INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 1, 1, 'In the name of Allah, the Entirely Merciful, the Especially Merciful.'),
  ('en.sahih', 1, 2, '[All] praise is [due] to Allah, Lord of the worlds -'),
  ('en.sahih', 1, 3, 'The Entirely Merciful, the Especially Merciful,'),
  ('en.sahih', 1, 4, 'Sovereign of the Day of Recompense.'),
  ('en.sahih', 1, 5, 'It is You we worship and You we ask for help.'),
  ('en.sahih', 1, 6, 'Guide us to the straight path -'),
  ('en.sahih', 1, 7, 'The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 1, 1, 'শুরু করছি আল্লাহর নামে যিনি পরম করুণাময়, অতি দয়ালু।'),
  ('bn.bengali', 1, 2, 'যাবতীয় প্রশংসা আল্লাহ তাআলার যিনি সকল সৃষ্টি জগতের পালনকর্তা।'),
  ('bn.bengali', 1, 3, 'যিনি নিতান্ত মেহেরবান ও দয়ালু।'),
  ('bn.bengali', 1, 4, 'যিনি বিচার দিনের মালিক।'),
  ('bn.bengali', 1, 5, 'আমরা একমাত্র তোমারই ইবাদত করি এবং শুধুমাত্র তোমারই সাহায্য প্রার্থনা করি।'),
  ('bn.bengali', 1, 6, 'আমাদেরকে সরল পথ দেখাও,'),
  ('bn.bengali', 1, 7, 'সে সমস্ত লোকের পথ, যাদেরকে তুমি নেয়ামত দান করেছ। তাদের পথ নয়, যাদের প্রতি তোমার গজব নাযিল হয়েছে এবং যারা পথভ্রষ্ট হয়েছে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 1, 1, 'In the name of Allah, the Beneficent, the Merciful.'),
  ('en.pickthall', 1, 2, 'Praise be to Allah, Lord of the Worlds,'),
  ('en.pickthall', 1, 3, 'The Beneficent, the Merciful.'),
  ('en.pickthall', 1, 4, 'Master of the Day of Judgment,'),
  ('en.pickthall', 1, 5, 'Thee (alone) we worship; Thee (alone) we ask for help.'),
  ('en.pickthall', 1, 6, 'Show us the straight path,'),
  ('en.pickthall', 1, 7, 'The path of those whom Thou hast favoured; Not the (path) of those who earn Thine anger nor of those who go astray.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 1, 1, 'In the name of Allah, Most Gracious, Most Merciful.'),
  ('en.yusufali', 1, 2, 'Praise be to Allah, the Cherisher and Sustainer of the worlds;'),
  ('en.yusufali', 1, 3, 'Most Gracious, Most Merciful;'),
  ('en.yusufali', 1, 4, 'Master of the Day of Judgment.'),
  ('en.yusufali', 1, 5, 'Thee do we worship, and Thine aid we seek.'),
  ('en.yusufali', 1, 6, 'Show us the straight way,'),
  ('en.yusufali', 1, 7, 'The way of those on whom Thou hast bestowed Thy Grace, those whose (portion) is not wrath, and who go not astray.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 1, 1, 'Bismillaahir Rahmaanir Raheem'),
  ('en.transliteration', 1, 2, 'Alhamdu lillaahi Rabbil \'aalameen'),
  ('en.transliteration', 1, 3, 'Ar-Rahmaanir-Raheem'),
  ('en.transliteration', 1, 4, 'Maaliki Yawmid-Deen'),
  ('en.transliteration', 1, 5, 'Iyyaaka na\'budu wa lyyaaka nasta\'een'),
  ('en.transliteration', 1, 6, 'Ihdinas-Siraatal-Mustaqeem'),
  ('en.transliteration', 1, 7, 'Siraatal-lazeena an\'amta \'alaihim ghayril-maghdoobi \'alaihim wa lad-daaalleen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 1, 1, 'شروع الله کا نام لے کر جو بڑا مہربان نہایت رحم والا ہے'),
  ('ur.ahmedali', 1, 2, 'سب تعریفیں الله کے لیے ہیں جو سب جہانوں کا پالنے والا ہے'),
  ('ur.ahmedali', 1, 3, 'بڑا مہربان نہایت رحم والا'),
  ('ur.ahmedali', 1, 4, 'جزا کے دن کا مالک'),
  ('ur.ahmedali', 1, 5, 'ہم تیری ہی عبادت کرتے ہیں اور تجھ ہی سے مدد مانگتے ہیں'),
  ('ur.ahmedali', 1, 6, 'ہمیں سیدھا راستہ دکھا'),
  ('ur.ahmedali', 1, 7, 'ان لوگوں کا راستہ جن پر تو نے انعام کیا نہ جن پر تیرا غضب نازل ہوا اور نہ وہ گمراہ ہوئے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 1, 1, 'Rahman ve Rahim olan Allah\'ın adıyla:'),
  ('tr.diyanet', 1, 2, 'Hamd, Alemlerin Rabbi Allah\'a mahsustur.'),
  ('tr.diyanet', 1, 3, 'O Rahman ve Rahim\'dir,'),
  ('tr.diyanet', 1, 4, 'Din Gününün sahibidir.'),
  ('tr.diyanet', 1, 5, 'Ancak Sana kulluk eder ve yalnız Senden yardım dileriz.'),
  ('tr.diyanet', 1, 6, 'Bizi doğru yola eriştir.'),
  ('tr.diyanet', 1, 7, 'Nimete erdirdiğin kimselerin yoluna; gazaba uğrayanların, ya da sapıtanların yoluna değil.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 1, 1, 'Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.'),
  ('id.indonesian', 1, 2, 'Segala puji bagi Allah, Tuhan semesta alam.'),
  ('id.indonesian', 1, 3, 'Maha Pemurah lagi Maha Penyayang.'),
  ('id.indonesian', 1, 4, 'Yang menguasai di Hari Pembalasan.'),
  ('id.indonesian', 1, 5, 'Hanya Engkaulah yang kami sembah, dan hanya kepada Engkaulah kami meminta pertolongan.'),
  ('id.indonesian', 1, 6, 'Tunjukilah kami jalan yang lurus,'),
  ('id.indonesian', 1, 7, '(yaitu) Jalan orang-orang yang telah Engkau beri nikmat kepada mereka; bukan (jalan) mereka yang dimurkai dan bukan (pula jalan) mereka yang sesat.')
