  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (1, 1, 1, '﻿بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 1, 1, 1, 0),
  (1, 2, 2, 'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 1, 1, 1, 0),
  (1, 3, 3, 'ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 1, 1, 1, 0),
  (1, 4, 4, 'مَٰلِكِ يَوْمِ ٱلدِّينِ', 1, 1, 1, 0),
  (1, 5, 5, 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 1, 1, 1, 0),
  (1, 6, 6, 'ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 1, 1, 1, 0),
  (1, 7, 7, 'صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ', 1, 1, 1, 0),
  (2, 1, 8, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 2, 1, 1, 0),
  (2, 2, 9, 'ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًۭى لِّلْمُتَّقِينَ', 2, 1, 1, 0),
  (2, 3, 10, 'ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 2, 1, 1, 0),
  (2, 4, 11, 'وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْءَاخِرَةِ هُمْ يُوقِنُونَ', 2, 1, 1, 0),
  (2, 5, 12, 'أُو۟لَٰٓئِكَ عَلَىٰ هُدًۭى مِّن رَّبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 2, 1, 1, 0),
  (2, 6, 13, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ', 3, 1, 1, 0),
  (2, 7, 14, 'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌۭ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌۭ', 3, 1, 1, 0),
  (2, 8, 15, 'وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْءَاخِرِ وَمَا هُم بِمُؤْمِنِينَ', 3, 1, 1, 0),
  (2, 9, 16, 'يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 3, 1, 1, 0),
  (2, 10, 17, 'فِى قُلُوبِهِم مَّرَضٌۭ فَزَادَهُمُ ٱللَّهُ مَرَضًۭا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ', 3, 1, 1, 0),
  (2, 11, 18, 'وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ', 3, 1, 1, 0),
  (2, 12, 19, 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ', 3, 1, 1, 0),
  (2, 13, 20, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ ۗ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ', 3, 1, 1, 0),
  (2, 14, 21, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ', 3, 1, 1, 0),
  (2, 15, 22, 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 3, 1, 1, 0),
  (2, 16, 23, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ', 3, 1, 1, 0),
  (2, 17, 24, 'مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًۭا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَٰتٍۢ لَّا يُبْصِرُونَ', 4, 1, 1, 0),
  (2, 18, 25, 'صُمٌّۢ بُكْمٌ عُمْىٌۭ فَهُمْ لَا يَرْجِعُونَ', 4, 1, 1, 0),
  (2, 19, 26, 'أَوْ كَصَيِّبٍۢ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٌۭ وَرَعْدٌۭ وَبَرْقٌۭ يَجْعَلُونَ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ ۚ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَٰفِرِينَ', 4, 1, 1, 0),
  (2, 20, 27, 'يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْ ۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ ۚ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَٰرِهِمْ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 4, 1, 1, 0),
  (2, 21, 28, 'يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 4, 1, 1, 0),
  (2, 22, 29, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًۭا وَٱلسَّمَآءَ بِنَآءًۭ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًۭا لَّكُمْ ۖ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًۭا وَأَنتُمْ تَعْلَمُونَ', 4, 1, 1, 0),
  (2, 23, 30, 'وَإِن كُنتُمْ فِى رَيْبٍۢ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍۢ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 4, 1, 1, 0),
  (2, 24, 31, 'فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَٰفِرِينَ', 4, 1, 1, 0),
  (2, 25, 32, 'وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍۢ رِّزْقًۭا ۙ قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًۭا ۖ وَلَهُمْ فِيهَآ أَزْوَٰجٌۭ مُّطَهَّرَةٌۭ ۖ وَهُمْ فِيهَا خَٰلِدُونَ', 5, 1, 1, 0),
  (2, 26, 33, '۞ إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًۭا مَّا بَعُوضَةًۭ فَمَا فَوْقَهَا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًۭا ۘ يُضِلُّ بِهِۦ كَثِيرًۭا وَيَهْدِى بِهِۦ كَثِيرًۭا ۚ وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ', 5, 1, 2, 0),
  (2, 27, 34, 'ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 5, 1, 2, 0),
  (2, 28, 35, 'كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًۭا فَأَحْيَٰكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 5, 1, 2, 0),
  (2, 29, 36, 'هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًۭا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍۢ ۚ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 5, 1, 2, 0),
  (2, 30, 37, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', 6, 1, 2, 0),
  (2, 31, 38, 'وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ', 6, 1, 2, 0),
  (2, 32, 39, 'قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ ۖ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 6, 1, 2, 0),
  (2, 33, 40, 'قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ ۖ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ', 6, 1, 2, 0),
  (2, 34, 41, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 6, 1, 2, 0),
  (2, 35, 42, 'وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', 6, 1, 2, 0),
  (2, 36, 43, 'فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۭ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّۭ وَمَتَٰعٌ إِلَىٰ حِينٍۢ', 6, 1, 2, 0),
  (2, 37, 44, 'فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍۢ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 6, 1, 2, 0),
  (2, 38, 45, 'قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًۭا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًۭى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 7, 1, 2, 0),
  (2, 39, 46, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 7, 1, 2, 0),
  (2, 40, 47, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ', 7, 1, 2, 0),
  (2, 41, 48, 'وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًۭا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًۭا قَلِيلًۭا وَإِيَّٰىَ فَٱتَّقُونِ', 7, 1, 2, 0),
  (2, 42, 49, 'وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 7, 1, 2, 0),
  (2, 43, 50, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ', 7, 1, 2, 0),
  (2, 44, 51, '۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ ۚ أَفَلَا تَعْقِلُونَ', 7, 1, 3, 0),
  (2, 45, 52, 'وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَٰشِعِينَ', 7, 1, 3, 0),
  (2, 46, 53, 'ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ', 7, 1, 3, 0),
  (2, 47, 54, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 7, 1, 3, 0),
  (2, 48, 55, 'وَٱتَّقُوا۟ يَوْمًۭا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍۢ شَيْـًۭٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌۭ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌۭ وَلَا هُمْ يُنصَرُونَ', 7, 1, 3, 0),
  (2, 49, 56, 'وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌۭ مِّن رَّبِّكُمْ عَظِيمٌۭ', 8, 1, 3, 0),
  (2, 50, 57, 'وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ', 8, 1, 3, 0),
  (2, 51, 58, 'وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةًۭ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 8, 1, 3, 0),
  (2, 52, 59, 'ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ', 8, 1, 3, 0),
  (2, 53, 60, 'وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ', 8, 1, 3, 0),
  (2, 54, 61, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 8, 1, 3, 0),
  (2, 55, 62, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةًۭ فَأَخَذَتْكُمُ ٱلصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ', 8, 1, 3, 0),
  (2, 56, 63, 'ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 8, 1, 3, 0),
  (2, 57, 64, 'وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ ۖ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 8, 1, 3, 0),
  (2, 58, 65, 'وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًۭا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا وَقُولُوا۟ حِطَّةٌۭ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ ۚ وَسَنَزِيدُ ٱلْمُحْسِنِينَ', 9, 1, 3, 0),
  (2, 59, 66, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًۭا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ', 9, 1, 3, 0),
  (2, 60, 67, '۞ وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًۭا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍۢ مَّشْرَبَهُمْ ۖ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 9, 1, 4, 0),
  (2, 61, 68, 'وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍۢ وَٰحِدٍۢ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا ۖ قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ۚ ٱهْبِطُوا۟ مِصْرًۭا فَإِنَّ لَكُم مَّا سَأَلْتُمْ ۗ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍۢ مِّنَ ٱللَّهِ ۗ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّۦنَ بِغَيْرِ ٱلْحَقِّ ۗ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 9, 1, 4, 0),
  (2, 62, 69, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَعَمِلَ صَٰلِحًۭا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 10, 1, 4, 0),
  (2, 63, 70, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍۢ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 10, 1, 4, 0),
  (2, 64, 71, 'ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ', 10, 1, 4, 0),
  (2, 65, 72, 'وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 10, 1, 4, 0),
  (2, 66, 73, 'فَجَعَلْنَٰهَا نَكَٰلًۭا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ', 10, 1, 4, 0),
  (2, 67, 74, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةًۭ ۖ قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًۭا ۖ قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَٰهِلِينَ', 10, 1, 4, 0),
  (2, 68, 75, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌۭ لَّا فَارِضٌۭ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ ۖ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ', 10, 1, 4, 0),
  (2, 69, 76, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا ۚ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌۭ صَفْرَآءُ فَاقِعٌۭ لَّوْنُهَا تَسُرُّ ٱلنَّٰظِرِينَ', 10, 1, 4, 0),
  (2, 70, 77, 'قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ', 11, 1, 4, 0),
  (2, 71, 78, 'قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌۭ لَّا ذَلُولٌۭ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌۭ لَّا شِيَةَ فِيهَا ۚ قَالُوا۟ ٱلْـَٰٔنَ جِئْتَ بِٱلْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ', 11, 1, 4, 0),
  (2, 72, 79, 'وَإِذْ قَتَلْتُمْ نَفْسًۭا فَٱدَّٰرَْٰٔتُمْ فِيهَا ۖ وَٱللَّهُ مُخْرِجٌۭ مَّا كُنتُمْ تَكْتُمُونَ', 11, 1, 4, 0),
  (2, 73, 80, 'فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 11, 1, 4, 0),
  (2, 74, 81, 'ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةًۭ ۚ وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 11, 1, 4, 0),
  (2, 75, 82, '۞ أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌۭ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ', 11, 1, 5, 0),
  (2, 76, 83, 'وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍۢ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ', 11, 1, 5, 0),
  (2, 77, 84, 'أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ', 12, 1, 5, 0),
  (2, 78, 85, 'وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ', 12, 1, 5, 0),
  (2, 79, 86, 'فَوَيْلٌۭ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا ۖ فَوَيْلٌۭ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌۭ لَّهُم مِّمَّا يَكْسِبُونَ', 12, 1, 5, 0),
  (2, 80, 87, 'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًۭا مَّعْدُودَةًۭ ۚ قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًۭا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ ۖ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 12, 1, 5, 0),
  (2, 81, 88, 'بَلَىٰ مَن كَسَبَ سَيِّئَةًۭ وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 12, 1, 5, 0),
  (2, 82, 89, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 12, 1, 5, 0),
  (2, 83, 90, 'وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًۭا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًۭا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًۭا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ', 12, 1, 5, 0),
  (2, 84, 91, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ', 13, 1, 5, 0),
  (2, 85, 92, 'ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًۭا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍۢ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 13, 1, 5, 0),
  (2, 86, 93, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْءَاخِرَةِ ۖ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ', 13, 1, 5, 0),
  (2, 87, 94, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ ۖ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ ۗ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًۭا كَذَّبْتُمْ وَفَرِيقًۭا تَقْتُلُونَ', 13, 1, 5, 0),
  (2, 88, 95, 'وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ ۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًۭا مَّا يُؤْمِنُونَ', 13, 1, 5, 0),
  (2, 89, 96, 'وَلَمَّا جَآءَهُمْ كِتَٰبٌۭ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌۭ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ ۚ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَٰفِرِينَ', 14, 1, 5, 0),
  (2, 90, 97, 'بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍۢ ۚ وَلِلْكَٰفِرِينَ عَذَابٌۭ مُّهِينٌۭ', 14, 1, 5, 0),
  (2, 91, 98, 'وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًۭا لِّمَا مَعَهُمْ ۗ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ', 14, 1, 5, 0),
  (2, 92, 99, '۞ وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ', 14, 1, 6, 0),
  (2, 93, 100, 'وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍۢ وَٱسْمَعُوا۟ ۖ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ', 14, 1, 6, 0),
  (2, 94, 101, 'قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْءَاخِرَةُ عِندَ ٱللَّهِ خَالِصَةًۭ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 15, 1, 6, 0),
  (2, 95, 102, 'وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 15, 1, 6, 0),
  (2, 96, 103, 'وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍۢ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ ۚ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍۢ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 15, 1, 6, 0),
  (2, 97, 104, 'قُلْ مَن كَانَ عَدُوًّۭا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ وَهُدًۭى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 15, 1, 6, 0),
  (2, 98, 105, 'مَن كَانَ عَدُوًّۭا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّۭ لِّلْكَٰفِرِينَ', 15, 1, 6, 0),
  (2, 99, 106, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَٰتٍۭ بَيِّنَٰتٍۢ ۖ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَٰسِقُونَ', 15, 1, 6, 0),
  (2, 100, 107, 'أَوَكُلَّمَا عَٰهَدُوا۟ عَهْدًۭا نَّبَذَهُۥ فَرِيقٌۭ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ', 15, 1, 6, 0),
  (2, 101, 108, 'وَلَمَّا جَآءَهُمْ رَسُولٌۭ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌۭ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌۭ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ', 15, 1, 6, 0),
  (2, 102, 109, 'وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ ۖ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌۭ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ ۚ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْءَاخِرَةِ مِنْ خَلَٰقٍۢ ۚ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 16, 1, 6, 0),
  (2, 103, 110, 'وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌۭ مِّنْ عِندِ ٱللَّهِ خَيْرٌۭ ۖ لَّوْ كَانُوا۟ يَعْلَمُونَ', 16, 1, 6, 0),
  (2, 104, 111, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ ۗ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌۭ', 16, 1, 6, 0),
  (2, 105, 112, 'مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍۢ مِّن رَّبِّكُمْ ۗ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 16, 1, 6, 0),
  (2, 106, 113, '۞ مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍۢ مِّنْهَآ أَوْ مِثْلِهَآ ۗ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 17, 1, 7, 0),
  (2, 107, 114, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍ', 17, 1, 7, 0),
  (2, 108, 115, 'أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ ۗ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 17, 1, 7, 0),
  (2, 109, 116, 'وَدَّ كَثِيرٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّارًا حَسَدًۭا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ ۖ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 17, 1, 7, 0),
  (2, 110, 117, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍۢ تَجِدُوهُ عِندَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 17, 1, 7, 0),
  (2, 111, 118, 'وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 17, 1, 7, 0),
  (2, 112, 119, 'بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌۭ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 17, 1, 7, 0),
  (2, 113, 120, 'وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَىْءٍۢ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍۢ وَهُمْ يَتْلُونَ ٱلْكِتَٰبَ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 18, 1, 7, 0),
  (2, 114, 121, 'وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ ۚ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌۭ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌۭ', 18, 1, 7, 0),
  (2, 115, 122, 'وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌۭ', 18, 1, 7, 0),
  (2, 116, 123, 'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًۭا ۗ سُبْحَٰنَهُۥ ۖ بَل لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ كُلٌّۭ لَّهُۥ قَٰنِتُونَ', 18, 1, 7, 0),
  (2, 117, 124, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 18, 1, 7, 0),
  (2, 118, 125, 'وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌۭ ۗ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَٰبَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا ٱلْءَايَٰتِ لِقَوْمٍۢ يُوقِنُونَ', 18, 1, 7, 0),
  (2, 119, 126, 'إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًۭا وَنَذِيرًۭا ۖ وَلَا تُسْـَٔلُ عَنْ أَصْحَٰبِ ٱلْجَحِيمِ', 18, 1, 7, 0),
  (2, 120, 127, 'وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۗ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ ۙ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍ', 19, 1, 7, 0),
  (2, 121, 128, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۗ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 19, 1, 7, 0),
  (2, 122, 129, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ', 19, 1, 7, 0),
  (2, 123, 130, 'وَٱتَّقُوا۟ يَوْمًۭا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍۢ شَيْـًۭٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌۭ وَلَا تَنفَعُهَا شَفَٰعَةٌۭ وَلَا هُمْ يُنصَرُونَ', 19, 1, 7, 0),
  (2, 124, 131, '۞ وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِۦمَ رَبُّهُۥ بِكَلِمَٰتٍۢ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًۭا ۖ قَالَ وَمِن ذُرِّيَّتِى ۖ قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ', 19, 1, 8, 0),
  (2, 125, 132, 'وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةًۭ لِّلنَّاسِ وَأَمْنًۭا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِۦمَ مُصَلًّۭى ۖ وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 19, 1, 8, 0),
  (2, 126, 133, 'وَإِذْ قَالَ إِبْرَٰهِۦمُ رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًۭا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًۭا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ ۖ وَبِئْسَ ٱلْمَصِيرُ', 19, 1, 8, 0),
  (2, 127, 134, 'وَإِذْ يَرْفَعُ إِبْرَٰهِۦمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 20, 1, 8, 0),
  (2, 128, 135, 'رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةًۭ مُّسْلِمَةًۭ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ ۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 20, 1, 8, 0),
  (2, 129, 136, 'رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 20, 1, 8, 0),
  (2, 130, 137, 'وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِۦمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ ۚ وَلَقَدِ ٱصْطَفَيْنَٰهُ فِى ٱلدُّنْيَا ۖ وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 20, 1, 8, 0),
  (2, 131, 138, 'إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَٰلَمِينَ', 20, 1, 8, 0),
  (2, 132, 139, 'وَوَصَّىٰ بِهَآ إِبْرَٰهِۦمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 20, 1, 8, 0),
  (2, 133, 140, 'أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهًۭا وَٰحِدًۭا وَنَحْنُ لَهُۥ مُسْلِمُونَ', 20, 1, 8, 0),
  (2, 134, 141, 'تِلْكَ أُمَّةٌۭ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 20, 1, 8, 0),
  (2, 135, 142, 'وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ ۗ قُلْ بَلْ مِلَّةَ إِبْرَٰهِۦمَ حَنِيفًۭا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 21, 1, 8, 0),
  (2, 136, 143, 'قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 21, 1, 8, 0),
  (2, 137, 144, 'فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍۢ ۖ فَسَيَكْفِيكَهُمُ ٱللَّهُ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 21, 1, 8, 0),
  (2, 138, 145, 'صِبْغَةَ ٱللَّهِ ۖ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةًۭ ۖ وَنَحْنُ لَهُۥ عَٰبِدُونَ', 21, 1, 8, 0),
  (2, 139, 146, 'قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ', 21, 1, 8, 0),
  (2, 140, 147, 'أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِۦمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَٰرَىٰ ۗ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 21, 1, 8, 0),
  (2, 141, 148, 'تِلْكَ أُمَّةٌۭ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ', 21, 1, 8, 0),
  (2, 142, 149, '۞ سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا ۚ قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ ۚ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 22, 2, 9, 0),
  (2, 143, 150, 'وَكَذَٰلِكَ جَعَلْنَٰكُمْ أُمَّةًۭ وَسَطًۭا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًۭا ۗ وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ ۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمْ ۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌۭ رَّحِيمٌۭ', 22, 2, 9, 0),
  (2, 144, 151, 'قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةًۭ تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 22, 2, 9, 0),
  (2, 145, 152, 'وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ بِكُلِّ ءَايَةٍۢ مَّا تَبِعُوا۟ قِبْلَتَكَ ۚ وَمَآ أَنتَ بِتَابِعٍۢ قِبْلَتَهُمْ ۚ وَمَا بَعْضُهُم بِتَابِعٍۢ قِبْلَةَ بَعْضٍۢ ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ ۙ إِنَّكَ إِذًۭا لَّمِنَ ٱلظَّٰلِمِينَ', 22, 2, 9, 0),
  (2, 146, 153, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ ۖ وَإِنَّ فَرِيقًۭا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ', 23, 2, 9, 0),
  (2, 147, 154, 'ٱلْحَقُّ مِن رَّبِّكَ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 23, 2, 9, 0),
  (2, 148, 155, 'وَلِكُلٍّۢ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 23, 2, 9, 0),
  (2, 149, 156, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 23, 2, 9, 0),
  (2, 150, 157, 'وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ', 23, 2, 9, 0),
  (2, 151, 158, 'كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًۭا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 23, 2, 9, 0),
  (2, 152, 159, 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ', 23, 2, 9, 0),
  (2, 153, 160, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 23, 2, 9, 0),
  (2, 154, 161, 'وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ ۚ بَلْ أَحْيَآءٌۭ وَلَٰكِن لَّا تَشْعُرُونَ', 24, 2, 9, 0),
  (2, 155, 162, 'وَلَنَبْلُوَنَّكُم بِشَىْءٍۢ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍۢ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ ۗ وَبَشِّرِ ٱلصَّٰبِرِينَ', 24, 2, 9, 0),
  (2, 156, 163, 'ٱلَّذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۭ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ', 24, 2, 9, 0),
  (2, 157, 164, 'أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌۭ مِّن رَّبِّهِمْ وَرَحْمَةٌۭ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ', 24, 2, 9, 0),
  (2, 158, 165, '۞ إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ ۖ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا ۚ وَمَن تَطَوَّعَ خَيْرًۭا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ', 24, 2, 10, 0),
  (2, 159, 166, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ ۙ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ', 24, 2, 10, 0),
  (2, 160, 167, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ', 24, 2, 10, 0),
  (2, 161, 168, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 24, 2, 10, 0),
  (2, 162, 169, 'خَٰلِدِينَ فِيهَا ۖ لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 24, 2, 10, 0),
  (2, 163, 170, 'وَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 24, 2, 10, 0),
  (2, 164, 171, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍۢ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍۢ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ', 25, 2, 10, 0),
  (2, 165, 172, 'وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًۭا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ ۖ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّۭا لِّلَّهِ ۗ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًۭا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ', 25, 2, 10, 0),
  (2, 166, 173, 'إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ', 25, 2, 10, 0),
  (2, 167, 174, 'وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةًۭ فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ', 25, 2, 10, 0),
  (2, 168, 175, 'يَٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَٰلًۭا طَيِّبًۭا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌ', 25, 2, 10, 0),
  (2, 169, 176, 'إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 25, 2, 10, 0),
  (2, 170, 177, 'وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ ۗ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًۭٔا وَلَا يَهْتَدُونَ', 26, 2, 10, 0),
  (2, 171, 178, 'وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءًۭ وَنِدَآءًۭ ۚ صُمٌّۢ بُكْمٌ عُمْىٌۭ فَهُمْ لَا يَعْقِلُونَ', 26, 2, 10, 0),
  (2, 172, 179, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 26, 2, 10, 0),
  (2, 173, 180, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 26, 2, 10, 0),
  (2, 174, 181, 'إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًۭا قَلِيلًا ۙ أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 26, 2, 10, 0),
  (2, 175, 182, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ ۚ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ', 26, 2, 10, 0),
  (2, 176, 183, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ ۗ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍۢ', 26, 2, 10, 0),
  (2, 177, 184, '۞ لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَٱلْمَلَٰٓئِكَةِ وَٱلْكِتَٰبِ وَٱلنَّبِيِّۦنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَٰهَدُوا۟ ۖ وَٱلصَّٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ ۗ أُو۟لَٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 27, 2, 11, 0),
  (2, 178, 185, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ۖ ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ ۚ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌۭ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَٰنٍۢ ۗ ذَٰلِكَ تَخْفِيفٌۭ مِّن رَّبِّكُمْ وَرَحْمَةٌۭ ۗ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌۭ', 27, 2, 11, 0),
  (2, 179, 186, 'وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌۭ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ', 27, 2, 11, 0),
  (2, 180, 187, 'كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ', 27, 2, 11, 0),
  (2, 181, 188, 'فَمَنۢ بَدَّلَهُۥ بَعْدَمَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 27, 2, 11, 0),
  (2, 182, 189, 'فَمَنْ خَافَ مِن مُّوصٍۢ جَنَفًا أَوْ إِثْمًۭا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 28, 2, 11, 0),
  (2, 183, 190, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 28, 2, 11, 0),
  (2, 184, 191, 'أَيَّامًۭا مَّعْدُودَٰتٍۢ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌۭ طَعَامُ مِسْكِينٍۢ ۖ فَمَن تَطَوَّعَ خَيْرًۭا فَهُوَ خَيْرٌۭ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌۭ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ', 28, 2, 11, 0),
  (2, 185, 192, 'شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًۭى لِّلنَّاسِ وَبَيِّنَٰتٍۢ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍۢ فَعِدَّةٌۭ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ', 28, 2, 11, 0),
  (2, 186, 193, 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ', 28, 2, 11, 0),
  (2, 187, 194, 'أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ ۚ هُنَّ لِبَاسٌۭ لَّكُمْ وَأَنتُمْ لِبَاسٌۭ لَّهُنَّ ۗ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ ۚ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ۖ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ ۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ', 29, 2, 11, 0),
  (2, 188, 195, 'وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًۭا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ', 29, 2, 11, 0),
  (2, 189, 196, '۞ يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ ۖ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ ۗ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ ۗ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 29, 2, 12, 0),
  (2, 190, 197, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 29, 2, 12, 0),
  (2, 191, 198, 'وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ ۚ وَلَا تُقَٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ ۖ فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 30, 2, 12, 0),
  (2, 192, 199, 'فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 30, 2, 12, 0),
  (2, 193, 200, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌۭ وَيَكُونَ ٱلدِّينُ لِلَّهِ ۖ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ', 30, 2, 12, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 2, 1, 'Alif, Lam, Meem.'),
  ('en.sahih', 2, 2, 'This is the Book about which there is no doubt, a guidance for those conscious of Allah -'),
  ('en.sahih', 2, 3, 'Who believe in the unseen, establish prayer, and spend out of what We have provided for them,'),
  ('en.sahih', 2, 4, 'And who believe in what has been revealed to you, [O Muhammad], and what was revealed before you, and of the Hereafter they are certain [in faith].'),
  ('en.sahih', 2, 5, 'Those are upon [right] guidance from their Lord, and it is those who are the successful.'),
  ('en.sahih', 2, 6, 'Indeed, those who disbelieve - it is all the same for them whether you warn them or do not warn them - they will not believe.'),
  ('en.sahih', 2, 7, 'Allah has set a seal upon their hearts and upon their hearing, and over their vision is a veil. And for them is a great punishment.'),
  ('en.sahih', 2, 8, 'And of the people are some who say, "We believe in Allah and the Last Day," but they are not believers.'),
  ('en.sahih', 2, 9, 'They [think to] deceive Allah and those who believe, but they deceive not except themselves and perceive [it] not.'),
  ('en.sahih', 2, 10, 'In their hearts is disease, so Allah has increased their disease; and for them is a painful punishment because they [habitually] used to lie.'),
  ('en.sahih', 2, 11, 'And when it is said to them, "Do not cause corruption on the earth," they say, "We are but reformers."'),
  ('en.sahih', 2, 12, 'Unquestionably, it is they who are the corrupters, but they perceive [it] not.'),
  ('en.sahih', 2, 13, 'And when it is said to them, "Believe as the people have believed," they say, "Should we believe as the foolish have believed?" Unquestionably, it is they who are the foolish, but they know [it] not.'),
  ('en.sahih', 2, 14, 'And when they meet those who believe, they say, "We believe"; but when they are alone with their evil ones, they say, "Indeed, we are with you; we were only mockers."'),
  ('en.sahih', 2, 15, '[But] Allah mocks them and prolongs them in their transgression [while] they wander blindly.'),
  ('en.sahih', 2, 16, 'Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided.'),
  ('en.sahih', 2, 17, 'Their example is that of one who kindled a fire, but when it illuminated what was around him, Allah took away their light and left them in darkness [so] they could not see.'),
  ('en.sahih', 2, 18, 'Deaf, dumb and blind - so they will not return [to the right path].'),
  ('en.sahih', 2, 19, 'Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allah is encompassing of the disbelievers.'),
  ('en.sahih', 2, 20, 'The lightning almost snatches away their sight. Every time it lights [the way] for them, they walk therein; but when darkness comes over them, they stand [still]. And if Allah had willed, He could have taken away their hearing and their sight. Indeed, Allah is over all things competent.'),
  ('en.sahih', 2, 21, 'O mankind, worship your Lord, who created you and those before you, that you may become righteous -'),
  ('en.sahih', 2, 22, '[He] who made for you the earth a bed [spread out] and the sky a ceiling and sent down from the sky, rain and brought forth thereby fruits as provision for you. So do not attribute to Allah equals while you know [that there is nothing similar to Him].'),
  ('en.sahih', 2, 23, 'And if you are in doubt about what We have sent down upon Our Servant [Muhammad], then produce a surah the like thereof and call upon your witnesses other than Allah, if you should be truthful.'),
  ('en.sahih', 2, 24, 'But if you do not - and you will never be able to - then fear the Fire, whose fuel is men and stones, prepared for the disbelievers.'),
  ('en.sahih', 2, 25, 'And give good tidings to those who believe and do righteous deeds that they will have gardens [in Paradise] beneath which rivers flow. Whenever they are provided with a provision of fruit therefrom, they will say, "This is what we were provided with before." And it is given to them in likeness. And they will have therein purified spouses, and they will abide therein eternally.'),
  ('en.sahih', 2, 26, 'Indeed, Allah is not timid to present an example - that of a mosquito or what is smaller than it. And those who have believed know that it is the truth from their Lord. But as for those who disbelieve, they say, "What did Allah intend by this as an example?" He misleads many thereby and guides many thereby. And He misleads not except the defiantly disobedient,'),
  ('en.sahih', 2, 27, 'Who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and cause corruption on earth. It is those who are the losers.'),
  ('en.sahih', 2, 28, 'How can you disbelieve in Allah when you were lifeless and He brought you to life; then He will cause you to die, then He will bring you [back] to life, and then to Him you will be returned.'),
  ('en.sahih', 2, 29, 'It is He who created for you all of that which is on the earth. Then He directed Himself to the heaven, [His being above all creation], and made them seven heavens, and He is Knowing of all things.'),
  ('en.sahih', 2, 30, 'And [mention, O Muhammad], when your Lord said to the angels, "Indeed, I will make upon the earth a successive authority." They said, "Will You place upon it one who causes corruption therein and sheds blood, while we declare Your praise and sanctify You?" Allah said, "Indeed, I know that which you do not know."'),
  ('en.sahih', 2, 31, 'And He taught Adam the names - all of them. Then He showed them to the angels and said, "Inform Me of the names of these, if you are truthful."'),
  ('en.sahih', 2, 32, 'They said, "Exalted are You; we have no knowledge except what You have taught us. Indeed, it is You who is the Knowing, the Wise."'),
  ('en.sahih', 2, 33, 'He said, "O Adam, inform them of their names." And when he had informed them of their names, He said, "Did I not tell you that I know the unseen [aspects] of the heavens and the earth? And I know what you reveal and what you have concealed."'),
  ('en.sahih', 2, 34, 'And [mention] when We said to the angels, "Prostrate before Adam"; so they prostrated, except for Iblees. He refused and was arrogant and became of the disbelievers.'),
  ('en.sahih', 2, 35, 'And We said, "O Adam, dwell, you and your wife, in Paradise and eat therefrom in [ease and] abundance from wherever you will. But do not approach this tree, lest you be among the wrongdoers."'),
  ('en.sahih', 2, 36, 'But Satan caused them to slip out of it and removed them from that [condition] in which they had been. And We said, "Go down, [all of you], as enemies to one another, and you will have upon the earth a place of settlement and provision for a time."'),
  ('en.sahih', 2, 37, 'Then Adam received from his Lord [some] words, and He accepted his repentance. Indeed, it is He who is the Accepting of repentance, the Merciful.'),
  ('en.sahih', 2, 38, 'We said, "Go down from it, all of you. And when guidance comes to you from Me, whoever follows My guidance - there will be no fear concerning them, nor will they grieve.'),
  ('en.sahih', 2, 39, 'And those who disbelieve and deny Our signs - those will be companions of the Fire; they will abide therein eternally."'),
  ('en.sahih', 2, 40, 'O Children of Israel, remember My favor which I have bestowed upon you and fulfill My covenant [upon you] that I will fulfill your covenant [from Me], and be afraid of [only] Me.'),
  ('en.sahih', 2, 41, 'And believe in what I have sent down confirming that which is [already] with you, and be not the first to disbelieve in it. And do not exchange My signs for a small price, and fear [only] Me.'),
  ('en.sahih', 2, 42, 'And do not mix the truth with falsehood or conceal the truth while you know [it].'),
  ('en.sahih', 2, 43, 'And establish prayer and give zakah and bow with those who bow [in worship and obedience].'),
  ('en.sahih', 2, 44, 'Do you order righteousness of the people and forget yourselves while you recite the Scripture? Then will you not reason?'),
  ('en.sahih', 2, 45, 'And seek help through patience and prayer, and indeed, it is difficult except for the humbly submissive [to Allah]'),
  ('en.sahih', 2, 46, 'Who are certain that they will meet their Lord and that they will return to Him.'),
  ('en.sahih', 2, 47, 'O Children of Israel, remember My favor that I have bestowed upon you and that I preferred you over the worlds.'),
  ('en.sahih', 2, 48, 'And fear a Day when no soul will suffice for another soul at all, nor will intercession be accepted from it, nor will compensation be taken from it, nor will they be aided.'),
  ('en.sahih', 2, 49, 'And [recall] when We saved your forefathers from the people of Pharaoh, who afflicted you with the worst torment, slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.'),
  ('en.sahih', 2, 50, 'And [recall] when We parted the sea for you and saved you and drowned the people of Pharaoh while you were looking on.'),
  ('en.sahih', 2, 51, 'And [recall] when We made an appointment with Moses for forty nights. Then you took [for worship] the calf after him, while you were wrongdoers.'),
  ('en.sahih', 2, 52, 'Then We forgave you after that so perhaps you would be grateful.'),
  ('en.sahih', 2, 53, 'And [recall] when We gave Moses the Scripture and criterion that perhaps you would be guided.'),
  ('en.sahih', 2, 54, 'And [recall] when Moses said to his people, "O my people, indeed you have wronged yourselves by your taking of the calf [for worship]. So repent to your Creator and kill yourselves. That is best for [all of] you in the sight of your Creator." Then He accepted your repentance; indeed, He is the Accepting of repentance, the Merciful.'),
  ('en.sahih', 2, 55, 'And [recall] when you said, "O Moses, we will never believe you until we see Allah outright"; so the thunderbolt took you while you were looking on.'),
  ('en.sahih', 2, 56, 'Then We revived you after your death that perhaps you would be grateful.'),
  ('en.sahih', 2, 57, 'And We shaded you with clouds and sent down to you manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not - but they were [only] wronging themselves.'),
  ('en.sahih', 2, 58, 'And [recall] when We said, "Enter this city and eat from it wherever you will in [ease and] abundance, and enter the gate bowing humbly and say, \'Relieve us of our burdens.\' We will [then] forgive your sins for you, and We will increase the doers of good [in goodness and reward]."'),
  ('en.sahih', 2, 59, 'But those who wronged changed [those words] to a statement other than that which had been said to them, so We sent down upon those who wronged a punishment from the sky because they were defiantly disobeying.'),
  ('en.sahih', 2, 60, 'And [recall] when Moses prayed for water for his people, so We said, "Strike with your staff the stone." And there gushed forth from it twelve springs, and every people knew its watering place. "Eat and drink from the provision of Allah, and do not commit abuse on the earth, spreading corruption."'),
  ('en.sahih', 2, 61, 'And [recall] when you said, "O Moses, we can never endure one [kind of] food. So call upon your Lord to bring forth for us from the earth its green herbs and its cucumbers and its garlic and its lentils and its onions." [Moses] said, "Would you exchange what is better for what is less? Go into [any] settlement and indeed, you will have what you have asked." And they were covered with humiliation and poverty and returned with anger from Allah [upon them]. That was because they [repeatedly] disbelieved in the signs of Allah and killed the prophets without right. That was because they disobeyed and were [habitually] transgressing.'),
  ('en.sahih', 2, 62, 'Indeed, those who believed and those who were Jews or Christians or Sabeans [before Prophet Muhammad] - those [among them] who believed in Allah and the Last Day and did righteousness - will have their reward with their Lord, and no fear will there be concerning them, nor will they grieve.'),
  ('en.sahih', 2, 63, 'And [recall] when We took your covenant, [O Children of Israel, to abide by the Torah] and We raised over you the mount, [saying], "Take what We have given you with determination and remember what is in it that perhaps you may become righteous."'),
  ('en.sahih', 2, 64, 'Then you turned away after that. And if not for the favor of Allah upon you and His mercy, you would have been among the losers.'),
  ('en.sahih', 2, 65, 'And you had already known about those who transgressed among you concerning the sabbath, and We said to them, "Be apes, despised."'),
  ('en.sahih', 2, 66, 'And We made it a deterrent punishment for those who were present and those who succeeded [them] and a lesson for those who fear Allah.'),
  ('en.sahih', 2, 67, 'And [recall] when Moses said to his people, "Indeed, Allah commands you to slaughter a cow." They said, "Do you take us in ridicule?" He said, "I seek refuge in Allah from being among the ignorant."'),
  ('en.sahih', 2, 68, 'They said, "Call upon your Lord to make clear to us what it is." [Moses] said, "[Allah] says, \'It is a cow which is neither old nor virgin, but median between that,\' so do what you are commanded."'),
  ('en.sahih', 2, 69, 'They said, "Call upon your Lord to show us what is her color." He said, "He says, \'It is a yellow cow, bright in color - pleasing to the observers.\' "'),
  ('en.sahih', 2, 70, 'They said, "Call upon your Lord to make clear to us what it is. Indeed, [all] cows look alike to us. And indeed we, if Allah wills, will be guided."'),
  ('en.sahih', 2, 71, 'He said, "He says, \'It is a cow neither trained to plow the earth nor to irrigate the field, one free from fault with no spot upon her.\' " They said, "Now you have come with the truth." So they slaughtered her, but they could hardly do it.'),
  ('en.sahih', 2, 72, 'And [recall] when you slew a man and disputed over it, but Allah was to bring out that which you were concealing.'),
  ('en.sahih', 2, 73, 'So, We said, "Strike the slain man with part of it." Thus does Allah bring the dead to life, and He shows you His signs that you might reason.'),
  ('en.sahih', 2, 74, 'Then your hearts became hardened after that, being like stones or even harder. For indeed, there are stones from which rivers burst forth, and there are some of them that split open and water comes out, and there are some of them that fall down for fear of Allah. And Allah is not unaware of what you do.'),
  ('en.sahih', 2, 75, 'Do you covet [the hope, O believers], that they would believe for you while a party of them used to hear the words of Allah and then distort the Torah after they had understood it while they were knowing?'),
  ('en.sahih', 2, 76, 'And when they meet those who believe, they say, "We have believed"; but when they are alone with one another, they say, "Do you talk to them about what Allah has revealed to you so they can argue with you about it before your Lord?" Then will you not reason?'),
  ('en.sahih', 2, 77, 'But do they not know that Allah knows what they conceal and what they declare?'),
  ('en.sahih', 2, 78, 'And among them are unlettered ones who do not know the Scripture except in wishful thinking, but they are only assuming.'),
  ('en.sahih', 2, 79, 'So woe to those who write the "scripture" with their own hands, then say, "This is from Allah," in order to exchange it for a small price. Woe to them for what their hands have written and woe to them for what they earn.'),
  ('en.sahih', 2, 80, 'And they say, "Never will the Fire touch us, except for a few days." Say, "Have you taken a covenant with Allah? For Allah will never break His covenant. Or do you say about Allah that which you do not know?"'),
  ('en.sahih', 2, 81, 'Yes, whoever earns evil and his sin has encompassed him - those are the companions of the Fire; they will abide therein eternally.'),
  ('en.sahih', 2, 82, 'But they who believe and do righteous deeds - those are the companions of Paradise; they will abide therein eternally.'),
  ('en.sahih', 2, 83, 'And [recall] when We took the covenant from the Children of Israel, [enjoining upon them], "Do not worship except Allah; and to parents do good and to relatives, orphans, and the needy. And speak to people good [words] and establish prayer and give zakah." Then you turned away, except a few of you, and you were refusing.'),
  ('en.sahih', 2, 84, 'And [recall] when We took your covenant, [saying], "Do not shed each other\'s blood or evict one another from your homes." Then you acknowledged [this] while you were witnessing.'),
  ('en.sahih', 2, 85, 'Then, you are those [same ones who are] killing one another and evicting a party of your people from their homes, cooperating against them in sin and aggression. And if they come to you as captives, you ransom them, although their eviction was forbidden to you. So do you believe in part of the Scripture and disbelieve in part? Then what is the recompense for those who do that among you except disgrace in worldly life; and on the Day of Resurrection they will be sent back to the severest of punishment. And Allah is not unaware of what you do.'),
  ('en.sahih', 2, 86, 'Those are the ones who have bought the life of this world [in exchange] for the Hereafter, so the punishment will not be lightened for them, nor will they be aided.'),
  ('en.sahih', 2, 87, 'And We did certainly give Moses the Torah and followed up after him with messengers. And We gave Jesus, the son of Mary, clear proofs and supported him with the Pure Spirit. But is it [not] that every time a messenger came to you, [O Children of Israel], with what your souls did not desire, you were arrogant? And a party [of messengers] you denied and another party you killed.'),
  ('en.sahih', 2, 88, 'And they said, "Our hearts are wrapped." But, [in fact], Allah has cursed them for their disbelief, so little is it that they believe.'),
  ('en.sahih', 2, 89, 'And when there came to them a Book from Allah confirming that which was with them - although before they used to pray for victory against those who disbelieved - but [then] when there came to them that which they recognized, they disbelieved in it; so the curse of Allah will be upon the disbelievers.'),
  ('en.sahih', 2, 90, 'How wretched is that for which they sold themselves - that they would disbelieve in what Allah has revealed through [their] outrage that Allah would send down His favor upon whom He wills from among His servants. So they returned having [earned] wrath upon wrath. And for the disbelievers is a humiliating punishment.'),
  ('en.sahih', 2, 91, 'And when it is said to them, "Believe in what Allah has revealed," they say, "We believe [only] in what was revealed to us." And they disbelieve in what came after it, while it is the truth confirming that which is with them. Say, "Then why did you kill the prophets of Allah before, if you are [indeed] believers?"'),
  ('en.sahih', 2, 92, 'And Moses had certainly brought you clear proofs. Then you took the calf [in worship] after that, while you were wrongdoers.'),
  ('en.sahih', 2, 93, 'And [recall] when We took your covenant and raised over you the mount, [saying], "Take what We have given you with determination and listen." They said [instead], "We hear and disobey." And their hearts absorbed [the worship of] the calf because of their disbelief. Say, "How wretched is that which your faith enjoins upon you, if you should be believers."'),
  ('en.sahih', 2, 94, 'Say, [O Muhammad], "If the home of the Hereafter with Allah is for you alone and not the [other] people, then wish for death, if you should be truthful.'),
  ('en.sahih', 2, 95, 'But they will never wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.'),
  ('en.sahih', 2, 96, 'And you will surely find them the most greedy of people for life - [even] more than those who associate others with Allah. One of them wishes that he could be granted life a thousand years, but it would not remove him in the least from the [coming] punishment that he should be granted life. And Allah is Seeing of what they do.'),
  ('en.sahih', 2, 97, 'Say, "Whoever is an enemy to Gabriel - it is [none but] he who has brought the Qur\'an down upon your heart, [O Muhammad], by permission of Allah, confirming that which was before it and as guidance and good tidings for the believers."'),
  ('en.sahih', 2, 98, 'Whoever is an enemy to Allah and His angels and His messengers and Gabriel and Michael - then indeed, Allah is an enemy to the disbelievers.'),
  ('en.sahih', 2, 99, 'And We have certainly revealed to you verses [which are] clear proofs, and no one would deny them except the defiantly disobedient.'),
  ('en.sahih', 2, 100, 'Is it not [true] that every time they took a covenant a party of them threw it away? But, [in fact], most of them do not believe.'),
  ('en.sahih', 2, 101, 'And when a messenger from Allah came to them confirming that which was with them, a party of those who had been given the Scripture threw the Scripture of Allah behind their backs as if they did not know [what it contained].'),
  ('en.sahih', 2, 102, 'And they followed [instead] what the devils had recited during the reign of Solomon. It was not Solomon who disbelieved, but the devils disbelieved, teaching people magic and that which was revealed to the two angels at Babylon, Harut and Marut. But the two angels do not teach anyone unless they say, "We are a trial, so do not disbelieve [by practicing magic]." And [yet] they learn from them that by which they cause separation between a man and his wife. But they do not harm anyone through it except by permission of Allah. And the people learn what harms them and does not benefit them. But the Children of Israel certainly knew that whoever purchased the magic would not have in the Hereafter any share. And wretched is that for which they sold themselves, if they only knew.'),
  ('en.sahih', 2, 103, 'And if they had believed and feared Allah, then the reward from Allah would have been [far] better, if they only knew.'),
  ('en.sahih', 2, 104, 'O you who have believed, say not [to Allah \'s Messenger], "Ra\'ina" but say, "Unthurna" and listen. And for the disbelievers is a painful punishment.'),
  ('en.sahih', 2, 105, 'Neither those who disbelieve from the People of the Scripture nor the polytheists wish that any good should be sent down to you from your Lord. But Allah selects for His mercy whom He wills, and Allah is the possessor of great bounty.'),
  ('en.sahih', 2, 106, 'We do not abrogate a verse or cause it to be forgotten except that We bring forth [one] better than it or similar to it. Do you not know that Allah is over all things competent?'),
  ('en.sahih', 2, 107, 'Do you not know that to Allah belongs the dominion of the heavens and the earth and [that] you have not besides Allah any protector or any helper?'),
  ('en.sahih', 2, 108, 'Or do you intend to ask your Messenger as Moses was asked before? And whoever exchanges faith for disbelief has certainly strayed from the soundness of the way.'),
  ('en.sahih', 2, 109, 'Many of the People of the Scripture wish they could turn you back to disbelief after you have believed, out of envy from themselves [even] after the truth has become clear to them. So pardon and overlook until Allah delivers His command. Indeed, Allah is over all things competent.'),
  ('en.sahih', 2, 110, 'And establish prayer and give zakah, and whatever good you put forward for yourselves - you will find it with Allah. Indeed, Allah of what you do, is Seeing.'),
  ('en.sahih', 2, 111, 'And they say, "None will enter Paradise except one who is a Jew or a Christian." That is [merely] their wishful thinking, Say, "Produce your proof, if you should be truthful."'),
  ('en.sahih', 2, 112, 'Yes [on the contrary], whoever submits his face in Islam to Allah while being a doer of good will have his reward with his Lord. And no fear will there be concerning them, nor will they grieve.'),
  ('en.sahih', 2, 113, 'The Jews say "The Christians have nothing [true] to stand on," and the Christians say, "The Jews have nothing to stand on," although they [both] recite the Scripture. Thus the polytheists speak the same as their words. But Allah will judge between them on the Day of Resurrection concerning that over which they used to differ.'),
  ('en.sahih', 2, 114, 'And who are more unjust than those who prevent the name of Allah from being mentioned in His mosques and strive toward their destruction. It is not for them to enter them except in fear. For them in this world is disgrace, and they will have in the Hereafter a great punishment.'),
  ('en.sahih', 2, 115, 'And to Allah belongs the east and the west. So wherever you [might] turn, there is the Face of Allah. Indeed, Allah is all-Encompassing and Knowing.'),
  ('en.sahih', 2, 116, 'They say, "Allah has taken a son." Exalted is He! Rather, to Him belongs whatever is in the heavens and the earth. All are devoutly obedient to Him,'),
  ('en.sahih', 2, 117, 'Originator of the heavens and the earth. When He decrees a matter, He only says to it, "Be," and it is.'),
  ('en.sahih', 2, 118, 'Those who do not know say, "Why does Allah not speak to us or there come to us a sign?" Thus spoke those before them like their words. Their hearts resemble each other. We have shown clearly the signs to a people who are certain [in faith].'),
  ('en.sahih', 2, 119, 'Indeed, We have sent you, [O Muhammad], with the truth as a bringer of good tidings and a warner, and you will not be asked about the companions of Hellfire.'),
  ('en.sahih', 2, 120, 'And never will the Jews or the Christians approve of you until you follow their religion. Say, "Indeed, the guidance of Allah is the [only] guidance." If you were to follow their desires after what has come to you of knowledge, you would have against Allah no protector or helper.'),
  ('en.sahih', 2, 121, 'Those to whom We have given the Book recite it with its true recital. They [are the ones who] believe in it. And whoever disbelieves in it - it is they who are the losers.'),
  ('en.sahih', 2, 122, 'O Children of Israel, remember My favor which I have bestowed upon you and that I preferred you over the worlds.'),
  ('en.sahih', 2, 123, 'And fear a Day when no soul will suffice for another soul at all, and no compensation will be accepted from it, nor will any intercession benefit it, nor will they be aided.'),
  ('en.sahih', 2, 124, 'And [mention, O Muhammad], when Abraham was tried by his Lord with commands and he fulfilled them. [Allah] said, "Indeed, I will make you a leader for the people." [Abraham] said, "And of my descendants?" [Allah] said, "My covenant does not include the wrongdoers."'),
  ('en.sahih', 2, 125, 'And [mention] when We made the House a place of return for the people and [a place of] security. And take, [O believers], from the standing place of Abraham a place of prayer. And We charged Abraham and Ishmael, [saying], "Purify My House for those who perform Tawaf and those who are staying [there] for worship and those who bow and prostrate [in prayer]."'),
  ('en.sahih', 2, 126, 'And [mention] when Abraham said, "My Lord, make this a secure city and provide its people with fruits - whoever of them believes in Allah and the Last Day." [Allah] said. "And whoever disbelieves - I will grant him enjoyment for a little; then I will force him to the punishment of the Fire, and wretched is the destination."'),
  ('en.sahih', 2, 127, 'And [mention] when Abraham was raising the foundations of the House and [with him] Ishmael, [saying], "Our Lord, accept [this] from us. Indeed You are the Hearing, the Knowing.'),
  ('en.sahih', 2, 128, 'Our Lord, and make us Muslims [in submission] to You and from our descendants a Muslim nation [in submission] to You. And show us our rites and accept our repentance. Indeed, You are the Accepting of repentance, the Merciful.'),
  ('en.sahih', 2, 129, 'Our Lord, and send among them a messenger from themselves who will recite to them Your verses and teach them the Book and wisdom and purify them. Indeed, You are the Exalted in Might, the Wise."'),
  ('en.sahih', 2, 130, 'And who would be averse to the religion of Abraham except one who makes a fool of himself. And We had chosen him in this world, and indeed he, in the Hereafter, will be among the righteous.'),
  ('en.sahih', 2, 131, 'When his Lord said to him, "Submit", he said "I have submitted [in Islam] to the Lord of the worlds."'),
  ('en.sahih', 2, 132, 'And Abraham instructed his sons [to do the same] and [so did] Jacob, [saying], "O my sons, indeed Allah has chosen for you this religion, so do not die except while you are Muslims."'),
  ('en.sahih', 2, 133, 'Or were you witnesses when death approached Jacob, when he said to his sons, "What will you worship after me?" They said, "We will worship your God and the God of your fathers, Abraham and Ishmael and Isaac - one God. And we are Muslims [in submission] to Him."'),
  ('en.sahih', 2, 134, 'That was a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.'),
  ('en.sahih', 2, 135, 'They say, "Be Jews or Christians [so] you will be guided." Say, "Rather, [we follow] the religion of Abraham, inclining toward truth, and he was not of the polytheists."'),
  ('en.sahih', 2, 136, 'Say, [O believers], "We have believed in Allah and what has been revealed to us and what has been revealed to Abraham and Ishmael and Isaac and Jacob and the Descendants and what was given to Moses and Jesus and what was given to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [in submission] to Him."'),
  ('en.sahih', 2, 137, 'So if they believe in the same as you believe in, then they have been [rightly] guided; but if they turn away, they are only in dissension, and Allah will be sufficient for you against them. And He is the Hearing, the Knowing.'),
  ('en.sahih', 2, 138, '[And say, "Ours is] the religion of Allah. And who is better than Allah in [ordaining] religion? And we are worshippers of Him."'),
  ('en.sahih', 2, 139, 'Say, [O Muhammad], "Do you argue with us about Allah while He is our Lord and your Lord? For us are our deeds, and for you are your deeds. And we are sincere [in deed and intention] to Him."'),
  ('en.sahih', 2, 140, 'Or do you say that Abraham and Ishmael and Isaac and Jacob and the Descendants were Jews or Christians? Say, "Are you more knowing or is Allah?" And who is more unjust than one who conceals a testimony he has from Allah? And Allah is not unaware of what you do.'),
  ('en.sahih', 2, 141, 'That is a nation which has passed on. It will have [the consequence of] what it earned, and you will have what you have earned. And you will not be asked about what they used to do.'),
  ('en.sahih', 2, 142, 'The foolish among the people will say, "What has turned them away from their qiblah, which they used to face?" Say, "To Allah belongs the east and the west. He guides whom He wills to a straight path."'),
  ('en.sahih', 2, 143, 'And thus we have made you a just community that you will be witnesses over the people and the Messenger will be a witness over you. And We did not make the qiblah which you used to face except that We might make evident who would follow the Messenger from who would turn back on his heels. And indeed, it is difficult except for those whom Allah has guided. And never would Allah have caused you to lose your faith. Indeed Allah is, to the people, Kind and Merciful.'),
  ('en.sahih', 2, 144, 'We have certainly seen the turning of your face, [O Muhammad], toward the heaven, and We will surely turn you to a qiblah with which you will be pleased. So turn your face toward al-Masjid al-Haram. And wherever you [believers] are, turn your faces toward it [in prayer]. Indeed, those who have been given the Scripture well know that it is the truth from their Lord. And Allah is not unaware of what they do.'),
  ('en.sahih', 2, 145, 'And if you brought to those who were given the Scripture every sign, they would not follow your qiblah. Nor will you be a follower of their qiblah. Nor would they be followers of one another\'s qiblah. So if you were to follow their desires after what has come to you of knowledge, indeed, you would then be among the wrongdoers.'),
  ('en.sahih', 2, 146, 'Those to whom We gave the Scripture know him as they know their own sons. But indeed, a party of them conceal the truth while they know [it].'),
  ('en.sahih', 2, 147, 'The truth is from your Lord, so never be among the doubters.'),
  ('en.sahih', 2, 148, 'For each [religious following] is a direction toward which it faces. So race to [all that is] good. Wherever you may be, Allah will bring you forth [for judgement] all together. Indeed, Allah is over all things competent.'),
  ('en.sahih', 2, 149, 'So from wherever you go out [for prayer, O Muhammad] turn your face toward al- Masjid al-Haram, and indeed, it is the truth from your Lord. And Allah is not unaware of what you do.'),
  ('en.sahih', 2, 150, 'And from wherever you go out [for prayer], turn your face toward al-Masjid al-Haram. And wherever you [believers] may be, turn your faces toward it in order that the people will not have any argument against you, except for those of them who commit wrong; so fear them not but fear Me. And [it is] so I may complete My favor upon you and that you may be guided.'),
  ('en.sahih', 2, 151, 'Just as We have sent among you a messenger from yourselves reciting to you Our verses and purifying you and teaching you the Book and wisdom and teaching you that which you did not know.'),
  ('en.sahih', 2, 152, 'So remember Me; I will remember you. And be grateful to Me and do not deny Me.'),
  ('en.sahih', 2, 153, 'O you who have believed, seek help through patience and prayer. Indeed, Allah is with the patient.'),
  ('en.sahih', 2, 154, 'And do not say about those who are killed in the way of Allah, "They are dead." Rather, they are alive, but you perceive [it] not.'),
  ('en.sahih', 2, 155, 'And We will surely test you with something of fear and hunger and a loss of wealth and lives and fruits, but give good tidings to the patient,'),
  ('en.sahih', 2, 156, 'Who, when disaster strikes them, say, "Indeed we belong to Allah, and indeed to Him we will return."'),
  ('en.sahih', 2, 157, 'Those are the ones upon whom are blessings from their Lord and mercy. And it is those who are the [rightly] guided.'),
  ('en.sahih', 2, 158, 'Indeed, as-Safa and al-Marwah are among the symbols of Allah. So whoever makes Hajj to the House or performs \'umrah - there is no blame upon him for walking between them. And whoever volunteers good - then indeed, Allah is appreciative and Knowing.'),
  ('en.sahih', 2, 159, 'Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Scripture - those are cursed by Allah and cursed by those who curse,'),
  ('en.sahih', 2, 160, 'Except for those who repent and correct themselves and make evident [what they concealed]. Those - I will accept their repentance, and I am the Accepting of repentance, the Merciful.'),
  ('en.sahih', 2, 161, 'Indeed, those who disbelieve and die while they are disbelievers - upon them will be the curse of Allah and of the angels and the people, all together,'),
  ('en.sahih', 2, 162, 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved.'),
  ('en.sahih', 2, 163, 'And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful.'),
  ('en.sahih', 2, 164, 'Indeed, in the creation of the heavens and earth, and the alternation of the night and the day, and the [great] ships which sail through the sea with that which benefits people, and what Allah has sent down from the heavens of rain, giving life thereby to the earth after its lifelessness and dispersing therein every [kind of] moving creature, and [His] directing of the winds and the clouds controlled between the heaven and the earth are signs for a people who use reason.'),
  ('en.sahih', 2, 165, 'And [yet], among the people are those who take other than Allah as equals [to Him]. They love them as they [should] love Allah. But those who believe are stronger in love for Allah. And if only they who have wronged would consider [that] when they see the punishment, [they will be certain] that all power belongs to Allah and that Allah is severe in punishment.'),
  ('en.sahih', 2, 166, '[And they should consider that] when those who have been followed disassociate themselves from those who followed [them], and they [all] see the punishment, and cut off from them are the ties [of relationship],'),
  ('en.sahih', 2, 167, 'Those who followed will say, "If only we had another turn [at worldly life] so we could disassociate ourselves from them as they have disassociated themselves from us." Thus will Allah show them their deeds as regrets upon them. And they are never to emerge from the Fire.'),
  ('en.sahih', 2, 168, 'O mankind, eat from whatever is on earth [that is] lawful and good and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.'),
  ('en.sahih', 2, 169, 'He only orders you to evil and immorality and to say about Allah what you do not know.'),
  ('en.sahih', 2, 170, 'And when it is said to them, "Follow what Allah has revealed," they say, "Rather, we will follow that which we found our fathers doing." Even though their fathers understood nothing, nor were they guided?'),
  ('en.sahih', 2, 171, 'The example of those who disbelieve is like that of one who shouts at what hears nothing but calls and cries cattle or sheep - deaf, dumb and blind, so they do not understand.'),
  ('en.sahih', 2, 172, 'O you who have believed, eat from the good things which We have provided for you and be grateful to Allah if it is [indeed] Him that you worship.'),
  ('en.sahih', 2, 173, 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], there is no sin upon him. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 2, 174, 'Indeed, they who conceal what Allah has sent down of the Book and exchange it for a small price - those consume not into their bellies except the Fire. And Allah will not speak to them on the Day of Resurrection, nor will He purify them. And they will have a painful punishment.'),
  ('en.sahih', 2, 175, 'Those are the ones who have exchanged guidance for error and forgiveness for punishment. How patient they are in pursuit of the Fire!'),
  ('en.sahih', 2, 176, 'That is [deserved by them] because Allah has sent down the Book in truth. And indeed, those who differ over the Book are in extreme dissension.'),
  ('en.sahih', 2, 177, 'Righteousness is not that you turn your faces toward the east or the west, but [true] righteousness is [in] one who believes in Allah, the Last Day, the angels, the Book, and the prophets and gives wealth, in spite of love for it, to relatives, orphans, the needy, the traveler, those who ask [for help], and for freeing slaves; [and who] establishes prayer and gives zakah; [those who] fulfill their promise when they promise; and [those who] are patient in poverty and hardship and during battle. Those are the ones who have been true, and it is those who are the righteous.'),
  ('en.sahih', 2, 178, 'O you who have believed, prescribed for you is legal retribution for those murdered - the free for the free, the slave for the slave, and the female for the female. But whoever overlooks from his brother anything, then there should be a suitable follow-up and payment to him with good conduct. This is an alleviation from your Lord and a mercy. But whoever transgresses after that will have a painful punishment.'),
  ('en.sahih', 2, 179, 'And there is for you in legal retribution [saving of] life, O you [people] of understanding, that you may become righteous.'),
  ('en.sahih', 2, 180, 'Prescribed for you when death approaches [any] one of you if he leaves wealth [is that he should make] a bequest for the parents and near relatives according to what is acceptable - a duty upon the righteous.'),
  ('en.sahih', 2, 181, 'Then whoever alters the bequest after he has heard it - the sin is only upon those who have altered it. Indeed, Allah is Hearing and Knowing.'),
  ('en.sahih', 2, 182, 'But if one fears from the bequeather [some] error or sin and corrects that which is between them, there is no sin upon him. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 2, 183, 'O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous -'),
  ('en.sahih', 2, 184, '[Fasting for] a limited number of days. So whoever among you is ill or on a journey [during them] - then an equal number of days [are to be made up]. And upon those who are able [to fast, but with hardship] - a ransom [as substitute] of feeding a poor person [each day]. And whoever volunteers excess - it is better for him. But to fast is best for you, if you only knew.'),
  ('en.sahih', 2, 185, 'The month of Ramadhan [is that] in which was revealed the Qur\'an, a guidance for the people and clear proofs of guidance and criterion. So whoever sights [the new moon of] the month, let him fast it; and whoever is ill or on a journey - then an equal number of other days. Allah intends for you ease and does not intend for you hardship and [wants] for you to complete the period and to glorify Allah for that [to] which He has guided you; and perhaps you will be grateful.'),
  ('en.sahih', 2, 186, 'And when My servants ask you, [O Muhammad], concerning Me - indeed I am near. I respond to the invocation of the supplicant when he calls upon Me. So let them respond to Me [by obedience] and believe in Me that they may be [rightly] guided.'),
  ('en.sahih', 2, 187, 'It has been made permissible for you the night preceding fasting to go to your wives [for sexual relations]. They are clothing for you and you are clothing for them. Allah knows that you used to deceive yourselves, so He accepted your repentance and forgave you. So now, have relations with them and seek that which Allah has decreed for you. And eat and drink until the white thread of dawn becomes distinct to you from the black thread [of night]. Then complete the fast until the sunset. And do not have relations with them as long as you are staying for worship in the mosques. These are the limits [set by] Allah, so do not approach them. Thus does Allah make clear His ordinances to the people that they may become righteous.'),
  ('en.sahih', 2, 188, 'And do not consume one another\'s wealth unjustly or send it [in bribery] to the rulers in order that [they might aid] you [to] consume a portion of the wealth of the people in sin, while you know [it is unlawful].'),
  ('en.sahih', 2, 189, 'They ask you, [O Muhammad], about the new moons. Say, "They are measurements of time for the people and for Hajj." And it is not righteousness to enter houses from the back, but righteousness is [in] one who fears Allah. And enter houses from their doors. And fear Allah that you may succeed.'),
  ('en.sahih', 2, 190, 'Fight in the way of Allah those who fight you but do not transgress. Indeed. Allah does not like transgressors.'),
  ('en.sahih', 2, 191, 'And kill them wherever you overtake them and expel them from wherever they have expelled you, and fitnah is worse than killing. And do not fight them at al-Masjid al- Haram until they fight you there. But if they fight you, then kill them. Such is the recompense of the disbelievers.'),
  ('en.sahih', 2, 192, 'And if they cease, then indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 2, 193, 'Fight them until there is no [more] fitnah and [until] worship is [acknowledged to be] for Allah. But if they cease, then there is to be no aggression except against the oppressors.'),
  ('en.sahih', 2, 194, '[Fighting in] the sacred month is for [aggression committed in] the sacred month, and for [all] violations is legal retribution. So whoever has assaulted you, then assault him in the same way that he has assaulted you. And fear Allah and know that Allah is with those who fear Him.'),
  ('en.sahih', 2, 195, 'And spend in the way of Allah and do not throw [yourselves] with your [own] hands into destruction [by refraining]. And do good; indeed, Allah loves the doers of good.'),
  ('en.sahih', 2, 196, 'And complete the Hajj and \'umrah for Allah. But if you are prevented, then [offer] what can be obtained with ease of sacrificial animals. And do not shave your heads until the sacrificial animal has reached its place of slaughter. And whoever among you is ill or has an ailment of the head [making shaving necessary must offer] a ransom of fasting [three days] or charity or sacrifice. And when you are secure, then whoever performs \'umrah [during the Hajj months] followed by Hajj [offers] what can be obtained with ease of sacrificial animals. And whoever cannot find [or afford such an animal] - then a fast of three days during Hajj and of seven when you have returned [home]. Those are ten complete [days]. This is for those whose family is not in the area of al-Masjid al-Haram. And fear Allah and know that Allah is severe in penalty.'),
  ('en.sahih', 2, 197, 'Hajj is [during] well-known months, so whoever has made Hajj obligatory upon himself therein [by entering the state of ihram], there is [to be for him] no sexual relations and no disobedience and no disputing during Hajj. And whatever good you do - Allah knows it. And take provisions, but indeed, the best provision is fear of Allah. And fear Me, O you of understanding.'),
  ('en.sahih', 2, 198, 'There is no blame upon you for seeking bounty from your Lord [during Hajj]. But when you depart from \'Arafat, remember Allah at al- Mash\'ar al-Haram. And remember Him, as He has guided you, for indeed, you were before that among those astray.'),
  ('en.sahih', 2, 199, 'Then depart from the place from where [all] the people depart and ask forgiveness of Allah. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 2, 200, 'And when you have completed your rites, remember Allah like your [previous] remembrance of your fathers or with [much] greater remembrance. And among the people is he who says, "Our Lord, give us in this world," and he will have in the Hereafter no share.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 2, 201, 'But among them is he who says, "Our Lord, give us in this world [that which is] good and in the Hereafter [that which is] good and protect us from the punishment of the Fire."'),
  ('en.sahih', 2, 202, 'Those will have a share of what they have earned, and Allah is swift in account.'),
  ('en.sahih', 2, 203, 'And remember Allah during [specific] numbered days. Then whoever hastens [his departure] in two days - there is no sin upon him; and whoever delays [until the third] - there is no sin upon him - for him who fears Allah. And fear Allah and know that unto Him you will be gathered.'),
  ('en.sahih', 2, 204, 'And of the people is he whose speech pleases you in worldly life, and he calls Allah to witness as to what is in his heart, yet he is the fiercest of opponents.'),
  ('en.sahih', 2, 205, 'And when he goes away, he strives throughout the land to cause corruption therein and destroy crops and animals. And Allah does not like corruption.'),
  ('en.sahih', 2, 206, 'And when it is said to him, "Fear Allah," pride in the sin takes hold of him. Sufficient for him is Hellfire, and how wretched is the resting place.'),
  ('en.sahih', 2, 207, 'And of the people is he who sells himself, seeking means to the approval of Allah. And Allah is kind to [His] servants.'),
  ('en.sahih', 2, 208, 'O you who have believed, enter into Islam completely [and perfectly] and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.'),
  ('en.sahih', 2, 209, 'But if you deviate after clear proofs have come to you, then know that Allah is Exalted in Might and Wise.'),
  ('en.sahih', 2, 210, 'Do they await but that Allah should come to them in covers of clouds and the angels [as well] and the matter is [then] decided? And to Allah [all] matters are returned.'),
  ('en.sahih', 2, 211, 'Ask the Children of Israel how many a sign of evidence We have given them. And whoever exchanges the favor of Allah [for disbelief] after it has come to him - then indeed, Allah is severe in penalty.'),
  ('en.sahih', 2, 212, 'Beautified for those who disbelieve is the life of this world, and they ridicule those who believe. But those who fear Allah are above them on the Day of Resurrection. And Allah gives provision to whom He wills without account.'),
  ('en.sahih', 2, 213, 'Mankind was [of] one religion [before their deviation]; then Allah sent the prophets as bringers of good tidings and warners and sent down with them the Scripture in truth to judge between the people concerning that in which they differed. And none differed over the Scripture except those who were given it - after the clear proofs came to them - out of jealous animosity among themselves. And Allah guided those who believed to the truth concerning that over which they had differed, by His permission. And Allah guides whom He wills to a straight path.'),
  ('en.sahih', 2, 214, 'Or do you think that you will enter Paradise while such [trial] has not yet come to you as came to those who passed on before you? They were touched by poverty and hardship and were shaken until [even their] messenger and those who believed with him said, "When is the help of Allah?" Unquestionably, the help of Allah is near.'),
  ('en.sahih', 2, 215, 'They ask you, [O Muhammad], what they should spend. Say, "Whatever you spend of good is [to be] for parents and relatives and orphans and the needy and the traveler. And whatever you do of good - indeed, Allah is Knowing of it."'),
  ('en.sahih', 2, 216, 'Fighting has been enjoined upon you while it is hateful to you. But perhaps you hate a thing and it is good for you; and perhaps you love a thing and it is bad for you. And Allah Knows, while you know not.'),
  ('en.sahih', 2, 217, 'They ask you about the sacred month - about fighting therein. Say, "Fighting therein is great [sin], but averting [people] from the way of Allah and disbelief in Him and [preventing access to] al-Masjid al-Haram and the expulsion of its people therefrom are greater [evil] in the sight of Allah. And fitnah is greater than killing." And they will continue to fight you until they turn you back from your religion if they are able. And whoever of you reverts from his religion [to disbelief] and dies while he is a disbeliever - for those, their deeds have become worthless in this world and the Hereafter, and those are the companions of the Fire, they will abide therein eternally.'),
  ('en.sahih', 2, 218, 'Indeed, those who have believed and those who have emigrated and fought in the cause of Allah - those expect the mercy of Allah. And Allah is Forgiving and Merciful.'),
  ('en.sahih', 2, 219, 'They ask you about wine and gambling. Say, "In them is great sin and [yet, some] benefit for people. But their sin is greater than their benefit." And they ask you what they should spend. Say, "The excess [beyond needs]." Thus Allah makes clear to you the verses [of revelation] that you might give thought.'),
  ('en.sahih', 2, 220, 'To this world and the Hereafter. And they ask you about orphans. Say, "Improvement for them is best. And if you mix your affairs with theirs - they are your brothers. And Allah knows the corrupter from the amender. And if Allah had willed, He could have put you in difficulty. Indeed, Allah is Exalted in Might and Wise.'),
  ('en.sahih', 2, 221, 'And do not marry polytheistic women until they believe. And a believing slave woman is better than a polytheist, even though she might please you. And do not marry polytheistic men [to your women] until they believe. And a believing slave is better than a polytheist, even though he might please you. Those invite [you] to the Fire, but Allah invites to Paradise and to forgiveness, by His permission. And He makes clear His verses to the people that perhaps they may remember.'),
  ('en.sahih', 2, 222, 'And they ask you about menstruation. Say, "It is harm, so keep away from wives during menstruation. And do not approach them until they are pure. And when they have purified themselves, then come to them from where Allah has ordained for you. Indeed, Allah loves those who are constantly repentant and loves those who purify themselves."'),
  ('en.sahih', 2, 223, 'Your wives are a place of sowing of seed for you, so come to your place of cultivation however you wish and put forth [righteousness] for yourselves. And fear Allah and know that you will meet Him. And give good tidings to the believers.'),
  ('en.sahih', 2, 224, 'And do not make [your oath by] Allah an excuse against being righteous and fearing Allah and making peace among people. And Allah is Hearing and Knowing.'),
  ('en.sahih', 2, 225, 'Allah does not impose blame upon you for what is unintentional in your oaths, but He imposes blame upon you for what your hearts have earned. And Allah is Forgiving and Forbearing.'),
  ('en.sahih', 2, 226, 'For those who swear not to have sexual relations with their wives is a waiting time of four months, but if they return [to normal relations] - then indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 2, 227, 'And if they decide on divorce - then indeed, Allah is Hearing and Knowing.'),
  ('en.sahih', 2, 228, 'Divorced women remain in waiting for three periods, and it is not lawful for them to conceal what Allah has created in their wombs if they believe in Allah and the Last Day. And their husbands have more right to take them back in this [period] if they want reconciliation. And due to the wives is similar to what is expected of them, according to what is reasonable. But the men have a degree over them [in responsibility and authority]. And Allah is Exalted in Might and Wise.'),
  ('en.sahih', 2, 229, 'Divorce is twice. Then, either keep [her] in an acceptable manner or release [her] with good treatment. And it is not lawful for you to take anything of what you have given them unless both fear that they will not be able to keep [within] the limits of Allah. But if you fear that they will not keep [within] the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself. These are the limits of Allah, so do not transgress them. And whoever transgresses the limits of Allah - it is those who are the wrongdoers.'),
  ('en.sahih', 2, 230, 'And if he has divorced her [for the third time], then she is not lawful to him afterward until [after] she marries a husband other than him. And if the latter husband divorces her [or dies], there is no blame upon the woman and her former husband for returning to each other if they think that they can keep [within] the limits of Allah. These are the limits of Allah, which He makes clear to a people who know.'),
  ('en.sahih', 2, 231, 'And when you divorce women and they have [nearly] fulfilled their term, either retain them according to acceptable terms or release them according to acceptable terms, and do not keep them, intending harm, to transgress [against them]. And whoever does that has certainly wronged himself. And do not take the verses of Allah in jest. And remember the favor of Allah upon you and what has been revealed to you of the Book and wisdom by which He instructs you. And fear Allah and know that Allah is Knowing of all things.'),
  ('en.sahih', 2, 232, 'And when you divorce women and they have fulfilled their term, do not prevent them from remarrying their [former] husbands if they agree among themselves on an acceptable basis. That is instructed to whoever of you believes in Allah and the Last Day. That is better for you and purer, and Allah knows and you know not.'),
  ('en.sahih', 2, 233, 'Mothers may breastfeed their children two complete years for whoever wishes to complete the nursing [period]. Upon the father is the mothers\' provision and their clothing according to what is acceptable. No person is charged with more than his capacity. No mother should be harmed through her child, and no father through his child. And upon the [father\'s] heir is [a duty] like that [of the father]. And if they both desire weaning through mutual consent from both of them and consultation, there is no blame upon either of them. And if you wish to have your children nursed by a substitute, there is no blame upon you as long as you give payment according to what is acceptable. And fear Allah and know that Allah is Seeing of what you do.'),
  ('en.sahih', 2, 234, 'And those who are taken in death among you and leave wives behind - they, [the wives, shall] wait four months and ten [days]. And when they have fulfilled their term, then there is no blame upon you for what they do with themselves in an acceptable manner. And Allah is [fully] Acquainted with what you do.'),
  ('en.sahih', 2, 235, 'There is no blame upon you for that to which you [indirectly] allude concerning a proposal to women or for what you conceal within yourselves. Allah knows that you will have them in mind. But do not promise them secretly except for saying a proper saying. And do not determine to undertake a marriage contract until the decreed period reaches its end. And know that Allah knows what is within yourselves, so beware of Him. And know that Allah is Forgiving and Forbearing.'),
  ('en.sahih', 2, 236, 'There is no blame upon you if you divorce women you have not touched nor specified for them an obligation. But give them [a gift of] compensation - the wealthy according to his capability and the poor according to his capability - a provision according to what is acceptable, a duty upon the doers of good.'),
  ('en.sahih', 2, 237, 'And if you divorce them before you have touched them and you have already specified for them an obligation, then [give] half of what you specified - unless they forego the right or the one in whose hand is the marriage contract foregoes it. And to forego it is nearer to righteousness. And do not forget graciousness between you. Indeed Allah, of whatever you do, is Seeing.'),
  ('en.sahih', 2, 238, 'Maintain with care the [obligatory] prayers and [in particular] the middle prayer and stand before Allah, devoutly obedient.'),
  ('en.sahih', 2, 239, 'And if you fear [an enemy, then pray] on foot or riding. But when you are secure, then remember Allah [in prayer], as He has taught you that which you did not [previously] know.'),
  ('en.sahih', 2, 240, 'And those who are taken in death among you and leave wives behind - for their wives is a bequest: maintenance for one year without turning [them] out. But if they leave [of their own accord], then there is no blame upon you for what they do with themselves in an acceptable way. And Allah is Exalted in Might and Wise.'),
  ('en.sahih', 2, 241, 'And for divorced women is a provision according to what is acceptable - a duty upon the righteous.'),
  ('en.sahih', 2, 242, 'Thus does Allah make clear to you His verses that you might use reason.'),
  ('en.sahih', 2, 243, 'Have you not considered those who left their homes in many thousands, fearing death? Allah said to them, "Die"; then He restored them to life. And Allah is full of bounty to the people, but most of the people do not show gratitude.'),
  ('en.sahih', 2, 244, 'And fight in the cause of Allah and know that Allah is Hearing and Knowing.'),
  ('en.sahih', 2, 245, 'Who is it that would loan Allah a goodly loan so He may multiply it for him many times over? And it is Allah who withholds and grants abundance, and to Him you will be returned.'),
  ('en.sahih', 2, 246, 'Have you not considered the assembly of the Children of Israel after [the time of] Moses when they said to a prophet of theirs, "Send to us a king, and we will fight in the way of Allah "? He said, "Would you perhaps refrain from fighting if fighting was prescribed for you?" They said, "And why should we not fight in the cause of Allah when we have been driven out from our homes and from our children?" But when fighting was prescribed for them, they turned away, except for a few of them. And Allah is Knowing of the wrongdoers.'),
  ('en.sahih', 2, 247, 'And their prophet said to them, "Indeed, Allah has sent to you Saul as a king." They said, "How can he have kingship over us while we are more worthy of kingship than him and he has not been given any measure of wealth?" He said, "Indeed, Allah has chosen him over you and has increased him abundantly in knowledge and stature. And Allah gives His sovereignty to whom He wills. And Allah is all-Encompassing [in favor] and Knowing."'),
  ('en.sahih', 2, 248, 'And their prophet said to them, "Indeed, a sign of his kingship is that the chest will come to you in which is assurance from your Lord and a remnant of what the family of Moses and the family of Aaron had left, carried by the angels. Indeed in that is a sign for you, if you are believers."'),
  ('en.sahih', 2, 249, 'And when Saul went forth with the soldiers, he said, "Indeed, Allah will be testing you with a river. So whoever drinks from it is not of me, and whoever does not taste it is indeed of me, excepting one who takes [from it] in the hollow of his hand." But they drank from it, except a [very] few of them. Then when he had crossed it along with those who believed with him, they said, "There is no power for us today against Goliath and his soldiers." But those who were certain that they would meet Allah said, "How many a small company has overcome a large company by permission of Allah. And Allah is with the patient."'),
  ('en.sahih', 2, 250, 'And when they went forth to [face] Goliath and his soldiers, they said, "Our Lord, pour upon us patience and plant firmly our feet and give us victory over the disbelieving people."'),
  ('en.sahih', 2, 251, 'So they defeated them by permission of Allah, and David killed Goliath, and Allah gave him the kingship and prophethood and taught him from that which He willed. And if it were not for Allah checking [some] people by means of others, the earth would have been corrupted, but Allah is full of bounty to the worlds.'),
  ('en.sahih', 2, 252, 'These are the verses of Allah which We recite to you, [O Muhammad], in truth. And indeed, you are from among the messengers.'),
  ('en.sahih', 2, 253, 'Those messengers - some of them We caused to exceed others. Among them were those to whom Allah spoke, and He raised some of them in degree. And We gave Jesus, the Son of Mary, clear proofs, and We supported him with the Pure Spirit. If Allah had willed, those [generations] succeeding them would not have fought each other after the clear proofs had come to them. But they differed, and some of them believed and some of them disbelieved. And if Allah had willed, they would not have fought each other, but Allah does what He intends.'),
  ('en.sahih', 2, 254, 'O you who have believed, spend from that which We have provided for you before there comes a Day in which there is no exchange and no friendship and no intercession. And the disbelievers - they are the wrongdoers.'),
  ('en.sahih', 2, 255, 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.'),
  ('en.sahih', 2, 256, 'There shall be no compulsion in [acceptance of] the religion. The right course has become clear from the wrong. So whoever disbelieves in Taghut and believes in Allah has grasped the most trustworthy handhold with no break in it. And Allah is Hearing and Knowing.'),
  ('en.sahih', 2, 257, 'Allah is the ally of those who believe. He brings them out from darknesses into the light. And those who disbelieve - their allies are Taghut. They take them out of the light into darknesses. Those are the companions of the Fire; they will abide eternally therein.'),
  ('en.sahih', 2, 258, 'Have you not considered the one who argued with Abraham about his Lord [merely] because Allah had given him kingship? When Abraham said, "My Lord is the one who gives life and causes death," he said, "I give life and cause death." Abraham said, "Indeed, Allah brings up the sun from the east, so bring it up from the west." So the disbeliever was overwhelmed [by astonishment], and Allah does not guide the wrongdoing people.'),
  ('en.sahih', 2, 259, 'Or [consider such an example] as the one who passed by a township which had fallen into ruin. He said, "How will Allah bring this to life after its death?" So Allah caused him to die for a hundred years; then He revived him. He said, "How long have you remained?" The man said, "I have remained a day or part of a day." He said, "Rather, you have remained one hundred years. Look at your food and your drink; it has not changed with time. And look at your donkey; and We will make you a sign for the people. And look at the bones [of this donkey] - how We raise them and then We cover them with flesh." And when it became clear to him, he said, "I know that Allah is over all things competent."'),
  ('en.sahih', 2, 260, 'And [mention] when Abraham said, "My Lord, show me how You give life to the dead." [Allah] said, "Have you not believed?" He said, "Yes, but [I ask] only that my heart may be satisfied." [Allah] said, "Take four birds and commit them to yourself. Then [after slaughtering them] put on each hill a portion of them; then call them - they will come [flying] to you in haste. And know that Allah is Exalted in Might and Wise."'),
  ('en.sahih', 2, 261, 'The example of those who spend their wealth in the way of Allah is like a seed [of grain] which grows seven spikes; in each spike is a hundred grains. And Allah multiplies [His reward] for whom He wills. And Allah is all-Encompassing and Knowing.'),
  ('en.sahih', 2, 262, 'Those who spend their wealth in the way of Allah and then do not follow up what they have spent with reminders [of it] or [other] injury will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.'),
  ('en.sahih', 2, 263, 'Kind speech and forgiveness are better than charity followed by injury. And Allah is Free of need and Forbearing.'),
  ('en.sahih', 2, 264, 'O you who have believed, do not invalidate your charities with reminders or injury as does one who spends his wealth [only] to be seen by the people and does not believe in Allah and the Last Day. His example is like that of a [large] smooth stone upon which is dust and is hit by a downpour that leaves it bare. They are unable [to keep] anything of what they have earned. And Allah does not guide the disbelieving people.'),
  ('en.sahih', 2, 265, 'And the example of those who spend their wealth seeking means to the approval of Allah and assuring [reward for] themselves is like a garden on high ground which is hit by a downpour - so it yields its fruits in double. And [even] if it is not hit by a downpour, then a drizzle [is sufficient]. And Allah, of what you do, is Seeing.'),
  ('en.sahih', 2, 266, 'Would one of you like to have a garden of palm trees and grapevines underneath which rivers flow in which he has from every fruit? But he is afflicted with old age and has weak offspring, and it is hit by a whirlwind containing fire and is burned. Thus does Allah make clear to you [His] verses that you might give thought.'),
  ('en.sahih', 2, 267, 'O you who have believed, spend from the good things which you have earned and from that which We have produced for you from the earth. And do not aim toward the defective therefrom, spending [from that] while you would not take it [yourself] except with closed eyes. And know that Allah is Free of need and Praiseworthy.'),
  ('en.sahih', 2, 268, 'Satan threatens you with poverty and orders you to immorality, while Allah promises you forgiveness from Him and bounty. And Allah is all-Encompassing and Knowing.'),
  ('en.sahih', 2, 269, 'He gives wisdom to whom He wills, and whoever has been given wisdom has certainly been given much good. And none will remember except those of understanding.'),
  ('en.sahih', 2, 270, 'And whatever you spend of expenditures or make of vows - indeed, Allah knows of it. And for the wrongdoers there are no helpers.'),
  ('en.sahih', 2, 271, 'If you disclose your charitable expenditures, they are good; but if you conceal them and give them to the poor, it is better for you, and He will remove from you some of your misdeeds [thereby]. And Allah, with what you do, is [fully] Acquainted.'),
  ('en.sahih', 2, 272, 'Not upon you, [O Muhammad], is [responsibility for] their guidance, but Allah guides whom He wills. And whatever good you [believers] spend is for yourselves, and you do not spend except seeking the countenance of Allah. And whatever you spend of good - it will be fully repaid to you, and you will not be wronged.'),
  ('en.sahih', 2, 273, '[Charity is] for the poor who have been restricted for the cause of Allah, unable to move about in the land. An ignorant [person] would think them self-sufficient because of their restraint, but you will know them by their [characteristic] sign. They do not ask people persistently [or at all]. And whatever you spend of good - indeed, Allah is Knowing of it.'),
  ('en.sahih', 2, 274, 'Those who spend their wealth [in Allah \'s way] by night and by day, secretly and publicly - they will have their reward with their Lord. And no fear will there be concerning them, nor will they grieve.'),
  ('en.sahih', 2, 275, 'Those who consume interest cannot stand [on the Day of Resurrection] except as one stands who is being beaten by Satan into insanity. That is because they say, "Trade is [just] like interest." But Allah has permitted trade and has forbidden interest. So whoever has received an admonition from his Lord and desists may have what is past, and his affair rests with Allah. But whoever returns to [dealing in interest or usury] - those are the companions of the Fire; they will abide eternally therein.'),
  ('en.sahih', 2, 276, 'Allah destroys interest and gives increase for charities. And Allah does not like every sinning disbeliever.'),
  ('en.sahih', 2, 277, 'Indeed, those who believe and do righteous deeds and establish prayer and give zakah will have their reward with their Lord, and there will be no fear concerning them, nor will they grieve.'),
  ('en.sahih', 2, 278, 'O you who have believed, fear Allah and give up what remains [due to you] of interest, if you should be believers.'),
  ('en.sahih', 2, 279, 'And if you do not, then be informed of a war [against you] from Allah and His Messenger. But if you repent, you may have your principal - [thus] you do no wrong, nor are you wronged.'),
  ('en.sahih', 2, 280, 'And if someone is in hardship, then [let there be] postponement until [a time of] ease. But if you give [from your right as] charity, then it is better for you, if you only knew.'),
  ('en.sahih', 2, 281, 'And fear a Day when you will be returned to Allah. Then every soul will be compensated for what it earned, and they will not be treated unjustly.'),
  ('en.sahih', 2, 282, 'O you who have believed, when you contract a debt for a specified term, write it down. And let a scribe write [it] between you in justice. Let no scribe refuse to write as Allah has taught him. So let him write and let the one who has the obligation dictate. And let him fear Allah, his Lord, and not leave anything out of it. But if the one who has the obligation is of limited understanding or weak or unable to dictate himself, then let his guardian dictate in justice. And bring to witness two witnesses from among your men. And if there are not two men [available], then a man and two women from those whom you accept as witnesses - so that if one of the women errs, then the other can remind her. And let not the witnesses refuse when they are called upon. And do not be [too] weary to write it, whether it is small or large, for its [specified] term. That is more just in the sight of Allah and stronger as evidence and more likely to prevent doubt between you, except when it is an immediate transaction which you conduct among yourselves. For [then] there is no blame upon you if you do not write it. And take witnesses when you conclude a contract. Let no scribe be harmed or any witness. For if you do so, indeed, it is [grave] disobedience in you. And fear Allah. And Allah teaches you. And Allah is Knowing of all things.'),
  ('en.sahih', 2, 283, 'And if you are on a journey and cannot find a scribe, then a security deposit [should be] taken. And if one of you entrusts another, then let him who is entrusted discharge his trust [faithfully] and let him fear Allah, his Lord. And do not conceal testimony, for whoever conceals it - his heart is indeed sinful, and Allah is Knowing of what you do.'),
  ('en.sahih', 2, 284, 'To Allah belongs whatever is in the heavens and whatever is in the earth. Whether you show what is within yourselves or conceal it, Allah will bring you to account for it. Then He will forgive whom He wills and punish whom He wills, and Allah is over all things competent.'),
  ('en.sahih', 2, 285, 'The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], "We make no distinction between any of His messengers." And they say, "We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination."'),
  ('en.sahih', 2, 286, 'Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. "Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 2, 1, 'আলিফ লাম মীম।'),
  ('bn.bengali', 2, 2, 'এ সেই কিতাব যাতে কোনই সন্দেহ নেই। পথ প্রদর্শনকারী পরহেযগারদের জন্য,'),
  ('bn.bengali', 2, 3, 'যারা অদেখা বিষয়ের উপর বিশ্বাস স্থাপন করে এবং নামায প্রতিষ্ঠা করে। আর আমি তাদেরকে যে রুযী দান করেছি তা থেকে ব্যয় করে'),
  ('bn.bengali', 2, 4, 'এবং যারা বিশ্বাস স্থাপন করেছে সেসব বিষয়ের উপর যা কিছু তোমার প্রতি অবতীর্ণ হয়েছে এবং সেসব বিষয়ের উপর যা তোমার পূর্ববর্তীদের প্রতি অবতীর্ণ হয়েছে। আর আখেরাতকে যারা নিশ্চিত বলে বিশ্বাস করে।'),
  ('bn.bengali', 2, 5, 'তারাই নিজেদের পালনকর্তার পক্ষ থেকে সুপথ প্রাপ্ত, আর তারাই যথার্থ সফলকাম।'),
  ('bn.bengali', 2, 6, 'নিশ্চিতই যারা কাফের হয়েছে তাদেরকে আপনি ভয় প্রদর্শন করুন আর নাই করুন তাতে কিছুই আসে যায় না, তারা ঈমান আনবে না।'),
  ('bn.bengali', 2, 7, 'আল্লাহ তাদের অন্তকরণ এবং তাদের কানসমূহ বন্ধ করে দিয়েছেন, আর তাদের চোখসমূহ পর্দায় ঢেকে দিয়েছেন। আর তাদের জন্য রয়েছে কঠোর শাস্তি।'),
  ('bn.bengali', 2, 8, 'আর মানুষের মধ্যে কিছু লোক এমন রয়েছে যারা বলে, আমরা আল্লাহ ও পরকালের প্রতি ঈমান এনেছি অথচ আদৌ তারা ঈমানদার নয়।'),
  ('bn.bengali', 2, 9, 'তারা আল্লাহ এবং ঈমানদারগণকে ধোঁকা দেয়। অথচ এতে তারা নিজেদেরকে ছাড়া অন্য কাউকে ধোঁকা দেয় না অথচ তারা তা অনুভব করতে পারে না।'),
  ('bn.bengali', 2, 10, 'তাদের অন্তঃকরণ ব্যধিগ্রস্ত আর আল্লাহ তাদের ব্যধি আরো বাড়িয়ে দিয়েছেন। বস্তুতঃ তাদের জন্য নির্ধারিত রয়েছে ভয়াবহ আযাব, তাদের মিথ্যাচারের দরুন।'),
  ('bn.bengali', 2, 11, 'আর যখন তাদেরকে বলা হয় যে, দুনিয়ার বুকে দাঙ্গা-হাঙ্গামা সৃষ্টি করো না, তখন তারা বলে, আমরা তো মীমাংসার পথ অবলম্বন করেছি।'),
  ('bn.bengali', 2, 12, 'মনে রেখো, তারাই হাঙ্গামা সৃষ্টিকারী, কিন্তু তারা তা উপলব্ধি করে না।'),
  ('bn.bengali', 2, 13, 'আর যখন তাদেরকে বলা হয়, অন্যান্যরা যেভাবে ঈমান এনেছে তোমরাও সেভাবে ঈমান আন, তখন তারা বলে, আমরাও কি ঈমান আনব বোকাদেরই মত! মনে রেখো, প্রকৃতপক্ষে তারাই বোকা, কিন্তু তারা তা বোঝে না।'),
  ('bn.bengali', 2, 14, 'আর তারা যখন ঈমানদারদের সাথে মিশে, তখন বলে, আমরা ঈমান এনেছি। আবার যখন তাদের শয়তানদের সাথে একান্তে সাক্ষাৎ করে, তখন বলে, আমরা তোমাদের সাথে রয়েছি। আমরা তো (মুসলমানদের সাথে) উপহাস করি মাত্রা।'),
  ('bn.bengali', 2, 15, 'বরং আল্লাহই তাদের সাথে উপহাস করেন। আর তাদেরকে তিনি ছেড়ে দিয়েছেন যেন তারা নিজেদের অহংকার ও কুমতলবে হয়রান ও পেরেশান থাকে।'),
  ('bn.bengali', 2, 16, 'তারা সে সমস্ত লোক, যারা হেদায়েতের বিনিময়ে গোমরাহী খরিদ করে। বস্তুতঃ তারা তাদের এ ব্যবসায় লাভবান হতে পারেনি এবং তারা হেদায়েতও লাভ করতে পারেনি।'),
  ('bn.bengali', 2, 17, 'তাদের অবস্থা সে ব্যক্তির মত, যে লোক কোথাও আগুন জ্বালালো এবং তার চারদিককার সবকিছুকে যখন আগুন স্পষ্ট করে তুললো, ঠিক এমনি সময় আল্লাহ তার চারদিকের আলোকে উঠিয়ে নিলেন এবং তাদেরকে অন্ধকারে ছেড়ে দিলেন। ফলে, তারা কিছুই দেখতে পায় না।'),
  ('bn.bengali', 2, 18, 'তারা বধির, মূক ও অন্ধ। সুতরাং তারা ফিরে আসবে না।'),
  ('bn.bengali', 2, 19, 'আর তাদের উদাহরণ সেসব লোকের মত যারা দুর্যোগপূর্ণ ঝড়ো রাতে পথ চলে, যাতে থাকে আঁধার, গর্জন ও বিদ্যুৎচমক। মৃত্যুর ভয়ে গর্জনের সময় কানে আঙ্গুল দিয়ে রক্ষা পেতে চায়। অথচ সমস্ত কাফেরই আল্লাহ কর্তৃক পরিবেষ্ঠিত।'),
  ('bn.bengali', 2, 20, 'বিদ্যুতালোকে যখন সামান্য আলোকিত হয়, তখন কিছুটা পথ চলে। আবার যখন অন্ধকার হয়ে যায়, তখন ঠাঁয় দাঁড়িয়ে থাকে। যদি আল্লাহ ইচ্ছা করেন, তাহলে তাদের শ্রবণশক্তি ও দৃষ্টিশক্তি ছিনিয়ে নিতে পারেন। আল্লাহ যাবতীয় বিষয়ের উপর সর্বময় ক্ষমতাশীল।'),
  ('bn.bengali', 2, 21, 'হে মানব সমাজ! তোমরা তোমাদের পালনকর্তার এবাদত কর, যিনি তোমাদিগকে এবং তোমাদের পূর্ববর্তীদিগকে সৃষ্টি করেছেন। তাতে আশা করা যায়, তোমরা পরহেযগারী অর্জন করতে পারবে।'),
  ('bn.bengali', 2, 22, 'যে পবিত্রসত্তা তোমাদের জন্য ভূমিকে বিছানা এবং আকাশকে ছাদ স্বরূপ স্থাপন করে দিয়েছেন, আর আকাশ থেকে পানি বর্ষণ করে তোমাদের জন্য ফল-ফসল উৎপাদন করেছেন তোমাদের খাদ্য হিসাবে। অতএব, আল্লাহর সাথে তোমরা অন্য কাকেও সমকক্ষ করো না। বস্তুতঃ এসব তোমরা জান।'),
  ('bn.bengali', 2, 23, 'এতদসম্পর্কে যদি তোমাদের কোন সন্দেহ থাকে যা আমি আমার বান্দার প্রতি অবতীর্ণ করেছি, তাহলে এর মত একটি সূরা রচনা করে নিয়ে এস। তোমাদের সেসব সাহায্যকারীদেরকে সঙ্গে নাও-এক আল্লাহকে ছাড়া, যদি তোমরা সত্যবাদী হয়ে থাকো।'),
  ('bn.bengali', 2, 24, 'আর যদি তা না পার-অবশ্য তা তোমরা কখনও পারবে না, তাহলে সে দোযখের আগুন থেকে রক্ষা পাওয়ার চেষ্টা কর, যার জ্বালানী হবে মানুষ ও পাথর। যা প্রস্তুত করা হয়েছে কাফেরদের জন্য।'),
  ('bn.bengali', 2, 25, 'আর হে নবী (সাঃ), যারা ঈমান এনেছে এবং সৎকাজসমূহ করেছে, আপনি তাদেরকে এমন বেহেশতের সুসংবাদ দিন, যার পাদদেশে নহরসমূহ প্রবাহমান থাকবে। যখনই তারা খাবার হিসেবে কোন ফল প্রাপ্ত হবে, তখনই তারা বলবে, এতো অবিকল সে ফলই যা আমরা ইতিপূর্বেও লাভ করেছিলাম। বস্তুতঃ তাদেরকে একই প্রকৃতির ফল প্রদান করা হবে। এবং সেখানে তাদের জন্য শুদ্ধচারিনী রমণীকূল থাকবে। আর সেখানে তারা অনন্তকাল অবস্থান করবে।'),
  ('bn.bengali', 2, 26, 'আল্লাহ পাক নিঃসন্দেহে মশা বা তদুর্ধ্ব বস্তু দ্বারা উপমা পেশ করতে লজ্জাবোধ করেন না। বস্তুতঃ যারা মুমিন তারা নিশ্চিতভাবে বিশ্বাস করে যে, তাদের পালনকর্তা কর্তৃক উপস্থাপিত এ উপমা সম্পূর্ণ নির্ভূল ও সঠিক। আর যারা কাফের তারা বলে, এরূপ উপমা উপস্থাপনে আল্লাহর মতলবই বা কি ছিল। এ দ্বারা আল্লাহ তা’আলা অনেককে বিপথগামী করেন, আবার অনেককে সঠিক পথও প্রদর্শন করেন। তিনি অনুরূপ উপমা দ্বারা অসৎ ব্যক্তিবর্গ ভিন্ন কাকেও বিপথগামী করেন না।'),
  ('bn.bengali', 2, 27, '(বিপথগামী ওরাই) যারা আল্লাহর সঙ্গে অঙ্গীকারাবদ্ধ হওয়ার পর তা ভঙ্গ করে এবং আল্লাহ পাক যা অবিচ্ছিন্ন রাখতে নির্দেশ দিয়েছেন, তা ছিন্ন করে, আর পৃথিবীর বুকে অশান্তি সৃষ্টি করে। ওরা যথার্থই ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 2, 28, 'কেমন করে তোমরা আল্লাহর ব্যাপারে কুফরী অবলম্বন করছ? অথচ তোমরা ছিলে নিষ্প্রাণ। অতঃপর তিনিই তোমাদেরকে প্রাণ দান করেছেন, আবার মৃত্যু দান করবেন। পুনরায় তোমাদেরকে জীবনদান করবেন। অতঃপর তারই প্রতি প্রত্যাবর্তন করবে।'),
  ('bn.bengali', 2, 29, 'তিনিই সে সত্ত্বা যিনি সৃষ্টি করেছেন তোমাদের জন্য যা কিছু জমীনে রয়েছে সে সমস্ত। তারপর তিনি মনোসংযোগ করেছেন আকাশের প্রতি। বস্তুতঃ তিনি তৈরী করেছেন সাত আসমান। আর আল্লাহ সর্ববিষয়ে অবহিত।'),
  ('bn.bengali', 2, 30, 'আর তোমার পালনকর্তা যখন ফেরেশতাদিগকে বললেনঃ আমি পৃথিবীতে একজন প্রতিনিধি বানাতে যাচ্ছি, তখন ফেরেশতাগণ বলল, তুমি কি পৃথিবীতে এমন কাউকে সৃষ্টি করবে যে দাঙ্গা-হাঙ্গামার সৃষ্টি করবে এবং রক্তপাত ঘটাবে? অথচ আমরা নিয়ত তোমার গুণকীর্তন করছি এবং তোমার পবিত্র সত্তাকে স্মরণ করছি। তিনি বললেন, নিঃসন্দেহে আমি জানি, যা তোমরা জান না।'),
  ('bn.bengali', 2, 31, 'আর আল্লাহ তা’আলা শিখালেন আদমকে সমস্ত বস্তু-সামগ্রীর নাম। তারপর সে সমস্ত বস্তু-সামগ্রীকে ফেরেশতাদের সামনে উপস্থাপন করলেন। অতঃপর বললেন, আমাকে তোমরা এগুলোর নাম বলে দাও, যদি তোমরা সত্য হয়ে থাক।'),
  ('bn.bengali', 2, 32, 'তারা বলল, তুমি পবিত্র! আমরা কোন কিছুই জানি না, তবে তুমি যা আমাদিগকে শিখিয়েছ (সেগুলো ব্যতীত) নিশ্চয় তুমিই প্রকৃত জ্ঞানসম্পন্ন, হেকমতওয়ালা।'),
  ('bn.bengali', 2, 33, 'তিনি বললেন, হে আদম, ফেরেশতাদেরকে বলে দাও এসবের নাম। তারপর যখন তিনি বলে দিলেন সে সবের নাম, তখন তিনি বললেন, আমি কি তোমাদেরকে বলিনি যে, আমি আসমান ও যমীনের যাবতীয় গোপন বিষয় সম্পর্কে খুব ভাল করেই অবগত রয়েছি? এবং সেসব বিষয়ও জানি যা তোমরা প্রকাশ কর, আর যা তোমরা গোপন কর!'),
  ('bn.bengali', 2, 34, 'এবং যখন আমি হযরত আদম (আঃ)-কে সেজদা করার জন্য ফেরেশতাগণকে নির্দেশ দিলাম, তখনই ইবলীস ব্যতীত সবাই সিজদা করলো। সে (নির্দেশ) পালন করতে অস্বীকার করল এবং অহংকার প্রদর্শন করল। ফলে সে কাফেরদের অন্তর্ভূক্ত হয়ে গেল।'),
  ('bn.bengali', 2, 35, 'এবং আমি আদমকে হুকুম করলাম যে, তুমি ও তোমার স্ত্রী জান্নাতে বসবাস করতে থাক এবং ওখানে যা চাও, যেখান থেকে চাও, পরিতৃপ্তিসহ খেতে থাক, কিন্তু এ গাছের নিকটবর্তী হয়ো না। অন্যথায় তোমরা যালিমদের অন্তর্ভূক্ত হয়ে পড়বে।'),
  ('bn.bengali', 2, 36, 'অনন্তর শয়তান তাদের উভয়কে ওখান থেকে পদস্খলিত করেছিল। পরে তারা যে সুখ-স্বাচ্ছন্দ্যে ছিল তা থেকে তাদেরকে বের করে দিল এবং আমি বললাম, তোমরা নেমে যাও। তোমরা পরস্পর একে অপরের শক্র হবে এবং তোমাদেরকে সেখানে কিছুকাল অবস্থান করতে হবে ও লাভ সংগ্রহ করতে হবে।'),
  ('bn.bengali', 2, 37, 'অতঃপর হযরত আদম (আঃ) স্বীয় পালনকর্তার কাছ থেকে কয়েকটি কথা শিখে নিলেন, অতঃপর আল্লাহ পাক তাঁর প্রতি (করুণাভরে) লক্ষ্য করলেন। নিশ্চয়ই তিনি মহা-ক্ষমাশীল ও অসীম দয়ালু।'),
  ('bn.bengali', 2, 38, 'আমি হুকুম করলাম, তোমরা সবাই নীচে নেমে যাও। অতঃপর যদি তোমাদের নিকট আমার পক্ষ থেকে কোন হেদায়েত পৌঁছে, তবে যে ব্যক্তি আমার সে হেদায়েত অনুসারে চলবে, তার উপর না কোন ভয় আসবে, না (কোন কারণে) তারা চিন্তাগ্রস্ত ও সন্তপ্ত হবে।'),
  ('bn.bengali', 2, 39, 'আর যে লোক তা অস্বীকার করবে এবং আমার নিদর্শনগুলোকে মিথ্যা প্রতিপন্ন করার প্রয়াস পাবে, তারাই হবে জাহান্নামবাসী; অন্তকাল সেখানে থাকবে।'),
  ('bn.bengali', 2, 40, 'হে বনী-ইসরাঈলগণ, তোমরা স্মরণ কর আমার সে অনুগ্রহ যা আমি তোমাদের প্রতি করেছি এবং তোমরা পূরণ কর আমার সাথে কৃত প্রতিজ্ঞা, তাহলে আমি তোমাদেরকে প্রদত্ত প্রতিশ্রুতি পূরণ করব। আর ভয় কর আমাকেই।'),
  ('bn.bengali', 2, 41, 'আর তোমরা সে গ্রন্থের প্রতি বিশ্বাস স্থাপন কর, যা আমি অবতীর্ণ করেছি সত্যবক্তা হিসেবে তোমাদের কাছে। বস্তুতঃ তোমরা তার প্রাথমিক অস্বীকারকারী হয়ো না আর আমার আয়াতের অল্প মূল্য দিও না। এবং আমার (আযাব) থেকে বাঁচ।'),
  ('bn.bengali', 2, 42, 'তোমরা সত্যকে মিথ্যার সাথে মিশিয়ে দিও না এবং জানা সত্ত্বে সত্যকে তোমরা গোপন করো না।'),
  ('bn.bengali', 2, 43, 'আর নামায কায়েম কর, যাকাত দান কর এবং নামাযে অবনত হও তাদের সাথে, যারা অবনত হয়।'),
  ('bn.bengali', 2, 44, 'তোমরা কি মানুষকে সৎকর্মের নির্দেশ দাও এবং নিজেরা নিজেদেরকে ভূলে যাও, অথচ তোমরা কিতাব পাঠ কর? তবুও কি তোমরা চিন্তা কর না?'),
  ('bn.bengali', 2, 45, 'ধৈর্য্যর সাথে সাহায্য প্রার্থনা কর নামাযের মাধ্যমে। অবশ্য তা যথেষ্ট কঠিন। কিন্তু সে সমস্ত বিনয়ী লোকদের পক্ষেই তা সম্ভব।'),
  ('bn.bengali', 2, 46, 'যারা একথা খেয়াল করে যে, তাদেরকে সম্মুখীন হতে হবে স্বীয় পরওয়ারদেগারের এবং তাঁরই দিকে ফিরে যেতে হবে।'),
  ('bn.bengali', 2, 47, 'হে বনী-ইসরাঈলগণ! তোমরা স্মরণ কর আমার অনুগ্রহের কথা, যা আমি তোমাদের উপর করেছি এবং (স্মরণ কর) সে বিষয়টি যে, আমি তোমাদেরকে উচ্চমর্যাদা দান করেছি সমগ্র বিশ্বের উপর।'),
  ('bn.bengali', 2, 48, 'আর সে দিনের ভয় কর, যখন কেউ কারও সামান্য উপকারে আসবে না এবং তার পক্ষে কোন সুপারিশও কবুল হবে না; কারও কাছ থেকে ক্ষতিপূরণও নেয়া হবে না এবং তারা কোন রকম সাহায্যও পাবে না।'),
  ('bn.bengali', 2, 49, 'আর (স্মরণ কর) সে সময়ের কথা, যখন আমি তোমাদিগকে মুক্তিদান করেছি ফেরআউনের লোকদের কবল থেকে যারা তোমাদিগকে কঠিন শাস্তি দান করত; তোমাদের পুত্রসন্তানদেরকে জবাই করত এবং তোমাদের স্ত্রীদিগকে অব্যাহতি দিত। বস্তুতঃ তাতে পরীক্ষা ছিল তোমাদের পালনকর্তার পক্ষ থেকে, মহা পরীক্ষা।'),
  ('bn.bengali', 2, 50, 'আর যখন আমি তোমাদের জন্য সাগরকে দ্বিখন্ডিত করেছি, অতঃপর তোমাদেরকে বাঁচিয়ে দিয়েছি এবং ডুবিয়ে দিয়েছি ফেরআউনের লোকদিগকে অথচ তোমরা দেখছিলে।'),
  ('bn.bengali', 2, 51, 'আর যখন আমি মূসার সাথে ওয়াদা করেছি চল্লিশ রাত্রির অতঃপর তোমরা গোবৎস বানিয়ে নিয়েছ মূসার অনুপস্থিতিতে। বস্তুতঃ তোমরা ছিলে যালেম।'),
  ('bn.bengali', 2, 52, 'তারপর আমি তাতেও তোমাদেরকে ক্ষমা করে দিয়েছি, যাতে তোমরা কৃতজ্ঞতা স্বীকার করে নাও।'),
  ('bn.bengali', 2, 53, 'আর (স্মরণ কর) যখন আমি মূসাকে কিতাব এবং সত্য-মিথ্যার পার্থক্য বিধানকারী নির্দেশ দান করেছি, যাতে তোমরা সরল পথ প্রাপ্ত হতে পার।'),
  ('bn.bengali', 2, 54, 'আর যখন মূসা তার সম্প্রদায়কে বলল, হে আমার সম্প্রদায়, তোমরা তোমাদেরই ক্ষতিসাধন করেছ এই গোবৎস নির্মাণ করে। কাজেই এখন তওবা কর স্বীয় স্রষ্টার প্রতি এবং নিজ নিজ প্রাণ বিসর্জন দাও। এটাই তোমাদের জন্য কল্যাণকর তোমাদের স্রষ্টার নিকট। তারপর তোমাদের প্রতি লক্ষ্য করা হল। নিঃসন্দেহে তিনিই ক্ষমাকারী, অত্যন্ত মেহেরবান।'),
  ('bn.bengali', 2, 55, 'আর যখন তোমরা বললে, হে মূসা, কস্মিনকালেও আমরা তোমাকে বিশ্বাস করব না, যতক্ষণ না আমরা আল্লাহকে (প্রকাশ্যে) দেখতে পাব। বস্তুতঃ তোমাদিগকে পাকড়াও করল বিদ্যুৎ। অথচ তোমরা তা প্রত্যক্ষ করছিলে।'),
  ('bn.bengali', 2, 56, 'তারপর, মরে যাবার পর তোমাদিগকে আমি তুলে দাঁড় করিয়েছি, যাতে করে তোমরা কৃতজ্ঞতা স্বীকার করে নাও।'),
  ('bn.bengali', 2, 57, 'আর আমি তোমাদের উপর ছায়া দান করেছি মেঘমালার দ্বারা এবং তোমাদের জন্য খাবার পাঠিয়েছি ’মান্না’ ও সালওয়া’। সেসব পবিত্র বস্তু তোমরা ভক্ষন কর, যা আমি তোমাদেরকে দান করেছি। বস্তুতঃ তারা আমার কোন ক্ষতি করতে পারেনি, বরং নিজেদেরই ক্ষতি সাধন করেছে।'),
  ('bn.bengali', 2, 58, 'আর যখন আমি বললাম, তোমরা প্রবেশ কর এ নগরীতে এবং এতে যেখানে খুশী খেয়ে স্বাচ্ছন্দ্যে বিচরণ করতে থাক এবং দরজার ভিতর দিয়ে প্রবেশ করার সময় সেজদা করে ঢুক, আর বলতে থাক-‘আমাদিগকে ক্ষমা করে দাও’-তাহলে আমি তোমাদের অপরাধ ক্ষমা করব এবং সৎ কর্মশীলদেরকে অতিরিক্ত দানও করব।'),
  ('bn.bengali', 2, 59, 'অতঃপর যালেমরা কথা পাল্টে দিয়েছে, যা কিছু তাদেরকে বলে দেয়া হয়েছিল তা থেকে। তারপর আমি অবতীর্ণ করেছি যালেমদের উপর আযাব, আসমান থেকে, নির্দেশ লংঘন করার কারণে।'),
  ('bn.bengali', 2, 60, 'আর মূসা যখন নিজ জাতির জন্য পানি চাইল, তখন আমি বললাম, স্বীয় যষ্ঠির দ্বারা আঘাত কর পাথরের উপরে। অতঃপর তা থেকে প্রবাহিত হয়ে এল বারটি প্রস্রবণ। তাদের সব গোত্রই চিনে নিল নিজ নিজ ঘাট। আল্লাহর দেয়া রিযিক খাও, পান কর আর দুনিয়ার বুকে দাংগা-হাংগামা করে বেড়িও না।'),
  ('bn.bengali', 2, 61, 'আর তোমরা যখন বললে, হে মূসা, আমরা একই ধরনের খাদ্য-দ্রব্যে কখনও ধৈর্য্যধারণ করব না। কাজেই তুমি তোমার পালনকর্তার নিকট আমাদের পক্ষে প্রার্থনা কর, তিনি যেন আমাদের জন্যে এমন বস্তুসামগ্রী দান করেন যা জমিতে উৎপন্ন হয়, তরকারী, কাকড়ী, গম, মসুরি, পেঁয়াজ প্রভৃতি। মূসা (আঃ) বললেন, তোমরা কি এমন বস্তু নিতে চাও যা নিকৃষ্ট সে বস্তুর পরিবর্তে যা উত্তম? তোমরা কোন নগরীতে উপনীত হও, তাহলেই পাবে যা তোমরা কামনা করছ। আর তাদের উপর আরোপ করা হল লাঞ্ছনা ও পরমুখাপেক্ষিতা। তারা আল্লাহর রোষানলে পতিত হয়ে ঘুরতে থাকল। এমন হলো এ জন্য যে, তারা আল্লাহর বিধি বিধান মানতো না এবং নবীগনকে অন্যায়ভাবে হত্যা করত। তার কারণ, তারা ছিল নাফরমান সীমালংঘকারী।'),
  ('bn.bengali', 2, 62, 'নিঃসন্দেহে যারা মুসলমান হয়েছে এবং যারা ইহুদী, নাসারা ও সাবেঈন, (তাদের মধ্য থেকে) যারা ঈমান এনেছে আল্লাহর প্রতি ও কিয়ামত দিবসের প্রতি এবং সৎকাজ করেছে, তাদের জন্য রয়েছে তার সওয়াব তাদের পালনকর্তার কাছে। আর তাদের কোনই ভয়-ভীতি নেই, তারা দুঃখিতও হবে না।'),
  ('bn.bengali', 2, 63, 'আর আমি যখন তোমাদের কাছ থেকে অঙ্গীকার নিয়েছিলাম এবং তুর পর্বতকে তোমাদের মাথার উপর তুলে ধরেছিলাম এই বলে যে, তোমাদিগকে যে কিতাব দেয়া হয়েছে তাকে ধর সুদৃঢ়ভাবে এবং এতে যা কিছু রয়েছে তা মনে রেখো যাতে তোমরা ভয় কর।'),
  ('bn.bengali', 2, 64, 'তারপরেও তোমরা তা থেকে ফিরে গেছ। কাজেই আল্লাহর অনুগ্রহ ও মেহেরবানী যদি তোমাদের উপর না থাকত, তবে অবশ্যই তোমরা ধবংস হয়ে যেতে।'),
  ('bn.bengali', 2, 65, 'তোমরা তাদেরকে ভালরূপে জেনেছ, যারা শনিবারের ব্যাপারে সীমা লঙ্ঘণ করেছিল। আমি বলেছিলামঃ তোমরা লাঞ্ছিত বানর হয়ে যাও।'),
  ('bn.bengali', 2, 66, 'অতঃপর আমি এ ঘটনাকে তাদের সমসাময়িক ও পরবর্তীদের জন্য দৃষ্টান্ত এবং আল্লাহভীরুদের জন্য উপদেশ গ্রহণের উপাদান করে দিয়েছি।'),
  ('bn.bengali', 2, 67, 'যখন মূসা (আঃ) স্বীয় সম্প্রদায়কে বললেনঃ আল্লাহ তোমাদের একটি গরু জবাই করতে বলেছেন। তারা বলল, তুমি কি আমাদের সাথে উপহাস করছ? মূসা (আঃ) বললেন, মূর্খদের অন্তর্ভুক্ত হওয়া থেকে আমি আল্লাহর আশ্রয় প্রার্থনা করছি।'),
  ('bn.bengali', 2, 68, 'তারা বলল, তুমি তোমার পালনকর্তার কাছে আমাদের জন্য প্রার্থনা কর, যেন সেটির রূপ বিশ্লেষণ করা হয়। মূসা (আঃ) বললেন, তিনি বলছেন, সেটা হবে একটা গাভী, যা বৃদ্ধ নয় এবং কুমারীও নয়-বার্ধক্য ও যৌবনের মাঝামাঝি বয়সের। এখন আদিষ্ট কাজ করে ফেল।'),
  ('bn.bengali', 2, 69, 'তারা বলল, তোমার পালনকর্তার কাছে আমাদের জন্য প্রার্থনা কর যে, তার রঙ কিরূপ হবে? মূসা (আঃ) বললেন, তিনি বলেছেন যে, গাঢ় পীতবর্ণের গাভী-যা দর্শকদের চমৎকৃত করবে।'),
  ('bn.bengali', 2, 70, 'তারা বলল, আপনি প্রভুর কাছে প্রার্থনা করুন-তিনি বলে দিন যে, সেটা কিরূপ? কেননা, গরু আমাদের কাছে সাদৃশ্যশীল মনে হয়। ইনশাআল্লাহ এবার আমরা অবশ্যই পথপ্রাপ্ত হব। মূসা (আঃ) বললেন, তিনি বলেন যে, এ গাভী ভূকর্ষণ ও জল সেচনের শ্রমে অভ্যস্ত নয়-হবে নিষ্কলঙ্ক, নিখুঁত।'),
  ('bn.bengali', 2, 71, 'তারা বলল, এবার সঠিক তথ্য এনেছ। অতঃপর তারা সেটা জবাই করল, অথচ জবাই করবে বলে মনে হচ্ছিল না।'),
  ('bn.bengali', 2, 72, 'যখন তোমরা একজনকে হত্যা করে পরে সে সম্পর্কে একে অপরকে অভিযুক্ত করেছিলে। যা তোমরা গোপন করছিলে, তা প্রকাশ করে দেয়া ছিল আল্লাহর অভিপ্রায়।'),
  ('bn.bengali', 2, 73, 'অতঃপর আমি বললামঃ গরুর একটি খন্ড দ্বারা মৃতকে আঘাত কর। এভাবে আল্লাহ মৃতকে জীবিত করেন এবং তোমাদেরকে তাঁর নিদর্শণ সমূহ প্রদর্শন করেন-যাতে তোমরা চিন্তা কর।'),
  ('bn.bengali', 2, 74, 'অতঃপর এ ঘটনার পরে তোমাদের অন্তর কঠিন হয়ে গেছে। তা পাথরের মত অথবা তদপেক্ষাও কঠিন। পাথরের মধ্যে এমন ও আছে; যা থেকে ঝরণা প্রবাহিত হয়, এমনও আছে, যা বিদীর্ণ হয়, অতঃপর তা থেকে পানি নির্গত হয় এবং এমনও আছে, যা আল্লাহর ভয়ে খসেপড়তে থাকে! আল্লাহ তোমাদের কাজকর্ম সম্পর্কে বে-খবর নন।'),
  ('bn.bengali', 2, 75, 'হে মুসলমানগণ, তোমরা কি আশা কর যে, তারা তোমাদের কথায় ঈমান আনবে? তাদের মধ্যে একদল ছিল, যারা আল্লাহর বাণী শ্রবণ করত; অতঃপর বুঝে-শুনে তা পরিবর্তন করে দিত এবং তারা তা অবগত ছিল।'),
  ('bn.bengali', 2, 76, 'যখন তারা মুসলমানদের সাথে মিলিত হয়, তখন বলেঃ আমরা মুসলমান হয়েছি। আর যখন পরস্পরের সাথে নিভৃতে অবস্থান করে, তখন বলে, পালনকর্তা তোমাদের জন্যে যা প্রকাশ করেছেন, তা কি তাদের কাছে বলে দিচ্ছ? তাহলে যে তারা এ নিয়ে পালকর্তার সামনে তোমাদেরকে মিথ্যা প্রতিপন্ন করবে। তোমরা কি তা উপলব্ধি কর না?'),
  ('bn.bengali', 2, 77, 'তারা কি এতটুকুও জানে না যে, আল্লাহ সেসব বিষয়ও পরিজ্ঞাত যা তারা গোপন করে এবং যা প্রকাশ করে?'),
  ('bn.bengali', 2, 78, 'তোমাদের কিছু লোক নিরক্ষর। তারা মিথ্যা আকাঙ্খা ছাড়া আল্লাহর গ্রন্থের কিছুই জানে না। তাদের কাছে কল্পনা ছাড়া কিছুই নেই।'),
  ('bn.bengali', 2, 79, 'অতএব তাদের জন্যে আফসোস! যারা নিজ হাতে গ্রন্থ লেখে এবং বলে, এটা আল্লাহর পক্ষ থেকে অবতীর্ণ-যাতে এর বিনিময়ে সামান্য অর্থ গ্রহণ করতে পারে। অতএব তাদের প্রতি আক্ষেপ, তাদের হাতের লেখার জন্য এবং তাদের প্রতি আক্ষেপ, তাদের উপার্জনের জন্যে।'),
  ('bn.bengali', 2, 80, 'তারা বলেঃ আগুন আমাদিগকে কখনও স্পর্শ করবে না; কিন্তু গণাগনতি কয়েকদিন। বলে দিনঃ তোমরা কি আল্লাহর কাছ থেকে কোন অঙ্গীকার পেয়েছ যে, আল্লাহ কখনও তার খেলাফ করবেন না-না তোমরা যা জান না, তা আল্লাহর সাথে জুড়ে দিচ্ছ।'),
  ('bn.bengali', 2, 81, 'হাঁ, যে ব্যক্তি পাপ অর্জন করেছে এবং সে পাপ তাকে পরিবেষ্টিত করে নিয়েছে, তারাই দোযখের অধিবাসী। তারা সেখানেই চিরকাল থাকবে।'),
  ('bn.bengali', 2, 82, 'পক্ষান্তরে যারা ঈমান এনেছে এবং সৎকাজ করেছে, তারাই জান্নাতের অধিবাসী। তারা সেখানেই চিরকাল থাকবে।'),
  ('bn.bengali', 2, 83, 'যখন আমি বনী-ইসরাঈলের কাছ থেকে অঙ্গীকার নিলাম যে, তোমরা আল্লাহ ছাড়া কারও উপাসনা করবে না, পিতা-মাতা, আত্নীয়-স্বজন, এতীম ও দীন-দরিদ্রদের সাথে সদ্ব্যবহার করবে, মানুষকে সৎ কথাবার্তা বলবে, নামায প্রতিষ্ঠা করবে এবং যাকাত দেবে, তখন সামান্য কয়েকজন ছাড়া তোমরা মুখ ফিরিয়ে নিলে, তোমরাই অগ্রাহ্যকারী।'),
  ('bn.bengali', 2, 84, 'যখন আমি তোমাদের কাছ থেকে অঙ্গীকার নিলাম যে, তোমরা পরস্পর খুনাখুনি করবে না এবং নিজেদেরকে দেশ থেকে বহিস্কার করবে না, তখন তোমরা তা স্বীকার করেছিলে এবং তোমরা তার সাক্ষ্য দিচ্ছিলে।'),
  ('bn.bengali', 2, 85, 'অতঃপর তোমরাই পরস্পর খুনাখুনি করছ এবং তোমাদেরই একদলকে তাদের দেশ থেকে বহিস্কার করছ। তাদের বিরুদ্ধে পাপ ও অন্যায়ের মাধ্যমে আক্রমণ করছ। আর যদি তারাই কারও বন্দী হয়ে তোমাদের কাছে আসে, তবে বিনিময় নিয়ে তাদের মুক্ত করছ। অথচ তাদের বহিস্কার করাও তোমাদের জন্য অবৈধ। তবে কি তোমরা গ্রন্থের কিয়দংশ বিশ্বাস কর এবং কিয়দংশ অবিশ্বাস কর? যারা এরূপ করে পার্থিব জীবনে দূগর্তি ছাড়া তাদের আর কোনই পথ নেই। কিয়ামতের দিন তাদের কঠোরতম শাস্তির দিকে পৌঁছে দেয়া হবে। আল্লাহ তোমাদের কাজ-কর্ম সম্পর্কে বে-খবর নন।'),
  ('bn.bengali', 2, 86, 'এরাই পরকালের বিনিময়ে পার্থিব জীবন ক্রয় করেছে। অতএব এদের শাস্তি লঘু হবে না এবং এরা সাহায্যও পাবে না।'),
  ('bn.bengali', 2, 87, 'অবশ্যই আমি মূসাকে কিতাব দিয়েছি। এবং তার পরে পর্যায়ক্রমে রসূল পাঠিয়েছি। আমি মরিয়ম তনয় ঈসাকে সুস্পষ্ট মোজেযা দান করেছি এবং পবিত্র রূহের মাধ্যমে তাকে শক্তিদান করেছি। অতঃপর যখনই কোন রসূল এমন নির্দেশ নিয়ে তোমাদের কাছে এসেছে, যা তোমাদের মনে ভাল লাগেনি, তখনই তোমরা অহংকার করেছ। শেষ পর্যন্ত তোমরা একদলকে মিথ্যাবাদী বলেছ এবং একদলকে হত্যা করেছ।'),
  ('bn.bengali', 2, 88, 'তারা বলে, আমাদের হৃদয় অর্ধাবৃত। এবং তাদের কুফরের কারণে আল্লাহ অভিসম্পাত করেছেন। ফলে তারা অল্পই ঈমান আনে।'),
  ('bn.bengali', 2, 89, 'যখন তাদের কাছে আল্লাহর পক্ষ থেকে কিতাব এসে পৌঁছাল, যা সে বিষয়ের সত্যায়ন করে, যা তাদের কাছে রয়েছে এবং তারা পূর্বে করত। অবশেষে যখন তাদের কাছে পৌঁছল যাকে তারা চিনে রেখেছিল, তখন তারা তা অস্বীকার করে বসল। অতএব, অস্বীকারকারীদের উপর আল্লাহর অভিসম্পাত।'),
  ('bn.bengali', 2, 90, 'যার বিনিময়ে তারা নিজেদের বিক্রি করেছে, তা খুবই মন্দ; যেহেতু তারা আল্লাহ যা নযিল করেছেন, তা অস্বীকার করেছে এই হঠকারিতার দরুন যে, আল্লাহ স্বীয় বান্দাদের মধ্যে যার প্রতি ইচ্ছা অনুগ্রহ নাযিল করেন। অতএব, তারা ক্রোধের উপর ক্রোধ অর্জন করেছে। আর কাফেরদের জন্য রয়েছে অপমানজনক শাস্তি।'),
  ('bn.bengali', 2, 91, 'যখন তাদেরকে বলা হয়, আল্লাহ যা পাঠিয়েছেন তা মেনে নাও, তখন তারা বলে, আমরা মানি যা আমাদের প্রতি অবর্তীণ হয়েছে। সেটি ছাড়া সবগুলোকে তারা অস্বীকার করে। অথচ এ গ্রন্থটি সত্য এবং সত্যায়ন করে ঐ গ্রন্থের যা তাদের কাছে রয়েছে। বলে দিন, তবে তোমরা ইতিপূর্বে পয়গম্বরদের হত্যা করতে কেন যদি তোমরা বিশ্বাসী ছিলে?'),
  ('bn.bengali', 2, 92, 'সুস্পষ্ট মু’জেযাসহ মূসা তোমাদের কাছে এসেছেন। এরপর তার অনুপস্থিতিতে তোমরা গোবৎস বানিয়েছ। বাস্তবিকই তোমরা অত্যাচারী।'),
  ('bn.bengali', 2, 93, 'আর যখন আমি তোমাদের কাছ থেকে প্রতিশ্রুতি নিলাম এবং তুর পর্বতকে তোমাদের উপর তুলে ধরলাম যে, শক্ত করে ধর, আমি যা তোমাদের দিয়েছি আর শোন। তারা বলল, আমরা শুনেছি আর অমান্য করেছি। কুফরের কারণে তাদের অন্তরে গোবৎসপ্রীতি পান করানো হয়েছিল। বলে দিন, তোমরা বিশ্বাসী হলে, তোমাদের সে বিশ্বাস মন্দ বিষয়াদি শিক্ষা দেয়।'),
  ('bn.bengali', 2, 94, 'বলে দিন, যদি আখেরাতের বাসস্থান আল্লাহর কাছে একমাত্র তোমাদের জন্যই বরাদ্দ হয়ে থাকে-অন্য লোকদের বাদ দিয়ে, তবে মৃত্যু কামনা কর, যদি সত্যবাদী হয়ে থাক।'),
  ('bn.bengali', 2, 95, 'কস্মিনকালেও তারা মৃত্যু কামনা করবে না ঐসব গোনাহর কারণে, যা তাদের হাত পাঠিয়ে দিয়েছে। আল্লাহ গোনাহগারদের সম্পর্কে সম্যক অবগত রয়েছেন।'),
  ('bn.bengali', 2, 96, 'আপনি তাদেরকে জীবনের প্রতি সবার চাইতে, এমনকি মুশরিকদের চাইতেও অধিক লোভী দেখবেন। তাদের প্রত্যেকে কামনা করে, যেন হাজার বছর আয়ু পায়। অথচ এরূপ আয়ু প্রাপ্তি তাদেরকে শাস্তি থেকে রক্ষা করতে পারবে না। আল্লাহ দেখেন যা কিছু তারা করে।'),
  ('bn.bengali', 2, 97, 'আপনি বলে দিন, যে কেউ জিবরাঈলের শত্রু হয়-যেহেতু তিনি আল্লাহর আদেশে এ কালাম আপনার অন্তরে নাযিল করেছেন, যা সত্যায়নকারী তাদের সম্মুখস্থ কালামের এবং মুমিনদের জন্য পথপ্রদর্শক ও সুসংবাদদাতা।'),
  ('bn.bengali', 2, 98, 'যে ব্যক্তি আল্লাহ তাঁর ফেরেশতা ও রসূলগণ এবং জিবরাঈল ও মিকাঈলের শত্রু হয়, নিশ্চিতই আল্লাহ সেসব কাফেরের শত্রু।'),
  ('bn.bengali', 2, 99, 'আমি আপনার প্রতি উজ্জ্বল নিদর্শনসমূহ অবতীর্ণ করেছি। অবাধ্যরা ব্যতীত কেউ এগুলো অস্বীকার করে না।'),
  ('bn.bengali', 2, 100, 'কি আশ্চর্য, যখন তারা কোন অঙ্গীকারে আবদ্ধ হয়, তখন তাদের একদল তা ছুঁড়ে ফেলে, বরং অধিকাংশই বিশ্বাস করে না।'),
  ('bn.bengali', 2, 101, 'যখন তাদের কাছে আল্লাহর পক্ষ থেকে একজন রসূল আগমন করলেন-যিনি ঐ কিতাবের সত্যায়ন করেন, যা তাদের কাছে রয়েছে, তখন আহলে কেতাবদের একদল আল্লাহর গ্রন্থকে পশ্চাতে নিক্ষেপ করল-যেন তারা জানেই না।'),
  ('bn.bengali', 2, 102, 'তারা ঐ শাস্ত্রের অনুসরণ করল, যা সুলায়মানের রাজত্ব কালে শয়তানরা আবৃত্তি করত। সুলায়মান কুফর করেনি; শয়তানরাই কুফর করেছিল। তারা মানুষকে জাদুবিদ্যা এবং বাবেল শহরে হারুত ও মারুত দুই ফেরেশতার প্রতি যা অবতীর্ণ হয়েছিল, তা শিক্ষা দিত। তারা উভয়ই একথা না বলে কাউকে শিক্ষা দিত না যে, আমরা পরীক্ষার জন্য; কাজেই তুমি কাফের হয়ো না। অতঃপর তারা তাদের কাছ থেকে এমন জাদু শিখত, যদ্দ্বারা স্বামী ও স্ত্রীর মধ্যে বিচ্ছেদ ঘটে। তারা আল্লাহর আদেশ ছাড়া তদ্দ্বারা কারও অনিষ্ট করতে পারত না। যা তাদের ক্ষতি করে এবং উপকার না করে, তারা তাই শিখে। তারা ভালরূপে জানে যে, যে কেউ জাদু অবলম্বন করে, তার জন্য পরকালে কোন অংশ নেই। যার বিনিময়ে তারা আত্নবিক্রয় করেছে, তা খুবই মন্দ যদি তারা জানত।'),
  ('bn.bengali', 2, 103, 'যদি তারা ঈমান আনত এবং খোদাভীরু হত, তবে আল্লাহর কাছ থেকে উত্তম প্রতিদান পেত। যদি তারা জানত।'),
  ('bn.bengali', 2, 104, 'হে মুমিন গণ, তোমরা ‘রায়িনা’ বলো না-‘উনযুরনা’ বল এবং শুনতে থাক। আর কাফেরদের জন্যে রয়েছে বেদনাদায়ক শাস্তি।'),
  ('bn.bengali', 2, 105, 'আহলে-কিতাব ও মুশরিকদের মধ্যে যারা কাফের, তাদের মনঃপুত নয় যে, তোমাদের পালনকর্তার পক্ষ থেকে তোমাদের প্রতি কোন কল্যাণ অবতীর্ণ হোক। আল্লাহ যাকে ইচ্ছা বিশেষ ভাবে স্বীয় অনুগ্রহ দান করেন। আল্লাহ মহান অনুগ্রহদাতা।'),
  ('bn.bengali', 2, 106, 'আমি কোন আয়াত রহিত করলে অথবা বিস্মৃত করিয়ে দিলে তদপেক্ষা উত্তম অথবা তার সমপর্যায়ের আয়াত আনয়ন করি। তুমি কি জান না যে, আল্লাহ সব কিছুর উপর শক্তিমান?'),
  ('bn.bengali', 2, 107, 'তুমি কি জান না যে, আল্লাহর জন্যই নভোমন্ডল ও ভূমন্ডলের আধিপত্য? আল্লাহ ব্যতীত তোমাদের কোন বন্ধু ও সাহায্যকারী নেই।'),
  ('bn.bengali', 2, 108, 'ইতিপূর্বে মূসা (আঃ) যেমন জিজ্ঞাসিত হয়েছিলেন, (মুসলমানগন, ) তোমরাও কি তোমাদের রসূলকে তেমনি প্রশ্ন করতে চাও? যে কেউ ঈমানের পরিবর্তে কুফর গ্রহন করে, সে সরল পথ থেকে বিচ্যুত হয়ে যায়।'),
  ('bn.bengali', 2, 109, 'আহলে কিতাবদের অনেকেই প্রতিহিংসাবশতঃ চায় যে, মুসলমান হওয়ার পর তোমাদেরকে কোন রকমে কাফের বানিয়ে দেয়। তাদের কাছে সত্য প্রকাশিত হওয়ার পর (তারা এটা চায়)। যাক তোমরা আল্লাহর নির্দেশ আসা পর্যন্ত তাদের ক্ষমা কর এবং উপেক্ষা কর। নিশ্চয় আল্লাহ সব কিছুর উপর ক্ষমতাবান।'),
  ('bn.bengali', 2, 110, 'তোমরা নামায প্রতিষ্ঠা কর এবং যাকাত দাও। তোমরা নিজের জন্যে পূর্বে যে সৎকর্ম প্রেরণ করবে, তা আল্লাহর কাছে পাবে। তোমরা যা কিছু কর, নিশ্চয় আল্লাহ তা প্রত্যক্ষ করেন।'),
  ('bn.bengali', 2, 111, 'ওরা বলে, ইহুদী অথবা খ্রীস্টান ব্যতীত কেউ জান্নাতে যাবে না। এটা ওদের মনের বাসনা। বলে দিন, তোমরা সত্যবাদী হলে, প্রমাণ উপস্থিত কর।'),
  ('bn.bengali', 2, 112, 'হাঁ, যে ব্যক্তি নিজেকে আল্লাহর উদ্দেশ্যে সমর্পন করেছে এবং সে সৎকর্মশীলও বটে তার জন্য তার পালনকর্তার কাছে পুরস্কার বয়েছে। তাদের ভয় নেই এবং তারা চিন্তিতও হবে না।'),
  ('bn.bengali', 2, 113, 'ইহুদীরা বলে, খ্রীস্টানরা কোন ভিত্তির উপরেই নয় এবং খ্রীস্টানরা বলে, ইহুদীরা কোন ভিত্তির উপরেই নয়। অথচ ওরা সবাই কিতাব পাঠ করে! এমনিভাবে যারা মূর্খ, তারাও ওদের মতই উক্তি করে। অতএব, আল্লাহ কেয়ামতের দিন তাদের মধ্যে ফয়সালা দেবেন, যে বিষয়ে তারা মতবিরোধ করছিল।'),
  ('bn.bengali', 2, 114, 'যে ব্যাক্তি আল্লাহর মসজিদসমূহে তাঁর নাম উচ্চারণ করতে বাধা দেয় এবং সেগুলোকে উজাড় করতে চেষ্টা করে, তার চাইতে বড় যালেম আর কে? এদের পক্ষে মসজিদসমূহে প্রবেশ করা বিধেয় নয়, অবশ্য ভীত-সন্ত্রস্ত অবস্থায়। ওদের জন্য ইহকালে লাঞ্ছনা এবং পরকালে কঠিন শাস্তি রয়েছে।'),
  ('bn.bengali', 2, 115, 'পূর্ব ও পশ্চিম আল্লারই। অতএব, তোমরা যেদিকেই মুখ ফেরাও, সেদিকেই আল্লাহ বিরাজমান। নিশ্চয় আল্লাহ সর্বব্যাপী, সর্বজ্ঞ।'),
  ('bn.bengali', 2, 116, 'তারা বলে, আল্লাহ সন্তান গ্রহণ করেছেন। তিনি তো এসব কিছু থেকে পবিত্র, বরং নভোমন্ডল ও ভূমন্ডলে যা কিছু রয়েছে সবই তার আজ্ঞাধীন।'),
  ('bn.bengali', 2, 117, 'তিনি নভোমন্ডল ও ভূমন্ডলের উদ্ভাবক। যখন তিনি কোন কার্য সম্পাদনের সিন্ধান্ত নেন, তখন সেটিকে একথাই বলেন, ‘হয়ে যাও’ তৎক্ষণাৎ তা হয়ে যায়।'),
  ('bn.bengali', 2, 118, 'যারা কিছু জানে না, তারা বলে, আল্লাহ আমাদের সঙ্গে কেন কথা বলেন না? অথবা আমাদের কাছে কোন নিদর্শন কেন আসে না? এমনি ভাবে তাদের পূর্বে যারা ছিল তারাও তাদেরই অনুরূপ কথা বলেছে। তাদের অন্তর একই রকম। নিশ্চয় আমি উজ্জ্বল নিদর্শনসমূহ বর্ণনা করেছি তাদের জন্যে যারা প্রত্যয়শীল।'),
  ('bn.bengali', 2, 119, 'নিশ্চয় আমি আপনাকে সত্যধর্মসহ সুসংবাদদাতা ও ভীতি প্রদর্শনকারীরূপে পাঠিয়েছি। আপনি দোযখবাসীদের সম্পর্কে জিজ্ঞাসিত হবেন না।'),
  ('bn.bengali', 2, 120, 'ইহুদী ও খ্রীষ্টানরা কখনই আপনার প্রতি সন্তুষ্ট হবে না, যে পর্যন্ত না আপনি তাদের ধর্মের অনুসরণ করেন। বলে দিন, যে পথ আল্লাহ প্রদর্শন করেন, তাই হল সরল পথ। যদি আপনি তাদের আকাঙ্খাসমূহের অনুসরণ করেন, ঐ জ্ঞান লাভের পর, যা আপনার কাছে পৌঁছেছে, তবে কেউ আল্লাহর কবল থেকে আপনার উদ্ধারকারী ও সাহায্যকারী নেই।'),
  ('bn.bengali', 2, 121, 'আমি যাদেরকে গ্রন্থ দান করেছি, তারা তা যথাযথভাবে পাঠ করে। তারাই তৎপ্রতি বিশ্বাস করে। আর যারা তা অবিশ্বাস করে, তারাই হবে ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 2, 122, 'হে বনী-ইসরাঈল! আমার অনুগ্রহের কথা স্মরণ কর, যা আমি তোমাদের দিয়েছি। আমি তোমাদেরকে বিশ্বাবাসীর উপর শ্রেষ্ঠত্ব দান করেছি।'),
  ('bn.bengali', 2, 123, 'তোমরা ভয় কর সেদিনকে, যে দিন এক ব্যক্তি থেকে অন্য ব্যক্তি বিন্দুমাত্র উপকৃত হবে না, কারও কাছ থেকে বিনিময় গৃহীত হবে না, কার ও সুপারিশ ফলপ্রদ হবে না এবং তারা সাহায্য প্রাপ্ত ও হবে না।'),
  ('bn.bengali', 2, 124, 'যখন ইব্রাহীমকে তাঁর পালনকর্তা কয়েকটি বিষয়ে পরীক্ষা করলেন, অতঃপর তিনি তা পূর্ণ করে দিলেন, তখন পালনকর্তা বললেন, আমি তোমাকে মানবজাতির নেতা করব। তিনি বললেন, আমার বংশধর থেকেও! তিনি বললেন আমার অঙ্গীকার অত্যাচারীদের পর্যন্ত পৌঁছাবে না।'),
  ('bn.bengali', 2, 125, 'যখন আমি কা’বা গৃহকে মানুষের জন্যে সম্মিলন স্থল ও শান্তির আলয় করলাম, আর তোমরা ইব্রাহীমের দাঁড়ানোর জায়গাকে নামাযের জায়গা বানাও এবং আমি ইব্রাহীম ও ইসমাঈলকে আদেশ করলাম, তোমরা আমার গৃহকে তওয়াফকারী, অবস্থানকারী ও রুকু-সেজদাকারীদের জন্য পবিত্র রাখ।'),
  ('bn.bengali', 2, 126, 'যখন ইব্রাহীম বললেন, পরওয়ারদেগার! এ স্থানকে তুমি শান্তিধান কর এবং এর অধিবাসীদের মধ্যে যারা অল্লাহ ও কিয়ামতে বিশ্বাস করে, তাদেরকে ফলের দ্বারা রিযিক দান কর। বললেনঃ যারা অবিশ্বাস করে, আমি তাদেরও কিছুদিন ফায়দা ভোগ করার সুযোগ দেব, অতঃপর তাদেরকে বলপ্রয়োগে দোযখের আযাবে ঠেলে দেবো; সেটা নিকৃষ্ট বাসস্থান।'),
  ('bn.bengali', 2, 127, 'স্মরণ কর, যখন ইব্রাহীম ও ইসমাঈল কা’বাগৃহের ভিত্তি স্থাপন করছিল। তারা দোয়া করেছিলঃ পরওয়ারদেগার! আমাদের থেকে কবুল কর। নিশ্চয়ই তুমি শ্রবণকারী, সর্বজ্ঞ।'),
  ('bn.bengali', 2, 128, 'পরওয়ারদেগার! আমাদের উভয়কে তোমার আজ্ঞাবহ কর এবং আমাদের বংশধর থেকেও একটি অনুগত দল সৃষ্টি কর, আমাদের হজ্বের রীতিনীতি বলে দাও এবং আমাদের ক্ষমা কর। নিশ্চয় তুমি তওবা কবুলকারী। দয়ালু।'),
  ('bn.bengali', 2, 129, 'হে পরওয়ারদেগার! তাদের মধ্যে থেকেই তাদের নিকট একজন পয়গম্বর প্রেরণ করুণ যিনি তাদের কাছে তোমার আয়াতসমূহ তেলাওয়াত করবেন, তাদেরকে কিতাব ও হেকমত শিক্ষা দিবেন। এবং তাদের পবিত্র করবেন। নিশ্চয় তুমিই পরাক্রমশালী হেকমতওয়ালা।'),
  ('bn.bengali', 2, 130, 'ইব্রাহীমের ধর্ম থেকে কে মুখ ফেরায়? কিন্তু সে ব্যক্তি, যে নিজেকে বোকা প্রতিপন্ন করে। নিশ্চয়ই আমি তাকে পৃথিবীতে মনোনীত করেছি এবং সে পরকালে সৎকর্মশীলদের অন্তর্ভুক্ত।'),
  ('bn.bengali', 2, 131, 'স্মরণ কর, যখন তাকে তার পালনকর্তা বললেনঃ অনুগত হও। সে বললঃ আমি বিশ্বপালকের অনুগত হলাম।'),
  ('bn.bengali', 2, 132, 'এরই ওছিয়ত করেছে ইব্রাহীম তার সন্তানদের এবং ইয়াকুবও যে, হে আমার সন্তানগণ, নিশ্চয় আল্লাহ তোমাদের জন্য এ ধর্মকে মনোনীত করেছেন। কাজেই তোমরা মুসলমান না হয়ে কখনও মৃত্যুবরণ করো না।'),
  ('bn.bengali', 2, 133, 'তোমরা কি উপস্থিত ছিলে, যখন ইয়াকুবের মৃত্যু নিকটবর্তী হয়? যখন সে সন্তানদের বললঃ আমার পর তোমরা কার এবাদত করবে? তারা বললো, আমরা তোমার পিতৃ-পুরুষ ইব্রাহীম, ইসমাঈল ও ইসহাকের উপাস্যের এবাদত করব। তিনি একক উপাস্য।'),
  ('bn.bengali', 2, 134, 'আমরা সবাই তাঁর আজ্ঞাবহ। তারা ছিল এক সম্প্রদায়-যারা গত হয়ে গেছে। তারা যা করেছে, তা তাদেরই জন্যে। তারা কি করত, সে সম্পর্কে তোমরা জিজ্ঞাসিত হবে না।'),
  ('bn.bengali', 2, 135, 'তারা বলে, তোমরা ইহুদী অথবা খ্রীষ্টান হয়ে যাও, তবেই সুপথ পাবে। আপনি বলুন, কখনই নয়; বরং আমরা ইব্রাহীমের ধর্মে আছি যাতে বক্রতা নেই। সে মুশরিকদের অন্তর্ভুক্ত ছিল না।'),
  ('bn.bengali', 2, 136, 'তোমরা বল, আমরা ঈমান এনেছি আল্লাহর উপর এবং যা অবতীর্ণ হয়েছে আমাদের প্রতি এবং যা অবতীর্ণ হয়েছে ইব্রাহীম, ইসমাঈল, ইসহাক, ইয়াকুব এবং তদীয় বংশধরের প্রতি এবং মূসা, ঈসা, অন্যান্য নবীকে পালনকর্তার পক্ষ থেকে যা দান করা হয়েছে, তৎসমুদয়ের উপর। আমরা তাদের মধ্যে পার্থক্য করি না। আমরা তাঁরই আনুগত্যকারী।'),
  ('bn.bengali', 2, 137, 'অতএব তারা যদি ঈমান আনে, তোমাদের ঈমান আনার মত, তবে তারা সুপথ পাবে। আর যদি মুখ ফিরিয়ে নেয়, তবে তারাই হঠকারিতায় রয়েছে। সুতরাং এখন তাদের জন্যে আপনার পক্ষ থেকে আল্লাহই যথেষ্ট। তিনিই শ্রবণকারী, মহাজ্ঞানী।'),
  ('bn.bengali', 2, 138, 'আমরা আল্লাহর রং গ্রহণ করেছি। আল্লাহর রং এর চাইতে উত্তম রং আর কার হতে পারে?আমরা তাঁরই এবাদত করি।'),
  ('bn.bengali', 2, 139, 'আপনি বলে দিন, তোমরা কি আমাদের সাথে আল্লাহ সম্পর্কে তর্ক করছ? অথচ তিনিই আমাদের পালনকর্তা এবং তোমাদের ও পালনকর্তা। আমাদের জন্যে আমাদের কর্ম তোমাদের জন্যে তোমাদের কর্ম। এবং আমরা তাঁরই প্রতি একনিষ্ঠ।'),
  ('bn.bengali', 2, 140, 'অথবা তোমরা কি বলছ যে, নিশ্চয়ই ইব্রাহীম, ইসমাঈল, ইসহাক, ইয়াকুব (আঃ) ও তাদের সন্তানগন ইহুদী অথবা খ্রীষ্টান ছিলেন? আপনি বলে দিন, তোমরা বেশী জান, না আল্লাহ বেশী জানেন?'),
  ('bn.bengali', 2, 141, 'তার চাইতে অত্যাচারী কে, যে আল্লাহর পক্ষ থেকে তার কাছে প্রমাণিত সাক্ষ্যকে গোপন করে? আল্লাহ তোমাদের কর্ম সম্পর্কে বেখবর নন। সে সম্প্রদায় অতীত হয়ে গেছে। তারা যা করেছে, তা তাদের জন্যে এবং তোমরা যা করছ, তা তোমাদের জন্যে। তাদের কর্ম সম্পর্কে তোমাদের জিজ্ঞেস করা হবে না।'),
  ('bn.bengali', 2, 142, 'এখন নির্বোধেরা বলবে, কিসে মুসলমানদের ফিরিয়ে দিল তাদের ঐ কেবলা থেকে, যার উপর তারা ছিল? আপনি বলুনঃ পূর্ব ও পশ্চিম আল্লাহরই। তিনি যাকে ইচ্ছা সরল পথে চালান।'),
  ('bn.bengali', 2, 143, 'এমনিভাবে আমি তোমাদেরকে মধ্যপন্থী সম্প্রদায় করেছি যাতে করে তোমরা সাক্ষ্যদাতা হও মানবমন্ডলীর জন্যে এবং যাতে রসূল সাক্ষ্যদাতা হন তোমাদের জন্য। আপনি যে কেবলার উপর ছিলেন, তাকে আমি এজন্যই কেবলা করেছিলাম, যাতে একথা প্রতীয়মান হয় যে, কে রসূলের অনুসারী থাকে আর কে পিঠটান দেয়। নিশ্চিতই এটা কঠোরতর বিষয়, কিন্তু তাদের জন্যে নয়, যাদেরকে আল্লাহ পথপ্রদর্শন করেছেন। আল্লাহ এমন নন যে, তোমাদের ঈমান নষ্ট করে দেবেন। নিশ্চয়ই আল্লাহ, মানুষের প্রতি অত্যন্ত স্নেহশীল, করুনাময়।'),
  ('bn.bengali', 2, 144, 'নিশ্চয়ই আমি আপনাকে বার বার আকাশের দিকে তাকাতে দেখি। অতএব, অবশ্যই আমি আপনাকে সে কেবলার দিকেই ঘুরিয়ে দেব যাকে আপনি পছন্দ করেন। এখন আপনি মসজিদুল-হারামের দিকে মুখ করুন এবং তোমরা যেখানেই থাক, সেদিকে মুখ কর। যারা আহলে-কিতাব, তারা অবশ্যই জানে যে, এটাই ঠিক পালনকর্তার পক্ষ থেকে। আল্লাহ বেখবর নন, সে সমস্ত কর্ম সম্পর্কে যা তারা করে।'),
  ('bn.bengali', 2, 145, 'যদি আপনি আহলে কিতাবদের কাছে সমুদয় নিদর্শন উপস্থাপন করেন, তবুও তারা আপনার কেবলা মেনে নেবে না এবং আপনিও তাদের কেবলা মানেন না। তারাও একে অন্যের কেবলা মানে না। যদি আপনি তাদের বাসনার অনুসরণ করেন, সে জ্ঞানলাভের পর, যা আপনার কাছে পৌঁছেছে, তবে নিশ্চয় আপনি অবিচারকারীদের অন্তর্ভুক্ত হবেন।'),
  ('bn.bengali', 2, 146, 'আমি যাদেরকে কিতাব দান করেছি, তারা তাকে চেনে, যেমন করে চেনে নিজেদের পুত্রদেরকে। আর নিশ্চয়ই তাদের একটি সম্প্রদায় জেনে শুনে সত্যকে গোপন করে।'),
  ('bn.bengali', 2, 147, 'বাস্তব সত্য সেটাই যা তোমার পালনকর্তা বলেন। কাজেই তুমি সন্দিহান হয়ো না।'),
  ('bn.bengali', 2, 148, 'আর সবার জন্যই রয়েছে কেবলা একেক দিকে, যে দিকে সে মুখ করে (এবাদত করবে)। কাজেই সৎকাজে প্রতিযোগিতামূলকভাবে এগিয়ে যাও। যেখানেই তোমরা থাকবে, আল্লাহ অবশ্যই তোমাদেরকে সমবেত করবেন। নিশ্চয়ই আল্লাহ সর্ব বিষয়ে ক্ষমতাশীল।'),
  ('bn.bengali', 2, 149, 'আর যে স্থান থেকে তুমি বের হও, নিজের মুখ মসজিদে হারামের দিকে ফেরাও-নিঃসন্দেহে এটাই হলো তোমার পালনকর্তার পক্ষ থেকে নির্ধারিত বাস্তব সত্য। বস্তুতঃ তোমার পালনকর্তা তোমাদের কার্যকলাপ সম্পর্কে অনবহিত নন।'),
  ('bn.bengali', 2, 150, 'আর তোমরা যেখান থেকেই বেরিয়ে আস এবং যেখানেই অবস্থান কর, সেদিকেই মুখ ফেরাও, যাতে করে মানুষের জন্য তোমাদের সাথে ঝগড়া করার অবকাশ না থাকে। অবশ্য যারা অবিবেচক, তাদের কথা আলাদা। কাজেই তাদের আপত্তিতে ভীত হয়ো না। আমাকেই ভয় কর। যাতে আমি তোমাদের জন্যে আমার অনুগ্রহ সমূহ পূর্ণ করে দেই এবং তাতে যেন তোমরা সরলপথ প্রাপ্ত হও।'),
  ('bn.bengali', 2, 151, 'যেমন, আমি পাঠিয়েছি তোমাদেরই মধ্য থেকে তোমাদের জন্যে একজন রসূল, যিনি তোমাদের নিকট আমার বাণীসমুহ পাঠ করবেন এবং তোমাদের পবিত্র করবেন; আর তোমাদের শিক্ষা দেবেন কিতাব ও তাঁর তত্ত্বজ্ঞান এবং শিক্ষা দেবেন এমন বিষয় যা কখনো তোমরা জানতে না।'),
  ('bn.bengali', 2, 152, 'সুতরাং তোমরা আমাকে স্মরণ কর, আমিও তোমাদের স্মরণ রাখবো এবং আমার কৃতজ্ঞতা প্রকাশ কর; অকৃতজ্ঞ হয়ো না।'),
  ('bn.bengali', 2, 153, 'হে মুমিন গন! তোমরা ধৈর্য্য ও নামাযের মাধ্যমে সাহায্য প্রার্থনা কর। নিশ্চিতই আল্লাহ ধৈর্য্যশীলদের সাথে রয়েছেন।'),
  ('bn.bengali', 2, 154, 'আর যারা আল্লাহর রাস্তায় নিহত হয়, তাদের মৃত বলো না। বরং তারা জীবিত, কিন্তু তোমরা তা বুঝ না।'),
  ('bn.bengali', 2, 155, 'এবং অবশ্যই আমি তোমাদিগকে পরীক্ষা করব কিছুটা ভয়, ক্ষুধা, মাল ও জানের ক্ষতি ও ফল-ফসল বিনষ্টের মাধ্যমে। তবে সুসংবাদ দাও সবরকারীদের।'),
  ('bn.bengali', 2, 156, 'যখন তারা বিপদে পতিত হয়, তখন বলে, নিশ্চয় আমরা সবাই আল্লাহর জন্য এবং আমরা সবাই তাঁরই সান্নিধ্যে ফিরে যাবো।'),
  ('bn.bengali', 2, 157, 'তারা সে সমস্ত লোক, যাদের প্রতি আল্লাহর অফুরন্ত অনুগ্রহ ও রহমত রয়েছে এবং এসব লোকই হেদায়েত প্রাপ্ত।'),
  ('bn.bengali', 2, 158, 'নিঃসন্দেহে সাফা ও মারওয়া আল্লাহ তা’আলার নিদর্শন গুলোর অন্যতম। সুতরাং যারা কা’বা ঘরে হজ্ব বা ওমরাহ পালন করে, তাদের পক্ষে এ দুটিতে প্রদক্ষিণ করাতে কোন দোষ নেই। বরং কেউ যদি স্বেচ্ছায় কিছু নেকীর কাজ করে, তবে আল্লাহ তা’আলার অবশ্যই তা অবগত হবেন এবং তার সে আমলের সঠিক মুল্য দেবেন।'),
  ('bn.bengali', 2, 159, 'নিশ্চয় যারা গোপন করে, আমি যেসব বিস্তারিত তথ্য এবং হেদায়েতের কথা নাযিল করেছি মানুষের জন্য কিতাবের মধ্যে বিস্তারিত বর্ণনা করার পরও; সে সমস্ত লোকের প্রতিই আল্লাহর অভিসম্পাত এবং অন্যান্য অভিসম্পাতকারীগণের ও।'),
  ('bn.bengali', 2, 160, 'তবে যারা তওবা করে এবং বর্ণিত তথ্যাদির সংশোধন করে মানুষের কাছে তা বর্ণনা করে দেয়, সে সমস্ত লোকের তওবা আমি কবুল করি এবং আমি তওবা কবুলকারী পরম দয়ালু।'),
  ('bn.bengali', 2, 161, 'নিশ্চয় যারা কুফরী করে এবং কাফের অবস্থায়ই মৃত্যুবরণ করে, সে সমস্ত লোকের প্রতি আল্লাহর ফেরেশতাগনের এবং সমগ্র মানুষের লা’নত।'),
  ('bn.bengali', 2, 162, 'এরা চিরকাল এ লা’নতের মাঝেই থাকবে। তাদের উপর থেকে আযাব কখনও হালকা করা হবে না বরং এরা বিরাম ও পাবে না।'),
  ('bn.bengali', 2, 163, 'আর তোমাদের উপাস্য একইমাত্র উপাস্য। তিনি ছাড়া মহা করুণাময় দয়ালু কেউ নেই।'),
  ('bn.bengali', 2, 164, 'নিশ্চয়ই আসমান ও যমীনের সৃষ্টিতে, রাত ও দিনের বিবর্তনে এবং নদীতে নৌকাসমূহের চলাচলে মানুষের জন্য কল্যাণ রয়েছে। আর আল্লাহ তা’ আলা আকাশ থেকে যে পানি নাযিল করেছেন, তদ্দ্বারা মৃত যমীনকে সজীব করে তুলেছেন এবং তাতে ছড়িয়ে দিয়েছেন সবরকম জীব-জন্তু। আর আবহাওয়া পরিবর্তনে এবং মেঘমালার যা তাঁরই হুকুমের অধীনে আসমান ও যমীনের মাঝে বিচরণ করে, নিশ্চয়ই সে সমস্ত বিষয়ের মাঝে নিদর্শন রয়েছে বুদ্ধিমান সম্প্রদায়ের জন্যে।'),
  ('bn.bengali', 2, 165, 'আর কোন লোক এমনও রয়েছে যারা অন্যান্যকে আল্লাহর সমকক্ষ সাব্যস্ত করে এবং তাদের প্রতি তেমনি ভালবাসা পোষণ করে, যেমন আল্লাহর প্রতি ভালবাসা হয়ে থাকে। কিন্তু যারা আল্লাহর প্রতি ঈমানদার তাদের ভালবাসা ওদের তুলনায় বহুগুণ বেশী। আর কতইনা উত্তম হ’ত যদি এ জালেমরা পার্থিব কোন কোন আযাব প্রত্যক্ষ করেই উপলব্ধি করে নিত যে, যাবতীয় ক্ষমতা শুধুমাত্র আল্লাহরই জন্য এবং আল্লাহর আযাবই সবচেয়ে কঠিনতর।'),
  ('bn.bengali', 2, 166, 'অনুসৃতরা যখন অনুসরণকারীদের প্রতি অসন্তুষ্ট হয়ে যাবে এবং যখন আযাব প্রত্যক্ষ করবে আর বিচ্ছিন্ন হয়ে যাবে তাদের পারস্পরিক সমস্ত সম্পর্ক।'),
  ('bn.bengali', 2, 167, 'এবং অনুসারীরা বলবে, কতইনা ভাল হত, যদি আমাদিগকে পৃথিবীতে ফিরে যাবার সুযোগ দেয়া হত। তাহলে আমরাও তাদের প্রতি তেমনি অসন্তুষ্ট হয়ে যেতাম, যেমন তারা অসন্তুষ্ট হয়েছে আমাদের প্রতি। এভাবেই আল্লাহ তা’আলা তাদেরকে দেখাবেন তাদের কৃতকর্ম তাদেরকে অনুতপ্ত করার জন্যে। অথচ, তারা কস্মিনকালেও আগুন থেকে বের হতে পারবে না।'),
  ('bn.bengali', 2, 168, 'হে মানব মন্ডলী, পৃথিবীর হালাল ও পবিত্র বস্তু-সামগ্রী ভক্ষন কর। আর শয়তানের পদাঙ্ক অনুসরণ করো না। সে নিঃসন্দেহে তোমাদের প্রকাশ্য শত্রু।'),
  ('bn.bengali', 2, 169, 'সে তো এ নির্দেশই তোমাদিগকে দেবে যে, তোমরা অন্যায় ও অশ্লীল কাজ করতে থাক এবং আল্লাহর প্রতি এমন সব বিষয়ে মিথ্যারোপ কর যা তোমরা জান না।'),
  ('bn.bengali', 2, 170, 'আর যখন তাদেরকে কেউ বলে যে, সে হুকুমেরই আনুগত্য কর যা আল্লাহ তা’আলা নাযিল করেছেন, তখন তারা বলে কখনো না, আমরা তো সে বিষয়েরই অনুসরণ করব। যাতে আমরা আমাদের বাপ-দাদাদেরকে দেখেছি। যদি ও তাদের বাপ দাদারা কিছুই জানতো না, জানতো না সরল পথও।'),
  ('bn.bengali', 2, 171, 'বস্তুতঃ এহেন কাফেরদের উদাহরণ এমন, যেন কেউ এমন কোন জীবকে আহবান করছে যা কোন কিছুই শোনে না, হাঁক-ডাক আর চিৎকার ছাড়া বধির মুক, এবং অন্ধ। সুতরাং তারা কিছুই বোঝে না।'),
  ('bn.bengali', 2, 172, 'হে ঈমানদারগণ, তোমরা পবিত্র বস্তু সামগ্রী আহার কর, যেগুলো আমি তোমাদেরকে রুযী হিসাবে দান করেছি এবং শুকরিয়া আদায় কর আল্লাহর, যদি তোমরা তাঁরই বন্দেগী কর।'),
  ('bn.bengali', 2, 173, 'তিনি তোমাদের উপর হারাম করেছেন, মৃত জীব, রক্ত, শুকর মাংস এবং সেসব জীব-জন্তু যা আল্লাহ ব্যাতীত অপর কারো নামে উৎসর্গ করা হয়। অবশ্য যে লোক অনন্যোপায় হয়ে পড়ে এবং নাফরমানী ও সীমালঙ্ঘনকারী না হয়, তার জন্য কোন পাপ নেই। নিঃসন্দেহে আল্লাহ মহান ক্ষমাশীল, অত্যন্ত দয়ালু।'),
  ('bn.bengali', 2, 174, 'নিশ্চয় যারা সেসব বিষয় গোপন করে, যা আল্লাহ কিতাবে নাযিল করেছেন এবং সেজন্য অল্প মূল্য গ্রহণ করে, তারা আগুন ছাড়া নিজের পেটে আর কিছুই ঢুকায় না। আর আল্লাহ কেয়ামতের দিন তাদের সাথে না কথা বলবেন, না তাদের পবিত্র করা হবে, বস্তুতঃ তাদের জন্যে রয়েছে বেদনাদায়ক আযাব।'),
  ('bn.bengali', 2, 175, 'এরাই হল সে সমস্ত লোক, যারা হেদায়েতের বিনিময়ে গোমরাহী খরিদ করেছে এবং (খরিদ করেছে) ক্ষমা ও অনুগ্রহের বিনিময়ে আযাব। অতএব, তারা দোযখের উপর কেমন ধৈর্য্য ধারণকারী।'),
  ('bn.bengali', 2, 176, 'আর এটা এজন্যে যে, আল্লাহ নাযিল করেছেন সত্যপূর্ণ কিতাব। আর যারা কেতাবের মাঝে মতবিরোধ সৃষ্টি করেছে নিশ্চয়ই তারা জেদের বশবর্তী হয়ে অনেক দূরে চলে গেছে।'),
  ('bn.bengali', 2, 177, 'সৎকর্ম শুধু এই নয় যে, পূর্ব কিংবা পশ্চিমদিকে মুখ করবে, বরং বড় সৎকাজ হল এই যে, ঈমান আনবে আল্লাহর উপর কিয়ামত দিবসের উপর, ফেরেশতাদের উপর এবং সমস্ত নবী-রসূলগণের উপর, আর সম্পদ ব্যয় করবে তাঁরই মহব্বতে আত্নীয়-স্বজন, এতীম-মিসকীন, মুসাফির-ভিক্ষুক ও মুক্তিকামী ক্রীতদাসদের জন্যে। আর যারা নামায প্রতিষ্ঠা করে, যাকাত দান করে এবং যারা কৃত প্রতিজ্ঞা সম্পাদনকারী এবং অভাবে, রোগে-শোকে ও যুদ্ধের সময় ধৈর্য্য ধারণকারী তারাই হল সত্যাশ্রয়ী, আর তারাই পরহেযগার।'),
  ('bn.bengali', 2, 178, 'হে ঈমানদারগন! তোমাদের প্রতি নিহতদের ব্যাপারে কেসাস গ্রহণ করা বিধিবদ্ধ করা হয়েছে। স্বাধীন ব্যক্তি স্বাধীন ব্যক্তির বদলায়, দাস দাসের বদলায় এবং নারী নারীর বদলায়। অতঃপর তার ভাইয়ের তরফ থেকে যদি কাউকে কিছুটা মাফ করে দেয়া হয়, তবে প্রচলিত নিয়মের অনুসরণ করবে এবং ভালভাবে তাকে তা প্রদান করতে হবে। এটা তোমাদের পালনকর্তার তরফ থেকে সহজ এবং বিশেষ অনুগ্রহ। এরপরও যে ব্যাক্তি বাড়াবাড়ি করে, তার জন্য রয়েছে বেদনাদায়ক আযাব।'),
  ('bn.bengali', 2, 179, 'হে বুদ্ধিমানগণ! কেসাসের মধ্যে তোমাদের জন্যে জীবন রয়েছে, যাতে তোমরা সাবধান হতে পার।'),
  ('bn.bengali', 2, 180, 'তোমাদের কারো যখন মৃত্যুর সময় উপস্থিত হয়, সে যদি কিছু ধন-সম্পদ ত্যাগ করে যায়, তবে তার জন্য ওসীয়ত করা বিধিবদ্ধ করা হলো, পিতা-মাতা ও নিকটাত্নীয়দের জন্য ইনসাফের সাথে পরহেযগারদের জন্য এ নির্দেশ জরুরী। নিশ্চয় আল্লাহ তা’আলা সবকিছু শোনেন ও জানেন।'),
  ('bn.bengali', 2, 181, 'যদি কেউ ওসীয়ত শোনার পর তাতে কোন রকম পরিবর্তন সাধন করে, তবে যারা পরিবর্তন করে তাদের উপর এর পাপ পতিত হবে।'),
  ('bn.bengali', 2, 182, 'যদি কেউ ওসীয়তকারীর পক্ষ থেকে আশংকা করে পক্ষপাতিত্বের অথবা কোন অপরাধমূলক সিদ্ধান্তের এবং তাদের মধ্যে মীমাংসা করে দেয়, তবে তার কোন গোনাহ হবে না। নিশ্চয় আল্লাহ তা’আলা ক্ষমাশীল, অতি দয়ালু।'),
  ('bn.bengali', 2, 183, 'হে ঈমানদারগণ! তোমাদের উপর রোজা ফরয করা হয়েছে, যেরূপ ফরজ করা হয়েছিল তোমাদের পূর্ববর্তী লোকদের উপর, যেন তোমরা পরহেযগারী অর্জন করতে পার।'),
  ('bn.bengali', 2, 184, 'গণনার কয়েকটি দিনের জন্য অতঃপর তোমাদের মধ্যে যে, অসুখ থাকবে অথবা সফরে থাকবে, তার পক্ষে অন্য সময়ে সে রোজা পূরণ করে নিতে হবে। আর এটি যাদের জন্য অত্যন্ত কষ্ট দায়ক হয়, তারা এর পরিবর্তে একজন মিসকীনকে খাদ্যদান করবে। যে ব্যক্তি খুশীর সাথে সৎকর্ম করে, তা তার জন্য কল্যাণ কর হয়। আর যদি রোজা রাখ, তবে তোমাদের জন্যে বিশেষ কল্যাণকর, যদি তোমরা তা বুঝতে পার।'),
  ('bn.bengali', 2, 185, 'রমযান মাসই হল সে মাস, যাতে নাযিল করা হয়েছে কোরআন, যা মানুষের জন্য হেদায়েত এবং সত্যপথ যাত্রীদের জন্য সুষ্পষ্ট পথ নির্দেশ আর ন্যায় ও অন্যায়ের মাঝে পার্থক্য বিধানকারী। কাজেই তোমাদের মধ্যে যে লোক এ মাসটি পাবে, সে এ মাসের রোযা রাখবে। আর যে লোক অসুস্থ কিংবা মুসাফির অবস্থায় থাকবে সে অন্য দিনে গণনা পূরণ করবে। আল্লাহ তোমাদের জন্য সহজ করতে চান; তোমাদের জন্য জটিলতা কামনা করেন না যাতে তোমরা গণনা পূরণ কর এবং তোমাদের হেদায়েত দান করার দরুন আল্লাহ তা’আলার মহত্ত্ব বর্ণনা কর, যাতে তোমরা কৃতজ্ঞতা স্বীকার কর।'),
  ('bn.bengali', 2, 186, 'আর আমার বান্দারা যখন তোমার কাছে জিজ্ঞেস করে আমার ব্যাপারে বস্তুতঃ আমি রয়েছি সন্নিকটে। যারা প্রার্থনা করে, তাদের প্রার্থনা কবুল করে নেই, যখন আমার কাছে প্রার্থনা করে। কাজেই আমার হুকুম মান্য করা এবং আমার প্রতি নিঃসংশয়ে বিশ্বাস করা তাদের একান্ত কর্তব্য। যাতে তারা সৎপথে আসতে পারে।'),
  ('bn.bengali', 2, 187, 'রোযার রাতে তোমাদের স্ত্রীদের সাথে সহবাস করা তোমাদের জন্য হালাল করা হয়েছে। তারা তোমাদের পরিচ্ছদ এবং তোমরা তাদের পরিচ্ছদ। আল্লাহ অবগত রয়েছেন যে, তোমরা আত্নপ্রতারণা করছিলে, সুতরাং তিনি তোমাদেরকে ক্ষমা করেছেন এবং তোমাদের অব্যাহতি দিয়েছেন। অতঃপর তোমরা নিজেদের স্ত্রীদের সাথে সহবাস কর এবং যা কিছু তোমাদের জন্য আল্লাহ দান করেছেন, তা আহরন কর। আর পানাহার কর যতক্ষণ না কাল রেখা থেকে ভোরের শুভ্র রেখা পরিষ্কার দেখা যায়। অতঃপর রোযা পূর্ণ কর রাত পর্যন্ত। আর যতক্ষণ তোমরা এতেকাফ অবস্থায় মসজিদে অবস্থান কর, ততক্ষণ পর্যন্ত স্ত্রীদের সাথে মিশো না। এই হলো আল্লাহ কর্তৃক বেঁধে দেয়া সীমানা। অতএব, এর কাছেও যেও না। এমনিভাবে বর্ণনা করেন আল্লাহ নিজের আয়াত সমূহ মানুষের জন্য, যাতে তারা বাঁচতে পারে।'),
  ('bn.bengali', 2, 188, 'তোমরা অন্যায়ভাবে একে অপরের সম্পদ ভোগ করো না। এবং জনগণের সম্পদের কিয়দংশ জেনে-শুনে পাপ পন্থায় আত্নসাৎ করার উদ্দেশে শাসন কতৃপক্ষের হাতেও তুলে দিও না।'),
  ('bn.bengali', 2, 189, 'তোমার নিকট তারা জিজ্ঞেস করে নতুন চাঁদের বিষয়ে। বলে দাও যে এটি মানুষের জন্য সময় নির্ধারণ এবং হজ্বের সময় ঠিক করার মাধ্যম। আর পেছনের দিক দিয়ে ঘরে প্রবেশ করার মধ্যে কোন নেকী বা কল্যাণ নেই। অবশ্য নেকী হল আল্লাহকে ভয় করার মধ্যে। আর তোমরা ঘরে প্রবেশ কর দরজা দিয়ে এবং আল্লাহকে ভয় করতে থাক যাতে তোমরা নিজেদের বাসনায় কৃতকার্য হতে পার।'),
  ('bn.bengali', 2, 190, 'আর লড়াই কর আল্লাহর ওয়াস্তে তাদের সাথে, যারা লড়াই করে তোমাদের সাথে। অবশ্য কারো প্রতি বাড়াবাড়ি করো না। নিশ্চয়ই আল্লাহ সীমালঙ্ঘনকারীদেরকে পছন্দ করেন না।'),
  ('bn.bengali', 2, 191, 'আর তাদেরকে হত্যাকর যেখানে পাও সেখানেই এবং তাদেরকে বের করে দাও সেখান থেকে যেখান থেকে তারা বের করেছে তোমাদেরকে। বস্তুতঃ ফেতনা ফ্যাসাদ বা দাঙ্গা-হাঙ্গামা সৃষ্টি করা হত্যার চেয়েও কঠিন অপরাধ। আর তাদের সাথে লড়াই করো না মসজিদুল হারামের নিকটে যতক্ষণ না তারা তোমাদের সাথে সেখানে লড়াই করে। অবশ্য যদি তারা নিজেরাই তোমাদের সাথে লড়াই করে। তাহলে তাদেরকে হত্যা কর। এই হল কাফেরদের শাস্তি।'),
  ('bn.bengali', 2, 192, 'আর তারা যদি বিরত থাকে, তাহলে আল্লাহ অত্যন্ত দয়ালু।'),
  ('bn.bengali', 2, 193, 'আর তোমরা তাদের সাথে লড়াই কর, যে পর্যন্ত না ফেতনার অবসান হয় এবং আল্লাহর দ্বীন প্রতিষ্ঠিত হয়। অতঃপর যদি তারা নিবৃত হয়ে যায় তাহলে কারো প্রতি কোন জবরদস্তি নেই, কিন্তু যারা যালেম (তাদের ব্যাপারে আলাদা)।'),
  ('bn.bengali', 2, 194, 'সম্মানিত মাসই সম্মানিত মাসের বদলা। আর সম্মান রক্ষা করারও বদলা রয়েছে। বস্তুতঃ যারা তোমাদের উপর জবর দস্তি করেছে, তোমরা তাদের উপর জবরদস্তি কর, যেমন জবরদস্তি তারা করেছে তোমাদের উপর। আর তোমরা আল্লাহকে ভয় কর এবং জেনে রাখ, যারা পরহেযগার, আল্লাহ তাদের সাথে রয়েছেন।'),
  ('bn.bengali', 2, 195, 'আর ব্যয় কর আল্লাহর পথে, তবে নিজের জীবনকে ধ্বংসের সম্মুখীন করো না। আর মানুষের প্রতি অনুগ্রহ কর। আল্লাহ অনুগ্রহকারীদেরকে ভালবাসেন।'),
  ('bn.bengali', 2, 196, 'আর তোমরা আল্লাহর উদ্দেশ্যে হজ্জ্ব ওমরাহ পরিপূর্ণ ভাবে পালন কর। যদি তোমরা বাধা প্রাপ্ত হও, তাহলে কোরবানীর জন্য যাকিছু সহজলভ্য, তাই তোমাদের উপর ধার্য। আর তোমরা ততক্ষণ পর্যন্ত মাথা মুন্ডন করবে না, যতক্ষণ না কোরবাণী যথাস্থানে পৌছে যাবে। যারা তোমাদের মধ্যে অসুস্থ হয়ে পড়বে কিংবা মাথায় যদি কোন কষ্ট থাকে, তাহলে তার পরিবর্তে রোজা করবে কিংবা খয়রাত দেবে অথবা কুরবানী করবে। আর তোমাদের মধ্যে যারা হজ্জ্ব ওমরাহ একত্রে একই সাথে পালন করতে চাও, তবে যাকিছু সহজলভ্য, তা দিয়ে কুরবানী করাই তার উপর কর্তব্য। বস্তুতঃ যারা কোরবানীর পশু পাবে না, তারা হজ্জ্বের দিনগুলোর মধ্যে রোজা রাখবে তিনটি আর সাতটি রোযা রাখবে ফিরে যাবার পর। এভাবে দশটি রোযা পূর্ণ হয়ে যাবে। এ নির্দেশটি তাদের জন্য, যাদের পরিবার পরিজন মসজিদুল হারামের আশে-পাশে বসবাস করে না। আর আল্লাহকে ভয় করতে থাক। সন্দেহাতীতভাবে জেনো যে, আল্লাহর আযাব বড়ই কঠিন।'),
  ('bn.bengali', 2, 197, 'হজ্জ্বে কয়েকটি মাস আছে সুবিদিত। এসব মাসে যে লোক হজ্জ্বের পরিপূর্ণ নিয়ত করবে, তার পক্ষে স্ত্রীও সাথে নিরাভরণ হওয়া জায়েজ নয়। না অশোভন কোন কাজ করা, না ঝাগড়া-বিবাদ করা হজ্জ্বের সেই সময় জায়েজ নয়। আর তোমরা যাকিছু সৎকাজ কর, আল্লাহ তো জানেন। আর তোমরা পাথেয় সাথে নিয়ে নাও। নিঃসন্দেহে সর্বোত্তম পাথেয় হচ্ছে আল্লাহর ভয়। আর আমাকে ভয় করতে থাক, হে বুদ্ধিমানগন! তোমাদের উপর তোমাদের পালনকর্তার অনুগ্রহ অন্বেষণ করায় কোন পাপ নেই।'),
  ('bn.bengali', 2, 198, 'তোমাদের উপর তোমাদের পালনকর্তার অনুগ্রহ অন্বেষন করায় কোন পাপ নেই। অতঃপর যখন তওয়াফের জন্য ফিরে আসবে আরাফাত থেকে, তখন মাশ‘ আরে-হারামের নিকটে আল্লাহকে স্মরণ কর। আর তাঁকে স্মরণ কর তেমনি করে, যেমন তোমাদিগকে হেদায়েত করা হয়েছে। আর নিশ্চয়ই ইতিপূর্বে তোমরা ছিলে অজ্ঞ।'),
  ('bn.bengali', 2, 199, 'অতঃপর তওয়াফের জন্যে দ্রুতগতিতে সেখান থেকে ফিরে আস, যেখান থেকে সবাই ফিরে। আর আল্লাহর কাছেই মাগফেরাত কামনা কর। নিশ্চয়ই আল্লাহ ক্ষমাকারী, করুনাময়।'),
  ('bn.bengali', 2, 200, 'আর অতঃপর যখন হজ্জ্বের যাবতীয় অনুষ্ঠানক্রিয়াদি সমাপ্ত করে সারবে, তখন স্মরণ করবে আল্লাহকে, যেমন করে তোমরা স্মরণ করতে নিজেদের বাপ-দাদাদেরকে; বরং তার চেয়েও বেশী স্মরণ করবে। তারপর অনেকে তো বলে যে পরওয়াদেগার! আমাদিগকে দুনিয়াতে দান কর। অথচ তার জন্যে পরকালে কোন অংশ নেই।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 2, 201, 'আর তাদের মধ্যে কেউ কেউ বলে-হে পরওয়ারদেগার! আমাদিগকে দুনয়াতেও কল্যাণ দান কর এবং আখেরাতেও কল্যাণ দান কর এবং আমাদিগকে দোযখের আযাব থেকে রক্ষা কর।'),
  ('bn.bengali', 2, 202, 'এদেরই জন্য অংশ রয়েছে নিজেদের উপার্জিত সম্পদের। আর আল্লাহ দ্রুত হিসাব গ্রহণকারী।'),
  ('bn.bengali', 2, 203, 'আর স্মরণ কর আল্লাহকে নির্দিষ্ট সংখ্যক কয়েকটি দিনে। অতঃপর যে লোক তাড়াহুড়া করে চলে যাবে শুধু দু, দিনের মধ্যে, তার জন্যে কোন পাপ নেই। আর যে লোক থেকে যাবে তাঁর উপর কোন পাপ নেই, অবশ্য যারা ভয় করে। আর তোমরা আল্লাহকে ভয় করতে থাক এবং নিশ্চিত জেনে রাখ, তোমরা সবাই তার সামনে সমবেত হবে।'),
  ('bn.bengali', 2, 204, 'আর এমন কিছু লোক রযেছে যাদের পার্থিব জীবনের কথাবার্তা তোমাকে চমৎকৃত করবে। আর তারা সাক্ষ্য স্থাপন করে আল্লাহকে নিজের মনের কথার ব্যাপারে। প্রকৃতপক্ষে তারা কঠিন ঝগড়াটে লোক।'),
  ('bn.bengali', 2, 205, 'যখন ফিরে যায় তখন চেষ্টা করে যাতে সেখানে অকল্যাণ সৃষ্টি করতে পারে এবং শস্যক্ষেত্র ও প্রাণনাশ করতে পারে। আল্লাহ ফাসাদ ও দাঙ্গা-হাঙ্গামা পছন্দ করেন না।'),
  ('bn.bengali', 2, 206, 'আর যখন তাকে বলা হয় যে, আল্লাহকে ভয় কর, তখন তার পাপ তাকে অহঙ্কারে উদ্বুদ্ধ করে। সুতরাং তার জন্যে দোযখই যথেষ্ট। আর নিঃসন্দেহে তা হলো নিকৃষ্টতর ঠিকানা।'),
  ('bn.bengali', 2, 207, 'আর মানুষের মাঝে এক শ্রেণীর লোক রয়েছে যারা আল্লাহর সন্তুষ্টিকল্পে নিজেদের জানের বাজি রাখে। আল্লাহ হলেন তাঁর বান্দাদের প্রতি অত্যন্ত মেহেরবান।'),
  ('bn.bengali', 2, 208, 'হে ঈমানদার গন! তোমরা পরিপূর্ণভাবে ইসলামের অন্তর্ভুক্ত হয়ে যাও এবং শয়তানের পদাংক অনুসরণ কর না। নিশ্চিত রূপে সে তোমাদের প্রকাশ্য শত্রু।'),
  ('bn.bengali', 2, 209, 'অতঃপর তোমাদের মাঝে পরিস্কার নির্দেশ এসে গেছে বলে জানার পরেও যদি তোমরা পদস্খলিত হও, তাহলে নিশ্চিত জেনে রেখো, আল্লাহ, পরাক্রমশালী, বিজ্ঞ।'),
  ('bn.bengali', 2, 210, 'তারা কি সে দিকেই তাকিয়ে রয়েছে যে, মেঘের আড়ালে তাদের সামনে আসবেন আল্লাহ ও ফেরেশতাগণ ? আর তাতেই সব মীমাংসা হয়ে যাবে। বস্তুতঃ সবকার্যকলাপই আল্লাহর নিকট গিয়ে পৌঁছবে।'),
  ('bn.bengali', 2, 211, 'বনী ইসরাঈলদিগকে জিজ্ঞেস কর, তাদেরকে আমি কত স্পষ্ট নির্দশনাবলী দান করেছি। আর আল্লাহর নেয়ামত পৌছে যাওয়ার পর যদি কেউ সে নেয়ামতকে পরিবর্তিত করে দেয়, তবে আল্লাহর আযাব অতি কঠিন।'),
  ('bn.bengali', 2, 212, 'পার্থিব জীবনের উপর কাফেরদিগকে উম্মত্ত করে দেয়া হয়েছে। আর তারা ঈমানদারদের প্রতি লক্ষ্য করে হাসাহাসি করে। পক্ষান্তরে যারা পরহেযগার তারা সেই কাফেরদের তুলনায় কেয়ামতের দিন অত্যন্ত উচ্চমর্যাদায় থাকবে। আর আল্লাহ যাকে ইচ্ছা সীমাহীন রুযী দান করেন।'),
  ('bn.bengali', 2, 213, 'সকল মানুষ একই জাতি সত্তার অন্তর্ভুক্ত ছিল। অতঃপর আল্লাহ তা’আলা পয়গম্বর পাঠালেন সুসংবাদদাতা ও ভীতি প্রদর্শনকরী হিসাবে। আর তাঁদের সাথে অবর্তীণ করলেন সত্য কিতাব, যাতে মানুষের মাঝে বিতর্কমূলক বিষয়ে মীমাংসা করতে পারেন। বস্তুতঃ কিতাবের ব্যাপারে অন্য কেউ মতভেদ করেনি; কিন্তু পরিষ্কার নির্দেশ এসে যাবার পর নিজেদের পারস্পরিক জেদবশতঃ তারাই করেছে, যারা কিতাব প্রাপ্ত হয়েছিল। অতঃপর আল্লাহ ঈমানদারদেরকে হেদায়েত করেছেন সেই সত্য বিষয়ে, যে ব্যাপারে তারা মতভেদ লিপ্ত হয়েছিল। আল্লাহ যাকে ইচ্ছা, সরল পথ বাতলে দেন।'),
  ('bn.bengali', 2, 214, 'তোমাদের কি এই ধারণা যে, তোমরা জান্নাতে চলে যাবে, অথচ সে লোকদের অবস্থা অতিক্রম করনি যারা তোমাদের পূর্বে অতীত হয়েছে। তাদের উপর এসেছে বিপদ ও কষ্ট। আর এমনি ভাবে শিহরিত হতে হয়েছে যাতে নবী ও তাঁর প্রতি যারা ঈমান এনেছিল তাদেরকে পর্যন্ত একথা বলতে হয়েছে যে, কখন আসবে আল্লাহর সাহায্যে! তোমরা শোনে নাও, আল্লাহর সাহায্যে একান্তই নিকটবর্তী।'),
  ('bn.bengali', 2, 215, 'তোমার কাছে জিজ্ঞেস করে, কি তারা ব্যয় করবে? বলে দাও-যে বস্তুই তোমরা ব্যয় কর, তা হবে পিতা-মাতার জন্যে, আত্নীয়-আপনজনের জন্যে, এতীম-অনাথদের জন্যে, অসহায়দের জন্যে এবং মুসাফিরদের জন্যে। আর তোমরা যে কোন সৎকাজ করবে, নিঃসন্দেহে তা অত্যন্ত ভালভাবেই আল্লাহর জানা রয়েছে।'),
  ('bn.bengali', 2, 216, 'তোমাদের উপর যুদ্ধ ফরয করা হয়েছে, অথচ তা তোমাদের কাছে অপছন্দনীয়। পক্ষান্তরে তোমাদের কাছে হয়তো কোন একটা বিষয় পছন্দসই নয়, অথচ তা তোমাদের জন্য কল্যাণকর। আর হয়তোবা কোন একটি বিষয় তোমাদের কাছে পছন্দনীয় অথচ তোমাদের জন্যে অকল্যাণকর। বস্তুতঃ আল্লাহই জানেন, তোমরা জান না।'),
  ('bn.bengali', 2, 217, 'সম্মানিত মাস সম্পর্কে তোমার কাছে জিজ্ঞেস করে যে, তাতে যুদ্ধ করা কেমন? বলে দাও এতে যুদ্ধ করা ভীষণ বড় পাপ। আর আল্লাহর পথে প্রতিবন্দ্বকতা সৃষ্টি করা এবং কুফরী করা, মসজিদে-হারামের পথে বাধা দেয়া এবং সেখানকার অধিবাসীদেরকে বহিস্কার করা, আল্লাহর নিকট তার চেয়েও বড় পাপ। আর ধর্মের ব্যাপারে ফেতনা সৃষ্টি করা নরহত্যা অপেক্ষাও মহা পাপ। বস্তুতঃ তারা তো সর্বদাই তোমাদের সাথে যুদ্ধ করতে থাকবে, যাতে করে তোমাদিগকে দ্বীন থেকে ফিরিয়ে দিতে পারে যদি সম্ভব হয়। তোমাদের মধ্যে যারা নিজের দ্বীন থেকে ফিরে দাঁড়াবে এবং কাফের অবস্থায় মৃত্যুবরণ করবে, দুনিয়া ও আখেরাতে তাদের যাবতীয় আমল বিনষ্ট হয়ে যাবে। আর তারাই হলো দোযখবাসী। তাতে তারা চিরকাল বাস করবে।'),
  ('bn.bengali', 2, 218, 'আর এতে কোন সন্দেহের অবকাশ নেই যে, যারা ঈমান এনেছে এবং যারা হিজরত করেছে আর আল্লাহর পথে লড়াই (জেহাদ) করেছে, তারা আল্লাহর রহমতের প্রত্যাশী। আর আল্লাহ হচ্ছেন ক্ষমাকারী করুনাময়।'),
  ('bn.bengali', 2, 219, 'তারা তোমাকে মদ ও জুয়া সম্পর্কে জিজ্ঞেস করে। বলে দাও, এতদুভয়ের মধ্যে রয়েছে মহাপাপ। আর মানুষের জন্যে উপকারিতাও রয়েছে, তবে এগুলোর পাপ উপকারিতা অপেক্ষা অনেক বড়। আর তোমার কাছে জিজ্ঞেস করে, কি তারা ব্যয় করবে? বলে দাও, নিজেদের প্রয়োজনীয় ব্যয়ের পর যা বাঁচে তাই খরচ করবে। এভাবেই আল্লাহ তোমাদের জন্যে নির্দেশ সুস্পষ্টরূপে বর্ণনা করেন, যাতে তোমরা চিন্তা করতে পার।'),
  ('bn.bengali', 2, 220, 'দুনিয়া ও আখেরাতের বিষয়ে। আর তোমার কাছে জিজ্ঞেস করে, এতীম সংক্রান্ত হুকুম। বলে দাও, তাদের কাজ-কর্ম সঠিকভাবে গুছিয়ে দেয়া উত্তম আর যদি তাদের ব্যয়ভার নিজের সাথে মিশিয়ে নাও, তাহলে মনে করবে তারা তোমাদের ভাই । বস্তুতঃ অমঙ্গলকামী ও মঙ্গলকামীদেরকে আল্লাহ জানেন। আল্লাহ যদি ইচ্ছা করতেন, তাহলে তোমাদের উপর জটিলতা আরোপ করতে পারতেন। নিশ্চয়ই তিনি পরাক্রমশালী, মহাপ্রজ্ঞ।'),
  ('bn.bengali', 2, 221, 'আর তোমরা মুশরেক নারীদেরকে বিয়ে করোনা, যতক্ষণ না তারা ঈমান গ্রহণ করে। অবশ্য মুসলমান ক্রীতদাসী মুশরেক নারী অপেক্ষা উত্তম, যদিও তাদেরকে তোমাদের কাছে ভালো লাগে। এবং তোমরা (নারীরা) কোন মুশরেকের সঙ্গে বিবাহ বন্ধনে আবদ্ধ হয়ো না, যে পর্যন্ত সে ঈমান না আনে। একজন মুসলমান ক্রীতদাসও একজন মুশরেকের তুলনায় অনেক ভাল, যদিও তোমরা তাদের দেখে মোহিত হও। তারা দোযখের দিকে আহ্বান করে, আর আল্লাহ নিজের হুকুমের মাধ্যমে আহ্বান করেন জান্নাত ও ক্ষমার দিকে। আর তিনি মানুষকে নিজের নির্দেশ বাতলে দেন যাতে তারা উপদেশ গ্রহণ করে।'),
  ('bn.bengali', 2, 222, 'আর তোমার কাছে জিজ্ঞেস করে হায়েয (ঋতু) সম্পর্কে। বলে দাও, এটা অশুচি। কাজেই তোমরা হায়েয অবস্থায় স্ত্রীগমন থেকে বিরত থাক। তখন পর্যন্ত তাদের নিকটবর্তী হবে না, যতক্ষণ না তারা পবিত্র হয়ে যায়। যখন উত্তম রূপে পরিশুদ্ধ হয়ে যাবে, তখন গমন কর তাদের কাছে, যেভাবে আল্লাহ তোমাদেরকে হুকুম দিয়েছেন। নিশ্চয়ই আল্লাহ তওবাকারী এবং অপবিত্রতা থেকে যারা বেঁচে থাকে তাদেরকে পছন্দ করেন।'),
  ('bn.bengali', 2, 223, 'তোমাদের স্ত্রীরা হলো তোমাদের জন্য শস্য ক্ষেত্র। তোমরা যেভাবে ইচ্ছা তাদেরকে ব্যবহার কর। আর নিজেদের জন্য আগামী দিনের ব্যবস্থা কর এবং আল্লাহকে ভয় করতে থাক। আর নিশ্চিতভাবে জেনে রাখ যে, আল্লাহর সাথে তোমাদেরকে সাক্ষাত করতেই হবে। আর যারা ঈমান এনেছে তাদেরকে সুসংবাদ জানিয়ে দাও।'),
  ('bn.bengali', 2, 224, 'আর নিজেদের শপথের জন্য আল্লাহর নামকে লক্ষ্যবস্তু বানিও না মানুষের সাথে কোন আচার আচরণ থেকে পরহেযগারী থেকে এবং মানুষের মাঝে মীমাংসা করে দেয়া থেকে বেঁচে থাকার উদ্দেশ্যে। আল্লাহ সবকিছুই শুনেন ও জানেন।'),
  ('bn.bengali', 2, 225, 'তোমাদের নিরর্থক শপথের জন্য আল্লাহ তোমাদেরকে ধরবেন না, কিন্তু সেসব কসমের ব্যাপারে ধরবেন, তোমাদের মন যার প্রতিজ্ঞা করেছে। আর আল্লাহ হচ্ছেন ক্ষমাকারী ধৈর্য্যশীল।'),
  ('bn.bengali', 2, 226, 'যারা নিজেদের স্ত্রীদের নিকট গমন করবেনা বলে কসম খেয়ে বসে তাদের জন্য চার মাসের অবকাশ রয়েছে অতঃপর যদি পারস্পরিক মিল-মিশ করে নেয়, তবে আল্লাহ ক্ষামাকারী দয়ালু।'),
  ('bn.bengali', 2, 227, 'আর যদি বর্জন করার সংকল্প করে নেয়, তাহলে নিশ্চয়ই আল্লাহ শ্রবণকারী ও জ্ঞানী।'),
  ('bn.bengali', 2, 228, 'আর তালাকপ্রাপ্তা নারী নিজেকে অপেক্ষায় রাখবে তিন হায়েয পর্যন্ত। আর যদি সে আল্লাহর প্রতি এবং আখেরাত দিবসের উপর ঈমানদার হয়ে থাকে, তাহলে আল্লাহ যা তার জরায়ুতে সৃষ্টি করেছেন তা লুকিয়ে রাখা জায়েজ নয়। আর যদি সদ্ভাব রেখে চলতে চায়, তাহলে তাদেরকে ফিরিয়ে নেবার অধিকার তাদের স্বামীরা সংরক্ষণ করে। আর পুরুষদের যেমন স্ত্রীদের উপর অধিকার রয়েছে, তেমনি ভাবে স্ত্রীদেরও অধিকার রয়েছে পুরুষদের উপর নিয়ম অনুযায়ী। আর নারীরদের ওপর পুরুষদের শ্রেষ্ঠত্ব রয়েছে। আর আল্লাহ হচ্ছে পরাক্রমশালী, বিজ্ঞ।'),
  ('bn.bengali', 2, 229, 'তালাকে-‘রাজঈ’ হ’ল দুবার পর্যন্ত তারপর হয় নিয়মানুযায়ী রাখবে, না হয় সহৃদয়তার সঙ্গে বর্জন করবে। আর নিজের দেয়া সম্পদ থেকে কিছু ফিরিয়ে নেয়া তোমাদের জন্য জায়েয নয় তাদের কাছ থেকে। কিন্তু যে ক্ষেত্রে স্বামী ও স্ত্রী উভয়েই এ ব্যাপারে ভয় করে যে, তারা আল্লাহর নির্দেশ বজায় রাখতে পারবে না, অতঃপর যদি তোমাদের ভয় হয় যে, তারা উভয়েই আল্লাহর নির্দেশ বজায় রাখতে পারবে না, তাহলে সেক্ষেত্রে স্ত্রী যদি বিনিময় দিয়ে অব্যাহতি নিয়ে নেয়, তবে উভয়ের মধ্যে কারোরই কোন পাপ নেই। এই হলো আল্লাহ কর্তৃক নির্ধারিত সীমা। কাজেই একে অতিক্রম করো না। বস্তুতঃ যারা আল্লাহ কর্তৃক নির্ধারিত সীমা লঙ্ঘন করবে, তারাই জালেম।'),
  ('bn.bengali', 2, 230, 'তারপর যদি সে স্ত্রীকে (তৃতীয়বার) তালাক দেয়া হয়, তবে সে স্ত্রী যে পর্যন্ত তাকে ছাড়া অপর কোন স্বামীর সাথে বিয়ে করে না নেবে, তার জন্য হালাল নয়। অতঃপর যদি দ্বিতীয় স্বামী তালাক দিয়ে দেয়, তাহলে তাদের উভয়ের জন্যই পরস্পরকে পুনরায় বিয়ে করাতে কোন পাপ নেই। যদি আল্লাহর হুকুম বজায় রাখার ইচ্ছা থাকে। আর এই হলো আল্লাহ কতৃꦣ2453; নির্ধারিত সীমা; যারা উপলব্ধি করে তাদের জন্য এসব বর্ণনা করা হয়।'),
  ('bn.bengali', 2, 231, 'আর যখন তোমরা স্ত্রীদেরকে তালাক দিয়ে দাও, অতঃপর তারা নির্ধারিত ইদ্দত সমাপ্ত করে নেয়, তখন তোমরা নিয়ম অনুযায়ী তাদেরকে রেখে দাও অথবা সহানুভুতির সাথে তাদেরকে মুক্ত করে দাও। আর তোমরা তাদেরকে জ্বালাতন ও বাড়াবাড়ি করার উদ্দেশ্যে আটকে রেখো না। আর যারা এমন করবে, নিশ্চয়ই তারা নিজেদেরই ক্ষতি করবে। আর আল্লাহর নির্দেশকে হাস্যকর বিষয়ে পরিণত করো না। আল্লাহর সে অনুগ্রহের কথা স্মরণ কর, যা তোমাদের উপর রয়েছে এবং তাও স্মরণ কর, যে কিতাব ও জ্ঞানের কথা তোমাদের উপর নাযিল করা হয়েছে যার দ্বারা তোমাদেরকে উপদেশ দান করা হয়। আল্লাহকে ভয় কর এবং জেনে রাখ যে, আল্লাহ সর্ববিষয়েই জ্ঞানময়।'),
  ('bn.bengali', 2, 232, 'আর যখন তোমরা স্ত্রীদেরকে তালাক দিয়ে দাও এবং তারপর তারাও নির্ধারিত ইদ্দত পূর্ন করতে থাকে, তখন তাদেরকে পূর্ব স্বামীদের সাথে পারস্পরিক সম্মতির ভিত্তিতে নিয়মানুযায়ী বিয়ে করতে বাধাদান করো না। এ উপদেশ তাকেই দেয়া হচ্ছে, যে আল্লাহ ও কেয়ামত দিনের উপর বিশ্বাস স্থাপন করেছে। এর মধ্যে তোমাদের জন্য রয়েছে একান্ত পরিশুদ্ধতা ও অনেক পবিত্রতা। আর আল্লাহ জানেন, তোমরা জান না।'),
  ('bn.bengali', 2, 233, 'আর সন্তানবতী নারীরা তাদের সন্তানদেরকে পূর্ন দু’বছর দুধ খাওয়াবে, যদি দুধ খাওয়াবার পূর্ণ মেয়াদ সমাপ্ত করতে চায়। আর সন্তানের অধিকারী অর্থাৎ, পিতার উপর হলো সে সমস্ত নারীর খোর-পোষের দায়িত্ব প্রচলিত নিয়ম অনুযায়ী। কাউকে তার সামর্থাতিরিক্ত চাপের সম্মুখীন করা হয় না। আর মাকে তার সন্তানের জন্য ক্ষতিগ্রস্ত করা যাবে না। এবং যার সন্তান তাকেও তার সন্তানের কারণে ক্ষতির সম্মুখীন করা যাবে না। আর ওয়ারিসদের উপরও দায়িত্ব এই। তারপর যদি পিতা-মাতা ইচ্ছা করে, তাহলে দু’বছরের ভিতরেই নিজেদের পারস্পরিক পরামর্শক্রমে দুধ ছাড়িয়ে দিতে পারে, তাতে তাদের কোন পাপ নেই, আর যদি তোমরা কোন ধাত্রীর দ্বারা নিজের সন্তানদেরকে দুধ খাওয়াতে চাও, তাহলে যদি তোমরা সাব্যস্তকৃত প্রচলিত বিনিময় দিয়ে দাও তাতেও কোন পাপ নেই। আর আল্লাহকে ভয় কর এবং জেনে রেখো যে, আল্লাহ তোমাদের যাবতীয় কাজ অত্যন্ত ভাল করেই দেখেন।'),
  ('bn.bengali', 2, 234, 'আর তোমাদের মধ্যে যারা মৃত্যুবরণ করবে এবং নিজেদের স্ত্রীদেরকে ছেড়ে যাবে, তখন সে স্ত্রীদের কর্তব্য হলো নিজেকে চার মাস দশ দিন পর্যন্ত অপেক্ষা করিয়ে রাখা। তারপর যখন ইদ্দত পূর্ণ করে নেবে, তখন নিজের ব্যাপারে নীতি সঙ্গত ব্যবস্থা নিলে কোন পাপ নেই। আর তোমাদের যাবতীয় কাজের ব্যাপারেই আল্লাহর অবগতি রয়েছে।'),
  ('bn.bengali', 2, 235, 'আর যদি তোমরা আকার ইঙ্গিতে সে নারীর বিয়ের পয়গাম দাও, কিংবা নিজেদের মনে গোপন রাখ, তবে তাতেও তোমাদের কোন পাপ নেই, আল্লাহ জানেন যে, তোমরা অবশ্যই সে নারীদের কথা উল্লেখ করবে। কিন্তু তাদের সাথে বিয়ে করার গোপন প্রতিশ্রুতি দিয়ে রেখো না। অবশ্য শরীয়তের নির্ধারিত প্রথা অনুযায়ী কোন কথা সাব্যস্ত করে নেবে। আর নির্ধারিত ইদ্দত সমাপ্তি পর্যায়ে না যাওয়া অবধি বিয়ে করার কোন ইচ্ছা করো না। আর একথা জেনে রেখো যে, তোমাদের মনে যে কথা রয়েছে, আল্লাহর তা জানা আছে। কাজেই তাঁকে ভয় করতে থাক। আর জেনে রেখো যে, আল্লাহ ক্ষমাকারী ও ধৈর্য্যশীল।'),
  ('bn.bengali', 2, 236, 'স্ত্রীদেরকে স্পর্শ করার আগে এবং কোন মোহর সাব্যস্ত করার পূর্বেও যদি তালাক দিয়ে দাও, তবে তাতেও তোমাদের কোন পাপ নেই। তবে তাদেরকে কিছু খরচ দেবে। আর সামর্থ্যবানদের জন্য তাদের সামর্থ্য অনুযায়ী এবং কম সামর্থ্যবানদের জন্য তাদের সাধ্য অনুযায়ী। যে খরচ প্রচলিত রয়েছে তা সৎকর্মশীলদের উপর দায়িত্ব।'),
  ('bn.bengali', 2, 237, 'আর যদি মোহর সাব্যস্ত করার পর স্পর্শ করার পূর্বে তালাক দিয়ে দাও, তাহলে যে, মোহর সাব্যস্ত করা হয়েছে তার অর্ধেক দিয়ে দিতে হবে। অবশ্য যদি নারীরা ক্ষমা করে দেয় কিংবা বিয়ের বন্ধন যার অধিকারে সে (অর্থাৎ, স্বামী) যদি ক্ষমা করে দেয় তবে তা স্বতন্ত্র কথা। আর তোমরা পুরুষরা যদি ক্ষমা কর, তবে তা হবে পরহেযগারীর নিকটবর্তী। আর পারস্পরিক সহানুভূতির কথা বিস্মৃত হয়ো না। নিশ্চয় তোমরা যা কিছু কর আল্লাহ সেসবই অত্যন্ত ভাল করে দেখেন।'),
  ('bn.bengali', 2, 238, 'সমস্ত নামাযের প্রতি যত্নবান হও, বিশেষ করে মধ্যবর্তী নামাযের ব্যাপারে। আর আল্লাহর সামনে একান্ত আদবের সাথে দাঁড়াও।'),
  ('bn.bengali', 2, 239, 'অতঃপর যদি তোমাদের কারো ব্যাপারে ভয় থাকে, তাহলে পদচারী অবস্থাতেই পড়ে নাও অথবা সওয়ারীর উপরে। তারপর যখন তোমরা নিরাপত্তা পাবে, তখন আল্লাহকে স্মরণ কর, যেভাবে তোমাদের শেখানো হয়েছে, যা তোমরা ইতিপূর্বে জানতে না।'),
  ('bn.bengali', 2, 240, 'আর যখন তোমাদের মধ্যে যারা মৃত্যুবরণ করবে তখন স্ত্রীদের ঘর থেকে বের না করে এক বছর পর্যন্ত তাদের খরচের ব্যাপারে ওসিয়ত করে যাবে। অতঃপর যদি সে স্ত্রীরা নিজে থেকে বেরিয়ে যায়, তাহলে সে নারী যদি নিজের ব্যাপারে কোন উত্তম ব্যবস্থা করে, তবে তাতে তোমাদের উপর কোন পাপ নেই। আর আল্লাহ হচ্ছেন পরাক্রমশালী বিজ্ঞতা সম্পন্ন।'),
  ('bn.bengali', 2, 241, 'আর তালাকপ্রাপ্তা নারীদের জন্য প্রচলিত নিয়ম অনুযায়ী খরচ দেয়া পরহেযগারদের উপর কর্তব্য।'),
  ('bn.bengali', 2, 242, 'এভাবেই আল্লাহ তা’আলা তোমাদের জন্য স্বীয় নির্দেশ বর্ণনা করেন যাতে তোমরা তা বুঝতে পার।'),
  ('bn.bengali', 2, 243, 'তুমি কি তাদেরকে দেখনি, যারা মৃত্যুর ভয়ে নিজেদের ঘর ছেড়ে বেরিয়ে গিয়েছিলেন? অথচ তারা ছিল হাজার হাজার। তারপর আল্লাহ তাদেরকে বললেন মরে যাও। তারপর তাদেরকে জীবিত করে দিলেন। নিশ্চয়ই আল্লাহ মানুষের উপর অনুগ্রহকারী। কিন্তু অধিকাংশ লোক শুকরিয়া প্রকাশ করে না।'),
  ('bn.bengali', 2, 244, 'আল্লাহর পথে লড়াই কর এবং জেনে রাখ, নিঃসন্দেহে আল্লাহ সবকিছু জানেন, সবকিছু শুনেন।'),
  ('bn.bengali', 2, 245, 'এমন কে আছে যে, আল্লাহকে করজ দেবে, উত্তম করজ; অতঃপর আল্লাহ তাকে দ্বিগুণ-বহুগুণ বৃদ্ধি করে দিবেন। আল্লাহই সংকোচিত করেন এবং তিনিই প্রশস্ততা দান করেন এবং তাঁরই নিকট তোমরা সবাই ফিরে যাবে।'),
  ('bn.bengali', 2, 246, 'মূসার পরে তুমি কি বনী ইসরাঈলের একটি দলকে দেখনি, যখন তারা বলেছে নিজেদের নবীর কাছে যে, আমাদের জন্য একজন বাদশাহ নির্ধারিত করে দিন যাতে আমরা আল্লাহর পথে যুদ্ধ করতে পারি। নবী বললেন, তোমাদের প্রতিও কি এমন ধারণা করা যায় যে, লড়াইর হুকুম যদি হয়, তাহলে তখন তোমরা লড়বে না? তারা বলল, আমাদের কি হয়েছে যে, আমরা আল্লাহর পথে লড়াই করব না। অথচ আমরা বিতাড়িত হয়েছি নিজেদের ঘর-বাড়ী ও সন্তান-সন্ততি থেকে। অতঃপর যখন লড়াইয়ের নির্দেশ হলো, তখন সামান্য কয়েকজন ছাড়া তাদের সবাই ঘুরে দাঁড়ালো। আর আল্লাহ তা’আলা জালেমদের ভাল করেই জানেন।'),
  ('bn.bengali', 2, 247, 'আর তাদেরকে তাদের নবী বললেন, নিশ্চয়ই আল্লাহ তালূতকে তোমাদের জন্য বাদশাহ সাব্যস্ত করেছেন। তারা বলতে লাগল তা কেমন করে হয় যে, তার শাসন চলবে আমাদের উপর। অথচ রাষ্ট্রক্ষমতা পাওয়ার ক্ষেত্রে তার চেয়ে আমাদেরই অধিকার বেশী। আর সে সম্পদের দিক দিয়েও সচ্ছল নয়। নবী বললেন, নিশ্চয় আল্লাহ তোমাদের উপর তাকে পছন্দ করেছেন এবং স্বাস্থ্য ও জ্ঞানের দিক দিয়ে প্রাচুর্য দান করেছেন। বস্তুতঃ আল্লাহ তাকেই রাজ্য দান করেন, যাকে ইচ্ছা। আর আল্লাহ হলেন অনুগ্রহ দানকারী এবং সব বিষয়ে অবগত।'),
  ('bn.bengali', 2, 248, 'বনী-ইসরাঈলদেরকে তাদের নবী আরো বললেন, তালূতের নেতৃত্বের চিহ্ন হলো এই যে, তোমাদের কাছে একটা সিন্দুক আসবে তোমাদের পালকর্তার পক্ষ থেকে তোমাদের মনের সন্তুষ্টির নিমিত্তে। আর তাতে থাকবে মূসা, হারুন এবং তাঁদের সন্তানবর্গের পরিত্যক্ত কিছু সামগ্রী। সিন্দুকটিকে বয়ে আনবে ফেরেশতারা। তোমরা যদি ঈমানদার হয়ে থাক, তাহলে এতে তোমাদের জন্য নিশ্চিতই পরিপূর্ণ নিদর্শন রয়েছে।'),
  ('bn.bengali', 2, 249, 'অতঃপর তালূত যখন সৈন্য-সামন্ত নিয়ে বেরুল, তখন বলল, নিশ্চয় আল্লাহ তোমাদিগকে পরীক্ষা করবেন একটি নদীর মাধ্যমে। সুতরাং যে লোক সেই নদীর পানি পান করবে সে আমার নয়। আর যে, লোক তার স্বাদ গ্রহণ করলো না, নিশ্চয়ই সে আমার লোক। কিন্তু যে লোক হাতের আঁজলা ভরে সামান্য খেয়ে নেবে তার দোষঅবশ্য তেমন গুরুতর হবে না। অতঃপর সবাই পান করল সে পানি, সামান্য কয়েকজন ছাড়া। পরে তালূত যখন তা পার হলো এবং তার সাথে ছিল মাত্র কয়েকজন ঈমানদার, তখন তারা বলতে লাগল, আজকের দিনে জালূত এবং তার সেনাবাহিনীর সাথে যুদ্ধ করার শক্তি আমাদের নেই, যাদের ধারণা ছিল যে, আল্লাহর সামনে তাদের একদিন উপস্থিত হতে হবে, তারা বার বার বলতে লাগল, সামান্য দলই বিরাট দলের মোকাবেলায় জয়ী হয়েছে আল্লাহর হুকুমে। আর যারা ধৈর্য্যশীল আল্লাহ তাদের সাথে রয়েছেন।'),
  ('bn.bengali', 2, 250, 'আর যখন তালূত ও তার সেনাবাহিনী শত্রুর সম্মুখীন হল, তখন বলল, হে আমাদের পালনকর্তা, আমাদের মনে ধৈর্য্য সৃষ্টি করে দাও এবং আমাদেরকে দৃঢ়পদ রাখ-আর আমাদের সাহায্য কর সে কাফের জাতির বিরুদ্ধে।'),
  ('bn.bengali', 2, 251, 'তারপর ঈমানদাররা আল্লাহর হুকুমে জালূতের বাহিনীকে পরাজিত করে দিল এবং দাউদ জালূতকে হত্যা করল। আর আল্লাহ দাউদকে দান করলেন রাজ্য ও অভিজ্ঞতা। আর তাকে যা চাইলেন শিখালেন। আল্লাহ যদি একজনকে অপরজনের দ্বারা প্রতিহত না করতেন, তাহলে গোটা দুনিয়া বিধ্বস্ত হয়ে যেতো। কিন্তু বিশ্ববাসীর প্রতি আল্লাহ একান্তই দয়ালু, করুণাময়।'),
  ('bn.bengali', 2, 252, 'এগুলো হলো আল্লাহর নিদর্শন, যা আমরা তোমাদেরকে যথাযথভাবে শুনিয়ে থাকি। আর আপনি নিশ্চিতই আমার রসূলগণের অন্তর্ভুক্ত।'),
  ('bn.bengali', 2, 253, 'এই রসূলগণ-আমি তাদের কাউকে কারো উপর মর্যাদা দিয়েছি। তাদের মধ্যে কেউ তো হলো তারা যার সাথে আল্লাহ কথা বলেছেন, আর কারও মর্যাদা উচ্চতর করেছেন এবং আমি মরিয়ম তনয় ঈসাকে প্রকৃষ্ট মু’জেযা দান করেছি এবং তাকে শক্তি দান করেছি ‘রুহূল কুদ্দুস’ অর্থৎ জিবরাঈলের মাধ্যমে। আর আল্লাহ যদি ইচ্ছা করতেন, তাহলে পরিস্কার নির্দেশ এসে যাবার পর পয়গম্বরদের পেছনে যারা ছিল তারা লড়াই করতো না। কিন্তু তাদের মধ্যে মতবিরোধ সৃষ্টি হয়ে গেছে। অতঃপর তাদের কেউ তো ঈমান এনেছে, আর কেউ হয়েছে কাফের। আর আল্লাহ যদি ইচ্ছা করতেন, তাহলে তারা পরস্পর লড়াই করতো, কিন্তু আল্লাহ তাই করেন, যা তিনি ইচ্ছা করেন।'),
  ('bn.bengali', 2, 254, 'হে ঈমানদারগণ! আমি তোমাদেরকে যে রুযী দিয়েছি, সেদিন আসার পূর্বেই তোমরা তা থেকে ব্যয় কর, যাতে না আছে বেচা-কেনা, না আছে সুপারিশ কিংবা বন্ধুত্ব। আর কাফেররাই হলো প্রকৃত যালেম।'),
  ('bn.bengali', 2, 255, 'আল্লাহ ছাড়া অন্য কোন উপাস্য নেই, তিনি জীবিত, সবকিছুর ধারক। তাঁকে তন্দ্রাও স্পর্শ করতে পারে না এবং নিদ্রাও নয়। আসমান ও যমীনে যা কিছু রয়েছে, সবই তাঁর। কে আছ এমন, যে সুপারিশ করবে তাঁর কাছে তাঁর অনুমতি ছাড়া? দৃষ্টির সামনে কিংবা পিছনে যা কিছু রয়েছে সে সবই তিনি জানেন। তাঁর জ্ঞানসীমা থেকে তারা কোন কিছুকেই পরিবেষ্টিত করতে পারে না, কিন্তু যতটুকু তিনি ইচ্ছা করেন। তাঁর সিংহাসন সমস্ত আসমান ও যমীনকে পরিবেষ্টিত করে আছে। আর সেগুলোকে ধারণ করা তাঁর পক্ষে কঠিন নয়। তিনিই সর্বোচ্চ এবং সর্বাপেক্ষা মহান।'),
  ('bn.bengali', 2, 256, 'দ্বীনের ব্যাপারে কোন জবরদস্তি বা বাধ্য-বাধকতা নেই। নিঃসন্দেহে হেদায়াত গোমরাহী থেকে পৃথক হয়ে গেছে। এখন যারা গোমরাহকারী ‘তাগুত’দেরকে মানবে না এবং আল্লাহতে বিশ্বাস স্থাপন করবে, সে ধারণ করে নিয়েছে সুদৃঢ় হাতল যা ভাংবার নয়। আর আল্লাহ সবই শুনেন এবং জানেন।'),
  ('bn.bengali', 2, 257, 'যারা ঈমান এনেছে, আল্লাহ তাদের অভিভাবক। তাদেরকে তিনি বের করে আনেন অন্ধকার থেকে আলোর দিকে। আর যারা কুফরী করে তাদের অভিভাবক হচ্ছে তাগুত। তারা তাদেরকে আলো থেকে বের করে অন্ধকারের দিকে নিয়ে যায়। এরাই হলো দোযখের অধিবাসী, চিরকাল তারা সেখানেই থাকবে।'),
  ('bn.bengali', 2, 258, 'তুমি কি সে লোককে দেখনি, যে পালনকর্তার ব্যাপারে বাদানুবাদ করেছিল ইব্রাহীমের সাথে এ কারণে যে, আল্লাহ সে ব্যাক্তিকে রাজ্য দান করেছিলেন? ইব্রাহীম যখন বললেন, আমার পালনকর্তা হলেন তিনি, যিনি জীবন দান করেন এবং মৃত্যু ঘটান। সে বলল, আমি জীবন দান করি এবং মৃত্যু ঘটিয়ে থাকি। ইব্রাহীম বললেন, নিশ্চয়ই তিনি সুর্যকে উদিত করেন পূর্ব দিক থেকে এবার তুমি তাকে পশ্চিম দিক থেকে উদিত কর। তখন সে কাফের হতভম্ব হয়ে গেল। আর আল্লাহ সীমালংঘণকারী সম্প্রদায়কে সরল পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 2, 259, 'তুমি কি সে লোককে দেখনি যে এমন এক জনপদ দিয়ে যাচ্ছিল যার বাড়ীঘরগুলো ভেঙ্গে ছাদের উপর পড়ে ছিল? বলল, কেমন করে আল্লাহ মরনের পর একে জীবিত করবেন? অতঃপর আল্লাহ তাকে মৃত অবস্থায় রাখলেন একশ বছর। তারপর তাকে উঠালেন। বললেন, কত কাল এভাবে ছিলে? বলল আমি ছিলাম, একদিন কংবা একদিনের কিছু কম সময়। বললেন, তা নয়; বরং তুমি তো একশ বছর ছিলে। এবার চেয়ে দেখ নিজের খাবার ও পানীয়ের দিকে-সেগুলো পচে যায় নি এবং দেখ নিজের গাধাটির দিকে। আর আমি তোমাকে মানুষের জন্য দৃষ্টান্ত বানাতে চেয়েছি। আর হাড়গুলোর দিকে চেয়ে দেখ যে, আমি এগুলোকে কেমন করে জুড়ে দেই এবং সেগুলোর উপর মাংসের আবরণ পরিয়ে দেই। অতঃপর যখন তার উপর এ অবস্থা প্রকাশিত হল, তখন বলে উঠল-আমি জানি, নিঃসন্দেহে আল্লাহ সর্ব বিষয়ে ক্ষমতাশীল।'),
  ('bn.bengali', 2, 260, 'আর স্মরণ কর, যখন ইব্রাহীম বলল, হে আমার পালনকর্তা আমাকে দেখাও, কেমন করে তুমি মৃতকে জীবিত করবে। বললেন; তুমি কি বিশ্বাস কর না? বলল, অবশ্যই বিশ্বাস করি, কিন্তু দেখতে এজন্যে চাইছি যাতে অন্তরে প্রশান্তি লাভ করতে পারি। বললেন, তাহলে চারটি পাখী ধরে নাও। পরে সেগুলোকে নিজের পোষ মানিয়ে নাও, অতঃপর সেগুলোর দেহের একেকটি অংশ বিভিন্ন পাহাড়ের উপর রেখে দাও। তারপর সেগুলোকে ডাক; তোমার নিকট দৌড়ে চলে আসবে। আর জেনে রাখো, নিশ্চয়ই আল্লাহ পরাক্রমশালী, অতি জ্ঞান সম্পন্ন।'),
  ('bn.bengali', 2, 261, 'যারা আল্লাহর রাস্তায় স্বীয় ধন সম্পদ ব্যয় করে, তাদের উদাহরণ একটি বীজের মত, যা থেকে সাতটি শীষ জন্মায়। প্রত্যেকটি শীষে একশ করে দানা থাকে। আল্লাহ অতি দানশীল, সর্বজ্ঞ।'),
  ('bn.bengali', 2, 262, 'যারা স্বীয় ধন সম্পদ আল্লাহর রাস্তায় ব্যয় করে, এরপর ব্যয় করার পর সে অনুগ্রহের কথা প্রকাশ করে না এবং কষ্টও দেয় না, তাদেরই জন্যে তাদের পালনকর্তার কাছে রয়েছে পুরস্কার এবং তাদের কোন আশংকা নেই, তারা চিন্তিতও হবে না।'),
  ('bn.bengali', 2, 263, 'নম্র কথা বলে দেয়া এবং ক্ষমা প্রদর্শন করা ঐ দান খয়রাত অপেক্ষা উত্তম, যার পরে কষ্ট দেয়া হয়। আল্লাহ তা’আলা সম্পদশালী, সহিঞ্চু।'),
  ('bn.bengali', 2, 264, 'হে ঈমানদারগণ!তোমরা অনুগ্রহের কথা প্রকাশ করে এবং কষ্ট দিয়ে নিজেদের দান খয়রাত বরবাদ করো না সে ব্যক্তির মত যে নিজের ধন-সম্পদ লোক দেখানোর উদ্দেশ্যে ব্যয় করে এবং আল্লাহ ও পরকালের প্রতি বিশ্বাস রাখে না। অতএব, এ ব্যাক্তির দৃষ্টান্ত একটি মসৃণ পাথরের মত যার উপর কিছু মাটি পড়েছিল। অতঃপর এর উপর প্রবল বৃষ্টি বর্ষিত হলো, অনন্তর তাকে সম্পূর্ণ পরিষ্কার করে দিল। তারা ঐ বস্তুর কোন সওয়াব পায় না, যা তারা উপার্জন করেছে। আল্লাহ কাফের সম্প্রদায়কে পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 2, 265, 'যারা আল্লাহর রাস্তায় স্বীয় ধন-সম্পদ ব্যয় করে আল্লাহর সন্তুষ্টি অর্জনের লক্ষ্যে এবং নিজের মনকে সুদৃঢ় করার জন্যে তাদের উদাহরণ টিলায় অবস্থিত বাগানের মত, যাতে প্রবল বৃষ্টিপাত হয়; অতঃপর দ্বিগুণ ফসল দান করে। যদি এমন প্রবল বৃষ্টিপাত নাও হয়, তবে হাল্কা বর্ষণই যথেষ্ট। আল্লাহ তোমাদের কাজকর্ম যথার্থই প্রত্যক্ষ করেন।'),
  ('bn.bengali', 2, 266, 'তোমাদের কেউ পছন্দ করে যে, তার একটি খেজুর ও আঙ্গুরের বাগান হবে, এর তলদেশ দিয়ে নহর প্রবাহিত হবে, আর এতে সর্বপ্রকার ফল-ফসল থাকবে এবং সে বার্ধক্যে পৌছবে, তার দুর্বল সন্তান সন্ততিও থাকবে, এমতাবস্থায় এ বাগানের একটি ঘূর্ণিবায়ু আসবে, যাতে আগুন রয়েছে, অনন্তর বাগানটি ভষ্মীভূত হয়ে যাবে? এমনিভাবে আল্লাহ তা’আলা তোমাদের জন্যে নিদর্শনসমূহ বর্ননা করেন-যাতে তোমরা চিন্তা-ভাবনা কর।'),
  ('bn.bengali', 2, 267, 'হে ঈমানদারগণ! তোমরা স্বীয় উপার্জন থেকে এবং যা আমি তোমাদের জন্যে ভূমি থেকে উৎপন্ন করেছি, তা থেকে উৎকৃষ্ট বস্তু ব্যয় কর এবং তা থেকে নিকৃষ্ট জিনিস ব্যয় করতে মনস্থ করো না। কেননা, তা তোমরা কখনও গ্রহণ করবে না; তবে যদি তোমরা চোখ বন্ধ করে নিয়ে নাও। জেনে রেখো, আল্লাহ অভাব মুক্ত, প্রশংসিত।'),
  ('bn.bengali', 2, 268, 'শয়তান তোমাদেরকে অভাব অনটনের ভীতি প্রদর্শন করে এবং অশ্লীলতার আদেশ দেয়। পক্ষান্তরে আল্লাহ তোমাদেরকে নিজের পক্ষ থেকে ক্ষমা ও বেশী অনুগ্রহের ওয়াদা করেন। আল্লাহ প্রাচুর্যময়, সুবিজ্ঞ।'),
  ('bn.bengali', 2, 269, 'তিনি যাকে ইচ্ছা বিশেষ জ্ঞান দান করেন এবং যাকে বিশেষ জ্ঞান দান করা হয়, সে প্রভুত কল্যাণকর বস্তু প্রাপ্ত হয়। উপদেশ তারাই গ্রহণ করে, যারা জ্ঞানবান।'),
  ('bn.bengali', 2, 270, 'তোমরা যে খয়রাত বা সদ্ব্যয় কর কিংবা কোন মানত কর, আল্লাহ নিশ্চয়ই সেসব কিছুই জানেন। অন্যায়কারীদের কোন সাহায্যকারী নেই।'),
  ('bn.bengali', 2, 271, 'যদি তোমরা প্রকাশ্যে দান-খয়রাত কর, তবে তা কতইনা উত্তম। আর যদি খয়রাত গোপনে কর এবং অভাবগ্রস্তদের দিয়ে দাও, তবে তা তোমাদের জন্যে আরও উত্তম। আল্লাহ তা’আলা তোমাদের কিছু গোনাহ দূর করে দিবেন। আল্লাহ তোমাদের কাজ কর্মের খুব খবর রাখেন।'),
  ('bn.bengali', 2, 272, 'তাদেরকে সৎপথে আনার দায় তোমার নয়। বরং আল্লাহ যাকে ইচ্ছা সৎপথে পরিচালিত করেন। যে মাল তোমরা ব্যয় কর, তা নিজ উপাকারার্থেই কর। আল্লাহর সন্তুষ্টি ছাড়া অন্য কোন উদ্দেশ্যে ব্যয় করো না। তোমরা যে, অর্থ ব্যয় করবে, তার পুরস্কার পুরোপুরি পেয়ে যাবে এবং তোমাদের প্রতি অন্যায় করা হবে না।'),
  ('bn.bengali', 2, 273, 'খয়রাত ঐ সকল গরীব লোকের জন্যে যারা আল্লাহর পথে আবদ্ধ হয়ে গেছে-জীবিকার সন্ধানে অন্যত্র ঘোরাফেরা করতে সক্ষম নয়। অজ্ঞ লোকেরা যাঞ্চা না করার কারণে তাদেরকে অভাবমুক্ত মনে করে। তোমরা তাদেরকে তাদের লক্ষণ দ্বারা চিনবে। তারা মানুষের কাছে কাকুতি-মিনতি করে ভিক্ষা চায় না। তোমরা যে অর্থ ব্যয় করবে, তা আল্লাহ তা’আলা অবশ্যই পরিজ্ঞাত।'),
  ('bn.bengali', 2, 274, 'যারা স্বীয় ধন-সম্পদ ব্যয় করে, রাত্রে ও দিনে, গোপনে ও প্রকাশ্যে। তাদের জন্যে তাদের সওয়াব রয়েছে তাদের পালনকর্তার কাছে। তাদের কোন আশংঙ্কা নেই এবং তারা চিন্তিত ও হবে না।'),
  ('bn.bengali', 2, 275, 'যারা সুদ খায়, তারা কিয়ামতে দন্ডায়মান হবে, যেভাবে দন্ডায়মান হয় ঐ ব্যক্তি, যাকে শয়তান আসর করে মোহাবিষ্ট করে দেয়। তাদের এ অবস্থার কারণ এই যে, তারা বলেছেঃ ক্রয়-বিক্রয় ও তো সুদ নেয়ারই মত! অথচ আল্লা’হ তা’আলা ক্রয়-বিক্রয় বৈধ করেছেন এবং সুদ হারাম করেছেন। অতঃপর যার কাছে তার পালনকর্তার পক্ষ থেকে উপদেশ এসেছে এবং সে বিরত হয়েছে, পূর্বে যা হয়ে গেছে, তা তার। তার ব্যাপার আল্লাহর উপর নির্ভরশীল। আর যারা পুনরায় সুদ নেয়, তারাই দোযখে যাবে। তারা সেখানে চিরকাল অবস্থান করবে।'),
  ('bn.bengali', 2, 276, 'আল্লাহ তা’আলা সুদকে নিশ্চিহ্ন করেন এবং দান খয়রাতকে বর্ধিত করেন। আল্লাহ পছন্দ করেন না কোন অবিশ্বাসী পাপীকে।'),
  ('bn.bengali', 2, 277, 'নিশ্চয়ই যারা বিশ্বাস স্থাপন করেছে, সৎকাজ করেছে, নামায প্রতিষ্ঠিত করেছে এবং যাকাত দান করেছে, তাদের জন্যে তাদের পুরষ্কার তাদের পালনকর্তার কছে রয়েছে। তাদের কোন শঙ্কা নেই এবং তারা দুঃখিত হবে না।'),
  ('bn.bengali', 2, 278, 'হে ঈমানদারগণ, তোমরা আল্লাহকে ভয় কর এবং সুদের যে সমস্ত বকেয়া আছে, তা পরিত্যাগ কর, যদি তোমরা ঈমানদার হয়ে থাক।'),
  ('bn.bengali', 2, 279, 'অতঃপর যদি তোমরা পরিত্যাগ না কর, তবে আল্লাহ ও তাঁর রসূলের সাথে যুদ্ধ করতে প্রস্তুত হয়ে যাও। কিন্তু যদি তোমরা তওবা কর, তবে তোমরা নিজের মূলধন পেয়ে যাবে। তোমরা কারও প্রতি অত্যাচার করো না এবং কেউ তোমাদের প্রতি অত্যাচার করবে না।'),
  ('bn.bengali', 2, 280, 'যদি খাতক অভাবগ্রস্থ হয়, তবে তাকে সচ্ছলতা আসা পর্যন্ত সময় দেয়া উচিত। আর যদি ক্ষমা করে দাও, তবে তা খুবই উত্তম যদি তোমরা উপলব্ধি কর।'),
  ('bn.bengali', 2, 281, 'ঐ দিনকে ভয় কর, যে দিন তোমরা আল্লাহর কাছে প্রত্যাবর্তিত হবে। অতঃপর প্রত্যেকেই তার কর্মের ফল পুরোপুরি পাবে এবং তাদের প্রতি কোন রূপ অবিচার করা হবে না।'),
  ('bn.bengali', 2, 282, 'হে মুমিনগণ! যখন তোমরা কোন নির্দিষ্ট সময়ের জন্যে ঋনের আদান-প্রদান কর, তখন তা লিপিবদ্ধ করে নাও এবং তোমাদের মধ্যে কোন লেখক ন্যায়সঙ্গতভাবে তা লিখে দেবে; লেখক লিখতে অস্বীকার করবে না। আল্লাহ তাকে যেমন শিক্ষা দিয়েছেন, তার উচিত তা লিখে দেয়া। এবং ঋন গ্রহীতা যেন লেখার বিষয় বলে দেয় এবং সে যেন স্বীয় পালনকর্তা আল্লাহকে ভয় করে এবং লেখার মধ্যে বিন্দুমাত্রও বেশ কম না করে। অতঃপর ঋণগ্রহীতা যদি নির্বোধ হয় কিংবা দূর্বল হয় অথবা নিজে লেখার বিষয়বস্তু বলে দিতে অক্ষম হয়, তবে তার অভিভাবক ন্যায়সঙ্গতভাবে লিখাবে। দুজন সাক্ষী কর, তোমাদের পুরুষদের মধ্যে থেকে। যদি দুজন পুরুষ না হয়, তবে একজন পুরুষ ও দুজন মহিলা। ঐ সাক্ষীদের মধ্য থেকে যাদেরকে তোমরা পছন্দ কর যাতে একজন যদি ভুলে যায়, তবে একজন অন্যজনকে স্মরণ করিয়ে দেয়। যখন ডাকা হয়, তখন সাক্ষীদের অস্বীকার করা উচিত নয়। তোমরা এটা লিখতে অলসতা করোনা, তা ছোট হোক কিংবা বড়, নির্দিষ্ট সময় পর্যন্ত। এ লিপিবদ্ধ করণ আল্লাহর কাছে সুবিচারকে অধিক কায়েম রাখে, সাক্ষ্যকে অধিক সুসংহত রাখে এবং তোমাদের সন্দেহে পতিত না হওয়ার পক্ষে অধিক উপযুক্ত। কিন্তু যদি কারবার নগদ হয়, পরস্পর হাতে হাতে আদান-প্রদান কর, তবে তা না লিখলে তোমাদের প্রতি কোন অভিযোগ নেই। তোমরা ক্রয়-বিক্রয়ের সময় সাক্ষী রাখ। কোন লেখক ও সাক্ষীকে ক্ষতিগ্রস্ত করো না। যদি তোমরা এরূপ কর, তবে তা তোমাদের পক্ষে পাপের বিষয়। আল্লাহকে ভয় কর তিনি তোমাদেরকে শিক্ষা দেন। আল্লাহ সব কিছু জানেন।'),
  ('bn.bengali', 2, 283, 'আর তোমরা যদি প্রবাসে থাক এবং কোন লেখক না পাও তবে বন্ধকী বন্তু হস্তগত রাখা উচিত। যদি একে অন্যকে বিশ্বাস করে, তবে যাকে বিশ্বাস করা হয়, তার উচিত অন্যের প্রাপ্য পরিশোধ করা এবং স্বীয় পালনকর্তা আল্লাহকে ভয় কর! তোমরা সাক্ষ্য গোপন করো না। যে কেউ তা গোপন করবে, তার অন্তর পাপপূর্ণ হবে। তোমরা যা করা, আল্লাহ সে সম্পর্কে খুব জ্ঞাত।'),
  ('bn.bengali', 2, 284, 'যা কিছু আকাশসমূহে রয়েছে এবং যা কিছু যমীনে আছে, সব আল্লাহরই। যদি তোমরা মনের কথা প্রকাশ কর কিংবা গোপন কর, আল্লাহ তোমাদের কাছ থেকে তার হিসাব নেবেন। অতঃপর যাকে ইচ্ছা তিনি ক্ষমা করবেন এবং যাকে ইচ্ছা তিনি শাস্তি দেবেন। আল্লাহ সর্ববিষয়ে শক্তিমান।'),
  ('bn.bengali', 2, 285, 'রসূল বিশ্বাস রাখেন ঐ সমস্ত বিষয় সম্পর্কে যা তাঁর পালনকর্তার পক্ষ থেকে তাঁর কাছে অবতীর্ণ হয়েছে এবং মুসলমানরাও সবাই বিশ্বাস রাখে আল্লাহর প্রতি, তাঁর ফেরেশতাদের প্রতি, তাঁর গ্রন্থসমুহের প্রতি এবং তাঁর পয়গম্বরগণের প্রতি। তারা বলে আমরা তাঁর পয়গম্বরদের মধ্যে কোন তারতম্য করিনা। তারা বলে, আমরা শুনেছি এবং কবুল করেছি। আমরা তোমার ক্ষমা চাই, হে আমাদের পালনকর্তা। তোমারই দিকে প্রত্যাবর্তন করতে হবে।'),
  ('bn.bengali', 2, 286, 'আল্লাহ কাউকে তার সাধ্যাতীত কোন কাজের ভার দেন না, সে তাই পায় যা সে উপার্জন করে এবং তাই তার উপর বর্তায় যা সে করে। হে আমাদের পালনকর্তা, যদি আমরা ভুলে যাই কিংবা ভুল করি, তবে আমাদেরকে অপরাধী করো না। হে আমাদের পালনকর্তা! এবং আমাদের উপর এমন দায়িত্ব অর্পণ করো না, যেমন আমাদের পূর্ববর্তীদের উপর অর্পণ করেছ, হে আমাদের প্রভূ! এবং আমাদের দ্বারা ঐ বোঝা বহন করিও না, যা বহন করার শক্তি আমাদের নাই। আমাদের পাপ মোচন কর। আমাদেরকে ক্ষমা কর এবং আমাদের প্রতি দয়া কর। তুমিই আমাদের প্রভু। সুতরাং কাফের সম্প্রদায়ের বিরুদ্ধে আমাদের কে সাহায্যে কর।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 2, 1, 'Alif. Lam. Mim.'),
  ('en.pickthall', 2, 2, 'This is the Scripture whereof there is no doubt, a guidance unto those who ward off (evil).'),
  ('en.pickthall', 2, 3, 'Who believe in the Unseen, and establish worship, and spend of that We have bestowed upon them;'),
  ('en.pickthall', 2, 4, 'And who believe in that which is revealed unto thee (Muhammad) and that which was revealed before thee, and are certain of the Hereafter.'),
  ('en.pickthall', 2, 5, 'These depend on guidance from their Lord. These are the successful.'),
  ('en.pickthall', 2, 6, 'As for the Disbelievers, Whether thou warn them or thou warn them not it is all one for them; they believe not.'),
  ('en.pickthall', 2, 7, 'Allah hath sealed their hearing and their hearts, and on their eyes there is a covering. Theirs will be an awful doom.'),
  ('en.pickthall', 2, 8, 'And of mankind are some who say: We believe in Allah and the Last Day, when they believe not.'),
  ('en.pickthall', 2, 9, 'They think to beguile Allah and those who believe, and they beguile none save themselves; but they perceive not.'),
  ('en.pickthall', 2, 10, 'In their hearts is a disease, and Allah increaseth their disease. A painful doom is theirs because they lie.'),
  ('en.pickthall', 2, 11, 'And when it is said unto them: Make not mischief in the earth, they say: We are peacemakers only.'),
  ('en.pickthall', 2, 12, 'Are not they indeed the mischief-makers? But they perceive not.'),
  ('en.pickthall', 2, 13, 'And when it is said unto them: believe as the people believe, they say: shall we believe as the foolish believe? are not they indeed the foolish? But they know not.'),
  ('en.pickthall', 2, 14, 'And when they fall in with those who believe, they say: We believe; but when they go apart to their devils they declare: Lo! we are with you; verily we did but mock.'),
  ('en.pickthall', 2, 15, 'Allah (Himself) doth mock them, leaving them to wander blindly on in their contumacy.'),
  ('en.pickthall', 2, 16, 'These are they who purchase error at the price of guidance, so their commerce doth not prosper, neither are they guided.'),
  ('en.pickthall', 2, 17, 'Their likeness is as the likeness of one who kindleth fire, and when it sheddeth its light around him Allah taketh away their light and leaveth them in darkness, where they cannot see,'),
  ('en.pickthall', 2, 18, 'Deaf, dumb and blind; and they return not.'),
  ('en.pickthall', 2, 19, 'Or like a rainstorm from the sky, wherein is darkness, thunder and the flash of lightning. They thrust their fingers in their ears by reason of the thunder-claps, for fear of death, Allah encompasseth the disbelievers (in His guidance, His omniscience and His omnipotence).'),
  ('en.pickthall', 2, 20, 'The lightning almost snatcheth away their sight from them. As often as it flasheth forth for them they walk therein, and when it darkeneth against them they stand still. If Allah willed, He could destroy their hearing and their sight. Lo! Allah is able to do all things.'),
  ('en.pickthall', 2, 21, 'O mankind! worship your Lord, Who hath created you and those before you, so that ye may ward off (evil).'),
  ('en.pickthall', 2, 22, 'Who hath appointed the earth a resting-place for you, and the sky a canopy; and causeth water to pour down from the sky, thereby producing fruits as food for you. And do not set up rivals to Allah when ye know (better).'),
  ('en.pickthall', 2, 23, 'And if ye are in doubt concerning that which We reveal unto Our slave (Muhammad), then produce a surah of the like thereof, and call your witness beside Allah if ye are truthful.'),
  ('en.pickthall', 2, 24, 'And if ye do it not - and ye can never do it - then guard yourselves against the Fire prepared for disbelievers, whose fuel is of men and stones.'),
  ('en.pickthall', 2, 25, 'And give glad tidings (O Muhammad) unto those who believe and do good works; that theirs are Gardens underneath which rivers flow; as often as they are regaled with food of the fruit thereof, they say: this is what was given us aforetime; and it is given to them in resemblance. There for them are pure companions; there for ever they abide.'),
  ('en.pickthall', 2, 26, 'Lo! Allah disdaineth not to coin the similitude even of a gnat. Those who believe know that it is the truth from their Lord; but those who disbelieve say: What doth Allah wish (to teach) by such a similitude? He misleadeth many thereby, and He guideth many thereby; and He misleadeth thereby only miscreants;'),
  ('en.pickthall', 2, 27, 'Those who break the covenant of Allah after ratifying it, and sever that which Allah ordered to be joined, and (who) make mischief in the earth: Those are they who are the losers.'),
  ('en.pickthall', 2, 28, 'How disbelieve ye in Allah when ye were dead and He gave life to you! Then He will give you death, then life again, and then unto Him ye will return.'),
  ('en.pickthall', 2, 29, 'He it is Who created for you all that is in the earth. Then turned He to the heaven, and fashioned it as seven heavens. And He is knower of all things.'),
  ('en.pickthall', 2, 30, 'And when thy Lord said unto the angels: Lo! I am about to place a viceroy in the earth, they said: Wilt thou place therein one who will do harm therein and will shed blood, while we, we hymn Thy praise and sanctify Thee? He said: Surely I know that which ye know not.'),
  ('en.pickthall', 2, 31, 'And He taught Adam all the names, then showed them to the angels, saying: Inform Me of the names of these, if ye are truthful.'),
  ('en.pickthall', 2, 32, 'They said: Be glorified! We have no knowledge saving that which Thou hast taught us. Lo! Thou, only Thou, art the Knower, the Wise.'),
  ('en.pickthall', 2, 33, 'He said: O Adam! Inform them of their names, and when he had informed them of their names, He said: Did I not tell you that I know the secret of the heavens and the earth? And I know that which ye disclose and which ye hide.'),
  ('en.pickthall', 2, 34, 'And when We said unto the angels: Prostrate yourselves before Adam, they fell prostrate, all save Iblis. He demurred through pride, and so became a disbeliever.'),
  ('en.pickthall', 2, 35, 'And We said: O Adam! Dwell thou and thy wife in the Garden, and eat ye freely (of the fruits) thereof where ye will; but come not nigh this tree lest ye become wrong-doers.'),
  ('en.pickthall', 2, 36, 'But Satan caused them to deflect therefrom and expelled them from the (happy) state in which they were; and We said: Fall down, one of you a foe unto the other! There shall be for you on earth a habitation and provision for a time.'),
  ('en.pickthall', 2, 37, 'Then Adam received from his Lord words (of revelation), and He relented toward him. Lo! He is the relenting, the Merciful.'),
  ('en.pickthall', 2, 38, 'We said: Go down, all of you, from hence; but verily there cometh unto you from Me a guidance; and whoso followeth My guidance, there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 2, 39, 'But they who disbelieve, and deny Our revelations, such are rightful Peoples of the Fire. They will abide therein.'),
  ('en.pickthall', 2, 40, 'O Children of Israel! Remember My favour wherewith I favoured you, and fulfil your (part of the) covenant, I shall fulfil My (part of the) covenant, and fear Me.'),
  ('en.pickthall', 2, 41, 'And believe in that which I reveal, confirming that which ye possess already (of the Scripture), and be not first to disbelieve therein, and part not with My revelations for a trifling price, and keep your duty unto Me.'),
  ('en.pickthall', 2, 42, 'Confound not truth with falsehood, nor knowingly conceal the truth.'),
  ('en.pickthall', 2, 43, 'Establish worship, pay the poor-due, and bow your heads with those who bow (in worship).'),
  ('en.pickthall', 2, 44, 'Enjoin ye righteousness upon mankind while ye yourselves forget (to practise it)? And ye are readers of the Scripture! Have ye then no sense?'),
  ('en.pickthall', 2, 45, 'Seek help in patience and prayer; and truly it is hard save for the humble-minded,'),
  ('en.pickthall', 2, 46, 'Who know that they will have to meet their Lord, and that unto Him they are returning.'),
  ('en.pickthall', 2, 47, 'O Children of Israel! Remember My favour wherewith I favoured you and how I preferred you to (all) creatures.'),
  ('en.pickthall', 2, 48, 'And guard yourselves against a day when no soul will in aught avail another, nor will intercession be accepted from it, nor will compensation be received from it, nor will they be helped.'),
  ('en.pickthall', 2, 49, 'And (remember) when We did deliver you from Pharaoh\'s folk, who were afflicting you with dreadful torment, slaying your sons and sparing your women: that was a tremendous trial from your Lord.'),
  ('en.pickthall', 2, 50, 'And when We brought you through the sea and rescued you, and drowned the folk of Pharaoh in your sight.'),
  ('en.pickthall', 2, 51, 'And when We did appoint for Moses forty nights (of solitude), and then ye chose the calf, when he had gone from you, and were wrong-doers.'),
  ('en.pickthall', 2, 52, 'Then, even after that, We pardoned you in order that ye might give thanks.'),
  ('en.pickthall', 2, 53, 'And when We gave unto Moses the Scripture and the criterion (of right and wrong), that ye might be led aright.'),
  ('en.pickthall', 2, 54, 'And when Moses said unto his people: O my people! Ye have wronged yourselves by your choosing of the calf (for worship) so turn in penitence to your Creator, and kill (the guilty) yourselves. That will be best for you with your Creator and He will relent toward you. Lo! He is the Relenting, the Merciful.'),
  ('en.pickthall', 2, 55, 'And when ye said: O Moses! We will not believe in thee till we see Allah plainly; and even while ye gazed the lightning seized you.'),
  ('en.pickthall', 2, 56, 'Then We revived you after your extinction, that ye might give thanks.'),
  ('en.pickthall', 2, 57, 'And We caused the white cloud to overshadow you and sent down on you the manna and the quails, (saying): Eat of the good things wherewith We have provided you - they wronged Us not, but they did wrong themselves.'),
  ('en.pickthall', 2, 58, 'And when We said: Go into this township and eat freely of that which is therein, and enter the gate prostrate, and say: "Repentance." We will forgive you your sins and will increase (reward) for the right-doers.'),
  ('en.pickthall', 2, 59, 'But those who did wrong changed the word which had been told them for another saying, and We sent down upon the evil-doers wrath from heaven for their evil-doing.'),
  ('en.pickthall', 2, 60, 'And when Moses asked for water for his people, We said: Smite with thy staff the rock. And there gushed out therefrom twelve springs (so that) each tribe knew their drinking-place. Eat and drink of that which Allah hath provided, and do not act corruptly, making mischief in the earth.'),
  ('en.pickthall', 2, 61, 'And when ye said: O Moses! We are weary of one kind of food; so call upon thy Lord for us that He bring forth for us of that which the earth groweth - of its herbs and its cucumbers and its corn and its lentils and its onions. He said: Would ye exchange that which is higher for that which is lower? Go down to settled country, thus ye shall get that which ye demand. And humiliation and wretchedness were stamped upon them and they were visited with wrath from Allah. That was because they disbelieved in Allah\'s revelations and slew the prophets wrongfully. That was for their disobedience and transgression.'),
  ('en.pickthall', 2, 62, 'Lo! Those who believe (in that which is revealed unto thee, Muhammad), and those who are Jews, and Christians, and Sabaeans - whoever believeth in Allah and the Last Day and doeth right - surely their reward is with their Lord, and there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 2, 63, 'And (remember, O Children of Israel) when We made a covenant with you and caused the mount to tower above you, (saying): Hold fast that which We have given you, and remember that which is therein, that ye may ward off (evil).'),
  ('en.pickthall', 2, 64, 'Then, even after that, ye turned away, and if it had not been for the grace of Allah and His mercy ye had been among the losers.'),
  ('en.pickthall', 2, 65, 'And ye know of those of you who broke the Sabbath, how We said unto them: Be ye apes, despised and hated!'),
  ('en.pickthall', 2, 66, 'And We made it an example to their own and to succeeding generations, and an admonition to the Allah-fearing.'),
  ('en.pickthall', 2, 67, 'And when Moses said unto his people: Lo! Allah commandeth you that ye sacrifice a cow, they said: Dost thou make game of us? He answered: Allah forbid that I should be among the foolish!'),
  ('en.pickthall', 2, 68, 'They said: Pray for us unto thy Lord that He make clear to us what (cow) she is. (Moses) answered: Lo! He saith, Verily she is a cow neither with calf nor immature; (she is) between the two conditions; so do that which ye are commanded.'),
  ('en.pickthall', 2, 69, 'They said: Pray for us unto thy Lord that He make clear to us of what colour she is. (Moses) answered: Lo! He saith: Verily she is a yellow cow. Bright is her colour, gladdening beholders.'),
  ('en.pickthall', 2, 70, 'They said: Pray for us unto thy Lord that He make clear to us what (cow) she is. Lo! cows are much alike to us; and Lo! if Allah wills, we may be led aright.'),
  ('en.pickthall', 2, 71, '(Moses) answered: Lo! He saith: Verily she is a cow unyoked; she plougheth not the soil nor watereth the tilth; whole and without mark. They said: Now thou bringest the truth. So they sacrificed her, though almost they did not.'),
  ('en.pickthall', 2, 72, 'And (remember) when ye slew a man and disagreed concerning it and Allah brought forth that which ye were hiding.'),
  ('en.pickthall', 2, 73, 'And We said: Smite him with some of it. Thus Allah bringeth the dead to life and showeth you His portents so that ye may understand.'),
  ('en.pickthall', 2, 74, 'Then, even after that, your hearts were hardened and became as rocks, or worse than rocks, for hardness. For indeed there are rocks from out which rivers gush, and indeed there are rocks which split asunder so that water floweth from them. And indeed there are rocks which fall down for the fear of Allah. Allah is not unaware of what ye do.'),
  ('en.pickthall', 2, 75, 'Have ye any hope that they will be true to you when a party of them used to listen to the word of Allah, then used to change it, after they had understood it, knowingly?'),
  ('en.pickthall', 2, 76, 'And when they fall in with those who believe, they say: We believe. But when they go apart one with another they say: Prate ye to them of that which Allah hath disclosed to you that they may contend with you before your Lord concerning it? Have ye then no sense?'),
  ('en.pickthall', 2, 77, 'Are they then unaware that Allah knoweth that which they keep hidden and that which they proclaim?'),
  ('en.pickthall', 2, 78, 'Among them are unlettered folk who know the Scripture not except from hearsay. They but guess.'),
  ('en.pickthall', 2, 79, 'Therefore woe be unto those who write the Scripture with their hands and then say, "This is from Allah," that they may purchase a small gain therewith. Woe unto them for that their hands have written, and woe unto them for that they earn thereby.'),
  ('en.pickthall', 2, 80, 'And they say: The Fire (of punishment) will not touch us save for a certain number of days. Say: Have ye received a covenant from Allah - truly Allah will not break His covenant - or tell ye concerning Allah that which ye know not?'),
  ('en.pickthall', 2, 81, 'Nay, but whosoever hath done evil and his sin surroundeth him; such are rightful owners of the Fire; they will abide therein.'),
  ('en.pickthall', 2, 82, 'And those who believe and do good works: such are rightful owners of the Garden. They will abide therein.'),
  ('en.pickthall', 2, 83, 'And (remember) when We made a covenant with the Children of Israel, (saying): Worship none save Allah (only), and be good to parents and to kindred and to orphans and the needy, and speak kindly to mankind; and establish worship and pay the poor-due. Then, after that, ye slid back, save a few of you, being averse.'),
  ('en.pickthall', 2, 84, 'And when We made with you a covenant (saying): Shed not the blood of your people nor turn (a party of) your people out of your dwellings. Then ye ratified (Our covenant) and ye were witnesses (thereto).'),
  ('en.pickthall', 2, 85, 'Yet ye it is who slay each other and drive out a party of your people from their homes, supporting one another against them by sin and transgression? - and if they came to you as captives ye would ransom them, whereas their expulsion was itself unlawful for you - Believe ye in part of the Scripture and disbelieve ye in part thereof? And what is the reward of those who do so save ignominy in the life of the world, and on the Day of Resurrection they will be consigned to the most grievous doom. For Allah is not unaware of what ye do.'),
  ('en.pickthall', 2, 86, 'Such are those who buy the life of the world at the price of the Hereafter. Their punishment will not be lightened, neither will they have support.'),
  ('en.pickthall', 2, 87, 'And verily We gave unto Moses the Scripture and We caused a train of messengers to follow after him, and We gave unto Jesus, son of Mary, clear proofs (of Allah\'s sovereignty), and We supported him with the Holy spirit. Is it ever so, that, when there cometh unto you a messenger (from Allah) with that which ye yourselves desire not, ye grow arrogant, and some ye disbelieve and some ye slay?'),
  ('en.pickthall', 2, 88, 'And they say: Our hearts are hardened. Nay, but Allah hath cursed them for their unbelief. Little is that which they believe.'),
  ('en.pickthall', 2, 89, 'And when there cometh unto them a scripture from Allah, confirming that in their possession - though before that they were asking for a signal triumph over those who disbelieved - and when there cometh unto them that which they know (to be the truth) they disbelieve therein. The curse of Allah is on disbelievers.'),
  ('en.pickthall', 2, 90, 'Evil is that for which they sell their souls: that they should disbelieve in that which Allah hath revealed, grudging that Allah should reveal of His bounty unto whom He will of His slaves. They have incurred anger upon anger. For disbelievers is a shameful doom.'),
  ('en.pickthall', 2, 91, 'And when it is said unto them: Believe in that which Allah hath revealed, they say: We believe in that which was revealed unto us. And they disbelieve in that which cometh after it, though it is the truth confirming that which they possess. Say (unto them, O Muhammad): Why then slew ye the prophets of Allah aforetime, if ye are (indeed) believers?'),
  ('en.pickthall', 2, 92, 'And Moses came unto you with clear proofs (of Allah\'s Sovereignty), yet, while he was away, ye chose the calf (for worship) and ye were wrong-doers.'),
  ('en.pickthall', 2, 93, 'And when We made with you a covenant and caused the Mount to tower above you, (saying): Hold fast by that which We have given you, and hear (Our Word), they said: We hear and we rebel. And (worship of) the calf was made to sink into their hearts because of their rejection (of the covenant). Say (unto them): Evil is that which your belief enjoineth on you, if ye are believers.'),
  ('en.pickthall', 2, 94, 'Say (unto them): If the abode of the Hereafter in the providence of Allah is indeed for you alone and not for others of mankind (as ye pretend), then long for death (for ye must long for death) if ye are truthful.'),
  ('en.pickthall', 2, 95, 'But they will never long for it, because of that which their own hands have sent before them. Allah is aware of evil-doers.'),
  ('en.pickthall', 2, 96, 'And thou wilt find them greediest of mankind for life and (greedier) than the idolaters. (Each) one of them would like to be allowed to live a thousand years. And to live (a thousand years) would be no means remove him from the doom. Allah is Seer of what they do.'),
  ('en.pickthall', 2, 97, 'Say (O Muhammad, to mankind): Who is an enemy to Gabriel! For he it is who hath revealed (this Scripture) to thy heart by Allah\'s leave, confirming that which was (revealed) before it, and a guidance and glad tidings to believers;'),
  ('en.pickthall', 2, 98, 'Who is an enemy to Allah, and His angels and His messengers, and Gabriel and Michael! Then, lo! Allah (Himself) is an enemy to the disbelievers.'),
  ('en.pickthall', 2, 99, 'Verily We have revealed unto thee clear tokens, and only miscreants will disbelieve in them.'),
  ('en.pickthall', 2, 100, 'Is it ever so that when they make a covenant a party of them set it aside? The truth is, most of them believe not.'),
  ('en.pickthall', 2, 101, 'And when there cometh unto them a messenger from Allah, confirming that which they possess, a party of those who have received the Scripture fling the Scripture of Allah behind their backs as if they knew not,'),
  ('en.pickthall', 2, 102, 'And follow that which the devils falsely related against the kingdom of Solomon. Solomon disbelieved not; but the devils disbelieved, teaching mankind magic and that which was revealed to the two angels in Babel, Harut and Marut. Nor did they (the two angels) teach it to anyone till they had said: We are only a temptation, therefore disbelieve not (in the guidance of Allah). And from these two (angles) people learn that by which they cause division between man and wife; but they injure thereby no-one save by Allah\'s leave. And they learn that which harmeth them and profiteth them not. And surely they do know that he who trafficketh therein will have no (happy) portion in the Hereafter; and surely evil is the price for which they sell their souls, if they but knew.'),
  ('en.pickthall', 2, 103, 'And if they had believed and kept from evil, a recompense from Allah would be better, if they only knew.'),
  ('en.pickthall', 2, 104, 'O ye who believe, say not (unto the Prophet): "Listen to us" but say "Look upon us," and be ye listeners. For disbelievers is a painful doom.'),
  ('en.pickthall', 2, 105, 'Neither those who disbelieve among the people of the Scripture nor the idolaters love that there should be sent down unto you any good thing from your Lord. But Allah chooseth for His mercy whom He will, and Allah is of Infinite Bounty.'),
  ('en.pickthall', 2, 106, 'Nothing of our revelation (even a single verse) do we abrogate or cause be forgotten, but we bring (in place) one better or the like thereof. Knowest thou not that Allah is Able to do all things?'),
  ('en.pickthall', 2, 107, 'Knowest thou not that it is Allah unto Whom belongeth the Sovereignty of the heavens and the earth; and ye have not, beside Allah, any guardian or helper?'),
  ('en.pickthall', 2, 108, 'Or would ye question your messenger as Moses was questioned aforetime? He who chooseth disbelief instead of faith, verily he hath gone astray from a plain road.'),
  ('en.pickthall', 2, 109, 'Many of the people of the Scripture long to make you disbelievers after your belief, through envy on their own account, after the truth hath become manifest unto them. Forgive and be indulgent (toward them) until Allah give command. Lo! Allah is Able to do all things.'),
  ('en.pickthall', 2, 110, 'Establish worship, and pay the poor-due; and whatever of good ye send before (you) for your souls, ye will find it with Allah. Lo! Allah is Seer of what ye do.'),
  ('en.pickthall', 2, 111, 'And they say: None entereth paradise unless he be a Jew or a Christian. These are their own desires. Say: Bring your proof (of what ye state) if ye are truthful.'),
  ('en.pickthall', 2, 112, 'Nay, but whosoever surrendereth his purpose to Allah while doing good, his reward is with his Lord; and there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 2, 113, 'And the Jews say the Christians follow nothing (true), and the Christians say the Jews follow nothing (true); yet both are readers of the Scripture. Even thus speak those who know not. Allah will judge between them on the Day of Resurrection concerning that wherein they differ.'),
  ('en.pickthall', 2, 114, 'And who doth greater wrong than he who forbiddeth the approach to the sanctuaries of Allah lest His name should be mentioned therein, and striveth for their ruin. As for such, it was never meant that they should enter them except in fear. Theirs in the world is ignominy and theirs in the Hereafter is an awful doom.'),
  ('en.pickthall', 2, 115, 'Unto Allah belong the East and the West, and whithersoever ye turn, there is Allah\'s Countenance. Lo! Allah is All-Embracing, All-Knowing.'),
  ('en.pickthall', 2, 116, 'And they say: Allah hath taken unto Himself a son. Be He glorified! Nay, but whatsoever is in the heavens and the earth is His. All are subservient unto Him.'),
  ('en.pickthall', 2, 117, 'The Originator of the heavens and the earth! When He decreeth a thing, He saith unto it only: Be! and it is.'),
  ('en.pickthall', 2, 118, 'And those who have no knowledge say: Why doth not Allah speak unto us, or some sign come unto us? Even thus, as they now speak, spake those (who were) before them. Their hearts are all alike. We have made clear the revelations for people who are sure.'),
  ('en.pickthall', 2, 119, 'Lo! We have sent thee (O Muhammad) with the truth, a bringer of glad tidings and a warner. And thou wilt not be asked about the owners of hell-fire.'),
  ('en.pickthall', 2, 120, 'And the Jews will not be pleased with thee, nor will the Christians, till thou follow their creed. Say: Lo! the guidance of Allah (Himself) is Guidance. And if thou shouldst follow their desires after the knowledge which hath come unto thee, then wouldst thou have from Allah no protecting guardian nor helper.'),
  ('en.pickthall', 2, 121, 'Those unto whom We have given the Scripture, who read it with the right reading, those believe in it. And whoso disbelieveth in it, those are they who are the losers.'),
  ('en.pickthall', 2, 122, 'O Children of Israel! Remember My favour wherewith I favoured you and how I preferred you to (all) creatures.'),
  ('en.pickthall', 2, 123, 'And guard (yourselves) against a day when no soul will in aught avail another, nor will compensation be accepted from it, nor will intercession be of use to it; nor will they be helped.'),
  ('en.pickthall', 2, 124, 'And (remember) when his Lord tried Abraham with (His) commands, and he fulfilled them, He said: Lo! I have appointed thee a leader for mankind. (Abraham) said: And of my offspring (will there be leaders)? He said: My covenant includeth not wrong-doers.'),
  ('en.pickthall', 2, 125, 'And when We made the House (at Makka) a resort for mankind and sanctuary, (saying): Take as your place of worship the place where Abraham stood (to pray). And We imposed a duty upon Abraham and Ishmael, (saying): Purify My house for those who go around and those who meditate therein and those who bow down and prostrate themselves (in worship).'),
  ('en.pickthall', 2, 126, 'And when Abraham prayed: My Lord! Make this a region of security and bestow upon its people fruits, such of them as believe in Allah and the Last Day, He answered: As for him who disbelieveth, I shall leave him in contentment for a while, then I shall compel him to the doom of Fire - a hapless journey\'s end!'),
  ('en.pickthall', 2, 127, 'And when Abraham and Ishmael were raising the foundations of the House, (Abraham prayed): Our Lord! Accept from us (this duty). Lo! Thou, only Thou, art the Hearer, the Knower.'),
  ('en.pickthall', 2, 128, 'Our Lord! And make us submissive unto Thee and of our seed a nation submissive unto Thee, and show us our ways of worship, and relent toward us. Lo! Thou, only Thou, art the Relenting, the Merciful.'),
  ('en.pickthall', 2, 129, 'Our Lord! And raise up in their midst a messenger from among them who shall recite unto them Thy revelations, and shall instruct them in the Scripture and in wisdom and shall make them grow. Lo! Thou, only Thou, art the Mighty, Wise.'),
  ('en.pickthall', 2, 130, 'And who forsaketh the religion of Abraham save him who befooleth himself? Verily We chose him in the world, and lo! in the Hereafter he is among the righteous.'),
  ('en.pickthall', 2, 131, 'When his Lord said unto him: Surrender! he said: I have surrendered to the Lord of the Worlds.'),
  ('en.pickthall', 2, 132, 'The same did Abraham enjoin upon his sons, and also Jacob, (saying): O my sons! Lo! Allah hath chosen for you the (true) religion; therefore die not save as men who have surrendered (unto Him).'),
  ('en.pickthall', 2, 133, 'Or were ye present when death came to Jacob, when he said unto his sons: What will ye worship after me? They said: We shall worship thy god, the god of thy fathers, Abraham and Ishmael and Isaac, One Allah, and unto Him we have surrendered.'),
  ('en.pickthall', 2, 134, 'Those are a people who have passed away. Theirs is that which they earned, and yours is that which ye earn. And ye will not be asked of what they used to do.'),
  ('en.pickthall', 2, 135, 'And they say: Be Jews or Christians, then ye will be rightly guided. Say (unto them, O Muhammad): Nay, but (we follow) the religion of Abraham, the upright, and he was not of the idolaters.'),
  ('en.pickthall', 2, 136, 'Say (O Muslims): We believe in Allah and that which is revealed unto us and that which was revealed unto Abraham, and Ishmael, and Isaac, and Jacob, and the tribes, and that which Moses and Jesus received, and that which the prophets received from their Lord. We make no distinction between any of them, and unto Him we have surrendered.'),
  ('en.pickthall', 2, 137, 'And if they believe in the like of that which ye believe, then are they rightly guided. But if they turn away, then are they in schism, and Allah will suffice thee (for defence) against them. He is the Hearer, the Knower.'),
  ('en.pickthall', 2, 138, '(We take our) colour from Allah, and who is better than Allah at colouring. We are His worshippers.'),
  ('en.pickthall', 2, 139, 'Say (unto the People of the Scripture): Dispute ye with us concerning Allah when He is our Lord and your Lord? Ours are our works and yours your works. We look to Him alone.'),
  ('en.pickthall', 2, 140, 'Or say ye that Abraham, and Ishmael, and Isaac, and Jacob, and the tribes were Jews or Christians? Say: Do ye know best, or doth Allah? And who is more unjust than he who hideth a testimony which he hath received from Allah? Allah is not unaware of what ye do.'),
  ('en.pickthall', 2, 141, 'Those are a people who have passed away; theirs is that which they earned and yours that which ye earn. And ye will not be asked of what they used to do.'),
  ('en.pickthall', 2, 142, 'The foolish of the people will say: What hath turned them from the qiblah which they formerly observed? Say: Unto Allah belong the East and the West. He guideth whom He will unto a straight path.'),
  ('en.pickthall', 2, 143, 'Thus We have appointed you a middle nation, that ye may be witnesses against mankind, and that the messenger may be a witness against you. And We appointed the qiblah which ye formerly observed only that We might know him who followeth the messenger, from him who turneth on his heels. In truth it was a hard (test) save for those whom Allah guided. But it was not Allah\'s purpose that your faith should be in vain, for Allah is Full of Pity, Merciful toward mankind.'),
  ('en.pickthall', 2, 144, 'We have seen the turning of thy face to heaven (for guidance, O Muhammad). And now verily We shall make thee turn (in prayer) toward a qiblah which is dear to thee. So turn thy face toward the Inviolable Place of Worship, and ye (O Muslims), wheresoever ye may be, turn your faces (when ye pray) toward it. Lo! Those who have received the Scripture know that (this revelation) is the Truth from their Lord. And Allah is not unaware of what they do.'),
  ('en.pickthall', 2, 145, 'And even if thou broughtest unto those who have received the Scripture all kinds of portents, they would not follow thy qiblah, nor canst thou be a follower of their qiblah; nor are some of them followers of the qiblah of others. And if thou shouldst follow their desires after the knowledge which hath come unto thee, then surely wert thou of the evil-doers.'),
  ('en.pickthall', 2, 146, 'Those unto whom We gave the Scripture recognise (this revelation) as they recognise their sons. But lo! a party of them knowingly conceal the truth.'),
  ('en.pickthall', 2, 147, 'It is the Truth from thy Lord (O Muhammad), so be not thou of those who waver.'),
  ('en.pickthall', 2, 148, 'And each one hath a goal toward which he turneth; so vie with one another in good works. Wheresoever ye may be, Allah will bring you all together. Lo! Allah is Able to do all things.'),
  ('en.pickthall', 2, 149, 'And whencesoever thou comest forth (for prayer, O Muhammad) turn thy face toward the Inviolable Place of Worship. Lo! it is the Truth from thy Lord. Allah is not unaware of what ye do.'),
  ('en.pickthall', 2, 150, 'Whencesoever thou comest forth turn thy face toward the Inviolable Place of Worship; and wheresoever ye may be (O Muslims) turn your faces toward it (when ye pray) so that men may have no argument against you, save such of them as do injustice - Fear them not, but fear Me! - and so that I may complete My grace upon you, and that ye may be guided.'),
  ('en.pickthall', 2, 151, 'Even as We have sent unto you a messenger from among you, who reciteth unto you Our revelations and causeth you to grow, and teacheth you the Scripture and wisdom, and teacheth you that which ye knew not.'),
  ('en.pickthall', 2, 152, 'Therefore remember Me, I will remember you. Give thanks to Me, and reject not Me.'),
  ('en.pickthall', 2, 153, 'O ye who believe! Seek help in steadfastness and prayer. Lo! Allah is with the steadfast.'),
  ('en.pickthall', 2, 154, 'And call not those who are slain in the way of Allah "dead." Nay, they are living, only ye perceive not.'),
  ('en.pickthall', 2, 155, 'And surely We shall try you with something of fear and hunger, and loss of wealth and lives and crops; but give glad tidings to the steadfast,'),
  ('en.pickthall', 2, 156, 'Who say, when a misfortune striketh them: Lo! we are Allah\'s and lo! unto Him we are returning.'),
  ('en.pickthall', 2, 157, 'Such are they on whom are blessings from their Lord, and mercy. Such are the rightly guided.'),
  ('en.pickthall', 2, 158, 'Lo! (the mountains) As-Safa and Al-Marwah are among the indications of Allah. It is therefore no sin for him who is on pilgrimage to the House (of Allah) or visiteth it, to go around them (as the pagan custom is). And he who doeth good of his own accord, (for him) lo! Allah is Responsive, Aware.'),
  ('en.pickthall', 2, 159, 'Lo! Those who hide the proofs and the guidance which We revealed, after We had made it clear to mankind in the Scripture: such are accursed of Allah and accursed of those who have the power to curse.'),
  ('en.pickthall', 2, 160, 'Except those who repent and amend and make manifest (the truth). These it is toward whom I relent. I am the Relenting, the Merciful.'),
  ('en.pickthall', 2, 161, 'Lo! Those who disbelieve, and die while they are disbelievers; on them is the curse of Allah and of angels and of men combined.'),
  ('en.pickthall', 2, 162, 'They ever dwell therein. The doom will not be lightened for them, neither will they be reprieved.'),
  ('en.pickthall', 2, 163, 'Your Allah is One Allah; there is no Allah save Him, the Beneficent, the Merciful.'),
  ('en.pickthall', 2, 164, 'Lo! In the creation of the heavens and the earth, and the difference of night and day, and the ships which run upon the sea with that which is of use to men, and the water which Allah sendeth down from the sky, thereby reviving the earth after its death, and dispersing all kinds of beasts therein, and (in) the ordinance of the winds, and the clouds obedient between heaven and earth: are signs (of Allah\'s Sovereignty) for people who have sense.'),
  ('en.pickthall', 2, 165, 'Yet of mankind are some who take unto themselves (objects of worship which they set as) rivals to Allah, loving them with a love like (that which is the due) of Allah (only) - those who believe are stauncher in their love for Allah - Oh, that those who do evil had but known, (on the day) when they behold the doom, that power belongeth wholly to Allah, and that Allah is severe in punishment!'),
  ('en.pickthall', 2, 166, '(On the day) when those who were followed disown those who followed (them), and they behold the doom, and all their aims collapse with them.'),
  ('en.pickthall', 2, 167, 'And those who were but followers will say: If a return were possible for us, we would disown them even as they have disowned us. Thus will Allah show them their own deeds as anguish for them, and they will not emerge from the Fire.'),
  ('en.pickthall', 2, 168, 'O mankind! Eat of that which is lawful and wholesome in the earth, and follow not the footsteps of the devil. Lo! he is an open enemy for you.'),
  ('en.pickthall', 2, 169, 'He enjoineth upon you only the evil and the foul, and that ye should tell concerning Allah that which ye know not.'),
  ('en.pickthall', 2, 170, 'And when it is said unto them: Follow that which Allah hath revealed, they say: We follow that wherein we found our fathers. What! Even though their fathers were wholly unintelligent and had no guidance?'),
  ('en.pickthall', 2, 171, 'The likeness of those who disbelieve (in relation to the messenger) is as the likeness of one who calleth unto that which heareth naught except a shout and cry. Deaf, dumb, blind, therefore they have no sense.'),
  ('en.pickthall', 2, 172, 'O ye who believe! Eat of the good things wherewith We have provided you, and render thanks to Allah if it is (indeed) He Whom ye worship.'),
  ('en.pickthall', 2, 173, 'He hath forbidden you only carrion, and blood, and swineflesh, and that which hath been immolated to (the name of) any other than Allah. But he who is driven by necessity, neither craving nor transgressing, it is no sin for him. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 2, 174, 'Lo! those who hide aught of the Scripture which Allah hath revealed and purchase a small gain therewith, they eat into their bellies nothing else than fire. Allah will not speak to them on the Day of Resurrection, nor will He make them grow. Theirs will be a painful doom.'),
  ('en.pickthall', 2, 175, 'Those are they who purchase error at the price of guidance, and torment at the price of pardon. How constant are they in their strife to reach the Fire!'),
  ('en.pickthall', 2, 176, 'That is because Allah hath revealed the Scripture with the truth. Lo! those who find (a cause of) disagreement in the Scripture are in open schism.'),
  ('en.pickthall', 2, 177, 'It is not righteousness that ye turn your faces to the East and the West; but righteous is he who believeth in Allah and the Last Day and the angels and the Scripture and the prophets; and giveth wealth, for love of Him, to kinsfolk and to orphans and the needy and the wayfarer and to those who ask, and to set slaves free; and observeth proper worship and payeth the poor-due. And those who keep their treaty when they make one, and the patient in tribulation and adversity and time of stress. Such are they who are sincere. Such are the Allah-fearing.'),
  ('en.pickthall', 2, 178, 'O ye who believe! Retaliation is prescribed for you in the matter of the murdered; the freeman for the freeman, and the slave for the slave, and the female for the female. And for him who is forgiven somewhat by his (injured) brother, prosecution according to usage and payment unto him in kindness. This is an alleviation and a mercy from your Lord. He who transgresseth after this will have a painful doom.'),
  ('en.pickthall', 2, 179, 'And there is life for you in retaliation, O men of understanding, that ye may ward off (evil).'),
  ('en.pickthall', 2, 180, 'It is prescribed for you, when death approacheth one of you, if he leave wealth, that he bequeath unto parents and near relatives in kindness. (This is) a duty for all those who ward off (evil).'),
  ('en.pickthall', 2, 181, 'And whoso changeth (the will) after he hath heard it - the sin thereof is only upon those who change it. Lo! Allah is Hearer, Knower.'),
  ('en.pickthall', 2, 182, 'But he who feareth from a testator some unjust or sinful clause, and maketh peace between the parties, (it shall be) no sin for him. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 2, 183, 'O ye who believe! Fasting is prescribed for you, even as it was prescribed for those before you, that ye may ward off (evil);'),
  ('en.pickthall', 2, 184, '(Fast) a certain number of days; and (for) him who is sick among you, or on a journey, (the same) number of other days; and for those who can afford it there is a ransom: the feeding of a man in need - but whoso doeth good of his own accord, it is better for him: and that ye fast is better for you if ye did but know -'),
  ('en.pickthall', 2, 185, 'The month of Ramadan in which was revealed the Qur\'an, a guidance for mankind, and clear proofs of the guidance, and the Criterion (of right and wrong). And whosoever of you is present, let him fast the month, and whosoever of you is sick or on a journey, (let him fast the same) number of other days. Allah desireth for you ease; He desireth not hardship for you; and (He desireth) that ye should complete the period, and that ye should magnify Allah for having guided you, and that peradventure ye may be thankful.'),
  ('en.pickthall', 2, 186, 'And when My servants question thee concerning Me, then surely I am nigh. I answer the prayer of the suppliant when he crieth unto Me. So let them hear My call and let them trust in Me, in order that they may be led aright.'),
  ('en.pickthall', 2, 187, 'It is made lawful for you to go in unto your wives on the night of the fast. They are raiment for you and ye are raiment for them. Allah is Aware that ye were deceiving yourselves in this respect and He hath turned in mercy toward you and relieved you. So hold intercourse with them and seek that which Allah hath ordained for you, and eat and drink until the white thread becometh distinct to you from the black thread of the dawn. Then strictly observe the fast till nightfall and touch them not, but be at your devotions in the mosques. These are the limits imposed by Allah, so approach them not. Thus Allah expoundeth His revelation to mankind that they may ward off (evil).'),
  ('en.pickthall', 2, 188, 'And eat not up your property among yourselves in vanity, nor seek by it to gain the hearing of the judges that ye may knowingly devour a portion of the property of others wrongfully.'),
  ('en.pickthall', 2, 189, 'They ask thee, (O Muhammad), of new moons, say: They are fixed seasons for mankind and for the pilgrimage. It is not righteousness that ye go to houses by the backs thereof (as do the idolaters at certain seasons), but the righteous man is he who wardeth off (evil). So go to houses by the gates thereof, and observe your duty to Allah, that ye may be successful.'),
  ('en.pickthall', 2, 190, 'Fight in the way of Allah against those who fight against you, but begin not hostilities. Lo! Allah loveth not aggressors.'),
  ('en.pickthall', 2, 191, 'And slay them wherever ye find them, and drive them out of the places whence they drove you out, for persecution is worse than slaughter. And fight not with them at the Inviolable Place of Worship until they first attack you there, but if they attack you (there) then slay them. Such is the reward of disbelievers.'),
  ('en.pickthall', 2, 192, 'But if they desist, then lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 2, 193, 'And fight them until persecution is no more, and religion is for Allah. But if they desist, then let there be no hostility except against wrong-doers.'),
  ('en.pickthall', 2, 194, 'The forbidden month for the forbidden month, and forbidden things in retaliation. And one who attacketh you, attack him in like manner as he attacked you. Observe your duty to Allah, and know that Allah is with those who ward off (evil).'),
  ('en.pickthall', 2, 195, 'Spend your wealth for the cause of Allah, and be not cast by your own hands to ruin; and do good. Lo! Allah loveth the beneficent.'),
  ('en.pickthall', 2, 196, 'Perform the pilgrimage and the visit (to Makka) for Allah. And if ye are prevented, then send such gifts as can be obtained with ease, and shave not your heads until the gifts have reached their destination. And whoever among you is sick or hath an ailment of the head must pay a ransom of fasting or almsgiving or offering. And if ye are in safety, then whosoever contenteth himself with the visit for the pilgrimage (shall give) such gifts as can be had with ease. And whosoever cannot find (such gifts), then a fast of three days while on the pilgrimage, and of seven when ye have returned; that is, ten in all. That is for him whoso folk are not present at the Inviolable Place of Worship. Observe your duty to Allah, and know that Allah is severe in punishment.'),
  ('en.pickthall', 2, 197, 'The pilgrimage is (in) the well-known months, and whoever is minded to perform the pilgrimage therein (let him remember that) there is (to be) no lewdness nor abuse nor angry conversation on the pilgrimage. And whatsoever good ye do Allah knoweth it. So make provision for yourselves (Hereafter); for the best provision is to ward off evil. Therefore keep your duty unto Me, O men of understanding.'),
  ('en.pickthall', 2, 198, 'It is no sin for you that ye seek the bounty of your Lord (by trading). But, when ye press on in the multitude from \'Arafat, remember Allah by the sacred monument. Remember Him as He hath guided you, although before ye were of those astray.'),
  ('en.pickthall', 2, 199, 'Then hasten onward from the place whence the multitude hasteneth onward, and ask forgiveness of Allah. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 2, 200, 'And when ye have completed your devotions, then remember Allah as ye remember your fathers or with a more lively remembrance. But of mankind is he who saith: "Our Lord! Give unto us in the world," and he hath no portion in the Hereafter.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 2, 201, 'And of them (also) is he who saith: "Our Lord! Give unto us in the world that which is good and in the Hereafter that which is good, and guard us from the doom of Fire."'),
  ('en.pickthall', 2, 202, 'For them there is in store a goodly portion out of that which they have earned. Allah is swift at reckoning.'),
  ('en.pickthall', 2, 203, 'Remember Allah through the appointed days. Then whoso hasteneth (his departure) by two days, it is no sin for him, and whoso delayeth, it is no sin for him; that is for him who wardeth off (evil). Be careful of your duty to Allah, and know that unto Him ye will be gathered.'),
  ('en.pickthall', 2, 204, 'And of mankind there is he whoso conversation on the life of this world pleaseth thee (Muhammad), and he calleth Allah to witness as to that which is in his heart; yet he is the most rigid of opponents.'),
  ('en.pickthall', 2, 205, 'And when he turneth away (from thee) his effort in the land is to make mischief therein and to destroy the crops and the cattle; and Allah loveth not mischief.'),
  ('en.pickthall', 2, 206, 'And when it is said unto him: Be careful of thy duty to Allah, pride taketh him to sin. Hell will settle his account, an evil resting-place.'),
  ('en.pickthall', 2, 207, 'And of mankind is he who would sell himself, seeking the pleasure of Allah; and Allah hath compassion on (His) bondmen.'),
  ('en.pickthall', 2, 208, 'O ye who believe! Come, all of you, into submission (unto Him); and follow not the footsteps of the devil. Lo! he is an open enemy for you.'),
  ('en.pickthall', 2, 209, 'And if ye slide back after the clear proofs have come unto you, then know that Allah is Mighty, Wise.'),
  ('en.pickthall', 2, 210, 'Wait they for naught else than that Allah should come unto them in the shadows of the clouds with the angels? Then the case would be already judged. All cases go back to Allah (for judgment).'),
  ('en.pickthall', 2, 211, 'Ask of the Children of Israel how many a clear revelation We gave them! He who altereth the grace of Allah after it hath come unto him (for him), lo! Allah is severe in punishment.'),
  ('en.pickthall', 2, 212, 'Beautified is the life of the world for those who disbelieve; they make a jest of the believers. But those who keep their duty to Allah will be above them on the Day of Resurrection. Allah giveth without stint to whom He will.'),
  ('en.pickthall', 2, 213, 'Mankind were one community, and Allah sent (unto them) prophets as bearers of good tidings and as warners, and revealed therewith the Scripture with the truth that it might judge between mankind concerning that wherein they differed. And only those unto whom (the Scripture) was given differed concerning it, after clear proofs had come unto them, through hatred one of another. And Allah by His Will guided those who believe unto the truth of that concerning which they differed. Allah guideth whom He will unto a straight path.'),
  ('en.pickthall', 2, 214, 'Or think ye that ye will enter paradise while yet there hath not come unto you the like of (that which came to) those who passed away before you? Affliction and adversity befell them, they were shaken as with earthquake, till the messenger (of Allah) and those who believed along with him said: When cometh Allah\'s help? Now surely Allah\'s help is nigh.'),
  ('en.pickthall', 2, 215, 'They ask thee, (O Muhammad), what they shall spend. Say: that which ye spend for good (must go) to parents and near kindred and orphans and the needy and the wayfarer. And whatsoever good ye do, lo! Allah is Aware of it.'),
  ('en.pickthall', 2, 216, 'Warfare is ordained for you, though it is hateful unto you; but it may happen that ye hate a thing which is good for you, and it may happen that ye love a thing which is bad for you. Allah knoweth, ye know not.'),
  ('en.pickthall', 2, 217, 'They question thee (O Muhammad) with regard to warfare in the sacred month. Say: Warfare therein is a great (transgression), but to turn (men) from the way of Allah, and to disbelieve in Him and in the Inviolable Place of Worship, and to expel His people thence, is a greater with Allah; for persecution is worse than killing. And they will not cease from fighting against you till they have made you renegades from your religion, if they can. And whoso becometh a renegade and dieth in his disbelief: such are they whose works have fallen both in the world and the Hereafter. Such are rightful owners of the Fire: they will abide therein.'),
  ('en.pickthall', 2, 218, 'Lo! those who believe, and those who emigrate (to escape the persecution) and strive in the way of Allah, these have hope of Allah\'s mercy. Allah is Forgiving, Merciful.'),
  ('en.pickthall', 2, 219, 'They question thee about strong drink and games of chance. Say: In both is great sin, and (some) utility for men; but the sin of them is greater than their usefulness. And they ask thee what they ought to spend. Say: that which is superfluous. Thus Allah maketh plain to you (His) revelations, that haply ye may reflect.'),
  ('en.pickthall', 2, 220, 'Upon the world and the Hereafter. And they question thee concerning orphans. Say: To improve their lot is best. And if ye mingle your affairs with theirs, then (they are) your brothers. Allah knoweth him who spoileth from him who improveth. Had Allah willed He could have overburdened you. Allah is Mighty, Wise.'),
  ('en.pickthall', 2, 221, 'Wed not idolatresses till they believe; for lo! a believing bondwoman is better than an idolatress though she please you; and give not your daughters in marriage to idolaters till they believe, for lo! a believing slave is better than an idolater though he please you. These invite unto the Fire, and Allah inviteth unto the Garden, and unto forgiveness by His grace, and expoundeth His revelations to mankind that haply they may remember.'),
  ('en.pickthall', 2, 222, 'They question thee (O Muhammad) concerning menstruation. Say: It is an illness, so let women alone at such times and go not in unto them till they are cleansed. And when they have purified themselves, then go in unto them as Allah hath enjoined upon you. Truly Allah loveth those who turn unto Him, and loveth those who have a care for cleanness.'),
  ('en.pickthall', 2, 223, 'Your women are a tilth for you (to cultivate) so go to your tilth as ye will, and send (good deeds) before you for your souls, and fear Allah, and know that ye will (one day) meet Him. Give glad tidings to believers, (O Muhammad).'),
  ('en.pickthall', 2, 224, 'And make not Allah, by your oaths, a hindrance to your being righteous and observing your duty unto Him and making peace among mankind. Allah is Hearer, Knower.'),
  ('en.pickthall', 2, 225, 'Allah will not take you to task for that which is unintentional in your oaths. But He will take you to task for that which your hearts have garnered. Allah is Forgiving, Clement.'),
  ('en.pickthall', 2, 226, 'Those who forswear their wives must wait four months; then, if they change their mind, lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 2, 227, 'And if they decide upon divorce (let them remember that) Allah is Hearer, Knower.'),
  ('en.pickthall', 2, 228, 'Women who are divorced shall wait, keeping themselves apart, three (monthly) courses. And it is not lawful for them that they should conceal that which Allah hath created in their wombs if they are believers in Allah and the Last Day. And their husbands would do better to take them back in that case if they desire a reconciliation. And they (women) have rights similar to those (of men) over them in kindness, and men are a degree above them. Allah is Mighty, Wise.'),
  ('en.pickthall', 2, 229, 'Divorce must be pronounced twice and then (a woman) must be retained in honour or released in kindness. And it is not lawful for you that ye take from women aught of that which ye have given them; except (in the case) when both fear that they may not be able to keep within the limits (imposed by) Allah. And if ye fear that they may not be able to keep the limits of Allah, in that case it is no sin for either of them if the woman ransom herself. These are the limits (imposed by) Allah. Transgress them not. For whoso transgresseth Allah\'s limits: such are wrong-doers.'),
  ('en.pickthall', 2, 230, 'And if he hath divorced her (the third time), then she is not lawful unto him thereafter until she hath wedded another husband. Then if he (the other husband) divorce her it is no sin for both of them that they come together again if they consider that they are able to observe the limits of Allah. These are the limits of Allah. He manifesteth them for people who have knowledge.'),
  ('en.pickthall', 2, 231, 'When ye have divorced women, and they have reached their term, then retain them in kindness or release them in kindness. Retain them not to their hurt so that ye transgress (the limits). He who doeth that hath wronged his soul. Make not the revelations of Allah a laughing-stock (by your behaviour), but remember Allah\'s grace upon you and that which He hath revealed unto you of the Scripture and of wisdom, whereby He doth exhort you. Observe your duty to Allah and know that Allah is Aware of all things.'),
  ('en.pickthall', 2, 232, 'And when ye have divorced women and they reach their term, place not difficulties in the way of their marrying their husbands if it is agreed between them in kindness. This is an admonition for him among you who believeth in Allah and the Last Day. That is more virtuous for you, and cleaner. Allah knoweth; ye know not.'),
  ('en.pickthall', 2, 233, 'Mothers shall suckle their children for two whole years; (that is) for those who wish to complete the suckling. The duty of feeding and clothing nursing mothers in a seemly manner is upon the father of the child. No-one should be charged beyond his capacity. A mother should not be made to suffer because of her child, nor should he to whom the child is born (be made to suffer) because of his child. And on the (father\'s) heir is incumbent the like of that (which was incumbent on the father). If they desire to wean the child by mutual consent and (after) consultation, it is no sin for them; and if ye wish to give your children out to nurse, it is no sin for you, provide that ye pay what is due from you in kindness. Observe your duty to Allah, and know that Allah is Seer of what ye do.'),
  ('en.pickthall', 2, 234, 'Such of you as die and leave behind them wives, they (the wives) shall wait, keeping themselves apart, four months and ten days. And when they reach the term (prescribed for them) then there is no sin for you in aught that they may do with themselves in decency. Allah is informed of what ye do.'),
  ('en.pickthall', 2, 235, 'There is no sin for you in that which ye proclaim or hide in your minds concerning your troth with women. Allah knoweth that ye will remember them. But plight not your troth with women except by uttering a recognised form of words. And do not consummate the marriage until (the term) prescribed is run. Know that Allah knoweth what is in your minds, so beware of Him; and know that Allah is Forgiving, Clement.'),
  ('en.pickthall', 2, 236, 'It is no sin for you if ye divorce women while yet ye have not touched them, nor appointed unto them a portion. Provide for them, the rich according to his means, and the straitened according to his means, a fair provision. (This is) a bounden duty for those who do good.'),
  ('en.pickthall', 2, 237, 'If ye divorce them before ye have touched them and ye have appointed unto them a portion, then (pay the) half of that which ye appointed, unless they (the women) agree to forgo it, or he agreeth to forgo it in whose hand is the marriage tie. To forgo is nearer to piety. And forget not kindness among yourselves. Allah is Seer of what ye do.'),
  ('en.pickthall', 2, 238, 'Be guardians of your prayers, and of the midmost prayer, and stand up with devotion to Allah.'),
  ('en.pickthall', 2, 239, 'And if ye go in fear, then (pray) standing or on horseback. And when ye are again in safety, remember Allah, as He hath taught you that which (heretofore) ye knew not.'),
  ('en.pickthall', 2, 240, '(In the case of) those of you who are about to die and leave behind them wives, they should bequeath unto their wives a provision for the year without turning them out, but if they go out (of their own accord) there is no sin for you in that which they do of themselves within their rights. Allah is Mighty, Wise.'),
  ('en.pickthall', 2, 241, 'For divorced women a provision in kindness: a duty for those who ward off (evil).'),
  ('en.pickthall', 2, 242, 'Thus Allah expoundeth unto you His revelations so that ye may understand.'),
  ('en.pickthall', 2, 243, 'Bethink thee (O Muhammad) of those of old, who went forth from their habitations in their thousands, fearing death, and Allah said unto them: Die; and then He brought them back to life. Lo! Allah is a Lord of Kindness to mankind, but most of mankind give not thanks.'),
  ('en.pickthall', 2, 244, 'Fight in the way of Allah, and know that Allah is Hearer, Knower.'),
  ('en.pickthall', 2, 245, 'Who is it that will lend unto Allah a goodly loan, so that He may give it increase manifold? Allah straiteneth and enlargeth. Unto Him ye will return.'),
  ('en.pickthall', 2, 246, 'Bethink thee of the leaders of the Children of Israel after Moses, how they said unto a prophet whom they had: Set up for us a king and we will fight in Allah\'s way. He said: Would ye then refrain from fighting if fighting were prescribed for you? They said: Why should we not fight in Allah\'s way when we have been driven from our dwellings with our children? Yet, when fighting was prescribed for them, they turned away, all save a few of them. Allah is aware of evil-doers.'),
  ('en.pickthall', 2, 247, 'Their Prophet said unto them: Lo! Allah hath raised up Saul to be a king for you. They said: How can he have kingdom over us when we are more deserving of the kingdom than he is, since he hath not been given wealth enough? He said: Lo! Allah hath chosen him above you, and hath increased him abundantly in wisdom and stature. Allah bestoweth His Sovereignty on whom He will. Allah is All-Embracing, All-Knowing.'),
  ('en.pickthall', 2, 248, 'And their Prophet said unto them: Lo! the token of his kingdom is that there shall come unto you the ark wherein is peace of reassurance from your Lord, and a remnant of that which the house of Moses and the house of Aaron left behind, the angels bearing it. Lo! herein shall be a token for you if (in truth) ye are believers.'),
  ('en.pickthall', 2, 249, 'And when Saul set out with the army, he said: Lo! Allah will try you by (the ordeal of) a river. Whosoever therefore drinketh thereof he is not of me, and whosoever tasteth it not he is of me, save him who taketh (thereof) in the hollow of his hand. But they drank thereof, all save a few of them. And after he had crossed (the river), he and those who believed with him, they said: We have no power this day against Goliath and his hosts. But those who knew that they would meet Allah exclaimed: How many a little company hath overcome a mighty host by Allah\'s leave! Allah is with the steadfast.'),
  ('en.pickthall', 2, 250, 'And when they went into the field against Goliath and his hosts they said: Our Lord! Bestow on us endurance, make our foothold sure, and give us help against the disbelieving folk.'),
  ('en.pickthall', 2, 251, 'So they routed them by Allah\'s leave and David slew Goliath; and Allah gave him the kingdom and wisdom, and taught him of that which He willeth. And if Allah had not repelled some men by others the earth would have been corrupted. But Allah is a Lord of Kindness to (His) creatures.'),
  ('en.pickthall', 2, 252, 'These are the portents of Allah which We recite unto thee (Muhammad) with truth, and lo! thou art of the number of (Our) messengers;'),
  ('en.pickthall', 2, 253, 'Of those messengers, some of whom We have caused to excel others, and of whom there are some unto whom Allah spake, while some of them He exalted (above others) in degree; and We gave Jesus, son of Mary, clear proofs (of Allah\'s Sovereignty) and We supported him with the holy Spirit. And if Allah had so wiled it, those who followed after them would not have fought one with another after the clear proofs had come unto them. But they differed, some of them believing and some disbelieving. And if Allah had so willed it, they would not have fought one with another; but Allah doeth what He will.'),
  ('en.pickthall', 2, 254, 'O ye who believe! spend of that wherewith We have provided you ere a day come when there will be no trafficking, nor friendship, nor intercession. The disbelievers, they are the wrong-doers.'),
  ('en.pickthall', 2, 255, 'Allah! There is no deity save Him, the Alive, the Eternal. Neither slumber nor sleep overtaketh Him. Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth. Who is he that intercedeth with Him save by His leave? He knoweth that which is in front of them and that which is behind them, while they encompass nothing of His knowledge save what He will. His throne includeth the heavens and the earth, and He is never weary of preserving them. He is the Sublime, the Tremendous.'),
  ('en.pickthall', 2, 256, 'There is no compulsion in religion. The right direction is henceforth distinct from error. And he who rejecteth false deities and believeth in Allah hath grasped a firm handhold which will never break. Allah is Hearer, Knower.'),
  ('en.pickthall', 2, 257, 'Allah is the Protecting Guardian of those who believe. He bringeth them out of darkness into light. As for those who disbelieve, their patrons are false deities. They bring them out of light into darkness. Such are rightful owners of the Fire. They will abide therein.'),
  ('en.pickthall', 2, 258, 'Bethink thee of him who had an argument with Abraham about his Lord, because Allah had given him the kingdom; how, when Abraham said: My Lord is He Who giveth life and causeth death, he answered: I give life and cause death. Abraham said: Lo! Allah causeth the sun to rise in the East, so do thou cause it to come up from the West. Thus was the disbeliever abashed. And Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 2, 259, 'Or (bethink thee of) the like of him who, passing by a township which had fallen into utter ruin, exclaimed: How shall Allah give this township life after its death? And Allah made him die a hundred years, then brought him back to life. He said: How long hast thou tarried? (The man) said: I have tarried a day or part of a day. (He) said: Nay, but thou hast tarried for a hundred years. Just look at thy food and drink which have not rotted! Look at thine ass! And, that We may make thee a token unto mankind, look at the bones, how We adjust them and then cover them with flesh! And when (the matter) became clear unto him, he said: I know now that Allah is Able to do all things.'),
  ('en.pickthall', 2, 260, 'And when Abraham said (unto his Lord): My Lord! Show me how Thou givest life to the dead, He said: Dost thou not believe? Abraham said: Yea, but (I ask) in order that my heart may be at ease. (His Lord) said: Take four of the birds and cause them to incline unto thee, then place a part of them on each hill, then call them, they will come to thee in haste, and know that Allah is Mighty, Wise.'),
  ('en.pickthall', 2, 261, 'The likeness of those who spend their wealth in Allah\'s way is as the likeness of a grain which groweth seven ears, in every ear a hundred grains. Allah giveth increase manifold to whom He will. Allah is All-Embracing, All-Knowing.'),
  ('en.pickthall', 2, 262, 'Those who spend their wealth for the cause of Allah and afterward make not reproach and injury to follow that which they have spent; their reward is with their Lord, and there shall no fear come upon them, neither shall they grieve.'),
  ('en.pickthall', 2, 263, 'A kind word with forgiveness is better than almsgiving followed by injury. Allah is Absolute, Clement.'),
  ('en.pickthall', 2, 264, 'O ye who believe! Render not vain your almsgiving by reproach and injury, like him who spendeth his wealth only to be seen of men and believeth not in Allah and the Last Day. His likeness is as the likeness of a rock whereon is dust of earth; a rainstorm smiteth it, leaving it smooth and bare. They have no control of aught of that which they have gained. Allah guideth not the disbelieving folk.'),
  ('en.pickthall', 2, 265, 'And the likeness of those who spend their wealth in search of Allah\'s pleasure, and for the strengthening of their souls, is as the likeness of a garden on a height. The rainstorm smiteth it and it bringeth forth its fruit twofold. And if the rainstorm smite it not, then the shower. Allah is Seer of what ye do.'),
  ('en.pickthall', 2, 266, 'Would any of you like to have a garden of palm-trees and vines, with rivers flowing underneath it, with all kinds of fruit for him therein; and old age hath stricken him and he hath feeble offspring; and a fiery whirlwind striketh it and it is (all) consumed by fire. Thus Allah maketh plain His revelations unto you, in order that ye may give thought.'),
  ('en.pickthall', 2, 267, 'O ye who believe! Spend of the good things which ye have earned, and of that which We bring forth from the earth for you, and seek not the bad (with intent) to spend thereof (in charity) when ye would not take it for yourselves save with disdain; and know that Allah is Absolute, Owner of Praise.'),
  ('en.pickthall', 2, 268, 'The devil promiseth you destitution and enjoineth on you lewdness. But Allah promiseth you forgiveness from Himself with bounty. Allah is All-Embracing, All-knowing.'),
  ('en.pickthall', 2, 269, 'He giveth wisdom unto whom He will, and he unto whom wisdom is given, he truly hath received abundant good. But none remember except men of understanding.'),
  ('en.pickthall', 2, 270, 'Whatever alms ye spend or vow ye vow, lo! Allah knoweth it. Wrong-doers have no helpers.'),
  ('en.pickthall', 2, 271, 'If ye publish your almsgiving, it is well, but if ye hide it and give it to the poor, it will be better for you, and will atone for some of your ill-deeds. Allah is Informed of what ye do.'),
  ('en.pickthall', 2, 272, 'The guiding of them is not thy duty (O Muhammad), but Allah guideth whom He will. And whatsoever good thing ye spend, it is for yourselves, when ye spend not save in search of Allah\'s Countenance; and whatsoever good thing ye spend, it will be repaid to you in full, and ye will not be wronged.'),
  ('en.pickthall', 2, 273, '(Alms are) for the poor who are straitened for the cause of Allah, who cannot travel in the land (for trade). The unthinking man accounteth them wealthy because of their restraint. Thou shalt know them by their mark: They do not beg of men with importunity. And whatsoever good thing ye spend, lo! Allah knoweth it.'),
  ('en.pickthall', 2, 274, 'Those who spend their wealth by night and day, by stealth and openly, verily their reward is with their Lord, and their shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 2, 275, 'Those who swallow usury cannot rise up save as he ariseth whom the devil hath prostrated by (his) touch. That is because they say: Trade is just like usury; whereas Allah permitteth trading and forbiddeth usury. He unto whom an admonition from his Lord cometh, and (he) refraineth (in obedience thereto), he shall keep (the profits of) that which is past, and his affair (henceforth) is with Allah. As for him who returneth (to usury) - Such are rightful owners of the Fire. They will abide therein.'),
  ('en.pickthall', 2, 276, 'Allah hath blighted usury and made almsgiving fruitful. Allah loveth not the impious and guilty.'),
  ('en.pickthall', 2, 277, 'Lo! those who believe and do good works and establish worship and pay the poor-due, their reward is with their Lord and there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 2, 278, 'O ye who believe! Observe your duty to Allah, and give up what remaineth (due to you) from usury, if ye are (in truth) believers.'),
  ('en.pickthall', 2, 279, 'And if ye do not, then be warned of war (against you) from Allah and His messenger. And if ye repent, then ye have your principal (without interest). Wrong not, and ye shall not be wronged.'),
  ('en.pickthall', 2, 280, 'And if the debtor is in straitened circumstances, then (let there be) postponement to (the time of) ease; and that ye remit the debt as almsgiving would be better for you if ye did but know.'),
  ('en.pickthall', 2, 281, 'And guard yourselves against a day in which ye will be brought back to Allah. Then every soul will be paid in full that which it hath earned, and they will not be wronged.'),
  ('en.pickthall', 2, 282, 'O ye who believe! When ye contract a debt for a fixed term, record it in writing. Let a scribe record it in writing between you in (terms of) equity. No scribe should refuse to write as Allah hath taught him, so let him write, and let him who incurreth the debt dictate, and let him observe his duty to Allah his Lord, and diminish naught thereof. But if he who oweth the debt is of low understanding, or weak, or unable himself to dictate, then let the guardian of his interests dictate in (terms of) equity. And call to witness, from among your men, two witnesses. And if two men be not (at hand) then a man and two women, of such as ye approve as witnesses, so that if the one erreth (through forgetfulness) the other will remember. And the witnesses must not refuse when they are summoned. Be not averse to writing down (the contract) whether it be small or great, with (record of) the term thereof. That is more equitable in the sight of Allah and more sure for testimony, and the best way of avoiding doubt between you; save only in the case when it is actual merchandise which ye transfer among yourselves from hand to hand. In that case it is no sin for you if ye write it not. And have witnesses when ye sell one to another, and let no harm be done to scribe or witness. If ye do (harm to them) lo! it is a sin in you. Observe your duty to Allah. Allah is teaching you. And Allah is knower of all things.'),
  ('en.pickthall', 2, 283, 'If ye be on a journey and cannot find a scribe, then a pledge in hand (shall suffice). And if one of you entrusteth to another let him who is trusted deliver up that which is entrusted to him (according to the pact between them) and let him observe his duty to Allah his Lord. Hide not testimony. He who hideth it, verily his heart is sinful. Allah is Aware of what ye do.'),
  ('en.pickthall', 2, 284, 'Unto Allah (belongeth) whatsoever is in the heavens and whatsoever is in the earth; and whether ye make known what is in your minds or hide it, Allah will bring you to account for it. He will forgive whom He will and He will punish whom He will. Allah is Able to do all things.'),
  ('en.pickthall', 2, 285, 'The messenger believeth in that which hath been revealed unto him from his Lord and (so do) believers. Each one believeth in Allah and His angels and His scriptures and His messengers - We make no distinction between any of His messengers - and they say: We hear, and we obey. (Grant us) Thy forgiveness, our Lord. Unto Thee is the journeying.'),
  ('en.pickthall', 2, 286, 'Allah tasketh not a soul beyond its scope. For it (is only) that which it hath earned, and against it (only) that which it hath deserved. Our Lord! Condemn us not if we forget, or miss the mark! Our Lord! Lay not on us such a burden as thou didst lay on those before us! Our Lord! Impose not on us that which we have not the strength to bear! Pardon us, absolve us and have mercy on us, Thou, our Protector, and give us victory over the disbelieving folk.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 2, 1, 'A. L. M.'),
  ('en.yusufali', 2, 2, 'This is the Book; in it is guidance sure, without doubt, to those who fear Allah;'),
  ('en.yusufali', 2, 3, 'Who believe in the Unseen, are steadfast in prayer, and spend out of what We have provided for them;'),
  ('en.yusufali', 2, 4, 'And who believe in the Revelation sent to thee, and sent before thy time, and (in their hearts) have the assurance of the Hereafter.'),
  ('en.yusufali', 2, 5, 'They are on (true) guidance, from their Lord, and it is these who will prosper.'),
  ('en.yusufali', 2, 6, 'As to those who reject Faith, it is the same to them whether thou warn them or do not warn them; they will not believe.'),
  ('en.yusufali', 2, 7, 'Allah hath set a seal on their hearts and on their hearing, and on their eyes is a veil; great is the penalty they (incur).'),
  ('en.yusufali', 2, 8, 'Of the people there are some who say: "We believe in Allah and the Last Day;" but they do not (really) believe.'),
  ('en.yusufali', 2, 9, 'Fain would they deceive Allah and those who believe, but they only deceive themselves, and realise (it) not!'),
  ('en.yusufali', 2, 10, 'In their hearts is a disease; and Allah has increased their disease: And grievous is the penalty they (incur), because they are false (to themselves).'),
  ('en.yusufali', 2, 11, 'When it is said to them: "Make not mischief on the earth," they say: "Why, we only Want to make peace!"'),
  ('en.yusufali', 2, 12, 'Of a surety, they are the ones who make mischief, but they realise (it) not.'),
  ('en.yusufali', 2, 13, 'When it is said to them: "Believe as the others believe:" They say: "Shall we believe as the fools believe?" Nay, of a surety they are the fools, but they do not know.'),
  ('en.yusufali', 2, 14, 'When they meet those who believe, they say: "We believe;" but when they are alone with their evil ones, they say: "We are really with you: We (were) only jesting."'),
  ('en.yusufali', 2, 15, 'Allah will throw back their mockery on them, and give them rope in their trespasses; so they will wander like blind ones (To and fro).'),
  ('en.yusufali', 2, 16, 'These are they who have bartered Guidance for error: But their traffic is profitless, and they have lost true direction,'),
  ('en.yusufali', 2, 17, 'Their similitude is that of a man who kindled a fire; when it lighted all around him, Allah took away their light and left them in utter darkness. So they could not see.'),
  ('en.yusufali', 2, 18, 'Deaf, dumb, and blind, they will not return (to the path).'),
  ('en.yusufali', 2, 19, 'Or (another similitude) is that of a rain-laden cloud from the sky: In it are zones of darkness, and thunder and lightning: They press their fingers in their ears to keep out the stunning thunder-clap, the while they are in terror of death. But Allah is ever round the rejecters of Faith!'),
  ('en.yusufali', 2, 20, 'The lightning all but snatches away their sight; every time the light (Helps) them, they walk therein, and when the darkness grows on them, they stand still. And if Allah willed, He could take away their faculty of hearing and seeing; for Allah hath power over all things.'),
  ('en.yusufali', 2, 21, 'O ye people! Adore your Guardian-Lord, who created you and those who came before you, that ye may have the chance to learn righteousness;'),
  ('en.yusufali', 2, 22, 'Who has made the earth your couch, and the heavens your canopy; and sent down rain from the heavens; and brought forth therewith Fruits for your sustenance; then set not up rivals unto Allah when ye know (the truth).'),
  ('en.yusufali', 2, 23, 'And if ye are in doubt as to what We have revealed from time to time to Our servant, then produce a Sura like thereunto; and call your witnesses or helpers (If there are any) besides Allah, if your (doubts) are true.'),
  ('en.yusufali', 2, 24, 'But if ye cannot- and of a surety ye cannot- then fear the Fire whose fuel is men and stones,- which is prepared for those who reject Faith.'),
  ('en.yusufali', 2, 25, 'But give glad tidings to those who believe and work righteousness, that their portion is Gardens, beneath which rivers flow. Every time they are fed with fruits therefrom, they say: "Why, this is what we were fed with before," for they are given things in similitude; and they have therein companions pure (and holy); and they abide therein (for ever).'),
  ('en.yusufali', 2, 26, 'Allah disdains not to use the similitude of things, lowest as well as highest. Those who believe know that it is truth from their Lord; but those who reject Faith say: "What means Allah by this similitude?" By it He causes many to stray, and many He leads into the right path; but He causes not to stray, except those who forsake (the path),-'),
  ('en.yusufali', 2, 27, 'Those who break Allah\'s Covenant after it is ratified, and who sunder what Allah Has ordered to be joined, and do mischief on earth: These cause loss (only) to themselves.'),
  ('en.yusufali', 2, 28, 'How can ye reject the faith in Allah?- seeing that ye were without life, and He gave you life; then will He cause you to die, and will again bring you to life; and again to Him will ye return.'),
  ('en.yusufali', 2, 29, 'It is He Who hath created for you all things that are on earth; Moreover His design comprehended the heavens, for He gave order and perfection to the seven firmaments; and of all things He hath perfect knowledge.'),
  ('en.yusufali', 2, 30, 'Behold, thy Lord said to the angels: "I will create a vicegerent on earth." They said: "Wilt Thou place therein one who will make mischief therein and shed blood?- whilst we do celebrate Thy praises and glorify Thy holy (name)?" He said: "I know what ye know not."'),
  ('en.yusufali', 2, 31, 'And He taught Adam the names of all things; then He placed them before the angels, and said: "Tell me the names of these if ye are right."'),
  ('en.yusufali', 2, 32, 'They said: "Glory to Thee, of knowledge We have none, save what Thou Hast taught us: In truth it is Thou Who art perfect in knowledge and wisdom."'),
  ('en.yusufali', 2, 33, 'He said: "O Adam! Tell them their names." When he had told them, Allah said: "Did I not tell you that I know the secrets of heaven and earth, and I know what ye reveal and what ye conceal?"'),
  ('en.yusufali', 2, 34, 'And behold, We said to the angels: "Bow down to Adam" and they bowed down. Not so Iblis: he refused and was haughty: He was of those who reject Faith.'),
  ('en.yusufali', 2, 35, 'We said: "O Adam! dwell thou and thy wife in the Garden; and eat of the bountiful things therein as (where and when) ye will; but approach not this tree, or ye run into harm and transgression."'),
  ('en.yusufali', 2, 36, 'Then did Satan make them slip from the (garden), and get them out of the state (of felicity) in which they had been. We said: "Get ye down, all (ye people), with enmity between yourselves. On earth will be your dwelling-place and your means of livelihood - for a time."'),
  ('en.yusufali', 2, 37, 'Then learnt Adam from his Lord words of inspiration, and his Lord Turned towards him; for He is Oft-Returning, Most Merciful.'),
  ('en.yusufali', 2, 38, 'We said: "Get ye down all from here; and if, as is sure, there comes to you Guidance from me, whosoever follows My guidance, on them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 2, 39, '"But those who reject Faith and belie Our Signs, they shall be companions of the Fire; they shall abide therein."'),
  ('en.yusufali', 2, 40, 'O Children of Israel! call to mind the (special) favour which I bestowed upon you, and fulfil your covenant with Me as I fulfil My Covenant with you, and fear none but Me.'),
  ('en.yusufali', 2, 41, 'And believe in what I reveal, confirming the revelation which is with you, and be not the first to reject Faith therein, nor sell My Signs for a small price; and fear Me, and Me alone.'),
  ('en.yusufali', 2, 42, 'And cover not Truth with falsehood, nor conceal the Truth when ye know (what it is).'),
  ('en.yusufali', 2, 43, 'And be steadfast in prayer; practise regular charity; and bow down your heads with those who bow down (in worship).'),
  ('en.yusufali', 2, 44, 'Do ye enjoin right conduct on the people, and forget (To practise it) yourselves, and yet ye study the Scripture? Will ye not understand?'),
  ('en.yusufali', 2, 45, 'Nay, seek (Allah\'s) help with patient perseverance and prayer: It is indeed hard, except to those who bring a lowly spirit,-'),
  ('en.yusufali', 2, 46, 'Who bear in mind the certainty that they are to meet their Lord, and that they are to return to Him.'),
  ('en.yusufali', 2, 47, 'Children of Israel! call to mind the (special) favour which I bestowed upon you, and that I preferred you to all other (for My Message).'),
  ('en.yusufali', 2, 48, 'Then guard yourselves against a day when one soul shall not avail another nor shall intercession be accepted for her, nor shall compensation be taken from her, nor shall anyone be helped (from outside).'),
  ('en.yusufali', 2, 49, 'And remember, We delivered you from the people of Pharaoh: They set you hard tasks and punishments, slaughtered your sons and let your women-folk live; therein was a tremendous trial from your Lord.'),
  ('en.yusufali', 2, 50, 'And remember We divided the sea for you and saved you and drowned Pharaoh\'s people within your very sight.'),
  ('en.yusufali', 2, 51, 'And remember We appointed forty nights for Moses, and in his absence ye took the calf (for worship), and ye did grievous wrong.'),
  ('en.yusufali', 2, 52, 'Even then We did forgive you; there was a chance for you to be grateful.'),
  ('en.yusufali', 2, 53, 'And remember We gave Moses the Scripture and the Criterion (Between right and wrong): There was a chance for you to be guided aright.'),
  ('en.yusufali', 2, 54, 'And remember Moses said to his people: "O my people! Ye have indeed wronged yourselves by your worship of the calf: So turn (in repentance) to your Maker, and slay yourselves (the wrong-doers); that will be better for you in the sight of your Maker." Then He turned towards you (in forgiveness): For He is Oft-Returning, Most Merciful.'),
  ('en.yusufali', 2, 55, 'And remember ye said: "O Moses! We shall never believe in thee until we see Allah manifestly," but ye were dazed with thunder and lighting even as ye looked on.'),
  ('en.yusufali', 2, 56, 'Then We raised you up after your death: Ye had the chance to be grateful.'),
  ('en.yusufali', 2, 57, 'And We gave you the shade of clouds and sent down to you Manna and quails, saying: "Eat of the good things We have provided for you:" (But they rebelled); to us they did no harm, but they harmed their own souls.'),
  ('en.yusufali', 2, 58, 'And remember We said: "Enter this town, and eat of the plenty therein as ye wish; but enter the gate with humility, in posture and in words, and We shall forgive you your faults and increase (the portion of) those who do good."'),
  ('en.yusufali', 2, 59, 'But the transgressors changed the word from that which had been given them; so We sent on the transgressors a plague from heaven, for that they infringed (Our command) repeatedly.'),
  ('en.yusufali', 2, 60, 'And remember Moses prayed for water for his people; We said: "Strike the rock with thy staff." Then gushed forth therefrom twelve springs. Each group knew its own place for water. So eat and drink of the sustenance provided by Allah, and do no evil nor mischief on the (face of the) earth.'),
  ('en.yusufali', 2, 61, 'And remember ye said: "O Moses! we cannot endure one kind of food (always); so beseech thy Lord for us to produce for us of what the earth groweth, -its pot-herbs, and cucumbers, Its garlic, lentils, and onions." He said: "Will ye exchange the better for the worse? Go ye down to any town, and ye shall find what ye want!" They were covered with humiliation and misery; they drew on themselves the wrath of Allah. This because they went on rejecting the Signs of Allah and slaying His Messengers without just cause. This because they rebelled and went on transgressing.'),
  ('en.yusufali', 2, 62, 'Those who believe (in the Qur\'an), and those who follow the Jewish (scriptures), and the Christians and the Sabians,- any who believe in Allah and the Last Day, and work righteousness, shall have their reward with their Lord; on them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 2, 63, 'And remember We took your covenant and We raised above you (The towering height) of Mount (Sinai): (Saying): "Hold firmly to what We have given you and bring (ever) to remembrance what is therein: Perchance ye may fear Allah."'),
  ('en.yusufali', 2, 64, 'But ye turned back thereafter: Had it not been for the Grace and Mercy of Allah to you, ye had surely been among the lost.'),
  ('en.yusufali', 2, 65, 'And well ye knew those amongst you who transgressed in the matter of the Sabbath: We said to them: "Be ye apes, despised and rejected."'),
  ('en.yusufali', 2, 66, 'So We made it an example to their own time and to their posterity, and a lesson to those who fear Allah.'),
  ('en.yusufali', 2, 67, 'And remember Moses said to his people: "Allah commands that ye sacrifice a heifer." They said: "Makest thou a laughing-stock of us?" He said: "Allah save me from being an ignorant (fool)!"'),
  ('en.yusufali', 2, 68, 'They said: "Beseech on our behalf Thy Lord to make plain to us what (heifer) it is!" He said; "He says: The heifer should be neither too old nor too young, but of middling age. Now do what ye are commanded!"'),
  ('en.yusufali', 2, 69, 'They said: "Beseech on our behalf Thy Lord to make plain to us Her colour." He said: "He says: A fawn-coloured heifer, pure and rich in tone, the admiration of beholders!"'),
  ('en.yusufali', 2, 70, 'They said: "Beseech on our behalf Thy Lord to make plain to us what she is: To us are all heifers alike: We wish indeed for guidance, if Allah wills."'),
  ('en.yusufali', 2, 71, 'He said: "He says: A heifer not trained to till the soil or water the fields; sound and without blemish." They said: "Now hast thou brought the truth." Then they offered her in sacrifice, but not with good-will.'),
  ('en.yusufali', 2, 72, 'Remember ye slew a man and fell into a dispute among yourselves as to the crime: But Allah was to bring forth what ye did hide.'),
  ('en.yusufali', 2, 73, 'So We said: "Strike the (body) with a piece of the (heifer)." Thus Allah bringeth the dead to life and showeth you His Signs: Perchance ye may understand.'),
  ('en.yusufali', 2, 74, 'Thenceforth were your hearts hardened: They became like a rock and even worse in hardness. For among rocks there are some from which rivers gush forth; others there are which when split asunder send forth water; and others which sink for fear of Allah. And Allah is not unmindful of what ye do.'),
  ('en.yusufali', 2, 75, 'Can ye (o ye men of Faith) entertain the hope that they will believe in you?- Seeing that a party of them heard the Word of Allah, and perverted it knowingly after they understood it.'),
  ('en.yusufali', 2, 76, 'Behold! when they meet the men of Faith, they say: "We believe": But when they meet each other in private, they say: "Shall you tell them what Allah hath revealed to you, that they may engage you in argument about it before your Lord?"- Do ye not understand (their aim)?'),
  ('en.yusufali', 2, 77, 'Know they not that Allah knoweth what they conceal and what they reveal?'),
  ('en.yusufali', 2, 78, 'And there are among them illiterates, who know not the Book, but (see therein their own) desires, and they do nothing but conjecture.'),
  ('en.yusufali', 2, 79, 'Then woe to those who write the Book with their own hands, and then say:"This is from Allah," to traffic with it for miserable price!- Woe to them for what their hands do write, and for the gain they make thereby.'),
  ('en.yusufali', 2, 80, 'And they say: "The Fire shall not touch us but for a few numbered days:" Say: "Have ye taken a promise from Allah, for He never breaks His promise? or is it that ye say of Allah what ye do not know?"'),
  ('en.yusufali', 2, 81, 'Nay, those who seek gain in evil, and are girt round by their sins,- they are companions of the Fire: Therein shall they abide (For ever).'),
  ('en.yusufali', 2, 82, 'But those who have faith and work righteousness, they are companions of the Garden: Therein shall they abide (For ever).'),
  ('en.yusufali', 2, 83, 'And remember We took a covenant from the Children of Israel (to this effect): Worship none but Allah; treat with kindness your parents and kindred, and orphans and those in need; speak fair to the people; be steadfast in prayer; and practise regular charity. Then did ye turn back, except a few among you, and ye backslide (even now).'),
  ('en.yusufali', 2, 84, 'And remember We took your covenant (to this effect): Shed no blood amongst you, nor turn out your own people from your homes: and this ye solemnly ratified, and to this ye can bear witness.'),
  ('en.yusufali', 2, 85, 'After this it is ye, the same people, who slay among yourselves, and banish a party of you from their homes; assist (Their enemies) against them, in guilt and rancour; and if they come to you as captives, ye ransom them, though it was not lawful for you to banish them. Then is it only a part of the Book that ye believe in, and do ye reject the rest? but what is the reward for those among you who behave like this but disgrace in this life?- and on the Day of Judgment they shall be consigned to the most grievous penalty. For Allah is not unmindful of what ye do.'),
  ('en.yusufali', 2, 86, 'These are the people who buy the life of this world at the price of the Hereafter: their penalty shall not be lightened nor shall they be helped.'),
  ('en.yusufali', 2, 87, 'We gave Moses the Book and followed him up with a succession of messengers; We gave Jesus the son of Mary Clear (Signs) and strengthened him with the holy spirit. Is it that whenever there comes to you a messenger with what ye yourselves desire not, ye are puffed up with pride?- Some ye called impostors, and others ye slay!'),
  ('en.yusufali', 2, 88, 'They say, "Our hearts are the wrappings (which preserve Allah\'s Word: we need no more)." Nay, Allah\'s curse is on them for their blasphemy: Little is it they believe.'),
  ('en.yusufali', 2, 89, 'And when there comes to them a Book from Allah, confirming what is with them,- although from of old they had prayed for victory against those without Faith,- when there comes to them that which they (should) have recognised, they refuse to believe in it but the curse of Allah is on those without Faith.'),
  ('en.yusufali', 2, 90, 'Miserable is the price for which they have sold their souls, in that they deny (the revelation) which Allah has sent down, in insolent envy that Allah of His Grace should send it to any of His servants He pleases: Thus have they drawn on themselves Wrath upon Wrath. And humiliating is the punishment of those who reject Faith.'),
  ('en.yusufali', 2, 91, 'When it is said to them, "Believe in what Allah Hath sent down, "they say, "We believe in what was sent down to us:" yet they reject all besides, even if it be Truth confirming what is with them. Say: "Why then have ye slain the prophets of Allah in times gone by, if ye did indeed believe?"'),
  ('en.yusufali', 2, 92, 'There came to you Moses with clear (Signs); yet ye worshipped the calf (Even) after that, and ye did behave wrongfully.'),
  ('en.yusufali', 2, 93, 'And remember We took your covenant and We raised above you (the towering height) of Mount (Sinai): (Saying): "Hold firmly to what We have given you, and hearken (to the Law)": They said:" We hear, and we disobey:" And they had to drink into their hearts (of the taint) of the calf because of their Faithlessness. Say: "Vile indeed are the behests of your Faith if ye have any faith!"'),
  ('en.yusufali', 2, 94, 'Say: "If the last Home, with Allah, be for you specially, and not for anyone else, then seek ye for death, if ye are sincere."'),
  ('en.yusufali', 2, 95, 'But they will never seek for death, on account of the (sins) which their hands have sent on before them. and Allah is well-acquainted with the wrong-doers.'),
  ('en.yusufali', 2, 96, 'Thou wilt indeed find them, of all people, most greedy of life,-even more than the idolaters: Each one of them wishes He could be given a life of a thousand years: But the grant of such life will not save him from (due) punishment. For Allah sees well all that they do.'),
  ('en.yusufali', 2, 97, 'Say: Whoever is an enemy to Gabriel-for he brings down the (revelation) to thy heart by Allah\'s will, a confirmation of what went before, and guidance and glad tidings for those who believe,-'),
  ('en.yusufali', 2, 98, 'Whoever is an enemy to Allah and His angels and messengers, to Gabriel and Michael,- Lo! Allah is an enemy to those who reject Faith.'),
  ('en.yusufali', 2, 99, 'We have sent down to thee Manifest Signs (ayat); and none reject them but those who are perverse.'),
  ('en.yusufali', 2, 100, 'Is it not (the case) that every time they make a covenant, some party among them throw it aside?- Nay, Most of them are faithless.'),
  ('en.yusufali', 2, 101, 'And when there came to them a messenger from Allah, confirming what was with them, a party of the people of the Book threw away the Book of Allah behind their backs, as if (it had been something) they did not know!'),
  ('en.yusufali', 2, 102, 'They followed what the evil ones gave out (falsely) against the power of Solomon: the blasphemers Were, not Solomon, but the evil ones, teaching men Magic, and such things as came down at babylon to the angels Harut and Marut. But neither of these taught anyone (Such things) without saying: "We are only for trial; so do not blaspheme." They learned from them the means to sow discord between man and wife. But they could not thus harm anyone except by Allah\'s permission. And they learned what harmed them, not what profited them. And they knew that the buyers of (magic) would have no share in the happiness of the Hereafter. And vile was the price for which they did sell their souls, if they but knew!'),
  ('en.yusufali', 2, 103, 'If they had kept their Faith and guarded themselves from evil, far better had been the reward from their Lord, if they but knew!'),
  ('en.yusufali', 2, 104, 'O ye of Faith! Say not (to the Messenger) words of ambiguous import, but words of respect; and hearken (to him): To those without Faith is a grievous punishment.'),
  ('en.yusufali', 2, 105, 'It is never the wish of those without Faith among the People of the Book, nor of the Pagans, that anything good should come down to you from your Lord. But Allah will choose for His special Mercy whom He will - for Allah is Lord of grace abounding.'),
  ('en.yusufali', 2, 106, 'None of Our revelations do We abrogate or cause to be forgotten, but We substitute something better or similar: Knowest thou not that Allah Hath power over all things?'),
  ('en.yusufali', 2, 107, 'Knowest thou not that to Allah belongeth the dominion of the heavens and the earth? And besides Him ye have neither patron nor helper.'),
  ('en.yusufali', 2, 108, 'Would ye question your Messenger as Moses was questioned of old? but whoever changeth from Faith to Unbelief, Hath strayed without doubt from the even way.'),
  ('en.yusufali', 2, 109, 'Quite a number of the People of the Book wish they could Turn you (people) back to infidelity after ye have believed, from selfish envy, after the Truth hath become Manifest unto them: But forgive and overlook, Till Allah accomplish His purpose; for Allah Hath power over all things.'),
  ('en.yusufali', 2, 110, 'And be steadfast in prayer and regular in charity: And whatever good ye send forth for your souls before you, ye shall find it with Allah: for Allah sees Well all that ye do.'),
  ('en.yusufali', 2, 111, 'And they say: "None shall enter Paradise unless he be a Jew or a Christian." Those are their (vain) desires. Say: "Produce your proof if ye are truthful."'),
  ('en.yusufali', 2, 112, 'Nay,-whoever submits His whole self to Allah and is a doer of good,- He will get his reward with his Lord; on such shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 2, 113, 'The Jews say: "The Christians have naught (to stand) upon; and the Christians say: "The Jews have naught (To stand) upon." Yet they (Profess to) study the (same) Book. Like unto their word is what those say who know not; but Allah will judge between them in their quarrel on the Day of Judgment.'),
  ('en.yusufali', 2, 114, 'And who is more unjust than he who forbids that in places for the worship of Allah, Allah\'s name should be celebrated?-whose zeal is (in fact) to ruin them? It was not fitting that such should themselves enter them except in fear. For them there is nothing but disgrace in this world, and in the world to come, an exceeding torment.'),
  ('en.yusufali', 2, 115, 'To Allah belong the east and the West: Whithersoever ye turn, there is the presence of Allah. For Allah is all-Pervading, all-Knowing.'),
  ('en.yusufali', 2, 116, 'They say: "Allah hath begotten a son": Glory be to Him.-Nay, to Him belongs all that is in the heavens and on earth: everything renders worship to Him.'),
  ('en.yusufali', 2, 117, 'To Him is due the primal origin of the heavens and the earth: When He decreeth a matter, He saith to it: "Be," and it is.'),
  ('en.yusufali', 2, 118, 'Say those without knowledge: "Why speaketh not Allah unto us? or why cometh not unto us a Sign?" So said the people before them words of similar import. Their hearts are alike. We have indeed made clear the Signs unto any people who hold firmly to Faith (in their hearts).'),
  ('en.yusufali', 2, 119, 'Verily We have sent thee in truth as a bearer of glad tidings and a warner: But of thee no question shall be asked of the Companions of the Blazing Fire.'),
  ('en.yusufali', 2, 120, 'Never will the Jews or the Christians be satisfied with thee unless thou follow their form of religion. Say: "The Guidance of Allah,-that is the (only) Guidance." Wert thou to follow their desires after the knowledge which hath reached thee, then wouldst thou find neither Protector nor helper against Allah.'),
  ('en.yusufali', 2, 121, 'Those to whom We have sent the Book study it as it should be studied: They are the ones that believe therein: Those who reject faith therein,- the loss is their own.'),
  ('en.yusufali', 2, 122, 'O Children of Israel! call to mind the special favour which I bestowed upon you, and that I preferred you to all others (for My Message).'),
  ('en.yusufali', 2, 123, 'Then guard yourselves against a Day when one soul shall not avail another, nor shall compensation be accepted from her nor shall intercession profit her nor shall anyone be helped (from outside).'),
  ('en.yusufali', 2, 124, 'And remember that Abraham was tried by his Lord with certain commands, which he fulfilled: He said: "I will make thee an Imam to the Nations." He pleaded: "And also (Imams) from my offspring!" He answered: "But My Promise is not within the reach of evil-doers."'),
  ('en.yusufali', 2, 125, 'Remember We made the House a place of assembly for men and a place of safety; and take ye the station of Abraham as a place of prayer; and We covenanted with Abraham and Isma\'il, that they should sanctify My House for those who compass it round, or use it as a retreat, or bow, or prostrate themselves (therein in prayer).'),
  ('en.yusufali', 2, 126, 'And remember Abraham said: "My Lord, make this a City of Peace, and feed its people with fruits,-such of them as believe in Allah and the Last Day." He said: "(Yea), and such as reject Faith,-for a while will I grant them their pleasure, but will soon drive them to the torment of Fire,- an evil destination (indeed)!"'),
  ('en.yusufali', 2, 127, 'And remember Abraham and Isma\'il raised the foundations of the House (With this prayer): "Our Lord! Accept (this service) from us: For Thou art the All-Hearing, the All-knowing.'),
  ('en.yusufali', 2, 128, '"Our Lord! make of us Muslims, bowing to Thy (Will), and of our progeny a people Muslim, bowing to Thy (will); and show us our place for the celebration of (due) rites; and turn unto us (in Mercy); for Thou art the Oft-Returning, Most Merciful.'),
  ('en.yusufali', 2, 129, '"Our Lord! send amongst them a Messenger of their own, who shall rehearse Thy Signs to them and instruct them in scripture and wisdom, and sanctify them: For Thou art the Exalted in Might, the Wise."'),
  ('en.yusufali', 2, 130, 'And who turns away from the religion of Abraham but such as debase their souls with folly? Him We chose and rendered pure in this world: And he will be in the Hereafter in the ranks of the Righteous.'),
  ('en.yusufali', 2, 131, 'Behold! his Lord said to him: "Bow (thy will to Me):" He said: "I bow (my will) to the Lord and Cherisher of the Universe."'),
  ('en.yusufali', 2, 132, 'And this was the legacy that Abraham left to his sons, and so did Jacob; "Oh my sons! Allah hath chosen the Faith for you; then die not except in the Faith of Islam."'),
  ('en.yusufali', 2, 133, 'Were ye witnesses when death appeared before Jacob? Behold, he said to his sons: "What will ye worship after me?" They said: "We shall worship Thy god and the god of thy fathers, of Abraham, Isma\'il and Isaac,- the one (True) Allah: To Him we bow (in Islam)."'),
  ('en.yusufali', 2, 134, 'That was a people that hath passed away. They shall reap the fruit of what they did, and ye of what ye do! Of their merits there is no question in your case!'),
  ('en.yusufali', 2, 135, 'They say: "Become Jews or Christians if ye would be guided (To salvation)." Say thou: "Nay! (I would rather) the Religion of Abraham the True, and he joined not gods with Allah."'),
  ('en.yusufali', 2, 136, 'Say ye: "We believe in Allah, and the revelation given to us, and to Abraham, Isma\'il, Isaac, Jacob, and the Tribes, and that given to Moses and Jesus, and that given to (all) prophets from their Lord: We make no difference between one and another of them: And we bow to Allah (in Islam)."'),
  ('en.yusufali', 2, 137, 'So if they believe as ye believe, they are indeed on the right path; but if they turn back, it is they who are in schism; but Allah will suffice thee as against them, and He is the All-Hearing, the All-Knowing.'),
  ('en.yusufali', 2, 138, '(Our religion is) the Baptism of Allah: And who can baptize better than Allah? And it is He Whom we worship.'),
  ('en.yusufali', 2, 139, 'Say: Will ye dispute with us about Allah, seeing that He is our Lord and your Lord; that we are responsible for our doings and ye for yours; and that We are sincere (in our faith) in Him?'),
  ('en.yusufali', 2, 140, 'Or do ye say that Abraham, Isma\'il Isaac, Jacob and the Tribes were Jews or Christians? Say: Do ye know better than Allah? Ah! who is more unjust than those who conceal the testimony they have from Allah? but Allah is not unmindful of what ye do!'),
  ('en.yusufali', 2, 141, 'That was a people that hath passed away. They shall reap the fruit of what they did, and ye of what ye do! Of their merits there is no question in your case:'),
  ('en.yusufali', 2, 142, 'The fools among the people will say: "What hath turned them from the Qibla to which they were used?" Say: To Allah belong both east and West: He guideth whom He will to a Way that is straight.'),
  ('en.yusufali', 2, 143, 'Thus, have We made of you an Ummat justly balanced, that ye might be witnesses over the nations, and the Messenger a witness over yourselves; and We appointed the Qibla to which thou wast used, only to test those who followed the Messenger from those who would turn on their heels (From the Faith). Indeed it was (A change) momentous, except to those guided by Allah. And never would Allah Make your faith of no effect. For Allah is to all people Most surely full of kindness, Most Merciful.'),
  ('en.yusufali', 2, 144, 'We see the turning of thy face (for guidance to the heavens: now Shall We turn thee to a Qibla that shall please thee. Turn then Thy face in the direction of the sacred Mosque: Wherever ye are, turn your faces in that direction. The people of the Book know well that that is the truth from their Lord. Nor is Allah unmindful of what they do.'),
  ('en.yusufali', 2, 145, 'Even if thou wert to bring to the people of the Book all the Signs (together), they would not follow Thy Qibla; nor art thou going to follow their Qibla; nor indeed will they follow each other\'s Qibla. If thou after the knowledge hath reached thee, Wert to follow their (vain) desires,-then wert thou Indeed (clearly) in the wrong.'),
  ('en.yusufali', 2, 146, 'The people of the Book know this as they know their own sons; but some of them conceal the truth which they themselves know.'),
  ('en.yusufali', 2, 147, 'The Truth is from thy Lord; so be not at all in doubt.'),
  ('en.yusufali', 2, 148, 'To each is a goal to which Allah turns him; then strive together (as in a race) Towards all that is good. Wheresoever ye are, Allah will bring you Together. For Allah Hath power over all things.'),
  ('en.yusufali', 2, 149, 'From whencesoever Thou startest forth, turn Thy face in the direction of the sacred Mosque; that is indeed the truth from the Lord. And Allah is not unmindful of what ye do.'),
  ('en.yusufali', 2, 150, 'So from whencesoever Thou startest forth, turn Thy face in the direction of the sacred Mosque; and wheresoever ye are, Turn your face thither: that there be no ground of dispute against you among the people, except those of them that are bent on wickedness; so fear them not, but fear Me; and that I may complete My favours on you, and ye May (consent to) be guided;'),
  ('en.yusufali', 2, 151, 'A similar (favour have ye already received) in that We have sent among you a Messenger of your own, rehearsing to you Our Signs, and sanctifying you, and instructing you in Scripture and Wisdom, and in new knowledge.'),
  ('en.yusufali', 2, 152, 'Then do ye remember Me; I will remember you. Be grateful to Me, and reject not Faith.'),
  ('en.yusufali', 2, 153, 'O ye who believe! seek help with patient perseverance and prayer; for Allah is with those who patiently persevere.'),
  ('en.yusufali', 2, 154, 'And say not of those who are slain in the way of Allah: "They are dead." Nay, they are living, though ye perceive (it) not.'),
  ('en.yusufali', 2, 155, 'Be sure we shall test you with something of fear and hunger, some loss in goods or lives or the fruits (of your toil), but give glad tidings to those who patiently persevere,'),
  ('en.yusufali', 2, 156, 'Who say, when afflicted with calamity: "To Allah We belong, and to Him is our return":-'),
  ('en.yusufali', 2, 157, 'They are those on whom (Descend) blessings from Allah, and Mercy, and they are the ones that receive guidance.'),
  ('en.yusufali', 2, 158, 'Behold! Safa and Marwa are among the Symbols of Allah. So if those who visit the House in the Season or at other times, should compass them round, it is no sin in them. And if any one obeyeth his own impulse to good,- be sure that Allah is He Who recogniseth and knoweth.'),
  ('en.yusufali', 2, 159, 'Those who conceal the clear (Signs) We have sent down, and the Guidance, after We have made it clear for the people in the Book,-on them shall be Allah\'s curse, and the curse of those entitled to curse,-'),
  ('en.yusufali', 2, 160, 'Except those who repent and make amends and openly declare (the Truth): To them I turn; for I am Oft-returning, Most Merciful.'),
  ('en.yusufali', 2, 161, 'Those who reject Faith, and die rejecting,- on them is Allah\'s curse, and the curse of angels, and of all mankind;'),
  ('en.yusufali', 2, 162, 'They will abide therein: Their penalty will not be lightened, nor will respite be their (lot).'),
  ('en.yusufali', 2, 163, 'And your Allah is One Allah: There is no god but He, Most Gracious, Most Merciful.'),
  ('en.yusufali', 2, 164, 'Behold! in the creation of the heavens and the earth; in the alternation of the night and the day; in the sailing of the ships through the ocean for the profit of mankind; in the rain which Allah Sends down from the skies, and the life which He gives therewith to an earth that is dead; in the beasts of all kinds that He scatters through the earth; in the change of the winds, and the clouds which they Trail like their slaves between the sky and the earth;- (Here) indeed are Signs for a people that are wise.'),
  ('en.yusufali', 2, 165, 'Yet there are men who take (for worship) others besides Allah, as equal (with Allah): They love them as they should love Allah. But those of Faith are overflowing in their love for Allah. If only the unrighteous could see, behold, they would see the penalty: that to Allah belongs all power, and Allah will strongly enforce the penalty.'),
  ('en.yusufali', 2, 166, 'Then would those who are followed clear themselves of those who follow (them): They would see the penalty, and all relations between them would be cut off.'),
  ('en.yusufali', 2, 167, 'And those who followed would say: "If only We had one more chance, We would clear ourselves of them, as they have cleared themselves of us." Thus will Allah show them (The fruits of) their deeds as (nothing but) regrets. Nor will there be a way for them out of the Fire.'),
  ('en.yusufali', 2, 168, 'O ye people! Eat of what is on earth, Lawful and good; and do not follow the footsteps of the evil one, for he is to you an avowed enemy.'),
  ('en.yusufali', 2, 169, 'For he commands you what is evil and shameful, and that ye should say of Allah that of which ye have no knowledge.'),
  ('en.yusufali', 2, 170, 'When it is said to them: "Follow what Allah hath revealed:" They say: "Nay! we shall follow the ways of our fathers." What! even though their fathers Were void of wisdom and guidance?'),
  ('en.yusufali', 2, 171, 'The parable of those who reject Faith is as if one were to shout Like a goat-herd, to things that listen to nothing but calls and cries: Deaf, dumb, and blind, they are void of wisdom.'),
  ('en.yusufali', 2, 172, 'O ye who believe! Eat of the good things that We have provided for you, and be grateful to Allah, if it is Him ye worship.'),
  ('en.yusufali', 2, 173, 'He hath only forbidden you dead meat, and blood, and the flesh of swine, and that on which any other name hath been invoked besides that of Allah. But if one is forced by necessity, without wilful disobedience, nor transgressing due limits,- then is he guiltless. For Allah is Oft-forgiving Most Merciful.'),
  ('en.yusufali', 2, 174, 'Those who conceal Allah\'s revelations in the Book, and purchase for them a miserable profit,- they swallow into themselves naught but Fire; Allah will not address them on the Day of Resurrection. Nor purify them: Grievous will be their penalty.'),
  ('en.yusufali', 2, 175, 'They are the ones who buy Error in place of Guidance and Torment in place of Forgiveness. Ah! what boldness (They show) for the Fire!'),
  ('en.yusufali', 2, 176, '(Their doom is) because Allah sent down the Book in truth but those who seek causes of dispute in the Book are in a schism Far (from the purpose).'),
  ('en.yusufali', 2, 177, 'It is not righteousness that ye turn your faces Towards east or West; but it is righteousness- to believe in Allah and the Last Day, and the Angels, and the Book, and the Messengers; to spend of your substance, out of love for Him, for your kin, for orphans, for the needy, for the wayfarer, for those who ask, and for the ransom of slaves; to be steadfast in prayer, and practice regular charity; to fulfil the contracts which ye have made; and to be firm and patient, in pain (or suffering) and adversity, and throughout all periods of panic. Such are the people of truth, the Allah-fearing.'),
  ('en.yusufali', 2, 178, 'O ye who believe! the law of equality is prescribed to you in cases of murder: the free for the free, the slave for the slave, the woman for the woman. But if any remission is made by the brother of the slain, then grant any reasonable demand, and compensate him with handsome gratitude, this is a concession and a Mercy from your Lord. After this whoever exceeds the limits shall be in grave penalty.'),
  ('en.yusufali', 2, 179, 'In the Law of Equality there is (saving of) Life to you, o ye men of understanding; that ye may restrain yourselves.'),
  ('en.yusufali', 2, 180, 'It is prescribed, when death approaches any of you, if he leave any goods that he make a bequest to parents and next of kin, according to reasonable usage; this is due from the Allah-fearing.'),
  ('en.yusufali', 2, 181, 'If anyone changes the bequest after hearing it, the guilt shall be on those who make the change. For Allah hears and knows (All things).'),
  ('en.yusufali', 2, 182, 'But if anyone fears partiality or wrong-doing on the part of the testator, and makes peace between (The parties concerned), there is no wrong in him: For Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 2, 183, 'O ye who believe! Fasting is prescribed to you as it was prescribed to those before you, that ye may (learn) self-restraint,-'),
  ('en.yusufali', 2, 184, '(Fasting) for a fixed number of days; but if any of you is ill, or on a journey, the prescribed number (Should be made up) from days later. For those who can do it (With hardship), is a ransom, the feeding of one that is indigent. But he that will give more, of his own free will,- it is better for him. And it is better for you that ye fast, if ye only knew.'),
  ('en.yusufali', 2, 185, 'Ramadhan is the (month) in which was sent down the Qur\'an, as a guide to mankind, also clear (Signs) for guidance and judgment (Between right and wrong). So every one of you who is present (at his home) during that month should spend it in fasting, but if any one is ill, or on a journey, the prescribed period (Should be made up) by days later. Allah intends every facility for you; He does not want to put to difficulties. (He wants you) to complete the prescribed period, and to glorify Him in that He has guided you; and perchance ye shall be grateful.'),
  ('en.yusufali', 2, 186, 'When My servants ask thee concerning Me, I am indeed close (to them): I listen to the prayer of every suppliant when he calleth on Me: Let them also, with a will, Listen to My call, and believe in Me: That they may walk in the right way.'),
  ('en.yusufali', 2, 187, 'Permitted to you, on the night of the fasts, is the approach to your wives. They are your garments and ye are their garments. Allah knoweth what ye used to do secretly among yourselves; but He turned to you and forgave you; so now associate with them, and seek what Allah Hath ordained for you, and eat and drink, until the white thread of dawn appear to you distinct from its black thread; then complete your fast Till the night appears; but do not associate with your wives while ye are in retreat in the mosques. Those are Limits (set by) Allah: Approach not nigh thereto. Thus doth Allah make clear His Signs to men: that they may learn self-restraint.'),
  ('en.yusufali', 2, 188, 'And do not eat up your property among yourselves for vanities, nor use it as bait for the judges, with intent that ye may eat up wrongfully and knowingly a little of (other) people\'s property.'),
  ('en.yusufali', 2, 189, 'They ask thee concerning the New Moons. Say: They are but signs to mark fixed periods of time in (the affairs of) men, and for Pilgrimage. It is no virtue if ye enter your houses from the back: It is virtue if ye fear Allah. Enter houses through the proper doors: And fear Allah: That ye may prosper.'),
  ('en.yusufali', 2, 190, 'Fight in the cause of Allah those who fight you, but do not transgress limits; for Allah loveth not transgressors.'),
  ('en.yusufali', 2, 191, 'And slay them wherever ye catch them, and turn them out from where they have Turned you out; for tumult and oppression are worse than slaughter; but fight them not at the Sacred Mosque, unless they (first) fight you there; but if they fight you, slay them. Such is the reward of those who suppress faith.'),
  ('en.yusufali', 2, 192, 'But if they cease, Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 2, 193, 'And fight them on until there is no more Tumult or oppression, and there prevail justice and faith in Allah; but if they cease, Let there be no hostility except to those who practise oppression.'),
  ('en.yusufali', 2, 194, 'The prohibited month for the prohibited month,- and so for all things prohibited,- there is the law of equality. If then any one transgresses the prohibition against you, Transgress ye likewise against him. But fear Allah, and know that Allah is with those who restrain themselves.'),
  ('en.yusufali', 2, 195, 'And spend of your substance in the cause of Allah, and make not your own hands contribute to (your) destruction; but do good; for Allah loveth those who do good.'),
  ('en.yusufali', 2, 196, 'And complete the Hajj or \'umra in the service of Allah. But if ye are prevented (From completing it), send an offering for sacrifice, such as ye may find, and do not shave your heads until the offering reaches the place of sacrifice. And if any of you is ill, or has an ailment in his scalp, (Necessitating shaving), (He should) in compensation either fast, or feed the poor, or offer sacrifice; and when ye are in peaceful conditions (again), if any one wishes to continue the \'umra on to the hajj, He must make an offering, such as he can afford, but if he cannot afford it, He should fast three days during the hajj and seven days on his return, Making ten days in all. This is for those whose household is not in (the precincts of) the Sacred Mosque. And fear Allah, and know that Allah Is strict in punishment.'),
  ('en.yusufali', 2, 197, 'For Hajj are the months well known. If any one undertakes that duty therein, Let there be no obscenity, nor wickedness, nor wrangling in the Hajj. And whatever good ye do, (be sure) Allah knoweth it. And take a provision (With you) for the journey, but the best of provisions is right conduct. So fear Me, o ye that are wise.'),
  ('en.yusufali', 2, 198, 'It is no crime in you if ye seek of the bounty of your Lord (during pilgrimage). Then when ye pour down from (Mount) Arafat, celebrate the praises of Allah at the Sacred Monument, and celebrate His praises as He has directed you, even though, before this, ye went astray.'),
  ('en.yusufali', 2, 199, 'Then pass on at a quick pace from the place whence it is usual for the multitude so to do, and ask for Allah\'s forgiveness. For Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 2, 200, 'So when ye have accomplished your holy rites, celebrate the praises of Allah, as ye used to celebrate the praises of your fathers,- yea, with far more Heart and soul. There are men who say: "Our Lord! Give us (Thy bounties) in this world!" but they will have no portion in the Hereafter.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 2, 201, 'And there are men who say: "Our Lord! Give us good in this world and good in the Hereafter, and defend us from the torment of the Fire!"'),
  ('en.yusufali', 2, 202, 'To these will be allotted what they have earned; and Allah is quick in account.'),
  ('en.yusufali', 2, 203, 'Celebrate the praises of Allah during the Appointed Days. But if any one hastens to leave in two days, there is no blame on him, and if any one stays on, there is no blame on him, if his aim is to do right. Then fear Allah, and know that ye will surely be gathered unto Him.'),
  ('en.yusufali', 2, 204, 'There is the type of man whose speech about this world\'s life May dazzle thee, and he calls Allah to witness about what is in his heart; yet is he the most contentious of enemies.'),
  ('en.yusufali', 2, 205, 'When he turns his back, His aim everywhere is to spread mischief through the earth and destroy crops and cattle. But Allah loveth not mischief.'),
  ('en.yusufali', 2, 206, 'When it is said to him, "Fear Allah", He is led by arrogance to (more) crime. Enough for him is Hell;-An evil bed indeed (To lie on)!'),
  ('en.yusufali', 2, 207, 'And there is the type of man who gives his life to earn the pleasure of Allah: And Allah is full of kindness to (His) devotees.'),
  ('en.yusufali', 2, 208, 'O ye who believe! Enter into Islam whole-heartedly; and follow not the footsteps of the evil one; for he is to you an avowed enemy.'),
  ('en.yusufali', 2, 209, 'If ye backslide after the clear (Signs) have come to you, then know that Allah is Exalted in Power, Wise.'),
  ('en.yusufali', 2, 210, 'Will they wait until Allah comes to them in canopies of clouds, with angels (in His train) and the question is (thus) settled? but to Allah do all questions go back (for decision).'),
  ('en.yusufali', 2, 211, 'Ask the Children of Israel how many clear (Signs) We have sent them. But if any one, after Allah\'s favour has come to him, substitutes (something else), Allah is strict in punishment.'),
  ('en.yusufali', 2, 212, 'The life of this world is alluring to those who reject faith, and they scoff at those who believe. But the righteous will be above them on the Day of Resurrection; for Allah bestows His abundance without measure on whom He will.'),
  ('en.yusufali', 2, 213, 'Mankind was one single nation, and Allah sent Messengers with glad tidings and warnings; and with them He sent the Book in truth, to judge between people in matters wherein they differed; but the People of the Book, after the clear Signs came to them, did not differ among themselves, except through selfish contumacy. Allah by His Grace Guided the believers to the Truth, concerning that wherein they differed. For Allah guided whom He will to a path that is straight.'),
  ('en.yusufali', 2, 214, 'Or do ye think that ye shall enter the Garden (of bliss) without such (trials) as came to those who passed away before you? they encountered suffering and adversity, and were so shaken in spirit that even the Messenger and those of faith who were with him cried: "When (will come) the help of Allah?" Ah! Verily, the help of Allah is (always) near!'),
  ('en.yusufali', 2, 215, 'They ask thee what they should spend (In charity). Say: Whatever ye spend that is good, is for parents and kindred and orphans and those in want and for wayfarers. And whatever ye do that is good, -Allah knoweth it well.'),
  ('en.yusufali', 2, 216, 'Fighting is prescribed for you, and ye dislike it. But it is possible that ye dislike a thing which is good for you, and that ye love a thing which is bad for you. But Allah knoweth, and ye know not.'),
  ('en.yusufali', 2, 217, 'They ask thee concerning fighting in the Prohibited Month. Say: "Fighting therein is a grave (offence); but graver is it in the sight of Allah to prevent access to the path of Allah, to deny Him, to prevent access to the Sacred Mosque, and drive out its members." Tumult and oppression are worse than slaughter. Nor will they cease fighting you until they turn you back from your faith if they can. And if any of you Turn back from their faith and die in unbelief, their works will bear no fruit in this life and in the Hereafter; they will be companions of the Fire and will abide therein.'),
  ('en.yusufali', 2, 218, 'Those who believed and those who suffered exile and fought (and strove and struggled) in the path of Allah,- they have the hope of the Mercy of Allah: And Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 2, 219, 'They ask thee concerning wine and gambling. Say: "In them is great sin, and some profit, for men; but the sin is greater than the profit." They ask thee how much they are to spend; Say: "What is beyond your needs." Thus doth Allah Make clear to you His Signs: In order that ye may consider-'),
  ('en.yusufali', 2, 220, '(Their bearings) on this life and the Hereafter. They ask thee concerning orphans. Say: "The best thing to do is what is for their good; if ye mix their affairs with yours, they are your brethren; but Allah knows the man who means mischief from the man who means good. And if Allah had wished, He could have put you into difficulties: He is indeed Exalted in Power, Wise."'),
  ('en.yusufali', 2, 221, 'Do not marry unbelieving women (idolaters), until they believe: A slave woman who believes is better than an unbelieving woman, even though she allures you. Nor marry (your girls) to unbelievers until they believe: A man slave who believes is better than an unbeliever, even though he allures you. Unbelievers do (but) beckon you to the Fire. But Allah beckons by His Grace to the Garden (of bliss) and forgiveness, and makes His Signs clear to mankind: That they may celebrate His praise.'),
  ('en.yusufali', 2, 222, 'They ask thee concerning women\'s courses. Say: They are a hurt and a pollution: So keep away from women in their courses, and do not approach them until they are clean. But when they have purified themselves, ye may approach them in any manner, time, or place ordained for you by Allah. For Allah loves those who turn to Him constantly and He loves those who keep themselves pure and clean.'),
  ('en.yusufali', 2, 223, 'Your wives are as a tilth unto you; so approach your tilth when or how ye will; but do some good act for your souls beforehand; and fear Allah. And know that ye are to meet Him (in the Hereafter), and give (these) good tidings to those who believe.'),
  ('en.yusufali', 2, 224, 'And make not Allah\'s (name) an excuse in your oaths against doing good, or acting rightly, or making peace between persons; for Allah is One Who heareth and knoweth all things.'),
  ('en.yusufali', 2, 225, 'Allah will not call you to account for thoughtlessness in your oaths, but for the intention in your hearts; and He is Oft-forgiving, Most Forbearing.'),
  ('en.yusufali', 2, 226, 'For those who take an oath for abstention from their wives, a waiting for four months is ordained; if then they return, Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 2, 227, 'But if their intention is firm for divorce, Allah heareth and knoweth all things.'),
  ('en.yusufali', 2, 228, 'Divorced women shall wait concerning themselves for three monthly periods. Nor is it lawful for them to hide what Allah Hath created in their wombs, if they have faith in Allah and the Last Day. And their husbands have the better right to take them back in that period, if they wish for reconciliation. And women shall have rights similar to the rights against them, according to what is equitable; but men have a degree (of advantage) over them. And Allah is Exalted in Power, Wise.'),
  ('en.yusufali', 2, 229, 'A divorce is only permissible twice: after that, the parties should either hold Together on equitable terms, or separate with kindness. It is not lawful for you, (Men), to take back any of your gifts (from your wives), except when both parties fear that they would be unable to keep the limits ordained by Allah. If ye (judges) do indeed fear that they would be unable to keep the limits ordained by Allah, there is no blame on either of them if she give something for her freedom. These are the limits ordained by Allah; so do not transgress them if any do transgress the limits ordained by Allah, such persons wrong (Themselves as well as others).'),
  ('en.yusufali', 2, 230, 'So if a husband divorces his wife (irrevocably), He cannot, after that, re-marry her until after she has married another husband and He has divorced her. In that case there is no blame on either of them if they re-unite, provided they feel that they can keep the limits ordained by Allah. Such are the limits ordained by Allah, which He makes plain to those who understand.'),
  ('en.yusufali', 2, 231, 'When ye divorce women, and they fulfil the term of their (\'Iddat), either take them back on equitable terms or set them free on equitable terms; but do not take them back to injure them, (or) to take undue advantage; if any one does that; He wrongs his own soul. Do not treat Allah\'s Signs as a jest, but solemnly rehearse Allah\'s favours on you, and the fact that He sent down to you the Book and Wisdom, for your instruction. And fear Allah, and know that Allah is well acquainted with all things.'),
  ('en.yusufali', 2, 232, 'When ye divorce women, and they fulfil the term of their (\'Iddat), do not prevent them from marrying their (former) husbands, if they mutually agree on equitable terms. This instruction is for all amongst you, who believe in Allah and the Last Day. That is (the course Making for) most virtue and purity amongst you and Allah knows, and ye know not.'),
  ('en.yusufali', 2, 233, 'The mothers shall give such to their offspring for two whole years, if the father desires to complete the term. But he shall bear the cost of their food and clothing on equitable terms. No soul shall have a burden laid on it greater than it can bear. No mother shall be Treated unfairly on account of her child. Nor father on account of his child, an heir shall be chargeable in the same way. If they both decide on weaning, by mutual consent, and after due consultation, there is no blame on them. If ye decide on a foster-mother for your offspring, there is no blame on you, provided ye pay (the mother) what ye offered, on equitable terms. But fear Allah and know that Allah sees well what ye do.'),
  ('en.yusufali', 2, 234, 'If any of you die and leave widows behind, they shall wait concerning themselves four months and ten days: When they have fulfilled their term, there is no blame on you if they dispose of themselves in a just and reasonable manner. And Allah is well acquainted with what ye do.'),
  ('en.yusufali', 2, 235, 'There is no blame on you if ye make an offer of betrothal or hold it in your hearts. Allah knows that ye cherish them in your hearts: But do not make a secret contract with them except in terms Honourable, nor resolve on the tie of marriage till the term prescribed is fulfilled. And know that Allah Knoweth what is in your hearts, and take heed of Him; and know that Allah is Oft-forgiving, Most Forbearing.'),
  ('en.yusufali', 2, 236, 'There is no blame on you if ye divorce women before consummation or the fixation of their dower; but bestow on them (A suitable gift), the wealthy according to his means, and the poor according to his means;- A gift of a reasonable amount is due from those who wish to do the right thing.'),
  ('en.yusufali', 2, 237, 'And if ye divorce them before consummation, but after the fixation of a dower for them, then the half of the dower (Is due to them), unless they remit it or (the man\'s half) is remitted by him in whose hands is the marriage tie; and the remission (of the man\'s half) is the nearest to righteousness. And do not forget Liberality between yourselves. For Allah sees well all that ye do.'),
  ('en.yusufali', 2, 238, 'Guard strictly your (habit of) prayers, especially the Middle Prayer; and stand before Allah in a devout (frame of mind).'),
  ('en.yusufali', 2, 239, 'If ye fear (an enemy), pray on foot, or riding, (as may be most convenient), but when ye are in security, celebrate Allah\'s praises in the manner He has taught you, which ye knew not (before).'),
  ('en.yusufali', 2, 240, 'Those of you who die and leave widows should bequeath for their widows a year\'s maintenance and residence; but if they leave (The residence), there is no blame on you for what they do with themselves, provided it is reasonable. And Allah is Exalted in Power, Wise.'),
  ('en.yusufali', 2, 241, 'For divorced women Maintenance (should be provided) on a reasonable (scale). This is a duty on the righteous.'),
  ('en.yusufali', 2, 242, 'Thus doth Allah Make clear His Signs to you: In order that ye may understand.'),
  ('en.yusufali', 2, 243, 'Didst thou not Turn by vision to those who abandoned their homes, though they were thousands (In number), for fear of death? Allah said to them: "Die": Then He restored them to life. For Allah is full of bounty to mankind, but Most of them are ungrateful.'),
  ('en.yusufali', 2, 244, 'Then fight in the cause of Allah, and know that Allah Heareth and knoweth all things.'),
  ('en.yusufali', 2, 245, 'Who is he that will loan to Allah a beautiful loan, which Allah will double unto his credit and multiply many times? It is Allah that giveth (you) Want or plenty, and to Him shall be your return.'),
  ('en.yusufali', 2, 246, 'Hast thou not Turned thy vision to the Chiefs of the Children of Israel after (the time of) Moses? they said to a prophet (That was) among them: "Appoint for us a king, that we May fight in the cause of Allah." He said: "Is it not possible, if ye were commanded to fight, that that ye will not fight?" They said: "How could we refuse to fight in the cause of Allah, seeing that we were turned out of our homes and our families?" but when they were commanded to fight, they turned back, except a small band among them. But Allah Has full knowledge of those who do wrong.'),
  ('en.yusufali', 2, 247, 'Their Prophet said to them: "Allah hath appointed Talut as king over you." They said: "How can he exercise authority over us when we are better fitted than he to exercise authority, and he is not even gifted, with wealth in abundance?" He said: "Allah hath Chosen him above you, and hath gifted him abundantly with knowledge and bodily prowess: Allah Granteth His authority to whom He pleaseth. Allah careth for all, and He knoweth all things."'),
  ('en.yusufali', 2, 248, 'And (further) their Prophet said to them: "A Sign of his authority is that there shall come to you the Ark of the covenant, with (an assurance) therein of security from your Lord, and the relics left by the family of Moses and the family of Aaron, carried by angels. In this is a symbol for you if ye indeed have faith."'),
  ('en.yusufali', 2, 249, 'When Talut set forth with the armies, he said: "Allah will test you at the stream: if any drinks of its water, He goes not with my army: Only those who taste not of it go with me: A mere sip out of the hand is excused." but they all drank of it, except a few. When they crossed the river,- He and the faithful ones with him,- they said: "This day We cannot cope with Goliath and his forces." but those who were convinced that they must meet Allah, said: "How oft, by Allah\'s will, Hath a small force vanquished a big one? Allah is with those who steadfastly persevere."'),
  ('en.yusufali', 2, 250, 'When they advanced to meet Goliath and his forces, they prayed: "Our Lord! Pour out constancy on us and make our steps firm: Help us against those that reject faith."'),
  ('en.yusufali', 2, 251, 'By Allah\'s will they routed them; and David slew Goliath; and Allah gave him power and wisdom and taught him whatever (else) He willed. And did not Allah Check one set of people by means of another, the earth would indeed be full of mischief: But Allah is full of bounty to all the worlds.'),
  ('en.yusufali', 2, 252, 'These are the Signs of Allah: we rehearse them to thee in truth: verily Thou art one of the messengers.'),
  ('en.yusufali', 2, 253, 'Those messengers We endowed with gifts, some above others: To one of them Allah spoke; others He raised to degrees (of honour); to Jesus the son of Mary We gave clear (Signs), and strengthened him with the holy spirit. If Allah had so willed, succeeding generations would not have fought among each other, after clear (Signs) had come to them, but they (chose) to wrangle, some believing and others rejecting. If Allah had so willed, they would not have fought each other; but Allah Fulfilleth His plan.'),
  ('en.yusufali', 2, 254, 'O ye who believe! Spend out of (the bounties) We have provided for you, before the Day comes when no bargaining (Will avail), nor friendship nor intercession. Those who reject Faith they are the wrong-doers.'),
  ('en.yusufali', 2, 255, 'Allah! There is no god but He,-the Living, the Self-subsisting, Eternal. No slumber can seize Him nor sleep. His are all things in the heavens and on earth. Who is there can intercede in His presence except as He permitteth? He knoweth what (appeareth to His creatures as) before or after or behind them. Nor shall they compass aught of His knowledge except as He willeth. His Throne doth extend over the heavens and the earth, and He feeleth no fatigue in guarding and preserving them for He is the Most High, the Supreme (in glory).'),
  ('en.yusufali', 2, 256, 'Let there be no compulsion in religion: Truth stands out clear from Error: whoever rejects evil and believes in Allah hath grasped the most trustworthy hand-hold, that never breaks. And Allah heareth and knoweth all things.'),
  ('en.yusufali', 2, 257, 'Allah is the Protector of those who have faith: from the depths of darkness He will lead them forth into light. Of those who reject faith the patrons are the evil ones: from light they will lead them forth into the depths of darkness. They will be companions of the fire, to dwell therein (For ever).'),
  ('en.yusufali', 2, 258, 'Hast thou not Turned thy vision to one who disputed with Abraham About his Lord, because Allah had granted him power? Abraham said: "My Lord is He Who Giveth life and death." He said: "I give life and death". Said Abraham: "But it is Allah that causeth the sun to rise from the east: Do thou then cause him to rise from the West." Thus was he confounded who (in arrogance) rejected faith. Nor doth Allah Give guidance to a people unjust.'),
  ('en.yusufali', 2, 259, 'Or (take) the similitude of one who passed by a hamlet, all in ruins to its roofs. He said: "Oh! how shall Allah bring it (ever) to life, after (this) its death?" but Allah caused him to die for a hundred years, then raised him up (again). He said: "How long didst thou tarry (thus)?" He said: (Perhaps) a day or part of a day." He said: "Nay, thou hast tarried thus a hundred years; but look at thy food and thy drink; they show no signs of age; and look at thy donkey: And that We may make of thee a sign unto the people, Look further at the bones, how We bring them together and clothe them with flesh." When this was shown clearly to him, he said: "I know that Allah hath power over all things."'),
  ('en.yusufali', 2, 260, 'When Abraham said: "Show me, Lord, how You will raise the dead, " He replied: "Have you no faith?" He said "Yes, but just to reassure my heart." Allah said, "Take four birds, draw them to you, and cut their bodies to pieces. Scatter them over the mountain-tops, then call them back. They will come swiftly to you. Know that Allah is Mighty, Wise."'),
  ('en.yusufali', 2, 261, 'The parable of those who spend their substance in the way of Allah is that of a grain of corn: it groweth seven ears, and each ear Hath a hundred grains. Allah giveth manifold increase to whom He pleaseth: And Allah careth for all and He knoweth all things.'),
  ('en.yusufali', 2, 262, 'Those who spend their substance in the cause of Allah, and follow not up their gifts with reminders of their generosity or with injury,-for them their reward is with their Lord: on them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 2, 263, 'Kind words and the covering of faults are better than charity followed by injury. Allah is free of all wants, and He is Most-Forbearing.'),
  ('en.yusufali', 2, 264, 'O ye who believe! cancel not your charity by reminders of your generosity or by injury,- like those who spend their substance to be seen of men, but believe neither in Allah nor in the Last Day. They are in parable like a hard, barren rock, on which is a little soil: on it falls heavy rain, which leaves it (Just) a bare stone. They will be able to do nothing with aught they have earned. And Allah guideth not those who reject faith.'),
  ('en.yusufali', 2, 265, 'And the likeness of those who spend their substance, seeking to please Allah and to strengthen their souls, is as a garden, high and fertile: heavy rain falls on it but makes it yield a double increase of harvest, and if it receives not Heavy rain, light moisture sufficeth it. Allah seeth well whatever ye do.'),
  ('en.yusufali', 2, 266, 'Does any of you wish that he should have a garden with date-palms and vines and streams flowing underneath, and all kinds of fruit, while he is stricken with old age, and his children are not strong (enough to look after themselves)- that it should be caught in a whirlwind, with fire therein, and be burnt up? Thus doth Allah make clear to you (His) Signs; that ye may consider.'),
  ('en.yusufali', 2, 267, 'O ye who believe! Give of the good things which ye have (honourably) earned, and of the fruits of the earth which We have produced for you, and do not even aim at getting anything which is bad, in order that out of it ye may give away something, when ye yourselves would not receive it except with closed eyes. And know that Allah is Free of all wants, and worthy of all praise.'),
  ('en.yusufali', 2, 268, 'The Evil one threatens you with poverty and bids you to conduct unseemly. Allah promiseth you His forgiveness and bounties. And Allah careth for all and He knoweth all things.'),
  ('en.yusufali', 2, 269, 'He granteth wisdom to whom He pleaseth; and he to whom wisdom is granted receiveth indeed a benefit overflowing; but none will grasp the Message but men of understanding.'),
  ('en.yusufali', 2, 270, 'And whatever ye spend in charity or devotion, be sure Allah knows it all. But the wrong-doers have no helpers.'),
  ('en.yusufali', 2, 271, 'If ye disclose (acts of) charity, even so it is well, but if ye conceal them, and make them reach those (really) in need, that is best for you: It will remove from you some of your (stains of) evil. And Allah is well acquainted with what ye do.'),
  ('en.yusufali', 2, 272, 'It is not required of thee (O Messenger), to set them on the right path, but Allah sets on the right path whom He pleaseth. Whatever of good ye give benefits your own souls, and ye shall only do so seeking the "Face" of Allah. Whatever good ye give, shall be rendered back to you, and ye shall not Be dealt with unjustly.'),
  ('en.yusufali', 2, 273, '(Charity is) for those in need, who, in Allah\'s cause are restricted (from travel), and cannot move about in the land, seeking (For trade or work): the ignorant man thinks, because of their modesty, that they are free from want. Thou shalt know them by their (Unfailing) mark: They beg not importunately from all the sundry. And whatever of good ye give, be assured Allah knoweth it well.'),
  ('en.yusufali', 2, 274, 'Those who (in charity) spend of their goods by night and by day, in secret and in public, have their reward with their Lord: on them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 2, 275, 'Those who devour usury will not stand except as stand one whom the Evil one by his touch Hath driven to madness. That is because they say: "Trade is like usury," but Allah hath permitted trade and forbidden usury. Those who after receiving direction from their Lord, desist, shall be pardoned for the past; their case is for Allah (to judge); but those who repeat (The offence) are companions of the Fire: They will abide therein (for ever).'),
  ('en.yusufali', 2, 276, 'Allah will deprive usury of all blessing, but will give increase for deeds of charity: For He loveth not creatures ungrateful and wicked.'),
  ('en.yusufali', 2, 277, 'Those who believe, and do deeds of righteousness, and establish regular prayers and regular charity, will have their reward with their Lord: on them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 2, 278, 'O ye who believe! Fear Allah, and give up what remains of your demand for usury, if ye are indeed believers.'),
  ('en.yusufali', 2, 279, 'If ye do it not, Take notice of war from Allah and His Messenger: But if ye turn back, ye shall have your capital sums: Deal not unjustly, and ye shall not be dealt with unjustly.'),
  ('en.yusufali', 2, 280, 'If the debtor is in a difficulty, grant him time Till it is easy for him to repay. But if ye remit it by way of charity, that is best for you if ye only knew.'),
  ('en.yusufali', 2, 281, 'And fear the Day when ye shall be brought back to Allah. Then shall every soul be paid what it earned, and none shall be dealt with unjustly.'),
  ('en.yusufali', 2, 282, 'O ye who believe! When ye deal with each other, in transactions involving future obligations in a fixed period of time, reduce them to writing Let a scribe write down faithfully as between the parties: let not the scribe refuse to write: as Allah Has taught him, so let him write. Let him who incurs the liability dictate, but let him fear His Lord Allah, and not diminish aught of what he owes. If they party liable is mentally deficient, or weak, or unable Himself to dictate, Let his guardian dictate faithfully, and get two witnesses, out of your own men, and if there are not two men, then a man and two women, such as ye choose, for witnesses, so that if one of them errs, the other can remind her. The witnesses should not refuse when they are called on (For evidence). Disdain not to reduce to writing (your contract) for a future period, whether it be small or big: it is juster in the sight of Allah, More suitable as evidence, and more convenient to prevent doubts among yourselves but if it be a transaction which ye carry out on the spot among yourselves, there is no blame on you if ye reduce it not to writing. But take witness whenever ye make a commercial contract; and let neither scribe nor witness suffer harm. If ye do (such harm), it would be wickedness in you. So fear Allah; For it is Good that teaches you. And Allah is well acquainted with all things. If ye are on a journey, and cannot find a scribe, a pledge with possession (may serve the purpose). And if one of you deposits a thing on trust with another, let the trustee (faithfully) discharge his trust, and let him Fear his Lord conceal not evidence; for whoever conceals it, - his heart is tainted with sin. And Allah knoweth all that ye do.'),
  ('en.yusufali', 2, 283, 'If ye are on a journey, and cannot find a scribe, a pledge with possession (may serve the purpose). And if one of you deposits a thing on trust with another, Let the trustee (Faithfully) discharge His trust, and let him fear his Lord. Conceal not evidence; for whoever conceals it,- His heart is tainted with sin. And Allah Knoweth all that ye do.'),
  ('en.yusufali', 2, 284, 'To Allah belongeth all that is in the heavens and on earth. Whether ye show what is in your minds or conceal it, Allah Calleth you to account for it. He forgiveth whom He pleaseth, and punisheth whom He pleaseth, for Allah hath power over all things.'),
  ('en.yusufali', 2, 285, 'The Messenger believeth in what hath been revealed to him from his Lord, as do the men of faith. Each one (of them) believeth in Allah, His angels, His books, and His messengers. "We make no distinction (they say) between one and another of His messengers." And they say: "We hear, and we obey: (We seek) Thy forgiveness, our Lord, and to Thee is the end of all journeys."'),
  ('en.yusufali', 2, 286, 'On no soul doth Allah Place a burden greater than it can bear. It gets every good that it earns, and it suffers every ill that it earns. (Pray:) "Our Lord! Condemn us not if we forget or fall into error; our Lord! Lay not on us a burden Like that which Thou didst lay on those before us; Our Lord! Lay not on us a burden greater than we have strength to bear. Blot out our sins, and grant us forgiveness. Have mercy on us. Thou art our Protector; Help us against those who stand against faith."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 2, 1, 'Alif-Laaam-Meeem'),
  ('en.transliteration', 2, 2, 'Zaalikal Kitaabu laa raiba feeh; udal lilmuttaqeen'),
  ('en.transliteration', 2, 3, 'Allazeena yu\'minoona bilghaibi wa yuqeemoonas salaata wa mimmaa razaqnaahum yunfiqoon'),
  ('en.transliteration', 2, 4, 'Wallazeena yu\'minoona bimaa unzila ilaika wa maaa unzila min qablika wa bil Aakhirati hum yooqinoon'),
  ('en.transliteration', 2, 5, 'Ulaaa\'ika \'alaa hudam mir rabbihim wa ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 2, 6, 'Innal lazeena kafaroo sawaaa\'un \'alaihim \'a-anzar tahum am lam tunzirhum laa yu\'minoon'),
  ('en.transliteration', 2, 7, 'Khatamal laahu \'alaa quloobihim wa \'alaa sam\'i-him wa \'alaaa absaarihim ghishaa watunw wa lahum \'azaabun \'azeem'),
  ('en.transliteration', 2, 8, 'Wa minan naasi mai yaqoolu aamannaa billaahi wa bil yawmil aakhiri wa maa hum bimu\'mineen'),
  ('en.transliteration', 2, 9, 'Yukhaadi\'oonal laaha wallazeena aamanoo wa maa yakhda\'oona illaaa anfusahum wa maa yash\'uroon'),
  ('en.transliteration', 2, 10, 'Fee quloobihim mara dun fazzdahumul laahu maradan wa lahum \'azaabun aleemum bimaa kaanoo yakziboon'),
  ('en.transliteration', 2, 11, 'Wa izaa qeela lahum laa tufsidoo fil ardi qaalo innamaa nahnu muslihoon'),
  ('en.transliteration', 2, 12, 'Alaaa innahum humul mufsidoona wa laakil laa yash\'uroon'),
  ('en.transliteration', 2, 13, 'Wa izaa qeela lahum aaminoo kamaaa aamanan naasu qaalooo anu\'minu kamaaa aamanas sufahaaa\'; alaaa innahum humus sufahaaa\'u wa laakil laa ya\'lamoon'),
  ('en.transliteration', 2, 14, 'Wa izaa laqul lazeena aamanoo qaalooo aamannaa wa izaa khalw ilaa shayaateenihim qaalooo innaa ma\'akum innamaa nahnu mustahzi\'oon'),
  ('en.transliteration', 2, 15, 'Allahu yastahzi\'u bihim wa yamudduhum fee tughyaanihim ya\'mahoon'),
  ('en.transliteration', 2, 16, 'Ulaaa\'ikal lazeenash tara wud dalaalata bilhudaa famaa rabihat tijaaratuhum wa maa kaanoo muhtadeen'),
  ('en.transliteration', 2, 17, 'Masaluhum kamasalillazis tawqada naaran falammaaa adaaa\'at maa hawlahoo zahabal laahu binoorihim wa tarakahum fee zulumaatil laa yubsiroon'),
  ('en.transliteration', 2, 18, 'Summum bukmun \'umyun fahum laa yarji\'oon'),
  ('en.transliteration', 2, 19, 'Aw kasaiyibim minas samaaa\'i feehi zulumaatunw wa ra\'dunw wa barq, yaj\'aloona asaabi\'ahum feee aazaanihim minas sawaa\'iqi hazaral mawt\' wallaahu muheetum bilkaafireen'),
  ('en.transliteration', 2, 20, 'Yakaadul barqu yakhtafu absaarahum kullamaaa adaaa\'a lahum mashaw feehi wa izaaa azlama \'alaihim qaamoo; wa law shaaa\'al laahu lazahaba bisam\'ihim wa absaarihim; innal laaha \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 2, 21, 'Yaaa aiyuhan naasu\'budoo Rabbakumul lazee khalaqakum wallazeena min qablikum la\'allakum tattaqoon'),
  ('en.transliteration', 2, 22, 'Allazee ja\'ala lakumul arda firaashanw wassamaaa\'a binaaa \'anw wa anzala minassamaaa\'i maaa\'an fa akhraja bihee minas samaraati rizqal lakum falaa taj\'aloo lillaahi andaadanw wa antum ta\'lamoon'),
  ('en.transliteration', 2, 23, 'Wa in kuntum fee raibim mimmaa nazzalnaa \'alaa \'abdinaa fatoo bi Sooratim mim mislihee wad\'oo shuhadaaa\'akum min doonil laahi in kuntum saadiqeen'),
  ('en.transliteration', 2, 24, 'Fail lam taf\'aloo wa lan taf\'aloo fattaqun Naaral latee waqooduhan naasu walhijaaratu u\'iddat lilkaafireen'),
  ('en.transliteration', 2, 25, 'Wa bashshiril lazeena aamanoo wa \'amilus saalihaati anna lahum jannaatin tajree min tahtihal anhaaru kullamaa riziqoo minhaa min samaratir rizqan qaaloo haazal lazee ruziqnaa min qablu wa utoo bihee mutashaabihaa, wa lahum feehaaa azwaajum mutahhara tunw wa hum feehaa khaalidoon'),
  ('en.transliteration', 2, 26, 'Innal laaha laa yastahyeee ai yadriba masalam maa ba\'oodatan famaa fawqahaa; faammal lazeena aamanoo faya\'lamoona annahul haqqu mir rabbihim wa ammal lazeena kafaroo fayaqooloona maazaaa araadal laahu bihaazaa masalaa; yudillu bihee kaseeranw wa yahdee bihee kaseeraa; wa maa yudillu biheee illal faasiqeen'),
  ('en.transliteration', 2, 27, 'Allazeena yanqudoona \'ahdal laahi mim ba\'di meesaaqihee wa yaqt\'oona maaa amaral laahu biheee ai yoosala wa yufsidoona fil ard; ulaaa\'ika hum khaasirron'),
  ('en.transliteration', 2, 28, 'Kaifa takfuroona billaahi wa kuntum amwaatan fa ahyaakum summa yumeetukum summa yuhyeekum summaa ilaihi turja\'oon'),
  ('en.transliteration', 2, 29, 'Huwal lazee khalaqa lakum maa fil ardi jamee\'an summas tawaaa ilas samaaa\'i fasaw waahunna sab\'a samaa waat; wa Huwa bikulli shai\'in Aleem'),
  ('en.transliteration', 2, 30, 'Wa iz qaala rabbuka lil malaaa\'ikati innee jaa\'ilun fil ardi khaleefatan qaalooo ataj\'alu feehaa mai yufsidu feehaa wa yasfikud dimaaa\'a wa nahnu nusabbihu bihamdika wa nuqaddisu laka qaala inneee a\'lamu maa laa ta\'lamoon'),
  ('en.transliteration', 2, 31, 'Wa \'allama Aadamal asmaaa\'a kullahaa summa \'aradahum \'alal malaaa\'ikati faqaala ambi\'oonee bias maaa\'i haaa\'ulaaa\'i in kuntum saadiqeen'),
  ('en.transliteration', 2, 32, 'Qaaloo subhaanaka laa \'ilma lanaaa illaa maa \'allamtanaaa innaka antal\'aleemul hakeem'),
  ('en.transliteration', 2, 33, 'Qaala yaaa Aadamu ambi\' hum biasmaaa\'ihimfalammaaa amba ahum bi asmaaa\'ihim qaala alam aqul lakum inneee a\'lamu ghaibas samaawaati wal ardi wa a\'lamu maa tubdoona wa maa kuntum taktumoon'),
  ('en.transliteration', 2, 34, 'Wa iz qulnaa lilmalaaa\'i katis judoo liAadama fasajadooo illaaa Ibleesa abaa wastakbara wa kaana minal kaafireen'),
  ('en.transliteration', 2, 35, 'Wa qulnaa yaaa Aadamus kun anta wa zawjukal jannata wa kulaa minhaa raghadan haisu shi\'tumaa wa laa taqabaa haazihish shajarata fatakoonaa minaz zaalimeen'),
  ('en.transliteration', 2, 36, 'Fa azallahumash Shaitaanu \'anhaa fa akhrajahumaa mimmaa kaanaa fee wa qulnah bitoo ba\'dukum liba\'din \'aduwwunw wa lakum fil ardi mustaqarrunw wa mataa\'un ilaa heen'),
  ('en.transliteration', 2, 37, 'Fatalaqqaaa Aadamu mir Rabbihee Kalimaatin fataaba \'alayh; innahoo Huwat Tawwaabur Raheem'),
  ('en.transliteration', 2, 38, 'Qulnah bitoo minhaa jamee \'an fa immaa yaatiyannakum minnee hudan faman tabi\'a hudaaya falaa khawfun \'alaihim wa laa hum yahza noon'),
  ('en.transliteration', 2, 39, 'Wallazeena kafaroo wa kaz zabooo bi aayaatinaa ulaaa\'ika Ashaabun Naari hum feehaa khaalidoon'),
  ('en.transliteration', 2, 40, 'Yaa Baneee Israaa\'eelaz kuroo ni\'matiyal lateee an\'amtu \'alaikum wa awfoo bi\'Ahdeee oofi bi ahdikum wa iyyaaya farhaboon'),
  ('en.transliteration', 2, 41, 'Wa aaminoo bimaaa anzaltu musaddiqal limaa ma\'akum wa laa takoonooo awwala kaafirim bihee wa laa tashtaroo bi Aayaatee samanan qaleelanw wa iyyaaya fattaqoon'),
  ('en.transliteration', 2, 42, 'Wa laa talbisul haqqa bilbaatili wa taktumul haqqa wa antum ta\'lamoon'),
  ('en.transliteration', 2, 43, 'Wa aqeemus salaata wa aatuz zakaata warka\'oo ma\'ar raaki\'een'),
  ('en.transliteration', 2, 44, 'Ataamuroonan naasa bilbirri wa tansawna anfusakum wa antum tatloonal Kitaab; afalaa ta\'qiloon'),
  ('en.transliteration', 2, 45, 'Wasta\'eenoo bissabri was Salaah; wa innahaa lakabee ratun illaa alal khaashi\'een'),
  ('en.transliteration', 2, 46, 'Allazeena yazunnoona annahum mulaaqoo Rabbihim wa annahum ilaihi raaji\'oon'),
  ('en.transliteration', 2, 47, 'Yaa Baneee Israaa\'eelaz kuroo ni\'matiyal lateee an\'amtu \'alaikum wa annee faddaltukum \'alal \'aalameen'),
  ('en.transliteration', 2, 48, 'Wattaqoo Yawmal laa tajzee nafsun \'an nafsin shai\'anw wa laa yuqbalu minhaa shafaa\'atunw wa laa yu\'khazu minhaa \'adlunw wa laa hum yunsaroon'),
  ('en.transliteration', 2, 49, 'Wa iz najjainaakum min Aali Fir\'awna yasoomoonakum sooo\'al azaabi yuzabbihoona abuaaa\'akum wa yastahyoona nisaaa\'akum; wa fee zaalikum balaaa\'um mir Rabbikum \'azeem'),
  ('en.transliteration', 2, 50, 'Wa iz faraqnaa bikumul bahra fa anjainaakum wa agh-raqnaaa Aala Fir\'awna wa antum tanzuroon'),
  ('en.transliteration', 2, 51, 'Wa iz waa\'adnaa Moosaaa arba\'eena lailatan summattakhaztumul \'ijla mim ba\'dihee wa antum zaalimoon'),
  ('en.transliteration', 2, 52, 'Summa \'afawnaa \'ankum mim ba\'di zaalika la\'allakum tashkuroon'),
  ('en.transliteration', 2, 53, 'Wa iz aatainaa Moosal kitaaba wal Furqaana la\'allakum tahtadoon'),
  ('en.transliteration', 2, 54, 'Wa iz qaala Moosaa liqawmihee yaa qawmi innakum zalamtum anfusakum bittikhaa zikumul \'ijla fatoobooo ilaa Baari\'ikum faqtulooo anfusakum zaalikum khairul lakum \'inda Baari\'ikum fataaba \'alaikum; innahoo Huwat Tawwaabur Raheem'),
  ('en.transliteration', 2, 55, 'Wa iz qultum yaa Moosaa lan nu\'mina laka hattaa naral laaha jahratan fa akhazat kumus saa\'iqatu wa antum tanzuroon'),
  ('en.transliteration', 2, 56, 'Summa ba\'asnaakum mim ba\'di mawtikum la\'allakum tashkuroon'),
  ('en.transliteration', 2, 57, 'Wa zallalnaa \'alaikumul ghamaama wa anzalnaa \'alaikumul Manna was Salwaa kuloo min taiyibaati maa razaqnaakum wa maa zalamoonaa wa laakin kaanooo anfusahum yazlimoon'),
  ('en.transliteration', 2, 58, 'Wa iz qulnad khuloo haazihil qaryata fakuloo minhaa haisu shi\'tum raghadanw wadkhulul baaba sujjadanw wa qooloo hittatun naghfir lakum khataayaakum; wa sanazeedul muhsineen'),
  ('en.transliteration', 2, 59, 'Fabaddalal lazeena zalamoo qawlan ghairal lazee qeela lahum fa anzalnaa \'alal lazeena zalamoo rijzam minas samaaa\'i bimaa kaanoo yafsuqoon'),
  ('en.transliteration', 2, 60, 'Wa izis tasqaa Moosaa liqawmihee faqulnad rib bi\'asaakal hajara fanfajarat minhusnataaa \'ashrata \'aynan qad \'alima kullu unaasim mash rabahum kuloo washraboo mir rizqil laahi wa laa ta\'saw fil ardi mufsideen'),
  ('en.transliteration', 2, 61, 'Wa iz qultum yaa Moosaa lan nasbira \'alaa ta\'aaminw waahidin fad\'u lanaa rabbaka yukhrij lanaa mimmaa tumbitul ardu mimbaqlihaa wa qis saaa\'ihaa wa foomihaa wa \'adasihaa wa basalihaa qaala atastabdiloonal lazee huwa adnaa billazee huwa khayr; ihbitoo misran fa inna lakum maa sa altum; wa duribat \'alaihimuz zillatu walmaskanatu wa baaa\'oo bighadabim minal laah; zaalika bi annahum kaano yakfuroona bi aayaatil laahi wa yaqtuloonan Nabiyyeena bighairil haqq; zaalika bimaa \'asaw wa kaanoo ya\'tadoon'),
  ('en.transliteration', 2, 62, 'Innal lazeena aamanoo wallazeena haadoo wan nasaaraa was Saabi\'eena man aamana billaahi wal yawmil aakhiri wa \'amila saalihan falahum ajruhum \'inda Rabbihim wa laa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 2, 63, 'Wa iz akhaznaa meesaaqakum wa rafa\'naa fawqakumut Toora khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la\'allakum tattaqoon'),
  ('en.transliteration', 2, 64, 'Summa tawallaitum mim ba\'di zaalika falawlaa fadlul laahi \'alaikum wa rahmatuhoo lakuntum minal khaasireen'),
  ('en.transliteration', 2, 65, 'Wa laqad \'alimtumul lazeena\'-tadaw minkum fis Sabti faqulnaa lahum koonoo qiradatan khaasi\'een'),
  ('en.transliteration', 2, 66, 'Faja\'alnaahaa nakaalal limaa baina yadihaa wa maa khalfahaa wa maw\'izatal lilmuttaqeen'),
  ('en.transliteration', 2, 67, 'Wa iz qaala Moosaa liqawmiheee innal laaha yaamurukum an tazbahoo baqaratan qaalooo atattakhizunna huzuwan qaala a\'oozu billaahi an akoona minal jaahileen'),
  ('en.transliteration', 2, 68, 'Qaalud-\'u lanaa rabbaka yubaiyil lanaa maa hee; qaala innahoo yaqoolu innahaa baqaratul laa faaridunw wa laa bikrun \'awaanum baina zaalika faf\'aloo maa tu\'maroon'),
  ('en.transliteration', 2, 69, 'Qaalud-\'u lanaa rabaaka yubaiyil lanaa maa lawnuhaa; qaala innahoo yaqoolu innahaa baqaratun safraaa\'u faqi\'ul lawnuhaa tasurrunnaazireen'),
  ('en.transliteration', 2, 70, 'Qaalud-\'u lanaa rabbaka yubaiyil lanaa maa hiya innal baqara tashaabaha \'alainaa wa innaaa in shaaa\'al laahu lamuhtadoon'),
  ('en.transliteration', 2, 71, 'Qaala innahoo yaqoolu innahaa baqaratul laa zaloolun tuseerul arda wa laa tasqil harsa musallamatullaa shiyata feehaa; qaalul \'aana jita bilhaqq; fazabahoohaa wa maa kaado yaf\'aloon'),
  ('en.transliteration', 2, 72, 'Wa iz qataltum nafsan faddaara\'tum feehaa wallaahu mukrijum maa kuntum taktumoon'),
  ('en.transliteration', 2, 73, 'Faqulnad riboohu biba\'dihaa; kazaalika yuhyil laa hul mawtaa wa yureekum aayaatihee la\'allakum ta\'qiloon'),
  ('en.transliteration', 2, 74, 'Summa qasat quloobukum mim ba\'di zaalika fahiya kalhijaarati aw-ashaadu qaswah; wa inna minal hijaarati lamaa yatafajjaru minhul anhaar; wa inna minhaa lamaa yash shaqqaqu fayakhruju minhul maaa\'; wa inna minhaa lamaa yahbitu min khashyatil laa; wa mal laahu bighaafilin \'ammaa ta\'maloon'),
  ('en.transliteration', 2, 75, 'Afatatma\'oona ai yu\'minoo lakum wa qad kaana fareequm minhum yasma\'oona Kalaamal laahi summa yuharri foonahoo mim ba\'di maa\'aqaloohu wa hum ya\'lamoon'),
  ('en.transliteration', 2, 76, 'Wa izaa laqul lazeena aamanoo qaalooo aamannaa wa izaakhalaa ba\'duhum ilaa ba\'din qaalooo atuhaddisoonahum bimaa fatahal laahu \'alaikum liyuhaajjookum bihee \'inda rabbikum; afalaa ta\'qiloon'),
  ('en.transliteration', 2, 77, 'Awalaa ya\'lamoona annal laaha ya\'lamu maa yusirroona wa maa yu\'linoon'),
  ('en.transliteration', 2, 78, 'Wa minhum ummiyyoona laa ya\'lamoonal kitaaba illaaa amaaniyya wa in hum illaa yazunnoon'),
  ('en.transliteration', 2, 79, 'Fawailul lillazeena yaktuboonal kitaaba bi aydddhim summa yaqooloona haazaa min \'indil laahi liyashtaroo bihee samanan qaleelan fawilul lahum mimaa katabat aydeehim wa wailul lahum mimmaa yaksiboon'),
  ('en.transliteration', 2, 80, 'Wa qaaloo lan tamassanan Naaru illaaa ayyaamam ma\'doo dah; qul attakhaztum \'indal laahi \'ahdan falai yukhlifal laahu \'ahdahooo am taqooloona \'alal laahi maa laa ta\'lamoon'),
  ('en.transliteration', 2, 81, 'Balaa man kasaba sayyi\'atanw wa ahaatat bihee khateee\'atuhoo fa-ulaaa\'ika Ashaabun Naari hum feehaa khaalidoon'),
  ('en.transliteration', 2, 82, 'Wallazeena aamanoo wa \'amilus saalihaati ulaaa\'ika Ashaabul Jannati hum feeha khaalidoon'),
  ('en.transliteration', 2, 83, 'Wa iz akhaznaa meesaaqa Baneee Israaa\'eela laa ta\'budoona illal laaha wa bil waalidaini ihsaananw wa zil qurbaa walyataamaa walmasaakeeni wa qooloo linnaasi husnanw wa aqeemus salaata wa aatuzZakaata summa tawallitum illaa qaleelam minkum wa antum mu\'ridoon'),
  ('en.transliteration', 2, 84, 'Wa iz akhaznaa meesaa qakum laa tasfikoona dimaaa\'akum wa laa tukrijoona anfusakum min diyaarikum summa aqrartum wa antum tashhadoon'),
  ('en.transliteration', 2, 85, 'Summa antum haaa\'ulaaa\'i taqtuloona anfusakum wa tukhrijoona fareeqam minkum min diyaarihim tazaaharoona \'alaihim bil ismi wal\'udwaani wa iny yaatookum usaaraa tufaadoohum wahuwa muharramun \'alaikum ikhraajuhum; afatu\' mi-noona biba\'dil Kitaabi wa takfuroona biba\'d; famaa jazaaa\'u mai yaf\'alu zaalika minkum illaa khizyun fil hayaatid-dunyaa wa yawmal qiyaamati yuraddoona ilaaa ashaddil \'azaab; wa mal laahu bighaafilin \'ammaa ta\'maloon'),
  ('en.transliteration', 2, 86, 'Ulaaa\'ikal lazeenash tarawul hayaatad dunyaa bil aakhirati falaa yukhaffafu \'anhumul \'azaabu wa laa hum yunsaroon'),
  ('en.transliteration', 2, 87, 'Wa laqad aatainaa Moosal Kitaaba wa qaffainaa mim ba\'dihee bir Rusuli wa aatainaa \'Eesab-na-Maryamal baiyinaati wa ayyadnaahu bi Roohil Qudus; afakullamaa jaaa\'akum Rasoolum bimaa laa tahwaaa anfusukumus takbartum fafareeqan kazzabtum wa fareeqan taqtuloon'),
  ('en.transliteration', 2, 88, 'Wa qaaloo quloobunaa ghulf; bal la\'anahumul laahu bikufrihim faqaleelam maa yu\'minoon'),
  ('en.transliteration', 2, 89, 'Wa lammaa jaaa\'ahum Kitaabum min \'indil laahi musaddiqul limaa ma\'ahum wa kaanoo min qablu yastaftihoona \'alal lazeena kafaroo falammaa jaaa\'ahum maa \'arafoo kafaroo bih; fala \'natul laahi \'alal kaafireen'),
  ('en.transliteration', 2, 90, 'Bi\'samash taraw biheee anfusahum ai yakfuroo bimaaa anzalal laahu baghyan ai yunazzilal laahu min fadlilhee \'alaa mai yashaaa\'u min ibaadihee fabaaa\'oo bighadabin \'alaa ghadab; wa lilkaafireena \'azaabum muheen'),
  ('en.transliteration', 2, 91, 'Wa izaa qeela lahum aaminoo bimaaa anzalal laahu qaaloo nu\'minu bimaaa unzila \'alainaa wa yakfuroona bimaa waraaa\'ahoo wa huwal haqqu musaddiqal limaa ma\'ahum; qul falima taqtuloona Ambiyaaa\'al laahi min qablu in kuntum mu\'mineen'),
  ('en.transliteration', 2, 92, 'Wa laqad jaaa\'akum Moosa bilbaiyinaati summat takhaztunmul \'ijla mim ba\'dihee wa antum zaalimoon'),
  ('en.transliteration', 2, 93, 'Wa iz akhaznaa meesaaqakum wa rafa\'naa fawqa kumut Toora khuzoo maaa aatainaakum biquwwatinw wasma\'oo qaaloo sami\'naa wa \'asainaa wa ushriboo fee quloobihimul \'ijla bikufrihim; qul bi\'samaa yaamurukum biheee eemaanukum in kuntum m\'mineen'),
  ('en.transliteration', 2, 94, 'Qul in kaanat lakumud Daarul Aakhiratu \'indal laahi khaalisatam min doonin naasi fatamannawul mawta in kuntum saadiqeen'),
  ('en.transliteration', 2, 95, 'Wa lai yatamannawhu abadam bimaa qaddamat aydeehim; wallaahu \'aleemum bizzaalimeen'),
  ('en.transliteration', 2, 96, 'Wa latajidannahum ahrasannaasi \'alaa hayaatinw wa minal lazeena ashrakoo; yawaddu ahaduhum law yu\'ammaru alfa sanatinw wa maa huwa bi muzahzihihee minal \'azaabi ai yu\'ammar; wallaahu baseerum bimaa ya\'maloon'),
  ('en.transliteration', 2, 97, 'Qul man kaana \'aduwwal li Jibreela fainnahoo nazzalahoo \'alaa qalbika bi iznil laahi musaddiqal limaa baina yadihi wa hudanw wa bushraa lilmu\'mineen'),
  ('en.transliteration', 2, 98, 'Man kaana \'aduwwal lillaahi wa malaaa\'ikatihee wa Rusulihee wa Jibreela wa Meekaala fa innal laaha \'aduwwul lilkaafireen'),
  ('en.transliteration', 2, 99, 'Wa laqad anzalnaaa ilaika Aayaatim baiyinaatinw wa maa yakfuru bihaaa illal faasiqoon'),
  ('en.transliteration', 2, 100, 'Awa kullamaa \'aahadoo ahdan nabazahoo fareequm minhum; bal aksaruhum laa u\'minoon'),
  ('en.transliteration', 2, 101, 'Wa lammaa jaaa\'ahum Rasoolum min \'indil laahi musaddiqul limaa ma\'ahum nabaza fareequm minal lazeena ootul Kitaaba Kitaabal laahi waraaa\'a zuhoorihim ka annahum laa ya\'lamoon'),
  ('en.transliteration', 2, 102, 'Wattaba\'oo maa tatlush Shayaateenu \'alaa mulki Sulaimaana wa maa kafara Sulaimaanu wa laakinnash Shayattena kafaroo yu\'al limoonan naasas sihra wa maaa unzila \'alal malakaini bi Baabila Haaroota wa Maaroot; wa maa yu\'allimaani min ahadin hattaa yaqoolaaa innamaa nahnu fitnatun falaa takfur fayata\'al lamoona minhumaa maa yufarriqoona bihee bainal mar\'i wa zawjih; wa maa hum bidaaarreena bihee min ahadin illaa bi-iznillah; wa yata\'allamoona maa yadurruhum wa laa yanfa\'uhum; wa laqad \'alimoo lamanish taraahu maa lahoo fil Aakhirati min khalaaq; wa labi\'sa maa sharaw biheee anfusahum; law kaanoo ya\'lamoon'),
  ('en.transliteration', 2, 103, 'Wa law annahum aamanoo wattaqaw lamasoobatum min \'indillaahi khairun law kaanoo ya\'lamoon'),
  ('en.transliteration', 2, 104, 'Yaaa ayyuhal lazeena aamanoo laa taqooloo raa\'inaa wa qoolun zurnaa wasma\'oo; wa lilkaafireena \'azaabun aleem'),
  ('en.transliteration', 2, 105, 'Maa yawaddul lazeena kafaroo min ahlil kitaabi wa lal mushrikeena ai-yunazzala \'alaikum min khairim mir Rabbikum; wallaahu yakhtassu birahmatihee mai-yashaaa; wallaahu zul fadlil\'azeem'),
  ('en.transliteration', 2, 106, 'Maa nansakh min aayatin aw nunsihaa na-ti bikhairim minhaaa aw mislihaaa; alam ta\'lam annal laaha \'alaa kulli shai\'in qadeer'),
  ('en.transliteration', 2, 107, 'Alam ta\'lam annallaaha lahoo mulkus samaawaati wal ard; wa maa lakum min doonil laahi minw waliyyinw wa laa naseer'),
  ('en.transliteration', 2, 108, 'Am tureedoona an tas\'aloo Rasoolakum kamaa su\'ila Moosa min qabl; wa mai yatabaddalil kufra bil eemaani faqad dalla sawaaa\'as sabeel'),
  ('en.transliteration', 2, 109, 'Wadda kaseerum min ahlil kitaabi law yaruddoo nakum mim ba\'di eemaanikum kuffaaran hasadam min \'indi anfusihim mim ba\'di maa tabaiyana lahumul haqqu fa\'foo washfahoo hattaa yaa tiyallaahu bi amrih; innal laaha \'alaa kulli shai\'in qadeer'),
  ('en.transliteration', 2, 110, 'Wa aqeemus salaata wa aatuz zakaah; wa maa tuqaddimoo li anfusikum min khairin tajidoohu \'indal laah; innal laaha bimaa ta\'maloona baseer'),
  ('en.transliteration', 2, 111, 'Wa qaaloo lai yadkhulal jannata illaa man kaana Hoodan aw Nasaaraa; tilka ammniyyuhum; qul haatoo burhaa nakum in kuntum saadiqeen'),
  ('en.transliteration', 2, 112, 'Balaa man aslama wajhahoo lillaahi wa huwa muhsinun falahooo ajruhoo \'inda rabbihee wa laa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 2, 113, 'Wa qaalatil Yahoodu laisatin Nasaaraa \'alaa shai\'inw-wa qaalatin Nasaaraaa laisatil Yahoodu \'alaa shai\'inw\'wa hum yatloonal Kitaab; kazaalika qaalal lazeena la ya\'lamoona misla qawlihim Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon'),
  ('en.transliteration', 2, 114, 'Wa man azlamu mimmam-mana\'a masaajidal laahi ai-yuzkara feehas muhoo wa sa\'aa fee kharaabihaaa; ulaaa\'ika maa kaana lahum ai yadkhuloohaaa illaa khaaa\'\'feen; lahum fiddunyaa khizyunw wa lahum fil aakhirati \'azaabun \'azeem'),
  ('en.transliteration', 2, 115, 'Wa lillaahil mashriqu walmaghrib; fa aynamaa tuwalloo fasamma wajhullaah; innal laaha waasi\'un Aleem'),
  ('en.transliteration', 2, 116, 'Wa qaalut takhazal laahu waladan subhaanahoo bal lahoo maa fis samaawaati wal ardi kullul lahoo qaanitoon'),
  ('en.transliteration', 2, 117, 'Badree\'us samaawaati wal ardi wa izaa qadaaa amran fa innamaa yaqoolu lahoo kun fayakoon'),
  ('en.transliteration', 2, 118, 'Wa qaalal lazeena laa ya\'lamoona law laa yukallimunal laahu aw taateenaaa aayah; kazaalika qaalal lazeena min qablihim misla qawlihim; tashaabahat quloobuhum; qad baiyannal aayaati liqawminy yooqinoon'),
  ('en.transliteration', 2, 119, 'Innaaa arsalnaaka bilhaqqi basheeranw wa nazeeranw wa laa tus\'alu \'am Ashaabil Jaheem'),
  ('en.transliteration', 2, 120, 'Wa lan tardaa \'ankal Yahoodu wa lan Nasaaraa hattaa tattabi\'a millatahum; qul inna hudal laahi huwalhudaa; wa la\'init taba\'ta ahwaaa\'ahum ba\'dal lazee jaaa\'aka minal \'ilmimaa laka minal laahi minw waliyyinw wa laa naseer'),
  ('en.transliteration', 2, 121, 'Allazeena aatainaahumul Kitaaba yatloonahoo haqqa tilaawatiheee ulaaa\'ika yu\'minoona bi; wa mai yakfur bihee fa ulaaa\'ika humul khaasiroon'),
  ('en.transliteration', 2, 122, 'Yaa Baneee Israaa\'eelaz-kuroo ni\'matiyal lateee an\'amtu \'alaikum wa annee faddaltukum \'alal \'aalameen'),
  ('en.transliteration', 2, 123, 'Wattaqoo yawmal laa tajzee nafsun \'an nafsin shai \'anw wa laa yuqbalu minhaa \'adlunw wa laa tanfa\'uhaa shafaa \'atunw wa laa hum yunsaroon'),
  ('en.transliteration', 2, 124, 'Wa izib talaaa Ibraaheema Rabbuho bi Kalimaatin fa atammahunna qaala Innee jaa\'iluka linnaasi Imaaman qaala wa min zurriyyatee qaala laa yanaalu \'ahdiz zaalimeen'),
  ('en.transliteration', 2, 125, 'Wa iz ja\'alnal Baita masaabatal linnassi wa amnanw wattakhizoo mim Maqaami Ibraaheema musallaaa; wa \'ahidnaaa ilaaa Ibraaheema wa Ismaa\'eela an tahhiraa Baitiya littaaa\'ifeena wal\'aakifeena warrukka\'is sujood'),
  ('en.transliteration', 2, 126, 'Wa iz qaala Ibraaheemu Rabbij \'al haazaa baladan aaminanw warzuq ahlahoo minas samaraati man aamana minhum billaahi wal yawmil aakhiri qaala wa man kafara faumatti\'uhoo qaleelan summa adtarruhooo ilaa \'azaabin Naari wa bi\'salmaseer'),
  ('en.transliteration', 2, 127, 'Wa iz yarfa\'u Ibraaheemul qawaa\'ida minal Baitiwa Ismaa\'eelu Rabbanaa taqabbal minnaa innaka Antas Samee\'ul Aleem'),
  ('en.transliteration', 2, 128, 'Rabbanaa waj\'alnaa muslimaini laka wa min zurriyyatinaaa ummatam muslimatal laka wa arinaa manaasikanaa wa tub \'alainaa innaka antat Tawwaabur Raheem'),
  ('en.transliteration', 2, 129, 'Rabbanaa wab\'as feehim Rasoolam minhum yatloo \'alaihim aayaatika wa yu\'allimuhumul Kitaaba wal Hikmata wa yuzakkeehim; innaka Antal \'Azeezul Hakeem'),
  ('en.transliteration', 2, 130, 'Wa manny yarghabu \'am-Millarti Ibraaheema illaa man safiha nafsah; wa laqadis tafainaahu fid-dunyaa wa innaho fil aakhirati laminas saaliheen'),
  ('en.transliteration', 2, 131, 'Iz qaala lahoo Rabbuhooo aslim qaala aslamtu li Rabbil \'aalameen'),
  ('en.transliteration', 2, 132, 'Wa wassaa bihaaa Ibraaheemu baneehi wa Ya\'qoob, yaa baniyya innal laahas tafaa lakumud deena falaa tamootunna illaa wa antum muslimoon'),
  ('en.transliteration', 2, 133, 'Am kuntum shuhadaaa\'a iz hadara Ya\'qoobal mawtu iz qaala libaneehi maa ta\'budoona mim ba\'dee qaaloo na\'budu ilaahaka wa ilaaha aabaaa\'ika Ibraaheema wa Ismaa\'eela wa Ishaaqa Ilaahanw waahidanw wa nahnu lahoo muslimoon'),
  ('en.transliteration', 2, 134, 'Tilka ummatun qad khalat lahaa maa kasabat wa lakum maa kasabtum wa laa tus\'aloona \'ammaa kaano ya\'maloon'),
  ('en.transliteration', 2, 135, 'Wa qaaloo koonoo Hoodan aw Nasaaraa tahtadoo; qul bal Millata Ibraaheema Haneefanw wa maa kaana minal mushrikeen'),
  ('en.transliteration', 2, 136, 'Qoolooo aamannaa billaahi wa maaa unzila ilainaa wa maaa unzila ilaaa Ibraaheema wa Ismaa\'eela wa Ishaaqa wa Ya\'qooba wal Asbaati wa maaootiya Moosa wa \'Eesaa wa maaa ootiyan Nabiyyoona mir Rabbihim laa nufaariq baina ahadim minhum wa nahnu lahoo muslimoon'),
  ('en.transliteration', 2, 137, 'Fa in aamanoo bimisli maaa aamantum bihee faqadih tadaw wa in tawallaw fa innamaa hum fee shiqaaq; fasayakfeekahumul laah; wa Huwas Samee\'ul Aleem'),
  ('en.transliteration', 2, 138, 'Sibghatal laahi wa man ahsanu minal laahi sibghatanw wa nahnu lahoo \'aabidoon'),
  ('en.transliteration', 2, 139, 'Qul atuhaaajjoonanaa fil laahi wa Huwa Rabbunaa wa Rabbukum wa lanaa a\'maalunaa wa lakum a\'maalukum wa nahnu lahoo mukhlisson'),
  ('en.transliteration', 2, 140, 'Am taqooloona inna Ibraaheema wa Ismaa\'eela wa Ishaaq wa Ya\'qooba wal asbaata kaanoo Hoodan aw Nasaaraa; qul \'a-antum a\'lamu amil laah; wa man azlamu mimman katama shahaadatan \'indahoo minallaah; wa mallaahu bighaafilin \'ammaa ta\'maloon'),
  ('en.transliteration', 2, 141, 'Tilka ummatun qad khalat lahaa maa kasabat wa lakum maa kasabtum wa laa tus\'aloona \'ammaa kaano ya\'maloo'),
  ('en.transliteration', 2, 142, 'Sayaqoolus sufahaaa\'u minan naasi maa wallaahum \'an Qiblatihimul latee kaanoo \'alaihaa; qulo lillaahil mashriqu walmaghrib; yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 2, 143, 'Wa kazaalika ja\'alnaakum ummatanw wasatal litakoonoo shuhadaaa\'a \'alan naasi wa yakoonar Rasoolu \'alaikum shaheedaa; wa maa ja\'alnal qiblatal latee kunta \'alaihaaa illaa lina\'lama mai yattabi\'ur Rasoola mimmai yanqalibu \'alaa \'aqibayh; wa in kaanat lakabeeratan illaa \'alal lazeena hadal laah; wa maa kaanal laahu liyudee\'a eemaanakum; innal laaha binnaasi la Ra\'oofur Raheem'),
  ('en.transliteration', 2, 144, 'Qad naraa taqalluba wajhika fis samaaa\'i fala nuwalliyannaka qiblatan tardaahaa; fawalli wajhaka shatral Masjidil haaraam; wa haisu maa kuntum fawalloo wujoohakum shatrah; wa innal lazeena ootul Kitaaba laya\'lamoona annahul haqqu mir Rabbihim; wa mal laahu bighaafilin \'ammaa ya\'maloon'),
  ('en.transliteration', 2, 145, 'Wa la\'in ataital lazeena ootul kitaaba bikulli aayatim maa tabi\'oo Qiblatak; wa maaa anta bitaabi\'in Qiblatahum; wa maa ba\'duhum bitaabi\'\'in Qiblata ba\'d; wa la\'init taba\'ta ahwaaa;ahum mim ba\'di maa jaaa\'aka minal \'ilmi innaka izal laminaz zaalimeen'),
  ('en.transliteration', 2, 146, 'Allazeena aatainaahumul kitaaba ya\'rifoonahoo kamaa ya\'rifoona abnaaa\'ahum wa inna fareeqam minhum layaktumoonal haqqa wa hum ya\'lamoon'),
  ('en.transliteration', 2, 147, 'Alhaqqu mir Rabbika falaa takoonana minal mumtareen'),
  ('en.transliteration', 2, 148, 'Wa likullinw wijhatun huwa muwalleehaa fastabiqul khairaat; ayna maa takoonoo yaati bikumullaahu jamee\'aa; innal laaha \'alaa kulli shai\'in qadeer'),
  ('en.transliteration', 2, 149, 'Wa min haisu kharajta fawalli wajhaka shatral Masjidil Haraami wa innahoo lalhaqqu mir Rabbik; wa mallaahu bighaafilin \'ammaa ta\'maloon'),
  ('en.transliteration', 2, 150, 'Wa min haisu kharajta fawalli wajhaka shatral Masjidil Haraam; wa haisu maa kuntum fawalloo wujoohakum shatrahoo li\'allaa yakoona linnaasi \'alaikum hujjatun illal lazeena zalamoo minhum falaa takhshawhum wakhshawnee wa liutimma ni\'matee \'alaikum wa la\'allakum tahtadoon'),
  ('en.transliteration', 2, 151, 'kamaaa arsalnaa feekum Rasoolam minkum yatloo \'alaikum aayaatina wa yuzakkeekum wa yu\'alli mukumul kitaaba wal hikmata wa yu\'allimukum maa lam takoonoo ta\'lamoon'),
  ('en.transliteration', 2, 152, 'Fazkurooneee azkurkum washkuroo lee wa laa takfuroon'),
  ('en.transliteration', 2, 153, 'Yaaa ayyuhal laazeena aamanus ta\'eenoo bissabri was Salaah; innal laaha ma\'as-saabireen'),
  ('en.transliteration', 2, 154, 'Wa laa taqooloo limai yuqtalu fee sabeelil laahi amwaat; bal ahyaaa\'unw wa laakil laa tash\'uroon'),
  ('en.transliteration', 2, 155, 'Wa lanablu wannakum bishai\'im minal khawfi waljoo\'i wa naqsim minal amwaali wal anfusi was samaraat; wa bashshiris saabireen'),
  ('en.transliteration', 2, 156, 'Allazeena izaaa asaabathum museebatun qaalooo innaa lillaahi wa innaaa ilaihi raaji\'oon'),
  ('en.transliteration', 2, 157, 'Ulaaa\'ika \'alaihim salawaatun mir Rabbihim wa rahma; wa ulaaa\'ika humul muhtadoon'),
  ('en.transliteration', 2, 158, 'Innas Safaa wal-Marwata min sha\'aaa\'iril laahi faman hajjal Baita awi\'tamara falaa junaaha \'alaihi ai yattawwafa bihimaa; wa man tatawwa\'a khairan fa innal laaha Shaakirun\'Aleem'),
  ('en.transliteration', 2, 159, 'Innal lazeena yaktumoona maaa anzalnaa minal baiyinaati walhudaa mim ba\'di maa baiyannaahu linnaasi fil kitaabi ulaaa\'ika yal\'anuhumul laahu wa yal\'anuhumul laa \'inoon'),
  ('en.transliteration', 2, 160, 'Illal lazeena taaboo wa aslahoo wa baiyanoo fa ulaaa\'ika atoobu \'alaihim; wa Anat Tawwaabur Raheem'),
  ('en.transliteration', 2, 161, 'Innal lazeena kafaroo wamaa too wa hum kuffaarun ulaaa\'ika \'alaihim la \'natul laahi walmalaa\'ikati wannaasi ajma\'een'),
  ('en.transliteration', 2, 162, 'khaalideena feeha laa yukhaffafu \'anhumul \'azaabu wa laa hum yunzaroon'),
  ('en.transliteration', 2, 163, 'Wa ilaahukum illaahunw waahid, laaa ilaaha illaa Huwar Rahmaanur Raheem'),
  ('en.transliteration', 2, 164, 'Inna fee khalqis samaawaati wal ardi wakhtilaafil laili wannahaari walfulkil latee tajree fil hahri bimaa yanfa\'unnaasa wa maaa anzalal laahu minas samaaa\'i mim maaa\'in fa ahyaa bihil arda ba\'da mawtihaa wa bas sa feehaa min kulli daaabbatinw wa tasreefir riyaahi wassahaabil musakhkhari bainas samaaa\'i wal ardi la aayaatil liqawminy ya\'qiloon'),
  ('en.transliteration', 2, 165, 'Wa minan naasi mai yattakhizu min doonil laahi andaadai yuhibboonahum kahubbil laahi wallazeena aamanooo ashaddu hubbal lillah; wa law yaral lazeena zalamoo iz yarawnal \'azaaba annal quwwata lillaahi jamee\'anw wa annallaaha shadeedul \'azaab'),
  ('en.transliteration', 2, 166, 'Iz tabarra al lazeenat tubi\'oo minal lazeenattaba\'oo wa ra awul \'azaaba wa taqatta\'at bihimul asbaab'),
  ('en.transliteration', 2, 167, 'Wa qaalal lazeenat taba\'oo law anna lanaa karratan fanatabarra a minhum kamaa tabarra\'oo minnaa; kazaalika yureehimullaahu a\'maalahum hasaraatin \'alaihim wa maa hum bikhaarijeena minan Naar'),
  ('en.transliteration', 2, 168, 'Yaaa ayyuhan naasu kuloo mimmaa fil ardi halaalan taiyibanw wa laa tattabi\'oo khutu waatish Shaitaan; innahoo lakum \'aduwwum mubeen'),
  ('en.transliteration', 2, 169, 'Innamaa yaamurukum bissooo\'i walfahshaaa\'i wa an taqooloo alal laahi maa laa ta\'lamoon'),
  ('en.transliteration', 2, 170, 'Wa izaa qeela lahumuttabi\'oo maaa anzalal laahu qaaloo bal nattabi\'u maaa alfainaa \'alaihi aabaaa\'anaaa; awalaw kaana aabaaa\'hum laa ya\'qiloona shai\'anw wa laa yahtadoon'),
  ('en.transliteration', 2, 171, 'Wa masalul lazeena kafaroo kamasalil lazee yan\'iqu bimaa laa yasma\'u illaa du\'aaa\'anw wa nidaaa\'aa; summum bukmun \'umyun fahum laa ya\'qiloon'),
  ('en.transliteration', 2, 172, 'Yaaa ayyuhal lazeena aamanoo kuloo min taiyibaati maa razaqnaakum washkuroo lillaahi in kuntum iyyaahu ta\'budoon'),
  ('en.transliteration', 2, 173, 'Innamaa harrama \'alaikumul maitata waddama wa lahmal khinzeeri wa maaa uhilla bihee lighairil laahi famanid turra ghaira baaghinw wa laa \'aadin falaaa isma \'alaih; innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 2, 174, 'Innal lazeena yaktumoona maaa anzalal laahu minal kitaabi wa yashtaroona bihee samanan qaleelan ulaaa\'ika maa yaakuloona fee butoonihim illan Naara wa laa yukallimu humul laahu Yawmal Qiyaamati wa laa yuzakkeehim wa lahum \'azaabun aleem'),
  ('en.transliteration', 2, 175, 'Ulaaa\'ikal lazeenash tarawud dalaalata bilhudaa wal\'azaaba bilmaghfirah; famaaa asbarahum \'alan Naar'),
  ('en.transliteration', 2, 176, 'Zaalika bi annal laaha nazzalal kitaaba bilhaqq; wa innal lazeenakh talafoo fil kitaabi lafee shiqaaqim ba\'eed'),
  ('en.transliteration', 2, 177, 'Laisal birra an tuwalloo wujoohakum qibalal mashriqi walmaghribi wa laakinnal birra man aamana billaahi wal yawmil aakhiri wal malaaa \'ikati wal kitaabi wan nabiyyeena wa aatalmaala \'alaa hubbihee zawilqurbaa walyataa maa walmasaakeena wabnas sabeeli wassaaa\'ileena wa firriqaabi wa aqaamas salaata wa aataz zakaata walmoofoona bi ahdihim izaa \'aahadoo wasaabireena fil baasaaa\'i waddarraaa\'i wa heenal baas; ulaaa\'ikal lazeena sadaqoo wa ulaaa \'ika humul muttaqoon'),
  ('en.transliteration', 2, 178, 'Yaaa ayyuhal lazeena aamanoo kutiba alaikumul qisaasu fil qatlaa alhurru bilhurri wal\'abdu bil\'abdi wal unsaa bil unsaa; faman \'ufiya lahoo min akheehi shai\'un fattibaa\'um bilma\'roofi wa adaaa\'un ilaihi bi ihsaan; zaalika takhfeefum mir rahbikum wa rahmah; famani\' tadaa ba\'da zaalika falahoo \'azaabun aleem'),
  ('en.transliteration', 2, 179, 'Wa lakum fil qisaasi hayaatuny yaaa ulil albaabi la \'allakum tattaqoon'),
  ('en.transliteration', 2, 180, 'Kutiba \'alaikum izaa hadara ahadakumul mawtu in taraka khairanil wasiyyatu lilwaalidaini wal aqrabeena bilma\'roofi haqqan \'alalmut taqeen'),
  ('en.transliteration', 2, 181, 'Famam baddalahoo ba\'da maa sami\'ahoo fa innamaaa ismuhoo \'alallazeena yubaddi loonah; innallaha Samee\'un \'Aleem'),
  ('en.transliteration', 2, 182, 'Faman khaafa mim moosin janafan aw isman fa aslaha bainahum falaaa ismaa \'alayh; innal laaha Ghafooru Raheem'),
  ('en.transliteration', 2, 183, 'Yaa ayyuhal lazeena aamanoo kutiba \'alaikumus Siyaamu kamaa kutiba \'alal lazeena min qablikum la\'allakum tattaqoon'),
  ('en.transliteration', 2, 184, 'Ayyaamam ma\'doodaat; faman kaana minkum mareedan aw\'alaa safarin fa\'iddatum min ayyaamin ukhar; wa \'alal lazeena yuteeqoonahoo fidyatun ta\'aamu miskeenin faman tatawwa\'a khairan fahuwa khairulo lahoo wa an tasoomoo khairul lakum in kuntum ta\'lamoon'),
  ('en.transliteration', 2, 185, 'Shahru Ramadaanallazeee unzila feehil Qur\'aanu hudal linnaasi wa baiyinaatim minal hudaa wal furqaan; faman shahida minkumush shahra falyasumhu wa man kaana mareedan aw \'alaa safarin fa\'iddatum min ayyaamin ukhar; yureedul laahu bikumul yusra wa laa yureedu bikumul \'usra wa litukmilul \'iddata wa litukabbirul laaha \'alaa maa hadaakum wa la\'allakum tashkuroon'),
  ('en.transliteration', 2, 186, 'Wa izaa sa alaka \'ibaadee \'annnee fa innee qareebun ujeebu da\'wataddaa\'i izaa da\'aani falyastajeeboo lee walyu minoo beela \'allahum yarshudoon'),
  ('en.transliteration', 2, 187, 'Uhilla lakum laylatas Siyaamir rafasu ilaa nisaaa\'ikum; hunna libaasullakum wa antum libaasullahunn; \'alimal laahu annakum kuntum takhtaanoona anfusakum fataaba \'alaikum wa \'afaa \'ankum fal\'aana baashiroo hunna wabtaghoo maa katabal laahoo lakum; wa kuloo washraboo hattaa yatabaiyana lakumul khaitul abyadu minal khaitil aswadi minal fajri summa atimmus Siyaama ilal layl; wa laa tubaashiroo hunna wa antum \'aakifoona fil masaajid; tilka hudoodul laahi falaa taqraboohaa; kazaalika yubaiyinul laahu aayaatihee linnaasi la\'allahum yattaqoon'),
  ('en.transliteration', 2, 188, 'Wa laa taakuloo amwaalakum bainakum bilbaatili wa tudloo bihaaa ilal hukkaami litaakuloo fareeqam min amwaalin naasi bil ismi wa antum ta\'lamoon'),
  ('en.transliteration', 2, 189, 'Yas\'aloonaka \'anil ahillati qul hiya mawaaqeetu linnaasi wal Hajj; wa laisal birru bi an taatul buyoota min zuhoorihaa wa laakinnal birra manit taqaa; waatul buyoota min abwaa bihaa; wattaqullaaha la\'allakum tuflihoon'),
  ('en.transliteration', 2, 190, 'Wa qaatiloo fee sabeelillaahil lazeena yuqaatiloonakum wa laa ta\'tadooo; innal laaha laa yuhibbul mu\'tadeen'),
  ('en.transliteration', 2, 191, 'Waqtuloohum haisu saqif tumoohum wa akhrijoohum min haisu akhrajookum; walfitnatu ashaddu minal qatl; wa laa tuqaatiloohum \'indal Majidil Haraami hattaa yaqaatilookum feehi fa in qaatalookum faqtuloohum; kazaalika jazaaa\'ul kaafireen'),
  ('en.transliteration', 2, 192, 'Fa ini-ntahaw fa innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 2, 193, 'Wa qaatiloohum hatta laa takoona fitnatunw wa yakoonad deenu lillaahi fa-inin tahaw falaa \'udwaana illaa \'alaz zaalimeen'),
  ('en.transliteration', 2, 194, 'Ash Shahrul Haraamu bish Shahril Haraami wal hurumaatu qisaas; famani\'tadaa \'alaikum fa\'tadoo \'alaihi bimsisli ma\'tadaa \'alaikum; wattaqul laaha wa\'lamooo annal laaha ma\'al muttaqeen'),
  ('en.transliteration', 2, 195, 'Wa anfiqoo fee sabeelil laahi wa laa tulqoo bi aydeekum ilat tahlukati wa ahsinoo; innal laaha yuhibbul muhsineen'),
  ('en.transliteration', 2, 196, 'Wa atimmul Hajja wal Umarata lillaah; fain uhsirtum famas taisara minal hadyi walaa tahliqoo ru\'oosakum hatta yablughal hadyu mahillah; faman kaana minkum mareedan aw biheee azam mir raasihee fafidyatum min Siyaamin aw sadaqatin aw nusuk; fa izaaa amintum faman tamatta\'a bil \'Umrati ilal Hajji famastaisara minal hady; famal lam yajid fa Siyaamu salaasti ayyaamin fil Hajji wa sab\'atin izaa raja\'tum; tilka \'asharatun kaamilah; zaalika limal lam yakun ahluhoo haadiril Masjidil Haraam; wattaqul laaha wa\'lamoo annal laaha shadeedul\'iqaab'),
  ('en.transliteration', 2, 197, 'Al-Hajju ashhurum ma\'-loomaat; faman farada feeinnal hajja falaa rafasa wa laa fusooqa wa laa jidaala fil Hajj; wa maa taf\'aloo min khairiny ya\'lamhul laah; wa tazawwadoo fa inna khairaz zaadit taqwaa; wattaqooni yaaa ulil albaab'),
  ('en.transliteration', 2, 198, 'Laisa \'alaikum junaahun an tabtaghoo fad lam mir rabbikum; fa izaaa afadtum min \'Arafaatin fazkurul laaha \'indal-Mash\'aril Haraami waz kuroohu kamaa hadaakum wa in kuntum min qablihee laminad daaaleen'),
  ('en.transliteration', 2, 199, 'Summa afeedoo min haisu afaadan naasu wastagh firullaah; innnal laaha Ghafoo rur-Raheem'),
  ('en.transliteration', 2, 200, 'Fa-izan qadaitum manaa sikakum fazkurul laaha kazikrikum aabaaa\'akum aw ashadda zikraa; faminannaasi mai yaqoolu Rabbanaaa aatinaa fiddunyaa wa maa lahoo fil Aakhirati min khalaaq')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 2, 201, 'Wa minhum mai yaqoolu rabbanaaa aatina fid dunyaa hasanatawn wa fil aakhirati hasanatanw wa qinaa azaaban Naar'),
  ('en.transliteration', 2, 202, 'Ulaaa\'ika lahum naseebum mimmaa kasaboo; wal laahu saree\'ul hisaab'),
  ('en.transliteration', 2, 203, 'Wazkurul laaha feee ayyaamim ma\'doodaat; faman ta\'ajjala fee yawmaini falaaa ismaa \'alaihi wa man taakhkhara falaaa isma \'alayh; limanit-taqaa; wattaqul laaha wa\'lamooo annakum ilaihi tuhsharoon'),
  ('en.transliteration', 2, 204, 'Wa minan naasi mai yu\'jibuka qawluhoo fil hayaatid dunyaa wa yushhidul laaha \'alaa maa fee qalbihee wa huwa aladdulkhisaam'),
  ('en.transliteration', 2, 205, 'Wa izaa tawallaa sa\'aa fil ardi liyufsida feeha wa yuhlikal harsa wannasl; wallaahu laa yuhibbul fasaad'),
  ('en.transliteration', 2, 206, 'Wa izaa qeela lahuttaqil laaha akhazathul izzatu bil-ism; fahasbuhoo jahannam; wa labi\'sal mihaad'),
  ('en.transliteration', 2, 207, 'Wa minan naasi mai yashree nafsahub tighaaa\'a mardaatil laah; wallaahu ra\'oofum bil\'ibaad'),
  ('en.transliteration', 2, 208, 'Yaaa ayyuhal lazeena aamanud khuloo fis silmi kaaaffatanw wa laa tattabi\'oo khutuwaatish Shaitaan; innahoo lakum \'aduwwum mubeen'),
  ('en.transliteration', 2, 209, 'Fa in zalaltum mimba\'di maa jaaa\'atkumul baiyinaatu fa\'lamoo annallaaha \'Azeezun hakeem'),
  ('en.transliteration', 2, 210, 'Hal yanzuroona illaaa ai yaatiyahumul laahu fee zulalim minal ghamaami walmalaaa\'ikatu wa qudiyal amr; wa ilal laahi turja\'ulumoor'),
  ('en.transliteration', 2, 211, 'Sal Banee Israaa\'eela kam aatainaahum min aayatim baiyinah; wa mai yubaddil ni\'matal laahi mim ba\'di maa jaaa\'athu fa innallaaha shadeedul\'iqaab'),
  ('en.transliteration', 2, 212, 'Zuyyina lillazeena kafarul hayaatud dunyaa wa yaskharoona minal lazeena aamanoo; wallazeenat taqaw fawqahum yawmal Qiyaamah; wallaahu yarzuqu mai yashaaa\'u bighairi hisaab;'),
  ('en.transliteration', 2, 213, 'Kaanan naasu ummatanw waahidatan fab\'asal laahun Nabiyyeena mubashshireena wa munzireena wa anzala ma\'ahumul kitaaba bilhaqqi liyahkuma bainan naasi feemakh talafoo feeh; wa makh talafa feehi \'illallazeena ootoohu mim ba\'di maa jaaa\'athumul baiyinaatu baghyam bainahm fahadal laahul lazeena aamanoo limakh talafoo feehi minal haqqi bi iznih; wallaahu yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 2, 214, 'Am hasibtum an tadkhulul jannata wa lammaa yaa-tikum masalul lazeena khalaw min qablikum massathumul baasaaa\'u waddarraaaa\'u wa zulziloo hattaa yaqoolar Rasoolu wallazeena aamanoo ma\'ahoo mataa nasrul laah; alaaa inna nasral laahiqareeb'),
  ('en.transliteration', 2, 215, 'Yas\'aloonaka maazaa yunfiqoona qul maaa anfaqtum min khairin falil waalidaini wal aqrabeena walyataamaa wal masaakeeni wabnis sabeel; wa maa taf\'aloo min khairin fa innal laaha bihee \'Aleem'),
  ('en.transliteration', 2, 216, 'Kutiba alaikumulqitaalu wa huwa kurhullakum wa \'asaaa an takrahoo shai\'anw wa huwa khairullakum wa \'asaaa an tuhibbo shai\'anw wa huwa sharrullakum; wallaahu ya\'lamu wa antum laa ta\'lamoon'),
  ('en.transliteration', 2, 217, 'Yas\'aloonaka \'anish Shahril Haraami qitaalin feehi qul qitaahun feehi kabeerunw wa saddun \'an sabeelil laahi wa kufrum bihee wal Masjidil Haraami wa ikhraaju ahlihee minhu akbaru \'indal laah; walfitnatu akbaru minal qatl; wa laa yazaaloona yuqaatiloonakum hatta yaruddookum \'an deenikum inis tataa\'oo; wa mai yartadid minkum \'an deenihee fayamut wahuwa kaafirun fa ulaaa\'ika habitat a\'maaluhum fid dunyaa wal aakhirati wa ulaaa\'ika ashaabun Naari hum feehaa khaalidoon'),
  ('en.transliteration', 2, 218, 'Innal lazeena aamanoo wallazeena haajaroo wa jaahadoo fee sabeelil laahi ulaaaika yarjoona rahmatal laah; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 2, 219, 'Yas\'aloonaka \'anilkhamri walmaisiri qul feehimaaa ismun kabeerunw wa manaafi\'u linnaasi wa ismuhumaa akbaru min naf\'ihimaa; wa yas\'aloonaka maaza yunfiqoona qulil-\'afw; kazaalika yubaiyinul laahu lakumul-aayaati la\'allakum tatafakkaroon'),
  ('en.transliteration', 2, 220, 'Fid dunyaa wal aakhirah; wa yas\'aloonaka \'anil yataamaa qul islaahullahum khayr, wa in tukhaalitoohum fa ikhwaanukum; wallaahu ya\'lamul mufsida minalmuslih; wa law shaaa\'al laahu la-a\'natakum; innal laaha \'Azeezun Hakeem'),
  ('en.transliteration', 2, 221, 'Wa laatankihul mushrikaati hattaa yu\'minn; wa la amatum mu\'minatun khairum mim mushrikatinw wa law a\'jabatkum; wa laa tunkihul mushrikeena hattaa yu\'minoo; wa la\'abdummu\'minun khairum mimmushrikinw wa law \'ajabakum; ulaaa\'ika yad\'oona ilan Naari wallaahu yad\'ooo ilal Jannati walmaghfirati biiznihee wa yubaiyinu Aayaatihee linnaasi la\'allahum yatazakkaroon'),
  ('en.transliteration', 2, 222, 'Wa yas\'aloonaka \'anil maheedi qul huwa azan fa\'tazilun nisaaa\'a fil maheedi wa laa taqraboo hunna hattaa yathurna fa-izaa tathharna faatoohunna min haisu amarakumul laah; innallaaha yuhibbut Tawwaabeena wa yuhibbul mutatahhireen'),
  ('en.transliteration', 2, 223, 'Nisaaa\'ukum harsullakum faatoo harsakum annaa shi\'tum wa qaddimoo li anfusikum; wattaqul laaha wa\'lamooo annakum mulaaqooh; wa bash shirilmu \'mineen'),
  ('en.transliteration', 2, 224, 'Wa laa taj\'alul laaha \'urdatal li aymaanikum an tabarroo wa tattaqoo wa tuslihoo bainan naas; wallaahu Samee\'un \'Aleem'),
  ('en.transliteration', 2, 225, 'Laa yu\'aakhi zukumul laahu billaghwi feee aymaa nikum wa laakiny yu\'aakhi zukum bimaa kasabat quloo bukum; wallaahu Ghafoorun Haleem'),
  ('en.transliteration', 2, 226, 'Lillazeena yu\'loona min nisaaa\'ihim tarabbusu arba\'ati ashhurin fain faaa\'oo fa innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 2, 227, 'Wa in \'azamut talaaqa fa innal laaha Samee\'un \'Aleem'),
  ('en.transliteration', 2, 228, 'Walmutallaqaatu yatarab basna bi anfusihinna salaasata qurooo\'; wa laa yahillu lahunna ai yaktumna maa khalaqal laahu feee arhaaminhinna in kunna yu\'minna billaahi wal yawmil aakhir; wa bu\'oola tuhunna ahaqqu biraddihinna fee zaalika in araadooo islaahaa; wa lahunna mislul lazee \'araihinna bilma\'roof; wa lirrijjaali \'alaihinna daraja; wallaahu \'Azeezun Hakeem'),
  ('en.transliteration', 2, 229, 'Attalaaqu marrataani fa imsaakum bima\'roofin aw tasreehum bi ihsaan; wa laa yahillu lakum an taakhuzoo mimmaaa aataitumoohunna shai\'an illaaa ai yakhaafaaa alla yuqeemaa hudoodallahi fa in khiftum allaa yuqeemaa budoodal laahi falaa junaaha \'Alaihimaa feemaf tadat bihee tilka hudoodul laahi falaa ta\'tadoohaa; wa mai yata\'adda hudoodal laahi fa ulaaa\'ika humuzzaa limoon'),
  ('en.transliteration', 2, 230, 'Fa in tallaqahaa falaa tahillu lahoo mim ba\'du hattaa tankiha zawjan ghairah; fa in tallaqahaa falaa junaaha \'alaihimaaa ai yataraaja\'aaa in zannaaa ai yuqeemaa hudoodal laa; wa tilka hudoodul laahi yubaiyinuhaa liqawminy ya\'lamoon'),
  ('en.transliteration', 2, 231, 'Wa izaa tallaqtumun nisaaa\'a fabalaghna ajala hunna fa amsikoohunna bima\'roofin law sarrihoo hunna bima\'roof; wa laa tumsikoo hunna diraa rallita\'tadoo; wa mai yaf\'al zaalika faqad zalama nafsah; wa laa tattakhizooo aayaatillaahi huzuwaa; wazkuroo ni\'matal laahi \'alaikum wa maaa anzala \'alaikum minal kitaabi wal ikmati ya\'izukum bih; wattaqul laaha wa\'lamooo annal laaha bikulli shai\'i \'Aleem'),
  ('en.transliteration', 2, 232, 'Wa izaa tallaqtumun nisaaa\'a fabalaghna ajalahunna falaa ta\'duloo hunna ai yankihna azwaaja humna izaa taraadaw bainahum bilma\' roof; zaalika yoo\'azu bihee man kaana minkum yu\'minu billaahi wal yawmil aakhir; zaalikum azkaa lakum wa athar; wallaahu ya\'lamu wa antum laa ta\'lamu wa antum laa ta\'lamoon'),
  ('en.transliteration', 2, 233, 'Walwaa lidaatu yurdi\'na awlaada hunna hawlaini kaamilaini liman araada ai yutimmar radaa\'ah; wa \'alalmawloodi lahoo rizuhunna wa kiswatuhunna bilma\'roof; laatukallafu nafsun illaa wus\'ahaa; laa tudaaarra waalidatum biwaladihaa wa laa mawloodul lahoo biwaladih; wa \'alal waarisi mislu zaalik; fa in araadaa Fisaalan \'an taraadim minhumaa wa tashaawurin falaa junaaha \'alaimaa; wa in arattum an tastardi\'ooo awlaadakum falaa junaaha \'alaikum izaa sallamtum maaa aataitum bilma\'roof; wattaqul laaha wa\'lamooo annal laaha bimaa ta\'maloona baseer'),
  ('en.transliteration', 2, 234, 'Wallazeena yutawaffawna minkum wa yazaroona azwaajai yatarabbasna bi anfusihinna arba\'ata ashhurinw wa \'ashran fa izaa balaghna ajalahunna falaa junaaha \'alaikum feemaa fa\'alna feee anfusihinna bilma\'roof; wallaahu bimaa ta\'maloona Khabeer'),
  ('en.transliteration', 2, 235, 'Wa laa junaaha \'alaikum feema \'arradtum bihee min khitbatin nisaaa\'i aw aknantum feee anfusikum; \'alimal laahu annakum satazkuroonahunna wa laakil laa tuwaa\'idoohunna sirran illaaa an taqooloo qawlamma\'roofaa; wa laa ta\'zimoo \'uqdatan nikaahi hattaa yablughal kitaabu ajalah; wa\'lamooo annal laaha ya\'lamumaa feee anfusikum fahzarooh; wa\'lamooo annallaaha Ghafoorun Haleem'),
  ('en.transliteration', 2, 236, 'Laa junaaha \'alaikum in tallaqtumun nisaaa\'a maa lam tamassoohunna aw tafridoo lahunna fareedah; wa matti\'oona \'alal moosi\'i qadaruhoo wa \'alal muqtiri qadaruhoo matta\'am bilma\'roofi haqqan \'alalmuhsineen'),
  ('en.transliteration', 2, 237, 'Wa in tallaqtumoohunna min qabli an tamassoohunna wa qad farad tum lahunna fareedatan fanisfu maa faradtum illaaa ai ya\'foona aw ya\'fuwallazee biyadihee \'uqdatunnikaah; wa an ta\'foona aw ya\'fuwallazee biyadihee \'uqdatunnikaah; wa an ta\'fooo aqrabu littaqwaa; wa laa tansawulfadla bainakum; innal laaha bimaa ta\'maloona Baseer'),
  ('en.transliteration', 2, 238, 'Haafizoo \'alas salawaati was Salaatil Wustaa wa qoomoo lillaahi qaaniteen'),
  ('en.transliteration', 2, 239, 'Fa in khiftum farijaalan aw rukbaanan fa izaaa amintum fazkurul laaha kamaa \'allamakum maa lam takoonoo ta\'lamoon'),
  ('en.transliteration', 2, 240, 'Wallazeena yutawaf fawna minkum wa yazaroona azwaajanw wasiyyatal li azwaajihim mataa\'an ilal hawlighaira ikhraaj; fa in kharajna falaa junaaha \'alaikum fee maa fa\'alna junaaha \'alaikum fee maa fa\'alna feee anfusihinna mim ma\'roof; wallaahu Azeezun Hakeem'),
  ('en.transliteration', 2, 241, 'Wa lilmutallaqaati mataa\'um bilma\'roofi haqqan \'alal muttaqeen'),
  ('en.transliteration', 2, 242, 'Kazaalika yubaiyinul laahu lakum aayaatihee la\'allakum ta\'qiloon'),
  ('en.transliteration', 2, 243, 'Alam tara ilal lazeena kharajoo min diyaarihim wa hum uloofun hazaral mawti faqaaala lahumul laahu mootoo summa ahyaahum; innal laaha lazoo fadlin \'alannaasi wa laakinna aksarannaasi laa yashkuroon'),
  ('en.transliteration', 2, 244, 'Wa qaatiloo fee sabeelil laahi wa\'lamooo annal laaha Samee\'un \'Aleem'),
  ('en.transliteration', 2, 245, 'Man zal lazee yuqridul laaha qardan hasanan fayudaa \'ifahoo lahoo ad\'aafan kaseerah; wallaahu yaqbidu wa yabsut-u wa ilaihi turja\'oon'),
  ('en.transliteration', 2, 246, 'Alam tara ilal malai mim Baneee Israaa\'eela mim ba\'di Moosaaa iz qaaloo li Nabiyyil lahumub \'as lanaa malikan nuqaatil fee sabeelillaahi qaala hal \'asaitum in kutiba \'alaikumul qitaalu allaa tuqaatiloo qaaloo wa maa lanaaa allaa nuqaatila fee sabeelil laahi wa qad ukhrijnaa min diyaarinaa wa abnaaa\'inaa falammaa kutiba \'alaihimul qitaalu tawallaw illaa qaleelam minhum; wallaahu \'aleemum bizzaalimeen'),
  ('en.transliteration', 2, 247, 'Wa qaala lahum Nabiy yuhum innal laaha qad ba\'asa lakum Taaloota malikaa; qaalooo annaa yakoonu lahul mulku \'alainaa wa nahnu ahaqqu bilmulki minhu wa lam yu\'ta sa\'atamminal maal; qaala innallaahas tafaahu \'alaikum wa zaadahoo bastatan fil\'ilmi waljismi wallaahu yu\'tee mulkahoo mai yashaaa\'; wallaahu Waasi\'un \'Aleem'),
  ('en.transliteration', 2, 248, 'Wa qaala lahum Nabiyyuhum inna Aayata mulkiheee ai yaatiyakumut Taabootu feei sakeenatummir Rabbikum wa baqiyyatummimmaa taraka Aalu Moosa wa Aalu Haaroona tahmiluhul malaaa\'ikah; inna fee zaalika la Aayatal lakum in kuntum mu\'mineen'),
  ('en.transliteration', 2, 249, 'Falammaa fasala Taalootu biljunoodi qaala innal laaha mubtaleekum binaharin faman shariba minhu falaisa minnee wa mallam yat\'amhu fa innahoo minneee illaa manigh tarafa ghurfatam biyadih; fashariboo minhu illaa qaleelamminhum; falammaa jaawazahoo huwa wallazeena aamanoo ma\'ahoo qaaloo laa taaqata lanal yawma bi Jaaloota wa junoodih; qaalallazeena yazunnoona annahum mulaaqul laahi kam min fi\'atin qaleelatin ghalabat fi\'atan kaseeratam bi iznil laah; wallaahuma\'as saabireen'),
  ('en.transliteration', 2, 250, 'Wa lammaa barazoo liJaaloota wa junoodihee qaaloo Rabbanaaa afrigh \'alainaa sabranw wa sabbit aqdaamanaa wansurnaa \'alal qawmil kaafireen'),
  ('en.transliteration', 2, 251, 'Fahazamoohum bi iznillaahi wa qatala Daawoodu jaaloota wa aataahul laahulmulka Wal Hikmata wa \'allamahoo mimmaa yashaaa\'; wa law laa daf\'ullaahin naasa ba\'dahum biba\'dil lafasadatil ardu wa laakinnal laaha zoo fadlin \'alal\'aalameen'),
  ('en.transliteration', 2, 252, 'Tilka Aayaatul laahi natloohaa \'alaika bilhaqq; wa innaka laminal mursaleen'),
  ('en.transliteration', 2, 253, 'Tilkar Rusulu faddalnaa ba\'dahum \'alaa ba\'d; minhum man kallamal laahu wa rafa\'a ba\'dahum darajaat; wa aatainaa \'Eesab na Maryamal baiyinaati wa ayyadnaahu bi Roohil Qudus; wa law shaaa\'al laahu maqtatalal lazeena mimba\'dihim mim ba\'di maa jaaa\'athumul baiyinaatu wa laakinikh talafoo faminhum man aamana wa minhum man kafar; wa law shaaa\'al laahu maq tataloo wa laakinnallaaha yaf\'alu maa yureed ('),
  ('en.transliteration', 2, 254, 'Yaa ayyuhal lazeena aamanoo anfiqoo mimmaa razaqnaakum min qabli ai yaatiya yawmul laa bai\'un fee wa la khullatunw wa laa shafaa\'ah; walkaa firoona humuz zaalimoon'),
  ('en.transliteration', 2, 255, 'Allahu laaa ilaaha illaa Huwal Haiyul Qaiyoom; laa taakhuzuhoo sinatunw wa laa nawm; lahoo maa fissamaawaati wa maa fil ard; man zal lazee yashfa\'u indahooo illaa bi-iznih; ya\'lamu maa baina aydeehim wa mww khalfahum wa laa yuheetoona bishai\'im min \'ilmihee illaa bimaa shaaa\'; wasi\'a Kursiyyuhus samaawaati wal arda wa laa ya\'ooduho hifzuhumaa; wa Huwal Aliyyul \'Azeem'),
  ('en.transliteration', 2, 256, 'Laaa ikraaha fid deeni qat tabiyanar rushdu minal ghayy; famai yakfur bit Taaghooti wa yu\'mim billaahi faqadis tamsaka bil\'urwatil wusqaa lan fisaama lahaa; wallaahu Samee\'un \'Aleem'),
  ('en.transliteration', 2, 257, 'Allaahu waliyyul lazeena aamanoo yukhrijuhum minaz zulumaati ilan noori wallazeena kafarooo awliyaaa\'uhumut Taaghootu yukhrijoonahum minan noori ilaz zulumaat; ulaaa\'ika Ashaabun Naari hum feehaa khaalidoon'),
  ('en.transliteration', 2, 258, 'Alam tara ilal lazee Haaajja Ibraaheema fee Rabbiheee an aataahullaahul mulka iz qaala Ibraaheemu Rabbiyal lazee yuhyee wa yumeetu qaala ana uhyee wa yumeetu qaala ana uhyee wa umeetu qaala Ibraaheemu fa innal laaha yaatee bishshamsi minal mashriqi faati bihaa minal maghribi fabuhital lazee kafar; wallaahu laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 2, 259, 'Aw kallazee marra \'alaa qaryatinw wa hiya khaawiyatun \'alaa \'urooshihaa qaala annaa yuhyee haazihil laahu ba\'da mawtihaa fa amaatahul laahu mi\'ata \'aamin suumma ba\'asahoo qaala kam labista qaala labistu yawman aw ba\'da yawmin qaala bal labista mi\'ata \'aamin fanzur ilaa ta\'aamika wa sharaabika lam yatasannah wanzur ilaa himaarika wa linaj\'alaka Aayatal linnaasi wanzur ilal\'izaami kaifa nunshizuhaa summa naksoohaa lahmaa; falammaa tabiyana lahoo qaala a\'lamu annal laaha \'alaakulli shai\'in Qadeer'),
  ('en.transliteration', 2, 260, 'Wa iz qaala Ibraaheemu Rabbi arinee kaifa tuhyil mawtaa qaala awa lam tu\'min qaala balaa wa laakil liyatma\'inna qalbee qaala fakhuz arab\'atam minal tairi fasurhunna ilaika summaj \'al a\'alaa kulli jabalim minhunna juz\'an sumaad \'uhunna yaateenaka sa\'yaa; wa\'lam annal laaha \'Azeezun Hakeem'),
  ('en.transliteration', 2, 261, 'Masalul lazeena yunfiqoona amwaalahum fee sabeelil laahi kamasali habbatin ambatat sab\'a sanaabila fee kulli sumbulatim mi\'atu habbah; wallaahu yudaa\'ifu limai yashaaa; wallaahu Waasi\'un \'Aleem'),
  ('en.transliteration', 2, 262, 'Allazeena yunfiqoona amwaalahum fee sabeelillaahi summa laa yutbi\'oona maaa anfaqoo mannanw wa laaa azal lahum ajruhum \'inda Rabbihim; wa laa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 2, 263, 'Qawlum ma\'roofunw wa maghfiratun khairum min sadaqatiny yatba\'uhaaa azaa; wallaahu Ghaniyyun Haleem'),
  ('en.transliteration', 2, 264, 'Yaaa ayyuhal lazeena aamanoo laa tubtiloo sadaqaatikum bilmanni wal azaa kallazee yunfiqu maalahoo ri\'aaa\'an naasi wa laa yu\'minu billaahi wal yawmil aakhiri famasaluhoo kamasali safwaanin \'alaihi turaabun fa asaabahoo waabilun fatara kahoo saldaa; laa yaqdiroona \'alaa shai\'im mimmaa kasaboo; wallaahu laa yahdil qawmal kaafireen'),
  ('en.transliteration', 2, 265, 'Wa masalul lazeena yunfiqoona amwaalahumub ti ghaaaa\'a mardaatil laahi wa tasbeetam min anfusihim kamasali jannatim birabwatin asaabahaa waabilun fa aatat ukulahaa di\'faini fa il lam yusibhaa waabilun fatall; wallaahu bimaa ta\'maloona Baseer'),
  ('en.transliteration', 2, 266, 'Ayawaddu ahadukum an takoona lahoo jannatum min nakheelinw wa a\'naabin tajree min tahtihal anhaaru lahoo feehaa min kullis samaraati wa asaabahul kibaru wa lahoo zurriyyatun du\'afaaa\'u fa asaabahaaa i\'saarun feehi naarun fahtaraqat; kazaalika yubaiyinul laahu lakumul aayaati la\'allakum tatafakkaroon'),
  ('en.transliteration', 2, 267, 'Yaaa \'ayyuhal lazeena aamanooo anfiqoo min taiyibaati maa kasabtum wa mimmaaa akhrajuaa lakum minal ardi wa laa tayammamul khabeesa minhu tunfiqoona wa lastum bi aakhizeehi illaaa an tughmidoo feeh; wa\'lamooo annal laaha Ghaniyyun Hameed'),
  ('en.transliteration', 2, 268, 'Ash Shaitaanu ya\'idukumul faqra wa yaamurukum bilfahshaaa\'i wallaahu ya\'idukum maghfiratam minhu wa fadlaa; wallaahu Waasi\'un \'Aleem'),
  ('en.transliteration', 2, 269, 'Yu\'til Hikmata mai yashaaa\'; wa mai yutal Hikmata faqad ootiya khairan kaseeraa; wa maa yazzakkaru illaaa ulul albaab'),
  ('en.transliteration', 2, 270, 'Wa maaa anfaqtum min nafaqatin aw nazartum min nazrin fa innal laaha ya\'lamuh; wa maa lizzaalimeena min ansaar'),
  ('en.transliteration', 2, 271, 'In tubdus sadaqaati fani\'immaa hiya wa in tukhfoohaa wa tu\'toohal fuqaraaa\'a fahuwa khayrul lakum; wa yukaffiru \'ankum min saiyi aatikum; wallaahu bimaa ta\'maloona Khabeer'),
  ('en.transliteration', 2, 272, 'Laisa \'alaika hudaahum wa laakinnal laaha yahdee mai yashaaa\'; wa maa tunfiqoo min khairin fali anfusikum; wa maa tunfiqoona illab tighaaa\'a wajhil laah; wa maa tunfiqoo min khairiny yuwaffa ilaikum wa antum laa tuzlamoon'),
  ('en.transliteration', 2, 273, 'Lilfuqaraaa\'il lazeena uhsiroo fee sabeelil laahi laa yastatee\'oona darban fil ardi yah sabuhumul jaahilu aghniyaaa\'a minat ta\'affufi ta\'rifuhum biseemaahum laa yas\'aloonan naasa ilhaafaa; wa maa tunfiqoo min khairin fa innal laaha bihee \'Aleem'),
  ('en.transliteration', 2, 274, 'Allazeena yunfiqoona amwaalahum billaili wan nahaari sirranw wa \'alaaniyatan falahum ajruhum \'inda Rabbihim wa laa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 2, 275, 'Allazeena yaakuloonar ribaa laa yaqoomoona illaa kamaa yaqoomul lazee yatakhabbatuhush shaitaanu minal mass; zaalika bi annahum qaalooo innamal bai\'u mishur ribaa; wa ahallal laahul bai\'a wa harramar ribba; faman jaaa\'ahoo maw\'izatum mir rabbihee fantahaa falahoo maa salafa wa amruhooo ilal laahi wa man \'aada fa ulaaa \'ika Ashaabun naari hum feehaa khaalidoon'),
  ('en.transliteration', 2, 276, 'Yamhaqul laahur ribaa wa yurbis sadaqaat; wallaahu laa yuhibbu kulla kaffaarin aseem'),
  ('en.transliteration', 2, 277, 'Innal lazeena aamanoo wa amilus saalihaati wa aqaamus salaata wa aatawuz zakaata lahum ajruhum \'inda rabbihim wa laa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 2, 278, 'Yaaa ayyuhal lazeena aamanut taqul laaha wa zaroo maa baqiya minar ribaaa in kuntum mu\'mineen'),
  ('en.transliteration', 2, 279, 'Fail lam taf\'aloo faazanoo biharbim minal laahi wa Rasoolihee wa in tubtum falakum ru\'oosu amwaalikum laa tazlimoona wa laa tuzlamoon'),
  ('en.transliteration', 2, 280, 'Wa in kaana zoo \'usratin fanaziratun ilaa maisarah; wa an tasaddaqoo khairul lakum in kuntum ta\'lamoon'),
  ('en.transliteration', 2, 281, 'Wattaqoo yawman turja\'oona feehi ilal laahi summa tuwaffaa kullu nafsim maa kasabat wa hum laa yuzlamoon'),
  ('en.transliteration', 2, 282, 'Yaa ayyuhal lazeena aamanoo izaa tadaayantum bidinin ilaa ajalimmusamman faktubooh; walyaktub bainakum kaatibum bil\'adl; wa laa yaaba kaatibun ai yaktuba kamaa \'allamahul laah; falyaktub walyumlilil lazee \'alaihil haqqu walyattaqil laaha rabbahoo wa laa yabkhas minhu shai\'aa; fa in kaanal lazee \'alaihil lhaqqu safeehan aw da\'eefan aw laa yastatee\'u ai yumilla huwa falyumlil waliyyuhoo bil\'adl; wastash hidoo shaheedaini mir rijaalikum fa il lam yakoonaa rajulaini farajulunw wamra ataani mimman tardawna minash shuhadaaa\'i an tadilla ihdaahumaa fatuzakkira ihdaahumal ukhraa; wa laa yaabash shuhadaaa\'u izaa maadu\'oo; wa laa tas\'amooo an taktuboohu sagheeran awkabeeran ilaaa ajalih; zaalikum aqsatu \'indal laahi wa aqwamu lishshahaadati wa adnaaa allaa tartaabooo illaaa an takoona tijaaratan haadiratan tudeeroonahaa bainakum falaisa \'alaikum junaahun allaa taktuboohan; wa ashidooo izaa tabaaya\'tum; wa laa yudaaarra kaatibunw wa laa shaheed; wa in taf\'aloo fa innahoo fusooqum bikum; wattaqul laaha wa yu\'allimu kumul laah; wallaahu bikulli shai\'in \'Aleem'),
  ('en.transliteration', 2, 283, 'Wa in kuntum \'alaa safarinw wa lam tajidoo kaatiban farihaanum maqboodatun fa in amina ba\'dukum ba\'dan falyu\'addil lazi tumina amaa natahoo walyattaqil laaha Rabbah; wa laa taktumush shahaadah; wa mai yaktumhaa fa innahooo aasimun qalbuh; wallaahu bimaa ta\'maloona \'Aleem'),
  ('en.transliteration', 2, 284, 'Lillaahi maa fissamaawaati wa maa fil ard; wa in tubdoo maa feee anfusikum aw tukhfoohu yuhaasibkum bihil laa; fayaghfiru li mai yashaaa\'u wa yu\'azzibu mai yashaaa u;wallaahu \'alaa kulli shai in qadeer'),
  ('en.transliteration', 2, 285, 'Aamanar-Rasoolu bimaaa unzila ilaihi mir-Rabbihee walmu\'minoon; kullun aamana billaahi wa Malaaa\'ikathihee wa Kutubhihee wa Rusulih laa nufarriqu baina ahadim-mir-Rusulihee wa qaaloo sami\'naa wa ata\'naa ghufraanaka Rabbanaa wa ilaikal-maseer'),
  ('en.transliteration', 2, 286, 'Laa yukalliful-laahu nafsan illaa wus\'ahaa; lahaa maa kasabat wa \'alaihaa maktasabat; Rabbanaa la tu\'aakhiznaa in naseenaaa aw akhtaanaa; Rabbanaa wa laa tahmil-\'alainaaa isran kamaa hamaltahoo \'alal-lazeena min qablinaa; Rabbanaa wa laa tuhammilnaa maa laa taaqata lanaa bih wa\'fu \'annaa waghfir lanaa warhamnaa; Anta mawlaanaa fansurnaa \'alal qawmil kaafireen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 2, 1, 'المۤ'),
  ('ur.ahmedali', 2, 2, 'یہ وہ کتاب ہے جس میں کوئی بھی شک نہیں پرہیز گارو ں کے لیے ہدایت ہے'),
  ('ur.ahmedali', 2, 3, 'جو بن دیکھے ایمان لاتے ہیں اور نماز قائم کرتے ہیں ا ور جو کچھ ہم نے انہیں دیا ہے اس میں خرچ کرتے ہیں'),
  ('ur.ahmedali', 2, 4, 'اور جو ایمان لاتے ہیں اس پر جو اتارا گیا آپ پراور جو آپ سے پہلے اتارا گیا اور آخرت پر بھی وہ یقین رکھتے ہیں'),
  ('ur.ahmedali', 2, 5, 'وہی لوگ اپنے رب کے راستہ پر ہیں اور وہی نجات پانے والے ہیں'),
  ('ur.ahmedali', 2, 6, 'بے شک جو لوگ انکار کر چکے ہیں برابر ہے انہیں تو ڈرائے یا نہ ڈرائے وہ ایمان نہیں لائیں گے'),
  ('ur.ahmedali', 2, 7, 'الله نے ان کے دلوں اورکانوں پرمہر لگا دی ہے اور ان کی آنکھوں پر پردہ ہے اوران کے لیے بڑا عذا ب ہے'),
  ('ur.ahmedali', 2, 8, 'اور کچھ ایسے بھی لوگ ہیں جو کہتے ہیں کہ ہم الله اور قیامت کے دن پر ایمان لائے حالانکہ وہ ایمان دار نہیں ہیں'),
  ('ur.ahmedali', 2, 9, 'الله اور ایمان داروں کو دھوکا دیتے ہیں حالانکہ وہ اپنے آپ ہی کو دھوکہ دے رہے ہیں اور نہیں سمجھتے'),
  ('ur.ahmedali', 2, 10, 'انکے دلوں میں بیماری ہے پھر الله نے ان کی بیماری بڑھا دی اور ان کے لیے دردناک عذاب ہے اس لیے کہ وہ جھوٹ بولتے تھے'),
  ('ur.ahmedali', 2, 11, 'اور جب انہیں کہا جاتا ہے کہ ملک میں فساد نہ ڈالو تو کہتے ہیں کہ ہم ہی تو اصلاح کرنے والے ہیں'),
  ('ur.ahmedali', 2, 12, 'خبردار بے شک وہی لوگ فسادی ہیں لیکن نہیں سمجھتے'),
  ('ur.ahmedali', 2, 13, 'اور جب انہیں کہا جاتا ہے ایمان لاؤ جس طرح اور لوگ ایمان لائے ہیں تو کہتے ہیں کیا ہم ایمان لائیں جس طرح بے وقوف ایمان لائے ہیں خبردار وہی بے وقوف ہیں لیکن نہیں جانتے'),
  ('ur.ahmedali', 2, 14, 'اور جب ایمانداروں سے ملتے ہیں تو کہتے ہیں کہ ہم ایمان لائے اور جب اپنے شیطانوں کے پاس اکیلے ہوتے ہیں تو کہتے ہیں ہم توتمہارے ساتھ ہیں ہم تو صرف ہنسی کرنے والے ہیں'),
  ('ur.ahmedali', 2, 15, 'الله ان سے ہنسی کرتا ہے اور انہیں مہلت دیتا ہے کہ وہ اپنی گمراہی میں حیران رہیں'),
  ('ur.ahmedali', 2, 16, 'یہ وہ لوگ ہیں جنہوں نے ہدایت کے بدلے گمراہی خریدی سو ان کی تجارت نے نفع نہ دیا اور ہدایت پانے والے نہ ہوئے'),
  ('ur.ahmedali', 2, 17, 'ان کی مثال اس شخص کی سی ہے جس نے آگ جلائی پھر جب آگ نے اس کے آس پاس کو روشن کر دیا تو الله نے ان کی روشنی بجھا دی اور انہیں اندھیروں میں چھوڑا کہ کچھ نہیں دیکھتے'),
  ('ur.ahmedali', 2, 18, 'بہرے گونگے اندھے ہیں سو وہ نہیں لوٹیں گے'),
  ('ur.ahmedali', 2, 19, 'یا جیسا کہ آسمان سے بارش ہو جس میں اندھیرے اور گرج اور بجلی ہو اپنی انگلیاں اپنے کانوں میں کڑک کے سبب سے موت کے ڈر سے دیتے ہوں اور الله کافروں کو گھیرے ہوئے ہے'),
  ('ur.ahmedali', 2, 20, 'قریب ہے کہ بجلی ان کے آنکھیں اچک لے جب ان پر چمکتی ہے تو اس کی روشنی میں چلتے ہیں اور جب ان پر اندھیرا ہوتا ہے تو ٹھر جاتے ہیں اور اگر الله چاہے تو ان کے کان اور آنکھیں لے جائے بے شک الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 2, 21, 'اے لوگو اپنے رب کی عبادت کرو جس نے تمہیں پیدا کیا اور انہیں جو تم سے پہلے تھے تاکہ تم پرہیزگار ہو جاؤ'),
  ('ur.ahmedali', 2, 22, 'جس نے تمہارے لیے زمین کو بچھونا اور آسمان کو چھت بنایا اور آسمان سے پانی اتارا پھر اس سے تمہارے کھانے کے لیے پھل نکالے سو کسی کو الله کا شریک نہ بناؤ حالانکہ تم جانتے بھی ہو'),
  ('ur.ahmedali', 2, 23, 'اور اگر تمہیں اس چیز میں شک ہے جو ہم نے اپنے بندے پر نازل کی ہے تو ایک سورت اس جیسی لے آؤ اور الله کے سوا جس قدر تمہارے حمایتی ہوں بلا لو اگر تم سچے ہو'),
  ('ur.ahmedali', 2, 24, 'بھلا اگر ایسا نہ کر سکو اور ہرگز نہ کر سکو گے تو اس آگ سے بچو جس کا ایندھن آدمی اور پتھر ہیں جو کافرو ں کے لیے تیار کی گئی ہے'),
  ('ur.ahmedali', 2, 25, 'اوران لوگو ں کو خوشخبری دے جو ایمان لائے اور اچھے کام کیے کہ ان کے لیے باغ ہیں ان کے نیچے نہریں بہتی ہیں جب انہیں وہاں کا کوئي پھل کھانے کو ملے گا تو کہیں گے یہ تو وہی ہے جو ہمیں اس سے پہلے ملا تھا اور انہیں ہم شکل پھل دیئے جائیں گے اور ان کے لیے وہاں پاکیزہ عورتیں ہوں گی اوروہ وہیں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 2, 26, 'بے شک الله نہیں شرماتا اس بات سے کہ کوئی مثال بیان کرے مچھر کی یا اس چیز کی جو اس سے بڑھ کر ہے سو جو لوگ مومن ہیں وہ اسے اپنے رب کی طرف سے صحیح جانتے ہیں اور جو کافر ہیں سو کہتے ہیں الله کا اس مثال سے کیا مطلب ہے الله اس مثال سے بہتوں کو گمراہ کرتا ہے اور بہتوں کو اس سے ہدایت کرتا ہے اوراس سے گمراہ تو بدکاروں ہی کو کیا کرتا ہے'),
  ('ur.ahmedali', 2, 27, 'جو الله کے عہد کو پختہ کرنے کے بعد توڑتے ہیں اور جس کے جوڑنے کا الله نے حکم دیا ہے اسے توڑتے ہیں اور ملک میں فساد کرتے ہیں وہی لوگ نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 2, 28, 'تم الله کا کیونکر انکار کرسکتے ہو حالانکہ تم بے جان تھے پھر تمہیں زندہ کیا پھر تمہیں مارے گا پھر تمہیں زندہ کرے گا پھر تم اسی کے پاس لوٹ کر جاؤ گے'),
  ('ur.ahmedali', 2, 29, 'الله وہ ہے جس نے جو کچھ زمین میں ہے سب تمہارے لیے پیدا کیا ہےپھر آسمان کی طرف متوجہ ہوا تو انہیں سات آسمان بنایا اور وہ ہر چیز جانتا ہے'),
  ('ur.ahmedali', 2, 30, 'اور جب تیرے رب نے فرشتوں سے کہا میں زمین میں ایک نائب بنانے والا ہوں فرشتوں نے کہا کیا تو زمین میں ایسے شخص کو نائب بنانا چاہتا ہے جو فساد پھیلائے اور خون بہائے حالانکہ ہم تیری حمد کے ساتھ تسبیح بیان کرتے اور تیری پاکی بیان کرتے ہیں فرمایا میں جو کچھ جانتا ہوں وہ تم نہیں جانتے'),
  ('ur.ahmedali', 2, 31, 'اور الله نے آدم کو سب چیزوں کے نام سکھائے پھر ان سب چیزوں کو فرشتوں کے سامنے پیش کیا پھر فرمایا مجھے ان کے نام بتاؤ اگر تم سچے ہو'),
  ('ur.ahmedali', 2, 32, 'انہوں نے کہا تو پاک ہے ہم تو اتنا ہی جانتے ہیں جتنا تو نے ہمیں بتایاہے بے شک تو بڑے علم والا حکمت والا ہے'),
  ('ur.ahmedali', 2, 33, 'فرمایا اے آدم ان چیزو ں کے نام بتا دو پھر جب آدم نے انہیں ان کے نام بتا دیئے فرمایا کیا میں نے تمہیں نہیں کہا تھا کہ میں آسمانوں اور زمین کی چھپی ہوئی چیزیں جانتا ہوں اور جو تم ظاہر کرتے ہو اور جو چھپاتے ہو اسے بھی جانتا ہوں'),
  ('ur.ahmedali', 2, 34, 'اورجب ہم نے فرشتوں سے کہا کہ آدم کو سجدہ کرو تو انہوں نے سجدہ کیا مگر ابلیس کہ اس نے انکار کیا اورتکبر کیا اورکافروں میں سے ہو گیا'),
  ('ur.ahmedali', 2, 35, 'اور ہم نے کہا اے آدم تم اور تمہاری بیوی جنت میں جا کر رہو اور اس میں جو چاہو اور جہاں سےچاہو کھاؤ اور اس درخت کے نزدیک نہ جاؤ پھر ظالموں میں سے ہو جاؤ گے'),
  ('ur.ahmedali', 2, 36, 'پھر شیطان نے ان کو وہاں سے ڈگمگایا پھر انہیں اس عزت و راحت سے نکالا کہ جس میں تھے اور ہم نے کہا تم سب اترو کہ تم ایک دوسرے کے دشمن ہو اور تمہارے لیے زمین میں ٹھکانا ہے اور سامان ایک وقت معین تک'),
  ('ur.ahmedali', 2, 37, 'پھر آدم نے اپنے رب سے چند کلمات حاصل کیے پھر اس کی توبہ قبول فرمائی بے شک وہ توبہ قبول کرنے والا مہربان ہے'),
  ('ur.ahmedali', 2, 38, 'ہم نے کہا کہ تم سب یہاں سے نیچے اتر جاؤ پھر اگرتمہارے پاس میری طرف سے کوئی ہدایت آئے پس جو میری ہدایت پر چلیں گے ان پرنہ کچھ خوف ہوگا اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 2, 39, 'اور جو انکار کریں گے اور ہماری آیتوں کو جھٹلائیں گے وہی دوزخی ہو ں گے جو اس میں ہمیشہ رہی گے'),
  ('ur.ahmedali', 2, 40, 'اے بنی اسرائل میرے احسان یاد کرو جو میں نے تم پر کئے اور تم میرا عہد پورا کرو میں تمہارا عہد پورا کروں گا اور مجھ ہی سے ڈرا کرو'),
  ('ur.ahmedali', 2, 41, 'اور اس کتاب پر ایمان لاؤ جو میں نے نازل کی تصدیق کرتی ہے اس کی جو تمہارے پاس ہے اور تم ہی سب سے پہلے اس کےمنکر نہ بنو اور میری آیتو ں کو تھوڑی قیمت پر نہ بیچو اور مجھ ہی سے ڈرو'),
  ('ur.ahmedali', 2, 42, 'اور سچ میں جھوٹ نہ ملاؤ اور جان بوجھ کر حق کو نہ چھپاؤ'),
  ('ur.ahmedali', 2, 43, 'اورنماز قائم کرو اوزکوةٰ دو اور رکوع کرنے والوں کے ساتھ رکوع کرو'),
  ('ur.ahmedali', 2, 44, 'کیا لوگوں کو تم نیکی کا حکم کرتے ہو اور اپنے آپ کو بھول جاتے ہو حالانکہ تم کتاب پڑھتے ہو پھر کیوں نہیں سمجھتے'),
  ('ur.ahmedali', 2, 45, 'اور صبر کرنے اور نماز پڑھنے سےمدد لیا کرو اوربے شک نماز مشکل ہے مگر ان پر جو عاجزی کرنے والے ہیں'),
  ('ur.ahmedali', 2, 46, 'جو یہ سمجھتے ہیں کہ ہمیں ضرور اپنے رب سے ملنا ہے اور ہمیں اس کے پاس لوٹ کر جانا ہے'),
  ('ur.ahmedali', 2, 47, 'اے بنی اسرائیل میری ان نعمتوں کو یاد کرو جو میں نے تمہیں دی تھیں اور میں نے تمہیں جہان پر فضیلت دی تھی'),
  ('ur.ahmedali', 2, 48, 'اوراس دن سے ڈرو جس دن کوئی شخص کسی کے کچھ بھی کام نہ آئے گا اور نہ ان کے لیے کوئی سفارش قبول ہو گی اورنہ اس کی طرف سے بدلہ لیا جائے گا اور نہ ان کی مدد کی جائے گی'),
  ('ur.ahmedali', 2, 49, 'اور جب ہم نے تمہیں فرعونیوں سے نجات دی و ہ تمہیں بری طرح عذاب دیا کرتے تھے تمہارے بیٹوں کو ذبح کرتے تھے اور تمہاری بیٹیوں کو زندہ رکھتے تھے اور اس میں تمہارے رب کی طرف سے تمہاری بڑی آزمائش تھی'),
  ('ur.ahmedali', 2, 50, 'اور جب ہم نے تمہارے لیے سمندر کو پھاڑ دیا پھر تمہیں تو بچا لیا اور تمہارے دیکھتے دیکھتے فرعوینوں کو ڈبو دیا'),
  ('ur.ahmedali', 2, 51, 'اورجب ہم نے موسیٰ سے چالیس رات کا وعدہ کیا پھر اس کے بعد تم نے بچھڑا بنا لیا حالانکہ تم ظالم تھے'),
  ('ur.ahmedali', 2, 52, 'پھر اس کے بعدبھی ہم نے تمہیں معاف کر دیا تاکہ تم شکر کرو'),
  ('ur.ahmedali', 2, 53, 'اورجب ہم نے موسیٰ کو کتاب اورقانون فیصل دیا تاکہ تم ہدایت پاؤ'),
  ('ur.ahmedali', 2, 54, 'اور جب موسیٰ نے اپنی قوم سے کہا اے میری قوم بے شک تم نے بچھڑا بنا کر اپنی جانوں پر ظلم کیا سو اپنے پیدا کرنے والے کے آگے توبہ کرو پھر اپنے آپ کو قتل کرو تمہارے لیے تمہارے خالق کے نزدیک یہی بہتر ہے پھر اس نے تمہاری توبہ قبول کر لی بے شک وہی بڑا توبہ قبول کرنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 55, 'اور جب تم نے کہا اے موسیٰ ہم ہرگز تیرا یقین نہیں کریں گے جب تک کہ روبرو الله کو دیکھ نہ لیں تب تمہیں بجلی نے دیکھتے ہی دیکھتے آ لیا'),
  ('ur.ahmedali', 2, 56, 'پھر ہم نے تمہیں تمہاری موت کے بعد زندہ کر اٹھایا تاکہ تم شکر کرو'),
  ('ur.ahmedali', 2, 57, 'اور ہم نے تم پر ابر کا سایہ کیا اور تم پر من اور سلویٰ اتارا جو کچھ ہم نے تمہیں پاکیزہ چیزیں عطا کی ہیں ان میں سے کھاؤ اور انہوں نے ہمارا کچھ نقصان نہ کیا بلکہ اپنا ہی نقصان کرتے رہے'),
  ('ur.ahmedali', 2, 58, 'اور جب ہم نے کہا اس شہر میں داخل ہو جاؤ پھر اس میں جہاں سے چاہو بے تکلفی سے کھاؤ اور دروازہ میں سجدہ کرتے ہوئے داخل ہو اور کہتے جاؤ بخش دے تو ہم تمہارے قصور معاف کر دیں گے اور نیکی کرنے والوں کو زیادہ بھی دیں گے'),
  ('ur.ahmedali', 2, 59, 'پھر ظالموں نے بدل ڈالا کلمہ سوائے اس کے جو انہیں کہا گیا تھا سو ہم نے ان ظالموں پر ان کی نافرمانی کی وجہ سے آسمان سے عذاب نازل کیا'),
  ('ur.ahmedali', 2, 60, 'پھر جب موسیٰ نے اپنی قوم کے لیے پانی مانگا تو ہم نے کہا اپنے عصا کو پتھر پر مار سو اس سے بارہ چشمے بہہ نکلے ہر قوم نے اپنا گھاٹ پہچان لیا الله کے دیئے ہوئے رزق میں سے کھاؤ پیو اور زمین میں فساد مچاتےنہ پھرو'),
  ('ur.ahmedali', 2, 61, 'اور جب تم نے کہا اے موسیٰ ہم ایک ہی طرح کے کھانے پر ہرگز صبر نہ کریں گے سو ہمارے لیے اپنے رب سے دعا مانگ کہ وہ ہمارے لیے زمین کی پیداوار میں سے ساگ اور ککڑی اور گیہوں اور مسور اور پیاز پیدا کر دے کہا کیا تم اس چیز کو لینا چاہتے ہو جو ادنیٰ ہے بدلہ اس کے جو بہتر ہے کسی شہر میں اُترو بے شک جو تم مانگتے ہو تمہیں ملے گا اور ان پر ذلت اور محتاجی ڈال دی گئی اور انہوں نے غضب الہیٰ کمایا یہ اس لیے کہ وہ الله کی نشانیوں کا انکار کرتے تھے اور نبیوں کو ناحق قتل کرتے تھے یہ اس لیے کہ نافرمان تھے اور حد سے بڑھ جاتے تھے'),
  ('ur.ahmedali', 2, 62, 'جو کوئی مسلمان اور یہودی اور نصرانی اورصابئی الله اور قیامت کے دن پر ایمان لائے اور اچھے کام بھی کرے تو ان کا اجر ان کے رب کے ہاں موجود ہے اور ان پر نہ کچھ خوف ہو گا اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 2, 63, 'اور جب ہم نے تم سے عہد لیا اور تم پر کوہِ طور بلند کیا جو کچھ ہم نے تمہیں دیا ہے اسے مضبوط پکڑو اور جو کچھ اس میں ہے اسے یاد رکھو تاکہ تم پرہیزگار ہو جاؤ'),
  ('ur.ahmedali', 2, 64, 'پھر تم اس کے بعد پھر گئے سو اگر تم پر الله کا فضل اور اس کی رحمت نہ ہوتی تو تم تباہ ہوجاتے'),
  ('ur.ahmedali', 2, 65, 'اور بے شک تمہیں وہ لوگ بھی معلوم ہیں جنہوں نے تم میں سے ہفتہ کے دن زیادتی کی تھی پھر ہم نے ان سے کہا تم ذلیل بندر ہو جاؤ'),
  ('ur.ahmedali', 2, 66, 'پھر ہم نے اس واقعہ کو اس زمانہ کے لوگوں کے لیے اور ان سے پچھلوں کے لیے عبرت اور پرہیز گاروں کے لیے نصیحت بنا دیا'),
  ('ur.ahmedali', 2, 67, 'اور جب موسیٰ نے اپنی قوم سے کہا کہ الله تمہیں حکم دیتا ہے کہ ایک گائے ذبح کرو انہوں نے کہا کیا تم ہم سے ہنسی کرتا ہے کہا میں الله کی پناہ مانگتا ہوں اس سے کہ جاہلوں میں سے ہوں'),
  ('ur.ahmedali', 2, 68, 'انہوں نے کہا ہمارے لیے اپنے رب سے دعا کر ہمیں بتائے کہ وہ گائے کیسی ہے کہا وہ فرماتا ہے کہ وہ ایک ایسی گائے ہے نہ بوڑھی اور نہ بچہ اس کے درمیان ہے پس کر ڈالو جو تمہیں حکم دیا جاتا ہے'),
  ('ur.ahmedali', 2, 69, 'انہوں نے کہا ہمارے لیے اپنے رب سے دعا کر کہ ہمیں بتائے اس کا رنگ کیسا ہےکہاوہ فرماتا ہے کہ وہ ایک زرد گائے ہے اس کا رنگ خوب گہراہے دیکھنے والوں کو بھلی معلوم ہوتی ہے'),
  ('ur.ahmedali', 2, 70, 'انہوں نے کہا ہمارے لیے اپنے رب سے دعا کر ہمیں بتائے کہ وہ کس قسم کی ہے کیوں کہ وہ گائے ہم پر مشتبہ ہو گئی ہے اور ہم اگر الله نے چاہا تو ضرور پتہ لگا لیں گے'),
  ('ur.ahmedali', 2, 71, 'کہا و ہ فرماتا ہے کہ وہ ایک ایسی گائے ہے محنت کرنے والی نہیں جو زمین کو جوتتی ہو یا کھیتی کو پانی دیتی ہو بے عیب ہے اس میں کوئي داغ نہیں انہوں نے کہا اب تو نے ٹھیک بات بتائی پھر انہوں نے اسے ذبح کر دیا اور وہ کرنے والے تو نہیں تھے'),
  ('ur.ahmedali', 2, 72, 'اور جب تم ایک شخص قتل کر کے اس میں جھگڑنے لگے اور الله ظاہر کرنے والا تھا اس چیز کو جسے تم چھپاتے تھے'),
  ('ur.ahmedali', 2, 73, 'پھر ہم نے کہا اس مردہ پر اس گائے کا ایک ٹکڑا مارو اسی طرح الله مردوں کو زندہ کرے گا اور تمہیں اپنی قدرت کی نشانیاں دکھاتا ہے تاکہ تم سمجھو'),
  ('ur.ahmedali', 2, 74, 'پھر ا سکے بعد تمہارے دل سخت ہو گئے گویا کہ وہ پتھر ہیں یا ان سے بھی زیادہ سخت اور بعض پتھر تو ایسے بھی ہیں جن سے نہریں پھوٹ کر نکلتی ہیں اور بعض ایسے بھی ہیں جو پھٹتے ہیں پھر ان سے پانی نکلتا ہے اور بعض ایسے بھی ہیں جو الله کے ڈر سے گر پڑتے ہیں اور الله تمہارے کاموں سے بے خبر نہیں'),
  ('ur.ahmedali', 2, 75, 'کیا تمہیں امید ہے کہ یہود تمہارے کہنے پر ایمان لے آئیں گے حالانکہ ان میں ایک ایسا گروہ بھی گزرا ہے جو الله کا کلام سنتا تھا پھر اسے سمجھنے کے بعد جان بوجھ کر بدل ڈالتا تھا'),
  ('ur.ahmedali', 2, 76, 'اور جب وہ ان لوگوں سے ملتے ہیں جو ایمان لاچکے ہیں تو کہتے ہیں ہم بھی ایمان لے آئےہیں اور جب وہ ایک دوسرے کے پاس علیحدٰہ ہوتے ہیں تو کہتے ہیں کیا تم انہیں وہ راز بتا دیتےہو جو الله نے تم پر کھولے ہیں تاکہ وہ اس سے تمہیں تمہارے رب کے روبرو الزام دیں کیا تم نہیں سمجھتے'),
  ('ur.ahmedali', 2, 77, 'کیا وہ نہیں جانتے کہ الله جانتا ہے جو وہ چھپاتے ہیں اور جو وہ ظاہر کرتے ہیں'),
  ('ur.ahmedali', 2, 78, 'اور بعض ان میں سے ان پڑھ ہیں جو کتاب نہیں جانتے سوائے جھوٹی آرزوؤں کے اور وہ محض اٹکل پچو باتیں بناتے ہیں'),
  ('ur.ahmedali', 2, 79, 'سو افسوس ہے ان لوگوں پر جو اپنے ہاتھوں سے لکھتے ہیں پھر کہتے ہیں کہ یہ الله کی طرف سے ہے تاکہ اس سے کچھ روپیہ کمائیں پھر افسوس ہے ان کے ہاتھوں کے لکھنے پر اور افسوس ہے ان کی کمائی ہر'),
  ('ur.ahmedali', 2, 80, 'اور کہتے ہیں ہمیں سوائے چند گنتی کے دنوں کے آگ نہیں چھوٹے گی کہہ دو کیا تم نے الله سے کوئی عہدلےلیا ہے کہ ہر گز الله اپنے عہد کا خلاف نہیں کرے گا یا تم الله پر وہ باتیں کہتے ہو جو تم نہیں جانتے'),
  ('ur.ahmedali', 2, 81, 'ہاں جس نے کوئی گناہ کیا اور اسے اس کے گناہ نے گھیر لیا سو وہی دوزخی ہیں وہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 2, 82, 'اور جو لوگ ایمان لائے اور نیک کام کئے وہی بہشتی ہیں وہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 2, 83, 'اور جب ہم نے بنی اسرائیل سے عہد لیا کہ الله کے سوا کسی کی عبادت نہ کرنا اور ماں باپ اور رشتہ داروں اور یتیموں اور محتاجوں سے اچھا سلوک کرنا اور لوگوں سے اچھی بات کہنا اور نماز قائم کرنا اور زکوةٰ دینا پھر سوائے چند آدمیوں کے تم میں سے سب منہ موڑ کر پھر گئے'),
  ('ur.ahmedali', 2, 84, 'اور جب ہم نے تم سے عہد لیا کہ آپس میں خونریزی نہ کرنا اور نہ اپنے لوگوں کو جلا وطن کرنا پھر تم نے اقرار کیا اور تم خود گواہ ہو'),
  ('ur.ahmedali', 2, 85, 'پھر تم ہی وہ ہو کہ اپنے لوگوں کو قتل کرتے ہو اور ایک جماعت کو اپنے میں سے ان کے گھروں میں سے نکالتے ہو ان پر گناہ اور ظلم سے چڑھائی کرتے ہو اور اگر وہ تمہارے پاس قیدی ہو کر آئیں تو ان کا تاوان دیتے ہو حالانکہ تم پر ان کا نکالنا بھی حرام تھا کیا تم کتاب کے ایک حصہ پرایمان رکھتے ہو اور دوسرے حصہ کا انکار کرتے ہو پھرجو تم میں سے ایسا کرے اس کی یہی سزا ہے کہ دنیا میں ذلیل ہو اور قیامت کے دن بھی سخت عذاب میں دھکیلے جائیں اور الله اس سے بے خبر نہیں جو تم کرتے ہو'),
  ('ur.ahmedali', 2, 86, 'یہی وہ لوگ ہیں جنہوں نے دنیا کی زندگی کو آخرت کے بدلہ خریدا سو ان سے عذاب ہلکانہ کیا جائے گا اور نہ انہیں کوئی مدد مل سکے گی'),
  ('ur.ahmedali', 2, 87, 'اور بے شک ہم نے موسیٰ کو کتاب دی اور اس کے بعد بھی پے در پے رسول بھیجتے رہے اور ہم نے عیسیٰ مریم کے بیٹے کو نشانیاں دیں اور روح لقدس سے اس کی تائید کی کیا جب تمہارے پاس کوئی وہ حکم لایا جسے تمہارے دل نہیں چاہتے تھے تو تم اکڑ بیٹھے پھر ایک جماعت کو تم نے جھٹلایا اور ایک جماعت کو قتل کیا'),
  ('ur.ahmedali', 2, 88, 'اور کہتے ہیں ہمارے دلوں پر غلاف ہیں بلکہ الله نے ان کے کفر کے سبب سے لعنت کی ہے سو بہت ہی کم ایمان لاتے ہیں'),
  ('ur.ahmedali', 2, 89, 'اور جب ان کے پاس اللہ کی طرف سے کتاب آئی جو تصدیق کرتی ہے اس کی جو ان کے پاس ہے اور اس سے پہلے وہ کفار پر فتح مانگا کرتے تھے پھر جب ان کے پاس وہ چیز آئی جسے انہوں نے پہچان لیا تو اس کا انکارکیاسوکافروں پر الله کی لعنت ہے'),
  ('ur.ahmedali', 2, 90, 'انہوں نے اپنی جانوں کو بہت ہی بری چیز کے لیے بیچ ڈالا یہ کہ الله کی نازل کی ہوئی چیزوں کا اس ضد میں آ کر انکار کرنے لگے کہ وہ پنے فضل کو اپنے بندوں میں سے جس پر چاہتا ہے کیوں نازل کر دیتا ہے سوغضب پر غضب میں آ گئے اور کافروں کے لیے ذلت کا عذاب ہے'),
  ('ur.ahmedali', 2, 91, 'اورجب ان سے کہا جاتا ہے کہ اس پر ایمان لاؤ جو الله نے نازل کیا ہے تو کہتے ہیں ہم تو اسی کو مانتے ہیں جو ہم پر اترا ہے اور اسے نہیں مانتے ہیں جو اس کے سوا ہے حالانکہ وہ حق ہے اور تصدیق کرنے والی ہے جو ان کے پاس ہے کہہ دو پھر تم کیوں اس سے پہلے الله کے نبیوں کو قتل کرتے رہے اگر تم مومن تھے'),
  ('ur.ahmedali', 2, 92, 'اور تمہارے پاس موسیٰ صریح معجزے لے کر آیا پھر تم نے اس کے بعد بچھڑے کو بنالیا اور تم ظالم تھے'),
  ('ur.ahmedali', 2, 93, 'اور جب ہم نے تم سے عہد لیا اور تم پر کوہِ طورکو اٹھایا کہ جو ہم نے تمہیں دیا ہے اسے مضبوطی سے پکڑو اور سنو انہوں نے کہا ہم نے سن لیا اور مانیں گے نہیں اور ان کے دلوں میں کفر کی وجہ سے بچھڑے کی محبت رچ گئی تھی کہہ دو اگر تم ایمان دار ہو تو تمہارا ایمان تمہیں بہت ہی برا حکم دے رہا ہے'),
  ('ur.ahmedali', 2, 94, 'کہہ دو اگر الله کے نزدیک آخرت کا گھر خصوصیت کے ساتھ سوائے اور لوگوں کے تمہارے ہی لئے ہے تو تم موت کی آرزو کرو اگر تم سچے ہو'),
  ('ur.ahmedali', 2, 95, 'وہ کبھی بھی اس کی ہر گز آرزو نہیں کریں گے ان گناہوں کی وجہ سے جو ان کے ہاتھ آگے بھیج چکے ہیں اور الله ظالموں کو خوب جانتا ہے'),
  ('ur.ahmedali', 2, 96, 'اور آپ انہیں زندگی پر سب لوگوں سے زيادہ حریص پائیں گے اور ان سے بھی جو مشرک ہیں ہرایک ان میں سے چاہتا ہے کہ کاش اسے ہزار برس عمرملے اور اسے عمر کا ملنا عذاب سے بچانے والا نہیں اور الله دیکھتا ہے جو وہ کرتے ہیں'),
  ('ur.ahmedali', 2, 97, 'کہہ دوجو کوئی جبرائیل کا دشمن ہو سواسی نے اتاراہے وہ قرآن اللہ کے حکم سے آپ کے دل پر ان کی تصدیق کرتا ہے جو اس سے پہلے ہیں اور ایمان والوں کے لئے ہدایت اور خوشخبری ہے'),
  ('ur.ahmedali', 2, 98, 'جو شخص اللہ اور اس کے فرشتوں اور اس کے رسولوں اور جبرائیل اور میکائیل کا دشمن ہو تو بیشک اللہ بھی ان کافروں کا دشمن ہے'),
  ('ur.ahmedali', 2, 99, 'اور ہم نے آپ کی طرف روشن آیتیں اتاری ہیں اور ان سے انکاری نہیں مگر فاسق'),
  ('ur.ahmedali', 2, 100, 'کیا جب کبھی انہوں نے کوئی عہد باندھا تو اسے ان میں سے ایک جماعت نے پھینک دیا بلکہ ان میں سے اکثرایمان ہی نہیں رکھتے'),
  ('ur.ahmedali', 2, 101, 'اور جب ان کے پاس الله کی طرف سے وہ رسول آیا جو اس کی تصدیق کرتا ہے جو ان کے پا س ہے تو اہلِ کتاب کی ایک جماعت نے الله کی کتاب کو اپنی پیٹھ کے پیچھے ایسا پھینکا کہ گویا اسے جانتے ہی نہیں'),
  ('ur.ahmedali', 2, 102, 'اور انہوں نے اس چیز کی پیروی کی جو شیطان سلیمان کی بادشاہت کے وقت پڑھتے تھے اور سلیمان نے کفر نہیں کیا تھا لیکن شیطانوں نے ہی کفر کیا لوگوں کو جادو سکھاتے تھے اور اس کی بھی جو شہر بابل میں ہاروت و ماروت دوفرشتوں پر اتارا گیا تھا اور وہ کسی کو نہ سکھاتے تھے جب تک یہ نہ کہہ دیتے ہم تو صرف آزمائش کے لیے ہیں تو کافر نہ بن پس ان سے وہ بات سیکھتے تھے جس سے خاوند اور بیوی میں جدائی ڈالیں حالانکہ وہ اس سے کسی کو الله کے حکم کے سوا کچھ بھی نقصان نہیں پہنچا سکتے تھے اور سیکھتے تھے وہ و ان کو نقصان دیتی تھی اورنہ نفع اور وہ یہ بھی جانتے تھے کہ جس نے جادو کو خریدا اس کے لیے آخرت میں کچھ حصہ نہیں اور وہ چیز بہت بری ہے جس کے بدلہ میں انہوں نے اپنے آپ کو بیچا کاش وہ جانتے'),
  ('ur.ahmedali', 2, 103, 'اور اگر وہ ایمان لاتے اور پرہیز گاری کرتے تو البتہ الله کے ہاں کا اجر ان کے لیے بہتر تھا کاش وہ جانتے'),
  ('ur.ahmedali', 2, 104, 'اے ایمان والو راعنا نہ کہو اور انظرنا کہو اور سنا کرو اور کافروں کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 2, 105, 'اہل کتاب کے کافر اور مشرک نہیں چاہتے کہ تمہارے رب کی طرف سے تم پر کوئی بھی اچھی بات نازل ہو اور الله اپنی رحمت کے ساتھ خاص کر لیتا ہے جسے چاہے اور الله بڑے فضل والا ہے'),
  ('ur.ahmedali', 2, 106, 'ہم جو کسی آیت کو منسوخ کرتے ہیں یا بھلا دیتے ہیں تو اس سے بہتر یا اس کے برابر لاتے ہیں کیا تم نہیں جانتے کہ الله ہر چیز پر قاد رہے'),
  ('ur.ahmedali', 2, 107, 'کیا تم نہیں جانتے الله ہی کے لیے آسمانوں اور زمین کی بادشاہت ہے اور تمہارے لیے الله کے سوا نہ کوئی دوست ہے نہ مددگار'),
  ('ur.ahmedali', 2, 108, 'کیا تم چاہتے ہو کہ اپنے رسول سے سوال کرو جیسے اس سے پہلے موسیٰ سے سوال کیے گئے تھے اور جو کوئی ایمان کے عوض کفر کوبدل لے سو وہ سیدھے راستہ سے گمراہ ہوا'),
  ('ur.ahmedali', 2, 109, 'اکثر اہلِ کتاب تو اپنے حسد سے حق ظاہر ہونے کے بعد بھی یہ چاہتے ہیں کہ کسی طرح سے تمہیں ایمان لانے کے بعد پھر کفر کی طرف لوٹا کر لے جائیں سو معاف کرو اور درگزر کرو جب تک کہ الله اپنا حکم بھیجے بے شک الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 2, 110, 'اور نماز قائم کرو اور زکوةٰ دو اور جو کچھ نیکی سے اپنےواسطے آگے بھیجو گے اسے الله کے ہاں پاؤ گے بے شک الله جو کچھ تم کرتے ہو سب دیکھتا ہے'),
  ('ur.ahmedali', 2, 111, 'اور کہتے ہیں کہ سوائے یہود یا نصاریٰ کے اور کوئی جنت میں ہرگز داخل نہ ہوگا یہ ان کے ڈھکوسلے ہیں کہہ دو اپنی دلیل لاؤ اگر تم سچے ہو'),
  ('ur.ahmedali', 2, 112, 'ہاں جس نے اپنا منہ الله کے سامنے جھکا دیا اور وہ نیکو کار بھی ہو تو اس کے لیے اس کا بدلہ اس کے رب کے ہاں ہے اور ان پر نہ کوئی خوف ہوگا اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 2, 113, 'اور یہود کہتے ہیں کہ نصاریٰ ٹھیک راہ پر نہیں اور نصاریٰ کہتے ہیں کہ یہودی راہے حق پر نہیں ہیں حالانکہ وہ سب کتاب پڑھتے ہیں ایسی ہی باتیں وہ لوگ بھی کہتے ہیں جو بے علم ہیں پھر الله قیامت کے دن ان باتوں کا کہ جس میں وہ جھگڑ رہے ہیں خودفیصلہ کرے گا'),
  ('ur.ahmedali', 2, 114, 'اوراس سے بڑھ کر کون ظالم ہوگا جس نے الله کی مسجدوں میں اس کا نام لینے کی ممانعت کردی اور ان کے ویران کرنے کی کوشش کی ایسے لوگوں کا حق نہیں ہے کہ ان میں داخل ہوں مگر ڈرتے ہوئے ان کے لیے دنیا میں بھی ذلت ہے اوران کے لیے آخرت میں بہت بڑا عذاب ہے'),
  ('ur.ahmedali', 2, 115, 'اورمشرق اور مغرب الله ہی کا ہے سو تم جدھر بھی رخ کرو ادھر ہی الله کا رخ ہے بے شک الله وسعت ولا جاننے والا ہے'),
  ('ur.ahmedali', 2, 116, 'اور کہتے ہیں الله نے بیٹا بنایاہے حالانکہ وہ پاک ہے بلکہ جو کچھ آسمانوں اور زمین میں ہے سب اسی کا ہے سب اسی کے فرمانبردار ہیں'),
  ('ur.ahmedali', 2, 117, 'آسمانوں اور زمین کا پیدا کرنے والا ہے اور جب کوئی چیز کرنا چاہتا ہے تو صرف یہی کہہ دیتا ہے کہ ہو جا سو وہ ہو جاتی ہے'),
  ('ur.ahmedali', 2, 118, 'اوربے علم کہتے ہیں کہ الله ہم سے کیوں کلام نہیں کرتا یا ہمارے اس کوئی نشانی کیوں نہیں آتی ان سے پہلے لوگ بھی ایسی ہی باتیں کہہ چکے ہیں ان کے دل ایک جیسے ہیں یقین کرنے والوں کے لیے تو ہم نشانیاں بیان کر چکے ہیں'),
  ('ur.ahmedali', 2, 119, 'بے شک ہم نے تمہیں سچائ کے ساتھ بھیجا ہے خوشخبری سنانے کے لیے اور ڈرانے کے لیے اور تم سے دوزخیوں کے متعلق باز پرس نہ ہو گی'),
  ('ur.ahmedali', 2, 120, 'اورتم سے یہود اور نصاریٰ ہرگز راضی نہ ہوں گے جب تک کہ تم ان کے دین کی پیروی نہیں کرو گے کہہ دو بے شک ہدایت الله ہی کی ہدایت ہے اور اگر تم نے ان کی خواہشوں کی پیروی کی اس کے بعد جو تمہارے پاس علم آ چکا تو تمہارے لیے الله کے ہاں کوئی دوست اور مددگار نہیں ہوگا'),
  ('ur.ahmedali', 2, 121, 'وہ لوگ جنہیں ہم نے کتاب دی ہے وہ اسے پڑھتے ہیں جیسا اس کے پڑھنے کا حق ہے وہی لوگ اس پر ایمان لاتے ہیں جور اس سے انکار کرتے ہیں وہی نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 2, 122, 'اے بنی اسرائل میرے احسان کو یاد کرو جو میں نے تم پر کیے اور بے شک میں نے تمہیں سارے جہاں پر بزرگی دی تھی'),
  ('ur.ahmedali', 2, 123, 'اوراس دن سے ڈرو جس دن کوئی بھی کسی کے کام نہ آئے گا اور نہ اس سے بدلہ قبول کیا جائے گا اور نہ اسے کوئی سفارش نفع دے گی اور نہ وہ مدد دیے جائیں گے'),
  ('ur.ahmedali', 2, 124, 'اور جب ابراھیم کو اس کے رب نے کئی باتوں میں آزمایا تو اس نےانہیں پورا کر دیا فرمایا بے شک میں تمہیں سب لوگوں کا پیشوا بنادوں گا کہا اور میری اولاد میں سے بھی فرمایا میرا عہد ظالموں کو نہیں پہنچے گا'),
  ('ur.ahmedali', 2, 125, 'اور جب ہم نے کعبہ لوگوں کے لیے عبادت گاہ اور امن کی جگہ بنایا (اور فرمایا) مقام ابراہیم کو نماز کی جگہ بناؤ اور ہم نے ابراھیم اور اسماعیل سے عہد لیا کہ میرے گھر کو طواف کرنے والوں اور اعتکاف کرنے والوں اور رکوع کرنے والوں اور سجدہ کرنے والوں کے لیے پاک رکھو'),
  ('ur.ahmedali', 2, 126, 'اورجب ابراھیم نے کہا اے میرے رب اسے امن کا شہر بنا دے اور اس کے رہنےو الوں کو پھلوں سے رزق دے جوکوئی ان میں سے الله اور قیامت کے دن پر ایمان لائے فرمایا اور جو کافر ہوگا سو اسے بھی تھوڑاسا فائدہ پہنچاؤں گا پھر اسے دوزخ کے عذاب میں دھکیل دوں گا اوروہ برا ٹھکانہ ہے'),
  ('ur.ahmedali', 2, 127, 'اور جب ابراھیم اور اسماعیل کعبہ کی بنیادیں اٹھا رہے تھے اے ہمارے رب ہم سے قبول کر بے شک تو ہی سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 128, 'اے ہمارے رب ہمیں اپنا فرمانبردار بنا دے اور ہماری اولاد میں سے بھی ایک جماعت کو اپنافرمانبردار بنا اور ہمیں ہمارے حج کے طریقے بتا دے اور ہماری توبہ قبول فرما بے شک تو بڑا توبہ قبول کرنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 129, 'اے ہمارے رب اور ان میں ایک رسول انہیں میں سے بھیج جو ان پر تیری آیتیں پڑھیں اور انہیں کتاب اور دانائی سکھائے اور انہیں پاک کرے بے شک تو ہی غالب حکمت والا ہے'),
  ('ur.ahmedali', 2, 130, 'اور کون ہے جو ملت ابراھیمی سے روگردانی کرے سوائے اس کے جو خود ہی احمق ہو اور ہم نے تو اسے دنیا میں بھی بزرگی دی تھی اور بے شک وہ آخرت میں بھی اچھے لوگوں میں سے ہوگا'),
  ('ur.ahmedali', 2, 131, 'جب اسے اس کے رب نے کہا فرمانبردار ہو جا تو کہا میں جہانوں کا پروردگار کا فرمانبردار ہوں'),
  ('ur.ahmedali', 2, 132, 'اور اسی بات کی ابراھیم اور یعقوب نے بھی اپنے بیٹوں کو وصیت کی کہ اے میرے بیٹو بے شک الله نےتمہارے لیے یہ دین چن لیا سو تم ہر گز نہ مرنا مگر درآنحالیکہ تم مسلمان ہو'),
  ('ur.ahmedali', 2, 133, 'کیا تم حاضر تھے جب یعقوب کو موت آئی تب اس نے اپنے بیٹوں سے کہا تم میرے بعد کس کی عبادت کرو گے انہوں نے کہا ہم آپ کے اور آپ کے باپ دادا ابراھیم اور اسماعیل اور اسحاق کے معبود کی عبادت کریں گے جو ایک معبود ہے اور ہم اسی کے فرمانبردار ہیں'),
  ('ur.ahmedali', 2, 134, 'یہ ایک جماعت تھی جو گزرچکی ان کے لیے ان کے اعمال میں اور تمہارے لیے اور تمہارے اعمال ہیں اور تم سے نہیں پوچھا جائے گا کہ وہ کیا کرتے تھے'),
  ('ur.ahmedali', 2, 135, 'اور کہتے ہیں کہ یہودی یا نصرانی ہو جاؤ تاکہ ہدایت پاؤ کہہ دو بلکہ ہم تو ملت ابراھیمی پر رہیں گے جو موحد تھا اور مشرکوں میں سے نہیں تھا'),
  ('ur.ahmedali', 2, 136, 'کہہ دو ہم الله پر ایمان لائے اور اس پر جو ہم پر اتارا گیا اور جو ابراھیم اور اسماعیل اور اسحاق اور یعقوب اور اس کی اولاد پر اتارا گیا اور جو موسیٰ اور عیسیٰ کو دیا گیا اور جو دوسرے نبیوں کو ان کے رب کی طرف سے دیا گیا ہم کسی ایک میں ان میں سے فرق نہیں کرتے اور ہم اسی کے فرمانبردار ہیں'),
  ('ur.ahmedali', 2, 137, 'پس اگر وہ بھی ایمان لے آئيں جس طرح تم ایمان لائے ہو تو وہ بھی ہدایت پا گئے اور اگر وہ نہ مانیں تو وہی ضد میں پڑے ہوئے ہیں سو تمہیں ان سے الله کافی ہے اور وہی سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 138, 'الله کا رنگ اللہ کے رنگ سے اور کس کا رنگ بہتر ہے اور ہم تو اسی کی عبادت کرتے ہیں'),
  ('ur.ahmedali', 2, 139, 'کہہ دو کیا تم ہم سے الله کی نسبت جھگڑا کرتے ہو حالانکہ وہی ہمارا اور تمہارا رب ہے اور ہمارے لیے ہمارے عمل ہیں اور تمہاری لئے تمہارے عمل او رہم تو خا لص اسی کی عبادت کرتے ہیں'),
  ('ur.ahmedali', 2, 140, 'یا تم کہتے ہو کہ ابراھیم اور اسماعیل اور اسحاق اور یعقوب اور اس کی اولاد یہودی یا نصرانی تھے کہہ دو کیا تم زیادہ جانتے ہو یا الله اور اس سے بڑھ کر کون ظالم ہے جو گواہی چھپائے جو اس کے پاس الله کی طرف سے ہےاور الله بے خبر نہیں اس سے جو تم کرتے ہو'),
  ('ur.ahmedali', 2, 141, 'وہ ایک جماعت تھی جو گزر چکی ان کے لیے ان کے عمل ہیں اور تمہارے لیے تمہارے عمل ہیں اور تم سے ان کے اعمال کی نسبت نہیں پوچھا جائے گا'),
  ('ur.ahmedali', 2, 142, 'بے وقوف لوگ کہیں گے کہ کس چیز نے مسلمانوں کو ان کے قبلہ سے پھیر دیا جس پر وہ تھے کہہ دو مشرق اور مغرب الله ہی کا ہے وہ جسے چاہتا ہے سیدھا راستہ دکھاتا ہے'),
  ('ur.ahmedali', 2, 143, 'اور اسی طرح ہم نے تمہیں برگزیدہ امت بنایا تاکہ تم اور لوگوں پر گواہ ہو اور رسول تم پر گواہ ہو اور ہم نے وہ قبلہ نہیں بنایا تھا جس پر آپ پہلے تھے مگر اس لیے کہ ہم معلوم کریں اس کو جو رسول کی پیروی کرتا ہے اس سے جو الٹے پاؤں پھر جاتا ہےاور بے شک یہ بات بھاری ہے سوائے ان کے جنہیں الله نے ہدایت دی اور الله تمہارے ایمان کو ضائع نہیں کرے گا بے شک الله لوگوں پر بڑا مہربان نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 144, 'بے شک ہم آپ کے منہ کا آسمان کی طرف پھرنا دیکھ رہے ہیں سو ہم آپ کو اس قبلہ کی طرف پھیر دیں گے جسے آپ پسند کرتے ہیں پس اب اپنا منہ مسجد حرام کی طرف پھیر لیجیئے اور جہاں کہیں تم ہوا کرو اپنے مونہوں کو اسی کی طرف پھیر لیا کرو اور بے شک وہ لوگ جنہیں کتاب دی گئی ہے یقیناً جانتے ہیں کہ وہی حق ہے ان کے رب کی طرف سے اور الله اس سے بے خبر نہیں جو وہ کر رہے ہیں'),
  ('ur.ahmedali', 2, 145, 'اور اگر آپ ان کے سامنے تمام دلیلیں لے آئيں جنہیں کتاب دی گئی تو بھی وہ آپ کے قبلے کو نہیں مانیں گے اور نہ آپ ہی ان کے قبلہ کو ماننے والے ہیں اور نہ ان میں کوئی دوسرے قبلہ کو ماننے والا ہے اور اگر آپ ان کی خواہشوں کی پیروی کریں گے بعد اس کے کہ آپ کے پاس علم آ چکا تو بے شک آپ بھی تب ظالموں میں سے ہوں گے'),
  ('ur.ahmedali', 2, 146, 'وہ لوگ جنہیں ہم نے کتاب دی تھی وہ اسے پہچانتے ہیں جیسے اپنے بیٹوں کو پہچانتے ہیں اور بےشک کچھ لوگ ان میں سے حق کوچھپاتے ہیں اور وہ جانتے ہیں'),
  ('ur.ahmedali', 2, 147, 'آپ کے رب کی طرف سے حق وہی ہے پس شک کرنے والوں میں سے نہ ہو'),
  ('ur.ahmedali', 2, 148, 'اور ہر ایک کے لیے ایک طرف ہے جس طرف وہ منہ کرتا ہے پس تم نیکیوں کی طرف دوڑو تم جہاں کہیں بھی ہو گے تم سب کو الله سمیٹ کر لے آئے گا بے شک الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 2, 149, 'اور جہاں سے آپ نکلیں تو اپنا منہ مسجد حرام کی طرف کیا کریں اور آپ کے رب کی طرف سےیہی حق بھی ہے اور الله تمہارے کام سے غافل نہیں'),
  ('ur.ahmedali', 2, 150, 'اور آپ جہاں کہیں سے نکلیں تو اپنا منہ مسجد حرام کی طرف کیا کریں اور تم بھی جہاں کہیں ہو تو اپنا منہ ا س کی طرف کیاکر و تاکہ لوگوں کو تم پر کوئی الزام نہ رہے مگر ان میں سے جو ہٹ دھرم ہیں تم بھی ان سے نہ ڈرو اور ہم سے ڈرتے رہا کرو اور تاکہ میں اپنی نعمت تم پر پوری کروں اورتاکہ تم راہ پاؤ'),
  ('ur.ahmedali', 2, 151, 'جیسا کہ ہم نے تم میں ایک رسول تم ہی میں سے بھیجا جو تم پر ہماری آیتیں پڑھتا ہے اور تمہیں پاک کرتا ہے اور تمہیں کتاب اور دانائی سکھاتا ہے اور تمہیں سکھاتا ہے جو تم نہیں جانتے تھے'),
  ('ur.ahmedali', 2, 152, 'پس مجھے یاد کرو میں تمہیں یاد کروں گا اور میرا شکر کرو اور ناشکری نہ کرو'),
  ('ur.ahmedali', 2, 153, 'اے ایمان والو صبر اور نماز سے مدد لیا کرو بے شک اللہ صبر کرنے والوں کے ساتھ ہے'),
  ('ur.ahmedali', 2, 154, 'اور جو الله کی راہ میں مارے جائیں انہیں مرا ہوا نہ کہا کرو بلکہ وہ تو زندہ ہیں لیکن تم نہیں سمجھتے'),
  ('ur.ahmedali', 2, 155, 'اور ہم تمہیں کچھ خوف اور بھوک اور مالوں اور جانوں اور پھلوں کے نقصان سے ضرور آز مائيں گے اور صبر کرنے والوں کو خوشخبری دے دو'),
  ('ur.ahmedali', 2, 156, 'وہ لوگ کہ جب انہیں کوئی مصیبت پہنچتی ہے تو کہتے ہیں ہم تو الله کے ہیں اور ہم اسی کی طرف لوٹ کر جانے والے ہیں'),
  ('ur.ahmedali', 2, 157, 'یہ لوگ ہیں جن پر ان کے رب کی طرف سے مہربانیاں ہیں اور رحمت اور یہی ہدایت پانے والے ہیں'),
  ('ur.ahmedali', 2, 158, 'بے شک صفا اور مروہ الله کی نشانیوں میں سے ہیں پس جو کعبہ کا حج یا عمرہ کرے تو اس پر کوئی گناہ نہیں کہ ان کے درمیان طواف کرے اورجو کوئی اپنی خوشی سے نیکی کرے تو بے شک الله قدردان جاننے والا ہے'),
  ('ur.ahmedali', 2, 159, 'بے شک جو لوگ ان کھلی کھلی باتوں اور ہدایت کو جسے ہم نے نازل کر دیا ہے اس کے بعد بھی چھپاتے ہیں کہ ہم نے ان کو لوگوں کے لیے کتاب میں بیان کر دیا یہی لوگ ہیں کہ ان پر الله لعنت کرتا ہے اور لعنت کرنے والے لعنت کرتے ہیں'),
  ('ur.ahmedali', 2, 160, 'مگر وہ لوگ جنہوں نے توبہ کی اور اصلاح کر لی اور ظاہر کر دیا پس یہی لوگ ہیں کہ میں ان کی توبہ قبول کرتا ہوں اور میں بڑاتوبہ قبول کرنے والا نہایت رحم والا ہوں'),
  ('ur.ahmedali', 2, 161, 'بے شک جنہوں نے انکار کیا اور انکار ہی کی حالت میں مر بھی گئے تو ان پر الله کی لعنت ہے اور فرشتوں اور سب لوگوں کی بھی'),
  ('ur.ahmedali', 2, 162, 'وہ ہمیشہ اسی میں رہیں گے ان سے عذاب ہلکا نہ کیا جائے گا اور نہ وہ مہلت دیئے جائیں گے'),
  ('ur.ahmedali', 2, 163, 'اور تمہارا معبود ایک ہی معبود ہے جس کے سوا کوئی معبود نہیں بڑا مہربان نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 164, 'بے شک آسمانوں اور زمین کے پیدا کرنے میں اور رات اور دن کے بدلنے میں اور جہازوں میں جو دریا میں لوگوں کی نفع دینے والی چیزیں لے کر چلتے ہیں اور اس پانی میں جسسے الله نے آسمان سے نازل کیا ہے پھر اس سے مردہ زمین کو زندہ کرتا ہے اور اس میں ہر قسم کے چلنے والے جانور پھیلاتا ہے اور ہواؤں کے بدلنے میں اور بادل میں جو آسمان اور زمین کے درمیان حکم کا تابع ہے البتہ عقلمندوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 2, 165, 'اورایسے لوگ بھی ہیں جنہوں نے الله کے سوا اور شریک بنا رکھے ہیں جن سے ایسی محبت رکھتے ہیں جیسی کہ الله سے رکھنی چاہیئے اور ایمان والوں کو تو الله ہی سے زیادہ محبت ہوتی ہے اور کاش دیکھتے وہ لوگ جو ظالم ہیں جب عذاب دیکھیں گے کہ سب قوت الله ہی کے لیے ہے اور الله سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 2, 166, 'جب وہ لوگ بیزار ہو جائیں گے جن کی پیروی کی گئی تھی ان لوگوں سے جنہوں نے پیروی کی تھی اور وہ عذاب دیکھ لیں گے اور ان کے تعلقات ٹوٹ جائیں گے'),
  ('ur.ahmedali', 2, 167, 'اور کہیں گے وہ لوگ جنہوں نے پیروی کی تھی کاش ہمیں دوبارہ جانا ہوتا تو ہم بھی ان سے بیزار ہوجاتے جیسے یہ ہم سے بیزار ہو جاتے جیسے یہ ہم سے بیزار ہوئے ہیں اسی طرح الله انہیں ان کے اعمال حسرت دلانے کے لیے دکھائے گا اور وہ دوزخ سے نکلنے والے نہیں'),
  ('ur.ahmedali', 2, 168, 'اے لوگو ان چیزوں میں سے کھاؤ جو زمین میں حلال پاکیزہ ہیں اور شیطان کے قدموں کی پیروی نہ کرو بے شک وہ تمہارا صریح دشمن ہے'),
  ('ur.ahmedali', 2, 169, 'وہ تو تمہیں برائی اور بے حیائی ہی کا حکم دے گا اور یہ کہ الله کے ذمے تم وہ باتیں لگاؤ جنہیں تم نہیں جانتے'),
  ('ur.ahmedali', 2, 170, 'اور جب انہیں کہا جاتا ہے کہ اس کی پیروی کرو جو الله نے نازل کیا ہے تو کہتے ہیں بلکہ ہم تو اس کی پیروی کریں گے جس پر ہم نے اپنے باپ دادا کو پایا کیا اگرچہ ان کے باپ دادا کچھ بھی نہ سمجھتے ہوں اور نہ سیدھی راہ پائی ہو'),
  ('ur.ahmedali', 2, 171, 'اوران کی مثال جو کافر ہیں اس شخص کی سی ہے جو اس چیز کو پکارتا ہے جو سوائے پکار اور آواز کے نہیں سنتی وہ بہرے ہیں گونگے ہیں اندھے ہیں پس وہ نہیں سمجھتے'),
  ('ur.ahmedali', 2, 172, 'اے ایمان والو پاکیزہ چیزوں میں سے کھاؤ جو ہم نے تمہیں عطا کی اور الله کا شکر کرو اگر تم اس کی عبادت کرتے ہو'),
  ('ur.ahmedali', 2, 173, 'سوائے اس کے نہیں کہ تم پر مردار اور خون اورسؤر کا گوشت اور اور اس چیز کو کہ الله کے سوا اور کے نام سے پکاری گئی ہو حرام کیا ہے پس جو لاچار ہو جائے نہ سرکشی کرنے والا ہو اور نے حد سے بڑھنے والا تو اس پر کوئی گناہ نہیں بے شک الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 174, 'بے شک جو لوگ الله کی نازل کی ہوئی کتاب کو چھپاتے اور اس کے بدلے میں تھوڑا سا مول لیتے ہیں یہ لوگ اپنے پیٹوں میں نہیں کھاتے مگر آگ اور الله ان سے قیامت کے دن کلام نہیں کرے گا اور نہ انہیں پاک کرے گا اور ان کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 2, 175, 'یہی وہ لوگ ہیں جنہوں نے گمراہی کو بدلے ہدایت کے خریدا اور عذاب کو بدلے بخشش کے پس دوزخ کی آگ پر ان کا کتنا بڑا صبر ہے'),
  ('ur.ahmedali', 2, 176, 'یہ اس لیے کہ الله نے کتاب سچائی کے ساتھ اتاری اور بے شک جنہوں نے کتاب میں اختلاف کیا البتہ ضد میں بہت دور جا پڑے'),
  ('ur.ahmedali', 2, 177, 'یہی نیکی نہیں کہ تم اپنے منہ مشرق اور مغرب کی طرف پھیرو بلکہ نیکی تو یہ ہے جو الله اور قیامت کے دن پر ایمان لائے اورفرشتوں اور کتابوں او رنبیوں پر اور ا سکی محبت میں رشتہ دارو ں اور یتیموں اور مسکینوں اور مسافروں اور سوال کرنے والوں کو اور گردنوں کے چھڑانے میں مال دے اور نماز پڑھے اور زکوةٰ دے اور جو اپنے عہدوں کو پورا کرنے والے ہیں جب وہ عہد کر لیں اورتنگدستی میں اور بیماری میں اور لڑائی کےوقت صبر کرنے والے ہیں یہی سچے لوگ ہیں اوریہی پرہیزگار ہیں'),
  ('ur.ahmedali', 2, 178, 'اے ایمان والو مقتولوں میں برابری کرنا تم پر فرض کیا گیا ہے آزاد بدلے آزاد کے اور غلام بدلے غلام کے اور عورت بدلے عورت کے پس جسے اس کے بھائی کی طرف سے کچھ بھی معاف کیا جائے تو دستور کے موافق مطالبہ کرنا چاہیئے اور اسے نیکی کے ساتھ ادا کرنا چاہیئے یہ تمہارے رب کی طرف سے آسانی اور مہربانی ہے پس جو اس کے بعد زیادتی کرے تو اس کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 2, 179, 'اور اے عقلمندو تمہارے لیے قصاص میں زندگی ہے تاکہ تم (خونریزی سے) بچو'),
  ('ur.ahmedali', 2, 180, 'تم پر فرض کیا گیا ہے کہ جب تم میں سے کسی کو موت آ پہنچے اگر وہ مال چھوڑے تو ماں باپ اور رشتہ داروں کے لیے مناسب طور پر وصیت کرے یہ پرہیزگاروں پرحق ہے'),
  ('ur.ahmedali', 2, 181, 'پس جواسے اس کے سننے کےبعد بدل دے اس کا گناہ ان ہی پر ہے جو اسے بدلتے ہیں بے شک اللہ سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 182, 'پس جو وصیت کرنے والے سے طرف داری یا گناہ کا خوف کرے پھر ان کے درمیان اصلاح کر دے تو اس پر کوئی گناہ نہیں بے شک الله بڑا بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 183, 'اے ایمان والو تم پر روزے فرض کیے گئے ہیں جو تم سے پہلے تھے تاکہ تم پرہیز گار ہو جاؤ'),
  ('ur.ahmedali', 2, 184, 'گنتی کے چند روز پھر جو کوئی تم میں سے بیمار یا سفر پر ہو تو دوسرے دنو ں سے گنتی پوری کر لےاور ان پر جو اس کی طاقت رکھتے ہیں فدیہ ہے ایک مسکین کا کھانا پھر جو کوئی خوشی سے نیکی کرے تو وہ اس کے لیےبہتر ہے اورروزہ رکھنا تمہارے لیے بہتر ہے اگرتم جانتے ہو'),
  ('ur.ahmedali', 2, 185, 'رمضان کا وہ مہینہ ہے جس میں قرآن اتارا گیا جو لوگوں کے واسطے ہدایت ہے اور ہدایت کی روشن دلیلیں اور حق و باطل میں فرق کرنے والا ہے سو جو کوئی تم میں سے اس مہینے کو پالے تو اس کے روزے رکھے اور جو کوئی بیمار یا سفر پر ہو تو دوسرے دنو ں سے گنتی پوری کر ے اللہ تم پر آسانی چاہتا ہے اور تم پر تنگی نہیں چاہتا اور تاکہ تم گنتی پوری کر لو اور تاکہ تم الله کی بڑائی بیان کرو اس پر کہ اس نے تمہیں ہدایت دی اور تاکہ تم شکر کرو'),
  ('ur.ahmedali', 2, 186, 'اور جب آپ سےمیرے بندے میرے متعلق سوال کریں تو میں نزدیک ہوں دعاا کرنے والے کی دعا قبول کرتا ہوں جب وہ مجھے پکارتا ہے پھر چاہیئے کہ میرا حکم مانیں اور مجھ پر ایمان لائیں تاکہ وہ ہدایت پائیں'),
  ('ur.ahmedali', 2, 187, 'تمہارے لیے روزوں کی راتو ں میں اپنی عورتوں سے مباثرت کرنا حلال کیا گیا ہے وہ تمہارے لیے پردہ ہیں اورتم ان کے لیے پردہ ہو الله کو معلوم ہے تم اپنے نفسوں سے خیانت کرتے تھے پس تمہاری توبہ قبول کر لی اور تمہیں معاف کر دیا سو اب ان سے مباثرت کرو اور طلب کرو وہ چیز جو الله نے تمہارے لیے لکھدی ہے اور کھاؤ اور پیو جب تک کہ تمہارے لیے سفید دھاری سیادہ دھاری سے فجر کے وقت صاف ظاہر ہو جاوے پھر روزوں کو رات پورا کرو اور ان سے مباثرت نہ کرو جب کہ تم مسجدوں میں معتکف ہو یہ الله کی حدیں ہیں سو ان کے قریب نہ جاؤ اسی طرح الله اپنی آیتیں لوگوں کے لیے بیان کرتا ہے تاکہ وہ پرہیز گار ہو جائیں'),
  ('ur.ahmedali', 2, 188, 'اور ایک دوسرے کے مال آپس میں ناجائز طور پر نہ کھاؤ اور انہیں حاکموں تک نہ پہنچاؤ تاکہ لوگوں کے مال کا کچھ حصہ گناہ سے کھا جاؤ حالانکہ تم جانتے ہو'),
  ('ur.ahmedali', 2, 189, 'آپ سے چاندوں کے متعلق پوچھتے ہیں کہہ دو یہ لوگوں کے لیے اور حج کے لیے وقت کے اندازے ہیں اور نیکی یہ نہیں ہے کہ تم گھروں میں ان کی پشت کی طرف سے آؤ اور لیکن نیکی یہ ہے کہ جو کوئی الله سے ڈرے اور تم گھروں میں ان کے دروازوں سے آؤ اور الله سے ڈرتے رہو تاکہ تم کامیاب ہو جاؤ'),
  ('ur.ahmedali', 2, 190, 'اور الله کی راہ میں ان سے لڑو جوتم سے لڑیں اور زیادتی نہ کرو بے شک الله زیادتی کرنے والوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 2, 191, 'اور انہیں قتل کرو جہاں پاؤ اور انہیں نکال دو جہاں سے انہوں نےتمہیں نکالا ہے اور غلبہ شرک قتل سے زیادہ سخت ہے اور مسجد حرام کے پاس ان سے نہ لڑو جب تک کہ وہ تم سے یہاں نہ لڑیں پھراگروہ تم سےلڑیں تم بھی انہیں قتل کرو کافروں کی یہی سزا ہے'),
  ('ur.ahmedali', 2, 192, 'پھر اگر وہ باز آجائیں تو الله بڑا بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 193, 'اور ان سے لڑو یہاں تک کہ فساد باقی نہ رہے اور الله کا دین قائم ہو جائے پھر اگر وہ باز آجائیں تو سوائے ظالموں کے کسی پر سختی جائز نہیں'),
  ('ur.ahmedali', 2, 194, 'حرمت واے مہینے کا بدلہ حرمت والا مہینہ ہے اور سب قابلِ تعظیم باتوں کا بدلہ ہے پھر جو تم پر زیادتی کرےتم بھی اس پر زیادتی کرو جیسی کہ اس نے تم پر زیادتی کی اور الله سے ڈرو اور جان لو کہ الله پرہیزگاروں کے ساتھ ہے'),
  ('ur.ahmedali', 2, 195, 'اورالله کی راہ میں خرچ کرو اور اپنے آپ کوپنے ہاتھوں ہلاکت میں نہ ڈالو او رنیکی کرو بے شک الله نیکی کرنے والوں کو دوست رکھتا ہے'),
  ('ur.ahmedali', 2, 196, 'اور الله کے لیے حج اور عمرہ پورا کرو پس اگر روکے جاؤ تو جو قربانی سے میسر ہو اور اپنے سر نہ منڈواؤ جب تک کہ قربانی اپنی جگہ پر نہ پہنچ جائے پھر جو کوئی تم میں سے بیمار ہو یا اسے سر میں تکلیف ہو تو روزوں سے یا صدقہ سے یا قربانی سے فدیہ دے پھر جب تم امن میں ہو تو عمرہ سے حج تک فائدہ اٹھائے تو قربانی سے جو میسر ہو (دے) پھر جو نہ پائے تو تین روزے حج کے دنوں میں رکھےاور سات جب تم لوٹو یہ دس پورے ہو گئے یہ ا س کے لیے ہے جس کا گھر بار مکہ میں نہ ہو اور الله سے ڈرتے رہو اور جان لو کہ الله سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 2, 197, 'حج کے چند مہینے معلوم ہیں سو جو کوئي ان میں حج کا قصد کرے تو مباثرت جائز نہیں اور نہ گناہ کرنا اور نہ حج میں لڑائي جھگڑا کرنا اور تم جو نیکی کرتے ہو الله اس کو جانتا ہے اور زادِ راہ لے لیا کرو اور بہترین زادِ راہ پرہیزگاری ہے اور اے عقلمندوں مجھ سے ڈرو'),
  ('ur.ahmedali', 2, 198, 'تم پر کوئی گناہ نہیں ہے کہ اپنے رب کا فضل تلاش کرو پھر جب تم عرفات سے پھرو تو مشعر الحرام کے پاس الله کو یاد کرو اور اس کی یاد اس طرح کرو کہ جس طرح اس نے تمیں بتائی ہے اور اس سے پہلے تو تم گمراہوں میں سے تھے'),
  ('ur.ahmedali', 2, 199, 'پھر تم لوٹ کر آؤ جہاں سے لوٹ کر آتے ہیں اور الله سے بخشش مانگو بے شک الله بڑا بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 200, 'پھر جب حج کے ارکان ادا کر چکو تو الله کو یاد کرو جیسے تم اپنے باپ دادا کو یاد کیا کرتے تھے یا اس سے بھی بڑھ کر یاد کرنا پھر بعض تو یہ کہتے ہیں اےہمارے رب ہمیں دنیا میں دے اور اس کے لیے آخرت میں کوئی حصہ نہیں ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 2, 201, 'اوربعض یہ کہتے ہیں کہ اے ہمارے رب ہمیں دنیا میں نیکی اور آخرت میں بھی نیکی دے اور ہمیں دوزخ کے عذاب سے بچا'),
  ('ur.ahmedali', 2, 202, 'یہی وہ لوگ ہیں جنہیں ان کی کمائی کا حصہ ملتا ہے اور الله جلد حساب لینے والا ہے'),
  ('ur.ahmedali', 2, 203, 'اور الله کو چند گنتی کے دنوں میں یاد کرو پھر جس نے دو دن کے اندر کوچ کرنے میں جلدی کی تو اس پر کوئی گناہ نہیں اور جو تاخیر کرے تو اس پر بھی کوئی گناہ نہیں جو (الله سے) ڈرتا ہے اور الله سے ڈرو اور جان لو کہ تم اسی کی طرف جمع کیے جاؤ گے'),
  ('ur.ahmedali', 2, 204, 'اور بعض ایسے بھی ہیں جن کی بات دنیا کی زندگی میں آپ کو بھلی معلوم ہوتی ہے اور وہ اپنی دل کی باتوں پر الله کو گواہ کرتا ہے حالانکہ وہ سخت جھگڑالو ہے'),
  ('ur.ahmedali', 2, 205, 'اور جب پیٹھ پھیر کر جاتا ہے تو ملک میں فساد ڈالتا اور کھیتی اور مویشی کو برباد کرنے کی کوشش کرتا ہے اور الله فساد کو پسندنہیں کرتا'),
  ('ur.ahmedali', 2, 206, 'اور جب اسسے کہا جاتا ہے کہ الله سے ڈر تو شیخی میں آ کر اور بھی گناہ کرتا ہے سو اس کے لیے دوزخ کافی ہے اور البتہ وہ برا ٹھکانہ ہے'),
  ('ur.ahmedali', 2, 207, 'اوربعض ایسے بھی ہیں جو الله کی رضا جوئی کے لیے اپنی جان بھی بیچ دیتے ہیں اور الله کے بندوں پر بڑا مہربان ہے'),
  ('ur.ahmedali', 2, 208, 'اے ایمان والو اسلام میں سارے کے سارے داخل ہو جاؤ اور شیطان کے قدموں کی پیروی نہ کرو کیوں کہ وہ تمہارا صریح دشمن ہے'),
  ('ur.ahmedali', 2, 209, 'پھر اگر تم کھلی کھلی نشانیاں آجانے کے بعد بھی پھسل گئے تو جان لو کہ الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 2, 210, 'کیا وہ انتظار کرتے ہیں کہ الله ان کے سامنے بادلوں کے سایہ میں آ موجود ہو اور فرشتے بھی آجائیں اور کام پورا ہو جائے اور سب باتیں الله ہی کے اختیار میں ہیں'),
  ('ur.ahmedali', 2, 211, 'بنی اسرائیل سے پوچھیئے کہ ہم نے انہیں کتنی روشن دلیلیں دیں اور جو الله کی نعمت کو بدل دیتا ہے بعد اس کے کہ وہ اس کے پاس آ چکی ہو تو بے شک الله سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 2, 212, 'کافروں کو دنیا کی زندگی بھلی لگتی ہے اور وہ ان لوگوں کا مذاق اڑاتے ہیں جو ایمان لائے حالانکہ جولوگ پرہیزگار ہیں وہ قیامت کے دن ان سے بالاتر ہوں گے اور الله جسے چاہے بے حساب رزق دیتا ہے'),
  ('ur.ahmedali', 2, 213, 'سب لوگ ایک دین پر تھے پھر الله نے انبیاء خوشخبری دینے والے اور ڈرانے والے بھیجے اور ان کے ساتھ سچی کتابیں نازل کیں تاکہ لوگوں میں اس بات میں فیصلہ کرے جس میں اختلاف کرتے تھےاور اس میں اختلاف نہیں کیا مگر انہیں لوگوں نے جنھیں وہ (کتاب) دی گئی تھی اس کے بعد کہ ا ن کے پاس روشن دلیلیں آ چکی تھیں آپس کی ضد کی وجہ سے پھر الله نے اپنے حکم سے ہدایت کی ان کو جو ایمان والے ہیں اس حق بات کی جس میں وہ اختلاف کر رہے تھے اور الله جسے چاہے سیدھے راستے کی ہدایت کرتا ہے'),
  ('ur.ahmedali', 2, 214, 'کیا تم خیال کرتے ہو کہ جنت میں داخل ہو جاؤ گے حالانکہ تمہیں وہ (حالات) پیش نہیں آئے جو ان لوگو ں کو پیش آئے جو تم سے پہلے ہو گزرے ہیں انہیں سختی اور تکلیف پہنچی اور ہلا دیئے گئے یہاں تک کہ رسول اور جو اس کے ساتھ ایمان لائے تھے بول اٹھے کہ الله کی مدد کب ہوگی سنو بے شک الله کی مدد قریب ہے'),
  ('ur.ahmedali', 2, 215, 'آپ سے پوچھتے ہیں کیا خرچ کریں کہہ دو جو مال بھی تم خرچ کرو وہ ماں باپ اور رشتہ داروں اور یتیموں اور محتاجوں اور مسافروں کا حق ہے اور جو نیکی تم کرتے ہو سو بے شک الله خوب جانتا ہے'),
  ('ur.ahmedali', 2, 216, 'تم پر جہاد فرض کیا گیا ہے اور وہ تمہیں ناگوار ہے اور ممکن ہے تم کسی چیز کو ناگوار سمجھو اور وہ تمہارے لیے بہتر ہو اور ممکن ہے کہ تم کسی چیز کو پسند کرو اور وہ تمہارے لیے مضر ہو اور الله ہی جانتا ہے اور تم نہیں جانتے'),
  ('ur.ahmedali', 2, 217, 'آپ سے حرمت والے مہینے میں لڑائی کے متعلق پوچھتے ہیں کہہ دو اس میں لڑنا بڑا (گناہ) ہے اور الله کے راستہ سے روکنا اور اس کا انکار کرنا اور مسجد حرام سے روکنا اور اس کے رہنے والوں کو اس میں سے نکالنا الله کے نزدیک اس سے بڑا گناہ ہے اور فتنہ انگیزی تو قتل سے بھی بڑا جرم ہے اور وہ تم سے ہمیشہ لڑتے رہیں گے یہاں تک کہ تمہیں تمہارے دین سے پھیر دیں اگر ان کا بس چلےاور جو تم میں سے اپنے دین سے پھر جائے پھر کافر ہی مرجائے پس یہی وہ لوگ ہیں کہ ان کے عمل دنیا اور آخرت میں ضائع ہو گئے اور وہی دوزخی ہیں جو اسی میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 2, 218, 'بے شک جو لوگ ایمان لائے اور جنہوں نے ہجرت کی اور الله کی راہ میں جہاد کیا وہی الله کی رحمت کے امیدوار ہیں اور الله بڑا بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 219, 'آپ سے شراب اور جوئے کے متعلق پوچھتے ہیں کہہ دو ان میں بڑا گنا ہے اور لوگوں کے لیے کچھ فائدے بھی ہیں اور ان کا گناہ ان کے نفع سے بہت بڑا ہے اور آپ سے پوچھتے ہیں کہ کیا خرچ کریں کہہ دو جو زاید ہو ایسے ہی الله تمہارے لیے آیتیں کھول کر بیان کرتا ہے تاکہ تم غور کرو'),
  ('ur.ahmedali', 2, 220, 'دنیا اور آخرت کے بارے میں اور یتیموں کے متعلق آپ سے پوچھتے ہیں کہہ دو ان کی اصلاح کرنا بہتر ہے اور اگر تم انہیں ملا لو تو وہ تمہارے بھائی ہیں اور الله بگاڑنے والے کو اصلاح کرنےوالے سے جانتا ہے اور اگر الله چاہتا تو تمہیں تکلیف میں ڈالتا بے شک الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 2, 221, 'اور مشرک عورتیں جب تک ایمان نہ لائیں ان سے نکاح نہ کرو اورمشرک عورتوں سے ایمان دار لونڈی بہتر ہے گو وہ تمہیں بھلی معلوم ہو اور مشرک مردوں سے نکاح نہ کرو یہاں تک کہ وہ ایمان لائیں اور البتہ مومن غلام مشرک سے بہتر ہے اگرچہ وہ تمہیں اچھا ہی لگے یہ لوگ دوزخ کی طرف بلاتے ہیں اور الله جنت اور بخشش کی طرف اپنے حکم سے بلاتا ہے اور لوگوں کے لیے اپنی آیتیں کھول کر بیان کرتا ہے تاکہ وہ نصیحت حاصل کریں'),
  ('ur.ahmedali', 2, 222, 'اور آپ سے حیض کے بارے میں پوچھتے ہیں کہہ دو وہ نجاست ہے پس حیض میں عورتوں سے علیحدٰہ رہو اور ان کے پاس نہ جاؤ یہاں تک کہ وہ پاک ہو لیں پھر جب وہ پاک ہو جائیں تو ان کے پاس جاؤ جہاں سے اللہ نےتمہیں حکم دیا ہے بے شک الله توبہ کرنے والوں کو دوست رکھتا ہے اوربہت پاک رہنے والوں کو دوست رکھتا ہے'),
  ('ur.ahmedali', 2, 223, 'تمہاری بیویاں تمہاری کھیتیاں ہیں پس تم اپنی کھیتیوں میں جیسے چاہو آؤ اور اپنے لیے آئندہ کی بھی تیاری کرو اور الله سے ڈرتے رہو اور جان لو کہ تم ضرور اسے ملو گے اور ایمان والوں کو خوشخبری سنا دو'),
  ('ur.ahmedali', 2, 224, 'اور الله کو اپنی قسموں کا نشانہ نہ بناؤ نیکی اور پرہیز گاری اور لوگو ں کے درمیان اصلاح کرنے سے اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 225, 'الله تمہیں تمہاری قسموں میں بے ہودہ گوئی پر نہیں پکڑتا لیکن تم سے ان قسموں پر مواخذہ کرتا ہے جن کا تمہارے دلوں نے ارادہ کیا ہو اور الله بڑا بحشنے والا بردبار ہے'),
  ('ur.ahmedali', 2, 226, 'جو لوگ اپنی بیویوں کے پاس جانے سے قسم کھا لیتے ہیں ان کے لیے چار مہینے کی مہلت ہے پھر اگر وہ رجوع کر لیں تو الله بڑا بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 2, 227, 'اور اگر انہوں نے طلاق کا پختہ ارداہ کر لیا تو بے شک الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 228, 'اور طلاق دی ہوئی عورتیں تین حیض تک اپنے آپ کو روکے رکھیں اور ان کے لیے جائز نہیں کہ چھپائیں جو الله نے ان کے پیٹوں میں پیدا کیاہے اگر وہ الله اور قیامت کے دن پر ایمان رکھتی ہیں اوران کے خاوند اس مدت میں ان کو لوٹالینے کے زیادہ حق دار ہیں اگر وہ اصلاح کا اردہ رکھتے ہیں اور دستور کے مطابق ان کا ویسا ہی حق ہےجیسا ان پر ہے اور مردوں کو ان پر فضیلت دی ہے اور الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 2, 229, 'طلاق دو مرتبہ ہے پھر بھلائی کے ساتھ روک لینا ہے یا نیکی کے ساتھ چھوڑ دنیا ہے اور تمہارے یے اس میں سے کچھ بھی لینا جائز نہیں جو تم نے انہیں دیا ہے مگر یہ کہ دونوں ڈریں کہ الله کی حدیں قائم نہیں رکھ سکیں گے پھر اگرتمہیں خوف ہو کہ دونوں الله کی حدیں قائم نہیں رکھ سکیں گے تو ان دونوں پر اس میں کوئی گناہ نہیں کہ عورت معاوضہ دے کر پیچھا چھڑالے یہ الله کی حدیں ہیں سو ان سے تجاوز نہ کرو اورجو الله کی حدوں سے تجاوز کرے گا سو وہی ظالم ہیں'),
  ('ur.ahmedali', 2, 230, 'پھر اگر اسے طلاق دے دی تو اس کے بعد اس کے لیے وہ حلال نہ ہوگی یہاں تک کہ وہ کسی اور خاوند سے نکاح کرے پھر اگر وہ اسے طلاق دے دے تو ان دونوں پر کوئی گناہ نہیں کہ آپس میں رجوع کر لیں اگر ان کا گمان غالب ہو کہ وہ الله کی حدیں قائم سکیں گے اور یہ الله کی حدیں ہیں وہ انہیں کھول کر بیان کرتا ہے ان لوگوں کے لیے جو علم رکھتے ہیں'),
  ('ur.ahmedali', 2, 231, 'اور جب عورتوں کو طلاق دے دوپھر وہ اپنی عدت کو پہنچ جائیں تو انہیں حسن سلوک سے روک لو یا انہیں دستور کے مطابق چھوڑ دو اور انہیں تکلیف دینے کے یے نہ روکو تاکہ تم سختی کرو اور جو ایسا کرے گا تو وہ اپنے اوپر ظلم کرے گا اور الله کی آیتوں کا تمسخر نہ اڑاؤ اورالله کے احسان کو یاد کرو جو اس نے تم پر کیا ہے اور جو اس نے تم پر کتاب اور حکمت اتاری ہے کہ تمہیں اس سے نصیحت کرے اور الله سے ڈرو اور جان لو کہ الله ہر چیز کو خوب جاننے والا ہے'),
  ('ur.ahmedali', 2, 232, 'اورجب تم عورتوں کو طلاق دے دو پس وہ اپنی عدت تمام کر چکیں تو اب انہیں اپنے خاوندوں سے نکاح کرنے سے نہ روکو جب کہ وہ آپس میں دستور کے مطابق راضی ہو جائیں تم میں سے یہ نصیحت اسے کی جاتی ہے جو الله اور قیامت کے دن پر ایمان رکھتا ہے یہ تمہارے لیے بڑی پاکیزی اوربڑی صفائی کی بات ہے اور الله ہی جانتا ہے اور تم نہیں جانتے'),
  ('ur.ahmedali', 2, 233, 'اور مائیں اپنے بچوں کو پورے دو برس دودھ پلائیں یہ اس کے لیے ہے جو دودھ کی مدت کو پورا کرنا چاہے اور باپ پر دودھ پلانے والیوں کا کھانا اور کپڑا دستور کے مطابق ہے کسی کو تکلیف نے دی جائے مگر اسی قدر کہ اس کی طاقت ہو نہ ماں کو اس کے بچہ کی وجہ سے تکلیف دی جائے اور نہ باپ ہی کو اس کی اولاد کی وجہ سے اور وارث پر بھی ویسا ہی نان نفقہ ہے پھر اگر دونوں اپنی رضا مندی اور مشورہ سے دودھ چھڑانا چاہیں تو ان پر کوئی گناہ نہیں ہے اور اگر کسی اور سے اپنی اولاد کو دودھ پلوانا چاہو تو اس میں بھی تم پر کوئی گناہ نہیں بشرطیکہ تم دے دو جو دستور کے مطابق تم نے دینا ٹھرایا ہے اور الله سے ڈرو اور جان لو کہ الله اسے جو تم کرتے ہو خوب دیکھتا ہے'),
  ('ur.ahmedali', 2, 234, 'اور جو تم میں سے مر جائیں اور بیویاں چھوڑ جائيں تو ان بیویوں کو چار مہینے دس دن تک اپنے نفس کو روکنا چاہیئے پھر جب وہ اپنی مدت پوری کر لیں تو تم پر اس میں کوئی گناہ نہیں جو وہ دستور کے مطابق اپنے حق میں کریں اور الله اس سے جو تم کرتے ہو خبردار ہے'),
  ('ur.ahmedali', 2, 235, 'اورتم پر اس میں گناہ نہیں ہے کہ ان عورتوں کو اشارہ سے پیغام نکاح دو اور یا تم اسے اپنے دل میں چھپاؤ الله جانتاہے کہ تمہیں ان عورتوں کا خیال پیدا ہو گا لیکن مخفی طور پر ان سے نکاح کا وعدہ نہ کرو مگر یہ کہ قاعدہ کے مطابق کوئی بات کہو اورجب تک معیاد نوشتہ پوری نہ ہو اس وقت تک نکاح کا قصد بھی نہ کرو اور جان لو کہ الله جانتا ہے جو کچھ تمہارے دلو ں میں ہے پس اس سے ڈرتے رہو اور جان لو الله بڑا بخشنے والا بردبار ہے'),
  ('ur.ahmedali', 2, 236, 'تم پر کوئی گناہ نہیں اگر تم عورتوں کو طلاق دے دو جب کہ انہیں ہاتھ بھی نہ لگایا ہو اور ان کے لیے کچھ مہر بھی مقرر نہ کیا ہو اور انہیں کچھ سامان دے دو وسعت والے پر اپنے قدر کے مطابق اور مفلس پر اپنے قدر کے مطابق سامان حسب دستور ہے نیکو کاروں پر یہ حق ہے'),
  ('ur.ahmedali', 2, 237, 'اور اگر تمہیں انہیں طلاق دو اس سے پہلےکہ انہیں ہاتھ لگاؤ حالانکہ تم ان کے لیے مہر مقرر کر چکے ہو تو نصف اس کا جو تم نے مقرر کیا تھا مگر یہ کہ وہ معاف کر دیں یا وہ شخص معاف کر دے جس کے ہاتھ میں نکاح کی گرہ ہے اور تمہارا معاف کر دینا پرہیزگاری کے زیادہ قریب ہے اور آپس میں احسان کرنا نہ بھولو کیوں کہ جو کچھ بھی تم کر رہے ہو الله اسے دیکھ رہا ہے'),
  ('ur.ahmedali', 2, 238, 'سب نمازوں کی حفاظت کیا کرو اور (خاص کر) درمیانی نماز کی اور الله کے لیے ادب سے کھڑے رہا کرو'),
  ('ur.ahmedali', 2, 239, 'پھر اگر تمہیں خوف ہو تو پیادہ یا سوار ہی (پڑھ لیا کرو) پھر جب امن پاؤ تو الله کو یادکیا کرو جیسا اس نے تمہیں سکھایا ہے جو تم نہ جانتے تھے'),
  ('ur.ahmedali', 2, 240, 'اور جو لوگ تم میں سے مر جائیں اوربیویاں چھوڑ جائیں تو انہیں اپنی بیویوں کے لیے سال بھر کے لیے گزارہ کے واسطے وصیت کرنی چاہیئے گھر سے باہر گئے بغیر پھر اگر وہ خود نکل جائیں توتم پر اس میں کوئي گناہ نہیں جو وہ عورتیں اپنے حق میں دستور کے موافق کریں اور الله زبردست حکمت والا ہے'),
  ('ur.ahmedali', 2, 241, 'اور طلاق دی ہوئی عورتوں کے واسطے دستور کے موافق خرچ دینا پرہیزگارو ں پر یہ لازم ہے'),
  ('ur.ahmedali', 2, 242, 'اسی طرح الله تمہارے واسطے اپنے احکام بیان فرماتا ہے تاکہ تم سمجھ لو'),
  ('ur.ahmedali', 2, 243, 'کیا تم نے ان لوگو ں کو نہیں دیکھا جو موت کے ڈر سے اپنے گھروں سے نکلے حالانکہ وہ ہزاروں تھے پھر الله نےان کو فرمایا کہ مرجاؤ پھر انہیں زندہ کر دیا بے شک الله لوگوں پر فضل کرنے والا ہے لیکن اکثر لوگ شکر نہیں کرتے'),
  ('ur.ahmedali', 2, 244, 'اور الله کی راہ میں لڑو اور سمجھ لو کہ بے شک الله خوب سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 245, 'ایسا کون شخص ہے جو الله کو اچھا قرض دے پھر الله اس کو کئی گناہ بڑھا کردے اور الله ہی تنگی کرتا ہے اور کشائش کرتا ہے اورتم سب اسی کی طرف لوٹائے جاؤ گے'),
  ('ur.ahmedali', 2, 246, 'کیاتم نے بنی اسرائیل کی ایک جماعت کو موسیٰ کے بعد نہیں دیکھا جب انہوں نے اپنے نبی سے کہا کہ ہمارے لیے ایک بادشاہ مقرر کر دو تاکہ ہم الله کی راہ میں لڑیں پیغمبر نے کہاکیا یہ بھی ممکن ہے اگر تمہیں لڑائی کا حکم ہو تو تم اس وقت نہ لڑو انہوں نے کہا ہم الله کی راہ میں کیوں نہیں لڑیں گے حالانکہ ہمیں اپنے گھروں اور اپنےبیٹوں سے نکال دیا گیا ہے پھر جب انہیں لڑائی کا حکم ہوا تو سوائے چند آدمیوں کے سب پھر گئے اور الله ظالموں کو خوب جانتا ہے'),
  ('ur.ahmedali', 2, 247, 'ان کے نبی نے ان سے کہا بے شک الله نے طالوت کو تمہارا بادشاہ مقرر فرمایا ہے انہوں نے کہا اس کی حکومت ہم پر کیوں کر ہو سکتی ہے اس سے تو ہم ہی سلطنت کے زیادہ مستحق ہیں اور اسے مال میں بھی کشائش نہیں دی گئی پیغمبر نے کہا بے شک الله نے اسے تم پر پسند فرمایا ہے اور اسے علم اور جسم میں زیادہ فراخ دی ہے اور الله اپنا ملک جسے چاہے دیتا ہے اور الله کشائش والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 248, 'اوربنی اسرائیل سے ان کے نبی نے کہاکہ طالوت کی بادشاہی کی یہ نشانی ہے کہ تمہارے پاس وہ صندوق واپس آئے گا جس میں تمہارے رب کی طرف سے اطمینان ہے اور کچھ بچی ہوئی چیزیں ہیں ان میں سے جو موسیٰ اور ہارون کی اولاد چھوڑ گئی تھی اس صندوق کو فرشتے اٹھا لائیں گے بے شک اس میں تمہارے لیے پوری نشانی ہے اگرتم ایمان والے ہو'),
  ('ur.ahmedali', 2, 249, 'پھر جب طالوت فوجیں لے کر نکلا کہا بے شک الله ایک نہر سے تمہاری آزمائش کرنے والا ہے جس نے اس نہر کا پانی پیا تو وہ میرا نہیں ہے اور جس نے اسے نہ چکھا تو وہ بےشک میرا ہے مگر جو کوئی اپنے ہاتھ سے ایک چلو بھر لے (تو اسے معاف ہے) پھر ان میں سے سوائے چند آدمیوں کے سب نے اس کا پانی پی لیا پھر جب طالوت اور ایمان والے ا س کے ساتھ پار ہوئے تو کہنے لگے آج ہمیں جالوت اور اس کے لشکروں سے لڑنے کی طاقت نہیں جن لوگو ں کو خیال تھا کہ انہیں الله سے ملنا ہے وہ کہنے لگے بار ہا بڑی جماعت پر چھوٹی جماعت الله کے حکم سے غالب ہوئی ہے اور الله صبر کرنے والو ں کے ساتھ ہے'),
  ('ur.ahmedali', 2, 250, 'اورجب جالوت اور اس کی فوجوں کے سامنے ہوئے تو کہا اے رب ہمارے دلوں میں صبر ڈال دے اور ہمارے پاؤں جمائے رکھ اور اس کافر قوم پر ہماری مدد کر'),
  ('ur.ahmedali', 2, 251, 'پھر الله کے حکم سے مومنو ں نے جالوت کے لشکروں کو شکست دی اور داؤد نے جالوت کو مار ڈالا اور الله نے سلطنت اور حکمت داؤد کو دی اور جو چاہا اسے سکھایا اور اگر الله کابعض کو بعض کے ذریعے سے دفع کرا دینا نہ ہوتا تو زمین فساد سے پُر ہو جاتی لیکن الله جہان والوں پر بہت مہربان ہے'),
  ('ur.ahmedali', 2, 252, 'یہ الله کی آیتیں ہیں ہم تمہیں ٹھیک طور پر پڑھ کر سناتے ہیں اوربے شک تو ہمارے رسولوں میں سے ہے'),
  ('ur.ahmedali', 2, 253, 'یہ سب رسول ہیں ہم نے ان میں سے بعض کو بعض پر فضیلت دی ہے بعض وہ ہیں جن سے الله نے کلام فرمائی اور بعضوں کے درجے بلند کیے اور ہم نے عیسیٰ مریم کے بیٹے کو صریح معجزے دیے تھے اور اسے روح القدس کے ساتھ قوت دی تھی اور اگر الله چاہتا تو وہ لوگ جو ان پیغمبروں کے بعد آئے وہ آپس میں نہ لڑتے بعد اس کے کہ ان کے پاس صاف حکم پہنچ چکے تھے لیکن ان میں اختلاف پیدا ہو گیا پھر کوئی ان میں سے ایمان لایا اور کوئی کافر ہوا اور اگر الله چاہتا تو وہ آپس میں نہ لڑتے لیکن الله جو چاہتا ہے کرتا ہے'),
  ('ur.ahmedali', 2, 254, 'اے ایمان والو! جو ہم نے تمہیں رزق دیا ہے اس میں سے خرچ کرو اس دن کے آنے سے پہلے جس میں نہ کوئی خرید و فروخت ہو گی اور نہ کوئی دوستی اور نہ کوئی سفارش اور کافر وہی ظالم ہیں'),
  ('ur.ahmedali', 2, 255, 'الله کے سوا کوئی معبود نہیں زندہ ہےسب کا تھامنے والا نہ اس کی اونگھ دبا سکتی ہے نہ نیند آسمانوں اور زمین میں جو کچھ بھی ہے سب اسی کا ہے ایسا کون ہے جو اس کی اجازت کے سوا اس کے ہاں سفارش کر سکے مخلوقات کے تمام حاضر اور غائب حالات کو جانتا ہے اور وہ سب اس کی معلومات میں سےکسی چیز کا احاطہ نہیں کر سکتے مگر جتنا کہ وہ چاہے اس کی کرسی نے سب آسمانوں اور زمین کو اپنے اندر لے رکھا ہے اور الله کو ان دونوں کی حفاظت کچھ گراں نہیں گزرتی اور وہی سب سےبرتر عظمت والا ہے'),
  ('ur.ahmedali', 2, 256, 'دین کے معاملے میں زبردستی نہیں ہے بے شک ہدایت یقیناً گمراہی سے ممتاز ہو چکی ہے پھر جو شخص شیطان کو نہ مانے اور الله پر ایمان لائے تو اس نے مضبوط حلقہ پکڑ لیاجو ٹوٹنے والا نہیں اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 2, 257, 'الله ایمان والوں کا مددگار ہے اور انہیں اندھیروں سے روشنی کی طرف نکالتا ہے اور جو لوگ کافر ہیں ان کے دوست شیطان ہیں انہیں روشنی سے اندھیروں کی طرف نکالتے ہیں یہی لوگ دوزخ میں رہنے والے ہیں وہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 2, 258, 'کیا تو نے اس شخص کو نہیں دیکھا جس نے ابراھیم سے اس کے رب کی بابت جھگڑا کیا اس لیے کہ الله نے اسے سلطنت دی تھی جب ابراھیم نے کہا کہ میرا رب وہ ہے جو زندہ کرتا ہے اور مارتا ہے اس نے کہا میں بھی زندہ کرتا ہوں اور مارتا ہوں کہا ابراھیم نے بے شک الله سورج مشرق سے لاتا ہے تو اسے مغرب سے لے آ تب وہ کافر حیران رہ گیا اور الله بے انصافوں کی سیدھی راہ نہیں دکھاتا'),
  ('ur.ahmedali', 2, 259, 'یا تو نے اس شخص کو نہیں دیکھا جو ایک شہر پر گزرا اور وہ اپنی چھتوں پر گرا ہوا تھاکہا اسے الله مرنے کے بعد کیوں کر زندہ کرے گا پھر الله نے اسے سو برس تک مار ڈالا پھر اسے اٹھایا کہا تو یہاں کتنی دیر رہا کہا ایک دن یا اس سے کچھ کم رہا فرمایا بلکہ تو سو برس رہا ہے اب تو اپنا کھانا اور پینا دیکھ وہ تو سڑا نہیں اور اپنے گدھے کو دیکھ اور ہم نے تجھے لوگوں کے واسطے نمونہ چاہا ہے اور ہڈیوں کیطرف دیکھ کہ ہم انہیں کس طرح ابھار کر جوڑدیتے ہیں پھر ان پر گوشت پہناتے ہیں پھر اس پر یہ حال ظاہر ہوا تو کہا میں یقین کرتا ہو ں کہ بے شک الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 2, 260, 'اور یاد کر جب ابراھیم نے کہا اے میرے پروردگار! مجھ کو دکھا کہ تو مردے کو کس طرح زندہ کرے گا فرمایا کہ کیا تم یقین نہیں لاتے کہا کیوں نہیں لیکن اس واسطے چاہتاہوں کہ میرے دل کو تسکین ہو جائے فرمایا تو چار جانور اڑنے والے پکڑے پھر انہیں اپنے ساتھ ہلا لے پھر ہر پہاڑ پر ان کے بدن کا ایک ایک ٹکڑا رکھ دے پھر ان کو بلا تیرے پاس دوڑتے ہوئے آئیں گے اور جان لے کہ بے شک الله زبردست حکمت والا ہے'),
  ('ur.ahmedali', 2, 261, 'ان لوگوں کی مثال جو الله کی راہ میں مال خرچ کرتے ہیں ایسی ہے کہ جیسے ایک دانہ کہ اگائے سات بالیں ہر بال میں سو سو دانے اور الله جس کے واسطے چاہے بڑھاتا ہے اور الله بڑی وسعت جاننے والا ہے'),
  ('ur.ahmedali', 2, 262, 'جو لوگ اپنے مال الله کی راہ میں خرچ کرتے ہیں پھر خرچ کرنے کے بعد نہ احسان رکھتے ہیں اور نہ ستاتے ہیں انہیں کے لیے اپنے رب کے ہاں ثواب ہے اوران پر نہ کوئی ڈر ہے اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 2, 263, 'مناسب بات کہہ دینا اور درگزر کرنا اس خیرات سے بہتر ہے جس کے بعد ستانا ہو اور الله بے پرواا نہایت تحمل والا ہے'),
  ('ur.ahmedali', 2, 264, 'اے ایمان والو! احسان رکھ کر اور ایذا دے کے اپنی خیرات کو ضائع نہ کرو اس شخص کی طرح جو اپنا مال لوگوں کے دکھانے کو خرچ کرتا ہے اور الله پر اور قیامت کے دن پر یقین نہیں رکھتا سو اس کی مثال ایسی ہے جیسے صاف پتھر کہ اس پر کچھ مٹی پڑی ہو پھر اس پر زور کا مینہ برساپھر اسی کو بالکل صاف کر دیا ایسے لوگوں کو اپنی کمائی ذرا ہاتھ بھی نہ لگے گی اور الله کافروں کو سیدھی راہ نہیں دکھاتا'),
  ('ur.ahmedali', 2, 265, 'اور ان لوگوں کی مثال جو اپنے مال الله کی رضا حاصل کرنے کے لیے اور اپنے دلوں کو مضبوط کر کے خرچ کرتے ہیں ایسی ہے جس طرح بلند زمین پر ایک باغ ہو اس پر زور کا مینہ برسا تو وہ باغ اپنا پھل دوگنا لایا اور اگر اس پر مینہ نہ برسایا تو شبنم ہی کافی ہے اور الله تمہارے کاموں کو خوب دیکھنے والا ہے'),
  ('ur.ahmedali', 2, 266, 'کیا تم میں کسی کو یہ بات پسند آتی ہے کہ اس کا ایک باغ کھجور اور انگور کا ہو جس کے نیچے نہریں بہتی ہوں اسے اس باغ میں اوربھی ہر طرح کا میوہ حاصل ہو اور اس پر بڑھاپا آ گیا ہو اور اس کی اولاد ضعیف ہو تب اس باغ پرایک بگولہ آ پڑا جس میں آگ تھی جس سے وہ باغ جل گیا الله تمہیں اس طرح نشانیاں سمجھاتا ہے تاکہ تم سوچا کرو'),
  ('ur.ahmedali', 2, 267, 'اے ایمان والو! اپنی کمائی میں سے ستھری چیزیں خرچ کرو اور اس چیز میں سے بھی جو ہم نے تمہارے لیے زمین سے پیدا کی ہے اور اس میں سے ردی چیز کا ارادہ نہ کرو کہ اس کو خرچ کرو حالانکہ تم اسے کبھی نہ لو مگر یہ کہ چشم پوشی کر جاؤ اور سمجھ لو کہ بے شک الله بے پرواہ تعریف کیا ہوا ہے'),
  ('ur.ahmedali', 2, 268, 'شیطان تمہیں تنگدستی کا وعدہ دیتا ہے اور بے حیائی کا حکم کرتا ہے اور الله تمہیں اپنی بخشش اور فضل کا وعدہ دیتا ہے اور الله بہت کشائش کرنے والا سب کچھ جاننے والا ہے'),
  ('ur.ahmedali', 2, 269, 'جس کو چاہتا ہے سمجھ دے دیتا ہے اور جسے سمجھ دی گئی تو اسے بڑی خوبی ملی اور نصیحت وہی قبول کرتے ہیں جو عقل والے ہیں'),
  ('ur.ahmedali', 2, 270, 'اورجو تم خیرات کے طور پر خرچ کرو گے یا تم کوئی منت مانگوگے تو بے شک الله کو سب معلوم ہے اور ظالموں کا کوئی مددگار نہیں ہے'),
  ('ur.ahmedali', 2, 271, 'اگر تم خیرات ظاہر کرکے دو تو بھی اچھی بات ہے اور اگر اسے چھپا کردو اور فقیروں کو پہنچادو تو تمہارے حق میں وہ بہتر ہے اور الله تمہارے کچھ گناہ دور کر دے گا اور الله تمہارے کاموں سے خوب خبر رکھنے والا ہے'),
  ('ur.ahmedali', 2, 272, 'انہیں راہ پر لانا تیرے ذمہ نہیں اور لیکن الله جسے چاہے راہ پر لاتا ہے اور جو مال تم خرچ کرو گے اس کا نفع تمہاری جان کے لیے ہےاور الله ہی کی رضا مندی کے لیے خرچ کرو اور جو اچھی چیز تم خرچ کرو گے اس کا پورا اجر تمہیں دیا جائے گا ااور تم پر ظلم نہیں کیا جائے گا'),
  ('ur.ahmedali', 2, 273, 'خیرات ان حاجت مندوں کے لیے ہے جو الله کی راہ میں رکےہوئے ہیں ملک میں چل پھر نہیں سکتے ناواقف ان کے سوال نہ کرنے سے انہیں مال دار سمجھتا ہے تو ان کے چہرے سے پہچان سکتا ہے لوگوں سے لپٹ کر سوال نہیں کرتے اور جو کام کی چیز تم خرچ کرو گے بے شک وہ الله کو معلوم ہے'),
  ('ur.ahmedali', 2, 274, 'جو لوگ اپنے مال الله کی راہ میں رات اوردن چھپا کر اور ظاہر خرچ کرتے ہیں تو ان کے لیےاپنے رب کے ہاں ثواب ہے ان پر نہ کوئي ڈر ہے اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 2, 275, 'جو لوگ سود کھاتے ہیں قیامت کے دن وہ نہیں اٹھیں گے مگر جس طرح کہ وہ شخص اٹھتا ہے جس کے حواس جن نے لپٹ کر کھو دیئے ہیں یہ حالت ان کی اس لیے ہوگی کہ انہوں نے کہا تھا کہ سوداگری بھی تو ایسی ہی ہے جیسےسود لینا حالانکہ الله نے سوداگری کو حلال کیا ہے اور سود کو حرام کیا ہے پھر جسے اپنے رب کی طرف سے نصیحت پہنچی اوروہ باز آ گیا تو جو پہلے لے چکا ہے وہ اسی کا رہا اور اس کا معاملہ الله کے حوالہ ہے اور جو کوئی پھر سود لے وہی لوگ دوزخ والے ہیں وہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 2, 276, 'الله سود کو مٹاتا ہے اور صدقات کو بڑھاتا ہے اور الله کسی ناشکرے گناہگار کو پسندنہیں کرتا'),
  ('ur.ahmedali', 2, 277, 'جو لوگ ایمان لائے اور نیک کام کیے اور نماز کو قائم رکھا اور زکواةٰ دیتے رہے تو ان کے رب کے ہاں ان کااجر ہے اور ان پر کوئی خوف نہ ہوگا اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 2, 278, 'اے ایمان والو! الله سے ڈرو اور جو کچھ باقی سود رہ گیا ہے اسے چھوڑ دو اگر تم ایمان والے ہو'),
  ('ur.ahmedali', 2, 279, 'اگر تم نے نہ چھوڑا تو الله اور اس کے رسول کی طرف سے تمہارےخلاف اعلان جنگ ہے اور اگرتوبہ کرلوتو اصل مال تمھارا تمہارے واسطے ہے نہ تم کسی پر ظلم کرو اور نہ تم پر ظلم کیا جائے گا'),
  ('ur.ahmedali', 2, 280, 'اور اگر وہ تنگ دست ہے تو آسودہ حالی تک مہلت دینی چاہیئے اور بخش دو تو تمہارے لیے بہت ہی بہتر ہے اگر تم جانتے ہو'),
  ('ur.ahmedali', 2, 281, 'اور اس دن سے ڈرو جس دن الله کی طرف لوٹائے جاؤ گے پھر پھر ہر شخص کو اس کی کمائی کا پورا پورا بدلہ دے دیا جائے گا اور ان پر ظلم نہ ہوگا'),
  ('ur.ahmedali', 2, 282, 'اے ایمان والو! جب تم کسی وقت مقرر تک آپس میں ادھار کا معاملہ کرو تو اسے لکھ لیا کرو اور چاہیئے کہ تمہارے درمیان لکھنے والے انصاف سے لکھے اور لکھنے والا لکھنے سے انکار نہ کرے جیسا کہ اس کو الله نے سکھایا ہے سو اسے چاہیئے کہ لکھ دے اور وہ شخص بتلاتا جائے کہ جس پر قرض ہے اور الله سے ڈرے جو اس کا رب ہے اور اس میں کچھ کم کر کے نہ لکھائے پھر اگر وہ شخص کہ جس پر قرض ہے بے وقوف ہے یا کمزور ہے یا وہ بتلا نہیں سکتا تو اس کا کارکن ٹھیک طور پر لکھوا دے اور اپنے مردوں میں سے دو گواہ کر لیا کرو پھر اگر دو مرد نہ ہوں تو ایک مرد اور دوعورتیں ان لوگوں میں سے جنہیں تم گواہو ں میں سے پسند کرتے ہوتاکہ اگر ایک ان میں سے بھول جائے تو دوسری اسے یاد دلا دے اور جب گواہوں کو بلایا جائے تو انکار نہ کریں اور معاملہ چھوٹا ہو یا بڑا اس کی معیاد تک لکھنے میں سستی نہ کرو یہ لکھ لینا الله کے نزدیک انصاف کو زیادہ قائم رکھنے والا ہے اور شہادت کا زیادہ درست رکھنے والا ہے اور زیادہ قریب ہے اس بات کے کہ تم کسی شبہ میں نہ پڑو مگر یہ کہ سوداگری ہاتھوں ہاتھ ہو جسے آپس میں لیتے دیتے ہو پھر تم پر کوئی گناہ نہیں کہ اسے نہ لکھو اور جب آپس میں سودا کرو تو گواہ بنا لو اور لکھنے والے اور گواہ بنانے والے کو تکلیف نہ دی جائے اور اگر تم نے تکلیف دی تو تمہیں گناہ ہوگا اور الله سے ڈرو اور الله تمہیں سکھاتا ہے اور الله ہر چیز کا جاننے والا ہے'),
  ('ur.ahmedali', 2, 283, 'اور اگر تم سفر میں ہو اور کوئی لکھنے والا نہ پاؤ تو گروی پر قبضہ کیا جائے اور اگر ایک تم میں سے دوسرے پر اعتبار کرے تو چاہیئے کہ کہ وہ شخص امانت ادا کردے جس پر اعتبار کیا گیا اور اپنے الله سے ڈرے جو اس کا رب ہے اور گواہی کو نہ چھپاؤ اور جو شخص اسے چھپائے گا تو بے شک اس کا دل گناہگار ہے اور جو کچھ تم کرتے ہو الله خوب جانتا ہے'),
  ('ur.ahmedali', 2, 284, 'جو کچھ آسمانوں اور زمین میں ہے اللہ ہی کا ہے اور اگر تم اپنے دل کی بات ظاہر کرو گے یا چھپاؤ گے الله تم سے اس کا حساب لے گا پھر جس کو چاہے بخشے گا اور جسے چاہے عذاب کرے گا اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 2, 285, 'رسول نے مان لیا جو کچھ اس پر اس کے رب کی طرف سے اترا ہے اور مسلمانوں نے بھی مان لیا سب نے الله کو اور اس کے فرشتوں کو اور اس کی کتابوں کو اور اس کے رسولوں کو مان لیا ہے کہتے ہیں کہ ہم الله کے رسولوں کو ایک دوسرے سے الگ نہیں کرتے اور کہتے ہیں ہم نے سنا اور مان لیا اے ہمارے رب تیری بخشش چاہتے ہیں اور تیری ہی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 2, 286, 'الله کسی کو اس کی طاقت کے سوا تکلیف نہیں دیتا نیکی کا فائدہ بھی اسی کو ہو گا اور برائی کی زد بھی اسی پر پڑے گی اے رب ہمارے! اگر ہم بھول جائیں یا غلطی کریں تو ہمیں نہ پکڑ اے رب ہمارے! اور ہم پر بھاری بوجھ نہ رکھ جیسا تو نے ہم سے پہلے لوگوں پر رکھا تھا اے رب ہمارے! اور ہم سے وہ بوجھ نہ اٹھوا جس کی ہمیں طاقت نہیں اور ہمیں معاف کر دے اور ہمیں بخش دے اور ہم پر رحم کر تو ہی ہمارا کارساز ہے کافروں کے مقابلہ میں تو ہماری مدد کر')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 2, 1, 'Elif, Lam, Mim.'),
  ('tr.diyanet', 2, 2, 'Bu, doğruluğu şüphe götürmeyen ve Allah\'a karşı gelmekten sakınanlara yol gösteren Kitap\'dır.'),
  ('tr.diyanet', 2, 3, 'Onlar, gaybe inanırlar, namazı kılarlar, kendilerine verdiğimiz rızıktan yerli yerince sarfederler.'),
  ('tr.diyanet', 2, 4, 'Onlar, sana indirilen Kitap\'a da, senden önce indirilenlere de inanırlar; ahirete de yalnız onlar kesinlikle inanırlar.'),
  ('tr.diyanet', 2, 5, 'İşte Rab\'lerinin yolunda olanlar ve saadete erişenler bunlardır.'),
  ('tr.diyanet', 2, 6, 'Şüphe yok ki, inkar edenleri, başlarına gelecekle uyarsan da uyarmasan da birdir, inanmazlar.'),
  ('tr.diyanet', 2, 7, 'Allah onların kalblerini ve kulaklarını mühürlemiştir, gözlerinde de perde vardır ve büyük azab onlar içindir.'),
  ('tr.diyanet', 2, 8, 'İnsanlardan, inanmadıkları halde, "Allah\'a ve ahiret gününe inandık" diyenler vardır.'),
  ('tr.diyanet', 2, 9, 'Bunlar Allah\'ı ve inananları aldatmaya çalışırlar, oysa sadece kendilerini aldatırlar da farkında değildirler.'),
  ('tr.diyanet', 2, 10, 'Kalblerinde hastalık vardır, Allah hastalıklarını artırmıştır. Yalan söyleye geldikleri için onlara elem verici azab vardır.'),
  ('tr.diyanet', 2, 11, 'Kendilerine: "Yeryüzünde bozgunculuk yapmayın" dendiği zaman, "Bizler sadece ıslah edicileriz" derler.'),
  ('tr.diyanet', 2, 12, 'İyi bilin ki, asıl bozguncular kendileridir, lakin farkında değillerdir.'),
  ('tr.diyanet', 2, 13, 'Onlara "Müslümanların inandığı gibi siz de inanın" denilince de, "Beyinsizlerin inandığı gibi mi inanalım?" derler; iyi bilin ki asıl beyinsizler kendileridir, fakat bilmezler.'),
  ('tr.diyanet', 2, 14, 'İnananlara rastladıkları zaman, "İnandık" derler, elebaşılarıyla baş başa kaldıklarında, "Biz şüphesiz sizinleyiz, onlarla sadece alay etmekteyiz" derler.'),
  ('tr.diyanet', 2, 15, 'Onlarla Allah alay eder ve taşkınlıkları içinde bocalar durumda bırakır.'),
  ('tr.diyanet', 2, 16, 'Onlar, doğruluk yerine sapıklığı aldılar da alışverişleri kar getirmedi; doğru yolu bulamamışlardı.'),
  ('tr.diyanet', 2, 17, 'Onlar, çevresini aydınlatmak için ateş yakan kimseye benzerler ki, Allah ışıklarını yok edince, onları karanlıklar içinde görmez bir halde bırakmıştır.'),
  ('tr.diyanet', 2, 18, 'Sağırdırlar, dilsizdirler, kördürler, bu yüzden doğru yola dönmezler.'),
  ('tr.diyanet', 2, 19, 'Bir kısmı da, karanlıklarda, gök gürlemeleri ve şimşek arasında gökten boşanan sağanağa tutulup, yıldırımlardan ölmek korkusu ile parmaklarını kulaklarına tıkayan kimseye benzer.'),
  ('tr.diyanet', 2, 20, 'Şimşeğin çakması neredeyse gözlerini alır; onları aydınlattıkça ışığında yürürler ve üzerlerine karanlık basınca durakalırlar. Allah dileseydi işitme ve görmelerini giderirdi. Doğrusu Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 2, 21, 'Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize kulluk ediniz ki, O\'na karşı gelmekten korunmuş olabilesiniz.'),
  ('tr.diyanet', 2, 22, 'O, yeryüzünü size bir döşek ve göğü de bir bina kıldı. Gökten su indirip onunla size rızık olmak üzere ürünler meydana getirdi; artık Allah\'a, bile bile eş koşmayın.'),
  ('tr.diyanet', 2, 23, 'Kulumuza indirdiğimiz Kuran\'dan şüphe ediyorsanız, siz de onun benzeri bir sure meydana getirin; eğer doğru sözlü iseniz, Allah\'tan başka, güvendiklerinizi de yardıma çağırın.'),
  ('tr.diyanet', 2, 24, 'Yapamazsanız ki yapamayacaksınız o takdirde, inkar edenler için hazırlanan ve yakıtı insanlarla taş olan ateşten sakının.'),
  ('tr.diyanet', 2, 25, 'İnananlar ve yararlı işler yapanlara, kendilerine altlarından ırmaklar akan cennetler olduğunu müjdele. Onlara buranın bir ürünü rızık olarak verildiğinde, "Bu daha önce de rızıklandığımızdır" derler. Bunlar, söylediklerinin benzerleri olarak sunulmuştur. Onlara orada tertemiz eşler vardır ve orada temelli kalırlar.'),
  ('tr.diyanet', 2, 26, 'Allah sivrisineği ve onun üstününü misal olarak vermekten çekinmez. İnananlar bunun Rablerinden bir gerçek olduğunu bilirler. İnkar edenler ise "Allah bu misalle neyi murad etti?" derler, O, bu misalle birçoğunu saptırır, birçoğunu da yola getirir. Onunla saptırdığı yalnız fasıklardır ki onlar Allah\'la yapılan sözleşmeyi kabulden sonra bozarlar. Allah\'ın birleştirilmesini buyurduğu şeyi ayırırlar ve yeryüzünde bozgunculuk yaparlar; zarara uğrayanlar işte onlardır.'),
  ('tr.diyanet', 2, 27, 'Onlar, Allah\'a verdikleri sözü, pekiştirilmesinden sonra bozan, Allah\'ın korunmasını emrettiği bağları (iman, akrabalık, beşeri ve ahlâki bütün ilişkileri) koparan ve yeryüzünde bozgunculuk yapan kimselerdir. İşte onlar ziyana uğrayanların ta kendileridir.'),
  ('tr.diyanet', 2, 28, 'Ölü idiniz sizleri diriltti, sonra öldürecek sonra tekrar diriltecek ve sonunda O\'na döneceksiniz; öyleyken Allah\'ı nasıl inkar edersiniz?'),
  ('tr.diyanet', 2, 29, 'Yerde olanların hepsini; sizin için yaratan O\'dur. Sonra, göğe doğru yönelerek yedi gök olarak onları düzenlemiştir. O her şeyi bilir.'),
  ('tr.diyanet', 2, 30, 'Rabbin meleklere "Ben yeryüzünde bir halife var edeceğim" demişti; melekler, "Orada bozgunculuk yapacak, kanlar akıtacak birini mi var edeceksin? Oysa biz Seni överek yüceltiyor ve Seni devamlı takdis ediyoruz" dediler; Allah "Ben şüphesiz sizin bilmediklerinizi bilirim" dedi.'),
  ('tr.diyanet', 2, 31, 'Ve Adem\'e bütün isimleri öğretti, sonra eşyayı meleklere gösterdi. "Eğer sözünüzde samimi iseniz bunların isimlerini bana söyleyin" dedi.'),
  ('tr.diyanet', 2, 32, 'Cevap verdiler: "Sen münezzehsin, öğrettiğinden başka bizim bir bilgimiz yoktur. Şüphesiz Sen hem bilensin, hem Hakim\'sin".'),
  ('tr.diyanet', 2, 33, 'Allah "Ey Adem onlara isimlerini söyle" dedi. Adem isimlerini söyleyince, Allah "Ben gökler ve yerde görünmeyeni biliyorum, sizin açıkladığınızı ve gizlemekte olduğunuzu da bilirim, diye size söylememiş miydim?" dedi.'),
  ('tr.diyanet', 2, 34, 'Meleklere, "Adem\'e secde edin" demiştik, İblis müstesna hepsi secde ettiler, o ise kaçındı, büyüklük tasladı ve inkar edenlerden oldu.'),
  ('tr.diyanet', 2, 35, '"Ey Adem! Eşin ve sen cennette kal, orada olandan istediğiniz yerde bol bol yiyin, yalnız şu ağaca yaklaşmayın; yoksa zalimlerden olursunuz" dedik.'),
  ('tr.diyanet', 2, 36, 'Şeytan oradan ikisinin de ayağını kaydırttı, onları bulundukları yerden çıkardı, onlara "Birbirinize düşman olarak inin, yeryüzünde bir müddet için yerleşip geçineceksiniz" dedik.'),
  ('tr.diyanet', 2, 37, 'Adem, Rabbi\'nden emirler aldı; onları yerine getirdi. Rabb\'i de bunun üzerine tevbesini kabul etti. Şüphesiz o tevbeleri daima kabul edendir, merhametli olandır.'),
  ('tr.diyanet', 2, 38, '"İnin oradan hepiniz, tarafımdan size bir yol gösteren gelecektir; Benim yoluma uyanlar için artık korku yoktur, onlar üzülmeyeceklerdir" dedik.'),
  ('tr.diyanet', 2, 39, 'İnkar eden kimseler ve ayetlerimizi yalan sayanlar cehennemlik olanlardır, onlar orada temelli kalacaklardır.'),
  ('tr.diyanet', 2, 40, 'Ey İsrailoğulları! Size verdiğim nimeti hatırlayın ve ahdimi yerine getirin ki Ben de yerine getireyim; yoksa benden korkun.'),
  ('tr.diyanet', 2, 41, 'Yanınızdaki Tevrat\'ı tasdik ederek indirdiğim Kuran\'a, inanın; onu ilk inkar edenler siz olmayın, ayetlerimi hiçbir değere karşılık değiştirmeyin ve bile bile hakkı gizlemeyin.'),
  ('tr.diyanet', 2, 42, 'Hakkı batıla karıştırmayın ve bile bile hakkı gizlemeyin.'),
  ('tr.diyanet', 2, 43, 'Namazı kılın, zekatı verin, rüku edenlerle birlikte rüku edin.'),
  ('tr.diyanet', 2, 44, 'Kitap\'ı okuyup durduğunuz halde kendinizi unutur da başkalarına mı iyilikle emredersiniz? Düşünmez misiniz?'),
  ('tr.diyanet', 2, 45, 'Sabır ve namazla Allah\'a sığınıp yardım isteyin; Rablerine kavuşacaklarını ve Ona döneceklerini umanlar ve huşu duyanlardan başkasına namaz elbette ağır gelir.'),
  ('tr.diyanet', 2, 46, 'Sabır ve namazla Allah\'a sığınıp yardım isteyin; Rablerine kavuşacaklarını ve Ona döneceklerini umanlar ve huşu duyanlardan başkasına namaz elbette ağır gelir.'),
  ('tr.diyanet', 2, 47, 'Ey İsrailoğulları! Size verdiğim nimeti ve sizi bir zamanlar alemlere üstün kıldığımı hatırlayın.'),
  ('tr.diyanet', 2, 48, 'Kimsenin kimseden faydalanamayacağı, kimseden bir şefaat kabul edilmeyeceği, kimseden bir fidye alınmayacağı ve yardım görülmeyeceği günden korunun.'),
  ('tr.diyanet', 2, 49, 'Size işkence eden, kadınlarınızı sağ bırakıp oğullarınızı boğazlayan Firavun ailesinden sizi kurtarmıştık; bu Rabbinizin büyük bir imtihanı idi.'),
  ('tr.diyanet', 2, 50, 'Denizi yarıp sizi kurtarmış ve gözlerinizin önünde Firavun ailesini batırmıştık.'),
  ('tr.diyanet', 2, 51, 'Musa\'ya kırk gece vade vermiştik. Sonra onun arkasından, kendinize yazık ederek, buzağıyı tanrı edinmiştiniz.'),
  ('tr.diyanet', 2, 52, 'Sonra bunun ardından, şükredersiniz diye, sizi bağışlamıştık.'),
  ('tr.diyanet', 2, 53, 'Doğru yola gidesiniz diye Musa\'ya hakkı batıldan ayıran Kitabı vermiştik.'),
  ('tr.diyanet', 2, 54, 'Musa milletine "Ey milletim! Buzağıyı tanrı olarak benimsemekle kendinize yazık ettiniz. Yaratanınıza tevbe edin ve nefislerinizi öldürün, bu Yaratanınız katında sizin için hayırlı olur; O daima tevbeleri kabul ve merhamet eden olduğu için tevbenizikabul eder" demişti.'),
  ('tr.diyanet', 2, 55, '"Ya Musa! Allah\'ı apaçık görmedikçe sana inanmayacağız" demiştiniz de gözleriniz göre göre sizi yıldırım çarpmıştı.'),
  ('tr.diyanet', 2, 56, 'Ölümünüzden sonra, şükredesiniz diye sizi tekrar diriltmiştik.'),
  ('tr.diyanet', 2, 57, 'Bulutla sizi gölgelendirdik, kudret helvası ve bıldırcın indirdik, "Verdiğimiz rızıkların iyi ve güzel olanlarından yiyin" dedik. Onlar Bize değil, fakat kendilerine yazık ediyorlardı.'),
  ('tr.diyanet', 2, 58, '"Şu şehre girin, orada dilediğiniz gibi, bol bol yiyin, secde ederek kapısından girin, "bağışla!" deyin, Biz de yanılmalarınızı bağışlarız, iyilere daha da artırırız" demiştik.'),
  ('tr.diyanet', 2, 59, 'Ama zulmedenler, kendilerine söylenmiş olan sözü başka sözle değiştirdiler. Biz de, zalimlere, yoldan çıkmalarından dolayı gökten azab indirdik.'),
  ('tr.diyanet', 2, 60, 'Musa, milleti için su aramıştı; "Asanla taşa vur" dedik; ondan on iki pınar fışkırdı, herkes içeceği yeri bildi. Allah\'ın rızkından yiyin, için, yalnız yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.'),
  ('tr.diyanet', 2, 61, '"Ey Musa! Bir çeşit yemeğe dayanamayacağız, bizim için Rabbine yalvar, bize, yerin bitirdiği sebze, hıyar, sarımsak, mercimek ve soğan yetiştirsin" demiştiniz de, "Hayırlı olanı daha düşük şeyle mi değiştirmek istiyorsunuz? Bir şehre inin, şüphesiz orada istediğiniz vardır" demişti. Onlara yoksulluk ve düşkünlük damgası vuruldu, Allah\'ın gazabına uğradılar. Bu, Allah\'ın ayetlerini inkar etmeleri ve haksız yere peygamberleri öldürmelerindendi; bu, karşı gelmeleri ve taşkınlık yapmalarındandı.'),
  ('tr.diyanet', 2, 62, 'Şüphesiz, inananlar, Yahudi olanlar, Hıristiyanlar ve Sabiilerden Allah\'a ve ahiret gününe inanıp yararlı iş yapanların ecirleri Rablerinin katındadır. Onlar için artık korku yoktur. Onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 2, 63, 'Sizden kesin söz almıştık. Tur dağını yükselterek tepenize dikmiştik. "Allah\'a karşı gelmekten sakınanlardan olabilmeniz için, size verdiğimiz Kitab\'a kuvvetle sarılın, onda bulunanları hatırda tutun" demiştik.'),
  ('tr.diyanet', 2, 64, 'Bundan sonra yine yüz çevirdiniz; eğer Allah\'ın size bol nimeti ve merhameti olmasaydı, muhakkak zarara uğrayanlardan olurdunuz.'),
  ('tr.diyanet', 2, 65, 'İçinizden cumartesi günü azgınlık edenleri elbette biliyorsunuz. Onlara "Aşağılık birer maymun olunuz" dedik; bunu, çağdaşlarına ve sonradan geleceklere bir ceza örneği ve Allah\'a karşı gelmekten sakınanlara öğüt olsun diye yaptık.'),
  ('tr.diyanet', 2, 66, 'İçinizden cumartesi günü azgınlık edenleri elbette biliyorsunuz. Onlara "Aşağılık birer maymun olunuz" dedik; bunu, çağdaşlarına ve sonradan geleceklere bir ceza örneği ve Allah\'a karşı gelmekten sakınanlara öğüt olsun diye yaptık.'),
  ('tr.diyanet', 2, 67, 'Musa milletine: "Allah muhakkak bir sığır boğazlamanızı buyuruyor" demişti; "Bizi alaya mı alıyorsun?" dediklerinde de: "Cahillerden olmaktan Allah\'a sığınırım" dedi.'),
  ('tr.diyanet', 2, 68, '"Rabbine bizim adımıza yalvar da onun mahiyetini bize bildirsin" dediler, "O, onun ne pek kart, ne pek körpe, ikisi ortası bir sığır olduğunu söylüyor, size emrolunanı yapın" dedi.'),
  ('tr.diyanet', 2, 69, '"Rabbine bizim adımıza yalvar da ne renk olduğunu bize bildirsin" dediler. "O, onun, bakanların içini açan parlak sarı renkli bir sığır olduğunu söylüyor" dedi.'),
  ('tr.diyanet', 2, 70, '"Rabbine bizim adımıza yalvar da, mahiyetini bize bildirsin, çünkü sığırlar, bizce, birbirine benzemektedir. Allah dilerse biz şüphesiz doğruyu bulmuş oluruz" dediler.'),
  ('tr.diyanet', 2, 71, '"Yeri sürüp, ekini sulayarak boyunduruk altında ezilmemiş, kusursuz, alacasız bir sığır olduğunu söylüyor" dedi. "Şimdi gerçeği bildirdin" deyip sığırı boğazladılar; az kalsın bunu yapmayacaklardı.'),
  ('tr.diyanet', 2, 72, 'Siz bir kimseyi öldürmüş ve bunu birbirinize atmıştınız; oysa Allah gizlemekte olduğunuzu ortaya çıkaracaktı.'),
  ('tr.diyanet', 2, 73, '"Sığırın bir parçasıyla ona vurun" dedik. İşte böylece Allah ölüleri diriltir ve aklınızı kullanasınız diye size ayetlerini gösterir.'),
  ('tr.diyanet', 2, 74, 'Sonra kalbleriniz yine katılaştı, taş gibi, hatta daha da katı oldu. Nitekim taşlar arasında kendisinden ırmaklar fışkıran vardır; yarılıp su çıkan vardır; Allah korkusundan yuvarlananlar vardır. Allah yaptıklarınızı bilmez değildir.'),
  ('tr.diyanet', 2, 75, 'Size inanacaklarını umuyor musunuz? Oysa onlardan bir takımı Allah\'ın sözünü işitiyor, ona akılları yattıktan sonra, bile bile onu tahrif ediyorlardı.'),
  ('tr.diyanet', 2, 76, 'İnananlarla karşılaştıkları zaman, "İnandık" derlerdi; birbirleriyle yalnız kaldıklarında, "Rabbinizin katında size karşı hüccet göstersinler diye mi Allah\'ın size açıkladığını onlara anlatıyorsunuz? Bunu akletmiyor musunuz?" derlerdi.'),
  ('tr.diyanet', 2, 77, 'Gizlediklerini de, açıkladıklarını da Allah\'ın bildiğini bilmiyorlar mı?'),
  ('tr.diyanet', 2, 78, 'Onların bir kısmının okuyup yazması yoktu. Kitab\'ı bilmezlerdi; bildikleri sadece bir takım yalan ve kuruntulardı. Onlar ancak vehim içindedirler.'),
  ('tr.diyanet', 2, 79, 'Vay, Kitabı elleriyle yazıp, sonra da onu az bir değere satmak için, "Bu Allah katındandır" diyenlere! Vay ellerinin yazdıklarına! Vay kazandıklarına!'),
  ('tr.diyanet', 2, 80, '"Ateş bize sadece sayılı birkaç gün değecektir", derler; sor, "Allah katından siz söz mü aldınız?", eğer öyle ise Allah sözünden caymayacaktır. "Yoksa Allah\'a karşı bilmediğiniz bir şey mi söylüyorsunuz?"'),
  ('tr.diyanet', 2, 81, 'Hayır öyle değil; kötülük işleyip suçu kendisini kuşatmış olan kimseler; cehennemlikler işte onlardır. Onlar orada temellidirler.'),
  ('tr.diyanet', 2, 82, 'İnanıp yararlı işler yapan kimseler cennetlik olanlardır, onlar da orada temellidirler.'),
  ('tr.diyanet', 2, 83, 'İsrailoğullarından, "Allah\'tan başkasına kulluk etmeyin, anne babaya, yakınlara, yetimlere, düşkünlere iyilik edin, insanlarla güzel güzel konuşun, namazı kılın, zekatı verin" diye söz almıştık. Sonra siz pek azınız müstesna, döndünüz; hala da yüz çevirip duruyorsunuz.'),
  ('tr.diyanet', 2, 84, 'Kanınızı dökmeyin, birbirinizi yurdunuzdan sürmeyin diye sizden söz almıştık, sonra bunu böylece kabul etmiştiniz, buna siz şahidsiniz.'),
  ('tr.diyanet', 2, 85, 'Sonra siz, birbirinizi öldüren, aranızdan bir takımı memleketlerinden süren, onlara karşı günah ve düşmanlıkta birleşen, onları çıkarmak haramken size esir olarak geldiklerinde fidyelerini vermeye kalkan kimselersiniz. Kitabın bir kısmına inanıp, bir kısmını inkar mı ediyorsunuz? Aranızda böyle yapanın cezası ancak dünya hayatında rezil olmaktır. Ahiret gününde de azabın en şiddetlisine onlar uğratılırlar. Allah yaptıklarınızdan gafil değildir.'),
  ('tr.diyanet', 2, 86, 'Onlar ahiret karşılığında dünya hayatını satın alan kimselerdir, bu yüzden azabları hafifletilmez, onlar yardım da görmezler.'),
  ('tr.diyanet', 2, 87, 'And olsun ki, Musa\'ya kitap verdik, ondan sonra ardarda peygamberler gönderdik. Meryem oğlu İsa\'ya belgeler verdik, onu Ruhul Kudüs ile destekledik. Size bir peygamber nefsinizin hoşlanmadığı bir şey getirdikçe, büyüklük taslayarak, bir kısmını yalancı sayıp, bir kısmını öldürür müsünüz?'),
  ('tr.diyanet', 2, 88, '"Kalplerimiz perdelidir" dediler, hayır, Allah inkarlarından dolayı onları lanetlemiştir. Onların pek azı inanırlar.'),
  ('tr.diyanet', 2, 89, 'Vaktaki Allah katından onlara, kendilerinde olanı tasdik eden Kitap geldi ki onlar bundan önceleri, inkar edenlere karşı kendilerine yardım gelmesini beklerlerdi, bildikleri gelince onu inkar ettiler. Allah\'ın laneti, inkar edenlerin üzerine olsun.'),
  ('tr.diyanet', 2, 90, 'Allah\'ın kullarından dilediğine, bol ihsanından indirmesini çekemeyerek, Allah\'ın indirdiğini inkar etmekle, kendilerini ne kötü bir şey karşılığında sattılar. Bu yüzden gazab üstüne gazaba uğradılar. Kafirlere alçaltıcı bir azab vardır.'),
  ('tr.diyanet', 2, 91, 'Onlara, "Allah\'ın indirdiğine inanın" denildiğinde "Bize indirilene inanırız" deyip ondan sonra gelen Kuran\'ı inkar ederler; halbuki o, ellerinde bulunan Tevrat\'ı tasdik eden hak bir Kitap\'dır. Onlara "Eğer inanıyor idiyseniz niçin daha önce Allah\'ın peygamberlerini öldürüyordunuz?" diye sor.'),
  ('tr.diyanet', 2, 92, 'And olsun ki, Musa size mucizeler getirdi, sonra ardından kendinize yazık ederek buzağıyı tanrı olarak benimsediniz.'),
  ('tr.diyanet', 2, 93, 'Sizden kesin söz almış ve Tur\'u tepenize dikmiştik, "Size verdiğimize kuvvetle sarılın ve dinleyin" demiştik "İşittik ve karşı geldik" dediler de inkarları yüzünden buzağı sevgisi kalblerine sindirildi. De ki, "Eğer inanmışsanız, imanınız size ne kötü şey emrediyor?"'),
  ('tr.diyanet', 2, 94, 'De ki, "Eğer ahiret yurdu Allah katında başkalarına değil de yalnız size mahsus ise ve eğer doğru sözlü iseniz, ölümü dilesenize!"'),
  ('tr.diyanet', 2, 95, 'Bunu, önceden işlediklerinden ötürü, asla dilemeyeceklerdir. Allah zalimleri bilir.'),
  ('tr.diyanet', 2, 96, 'And olsun ki, onların hayata diğer insanlardan ve hatta Allah\'a eş koşanlardan da daha düşkün olduklarını görürsün. Her biri ömrünün bin yıl olmasını ister. Oysa uzun ömürlü olması onu azabdan uzaklaştırmaz. Allah onların yaptıklarını görür.'),
  ('tr.diyanet', 2, 97, 'De ki, "Cebrail\'e düşman olan kimse Allah\'a düşmandır", çünkü O, Kuran\'ı Allah\'ın izniyle kendinden öncekini tasdik ederek, yol gösterici ve inananlara müjdeci olarak senin kalbine indirmiştir.'),
  ('tr.diyanet', 2, 98, 'Allah\'a, meleklerine, peygamberlerine, Cebrail\'e ve Mikail\'e düşman olan kimse inkar etmiş olur. Allah şüphesiz, inkar edenlerin düşmanıdır.'),
  ('tr.diyanet', 2, 99, 'And olsun ki, sana apaçık ayetler indirdik. Onları sadece yoldan çıkmışlar inkar eder.'),
  ('tr.diyanet', 2, 100, 'Onlar, her ne zaman bir ahidde bulunmuşlarsa içlerinden bir takımı onu bozmamış mıdır? Zaten onların çoğu inanmazlar.'),
  ('tr.diyanet', 2, 101, 'Yanlarındakini doğrulayan bir Peygamber, Allah katından onlara gelince Kitap verilenlerden bir takımı, bilmiyorlarmış gibi, Allah\'ın Kitabı\'nı arkalarına attılar.'),
  ('tr.diyanet', 2, 102, 'Şeytanların Süleyman\'ın hükümdarlığı hakkında söylediklerine uydular. Oysa Süleyman kafir değildi, ama insanlara sihri öğreten şeytanlar kafir olmuşlardı. Babil\'de, melek denilen Harut ve Marut\'a bir şey indirilmemişti. Bu ikisi "Biz sadece imtihan ediyoruz, sakın inkar etme" demedikçe kimseye bir şey öğretmezlerdi. Halbuki bu ikisinden, koca ile karısının arasını ayıracak şeyler öğreniyorlardı. Oysa Allah\'ın izni olmadıkça onlar kimseye zarar veremezlerdi. Kendilerine zarar verecek, faydalı olmayacak şeyler öğreniyorlardı. And olsun ki, onu satın alanın ahiretten bir nasibi olmadığını biliyorlardı. Kendilerini karşılığında sattıkları şeyin ne kötü olduğunu keşke bilselerdi!'),
  ('tr.diyanet', 2, 103, 'Onlar inanıp, Allah\'a karşı gelmekten sakınsalardı, Allah katından olan sevab daha hayırlı olurdu. Keşke bilselerdi!'),
  ('tr.diyanet', 2, 104, 'Ey inananlar! Peygamber\'e, "Bizi de dinle" (raina; kötü anlama gelebilecek söz) demeyin, "Bizi gözet" (unzurna) deyin ve dinleyin, inkar edenlere elem verici azab vardır.'),
  ('tr.diyanet', 2, 105, 'Kitap ehlinden ve Allah\'a eş koşanlardan inkar edenler, Rabbinizden size bir iyilik gelmesini istemezler. Allah, rahmetini dilediğine tahsis eder. Allah büyük nimet sahibidir.'),
  ('tr.diyanet', 2, 106, 'Herhangi bir ayetin hükmünü yürürlükten kaldırır veya unutturursak, onun yerine daha hayırlısını veya onun benzerini getiririz. Allah\'ın her şeye kadir olduğunu bilmez misin?'),
  ('tr.diyanet', 2, 107, 'Göklerin ve yerin Hükümdarlığının Allah\'a aid olduğunu bilmez misin? Allah\'tan başka dost ve yardımcınız yoktur.'),
  ('tr.diyanet', 2, 108, 'Yoksa, daha önce Musa\'nın sorguya çekildiği gibi, siz de peygamberinizi sorguya mı çekmek istiyorsunuz? İmanı inkarla değiştiren, şüphesiz doğru yoldan sapmış olur.'),
  ('tr.diyanet', 2, 109, 'Kitap ehlinin çoğu, hak kendilerine apaçık belli olduktan sonra, içlerindeki çekememezlikten ötürü, sizi, inandıktan sonra küfre döndürmeyi isterler. Allah\'ın emri gelene kadar onları affedin, geçin. Allah muhakkak her şeye Kadir\'dir.'),
  ('tr.diyanet', 2, 110, 'Namazı kılın, zekatı verin, kendiniz için önden gönderdiğiniz her hayrı Allah katında bulacaksınız. Allah yaptıklarınızı şüphesiz görür.'),
  ('tr.diyanet', 2, 111, '"Yahudi veya Hıristiyan olmayan kimse elbette cennete girmeyecek" dediler; bu onların kuruntularıdır. De ki: "Sözünüz doğru ise delillerinizi getirin".'),
  ('tr.diyanet', 2, 112, 'Hayır, öyle değil; iyilik yaparak kendini Allah\'a veren kimsenin ecri Rabbi\'nin katındadır. Onlara korku yoktur, onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 2, 113, 'Yahudiler "Hıristiyanlar bir temel üzerinde değil" dediler, Hıristiyanlar da "Yahudiler bir temel üzerinde değil" dediler; oysa onlar Kitaplarını da okuyorlar. Bilgisizler de tıpkı onların söylediklerini söylemiştir. Allah, kıyamet günü, anlaşmazlığa düştükleri şeylerde onların arasında hüküm verecektir.'),
  ('tr.diyanet', 2, 114, 'Allah\'ın mescidlerinde O\'nun isminin anılmasını yasak eden ve oraların yıkılmasına çalışan kimseden daha zalim kim vardır? Onların oralara korkmadan girememeleri gerekir. Dünyada rezillik onlaradır, ahirette büyük azab da onlaradır.'),
  ('tr.diyanet', 2, 115, 'Doğu da batı da Allah\'ındır, nereye dönerseniz Allah\'ın yönü orasıdır. Doğrusu Allah her yeri kaplar ve her şeyi bilir.'),
  ('tr.diyanet', 2, 116, '"Allah oğul edindi" dediler; haşa, oysa, göklerde ve yerde olanlar O\'nundur. Hepsi O\'na boyun eğmişlerdir.'),
  ('tr.diyanet', 2, 117, 'Gökleri ve yeri yoktan var eden Allah\'tır. O, bir işin olmasını dilerse, ona ancak "ol" der ve olur.'),
  ('tr.diyanet', 2, 118, 'Bilmeyenler: "Allah bizimle konuşmalı veya bize bir ayet gelmeli değil miydi?" dediler. Onlardan öncekiler de onların söylediklerinin tıpkısını söylemişlerdi. Kalbleri birbirine benzedi. Kesinlikle inanan kimseler için ayetleri açıklamışızdır.'),
  ('tr.diyanet', 2, 119, 'Doğrusu Biz, seni hak ile, müjdeci ve uyarıcı olarak göndermişizdir. Sen, cehennemliklerden sorumlu tutulmayacaksın.'),
  ('tr.diyanet', 2, 120, 'Kendi dinlerine uymadıkça, Yahudi ve Hıristiyanlar senden asla hoşnud olmayacaklardır. De ki: "Doğru yol, ancak Allah\'ın yoludur". Sana gelen ilimden sonra onların heveslerine uyarsan, and olsun ki, Allah\'tan sana ne bir dost ve ne de bir yardımcı olur.'),
  ('tr.diyanet', 2, 121, 'Kendilerine verdiğimiz Kitabı gereğince okuyanlar var ya, işte ona ancak onlar inanırlar. Onu inkar edenler ise kaybedenlerdir.'),
  ('tr.diyanet', 2, 122, 'Ey İsrailoğulları! Size verdiğim nimeti ve sizi bir zamanlar alemlere üstün tuttuğumu hatırlayın.'),
  ('tr.diyanet', 2, 123, 'Kimsenin kimse namına bir şey ödemeyeceği, hiç kimseden fidye alınmayacağı, kimseye şefaatin yarar sağlamayacağı ve onların yardım görmeyeceği günden korunun.'),
  ('tr.diyanet', 2, 124, 'Rabbi İbrahim\'i bir takım emirlerle denemiş, o da onları yerine getirmişti. Allah, "seni insanlara önder kılacağım" demişti. O "soyumdan da" deyince, "zalimler benim ahdime erişemez" buyurmuştu.'),
  ('tr.diyanet', 2, 125, 'Kabeyi, insanlar için toplanma ve güven yeri kılmıştık. İbrahim\'in makamını namaz yeri edinin, dedik. Evimi ziyaret edenler, kendini ibadete verenler, rüku ve secde edenler için temiz tutun diye İbrahim ve İsmail\'e ahd verdik.'),
  ('tr.diyanet', 2, 126, 'İbrahim: "Rabbim! Burasını emin bir şehir kıl, halkından, Allah\'a ve ahiret gününe inananları ürünlerle rızıklandır" demişti. Allah da: "İnkar edeni de az bir müddet geçindirir, sonra da onu ateşin azabına uğramak zorunda bırakırım, ne kötü sonuç" buyurmuştu.'),
  ('tr.diyanet', 2, 127, 'İbrahim ve İsmail, Kabenin temellerini yükseltiyordu: "Rabbimiz! Yaptığımızı kabul buyur. Şüphesiz ki, Sen hem işitir hem bilirsin"'),
  ('tr.diyanet', 2, 128, '"Rabbimiz! İkimizi Sana teslim olanlardan kıl, soyumuzdan da Sana teslim olanlardan bir ümmet yetiştir. Bize ibadet yollarımızı göster, tevbemizi kabul buyur, çünkü tevbeleri daima kabul eden, merhametli olan ancak Sensin".'),
  ('tr.diyanet', 2, 129, '"Rabbimiz! İçlerinden onlara Senin ayetlerini okuyan, Kitabı ve hikmeti öğreten, onları her kötülükten arıtan bir peygamber gönder. Doğrusu güçlü ve Hakim olan ancak Sensin".'),
  ('tr.diyanet', 2, 130, 'Kendini bilmezden başkası İbrahim\'in dininden yüz çevirmez. And olsun ki, dünyada onu seçtik, şüphesiz o, ahirette de iyilerdendir.'),
  ('tr.diyanet', 2, 131, 'Rabbi ona: "Teslim ol" buyurduğunda, "Alemlerin Rabbine teslim oldum" demişti.'),
  ('tr.diyanet', 2, 132, 'İbrahim bunu oğullarına vasiyet etti. Yakub da: "Oğullarım! Allah dini size seçti, siz de ancak O\'na teslim olmuş olarak can verin" dedi.'),
  ('tr.diyanet', 2, 133, 'Yoksa Yakub can verirken sizler yanında mı idiniz? O, oğullarına: "Benden sonra kime kulluk edeceksiniz?" diye sormuştu; Onlar da: "Senin Tanrına ve ataların İbrahim, İsmail, İshak\'ın Tanrısı olan tek Tanrıya kulluk edeceğiz, bizler O\'na teslim olmuşuzdur" demişlerdi.'),
  ('tr.diyanet', 2, 134, 'Onlar geçmiş birer ümmettir. Kazandıkları kendilerine, sizin kazandıklarınız da sizedir. Onların yapmış olduklarından sorumlu değilsiniz.'),
  ('tr.diyanet', 2, 135, '"Yahudi veya Hıristiyan olun ki doğru yolu bulasınız" dediler. "Doğruya yönelmiş olan ve Allah\'a eş koşanlardan olmayan İbrahim\'in dinine uyarız" de.'),
  ('tr.diyanet', 2, 136, '"Allah\'a, bize gönderilene, İbrahim\'e, İsmail\'e, İshak\'a, Yakub\'a ve torunlarına gönderilene, Musa ve İsa\'ya verilene, Rableri tarafından peygamberlere verilene, onları birbirinden ayırt etmeyerek inandık, biz O\'na teslim olanlarız" deyin.'),
  ('tr.diyanet', 2, 137, 'Sizin inandığınız gibi inanmış olsalar, doğru yolu bulmuş olurlar. Yüz çevirirlerse, şüphesiz onlar çıkmazdadırlar. Onlara karşı sana Allah yetecektir. O, işitir ve bilir.'),
  ('tr.diyanet', 2, 138, 'Allah\'ın verdiği renge uyun; rengi Allah\'ınkinden daha güzel olan kim vardır? "Biz O\'na kulluk edenleriz" deyin.'),
  ('tr.diyanet', 2, 139, 'De ki: "Bizim ve sizin Rabbiniz olan Allah hakkında bize karşı hüccet mi gösteriyorsunuz? Bizim yaptıklarımız kendimize, sizin yaptıklarınız de kendinize aittir. Biz O\'na karşı samimiyiz".'),
  ('tr.diyanet', 2, 140, 'Yoksa İbrahim, İsmail, İshak, Yakub ve torunlarının Yahudi veya Hıristiyan olduklarını mı söylüyorsunuz? Peki, siz mi yoksa Allah mı daha iyi bilir? de. Allah tarafından kendisine bildirilen bir gerçeği gizleyenden daha zalim kim vardır? Allah yaptıklarınızdan gafil değildir.'),
  ('tr.diyanet', 2, 141, 'Onlar geçmiş birer ümmettir. Kazandıkları kendilerine, sizin kazandıklarınız da sizedir. Onların yapmış olduklarından sorumlu değilsiniz.'),
  ('tr.diyanet', 2, 142, 'İnsanların beyinsizleri, "Yöneldikleri kıbleden onları çeviren nedir?" diyecekler; de ki: "Doğu ve batı Allah\'ındır. O, dilediğini doğru yola eriştirir".'),
  ('tr.diyanet', 2, 143, 'Böylece sizi insanlara şahid ve örnek olmanız için tam ortada bulunan bir ümmet kıldık. Peygamber de size şahid ve örnektir. Senin yöneldiğin yönü, Peygambere uyanları, cayacaklardan ayırdetmek için kıble yaptık. Doğrusu Allah\'ın yola koyduğu kimselerden başkasına bu ağır bir şeydir. Allah ibadetlerinizi boşa çıkaracak değildir. Doğrusu Allah insanlara şefkat gösterir, merhamet eder.'),
  ('tr.diyanet', 2, 144, 'Yüzünü göğe çevirip durduğunu görüyoruz. Hoşnud olacağın kıbleye seni elbette çevireceğiz. Artık yüzünü Mescid-i Haram semtine çevir; bulunduğunuz yerde yüzlerinizi o yöne çevirin. Doğrusu Kitap verilenler, bunun Rab\'lerinden bir gerçek olduğunu bilirler. Allah onların yaptıklarından gafil değildir.'),
  ('tr.diyanet', 2, 145, 'Sen, Kitap verilenlere her türlü delili getirsen, yine de kıblene uymazlar; sen de onların kıblesine uyacak değilsin. Onlar birbirlerinin kıblesine de uymazlar. And olsun ki, eğer sana gelen ilimden sonra onların heveslerine uyarsan, şüphesiz o zaman zulmedenlerden olursun.'),
  ('tr.diyanet', 2, 146, 'Kendilerine Kitap verdiklerimiz, onu (peygamberi) oğullarını tanıdıkları gibi tanırlar. Onlardan bir takımı, doğrusu bile bile hakkı gizlerler.'),
  ('tr.diyanet', 2, 147, 'Gerçek Rabb\'indendir, sakın şüphelenenlerden olma.'),
  ('tr.diyanet', 2, 148, 'Herkesin yöneldiği bir yön vardır. Hayırlı işlerde birbirinizle yarışın. Nerede olursanız olun Allah sizi bir araya toplar, Allah şüphesiz her şeye Kadir\'dir.'),
  ('tr.diyanet', 2, 149, 'Her nereden yola çıkarsan, yüzünü Mescid-i Haram semtine çevir, şüphesiz bu Rabbinden bir haktır. Allah, yaptıklarınızdan gafil değildir.'),
  ('tr.diyanet', 2, 150, 'Her nereden çıkarsan, yüzünü Mescid-i Haram semtine çevir. İnsanların zulmedenlerinden başkalarının size karşı gösterecekleri bir hüccet olmaması için, her nerede olursanız, yüzlerinizi oranın semtine çevirin, bu hususta onlardan korkmayın. Benden korkun da size olan nimetimi tamamlayayım. Böylece doğru yolu bulursunuz.'),
  ('tr.diyanet', 2, 151, 'Nitekim Biz size, ayetlerimizi okuyacak, sizi her kötülükten arıtacak, size kitabı ve hikmeti öğretecek ve bilmediklerinizi bildirecek aranızdan, bir Peygamber gönderdik.'),
  ('tr.diyanet', 2, 152, 'Artık Beni anın, Ben de sizi anayım; Bana şükredin, nankörlük etmeyin.'),
  ('tr.diyanet', 2, 153, 'Ey İnananlar! Sabır ve namazla yardım dileyin. Allah, muhakkak ki sabredenlerle beraberdir.'),
  ('tr.diyanet', 2, 154, 'Allah yolunda öldürülenlere "Ölüler" demeyin, zira onlar diridirler, fakat siz farkında değilsiniz.'),
  ('tr.diyanet', 2, 155, 'Muhakkak sizi biraz korku, biraz açlık ve mallardan, canlardan, ürünlerden biraz eksiltmekle deneriz, sabredenleri müjdele.'),
  ('tr.diyanet', 2, 156, 'Onlara bir musibet geldiğinde: "Biz Allah\'ınız ve elbette O\'na döneceğiz" derler.'),
  ('tr.diyanet', 2, 157, 'Rablerinin mağfiret ve rahmeti onlaradır. O\'nun yolunda olanlar da onlardır.'),
  ('tr.diyanet', 2, 158, 'Şüphesiz Safa ile Merve Allah\'ın nişanelerindendir. Kim Kabe\'yi hacceder veya umre yaparsa, bu ikisini de tavaf etmesinde bir beis yoktur. Kim gönülden iyilik yaparsa, karşılığını görür. Doğrusu Allah şükrün karşılığını verendir ve bilendir.'),
  ('tr.diyanet', 2, 159, 'İndirdiğimiz belgeleri ve doğru yolu Kitab\'da insanlara açıkladıktan sonra, gizleyen kimseler var ya, onlara hem Allah lanet eder, hem lanetçiler lanet eder, ancak tevbe edenler, ıslah olanlar ve gerçeği ortaya koyanlar müstesna; işte onların tevbesini kabul ederim. Ben, tevbeleri daima kabul ve merhamet edenim.'),
  ('tr.diyanet', 2, 160, 'Ancak tövbe edip durumlarını düzeltenler ve gerçeği açıkça ortaya koyanlar (lanetlenmekten) kurtulmuşlardır. Çünkü ben onların tövbelerini kabul ederim. Zira ben tövbeleri çok kabul edenim, çok merhamet edenim.'),
  ('tr.diyanet', 2, 161, 'İnkar edip de o halde ölenler var ya, işte, Allah\'ın, meleklerin, insanların hepsinin laneti onlaradır.'),
  ('tr.diyanet', 2, 162, 'Lanette temellidirler, onlardan azab hafifletilmez ve onların azabı geciktirilmez.'),
  ('tr.diyanet', 2, 163, 'Tanrınız bir tek Tanrıdır. O, merhamet eden, merhametli olandan başka Tanrı yoktur.'),
  ('tr.diyanet', 2, 164, 'Göklerin ve yerin yaratılmasında, gece ile gündüzün birbiri ardınca gelmesinde, insanlara yararlı şeylerle denizde süzülen gemilerde, Allah\'ın gökten indirip yeri ölümünden sonra dirilttiği suda, her türlü canlıyı orada yaymasında, rüzgarları ve yerle gök arasında emre amade duran bulutları döndürmesinde, düşünen kimseler için deliller vardır.'),
  ('tr.diyanet', 2, 165, 'İnsanlar arasında, Allah\'ı bırakıp, O\'na koştukları eşleri tanrı olarak benimseyenler ve onları, Allah\'ı severcesine sevenler vardır. Müminlerin Allah\'ı sevmesi ise hepsinden kuvvetlidir. Zalimler azabı gördükleri zaman, bütün kuvvetin Allah\'a aid bulunacağını ve Allah\'ın azabının şiddetli olduğunu keşke bilselerdi!'),
  ('tr.diyanet', 2, 166, 'Nitekim, kendilerine uyulanlar, azabı görünce uyanlardan uzaklaşacaklar ve aralarındaki bağlar kopacaktır.'),
  ('tr.diyanet', 2, 167, 'Uyanlar: "Keşke bizim için dünyaya bir dönüş olsa da, bizden uzaklaştıkları gibi biz de onlardan uzaklaşsak" derler. Böylece Allah onlara, hasretini çekecekleri işlerini gösterir. Onlar cehennemden çıkmayacaklardır.'),
  ('tr.diyanet', 2, 168, 'Ey İnsanlar! Yeryüzündeki temiz ve helal şeylerden yiyin, şeytana ayak uydurmayın, zira o sizin için apaçık bir düşmandır.'),
  ('tr.diyanet', 2, 169, 'Muhakkak size, kötülüğü, hayasızlığı, Allah\'a karşı da bilmediğiniz şeyi söylemenizi emreder.'),
  ('tr.diyanet', 2, 170, 'Onlara: "Allah\'ın indirdiğine uyun" denilince, "Hayır, atalarımızı yapar bulduğumuz şeye uyarız" derler; ya ataları bir şey akledemeyen ve doğru olmayan kimseler idiyseler?'),
  ('tr.diyanet', 2, 171, 'İnkar edenlerin durumu, çağırma ve bağırmadan başkasını duymayarak haykıran gibidir. Sağırdırlar, dilsizdirler, kördürler, bu yüzden akledemezler.'),
  ('tr.diyanet', 2, 172, 'Ey İnananlar! Sizi rızıklandırdığımızın temizlerinden yiyin; yalnız Allah\'a kulluk ediyorsanız, O\'na şükredin.'),
  ('tr.diyanet', 2, 173, 'Şüphesiz size ölü hayvan etini, kanı, domuz etini, Allah\'tan başkası için kesilen hayvanı haram kılmıştır; fakat, darda kalana, başkasının payına el uzatmamak ve zaruret miktarını aşmamak üzere günah sayılmaz. Çünkü Allah bağışlayandır, merhamet edendir.'),
  ('tr.diyanet', 2, 174, 'Gerçekten, Allah\'ın indirdiği Kitap\'tan bir şeyi gizlemede bulunup onu az bir değere değişenler var ya, onların karınlarına tıkındıkları ancak ateştir. Allah kıyamet günü onlarla konuşmaz ve onları günahlardan arıtmaz. Onlara elem verici azab vardır.'),
  ('tr.diyanet', 2, 175, 'Onlar doğruluk yerine sapıklığı, mağfiret yerine azabı alanlardır.'),
  ('tr.diyanet', 2, 176, 'Bu da, Allah\'ın Kitab\'ı doğru olarak indirmesinden ileri geliyor. Kitap hakkında ayrılığa düşenler doğrusu derin bir çıkmazdadırlar.'),
  ('tr.diyanet', 2, 177, 'Yüzlerinizi doğudan yana ve batıdan yana çevirmeniz iyi olmak demek değildir; Lakin iyi olan, Allah\'a, ahiret gününe, meleklere, Kitap\'a, peygamberlere inanan, O\'nun sevgisiyle, yakınlarına, yetimlere, düşkünlere, yolculara, yoksullara ve köleler uğrunda mal veren, namaz kılan, zekat veren ve ahidleştiklerinde ahidlerine vefa gösterenler, zorda, darda ve savaş alanında sabredenlerdir. İşte onlar doğru olanlardır ve sakınanlar ancak onlardır.'),
  ('tr.diyanet', 2, 178, 'Ey İnananlar! Öldürülenler hakkında size kısas farz kılındı: Hür ile hür insan, köle ile köle ve kadın ile kadın. Öldüren, ölenin kardeşi tarafından bağışlanmışsa, kendisine örfe uymak ve bağışlayana güzellikle diyet ödemek gerekir. Bu, Rabbiniz\'den bir hafifletme ve rahmettir. Bundan sonra tecavüzde bulunana elem verici azab vardır.'),
  ('tr.diyanet', 2, 179, 'Ey akıl sahibleri! Kısasta sizin için hayat vardır. Artık, Allah\'a karşı gelmekten sakınırsınız.'),
  ('tr.diyanet', 2, 180, 'Birinize ölüm geldiği zaman, eğer mal bırakıyorsa, ana babaya, yakınlara, uygun bir tarzda vasiyet etmesi Allah\'a karşı gelmekten sakınanlara bir borç olarak size farz kılındı.'),
  ('tr.diyanet', 2, 181, 'Vasiyeti işittikten sonra değiştiren olursa, bunun günahı değiştirenin üzerinedir. Allah şüphesiz işitir ve bilir.'),
  ('tr.diyanet', 2, 182, 'Vasiyet edenin yanılacağından veya günaha gireceğinden endişe duyan kimse, ilgililerin arasını düzeltirse ona günah yoktur. Allah şüphesiz bağışlar ve merhamet eder.'),
  ('tr.diyanet', 2, 183, 'Ey İnananlar! Oruç, sizden öncekilere farz kılındığı gibi, Allah\'a karşı gelmekten sakınasınız diye, size sayılı günlerde farz kılındı. İçinizden hasta olan veya yolculukta bulunan, tutamadığı günlerin sayısınca diğer günlerde tutar. Oruca dayanamıyanlar, bir düşkünü doyuracak kadar fidye verir. Kim gönülden iyilik yaparsa o iyilik kendisinedir. Oruç tutmanız eğer bilirseniz sizin için hayırlıdır.'),
  ('tr.diyanet', 2, 184, 'Ey İnananlar! Oruç, sizden öncekilere farz kılındığı gibi, Allah\'a karşı gelmekten sakınasınız diye, size sayılı günlerde farz kılındı. İçinizden hasta olan veya yolculukta bulunan, tutamadığı günlerin sayısınca diğer günlerde tutar. Oruca dayanamıyanlar, bir düşkünü doyuracak kadar fidye verir. Kim gönülden iyilik yaparsa o iyilik kendisinedir. Oruç tutmanız eğer bilirseniz sizin için hayırlıdır.'),
  ('tr.diyanet', 2, 185, 'Ramazan ayı, ki onda Kuran, insanlara yol gösterici ve doğruyu yanlıştan ayırıcı belgeler olarak indirildi. Sizden bu ayı idrak eden, onda oruç tutsun; hasta veya yolculukta olan, tutamadığı günlerin sayısınca diğer günlerde tutsun. Allah size kolaylık ister, zorluk istemez. Bu kolaylıkları, sayıyı tamamlamanız ve size yol gösterdiğine karşılık O\'nu ululamanız için meşru kılmıştır; ola ki şükredersiniz.'),
  ('tr.diyanet', 2, 186, 'Kullarım sana Beni sorarlarsa, bilsinler ki Ben, şüphesiz onlara yakınım. Benden isteyenin, dua ettiğinde duasını kabul ederim. Artık onlar da davetimi kabul edip Bana inansınlar ki doğru yolda yürüyenlerden olsunlar.'),
  ('tr.diyanet', 2, 187, 'Oruç tuttuğunuz günlerin gecesi kadınlarınıza yaklaşmanız size helal kılındı, onlar sizin örtünüz, siz de onların örtülerisiniz. Allah, nefsinize güvenemiyeceğinizi biliyordu, bu sebeple tevbenizi kabul edip sizi affetti; artık onlara yaklaşabilirsiniz. Allah\'ın sizin için takdir ettiğini dileyin. Tan yerinde, beyaz iplik siyah iplikten sizce ayırdedilinceye kadar, yiyin için, sonra orucu geceye kadar tamamlayın. Mescidlerde itikafa çekildiğinizde kadınlarınıza yaklaşmayın. Allah insanlara yasaklardan sakınsınlar diye ayetlerini böylece apaçık bildirir.'),
  ('tr.diyanet', 2, 188, 'Aranızda mallarınızı haksızlıkla yemeyin; bildiğiniz halde günaha girerek insanların mallarından bir kısmını yemek için onu hakimlere aktarmayın.'),
  ('tr.diyanet', 2, 189, 'Sana hilal halindeki ayları sorarlar. De ki: "Onlar, insanların ve hac vakitlerinin ölçüsüdür". Evlere arkalarından girmeniz iyilik değildir; iyi kimse kötülükten sakınan kimsedir. Evlere kapılarından girin; Allah\'tan sakının ki muradınıza erersiniz.'),
  ('tr.diyanet', 2, 190, 'Sizinle savaşanlarla Allah yolunda savaşın, aşırı gitmeyin; doğrusu Allah aşırı gidenleri sevmez.'),
  ('tr.diyanet', 2, 191, 'Onları bulduğunuz yerde öldürün. Sizi çıkardıkları yerden siz de onları çıkarın. Fitne çıkarmak, adam öldürmekten daha kötüdür. Mescidi Haram\'ın yanında, onlar savaşmadıkça siz de onlarla savaşmayın. Sizinle savaşırlarsa onları öldürün. İnkar edenlerin cezası böyledir.'),
  ('tr.diyanet', 2, 192, 'Vazgeçerlerse onları bağışlayın; şüphesiz Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 2, 193, 'Fitne kalmayıp, yalnız Allah\'ın dini ortada kalana kadar onlarla savaşın. Eğer vazgeçerlerse sataşmayın. Zulmedenlerden başkasına düşmanlık yoktur.'),
  ('tr.diyanet', 2, 194, 'Hürmetli ay, hürmetli aya mukabildir, hürmetler karşılıklıdır; o halde, size tecavüz edene (saldırana), size saldırdıkları gibi saldırın. Allah\'tan sakının ve Allah\'ın sakınanlarla beraber olduğunu bilin.'),
  ('tr.diyanet', 2, 195, 'Allah yolunda sarf edin, kendinizi kendi elinizle tehlikeye atmayın, işlerinizi iyi yapın. Şüphesiz Allah iyi iş yapanları sever.'),
  ('tr.diyanet', 2, 196, 'Başladığınız hac ve umreyi Allah için tamamlayın. Alıkonursanız, kolayınıza gelen bir kurban gönderin. Kurban, yerine ulaşıncaya kadar, başlarınızı tıraş etmeyin. İçinizde hasta olan veya başından rahatsız bulunan varsa fidye olarak ya oruç tutması, ya sadaka vermesi ya da kurban kesmesi gerekir. Güven içinde olursanız, hacca kadar umreden faydalanabilen kimseye kolayına gelen bir kurban kesmek, bulamayana, hac esnasında üç gün ve döndüğünüzde yedi gün, ki o tam on gündür oruç tutmak gerekir. Bu, ailesi Mescidi Haram\'da oturmayan kimseler içindir. Allah\'tan sakının ve Allah\'ın cezasının şiddetli olacağını bilin.'),
  ('tr.diyanet', 2, 197, 'Hac bilinen aylardadır. O aylarda hacca girişen kimse bilmelidir ki, hacda kadına yaklaşmak, sövüşmek, dövüşmek yoktur. Ne iyilik yaparsanız Allah onu bilir. Kendinize azık edinin, şüphe yok ki azığın en iyisi Allah korkusudur. Ey akıl sahibleri! Benden korkun.'),
  ('tr.diyanet', 2, 198, 'Rabbiniz\'den refah istemenizde bir engel yoktur. Arafat\'tan indiğinizde, Allah\'ı Meşari Haram\'da anın; O\'nu, size gösterdiği şekilde zikredin. Nitekim siz önceleri hiç şüphesiz sapıklardandınız.'),
  ('tr.diyanet', 2, 199, 'Sonra, insanların toplu olarak akın ettiği yerden, siz de akın edin. Allah\'tan mağfiret dileyin. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 2, 200, 'Hac ibadetinizi bitirdiğinizde, babalarınızı andığınız gibi, hatta ondan daha kuvvetli bir anışla Allah\'ı anın. "Rabbimiz! Bize sadece dünyada ver" diyen insanlar vardır, öylesine, ahirette bir pay yoktur.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 2, 201, '"Rabbimiz! Bize dünyada iyiyi, ahirette de iyiyi ver, bizi ateşin azabından koru" diyenler vardır.'),
  ('tr.diyanet', 2, 202, 'İşte onlara, kazançlarından ötürü karşılık vardır. Allah hesabı çabuk görür.'),
  ('tr.diyanet', 2, 203, 'Allah\'ı sayılı günlerde anın. Günahtan sakınan kimseye, acele edip, Mina\'daki ibadeti iki günde bitirirse günah yoktur, geri kalsa da günah yoktur. Allah\'tan sakının. O\'nun katında toplanacağınızı bilin.'),
  ('tr.diyanet', 2, 204, 'Dünya hayatına dair konuşması senin hoşuna giden, pek azılı düşman iken, kalbinde olana Allah\'ı şahid tutan, işbaşına geçince, yeryüzünde bozgunculuk yapmaya, ekin ve nesli yok etmeğe çabalayan insanlar vardır. Allah bozgunculuğu sevmez.'),
  ('tr.diyanet', 2, 205, 'Dünya hayatına dair konuşması senin hoşuna giden, pek azılı düşman iken, kalbinde olana Allah\'ı şahid tutan, işbaşına geçince, yeryüzünde bozgunculuk yapmaya, ekin ve nesli yok etmeğe çabalayan insanlar vardır. Allah bozgunculuğu sevmez.'),
  ('tr.diyanet', 2, 206, 'Ona: "Allah\'tan sakın" denince, gururu kendisine günah işletir, artık ona cehennem yetişir, ne kötü yataktır!..'),
  ('tr.diyanet', 2, 207, 'İnsanlar arasında, Allah\'ın rızasını kazanmak için canını verenler vardır. Allah kullarına karşı şefkatlidir.'),
  ('tr.diyanet', 2, 208, 'Ey İnananlar! Hep birden barışa girin, şeytana ayak uydurmayın, o sizin apaçık düşmanınızdır.'),
  ('tr.diyanet', 2, 209, 'Size belgeler geldikten sonra kayarsanız, biliniz ki Allah güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 2, 210, 'Onlar, bulut gölgeleri içinde, Allah\'ın azabının ve meleklerin tepelerine inip işin bitmesini mi bekliyorlar? Bütün işler Allah\'a dönecektir.'),
  ('tr.diyanet', 2, 211, 'İsrailoğullarına sor; onlara apaçık nice ayetler verdik, Allah\'ın nimetini, kendisine geldikten sonra kim değiştirirse, bilsin ki, Allah\'ın cezası şüphesiz şiddetlidir.'),
  ('tr.diyanet', 2, 212, 'İnkar edenlere, dünya hayatı güzel görünür, onlar, inananlarla alay ederler, oysa, Allah\'a karşı gelmekten sakınanlar kıyamet günü onların üstünde olacaklardır. Allah dilediğini hesabsız şekilde rızıklandırır.'),
  ('tr.diyanet', 2, 213, 'İnsanlar bir tek ümmetti. Allah peygamberleri müjdeci ve uyarıcı olarak gönderdi; insanların ayrılığa düşecekleri hususlarda aralarında hüküm vermek için onlarla birlikte hak Kitaplar indirdi. Ancak Kitap verilenler, kendilerine belgeler geldikten sonra, aralarındaki ihtiras yüzünden onda ayrılığa düştüler. Allah, inananları, ayrılığa düştükleri gerçeğe kendi izni ile eriştirdi. Allah dilediğini doğru yola eriştirir.'),
  ('tr.diyanet', 2, 214, 'Sizden önce gelenlerin durumu sizin başınıza gelmeden cennete gireceğinizi mi zannettiniz? Peygamber ve onunla beraber müminler: "Allah\'ın yardımı ne zaman?" diyecek kadar darlığa ve zorluğa uğramışlar ve sarsılmışlardı; iyi bilin ki Allah\'ın yardımı şüphesiz yakındır.'),
  ('tr.diyanet', 2, 215, 'Sana, ne sarfedeceklerini sorarlar, de ki: "Sarfedeceğiniz mal, ana baba, yakınlar, yetimler, düşkünler, yolcular içindir. Yaptığınız her iyiliği Allah şüphesiz bilir".'),
  ('tr.diyanet', 2, 216, 'Savaş, hoşunuza gitmediği halde size farz kılındı. İhtimal ki hoşlanmadığınız şey sizin iyiliğinizedir ve ihtimal ki sevdiğiniz bir şey sizin kötülüğünüzedir. Siz bilmezsiniz, Allah bilir.'),
  ('tr.diyanet', 2, 217, 'Sana hürmet edilen ayı, o aydaki savaşı sorarlar. De ki: "O ayda savaşmak büyük suçtur. Allah yolundan alıkoymak, O\'nu inkar etmek, Mescidi Haram\'a engel olmak ve halkını oradan çıkarmak Allah katında daha büyük suçtur. Fitne çıkarmak ise öldürmekten daha büyüktür". Güçleri yeterse, dininizden döndürünceye kadar sizinle savaşa devam ederler. İçinizden dininden dönüp kafir olarak ölen olursa, bunların işleri dünya ve ahirette boşa gitmiş olur. İşte cehennemlikler onlardır, onlar orada temellidirler.'),
  ('tr.diyanet', 2, 218, 'İnananlar, hicret edenler ve Allah yolunda cihad edenler Allah\'ın rahmetini umarlar. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 2, 219, 'Sana içki ve kumarı sorarlar, de ki: "İkisinde hem büyük günah ve hem insanlara bazı faydalar vardır. Günahları faydasından daha büyüktür". Ne sarfedeceklerini sana sorarlar, de ki: "Artanı". Böylece Allah, dünya ve ahiret hususunda düşünesiniz diye size ayetleri açıklar.'),
  ('tr.diyanet', 2, 220, 'Sana yetimleri sorarlar, de ki: "Onların işlerini düzeltmek hayırlıdır". Eğer onlarla bir arada yaşarsanız, artık onlar sizin kardeşlerinizdir. Allah düzeltenden bozanı ayırdetmesini bilir. Allah dileseydi sizi zora sokardı. Allah şüphesiz güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 2, 221, 'Allah\'a eş koşan kadınlarla onlar imana gelinceye kadar evlenmeyin. İnanan bir cariye, hoşunuza gitse de ortak koşan bir kadından daha iyidir. İnanmalarına kadar; ortak koşan erkeklerle mümin kadınları evlendirmeyin. İnanan bir köle, hoşunuza gitmiş olsa da, ortak koşan bir erkekten daha iyidir. İşte onlar ateşe çağırırlar, Allah ise izniyle cennete ve mağfirete çağırır ve insanlara ibret alsınlar diye ayetlerini açıklar.'),
  ('tr.diyanet', 2, 222, 'Sana, kadınların aybaşı hali hakkında da sorarlar, de ki: "O bir ezadır (rahatsızlıktır)". Aybaşı halinde iken kadınlardan el çekin, temizlenmelerine kadar onlara yaklaşmayın. Temizlendikleri zaman, Allah\'ın size buyurduğu yoldan yaklaşın. Allah şüphesiz daima tevbe edenleri sever, temizlenenleri de sever.'),
  ('tr.diyanet', 2, 223, 'Kadınlarınız sizin tarlanızdır, tarlanıza istediğiniz gibi gelin. İstikbal için hazırlıklı olun, Allah\'tan sakının. O\'na, hiç şüphesiz kavuşacağınızı bilin, bunu inananlara müjdele.'),
  ('tr.diyanet', 2, 224, 'İnsanların arasını düzeltmeniz, günahtan sakınmanız ve iyi olmanız için, Allah\'a yaptığınız yeminleri engel kılmayın, Allah işitir ve bilir.'),
  ('tr.diyanet', 2, 225, 'Allah sizi rastgele yeminlerinizden dolayı değil, fakat kalblerinizin kasdettiği yeminlerden dolayı sorumlu tutar. Allah bağışlayandır, Halim\'dir.'),
  ('tr.diyanet', 2, 226, 'Kadınlarına yaklaşmamaya yemin edenler, dört ay bekleyebilirler; eğer yeminlerinden dönerlerse, bilsinler ki Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 2, 227, 'Şayet boşanmaya kararlı iseler, bilsinler ki Allah şüphesiz işitir ve bilir.'),
  ('tr.diyanet', 2, 228, 'Boşanan kadınlar, kendi kendilerine üç aybaşı hali beklerler, eğer Allah\'a ve ahiret gününe inanmışlarsa, rahimlerinde Allah\'ın yarattığını gizlemeleri kendilerine helal değildir. Kocaları bu arada barışmak isterlerse, karılarını geri almakta daha çok hak sahibidirler. Kadınların hakları, örfe uygun bir şekilde vazifelerine denktir. Erkeklerin onlardan bir üstün derecesi vardır. Allah güçlüdür. Hakim\'dir.'),
  ('tr.diyanet', 2, 229, 'Boşanma iki defadır. Ya iyilikle tutma ya da iyilik yaparak bırakmadır. İkisi Allah\'ın yasalarını koruyamamaktan korkmadıkça kadınlara verdiklerinizden (mehirden) bir şey almanız size helal değildir. Eğer Allah\'ın yasalarını ikisi koruyamıyacaklar diye korkarsanız, o zaman kadının fidye vermesinde (mehrinden vazgeçerse) ikisine de günah yoktur. Bunlar Allah\'ın yasalarıdır, onları bozmayın. Allah\'ın yasalarını bozanlar ancak zalimlerdir.'),
  ('tr.diyanet', 2, 230, 'Bundan sonra kadını boşarsa, kadın başka birisiyle evlenmedikçe bir daha kendisine helal olmaz. Eğer ikinci koca da onu boşarsa, Allah\'ın yasalarını koruyacaklarını sanırlarsa eski karı kocanın birbirlerine dönmelerine bir engel yoktur. Bunlar, bilenkimseler için Allah\'ın açıkladığı yasalardır.'),
  ('tr.diyanet', 2, 231, 'Kadınları boşadığınızda, müddetleri sona ererken, onları güzellikle tutun, ya da güzellikle bırakın, haklarına tecavüz etmek için onlara zararlı olacak şekilde tutmayın; böyle yapan şüphesiz kendisine yazık etmiş olur. Allah\'ın ayetlerini de alaya almayın; Allah\'ın üzerinize olan nimetini, öğüt vermek üzere size indirdiği Kitap ve hikmeti anın, Allah\'tan sakının, Allah\'ın her şeyi bildiğini bilin.'),
  ('tr.diyanet', 2, 232, 'Kadınları boşadığınızda, müddetleri sona ermişse, kocaları ile birbirleriyle güzellikle anlaşmışlarsa evlenmelerine engel olmayın. İçinizden Allah\'a ve ahiret gününe inanan kimse bundan ibret alır. Bu sizin için daha nezih ve daha paktır. Allah bilir, siz bilmezsiniz.'),
  ('tr.diyanet', 2, 233, 'Anneler çocuklarını, emzirmeyi tamamlatmak isteyen baba için, tam iki sene emzirirler. Anaların yiyecek ve giyeceğini uygun bir şekilde sağlamak çocuk kendisinin olan babaya borçtur. Herkese ancak gücü nisbetinde teklifte bulunulur. Ana çocuğundan, çocuk kendisinin olan baba da çocuğundan dolayı zarara sokulmasın. Mirasçıya da aynı şeyi yapmak borçtur. Ana baba aralarında danışarak ve anlaşarak sütten kesmek isterlerse, ikisine de sorumluluk yoktur. Çocuklarınızı sütanneye emzirtmek isterseniz, vereceğinizi örfe uygun bir şekilde öderseniz, size sorumluluk yoktur. Allah\'tan sakının, yaptıklarınızı gördüğünü bilin.'),
  ('tr.diyanet', 2, 234, 'İçinizden ölenlerin bırakmış olduğu eşler kendi kendilerine dört ay on gün beklerler; müddetleri sona erdiğinde, onların kendi haklarında uygun şekilde yaptıklarından dolayı size sorumluluk yoktur. Allah işlediklerinizden haberdardır.'),
  ('tr.diyanet', 2, 235, 'Böyle kadınlara kapalı bir şekilde evlenme teklif etmenizde veya içinizden onlarla evlenmeyi geçirmenizde size sorumluluk yoktur. Allah onları anacağınızı bilir. Sakın meşru sözler dışında onlarla gizlice sözleşmeyin, müddet sona erene kadar nikah akdine kalkışmayın. İçinizde olanı Allah\'ın bildiğini bilin de O\'ndan çekinin. Allah\'ın bağışlayan ve Halim olduğunu bilin.'),
  ('tr.diyanet', 2, 236, 'Kadınlara el sürmeden ve mehirlerini biçmeden onları boşarsanız size sorumluluk yoktur. Onları zengin kendi çapına, fakir kendi çapına uygun bir şekilde faydalandırın. Bu iyi davrananların şanına yakışır bir borçtur.'),
  ('tr.diyanet', 2, 237, 'Eğer onlara mehir biçer de el sürmeden onları boşarsanız, kendileri veya nikah akdi elinde olan erkeğin bağışlaması hali müstesna biçtiğinizin yarısını verin, bağışlamanız Allah\'tan sakınmaya daha uygundur. Aranızdaki iyiliği unutmayın. Allah şüphesiz işlediklerinizi görür.'),
  ('tr.diyanet', 2, 238, 'Namazlara ve orta namaza devam edin; gönülden boyun eğerek Allah için namaza durun.'),
  ('tr.diyanet', 2, 239, 'Eğer korkarsanız, yaya yahut binekte iken kılın, güvene erişince, bilmediklerinizi öğrettiği gibi Allah\'ı anın.'),
  ('tr.diyanet', 2, 240, 'İçinizden ölüp, eşler bırakacak olanlar, evlerinden çıkarılmaksızın, senesine kadar eşlerinin geçimini sağlayacak şeyi vasiyet etsinler; eğer çıkarlarsa kendilerinin meşru olarak yaptıklarından dolayı size sorumluluk yoktur. Allah güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 2, 241, 'Boşanan kadınları, haksızlıktan sakınanlara bir borç olmak üzere, uygun bir surette faydalandırma vardır.'),
  ('tr.diyanet', 2, 242, 'Allah ayetlerini düşünesiniz diye böylece açıklamaktadır.'),
  ('tr.diyanet', 2, 243, 'Binlerce kişinin memleketlerinden ölüm korkusuyla çıktıklarını görmedin mi? Allah onlara "Ölün" dedi. Sonra onları diriltti. Allah insanlara bol nimet verir, fakat insanların çoğu şükretmezler.'),
  ('tr.diyanet', 2, 244, 'Allah yolunda savaşın; bilin ki Allah işitir ve bilir.'),
  ('tr.diyanet', 2, 245, 'Allah\'a, kat kat karşılığını arttıracağı güzel bir ödünç takdiminde kim bulunur? Allah hem darlaştırır, hem bollaştırır; O\'na döneceksiniz.'),
  ('tr.diyanet', 2, 246, 'Musa\'dan sonra İsrailoğullarının ileri gelenlerini görmedin mi? Peygamberlerinden birine, "Bize bir hükümdar gönder de Allah yolunda savaşalım" demişlerdi. "Ya savaş size farz kılındığında gitmeyecek olursanız?" demişti. "Memleketimizden ve çocuklarımızdan uzaklaştırıldığımıza göre niye Allah yolunda savaşmıyalım?" demişlerdi. Ama savaş onlara farz kılınınca, az bir kısmı müstesna yüz cevirdiler. Allah zalimleri bilir.'),
  ('tr.diyanet', 2, 247, 'Peygamberleri onlara "Allah size şüphesiz, Talut\'u hükümdar olarak gönderdi" dedi. "Biz hükümdarlığa ondan layık iken ve ona malca da bir bolluk verilmemişken bize hükümdar olmağa o nasıl layık olabilir?" dediler, "Doğrusu Allah size onu seçti, bilgice ve vücutça gücünü artırdı" dedi. Allah mülkü dilediğine verir. Allah her şeyi kaplar ve bilir.'),
  ('tr.diyanet', 2, 248, 'Peygamberleri onlara, "Onun hükümdarlığının alameti, size sandığın gelmesidir, onda Rabbinizden gelen gönül rahatlığı ve Musa ailesinin ve Harun ailesinin bıraktıklarından kalanlar var; onu melekler taşır, eğer inanmışsanız bunda sizin için delil vardır" dedi.'),
  ('tr.diyanet', 2, 249, 'Talut orduyla birlikte ayrıldıktan sonra, "Doğrusu Allah sizi bir ırmakla deneyecektir, ondan içen benden değildir, onu tatmayan eliyle sadece bir avuç avuçlayan müstesna şüphesiz bendendir" dedi. Onlardan pek azı hariç, sudan içtiler. Kendisi ve kendisiyle olan inananlar ırmağı geçince, "Bugün Calut ve ordusuna karşı koyacak gücümüz yok" dediler. Kendilerinin Allah\'a kavuşacağını bilenler ise: "Nice az topluluk çok topluluğa Allah\'ın izniyle üstün gelmiştir, Allah sabredenlerle beraberdir" dediler.'),
  ('tr.diyanet', 2, 250, 'Calut ve ordusuna karşı çıktıklarında, "Rabbimiz! Bize sabır ver, sebatımızı artır, inkar eden millete karşı bize yardım et" dediler.'),
  ('tr.diyanet', 2, 251, 'Onları Allah\'ın izniyle bozguna uğrattılar; Davud Calut\'u öldürdü, Allah Davud\'a hükümranlık ve hikmet verdi ve ona dilediğinden öğretti. Allah\'ın insanları birbiriyle savması olmasaydı yeryüzünün düzeni bozulurdu. Fakat Allah alemlere lütufkardır.'),
  ('tr.diyanet', 2, 252, 'İşte bunlar Allah\'ın ayetleridir. Biz onları sana doğru olarak okuyoruz. Şüphesiz sen peygamberlerden birisin.'),
  ('tr.diyanet', 2, 253, 'İşte bu peygamberlerden bir kısmını diğerlerinden üstün kıldık. Onlardan Allah\'ın kendilerine hitabettiği, derecelerle yükselttikleri vardır. Meryem oğlu İsa\'ya belgeler verdik, onu Ruhul Kudüs\'le destekledik. Allah dileseydi, belgeler kendilerine geldikten sonra, peygamberlerin ardından birbirlerini öldürmezlerdi. Fakat ayrılığa düştüler, kimi inandı, kimi inkar etti. Allah dileseydi birbirlerini öldürmezlerdi, lakin Allah istediğini yapar.'),
  ('tr.diyanet', 2, 254, 'Ey inananlar! Alışverişin, dostluğun, şefaatin olmayacağı günün gelmesinden önce sizi rızıklandırdığımızdan hayra sarfedin. İnkar edenler ancak yazık edenlerdir.'),
  ('tr.diyanet', 2, 255, 'Allah, O\'ndan başka tanrı olmayan, kendisini uyuklama ve uyku tutmayan, diri, her an yaratıklarını gözetip durandır. Göklerde olan ve yerde olan ancak O\'nundur. O\'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini ve işleyeceklerini bilir, dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Hükümranlığı gökleri ve yeri kaplamıştır, onların gözetilmesi O\'na ağır gelmez. O yücedir, büyüktür.'),
  ('tr.diyanet', 2, 256, 'Dinde zorlama yoktur; Artık hak ile batıl iyice ayrılmıştır. Tağutu (saptırıcıları) inkar edip Allah\'a inanan kimse, kopmak bilmeyen sağlam bir kulpa sarılmıştır. Allah işitendir, bilendir.'),
  ('tr.diyanet', 2, 257, 'Allah inananların dostudur, onları karanlıklardan aydınlığa çıkarır. İnkar edenlerin ise dostları tağuttur. Onları aydınlıktan karanlıklara sürüklerler. İşte onlar cehennemliklerdir, onlar orada temelli kalacaklardır.'),
  ('tr.diyanet', 2, 258, 'Allah kendisine mülk verdi diye İbrahim ile Rabbi hakkında tartışanı görmedin mi? İbrahim: "Rabbim, dirilten ve öldürendir" demişti. "Ben de diriltir ve öldürürüm" dedi; İbrahim, "Şüphesiz Allah güneşi doğudan getiriyor, sen de batıdan getirsene" dedi. İnkar eden şaşırıp kaldı. Allah zulmeden kimseleri doğru yola eriştirmez.'),
  ('tr.diyanet', 2, 259, 'Yahut altı üstüne gelmiş bir kasabaya uğrayan kimseyi görmedin mi? "Allah burayı ölümünden sonra acaba nasıl diriltecek?" dedi. Bunun üzerine Allah onu yüz yıl ölü bıraktı, sonra diriltti, "Ne kadar kaldın?" dedi, "Bir gün veya bir günden az kaldım" dedi, "Hayır yüz yıl kaldın, yiyeceğine içeceğine bak, bozulmamış; eşeğine bak ve hem seni insanlar için bir ibret kılacağız, kemiklere bak, onları nasıl birleştirip, sonra onlara et giydiriyoruz" dedi; bu ona apaçık belli olunca, "Artık Allah\'ın her şeye Kadir olduğuna inanmış bulunuyorum" dedi.'),
  ('tr.diyanet', 2, 260, 'İbrahim: "Rabbim! Ölüleri nasıl dirilttiğini bana göster" dediğinde, "İnanmıyor musun?" deyince de, "Hayır öyle değil, fakat kalbim iyice kansın" demişti. "Öyleyse dört çeşit kuş al, onları kendine alıştır, sonra onları parçalayıp her dağın üzerine bir parça koy, sonra onları çağır; koşarak sana gelirler. O halde Allah\'ın güçlü ve Hakim olduğunu bil" demişti.'),
  ('tr.diyanet', 2, 261, 'Mallarını Allah yolunda sarfedenlerin durumu, her başağında yüz tane olmak üzere yedi başak veren tanenin durumu gibidir. Allah dilediğine kat kat verir. Allah\'ın lütfü geniştir, O her şeyi bilendir.'),
  ('tr.diyanet', 2, 262, 'Mallarını Allah yolunda sarfedip sonra sarfettikleri şeyin ardından başa kakmayan ve eza etmeyenlerin ecirleri Rablerinin katındadır. Onlara korku yoktur ve onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 2, 263, 'Güzel bir söz ve bağışlama, peşinden eza gelen bir sadakadan daha iyidir. Allah müstağnidir, Halim\'dir.'),
  ('tr.diyanet', 2, 264, 'Ey İnananlar! Allah\'a ve ahiret gününe inanmayıp, insanlara gösteriş için malını sarfeden kimse gibi, sadakalarınızı başa kakma ve eza etmekle boşa çıkarmayın. Onun durumu, üzerinde toprak bulunan kayanın durumu gibidir, üzerine bol yağmur yağdığındaonu cascavlak bırakır. Kazandıklarından hiçbir şey elde edemezler. Allah inkar eden kimseleri doğru yola eriştirmez.'),
  ('tr.diyanet', 2, 265, 'Allah\'ın rızasını kazanmak ve kalblerini sağlamlaştırmak için mallarını sarfedenlerin durumu, yüksekçe bir tepede bulunan, bol yağmur aldığında yemişlerini iki kat veren, bol yağmur yağmasa bile çisentisi düşen bir bahçenin durumu gibidir. Allah işlediklerinizi görür.'),
  ('tr.diyanet', 2, 266, 'Hangi biriniz, kendisi ihtiyarlamış ve çocukları da güçsüzken, altlarından ırmaklar akan, hurma, üzüm ve her çeşit meyveleri bulunan bahçesinin, ateşli bir kasırganın kopmasıyla yanmasını ister? Düşünesiniz diye Allah size ayetlerini böylece açıklar.'),
  ('tr.diyanet', 2, 267, 'Ey İnananlar! Kazandıklarınızın temizlerinden ve size yerden çıkardıklarımızdan sarfedin; iğrenmeden alamıyacağınız pis şeyleri vermeye kalkmayın. Allah\'ın müstağni ve övülmeye layık olduğunu bilin.'),
  ('tr.diyanet', 2, 268, 'Şeytan sizi fakirlikle korkutarak cimriliği ve hayasızlığı emreder; Allah ise kendisinden mağfiret ve bol nimet vadeder. Allah\'ın lütfü boldur, O her şeyi bilir.'),
  ('tr.diyanet', 2, 269, 'Hikmeti dilediğine verir. Kime hikmet verilmişse şüphesiz ona çokça hayır verilmiştir. Bundan ancak akıl sahipleri ibret alır.'),
  ('tr.diyanet', 2, 270, 'Sarfettiğiniz harcı ve adadığınız adağı şüphesiz Allah bilir. Zulmedenlerin hiç yardımcıları yoktur.'),
  ('tr.diyanet', 2, 271, 'Sadakaları açıkça verirseniz o ne güzel! Eğer onları yoksullara gizlice verirseniz sizin için daha iyidir. Allah onları kötülüklerinizden bir kısmına karşı tutar. Allah işlediklerinizden haberdardır.'),
  ('tr.diyanet', 2, 272, 'Onların doğru yola iletilmeleri sana düşmez, fakat Allah dilediğini doğru yola eriştirir. Sarfettiğiniz iyi şey kendinizedir, zaten ancak Allah\'ın rızasını kazanmak için sarfedersiniz. Sarfettiğiniz iyi bir şeyin karşılığı haksızlığa uğratılmaksızın size verilir.'),
  ('tr.diyanet', 2, 273, 'Sadakalarınızı, kendilerini Allah yoluna adayıp yeryüzünde dolaşamayanlara, hayalarından dolayı, kendilerini tanımayanların zengin saydıkları yoksullara verin. Onları yüzlerinden tanırsın, insanlardan yüzsüzlük ederek bir şey istemezler. Sarfettiğiniz iyi bir şeyi Allah şüphesiz bilir.'),
  ('tr.diyanet', 2, 274, 'Gece gündüz, açık gizli, mallarını sarfedenlerin mükafatlarını Rab\'leri verecektir. Onlara korku yoktur ve onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 2, 275, 'Faiz yiyenler mahşerde ancak şeytanın çarptığı kimsenin kalktığı gibi kalkarlar. Bu, onların, "Zaten alışveriş de faiz gibidir" demelerindendir. Oysa Allah alışverişi helal, faizi haram kıldı. Kime Rabb\'inden bir öğüt gelir de faizcilikten geri durursa, geçmişi kendisinedir, onun işi Allah\'a aittir. Kim faizciliğe dönerse, işte onlar cehennemliktir, onlar orada temelli kalacaklardır.'),
  ('tr.diyanet', 2, 276, 'Allah faizi eksiltir, sadakaları bereketlendirir. Allah pek nankör olan hiçbir günahkarı sevmez.'),
  ('tr.diyanet', 2, 277, 'İnanıp yararlı işler işleyenlerin, namaz kılıp, zekat verenlerin Rab\'leri katında ecirleri vardır. Onlara korku yoktur ve onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 2, 278, 'Ey İnananlar! Allah\'tan sakının, inanmışsanız, faizden arta kalmış hesabdan vazgeçin.'),
  ('tr.diyanet', 2, 279, 'Böyle yapmazsanız, bunun Allah\'a ve Peygamberine karşı açılmış bir savaş olduğunu bilin. Eğer tevbe ederseniz sermayeniz sizindir. Böylece haksızlık etmemiş ve haksızlığa uğramamış olursunuz.'),
  ('tr.diyanet', 2, 280, 'Borçlu darda ise, eli genişleyinceye kadar ona mühlet verin. Bilmiş olsanız borcu bağışlamanız sizin için daha hayırlıdır.'),
  ('tr.diyanet', 2, 281, 'Allah\'a döneceğiniz ve sonra haksızlığa uğramadan herkesin kazancının kendisine eksiksiz verileceği günden korkunuz.'),
  ('tr.diyanet', 2, 282, 'Ey İnananlar! Birbirinize belirli bir süre için borçlandığınız zaman onu yazınız. İçinizden bir katip doğru olarak yazsın; katip onu Allah\'ın kendisine öğrettiği gibi yazmaktan çekinmesin, yazsın. Borçlu olan da yazdırsın, Rabbi olan Allah\'tan sakınsın, ondan bir şey eksiltmesin. Eğer borçlu, aptal veya aciz, ya da yazdıramıyacak durumda ise, velisi, doğru olarak yazdırsın. Erkeklerinizden iki şahid tutun; eğer iki erkek bulunmazsa, şahidlerden razı olacağınız bir erkek, biri unuttuğunda diğeri ona hatırlatacak iki kadın olabilir. Şahidler çağırıldıklarında çekinmesinler. Borç büyük veya küçük olsun, onu süresiyle beraber yazmaya üşenmeyin; bu, Allah katında en doğru, şahidlik için en sağlam ve şüphelenmenizden en uzak olandır. Ancak aranızdaki alışveriş peşin olursa, onu yazmamanızda size bir sorumluluk yoktur. Alışveriş yaptığınızda şahid tutun. Katibe de şahide de zarar verilmesin; eğer zarar verirseniz, o zaman doğru yoldan çıkmış olursunuz. Allah\'tan sakının, Allah size öğretiyor; Allah her şeyi bilir.'),
  ('tr.diyanet', 2, 283, 'Eğer yolculukta olup katip bulamazsanız alınan rehin yeter. Şayet birbirinize güvenirseniz, güvenilen kimse borcunu ödesin. Rabbi olan Allah\'tan sakınsın. Şahidliği gizlemeyin, onu kim gizlerse şüphesiz kalbi günah işlemiş olur. Allah işlediklerinizi bilir.'),
  ('tr.diyanet', 2, 284, 'Göklerde ve yerde olanlar Allah\'ındır. İçinizdekini açıklasanız da gizleseniz de Allah sizi onunla hesaba çeker ve dilediğini bağışlar, dilediğine azabeder. Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 2, 285, 'Peygamber ve inananlar, ona Rabb\'inden indirilene inandı. Hepsi Allah\'a, meleklerine, kitaplarına, peygamberlerine inandı. "Peygamberleri arasından hiçbirini ayırdetmeyiz, işittik, itaat ettik, Rabbimiz! Affını dileriz, dönüş Sanadır" dediler.'),
  ('tr.diyanet', 2, 286, 'Allah kişiye ancak gücünün yeteceği kadar yükler; kazandığı iyilik lehine, ettiği kötülük de aleyhinedir. Rabbimiz! Eğer unutacak veya yanılacak olursak bizi sorumlu tutma. Rabbimiz bizden öncekilere yüklediğin gibi, bize de ağır yük yükleme. Rabbimiz! Bize gücümüzün yetmeyeceği şeyi taşıtma, bizi affet, bizi bağışla, bize acı. Sen Mevlamızsın, kafirlere karşı bize yardım et.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 2, 1, 'Alif laam miim.'),
  ('id.indonesian', 2, 2, 'Kitab (Al Quran) ini tidak ada keraguan padanya; petunjuk bagi mereka yang bertakwa,'),
  ('id.indonesian', 2, 3, '(yaitu) mereka yang beriman kepada yang ghaib, yang mendirikan shalat, dan menafkahkan sebahagian rezeki yang Kami anugerahkan kepada mereka.'),
  ('id.indonesian', 2, 4, 'dan mereka yang beriman kepada Kitab (Al Quran) yang telah diturunkan kepadamu dan Kitab-kitab yang telah diturunkan sebelummu, serta mereka yakin akan adanya (kehidupan) akhirat.'),
  ('id.indonesian', 2, 5, 'Mereka itulah yang tetap mendapat petunjuk dari Tuhan mereka, dan merekalah orang-orang yang beruntung.'),
  ('id.indonesian', 2, 6, 'Sesungguhnya orang-orang kafir, sama saja bagi mereka, kamu beri peringatan atau tidak kamu beri peringatan, mereka tidak juga akan beriman.'),
  ('id.indonesian', 2, 7, 'Allah telah mengunci-mati hati dan pendengaran mereka, dan penglihatan mereka ditutup. Dan bagi mereka siksa yang amat berat.'),
  ('id.indonesian', 2, 8, 'Di antara manusia ada yang mengatakan: "Kami beriman kepada Allah dan Hari kemudian," pada hal mereka itu sesungguhnya bukan orang-orang yang beriman.'),
  ('id.indonesian', 2, 9, 'Mereka hendak menipu Allah dan orang-orang yang beriman, padahal mereka hanya menipu dirinya sendiri sedang mereka tidak sadar.'),
  ('id.indonesian', 2, 10, 'Dalam hati mereka ada penyakit, lalu ditambah Allah penyakitnya; dan bagi mereka siksa yang pedih, disebabkan mereka berdusta.'),
  ('id.indonesian', 2, 11, 'Dan bila dikatakan kepada mereka: "Janganlah kamu membuat kerusakan di muka bumi". Mereka menjawab: "Sesungguhnya kami orang-orang yang mengadakan perbaikan".'),
  ('id.indonesian', 2, 12, 'Ingatlah, sesungguhnya mereka itulah orang-orang yang membuat kerusakan, tetapi mereka tidak sadar.'),
  ('id.indonesian', 2, 13, 'Apabila dikatakan kepada mereka: "Berimanlah kamu sebagaimana orang-orang lain telah beriman". Mereka menjawab: "Akan berimankah kami sebagaimana orang-orang yang bodoh itu telah beriman?" Ingatlah, sesungguhnya merekalah orang-orang yang bodoh; tetapi mereka tidak tahu.'),
  ('id.indonesian', 2, 14, 'Dan bila mereka berjumpa dengan orang-orang yang beriman, mereka mengatakan: "Kami telah beriman". Dan bila mereka kembali kepada syaitan-syaitan mereka, mereka mengatakan: "Sesungguhnya kami sependirian dengan kamu, kami hanyalah berolok-olok".'),
  ('id.indonesian', 2, 15, 'Allah akan (membalas) olok-olokan mereka dan membiarkan mereka terombang-ambing dalam kesesatan mereka.'),
  ('id.indonesian', 2, 16, 'Mereka itulah orang yang membeli kesesatan dengan petunjuk, maka tidaklah beruntung perniagaan mereka dan tidaklah mereka mendapat petunjuk.'),
  ('id.indonesian', 2, 17, 'Perumpamaan mereka adalah seperti orang yang menyalakan api, maka setelah api itu menerangi sekelilingnya Allah hilangkan cahaya (yang menyinari) mereka, dan membiarkan mereka dalam kegelapan, tidak dapat melihat.'),
  ('id.indonesian', 2, 18, 'Mereka tuli, bisu dan buta, maka tidaklah mereka akan kembali (ke jalan yang benar),'),
  ('id.indonesian', 2, 19, 'atau seperti (orang-orang yang ditimpa) hujan lebat dari langit disertai gelap gulita, guruh dan kilat; mereka menyumbat telinganya dengan anak jarinya, karena (mendengar suara) petir, sebab takut akan mati. Dan Allah meliputi orang-orang yang kafir.'),
  ('id.indonesian', 2, 20, 'Hampir-hampir kilat itu menyambar penglihatan mereka. Setiap kali kilat itu menyinari mereka, mereka berjalan di bawah sinar itu, dan bila gelap menimpa mereka, mereka berhenti. Jikalau Allah menghendaki, niscaya Dia melenyapkan pendengaran dan penglihatan mereka. Sesungguhnya Allah berkuasa atas segala sesuatu.'),
  ('id.indonesian', 2, 21, 'Hai manusia, sembahlah Tuhanmu yang telah menciptakanmu dan orang-orang yang sebelummu, agar kamu bertakwa,'),
  ('id.indonesian', 2, 22, 'Dialah yang menjadikan bumi sebagai hamparan bagimu dan langit sebagai atap, dan Dia menurunkan air (hujan) dari langit, lalu Dia menghasilkan dengan hujan itu segala buah-buahan sebagai rezeki untukmu; karena itu janganlah kamu mengadakan sekutu-sekutu bagi Allah, padahal kamu mengetahui.'),
  ('id.indonesian', 2, 23, 'Dan jika kamu (tetap) dalam keraguan tentang Al Quran yang Kami wahyukan kepada hamba Kami (Muhammad), buatlah satu surat (saja) yang semisal Al Quran itu dan ajaklah penolong-penolongmu selain Allah, jika kamu orang-orang yang benar.'),
  ('id.indonesian', 2, 24, 'Maka jika kamu tidak dapat membuat(nya) -- dan pasti kamu tidak akan dapat membuat(nya), peliharalah dirimu dari neraka yang bahan bakarnya manusia dan batu, yang disediakan bagi orang-orang kafir.'),
  ('id.indonesian', 2, 25, 'Dan sampaikanlah berita gembira kepada mereka yang beriman dan berbuat baik, bahwa bagi mereka disediakan surga-surga yang mengalir sungai-sungai di dalamnya. Setiap mereka diberi rezeki buah-buahan dalam surga-surga itu, mereka mengatakan: "Inilah yang pernah diberikan kepada kami dahulu". Mereka diberi buah-buahan yang serupa dan untuk mereka di dalamnya ada isteri-isteri yang suci dan mereka kekal di dalamnya.'),
  ('id.indonesian', 2, 26, 'Sesungguhnya Allah tiada segan membuat perumpamaan berupa nyamuk atau yang lebih rendah dari itu. Adapun orang-orang yang beriman, maka mereka yakin bahwa perumpamaan itu benar dari Tuhan mereka, tetapi mereka yang kafir mengatakan: "Apakah maksud Allah menjadikan ini untuk perumpamaan?". Dengan perumpamaan itu banyak orang yang disesatkan Allah, dan dengan perumpamaan itu (pula) banyak orang yang diberi-Nya petunjuk. Dan tidak ada yang disesatkan Allah kecuali orang-orang yang fasik,'),
  ('id.indonesian', 2, 27, '(yaitu) orang-orang yang melanggar perjanjian Allah sesudah perjanjian itu teguh, dan memutuskan apa yang diperintahkan Allah (kepada mereka) untuk menghubungkannya dan membuat kerusakan di muka bumi. Mereka itulah orang-orang yang rugi.'),
  ('id.indonesian', 2, 28, 'Mengapa kamu kafir kepada Allah, padahal kamu tadinya mati, lalu Allah menghidupkan kamu, kemudian kamu dimatikan dan dihidupkan-Nya kembali, kemudian kepada-Nya-lah kamu dikembalikan?'),
  ('id.indonesian', 2, 29, 'Dialah Allah, yang menjadikan segala yang ada di bumi untuk kamu dan Dia berkehendak (menciptakan) langit, lalu dijadikan-Nya tujuh langit. Dan Dia Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 2, 30, 'Ingatlah ketika Tuhanmu berfirman kepada para Malaikat: "Sesungguhnya Aku hendak menjadikan seorang khalifah di muka bumi". Mereka berkata: "Mengapa Engkau hendak menjadikan (khalifah) di bumi itu orang yang akan membuat kerusakan padanya dan menumpahkan darah, padahal kami senantiasa bertasbih dengan memuji Engkau dan mensucikan Engkau?" Tuhan berfirman: "Sesungguhnya Aku mengetahui apa yang tidak kamu ketahui".'),
  ('id.indonesian', 2, 31, 'Dan Dia mengajarkan kepada Adam nama-nama (benda-benda) seluruhnya, kemudian mengemukakannya kepada para Malaikat lalu berfirman: "Sebutkanlah kepada-Ku nama benda-benda itu jika kamu mamang benar orang-orang yang benar!"'),
  ('id.indonesian', 2, 32, 'Mereka menjawab: "Maha Suci Engkau, tidak ada yang kami ketahui selain dari apa yang telah Engkau ajarkan kepada kami; sesungguhnya Engkaulah Yang Maha Mengetahui lagi Maha Bijaksana".'),
  ('id.indonesian', 2, 33, 'Allah berfirman: "Hai Adam, beritahukanlah kepada mereka nama-nama benda ini". Maka setelah diberitahukannya kepada mereka nama-nama benda itu, Allah berfirman: "Bukankah sudah Ku-katakan kepadamu, bahwa sesungguhnya Aku mengetahui rahasia langit dan bumi dan mengetahui apa yang kamu lahirkan dan apa yang kamu sembunyikan?"'),
  ('id.indonesian', 2, 34, 'Dan (ingatlah) ketika Kami berfirman kepada para malaikat: "Sujudlah kamu kepada Adam," maka sujudlah mereka kecuali Iblis; ia enggan dan takabur dan adalah ia termasuk golongan orang-orang yang kafir.'),
  ('id.indonesian', 2, 35, 'Dan Kami berfirman: "Hai Adam, diamilah oleh kamu dan isterimu surga ini, dan makanlah makanan-makanannya yang banyak lagi baik dimana saja yang kamu sukai, dan janganlah kamu dekati pohon ini, yang menyebabkan kamu termasuk orang-orang yang zalim.'),
  ('id.indonesian', 2, 36, 'Lalu keduanya digelincirkan oleh syaitan dari surga itu dan dikeluarkan dari keadaan semula dan Kami berfirman: "Turunlah kamu! sebagian kamu menjadi musuh bagi yang lain, dan bagi kamu ada tempat kediaman di bumi, dan kesenangan hidup sampai waktu yang ditentukan".'),
  ('id.indonesian', 2, 37, 'Kemudian Adam menerima beberapa kalimat dari Tuhannya, maka Allah menerima taubatnya. Sesungguhnya Allah Maha Penerima taubat lagi Maha Penyayang.'),
  ('id.indonesian', 2, 38, 'Kami berfirman: "Turunlah kamu semuanya dari surga itu! Kemudian jika datang petunjuk-Ku kepadamu, maka barang siapa yang mengikuti petunjuk-Ku, niscaya tidak ada kekhawatiran atas mereka, dan tidak (pula) mereka bersedih hati".'),
  ('id.indonesian', 2, 39, 'Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itu penghuni neraka; mereka kekal di dalamnya.'),
  ('id.indonesian', 2, 40, 'Hai Bani Israil, ingatlah akan nikmat-Ku yang telah Aku anugerahkan kepadamu, dan penuhilah janjimu kepada-Ku, niscaya Aku penuhi janji-Ku kepadamu; dan hanya kepada-Ku-lah kamu harus takut (tunduk).'),
  ('id.indonesian', 2, 41, 'Dan berimanlah kamu kepada apa yang telah Aku turunkan (Al Quran) yang membenarkan apa yang ada padamu (Taurat), dan janganlah kamu menjadi orang yang pertama kafir kepadanya, dan janganlah kamu menukarkan ayat-ayat-Ku dengan harga yang rendah, dan hanya kepada Akulah kamu harus bertakwa.'),
  ('id.indonesian', 2, 42, 'Dan janganlah kamu campur adukkan yang hak dengan yang bathil dan janganlah kamu sembunyikan yang hak itu, sedang kamu mengetahui.'),
  ('id.indonesian', 2, 43, 'Dan dirikanlah shalat, tunaikanlah zakat dan ruku\'lah beserta orang-orang yang ruku\'.'),
  ('id.indonesian', 2, 44, 'Mengapa kamu suruh orang lain (mengerjakan) kebaktian, sedang kamu melupakan diri (kewajiban)mu sendiri, padahal kamu membaca Al Kitab (Taurat)? Maka tidaklah kamu berpikir?'),
  ('id.indonesian', 2, 45, 'Jadikanlah sabar dan shalat sebagai penolongmu. Dan sesungguhnya yang demikian itu sungguh berat, kecuali bagi orang-orang yang khusyu\','),
  ('id.indonesian', 2, 46, '(yaitu) orang-orang yang meyakini, bahwa mereka akan menemui Tuhannya, dan bahwa mereka akan kembali kepada-Nya.'),
  ('id.indonesian', 2, 47, 'Hai Bani Israil, ingatlah akan nikmat-Ku yang telah Aku anugerahkan kepadamu dan (ingatlah pula) bahwasanya Aku telah melebihkan kamu atas segala umat.'),
  ('id.indonesian', 2, 48, 'Dan jagalah dirimu dari (azab) hari (kiamat, yang pada hari itu) seseorang tidak dapat membela orang lain, walau sedikitpun; dan (begitu pula) tidak diterima syafa\'at dan tebusan dari padanya, dan tidaklah mereka akan ditolong.'),
  ('id.indonesian', 2, 49, 'Dan (ingatlah) ketika Kami selamatkan kamu dari (Fir\'aun) dan pengikut-pengikutnya; mereka menimpakan kepadamu siksaan yang seberat-beratnya, mereka menyembelih anak-anakmu yang laki-laki dan membiarkan hidup anak-anakmu yang perempuan. Dan pada yang demikian itu terdapat cobaan-cobaan yang besar dari Tuhanmu.'),
  ('id.indonesian', 2, 50, 'Dan (ingatlah), ketika Kami belah laut untukmu, lalu Kami selamatkan kamu dan Kami tenggelamkan (Fir\'aun) dan pengikut-pengikutnya sedang kamu sendiri menyaksikan.'),
  ('id.indonesian', 2, 51, 'Dan (ingatlah), ketika Kami berjanji kepada Musa (memberikan Taurat, sesudah) empat puluh malam, lalu kamu menjadikan anak lembu (sembahan) sepeninggalnya dan kamu adalah orang-orang yang zalim.'),
  ('id.indonesian', 2, 52, 'Kemudian sesudah itu Kami maafkan kesalahanmu, agar kamu bersyukur.'),
  ('id.indonesian', 2, 53, 'Dan (ingatlah), ketika Kami berikan kepada Musa Al Kitab (Taurat) dan keterangan yang membedakan antara yang benar dan yang salah, agar kamu mendapat petunjuk.'),
  ('id.indonesian', 2, 54, 'Dan (ingatlah), ketika Musa berkata kepada kaumnya: "Hai kaumku, sesungguhnya kamu telah menganiaya dirimu sendiri karena kamu telah menjadikan anak lembu (sembahanmu), maka bertaubatlah kepada Tuhan yang menjadikan kamu dan bunuhlah dirimu. Hal itu adalah lebih baik bagimu pada sisi Tuhan yang menjadikan kamu; maka Allah akan menerima taubatmu. Sesungguhnya Dialah Yang Maha Penerima taubat lagi Maha Penyayang".'),
  ('id.indonesian', 2, 55, 'Dan (ingatlah), ketika kamu berkata: "Hai Musa, kami tidak akan beriman kepadamu sebelum kami melihat Allah dengan terang, karena itu kamu disambar halilintar, sedang kamu menyaksikannya".'),
  ('id.indonesian', 2, 56, 'Setelah itu Kami bangkitkan kamu sesudah kamu mati, supaya kamu bersyukur.'),
  ('id.indonesian', 2, 57, 'Dan Kami naungi kamu dengan awan, dan Kami turunkan kepadamu "manna" dan "salwa". Makanlah dari makanan yang baik-baik yang telah Kami berikan kepadamu; dan tidaklah mereka menganiaya Kami; akan tetapi merekalah yang menganiaya diri mereka sendiri.'),
  ('id.indonesian', 2, 58, 'Dan (ingatlah), ketika Kami berfirman: "Masuklah kamu ke negeri ini (Baitul Maqdis), dan makanlah dari hasil buminya, yang banyak lagi enak dimana yang kamu sukai, dan masukilah pintu gerbangnya sambil bersujud, dan katakanlah: "Bebaskanlah kami dari dosa", niscaya Kami ampuni kesalahan-kesalahanmu, dan kelak Kami akan menambah (pemberian Kami) kepada orang-orang yang berbuat baik".'),
  ('id.indonesian', 2, 59, 'Lalu orang-orang yang zalim mengganti perintah dengan (mengerjakan) yang tidak diperintahkan kepada mereka. Sebab itu Kami timpakan atas orang-orang yang zalim itu dari langit, karena mereka berbuat fasik.'),
  ('id.indonesian', 2, 60, 'Dan (ingatlah) ketika Musa memohon air untuk kaumnya, lalu Kami berfirman: "Pukullah batu itu dengan tongkatmu". Lalu memancarlah daripadanya dua belas mata air. Sungguh tiap-tiap suku telah mengetahui tempat minumnya (masing-masing). Makan dan minumlah rezeki (yang diberikan) Allah, dan janganlah kamu berkeliaran di muka bumi dengan berbuat kerusakan.'),
  ('id.indonesian', 2, 61, 'Dan (ingatlah), ketika kamu berkata: "Hai Musa, kami tidak bisa sabar (tahan) dengan satu macam makanan saja. Sebab itu mohonkanlah untuk kami kepada Tuhanmu, agar Dia mengeluarkan bagi kami dari apa yang ditumbuhkan bumi, yaitu sayur-mayurnya, ketimunnya, bawang putihnya, kacang adasnya, dan bawang merahnya". Musa berkata: "Maukah kamu mengambil yang rendah sebagai pengganti yang lebih baik? Pergilah kamu ke suatu kota, pasti kamu memperoleh apa yang kamu minta". Lalu ditimpahkanlah kepada mereka nista dan kehinaan, serta mereka mendapat kemurkaan dari Allah. Hal itu (terjadi) karena mereka selalu mengingkari ayat-ayat Allah dan membunuh para Nabi yang memang tidak dibenarkan. Demikian itu (terjadi) karena mereka selalu berbuat durhaka dan melampaui batas.'),
  ('id.indonesian', 2, 62, 'Sesungguhnya orang-orang mukmin, orang-orang Yahudi, orang-orang Nasrani dan orang-orang Shabiin, siapa saja diantara mereka yang benar-benar beriman kepada Allah, hari kemudian dan beramal saleh, mereka akan menerima pahala dari Tuhan mereka, tidak ada kekhawatiran kepada mereka, dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 2, 63, 'Dan (ingatlah), ketika Kami mengambil janji dari kamu dan Kami angkatkan gunung (Thursina) di atasmu (seraya Kami berfirman): "Peganglah teguh-teguh apa yang Kami berikan kepadamu dan ingatlah selalu apa yang ada didalamnya, agar kamu bertakwa".'),
  ('id.indonesian', 2, 64, 'Kemudian kamu berpaling setelah (adanya perjanjian) itu, maka kalau tidak ada karunia Allah dan rahmat-Nya atasmu, niscaya kamu tergolong orang yang rugi.'),
  ('id.indonesian', 2, 65, 'Dan sesungguhnya telah kamu ketahui orang-orang yang melanggar diantaramu pada hari Sabtu, lalu Kami berfirman kepada mereka: "Jadilah kamu kera yang hina".'),
  ('id.indonesian', 2, 66, 'Maka Kami jadikan yang demikian itu peringatan bagi orang-orang dimasa itu, dan bagi mereka yang datang kemudian, serta menjadi pelajaran bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 2, 67, 'Dan (ingatlah), ketika Musa berkata kepada kaumnya: "Sesungguhnya Allah menyuruh kamu menyembelih seekor sapi betina". Mereka berkata: "Apakah kamu hendak menjadikan kami buah ejekan?" Musa menjawab: "Aku berlindung kepada Allah agar tidak menjadi salah seorang dari orang-orang yang jahil".'),
  ('id.indonesian', 2, 68, 'Mereka menjawab: "Mohonkanlah kepada Tuhanmu untuk kami, agar Dia menerangkan kepada kami; sapi betina apakah itu". Musa menjawab: "Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang tidak tua dan tidak muda; pertengahan antara itu; maka kerjakanlah apa yang diperintahkan kepadamu".'),
  ('id.indonesian', 2, 69, 'Mereka berkata: "Mohonkanlah kepada Tuhanmu untuk kami agar Dia menerangkan kepada kami apa warnanya". Musa menjawab: "Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang kuning, yang kuning tua warnanya, lagi menyenangkan orang-orang yang memandangnya".'),
  ('id.indonesian', 2, 70, 'Mereka berkata: "Mohonkanlah kepada Tuhanmu untuk kami agar Dia menerangkan kepada kami bagaimana hakikat sapi betina itu, karena sesungguhnya sapi itu (masih) samar bagi kami dan sesungguhnya kami insya Allah akan mendapat petunjuk (untuk memperoleh sapi itu)".'),
  ('id.indonesian', 2, 71, 'Musa berkata: "Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang belum pernah dipakai untuk membajak tanah dan tidak pula untuk mengairi tanaman, tidak bercacat, tidak ada belangnya". Mereka berkata: "Sekarang barulah kamu menerangkan hakikat sapi betina yang sebenarnya". Kemudian mereka menyembelihnya dan hampir saja mereka tidak melaksanakan perintah itu.'),
  ('id.indonesian', 2, 72, 'Dan (ingatlah), ketika kamu membunuh seorang manusia lalu kamu saling tuduh menuduh tentang itu. Dan Allah hendak menyingkapkan apa yang selama ini kamu sembunyikan.'),
  ('id.indonesian', 2, 73, 'Lalu Kami berfirman: "Pukullah mayat itu dengan sebahagian anggota sapi betina itu!" Demikianlah Allah menghidupkan kembali orang-orang yang telah mati, dam memperlihatkan padamu tanda-tanda kekuasaan-Nya agar kamu mengerti.'),
  ('id.indonesian', 2, 74, 'Kemudian setelah itu hatimu menjadi keras seperti batu, bahkan lebih keras lagi. Padahal diantara batu-batu itu sungguh ada yang mengalir sungai-sungai dari padanya dan diantaranya sungguh ada yang terbelah lalu keluarlah mata air dari padanya dan diantaranya sungguh ada yang meluncur jatuh, karena takut kepada Allah. Dan Allah sekali-sekali tidak lengah dari apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 75, 'Apakah kamu masih mengharapkan mereka akan percaya kepadamu, padahal segolongan dari mereka mendengar firman Allah, lalu mereka mengubahnya setelah mereka memahaminya, sedang mereka mengetahui?.'),
  ('id.indonesian', 2, 76, 'Dan apabila mereka berjumpa dengan orang-orang yang beriman, mereka berkata: "Kamipun telah beriman," tetapi apabila mereka berada sesama mereka saja, lalu mereka berkata: "Apakah kamu menceritakan kepada mereka (orang-orang mukmin) apa yang telah diterangkan Allah kepadamu, supaya dengan demikian mereka dapat mengalahkan hujjahmu di hadapan Tuhanmu; tidakkah kamu mengerti?"'),
  ('id.indonesian', 2, 77, 'Tidakkah mereka mengetahui bahwa Allah mengetahui segala yang mereka sembunyikan dan segala yang mereka nyatakan?'),
  ('id.indonesian', 2, 78, 'Dan diantara mereka ada yang buta huruf, tidak mengetahui Al Kitab (Taurat), kecuali dongengan bohong belaka dan mereka hanya menduga-duga.'),
  ('id.indonesian', 2, 79, 'Maka kecelakaan yAng besarlah bagi orang-orang yang menulis Al Kitab dengan tangan mereka sendiri, lalu dikatakannya; "Ini dari Allah", (dengan maksud) untuk memperoleh keuntungan yang sedikit dengan perbuatan itu. Maka kecelakaan yang besarlah bagi mereka, akibat apa yang ditulis oleh tangan mereka sendiri, dan kecelakaan yang besarlah bagi mereka, akibat apa yang mereka kerjakan.'),
  ('id.indonesian', 2, 80, 'Dan mereka berkata: "Kami sekali-kali tidak akan disentuh oleh api neraka, kecuali selama beberapa hari saja". Katakanlah: "Sudahkah kamu menerima janji dari Allah sehingga Allah tidak akan memungkiri janji-Nya, ataukah kamu hanya mengatakan terhadap Allah apa yang tidak kamu ketahui?"'),
  ('id.indonesian', 2, 81, '(Bukan demikian), yang benar: barangsiapa berbuat dosa dan ia telah diliputi oleh dosanya, mereka itulah penghuni neraka, mereka kekal di dalamnya.'),
  ('id.indonesian', 2, 82, 'Dan orang-orang yang beriman serta beramal saleh, mereka itu penghuni surga; mereka kekal di dalamnya.'),
  ('id.indonesian', 2, 83, 'Dan (ingatlah), ketika Kami mengambil janji dari Bani Israil (yaitu): Janganlah kamu menyembah selain Allah, dan berbuat kebaikanlah kepada ibu bapa, kaum kerabat, anak-anak yatim, dan orang-orang miskin, serta ucapkanlah kata-kata yang baik kepada manusia, dirikanlah shalat dan tunaikanlah zakat. Kemudian kamu tidak memenuhi janji itu, kecuali sebahagian kecil daripada kamu, dan kamu selalu berpaling.'),
  ('id.indonesian', 2, 84, 'Dan (ingatlah), ketika Kami mengambil janji dari kamu (yaitu): kamu tidak akan menumpahkan darahmu (membunuh orang), dan kamu tidak akan mengusir dirimu (saudaramu sebangsa) dari kampung halamanmu, kemudian kamu berikrar (akan memenuhinya) sedang kamu mempersaksikannya.'),
  ('id.indonesian', 2, 85, 'Kemudian kamu (Bani Israil) membunuh dirimu (saudaramu sebangsa) dan mengusir segolongan daripada kamu dari kampung halamannya, kamu bantu membantu terhadap mereka dengan membuat dosa dan permusuhan; tetapi jika mereka datang kepadamu sebagai tawanan, kamu tebus mereka, padahal mengusir mereka itu (juga) terlarang bagimu. Apakah kamu beriman kepada sebahagian Al Kitab (Taurat) dan ingkar terhadap sebahagian yang lain? Tiadalah balasan bagi orang yang berbuat demikian daripadamu, melainkan kenistaan dalam kehidupan dunia, dan pada hari kiamat mereka dikembalikan kepada siksa yang sangat berat. Allah tidak lengah dari apa yang kamu perbuat.'),
  ('id.indonesian', 2, 86, 'Itulah orang-orang yang membeli kehidupan dunia dengan (kehidupan) akhirat, maka tidak akan diringankan siksa mereka dan mereka tidak akan ditolong.'),
  ('id.indonesian', 2, 87, 'Dan sesungguhnya Kami telah mendatangkan Al Kitab (Taurat) kepada Musa, dan Kami telah menyusulinya (berturut-turut) sesudah itu dengan rasul-rasul, dan telah Kami berikan bukti-bukti kebenaran (mukjizat) kepada Isa putera Maryam dan Kami memperkuatnya dengan Ruhul Qudus. Apakah setiap datang kepadamu seorang rasul membawa sesuatu (pelajaran) yang tidak sesuai dengan keinginanmu lalu kamu menyombong; maka beberapa orang (diantara mereka) kamu dustakan dan beberapa orang (yang lain) kamu bunuh?'),
  ('id.indonesian', 2, 88, 'Dan mereka berkata: "Hati kami tertutup". Tetapi sebenarnya Allah telah mengutuk mereka karena keingkaran mereka; maka sedikit sekali mereka yang beriman.'),
  ('id.indonesian', 2, 89, 'Dan setelah datang kepada mereka Al Quran dari Allah yang membenarkan apa yang ada pada mereka, padahal sebelumnya mereka biasa memohon (kedatangan Nabi) untuk mendapat kemenangan atas orang-orang kafir, maka setelah datang kepada mereka apa yang telah mereka ketahui, mereka lalu ingkar kepadanya. Maka laknat Allah-lah atas orang-orang yang ingkar itu.'),
  ('id.indonesian', 2, 90, 'Alangkah buruknya (hasil perbuatan) mereka yang menjual dirinya sendiri dengan kekafiran kepada apa yang telah diturunkan Allah, karena dengki bahwa Allah menurunkan karunia-Nya kepada siapa yang dikehendaki-Nya diantara hamba-hamba-Nya. Karena itu mereka mendapat murka sesudah (mendapat) kemurkaan. Dan untuk orang-orang kafir siksaan yang menghinakan.'),
  ('id.indonesian', 2, 91, 'Dan apabila dikatakan kepada mereka: "Berimanlah kepada Al Quran yang diturunkan Allah," mereka berkata: "Kami hanya beriman kepada apa yang diturunkan kepada kami". Dan mereka kafir kepada Al Quran yang diturunkan sesudahnya, sedang Al Quran itu adalah (Kitab) yang hak; yang membenarkan apa yang ada pada mereka. Katakanlah: "Mengapa kamu dahulu membunuh nabi-nabi Allah jika benar kamu orang-orang yang beriman?"'),
  ('id.indonesian', 2, 92, 'Sesungguhnya Musa telah datang kepadamu membawa bukti-bukti kebenaran (mukjizat), kemudian kamu jadikan anak sapi (sebagai sembahan) sesudah (kepergian)nya, dan sebenarnya kamu adalah orang-orang yang zalim.'),
  ('id.indonesian', 2, 93, 'Dan (ingatlah), ketika Kami mengambil janji dari kamu dan Kami angkat bukit (Thursina) di atasmu (seraya Kami berfirman): "Peganglah teguh-teguh apa yang Kami berikan kepadamu dan dengarkanlah!" Mereka menjawab: "Kami mendengar tetapi tidak mentaati". Dan telah diresapkan ke dalam hati mereka itu (kecintaan menyembah) anak sapi karena kekafirannya. Katakanlah: "Amat jahat perbuatan yang telah diperintahkan imanmu kepadamu jika betul kamu beriman (kepada Taurat).'),
  ('id.indonesian', 2, 94, 'Katakanlah: "Jika kamu (menganggap bahwa) kampung akhirat (surga) itu khusus untukmu di sisi Allah, bukan untuk orang lain, maka inginilah kematian(mu), jika kamu memang benar.'),
  ('id.indonesian', 2, 95, 'Dan sekali-kali mereka tidak akan mengingini kematian itu selama-lamanya, karena kesalahan-kesalahan yang telah diperbuat oleh tangan mereka (sendiri), dan Allah Maha Mengetahui siapa orang-orang yang aniaya.'),
  ('id.indonesian', 2, 96, 'Dan sungguh kamu akan mendapati mereka, manusia yang paling loba kepada kehidupan (di dunia), bahkan (lebih loba lagi) dari orang-orang musyrik. Masing-masing mereka ingin agar diberi umur seribu tahun, padahal umur panjang itu sekali-kali tidak akan menjauhkannya daripada siksa. Allah Maha Mengetahui apa yang mereka kerjakan.'),
  ('id.indonesian', 2, 97, 'Katakanlah: "Barang siapa yang menjadi musuh Jibril, maka Jibril itu telah menurunkannya (Al Quran) ke dalam hatimu dengan seizin Allah; membenarkan apa (kitab-kitab) yang sebelumnya dan menjadi petunjuk serta berita gembira bagi orang-orang yang beriman.'),
  ('id.indonesian', 2, 98, 'Barang siapa yang menjadi musuh Allah, malaikat-malaikat-Nya, rasul-rasul-Nya, Jibril dan Mikail, maka sesungguhnya Allah adalah musuh orang-orang kafir.'),
  ('id.indonesian', 2, 99, 'Dan sesungguhnya Kami telah menurunkan kepadamu ayat-ayat yang jelas; dan tak ada yang ingkar kepadanya, melainkan orang-orang yang fasik.'),
  ('id.indonesian', 2, 100, 'Patutkah (mereka ingkar kepada ayat-ayat Allah), dan setiap kali mereka mengikat janji, segolongan mereka melemparkannya? Bahkan sebagian besar dari mereka tidak beriman.'),
  ('id.indonesian', 2, 101, 'Dan setelah datang kepada mereka seorang Rasul dari sisi Allah yang membenarkan apa (kitab) yang ada pada mereka, sebahagian dari orang-orang yang diberi kitab (Taurat) melemparkan kitab Allah ke belakang (punggung)nya, seolah-olah mereka tidak mengetahui (bahwa itu adalah kitab Allah).'),
  ('id.indonesian', 2, 102, 'Dan mereka mengikuti apa yang dibaca oleh syaitan-syaitan pada masa kerajaan Sulaiman (dan mereka mengatakan bahwa Sulaiman itu mengerjakan sihir), padahal Sulaiman tidak kafir (tidak mengerjakan sihir), hanya syaitan-syaitan lah yang kafir (mengerjakan sihir). Mereka mengajarkan sihir kepada manusia dan apa yang diturunkan kepada dua orang malaikat di negeri Babil yaitu Harut dan Marut, sedang keduanya tidak mengajarkan (sesuatu) kepada seorangpun sebelum mengatakan: "Sesungguhnya kami hanya cobaan (bagimu), sebab itu janganlah kamu kafir". Maka mereka mempelajari dari kedua malaikat itu apa yang dengan sihir itu, mereka dapat menceraikan antara seorang (suami) dengan isterinya. Dan mereka itu (ahli sihir) tidak memberi mudharat dengan sihirnya kepada seorangpun, kecuali dengan izin Allah. Dan mereka mempelajari sesuatu yang tidak memberi mudharat kepadanya dan tidak memberi manfaat. Demi, sesungguhnya mereka telah meyakini bahwa barangsiapa yang menukarnya (kitab Allah) dengan sihir itu, tiadalah baginya keuntungan di akhirat, dan amat jahatlah perbuatan mereka menjual dirinya dengan sihir, kalau mereka mengetahui.'),
  ('id.indonesian', 2, 103, 'Sesungguhnya kalau mereka beriman dan bertakwa, (niscaya mereka akan mendapat pahala), dan sesungguhnya pahala dari sisi Allah adalah lebih baik, kalau mereka mengetahui.'),
  ('id.indonesian', 2, 104, 'Hai orang-orang yang beriman, janganlah kamu katakan (kepada Muhammad): "Raa\'ina", tetapi katakanlah: "Unzhurna", dan "dengarlah". Dan bagi orang-orang yang kafir siksaan yang pedih.'),
  ('id.indonesian', 2, 105, 'Orang-orang kafir dari Ahli Kitab dan orang-orang musyrik tiada menginginkan diturunkannya sesuatu kebaikan kepadamu dari Tuhanmu. Dan Allah menentukan siapa yang dikehendaki-Nya (untuk diberi) rahmat-Nya (kenabian); dan Allah mempunyai karunia yang besar.'),
  ('id.indonesian', 2, 106, 'Ayat mana saja yang Kami nasakhkan, atau Kami jadikan (manusia) lupa kepadanya, Kami datangkan yang lebih baik daripadanya atau yang sebanding dengannya. Tidakkah kamu mengetahui bahwa sesungguhnya Allah Maha Kuasa atas segala sesuatu?'),
  ('id.indonesian', 2, 107, 'Tiadakah kamu mengetahui bahwa kerajaan langit dan bumi adalah kepunyaan Allah? Dan tiada bagimu selain Allah seorang pelindung maupun seorang penolong.'),
  ('id.indonesian', 2, 108, 'Apakah kamu menghendaki untuk meminta kepada Rasul kamu seperti Bani Israil meminta kepada Musa pada jaman dahulu? Dan barangsiapa yang menukar iman dengan kekafiran, maka sungguh orang itu telah sesat dari jalan yang lurus.'),
  ('id.indonesian', 2, 109, 'Sebahagian besar Ahli Kitab menginginkan agar mereka dapat mengembalikan kamu kepada kekafiran setelah kamu beriman, karena dengki yang (timbul) dari diri mereka sendiri, setelah nyata bagi mereka kebenaran. Maka maafkanlah dan biarkanlah mereka, sampai Allah mendatangkan perintah-Nya. Sesungguhnya Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 2, 110, 'Dan dirikanlah shalat dan tunaikanlah zakat. Dan kebaikan apa saja yang kamu usahakan bagi dirimu, tentu kamu akan mendapat pahala nya pada sisi Allah. Sesungguhnya Alah Maha Melihat apa-apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 111, 'Dan mereka (Yahudi dan Nasrani) berkata: "Sekali-kali tidak akan masuk surga kecuali orang-orang (yang beragama) Yahudi atau Nasrani". Demikian itu (hanya) angan-angan mereka yang kosong belaka. Katakanlah: "Tunjukkanlah bukti kebenaranmu jika kamu adalah orang yang benar".'),
  ('id.indonesian', 2, 112, '(Tidak demikian) bahkan barangsiapa yang menyerahkan diri kepada Allah, sedang ia berbuat kebajikan, maka baginya pahala pada sisi Tuhannya dan tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 2, 113, 'Dan orang-orang Yahudi berkata: "Orang-orang Nasrani itu tidak mempunyai suatu pegangan", dan orang-orang Nasrani berkata: "Orang-orang Yahudi tidak mempunyai sesuatu pegangan," padahal mereka (sama-sama) membaca Al Kitab. Demikian pula orang-orang yang tidak mengetahui, mengatakan seperti ucapan mereka itu. Maka Allah akan mengadili diantara mereka pada hari Kiamat, tentang apa-apa yang mereka berselisih padanya.'),
  ('id.indonesian', 2, 114, 'Dan siapakah yang lebih aniaya daripada orang yang menghalanghalangi menyebut nama Allah dalam mesjid-mesjid-Nya, dan berusaha untuk merobohkannya? Mereka itu tidak sepatutnya masuk ke dalamnya (mesjid Allah), kecuali dengan rasa takut (kepada Allah). Mereka di dunia mendapat kehinaan dan di akhirat mendapat siksa yang berat.'),
  ('id.indonesian', 2, 115, 'Dan kepunyaan Allah-lah timur dan barat, maka kemanapun kamu menghadap di situlah wajah Allah. Sesungguhnya Allah Maha Luas (rahmat-Nya) lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 116, 'Mereka (orang-orang kafir) berkata: "Allah mempunyai anak". Maha Suci Allah, bahkan apa yang ada di langit dan di bumi adalah kepunyaan Allah; semua tunduk kepada-Nya.'),
  ('id.indonesian', 2, 117, 'Allah Pencipta langit dan bumi, dan bila Dia berkehendak (untuk menciptakan) sesuatu, maka (cukuplah) Dia hanya mengatakan kepadanya: "Jadilah!" Lalu jadilah ia.'),
  ('id.indonesian', 2, 118, 'Dan orang-orang yang tidak mengetahui berkata: "Mengapa Allah tidak (langsung) berbicara dengan kami atau datang tanda-tanda kekuasaan-Nya kepada kami?" Demikian pula orang-orang yang sebelum mereka telah mengatakan seperti ucapan mereka itu; hati mereka serupa. Sesungguhnya Kami telah menjelaskan tanda-tanda kekuasaan Kami kepada kaum yang yakin.'),
  ('id.indonesian', 2, 119, 'Sesungguhnya Kami telah mengutusmu (Muhammad) dengan kebenaran; sebagai pembawa berita gembira dan pemberi peringatan, dan kamu tidak akan diminta (pertanggungan jawab) tentang penghuni-penghuni neraka.'),
  ('id.indonesian', 2, 120, 'Orang-orang Yahudi dan Nasrani tidak akan senang kepada kamu hingga kamu mengikuti agama mereka. Katakanlah: "Sesungguhnya petunjuk Allah itulah petunjuk (yang benar)". Dan sesungguhnya jika kamu mengikuti kemauan mereka setelah pengetahuan datang kepadamu, maka Allah tidak lagi menjadi pelindung dan penolong bagimu.'),
  ('id.indonesian', 2, 121, 'Orang-orang yang telah Kami berikan Al Kitab kepadanya, mereka membacanya dengan bacaan yang sebenarnya, mereka itu beriman kepadanya. Dan barangsiapa yang ingkar kepadanya, maka mereka itulah orang-orang yang rugi.'),
  ('id.indonesian', 2, 122, 'Hai Bani Israil, ingatlah akan nikmat-Ku yang telah Ku-anugerahkan kepadamu dan Aku telah melabihkan kamu atas segala umat.'),
  ('id.indonesian', 2, 123, 'Dan takutlah kamu kepada suatu hari di waktu seseorang tidak dapat menggantikan seseorang lain sedikitpun dan tidak akan diterima suatu tebusan daripadanya dan tidak akan memberi manfaat sesuatu syafa\'at kepadanya dan tidak (pula) mereka akan ditolong.'),
  ('id.indonesian', 2, 124, 'Dan (ingatlah), ketika Ibrahim diuji Tuhannya dengan beberapa kalimat (perintah dan larangan), lalu Ibrahim menunaikannya. Allah berfirman: "Sesungguhnya Aku akan menjadikanmu imam bagi seluruh manusia". Ibrahim berkata: "(Dan saya mohon juga) dari keturunanku". Allah berfirman: "Janji-Ku (ini) tidak mengenai orang yang zalim".'),
  ('id.indonesian', 2, 125, 'Dan (ingatlah), ketika Kami menjadikan rumah itu (Baitullah) tempat berkumpul bagi manusia dan tempat yang aman. Dan jadikanlah sebahagian maqam Ibrahim tempat shalat. Dan telah Kami perintahkan kepada Ibrahim dan Ismail: "Bersihkanlah rumah-Ku untuk orang-orang yang thawaf, yang i\'tikaf, yang ruku\' dan yang sujud".'),
  ('id.indonesian', 2, 126, 'Dan (ingatlah), ketika Ibrahim berdoa: "Ya Tuhanku, jadikanlah negeri ini, negeri yang aman sentosa, dan berikanlah rezeki dari buah-buahan kepada penduduknya yang beriman diantara mereka kepada Allah dan hari kemudian. Allah berfirman: "Dan kepada orang yang kafirpun Aku beri kesenangan sementara, kemudian Aku paksa ia menjalani siksa neraka dan itulah seburuk-buruk tempat kembali".'),
  ('id.indonesian', 2, 127, 'Dan (ingatlah), ketika Ibrahim meninggikan (membina) dasar-dasar Baitullah bersama Ismail (seraya berdoa): "Ya Tuhan kami terimalah daripada kami (amalan kami), sesungguhnya Engkaulah Yang Maha Mendengar lagi Maha Mengetahui".'),
  ('id.indonesian', 2, 128, 'Ya Tuhan kami, jadikanlah kami berdua orang yang tunduk patuh kepada Engkau dan (jadikanlah) diantara anak cucu kami umat yang tunduk patuh kepada Engkau dan tunjukkanlah kepada kami cara-cara dan tempat-tempat ibadat haji kami, dan terimalah taubat kami. Sesungguhnya Engkaulah Yang Maha Penerima taubat lagi Maha Penyayang.'),
  ('id.indonesian', 2, 129, 'Ya Tuhan kami, utuslah untuk mereka sesorang Rasul dari kalangan mereka, yang akan membacakan kepada mereka ayat-ayat Engkau, dan mengajarkan kepada mereka Al Kitab (Al Quran) dan Al-Hikmah (As-Sunnah) serta mensucikan mereka. Sesungguhnya Engkaulah yang Maha Kuasa lagi Maha Bijaksana.'),
  ('id.indonesian', 2, 130, 'Dan tidak ada yang benci kepada agama Ibrahim, melainkan orang yang memperbodoh dirinya sendiri, dan sungguh Kami telah memilihnya di dunia dan sesungguhnya dia di akhirat benar-benar termasuk orang-orang yang saleh.'),
  ('id.indonesian', 2, 131, 'Ketika Tuhannya berfirman kepadanya: "Tunduk patuhlah!" Ibrahim menjawab: "Aku tunduk patuh kepada Tuhan semesta alam".'),
  ('id.indonesian', 2, 132, 'Dan Ibrahim telah mewasiatkan ucapan itu kepada anak-anaknya, demikian pula Ya\'qub. (Ibrahim berkata): "Hai anak-anakku! Sesungguhnya Allah telah memilih agama ini bagimu, maka janganlah kamu mati kecuali dalam memeluk agama Islam".'),
  ('id.indonesian', 2, 133, 'Adakah kamu hadir ketika Ya\'qub kedatangan (tanda-tanda) maut, ketika ia berkata kepada anak-anaknya: "Apa yang kamu sembah sepeninggalku?" Mereka menjawab: "Kami akan menyembah Tuhanmu dan Tuhan nenek moyangmu, Ibrahim, Ismail dan Ishaq, (yaitu) Tuhan Yang Maha Esa dan kami hanya tunduk patuh kepada-Nya".'),
  ('id.indonesian', 2, 134, 'Itu adalah umat yang lalu; baginya apa yang telah diusahakannya dan bagimu apa yang sudah kamu usahakan, dan kamu tidak akan diminta pertanggungan jawab tentang apa yang telah mereka kerjakan.'),
  ('id.indonesian', 2, 135, 'Dan mereka berkata: "Hendaklah kamu menjadi penganut agama Yahudi atau Nasrani, niscaya kamu mendapat petunjuk". Katakanlah: "Tidak, melainkan (kami mengikuti) agama Ibrahim yang lurus. Dan bukanlah dia (Ibrahim) dari golongan orang musyrik".'),
  ('id.indonesian', 2, 136, 'Katakanlah (hai orang-orang mukmin): "Kami beriman kepada Allah dan apa yang diturunkan kepada kami, dan apa yang diturunkan kepada Ibrahim, Isma\'il, Ishaq, Ya\'qub dan anak cucunya, dan apa yang diberikan kepada Musa dan Isa serta apa yang diberikan kepada nabi-nabi dari Tuhannya. Kami tidak membeda-bedakan seorangpun diantara mereka dan kami hanya tunduk patuh kepada-Nya".'),
  ('id.indonesian', 2, 137, 'Maka jika mereka beriman kepada apa yang kamu telah beriman kepadanya, sungguh mereka telah mendapat petunjuk; dan jika mereka berpaling, sesungguhnya mereka berada dalam permusuhan (dengan kamu). Maka Allah akan memelihara kamu dari mereka. Dan Dialah Yang Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 138, 'Shibghah Allah. Dan siapakah yang lebih baik shibghahnya dari pada Allah? Dan hanya kepada-Nya-lah kami menyembah.'),
  ('id.indonesian', 2, 139, 'Katakanlah: "Apakah kamu memperdebatkan dengan kami tentang Allah, padahal Dia adalah Tuhan kami dan Tuhan kamu; bagi kami amalan kami, dan bagi kamu amalan kamu dan hanya kepada-Nya kami mengikhlaskan hati,'),
  ('id.indonesian', 2, 140, 'ataukah kamu (hai orang-orang Yahudi dan Nasrani) mengatakan bahwa Ibrahim, Isma\'il, Ishaq, Ya\'qub dan anak cucunya, adalah penganut agama Yahudi atau Nasrani?" Katakanlah: "Apakah kamu lebih mengetahui ataukah Allah, dan siapakah yang lebih zalim dari pada orang yang menyembunyikan syahadah dari Allah yang ada padanya?" Dan Allah sekali-kali tiada lengah dari apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 141, 'Itu adalah umat yang telah lalu; baginya apa yang diusahakannya dan bagimu apa yang kamu usahakan; dan kamu tidak akan diminta pertanggungan jawab tentang apa yang telah mereka kerjakan.'),
  ('id.indonesian', 2, 142, 'Orang-orang yang kurang akalnya diantara manusia akan berkata: "Apakah yang memalingkan mereka (umat Islam) dari kiblatnya (Baitul Maqdis) yang dahulu mereka telah berkiblat kepadanya?" Katakanlah: "Kepunyaan Allah-lah timur dan barat; Dia memberi petunjuk kepada siapa yang dikehendaki-Nya ke jalan yang lurus".'),
  ('id.indonesian', 2, 143, 'Dan demikian (pula) Kami telah menjadikan kamu (umat Islam), umat yang adil dan pilihan agar kamu menjadi saksi atas (perbuatan) manusia dan agar Rasul (Muhammad) menjadi saksi atas (perbuatan) kamu. Dan Kami tidak menetapkan kiblat yang menjadi kiblatmu (sekarang) melainkan agar Kami mengetahui (supaya nyata) siapa yang mengikuti Rasul dan siapa yang membelot. Dan sungguh (pemindahan kiblat) itu terasa amat berat, kecuali bagi orang-orang yang telah diberi petunjuk oleh Allah; dan Allah tidak akan menyia-nyiakan imanmu. Sesungguhnya Allah Maha Pengasih lagi Maha Penyayang kepada manusia.'),
  ('id.indonesian', 2, 144, 'Sungguh Kami (sering) melihat mukamu menengadah ke langit, maka sungguh Kami akan memalingkan kamu ke kiblat yang kamu sukai. Palingkanlah mukamu ke arah Masjidil Haram. Dan dimana saja kamu berada, palingkanlah mukamu ke arahnya. Dan sesungguhnya orang-orang (Yahudi dan Nasrani) yang diberi Al Kitab (Taurat dan Injil) memang mengetahui, bahwa berpaling ke Masjidil Haram itu adalah benar dari Tuhannya; dan Allah sekali-kali tidak lengah dari apa yang mereka kerjakan.'),
  ('id.indonesian', 2, 145, 'Dan sesungguhnya jika kamu mendatangkan kepada orang-orang (Yahudi dan Nasrani) yang diberi Al Kitab (Taurat dan Injil), semua ayat (keterangan), mereka tidak akan mengikuti kiblatmu, dan kamupun tidak akan mengikuti kiblat mereka, dan sebahagian merekapun tidak akan mengikuti kiblat sebahagian yang lain. Dan sesungguhnya jika kamu mengikuti keinginan mereka setelah datang ilmu kepadamu, sesungguhnya kamu -- kalau begitu -- termasuk golongan orang-orang yang zalim.'),
  ('id.indonesian', 2, 146, 'Orang-orang (Yahudi dan Nasrani) yang telah Kami beri Al Kitab (Taurat dan Injil) mengenal Muhammad seperti mereka mengenal anak-anaknya sendiri. Dan sesungguhnya sebahagian diantara mereka menyembunyikan kebenaran, padahal mereka mengetahui.'),
  ('id.indonesian', 2, 147, 'Kebenaran itu adalah dari Tuhanmu, sebab itu jangan sekali-kali kamu termasuk orang-orang yang ragu.'),
  ('id.indonesian', 2, 148, 'Dan bagi tiap-tiap umat ada kiblatnya (sendiri) yang ia menghadap kepadanya. Maka berlomba-lombalah (dalam membuat) kebaikan. Di mana saja kamu berada pasti Allah akan mengumpulkan kamu sekalian (pada hari kiamat). Sesungguhnya Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 2, 149, 'Dan dari mana saja kamu keluar (datang), maka palingkanlah wajahmu ke arah Masjidil Haram, sesungguhnya ketentuan itu benar-benar sesuatu yang hak dari Tuhanmu. Dan Allah sekali-kali tidak lengah dari apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 150, 'Dan dari mana saja kamu (keluar), maka palingkanlah wajahmu ke arah Masjidil Haram. Dan dimana saja kamu (sekalian) berada, maka palingkanlah wajahmu ke arahnya, agar tidak ada hujjah bagi manusia atas kamu, kecuali orang-orang yang zalim diantara mereka. Maka janganlah kamu takut kepada mereka dan takutlah kepada-Ku (saja). Dan agar Ku-sempurnakan nikmat-Ku atasmu, dan supaya kamu mendapat petunjuk.'),
  ('id.indonesian', 2, 151, 'Sebagaimana (Kami telah menyempurnakan nikmat Kami kepadamu) Kami telah mengutus kepadamu Rasul diantara kamu yang membacakan ayat-ayat Kami kepada kamu dan mensucikan kamu dan mengajarkan kepadamu Al Kitab dan Al-Hikmah, serta mengajarkan kepada kamu apa yang belum kamu ketahui.'),
  ('id.indonesian', 2, 152, 'Karena itu, ingatlah kamu kepada-Ku niscaya Aku ingat (pula) kepadamu, dan bersyukurlah kepada-Ku, dan janganlah kamu mengingkari (nikmat)-Ku.'),
  ('id.indonesian', 2, 153, 'Hai orang-orang yang beriman, jadikanlah sabar dan shalat sebagai penolongmu, sesungguhnya Allah beserta orang-orang yang sabar.'),
  ('id.indonesian', 2, 154, 'Dan janganlah kamu mengatakan terhadap orang-orang yang gugur di jalan Allah, (bahwa mereka itu) mati; bahkan (sebenarnya) mereka itu hidup, tetapi kamu tidak menyadarinya.'),
  ('id.indonesian', 2, 155, 'Dan sungguh akan Kami berikan cobaan kepadamu, dengan sedikit ketakutan, kelaparan, kekurangan harta, jiwa dan buah-buahan. Dan berikanlah berita gembira kepada orang-orang yang sabar.'),
  ('id.indonesian', 2, 156, '(yaitu) orang-orang yang apabila ditimpa musibah, mereka mengucapkan: "Inna lillaahi wa innaa ilaihi raaji\'uun".'),
  ('id.indonesian', 2, 157, 'Mereka itulah yang mendapat keberkatan yang sempurna dan rahmat dari Tuhan mereka dan mereka itulah orang-orang yang mendapat petunjuk.'),
  ('id.indonesian', 2, 158, 'Sesungguhnya Shafaa dan Marwa adalah sebahagian dari syi\'ar Allah. Maka barangsiapa yang beribadah haji ke Baitullah atau ber\'umrah, maka tidak ada dosa baginya mengerjakan sa\'i antara keduanya. Dan barangsiapa yang mengerjakan suatu kebajikan dengan kerelaan hati, maka sesungguhnya Allah Maha Mensyukuri kebaikan lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 159, 'Sesungguhnya orang-orang yang menyembunyikan apa yang telah Kami turunkan berupa keterangan-keterangan (yang jelas) dan petunjuk, setelah Kami menerangkannya kepada manusia dalam Al Kitab, mereka itu dilaknati Allah dan dilaknati (pula) oleh semua (mahluk) yang dapat melaknati,'),
  ('id.indonesian', 2, 160, 'kecuali mereka yang telah taubat dan mengadakan perbaikan dan menerangkan (kebenaran), maka terhadap mereka itulah Aku menerima taubatnya dan Akulah Yang Maha Menerima taubat lagi Maha Penyayang.'),
  ('id.indonesian', 2, 161, 'Sesungguhnya orang-orang kafir dan mereka mati dalam keadaan kafir, mereka itu mendapat laknat Allah, para Malaikat dan manusia seluruhnya.'),
  ('id.indonesian', 2, 162, 'Mereka kekal di dalam laknat itu; tidak akan diringankan siksa dari mereka dan tidak (pula) mereka diberi tangguh.'),
  ('id.indonesian', 2, 163, 'Dan Tuhanmu adalah Tuhan Yang Maha Esa; tidak ada Tuhan melainkan Dia Yang Maha Pemurah lagi Maha Penyayang.'),
  ('id.indonesian', 2, 164, 'Sesungguhnya dalam penciptaan langit dan bumi, silih bergantinya malam dan siang, bahtera yang berlayar di laut membawa apa yang berguna bagi manusia, dan apa yang Allah turunkan dari langit berupa air, lalu dengan air itu Dia hidupkan bumi sesudah mati (kering)-nya dan Dia sebarkan di bumi itu segala jenis hewan, dan pengisaran angin dan awan yang dikendalikan antara langit dan bumi; sungguh (terdapat) tanda-tanda (keesaan dan kebesaran Allah) bagi kaum yang memikirkan.'),
  ('id.indonesian', 2, 165, 'Dan diantara manusia ada orang-orang yang menyembah tandingan-tandingan selain Allah; mereka mencintainya sebagaimana mereka mencintai Allah. Adapun orang-orang yang beriman amat sangat cintanya kepada Allah. Dan jika seandainya orang-orang yang berbuat zalim itu mengetahui ketika mereka melihat siksa (pada hari kiamat), bahwa kekuatan itu kepunyaan Allah semuanya, dan bahwa Allah amat berat siksaan-Nya (niscaya mereka menyesal).'),
  ('id.indonesian', 2, 166, '(Yaitu) ketika orang-orang yang diikuti itu berlepas diri dari orang-orang yang mengikutinya, dan mereka melihat siksa; dan (ketika) segala hubungan antara mereka terputus sama sekali.'),
  ('id.indonesian', 2, 167, 'Dan berkatalah orang-orang yang mengikuti: "Seandainya kami dapat kembali (ke dunia), pasti kami akan berlepas diri dari mereka, sebagaimana mereka berlepas diri dari kami". Demikianlah Allah memperlihatkan kepada mereka amal perbuatannya menjadi sesalan bagi mereka; dan sekali-kali mereka tidak akan keluar dari api neraka.'),
  ('id.indonesian', 2, 168, 'Hai sekalian manusia, makanlah yang halal lagi baik dari apa yang terdapat di bumi, dan janganlah kamu mengikuti langkah-langkah syaitan; karena sesungguhnya syaitan itu adalah musuh yang nyata bagimu.'),
  ('id.indonesian', 2, 169, 'Sesungguhnya syaitan itu hanya menyuruh kamu berbuat jahat dan keji, dan mengatakan terhadap Allah apa yang tidak kamu ketahui.'),
  ('id.indonesian', 2, 170, 'Dan apabila dikatakan kepada mereka: "Ikutilah apa yang telah diturunkan Allah," mereka menjawab: "(Tidak), tetapi kami hanya mengikuti apa yang telah kami dapati dari (perbuatan) nenek moyang kami". "(Apakah mereka akan mengikuti juga), walaupun nenek moyang mereka itu tidak mengetahui suatu apapun, dan tidak mendapat petunjuk?".'),
  ('id.indonesian', 2, 171, 'Dan perumpamaan (orang-orang yang menyeru) orang-orang kafir adalah seperti penggembala yang memanggil binatang yang tidak mendengar selain panggilan dan seruan saja. Mereka tuli, bisu dan buta, maka (oleh sebab itu) mereka tidak mengerti.'),
  ('id.indonesian', 2, 172, 'Hai orang-orang yang beriman, makanlah di antara rezeki yang baik-baik yang Kami berikan kepadamu dan bersyukurlah kepada Allah, jika benar-benar kepada-Nya kamu menyembah.'),
  ('id.indonesian', 2, 173, 'Sesungguhnya Allah hanya mengharamkan bagimu bangkai, darah, daging babi, dan binatang yang (ketika disembelih) disebut (nama) selain Allah. Tetapi barangsiapa dalam keadaan terpaksa (memakannya) sedang dia tidak menginginkannya dan tidak (pula) melampaui batas, maka tidak ada dosa baginya. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 2, 174, 'Sesungguhnya orang-orang yang menyembunyikan apa yang telah diturunkan Allah, yaitu Al Kitab dan menjualnya dengan harga yang sedikit (murah), mereka itu sebenarnya tidak memakan (tidak menelan) ke dalam perutnya melainkan api, dan Allah tidak akan berbicara kepada mereka pada hari kiamat dan tidak mensucikan mereka dan bagi mereka siksa yang amat pedih.'),
  ('id.indonesian', 2, 175, 'Mereka itulah orang-orang yang membeli kesesatan dengan petunjuk dan siksa dengan ampunan. Maka alangkah beraninya mereka menentang api neraka!'),
  ('id.indonesian', 2, 176, 'Yang demikian itu adalah karena Allah telah menurunkan Al Kitab dengan membawa kebenaran; dan sesungguhnya orang-orang yang berselisih tentang (kebenaran) Al Kitab itu, benar-benar dalam penyimpangan yang jauh (dari kebenaran).'),
  ('id.indonesian', 2, 177, 'Bukanlah menghadapkan wajahmu ke arah timur dan barat itu suatu kebajikan, akan tetapi sesungguhnya kebajikan itu ialah beriman kepada Allah, hari kemudian, malaikat-malaikat, kitab-kitab, nabi-nabi dan memberikan harta yang dicintainya kepada kerabatnya, anak-anak yatim, orang-orang miskin, musafir (yang memerlukan pertolongan) dan orang-orang yang meminta-minta; dan (memerdekakan) hamba sahaya, mendirikan shalat, dan menunaikan zakat; dan orang-orang yang menepati janjinya apabila ia berjanji, dan orang-orang yang sabar dalam kesempitan, penderitaan dan dalam peperangan. Mereka itulah orang-orang yang benar (imannya); dan mereka itulah orang-orang yang bertakwa.'),
  ('id.indonesian', 2, 178, 'Hai orang-orang yang beriman, diwajibkan atas kamu qishaash berkenaan dengan orang-orang yang dibunuh; orang merdeka dengan orang merdeka, hamba dengan hamba, dan wanita dengan wanita. Maka barangsiapa yang mendapat suatu pemaafan dari saudaranya, hendaklah (yang memaafkan) mengikuti dengan cara yang baik, dan hendaklah (yang diberi maaf) membayar (diat) kepada yang memberi maaf dengan cara yang baik (pula). Yang demikian itu adalah suatu keringanan dari Tuhan kamu dan suatu rahmat. Barangsiapa yang melampaui batas sesudah itu, maka baginya siksa yang sangat pedih.'),
  ('id.indonesian', 2, 179, 'Dan dalam qishaash itu ada (jaminan kelangsungan) hidup bagimu, hai orang-orang yang berakal, supaya kamu bertakwa.'),
  ('id.indonesian', 2, 180, 'Diwajibkan atas kamu, apabila seorang di antara kamu kedatangan (tanda-tanda) maut, jika ia meninggalkan harta yang banyak, berwasiat untuk ibu-bapak dan karib kerabatnya secara ma\'ruf, (ini adalah) kewajiban atas orang-orang yang bertakwa.'),
  ('id.indonesian', 2, 181, 'Maka barangsiapa yang mengubah wasiat itu, setelah ia mendengarnya, maka sesungguhnya dosanya adalah bagi orang-orang yang mengubahnya. Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 182, '(Akan tetapi) barangsiapa khawatir terhadap orang yang berwasiat itu, berlaku berat sebelah atau berbuat dosa, lalu ia mendamaikan antara mereka, maka tidaklah ada dosa baginya. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 2, 183, 'Hai orang-orang yang beriman, diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang-orang sebelum kamu agar kamu bertakwa,'),
  ('id.indonesian', 2, 184, '(yaitu) dalam beberapa hari yang tertentu. Maka barangsiapa diantara kamu ada yang sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa) sebanyak hari yang ditinggalkan itu pada hari-hari yang lain. Dan wajib bagi orang-orang yang berat menjalankannya (jika mereka tidak berpuasa) membayar fidyah, (yaitu): memberi makan seorang miskin. Barangsiapa yang dengan kerelaan hati mengerjakan kebajikan, maka itulah yang lebih baik baginya. Dan berpuasa lebih baik bagimu jika kamu mengetahui.'),
  ('id.indonesian', 2, 185, '(Beberapa hari yang ditentukan itu ialah) bulan Ramadhan, bulan yang di dalamnya diturunkan (permulaan) Al Quran sebagai petunjuk bagi manusia dan penjelasan-penjelasan mengenai petunjuk itu dan pembeda (antara yang hak dan yang bathil). Karena itu, barangsiapa di antara kamu hadir (di negeri tempat tinggalnya) di bulan itu, maka hendaklah ia berpuasa pada bulan itu, dan barangsiapa sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa), sebanyak hari yang ditinggalkannya itu, pada hari-hari yang lain. Allah menghendaki kemudahan bagimu, dan tidak menghendaki kesukaran bagimu. Dan hendaklah kamu mencukupkan bilangannya dan hendaklah kamu mengagungkan Allah atas petunjuk-Nya yang diberikan kepadamu, supaya kamu bersyukur.'),
  ('id.indonesian', 2, 186, 'Dan apabila hamba-hamba-Ku bertanya kepadamu tentang Aku, maka (jawablah), bahwasanya Aku adalah dekat. Aku mengabulkan permohonan orang yang berdoa apabila ia memohon kepada-Ku, maka hendaklah mereka itu memenuhi (segala perintah-Ku) dan hendaklah mereka beriman kepada-Ku, agar mereka selalu berada dalam kebenaran.'),
  ('id.indonesian', 2, 187, 'Dihalalkan bagi kamu pada malam hari bulan puasa bercampur dengan isteri-isteri kamu; mereka adalah pakaian bagimu, dan kamupun adalah pakaian bagi mereka. Allah mengetahui bahwasanya kamu tidak dapat menahan nafsumu, karena itu Allah mengampuni kamu dan memberi maaf kepadamu. Maka sekarang campurilah mereka dan ikutilah apa yang telah ditetapkan Allah untukmu, dan makan minumlah hingga terang bagimu benang putih dari benang hitam, yaitu fajar. Kemudian sempurnakanlah puasa itu sampai (datang) malam, (tetapi) janganlah kamu campuri mereka itu, sedang kamu beri\'tikaf dalam mesjid. Itulah larangan Allah, maka janganlah kamu mendekatinya. Demikianlah Allah menerangkan ayat-ayat-Nya kepada manusia, supaya mereka bertakwa.'),
  ('id.indonesian', 2, 188, 'Dan janganlah sebahagian kamu memakan harta sebahagian yang lain di antara kamu dengan jalan yang bathil dan (janganlah) kamu membawa (urusan) harta itu kepada hakim, supaya kamu dapat memakan sebahagian daripada harta benda orang lain itu dengan (jalan berbuat) dosa, padahal kamu mengetahui.'),
  ('id.indonesian', 2, 189, 'Mereka bertanya kepadamu tentang bulan sabit. Katakanlah: "Bulan sabit itu adalah tanda-tanda waktu bagi manusia dan (bagi ibadat) haji; Dan bukanlah kebajikan memasuki rumah-rumah dari belakangnya, akan tetapi kebajikan itu ialah kebajikan orang yang bertakwa. Dan masuklah ke rumah-rumah itu dari pintu-pintunya; dan bertakwalah kepada Allah agar kamu beruntung.'),
  ('id.indonesian', 2, 190, 'Dan perangilah di jalan Allah orang-orang yang memerangi kamu, (tetapi) janganlah kamu melampaui batas, karena sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas.'),
  ('id.indonesian', 2, 191, 'Dan bunuhlah mereka di mana saja kamu jumpai mereka, dan usirlah mereka dari tempat mereka telah mengusir kamu (Mekah); dan fitnah itu lebih besar bahayanya dari pembunuhan, dan janganlah kamu memerangi mereka di Masjidil Haram, kecuali jika mereka memerangi kamu di tempat itu. Jika mereka memerangi kamu (di tempat itu), maka bunuhlah mereka. Demikanlah balasan bagi orang-orang kafir.'),
  ('id.indonesian', 2, 192, 'Kemudian jika mereka berhenti (dari memusuhi kamu), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 2, 193, 'Dan perangilah mereka itu, sehingga tidak ada fitnah lagi dan (sehingga) ketaatan itu hanya semata-mata untuk Allah. Jika mereka berhenti (dari memusuhi kamu), maka tidak ada permusuhan (lagi), kecuali terhadap orang-orang yang zalim.'),
  ('id.indonesian', 2, 194, 'Bulan haram dengan bulan haram, dan pada sesuatu yang patut dihormati, berlaku hukum qishaash. Oleh sebab itu barangsiapa yang menyerang kamu, maka seranglah ia, seimbang dengan serangannya terhadapmu. Bertakwalah kepada Allah dan ketahuilah, bahwa Allah beserta orang-orang yang bertakwa.'),
  ('id.indonesian', 2, 195, 'Dan belanjakanlah (harta bendamu) di jalan Allah, dan janganlah kamu menjatuhkan dirimu sendiri ke dalam kebinasaan, dan berbuat baiklah, karena sesungguhnya Allah menyukai orang-orang yang berbuat baik.'),
  ('id.indonesian', 2, 196, 'Dan sempurnakanlah ibadah haji dan \'umrah karena Allah. Jika kamu terkepung (terhalang oleh musuh atau karena sakit), maka (sembelihlah) korban yang mudah didapat, dan jangan kamu mencukur kepalamu, sebelum korban sampai di tempat penyembelihannya. Jika ada di antaramu yang sakit atau ada gangguan di kepalanya (lalu ia bercukur), maka wajiblah atasnya berfid-yah, yaitu: berpuasa atau bersedekah atau berkorban. Apabila kamu telah (merasa) aman, maka bagi siapa yang ingin mengerjakan \'umrah sebelum haji (di dalam bulan haji), (wajiblah ia menyembelih) korban yang mudah didapat. Tetapi jika ia tidak menemukan (binatang korban atau tidak mampu), maka wajib berpuasa tiga hari dalam masa haji dan tujuh hari (lagi) apabila kamu telah pulang kembali. Itulah sepuluh (hari) yang sempurna. Demikian itu (kewajiban membayar fidyah) bagi orang-orang yang keluarganya tidak berada (di sekitar) Masjidil Haram (orang-orang yang bukan penduduk kota Mekah). Dan bertakwalah kepada Allah dan ketahuilah bahwa Allah sangat keras siksaan-Nya.'),
  ('id.indonesian', 2, 197, '(Musim) haji adalah beberapa bulan yang dimaklumi, barangsiapa yang menetapkan niatnya dalam bulan itu akan mengerjakan haji, maka tidak boleh rafats, berbuat fasik dan berbantah-bantahan di dalam masa mengerjakan haji. Dan apa yang kamu kerjakan berupa kebaikan, niscaya Allah mengetahuinya. Berbekallah, dan sesungguhnya sebaik-baik bekal adalah takwa dan bertakwalah kepada-Ku hai orang-orang yang berakal.'),
  ('id.indonesian', 2, 198, 'Tidak ada dosa bagimu untuk mencari karunia (rezeki hasil perniagaan) dari Tuhanmu. Maka apabila kamu telah bertolak dari \'Arafat, berdzikirlah kepada Allah di Masy\'arilharam. Dan berdzikirlah (dengan menyebut) Allah sebagaimana yang ditunjukkan-Nya kepadamu; dan sesungguhnya kamu sebelum itu benar-benar termasuk orang-orang yang sesat.'),
  ('id.indonesian', 2, 199, 'Kemudian bertolaklah kamu dari tempat bertolaknya orang-orang banyak (\'Arafah) dan mohonlah ampun kepada Allah; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 2, 200, 'Apabila kamu telah menyelesaikan ibadah hajimu, maka berdzikirlah dengan menyebut Allah, sebagaimana kamu menyebut-nyebut (membangga-banggakan) nenek moyangmu, atau (bahkan) berdzikirlah lebih banyak dari itu. Maka di antara manusia ada orang yang bendoa: "Ya Tuhan kami, berilah kami (kebaikan) di dunia", dan tiadalah baginya bahagian (yang menyenangkan) di akhirat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 2, 201, 'Dan di antara mereka ada orang yang berdoa: "Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat dan peliharalah kami dari siksa neraka".'),
  ('id.indonesian', 2, 202, 'Mereka itulah orang-orang yang mendapat bahagian daripada yang mereka usahakan; dan Allah sangat cepat perhitungan-Nya.'),
  ('id.indonesian', 2, 203, 'Dan berdzikirlah (dengan menyebut) Allah dalam beberapa hari yang berbilang. Barangsiapa yang ingin cepat berangkat (dari Mina) sesudah dua hari, maka tiada dosa baginya. Dan barangsiapa yang ingin menangguhkan (keberangkatannya dari dua hari itu), maka tidak ada dosa pula baginya, bagi orang yang bertakwa. Dan bertakwalah kepada Allah, dan ketahuilah, bahwa kamu akan dikumpulkan kepada-Nya.'),
  ('id.indonesian', 2, 204, 'Dan di antara manusia ada orang yang ucapannya tentang kehidupan dunia menarik hatimu, dan dipersaksikannya kepada Allah (atas kebenaran) isi hatinya, padahal ia adalah penantang yang paling keras.'),
  ('id.indonesian', 2, 205, 'Dan apabila ia berpaling (dari kamu), ia berjalan di bumi untuk mengadakan kerusakan padanya, dan merusak tanam-tanaman dan binatang ternak, dan Allah tidak menyukai kebinasaan.'),
  ('id.indonesian', 2, 206, 'Dan apabila dikatakan kepadanya: "Bertakwalah kepada Allah", bangkitlah kesombongannya yang menyebabkannya berbuat dosa. Maka cukuplah (balasannya) neraka Jahannam. Dan sungguh neraka Jahannam itu tempat tinggal yang seburuk-buruknya.'),
  ('id.indonesian', 2, 207, 'Dan di antara manusia ada orang yang mengorbankan dirinya karena mencari keridhaan Allah; dan Allah Maha Penyantun kepada hamba-hamba-Nya.'),
  ('id.indonesian', 2, 208, 'Hai orang-orang yang beriman, masuklah kamu ke dalam Islam keseluruhan, dan janganlah kamu turut langkah-langkah syaitan. Sesungguhnya syaitan itu musuh yang nyata bagimu.'),
  ('id.indonesian', 2, 209, 'Tetapi jika kamu menyimpang (dari jalan Allah) sesudah datang kepadamu bukti-bukti kebenaran, maka ketahuilah, bahwasanya Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 2, 210, 'Tiada yang mereka nanti-nantikan melainkan datangnya Allah dan malaikat (pada hari kiamat) dalam naungan awan, dan diputuskanlah perkaranya. Dan hanya kepada Allah dikembalikan segala urusan.'),
  ('id.indonesian', 2, 211, 'Tanyakanlah kepada Bani Israil: "Berapa banyaknya tanda-tanda (kebenaran) yang nyata, yang telah Kami berikan kepada mereka". Dan barangsiapa yang menukar nikmat Allah setelah datang nikmat itu kepadanya, maka sesungguhnya Allah sangat keras siksa-Nya.'),
  ('id.indonesian', 2, 212, 'Kehidupan dunia dijadikan indah dalam pandangan orang-orang kafir, dan mereka memandang hina orang-orang yang beriman. Padahal orang-orang yang bertakwa itu lebih mulia daripada mereka di hari kiamat. Dan Allah memberi rezeki kepada orang-orang yang dikehendaki-Nya tanpa batas.'),
  ('id.indonesian', 2, 213, 'Manusia itu adalah umat yang satu. (setelah timbul perselisihan), maka Allah mengutus para nabi, sebagai pemberi peringatan, dan Allah menurunkan bersama mereka Kitab yang benar, untuk memberi keputusan di antara manusia tentang perkara yang mereka perselisihkan. Tidaklah berselisih tentang Kitab itu melainkan orang yang telah didatangkan kepada mereka Kitab, yaitu setelah datang kepada mereka keterangan-keterangan yang nyata, karena dengki antara mereka sendiri. Maka Allah memberi petunjuk orang-orang yang beriman kepada kebenaran tentang hal yang mereka perselisihkann itu dengan kehendak-Nya. Dan Allah selalu memberi petunjuk orang yang dikehendaki-Nya kepada jalan yang lurus.'),
  ('id.indonesian', 2, 214, 'Apakah kamu mengira bahwa kamu akan masuk surga, padahal belum datang kepadamu (cobaan) sebagaimana halnya orang-orang terdahulu sebelum kamu? Mereka ditimpa oleh malapetaka dan kesengsaraan, serta digoncangkan (dengan bermacam-macam cobaan) sehingga berkatalah Rasul dan orang-orang yang beriman bersamanya: "Bilakah datangnya pertolongan Allah?" Ingatlah, sesungguhnya pertolongan Allah itu amat dekat.'),
  ('id.indonesian', 2, 215, 'Mereka bertanya tentang apa yang mereka nafkahkan. Jawablah: "Apa saja harta yang kamu nafkahkan hendaklah diberikan kepada ibu-bapak, kaum kerabat, anak-anak yatim, orang-orang miskin dan orang-orang yang sedang dalam perjalanan". Dan apa saja kebaikan yang kamu buat, maka sesungguhnya Allah Maha Mengetahuinya.'),
  ('id.indonesian', 2, 216, 'Diwajibkan atas kamu berperang, padahal berperang itu adalah sesuatu yang kamu benci. Boleh jadi kamu membenci sesuatu, padahal ia amat baik bagimu, dan boleh jadi (pula) kamu menyukai sesuatu, padahal ia amat buruk bagimu; Allah mengetahui, sedang kamu tidak mengetahui.'),
  ('id.indonesian', 2, 217, 'Mereka bertanya kepadamu tentang berperang pada bulan Haram. Katakanlah: "Berperang dalam bulan itu adalah dosa besar; tetapi menghalangi (manusia) dari jalan Allah, kafir kepada Allah, (menghalangi masuk) Masjidilharam dan mengusir penduduknya dari sekitarnya, lebih besar (dosanya) di sisi Allah. Dan berbuat fitnah lebih besar (dosanya) daripada membunuh. Mereka tidak henti-hentinya memerangi kamu sampai mereka (dapat) mengembalikan kamu dari agamamu (kepada kekafiran), seandainya mereka sanggup. Barangsiapa yang murtad di antara kamu dari agamanya, lalu dia mati dalam kekafiran, maka mereka itulah yang sia-sia amalannya di dunia dan di akhirat, dan mereka itulah penghuni neraka, mereka kekal di dalamnya.'),
  ('id.indonesian', 2, 218, 'Sesungguhnya orang-orang yang beriman, orang-orang yang berhijrah dan berjihad di jalan Allah, mereka itu mengharapkan rahmat Allah, dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 2, 219, 'Mereka bertanya kepadamu tentang khamar dan judi. Katakanlah: "Pada keduanya terdapat dosa yang besar dan beberapa manfaat bagi manusia, tetapi dosa keduanya lebih besar dari manfaatnya". Dan mereka bertanya kepadamu apa yang mereka nafkahkan. Katakanlah: "Yang lebih dari keperluan". Demikianlah Allah menerangkan ayat-ayat-Nya kepadamu supaya kamu berfikir,'),
  ('id.indonesian', 2, 220, 'tentang dunia dan akhirat. Dan mereka bertanya kepadamu tentang anak yatim, katakalah: "Mengurus urusan mereka secara patut adalah baik, dan jika kamu bergaul dengan mereka, maka mereka adalah saudaramu; dan Allah mengetahui siapa yang membuat kerusakan dari yang mengadakan perbaikan. Dan jikalau Allah menghendaki, niscaya Dia dapat mendatangkan kesulitan kepadamu. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 2, 221, 'Dan janganlah kamu menikahi wanita-wanita musyrik, sebelum mereka beriman. Sesungguhnya wanita budak yang mukmin lebih baik dari wanita musyrik, walaupun dia menarik hatimu. Dan janganlah kamu menikahkan orang-orang musyrik (dengan wanita-wanita mukmin) sebelum mereka beriman. Sesungguhnya budak yang mukmin lebih baik dari orang musyrik, walaupun dia menarik hatimu. Mereka mengajak ke neraka, sedang Allah mengajak ke surga dan ampunan dengan izin-Nya. Dan Allah menerangkan ayat-ayat-Nya (perintah-perintah-Nya) kepada manusia supaya mereka mengambil pelajaran.'),
  ('id.indonesian', 2, 222, 'Mereka bertanya kepadamu tentang haidh. Katakanlah: "Haidh itu adalah suatu kotoran". Oleh sebab itu hendaklah kamu menjauhkan diri dari wanita di waktu haidh; dan janganlah kamu mendekati mereka, sebelum mereka suci. Apabila mereka telah suci, maka campurilah mereka itu di tempat yang diperintahkan Allah kepadamu. Sesungguhnya Allah menyukai orang-orang yang bertaubat dan menyukai orang-orang yang mensucikan diri.'),
  ('id.indonesian', 2, 223, 'Isteri-isterimu adalah (seperti) tanah tempat kamu bercocok tanam, maka datangilah tanah tempat bercocok-tanammu itu bagaimana saja kamu kehendaki. Dan kerjakanlah (amal yang baik) untuk dirimu, dan bertakwalah kepada Allah dan ketahuilah bahwa kamu kelak akan menemui-Nya. Dan berilah kabar gembira orang-orang yang beriman.'),
  ('id.indonesian', 2, 224, 'Jangahlah kamu jadikan (nama) Allah dalam sumpahmu sebagai penghalang untuk berbuat kebajikan, bertakwa dan mengadakan ishlah di antara manusia. Dan Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 225, 'Allah tidak menghukum kamu disebabkan sumpahmu yang tidak dimaksud (untuk bersumpah), tetapi Allah menghukum kamu disebabkan (sumpahmu) yang disengaja (untuk bersumpah) oleh hatimu. Dan Allah Maha Pengampun lagi Maha Penyantun.'),
  ('id.indonesian', 2, 226, 'Kepada orang-orang yang meng-ilaa\' isterinya diberi tangguh empat bulan (lamanya). Kemudian jika mereka kembali (kepada isterinya), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 2, 227, 'Dan jika mereka berazam (bertetap hati untuk) talak, maka sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 228, 'Wanita-wanita yang ditalak handaklah menahan diri (menunggu) tiga kali quru\'. Tidak boleh mereka menyembunyikan apa yang diciptakan Allah dalam rahimnya, jika mereka beriman kepada Allah dan hari akhirat. Dan suami-suaminya berhak merujukinya dalam masa menanti itu, jika mereka (para suami) menghendaki ishlah. Dan para wanita mempunyai hak yang seimbang dengan kewajibannya menurut cara yang ma\'ruf. Akan tetapi para suami, mempunyai satu tingkatan kelebihan daripada isterinya. Dan Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 2, 229, 'Talak (yang dapat dirujuki) dua kali. Setelah itu boleh rujuk lagi dengan cara yang ma\'ruf atau menceraikan dengan cara yang baik. Tidak halal bagi kamu mengambil kembali sesuatu dari yang telah kamu berikan kepada mereka, kecuali kalau keduanya khawatir tidak akan dapat menjalankan hukum-hukum Allah. Jika kamu khawatir bahwa keduanya (suami isteri) tidak dapat menjalankan hukum-hukum Allah, maka tidak ada dosa atas keduanya tentang bayaran yang diberikan oleh isteri untuk menebus dirinya. Itulah hukum-hukum Allah, maka janganlah kamu melanggarnya. Barangsiapa yang melanggar hukum-hukum Allah mereka itulah orang-orang yang zalim.'),
  ('id.indonesian', 2, 230, 'Kemudian jika si suami mentalaknya (sesudah talak yang kedua), maka perempuan itu tidak lagi halal baginya hingga dia kawin dengan suami yang lain. Kemudian jika suami yang lain itu menceraikannya, maka tidak ada dosa bagi keduanya (bekas suami pertama dan isteri) untuk kawin kembali jika keduanya berpendapat akan dapat menjalankan hukum-hukum Allah. Itulah hukum-hukum Allah, diterangkan-Nya kepada kaum yang (mau) mengetahui.'),
  ('id.indonesian', 2, 231, 'Apabila kamu mentalak isteri-isterimu, lalu mereka mendekati akhir iddahnya, maka rujukilah mereka dengan cara yang ma\'ruf, atau ceraikanlah mereka dengan cara yang ma\'ruf (pula). Janganlah kamu rujuki mereka untuk memberi kemudharatan, karena dengan demikian kamu menganiaya mereka. Barangsiapa berbuat demikian, maka sungguh ia telah berbuat zalim terhadap dirinya sendiri. Janganlah kamu jadikan hukum-hukum Allah permainan, dan ingatlah nikmat Allah padamu, dan apa yang telah diturunkan Allah kepadamu yaitu Al Kitab dan Al Hikmah (As Sunnah). Allah memberi pengajaran kepadamu dengan apa yang diturunkan-Nya itu. Dan bertakwalah kepada Allah serta ketahuilah bahwasanya Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 2, 232, 'Apabila kamu mentalak isteri-isterimu, lalu habis masa iddahnya, maka janganlah kamu (para wali) menghalangi mereka kawin lagi dengan bakal suaminya, apabila telah terdapat kerelaan di antara mereka dengan cara yang ma\'ruf. Itulah yang dinasehatkan kepada orang-orang yang beriman di antara kamu kepada Allah dan hari kemudian. Itu lebih baik bagimu dan lebih suci. Allah mengetahui, sedang kamu tidak mengetahui.'),
  ('id.indonesian', 2, 233, 'Para ibu hendaklah menyusukan anak-anaknya selama dua tahun penuh, yaitu bagi yang ingin menyempurnakan penyusuan. Dan kewajiban ayah memberi makan dan pakaian kepada para ibu dengan cara ma\'ruf. Seseorang tidak dibebani melainkan menurut kadar kesanggupannya. Janganlah seorang ibu menderita kesengsaraan karena anaknya dan seorang ayah karena anaknya, dan warispun berkewajiban demikian. Apabila keduanya ingin menyapih (sebelum dua tahun) dengan kerelaan keduanya dan permusyawaratan, maka tidak ada dosa atas keduanya. Dan jika kamu ingin anakmu disusukan oleh orang lain, maka tidak ada dosa bagimu apabila kamu memberikan pembayaran menurut yang patut. Bertakwalah kamu kepada Allah dan ketahuilah bahwa Allah Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 234, 'Orang-orang yang meninggal dunia di antaramu dengan meninggalkan isteri-isteri (hendaklah para isteri itu) menangguhkan dirinya (ber\'iddah) empat bulan sepuluh hari. Kemudian apabila telah habis \'iddahnya, maka tiada dosa bagimu (para wali) membiarkan mereka berbuat terhadap diri mereka menurut yang patut. Allah mengetahui apa yang kamu perbuat.'),
  ('id.indonesian', 2, 235, 'Dan tidak ada dosa bagi kamu meminang wanita-wanita itu dengan sindiran atau kamu menyembunyikan (keinginan mengawini mereka) dalam hatimu. Allah mengetahui bahwa kamu akan menyebut-nyebut mereka, dalam pada itu janganlah kamu mengadakan janji kawin dengan mereka secara rahasia, kecuali sekedar mengucapkan (kepada mereka) perkataan yang ma\'ruf. Dan janganlah kamu berazam (bertetap hati) untuk beraqad nikah, sebelum habis \'iddahnya. Dan ketahuilah bahwasanya Allah mengetahui apa yang ada dalam hatimu; maka takutlah kepada-Nya, dan ketahuilah bahwa Allah Maha Pengampun lagi Maha Penyantun.'),
  ('id.indonesian', 2, 236, 'Tidak ada kewajiban membayar (mahar) atas kamu, jika kamu menceraikan isteri-isteri kamu sebelum kamu bercampur dengan mereka dan sebelum kamu menentukan maharnya. Dan hendaklah kamu berikan suatu mut\'ah (pemberian) kepada mereka. Orang yang mampu menurut kemampuannya dan orang yang miskin menurut kemampuannya (pula), yaitu pemberian menurut yang patut. Yang demikian itu merupakan ketentuan bagi orang-orang yang berbuat kebajikan.'),
  ('id.indonesian', 2, 237, 'Jika kamu menceraikan isteri-isterimu sebelum kamu bercampur dengan mereka, padahal sesungguhnya kamu sudah menentukan maharnya, maka bayarlah seperdua dari mahar yang telah kamu tentukan itu, kecuali jika isteri-isterimu itu memaafkan atau dimaafkan oleh orang yang memegang ikatan nikah, dan pemaafan kamu itu lebih dekat kepada takwa. Dan janganlah kamu melupakan keutamaan di antara kamu. Sesungguhnya Allah Maha Melihat segala apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 238, 'Peliharalah semua shalat(mu), dan (peliharalah) shalat wusthaa. Berdirilah untuk Allah (dalam shalatmu) dengan khusyu\'.'),
  ('id.indonesian', 2, 239, 'Jika kamu dalam keadaan takut (bahaya), maka shalatlah sambil berjalan atau berkendaraan. Kemudian apabila kamu telah aman, maka sebutlah Allah (shalatlah), sebagaimana Allah telah mengajarkan kepada kamu apa yang belum kamu ketahui.'),
  ('id.indonesian', 2, 240, 'Dan orang-orang yang akan meninggal dunia di antara kamu dan meninggalkan isteri, hendaklah berwasiat untuk isteri-isterinya, (yaitu) diberi nafkah hingga setahun lamanya dan tidak disuruh pindah (dari rumahnya). Akan tetapi jika mereka pindah (sendiri), maka tidak ada dosa bagimu (wali atau waris dari yang meninggal) membiarkan mereka berbuat yang ma\'ruf terhadap diri mereka. Dan Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 2, 241, 'Kepada wanita-wanita yang diceraikan (hendaklah diberikan oleh suaminya) mut\'ah menurut yang ma\'ruf, sebagai suatu kewajiban bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 2, 242, 'Demikianlah Allah menerangkan kepadamu ayat-ayat-Nya (hukum-hukum-Nya) supaya kamu memahaminya.'),
  ('id.indonesian', 2, 243, 'Apakah kamu tidak memperhatikan orang-orang yang ke luar dari kampung halaman mereka, sedang mereka beribu-ribu (jumlahnya) karena takut mati; maka Allah berfirman kepada mereka: "Matilah kamu", kemudian Allah menghidupkan mereka. Sesungguhnya Allah mempunyai karunia terhadap manusia tetapi kebanyakan manusia tidak bersyukur.'),
  ('id.indonesian', 2, 244, 'Dan berperanglah kamu sekalian di jalan Allah, dan ketahuilah sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 245, 'Siapakah yang mau memberi pinjaman kepada Allah, pinjaman yang baik (menafkahkan hartanya di jalan Allah), maka Allah akan meperlipat gandakan pembayaran kepadanya dengan lipat ganda yang banyak. Dan Allah menyempitkan dan melapangkan (rezeki) dan kepada-Nya-lah kamu dikembalikan.'),
  ('id.indonesian', 2, 246, 'Apakah kamu tidak memperhatikan pemuka-pemuka Bani Israil sesudah Nabi Musa, yaitu ketika mereka berkata kepada seorang Nabi mereka: "Angkatlah untuk kami seorang raja supaya kami berperang (di bawah pimpinannya) di jalan Allah". Nabi mereka menjawab: "Mungkin sekali jika kamu nanti diwajibkan berperang, kamu tidak akan berperang". Mereka menjawab: "Mengapa kami tidak mau berperang di jalan Allah, padahal sesungguhnya kami telah diusir dari anak-anak kami?". Maka tatkala perang itu diwajibkan atas mereka, merekapun berpaling, kecuali beberapa saja di antara mereka. Dan Allah Maha Mengetahui siapa orang-orang yang zalim.'),
  ('id.indonesian', 2, 247, 'Nabi mereka mengatakan kepada mereka: "Sesungguhnya Allah telah mengangkat Thalut menjadi rajamu". Mereka menjawab: "Bagaimana Thalut memerintah kami, padahal kami lebih berhak mengendalikan pemerintahan daripadanya, sedang diapun tidak diberi kekayaan yang cukup banyak?" Nabi (mereka) berkata: "Sesungguhnya Allah telah memilih rajamu dan menganugerahinya ilmu yang luas dan tubuh yang perkasa". Allah memberikan pemerintahan kepada siapa yang dikehendaki-Nya. Dan Allah Maha Luas pemberian-Nya lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 248, 'Dan Nabi mereka mengatakan kepada mereka: "Sesungguhnya tanda ia akan menjadi raja, ialah kembalinya tabut kepadamu, di dalamnya terdapat ketenangan dari Tuhanmu dan sisa dari peninggalan keluarga Musa dan keluarga Harun; tabut itu dibawa malaikat. Sesungguhnya pada yang demikian itu terdapat tanda bagimu, jika kamu orang yang beriman.'),
  ('id.indonesian', 2, 249, 'Maka tatkala Thalut keluar membawa tentaranya, ia berkata: "Sesungguhnya Allah akan menguji kamu dengan suatu sungai. Maka siapa di antara kamu meminum airnya; bukanlah ia pengikutku. Dan barangsiapa tiada meminumnya, kecuali menceduk seceduk tangan, maka dia adalah pengikutku". Kemudian mereka meminumnya kecuali beberapa orang di antara mereka. Maka tatkala Thalut dan orang-orang yang beriman bersama dia telah menyeberangi sungai itu, orang-orang yang telah minum berkata: "Tak ada kesanggupan kami pada hari ini untuk melawan Jalut dan tentaranya". Orang-orang yang meyakini bahwa mereka akan menemui Allah, berkata: "Berapa banyak terjadi golongan yang sedikit dapat mengalahkan golongan yang banyak dengan izin Allah. Dan Allah beserta orang-orang yang sabar".'),
  ('id.indonesian', 2, 250, 'Tatkala Jalut dan tentaranya telah nampak oleh mereka, merekapun (Thalut dan tentaranya) berdoa: "Ya Tuhan kami, tuangkanlah kesabaran atas diri kami, dan kokohkanlah pendirian kami dan tolonglah kami terhadap orang-orang kafir".'),
  ('id.indonesian', 2, 251, 'Mereka (tentara Thalut) mengalahkan tentara Jalut dengan izin Allah dan (dalam peperangan itu) Daud membunuh Jalut, kemudian Allah memberikan kepadanya (Daud) pemerintahan dan hikmah (sesudah meninggalnya Thalut) dan mengajarkan kepadanya apa yang dikehendaki-Nya. Seandainya Allah tidak menolak (keganasan) sebahagian umat manusia dengan sebagian yang lain, pasti rusaklah bumi ini. Tetapi Allah mempunyai karunia (yang dicurahkan) atas semesta alam.'),
  ('id.indonesian', 2, 252, 'Itu adalah ayat-ayat dari Allah, Kami bacakan kepadamu dengan hak (benar) dan sesungguhnya kamu benar-benar salah seorang di antara nabi-nabi yang diutus.'),
  ('id.indonesian', 2, 253, 'Rasul-rasul itu Kami lebihkan sebagian (dari) mereka atas sebagian yang lain. Di antara mereka ada yang Allah berkata-kata (langsung dengan dia) dan sebagiannya Allah meninggikannya beberapa derajat. Dan Kami berikan kepada Isa putera Maryam beberapa mukjizat serta Kami perkuat dia dengan Ruhul Qudus. Dan kalau Allah menghendaki, niscaya tidaklah berbunuh-bunuhan orang-orang (yang datang) sesudah rasul-rasul itu, sesudah datang kepada mereka beberapa macam keterangan, akan tetapi mereka berselisih, maka ada di antara mereka yang beriman dan ada (pula) di antara mereka yang kafir. Seandainya Allah menghendaki, tidaklah mereka berbunuh-bunuhan. Akan tetapi Allah berbuat apa yang dikehendaki-Nya.'),
  ('id.indonesian', 2, 254, 'Hai orang-orang yang beriman, belanjakanlah (di jalan Allah) sebagian dari rezeki yang telah Kami berikan kepadamu sebelum datang hari yang pada hari itu tidak ada lagi jual beli dan tidak ada lagi syafa\'at. Dan orang-orang kafir itulah orang-orang yang zalim.'),
  ('id.indonesian', 2, 255, 'Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia Yang Hidup kekal lagi terus menerus mengurus (makhluk-Nya); tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafa\'at di sisi Allah tanpa izin-Nya? Allah mengetahui apa-apa yang di hadapan mereka dan di belakang mereka, dan mereka tidak mengetahui apa-apa dari ilmu Allah melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi. Dan Allah tidak merasa berat memelihara keduanya, dan Allah Maha Tinggi lagi Maha Besar.'),
  ('id.indonesian', 2, 256, 'Tidak ada paksaan untuk (memasuki) agama (Islam); sesungguhnya telah jelas jalan yang benar daripada jalan yang sesat. Karena itu barangsiapa yang ingkar kepada Thaghut dan beriman kepada Allah, maka sesungguhnya ia telah berpegang kepada buhul tali yang amat kuat yang tidak akan putus. Dan Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 257, 'Allah Pelindung orang-orang yang beriman; Dia mengeluarkan mereka dari kegelapan (kekafiran) kepada cahaya (iman). Dan orang-orang yang kafir, pelindung-pelindungnya ialah syaitan, yang mengeluarkan mereka daripada cahaya kepada kegelapan (kekafiran). Mereka itu adalah penghuni neraka; mereka kekal di dalamnya.'),
  ('id.indonesian', 2, 258, 'Apakah kamu tidak memperhatikan orang yang mendebat Ibrahim tentang Tuhannya (Allah) karena Allah telah memberikan kepada orang itu pemerintahan (kekuasaan). Ketika Ibrahim mengatakan: "Tuhanku ialah Yang menghidupkan dan mematikan," orang itu berkata: "Saya dapat menghidupkan dan mematikan". Ibrahim berkata: "Sesungguhnya Allah menerbitkan matahari dari timur, maka terbitkanlah dia dari barat," lalu terdiamlah orang kafir itu; dan Allah tidak memberi petunjuk kepada orang-orang yang zalim.'),
  ('id.indonesian', 2, 259, 'Atau apakah (kamu tidak memperhatikan) orang yang melalui suatu negeri yang (temboknya) telah roboh menutupi atapnya. Dia berkata: "Bagaimana Allah menghidupkan kembali negeri ini setelah hancur?" Maka Allah mematikan orang itu seratus tahun, kemudian menghidupkannya kembali. Allah bertanya: "Berapakah lamanya kamu tinggal di sini?" Ia menjawab: "Saya tinggal di sini sehari atau setengah hari". Allah berfirman: "Sebenarnya kamu telah tinggal di sini seratus tahun lamanya; lihatlah kepada makanan dan minumanmu yang belum lagi beubah; dan lihatlah kepada keledai kamu (yang telah menjadi tulang belulang); Kami akan menjadikan kamu tanda kekuasaan Kami bagi manusia; dan lihatlah kepada tulang belulang keledai itu, kemudian Kami menyusunnya kembali, kemudian Kami membalutnya dengan daging". Maka tatkala telah nyata kepadanya (bagaimana Allah menghidupkan yang telah mati) diapun berkata: "Saya yakin bahwa Allah Maha Kuasa atas segala sesuatu".'),
  ('id.indonesian', 2, 260, 'Dan (ingatlah) ketika Ibrahim berkata: "Ya Tuhanku, perlihatkanlah kepadaku bagaimana Engkau menghidupkan orang-orang mati". Allah berfirman: "Belum yakinkah kamu?" Ibrahim menjawab: "Aku telah meyakinkannya, akan tetapi agar hatiku tetap mantap (dengan imanku) Allah berfirman: "(Kalau demikian) ambillah empat ekor burung, lalu cincanglah semuanya olehmu. (Allah berfirman): "Lalu letakkan diatas tiap-tiap satu bukit satu bagian dari bagian-bagian itu, kemudian panggillah mereka, niscaya mereka datang kepadamu dengan segera". Dan ketahuilah bahwa Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 2, 261, 'Perumpamaan (nafkah yang dikeluarkan oleh) orang-orang yang menafkahkan hartanya di jalan Allah adalah serupa dengan sebutir benih yang menumbuhkan tujuh bulir, pada tiap-tiap bulir seratus biji. Allah melipat gandakan (ganjaran) bagi siapa yang Dia kehendaki. Dan Allah Maha Luas (karunia-Nya) lagi Maha Mengetahui.'),
  ('id.indonesian', 2, 262, 'Orang-orang yang menafkahkan hartanya di jalan Allah, kemudian mereka tidak mengiringi apa yang dinafkahkannya itu dengan menyebut-nyebut pemberiannya dan dengan tidak menyakiti (perasaan si penerima), mereka memperoleh pahala di sisi Tuhan mereka. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 2, 263, 'Perkataan yang baik dan pemberian maaf lebih baik dari sedekah yang diiringi dengan sesuatu yang menyakitkan (perasaan si penerima). Allah Maha Kaya lagi Maha Penyantun.'),
  ('id.indonesian', 2, 264, 'Hai orang-orang yang beriman, janganlah kamu menghilangkan (pahala) sedekahmu dengan menyebut-nyebutnya dan menyakiti (perasaan si penerima), seperti orang yang menafkahkan hartanya karena riya kepada manusia dan dia tidak beriman kepada Allah dan hari kemudian. Maka perumpamaan orang itu seperti batu licin yang di atasnya ada tanah, kemudian batu itu ditimpa hujan lebat, lalu menjadilah dia bersih (tidak bertanah). Mereka tidak menguasai sesuatupun dari apa yang mereka usahakan; dan Allah tidak memberi petunjuk kepada orang-orang yang kafir.'),
  ('id.indonesian', 2, 265, 'Dan perumpamaan orang-orang yang membelanjakan hartanya karena mencari keridhaan Allah dan untuk keteguhan jiwa mereka, seperti sebuah kebun yang terletak di dataran tinggi yang disiram oleh hujan lebat, maka kebun itu menghasilkan buahnya dua kali lipat. Jika hujan lebat tidak menyiraminya, maka hujan gerimis (pun memadai). Dan Allah Maha Melihat apa yang kamu perbuat.'),
  ('id.indonesian', 2, 266, 'Apakah ada salah seorang di antaramu yang ingin mempunyai kebun kurma dan anggur yang mengalir di bawahnya sungai-sungai; dia mempunyai dalam kebun itu segala macam buah-buahan, kemudian datanglah masa tua pada orang itu sedang dia mempunyai keturunan yang masih kecil-kecil. Maka kebun itu ditiup angin keras yang mengandung api, lalu terbakarlah. Demikianlah Allah menerangkan ayat-ayat-Nya kepada kamu supaya kamu memikirkannya.'),
  ('id.indonesian', 2, 267, 'Hai orang-orang yang beriman, nafkahkanlah (di jalan allah) sebagian dari hasil usahamu yang baik-baik dan sebagian dari apa yang Kami keluarkan dari bumi untuk kamu. Dan janganlah kamu memilih yang buruk-buruk lalu kamu menafkahkan daripadanya, padahal kamu sendiri tidak mau mengambilnya melainkan dengan memincingkan mata terhadapnya. Dan ketahuilah, bahwa Allah Maha Kaya lagi Maha Terpuji.'),
  ('id.indonesian', 2, 268, 'Syaitan menjanjikan (menakut-nakuti) kamu dengan kemiskinan dan menyuruh kamu berbuat kejahatan (kikir); sedang Allah menjadikan untukmu ampunan daripada-Nya dan karunia. Dan Allah Maha Luas (karunia-Nya) lagi Maha Mengatahui.'),
  ('id.indonesian', 2, 269, 'Allah menganugerahkan al hikmah (kefahaman yang dalam tentang Al Quran dan As Sunnah) kepada siapa yang dikehendaki-Nya. Dan barangsiapa yang dianugerahi hikmah, ia benar-benar telah dianugerahi karunia yang banyak. Dan hanya orang-orang yang berakallah yang dapat mengambil pelajaran (dari firman Allah).'),
  ('id.indonesian', 2, 270, 'Apa saja yang kamu nafkahkan atau apa saja yang kamu nazarkan, maka sesungguhnya Allah mengetahuinya. Orang-orang yang berbuat zalim tidak ada seorang penolongpun baginya.'),
  ('id.indonesian', 2, 271, 'Jika kamu menampakkan sedekah(mu), maka itu adalah baik sekali. Dan jika kamu menyembunyikannya dan kamu berikan kepada orang-orang fakir, maka menyembunyikan itu lebih baik bagimu. Dan Allah akan menghapuskan dari kamu sebagian kesalahan-kesalahanmu; dan Allah mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 272, 'Bukanlah kewajibanmu menjadikan mereka mendapat petunjuk, akan tetapi Allah-lah yang memberi petunjuk (memberi taufiq) siapa yang dikehendaki-Nya. Dan apa saja harta yang baik yang kamu nafkahkan (di jalan allah), maka pahalanya itu untuk kamu sendiri. Dan janganlah kamu membelanjakan sesuatu melainkan karena mencari keridhaan Allah. Dan apa saja harta yang baik yang kamu nafkahkan, niscaya kamu akan diberi pahalanya dengan cukup sedang kamu sedikitpun tidak akan dianiaya (dirugikan).'),
  ('id.indonesian', 2, 273, '(Berinfaqlah) kepada orang-orang fakir yang terikat (oleh jihad) di jalan Allah; mereka tidak dapat (berusaha) di bumi; orang yang tidak tahu menyangka mereka orang kaya karena memelihara diri dari minta-minta. Kamu kenal mereka dengan melihat sifat-sifatnya, mereka tidak meminta kepada orang secara mendesak. Dan apa saja harta yang baik yang kamu nafkahkan (di jalan Allah), maka sesungguhnya Allah Maha Mengatahui.'),
  ('id.indonesian', 2, 274, 'Orang-orang yang menafkahkan hartanya di malam dan di siang hari secara tersembunyi dan terang-terangan, maka mereka mendapat pahala di sisi Tuhannya. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 2, 275, 'Orang-orang yang makan (mengambil) riba tidak dapat berdiri melainkan seperti berdirinya orang yang kemasukan syaitan lantaran (tekanan) penyakit gila. Keadaan mereka yang demikian itu, adalah disebabkan mereka berkata (berpendapat), sesungguhnya jual beli itu sama dengan riba, padahal Allah telah menghalalkan jual beli dan mengharamkan riba. Orang-orang yang telah sampai kepadanya larangan dari Tuhannya, lalu terus berhenti (dari mengambil riba), maka baginya apa yang telah diambilnya dahulu (sebelum datang larangan); dan urusannya (terserah) kepada Allah. Orang yang kembali (mengambil riba), maka orang itu adalah penghuni-penghuni neraka; mereka kekal di dalamnya.'),
  ('id.indonesian', 2, 276, 'Allah memusnahkan riba dan menyuburkan sedekah. Dan Allah tidak menyukai setiap orang yang tetap dalam kekafiran, dan selalu berbuat dosa.'),
  ('id.indonesian', 2, 277, 'Sesungguhnya orang-orang yang beriman, mengerjakan amal saleh, mendirikan shalat dan menunaikan zakat, mereka mendapat pahala di sisi Tuhannya. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 2, 278, 'Hai orang-orang yang beriman, bertakwalah kepada Allah dan tinggalkan sisa riba (yang belum dipungut) jika kamu orang-orang yang beriman.'),
  ('id.indonesian', 2, 279, 'Maka jika kamu tidak mengerjakan (meninggalkan sisa riba), maka ketahuilah, bahwa Allah dan Rasul-Nya akan memerangimu. Dan jika kamu bertaubat (dari pengambilan riba), maka bagimu pokok hartamu; kamu tidak menganiaya dan tidak (pula) dianiaya.'),
  ('id.indonesian', 2, 280, 'Dan jika (orang yang berhutang itu) dalam kesukaran, maka berilah tangguh sampai dia berkelapangan. Dan menyedekahkan (sebagian atau semua utang) itu, lebih baik bagimu, jika kamu mengetahui.'),
  ('id.indonesian', 2, 281, 'Dan peliharalah dirimu dari (azab yang terjadi pada) hari yang pada waktu itu kamu semua dikembalikan kepada Allah. Kemudian masing-masing diri diberi balasan yang sempurna terhadap apa yang telah dikerjakannya, sedang mereka sedikitpun tidak dianiaya (dirugikan).'),
  ('id.indonesian', 2, 282, 'Hai orang-orang yang beriman, apabila kamu bermu\'amalah tidak secara tunai untuk waktu yang ditentukan, hendaklah kamu menuliskannya. Dan hendaklah seorang penulis di antara kamu menuliskannya dengan benar. Dan janganlah penulis enggan menuliskannya sebagaimana Allah mengajarkannya, meka hendaklah ia menulis, dan hendaklah orang yang berhutang itu mengimlakkan (apa yang akan ditulis itu), dan hendaklah ia bertakwa kepada Allah Tuhannya, dan janganlah ia mengurangi sedikitpun daripada hutangnya. Jika yang berhutang itu orang yang lemah akalnya atau lemah (keadaannya) atau dia sendiri tidak mampu mengimlakkan, maka hendaklah walinya mengimlakkan dengan jujur. Dan persaksikanlah dengan dua orang saksi dari orang-orang lelaki (di antaramu). Jika tak ada dua oang lelaki, maka (boleh) seorang lelaki dan dua orang perempuan dari saksi-saksi yang kamu ridhai, supaya jika seorang lupa maka yang seorang mengingatkannya. Janganlah saksi-saksi itu enggan (memberi keterangan) apabila mereka dipanggil; dan janganlah kamu jemu menulis hutang itu, baik kecil maupun besar sampai batas waktu membayarnya. Yang demikian itu, lebih adil di sisi Allah dan lebih menguatkan persaksian dan lebih dekat kepada tidak (menimbulkan) keraguanmu. (Tulislah mu\'amalahmu itu), kecuali jika mu\'amalah itu perdagangan tunai yang kamu jalankan di antara kamu, maka tidak ada dosa bagi kamu, (jika) kamu tidak menulisnya. Dan persaksikanlah apabila kamu berjual beli; dan janganlah penulis dan saksi saling sulit menyulitkan. Jika kamu lakukan (yang demikian), maka sesungguhnya hal itu adalah suatu kefasikan pada dirimu. Dan bertakwalah kepada Allah; Allah mengajarmu; dan Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 2, 283, 'Jika kamu dalam perjalanan (dan bermu\'amalah tidak secara tunai) sedang kamu tidak memperoleh seorang penulis, maka hendaklah ada barang tanggungan yang dipegang (oleh yang berpiutang). Akan tetapi jika sebagian kamu mempercayai sebagian yang lain, maka hendaklah yang dipercayai itu menunaikan amanatnya (hutangnya) dan hendaklah ia bertakwa kepada Allah Tuhannya; dan janganlah kamu (para saksi) menyembunyikan persaksian. Dan barangsiapa yang menyembunyikannya, maka sesungguhnya ia adalah orang yang berdosa hatinya; dan Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 2, 284, 'Kepunyaan Allah-lah segala apa yang ada di langit dan apa yang ada di bumi. Dan jika kamu melahirkan apa yang ada di dalam hatimu atau kamu menyembunyikan, niscaya Allah akan membuat perhitungan dengan kamu tentang perbuatanmu itu. Maka Allah mengampuni siapa yang dikehendaki-Nya dan menyiksa siapa yang dikehendaki-Nya; dan Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 2, 285, 'Rasul telah beriman kepada Al Quran yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang yang beriman. Semuanya beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya dan rasul-rasul-Nya. (Mereka mengatakan): "Kami tidak membeda-bedakan antara seseorangpun (dengan yang lain) dari rasul-rasul-Nya", dan mereka mengatakan: "Kami dengar dan kami taat". (Mereka berdoa): "Ampunilah kami ya Tuhan kami dan kepada Engkaulah tempat kembali".'),
  ('id.indonesian', 2, 286, 'Allah tidak membebani seseorang melainkan sesuai dengan kesanggupannya. Ia mendapat pahala (dari kebajikan) yang diusahakannya dan ia mendapat siksa (dari kejahatan) yang dikerjakannya. (Mereka berdoa): "Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau kami tersalah. Ya Tuhan kami, janganlah Engkau bebankan kepada kami beban yang berat sebagaimana Engkau bebankan kepada orang-orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tak sanggup kami memikulnya. Beri maaflah kami; ampunilah kami; dan rahmatilah kami. Engkaulah Penolong kami, maka tolonglah kami terhadap kaum yang kafir".')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (2, 194, 201, 'ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌۭ ۚ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 30, 2, 12, 0),
  (2, 195, 202, 'وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ ۛ وَأَحْسِنُوٓا۟ ۛ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 30, 2, 12, 0),
  (2, 196, 203, 'وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۖ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًۭى مِّن رَّأْسِهِۦ فَفِدْيَةٌۭ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍۢ ۚ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ ۚ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍۢ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ ۗ تِلْكَ عَشَرَةٌۭ كَامِلَةٌۭ ۗ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 30, 2, 12, 0),
  (2, 197, 204, 'ٱلْحَجُّ أَشْهُرٌۭ مَّعْلُومَٰتٌۭ ۚ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍۢ يَعْلَمْهُ ٱللَّهُ ۗ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ ۚ وَٱتَّقُونِ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ', 31, 2, 12, 0),
  (2, 198, 205, 'لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًۭا مِّن رَّبِّكُمْ ۚ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍۢ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ ۖ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ', 31, 2, 12, 0),
  (2, 199, 206, 'ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 31, 2, 12, 0),
  (2, 200, 207, 'فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًۭا ۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْءَاخِرَةِ مِنْ خَلَٰقٍۢ', 31, 2, 12, 0),
  (2, 201, 208, 'وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْءَاخِرَةِ حَسَنَةًۭ وَقِنَا عَذَابَ ٱلنَّارِ', 31, 2, 12, 0),
  (2, 202, 209, 'أُو۟لَٰٓئِكَ لَهُمْ نَصِيبٌۭ مِّمَّا كَسَبُوا۟ ۚ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 31, 2, 12, 0),
  (2, 203, 210, '۞ وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍۢ مَّعْدُودَٰتٍۢ ۚ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ ۚ لِمَنِ ٱتَّقَىٰ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ', 32, 2, 13, 0),
  (2, 204, 211, 'وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ', 32, 2, 13, 0),
  (2, 205, 212, 'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', 32, 2, 13, 0),
  (2, 206, 213, 'وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ ۚ فَحَسْبُهُۥ جَهَنَّمُ ۚ وَلَبِئْسَ ٱلْمِهَادُ', 32, 2, 13, 0),
  (2, 207, 214, 'وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 32, 2, 13, 0),
  (2, 208, 215, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةًۭ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ', 32, 2, 13, 0),
  (2, 209, 216, 'فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 32, 2, 13, 0),
  (2, 210, 217, 'هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍۢ مِّنَ ٱلْغَمَامِ وَٱلْمَلَٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 32, 2, 13, 0),
  (2, 211, 218, 'سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍۢ ۗ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 33, 2, 13, 0),
  (2, 212, 219, 'زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ ۘ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍۢ', 33, 2, 13, 0),
  (2, 213, 220, 'كَانَ ٱلنَّاسُ أُمَّةًۭ وَٰحِدَةًۭ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّۦنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ ۚ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ ۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ ۗ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍ', 33, 2, 13, 0),
  (2, 214, 221, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم ۖ مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ ۗ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌۭ', 33, 2, 13, 0),
  (2, 215, 222, 'يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ ۖ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍۢ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ ۗ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍۢ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌۭ', 33, 2, 13, 0),
  (2, 216, 223, 'كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌۭ لَّكُمْ ۖ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًۭٔا وَهُوَ خَيْرٌۭ لَّكُمْ ۖ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًۭٔا وَهُوَ شَرٌّۭ لَّكُمْ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 34, 2, 13, 0),
  (2, 217, 224, 'يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍۢ فِيهِ ۖ قُلْ قِتَالٌۭ فِيهِ كَبِيرٌۭ ۖ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ ۚ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ ۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَٰعُوا۟ ۚ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌۭ فَأُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۖ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 34, 2, 13, 0),
  (2, 218, 225, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 34, 2, 13, 0),
  (2, 219, 226, '۞ يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ ۖ قُلْ فِيهِمَآ إِثْمٌۭ كَبِيرٌۭ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا ۗ وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 34, 2, 14, 0),
  (2, 220, 227, 'فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۗ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَٰمَىٰ ۖ قُلْ إِصْلَاحٌۭ لَّهُمْ خَيْرٌۭ ۖ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ ۚ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ ۚ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 35, 2, 14, 0),
  (2, 221, 228, 'وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَٰتِ حَتَّىٰ يُؤْمِنَّ ۚ وَلَأَمَةٌۭ مُّؤْمِنَةٌ خَيْرٌۭ مِّن مُّشْرِكَةٍۢ وَلَوْ أَعْجَبَتْكُمْ ۗ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ ۚ وَلَعَبْدٌۭ مُّؤْمِنٌ خَيْرٌۭ مِّن مُّشْرِكٍۢ وَلَوْ أَعْجَبَكُمْ ۗ أُو۟لَٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ ۖ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ ۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 35, 2, 14, 0),
  (2, 222, 229, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ۖ قُلْ هُوَ أَذًۭى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', 35, 2, 14, 0),
  (2, 223, 230, 'نِسَآؤُكُمْ حَرْثٌۭ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ ۖ وَقَدِّمُوا۟ لِأَنفُسِكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَٰقُوهُ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 35, 2, 14, 0),
  (2, 224, 231, 'وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةًۭ لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 35, 2, 14, 0),
  (2, 225, 232, 'لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌۭ', 36, 2, 14, 0),
  (2, 226, 233, 'لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍۢ ۖ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 36, 2, 14, 0),
  (2, 227, 234, 'وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 36, 2, 14, 0),
  (2, 228, 235, 'وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍۢ ۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَٰحًۭا ۚ وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ ۚ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌۭ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 36, 2, 14, 0),
  (2, 229, 236, 'ٱلطَّلَٰقُ مَرَّتَانِ ۖ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍۢ ۗ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 36, 2, 14, 0),
  (2, 230, 237, 'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ ۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ ۗ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍۢ يَعْلَمُونَ', 36, 2, 14, 0),
  (2, 231, 238, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍۢ ۚ وَلَا تُمْسِكُوهُنَّ ضِرَارًۭا لِّتَعْتَدُوا۟ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ وَلَا تَتَّخِذُوٓا۟ ءَايَٰتِ ٱللَّهِ هُزُوًۭا ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ ۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 37, 2, 14, 0),
  (2, 232, 239, 'وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ۗ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۗ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ ۗ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 37, 2, 14, 0),
  (2, 233, 240, '۞ وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ۖ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ ۚ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ ۚ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا ۚ لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌۭ لَّهُۥ بِوَلَدِهِۦ ۚ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ ۗ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍۢ مِّنْهُمَا وَتَشَاوُرٍۢ فَلَا جُنَاحَ عَلَيْهِمَا ۗ وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 37, 2, 15, 0),
  (2, 234, 241, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًۭا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍۢ وَعَشْرًۭا ۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 38, 2, 15, 0),
  (2, 235, 242, 'وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ ۚ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًۭا مَّعْرُوفًۭا ۚ وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَٰبُ أَجَلَهُۥ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌۭ', 38, 2, 15, 0),
  (2, 236, 243, 'لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةًۭ ۚ وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَٰعًۢا بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُحْسِنِينَ', 38, 2, 15, 0),
  (2, 237, 244, 'وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةًۭ فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ ۚ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ ۚ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ ۚ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ', 38, 2, 15, 0),
  (2, 238, 245, 'حَٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَٰنِتِينَ', 39, 2, 15, 0),
  (2, 239, 246, 'فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًۭا ۖ فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ', 39, 2, 15, 0),
  (2, 240, 247, 'وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًۭا وَصِيَّةًۭ لِّأَزْوَٰجِهِم مَّتَٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍۢ ۚ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍۢ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌۭ', 39, 2, 15, 0),
  (2, 241, 248, 'وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ ۖ حَقًّا عَلَى ٱلْمُتَّقِينَ', 39, 2, 15, 0),
  (2, 242, 249, 'كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 39, 2, 15, 0),
  (2, 243, 250, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَٰهُمْ ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 39, 2, 16, 0),
  (2, 244, 251, 'وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 39, 2, 16, 0),
  (2, 245, 252, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًۭا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضْعَافًۭا كَثِيرَةًۭ ۚ وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ', 39, 2, 16, 0),
  (2, 246, 253, 'أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّۢ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًۭا نُّقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ۖ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَٰتِلُوا۟ ۖ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَٰرِنَا وَأَبْنَآئِنَا ۖ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًۭا مِّنْهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 40, 2, 16, 0),
  (2, 247, 254, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًۭا ۚ قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةًۭ مِّنَ ٱلْمَالِ ۚ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةًۭ فِى ٱلْعِلْمِ وَٱلْجِسْمِ ۖ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 40, 2, 16, 0),
  (2, 248, 255, 'وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌۭ مِّن رَّبِّكُمْ وَبَقِيَّةٌۭ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ٱلْمَلَٰٓئِكَةُ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 40, 2, 16, 0),
  (2, 249, 256, 'فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍۢ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ ۚ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًۭا مِّنْهُمْ ۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ ۚ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍۢ قَلِيلَةٍ غَلَبَتْ فِئَةًۭ كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 41, 2, 16, 0),
  (2, 250, 257, 'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًۭا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 41, 2, 16, 0),
  (2, 251, 258, 'فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍۢ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ', 41, 2, 16, 0),
  (2, 252, 259, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۚ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ', 41, 2, 16, 0),
  (2, 253, 260, '۞ تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍۢ ۘ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍۢ ۚ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ ۗ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ ۚ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 42, 3, 17, 0),
  (2, 254, 261, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خُلَّةٌۭ وَلَا شَفَٰعَةٌۭ ۗ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ', 42, 3, 17, 0),
  (2, 255, 262, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌۭ وَلَا نَوْمٌۭ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍۢ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 42, 3, 17, 0),
  (2, 256, 263, 'لَآ إِكْرَاهَ فِى ٱلدِّينِ ۖ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ ۚ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 42, 3, 17, 0),
  (2, 257, 264, 'ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۖ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِ ۗ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 43, 3, 17, 0),
  (2, 258, 265, 'أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِۦمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِۦمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ ۖ قَالَ إِبْرَٰهِۦمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 43, 3, 17, 0),
  (2, 259, 266, 'أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍۢ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا ۖ فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍۢ ثُمَّ بَعَثَهُۥ ۖ قَالَ كَمْ لَبِثْتَ ۖ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍۢ ۖ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍۢ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ ۖ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةًۭ لِّلنَّاسِ ۖ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًۭا ۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 43, 3, 17, 0),
  (2, 260, 267, 'وَإِذْ قَالَ إِبْرَٰهِۦمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ ۖ قَالَ أَوَلَمْ تُؤْمِن ۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِى ۖ قَالَ فَخُذْ أَرْبَعَةًۭ مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍۢ مِّنْهُنَّ جُزْءًۭا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًۭا ۚ وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 44, 3, 17, 0),
  (2, 261, 268, 'مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍۢ مِّا۟ئَةُ حَبَّةٍۢ ۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 44, 3, 17, 0),
  (2, 262, 269, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّۭا وَلَآ أَذًۭى ۙ لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 44, 3, 17, 0),
  (2, 263, 270, '۞ قَوْلٌۭ مَّعْرُوفٌۭ وَمَغْفِرَةٌ خَيْرٌۭ مِّن صَدَقَةٍۢ يَتْبَعُهَآ أَذًۭى ۗ وَٱللَّهُ غَنِىٌّ حَلِيمٌۭ', 44, 3, 18, 0),
  (2, 264, 271, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌۭ فَأَصَابَهُۥ وَابِلٌۭ فَتَرَكَهُۥ صَلْدًۭا ۖ لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍۢ مِّمَّا كَسَبُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 44, 3, 18, 0),
  (2, 265, 272, 'وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًۭا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌۭ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌۭ فَطَلٌّۭ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 45, 3, 18, 0),
  (2, 266, 273, 'أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌۭ مِّن نَّخِيلٍۢ وَأَعْنَابٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌۭ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌۭ فِيهِ نَارٌۭ فَٱحْتَرَقَتْ ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ', 45, 3, 18, 0),
  (2, 267, 274, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ ۖ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ', 45, 3, 18, 0),
  (2, 268, 275, 'ٱلشَّيْطَٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ ۖ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةًۭ مِّنْهُ وَفَضْلًۭا ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 45, 3, 18, 0),
  (2, 269, 276, 'يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ ۚ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًۭا كَثِيرًۭا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 45, 3, 18, 0),
  (2, 270, 277, 'وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍۢ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ ۗ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ', 46, 3, 18, 0),
  (2, 271, 278, 'إِن تُبْدُوا۟ ٱلصَّدَقَٰتِ فَنِعِمَّا هِىَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌۭ لَّكُمْ ۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 46, 3, 18, 0),
  (2, 272, 279, '۞ لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍۢ فَلِأَنفُسِكُمْ ۚ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ ۚ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍۢ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 46, 3, 19, 0),
  (2, 273, 280, 'لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًۭا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًۭا ۗ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍۢ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ', 46, 3, 19, 0),
  (2, 274, 281, 'ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّۭا وَعَلَانِيَةًۭ فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 46, 3, 19, 0),
  (2, 275, 282, 'ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَٰنُ مِنَ ٱلْمَسِّ ۚ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ ۗ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ ۚ فَمَن جَآءَهُۥ مَوْعِظَةٌۭ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ ۖ وَمَنْ عَادَ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 47, 3, 19, 0),
  (2, 276, 283, 'يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَٰتِ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ', 47, 3, 19, 0),
  (2, 277, 284, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 47, 3, 19, 0),
  (2, 278, 285, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 47, 3, 19, 0),
  (2, 279, 286, 'فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍۢ مِّنَ ٱللَّهِ وَرَسُولِهِۦ ۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ', 47, 3, 19, 0),
  (2, 280, 287, 'وَإِن كَانَ ذُو عُسْرَةٍۢ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍۢ ۚ وَأَن تَصَدَّقُوا۟ خَيْرٌۭ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ', 47, 3, 19, 0),
  (2, 281, 288, 'وَٱتَّقُوا۟ يَوْمًۭا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 47, 3, 19, 0),
  (2, 282, 289, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى فَٱكْتُبُوهُ ۚ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ ۚ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ ۚ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًۭٔا ۚ فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ ۚ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌۭ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ ۚ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ ۚ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ۚ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ ۖ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةًۭ تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا ۗ وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ ۚ وَلَا يُضَآرَّ كَاتِبٌۭ وَلَا شَهِيدٌۭ ۚ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ ۖ وَيُعَلِّمُكُمُ ٱللَّهُ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 48, 3, 19, 0),
  (2, 283, 290, '۞ وَإِن كُنتُمْ عَلَىٰ سَفَرٍۢ وَلَمْ تَجِدُوا۟ كَاتِبًۭا فَرِهَٰنٌۭ مَّقْبُوضَةٌۭ ۖ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًۭا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ ۗ وَلَا تَكْتُمُوا۟ ٱلشَّهَٰدَةَ ۚ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌۭ قَلْبُهُۥ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌۭ', 49, 3, 20, 0),
  (2, 284, 291, 'لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 49, 3, 20, 0),
  (2, 285, 292, 'ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ', 49, 3, 20, 0),
  (2, 286, 293, 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًۭا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ ۖ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ ۚ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 49, 3, 20, 0),
  (3, 1, 294, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓ', 50, 3, 20, 0),
  (3, 2, 295, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ', 50, 3, 20, 0),
  (3, 3, 296, 'نَزَّلَ عَلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ وَأَنزَلَ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 50, 3, 20, 0),
  (3, 4, 297, 'مِن قَبْلُ هُدًۭى لِّلنَّاسِ وَأَنزَلَ ٱلْفُرْقَانَ ۗ إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۭ ۗ وَٱللَّهُ عَزِيزٌۭ ذُو ٱنتِقَامٍ', 50, 3, 20, 0),
  (3, 5, 298, 'إِنَّ ٱللَّهَ لَا يَخْفَىٰ عَلَيْهِ شَىْءٌۭ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 50, 3, 20, 0),
  (3, 6, 299, 'هُوَ ٱلَّذِى يُصَوِّرُكُمْ فِى ٱلْأَرْحَامِ كَيْفَ يَشَآءُ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 50, 3, 20, 0),
  (3, 7, 300, 'هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ مِنْهُ ءَايَٰتٌۭ مُّحْكَمَٰتٌ هُنَّ أُمُّ ٱلْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌۭ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌۭ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّۭ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 50, 3, 20, 0),
  (3, 8, 301, 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 50, 3, 20, 0),
  (3, 9, 302, 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 50, 3, 20, 0),
  (3, 10, 303, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًۭٔا ۖ وَأُو۟لَٰٓئِكَ هُمْ وَقُودُ ٱلنَّارِ', 51, 3, 20, 0),
  (3, 11, 304, 'كَدَأْبِ ءَالِ فِرْعَوْنَ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 51, 3, 20, 0),
  (3, 12, 305, 'قُل لِّلَّذِينَ كَفَرُوا۟ سَتُغْلَبُونَ وَتُحْشَرُونَ إِلَىٰ جَهَنَّمَ ۚ وَبِئْسَ ٱلْمِهَادُ', 51, 3, 20, 0),
  (3, 13, 306, 'قَدْ كَانَ لَكُمْ ءَايَةٌۭ فِى فِئَتَيْنِ ٱلْتَقَتَا ۖ فِئَةٌۭ تُقَٰتِلُ فِى سَبِيلِ ٱللَّهِ وَأُخْرَىٰ كَافِرَةٌۭ يَرَوْنَهُم مِّثْلَيْهِمْ رَأْىَ ٱلْعَيْنِ ۚ وَٱللَّهُ يُؤَيِّدُ بِنَصْرِهِۦ مَن يَشَآءُ ۗ إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّأُو۟لِى ٱلْأَبْصَٰرِ', 51, 3, 20, 0),
  (3, 14, 307, 'زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ مِنَ ٱلنِّسَآءِ وَٱلْبَنِينَ وَٱلْقَنَٰطِيرِ ٱلْمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلْفِضَّةِ وَٱلْخَيْلِ ٱلْمُسَوَّمَةِ وَٱلْأَنْعَٰمِ وَٱلْحَرْثِ ۗ ذَٰلِكَ مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلْمَـَٔابِ', 51, 3, 20, 0),
  (3, 15, 308, '۞ قُلْ أَؤُنَبِّئُكُم بِخَيْرٍۢ مِّن ذَٰلِكُمْ ۚ لِلَّذِينَ ٱتَّقَوْا۟ عِندَ رَبِّهِمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَأَزْوَٰجٌۭ مُّطَهَّرَةٌۭ وَرِضْوَٰنٌۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 51, 3, 21, 0),
  (3, 16, 309, 'ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ', 52, 3, 21, 0),
  (3, 17, 310, 'ٱلصَّٰبِرِينَ وَٱلصَّٰدِقِينَ وَٱلْقَٰنِتِينَ وَٱلْمُنفِقِينَ وَٱلْمُسْتَغْفِرِينَ بِٱلْأَسْحَارِ', 52, 3, 21, 0),
  (3, 18, 311, 'شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ وَٱلْمَلَٰٓئِكَةُ وَأُو۟لُوا۟ ٱلْعِلْمِ قَآئِمًۢا بِٱلْقِسْطِ ۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 52, 3, 21, 0),
  (3, 19, 312, 'إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 52, 3, 21, 0),
  (3, 20, 313, 'فَإِنْ حَآجُّوكَ فَقُلْ أَسْلَمْتُ وَجْهِىَ لِلَّهِ وَمَنِ ٱتَّبَعَنِ ۗ وَقُل لِّلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ وَٱلْأُمِّيِّۦنَ ءَأَسْلَمْتُمْ ۚ فَإِنْ أَسْلَمُوا۟ فَقَدِ ٱهْتَدَوا۟ ۖ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ۗ وَٱللَّهُ بَصِيرٌۢ بِٱلْعِبَادِ', 52, 3, 21, 0),
  (3, 21, 314, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّۦنَ بِغَيْرِ حَقٍّۢ وَيَقْتُلُونَ ٱلَّذِينَ يَأْمُرُونَ بِٱلْقِسْطِ مِنَ ٱلنَّاسِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 52, 3, 21, 0),
  (3, 22, 315, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 52, 3, 21, 0),
  (3, 23, 316, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌۭ مِّنْهُمْ وَهُم مُّعْرِضُونَ', 53, 3, 21, 0),
  (3, 24, 317, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًۭا مَّعْدُودَٰتٍۢ ۖ وَغَرَّهُمْ فِى دِينِهِم مَّا كَانُوا۟ يَفْتَرُونَ', 53, 3, 21, 0),
  (3, 25, 318, 'فَكَيْفَ إِذَا جَمَعْنَٰهُمْ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ وَوُفِّيَتْ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 53, 3, 21, 0),
  (3, 26, 319, 'قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ ۖ بِيَدِكَ ٱلْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 53, 3, 21, 0),
  (3, 27, 320, 'تُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۖ وَتُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ ۖ وَتَرْزُقُ مَن تَشَآءُ بِغَيْرِ حِسَابٍۢ', 53, 3, 21, 0),
  (3, 28, 321, 'لَّا يَتَّخِذِ ٱلْمُؤْمِنُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۖ وَمَن يَفْعَلْ ذَٰلِكَ فَلَيْسَ مِنَ ٱللَّهِ فِى شَىْءٍ إِلَّآ أَن تَتَّقُوا۟ مِنْهُمْ تُقَىٰةًۭ ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 53, 3, 21, 0),
  (3, 29, 322, 'قُلْ إِن تُخْفُوا۟ مَا فِى صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ ٱللَّهُ ۗ وَيَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 53, 3, 21, 0),
  (3, 30, 323, 'يَوْمَ تَجِدُ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ مِنْ خَيْرٍۢ مُّحْضَرًۭا وَمَا عَمِلَتْ مِن سُوٓءٍۢ تَوَدُّ لَوْ أَنَّ بَيْنَهَا وَبَيْنَهُۥٓ أَمَدًۢا بَعِيدًۭا ۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفْسَهُۥ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ', 54, 3, 21, 0),
  (3, 31, 324, 'قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 54, 3, 21, 0),
  (3, 32, 325, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ', 54, 3, 21, 0),
  (3, 33, 326, '۞ إِنَّ ٱللَّهَ ٱصْطَفَىٰٓ ءَادَمَ وَنُوحًۭا وَءَالَ إِبْرَٰهِيمَ وَءَالَ عِمْرَٰنَ عَلَى ٱلْعَٰلَمِينَ', 54, 3, 22, 0),
  (3, 34, 327, 'ذُرِّيَّةًۢ بَعْضُهَا مِنۢ بَعْضٍۢ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 54, 3, 22, 0),
  (3, 35, 328, 'إِذْ قَالَتِ ٱمْرَأَتُ عِمْرَٰنَ رَبِّ إِنِّى نَذَرْتُ لَكَ مَا فِى بَطْنِى مُحَرَّرًۭا فَتَقَبَّلْ مِنِّىٓ ۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 54, 3, 22, 0),
  (3, 36, 329, 'فَلَمَّا وَضَعَتْهَا قَالَتْ رَبِّ إِنِّى وَضَعْتُهَآ أُنثَىٰ وَٱللَّهُ أَعْلَمُ بِمَا وَضَعَتْ وَلَيْسَ ٱلذَّكَرُ كَٱلْأُنثَىٰ ۖ وَإِنِّى سَمَّيْتُهَا مَرْيَمَ وَإِنِّىٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 54, 3, 22, 0),
  (3, 37, 330, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٍۢ وَأَنۢبَتَهَا نَبَاتًا حَسَنًۭا وَكَفَّلَهَا زَكَرِيَّا ۖ كُلَّمَا دَخَلَ عَلَيْهَا زَكَرِيَّا ٱلْمِحْرَابَ وَجَدَ عِندَهَا رِزْقًۭا ۖ قَالَ يَٰمَرْيَمُ أَنَّىٰ لَكِ هَٰذَا ۖ قَالَتْ هُوَ مِنْ عِندِ ٱللَّهِ ۖ إِنَّ ٱللَّهَ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ', 54, 3, 22, 0),
  (3, 38, 331, 'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥ ۖ قَالَ رَبِّ هَبْ لِى مِن لَّدُنكَ ذُرِّيَّةًۭ طَيِّبَةً ۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ', 55, 3, 22, 0),
  (3, 39, 332, 'فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌۭ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍۢ مِّنَ ٱللَّهِ وَسَيِّدًۭا وَحَصُورًۭا وَنَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ', 55, 3, 22, 0),
  (3, 40, 333, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَقَدْ بَلَغَنِىَ ٱلْكِبَرُ وَٱمْرَأَتِى عَاقِرٌۭ ۖ قَالَ كَذَٰلِكَ ٱللَّهُ يَفْعَلُ مَا يَشَآءُ', 55, 3, 22, 0),
  (3, 41, 334, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةًۭ ۖ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَةَ أَيَّامٍ إِلَّا رَمْزًۭا ۗ وَٱذْكُر رَّبَّكَ كَثِيرًۭا وَسَبِّحْ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 55, 3, 22, 0),
  (3, 42, 335, 'وَإِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَٰلَمِينَ', 55, 3, 22, 0),
  (3, 43, 336, 'يَٰمَرْيَمُ ٱقْنُتِى لِرَبِّكِ وَٱسْجُدِى وَٱرْكَعِى مَعَ ٱلرَّٰكِعِينَ', 55, 3, 22, 0),
  (3, 44, 337, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۚ وَمَا كُنتَ لَدَيْهِمْ إِذْ يُلْقُونَ أَقْلَٰمَهُمْ أَيُّهُمْ يَكْفُلُ مَرْيَمَ وَمَا كُنتَ لَدَيْهِمْ إِذْ يَخْتَصِمُونَ', 55, 3, 22, 0),
  (3, 45, 338, 'إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍۢ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ', 55, 3, 22, 0),
  (3, 46, 339, 'وَيُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًۭا وَمِنَ ٱلصَّٰلِحِينَ', 56, 3, 22, 0),
  (3, 47, 340, 'قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ ۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ ۚ إِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 56, 3, 22, 0),
  (3, 48, 341, 'وَيُعَلِّمُهُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ', 56, 3, 22, 0),
  (3, 49, 342, 'وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍۢ مِّن رَّبِّكُمْ ۖ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ ۖ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ ۖ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 56, 3, 22, 0),
  (3, 50, 343, 'وَمُصَدِّقًۭا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَلِأُحِلَّ لَكُم بَعْضَ ٱلَّذِى حُرِّمَ عَلَيْكُمْ ۚ وَجِئْتُكُم بِـَٔايَةٍۢ مِّن رَّبِّكُمْ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 56, 3, 22, 0),
  (3, 51, 344, 'إِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۗ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 56, 3, 22, 0),
  (3, 52, 345, '۞ فَلَمَّآ أَحَسَّ عِيسَىٰ مِنْهُمُ ٱلْكُفْرَ قَالَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشْهَدْ بِأَنَّا مُسْلِمُونَ', 56, 3, 23, 0),
  (3, 53, 346, 'رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلْتَ وَٱتَّبَعْنَا ٱلرَّسُولَ فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 57, 3, 23, 0),
  (3, 54, 347, 'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 57, 3, 23, 0),
  (3, 55, 348, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۖ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأَحْكُمُ بَيْنَكُمْ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 57, 3, 23, 0),
  (3, 56, 349, 'فَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَأُعَذِّبُهُمْ عَذَابًۭا شَدِيدًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمَا لَهُم مِّن نَّٰصِرِينَ', 57, 3, 23, 0),
  (3, 57, 350, 'وَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 57, 3, 23, 0),
  (3, 58, 351, 'ذَٰلِكَ نَتْلُوهُ عَلَيْكَ مِنَ ٱلْءَايَٰتِ وَٱلذِّكْرِ ٱلْحَكِيمِ', 57, 3, 23, 0),
  (3, 59, 352, 'إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍۢ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ', 57, 3, 23, 0),
  (3, 60, 353, 'ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلْمُمْتَرِينَ', 57, 3, 23, 0),
  (3, 61, 354, 'فَمَنْ حَآجَّكَ فِيهِ مِنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ فَقُلْ تَعَالَوْا۟ نَدْعُ أَبْنَآءَنَا وَأَبْنَآءَكُمْ وَنِسَآءَنَا وَنِسَآءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ ٱللَّهِ عَلَى ٱلْكَٰذِبِينَ', 57, 3, 23, 0),
  (3, 62, 355, 'إِنَّ هَٰذَا لَهُوَ ٱلْقَصَصُ ٱلْحَقُّ ۚ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 58, 3, 23, 0),
  (3, 63, 356, 'فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ عَلِيمٌۢ بِٱلْمُفْسِدِينَ', 58, 3, 23, 0),
  (3, 64, 357, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍۢ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًۭٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًۭا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ', 58, 3, 23, 0),
  (3, 65, 358, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تُحَآجُّونَ فِىٓ إِبْرَٰهِيمَ وَمَآ أُنزِلَتِ ٱلتَّوْرَىٰةُ وَٱلْإِنجِيلُ إِلَّا مِنۢ بَعْدِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ', 58, 3, 23, 0),
  (3, 66, 359, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ حَٰجَجْتُمْ فِيمَا لَكُم بِهِۦ عِلْمٌۭ فَلِمَ تُحَآجُّونَ فِيمَا لَيْسَ لَكُم بِهِۦ عِلْمٌۭ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 58, 3, 23, 0),
  (3, 67, 360, 'مَا كَانَ إِبْرَٰهِيمُ يَهُودِيًّۭا وَلَا نَصْرَانِيًّۭا وَلَٰكِن كَانَ حَنِيفًۭا مُّسْلِمًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 58, 3, 23, 0),
  (3, 68, 361, 'إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ وَٱلَّذِينَ ءَامَنُوا۟ ۗ وَٱللَّهُ وَلِىُّ ٱلْمُؤْمِنِينَ', 58, 3, 23, 0),
  (3, 69, 362, 'وَدَّت طَّآئِفَةٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يُضِلُّونَكُمْ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 58, 3, 23, 0),
  (3, 70, 363, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَأَنتُمْ تَشْهَدُونَ', 58, 3, 23, 0),
  (3, 71, 364, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَلْبِسُونَ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُونَ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ', 59, 3, 23, 0),
  (3, 72, 365, 'وَقَالَت طَّآئِفَةٌۭ مِّنْ أَهْلِ ٱلْكِتَٰبِ ءَامِنُوا۟ بِٱلَّذِىٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَجْهَ ٱلنَّهَارِ وَٱكْفُرُوٓا۟ ءَاخِرَهُۥ لَعَلَّهُمْ يَرْجِعُونَ', 59, 3, 23, 0),
  (3, 73, 366, 'وَلَا تُؤْمِنُوٓا۟ إِلَّا لِمَن تَبِعَ دِينَكُمْ قُلْ إِنَّ ٱلْهُدَىٰ هُدَى ٱللَّهِ أَن يُؤْتَىٰٓ أَحَدٌۭ مِّثْلَ مَآ أُوتِيتُمْ أَوْ يُحَآجُّوكُمْ عِندَ رَبِّكُمْ ۗ قُلْ إِنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 59, 3, 23, 0),
  (3, 74, 367, 'يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 59, 3, 23, 0),
  (3, 75, 368, '۞ وَمِنْ أَهْلِ ٱلْكِتَٰبِ مَنْ إِن تَأْمَنْهُ بِقِنطَارٍۢ يُؤَدِّهِۦٓ إِلَيْكَ وَمِنْهُم مَّنْ إِن تَأْمَنْهُ بِدِينَارٍۢ لَّا يُؤَدِّهِۦٓ إِلَيْكَ إِلَّا مَا دُمْتَ عَلَيْهِ قَآئِمًۭا ۗ ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لَيْسَ عَلَيْنَا فِى ٱلْأُمِّيِّۦنَ سَبِيلٌۭ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 59, 3, 24, 0),
  (3, 76, 369, 'بَلَىٰ مَنْ أَوْفَىٰ بِعَهْدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 59, 3, 24, 0),
  (3, 77, 370, 'إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًۭا قَلِيلًا أُو۟لَٰٓئِكَ لَا خَلَٰقَ لَهُمْ فِى ٱلْءَاخِرَةِ وَلَا يُكَلِّمُهُمُ ٱللَّهُ وَلَا يَنظُرُ إِلَيْهِمْ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 59, 3, 24, 0),
  (3, 78, 371, 'وَإِنَّ مِنْهُمْ لَفَرِيقًۭا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ', 60, 3, 24, 0),
  (3, 79, 372, 'مَا كَانَ لِبَشَرٍ أَن يُؤْتِيَهُ ٱللَّهُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ثُمَّ يَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادًۭا لِّى مِن دُونِ ٱللَّهِ وَلَٰكِن كُونُوا۟ رَبَّٰنِيِّۦنَ بِمَا كُنتُمْ تُعَلِّمُونَ ٱلْكِتَٰبَ وَبِمَا كُنتُمْ تَدْرُسُونَ', 60, 3, 24, 0),
  (3, 80, 373, 'وَلَا يَأْمُرَكُمْ أَن تَتَّخِذُوا۟ ٱلْمَلَٰٓئِكَةَ وَٱلنَّبِيِّۦنَ أَرْبَابًا ۗ أَيَأْمُرُكُم بِٱلْكُفْرِ بَعْدَ إِذْ أَنتُم مُّسْلِمُونَ', 60, 3, 24, 0),
  (3, 81, 374, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلنَّبِيِّۦنَ لَمَآ ءَاتَيْتُكُم مِّن كِتَٰبٍۢ وَحِكْمَةٍۢ ثُمَّ جَآءَكُمْ رَسُولٌۭ مُّصَدِّقٌۭ لِّمَا مَعَكُمْ لَتُؤْمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥ ۚ قَالَ ءَأَقْرَرْتُمْ وَأَخَذْتُمْ عَلَىٰ ذَٰلِكُمْ إِصْرِى ۖ قَالُوٓا۟ أَقْرَرْنَا ۚ قَالَ فَٱشْهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ', 60, 3, 24, 0),
  (3, 82, 375, 'فَمَن تَوَلَّىٰ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 60, 3, 24, 0),
  (3, 83, 376, 'أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًۭا وَكَرْهًۭا وَإِلَيْهِ يُرْجَعُونَ', 60, 3, 24, 0),
  (3, 84, 377, 'قُلْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ عَلَيْنَا وَمَآ أُنزِلَ عَلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍۢ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ', 61, 3, 24, 0),
  (3, 85, 378, 'وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًۭا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 61, 3, 24, 0),
  (3, 86, 379, 'كَيْفَ يَهْدِى ٱللَّهُ قَوْمًۭا كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ وَشَهِدُوٓا۟ أَنَّ ٱلرَّسُولَ حَقٌّۭ وَجَآءَهُمُ ٱلْبَيِّنَٰتُ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 61, 3, 24, 0),
  (3, 87, 380, 'أُو۟لَٰٓئِكَ جَزَآؤُهُمْ أَنَّ عَلَيْهِمْ لَعْنَةَ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ', 61, 3, 24, 0),
  (3, 88, 381, 'خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ', 61, 3, 24, 0),
  (3, 89, 382, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 61, 3, 24, 0),
  (3, 90, 383, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بَعْدَ إِيمَٰنِهِمْ ثُمَّ ٱزْدَادُوا۟ كُفْرًۭا لَّن تُقْبَلَ تَوْبَتُهُمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلضَّآلُّونَ', 61, 3, 24, 0),
  (3, 91, 384, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌۭ فَلَن يُقْبَلَ مِنْ أَحَدِهِم مِّلْءُ ٱلْأَرْضِ ذَهَبًۭا وَلَوِ ٱفْتَدَىٰ بِهِۦٓ ۗ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌۭ وَمَا لَهُم مِّن نَّٰصِرِينَ', 61, 3, 24, 0),
  (3, 92, 385, 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍۢ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌۭ', 62, 3, 24, 0),
  (3, 93, 386, '۞ كُلُّ ٱلطَّعَامِ كَانَ حِلًّۭا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ ۗ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ', 62, 4, 25, 0),
  (3, 94, 387, 'فَمَنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ مِنۢ بَعْدِ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 62, 4, 25, 0),
  (3, 95, 388, 'قُلْ صَدَقَ ٱللَّهُ ۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 62, 4, 25, 0),
  (3, 96, 389, 'إِنَّ أَوَّلَ بَيْتٍۢ وُضِعَ لِلنَّاسِ لَلَّذِى بِبَكَّةَ مُبَارَكًۭا وَهُدًۭى لِّلْعَٰلَمِينَ', 62, 4, 25, 0),
  (3, 97, 390, 'فِيهِ ءَايَٰتٌۢ بَيِّنَٰتٌۭ مَّقَامُ إِبْرَٰهِيمَ ۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنًۭا ۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًۭا ۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنِ ٱلْعَٰلَمِينَ', 62, 4, 25, 0),
  (3, 98, 391, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعْمَلُونَ', 62, 4, 25, 0),
  (3, 99, 392, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لِمَ تَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ تَبْغُونَهَا عِوَجًۭا وَأَنتُمْ شُهَدَآءُ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 62, 4, 25, 0),
  (3, 100, 393, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ فَرِيقًۭا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ يَرُدُّوكُم بَعْدَ إِيمَٰنِكُمْ كَٰفِرِينَ', 62, 4, 25, 0),
  (3, 101, 394, 'وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ ءَايَٰتُ ٱللَّهِ وَفِيكُمْ رَسُولُهُۥ ۗ وَمَن يَعْتَصِم بِٱللَّهِ فَقَدْ هُدِىَ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 63, 4, 25, 0),
  (3, 102, 395, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ', 63, 4, 25, 0),
  (3, 103, 396, 'وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا وَلَا تَفَرَّقُوا۟ ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءًۭ فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًۭا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍۢ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ', 63, 4, 25, 0),
  (3, 104, 397, 'وَلْتَكُن مِّنكُمْ أُمَّةٌۭ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 63, 4, 25, 0),
  (3, 105, 398, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ ۚ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌۭ', 63, 4, 25, 0),
  (3, 106, 399, 'يَوْمَ تَبْيَضُّ وُجُوهٌۭ وَتَسْوَدُّ وُجُوهٌۭ ۚ فَأَمَّا ٱلَّذِينَ ٱسْوَدَّتْ وُجُوهُهُمْ أَكَفَرْتُم بَعْدَ إِيمَٰنِكُمْ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 63, 4, 25, 0),
  (3, 107, 400, 'وَأَمَّا ٱلَّذِينَ ٱبْيَضَّتْ وُجُوهُهُمْ فَفِى رَحْمَةِ ٱللَّهِ هُمْ فِيهَا خَٰلِدُونَ', 63, 4, 25, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 3, 1, 'Alif, Lam, Meem.'),
  ('en.sahih', 3, 2, 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of existence.'),
  ('en.sahih', 3, 3, 'He has sent down upon you, [O Muhammad], the Book in truth, confirming what was before it. And He revealed the Torah and the Gospel.'),
  ('en.sahih', 3, 4, 'Before, as guidance for the people. And He revealed the Qur\'an. Indeed, those who disbelieve in the verses of Allah will have a severe punishment, and Allah is exalted in Might, the Owner of Retribution.'),
  ('en.sahih', 3, 5, 'Indeed, from Allah nothing is hidden in the earth nor in the heaven.'),
  ('en.sahih', 3, 6, 'It is He who forms you in the wombs however He wills. There is no deity except Him, the Exalted in Might, the Wise.'),
  ('en.sahih', 3, 7, 'It is He who has sent down to you, [O Muhammad], the Book; in it are verses [that are] precise - they are the foundation of the Book - and others unspecific. As for those in whose hearts is deviation [from truth], they will follow that of it which is unspecific, seeking discord and seeking an interpretation [suitable to them]. And no one knows its [true] interpretation except Allah. But those firm in knowledge say, "We believe in it. All [of it] is from our Lord." And no one will be reminded except those of understanding.'),
  ('en.sahih', 3, 8, '[Who say], "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.'),
  ('en.sahih', 3, 9, 'Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise."'),
  ('en.sahih', 3, 10, 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all. And it is they who are fuel for the Fire.'),
  ('en.sahih', 3, 11, '[Theirs is] like the custom of the people of Pharaoh and those before them. They denied Our signs, so Allah seized them for their sins. And Allah is severe in penalty.'),
  ('en.sahih', 3, 12, 'Say to those who disbelieve, "You will be overcome and gathered together to Hell, and wretched is the resting place."'),
  ('en.sahih', 3, 13, 'Already there has been for you a sign in the two armies which met - one fighting in the cause of Allah and another of disbelievers. They saw them [to be] twice their [own] number by [their] eyesight. But Allah supports with His victory whom He wills. Indeed in that is a lesson for those of vision.'),
  ('en.sahih', 3, 14, 'Beautified for people is the love of that which they desire - of women and sons, heaped-up sums of gold and silver, fine branded horses, and cattle and tilled land. That is the enjoyment of worldly life, but Allah has with Him the best return.'),
  ('en.sahih', 3, 15, 'Say, "Shall I inform you of [something] better than that? For those who fear Allah will be gardens in the presence of their Lord beneath which rivers flow, wherein they abide eternally, and purified spouses and approval from Allah. And Allah is Seeing of [His] servants -'),
  ('en.sahih', 3, 16, 'Those who say, "Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire,"'),
  ('en.sahih', 3, 17, 'The patient, the true, the obedient, those who spend [in the way of Allah], and those who seek forgiveness before dawn.'),
  ('en.sahih', 3, 18, 'Allah witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise.'),
  ('en.sahih', 3, 19, 'Indeed, the religion in the sight of Allah is Islam. And those who were given the Scripture did not differ except after knowledge had come to them - out of jealous animosity between themselves. And whoever disbelieves in the verses of Allah, then indeed, Allah is swift in [taking] account.'),
  ('en.sahih', 3, 20, 'So if they argue with you, say, "I have submitted myself to Allah [in Islam], and [so have] those who follow me." And say to those who were given the Scripture and [to] the unlearned, "Have you submitted yourselves?" And if they submit [in Islam], they are rightly guided; but if they turn away - then upon you is only the [duty of] notification. And Allah is Seeing of [His] servants.'),
  ('en.sahih', 3, 21, 'Those who disbelieve in the signs of Allah and kill the prophets without right and kill those who order justice from among the people - give them tidings of a painful punishment.'),
  ('en.sahih', 3, 22, 'They are the ones whose deeds have become worthless in this world and the Hereafter, and for them there will be no helpers.'),
  ('en.sahih', 3, 23, 'Do you not consider, [O Muhammad], those who were given a portion of the Scripture? They are invited to the Scripture of Allah that it should arbitrate between them; then a party of them turns away, and they are refusing.'),
  ('en.sahih', 3, 24, 'That is because they say, "Never will the Fire touch us except for [a few] numbered days," and [because] they were deluded in their religion by what they were inventing.'),
  ('en.sahih', 3, 25, 'So how will it be when We assemble them for a Day about which there is no doubt? And each soul will be compensated [in full for] what it earned, and they will not be wronged.'),
  ('en.sahih', 3, 26, 'Say, "O Allah, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is [all] good. Indeed, You are over all things competent.'),
  ('en.sahih', 3, 27, 'You cause the night to enter the day, and You cause the day to enter the night; and You bring the living out of the dead, and You bring the dead out of the living. And You give provision to whom You will without account."'),
  ('en.sahih', 3, 28, 'Let not believers take disbelievers as allies rather than believers. And whoever [of you] does that has nothing with Allah, except when taking precaution against them in prudence. And Allah warns you of Himself, and to Allah is the [final] destination.'),
  ('en.sahih', 3, 29, 'Say, "Whether you conceal what is in your breasts or reveal it, Allah knows it. And He knows that which is in the heavens and that which is on the earth. And Allah is over all things competent.'),
  ('en.sahih', 3, 30, 'The Day every soul will find what it has done of good present [before it] and what it has done of evil, it will wish that between itself and that [evil] was a great distance. And Allah warns you of Himself, and Allah is Kind to [His] servants."'),
  ('en.sahih', 3, 31, 'Say, [O Muhammad], "If you should love Allah, then follow me, [so] Allah will love you and forgive you your sins. And Allah is Forgiving and Merciful."'),
  ('en.sahih', 3, 32, 'Say, "Obey Allah and the Messenger." But if they turn away - then indeed, Allah does not like the disbelievers.'),
  ('en.sahih', 3, 33, 'Indeed, Allah chose Adam and Noah and the family of Abraham and the family of \'Imran over the worlds -'),
  ('en.sahih', 3, 34, 'Descendants, some of them from others. And Allah is Hearing and Knowing.'),
  ('en.sahih', 3, 35, '[Mention, O Muhammad], when the wife of \'Imran said, "My Lord, indeed I have pledged to You what is in my womb, consecrated [for Your service], so accept this from me. Indeed, You are the Hearing, the Knowing."'),
  ('en.sahih', 3, 36, 'But when she delivered her, she said, "My Lord, I have delivered a female." And Allah was most knowing of what she delivered, "And the male is not like the female. And I have named her Mary, and I seek refuge for her in You and [for] her descendants from Satan, the expelled [from the mercy of Allah]."'),
  ('en.sahih', 3, 37, 'So her Lord accepted her with good acceptance and caused her to grow in a good manner and put her in the care of Zechariah. Every time Zechariah entered upon her in the prayer chamber, he found with her provision. He said, "O Mary, from where is this [coming] to you?" She said, "It is from Allah. Indeed, Allah provides for whom He wills without account."'),
  ('en.sahih', 3, 38, 'At that, Zechariah called upon his Lord, saying, "My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication."'),
  ('en.sahih', 3, 39, 'So the angels called him while he was standing in prayer in the chamber, "Indeed, Allah gives you good tidings of John, confirming a word from Allah and [who will be] honorable, abstaining [from women], and a prophet from among the righteous."'),
  ('en.sahih', 3, 40, 'He said, "My Lord, how will I have a boy when I have reached old age and my wife is barren?" The angel said, "Such is Allah; He does what He wills."'),
  ('en.sahih', 3, 41, 'He said, "My Lord, make for me a sign." He Said, "Your sign is that you will not [be able to] speak to the people for three days except by gesture. And remember your Lord much and exalt [Him with praise] in the evening and the morning."'),
  ('en.sahih', 3, 42, 'And [mention] when the angels said, "O Mary, indeed Allah has chosen you and purified you and chosen you above the women of the worlds.'),
  ('en.sahih', 3, 43, 'O Mary, be devoutly obedient to your Lord and prostrate and bow with those who bow [in prayer]."'),
  ('en.sahih', 3, 44, 'That is from the news of the unseen which We reveal to you, [O Muhammad]. And you were not with them when they cast their pens as to which of them should be responsible for Mary. Nor were you with them when they disputed.'),
  ('en.sahih', 3, 45, '[And mention] when the angels said, "O Mary, indeed Allah gives you good tidings of a word from Him, whose name will be the Messiah, Jesus, the son of Mary - distinguished in this world and the Hereafter and among those brought near [to Allah].'),
  ('en.sahih', 3, 46, 'He will speak to the people in the cradle and in maturity and will be of the righteous."'),
  ('en.sahih', 3, 47, 'She said, "My Lord, how will I have a child when no man has touched me?" [The angel] said, "Such is Allah; He creates what He wills. When He decrees a matter, He only says to it, \'Be,\' and it is.'),
  ('en.sahih', 3, 48, 'And He will teach him writing and wisdom and the Torah and the Gospel'),
  ('en.sahih', 3, 49, 'And [make him] a messenger to the Children of Israel, [who will say], \'Indeed I have come to you with a sign from your Lord in that I design for you from clay [that which is] like the form of a bird, then I breathe into it and it becomes a bird by permission of Allah. And I cure the blind and the leper, and I give life to the dead - by permission of Allah. And I inform you of what you eat and what you store in your houses. Indeed in that is a sign for you, if you are believers.'),
  ('en.sahih', 3, 50, 'And [I have come] confirming what was before me of the Torah and to make lawful for you some of what was forbidden to you. And I have come to you with a sign from your Lord, so fear Allah and obey me.'),
  ('en.sahih', 3, 51, 'Indeed, Allah is my Lord and your Lord, so worship Him. That is the straight path."'),
  ('en.sahih', 3, 52, 'But when Jesus felt [persistence in] disbelief from them, he said, "Who are my supporters for [the cause of] Allah?" The disciples said, "We are supporters for Allah. We have believed in Allah and testify that we are Muslims [submitting to Him].'),
  ('en.sahih', 3, 53, 'Our Lord, we have believed in what You revealed and have followed the messenger Jesus, so register us among the witnesses [to truth]."'),
  ('en.sahih', 3, 54, 'And the disbelievers planned, but Allah planned. And Allah is the best of planners.'),
  ('en.sahih', 3, 55, '[Mention] when Allah said, "O Jesus, indeed I will take you and raise you to Myself and purify you from those who disbelieve and make those who follow you [in submission to Allah alone] superior to those who disbelieve until the Day of Resurrection. Then to Me is your return, and I will judge between you concerning that in which you used to differ.'),
  ('en.sahih', 3, 56, 'And as for those who disbelieved, I will punish them with a severe punishment in this world and the Hereafter, and they will have no helpers."'),
  ('en.sahih', 3, 57, 'But as for those who believed and did righteous deeds, He will give them in full their rewards, and Allah does not like the wrongdoers.'),
  ('en.sahih', 3, 58, 'This is what We recite to you, [O Muhammad], of [Our] verses and the precise [and wise] message.'),
  ('en.sahih', 3, 59, 'Indeed, the example of Jesus to Allah is like that of Adam. He created Him from dust; then He said to him, "Be," and he was.'),
  ('en.sahih', 3, 60, 'The truth is from your Lord, so do not be among the doubters.'),
  ('en.sahih', 3, 61, 'Then whoever argues with you about it after [this] knowledge has come to you - say, "Come, let us call our sons and your sons, our women and your women, ourselves and yourselves, then supplicate earnestly [together] and invoke the curse of Allah upon the liars [among us]."'),
  ('en.sahih', 3, 62, 'Indeed, this is the true narration. And there is no deity except Allah. And indeed, Allah is the Exalted in Might, the Wise.'),
  ('en.sahih', 3, 63, 'But if they turn away, then indeed - Allah is Knowing of the corrupters.'),
  ('en.sahih', 3, 64, 'Say, "O People of the Scripture, come to a word that is equitable between us and you - that we will not worship except Allah and not associate anything with Him and not take one another as lords instead of Allah." But if they turn away, then say, "Bear witness that we are Muslims [submitting to Him]."'),
  ('en.sahih', 3, 65, 'O People of the Scripture, why do you argue about Abraham while the Torah and the Gospel were not revealed until after him? Then will you not reason?'),
  ('en.sahih', 3, 66, 'Here you are - those who have argued about that of which you have [some] knowledge, but why do you argue about that of which you have no knowledge? And Allah knows, while you know not.'),
  ('en.sahih', 3, 67, 'Abraham was neither a Jew nor a Christian, but he was one inclining toward truth, a Muslim [submitting to Allah]. And he was not of the polytheists.'),
  ('en.sahih', 3, 68, 'Indeed, the most worthy of Abraham among the people are those who followed him [in submission to Allah] and this prophet, and those who believe [in his message]. And Allah is the ally of the believers.'),
  ('en.sahih', 3, 69, 'A faction of the people of the Scripture wish they could mislead you. But they do not mislead except themselves, and they perceive [it] not.'),
  ('en.sahih', 3, 70, 'O People of the Scripture, why do you disbelieve in the verses of Allah while you witness [to their truth]?'),
  ('en.sahih', 3, 71, 'O People of the Scripture, why do you confuse the truth with falsehood and conceal the truth while you know [it]?'),
  ('en.sahih', 3, 72, 'And a faction of the People of the Scripture say [to each other], "Believe in that which was revealed to the believers at the beginning of the day and reject it at its end that perhaps they will abandon their religion,'),
  ('en.sahih', 3, 73, 'And do not trust except those who follow your religion." Say, "Indeed, the [true] guidance is the guidance of Allah. [Do you fear] lest someone be given [knowledge] like you were given or that they would [thereby] argue with you before your Lord?" Say, "Indeed, [all] bounty is in the hand of Allah - He grants it to whom He wills. And Allah is all-Encompassing and Wise."'),
  ('en.sahih', 3, 74, 'He selects for His mercy whom He wills. And Allah is the possessor of great bounty.'),
  ('en.sahih', 3, 75, 'And among the People of the Scripture is he who, if you entrust him with a great amount [of wealth], he will return it to you. And among them is he who, if you entrust him with a [single] silver coin, he will not return it to you unless you are constantly standing over him [demanding it]. That is because they say, "There is no blame upon us concerning the unlearned." And they speak untruth about Allah while they know [it].'),
  ('en.sahih', 3, 76, 'But yes, whoever fulfills his commitment and fears Allah - then indeed, Allah loves those who fear Him.'),
  ('en.sahih', 3, 77, 'Indeed, those who exchange the covenant of Allah and their [own] oaths for a small price will have no share in the Hereafter, and Allah will not speak to them or look at them on the Day of Resurrection, nor will He purify them; and they will have a painful punishment.'),
  ('en.sahih', 3, 78, 'And indeed, there is among them a party who alter the Scripture with their tongues so you may think it is from the Scripture, but it is not from the Scripture. And they say, "This is from Allah," but it is not from Allah. And they speak untruth about Allah while they know.'),
  ('en.sahih', 3, 79, 'It is not for a human [prophet] that Allah should give him the Scripture and authority and prophethood and then he would say to the people, "Be servants to me rather than Allah," but [instead, he would say], "Be pious scholars of the Lord because of what you have taught of the Scripture and because of what you have studied."'),
  ('en.sahih', 3, 80, 'Nor could he order you to take the angels and prophets as lords. Would he order you to disbelief after you had been Muslims?'),
  ('en.sahih', 3, 81, 'And [recall, O People of the Scripture], when Allah took the covenant of the prophets, [saying], "Whatever I give you of the Scripture and wisdom and then there comes to you a messenger confirming what is with you, you [must] believe in him and support him." [Allah] said, "Have you acknowledged and taken upon that My commitment?" They said, "We have acknowledged it." He said, "Then bear witness, and I am with you among the witnesses."'),
  ('en.sahih', 3, 82, 'And whoever turned away after that - they were the defiantly disobedient.'),
  ('en.sahih', 3, 83, 'So is it other than the religion of Allah they desire, while to Him have submitted [all] those within the heavens and earth, willingly or by compulsion, and to Him they will be returned?'),
  ('en.sahih', 3, 84, 'Say, "We have believed in Allah and in what was revealed to us and what was revealed to Abraham, Ishmael, Isaac, Jacob, and the Descendants, and in what was given to Moses and Jesus and to the prophets from their Lord. We make no distinction between any of them, and we are Muslims [submitting] to Him."'),
  ('en.sahih', 3, 85, 'And whoever desires other than Islam as religion - never will it be accepted from him, and he, in the Hereafter, will be among the losers.'),
  ('en.sahih', 3, 86, 'How shall Allah guide a people who disbelieved after their belief and had witnessed that the Messenger is true and clear signs had come to them? And Allah does not guide the wrongdoing people.'),
  ('en.sahih', 3, 87, 'Those - their recompense will be that upon them is the curse of Allah and the angels and the people, all together,'),
  ('en.sahih', 3, 88, 'Abiding eternally therein. The punishment will not be lightened for them, nor will they be reprieved.'),
  ('en.sahih', 3, 89, 'Except for those who repent after that and correct themselves. For indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 3, 90, 'Indeed, those who reject the message after their belief and then increase in disbelief - never will their [claimed] repentance be accepted, and they are the ones astray.'),
  ('en.sahih', 3, 91, 'Indeed, those who disbelieve and die while they are disbelievers - never would the [whole] capacity of the earth in gold be accepted from one of them if he would [seek to] ransom himself with it. For those there will be a painful punishment, and they will have no helpers.'),
  ('en.sahih', 3, 92, 'Never will you attain the good [reward] until you spend [in the way of Allah] from that which you love. And whatever you spend - indeed, Allah is Knowing of it.'),
  ('en.sahih', 3, 93, 'All food was lawful to the Children of Israel except what Israel had made unlawful to himself before the Torah was revealed. Say, [O Muhammad], "So bring the Torah and recite it, if you should be truthful."'),
  ('en.sahih', 3, 94, 'And whoever invents about Allah untruth after that - then those are [truly] the wrongdoers.'),
  ('en.sahih', 3, 95, 'Say, "Allah has told the truth. So follow the religion of Abraham, inclining toward truth; and he was not of the polytheists."'),
  ('en.sahih', 3, 96, 'Indeed, the first House [of worship] established for mankind was that at Makkah - blessed and a guidance for the worlds.'),
  ('en.sahih', 3, 97, 'In it are clear signs [such as] the standing place of Abraham. And whoever enters it shall be safe. And [due] to Allah from the people is a pilgrimage to the House - for whoever is able to find thereto a way. But whoever disbelieves - then indeed, Allah is free from need of the worlds.'),
  ('en.sahih', 3, 98, 'Say, "O People of the Scripture, why do you disbelieve in the verses of Allah while Allah is Witness over what you do?"'),
  ('en.sahih', 3, 99, 'Say, "O People of the Scripture, why do you avert from the way of Allah those who believe, seeking to make it [seem] deviant, while you are witnesses [to the truth]? And Allah is not unaware of what you do."'),
  ('en.sahih', 3, 100, 'O you who have believed, if you obey a party of those who were given the Scripture, they would turn you back, after your belief, [to being] unbelievers.'),
  ('en.sahih', 3, 101, 'And how could you disbelieve while to you are being recited the verses of Allah and among you is His Messenger? And whoever holds firmly to Allah has [indeed] been guided to a straight path.'),
  ('en.sahih', 3, 102, 'O you who have believed, fear Allah as He should be feared and do not die except as Muslims [in submission to Him].'),
  ('en.sahih', 3, 103, 'And hold firmly to the rope of Allah all together and do not become divided. And remember the favor of Allah upon you - when you were enemies and He brought your hearts together and you became, by His favor, brothers. And you were on the edge of a pit of the Fire, and He saved you from it. Thus does Allah make clear to you His verses that you may be guided.'),
  ('en.sahih', 3, 104, 'And let there be [arising] from you a nation inviting to [all that is] good, enjoining what is right and forbidding what is wrong, and those will be the successful.'),
  ('en.sahih', 3, 105, 'And do not be like the ones who became divided and differed after the clear proofs had come to them. And those will have a great punishment.'),
  ('en.sahih', 3, 106, 'On the Day [some] faces will turn white and [some] faces will turn black. As for those whose faces turn black, [to them it will be said], "Did you disbelieve after your belief? Then taste the punishment for what you used to reject."'),
  ('en.sahih', 3, 107, 'But as for those whose faces will turn white, [they will be] within the mercy of Allah. They will abide therein eternally.'),
  ('en.sahih', 3, 108, 'These are the verses of Allah. We recite them to you, [O Muhammad], in truth; and Allah wants no injustice to the worlds.'),
  ('en.sahih', 3, 109, 'To Allah belongs whatever is in the heavens and whatever is on the earth. And to Allah will [all] matters be returned.'),
  ('en.sahih', 3, 110, 'You are the best nation produced [as an example] for mankind. You enjoin what is right and forbid what is wrong and believe in Allah. If only the People of the Scripture had believed, it would have been better for them. Among them are believers, but most of them are defiantly disobedient.'),
  ('en.sahih', 3, 111, 'They will not harm you except for [some] annoyance. And if they fight you, they will show you their backs; then they will not be aided.'),
  ('en.sahih', 3, 112, 'They have been put under humiliation [by Allah] wherever they are overtaken, except for a covenant from Allah and a rope from the Muslims. And they have drawn upon themselves anger from Allah and have been put under destitution. That is because they disbelieved in the verses of Allah and killed the prophets without right. That is because they disobeyed and [habitually] transgressed.'),
  ('en.sahih', 3, 113, 'They are not [all] the same; among the People of the Scripture is a community standing [in obedience], reciting the verses of Allah during periods of the night and prostrating [in prayer].'),
  ('en.sahih', 3, 114, 'They believe in Allah and the Last Day, and they enjoin what is right and forbid what is wrong and hasten to good deeds. And those are among the righteous.'),
  ('en.sahih', 3, 115, 'And whatever good they do - never will it be removed from them. And Allah is Knowing of the righteous.'),
  ('en.sahih', 3, 116, 'Indeed, those who disbelieve - never will their wealth or their children avail them against Allah at all, and those are the companions of the Fire; they will abide therein eternally.'),
  ('en.sahih', 3, 117, 'The example of what they spend in this worldly life is like that of a wind containing frost which strikes the harvest of a people who have wronged themselves and destroys it. And Allah has not wronged them, but they wrong themselves.'),
  ('en.sahih', 3, 118, 'O you who have believed, do not take as intimates those other than yourselves, for they will not spare you [any] ruin. They wish you would have hardship. Hatred has already appeared from their mouths, and what their breasts conceal is greater. We have certainly made clear to you the signs, if you will use reason.'),
  ('en.sahih', 3, 119, 'Here you are loving them but they are not loving you, while you believe in the Scripture - all of it. And when they meet you, they say, "We believe." But when they are alone, they bite their fingertips at you in rage. Say, "Die in your rage. Indeed, Allah is Knowing of that within the breasts."'),
  ('en.sahih', 3, 120, 'If good touches you, it distresses them; but if harm strikes you, they rejoice at it. And if you are patient and fear Allah, their plot will not harm you at all. Indeed, Allah is encompassing of what they do.'),
  ('en.sahih', 3, 121, 'And [remember] when you, [O Muhammad], left your family in the morning to post the believers at their stations for the battle [of Uhud] - and Allah is Hearing and Knowing -'),
  ('en.sahih', 3, 122, 'When two parties among you were about to lose courage, but Allah was their ally; and upon Allah the believers should rely.'),
  ('en.sahih', 3, 123, 'And already had Allah given you victory at [the battle of] Badr while you were few in number. Then fear Allah; perhaps you will be grateful.'),
  ('en.sahih', 3, 124, '[Remember] when you said to the believers, "Is it not sufficient for you that your Lord should reinforce you with three thousand angels sent down?'),
  ('en.sahih', 3, 125, 'Yes, if you remain patient and conscious of Allah and the enemy come upon you [attacking] in rage, your Lord will reinforce you with five thousand angels having marks [of distinction]'),
  ('en.sahih', 3, 126, 'And Allah made it not except as [a sign of] good tidings for you and to reassure your hearts thereby. And victory is not except from Allah, the Exalted in Might, the Wise -'),
  ('en.sahih', 3, 127, 'That He might cut down a section of the disbelievers or suppress them so that they turn back disappointed.'),
  ('en.sahih', 3, 128, 'Not for you, [O Muhammad, but for Allah], is the decision whether He should [cut them down] or forgive them or punish them, for indeed, they are wrongdoers.'),
  ('en.sahih', 3, 129, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. He forgives whom He wills and punishes whom He wills. And Allah is Forgiving and Merciful.'),
  ('en.sahih', 3, 130, 'O you who have believed, do not consume usury, doubled and multiplied, but fear Allah that you may be successful.'),
  ('en.sahih', 3, 131, 'And fear the Fire, which has been prepared for the disbelievers.'),
  ('en.sahih', 3, 132, 'And obey Allah and the Messenger that you may obtain mercy.'),
  ('en.sahih', 3, 133, 'And hasten to forgiveness from your Lord and a garden as wide as the heavens and earth, prepared for the righteous'),
  ('en.sahih', 3, 134, 'Who spend [in the cause of Allah] during ease and hardship and who restrain anger and who pardon the people - and Allah loves the doers of good;'),
  ('en.sahih', 3, 135, 'And those who, when they commit an immorality or wrong themselves [by transgression], remember Allah and seek forgiveness for their sins - and who can forgive sins except Allah? - and [who] do not persist in what they have done while they know.'),
  ('en.sahih', 3, 136, 'Those - their reward is forgiveness from their Lord and gardens beneath which rivers flow [in Paradise], wherein they will abide eternally; and excellent is the reward of the [righteous] workers.'),
  ('en.sahih', 3, 137, 'Similar situations [as yours] have passed on before you, so proceed throughout the earth and observe how was the end of those who denied.'),
  ('en.sahih', 3, 138, 'This [Qur\'an] is a clear statement to [all] the people and a guidance and instruction for those conscious of Allah.'),
  ('en.sahih', 3, 139, 'So do not weaken and do not grieve, and you will be superior if you are [true] believers.'),
  ('en.sahih', 3, 140, 'If a wound should touch you - there has already touched the [opposing] people a wound similar to it. And these days [of varying conditions] We alternate among the people so that Allah may make evident those who believe and [may] take to Himself from among you martyrs - and Allah does not like the wrongdoers -'),
  ('en.sahih', 3, 141, 'And that Allah may purify the believers [through trials] and destroy the disbelievers.'),
  ('en.sahih', 3, 142, 'Or do you think that you will enter Paradise while Allah has not yet made evident those of you who fight in His cause and made evident those who are steadfast?'),
  ('en.sahih', 3, 143, 'And you had certainly wished for martyrdom before you encountered it, and you have [now] seen it [before you] while you were looking on.'),
  ('en.sahih', 3, 144, 'Muhammad is not but a messenger. [Other] messengers have passed on before him. So if he was to die or be killed, would you turn back on your heels [to unbelief]? And he who turns back on his heels will never harm Allah at all; but Allah will reward the grateful.'),
  ('en.sahih', 3, 145, 'And it is not [possible] for one to die except by permission of Allah at a decree determined. And whoever desires the reward of this world - We will give him thereof; and whoever desires the reward of the Hereafter - We will give him thereof. And we will reward the grateful.'),
  ('en.sahih', 3, 146, 'And how many a prophet [fought and] with him fought many religious scholars. But they never lost assurance due to what afflicted them in the cause of Allah, nor did they weaken or submit. And Allah loves the steadfast.'),
  ('en.sahih', 3, 147, 'And their words were not but that they said, "Our Lord, forgive us our sins and the excess [committed] in our affairs and plant firmly our feet and give us victory over the disbelieving people."'),
  ('en.sahih', 3, 148, 'So Allah gave them the reward of this world and the good reward of the Hereafter. And Allah loves the doers of good.'),
  ('en.sahih', 3, 149, 'O you who have believed, if you obey those who disbelieve, they will turn you back on your heels, and you will [then] become losers.'),
  ('en.sahih', 3, 150, 'But Allah is your protector, and He is the best of helpers.'),
  ('en.sahih', 3, 151, 'We will cast terror into the hearts of those who disbelieve for what they have associated with Allah of which He had not sent down [any] authority. And their refuge will be the Fire, and wretched is the residence of the wrongdoers.'),
  ('en.sahih', 3, 152, 'And Allah had certainly fulfilled His promise to you when you were killing the enemy by His permission until [the time] when you lost courage and fell to disputing about the order [given by the Prophet] and disobeyed after He had shown you that which you love. Among you are some who desire this world, and among you are some who desire the Hereafter. Then he turned you back from them [defeated] that He might test you. And He has already forgiven you, and Allah is the possessor of bounty for the believers.'),
  ('en.sahih', 3, 153, '[Remember] when you [fled and] climbed [the mountain] without looking aside at anyone while the Messenger was calling you from behind. So Allah repaid you with distress upon distress so you would not grieve for that which had escaped you [of victory and spoils of war] or [for] that which had befallen you [of injury and death]. And Allah is [fully] Acquainted with what you do.'),
  ('en.sahih', 3, 154, 'Then after distress, He sent down upon you security [in the form of] drowsiness, overcoming a faction of you, while another faction worried about themselves, thinking of Allah other than the truth - the thought of ignorance, saying, "Is there anything for us [to have done] in this matter?" Say, "Indeed, the matter belongs completely to Allah." They conceal within themselves what they will not reveal to you. They say, "If there was anything we could have done in the matter, some of us would not have been killed right here." Say, "Even if you had been inside your houses, those decreed to be killed would have come out to their death beds." [It was] so that Allah might test what is in your breasts and purify what is in your hearts. And Allah is Knowing of that within the breasts.'),
  ('en.sahih', 3, 155, 'Indeed, those of you who turned back on the day the two armies met, it was Satan who caused them to slip because of some [blame] they had earned. But Allah has already forgiven them. Indeed, Allah is Forgiving and Forbearing.'),
  ('en.sahih', 3, 156, 'O you who have believed, do not be like those who disbelieved and said about their brothers when they traveled through the land or went out to fight, "If they had been with us, they would not have died or have been killed," so Allah makes that [misconception] a regret within their hearts. And it is Allah who gives life and causes death, and Allah is Seeing of what you do.'),
  ('en.sahih', 3, 157, 'And if you are killed in the cause of Allah or die - then forgiveness from Allah and mercy are better than whatever they accumulate [in this world].'),
  ('en.sahih', 3, 158, 'And whether you die or are killed, unto Allah you will be gathered.'),
  ('en.sahih', 3, 159, 'So by mercy from Allah, [O Muhammad], you were lenient with them. And if you had been rude [in speech] and harsh in heart, they would have disbanded from about you. So pardon them and ask forgiveness for them and consult them in the matter. And when you have decided, then rely upon Allah. Indeed, Allah loves those who rely [upon Him].'),
  ('en.sahih', 3, 160, 'If Allah should aid you, no one can overcome you; but if He should forsake you, who is there that can aid you after Him? And upon Allah let the believers rely.'),
  ('en.sahih', 3, 161, 'It is not [attributable] to any prophet that he would act unfaithfully [in regard to war booty]. And whoever betrays, [taking unlawfully], will come with what he took on the Day of Resurrection. Then will every soul be [fully] compensated for what it earned, and they will not be wronged.'),
  ('en.sahih', 3, 162, 'So is one who pursues the pleasure of Allah like one who brings upon himself the anger of Allah and whose refuge is Hell? And wretched is the destination.'),
  ('en.sahih', 3, 163, 'They are [varying] degrees in the sight of Allah, and Allah is Seeing of whatever they do.'),
  ('en.sahih', 3, 164, 'Certainly did Allah confer [great] favor upon the believers when He sent among them a Messenger from themselves, reciting to them His verses and purifying them and teaching them the Book and wisdom, although they had been before in manifest error.'),
  ('en.sahih', 3, 165, 'Why [is it that] when a [single] disaster struck you [on the day of Uhud], although you had struck [the enemy in the battle of Badr] with one twice as great, you said, "From where is this?" Say, "It is from yourselves." Indeed, Allah is over all things competent.'),
  ('en.sahih', 3, 166, 'And what struck you on the day the two armies met was by permission of Allah that He might make evident the [true] believers.'),
  ('en.sahih', 3, 167, 'And that He might make evident those who are hypocrites. For it was said to them, "Come, fight in the way of Allah or [at least] defend." They said, "If we had known [there would be] fighting, we would have followed you." They were nearer to disbelief that day than to faith, saying with their mouths what was not in their hearts. And Allah is most Knowing of what they conceal -'),
  ('en.sahih', 3, 168, 'Those who said about their brothers while sitting [at home], "If they had obeyed us, they would not have been killed." Say, "Then prevent death from yourselves, if you should be truthful."'),
  ('en.sahih', 3, 169, 'And never think of those who have been killed in the cause of Allah as dead. Rather, they are alive with their Lord, receiving provision,'),
  ('en.sahih', 3, 170, 'Rejoicing in what Allah has bestowed upon them of His bounty, and they receive good tidings about those [to be martyred] after them who have not yet joined them - that there will be no fear concerning them, nor will they grieve.'),
  ('en.sahih', 3, 171, 'They receive good tidings of favor from Allah and bounty and [of the fact] that Allah does not allow the reward of believers to be lost -'),
  ('en.sahih', 3, 172, 'Those [believers] who responded to Allah and the Messenger after injury had struck them. For those who did good among them and feared Allah is a great reward -'),
  ('en.sahih', 3, 173, 'Those to whom hypocrites said, "Indeed, the people have gathered against you, so fear them." But it [merely] increased them in faith, and they said, "Sufficient for us is Allah, and [He is] the best Disposer of affairs."'),
  ('en.sahih', 3, 174, 'So they returned with favor from Allah and bounty, no harm having touched them. And they pursued the pleasure of Allah, and Allah is the possessor of great bounty.'),
  ('en.sahih', 3, 175, 'That is only Satan who frightens [you] of his supporters. So fear them not, but fear Me, if you are [indeed] believers.'),
  ('en.sahih', 3, 176, 'And do not be grieved, [O Muhammad], by those who hasten into disbelief. Indeed, they will never harm Allah at all. Allah intends that He should give them no share in the Hereafter, and for them is a great punishment.'),
  ('en.sahih', 3, 177, 'Indeed, those who purchase disbelief [in exchange] for faith - never will they harm Allah at all, and for them is a painful punishment.'),
  ('en.sahih', 3, 178, 'And let not those who disbelieve ever think that [because] We extend their time [of enjoyment] it is better for them. We only extend it for them so that they may increase in sin, and for them is a humiliating punishment.'),
  ('en.sahih', 3, 179, 'Allah would not leave the believers in that [state] you are in [presently] until He separates the evil from the good. Nor would Allah reveal to you the unseen. But [instead], Allah chooses of His messengers whom He wills, so believe in Allah and His messengers. And if you believe and fear Him, then for you is a great reward.'),
  ('en.sahih', 3, 180, 'And let not those who [greedily] withhold what Allah has given them of His bounty ever think that it is better for them. Rather, it is worse for them. Their necks will be encircled by what they withheld on the Day of Resurrection. And to Allah belongs the heritage of the heavens and the earth. And Allah, with what you do, is [fully] Acquainted.'),
  ('en.sahih', 3, 181, 'Allah has certainly heard the statement of those [Jews] who said, "Indeed, Allah is poor, while we are rich." We will record what they said and their killing of the prophets without right and will say, "Taste the punishment of the Burning Fire.'),
  ('en.sahih', 3, 182, 'That is for what your hands have put forth and because Allah is not ever unjust to [His] servants."'),
  ('en.sahih', 3, 183, '[They are] those who said, "Indeed, Allah has taken our promise not to believe any messenger until he brings us an offering which fire [from heaven] will consume." Say, "There have already come to you messengers before me with clear proofs and [even] that of which you speak. So why did you kill them, if you should be truthful?"'),
  ('en.sahih', 3, 184, 'Then if they deny you, [O Muhammad] - so were messengers denied before you, who brought clear proofs and written ordinances and the enlightening Scripture.'),
  ('en.sahih', 3, 185, 'Every soul will taste death, and you will only be given your [full] compensation on the Day of Resurrection. So he who is drawn away from the Fire and admitted to Paradise has attained [his desire]. And what is the life of this world except the enjoyment of delusion.'),
  ('en.sahih', 3, 186, 'You will surely be tested in your possessions and in yourselves. And you will surely hear from those who were given the Scripture before you and from those who associate others with Allah much abuse. But if you are patient and fear Allah - indeed, that is of the matters [worthy] of determination.'),
  ('en.sahih', 3, 187, 'And [mention, O Muhammad], when Allah took a covenant from those who were given the Scripture, [saying], "You must make it clear to the people and not conceal it." But they threw it away behind their backs and exchanged it for a small price. And wretched is that which they purchased.'),
  ('en.sahih', 3, 188, 'And never think that those who rejoice in what they have perpetrated and like to be praised for what they did not do - never think them [to be] in safety from the punishment, and for them is a painful punishment.'),
  ('en.sahih', 3, 189, 'And to Allah belongs the dominion of the heavens and the earth, and Allah is over all things competent.'),
  ('en.sahih', 3, 190, 'Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding.'),
  ('en.sahih', 3, 191, 'Who remember Allah while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], "Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire.'),
  ('en.sahih', 3, 192, 'Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers.'),
  ('en.sahih', 3, 193, 'Our Lord, indeed we have heard a caller calling to faith, [saying], \'Believe in your Lord,\' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous.'),
  ('en.sahih', 3, 194, 'Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise."'),
  ('en.sahih', 3, 195, 'And their Lord responded to them, "Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allah, and Allah has with Him the best reward."'),
  ('en.sahih', 3, 196, 'Be not deceived by the [uninhibited] movement of the disbelievers throughout the land.'),
  ('en.sahih', 3, 197, '[It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place.'),
  ('en.sahih', 3, 198, 'But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allah. And that which is with Allah is best for the righteous.'),
  ('en.sahih', 3, 199, 'And indeed, among the People of the Scripture are those who believe in Allah and what was revealed to you and what was revealed to them, [being] humbly submissive to Allah. They do not exchange the verses of Allah for a small price. Those will have their reward with their Lord. Indeed, Allah is swift in account.'),
  ('en.sahih', 3, 200, 'O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 3, 1, 'আলিফ লাম মীম।'),
  ('bn.bengali', 3, 2, 'আল্লাহ ছাড়া কোন উপাস্য নেই, তিনি চিরঞ্জীব, সবকিছুর ধারক।'),
  ('bn.bengali', 3, 3, 'তিনি আপনার প্রতি কিতাব নাযিল করেছেন সত্যতার সাথে; যা সত্যায়ন করে পূর্ববর্তী কিতাবসমুহের।'),
  ('bn.bengali', 3, 4, 'নাযিল করেছেন তাওরত ও ইঞ্জিল, এ কিতাবের পূর্বে, মানুষের হেদায়েতের জন্যে এবং অবতীর্ণ করেছেন মীমাংসা। নিঃসন্দেহে যারা আল্লাহর আয়াতসমূহ অস্বীকার করে, তাদের জন্যে রয়েছে কঠিন আযাব। আর আল্লাহ হচ্ছেন পরাক্রমশীল, প্রতিশোধ গ্রহণকারী।'),
  ('bn.bengali', 3, 5, 'আল্লাহর নিকট আসমান ও যমীনের কোন বিষয়ই গোপন নেই।'),
  ('bn.bengali', 3, 6, 'তিনিই সেই আল্লাহ, যিনি তোমাদের আকৃতি গঠন করেন মায়ের গর্ভে, যেমন তিনি চেয়েছেন। তিনি ছাড়া আর কোন উপাস্য নেই। তিনি প্রবল পরাক্রমশীল, প্রজ্ঞাময়।'),
  ('bn.bengali', 3, 7, 'তিনিই আপনার প্রতি কিতাব নাযিল করেছেন। তাতে কিছু আয়াত রয়েছে সুস্পষ্ট, সেগুলোই কিতাবের আসল অংশ। আর অন্যগুলো রূপক। সুতরাং যাদের অন্তরে কুটিলতা রয়েছে, তারা অনুসরণ করে ফিৎনা বিস্তার এবং অপব্যাখ্যার উদ্দেশে তন্মধ্যেকার রূপকগুলোর। আর সেগুলোর ব্যাখ্যা আল্লাহ ব্যতীত কেউ জানে না। আর যারা জ্ঞানে সুগভীর, তারা বলেনঃ আমরা এর প্রতি ঈমান এনেছি। এই সবই আমাদের পালনকর্তার পক্ষ থেকে অবতীর্ণ হয়েছে। আর বোধশক্তি সম্পন্নেরা ছাড়া অপর কেউ শিক্ষা গ্রহণ করে না।'),
  ('bn.bengali', 3, 8, 'হে আমাদের পালনকর্তা! সরল পথ প্রদর্শনের পর তুমি আমাদের অন্তরকে সত্যলংঘনে প্রবৃত্ত করোনা এবং তোমার নিকট থেকে আমাদিগকে অনুগ্রহ দান কর। তুমিই সব কিছুর দাতা।'),
  ('bn.bengali', 3, 9, 'হে আমাদের পালনকর্তা! তুমি মানুষকে একদিন অবশ্যই একত্রিত করবেঃ এতে কোনই সন্দেহ নেই। নিশ্চয় আল্লাহ তাঁর ওয়াদার অন্যথা করেন না।'),
  ('bn.bengali', 3, 10, 'যারা কুফুরী করে, তাদের ধন-সম্পদ ও সন্তান-সন্ততি আল্লাহর সামনে কখনও কাজে আসবে না। আর তারাই হচ্ছে দোযখের ইন্ধন।'),
  ('bn.bengali', 3, 11, 'ফেরআউনের সম্প্রদায় এবং তাদের পূর্ববর্তীদের ধারা অনুযায়ীই তারা আমার আয়াতসমূহকে মিথ্যা প্রতিপন্ন করেছে। ফলে তাদের পাপের কারণে আল্লাহ তাদেরকে পাকড়াও করেছেন আর আল্লাহর আযাব অতি কঠিন।'),
  ('bn.bengali', 3, 12, 'কাফেরদিগকে বলে দিন, খুব শিগগীরই তোমরা পরাভূত হয়ে দোযখের দিকে হাঁকিয়ে নীত হবে-সেটা কতই না নিকৃষ্টতম অবস্থান।'),
  ('bn.bengali', 3, 13, 'নিশ্চয়ই দুটো দলের মোকাবিলার মধ্যে তোমাদের জন্য নিদর্শন ছিল। একটি দল আল্লাহর রাহে যুদ্ধ করে। আর অপর দল ছিল কাফেরদের এরা স্বচক্ষে তাদেরকে দ্বিগুন দেখছিল। আর আল্লাহ যাকে নিজের সাহায্যের মাধ্যমে শক্তি দান করেন। এরই মধ্যে শিক্ষনীয় রয়েছে দৃষ্টি সম্পন্নদের জন্য।'),
  ('bn.bengali', 3, 14, 'মানবকূলকে মোহগ্রস্ত করেছে নারী, সন্তান-সন্ততি, রাশিকৃত স্বর্ণ-রৌপ্য, চিহ্নিত অশ্ব, গবাদি পশুরাজি এবং ক্ষেত-খামারের মত আকর্ষণীয় বস্তুসামগ্রী। এসবই হচ্ছে পার্থিব জীবনের ভোগ্য বস্তু। আল্লাহর নিকটই হলো উত্তম আশ্রয়।'),
  ('bn.bengali', 3, 15, 'বলুন, আমি কি তোমাদেরকে এসবের চাইতেও উত্তম বিষয়ের সন্ধান বলবো?-যারা পরহেযগার, আল্লাহর নিকট তাদের জন্যে রয়েছে বেহেশত, যার তলদেশে প্রস্রবণ প্রবাহিত-তারা সেখানে থাকবে অনন্তকাল। আর রয়েছে পরিচ্ছন্ন সঙ্গিনীগণ এবং আল্লাহর সন্তুষ্টি। আর আল্লাহ তাঁর বান্দাদের প্রতি সুদৃষ্টি রাখেন।'),
  ('bn.bengali', 3, 16, 'যারা বলে, হে আমাদের পালনকর্তা, আমরা ঈমান এনেছি, কাজেই আমাদের গোনাহ ক্ষমা করে দাও আর আমাদেরকে দোযখের আযাব থেকে রক্ষা কর।'),
  ('bn.bengali', 3, 17, 'তারা ধৈর্য্যধারণকারী, সত্যবাদী, নির্দেশ সম্পাদনকারী, সৎপথে ব্যয়কারী এবং শেষরাতে ক্ষমা প্রার্থনাকারী।'),
  ('bn.bengali', 3, 18, 'আল্লাহ সাক্ষ্য দিয়েছেন যে, তাঁকে ছাড়া আর কোন উপাস্য নেই। ফেরেশতাগণ এবং ন্যায়নিষ্ঠ জ্ঞানীগণও সাক্ষ্য দিয়েছেন যে, তিনি ছাড়া আর কোন ইলাহ নেই। তিনি পরাক্রমশালী প্রজ্ঞাময়।'),
  ('bn.bengali', 3, 19, 'নিঃসন্দেহে আল্লাহর নিকট গ্রহণযোগ্য দ্বীন একমাত্র ইসলাম। এবং যাদের প্রতি কিতাব দেয়া হয়েছে তাদের নিকট প্রকৃত জ্ঞান আসার পরও ওরা মতবিরোধে লিপ্ত হয়েছে, শুধুমাত্র পরস্পর বিদ্বেষবশতঃ, যারা আল্লাহর নিদর্শনসমূহের প্রতি কুফরী করে তাদের জানা উচিত যে, নিশ্চিতরূপে আল্লাহ হিসাব গ্রহণে অত্যন্ত দ্রুত।'),
  ('bn.bengali', 3, 20, 'যদি তারা তোমার সাথে বিতর্কে অবতীর্ণ হয় তবে বলে দাও, "আমি এবং আমার অনুসরণকারীগণ আল্লাহর প্রতি আত্নসমর্পণ করেছি।" আর আহলে কিতাবদের এবং নিরক্ষরদের বলে দাও যে, তোমরাও কি আত্নসমর্পণ করেছ? তখন যদি তারা আত্নসমর্পণ করে, তবে সরল পথ প্রাপ্ত হলো, আর যদি মুখ ঘুরিয়ে নেয়, তাহলে তোমার দায়িত্ব হলো শুধু পৌছে দেয়া। আর আল্লাহর দৃষ্টিতে রয়েছে সকল বান্দা।'),
  ('bn.bengali', 3, 21, 'যারা আল্লাহর নিদর্শনাবলীকে অস্বীকার করে এবং পয়গম্বরগণকে হত্যা করে অন্যায়ভাবে, আর সেসব লোককে হত্যা করে যারা ন্যায়পরায়ণতার নির্দেশ দেয় তাদেরকে বেদনাদায়ক শাস্তির সংবাদ দিন।'),
  ('bn.bengali', 3, 22, 'এরাই হলো সে লোক যাদের সমগ্র আমল দুনিয়া ও আখেরাত উভয়লোকেই বিনষ্ট হয়ে গেছে। পক্ষান্তরে তাদের কোন সাহায্যকারীও নেই।'),
  ('bn.bengali', 3, 23, 'আপনি কি তাদের দেখেননি, যারা কিতাবের কিছু অংশ পেয়েছে-আল্লাহর কিতাবের প্রতি তাদের আহবান করা হয়েছিল যাতে তাদের মধ্যে মীমাংসা করা যায়। অতঃপর তাদের মধ্যে একদল তা অমান্য করে মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 3, 24, 'তা এজন্য যে, তারা বলে থাকে যে, দোযখের আগুন আমাদের স্পর্শ করবে না; তবে সামান্য হাতে গোনা কয়েকদিনের জন্য স্পর্শ করতে পারে। নিজেদের উদ্ভাবিত ভিত্তিহীন কথায় তারা ধোকা খেয়েছে।'),
  ('bn.bengali', 3, 25, 'কিন্তু তখন কি অবস্থা দাঁড়াবে যখন আমি তাদেরকে একদিন সমবেত করবো যে দিনের আগমনে কোন সন্দেহ নেই আর নিজেদের কৃতকর্ম তাদের প্রত্যেকেই পাবে তাদের প্রাপ্য প্রদান মোটেই অন্যায় করা হবে না।'),
  ('bn.bengali', 3, 26, 'বলুন ইয়া আল্লাহ! তুমিই সার্বভৌম শক্তির অধিকারী। তুমি যাকে ইচ্ছা রাজ্য দান কর এবং যার কাছ থেকে ইচ্ছা রাজ্য ছিনিয়ে নাও এবং যাকে ইচ্ছা সম্মান দান কর আর যাকে ইচ্ছা অপমানে পতিত কর। তোমারই হাতে রয়েছে যাবতীয় কল্যাণ। নিশ্চয়ই তুমি সর্ব বিষয়ে ক্ষমতাশীল।'),
  ('bn.bengali', 3, 27, 'তুমি রাতকে দিনের ভেতরে প্রবেশ করাও এবং দিনকে রাতের ভেতরে প্রবেশ করিয়ে দাও। আর তুমিই জীবিতকে মৃতের ভেতর থেকে বের করে আন এবং মৃতকে জীবিতের ভেতর থেকে বের কর। আর তুমিই যাকে ইচ্ছা বেহিসাব রিযিক দান কর।'),
  ('bn.bengali', 3, 28, 'মুমিনগন যেন অন্য মুমিনকে ছেড়ে কেন কাফেরকে বন্ধুরূপে গ্রহণ না করে। যারা এরূপ করবে আল্লাহর সাথে তাদের কেন সম্পর্ক থাকবে না। তবে যদি তোমরা তাদের পক্ষ থেকে কোন অনিষ্টের আশঙ্কা কর, তবে তাদের সাথে সাবধানতার সাথে থাকবে আল্লাহ তা’আলা তাঁর সম্পর্কে তোমাদের সতর্ক করেছেন। এবং সবাই কে তাঁর কাছে ফিরে যেতে হবে।'),
  ('bn.bengali', 3, 29, 'বলে দিন, তোমরা যদি মনের কথা গোপন করে রাখ অথবা প্রকাশ করে দাও, আল্লাহ সে সবই জানতে পারেন। আর আসমান ও জমিনে যা কিছু আছে, সেসব ও তিনি জানেন। আল্লাহ সর্ব বিষয়ে শক্তিমান।'),
  ('bn.bengali', 3, 30, 'সেদিন প্রত্যেকেই যা কিছু সে ভাল কাজ করেছে; চোখের সামনে দেখতে পাবে এবং যা কিছু মন্দ কাজ করেছে তাও, ওরা তখন কামনা করবে, যদি তার এবং এসব কর্মের মধ্যে ব্যবধান দুরের হতো! আল্লাহ তাঁর নিজের সম্পর্কে তোমাদের সাবধান করছেন। আল্লাহ তাঁর বান্দাদের প্রতি অত্যন্ত দয়ালু।'),
  ('bn.bengali', 3, 31, 'বলুন, যদি তোমরা আল্লাহকে ভালবাস, তাহলে আমাকে অনুসরণ কর, যাতে আল্লাহ ও তোমাদিগকে ভালবাসেন এবং তোমাদিগকে তোমাদের পাপ মার্জনা করে দেন। আর আল্লাহ হলেন ক্ষমাকারী দয়ালু।'),
  ('bn.bengali', 3, 32, 'বলুন, আল্লাহ ও রসূলের আনুগত্য প্রকাশ কর। বস্তুতঃ যদি তারা বিমুখতা অবলম্বন করে, তাহলে আল্লাহ কাফেরদিগকে ভালবাসেন না।'),
  ('bn.bengali', 3, 33, 'নিঃসন্দেহে আল্লাহ আদম (আঃ) নূহ (আঃ)͠ও ইব্রাহীম (আঃ) এর বংশধর এবং এমরানের খান্দানকে নির্বাচিত করেছেন।'),
  ('bn.bengali', 3, 34, 'যারা বংশধর ছিলেন পরস্পরের। আল্লাহ শ্রবণকারী ও মহাজ্ঞানী।'),
  ('bn.bengali', 3, 35, 'এমরানের স্ত্রী যখন বললো-হে আমার পালনকর্তা! আমার গর্ভে যা রয়েছে আমি তাকে তোমার নামে উৎসর্গ করলাম সবার কাছ থেকে মুক্ত রেখে। আমার পক্ষ থেকে তুমি তাকে কবুল করে নাও, নিশ্চয়ই তুমি শ্রবণকারী, সর্বজ্ঞাত।'),
  ('bn.bengali', 3, 36, 'অতঃপর যখন তাকে প্রসব করলো বলল, হে আমার পালনকর্তা! আমি একে কন্যা প্রসব করেছি। বস্তুতঃ কি সে প্রসব করেছে আল্লাহ তা ভালই জানেন। সেই কন্যার মত কোন পুত্রই যে নেই। আর আমি তার নাম রাখলাম মারইয়াম। আর আমি তাকে ও তার সন্তানদেরকে তোমার আশ্রয়ে সমর্পণ করছি। অভিশপ্ত শয়তানের কবল থেকে।'),
  ('bn.bengali', 3, 37, 'অতঃপর তাঁর পালনকর্তা তাঁকে উত্তম ভাবে গ্রহণ করে নিলেন এবং তাঁকে প্রবৃদ্ধি দান করলেন-অত্যন্ত সুন্দর প্রবৃদ্ধি। আর তাঁকে যাকারিয়ার তত্ত্বাবধানে সমর্পন করলেন। যখনই যাকারিয়া মেহরাবের মধ্যে তার কছে আসতেন তখনই কিছু খাবার দেখতে পেতেন। জিজ্ঞেস করতেন "মারইয়াম! কোথা থেকে এসব তোমার কাছে এলো?" তিনি বলতেন, "এসব আল্লাহর নিকট থেকে আসে। আল্লাহ যাকে ইচ্ছা বেহিসাব রিযিক দান করেন।"'),
  ('bn.bengali', 3, 38, 'সেখানেই যাকারিয়া তাঁর পালনকর্তার নিকট প্রার্থনা করলেন। বললেন, হে, আমার পালনকর্তা! তোমার নিকট থেকে আমাকে পুত-পবিত্র সন্তান দান কর-নিশ্চয়ই তুমি প্রার্থনা শ্রবণকারী।'),
  ('bn.bengali', 3, 39, 'যখন তিনি কামরার ভেতরে নামাযে দাঁড়িয়েছিলেন, তখন ফেরেশতারা তাঁকে ডেকে বললেন যে, আল্লাহ তোমাকে সুসংবাদ দিচ্ছেন ইয়াহইয়া সম্পর্কে, যিনি সাক্ষ্য দেবেন আল্লাহর নির্দেশের সত্যতা সম্পর্কে, যিনি নেতা হবেন এবং নারীদের সংস্পর্শে যাবেন না, তিনি অত্যন্ত সৎকর্মশীল নবী হবেন।'),
  ('bn.bengali', 3, 40, 'তিনি বললেন হে পালনকর্তা! কেমন করে আমার পুত্র সন্তান হবে, আমার যে বার্ধক্য এসে গেছে, আমার স্ত্রীও যে বন্ধ্যা। বললেন, আল্লাহ এমনি ভাবেই যা ইচ্ছা করে থাকেন।'),
  ('bn.bengali', 3, 41, 'তিনি বললেন, হে পালনকর্তা আমার জন্য কিছু নিদর্শন দাও। তিনি বললেন, তোমার জন্য নিদর্শন হলো এই যে, তুমি তিন দিন পর্যন্ত কারও সাথে কথা বলবে না। তবে ইশারা ইঙ্গতে করতে পারবে এবং তোমার পালনকর্তাকে অধিক পরিমাণে স্মরণ করবে আর সকাল-সন্ধ্যা তাঁর পবিত্রতা ও মহিমা ঘোষনা করবে।'),
  ('bn.bengali', 3, 42, 'আর যখন ফেরেশতা বলল হে মারইয়াম!, আল্লাহ তোমাকে পছন্দ করেছেন এবং তোমাকে পবিত্র পরিচ্ছন্ন করে দিয়েছেন। আর তোমাকে বিশ্ব নারী সমাজের উর্ধ্বে মনোনীত করেছেন।'),
  ('bn.bengali', 3, 43, 'হে মারইয়াম! তোমার পালনকর্তার উপাসনা কর এবং রুকুকারীদের সাথে সেজদা ও রুকু কর।'),
  ('bn.bengali', 3, 44, 'এ হলো গায়েবী সংবাদ, যা আমি আপনাকে পাঠিয়ে থাকি। আর আপনি তো তাদের কাছে ছিলেন না, যখন প্রতিযোগিতা করছিল যে, কে প্রতিপালন করবে মারইয়ামকে এবং আপনি তাদের কাছে ছিলেন না, যখন তারা ঝগড়া করছিলো।'),
  ('bn.bengali', 3, 45, 'যখন ফেরেশতাগণ বললো, হে মারইয়াম আল্লাহ তোমাকে তাঁর এক বানীর সুসংবাদ দিচ্ছেন, যার নাম হলো মসীহ-মারইয়াম-তনয় ঈসা, দুনিয়া ও আখেরাতে তিনি মহাসম্মানের অধিকারী এবং আল্লাহর ঘনিষ্ঠদের অন্তর্ভূক্ত।'),
  ('bn.bengali', 3, 46, 'যখন তিনি মায়ের কোলে থাকবেন এবং পূর্ণ বয়স্ক হবেন তখন তিনি মানুষের সাথে কথা বলবেন। আর তিনি সৎকর্মশীলদের অন্তর্ভুক্ত হবেন।'),
  ('bn.bengali', 3, 47, 'তিনি বললেন, পরওয়ারদেগার! কেমন করে আমার সন্তান হবে; আমাকে তো কোন মানুষ স্পর্শ করেনি। বললেন এ ভাবেই আল্লাহ যা ইচ্ছা সৃষ্টি করেন। যখন কোন কাজ করার জন্য ইচ্ছা করেন তখন বলেন যে, ‘হয়ে যাও’ অমনি তা হয়ে যায়।'),
  ('bn.bengali', 3, 48, 'আর তাকে তিনি শিখিয়ে দেবেন কিতাব, হিকমত, তওরাত, ইঞ্জিল।'),
  ('bn.bengali', 3, 49, 'আর বণী ইসরাঈলদের জন্যে রসূল হিসেবে তাকে মনোনীত করবেন। তিনি বললেন নিশ্চয়ই আমি তোমাদের নিকট তোমাদের পালনকর্তার পক্ষ থেকে এসেছি নিদর্শনসমূহ নিয়ে। আমি তোমাদের জন্য মাটির দ্বারা পাখীর আকৃতি তৈরী করে দেই। তারপর তাতে যখন ফুৎকার প্রদান করি, তখন তা উড়ন্ত পাখীতে পরিণত হয়ে যায় আল্লাহর হুকুমে। আর আমি সুস্থ করে তুলি জন্মান্ধকে এবং শ্বেত কুষ্ঠ রোগীকে। আর আমি জীবিত করে দেই মৃতকে আল্লাহর হুকুমে। আর আমি তোমাদেরকে বলে দেই যা তোমরা খেয়ে আস এবং যা তোমরা ঘরে রেখে আস। এতে প্রকৃষ্ট নিদর্শন রয়েছে, যদি তোমরা বিশ্বাসী হও।'),
  ('bn.bengali', 3, 50, 'আর এটি পূর্ববর্তী কিতাব সমুহকে সত্যায়ন করে, যেমন তওরাত। আর তা এজন্য যাতে তোমাদের জন্য হালাল করে দেই কোন কোন বস্তু যা তোমাদের জন্য হারাম ছিল। আর আমি তোমাদের নিকট এসেছি তোমাদের পালনকর্তার নিদর্শনসহ। কাজেই আল্লাহকে ভয় কর এবং আমার অনুসরণ কর।'),
  ('bn.bengali', 3, 51, 'নিশ্চয়ই আল্লাহ আমার পালনকর্তা এবং তোমাদেরও পালনকর্তা-তাঁর এবাদত কর, এটাই হলো সরল পথ।'),
  ('bn.bengali', 3, 52, 'অতঃপর ঈসা (আঃ) যখন বণী ইসরায়ীলের কুফরী সম্পর্কে উপলব্ধি করতে পারলেন, তখন বললেন, কারা আছে আল্লাহর পথে আমাকে সাহায্য করবে? সঙ্গী-সাথীরা বললো, আমরা রয়েছি আল্লাহর পথে সাহায্যকারী। আমরা আল্লাহর প্রতি ঈমান এনেছি। আর তুমি সাক্ষী থাক যে, আমরা হুকুম কবুল করে নিয়েছি।'),
  ('bn.bengali', 3, 53, 'হে আমাদের পালনকর্তা! আমরা সে বিষয়ের প্রতি বিশ্বাস স্থাপন করেছি যা তুমি নাযিল করেছ, আমরা রসূলের অনুগত হয়েছি। অতএব, আমাদিগকে মান্যকারীদের তালিকাভুক্ত করে নাও।'),
  ('bn.bengali', 3, 54, 'এবং কাফেরেরা চক্রান্ত করেছে আর আল্লাহও কৌশল অবলম্বন করেছেন। বস্তুতঃ আল্লাহ হচ্ছেন সর্বোত্তম কুশলী।'),
  ('bn.bengali', 3, 55, 'আর স্মরণ কর, যখন আল্লাহ বলবেন, হে ঈসা! আমি তোমাকে নিয়ে নেবো এবং তোমাকে নিজের দিকে তুলে নিবো-কাফেরদের থেকে তোমাকে পবিত্র করে দেবো। আর যারা তোমার অনুগত রয়েছে তাদেরকে কিয়ামতের দিন পর্যন্ত যারা অস্বীকৃতি জ্ঞাপন করে তাদের উপর জয়ী করে রাখবো। বস্তুতঃ তোমাদের সবাইকে আমার কাছেই ফিরে আসতে হবে। তখন যে বিষয়ে তোমরা বিবাদ করতে, আমি তোমাদের মধ্যে তার ফয়সালা করে দেবো।'),
  ('bn.bengali', 3, 56, 'অতএব যারা কাফের হয়েছে, তাদেরকে আমি কঠিন শাস্তি দেবো দুনিয়াতে এবং আখেরাতে-তাদের কোন সাহায্যকারী নেই।'),
  ('bn.bengali', 3, 57, 'পক্ষান্তরে যারা ঈমান এনেছে এবং সৎকাজ করেছে। তাদের প্রাপ্য পরিপুর্ণভাবে দেয়া হবে। আর আল্লাহ অত্যাচারীদেরকে ভালবাসেন না।'),
  ('bn.bengali', 3, 58, 'আমি তোমাদেরকে পড়ে শুনাই এ সমস্ত আয়াত এবং নিশ্চিত বর্ণনা।'),
  ('bn.bengali', 3, 59, 'নিঃসন্দেহে আল্লাহর নিকট ঈসার দৃষ্টান্ত হচ্ছে আদমেরই মতো। তাকে মাটি দিয়ে তৈরী করেছিলেন এবং তারপর তাকে বলেছিলেন হয়ে যাও, সঙ্গে সঙ্গে হয়ে গেলেন।'),
  ('bn.bengali', 3, 60, 'যা তোমার পালকর্তা বলেন তাই হচ্ছে যথার্থ সত্য। কাজেই তোমরা সংশয়বাদী হয়ো না।'),
  ('bn.bengali', 3, 61, 'অতঃপর তোমার নিকট সত্য সংবাদ এসে যাওয়ার পর যদি এই কাহিনী সম্পর্কে তোমার সাথে কেউ বিবাদ করে, তাহলে বল-এসো, আমরা ডেকে নেই আমাদের পুত্রদের এবং তোমাদের পুত্রদের এবং আমাদের স্ত্রীদের ও তোমাদের স্ত্রীদের এবং আমাদের নিজেদের ও তোমাদের নিজেদের আর তারপর চল আমরা সবাই মিলে প্রার্থনা করি এবং তাদের প্রতি আল্লাহর অভিসম্পাত করি যারা মিথ্যাবাদী।'),
  ('bn.bengali', 3, 62, 'নিঃসন্দেহে এটাই হলো সত্য ভাষণ। আর এক আল্লাহ ছাড়া অন্য কোন ইলাহ নেই। আর আল্লাহ; তিনিই হলেন পরাক্রমশালী মহাপ্রাজ্ঞ।'),
  ('bn.bengali', 3, 63, 'তারপর যদি তারা গ্রহণ না করে, তাহলে প্রমাদ সৃষ্টিকারীদেরকে আল্লাহ জানেন।'),
  ('bn.bengali', 3, 64, 'বলুনঃ ‘হে আহলে-কিতাবগণ! একটি বিষয়ের দিকে আস-যা আমাদের মধ্যে ও তোমাদের মধ্যে সমান-যে, আমরা আল্লাহ ছাড়া অন্য কারও ইবাদত করব না, তাঁর সাথে কোন শরীক সাব্যস্ত করব না এবং একমাত্র আল্লাহকে ছাড়া কাউকে পালনকর্তা বানাব না। তারপর যদি তারা স্বীকার না করে, তাহলে বলে দাও যে, ‘সাক্ষী থাক আমরা তো অনুগত।'),
  ('bn.bengali', 3, 65, 'হে আহলে কিতাবগণ! কেন তোমরা ইব্রাহীমের বিষয়ে বাদানুবাদ কর? অথচ তওরাত ও ইঞ্জিল তাঁর পরেই নাযিল হয়েছে। তোমরা কি বুঝ না?'),
  ('bn.bengali', 3, 66, 'শোন! ইতিপূর্বে তোমরা যে বিষয়ে কিছু জানতে, তাই নিয়ে বিবাদ করতে। এখন আবার যে বিষয়ে তোমরা কিছুই জান না, সে বিষয়ে কেন বিবাদ করছ?'),
  ('bn.bengali', 3, 67, 'ইব্রাহীম ইহুদী ছিলেন না এবং নাসারাও ছিলেন না, কিক্তু তিনি ছিলেন ‘হানীফ’ অর্থাৎ, সব মিথ্যা ধর্মের প্রতি বিমুখ এবং আত্নসমর্পণকারী, এবং তিনি মুশরিক ছিলেন না।'),
  ('bn.bengali', 3, 68, 'মানুষদের মধ্যে যারা ইব্রাহীমের অনুসরণ করেছিল, তারা, আর এই নবী এবং যারা এ নবীর প্রতি ঈমান এনেছে তারা ইব্রাহীমের ঘনিষ্ঠতম-আর আল্লাহ হচ্ছেন মুমিনদের বন্ধু।'),
  ('bn.bengali', 3, 69, 'কোন কোন আহলে-কিতাবের আকাঙ্খা, যাতে তোমাদের গোমরাহ করতে পারে, কিন্তু তারা নিজেদের ছাড়া অন্য কাউকেই গোমরাহ করে না। অথচ তারা বুঝতে পারে না।'),
  ('bn.bengali', 3, 70, 'হে আহলে-কিতাবগণ, কেন তোমরা আল্লাহর কালামকে অস্বীকার কর, অথচ তোমরাই তাঁর প্রবক্তা?'),
  ('bn.bengali', 3, 71, 'হে আহলে কিতাবগণ, কেন তোমরা সত্যকে মিথ্যার সাথে সংমিশ্রণ করছ এবং সত্যকে গোপন করছ, অথচ তোমরা তা জান।'),
  ('bn.bengali', 3, 72, 'আর আহলে-কিতাবগণের একদল বললো, মুসলমানগণের উপর যা কিছু অবর্তীণ হয়েছে তাকে দিনের প্রথম ভাগে মেনে নাও, আর দিনের শেষ ভাগে অস্বীকার ক র, হয়তো তারা মুখ ফিরিয়ে নিতে পারে।'),
  ('bn.bengali', 3, 73, 'যারা তোমাদের ধর্মমতে চলবে, তাদের ছাড়া আর কাউকে বিশ্বাস করবে না। বলে দিন নিঃসন্দেহে হেদায়েত সেটাই, যে হেদায়েত আল্লাহ করেন। আর এসব কিছু এ জন্যে যে, তোমরা যা লাভ করেছিলে তা অন্য কেউ কেন প্রাপ্ত হবে, কিংবা তোমাদের পালনকর্তার সামনে তোমাদের উপর তারা কেন প্রবল হয়ে যাবে! বলে দিন, মর্যাদা আল্লাহরই হাতে; তিনি যাকে ইচ্ছা দান করেন এবং আল্লাহ প্রাচুর্যময় ও সর্বজ্ঞ।'),
  ('bn.bengali', 3, 74, 'তিনি যাকে ইচ্ছা নিজের বিশেষ অনুগ্রহ দান করেন। আর আল্লাহ মহা অনুগ্রহশীল।'),
  ('bn.bengali', 3, 75, 'কোন কোন আহলে কিতাব এমনও রয়েছে, তোমরা যদি তাদের কাছে বহু ধন-সম্পদ আমানত রাখ, তাহলেও তা তোমাদের যথারীতি পরিশোধ করবে। আর তোদের মধ্যে অনেক এমনও রয়েছে যারা একটি দীনার গচ্ছিত রাখলেও ফেরত দেবে না-যে পর্যন্ত না তুমি তার মাথার উপর দাঁড়াতে পারবে। এটা এজন্য যে, তারা বলে রেখেছে যে, উম্মীদের অধিকার বিনষ্ট করাতে আমাদের কোন পাপ নেই। আর তারা আল্লাহ সম্পর্কে জেনে শুনেই মিথ্যা বলে।'),
  ('bn.bengali', 3, 76, 'যে লোক নিজ প্রতিজ্ঞা পূর্ন করবে এং পরহেজগার হবে, অবশ্যই আল্লাহ পরহেজগারদেরকে ভালবাসেন।'),
  ('bn.bengali', 3, 77, 'যারা আল্লাহর নামে কৃত অঙ্গীকার এবং প্রতিজ্ঞা সামান্য মুল্যে বিক্রয় করে, আখেরাতে তাদের কেন অংশ নেই। আর তাদের সাথে কেয়ামতের দিন আল্লাহ কথা বলবেন না। তাদের প্রতি (করুণার) দৃষ্টিও দেবেন না। আর তাদেরকে পরিশুদ্ধও করবেন না। বস্তুতঃ তাদের জন্য রয়েছে যন্ত্রণাদায়ক আযাব।'),
  ('bn.bengali', 3, 78, 'আর তাদের মধ্যে একদল রয়েছে, যারা বিকৃত উচ্চারণে মুখ বাঁকিয়ে কিতাব পাঠ করে, যাতে তোমরা মনে কর যে, তার কিতাব থেকেই পাঠ করছে। অথচ তারা যা আবৃত্তি করছে তা আদৌ কিতাব নয়। এবং তারা বলে যে, এসব কথা আল্লাহর তরফ থেকে আগত। অথচ এসব আল্লাহর তরফ থেকে প্রেরিত নয়। তারা বলে যে, এটি আল্লাহর কথা অথচ এসব আল্লাহর কথা নয়। আর তারা জেনে শুনে আল্লাহরই প্রতি মিথ্যারোপ করে।'),
  ('bn.bengali', 3, 79, 'কোন মানুষকে আল্লাহ কিতাব, হেকমত ও নবুওয়ত দান করার পর সে বলবে যে, ‘তোমরা আল্লাহকে পরিহার করে আমার বান্দা হয়ে যাও’-এটা সম্ভব নয়। বরং তারা বলবে, ‘তোমরা আল্লাহওয়ালা হয়ে যাও, যেমন, তোমরা কিতাব শিখাতে এবং যেমন তোমরা নিজেরা ও পড়তে।'),
  ('bn.bengali', 3, 80, 'তাছাড়া তোমাদেরকে একথা বলাও সম্ভব নয় যে, তোমরা ফেরেশতা ও নবীগনকে নিজেদের পালনকর্তা সাব্যস্ত করে নাও। তোমাদের মুসলমান হবার পর তারা কি তোমাদেরকে কুফরী শেখাবে?'),
  ('bn.bengali', 3, 81, 'আর আল্লাহ যখন নবীগনের কাছ থেকে অস্বীকার গ্রহন করলেন যে, আমি যা কিছু তোমাদের দান করেছি কিতাব ও জ্ঞান এবং অতঃপর তোমাদের নিকট কোন রসূল আসেন তোমাদের কিতাবকে সত্য বলে দেয়ার জন্য, তখন সে রসূলের প্রতি ঈমান আনবে এবং তার সাহায্য করবে। তিনি বললেন, ‘তোমার কি অঙ্গীকার করছো এবং এই শর্তে আমার ওয়াদা গ্রহণ করে নিয়েছ? তারা বললো, ‘আমরা অঙ্গীকার করেছি’। তিনি বললেন, তাহলে এবার সাক্ষী থাক। আর আমিও তোমাদের সাথে সাক্ষী রইলাম।'),
  ('bn.bengali', 3, 82, 'অতঃপর যে লোক এই ওয়াদা থেকে ফিরে দাঁড়াবে, সেই হবে নাফরমান।'),
  ('bn.bengali', 3, 83, 'তারা কি আল্লাহর দ্বীনের পরিবর্তে অন্য দ্বীন তালাশ করছে? আসমান ও যমীনে যা কিছু রয়েছে স্বেচ্ছায় হোক বা অনিচ্ছায় হোক, তাঁরই অনুগত হবে এবং তাঁর দিকেই ফিরে যাবে।'),
  ('bn.bengali', 3, 84, 'বলুন, আমরা ঈমান এনেছি আল্লাহর উপর এবং যা কিছু অবতীর্ণ হয়েছে আমাদের উপর, ইব্রাহীম, ইসমাঈল, ইসহাক, ইয়াকুব এবং তাঁদের সন্তানবর্গের উপর আর যা কিছু পেয়েছেন মূসা ও ঈসা এবং অন্যান্য নবী রসূলগণ তাঁদের পালনকর্তার পক্ষ থেকে। আমরা তাঁদের কারো মধ্যে পার্থক্য করি না। আর আমরা তাঁরই অনুগত।'),
  ('bn.bengali', 3, 85, 'যে লোক ইসলাম ছাড়া অন্য কোন ধর্ম তালাশ করে, কস্মিণকালেও তা গ্রহণ করা হবে না এবং আখেরাতে সে ক্ষতি গ্রস্ত।'),
  ('bn.bengali', 3, 86, 'কেমন করে আল্লাহ এমন জাতিকে হেদায়েত দান করবেন, যারা ঈমান আনার পর এবং রসূলকে সত্য বলে সাক্ষ্য দেয়ার পর এবং তাদের নিকট প্রমাণ এসে যাওয়ার পর কাফের হয়েছে। আর আল্লাহ জালেম সম্প্রদায়কে হেদায়েত দান করেন না।'),
  ('bn.bengali', 3, 87, 'এমন লোকের শাস্তি হলো আল্লাহ, ফেরেশতাগণ এবং মানুষ সকলেরই অভিসম্পাত।'),
  ('bn.bengali', 3, 88, 'সর্বক্ষণই তারা তাতে থাকবে। তাদের আযাব হালকাও হবে না এবং তার এত অবকাশও পাবে না।'),
  ('bn.bengali', 3, 89, 'কিন্তু যারা অতঃপর তওবা করে নেবে এবং সৎকাজ করবে তারা ব্যতীত, নিশ্চয় আল্লাহ ক্ষমাশীল ও পরম দয়ালূ।'),
  ('bn.bengali', 3, 90, 'যারা ঈমান আনার পর অস্বীকার করেছে এবং অস্বীকৃতিতে বৃদ্ধি ঘটেছে, কস্মিণকালেও তাদের তওবা কবুল করা হবে না। আর তারা হলো গোমরাহ।'),
  ('bn.bengali', 3, 91, 'যদি সারা পৃথিবী পরিমাণ স্বর্ণও তার পরিবর্তে দেয়া হয়, তবুও যারা কাফের হয়েছে এবং কাফের অবস্থায় মৃত্যুবরণ করেছে তাদের তওবা কবুল করা হবে না। তাদের জন্য রয়েছে যন্ত্রণাদায়ক আযাব! পক্ষান্তরে তাদের কোনই সাহায্যকারী নেই।'),
  ('bn.bengali', 3, 92, 'কস্মিণকালেও কল্যাণ লাভ করতে পারবে না, যদি তোমাদের প্রিয় বস্তু থেকে তোমরা ব্যয় না কর। আর তোমরা যদি কিছু ব্যয় করবে আল্লাহ তা জানেন।'),
  ('bn.bengali', 3, 93, 'তওরাত নাযিল হওয়ার পূর্বে ইয়াকুব যেগুলো নিজেদের জন্য হারাম করে নিয়েছিলেন, সেগুলো ব্যতীত সমস্ত আহার্য বস্তুই বনী-ইসরায়ীলদের জন্য হালাল ছিল। তুমি বলে দাও, তোমরা যদি সত্যবাদী হয়ে থাক। তাহলে তওরাত নিয়ে এসো এবং তা পাঠ কর।'),
  ('bn.bengali', 3, 94, 'অতঃপর আল্লাহর প্রতি যারা মিথ্যা আরোপ করেছে, তারাই যালেম সীমালংঘনকারী।'),
  ('bn.bengali', 3, 95, 'বল, ‘আল্লাহ সত্য বলেছেন। এখন সবাই ইব্রাহীমের ধর্মের অনুগত হয়ে যাও, যিনি ছিলেন একনিষ্ঠ ভাবে সত্যধর্মের অনুসারী। তিনি মুশরিকদের অন্তর্ভুক্ত ছিলেন না।'),
  ('bn.bengali', 3, 96, 'নিঃসন্দেহে সর্বপ্রথম ঘর যা মানুষের জন্যে নির্ধারিত হয়েছে, সেটাই হচ্ছে এ ঘর, যা মক্কায় অবস্থিত এবং সারা জাহানের মানুষের জন্য হেদায়েত ও বরকতময়।'),
  ('bn.bengali', 3, 97, 'এতে রয়েছে মকামে ইব্রাহীমের মত প্রকৃষ্ট নিদর্শন। আর যে, লোক এর ভেতরে প্রবেশ করেছে, সে নিরাপত্তা লাভ করেছে। আর এ ঘরের হজ্ব করা হলো মানুষের উপর আল্লাহর প্রাপ্য; যে লোকের সামর্থ?2480;য়েছে এ পর্যন্ত পৌছার। আর যে লোক তা মানে না। আল্লাহ সারা বিশ্বের কোন কিছুরই পরোয়া করেন না।'),
  ('bn.bengali', 3, 98, 'বলুন, হে আহলে কিতাবগণ, কেন তোমরা আল্লাহর কিতাব অমান্য করছো, অথচ তোমরা যা কিছু কর, তা আল্লাহর সামনেই রয়েছে।'),
  ('bn.bengali', 3, 99, 'বলুন, হে আহলে কিতাবগণ! কেন তোমরা আল্লাহর পথে ঈমানদারদিগকে বাধা দান কর-তোমরা তাদের দ্বীনের মধ্যে বক্রতা অনুপ্রবেশ করানোর পন্থা অনুসন্ধান কর, অথচ তোমরা এ পথের সত্যতা প্রত্যক্ষ করছ। বস্তুতঃ আল্লাহ তোমাদের কার্যকলাপ সম্পর্কে অনবগত নন।'),
  ('bn.bengali', 3, 100, 'হে ঈমানদারগণ! তোমরা যদি আহলে কিতাবদের কোন ফেরকার কথা মান, তাহলে ঈমান আনার পর তারা তোমাদিগকে কাফেরে পরিণত করে দেবে।'),
  ('bn.bengali', 3, 101, 'আর তোমরা কেমন করে কাফের হতে পার, অথচ তোমাদের সামনে পাঠ করা হয় আল্লাহর আয়াত সমূহ এবং তোমাদের মধ্যে রয়েছেন আল্লাহর রসূল। আর যারা আল্লাহর কথা দৃঢ়ভাবে ধরবে, তারা হেদায়েত প্রাপ্ত হবে সরল পথের।'),
  ('bn.bengali', 3, 102, 'হে ঈমানদারগণ! আল্লাহকে যেমন ভয় করা উচিৎ ঠিক তেমনিভাবে ভয় করতে থাক। এবং অবশ্যই মুসলমান না হয়ে মৃত্যুবরণ করো না।'),
  ('bn.bengali', 3, 103, 'আর তোমরা সকলে আল্লাহর রজ্জুকে সুদৃঢ় হস্তে ধারণ কর; পরস্পর বিচ্ছিন্ন হয়ো না। আর তোমরা সে নেয়ামতের কথা স্মরণ কর, যা আল্লাহ তোমাদিগকে দান করেছেন। তোমরা পরস্পর শত্রু ছিলে। অতঃপর আল্লাহ তোমাদের মনে সম্প্রীতি দান করেছেন। ফলে, এখন তোমরা তাঁর অনুগ্রহের কারণে পরস্পর ভাই ভাই হয়েছ। তোমরা এক অগ্নিকুন্ডের পাড়ে অবস্থান করছিলে। অতঃপর তা থেকে তিনি তোমাদেরকে মুক্তি দিয়েছেন। এভাবেই আল্লাহ নিজের নিদর্শনসমুহ প্রকাশ করেন, যাতে তোমরা হেদায়েত প্রাপ্ত হতে পার।'),
  ('bn.bengali', 3, 104, 'আর তোমাদের মধ্যে এমন একটা দল থাকা উচিত যারা আহবান জানাবে সৎকর্মের প্রতি, নির্দেশ দেবে ভাল কাজের এবং বারণ করবে অন্যায় কাজ থেকে, আর তারাই হলো সফলকাম।'),
  ('bn.bengali', 3, 105, 'আর তাদের মত হয়ো না, যারা বিচ্ছিন্ন হয়ে গেছে এবং নিদর্শন সমূহ আসার পরও বিরোধিতা করতে শুরু করেছে-তাদের জন্যে রয়েছে ভয়ঙ্কর আযাব।'),
  ('bn.bengali', 3, 106, 'সেদিন কোন কোন মুখ উজ্জ্বল হবে, আর কোন কোন মুখ হবে কালো। বস্তুতঃ যাদের মুখ কালো হবে, তাদের বলা হবে, তোমরা কি ঈমান আনার পর কাফের হয়ে গিয়েছিলে? এবার সে কুফরীর বিনিময়ে আযাবের আস্বাদ গ্রহণ কর।'),
  ('bn.bengali', 3, 107, 'আর যাদের মুখ উজ্জ্বল হবে, তারা থাকবে রহমতের মাঝে। তাতে তারা অনন্তকাল অবস্থান করবে।'),
  ('bn.bengali', 3, 108, 'এগুলো হচ্ছে আল্লাহর নির্দেশ, যা তোমাদিগকে যথাযথ পাঠ করে শুনানো হচ্ছে। আর আল্লাহ বিশ্ব জাহানের প্রতি উৎপীড়ন করতে চান না।'),
  ('bn.bengali', 3, 109, 'আর যা কিছু আসমান ও যমীনে রয়েছে সে সবই আল্লাহর এবং আল্লাহর প্রতিই সব কিছু প্রত্যাবর্তনশীল।'),
  ('bn.bengali', 3, 110, 'তোমরাই হলে সর্বোত্তম উম্মত, মানবজাতির কল্যানের জন্যেই তোমাদের উদ্ভব ঘটানো হয়েছে। তোমরা সৎকাজের নির্দেশ দান করবে ও অন্যায় কাজে বাধা দেবে এবং আল্লাহর প্রতি ঈমান আনবে। আর আহলে-কিতাবরা যদি ঈমান আনতো, তাহলে তা তাদের জন্য মঙ্গলকর হতো। তাদের মধ্যে কিছু তো রয়েছে ঈমানদার আর অধিকাংশই হলো পাপাচারী।'),
  ('bn.bengali', 3, 111, 'যৎসামান্য কষ্ট দেয়া ছাড়া তারা তোমাদের কোনই ক্ষতি করতে পারবে না। আর যদি তারা তোমাদের সাথে লড়াই করে, তাহলে তারা পশ্চাদপসরণ করবে। অতঃপর তাদের সাহায্য করা হবে না।'),
  ('bn.bengali', 3, 112, 'আল্লাহর প্রতিশ্রুতি কিংবা মানুষের প্রতিশ্রুতি ব্যতিত ওরা যেখানেই অবস্থান করেছে সেখানেই তাদের ওপর লাঞ্ছনা চাপিয়ে দেয়া হয়েছে। আর ওরা উপার্জন করেছে আল্লাহর গযব। ওদের উপর চাপানো হয়েছে গলগ্রহতা। তা এজন্যে যে, ওরা আল্লাহর আয়াতসমূহকে অনবরত অস্বীকার করেছে এবং নবীগনকে অন্যায়ভাবে হত্যা করেছে। তার কারণ, ওরা নাফরমানী করেছে এবং সীমা লংঘন করেছে।'),
  ('bn.bengali', 3, 113, 'তারা সবাই সমান নয়। আহলে কিতাবদের মধ্যে কিছু লোক এমনও আছে যারা অবিচলভাবে আল্লাহর আয়াতসমূহ পাঠ করে এবং রাতের গভীরে তারা সেজদা করে।'),
  ('bn.bengali', 3, 114, 'তারা আল্লাহর প্রতি ও কিয়ামত দিবসের প্রতি ঈমান রাখে এবং কল্যাণকর বিষয়ের নির্দেশ দেয়; অকল্যাণ থেকে বারণ করে এবং সৎকাজের জন্য সাধ্যমত চেষ্টা করতে থাকে। আর এরাই হল সৎকর্মশীল।'),
  ('bn.bengali', 3, 115, 'তারা যেসব সৎকাজ করবে, কোন অবস্থাতেই সেগুলোর প্রতি অবজ্ঞা প্রদর্শন করা হবে না। আর আল্লাহ পরহেযগারদের বিষয়ে অবগত।'),
  ('bn.bengali', 3, 116, 'নিশ্চয় যারা কাফের হয়, তাদের ধন সম্পদ ও সন্তান-সন্ততি আল্লাহর সামনে কখনও কোন কাজে আসবে না। আর তারাই হলো দোযখের আগুনের অধিবাসী। তারা সে আগুনে চিরকাল থাকবে।'),
  ('bn.bengali', 3, 117, 'এ দুনিয়ার জীবনে যা কিছু ব্যয় করা হয়, তার তুলনা হলো ঝড়ো হাওয়ার মতো, যাতে রয়েছে তুষারের শৈত্য, যা সে জাতির শস্যক্ষেত্রে গিয়ে লেগেছে যারা নিজের জন্য মন্দ করেছে। অতঃপর সেগুলোকে নিঃশেষ করে দিয়েছে। বস্তুতঃ আল্লাহ তাদের উপর কোন অন্যায় করেননি, কিন্তু তারা নিজেরাই নিজেদের উপর অত্যাচার করছিল।'),
  ('bn.bengali', 3, 118, 'হে ঈমানদারগণ! তোমরা মুমিন ব্যতীত অন্য কাউকে অন্তরঙ্গরূপে গ্রহণ করো না, তারা তোমাদের অমঙ্গল সাধনে কোন ক্রটি করে না-তোমরা কষ্টে থাক, তাতেই তাদের আনন্দ। শত্রুতাপ্রসুত বিদ্বেষ তাদের মুখেই ফুটে বেরোয়। আর যা কিছু তাদের মনে লুকিয়ে রয়েছে, তা আরো অনেকগুণ বেশী জঘন্য। তোমাদের জন্যে নিদর্শন বিশদভাবে বর্ণনা করে দেয়া হলো, যদি তোমরা তা অনুধাবন করতে সমর্থ হও।'),
  ('bn.bengali', 3, 119, 'দেখ! তোমরাই তাদের ভালবাস, কিন্তু তারা তোমাদের প্রতি মোটেও সদভাব পোষণ করে না। আর তোমরা সমস্ত কিতাবেই বিশ্বাস কর। অথচ তারা যখন তোমাদের সাথে এসে মিশে, বলে, আমরা ঈমান এনেছি। পক্ষান্তরে তারা যখন পৃথক হয়ে যায়, তখন তোমাদের উপর রোষবশতঃ আঙ্গুল কামড়াতে থাকে। বলুন, তোমরা আক্রোশে মরতে থাক। আর আল্লাহ মনের কথা ভালই জানেন।'),
  ('bn.bengali', 3, 120, 'তোমাদের যদি কোন মঙ্গল হয়; তাহলে তাদের খারাপ লাগে। আর তোমাদের যদি অমঙ্গল হয় তাহলে আনন্দিত হয় আর তাতে যদি তোমরা ধৈর্য্যধারণ কর এবং তাকওয়া অবলম্বন কর, তবে তাদের প্রতারণায় তোমাদের কোনই ক্ষতি হবে না। নিশ্চয়ই তারা যা কিছু করে সে সমস্তই আল্লাহর আয়ত্তে রয়েছে।'),
  ('bn.bengali', 3, 121, 'আর আপনি যখন পরিজনদের কাছ থেকে সকাল বেলা বেরিয়ে গিয়ে মুমিনগণকে যুদ্ধের অবস্থানে বিন্যস্ত করলেন, আর আল্লাহ সব বিষয়েই শোনেন এবং জানেন।'),
  ('bn.bengali', 3, 122, 'যখন তোমাদের দুটি দল সাহস হারাবার উপক্রম হলো, অথচ আল্লাহ তাদের সাহায্যকারী ছিলেন, আর আল্লাহর উপরই ভরসা করা মুমিনদের উচিত।'),
  ('bn.bengali', 3, 123, 'বস্তুতঃ আল্লাহ বদরের যুদ্ধে তোমাদের সাহায্য করেছেন, অথচ তোমরা ছিলে দুর্বল। কাজেই আল্লাহকে ভয় করতে থাক, যাতে তোমরা কৃতজ্ঞ হতে পারো।'),
  ('bn.bengali', 3, 124, 'আপনি যখন বলতে লাগলেন মুমিনগণকে-তোমাদের জন্য কি যথেষ্ট নয় যে, তোমাদের সাহায্যার্থে তোমাদের পালনকর্তা আসমান থেকে অবতীর্ণ তিন হাজার ফেরেশতা পাঠাবেন।'),
  ('bn.bengali', 3, 125, 'অবশ্য তোমরা যদি সবর কর এবং বিরত থাক আর তারা যদি তখনই তোমাদের উপর চড়াও হয়, তাহলে তোমাদের পালনকর্তা চিহিߦ#2468; ঘোড়ার উপর পাঁচ হাজার ফেরেশতা তোমাদের সাহায্যে পাঠাতে পারেন।'),
  ('bn.bengali', 3, 126, 'বস্তুতঃ এটা তো আল্লাহ তোমাদের সুসংবাদ দান করলেন, যাতে তোমাদের মনে এতে সান্ত্বনা আসতে পারে। আর সাহায্য শুধুমাত্র পরাক্রান্ত, মহাজ্ঞানী আল্লাহরই পক্ষ থেকে,'),
  ('bn.bengali', 3, 127, 'যাতে ধবংস করে দেন কোন কোন কাফেরকে অথবা লাঞ্ছিত করে দেন-যেন ওরা বঞ্চিত হয়ে ফিরে যায়।'),
  ('bn.bengali', 3, 128, 'হয় আল্লাহ তাদের ক্ষমা করবেন কিংবা তাদেরকে আযাব দেবেন। এ ব্যাপারে আপনার কোন করণীয় নাই। কারণ তারা রয়েছে অন্যায়ের উপর।'),
  ('bn.bengali', 3, 129, 'আর যা কিছু আসমান ও যমীনে রয়েছে, সেসবই আল্লাহর। তিনি যাকে ইচ্ছা ক্ষমা করবেন, যাকে ইচ্ছা আযাব দান করবেন। আর আল্লাহ হচ্ছেন ক্ষমাকারী, করুণাময়।'),
  ('bn.bengali', 3, 130, 'হে ঈমানদারগণ! তোমরা চক্রবৃদ্ধি হারে সুদ খেয়ো না। আর আল্লাহকে ভয় করতে থাক, যাতে তোমরা কল্যাণ অর্জন করতে পারো।'),
  ('bn.bengali', 3, 131, 'এবং তোমরা সে আগুন থেকে বেঁচে থাক, যা কাফেরদের জন্য প্রস্তুত করা হয়েছে।'),
  ('bn.bengali', 3, 132, 'আর তোমরা আনুগত্য কর আল্লাহ ও রসূলের, যাতে তোমাদের উপর রহমত করা হয়।'),
  ('bn.bengali', 3, 133, 'তোমরা তোমাদের পালনকর্তার ক্ষমা এবং জান্নাতের দিকে ছুটে যাও যার সীমানা হচ্ছে আসমান ও যমীন, যা তৈরী করা হয়েছে পরহেযগারদের জন্য।'),
  ('bn.bengali', 3, 134, 'যারা স্বচ্ছলতায় ও অভাবের সময় ব্যয় করে, যারা নিজেদের রাগকে সংবরণ করে আর মানুষের প্রতি ক্ষমা প্রদর্শন করে, বস্তুতঃ আল্লাহ সৎকর্মশীলদিগকেই ভালবাসেন।'),
  ('bn.bengali', 3, 135, 'তারা কখনও কোন অশ্লীল কাজ করে ফেললে কিংবা কোন মন্দ কাজে জড়িত হয়ে নিজের উপর জুলুম করে ফেললে আল্লাহকে স্মরণ করে এবং নিজের পাপের জন্য ক্ষমা প্রার্থনা করে। আল্লাহ ছাড়া আর কে পাপ ক্ষমা করবেন? তারা নিজের কৃতকর্মের জন্য হঠকারিতা প্রদর্শন করে না এবং জেনে-শুনে তাই করতে থাকে না।'),
  ('bn.bengali', 3, 136, 'তাদেরই জন্য প্রতিদান হলো তাদের পালনকর্তার ক্ষমা ও জান্নাত, যার তলদেশে প্রবাহিত হচ্ছে প্রস্রবণ যেখানে তারা থাকবে অনন্তকাল। যারা কাজ করে তাদের জন্য কতইনা চমৎকার প্রতিদান।'),
  ('bn.bengali', 3, 137, 'তোমাদের আগে অতীত হয়েছে অনেক ধরনের জীবনাচরণ। তোমরা পৃথিবীতে ভ্রমণ কর এবং দেখ যারা মিথ্যা প্রতিপন্ন করেছে তাদের পরিণতি কি হয়েছে।'),
  ('bn.bengali', 3, 138, 'এই হলো মানুষের জন্য বর্ণনা। আর যারা ভয় করে তাদের জন্য উপদেশবাণী।'),
  ('bn.bengali', 3, 139, 'আর তোমরা নিরাশ হয়ো না এবং দুঃখ করো না। যদি তোমরা মুমিন হও তবে, তোমরাই জয়ী হবে।'),
  ('bn.bengali', 3, 140, 'তোমরা যদি আহত হয়ে থাক, তবে তারাও তো তেমনি আহত হয়েছে। আর এ দিনগুলোকে আমি মানুষের মধ্যে পালাক্রমে আবর্তন ঘটিয়ে থাকি। এভাবে আল্লাহ জানতে চান কারা ঈমানদার আর তিনি তোমাদের কিছু লোককে শহীদ হিসাবে গ্রহণ করতে চান। আর আল্লাহ অত্যাচারীদেরকে ভালবাসেন না।'),
  ('bn.bengali', 3, 141, 'আর এ কারণে আল্লাহ ঈমানদারদেরকে পাক-সাফ করতে চান এবং কাফেরদেরকে ধবংস করে দিতে চান।'),
  ('bn.bengali', 3, 142, 'তোমাদের কি ধারণা, তোমরা জান্নাতে প্রবেশ করবে? অথচ আল্লাহ এখনও দেখেননি তোমাদের মধ্যে কারা জেহাদ করেছে এবং কারা ধৈর্য্যশীল।'),
  ('bn.bengali', 3, 143, 'আর তোমরা তো মৃত্যু আসার আগেই মরণ কামনা করতে, কাজেই এখন তো তোমরা তা চোখের সামনে উপস্থিত দেখতে পাচ্ছ।'),
  ('bn.bengali', 3, 144, 'আর মুহাম্মদ একজন রসূল বৈ তো নয়! তাঁর পূর্বেও বহু রসূল অতিবাহিত হয়ে গেছেন। তাহলে কি তিনি যদি মৃত্যুবরণ করেন অথবা নিহত হন, তবে তোমরা পশ্চাদপসরণ করবে? বস্তুতঃ কেউ যদি পশ্চাদপসরণ করে, তবে তাতে আল্লাহর কিছুই ক্ষতি-বৃদ্ধি হবে না। আর যারা কৃতজ্ঞ, আল্লাহ তাদের সওয়াব দান করবেন।'),
  ('bn.bengali', 3, 145, 'আর আল্লাহর হুকুম ছাড়া কেউ মরতে পারে না-সেজন্য একটা সময় নির্ধারিত রয়েছে। বস্তুতঃ যে লোক দুনিয়ায় বিনিময় কামনা করবে, আমি তাকে তা দুনিয়াতেই দান করব। পক্ষান্তরে-যে লোক আখেরাতে বিনিময় কামনা করবে, তা থেকে আমি তাকে তাই দেবো। আর যারা কৃতজ্ঞ তাদেরকে আমি প্রতিদান দেবো'),
  ('bn.bengali', 3, 146, 'আর বহু নবী ছিলেন, যাঁদের সঙ্গী-সাথীরা তাঁদের অনুবর্তী হয়ে জেহাদ করেছে; আল্লাহর পথে-তাদের কিছু কষ্ট হয়েছে বটে, কিন্তু আল্লাহর রাহে তারা হেরেও যায়নি, ক্লান্তও হয়নি এবং দমেও যায়নি। আর যারা সবর করে, আল্লাহ তাদেরকে ভালবাসেন।'),
  ('bn.bengali', 3, 147, 'তারা আর কিছুই বলেনি-শুধু বলেছে, হে আমাদের পালনকর্তা! মোচন করে দাও আমাদের পাপ এবং যা কিছু বাড়াবাড়ি হয়ে গেছে আমাদের কাজে। আর আমাদিগকে দৃঢ় রাখ এবং কাফেরদের উপর আমাদিগকে সাহায্য কর।'),
  ('bn.bengali', 3, 148, 'অতঃপর আল্লাহ তাদেরকে দুনিয়ার সওয়াব দান করেছেন এবং যথার্থ আখেরাতের সওয়াব। আর যারা সৎকর্মশীল আল্লাহ তাদেরকে ভালবাসেন।'),
  ('bn.bengali', 3, 149, 'হে ঈমানদারগণ! তোমরা যদি কাফেরদের কথা শোন, তাহলে ওরা তোমাদেরকে পেছনে ফিরিয়ে দেবে, তাতে তোমরা ক্ষতির সম্মুখীণ হয়ে পড়বে।'),
  ('bn.bengali', 3, 150, 'বরং আল্লাহ তোমাদের সাহায্যকারী, আর তাঁর সাহায্যই হচ্ছে উত্তম সাহায্য।'),
  ('bn.bengali', 3, 151, 'খুব শীঘ্রই আমি কাফেরদের মনে ভীতির সঞ্চার করবো। কারণ, ওরা আল্লাহর সাথে অংশীদার সাব্যস্ত করে যে সম্পর্কে কোন সনদ অবতীর্ণ করা হয়নি। আর ওদের ঠিকানা হলো দোযখের আগুন। বস্তুতঃ জালেমদের ঠিকানা অত্যন্ত নিকৃষ্ট।'),
  ('bn.bengali', 3, 152, 'আর আল্লাহ সে ওয়াদাকে সত্যে পরিণত করেছেন, যখন তোমরা তাঁরই নির্দেশে ওদের খতম করছিলে। এমনকি যখন তোমরা ছত্রভঙ্গ হয়ে পড়েছে ও কর্তব্য স্থির করার ব্যাপারে বিবাদে লিপ্ত হয়েছে। আর যা তোমরা চাইতে তা দেখার পর কৃতঘ্নতা প্রদর্শন করেছ, তাতে তোমাদের কারো কাম্য ছিল দুনিয়া আর কারো বা কাম্য ছিল আখেরাত। অতঃপর তোমাদিগকে সরিয়ে দিলেন ওদের উপর থেকে যাতে তোমাদিগকে পরীক্ষা করেন। বস্তুতঃ তিনি তোমাদিগকে ক্ষমা করেছেন। আর আল্লাহর মুমিনদের প্রতি অনুগ্রহশীল।'),
  ('bn.bengali', 3, 153, 'আর তোমরা উপরে উঠে যাচ্ছিলে এবং পেছন দিকে ফিরে তাকাচ্ছিলে না কারো প্রতি, অথচ রসূল ডাকছিলেন তোমাদিগকে তোমাদের পেছন দিক থেকে। অতঃপর তোমাদের উপর এলো শোকের ওপরে শোক, যাতে তোমরা হাত থেকে বেরিয়ে যাওয়া বস্তুর জন্য দুঃখ না কর এবং যার সম্মুখীণ হচ্ছ সেজন্য বিমর্ষ না হও। আর আল্লাহ তোমাদের কাজের ব্যাপারে অবহিত রয়েছেন।'),
  ('bn.bengali', 3, 154, 'অতঃপর তোমাদের উপর শোকের পর শান্তি অবতীর্ণ করলেন, যা ছিল তন্দ্রার মত। সে তন্দ্রায় তোমাদের মধ্যে কেউ কেউ ঝিমোচ্ছিল আর কেউ কেউ প্রাণের ভয়ে ভাবছিল। আল্লাহ সম্পর্কে তাদের মিথ্যা ধারণা হচ্ছিল মুর্খদের মত। তারা বলছিল আমাদের হাতে কি কিছুই করার নেই? তুমি বল, সবকিছুই আল্লাহর হাতে। তারা যা কিছু মনে লুকিয়ে রাখে-তোমার নিকট প্রকাশ করে না সে সবও। তারা বলে আমাদের হাতে যদি কিছু করার থাকতো, তাহলে আমরা এখানে নিহত হতাম না। তুমি বল, তোমরা যদি নিজেদের ঘরেও থাকতে তবুও তারা অবশ্যই বেরিয়ে আসত নিজেদের অবস্থান থেকে যাদের মৃত্যু লিখে দেয়া হয়েছে। তোমাদের বুকে যা রয়েছে তার পরীক্ষা করা ছিল আল্লাহর ইচ্ছা, আর তোমাদের অন্তরে যা কিছু রয়েছে তা পরিষ্কার করা ছিল তাঁর কাম্য। আল্লাহ মনের গোপন বিষয় জানেন।'),
  ('bn.bengali', 3, 155, 'তোমাদের যে দুটি দল লড়াইয়ের দিনে ঘুরে দাঁড়িয়েছিল শয়তান তাদেরকে বিভ্রান্ত করেছিল, তাদেরই পাপের দরুন।'),
  ('bn.bengali', 3, 156, 'হে ঈমাণদারগণ! তোমরা তাদের মত হয়ো না, যারা কাফের হয়েছে এবং নিজেদের ভাই বন্ধুরা যখন কোন অভিযানে বের হয় কিংবা জেহাদে যায়, তখন তাদের সম্পর্কে বলে, তারা যদি আমাদের সাথে থাকতো, তাহলে মরতোও না আহতও হতো না। যাতে তারা এ ধারণা সৃষ্টির মাধ্যমে সংশ্লিষ্টদের মনে অনুতাপ সৃষ্টি করতে পারে। অথচ আল্লাহই জীবন দান করেন এবং মৃত্যু দেন। তোমাদের সমস্ত কাজই, তোমরা যা কিছুই কর না কেন, আল্লাহ সবকিছুৃই দেখেন।'),
  ('bn.bengali', 3, 157, 'আর তোমরা যদি আল্লাহর পথে নিহত হও কিংবা মৃত্যুবরণ কর, তোমরা যা কিছু সংগ্রহ করে থাক আল্লাহ তা’আলার ক্ষমা ও করুণা সে সবকিছুর চেয়ে উত্তম।'),
  ('bn.bengali', 3, 158, 'আর তোমরা মৃত্যুই বরণ কর অথবা নিহতই হও, অবশ্য আল্লাহ তা’আলার সামনেই সমবেত হবে।'),
  ('bn.bengali', 3, 159, 'আল্লাহর রহমতেই আপনি তাদের জন্য কোমল হৃদয় হয়েছেন পক্ষান্তরে আপনি যদি রাগ ও কঠিন হৃদয় হতেন তাহলে তারা আপনার কাছ থেকে বিচ্ছিন্ন হয়ে যেতো। কাজেই আপনি তাদের ক্ষমা করে দিন এবং তাদের জন্য মাগফেরাত কামনা করুন এবং কাজে কর্মে তাদের পরামর্শ করুন। অতঃপর যখন কোন কাজের সিদ্ধান্ত গ্রহণ করে ফেলেন, তখন আল্লাহ তা’আলার উপর ভরসা করুন আল্লাহ তাওয়াক্কুল কারীদের ভালবাসেন।'),
  ('bn.bengali', 3, 160, 'যদি আল্লাহ তোমাদের সহায়তা করেন, তাহলে কেউ তোমাদের উপর পরাক্রান্ত হতে পারবে না। আর যদি তিনি তোমাদের সাহায্য না করেন, তবে এমন কে আছে, যে তোমাদের সাহায্য করতে পারে? আর আল্লাহর ওপরই মুসলমানগনের ভরসা করা উচিত।'),
  ('bn.bengali', 3, 161, 'আর কোন বিষয় গোপন করে রাখা নবীর কাজ নয়। আর যে লোক গোপন করবে সে কিয়ামতের দিন সেই গোপন বস্তু নিয়ে আসবে। অতঃপর পরিপূর্ণভাবে পাবে প্রত্যেকে, যা সে অর্জন করেছে। আর তাদের প্রতি কোন অন্যায় করা হবে না।'),
  ('bn.bengali', 3, 162, 'যে লোক আল্লাহর ইচ্ছার অনুগত, সে কি ঐ লোকের সমান হতে পারে, যে আল্লাহর রোষ অর্জন করেছে? বস্তুতঃ তার ঠিকানা হল দোযখ। আর তা কতইনা নিকৃষ্ট অবস্থান!'),
  ('bn.bengali', 3, 163, 'আল্লাহর নিকট মানুষের মর্যাদা বিভিন্ন স্তরের আর আল্লাহ দেখেন যা কিছু তারা করে।'),
  ('bn.bengali', 3, 164, 'আল্লাহ ঈমানদারদের উপর অনুগ্রহ করেছেন যে, তাদের মাঝে তাদের নিজেদের মধ্য থেকে নবী পাঠিয়েছেন। তিনি তাদের জন্য তাঁর আয়াতসমূহ পাঠ করেন। তাদেরকে পরিশোধন করেন এবং তাদেরকে কিতাব ও কাজের কথা শিক্ষা দেন। বস্তুতঃ তারা ছিল পূর্ব থেকেই পথভ্রষ্ট।'),
  ('bn.bengali', 3, 165, 'যখন তোমাদের উপর একটি মুসীবত এসে পৌছাল, অথচ তোমরা তার পূর্বেই দ্বিগুণ কষ্টে পৌছে গিয়েছ, তখন কি তোমরা বলবে, এটা কোথা থেকে এল? তাহলে বলে দাও, এ কষ্ট তোমাদের উপর পৌছেছে তোমারই পক্ষ থেকে। নিশ্চয়ই আল্লাহ প্রত্যেক বিষয়ের উপর ক্ষমতাশীল।'),
  ('bn.bengali', 3, 166, 'আর যেদিন দু’দল সৈন্যের মোকাবিলা হয়েছে; সেদিন তোমাদের উপর যা আপতিত হয়েছে তা আল্লাহর হুকুমেই হয়েছে এবং তা এজন্য যে, তাতে ঈমানদারদিগকে জানা যায়।'),
  ('bn.bengali', 3, 167, 'এবং তাদেরকে যাতে সনাক্ত করা যায় যারা মুনাফিক ছিল। আর তাদেরকে বলা হল এসো, আল্লাহর রাহে লড়াই কর কিংবা শত্রুদিগকে প্রতিহত কর। তারা বলেছিল, আমরা যদি জানতাম যে, লড়াই হবে, তাহলে অবশ্যই তোমাদের সাথে থাকতাম। সে দিন তারা ঈমানের তুলনায় কুফরীর কাছাকাছি ছিল। যা তাদের অন্তরে নেই তারা নিজের মুখে সে কথাই বলে বস্তুতঃআল্লাহ ভালভাবে জানেন তারা যা কিছু গোপন করে থাকে।'),
  ('bn.bengali', 3, 168, 'ওরা হলো যে সব লোক, যারা বসে থেকে নিজেদের ভাইদের সম্বদ্ধে বলে, যদি তারা আমাদের কথা শুনত, তবে নিহত হত না। তাদেরকে বলে দিন, এবার তোমাদের নিজেদের উপর থেকে মৃত্যুকে সরিয়ে দাও, যদি তোমরা সত্যবাদী হয়ে থাক।'),
  ('bn.bengali', 3, 169, 'আর যারা আল্লাহর রাহে নিহত হয়, তাদেরকে তুমি কখনো মৃত মনে করো না। বরং তারা নিজেদের পালনকর্তার নিকট জীবিত ও জীবিকাপ্রাপ্ত।'),
  ('bn.bengali', 3, 170, 'আল্লাহ নিজের অনুগ্রহ থেকে যা দান করেছেন তার প্রেক্ষিতে তারা আনন্দ উদযাপন করছে। আর যারা এখনও তাদের কাছে এসে পৌঁছেনি তাদের পেছনে তাদের জন্যে আনন্দ প্রকাশ করে। কারণ, তাদের কোন ভয় ভীতিও নেই এবং কোন চিন্তা ভাবনাও নেই।'),
  ('bn.bengali', 3, 171, 'আল্লাহর নেয়ামত ও অনুগ্রহের জন্যে তারা আনন্দ প্রকাশ করে এবং তা এভাবে যে, আল্লাহ, ঈমানদারদের শ্রমফল বিনষ্ট করেন না।'),
  ('bn.bengali', 3, 172, 'যারা আহত হয়ে পড়ার পরেও আল্লাহ এবং তাঁর রসূলের নির্দেশ মান্য করেছে, তাদের মধ্যে যারা সৎ ও পরহেযগার, তাদের জন্য রয়েছে মহান সওয়াব।'),
  ('bn.bengali', 3, 173, 'যাদেরকে লোকেরা বলেছে যে, তোমাদের সাথে মোকাবেলা করার জন্য লোকেরা সমাবেশ করেছে বহু সাজ-সরঞ্জাম; তাদের ভয় কর। তখন তাদের বিশ্বাস আরও দৃঢ়তর হয়ে যায় এবং তারা বলে, আমাদের জন্য আল্লাহই যথেষ্ট; কতই না চমৎকার কামিয়াবীদানকারী।'),
  ('bn.bengali', 3, 174, 'অতঃপর ফিরে এল মুসলমানরা আল্লাহর অনুগ্রহ নিয়ে, তদের কিছুই অনিষ্ট হলো না। তারপর তারা আল্লাহর ইচ্ছার অনুগত হল। বস্তুতঃ আল্লাহর অনুগ্রহ অতি বিরাট।'),
  ('bn.bengali', 3, 175, 'এরা যে রয়েছে, এরাই হলে শয়তান, এরা নিজেদের বন্ধুদের ব্যাপারে ভীতি প্রদর্শন করে। সুতরাং তোমরা তাদের ভয় করো না। আর তোমরা যদি ঈমানদার হয়ে থাক, তবে আমাকে ভয় কর।'),
  ('bn.bengali', 3, 176, 'আর যারা কুফরের দিকে ধাবিত হচ্ছে তারা যেন তোমাদিগকে চিন্তাম্বিত করে না তোলে। তারা আল্লাহ তা’আলার কোন কিছুই অনিষ্ট সাধন করতে পারবে না। আখেরাতে তাদেরকে কোন কল্যাণ দান না করাই আল্লাহর ইচ্ছা। বস্তুতঃ তাদের জন্যে রয়েছে মহা শাস্তি।'),
  ('bn.bengali', 3, 177, 'যারা ঈমানের পরিবর্তে কুফর ক্রয় করে নিয়েছে, তারা আল্লাহ তা’আলার কিছুই ক্ষতিসাধন করতে পারবে না। আর তাদের জন্য রয়েছে বেদনাদায়ক শাস্তি।'),
  ('bn.bengali', 3, 178, 'কাফেররা যেন মনে না করে যে আমি যে, অবকাশ দান করি, তা তাদের পক্ষে কল্যাণকর। আমি তো তাদেরকে অবকাশ দেই যাতে করে তারা পাপে উন্নতি লাভ করতে পারে। বস্তুতঃ তাদের জন্য রয়েছে লাঞ্ছনাজনক শাস্তি।'),
  ('bn.bengali', 3, 179, 'নাপাককে পাক থেকে পৃথক করে দেয়া পর্যন্ত আল্লাহ এমন নন যে, ঈমানদারগণকে সে অবস্থাতেই রাখবেন যাতে তোমরা রয়েছ, আর আল্লাহ এমন নন যে, তোমাদিগকে গায়বের সংবাদ দেবেন। কিন্তু আল্লাহ স্বীয় রসূল গণের মধ্যে যাকে ইচ্ছা বাছাই করে নিয়েছেন। সুতরাং আল্লাহর ওপর এবং তাঁর রসূলগণের ওপর তোমরা প্রত্যয় স্থাপন কর। বস্তুতঃ তোমরা যদি বিশ্বাস ও পরহেযগারীর ওপর প্রতিষ্ঠিত থেকে থাক, তবে তোমাদের জন্যে রয়েছে বিরাট প্রতিদান।'),
  ('bn.bengali', 3, 180, 'আল্লাহ তাদেরকে নিজের অনুগ্রহে যা দান করেছেন তাতে যারা কৃপণতা করে এই কার্পন্য তাদের জন্য মঙ্গলকর হবে বলে তারা যেন ধারণা না করে। বরং এটা তাদের পক্ষে একান্তই ক্ষতিকর প্রতিপন্ন হবে। যাতে তারা কার্পন্য করে সে সমস্ত ধন-সম্পদকে কিয়ামতের দিন তাদের গলায় বেড়ী বানিয়ে পরানো হবে। আর আল্লাহ হচ্ছেন আসমান ও যমীনের পরম সত্ত্বাধিকারী। আর যা কিছু তোমরা কর; আল্লাহ সে সম্পর্কে জানেন।'),
  ('bn.bengali', 3, 181, 'নিঃসন্দেহে আল্লাহ তাদের কথা শুনেছেন, যারা বলেছে যে, আল্লাহ হচ্ছেন অভাবগ্রস্ত আর আমরা বিত্তবান! এখন আমি তাদের কথা এবং যেসব নবীকে তারা অন্যায়ভাবে হত্যা করেছে তা লিখে রাখব, অতঃপর বলব, আস্বাদন কর জ্বলন্ত আগুনের আযাব।'),
  ('bn.bengali', 3, 182, 'এ হল তারই প্রতিফল যা তোমরা ইতিপূর্বে নিজের হাতে পাঠিয়েছ। বস্তুতঃ আল্লাহ বান্দাদের প্রতি অত্যাচার করেন না।'),
  ('bn.bengali', 3, 183, 'সে সমস্ত লোক, যারা বলে যে, আল্লাহ আমাদিগকে এমন কোন রসূলের ওপর বিশ্বাস না করতে বলে রেখেছেন যতক্ষণ না তারা আমাদের নিকট এমন কোরবানী নিয়ে আসবেন যাকে আগুন গ্রাস করে নেবে। তুমি তাদের বলে দাও, তোমাদের মাঝে আমার পূর্বে বহু রসূল নিদর্শনসমূহ এবং তোমরা যা আব্দার করেছ তা নিয়ে এসেছিলেন, তখন তোমরা কেন তাদেরকে হত্যা করলে যদি তোমরা সত্য হয়ে থাক।'),
  ('bn.bengali', 3, 184, 'তাছাড়া এরা যদি তোমাকে মিথ্যা প্রতিপন্ন করে, তবে তোমার পূর্বেও এরা এমন বহু নবীকে মিথ্যা প্রতিপন্ন করেছে, যারা নিদর্শন সমূহ নিয়ে এসেছিলেন। এবং এনেছিলেন সহীফা ও প্রদীপ্ত গ্রন্থ।'),
  ('bn.bengali', 3, 185, 'প্রত্যেক প্রাণীকে আস্বাদন করতে হবে মৃত্যু। আর তোমরা কিয়ামতের দিন পরিপূর্ণ বদলা প্রাপ্ত হবে। তারপর যাকে দোযখ থেকে দূরে রাখা হবে এবং জান্নাতে প্রবেশ করানো হবে, তার কার্যসিদ্ধি ঘটবে। আর পার্থিব জীবন ধোঁকা ছাড়া অন্য কোন সম্পদ নয়।'),
  ('bn.bengali', 3, 186, 'অবশ্য ধন-সম্পদে এবং জনসম্পদে তোমাদের পরীক্ষা হবে এবং অবশ্য তোমরা শুনবে পূর্ববর্তী আহলে কিতাবদের কাছে এবং মুশরেকদের কাছে বহু অশোভন উক্তি। আর যদি তোমরা ধৈর্য্য ধারণ কর এবং পরহেযগারী অবলম্বন কর, তবে তা হবে একান্ত সৎসাহসের ব্যাপার।'),
  ('bn.bengali', 3, 187, 'আর আল্লাহ যখন আহলে কিতাবদের কাছ থেকে প্রতিজ্ঞা গ্রহণ করলেন যে, তা মানুষের নিকট বর্ণনা করবে এবং গোপন করবে না, তখন তারা সে প্রতিজ্ঞাকে নিজেদের পেছনে ফেলে রাখল আর তার কেনা-বেচা করল সামান্য মূল্যের বিনিময়ে। সুতরাং কতই না মন্দ তাদের এ বেচা-কেনা।'),
  ('bn.bengali', 3, 188, 'তুমি মনে করো না, যারা নিজেদের কৃতকর্মের উপর আনন্দিত হয় এবং না করা বিষয়ের জন্য প্রশংসা কামনা করে, তারা আমার নিকট থেকে অব্যাহতি লাভ করেছে। বস্তুতঃ তাদের জন্যে রয়েছে বেদনাদায়ক আযাব।'),
  ('bn.bengali', 3, 189, 'আর আল্লাহর জন্যই হল আসমান ও যমিনের বাদশাহী। আল্লাহই সর্ব বিষয়ে ক্ষমতার অধিকারী।'),
  ('bn.bengali', 3, 190, 'নিশ্চয় আসমান ও যমীন সৃষ্টিতে এবং রাত্রি ও দিনের আবর্তনে নিদর্শন রয়েছে বোধ সম্পন্ন লোকদের জন্যে।'),
  ('bn.bengali', 3, 191, 'যাঁরা দাঁড়িয়ে, বসে, ও শায়িত অবস্থায় আল্লাহকে স্মরণ করে এবং চিন্তা গবেষণা করে আসমান ও জমিন সৃষ্টির বিষযে, (তারা বলে) পরওয়ারদেগার! এসব তুমি অনর্থক সৃষ্টি করনি। সকল পবিত্রতা তোমারই, আমাদিগকে তুমি দোযখের শাস্তি থেকে বাঁচাও।'),
  ('bn.bengali', 3, 192, 'হে আমাদের পালনকর্তা! নিশ্চয় তুমি যাকে দোযখে নিক্ষেপ করলে তাকে সবসময়ে অপমানিত করলে; আর জালেমদের জন্যে তো সাহায্যকারী নেই।'),
  ('bn.bengali', 3, 193, 'হে আমাদের পালনকর্তা! আমরা নিশ্চিতরূপে শুনেছি একজন আহবানকারীকে ঈমানের প্রতি আহবান করতে যে, তোমাদের পালনকর্তার প্রতি ঈমান আন; তাই আমরা ঈমান এনেছি। হে আমাদের পালনকর্তা! অতঃপর আমাদের সকল গোনাহ মাফ কর এবং আমাদের সকল দোষত্রুটি দুর করে দাও, আর আমাদের মৃত্যু দাও নেক লোকদের সাথে।'),
  ('bn.bengali', 3, 194, 'হে আমাদের পালনকর্তা! আমাদেরকে দাও, যা তুমি ওয়াদা করেছ তোমার রসূলগণের মাধ্যমে এবং কিয়ামতের দিন আমাদিগকে তুমি অপমানিত করো না। নিশ্চয় তুমি ওয়াদা খেলাফ করো না।'),
  ('bn.bengali', 3, 195, 'অতঃপর তাদের পালনকর্তা তাদের দোয়া (এই বলে) কবুল করে নিলেন যে, আমি তোমাদের কোন পরিশ্রমকারীর পরিশ্রমই বিনষ্ট করি না, তা সে পুরুষ হোক কিংবা স্ত্রীলোক। তোমরা পরস্পর এক। তারপর সে সমস্ত লোক যারা হিজরত করেছে, তাদেরকে নিজেদের দেশ থেকে বের করে দেওয়া হয়েছে এবং তাদের প্রতি উৎপীড়ন করা হয়েছে আমার পথে এবং যারা লড়াই করেছে ও মৃত্যুবরণ করেছে, অবশ্যই আমি তাদের উপর থেকে অকল্যাণকে অপসারিত করব। এবং তাদেরকে প্রবিষ্ট করব জান্নাতে যার তলদেশে নহর সমূহ প্রবাহিত। এই হলো বিনিময় আল্লাহর পক্ষ থেকে। আর আল্লাহর নিকট রয়েছে উত্তম বিনিময়।'),
  ('bn.bengali', 3, 196, 'নগরীতে কাফেরদের চাল-চলন যেন তোমাদিগকে ধোঁকা না দেয়।'),
  ('bn.bengali', 3, 197, 'এটা হলো সামান্য ফায়দা-এরপর তাদের ঠিকানা হবে দোযখ। আর সেটি হলো অতি নিকৃষ্ট অবস্থান।'),
  ('bn.bengali', 3, 198, 'কিন্তু যারা ভয় করে নিজেদের পালনকর্তাকে তাদের জন্যে রয়েছে জান্নাত যার তলদেশে প্রবাহিত রয়েছে প্রস্রবণ। তাতে আল্লাহর পক্ষ থেকে সদা আপ্যায়ন চলতে থাকবে। আর যা আল্লাহর নিকট রয়েছে, তা সৎকর্মশীলদের জন্যে একান্তই উত্তম।'),
  ('bn.bengali', 3, 199, 'আর আহলে কিতাবদের মধ্যে কেউ কেউ এমনও রয়েছে, যারা আল্লাহর উপর ঈমান আনে এবং যা কিছু তোমার উপর অবতীর্ণ হয় আর যা কিছু তাদের উপর অবতীর্ণ হয়েছে সেগুলোর উপর, আল্লাহর সামনে বিনয়াবনত থাকে এবং আল্লার আয়াতসমুহকে স্বল্পমুল্যের বিনিময়ে সওদা করে না, তারাই হলো সে লোক যাদের জন্য পারিশ্রমিক রয়েছে তাদের পালনকর্তার নিকট। নিশ্চয়ই আল্লাহ যথাশীঘ্র হিসাব চুকিয়ে দেন।'),
  ('bn.bengali', 3, 200, 'হে ঈমানদানগণ! ধৈর্য্য ধারণ কর এবং মোকাবেলায় দৃঢ়তা অবলম্বন কর। আর আল্লাহকে ভয় করতে থাক যাতে তোমরা তোমাদের উদ্দেশ্য লাভে সমর্থ হতে পার।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 3, 1, 'Alim. Lam. Mim.'),
  ('en.pickthall', 3, 2, 'Allah! There is no god save Him, the Alive, the Eternal.'),
  ('en.pickthall', 3, 3, 'He hath revealed unto thee (Muhammad) the Scripture with truth, confirming that which was (revealed) before it, even as He revealed the Torah and the Gospel.'),
  ('en.pickthall', 3, 4, 'Aforetime, for a guidance to mankind; and hath revealed the Criterion (of right and wrong). Lo! those who disbelieve the revelations of Allah, theirs will be a heavy doom. Allah is Mighty, Able to Requite (the wrong).'),
  ('en.pickthall', 3, 5, 'Lo! nothing in the earth or in the heavens is hidden from Allah.'),
  ('en.pickthall', 3, 6, 'He it is Who fashioneth you in the wombs as pleaseth Him. There is no Allah save Him, the Almighty, the Wise.'),
  ('en.pickthall', 3, 7, 'He it is Who hath revealed unto thee (Muhammad) the Scripture wherein are clear revelations - they are the substance of the Book - and others (which are) allegorical. But those in whose hearts is doubt pursue, forsooth, that which is allegorical seeking (to cause) dissension by seeking to explain it. None knoweth its explanation save Allah. And those who are of sound instruction say: We believe therein; the whole is from our Lord; but only men of understanding really heed.'),
  ('en.pickthall', 3, 8, 'Our Lord! Cause not our hearts to stray after Thou hast guided us, and bestow upon us mercy from Thy Presence. Lo! Thou, only Thou, art the Bestower.'),
  ('en.pickthall', 3, 9, 'Our Lord! Lo! it is Thou Who gatherest mankind together to a Day of which there is no doubt. Lo! Allah faileth not to keep the tryst.'),
  ('en.pickthall', 3, 10, '(On that Day) neither the riches nor the progeny of those who disbelieve will aught avail them with Allah. They will be fuel for Fire.'),
  ('en.pickthall', 3, 11, 'Like Pharaoh\'s folk and those who were before them, they disbelieved Our revelations and so Allah seized them for their sins. And Allah is severe in punishment.'),
  ('en.pickthall', 3, 12, 'Say (O Muhammad) unto those who disbelieve: Ye shall be overcome and gathered unto Hell, an evil resting-place.'),
  ('en.pickthall', 3, 13, 'There was a token for you in two hosts which met: one army fighting in the way of Allah, and another disbelieving, whom they saw as twice their number, clearly, with their very eyes. Thus Allah strengtheneth with His succour whom He will. Lo! herein verily is a lesson for those who have eyes.'),
  ('en.pickthall', 3, 14, 'Beautified for mankind is love of the joys (that come) from women and offspring; and stored-up heaps of gold and silver, and horses branded (with their mark), and cattle and land. That is comfort of the life of the world. Allah! With Him is a more excellent abode.'),
  ('en.pickthall', 3, 15, 'Say: Shall I inform you of something better than that? For those who keep from evil, with their Lord, are Gardens underneath which rivers flow wherein they will abide, and pure companions, and contentment from Allah. Allah is Seer of His bondmen,'),
  ('en.pickthall', 3, 16, 'Those who say: Our Lord! Lo! we believe. So forgive us our sins and guard us from the punishment of Fire;'),
  ('en.pickthall', 3, 17, 'The steadfast, and the truthful, and the obedient, those who spend (and hoard not), those who pray for pardon in the watches of the night.'),
  ('en.pickthall', 3, 18, 'Allah (Himself) is Witness that there is no Allah save Him. And the angels and the men of learning (too are witness). Maintaining His creation in justice, there is no Allah save Him the Almighty, the Wise.'),
  ('en.pickthall', 3, 19, 'Lo! religion with Allah (is) the Surrender (to His Will and Guidance). Those who (formerly) received the Scripture differed only after knowledge came unto them, through transgression among themselves. Whoso disbelieveth the revelations of Allah (will find that) lo! Allah is swift at reckoning.'),
  ('en.pickthall', 3, 20, 'And if they argue with thee, (O Muhammad), say: I have surrendered my purpose to Allah and (so have) those who follow me. And say unto those who have received the Scripture and those who read not: Have ye (too) surrendered? If they surrender, then truly they are rightly guided, and if they turn away, then it is thy duty only to convey the message (unto them). Allah is Seer of (His) bondmen.'),
  ('en.pickthall', 3, 21, 'Lo! those who disbelieve the revelations of Allah, and slay the prophets wrongfully, and slay those of mankind who enjoin equity: promise them a painful doom.'),
  ('en.pickthall', 3, 22, 'Those are they whose works have failed in the world and the Hereafter; and they have no helpers.'),
  ('en.pickthall', 3, 23, 'Hast thou not seen how those who have received a portion of the Scripture invoke the Scripture of Allah (in their disputes) that it may judge between them; then a faction of them turn away, being opposed (to it)?'),
  ('en.pickthall', 3, 24, 'That is because they say: The Fire will not touch us save for a certain number of days. That which they used to invent hath deceived them regarding their religion.'),
  ('en.pickthall', 3, 25, 'How (will it be with them) when We have brought them all together to a Day of which there is no doubt, when every soul will be paid in full what it hath earned, and they will not be wronged.'),
  ('en.pickthall', 3, 26, 'Say: O Allah! Owner of Sovereignty! Thou givest sovereignty unto whom Thou wilt, and Thou withdrawest sovereignty from whom Thou wilt. Thou exaltest whom Thou wilt, and Thou abasest whom Thou wilt. In Thy hand is the good. Lo! Thou art Able to do all things.'),
  ('en.pickthall', 3, 27, 'Thou causest the night to pass into the day, and Thou causest the day to pass into the night. And Thou bringest forth the living from the dead, and Thou bringest forth the dead from the living. And Thou givest sustenance to whom Thou choosest, without stint.'),
  ('en.pickthall', 3, 28, 'Let not the believers take disbelievers for their friends in preference to believers. Whoso doeth that hath no connection with Allah unless (it be) that ye but guard yourselves against them, taking (as it were) security. Allah biddeth you beware (only) of Himself. Unto Allah is the journeying.'),
  ('en.pickthall', 3, 29, 'Say, (O Muhammad): Whether ye hide that which is in your breasts or reveal it, Allah knoweth it. He knoweth that which is in the heavens and that which is in the earth, and Allah is Able to do all things.'),
  ('en.pickthall', 3, 30, 'On the Day when every soul will find itself confronted with all that it hath done of good and all that it hath done of evil (every soul) will long that there might be a mighty space of distance between it and that (evil). Allah biddeth you beware of Him. And Allah is Full of Pity for (His) bondmen.'),
  ('en.pickthall', 3, 31, 'Say, (O Muhammad, to mankind): If ye love Allah, follow me; Allah will love you and forgive you your sins. Allah is Forgiving, Merciful.'),
  ('en.pickthall', 3, 32, 'Say: Obey Allah and the messenger. But if they turn away, lo! Allah loveth not the disbelievers (in His guidance).'),
  ('en.pickthall', 3, 33, 'Lo! Allah preferred Adam and Noah and the Family of Abraham and the Family of \'Imran above (all His) creatures.'),
  ('en.pickthall', 3, 34, 'They were descendants one of another. Allah is Hearer, Knower.'),
  ('en.pickthall', 3, 35, '(Remember) when the wife of \'Imran said: My Lord! I have vowed unto Thee that which is in my belly as a consecrated (offering). Accept it from me. Lo! Thou, only Thou, art the Hearer, the Knower!'),
  ('en.pickthall', 3, 36, 'And when she was delivered she said: My Lord! Lo! I am delivered of a female - Allah knew best of what she was delivered - the male is not as the female; and lo! I have named her Mary, and lo! I crave Thy protection for her and for her offspring from Satan the outcast.'),
  ('en.pickthall', 3, 37, 'And her Lord accepted her with full acceptance and vouchsafed to her a goodly growth; and made Zachariah her guardian. Whenever Zachariah went into the sanctuary where she was, he found that she had food. He said: O Mary! Whence cometh unto thee this (food)? She answered: It is from Allah. Allah giveth without stint to whom He will.'),
  ('en.pickthall', 3, 38, 'Then Zachariah prayed unto his Lord and said: My Lord! Bestow upon me of Thy bounty goodly offspring. Lo! Thou art the Hearer of Prayer.'),
  ('en.pickthall', 3, 39, 'And the angels called to him as he stood praying in the sanctuary: Allah giveth thee glad tidings of (a son whose name is) John, (who cometh) to confirm a word from Allah lordly, chaste, a prophet of the righteous.'),
  ('en.pickthall', 3, 40, 'He said: My Lord! How can I have a son when age hath overtaken me already and my wife is barren? (The angel) answered: So (it will be). Allah doeth what He will.'),
  ('en.pickthall', 3, 41, 'He said: My Lord! Appoint a token for me. (The angel) said: The token unto thee (shall be) that thou shalt not speak unto mankind three days except by signs. Remember thy Lord much, and praise (Him) in the early hours of night and morning.'),
  ('en.pickthall', 3, 42, 'And when the angels said: O Mary! Lo! Allah hath chosen thee and made thee pure, and hath preferred thee above (all) the women of creation.'),
  ('en.pickthall', 3, 43, 'O Mary! Be obedient to thy Lord, prostrate thyself and bow with those who bow (in worship).'),
  ('en.pickthall', 3, 44, 'This is of the tidings of things hidden. We reveal it unto thee (Muhammad). Thou wast not present with them when they threw their pens (to know) which of them should be the guardian of Mary, nor wast thou present with them when they quarrelled (thereupon).'),
  ('en.pickthall', 3, 45, '(And remember) when the angels said: O Mary! Lo! Allah giveth thee glad tidings of a word from him, whose name is the Messiah, Jesus, son of Mary, illustrious in the world and the Hereafter, and one of those brought near (unto Allah).'),
  ('en.pickthall', 3, 46, 'He will speak unto mankind in his cradle and in his manhood, and he is of the righteous.'),
  ('en.pickthall', 3, 47, 'She said: My Lord! How can I have a child when no mortal hath touched me? He said: So (it will be). Allah createth what He will. If He decreeth a thing, He saith unto it only: Be! and it is.'),
  ('en.pickthall', 3, 48, 'And He will teach him the Scripture and wisdom, and the Torah and the Gospel,'),
  ('en.pickthall', 3, 49, 'And will make him a messenger unto the Children of Israel, (saying): Lo! I come unto you with a sign from your Lord. Lo! I fashion for you out of clay the likeness of a bird, and I breathe into it and it is a bird, by Allah\'s leave. I heal him who was born blind, and the leper, and I raise the dead, by Allah\'s leave. And I announce unto you what ye eat and what ye store up in your houses. Lo! herein verily is a portent for you, if ye are to be believers.'),
  ('en.pickthall', 3, 50, 'And (I come) confirming that which was before me of the Torah, and to make lawful some of that which was forbidden unto you. I come unto you with a sign from your Lord, so keep your duty to Allah and obey me.'),
  ('en.pickthall', 3, 51, 'Lo! Allah is my Lord and your Lord, so worship Him. That is a straight path.'),
  ('en.pickthall', 3, 52, 'But when Jesus became conscious of their disbelief, he cried: Who will be my helpers in the cause of Allah? The disciples said: We will be Allah\'s helpers. We believe in Allah, and bear thou witness that we have surrendered (unto Him).'),
  ('en.pickthall', 3, 53, 'Our Lord! We believe in that which Thou hast revealed and we follow him whom Thou hast sent. Enrol us among those who witness (to the truth).'),
  ('en.pickthall', 3, 54, 'And they (the disbelievers) schemed, and Allah schemed (against them): and Allah is the best of schemers.'),
  ('en.pickthall', 3, 55, '(And remember) when Allah said: O Jesus! Lo! I am gathering thee and causing thee to ascend unto Me, and am cleansing thee of those who disbelieve and am setting those who follow thee above those who disbelieve until the Day of Resurrection. Then unto Me ye will (all) return, and I shall judge between you as to that wherein ye used to differ.'),
  ('en.pickthall', 3, 56, 'As for those who disbelieve I shall chastise them with a heavy chastisement in the world and the Hereafter; and they will have no helpers.'),
  ('en.pickthall', 3, 57, 'And as for those who believe and do good works, He will pay them their wages in full. Allah loveth not wrong-doers.'),
  ('en.pickthall', 3, 58, 'This (which) We recite unto thee is a revelation and a wise reminder.'),
  ('en.pickthall', 3, 59, 'Lo! the likeness of Jesus with Allah is as the likeness of Adam. He created him of dust, then He said unto him: Be! and he is.'),
  ('en.pickthall', 3, 60, '(This is) the truth from thy Lord (O Muhammad), so be not thou of those who waver.'),
  ('en.pickthall', 3, 61, 'And whoso disputeth with thee concerning him, after the knowledge which hath come unto thee, say (unto him): Come! We will summon our sons and your sons, and our women and your women, and ourselves and yourselves, then we will pray humbly (to our Lord) and (solemnly) invoke the curse of Allah upon those who lie.'),
  ('en.pickthall', 3, 62, 'Lo! This verily is the true narrative. There is no Allah save Allah, and lo! Allah, He verily is, is the Mighty, the Wise.'),
  ('en.pickthall', 3, 63, 'And if they turn away, then lo! Allah is Aware of (who are) the corrupters.'),
  ('en.pickthall', 3, 64, 'Say: O People of the Scripture! Come to an agreement between us and you: that we shall worship none but Allah, and that we shall ascribe no partner unto Him, and that none of us shall take others for lords beside Allah. And if they turn away, then say: Bear witness that we are they who have surrendered (unto Him).'),
  ('en.pickthall', 3, 65, 'O People of the Scripture! Why will ye argue about Abraham, when the Torah and the Gospel were not revealed till after him? Have ye then no sense?'),
  ('en.pickthall', 3, 66, 'Lo! ye are those who argue about that whereof ye have some knowledge: Why then argue ye concerning that whereof ye have no knowledge? Allah knoweth. Ye know not.'),
  ('en.pickthall', 3, 67, 'Abraham was not a Jew, nor yet a Christian; but he was an upright man who had surrendered (to Allah), and he was not of the idolaters.'),
  ('en.pickthall', 3, 68, 'Lo! those of mankind who have the best claim to Abraham are those who followed him, and this Prophet and those who believe (with him); and Allah is the Protecting Guardian of the believers.'),
  ('en.pickthall', 3, 69, 'A party of the People of the Scripture long to make you go astray; and they make none to go astray except themselves, but they perceive not.'),
  ('en.pickthall', 3, 70, 'O People of the Scripture! Why disbelieve ye in the revelations of Allah, when ye (yourselves) bear witness (to their truth)?'),
  ('en.pickthall', 3, 71, 'O People of the Scripture! Why confound ye truth with falsehood and knowingly conceal the truth?'),
  ('en.pickthall', 3, 72, 'And a party of the People of the Scripture say: Believe in that which hath been revealed unto those who believe at the opening of the day, and disbelieve at the end thereof, in order that they may return;'),
  ('en.pickthall', 3, 73, 'And believe not save in one who followeth your religion - Say (O Muhammad): Lo! the guidance is Allah\'s Guidance - that anyone is given the like of that which was given unto you or that they may argue with you in the presence of their Lord. Say (O Muhammad): Lo! the bounty is in Allah\'s hand. He bestoweth it on whom He will. Allah is All-Embracing, All-Knowing.'),
  ('en.pickthall', 3, 74, 'He selecteth for His mercy whom He will. Allah is of Infinite Bounty.'),
  ('en.pickthall', 3, 75, 'Among the People of the Scripture there is he who, if thou trust him with a weight of treasure, will return it to thee. And among them there is he who, if thou trust him with a piece of gold, will not return it to thee unless thou keep standing over him. That is because they say: We have no duty to the Gentiles. They speak a lie concerning Allah knowingly.'),
  ('en.pickthall', 3, 76, 'Nay, but (the chosen of Allah is) he who fulfilleth his pledge and wardeth off (evil); for lo! Allah loveth those who ward off (evil).'),
  ('en.pickthall', 3, 77, 'Lo! those who purchase a small gain at the cost of Allah\'s covenant and their oaths, they have no portion in the Hereafter. Allah will neither speak to them nor look upon them on the Day of Resurrection, nor will He make them grow. Theirs will be a painful doom.'),
  ('en.pickthall', 3, 78, 'And lo! there is a party of them who distort the Scripture with their tongues, that ye may think that what they say is from the Scripture, when it is not from the Scripture. And they say: It is from Allah, when it is not from Allah; and they speak a lie concerning Allah knowingly.'),
  ('en.pickthall', 3, 79, 'It is not (possible) for any human being unto whom Allah had given the Scripture and wisdom and the prophethood that he should afterwards have said unto mankind: Be slaves of me instead of Allah; but (what he said was): Be ye faithful servants of the Lord by virtue of your constant teaching of the Scripture and of your constant study thereof.'),
  ('en.pickthall', 3, 80, 'And he commanded you not that ye should take the angels and the prophets for lords. Would he command you to disbelieve after ye had surrendered (to Allah)?'),
  ('en.pickthall', 3, 81, 'When Allah made (His) covenant with the prophets, (He said): Behold that which I have given you of the Scripture and knowledge. And afterward there will come unto you a messenger, confirming that which ye possess. Ye shall believe in him and ye shall help him. He said: Do ye agree, and will ye take up My burden (which I lay upon you) in this (matter)? They answered: We agree. He said: Then bear ye witness. I will be a witness with you.'),
  ('en.pickthall', 3, 82, 'Then whosoever after this shall turn away: they will be miscreants.'),
  ('en.pickthall', 3, 83, 'Seek they other than the religion of Allah, when unto Him submitteth whosoever is in the heavens and the earth, willingly or unwillingly, and unto Him they will be returned.'),
  ('en.pickthall', 3, 84, 'Say (O Muhammad): We believe in Allah and that which is revealed unto us and that which was revealed unto Abraham and Ishmael and Isaac and Jacob and the tribes, and that which was vouchsafed unto Moses and Jesus and the prophets from their Lord. We make no distinction between any of them, and unto Him we have surrendered.'),
  ('en.pickthall', 3, 85, 'And whoso seeketh as religion other than the Surrender (to Allah) it will not be accepted from him, and he will be a loser in the Hereafter.'),
  ('en.pickthall', 3, 86, 'How shall Allah guide a people who disbelieved after their belief and (after) they bore witness that the messenger is true and after clear proofs (of Allah\'s Sovereignty) had come unto them. And Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 3, 87, 'As for such, their guerdon is that on them rests the curse of Allah and of angels and of men combined.'),
  ('en.pickthall', 3, 88, 'They will abide therein. Their doom will not be lightened, neither will they be reprieved;'),
  ('en.pickthall', 3, 89, 'Save those who afterward repent and do right. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 3, 90, 'Lo! those who disbelieve after their (profession of) belief, and afterward grow violent in disbelief: their repentance will not be accepted. And such are those who are astray.'),
  ('en.pickthall', 3, 91, 'Lo! those who disbelieve, and die in disbelief, the (whole) earth full of gold would not be accepted from such an one if it were offered as a ransom (for his soul). Theirs will be a painful doom and they will have no helpers.'),
  ('en.pickthall', 3, 92, 'Ye will not attain unto piety until ye spend of that which ye love. And whatsoever ye spend, Allah is Aware thereof.'),
  ('en.pickthall', 3, 93, 'All food was lawful unto the Children of Israel, save that which Israel forbade himself, (in days) before the Torah was revealed. Say: Produce the Torah and read it (unto us) if ye are truthful.'),
  ('en.pickthall', 3, 94, 'And whoever shall invent a falsehood after that concerning Allah, such will be wrong-doers.'),
  ('en.pickthall', 3, 95, 'Say: Allah speaketh truth. So follow the religion of Abraham, the upright. He was not of the idolaters.'),
  ('en.pickthall', 3, 96, 'Lo! the first Sanctuary appointed for mankind was that at Becca, a blessed place, a guidance to the peoples;'),
  ('en.pickthall', 3, 97, 'Wherein are plain memorials (of Allah\'s guidance); the place where Abraham stood up to pray; and whosoever entereth it is safe. And pilgrimage to the House is a duty unto Allah for mankind, for him who can find a way thither. As for him who disbelieveth, (let him know that) lo! Allah is Independent of (all) creatures.'),
  ('en.pickthall', 3, 98, 'Say: O People of the Scripture! Why disbelieve ye in the revelations of Allah, when Allah (Himself) is Witness of what ye do?'),
  ('en.pickthall', 3, 99, 'Say: O People of the Scripture! Why drive ye back believers from the way of Allah, seeking to make it crooked, when ye are witnesses (to Allah\'s guidance)? Allah is not unaware of what ye do.'),
  ('en.pickthall', 3, 100, 'O ye who believe! If ye obey a party of those who have received the Scripture they will make you disbelievers after your belief.'),
  ('en.pickthall', 3, 101, 'How can ye disbelieve, when it is ye unto whom Allah\'s revelations are recited, and His messenger is in your midst? He who holdeth fast to Allah, he indeed is guided unto a right path.'),
  ('en.pickthall', 3, 102, 'O ye who believe! Observe your duty to Allah with right observance, and die not save as those who have surrendered (unto Him)'),
  ('en.pickthall', 3, 103, 'And hold fast, all of you together, to the cable of Allah, and do not separate. And remember Allah\'s favour unto you: How ye were enemies and He made friendship between your hearts so that ye became as brothers by His grace; and (how) ye were upon the brink of an abyss of fire, and He did save you from it. Thus Allah maketh clear His revelations unto you, that haply ye may be guided,'),
  ('en.pickthall', 3, 104, 'And there may spring from you a nation who invite to goodness, and enjoin right conduct and forbid indecency. Such are they who are successful.'),
  ('en.pickthall', 3, 105, 'And be ye not as those who separated and disputed after the clear proofs had come unto them. For such there is an awful doom,'),
  ('en.pickthall', 3, 106, 'On the Day when (some) faces will be whitened and (some) faces will be blackened; and as for those whose faces have been blackened, it will be said unto them: Disbelieved ye after your (profession of) belief? Then taste the punishment for that ye disbelieved.'),
  ('en.pickthall', 3, 107, 'And as for those whose faces have been whitened, in the mercy of Allah they dwell for ever.'),
  ('en.pickthall', 3, 108, 'These are revelations of Allah. We recite them unto thee in truth. Allah willeth no injustice to (His) creatures.'),
  ('en.pickthall', 3, 109, 'Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth; and unto Allah all things are returned.'),
  ('en.pickthall', 3, 110, 'Ye are the best community that hath been raised up for mankind. Ye enjoin right conduct and forbid indecency; and ye believe in Allah. And if the People of the Scripture had believed it had been better for them. Some of them are believers; but most of them are evil-livers.'),
  ('en.pickthall', 3, 111, 'They will not harm you save a trifling hurt, and if they fight against you they will turn and flee. And afterward they will not be helped.'),
  ('en.pickthall', 3, 112, 'Ignominy shall be their portion wheresoever they are found save (where they grasp) a rope from Allah and a rope from men. They have incurred anger from their Lord, and wretchedness is laid upon them. That is because they used to disbelieve the revelations of Allah, and slew the prophets wrongfully. That is because they were rebellious and used to transgress.'),
  ('en.pickthall', 3, 113, 'They are not all alike. Of the People of the Scripture there is a staunch community who recite the revelations of Allah in the night season, falling prostrate (before Him).'),
  ('en.pickthall', 3, 114, 'They believe in Allah and the Last Day, and enjoin right conduct and forbid indecency, and vie one with another in good works. These are of the righteous.'),
  ('en.pickthall', 3, 115, 'And whatever good they do, they will not be denied the meed thereof. Allah is Aware of those who ward off (evil).'),
  ('en.pickthall', 3, 116, 'Lo! the riches and the progeny of those who disbelieve will not avail them aught against Allah; and such are rightful owners of the Fire. They will abide therein.'),
  ('en.pickthall', 3, 117, 'The likeness of that which they spend in this life of the world is as the likeness of a biting, icy wind which smiteth the harvest of a people who have wronged themselves, and devastateth it. Allah wronged them not, but they do wrong themselves.'),
  ('en.pickthall', 3, 118, 'O ye who believe! Take not for intimates others than your own folk, who would spare no pains to ruin you; they love to hamper you. Hatred is revealed by (the utterance of) their mouths, but that which their breasts hide is greater. We have made plain for you the revelations if ye will understand.'),
  ('en.pickthall', 3, 119, 'Lo! ye are those who love them though they love you not, and ye believe in all the Scripture. When they fall in with you they say: We believe; but when they go apart they bite their finger-tips at you, for rage. Say: Perish in your rage! Lo! Allah is Aware of what is hidden in (your) breasts.'),
  ('en.pickthall', 3, 120, 'If a lucky chance befall you, it is evil unto them, and if disaster strike you they rejoice thereat. But if ye persevere and keep from evil their guile will never harm you. Lo! Allah is Surrounding what they do.'),
  ('en.pickthall', 3, 121, 'And when thou settedst forth at daybreak from thy housefolk to assign to the believers their positions for the battle, Allah was Hearer, Knower.'),
  ('en.pickthall', 3, 122, 'When two parties of you almost fell away, and Allah was their Protecting Friend. In Allah let believers put their trust.'),
  ('en.pickthall', 3, 123, 'Allah had already given you the victory at Badr, when ye were contemptible. So observe your duty to Allah in order that ye may be thankful.'),
  ('en.pickthall', 3, 124, 'When thou didst say unto the believers: Is it not sufficient for you that your Lord should support you with three thousand angels sent down (to your help)?'),
  ('en.pickthall', 3, 125, 'Nay, but if ye persevere, and keep from evil, and (the enemy) attack you suddenly, your Lord will help you with five thousand angels sweeping on.'),
  ('en.pickthall', 3, 126, 'Allah ordained this only as a message of good cheer for you, and that thereby your hearts might be at rest - Victory cometh only from Allah, the Mighty, the Wise -'),
  ('en.pickthall', 3, 127, 'That He may cut off a part of those who disbelieve, or overwhelm them so that they retire, frustrated.'),
  ('en.pickthall', 3, 128, 'It is no concern at all of thee (Muhammad) whether He relent toward them or punish them; for they are evil-doers.'),
  ('en.pickthall', 3, 129, 'Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth. He forgiveth whom He will, and punisheth whom He will. Allah is Forgiving, Merciful.'),
  ('en.pickthall', 3, 130, 'O ye who believe! Devour not usury, doubling and quadrupling (the sum lent). Observe your duty to Allah, that ye may be successful.'),
  ('en.pickthall', 3, 131, 'And ward off (from yourselves) the Fire prepared for disbelievers.'),
  ('en.pickthall', 3, 132, 'And obey Allah and the messenger, that ye may find mercy.'),
  ('en.pickthall', 3, 133, 'And vie one with another for forgiveness from your Lord, and for a paradise as wide as are the heavens and the earth, prepared for those who ward off (evil);'),
  ('en.pickthall', 3, 134, 'Those who spend (of that which Allah hath given them) in ease and in adversity, those who control their wrath and are forgiving toward mankind; Allah loveth the good;'),
  ('en.pickthall', 3, 135, 'And those who, when they do an evil thing or wrong themselves, remember Allah and implore forgiveness for their sins - Who forgiveth sins save Allah only? - and will not knowingly repeat (the wrong) they did.'),
  ('en.pickthall', 3, 136, 'The reward of such will be forgiveness from their Lord, and Gardens underneath which rivers flow, wherein they will abide for ever - a bountiful reward for workers!'),
  ('en.pickthall', 3, 137, 'Systems have passed away before you. Do but travel in the land and see the nature of the consequence for those who did deny (the messengers).'),
  ('en.pickthall', 3, 138, 'This is a declaration for mankind, a guidance and an admonition unto those who ward off (evil)'),
  ('en.pickthall', 3, 139, 'Faint not nor grieve, for ye will overcome them if ye are (indeed) believers.'),
  ('en.pickthall', 3, 140, 'If ye have received a blow, the (disbelieving) people have received a blow the like thereof. These are (only) the vicissitudes which We cause to follow one another for mankind, to the end that Allah may know those who believe and may choose witnesses from among you; and Allah loveth not wrong-doers.'),
  ('en.pickthall', 3, 141, 'And that Allah may prove those who believe, and may blight the disbelievers.'),
  ('en.pickthall', 3, 142, 'Or deemed ye that ye would enter paradise while yet Allah knoweth not those of you who really strive, nor knoweth those (of you) who are steadfast?'),
  ('en.pickthall', 3, 143, 'And verily ye used to wish for death before ye met it (in the field). Now ye have seen it with your eyes!'),
  ('en.pickthall', 3, 144, 'Muhammad is but a messenger, messengers (the like of whom) have passed away before him. Will it be that, when he dieth or is slain, ye will turn back on your heels? He who turneth back on his heels doth no hurt to Allah, and Allah will reward the thankful.'),
  ('en.pickthall', 3, 145, 'No soul can ever die except by Allah\'s leave and at a term appointed. Whoso desireth the reward of the world, We bestow on him thereof; and whoso desireth the reward of the Hereafter, We bestow on him thereof. We shall reward the thankful.'),
  ('en.pickthall', 3, 146, 'And with how many a prophet have there been a number of devoted men who fought (beside him). They quailed not for aught that befell them in the way of Allah, nor did they weaken, nor were they brought low. Allah loveth the steadfast.'),
  ('en.pickthall', 3, 147, 'Their cry was only that they said: Our Lord! forgive us for our sins and wasted efforts, make our foothold sure, and give us victory over the disbelieving folk.'),
  ('en.pickthall', 3, 148, 'So Allah gave them the reward of the world and the good reward of the Hereafter. Allah loveth those whose deeds are good.'),
  ('en.pickthall', 3, 149, 'O ye who believe! if ye obey those who disbelieve, they will make you turn back on your heels, and ye turn back as losers.'),
  ('en.pickthall', 3, 150, 'But Allah is your Protector, and He is the Best of Helpers.'),
  ('en.pickthall', 3, 151, 'We shall cast terror into the hearts of those who disbelieve because they ascribe unto Allah partners, for which no warrant hath been revealed. Their habitation is the Fire, and hapless the abode of the wrong-doers.'),
  ('en.pickthall', 3, 152, 'Allah verily made good His promise unto you when ye routed them by His leave, until (the moment) when your courage failed you, and ye disagreed about the order and ye disobeyed, after He had shown you that for which ye long. Some of you desired the world, and some of you desired the Hereafter. Therefore He made you flee from them, that He might try you. Yet now He hath forgiven you. Allah is a Lord of Kindness to believers.'),
  ('en.pickthall', 3, 153, 'When ye climbed (the hill) and paid no heed to anyone, while the messenger, in your rear, was calling you (to fight). Therefor He rewarded you grief for (his) grief, that (He might teach) you not to sorrow either for that which ye missed or for that which befell you. Allah is Informed of what ye do.'),
  ('en.pickthall', 3, 154, 'Then, after grief, He sent down security for you. As slumber did it overcome a party of you, while (the other) party, who were anxious on their own account, thought wrongly of Allah, the thought of ignorance. They said: Have we any part in the cause? Say (O Muhammad): The cause belongeth wholly to Allah. They hide within themselves (a thought) which they reveal not unto thee, saying: Had we had any part in the cause we should not have been slain here. Say: Even though ye had been in your houses, those appointed to be slain would have gone forth to the places where they were to lie. (All this hath been) in order that Allah might try what is in your breasts and prove what is in your hearts. Allah is Aware of what is hidden in the breasts (of men).'),
  ('en.pickthall', 3, 155, 'Lo! those of you who turned back on the day when the two hosts met, Satan alone it was who caused them to backslide, because of some of that which they have earned. Now Allah hath forgiven them. Lo! Allah is Forgiving, Clement.'),
  ('en.pickthall', 3, 156, 'O ye who believe! Be not as those who disbelieved and said of their brethren who went abroad in the land or were fighting in the field: If they had been (here) with us they would not have died or been killed: that Allah may make it anguish in their hearts. Allah giveth life and causeth death; and Allah is Seer of what ye do.'),
  ('en.pickthall', 3, 157, 'And what though ye be slain in Allah\'s way or die therein? Surely pardon from Allah and mercy are better than all that they amass.'),
  ('en.pickthall', 3, 158, 'What though ye be slain or die, when unto Allah ye are gathered?'),
  ('en.pickthall', 3, 159, 'It was by the mercy of Allah that thou wast lenient with them (O Muhammad), for if thou hadst been stern and fierce of heart they would have dispersed from round about thee. So pardon them and ask forgiveness for them and consult with them upon the conduct of affairs. And when thou art resolved, then put thy trust in Allah. Lo! Allah loveth those who put their trust (in Him).'),
  ('en.pickthall', 3, 160, 'If Allah is your helper none can overcome you, and if He withdraw His help from you, who is there who can help you after Him? In Allah let believers put their trust.'),
  ('en.pickthall', 3, 161, 'It is not for any prophet to embezzle. Whoso embezzleth will bring what he embezzled with him on the Day of Resurrection. Then every soul will be paid in full what it hath earned; and they will not be wronged.'),
  ('en.pickthall', 3, 162, 'Is one who followeth the pleasure of Allah as one who hath earned condemnation from Allah, whose habitation is the Fire, a hapless journey\'s end?'),
  ('en.pickthall', 3, 163, 'There are degrees (of grace and reprobation) with Allah, and Allah is Seer of what they do.'),
  ('en.pickthall', 3, 164, 'Allah verily hath shown grace to the believers by sending unto them a messenger of their own who reciteth unto them His revelations, and causeth them to grow, and teacheth them the Scripture and wisdom; although before (he came to them) they were in flagrant error.'),
  ('en.pickthall', 3, 165, 'And was it so, when a disaster smote you, though ye had smitten (them with a disaster) twice (as great), that ye said: How is this? Say (unto them, O Muhammad): It is from yourselves. Lo! Allah is Able to do all things.'),
  ('en.pickthall', 3, 166, 'That which befell you, on the day when the two armies met, was by permission of Allah; that He might know the true believers;'),
  ('en.pickthall', 3, 167, 'And that He might know the hypocrites, unto whom it was said: Come, fight in the way of Allah, or defend yourselves. They answered: If we knew aught of fighting we would follow you. On that day they were nearer disbelief than faith. They utter with their mouths a thing which is not in their hearts. Allah is Best Aware of what they hide.'),
  ('en.pickthall', 3, 168, 'Those who, while they sat at home, said of their brethren (who were fighting for the cause of Allah): If they had been guided by us they would not have been slain. Say (unto them, O Muhammad): Then avert death from yourselves if ye are truthful.'),
  ('en.pickthall', 3, 169, 'Think not of those, who are slain in the way of Allah, as dead. Nay, they are living. With their Lord they have provision.'),
  ('en.pickthall', 3, 170, 'Jubilant (are they) because of that which Allah hath bestowed upon them of His bounty, rejoicing for the sake of those who have not joined them but are left behind: That there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 3, 171, 'They rejoice because of favour from Allah and kindness, and that Allah wasteth not the wage of the believers.'),
  ('en.pickthall', 3, 172, 'As for those who heard the call of Allah and His messenger after the harm befell them (in the fight); for such of them as do right and ward off (evil), there is great reward.'),
  ('en.pickthall', 3, 173, 'Those unto whom men said: Lo! the people have gathered against you, therefor fear them. (The threat of danger) but increased the faith of them and they cried: Allah is Sufficient for us! Most Excellent is He in Whom we trust!'),
  ('en.pickthall', 3, 174, 'So they returned with grace and favour from Allah, and no harm touched them. They followed the good pleasure of Allah, and Allah is of Infinite Bounty.'),
  ('en.pickthall', 3, 175, 'It is only the devil who would make (men) fear his partisans. Fear them not; fear Me, if ye are true believers.'),
  ('en.pickthall', 3, 176, 'Let not their conduct grieve thee, who run easily to disbelief, for lo! they injure Allah not at all. It is Allah\'s Will to assign them no portion in the Hereafter, and theirs will be an awful doom.'),
  ('en.pickthall', 3, 177, 'Those who purchase disbelief at the price of faith harm Allah not at all, but theirs will be a painful doom.'),
  ('en.pickthall', 3, 178, 'And let not those who disbelieve imagine that the rein We give them bodeth good unto their souls. We only give them rein that they may grow in sinfulness. And theirs will be a shameful doom.'),
  ('en.pickthall', 3, 179, 'It is not (the purpose) of Allah to leave you in your present state till He shall separate the wicked from the good. And it is not (the purpose of) Allah to let you know the Unseen. But Allah chooseth of His messengers whom He will, (to receive knowledge thereof). So believe in Allah and His messengers. If ye believe and ward off (evil), yours will be a vast reward.'),
  ('en.pickthall', 3, 180, 'And let not those who hoard up that which Allah hath bestowed upon them of His bounty think that it is better for them. Nay, it is worse for them. That which they hoard will be their collar on the Day of Resurrection. Allah\'s is the heritage of the heavens and the earth, and Allah is Informed of what ye do.'),
  ('en.pickthall', 3, 181, 'Verily Allah heard the saying of those who said, (when asked for contributions to the war): "Allah, forsooth, is poor, and we are rich!" We shall record their saying with their slaying of the prophets wrongfully and We shall say: Taste ye the punishment of burning!'),
  ('en.pickthall', 3, 182, 'This is on account of that which your own hands have sent before (you to the judgment). Allah is no oppressor of (His) bondmen.'),
  ('en.pickthall', 3, 183, '(The same are) those who say: Lo! Allah hath charged us that we believe not in any messenger until he bring us an offering which fire (from heaven) shall devour. Say (unto them, O Muhammad): Messengers came unto you before me with miracles, and with that (very miracle) which ye describe. Why then did ye slay them? (Answer that) if ye are truthful!'),
  ('en.pickthall', 3, 184, 'And if they deny thee, even so did they deny messengers who were before thee, who came with miracles and with the Psalms and with the Scripture giving light.'),
  ('en.pickthall', 3, 185, 'Every soul will taste of death. And ye will be paid on the Day of Resurrection only that which ye have fairly earned. Whoso is removed from the Fire and is made to enter paradise, he indeed is triumphant. The life of this world is but comfort of illusion.'),
  ('en.pickthall', 3, 186, 'Assuredly ye will be tried in your property and in your persons, and ye will hear much wrong from those who were given the Scripture before you, and from the idolaters. But if ye persevere and ward off (evil), then that is of the steadfast heart of things.'),
  ('en.pickthall', 3, 187, 'And (remember) when Allah laid a charge on those who had received the Scripture (He said): Ye are to expound it to mankind and not to hide it. But they flung it behind their backs and bought thereby a little gain. Verily evil is that which they have gained thereby.'),
  ('en.pickthall', 3, 188, 'Think not that those who exult in what they have given, and love to be praised for what they have not done - Think not, they are in safety from the doom. A painful doom is theirs.'),
  ('en.pickthall', 3, 189, 'Unto Allah belongeth the Sovereignty of the heavens and the earth. Allah is Able to do all things.'),
  ('en.pickthall', 3, 190, 'Lo! In the creation of the heavens and the earth and (in) the difference of night and day are tokens (of His Sovereignty) for men of understanding,'),
  ('en.pickthall', 3, 191, 'Such as remember Allah, standing, sitting, and reclining, and consider the creation of the heavens and the earth, (and say): Our Lord! Thou createdst not this in vain. Glory be to Thee! Preserve us from the doom of Fire.'),
  ('en.pickthall', 3, 192, 'Our Lord! Whom Thou causest to enter the Fire: him indeed Thou hast confounded. For evil-doers there will be no helpers.'),
  ('en.pickthall', 3, 193, 'Our Lord! Lo! we have heard a crier calling unto Faith: "Believe ye in your Lord!" So we believed. Our Lord! Therefor forgive us our sins, and remit from us our evil deeds, and make us die the death of the righteous.'),
  ('en.pickthall', 3, 194, 'Our Lord! And give us that which Thou hast promised to us by Thy messengers. Confound us not upon the Day of Resurrection. Lo! Thou breakest not the tryst.'),
  ('en.pickthall', 3, 195, 'And their Lord hath heard them (and He saith): Lo! I suffer not the work of any worker, male or female, to be lost. Ye proceed one from another. So those who fled and were driven forth from their homes and suffered damage for My cause, and fought and were slain, verily I shall remit their evil deeds from them and verily I shall bring them into Gardens underneath which rivers flow - A reward from Allah. And with Allah is the fairest of rewards.'),
  ('en.pickthall', 3, 196, 'Let not the vicissitude (of the success) of those who disbelieve, in the land, deceive thee (O Muhammad).'),
  ('en.pickthall', 3, 197, 'It is but a brief comfort. And afterward their habitation will be hell, an ill abode.'),
  ('en.pickthall', 3, 198, 'But those who keep their duty to their Lord, for them are Gardens underneath which rivers flow, wherein they will be safe for ever. A gift of welcome from their Lord. That which Allah hath in store is better for the righteous.'),
  ('en.pickthall', 3, 199, 'And lo! of the People of the Scripture there are some who believe in Allah and that which is revealed unto you and that which was revealed unto them, humbling themselves before Allah. They purchase not a trifling gain at the price of the revelations of Allah. Verily their reward is with their Lord. Lo! Allah is swift to take account.'),
  ('en.pickthall', 3, 200, 'O ye who believe! Endure, outdo all others in endurance, be ready, and observe your duty to Allah, in order that ye may succeed.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 3, 1, 'A. L. M.'),
  ('en.yusufali', 3, 2, 'Allah! There is no god but He,-the Living, the Self-Subsisting, Eternal.'),
  ('en.yusufali', 3, 3, 'It is He Who sent down to thee (step by step), in truth, the Book, confirming what went before it; and He sent down the Law (of Moses) and the Gospel (of Jesus) before this, as a guide to mankind, and He sent down the criterion (of judgment between right and wrong).'),
  ('en.yusufali', 3, 4, 'Then those who reject Faith in the Signs of Allah will suffer the severest penalty, and Allah is Exalted in Might, Lord of Retribution.'),
  ('en.yusufali', 3, 5, 'From Allah, verily nothing is hidden on earth or in the heavens.'),
  ('en.yusufali', 3, 6, 'He it is Who shapes you in the wombs as He pleases. There is no god but He, the Exalted in Might, the Wise.'),
  ('en.yusufali', 3, 7, 'He it is Who has sent down to thee the Book: In it are verses basic or fundamental (of established meaning); they are the foundation of the Book: others are allegorical. But those in whose hearts is perversity follow the part thereof that is allegorical, seeking discord, and searching for its hidden meanings, but no one knows its hidden meanings except Allah. And those who are firmly grounded in knowledge say: "We believe in the Book; the whole of it is from our Lord:" and none will grasp the Message except men of understanding.'),
  ('en.yusufali', 3, 8, '"Our Lord!" (they say), "Let not our hearts deviate now after Thou hast guided us, but grant us mercy from Thine own Presence; for Thou art the Grantor of bounties without measure.'),
  ('en.yusufali', 3, 9, '"Our Lord! Thou art He that will gather mankind Together against a day about which there is no doubt; for Allah never fails in His promise."'),
  ('en.yusufali', 3, 10, 'Those who reject Faith,- neither their possessions nor their (numerous) progeny will avail them aught against Allah: They are themselves but fuel for the Fire.'),
  ('en.yusufali', 3, 11, '(Their plight will be) no better than that of the people of Pharaoh, and their predecessors: They denied our Signs, and Allah called them to account for their sins. For Allah is strict in punishment.'),
  ('en.yusufali', 3, 12, 'Say to those who reject Faith: "Soon will ye be vanquished and gathered together to Hell,-an evil bed indeed (to lie on)!'),
  ('en.yusufali', 3, 13, '"There has already been for you a Sign in the two armies that met (in combat): One was fighting in the cause of Allah, the other resisting Allah; these saw with their own eyes Twice their number. But Allah doth support with His aid whom He pleaseth. In this is a warning for such as have eyes to see."'),
  ('en.yusufali', 3, 14, 'Fair in the eyes of men is the love of things they covet: Women and sons; Heaped-up hoards of gold and silver; horses branded (for blood and excellence); and (wealth of) cattle and well-tilled land. Such are the possessions of this world\'s life; but in nearness to Allah is the best of the goals (To return to).'),
  ('en.yusufali', 3, 15, 'Say: Shall I give you glad tidings of things Far better than those? For the righteous are Gardens in nearness to their Lord, with rivers flowing beneath; therein is their eternal home; with companions pure (and holy); and the good pleasure of Allah. For in Allah\'s sight are (all) His servants,-'),
  ('en.yusufali', 3, 16, '(Namely), those who say: "Our Lord! we have indeed believed: forgive us, then, our sins, and save us from the agony of the Fire;"-'),
  ('en.yusufali', 3, 17, 'Those who show patience, Firmness and self-control; who are true (in word and deed); who worship devoutly; who spend (in the way of Allah); and who pray for forgiveness in the early hours of the morning.'),
  ('en.yusufali', 3, 18, 'There is no god but He: That is the witness of Allah, His angels, and those endued with knowledge, standing firm on justice. There is no god but He, the Exalted in Power, the Wise.'),
  ('en.yusufali', 3, 19, 'The Religion before Allah is Islam (submission to His Will): Nor did the People of the Book dissent therefrom except through envy of each other, after knowledge had come to them. But if any deny the Signs of Allah, Allah is swift in calling to account.'),
  ('en.yusufali', 3, 20, 'So if they dispute with thee, say: "I have submitted My whole self to Allah and so have those who follow me." And say to the People of the Book and to those who are unlearned: "Do ye (also) submit yourselves?" If they do, they are in right guidance, but if they turn back, Thy duty is to convey the Message; and in Allah\'s sight are (all) His servants.'),
  ('en.yusufali', 3, 21, 'As to those who deny the Signs of Allah and in defiance of right, slay the prophets, and slay those who teach just dealing with mankind, announce to them a grievous penalty.'),
  ('en.yusufali', 3, 22, 'They are those whose works will bear no fruit in this world and in the Hereafter nor will they have anyone to help.'),
  ('en.yusufali', 3, 23, 'Hast thou not turned Thy vision to those who have been given a portion of the Book? They are invited to the Book of Allah, to settle their dispute, but a party of them Turn back and decline (The arbitration).'),
  ('en.yusufali', 3, 24, 'This because they say: "The Fire shall not touch us but for a few numbered days": For their forgeries deceive them as to their own religion.'),
  ('en.yusufali', 3, 25, 'But how (will they fare) when we gather them together against a day about which there is no doubt, and each soul will be paid out just what it has earned, without (favour or) injustice?'),
  ('en.yusufali', 3, 26, 'Say: "O Allah! Lord of Power (And Rule), Thou givest power to whom Thou pleasest, and Thou strippest off power from whom Thou pleasest: Thou enduest with honour whom Thou pleasest, and Thou bringest low whom Thou pleasest: In Thy hand is all good. Verily, over all things Thou hast power.'),
  ('en.yusufali', 3, 27, '"Thou causest the night to gain on the day, and thou causest the day to gain on the night; Thou bringest the Living out of the dead, and Thou bringest the dead out of the Living; and Thou givest sustenance to whom Thou pleasest, without measure."'),
  ('en.yusufali', 3, 28, 'Let not the believers Take for friends or helpers Unbelievers rather than believers: if any do that, in nothing will there be help from Allah: except by way of precaution, that ye may Guard yourselves from them. But Allah cautions you (To remember) Himself; for the final goal is to Allah.'),
  ('en.yusufali', 3, 29, 'Say: "Whether ye hide what is in your hearts or reveal it, Allah knows it all: He knows what is in the heavens, and what is on earth. And Allah has power over all things.'),
  ('en.yusufali', 3, 30, '"On the Day when every soul will be confronted with all the good it has done, and all the evil it has done, it will wish there were a great distance between it and its evil. But Allah cautions you (To remember) Himself. And Allah is full of kindness to those that serve Him."'),
  ('en.yusufali', 3, 31, 'Say: "If ye do love Allah, Follow me: Allah will love you and forgive you your sins: For Allah is Oft-Forgiving, Most Merciful."'),
  ('en.yusufali', 3, 32, 'Say: "Obey Allah and His Messenger": But if they turn back, Allah loveth not those who reject Faith.'),
  ('en.yusufali', 3, 33, 'Allah did choose Adam and Noah, the family of Abraham, and the family of \'Imran above all people,-'),
  ('en.yusufali', 3, 34, 'Offspring, one of the other: And Allah heareth and knoweth all things.'),
  ('en.yusufali', 3, 35, 'Behold! a woman of \'Imran said: "O my Lord! I do dedicate unto Thee what is in my womb for Thy special service: So accept this of me: For Thou hearest and knowest all things."'),
  ('en.yusufali', 3, 36, 'When she was delivered, she said: "O my Lord! Behold! I am delivered of a female child!"- and Allah knew best what she brought forth- "And no wise is the male Like the female. I have named her Mary, and I commend her and her offspring to Thy protection from the Evil One, the Rejected."'),
  ('en.yusufali', 3, 37, 'Right graciously did her Lord accept her: He made her grow in purity and beauty: To the care of Zakariya was she assigned. Every time that he entered (Her) chamber to see her, He found her supplied with sustenance. He said: "O Mary! Whence (comes) this to you?" She said: "From Allah: for Allah Provides sustenance to whom He pleases without measure."'),
  ('en.yusufali', 3, 38, 'There did Zakariya pray to his Lord, saying: "O my Lord! Grant unto me from Thee a progeny that is pure: for Thou art He that heareth prayer!'),
  ('en.yusufali', 3, 39, 'While he was standing in prayer in the chamber, the angels called unto him: "Allah doth give thee glad tidings of Yahya, witnessing the truth of a Word from Allah, and (be besides) noble, chaste, and a prophet,- of the (goodly) company of the righteous."'),
  ('en.yusufali', 3, 40, 'He said: "O my Lord! How shall I have son, seeing I am very old, and my wife is barren?" "Thus," was the answer, "Doth Allah accomplish what He willeth."'),
  ('en.yusufali', 3, 41, 'He said: "O my Lord! Give me a Sign!" "Thy Sign," was the answer, "Shall be that thou shalt speak to no man for three days but with signals. Then celebrate the praises of thy Lord again and again, and glorify Him in the evening and in the morning."'),
  ('en.yusufali', 3, 42, 'Behold! the angels said: "O Mary! Allah hath chosen thee and purified thee- chosen thee above the women of all nations.'),
  ('en.yusufali', 3, 43, '"O Mary! worship Thy Lord devoutly: Prostrate thyself, and bow down (in prayer) with those who bow down."'),
  ('en.yusufali', 3, 44, 'This is part of the tidings of the things unseen, which We reveal unto thee (O Messenger!) by inspiration: Thou wast not with them when they cast lots with arrows, as to which of them should be charged with the care of Mary: Nor wast thou with them when they disputed (the point).'),
  ('en.yusufali', 3, 45, 'Behold! the angels said: "O Mary! Allah giveth thee glad tidings of a Word from Him: his name will be Christ Jesus, the son of Mary, held in honour in this world and the Hereafter and of (the company of) those nearest to Allah;'),
  ('en.yusufali', 3, 46, '"He shall speak to the people in childhood and in maturity. And he shall be (of the company) of the righteous."'),
  ('en.yusufali', 3, 47, 'She said: "O my Lord! How shall I have a son when no man hath touched me?" He said: "Even so: Allah createth what He willeth: When He hath decreed a plan, He but saith to it, \'Be,\' and it is!'),
  ('en.yusufali', 3, 48, '"And Allah will teach him the Book and Wisdom, the Law and the Gospel,'),
  ('en.yusufali', 3, 49, '"And (appoint him) a messenger to the Children of Israel, (with this message): "\'I have come to you, with a Sign from your Lord, in that I make for you out of clay, as it were, the figure of a bird, and breathe into it, and it becomes a bird by Allah\'s leave: And I heal those born blind, and the lepers, and I quicken the dead, by Allah\'s leave; and I declare to you what ye eat, and what ye store in your houses. Surely therein is a Sign for you if ye did believe;'),
  ('en.yusufali', 3, 50, '"\'(I have come to you), to attest the Law which was before me. And to make lawful to you part of what was (Before) forbidden to you; I have come to you with a Sign from your Lord. So fear Allah, and obey me.'),
  ('en.yusufali', 3, 51, '"\'It is Allah Who is my Lord and your Lord; then worship Him. This is a Way that is straight.\'"'),
  ('en.yusufali', 3, 52, 'When Jesus found Unbelief on their part He said: "Who will be My helpers to (the work of) Allah?" Said the disciples: "We are Allah\'s helpers: We believe in Allah, and do thou bear witness that we are Muslims.'),
  ('en.yusufali', 3, 53, '"Our Lord! we believe in what Thou hast revealed, and we follow the Messenger; then write us down among those who bear witness."'),
  ('en.yusufali', 3, 54, 'And (the unbelievers) plotted and planned, and Allah too planned, and the best of planners is Allah.'),
  ('en.yusufali', 3, 55, 'Behold! Allah said: "O Jesus! I will take thee and raise thee to Myself and clear thee (of the falsehoods) of those who blaspheme; I will make those who follow thee superior to those who reject faith, to the Day of Resurrection: Then shall ye all return unto me, and I will judge between you of the matters wherein ye dispute.'),
  ('en.yusufali', 3, 56, '"As to those who reject faith, I will punish them with terrible agony in this world and in the Hereafter, nor will they have anyone to help."'),
  ('en.yusufali', 3, 57, '"As to those who believe and work righteousness, Allah will pay them (in full) their reward; but Allah loveth not those who do wrong."'),
  ('en.yusufali', 3, 58, '"This is what we rehearse unto thee of the Signs and the Message of Wisdom."'),
  ('en.yusufali', 3, 59, 'The similitude of Jesus before Allah is as that of Adam; He created him from dust, then said to him: "Be". And he was.'),
  ('en.yusufali', 3, 60, 'The Truth (comes) from Allah alone; so be not of those who doubt.'),
  ('en.yusufali', 3, 61, 'If any one disputes in this matter with thee, now after (full) knowledge Hath come to thee, say: "Come! let us gather together,- our sons and your sons, our women and your women, ourselves and yourselves: Then let us earnestly pray, and invoke the curse of Allah on those who lie!"'),
  ('en.yusufali', 3, 62, 'This is the true account: There is no god except Allah; and Allah-He is indeed the Exalted in Power, the Wise.'),
  ('en.yusufali', 3, 63, 'But if they turn back, Allah hath full knowledge of those who do mischief.'),
  ('en.yusufali', 3, 64, 'Say: "O People of the Book! come to common terms as between us and you: That we worship none but Allah; that we associate no partners with him; that we erect not, from among ourselves, Lords and patrons other than Allah." If then they turn back, say ye: "Bear witness that we (at least) are Muslims (bowing to Allah\'s Will).'),
  ('en.yusufali', 3, 65, 'Ye People of the Book! Why dispute ye about Abraham, when the Law and the Gospel Were not revealed Till after him? Have ye no understanding?'),
  ('en.yusufali', 3, 66, 'Ah! Ye are those who fell to disputing (Even) in matters of which ye had some knowledge! but why dispute ye in matters of which ye have no knowledge? It is Allah Who knows, and ye who know not!'),
  ('en.yusufali', 3, 67, 'Abraham was not a Jew nor yet a Christian; but he was true in Faith, and bowed his will to Allah\'s (Which is Islam), and he joined not gods with Allah.'),
  ('en.yusufali', 3, 68, 'Without doubt, among men, the nearest of kin to Abraham, are those who follow him, as are also this Prophet and those who believe: And Allah is the Protector of those who have faith.'),
  ('en.yusufali', 3, 69, 'It is the wish of a section of the People of the Book to lead you astray. But they shall lead astray (Not you), but themselves, and they do not perceive!'),
  ('en.yusufali', 3, 70, 'Ye People of the Book! Why reject ye the Signs of Allah, of which ye are (Yourselves) witnesses?'),
  ('en.yusufali', 3, 71, 'Ye People of the Book! Why do ye clothe Truth with falsehood, and conceal the Truth, while ye have knowledge?'),
  ('en.yusufali', 3, 72, 'A section of the People of the Book say: "Believe in the morning what is revealed to the believers, but reject it at the end of the day; perchance they may (themselves) Turn back;'),
  ('en.yusufali', 3, 73, '"And believe no one unless he follows your religion." Say: "True guidance is the Guidance of Allah: (Fear ye) Lest a revelation be sent to someone (else) Like unto that which was sent unto you? or that those (Receiving such revelation) should engage you in argument before your Lord?" Say: "All bounties are in the hand of Allah: He granteth them to whom He pleaseth: And Allah careth for all, and He knoweth all things."'),
  ('en.yusufali', 3, 74, 'For His Mercy He specially chooseth whom He pleaseth; for Allah is the Lord of bounties unbounded.'),
  ('en.yusufali', 3, 75, 'Among the People of the Book are some who, if entrusted with a hoard of gold, will (readily) pay it back; others, who, if entrusted with a single silver coin, will not repay it unless thou constantly stoodest demanding, because, they say, "there is no call on us (to keep faith) with these ignorant (Pagans)." but they tell a lie against Allah, and (well) they know it.'),
  ('en.yusufali', 3, 76, 'Nay.- Those that keep their plighted faith and act aright,-verily Allah loves those who act aright.'),
  ('en.yusufali', 3, 77, 'As for those who sell the faith they owe to Allah and their own plighted word for a small price, they shall have no portion in the Hereafter: Nor will Allah (Deign to) speak to them or look at them on the Day of Judgment, nor will He cleans them (of sin): They shall have a grievous penalty.'),
  ('en.yusufali', 3, 78, 'There is among them a section who distort the Book with their tongues: (As they read) you would think it is a part of the Book, but it is no part of the Book; and they say, "That is from Allah," but it is not from Allah: It is they who tell a lie against Allah, and (well) they know it!'),
  ('en.yusufali', 3, 79, 'It is not (possible) that a man, to whom is given the Book, and Wisdom, and the prophetic office, should say to people: "Be ye my worshippers rather than Allah\'s": on the contrary (He would say) "Be ye worshippers of Him Who is truly the Cherisher of all: For ye have taught the Book and ye have studied it earnestly."'),
  ('en.yusufali', 3, 80, 'Nor would he instruct you to take angels and prophets for Lords and patrons. What! would he bid you to unbelief after ye have bowed your will (To Allah in Islam)?'),
  ('en.yusufali', 3, 81, 'Behold! Allah took the covenant of the prophets, saying: "I give you a Book and Wisdom; then comes to you a messenger, confirming what is with you; do ye believe in him and render him help." Allah said: "Do ye agree, and take this my Covenant as binding on you?" They said: "We agree." He said: "Then bear witness, and I am with you among the witnesses."'),
  ('en.yusufali', 3, 82, 'If any turn back after this, they are perverted transgressors.'),
  ('en.yusufali', 3, 83, 'Do they seek for other than the Religion of Allah?-while all creatures in the heavens and on earth have, willing or unwilling, bowed to His Will (Accepted Islam), and to Him shall they all be brought back.'),
  ('en.yusufali', 3, 84, 'Say: "We believe in Allah, and in what has been revealed to us and what was revealed to Abraham, Isma\'il, Isaac, Jacob, and the Tribes, and in (the Books) given to Moses, Jesus, and the prophets, from their Lord: We make no distinction between one and another among them, and to Allah do we bow our will (in Islam)."'),
  ('en.yusufali', 3, 85, 'If anyone desires a religion other than Islam (submission to Allah), never will it be accepted of him; and in the Hereafter He will be in the ranks of those who have lost (All spiritual good).'),
  ('en.yusufali', 3, 86, 'How shall Allah Guide those who reject Faith after they accepted it and bore witness that the Messenger was true and that Clear Signs had come unto them? but Allah guides not a people unjust.'),
  ('en.yusufali', 3, 87, 'Of such the reward is that on them (rests) the curse of Allah, of His angels, and of all mankind;-'),
  ('en.yusufali', 3, 88, 'In that will they dwell; nor will their penalty be lightened, nor respite be (their lot);-'),
  ('en.yusufali', 3, 89, 'Except for those that repent (Even) after that, and make amends; for verily Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 3, 90, 'But those who reject Faith after they accepted it, and then go on adding to their defiance of Faith,- never will their repentance be accepted; for they are those who have (of set purpose) gone astray.'),
  ('en.yusufali', 3, 91, 'As to those who reject Faith, and die rejecting,- never would be accepted from any such as much gold as the earth contains, though they should offer it for ransom. For such is (in store) a penalty grievous, and they will find no helpers.'),
  ('en.yusufali', 3, 92, 'By no means shall ye attain righteousness unless ye give (freely) of that which ye love; and whatever ye give, of a truth Allah knoweth it well.'),
  ('en.yusufali', 3, 93, 'All food was lawful to the Children of Israel, except what Israel Made unlawful for itself, before the Law (of Moses) was revealed. Say: "Bring ye the Law and study it, if ye be men of truth."'),
  ('en.yusufali', 3, 94, 'If any, after this, invent a lie and attribute it to Allah, they are indeed unjust wrong-doers.'),
  ('en.yusufali', 3, 95, 'Say: "Allah speaketh the Truth: follow the religion of Abraham, the sane in faith; he was not of the Pagans."'),
  ('en.yusufali', 3, 96, 'The first House (of worship) appointed for men was that at Bakka: Full of blessing and of guidance for all kinds of beings:'),
  ('en.yusufali', 3, 97, 'In it are Signs Manifest; (for example), the Station of Abraham; whoever enters it attains security; Pilgrimage thereto is a duty men owe to Allah,- those who can afford the journey; but if any deny faith, Allah stands not in need of any of His creatures.'),
  ('en.yusufali', 3, 98, 'Say: "O People of the Book! Why reject ye the Signs of Allah, when Allah is Himself witness to all ye do?"'),
  ('en.yusufali', 3, 99, 'Say: "O ye People of the Book! Why obstruct ye those who believe, from the path of Allah, Seeking to make it crooked, while ye were yourselves witnesses (to Allah\'s Covenant)? but Allah is not unmindful of all that ye do."'),
  ('en.yusufali', 3, 100, 'O ye who believe! If ye listen to a faction among the People of the Book, they would (indeed) render you apostates after ye have believed!'),
  ('en.yusufali', 3, 101, 'And how would ye deny Faith while unto you are rehearsed the Signs of Allah, and among you Lives the Messenger? Whoever holds firmly to Allah will be shown a way that is straight.'),
  ('en.yusufali', 3, 102, 'O ye who believe! Fear Allah as He should be feared, and die not except in a state of Islam.'),
  ('en.yusufali', 3, 103, 'And hold fast, all together, by the rope which Allah (stretches out for you), and be not divided among yourselves; and remember with gratitude Allah\'s favour on you; for ye were enemies and He joined your hearts in love, so that by His Grace, ye became brethren; and ye were on the brink of the pit of Fire, and He saved you from it. Thus doth Allah make His Signs clear to you: That ye may be guided.'),
  ('en.yusufali', 3, 104, 'Let there arise out of you a band of people inviting to all that is good, enjoining what is right, and forbidding what is wrong: They are the ones to attain felicity.'),
  ('en.yusufali', 3, 105, 'Be not like those who are divided amongst themselves and fall into disputations after receiving Clear Signs: For them is a dreadful penalty,-'),
  ('en.yusufali', 3, 106, 'On the Day when some faces will be (lit up with) white, and some faces will be (in the gloom of) black: To those whose faces will be black, (will be said): "Did ye reject Faith after accepting it? Taste then the penalty for rejecting Faith."'),
  ('en.yusufali', 3, 107, 'But those whose faces will be (lit with) white,- they will be in (the light of) Allah\'s mercy: therein to dwell (for ever).'),
  ('en.yusufali', 3, 108, 'These are the Signs of Allah: We rehearse them to thee in Truth: And Allah means no injustice to any of His creatures.'),
  ('en.yusufali', 3, 109, 'To Allah belongs all that is in the heavens and on earth: To Him do all questions go back (for decision).'),
  ('en.yusufali', 3, 110, 'Ye are the best of peoples, evolved for mankind, enjoining what is right, forbidding what is wrong, and believing in Allah. If only the People of the Book had faith, it were best for them: among them are some who have faith, but most of them are perverted transgressors.'),
  ('en.yusufali', 3, 111, 'They will do you no harm, barring a trifling annoyance; if they come out to fight you, they will show you their backs, and no help shall they get.'),
  ('en.yusufali', 3, 112, 'Shame is pitched over them (Like a tent) wherever they are found, except when under a covenant (of protection) from Allah and from men; they draw on themselves wrath from Allah, and pitched over them is (the tent of) destitution. This because they rejected the Signs of Allah, and slew the prophets in defiance of right; this because they rebelled and transgressed beyond bounds.'),
  ('en.yusufali', 3, 113, 'Not all of them are alike: Of the People of the Book are a portion that stand (For the right): They rehearse the Signs of Allah all night long, and they prostrate themselves in adoration.'),
  ('en.yusufali', 3, 114, 'They believe in Allah and the Last Day; they enjoin what is right, and forbid what is wrong; and they hasten (in emulation) in (all) good works: They are in the ranks of the righteous.'),
  ('en.yusufali', 3, 115, 'Of the good that they do, nothing will be rejected of them; for Allah knoweth well those that do right.'),
  ('en.yusufali', 3, 116, 'Those who reject Faith,- neither their possessions nor their (numerous) progeny will avail them aught against Allah: They will be companions of the Fire,-dwelling therein (for ever).'),
  ('en.yusufali', 3, 117, 'What they spend in the life of this (material) world May be likened to a wind which brings a nipping frost: It strikes and destroys the harvest of men who have wronged their own souls: it is not Allah that hath wronged them, but they wrong themselves.'),
  ('en.yusufali', 3, 118, 'O ye who believe! Take not into your intimacy those outside your ranks: They will not fail to corrupt you. They only desire your ruin: Rank hatred has already appeared from their mouths: What their hearts conceal is far worse. We have made plain to you the Signs, if ye have wisdom.'),
  ('en.yusufali', 3, 119, 'Ah! ye are those who love them, but they love you not,- though ye believe in the whole of the Book. When they meet you, they say, "We believe": But when they are alone, they bite off the very tips of their fingers at you in their rage. Say: "Perish in your rage; Allah knoweth well all the secrets of the heart."'),
  ('en.yusufali', 3, 120, 'If aught that is good befalls you, it grieves them; but if some misfortune overtakes you, they rejoice at it. But if ye are constant and do right, not the least harm will their cunning do to you; for Allah Compasseth round about all that they do.'),
  ('en.yusufali', 3, 121, 'Remember that morning Thou didst leave Thy household (early) to post the faithful at their stations for battle: And Allah heareth and knoweth all things:'),
  ('en.yusufali', 3, 122, 'Remember two of your parties Meditated cowardice; but Allah was their protector, and in Allah should the faithful (Ever) put their trust.'),
  ('en.yusufali', 3, 123, 'Allah had helped you at Badr, when ye were a contemptible little force; then fear Allah; thus May ye show your gratitude.'),
  ('en.yusufali', 3, 124, 'Remember thou saidst to the Faithful: "Is it not enough for you that Allah should help you with three thousand angels (Specially) sent down?'),
  ('en.yusufali', 3, 125, '"Yea, - if ye remain firm, and act aright, even if the enemy should rush here on you in hot haste, your Lord would help you with five thousand angels Making a terrific onslaught.'),
  ('en.yusufali', 3, 126, 'Allah made it but a message of hope for you, and an assurance to your hearts: (in any case) there is no help except from Allah. The Exalted, the Wise:'),
  ('en.yusufali', 3, 127, 'That He might cut off a fringe of the Unbelievers or expose them to infamy, and they should then be turned back, frustrated of their purpose.'),
  ('en.yusufali', 3, 128, 'Not for thee, (but for Allah), is the decision: Whether He turn in mercy to them, or punish them; for they are indeed wrong-doers.'),
  ('en.yusufali', 3, 129, 'To Allah belongeth all that is in the heavens and on earth. He forgiveth whom He pleaseth and punisheth whom He pleaseth; but Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 3, 130, 'O ye who believe! Devour not usury, doubled and multiplied; but fear Allah; that ye may (really) prosper.'),
  ('en.yusufali', 3, 131, 'Fear the Fire, which is repaired for those who reject Faith:'),
  ('en.yusufali', 3, 132, 'And obey Allah and the Messenger; that ye may obtain mercy.'),
  ('en.yusufali', 3, 133, 'Be quick in the race for forgiveness from your Lord, and for a Garden whose width is that (of the whole) of the heavens and of the earth, prepared for the righteous,-'),
  ('en.yusufali', 3, 134, 'Those who spend (freely), whether in prosperity, or in adversity; who restrain anger, and pardon (all) men;- for Allah loves those who do good;-'),
  ('en.yusufali', 3, 135, 'And those who, having done something to be ashamed of, or wronged their own souls, earnestly bring Allah to mind, and ask for forgiveness for their sins,- and who can forgive sins except Allah?- and are never obstinate in persisting knowingly in (the wrong) they have done.'),
  ('en.yusufali', 3, 136, 'For such the reward is forgiveness from their Lord, and Gardens with rivers flowing underneath,- an eternal dwelling: How excellent a recompense for those who work (and strive)!'),
  ('en.yusufali', 3, 137, 'Many were the Ways of Life that have passed away before you: travel through the earth, and see what was the end of those who rejected Truth.'),
  ('en.yusufali', 3, 138, 'Here is a plain statement to men, a guidance and instruction to those who fear Allah!'),
  ('en.yusufali', 3, 139, 'So lose not heart, nor fall into despair: For ye must gain mastery if ye are true in Faith.'),
  ('en.yusufali', 3, 140, 'If a wound hath touched you, be sure a similar wound hath touched the others. Such days (of varying fortunes) We give to men and men by turns: that Allah may know those that believe, and that He may take to Himself from your ranks Martyr-witnesses (to Truth). And Allah loveth not those that do wrong.'),
  ('en.yusufali', 3, 141, 'Allah\'s object also is to purge those that are true in Faith and to deprive of blessing Those that resist Faith.'),
  ('en.yusufali', 3, 142, 'Did ye think that ye would enter Heaven without Allah testing those of you who fought hard (In His Cause) and remained steadfast?'),
  ('en.yusufali', 3, 143, 'Ye did indeed wish for death before ye met him: Now ye have seen him with your own eyes, (And ye flinch!)'),
  ('en.yusufali', 3, 144, 'Muhammad is no more than a messenger: many Were the messenger that passed away before him. If he died or were slain, will ye then Turn back on your heels? If any did turn back on his heels, not the least harm will he do to Allah; but Allah (on the other hand) will swiftly reward those who (serve Him) with gratitude.'),
  ('en.yusufali', 3, 145, 'Nor can a soul die except by Allah\'s leave, the term being fixed as by writing. If any do desire a reward in this life, We shall give it to him; and if any do desire a reward in the Hereafter, We shall give it to him. And swiftly shall We reward those that (serve us with) gratitude.'),
  ('en.yusufali', 3, 146, 'How many of the prophets fought (in Allah\'s way), and with them (fought) Large bands of godly men? but they never lost heart if they met with disaster in Allah\'s way, nor did they weaken (in will) nor give in. And Allah Loves those who are firm and steadfast.'),
  ('en.yusufali', 3, 147, 'All that they said was: "Our Lord! Forgive us our sins and anything We may have done that transgressed our duty: Establish our feet firmly, and help us against those that resist Faith."'),
  ('en.yusufali', 3, 148, 'And Allah gave them a reward in this world, and the excellent reward of the Hereafter. For Allah Loveth those who do good.'),
  ('en.yusufali', 3, 149, 'O ye who believe! If ye obey the Unbelievers, they will drive you back on your heels, and ye will turn back (from Faith) to your own loss.'),
  ('en.yusufali', 3, 150, 'Nay, Allah is your protector, and He is the best of helpers.'),
  ('en.yusufali', 3, 151, 'Soon shall We cast terror into the hearts of the Unbelievers, for that they joined companions with Allah, for which He had sent no authority: their abode will be the Fire: And evil is the home of the wrong-doers!'),
  ('en.yusufali', 3, 152, 'Allah did indeed fulfil His promise to you when ye with His permission Were about to annihilate your enemy,-until ye flinched and fell to disputing about the order, and disobeyed it after He brought you in sight (of the booty) which ye covet. Among you are some that hanker after this world and some that desire the Hereafter. Then did He divert you from your foes in order to test you but He forgave you: For Allah is full of grace to those who believe.'),
  ('en.yusufali', 3, 153, 'Behold! ye were climbing up the high ground, without even casting a side glance at any one, and the Messenger in your rear was calling you back. There did Allah give you one distress after another by way of requital, to teach you not to grieve for (the booty) that had escaped you and for (the ill) that had befallen you. For Allah is well aware of all that ye do.'),
  ('en.yusufali', 3, 154, 'After (the excitement) of the distress, He sent down calm on a band of you overcome with slumber, while another band was stirred to anxiety by their own feelings, Moved by wrong suspicions of Allah-suspicions due to ignorance. They said: "What affair is this of ours?" Say thou: "Indeed, this affair is wholly Allah\'s." They hide in their minds what they dare not reveal to thee. They say (to themselves): "If we had had anything to do with this affair, We should not have been in the slaughter here." Say: "Even if you had remained in your homes, those for whom death was decreed would certainly have gone forth to the place of their death"; but (all this was) that Allah might test what is in your breasts and purge what is in your hearts. For Allah knoweth well the secrets of your hearts.'),
  ('en.yusufali', 3, 155, 'Those of you who turned back on the day the two hosts Met,-it was Satan who caused them to fail, because of some (evil) they had done. But Allah Has blotted out (their fault): For Allah is Oft-Forgiving, Most Forbearing.'),
  ('en.yusufali', 3, 156, 'O ye who believe! Be not like the Unbelievers, who say of their brethren, when they are travelling through the Earth or engaged in fighting: "If they had stayed with us, they would not have died, or been slain." This that Allah may make it a cause of sighs and regrets in their hearts. It is Allah that gives Life and Death, and Allah sees well all that ye do.'),
  ('en.yusufali', 3, 157, 'And if ye are slain, or die, in the way of Allah, forgiveness and mercy from Allah are far better than all they could amass.'),
  ('en.yusufali', 3, 158, 'And if ye die, or are slain, Lo! it is unto Allah that ye are brought together.'),
  ('en.yusufali', 3, 159, 'It is part of the Mercy of Allah that thou dost deal gently with them Wert thou severe or harsh-hearted, they would have broken away from about thee: so pass over (Their faults), and ask for (Allah\'s) forgiveness for them; and consult them in affairs (of moment). Then, when thou hast Taken a decision put thy trust in Allah. For Allah loves those who put their trust (in Him).'),
  ('en.yusufali', 3, 160, 'If Allah helps you, none can overcome you: If He forsakes you, who is there, after that, that can help you? in Allah, then, Let believers put their trust.'),
  ('en.yusufali', 3, 161, 'No prophet could (ever) be false to his trust. If any person is so false, He shall, on the Day of Judgment, restore what he misappropriated; then shall every soul receive its due,- whatever it earned,- and none shall be dealt with unjustly.'),
  ('en.yusufali', 3, 162, 'Is the man who follows the good pleasure of Allah Like the man who draws on himself the wrath of Allah, and whose abode is in Hell?- A woeful refuge!'),
  ('en.yusufali', 3, 163, 'They are in varying gardens in the sight of Allah, and Allah sees well all that they do.'),
  ('en.yusufali', 3, 164, 'Allah did confer a great favour on the believers when He sent among them a messenger from among themselves, rehearsing unto them the Signs of Allah, sanctifying them, and instructing them in Scripture and Wisdom, while, before that, they had been in manifest error.'),
  ('en.yusufali', 3, 165, 'What! When a single disaster smites you, although ye smote (your enemies) with one twice as great, do ye say?- "Whence is this?" Say (to them): "It is from yourselves: For Allah hath power over all things."'),
  ('en.yusufali', 3, 166, 'What ye suffered on the day the two armies Met, was with the leave of Allah, in order that He might test the believers,-'),
  ('en.yusufali', 3, 167, 'And the Hypocrites also. These were told: "Come, fight in the way of Allah, or (at least) drive (The foe from your city)." They said: "Had we known how to fight, we should certainly have followed you." They were that day nearer to Unbelief than to Faith, saying with their lips what was not in their hearts but Allah hath full knowledge of all they conceal.'),
  ('en.yusufali', 3, 168, '(They are) the ones that say, (of their brethren slain), while they themselves sit (at ease): "If only they had listened to us they would not have been slain." Say: "Avert death from your own selves, if ye speak the truth."'),
  ('en.yusufali', 3, 169, 'Think not of those who are slain in Allah\'s way as dead. Nay, they live, finding their sustenance in the presence of their Lord;'),
  ('en.yusufali', 3, 170, 'They rejoice in the bounty provided by Allah: And with regard to those left behind, who have not yet joined them (in their bliss), the (Martyrs) glory in the fact that on them is no fear, nor have they (cause to) grieve.'),
  ('en.yusufali', 3, 171, 'They glory in the Grace and the bounty from Allah, and in the fact that Allah suffereth not the reward of the Faithful to be lost (in the least).'),
  ('en.yusufali', 3, 172, 'Of those who answered the call of Allah and the Messenger, even after being wounded, those who do right and refrain from wrong have a great reward;-'),
  ('en.yusufali', 3, 173, 'Men said to them: "A great army is gathering against you": And frightened them: But it (only) increased their Faith: They said: "For us Allah sufficeth, and He is the best disposer of affairs."'),
  ('en.yusufali', 3, 174, 'And they returned with Grace and bounty from Allah: no harm ever touched them: For they followed the good pleasure of Allah: And Allah is the Lord of bounties unbounded.'),
  ('en.yusufali', 3, 175, 'It is only the Evil One that suggests to you the fear of his votaries: Be ye not afraid of them, but fear Me, if ye have Faith.'),
  ('en.yusufali', 3, 176, 'Let not those grieve thee who rush headlong into Unbelief: Not the least harm will they do to Allah: Allah\'s plan is that He will give them no portion in the Hereafter, but a severe punishment.'),
  ('en.yusufali', 3, 177, 'Those who purchase Unbelief at the price of faith,- not the least harm will they do to Allah, but they will have a grievous punishment.'),
  ('en.yusufali', 3, 178, 'Let not the Unbelievers think that our respite to them is good for themselves: We grant them respite that they may grow in their iniquity: But they will have a shameful punishment.'),
  ('en.yusufali', 3, 179, 'Allah will not leave the believers in the state in which ye are now, until He separates what is evil from what is good nor will He disclose to you the secrets of the Unseen. But He chooses of His Messengers (For the purpose) whom He pleases. So believe in Allah. And His messengers: And if ye believe and do right, ye have a reward without measure.'),
  ('en.yusufali', 3, 180, 'And let not those who covetously withhold of the gifts which Allah Hath given them of His Grace, think that it is good for them: Nay, it will be the worse for them: soon shall the things which they covetously withheld be tied to their necks Like a twisted collar, on the Day of Judgment. To Allah belongs the heritage of the heavens and the earth; and Allah is well-acquainted with all that ye do.'),
  ('en.yusufali', 3, 181, 'Allah hath heard the taunt of those who say: "Truly, Allah is indigent and we are rich!"- We shall certainly record their word and (their act) of slaying the prophets in defiance of right, and We shall say: "Taste ye the penalty of the Scorching Fire!'),
  ('en.yusufali', 3, 182, '"This is because of the (unrighteous deeds) which your hands sent on before ye: For Allah never harms those who serve Him."'),
  ('en.yusufali', 3, 183, 'They (also) said: "Allah took our promise not to believe in an messenger unless He showed us a sacrifice consumed by Fire (From heaven)." Say: "There came to you messengers before me, with clear Signs and even with what ye ask for: why then did ye slay them, if ye speak the truth?"'),
  ('en.yusufali', 3, 184, 'Then if they reject thee, so were rejected messengers before thee, who came with Clear Signs, Books of dark prophecies, and the Book of Enlightenment.'),
  ('en.yusufali', 3, 185, 'Every soul shall have a taste of death: And only on the Day of Judgment shall you be paid your full recompense. Only he who is saved far from the Fire and admitted to the Garden will have attained the object (of Life): For the life of this world is but goods and chattels of deception.'),
  ('en.yusufali', 3, 186, 'Ye shall certainly be tried and tested in your possessions and in your personal selves; and ye shall certainly Hear much that will grieve you, from those who received the Book before you and from those who worship many gods. But if ye persevere patiently, and guard against evil,-then that will be a determining factor in all affairs.'),
  ('en.yusufali', 3, 187, 'And remember Allah took a covenant from the People of the Book, to make it known and clear to mankind, and not to hide it; but they threw it away behind their backs, and purchased with it some miserable gain! And vile was the bargain they made!'),
  ('en.yusufali', 3, 188, 'Think not that those who exult in what they have brought about, and love to be praised for what they have not done,- think escape the penalty. For them is a penalty Grievous indeed.'),
  ('en.yusufali', 3, 189, 'To Allah belongeth the dominion of the heavens and the earth; and Allah hath power over all things.'),
  ('en.yusufali', 3, 190, 'Behold! in the creation of the heavens and the earth, and the alternation of night and day,- there are indeed Signs for men of understanding,-'),
  ('en.yusufali', 3, 191, 'Men who celebrate the praises of Allah, standing, sitting, and lying down on their sides, and contemplate the (wonders of) creation in the heavens and the earth, (With the thought): "Our Lord! not for naught Hast Thou created (all) this! Glory to Thee! Give us salvation from the penalty of the Fire.'),
  ('en.yusufali', 3, 192, '"Our Lord! any whom Thou dost admit to the Fire, Truly Thou coverest with shame, and never will wrong-doers Find any helpers!'),
  ('en.yusufali', 3, 193, '"Our Lord! we have heard the call of one calling (Us) to Faith, \'Believe ye in the Lord,\' and we have believed. Our Lord! Forgive us our sins, blot out from us our iniquities, and take to Thyself our souls in the company of the righteous.'),
  ('en.yusufali', 3, 194, '"Our Lord! Grant us what Thou didst promise unto us through Thine messengers, and save us from shame on the Day of Judgment: For Thou never breakest Thy promise."'),
  ('en.yusufali', 3, 195, 'And their Lord hath accepted of them, and answered them: "Never will I suffer to be lost the work of any of you, be he male or female: Ye are members, one of another: Those who have left their homes, or been driven out therefrom, or suffered harm in My Cause, or fought or been slain,- verily, I will blot out from them their iniquities, and admit them into Gardens with rivers flowing beneath;- A reward from the presence of Allah, and from His presence is the best of rewards."'),
  ('en.yusufali', 3, 196, 'Let not the strutting about of the Unbelievers through the land deceive thee:'),
  ('en.yusufali', 3, 197, 'Little is it for enjoyment: Their ultimate abode is Hell: what an evil bed (To lie on)!'),
  ('en.yusufali', 3, 198, 'On the other hand, for those who fear their Lord, are Gardens, with rivers flowing beneath; therein are they to dwell (for ever),- a gift from the presence of Allah; and that which is in the presence of Allah is the best (bliss) for the righteous.'),
  ('en.yusufali', 3, 199, 'And there are, certainly, among the People of the Book, those who believe in Allah, in the revelation to you, and in the revelation to them, bowing in humility to Allah: They will not sell the Signs of Allah for a miserable gain! For them is a reward with their Lord, and Allah is swift in account.'),
  ('en.yusufali', 3, 200, 'O ye who believe! Persevere in patience and constancy; vie in such perseverance; strengthen each other; and fear Allah; that ye may prosper.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 3, 1, 'Alif-Laam-Meeem'),
  ('en.transliteration', 3, 2, 'Allaahu laaa ilaaha illaa Huwal Haiyul Qaiyoom'),
  ('en.transliteration', 3, 3, 'Nazzala \'alaikal Kitaaba bilhaqqi musaddiqal limaa baina yadaihi wa anzalat Tawraata wal Injeel'),
  ('en.transliteration', 3, 4, 'Min qablu hudal linnaasi wa anzalal Furqaan; innallazeena kafaroo bi Aayaatil laahi lahum \'azaabun shadeed; wallaahu \'azeezun zun tiqaam'),
  ('en.transliteration', 3, 5, 'Innal laaha laa yakhfaa \'alaihi shai\'un fil ardi wa laa fis samaaa\''),
  ('en.transliteration', 3, 6, 'Huwal lazee yusawwirukum fil arhaami kaifa yashaaa\'; laa ilaaha illaa Huwal \'Azeezul Hakeem'),
  ('en.transliteration', 3, 7, 'Huwal lazeee anzala \'alaikal Kitaaba minhu Aayaatum Muh kamaatun hunna Ummul Kitaabi wa ukharu Mutashaabihaatun faammal lazeena fee quloobihim ziyghun fa yattabi\'oona ma tashaabaha minhubtighaaa \'alfitnati wabtighaaa\'a taaweelih; wa maa ya\'lamu taaweelahooo illal laah; warraasikhoona fil \'ilmi yaqooloona aamannaa bihee kullum min \'indi Rabbinaa; wa maa yazzakkaru illaaa ulul albaab'),
  ('en.transliteration', 3, 8, 'Rabbanaa laa tuzigh quloobanaa ba\'da iz hadaitanaa wa hab lanaa mil ladunka rahmah; innaka antal Wahhaab'),
  ('en.transliteration', 3, 9, 'Rabbanaaa innaka jaami \'un-naasi li Yawmil laa raibafeeh; innal laaha laa yukhliful mee\'aad'),
  ('en.transliteration', 3, 10, 'Innal lazeena kafaroo lan tughniya \'anhum amwaaluhum wa laaa awlaaduhum minal laahi shai\'anw wa ulaaa\'ika hum waqoodun Naar'),
  ('en.transliteration', 3, 11, 'Kadaabi Aali Fir\'awna wallazeena min qablihim; kazzaboo bi Aayaatinaa fa akhazahumul laahu bizunoo bihim; wallaahu shadeedul \'iqaab'),
  ('en.transliteration', 3, 12, 'Qul lillazeena kafaroosatughlaboona wa tuhsharoona ilaa jahannam; wa bi\'sal mihaad'),
  ('en.transliteration', 3, 13, 'Qad kaana lakum Aayatun fee fi\'atainil taqataa fi\'atun tuqaatilu fee sabeelil laahi wa ukhraa kaafiratuny yarawnahum mislaihim raayal \'ayn; wallaahu yu\'ayyidu bi nasrihee mai yashaaa\'; innaa fee zaalika la \'ibratal li ulil absaar'),
  ('en.transliteration', 3, 14, 'Zuyyina linnaasi hubbush shahawaati minannisaaa\'i wal baneena walqanaateeril muqantarati minaz zahabi walfiddati walkhailil musawwamati wal an\'aami walhars; zaalika mataa\'ul hayaatid dunyaa wallaahu \'indahoo husnul ma-aab'),
  ('en.transliteration', 3, 15, 'Qul a\'unabbi \'ukum bikhairim min zaalikum; lillazeenat taqaw \'inda Rabbihim jannaatun tajree min tahtihal anhaaru khaalideena feehaa wa azwaajum mutahharatunw wa ridwaanum minal laah; wallaahu baseerum bil\'ibaad'),
  ('en.transliteration', 3, 16, 'Allazeena yaqooloona Rabbanaaa innanaaa aamannaa faghfir lanaa zunoobanaa wa qinaa \'azaaban Naar'),
  ('en.transliteration', 3, 17, 'Assaabireena wassaa diqeena walqaaniteena walmunfiqeena walmus taghfireena bil ashaar'),
  ('en.transliteration', 3, 18, 'Shahidal laahu annahoo laa ilaaha illaa Huwa walmalaaa\'ikatu wa ulul \'ilmi qaaa\'imam bilqist; laaa ilaaha illaa Huwal \'Azeezul Hakeem'),
  ('en.transliteration', 3, 19, 'Innad deena \'indal laahil Islaam; wa makhtalafal lazeena ootul Kitaaba illaa mim ba\'di maa jaaa\'ahumul \'ilmu baghyam bainahum; wa mai yakfur bi Aayaatil laahi fa innal laaha saree\'ul hisaab'),
  ('en.transliteration', 3, 20, 'Fa in haaajjooka faqul aslamtu wajhiya lillaahi wa manit taba\'an; wa qul lillazeena ootul Kitaaba wal ummiyyeena \'a-aslamtum; fa in aslamoo faqadih tadaw wa in tawallaw fa innamaa \'alaikal balaagh; wallaahu baseerum bil \'ibaad'),
  ('en.transliteration', 3, 21, 'Innal lazeena yakfuroona bi Aayaatil laahi wa yaqtuloonan Nabiyyeena bighairi haqqinw wa yaqtuloonal lazeena yaamuroona bilqisti minannaasi fabashirhum bi\'azaabin aleem'),
  ('en.transliteration', 3, 22, 'Ulaaa\'ikal lazeena habitat a\'maaluhum fid dunyaa wal Aaakhirati wa maa lahum min naasireen'),
  ('en.transliteration', 3, 23, 'Alam tara ilal lazeena ootoo naseebam minal Kitaabi yud\'awna ilaa Kitaabil laahi liyahkuma bainahum summa yatawallaa fareequm minhum wa hum mu\'ridoon'),
  ('en.transliteration', 3, 24, 'Zaalika bi annahum qaaloo lan tamassanan naaru illaaa ayyaamam ma\'doodaatinw wa gharrahum fee deenihim maa kaanoo yaftaroon'),
  ('en.transliteration', 3, 25, 'Fakaifa izaa jama\'naahum li Yawmil laa raiba fee wa wuffiyat kullu nafsim maa kasabat wa hum laa yuzlamoon'),
  ('en.transliteration', 3, 26, 'Qulil laahumma Maalikal Mulki tu\'til mulka man tashaaa\'u wa tanzi\'ulmulka mimman tashhaaa\'u wa tu\'izzu man tashaaa\'u wa tuzillu man tashaaa\'u biyadikal khairu innaka \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 3, 27, 'Toolijul laila fin nahaari wa toolijun nahaara fil laili wa tukhrijul haiya minalmaiyiti wa tukhrijulo maiyita minal haiyi wa tarzuqu man tashaaa\'u bighari hisab'),
  ('en.transliteration', 3, 28, 'Laa yattakhizil mu\'minoonal kaafireena awliyaaa\'a min doonil mu\'mineena wa mai yaf\'al zaalika falaisa minal laahi fee shai\'in illaaa an tattaqoo minhum tuqaah; wa yuhazzirukumul laahu nafsah; wa ilal laahil maseer'),
  ('en.transliteration', 3, 29, 'Qul in tukhfoo maa fee sudoorikum aw tubdoohu ya\'lamhul laah; wa ya\'lamu maa fis samaawaati wa maa fil ard; wallaahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 3, 30, 'Yawma tajidu kullu nafsim maa\'amilat min khairim muhdaranw wa maa \'amilat min sooo\'in tawaddu law anna bainahaa wa bainahooo amadam ba\'eedaa; wa yuhazzirukumul laahu nafsah; wallaahu ra\'oofum bil\'ibaad'),
  ('en.transliteration', 3, 31, 'Qul in kuntum tuhibboonal laaha fattabi\' oonee yuhbibkumul laahu wa yaghfir lakum zunoobakum; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 3, 32, 'Qul atee\'ul laaha war Rasoola fa in tawallaw fa innal laaha laa yuhibbul kaafireen'),
  ('en.transliteration', 3, 33, 'Innal laahas tafaaa Aadama wa Noohanw wa Aala Ibraaheema wa Aala Imraana \'alal \'aalameen'),
  ('en.transliteration', 3, 34, 'Zurriyyatam ba\'duhaa mim ba\'d; wallaahu Samee\'un \'Aleem'),
  ('en.transliteration', 3, 35, 'Iz qaalatim ra atu \'Imraana Rabbi innee nazartu laka maa fee batnee muharraran fataqabbal minnee innaka Antas Samee\'ul \'Aleem'),
  ('en.transliteration', 3, 36, 'Falammaa waqa\'athaa qaalat Rabbi innee wada\'tuhaaa unsaa wallaahu a\'lamu bimaa wada\'at wa laisaz zakaru kalunsaa wa innee sammaituhaa Maryama wa innee u\'eezuhaa bika wa zurriyyatahaa minash Shaitaanir Rajeem'),
  ('en.transliteration', 3, 37, 'Fataqabbalahaa Rabbuhaa biqaboolin hasaninw wa ambatahaa nabaatan hasananw wa kaffalahaa Zakariyyaa kullamaa dakhala \'alaihaa Zakariyyal Mihraaba wajada \'indahaa rizqan qaala yaa Maryamu annaa laki haazaa qaalat huwa min \'indil laahi innal laaha yarzuqu mai yashaaa\'u bighairi hisaab'),
  ('en.transliteration', 3, 38, 'Hunaaalika da\'aa Zakariyyaa Rabbahoo qaala Rabbi hab lee mil ladunka zurriyyatan taiyibatan innaka samee\'ud du\'aaa\''),
  ('en.transliteration', 3, 39, 'Fanaadat hul malaaa\'ikatu wa huwa qaaa\'imuny yusallee fil Mihraabi annal laaha yubashshiruka bi Yahyaa musaddiqam bi Kalimatim minal laahi wa saiyidanw wa hasooranw wa Nabiyyam minas saaliheen'),
  ('en.transliteration', 3, 40, 'Qaala Rabbi annaa yakoonu lee ghulaamunw wa qad balaghaniyal kibaru wamraatee \'aaqirun qaala kazaalikal laahu yaf\'alu maa yashaaa\''),
  ('en.transliteration', 3, 41, 'Qaala Rabbij \'al leee Aayatan qaala Aaayatuka allaa tukalliman naasa salaasata ayyaamin illa ramzaa; wzkur Rabbaka kaseeranw wa sabbih bil\'ashiyyi wal ibkaar'),
  ('en.transliteration', 3, 42, 'Wa iz qaalatil malaaa\'ikatu yaa Ya Maryamu innal laahas tafaaki wa tahharaki wastafaaki \'alaa nisaaa\'il \'aalameen'),
  ('en.transliteration', 3, 43, 'Yaa Maryamuq nutee li Rabbiki wasjudee warka\'ee ma\'ar raaki\'een'),
  ('en.transliteration', 3, 44, 'Zaalika min ambaaa\'il ghaibi nooheehi ilaik; wa maa kunta ladaihim iz yulqoona aqlaamahum ayyuhum yakfulu Maryama wa maa kunta ladaihim iz yakhtasimoon'),
  ('en.transliteration', 3, 45, 'Iz qaalatil malaaa\'ikatu yaa Maryamu innal laaha yubashshiruki bi Kalimatim minhus muhul Maseeh u \'Eesab nu Maryama wajeehan fid dunyaa wal Aakhirati wa minal muqarrabeen'),
  ('en.transliteration', 3, 46, 'Wa yukallimun naasa filmahdi wa kahlanw wa minassaaliheen'),
  ('en.transliteration', 3, 47, 'Qaalat Rabbi annaa yakoonu ee waladunw wa lam yamsasnee basharun qaala kazaalikil laahu yakhluqu maa yashaaa\'; izaa qadaaa amran fa innamaa yaqoolu lahoo kun fayakoon'),
  ('en.transliteration', 3, 48, 'Wa yu\'allimuhul Kitaaba wal Hikmata wat Tawraata wal Injeel'),
  ('en.transliteration', 3, 49, 'Wa Rasoolan ilaa Baneee Israaa\'eela annee qad ji\'tukum bi Aayatim mir Rabbikum annee akhluqu lakum minatteeni kahai \'atittairi fa anfukhu feehi fayakoonu tairam bi iznil laahi wa ubri\'ul akmaha wal abrasa wa uhyil mawtaa bi iznil laahi wa unabbi\'ukum bimaa taakuloona wa maa taddakhiroona fee buyootikum; inna fee zaalika la Aayatal lakum in kuntum mu\'mineen'),
  ('en.transliteration', 3, 50, 'Wa musaddiqal limaa baina yadaiya minat Tawraati wa liuhilla lakum ba\'dal lazee hurrima \'alaikum; wa ji\'tukum bi Aayatim mir Rabbikum fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 3, 51, 'Innal laaha Rabbee wa Rabbukum fa\'budooh; haazaa Siraatum Mustaqeem'),
  ('en.transliteration', 3, 52, 'Falammaaa ahassa \'Eesaa minhumul kufra qaala man ansaaree ilal laahi qaalal Hawaariyyoona nahnu ansaarul laahi aamannaa billaahi washhad bi annaa muslimoon'),
  ('en.transliteration', 3, 53, 'Rabbanaaa aamannaa bimaaa anzalta wattaba\'nar Rasoola faktubnaa ma\'ash shaahideen'),
  ('en.transliteration', 3, 54, 'Wa makaroo wa makaral laahu wallaahu khairul maakireen'),
  ('en.transliteration', 3, 55, 'Iz qaalal laahu yaa \'Eesaaa innee mutawaffeeka wa raafi\'uka ilaiya wa mutah hiruka minal lazeena kafaroo wa jaa\'ilul lazeenattaba ooka fawqal lazeena kafarooo ilaa Yawmil Qiyaamati summa ilaiya marji\'ukum fa ahkumu bainakum feemaa kuntum feehi takhtaliifoon'),
  ('en.transliteration', 3, 56, 'Fa ammal lazeena kafaroo fa u\'az zibuhum \'azaaban shadeedan fiddunyaa wal Aakhirati wa maa lahum min naasireen'),
  ('en.transliteration', 3, 57, 'Wa ammal lazeena aamanoo wa \'amilus saalihaati fa yuwaffeehim ujoorahum; wallaahu laa yuhibbuz zaalimeen'),
  ('en.transliteration', 3, 58, 'Zaalika natloohu \'alaika minal Aayaati wa Zikril Hakeem'),
  ('en.transliteration', 3, 59, 'Inna masala \'Eesaa \'indal laahi kamasali Aadama khalaqahoo min turaabin summa qaala lahoo kun fayakoon'),
  ('en.transliteration', 3, 60, 'Alhaqqu mir Rabbika falaa takum minal mumtareen'),
  ('en.transliteration', 3, 61, 'Faman haaajjaka feehi mim ba\'di maa jaaa\'aka minal \'ilmi faqul ta\'aalaw nad\'u abnaaa\'anaa wa abnaaa\'akum wa nisaaa\'anaa wa nisaaa\'akum wa anfusanaa wa anfusakum summa nabtahil fanaj\'al la\'natal laahi \'alal kaazibeen'),
  ('en.transliteration', 3, 62, 'Innaa haazaa lahuwal qasasul haqq; wa maa min ilaahin illal laah; wa innal laahaa la Huwal \'Azeezul Hakeem'),
  ('en.transliteration', 3, 63, 'Fa in tawallaw fa innal laaha\'aleemun bil mufsideen'),
  ('en.transliteration', 3, 64, 'Qul yaa Ahlal Kitaabi ta\'aalaw ilaa Kalimatin sawaaa\'im bainanaa wa bainakum allaa na\'buda illal laaha wa laa nushrika bihee shai\'anw wa laa yattakhiza ba\'dunaa ba\'dan arbaabam min doonil laah; fa in tawallaw faqoolush hadoo bi annaa muslimoon'),
  ('en.transliteration', 3, 65, 'Yaaa Ahlal Kitaabi limaa tuhaaajjoona feee Ibraaheema wa maaa unzilatit Tawraatu wal Injeelu illaa mim ba\'dih; afala ta\'qiloon'),
  ('en.transliteration', 3, 66, 'Haaa antum haaa\'ulaaa\'i baajajtum feemaa lakum bihee \'ilmun falima tuhaaajjoonaa feemaa laisa lakum bihee \'ilm; wallaahu ya\'lamu wa antum laa ta\'lamoon'),
  ('en.transliteration', 3, 67, 'Maa kaana Ibraaheemu Yahoodiyyanw wa laa Nasraa niyyanw wa laakin kaana Haneefam Muslimanw wa maa kaana minal mushrikeen'),
  ('en.transliteration', 3, 68, 'Innaa awlan naasi bi Ibraaheema lallazeenat taba \'oohu wa haazan nabiyyu wallazeena aamanoo; wallaahu waliyyul mu\'mineen'),
  ('en.transliteration', 3, 69, 'Waddat taaa\'ifatum min Ahlil Kitaabi law yudil loonakum wa maa yudilloona illaaa anfusahum wa maa yash\'uroon'),
  ('en.transliteration', 3, 70, 'Yaaa Ahlal Kitaabi lima takfuroona bi Aayaatil laahi wan antum tashadoon'),
  ('en.transliteration', 3, 71, 'Yaaa Ahalal Kitaabi lima talbisoonal haqqa bilbaatili wa taktumoonal haqqa wa antum ta\'lamoon'),
  ('en.transliteration', 3, 72, 'Wa qaalat taaa\'ifatum min Ahlil Kitaabi aaminoo billazeee unzila \'alal lazeena aamanoo wajhan nahaari wakfurooo aakhirahoo la\'alla hum yarji\'oon'),
  ('en.transliteration', 3, 73, 'Wa laa tu\'minooo illaa liman tabi\'a deenakum qul innal hudaa hudal laahi ai yu\'taaa ahadum misla maaa ooteetum aw yuhaaajjookum \'inda Rabbikum, qul innal fadla biyadil laah; yu\'teehi mai yashaaa\'; wallaahu Waasi\'un \'Aleem'),
  ('en.transliteration', 3, 74, 'Yakhtassu birahmatihee mai yashaaa\'; wallaahu zulfadil \'azeem'),
  ('en.transliteration', 3, 75, 'Wa min Ahlil Kitaabi man in taamanhu biqintaariny yu\'addihee ilaika wa minhum man in taamanhu bideenaaril laa yu\'addiheee ilaika illaa maa dumta \'alaihi qaaa\' imaa; zaalika biannahum qaaloo laisa \'alainaa fil ummiyyeena sabeelunw wa yaqooloona \'alal laahil kaziba wa hum ya\'lamoon'),
  ('en.transliteration', 3, 76, 'Balaa man awfaa bi\'ahdihee wattaqaa fainnal laaha yuhibbul muttaqeen'),
  ('en.transliteration', 3, 77, 'Innal lazeena yashtaroona bi\'ahdil laahi wa aymaanihim samanan qaleelan ulaaa\'ika laa khalaaqa lahum fil Aakhirati wa laa yukallimuhumul laahu wa laa yanzuru ilaihim Yawmal Qiyaamati wa laa yuzakkeehim wa lahum \'azabun \'aleem'),
  ('en.transliteration', 3, 78, 'Wa inna minhum lafaree qany yalwoona alsinatahum bil Kitaabi litahsaboohu minal Kitaab, wa maa huwa minal Kitaabi wa yaqooloon huwa min \'indillaahi wa maa huwa min \'indillaahi wa yaqooloona \'alal laahil kaziba wa hum ya\'lamoon'),
  ('en.transliteration', 3, 79, 'Maa kaana libasharin ai yu\'tiyahul laahul Kitaaba walhukma wan Nubuwwata summa yaqoola linnaasi koonoo \'ibaadal lee min doonil laahi wa laakin koonoo rabbaaniy yeena bimaa kuntum tu\'allimoonal Kitaaba wa bimaa kuntum tadrusoon'),
  ('en.transliteration', 3, 80, 'Wa laa yaamurakum an tattakhizul malaaa \'ikata wan Nabiyyeena arbaabaa; a yaamurukum bilkufri ba\'da iz antum muslimoon'),
  ('en.transliteration', 3, 81, 'Wa iz akhazal laahu meesaaqan Nabiyyeena lamaaa aataitukum min Kitaabinw wa Hikmatin summa jaaa\'akum Rasoolum musaddiqul limaa ma\'akum latu\'minunna bihee wa latansurunnah; qaala \'aaqrartum wa akhaztum alaa zaalikum isree qaalooo aqrarnaa; qaala fashhadoo wa ana ma\'akum minash shaahideen'),
  ('en.transliteration', 3, 82, 'Faman tawallaa ba\'da zaalika fa ulaaa\'ika humul faasiqoon'),
  ('en.transliteration', 3, 83, 'Afaghaira deenil laahi yabghoona wa lahooo aslama man fis samaawaati wal ardi taw\'anw wa karhanw wa ilaihi yurja\'oon'),
  ('en.transliteration', 3, 84, 'Qul aamannaa billaahi wa maaa unzila \'alainaa wa maaa unzila \'alaaa Ibraaheema wa Ismaa\'eela wa Ishaaqa wa Ya\'qooba wal Asbaati wa maaa ootiya Moosaa wa \'Eesaa wan Nabiyyoona mir Rabbihim laa nufarriqu baina ahadim minhum wa nahnu lahoo muslimoon'),
  ('en.transliteration', 3, 85, 'Wa mai yabtaghi ghairal Islaami deenan falany yuqbala minhu wa huwa fil Aakhirati minal khaasireen'),
  ('en.transliteration', 3, 86, 'Kaifa yahdil laahu qawman kafaroo ba\'da eemaanihim wa shahidooo annar Rasoola haqqunw wa jaaa\'ahumul baiyinaat; wallaahu laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 3, 87, 'Ulaaa\'ika jazaaa\'uhum anna \'alaihim la\'natal laahi walmalaaa\'ikati wannaasi ajma\'een'),
  ('en.transliteration', 3, 88, 'Khaalideena feehaa laa yukhaffafu \'anhumul \'azaabu wa laa hum yunzaroon'),
  ('en.transliteration', 3, 89, 'Illal lazeena taaboo mim ba\'di zaalika wa aslahoo fa innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 3, 90, 'Innal lazeena kafaroo ba\'da eemaanihim summaz daadoo kufral lan tuqbala tawbatuhum wa ulaaa\'ika humud daaalloon'),
  ('en.transliteration', 3, 91, 'Innal lazeena kafaroo wa maatoo wa hum kuffaarun falany yuqbala min ahadihim mil\'ul ardi zahabanw wa lawiftadaa bih; ulaaa \'ika lahum \'azaabun aleemunw wa maa lahum min naasireen'),
  ('en.transliteration', 3, 92, 'Lan tanaalul birra hattaa tunfiqoo mimmaa tuhibboon; wa maa tunfiqoo min shai\'in fa innal laaha bihee \'Aleem'),
  ('en.transliteration', 3, 93, 'Kullut ta\'aami kaana hillal li Baneee Israaa\'eela illaa maa harrama Israaa\'eelu \'alaa nafsihee min qabli an tunzzalat Tawraah; qul faatoo bit Tawraati fatloohaaa in kuntum saadiqeen'),
  ('en.transliteration', 3, 94, 'Famanif taraa \'alal laahilkaziba mim ba\'di zaalika fa ulaaa\'ika humuz zaalimoon'),
  ('en.transliteration', 3, 95, 'Qul sadaqal laah; fattabi\'oo Millata Ibraaheema Haneefanw wa maa kaana minal mush rikeen'),
  ('en.transliteration', 3, 96, 'Inna awwala Baitinw wudi\'a linnaasi lallazee bi Bakkata mubaarakanw wa hudal lil \'aalameen'),
  ('en.transliteration', 3, 97, 'Feehi Aayaatum baiyinaatum Maqaamu Ibraaheema wa man dakhalahoo kaana aaminaa; wa lillaahi \'alan naasi Hijjul Baiti manis tataa\'a ilaihi sabeelaa; wa man kafara fa innal laaha ghaniyyun \'anil \'aalameen'),
  ('en.transliteration', 3, 98, 'Qul yaaa Ahlal Kitaabi lima takfuroona bi Aayaatillaahi wallaahu shaheedun \'alaa maa ta\'maloon'),
  ('en.transliteration', 3, 99, 'Qul yaaa Ahlal Kitaabi lima tusuddoona \'an sabeelil laahi man aamana tabghoonahaa \'iwajanw wa antum shuhadaaa\'; wa mallaahu bighaafilin \'ammaa ta\'maloon'),
  ('en.transliteration', 3, 100, 'Yaaa ayyuhal lazeena aamanoo in tutee\'oo fareeqam minal lazeena ootul Kitaaba yaruddookum ba\'da eemaanikum kaafireen'),
  ('en.transliteration', 3, 101, 'Wa kaifa takfuroona wa antum tutlaa \'alaikum Aayaatul laahi wa feekum Rasooluh; wa mai ya\'tasim baillaahi faqad hudiya ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 3, 102, 'Yaaa ayyuhal lazeena aamanut taqul laaha haqqa tuqaatihee wa laa tamoontunna illaa wa antum muslimoon'),
  ('en.transliteration', 3, 103, 'Wa\'tasimoo bi Hablil laahi jamee\'anw wa laa tafarraqoo; wazkuroo ni\'matal laahi alaikum iz kuntum a\'daaa\'an fa allafa baina quloobikum fa asbah tum bini\'matiheee ikhwaananw wa kuntum \'alaa shafaa hufratim minan Naari fa anqazakum minhaa; kazaalika yubaiyinul laahu lakum aayaatihee la\'allakum tahtadoon'),
  ('en.transliteration', 3, 104, 'Waltakum minkum ummatuny yad\'oona ilal khairi wa yaamuroona bilma \'roofi wa yanhawna \'anil munkar; wa ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 3, 105, 'Wa laa takoonoo kallazeena tafarraqoo wakhtalafoo mim ba\'di maa jaaa\'ahumul baiyinaat; wa ulaaa\'ika lahum \'azaabun \'azeem'),
  ('en.transliteration', 3, 106, 'Yawma tabyaddu wujoohunw wa taswaddu wujooh; faammal lazeenas waddat wujoohum akafartum ba\'da eemaanikum fazooqul \'azaaba bimaa kuntum takfuroon'),
  ('en.transliteration', 3, 107, 'Wa ammal lazeenabyadd at wujoohuhum fafee rahmatil laahi hum feehaa khaalidoon'),
  ('en.transliteration', 3, 108, 'Tilka Aayaatul laahi natloohaa \'alaika bilhaqq; wa mal laahu yureedu zulmallil \'aalameen'),
  ('en.transliteration', 3, 109, 'Wa lillaahi maa fissamaawaati wa maa fil ard; wa ilal laahi turja;ul umoor'),
  ('en.transliteration', 3, 110, 'Kuntum khaira ummatin ukhrijat linnaasi taamuroona bilma\'roofi wa tanhawna \'anil munkari wa tu\'minoona billaah; wa law aamana Ahlul Kitaabi lakaana khairal lahum minhumul mu\'minoona wa aksaruhumul faasiqoon'),
  ('en.transliteration', 3, 111, 'Lai yadurrookum \'illaaa azanw wa ai yuqaatilookum yuwallookumul adbaara summa laa yunsaroon'),
  ('en.transliteration', 3, 112, 'Duribat \'alaihimuz zillatu aina maa suqifooo illaa bihablim minal laahi wa hablim minan naasi wa baaa\'oo bighadabim minallaahi wa duribat \'alaihimul maskanah; zaalika bi-annahum kaanoo yakfuroona bi Aayaatil laahi wa yaqtuloonal Ambiyaaa\'a bighairi haqq; zaalika bimaa \'asaw wa kaanoo ya\'tadoon'),
  ('en.transliteration', 3, 113, 'Laisoo sawaaa\'a; min Ahlil Kitaabi ummatun qaaa\'imatuny yatloona Aayaatil laahi aanaaa\'al laili wa hum yasjudoon'),
  ('en.transliteration', 3, 114, 'Yu\'minoona billaahi wal Yawmil Aakhiri wa yaa muroona bilma\'roofi wa yanhawna \'anil munkari wa yusaari\'oona fil khairaati wa ulaa\'ika minas saaliheen'),
  ('en.transliteration', 3, 115, 'Wa maa yaf\'aloo min khairin falai yukfarooh; wallaahu \'aleemun bilmuttaqeen'),
  ('en.transliteration', 3, 116, 'Innal lazeena kafaroo lan tughniya \'anhum amwaalum wa laaa awlaaduhum minal laahi shai anw wa ulaaa\'ika Ashaabun Naar; hum feehaa khaalidoon'),
  ('en.transliteration', 3, 117, 'Masalu maa yunfiqoona fee haazihil hayaatid dunyaa kamasali reehin feehaa sirrun as aabat harsa qawmin zalamooo anfusahum fa ahlakath; wa maa zalamahumul laahu wa laakin anfusahum yazlimoon'),
  ('en.transliteration', 3, 118, 'Yaaa ayyuhal lazeena aamanoo laa tattakhizoo bitaanatam min doonikum laa yaaloonakum khabaalanw waddoo maa \'anittum qad badatil baghdaaa\'u min afwaahihim; wa maa tukhfee sudooruhum akbar; qad baiyannaa lakumul Aayaati in kuntum ta\'qiloon'),
  ('en.transliteration', 3, 119, 'Haaa antum ulaaa\'i tuhibboonahum wa laa yuhibboonakum wa tu\'minoona bil kitaabi kullihee wa izaa laqookum qaalooo aamannaa wa izaa khalaw \'addoo \'alaikumul anaamila minal ghaiz; qul mootoo bighai zikum; innal laaha \'aleemum bizaatis sudoor'),
  ('en.transliteration', 3, 120, 'In tamsaskum hasanatun tasu\'hum wa in tusibkum saiyi\'atuny yafrahoo bihaa wa in tasbiroo wa tattaqoo laa yad urrukum kaiduhum shai\'aa; innal laaha bimaa ya\'maloona muheet'),
  ('en.transliteration', 3, 121, 'Wa iz ghadawta min ahlika tubawwi\'ul mu\'mineena maqaa\'ida lilqitaal; wallaahu samee\'un \'aleem'),
  ('en.transliteration', 3, 122, 'Iz hammat taaa\'ifataani minkum an tafshalaa wallaahu waliyyuhumaa; wa \'alal laahi falyatawakkalil mu\'minoon'),
  ('en.transliteration', 3, 123, 'Wa laqad nasarakumul laahu bi-Badrinw wa antum azillatun fattaqul laaha la\'allakum tashkuroon'),
  ('en.transliteration', 3, 124, 'Iz taqoolu lilmu\'mineena alai yakfiyakum ai-yumiddakum Rabbukum bisalaasati aalaafim minal malaaa\'ikati munzaleen'),
  ('en.transliteration', 3, 125, 'Balaaa; in tasbiroo wa tattaqoo wa yaatookum min fawrihim haazaa yumdidkum Rabbukum bikhamsati aalaafim minal malaaa\'ikati musawwaimeen'),
  ('en.transliteration', 3, 126, 'Wa maa ja\'alahul laahu illaa bushraa lakum wa litatma\'inna quloobukum bih\' wa man-nasru illaa min \'indilllaahil \'Azeezil Hakeem'),
  ('en.transliteration', 3, 127, 'Laiyaqta\'a tarafam minal lazeena kafarooo aw yakbitahum fayanqaliboo khaaa\'ibeen'),
  ('en.transliteration', 3, 128, 'Laisa laka minal amrishai\'un aw yatooba \'alaihim aw yu\'az zi bahum fa innahum zaalimoon'),
  ('en.transliteration', 3, 129, 'Wa lilaahi maa fissamaawaati wa maa fil-ard; yaghfiru limai-yashaaa\'u wa yu\'azzibu mai-yashaaa\'; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 3, 130, 'Yaaa ayyuhal lazeena aamanoo la taakuhur ribaaa ad\'aafam mudaa\'afatanw wattaqul laaha la\'allakum tuflihoon'),
  ('en.transliteration', 3, 131, 'Wattaqun Naaral lateee u\'iddat lilkaafireen'),
  ('en.transliteration', 3, 132, 'Wa atee\'ul laaha war Rasoola la\'allakum turhamoon'),
  ('en.transliteration', 3, 133, 'Wa saari\'ooo ilaa maghfiratim mir Rabbikum wa Jannatin arduhassamaawaatu wal ardu u\'iddat lilmuttaqeen'),
  ('en.transliteration', 3, 134, 'Allazeena yunfiqoona fissarraaa\'i waddarraaa\'i wal kaazimeenal ghaiza wal aafeena \'anin-naas; wallaahu yuhibbul muhsineen'),
  ('en.transliteration', 3, 135, 'Wallazeena izaa fa\'aloo faahishatan aw zalamooo anfusahum zakarul laaha fastaghfaroo lizunoobihim; wa mai yaghfiruz zunooba illal laahu wa lam yusirroo \'alaa maa fa\'aloo wa hum ya\'lamooo'),
  ('en.transliteration', 3, 136, 'Ulaaa\'ika jazaaa\'uhum maghfiratum mir Rabbihim wa Jannaatun tajree min tahtihal anhaaru khaalideena feeha; wa ni\'ma ajrul \'aamileen'),
  ('en.transliteration', 3, 137, 'Qad khalat min qablikum sunanum faseeroo fil ardi fanzuroo kaifa kaana \'aaqiba tul mukazzibeen'),
  ('en.transliteration', 3, 138, 'Haazaa bayaanul linnaasi wa hudanw wa maw\'izatul lilmuttaqeen'),
  ('en.transliteration', 3, 139, 'Wa laa tahinoo wa laa tahzanoo wa antumul a\'lawna in kuntum mu\'mineen'),
  ('en.transliteration', 3, 140, 'Iny-yamsaskum qarhum faqad massal qawma qarhum misluh; wa tilkal ayyaamu nudaawiluhaa bainan naasi wa liya\'lamal laahul lazeena aamanoo wa yattakhiza minkum shuhadaaa\'; wallaahu laa yuh ibbuz zaalimeen'),
  ('en.transliteration', 3, 141, 'Wa liyumahhisal laahul lazeena aamanoo wa yamhaqal kaafireen'),
  ('en.transliteration', 3, 142, 'Am hasibtum an tadkhulul Jannnata wa lammaa ya\'lamil laahul lazeena jaahadoo minkum wa ya\'lamas saabireen'),
  ('en.transliteration', 3, 143, 'Wa laqad kuntum tamannnawnal mawta min qabli an talqawhu faqad ra aitumoohu wa antum tanzuroon'),
  ('en.transliteration', 3, 144, 'Wa maa Muhammadun illaa Rasoolun qad khalat min qablihir Rusul; afa\'im maata aw qutilan qalabtum \'alaaa a\'qaabikum; wa mai yanqalib \'alaa aqibihi falai yadurral laaha shai\'aa; wa sayajzil laahush shaakireen'),
  ('en.transliteration', 3, 145, 'Wa maa kaana linafsin an tamoota illaa bi iznillaahi kitaabam mu\'ajjalaa; wa mai yurid sawaabad dunyaa nu\'tihee minhaa wa mai yurid sawaabal Aakhirati nu\'tihee minhaa; wa sanajzish shaakireen'),
  ('en.transliteration', 3, 146, 'Wa ka aiyim min Nabiyyin qaatala ma\'ahoo ribbiyyoona kaseerun famaa wahanoo limaaa Asaabahum fee sabeelil laahi wa maa da\'ufoo wa mas takaanoo; wallaahu yuhibbus saabireen'),
  ('en.transliteration', 3, 147, 'Wa maa kaana qawlahum illaa an qaaloo Rabbanagh fir lanaa zunoobanaa wa israafanaa feee amirnaa wa sabbit aqdaamanaa wansurnaa \'alal qawmil kaafireen'),
  ('en.transliteration', 3, 148, 'Fa aataahumul laahu sawaabad dunyaa wa husna sawaabil Aakhirah; wallaahu yuhibbul muhsineen'),
  ('en.transliteration', 3, 149, 'Yaaa \'aiyuhal lazeena aamanoo in tutee\'ullazeena kafaroo yaruddookum \'alaaa a\'qaabkum fatanqaliboo khaasireen'),
  ('en.transliteration', 3, 150, 'Balil laahu mawlaakum wa Huwa khairun naasireen'),
  ('en.transliteration', 3, 151, 'Sanulqee fee quloobil lazeena kafarur ru\'ba bimaaa ashrakoo billaahi maa lam yunazzil bihee sultaana-nw wa maawaahumun Naar; wa bi\'sa maswaz zaalimeen'),
  ('en.transliteration', 3, 152, 'Wa laqad sadaqakumul laahu wa\'dahooo iz tahussoo nahum bi iznihee hattaaa izaa fashiltim wa tanaaza\'tum fil amri wa \'asaitum mim ba\'di maaa araakum maa tuhibboon; minkum mai yureedud dunyaa wa minkum mai yureedul Aakhirah; summa sarafakum \'anhum sarafakum \'anhum liyabtaliyakum wa laqad \'afaa \'ankum; wallaahu zoo fadlin \'alal mu\'mineen'),
  ('en.transliteration', 3, 153, 'Iz tus\'idoona wa laa talwoona \'alaaa ahadinw war Rasoolu yad\'ookum feee ukhraakum fa asaabakum ghammam bighammil likailaa tahzanoo \'alaa maa faatakum wa laa maaa asaabakum; wallaahu khabeerum bimaa ta\'maloon'),
  ('en.transliteration', 3, 154, 'Summa anzala \'alaikum mim ba\'dil ghammi amanatan nu\'aasai yaghshaa taaa\' ifatam minkum wa taaa\'ifatun qad ahammathum anfusuhum yazunnoona billaahi ghairal haqqi zannal jaahiliyyati yaqooloona hal lanaa minal amri min shai\'; qul innal amra kullahoo lillaah; yukhfoona fee anfusihim maa laa yubdoona laka yaqooloona law kaana lanaa minal amri shai\'ummaa qutilnaa haahunaa; qul law kuntum fee buyootikum labarazal lazeena kutiba \'alaihimul qatlu ilaa madaaji\'ihim wa liyabtaliyal laahu maa fee sudoorikum wa liyumah hisa maa fee quloobikum; wallaahu \'aleemum bizaatis sudoor'),
  ('en.transliteration', 3, 155, 'Innal lazeena tawallaw minkum yawmal taqal jam\'aani innamas tazallahumush Shaitaanu biba\'di maa kasaboo wa laqad \'afal laahu \'anhum; innnal laaha Ghafoorum Haleem'),
  ('en.transliteration', 3, 156, 'Yaaa ayyuhul lazeena aamanoo laa takoonoo kallazeena kafaroo wa qaaloo li ikhwaanihim izaa daraboo fil ardi aw kaanoo ghuzzal law kaanoo \'indanaa maa maatoo wa maa qutiloo liyaj\'alal laahu zaalika hasratan fee quloobihim; qallaahu yuhyee wa yumeet; wallaahu bimaa ta\'maloona Baseer'),
  ('en.transliteration', 3, 157, 'Wa la\'in qutiltum fee sabeelil laahi aw muttum lamaghfiratum minal laahi wa rahmatun khairum mimmaa yajma\'oon'),
  ('en.transliteration', 3, 158, 'Wa la\'im muttum \'aw qutiltumla ilal laahi tuhsharoon'),
  ('en.transliteration', 3, 159, 'Fabimaa rahmatim minal laahi linta lahum wa law kunta fazzan ghaleezal qalbi lanfaddoo min hawlika fafu \'anhum wastaghfir lahum wa shaawirhum fil amri fa izaa \'azamta fatawakkal \'alal laah; innallaaha yuhibbul mutawak kileen'),
  ('en.transliteration', 3, 160, 'Iny-yansurkumul laahu falaa ghaaliba lakum wa iny-yakhzulkum faman zal lazee yansurukum mim ba\'dih; wa \'alal laahi falyatawakkalil mu\'minoon'),
  ('en.transliteration', 3, 161, 'Wa maa kaana li Nabiyyin ai yaghull; wa mai yaghlul yaati bimaa ghalla Yawmal Qiyaamah; summa tuwaffaa kullu nafsim maa kasabat wa hum laa yuzlamoon'),
  ('en.transliteration', 3, 162, 'Afamanit taba\'a Ridwaanal laahi kamam baaa\'a bisakhatim minal laahi wa maawaahu Jahannam; wa bi\'sal maseer'),
  ('en.transliteration', 3, 163, 'Hum darajaatun \'indal laah; wallaahu baseerum bimaa ya\'maloon'),
  ('en.transliteration', 3, 164, 'Laqad mannal laahu \'alal mu\'mineena iz ba\'asa feehim Rasoolam min anfusihim yatloo \'alaihim Aayaatihee wa yuzakkeehim wa yu\'allimu humul Kitaaba wal Hikmata wa in kaanoo min qablu lafee dalaalim mubeen'),
  ('en.transliteration', 3, 165, 'Awa lammaaa asaabatkum museebatun qad asabtum mislaihaa qultum annaa haazaa qul huwa min \'indi anfusikum; innal laaha \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 3, 166, 'Wa maa asaabakum yawmal taqal jam\'aani fabiiznil laahi wa liya\'lamal mu\'mineen'),
  ('en.transliteration', 3, 167, 'Wa liya\'lamal lazeena naafaqoo; wa qeela lahum ta\'aalaw qaatiloo fee sabeelil laahi awid fa\'oo qaaloo law na\'lamu qitaalallat taba\'naakum; hum lilkufri yawma\'izin aqrabu minhum lil eemaan; yaqooloona bi afwaahihim maa laisa fee quloobihim; wallaahu a\'lamu bimaa yaktumoon'),
  ('en.transliteration', 3, 168, 'Allazeena qaaloo liikhwaanihim wa qa\'adoo law ataa\'oonaa maa qutiloo; qul fadra\'oo\'an anfusikumul mawta in kuntum saadiqeen'),
  ('en.transliteration', 3, 169, 'Wa laa tahsabannal lazeena qutiloo fee sabeelillaahi amwaata; bal ahyaaa\'un \'inda Rabbihim yurzaqoon'),
  ('en.transliteration', 3, 170, 'Fariheena bimaaa aataa humul laahu min fadlihee wa yastabshiroona billazeena lam yalhaqoo bihim min fadlihee wa yastabshiroona billazeena lam yalhaqoo bihim min khalfihim allaa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 3, 171, 'Yastabshiroona bini\'matim minal laahi wa fad linw wa annal laaha laa yudee\'u ajral mu\'mineen'),
  ('en.transliteration', 3, 172, 'Allazeenas tajaaboo lil laahi war Rasooli mim ba\'di maaa asaabahumulqarh; lillazeena ahsanoo minhum wattaqaw ajrun \'azeem'),
  ('en.transliteration', 3, 173, 'Allazeena qaala lahumun naasu innan naasa qad jama\'oo lakum fakhshawhuin fazaadahum eemaannanwa wa qaaloo hasbunal laahu wa ni\'malwakeel'),
  ('en.transliteration', 3, 174, 'Fanqalaboo bini\'matim minal laahi wa fadlil lam yamsashum sooo\'unw wattaba\'oo ridwaanal laah; wallaahu zoo fadlin \'azeem'),
  ('en.transliteration', 3, 175, 'Innamaa zaalikumush Shaitaanu yukhawwifu awliyaaa\'ahoo falaa takhaafoohum wa khaafooni in kuntum mu\'mineen'),
  ('en.transliteration', 3, 176, 'Wa laa yahzunkal lazeena yusaari\'oona fil Kufr; innahum lai yadurrul laaha shai\'aa; yureedul laahu allaa yaj\'ala lahum hazzan fil Aakhirati wa lahum \'azaabun \'azeem'),
  ('en.transliteration', 3, 177, 'Innal lazeenash tarawul kufra bil eemaani lai yadurrul laaha shai anw wa lahum \'azdaabun aleem'),
  ('en.transliteration', 3, 178, 'Wa laa yahsabannal lazeena kafarooo annamaa numlee lahum khairulli anfusihim; innamaa numlee lahum liyazdaadooo ismaa wa lahum \'azaabum muheen'),
  ('en.transliteration', 3, 179, 'Maa kaanal laahu liyazaral mu\'mineena \'alaa maaa antum \'alaihi hattaa yameezal khabeesa minat taiyib; wa maa kaanal laahu liyutli\'akum \'alal ghaibi wa laakinnal laaha yajtabee mir Rusulihii mai yashaaa\'u fa aaminoo billaahi wa Rusulih; wa in tu \'minoo wa tattaqoo falakum ajrun \'azeem'),
  ('en.transliteration', 3, 180, 'Wa laa yahsabannal lazeena yabkhaloon bimaa aataahumul lahu min fadilhee huwa khairal lahum bal huwa sharrul lahum sayutaw waqoona maa bakhiloo bihee Yawmal Qiyaamah; wa lillaahi meeraasus samaawaati wal ard; wallaahu bimaa ta\'maloona Khabeer'),
  ('en.transliteration', 3, 181, 'Laqad sami\'al laahu qawlal lazeena qaalooo innal laaha faqeerunw wa nahnu aghniyaaa\'; sanaktubu maa qaaloo wa qatlahumul Ambiyaa\'a bighairi haqqinw wa naqoolu zooqoo \'azaaba Ihreeq'),
  ('en.transliteration', 3, 182, 'Zaalika bimaa qaddamat aideekum wa annal laaha laisa bizallaamil lil\'abeed'),
  ('en.transliteration', 3, 183, 'Allazeena qaalooo innal laaha \'ahida ilainaaa allaa nu\'mina liRasoolin hatta yaa tiyanaa biqurbaanin taa kuluhun naar; qul qad jaaa\'akum Rusulum min qablee bilbaiyinaati wa billazee qultum falima qataltumoohum in kuntum saadiqeen'),
  ('en.transliteration', 3, 184, 'Fa in kaz zabooka faqad kuz ziba Rusulum min qablika jaaa\'oo bilbaiyinaati waz Zuburi wal Kitaabil Muneer'),
  ('en.transliteration', 3, 185, 'Kulu nafsin zaaa\'iqatul mawt; wa innamaa tuwaffawna ujoorakum Yawmal Qiyaamati faman zuhziha \'anin Naari waudkhilal Jannata faqad faaz; wa mal hayaatud dunyaaa illaa mataa\'ul ghuroor'),
  ('en.transliteration', 3, 186, 'Latublawunna feee amwaalikum wa anfusikum wa latasma\'unna minal lazeena ootul Kitaaba min qablikum wa minal lazeena ashrakooo azan kaseeraa; wa in tasbiroo wa tattaqoo fa inna zaalika min \'azmil umoor'),
  ('en.transliteration', 3, 187, 'Wa iz akhazal laahu meesaaqal lazeena ootul Kitaaba latubaiyinunnahoo linnaasi wa laa taktumoona hoo fanabazoohu waraaa\'a zuhoorihim washtaraw bihee samanan qaleelan fabi\'sa maa yashtaroon'),
  ('en.transliteration', 3, 188, 'Laa tahsabannal lazeena yafrahoona bimaaa ataw wa yuhibbona ai yuhmadoo bimaa lam yaf\'aloo falaa tahsabunnahum bimafaazatim minal \'azaabi wa lahum \'azaabun aleem'),
  ('en.transliteration', 3, 189, 'Wa lillaahi mulkus samaawaati wal ard; wallaahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 3, 190, 'Inna fee khalqis samaawati wal ardi wakhtilaafil laili wannahaari la Aayaatil liulil albaab'),
  ('en.transliteration', 3, 191, 'Allazeena yazkuroonal laaha qiyaamaiw-wa qu\'oodanw-wa \'alaa juno obihim wa yatafakkaroona fee khalqis samaawaati wal ardi Rabbanaa maa khalaqta haaza baatilan Subhaanak faqinaa \'azaaban Naar'),
  ('en.transliteration', 3, 192, 'Rabbanaaa innaka man tudkhilin Naara faqad akhzai tahoo wa maa lizzaalimeena min ansaar'),
  ('en.transliteration', 3, 193, 'Rabbanaaa innanaa sami\'naa munaadiyai yunaadee lil eemaani an aaminoo bi Rabbikum fa aamannaa; Rabbanaa faghfir lanaa zunoobanaa wa kaffir \'annaa saiyi aatina wa tawaffanaa ma\'al abraar'),
  ('en.transliteration', 3, 194, 'Rabbanaa wa aatinaa maa wa\'attanaa \'alaa Rusulika wa laa tukhzinaa Yawmal Qiyaamah; innaka laa tukhliful mee\'aad'),
  ('en.transliteration', 3, 195, 'Fastajaaba lahum Rabbuhum annee laaa Udee\'u \'amala \'aamilim minkum min zakarin aw unsaa ba\'dukum mim ba\'din fal lazeena haajaroo wa ukhrijoo min diyaarihim wa oozoo fee sabeelee wa qaataloo wa qutiloo la ukaffiranna \'anhum saiyi aatihim wa la udkhilanna hum Jannnatin tajree min tahtihal anhaaru sawaabam min \'indil laah; wallaahu \'indahoo husnus sawaab'),
  ('en.transliteration', 3, 196, 'Laa yaghurrannaka taqal lubul lazeena kafaroo fil bilaad'),
  ('en.transliteration', 3, 197, 'Mataa\'un qaleelun summa maawaahum Jahannam; wa bi\'sal mihaad'),
  ('en.transliteration', 3, 198, 'Laakinil lazeenat taqaw Rabbahum lahum Jannnaatun tajree min tahtihal anhaaru khaalideena feehaa nuzulammin \'indil laah; wa maa \'indal laahi khairul lil abraar'),
  ('en.transliteration', 3, 199, 'Wa inna min Ahlil Kitaabi lamai yu minu billaahi wa maaa unzila ilaikum wa maaa unzila ilaihim khaashi \'eena lillaahi laa yashtaroona bi Aayaatil laahi samanan qaleelaa; ulaaa\'ika lahum ajruhum \'inda Rabbihim; innal laaha saree\'ul hisaab'),
  ('en.transliteration', 3, 200, 'Yaaa aiyuhal lazeena aamanus biroo wa saabiroo wa raabitoo wattaqul laaha la\'allakum tuflihoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 3, 1, 'المۤ'),
  ('ur.ahmedali', 3, 2, 'الله اس کے سوا کوئی معبود نہیں زندہ ہے نظام کائنات کا سنبھالنے والا ہے'),
  ('ur.ahmedali', 3, 3, 'اس نے تجھ پر یہ سچی کتاب نازل فرمائی جو پہلی کتابوں کی تصدیق کرتی ہے اور اسی نے اس کتاب سے پہلے تورات اور انجیل نازل فرمائی'),
  ('ur.ahmedali', 3, 4, 'وہ کتابیں لوگوں کے لیے راہ نما ہیں اور اسی نے فیصلہ کن چیزیں نازل فرمائیں بے شک جو لوگ الله کی آیتوں سے منکر ہوئے ان کے لیے سخت عذاب ہے اور الله تعالیٰ زبردست بدلہ دینے والا ہے'),
  ('ur.ahmedali', 3, 5, 'الله پر زمین اور آسمان میں کوئی چیز چھپی ہوئی نہیں'),
  ('ur.ahmedali', 3, 6, 'وہی جس طرح چاہے ماں کے پیٹ میں تمہارا نقشہ بناتا ہے اس کے سوا اور کوئی معبود نہیں زبردست حکمت والا ہے'),
  ('ur.ahmedali', 3, 7, 'وہی ہے جس نے تجھ پر کتاب اتاری اس میں بعض آیتیں محکم ہیں (جن کے معنیٰ واضح ہیں) وہ کتاب کی اصل ہیں اور دوسری مشابہ ہیں (جن کے معنیٰ معلوم یا معین نہیں) سو جن لوگو ں کے دل ٹیڑھے ہیں وہ گمراہی پھیلانے کی غرض سے اور مطلب معلوم کرنے کی غرض سے متشابہات کے پیچھے لگتے ہیں اور حالانکہ ان کا مطلب سوائے الله کے اور کوئی نہیں جانتا اور مضبوط علم والے کہتے ہیں ہمارا ان چیزوں پر ایمان ہے یہ سب ہمارے رب کی طرف سے ہیں اور نصیحت وہی لوگ مانتے ہیں جو عقلمند ہیں'),
  ('ur.ahmedali', 3, 8, 'اے رب ہمارے! جب تو ہم کو ہدایت کر چکا تو ہمارے دلوں کا نہ پھیر اور اپنے ہاں سے ہمیں رحمت عطافرما بے شک تو بہت زیادہ دینے والا ہے'),
  ('ur.ahmedali', 3, 9, 'اے ہمارے رب! توایک دن سب لوگوں کو جمع کرنے والا ہے جس میں کوئی شک نہیں بے شک الله اپنے وعدہ کا خلاف نہیں کرتا'),
  ('ur.ahmedali', 3, 10, 'بے شک جو لوگ کافر ہیں ان کے مال او ران کی اولاد الله کے مقابلے میں ہر گز کام نہیں آئیں گے اوروہ لوگ دوزخ کا ایندھن ہیں'),
  ('ur.ahmedali', 3, 11, 'جس طرح فرعون والوں اور ان سے پہلے لوگوں کا معاملہ تھا انہوں نے ہماری نشانیوں کو جھٹلایا پھر الله نے ان کے گناہوں کے سبب سے انہیں پکڑا اور الله سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 3, 12, 'کافروں کو کہہ دے کہ اب تم مغلوب ہو گئے اور دوزخ کی طرف اکھٹے کیے جاؤ گے اوروہ برا ٹھکانہ ہے'),
  ('ur.ahmedali', 3, 13, 'تمہارے سامنے ایک نمونہ دو فوجوں کا گزر چکا ہے جو آپس میں ملیں ایک فوج الله کی راہ میں لڑتی ہے اور دوسری فوج کافروں کی ہے وہ کافر مسلمانوں کو اپنے سے دوگنا دیکھ رہے تھے آنکھوں کے دیکھنے سے اور االله جسے چاہے اپنی مدد سے قوت دیتا ہے اس واقعہ میں دیکھنے والوں کے لیے عبرت ہے'),
  ('ur.ahmedali', 3, 14, 'لوگوں کو مرغوب چیزوں کی محبت نے فریفتہ کیا ہوا ہے جیسے عورتیں اور بیٹے اور سونے اور چاندی کے جمع کیے ہوئے خزانے اور نشان کیے ہوئے گھوڑے اور مویشی اور کھیتی یہ دنیا کی زندگی کا فائدہ ہے اور الله ہی کے پاس اچھا ٹھکانہ ہے'),
  ('ur.ahmedali', 3, 15, 'کہہ دے کیا میں تم کو اس سے بہتر بناؤں پرہیزگاروں کے لیے اپنے رب کے ہاں باغ ہیں جن کے نیچے نہریں بہتی ہیں ان میں ہمیشہ رہیں گے اور پاک عورتیں ہیں اور الله کی رضا مندی ہے اور الله بندوں کو خوب دیکھنے والا ہے'),
  ('ur.ahmedali', 3, 16, 'وہ جو کہتے ہیں اے رب ہمارے! ہم ایمان لائے ہیں سو ہمیں ہمارے گناہ بخش دے اور ہمیں دوزخ کے عذاب سے بچا لے'),
  ('ur.ahmedali', 3, 17, 'وہ صبر کرنے والے ہیں اور سچے ہیں اور فرمانبرداری کرنے والے ہیں اور خرچ کرنے والے ہیں اور پچھلی راتوں میں گناہ بخشوا نے والے ہیں'),
  ('ur.ahmedali', 3, 18, 'الله نے اور فرشتوں نے اور علم والوں نے گواہی دی کہ اس کے سوا اورکوئی معبود نہیں وہی انصاف کا حاکم ہے اس کے سوا اورکوئی معبود نہیں زبردست حکمت والا ہے'),
  ('ur.ahmedali', 3, 19, 'بےشک دین الله کے ہاں فرمابرداری ہی ہے اور جنہیں کتاب دی گئی تھی انہوں نے صحیح علم ہونے کے بعد آپس کی ضد کے باعث اختلاف کیا اور جو شخص الله کے حکموں کا انکار کرے تو الله جلد ہی حساب لینے والا ہے'),
  ('ur.ahmedali', 3, 20, 'پھربھی اگر تجھ سے جھگڑیں تو ان سے کہہ دے کہ میں نے اپنا منہ الله کے تابع کیا ہے ان لوگوں نے بھی جو میرے ساتھ ہیں اور ان لوگوں سے کہہ دے جنہیں کتاب دی گئی ہے اور ان پڑھوں سے آیا تم بھی تابع ہوتے ہو پھر اگر وہ تابع ہو گئے تو انہوں نے بھی سیدھی راہ پالی اور اگر وہ منہ پھیریں تو تیرے ذمہ فقط پہنچا دینا ہے اور الله بندوں کو خوب دیکھنے والا ہے'),
  ('ur.ahmedali', 3, 21, 'بے شک جولوگ الله کے حکموں کا انکار کرتے ہیں اور پیغمبروں کو ناحق قتل کرتے ہیں اور لوگوں میں سے انصاف کا حکم کرنے والوں کو قتل کرتے ہیں سو انہیں دردناک عذاب کی خوشخبری سنا دیے'),
  ('ur.ahmedali', 3, 22, 'یہی وہ لوگ ہیں جنکی دنیا اور آخرت میں محنت ضائع ہو گئی اور ان کا کوئی مددگار نہیں'),
  ('ur.ahmedali', 3, 23, 'کیا تو نے ان لوگوں کو نہیں دیکھا جنہیں ایک حصہ کتاب کا ملا وہ الله کی کتاب کی طرف بلائے جاتے ہیں تاکہ وہ کتاب ان میں فیصلہ کرے پھر ایک فرقہ ان میں سے پھر جاتا ہے ایسے حال میں کہ وہ منہ پھیرنے والے ہوتے ہیں'),
  ('ur.ahmedali', 3, 24, 'یہ ا سلیے ہےکہ وہ کہتے ہیں کہ ہمیں ہرگز آگ نہیں لگے گی مگر چند دن گنتی کے اور ان کی بنائی ہوئی باتوں نے انہیں دین میں دھوکہ دیا ہوا ہے'),
  ('ur.ahmedali', 3, 25, 'پھر ان کا کیا ہوگا جب ہم انہیں ایک دن جمع کریں گے جس کے آنے میں کوئی شبہ نہیں اور ہر کسی کواپنی کمائی کا اجر پورا دیا جائے گا اور ان پر کوئی ظلم نہیں کیا جائے گا'),
  ('ur.ahmedali', 3, 26, 'تو کہہ اے الله! بادشاہی کے مالک! جسے تو چاہتا ہے سلطنت دیتاہے اور جس سے چاہتا ہے سلطنت چھین لیتا ہے جسے تو چاہتا ہے عزت دیتا ہے اور جسے توچاہے ذلیل کرتا ہے سب خوبی تیرے ہاتھ میں ہے بے شک تو ہر چیز قادر ہے'),
  ('ur.ahmedali', 3, 27, 'تو رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کرتا ہے اور زندہ کو مردہ سے نکالتا ہے اور مردہ کو زندہ سےنکالتا ہے اور جسے تو چاہتا ہے بے حساب رزق دیتا ہے'),
  ('ur.ahmedali', 3, 28, 'مسلمان مسلمانوں کو چھوڑ کر کافروں کو دوست نہ بنائيں اور جوکوئی یہ کام کریں اسے الله سے کوئی تعلق نہیں مگر اس صورت میں کہ تم ان سے بچاؤ کرنا چاہو اور الله تمہیں اپنے سے ڈراتا ہے اور الله ہی کی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 3, 29, 'تو کہہ دے اگر تم اپنے دل کی بات چھپاؤ یا ظاہر کرو اسے الله جانتا ہے اور جو کچھ آسمانوں اور جو کچھ زمین میں ہے اسے جانتا ہے اور الله ہر چیز ہر قادر ہے'),
  ('ur.ahmedali', 3, 30, 'جس دن ہرشخص موجود پائے گا اپنے سامنے اس نیکی کو جو اس نے کی تھی اور جو کچھ کہ اس نے برائی کی تھی اس دن چاہے گا کہ کاش درمیان اس کے اور درمیان اس کی برائی کے مسافت دور کی ہو اور الله تمہیں اپنی ذات سے ڈراتا ہے اور الله بندوں پر شفقت کرنے والا ہے'),
  ('ur.ahmedali', 3, 31, 'کہہ دو اگر تم الله کی محبت رکھتے ہو تو میری تابعداری کرو تاکہ تم سے الله محبت کرے اور تمہارے گناہ بخشے اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 3, 32, 'کہہ دو الله اور اس کے رسول کی فرمانبرداری کرو پھر اگر وہ منہ موڑیں تو الله کافروں کو دوست نہیں رکھتا'),
  ('ur.ahmedali', 3, 33, 'بے شک اللهنے آدم کو اور نوح کو اور ابراھیم کی اولاد کو اور عمران کی اولاد کو سارے جہان سے پسند کیاہے'),
  ('ur.ahmedali', 3, 34, 'جو ایک دوسرے کی اولاد تھے اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 3, 35, 'جب عمران کی عورت نے کہا اے میرے رب جو کچھ میرے پیٹ میں ہے سب سے آزاد کر کے میں نےتیری نذر کیا سو تو مجھ سے قبول فرما بے شک تو ہی سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 3, 36, 'پھر جب اسے جنا کہا اے میرے رب! میں نے تو وہ لڑکی جنی ہے اور جو کچھ اس نے جنا ہے الله اسے خوب جانتا ہے اور بیٹا بیٹی کی طرح نہیں ہوتا اور میں نے اس کا نام مریم رکھا اور میں اسے اور اس کی اولاد کو شیطان مردود سے بچا کر تیری پناہ میں دیتی ہوں'),
  ('ur.ahmedali', 3, 37, 'پھر اسے اس کے رب نے اچھی طرح سے قبول کیا اور اسے اچھی طرح بڑھایا اور وہ زکریا کو سونپ دی جب زکریا اس کے پاس حجرہ میں آتے تو اس کے پاس کچھ کھانے کی چیز پاتے کہتے اے مریم! تیرے پاس یہ چیز کہاں سے آئی ہے وہ کہتی یہ الله کے ہاں سے آئی ہے الله جسے چاہے بے قیاس رزق دیتا ہے'),
  ('ur.ahmedali', 3, 38, 'زکریا نے وہیں اپنے رب سے دعا کی کہا اے میرے رب! مجھے اپنے پاس سے پاکیزہ اولاد عطا فرما بے شک تو دعا کا سننے والا ہے'),
  ('ur.ahmedali', 3, 39, 'پھر فرشتوں نے اس کو آواز دی جب وہ حجرے کے اندر نماز میں کھڑے تھے کہ بے شک الله تجھ کو یحییٰ کو خوشخبری دیتا ہے جو الله کے ایک حکم کی گواہی دے گا اور سردار ہوگا اور عورت کے پاس نہ جائے گا اور صالحین میں سے نبی ہوگا'),
  ('ur.ahmedali', 3, 40, 'کہا اے میرے رب! میرا لڑکا کہاں سے ہوگا حالانکہ میں بڑھاپے کو پہنچ چکا ہوں اور میری بیوی بانجھ ہے فرمایا الله اسی طرح جو چاہتا ہے کرتا ہے'),
  ('ur.ahmedali', 3, 41, 'کہا اے میرے رب! میرے لیے کوئی نشانی مقرر کر فرمایا تیرے لیے یہ نشانی ہے کہ تو لوگوں سے تین دن سوائے اشارہ کے بات نہ کر سکے گا اور اپنے رب کو بہت یاد کر اور شام اور صبح تسبیح کر'),
  ('ur.ahmedali', 3, 42, 'اور جب فرشتوں نے کہا اے مریم! بے شک الله نے تجھے پسند کیا ہے تجھے پاک کیا ہے اور تجھے سب جہان کی عورتوں پر پسند کیا ہے'),
  ('ur.ahmedali', 3, 43, 'اے مریم! اپنے رب کی بندگی کر اور سجدہ اور رکوع کرنے والوں کے ساتھ رکوع کر'),
  ('ur.ahmedali', 3, 44, 'یہ غیب کی خبریں ہیں ہم بذریعہ وحی تمہیں اطلاع دیتے ہیں اورتو ان کے پاس نہیں تھا جب اپنا قلم ڈالنے لگے تھے کہ مریم کی کون پرورش کرے اور تو ان کے پاس نہیں تھا جب کہ وہ جھگڑتے تھے'),
  ('ur.ahmedali', 3, 45, 'جب فرشتوں نے کہا اے مریم! الله تجھ کو ایک بات کی اپنی طرف سے بشارت دیتا ہے اس کا نام مسیح عیسیٰ بیٹا مریم کا ہوگا دنیا اور آخرت میں مرتبے والا اور الله کے مقربوں میں سے ہو گا'),
  ('ur.ahmedali', 3, 46, 'اور جب کہ وہ ماں کی گود میں ہوگا تو لوگوں سے باتیں کرے گا اور جبکہ وہ ادھیڑ عمر کا ہوگا اور نیکوں میں سے ہوگا'),
  ('ur.ahmedali', 3, 47, 'مریم نے کہا اے میرے رب! مجھے بیٹا کیسے ہو گا حالانکہ مجھے کسی آدمی نے ہاتھ نہیں لگایا فرمایا اسی طرح الله جو چاہے پیدا کرتا ہےجب کسی کام کا ارادہ کرتا ہے تو اس کو یہی کہتا ہے کہ ہوجا تو وہ ہو جاتا ہے'),
  ('ur.ahmedali', 3, 48, 'اور اس کو کتاب سکھائے گا اور دانش عطا فرمائے گا اور توریت اور انجیل'),
  ('ur.ahmedali', 3, 49, 'اور اس کو بنی اسرائیل کی طرف پیغمبر بنا کر بھیجے گا بے شک میں تمہارے رب کی طرف سے تمہارے پاس نشانیاں لے کر آیا ہوں کہ میں تمہیں مٹی سے ایک پرندہ کی شکل بنادیتا ہوں پھر اس میں پھونک مارتا ہوں اور وہ الله کے حکم سے اڑتا جانور ہو جاتا ہے اور مادر زاد اندھے اور کوڑھی کو اچھا کردیتا ہوں اور الله کے حکم سے مردے زندہ کرتا ہوں اور تمہیں بتا دیتا ہوں جو کھا کر آؤ اور جواپنے گھروں میں رکھ کر آؤ اس میں تمہار لیے نشانیاں ہیں اگر تم ایماندار ہو'),
  ('ur.ahmedali', 3, 50, 'اور مجھ سے پہلی کتاب جو تورات ہے اس کی تصدیق کرنے والاہوں اور تا کہ تم کو بعض چیزیں حلال کر دوں جو تم پر حرام تھیں اور تمہارے پاس تمہارے رب کی طرف سے نشانی لے کر آیا ہوں سو الله سے ڈرو اور میرا کہنا مانو'),
  ('ur.ahmedali', 3, 51, 'بے شک الله ہی میرا اور تمہارا رب ہے سو اسی کی بندگی کرو یہی سیدھا راستہ ہے'),
  ('ur.ahmedali', 3, 52, 'جب عیسیٰ نے بنی اسرائیل کاکفر معلوم کیا تو کہاکہ الله کی راہ میں کون میرا مددگار ہے حواریو ں نے کہا ہم الله کے دین کی مدد کرنے والے ہیں ہم الله پر یقین لائے اور تو گواہ رہ کہ ہم فرمانبرادر ہونے والے ہیں'),
  ('ur.ahmedali', 3, 53, 'اے رب ہمارے! ہم اس چیز پر ایمان لائے جو تو نے نازل کی اور ہم رسول کے تابعدار ہوئے سو تو ہمیں گواہی دینے والوں میں لکھ لے'),
  ('ur.ahmedali', 3, 54, 'اور انہوں نے خفیہ تدبیر کی اور الله نے بھی خفیہ تدبیر فرمائی اور الله بہترین خفیہ تدبیر کرنے والو ں میں سے ہے'),
  ('ur.ahmedali', 3, 55, 'جس وقت الله نے فرمایا اے عیسیٰ! بے شک میں تمہیں وفات دینے والا ہوں اور تمہیں اپنی طرف اٹھانے والا ہوں اور تمہیں کافروں سے پاک کرنے والا ہوں اور جو لوگ تیرے تابعدار ہوں گے انہیں ان لوگوں پر قیامت کے دن تک غالب رکھنے والا ہوں جو تیرے منکر ہیں پھر تم سب کو میری طرف لوٹ کر آنا ہوگا پھر میں تم میں فیصلہ کروں گا جس بات میں تم جھگڑتے تھے'),
  ('ur.ahmedali', 3, 56, 'سو جو لوگ کافر ہوئے انہیں دنیا اور آخرت میں سخت عذاب دوں گا اور ان کا کوئی مددگار نہیں ہوگا'),
  ('ur.ahmedali', 3, 57, 'اورجو لوگ ایمان لائے اور نیک کام کیے انہیں ان کا حق پورا پورا دے گا اور الله ظالموں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 3, 58, 'یہ آیتیں ہم تمہیں پڑھ کر سناتے ہیں اور نصیحت حکمت والی'),
  ('ur.ahmedali', 3, 59, 'بے شک عیسیٰ کی مثال الله کے نزدیک آدم کی سی ہے اسے مٹی سے بنایا پھر اسے کہا کہ ہو جا پھر ہو گیا'),
  ('ur.ahmedali', 3, 60, 'حق وہی ہے جو تیرا رب کہے پھر تو شک کرنے والو ں میں سے نہ ہو'),
  ('ur.ahmedali', 3, 61, 'پھر جو کوئی تجھ سے اس واقعہ میں جھگڑے بعد اس کے کہ تیرے پاس صحیح علم آ چکا ہے تو کہہ دے آؤ ہم اپنے بیٹے اور تمہارے بیٹے اور اپنی عورتیں اور تمہاری عورتیں اور اپنی جانیں اور تمہاری جانیں بلائیں پھر سب التجا کریں اور الله کی لعنت ڈالیں ان پر جو جھوٹے ہوں'),
  ('ur.ahmedali', 3, 62, 'بے شک یہی سچا بیان ہے اور الله کے سوا اور کوئی معبود نہیں اور بے شک الله ہی زبردست حکمت والا ہے'),
  ('ur.ahmedali', 3, 63, 'پھر اگر پھر جائیں تو بے شک الله فساد کرنے والوں کو جانتا ہے'),
  ('ur.ahmedali', 3, 64, 'کہہ اے اہلِ کتاب! ایک بات کی طرف آؤ جو ہمارے اور تمہارے درمیان برابر ہے کہ سوائے الله کے اور کسی کی بندگی نہ کریں اور اس کا کسی کو شریک نہ ٹھیرائیں اور سوائے الله کے کوئی کسی کو رب نہ بنائے پس اگر وہ پھر جائیں تو کہہ دو گواہ رہو کہ ہم تو فرمانبردار ہونے والے ہیں'),
  ('ur.ahmedali', 3, 65, 'اے اہلِ کتاب! ابراھیم کے معاملہ میں کیوں جھگڑتے ہو حالانکہ تورات اور انجیل تو اس کے بعد اتری ہیں کیا تم یہ نہیں سجحھتے'),
  ('ur.ahmedali', 3, 66, 'ہاں! تم وہ لوگ ہو جس چیز کا تمہیں علم تھا اس میں تو جھگڑے پس اس چیز میں کیوں جھگڑتے ہو جس چیز کا تمہیں علم ہی نہیں اور الله جانتا ہے اور تم نہیں جانتے'),
  ('ur.ahmedali', 3, 67, 'ابراھیم نہ یہوودی تھے اور نہ نصرانی لیکن سیدھے راستے والے مسلمان تھے اور مشرکوں میں سے نہ تھے'),
  ('ur.ahmedali', 3, 68, 'لوگوں میں سب سے زیادہ قریب ابراھیم کے وہ لوگ تھے جنہوں نے اس کی تابعداری کی اور یہ نبی اور جو اس نبی پر ایمان لائے اور الله ایمان والوں کا دوست ہے'),
  ('ur.ahmedali', 3, 69, 'بعض اہلِ کتاب دل سے چاہتے ہیں کہ کسی طرح تم کو گمراہ کردیں اور گمراہ نہیں کرتے مگر اپنے نفسوں کو اور نہیں سمجتے'),
  ('ur.ahmedali', 3, 70, 'اے اہلِ کتاب! الله کی آیتو ں کا کیوں انکار کرتے ہو حالانکہ تم گواہ ہو'),
  ('ur.ahmedali', 3, 71, 'اے اہلِ کتاب! سچ میں جھوٹ کیوں ملاتے ہو اور سچی بات کو چھپاتے ہو حالانکہ تم جانتے ہو'),
  ('ur.ahmedali', 3, 72, 'اور اہل کتاب میں سے ایک جماعت نے کہا جو کچھ مسلمانوں پر اترا ہے اس پر صبح ایمان لاؤ اور شام کو اس سے انکار کر دو شاید کہ وہ پھر جائیں'),
  ('ur.ahmedali', 3, 73, 'اوراپنے مذہب والے کے سوا کسی کی بات نہ مانو ان سے کہہ دو کہ بے شک ہدایت وہی ہے جو الله ہدایت کرے اور یہ بات نہ مانو کہ کوئی شخص دیا جا سکتا ہے مثل اس کے کہ تم دیے گئے ہو یا کوئی گروہ خدا کے ہاں تم پر الزام قائم کرسکتا ہے ان سے کہہ دو کہ فضل الله کے اختیار میں ہے جسے چاہے وہ دیتا ہے اور الله کشائش والا جاننے والا ہے'),
  ('ur.ahmedali', 3, 74, 'جسے چاہے اپنی مہربانی سے خاص کرتا ہے اور الله بڑے فضل والا ہے'),
  ('ur.ahmedali', 3, 75, 'اور اہل کتاب میں بعض ایسے ہیں کہ اگر تو ان کے پاس ایک ڈھیر مال کا امانت رکھے وہ تجھ کو ادا کریں اور بعضے ان میں سے وہ ہیں اگر تو ان کے پاس ایک اشرفی امانت رکھے تو بھی تجھے واپس نہیں کریں گے ہاں جب تک کہ تو اس کے سر پر کھڑا رہے یا اس واسطے ہے کہ وہ کہتے ہیں ہم پر ان پڑھ لوگوں کا حق لینے میں کوئی گناہ نہیں اور الله پر وہ جھوٹ بولتے ہیں حالانکہ وہ جانتے ہیں'),
  ('ur.ahmedali', 3, 76, 'گناہ کیوں نہ ہوگا جس شخص نے اپنا عہد پورا کیا اور الله سے ڈرا تو بے شک پرہیزگاروں کو دوست رکھتا ہے'),
  ('ur.ahmedali', 3, 77, 'بے شک جو لوگ الله کے عہد اور اپنی قسمو ں کے بدلے حقیر معاوضہ لیتے ہیں آخرت میں ان کا کوئی حصہ نہیں اور ان سے الله کلام نہیں کرے گا اور قیامت کے دن ان کی طرف نہ دیکھے گا اور انہیں پاک بھی نہ کرے گا اور ان کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 3, 78, 'اوربے شک ان میں سے ایک جماعت ہے کہ کتاب کو زبان مروڑ کر پڑھتے ہیں تاکہ تم یہ خیال کرو کہ وہ کتاب میں سے ہے حالانکہ وہ کتاب میں سے نہیں ہے اوروہ کہتے ہیں کہ الله کے ہاں سے ہے حالانکہ وہ الله کے ہاں سے نہیں ہے اور الله پر جان بوجھ کر جھوٹ بولتے ہیں'),
  ('ur.ahmedali', 3, 79, 'کسی انسان کے لیے یہ جائز نہیں ہے کہ الله اسے کتاب اور حکمت اور نبوت عطا فرمائے پھر وہ لوگوں سے یہ کہے کہ الله کو چھوڑ کر میرے بندے ہو جاؤ لیکن کہے گا کہ تم لوگ الله والے بن جاؤ اس لیے کہ تم الله کی کتاب سکھاتے ہو اوراس واسطے کہ تم پڑھتے ہو'),
  ('ur.ahmedali', 3, 80, 'اورنہ یہ جائز ہے کہ تمہیں حکم کرے کہ تم فرشتوں اور نبیوں کو رب بنا لو کیا وہ تمہیں کفر سکھائے گا بعد اس کے کہ تم مسلمان ہو چکے ہو'),
  ('ur.ahmedali', 3, 81, 'اورجب الله نے نبیوں سے عہد لیا اور البتہ جو کچھ میں تمہیں کتاب ابور علم سے دوں پھر تمہارے پاس پیغنبر آئے جو اس چیز کی تصدیق کرنے والا ہو جو تمہارے پاس ہے البتہ اس پر ایمان لے آنا اور البتہ اس کی مدد کرنا فرمایا کیاتم نے اقرار کیا اور اس شرط پر میرا عہد قبول کیا انہوں نے کہا ہم نے اقرار کیا الله نے فرمایا تو اب تم گواہ رہو میں بھی تمہارے ساتھ گواہ ہوں'),
  ('ur.ahmedali', 3, 82, 'پھر جو کوئی اس کے بعد پھر جائے تو وہی لوگ نافرمان ہیں'),
  ('ur.ahmedali', 3, 83, 'کیا الله کے دین کے سوا کوئی اور دین تلاش کرتے ہیں حالانکہ جو کوئی آسمان اور زمین میں ہے خوشی سے یا لاچاری سے سب اسی کے تابع ہے اور اسی کی طرف لوٹائے جائیں گے'),
  ('ur.ahmedali', 3, 84, 'کہہ دو ہم الله پر ایمان لائے اور جو کچھ ہم پر نازل کیاگیا اور جو کچھ ابراھیم اور اسماعیل اور اسحاق اور یعقوب اور اس کی اولاد پر نازل کیا گیا اور جو کچھ موسیٰ اور عیسیٰ اور سب نبیوں کو ان کے رب کی طرف سے ملا ہم ان میں سے کسی کو جدا نہیں کرتے اور ہم اسی کے فرمانبردار ہیں'),
  ('ur.ahmedali', 3, 85, 'اور جو کوئی اسلام کے سوا اور کوئی دین چاہے تو وہ اس سے ہر گز قبول نہیں کیا جائے گا اور وہ آخرت میں نقصان اٹھانے والوں میں سے ہوگا'),
  ('ur.ahmedali', 3, 86, 'الله ایسے لوگوں کو کیونکر راہ دکھائے جو ایمان لانے کے بعد کافر ہوگئے اور گواہی دے چکے ہیں کہ بے شک یہ رسول سچا ہے اور ان کے پاس روشن نشانیاں آئی ہیں اور الله ظالموں کو راہ نہیں دکھاتا'),
  ('ur.ahmedali', 3, 87, 'ایسے لوگوں کی یہ سزا ہے کہ ان پر الله اور فرشتوں اور سب لوگو ں کی لعنت ہو'),
  ('ur.ahmedali', 3, 88, 'اس میں ہمیشہ رہنے والے ہوں گے ان سے عذاب ہلکا نہ کیا جائے گا اور نہ وہ مہلت دیے جائیں گے'),
  ('ur.ahmedali', 3, 89, 'مگر جنہوں نے اس کے بعد توبہ کی اور نیک کام کیے تو بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 3, 90, 'بے شک جو لوگ ایمان لانے کے بعد منکر ہو گئے پھر انکار میں بڑھتے گئے ان کی توبہ ہر گز قبول نہیں کی جائے گی اور وہی گمراہ ہیں'),
  ('ur.ahmedali', 3, 91, 'بے شک جو لوگ کافر ہوئے اور کفر کی حالت میں مر گئے تو کسی ایسے سے زمین بھر کر سونا بھی قبول نہیں کیا جائے گا اگرچہ وہ اس قدر سونا بدلے میں دے ان لوگوں کے لیے دردناک عذاب ہے اور ان کا کوئی مددگار نہیں ہوگا'),
  ('ur.ahmedali', 3, 92, 'ہر گز نیکی میں کمال حاصل نہ کر سکو گے یہاں تک کہ اپنی پیاری چیز سے کچھ خرچ کرو اور جو چیز تم خرچ کرو گے بے شک الله اسے جاننے والا ہے'),
  ('ur.ahmedali', 3, 93, 'بنی اسرائیل کے لیے سب کھانے کی چیزیں حلال تھیں مگر وہ چیز جو اسرائیل نے تورات نازل ہونے سے پہلےاپنے اوپر حرام کی تھی کہہ دو تورات لاؤ اور اسے پڑھو اگر تم سچے ہو'),
  ('ur.ahmedali', 3, 94, 'پھر جس شخص نے اس کے بعد الله پر جھوٹ بنایا وہی بڑے بے انصاف ہیں'),
  ('ur.ahmedali', 3, 95, 'کہہ دو الله نے سچ فرمایا ہے اب ابراھیم کے دین کے تابع ہو جاؤ جوایک ہی کےہو گئے تھے اور مشرکوں میں سے نہ تھے'),
  ('ur.ahmedali', 3, 96, 'بے شک لوگوں کے واسطے جو سب سے پہلا گھر مقرر ہوا یہی ہے جو مکہ میں برکت والا ہے اور جہان کے لوگوں کے لیے راہ نما ہے'),
  ('ur.ahmedali', 3, 97, 'اس میں ظاہر نشانیاں ہیں مقام ابراھیم ہے اور جو اس میں داخل ہو جائے وہ امن والا ہو جاتا ہے اور لوگوں پر اس گھر کا حج کرنا الله کا حق ہے جو شخص اس تک پہنچنے کی طاقت رکھتا ہو اور جو انکار کرے تو پھر الله جہان والوں سے بے پرواہ ہے'),
  ('ur.ahmedali', 3, 98, 'کہہ دواے اہلِ کتاب الله کیا آیتوں کا کیوں انکار کرتے ہو اور جو کچھ تم کرتے ہو الله اس پر گواہ ہے'),
  ('ur.ahmedali', 3, 99, 'کہہ دواے اہلِ کتاب الله کی راہ سے کیوں روکتے ہو اس شخص کو جو ایمان لائے اس میں عیب ڈھونڈتے ہو اورتم خود جانتے ہو اور تمہارے کام سے الله بے خبر نہیں ہے'),
  ('ur.ahmedali', 3, 100, 'اے ایمان والو اگرتم اہلِ کتاب کی کسی جماعت کابھی کہا مانو گےتو وہ تمہیں ایمان لانے کے بعد کافر کر دیں گے'),
  ('ur.ahmedali', 3, 101, 'اور تم کس طرح کافر ہو گے حالانکہ تم پر الله کی آیتیں پڑھی جاتی ہیں اور اس کا رسول تم میں موجود ہے اور جو شخص الله کو مضبوط پکڑے گا تو اسے ہی سیدھے راستے کی ہدایت کی جائے گی'),
  ('ur.ahmedali', 3, 102, 'اے ایمان والو الله سے ڈرتے رہو جیسا اس سے ڈرنا چاہیئے اور نہ مرد مگر ایسے حال میں کہ تم مسملمان ہو'),
  ('ur.ahmedali', 3, 103, 'اور سب مل کر الله کی رسی مضبوط پکڑو اور پھوٹ نہ ڈالو اور الله کا احسان اپنے اوپر یاد کرو جب کہ تم آپس میں دشمن تھے پھر تمہارے دلوں میں الفت ڈال دی پھر تم اس کے فضل سے بھائی بھائی ہو گئے اور تم آگ کے گڑھے کے کنارے پر تھے پھر تم کو اس سے نجات دی اس طرح تم پر الله اپنی نشانیاں بیان کرتا ہے تاکہ تم ہدایت پاؤ'),
  ('ur.ahmedali', 3, 104, 'اور چاہیئے کہ تم میں سے ایک جماعت ایسی ہو جو نیک کام کی طرف بلاتی رہے اوراچھے کاموں کا حکم کرتی رہے اور برے کاموں سے روکتی رہے اور وہی لوگ نجات پانے والے ہیں'),
  ('ur.ahmedali', 3, 105, 'ان لوگو ں کی طرح مت ہو جو متفرق ہو گئے بعد اس کے کہ ان کے پاس واضح احکام آئے انہوں نے اختلاف کیا اور ان کے لیے بڑا عذاب ہے'),
  ('ur.ahmedali', 3, 106, 'جس دن بعضے منہ سفید اور بعضے منہ سیاہ ہوں گے سو وہ جن کے منہ سیاہ ہوں گے ان سے کہا جائے گا کیا تم ایمان لا کر کافر ہو گئے تھے اب اس کفر کرنےکے بدلے میں عذاب چکھو'),
  ('ur.ahmedali', 3, 107, 'اور وہ لوگ جن کے منہ سفید ہوں گے تو وہ الله کی رحمت میں ہوں گے وہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 3, 108, 'یہ الله کے احکام ہیں ہم تمہیں ٹھیک ٹھیک سناتے ہیں اور الله مخلوقات پر ظلم نہیں کرنا چاہتا'),
  ('ur.ahmedali', 3, 109, 'اور جو کچھ آسمانوں اور جو کچھ زمین میں ہے سب الله ہی کا ہے اور سب کام الله ہی کے طرف پھیرے جاتے ہیں'),
  ('ur.ahmedali', 3, 110, 'تم سب امتوں میں سے بہتر ہو جو لوگوں کے لیے بھیجی گئی ہیں اچھے کاموں کا حکم کرتے رہو اور برے کاموں سے روکتے رہو اور الله پر ایمان لاتے ہو اور اگر اہل کتاب ایمان لے آتے تو ان کے لیے بہتر تھا کچھ ان میں سے ایماندار ہیں اور اکثر ان میں سے نافرمان ہیں'),
  ('ur.ahmedali', 3, 111, 'وہ زبان سے ستانے کے سوا تمہارا اور کچھ بگاڑ نہ سکیں گے اور اگر تم سے لڑیں گے تو پیٹھ پھیر دیں گے پھر مدد نہیں دیے جائیں گے'),
  ('ur.ahmedali', 3, 112, 'ان پر ذلت لازم کی گئی ہے جہاں وہ پائے جائیں گے مگر ساتھ الله کی پناہ کے اور لوگو ں کی پناہ کے اور وہ الله کے غضب کے مستحق ہوئے اور ان پر پستی لازم کی گئی یہ اس واسطے ہے کہ الله کی نشانیوں کے ساتھ کفر کرتے تھے اور پیغمبروں کو ناحق قتل کرتے تھے یہ اس سبب سے ہے کہ انہوں نے نافرمانی کی اور حد سے نکل جاتے تھے'),
  ('ur.ahmedali', 3, 113, 'وہ سب برابر نہیں اہل کتاب میں سے ایک فرقہ سیدھی راہ پر ہے وہ رات کے وقت الله کی آیتیں پڑھتے ہیں اور وہ سجدے کرتے ہیں'),
  ('ur.ahmedali', 3, 114, 'الله اور قیامت کے دن پر ایمان لاتے ہیں اور اچھی بات کا حکم کرتے ہیں اور برے کاموں سے روکتے ہیں اور نیک کاموں میں دوڑتے ہیں اور وہی لوگ نیک بخت ہیں'),
  ('ur.ahmedali', 3, 115, 'وہ لوگ جو نیک کام کریں گے اس سے محروم نہ کیے جائیں گے اور الله پرہیزگارو ں کا جاننے والا ہے'),
  ('ur.ahmedali', 3, 116, 'بے شک جو لوگ کافر ہیں ان کے مال اور اولاد الله کے مقابلے میں کچھ کام نہ آئیں گے اوروہی لوگ دوزخی ہیں وہ اس آگ میں ہمیشہ رہنے والے ہیں'),
  ('ur.ahmedali', 3, 117, 'اس دنیا کی زندگی میں جو کچھ خرچ کرتے ہیں اس کی مثال ایسی ہے جس طرح ایک ہوا ہو جس میں تیز سردی ہو وہ ایسے لوگو ں کی کھیتی کو لگ جائے جنہوں نے اپنے نفسوں پر ظلم کیا تھا پھر ا سکو برباد کر گئی اور الله نے ان پر ظلم نہیں کیا لیکن وہ اپنے او پر ظلم کرتے ہیں'),
  ('ur.ahmedali', 3, 118, 'اے ایمان والو اپنوں کے سوا کسی کو بھیدی نہ بناؤ وہ تمہاری خرابی میں قصور نہیں کرتے جو چیز تمہیں تکلیف دے وہ انہیں پسند آتی ہے ان کے مونہوں سے دشمنی نکل پڑتی ہے اور جو ان کے سینے میں چپھی ہوئي ہے وہ بہت زیادہ ہے ہم نے تمہارے لیے نشانیاں بیان کر دی ہیں اگر تم عقل رکھتے ہو'),
  ('ur.ahmedali', 3, 119, 'سن لو تم ان کے دوست ہو اور وہ تمہارے دوست نہیں اور تم تو سب کتابوں کو مانتے ہو اور جب وہ تم سے ملتے ہیں تو کہتے ہیں کہ ہم مسلمان ہیں اور جب الگ ہوتے ہیں تو تم پر غصہ سے انگلیاں کاٹ کاٹ کھاتے ہیں کہہ دو تم اپنے غصہ میں مرو الله کو دلوں کی باتیں خوب معلوم ہیں'),
  ('ur.ahmedali', 3, 120, 'اگر تمہیں کوئی بھلائی پہنچے توانہیں بری لگتی ہے اور اگر تمہیں کوئی تکلیف پہنچے تو اس سے خوش ہوتے ہیں اور اگر تم صبر کرو اور پرہیزگاری کرو تو ان کے فریب سے تمہارا کچھ نہ بگڑے گا بے شک الله ان کے اعمال پر احاطہ کرنے والا ہے'),
  ('ur.ahmedali', 3, 121, 'اور جب تو صبح کو اپنے گھر سے نکلا مسلمانوں کو لڑائی کا ٹھکانے پر بٹھا رہا تھا اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 3, 122, 'جب تم میں سے دو جماعتوں نے قصد کیا کہ نامردی کریں اور الله ا ن کا مددگار تھا اور چاہیئے کہ الله ہی پر مسلمان بھروسہ کریں'),
  ('ur.ahmedali', 3, 123, 'اور الله بدر کی لڑائی میں تمہاری مدد کر چکا ہے حالانکہ تم کمزور تھے پس الله سے ڈرو تاکہ تم شکر کرو'),
  ('ur.ahmedali', 3, 124, 'جب تو مسلمانوں کو کہتا تھا کیا تمہیں یہ کافی نہیں کہ تمہارا رب تمہاری مدد کے لیے تین ہزار فرشتے آسمان سے اترنے والے بھیجے'),
  ('ur.ahmedali', 3, 125, 'بلکہ اگر تم صبر کرو اور پرہیزگاری کرو اور وہ تم پر ایک دم سے آ پہنچیں تو تمہارا رب پانچ ہزار فرشتے نشان دار گھوڑوں پر مدد کے لیے بھیجے گا'),
  ('ur.ahmedali', 3, 126, 'اوراس چیز کواللہ نے تمہارے دل کی خوشی کے لیے کیا ہے اور تاکہ تمہارے دلوں کو اس سے اطمینان ہو اورمدد تو صرف الله ہی کی طرف سے ہے جو زبردست حکمت والا ہے'),
  ('ur.ahmedali', 3, 127, 'تاکہ بعض کافروں کو ہلاک کرے یا انہیں ذلیل کرے پھر وہ ناکام ہو کر لوٹ جائیں'),
  ('ur.ahmedali', 3, 128, 'تیرا کوئی اختیار نہیں ہے یا الله انہیں توبہ کی توفیق دے یاانہیں عذاب کرے کیوں کہ وہ ظالم ہیں'),
  ('ur.ahmedali', 3, 129, 'اور جو کچھ آسمانو ں میں اور جو کچھ زمین میں ہے سب الله ہی کا ہے جسے چاہے بخش دے اور جسے چاہے عذاب کرے اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 3, 130, 'اے ایمان والو سود دونے پر دونا نہ کھاؤ اور الله سے ڈرو تاکہ تمہارا چھٹکارا ہو'),
  ('ur.ahmedali', 3, 131, 'اوراس آگ سے بچو جو کافروں کے لیے تیار کی گئی ہے'),
  ('ur.ahmedali', 3, 132, 'اور الله اور رسول کی تابعداری کرو تاکہ تم پر رحم کیے جاؤ'),
  ('ur.ahmedali', 3, 133, 'اور اپنے رب کی بخشش کی طرف دوڑو اوربہشت کی طرف جس کا عرض آسمان اور زمین ہے جوپرہیزگاروں کے لیے تیار کی گئی ہے'),
  ('ur.ahmedali', 3, 134, 'جو خوشی اور تکلیف میں خرچ کرتے ہیں اور غصہ ضبط کرنے والے ہیں اور لوگوں کو معاف کرنے والے ہیں اور الله نیکی کرنے والوں کو دوست رکھتا ہے'),
  ('ur.ahmedali', 3, 135, 'اور وہ لوگ جب کوئی کھلا گناہ کر بیٹھیں یا اپنے حق میں ظلم کریں تو الله کو یاد کرتے ہیں اور اپنے گناہوں سے بخشش مانگتے ہیں اور سوائے الله کے اور کون گناہ بخشنے والا ہے اور اپنے کیے پر وہ اڑتے نہیں اور وہ جانتے ہیں'),
  ('ur.ahmedali', 3, 136, 'یہ لوگ ان کا بدلہ ان کے رب کے ہاں سے بخشش ہے اور باغ ہیں جن کے نیچے نہریں بہتی ہوں گی ان باغوں میں ہمیشہ رہنے والے ہوں گے اور کام کرنے والوں کی کیسی اچھی مزدوری ہے'),
  ('ur.ahmedali', 3, 137, 'تم سے پہلے کئی واقعات ہو چکے ہیں سو زمین میں سیر کرو اور دیکھو کہ جھٹلانے والوں کا کیا انجام ہوا'),
  ('ur.ahmedali', 3, 138, 'یہ لوگوں کے واسطے بیان ہے اور ڈرنے والوں کے لیے ہدایت اور نصیحت ہے'),
  ('ur.ahmedali', 3, 139, 'اورسست نہ ہو اور غم نہ کھاؤ اور تم ہی غالب رہو گے'),
  ('ur.ahmedali', 3, 140, 'اگر تمہیں زخم پہنچا ہےتو انہیں بھی ایسا ہی زخم پہنچ چکا ہے اور ہم یہ دن لوگوں میں باری باری بدلتے رہتے ہیں اور تاکہ الله ایمان والوں کو جان لے اور تم میں سے بعضوں کو شہید کرے اور الله ظالموں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 3, 141, 'اور تاکہ الله ایمان والوں کو پاک کردے اور کافروں کو مٹا دے'),
  ('ur.ahmedali', 3, 142, 'کیا تم یہ خیال کرتے ہو کہ جنت میں داخل ہو جاؤ گے اور ابھی تک الله نے نہیں ظاہرکیا ان لوگوں کو جو تم میں سے جہاد کرنے والے ہیں اور ابھی صبر کرنے والوں کو بھی ظاہر نہیں کیا'),
  ('ur.ahmedali', 3, 143, 'اور تم موت سے پہلے اس کی ملاقات کی آرزو کرتے تھے سو اب تم نے اسے آنکھوں کے سامنہ دیکھ لیا'),
  ('ur.ahmedali', 3, 144, 'اور محمد تو ایک رسول ہے اس سے پہلے بہت رسول گزرے پھرکیا اگر وہ مرجائے یا مارا جائے تو تم الٹے پاؤں پھر جاؤ گے اور جو کوئی الٹے پاؤں پھر جائے گا تو الله کا کچھ بھی نہیں بگاڑے گا اور الله شکر گزاروں کو ثواب دے گا'),
  ('ur.ahmedali', 3, 145, 'اور الله کے حکم کے سوا کوئی مر نہیں سکتا ایک وقت مقرر لکھا ہوا ہے اور جو شخص دنیا کا بدلہ چاہے گا ہم اسے دنیا ہی میں دے دیں گے اور جو آخرت کا بدلہ چاہے گا ہم اسے دنیاہی میں دے دینگے اور ہم شکر گزاروں کو جزا دیں گے'),
  ('ur.ahmedali', 3, 146, 'اور کئی نبی ہیں جن کے ساتھ ہو کر بہت الله والے لڑے ہیں پھر الله کی راہ میں تکلیف پہنچنے پر نہ ہارے ہیں اور نہ سست ہوئے اور نہ وہ دبے ہیں اور الله ثابت قدم رہنے والوں کو پسند کرتا ہے'),
  ('ur.ahmedali', 3, 147, 'اور انہوں نے سوائے اس کے کچھ نہیں کہا کہ اے ہمارے رب ہمارے گناہ بخش دے اور جو ہمارے کام میں ہم سے زیادتی ہوئی ہے او رہمارے قدم ثابت رکھ اور کافروں کی قوم پر ہمیں مدد دے'),
  ('ur.ahmedali', 3, 148, 'پھر الله نے ان کو دنیا کا ثواب اور آخرت کا عمدہ بدلہ دیا اور الله نیک کاموں کو پسند کرتا ہے'),
  ('ur.ahmedali', 3, 149, 'اے ایمان والو اگر تم کافروں کا کہا مانو گے تو وہ تمہیں الٹے پاؤں پھیر دیں گے پھر تم نقصان میں جا پڑو گے'),
  ('ur.ahmedali', 3, 150, 'بلکہ الله تمہارا مددگار ہے اور وہ بہترین مدد کرنے والا ہے'),
  ('ur.ahmedali', 3, 151, 'اب ہم کافروں کے دلوں میں ہیبت ڈال دیں گے اس لیے کہ انہوں نے الله کا شریک ٹھیرایا جس کی اس نے کوئی دلیل نہیں اتاری اور ان کا ٹھکانا دوزخ ہے اور ظالموں کا وہ بہت بڑاٹھکانا ہے'),
  ('ur.ahmedali', 3, 152, 'اور الله تو اپنا وعدہ تم سے سچا کر چکا جب تم اس کے حکم سے انہیں قتل کرنے لگے یہاں تک کہ جب تم نے نامردی کی اور کام میں جھگڑا ڈالا اور نافرمانی کی بعد اس کے کہ تم کو دکھا دی وہ چیز جسے تم پسند کرتے تھے بعض تم میں سے دنیا چاہتے تھے اور بعض تم میں سے آخرت کے طالب تھےپھر تمہیں ان سے پھیر دیا تاکہ تمہیں آزمائے اورالبتہ تحقیق تمہیں اس نے معاف کردیا ہے اور اللہ ایمانداروں پر فضل والا ہے'),
  ('ur.ahmedali', 3, 153, 'جس وقت تم چڑھے جاتے تھے اور کسی کو مڑ کر نہ دیکھتے تھے اور رسول تمہیں تمہارےپیچھے سے پکار رہا تھا سو الله نے تمہیں اس کی پاداش میں غم دیا بسبب غم دینے کے تاکہ تم مغموم نہ ہو اس پر جو ہاتھ سے نکل گئی اور نہ اس پر جو تمہیں پیش آئی اور الله خبردار ہے اس چیز سے جو تم کرتے ہو'),
  ('ur.ahmedali', 3, 154, 'پھر الله نے اس غم کے بعد تم پر چین یعنی اونگھ بھیجی اس نے بعضوں کو تم میں سے ڈھانک لیا اور بعضوں کو اپنی جان کا فکر لڑ رہا تھا الله پر جھوٹے خیال جاہلوں جیسے کر رہے تھے کہتے تھے ہمارے ہاتھ میں کچھ کام ہے کہہ دو کہ سب کام الله کے ہاتھ میں ہے وہ اپنے دل میں چھپاتے ہیں جو تیرے سامنے ظاہر نہیں کرتے کہتے ہیں اگر ہمارے ہاتھ میں کچھ کام ہوتا تو ہم اس جگہ مارے نہ جاتے کہہ دو اگر تم اپنے گھروں میں ہوتے البتہ اپنے گرنے کی جگہ پرباہر نکل آتے وہ لوگ جن پر قتل ہونا لکھا جا چکا تھا اور تاکہ الله آزمائے جو تمہارے سینوں میں ہے اور تاکہ اس چیز کو صاف کردے جو تمہارے دلوں میں ہے اور الله دلوں کے بھید جاننے والا ہے'),
  ('ur.ahmedali', 3, 155, 'بے شک وہ لوگ جو تم میں پیٹھ پھیر گئے جس دن دونوں فوجیں ملیں سو شیطان نے ان کے گناہ کے سبب سے انہیں بہکا دیا تھا اور الله نے ان کو معاف کر دیا ہے بے شک الله بخشنے والا تحمل کرنے والا ہے'),
  ('ur.ahmedali', 3, 156, 'اے ایمان والو تم ان لوگو ں کی طرح نہ ہو جو کافر ہوئے اور وہ اپنے بھائیوں سے کہتے ہیں جب وہ ملک میں سفر پر نکلیں یا جہاد پر جائیں اگر ہمارے پاس رہتے تو نہ مرتے اور نہ مارے جاتے تاکہ الله اس خیال سے ان کے دلوں میں افسوس ڈالے اور الله ہی جلاتا اور مارتا ہے اور الله تمہارے سب کاموں کو دیکھنے والا ہے'),
  ('ur.ahmedali', 3, 157, 'اور اگر تم الله کی راہ میں مارے گئے یا مر گئے تو الله کی بخشش اور اس کی مہربانی اس چیز سے بہتر ہے جو وہ جمع کرتے ہیں'),
  ('ur.ahmedali', 3, 158, 'اوراگرتم مرگئے یا مارے گئے تو البتہ تم سب الله ہی کے ہاں جمع کیے جاؤ گے'),
  ('ur.ahmedali', 3, 159, 'پھر الله کی رحمت کے سبب سے تو ان کے لیے نرم ہو گیا اور اگرتو تند خو اور سخت دل ہوتا تو البتہ تیرے گرد سے بھاگ جاتے پس انہیں معاف کردے اور ان کے واسطے بخشش مانگ او رکام میں ان سے مشورہ لیا کر پھر جب تو اس کام کا ارادہ کر چکا تو الله پر بھروسہ کر بے شک الله توکل کرنے والے لوگوں کو پسند کرتا ہے'),
  ('ur.ahmedali', 3, 160, 'ااگر الله تمہاری مدد کرے گا تو تم پر کوئی غالب نہ ہوسکے گا اور اگر اس نے مدد چھوڑ دی تو پھر ایسا کون ہے جو اس کے بعد تمہاری مدد کر سکے اور مسلمانوں کو الله ہی پر بھروسہ کرنا چاہیے'),
  ('ur.ahmedali', 3, 161, 'اور کسی نبی کو یہ لائق نہیں کہ خیانت کرے گااور جو کوئی خیانت کرے گا اس چیز کو قیامت کے دن لائے گا جو خیانت کی تھی پھر ہر کوئی پورا پالے گا جو اس نے کمایا تھا اور وہ ظلم نہیں کیے جائیں گے'),
  ('ur.ahmedali', 3, 162, 'آیا وہ شخص جو الله کی رضا کا تابع ہے اس کے برابر ہو سکتا ہے جو غضب الہیٰ کا مستحق ہوا اور اس کا ٹھکانہ دوزخ ہے اور کیسی وہ بری جگہ ہے'),
  ('ur.ahmedali', 3, 163, 'الله کے ہاں لوگوں کے مختلف درجے ہیں اور الله دیکھتا ہے جو کچھ وہ کرتے ہیں'),
  ('ur.ahmedali', 3, 164, 'الله نے ایمان والوں پر احسان کیا ہے جو ان میں انہیں میں سے رسول بھیجا ان پر اس کی آیتیں پڑھتا ہے اور انہیں پاک کرتا ہے اور انہیں کتاب اور دانش سکھاتا ہے اگرچہ وہ اس سے پہلے صریح گمراہی میں تھے'),
  ('ur.ahmedali', 3, 165, 'کیا جب تمہیں ایک تکلیف پہنچی حالانکہ تم تو اس سے دو چند تکلیف پہنچا چکے ہو تو کہتے ہو یہ کہاں سے آئی کہہ دو یہ تکلیف تمہیں تمہاری طرف سے پہنچی ہے بے شک الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 3, 166, 'اور جو کچھ تمہیں اس دن پیش آیا جس دن دونوں جماعتیں ملیں سو الله کے حکم سے ہوا او رتاکہ الله ایمان دارو ں کو ظاہر کر دے'),
  ('ur.ahmedali', 3, 167, 'اور تاکہ منافقوں کو ظاہر کر دے اور انہیں کہا گیا تھا کہ آؤ الله کی راہ میں لڑو یا دشمنوں کو دفع کرو تو انہوں نے کہا اگر ہمیں علم ہوتا کہ آج جنگ ہو گی تو ہم ضرور تمہارے ساتھ چلتے وہ اس وقت بہ نسبت ایمان کے کفر سے زیادہ قریب تھے وہ اپنے مونہوں سے وہ باتیں کہتے ہیں جو ان کے دلو ں میں نہیں ہیں اور جو کچھ وہ چھپاتے ہیں الله اس کو خوب جانتا ہے'),
  ('ur.ahmedali', 3, 168, 'یہ وہ لوگ ہیں جو اپنے بھائیوں سے کہتے ہیں حالانکہ خود بیٹھ رہے تھے اگر وہ ہماری بات مانتے تو قتل نہ کیے جاتے کہہ دو اگر تم سچے ہو تو اپنی جانوں سے موت کو ہٹا دو'),
  ('ur.ahmedali', 3, 169, 'اور جو لوگ الله کی راہ میں مارے گئے ہیں انہیں مردہ نہ سمجھو بلکہ وہ زندہ ہیں اپنے رب کے ہاں سے رزق دیے جاتے ہیں'),
  ('ur.ahmedali', 3, 170, 'الله نے اپنے فضل سے جو انہیں دیا ہے اس پر خوش ہونے والے ہیں اور ان کی طرف سے بھی خوش ہوتے ہیں جو ابھی تک ان کے پیچھے سے ان کے پاس نہیں پہنچے اس لئے کہ نہ ان پر خوف ہے او رنہ وہ غم کھائیں گے'),
  ('ur.ahmedali', 3, 171, 'الله کی نعمت اور فضل سے خوش ہوتے ہیں اوراس بات سے کہ الله ایمانداروں کی مزدوری کو ضائع نہیں کرتا'),
  ('ur.ahmedali', 3, 172, 'جن لوگو ں نے الله اور اس کے رسول کا حکم مانا بعد اس کے کہ انہیں زخم پہنچ چکے تھے جو ان میں سے نیک ہیں اور پرہیزگارہوئے ان کے لیے بڑا اجر ہے'),
  ('ur.ahmedali', 3, 173, 'جنہیں لوگوں نے کہا کہ مکہ والوں نے تمہارے مقابلے کے لیے سامان جمع کیا ہے سوتم ان سے ڈرو تو ان کا ایمان اور زیادہ ہوا اور کہا کہ ہمیں الله کافی ہے اور وہ بہترین کارساز ہے'),
  ('ur.ahmedali', 3, 174, 'پھر مسلمان الله کی نعمت اور فضل کے ساتھ لوٹ آئے انہیں کوئی تکلیف نہ پہنچی اور الله کی مرضی کے تابع ہوئے اور الله بڑے فضل والا ہے'),
  ('ur.ahmedali', 3, 175, 'سویہ شیطان ہے کہ اپنے دوستوں سے ڈراتا ہے پس تم ان سے مت ڈرو اورمجھ سے ڈرو اگر تم ایمان دار ہو'),
  ('ur.ahmedali', 3, 176, 'اور وہ لوگ آپ ے غم میں نہ ڈال دیں جو کفر کی طرف دوڑتے ہیں وہ الله کا کچھ نہیں بگاڑیں گے الله ارادہ کرتا ہے کہ آخرت میں انہیں کوئی حصہ نہ دے اوران کے لیے بڑا عذاب ہے'),
  ('ur.ahmedali', 3, 177, 'جنہوں نے ایمان کے بدلے کفر خرید لیا وہ الله کا کچھ نہیں بگاڑیں گے اور ان کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 3, 178, 'اور کافر یہ نہ سمجھیں کہ ہم جو انہیں مہلت دیتے ہیں یہ ان کے حق میں بھلائی ہے ہم انہیں مہلت اس لیے دیتے ہیں کہ وہ گناہ میں زیادتی کریں اور ان کے لیے خوار کرنے والا عذاب ہے'),
  ('ur.ahmedali', 3, 179, 'الله مسلمانوں کو اس حالت پر رکھنا نہیں چاہتا جس پر اب تم ہو جب تک کہ ناپاک کو پاک سے جدا نہ کر دے اورالله کا یہ طریقہ نہیں ہے کہ تمہیں غیب پر مطلع کر دے لیکن الله اپنے رسولوں میں جسے چاہے چن لیتا ہے سو تم الله اور اس کے رسول پر ایمان لاؤ اور پرہیزگاری کرو تو تمہارے لیے بہت بڑا اجر ہے'),
  ('ur.ahmedali', 3, 180, 'اور جو لوگ اس چیز پر بخل کرتے ہیں جو الله نے ان کو اپنے فضل سے دی ہے وہ یہ خیال نہ کریں کہ بخل ان کے حق میں بہتر ہے بلکہ یہ ان کے حق میں براہے قیامت کے دن وہ مال طوق بناا کر ان کے گلوں میں ڈالا جائے گا جس میں وہ بخل کرتے تھے اور الله ہی آسمانوں اور زمین کا وارث ہے اور جو کچھ تم کرتے ہو الله اسے جانتا ہے'),
  ('ur.ahmedali', 3, 181, 'بے شک الله نے ان کی بات سنی ہے جنہوں نے کہا کہ بے شک الله فقیر ہے اور ہم دولت مند ہیں اب ہم ان کی بات لکھ رکھیں گے اور جو انہوں نے انبیاء کے ناحق خون کیے ہیں اور کہیں گے کہ جلتی آگ کا عذاب چکھو'),
  ('ur.ahmedali', 3, 182, 'یہ اس چیز کے بدلےہے جو تمہارے ہاتھوں نے آگے بھیجا اور الله بندوں پر ظلم نہیں کرتا'),
  ('ur.ahmedali', 3, 183, 'وہ لوگ جو کہتے ہیں کہ الله نے ہمیں حکم فرمایا تھا کہ ہم کسی پیغمبر پر ایمان نہ لائیں یہاں تک کہ وہ ہمارے پاس قربانی لائے کہ اسے آگ کھا جائے کہہ دو مجھ سے پہلے کتنے رسول نشانیاں لے کر تمہارے پاس آئے اور یہ نشانی بھی جو تم کہتے ہو پھر انہیں تم نے کیوں قتل کیا اگر تم سچے ہو'),
  ('ur.ahmedali', 3, 184, 'پھر اگر یہ تجھے جھٹلائیں تو تجھ سے پہلے بہت سے رسول جھٹلائے گئے جو نشانیاں اور صحیفے اور روشن کتاب لائے'),
  ('ur.ahmedali', 3, 185, 'ہر جان موت کا مزہ چکھنے والی ہے اور تمہیں قیامت کے دن پورے پورے بدلے ملیں گے پھر جو کوئی دوزخ سے دور رکھا گیا اور بہشت میں داخل کیا گیا سو وہ پورا کامیاب ہوا اور دنیا کی زندگی سوائے دھوکے کی پونجی کے اور کچھ نہیں'),
  ('ur.ahmedali', 3, 186, 'البتہ تم اپنے مالوں اور جانوں میں آزمائے جاؤ گے اور البتہ پہلی کتاب والوں اور مشرکوں سے تم بہت بدگوئی سنو گے اور اگر تم نے صبر کیا اور پرہیزگاری کی تو یہ ہمت کے کاموں میں سے ہے'),
  ('ur.ahmedali', 3, 187, 'اور جب الله نے اہلِ کتاب سے یہ عہد لیا کہ اسے لوگوں سے ضرور بیان کرو گے اورنہ چھپاؤ گے انہوں نے وہ عہد اپنی پیٹھ کے پیچھے پھینک دیا اور اس کے بدلے میں تھوڑا سا مول خرید کیا سو کیا ہی برا ہے جو وہ خریدتے ہیں'),
  ('ur.ahmedali', 3, 188, 'مت گمان کر ان لوگوں کو جو خوش ہوتے ہیں جو کرتے ہیں اور چاہتے ہیں کہ اس چیز کے ساتھ تعریف کیے جائیں جو انہوں نے کی پس ہر گز تو انہیں عذاب سے خلاصی پانے والا خیال نہ کر اور ان کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 3, 189, 'اور آسمانوں اور زمین کی بادشاہی الله ہی کے واسطے ہے اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 3, 190, 'بے شک آسمان اور زمین کے بنانے اور رات اور دن کے آنے جانے میں البتہ عقلمندوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 3, 191, 'وہ جو الله کو کھڑے اور بیٹھے اور کروٹ پر لیٹے یاد کرتے ہیں اور آسمان اور زمین کی پیدائش میں فکر کرتے ہیں (کہتے ہیں) اے ہمارے رب تو نے یہ بےفائدہ نہیں بنایا توسب عیبوں سے پاک ہے سو ہمیں دوزح کے عذاب سے بچا'),
  ('ur.ahmedali', 3, 192, 'اے رب ہمارے جسے تو نے دوزخ میں داخل کیا سو تو نے اے رسوا کیا اور ظالموں کا کوئی مددگار نہیں ہوگا'),
  ('ur.ahmedali', 3, 193, 'ہم نے ایک پکارنے والے سے سنا جو ایمان لانے کو پکارتا تھا کہ اپنے رب پر ایمان لاؤ سو ہم ایمان لائے اے رب ہمارے اب ہمارے گناہ بخش دے اور ہم سے ہمارا برائیاں دو رکردے اور ہمیں نیک لوگو ں کے ساتھ موت دے'),
  ('ur.ahmedali', 3, 194, 'اے رب ہمارے او رہمیں دے جو تو نےہم سے اپنے رسولوں کے ذریعے سے وعدہ کیا ہے اور ہمیں قیامت کے دن رسوا نہ کر بے شک تو وعدہ کے خلاف نہیں کرتا'),
  ('ur.ahmedali', 3, 195, 'پھر ان کے رب نے ان کی دعا قبول کی کہ میں تم میں سے کسی کام کرنے والے کا کام ضائع نہیں کرتا خواہ مرد ہو یا عورت تم آپس میں ایک دوسرے کے جز ہو پھر جن لوگوں نے وطن چھوڑا اور اپنے گھروں سے نکالے گئے اور میری راہ میں ستائے گئے او رلڑے اور مارے گئے البتہ میں ان سے ان کی برائیاں دور کروں گا اور انہیں باغوں میں داخل کروں گا جن کے نیچے نہریں بہتی ہوں گی یہ الله کے ہاں سے بدلہ ہے'),
  ('ur.ahmedali', 3, 196, 'تجھ کو کافروں کا شہرو ں میں چلنا پھرنا دھوکہ نہ دے'),
  ('ur.ahmedali', 3, 197, 'یہ تھوڑا سا فائدہ ہے پھر ان کا ٹھکانا دوزخ ہے اوروہ بہت برا ٹھکاناہے'),
  ('ur.ahmedali', 3, 198, 'ے لیکن جو لوگ اپنے رب سے ڈرتے رہے ان کے لیے باغ ہیں جن کے نیچے نہریں بہتی ہیں ان میں وہ ہمیشہ رہیں گے یہ الله کے ہاں مہمانی ہے اور جو الله کے ہاں ہے وہ نیک بندوں کے لیے بدرجہا بہتر ہے'),
  ('ur.ahmedali', 3, 199, 'اور اہل کتاب میں بعض ایسے بھی ہیں جو الله پر ایمان لاتے ہیں اور جو چیز تمہاری طرف نازل کی گئی اور جو ان کی طرف نازل کی گئی الله کے سامنے عاجزی کرنے والے ہیں الله کی آیتوں پر تھوڑا مول نہیں لیتے یہی ہیں جن کے لیے ان کے رب کے ہاں مزدوری ہے بے شک الله جلد حساب لینے والا ہے'),
  ('ur.ahmedali', 3, 200, 'اے ایمان والو صبر کرو اور مقابلہ کے وقت مضبوط رہو اور لگے رہو اور الله سے ڈرتے رہو تاکہ تم نجات پاؤ')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 3, 1, 'Elif, Lam, Mim.'),
  ('tr.diyanet', 3, 2, 'Allah, Ondan başka tanrı olmayan, diri, her an yaratıklarını gözetip durandır.'),
  ('tr.diyanet', 3, 3, 'Kendisinden önceki Kitapları tasdik eden Hak Kitap\'ı sana indirdi. Önceden insanlara yol gösterici olarak Tevrat ve İncil\'i de indirmişti. O, doğruyu yanlıştan ayıran Kitap\'ı indirdi. Doğrusu Allah\'ın ayetlerini inkar edenler için şiddetli azab vardır. Allah güçlüdür, mazlumların öcünü alır.'),
  ('tr.diyanet', 3, 4, 'Kendisinden önceki Kitapları tasdik eden Hak Kitap\'ı sana indirdi. Önceden insanlara yol gösterici olarak Tevrat ve İncil\'i de indirmişti. O, doğruyu yanlıştan ayıran Kitap\'ı indirdi. Doğrusu Allah\'ın ayetlerini inkar edenler için şiddetli azab vardır. Allah güçlüdür, mazlumların öcünü alır.'),
  ('tr.diyanet', 3, 5, 'Şüphesiz gökte ve yerde hiçbir şey Allah\'tan gizli kalmaz.'),
  ('tr.diyanet', 3, 6, 'Ana rahminde sizi dilediği gibi şekillendiren O\'dur. O\'ndan başka tanrı yoktur, güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 3, 7, 'Sana Kitap\'ı indiren O\'dur. Onda Kitap\'ın temeli olan kesin anlamlı ayetler vardır, diğerleri de çeşitli anlamlıdırlar. Kalblerinde eğrilik olan kimseler, fitne çıkarmak, kendilerine göre yorumlamak için onların çeşitli anlamlı olanlarına uyarlar. Oysa onların yorumunu ancak Allah bilir. İlimde derinleşmiş olanlar: "Ona inandık, hepsi Rabbimiz\'in katındandır" derler. Bunu ancak akıl sahipleri düşünür;'),
  ('tr.diyanet', 3, 8, 'Rabbimiz! Bizi doğru yola erdirdikten sonra kalblerimizi eğriltme, katından bize rahmet bağışla; şüphesiz Sen sonsuz bağışta bulunansın.'),
  ('tr.diyanet', 3, 9, 'Rabbimiz! Doğrusu geleceği şüphe götürmeyen günde, insanları toplayacak olan Sensin. Şüphesiz ki Allah verdiği sözden caymaz.'),
  ('tr.diyanet', 3, 10, 'İnkar edenlerin malları ve çocukları, Allah\'a karşı onlara bir şey sağlamaz. İşte onlar ateşin yakıtlarıdır.'),
  ('tr.diyanet', 3, 11, 'Bunların tutumu, Firavun ailesinin ve onlardan öncekilerin tutumu gibi ki, ayetlerimizi yalanladılar da Allah onları günahlarından dolayı yok (helak) etti. Allah\'ın cezalandırması şiddetlidir.'),
  ('tr.diyanet', 3, 12, 'İnkar edenlere: "Yenileceksiniz, toplanıp cehenneme sürüleceksiniz, orası ne kötü döşektir" de.'),
  ('tr.diyanet', 3, 13, 'Karşı karşıya gelen iki topluluğun durumlarında sizin için ibret vardır; biri Allah yolunda savaşanlardır, diğeri inkarcılardır ki, bunlar karşı tarafı gözleriyle kendilerinin iki misli görüyorlardı. Allah dilediğini yardımıyla destekler. Bunda görebilenler için ibret vardır.'),
  ('tr.diyanet', 3, 14, 'Kadınlara, oğullara, kantar kantar altın ve gümüşe, nişanlı atlar ve develere, ekinlere karşı aşırı sevgi beslemek insanlara güzel gösterilmiştir. Bunlar dünya hayatının nimetleridir, oysa gidilecek yerin güzeli Allah katındadır.'),
  ('tr.diyanet', 3, 15, 'De ki: Bundan daha iyisini size haber vereyim mi? Allah\'a karşı gelmekten sakınanlara, Rab\'lerinin katında, altlarından ırmaklar akan ve orada temelli kalacakları cennetler, tertemiz eşler ve Allah\'ın rızası vardır. Allah kullarını hakkiyle görücüdür.'),
  ('tr.diyanet', 3, 16, 'Onlar ki, "Rabbimiz! Biz şüphesiz inandık, bunun için günahlarımızı bize bağışla ve bizi ateşin azabından koru" diyen, sabreden, doğru olan, gönülden kulluk eden, hayra sarfeden ve seher vakitlerinde bağışlanma dileyenlerdir.'),
  ('tr.diyanet', 3, 17, 'Onlar ki, "Rabbimiz! Biz şüphesiz inandık, bunun için günahlarımızı bize bağışla ve bizi ateşin azabından koru" diyen, sabreden, doğru olan, gönülden kulluk eden, hayra sarfeden ve seher vakitlerinde bağışlanma dileyenlerdir.'),
  ('tr.diyanet', 3, 18, 'Allah, melekler ve adaleti yerine getiren ilim sahibleri, O\'ndan başka tanrı olmadığına şahidlik etmişlerdir. O\'ndan başka tanrı yoktur, O güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 3, 19, 'Allah katında din, şüphesiz İslam\'dır. Ancak, Kitap verilenler, kendilerine ilim geldikten sonra, aralarındaki ihtiras yüzünden ayrılığa düştüler. Allah\'ın ayetlerini kim inkar ederse bilsin ki, Allah hesabı çabuk görür.'),
  ('tr.diyanet', 3, 20, 'Eğer seninle tartışmaya girişirlerse, "Ben bana uyanlarla birlikte kendimi Allah\'a verdim" de. Kendilerine Kitap verilenlere ve kitapsızlara: "Siz de İslam oldunuz mu?" de, şayet İslam olurlarsa doğru yola girmişlerdir, yüz çevirirlerse, sana yalnız tebliğ etmek düşer. Allah kullarını görür.'),
  ('tr.diyanet', 3, 21, 'Allah\'ın ayetlerini inkar edenlere, haksız yere peygamberleri öldürenlere, insanlardan adaleti emredenleri öldürenlere elem verici bir azabı müjdele.'),
  ('tr.diyanet', 3, 22, 'Onlar, dünya ve ahirette işleri boşa çıkacak olanlardır. Onların hiç yardımcıları da yoktur.'),
  ('tr.diyanet', 3, 23, 'Kendilerine Kitapdan bir pay verilenleri, görmedin mi? Onlar aralarında hüküm vermek için Allah\'ın Kitabına çağırılmışlar, sonra onlardan bir takımı dönmüşlerdir. Onlar temelli yüz çevirenlerdir.'),
  ('tr.diyanet', 3, 24, 'Bu, onların: "Bize ateş sadece sayılı birkaç gün değecektir" demelerindendir. Uydurup durdukları şeyler, onları dinlerinde yanıltmıştır.'),
  ('tr.diyanet', 3, 25, 'Geleceğinden şüphe olmayan günde, onları topladığımız ve haksızlık yapılmayarak herkese kazandığı eksiksiz verildiği zaman, nasıl olacak?'),
  ('tr.diyanet', 3, 26, 'De ki: "Mülkün sahibi olan Allah\'ım! Mülkü dilediğine verirsin; dilediğinden çekip alırsın; dilediğini aziz kılar, dilediğini alçaltırsın; iyilik elindedir. Doğrusu Sen, her şeye Kadir\'sin.'),
  ('tr.diyanet', 3, 27, 'Geceyi gündüze, gündüzü geceye geçirirsin; ölüden diri, diriden ölü çıkarırsın; dilediğini hesapsız rızıklandırırsın".'),
  ('tr.diyanet', 3, 28, 'Müminler, müminleri bırakıp kafirleri dost edinmesinler; kim böyle yaparsa Allah katında bir değeri yoktur, ancak, onlardan sakınmanız hali müstesnadır. Allah sizi Kendisiyle korkutur, dönüş Allah\'adır.'),
  ('tr.diyanet', 3, 29, 'De ki: "İçinizde olanı gizleseniz de açıklasanız da Allah onu bilir. Göklerde olanları da, yerde olanları da bilir. Allah her şeye Kadir\'dir".'),
  ('tr.diyanet', 3, 30, 'Her kişinin yaptığı iyiliği ve yaptığı kötülüğü, ki kendisiyle o kötülük arasında uzun bir mesafe olmasını diler, hazır bulacağı günü bir düşünün. Kullarına karşı şefkatli olan Allah size kendinden korkmanızı emreder.'),
  ('tr.diyanet', 3, 31, 'De ki: "Allah\'ı seviyorsanız bana uyun. Allah da sizi sevsin ve günahlarınızı bağışlasın. Allah affeder ve merhamet eder".'),
  ('tr.diyanet', 3, 32, 'De ki: "Allah\'a ve Peygambere itaat edin". Yüz çevirirlerse bilsinler ki, Allah inkar edenleri sevmez.'),
  ('tr.diyanet', 3, 33, 'Allah, Adem\'i, Nuh\'u, İbrahim ailesini, İmran ailesini birbirinin soyundan olarak alemlere tercih etti. Allah işitendir, bilendir.'),
  ('tr.diyanet', 3, 34, 'Allah, Adem\'i, Nuh\'u, İbrahim ailesini, İmran ailesini birbirinin soyundan olarak alemlere tercih etti. Allah işitendir, bilendir.'),
  ('tr.diyanet', 3, 35, 'İmran\'ın karısı: "Ya Rabbi! Karnımda olanı, sadece sana hizmet etmek üzere adadım, benden kabul buyur, doğrusu işiten ve bilen ancak Sensin" demişti.'),
  ('tr.diyanet', 3, 36, 'Onu doğurduğunda, Allah onun ne doğurduğunu bilirken "Ya Rabbi! Kız doğurdum. Erkek, kız gibi değildir, ben ona Meryem adını verdim, ben onu da soyunu da, kovulmuş şeytandan Sana sığındırırım" dedi.'),
  ('tr.diyanet', 3, 37, 'Rabbi onu güzel bir kabulle karşıladı, güzel bir bitki gibi yetiştirdi; onu Zekeriya\'nın himayesine bıraktı. Zekeriya mabedde onun yanına her girişinde, yanında bir yiyecek bulurdu. "Ey Meryem! Bu sana nereden geldi?" demiş, o da: Bu, Allah\'ın katındandır" cevabını vermişti. Doğrusu Allah dilediğini hesapsız rızıklandırır.'),
  ('tr.diyanet', 3, 38, 'Orada Zekeriya Rabbine dua etti: "Ya Rabbi! Bana kendi katından temiz bir soy bahşet, doğrusu Sen duayı işitirsin".'),
  ('tr.diyanet', 3, 39, 'Mabedde namaz kılarken melekler ona seslendiler: "Allah sana Allah\'ın emriyle (vücud bulan İsa\'yı) tasdik eden, efendi, iffetli, iyilerden bir peygamber olarak Yahya\'yı müjdeler".'),
  ('tr.diyanet', 3, 40, '"Ya Rabbi! Ben artık iyice kocamış, karım da kısırken nasıl oğlum olabilir?" dedi. Allah: "Böyledir, Allah dilediğini yapar" dedi.'),
  ('tr.diyanet', 3, 41, '"Ya Rabbi! Bana bir alamet ver" dedi, "Alametin, üç gün, işaretle anlaşma dışında insanlarla konuşmamandır; Rabbini çok an, akşam sabah hamd et" dedi.'),
  ('tr.diyanet', 3, 42, 'Melekler şöyle demişti: "Ey Meryem! Allah seni seçip temizledi. Dünyaların kadınlarından seni üstün tuttu."'),
  ('tr.diyanet', 3, 43, '"Ey Meryem! Rabbine gönülden boyun eğ, secde et, rüku edenlerle birlikte rüku et."'),
  ('tr.diyanet', 3, 44, 'Bu Sana vahyettiğimiz gayb haberlerindendir. Meryem\'e hangisi kefil olacak diye kalemlerini atarlarken sen yanlarında değildin, çekişirlerken de orada bulunmadın.'),
  ('tr.diyanet', 3, 45, 'Melekler demişti ki: "Ey Meryem! Allah sana, Kendinden bir sözü, adı Meryem oğlu İsa olan Mesihi, dünya ve ahirette şerefli ve Allah\'a yakın kılınanlardan olarak müjdeler".'),
  ('tr.diyanet', 3, 46, '"İnsanlarla, beşikte iken de, yetişkin iken de konuşacaktır ve o, iyilerdendir".'),
  ('tr.diyanet', 3, 47, 'Meryem: "Rabbim! Bana bir insan dokunmamışken nasıl çocuğum olabilir?" demişti. Melekler şöyle dediler: "Allah dilediğini böylece yaratır. Bir işin olmasını dilerse ona ol der ve olur".'),
  ('tr.diyanet', 3, 48, 'Ona Kitabı, hikmeti, Tevrat\'ı ve İncil\'i öğretecek, İsrailoğullarına şöyle diyen bir peygamber kılacak: "Ben size Rabbinizden bir ayet getirdim. Ben size çamurdan kuş gibi bir şey yapıp ona üfleyeceğim, Allah\'ın izniyle, hemen kuş olacaktır; anadan doğma körleri, alacalıları iyi edeceğim; Allah\'ın izniyle, ölüleri dirilteceğim; yediklerinizi ve evlerinizde sakladıklarınızı da size haber vereceğim. İnanmışsanız bunda size delil vardır".'),
  ('tr.diyanet', 3, 49, 'Ona Kitabı, hikmeti, Tevrat\'ı ve İncil\'i öğretecek, İsrailoğullarına şöyle diyen bir peygamber kılacak: "Ben size Rabbinizden bir ayet getirdim. Ben size çamurdan kuş gibi bir şey yapıp ona üfleyeceğim, Allah\'ın izniyle, hemen kuş olacaktır; anadan doğma körleri, alacalıları iyi edeceğim; Allah\'ın izniyle, ölüleri dirilteceğim; yediklerinizi ve evlerinizde sakladıklarınızı da size haber vereceğim. İnanmışsanız bunda size delil vardır".'),
  ('tr.diyanet', 3, 50, '"Benden önce gelen Tevrat\'ı tasdik etmekle beraber size yasak edilenlerin bir kısmını helal kılmak üzere, Rabbinizden size bir ayet getirdim. Allah\'tan sakının ve bana itaat edin; çünkü Allah benim de Rabbim, sizin de Rabbinizdir. O\'na kulluk edin, bu doğru yoldur".'),
  ('tr.diyanet', 3, 51, '"Benden önce gelen Tevrat\'ı tasdik etmekle beraber size yasak edilenlerin bir kısmını helal kılmak üzere, Rabbinizden size bir ayet getirdim. Allah\'tan sakının ve bana itaat edin; çünkü Allah benim de Rabbim, sizin de Rabbinizdir. O\'na kulluk edin, bu doğru yoldur".'),
  ('tr.diyanet', 3, 52, 'İsa onların inkarlarını hissedince: "Allah uğrunda yardımcılarım kimlerdir?" dedi. Havariler şöyle dediler: "Biz Allah\'ın yardımcılarıyız, Allah\'a inandık, O\'na teslim olduğumuza şahid ol".'),
  ('tr.diyanet', 3, 53, '"Rabbimiz! İndirdiğine inandık, Peygambere uyduk; bizi sahid olanlarla beraber yaz".'),
  ('tr.diyanet', 3, 54, 'Fakat (inkarcılar) hile yaptılar. Allah da onları cezalandırdı. Allah, hile yapanların cezasını en iyi verendir.'),
  ('tr.diyanet', 3, 55, 'Allah demişti ki: "Ey İsa! Ben seni eceline yetireceğim, seni kendime yükselteceğim, inkar edenlerden seni tertemiz ayıracağım; sana uyanları, kıyamet gününe kadar, inkar edenlerin üstünde tutacağım. Sonra dönüşünüz Banadır. Ayrılığa düştüğünüz hususlarda aranızda hükmedeceğim. İnkar edenleri de dünya ve ahirette şiddetli azaba uğratacağım. Onların hiç yardımcıları olmayacaktır."'),
  ('tr.diyanet', 3, 56, 'Allah demişti ki: "Ey İsa! Ben seni eceline yetireceğim, seni kendime yükselteceğim, inkar edenlerden seni tertemiz ayıracağım; sana uyanları, kıyamet gününe kadar, inkar edenlerin üstünde tutacağım. Sonra dönüşünüz Banadır. Ayrılığa düştüğünüz hususlarda aranızda hükmedeceğim. İnkar edenleri de dünya ve ahirette şiddetli azaba uğratacağım. Onların hiç yardımcıları olmayacaktır."'),
  ('tr.diyanet', 3, 57, 'İnanıp yararlı iş işleyenlerin ecirleri ise tastamam verilecektir. Allah zalimleri sevmez.'),
  ('tr.diyanet', 3, 58, 'Sana okuduğumuz bunlar, ayetlerden ve hikmet dolu Kuran\'dandır.'),
  ('tr.diyanet', 3, 59, 'Allah\'ın katında İsa\'nın durumu kendisini topraktan yaratıp sonra ol demesiyle olmuş olan Adem\'in durumu gibidir.'),
  ('tr.diyanet', 3, 60, 'Gerçek Rabb\'indendir, o halde şüphelenenlerden olma.'),
  ('tr.diyanet', 3, 61, 'Sana ilim geldikten sonra, bu hususta seninle kim tartışacak olursa, de ki: "Gelin, oğullarımızı, oğullarınızı, kadınlarımızı, kadınlarınızı, kendimizi ve kendinizi çağıralım, sonra lanetleşelim de, Allah\'ın lanetinin yalancılara olmasını dileyelim".'),
  ('tr.diyanet', 3, 62, 'Şüphesiz bu anlatılanlar gerçek olaylardır. Allah\'tan başka tanrı yoktur. Doğrusu Allah güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 3, 63, 'Eğer yüz çevirirlerse, şüphesiz Allah bozguncuları bilir.'),
  ('tr.diyanet', 3, 64, 'De ki: "Ey Kitap ehli! Ancak Allah\'a kulluk etmek, O\'na bir şeyi eş koşmamak, Allah\'ı bırakıp birbirimizi rab olarak benimsememek üzere, bizimle sizin aranızda müşterek bir söze gelin". Eğer yüz çevirirlerse: "Bizim müslüman olduğumuza şahid olun" deyin.'),
  ('tr.diyanet', 3, 65, 'Ey Kitap ehli! İbrahim hakkında niçin tartışıyorsunuz? Tevrat da, İncil de şüphesiz ondan sonra indirilmiştir. Akletmiyor musunuz?'),
  ('tr.diyanet', 3, 66, 'Siz, hadi bilginiz olan şey üzerinde tartışanlarsınız. Ama bilginiz olmayan şey hakkında niçin tartışırsınız? Oysa Allah bilir, sizler bilmezsiniz.'),
  ('tr.diyanet', 3, 67, 'İbrahim, yahudi de, hıristiyan da değildi, ama doğruya yönelen bir müslimdi; ortak koşanlardan değildi.'),
  ('tr.diyanet', 3, 68, 'Doğrusu İbrahim\'e en yakın olanlar, ona uyanlar, bu Peygamber ve inananlardır. Allah inananların dostudur.'),
  ('tr.diyanet', 3, 69, 'Kitap ehlinden bir takımı sizi sapıtmak isterler; oysa kendilerini saptırırlar da farkına varmazlar.'),
  ('tr.diyanet', 3, 70, 'Ey Kitap ehli! Sizler göz göre göre Allah\'ın ayetlerini niçin inkar ediyorsunuz?'),
  ('tr.diyanet', 3, 71, 'Ey Kitap ehli! Niçin hakkı batıla karıştırıyor ve bile bile hakkı gizliyorsunuz?'),
  ('tr.diyanet', 3, 72, 'Kitap ehlinden bir takımı şöyle dedi: "İnananlara indirilene günün başında inanın, sonunda inkar edin ki, belki dönerler ve dininize uyanlardan başkasına inanmayın". De ki: "Doğru yol Allah\'ın yoludur". Ve yine başkasına da verildiğine veya Rabbinizin katında Müslümanların karşı delil getirip sizi alt edeceğine inanmayın, derler. De ki: "Doğrusu bol nimet Allah\'ın elindedir, onu dilediğine verir. Allah\'ın fazlı her şeyi kaplar, O her şeyi bilir".'),
  ('tr.diyanet', 3, 73, 'Kitap ehlinden bir takımı şöyle dedi: "İnananlara indirilene günün başında inanın, sonunda inkar edin ki, belki dönerler ve dininize uyanlardan başkasına inanmayın". De ki: "Doğru yol Allah\'ın yoludur". Ve yine başkasına da verildiğine veya Rabbinizin katında Müslümanların karşı delil getirip sizi alt edeceğine inanmayın, derler. De ki: "Doğrusu bol nimet Allah\'ın elindedir, onu dilediğine verir. Allah\'ın fazlı her şeyi kaplar, O her şeyi bilir".'),
  ('tr.diyanet', 3, 74, '"Rahmetini dilediğine tahsis eder, Allah büyük, bol nimet sahibidir".'),
  ('tr.diyanet', 3, 75, 'Kitap ehli arasında kantarla emanet bıraksan onu sana ödeyen ve bir lira emanet etsen, tepesine dikilmedikçe onu sana ödemeyen vardır. Bu, onların: "Kitapsızlara karşı üzerimize bir sorumluluk yoktur" demelerindendir. Onlar bile bile Allah\'a karşı yalan söylemektedirler.'),
  ('tr.diyanet', 3, 76, 'Hayır, öyle değil; ahdini yerine getiren ve günahtan sakınan bilsin ki, Allah sakınanları şüphesiz sever.'),
  ('tr.diyanet', 3, 77, 'Allah\'ın ahdini ve yeminlerini az bir değere değişenlerin, işte onların, ahirette bir payları yoktur. Allah onlara kıyamet günü hitab etmeyecek, onlara bakmayacak, onları temize çıkarmayacaktır. Elem verici azab onlar içindir.'),
  ('tr.diyanet', 3, 78, 'Onlardan bir takımı, Kitapta olmadığı halde Kitaptan zannedesiniz diye dillerini eğip bükerler. O, Allah katından olmadığı halde: "Allah katındandır" derler, bile bile Allah\'a karşı yalan söylerler.'),
  ('tr.diyanet', 3, 79, 'Allah\'ın kendisine Kitap\'ı, hükmü, peygamberliği verdiği insanoğluna: "Allah\'ı bırakıp bana kulluk edin" demek yaraşmaz, fakat: "Kitabı öğrettiğinize, okuduğunuza göre Rabb\'e kul olun" demek yaraşır.'),
  ('tr.diyanet', 3, 80, 'Size melekleri, peygamberleri Rab olarak benimsemenizi emretmesi de yaraşmaz. Siz müslüman olduktan sonra, size inkar etmeyi mi emredecek?'),
  ('tr.diyanet', 3, 81, 'Allah peygamberlerden ahid almıştı: "And olsun ki size Kitap, hikmet verdim; sizde olanı tasdik eden bir peygamber gelecek, ona mutlaka inanacaksınız ve ona mutlaka yardım edeceksiniz, ikrar edip bu ahdi kabul ettiniz mi?" demişti. "İkrar ettik" demişlerdi de: "Şahid olun, Ben de sizinle beraber şahidlerdenim" demişti.'),
  ('tr.diyanet', 3, 82, 'Bunun ardından yüz çeviren var ya, işte onlar fasık olanlardır.'),
  ('tr.diyanet', 3, 83, 'Allah\'ın dininden başka bir din mi arzu ediyorlar? Oysa göklerde ve yerde kim varsa, ister istemez O\'na teslim olmuştur, O\'na döneceklerdir.'),
  ('tr.diyanet', 3, 84, '"Allah\'a, bize indirilene, İbrahim\'e, İsmail\'e, İshak\'a, Yakub\'a ve torunlarına indirilene, Rableri tarafından Musa, İsa ve peygamberlere verilene inandık, onları birbirinden ayırt etmeyiz, biz O\'na teslim olanlarız" de.'),
  ('tr.diyanet', 3, 85, 'Kim İslam\'dan başka bir dine yönelirse, onunki kabul edilmeyecektir. O ahirette de kaybedenlerdendir.'),
  ('tr.diyanet', 3, 86, 'İnandıktan, peygamberin hak olduğuna şehadet ettikten, kendilerine belgeler geldikten sonra inkar eden bir milleti Allah nasıl doğru yola eriştirir? Allah zalimleri doğru yola eriştirmez.'),
  ('tr.diyanet', 3, 87, 'İşte bunların cezası, Allah\'ın, meleklerin, insanların hepsinin lanetine uğramalarıdır.'),
  ('tr.diyanet', 3, 88, 'Orada temellidirler; onlardan azab hafifletilmez; onların azabı geciktirilmez.'),
  ('tr.diyanet', 3, 89, 'Ancak bunun ardından tevbe edip düzelenler müstesnadır. Doğrusu Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 3, 90, 'İnandıktan sonra inkar edip, inkarda aşırı gidenler var ya, onların tevbeleri kabul edilmeyecektir. İşte sapıklar onlardır.'),
  ('tr.diyanet', 3, 91, 'Doğrusu inkar edip, inkarcı olarak ölenlerin hiçbirinden, yeryüzünü dolduracak kadar altını fidye vermiş olsa bile, bu kabul edilmeyecektir. İşte elem verici azab onlaradır, onların hiç yardımcıları da yoktur.'),
  ('tr.diyanet', 3, 92, 'Sevdiğiniz şeylerden sarfetmedikçe iyiliğe erişemezsiniz. Her ne sarfederseniz, şüphesiz Allah onu bilir.'),
  ('tr.diyanet', 3, 93, 'Tevrat\'ın indirilmesinden önce İsrail\'in kendisine haram ettiğinden başka bütün yiyecekler İsrailoğullarına helal idi. De ki: "Doğru sözlü iseniz Tevrat\'ı getirip okuyun".'),
  ('tr.diyanet', 3, 94, 'Bundan sonra Allah\'a karşı kim yalan isnad ederse, işte onlar zalimlerdir.'),
  ('tr.diyanet', 3, 95, 'De ki: "Allah doğru söyledi, doğruya meyleden İbrahim\'in dinine uyun; O, puta tapanlardan değildi".'),
  ('tr.diyanet', 3, 96, 'Doğrusu insanlar için ilk kurulan ev, Mekke\'de, dünyalar için mübarek ve doğru yol gösteren Kabe\'dir.'),
  ('tr.diyanet', 3, 97, 'Orada apaçık deliller vardır, İbrahim\'in makamı vardır; kim oraya girerse, güvenlik içinde olur; oraya yol bulabilen insana Allah için Kabe\'yi haccetmesi gereklidir. Kim inkar ederse, bilsin ki; doğrusu Allah alemlerden müstağnidir.'),
  ('tr.diyanet', 3, 98, 'De ki: "Ey Kitap ehli! Allah yaptıklarınızı görüp dururken, niçin Allah\'ın ayetlerini inkar ediyorsunuz?"'),
  ('tr.diyanet', 3, 99, 'De ki: "Ey Kitap ehli! Siz doğru olduğuna şahidken, niçin inananları Allah\'ın yolunu eğri göstermeğe yeltenerek ondan çeviriyorsunuz? Allah işlediklerinizden gafil değildir".'),
  ('tr.diyanet', 3, 100, 'Ey İnananlar! Kitap verilenlerin bir takımına uyarsanız, inanmanızdan sonra sizi kafir olmağa çevirirler.'),
  ('tr.diyanet', 3, 101, 'Allah\'ın ayetleri size okunur, aranızda da Peygamberi bulunurken nasıl inkar edersiniz? Kim Allah\'ın Kitabına sarılırsa şüphesiz doğru yola erişir.'),
  ('tr.diyanet', 3, 102, 'Ey inananlar! Allah\'tan, sakınılması gerektiği gibi sakının, sizler ancak müslüman olarak can verin.'),
  ('tr.diyanet', 3, 103, 'Toptan Allah\'ın ipine sarılın, ayrılmayın. Allah\'ın size olan nimetini anın: Düşmandınız, kalblerinizin arasını uzlaştırdı da onun nimeti sayesinde kardeş oldunuz. Bir ateş çukurunun kenarında idiniz, sizi oradan kurtardı. Allah, doğru yola erişesiniz diye size böylece ayetlerini açıklar.'),
  ('tr.diyanet', 3, 104, 'Sizden, iyiye çağıran, doğruluğu emreden ve fenalıktan meneden bir cemaat olsun. İşte başarıya erişenler yalnız onlardır.'),
  ('tr.diyanet', 3, 105, 'Kendilerine belgeler geldikten sonra ayrılan ve ayrılığa düşenler gibi olmayın. Bir takım yüzlerin ağaracağı ve bir takım yüzlerin kararacağı günde büyük azab onlaradır. Yüzleri kararanlara: "İnanmanızdan sonra inkar eder misiniz? İnkar etmenizden dolayı tadın azabı" denecektir.'),
  ('tr.diyanet', 3, 106, 'Kendilerine belgeler geldikten sonra ayrılan ve ayrılığa düşenler gibi olmayın. Bir takım yüzlerin ağaracağı ve bir takım yüzlerin kararacağı günde büyük azab onlaradır. Yüzleri kararanlara: "İnanmanızdan sonra inkar eder misiniz? İnkar etmenizden dolayı tadın azabı" denecektir.'),
  ('tr.diyanet', 3, 107, 'Yüzleri ağaranlar ise Allah\'ın rahmetindedirler. Onlar orada temellidirler.'),
  ('tr.diyanet', 3, 108, 'İşte bunlar, sana doğru olarak okuduğumuz Allah\'ın ayetleridir. Allah hiç kimseye zulmetmek istemez.'),
  ('tr.diyanet', 3, 109, 'Göklerde olanlar da, yerde olanlar da Allah\'ındır. İşler Allah\'a varacaktır.'),
  ('tr.diyanet', 3, 110, 'Siz, insanlar için ortaya çıkarılan, doğruluğu emreden, fenalıktan alıkoyan, Allah\'a inanan hayırlı bir ümmetsiniz. Kitap ehli inanmış olsalardı, kendileri için daha hayırlı olurdu; içlerinde inananlar olmakla beraber, çoğu yoldan çıkmıştır.'),
  ('tr.diyanet', 3, 111, 'Onlar incitmekten başka size bir zarar veremezler. Sizinle savaşa koyulurlarsa, geri dönüp kaçarlar. Sonra kendilerine yardım da edilmez.'),
  ('tr.diyanet', 3, 112, 'Nerede bulunsalar Allah\'ın ve inanan insanların himayesinde olanlar müstesna onlara alçaklık damgası vurulmuştur. Allah\'tan bir gazaba uğradılar, onlara aşağılık damgası vuruldu. Bu, Allah\'ın ayetlerini inkar etmeleri ve haksız yere peygamberleri öldürmelerindendir. Bu, karşı gelmeleri ve taşkınlık yapmalarındandır.'),
  ('tr.diyanet', 3, 113, 'Kitap ehlinin hepsi bir değildir: Onlardan geceleri secdeye kapanarak Allah\'ın ayetlerini okuyup duranlar vardır; bunlar Allah\'a ve ahiret gününe inanır, kötülükten meneder, iyiliklere koşarlar. İşte onlar iyilerdendir.'),
  ('tr.diyanet', 3, 114, 'Kitap ehlinin hepsi bir değildir: Onlardan geceleri secdeye kapanarak Allah\'ın ayetlerini okuyup duranlar vardır; bunlar Allah\'a ve ahiret gününe inanır, kötülükten meneder, iyiliklere koşarlar. İşte onlar iyilerdendir.'),
  ('tr.diyanet', 3, 115, 'Ne iyilik yaparlarsa, karşılığını bulacaklardır. Allah sakınanları bilir.'),
  ('tr.diyanet', 3, 116, 'İnkar eden kimselerin malları ve çocukları, Allah\'tan yana, onlara bir fayda vermeyecektir. İşte onlar cehennemliklerdir, onlar orada temellidirler.'),
  ('tr.diyanet', 3, 117, 'Bu dünya hayatında sarfettiklerinin durumu, kendilerine zulmeden kimselerin ekinlerine isabetle kavurup mahveden soğuk bir rüzgarın durumu gibidir. Allah onlara zulmetmedi, onlar kendilerine yazık ettiler.'),
  ('tr.diyanet', 3, 118, 'Ey İnananlar! Sizden olmayanı sırdaş edinmeyin, onlar sizi şaşırtmaktan geri durmazlar, sıkıntıya düşmenizi isterler. Onların öfkesi ağızlarından taşmaktadır, kalblerinin gizlediği ise daha büyüktür. Eğer aklediyorsanız, şüphesiz size ayetleri açıkladık.'),
  ('tr.diyanet', 3, 119, 'İşte siz, onlar sizi sevmezken onları seven ve Kitapların bütününe inanan kimselersiniz. Size rastladıkları zaman: "İnandık" derler, yalnız kaldıklarında da, size öfkelerinden parmaklarını ısırırlar. De ki: "Öfkenizden çatlayın". Allah kalblerde olanı bilir.'),
  ('tr.diyanet', 3, 120, 'Size bir iyilik gelse, onların fenasına gider; başınıza bir kötülük gelse buna sevinirler. Sabreder ve sakınırsanız, onların hilesi size hiçbir zarar vermez. Allah işlediklerinin hepsini ilmiyle kuşatmıştır.'),
  ('tr.diyanet', 3, 121, 'Sen inananları savaş için duracakları yerlere yerleştirmek üzere, erkenden evinden ayrılmıştın. Allah işitir ve bilir.'),
  ('tr.diyanet', 3, 122, 'Sizden iki takım bozulup geri çekilmek üzere idi; oysa Allah onların dostu idi, inananlar yalnız Allah\'a güvensinler.'),
  ('tr.diyanet', 3, 123, 'And olsun ki, siz düşkün bir durumda iken, Bedir\'de, Allah size yardım etmişti; Allah\'tan sakının ki şükredebilesiniz.'),
  ('tr.diyanet', 3, 124, 'İnananlara: "Rabbinizin size gönderilmiş üç bin melekle yardım etmesi size yetmeyecek mi?" diyordun. Evet, eğer sabrederseniz, sakınırsanız ve onlar de hemen üzerinize gelirlerse Rabbiniz size, nişanlı beş bin melekle imdat edecektir.'),
  ('tr.diyanet', 3, 125, 'İnananlara: "Rabbinizin size gönderilmiş üç bin melekle yardım etmesi size yetmeyecek mi?" diyordun. Evet, eğer sabrederseniz, sakınırsanız ve onlar de hemen üzerinize gelirlerse Rabbiniz size, nişanlı beş bin melekle imdat edecektir.'),
  ('tr.diyanet', 3, 126, 'Allah bunu, ancak size müjde olsun ve böylece kalbleriniz yatışsın diye yapmıştır. İnkar edenlerin bir kısmını kesmek veya ümidsiz olarak geri dönecek şekilde bozguna uğratmak için gereken yardım, ancak Güçlü ve Hakim olan Allah katından olur.'),
  ('tr.diyanet', 3, 127, 'Allah bunu, ancak size müjde olsun ve böylece kalbleriniz yatışsın diye yapmıştır. İnkar edenlerin bir kısmını kesmek veya ümidsiz olarak geri dönecek şekilde bozguna uğratmak için gereken yardım, ancak Güçlü ve Hakim olan Allah katından olur.'),
  ('tr.diyanet', 3, 128, 'Allah\'ın, onların tevbelerini kabul veya onlara azab etmesi işiyle senin bir ilişiğin yoktur; çünkü onlar zalimlerdir.'),
  ('tr.diyanet', 3, 129, 'Göklerde olanlar da, yerde olanlar da Allah\'ındır. Dilediğini bağışlar, dilediğine azab eder. Allah bağışlayandır, merhamet edendir.'),
  ('tr.diyanet', 3, 130, 'Ey İnananlar! Faizi kat kat alarak yemeyin. Allah\'tan sakının ki başarıya erişesiniz.'),
  ('tr.diyanet', 3, 131, 'İnkar edenler için hazırlanmış ateşten sakının.'),
  ('tr.diyanet', 3, 132, 'Size merhamet edilmesi için, Allah\'a ve Peygamber\'e itaat edin.'),
  ('tr.diyanet', 3, 133, 'Rabbinizin mağfiretine ve Allah\'a karşı gelmekten sakınanlar için hazırlanmış eni gökler ve yer kadar olan cennete koşuşun.'),
  ('tr.diyanet', 3, 134, 'Onlar bollukta ve darlıkta sarfederler, öfkelerini yenerler, insanların kusurlarını affederler. Allah iyilik yapanları sever.'),
  ('tr.diyanet', 3, 135, 'Onlar fena bir şey yaptıklarında veya kendilerine zulmettiklerinde Allah\'ı anarlar, günahlarının bağışlanmasını dilerler. Günahları Allah\'tan başka bağışlayan kim vardır? Onlar, yaptıklarında bile bile direnmezler.'),
  ('tr.diyanet', 3, 136, 'Onların hareketlerinin karşılığı Rablerinden bağışlanma ve altlarından ırmaklar akan, içinde temelli kalacakları cennetlerdir. İyi davrananların ne güzel ecri vardır!'),
  ('tr.diyanet', 3, 137, 'Sizden önce neler gelip geçmiştir. Yeryüzünde gezin de, yalancıların sonunun ne olduğuna bir bakın.'),
  ('tr.diyanet', 3, 138, 'Bu Kuran, insanlara bir açıklama, sakınanlara yol gösterme ve bir öğüttür.'),
  ('tr.diyanet', 3, 139, 'Gevşemeyin, üzülmeyin, inanmışsanız, mutlaka siz en üstünsünüzdür.'),
  ('tr.diyanet', 3, 140, 'Eğer siz (Uhud\'da) bir yara almışsanız, (size düşman olan) o topluluk da (Bedir\'de) benzeri bir yara almıştı. Böylece biz, Allah\'ın gerçek müminleri ortaya çıkarması ve içinizden şahitler edinmesi için, bu günleri bazen lehe, bazen de aleyhe döndürüp duruyoruz. Allah, zulmedenleri sevmez.'),
  ('tr.diyanet', 3, 141, 'Bir de Allah, böylece iman edenleri günahlardan arıtmak, inkarcıları ise yok etmek ister.'),
  ('tr.diyanet', 3, 142, 'Yoksa içinizden Allah cihad edenleri ve sabredenleri belirtmeden cennete gireceğinizi mi sanıyordunuz?'),
  ('tr.diyanet', 3, 143, 'And olsun ki, ölümle karşılaşmadan önce onu temenni ediyordunuz; işte onu gözlerinizle bakarak gördünüz.'),
  ('tr.diyanet', 3, 144, 'Muhammed ancak bir peygamberdir. Ondan önce de peygamberler geçmişti. Ölür veya öldürülürse geriye mi döneceksiniz? Geriye dönen, Allah\'a hiçbir zarar vermez. Allah şükredenlerin mükafatını verecektir.'),
  ('tr.diyanet', 3, 145, 'Hiçbir kimse Allah\'ın izni olmadan ölmez; o, belli bir vakte bağlanmıştır. Kim dünya nimetini isterse ona ondan veririz; ve kim ahiret nimetini isterse ona ondan veririz. Şükredenlerin mükafatını vereceğiz.'),
  ('tr.diyanet', 3, 146, 'Nice peygamberlerin yanında Rabbe kul olmuş pek çok kimse savaşmıştır. Allah yolunda başlarına gelenlerden ötürü gevşememişler, yılmamışlar ve boyun eğmemişlerdi. Allah, sabredenleri sever.'),
  ('tr.diyanet', 3, 147, 'Dedikleri ancak şu idi: "Rabbimiz! Günahlarımızı, işimizdeki aşırılıklarımızı bize bağışla, sebatımızı arttır, inkarcı topluluğa karşı bize yardım et".'),
  ('tr.diyanet', 3, 148, 'Bu yüzden Allah onlara dünya nimetini de ahiret nimetini de fazlasiyle verdi. Allah işlerini iyi yapanları sever.'),
  ('tr.diyanet', 3, 149, 'Ey İnananlar! İnkar edenlere itaat ederseniz, sizi geriye döndürürler de kayba uğrarsınız.'),
  ('tr.diyanet', 3, 150, 'Halbuki Mevlanız Allah\'tır. O, yardımcıların en iyisidir.'),
  ('tr.diyanet', 3, 151, 'Hakkında hiçbir delil indirmediği şeyi Allah\'a ortak koşmalarından ötürü, inkar edenlerin kalbine korku salacağız. Onların varacağı yer cehennemdir. Zalimlerin durağı ne kötüdür!'),
  ('tr.diyanet', 3, 152, 'And olsun ki, Allah, size verdiği sözde durdu. Onun izniyle kafirleri kırıp biçiyordunuz, ama Allah size arzuladığınız zaferi gösterdikten sonra gevşeyip bu hususta çekiştiniz ve isyan ettiniz; sizden kimi dünyayı, kimi ahireti istiyordu; derken denemek için Allah sizi geri çevirip bozguna uğrattı. And olsun ki O, sizi bağışladı. Allah\'ın inananlara nimeti boldur.'),
  ('tr.diyanet', 3, 153, 'Peygamber arkanızdan sizi çağırırken, kimseye bakmadan kaçıyordunuz; kaybettiğinize ve başınıza gelene üzülmeyesiniz diye, Allah sizi kederden kedere uğrattı. Allah, işlediklerinizden haberdardır.'),
  ('tr.diyanet', 3, 154, 'Kederden sonra, bir takımınızı kendinden geçirecek şekilde size huzur ve emniyet indirdi; oysa bir takımınız da kendi derdlerine düşmüşlerdi. Haksız yere Allah hakkında, cahiliye devrinde olduğu gibi inanıyorlar. "Bu işte bizim bir fikrimiz var mı?" diyorlardı; De ki: "Buyruğun hepsi Allah\'ındır". Sana açmadıklarını içlerinde gizliyorlar. "Bu işte bizim fikrimiz alınsaydı, burada öldürülmezdik" diyorlar. De ki: Evlerinizde olsaydınız, haklarında ölüm yazılı olan kimseler, yine de devrilecekleri yere varırlardı. Bu, Allah\'ın içinizde olanı denemesi, kalblerinizde olanı arıtması içindir. Allah gönüllerde olanı bilir.'),
  ('tr.diyanet', 3, 155, 'İki topluluğun karşılaştığı gün, içinizden yüz çevirenlerin, yaptıklarının bir kısmından ötürü şeytan ayaklarını kaydırıp yoldan çıkarmak istemişti. Allah, and olsun ki, onları affetti. Allah bağışlayandır. Halim\'dir.'),
  ('tr.diyanet', 3, 156, 'Ey İnananlar! Yolculuğa çıkan veya savaşa giden kardeşleri hakkında: "Onlar yanımızda olsalardı ölmezler ve öldürülmezlerdi" diyen inkarcılar gibi olmayın ki, Allah bunu onların kalblerinde bir hasret olarak bıraksın. Dirilten de öldüren de Allah\'tır. Allah işlediklerinizi görür.'),
  ('tr.diyanet', 3, 157, 'Allah yolunda öldürülür veya ölürseniz, size Allah\'tan onların topladıklarından hayırlı bir mağfiret ve rahmet vardır.'),
  ('tr.diyanet', 3, 158, 'And olsun ki, ölseniz de, öldürülseniz de Allah katında toplanacaksınız.'),
  ('tr.diyanet', 3, 159, 'Allah\'ın rahmetinden dolayı, sen onlara karşı yumuşak davrandın. Eğer kaba ve katı kalbli olsaydın, şüphesiz etrafından dağılır giderlerdi. Onları affet, onlara mağfiret dile, iş hakkında onlara danış, fakat karar verdin mi Allah\'a güven, doğrusu Allah güvenenleri sever.'),
  ('tr.diyanet', 3, 160, 'Allah size yardım ederse, sizi yenecek yoktur; eğer sizi yardımsız bırakıverirse, O\'ndan başka size yardım edecek kimdir? İnananlar yalnız Allah\'a güvensinler.'),
  ('tr.diyanet', 3, 161, 'Hiçbir peygambere ganimete ve millet malına hiyanet yaraşmaz; haksızlık kim yaparsa, kıyamet günü yaptığı ile gelir, sonra, haksızlık yapılmaksızın herkese kazanmış olduğu ödenir.'),
  ('tr.diyanet', 3, 162, 'Allah\'ın rızasına uyan kimse, Allah\'ın hışmına uğrayan gibi midir? Bu kimsenin varacağı yer cehennemdir; o ne kötü varılacak yerdir!'),
  ('tr.diyanet', 3, 163, 'Onlar Allah katında derece derecedir. Allah, işlediklerini görmektedir.'),
  ('tr.diyanet', 3, 164, 'And olsun ki Allah, inananlara, ayetlerini okuyan, onları arıtan, onlara Kitap ve hikmeti öğreten, kendilerinden bir peygamber göndermekle iyilikte bulunmuştur. Halbuki onlar, önceleri apaçık sapıklıkta idiler.'),
  ('tr.diyanet', 3, 165, 'Başkalarını iki misline uğrattığınız bir musibete kendiniz uğrayınca mı: "Bu nereden?" dersiniz? De ki: "O, kendi tarafınızdandır". Doğrusu Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 3, 166, 'İki topluluğun karşılaştığı günde başınıza gelen, Allah\'ın izniyledir. Bu, inananları da, münafıklık edenleri de belirtmesi içindir. Münafıklık edenlere: "gelin, Allah yolunda savaşın, veya hiç olmazsa savunmada bulunun" dendiği zaman: "Eğer savaşmayı bilseydik, ardınızdan gelirdik" dediler. O gün, onlar imandan çok inkara yakındılar. Kalblerinde olmayanı ağızlarıyla söylüyorlar. Allah gizlediklerini onlardan iyi bilir.'),
  ('tr.diyanet', 3, 167, 'İki topluluğun karşılaştığı günde başınıza gelen, Allah\'ın izniyledir. Bu, inananları da, münafıklık edenleri de belirtmesi içindir. Münafıklık edenlere: "gelin, Allah yolunda savaşın, veya hiç olmazsa savunmada bulunun" dendiği zaman: "Eğer savaşmayı bilseydik, ardınızdan gelirdik" dediler. O gün, onlar imandan çok inkara yakındılar. Kalblerinde olmayanı ağızlarıyla söylüyorlar. Allah gizlediklerini onlardan iyi bilir.'),
  ('tr.diyanet', 3, 168, 'Onlar oturup, kardeşleri için: "Bize itaat etselerdi öldürülmezlerdi" dediler. De ki: "Eğer doğru sözlü iseniz, ölümü kendinizden savın".'),
  ('tr.diyanet', 3, 169, 'Allah yolunda öldürülenleri ölü saymayın, bilakis Rableri katında diridirler. Allah\'ın bol nimetinden onlara verdiği şeylerle sevinç içinde rızıklanırlar, arkalarından kendilerine ulaşamayan kimselere, kendilerine korku olmadığını ve kendilerinin üzülmeyeceklerini müjde etmek isterler.'),
  ('tr.diyanet', 3, 170, 'Allah yolunda öldürülenleri ölü saymayın, bilakis Rableri katında diridirler. Allah\'ın bol nimetinden onlara verdiği şeylerle sevinç içinde rızıklanırlar, arkalarından kendilerine ulaşamayan kimselere, kendilerine korku olmadığını ve kendilerinin üzülmeyeceklerini müjde etmek isterler.'),
  ('tr.diyanet', 3, 171, 'Onlar Allah\'tan olan bir nimeti, bolluğu ve Allah\'ın, müminlerin ecrini zayi etmeyeceğini müjdelemek isterler.'),
  ('tr.diyanet', 3, 172, 'Kendileri savaşta yara aldıktan sonra Allah ve Peygamberin çağrısına koşanlara, hele onlardan iyilik edip sakınanlara büyük ecir vardır.'),
  ('tr.diyanet', 3, 173, 'İnsanlar onlara: "Düşmanınız olan insanlar size karşı bir ordu topladılar, onlardan korkun" dediler. Bu, onların imanını artırdı da: "Allah bize yeter. O ne güzel Vekil\'dir" dediler.'),
  ('tr.diyanet', 3, 174, 'Bu yüzden kendilerine bir fenalık dokunmadan, Allah\'tan nimet ve bollukla geri döndüler; Allah\'ın rızasına uydular. Allah büyük, bol nimet sahibidir.'),
  ('tr.diyanet', 3, 175, 'İşte o şeytan ancak kendi dostlarını korkutur, inanmışsanız onlardan korkmayın, Benden korkun.'),
  ('tr.diyanet', 3, 176, 'Küfürde yarışanlar seni üzmesin; şüphesiz onlar Allah\'a bir zarar veremezler. Allah ahirette onlara bir pay vermemek istiyor; onlara büyük azab vardır.'),
  ('tr.diyanet', 3, 177, 'İmanı inkar edenler, kendilerine vermiş olduğumuz mühletin sakın kendileri için hayırlı olduğunu sanmasınlar.'),
  ('tr.diyanet', 3, 178, 'Biz onlara ancak, günahları çoğalsın diye mühlet veriyoruz. Küçültücü azab onlaradır.'),
  ('tr.diyanet', 3, 179, 'Allah inananları sizin durumunuzda bırakacak değildir, temizi pisten ayıracaktır. Allah size gaybı bildirecek değildir; fakat Allah peygamberlerinden dilediğini seçip, ona gaybı bildirir. Artık Allah\'a ve peygamberlerine inanın; inanır ve sakınırsanız size büyük ecir vardır.'),
  ('tr.diyanet', 3, 180, 'Allah\'ın bol nimetinden verdiklerinde cimrilik edenler, sakın bunun kendileri için hayırlı olduğunu sanmasınlar, bilakis bu onların kötülüğünedir. Cimrilik yaptıkları şey, kıyamet günü boyunlarına dolanacaktır. Göklerin ve yerin mirası Allah\'ındır. Allah işlediklerinizden haberdardır.'),
  ('tr.diyanet', 3, 181, 'And olsun ki, Allah: "Allah fakir; biz zenginiz" diyenlerin sözünü işitmiştir. Dediklerini ve haksız yere peygamberleri öldürdüklerini elbette yazacağız, "Yakıcı azabı tadın" diyeceğiz.'),
  ('tr.diyanet', 3, 182, '"Bu, yaptığınızın karşılığıdır". Yoksa Allah kullara asla zulmetmez.'),
  ('tr.diyanet', 3, 183, '"Doğrusu, ateşin yiyeceği bir kurban getirmedikçe hiçbir peygambere inanmamak üzere Allah bize ahid verdi" diyenlere sen, de ki: "Benden önce peygamberler size belgeler ve dediğiniz şeyi getirdi. Doğru sözlü iseniz niçin onları öldürdünüz?"'),
  ('tr.diyanet', 3, 184, 'Seni yalancı saydılarsa, senden önce belgeler, sahifeler ve aydınlatıcı kitap getiren peygamberler de yalanlanmıştı.'),
  ('tr.diyanet', 3, 185, 'Her insan ölümü tadacaktır. Kıyamet günü, ecirleriniz size mutlaka ödenecektir. Ateşten uzaklaştırılıp cennete sokulan kimse artık kurtulmuştur. Dünya hayatı, zaten, sadece aldatıcı bir geçinmeden ibarettir.'),
  ('tr.diyanet', 3, 186, 'And olsun ki mallarınız ve canlarınızla sınanacaksınız; hiç şüphesiz, sizden önce Kitap verilenlerden ve Allah\'a eş koşanlardan çok üzücü sözler işiteceksiniz. Sabreder ve Allah\'a karşı gelmekten sakınırsanız bilin ki, bu üzerinde sebat edilecek işlerdendir.'),
  ('tr.diyanet', 3, 187, 'Allah, Kitap verilenlerden, onu insanlara açıklayacaksınız ve gizlemeyeceksiniz, diye ahid almıştı. Onlar ise, onu arkalarına atıp az bir değere değiştiler. Alış verişleri ne kötüdür!'),
  ('tr.diyanet', 3, 188, 'Ettiklerine sevinen ve yapmadıklarıyla övülmekten hoşlananların, sakın onların azabdan kurtulacaklarını sanma; elem verici azab onlaradır.'),
  ('tr.diyanet', 3, 189, 'Göklerin ve yerin hükümranlığı Allah\'ındır. Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 3, 190, 'Göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelmesinde akıl sahiblerine şüphesiz deliller vardır.'),
  ('tr.diyanet', 3, 191, 'Onlar ayakta iken, otururken, yan yatarken Allah\'ı anarlar; göklerin ve yerin yaratılışını düşünürler: "Rabbimiz! Sen bunu boşuna yaratmadın, Sen münezzehsin. Bizi ateşin azabından koru"'),
  ('tr.diyanet', 3, 192, '"Rabbimiz! Sen ateşe kimi sokarsan, onu şüphesiz rezil etmiş olursun, zulmedenlerin hiç yardımcıları yoktur".'),
  ('tr.diyanet', 3, 193, '"Rabbimiz! Doğrusu biz Rabbinize inanın diye inanmaya çağıran bir çağırıcıyı işittik de iman ettik. Rabbimiz! Günahlarımızı bize bağışla, kötülüklerimizi ört, canımızi iyilerle beraber al".'),
  ('tr.diyanet', 3, 194, '"Rabbimiz! Peygamberlerinle vadettiklerini bize ver, kıyamet günü bizi rezil etme. Sen şüphesiz sözünden caymazsın".'),
  ('tr.diyanet', 3, 195, 'Rableri dualarını kabul etti: "Birbirinizden meydana gelen sizlerden, erkek olsun, kadın olsun, iş yapanın işini boşa çıkarmam. Hicret edenlerin, memleketlerinden çıkarılanların, yolumda ezaya uğratılanların, savaşan ve öldürülenlerin günahlarını elbette örteceğim. And olsun ki, Allah katından bir nimet olarak, onları içlerinden ırmaklar akan cennetlere koyacağım. Nimetin güzeli Allah katındadır".'),
  ('tr.diyanet', 3, 196, 'İnkar edenlerin diyar diyar gezip refah içinde dolaşması sakın seni aldatmasın; az bir faydalanmadan sonra onların varacakları yer cehennemdir. O ne kötü duraktır!..'),
  ('tr.diyanet', 3, 197, 'İnkar edenlerin diyar diyar gezip refah içinde dolaşması sakın seni aldatmasın; az bir faydalanmadan sonra onların varacakları yer cehennemdir. O ne kötü duraktır!..'),
  ('tr.diyanet', 3, 198, 'Fakat Rablerinden sakınanlara, Allah katından konukluklar bulunan, içlerinden ırmaklar akan, içinde temelli kalacakları cennetler vardır. Allah katındaki şeyler, iyi olanlar için daha hayırlıdır.'),
  ('tr.diyanet', 3, 199, 'Kitap ehlinden Allah\'a huşu duyarak inanıp, Allah\'ın ayetlerini az bir değere değişmeyenler vardır. İşte onların ecirleri Rablerinin katındadır. Şüphesiz Allah\'ın hesabı çabuktur.'),
  ('tr.diyanet', 3, 200, 'Ey İnananlar! Sabredin, düşmanlarınızdan daha sabırlı olun, cihada hazır bulunun, Allah\'a karşı gelmekten sakının ki başarıya erişebilesiniz.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 3, 1, 'Alif laam miim.'),
  ('id.indonesian', 3, 2, 'Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia. Yang hidup kekal lagi terus menerus mengurus makhluk-Nya.'),
  ('id.indonesian', 3, 3, 'Dia menurunkan Al Kitab (Al Quran) kepadamu dengan sebenarnya; membenarkan kitab yang telah diturunkan sebelumnya dan menurunkan Taurat dan Injil,'),
  ('id.indonesian', 3, 4, 'sebelum (Al Quran), menjadi petunjuk bagi manusia, dan Dia menurunkan Al Furqaan. Sesungguhnya orang-orang yang kafir terhadap ayat-ayat Allah akan memperoleh siksa yang berat; dan Allah Maha Perkasa lagi mempunyai balasan (siksa).'),
  ('id.indonesian', 3, 5, 'Sesungguhnya bagi Allah tidak ada satupun yang tersembunyi di bumi dan tidak (pula) di langit.'),
  ('id.indonesian', 3, 6, 'Dialah yang membentuk kamu dalam rahim sebagaimana dikehendaki-Nya. Tak ada Tuhan (yang berhak disembah) melainkan Dia, Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 3, 7, 'Dialah yang menurunkan Al Kitab (Al Quran) kepada kamu. Di antara (isi)nya ada ayat-ayat yang muhkamaat, itulah pokok-pokok isi Al qur\'an dan yang lain (ayat-ayat) mutasyaabihaat. Adapun orang-orang yang dalam hatinya condong kepada kesesatan, maka mereka mengikuti sebahagian ayat-ayat yang mutasyaabihaat daripadanya untuk menimbulkan fitnah untuk mencari-cari ta\'wilnya, padahal tidak ada yang mengetahui ta\'wilnya melainkan Allah. Dan orang-orang yang mendalam ilmunya berkata: "Kami beriman kepada ayat-ayat yang mutasyaabihaat, semuanya itu dari sisi Tuhan kami". Dan tidak dapat mengambil pelajaran (daripadanya) melainkan orang-orang yang berakal.'),
  ('id.indonesian', 3, 8, '(Mereka berdoa): "Ya Tuhan kami, janganlah Engkau jadikan hati kami condong kepada kesesatan sesudah Engkau beri petunjuk kepada kami, dan karuniakanlah kepada kami rahmat dari sisi Engkau; karena sesungguhnya Engkau-lah Maha Pemberi (karunia)".'),
  ('id.indonesian', 3, 9, '"Ya Tuhan kami, sesungguhnya Engkau mengumpulkan manusia untuk (menerima pembalasan pada) hari yang tak ada keraguan padanya". Sesungguhnya Allah tidak menyalahi janji.'),
  ('id.indonesian', 3, 10, 'Sesungguhnya orang-orang yang kafir, harta benda dan anak-anak mereka, sedikitpun tidak dapat menolak (siksa) Allah dari mereka. Dan mereka itu adalah bahan bakar api neraka,'),
  ('id.indonesian', 3, 11, '(keadaan mereka) adalah sebagai keadaan kaum Fir\'aun dan orang-orang yang sebelumnya; mereka mendustakan ayat-ayat Kami; karena itu Allah menyiksa mereka disebabkan dosa-dosa mereka. Dan Allah sangat keras siksa-Nya.'),
  ('id.indonesian', 3, 12, 'Katakanlah kepada orang-orang yang kafir: "Kamu pasti akan dikalahkan (di dunia ini) dan akan digiring ke dalam neraka Jahannam. Dan itulah tempat yang seburuk-buruknya".'),
  ('id.indonesian', 3, 13, 'Sesungguhnya telah ada tanda bagi kamu pada dua golongan yang telah bertemu (bertempur). Segolongan berperang di jalan Allah dan (segolongan) yang lain kafir yang dengan mata kepala melihat (seakan-akan) orang-orang muslimin dua kali jumlah mereka. Allah menguatkan dengan bantuan-Nya siapa yang dikehendaki-Nya. Sesungguhnya pada yang demikian itu terdapat pelajaran bagi orang-orang yang mempunyai mata hati.'),
  ('id.indonesian', 3, 14, 'Dijadikan indah pada (pandangan) manusia kecintaan kepada apa-apa yang diingini, yaitu: wanita-wanita, anak-anak, harta yang banyak dari jenis emas, perak, kuda pilihan, binatang-binatang ternak dan sawah ladang. Itulah kesenangan hidup di dunia, dan di sisi Allah-lah tempat kembali yang baik (surga).'),
  ('id.indonesian', 3, 15, 'Katakanlah: "Inginkah aku kabarkan kepadamu apa yang lebih baik dari yang demikian itu?". Untuk orang-orang yang bertakwa (kepada Allah), pada sisi Tuhan mereka ada surga yang mengalir dibawahnya sungai-sungai; mereka kekal didalamnya. Dan (mereka dikaruniai) isteri-isteri yang disucikan serta keridhaan Allah. Dan Allah Maha Melihat akan hamba-hamba-Nya.'),
  ('id.indonesian', 3, 16, '(Yaitu) orang-orang yang berdoa: Ya Tuhan kami, sesungguhnya kami telah beriman, maka ampunilah segala dosa kami dan peliharalah kami dari siksa neraka,"'),
  ('id.indonesian', 3, 17, '(yaitu) orang-orang yang sabar, yang benar, yang tetap taat, yang menafkahkan hartanya (di jalan Allah), dan yang memohon ampun di waktu sahur.'),
  ('id.indonesian', 3, 18, 'Allah menyatakan bahwasanya tidak ada Tuhan melainkan Dia (yang berhak disembah), Yang menegakkan keadilan. Para Malaikat dan orang-orang yang berilmu (juga menyatakan yang demikian itu). Tak ada Tuhan melainkan Dia (yang berhak disembah), Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 3, 19, 'Sesungguhnya agama (yang diridhai) disisi Allah hanyalah Islam. Tiada berselisih orang-orang yang telah diberi Al Kitab kecuali sesudah datang pengetahuan kepada mereka, karena kedengkian (yang ada) di antara mereka. Barangsiapa yang kafir terhadap ayat-ayat Allah maka sesungguhnya Allah sangat cepat hisab-Nya.'),
  ('id.indonesian', 3, 20, 'Kemudian jika mereka mendebat kamu (tentang kebenaran Islam), maka katakanlah: "Aku menyerahkan diriku kepada Allah dan (demikian pula) orang-orang yang mengikutiku". Dan katakanlah kepada orang-orang yang telah diberi Al Kitab dan kepada orang-orang yang ummi: "Apakah kamu (mau) masuk Islam". Jika mereka masuk Islam, sesungguhnya mereka telah mendapat petunjuk, dan jika mereka berpaling, maka kewajiban kamu hanyalah menyampaikan (ayat-ayat Allah). Dan Allah Maha Melihat akan hamba-hamba-Nya.'),
  ('id.indonesian', 3, 21, 'Sesungguhnya orang-orang yang kafir kepada ayat-ayat Allah dan membunuh para nabi yang memamg tak dibenarkan dan membunuh orang-orang yang menyuruh manusia berbuat adil, maka gembirakanlah mereka bahwa mereka akan menerima siksa yg pedih.'),
  ('id.indonesian', 3, 22, 'Mereka itu adalah orang-orang yang lenyap (pahala) amal-amalnya di dunia dan akhirat, dan mereka sekali-kali tidak memperoleh penolong.'),
  ('id.indonesian', 3, 23, 'Tidakkah kamu memperhatikan orang-orang yang telah diberi bahagian yaitu Al Kitab (Taurat), mereka diseru kepada kitab Allah supaya kitab itu menetapkan hukum diantara mereka; kemudian sebahagian dari mereka berpaling, dan mereka selalu membelakangi (kebenaran).'),
  ('id.indonesian', 3, 24, 'Hal itu adalah karena mereka mengaku: "Kami tidak akan disentuh oleh api neraka kecuali beberapa hari yang dapat dihitung". Mereka diperdayakan dalam agama mereka oleh apa yang selalu mereka ada-adakan.'),
  ('id.indonesian', 3, 25, 'Bagaimanakah nanti apabila mereka Kami kumpulkan di hari (kiamat) yang tidak ada keraguan tentang adanya. Dan disempurnakan kepada tiap-tiap diri balasan apa yang diusahakannya sedang mereka tidak dianiaya (dirugikan).'),
  ('id.indonesian', 3, 26, 'Katakanlah: "Wahai Tuhan Yang mempunyai kerajaan, Engkau berikan kerajaan kepada orang yang Engkau kehendaki dan Engkau cabut kerajaan dari orang yang Engkau kehendaki. Engkau muliakan orang yang Engkau kehendaki dan Engkau hinakan orang yang Engkau kehendaki. Di tangan Engkaulah segala kebajikan. Sesungguhnya Engkau Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 3, 27, 'Engkau masukkan malam ke dalam siang dan Engkau masukkan siang ke dalam malam. Engkau keluarkan yang hidup dari yang mati, dan Engkau keluarkan yang mati dari yang hidup. Dan Engkau beri rezeki siapa yang Engkau kehendaki tanpa hisab (batas)".'),
  ('id.indonesian', 3, 28, 'Janganlah orang-orang mukmin mengambil orang-orang kafir menjadi wali dengan meninggalkan orang-orang mukmin. Barang siapa berbuat demikian, niscaya lepaslah ia dari pertolongan Allah, kecuali karena (siasat) memelihara diri dari sesuatu yang ditakuti dari mereka. Dan Allah memperingatkan kamu terhadap diri (siksa)-Nya. Dan hanya kepada Allah kembali(mu).'),
  ('id.indonesian', 3, 29, 'Katakanlah: "Jika kamu menyembunyikan apa yang ada dalam hatimu atau kamu melahirkannya, pasti Allah mengetahui". Allah mengetahui apa-apa yang ada di langit dan apa-apa yang ada di bumi. Dan Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 3, 30, 'Pada hari ketika tiap-tiap diri mendapati segala kebajikan dihadapkan (dimukanya), begitu (juga) kejahatan yang telah dikerjakannya; ia ingin kalau kiranya antara ia dengan hari itu ada masa yang jauh; dan Allah memperingatkan kamu terhadap siksa-Nya. Dan Allah sangat Penyayang kepada hamba-hamba-Nya.'),
  ('id.indonesian', 3, 31, 'Katakanlah: "Jika kamu (benar-benar) mencintai Allah, ikutilah aku, niscaya Allah mengasihi dan mengampuni dosa-dosamu". Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 3, 32, 'Katakanlah: "Taatilah Allah dan Rasul-Nya; jika kamu berpaling, maka sesungguhnya Allah tidak menyukai orang-orang kafir".'),
  ('id.indonesian', 3, 33, 'Sesungguhnya Allah telah memilih Adam, Nuh, keluarga Ibrahim dan keluarga \'Imran melebihi segala umat (di masa mereka masing-masing),'),
  ('id.indonesian', 3, 34, '(sebagai) satu keturunan yang sebagiannya (turunan) dari yang lain. Dan Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 3, 35, '(Ingatlah), ketika isteri \'Imran berkata: "Ya Tuhanku, sesungguhnya aku menazarkan kepada Engkau anak yang dalam kandunganku menjadi hamba yang saleh dan berkhidmat (di Baitul Maqdis). Karena itu terimalah (nazar) itu dari padaku. Sesungguhnya Engkaulah Yang Maha Mendengar lagi Maha Mengetahui".'),
  ('id.indonesian', 3, 36, 'Maka tatkala isteri \'Imran melahirkan anaknya, diapun berkata: "Ya Tuhanku, sesunguhnya aku melahirkannya seorang anak perempuan; dan Allah lebih mengetahui apa yang dilahirkannya itu; dan anak laki-laki tidaklah seperti anak perempuan. Sesungguhnya aku telah menamai dia Maryam dan aku mohon perlindungan untuknya serta anak-anak keturunannya kepada (pemeliharaan) Engkau daripada syaitan yang terkutuk".'),
  ('id.indonesian', 3, 37, 'Maka Tuhannya menerimanya (sebagai nazar) dengan penerimaan yang baik, dan mendidiknya dengan pendidikan yang baik dan Allah menjadikan Zakariya pemeliharanya. Setiap Zakariya masuk untuk menemui Maryam di mihrab, ia dapati makanan di sisinya. Zakariya berkata: "Hai Maryam dari mana kamu memperoleh (makanan) ini?" Maryam menjawab: "Makanan itu dari sisi Allah". Sesungguhnya Allah memberi rezeki kepada siapa yang dikehendaki-Nya tanpa hisab.'),
  ('id.indonesian', 3, 38, 'Di sanalah Zakariya mendoa kepada Tuhannya seraya berkata: "Ya Tuhanku, berilah aku dari sisi Engkau seorang anak yang baik. Sesungguhnya Engkau Maha Pendengar doa".'),
  ('id.indonesian', 3, 39, 'Kemudian Malaikat (Jibril) memanggil Zakariya, sedang ia tengah berdiri melakukan shalat di mihrab (katanya): "Sesungguhnya Allah menggembirakan kamu dengan kelahiran (seorang puteramu) Yahya, yang membenarkan kalimat (yang datang) dari Allah, menjadi ikutan, menahan diri (dari hawa nafsu) dan seorang Nabi termasuk keturunan orang-orang saleh".'),
  ('id.indonesian', 3, 40, 'Zakariya berkata: "Ya Tuhanku, bagaimana aku bisa mendapat anak sedang aku telah sangat tua dan isteriku pun seorang yang mandul?". Berfirman Allah: "Demikianlah, Allah berbuat apa yang dikehendaki-Nya".'),
  ('id.indonesian', 3, 41, 'Berkata Zakariya: "Berilah aku suatu tanda (bahwa isteriku telah mengandung)". Allah berfirman: "Tandanya bagimu, kamu tidak dapat berkata-kata dengan manusia selama tiga hari, kecuali dengan isyarat. Dan sebutlah (nama) Tuhanmu sebanyak-banyaknya serta bertasbihlah di waktu petang dan pagi hari".'),
  ('id.indonesian', 3, 42, 'Dan (ingatlah) ketika Malaikat (Jibril) berkata: "Hai Maryam, sesungguhnya Allah telah memilih kamu, mensucikan kamu dan melebihkan kamu atas segala wanita di dunia (yang semasa dengan kamu).'),
  ('id.indonesian', 3, 43, 'Hai Maryam, taatlah kepada Tuhanmu, sujud dan ruku\'lah bersama orang-orang yang ruku\'.'),
  ('id.indonesian', 3, 44, 'Yang demikian itu adalah sebagian dari berita-berita ghaib yang Kami wahyukan kepada kamu (ya Muhammad); padahal kamu tidak hadir beserta mereka, ketika mereka melemparkan anak-anak panah mereka (untuk mengundi) siapa di antara mereka yang akan memelihara Maryam. Dan kamu tidak hadir di sisi mereka ketika mereka bersengketa.'),
  ('id.indonesian', 3, 45, '(Ingatlah), ketika Malaikat berkata: "Hai Maryam, seungguhnya Allah menggembirakan kamu (dengan kelahiran seorang putera yang diciptakan) dengan kalimat (yang datang) daripada-Nya, namanya Al Masih Isa putera Maryam, seorang terkemuka di dunia dan di akhirat dan termasuk orang-orang yang didekatkan (kepada Allah),'),
  ('id.indonesian', 3, 46, 'dan dia berbicara dengan manusia dalam buaian dan ketika sudah dewasa dan dia adalah termasuk orang-orang yang saleh".'),
  ('id.indonesian', 3, 47, 'Maryam berkata: "Ya Tuhanku, betapa mungkin aku mempunyai anak, padahal aku belum pernah disentuh oleh seorang laki-lakipun". Allah berfirman (dengan perantaraan Jibril): "Demikianlah Allah menciptakan apa yang dikehendaki-Nya. Apabila Allah berkehendak menetapkan sesuatu, maka Allah hanya cukup berkata kepadanya: "Jadilah", lalu jadilah dia.'),
  ('id.indonesian', 3, 48, 'Dan Allah akan mengajarkan kepadanya Al Kitab, Hikmah, Taurat dan Injil.'),
  ('id.indonesian', 3, 49, 'Dan (sebagai) Rasul kepada Bani Israil (yang berkata kepada mereka): "Sesungguhnya aku telah datang kepadamu dengan membawa sesuatu tanda (mukjizat) dari Tuhanmu, yaitu aku membuat untuk kamu dari tanah berbentuk burung; kemudian aku meniupnya, maka ia menjadi seekor burung dengan seizin Allah; dan aku menyembuhkan orang yang buta sejak dari lahirnya dan orang yang berpenyakit sopak; dan aku menghidupkan orang mati dengan seizin Allah; dan aku kabarkan kepadamu apa yang kamu makan dan apa yang kamu simpan di rumahmu. Sesungguhnya pada yang demikian itu adalah suatu tanda (kebenaran kerasulanku) bagimu, jika kamu sungguh-sungguh beriman.'),
  ('id.indonesian', 3, 50, 'Dan (aku datang kepadamu) membenarkan Taurat yang datang sebelumku, dan untuk menghalalkan bagimu sebagian yang telah diharamkan untukmu, dan aku datang kepadamu dengan membawa suatu tanda (mukjizat) daripada Tuhanmu. Karena itu bertakwalah kepada Allah dan taatlah kepadaku.'),
  ('id.indonesian', 3, 51, 'Sesungguhnya Allah, Tuhanku dan Tuhanmu, karena itu sembahlah Dia. Inilah jalan yang lurus".'),
  ('id.indonesian', 3, 52, 'Maka tatkala Isa mengetahui keingkaran mereka (Bani lsrail) berkatalah dia: "Siapakah yang akan menjadi penolong-penolongku untuk (menegakkan agama) Allah?" Para hawariyyin (sahabat-sahabat setia) menjawab: "Kamilah penolong-penolong (agama) Allah, kami beriman kepada Allah; dan saksikanlah bahwa sesungguhnya kami adalah orang-orang yang berserah diri.'),
  ('id.indonesian', 3, 53, 'Ya Tuhan kami, kami telah beriman kepada apa yang telah Engkau turunkan dan telah kami ikuti rasul, karena itu masukanlah kami ke dalam golongan orang-orang yang menjadi saksi (tentang keesaan Allah)".'),
  ('id.indonesian', 3, 54, 'Orang-orang kafir itu membuat tipu daya, dan Allah membalas tipu daya mereka itu. Dan Allah sebaik-baik pembalas tipu daya.'),
  ('id.indonesian', 3, 55, '(Ingatlah), ketika Allah berfirman: "Hai Isa, sesungguhnya Aku akan menyampaikan kamu kepada akhir ajalmu dan mengangkat kamu kepada-Ku serta membersihkan kamu dari orang-orang yang kafir, dan menjadikan orang-orang yang mengikuti kamu di atas orang-orang yang kafir hingga hari kiamat. Kemudian hanya kepada Akulah kembalimu, lalu Aku memutuskan diantaramu tentang hal-hal yang selalu kamu berselisih padanya".'),
  ('id.indonesian', 3, 56, 'Adapun orang-orang yang kafir, maka akan Ku-siksa mereka dengan siksa yang sangat keras di dunia dan di akhirat, dan mereka tidak memperoleh penolong.'),
  ('id.indonesian', 3, 57, 'Adapun orang-orang yang beriman dan mengerjakan amalan-amalan yang saleh, maka Allah akan memberikan kepada mereka dengan sempurna pahala amalan-amalan mereka; dan Allah tidak menyukai orang-orang yang zalim.'),
  ('id.indonesian', 3, 58, 'Demikianlah (kisah Isa), Kami membacakannya kepada kamu sebagian dari bukti-bukti (kerasulannya) dan (membacakan) Al Quran yang penuh hikmah.'),
  ('id.indonesian', 3, 59, 'Sesungguhnya misal (penciptaan) Isa di sisi AllAh, adalah seperti (penciptaan) Adam. Allah menciptakan Adam dari tanah, kemudian Allah berfirman kepadanya: "Jadilah" (seorang manusia), maka jadilah dia.'),
  ('id.indonesian', 3, 60, '(Apa yang telah Kami ceritakan itu), itulah yang benar, yang datang dari Tuhanmu, karena itu janganlah kamu termasuk orang-orang yang ragu-ragu.'),
  ('id.indonesian', 3, 61, 'Siapa yang membantahmu tentang kisah Isa sesudah datang ilmu (yang meyakinkan kamu), maka katakanlah (kepadanya): "Marilah kita memanggil anak-anak kami dan anak-anak kamu, isteri-isteri kami dan isteri-isteri kamu, diri kami dan diri kamu; kemudian marilah kita bermubahalah kepada Allah dan kita minta supaya laknat Allah ditimpakan kepada orang-orang yang dusta.'),
  ('id.indonesian', 3, 62, 'Sesungguhnya ini adalah kisah yang benar, dan tak ada Tuhan (yang berhak disembah) selain Allah; dan sesungguhnya Allah, Dialah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 3, 63, 'Kemudian jika mereka berpaling (dari kebenaran), maka sesunguhnya Allah Maha Mengetahui orang-orang yang berbuat kerusakan.'),
  ('id.indonesian', 3, 64, 'Katakanlah: "Hai Ahli Kitab, marilah (berpegang) kepada suatu kalimat (ketetapan) yang tidak ada perselisihan antara kami dan kamu, bahwa tidak kita sembah kecuali Allah dan tidak kita persekutukan Dia dengan sesuatupun dan tidak (pula) sebagian kita menjadikan sebagian yang lain sebagai tuhan selain Allah". Jika mereka berpaling maka katakanlah kepada mereka: "Saksikanlah, bahwa kami adalah orang-orang yang berserah diri (kepada Allah)".'),
  ('id.indonesian', 3, 65, 'Hai Ahli Kitab, mengapa kamu bantah membantah tentang hal Ibrahim, padahal Taurat dan Injil tidak diturunkan melainkan sesudah Ibrahim. Apakah kamu tidak berpikir?'),
  ('id.indonesian', 3, 66, 'Beginilah kamu, kamu ini (sewajarnya) bantah membantah tentang hal yang kamu ketahui, maka kenapa kamu bantah membantah tentang hal yang tidak kamu ketahui? Allah mengetahui sedang kamu tidak mengetahui.'),
  ('id.indonesian', 3, 67, 'Ibrahim bukan seorang Yahudi dan bukan (pula) seorang Nasrani, akan tetapi dia adalah seorang yang lurus lagi berserah diri (kepada Allah) dan sekali-kali bukanlah dia termasuk golongan orang-orang musyrik.'),
  ('id.indonesian', 3, 68, 'Sesungguhnya orang yang paling dekat kepada Ibrahim ialah orang-orang yang mengikutinya dan Nabi ini (Muhammad), beserta orang-orang yang beriman (kepada Muhammad), dan Allah adalah Pelindung semua orang-orang yang beriman.'),
  ('id.indonesian', 3, 69, 'Segolongan dari Ahli Kitab ingin menyesatkan kamu, padahal mereka (sebenarnya) tidak menyesatkan melainkan dirinya sendiri, dan mereka tidak menyadarinya.'),
  ('id.indonesian', 3, 70, 'Hai Ahli Kitab, mengapa kamu mengingkari ayat-ayat Allah, padahal kamu mengetahui (kebenarannya).'),
  ('id.indonesian', 3, 71, 'Hai Ahli Kitab, mengapa kamu mencampur adukkan yang haq dengan yang bathil, dan menyembunyikan kebenaran, padahal kamu mengetahuinya?'),
  ('id.indonesian', 3, 72, 'Segolongan (lain) dari Ahli Kitab berkata (kepada sesamanya): "Perlihatkanlah (seolah-olah) kamu beriman kepada apa yang diturunkan kepada orang-orang beriman (sahabat-sahabat Rasul) pada permulaan siang dan ingkarilah ia pada akhirnya, supaya mereka (orang-orang mukmin) kembali (kepada kekafiran).'),
  ('id.indonesian', 3, 73, 'Dan janganlah kamu percaya melainkan kepada orang yang mengikuti agamamu. Katakanlah: "Sesungguhnya petunjuk (yang harus diikuti) ialah petunjuk Allah, dan (janganlah kamu percaya) bahwa akan diberikan kepada seseorang seperti apa yang diberikan kepadamu, dan (jangan pula kamu percaya) bahwa mereka akan mengalahkan hujjahmu di sisi Tuhanmu". Katakanlah: "Sesungguhnya karunia itu di tangan Allah, Allah memberikan karunia-Nya kepada siapa yang dikehendaki-Nya; dan Allah Maha Luas karunia-Nya) lagi Maha Mengetahui";'),
  ('id.indonesian', 3, 74, 'Allah menentukan rahmat-Nya (kenabian) kepada siapa yang dikehendaki-Nya dan Allah mempunyai karunia yang besar.'),
  ('id.indonesian', 3, 75, 'Di antara Ahli kitab ada orang yang jika kamu mempercayakan kepadanya harta yang banyak, dikembalikannya kepadamu; dan di antara mereka ada orang yang jika kamu mempercayakan kepadanya satu dinar, tidak dikembalikannya kepadamu kecuali jika kamu selalu menagihnya. Yang demikian itu lantaran mereka mengatakan: "tidak ada dosa bagi kami terhadap orang-orang ummi. Mereka berkata dusta terhadap Allah, padahal mereka mengetahui.'),
  ('id.indonesian', 3, 76, '(Bukan demikian), sebenarnya siapa yang menepati janji (yang dibuat)nya dan bertakwa, maka sesungguhnya Allah menyukai orang-orang yang bertakwa.'),
  ('id.indonesian', 3, 77, 'Sesungguhnya orang-orang yang menukar janji (nya dengan) Allah dan sumpah-sumpah mereka dengan harga yang sedikit, mereka itu tidak mendapat bahagian (pahala) di akhirat, dan Allah tidak akan berkata-kata dengan mereka dan tidak akan melihat kepada mereka pada hari kiamat dan tidak (pula) akan mensucikan mereka. Bagi mereka azab yang pedih.'),
  ('id.indonesian', 3, 78, 'Sesungguhnya diantara mereka ada segolongan yang memutar-mutar lidahnya membaca Al Kitab, supaya kamu menyangka yang dibacanya itu sebagian dari Al Kitab, padahal ia bukan dari Al Kitab dan mereka mengatakan: "Ia (yang dibaca itu datang) dari sisi Allah", padahal ia bukan dari sisi Allah. Mereka berkata dusta terhadap Allah sedang mereka mengetahui.'),
  ('id.indonesian', 3, 79, 'Tidak wajar bagi seseorang manusia yang Allah berikan kepadanya Al Kitab, hikmah dan kenabian, lalu dia berkata kepada manusia: "Hendaklah kamu menjadi penyembah-penyembahku bukan penyembah Allah". Akan tetapi (dia berkata): "Hendaklah kamu menjadi orang-orang rabbani, karena kamu selalu mengajarkan Al Kitab dan disebabkan kamu tetap mempelajarinya.'),
  ('id.indonesian', 3, 80, 'dan (tidak wajar pula baginya) menyuruhmu menjadikan malaikat dan para nabi sebagai tuhan. Apakah (patut) dia menyuruhmu berbuat kekafiran di waktu kamu sudah (menganut agama) Islam?".'),
  ('id.indonesian', 3, 81, 'Dan (ingatlah), ketika Allah mengambil perjanjian dari para nabi: "Sungguh, apa saja yang Aku berikan kepadamu berupa kitab dan hikmah kemudian datang kepadamu seorang rasul yang membenarkan apa yang ada padamu, niscaya kamu akan sungguh-sungguh beriman kepadanya dan menolongnya". Allah berfirman: "Apakah kamu mengakui dan menerima perjanjian-Ku terhadap yang demikian itu?" Mereka menjawab: "Kami mengakui". Allah berfirman: "Kalau begitu saksikanlah (hai para nabi) dan Aku menjadi saksi (pula) bersama kamu".'),
  ('id.indonesian', 3, 82, 'Barang siapa yang berpaling sesudah itu, maka mereka itulah orang-orang yang fasik.'),
  ('id.indonesian', 3, 83, 'Maka apakah mereka mencari agama yang lain dari agama Allah, padahal kepada-Nya-lah menyerahkan diri segala apa yang di langit dan di bumi, baik dengan suka maupun terpaksa dan hanya kepada Allahlah mereka dikembalikan.'),
  ('id.indonesian', 3, 84, 'Katakanlah: "Kami beriman kepada Allah dan kepada apa yang diturunkan kepada kami dan yang diturunkan kepada Ibrahim, Ismail, Ishaq, Ya\'qub, dan anak-anaknya, dan apa yang diberikan kepada Musa, Isa dan para nabi dari Tuhan mereka. Kami tidak membeda-bedakan seorangpun di antara mereka dan hanya kepada-Nya-lah kami menyerahkan diri".'),
  ('id.indonesian', 3, 85, 'Barangsiapa mencari agama selain agama Islam, maka sekali-kali tidaklah akan diterima (agama itu)daripadanya, dan dia di akhirat termasuk orang-orang yang rugi.'),
  ('id.indonesian', 3, 86, 'Bagaimana Allah akan menunjuki suatu kaum yang kafir sesudah mereka beriman, serta mereka telah mengakui bahwa Rasul itu (Muhammad) benar-benar rasul, dan keterangan-keteranganpun telah datang kepada mereka? Allah tidak menunjuki orang-orang yang zalim.'),
  ('id.indonesian', 3, 87, 'Mereka itu, balasannya ialah: bahwasanya laknat Allah ditimpakan kepada mereka, (demikian pula) laknat para malaikat dan manusia seluruhnya,'),
  ('id.indonesian', 3, 88, 'mereka kekal di dalamnya, tidak diringankan siksa dari mereka, dan tidak (pula) mereka diberi tangguh,'),
  ('id.indonesian', 3, 89, 'kecuali orang-orang yang taubat, sesudah (kafir) itu dan mengadakan perbaikan. Karena sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 3, 90, 'Sesungguhnya orang-orang kafir sesudah beriman, kemudian bertambah kekafirannya, sekali-kali tidak akan diterima taubatnya; dan mereka itulah orang-orang yang sesat.'),
  ('id.indonesian', 3, 91, 'Sesungguhnya orang-orang yang kafir dan mati sedang mereka tetap dalam kekafirannya, maka tidaklah akan diterima dari seseorang diantara mereka emas sepenuh bumi, walaupun dia menebus diri dengan emas (yang sebanyak) itu. Bagi mereka itulah siksa yang pedih dan sekali-kali mereka tidak memperoleh penolong.'),
  ('id.indonesian', 3, 92, 'Kamu sekali-kali tidak sampai kepada kebajikan (yang sempurna), sebelum kamu menafkahkan sehahagian harta yang kamu cintai. Dan apa saja yang kamu nafkahkan maka sesungguhnya Allah mengetahuinya.'),
  ('id.indonesian', 3, 93, 'Semua makanan adalah halal bagi Bani Israil melainkan makanan yang diharamkan oleh Israil (Ya\'qub) untuk dirinya sendiri sebelum Taurat diturunkan. Katakanlah: "(Jika kamu mengatakan ada makanan yang diharamkan sebelum turun Taurat), maka bawalah Taurat itu, lalu bacalah dia jika kamu orang-orang yang benar".'),
  ('id.indonesian', 3, 94, 'Maka barangsiapa mengada-adakan dusta terhadap Allah sesudah itu, maka merekalah orang-orang yang zalim.'),
  ('id.indonesian', 3, 95, 'Katakanlah: "Benarlah (apa yang difirmankan) Allah". Maka ikutilah agama Ibrahim yang lurus, dan bukanlah dia termasuk orang-orang yang musyrik.'),
  ('id.indonesian', 3, 96, 'Sesungguhnya rumah yang mula-mula dibangun untuk (tempat beribadat) manusia, ialah Baitullah yang di Bakkah (Mekah) yang diberkahi dan menjadi petunjuk bagi semua manusia.'),
  ('id.indonesian', 3, 97, 'Padanya terdapat tanda-tanda yang nyata, (di antaranya) maqam Ibrahim; barangsiapa memasukinya (Baitullah itu) menjadi amanlah dia; mengerjakan haji adalah kewajiban manusia terhadap Allah, yaitu (bagi) orang yang sanggup mengadakan perjalanan ke Baitullah. Barangsiapa mengingkari (kewajiban haji), maka sesungguhnya Allah Maha Kaya (tidak memerlukan sesuatu) dari semesta alam.'),
  ('id.indonesian', 3, 98, 'Katakanlah: "Hai Ahli Kitab, mengapa kamu ingkari ayat-ayat Allah, padahal Allah Maha menyaksikan apa yang kamu kerjakan?".'),
  ('id.indonesian', 3, 99, 'Katakanlah: "Hai Ahli Kitab, mengapa kamu menghalang-halangi dari jalan Allah orang-orang yang telah beriman, kamu menghendakinya menjadi bengkok, padahal kamu menyaksikan?". Allah sekali-kali tidak lalai dari apa yang kamu kerjakan.'),
  ('id.indonesian', 3, 100, 'Hai orang-orang yang beriman, jika kamu mengikuti sebahagian dari orang-orang yang diberi Al Kitab, niscaya mereka akan mengembalikan kamu menjadi orang kafir sesudah kamu beriman.'),
  ('id.indonesian', 3, 101, 'Bagaimanakah kamu (sampai) menjadi kafir, padahal ayat-ayat Allah dibacakan kepada kamu, dan Rasul-Nya pun berada di tengah-tengah kamu? Barangsiapa yang berpegang teguh kepada (agama) Allah, maka sesungguhnya ia telah diberi petunjuk kepada jalan yang lurus.'),
  ('id.indonesian', 3, 102, 'Hai orang-orang yang beriman, bertakwalah kepada Allah sebenar-benar takwa kepada-Nya; dan janganlah sekali-kali kamu mati melainkan dalam keadaan beragama Islam.'),
  ('id.indonesian', 3, 103, 'Dan berpeganglah kamu semuanya kepada tali (agama) Allah, dan janganlah kamu bercerai berai, dan ingatlah akan nikmat Allah kepadamu ketika kamu dahulu (masa Jahiliyah) bermusuh-musuhan, maka Allah mempersatukan hatimu, lalu menjadilah kamu karena nikmat Allah, orang-orang yang bersaudara; dan kamu telah berada di tepi jurang neraka, lalu Allah menyelamatkan kamu dari padanya. Demikianlah Allah menerangkan ayat-ayat-Nya kepadamu, agar kamu mendapat petunjuk.'),
  ('id.indonesian', 3, 104, 'Dan hendaklah ada di antara kamu segolongan umat yang menyeru kepada kebajikan, menyuruh kepada yang ma\'ruf dan mencegah dari yang munkar; merekalah orang-orang yang beruntung.'),
  ('id.indonesian', 3, 105, 'Dan janganlah kamu menyerupai orang-orang yang bercerai-berai dan berselisih sesudah datang keterangan yang jelas kepada mereka. Mereka itulah orang-orang yang mendapat siksa yang berat,'),
  ('id.indonesian', 3, 106, 'pada hari yang di waktu itu ada muka yang putih berseri, dan ada pula muka yang hitam muram. Adapun orang-orang yang hitam muram mukanya (kepada mereka dikatakan): "Kenapa kamu kafir sesudah kamu beriman? Karena itu rasakanlah azab disebabkan kekafiranmu itu".'),
  ('id.indonesian', 3, 107, 'Adapun orang-orang yang putih berseri mukanya, maka mereka berada dalam rahmat Allah (surga); mereka kekal di dalamnya.'),
  ('id.indonesian', 3, 108, 'Itulah ayat-ayat Allah. Kami bacakan ayat-ayat itu kepadamu dengan benar; dan tiadalah Allah berkehendak untuk menganiaya hamba-hamba-Nya.'),
  ('id.indonesian', 3, 109, 'Kepunyaan Allah-lah segala yang ada di langit dan di bumi; dan kepada Allahlah dikembalikan segala urusan.'),
  ('id.indonesian', 3, 110, 'Kamu adalah umat yang terbaik yang dilahirkan untuk manusia, menyuruh kepada yang ma\'ruf, dan mencegah dari yang munkar, dan beriman kepada Allah. Sekiranya Ahli Kitab beriman, tentulah itu lebih baik bagi mereka, di antara mereka ada yang beriman, dan kebanyakan mereka adalah orang-orang yang fasik.'),
  ('id.indonesian', 3, 111, 'Mereka sekali-kali tidak akan dapat membuat mudharat kepada kamu, selain dari gangguan-gangguan celaan saja, dan jika mereka berperang dengan kamu, pastilah mereka berbalik melarikan diri ke belakang (kalah). Kemudian mereka tidak mendapat pertolongan.'),
  ('id.indonesian', 3, 112, 'Mereka diliputi kehinaan di mana saja mereka berada, kecuali jika mereka berpegang kepada tali (agama) Allah dan tali (perjanjian) dengan manusia, dan mereka kembali mendapat kemurkaan dari Allah dan mereka diliputi kerendahan. Yang demikian itu karena mereka kafir kepada ayat-ayat Allah dan membunuh para nabi tanpa alasan yang benar. Yang demikian itu disebabkan mereka durhaka dan melampaui batas.'),
  ('id.indonesian', 3, 113, 'Mereka itu tidak sama; di antara Ahli Kitab itu ada golongan yang berlaku lurus, mereka membaca ayat-ayat Allah pada beberapa waktu di malam hari, sedang mereka juga bersujud (sembahyang).'),
  ('id.indonesian', 3, 114, 'Mereka beriman kepada Allah dan hari penghabisan, mereka menyuruh kepada yang ma\'ruf, dan mencegah dari yang munkar dan bersegera kepada (mengerjakan) pelbagai kebajikan; mereka itu termasuk orang-orang yang saleh.'),
  ('id.indonesian', 3, 115, 'Dan apa saja kebajikan yang mereka kerjakan, maka sekali-kali mereka tidak dihalangi (menenerima pahala)nya; dan Allah Maha Mengetahui orang-orang yang bertakwa.'),
  ('id.indonesian', 3, 116, 'Sesungguhnya orang-orang yang kafir baik harta mereka maupun anak-anak mereka, sekali-kali tidak dapat menolak azab Allah dari mereka sedikitpun. Dan mereka adalah penghuni neraka; mereka kekal di dalamnya.'),
  ('id.indonesian', 3, 117, 'Perumpamaan harta yang mereka nafkahkan di dalam kehidupan dunia ini, adalah seperti perumpamaan angin yang mengandung hawa yang sangat dingin, yang menimpa tanaman kaum yang menganiaya diri sendiri, lalu angin itu merusaknya. Allah tidak menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.'),
  ('id.indonesian', 3, 118, 'Hai orang-orang yang beriman, janganlah kamu ambil menjadi teman kepercayaanmu orang-orang yang, di luar kalanganmu (karena) mereka tidak henti-hentinya (menimbulkan) kemudharatan bagimu. Mereka menyukai apa yang menyusahkan kamu. Telah nyata kebencian dari mulut mereka, dan apa yang disembunyikan oleh hati mereka adalah lebih besar lagi. Sungguh telah Kami terangkan kepadamu ayat-ayat (Kami), jika kamu memahaminya.'),
  ('id.indonesian', 3, 119, 'Beginilah kamu, kamu menyukai mereka, padahal mereka tidak menyukai kamu, dan kamu beriman kepada kitab-kitab semuanya. Apabila mereka menjumpai kamu, mereka berkata "Kami beriman", dan apabila mereka menyendiri, mereka menggigit ujung jari antaran marah bercampur benci terhadap kamu. Katakanlah (kepada mereka): "Matilah kamu karena kemarahanmu itu". Sesungguhnya Allah mengetahui segala isi hati.'),
  ('id.indonesian', 3, 120, 'Jika kamu memperoleh kebaikan, niscaya mereka bersedih hati, tetapi Jika kamu mendapat bencana, mereka bergembira karenanya. Jika kamu bersabar dan bertakwa, niscaya tipu daya mereka sedikitpun tidak mendatangkan kemudharatan kepadamu. Sesungguhnya Allah mengetahui segala apa yang mereka kerjakan.'),
  ('id.indonesian', 3, 121, 'Dan (ingatlah), ketika kamu berangkat pada pagi hari dari (rumah) keluargamu akan menempatkan para mukmin pada beberapa tempat untuk berperang. Dan Allah Maha Mendengar lagi Maha Mengetahui,'),
  ('id.indonesian', 3, 122, 'ketika dua golongan dari padamu ingin (mundur) karena takut, padahal Allah adalah penolong bagi kedua golongan itu. Karena itu hendaklah kepada Allah saja orang-orang mukmin bertawakkal.'),
  ('id.indonesian', 3, 123, 'Sungguh Allah telah menolong kamu dalam peperangan Badar, padahal kamu adalah (ketika itu) orang-orang yang lemah. Karena itu bertakwalah kepada Allah, supaya kamu mensyukuri-Nya.'),
  ('id.indonesian', 3, 124, '(Ingatlah), ketika kamu mengatakan kepada orang mukmin: "Apakah tidak cukup bagi kamu Allah membantu kamu dengan tiga ribu malaikat yang diturunkan (dari langit)?"'),
  ('id.indonesian', 3, 125, 'Ya (cukup), jika kamu bersabar dan bersiap-siaga, dan mereka datang menyerang kamu dengan seketika itu juga, niscaya Allah menolong kamu dengan lima ribu Malaikat yang memakai tanda.'),
  ('id.indonesian', 3, 126, 'Dan Allah tidak menjadikan pemberian bala bantuan itu melainkan sebagai khabar gembira bagi (kemenangan)mu, dan agar tenteram hatimu karenanya. Dan kemenanganmu itu hanyalah dari Allah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 3, 127, '(Allah menolong kamu dalam perang Badar dan memberi bala bantuan itu) untuk membinasakan segolongan orang-orang yang kafir, atau untuk menjadikan mereka hina, lalu mereka kembali dengan tiada memperoleh apa-apa.'),
  ('id.indonesian', 3, 128, 'Tak ada sedikitpun campur tanganmu dalam urusan mereka itu atau Allah menerima taubat mereka, atau mengazab mereka karena sesungguhnya mereka itu orang-orang yang zalim.'),
  ('id.indonesian', 3, 129, 'Kepunyaan Allah apa yang ada di langit dan yang ada di bumi. Dia memberi ampun kepada siapa yang Dia kehendaki; Dia menyiksa siapa yang Dia kehendaki, dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 3, 130, 'Hai orang-orang yang beriman, janganlah kamu memakan riba dengan berlipat ganda] dan bertakwalah kamu kepada Allah supaya kamu mendapat keberuntungan.'),
  ('id.indonesian', 3, 131, 'Dan peliharalah dirimu dari api neraka, yang disediakan untuk orang-orang yang kafir.'),
  ('id.indonesian', 3, 132, 'Dan taatilah Allah dan Rasul, supaya kamu diberi rahmat.'),
  ('id.indonesian', 3, 133, 'Dan bersegeralah kamu kepada ampunan dari Tuhanmu dan kepada surga yang luasnya seluas langit dan bumi yang disediakan untuk orang-orang yang bertakwa,'),
  ('id.indonesian', 3, 134, '(yaitu) orang-orang yang menafkahkan (hartanya), baik di waktu lapang maupun sempit, dan orang-orang yang menahan amarahnya dan memaafkan (kesalahan) orang. Allah menyukai orang-orang yang berbuat kebajikan.'),
  ('id.indonesian', 3, 135, 'Dan (juga) orang-orang yang apabila mengerjakan perbuatan keji atau menganiaya diri sendiri, mereka ingat akan Allah, lalu memohon ampun terhadap dosa-dosa mereka dan siapa lagi yang dapat mengampuni dosa selain dari pada Allah? Dan mereka tidak meneruskan perbuatan kejinya itu, sedang mereka mengetahui.'),
  ('id.indonesian', 3, 136, 'Mereka itu balasannya ialah ampunan dari Tuhan mereka dan surga yang di dalamnya mengalir sungai-sungai, sedang mereka kekal di dalamnya; dan itulah sebaik-baik pahala orang-orang yang beramal.'),
  ('id.indonesian', 3, 137, 'Sesungguhnya telah berlalu sebelum kamu sunnah-sunnah Allah; Karena itu berjalanlah kamu di muka bumi dan perhatikanlah bagaimana akibat orang-orang yang mendustakan (rasul-rasul).'),
  ('id.indonesian', 3, 138, '(Al Quran) ini adalah penerangan bagi seluruh manusia, dan petunjuk serta pelajaran bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 3, 139, 'Janganlah kamu bersikap lemah, dan janganlah (pula) kamu bersedih hati, padahal kamulah orang-orang yang paling tinggi (derajatnya), jika kamu orang-orang yang beriman.'),
  ('id.indonesian', 3, 140, 'Jika kamu (pada perang Uhud) mendapat luka, maka sesungguhnya kaum (kafir) itupun (pada perang Badar) mendapat luka yang serupa. Dan masa (kejayaan dan kehancuran) itu Kami pergilirkan diantara manusia (agar mereka mendapat pelajaran); dan supaya Allah membedakan orang-orang yang beriman (dengan orang-orang kafir) supaya sebagian kamu dijadikan-Nya (gugur sebagai) syuhada\'. Dan Allah tidak menyukai orang-orang yang zalim,'),
  ('id.indonesian', 3, 141, 'Dan agar Allah membersihkan orang-orang yang beriman (dari dosa mereka) dan membinasakan orang-orang yang kafir.'),
  ('id.indonesian', 3, 142, 'Apakah kamu mengira bahwa kamu akan masuk surga, padahal belum nyata bagi Allah orang-orang yang berjihad diantaramu dan belum nyata orang-orang yang sabar.'),
  ('id.indonesian', 3, 143, 'Sesungguhnya kamu mengharapkan mati (syahid) sebelum kamu menghadapinya; (sekarang) sungguh kamu telah melihatnya dan kamu menyaksikannya.'),
  ('id.indonesian', 3, 144, 'Muhammad itu tidak lain hanyalah seorang rasul, sungguh telah berlalu sebelumnya beberapa orang rasul. Apakah Jika dia wafat atau dibunuh kamu berbalik ke belakang (murtad)? Barangsiapa yang berbalik ke belakang, maka ia tidak dapat mendatangkan mudharat kepada Allah sedikitpun, dan Allah akan memberi balasan kepada orang-orang yang bersyukur.'),
  ('id.indonesian', 3, 145, 'Sesuatu yang bernyawa tidak akan mati melainkan dengan izin Allah, sebagai ketetapan yang telah ditentukan waktunya. Barang siapa menghendaki pahala dunia, niscaya Kami berikan kepadanya pahala dunia itu, dan barang siapa menghendaki pahala akhirat, Kami berikan (pula) kepadanya pahala akhirat itu. Dan kami akan memberi balasan kepada orang-orang yang bersyukur.'),
  ('id.indonesian', 3, 146, 'Dan berapa banyaknya nabi yang berperang bersama-sama mereka sejumlah besar dari pengikut(nya) yang bertakwa. Mereka tidak menjadi lemah karena bencana yang menimpa mereka di jalan Allah, dan tidak lesu dan tidak (pula) menyerah (kepada musuh). Allah menyukai orang-orang yang sabar.'),
  ('id.indonesian', 3, 147, 'Tidak ada doa mereka selain ucapan: "Ya Tuhan kami, ampunilah dosa-dosa kami dan tindakan-tindakan kami yang berlebih-lebihan dalam urusan kami dan tetapkanlah pendirian kami, dan tolonglah kami terhadap kaum yang kafir".'),
  ('id.indonesian', 3, 148, 'Karena itu Allah memberikan kepada mereka pahala di dunia dan pahala yang baik di akhirat. Dan Allah menyukai orang-orang yang berbuat kebaikan.'),
  ('id.indonesian', 3, 149, 'Hai orang-orang yang beriman, jika kamu mentaati orang-orang yang kafir itu, niscaya mereka mengembalikan kamu ke belakang (kepada kekafiran), lalu jadilah kamu orang-orang yang rugi.'),
  ('id.indonesian', 3, 150, 'Tetapi (ikutilah Allah), Allahlah Pelindungmu, dan Dialah sebaik-baik Penolong.'),
  ('id.indonesian', 3, 151, 'Akan Kami masukkan ke dalam hati orang-orang kafir rasa takut, disebabkan mereka mempersekutukan Allah dengan sesuatu yang Allah sendiri tidak menurunkan keterangan tentang itu. Tempat kembali mereka ialah neraka; dan itulah seburuk-buruk tempat tinggal orang-orang yang zalim.'),
  ('id.indonesian', 3, 152, 'Dan sesungguhnya Allah telah memenuhi janji-Nya kepada kamu, ketika kamu membunuh mereka dengan izin-Nya sampai pada saat kamu lemah dan berselisih dalam urusan itu dan mendurhakai perintah (Rasul) sesudah Allah memperlihatkan kepadamu apa yang kamu sukai. Di antaramu ada orang yang menghendaki dunia dan diantara kamu ada orang yang menghendaki akhirat. Kemudian Allah memalingkan kamu dari mereka untuk menguji kamu, dan sesunguhnya Allah telah memaafkan kamu. Dan Allah mempunyai karunia (yang dilimpahkan) atas orang orang yang beriman.'),
  ('id.indonesian', 3, 153, '(Ingatlah) ketika kamu lari dan tidak menoleh kepada seseorangpun, sedang Rasul yang berada di antara kawan-kawanmu yang lain memanggil kamu, karena itu Allah menimpakan atas kamu kesedihan atas kesedihan, supaya kamu jangan bersedih hati terhadap apa yang luput dari pada kamu dan terhadap apa yang menimpa kamu. Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 3, 154, 'Kemudian setelah kamu berdukacita, Allah menurunkan kepada kamu keamanan (berupa) kantuk yang meliputi segolongan dari pada kamu, sedang segolongan lagi telah dicemaskan oleh diri mereka sendiri, mereka menyangka yang tidak benar terhadap Allah seperti sangkaan jahiliyah. Mereka berkata: "Apakah ada bagi kita barang sesuatu (hak campur tangan) dalam urusan ini?". Katakanlah: "Sesungguhnya urusan itu seluruhnya di tangan Allah". Mereka menyembunyikan dalam hati mereka apa yang tidak mereka terangkan kepadamu; mereka berkata: "Sekiranya ada bagi kita barang sesuatu (hak campur tangan) dalam urusan ini, niscaya kita tidak akan dibunuh (dikalahkan) di sini". Katakanlah: "Sekiranya kamu berada di rumahmu, niscaya orang-orang yang telah ditakdirkan akan mati terbunuh itu keluar (juga) ke tempat mereka terbunuh". Dan Allah (berbuat demikian) untuk menguji apa yang ada dalam dadamu dan untuk membersihkan apa yang ada dalam hatimu. Allah Maha Mengetahui isi hati.'),
  ('id.indonesian', 3, 155, 'Sesungguhnya orang-orang yang berpaling di antaramu pada hari bertemu dua pasukan itu, hanya saja mereka digelincirkan oleh syaitan, disebabkan sebagian kesalahan yang telah mereka perbuat (di masa lampau) dan sesungguhnya Allah telah memberi maaf kepada mereka. Sesungguhnya Allah Maha Pengampun lagi Maha Penyantun.'),
  ('id.indonesian', 3, 156, 'Hai orang-orang yang beriman, janganlah kamu seperti orang-orang kafir (orang-orang munafik) itu, yang mengatakan kepada saudara-saudara mereka apabila mereka mengadakan perjalanan di muka bumi atau mereka berperang: "Kalau mereka tetap bersama-sama kita tentulah mereka tidak mati dan tidak dibunuh". Akibat (dari perkataan dan keyakinan mereka) yang demikian itu, Allah menimbulkan rasa penyesalan yang sangat di dalam hati mereka. Allah menghidupkan dan mematikan. Dan Allah melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 3, 157, 'Dan sungguh kalau kamu gugur di jalan Allah atau meninggal, tentulah ampunan Allah dan rahmat-Nya lebih baik (bagimu) dari harta rampasan yang mereka kumpulkan.'),
  ('id.indonesian', 3, 158, 'Dan sungguh jika kamu meninggal atau gugur, tentulah kepada Allah saja kamu dikumpulkan.'),
  ('id.indonesian', 3, 159, 'Maka disebabkan rahmat dari Allah-lah kamu berlaku lemah lembut terhadap mereka. Sekiranya kamu bersikap keras lagi berhati kasar, tentulah mereka menjauhkan diri dari sekelilingmu. Karena itu maafkanlah mereka, mohonkanlah ampun bagi mereka, dan bermusyawaratlah dengan mereka dalam urusan itu. Kemudian apabila kamu telah membulatkan tekad, maka bertawakkallah kepada Allah. Sesungguhnya Allah menyukai orang-orang yang bertawakkal kepada-Nya.'),
  ('id.indonesian', 3, 160, 'Jika Allah menolong kamu, maka tak adalah orang yang dapat mengalahkan kamu; jika Allah membiarkan kamu (tidak memberi pertolongan), maka siapakah gerangan yang dapat menolong kamu (selain) dari Allah sesudah itu? Karena itu hendaklah kepada Allah saja orang-orang mukmin bertawakkal.'),
  ('id.indonesian', 3, 161, 'Tidak mungkin seorang nabi berkhianat dalam urusan harta rampasan perang. Barangsiapa yang berkhianat dalam urusan rampasan perang itu, maka pada hari kiamat ia akan datang membawa apa yang dikhianatkannya itu, kemudian tiap-tiap diri akan diberi pembalasan tentang apa yang ia kerjakan dengan (pembalasan) setimpal, sedang mereka tidak dianiaya.'),
  ('id.indonesian', 3, 162, 'Apakah orang yang mengikuti keridhaan Allah sama dengan orang yang kembali membawa kemurkaan (yang besar) dari Allah dan tempatnya adalah Jahannam? Dan itulah seburuk-buruk tempat kembali.'),
  ('id.indonesian', 3, 163, '(Kedudukan) mereka itu bertingkat-tingkat di sisi Allah, dan Allah Maha Melihat apa yang mereka kerjakan.'),
  ('id.indonesian', 3, 164, 'Sungguh Allah telah memberi karunia kepada orang-orang yang beriman ketika Allah mengutus diantara mereka seorang rasul dari golongan mereka sendiri, yang membacakan kepada mereka ayat-ayat Allah, membersihkan (jiwa) mereka, dan mengajarkan kepada mereka Al Kitab dan Al Hikmah. Dan sesungguhnya sebelum (kedatangan Nabi) itu, mereka adalah benar-benar dalam kesesatan yang nyata.'),
  ('id.indonesian', 3, 165, 'Dan mengapa ketika kamu ditimpa musibah (pada peperangan Uhud), padahal kamu telah menimpakan kekalahan dua kali lipat kepada musuh-musuhmu (pada peperangan Badar), kamu berkata: "Darimana datangnya (kekalahan) ini?" Katakanlah: "Itu dari (kesalahan) dirimu sendiri". Sesungguhnya Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 3, 166, 'Dan apa yang menimpa kamu pada hari bertemunya dua pasukan, maka (kekalahan) itu adalah dengan izin (takdir) Allah, dan agar Allah mengetahui siapa orang-orang yang beriman.'),
  ('id.indonesian', 3, 167, 'Dan supaya Allah mengetahui siapa orang-orang yang munafik. Kepada mereka dikatakan: "Marilah berperang di jalan Allah atau pertahankanlah (dirimu)". Mereka berkata: "Sekiranya kami mengetahui akan terjadi peperangan, tentulah kami mengikuti kamu". Mereka pada hari itu lebih dekat kepada kekafiran dari pada keimanan. Mereka mengatakan dengan mulutnya apa yang tidak terkandung dalam hatinya. Dan Allah lebih mengetahui dalam hatinya. Dan Allah lebih mengetahui apa yang mereka sembunyikan.'),
  ('id.indonesian', 3, 168, 'Orang-orang yang mengatakan kepada saudara-saudaranya dan mereka tidak turut pergi berperang: "Sekiranya mereka mengikuti kita, tentulah mereka tidak terbunuh". Katakanlah: "Tolaklah kematian itu dari dirimu, jika kamu orang-orang yang benar".'),
  ('id.indonesian', 3, 169, 'Janganlah kamu mengira bahwa orang-orang yang gugur di jalan Allah itu mati; bahkan mereka itu hidup disisi Tuhannya dengan mendapat rezeki.'),
  ('id.indonesian', 3, 170, 'Mereka dalam keadaan gembira disebabkan karunia Allah yang diberikan-Nya kepada mereka, dan mereka bergirang hati terhadap orang-orang yang masih tinggal di belakang yang belum menyusul mereka, bahwa tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 3, 171, 'Mereka bergirang hati dengan nikmat dan karunia yang yang besar dari Allah, dan bahwa Allah tidak menyia-nyiakan pahala orang-orang yang beriman.'),
  ('id.indonesian', 3, 172, '(Yaitu) orang-orang yang mentaati perintah Allah dan Rasul-Nya sesudah mereka mendapat luka (dalam peperangan Uhud). Bagi orang-orang yang berbuat kebaikan diantara mereka dan yang bertakwa ada pahala yang besar.'),
  ('id.indonesian', 3, 173, '(Yaitu) orang-orang (yang mentaati Allah dan Rasul) yang kepada mereka ada orang-orang yang mengatakan: "Sesungguhnya manusia telah mengumpulkan pasukan untuk menyerang kamu, karena itu takutlah kepada mereka", maka perkataan itu menambah keimanan mereka dan mereka menjawab: "Cukuplah Allah menjadi Penolong kami dan Allah adalah sebaik-baik Pelindung".'),
  ('id.indonesian', 3, 174, 'Maka mereka kembali dengan nikmat dan karunia (yang besar) dari Allah, mereka tidak mendapat bencana apa-apa, mereka mengikuti keridhaan Allah. Dan Allah mempunyai karunia yang besar.'),
  ('id.indonesian', 3, 175, 'Sesungguhnya mereka itu tidak lain hanyalah syaitan yang menakut-nakuti (kamu) dengan kawan-kawannya (orang-orang musyrik Quraisy), karena itu janganlah kamu takut kepada mereka, tetapi takutlah kepada-Ku, jika kamu benar-benar orang yang beriman.'),
  ('id.indonesian', 3, 176, 'Janganlah kamu disedihkan oleh orang-orang yang segera menjadi kafir; sesungguhnya mereka tidak sekali-kali dapat memberi mudharat kepada Allah sedikitpun. Allah berkehendak tidak akan memberi sesuatu bahagian (dari pahala) kepada mereka di hari akhirat, dan bagi mereka azab yang besar.'),
  ('id.indonesian', 3, 177, 'Sesungguhnya orang-orang yang menukar iman dengan kekafiran, sekali-kali mereka tidak dapat memberi mudharat kepada Allah sedikitpun; dan bagi mereka azab yang pedih.'),
  ('id.indonesian', 3, 178, 'Dan janganlah sekali-kali orang-orang kafir menyangka, bahwa pemberian tangguh Kami kepada mereka adalah lebih baik bagi mereka. Sesungguhnya Kami memberi tangguh kepada mereka hanyalah supaya bertambah-tambah dosa mereka; dan bagi mereka azab yang menghinakan.'),
  ('id.indonesian', 3, 179, 'Allah sekali-kali tidak akan membiarkan orang-orang yang beriman dalam keadaan kamu sekarang ini, sehingga Dia menyisihkan yang buruk (munafik) dari yang baik (mukmin). Dan Allah sekali-kali tidak akan memperlihatkan kepada kamu hal-hal yang ghaib, akan tetapi Allah memilih siapa yang dikehendaki-Nya di antara rasul-rasul-Nya. Karena itu berimanlah kepada Allah dan rasul-rasul-Nya; dan jika kamu beriman dan bertakwa, maka bagimu pahala yang besar.'),
  ('id.indonesian', 3, 180, 'Sekali-kali janganlah orang-orang yang bakhil dengan harta yang Allah berikan kepada mereka dari karunia-Nya menyangka, bahwa kebakhilan itu baik bagi mereka. Sebenarnya kebakhilan itu adalah buruk bagi mereka. Harta yang mereka bakhilkan itu akan dikalungkan kelak di lehernya di hari kiamat. Dan kepunyaan Allah-lah segala warisan (yang ada) di langit dan di bumi. Dan Allah mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 3, 181, 'Sesungguhnya Allah telah mendengar perkatan orang-orang yang mengatakan: "Sesunguhnya Allah miskin dan kami kaya". Kami akan mencatat perkataan mereka itu dan perbuatan mereka membunuh nabi-nabi tanpa alasan yang benar, dan Kami akan mengatakan (kepada mereka): "Rasakanlah olehmu azab yang mem bakar".'),
  ('id.indonesian', 3, 182, '(Azab) yang demikian itu adalah disebabkan perbuatan tanganmu sendiri, dan bahwasanya Allah sekali-kali tidak menganiaya hamba-hamba-Nya.'),
  ('id.indonesian', 3, 183, '(Yaitu) orang-orang (Yahudi) yang mengatakan: "Sesungguhnya Allah telah memerintahkan kepada kami, supaya kami jangan beriman kepada seseorang rasul, sebelum dia mendatangkan kepada kami korban yang dimakan api". Katakanlah: "Sesungguhnya telah datang kepada kamu beberapa orang rasul sebelumku membawa keterangan-keterangan yang nyata dan membawa apa yang kamu sebutkan, maka mengapa kamu membunuh mereka jika kamu adalah orang-orang yang benar".'),
  ('id.indonesian', 3, 184, 'Jika mereka mendustakan kamu, maka sesungguhnya rasul-rasul sebelum kamupun telah didustakan (pula), mereka membawa mukjizat-mukjizat yang nyata, Zabur dan kitab yang memberi penjelasan yang sempurna.'),
  ('id.indonesian', 3, 185, 'Tiap-tiap yang berjiwa akan merasakan mati. Dan sesungguhnya pada hari kiamat sajalah disempurnakan pahalamu. Barangsiapa dijauhkan dari neraka dan dimasukkan ke dalam surga, maka sungguh ia telah beruntung. Kehidupan dunia itu tidak lain hanyalah kesenangan yang memperdayakan.'),
  ('id.indonesian', 3, 186, 'Kamu sungguh-sungguh akan diuji terhadap hartamu dan dirimu. Dan (juga) kamu sungguh-sungguh akan mendengar dari orang-orang yang diberi kitab sebelum kamu dan dari orang-orang yang mempersekutukan Allah, gangguan yang banyak yang menyakitkan hati. Jika kamu bersabar dan bertakwa, maka sesungguhnya yang demikian itu termasuk urusan yang patut diutamakan.'),
  ('id.indonesian', 3, 187, 'Dan (ingatlah), ketika Allah mengambil janji dari orang-orang yang telah diberi kitab (yaitu): "Hendaklah kamu menerangkan isi kitab itu kepada manusia, dan jangan kamu menyembunyikannya," lalu mereka melemparkan janji itu ke belakang punggung mereka dan mereka menukarnya dengan harga yang sedikit. Amatlah buruknya tukaran yang mereka terima.'),
  ('id.indonesian', 3, 188, 'Janganlah sekali-kali kamu menyangka, hahwa orang-orang yang gembira dengan apa yang telah mereka kerjakan dan mereka suka supaya dipuji terhadap perbuatan yang belum mereka kerjakan janganlah kamu menyangka bahwa mereka terlepas dari siksa, dan bagi mereka siksa yang pedih.'),
  ('id.indonesian', 3, 189, 'kepunyaan Allah-lah kerajaan langit dan bumi, dan Allah Maha Perkasa atas segala sesuatu.'),
  ('id.indonesian', 3, 190, 'Sesungguhnya dalam penciptaan langit dan bumi, dan silih bergantinya malam dan siang terdapat tanda-tanda bagi orang-orang yang berakal,'),
  ('id.indonesian', 3, 191, '(yaitu) orang-orang yang mengingat Allah sambil berdiri atau duduk atau dalam keadan berbaring dan mereka memikirkan tentang penciptaan langit dan bumi (seraya berkata): "Ya Tuhan kami, tiadalah Engkau menciptakan ini dengan sia-sia, Maha Suci Engkau, maka peliharalah kami dari siksa neraka.'),
  ('id.indonesian', 3, 192, 'Ya Tuhan kami, sesungguhnya barangsiapa yang Engkau masukkan ke dalam neraka, maka sungguh telah Engkau hinakan ia, dan tidak ada bagi orang-orang yang zalim seorang penolongpun.'),
  ('id.indonesian', 3, 193, 'Ya Tuhan kami, sesungguhnya kami mendengar (seruan) yang menyeru kepada iman, (yaitu): "Berimanlah kamu kepada Tuhanmu", maka kamipun beriman. Ya Tuhan kami, ampunilah bagi kami dosa-dosa kami dan hapuskanlah dari kami kesalahan-kesalahan kami, dan wafatkanlah kami beserta orang-orang yang banyak berbakti.'),
  ('id.indonesian', 3, 194, 'Ya Tuhan kami, berilah kami apa yang telah Engkau janjikan kepada kami dengan perantaraan rasul-rasul Engkau. Dan janganlah Engkau hinakan kami di hari kiamat. Sesungguhnya Engkau tidak menyalahi janji".'),
  ('id.indonesian', 3, 195, 'Maka Tuhan mereka memperkenankan permohonannya (dengan berfirman): "Sesungguhnya Aku tidak menyia-nyiakan amal orang-orang yang beramal di antara kamu, baik laki-laki atau perempuan, (karena) sebagian kamu adalah turunan dari sebagian yang lain. Maka orang-orang yang berhijrah, yang diusir dari kampung halamannya, yang disakiti pada jalan-Ku, yang berperang dan yang dibunuh, pastilah akan Ku-hapuskan kesalahan-kesalahan mereka dan pastilah Aku masukkan mereka ke dalam surga yang mengalir sungai-sungai di bawahnya, sebagai pahala di sisi Allah. Dan Allah pada sisi-Nya pahala yang baik".'),
  ('id.indonesian', 3, 196, 'Janganlah sekali-kali kamu terperdaya oleh kebebasan orang-orang kafir bergerak di dalam negeri.'),
  ('id.indonesian', 3, 197, 'Itu hanyalah kesenangan sementara, kemudian tempat tinggal mereka ialah Jahannam; dan Jahannam itu adalah tempat yang seburuk-buruknya.'),
  ('id.indonesian', 3, 198, 'Akan tetapi orang-orang yang bertakwa kepada Tuhannya, bagi mereka surga yang mengalir sungai-sungai di dalamnya, sedang mereka kekal di dalamnya sebagai tempat tinggal (anugerah) dari sisi Allah. Dan apa yang di sisi Allah adalah lebih baik bagi orang-orang yang berbakti.'),
  ('id.indonesian', 3, 199, 'Dan sesungguhnya diantara ahli kitab ada orang yang beriman kepada Allah dan kepada apa yang diturunkan kepada kamu dan yang diturunkan kepada mereka sedang mereka berendah hati kepada Allah dan mereka tidak menukarkan ayat-ayat Allah dengan harga yang sedikit. Mereka memperoleh pahala di sisi Tuhannya. Sesungguhnya Allah amat cepat perhitungan-Nya.'),
  ('id.indonesian', 3, 200, 'Hai orang-orang yang beriman, bersabarlah kamu dan kuatkanlah kesabaranmu dan tetaplah bersiap siaga (di perbatasan negerimu) dan bertakwalah kepada Allah, supaya kamu beruntung.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (3, 108, 401, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۗ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًۭا لِّلْعَٰلَمِينَ', 63, 4, 25, 0),
  (3, 109, 402, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 64, 4, 25, 0),
  (3, 110, 403, 'كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ ۗ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًۭا لَّهُم ۚ مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ', 64, 4, 25, 0),
  (3, 111, 404, 'لَن يَضُرُّوكُمْ إِلَّآ أَذًۭى ۖ وَإِن يُقَٰتِلُوكُمْ يُوَلُّوكُمُ ٱلْأَدْبَارَ ثُمَّ لَا يُنصَرُونَ', 64, 4, 25, 0),
  (3, 112, 405, 'ضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ أَيْنَ مَا ثُقِفُوٓا۟ إِلَّا بِحَبْلٍۢ مِّنَ ٱللَّهِ وَحَبْلٍۢ مِّنَ ٱلنَّاسِ وَبَآءُو بِغَضَبٍۢ مِّنَ ٱللَّهِ وَضُرِبَتْ عَلَيْهِمُ ٱلْمَسْكَنَةُ ۚ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 64, 4, 25, 0),
  (3, 113, 406, '۞ لَيْسُوا۟ سَوَآءًۭ ۗ مِّنْ أَهْلِ ٱلْكِتَٰبِ أُمَّةٌۭ قَآئِمَةٌۭ يَتْلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيْلِ وَهُمْ يَسْجُدُونَ', 64, 4, 26, 0),
  (3, 114, 407, 'يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَأُو۟لَٰٓئِكَ مِنَ ٱلصَّٰلِحِينَ', 64, 4, 26, 0),
  (3, 115, 408, 'وَمَا يَفْعَلُوا۟ مِنْ خَيْرٍۢ فَلَن يُكْفَرُوهُ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 64, 4, 26, 0),
  (3, 116, 409, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًۭٔا ۖ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۚ هُمْ فِيهَا خَٰلِدُونَ', 65, 4, 26, 0),
  (3, 117, 410, 'مَثَلُ مَا يُنفِقُونَ فِى هَٰذِهِ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَثَلِ رِيحٍۢ فِيهَا صِرٌّ أَصَابَتْ حَرْثَ قَوْمٍۢ ظَلَمُوٓا۟ أَنفُسَهُمْ فَأَهْلَكَتْهُ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ', 65, 4, 26, 0),
  (3, 118, 411, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةًۭ مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًۭا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَٰهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ ۖ إِن كُنتُمْ تَعْقِلُونَ', 65, 4, 26, 0),
  (3, 119, 412, 'هَٰٓأَنتُمْ أُو۟لَآءِ تُحِبُّونَهُمْ وَلَا يُحِبُّونَكُمْ وَتُؤْمِنُونَ بِٱلْكِتَٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمْ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ عَضُّوا۟ عَلَيْكُمُ ٱلْأَنَامِلَ مِنَ ٱلْغَيْظِ ۚ قُلْ مُوتُوا۟ بِغَيْظِكُمْ ۗ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 65, 4, 26, 0),
  (3, 120, 413, 'إِن تَمْسَسْكُمْ حَسَنَةٌۭ تَسُؤْهُمْ وَإِن تُصِبْكُمْ سَيِّئَةٌۭ يَفْرَحُوا۟ بِهَا ۖ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْـًٔا ۗ إِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌۭ', 65, 4, 26, 0),
  (3, 121, 414, 'وَإِذْ غَدَوْتَ مِنْ أَهْلِكَ تُبَوِّئُ ٱلْمُؤْمِنِينَ مَقَٰعِدَ لِلْقِتَالِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 65, 4, 26, 0),
  (3, 122, 415, 'إِذْ هَمَّت طَّآئِفَتَانِ مِنكُمْ أَن تَفْشَلَا وَٱللَّهُ وَلِيُّهُمَا ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 66, 4, 26, 0),
  (3, 123, 416, 'وَلَقَدْ نَصَرَكُمُ ٱللَّهُ بِبَدْرٍۢ وَأَنتُمْ أَذِلَّةٌۭ ۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تَشْكُرُونَ', 66, 4, 26, 0),
  (3, 124, 417, 'إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَٰثَةِ ءَالَٰفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُنزَلِينَ', 66, 4, 26, 0),
  (3, 125, 418, 'بَلَىٰٓ ۚ إِن تَصْبِرُوا۟ وَتَتَّقُوا۟ وَيَأْتُوكُم مِّن فَوْرِهِمْ هَٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ ءَالَٰفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُسَوِّمِينَ', 66, 4, 26, 0),
  (3, 126, 419, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِۦ ۗ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 66, 4, 26, 0),
  (3, 127, 420, 'لِيَقْطَعَ طَرَفًۭا مِّنَ ٱلَّذِينَ كَفَرُوٓا۟ أَوْ يَكْبِتَهُمْ فَيَنقَلِبُوا۟ خَآئِبِينَ', 66, 4, 26, 0),
  (3, 128, 421, 'لَيْسَ لَكَ مِنَ ٱلْأَمْرِ شَىْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَٰلِمُونَ', 66, 4, 26, 0),
  (3, 129, 422, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 66, 4, 26, 0),
  (3, 130, 423, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوا۟ ٱلرِّبَوٰٓا۟ أَضْعَٰفًۭا مُّضَٰعَفَةًۭ ۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 66, 4, 26, 0),
  (3, 131, 424, 'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِىٓ أُعِدَّتْ لِلْكَٰفِرِينَ', 66, 4, 26, 0),
  (3, 132, 425, 'وَأَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 66, 4, 26, 0),
  (3, 133, 426, '۞ وَسَارِعُوٓا۟ إِلَىٰ مَغْفِرَةٍۢ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ', 67, 4, 27, 0),
  (3, 134, 427, 'ٱلَّذِينَ يُنفِقُونَ فِى ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلْكَٰظِمِينَ ٱلْغَيْظَ وَٱلْعَافِينَ عَنِ ٱلنَّاسِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 67, 4, 27, 0),
  (3, 135, 428, 'وَٱلَّذِينَ إِذَا فَعَلُوا۟ فَٰحِشَةً أَوْ ظَلَمُوٓا۟ أَنفُسَهُمْ ذَكَرُوا۟ ٱللَّهَ فَٱسْتَغْفَرُوا۟ لِذُنُوبِهِمْ وَمَن يَغْفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمْ يُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمْ يَعْلَمُونَ', 67, 4, 27, 0),
  (3, 136, 429, 'أُو۟لَٰٓئِكَ جَزَآؤُهُم مَّغْفِرَةٌۭ مِّن رَّبِّهِمْ وَجَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 67, 4, 27, 0),
  (3, 137, 430, 'قَدْ خَلَتْ مِن قَبْلِكُمْ سُنَنٌۭ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 67, 4, 27, 0),
  (3, 138, 431, 'هَٰذَا بَيَانٌۭ لِّلنَّاسِ وَهُدًۭى وَمَوْعِظَةٌۭ لِّلْمُتَّقِينَ', 67, 4, 27, 0),
  (3, 139, 432, 'وَلَا تَهِنُوا۟ وَلَا تَحْزَنُوا۟ وَأَنتُمُ ٱلْأَعْلَوْنَ إِن كُنتُم مُّؤْمِنِينَ', 67, 4, 27, 0),
  (3, 140, 433, 'إِن يَمْسَسْكُمْ قَرْحٌۭ فَقَدْ مَسَّ ٱلْقَوْمَ قَرْحٌۭ مِّثْلُهُۥ ۚ وَتِلْكَ ٱلْأَيَّامُ نُدَاوِلُهَا بَيْنَ ٱلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَتَّخِذَ مِنكُمْ شُهَدَآءَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 67, 4, 27, 0),
  (3, 141, 434, 'وَلِيُمَحِّصَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَيَمْحَقَ ٱلْكَٰفِرِينَ', 68, 4, 27, 0),
  (3, 142, 435, 'أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَيَعْلَمَ ٱلصَّٰبِرِينَ', 68, 4, 27, 0),
  (3, 143, 436, 'وَلَقَدْ كُنتُمْ تَمَنَّوْنَ ٱلْمَوْتَ مِن قَبْلِ أَن تَلْقَوْهُ فَقَدْ رَأَيْتُمُوهُ وَأَنتُمْ تَنظُرُونَ', 68, 4, 27, 0),
  (3, 144, 437, 'وَمَا مُحَمَّدٌ إِلَّا رَسُولٌۭ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ ۚ وَمَن يَنقَلِبْ عَلَىٰ عَقِبَيْهِ فَلَن يَضُرَّ ٱللَّهَ شَيْـًۭٔا ۗ وَسَيَجْزِى ٱللَّهُ ٱلشَّٰكِرِينَ', 68, 4, 27, 0),
  (3, 145, 438, 'وَمَا كَانَ لِنَفْسٍ أَن تَمُوتَ إِلَّا بِإِذْنِ ٱللَّهِ كِتَٰبًۭا مُّؤَجَّلًۭا ۗ وَمَن يُرِدْ ثَوَابَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَن يُرِدْ ثَوَابَ ٱلْءَاخِرَةِ نُؤْتِهِۦ مِنْهَا ۚ وَسَنَجْزِى ٱلشَّٰكِرِينَ', 68, 4, 27, 0),
  (3, 146, 439, 'وَكَأَيِّن مِّن نَّبِىٍّۢ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٌۭ فَمَا وَهَنُوا۟ لِمَآ أَصَابَهُمْ فِى سَبِيلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسْتَكَانُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ', 68, 4, 27, 0),
  (3, 147, 440, 'وَمَا كَانَ قَوْلَهُمْ إِلَّآ أَن قَالُوا۟ رَبَّنَا ٱغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِىٓ أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 68, 4, 27, 0),
  (3, 148, 441, 'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنْيَا وَحُسْنَ ثَوَابِ ٱلْءَاخِرَةِ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 68, 4, 27, 0),
  (3, 149, 442, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تُطِيعُوا۟ ٱلَّذِينَ كَفَرُوا۟ يَرُدُّوكُمْ عَلَىٰٓ أَعْقَٰبِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 69, 4, 27, 0),
  (3, 150, 443, 'بَلِ ٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ خَيْرُ ٱلنَّٰصِرِينَ', 69, 4, 27, 0),
  (3, 151, 444, 'سَنُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ بِمَآ أَشْرَكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا ۖ وَمَأْوَىٰهُمُ ٱلنَّارُ ۚ وَبِئْسَ مَثْوَى ٱلظَّٰلِمِينَ', 69, 4, 27, 0),
  (3, 152, 445, 'وَلَقَدْ صَدَقَكُمُ ٱللَّهُ وَعْدَهُۥٓ إِذْ تَحُسُّونَهُم بِإِذْنِهِۦ ۖ حَتَّىٰٓ إِذَا فَشِلْتُمْ وَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَعَصَيْتُم مِّنۢ بَعْدِ مَآ أَرَىٰكُم مَّا تُحِبُّونَ ۚ مِنكُم مَّن يُرِيدُ ٱلدُّنْيَا وَمِنكُم مَّن يُرِيدُ ٱلْءَاخِرَةَ ۚ ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ ۖ وَلَقَدْ عَفَا عَنكُمْ ۗ وَٱللَّهُ ذُو فَضْلٍ عَلَى ٱلْمُؤْمِنِينَ', 69, 4, 27, 0),
  (3, 153, 446, '۞ إِذْ تُصْعِدُونَ وَلَا تَلْوُۥنَ عَلَىٰٓ أَحَدٍۢ وَٱلرَّسُولُ يَدْعُوكُمْ فِىٓ أُخْرَىٰكُمْ فَأَثَٰبَكُمْ غَمًّۢا بِغَمٍّۢ لِّكَيْلَا تَحْزَنُوا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا مَآ أَصَٰبَكُمْ ۗ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 69, 4, 28, 0),
  (3, 154, 447, 'ثُمَّ أَنزَلَ عَلَيْكُم مِّنۢ بَعْدِ ٱلْغَمِّ أَمَنَةًۭ نُّعَاسًۭا يَغْشَىٰ طَآئِفَةًۭ مِّنكُمْ ۖ وَطَآئِفَةٌۭ قَدْ أَهَمَّتْهُمْ أَنفُسُهُمْ يَظُنُّونَ بِٱللَّهِ غَيْرَ ٱلْحَقِّ ظَنَّ ٱلْجَٰهِلِيَّةِ ۖ يَقُولُونَ هَل لَّنَا مِنَ ٱلْأَمْرِ مِن شَىْءٍۢ ۗ قُلْ إِنَّ ٱلْأَمْرَ كُلَّهُۥ لِلَّهِ ۗ يُخْفُونَ فِىٓ أَنفُسِهِم مَّا لَا يُبْدُونَ لَكَ ۖ يَقُولُونَ لَوْ كَانَ لَنَا مِنَ ٱلْأَمْرِ شَىْءٌۭ مَّا قُتِلْنَا هَٰهُنَا ۗ قُل لَّوْ كُنتُمْ فِى بُيُوتِكُمْ لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيْهِمُ ٱلْقَتْلُ إِلَىٰ مَضَاجِعِهِمْ ۖ وَلِيَبْتَلِىَ ٱللَّهُ مَا فِى صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 70, 4, 28, 0),
  (3, 155, 448, 'إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ إِنَّمَا ٱسْتَزَلَّهُمُ ٱلشَّيْطَٰنُ بِبَعْضِ مَا كَسَبُوا۟ ۖ وَلَقَدْ عَفَا ٱللَّهُ عَنْهُمْ ۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِيمٌۭ', 70, 4, 28, 0),
  (3, 156, 449, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ كَفَرُوا۟ وَقَالُوا۟ لِإِخْوَٰنِهِمْ إِذَا ضَرَبُوا۟ فِى ٱلْأَرْضِ أَوْ كَانُوا۟ غُزًّۭى لَّوْ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِيَجْعَلَ ٱللَّهُ ذَٰلِكَ حَسْرَةًۭ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ يُحْىِۦ وَيُمِيتُ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 70, 4, 28, 0),
  (3, 157, 450, 'وَلَئِن قُتِلْتُمْ فِى سَبِيلِ ٱللَّهِ أَوْ مُتُّمْ لَمَغْفِرَةٌۭ مِّنَ ٱللَّهِ وَرَحْمَةٌ خَيْرٌۭ مِّمَّا يَجْمَعُونَ', 70, 4, 28, 0),
  (3, 158, 451, 'وَلَئِن مُّتُّمْ أَوْ قُتِلْتُمْ لَإِلَى ٱللَّهِ تُحْشَرُونَ', 71, 4, 28, 0),
  (3, 159, 452, 'فَبِمَا رَحْمَةٍۢ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ', 71, 4, 28, 0),
  (3, 160, 453, 'إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ ۖ وَإِن يَخْذُلْكُمْ فَمَن ذَا ٱلَّذِى يَنصُرُكُم مِّنۢ بَعْدِهِۦ ۗ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 71, 4, 28, 0),
  (3, 161, 454, 'وَمَا كَانَ لِنَبِىٍّ أَن يَغُلَّ ۚ وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ يَوْمَ ٱلْقِيَٰمَةِ ۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 71, 4, 28, 0),
  (3, 162, 455, 'أَفَمَنِ ٱتَّبَعَ رِضْوَٰنَ ٱللَّهِ كَمَنۢ بَآءَ بِسَخَطٍۢ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمَصِيرُ', 71, 4, 28, 0),
  (3, 163, 456, 'هُمْ دَرَجَٰتٌ عِندَ ٱللَّهِ ۗ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 71, 4, 28, 0),
  (3, 164, 457, 'لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًۭا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍ', 71, 4, 28, 0),
  (3, 165, 458, 'أَوَلَمَّآ أَصَٰبَتْكُم مُّصِيبَةٌۭ قَدْ أَصَبْتُم مِّثْلَيْهَا قُلْتُمْ أَنَّىٰ هَٰذَا ۖ قُلْ هُوَ مِنْ عِندِ أَنفُسِكُمْ ۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 71, 4, 28, 0),
  (3, 166, 459, 'وَمَآ أَصَٰبَكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ فَبِإِذْنِ ٱللَّهِ وَلِيَعْلَمَ ٱلْمُؤْمِنِينَ', 72, 4, 28, 0),
  (3, 167, 460, 'وَلِيَعْلَمَ ٱلَّذِينَ نَافَقُوا۟ ۚ وَقِيلَ لَهُمْ تَعَالَوْا۟ قَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَوِ ٱدْفَعُوا۟ ۖ قَالُوا۟ لَوْ نَعْلَمُ قِتَالًۭا لَّٱتَّبَعْنَٰكُمْ ۗ هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَٰنِ ۚ يَقُولُونَ بِأَفْوَٰهِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۗ وَٱللَّهُ أَعْلَمُ بِمَا يَكْتُمُونَ', 72, 4, 28, 0),
  (3, 168, 461, 'ٱلَّذِينَ قَالُوا۟ لِإِخْوَٰنِهِمْ وَقَعَدُوا۟ لَوْ أَطَاعُونَا مَا قُتِلُوا۟ ۗ قُلْ فَٱدْرَءُوا۟ عَنْ أَنفُسِكُمُ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 72, 4, 28, 0),
  (3, 169, 462, 'وَلَا تَحْسَبَنَّ ٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتًۢا ۚ بَلْ أَحْيَآءٌ عِندَ رَبِّهِمْ يُرْزَقُونَ', 72, 4, 28, 0),
  (3, 170, 463, 'فَرِحِينَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ وَيَسْتَبْشِرُونَ بِٱلَّذِينَ لَمْ يَلْحَقُوا۟ بِهِم مِّنْ خَلْفِهِمْ أَلَّا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 72, 4, 28, 0),
  (3, 171, 464, '۞ يَسْتَبْشِرُونَ بِنِعْمَةٍۢ مِّنَ ٱللَّهِ وَفَضْلٍۢ وَأَنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُؤْمِنِينَ', 72, 4, 29, 0),
  (3, 172, 465, 'ٱلَّذِينَ ٱسْتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعْدِ مَآ أَصَابَهُمُ ٱلْقَرْحُ ۚ لِلَّذِينَ أَحْسَنُوا۟ مِنْهُمْ وَٱتَّقَوْا۟ أَجْرٌ عَظِيمٌ', 72, 4, 29, 0),
  (3, 173, 466, 'ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدْ جَمَعُوا۟ لَكُمْ فَٱخْشَوْهُمْ فَزَادَهُمْ إِيمَٰنًۭا وَقَالُوا۟ حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ', 72, 4, 29, 0),
  (3, 174, 467, 'فَٱنقَلَبُوا۟ بِنِعْمَةٍۢ مِّنَ ٱللَّهِ وَفَضْلٍۢ لَّمْ يَمْسَسْهُمْ سُوٓءٌۭ وَٱتَّبَعُوا۟ رِضْوَٰنَ ٱللَّهِ ۗ وَٱللَّهُ ذُو فَضْلٍ عَظِيمٍ', 73, 4, 29, 0),
  (3, 175, 468, 'إِنَّمَا ذَٰلِكُمُ ٱلشَّيْطَٰنُ يُخَوِّفُ أَوْلِيَآءَهُۥ فَلَا تَخَافُوهُمْ وَخَافُونِ إِن كُنتُم مُّؤْمِنِينَ', 73, 4, 29, 0),
  (3, 176, 469, 'وَلَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ ۚ إِنَّهُمْ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا ۗ يُرِيدُ ٱللَّهُ أَلَّا يَجْعَلَ لَهُمْ حَظًّۭا فِى ٱلْءَاخِرَةِ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', 73, 4, 29, 0),
  (3, 177, 470, 'إِنَّ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْكُفْرَ بِٱلْإِيمَٰنِ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 73, 4, 29, 0),
  (3, 178, 471, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّمَا نُمْلِى لَهُمْ خَيْرٌۭ لِّأَنفُسِهِمْ ۚ إِنَّمَا نُمْلِى لَهُمْ لِيَزْدَادُوٓا۟ إِثْمًۭا ۚ وَلَهُمْ عَذَابٌۭ مُّهِينٌۭ', 73, 4, 29, 0),
  (3, 179, 472, 'مَّا كَانَ ٱللَّهُ لِيَذَرَ ٱلْمُؤْمِنِينَ عَلَىٰ مَآ أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ ۗ وَمَا كَانَ ٱللَّهُ لِيُطْلِعَكُمْ عَلَى ٱلْغَيْبِ وَلَٰكِنَّ ٱللَّهَ يَجْتَبِى مِن رُّسُلِهِۦ مَن يَشَآءُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمْ أَجْرٌ عَظِيمٌۭ', 73, 4, 29, 0),
  (3, 180, 473, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ يَبْخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ هُوَ خَيْرًۭا لَّهُم ۖ بَلْ هُوَ شَرٌّۭ لَّهُمْ ۖ سَيُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ يَوْمَ ٱلْقِيَٰمَةِ ۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 73, 4, 29, 0),
  (3, 181, 474, 'لَّقَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ فَقِيرٌۭ وَنَحْنُ أَغْنِيَآءُ ۘ سَنَكْتُبُ مَا قَالُوا۟ وَقَتْلَهُمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 74, 4, 29, 0),
  (3, 182, 475, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّامٍۢ لِّلْعَبِيدِ', 74, 4, 29, 0),
  (3, 183, 476, 'ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَيْنَآ أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍۢ تَأْكُلُهُ ٱلنَّارُ ۗ قُلْ قَدْ جَآءَكُمْ رُسُلٌۭ مِّن قَبْلِى بِٱلْبَيِّنَٰتِ وَبِٱلَّذِى قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَٰدِقِينَ', 74, 4, 29, 0),
  (3, 184, 477, 'فَإِن كَذَّبُوكَ فَقَدْ كُذِّبَ رُسُلٌۭ مِّن قَبْلِكَ جَآءُو بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ وَٱلْكِتَٰبِ ٱلْمُنِيرِ', 74, 4, 29, 0),
  (3, 185, 478, 'كُلُّ نَفْسٍۢ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَإِنَّمَا تُوَفَّوْنَ أُجُورَكُمْ يَوْمَ ٱلْقِيَٰمَةِ ۖ فَمَن زُحْزِحَ عَنِ ٱلنَّارِ وَأُدْخِلَ ٱلْجَنَّةَ فَقَدْ فَازَ ۗ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', 74, 4, 29, 0),
  (3, 186, 479, '۞ لَتُبْلَوُنَّ فِىٓ أَمْوَٰلِكُمْ وَأَنفُسِكُمْ وَلَتَسْمَعُنَّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَمِنَ ٱلَّذِينَ أَشْرَكُوٓا۟ أَذًۭى كَثِيرًۭا ۚ وَإِن تَصْبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ', 74, 4, 30, 0),
  (3, 187, 480, 'وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا ۖ فَبِئْسَ مَا يَشْتَرُونَ', 75, 4, 30, 0),
  (3, 188, 481, 'لَا تَحْسَبَنَّ ٱلَّذِينَ يَفْرَحُونَ بِمَآ أَتَوا۟ وَّيُحِبُّونَ أَن يُحْمَدُوا۟ بِمَا لَمْ يَفْعَلُوا۟ فَلَا تَحْسَبَنَّهُم بِمَفَازَةٍۢ مِّنَ ٱلْعَذَابِ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 75, 4, 30, 0),
  (3, 189, 482, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 75, 4, 30, 0),
  (3, 190, 483, 'إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلْأَلْبَٰبِ', 75, 4, 30, 0),
  (3, 191, 484, 'ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًۭا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 75, 4, 30, 0),
  (3, 192, 485, 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ', 75, 4, 30, 0),
  (3, 193, 486, 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا ۚ رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ', 75, 4, 30, 0),
  (3, 194, 487, 'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ', 75, 4, 30, 0),
  (3, 195, 488, 'فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍۢ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّنۢ بَعْضٍۢ ۖ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ', 76, 4, 30, 0),
  (3, 196, 489, 'لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ', 76, 4, 30, 0),
  (3, 197, 490, 'مَتَٰعٌۭ قَلِيلٌۭ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ ۚ وَبِئْسَ ٱلْمِهَادُ', 76, 4, 30, 0),
  (3, 198, 491, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًۭا مِّنْ عِندِ ٱللَّهِ ۗ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ لِّلْأَبْرَارِ', 76, 4, 30, 0),
  (3, 199, 492, 'وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًۭا قَلِيلًا ۗ أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 76, 4, 30, 0),
  (3, 200, 493, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ', 76, 4, 30, 0),
  (4, 1, 494, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًۭا كَثِيرًۭا وَنِسَآءًۭ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِى تَسَآءَلُونَ بِهِۦ وَٱلْأَرْحَامَ ۚ إِنَّ ٱللَّهَ كَانَ عَلَيْكُمْ رَقِيبًۭا', 77, 4, 31, 0),
  (4, 2, 495, 'وَءَاتُوا۟ ٱلْيَتَٰمَىٰٓ أَمْوَٰلَهُمْ ۖ وَلَا تَتَبَدَّلُوا۟ ٱلْخَبِيثَ بِٱلطَّيِّبِ ۖ وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَهُمْ إِلَىٰٓ أَمْوَٰلِكُمْ ۚ إِنَّهُۥ كَانَ حُوبًۭا كَبِيرًۭا', 77, 4, 31, 0),
  (4, 3, 496, 'وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا۟ فِى ٱلْيَتَٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا۟ فَوَٰحِدَةً أَوْ مَا مَلَكَتْ أَيْمَٰنُكُمْ ۚ ذَٰلِكَ أَدْنَىٰٓ أَلَّا تَعُولُوا۟', 77, 4, 31, 0),
  (4, 4, 497, 'وَءَاتُوا۟ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحْلَةًۭ ۚ فَإِن طِبْنَ لَكُمْ عَن شَىْءٍۢ مِّنْهُ نَفْسًۭا فَكُلُوهُ هَنِيٓـًۭٔا مَّرِيٓـًۭٔا', 77, 4, 31, 0),
  (4, 5, 498, 'وَلَا تُؤْتُوا۟ ٱلسُّفَهَآءَ أَمْوَٰلَكُمُ ٱلَّتِى جَعَلَ ٱللَّهُ لَكُمْ قِيَٰمًۭا وَٱرْزُقُوهُمْ فِيهَا وَٱكْسُوهُمْ وَقُولُوا۟ لَهُمْ قَوْلًۭا مَّعْرُوفًۭا', 77, 4, 31, 0),
  (4, 6, 499, 'وَٱبْتَلُوا۟ ٱلْيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنْ ءَانَسْتُم مِّنْهُمْ رُشْدًۭا فَٱدْفَعُوٓا۟ إِلَيْهِمْ أَمْوَٰلَهُمْ ۖ وَلَا تَأْكُلُوهَآ إِسْرَافًۭا وَبِدَارًا أَن يَكْبَرُوا۟ ۚ وَمَن كَانَ غَنِيًّۭا فَلْيَسْتَعْفِفْ ۖ وَمَن كَانَ فَقِيرًۭا فَلْيَأْكُلْ بِٱلْمَعْرُوفِ ۚ فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَٰلَهُمْ فَأَشْهِدُوا۟ عَلَيْهِمْ ۚ وَكَفَىٰ بِٱللَّهِ حَسِيبًۭا', 77, 4, 31, 0),
  (4, 7, 500, 'لِّلرِّجَالِ نَصِيبٌۭ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ وَلِلنِّسَآءِ نَصِيبٌۭ مِّمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ مِمَّا قَلَّ مِنْهُ أَوْ كَثُرَ ۚ نَصِيبًۭا مَّفْرُوضًۭا', 78, 4, 31, 0),
  (4, 8, 501, 'وَإِذَا حَضَرَ ٱلْقِسْمَةَ أُو۟لُوا۟ ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينُ فَٱرْزُقُوهُم مِّنْهُ وَقُولُوا۟ لَهُمْ قَوْلًۭا مَّعْرُوفًۭا', 78, 4, 31, 0),
  (4, 9, 502, 'وَلْيَخْشَ ٱلَّذِينَ لَوْ تَرَكُوا۟ مِنْ خَلْفِهِمْ ذُرِّيَّةًۭ ضِعَٰفًا خَافُوا۟ عَلَيْهِمْ فَلْيَتَّقُوا۟ ٱللَّهَ وَلْيَقُولُوا۟ قَوْلًۭا سَدِيدًا', 78, 4, 31, 0),
  (4, 10, 503, 'إِنَّ ٱلَّذِينَ يَأْكُلُونَ أَمْوَٰلَ ٱلْيَتَٰمَىٰ ظُلْمًا إِنَّمَا يَأْكُلُونَ فِى بُطُونِهِمْ نَارًۭا ۖ وَسَيَصْلَوْنَ سَعِيرًۭا', 78, 4, 31, 0),
  (4, 11, 504, 'يُوصِيكُمُ ٱللَّهُ فِىٓ أَوْلَٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۚ فَإِن كُنَّ نِسَآءًۭ فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةًۭ فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٌۭ ۚ فَإِن لَّمْ يَكُن لَّهُۥ وَلَدٌۭ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ ۚ فَإِن كَانَ لَهُۥٓ إِخْوَةٌۭ فَلِأُمِّهِ ٱلسُّدُسُ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصِى بِهَآ أَوْ دَيْنٍ ۗ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًۭا ۚ فَرِيضَةًۭ مِّنَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا', 78, 4, 31, 0),
  (4, 12, 505, '۞ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌۭ ۚ فَإِن كَانَ لَهُنَّ وَلَدٌۭ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصِينَ بِهَآ أَوْ دَيْنٍۢ ۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌۭ ۚ فَإِن كَانَ لَكُمْ وَلَدٌۭ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم ۚ مِّنۢ بَعْدِ وَصِيَّةٍۢ تُوصُونَ بِهَآ أَوْ دَيْنٍۢ ۗ وَإِن كَانَ رَجُلٌۭ يُورَثُ كَلَٰلَةً أَوِ ٱمْرَأَةٌۭ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌۭ فَلِكُلِّ وَٰحِدٍۢ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِى ٱلثُّلُثِ ۚ مِنۢ بَعْدِ وَصِيَّةٍۢ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّۢ ۚ وَصِيَّةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌۭ', 79, 4, 32, 0),
  (4, 13, 506, 'تِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 79, 4, 32, 0),
  (4, 14, 507, 'وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدْخِلْهُ نَارًا خَٰلِدًۭا فِيهَا وَلَهُۥ عَذَابٌۭ مُّهِينٌۭ', 79, 4, 32, 0),
  (4, 15, 508, 'وَٱلَّٰتِى يَأْتِينَ ٱلْفَٰحِشَةَ مِن نِّسَآئِكُمْ فَٱسْتَشْهِدُوا۟ عَلَيْهِنَّ أَرْبَعَةًۭ مِّنكُمْ ۖ فَإِن شَهِدُوا۟ فَأَمْسِكُوهُنَّ فِى ٱلْبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلْمَوْتُ أَوْ يَجْعَلَ ٱللَّهُ لَهُنَّ سَبِيلًۭا', 80, 4, 32, 0),
  (4, 16, 509, 'وَٱلَّذَانِ يَأْتِيَٰنِهَا مِنكُمْ فَـَٔاذُوهُمَا ۖ فَإِن تَابَا وَأَصْلَحَا فَأَعْرِضُوا۟ عَنْهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ تَوَّابًۭا رَّحِيمًا', 80, 4, 32, 0),
  (4, 17, 510, 'إِنَّمَا ٱلتَّوْبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعْمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٍۢ ثُمَّ يَتُوبُونَ مِن قَرِيبٍۢ فَأُو۟لَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيْهِمْ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 80, 4, 32, 0),
  (4, 18, 511, 'وَلَيْسَتِ ٱلتَّوْبَةُ لِلَّذِينَ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ إِنِّى تُبْتُ ٱلْـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمْ كُفَّارٌ ۚ أُو۟لَٰٓئِكَ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًۭا', 80, 4, 32, 0),
  (4, 19, 512, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا۟ ٱلنِّسَآءَ كَرْهًۭا ۖ وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا۟ بِبَعْضِ مَآ ءَاتَيْتُمُوهُنَّ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍۢ مُّبَيِّنَةٍۢ ۚ وَعَاشِرُوهُنَّ بِٱلْمَعْرُوفِ ۚ فَإِن كَرِهْتُمُوهُنَّ فَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًۭٔا وَيَجْعَلَ ٱللَّهُ فِيهِ خَيْرًۭا كَثِيرًۭا', 80, 4, 32, 0),
  (4, 20, 513, 'وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍۢ مَّكَانَ زَوْجٍۢ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًۭا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا ۚ أَتَأْخُذُونَهُۥ بُهْتَٰنًۭا وَإِثْمًۭا مُّبِينًۭا', 81, 4, 32, 0),
  (4, 21, 514, 'وَكَيْفَ تَأْخُذُونَهُۥ وَقَدْ أَفْضَىٰ بَعْضُكُمْ إِلَىٰ بَعْضٍۢ وَأَخَذْنَ مِنكُم مِّيثَٰقًا غَلِيظًۭا', 81, 4, 32, 0),
  (4, 22, 515, 'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ ۚ إِنَّهُۥ كَانَ فَٰحِشَةًۭ وَمَقْتًۭا وَسَآءَ سَبِيلًا', 81, 4, 32, 0),
  (4, 23, 516, 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ وَبَنَاتُكُمْ وَأَخَوَٰتُكُمْ وَعَمَّٰتُكُمْ وَخَٰلَٰتُكُمْ وَبَنَاتُ ٱلْأَخِ وَبَنَاتُ ٱلْأُخْتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِىٓ أَرْضَعْنَكُمْ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمْ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِى فِى حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِى دَخَلْتُم بِهِنَّ فَإِن لَّمْ تَكُونُوا۟ دَخَلْتُم بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَٰٓئِلُ أَبْنَآئِكُمُ ٱلَّذِينَ مِنْ أَصْلَٰبِكُمْ وَأَن تَجْمَعُوا۟ بَيْنَ ٱلْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ ۗ إِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا', 81, 4, 32, 0),
  (4, 24, 517, '۞ وَٱلْمُحْصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتْ أَيْمَٰنُكُمْ ۖ كِتَٰبَ ٱللَّهِ عَلَيْكُمْ ۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ أَن تَبْتَغُوا۟ بِأَمْوَٰلِكُم مُّحْصِنِينَ غَيْرَ مُسَٰفِحِينَ ۚ فَمَا ٱسْتَمْتَعْتُم بِهِۦ مِنْهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةًۭ ۚ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا تَرَٰضَيْتُم بِهِۦ مِنۢ بَعْدِ ٱلْفَرِيضَةِ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًۭا', 82, 5, 33, 0),
  (4, 25, 518, 'وَمَن لَّمْ يَسْتَطِعْ مِنكُمْ طَوْلًا أَن يَنكِحَ ٱلْمُحْصَنَٰتِ ٱلْمُؤْمِنَٰتِ فَمِن مَّا مَلَكَتْ أَيْمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلْمُؤْمِنَٰتِ ۚ وَٱللَّهُ أَعْلَمُ بِإِيمَٰنِكُم ۚ بَعْضُكُم مِّنۢ بَعْضٍۢ ۚ فَٱنكِحُوهُنَّ بِإِذْنِ أَهْلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلْمَعْرُوفِ مُحْصَنَٰتٍ غَيْرَ مُسَٰفِحَٰتٍۢ وَلَا مُتَّخِذَٰتِ أَخْدَانٍۢ ۚ فَإِذَآ أُحْصِنَّ فَإِنْ أَتَيْنَ بِفَٰحِشَةٍۢ فَعَلَيْهِنَّ نِصْفُ مَا عَلَى ٱلْمُحْصَنَٰتِ مِنَ ٱلْعَذَابِ ۚ ذَٰلِكَ لِمَنْ خَشِىَ ٱلْعَنَتَ مِنكُمْ ۚ وَأَن تَصْبِرُوا۟ خَيْرٌۭ لَّكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 82, 5, 33, 0),
  (4, 26, 519, 'يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ ٱلَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 82, 5, 33, 0),
  (4, 27, 520, 'وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيْكُمْ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُوا۟ مَيْلًا عَظِيمًۭا', 83, 5, 33, 0),
  (4, 28, 521, 'يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمْ ۚ وَخُلِقَ ٱلْإِنسَٰنُ ضَعِيفًۭا', 83, 5, 33, 0),
  (4, 29, 522, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٍۢ مِّنكُمْ ۚ وَلَا تَقْتُلُوٓا۟ أَنفُسَكُمْ ۚ إِنَّ ٱللَّهَ كَانَ بِكُمْ رَحِيمًۭا', 83, 5, 33, 0),
  (4, 30, 523, 'وَمَن يَفْعَلْ ذَٰلِكَ عُدْوَٰنًۭا وَظُلْمًۭا فَسَوْفَ نُصْلِيهِ نَارًۭا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا', 83, 5, 33, 0),
  (4, 31, 524, 'إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًۭا كَرِيمًۭا', 83, 5, 33, 0),
  (4, 32, 525, 'وَلَا تَتَمَنَّوْا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعْضَكُمْ عَلَىٰ بَعْضٍۢ ۚ لِّلرِّجَالِ نَصِيبٌۭ مِّمَّا ٱكْتَسَبُوا۟ ۖ وَلِلنِّسَآءِ نَصِيبٌۭ مِّمَّا ٱكْتَسَبْنَ ۚ وَسْـَٔلُوا۟ ٱللَّهَ مِن فَضْلِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًۭا', 83, 5, 33, 0),
  (4, 33, 526, 'وَلِكُلٍّۢ جَعَلْنَا مَوَٰلِىَ مِمَّا تَرَكَ ٱلْوَٰلِدَانِ وَٱلْأَقْرَبُونَ ۚ وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ ۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدًا', 83, 5, 33, 0),
  (4, 34, 527, 'ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعْضَهُمْ عَلَىٰ بَعْضٍۢ وَبِمَآ أَنفَقُوا۟ مِنْ أَمْوَٰلِهِمْ ۚ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٌۭ لِّلْغَيْبِ بِمَا حَفِظَ ٱللَّهُ ۚ وَٱلَّٰتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهْجُرُوهُنَّ فِى ٱلْمَضَاجِعِ وَٱضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا۟ عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ ٱللَّهَ كَانَ عَلِيًّۭا كَبِيرًۭا', 84, 5, 33, 0),
  (4, 35, 528, 'وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَٱبْعَثُوا۟ حَكَمًۭا مِّنْ أَهْلِهِۦ وَحَكَمًۭا مِّنْ أَهْلِهَآ إِن يُرِيدَآ إِصْلَٰحًۭا يُوَفِّقِ ٱللَّهُ بَيْنَهُمَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرًۭا', 84, 5, 33, 0),
  (4, 36, 529, '۞ وَٱعْبُدُوا۟ ٱللَّهَ وَلَا تُشْرِكُوا۟ بِهِۦ شَيْـًۭٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًۭا وَبِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱلْجَارِ ذِى ٱلْقُرْبَىٰ وَٱلْجَارِ ٱلْجُنُبِ وَٱلصَّاحِبِ بِٱلْجَنۢبِ وَٱبْنِ ٱلسَّبِيلِ وَمَا مَلَكَتْ أَيْمَٰنُكُمْ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًۭا فَخُورًا', 84, 5, 34, 0),
  (4, 37, 530, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ وَيَكْتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًۭا مُّهِينًۭا', 84, 5, 34, 0),
  (4, 38, 531, 'وَٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْءَاخِرِ ۗ وَمَن يَكُنِ ٱلشَّيْطَٰنُ لَهُۥ قَرِينًۭا فَسَآءَ قَرِينًۭا', 85, 5, 34, 0),
  (4, 39, 532, 'وَمَاذَا عَلَيْهِمْ لَوْ ءَامَنُوا۟ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُ ۚ وَكَانَ ٱللَّهُ بِهِمْ عَلِيمًا', 85, 5, 34, 0),
  (4, 40, 533, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍۢ ۖ وَإِن تَكُ حَسَنَةًۭ يُضَٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًۭا', 85, 5, 34, 0),
  (4, 41, 534, 'فَكَيْفَ إِذَا جِئْنَا مِن كُلِّ أُمَّةٍۭ بِشَهِيدٍۢ وَجِئْنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدًۭا', 85, 5, 34, 0),
  (4, 42, 535, 'يَوْمَئِذٍۢ يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوْ تُسَوَّىٰ بِهِمُ ٱلْأَرْضُ وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًۭا', 85, 5, 34, 0),
  (4, 43, 536, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌۭ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُمْ ۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا', 85, 5, 34, 0),
  (4, 44, 537, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يَشْتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّوا۟ ٱلسَّبِيلَ', 85, 5, 34, 0),
  (4, 45, 538, 'وَٱللَّهُ أَعْلَمُ بِأَعْدَآئِكُمْ ۚ وَكَفَىٰ بِٱللَّهِ وَلِيًّۭا وَكَفَىٰ بِٱللَّهِ نَصِيرًۭا', 86, 5, 34, 0),
  (4, 46, 539, 'مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍۢ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًۭا فِى ٱلدِّينِ ۚ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًۭا لَّهُمْ وَأَقْوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًۭا', 86, 5, 34, 0),
  (4, 47, 540, 'يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ ءَامِنُوا۟ بِمَا نَزَّلْنَا مُصَدِّقًۭا لِّمَا مَعَكُم مِّن قَبْلِ أَن نَّطْمِسَ وُجُوهًۭا فَنَرُدَّهَا عَلَىٰٓ أَدْبَارِهَآ أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّآ أَصْحَٰبَ ٱلسَّبْتِ ۚ وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا', 86, 5, 34, 0),
  (4, 48, 541, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدِ ٱفْتَرَىٰٓ إِثْمًا عَظِيمًا', 86, 5, 34, 0),
  (4, 49, 542, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُم ۚ بَلِ ٱللَّهُ يُزَكِّى مَن يَشَآءُ وَلَا يُظْلَمُونَ فَتِيلًا', 86, 5, 34, 0),
  (4, 50, 543, 'ٱنظُرْ كَيْفَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَكَفَىٰ بِهِۦٓ إِثْمًۭا مُّبِينًا', 86, 5, 34, 0),
  (4, 51, 544, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يُؤْمِنُونَ بِٱلْجِبْتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُوا۟ هَٰٓؤُلَآءِ أَهْدَىٰ مِنَ ٱلَّذِينَ ءَامَنُوا۟ سَبِيلًا', 86, 5, 34, 0),
  (4, 52, 545, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ ۖ وَمَن يَلْعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا', 87, 5, 34, 0),
  (4, 53, 546, 'أَمْ لَهُمْ نَصِيبٌۭ مِّنَ ٱلْمُلْكِ فَإِذًۭا لَّا يُؤْتُونَ ٱلنَّاسَ نَقِيرًا', 87, 5, 34, 0),
  (4, 54, 547, 'أَمْ يَحْسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۖ فَقَدْ ءَاتَيْنَآ ءَالَ إِبْرَٰهِيمَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَءَاتَيْنَٰهُم مُّلْكًا عَظِيمًۭا', 87, 5, 34, 0),
  (4, 55, 548, 'فَمِنْهُم مَّنْ ءَامَنَ بِهِۦ وَمِنْهُم مَّن صَدَّ عَنْهُ ۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا', 87, 5, 34, 0),
  (4, 56, 549, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا سَوْفَ نُصْلِيهِمْ نَارًۭا كُلَّمَا نَضِجَتْ جُلُودُهُم بَدَّلْنَٰهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا۟ ٱلْعَذَابَ ۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمًۭا', 87, 5, 34, 0),
  (4, 57, 550, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ لَّهُمْ فِيهَآ أَزْوَٰجٌۭ مُّطَهَّرَةٌۭ ۖ وَنُدْخِلُهُمْ ظِلًّۭا ظَلِيلًا', 87, 5, 34, 0),
  (4, 58, 551, '۞ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَٰنَٰتِ إِلَىٰٓ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ ٱلنَّاسِ أَن تَحْكُمُوا۟ بِٱلْعَدْلِ ۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓ ۗ إِنَّ ٱللَّهَ كَانَ سَمِيعًۢا بَصِيرًۭا', 87, 5, 35, 0),
  (4, 59, 552, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ ۖ فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍۢ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ ذَٰلِكَ خَيْرٌۭ وَأَحْسَنُ تَأْوِيلًا', 87, 5, 35, 0),
  (4, 60, 553, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يَزْعُمُونَ أَنَّهُمْ ءَامَنُوا۟ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓا۟ إِلَى ٱلطَّٰغُوتِ وَقَدْ أُمِرُوٓا۟ أَن يَكْفُرُوا۟ بِهِۦ وَيُرِيدُ ٱلشَّيْطَٰنُ أَن يُضِلَّهُمْ ضَلَٰلًۢا بَعِيدًۭا', 88, 5, 35, 0),
  (4, 61, 554, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًۭا', 88, 5, 35, 0),
  (4, 62, 555, 'فَكَيْفَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ ثُمَّ جَآءُوكَ يَحْلِفُونَ بِٱللَّهِ إِنْ أَرَدْنَآ إِلَّآ إِحْسَٰنًۭا وَتَوْفِيقًا', 88, 5, 35, 0),
  (4, 63, 556, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَعْلَمُ ٱللَّهُ مَا فِى قُلُوبِهِمْ فَأَعْرِضْ عَنْهُمْ وَعِظْهُمْ وَقُل لَّهُمْ فِىٓ أَنفُسِهِمْ قَوْلًۢا بَلِيغًۭا', 88, 5, 35, 0),
  (4, 64, 557, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ ٱللَّهِ ۚ وَلَوْ أَنَّهُمْ إِذ ظَّلَمُوٓا۟ أَنفُسَهُمْ جَآءُوكَ فَٱسْتَغْفَرُوا۟ ٱللَّهَ وَٱسْتَغْفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابًۭا رَّحِيمًۭا', 88, 5, 35, 0),
  (4, 65, 558, 'فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًۭا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًۭا', 88, 5, 35, 0),
  (4, 66, 559, 'وَلَوْ أَنَّا كَتَبْنَا عَلَيْهِمْ أَنِ ٱقْتُلُوٓا۟ أَنفُسَكُمْ أَوِ ٱخْرُجُوا۟ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٌۭ مِّنْهُمْ ۖ وَلَوْ أَنَّهُمْ فَعَلُوا۟ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيْرًۭا لَّهُمْ وَأَشَدَّ تَثْبِيتًۭا', 89, 5, 35, 0),
  (4, 67, 560, 'وَإِذًۭا لَّءَاتَيْنَٰهُم مِّن لَّدُنَّآ أَجْرًا عَظِيمًۭا', 89, 5, 35, 0),
  (4, 68, 561, 'وَلَهَدَيْنَٰهُمْ صِرَٰطًۭا مُّسْتَقِيمًۭا', 89, 5, 35, 0),
  (4, 69, 562, 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٰٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَ ۚ وَحَسُنَ أُو۟لَٰٓئِكَ رَفِيقًۭا', 89, 5, 35, 0),
  (4, 70, 563, 'ذَٰلِكَ ٱلْفَضْلُ مِنَ ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ عَلِيمًۭا', 89, 5, 35, 0),
  (4, 71, 564, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ خُذُوا۟ حِذْرَكُمْ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِيعًۭا', 89, 5, 35, 0),
  (4, 72, 565, 'وَإِنَّ مِنكُمْ لَمَن لَّيُبَطِّئَنَّ فَإِنْ أَصَٰبَتْكُم مُّصِيبَةٌۭ قَالَ قَدْ أَنْعَمَ ٱللَّهُ عَلَىَّ إِذْ لَمْ أَكُن مَّعَهُمْ شَهِيدًۭا', 89, 5, 35, 0),
  (4, 73, 566, 'وَلَئِنْ أَصَٰبَكُمْ فَضْلٌۭ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمْ تَكُنۢ بَيْنَكُمْ وَبَيْنَهُۥ مَوَدَّةٌۭ يَٰلَيْتَنِى كُنتُ مَعَهُمْ فَأَفُوزَ فَوْزًا عَظِيمًۭا', 89, 5, 35, 0),
  (4, 74, 567, '۞ فَلْيُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشْرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْءَاخِرَةِ ۚ وَمَن يُقَٰتِلْ فِى سَبِيلِ ٱللَّهِ فَيُقْتَلْ أَوْ يَغْلِبْ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًۭا', 89, 5, 36, 0),
  (4, 75, 568, 'وَمَا لَكُمْ لَا تُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخْرِجْنَا مِنْ هَٰذِهِ ٱلْقَرْيَةِ ٱلظَّالِمِ أَهْلُهَا وَٱجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّۭا وَٱجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا', 90, 5, 36, 0),
  (4, 76, 569, 'ٱلَّذِينَ ءَامَنُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ وَٱلَّذِينَ كَفَرُوا۟ يُقَٰتِلُونَ فِى سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓا۟ أَوْلِيَآءَ ٱلشَّيْطَٰنِ ۖ إِنَّ كَيْدَ ٱلشَّيْطَٰنِ كَانَ ضَعِيفًا', 90, 5, 36, 0),
  (4, 77, 570, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمْ كُفُّوٓا۟ أَيْدِيَكُمْ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ إِذَا فَرِيقٌۭ مِّنْهُمْ يَخْشَوْنَ ٱلنَّاسَ كَخَشْيَةِ ٱللَّهِ أَوْ أَشَدَّ خَشْيَةًۭ ۚ وَقَالُوا۟ رَبَّنَا لِمَ كَتَبْتَ عَلَيْنَا ٱلْقِتَالَ لَوْلَآ أَخَّرْتَنَآ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ ۗ قُلْ مَتَٰعُ ٱلدُّنْيَا قَلِيلٌۭ وَٱلْءَاخِرَةُ خَيْرٌۭ لِّمَنِ ٱتَّقَىٰ وَلَا تُظْلَمُونَ فَتِيلًا', 90, 5, 36, 0),
  (4, 78, 571, 'أَيْنَمَا تَكُونُوا۟ يُدْرِككُّمُ ٱلْمَوْتُ وَلَوْ كُنتُمْ فِى بُرُوجٍۢ مُّشَيَّدَةٍۢ ۗ وَإِن تُصِبْهُمْ حَسَنَةٌۭ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِ ٱللَّهِ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۭ يَقُولُوا۟ هَٰذِهِۦ مِنْ عِندِكَ ۚ قُلْ كُلٌّۭ مِّنْ عِندِ ٱللَّهِ ۖ فَمَالِ هَٰٓؤُلَآءِ ٱلْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًۭا', 90, 5, 36, 0),
  (4, 79, 572, 'مَّآ أَصَابَكَ مِنْ حَسَنَةٍۢ فَمِنَ ٱللَّهِ ۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٍۢ فَمِن نَّفْسِكَ ۚ وَأَرْسَلْنَٰكَ لِلنَّاسِ رَسُولًۭا ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًۭا', 90, 5, 36, 0),
  (4, 80, 573, 'مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ ۖ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًۭا', 91, 5, 36, 0),
  (4, 81, 574, 'وَيَقُولُونَ طَاعَةٌۭ فَإِذَا بَرَزُوا۟ مِنْ عِندِكَ بَيَّتَ طَآئِفَةٌۭ مِّنْهُمْ غَيْرَ ٱلَّذِى تَقُولُ ۖ وَٱللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ ۖ فَأَعْرِضْ عَنْهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 91, 5, 36, 0),
  (4, 82, 575, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ ۚ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَٰفًۭا كَثِيرًۭا', 91, 5, 36, 0),
  (4, 83, 576, 'وَإِذَا جَآءَهُمْ أَمْرٌۭ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ ۖ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ ۗ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَٰنَ إِلَّا قَلِيلًۭا', 91, 5, 36, 0),
  (4, 84, 577, 'فَقَٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ ۚ وَحَرِّضِ ٱلْمُؤْمِنِينَ ۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَٱللَّهُ أَشَدُّ بَأْسًۭا وَأَشَدُّ تَنكِيلًۭا', 91, 5, 36, 0),
  (4, 85, 578, 'مَّن يَشْفَعْ شَفَٰعَةً حَسَنَةًۭ يَكُن لَّهُۥ نَصِيبٌۭ مِّنْهَا ۖ وَمَن يَشْفَعْ شَفَٰعَةًۭ سَيِّئَةًۭ يَكُن لَّهُۥ كِفْلٌۭ مِّنْهَا ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ مُّقِيتًۭا', 91, 5, 36, 0),
  (4, 86, 579, 'وَإِذَا حُيِّيتُم بِتَحِيَّةٍۢ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا', 91, 5, 36, 0),
  (4, 87, 580, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ۗ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًۭا', 92, 5, 36, 0),
  (4, 88, 581, '۞ فَمَا لَكُمْ فِى ٱلْمُنَٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ ۚ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًۭا', 92, 5, 37, 0),
  (4, 89, 582, 'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءًۭ ۖ فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ ۖ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّۭا وَلَا نَصِيرًا', 92, 5, 37, 0),
  (4, 90, 583, 'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَٰتِلُوكُمْ أَوْ يُقَٰتِلُوا۟ قَوْمَهُمْ ۚ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَٰتَلُوكُمْ ۚ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًۭا', 92, 5, 37, 0),
  (4, 91, 584, 'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا ۚ فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ ۚ وَأُو۟لَٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَٰنًۭا مُّبِينًۭا', 92, 5, 37, 0),
  (4, 92, 585, 'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًۭٔا ۚ وَمَن قَتَلَ مُؤْمِنًا خَطَـًۭٔا فَتَحْرِيرُ رَقَبَةٍۢ مُّؤْمِنَةٍۢ وَدِيَةٌۭ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ ۚ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّۢ لَّكُمْ وَهُوَ مُؤْمِنٌۭ فَتَحْرِيرُ رَقَبَةٍۢ مُّؤْمِنَةٍۢ ۖ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌۭ فَدِيَةٌۭ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍۢ مُّؤْمِنَةٍۢ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةًۭ مِّنَ ٱللَّهِ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 93, 5, 37, 0),
  (4, 93, 586, 'وَمَن يَقْتُلْ مُؤْمِنًۭا مُّتَعَمِّدًۭا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدًۭا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًۭا', 93, 5, 37, 0),
  (4, 94, 587, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًۭا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌۭ ۚ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا', 93, 5, 37, 0),
  (4, 95, 588, 'لَّا يَسْتَوِى ٱلْقَٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ فَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَٰعِدِينَ دَرَجَةًۭ ۚ وَكُلًّۭا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَفَضَّلَ ٱللَّهُ ٱلْمُجَٰهِدِينَ عَلَى ٱلْقَٰعِدِينَ أَجْرًا عَظِيمًۭا', 94, 5, 37, 0),
  (4, 96, 589, 'دَرَجَٰتٍۢ مِّنْهُ وَمَغْفِرَةًۭ وَرَحْمَةًۭ ۚ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًا', 94, 5, 37, 0),
  (4, 97, 590, 'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ ۖ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ ۚ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةًۭ فَتُهَاجِرُوا۟ فِيهَا ۚ فَأُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ ۖ وَسَآءَتْ مَصِيرًا', 94, 5, 37, 0),
  (4, 98, 591, 'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةًۭ وَلَا يَهْتَدُونَ سَبِيلًۭا', 94, 5, 37, 0),
  (4, 99, 592, 'فَأُو۟لَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًۭا', 94, 5, 37, 0),
  (4, 100, 593, '۞ وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًۭا كَثِيرًۭا وَسَعَةًۭ ۚ وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 94, 5, 38, 0),
  (4, 101, 594, 'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ ۚ إِنَّ ٱلْكَٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّۭا مُّبِينًۭا', 94, 5, 38, 0),
  (4, 102, 595, 'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌۭ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ ۗ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةًۭ وَٰحِدَةًۭ ۚ وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًۭى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ ۖ وَخُذُوا۟ حِذْرَكُمْ ۗ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَٰفِرِينَ عَذَابًۭا مُّهِينًۭا', 95, 5, 38, 0),
  (4, 103, 596, 'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَٰمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًۭا مَّوْقُوتًۭا', 95, 5, 38, 0),
  (4, 104, 597, 'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ ۖ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ ۖ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا', 95, 5, 38, 0),
  (4, 105, 598, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ ۚ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًۭا', 95, 5, 38, 0),
  (4, 106, 599, 'وَٱسْتَغْفِرِ ٱللَّهَ ۖ إِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا', 96, 5, 38, 0),
  (4, 107, 600, 'وَلَا تُجَٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًۭا', 96, 5, 38, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 4, 1, 'O mankind, fear your Lord, who created you from one soul and created from it its mate and dispersed from both of them many men and women. And fear Allah, through whom you ask one another, and the wombs. Indeed Allah is ever, over you, an Observer.'),
  ('en.sahih', 4, 2, 'And give to the orphans their properties and do not substitute the defective [of your own] for the good [of theirs]. And do not consume their properties into your own. Indeed, that is ever a great sin.'),
  ('en.sahih', 4, 3, 'And if you fear that you will not deal justly with the orphan girls, then marry those that please you of [other] women, two or three or four. But if you fear that you will not be just, then [marry only] one or those your right hand possesses. That is more suitable that you may not incline [to injustice].'),
  ('en.sahih', 4, 4, 'And give the women [upon marriage] their [bridal] gifts graciously. But if they give up willingly to you anything of it, then take it in satisfaction and ease.'),
  ('en.sahih', 4, 5, 'And do not give the weak-minded your property, which Allah has made a means of sustenance for you, but provide for them with it and clothe them and speak to them words of appropriate kindness.'),
  ('en.sahih', 4, 6, 'And test the orphans [in their abilities] until they reach marriageable age. Then if you perceive in them sound judgement, release their property to them. And do not consume it excessively and quickly, [anticipating] that they will grow up. And whoever, [when acting as guardian], is self-sufficient should refrain [from taking a fee]; and whoever is poor - let him take according to what is acceptable. Then when you release their property to them, bring witnesses upon them. And sufficient is Allah as Accountant.'),
  ('en.sahih', 4, 7, 'For men is a share of what the parents and close relatives leave, and for women is a share of what the parents and close relatives leave, be it little or much - an obligatory share.'),
  ('en.sahih', 4, 8, 'And when [other] relatives and orphans and the needy are present at the [time of] division, then provide for them [something] out of the estate and speak to them words of appropriate kindness.'),
  ('en.sahih', 4, 9, 'And let those [executors and guardians] fear [injustice] as if they [themselves] had left weak offspring behind and feared for them. So let them fear Allah and speak words of appropriate justice.'),
  ('en.sahih', 4, 10, 'Indeed, those who devour the property of orphans unjustly are only consuming into their bellies fire. And they will be burned in a Blaze.'),
  ('en.sahih', 4, 11, 'Allah instructs you concerning your children: for the male, what is equal to the share of two females. But if there are [only] daughters, two or more, for them is two thirds of one\'s estate. And if there is only one, for her is half. And for one\'s parents, to each one of them is a sixth of his estate if he left children. But if he had no children and the parents [alone] inherit from him, then for his mother is one third. And if he had brothers [or sisters], for his mother is a sixth, after any bequest he [may have] made or debt. Your parents or your children - you know not which of them are nearest to you in benefit. [These shares are] an obligation [imposed] by Allah. Indeed, Allah is ever Knowing and Wise.'),
  ('en.sahih', 4, 12, 'And for you is half of what your wives leave if they have no child. But if they have a child, for you is one fourth of what they leave, after any bequest they [may have] made or debt. And for the wives is one fourth if you leave no child. But if you leave a child, then for them is an eighth of what you leave, after any bequest you [may have] made or debt. And if a man or woman leaves neither ascendants nor descendants but has a brother or a sister, then for each one of them is a sixth. But if they are more than two, they share a third, after any bequest which was made or debt, as long as there is no detriment [caused]. [This is] an ordinance from Allah, and Allah is Knowing and Forbearing.'),
  ('en.sahih', 4, 13, 'These are the limits [set by] Allah, and whoever obeys Allah and His Messenger will be admitted by Him to gardens [in Paradise] under which rivers flow, abiding eternally therein; and that is the great attainment.'),
  ('en.sahih', 4, 14, 'And whoever disobeys Allah and His Messenger and transgresses His limits - He will put him into the Fire to abide eternally therein, and he will have a humiliating punishment.'),
  ('en.sahih', 4, 15, 'Those who commit unlawful sexual intercourse of your women - bring against them four [witnesses] from among you. And if they testify, confine the guilty women to houses until death takes them or Allah ordains for them [another] way.'),
  ('en.sahih', 4, 16, 'And the two who commit it among you, dishonor them both. But if they repent and correct themselves, leave them alone. Indeed, Allah is ever Accepting of repentance and Merciful.'),
  ('en.sahih', 4, 17, 'The repentance accepted by Allah is only for those who do wrong in ignorance [or carelessness] and then repent soon after. It is those to whom Allah will turn in forgiveness, and Allah is ever Knowing and Wise.'),
  ('en.sahih', 4, 18, 'But repentance is not [accepted] of those who [continue to] do evil deeds up until, when death comes to one of them, he says, "Indeed, I have repented now," or of those who die while they are disbelievers. For them We have prepared a painful punishment.'),
  ('en.sahih', 4, 19, 'O you who have believed, it is not lawful for you to inherit women by compulsion. And do not make difficulties for them in order to take [back] part of what you gave them unless they commit a clear immorality. And live with them in kindness. For if you dislike them - perhaps you dislike a thing and Allah makes therein much good.'),
  ('en.sahih', 4, 20, 'But if you want to replace one wife with another and you have given one of them a great amount [in gifts], do not take [back] from it anything. Would you take it in injustice and manifest sin?'),
  ('en.sahih', 4, 21, 'And how could you take it while you have gone in unto each other and they have taken from you a solemn covenant?'),
  ('en.sahih', 4, 22, 'And do not marry those [women] whom your fathers married, except what has already occurred. Indeed, it was an immorality and hateful [to Allah] and was evil as a way.'),
  ('en.sahih', 4, 23, 'Prohibited to you [for marriage] are your mothers, your daughters, your sisters, your father\'s sisters, your mother\'s sisters, your brother\'s daughters, your sister\'s daughters, your [milk] mothers who nursed you, your sisters through nursing, your wives\' mothers, and your step-daughters under your guardianship [born] of your wives unto whom you have gone in. But if you have not gone in unto them, there is no sin upon you. And [also prohibited are] the wives of your sons who are from your [own] loins, and that you take [in marriage] two sisters simultaneously, except for what has already occurred. Indeed, Allah is ever Forgiving and Merciful.'),
  ('en.sahih', 4, 24, 'And [also prohibited to you are all] married women except those your right hands possess. [This is] the decree of Allah upon you. And lawful to you are [all others] beyond these, [provided] that you seek them [in marriage] with [gifts from] your property, desiring chastity, not unlawful sexual intercourse. So for whatever you enjoy [of marriage] from them, give them their due compensation as an obligation. And there is no blame upon you for what you mutually agree to beyond the obligation. Indeed, Allah is ever Knowing and Wise.'),
  ('en.sahih', 4, 25, 'And whoever among you cannot [find] the means to marry free, believing women, then [he may marry] from those whom your right hands possess of believing slave girls. And Allah is most knowing about your faith. You [believers] are of one another. So marry them with the permission of their people and give them their due compensation according to what is acceptable. [They should be] chaste, neither [of] those who commit unlawful intercourse randomly nor those who take [secret] lovers. But once they are sheltered in marriage, if they should commit adultery, then for them is half the punishment for free [unmarried] women. This [allowance] is for him among you who fears sin, but to be patient is better for you. And Allah is Forgiving and Merciful.'),
  ('en.sahih', 4, 26, 'Allah wants to make clear to you [the lawful from the unlawful] and guide you to the [good] practices of those before you and to accept your repentance. And Allah is Knowing and Wise.'),
  ('en.sahih', 4, 27, 'Allah wants to accept your repentance, but those who follow [their] passions want you to digress [into] a great deviation.'),
  ('en.sahih', 4, 28, 'And Allah wants to lighten for you [your difficulties]; and mankind was created weak.'),
  ('en.sahih', 4, 29, 'O you who have believed, do not consume one another\'s wealth unjustly but only [in lawful] business by mutual consent. And do not kill yourselves [or one another]. Indeed, Allah is to you ever Merciful.'),
  ('en.sahih', 4, 30, 'And whoever does that in aggression and injustice - then We will drive him into a Fire. And that, for Allah, is [always] easy.'),
  ('en.sahih', 4, 31, 'If you avoid the major sins which you are forbidden, We will remove from you your lesser sins and admit you to a noble entrance [into Paradise].'),
  ('en.sahih', 4, 32, 'And do not wish for that by which Allah has made some of you exceed others. For men is a share of what they have earned, and for women is a share of what they have earned. And ask Allah of his bounty. Indeed Allah is ever, of all things, Knowing.'),
  ('en.sahih', 4, 33, 'And for all, We have made heirs to what is left by parents and relatives. And to those whom your oaths have bound [to you] - give them their share. Indeed Allah is ever, over all things, a Witness.'),
  ('en.sahih', 4, 34, 'Men are in charge of women by [right of] what Allah has given one over the other and what they spend [for maintenance] from their wealth. So righteous women are devoutly obedient, guarding in [the husband\'s] absence what Allah would have them guard. But those [wives] from whom you fear arrogance - [first] advise them; [then if they persist], forsake them in bed; and [finally], strike them. But if they obey you [once more], seek no means against them. Indeed, Allah is ever Exalted and Grand.'),
  ('en.sahih', 4, 35, 'And if you fear dissension between the two, send an arbitrator from his people and an arbitrator from her people. If they both desire reconciliation, Allah will cause it between them. Indeed, Allah is ever Knowing and Acquainted [with all things].'),
  ('en.sahih', 4, 36, 'Worship Allah and associate nothing with Him, and to parents do good, and to relatives, orphans, the needy, the near neighbor, the neighbor farther away, the companion at your side, the traveler, and those whom your right hands possess. Indeed, Allah does not like those who are self-deluding and boastful.'),
  ('en.sahih', 4, 37, 'Who are stingy and enjoin upon [other] people stinginess and conceal what Allah has given them of His bounty - and We have prepared for the disbelievers a humiliating punishment -'),
  ('en.sahih', 4, 38, 'And [also] those who spend of their wealth to be seen by the people and believe not in Allah nor in the Last Day. And he to whom Satan is a companion - then evil is he as a companion.'),
  ('en.sahih', 4, 39, 'And what [harm would come] upon them if they believed in Allah and the Last Day and spent out of what Allah provided for them? And Allah is ever, about them, Knowing.'),
  ('en.sahih', 4, 40, 'Indeed, Allah does not do injustice, [even] as much as an atom\'s weight; while if there is a good deed, He multiplies it and gives from Himself a great reward.'),
  ('en.sahih', 4, 41, 'So how [will it be] when We bring from every nation a witness and we bring you, [O Muhammad] against these [people] as a witness?'),
  ('en.sahih', 4, 42, 'That Day, those who disbelieved and disobeyed the Messenger will wish they could be covered by the earth. And they will not conceal from Allah a [single] statement.'),
  ('en.sahih', 4, 43, 'O you who have believed, do not approach prayer while you are intoxicated until you know what you are saying or in a state of janabah, except those passing through [a place of prayer], until you have washed [your whole body]. And if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and find no water, then seek clean earth and wipe over your faces and your hands [with it]. Indeed, Allah is ever Pardoning and Forgiving.'),
  ('en.sahih', 4, 44, 'Have you not seen those who were given a portion of the Scripture, purchasing error [in exchange for it] and wishing you would lose the way?'),
  ('en.sahih', 4, 45, 'And Allah is most knowing of your enemies; and sufficient is Allah as an ally, and sufficient is Allah as a helper.'),
  ('en.sahih', 4, 46, 'Among the Jews are those who distort words from their [proper] usages and say, "We hear and disobey" and "Hear but be not heard" and "Ra\'ina," twisting their tongues and defaming the religion. And if they had said [instead], "We hear and obey" and "Wait for us [to understand]," it would have been better for them and more suitable. But Allah has cursed them for their disbelief, so they believe not, except for a few.'),
  ('en.sahih', 4, 47, 'O you who were given the Scripture, believe in what We have sent down [to Muhammad], confirming that which is with you, before We obliterate faces and turn them toward their backs or curse them as We cursed the sabbath-breakers. And ever is the decree of Allah accomplished.'),
  ('en.sahih', 4, 48, 'Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly fabricated a tremendous sin.'),
  ('en.sahih', 4, 49, 'Have you not seen those who claim themselves to be pure? Rather, Allah purifies whom He wills, and injustice is not done to them, [even] as much as a thread [inside a date seed].'),
  ('en.sahih', 4, 50, 'Look how they invent about Allah untruth, and sufficient is that as a manifest sin.'),
  ('en.sahih', 4, 51, 'Have you not seen those who were given a portion of the Scripture, who believe in superstition and false objects of worship and say about the disbelievers, "These are better guided than the believers as to the way"?'),
  ('en.sahih', 4, 52, 'Those are the ones whom Allah has cursed; and he whom Allah curses - never will you find for him a helper.'),
  ('en.sahih', 4, 53, 'Or have they a share of dominion? Then [if that were so], they would not give the people [even as much as] the speck on a date seed.'),
  ('en.sahih', 4, 54, 'Or do they envy people for what Allah has given them of His bounty? But we had already given the family of Abraham the Scripture and wisdom and conferred upon them a great kingdom.'),
  ('en.sahih', 4, 55, 'And some among them believed in it, and some among them were averse to it. And sufficient is Hell as a blaze.'),
  ('en.sahih', 4, 56, 'Indeed, those who disbelieve in Our verses - We will drive them into a Fire. Every time their skins are roasted through We will replace them with other skins so they may taste the punishment. Indeed, Allah is ever Exalted in Might and Wise.'),
  ('en.sahih', 4, 57, 'But those who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they abide forever. For them therein are purified spouses, and We will admit them to deepening shade.'),
  ('en.sahih', 4, 58, 'Indeed, Allah commands you to render trusts to whom they are due and when you judge between people to judge with justice. Excellent is that which Allah instructs you. Indeed, Allah is ever Hearing and Seeing.'),
  ('en.sahih', 4, 59, 'O you who have believed, obey Allah and obey the Messenger and those in authority among you. And if you disagree over anything, refer it to Allah and the Messenger, if you should believe in Allah and the Last Day. That is the best [way] and best in result.'),
  ('en.sahih', 4, 60, 'Have you not seen those who claim to have believed in what was revealed to you, [O Muhammad], and what was revealed before you? They wish to refer legislation to Taghut, while they were commanded to reject it; and Satan wishes to lead them far astray.'),
  ('en.sahih', 4, 61, 'And when it is said to them, "Come to what Allah has revealed and to the Messenger," you see the hypocrites turning away from you in aversion.'),
  ('en.sahih', 4, 62, 'So how [will it be] when disaster strikes them because of what their hands have put forth and then they come to you swearing by Allah, "We intended nothing but good conduct and accommodation."'),
  ('en.sahih', 4, 63, 'Those are the ones of whom Allah knows what is in their hearts, so turn away from them but admonish them and speak to them a far-reaching word.'),
  ('en.sahih', 4, 64, 'And We did not send any messenger except to be obeyed by permission of Allah. And if, when they wronged themselves, they had come to you, [O Muhammad], and asked forgiveness of Allah and the Messenger had asked forgiveness for them, they would have found Allah Accepting of repentance and Merciful.'),
  ('en.sahih', 4, 65, 'But no, by your Lord, they will not [truly] believe until they make you, [O Muhammad], judge concerning that over which they dispute among themselves and then find within themselves no discomfort from what you have judged and submit in [full, willing] submission.'),
  ('en.sahih', 4, 66, 'And if We had decreed upon them, "Kill yourselves" or "Leave your homes," they would not have done it, except for a few of them. But if they had done what they were instructed, it would have been better for them and a firmer position [for them in faith].'),
  ('en.sahih', 4, 67, 'And then We would have given them from Us a great reward.'),
  ('en.sahih', 4, 68, 'And We would have guided them to a straight path.'),
  ('en.sahih', 4, 69, 'And whoever obeys Allah and the Messenger - those will be with the ones upon whom Allah has bestowed favor of the prophets, the steadfast affirmers of truth, the martyrs and the righteous. And excellent are those as companions.'),
  ('en.sahih', 4, 70, 'That is the bounty from Allah, and sufficient is Allah as Knower.'),
  ('en.sahih', 4, 71, 'O you who have believed, take your precaution and [either] go forth in companies or go forth all together.'),
  ('en.sahih', 4, 72, 'And indeed, there is among you he who lingers behind; and if disaster strikes you, he says, "Allah has favored me in that I was not present with them."'),
  ('en.sahih', 4, 73, 'But if bounty comes to you from Allah, he will surely say, as if there had never been between you and him any affection. "Oh, I wish I had been with them so I could have attained a great attainment."'),
  ('en.sahih', 4, 74, 'So let those fight in the cause of Allah who sell the life of this world for the Hereafter. And he who fights in the cause of Allah and is killed or achieves victory - We will bestow upon him a great reward.'),
  ('en.sahih', 4, 75, 'And what is [the matter] with you that you fight not in the cause of Allah and [for] the oppressed among men, women, and children who say, "Our Lord, take us out of this city of oppressive people and appoint for us from Yourself a protector and appoint for us from Yourself a helper?"'),
  ('en.sahih', 4, 76, 'Those who believe fight in the cause of Allah, and those who disbelieve fight in the cause of Taghut. So fight against the allies of Satan. Indeed, the plot of Satan has ever been weak.'),
  ('en.sahih', 4, 77, 'Have you not seen those who were told, "Restrain your hands [from fighting] and establish prayer and give zakah"? But then when fighting was ordained for them, at once a party of them feared men as they fear Allah or with [even] greater fear. They said, "Our Lord, why have You decreed upon us fighting? If only You had postponed [it for] us for a short time." Say, The enjoyment of this world is little, and the Hereafter is better for he who fears Allah. And injustice will not be done to you, [even] as much as a thread [inside a date seed]."'),
  ('en.sahih', 4, 78, 'Wherever you may be, death will overtake you, even if you should be within towers of lofty construction. But if good comes to them, they say, "This is from Allah "; and if evil befalls them, they say, "This is from you." Say, "All [things] are from Allah." So what is [the matter] with those people that they can hardly understand any statement?'),
  ('en.sahih', 4, 79, 'What comes to you of good is from Allah, but what comes to you of evil, [O man], is from yourself. And We have sent you, [O Muhammad], to the people as a messenger, and sufficient is Allah as Witness.'),
  ('en.sahih', 4, 80, 'He who obeys the Messenger has obeyed Allah; but those who turn away - We have not sent you over them as a guardian.'),
  ('en.sahih', 4, 81, 'And they say, "[We pledge] obedience." But when they leave you, a group of them spend the night determining to do other than what you say. But Allah records what they plan by night. So leave them alone and rely upon Allah. And sufficient is Allah as Disposer of affairs.'),
  ('en.sahih', 4, 82, 'Then do they not reflect upon the Qur\'an? If it had been from [any] other than Allah, they would have found within it much contradiction.'),
  ('en.sahih', 4, 83, 'And when there comes to them information about [public] security or fear, they spread it around. But if they had referred it back to the Messenger or to those of authority among them, then the ones who [can] draw correct conclusions from it would have known about it. And if not for the favor of Allah upon you and His mercy, you would have followed Satan, except for a few.'),
  ('en.sahih', 4, 84, 'So fight, [O Muhammad], in the cause of Allah; you are not held responsible except for yourself. And encourage the believers [to join you] that perhaps Allah will restrain the [military] might of those who disbelieve. And Allah is greater in might and stronger in [exemplary] punishment.'),
  ('en.sahih', 4, 85, 'Whoever intercedes for a good cause will have a reward therefrom; and whoever intercedes for an evil cause will have a burden therefrom. And ever is Allah, over all things, a Keeper.'),
  ('en.sahih', 4, 86, 'And when you are greeted with a greeting, greet [in return] with one better than it or [at least] return it [in a like manner]. Indeed, Allah is ever, over all things, an Accountant.'),
  ('en.sahih', 4, 87, 'Allah - there is no deity except Him. He will surely assemble you for [account on] the Day of Resurrection, about which there is no doubt. And who is more truthful than Allah in statement.'),
  ('en.sahih', 4, 88, 'What is [the matter] with you [that you are] two groups concerning the hypocrites, while Allah has made them fall back [into error and disbelief] for what they earned. Do you wish to guide those whom Allah has sent astray? And he whom Allah sends astray - never will you find for him a way [of guidance].'),
  ('en.sahih', 4, 89, 'They wish you would disbelieve as they disbelieved so you would be alike. So do not take from among them allies until they emigrate for the cause of Allah. But if they turn away, then seize them and kill them wherever you find them and take not from among them any ally or helper.'),
  ('en.sahih', 4, 90, 'Except for those who take refuge with a people between yourselves and whom is a treaty or those who come to you, their hearts strained at [the prospect of] fighting you or fighting their own people. And if Allah had willed, He could have given them power over you, and they would have fought you. So if they remove themselves from you and do not fight you and offer you peace, then Allah has not made for you a cause [for fighting] against them.'),
  ('en.sahih', 4, 91, 'You will find others who wish to obtain security from you and [to] obtain security from their people. Every time they are returned to [the influence of] disbelief, they fall back into it. So if they do not withdraw from you or offer you peace or restrain their hands, then seize them and kill them wherever you overtake them. And those - We have made for you against them a clear authorization.'),
  ('en.sahih', 4, 92, 'And never is it for a believer to kill a believer except by mistake. And whoever kills a believer by mistake - then the freeing of a believing slave and a compensation payment presented to the deceased\'s family [is required] unless they give [up their right as] charity. But if the deceased was from a people at war with you and he was a believer - then [only] the freeing of a believing slave; and if he was from a people with whom you have a treaty - then a compensation payment presented to his family and the freeing of a believing slave. And whoever does not find [one or cannot afford to buy one] - then [instead], a fast for two months consecutively, [seeking] acceptance of repentance from Allah. And Allah is ever Knowing and Wise.'),
  ('en.sahih', 4, 93, 'But whoever kills a believer intentionally - his recompense is Hell, wherein he will abide eternally, and Allah has become angry with him and has cursed him and has prepared for him a great punishment.'),
  ('en.sahih', 4, 94, 'O you who have believed, when you go forth [to fight] in the cause of Allah, investigate; and do not say to one who gives you [a greeting of] peace "You are not a believer," aspiring for the goods of worldly life; for with Allah are many acquisitions. You [yourselves] were like that before; then Allah conferred His favor upon you, so investigate. Indeed Allah is ever, with what you do, Acquainted.'),
  ('en.sahih', 4, 95, 'Not equal are those believers remaining [at home] - other than the disabled - and the mujahideen, [who strive and fight] in the cause of Allah with their wealth and their lives. Allah has preferred the mujahideen through their wealth and their lives over those who remain [behind], by degrees. And to both Allah has promised the best [reward]. But Allah has preferred the mujahideen over those who remain [behind] with a great reward -'),
  ('en.sahih', 4, 96, 'Degrees [of high position] from Him and forgiveness and mercy. And Allah is ever Forgiving and Merciful.'),
  ('en.sahih', 4, 97, 'Indeed, those whom the angels take [in death] while wronging themselves - [the angels] will say, "In what [condition] were you?" They will say, "We were oppressed in the land." The angels will say, "Was not the earth of Allah spacious [enough] for you to emigrate therein?" For those, their refuge is Hell - and evil it is as a destination.'),
  ('en.sahih', 4, 98, 'Except for the oppressed among men, women and children who cannot devise a plan nor are they directed to a way -'),
  ('en.sahih', 4, 99, 'For those it is expected that Allah will pardon them, and Allah is ever Pardoning and Forgiving.'),
  ('en.sahih', 4, 100, 'And whoever emigrates for the cause of Allah will find on the earth many [alternative] locations and abundance. And whoever leaves his home as an emigrant to Allah and His Messenger and then death overtakes him - his reward has already become incumbent upon Allah. And Allah is ever Forgiving and Merciful.'),
  ('en.sahih', 4, 101, 'And when you travel throughout the land, there is no blame upon you for shortening the prayer, [especially] if you fear that those who disbelieve may disrupt [or attack] you. Indeed, the disbelievers are ever to you a clear enemy.'),
  ('en.sahih', 4, 102, 'And when you are among them and lead them in prayer, let a group of them stand [in prayer] with you and let them carry their arms. And when they have prostrated, let them be [in position] behind you and have the other group come forward which has not [yet] prayed and let them pray with you, taking precaution and carrying their arms. Those who disbelieve wish that you would neglect your weapons and your baggage so they could come down upon you in one [single] attack. But there is no blame upon you, if you are troubled by rain or are ill, for putting down your arms, but take precaution. Indeed, Allah has prepared for the disbelievers a humiliating punishment.'),
  ('en.sahih', 4, 103, 'And when you have completed the prayer, remember Allah standing, sitting, or [lying] on your sides. But when you become secure, re-establish [regular] prayer. Indeed, prayer has been decreed upon the believers a decree of specified times.'),
  ('en.sahih', 4, 104, 'And do not weaken in pursuit of the enemy. If you should be suffering - so are they suffering as you are suffering, but you expect from Allah that which they expect not. And Allah is ever Knowing and Wise.'),
  ('en.sahih', 4, 105, 'Indeed, We have revealed to you, [O Muhammad], the Book in truth so you may judge between the people by that which Allah has shown you. And do not be for the deceitful an advocate.'),
  ('en.sahih', 4, 106, 'And seek forgiveness of Allah. Indeed, Allah is ever Forgiving and Merciful.'),
  ('en.sahih', 4, 107, 'And do not argue on behalf of those who deceive themselves. Indeed, Allah loves not one who is a habitually sinful deceiver.'),
  ('en.sahih', 4, 108, 'They conceal [their evil intentions and deeds] from the people, but they cannot conceal [them] from Allah, and He is with them [in His knowledge] when they spend the night in such as He does not accept of speech. And ever is Allah, of what they do, encompassing.'),
  ('en.sahih', 4, 109, 'Here you are - those who argue on their behalf in [this] worldly life - but who will argue with Allah for them on the Day of Resurrection, or who will [then] be their representative?'),
  ('en.sahih', 4, 110, 'And whoever does a wrong or wrongs himself but then seeks forgiveness of Allah will find Allah Forgiving and Merciful.'),
  ('en.sahih', 4, 111, 'And whoever commits a sin only earns it against himself. And Allah is ever Knowing and Wise.'),
  ('en.sahih', 4, 112, 'But whoever earns an offense or a sin and then blames it on an innocent [person] has taken upon himself a slander and manifest sin.'),
  ('en.sahih', 4, 113, 'And if it was not for the favor of Allah upon you, [O Muhammad], and His mercy, a group of them would have determined to mislead you. But they do not mislead except themselves, and they will not harm you at all. And Allah has revealed to you the Book and wisdom and has taught you that which you did not know. And ever has the favor of Allah upon you been great.'),
  ('en.sahih', 4, 114, 'No good is there in much of their private conversation, except for those who enjoin charity or that which is right or conciliation between people. And whoever does that seeking means to the approval of Allah - then We are going to give him a great reward.'),
  ('en.sahih', 4, 115, 'And whoever opposes the Messenger after guidance has become clear to him and follows other than the way of the believers - We will give him what he has taken and drive him into Hell, and evil it is as a destination.'),
  ('en.sahih', 4, 116, 'Indeed, Allah does not forgive association with Him, but He forgives what is less than that for whom He wills. And he who associates others with Allah has certainly gone far astray.'),
  ('en.sahih', 4, 117, 'They call upon instead of Him none but female [deities], and they [actually] call upon none but a rebellious Satan.'),
  ('en.sahih', 4, 118, 'Whom Allah has cursed. For he had said, "I will surely take from among Your servants a specific portion.'),
  ('en.sahih', 4, 119, 'And I will mislead them, and I will arouse in them [sinful] desires, and I will command them so they will slit the ears of cattle, and I will command them so they will change the creation of Allah." And whoever takes Satan as an ally instead of Allah has certainly sustained a clear loss.'),
  ('en.sahih', 4, 120, 'Satan promises them and arouses desire in them. But Satan does not promise them except delusion.'),
  ('en.sahih', 4, 121, 'The refuge of those will be Hell, and they will not find from it an escape.'),
  ('en.sahih', 4, 122, 'But the ones who believe and do righteous deeds - We will admit them to gardens beneath which rivers flow, wherein they will abide forever. [It is] the promise of Allah, [which is] truth, and who is more truthful than Allah in statement.'),
  ('en.sahih', 4, 123, 'Paradise is not [obtained] by your wishful thinking nor by that of the People of the Scripture. Whoever does a wrong will be recompensed for it, and he will not find besides Allah a protector or a helper.'),
  ('en.sahih', 4, 124, 'And whoever does righteous deeds, whether male or female, while being a believer - those will enter Paradise and will not be wronged, [even as much as] the speck on a date seed.'),
  ('en.sahih', 4, 125, 'And who is better in religion than one who submits himself to Allah while being a doer of good and follows the religion of Abraham, inclining toward truth? And Allah took Abraham as an intimate friend.'),
  ('en.sahih', 4, 126, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah, of all things, encompassing.'),
  ('en.sahih', 4, 127, 'And they request from you, [O Muhammad], a [legal] ruling concerning women. Say, "Allah gives you a ruling about them and [about] what has been recited to you in the Book concerning the orphan girls to whom you do not give what is decreed for them - and [yet] you desire to marry them - and concerning the oppressed among children and that you maintain for orphans [their rights] in justice." And whatever you do of good - indeed, Allah is ever Knowing of it.'),
  ('en.sahih', 4, 128, 'And if a woman fears from her husband contempt or evasion, there is no sin upon them if they make terms of settlement between them - and settlement is best. And present in [human] souls is stinginess. But if you do good and fear Allah - then indeed Allah is ever, with what you do, Acquainted.'),
  ('en.sahih', 4, 129, 'And you will never be able to be equal [in feeling] between wives, even if you should strive [to do so]. So do not incline completely [toward one] and leave another hanging. And if you amend [your affairs] and fear Allah - then indeed, Allah is ever Forgiving and Merciful.'),
  ('en.sahih', 4, 130, 'But if they separate [by divorce], Allah will enrich each [of them] from His abundance. And ever is Allah Encompassing and Wise.'),
  ('en.sahih', 4, 131, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And We have instructed those who were given the Scripture before you and yourselves to fear Allah. But if you disbelieve - then to Allah belongs whatever is in the heavens and whatever is on the earth. And ever is Allah Free of need and Praiseworthy.'),
  ('en.sahih', 4, 132, 'And to Allah belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs.'),
  ('en.sahih', 4, 133, 'If He wills, He can do away with you, O people, and bring others [in your place]. And ever is Allah competent to do that.'),
  ('en.sahih', 4, 134, 'Whoever desires the reward of this world - then with Allah is the reward of this world and the Hereafter. And ever is Allah Hearing and Seeing.'),
  ('en.sahih', 4, 135, 'O you who have believed, be persistently standing firm in justice, witnesses for Allah, even if it be against yourselves or parents and relatives. Whether one is rich or poor, Allah is more worthy of both. So follow not [personal] inclination, lest you not be just. And if you distort [your testimony] or refuse [to give it], then indeed Allah is ever, with what you do, Acquainted.'),
  ('en.sahih', 4, 136, 'O you who have believed, believe in Allah and His Messenger and the Book that He sent down upon His Messenger and the Scripture which He sent down before. And whoever disbelieves in Allah, His angels, His books, His messengers, and the Last Day has certainly gone far astray.'),
  ('en.sahih', 4, 137, 'Indeed, those who have believed then disbelieved, then believed, then disbelieved, and then increased in disbelief - never will Allah forgive them, nor will He guide them to a way.'),
  ('en.sahih', 4, 138, 'Give tidings to the hypocrites that there is for them a painful punishment -'),
  ('en.sahih', 4, 139, 'Those who take disbelievers as allies instead of the believers. Do they seek with them honor [through power]? But indeed, honor belongs to Allah entirely.'),
  ('en.sahih', 4, 140, 'And it has already come down to you in the Book that when you hear the verses of Allah [recited], they are denied [by them] and ridiculed; so do not sit with them until they enter into another conversation. Indeed, you would then be like them. Indeed Allah will gather the hypocrites and disbelievers in Hell all together -'),
  ('en.sahih', 4, 141, 'Those who wait [and watch] you. Then if you gain a victory from Allah, they say, "Were we not with you?" But if the disbelievers have a success, they say [to them], "Did we not gain the advantage over you, but we protected you from the believers?" Allah will judge between [all of] you on the Day of Resurrection, and never will Allah give the disbelievers over the believers a way [to overcome them].'),
  ('en.sahih', 4, 142, 'Indeed, the hypocrites [think to] deceive Allah, but He is deceiving them. And when they stand for prayer, they stand lazily, showing [themselves to] the people and not remembering Allah except a little,'),
  ('en.sahih', 4, 143, 'Wavering between them, [belonging] neither to the believers nor to the disbelievers. And whoever Allah leaves astray - never will you find for him a way.'),
  ('en.sahih', 4, 144, 'O you who have believed, do not take the disbelievers as allies instead of the believers. Do you wish to give Allah against yourselves a clear case?'),
  ('en.sahih', 4, 145, 'Indeed, the hypocrites will be in the lowest depths of the Fire - and never will you find for them a helper -'),
  ('en.sahih', 4, 146, 'Except for those who repent, correct themselves, hold fast to Allah, and are sincere in their religion for Allah, for those will be with the believers. And Allah is going to give the believers a great reward.'),
  ('en.sahih', 4, 147, 'What would Allah do with your punishment if you are grateful and believe? And ever is Allah Appreciative and Knowing.'),
  ('en.sahih', 4, 148, 'Allah does not like the public mention of evil except by one who has been wronged. And ever is Allah Hearing and Knowing.'),
  ('en.sahih', 4, 149, 'If [instead] you show [some] good or conceal it or pardon an offense - indeed, Allah is ever Pardoning and Competent.'),
  ('en.sahih', 4, 150, 'Indeed, those who disbelieve in Allah and His messengers and wish to discriminate between Allah and His messengers and say, "We believe in some and disbelieve in others," and wish to adopt a way in between -'),
  ('en.sahih', 4, 151, 'Those are the disbelievers, truly. And We have prepared for the disbelievers a humiliating punishment.'),
  ('en.sahih', 4, 152, 'But they who believe in Allah and His messengers and do not discriminate between any of them - to those He is going to give their rewards. And ever is Allah Forgiving and Merciful.'),
  ('en.sahih', 4, 153, 'The People of the Scripture ask you to bring down to them a book from the heaven. But they had asked of Moses [even] greater than that and said, "Show us Allah outright," so the thunderbolt struck them for their wrongdoing. Then they took the calf [for worship] after clear evidences had come to them, and We pardoned that. And We gave Moses a clear authority.'),
  ('en.sahih', 4, 154, 'And We raised over them the mount for [refusal of] their covenant; and We said to them, "Enter the gate bowing humbly", and We said to them, "Do not transgress on the sabbath", and We took from them a solemn covenant.'),
  ('en.sahih', 4, 155, 'And [We cursed them] for their breaking of the covenant and their disbelief in the signs of Allah and their killing of the prophets without right and their saying, "Our hearts are wrapped". Rather, Allah has sealed them because of their disbelief, so they believe not, except for a few.'),
  ('en.sahih', 4, 156, 'And [We cursed them] for their disbelief and their saying against Mary a great slander,'),
  ('en.sahih', 4, 157, 'And [for] their saying, "Indeed, we have killed the Messiah, Jesus, the son of Mary, the messenger of Allah." And they did not kill him, nor did they crucify him; but [another] was made to resemble him to them. And indeed, those who differ over it are in doubt about it. They have no knowledge of it except the following of assumption. And they did not kill him, for certain.'),
  ('en.sahih', 4, 158, 'Rather, Allah raised him to Himself. And ever is Allah Exalted in Might and Wise.'),
  ('en.sahih', 4, 159, 'And there is none from the People of the Scripture but that he will surely believe in Jesus before his death. And on the Day of Resurrection he will be against them a witness.'),
  ('en.sahih', 4, 160, 'For wrongdoing on the part of the Jews, We made unlawful for them [certain] good foods which had been lawful to them, and for their averting from the way of Allah many [people],'),
  ('en.sahih', 4, 161, 'And [for] their taking of usury while they had been forbidden from it, and their consuming of the people\'s wealth unjustly. And we have prepared for the disbelievers among them a painful punishment.'),
  ('en.sahih', 4, 162, 'But those firm in knowledge among them and the believers believe in what has been revealed to you, [O Muhammad], and what was revealed before you. And the establishers of prayer [especially] and the givers of zakah and the believers in Allah and the Last Day - those We will give a great reward.'),
  ('en.sahih', 4, 163, 'Indeed, We have revealed to you, [O Muhammad], as We revealed to Noah and the prophets after him. And we revealed to Abraham, Ishmael, Isaac, Jacob, the Descendants, Jesus, Job, Jonah, Aaron, and Solomon, and to David We gave the book [of Psalms].'),
  ('en.sahih', 4, 164, 'And [We sent] messengers about whom We have related [their stories] to you before and messengers about whom We have not related to you. And Allah spoke to Moses with [direct] speech.'),
  ('en.sahih', 4, 165, '[We sent] messengers as bringers of good tidings and warners so that mankind will have no argument against Allah after the messengers. And ever is Allah Exalted in Might and Wise.'),
  ('en.sahih', 4, 166, 'But Allah bears witness to that which He has revealed to you. He has sent it down with His knowledge, and the angels bear witness [as well]. And sufficient is Allah as Witness.'),
  ('en.sahih', 4, 167, 'Indeed, those who disbelieve and avert [people] from the way of Allah have certainly gone far astray.'),
  ('en.sahih', 4, 168, 'Indeed, those who disbelieve and commit wrong [or injustice] - never will Allah forgive them, nor will He guide them to a path.'),
  ('en.sahih', 4, 169, 'Except the path of Hell; they will abide therein forever. And that, for Allah, is [always] easy.'),
  ('en.sahih', 4, 170, 'O Mankind, the Messenger has come to you with the truth from your Lord, so believe; it is better for you. But if you disbelieve - then indeed, to Allah belongs whatever is in the heavens and earth. And ever is Allah Knowing and Wise.'),
  ('en.sahih', 4, 171, 'O People of the Scripture, do not commit excess in your religion or say about Allah except the truth. The Messiah, Jesus, the son of Mary, was but a messenger of Allah and His word which He directed to Mary and a soul [created at a command] from Him. So believe in Allah and His messengers. And do not say, "Three"; desist - it is better for you. Indeed, Allah is but one God. Exalted is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs.'),
  ('en.sahih', 4, 172, 'Never would the Messiah disdain to be a servant of Allah, nor would the angels near [to Him]. And whoever disdains His worship and is arrogant - He will gather them to Himself all together.'),
  ('en.sahih', 4, 173, 'And as for those who believed and did righteous deeds, He will give them in full their rewards and grant them extra from His bounty. But as for those who disdained and were arrogant, He will punish them with a painful punishment, and they will not find for themselves besides Allah any protector or helper.'),
  ('en.sahih', 4, 174, 'O mankind, there has come to you a conclusive proof from your Lord, and We have sent down to you a clear light.'),
  ('en.sahih', 4, 175, 'So those who believe in Allah and hold fast to Him - He will admit them to mercy from Himself and bounty and guide them to Himself on a straight path.'),
  ('en.sahih', 4, 176, 'They request from you a [legal] ruling. Say, "Allah gives you a ruling concerning one having neither descendants nor ascendants [as heirs]." If a man dies, leaving no child but [only] a sister, she will have half of what he left. And he inherits from her if she [dies and] has no child. But if there are two sisters [or more], they will have two-thirds of what he left. If there are both brothers and sisters, the male will have the share of two females. Allah makes clear to you [His law], lest you go astray. And Allah is Knowing of all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 4, 1, 'হে মানব সমাজ! তোমরা তোমাদের পালনকর্তাকে ভয় কর, যিনি তোমাদেরকে এক ব্যক্তি থেকে সৃষ্টি করেছেন এবং যিনি তার থেকে তার সঙ্গীনীকে সৃষ্টি করেছেন; আর বিস্তার করেছেন তাদের দু’জন থেকে অগণিত পুরুষ ও নারী। আর আল্লাহকে ভয় কর, যাঁর নামে তোমরা একে অপরের নিকট যাচঞ্ঝা করে থাক এবং আত্নীয় জ্ঞাতিদের ব্যাপারে সতর্কতা অবলম্বন কর। নিশ্চয় আল্লাহ তোমাদের ব্যাপারে সচেতন রয়েছেন।'),
  ('bn.bengali', 4, 2, 'এতীমদেরকে তাদের সম্পদ বুঝিয়ে দাও। খারাপ মালামালের সাথে ভালো মালামালের অদল-বদল করো না। আর তাদের ধন-সম্পদ নিজেদের ধন-সম্পদের সাথে সংমিশ্রিত করে তা গ্রাস করো না। নিশ্চয় এটা বড়ই মন্দ কাজ।'),
  ('bn.bengali', 4, 3, 'আর যদি তোমরা ভয় কর যে, এতীম মেয়েদের হক যথাথভাবে পুরণ করতে পারবে না, তবে সেসব মেয়েদের মধ্যে থেকে যাদের ভাল লাগে তাদের বিয়ে করে নাও দুই, তিন, কিংবা চারটি পর্যন্ত। আর যদি এরূপ আশঙ্কা কর যে, তাদের মধ্যে ন্যায় সঙ্গত আচরণ বজায় রাখতে পারবে না, তবে, একটিই অথবা তোমাদের অধিকারভুক্ত দাসীদেরকে; এতেই পক্ষপাতিত্বে জড়িত না হওয়ার অধিকতর সম্ভাবনা।'),
  ('bn.bengali', 4, 4, 'আর তোমরা স্ত্রীদেরকে তাদের মোহর দিয়ে দাও খুশীমনে। তারা যদি খুশী হয়ে তা থেকে অংশ ছেড়ে দেয়, তবে তা তোমরা স্বাচ্ছন্দ্যে ভোগ কর।'),
  ('bn.bengali', 4, 5, 'আর যে সম্পদকে আল্লাহ তোমাদের জীবন-যাত্রার অবলম্বন করেছেন, তা অর্বাচীনদের হাতে তুলে দিও না। বরং তা থেকে তাদেরকে খাওয়াও, পরাও এবং তাদেরকে সান্তনার বানী শোনাও।'),
  ('bn.bengali', 4, 6, 'আর এতীমদের প্রতি বিশেষভাবে নজর রাখবে, যে পর্যন্ত না তারা বিয়ের বয়সে পৌঁছে। যদি তাদের মধ্যে বুদ্ধি-বিবেচনার উন্মেষ আঁচ করতে পার, তবে তাদের সম্পদ তাদের হাতে অর্পন করতে পার। এতীমের মাল প্রয়োজনাতিরিক্ত খরচ করো না বা তারা বড় হয়ে যাবে মনে করে তাড়াতাড়ি খেয়ে ফেলো না। যারা স্বচ্ছল তারা অবশ্যই এতীমের মাল খরচ করা থেকে বিরত থাকবে। আর যে অভাবগ্রস্ত সে সঙ্গত পরিমাণ খেতে পারে। যখন তাদের হাতে তাদের সম্পদ প্রত্যার্পণ কর, তখন সাক্ষী রাখবে। অবশ্য আল্লাহই হিসাব নেয়ার ব্যাপারে যথেষ্ট।'),
  ('bn.bengali', 4, 7, 'পিতা-মাতা ও আত্নীয়-স্বজনদের পরিত্যক্ত সম্পত্তিতে পুরুষদেরও অংশ আছে এবং পিতা-মাতা ও আত্নীয়-স্বজনদের পরিত্যক্ত সম্পত্তিতে নারীদেরও অংশ আছে; অল্প হোক কিংবা বেশী। এ অংশ নির্ধারিত।'),
  ('bn.bengali', 4, 8, 'সম্পতি বন্টনের সময় যখন আত্নীয়-স্বজন, এতীম ও মিসকীন উপস্থিত হয়, তখন তা থেকে তাদের কিছু খাইয়ে দাও এবং তাদের সাথে কিছু সদালাপ করো।'),
  ('bn.bengali', 4, 9, 'তাদের ভয় করা উচিত, যারা নিজেদের পশ্চাতে দুর্বল অক্ষম সন্তান-সন্ততি ছেড়ে গেলে তাদের জন্যে তারাও আশঙ্কা করে; সুতরাং তারা যেন আল্লাহকে ভয় করে এবং সংগত কথা বলে।'),
  ('bn.bengali', 4, 10, 'যারা এতীমদের অর্থ-সম্পদ অন্যায়ভাবে খায়, তারা নিজেদের পেটে আগুনই ভর্তি করেছে এবং সত্ত্বরই তারা অগ্নিতে প্রবেশ করবে।'),
  ('bn.bengali', 4, 11, 'আল্লাহ তোমাদেরকে তোমাদের সন্তানদের সম্পর্কে আদেশ করেনঃ একজন পুরুষের অংশ দু?জন নারীর অংশের সমান। অতঃপর যদি শুধু নারীই হয় দু\' এর অধিক, তবে তাদের জন্যে ঐ মালের তিন ভাগের দুই ভাগ যা ত্যাগ করে মরে এবং যদি একজনই হয়, তবে তার জন্যে অর্ধেক। মৃতের পিতা-মাতার মধ্য থেকে প্রত্যেকের জন্যে ত্যাজ্য সম্পত্তির ছয় ভাগের এক ভাগ, যদি মৃতের পুত্র থাকে। যদি পুত্র না থাকে এবং পিতা-মাতাই ওয়ারিস হয়, তবে মাতা পাবে তিন ভাগের এক ভাগ। অতঃপর যদি মৃতের কয়েকজন ভাই থাকে, তবে তার মাতা পাবে ছয় ভাগের এক ভাগ ওছিয়্যতের পর, যা করে মরেছে কিংবা ঋণ পরিশোধের পর। তোমাদের পিতা ও পুত্রের মধ্যে কে তোমাদের জন্যে অধিক উপকারী তোমরা জান না। এটা আল্লাহ কতৃক নির্ধারিত অংশ নিশ্চয় আল্লাহ সর্বজ্ঞ, রহস্যবিদ।'),
  ('bn.bengali', 4, 12, 'আর, তোমাদের হবে অর্ধেক সম্পত্তি, যা ছেড়ে যায় তোমাদের স্ত্রীরা যদি তাদের কোন সন্তান না থাকে। যদি তাদের সন্তান থাকে, তবে তোমাদের হবে এক-চতুর্থাংশ ঐ সম্পত্তির, যা তারা ছেড়ে যায়; ওছিয়্যতের পর, যা তারা করে এবং ঋণ পরিশোধের পর। স্ত্রীদের জন্যে এক-চতুর্থাংশ হবে ঐ সম্পত্তির, যা তোমরা ছেড়ে যাও যদি তোমাদের কোন সন্তান না থাকে। আর যদি তোমাদের সন্তান থাকে, তবে তাদের জন্যে হবে ঐ সম্পত্তির আট ভাগের এক ভাগ, যা তোমরা ছেড়ে যাও ওছিয়্যতের পর, যা তোমরা কর এবং ঋণ পরিশোধের পর। যে পুরুষের, ত্যাজ্য সম্পত্তি, তার যদি পিতা-পুত্র কিংবা স্ত্রী না থাকে এবং এই মৃতের এক ভাই কিংবা এক বোন থাকে, তবে উভয়ের প্রত্যেকে ছয়-ভাগের এক পাবে। আর যদি ততোধিক থাকে, তবে তারা এক তৃতীয়াংশ অংশীদার হবে ওছিয়্যতের পর, যা করা হয় অথবা ঋণের পর এমতাবস্থায় যে, অপরের ক্ষতি না করে। এ বিধান আল্লাহর। আল্লাহ সর্বজ্ঞ, সহনশীল।'),
  ('bn.bengali', 4, 13, 'এগুলো আল্লাহর নির্ধারিত সীমা। যে কেউ আল্লাহ ও রসূলের আদেশমত চলে, তিনি তাকে জান্নাত সমূহে প্রবেশ করাবেন, যেগুলোর তলদেশ দিয়ে স্রোতস্বিনী প্রবাহিত হবে। তারা সেখানে চিরকাল থাকবে। এ হল বিরাট সাফল্য।'),
  ('bn.bengali', 4, 14, 'যে কেউ আল্লাহ ও রসূলের অবাধ্যতা করে এবং তার সীমা অতিক্রম করে তিনি তাকে আগুনে প্রবেশ করাবেন। সে সেখানে চিরকাল থাকবে। তার জন্যে রয়েছে অপমানজনক শাস্তি।'),
  ('bn.bengali', 4, 15, 'আর তোমাদের নারীদের মধ্যে যারা ব্যভিচারিণী তাদের বিরুদ্ধে তোমাদের মধ্য থেকে চার জন পুরুষকে সাক্ষী হিসেবে তলব কর। অতঃপর যদি তারা সাক্ষ্য প্রদান করে তবে সংশ্লিষ্টদেরকে গৃহে আবদ্ধ রাখ, যে পর্যন্ত মৃত্যু তাদেরকে তুলে না নেয় অথবা আল্লাহ তাদের জন্য অন্য কোন পথ নির্দেশ না করেন।'),
  ('bn.bengali', 4, 16, 'তোমাদের মধ্য থেকে যে দু’জন সেই কুকর্মে লিপ্ত হয়, তাদেরকে শাস্তি প্রদান কর। অতঃপর যদি উভয়ে তওবা করে এবং নিজেদের সংশোধন করে, তবে তাদের থেকে হাত গুটিয়ে নাও। নিশ্চয় আল্লাহ তওবা কবুলকারী, দয়ালু।'),
  ('bn.bengali', 4, 17, 'অবশ্যই আল্লাহ তাদের তওবা কবুল করবেন, যারা ভূলবশতঃ মন্দ কাজ করে, অতঃপর অনতিবিলম্বে তওবা করে; এরাই হল সেসব লোক যাদেরকে আল্লাহ ক্ষমা করে দেন। আল্লাহ মহাজ্ঞানী, রহস্যবিদ।'),
  ('bn.bengali', 4, 18, 'আর এমন লোকদের জন্য কোন ক্ষমা নেই, যারা মন্দ কাজ করতেই থাকে, এমন কি যখন তাদের কারো মাথার উপর মৃত্যু উপস্থিত হয়, তখন বলতে থাকেঃ আমি এখন তওবা করছি। আর তওবা নেই তাদের জন্য, যারা কুফরী অবস্থায় মৃত্যুবরণ করে। আমি তাদের জন্য যন্ত্রণাদায়ক শাস্তি প্রস্তুত করে রেখেছি।'),
  ('bn.bengali', 4, 19, 'হে ঈমাণদারগণ! বলপূর্বক নারীদেরকে উত্তরাধিকারে গ্রহন করা তোমাদের জন্যে হালাল নয় এবং তাদেরকে আটক রেখো না যাতে তোমরা তাদেরকে যা প্রদান করেছ তার কিয়দংশ নিয়ে নাও; কিন্তু তারা যদি কোন প্রকাশ্য অশ্লীলতা করে! নারীদের সাথে সদ্ভাবে জীবন-যাপন কর। অতঃপর যদি তাদেরকে অপছন্দ কর, তবে হয়ত তোমরা এমন এক জিনিসকে অপছন্দ করছ, যাতে আল্লাহ, অনেক কল্যাণ রেখেছেন।'),
  ('bn.bengali', 4, 20, 'যদি তোমরা এক স্ত্রীর স্থলে অন্য স্ত্রী পরিবর্তন করতে ইচ্ছা কর এবং তাদের একজনকে প্রচুর ধন-সম্পদ প্রদান করে থাক, তবে তা থেকে কিছুই ফেরত গ্রহণ করো না। তোমরা কি তা অন্যায়ভাবে ও প্রকাশ্য গোনাহর মাধ্যমে গ্রহণ করবে?'),
  ('bn.bengali', 4, 21, 'তোমরা কিরূপে তা গ্রহণ করতে পার, অথচ তোমাদের একজন অন্য জনের কাছে গমন এবং নারীরা তোমাদের কাছে থেকে সুদৃঢ় অঙ্গীকার গ্রহণ করেছে।'),
  ('bn.bengali', 4, 22, 'যে নারীকে তোমাদের পিতা-পিতামহ বিবাহ করেছে তোমরা তাদের বিবাহ করো না। কিন্তু যা বিগত হয়ে গেছে। এটা অশ্লীল, গযবের কাজ এবং নিকৃষ্ট আচরণ।'),
  ('bn.bengali', 4, 23, 'তোমাদের জন্যে হারাম করা হয়েছে তোমাদের মাতা, তোমাদের কন্যা, তোমাদের বোন, তোমাদের ফুফু, তোমাদের খালা, ভ্রাতৃকণ্যা; ভগিনীকণ্যা তোমাদের সে মাতা, যারা তোমাদেরকে স্তন্যপান করিয়েছে, তোমাদের দুধ-বোন, তোমাদের স্ত্রীদের মাতা, তোমরা যাদের সাথে সহবাস করেছ সে স্ত্রীদের কন্যা যারা তোমাদের লালন-পালনে আছে। যদি তাদের সাথে সহবাস না করে থাক, তবে এ বিবাহে তোমাদের কোন গোনাহ নেই। তোমাদের ঔরসজাত পুত্রদের স্ত্রী এবং দুই বোনকে একত্রে বিবাহ করা; কিন্তু যা অতীত হয়ে গেছে। নিশ্চয় আল্লাহ ক্ষমাকরী, দয়ালু।'),
  ('bn.bengali', 4, 24, 'এবং নারীদের মধ্যে তাদের ছাড়া সকল সধবা স্ত্রীলোক তোমাদের জন্যে নিষিদ্ধ; তোমাদের দক্ষিণ হস্ত যাদের মালিক হয়ে যায়-এটা তোমাদের জন্য আল্লাহর হুকুম। এদেরকে ছাড়া তোমাদের জন্যে সব নারী হালাল করা হয়েছে, শর্ত এই যে, তোমরা তাদেরকে স্বীয় অর্থের বিনিময়ে তলব করবে বিবাহ বন্ধনে আবদ্ধ করার জন্য-ব্যভিচারের জন্য নয়। অনন্তর তাদের মধ্যে যাকে তোমরা ভোগ করবে, তাকে তার নির্ধারিত হক দান কর। তোমাদের কোন গোনাহ হবে না যদি নির্ধারণের পর তোমরা পরস্পরে সম্মত হও। নিশ্চয় আল্লাহ সুবিজ্ঞ, রহস্যবিদ।'),
  ('bn.bengali', 4, 25, 'আর তোমাদের মধ্যে যে ব্যক্তি স্বাধীন মুসলমান নারীকে বিয়ে করার সামর্থ্য রাখে না, সে তোমাদের অধিকারভুক্ত মুসলিম ক্রীতদাসীদেরকে বিয়ে করবে। আল্লাহ তোমাদের ঈমান সম্পর্কে ভালোভাবে জ্ঞাত রয়েছেন। তোমরা পরস্পর এক, অতএব, তাদেরকে তাদের মালিকের অনুমতিক্রমে বিয়ে কর এবং নিয়ম অনুযায়ী তাদেরকে মোহরানা প্রদান কর এমতাবস্থায় যে, তারা বিবাহ বন্ধনে আবদ্ধ হবে-ব্যভিচারিণী কিংবা উপ-পতি গ্রহণকারিণী হবে না। অতঃপর যখন তারা বিবাহ বন্ধনে এসে যায়, তখন যদি কোন অশ্লীল কাজ করে, তবে তাদেরকে স্বাধীন নারীদের অর্ধেক শাস্তি ভোগ করতে হবে। এ ব্যবস্থা তাদের জন্যে, তোমাদের মধ্যে যারা ব্যভিচারে লিপ্ত হওয়ার ব্যাপারে ভয় করে। আর যদি সবর কর, তবে তা তোমাদের জন্যে উত্তম। আল্লাহ ক্ষমাশীল, করুণাময়।'),
  ('bn.bengali', 4, 26, 'আল্লাহ তোমাদের জন্যে সব কিছু পরিষ্কার বর্ণনা করে দিতে চান, তোমাদের পূর্ববর্তীদের পথ প্রদর্শন করতে চান। এবং তোমাদেরকে ক্ষমা করতে চান, আল্লাহ মহাজ্ঞানী রহস্যবিদ।'),
  ('bn.bengali', 4, 27, 'আল্লাহ তোমাদের প্রতি ক্ষমাশীল হতে চান, এবং যারা কামনা-বাসনার অনুসারী, তারা চায় যে, তোমরা পথ থেকে অনেক দূরে বিচ্যুত হয়ে পড়।'),
  ('bn.bengali', 4, 28, 'আল্লাহ তোমাদের বোঝা হালকা করতে চান। মানুষ দুর্বল সৃজিত হয়েছে।'),
  ('bn.bengali', 4, 29, 'হে ঈমানদারগণ! তোমরা একে অপরের সম্পদ অন্যায়ভাবে গ্রাস করো না। কেবলমাত্র তোমাদের পরস্পরের সম্মতিক্রমে যে ব্যবসা করা হয় তা বৈধ। আর তোমরা নিজেদের কাউকে হত্যা করো না। নিঃসন্দেহে আল্লাহ তা’আলা তোমাদের প্রতি দয়ালু।'),
  ('bn.bengali', 4, 30, 'আর যে কেউ সীমালঙ্ঘন কিংবা জুলুমের বশবর্তী হয়ে এরূপ করবে, তাকে খুব শীঘ্রই আগুনে নিক্ষেপ করা হবে। এটা আল্লাহর পক্ষে খুবই সহজসাধ্য।'),
  ('bn.bengali', 4, 31, 'যেগুলো সম্পর্কে তোমাদের নিষেধ করা হয়েছে যদি তোমরা সেসব বড় গোনাহ গুলো থেকে বেঁচে থাকতে পার। তবে আমি তোমাদের ক্রটি-বিচ্যুতিগুলো ক্ষমা করে দেব এবং সম্মান জনক স্থানে তোমাদের প্রবেশ করার।'),
  ('bn.bengali', 4, 32, 'আর তোমরা আকাঙ্ক্ষা করো না এমন সব বিষয়ে যাতে আল্লাহ তা’আলা তোমাদের একের উপর অপরের শ্রেষ্ঠত্ব দান করেছেন। পুরুষ যা অর্জন করে সেটা তার অংশ এবং নারী যা অর্জন করে সেটা তার অংশ। আর আল্লাহর কাছে তাঁর অনুগ্রহ প্রার্থনা কর। নিঃসন্দেহে আল্লাহ তা’আলা সর্ব বিষয়ে জ্ঞাত।'),
  ('bn.bengali', 4, 33, 'পিতা-মাতা এবং নিকটাত্নীয়গণ যা ত্যাগ করে যান সেসবের জন্যই আমি উত্তরাধিকারী নির্ধারণ করে দিয়েছি। আর যাদের সাথে তোমরা অঙ্গীকারাবদ্ধ হয়েছ তাদের প্রাপ্য দিয়ে দাও। আল্লাহ তা’আলা নিঃসন্দেহে সব কিছুই প্রত্যক্ষ করেন।'),
  ('bn.bengali', 4, 34, 'পুরুষেরা নারীদের উপর কৃর্তত্বশীল এ জন্য যে, আল্লাহ একের উপর অন্যের বৈশিষ্ট্য দান করেছেন এবং এ জন্য যে, তারা তাদের অর্থ ব্যয় করে। সে মতে নেককার স্ত্রীলোকগণ হয় অনুগতা এবং আল্লাহ যা হেফাযতযোগ্য করে দিয়েছেন লোক চক্ষুর অন্তরালেও তার হেফাযত করে। আর যাদের মধ্যে অবাধ্যতার আশঙ্কা কর তাদের সদুপদেশ দাও, তাদের শয্যা ত্যাগ কর এবং প্রহার কর। যদি তাতে তারা বাধ্য হয়ে যায়, তবে আর তাদের জন্য অন্য কোন পথ অনুসন্ধান করো না। নিশ্চয় আল্লাহ সবার উপর শ্রেষ্ঠ।'),
  ('bn.bengali', 4, 35, 'যদি তাদের মধ্যে সম্পর্কচ্ছেদ হওয়ার মত পরিস্থিতিরই আশঙ্কা কর, তবে স্বামীর পরিবার থেকে একজন এবং স্ত্রীর পরিবার থেকে একজন সালিস নিযুক্ত করবে। তারা উভয়ের মীমাংসা চাইলে আল্লাহ সর্বজ্ঞ, সবকিছু অবহিত।'),
  ('bn.bengali', 4, 36, 'আর উপাসনা কর আল্লাহর, শরীক করো না তাঁর সাথে অপর কাউকে। পিতা-মাতার সাথে সৎ ও সদয় ব্যবহার কর এবং নিকটাত্নীয়, এতীম-মিসকীন, প্রতিবেশী, অসহায় মুসাফির এবং নিজের দাস-দাসীর প্রতিও। নিশ্চয়ই আল্লাহ পছন্দ করেন না দাম্ভিক-গর্বিতজনকে।'),
  ('bn.bengali', 4, 37, 'যারা নিজেরাও কার্পন্য করে এবং অন্যকেও কৃপণতা শিক্ষা দেয় আর গোপন করে সে সব বিষয় যা আল্লাহ তা’আলা তাদেরকে দান করেছেন স্বীয় অনুগ্রহে-বস্তুতঃ তৈরী করে রেখেছি কাফেরদের জন্য অপমান জনক আযাব।'),
  ('bn.bengali', 4, 38, 'আর সে সমস্ত লোক যারা ব্যয় করে স্বীয় ধন-সম্পদ লোক-দেখানোর উদ্দেশে এবং যারা আল্লাহর উপর ঈমান আনে না, ঈমান আনে না কেয়ামত দিবসের প্রতি এবং শয়তান যার সাথী হয় সে হল নিকৃষ্টতর সাথী।'),
  ('bn.bengali', 4, 39, 'আর কিই বা ক্ষতি হত তাদের যদি তারা ঈমান আনত আল্লাহর উপর কেয়ামত দিবসের উপর এবং যদি ব্যয় করত আল্লাহ প্রদত্ত রিযিক থেকে! অথচ আল্লাহ, তাদের ব্যাপারে যথার্থভাবেই অবগত।'),
  ('bn.bengali', 4, 40, 'নিশ্চয়ই আল্লাহ কারো প্রাপ্য হক বিন্দু-বিসর্গও রাখেন না; আর যদি তা সৎকর্ম হয়, তবে তাকে দ্বিগুণ করে দেন এবং নিজের পক্ষ থেকে বিপুল সওয়াব দান করেন।'),
  ('bn.bengali', 4, 41, 'আর তখন কি অবস্থা দাঁড়াবে, যখন আমি ডেকে আনব প্রতিটি উম্মতের মধ্য থেকে অবস্থা বর্ণনাকারী এবং আপনাকে ডাকব তাদের উপর অবস্থা বর্ণনাকারীরূপে।'),
  ('bn.bengali', 4, 42, 'সেদিন কামনা করবে সে সমস্ত লোক, যারা কাফের হয়েছিল এবং রসূলের নাফরমানী করেছিল, যেন যমীনের সাথে মিশে যায়। কিন্তু গোপন করতে পারবে না আল্লাহর নিকট কোন বিষয়।'),
  ('bn.bengali', 4, 43, 'হে ঈমাণদারগণ! তোমরা যখন নেশাগ্রস্ত থাক, তখন নামাযের ধারে-কাছেও যেওনা, যতক্ষণ না বুঝতে সক্ষম হও যা কিছু তোমরা বলছ, আর (নামাযের কাছে যেও না) ফরয গোসলের আবস্থায়ও যতক্ষণ না গোসল করে নাও। কিন্তু মুসাফির অবস্থার কথা স্বতন্ত্র আর যদি তোমরা অসুস্থ হয়ে থাক কিংবা সফরে থাক অথবা তোমাদের মধ্য থেকে কেউ যদি প্রস্রাব-পায়খানা থেকে এসে থাকে কিংবা নারী গমন করে থাকে, কিন্তু পরে যদি পানিপ্রাপ্তি সম্ভব না হয়, তবে পাক-পবিত্র মাটির দ্বারা তায়াম্মুম করে নাও-তাতে মুখমন্ডল ও হাতকে ঘষে নাও। নিশ্চয়ই আল্লাহ তা’আলা ক্ষমাশীল।'),
  ('bn.bengali', 4, 44, 'তুমি কি ওদের দেখনি, যারা কিতাবের কিছু অংশ প্রাপ্ত হয়েছে, (অথচ) তারা পথভ্রষ্টতা খরিদ করে এবং কামনা করে, যাতে তোমরাও আল্লাহর পথ থেকে বিভ্রান্ত হয়ে যাও।'),
  ('bn.bengali', 4, 45, 'অথচ আল্লাহ তোমাদের শত্রুদেরকে যথার্থই জানেন। আর অভিভাবক হিসাবে আল্লাহই যথেষ্ট এবং সাহায্যকারী হিসাবেও আল্লাহই যথেষ্ট।'),
  ('bn.bengali', 4, 46, 'কোন কোন ইহুদী তার লক্ষ্য থেকে কথার মোড় ঘুড়িয়ে নেয় এবং বলে, আমরা শুনেছি কিন্তু অমান্য করছি। তারা আরো বলে, শোন, না শোনার মত। মুখ বাঁকিয়ে দ্বীনের প্রতি তাচ্ছিল্য প্রদর্শনের উদ্দেশে বলে, রায়েনা’ (আমাদের রাখাল)। অথচ যদি তারা বলত যে, আমরা শুনেছি ও মান্য করেছি এবং (যদি বলত, ) শোন এবং আমাদের প্রতি লক্ষ্য রাখ, তবে তাই ছিল তাদের জন্য উত্তম আর সেটাই ছিল যথার্থ ও সঠিক। কিন্তু আল্লাহ তাদের প্রতি অভিসম্পাত করেছেন তাদের কুফরীর দরুন। অতএব, তারা ঈমান আনছে না, কিন্তু অতি অল্পসংখ্যক।'),
  ('bn.bengali', 4, 47, 'হে আসমানী গ্রন্থের অধিকারীবৃন্দ! যা কিছু আমি অবতীর্ণ করেছি তার উপর বিশ্বাস স্থাপন কর, যা সে গ্রন্থের সত্যায়ন করে এবং যা তোমাদের নিকট রয়েছে পূর্ব থেকে। (বিশ্বাস স্থাপন কর) এমন হওয়ার আগেই যে, আমি মুছে দেব অনেক চেহারাকে এবং অতঃপর সেগুলোকে ঘুরিয়ে দেব পশ্চাৎ দিকে কিংবা অভিসম্পাত করব তাদের প্রতি যেমন করে অভিসম্পাত করেছি আছহাবে-সাবতের উপর। আর আল্লাহর নির্দেশ অবশ্যই কার্যকর হবে।'),
  ('bn.bengali', 4, 48, 'নিঃসন্দেহে আল্লাহ তাকে ক্ষমা করেন না, যে লোক তাঁর সাথে শরীক করে। তিনি ক্ষমা করেন এর নিম্ন পর্যায়ের পাপ, যার জন্য তিনি ইচ্ছা করেন। আর যে লোক অংশীদার সাব্যস্ত করল আল্লাহর সাথে, সে যেন অপবাদ আরোপ করল।'),
  ('bn.bengali', 4, 49, 'তুমি কি তাদেকে দেখনি, যারা নিজেদেরকে পূত-পবিত্র বলে থাকে অথচ পবিত্র করেন আল্লাহ যাকে ইচ্ছা তাকেই? বস্তুতঃ তাদের উপর সুতা পরিমাণ অন্যায়ও হবে না।'),
  ('bn.bengali', 4, 50, 'লক্ষ্য কর, কেমন করে তারা আল্লাহর প্রতি মিথ্যা অপবাদ আরোপ করে, অথচ এই প্রকাশ্য পাপই যথেষ্ট।'),
  ('bn.bengali', 4, 51, 'তুমি কি তাদেরকে দেখনি, যারা কিতাবের কিছু অংশ প্রাপ্ত হয়েছে, যারা মান্য করে প্রতিমা ও শয়তানকে এবং কাফেরদেরকে বলে যে, এরা মুসলমানদের তুলনায় অধিকতর সরল সঠিক পথে রয়েছে।'),
  ('bn.bengali', 4, 52, 'এরা হলো সে সমস্ত লোক, যাদের উপর লা’নত করেছেন আল্লাহ তা’আলা স্বয়ং। বস্তুতঃ আল্লাহ যার উপর লা’নত করেন তুমি তার কোন সাহায্যকারী খুঁজে পাবে না।'),
  ('bn.bengali', 4, 53, 'তাদের কাছে কি রাজ্যের কোন অংশ আছে? তাহলে যে এরা কাউকেও একটি তিল পরিমাণও দেবে না।'),
  ('bn.bengali', 4, 54, 'নাকি যাকিছু আল্লাহ তাদেরকে স্বীয় অনুগ্রহে দান করেছেন সে বিষয়ের জন্য মানুষকে হিংসা করে। অবশ্যই আমি ইব্রাহীমের বংশধরদেরকে কিতাব ও হেকমত দান করেছিলাম আর তাদেরকে দান করেছিলাম বিশাল রাজ্য।'),
  ('bn.bengali', 4, 55, 'অতঃপর তাদের কেউ তাকে মান্য করেছে আবার কেউ তার কাছ থেকে দূরে সরে রয়েছে। বস্তুতঃ (তাদের জন্য) দোযখের শিখায়িত আগুনই যথেষ্ট।'),
  ('bn.bengali', 4, 56, 'এতে সন্দেহ নেই যে, আমার নিদর্শন সমুহের প্রতি যেসব লোক অস্বীকৃতি জ্ঞাপন করবে, আমি তাদেরকে আগুনে নিক্ষেপ করব। তাদের চামড়াগুলো যখন জ্বলে-পুড়ে যাবে, তখন আবার আমি তা পালটে দেব অন্য চামড়া দিয়ে, যাতে তারা আযাব আস্বাদন করতে থাকে। নিশ্চয়ই আল্লাহ মহাপরাক্রমশালী, হেকমতের অধিকারী।'),
  ('bn.bengali', 4, 57, 'আর যারা ঈমান এনেছে এবং সৎকর্ম করেছে, অবশ্য আমি প্রবিষ্ট করাব তাদেরকে জান্নাতে, যার তলদেশে প্রবাহিত রয়েছে নহর সমূহ। সেখানে তারা থাকবে অনন্তকাল। সেখানে তাদের জন্য থাকবে পরিষ্কার-পরিচ্ছন্ন স্ত্রীগণ। তাদেরকে আমি প্রবিষ্ট করব ঘন ছায়া নীড়ে।'),
  ('bn.bengali', 4, 58, 'নিশ্চয়ই আল্লাহ তোমাদিগকে নির্দেশ দেন যে, তোমরা যেন প্রাপ্য আমানতসমূহ প্রাপকদের নিকট পৌছে দাও। আর যখন তোমরা মানুষের কোন বিচার-মীমাংসা করতে আরম্ভ কর, তখন মীমাংসা কর ন্যায় ভিত্তিক। আল্লাহ তোমাদিগকে সদুপদেশ দান করেন। নিশ্চয়ই আল্লাহ শ্রবণকারী, দর্শনকারী।'),
  ('bn.bengali', 4, 59, 'হে ঈমানদারগণ! আল্লাহর নির্দেশ মান্য কর, নির্দেশ মান্য কর রসূলের এবং তোমাদের মধ্যে যারা বিচারক তাদের। তারপর যদি তোমরা কোন বিষয়ে বিবাদে প্রবৃত্ত হয়ে পড়, তাহলে তা আল্লাহ ও তাঁর রসূলের প্রতি প্রত্যর্পণ কর-যদি তোমরা আল্লাহ ও কেয়ামত দিবসের উপর বিশ্বাসী হয়ে থাক। আর এটাই কল্যাণকর এবং পরিণতির দিক দিয়ে উত্তম।'),
  ('bn.bengali', 4, 60, 'আপনি কি তাদেরকে দেখেননি, যারা দাবী করে যে, যা আপনার প্রতি অবর্তীর্ণ হয়েছে আমরা সে বিষয়ের উপর ঈমান এনেছি এবং আপনার পূর্বে যা অবর্তীণ হয়েছে। তারা বিরোধীয় বিষয়কে শয়তানের দিকে নিয়ে যেতে চায়, অথচ তাদের প্রতি নির্দেশ হয়েছে, যাতে তারা ওকে মান্য না করে। পক্ষান্তরে শয়তান তাদেরকে প্রতারিত করে পথভ্রষ্ট করে ফেলতে চায়।'),
  ('bn.bengali', 4, 61, 'আর যখন আপনি তাদেরকে বলবেন, আল্লাহর নির্দেশের দিকে এসো-যা তিনি রসূলের প্রতি নাযিল করেছেন, তখন আপনি মুনাফেকদিগকে দেখবেন, ওরা আপনার কাছ থেকে সম্পূর্ণ ভাবে সরে যাচ্ছে।'),
  ('bn.bengali', 4, 62, 'এমতাবস্থায় যদি তাদের কৃতকর্মের দরুন বিপদ আরোপিত হয়, তবে তাতে কি হল! অতঃপর তারা আপনার কাছে আল্লাহর নামে কসম খেয়ে খেয়ে ফিরে আসবে যে, মঙ্গল ও সম্প্রীতি ছাড়া আমাদের অন্য কোন উদ্দেশ্য ছিল না।'),
  ('bn.bengali', 4, 63, 'এরা হলো সে সমস্ত লোক, যাদের মনের গোপন বিষয় সম্পর্কেও আল্লাহ তা’আলা অবগত। অতএব, আপনি ওদেরকে উপেক্ষা করুন এবং ওদেরকে সদুপদেশ দিয়ে এমন কোন কথা বলুন যা তাদের জন্য কল্যাণকর।'),
  ('bn.bengali', 4, 64, 'বস্তুতঃ আমি একমাত্র এই উদ্দেশ্যেই রসূল প্রেরণ করেছি, যাতে আল্লাহর নির্দেশানুযায়ী তাঁদের আদেশ-নিষেধ মান্য করা হয়। আর সেসব লোক যখন নিজেদের অনিষ্ট সাধন করেছিল, তখন যদি আপনার কাছে আসত অতঃপর আল্লাহর নিকট ক্ষমা প্রার্থনা করত এবং রসূলও যদি তাদেরকে ক্ষমা করিয়ে দিতেন। অবশ্যই তারা আল্লাহকে ক্ষমাকারী, মেহেরবানরূপে পেত।'),
  ('bn.bengali', 4, 65, 'অতএব, তোমার পালনকর্তার কসম, সে লোক ঈমানদার হবে না, যতক্ষণ না তাদের মধ্যে সৃষ্ট বিবাদের ব্যাপারে তোমাকে ন্যায়বিচারক বলে মনে না করে। অতঃপর তোমার মীমাংসার ব্যাপারে নিজের মনে কোন রকম সংকীর্ণতা পাবে না এবং তা হূষ্টচিত্তে কবুল করে নেবে।'),
  ('bn.bengali', 4, 66, 'আর যদি আমি তাদের নির্দেশ দিতাম যে, নিজেদের প্রাণ ধ্বংস করে দাও কিংবা নিজেদের নগরী ছেড়ে বেরিয়ে যাও, তবে তারা তা করত না; অবশ্য তাদের মধ্যে অল্প কয়েকজন। যদি তারা তাই করে যা তাদের উপদেশ দেয়া হয়, তবে তা অবশ্যই তাদের জন্য উত্তম এং তাদেরকে নিজের ধর্মের উপর সুদৃঢ় রাখার জন্য তা উত্তম হবে।'),
  ('bn.bengali', 4, 67, 'আর তখন অবশ্যই আমি তাদেরকে নিজের পক্ষ থেকে মহান সওয়াব দেব।'),
  ('bn.bengali', 4, 68, 'আর তাদেরকে সরল পথে পরিচালিত করব।'),
  ('bn.bengali', 4, 69, 'আর যে কেউ আল্লাহর হুকুম এবং তাঁর রসূলের হুকুম মান্য করবে, তাহলে যাঁদের প্রতি আল্লাহ নেয়ামত দান করেছেন, সে তাঁদের সঙ্গী হবে। তাঁরা হলেন নবী, ছিদ্দীক, শহীদ ও সৎকর্মশীল ব্যক্তিবর্গ। আর তাদের সান্নিধ্যই হল উত্তম।'),
  ('bn.bengali', 4, 70, 'এটা হল আল্লাহ-প্রদত্ত মহত্ত্ব। আর আল্লাহ যথেষ্ট পরিজ্ঞাত।'),
  ('bn.bengali', 4, 71, 'হে ঈমানদারগণ! নিজেদের অস্ত্র তুলে নাও এবং পৃথক পৃথক সৈন্যদলে কিংবা সমবেতভাবে বেরিয়ে পড়।'),
  ('bn.bengali', 4, 72, 'আর তোমাদের মধ্যে এমনও কেউ কেউ রয়েছে, যারা অবশ্য বিলম্ব করবে এবং তোমাদের উপর কোন বিপদ উপস্থিত হলে বলবে, আল্লাহ আমার প্রতি অনুগ্রহ করেছেন যে, আমি তাদের সাথে যাইনি।'),
  ('bn.bengali', 4, 73, 'পক্ষান্তরে তোমাদের প্রতি আল্লাহর পক্ষ থেকে কোন অনুগ্রহ আসলে তারা এমন ভাবে বলতে শুরু করবে যেন তোমাদের মধ্যে এবং তাদের মধ্যে কোন মিত্রতাই ছিল না। (বলবে) হায়, আমি যদি তাদের সাথে থাকতাম, তাহলে আমি ও যে সফলতা লাভ করতাম।'),
  ('bn.bengali', 4, 74, 'কাজেই আল্লাহর কাছে যারা পার্থিব জীবনকে আখেরাতের পরিবর্তে বিক্রি করে দেয় তাদের জেহাদ করাই কর্তব্য। বস্তুতঃ যারা আল্লাহর রাহে লড়াই করে এবং অতঃপর মৃত্যুবরণ করে কিংবা বিজয় অর্জন করে, আমি তাদেরকে মহাপুণ্য দান করব।'),
  ('bn.bengali', 4, 75, 'আর তোমাদের কি হল যে, তেমারা আল্লাহর রাহে লড়াই করছ না দুর্বল সেই পুরুষ, নারী ও শিশুদের পক্ষে, যারা বলে, হে আমাদের পালনকর্তা! আমাদিগকে এই জনপদ থেকে নিষ্কৃতি দান কর; এখানকার অধিবাসীরা যে, অত্যাচারী! আর তোমার পক্ষ থেকে আমাদের জন্য পক্ষালম্বনকারী নির্ধারণ করে দাও এবং তোমার পক্ষ থেকে আমাদের জন্য সাহায্যকারী নির্ধারণ করে দাও।'),
  ('bn.bengali', 4, 76, 'যারা ঈমানদার তারা যে, জেহাদ করে আল্লাহর রাহেই। পক্ষান্তরে যারা কাফের তারা লড়াই করে শয়তানের পক্ষে সুতরাং তোমরা জেহাদ করতে থাক শয়তানের পক্ষালম্বনকারীদের বিরুদ্ধে, (দেখবে) শয়তানের চক্রান্ত একান্তই দুর্বল।'),
  ('bn.bengali', 4, 77, 'তুমি কি সেসব লোককে দেখনি, যাদেরকে নির্দেশ দেয়া হয়েছিল যে, তোমরা নিজেদের হাতকে সংযত রাখ, নামায কায়েম কর এবং যাকাত দিতে থাক? অতঃপর যখন তাদের প্রতি জেহাদের নির্দেশ দেয়া হল, তৎক্ষণাৎ তাদের মধ্যে একদল লোক মানুষকে ভয় করতে আরম্ভ করল, যেমন করে ভয় করা হয় আল্লাহকে। এমন কি তার চেয়েও অধিক ভয়। আর বলতে লাগল, হায় পালনকর্তা, কেন আমাদের উপর যুদ্ধ ফরজ করলে! আমাদেরকে কেন আরও কিছুকাল অবকাশ দান করলে না। ( হে রসূল) তাদেরকে বলে দিন, পার্থিব ফায়দা সীমিত। আর আখেরাত পরহেযগারদের জন্য উত্তম। আর তোমাদের অধিকার একটি সূতা পরিমান ও খর্ব করা হবে না।'),
  ('bn.bengali', 4, 78, 'তোমরা যেখানেই থাক না কেন; মৃত্যু কিন্তু তোমাদেরকে পাকড়াও করবেই। যদি তোমরা সুদৃঢ় দূর্গের ভেতরেও অবস্থান কর, তবুও। বস্তুতঃ তাদের কোন কল্যাণ সাধিত হলে তারা বলে যে, এটা সাধিত হয়েছে আল্লাহর পক্ষ থেকে। আর যদি তাদের কোন অকল্যাণ হয়, তবে বলে, এটা হয়েছে তোমার পক্ষ থেকে, বলে দাও, এসবই আল্লাহর পক্ষ থেকে। পক্ষান্তরে তাদের পরিণতি কি হবে, যারা কখনও কোন কথা বুঝতে চেষ্টা করে না।'),
  ('bn.bengali', 4, 79, 'আপনার যে কল্যাণ হয়, তা হয় আল্লাহর পক্ষ থেকে আর আপনার যে অকল্যাণ হয়, সেটা হয় আপনার নিজের কারণে। আর আমি আপনাকে পাঠিয়েছি মানুষের প্রতি আমার পয়গামের বাহক হিসাবে। আর আল্লাহ সব বিষয়েই যথেষ্ট-সববিষয়ই তাঁর সম্মুখে উপস্থিত।'),
  ('bn.bengali', 4, 80, 'যে লোক রসূলের হুকুম মান্য করবে সে আল্লাহরই হুকুম মান্য করল। আর যে লোক বিমুখতা অবলম্বন করল, আমি আপনাকে (হে মুহাম্মদ), তাদের জন্য রক্ষণাবেক্ষণকারী নিযুক্ত করে পাঠাইনি।'),
  ('bn.bengali', 4, 81, 'আর তারা বলে, আপনার আনুগত্য করি। অতঃপর আপনার নিকট থেকে বেরিয়ে গেলেই তাদের মধ্য থেকে কেউ কেউ পরামর্শ করে রাতের বেলায় সে কথার পরিপন্থী যা তারা আপনার সাথে বলেছিল। আর আল্লাহ লিখে নেন, সে সব পরামর্শ যা তারা করে থাকে। সুতরাং আপনি তাদের ব্যাপারে নিস্পৃহতা অবলম্বন করুন এবং ভরসা করুন আল্লাহর উপর, আল্লাহ হলেন যথেষ্ট ও কার্যসম্পাদনকারী।'),
  ('bn.bengali', 4, 82, 'এরা কি লক্ষ্য করে না কোরআনের প্রতি? পক্ষান্তরে এটা যদি আল্লাহ ব্যতীত অপর কারও পক্ষ থেকে হত, তবে এতো অবশ্যই বহু বৈপরিত্য দেখতে পেত।'),
  ('bn.bengali', 4, 83, 'আর যখন তাদের কছে পৌঁছে কোন সংবাদ শান্তি-সংক্রান্ত কিংবা ভয়ের, তখন তারা সেগুলোকে রটিয়ে দেয়। আর যদি সেগুলো পৌঁছে দিত রসূল পর্যন্ত কিংবা তাদের শাসকদের পর্যন্ত, তখন অনুসন্ধান করে দেখা যেত সেসব বিষয়, যা তাতে রয়েছে অনুসন্ধান করার মত। বস্তুতঃ আল্লাহর অনুগ্রহ ও করুণা যদি তোমাদের উপর বিদ্যমান না থাকত তবে তোমাদের অল্প কতিপয় লোক ব্যতীত সবাই শয়তানের অনুসরণ করতে শুরু করত!'),
  ('bn.bengali', 4, 84, 'আল্লাহর রাহে যুদ্ধ করতে থাকুন, আপনি নিজের সত্তা ব্যতীত অন্য কোন বিষয়ের যিম্মাদার নন! আর আপনি মুসলমানদেরকে উৎসাহিত করতে থাকুন। শীঘ্রই আল্লাহ কাফেরদের শক্তি-সামর্থ খর্ব করে দেবেন। আর আল্লাহ শক্তি-সামর্থের দিক দিয়ে অত্যন্ত কঠোর এবং কঠিন শাস্তিদাতা।'),
  ('bn.bengali', 4, 85, 'যে লোক সৎকাজের জন্য কোন সুপারিশ করবে, তা থেকে সেও একটি অংশ পাবে। আর যে লোক সুপারিশ করবে মন্দ কাজের জন্যে সে তার বোঝারও একটি অংশ পাবে। বস্তুতঃ আল্লাহ সর্ব বিষয়ে ক্ষমতাশীল।'),
  ('bn.bengali', 4, 86, 'আর তোমাদেরকে যদি কেউ দোয়া করে, তাহলে তোমরাও তার জন্য দোয়া কর; তারচেয়ে উত্তম দোয়া অথবা তারই মত ফিরিয়ে বল। নিশ্চয়ই আল্লাহ সর্ব বিষয়ে হিসাব-নিকাশ গ্রহণকারী।'),
  ('bn.bengali', 4, 87, 'আল্লাহ ব্যতীত আর কোনোই উপাস্য নেই। অবশ্যই তিনি তোমাদেরকে সমবেত করবেন কেয়ামতের দিন, এতে বিন্দুমাত্র সন্দেহ নেই। তাছাড়া আল্লাহর চাইতে বেশী সত্য কথা আর কার হবে!'),
  ('bn.bengali', 4, 88, 'অতঃপর তোমাদের কি হল যে, মুনাফিকদের সম্পর্কে তোমরা দু’দল হয়ে গেলে? অথচ আল্লাহ তা’আলা তাদেরকে ঘুরিয়ে দিয়েছেন তাদের মন্দ কাজের কারনে! তোমরা কি তাদেরকে পথ প্রদর্শন করতে চাও, যাদেরকে আল্লাহ পথভ্রষ্ট করেছেন? আল্লাহ যাকে পথভ্রান্ত করেন, তুমি তার জন্য কোন পথ পাবে না।'),
  ('bn.bengali', 4, 89, 'তারা চায় যে, তারা যেমন কাফের, তোমরাও তেমনি কাফের হয়ে যাও, যাতে তোমরা এবং তারা সব সমান হয়ে যাও। অতএব, তাদের মধ্যে কাউকে বন্ধুরূপে গ্রহণ করো না, যে পর্যন্ত না তারা আল্লাহর পথে হিজরত করে চলে আসে। অতঃপর যদি তারা বিমুখ হয়, তবে তাদেরকে পাকড়াও কর এবং যেখানে পাও হত্যা কর। তাদের মধ্যে কাউকে বন্ধুরূপে গ্রহণ করো না এবং সাহায্যকারী বানিও না।'),
  ('bn.bengali', 4, 90, 'কিন্তু যারা এমন সম্প্রদায়ের সাথে মিলিত হয় যে, তোমাদের মধ্যে ও তাদের মধ্যে চুক্তি আছে অথবা তোমাদের কাছে এভাবে আসে যে, তাদের অন্তর তোমাদের সাথে এবং স্বজাতির সাথেও যুদ্ধ করতে অনিচ্ছুক। যদি আল্লাহ ইচ্ছে করতেন, তবে তোমাদের উপর তাদেরকে প্রবল করে দিতেন। ফলে তারা অবশ্যই তোমাদের সাথে যুদ্ধ করত। অতঃপর যদি তারা তোমাদের থেকে পৃথক থাকে তোমাদের সাথে যুদ্ধ না করে এবং তোমাদের সাথে সন্ধি করে, তবে আল্লাহ তোমাদের কে তাদের বিরুদ্ধে কোন পথ দেননি।'),
  ('bn.bengali', 4, 91, 'এখন তুমি আরও এক সম্প্রদায়কে পাবে। তারা তোমাদের কাছেও স্বজাতির কাছেও এবং নির্বিঘ্ন হয়ে থাকতে চায়। যখন তাদেরকে ফ্যাসাদের প্রতি মনোনিবেশ করানো হয়, তখন তারা তাতে নিপতিত হয়, অতএব তারা যদি তোমাদের থেকে নিবৃত্ত না হয়, তোমাদের সাথে সন্ধি না রাখে এবং স্বীয় হস্তসমূহকে বিরত না রাখে, তবে তোমরা তাদেরকে পাকড়াও কর এবং যেখানে পাও হত্যা কর। আমি তাদের বিরুদ্ধে তোমাদেরকে প্রকাশ্য যুক্তি-প্রমাণ দান করেছি।'),
  ('bn.bengali', 4, 92, 'মুসলমানের কাজ নয় যে, মুসলমানকে হত্যা করে; কিন্তু ভুলক্রমে। যে ব্যক্তি মুসলমানকে ভূলক্রমে হত্যা করে, সে একজন মুসলমান ক্রীতদাস মুক্ত করবে এবং রক্ত বিনিময় সমর্পন করবে তার স্বজনদেরকে; কিন্তু যদি তারা ক্ষমা করে দেয়। অতঃপর যদি নিহত ব্যক্তি তোমাদের শত্রু সম্প্রদায়ের অন্তর্গত হয়, তবে মুসলমান ক্রীতদাস মুক্ত করবে এবং যদি সে তোমাদের সাথে চুক্তিবদ্ধ কোন সম্প্রদায়ের অন্তর্গত হয়, তবে রক্ত বিনিময় সমর্পণ করবে তার স্বজনদেরকে এবং একজন মুসলমান ক্রীতদাস মুক্ত করবে। অতঃপর যে ব্যক্তি না পায়, সে আল্লাহর কাছ থেকে গোনাহ মাফ করানোর জন্যে উপর্যুপুরি দুই মাস রোযা রাখবে। আল্লাহ, মহাজ্ঞানী, প্রজ্ঞাময়।'),
  ('bn.bengali', 4, 93, 'যে ব্যক্তি স্বেচ্ছাক্রমে মুসলমানকে হত্যা করে, তার শাস্তি জাহান্নাম, তাতেই সে চিরকাল থাকবে। আল্লাহ তার প্রতি ক্রুদ্ধ হয়েছেন, তাকে অভিসম্পাত করেছেন এবং তার জন্যে ভীষণ শাস্তি প্রস্তুত রেখেছেন।'),
  ('bn.bengali', 4, 94, 'হে ঈমানদারগণ! তোমরা যখন আল্লাহর পথে সফর কর, তখন যাচাই করে নিও এবং যে, তোমাদেরকে সালাম করে তাকে বলো না যে, তুমি মুসলমান নও। তোমরা পার্থিব জীবনের সম্পদ অন্বেষণ কর, বস্তুতঃ আল্লাহর কাছে অনেক সম্পদ রয়েছে। তোমরা ও তো এমনি ছিলে ইতিপূর্বে; অতঃপর আল্লাহ তোমাদের প্রতি অনুগ্রহ করেছেন। অতএব, এখন অনুসন্ধান করে নিও। নিশ্চয় আল্লাহ তোমাদের কাজ কর্মের খবর রাখেন।'),
  ('bn.bengali', 4, 95, 'গৃহে উপবিষ্ট মুসলমান-যাদের কোন সঙ্গত ওযর নেই এবং ঐ মুসলমান যারা জান ও মাল দ্বারা আল্লাহর পথে জেহাদ করে,-সমান নয়। যারা জান ও মাল দ্বারা জেহাদ করে, আল্লাহ তাদের পদমর্যাদা বাড়িয়ে দিয়েছেন গৃহে উপবিষ্টদের তুলনায় এবং প্রত্যেকের সাথেই আল্লাহ কল্যাণের ওয়াদা করেছেন। আল্লাহ মুজাহেদীনকে উপবিষ্টদের উপর মহান প্রতিদানে শ্রেষ্ঠ করেছেন।'),
  ('bn.bengali', 4, 96, 'এগুলো তাঁর পক্ষ থেকে পদমর্যাদা, ক্ষমা ও করুণা; আল্লাহ ক্ষমাশীল ও করুণাময়।'),
  ('bn.bengali', 4, 97, 'যারা নিজের অনিষ্ট করে, ফেরেশতারা তাদের প্রাণ হরণ করে বলে, তোমরা কি অবস্থায় ছিলে? তারা বলেঃ এ ভূখন্ডে আমরা অসহায় ছিলাম। ফেরেশতারা বলেঃ আল্লাহর পৃথিবী কি প্রশস্ত ছিল না যে, তোমরা দেশত্যাগ করে সেখানে চলে যেতে? অতএব, এদের বাসস্থান হল জাহান্নাম এবং তা অত্যন্ত মন্দ স্থান।'),
  ('bn.bengali', 4, 98, 'কিন্তু পুরুষ, নারী ও শিশুদের মধ্যে যারা অসহায়, তারা কোন উপায় করতে পারে না এবং পথও জানে না।'),
  ('bn.bengali', 4, 99, 'অতএব, আশা করা যায়, আল্লাহ তাদেরকে ক্ষমা করবেন। আল্লাহ মার্জনাকারী, ক্ষমাশীল।'),
  ('bn.bengali', 4, 100, 'যে কেউ আল্লাহর পথে দেশত্যাগ করে, সে এর বিনিময়ে অনেক স্থান ও সচ্ছলতা প্রাপ্ত হবে। যে কেউ নিজ গৃহ থেকে বের হয় আল্লাহ ও রসূলের প্রতি হিজরত করার উদ্দেশে, অতঃপর মৃত্যুমুখে পতিত হয়, তবে তার সওয়াব আল্লাহর কাছে অবধারিত হয়ে যায়। আল্লাহ ক্ষমাশীল, করুণাময়।'),
  ('bn.bengali', 4, 101, 'যখন তোমরা কোন দেশ সফর কর, তখন নামাযে কিছুটা হ্রাস করলে তোমাদের কোন গোনাহ নেই, যদি তোমরা আশঙ্কা কর যে, কাফেররা তোমাদেরকে উত্ত্যক্ত করবে। নিশ্চয় কাফেররা তোমাদের প্রকাশ্য শত্রু।'),
  ('bn.bengali', 4, 102, 'যখন আপনি তাদের মধ্যে থাকেন, অতঃপর নামাযে দাঁড়ান, তখন যেন একদল দাঁড়ায় আপনার সাথে এবং তারা যেন স্বীয় অস্ত্র সাথে নেয়। অতঃপর যখন তারা সেজদা সম্পন্ন করে, তখন আপনার কাছ থেকে যেন সরে যায় এবং অন্য দল যেন আসে, যারা নামায পড়েনি। অতঃপর তারা যেন আপনার সাথে নামায পড়ে এবং আত্মরক্ষার হাতিয়ার সাথে নেয়। কাফেররা চায় যে, তোমরা কোন রূপে অসতর্ক থাক, যাতে তারা একযোগে তোমাদেরকে আক্রমণ করে বসে। যদি বৃষ্টির কারণে তোমাদের কষ্ট হয় অথবা তোমরা অসুস্থ হও তবে স্বীয় অস্ত্র পরিত্যাগ করায় তোমাদের কোন গোনাহ নেই এবং সাথে নিয়ে নাও তোমাদের আত্নরক্ষার অস্ত্র। নিশ্চয় আল্লাহ কাফেরদের জন্যে অপমানকর শাস্তি প্রস্তুত করে রেখেছেন।'),
  ('bn.bengali', 4, 103, 'অতঃপর যখন তোমরা নামায সম্পন্ন কর, তখন দন্ডায়মান, উপবিষ্ট ও শায়িত অবস্থায় আল্লাহকে স্মরণ কর। অতঃপর যখন বিপদমুক্ত হয়ে যাও, তখন নামায ঠিক করে পড়। নিশ্চয় নামায মুসলমানদের উপর ফরয নির্দিষ্ট সময়ের মধ্যে।'),
  ('bn.bengali', 4, 104, 'তাদের পশ্চাদ্ধাবনে শৈথিল্য করো না। যদি তোমরা আঘাত প্রাপ্ত, তবে তারাও তো তোমাদের মতই হয়েছে আঘাতপ্রাপ্ত এবং তোমরা আল্লাহর কাছে আশা কর, যা তারা আশা করে না। আল্লাহ মহাজ্ঞানী, প্রজ্ঞাময়।'),
  ('bn.bengali', 4, 105, 'নিশ্চয় আমি আপনার প্রতি সত্য কিতাব অবতীর্ণ করেছি, যাতে আপনি মানুষের মধ্যে ফয়সালা করেন, যা আল্লাহ আপনাকে হৃদয়ঙ্গম করান। আপনি বিশ্বাসঘাতকদের পক্ষ থেকে বিতর্ককারী হবেন না।'),
  ('bn.bengali', 4, 106, 'এবং আল্লাহর কাছে ক্ষমা প্রার্থনা করুন। নিশ্চয় আল্লাহ ক্ষমাশীল, দয়ালু।'),
  ('bn.bengali', 4, 107, 'যারা মনে বিশ্বাস ঘাতকতা পোষণ করে তাদের পক্ষ থেকে বিতর্ক করবেন না। আল্লাহ পছন্দ করেন না তাকে, যে বিশ্বাস ঘাতক পাপী হয়।'),
  ('bn.bengali', 4, 108, 'তারা মানুষের কাছে লজ্জিত হয় এবং আল্লাহর কাছে লজ্জিত হয় না। তিনি তাদের সাথে রয়েছেন, যখন তারা রাত্রে এমন বিষয়ে পরামর্শ করে, যাতে আল্লাহ সম্মত নন। তারা যাকিছু করে, সবই আল্লাহর আয়ত্তাধীণ।'),
  ('bn.bengali', 4, 109, 'শুনছ? তোমরা তাদের পক্ষ থেকে পার্থিব জীবনে বিবাদ করছ, অতঃপর কেয়ামতের দিনে তাদের পক্ষ হয়ে আল্লাহর সাথে কে বিবাদ করবে অথবা কে তাদের কার্যনির্বাহী হবে।'),
  ('bn.bengali', 4, 110, 'যে গোনাহ, করে কিংবা নিজের অনিষ্ট করে, অতঃপর আল্লাহর কাছে ক্ষমা প্রার্থনা করে, সে আল্লাহকে ক্ষমাশীল, করুণাময় পায়।'),
  ('bn.bengali', 4, 111, 'যে কেউ পাপ করে, সে নিজের পক্ষেই করে। আল্লাহ মহাজ্ঞানী, প্রজ্ঞাময়।'),
  ('bn.bengali', 4, 112, 'যে ব্যক্তি ভূল কিংবা গোনাহ করে, অতঃপর কোন নিরপরাধের উপর অপবাদ আরোপ করে সে নিজের মাথায় বহন করে জঘন্য মিথ্যা ও প্রকাশ্য গোনাহ।'),
  ('bn.bengali', 4, 113, 'যদি আপনার প্রতি আল্লাহর অনুগ্রহ ও করুণা না হত, তবে তাদের একদল আপনাকে পথভ্রষ্ট করার সংকল্প করেই ফেলেছিল। তারা পথভ্রান্ত করতে পারে না কিন্তু নিজেদেরকেই এবং আপনার কোন অনিষ্ট করতে পারে না। আল্লাহ আপনার প্রতি ঐশী গ্রন্থ ও প্রজ্ঞা অবতীর্ণ করেছেন এবং আপনাকে এমন বিষয় শিক্ষা দিয়েছেন, যা আপনি জানতেন না। আপনার প্রতি আল্লাহর করুণা অসীম।'),
  ('bn.bengali', 4, 114, 'তাদের অধিকাংশ সলা-পরামর্শ ভাল নয়; কিন্তু যে সলা-পরামর্শ দান খয়রাত করতে কিংবা সৎকাজ করতে কিংবা মানুষের মধ্যে সন্ধিস্থাপন কল্পে করতো তা স্বতন্ত্র। যে একাজ করে আল্লাহর সন্তুষ্টির জন্যে আমি তাকে বিরাট ছওয়াব দান করব।'),
  ('bn.bengali', 4, 115, 'যে কেউ রসূলের বিরুদ্ধাচারণ করে, তার কাছে সরল পথ প্রকাশিত হওয়ার পর এবং সব মুসলমানের অনুসৃত পথের বিরুদ্ধে চলে, আমি তাকে ঐ দিকেই ফেরাব যে দিক সে অবলম্বন করেছে এবং তাকে জাহান্নামে নিক্ষেপ করব। আর তা নিকৃষ্টতর গন্তব্যস্থান।'),
  ('bn.bengali', 4, 116, 'নিশ্চয় আল্লাহ তাকে ক্ষমা করেন না, যে তাঁর সাথে কাউকে শরীক করে। এছাড়া যাকে ইচ্ছা, ক্ষমা করেন। যে আল্লাহর সাথে শরীক করে সে সুদূর ভ্রান্তিতে পতিত হয়।'),
  ('bn.bengali', 4, 117, 'তারা আল্লাহকে পরিত্যাগ করে শুধু নারীর আরাধনা করে এবং শুধু অবাধ্য শয়তানের পূজা করে।'),
  ('bn.bengali', 4, 118, 'যার প্রতি আল্লাহ অভিসম্পাত করেছেন। শয়তান বললঃ আমি অবশ্যই তোমার বান্দাদের মধ্য থেকে নির্দিষ্ট অংশ গ্রহণ করব।'),
  ('bn.bengali', 4, 119, 'তাদেরকে পথভ্রষ্ট করব, তাদেরকে আশ্বাস দেব; তাদেরকে পশুদের কর্ণ ছেদন করতে বলব এবং তাদেরকে আল্লাহর সৃষ্ট আকৃতি পরিবর্তন করতে আদেশ দেব। যে কেউ আল্লাহকে ছেড়ে শয়তানকে বন্ধুরূপে গ্রহণ করে, সে প্রকাশ্য ক্ষতিতে পতিত হয়।'),
  ('bn.bengali', 4, 120, 'সে তাদেরকে প্রতিশ্রুতি দেয় এবং তাদেরকে আশ্বাস দেয়। শয়তান তাদেরকে যে প্রতিশ্রুতি দেয়, তা সব প্রতারণা বৈ নয়।'),
  ('bn.bengali', 4, 121, 'তাদের বাসস্থান জাহান্নাম। তারা সেখান থেকে কোথাও পালাবার জায়গা পাবে না।'),
  ('bn.bengali', 4, 122, 'যারা বিশ্বাস স্থাপন করেছে এবং সৎকর্ম করেছে, আমি তাদেরকে উদ্যানসমূহে প্রবিষ্ট করাব, যেগুলোর তলদেশে নহরসমূহ প্রবাহিত হয়। তারা চিরকাল তথায় অবস্থান করবে। আল্লাহ প্রতিশ্রুতি দিয়েছেন সত্য সত্য। আল্লাহর চাইতে অধিক সত্যবাদী কে?'),
  ('bn.bengali', 4, 123, 'তোমাদের আশার উপর ও ভিত্তি নয় এবং আহলে-কিতাবদের আশার উপরও না। যে কেউ মন্দ কাজ করবে, সে তার শাস্তি পাবে এবং সে আল্লাহ ছাড়া নিজের কোন সমর্থক বা সাহায্যকারী পাবে না।'),
  ('bn.bengali', 4, 124, 'যে লোক পুরুষ হোক কিংবা নারী, কোন সৎকর্ম করে এবং বিশ্বাসী হয়, তবে তারা জান্নাতে প্রবেশ করবে এবং তাদের প্রাপ্য তিল পরিমাণ ও নষ্ট হবে না।'),
  ('bn.bengali', 4, 125, 'যে আল্লাহর নির্দেশের সামনে মস্তক অবনত করে সৎকাজে নিয়োজিত থাকে এবং ইব্রাহীমের ধর্ম অনুসরণ করে, যিনি একনিষ্ঠ ছিলেন, তার চাইতে উত্তম ধর্ম কার? আল্লাহ ইব্রাহীমকে বন্ধুরূপে গ্রহণ করেছেন।'),
  ('bn.bengali', 4, 126, 'যা কিছু নভোন্ডলে আছে এবং যা কিছু ভুমন্ডলে আছে, সব আল্লাহরই। সব বস্তু আল্লাহর মুষ্ঠি বলয়ে।'),
  ('bn.bengali', 4, 127, 'তারা আপনার কাছে নারীদের বিবাহের অনুমতি চায়। বলে দিনঃ আল্লাহ তোমাদেরকে তাদের সম্পর্কে অনুমতি দেন এবং কোরআনে তোমাদেরকে যা যা পাট করে শুনানো হয়, তা ঐ সব পিতৃহীনা-নারীদের বিধান, যাদের কে তোমরা নির্ধারিত অধিকার প্রদান কর না অথচ বিবাহ বন্ধনে আবদ্ধ করার বাসনা রাখ। আর অক্ষম শিশুদের বিধান এই যে, এতীমদের জন্যে ইনসাফের উপর কায়েম থাক। তোমরা যা ভাল কাজ করবে, তা আল্লাহ জানেন।'),
  ('bn.bengali', 4, 128, 'যদি কোন নারী স্বীয় স্বামীর পক্ষ থেকে অসদাচরণ কিংবা উপেক্ষার আশংকা করে, তবে পরস্পর কোন মীমাংসা করে নিলে তাদের উভয়ের কোন গোনাহ নাই। মীমাংসা উত্তম। মনের সামনে লোভ বিদ্যমান আছে। যদি তোমরা উত্তম কাজ কর এবং খোদাভীরু হও, তবে, আল্লাহ তোমাদের সব কাজের খবর রাখেন।'),
  ('bn.bengali', 4, 129, 'তোমরা কখনও নারীদেরকে সমান রাখতে পারবে না, যদিও এর আকাঙ্ক্ষী হও। অতএব, সম্পূর্ণ ঝুঁকেও পড়ো না যে, একজনকে ফেলে রাখ দোদুল্যমান অবস্থায়। যদি সংশোধন কর এবং খোদাভীরু হও, তবে আল্লাহ ক্ষমাশীল, করুণাময়।'),
  ('bn.bengali', 4, 130, 'যদি উভয়েই বিচ্ছিন্ন হয়ে যায়, তবে আল্লাহ স্বীয় প্রশস্ততা দ্বারা প্রত্যেককে অমুখাপেক্ষী করে দিবেন। আল্লাহ সুপ্রশস্ত, প্রজ্ঞাময়।'),
  ('bn.bengali', 4, 131, 'আর যা কিছু রয়েছে আসমান সমূহে ও যমীনে সবই আল্লাহর। বস্তুতঃ আমি নির্দেশ দিয়েছি তোমাদের পূর্ববর্তী গ্রন্থের অধিকারীদেরকে এবং তোমাদেরকে যে, তোমরা সবাই ভয় করতে থাক আল্লাহকে। যদি তোমরা তা না মান, তবে জেনো, সে সব কিছুই আল্লাহ তা’আলার যা কিছু রয়েছে আসমান সমূহে ও যমীনে। আর আল্লাহ হচ্ছেন অভাবহীন, প্রসংশিত।'),
  ('bn.bengali', 4, 132, 'আর আল্লাহরই জন্যে সে সবকিছু যা কিছু রয়েছে আসমান সমূহে ও যমীনে। আল্লাহই যথেষ্ট কর্মবিধায়ক।'),
  ('bn.bengali', 4, 133, 'হে মানবকূল, যদি আল্লাহ তোমাদেরকে সরিয়ে তোমাদের জায়গায় অন্য কাউকে প্রতিষ্ঠিত করেন? বস্তুতঃ আল্লাহর সে ক্ষমতা রয়েছে।'),
  ('bn.bengali', 4, 134, 'যে কেউ দুনিয়ার কল্যাণ কামনা করবে, তার জেনে রাখা প্রয়োজন যে, দুনিয়া ও আখেরাতের কল্যাণ আল্লাহরই নিকট রয়েছে। আর আল্লাহ সব কিছু শোনেন ও দেখেন।'),
  ('bn.bengali', 4, 135, 'হে ঈমানদারগণ, তোমরা ন্যায়ের উপর প্রতিষ্ঠিত থাক; আল্লাহর ওয়াস্তে ন্যায়সঙ্গত সাক্ষ্যদান কর, তাতে তোমাদের নিজের বা পিতা-মাতার অথবা নিকটবর্তী আত্নীয়-স্বজনের যদি ক্ষতি হয় তবুও। কেউ যদি ধনী কিংবা দরিদ্র হয়, তবে আল্লাহ তাদের শুভাকাঙ্খী তোমাদের চাইতে বেশী। অতএব, তোমরা বিচার করতে গিয়ে রিপুর কামনা-বাসনার অনুসরণ করো না। আর যদি তোমরা ঘুরিয়ে-পেঁচিয়ে কথা বল কিংবা পাশ কাটিয়ে যাও, তবে আল্লাহ তোমাদের যাবতীয় কাজ কর্ম সম্পর্কেই অবগত।'),
  ('bn.bengali', 4, 136, 'হে ঈমানদারগণ, আল্লাহর উপর পরিপূর্ণ বিশ্বাস স্থাপন কর এবং বিশ্বাস স্থাপন কর তাঁর রসূলও তাঁর কিতাবের উপর, যা তিনি নাযিল করেছেন স্বীয় রসূলের উপর এবং সেসমস্ত কিতাবের উপর, যেগুলো নাযিল করা হয়েছিল ইতিপূর্বে। যে আল্লাহর উপর, তাঁর ফেরেশতাদের উপর, তাঁর কিতাব সমূহের উপর এবং রসূলগণের উপর ও কিয়ামতদিনের উপর বিশ্বাস করবে না, সে পথভ্রষ্ট হয়ে বহু দূরে গিয়ে পড়বে।'),
  ('bn.bengali', 4, 137, 'যারা একবার মুসলমান হয়ে পরে পুনরায় কাফের হয়ে গেছে, আবার মুসলমান হয়েছে এবং আবারো কাফের হয়েছে এবং কুফরীতেই উন্নতি লাভ করেছে, আল্লাহ তাদেরকে না কখনও ক্ষমা করবেন, না পথ দেখাবেন।'),
  ('bn.bengali', 4, 138, 'সেসব মুনাফেককে সুসংবাদ শুনিয়ে দিন যে, তাদের জন্য নির্ধারিত রয়েছে বেদনাদায়ক আযাব।'),
  ('bn.bengali', 4, 139, 'যারা মুসলমানদের বর্জন করে কাফেরদেরকে নিজেদের বন্ধু বানিয়ে নেয় এবং তাদেরই কাছে সম্মান প্রত্যাশা করে, অথচ যাবতীয় সম্মান শুধুমাত্র আল্লাহরই জন্য।'),
  ('bn.bengali', 4, 140, 'আর কোরআনের মাধ্যমে তোমাদের প্রতি এই হুকুম জারি করে দিয়েছেন যে, যখন আল্লাহ তা’ আলার আয়াতসমূহের প্রতি অস্বীকৃতি জ্ঞাপন ও বিদ্রুপ হতে শুনবে, তখন তোমরা তাদের সাথে বসবে না, যতক্ষণ না তারা প্রসঙ্গান্তরে চলে যায়। তা না হলে তোমরাও তাদেরই মত হয়ে যাবে। আল্লাহ দোযখের মাঝে মুনাফেক ও কাফেরদেরকে একই জায়গায় সমবেত করবেন।'),
  ('bn.bengali', 4, 141, 'এরা এমনি মুনাফেক যারা তোমাদের কল্যাণ-অকল্যাণের প্রতীক্ষায় ওঁৎপেতে থাকে। অতঃপর আল্লাহর ইচ্ছায় তোমাদের যদি কোন বিজয় অর্জিত হয়, তবে তারা বলে, আমরাও কি তোমাদের সাথে ছিলাম না? পক্ষান্তরে কাফেরদের যদি আংশিক বিজয় হয়, তবে বলে, আমরা কি তোমাদেরকে ঘিরে রাখিনি এবং মুসলমানদের কবল থেকে রক্ষা করিনি? সুতরাং আল্লাহ তোমাদের মধ্যে কেয়ামতের দিন মীমাংসা করবেন এবং কিছুতেই আল্লাহ কাফেরদেরকে মুসলমানদের উপর বিজয় দান করবেন না।'),
  ('bn.bengali', 4, 142, 'অবশ্যই মুনাফেকরা প্রতারণা করছে আল্লাহর সাথে, অথচ তারা নিজেরাই নিজেদের প্রতারিত করে। বস্তুতঃ তারা যখন নামাযে দাঁড়ায় তখন দাঁড়ায়, একান্ত শিথিল ভাবে লোক দেখানোর জন্য। আর তারা আল্লাহকে অল্পই স্মরণ করে।'),
  ('bn.bengali', 4, 143, 'এরা দোদুল্যমান অবস্থায় ঝুলন্ত; এদিকেও নয় ওদিকেও নয়। বস্তুতঃ যাকে আল্লাহ গোমরাহ করে দেন, তুমি তাদের জন্য কোন পথই পাবে না কোথাও।'),
  ('bn.bengali', 4, 144, 'হে ঈমানদারগণ! তোমরা কাফেরদেরকে বন্ধু বানিও না মুসলমানদের বাদ দিয়ে। তোমরা কি এমনটি করে নিজের উপর আল্লাহর প্রকাশ্য দলীল কায়েম করে দেবে?'),
  ('bn.bengali', 4, 145, 'নিঃসন্দেহে মুনাফেকরা রয়েছে দোযখের সর্বনিম্ন স্তরে। আর তোমরা তাদের জন্য কোন সাহায্যকারী কখনও পাবে না।'),
  ('bn.bengali', 4, 146, 'অবশ্য যারা তওবা করে নিয়েছে, নিজেদের অবস্থার সংস্কার করেছে এবং আল্লাহর পথকে সুদৃঢ়ভাবে আঁকড়ে ধরে আল্লাহর ফরমাবরদার হয়েছে, তারা থাকবে মুসলমানদেরই সাথে। বস্তুতঃ আল্লাহ শীঘ্রই ঈমানদারগণকে মহাপূণ্য দান করবেন।'),
  ('bn.bengali', 4, 147, 'তোমাদের আযাব দিয়ে আল্লাহ কি করবেন যদি তোমরা কৃতজ্ঞতা প্রকাশ কর এবং ঈমানের উপর প্রতিষ্ঠিত থাক! আর আল্লাহ হচ্ছেন সমুচিত মূল্যদানকারী সর্বজ্ঞ।'),
  ('bn.bengali', 4, 148, 'আল্লাহ কোন মন্দ বিষয় প্রকাশ করা পছন্দ করেন না। তবে কারো প্রতি জুলুম হয়ে থাকলে সে কথা আলাদা। আল্লাহ শ্রবণকারী, বিজ্ঞ।'),
  ('bn.bengali', 4, 149, 'তোমরা যদি কল্যাণ কর প্রকাশ্যভাবে কিংবা গোপনে অথবা যদি তোমরা আপরাধ ক্ষমা করে দাও, তবে জেনো, আল্লাহ নিজেও ক্ষমাকারী, মহাশক্তিশালী।'),
  ('bn.bengali', 4, 150, 'যারা আল্লাহ ও তার রসূলের প্রতি অস্বীকৃতি জ্ঞাপনকারী তদুপরি আল্লাহ ও রসূলের প্রতি বিশ্বাসে তারতম্য করতে চায় আর বলে যে, আমরা কতককে বিশ্বাস করি কিন্তু কতককে প্রত্যাখ্যান করি এবং এরই মধ্যবর্তী কোন পথ অবলম্বন করতে চায়।'),
  ('bn.bengali', 4, 151, 'প্রকৃতপক্ষে এরাই সত্য প্রত্যাখ্যাকারী। আর যারা সত্য প্রত্যাখ্যানকারী তাদের জন্য তৈরী করে রেখেছি অপমানজনক আযাব।'),
  ('bn.bengali', 4, 152, 'আর যারা ঈমান এনেছে আল্লাহর উপর, তাঁর রসূলের উপর এবং তাঁদের কারও প্রতি ঈমান আনতে গিয়ে কাউকে বাদ দেয়নি, শীঘ্রই তাদেরকে প্রাপ্য সওয়াব দান করা হবে। বস্তুতঃ আল্লাহ ক্ষমাশীল দয়ালু।'),
  ('bn.bengali', 4, 153, 'আপনার নিকট আহলে-কিতাবরা আবেদন জানায় যে, আপনি তাদের উপর আসমান থেকে লিখিত কিতাব অবতীর্ণ করিয়ে নিয়ে আসুন। বস্তুতঃ এরা মূসার কাছে এর চেয়েও বড় জিনিস চেয়েছে। বলেছে, একেবারে সামনাসামনিভাবে আমাদের আল্লাহকে দেখিয়ে দাও। অতএব, তাদের উপর বজ্রপাত হয়েছে তাদের পাপের দরুন; অতঃপর তাদের নিকট সুস্পষ্ট প্রমাণ-নিদর্শন প্রকাশিত হবার পরেও তারা গো-বৎসকে উপাস্যরূপে গ্রহণ করেছিল; তাও আমি ক্ষমা করে দিয়েছিলাম এবং আমি মূসাকে প্রকৃষ্ট প্রভাব দান করেছিলাম।'),
  ('bn.bengali', 4, 154, 'আর তাদের কাছ থেকে প্রতিশ্রুতি নেবার উদ্দেশ্যে আমি তাদের উপর তূর পর্বতকে তুলে ধরেছিলাম এবং তাদেরকে বলেছিলাম, অবনত মস্তকে দরজায় ঢোক। আর বলেছিলাম, শনিবার দিন সীমালংঘন করো না। এভাবে তাদের কাছ থেকে দৃঢ় অঙ্গীকার নিয়েছিলাম।'),
  ('bn.bengali', 4, 155, 'অতএব, তারা যে শাস্তিপ্রাপ্ত হয়েছিল, তা ছিল তাদেরই অঙ্গীকার ভঙ্গর জন্য এবং অন্যায়ভাবে রসূলগণকে হত্যা করার কারণে এবং তাদের এই উক্তির দরুন যে, আমাদের হৃদয় আচ্ছন্ন। অবশ্য তা নয়, বরং কুফরীর কারণে স্বয়ং আল্লাহ তাদের অন্তরের উপর মোহর এঁটে দিয়েছেন। ফলে এরা ঈমান আনে না কিন্তু অতি অল্পসংখ্যক।'),
  ('bn.bengali', 4, 156, 'আর তাদের কুফরী এবং মরিয়মের প্রতি মহা অপবাদ আরোপ করার কারণে।'),
  ('bn.bengali', 4, 157, 'আর তাদের একথা বলার কারণে যে, আমরা মরিয়ম পুত্র ঈসা মসীহকে হত্যা করেছি যিনি ছিলেন আল্লাহর রসূল। অথচ তারা না তাঁকে হত্যা করেছে, আর না শুলীতে চড়িয়েছে, বরং তারা এরূপ ধাঁধায় পতিত হয়েছিল। বস্তুতঃ তারা এ ব্যাপারে নানা রকম কথা বলে, তারা এক্ষেত্রে সন্দেহের মাঝে পড়ে আছে, শুধুমাত্র অনুমান করা ছাড়া তারা এ বিষয়ে কোন খবরই রাখে না। আর নিশ্চয়ই তাঁকে তারা হত্যা করেনি।'),
  ('bn.bengali', 4, 158, 'বরং তাঁকে উঠিয়ে নিয়েছেন আল্লাহ তা’আলা নিজের কাছে। আর আল্লাহ হচ্ছেন মহাপরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 4, 159, 'আর আহলে-কিতাবদের মধ্যে যত শ্রেণী রয়েছে তারা সবাই ঈমান আনবে ঈসার উপর তাদের মৃত্যুর পূর্বে। আর কেয়ামতের দিন তাদের জন্য সাক্ষীর উপর সাক্ষী উপস্থিত হবে।'),
  ('bn.bengali', 4, 160, 'বস্তুতঃ ইহুদীদের জন্য আমি হারাম করে দিয়েছি বহু পূত-পবিত্র বস্তু যা তাদের জন্য হালাল ছিল-তাদের পাপের কারণে এবং আল্লাহর পথে অধিক পরিমাণে বাধা দানের দরুন।'),
  ('bn.bengali', 4, 161, 'আর এ কারণে যে, তারা সুদ গ্রহণ করত, অথচ এ ব্যাপারে নিষেধাজ্ঞা আরোপ করা হয়েছিল এবং এ কারণে যে, তারা অপরের সম্পদ ভোগ করতো অন্যায় ভাবে। বস্তুত; আমি কাফেরদের জন্য তৈরী করে রেখেছি বেদনাদায়ক আযাব।'),
  ('bn.bengali', 4, 162, 'কিন্তু যারা তাদের মধ্যে জ্ঞানপক্ক ও ঈমানদার, তারা তাও মান্য করে যা আপনার উপর অবতীর্ণ হয়েছে এবং যা অবতীর্ণ হয়েছে আপনার পূর্বে। আর যারা নামাযে অনুবর্তিতা পালনকারী, যারা যাকাত দানকারী এবং যারা আল্লাহ ও কেয়ামতে আস্থাশীল। বস্তুতঃ এমন লোকদেরকে আমি দান করবো মহাপুণ্য।'),
  ('bn.bengali', 4, 163, 'আমি আপনার প্রতি ওহী পাঠিয়েছি, যেমন করে ওহী পাঠিয়েছিলাম নূহের প্রতি এবং সে সমস্ত নবী-রসূলের প্রতি যাঁরা তাঁর পরে প্রেরিত হয়েছেন। আর ওহী পাঠিয়েছি, ইসমাঈল, ইব্রাহীম, ইসহাক, ইয়াকুব, ও তাঁর সন্তাবর্গের প্রতি এবং ঈসা, আইয়ুব, ইউনূস, হারুন ও সুলায়মানের প্রতি। আর আমি দাউদকে দান করেছি যবুর গ্রন্থ।'),
  ('bn.bengali', 4, 164, 'এছাড়া এমন রসূল পাঠিয়েছি যাদের ইতিবৃত্ত আমি আপনাকে শুনিয়েছি ইতিপূর্বে এবং এমন রসূল পাঠিয়েছি যাদের বৃত্তান্ত আপনাকে শোনাইনি। আর আল্লাহ মূসার সাথে কথোপকথন করেছেন সরাসরি।'),
  ('bn.bengali', 4, 165, 'সুসংবাদদাতা ও ভীতি-প্রদর্শনকারী রসূলগণকে প্রেরণ করেছি, যাতে রসূলগণের পরে আল্লাহর প্রতি অপবাদ আরোপ করার মত কোন অবকাশ মানুষের জন্য না থাকে। আল্লাহ প্রবল পরাক্রমশীল, প্রাজ্ঞ।'),
  ('bn.bengali', 4, 166, 'আল্লাহ আপনার প্রতি যা অবতীর্ণ করেছেন তিনি যে তা সজ্ঞানেই করেছেন, সে ব্যাপারে আল্লাহ নিজেও সাক্ষী এবং ফেরেশতাগণও সাক্ষী। আর সাক্ষী হিসাবে আল্লাহই যথেষ্ট।'),
  ('bn.bengali', 4, 167, 'যারা কুফরী অবলম্বন করেছে, এবং আল্লাহর পথে বাধার সৃষ্টি করেছে, তারা বিভ্রান্তিতে সুদূরে পতিত হয়েছে।'),
  ('bn.bengali', 4, 168, 'যারা কুফরী অবলম্বন করেছে এবং সত্য চাপা দিয়ে রেখেছে, আল্লাহ কখনও তাদের ক্ষমা করবেন না এবং সরল পথ দেখাবেন না।'),
  ('bn.bengali', 4, 169, 'তাদের জন্য রয়েছে জাহান্নামের পথ। সেখানে তারা বাস করবে অনন্তকাল। আর এমন করাটা আল্লাহর পক্ষে সহজ।'),
  ('bn.bengali', 4, 170, 'হে মানবজাতি! তোমাদের পালনকর্তার যথার্থ বাণী নিয়ে তোমাদের নিকট রসূল এসেছেন, তোমরা তা মেনে নাও যাতে তোমাদের কল্যাণ হতে পারে। আর যদি তোমরা তা না মান, জেনে রাখ আসমানসমূহে ও যমীনে যা কিছু রয়েছে সে সবকিছুই আল্লাহর। আর আল্লাহ হচ্ছেন সর্বজ্ঞ, প্রাজ্ঞ।'),
  ('bn.bengali', 4, 171, 'হে আহলে-কিতাবগণ! তোমরা দ্বীনের ব্যাপারে বাড়াবাড়ি করো না এবং আল্লাহর শানে নিতান্ত সঙ্গত বিষয় ছাড়া কোন কথা বলো না। নিঃসন্দেহে মরিয়ম পুত্র মসীহ ঈসা আল্লাহর রসূল এবং তাঁর বাণী যা তিনি প্রেরণ করেছেন মরিয়মের নিকট এবং রূহ-তাঁরই কাছ থেকে আগত। অতএব, তোমরা আল্লাহকে এবং তার রসূলগণকে মান্য কর। আর একথা বলো না যে, আল্লাহ তিনের এক, একথা পরিহার কর; তোমাদের মঙ্গল হবে। নিঃসন্দেহে আল্লাহ একক উপাস্য। সন্তান-সন্ততি হওয়াটা তাঁর যোগ্য বিষয় নয়। যা কিছু আসমান সমূহ ও যমীনে রয়েছে সবই তার। আর কর্মবিধানে আল্লাহই যথেষ্ট।'),
  ('bn.bengali', 4, 172, 'মসীহ আল্লাহর বান্দা হবেন, তাতে তার কোন লজ্জাবোধ নেই এবং ঘনিষ্ঠ ফেরেশতাদেরও না। বস্তুতঃ যারা আল্লাহর দাসত্বে লজ্জাবোধ করবে এবং অহংকার করবে, তিনি তাদের সবাইকে নিজের কাছে সমবেত করবেন।'),
  ('bn.bengali', 4, 173, 'অতঃপর যারা ঈমান এনেছে এবং সৎকাজ করেছে, তিনি তাদেরকে পরিপূর্ণ সওয়াব দান করবেন, বরং স্বীয় অনুগ্রহে আরো বেশী দেবেন। পক্ষান্তরে যারা লজ্জাবোধ করেছে এবং অহঙ্কার করেছে তিনি তাদেরকে দেবেন বেদনাদায়ক আযাব। আল্লাহকে ছাড়া তারা কোন সাহায্যকারী ও সমর্থক পাবে না।'),
  ('bn.bengali', 4, 174, 'হে মানবকুল! তোমাদের পরওয়ারদেগারের পক্ষ থেকে তোমাদের নিকট সনদ পৌঁছে গেছে। আর আমি তোমাদের প্রতি প্রকৃষ্ট আলো অবতীর্ণ করেছি।'),
  ('bn.bengali', 4, 175, 'অতএব, যারা আল্লাহর প্রতি ঈমান এনেছে এবং তাতে দৃঢ়তা অবলম্বন করেছে তিনি তাদেরকে স্বীয় রহমত ও অনুগ্রহের আওতায় স্থান দেবেন এবং নিজের দিকে আসার মত সরল পথে তুলে দেবেন।'),
  ('bn.bengali', 4, 176, 'মানুষ আপনার নিকট ফতোয়া জানতে চায় অতএব, আপনি বলে দিন, আল্লাহ তোমাদিগকে কালালাহ এর মীরাস সংক্রান্ত সুস্পষ্ট নির্দেশ বাতলে দিচ্ছেন, যদি কোন পুরুষ মারা যায় এবং তার কোন সন্তানাদি না থাকে এবং এক বোন থাকে, তবে সে পাবে তার পরিত্যাক্ত সম্পত্তির অর্ধেক অংশ এবং সে যদি নিঃসন্তান হয়, তবে তার ভাই তার উত্তরাধিকারী হবে। তা দুই বোন থাকলে তাদের জন্য পরিত্যক্ত সম্পত্তির দুই তৃতীয়াংশ। পক্ষান্তরে যদি ভাই ও বোন উভয়ই থাকে, তবে একজন পুরুষের অংশ দুজন নারীর সমান। তোমরা বিভ্রান্ত হবে আল্লাহ তোমাদিগকে সুস্পষ্ট ভাবে জানিয়ে দিচ্ছেন। আর আল্লাহ হচ্ছেন সর্ব বিষয়ে পরিজ্ঞাত।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 4, 1, 'O mankind! Be careful of your duty to your Lord Who created you from a single soul and from it created its mate and from them twain hath spread abroad a multitude of men and women. Be careful of your duty toward Allah in Whom ye claim (your rights) of one another, and toward the wombs (that bare you). Lo! Allah hath been a watcher over you.'),
  ('en.pickthall', 4, 2, 'Give unto orphans their wealth. Exchange not the good for the bad (in your management thereof) nor absorb their wealth into your own wealth. Lo! that would be a great sin.'),
  ('en.pickthall', 4, 3, 'And if ye fear that ye will not deal fairly by the orphans, marry of the women, who seem good to you, two or three or four; and if ye fear that ye cannot do justice (to so many) then one (only) or (the captives) that your right hands possess. Thus it is more likely that ye will not do injustice.'),
  ('en.pickthall', 4, 4, 'And give unto the women (whom ye marry) free gift of their marriage portions; but if they of their own accord remit unto you a part thereof, then ye are welcome to absorb it (in your wealth).'),
  ('en.pickthall', 4, 5, 'Give not unto the foolish (what is in) your (keeping of their) wealth, which Allah hath given you to maintain; but feed and clothe them from it, and speak kindly unto them.'),
  ('en.pickthall', 4, 6, 'Prove orphans till they reach the marriageable age; then, if ye find them of sound judgment, deliver over unto them their fortune; and devour it not by squandering and in haste lest they should grow up Whoso (of the guardians) is rich, let him abstain generously (from taking of the property of orphans); and whoso is poor let him take thereof in reason (for his guardianship). And when ye deliver up their fortune unto orphans, have (the transaction) witnessed in their presence. Allah sufficeth as a Reckoner.'),
  ('en.pickthall', 4, 7, 'Unto the men (of a family) belongeth a share of that which parents and near kindred leave, and unto the women a share of that which parents and near kindred leave, whether it be little or much - a legal share.'),
  ('en.pickthall', 4, 8, 'And when kinsfolk and orphans and the needy are present at the division (of the heritage), bestow on them therefrom and speak kindly unto them.'),
  ('en.pickthall', 4, 9, 'And let those fear (in their behaviour toward orphans) who if they left behind them weak offspring would be afraid for them. So let them mind their duty to Allah, and speak justly.'),
  ('en.pickthall', 4, 10, 'Lo! Those who devour the wealth of orphans wrongfully, they do but swallow fire into their bellies, and they will be exposed to burning flame.'),
  ('en.pickthall', 4, 11, 'Allah chargeth you concerning (the provision for) your children: to the male the equivalent of the portion of two females, and if there be women more than two, then theirs is two-thirds of the inheritance, and if there be one (only) then the half. And to each of his parents a sixth of the inheritance, if he have a son; and if he have no son and his parents are his heirs, then to his mother appertaineth the third; and if he have brethren, then to his mother appertaineth the sixth, after any legacy he may have bequeathed, or debt (hath been paid). Your parents and your children: Ye know not which of them is nearer unto you in usefulness. It is an injunction from Allah. Lo! Allah is Knower, Wise.'),
  ('en.pickthall', 4, 12, 'And unto you belongeth a half of that which your wives leave, if they have no child; but if they have a child then unto you the fourth of that which they leave, after any legacy they may have bequeathed, or debt (they may have contracted, hath been paid). And unto them belongeth the fourth of that which ye leave if ye have no child, but if ye have a child then the eighth of that which ye leave, after any legacy ye may have bequeathed, or debt (ye may have contracted, hath been paid). And if a man or a woman have a distant heir (having left neither parent nor child), and he (or she) have a brother or a sister (only on the mother\'s side) then to each of them twain (the brother and the sister) the sixth, and if they be more than two, then they shall be sharers in the third, after any legacy that may have been bequeathed or debt (contracted) not injuring (the heirs by willing away more than a third of the heritage) hath been paid. A commandment from Allah. Allah is Knower, Indulgent.'),
  ('en.pickthall', 4, 13, 'These are the limits (imposed by) Allah. Whoso obeyeth Allah and His messenger, He will make him enter Gardens underneath which rivers flow, where such will dwell for ever. That will be the great success.'),
  ('en.pickthall', 4, 14, 'And whoso disobeyeth Allah and His messenger and transgresseth His limits, He will make him enter Fire, where he will dwell for ever; his will be a shameful doom.'),
  ('en.pickthall', 4, 15, 'As for those of your women who are guilty of lewdness, call to witness four of you against them. And if they testify (to the truth of the allegation) then confine them to the houses until death take them or (until) Allah appoint for them a way (through new legislation).'),
  ('en.pickthall', 4, 16, 'And as for the two of you who are guilty thereof, punish them both. And if they repent and improve, then let them be. Lo! Allah is ever relenting, Merciful.'),
  ('en.pickthall', 4, 17, 'Forgiveness is only incumbent on Allah toward those who do evil in ignorance (and) then turn quickly (in repentance) to Allah. These are they toward whom Allah relenteth. Allah is ever Knower, Wise.'),
  ('en.pickthall', 4, 18, 'The forgiveness is not for those who do ill-deeds until, when death attendeth upon one of them, he saith: Lo! I repent now; nor yet for those who die while they are disbelievers. For such We have prepared a painful doom.'),
  ('en.pickthall', 4, 19, 'O ye who believe! It is not lawful for you forcibly to inherit the women (of your deceased kinsmen), nor (that) ye should put constraint upon them that ye may take away a part of that which ye have given them, unless they be guilty of flagrant lewdness. But consort with them in kindness, for if ye hate them it may happen that ye hate a thing wherein Allah hath placed much good.'),
  ('en.pickthall', 4, 20, 'And if ye wish to exchange one wife for another and ye have given unto one of them a sum of money (however great), take nothing from it. Would ye take it by the way of calumny and open wrong?'),
  ('en.pickthall', 4, 21, 'How can ye take it (back) after one of you hath gone in unto the other, and they have taken a strong pledge from you?'),
  ('en.pickthall', 4, 22, 'And marry not those women whom your fathers married, except what hath already happened (of that nature) in the past. Lo! it was ever lewdness and abomination, and an evil way.'),
  ('en.pickthall', 4, 23, 'Forbidden unto you are your mothers, and your daughters, and your sisters, and your father\'s sisters, and your mother\'s sisters, and your brother\'s daughters and your sister\'s daughters, and your foster-mothers, and your foster-sisters, and your mothers-in-law, and your step-daughters who are under your protection (born) of your women unto whom ye have gone in - but if ye have not gone in unto them, then it is no sin for you (to marry their daughters) - and the wives of your sons who (spring) from your own loins. And (it is forbidden unto you) that ye should have two sisters together, except what hath already happened (of that nature) in the past. Lo! Allah is ever Forgiving, Merciful.'),
  ('en.pickthall', 4, 24, 'And all married women (are forbidden unto you) save those (captives) whom your right hands possess. It is a decree of Allah for you. Lawful unto you are all beyond those mentioned, so that ye seek them with your wealth in honest wedlock, not debauchery. And those of whom ye seek content (by marrying them), give unto them their portions as a duty. And there is no sin for you in what ye do by mutual agreement after the duty (hath been done). Lo! Allah is ever Knower, Wise.'),
  ('en.pickthall', 4, 25, 'And whoso is not able to afford to marry free, believing women, let them marry from the believing maids whom your right hands possess. Allah knoweth best (concerning) your faith. Ye (proceed) one from another; so wed them by permission of their folk, and give unto them their portions in kindness, they being honest, not debauched nor of loose conduct. And if when they are honourably married they commit lewdness they shall incur the half of the punishment (prescribed) for free women (in that case). This is for him among you who feareth to commit sin. But to have patience would be better for you. Allah is Forgiving, Merciful.'),
  ('en.pickthall', 4, 26, 'Allah would explain to you and guide you by the examples of those who were before you, and would turn to you in mercy. Allah is Knower, Wise.'),
  ('en.pickthall', 4, 27, 'And Allah would turn to you in mercy; but those who follow vain desires would have you go tremendously astray.'),
  ('en.pickthall', 4, 28, 'Allah would make the burden light for you, for man was created weak.'),
  ('en.pickthall', 4, 29, 'O ye who believe! Squander not your wealth among yourselves in vanity, except it be a trade by mutual consent, and kill not one another. Lo! Allah is ever Merciful unto you.'),
  ('en.pickthall', 4, 30, 'Whoso doeth that through aggression and injustice, we shall cast him into Fire, and that is ever easy for Allah.'),
  ('en.pickthall', 4, 31, 'If ye avoid the great (things) which ye are forbidden, We will remit from you your evil deeds and make you enter at a noble gate.'),
  ('en.pickthall', 4, 32, 'And covet not the thing in which Allah hath made some of you excel others. Unto men a fortune from that which they have earned, and unto women a fortune from that which they have earned. (Envy not one another) but ask Allah of His bounty. Lo! Allah is ever Knower of all things.'),
  ('en.pickthall', 4, 33, 'And unto each We have appointed heirs of that which parents and near kindred leave; and as for those with whom your right hands have made a covenant, give them their due. Lo! Allah is ever Witness over all things.'),
  ('en.pickthall', 4, 34, 'Men are in charge of women, because Allah hath made the one of them to excel the other, and because they spend of their property (for the support of women). So good women are the obedient, guarding in secret that which Allah hath guarded. As for those from whom ye fear rebellion, admonish them and banish them to beds apart, and scourge them. Then if they obey you, seek not a way against them. Lo! Allah is ever High, Exalted, Great.'),
  ('en.pickthall', 4, 35, 'And if ye fear a breach between them twain (the man and wife), appoint an arbiter from his folk and an arbiter from her folk. If they desire amendment Allah will make them of one mind. Lo! Allah is ever Knower, Aware.'),
  ('en.pickthall', 4, 36, 'And serve Allah. Ascribe no thing as partner unto Him. (Show) kindness unto parents, and unto near kindred, and orphans, and the needy, and unto the neighbour who is of kin (unto you) and the neighbour who is not of kin, and the fellow-traveller and the wayfarer and (the slaves) whom your right hands possess. Lo! Allah loveth not such as are proud and boastful,'),
  ('en.pickthall', 4, 37, 'Who hoard their wealth and enjoin avarice on others, and hide that which Allah hath bestowed upon them of His bounty. For disbelievers We prepare a shameful doom;'),
  ('en.pickthall', 4, 38, 'And (also) those who spend their wealth in order to be seen of men, and believe not in Allah nor the Last Day. Whoso taketh Satan for a comrade, a bad comrade hath he.'),
  ('en.pickthall', 4, 39, 'What have they (to fear) if they believe in Allah and the Last Day and spend (aright) of that which Allah hath bestowed upon them, when Allah is ever Aware of them (and all they do)?'),
  ('en.pickthall', 4, 40, 'Lo! Allah wrongeth not even of the weight of an ant; and if there is a good deed, He will double it and will give (the doer) from His presence an immense reward.'),
  ('en.pickthall', 4, 41, 'But how (will it be with them) when We bring of every people a witness, and We bring thee (O Muhammad) a witness against these?'),
  ('en.pickthall', 4, 42, 'On that day those who disbelieved and disobeyed the messenger will wish that they were level with the ground, and they can hide no fact from Allah.'),
  ('en.pickthall', 4, 43, 'O ye who believe! Draw not near unto prayer when ye are drunken, till ye know that which ye utter, nor when ye are polluted, save when journeying upon the road, till ye have bathed. And if ye be ill, or on a journey, or one of you cometh from the closet, or ye have touched women, and ye find not water, then go to high clean soil and rub your faces and your hands (therewith). Lo! Allah is Benign, Forgiving.'),
  ('en.pickthall', 4, 44, 'Seest thou not those unto whom a portion of the Scripture hath been given, how they purchase error, and seek to make you (Muslims) err from the right way?'),
  ('en.pickthall', 4, 45, 'Allah knoweth best (who are) your enemies. Allah is sufficient as a Guardian, and Allah is sufficient as a Supporter.'),
  ('en.pickthall', 4, 46, 'Some of those who are Jews change words from their context and say: "We hear and disobey; hear thou as one who heareth not" and "Listen to us!" distorting with their tongues and slandering religion. If they had said: "We hear and we obey: hear thou, and look at us" it had been better for them, and more upright. But Allah hath cursed them for their disbelief, so they believe not, save a few.'),
  ('en.pickthall', 4, 47, 'O ye unto whom the Scripture hath been given! Believe in what We have revealed confirming that which ye possess, before We destroy countenances so as to confound them, or curse them as We cursed the Sabbath-breakers (of old time). The commandment of Allah is always executed.'),
  ('en.pickthall', 4, 48, 'Lo! Allah forgiveth not that a partner should be ascribed unto Him. He forgiveth (all) save that to whom He will. Whoso ascribeth partners to Allah, he hath indeed invented a tremendous sin.'),
  ('en.pickthall', 4, 49, 'Hast thou not seen those who praise themselves for purity? Nay, Allah purifieth whom He will, and they will not be wronged even the hair upon a date-stone.'),
  ('en.pickthall', 4, 50, 'See, how they invent lies about Allah! That of itself is flagrant sin.'),
  ('en.pickthall', 4, 51, 'Hast thou not seen those unto whom a portion of the Scripture hath been given, how they believe in idols and false deities, and how they say of those (idolaters) who disbelieve: "These are more rightly guided than those who believe"?'),
  ('en.pickthall', 4, 52, 'Those are they whom Allah hath cursed, and he whom Allah hath cursed, thou (O Muhammad) wilt find for him no helper.'),
  ('en.pickthall', 4, 53, 'Or have they even a share in the Sovereignty? Then in that case, they would not give mankind even the speck on a date-stone.'),
  ('en.pickthall', 4, 54, 'Or are they jealous of mankind because of that which Allah of His bounty hath bestowed upon them? For We bestowed upon the house of Abraham (of old) the Scripture and wisdom, and We bestowed on them a mighty kingdom.'),
  ('en.pickthall', 4, 55, 'And of them were (some) who believed therein and of them were (some) who turned away from it. Hell is sufficient for (their) burning.'),
  ('en.pickthall', 4, 56, 'Lo! Those who disbelieve Our revelations, We shall expose them to the Fire. As often as their skins are consumed We shall exchange them for fresh skins that they may taste the torment. Lo! Allah is ever Mighty, Wise.'),
  ('en.pickthall', 4, 57, 'And as for those who believe and do good works, We shall make them enter Gardens underneath which rivers flow - to dwell therein for ever; there for them are pure companions - and We shall make them enter plenteous shade.'),
  ('en.pickthall', 4, 58, 'Lo! Allah commandeth you that ye restore deposits to their owners, and, if ye judge between mankind, that ye judge justly. Lo! comely is this which Allah admonisheth you. Lo! Allah is ever Hearer, Seer.'),
  ('en.pickthall', 4, 59, 'O ye who believe! Obey Allah, and obey the messenger and those of you who are in authority; and if ye have a dispute concerning any matter, refer it to Allah and the messenger if ye are (in truth) believers in Allah and the Last Day. That is better and more seemly in the end.'),
  ('en.pickthall', 4, 60, 'Hast thou not seen those who pretend that they believe in that which is revealed unto thee and that which was revealed before thee, how they would go for judgment (in their disputes) to false deities when they have been ordered to abjure them? Satan would mislead them far astray.'),
  ('en.pickthall', 4, 61, 'And when it is said unto them: Come unto that which Allah hath revealed and unto the messenger, thou seest the hypocrites turn from thee with aversion.'),
  ('en.pickthall', 4, 62, 'How would it be if a misfortune smote them because of that which their own hands have sent before (them)? Then would they come unto thee, swearing by Allah that they were seeking naught but harmony and kindness.'),
  ('en.pickthall', 4, 63, 'Those are they, the secrets of whose hearts Allah knoweth. So oppose them and admonish them, and address them in plain terms about their souls.'),
  ('en.pickthall', 4, 64, 'We sent no messenger save that he should be obeyed by Allah\'s leave. And if, when they had wronged themselves, they had but come unto thee and asked forgiveness of Allah, and asked forgiveness of the messenger, they would have found Allah Forgiving, Merciful.'),
  ('en.pickthall', 4, 65, 'But nay, by thy Lord, they will not believe (in truth) until they make thee judge of what is in dispute between them and find within themselves no dislike of that which thou decidest, and submit with full submission.'),
  ('en.pickthall', 4, 66, 'And if We had decreed for them: Lay down your lives or go forth from your dwellings, but few of them would have done it; though if they did what they are exhorted to do it would be better for them, and more strengthening;'),
  ('en.pickthall', 4, 67, 'And then We should bestow upon them from Our presence an immense reward,'),
  ('en.pickthall', 4, 68, 'And should guide them unto a straight path.'),
  ('en.pickthall', 4, 69, 'Whoso obeyeth Allah and the messenger, they are with those unto whom Allah hath shown favour, of the prophets and the saints and the martyrs and the righteous. The best of company are they!'),
  ('en.pickthall', 4, 70, 'That is bounty from Allah, and Allah sufficeth as Knower.'),
  ('en.pickthall', 4, 71, 'O ye who believe! Take your precautions, then advance the proven ones, or advance all together.'),
  ('en.pickthall', 4, 72, 'Lo! among you there is he who loitereth; and if disaster overtook you, he would say: Allah hath been gracious unto me since I was not present with them.'),
  ('en.pickthall', 4, 73, 'And if a bounty from Allah befell you, he would surely cry, as if there had been no love between you and him: Oh, would that I had been with them, then should I have achieved a great success!'),
  ('en.pickthall', 4, 74, 'Let those fight in the way of Allah who sell the life of this world for the other. Whoso fighteth in the way of Allah, be he slain or be he victorious, on him We shall bestow a vast reward.'),
  ('en.pickthall', 4, 75, 'How should ye not fight for the cause of Allah and of the feeble among men and of the women and the children who are crying: Our Lord! Bring us forth from out this town of which the people are oppressors! Oh, give us from thy presence some protecting friend! Oh, give us from Thy presence some defender!'),
  ('en.pickthall', 4, 76, 'Those who believe do battle for the cause of Allah; and those who disbelieve do battle for the cause of idols. So fight the minions of the devil. Lo! the devil\'s strategy is ever weak.'),
  ('en.pickthall', 4, 77, 'Hast thou not seen those unto whom it was said: Withhold your hands, establish worship and pay the poordue, but when fighting was prescribed for them behold! a party of them fear mankind even as their fear of Allah or with greater fear, and say: Our Lord! Why hast Thou ordained fighting for us? If only Thou wouldst give us respite yet a while! Say (unto them, O Muhammad): The comfort of this world is scant; the Hereafter will be better for him who wardeth off (evil); and ye will not be wronged the down upon a date-stone.'),
  ('en.pickthall', 4, 78, 'Wheresoever ye may be, death will overtake you, even though ye were in lofty towers. Yet if a happy thing befalleth them they say: This is from Allah; and if an evil thing befalleth them they say: This is of thy doing (O Muhammad). Say (unto them): All is from Allah. What is amiss with these people that they come not nigh to understand a happening?'),
  ('en.pickthall', 4, 79, 'Whatever of good befalleth thee (O man) it is from Allah, and whatever of ill befalleth thee it is from thyself. We have sent thee (Muhammad) as a messenger unto mankind and Allah is sufficient as Witness.'),
  ('en.pickthall', 4, 80, 'Whoso obeyeth the messenger hath obeyed Allah, and whoso turneth away: We have not sent thee as a warder over them.'),
  ('en.pickthall', 4, 81, 'And they say: (It is) obedience; but when they have gone forth from thee a party of them spend the night in planning other than what thou sayest. Allah recordeth what they plan by night. So oppose them and put thy trust in Allah. Allah is sufficient as Trustee.'),
  ('en.pickthall', 4, 82, 'Will they not then ponder on the Qur\'an? If it had been from other than Allah they would have found therein much incongruity.'),
  ('en.pickthall', 4, 83, 'And if any tidings, whether of safety or fear, come unto them, they noise it abroad, whereas if they had referred it to the messenger and to such of them as are in authority, those among them who are able to think out the matter would have known it. If it had not been for the grace of Allah upon you and His mercy ye would have followed Satan, save a few (of you).'),
  ('en.pickthall', 4, 84, 'So fight (O Muhammad) in the way of Allah Thou art not taxed (with the responsibility for anyone) except thyself - and urge on the believers. Peradventure Allah will restrain the might of those who disbelieve. Allah is stronger in might and stronger in inflicting punishment.'),
  ('en.pickthall', 4, 85, 'Whoso interveneth in a good cause will have the reward thereof, and whoso interveneth in an evil cause will bear the consequence thereof. Allah overseeth all things.'),
  ('en.pickthall', 4, 86, 'When ye are greeted with a greeting, greet ye with a better than it or return it. Lo! Allah taketh count of all things.'),
  ('en.pickthall', 4, 87, 'Allah! There is no Allah save Him. He gathereth you all unto a Day of Resurrection whereof there is no doubt. Who is more true in statement than Allah?'),
  ('en.pickthall', 4, 88, 'What aileth you that ye are become two parties regarding the hypocrites, when Allah cast them back (to disbelief) because of what they earned? Seek ye to guide him whom Allah hath sent astray? He whom Allah sendeth astray, for him thou (O MUhammad) canst not find a road.'),
  ('en.pickthall', 4, 89, 'They long that ye should disbelieve even as they disbelieve, that ye may be upon a level (with them). So choose not friends from them till they forsake their homes in the way of Allah; if they turn back (to enmity) then take them and kill them wherever ye find them, and choose no friend nor helper from among them,'),
  ('en.pickthall', 4, 90, 'Except those who seek refuge with a people between whom and you there is a covenant, or (those who) come unto you because their hearts forbid them to make war on you or make war on their own folk. Had Allah willed He could have given them power over you so that assuredly they would have fought you. So, if they hold aloof from you and wage not war against you and offer you peace, Allah alloweth you no way against them.'),
  ('en.pickthall', 4, 91, 'Ye will find others who desire that they should have security from you, and security from their own folk. So often as they are returned to hostility they are plunged therein. If they keep not aloof from you nor offer you peace nor hold their hands, then take them and kill them wherever ye find them. Against such We have given you clear warrant.'),
  ('en.pickthall', 4, 92, 'It is not for a believer to kill a believer unless (it be) by mistake. He who hath killed a believer by mistake must set free a believing slave, and pay the blood-money to the family of the slain, unless they remit it as a charity. If he (the victim) be of a people hostile unto you, and he is a believer, then (the penance is) to set free a believing slave. And if he cometh of a folk between whom and you there is a covenant, then the blood-money must be paid unto his folk and (also) a believing slave must be set free. And whoso hath not the wherewithal must fast two consecutive months. A penance from Allah. Allah is Knower, Wise.'),
  ('en.pickthall', 4, 93, 'Whoso slayeth a believer of set purpose, his reward is hell for ever. Allah is wroth against him and He hath cursed him and prepared for him an awful doom.'),
  ('en.pickthall', 4, 94, 'O ye who believe! When ye go forth (to fight) in the way of Allah, be careful to discriminate, and say not unto one who offereth you peace: "Thou art not a believer," seeking the chance profits of this life (so that ye may despoil him). With Allah are plenteous spoils. Even thus (as he now is) were ye before; but Allah hath since then been gracious unto you. Therefore take care to discriminate. Allah is ever Informed of what ye do.'),
  ('en.pickthall', 4, 95, 'Those of the believers who sit still, other than those who have a (disabling) hurt, are not on an equality with those who strive in the way of Allah with their wealth and lives. Allah hath conferred on those who strive with their wealth and lives a rank above the sedentary. Unto each Allah hath promised good, but He hath bestowed on those who strive a great reward above the sedentary;'),
  ('en.pickthall', 4, 96, 'Degrees of rank from Him, and forgiveness and mercy. Allah is ever Forgiving, Merciful.'),
  ('en.pickthall', 4, 97, 'Lo! as for those whom the angels take (in death) while they wrong themselves, (the angels) will ask: In what were ye engaged? They will say: We were oppressed in the land. (The angels) will say: Was not Allah\'s earth spacious that ye could have migrated therein? As for such, their habitation will be hell, an evil journey\'s end;'),
  ('en.pickthall', 4, 98, 'Except the feeble among men, and the women, and the children, who are unable to devise a plan and are not shown a way.'),
  ('en.pickthall', 4, 99, 'As for such, it may be that Allah will pardon them. Allah is ever Clement, Forgiving.'),
  ('en.pickthall', 4, 100, 'Whoso migrateth for the cause of Allah will find much refuge and abundance in the earth, and whoso forsaketh his home, a fugitive unto Allah and His messenger, and death overtaketh him, his reward is then incumbent on Allah. Allah is ever Forgiving, Merciful.'),
  ('en.pickthall', 4, 101, 'And when ye go forth in the land, it is no sin for you to curtail (your) worship if ye fear that those who disbelieve may attack you. In truth the disbelievers are an open enemy to you.'),
  ('en.pickthall', 4, 102, 'And when thou (O Muhammad) art among them and arrangest (their) worship for them, let only a party of them stand with thee (to worship) and let them take their arms. Then when they have performed their prostrations let them fall to the rear and let another party come that hath not worshipped and let them worship with thee, and let them take their precaution and their arms. Those who disbelieve long for you to neglect your arms and your baggage that they may attack you once for all. It is no sin for you to lay aside your arms, if rain impedeth you or ye are sick. But take your precaution. Lo! Allah prepareth for the disbelievers shameful punishment.'),
  ('en.pickthall', 4, 103, 'When ye have performed the act of worship, remember Allah, standing, sitting and reclining. And when ye are in safety, observe proper worship. Worship at fixed times hath been enjoined on the believers.'),
  ('en.pickthall', 4, 104, 'Relent not in pursuit of the enemy. If ye are suffering, lo! they suffer even as ye suffer and ye hope from Allah that for which they cannot hope. Allah is ever Knower, Wise.'),
  ('en.pickthall', 4, 105, 'Lo! We reveal unto thee the Scripture with the truth, that thou mayst judge between mankind by that which Allah showeth thee. And be not thou a pleader for the treacherous;'),
  ('en.pickthall', 4, 106, 'And seek forgiveness of Allah. Lo! Allah is ever Forgiving, Merciful.'),
  ('en.pickthall', 4, 107, 'And plead not on behalf of (people) who deceive themselves. Lo! Allah loveth not one who is treacherous and sinful.'),
  ('en.pickthall', 4, 108, 'They seek to hide from men and seek not to hide from Allah. He is with them when by night they hold discourse displeasing unto Him. Allah ever surroundeth what they do.'),
  ('en.pickthall', 4, 109, 'Ho! ye are they who pleaded for them in the life of the world. But who will plead with Allah for them on the Day of Resurrection, or who will then be their defender?'),
  ('en.pickthall', 4, 110, 'Yet whoso doeth evil or wrongeth his own soul, then seeketh pardon of Allah, will find Allah Forgiving, Merciful.'),
  ('en.pickthall', 4, 111, 'Whoso committeth sin committeth it only against himself. Allah is ever Knower, Wise.'),
  ('en.pickthall', 4, 112, 'And whoso committeth a delinquency or crime, then throweth (the blame) thereof upon the innocent, hath burdened himself with falsehood and a flagrant crime.'),
  ('en.pickthall', 4, 113, 'But for the grace of Allah upon thee (Muhammad), and His mercy, a party of them had resolved to mislead thee, but they will mislead only themselves and they will hurt thee not at all. Allah revealeth unto thee the Scripture and wisdom, and teacheth thee that which thou knewest not. The grace of Allah toward thee hath been infinite.'),
  ('en.pickthall', 4, 114, 'There is no good in much of their secret conferences save (in) him who enjoineth almsgiving and kindness and peace-making among the people. Whoso doeth that, seeking the good pleasure of Allah, We shall bestow on him a vast reward.'),
  ('en.pickthall', 4, 115, 'And whoso opposeth the messenger after the guidance (of Allah) hath been manifested unto him, and followeth other than the believer\'s way, We appoint for him that unto which he himself hath turned, and expose him unto hell - a hapless journey\'s end!'),
  ('en.pickthall', 4, 116, 'Lo! Allah pardoneth not that partners should be ascribed unto Him. He pardoneth all save that to whom He will. Whoso ascribeth partners unto Allah hath wandered far astray.'),
  ('en.pickthall', 4, 117, 'They invoke in His stead only females; they pray to none else than Satan, a rebel'),
  ('en.pickthall', 4, 118, 'Whom Allah cursed, and he said: Surely I will take of Thy bondmen an appointed portion,'),
  ('en.pickthall', 4, 119, 'And surely I will lead them astray, and surely I will arouse desires in them, and surely I will command them and they will cut the cattle\' ears, and surely I will command them and they will change Allah\'s creation. Whoso chooseth Satan for a patron instead of Allah is verily a loser and his loss is manifest.'),
  ('en.pickthall', 4, 120, 'He promiseth them and stirreth up desires in them, and Satan promiseth them only to beguile.'),
  ('en.pickthall', 4, 121, 'For such, their habitation will be hell, and they will find no refuge therefrom.'),
  ('en.pickthall', 4, 122, 'But as for those who believe and do good works We shall bring them into Gardens underneath which rivers flow, wherein they will abide for ever. It is a promise from Allah in truth; and who can be more truthful than Allah in utterance?'),
  ('en.pickthall', 4, 123, 'It will not be in accordance with your desires, nor the desires of the People of the Scripture. He who doeth wrong will have the recompense thereof, and will not find against Allah any protecting friend or helper.'),
  ('en.pickthall', 4, 124, 'And whoso doeth good works, whether of male or female, and he (or she) is a believer, such will enter paradise and they will not be wronged the dint in a date-stone.'),
  ('en.pickthall', 4, 125, 'Who is better in religion than he who surrendereth his purpose to Allah while doing good (to men) and followeth the tradition of Abraham, the upright? Allah (Himself) chose Abraham for friend.'),
  ('en.pickthall', 4, 126, 'Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth. Allah ever surroundeth all things.'),
  ('en.pickthall', 4, 127, 'They consult thee concerning women. Say: Allah giveth you decree concerning them, and the Scripture which hath been recited unto you (giveth decree), concerning female orphans and those unto whom ye give not that which is ordained for them though ye desire to marry them, and (concerning) the weak among children, and that ye should deal justly with orphans. Whatever good ye do, lo! Allah is ever Aware of it.'),
  ('en.pickthall', 4, 128, 'If a woman feareth ill treatment from her husband, or desertion, it is no sin for them twain if they make terms of peace between themselves. Peace is better. But greed hath been made present in the minds (of men). If ye do good and keep from evil, lo! Allah is ever Informed of what ye do.'),
  ('en.pickthall', 4, 129, 'Ye will not be able to deal equally between (your) wives, however much ye wish (to do so). But turn not altogether away (from one), leaving her as in suspense. If ye do good and keep from evil, lo! Allah is ever Forgiving, Merciful.'),
  ('en.pickthall', 4, 130, 'But if they separate, Allah will compensate each out of His abundance. Allah is ever All-Embracing, All-Knowing.'),
  ('en.pickthall', 4, 131, 'Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth. And We charged those who received the Scripture before you, and (We charge) you, that ye keep your duty toward Allah. And if ye disbelieve, lo! unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth, and Allah is ever Absolute, Owner of Praise.'),
  ('en.pickthall', 4, 132, 'Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth. And Allah is sufficient as Defender.'),
  ('en.pickthall', 4, 133, 'If He will, He can remove you, O people, and produce others (in your stead). Allah is Able to do that.'),
  ('en.pickthall', 4, 134, 'Whoso desireth the reward of the world, (let him know that) with Allah is the reward of the world and the Hereafter. Allah is ever Hearer, Seer.'),
  ('en.pickthall', 4, 135, 'O ye who believe! Be ye staunch in justice, witnesses for Allah, even though it be against yourselves or (your) parents or (your) kindred, whether (the case be of) a rich man or a poor man, for Allah is nearer unto both (them ye are). So follow not passion lest ye lapse (from truth) and if ye lapse or fall away, then lo! Allah is ever Informed of what ye do.'),
  ('en.pickthall', 4, 136, 'O ye who believe! Believe in Allah and His messenger and the Scripture which He hath revealed unto His messenger, and the Scripture which He revealed aforetime. Whoso disbelieveth in Allah and His angels and His scriptures and His messengers and the Last Day, he verily hath wandered far astray.'),
  ('en.pickthall', 4, 137, 'Lo! those who believe, then disbelieve and then (again) believe, then disbelieve, and then increase in disbelief, Allah will never pardon them, nor will He guide them unto a way.'),
  ('en.pickthall', 4, 138, 'Bear unto the hypocrites the tidings that for them there is a painful doom;'),
  ('en.pickthall', 4, 139, 'Those who chose disbelievers for their friends instead of believers! Do they look for power at their hands? Lo! all power appertaineth to Allah.'),
  ('en.pickthall', 4, 140, 'He hath already revealed unto you in the Scripture that, when ye hear the revelations of Allah rejected and derided, (ye) sit not with them (who disbelieve and mock) until they engage in some other conversation. Lo! in that case (if ye stayed) ye would be like unto them. Lo! Allah will gather hypocrites and disbelievers, all together, into hell;'),
  ('en.pickthall', 4, 141, 'Those who wait upon occasion in regard to you and, if a victory cometh unto you from Allah, say: Are we not with you? and if the disbelievers meet with a success say: Had we not the mastery of you, and did we not protect you from the believers? - Allah will judge between you at the Day of Resurrection, and Allah will not give the disbelievers any way (of success) against the believers.'),
  ('en.pickthall', 4, 142, 'Lo! the hypocrites seek to beguile Allah, but it is He Who beguileth them. When they stand up to worship they perform it languidly and to be seen of men, and are mindful of Allah but little;'),
  ('en.pickthall', 4, 143, 'Swaying between this (and that), (belonging) neither to these nor to those. He whom Allah causeth to go astray, thou (O Muhammad) wilt not find a way for him:'),
  ('en.pickthall', 4, 144, 'O ye who believe! Choose not disbelievers for (your) friends in place of believers. Would ye give Allah a clear warrant against you?'),
  ('en.pickthall', 4, 145, 'Lo! the hypocrites (will be) in the lowest deep of the Fire, and thou wilt find no helper for them;'),
  ('en.pickthall', 4, 146, 'Save those who repent and amend and hold fast to Allah and make their religion pure for Allah (only). Those are with the believers. And Allah will bestow on the believers an immense reward.'),
  ('en.pickthall', 4, 147, 'What concern hath Allah for your punishment if ye are thankful (for His mercies) and believe (in Him)? Allah was ever Responsive, Aware.'),
  ('en.pickthall', 4, 148, 'Allah loveth not the utterance of harsh speech save by one who hath been wronged. Allah is ever Hearer, Knower.'),
  ('en.pickthall', 4, 149, 'If ye do good openly or keep it secret, or forgive evil, lo! Allah is ever Forgiving, Powerful.'),
  ('en.pickthall', 4, 150, 'Lo! those who disbelieve in Allah and His messengers, and seek to make distinction between Allah and His messengers, and say: We believe in some and disbelieve in others, and seek to choose a way in between;'),
  ('en.pickthall', 4, 151, 'Such are disbelievers in truth; and for disbelievers We prepare a shameful doom.'),
  ('en.pickthall', 4, 152, 'But those who believe in Allah and His messengers and make no distinction between any of them, unto them Allah will give their wages; and Allah was ever Forgiving, Merciful.'),
  ('en.pickthall', 4, 153, 'The people of the Scripture ask of thee that thou shouldst cause an (actual) Book to descend upon them from heaven. They asked a greater thing of Moses aforetime, for they said: Show us Allah plainly. The storm of lightning seized them for their wickedness. Then (even) after that) they chose the calf (for worship) after clear proofs (of Allah\'s Sovereignty) had come unto them. And We forgave them that! And We bestowed on Moses evident authority.'),
  ('en.pickthall', 4, 154, 'And We caused the Mount to tower above them at (the taking of) their covenant: and We bade them: Enter the gate, prostrate! and We bode them: Transgress not the Sabbath! and We took from them a firm covenant.'),
  ('en.pickthall', 4, 155, 'Then because of their breaking of their covenant, and their disbelieving in the revelations of Allah, and their slaying of the prophets wrongfully, and their saying: Our hearts are hardened - Nay, but Allah set a seal upon them for their disbelief, so that they believe not save a few -'),
  ('en.pickthall', 4, 156, 'And because of their disbelief and of their speaking against Mary a tremendous calumny;'),
  ('en.pickthall', 4, 157, 'And because of their saying: We slew the Messiah, Jesus son of Mary, Allah\'s messenger - they slew him not nor crucified him, but it appeared so unto them; and lo! those who disagree concerning it are in doubt thereof; they have no knowledge thereof save pursuit of a conjecture; they slew him not for certain.'),
  ('en.pickthall', 4, 158, 'But Allah took him up unto Himself. Allah was ever Mighty, Wise.'),
  ('en.pickthall', 4, 159, 'There is not one of the People of the Scripture but will believe in him before his death, and on the Day of Resurrection he will be a witness against them -'),
  ('en.pickthall', 4, 160, 'Because of the wrongdoing of the Jews We forbade them good things which were (before) made lawful unto them, and because of their much hindering from Allah\'s way,'),
  ('en.pickthall', 4, 161, 'And of their taking usury when they were forbidden it, and of their devouring people\'s wealth by false pretences, We have prepared for those of them who disbelieve a painful doom.'),
  ('en.pickthall', 4, 162, 'But those of them who are firm in knowledge and the believers believe in that which is revealed unto thee, and that which was revealed before thee, especially the diligent in prayer and those who pay the poor-due, the believers in Allah and the Last Day. Upon these We shall bestow immense reward.'),
  ('en.pickthall', 4, 163, 'Lo! We inspire thee as We inspired Noah and the prophets after him, as We inspired Abraham and Ishmael and Isaac and Jacob and the tribes, and Jesus and Job and Jonah and Aaron and Solomon, and as We imparted unto David the Psalms;'),
  ('en.pickthall', 4, 164, 'And messengers We have mentioned unto thee before and messengers We have not mentioned unto thee; and Allah spake directly unto Moses;'),
  ('en.pickthall', 4, 165, 'Messengers of good cheer and of warning, in order that mankind might have no argument against Allah after the messengers. Allah was ever Mighty, Wise.'),
  ('en.pickthall', 4, 166, 'But Allah (Himself) testifieth concerning that which He hath revealeth unto thee; in His knowledge hath He revealed it; and the angels also testify. And Allah is sufficient Witness.'),
  ('en.pickthall', 4, 167, 'Lo! those who disbelieve and hinder (others) from the way of Allah, they verily have wandered far astray.'),
  ('en.pickthall', 4, 168, 'Lo! those who disbelieve and deal in wrong, Allah will never forgive them, neither will He guide them unto a road,'),
  ('en.pickthall', 4, 169, 'Except the road of hell, wherein they will abide for ever. And that is ever easy for Allah.'),
  ('en.pickthall', 4, 170, 'O mankind! The messenger hath come unto you with the Truth from your Lord. Therefor believe; (it is) better for you. But if ye disbelieve, still, lo! unto Allah belongeth whatsoever is in the heavens and the earth. Allah is ever Knower, Wise.'),
  ('en.pickthall', 4, 171, 'O People of the Scripture! Do not exaggerate in your religion nor utter aught concerning Allah save the truth. The Messiah, Jesus son of Mary, was only a messenger of Allah, and His word which He conveyed unto Mary, and a spirit from Him. So believe in Allah and His messengers, and say not "Three" - Cease! (it is) better for you! - Allah is only One Allah. Far is it removed from His Transcendent Majesty that He should have a son. His is all that is in the heavens and all that is in the earth. And Allah is sufficient as Defender.'),
  ('en.pickthall', 4, 172, 'The Messiah will never scorn to be a slave unto Allah, nor will the favoured angels. Whoso scorneth His service and is proud, all such will He assemble unto Him;'),
  ('en.pickthall', 4, 173, 'Then, as for those who believed and did good works, unto them will He pay their wages in full, adding unto them of His bounty; and as for those who were scornful and proud, them will He punish with a painful doom. And they will not find for them, against Allah, any protecting friend or helper.'),
  ('en.pickthall', 4, 174, 'O mankind! Now hath a proof from your Lord come unto you, and We have sent down unto you a clear light;'),
  ('en.pickthall', 4, 175, 'As for those who believe in Allah, and hold fast unto Him, them He will cause to enter into His mercy and grace, and will guide them unto Him by a straight road.'),
  ('en.pickthall', 4, 176, 'They ask thee for a pronouncement. Say: Allah hath pronounced for you concerning distant kindred. If a man die childless and he have a sister, hers is half the heritage, and he would have inherited from her had she died childless. And if there be two sisters, then theirs are two-thirds of the heritage, and if they be brethren, men and women, unto the male is the equivalent of the share of two females. Allah expoundeth unto you, so that ye err not. Allah is Knower of all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 4, 1, 'O mankind! reverence your Guardian-Lord, who created you from a single person, created, of like nature, His mate, and from them twain scattered (like seeds) countless men and women;- reverence Allah, through whom ye demand your mutual (rights), and (reverence) the wombs (That bore you): for Allah ever watches over you.'),
  ('en.yusufali', 4, 2, 'To orphans restore their property (When they reach their age), nor substitute (your) worthless things for (their) good ones; and devour not their substance (by mixing it up) with your own. For this is indeed a great sin.'),
  ('en.yusufali', 4, 3, 'If ye fear that ye shall not be able to deal justly with the orphans, Marry women of your choice, Two or three or four; but if ye fear that ye shall not be able to deal justly (with them), then only one, or (a captive) that your right hands possess, that will be more suitable, to prevent you from doing injustice.'),
  ('en.yusufali', 4, 4, 'And give the women (on marriage) their dower as a free gift; but if they, of their own good pleasure, remit any part of it to you, Take it and enjoy it with right good cheer.'),
  ('en.yusufali', 4, 5, 'To those weak of understanding Make not over your property, which Allah hath made a means of support for you, but feed and clothe them therewith, and speak to them words of kindness and justice.'),
  ('en.yusufali', 4, 6, 'Make trial of orphans until they reach the age of marriage; if then ye find sound judgment in them, release their property to them; but consume it not wastefully, nor in haste against their growing up. If the guardian is well-off, Let him claim no remuneration, but if he is poor, let him have for himself what is just and reasonable. When ye release their property to them, take witnesses in their presence: But all-sufficient is Allah in taking account.'),
  ('en.yusufali', 4, 7, 'From what is left by parents and those nearest related there is a share for men and a share for women, whether the property be small or large,-a determinate share.'),
  ('en.yusufali', 4, 8, 'But if at the time of division other relatives, or orphans or poor, are present, feed them out of the (property), and speak to them words of kindness and justice.'),
  ('en.yusufali', 4, 9, 'Let those (disposing of an estate) have the same fear in their minds as they would have for their own if they had left a helpless family behind: Let them fear Allah, and speak words of appropriate (comfort).'),
  ('en.yusufali', 4, 10, 'Those who unjustly eat up the property of orphans, eat up a Fire into their own bodies: They will soon be enduring a Blazing Fire!'),
  ('en.yusufali', 4, 11, 'Allah (thus) directs you as regards your Children\'s (Inheritance): to the male, a portion equal to that of two females: if only daughters, two or more, their share is two-thirds of the inheritance; if only one, her share is a half. For parents, a sixth share of the inheritance to each, if the deceased left children; if no children, and the parents are the (only) heirs, the mother has a third; if the deceased Left brothers (or sisters) the mother has a sixth. (The distribution in all cases (\'s) after the payment of legacies and debts. Ye know not whether your parents or your children are nearest to you in benefit. These are settled portions ordained by Allah; and Allah is All-knowing, Al-wise.'),
  ('en.yusufali', 4, 12, 'In what your wives leave, your share is a half, if they leave no child; but if they leave a child, ye get a fourth; after payment of legacies and debts. In what ye leave, their share is a fourth, if ye leave no child; but if ye leave a child, they get an eighth; after payment of legacies and debts. If the man or woman whose inheritance is in question, has left neither ascendants nor descendants, but has left a brother or a sister, each one of the two gets a sixth; but if more than two, they share in a third; after payment of legacies and debts; so that no loss is caused (to any one). Thus is it ordained by Allah; and Allah is All-knowing, Most Forbearing.'),
  ('en.yusufali', 4, 13, 'Those are limits set by Allah: those who obey Allah and His Messenger will be admitted to Gardens with rivers flowing beneath, to abide therein (for ever) and that will be the supreme achievement.'),
  ('en.yusufali', 4, 14, 'But those who disobey Allah and His Messenger and transgress His limits will be admitted to a Fire, to abide therein: And they shall have a humiliating punishment.'),
  ('en.yusufali', 4, 15, 'If any of your women are guilty of lewdness, Take the evidence of four (Reliable) witnesses from amongst you against them; and if they testify, confine them to houses until death do claim them, or Allah ordain for them some (other) way.'),
  ('en.yusufali', 4, 16, 'If two men among you are guilty of lewdness, punish them both. If they repent and amend, Leave them alone; for Allah is Oft-returning, Most Merciful.'),
  ('en.yusufali', 4, 17, 'Allah accept the repentance of those who do evil in ignorance and repent soon afterwards; to them will Allah turn in mercy: For Allah is full of knowledge and wisdom.'),
  ('en.yusufali', 4, 18, 'Of no effect is the repentance of those who continue to do evil, until death faces one of them, and he says, "Now have I repented indeed;" nor of those who die rejecting Faith: for them have We prepared a punishment most grievous.'),
  ('en.yusufali', 4, 19, 'O ye who believe! Ye are forbidden to inherit women against their will. Nor should ye treat them with harshness, that ye may Take away part of the dower ye have given them,-except where they have been guilty of open lewdness; on the contrary live with them on a footing of kindness and equity. If ye take a dislike to them it may be that ye dislike a thing, and Allah brings about through it a great deal of good.'),
  ('en.yusufali', 4, 20, 'But if ye decide to take one wife in place of another, even if ye had given the latter a whole treasure for dower, Take not the least bit of it back: Would ye take it by slander and manifest wrong?'),
  ('en.yusufali', 4, 21, 'And how could ye take it when ye have gone in unto each other, and they have Taken from you a solemn covenant?'),
  ('en.yusufali', 4, 22, 'And marry not women whom your fathers married,- except what is past: It was shameful and odious,- an abominable custom indeed.'),
  ('en.yusufali', 4, 23, 'Prohibited to you (For marriage) are:- Your mothers, daughters, sisters; father\'s sisters, Mother\'s sisters; brother\'s daughters, sister\'s daughters; foster-mothers (Who gave you suck), foster-sisters; your wives\' mothers; your step-daughters under your guardianship, born of your wives to whom ye have gone in,- no prohibition if ye have not gone in;- (Those who have been) wives of your sons proceeding from your loins; and two sisters in wedlock at one and the same time, except for what is past; for Allah is Oft-forgiving, Most Merciful;-'),
  ('en.yusufali', 4, 24, 'Also (prohibited are) women already married, except those whom your right hands possess: Thus hath Allah ordained (Prohibitions) against you: Except for these, all others are lawful, provided ye seek (them in marriage) with gifts from your property,- desiring chastity, not lust, seeing that ye derive benefit from them, give them their dowers (at least) as prescribed; but if, after a dower is prescribed, agree Mutually (to vary it), there is no blame on you, and Allah is All-knowing, All-wise.'),
  ('en.yusufali', 4, 25, 'If any of you have not the means wherewith to wed free believing women, they may wed believing girls from among those whom your right hands possess: And Allah hath full knowledge about your faith. Ye are one from another: Wed them with the leave of their owners, and give them their dowers, according to what is reasonable: They should be chaste, not lustful, nor taking paramours: when they are taken in wedlock, if they fall into shame, their punishment is half that for free women. This (permission) is for those among you who fear sin; but it is better for you that ye practise self-restraint. And Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 4, 26, 'Allah doth wish to make clear to you and to show you the ordinances of those before you; and (He doth wish to) turn to you (In Mercy): And Allah is All-knowing, All-wise.'),
  ('en.yusufali', 4, 27, 'Allah doth wish to Turn to you, but the wish of those who follow their lusts is that ye should turn away (from Him),- far, far away.'),
  ('en.yusufali', 4, 28, 'Allah doth wish to lighten your (difficulties): For man was created Weak (in flesh).'),
  ('en.yusufali', 4, 29, 'O ye who believe! Eat not up your property among yourselves in vanities: But let there be amongst you Traffic and trade by mutual good-will: Nor kill (or destroy) yourselves: for verily Allah hath been to you Most Merciful!'),
  ('en.yusufali', 4, 30, 'If any do that in rancour and injustice,- soon shall We cast them into the Fire: And easy it is for Allah.'),
  ('en.yusufali', 4, 31, 'If ye (but) eschew the most heinous of the things which ye are forbidden to do, We shall expel out of you all the evil in you, and admit you to a gate of great honour.'),
  ('en.yusufali', 4, 32, 'And in no wise covet those things in which Allah Hath bestowed His gifts More freely on some of you than on others: To men is allotted what they earn, and to women what they earn: But ask Allah of His bounty. For Allah hath full knowledge of all things.'),
  ('en.yusufali', 4, 33, 'To (benefit) every one, We have appointed shares and heirs to property left by parents and relatives. To those, also, to whom your right hand was pledged, give their due portion. For truly Allah is witness to all things.'),
  ('en.yusufali', 4, 34, 'Men are the protectors and maintainers of women, because Allah has given the one more (strength) than the other, and because they support them from their means. Therefore the righteous women are devoutly obedient, and guard in (the husband\'s) absence what Allah would have them guard. As to those women on whose part ye fear disloyalty and ill-conduct, admonish them (first), (Next), refuse to share their beds, (And last) beat them (lightly); but if they return to obedience, seek not against them Means (of annoyance): For Allah is Most High, great (above you all).'),
  ('en.yusufali', 4, 35, 'If ye fear a breach between them twain, appoint (two) arbiters, one from his family, and the other from hers; if they wish for peace, Allah will cause their reconciliation: For Allah hath full knowledge, and is acquainted with all things.'),
  ('en.yusufali', 4, 36, 'Serve Allah, and join not any partners with Him; and do good- to parents, kinsfolk, orphans, those in need, neighbours who are near, neighbours who are strangers, the companion by your side, the wayfarer (ye meet), and what your right hands possess: For Allah loveth not the arrogant, the vainglorious;-'),
  ('en.yusufali', 4, 37, '(Nor) those who are niggardly or enjoin niggardliness on others, or hide the bounties which Allah hath bestowed on them; for We have prepared, for those who resist Faith, a punishment that steeps them in contempt;-'),
  ('en.yusufali', 4, 38, 'Not those who spend of their substance, to be seen of men, but have no faith in Allah and the Last Day: If any take the Evil One for their intimate, what a dreadful intimate he is!'),
  ('en.yusufali', 4, 39, 'And what burden Were it on them if they had faith in Allah and in the Last Day, and they spent out of what Allah hath given them for sustenance? For Allah hath full knowledge of them.'),
  ('en.yusufali', 4, 40, 'Allah is never unjust in the least degree: If there is any good (done), He doubleth it, and giveth from His own presence a great reward.'),
  ('en.yusufali', 4, 41, 'How then if We brought from each people a witness, and We brought thee as a witness against these people!'),
  ('en.yusufali', 4, 42, 'On that day those who reject Faith and disobey the messenger will wish that the earth Were made one with them: But never will they hide a single fact from Allah!'),
  ('en.yusufali', 4, 43, 'O ye who believe! Approach not prayers with a mind befogged, until ye can understand all that ye say,- nor in a state of ceremonial impurity (Except when travelling on the road), until after washing your whole body. If ye are ill, or on a journey, or one of you cometh from offices of nature, or ye have been in contact with women, and ye find no water, then take for yourselves clean sand or earth, and rub therewith your faces and hands. For Allah doth blot out sins and forgive again and again.'),
  ('en.yusufali', 4, 44, 'Hast thou not turned Thy vision to those who were given a portion of the Book? they traffic in error, and wish that ye should lose the right path.'),
  ('en.yusufali', 4, 45, 'But Allah hath full knowledge of your enemies: Allah is enough for a protector, and Allah is enough for a Helper.'),
  ('en.yusufali', 4, 46, 'Of the Jews there are those who displace words from their (right) places, and say: "We hear and we disobey"; and "Hear what is not Heard"; and "Ra\'ina"; with a twist of their tongues and a slander to Faith. If only they had said: "What hear and we obey"; and "Do hear"; and "Do look at us"; it would have been better for them, and more proper; but Allah hath cursed them for their Unbelief; and but few of them will believe.'),
  ('en.yusufali', 4, 47, 'O ye People of the Book! believe in what We have (now) revealed, confirming what was (already) with you, before We change the face and fame of some (of you) beyond all recognition, and turn them hindwards, or curse them as We cursed the Sabbath-breakers, for the decision of Allah Must be carried out.'),
  ('en.yusufali', 4, 48, 'Allah forgiveth not that partners should be set up with Him; but He forgiveth anything else, to whom He pleaseth; to set up partners with Allah is to devise a sin Most heinous indeed.'),
  ('en.yusufali', 4, 49, 'Hast thou not turned Thy vision to those who claim sanctity for themselves? Nay-but Allah Doth sanctify whom He pleaseth. But never will they fail to receive justice in the least little thing.'),
  ('en.yusufali', 4, 50, 'Behold! how they invent a lie against Allah! but that by itself is a manifest sin!'),
  ('en.yusufali', 4, 51, 'Hast thou not turned Thy vision to those who were given a portion of the Book? they believe in sorcery and Evil, and say to the Unbelievers that they are better guided in the (right) way Than the believers!'),
  ('en.yusufali', 4, 52, 'They are (men) whom Allah hath cursed: And those whom Allah Hath cursed, thou wilt find, have no one to help.'),
  ('en.yusufali', 4, 53, 'Have they a share in dominion or power? Behold, they give not a farthing to their fellow-men?'),
  ('en.yusufali', 4, 54, 'Or do they envy mankind for what Allah hath given them of his bounty? but We had already given the people of Abraham the Book and Wisdom, and conferred upon them a great kingdom.'),
  ('en.yusufali', 4, 55, 'Some of them believed, and some of them averted their faces from him: And enough is Hell for a burning fire.'),
  ('en.yusufali', 4, 56, 'Those who reject our Signs, We shall soon cast into the Fire: as often as their skins are roasted through, We shall change them for fresh skins, that they may taste the penalty: for Allah is Exalted in Power, Wise.'),
  ('en.yusufali', 4, 57, 'But those who believe and do deeds of righteousness, We shall soon admit to Gardens, with rivers flowing beneath,- their eternal home: Therein shall they have companions pure and holy: We shall admit them to shades, cool and ever deepening.'),
  ('en.yusufali', 4, 58, 'Allah doth command you to render back your Trusts to those to whom they are due; And when ye judge between man and man, that ye judge with justice: Verily how excellent is the teaching which He giveth you! For Allah is He Who heareth and seeth all things.'),
  ('en.yusufali', 4, 59, 'O ye who believe! Obey Allah, and obey the Messenger, and those charged with authority among you. If ye differ in anything among yourselves, refer it to Allah and His Messenger, if ye do believe in Allah and the Last Day: That is best, and most suitable for final determination.'),
  ('en.yusufali', 4, 60, 'Hast thou not turned Thy vision to those who declare that they believe in the revelations that have come to thee and to those before thee? Their (real) wish is to resort together for judgment (in their disputes) to the Evil One, though they were ordered to reject him. But Satan\'s wish is to lead them astray far away (from the right).'),
  ('en.yusufali', 4, 61, 'When it is said to them: "Come to what Allah hath revealed, and to the Messenger": Thou seest the Hypocrites avert their faces from thee in disgust.'),
  ('en.yusufali', 4, 62, 'How then, when they are seized by misfortune, because of the deeds which they hands have sent forth? Then their come to thee, swearing by Allah: "We meant no more than good-will and conciliation!"'),
  ('en.yusufali', 4, 63, 'Those men,-Allah knows what is in their hearts; so keep clear of them, but admonish them, and speak to them a word to reach their very souls.'),
  ('en.yusufali', 4, 64, 'We sent not a messenger, but to be obeyed, in accordance with the will of Allah. If they had only, when they were unjust to themselves, come unto thee and asked Allah\'s forgiveness, and the Messenger had asked forgiveness for them, they would have found Allah indeed Oft-returning, Most Merciful.'),
  ('en.yusufali', 4, 65, 'But no, by the Lord, they can have no (real) Faith, until they make thee judge in all disputes between them, and find in their souls no resistance against Thy decisions, but accept them with the fullest conviction.'),
  ('en.yusufali', 4, 66, 'If We had ordered them to sacrifice their lives or to leave their homes, very few of them would have done it: But if they had done what they were (actually) told, it would have been best for them, and would have gone farthest to strengthen their (faith);'),
  ('en.yusufali', 4, 67, 'And We should then have given them from our presence a great reward;'),
  ('en.yusufali', 4, 68, 'And We should have shown them the Straight Way.'),
  ('en.yusufali', 4, 69, 'All who obey Allah and the messenger are in the company of those on whom is the Grace of Allah,- of the prophets (who teach), the sincere (lovers of Truth), the witnesses (who testify), and the Righteous (who do good): Ah! what a beautiful fellowship!'),
  ('en.yusufali', 4, 70, 'Such is the bounty from Allah: And sufficient is it that Allah knoweth all.'),
  ('en.yusufali', 4, 71, 'O ye who believe! Take your precautions, and either go forth in parties or go forth all together.'),
  ('en.yusufali', 4, 72, 'There are certainly among you men who would tarry behind: If a misfortune befalls you, they say: "Allah did favour us in that we were not present among them."'),
  ('en.yusufali', 4, 73, 'But if good fortune comes to you from Allah, they would be sure to say - as if there had never been Ties of affection between you and them - "Oh! I wish I had been with them; a fine thing should I then have made of it!"'),
  ('en.yusufali', 4, 74, 'Let those fight in the cause of Allah Who sell the life of this world for the hereafter. To him who fighteth in the cause of Allah,- whether he is slain or gets victory - Soon shall We give him a reward of great (value).'),
  ('en.yusufali', 4, 75, 'And why should ye not fight in the cause of Allah and of those who, being weak, are ill-treated (and oppressed)?- Men, women, and children, whose cry is: "Our Lord! Rescue us from this town, whose people are oppressors; and raise for us from thee one who will protect; and raise for us from thee one who will help!"'),
  ('en.yusufali', 4, 76, 'Those who believe fight in the cause of Allah, and those who reject Faith Fight in the cause of Evil: So fight ye against the friends of Satan: feeble indeed is the cunning of Satan.'),
  ('en.yusufali', 4, 77, 'Hast thou not turned Thy vision to those who were told to hold back their hands (from fight) but establish regular prayers and spend in regular charity? When (at length) the order for fighting was issued to them, behold! a section of them feared men as - or even more than - they should have feared Allah: They said: "Our Lord! Why hast Thou ordered us to fight? Wouldst Thou not Grant us respite to our (natural) term, near (enough)?" Say: "Short is the enjoyment of this world: the Hereafter is the best for those who do right: Never will ye be dealt with unjustly in the very least!'),
  ('en.yusufali', 4, 78, '"Wherever ye are, death will find you out, even if ye are in towers built up strong and high!" If some good befalls them, they say, "This is from Allah"; but if evil, they say, "This is from thee" (O Prophet). Say: "All things are from Allah." But what hath come to these people, that they fail to understand a single fact?'),
  ('en.yusufali', 4, 79, 'Whatever good, (O man!) happens to thee, is from Allah; but whatever evil happens to thee, is from thy (own) soul. and We have sent thee as a messenger to (instruct) mankind. And enough is Allah for a witness.'),
  ('en.yusufali', 4, 80, 'He who obeys the Messenger, obeys Allah: But if any turn away, We have not sent thee to watch over their (evil deeds).'),
  ('en.yusufali', 4, 81, 'They have "Obedience" on their lips; but when they leave thee, a section of them Meditate all night on things very different from what thou tellest them. But Allah records their nightly (plots): So keep clear of them, and put thy trust in Allah, and enough is Allah as a disposer of affairs.'),
  ('en.yusufali', 4, 82, 'Do they not consider the Qur\'an (with care)? Had it been from other Than Allah, they would surely have found therein Much discrepancy.'),
  ('en.yusufali', 4, 83, 'When there comes to them some matter touching (Public) safety or fear, they divulge it. If they had only referred it to the Messenger, or to those charged with authority among them, the proper investigators would have Tested it from them (direct). Were it not for the Grace and Mercy of Allah unto you, all but a few of you would have fallen into the clutches of Satan.'),
  ('en.yusufali', 4, 84, 'Then fight in Allah\'s cause - Thou art held responsible only for thyself - and rouse the believers. It may be that Allah will restrain the fury of the Unbelievers; for Allah is the strongest in might and in punishment.'),
  ('en.yusufali', 4, 85, 'Whoever recommends and helps a good cause becomes a partner therein: And whoever recommends and helps an evil cause, shares in its burden: And Allah hath power over all things.'),
  ('en.yusufali', 4, 86, 'When a (courteous) greeting is offered you, meet it with a greeting still more courteous, or (at least) of equal courtesy. Allah takes careful account of all things.'),
  ('en.yusufali', 4, 87, 'Allah! There is no god but He: of a surety He will gather you together against the Day of Judgment, about which there is no doubt. And whose word can be truer than Allah\'s?'),
  ('en.yusufali', 4, 88, 'Why should ye be divided into two parties about the Hypocrites? Allah hath upset them for their (evil) deeds. Would ye guide those whom Allah hath thrown out of the Way? For those whom Allah hath thrown out of the Way, never shalt thou find the Way.'),
  ('en.yusufali', 4, 89, 'They but wish that ye should reject Faith, as they do, and thus be on the same footing (as they): But take not friends from their ranks until they flee in the way of Allah (From what is forbidden). But if they turn renegades, seize them and slay them wherever ye find them; and (in any case) take no friends or helpers from their ranks;-'),
  ('en.yusufali', 4, 90, 'Except those who join a group between whom and you there is a treaty (of peace), or those who approach you with hearts restraining them from fighting you as well as fighting their own people. If Allah had pleased, He could have given them power over you, and they would have fought you: Therefore if they withdraw from you but fight you not, and (instead) send you (Guarantees of) peace, then Allah Hath opened no way for you (to war against them).'),
  ('en.yusufali', 4, 91, 'Others you will find that wish to gain your confidence as well as that of their people: Every time they are sent back to temptation, they succumb thereto: if they withdraw not from you nor give you (guarantees) of peace besides restraining their hands, seize them and slay them wherever ye get them: In their case We have provided you with a clear argument against them.'),
  ('en.yusufali', 4, 92, 'Never should a believer kill a believer; but (If it so happens) by mistake, (Compensation is due): If one (so) kills a believer, it is ordained that he should free a believing slave, and pay compensation to the deceased\'s family, unless they remit it freely. If the deceased belonged to a people at war with you, and he was a believer, the freeing of a believing slave (Is enough). If he belonged to a people with whom ye have treaty of Mutual alliance, compensation should be paid to his family, and a believing slave be freed. For those who find this beyond their means, (is prescribed) a fast for two months running: by way of repentance to Allah: for Allah hath all knowledge and all wisdom.'),
  ('en.yusufali', 4, 93, 'If a man kills a believer intentionally, his recompense is Hell, to abide therein (For ever): And the wrath and the curse of Allah are upon him, and a dreadful penalty is prepared for him.'),
  ('en.yusufali', 4, 94, 'O ye who believe! When ye go abroad in the cause of Allah, investigate carefully, and say not to any one who offers you a salutation: "Thou art none of a believer!" Coveting the perishable goods of this life: with Allah are profits and spoils abundant. Even thus were ye yourselves before, till Allah conferred on you His favours: Therefore carefully investigate. For Allah is well aware of all that ye do.'),
  ('en.yusufali', 4, 95, 'Not equal are those believers who sit (at home) and receive no hurt, and those who strive and fight in the cause of Allah with their goods and their persons. Allah hath granted a grade higher to those who strive and fight with their goods and persons than to those who sit (at home). Unto all (in Faith) Hath Allah promised good: But those who strive and fight Hath He distinguished above those who sit (at home) by a special reward,-'),
  ('en.yusufali', 4, 96, 'Ranks specially bestowed by Him, and Forgiveness and Mercy. For Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 4, 97, 'When angels take the souls of those who die in sin against their souls, they say: "In what (plight) Were ye?" They reply: "Weak and oppressed Were we in the earth." They say: "Was not the earth of Allah spacious enough for you to move yourselves away (From evil)?" Such men will find their abode in Hell,- What an evil refuge! -'),
  ('en.yusufali', 4, 98, 'Except those who are (really) weak and oppressed - men, women, and children - who have no means in their power, nor (a guide-post) to their way.'),
  ('en.yusufali', 4, 99, 'For these, there is hope that Allah will forgive: For Allah doth blot out (sins) and forgive again and again.'),
  ('en.yusufali', 4, 100, 'He who forsakes his home in the cause of Allah, finds in the earth Many a refuge, wide and spacious: Should he die as a refugee from home for Allah and His Messenger, His reward becomes due and sure with Allah: And Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 4, 101, 'When ye travel through the earth, there is no blame on you if ye shorten your prayers, for fear the Unbelievers May attack you: For the Unbelievers are unto you open enemies.'),
  ('en.yusufali', 4, 102, 'When thou (O Messenger) art with them, and standest to lead them in prayer, Let one party of them stand up (in prayer) with thee, Taking their arms with them: When they finish their prostrations, let them Take their position in the rear. And let the other party come up which hath not yet prayed - and let them pray with thee, Taking all precaution, and bearing arms: the Unbelievers wish, if ye were negligent of your arms and your baggage, to assault you in a single rush. But there is no blame on you if ye put away your arms because of the inconvenience of rain or because ye are ill; but take (every) precaution for yourselves. For the Unbelievers Allah hath prepared a humiliating punishment.'),
  ('en.yusufali', 4, 103, 'When ye pass (Congregational) prayers, celebrate Allah\'s praises, standing, sitting down, or lying down on your sides; but when ye are free from danger, set up Regular Prayers: For such prayers are enjoined on believers at stated times.'),
  ('en.yusufali', 4, 104, 'And slacken not in following up the enemy: If ye are suffering hardships, they are suffering similar hardships; but ye have Hope from Allah, while they have none. And Allah is full of knowledge and wisdom.'),
  ('en.yusufali', 4, 105, 'We have sent down to thee the Book in truth, that thou mightest judge between men, as guided by Allah: so be not (used) as an advocate by those who betray their trust;'),
  ('en.yusufali', 4, 106, 'But seek the forgiveness of Allah; for Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 4, 107, 'Contend not on behalf of such as betray their own souls; for Allah loveth not one given to perfidy and crime:'),
  ('en.yusufali', 4, 108, 'They may hide (Their crimes) from men, but they cannot hide (Them) from Allah, seeing that He is in their midst when they plot by night, in words that He cannot approve: And Allah Doth compass round all that they do.'),
  ('en.yusufali', 4, 109, 'Ah! These are the sort of men on whose behalf ye may contend in this world; but who will contend with Allah on their behalf on the Day of Judgment, or who will carry their affairs through?'),
  ('en.yusufali', 4, 110, 'If any one does evil or wrongs his own soul but afterwards seeks Allah\'s forgiveness, he will find Allah Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 4, 111, 'And if any one earns sin. he earns it against His own soul: for Allah is full of knowledge and wisdom.'),
  ('en.yusufali', 4, 112, 'But if any one earns a fault or a sin and throws it on to one that is innocent, He carries (on himself) (Both) a falsehood and a flagrant sin.'),
  ('en.yusufali', 4, 113, 'But for the Grace of Allah to thee and his Mercy, a party of them would certainly have plotted to lead thee astray. But (in fact) they will only Lead their own souls astray, and to thee they can do no harm in the least. For Allah hath sent down to thee the Book and wisdom and taught thee what thou Knewest not (before): And great is the Grace of Allah unto thee.'),
  ('en.yusufali', 4, 114, 'In most of their secret talks there is no good: But if one exhorts to a deed of charity or justice or conciliation between men, (Secrecy is permissible): To him who does this, seeking the good pleasure of Allah, We shall soon give a reward of the highest (value).'),
  ('en.yusufali', 4, 115, 'If anyone contends with the Messenger even after guidance has been plainly conveyed to him, and follows a path other than that becoming to men of Faith, We shall leave him in the path he has chosen, and land him in Hell,- what an evil refuge!'),
  ('en.yusufali', 4, 116, 'Allah forgiveth not (The sin of) joining other gods with Him; but He forgiveth whom He pleaseth other sins than this: one who joins other gods with Allah, Hath strayed far, far away (from the right).'),
  ('en.yusufali', 4, 117, '(The Pagans), leaving Him, call but upon female deities: They call but upon satan the persistent rebel!'),
  ('en.yusufali', 4, 118, 'Allah did curse him, but he said: "I will take of Thy servants a portion Marked off;'),
  ('en.yusufali', 4, 119, '"I will mislead them, and I will create in them false desires; I will order them to slit the ears of cattle, and to deface the (fair) nature created by Allah." Whoever, forsaking Allah, takes satan for a friend, hath of a surety suffered a loss that is manifest.'),
  ('en.yusufali', 4, 120, 'Satan makes them promises, and creates in them false desires; but satan\'s promises are nothing but deception.'),
  ('en.yusufali', 4, 121, 'They (his dupes) will have their dwelling in Hell, and from it they will find no way of escape.'),
  ('en.yusufali', 4, 122, 'But those who believe and do deeds of righteousness,- we shall soon admit them to gardens, with rivers flowing beneath,-to dwell therein for ever. Allah\'s promise is the truth, and whose word can be truer than Allah\'s?'),
  ('en.yusufali', 4, 123, 'Not your desires, nor those of the People of the Book (can prevail): whoever works evil, will be requited accordingly. Nor will he find, besides Allah, any protector or helper.'),
  ('en.yusufali', 4, 124, 'If any do deeds of righteousness,- be they male or female - and have faith, they will enter Heaven, and not the least injustice will be done to them.'),
  ('en.yusufali', 4, 125, 'Who can be better in religion than one who submits his whole self to Allah, does good, and follows the way of Abraham the true in Faith? For Allah did take Abraham for a friend.'),
  ('en.yusufali', 4, 126, 'But to Allah belong all things in the heavens and on earth: And He it is that Encompasseth all things.'),
  ('en.yusufali', 4, 127, 'They ask thy instruction concerning the women say: Allah doth instruct you about them: And (remember) what hath been rehearsed unto you in the Book, concerning the orphans of women to whom ye give not the portions prescribed, and yet whom ye desire to marry, as also concerning the children who are weak and oppressed: that ye stand firm for justice to orphans. There is not a good deed which ye do, but Allah is well-acquainted therewith.'),
  ('en.yusufali', 4, 128, 'If a wife fears cruelty or desertion on her husband\'s part, there is no blame on them if they arrange an amicable settlement between themselves; and such settlement is best; even though men\'s souls are swayed by greed. But if ye do good and practise self-restraint, Allah is well-acquainted with all that ye do.'),
  ('en.yusufali', 4, 129, 'Ye are never able to be fair and just as between women, even if it is your ardent desire: But turn not away (from a woman) altogether, so as to leave her (as it were) hanging (in the air). If ye come to a friendly understanding, and practise self-restraint, Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 4, 130, 'But if they disagree (and must part), Allah will provide abundance for all from His all-reaching bounty: for Allah is He that careth for all and is Wise.'),
  ('en.yusufali', 4, 131, 'To Allah belong all things in the heavens and on earth. Verily we have directed the People of the Book before you, and you (o Muslims) to fear Allah. But if ye deny Him, lo! unto Allah belong all things in the heavens and on earth, and Allah is free of all wants, worthy of all praise.'),
  ('en.yusufali', 4, 132, 'Yea, unto Allah belong all things in the heavens and on earth, and enough is Allah to carry through all affairs.'),
  ('en.yusufali', 4, 133, 'If it were His will, He could destroy you, o mankind, and create another race; for He hath power this to do.'),
  ('en.yusufali', 4, 134, 'If any one desires a reward in this life, in Allah\'s (gift) is the reward (both) of this life and of the hereafter: for Allah is He that heareth and seeth (all things).'),
  ('en.yusufali', 4, 135, 'O ye who believe! stand out firmly for justice, as witnesses to Allah, even as against yourselves, or your parents, or your kin, and whether it be (against) rich or poor: for Allah can best protect both. Follow not the lusts (of your hearts), lest ye swerve, and if ye distort (justice) or decline to do justice, verily Allah is well-acquainted with all that ye do.'),
  ('en.yusufali', 4, 136, 'O ye who believe! Believe in Allah and His Messenger, and the scripture which He hath sent to His Messenger and the scripture which He sent to those before (him). Any who denieth Allah, His angels, His Books, His Messengers, and the Day of Judgment, hath gone far, far astray.'),
  ('en.yusufali', 4, 137, 'Those who believe, then reject faith, then believe (again) and (again) reject faith, and go on increasing in unbelief,- Allah will not forgive them nor guide them nor guide them on the way.'),
  ('en.yusufali', 4, 138, 'To the Hypocrites give the glad tidings that there is for them (but) a grievous penalty;-'),
  ('en.yusufali', 4, 139, 'Yea, to those who take for friends unbelievers rather than believers: is it honour they seek among them? Nay,- all honour is with Allah.'),
  ('en.yusufali', 4, 140, 'Already has He sent you Word in the Book, that when ye hear the signs of Allah held in defiance and ridicule, ye are not to sit with them unless they turn to a different theme: if ye did, ye would be like them. For Allah will collect the hypocrites and those who defy faith - all in Hell:-'),
  ('en.yusufali', 4, 141, '(These are) the ones who wait and watch about you: if ye do gain a victory from Allah, they say: "Were we not with you?"- but if the unbelievers gain a success, they say (to them): "Did we not gain an advantage over you, and did we not guard you from the believers?" but Allah will judge betwixt you on the Day of Judgment. And never will Allah grant to the unbelievers a way (to triumphs) over the believers.'),
  ('en.yusufali', 4, 142, 'The Hypocrites - they think they are over-reaching Allah, but He will over-reach them: When they stand up to prayer, they stand without earnestness, to be seen of men, but little do they hold Allah in remembrance;'),
  ('en.yusufali', 4, 143, '(They are) distracted in mind even in the midst of it,- being (sincerely) for neither one group nor for another whom Allah leaves straying,- never wilt thou find for him the way.'),
  ('en.yusufali', 4, 144, 'O ye who believe! Take not for friends unbelievers rather than believers: Do ye wish to offer Allah an open proof against yourselves?'),
  ('en.yusufali', 4, 145, 'The Hypocrites will be in the lowest depths of the Fire: no helper wilt thou find for them;-'),
  ('en.yusufali', 4, 146, 'Except for those who repent, mend (their lives) hold fast to Allah, and purify their religion as in Allah\'s sight: if so they will be (numbered) with the believers. And soon will Allah grant to the believers a reward of immense value.'),
  ('en.yusufali', 4, 147, 'What can Allah gain by your punishment, if ye are grateful and ye believe? Nay, it is Allah that recogniseth (all good), and knoweth all things.'),
  ('en.yusufali', 4, 148, 'Allah loveth not that evil should be noised abroad in public speech, except where injustice hath been done; for Allah is He who heareth and knoweth all things.'),
  ('en.yusufali', 4, 149, 'Whether ye publish a good deed or conceal it or cover evil with pardon, verily Allah doth blot out (sins) and hath power (in the judgment of values).'),
  ('en.yusufali', 4, 150, 'Those who deny Allah and His messengers, and (those who) wish to separate Allah from His messengers, saying: "We believe in some but reject others": And (those who) wish to take a course midway,-'),
  ('en.yusufali', 4, 151, 'They are in truth (equally) unbelievers; and we have prepared for unbelievers a humiliating punishment.'),
  ('en.yusufali', 4, 152, 'To those who believe in Allah and His messengers and make no distinction between any of the messengers, we shall soon give their (due) rewards: for Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 4, 153, 'The people of the Book ask thee to cause a book to descend to them from heaven: Indeed they asked Moses for an even greater (miracle), for they said: "Show us Allah in public," but they were dazed for their presumption, with thunder and lightning. Yet they worshipped the calf even after clear signs had come to them; even so we forgave them; and gave Moses manifest proofs of authority.'),
  ('en.yusufali', 4, 154, 'And for their covenant we raised over them (the towering height) of Mount (Sinai); and (on another occasion) we said: "Enter the gate with humility"; and (once again) we commanded them: "Transgress not in the matter of the sabbath." And we took from them a solemn covenant.'),
  ('en.yusufali', 4, 155, '(They have incurred divine displeasure): In that they broke their covenant; that they rejected the signs of Allah; that they slew the Messengers in defiance of right; that they said, "Our hearts are the wrappings (which preserve Allah\'s Word; We need no more)";- Nay, Allah hath set the seal on their hearts for their blasphemy, and little is it they believe;-'),
  ('en.yusufali', 4, 156, 'That they rejected Faith; that they uttered against Mary a grave false charge;'),
  ('en.yusufali', 4, 157, 'That they said (in boast), "We killed Christ Jesus the son of Mary, the Messenger of Allah";- but they killed him not, nor crucified him, but so it was made to appear to them, and those who differ therein are full of doubts, with no (certain) knowledge, but only conjecture to follow, for of a surety they killed him not:-'),
  ('en.yusufali', 4, 158, 'Nay, Allah raised him up unto Himself; and Allah is Exalted in Power, Wise;-'),
  ('en.yusufali', 4, 159, 'And there is none of the People of the Book but must believe in him before his death; and on the Day of Judgment he will be a witness against them;-'),
  ('en.yusufali', 4, 160, 'For the iniquity of the Jews We made unlawful for them certain (foods) good and wholesome which had been lawful for them;- in that they hindered many from Allah\'s Way;-'),
  ('en.yusufali', 4, 161, 'That they took usury, though they were forbidden; and that they devoured men\'s substance wrongfully;- we have prepared for those among them who reject faith a grievous punishment.'),
  ('en.yusufali', 4, 162, 'But those among them who are well-grounded in knowledge, and the believers, believe in what hath been revealed to thee and what was revealed before thee: And (especially) those who establish regular prayer and practise regular charity and believe in Allah and in the Last Day: To them shall We soon give a great reward.'),
  ('en.yusufali', 4, 163, 'We have sent thee inspiration, as We sent it to Noah and the Messengers after him: we sent inspiration to Abraham, Isma\'il, Isaac, Jacob and the Tribes, to Jesus, Job, Jonah, Aaron, and solomon, and to David We gave the Psalms.'),
  ('en.yusufali', 4, 164, 'Of some messengers We have already told thee the story; of others We have not;- and to Moses Allah spoke direct;-'),
  ('en.yusufali', 4, 165, 'Messengers who gave good news as well as warning, that mankind, after (the coming) of the messengers, should have no plea against Allah: For Allah is Exalted in Power, Wise.'),
  ('en.yusufali', 4, 166, 'But Allah beareth witness that what He hath sent unto thee He hath sent from His (own) knowledge, and the angels bear witness: But enough is Allah for a witness.'),
  ('en.yusufali', 4, 167, 'Those who reject Faith and keep off (men) from the way of Allah, have verily strayed far, far away from the Path.'),
  ('en.yusufali', 4, 168, 'Those who reject Faith and do wrong,- Allah will not forgive them nor guide them to any way-'),
  ('en.yusufali', 4, 169, 'Except the way of Hell, to dwell therein for ever. And this to Allah is easy.'),
  ('en.yusufali', 4, 170, 'O Mankind! The Messenger hath come to you in truth from Allah: believe in him: It is best for you. But if ye reject Faith, to Allah belong all things in the heavens and on earth: And Allah is All-knowing, All-wise.'),
  ('en.yusufali', 4, 171, 'O People of the Book! Commit no excesses in your religion: Nor say of Allah aught but the truth. Christ Jesus the son of Mary was (no more than) a messenger of Allah, and His Word, which He bestowed on Mary, and a spirit proceeding from Him: so believe in Allah and His messengers. Say not "Trinity": desist: it will be better for you: for Allah is one Allah: Glory be to Him: (far exalted is He) above having a son. To Him belong all things in the heavens and on earth. And enough is Allah as a Disposer of affairs.'),
  ('en.yusufali', 4, 172, 'Christ disdaineth nor to serve and worship Allah, nor do the angels, those nearest (to Allah): those who disdain His worship and are arrogant,-He will gather them all together unto Himself to (answer).'),
  ('en.yusufali', 4, 173, 'But to those who believe and do deeds of righteousness, He will give their (due) rewards,- and more, out of His bounty: But those who are disdainful and arrogant, He will punish with a grievous penalty; Nor will they find, besides Allah, any to protect or help them.'),
  ('en.yusufali', 4, 174, 'O mankind! verily there hath come to you a convincing proof from your Lord: For We have sent unto you a light (that is) manifest.'),
  ('en.yusufali', 4, 175, 'Then those who believe in Allah, and hold fast to Him,- soon will He admit them to mercy and grace from Himself, and guide them to Himself by a straight way.'),
  ('en.yusufali', 4, 176, 'They ask thee for a legal decision. Say: Allah directs (thus) about those who leave no descendants or ascendants as heirs. If it is a man that dies, leaving a sister but no child, she shall have half the inheritance: If (such a deceased was) a woman, who left no child, Her brother takes her inheritance: If there are two sisters, they shall have two-thirds of the inheritance (between them): if there are brothers and sisters, (they share), the male having twice the share of the female. Thus doth Allah make clear to you (His law), lest ye err. And Allah hath knowledge of all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 4, 1, 'Yaaa aiyuhan naasut taqoo Rabbakumul lazee khalaqakum min nafsinw waahidatinw wa khalaqa minhaa zawjahaa wa bas sa minhumaa rijaalan kaseeranw wa nisaaa\'aa; wattaqul laahallazee tasaaa \'aloona bihee wal arhaam; innal laaha kaana \'alaikum Raqeeba'),
  ('en.transliteration', 4, 2, 'Wa aatul yataamaaa amwaalahum wa laa tatabad dalul khabeesa bittaiyibi wa laa taakulooo amwaalahum ilaaa amwaalikum; innahoo kaana hooban kabeeraa'),
  ('en.transliteration', 4, 3, 'Wa in khiftum allaa tuqsitoo fil yataamaa fankihoo maa taaba lakum minan nisaaa\'i masnaa wa sulaasa wa rubaa\'a fa\'in khiftum allaa ta\'diloo fawaahidatan aw maa malakat aimaanukum; zaalika adnaaa allaa ta\'ooloo'),
  ('en.transliteration', 4, 4, 'Wa aatun nisaaa\'a sadu qaatihinna nihlah; fa in tibna lakum \'an shai\'im minhu nafsan fakuloohu hanee\'am mareee\'aa'),
  ('en.transliteration', 4, 5, 'Wa laa tu\'tus sufahaaa\'a amwaalakumul latee ja\'alal laahu lakum qiyaamanw-warzuqoohum feehaa waksoohum wa qooloo lahum qawlam ma\'roofaa'),
  ('en.transliteration', 4, 6, 'Wabtalul yataamaa hattaaa izaa balaghun nikaaha fa in aanastum minhum rushdan fad fa\'ooo ilaihim amwaalahum wa laa taa kuloohaaa israafanw wa bidaaran ai yakbaroo; wa mai kaana ghaniyyan falyasta\' fif wa mai kaana faqeeran falyaakul bilma\'roof; fa izaa dafa\'tum ilaihim amwaalahum fa\'ashhidoo \'alaihim; wa kafaa billaahi Haseeba'),
  ('en.transliteration', 4, 7, 'Lirrijaali naseebum mimmaa tarakal waalidaani wal aqraboona wa lin nisaaa\'i naseebum mimmaa tarakal waalidaani wal aqraboona mimmaa qalla minhu aw kasur; naseebam mafroodaa'),
  ('en.transliteration', 4, 8, 'Wa izaa hadaral qismata ulul qurbaa walyataamaa walmasaakeenu farzuqoohum minhu wa qooloo lahum qawlam ma\'roofaa'),
  ('en.transliteration', 4, 9, 'Walyakhshal lazeena law tarakoo min khalfihim zurriyyatan di\'aafan khaafoo \'alaihim falyattaqul laaha walyaqooloo qawlan sadeedaa'),
  ('en.transliteration', 4, 10, 'Innal lazeena yaakuloona amwaalal yataamaa zulman innamaa yaakuloona fee butoonihim Naaranw-wa sayaslawna sa\'eeraa'),
  ('en.transliteration', 4, 11, 'Yooseekumul laahu feee awlaadikum liz zakari mislu hazzil unsayayn; fa in kunna nisaaa\'an fawqas nataini falahunna suhusaa maa taraka wa in kaanat waahidatan falahan nisf; wa li abawaihi likulli waahidim minhumas sudusu mimmma taraka in kaana lahoo walad; fa il lam yakul lahowaladunw wa warisahooo abawaahu fali ummihis sulus; fa in kaana lahoo ikhwatun fali ummihis sudus; mim ba\'di wasiyyatiny yoosee bihaaa aw dayn; aabaaa\'ukum wa abnaaa\'ukum laa tadroona aiyuhum aqrabu lakum naf\'aa; fareedatam minallaah; innal laaha kaana \'Aleeman Hakeemaa'),
  ('en.transliteration', 4, 12, 'Wa lakum nisfu maa taraka azwaajukum il lam yakul lahunna walad; fa in kaana lahunna waladun falakumur rub\'u mimmaa tarakna mim ba\'di wasiyyatiny yooseena bihaaa aw dayn; wa lahunnar rubu\'u mimmaa tarakum il lam yakul lakum walad; fa in kaana lakum waladun falahunnas sumunu mimmaa taraktum; mim ba\'di wasiyyatin toosoona bihaaa aw dayn; wa in kaana rajuluny yoorasu kalaalatan awim ra atunw wa lahooo akhun aw ukhtun falikulli waahidim minhumas sudus; fa in kaanooo aksara min zaalika fahum shurakaaa\'u fissulusi mim ba\'di wasiyyatiny yoosaa bihaaa aw dainin ghaira mudaaarr; wasiyyatam minal laah; wallaahu \'Aleemun Haleem'),
  ('en.transliteration', 4, 13, 'Tilka hudoodul laah; wa mai yuti\'il laaha wa Rasoolahoo yudkhilhu Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalikal fawzul \'azeem'),
  ('en.transliteration', 4, 14, 'Wa mai ya\'sil laaha wa Rasoolahoo wa yata\'adda hudoodahoo yudkhilhu Naaran khaalidan feehaa wa lahoo \'azaabum muheen'),
  ('en.transliteration', 4, 15, 'Wallaatee yaateenal faahishata min nisaaa\'ikum fastashhidoo \'alaihinna arba\'atam minkum fa in shahidoo fa amsikoohunna fil buyooti hatta yatawaffaa hunnal mawtu aw yaj\'alal laahu lahunna sabeelaa'),
  ('en.transliteration', 4, 16, 'Wallazaani yaatiyaanihaa minkum fa aazoohumaa fa in taabaa wa aslahaa fa a\'ridoo \'anhumaaa; innal laaha kaana Tawwaabar Raheema'),
  ('en.transliteration', 4, 17, 'Innamat tawbatu \'alallaahi lillazeena ya\'maloonas sooo\'a bijahaalatin summa yatooboona min qareebin faulaaika yatoobul laahu \'alaihim; wa kaanal laahu \'Aleeman Hakeemaa'),
  ('en.transliteration', 4, 18, 'Wa laisatit tawbatu lillazeena ya\'maloonas saiyiaati hattaaa izaa hadara ahadahumul mawtu qaala innee tubtul \'aana wa lallazeena yamootoona wa hum kuffaar; ulaaa\'ika a\'tadnaa lahum \'azaaban aleemaa'),
  ('en.transliteration', 4, 19, 'Yaaa aiyuhal lazeena aamanoo laa yahillu lakum an tarisun nisaaa\'a karhan wa laa ta\'duloohunna litazhaboo biba\'di maaa aataitumoohunna illaaa ai yaateena bifaahishatim bubaiyinah; wa \'aashiroo hunna bilma\'roof; fa in karihtumoohunna fa\'asaaa an takrahoo shai\'anw wa yaj\'alal laahu feehi khairan kaseeraa'),
  ('en.transliteration', 4, 20, 'Wa in arattumustib daala zawjim makaana zawjin wa aataitum ihdaahunna qintaaran falaa taakhuzoo minhu shai\'aa; ataakhuzoonahoo buhtaannanw wa ismam mubeenaa'),
  ('en.transliteration', 4, 21, 'Wa kaifa taakhuzoonahoo wa qad afdaa ba\'dukum ilaa ba\'dinw wa akhazna minkum meesaaqan ghaleezaa'),
  ('en.transliteration', 4, 22, 'Wa laa tankihoo maa nakaha aabaaa\'ukum minan nisaaa\'i illaa maa qad salaf; inahoo kaana faahishatanw wa maqtanw wa saaa\'a sabeelaa'),
  ('en.transliteration', 4, 23, 'Hurrimat \'alaikum umma haatukum wa bannaatukum wa akhawaatukum wa \'ammaatukum wa khaalaatukum wa banaatul akhi wa banaatul ukhti wa ummahaatu kumul laateee arda\' nakum wa akhawaatukum minarradaa\'ati wa ummahaatu nisaaa\'ikum wa rabaaa\'i bukumul laatee fee hujoorikum min nisaaa\'ikumul laatee dakhaltum bihinna Fa il lam takoonoo dakhaltum bihina falaa junaaha \'alaikum wa halaaa\'ilu abnaaa\'ikumul lazeena min aslaabikum wa an tajma\'oo bainal ukhtaini illaa maa qad salaf; innallaaha kaana Ghafoorar Raheema'),
  ('en.transliteration', 4, 24, 'Walmuhsanaatu minan nisaaa\'i illaa maa malakat aimaanukum kitaabal laahi \'alaikum; wa uhilla lakum maa waraaa\'a zaalikum an tabtaghoo bi amwaali kum muhsineena ghaira musaa fiheen; famastamta\'tum bihee minhunna fa aatoohunna ujoorahunna fareedah; wa laa junaaha \'alaikum feemaa taraadaitum bihee mim ba\'dil fareedah; innal laaha kaana \'Aleeman Hakeemaa'),
  ('en.transliteration', 4, 25, 'Wa mal lam yastati\' minkum tawlan ai yankihal muhsanaatil mu\'minaati famimmaa malakat aimaanukum min fatayaatikumul mu\'minaat; wallaahu a\'lamu bi eemaanikum; ba\'dukum mim ba\'d; fankihoohunna bi izni ahlihinna wa aatoohunna ujoorahunna bilma\'roofi muhsanaatin ghaira musaa fihaatinw wa laa muttakhizaati akhdaan; fa izaaa uhsinna fa in ataina bifaahi shatin fa\'alaihinnna nisfu maa \'alal muhsanaati minal \'azaab; zaalika liman khashiyal \'anata minkum; wa an tasbiroo khairul lakum; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 4, 26, 'Yureedul laahu liyubai yina lakum wa yahdiyakum sunanal lazeena min qablikum wa yatooba \'alaikum; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 4, 27, 'Wallaahu yureedu ai yatooba \'alaikum wa yureedul lazeena yattabi \'oonash shahawaati an tameeloo mailan \'azeemaa'),
  ('en.transliteration', 4, 28, 'Yureedul laahu ai yukhaffifa \'ankum; wa khuliqal insaanu da\'eefaa'),
  ('en.transliteration', 4, 29, 'Yaaa aiyuhal lazeena aamanoo laa taakulooo amwaalakum bainakum bilbaatili \'illaaa an takoona tijaaratan \'an taraadim minkum; wa laa taqtulooo anfusakum; innal laaha kaana bikum Raheemaa'),
  ('en.transliteration', 4, 30, 'Wa mai yaf\'al zaalika \'udwaananw wa zulman fasawfa nusleehi Naaraa; wa kaana zaalika \'alal laahi yaseeraa'),
  ('en.transliteration', 4, 31, 'In tajtaniboo kabaaa\'ira maa tunhawna \'anhu nukaffir \'ankum saiyiaatikum wa nudkhilkum mudkhalan kareemaa'),
  ('en.transliteration', 4, 32, 'Wa laa tatamannaw maa faddalal laahu bihee ba\'dakum \'alaa ba\'d; lirrijaali naseebum mimak tasaboo wa linnisaaa\'i naseebum mimmak tasabna; was\'alullaaha min fadlih; innal laaha kaana bikulli shai\'in \'Aleemaa'),
  ('en.transliteration', 4, 33, 'Wa likullin ja\'alnaa ma waaliya mimmaa tarakal waalidaani wal aqraboon; wallazeena \'aqadat aimaanukum fa aatoohum naseebahum; innal laaha kaana \'alaa kulli shai\'in Shaheedaa'),
  ('en.transliteration', 4, 34, 'Arrijaalu qawwaamoona \'alan nisaaa\'i bimaa fad dalallaahu ba\'dahum \'alaa ba\'dinw wa bimaaa anfoqoo min amwaalihim; fassaalihaatu qaanitaatun haafizaatul lil ghaibi bimaa hafizal laah; wallaatee takhaafoona nushoo zahunna fa \'izoohunna wahjuroohunna fil madaaji\'i wadriboohunna fa in ata\'nakum falaa tabghoo \'alaihinna sabeelaa; innallaaha kaana \'Aliyyan Kabeeraa'),
  ('en.transliteration', 4, 35, 'Wa in khiftum shiqaaqa baini himaa fab\'asoo haka mam min ahlihee wa hakamam min ahlihaa; iny-yureedaaa islaah ai-yuwaffiqil laahu bainahumaa; innal laaha kaana \'Aleeman Khabeeraa'),
  ('en.transliteration', 4, 36, 'Wa\'budul laaha wa laa tushrikoo bihee shai\'anw wa bilwaalidaini ihsaananw wa bizil qurbaa walyataamaa walmasaakeeni waljaari zilqurbaa waljaaril junubi wassaahibi biljambi wabnis sabeeli wa maa malakat aimaanukum; innal laaha laa yuhibbu man kaana mukhtaalan fakhooraa'),
  ('en.transliteration', 4, 37, 'Allazeena yabkhaloona wa yaamuroonan naasa bilbukhli wa yaktumoona maaa aataahu mullaahu min fadlih; wa a\'tadnaa lilkaafireena \'azaabam muheenaa'),
  ('en.transliteration', 4, 38, 'Wallazeena yunfiqoona amwaalahum ri\'aaa\'an naasi wa laa yu\'minoona billaahi wa laa bil Yawmil Aakhir; wa mai yakunish shaitaanu lahoo qareenan fasaaa\'a qareenaa'),
  ('en.transliteration', 4, 39, 'Wa maazaa \'alaihim law aamanoo billaahi wal Yawmil Aakhiri wa anfaqoo mimmaa razaqahumul laah; wa kaanallaahu bihim Aaleemaa'),
  ('en.transliteration', 4, 40, 'Innal laaha laa yazlimu misqaala zarratinw wa in taku hasanatany yudaa\'ifhaa wa yu\'ti mil ladunhu ajran \'azeemaa'),
  ('en.transliteration', 4, 41, 'Fakaifa izaa ji\'naa min kulli ummatim bishaheedinw wa ji\'naabika \'alaa haaa\'ulaaa \'i Shaheedan'),
  ('en.transliteration', 4, 42, 'Yawma\'iziny yawad dullazeena kafaroo wa\'asawur Rasoola law tusawwaa bihimul ardu wa laa yaktumoonal laaha hadeesaa'),
  ('en.transliteration', 4, 43, 'yaaa aiyuhal lazeena aamanoo laa taqrabus Salaata wa antum sukaaraa hatta ta\'lamoo ma taqooloona wa la junuban illaa \'aabiree sabeelin hatta taghtasiloo; wa in kuntum mardaaa aw \'alaa safarin aw jaaa\'a ahadum minkum minal ghaaa\'iti aw laamastumun nisaaa\'a falam tajidoo maaa\'an fatayam mamoo sa\'eedan taiyiban famsahoo biwujoohikum wa aideekum; innal laaha kaana \'Afuwwan Ghafooraa'),
  ('en.transliteration', 4, 44, 'Alam tara ilal lazeena ootoo naseebam minal Kitaabi yashtaroonad dalaalata wa yureedoona an tadillus sabeel'),
  ('en.transliteration', 4, 45, 'Wallaahu a\'lamu bi a\'daaa\'i-kum; wa kafaa billaahi waliyyanw wa kafaa billaahi naseera'),
  ('en.transliteration', 4, 46, 'Minal lazeena haadoo yuharrifoonal Kalima \'am mawaadi\'ihee wa yaqooloona sami\'naa wa \'asainaa wasma\' ghaira musma\'inw wa raa\'inaa laiyam bi alsinatihim wa ta\'nan fiddeen; wa law annahum qaaloo sami\'naa wa ata\'naa wasma\' wanzurnaa lakaana khairal lahum wa aqwama wa laakil la \'\'anahumul laahu bikufrihim falaa yu\'minoona illaa qaleela'),
  ('en.transliteration', 4, 47, 'yaaa aiyuha lazeena ootu Kitaaba aaminoo bimaa nazzalnaa musadiqallimaa ma\'akum min qabli an natmisa wujoohan fanaruddahaa \'alaaa adbaarihaaa aw nal\'anahum kamaa la\'annaaa Ashaabas Sabt; wa kaana amrul laahi maf\'oolaa'),
  ('en.transliteration', 4, 48, 'Innal laaha laa yaghfiru ai yushraka bihee wa yaghfiru maa doona zaalika limai yashaaa\'; wa mai yushrik billaahi faqadif taraaa isman \'azeemaa'),
  ('en.transliteration', 4, 49, 'Alam tara ilal lazeena yuzakkoona anfusahum; balil laahu yuzakkee mai yashaaa\'u wa laa yuzlamoona fateelaa'),
  ('en.transliteration', 4, 50, 'Unzur kaifa yaftaroona \'alal laahil kazib, wakafaa biheee ismamm mubeenaa'),
  ('en.transliteration', 4, 51, 'Alam tara ilal lazeena \'ootoo naseebam minal kitaabi yu\'minoona bil Jibti wat Taaghooti wa yaqooloona lillazeena kafaroo haaa ulaaa\'i ahdaa minal lazeena aamanoo sabeelaa'),
  ('en.transliteration', 4, 52, 'Ulaaa\'ikal lazeena la\'ana humul laahu wa mai yal\'anil laahu falan tajida lahoo naseeraa'),
  ('en.transliteration', 4, 53, 'Am lahum naseebum minal mulki fa izal laa yu\'toonan naasa naqeeraa'),
  ('en.transliteration', 4, 54, 'Am yahsudoonan naasa \'alaa maaa aataahumul laahu min fadlihee faqad aatainaaa Aala Ibraaheemal Kitaaba wal Hikmata wa aatainaahum mulkan \'azeemaa'),
  ('en.transliteration', 4, 55, 'Faminhum man aamana bihee wa minhum man sadda \'anh; wa kafaa bi Jahannama sa\'eeraa'),
  ('en.transliteration', 4, 56, 'Innal lazeena kafaroo bi Aayaatinaa sawfa nusleehim Naaran kullamaa nadijat julooduhum baddalnaahum juloodan ghairahaa liyazooqul \'azaab; innallaaha kaana \'Azeezan Hakeemaa'),
  ('en.transliteration', 4, 57, 'Wallazeena aamanoo wa \'amilus saalihaati sanud khiluum jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa, lahum feehaaa azwaajum mutahharatun wa nudkhiluhum zillan zaleelaa'),
  ('en.transliteration', 4, 58, 'Innal laaha yaamurukum an tu\'addul amaanaati ilaaa ahlihaa wa izaa hakamtum bainan naasi an tahkumoo bil \'adl; innal laaha yaamurukum an tu\'addul amaanaati ilaaa ahlihaa wa izaa hakamtum bainan naasi an tahkumoo bil \'adl; innal laaha ni\'immaa ya\'izukum bih; innal laaha kaana Samee\'am Baseera'),
  ('en.transliteration', 4, 59, 'Yaaa aiyuhal lazeena aamanooo atee\'ul laaha wa atee\'ur Rasoola wa ulil amri minkum fa in tanaaza\'tum fee shai\'in faruddoohu ilal laahi war Rasooli in kuntum tu\'minoona billaahi wal yawmil Aakhir; zaalika khairunw wa ahsanu taaweelaa'),
  ('en.transliteration', 4, 60, 'Alam tara ilal lazeena yaz\'umoona annahum aarmanoo bimaa unzilaa ilaika wa maaa unzila min qablika yureedoona ai yatahaakamooo ilat Taaghooti wa qad umirooo ai yakfuroo bih, wa yureedush Shaitaanu ai yudillahum dalaalam ba\'eedaa'),
  ('en.transliteration', 4, 61, 'Wa izaa qeela lahum ta\'aalaw ilaa maaa anzalallaahu wa ilar Rasooli ra aital munaafiqeena yasuddoona \'anka sudoodaa'),
  ('en.transliteration', 4, 62, 'Fakaifa izaaa asaabathum museebatum summa jaaa\'ooka yahlifoona billaahi in aradnaaa illaaa ihsaananw wa tawfeeqaa'),
  ('en.transliteration', 4, 63, 'Ulaaa\'ikal lazeena ya\'la mullaahu maa fee quloobihim fa a\'rid \'anhum wa \'izhum wa qul lahum feee anfusihim qawlam baleeghaa'),
  ('en.transliteration', 4, 64, 'Wa maa arsalnaa mir Rasoolin illaa liyutaa\'a bi iznil laah; wa law annahum \'iz zalamooo anfusahum jaaa\'ooka fastaghfarul laaha wastaghfara lahumur Rasoolu la wajadul laaha Tawwaabar Raheemaa'),
  ('en.transliteration', 4, 65, 'Falaa wa Rabbika laa yu\'minoona hattaa yuhakkimooka fe emaa shajara bainahum summa laa yajidoo fee anfusihim harajam mimmaa qadaita wa yusal limoo tasleemaa'),
  ('en.transliteration', 4, 66, 'Wa law annaa katabnaa \'alaihim aniq tulooo anfusakum awikh rujoo min diyaarikum maa fa\'aloohu illaa qaleelum minhum wa law annahum fa\'aloo maa yoo\'azoona bihee lakaana khairal lahum wa ashadda tasbeetaa'),
  ('en.transliteration', 4, 67, 'Wa izal la aatainaahum mil ladunnaaa ajran \'azeemaa'),
  ('en.transliteration', 4, 68, 'Wa lahadainaahum Siraatam mustaqeemaa'),
  ('en.transliteration', 4, 69, 'Wa many-yuti\'il laaha war Rasoola fa ulaaa\'ika ma\'al lazeena an\'amal laahu \'alaihim minan nabiyyeena wassiddeeqeena washshuhadaaa\'i wassaaliheen; wa hasuna ulaaa\'ika rafeeqaa'),
  ('en.transliteration', 4, 70, 'Zaalikal fadlu minal laah; wa kafaa billaahi \'Aleemaa'),
  ('en.transliteration', 4, 71, 'Yaaa aiyuhal lazeena aamanoo khuzoo hizrakum fanfiroo subaain awin firoo jamee\'aa'),
  ('en.transliteration', 4, 72, 'Wa inna minkum lamal la yubatti\'anna fa in asaabatkum museebatun qaala qad an\'amal laahu \'alaiya iz lam akum ma\'ahum shaheeda'),
  ('en.transliteration', 4, 73, 'Wa la\'in asaabakum fadlum minal laahi la yaqoolanna ka al lam takum bainakum wa bainahoo mawaddatuny yaa laitanee kuntu ma\'ahum fa afooza fawzan \'azeemaa'),
  ('en.transliteration', 4, 74, 'Falyuqaatil fee sabeelil laahil lazeena yashroonal hayaatad dunyaa bil Aakhirah; wa many-uqaatil fee sabeelil laahi fa yuqtal aw yaghlib fasawfa nu\'teehi ajran \'azeemaa'),
  ('en.transliteration', 4, 75, 'Wa maa lakum laa tuqaatiloona fee sabeelil laahi walmustad\'afeena minar rijaali wannisaaa\'i walwildaanil lazeena yaqooloona Rabbanaaa akhrijnaa min haazihil qaryatiz zaalimi ahluhaa waj\'al lanaa mil ladunka waliyanw waj\'al lanaa mil ladunka naseeraa'),
  ('en.transliteration', 4, 76, 'Allazeena aamanoo yuqaatiloona fee sabeelil laahi wallazeena kafaroo yuqaatiloona fee sabeelit Taaghoot faqaatiloo awliyaaa\'ash Shaitaan; inna kaidash Shairaani kaana da\'eefa'),
  ('en.transliteration', 4, 77, 'Alam tara ilal lazeena qeela lahum kuffooo aidiyakum wa aqeemus Salaata w aaatuz Zakaata falammaa kutiba \'alaihimul qitaalu izaa fareequm minhum yakhshawnnan naasa kakhashyatil laahi aw ashadda khashyah; wa qaaloo Rabbanaa lima katabta \'alainal qitaala law laaa akhkhartanaa ilaaa ajalin qareeb; qul mataa\'ud dunyaa qaleelunw wal Aakhiratu khairul limanit taqaa wa laa tuzlamoona fateelaa'),
  ('en.transliteration', 4, 78, 'Ainamaa takoonoo yudrikkumul mawtu wa law kuntum fee buroojim mushai yadah; wa in tusibhum hasanatuny yaqooloo haazihee min indil laahi wa in tusibhum saiyi\'atuny yaqooloo haazihee min \'indik; qul kullum min \'indillaahi famaa lihaaa \'ulaaa\'il qawmi laa yakkaadoona yafqahoona hadeesaa'),
  ('en.transliteration', 4, 79, 'Maaa asaabaka min hasanatin faminal laahi wa maaa asaaabaka min saiyi\'atin famin nafsik; wa arsalnaaka linnaasi Rasoolaa; wa kafaa billaahi Shaheedaa'),
  ('en.transliteration', 4, 80, 'Man yuti\'ir Rasoola faqad ataa\'al laaha wa man tawallaa famaaa arsalnaaka \'alaihim hafeezaa'),
  ('en.transliteration', 4, 81, 'Wa yaqooloona taa\'antun fa izaa barazoo min \'indika baiyata taaa\'ifatum minhum ghairal lazee taqoolu wallaahu yaktubu maa yubaiyitoona faa\'rid \'anhum wa tawakkal \'alal laah; wa kafaa billaahi Wakeelaa'),
  ('en.transliteration', 4, 82, 'Afalaa yatadabbaroonal Qur\'aan; wa law kaana min \'indi ghairil laahi la wajadoo fee hikh tilaafan kaseeraa'),
  ('en.transliteration', 4, 83, 'Wa izaa jaaa\'ahum amrum minal amni awil kkhawfi azaa\'oo bihee wa law raddoohu ilar Rasooli wa ilaaa ulil amri minhum la\'alimahul lazeena yastambitoonahoo minhum; wa law laa fadlul laahi \'alaikum wa rahmatuhoo lattaba\'tumush Shaitaana illaa qaleelaa'),
  ('en.transliteration', 4, 84, 'Faqaatil fee sabeelil laahi laa tukallafu illa nafsaka wa harridil mu\'mineena \'asallaahu ai yakuffa baasallazeena kafaroo; wallaahu ashaddu baasanw wa ashaaddu tanakeelaa'),
  ('en.transliteration', 4, 85, 'Mai yashfa\' shafaa\'atan hasanatay yakul lahoo naseebum minhaa wa mai yashfa\' shafaa\'tan saiyi\'atanny-yakul lahoo kiflum minhaa; wa kaanal laahu \'alaa kulli shai\'im Muqeetaa'),
  ('en.transliteration', 4, 86, 'Wa izaa huyyeetum bitahiy yatin fahaiyoo bi ahsana minhaaa aw ruddoohaa; innal laaha kaana \'alaa kulli shai\'in Haseeba'),
  ('en.transliteration', 4, 87, 'Allaahu laaa ilaaha illaa huwa la yajma\'annakum ilaa Yawmil Qiyaamati laa raiba feeh; wa man asdaqu mminallaahi hadeesaa'),
  ('en.transliteration', 4, 88, 'Famaa lakum filmuna afiqeena fi\'ataini wallaahu arkasahum bimaa kasaboo; atureedoona an tahdoo man adallal laahu wa mmai yudlilil laahu falan tajida lahoo sabeelaa'),
  ('en.transliteration', 4, 89, 'Wadoo law takfuroona kamaa kafaroo fatakoonoona sawaaa\'an falaa tattakhizoo minhum awliyaaa\'a hattaa yuhaajiroo fee sabeelil laah; fa in tawallaw fa khuzoohum waqtuloohum haisu wajat tumoohum wa laa tattakhizoo minhum waliyyanw wa laa naseeraa'),
  ('en.transliteration', 4, 90, 'Illal lazeena yasiloona ilaa qawmim binakum wa bainahum meesaaqun aw jaaa\'ookum hasirat sudooruhum ai yuqaatilookum aw yuqaatiloo qawmahum, wa law shaaa\'al laahu lasallatahum \'alaikum falaqaatalookum; fa ini\' tazalookum falam yuqaatilookum wa alqaw ilaikumus salama famaa ja\'alal laahu lakum \'alaihim sabeelaa'),
  ('en.transliteration', 4, 91, 'Satajidoona aakhareena yureedoona ai yaamanookum wa yaamanoo qawmahum kullamaa ruddooo ilal itnati urkisoo feehaa; fa il lam ya\'tazilookum wa yulqooo ilai kumus salama wa yakuffooo aidiyahum fakhuzoohum waqtuloohum haisu saqif tumoohum; wa ulaaa\'ikum ja\'alnaa lakum \'alaihim sultaanam mubeenaa'),
  ('en.transliteration', 4, 92, 'Wa maa kaana limu\'minin ai yaqtula mu\'minan illaa khata\'aa; waman qatala mu\'minan khata\'an fatabreeru raqabatim mu\'minatinw wa diyatum mmusallamatun ilaaa ahliheee illaaa ai yassaddaqoo; fa in kaana min qawmin \'aduwwil lakum wa huwa mu\'minun fatabreeru raqabatim mu\'minah; wa in kaana min qawmim bainakum wa bainahum meesaaqun fadiyatum mmusallamatun ilaaa ahlihee wa tahreeru raqabatim mu\'minatin famal lam yajid fa Siyaamu shahraini mutataabi\'aini tawhatam minal laah; wa kaanal laahu \'Aleeman hakeemaa'),
  ('en.transliteration', 4, 93, 'Wa mai yaqtul mu\'minammuta \'ammidan fajazaaa\'uhoo Jahannamu khaalidan feehaa wa ghadibal laahu\' alaihi wa la\'anahoo wa a\'adda lahoo \'azaaban \'azeemaa'),
  ('en.transliteration', 4, 94, 'Yaaa aiyuhal lazeena aamanoo izaa darabtum fee sabeelil laahi fatabaiyanoo wa laa taqooloo liman alqaaa ilaikumus salaama lasta mu\'minan tabtaghoona \'aradal hayaatid dunyaa fa\'indal laahi maghaanimu kaseerah; kazaalika kuntum min qablu famannnal laahu \'alaikum fatabaiyanoo; innallaaha kaana bimaa ta\'maloona Khabeeraa'),
  ('en.transliteration', 4, 95, 'Laa yastawil qaa\'idoona Minal mu\'mineena ghairu ulid darari walmujaahidoona fee sabeelil laahi bi amwaalihim wa anfusihim; faddalal laahul mujaahideena bi amwaalihim wa anfusihim; faddalal laahul mujaahideena bi am waalihim wa anfusihim \'alalqaa\'ideena darajab; wa kullanw wa\'adal laahul husnaa; wa faddalal laahul mujaahideena \'alal qaa\'ideena ajran \'azeemaa'),
  ('en.transliteration', 4, 96, 'Darajaatim minhu wa maghfiratanw wa rahmah; wa kaanal laahu Ghafoorar Raheema'),
  ('en.transliteration', 4, 97, 'Innal lazeena tawaffaa humul malaaa\'ikatu zaalimeee anfusihim qaaloo feema kuntum qaaloo kunnaa mustad\'afeena fil-ard; qaalooo alam takun ardul laahi waasi\'atan fatuhaajiroo feehaa; fa ulaaa\'ika maawaahum Jahannamu wa saaa\'at maseeraa'),
  ('en.transliteration', 4, 98, 'Illal mustad \'afeena minar rijaali wannisaaa\'i walwildaani laa yastatee\'oona heelatanw wa laa yahtadoona sabeela'),
  ('en.transliteration', 4, 99, 'Fa ulaaa\'ika \'asal laahu ai ya\'fuwa \'anhum; wa kaanal laahu \'Afuwwan Ghafooraa'),
  ('en.transliteration', 4, 100, 'Wa mai yuhaajir fee sabeelil laahi yajid fil ardi mmuraaghaman kaseeranw wa sa\'ah; wa mai yakhruj mim baitihee muhaajiran ilal laahi wa Rasoolihee summa yudrikhul mawtu faqad waqa\'a ajruhoo \'alal laah; wa kaanal laahu Ghafoorar Raheemaa'),
  ('en.transliteration', 4, 101, 'Wa izaa darabtum fil ardi falaisa \'alaikum junaahun an taqsuroo minas Salaati in khiftum ai yaftinakumul lazeena kafarooo; innal kaafireena kaanoo lakum aduwwam mubeenaa'),
  ('en.transliteration', 4, 102, 'Wa izaa kunta feehim fa aqamta lahumus Salaata faltaqum taaa\'ifatum minhum ma\'aka walyaakhuzooo aslihatahum fa izaa sajadoo fal yakoonoo minw waraaa\'ikum waltaati taaa\'ifatun ukhraa lam yusalloo falyusallo ma\'aka walyaakhuzoo hizrahum wa aslihatahum; waddal lazeena kafaroo law taghfuloona \'anaslihatikum wa amti\'atikum fa yameeloona \'alaikum mailatanw waahidah; wa laa junaaha \'alaikum in kaana bikum azam mimmatarin aw kuntum mmardaaa an tada\'ooo aslihatakum wa khuzoo hizrakum; innal laaha a\'adda lilkaafireena \'azaabam muheenaa'),
  ('en.transliteration', 4, 103, 'Fa izaa qadaitumus Salaata fazkurul laaha qiyaamanw wa qu\'oodanw wa \'alaa junoobikum; fa izat maanantum fa aqeemus Salaah; innas Salaata kaanat \'alal mu\'mineena kitaabam mawqootaa'),
  ('en.transliteration', 4, 104, 'Wa laa tahinoo fibtighaaa\'il qawmi in takoonoo taalamoona fa innahum yaalamoona kamaa taalamoona wa tarjoona minal laahi maa laa yarjoon; wa kaanal laahu \'Aleeman Hakeemaa'),
  ('en.transliteration', 4, 105, 'Innaaa anzalnaaa ilaikal Kitaaba bilhaqqi litahkuma bainan naasi bimaaa araakal laah; wa laa takul lilkhaaa\'ineena khaseemaa'),
  ('en.transliteration', 4, 106, 'Wastaghfiril laaha innal laaha kaana Ghafoorar Raheema'),
  ('en.transliteration', 4, 107, 'Wa laa tujaadil \'anil lazeena yakhtaanoona anfusahum; innal laaha laa yuhibbuman kaana khawwaanan aseemaa'),
  ('en.transliteration', 4, 108, 'Yastakhfoona minannaasi wa laa yastakh foona minal laahi wa huwa ma\'ahum iz yubaiyitoona maa laa yardaa minal qawl; wa kaanal laahu bimaa ya\'maloona muheetaa'),
  ('en.transliteration', 4, 109, 'haaa antum haaa\'ulaaa\'i jaadaltum \'anhum fil hayaatid dunyaa famai yujaadilul laaha \'anhum Yawmal Qiyaamati am mai yakoonu \'alaihim wakeelaa'),
  ('en.transliteration', 4, 110, 'Wa mai ya\'mal sooo\'an aw yazlim nafsahoo summa yastaghfiril laaha yajidil laaha Ghafoorar Raheemaa'),
  ('en.transliteration', 4, 111, 'Wa mai yaksib isman fa innamaa yaksibuhoo \'alaa nafsih; wa kaanal laahu \'Aleeman hakeemaa'),
  ('en.transliteration', 4, 112, 'Wa mai yaksib khateee\'atan aw isman summa yarmi bihee bareee\'an faqadih tamala buhtaananw wa ismam mubeenaa'),
  ('en.transliteration', 4, 113, 'Wa law laa fadlul laahi \'alaika wa rahmatuhoo lahammat taaa\'ifatum minhum ai yudillooka wa maa yudilloona illaaa anfusahum wa maa yadurroonaka min shai\'; wa anzalal laahu \'alaikal Kitaaba wal Hikmata wa \'allamaka maa lam takun ta\'lam; wa kaana fadlul laahi \'alaika \'azeemaa'),
  ('en.transliteration', 4, 114, 'laa khaira fee kaseerim min najwaahum illaa man amara bisadaqatin aw ma\'roofin aw islaahim bainan naas; wa mai yaf\'al zaalikab tighaaa\'a mardaatil laahi fa sawfa nu\'teehi ajran \'azeemaa'),
  ('en.transliteration', 4, 115, 'Wa mai yushaaqiqir Rasoola mim ba\'di maa tabaiyana lahul hudaa wa tattabi\' ghaira sabeelil mu\'mineena nuwallihee ma tawallaa wa nuslihee Jahannama wa saaa\'at maseeraa'),
  ('en.transliteration', 4, 116, 'Innal laaha laa yaghfiru ai yushraka bihee wayaghfiru maa doona zaalika limai yashaaa\'; wa mai yushrik billaahi faqad dalla dalaalam ba\'eedaa'),
  ('en.transliteration', 4, 117, 'iny yad\'oona min dooniheee illaaa inaasanw wa iny yad\'oona illaa Shaitaanam mareedaa'),
  ('en.transliteration', 4, 118, 'La\'anahul laah; wa qaala la attakhizanna min \'ibaadika naseebam mafroodaa'),
  ('en.transliteration', 4, 119, 'Wa la udillannahum wa la umanni yannnahum wa la aamurannahum fala yubat tikunna aazaanal lan\'aami wa la aamurannahum fala yughai yirunna khalqal laah; wa mai yattakhizish Shaitaana waliyyam mmin doonil laahi faqad khasira khusraanam mubeena'),
  ('en.transliteration', 4, 120, 'Ya\'iduhum wa yuman neehim wa maa ya\'iduhumush Shaitaanu illaa ghurooraa'),
  ('en.transliteration', 4, 121, 'Ulaaa\'ika maawaahum Jahannamu wa laa yajidoona \'anhaa maheesaa'),
  ('en.transliteration', 4, 122, 'Wallazeena aamanoo wa \'amilus saalihaati sanud khiluhum Jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa; wa\'dal laahi haqqaa; wa man asdaqu minal laahi qeelaa'),
  ('en.transliteration', 4, 123, 'Laisa bi amaaniyyikum wa laaa amaaniyyi Ahlil Kitaab; mai ya\'mal sooo\'ai yujza bihee wa laa yajid lahoo min doonil laahi waliyanw wa laa naseeraa'),
  ('en.transliteration', 4, 124, 'Wa mai ya\'mal minas saalihaati min zakarin aw unsaa wa huwa mu\'minun fa ulaaa\'ika yadkhuloonal Jannata wa laa yuzlamoona naqeeraa'),
  ('en.transliteration', 4, 125, 'Wa man ahsanu deenam mimmman aslama wajhahoo lillaahi wa huwa muhsinunw wattaba\'a Millata Ibraaheema haneefaa; wattakhazal laahu Ibraaheema khaleelaa'),
  ('en.transliteration', 4, 126, 'Wa lillaahi maa fis samaawaati wa maa fil ard; wa kaanal laahu bikulli shai\'im muheetaa'),
  ('en.transliteration', 4, 127, 'Wa yastaftoonaka finnisaaa\'i qulil laahu yufteekum feehinna wa maa yutlaa \'alaikum fil Kitaabi fee yataaman nisaaa\'il laatee laa tu\'toonahunna mmaa kutiba lahunnna wa targhaboona an tankihoohunna wal mustad\'a feena minal wildaani wa an taqoomoo lilyataamaa bilqist; wa maa taf\'aloo min khairin fa innal laaha kaana bihee \'Aleemaa'),
  ('en.transliteration', 4, 128, 'Wa inimra atun khaafat mim ba\'lihaa nushoozan aw i\'raadan falaa junaaha \'alaihi maaa ai yuslihaa bainahumaa sulhaa; wassulhu khair; wa uhdiratil anfusush shuhh; wa in tuhsinoo wa tattaqoo fa innal laaha kaana bimaa ta\'maloona Khabeeraa'),
  ('en.transliteration', 4, 129, 'Wa lan tastatee\'ooo an ta\'diloo bainan nisaaa\'i wa law harastum falaa tameeloo kullal maili fatazaroohaa kalmu\'al laqah; wa in tuslihoo wa tattaqoo fa innal laaha kaana Ghafoorar Raheema'),
  ('en.transliteration', 4, 130, 'Wa iny-yatafarraqaa yughnil laahu kullam min sa\'atih; wa kaanal laahu Waasi\'an Hakeemaa'),
  ('en.transliteration', 4, 131, 'Wa lillaahi maafis samaawaati wa maa fil ard; wa laqad wassainal lazeena ootul Kitaaba min qablikum wa iyyaakum anit taqul laah; wa intakfuroo fa inna lillaahi maa fis samaawaati wa maa fil ard; wa kaanal laahu Ghaniyyan hameedaa'),
  ('en.transliteration', 4, 132, 'Wa lillaahi maa fis samaawaati wa maa fil ard; wa kafaa billaahi Wakeelaa'),
  ('en.transliteration', 4, 133, 'Iny-yashaa yuzhibkum aiyuhan naasu wa yaati bi aakhareen; wa kaanal laahu \'alaa zaalika Qadeeraa'),
  ('en.transliteration', 4, 134, 'man kaana yureedu sawaabad dunyaa fa\'indallaahi sawaabud dunyaa wal Aakhirah; wa kaanal laahu Samee\'am Baseeraa'),
  ('en.transliteration', 4, 135, 'Yaa aiyuhal lazeena aamanoo koonoo qawwa ameena bilqisti shuhadaaa\'a lillaahi wa law \'alaa anfusikum awil waalidaini wal aqrabeen iny yakun ghaniyyan aw faqeeran fallaahu awlaa bihimaa falaaa tattabi\'ul hawaaa an ta\'diloo; wa in talwooo aw tu\'ridoo fa innal laaha kaana bimaa ta\'maloona Khabeera'),
  ('en.transliteration', 4, 136, 'Yaaa aiyuhal lazeena aamanooo aaminoo billaahi wa Rasoolihee wal Kitaabil lazee nazzala \'alaa Rasoolihee wal Kitaabil lazeee anzala min qabl; wa mai yakfur billaahi wa Malaaa\'ikatihee wa Kutubihee wa Rusulihee wal Yawmil Aakhiri faqad dalla dalaalam ba\'eedaa'),
  ('en.transliteration', 4, 137, 'Innal lazeena aamanoo summa kafaroo summa aamanoo summa kafaroo summaz daado kufral lam yakunil laahu liyaghfira lahum wa laa liyahdiyahum sabeelaa'),
  ('en.transliteration', 4, 138, 'Bashshiril munaafiqeena bi anna lahum \'azaaban aleemaa'),
  ('en.transliteration', 4, 139, 'Allazeena yattakhizoo nal kaafireena awliyaaa\'a min doonil mu\'mineen; a-yabta ghoona \'indahumul \'izzata fainnnal \'izzata lillaahi jamee\'aa'),
  ('en.transliteration', 4, 140, 'Wa qad nazzala \'alaikum fil Kitaabi an izaa sami\'tum Aayaatil laahi yukfaru bihaa wa yustahza u bihaa falaa taq\'udoo ma\'ahum hattaa yakhoodoo fee hadeesin ghairih; innakum izam misluhum; innal laaha jaami\'ul munaafiqeena wal kaafireena fee jahannama jamee\'aa'),
  ('en.transliteration', 4, 141, 'Allazeena yatarab basoona bikum fa in kaana lakum fathum minal laahi qaalooo alam nakum ma\'akum wa in kaana lilkaafireena naseebun qaalooo alam nastah wiz \'alaikum wa nammna\'kum minal mu\'mineen; fallaahu yahkumu bainakum Yawmal Qiyaamah; wa lai yaj\'alal laahu lilkaafireena \'alal mu\'mineena sabeelaa'),
  ('en.transliteration', 4, 142, 'Innal munaafiqeena yukhaadi\'oonal laaha wa huwa khaadi\'uhum wa izaa qaamooo ilas Salaati qaamoo kusaalaa yuraaa\'oonan naasa wa laa yazkuroonal laaha illaa qaleelaa'),
  ('en.transliteration', 4, 143, 'Muzabzabeena baina zaalika laaa ilaa haaa\' ulaaa\'i wa laaa ilaa haaa\'ulaaa\'; wa mai yudlilil laahu falan tajida lahoo sabeela'),
  ('en.transliteration', 4, 144, 'Yaaa aiyuhal lazeena aamanoo laa tattakhizul kaafireena awliyaaa\'a min doonil mu\'mineen; aturee doona an taj\'aloo lillaahi \'alaikum sultaanam mubeenaa'),
  ('en.transliteration', 4, 145, 'Innal munaafiqeena fiddarkil asfali minan Naari wa lan tajjida lahum naseeraa'),
  ('en.transliteration', 4, 146, 'Illal lazeena taaboo wa aslahoo wa\'tasamoo billaahi wa akhlasoo deenahum lillaahi faulaaa\'ika ma\'al mu\'mineena wa sawfa yu\'til laahul mu\'mineena ajran \'azeemaa'),
  ('en.transliteration', 4, 147, 'maa yafa\'lul laahu bi \'azaabikum in shakartum wa aamantum; wa kaanal laahu Shaakiran \'Aleema'),
  ('en.transliteration', 4, 148, 'Laa yuhibbullaahul jahra bis sooo\'i minal qawli illaa man zulim; wa kaanallaahu Samee\'an \'Aleeman'),
  ('en.transliteration', 4, 149, 'in tubdoo khairann aw tukhfoohu aw ta\'foo \'an sooo\'in fa innal laaha kaana \'afuwwan Qadeeraa'),
  ('en.transliteration', 4, 150, 'Innal lazeena yakkfuroona billaahi wa Rusulihee wa yureedoona ai yufarriqoo bainal laahi wa Rusulihee wa yaqooloona nu\'minu biba\'dinw wa nakfuru biba\' dinw wa yureedoona ai yattakhizoo baina zaalika sabeelaa'),
  ('en.transliteration', 4, 151, 'Ulaaa\'ika humul kaafiroona haqqaa; wa a\'tadnaa lilkaafireena \'azaabam muheenaa'),
  ('en.transliteration', 4, 152, 'Wallazeena aamanoo billaahi wa Rusulihee wa lam yufarriqoo baina ahadim minhum ulaaa\'ika sawfa yu\'teehim ujoorahum; wa kaanal laahu Ghafoorar Raheema'),
  ('en.transliteration', 4, 153, 'yas\'aluka Ahlul Kitaabi an tunazzila \'alaihim Kitaabam minas samaaa\'i faqad sa aloo Moosaa akbara min zaalika faqaaloo arinal laaha jahratan fa akhazat humus saa\'iqatu bizulmihim; summat takhazul \'ijla mim ba\'di maa jaa\'at humul baiyinaatu fa\'afawnaa \'ann zaalik; wa aatainaa Moosaa sultaanam mubeenaa'),
  ('en.transliteration', 4, 154, 'Wa rafa\'naa fawqahumut Toora bimeesaaqihim wa qulnaa lahumud khulul baaba sujjadanw wa qulnaa lahum laa ta\'doo fis Sabti wa akhaznaa minhum meesaaqan ghaleezaa'),
  ('en.transliteration', 4, 155, 'Fabimaa naqdihim meesaaqahum wa kufrihim bi Aayaatil laahi wa qatlihimul Ambiyaaa\'a bighairi haqqinw wa qawlihim quloobunna ghulf; bal taba\'al laahu \'alaihaa bikufrihim falaa yu\'minoona illaa qaleelaa'),
  ('en.transliteration', 4, 156, 'Wa bikufrihim wa qawlihim \'alaa Maryama buh taanan \'azeema'),
  ('en.transliteration', 4, 157, 'Wa qawlihim innaa qatal nal maseeha \'Eesab-na-Maryama Rasoolal laahi wa maa qataloohu wa maa salaboohu wa laakin shubbiha lahum; wa innal lazeenakh talafoo fee lafee shakkim minh; maa lahum bihee min \'ilmin illat tibaa\'az zann; wa maa qataloohu yaqeenaa'),
  ('en.transliteration', 4, 158, 'Bar rafa\'ahul laahu ilayh; wa kaanal laahu \'Azeezan Hakeemaa'),
  ('en.transliteration', 4, 159, 'Wa im min Ahlil Kitaabi illaa layu\'minanna bihee qabla mawtihee wa Yawmal Qiyaamati yakoonu \'alaihim shaheedaa'),
  ('en.transliteration', 4, 160, 'Fabizulmin minal lazeena haadoo harramnaa \'alaihim taiyibaatin uhillat lahum wa bisadihim \'an sabeelil laahi kaseeraa'),
  ('en.transliteration', 4, 161, 'Wa akhzihimur ribaa wa qad nuhoo \'anhu wa aklihim amwaalan naasi bilbaatil; wa a\'tadnaa lilkaafireena minhum \'azaaban aleema'),
  ('en.transliteration', 4, 162, 'Laakinir raasikhoona fil\'ilmi minhum walmu\'minoona yu\'minoona bimaaa unzila ilaika wa maaa unzila min qablika walmuqeemeenas Salaata walmu\'toonaz Zakaata walmu \'minoona billaahi wal yawmil Aakhir; ulaaa\'ika sanu\'teehim ajran \'azeemaa'),
  ('en.transliteration', 4, 163, 'innaaa awhainaaa ilaika kamaaa awhainaaa ilaa Noohinw wan nabiyyeena mim ba\'dih; wa awhainaaa ilaaa ibraaheema wa Ismaaa\'eela wa Ishaaqa wa Ya\'qooba wal Asbaati wa \'Eesaa wa Ayyooba wa Yoonusa wa haaroona wa Sulaimaan; wa aatainaa Daawooda Zabooraa'),
  ('en.transliteration', 4, 164, 'Wa Rusulan qad qasas naahum \'alaika min qablu wa Rusulal lam naqsushum \'alaik; wa kallamallaahu Moosaa takleemaa'),
  ('en.transliteration', 4, 165, 'Rusulam mubashshireena wa munzireena li\'allaa yakoona linnaasi \'alal laahi hujjatum ba\'dar Rusul; wa kaanallaahu \'Azeezan Hakeema'),
  ('en.transliteration', 4, 166, 'Laakinil laahu yashhadu bimaaa anzala ilaika anzalahoo bi\'ilmihee wal malaaa\'ikatu yashhadoon; wa kafaa billaahi Shaheeda'),
  ('en.transliteration', 4, 167, 'Innal lazeena kafaroo wa saddoo \'an sabeelil laahi qad dalloo dalaalam ba\'eedaa'),
  ('en.transliteration', 4, 168, 'Innal lazeenakafaroo wa zalamoo lam yakkunillaahu liyaghfira lahum wa laa liyahdiyahum tareeqaa'),
  ('en.transliteration', 4, 169, 'Illaa tareeqa jahannamma khaalideena feehaa abadaa; wa kaana zaalika \'alal laahi yaseeraa'),
  ('en.transliteration', 4, 170, 'Yaaa aiyuhan naasu qad jaaa\'akumur Rasoolu bilhaqqi mir Rabbikum fa ammminoo khairal lakum; wa in takfuroo fainnna lillaahi maa fis samaawaati wal ard; wa kaanal laahu \'Aleemann hakeemaa'),
  ('en.transliteration', 4, 171, 'Yaaa Ahlal Kitaabi laa taghloo fee deenikum wa laa taqooloo \'alal laahi illalhaqq; innamal Maseehu \'Eesab-nu-Maryamma Rasoolul laahi wa Kalimatuhooo alqaahaaa ilaa Maryamma wa roohum minhum fa aaminoo billaahi wa Rusulihee wa laa taqooloo salaasah; intahoo khairallakum; innamal laahu Ilaahunw Waahid, Subhaanahooo ani yakoona lahoo walad; lahoo maa fissamaawaati wa maa fil ard; wa kafaa billaahi Wakeelaa'),
  ('en.transliteration', 4, 172, 'Lanny yastankifal Maseehu ai yakoona \'abdal lillaahi wa lal malaaa\'ikatul muqarraboon; wa mai yastankif \'an ibaadatihee wa yastakbir fasa yahshuruhum ilaihi jamee\'aa'),
  ('en.transliteration', 4, 173, 'Fa ammal lazeena aamanoo wa \'amilus saalihaati fa yuwaffeehim ujoorahum wa yazeeduhum min fadlihee wa ammal lazeenas tankafoo wastakbaroo fa yu\'azzibuhum \'azaaban aleemanw wa laa yajidoona lahum min doonil laahi waliyyanw wa laa naseeraa'),
  ('en.transliteration', 4, 174, 'yaa aiyuhan naasu qad jaaa\'akum burhaanum mir Rabbikum wa anzalnaaa ilaikum Nooram Mubeena'),
  ('en.transliteration', 4, 175, 'Fa ammal lazeena aamanoo billaahi wa\'tasamoo bihee fasa yudkhiluhum fee rah matim minhu wa fadlinw wa yahdeehim ilaihi Siraatam Mustaqeema'),
  ('en.transliteration', 4, 176, 'Yastaftoonaka qulillaahu yafteekum fil kalaalah; inimru\'un halaka laisa lahoo waladunw wa lahoo ukhtun falahaa nisfu maa tarak; wa huwa yarisuhaaa il lam yakkul lahaa walad; fa in kaanatas nataini falahumas sulusaani mimmmaa tarak; wa in kaanooo ikhwatar rijaalanw wa nisaaa\'an faliz zakari mislu hazzil unsayayn; yubaiyinullaahu lakum an tadilloo; wallaahu bikulli shai\'in Aleem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 4, 1, 'اے لوگو اپنے رب سے ڈرو جس نے تمہیں ایک جان سے پیدا کیا اور اسی جان سے اس کا جوڑا بنایا اور ان دونوں سے بہت سے مرد اور عورتیں پھیلائیں اس اللہ سے ڈرو جس کا واسطہ دے کر تم ایک دوسرے اپنا حق مانگتے ہو اور رشتہ داری کے تعلقات کو بگاڑنے سے بچو بے شک الله تم پر نگرانی کر رہا ہے'),
  ('ur.ahmedali', 4, 2, 'اوریتیموں کوان کے مال دے دو اور ناپاک کو پاک سے نہ بدلو اور ان کے مال اپنے مال کے ساتھ ملا کر نہ کھا جاؤ یہ بڑا گناہ ہے'),
  ('ur.ahmedali', 4, 3, 'اور اگر تم یتیم لڑکیوں سے بے انصافی کرنے سے ڈرتے ہوتوجوعورتیں تمہیں پسند آئیں ان میں سے دو دو تین تین چار چار سے نکاح کر لو اگر تمہیں خطرہ ہو کہ انصاف نہ کر سکو گے تو پھر ایک ہی سے نکاح کرو جو لونڈی تمہارے ملک میں ہو وہی سہی یہ طریقہ بے انصافی سے بچنے کے لیے زیادہ قریب ہے'),
  ('ur.ahmedali', 4, 4, 'اور عورتوں کو ان کے مہر خوشی سے دے دو پھر اگر وہ اس میں سے اپنی خوشی سے تمہیں کچھ معاف کر دیں تو تم اسے مزہ دار خوشگوار سمجھ کر کھاؤ'),
  ('ur.ahmedali', 4, 5, 'اور اپنے وہ مال جنہیں الله نے تمہاری زندگی کے قیام کا ذریعہ بنایا ہے بے سمجھو کے حوالے نہ کرو البتہ انہیں ان مالوں سے کھلاتے او رپہناتے رہو اور انہیں نصیحت کی بات کہتے رہو'),
  ('ur.ahmedali', 4, 6, 'اور یتیموں کی آزمائش کرتے رہو یہاں تک کہ وہ نکاح کی عمر کو پہنچ جائیں پھر اگر ان میں ہوشیاری دیکھو تو ان کے مال ان کے حوالے کر دو اور انصاف کی حد سے تجاوز کر کے یتیموں کا مال نہ کھا جاؤ اور ان کے بڑے ہونے کے ڈر سے ان کا مال جلدی نہ کھاؤ اور جسے ضرورت نہ ہو تو وہ یتیم کے مال سے بچے او رجو حاجت مند ہو تو مناسب مقدار کھالے پھر جب ان کے مال ان کے حوالے کر و تو اس پر گواہ بنا لو اور حساب لینے کے لیے الله کافی ہے'),
  ('ur.ahmedali', 4, 7, 'مردوں کا اس مال میں حصہ ہے جو ماں باپ اور رشتہ داروں نے چھوڑا ہو اور عورتوں کا بھی اس مال میں حصہ ہے جو ماں باپ اور رشتہ دارو ں نے چھوڑا ہو تھوڑا ہو یہ بہت یہ حصہ مقرر ہے'),
  ('ur.ahmedali', 4, 8, 'اور جب تقسیم کے وقت رشتہ دار اور یتیم اور مسکین آئيں تو اس مال میں سے کچھ انہیں بھی دے دو اور ان کو معقول بات کہہ دو'),
  ('ur.ahmedali', 4, 9, 'اور ایسے لوگو ں کو ڈرنا چاہيے اگر اپنے بعد چھوٹے چھوٹے بچے چھوڑ جائیں جن کی انہیں فکر ہو ان لوگو ں کو چاہیئے کہ خدا سے ڈریں اور سیدھی بات کہیں'),
  ('ur.ahmedali', 4, 10, 'بے شک جو لوگ یتیموں کا مال ناحق کھاتے ہیں وہ اپنے پیٹ آگ سے بھرتے ہیں اور عنقریب آگ میں داخل ہوں گے'),
  ('ur.ahmedali', 4, 11, 'الله تعالیٰ تمہاری اولاد کے حق میں تمہیں حکم دیتا ہے کہ ایک مرد کا حصہ دوعورتوں کے برابر ہے پھر اگر دو سے زاید لڑکیاں ہوں تو ا ن کے لیے دو تہائی اس مال میں سے ہے جو میت نے چھوڑا اور اگر ایک ہی لڑکی ہو تو اس کے لیے آدھا ہے اور اگر میت کی اولاد ہے تو اس کے والدین میں سے ہر ایک کو کل مال کا چھٹا حصہ ملنا چاہیئے اور اگر اس کی کوئی اولاد نہیں اور ماں باپ ہی اس کے وارث ہیں تو اس کی ماں کا ایک تہائی حصہ ہے پھر اگر میت کے بھائی بہن بھی ہوں تو اس کی ماں کا چھٹا حصہ ہے (یہ حصہ اس) وصیت کے بعد ہوگا جو وہ کر گیا تھا اور بعد ادا کرنے قرض کے تم نہیں جانتے تمہارے باپوں اور تمہارے بیٹوں میں سے کون تمہیں زیادہ نفع پہنچانے والا ہے الله کی طرف سے یہ حصہ مقرر کیا ہوا ہے بے شک الله خبردار حکمت والا ہے'),
  ('ur.ahmedali', 4, 12, 'جو مال تمہارحی عورتیں چھوڑ مریں اس میں تمہارا آدھا حصہ ہے بشرطیکہ ان کی اولاد نہ ہو او راگر ان کی اولاد ہو تو اس میں سےجو چھوڑ جائیں ایک چوتھائي تمہاری ہے اس وصیت کے بعد جو وہ کر جائیں یا قرض کے بعد اور عورتوں کے لیے چوتھائی مال ہے جو تم چھوڑ کر مرو بشرطیکہ تمہاری اولاد نہ ہوپس اگر تمہاری اولاد ہو تو جو تم نے چھوڑا اس میں ان کا آٹھواں حصہ ہے اس وصیت کے بعد جو تم کر جاؤ یا قرض کے بعد اوراگر وہ مرد یا عورت جس کی یہ میراث ہے باپ بیٹا کچھ نہیں رکھتا اور اس میت کا ایک بھائي یا بہن ہے تو دونوں میں سے ہر ایک کا چھٹا حصہ ہے پس اگر اس سے زیادہ ہوں تو ایک تہائی میں سب شریک ہیں وصیت کی بات جوہو چکی ہو یا قرض کے بعد بشرطیکہ اورروں کا نقصان نہ ہو یہ الله کا حکم ہے اور الله جاننے والا تحمل کرنے والا ہے'),
  ('ur.ahmedali', 4, 13, 'یہ الله کی باندھی ہوئی حدیں ہیں اور جو شخص الله اور اس کے رسول کے حکم پر چلے اسے بہشتوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہوں گی ان میں ہمیشہ رہیں گے اور یہی ہے بڑی کامیابی'),
  ('ur.ahmedali', 4, 14, 'اور جو شخص الله اور اس کے رسول کی نافرمانی کرے اوراس کی حدوں سے نکل جائے اسے آگ میں ڈالے گا اس میں ہمیشہ رہے گا اور اس کے لیے ذلت کا عذاب ہے'),
  ('ur.ahmedali', 4, 15, 'اور تمہاری عورتوں میں سے جوکوئی بدکاری کرے ان پر اپنوں میں سے چار مرد گواہ لاؤ پھر اگر وہ گواہی دے دیں تو ان عورتوں کو ان گھروں میں بند رکھو یہاں تک کہ انہیں موت آ جائے یا الله ان کے لیے کوئی راستہ نکال دے'),
  ('ur.ahmedali', 4, 16, 'اور تم میں سے جو دو مرد وہی بدکاری کریں تو ان کو تکلیف دو پھر اگر وہ توبہ کریں اور اپنی اصلاح کرلیں تو انہیں چھوڑ دو بےشک الله توبہ قبول کرنے والا مہربان ہے'),
  ('ur.ahmedali', 4, 17, 'الله پر توبہ قبول کرنے کا حق انہیں لوگو ں کے لیے ہے جو جہالت کی وجہ سے برا کام کرتے ہیں اس کے بعد جلد ہی توبہ کر لیتے ہیں ان لوگو ں کو الله معاف کر دیتا ہے اور الله سب کچھ جاننے والا دانا ہے'),
  ('ur.ahmedali', 4, 18, 'اور ان لوگوں کی توبہ قبول نہیں ہے جو برے کام کرتےرہتے ہیں یہاں تک کہ جب ان میں سے کسی کی موت کا وقت آ جاتا ہے اس وقت کہتا ہے کہ اب میں توبہ کرتا ہوں اوراسی طرح ان لوگو ں کی توبہ قبول نہیں ہے جو کفر کی حالت میں مرتے ہیں ان کے لیے ہم نے دردناک عذاب تیار کیا ہے'),
  ('ur.ahmedali', 4, 19, 'اے ایمان والو! تمہیں یہ حلال نہیں کہ زبردستی عورتوں کو میراث میں لے لو اور ان کو اس واسطے نہ روکے رکھو کہ ان سے کچھ اپنا دیا ہوا مال واپس لے لو ہاں اگر وہ کسی صریح بدچلنی کا ارتکاب کریں اور عورتوں کے ساتھ اچھی طرح سے زندگی بسر کرو اگر وہ تمہیں نا پسند ہوں تو ممکن ہے کہ تمہیں ایک چیز پسند نہ آئے مگر الله نے اس میں بہت کچھ بھلائی رکھی ہو'),
  ('ur.ahmedali', 4, 20, 'اور اگر تم ایک عورت کی جگہ دوسری عورت کو بدلنا چاہو اور ایک کو بہت سا مال دے چکے ہو تو اس میں سے کچھ بھی واپس نہ لو کیا تم اسے بہتان لگا کر اور صریح ظلم کر کے واپس لو گے'),
  ('ur.ahmedali', 4, 21, 'تم اسے کیوں کر لے سکتے ہو جب کہ تم میں سے ہر ایک دوسرے سے لطف اندوز ہو چکا ہے اور وہ عورتیں تم سے پختہ عہد لے چکی ہیں'),
  ('ur.ahmedali', 4, 22, 'ان عورتوں سے نکاح نہ کرو جن سے تمہارے ماں باپ نکاح کر چکے ہیں مگر جو پہلے ہو چکا بے حیائی ہے اور غضب کا کام ہے اور برا چلن ہے'),
  ('ur.ahmedali', 4, 23, 'تم پر تمہاری مائیں اور بیٹیاں اور بہنیں اور پھوپھیاں اور خالائیں اور بھتیجیاں اور بھانجیاں اور جن ماؤں نے تمہیں دودھ پلایا اور تمہاری دودھ شریک بہنیں اور تمہاری عورتوں کی مائیں اور ان کی بیٹیاں جنہوں نے تمہاری گود میں پرورش پائی ہے ان بیویو ں کی لڑکیاں جن سے تمہار تعلق زن و شو ہو چکاہے اور اگر تعلق زن و شو نہ ہوا ہو تو تم پر اس نکاح میں کچھ گناہ نہیں اور تمہارے بیٹو ں کی عورتیں جو تمہاری پشت سے ہیں یہ سب عورتیں تم پر حرام ہیں اور دو بہنوں کو (ایک نکاح میں) اکھٹا کرنا حرام ہے مگر جو پہلے ہو چکا بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 4, 24, 'اور خاوند والی عورتیں مگر تمہارے ہاتھ جن کے مالک ہو جائیں یہ الله کا قانون تم پر لازم ہے اور ان کے سوا تم پرسب عورتیں حلال ہیں بشرطیکہ انہیں اپنے مال کے بدلے میں طلب کرو ایسے حال میں کہ نکاح کرنے والے ہو نہ یہ کہ آزاد شہوت رانی کرنے لگو پھر ان عورتوں میں سے جسے تم کام میں لائے ہو تو ان کے حق جو مقرر ہوئے ہیں وہ انہیں دے دو البتہ مہر کے مقرر ہو جانے کے بعد آپس کی رضا مندی سے باہمی کوئی سمجھوتہ ہو جائے تو اس میں کوئی گناہ نہیں بے شک الله خبردار حکمت والا ہے'),
  ('ur.ahmedali', 4, 25, 'اور جو کوئی تم میں سے اس بات کی طاقت نہ رکھے کہ خاندانی مسلمان عورتیں نکاح میں لائے تو تمہاری ان لونڈیو ں میں سے کسی سے نکاح کر لے جو تمہارے قبضے میں ہوں اور ایماندار بھی ہوں اور الله تمہارے ایمانو ں کا حال خوب جانتا ہے تم آپس میں ایک ہو لہذا ان کے مالکوں کی اجازت سے ان سے نکاح کر لو اور دستور کے موافق ان کے مہر دے دو در آنحالیکہ نکاح میں آنے والیاں ہو ں آزاد شہوت رانیاں کرنے والیاں نہ ہوں اور نہ چھپی یاری کرنے والیاں پھر جب وہ قید نکاح میں آجائیں پھر اگر بے حیائی کا کام کریں تو ان پرآدھی سزاہے جو خاندانی عورتوں پر مقرر کی گئی ہے یہ سہولت اس کیلئے ہے جوکوئی تم سے تکلیف میں پڑنے سے دڑےاور صبر کروتو تمہارےحق میں بہتر ہے اور اللہ بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 4, 26, 'الله چاہتا ہے کہ تمہارے واسطے بیان کرے اور تمہیں پہلوں کی راہ پر چلائے اور تمہاری توبہ قبول کرے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 4, 27, 'اور الله چاہتا ہے کہ تم پر اپنی رحمت سے متوجہ ہو اور جو لوگ اپنے مزوں کے پیچھے لگے ہوئے ہیں وہ چاہتے ہیں کہ تم راہ راست سے بہت دور ہٹ جاؤ'),
  ('ur.ahmedali', 4, 28, 'اللہ چاہتا ہے کہ تم سے بوجھ ہلکا کر دے کیوں کہ انسان کمزور پیدا کیا گیا ہے'),
  ('ur.ahmedali', 4, 29, 'اے ایمان والو! آپس میں ایک دوسرے کے مال نا حق نہ کھاؤ مگر یہ کہ آپس کی خوشی سے تجارت ہو اور آپس میں کسی کو قتل نہ کرو بے شک اللہ تم پر مہربان ہے'),
  ('ur.ahmedali', 4, 30, 'اور جو شخص تعدّی اور ظلم سے یہ کام کرے گا تو ہم اسے آگ میں ڈالیں گے اور یہ اللہ پر آسان ہے'),
  ('ur.ahmedali', 4, 31, 'اگر تم ان بڑے گناہوں سے بچو گے جن سے تمہیں منع کیا گیا تو ہم تم سے تمہارے چھوٹے گناہ معاف کردیں گے اور تمہیں عزت کے مقام میں داخل کریں گے'),
  ('ur.ahmedali', 4, 32, 'اور مت ہوس کرو اس فضیلت میں جو الله نے بعض کو بعض پر دی ہے مردوں کو اپنی کمائی سے حصہ ہے اور عورتوں کو اپنی کمائی سے حصہ ہے اور اللہ سے اس کا فضل مانگو بے شک اللہ کو ہر چیز کا علم ہے'),
  ('ur.ahmedali', 4, 33, 'اور ہر شخص کے ہم نے وارث مقرر کر دیئے ہیں اس مال کے جو ماں باپ یا رشتہ دار چھوڑ کر مریں اور وہ لوگ جن سے تمہارے عہد و پیمان ہوں تو انہیں ان کا حصہ دے دو بے شک الله ہر چیز پر گواہ ہے'),
  ('ur.ahmedali', 4, 34, 'مرد عورتوں پر حاکم ہیں اس واسطے کہ الله نے ایک کو ایک پر فضیلت دی ہے اور اس واسطے کہ انہوں نے اپنے مال خرچ کیے ہیں پھر جو عورتیں نیک ہیں وہ تابعدار ہیں مردوں کے پیٹھ پیچھے الله کی نگرانی میں (ان کے حقوق کی) حفاظت کرتی ہیں اور جن عورتو ں سےتمہیں سرکشی کا خطرہ ہو تو انہیں سمجھاؤ اور سونے میں جدا کر دو اور مارو پھر اگر تمہارا کہا مان جائیں تو ان پر الزام لگانے کے لیے بہانے مت تلاش کرو بے شک الله سب سے اوپر بڑا ہے'),
  ('ur.ahmedali', 4, 35, 'اور اگر تمہیں کہیں میاں بیوی کے تعلقات بگڑ جانے کا خطرہ ہو تو ایک منصف مرد کے خاندان میں سے اور ایک منصف عورت کے خاندان میں سے مقرر کرو اگر یہ دونوں صلح کرنا چاہیں گے تو الله ان دونو ں میں موافقت کر دے گا بے شک الله سب کچھ جاننے والا خبردار ہے'),
  ('ur.ahmedali', 4, 36, 'اور الله کی بندگی کرو اورکسی کو اس کا شریک نہ کرو اور ماں باپ کے ساتھ نیکی کرو اور رشتہ داروں اور یتیموں اور مسکینوں اور قریبی ہمسایہ اور اجنبی ہمسایہ اورپاس بیٹھنے والے او رمسافر او راپنے غلاموں کے ساتھ بھی نیکی کرو بے شک الله اترانے والے بڑائی کرنے والے کو پسند نہیں کرتا'),
  ('ur.ahmedali', 4, 37, 'جو لوگ بخل کرتے ہیں اور لوگو ں کو بخل سکھاتے ہیں اور الله نے انہیں اپنے فضل سے جو دیا ہے اسے چھپاتے ہیں اور ہم نے کافروں کے لیے ذلت کا عذاب تیار کر رکھا ہے'),
  ('ur.ahmedali', 4, 38, 'اور جو لوگ اپنے مالوں کو لوگوں کے دکھانے میں خرچ کرتے ہیں اور اللہ پر اور قیامت کے دن پر ایمان نہیں لاتے اور جس کا شیطان ساتھی ہوا تو وہ بہت برا ساتھی ہے'),
  ('ur.ahmedali', 4, 39, 'اور اگر یہ الله اور قیامت کے دن پر ایمان لے آتے اور الله کے دیے ہوئے مال میں سے خرچ کرتے تو ان کا کیا نقصان تھا اور الله انہیں خوب جانتا ہے'),
  ('ur.ahmedali', 4, 40, 'بے شک الله کسی کا ایک ذرہ برابر بھی حق نہیں رکھتا اور اگر نیکی ہو تو اس کو دگنا کر دیتا ہے اور اپنے ہاں سے بڑا ثواب دیتا ہے'),
  ('ur.ahmedali', 4, 41, 'پھر کیا حال ہوگا جب ہم ہر امت میں سے گواہ بلائینگے اور تمیں ان پر گواہ کر کے لائیں گے'),
  ('ur.ahmedali', 4, 42, 'جن لوگو ں نے کفر کیا تھا اور رسول کی نافرمانی کی تھی وہ اس دن کی آرزو کریں گے کہ زمین کے برابر ہو جائیں اور الله سے کوئی بات نہ چھپا سکیں گے'),
  ('ur.ahmedali', 4, 43, 'اے ایمان والو! جس وقت کہ تم نشہ میں ہو نماز کے نزدیک نہ جاؤ یہاں تک کہ تم سمجھو سکوکہ تم کیا کہہ رہے ہو اور جنبی ہونے کی حالت میں مگر راستہ گزرتے ہوئے یہاں تک کہ غسل کر لو اور اگر تم بیمار ہو یا سفر میں ہو یا کوئی شخص تم میں سے رفع حاجت کر کے آئے یا عورتوں کے پاس گئے ہو پھر تمہیں پانی نہ ملے تو پاک مٹی سے کام لو اور اسے اپنے مونہوں پر اور ہاتھوں پر ملو بے شک الله معاف کرنے والا بخشنے والا ہے'),
  ('ur.ahmedali', 4, 44, 'کیا تم نے ان لوگوں کو نہیں دیکھا جنہیں کچھ حصہ کتاب سے ملا ہے وہ گمراہی خریدتے ہیں اور چاہتے ہیں کہ تم بھی راستہ گم کر دو'),
  ('ur.ahmedali', 4, 45, 'اور الله تمہارے دشمنوں کو خوب جانتا ہے اور تمہاری حمایت اور مدد کے لیے الله ہی کافی ہے'),
  ('ur.ahmedali', 4, 46, 'یہودیوں میں بعض ایسے ہیں جو الفاظ کو ان کے محل سے پھیر دیتے ہیں او ر کہتے ہیں ہم نے سنا اور نہ مانا او رکہتے ہیں کہ سن نہ سنایا جائے تو اور کہتے ہیں راعِنا اپنی زبان کو مروڑ کر اور دین میں طعن کرنے کے خیال سےاور اگر وہ کہتے ہیں کہ ہم نے سنا اور ہمنے مانا اور سن تو اور ہم پر نظر کو تو ان کے حق میں بہتر اور درست ہوتا لیکن ان کے کفر کے سبب سے الله نے ا ن پر لعنت کی سو ان میں سے بہت کم لوگ ایمان لائیں گے'),
  ('ur.ahmedali', 4, 47, 'اے کتاب والو اس پر ایمان لے آؤ جو ہم نے نازل کیا ہے اس کتاب کی تصدیق کرتا ہے جو تمہارے پاس ہے اس سے پہلے کہ ہم بہت سے چہرو ں کو مٹا ڈالیں پھر انہیں پیٹھ کیطرف الٹ دیں یا ان پر لعنت کریں جسطرح ہم نے ہفتے کے دن والوں پر لعنت کی تھی اور الله کا حکم تو نافذ ہو کر ہی رہتا ہے'),
  ('ur.ahmedali', 4, 48, 'بے شک الله اسے نہیں بخشتا جو اس کا شریک کرے اور شرک کے ماسوا دوسرےگناہ جسے چاہے بخشتا ہے اور جس نے الله کا شریک ٹھیرایا اس نے بڑا ہی گناہ کیا'),
  ('ur.ahmedali', 4, 49, 'کیا تم نے ان لوگو ں کو نہیں دیکھا جو اپنی پاکیزگی کا دم بھرتے ہیں بلکہ الله جسے چاہے پاک کرتا ہے اور ان پر تاگے کے برابر بھی ظلم نہ ہوگا'),
  ('ur.ahmedali', 4, 50, 'دیکھو یہ لوگ الله پر کیسا جھوٹ باندھتے ہیں یہی ایک صریح گنا ہ کافی ہے'),
  ('ur.ahmedali', 4, 51, 'کیا تم نے ان لوگوں کو نہیں دیکھا جنہیں کتاب کا کچھ حصہ دیا گیا وہ بتوں اور شیطانوں کو مانتے ہیں اور کافروں سے یہ کہتے ہیں کہ یہ لوگ مسلمانوں سے زیادہ راہِ راست پر ہیں'),
  ('ur.ahmedali', 4, 52, 'یہی وہ لوگ ہیں جن پر الله کی لعنت ہے اور جس پر الله لعنت کرے تو اس کا کوئي مددگار نہیں پائے گا'),
  ('ur.ahmedali', 4, 53, 'کیا سلطنت میں ان کا بھی کچھ حصہ ہے پھر تو یہ لوگوں کو ایک تِل بھر بھی نہیں دیں گے'),
  ('ur.ahmedali', 4, 54, 'یا لوگو ں پر حسد کرتے ہیں جو الله نے ان کو اپنے فضل سے دیا ہے ہم نے تو ابراھیم کی اولاد کو کتاب اور حکمت ادا کی ہے اور ان کوہم نے بڑی بادشاہی دی ہے'),
  ('ur.ahmedali', 4, 55, 'پھران میں سے کوئی اس پر ایمان لایا اورکوئی اس سے ہٹ گیا اور دوزخ کی بھڑکتی ہوئی آگ کافی ہے'),
  ('ur.ahmedali', 4, 56, 'بے شک جن لوگو ں نے ہماری آیتوں کا انکار کیا انہیں ہم آگ میں ڈال دیں گے جس وقت ان کی کھالیں جل جائیں گی تو ہم انکو اور کھالیں بدل دیں گے تاکہ عذاب چکھتے رہیں بے شک الله زبردست حکمت والا ہے'),
  ('ur.ahmedali', 4, 57, 'او رجو لوگ ایمان لائے اور نیک کام کیے انہیں ہم ایسے باغوں میں داخل کریں گے جن کے نیچے نہریں بہتی ہوں گی ان میں ہمیشہ ہمیشہ رہنے والے ہوں گے ان کے لیے وہاں ستھری عورتیں ہوں گی اور ہم انہیں گھنی چھاؤں میں رکھیں گے'),
  ('ur.ahmedali', 4, 58, 'بے شک الله تمہیں حکم دیتا ہے کہ امانتیں امانت والوں کو پہنچا دو اور جب لوگوں کے درمیان فیصلہ کرو تو انصاف سے فیصلہ کرو بے شک تمہیں نہایت اچھی نصیحت کرتا ہے بے شک الله سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 4, 59, 'اے ایمان والو الله کی فرمانبرداری کرو اور رسول کی فرمانبرداری کرو اور ان لوگوں کی جو تم میں سے حاکم ہوں پھر اگر آپس میں کوئی چیز میں جھگڑا کرو تو اسے الله اور اس کے رسول کی طرف پھیرو اگر تم الله اور قیامت کے دن پر یقین رکھتے ہو یہی بات اچھی ہے اور انجام کے لحاظ سے بہت بہتر ہے'),
  ('ur.ahmedali', 4, 60, 'کیا تم لوگوں نے ان لوگوں کو نہیں دیکھا جواس چیز پر ایمان لانے کا دعویٰ کرتے ہیں جو تجھ پر نازل کی گئی ہے اور جو چیز تم سےپہلے نازل کی گئی ہے وہ چاہتے ہیں کہ اپنا فیصلہ شیطان سے کرائیں حالانکہ انہیں حکم دیا گیا ہے کہ اسے نہ مانیں اور شیطان تو چاہتا ہے کہ انہیں بہکا کر دو رجا ڈالے'),
  ('ur.ahmedali', 4, 61, 'اور جب انہیں کہا جاتا ہے جو چیز الله نے نازل کی ہے اس کی طرف آؤ اور رسول کی طرف آؤ توتو منافقوں کو دیکھے گا کہ تجھ سے پہلو تہی کرتے ہیں'),
  ('ur.ahmedali', 4, 62, 'پھر کیاہوتا ہے جب ان کے اپنے ہاتھوں سے لائی ہوئی مصیبت ان پر آتی ہے پھر تیرے پاس آ کر خدا کی قسمیں کھاتے ہیں کہ ہم کو تو سوائے بھلائیا ور باہمی موافقت کے اور کوئی غرض نہ تھی'),
  ('ur.ahmedali', 4, 63, 'یہ وہ لوگ ہیں کہ الله جانتا ہے جو ان کے دلوں میں ہے تو ان سے منہ پھیر لے اور انہیں نصیحت کرو ان سے ایسی بات کہو جو ان کے دلوں میں اتر جائے'),
  ('ur.ahmedali', 4, 64, 'اورہم نے کبھی کوئی رسول نہیں بھیجا مگر اسی واسطے کہ الله کے حکم سے اس کی تابعداری کی جائے اور جب انہوں نے اپنے نفسوں پر ظلم کیا تھا تیرے پاس آتے پھر الله سے معافی مانگتے اور رسول بھی ان کی معافی کی درخواست کرتا تو یقیناًیہ الله کو بخشنے والا رحم کرنے والا پاتے'),
  ('ur.ahmedali', 4, 65, 'سو تیرے رب کی قسم ہے یہ کبھی مومن نہیں ہوں گے جب تک کہ اپنے اختلافات میں تجھے منصف نہ مان لیں پھر تیرے فیصلہ پر اپنے دلوں میں کوئی تنگی نہ پائیں اور خوشی سے قبول کریں'),
  ('ur.ahmedali', 4, 66, 'اور اگر ہم ان پر حکم کرتے کہ اپنی جانوں کو ہلاک کر دو یا اپنے گھروں سے نکل جاؤ تو ان میں سے بہت ہی کم آدمی اس پر عمل کرتے اور اگر یہ لوگ کریں جو ان کو نصیحت کی جاتی ہے تو یہ ان کے لیے زیادہ بہتر ہوتا اور دین میں زیادہ ثابت رکھنے والا ہوتا'),
  ('ur.ahmedali', 4, 67, 'اور اس وقت البتہ ہم ان کو اپنے ہاں سے بڑا ثواب دیتے'),
  ('ur.ahmedali', 4, 68, 'اور البتہ انھیں سیدھا راستہ دکھاتے'),
  ('ur.ahmedali', 4, 69, 'اورجو شخص الله اور اس کے رسول کا فرمانبردار ہو تو وہ ان کے ساتھ ہوں گے جن پر الله نے انعام کیا وہ نبی اور صدیق اور شہید اور صالح ہیں اور یہ رفیق کیسے اچھے ہیں'),
  ('ur.ahmedali', 4, 70, 'یہ الله کی طرف سے احسان ہے اور الله کافی ہے جاننے والا'),
  ('ur.ahmedali', 4, 71, 'اے ایمان والو! اپنے ہتھیار لے لو پھر جدا جدا فوج ہو کر نکلویا سب اکھٹے ہوکر نکلو'),
  ('ur.ahmedali', 4, 72, 'اور بے شک تم میں بعض ایسا بھی ہے جو لڑائی سے جی چراتا ہے پھر اگر تم پر کوئی مصیبت آجائے تو کہتا ہے الله نے مجھ پر فضل کیا کہ میں ان لوگوں کے ساتھ نہ تھا'),
  ('ur.ahmedali', 4, 73, 'اور اگر الله کی طرف سے تم پر فضل ہو تو اس طرح کہنے لگتا ہے کہ گویا تمہارے اور اس کے درمیان دوستی کا کوئی تعلق ہی نہیں کہ کاش میں بھی ان کے ساتھ ہوتا تو بڑی مراد پاتا'),
  ('ur.ahmedali', 4, 74, 'سو چاہیئے کہ الله کی راہ میں وہ لوگ لڑیں جو دنیا کی زندگی کو آخرت کے بدلے بیچتے ہیں اور جو کوئی الله کی راہ میں لڑے پھر مارا جائے یا غالب رہے تو اسے ہم بڑا ثواب دیں گے'),
  ('ur.ahmedali', 4, 75, 'اور کیا وجہ ہے کہ تم الله کی راہ میں ان بے بس مردوں اور عورتوں اور بچوں کی خاطر نہ لڑو جو کہتے ہیں اے ہمارے رب ہمیں اس بستی سے نکال جس کے باشندے ظالم ہیں اور ہمارے واسطے اپنے ہاں سے کوئی حمایتی کر دے اور ہمارے واسطےاپنے ہاں سے کوئی مددگار بنا دے'),
  ('ur.ahmedali', 4, 76, 'جو ایمان والے ہیں وہ الله کی راہ میں لڑتے ہیں اور جو کافر ہیں وہ شیطان کی راہ میں لڑتے ہیں سو تم شیطان کے ساتھیوں سے لڑو بے شک شیطان کا فریب کمزور ہے'),
  ('ur.ahmedali', 4, 77, 'کیا تم نے ان لوگوں کو نہیں دیکھا جنہیں کہا گیا تھا کہ اپنے ہاتھ روکے رکھو اور نماز قائم کرو اور زکواة دو پھر جب انہیں لڑنے کا حکم دیا گیا اس وقت ان میں سے ایک جماعت لوگوں سے ایسا ڈرنے لگی جیسا الله کا ڈر ہو یا اس سے بھی زیادہ ڈر اور کہنے لگے اے رب ہمارے تو نے ہم پر لڑنا یوں فرض کیا کیوں نہ ہمیں تھوڑی مدت اور مہلت دی ان سے کہ دو دنیا کا فائدہ تھوڑا ہے اور آخرت پرہیزگاروں کے لیے بہتر ہے اور ایک تاگے کے برابر بھی تم سے بے انصافی نہیں کی جائے گی'),
  ('ur.ahmedali', 4, 78, 'تم جہاں کہیں ہو گے موت تمہیں آ ہی پکڑے گی اگرچہ تم مضبوط قلعوں میں ہی ہو اور اگر انہیں کوئی فائدہ پہنچتا ہے تو لوگ کہتے ہیں کہ یہ الله کی طرف سے ہے اور اگر کوئی نقصان پہنچتا ہے تو کہتے ہیں کہ یہ تیری طرف سے ہے ان لوگوں کو کیا ہو گیا ہے کہ کوئی بات ان کی سمجھ میں نہیں آتی'),
  ('ur.ahmedali', 4, 79, 'تجھے جو بھی بھلائی پہنچے وہ الله کی طرف سے ہے اور جو تجھے برائی پہنچے وہ تیرے نفس کی طرف سے ہے ہم نے تجھے لوگوں کو پیغام پہنچانے واا بنا کر بھیجا ہے اور الله کی گواہی کافی ہے'),
  ('ur.ahmedali', 4, 80, 'جس نے رسول کا حکم مانا اس نے الله کا حکم مانا اور جس نے منہ موڑا تو ہم نے تجھے ان پر نگہبان بنا کر نہیں بھیجا'),
  ('ur.ahmedali', 4, 81, 'اور کہتے ہیں قبول کیا پھر جب تیرے ہاں سے باہر گئے تو ان میں سے ایک گروہ رات کو جمع ہو کر تمہاری باتو ں کے خلاف مشورہ کرتا ہے اور الله لکھتا ہے جو وہ مشورہ کرتے ہیں تو ان کی پرواہ نہ کر اور الله پر بھروسہ کر اور الله کارساز کافی ہے'),
  ('ur.ahmedali', 4, 82, 'کیا یہ لوگ قرآن میں غور نہیں کرتے اور اگر یہ قرآن سوائے الله کے کسی اور کی طرف سے ہوتا تو وہ اس میں بہت اختلاف پاتے'),
  ('ur.ahmedali', 4, 83, 'اور جب ان کے پاس کوئی خبر امن یا ڈر کی پہنچتی ہے تو اسے مشہور کر دیتے ہیں اور اگر اسے رسول او راپنی جماعت کے ذمہ دار اصحاب تک پہنچاتے تو اس کی تحقیق کرتے جو ان میں تحقیق کرنے والے ہیں اوراگر تم پر الله کا فضل اوراس کی مہربانی نہ ہوتی تو البتہ تم شیطان کے پیچھے ہو لیتے سوائے چند لوگوں کے'),
  ('ur.ahmedali', 4, 84, 'سو تو الله کی راہ میں لڑ تو سوائے اپنی جان کے کسی کا ذمہ دار نہیں اور مسلمانوں کو تاکید کر قریب ہے کہ الله کافرو ں کی لڑائی بند کر دے اور الله لڑائی میں بہت ہی سخت ہےاور سزا دینے میں بھی بہت سخت ہے'),
  ('ur.ahmedali', 4, 85, 'جو کوئی اچھی بات میں سفارش کرے اسے بھی اس میں سے ایک حصہ ملے گا اور جو کوئی بری بات میں سفارش کرے اس میں سے ایک بوجھ اس پر بھی ہے اور الله ہر چیز پر قدرت رکھنے والا ہے'),
  ('ur.ahmedali', 4, 86, 'اور جب تمہیں کوئی دعا دے تو تم اس سے بہتر دعا دو یا الٹ کر ویسی ہی کہو بے شک الله ہر چیز کا حساب لینے والا ہے'),
  ('ur.ahmedali', 4, 87, 'الله وہ ہے جس کے سوا کوئی بندگی نہیں بے شک قیامت کے دن تم سب کو جمع کرے گا اس میں کوئی شک نہیں اور الله سے بڑھ کر کس کی بات سچی ہو سکتی ہے'),
  ('ur.ahmedali', 4, 88, 'پھر تمہیں کیا ہو گیا ہے کہ منافقوں کے معاملہ میں دو گروہ ہو رہے ہیں اور الله نے ان کے اعمال کے سبب سےانہیں الٹ دیا ہے کیا تم چاہتے ہو جسے الله نے گمراہ کیا ہو اسے راہ پر لاؤ اور جسے الله گمراہ کرے تو اس کے لیے ہرگز کوئی راہ نہیں پائے گا'),
  ('ur.ahmedali', 4, 89, 'وہ تو چاہتے ہیں کہ جیسے وہ کافر ہوئے ہیں تم بھی کافر ہو جاؤ پھر تم سب برابر ہو جاؤ لہذا ان میں سے کسی کو اپنا دوست نہ بناؤ جب تک وہ الله کی راہ میں ہجرت کر کے نہ آ جائیں پھر اگر وہ اس بات کو قبول نہ کریں تو جہاں پاؤ انہیں پکڑو اور قتل کرو اور ان میں سے کسی کو اپنے دوست اور مددگار نہ بناؤ'),
  ('ur.ahmedali', 4, 90, 'البتہ وہ منافق اس حکم سے مستثنیٰ ہیں جو کسی ایسی قوم سے جا ملیں جس کے ساتھ تمہارا معاہدہ ہو یا وہ جو تمہارے پاس آتے ہیں اور لڑائی سے دل برداشتہ ہیں نہ تم سے لڑتے ہیں اور نہ اپنی قوم سے اور اگر الله چاہتا تو انہیں تم پر مسلط کر دیتا ہے پھر وہ تم سے لڑتے ہیں سو اگر وہ تم سے یک سو رہیں اور تم سے نہ لڑیں او رتمہاری طرف صلح کا ہاتھ بڑھائیں تو الله نے تمہیں ان پر کوئی راہ نہیں دی'),
  ('ur.ahmedali', 4, 91, 'ایک اور قسم کے تم منافق دیکھو گے جو چاہتے ہیں تم سے بھی امن میں رہیں اور اپنی قوم سے بھی جب کبھی وہ فساد کی طرف لوٹائے جاتے ہیں تو اس میں کود پڑتے ہیں پھر اگر وہ تم سے یک سو نہ رہیں اور تہارے آگے صلح پیش نہ کریں اور اپنے ہاتھ نہ روکیں تو انہیں جہاں پا پکڑو او رمار ڈالو اور ان پر ہاتھ اٹھانے کے لیے ہم نے تمہیں کھلی حجت دے دی ہے'),
  ('ur.ahmedali', 4, 92, 'اور مسلمانوں کا یہ کام نہیں کہ کسی مسلمان کو قتل کرے مگر غلطی سے اور جو مسلمان کو غلطی سے قتل کرے تو ایک مسلمان کی گردن آزاد کرے اور مقتول کے وارثوں کو خون بہا دے مگر یہ کہ وہ خون بہا معاف کر دیں پھر اگر وہ مسلمان مقتول کسی ایسی قوم میں تھا جس سے تمہاری دشمنی ہے تو ایک مومن غلام آزاد کرنا ہے اور اگر وہ مقتول مسلمان کسی ایسی قوم میں سے تھا جس سے تمہارا معاہدہ ہے تو اس کے وارثوں کو خون بہا دیا جائے گا اور ایک مومن غلام کو آزاد کرنا ہوگا پھر جو غلام نہ پائے وہ پے درپے دو مہینے کے روزے رکھے الله سےگناہ بخشوانے کے لیے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 4, 93, 'اور جو کوئی کسی مسلمان کو جان کر قتل کرے اس کی سزا دوزخ ہے جس میں وہ ہمیشہ رہے گا اس پر الله کا غضب اور اس کی لعنت ہے اور الله نے اس کےلیے بڑا عذاب تیا رکیا ہے'),
  ('ur.ahmedali', 4, 94, 'اے ایمان والو! جب الله کی راہ میں سفر کرو تو تحقیق کر لیا کرو او جو تم پر سلام کہے اس کو مت کہو کہ مسلمان نہیں ہے تم دنیا کی زندگی کا سامان چاہتے ہو سو الله کے ہاں بہت غنیمتیں ہیں تم بھی تو اس سے پہلے ایسے ہی تھے پھر الله نے تم پر احسان کیا لہذا تحقیق سے کام لیا کرو بے شک الله تمہارے کاموں سے باخبر ہے'),
  ('ur.ahmedali', 4, 95, 'مسلمانوں میں سے جو لوگ کسی عذر کے بغیر گھر بیٹھے رہتے ہیں اور وہ جو الله کی راہ میں جان و مال سے جہاد کرتے ہیں دونوں برابر نہیں ہیں الله نے بیٹھنے والوں پر جان و مال سے جہاد کرنے والوں کا درجہ بڑھایا دیا ہے اگرچہ ہر ایک سے الله نے بھلائي کا وعدہ کیا ہے اور الله نے لڑنے والوں کو بیٹھنے والوں سے اجر عظیم میں زیادہ کیا ہے'),
  ('ur.ahmedali', 4, 96, 'ان کے لیے الله کی طرف سے بڑے درجے اور مغفرت اور رحمت ہے اور الله معاف کرنے والا رحم کرنے والا ہے'),
  ('ur.ahmedali', 4, 97, 'بے شک جو لوگ اپنے نفسوں پر ظلم کر رہے تھے ان کی روحیں جب فرشتوں نے قبض کیں توان سے پوچھا کہ تم کس حال میں تھے انہوں نے جواب دیا ہم اس ملک میں بے بس تھے فرتشوں نے کہا کیا الله کی زمین وسیع نہ تھی کہ تم اس میں ہجرت کر جاتےسو ایسوں کا ٹھکانہ دوزخ ہے اور بہت ہی برا ٹھکانہ ہے'),
  ('ur.ahmedali', 4, 98, 'ہاں جو مرد اور عورتیں اور بچے کافی کمزور ہیں جو نکلنے کا کوئی ذریعہ اور راستہ نہیں پاتے'),
  ('ur.ahmedali', 4, 99, 'پس امید ہے کہ ایسوں کو الله معاف کر دے اور الله معاف کرنے والا بخشنے والا ہے'),
  ('ur.ahmedali', 4, 100, 'اور جو کوئی الله کی راہ میں وطن چھوڑے اس کے عوض جگہ بہت اور کشائش پائے گا اور جو کوئی اپنے گھر سے الله اور رسول کی طرف ہجرت کر کے نکلے پھر اس کو موت پالے تو الله کے ہاں اس کا ثواب ہو چکا اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 4, 101, 'اور جب تم سفر کے لیے نکلو تو تم پر کوئی گناہ نہیں نماز میں سے کچھ کم کر دو اگر تمہیں یہ ڈر ہو کہ کافر تمہیں ستائیں گے بےشک کافر تمہارے صریح دشمن ہیں'),
  ('ur.ahmedali', 4, 102, 'اے نبی جب تم مسلمانو ں میں موجود ہو اور انہیں نماز پڑھانے کے لیے کھڑا ہو تو چاہیئے ان میں سے ایک جماعت تیرے ساتھ کھڑی ہو اور اپنے ہتھیار ساتھ لے لیں پھر جب یہ سجدہ کریں تو تیرے پیچھے سے ہٹ جائیں اور دوسری جماعت آئے جس نے نماز نہیں پڑھی وہ تیرے ساتھ نماز پڑھتے اور وہ بھی اپنے بچاؤ اور اپنے ہتھیار ساتھ رکھیں کافر چاہتے ہیں کہ کسی طرح تم اپنے ہتھیاروں اور اسباب سے بے خبر ہو جاؤ تاکہ تم پر یک بارگی ٹوٹ پڑیں اور اگر تم بارش کی وجہ سے تکلیف محسوس کرو یا بیمار ہو تو ہتھیار رکھ دینے میں کوئي مضائقہ نہیں اور (تب بھی) اپنا بچاؤ ساتھ رکھو بے شک الله نے کافروں کے لیے ذلت کا عذاب تیار کر رکھا ہے'),
  ('ur.ahmedali', 4, 103, 'پھر جب نماز سے فارغ ہو جاؤ تو الله کو کھڑے او ربیٹھے اور لیٹے ہونے کی حالت میں یاد کرو پھر جب تمہیں اطمینان ہو جائے تو پوری نماز پڑھو بے شک نماز اپنے مقرر وقتوں میں مسلمانوں پر فرض ہے'),
  ('ur.ahmedali', 4, 104, 'اور ان لوگوں کا پیچھا کرنے سے ہمت نہ ہارو اگر تم تکلیف اٹھاتے ہو تو وہ بھی تمہاری طرح تکلیف اٹھاتے ہیں حالانکہ تم الله سے جس چیز کے امیدوار ہو وہ نہیں ہیں اور الله سب کچھ جاننے والا حکمت ولا ہے'),
  ('ur.ahmedali', 4, 105, 'بے شک ہم نے تیری طرف سچی کتاب اتاری ہے تاکہ تو لوگوں میں انصاف کرے جو کچھ تمہیں الله سجھا دے اور تو بد دیانت لوگوں کی طرف سے جھگڑنے والا نہ ہو'),
  ('ur.ahmedali', 4, 106, 'اور الله سے بخشش مانگ بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 4, 107, 'اور ان لوگوں کی طرف سے مت جھگڑو جو اپنے دل میں دغا رکھتے ہیں جو شخص دغا باز گناہگار ہو بے شک الله اسے پسند نہیں کرتا'),
  ('ur.ahmedali', 4, 108, 'یہ لوگوں سے تو چھپتے ہیں اور خدا سے نہیں چھپتے حالانکہ جب وہ راتوں کو ایسی باتوں کے مشورے کیا کرتے ہیں جن کو وہ پسند نہیں کرتا ان کے ساتھ ہوا کرتا ہے اور خدا ان کے (تمام) کاموں پر احاطہ کئے ہوئے ہے'),
  ('ur.ahmedali', 4, 109, 'ہاں تم لوگوں نے ان مجرمو ں کی طرف سے دنیا کی زندگی میں تو جھگڑا کر لیا پھر قیامت کے دن ان کی طرف سے الله سے کون جھگڑے گا یا ان کا وکیل کون ہوگا'),
  ('ur.ahmedali', 4, 110, 'اور جو کوئی برا فعل کرے یا اپنے نفس پر ظلم کرے پھراس کے بعد اللهسےبخشوائے تو الله کو بخشنے والا مہربان پائے'),
  ('ur.ahmedali', 4, 111, 'اور جو کوئی گناہ کرے سو اپنےہی حق میں کرتا ہے اور الله سب باتوں کا جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 4, 112, 'اور جو کوئی خطا یا گناہ کرے پھر کسی بے گنا پر تہمت لگادے تو اس نے بڑے بہتان اور صریح گناہ کا بار سمیٹ لیا'),
  ('ur.ahmedali', 4, 113, 'اور اگر تجھ پر الله کا فضل اور اس کی رحمت نہ ہوتی تو ان میں سے ایک گروہ نے تمہیں غلط فہمی میں مبتلا کرنے کا فیصلہ کرہی لیا تھا حالا نکہ وہ اپنے سوا کسی کو غلط فہمی میں مبتلانہیں کر سکتے تھے اور وہ تمہارا کچھ نہیں بگاڑ سکتے تھے اور الله نے تجھ پر کتاب اور حکمت نازل کی ہے اور تجھے وہ باتیں سکھائی ہیں جو تو نہ جانتا تھا اور الله کا تجھ پر بہت بڑا فضل ہے'),
  ('ur.ahmedali', 4, 114, 'ان لوگو ں کی خفیہ سرگوشیوں میں اکثر کوئی بھلائی نہیں ہوتی ہاں مگر کوئی پوشیدہ طور پر صدقہ کرنے یا کسی نیک کام کرنے یا لوگو ں میں صلح کرانے میں کی جائے تو یہ بھلی بات ہے اور جو شخص یہ کام الله کی رضا جوئی کے لیے کرے تو ہم اسے بڑا ثواب دیں گے'),
  ('ur.ahmedali', 4, 115, 'اور جو کوئی رسول کی مخالفت کرے بعد اس کے کہ اس پر سیدھی راہ کھل چکی ہو اور سب مسلمانوں کے راستہ کے خلاف چلے تو ہم اسے اسی طرف چلائیں گے جدھر وہ خود پھر گیا ہے اور اسے دوزح میں ڈال دینگے اور وہ بہت برا ٹھکانا ہے'),
  ('ur.ahmedali', 4, 116, 'بے شک الله اس کو نہیں بخشتا جو کسی کو اس کا شریک بنائے اس کے سوا جسے چاہے بخش دے اور جس نے الله کا شریک ٹھیرایا وہ بڑی دور کی گمراہی میں جا پڑا'),
  ('ur.ahmedali', 4, 117, 'یہ لوگ الله کے سوا عورتو ں کی عبادت کرتے ہیں اور صرف شیطان سرکش کی عبادت کرتے ہیں'),
  ('ur.ahmedali', 4, 118, 'جس پر الله کی لعنت ہے اور شیطان نے کہا کہ اے الله میں تیرے بندوں میں سے حصہ مقرر لوں گا'),
  ('ur.ahmedali', 4, 119, 'اور البتہ انہیں ضرور گمراہ کروں گا اور البتہ ضرور انہیں امیدیں دلاؤں گا اور البتہ ضرور انہیں حکم کروں گا کہ جانوروں کے کان چریں اور البتہ ضرور انہیں حکم دوں گا کہ جانورں کے کان چیریں اور البتہ ضرور انہیں حکم دوں گاکہ الله کی بنائی ہوئی صورتیں بدلیں اور جو شخص الله کو چھوڑ کر شیطان کو دوست بنائے گا وہ صریح نقصان میں جا پڑا'),
  ('ur.ahmedali', 4, 120, 'شیطان ان سے وعدے کرتا ہےاور انہیں امیدیں دلاتا ہے اور شیطان ان سے صرف جھوٹے وعدے کرتا ہے'),
  ('ur.ahmedali', 4, 121, 'ایسے لوگو ں کا ٹھکانہ دورخ ہے ااور اس ے کہیں بچنے کے لیے جگہ نہ پائیں گے'),
  ('ur.ahmedali', 4, 122, 'اور جو لوگ ایمان لائے اور اچھے کام کیے انہیں ہم باغوں میں داخل کر ینگے جن کے نیچے نہریں بہتی ہیں ان میں ہمیشہ رہیں گے الله کا وعدہ سچا ہے اور الله سے زیادہ سچا کون ہے'),
  ('ur.ahmedali', 4, 123, 'نہ تمہاری امیدوں پر مدار ہے اور نہ اہل کتاب کی امیدوں پر جو کوئی برائی کا کام کرے گا اس کی سزا دیا جائے گا اور الله کے سوا اپنا کوئی حمایتی اور مددگار نہیں پائے گا'),
  ('ur.ahmedali', 4, 124, 'اور جو کوئی اچھے کام کرے گا مرد ہے یا عورت درآنحالینکہ وہ ایما ندار ہو تو وہ لوگ جنت میں داخل ہوں گے اور کھجور کے شگاف برابر بھی ظلم نہیں کیے جائیں گے'),
  ('ur.ahmedali', 4, 125, 'اس شخص سے بہتر دین میں کون ہے جس نے الله کے حکم پر پیشانی رکھی اور وہ نیکی کرنے والا ہو اور ابراھیم حنیف کے دین کی پیروی کرے اور الله نے ابراھیم کوخاص دوست بنا لیا ہے'),
  ('ur.ahmedali', 4, 126, 'اور الله ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے اور الله سب چیزو ں کا احاطہ کیے ہوئے ہے'),
  ('ur.ahmedali', 4, 127, 'اور تجھ سے عورتو ں کے نکاح کی رخصت مانگتے ہیں کہہ دے الله تمہیں ان کی اجازت دیتا ہے اور وہ جو تمہیں قرآن سنایا جاتا ہے سو ان یتیم عورتوں کا حکم ہے جنہیں تم نہیں دیتے جو ان کے لیے مقرر کیا گیا ہے او رچاہتے ہو کہ ان سے نکاح کرو اور کمزور لڑکوں کے بارے میں ہے اور یہ کہ یتیموں کے حق میں انصاف پر قائم رہو اور جو تم نیکی کرو گے پس تحقیق الله اسے جاننے والا ہے'),
  ('ur.ahmedali', 4, 128, 'اور اگر کوئی عورت اپنے خاوند کے لڑنے یا منہ پھیرنے سے ڈرے تو دونوں پر کوئی گناہ نہیں کہ آپس میں کسی طرح صلح کر لیں اور یہ صلح بہتر ہے اور دلوں میں حرص موجود ہے اور اگر تم نیکی کرو او رپرہیزگاری کرو تو الله کو تمہارے اعمال کی پوری خبر ہے'),
  ('ur.ahmedali', 4, 129, 'اور تم عورتوں کو ہرگز برابر نہیں رکھ سکو گے اگرچہ اس کی حرص کرو سوتم بالکل ہی ایک طرف نہ جھک جاؤ کہ دوسری عورت کو لٹکی ہوئی چھوڑ دو اور اگر اصلاح کرتے رہو اور پرہیزگاری کرتے رہو تو الله بحشنے والا مہربان ہے'),
  ('ur.ahmedali', 4, 130, 'اور اگر دونوں میاں بیوی جدا ہو جائیں تو الله اپنی و سعت سے ہر ایک کو بے پروا کردے گا اور الله وسعت کرنے والا حکمت والا ہے'),
  ('ur.ahmedali', 4, 131, 'اور جو کچھ اسمانوں اور جو کچھ زمین میں ہے وہ الله ہی کا ہے اور ہم نے پہلی کتاب والوں کو اور تمہیں حکم دیا ہے کہ الله سے ڈرو اور اگر ناشکری کرو گے تو جو کچھ آسمانو ں میں ہے اور جو کچھ زمین میں ہے سب الله ہی کا ہے اور الله بے پرواہ تعریف کیا ہواہے'),
  ('ur.ahmedali', 4, 132, 'اور جو کچھ آسمانو ں اور زمین میں سب الله ہی کا ہے اور الله کارسازکافی ہے'),
  ('ur.ahmedali', 4, 133, 'اگر چاہے تو اے لوگو تمہیں لے جائے اوراوروں کو لے آئے اور الله اس پر قادر ہے'),
  ('ur.ahmedali', 4, 134, 'جو شخص دنیا کا ثواب چاہتا ہے تو الله کے ہاں دنیا اور آخرت کا ثواب ہے اور الله سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 4, 135, 'اے ایمان والو! انصاف پر قائم رہو الله کی طرف گواہی دو اگرچہ اپنی جانوں پر ہو یا اپنے ماں باپ اور رشہ داروں پر اگر کوئی مالدار ہے یا فقیر ہے تو الله ان کا تم سے زیادہ خیر خوا ہ ہے سو تم انصاف کرنے میں دل کی خواہش کی پیروی نہ کرو اور اگر تم کج بیانی کرو گے یا پہلو تہی کرو گے تو بلاشبہ الله تمہارے سب اعمال سے با خبر ہے'),
  ('ur.ahmedali', 4, 136, 'اے ایمان والو! الله اور اس کے رسول پر یقین لاؤ اور اس کتاب پر جو اس نے اپنے رسول پر نازل کی ہےاور اس کتاب پر جو پہلے نازل کی تھی اور جو کوئی الله کا انکار کرے اور اس کے فرشتوں کا اور اس کے رسولوں کا اور قیامت کے دن کا تو وہ شخص بڑی دور کی گمراہی میں جا پڑا'),
  ('ur.ahmedali', 4, 137, 'بے شک وہ لوگ جو ایمان لائے پھر کفر کیا پھر ایمان لائے پھر کفر کیا پھر کفر میں بڑھتے رہے تو الله ان کو ہرگز نہیں بخشے گا اور نہ انہیں راہ دکھائے گا'),
  ('ur.ahmedali', 4, 138, 'منافقوں کو خوشخبری سنا دے کہ ان کے واسطے دردناک عذاب ہے'),
  ('ur.ahmedali', 4, 139, 'وہ جو مسلمانوں کو چھوڑ کر کافروں کو اپنا دوست بناتے ہیں کیا ان کے ہاں سے عزت چاہتے ہیں سو ساری عزت الله ہی کے قبضہ میں ہے'),
  ('ur.ahmedali', 4, 140, 'اور الله نے تم پر قرآن میں حکم اتارا ہے کہ جب تم الله کی آیتوں پر انکار اور مذاق ہوتا سنو تو ان کے ساتھ نہ بیٹھو یہاں تک کہ کسی بات میں مشغول ہوں ورنہ تم بھی ان جیسے ہو جاؤ گے اور الله منافقوں اور کافروں کو دوزخ میں ایک ہی جگہ اکھٹا کرنے والا ہے'),
  ('ur.ahmedali', 4, 141, 'وہ منافق جو تمہارے متعلق انتظار کرتے ہیں پھر اگر تمہیں الله کی طرف سے فتح ہو تو کہتے ہیں کیا ہم تمہارے ساتھ نہ تھےاور اگر کافرو ں کو کچھ حصہ مل جائے تو کہتے ہیں کیا ہم تم پر غالب نہ آنے لگے تھے اور کیا ہم نے تمہیں مسلمانوں سے بچا نہیں لیا سو الله تمہارا اور ان کا قیامت میں فیصلہ کرے گا اور (وہاں) الله کافروں کو مسلمانوں کے مقابلہ میں ہرگز غالب نہیں کرے گا'),
  ('ur.ahmedali', 4, 142, 'منافق الله کو فریب دیتے ہیں اور وہی ان کو فریب دے گا اور جب وہ نماز میں کھڑے ہوتے ہیں تو سست بن کر کھڑے ہوتے ہیں لوگو ں کو دکھا تے ہیں اور الله کو بہت کم یاد کرتے ہیں'),
  ('ur.ahmedali', 4, 143, 'کفر اور ایمان کے درمیان ڈانوں ڈول ہیں نہ پورے اس طرف ہیں اور نہ پورے اس طرف اور جسے الله گمراہ کر دے تو اس کے واسطے ہرگزکہیں راہ نہ پائے گا'),
  ('ur.ahmedali', 4, 144, 'اے ایمان والو مسلمانوں کو چھوڑ کر کافروں کو اپنا دوست نہ بناؤ کیا تم اپنے اوپر الله کا صریح الزام لینا چاہتے ہو'),
  ('ur.ahmedali', 4, 145, 'بے شک منافق دوزخ کے سب سےنیچے درجہ میں ہوں گے تو ان کے واسطے کوئی مددگار ہرگز نہ پائے گا'),
  ('ur.ahmedali', 4, 146, 'مگر جنہوں نے توبہ کی اور اپنی اصلاح کی اور الله کو مضبوط پکڑا اور اپنے دین کو خالص الله ہی کے لیے کیاتو وہ لوگ ایمان والوں کے ساتھ ہیں اور الله جلدی ایمان والوں کو بہت بڑا ثواب دے گا'),
  ('ur.ahmedali', 4, 147, ') اے منافقو) الله تمہیں سزادے کر کیا کرے گا اگر تم شکر گزار بنو اور ایمان لے آؤ اور الله قدردان جاننے والا ہے'),
  ('ur.ahmedali', 4, 148, 'الله کو کسی کی بڑی بات کا ظاہر کرنا پسند نہیں مگر جس پر ظلم ہواہو اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 4, 149, 'اور اگرتم نیک کام اعلانیہ کر ویا اسے خفیہ کرو یا کسی برائی کو معاف کردو تو الله بڑا معاف کرنے والا قدرت والا ہے'),
  ('ur.ahmedali', 4, 150, 'بے شک جو لوگ الله اور اس کے رسولوں کے ساتھ کفر کرتے ہیں اور چاہتے ہیں کہ الله اوراس کے رسولوں کے درمیان فرق رکھیں اور کہتے ہیں کہ ہم بعضوں پر ایمان لائے ہیں اور بعضوں کے منکر ہیں اور چاہتے ہیں کہ کفر اور ایمان کے درمیان ایک راہ نکالیں'),
  ('ur.ahmedali', 4, 151, 'ایسے لوگ یقیناً کافر ہیں اور ہم نے کافرو ں کے واسطے ذلت کا عذاب تیار کر رکھا ہے'),
  ('ur.ahmedali', 4, 152, 'اور جو لوگ الله پر ایمان لائے اور رسولوں پر ان میں سے کسی کو جدا نہ کیاان لوگوں کو الله جلدان کے ثواب دے گا اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 4, 153, 'اہلِ کتاب تجھ سےدرخواست کرتے ہیں کہ تو ان پر آسمان سے لکھی ہوئی کتب اتار لائے سو موسیٰ سے اس سے بڑی چیز مانگ چکے ہیں اور کہا ہمیں الله کو بالکل سامنے لا کر دکھا دے ان کے اس ظلم کے باعث ان پر بجلی ٹوٹ پڑی پھر بہت سی نشانیاں پہنچ چکنے کے بعد بچھڑے کو بنا لیا پھر ہم نے وہ بھی معاف کر دیا اور ہم نے موسیٰ کو بڑا رعب دیاتھا'),
  ('ur.ahmedali', 4, 154, 'اور لوگوں پر طور اٹھا کر ان سے عہد لیا اور ہم نے کہا کہ دروازہ میں سجدہ کرتے ہوئےداخل ہو اور ہم نے کہا کہ ہفتے کے بارے میں زیادتی نہ کرو اور ہم نے ان سے پختہ عہد لیا'),
  ('ur.ahmedali', 4, 155, 'پھر ان کی عہد شکنی پر اور الله کی آیتوں سے منکر ہونے پر اور پیغمبروں کا ناحق خون کرنے پر اور اس کہنے پرکہ ہمارے دلوں پرپر دے رہے ہیں انہیں سزا ملی پردے نہیں بلکہ الله نے ان کے دلوں پر کفر کے سبب سے مہر کر دی ہے سو ایمان نہیں لاتے مگر تھوڑے'),
  ('ur.ahmedali', 4, 156, 'اور ان کے کفر او رمریم پر بڑا بہتان باندھنے کے سبب سے'),
  ('ur.ahmedali', 4, 157, 'اور ان کے اس کہنے پر کہ ہم نے مسیح عیسیٰ مریم کے بیٹے کو قتل کیا جو الله کا رسول تھا حالانکہ انہوں نے نہ اسے قتل کیا اور نہ سولی پر چڑھایا لیکن ان کو اشتباہ ہو گیا اورجن لوگوں نے اس کے بارے میں اختلاف کیا ہے وہ بھی دراصل شک میں مبتلا ہیں ان کے پا س بھی اس معاملہ میں کوئی یقین نہیں ہے محض گمان ہی کی پیروی ہے انہوں نے یقیناً مسیح کو قتل نہیں کیا'),
  ('ur.ahmedali', 4, 158, 'بلکہ اسے الله نے اپنی طرف اٹھا لیا اور الله زبردست حکمت والا ہے'),
  ('ur.ahmedali', 4, 159, 'اور اہلِ کتاب میں کوئی ایسانہ ہوگا جواسکی موت سے پہلے اس پر ایمان نہ لائے گا اور قیامت کے دن وہ ان پر گواہ ہو گا'),
  ('ur.ahmedali', 4, 160, 'سویہود کے گناہوں کے سبب سے ہم نے ان پر بہت سی پاک چیزیں حرام کر دیں جو ان پر حلا ل تھیں اور اس سبب سے الله کی راہ سے بہت روکتے تھے'),
  ('ur.ahmedali', 4, 161, 'اور ان کو سود لینے کے سبب سے حالانکہ اس سے منع کیے گئے تھے اور اس سبب سے کہ لوگو ں کا مال ناحق کھاتے تھے اور ان میں سے جو کافر ہیں ہم نے ان کے لیے دردناک عذاب تیار کر رکھا ہے'),
  ('ur.ahmedali', 4, 162, 'لیکن ان میں سے جو علم میں پختہ ہیں اور مسلمان ہیں سومانتے ہیں اس کو جو تجھ پر نازل ہوا اور جو تجھ سے پہلے نازل ہو چکا ہے اور نماز قائم کرنے والے اور زکواة دینے والے اور اللهاور قیامت پر ایمان لانے والے ہیں یہ وہ لوگ ہیں جنہیں ہم بڑا ثواب عطا فرمائیں گے'),
  ('ur.ahmedali', 4, 163, 'ہم نے تیری طرف وحی بھیجی جیسی نوح پر وحی بھیجی اور ان نبیوں پر جو اس کے بعد آئے اور ابراھیمؑ اور اسماعیلؑ اور اسحاقؑ اور یعقوبؑ اور اس کی اولاد اور عیسیٰؑ اور ایوبؑ اوریونسؑ اور ھارونؑ اور سلیمانؑ پر وحی بھیجی اور ہم نے داؤدؑ کو زبور دی'),
  ('ur.ahmedali', 4, 164, 'اور ایسے رسول بھیجے جن کا حال اس سے پہلےہم تمہیں سنا چکیں ہیں اور ایسے رسول جن کا ہم نے تم سے بیان نہیں کیا اور الله نے موسیٰ سے خاص طور پر کلام فرمایا'),
  ('ur.ahmedali', 4, 165, 'ہم نے پیغمبر بھیجے خوشخبری دینے والے اور ڈرانے والے تاکہ ان لوگوں کا الله پر پیغمبرو ں کے بعد الزا م نہ رہے اور الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 4, 166, 'لیکن الله اس پر شاہد ہے جو تم پر نازل کیا کہ اسے اپنے علم سے نازل کیا اور فرشتے بھی گواہ ہیں اورالله گواہی دینے والا کافی ہے'),
  ('ur.ahmedali', 4, 167, 'بے شک جو لوگ کافر ہوئے اور الله کی راہ سے روکا وہ بڑی دور کی گمراہی میں جا پڑے'),
  ('ur.ahmedali', 4, 168, 'بے شک جو لوگ کافر ہوئے اور ظلم کیا الله انہیں کبھی نہیں بخشے گا اور نہ ان کو سیدھی راہ دکھائے گا'),
  ('ur.ahmedali', 4, 169, 'مگر دوزخ کی راہ جس میں وہ ہمیشہ رہیں گے اور الله پر یہ آسان ہے'),
  ('ur.ahmedali', 4, 170, 'اے لوگو! تمہارے پاس تمہارے رب کی طرف سے ٹھیک بات لے کر رسول آ چکا سو مان لو تاکہ تمہارا بھلا ہو اور اگر انکار کرو گے تو الله ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے اور الله سب کچھ جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 4, 171, 'اے اہِل کتاب تم اپنے دین میں حد سے نہ نکلو اور الله کی شان میں سوائے پکی بات کے نہ کہو بے شک مسیح عیسیٰ مریم کا بیٹا الله کا رسول ہے اور الله کا ایک کلمہ ہےجسے الله نے مریم تک پہنچایا اور الله کی طرف سے ایک جان ہے سو الله پر اور اس کے سب رسولوں پر ایمان لاؤ اور نہ کہو کہ خدا تین ہیں اس بات کو چھوڑ دو تمہارے لیے بہتر ہو گا بے شک الله اکیلا معبود ہے وہ اس سے پاک ہے اس کی اولاد ہو اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور الله کارساز کافی ہے'),
  ('ur.ahmedali', 4, 172, 'مسیح خدا کا بندہ بننے سے ہرگز عار نہیں کرے گا اور نہ مقرب فرشتے اور جو کوئی اس کی بندگی سے انکار کرے گا اور تکبر کرے گا پھران سب کو اپنی طرف اکھٹاکرے گا'),
  ('ur.ahmedali', 4, 173, 'پھر جو لوگ ایمان لائے ہوں گے اور اچھے کام کیے ہوں گے انہیں تو ان کا پورا ثواب دے گا اور انہیں اپنے فضل سے زیادہ دے گا اور جن لوگوں نے انکار کیا اورتکبر کیا انہیں درد دینے والا عذاب دے گا اور وہ الله کے سوا اپنے واسطے کوئی دوست اور مددگار نہیں پائیں گے'),
  ('ur.ahmedali', 4, 174, 'اے لوگو! تمہارے پاس تمہارے پروردگار کی طرف سے ایک دلیل آ چکی ہے اور ہم نےتمہاری طرف ایک ظاہر روشنی اتاری ہے'),
  ('ur.ahmedali', 4, 175, 'سو جو لوگ الله پر ایمان لائے اور انھوں نے الله کومظبوط پکڑا انہیں الله اپنی رحمت اور اپنے فضل میں داخل کرے گا اور اپنے تک ان کو سیدھا راستہ دکھائے گا'),
  ('ur.ahmedali', 4, 176, 'تجھ سے حکم دریافت کرتے ہیں کہہ دو الله تمہیں کلالہ کے بارے میں حکم دیتا ہے اگر کوئی شخص مر جائے جس کی اولاد نہ ہو اور اس کی ایک بہن ہو تو اسے اس کے تمام ترکہ کانصف ملے گا اور وہ شخص اس بہن کا وارث ہو گا اگر اس کی کوئی اولاد نہ ہو اور اگر دو بہنیں ہوں تو انہیں کل ترکہ میں سے دو تہائی ملے گا اور اگر چند وارث بھائی بہن ہوں مرد اور عورت تو ایک مرد کو دو عورتوں کے حصہ کے برابر ملے گا الله تم سے اس لیے بیان کرتا ہے کہ تم گمراہ نہ ہو جاؤ اور الله ہر چیز کو جاننے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 4, 1, 'Ey İnsanlar! Sizi bir tek nefisten yaratan, ondan eşini var eden ve ikisinden pek çok erkek ve kadın meydana getiren Rabb\'inize hürmetsizlikten sakının. Kendisi adına birbirinizden dilekte bulunduğunuz Allah\'ın ve akrabanın haklarına riayetsizliktende sakının. Allah şüphesiz hepinizi görüp gözetmektedir.'),
  ('tr.diyanet', 4, 2, 'Yetimlere mallarını verin. Temizi murdara değişmeyin, onların mallariyle kendi mallarınızı karıştırarak yemeyin, çünkü bu büyük bir suçtur.'),
  ('tr.diyanet', 4, 3, 'Eğer, velisi olduğunuz mal sahibi yetim kızlarla evlenmekle onlara haksızlık yapmaktan korkarsanız onlarla değil, hoşunuza giden başka kadınlarla iki, üç ve dörde kadar evlenebilirsiniz; şayet, aralarında adaletsizlik yapmaktan korkarsanız bir tane almalısınız veya sahip olduğunuz ile yetinmelisiniz. Doğru yoldan sapmamanız için en uygunu budur.'),
  ('tr.diyanet', 4, 4, 'Kadınlara mehirlerini cömertçe verin, eğer ondan gönül hoşluğu ile size bir şey bağışlarlarsa onu afiyetle yiyin.'),
  ('tr.diyanet', 4, 5, 'Allah\'ın sizi koruyucu kılmış olduğu mallarınızı, beyinsizlere vermeyin, kendilerini bunların geliriyle rızıklandırıp giydirin ve onlara güzel söz söyleyin.'),
  ('tr.diyanet', 4, 6, 'Yetimleri, evlenme çağına gelene kadar deneyin; onlarda olgunlaşma görürseniz mallarını kendilerine verin; büyüyecekler de geri alacaklar diye onları israf ederek ve tez elden yemeyin. Zengin olan, iffetli olmağa çalışsın, yoksul olan uygun bir şekilde yesin. Mallarını kendilerine verdiğiniz zaman, yanlarında şahid bulundurun. Hesap sormak için Allah yeter.'),
  ('tr.diyanet', 4, 7, 'Ana babanın ve yakınların bıraktıklarından, erkeklere hisse vardır. Ana babanın ve yakınların bıraktıklarından kadınlara da hisse vardır. Bunlar, az veya çok, belirli bir hissedir.'),
  ('tr.diyanet', 4, 8, 'Taksimde, yakınlar, yetimler ve düşkünler bulunursa, ondan onlara da verin, güzel sözler söyleyin.'),
  ('tr.diyanet', 4, 9, 'Arkalarında cılız çocuklar bıraktıkları takdirde, bundan endişe edecek olanlar, haksızlık yapmaktan korksunlar; dürüst söz söylesinler.'),
  ('tr.diyanet', 4, 10, 'Yetimlerin mallarını haksız yere yiyenler, karınlarına ancak ateş tıkınmış olurlar, zaten onlar çılgın aleve atılacaklardır.'),
  ('tr.diyanet', 4, 11, 'Allah çocuklarınız hakkında, erkeğe iki dişinin hissesi kadar tavsiye eder. Eğer kadınlar ikinin üstünde ise, bırakılanın üçte ikisi onlarındır; şayet bir ise yarısı onundur. Ana babadan her birine, ölenin çocuğu varsa yaptığı vasiyetten veya borcundan arta kalanın altıda biri, çocuğu yoksa, anası babası ona varis olur, anasına üçte bir düşer. Kardeşleri varsa, altıda biri annesinindir; babalarınız ve oğullarınızdan menfaatçe hangisinin size daha yakın olduğunu siz bilmezsiniz. Bunlar Allah tarafından tesbit edilmiştir. Doğrusu Allah bilendir, Hakim olandır.'),
  ('tr.diyanet', 4, 12, 'Kadınlarınızın çocukları yoksa bıraktıklarının yarısı sizindir, çocukları varsa, bıraktıklarının ettikleri vasiyetten veya borçtan arta kalanın dörtte biri sizindir. Sizin çocuğunuz yoksa ettiğiniz vasiyet veya borç çıktıktan sonra bıraktıklarınızın dörtte biri karılarınızındır; çocuğunuz varsa, bıraktıklarınızın sekizde biri onlarındır. Eğer bir erkek veya kadına kelale yollu (çocuğu ve babası olmadığı halde) varis olunuyor ve bunların ana-bir erkek veya bir kız kardeşi bulunuyorsa, her birine edilen vasiyetten veya borçtan arta kalanın altıda biri düşer; ikiden çoksalar, üçte birine, zarara uğratılmaksızın ortak olurlar. Bunlar Allah tarafından tavsiye edilmiştir. Allah bilendir. Halim\'dir.'),
  ('tr.diyanet', 4, 13, 'Bunlar Allah\'ın yasalarıdır. Allah\'a ve Peygamberine kim itaat ederse onu içlerinden ırmaklar akan cennetlere koyacaktır, orada temellidirler, büyük kurtuluş budur.'),
  ('tr.diyanet', 4, 14, 'Kim Allah\'a ve Peygamberine baş kaldırır ve yasalarını aşarsa, onu, temelli kalacağı cehenneme sokar. Alçaltıcı azab onadır.'),
  ('tr.diyanet', 4, 15, 'Kadınlarınızdan zina edenlere, bunu isbat edecek aranızdan dört şahid getirin, şehadet ederlerse, ölünceye veya Allah onlara bir yol açana kadar evlerde tutun.'),
  ('tr.diyanet', 4, 16, 'İçinizden zina eden iki kimseye eziyet edin, tevbe edip düzeltirlerse onları bırakın. Doğrusu Allah tevbeleri daima kabul ve merhamet eder.'),
  ('tr.diyanet', 4, 17, 'Allah kötülüğü bilmeyerek yapıp da, hemen tevbe edenlerin tevbesini kabul etmeyi üzerine almıştır. Allah işte onların tevbesini kabul eder. Allah Bilen\'dir, Hakim olandır.'),
  ('tr.diyanet', 4, 18, 'Kötülükleri işleyip dururken, ölüm kendisine geldiği zaman; "şimdi tevbe ettim" diyenler ile kafir olarak ölenlerin tevbesi makbul değildir. İşte onlara elem verici azab hazırlamışızdır.'),
  ('tr.diyanet', 4, 19, 'Ey İnananlar! Kadınlara zorla mirasçı olmaya kalkmanız size helal değildir. Apaçık hayasızlık etmedikçe onlara verdiğinizin bir kısmını alıp götürmeniz için onları sıkıştırmayın. Onlarla güzellikle geçinin. Eğer onlardan hoşlanmıyorsanız, sabredin, hoşlanmadığınız bir şeyi Allah çok hayırlı kılmış olabilir.'),
  ('tr.diyanet', 4, 20, 'Bir eşin yerine başka bir eşi almak isterseniz, birincisine bir yük altın vermiş olsanız bile ondan bir şey almayın. İftira ederek ve apaçık günaha girerek ona verdiğinizi geri alır mısınız?'),
  ('tr.diyanet', 4, 21, 'Nasıl alırsınız ki siz birbirinize katılmıştınız ve onlar sizden sağlam teminat almışlardı.'),
  ('tr.diyanet', 4, 22, 'Babalarınızın evlendikleri kadınlarla evlenmeyin, geçmişte olanlar artık geçmiştir çünkü bu bir fuhuş ve igrenç bir şeydi, ne kötü yoldu!'),
  ('tr.diyanet', 4, 23, 'Sizlere, analarınız, kızlarınız, kızkardeşleriniz, halalarınız, teyzeleriniz, kardeşlerinizin kızları, kızkardeşlerinizin kızları, sizi emziren süt anneleriniz, süt kardeşleriniz, karılarınızın anneleri, kendileriyle gerdeğe girdiğiniz kadınlarınızin yanınızda kalan üvey kızlarınız ki onlarla gerdeğe girmemişseniz size bir engel yoktur, öz oğullarınızın eşleri ve iki kız kardeşi bir arada almak suretiyle evlenmek, -geçmişte olanlar artık geçmiştir- size haram kılındı. Doğrusu Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 24, 'Evli kadınlarla evlenmeniz de haram kılındı. Maliki bulunduğunuz cariyeler müstesna, bunlar, Allah\'ın üzerinize farz kıldığı hükümlerdir. Bunlardan başkasını, zinadan kaçınıp, iffetli olarak, mallarınızla istemeniz size helal kılındı. Onlardan faydalandığınıza mukabil, kararlaştırılmış olan mehirlerini verin; kararlaştırılandan başka, karşılıklı hoşnud olduğunuz hususda size bir sorumluluk yoktur. Allah Bilen\'dir, Hakim\'dir.'),
  ('tr.diyanet', 4, 25, 'Sizden, hür mümin kadınlarla evlenmeye güç yetiremiyen kimse, ellerinizdeki mümin cariyelerinizden alsın. Allah sizin imanınızı çok iyi bilir. Birbirinizdensiniz, aynı soydansınız. Onlarla, zinadan kaçınmaları, iffetli olmaları ve gizli dost tutmamış olmaları halinde, velilerinin izniyle evlenin ve örfe uygun bir şekilde mehirlerini verin. Evlendiklerinde zina edecek olurlarsa, onlara, hür kadınlara edilen azabın yarısı edilir. Cariye ile evlenmedeki bu izin içinizden, günaha girme korkusu olanlaradır. Sabretmeniz sizin için daha hayırlıdır. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 26, 'Allah size açıklamak ve sizden öncekilerin yollarını göstermek ve tevbenizi kabul etmek ister. Allah Bilen\'dir, Hakim\'dir.'),
  ('tr.diyanet', 4, 27, 'Allah sizin tevbenizi kabul etmek ister, şehvetlerine uyanlar ise sizin büyük bir sapıklığa girmenizi isterler.'),
  ('tr.diyanet', 4, 28, 'İnsan zayıf yaratılmış olduğundan Allah sizden yükü hafifletmek ister.'),
  ('tr.diyanet', 4, 29, 'Ey İnananlar! Mallarınızı aranızda haksızlıkla değil, karşılıklı rıza ile yapılan ticaretle yeyin, haram ile nefsinizi mahvetmeyin. Allah şüphesiz ki size merhamet eder.'),
  ('tr.diyanet', 4, 30, 'Bunu kim aşırı giderek haksızlıkla yaparsa, onu ateşe sokacağız. Bu, Allah\'a kolaydır.'),
  ('tr.diyanet', 4, 31, 'Size yasak edilen büyük günahlardan kaçınırsanız, kusurlarınızı örter ve sizi şerefli bir yere yerleştiririz.'),
  ('tr.diyanet', 4, 32, 'Allah\'ın sizi birbirinizden üstün kıldığı şeyleri özlemeyin. Erkeklere, kazandıklarından bir pay, kadınlara da kazandıklarından bir pay vardır. Allah\'tan bol nimet isteyin. Doğrusu Allah her şeyi bilir.'),
  ('tr.diyanet', 4, 33, 'Ana babanın ve yakınların bıraktıklarından her birine varisler kıldık. Kendileriyle yeminleştiğiniz kimselere hisselerini veriniz. Doğrusu Allah her şeye şahiddir.'),
  ('tr.diyanet', 4, 34, 'Allah\'ın kimini kimine üstün kılmasından ötürü ve erkeklerin, mallarından sarfetmelerinden dolayı erkekler kadınlar üzerine hakimdirler. İyi kadınlar, gönülden boyun eğenler ve Allah\'ın korunmasını emrettiğini, kocasının bulunmadığı zaman da koruyanlardır. Serkeşlik etmelerinden endişelendiğiniz kadınlara öğüt verin, yataklarında onları yalnız bırakın, nihayet dövün. Size itaat ediyorlarsa aleyhlerine yol aramayın. Doğrusu Allah Yüce\'dir, Büyük\'tür.'),
  ('tr.diyanet', 4, 35, 'Karı kocanın arasının açılmasından endişelenirseniz, erkeğin ailesinden bir hakem ve kadının ailesinden bir hakem gönderin; bunlar düzeltmek isterlerse, Allah onların aralarını buldurur. Doğrusu Allah her şeyi Bilen ve haberdar olandır.'),
  ('tr.diyanet', 4, 36, 'Allah\'a kulluk edin, O\'na bir şeyi ortak koşmayın. Ana babaya, yakınlara, yetimlere, düşkünlere, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolcuya ve elinizin altında bulunan kimselere iyilik edin. Allah, kendini beğenip öğünenleri elbette sevmez.'),
  ('tr.diyanet', 4, 37, 'Onlar cimrilik ederler, insanlara cimrilik tavsiyesinde bulunurlar, Allah\'ın bol nimetinden kendilerine verdiğini gizlerler. Kafirlere aşağılık bir azab hazırlamışızdır.'),
  ('tr.diyanet', 4, 38, 'Mallarını insanlara gösteriş için sarfedip, Allah\'a ve ahiret gününe inanmayanları da Allah sevmez. Şeytanın arkadaş olduğu kimsenin ne fena arkadaşı vardır!'),
  ('tr.diyanet', 4, 39, 'Bunlar Allah\'a, ahiret gününe inanmış, Allah\'ın verdiği rızıklardan sarfetmiş olsalardı ne zararı olurdu? Oysa Allah onları bilir.'),
  ('tr.diyanet', 4, 40, 'Allah şüphesiz zerre kadar haksızlık yapmaz, zerre kadar iyilik olsa onu kat kat arttırır ve yapana büyük ecir verir.'),
  ('tr.diyanet', 4, 41, 'Her ümmete bir şahid getirdiğimiz ve seni de bunlara şahid getirdiğimiz vakit durumları nasıl olacak?'),
  ('tr.diyanet', 4, 42, 'O gün, inkar edip Peygambere baş kaldırmış olanlar, yerle bir olmayı ne kadar isterler ve Allah\'tan bir söz gizleyemezler.'),
  ('tr.diyanet', 4, 43, 'Ey İnananlar! Sarhoşken, ne dediğinizi bilene kadar, cünübken, yolcu olan müstesna gusledene kadar namaza yaklaşmayın. Eğer hasta veya yolculukta iseniz yahut biriniz ayak yolundan gelmişseniz veya kadınlara yaklaşmışsanız ve bu durumlarda su bulamamışsanız tertemiz bir toprağa teyemmüm edin, yüzlerinize ve ellerinize sürün. Allah affeder ve bağışlar.'),
  ('tr.diyanet', 4, 44, 'Kendilerine Kitap\'dan bir pay verilenlerin sapıklığı satın aldıklarını ve sizin yolu sapıtmanızı istediklerini görmüyor musun?'),
  ('tr.diyanet', 4, 45, 'Allah, düşmanlarınızı çok iyi bilir. Allah size dost olarak da yeter, yardımcı olarak da yeter.'),
  ('tr.diyanet', 4, 46, 'Yahudilerden, sözleri yerlerinden değiştirip: "İşittik ve karşı geldik, kulak vermeyerek dinle" ve dillerini eğip bükerek ve dini yererek: "Bizi de dinle" diyenler vardır. Şayet: "İşittik ve itaat ettik, dinle ve bizi gözet" demiş olsalardı, onlar için daha iyi daha doğru olurdu. İşte Allah inkarları yüzünden onlara lanet etmiştir. Onların ancak pek azı inanır.'),
  ('tr.diyanet', 4, 47, 'Ey Kitap verilenler! Yüzleri silip arkaya çevirerek enseler gibi dümdüz yapmadan, yahut cumartesi güncüleri lanetlediğimiz gibi lanetlemeden önce, yanınızdakini tasdik ederek indirdiğimiz Kuran\'a inanın; Allah\'ın emri daima yapılagelmiştir.'),
  ('tr.diyanet', 4, 48, 'Allah kendisine ortak koşmayı elbette bağışlamaz, bundan başkasını dilediğine bağışlar. Allah\'a ortak koşan kimse, şüphesiz büyük bir günahla iftira etmiş olur.'),
  ('tr.diyanet', 4, 49, 'Kendilerini temize çıkaranları görmedin mi? Allah dilediğini temize çıkarır ve kendilerine kıl kadar haksızlık yapmaz.'),
  ('tr.diyanet', 4, 50, 'Allah\'a nasıl yalan yere iftira ettiklerine bir bak. Bu, apaçık bir günah olarak yeter.'),
  ('tr.diyanet', 4, 51, 'Kendilerine kitap verilmiş olanların, puta ve şeytana kanıp, inkar edenlere: "Bunlar, inananlardan daha doğru yoldadırlar" dediklerini görmedin mi?'),
  ('tr.diyanet', 4, 52, 'İşte, Allah\'ın lanetledikleri onlardır. Allah\'ın lanetlediği kişiye asla yardımcı bulamayacaksın.'),
  ('tr.diyanet', 4, 53, 'Yoksa onların hükümranlıktan bir payı mı var? O zaman insanlara bir çekirdek parçası bile vermezler.'),
  ('tr.diyanet', 4, 54, 'Yoksa Allah\'ın bol nimetinden verdiği kimseleri mi çekemiyorlar? Oysa İbrahim ailesine kitap ve hikmet verdik, onlara büyük hükümranlık bahşettik.'),
  ('tr.diyanet', 4, 55, 'Onlardan ona inananlar ve yüz çevirenler vardı. Çılgın bir alev olarak cehennem yeter. Doğrusu, ayetlerimizi inkar edenleri ateşe sokacağız; derilerinin her yanışında, azabı tatmaları için onları başka derilerle değiştireceğiz. Allah güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 4, 56, 'Onlardan ona inananlar ve yüz çevirenler vardı. Çılgın bir alev olarak cehennem yeter. Doğrusu, ayetlerimizi inkar edenleri ateşe sokacağız; derilerinin her yanışında, azabı tatmaları için onları başka derilerle değiştireceğiz. Allah güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 4, 57, 'İnanıp yararlı iş işleyenleri içinde temelli ve ebedi kalacakları, içlerinden ırmaklar akan cennetlere koyacağız. Onlara orada tertemiz eşler vardır. Onları en koyu gölgeliklere yerleştireceğiz.'),
  ('tr.diyanet', 4, 58, 'Hiç şüphesiz Allah size, emanetleri ehline teslim etmenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emreder. Allah size ne güzel öğüt veriyor. Şüphesiz Allah işitir ve görür.'),
  ('tr.diyanet', 4, 59, 'Ey İnananlar! Allah\'a itaat edin, Peygambere ve sizden buyruk sahibi olanlara itaat edin. Eğer bir şeyde çekişirseniz, Allah\'a ve ahiret gününe inanmışsanız onun halini Allah\'a ve Peygambere bırakın. Bu, hayırlı ve netice itibariyle en güzeldir.'),
  ('tr.diyanet', 4, 60, 'Sana indirilen Kuran\'a ve senden önce indirilenlere inandıklarını iddia edenleri görmüyor musun? Putlarının önünde muhakeme olunmalarını isterler. Oysa, onları tanımamakla emr olunmuşlardı. Şeytan onları derin bir sapıklığa saptırmak ister.'),
  ('tr.diyanet', 4, 61, 'Onlara: "Allah\'ın indirdiğine ve Peygambere gelin" dendiği zaman, münafıkların senden büsbütün uzaklaştıklarını görürsün.'),
  ('tr.diyanet', 4, 62, 'Başlarına kendi işlediklerinden ötürü bir musibet çattığında sana gelip: "Biz, iyilik etmek ve uzlaştırmaktan başka bir şey istemedik" diye de nasıl Allah\'a yemin ederler?'),
  ('tr.diyanet', 4, 63, 'İşte bunlarin kalblerinde olanı Allah bilir. Onlardan yüz çevir, onlara öğüt ver, kendilerine tesirli sözler söyle.'),
  ('tr.diyanet', 4, 64, 'Biz her peygamberi ancak, Allah\'ın izniyle, itaat olunması için gönderdik. Onlar, kendilerine yazık ettiklerinde, sana gelip Allah\'tan mağfiret dileseler ve Peygamber de onlara mağfiret dileseydi, Allah\'ın tevbeleri daima kabul ve merhamet eden olduğunu görürlerdi.'),
  ('tr.diyanet', 4, 65, 'Hayır; Rabb\'ine and olsun ki, aralarında çekiştikleri şeylerde seni hakem tayin edip, sonra senin verdiğin hükmü içlerinde bir sıkıntı duymadan tamamen kabul etmedikçe inanmış olmazlar.'),
  ('tr.diyanet', 4, 66, 'Şayet onlara "Kendinizi öldürün" yahut "Memleketinizden çıkın" diye emretmiş olsaydık, pek azından başkaları bunu yapmazlardı. Kendilerine verilen öğüdü yerine getirmiş olsalardı onlar için daha iyi ve daha sağlam olurdu.'),
  ('tr.diyanet', 4, 67, 'O zaman onlara kendi katımızdan büyük bir ecir verir ve onları doğru yola eriştirirdik.'),
  ('tr.diyanet', 4, 68, 'O zaman onlara kendi katımızdan büyük bir ecir verir ve onları doğru yola eriştirirdik.'),
  ('tr.diyanet', 4, 69, 'Kim Allah\'a ve Peygambere itaat ederse, işte onlar Allah\'ın nimetine eriştirdiği peygamberlerle, dosdoğru olanlar, şehidler ve iyilerle beraberdirler. Onlar ne iyi arkadaştırlar!'),
  ('tr.diyanet', 4, 70, 'Bu nimet, Allah\'tandır. Bilen olarak Allah yeter.'),
  ('tr.diyanet', 4, 71, 'Ey İnananlar! İhtiyatlı davranın, bölük bölük veya hep birden savaşa gidin.'),
  ('tr.diyanet', 4, 72, 'Şüphesiz aranızda pek ağır davrananlar vardır; size bir musibet gelirse: "Allah bana iyilikte bulundu, çünkü onlarla beraber bulunmadim" der.'),
  ('tr.diyanet', 4, 73, 'Allah\'tan size bir nimet erişse, and olsun ki, sizinle kendi arasında bir dostluk yokmuş gibi: "Keşki onlarla beraber olsaydım da ben de büyük bir başarı kazansaydım" der.'),
  ('tr.diyanet', 4, 74, 'O halde, dünya hayatı yerine ahireti alanlar, Allah yolunda savaşsınlar. Kim Allah yolunda savaşır, öldürülür veya galib gelirse, Biz ona büyük bir ecir vereceğiz.'),
  ('tr.diyanet', 4, 75, 'Size ne oluyor da: "Rabbimiz! Bizi halkı zalim olan bu şehirden çıkar, katından bize bir sahip çıkan gönder, katından bize bir yardımcı lutfet" diyen zavallı çocuklar, erkekler ve kadınlar uğrunda ve Allah yolunda savaşmıyorsunuz?'),
  ('tr.diyanet', 4, 76, 'İnananlar Allah yolunda savaşırlar, inkar edenler ise tağut yolunda harbederler. Şeytanın dostlarıyla savaşın, esasen şeytanın hilesi zayıftır.'),
  ('tr.diyanet', 4, 77, 'Kendilerine: "Elinizi savaştan çekin, namaz kılın, zekat verin" denenleri görmedin mi? Onlara savaş farz kılındığında, içlerinden bir takımı hemen, insanlardan, Allah\'tan korkar gibi, hatta daha çok korkarlar ve "Rabbimiz! Bize savaşı niçin farz kıldın, bizi yakın bir zamana kadar tehir edemez miydin?" derler. De ki: "Dünya geçimliği azdır, ahiret, Allah\'a karşı gelmekten sakınan için hayırlıdır, size zerre kadar zulmedilmez".'),
  ('tr.diyanet', 4, 78, 'Nerede olursaniz olun, sağlam kaleler içinde bulunsanız bile, ölüm size yetişecektir. Onlara bir iyilik gelirse: "Bu Allah\'tandır" derler, bir kötülüğe uğrarlarsa "Bu, senin tarafındandır" derler. De ki: "Hepsi Allah\'tandır". Bunlara ne oluyor ki, hiçbir sözü anlamaya yanaşmıyorlar?'),
  ('tr.diyanet', 4, 79, 'Sana ne iyilik gelirse Allah\'tandır, sana ne kötülük dokunursa kendindendir. Seni insanlara peygamber gönderdik, şahid olarak Allah yeter.'),
  ('tr.diyanet', 4, 80, 'Peygamber\'e itaat eden, Allah\'a itaat etmiş olur. Kim yüz çevirirse bilsin ki, Biz seni onlara bekçi göndermedik.'),
  ('tr.diyanet', 4, 81, '"Peki" derler, fakat senin yanından çıktıklarında, içlerinden bir takımı, geceleyin senin dediklerinden başka bir şey kurarlar. Allah gece tasarladıklarını yazıyor, onlara aldırış etme. Allah\'a güven, vekil olarak Allah yeter.'),
  ('tr.diyanet', 4, 82, 'Kuran\'ı durup düşünmüyorlar mı? Eğer o Allah\'tan başkasından gelseydi, onda çok aykırılıklar bulurlardı.'),
  ('tr.diyanet', 4, 83, 'Kendilerine güven veya korku hususunda bir haber geldiğinde onu yayarlar; halbuki o haberi Peygamber\'e veya kendilerinden buyruk sahibi olanlara götürselerdi, onlardan sonuç çıkarmaya kadir olanlar onu bilirdi. Allah\'ın size bol nimeti ve rahmeti olmasaydı, pek azınız bir yana, şeytana uyardınız.'),
  ('tr.diyanet', 4, 84, 'Allah yolunda savaş; sen ancak kendinden sorumlusun, inananları teşvik et; umulur ki Allah, inkar edenlerin baskınını önler. Allah\'ın kahrı da, ibret alınacak cezası da pek şiddetlidir.'),
  ('tr.diyanet', 4, 85, 'Kim iyi bir işte aracılık ederse, ona onun sevabından bir pay vardır; kim de kötü bir şeyde aracılık yaparsa, ona o kötülükten bir hisse vardır. Allah, her şeyin karşılığını verir.'),
  ('tr.diyanet', 4, 86, 'Size bir selam verildiği zaman, ondan daha iyisiyle selam verin veya ayniyle mukabele edin. Allah her şeyin hesabını gereği gibi yapandır.'),
  ('tr.diyanet', 4, 87, 'Allah\'tan başka tanrı yoktur, geleceğinde şüphe olmayan kıyamet günü, sizi mutlaka toplayacaktır. Allah\'tan daha doğru sözlü kim olabilir?'),
  ('tr.diyanet', 4, 88, 'Ey müslümanlar! Münafıklar hakkında iki fırka olmanız da niye? Allah onları, yaptıklarından dolayı başaşağı etmiştir. Allah\'ın saptırdığını siz mi yola getirmek istiyorsunuz? Allah\'ın saptırdığı kimseye sen hiç yol bulamayacaksın.'),
  ('tr.diyanet', 4, 89, 'Onlar kendileri inkar ettikleri gibi, keşki siz de inkar etseniz de eşit olsanız isterler. Allah yolunda hicret etmedikçe onlardan dost edinmeyin. Eğer yüz çevirirlerse onları tutun, bulduğunuz yerde öldürün. Onlardan dost ve yardımcı edinmeyin.'),
  ('tr.diyanet', 4, 90, 'Ancak, sizinle kendileri arasında anlaşma olan bir millete sığınanlar yahut sizinle savaştan veya kendi milletleriyle savaşmaktan bıkarak size başvuranlar müstesnadır. Allah dileseydi onları üzerinize çullandırırdı da sizinle savaşırlardı. Eğer sizden uzak durur, sizinle savaşmaz, size barış teklif ederlerse Allah onlara dokunmanıza izin vermez.'),
  ('tr.diyanet', 4, 91, 'Diğerlerinin de sizden ve kendi milletlerinden güvende olmayı istediklerini göreceksiniz. Ne var ki fitneciliğe her çağırıldıklarında ona can atarlar; eğer sizden uzak durmazlar, barış teklif etmezler ve sizden el çekmezlerse onları yakalayın, bulduğunuz yerde öldürün. İşte onların aleyhlerine size apaçık ferman verdik.'),
  ('tr.diyanet', 4, 92, 'Bir müminin diğer mümini yanlışlık dışında öldürmesi asla caiz değildir. Bir mümini yanlışlıkla öldürenin, bir mümin köleyi azad etmesi ve öldürülenin ailesi bağışlamadıkça, ona diyet ödemesi gerekir. Eğer o mümin, size düşman bir topluluktan ise mümin bir köleyi azad etmek gerekir. Şayet aranızda anlaşma olan bir millettense, ailesine diyet ödemek ve mümin bir köleyi azat etmek gerekir. Bulamayana, Allah tarafından tevbesinin kabulü için, ard arda iki ay oruç tutmak gerekir. Allah bilendir. Hakim\'dir.'),
  ('tr.diyanet', 4, 93, 'Kim bir mümini kasden öldürürse cezası, içinde temelli kalacağı cehennemdir. Allah ona gazabetmiş, lanetlemiş ve büyük azab hazırlamıştır.'),
  ('tr.diyanet', 4, 94, 'Ey İnananlar! Allah yolunda yürüdüğünüz vakit, her şeyi iyice anlayın. Size, müslüman olduğunu bildirene, dünya hayatının geçici menfaatine göz dikerek: "Sen mümin değilsin" demeyin. Allah katında birçok ganimetler vardır. Evvelce siz de öyleydiniz. Allah size iyilikte bulundu, iyice araştırıp anlayın, Allah işlediklerinizden şüphesiz haberdardır.'),
  ('tr.diyanet', 4, 95, 'İnananlardan, özürsüz olarak yerlerinde oturanlar ile, mal ve canlariyle cihad edenleri, mertebece, oturanlardan üstün kılmıştır. Allah hepsine de cenneti vadetmiştir, ama Allah, cihad edenleri oturanlara, büyük ecirler, dereceler, mağfiret ve rahmetle üstün kılmıştır. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 96, 'İnananlardan, özürsüz olarak yerlerinde oturanlar ile, mal ve canlariyle cihad edenleri, mertebece, oturanlardan üstün kılmıştır. Allah hepsine de cenneti vadetmiştir, ama Allah, cihad edenleri oturanlara, büyük ecirler, dereceler, mağfiret ve rahmetle üstün kılmıştır. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 97, 'Kendilerine yazık edenlerin melekler canlarını aldıkları zaman onlara: "Ne yaptınız bakalım?" deyince, "Biz yeryüzünde zavallı kimselerdik" diyecekler, melekler de: "Allah\'ın arzı geniş değil miydi? Hicret etseydiniz ya!" cevabını verecekler. Onlarınvaracakları yer cehennemdir. Orası ne kötü dönülecek yerdir!'),
  ('tr.diyanet', 4, 98, 'Çaresiz kalan, yol bulamayan zavallı erkek, kadın ve çocuklar müstesnadırlar.'),
  ('tr.diyanet', 4, 99, 'İşte Allah\'ın bunları affetmesi umulur. Allah Affedendir, Bağışlayan\'dır.'),
  ('tr.diyanet', 4, 100, 'Allah yolunda hicret eden kişi, yeryüzünde çok bereketli yer ve genişlik bulur. Evinden, Allah\'a ve Peygamberine hicret ederek çıkan kimseye ölüm gelirse, onun ecrini vermek Allah\'a düşer. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 101, 'Yolculuk ettiğinizde, kafirlerin size bir fenalık yapmasından korkarsanız, namazı kısaltmanızda size bir sorumluluk yoktur. Zira kafirler, size apaçık düşmandırlar.'),
  ('tr.diyanet', 4, 102, 'Sen içlerinde olup da namazlarını kıldırdığın zaman, bir kısmı seninle beraber namaza dursun ve silahlarını da yanlarına alsınlar; secdeyi yaptıktan sonra onlar arkanıza geçsinler; kılmayan öbür kısım gelsin, seninle beraber kılsınlar, tedbirli olsunlar, silahlarını alsınlar. Kafirler, size ansızın bir baskın vermek için, silah ve eşyanızdan ayrılmış bulunmanızı dilerler. Yağmurdan zarar görecekseniz veya hasta olursanız, silahlarınızı bırakmanıza engel yoktur, fakat dikkatli olun. Allah kafirlere şüphesiz ağır bir azab hazırlamıştır.'),
  ('tr.diyanet', 4, 103, 'Namazı kıldıktan başka, Allah\'ı ayakta iken, otururken, yan yatarken de anın. Emniyete kavuştuğunuzda, namazı gereğince kılın. Namaz şüphesiz, inananlara belirli vakitlerde farz kılınmıştır.'),
  ('tr.diyanet', 4, 104, 'Düşman milleti kovalamakta gevşeklik göstermeyin. Eğer siz acı çekiyorsanız, şüphesiz onlar da sizin çektiğiniz gibi acı çekiyorlar; oysa siz Allah\'tan onların beklemedikleri şeyleri bekliyorsunuz. Allah Bilendir, Hakim olandır.'),
  ('tr.diyanet', 4, 105, 'Doğrusu, insanlar arasında Allah\'ın sana gösterdiği gibi hükmedesin diye Kitap\'ı sana hak olarak indirdik; hakkı gözet, hainlerden taraf olma.'),
  ('tr.diyanet', 4, 106, 'Allah\'tan mağfiret dile. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 107, 'Kendilerine hainlik edenlerden yana uğraşmaya kalkma. Allah, hainlikte direnen suçluyu sevmez.'),
  ('tr.diyanet', 4, 108, 'Allah\'ın razı olmadığı sözü gece kurarlarken, onu, insanlardan gizliyorlar da kendileriyle beraber olan Allah\'dan gizlemiyorlar. Allah işlediklerinin hepsini bilmektedir.'),
  ('tr.diyanet', 4, 109, 'İşte siz dünya hayatında onları savunuyorsunuz ama, kıyamet günü onları Allah\'a karşı kim savunacak? Veya onların vekaletini kim üzerine alacaktır?'),
  ('tr.diyanet', 4, 110, 'Kim kötülük işler veya kendine yazık eder de sonra Allah\'tan bağışlanma dilerse, Allah\'ı mağfiret ve merhamet sahibi olarak bulur.'),
  ('tr.diyanet', 4, 111, 'Kim günah işlerse bunu ancak kendi aleyhine yapmış olur. Allah bilendir, Hakim\'dir.'),
  ('tr.diyanet', 4, 112, 'Kim yanılır veya suç işler de sonra onu bir suçsuzun üzerine atarsa, şüphesiz iftira etmiş, apaçık bir günah yüklenmiş olur.'),
  ('tr.diyanet', 4, 113, 'Eğer sana Allah\'ın bol nimeti ve rahmeti olmasaydı, onlardan bir takımı seni sapıtmaya çalışırdı. Halbuki onlar kendilerinden başkasını saptıramazlar, sana da bir zarar vermezler. Allah sana Kitap ve hikmet indirmiş, sana bilmediğini öğretmiştir. Allah\'ın sana olan nimeti ne büyüktür.'),
  ('tr.diyanet', 4, 114, 'Ancak sadaka vermeyi yahut iyilik yapmayı ve insanların arasını düzeltmeyi gözeten kimseler müstesna, onların gizli toplantılarının çoğunda hayır yoktur. Bunları, Allah\'ın rızasını kazanmak için yapana büyük ecir vereceğiz.'),
  ('tr.diyanet', 4, 115, 'Doğru yol kendisine apaçık belli olduktan sonra, Peygamberden ayrılıp, inananların yolundan başkasına uyan kimseyi, döndüğü yöne döndürür ve onu cehenneme sokarız. Orası ne kötü bir dönüş yeridir!'),
  ('tr.diyanet', 4, 116, 'Allah, kendisine ortak koşulmasını elbette bağışlamaz, bundan başkasını dilediğine bağışlar. Allah\'a ortak koşan kimse derin bir sapıklığa sapmış olur.'),
  ('tr.diyanet', 4, 117, 'Onlar Allah\'ı bırakıp tanrıçalara taparlar ve: "Elbette senin kullarından belli bir takımı alıp onları saptıracağım, onlara kuruntu kurduracağım, develerin kulaklarını yarmalarını emredeceğim, Allah\'ın yarattığını değiştirmelerini emredeceğim" diyen, Allah\'ın lanet ettiği azgın şeytana taparlar. Allah\'ı bırakıp şeytanı dost edinen şüphesiz açıktan açığa kayba uğramıştır.'),
  ('tr.diyanet', 4, 118, 'Onlar Allah\'ı bırakıp tanrıçalara taparlar ve: "Elbette senin kullarından belli bir takımı alıp onları saptıracağım, onlara kuruntu kurduracağım, develerin kulaklarını yarmalarını emredeceğim, Allah\'ın yarattığını değiştirmelerini emredeceğim" diyen, Allah\'ın lanet ettiği azgın şeytana taparlar. Allah\'ı bırakıp şeytanı dost edinen şüphesiz açıktan açığa kayba uğramıştır.'),
  ('tr.diyanet', 4, 119, 'Onlar Allah\'ı bırakıp tanrıçalara taparlar ve: "Elbette senin kullarından belli bir takımı alıp onları saptıracağım, onlara kuruntu kurduracağım, develerin kulaklarını yarmalarını emredeceğim, Allah\'ın yarattığını değiştirmelerini emredeceğim" diyen, Allah\'ın lanet ettiği azgın şeytana taparlar. Allah\'ı bırakıp şeytanı dost edinen şüphesiz açıktan açığa kayba uğramıştır.'),
  ('tr.diyanet', 4, 120, 'Şeytan onlara vadediyor, onları kuruntulara düşürüyor, ancak aldatmak için vaadde bulunuyor.'),
  ('tr.diyanet', 4, 121, 'İşte onların varacağı yer cehennemdir. Oradan kaçacak yer de bulamıyacaklardır.'),
  ('tr.diyanet', 4, 122, 'İnanıp yararlı işler yapanları, Allah\'ın gerçek bir sözü olarak, içinde temelli ve ebedi kalacakları, içinden ırmaklar akan cennetlere koyacağız. Allah\'tan daha doğru sözlü kim vardır?'),
  ('tr.diyanet', 4, 123, 'Bu, sizin kuruntularınıza ve Kitap ehlinin kuruntularına göre değildir. Kim fenalık yaparsa cezasını görür, kendisine Allah\'tan başka ne dost ve ne de yardımcı bulur.'),
  ('tr.diyanet', 4, 124, 'Erkek veya kadın, mümin olarak, kim yararlı işler işlerse, işte onlar cennete girerler, kendilerine zerre kadar zulmedilmez.'),
  ('tr.diyanet', 4, 125, 'İyilik yaparak kendisini Allah\'a teslim edip, hakka yönelen İbrahim\'in dinine uyandan, din bakımından daha iyi kim olabilir? Allah İbrahim\'i dost edinmişti.'),
  ('tr.diyanet', 4, 126, 'Göklerde olanlar da, yerde olanlar da Allah\'ındır. Allah her şeyi kuşatır.'),
  ('tr.diyanet', 4, 127, 'Kadınlar hakkında senden fetva isterler, de ki: "Onlar hakkında fetvayı size Allah veriyor: "Bu fetva, kendilerine yazılan şeyi vermeyip kendileriyle evlenmeyi arzuladığınız yetim kadınlara ve bir de zavallı çocuklara ve yetimlere doğrulukla bakmanız hususunda Kitap\'da size okunandır". Ne iyilik yaparsaniz Allah onu şüphesiz bilir.'),
  ('tr.diyanet', 4, 128, 'Eğer kadın, kocasının serkeşliğinden veya aldırışsızlığından endişe ederse, aralarında anlaşmaya çalışmalarında kendilerine bir engel yoktur. Anlaşmak daha hayırlıdır. Nefisler kıskançlığa meyyaldir. Eğer iyi davranır ve haksızlıktan sakınırsaniz bilin ki, Allah işlediklerinizden şüphesiz haberdardır.'),
  ('tr.diyanet', 4, 129, 'Adil hareket etmeye ne kadar uğraşsanız, kadınlar arasında eşitlik yapamayacaksınız, bari bir tarafa kalben tamamen meyletmeyin ki diğerini askıdaymış gibi bırakmış olmayasınız. İşleri düzeltir ve haksızlıktan sakınırsanız bilin ki Allah şüphesiz bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 130, 'Ayrılırlarsa, Allah her birini nimetinin genişliğiyle yoksulluktan kurtarır, Allah her şeyi kaplayandır. Hakim\'dir.'),
  ('tr.diyanet', 4, 131, 'Göklerde olanlar da, yerde olanlar da Allah\'ındır. And olsun ki, sizden önce Kitap verilenlere ve size, Allah\'tan sakınmanızı tavsiye ettik. İnkar ederseniz bilin ki, göklerde olanlar da yerde olanlar da Allah\'ındır.'),
  ('tr.diyanet', 4, 132, 'Göklerde ve yerde olanlar Allah\'ındır. Vekil olarak Allah yeter.'),
  ('tr.diyanet', 4, 133, 'Ey İnsanlar! Allah dilerse sizi yok eder, başkalarını getirir, O, buna Kadir\'dir.'),
  ('tr.diyanet', 4, 134, 'Dünya nimetini kim isterse, bilsin ki, dünyanın ve ahiretin nimeti Allah\'ın katındadır. Allah işitir ve görür.'),
  ('tr.diyanet', 4, 135, 'Ey İnananlar! Kendiniz, ana babanız ve yakınlarınız aleyhlerine de olsa, Allah için şahit olarak adaleti gözetin; ister zengin, ister fakir olsun, Allah onlara daha yakındır. Adaletinizde heveslere uymayın. Eğer eğriltirseniz veya yüz çevirirseniz bilin ki, Allah işlediklerinizden şüphesiz haberdardır.'),
  ('tr.diyanet', 4, 136, 'Ey İnananlar! Allah\'a, Peygamberine, Peygamberine indirdiği Kitap\'a ve daha önce indirdiği Kitap\'a inanmakta sebat gösterin. Kim Allah\'ı, meleklerini, kitaplarını, peygamberlerini ve ahiret gününu inkar ederse, şüphesiz derin bir sapıklığa sapmıştır.'),
  ('tr.diyanet', 4, 137, 'Doğrusu inanıp sonra inkar edenleri, sonra inanıp tekrar inkar edenleri, sonra da inkarları artmış olanları Allah bağışlamaz; onları doğru yola eriştirmez.'),
  ('tr.diyanet', 4, 138, 'Münafıklara, kendilerine elem verici bir azab olduğunu müjdele.'),
  ('tr.diyanet', 4, 139, 'Onlar, inananları bırakıp da kafirleri dost edinirler; onların tarafında bir şeref ve kudret mi arıyorlar? Doğrusu kudret bütün olarak Allah\'ındır.'),
  ('tr.diyanet', 4, 140, 'O, size Kitap\'da "Allah\'ın ayetlerinin inkar edildiğini ve alaya alındığını işittiğinizde, başka bir söze geçmedikçe, onlarla bir arada oturmayın, yoksa siz de onlar gibi olursunuz" diye indirdi. Doğrusu Allah münafıkları ve kafirlerin hepsini cehennemde toplayacaktır.'),
  ('tr.diyanet', 4, 141, 'Sizi gözleyenler, Allah\'tan size bir zafer gelirse, "Sizinle beraber değil miydik?" derler; eğer kafirlere bir pay çıkarsa, onlara: "Size üstünlük sağlayarak sizi müminlerden korumadık mı?" derler. Allah kıyamet günü aranızda hüküm verir. Allah inkarcılara, inananlar aleyhinde asla fırsat vermeyecektir.'),
  ('tr.diyanet', 4, 142, 'Doğrusu münafıklar Allah\'ı aldatmağa çalışırlar, oysa O, onlara aldatmanın ne olduğunu gösterecektir. Onlar namaza tembel tembel kalkarlar, insanlara gösteriş yaparlar, ne onlarla, ne de bunlarla olur, ikisi arasında bocalayarak Allah\'ı pek az anarlar. Allah\'ın saptırdığı kimseye yol bulamayacaksın.'),
  ('tr.diyanet', 4, 143, 'Doğrusu münafıklar Allah\'ı aldatmağa çalışırlar, oysa O, onlara aldatmanın ne olduğunu gösterecektir. Onlar namaza tembel tembel kalkarlar, insanlara gösteriş yaparlar, ne onlarla, ne de bunlarla olur, ikisi arasında bocalayarak Allah\'ı pek az anarlar. Allah\'ın saptırdığı kimseye yol bulamayacaksın.'),
  ('tr.diyanet', 4, 144, 'Ey İnananlar! Müminleri bırakıp kafirleri dost edinmeyin. Allah\'ın aleyhinize apaçık bir ferman vermesini mi istersiniz?'),
  ('tr.diyanet', 4, 145, 'Doğrusu münafıklar cehennemin en alt tabakasındadırlar. Onlara yardımcı bulamayacaksın.'),
  ('tr.diyanet', 4, 146, 'Ancak tevbe edenler, nefislerini ıslah edenler, Allah\'ın Kitap\'ına sarılanlar ve dinlerine Allah için candan bağlananlar müstesnadır. Onlar inananlarla beraberdirler. Allah müminlere büyük ecir verecektir.'),
  ('tr.diyanet', 4, 147, 'Şükreder ve inanırsanız, Allah size niçin azabetsin? Allah şükrün karşılığını verir ve bilir.'),
  ('tr.diyanet', 4, 148, 'Allah, zulme uğrayan kimseden başkasının, kötülüğü sözle bile açıklamasını sevmez. Allah işitir ve bilir.'),
  ('tr.diyanet', 4, 149, 'Bir iyiliği açığa vurur veya gizler yahut bir kötülüğü affederseniz, bilin ki Allah da Affeden\'dir, Güçlü Olan\'dır.'),
  ('tr.diyanet', 4, 150, 'Allah\'ı ve peygamberlerini inkar eden, Allah\'la peygamberleri arasını ayırmak isteyen, "Bir kısmına inanır bir kısmını inkar ederiz" diyerek ikisi arasında bir yol tutmak isteyenler, işte onlar gerçekten kafir olanlardır. Kafirlere ağır bir azab hazırlamışızdır.'),
  ('tr.diyanet', 4, 151, 'Allah\'ı ve peygamberlerini inkar eden, Allah\'la peygamberleri arasını ayırmak isteyen, "Bir kısmına inanır bir kısmını inkar ederiz" diyerek ikisi arasında bir yol tutmak isteyenler, işte onlar gerçekten kafir olanlardır. Kafirlere ağır bir azab hazırlamışızdır.'),
  ('tr.diyanet', 4, 152, 'Allah\'a ve peygamberlerine inanıp, onlardan hiçbirini ayırmayanlara, işte onlara Allah ecirlerini verecektir. O, bağışlar ve merhamet eder.'),
  ('tr.diyanet', 4, 153, 'Kitap ehli, senin kendilerine gökten bir kitap indirmeni isterler. Musa\'dan bundan daha büyüğünü istemişlerdi ve "Bize Allah\'ı apaçık göster" demişlerdi. Zulümlerinden ötürü onları yıldırım çarpmıştı. Belgeler kendilerine geldikten sonra da, buzağıyı tanrı olarak benimsediler, fakat bunları affettik ve Musa\'ya apaçık bir hüccet verdik, söz vermelerine karşılık Tur dağını üzerlerine kaldırdık ve onlara: "Kapıdan secde ederek girin" dedik, "Cumartesileri aşırı gitmeyin" dedik, onlardan sağlam bir söz aldık.'),
  ('tr.diyanet', 4, 154, 'Kitap ehli, senin kendilerine gökten bir kitap indirmeni isterler. Musa\'dan bundan daha büyüğünü istemişlerdi ve "Bize Allah\'ı apaçık göster" demişlerdi. Zulümlerinden ötürü onları yıldırım çarpmıştı. Belgeler kendilerine geldikten sonra da, buzağıyı tanrı olarak benimsediler, fakat bunları affettik ve Musa\'ya apaçık bir hüccet verdik, söz vermelerine karşılık Tur dağını üzerlerine kaldırdık ve onlara: "Kapıdan secde ederek girin" dedik, "Cumartesileri aşırı gitmeyin" dedik, onlardan sağlam bir söz aldık.'),
  ('tr.diyanet', 4, 155, 'Sözleşmelerini bozmaları, Allah\'ın ayetlerini inkar etmeleri, peygamberleri haksız yere öldürmeleri, "Kalblerimiz perdelidir" demelerinden ötürü Allah, evet, inkarlarına karşılık onların kalblerini mühürledi, onun için bunların ancak pek azı inanır.'),
  ('tr.diyanet', 4, 156, 'Bu, bir de inkarlarından, Meryem\'e büyük bir iftirada bulunmalarından ve: "Meryem oğlu İsa Mesih\'i, Allah\'ın elçisini öldürdük" demelerinden ötürüdür. Oysa onu öldürmediler ve asmadılar, fakat onlara öyle göründü. Ayrılığa düştükleri şeyde doğrusu şüphededirler, bu husustaki bilgileri ancak sanıya uymaktan ibarettir, kesin olarak onu öldürmediler, bilakis Allah onu kendi katına yükseltti. Allah Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 4, 157, 'Bu, bir de inkarlarından, Meryem\'e büyük bir iftirada bulunmalarından ve: "Meryem oğlu İsa Mesih\'i, Allah\'ın elçisini öldürdük" demelerinden ötürüdür. Oysa onu öldürmediler ve asmadılar, fakat onlara öyle göründü. Ayrılığa düştükleri şeyde doğrusu şüphededirler, bu husustaki bilgileri ancak sanıya uymaktan ibarettir, kesin olarak onu öldürmediler, bilakis Allah onu kendi katına yükseltti. Allah Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 4, 158, 'Bu, bir de inkarlarından, Meryem\'e büyük bir iftirada bulunmalarından ve: "Meryem oğlu İsa Mesih\'i, Allah\'ın elçisini öldürdük" demelerinden ötürüdür. Oysa onu öldürmediler ve asmadılar, fakat onlara öyle göründü. Ayrılığa düştükleri şeyde doğrusu şüphededirler, bu husustaki bilgileri ancak sanıya uymaktan ibarettir, kesin olarak onu öldürmediler, bilakis Allah onu kendi katına yükseltti. Allah Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 4, 159, 'Kitap ehlinden, ölmeden önce, İsa\'ya inanmayacak yoktur. O, gerektiği gibi inanmadıklarından, kıyamet günü onların aleyhine şahit olur.'),
  ('tr.diyanet', 4, 160, 'Yahudilerin haksızlıklarından, çoklarını Allah yolundan menetmelerinden, yasak edilmişken faiz almaları ve insanların mallarını haksızlıkla yemelerinden ötürü kendilerine helal kılınan temiz şeyleri onlara haram kıldık. Onlardan inkar edenlere, elem verici azab hazırladık.'),
  ('tr.diyanet', 4, 161, 'Yahudilerin haksızlıklarından, çoklarını Allah yolundan menetmelerinden, yasak edilmişken faiz almaları ve insanların mallarını haksızlıkla yemelerinden ötürü kendilerine helal kılınan temiz şeyleri onlara haram kıldık. Onlardan inkar edenlere, elem verici azab hazırladık.'),
  ('tr.diyanet', 4, 162, 'Fakat onlardan ilimde derinleşmiş olanlara, sana indirilen Kitap\'a ve senden önce indirilen Kitap\'a inanan müminlere, namaz kılanlara, zekat verenlere, Allah\'a ve ahiret gününe inananlara, elbette büyük ecir vereceğiz.'),
  ('tr.diyanet', 4, 163, 'Nuh\'a, ondan sonra gelen peygamberlere vahyettiğimiz, İbrahim\'e, İsmail\'e, İshak\'a, Yakub\'a, torunlarına, İsa\'ya, Eyyub\'a, Yunus\'a, Harun\'a ve Süleyman\'a vahyettiğimiz gibi şüphesiz sana da vahyettik. Davud\'a da Zebur verdik.'),
  ('tr.diyanet', 4, 164, 'Peygamberlerden sonra, insanların Allah\'a karşı bir hüccetleri olmaması için, gönderilen müjdeci ve uyarıcı peygamberlerden bir kısmını daha önce sana anlatmış, bir kısmını da anlatmamıştık. Allah, Musa\'ya hitabetmişti. Allah güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 4, 165, 'Peygamberlerden sonra, insanların Allah\'a karşı bir hüccetleri olmaması için, gönderilen müjdeci ve uyarıcı peygamberlerden bir kısmını daha önce sana anlatmış, bir kısmını da anlatmamıştık. Allah, Musa\'ya hitabetmişti. Allah güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 4, 166, 'Fakat Allah sana indirdiğine şahidlik eder, onu bilerek indirmiştir, melekler de şahidlik ederler. Şahid olarak Allah yeter.'),
  ('tr.diyanet', 4, 167, 'İnkar edenler, Allah yolundan alıkoyanlar, şüphesiz derin bir sapıklığa sapmışlardır.'),
  ('tr.diyanet', 4, 168, 'İnkar edenleri ve zalimleri Allah şüphesiz bağışlamaz, onları içinde temelli ve ebediyyen kalacakları cehennem yolundan başka bir yola eriştirmez. Bu, Allah\'a kolaydır.'),
  ('tr.diyanet', 4, 169, 'İnkar edenleri ve zalimleri Allah şüphesiz bağışlamaz, onları içinde temelli ve ebediyyen kalacakları cehennem yolundan başka bir yola eriştirmez. Bu, Allah\'a kolaydır.'),
  ('tr.diyanet', 4, 170, 'Ey İnsanlar! Peygamber Rabbiniz\'den size gerçekle geldi, inanın, bu sizin hayrınızadır. İnkar ederseniz, bilin ki, göklerde ve yerde olanlar Allah\'ındır. Allah bilendir. Hakim\'dir.'),
  ('tr.diyanet', 4, 171, 'Ey Kitap ehli! Dininizde taşkınlık etmeyin. Allah hakkında ancak gerçeği söyleyin. Meryem oğlu İsa Mesih, Allah\'ın peygamberi, Meryem\'e ulaştırdığı kelimesi ve kendinden bir ruhtur. Allah\'a ve peygamberlerine inanın, "üçtür" demeyin, vazgeçin, bu hayrınızadır. Allah ancak bir tek Tanrı\'dır, çocuğu olmaktan münezzehtir, göklerde olanlar da yerde olanlar da O\'nundur. Vekil olarak Allah yeter.'),
  ('tr.diyanet', 4, 172, 'Mesih de, gözde melekler de Allah\'a kul olmaktan asla çekinmezler. Kim O\'na kulluktan çekinir ve büyüklük taslarsa, bilsin ki, O, hepsini huzuruna toplayacaktır.'),
  ('tr.diyanet', 4, 173, 'İnananlara ve yararlı iş işleyenlere, ecirlerini ödeyecek, onlara olan bol nimetini daha da artıracaktır. Kulluk etmekten çekinenleri ve büyüklük taslayanları elem verici bir azaba uğratacaktır. Onlar kendilerine Allah\'tan başka bir dost ve yardımcı bulamazlar.'),
  ('tr.diyanet', 4, 174, 'Ey İnsanlar! Rabbiniz\'den size açık bir delil geldi, size apaçık bir nur, Kuran indirdik.'),
  ('tr.diyanet', 4, 175, 'Allah kendisine inananları ve Kitabına sarılanları rahmetine ve bol nimetine kavuşturacak, onları Kendisine götüren doğru yola eriştirecektir.'),
  ('tr.diyanet', 4, 176, 'Senden fetva isterler, de ki: "Allah size ikinci dereceden mirasçılar hakkında fetva veriyor: "Şayet çocuğu olmayıp bir kızkardeşi bulunan kimse ölürse, bıraktığının yarısı kızkardeşe kalır. Fakat kızkardeşinin çocuğu yoksa kendisi, ona tamamen varis olur. Eğer iki kızkardeş kalmışsa, bıraktığının üçte ikisi onlaradır. Eğer mirasçılar erkek ve kadın kardeşlerse, erkeğe, iki dişinin hissesi kadar vardır. Doğru yoldan saparsınız diye Allah size açıklıyor." Allah her şeyi bilir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 4, 1, 'Hai sekalian manusia, bertakwalah kepada Tuhan-mu yang telah menciptakan kamu dari seorang diri, dan dari padanya Allah menciptakan isterinya; dan dari pada keduanya Allah memperkembang biakkan laki-laki dan perempuan yang banyak. Dan bertakwalah kepada Allah yang dengan (mempergunakan) nama-Nya kamu saling meminta satu sama lain, dan (peliharalah) hubungan silaturrahim. Sesungguhnya Allah selalu menjaga dan mengawasi kamu.'),
  ('id.indonesian', 4, 2, 'Dan berikanlah kepada anak-anak yatim (yang sudah balig) harta mereka, jangan kamu menukar yang baik dengan yang buruk dan jangan kamu makan harta mereka bersama hartamu. Sesungguhnya tindakan-tindakan (menukar dan memakan) itu, adalah dosa yang besar.'),
  ('id.indonesian', 4, 3, 'Dan jika kamu takut tidak akan dapat berlaku adil terhadap (hak-hak) perempuan yang yatim (bilamana kamu mengawininya), maka kawinilah wanita-wanita (lain) yang kamu senangi: dua, tiga atau empat. Kemudian jika kamu takut tidak akan dapat berlaku adil, maka (kawinilah) seorang saja, atau budak-budak yang kamu miliki. Yang demikian itu adalah lebih dekat kepada tidak berbuat aniaya.'),
  ('id.indonesian', 4, 4, 'Berikanlah maskawin (mahar) kepada wanita (yang kamu nikahi) sebagai pemberian dengan penuh kerelaan. Kemudian jika mereka menyerahkan kepada kamu sebagian dari maskawin itu dengan senang hati, maka makanlah (ambillah) pemberian itu (sebagai makanan) yang sedap lagi baik akibatnya.'),
  ('id.indonesian', 4, 5, 'Dan janganlah kamu serahkan kepada orang-orang yang belum sempurna akalnya, harta (mereka yang ada dalam kekuasaanmu) yang dijadikan Allah sebagai pokok kehidupan. Berilah mereka belanja dan pakaian (dari hasil harta itu) dan ucapkanlah kepada mereka kata-kata yang baik.'),
  ('id.indonesian', 4, 6, 'Dan ujilah anak yatim itu sampai mereka cukup umur untuk kawin. Kemudian jika menurut pendapatmu mereka telah cerdas (pandai memelihara harta), maka serahkanlah kepada mereka harta-hartanya. Dan janganlah kamu makan harta anak yatim lebih dari batas kepatutan dan (janganlah kamu) tergesa-gesa (membelanjakannya) sebelum mereka dewasa. Barang siapa (di antara pemelihara itu) mampu, maka hendaklah ia menahan diri (dari memakan harta anak yatim itu) dan barangsiapa yang miskin, maka bolehlah ia makan harta itu menurut yang patut. Kemudian apabila kamu menyerahkan harta kepada mereka, maka hendaklah kamu adakan saksi-saksi (tentang penyerahan itu) bagi mereka. Dan cukuplah Allah sebagai Pengawas (atas persaksian itu).'),
  ('id.indonesian', 4, 7, 'Bagi orang laki-laki ada hak bagian dari harta peninggalan ibu-bapa dan kerabatnya, dan bagi orang wanita ada hak bagian (pula) dari harta peninggalan ibu-bapa dan kerabatnya, baik sedikit atau banyak menurut bahagian yang telah ditetapkan.'),
  ('id.indonesian', 4, 8, 'Dan apabila sewaktu pembagian itu hadir kerabat, anak yatim dan orang miskin, maka berilah mereka dari harta itu (sekedarnya) dan ucapkanlah kepada mereka perkataan yang baik.'),
  ('id.indonesian', 4, 9, 'Dan hendaklah takut kepada Allah orang-orang yang seandainya meninggalkan dibelakang mereka anak-anak yang lemah, yang mereka khawatir terhadap (kesejahteraan) mereka. Oleh sebab itu hendaklah mereka bertakwa kepada Allah dan hendaklah mereka mengucapkan perkataan yang benar.'),
  ('id.indonesian', 4, 10, 'Sesungguhnya orang-orang yang memakan harta anak yatim secara zalim, sebenarnya mereka itu menelan api sepenuh perutnya dan mereka akan masuk ke dalam api yang menyala-nyala (neraka).'),
  ('id.indonesian', 4, 11, 'Allah mensyari\'atkan bagimu tentang (pembagian pusaka untuk) anak-anakmu. Yaitu: bahagian seorang anak lelaki sama dengan bagahian dua orang anak perempuan; dan jika anak itu semuanya perempuan lebih dari dua, maka bagi mereka dua pertiga dari harta yang ditinggalkan; jika anak perempuan itu seorang saja, maka ia memperoleh separo harta. Dan untuk dua orang ibu-bapa, bagi masing-masingnya seperenam dari harta yang ditinggalkan, jika yang meninggal itu mempunyai anak; jika orang yang meninggal tidak mempunyai anak dan ia diwarisi oleh ibu-bapanya (saja), maka ibunya mendapat sepertiga; jika yang meninggal itu mempunyai beberapa saudara, maka ibunya mendapat seperenam. (Pembagian-pembagian tersebut di atas) sesudah dipenuhi wasiat yang ia buat atau (dan) sesudah dibayar hutangnya. (Tentang) orang tuamu dan anak-anakmu, kamu tidak mengetahui siapa di antara mereka yang lebih dekat (banyak) manfaatnya bagimu. Ini adalah ketetapan dari Allah. Sesungguhnya Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 12, 'Dan bagimu (suami-suami) seperdua dari harta yang ditinggalkan oleh isteri-isterimu, jika mereka tidak mempunyai anak. Jika isteri-isterimu itu mempunyai anak, maka kamu mendapat seperempat dari harta yang ditinggalkannya sesudah dipenuhi wasiat yang mereka buat atau (dan) seduah dibayar hutangnya. Para isteri memperoleh seperempat harta yang kamu tinggalkan jika kamu tidak mempunyai anak. Jika kamu mempunyai anak, maka para isteri memperoleh seperdelapan dari harta yang kamu tinggalkan sesudah dipenuhi wasiat yang kamu buat atau (dan) sesudah dibayar hutang-hutangmu. Jika seseorang mati, baik laki-laki maupun perempuan yang tidak meninggalkan ayah dan tidak meninggalkan anak, tetapi mempunyai seorang saudara laki-laki (seibu saja) atau seorang saudara perempuan (seibu saja), maka bagi masing-masing dari kedua jenis saudara itu seperenam harta. Tetapi jika saudara-saudara seibu itu lebih dari seorang, maka mereka bersekutu dalam yang sepertiga itu, sesudah dipenuhi wasiat yang dibuat olehnya atau sesudah dibayar hutangnya dengan tidak memberi mudharat (kepada ahli waris). (Allah menetapkan yang demikian itu sebagai) syari\'at yang benar-benar dari Allah, dan Allah Maha Mengetahui lagi Maha Penyantun.'),
  ('id.indonesian', 4, 13, '(Hukum-hukum tersebut) itu adalah ketentuan-ketentuan dari Allah. Barangsiapa taat kepada Allah dan Rasul-Nya, niscaya Allah memasukkannya kedalam surga yang mengalir didalamnya sungai-sungai, sedang mereka kekal di dalamnya; dan itulah kemenangan yang besar.'),
  ('id.indonesian', 4, 14, 'Dan barangsiapa yang mendurhakai Allah dan Rasul-Nya dan melanggar ketentuan-ketentuan-Nya, niscaya Allah memasukkannya ke dalam api neraka sedang ia kekal di dalamnya; dan baginya siksa yang menghinakan.'),
  ('id.indonesian', 4, 15, 'Dan (terhadap) para wanita yang mengerjakan perbuatan keji, hendaklah ada empat orang saksi diantara kamu (yang menyaksikannya). Kemudian apabila mereka telah memberi persaksian, maka kurunglah mereka (wanita-wanita itu) dalam rumah sampai mereka menemui ajalnya, atau sampai Allah memberi jalan lain kepadanya.'),
  ('id.indonesian', 4, 16, 'Dan terhadap dua orang yang melakukan perbuatan keji di antara kamu, maka berilah hukuman kepada keduanya, kemudian jika keduanya bertaubat dan memperbaiki diri, maka biarkanlah mereka. Sesungguhnya Allah Maha Penerima taubat lagi Maha Penyayang.'),
  ('id.indonesian', 4, 17, 'Sesungguhnya taubat di sisi Allah hanyalah taubat bagi orang-orang yang mengerjakan kejahatan lantaran kejahilan, yang kemudian mereka bertaubat dengan segera, maka mereka itulah yang diterima Allah taubatnya; dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 18, 'Dan tidaklah taubat itu diterima Allah dari orang-orang yang mengerjakan kejahatan (yang) hingga apabila datang ajal kepada seseorang di antara mereka, (barulah) ia mengatakan: "Sesungguhnya saya bertaubat sekarang". Dan tidak (pula diterima taubat) orang-orang yang mati sedang mereka di dalam kekafiran. Bagi orang-orang itu telah Kami sediakan siksa yang pedih.'),
  ('id.indonesian', 4, 19, 'Hai orang-orang yang beriman, tidak halal bagi kamu mempusakai wanita dengan jalan paksa dan janganlah kamu menyusahkan mereka karena hendak mengambil kembali sebagian dari apa yang telah kamu berikan kepadanya, terkecuali bila mereka melakukan pekerjaan keji yang nyata. Dan bergaullah dengan mereka secara patut. Kemudian bila kamu tidak menyukai mereka, (maka bersabarlah) karena mungkin kamu tidak menyukai sesuatu, padahal Allah menjadikan padanya kebaikan yang banyak.'),
  ('id.indonesian', 4, 20, 'Dan jika kamu ingin mengganti isterimu dengan isteri yang lain, sedang kamu telah memberikan kepada seseorang di antara mereka harta yang banyak, maka janganlah kamu mengambil kembali dari padanya barang sedikitpun. Apakah kamu akan mengambilnya kembali dengan jalan tuduhan yang dusta dan dengan (menanggung) dosa yang nyata?'),
  ('id.indonesian', 4, 21, 'Bagaimana kamu akan mengambilnya kembali, padahal sebagian kamu telah bergaul (bercampur) dengan yang lain sebagai suami-isteri. Dan mereka (isteri-isterimu) telah mengambil dari kamu perjanjian yang kuat.'),
  ('id.indonesian', 4, 22, 'Dan janganlah kamu kawini wanita-wanita yang telah dikawini oleh ayahmu, terkecuali pada masa yang telah lampau. Sesungguhnya perbuatan itu amat keji dan dibenci Allah dan seburuk-buruk jalan (yang ditempuh).'),
  ('id.indonesian', 4, 23, 'Diharamkan atas kamu (mengawini) ibu-ibumu; anak-anakmu yang perempuan; saudara-saudaramu yang perempuan, saudara-saudara bapakmu yang perempuan; saudara-saudara ibumu yang perempuan; anak-anak perempuan dari saudara-saudaramu yang laki-laki; anak-anak perempuan dari saudara-saudaramu yang perempuan; ibu-ibumu yang menyusui kamu; saudara perempuan sepersusuan; ibu-ibu isterimu (mertua); anak-anak isterimu yang dalam pemeliharaanmu dari isteri yang telah kamu campuri, tetapi jika kamu belum campur dengan isterimu itu (dan sudah kamu ceraikan), maka tidak berdosa kamu mengawininya; (dan diharamkan bagimu) isteri-isteri anak kandungmu (menantu); dan menghimpunkan (dalam perkawinan) dua perempuan yang bersaudara, kecuali yang telah terjadi pada masa lampau; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 24, 'dan (diharamkan juga kamu mengawini) wanita yang bersuami, kecuali budak-budak yang kamu miliki (Allah telah menetapkan hukum itu) sebagai ketetapan-Nya atas kamu. Dan dihalalkan bagi kamu selain yang demikian (yaitu) mencari isteri-isteri dengan hartamu untuk dikawini bukan untuk berzina. Maka isteri-isteri yang telah kamu nikmati (campuri) di antara mereka, berikanlah kepada mereka maharnya (dengan sempurna), sebagai suatu kewajiban; dan tiadalah mengapa bagi kamu terhadap sesuatu yang kamu telah saling merelakannya, sesudah menentukan mahar itu. Sesungguhnya Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 25, 'Dan barangsiapa diantara kamu (orang merdeka) yang tidak cukup perbelanjaannya untuk mengawini wanita merdeka lagi beriman, ia boleh mengawini wanita yang beriman, dari budak-budak yang kamu miliki. Allah mengetahui keimananmu; sebahagian kamu adalah dari sebahagian yang lain, karena itu kawinilah mereka dengan seizin tuan mereka, dan berilah maskawin mereka menurut yang patut, sedang merekapun wanita-wanita yang memelihara diri, bukan pezina dan bukan (pula) wanita yang mengambil laki-laki lain sebagai piaraannya; dan apabila mereka telah menjaga diri dengan kawin, kemudian mereka melakukan perbuatan yang keji (zina), maka atas mereka separo hukuman dari hukuman wanita-wanita merdeka yang bersuami. (Kebolehan mengawini budak) itu, adalah bagi orang-orang yang takut kepada kemasyakatan menjaga diri (dari perbuatan zina) di antara kamu, dan kesabaran itu lebih baik bagimu. Dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 26, 'Allah hendak menerangkan (hukum syari\'at-Nya) kepadamu, dan menunjukimu kepada jalan-jalan orang yang sebelum kamu (para nabi dan shalihin) dan (hendak) menerima taubatmu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 27, 'Dan Allah hendak menerima taubatmu, sedang orang-orang yang mengikuti hawa nafsunya bermaksud supaya kamu berpaling sejauh-jauhnya (dari kebenaran).'),
  ('id.indonesian', 4, 28, 'Allah hendak memberikan keringanan kepadamu, dan manusia dijadikan bersifat lemah.'),
  ('id.indonesian', 4, 29, 'Hai orang-orang yang beriman, janganlah kamu saling memakan harta sesamamu dengan jalan yang batil, kecuali dengan jalan perniagaan yang berlaku dengan suka sama-suka di antara kamu. Dan janganlah kamu membunuh dirimu; sesungguhnya Allah adalah Maha Penyayang kepadamu.'),
  ('id.indonesian', 4, 30, 'Dan barangsiapa berbuat demikian dengan melanggar hak dan aniaya, maka Kami kelak akan memasukkannya ke dalam neraka. Yang demikian itu adalah mudah bagi Allah.'),
  ('id.indonesian', 4, 31, 'Jika kamu menjauhi dosa-dosa besar di antara dosa-dosa yang dilarang kamu mengerjakannya, niscaya Kami hapus kesalahan-kesalahanmu (dosa-dosamu yang kecil) dan Kami masukkan kamu ke tempat yang mulia (surga).'),
  ('id.indonesian', 4, 32, 'Dan janganlah kamu iri hati terhadap apa yang dikaruniakan Allah kepada sebahagian kamu lebih banyak dari sebahagian yang lain. (Karena) bagi orang laki-laki ada bahagian dari pada apa yang mereka usahakan, dan bagi para wanita (pun) ada bahagian dari apa yang mereka usahakan, dan mohonlah kepada Allah sebagian dari karunia-Nya. Sesungguhnya Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 4, 33, 'Bagi tiap-tiap harta peninggalan dari harta yang ditinggalkan ibu bapak dan karib kerabat, Kami jadikan pewaris-pewarisnya. Dan (jika ada) orang-orang yang kamu telah bersumpah setia dengan mereka, maka berilah kepada mereka bahagiannya. Sesungguhnya Allah menyaksikan segala sesuatu.'),
  ('id.indonesian', 4, 34, 'Kaum laki-laki itu adalah pemimpin bagi kaum wanita, oleh karena Allah telah melebihkan sebahagian mereka (laki-laki) atas sebahagian yang lain (wanita), dan karena mereka (laki-laki) telah menafkahkan sebagian dari harta mereka. Sebab itu maka wanita yang saleh, ialah yang taat kepada Allah lagi memelihara diri ketika suaminya tidak ada, oleh karena Allah telah memelihara (mereka). Wanita-wanita yang kamu khawatirkan nusyuznya, maka nasehatilah mereka dan pisahkanlah mereka di tempat tidur mereka, dan pukullah mereka. Kemudian jika mereka mentaatimu, maka janganlah kamu mencari-cari jalan untuk menyusahkannya. Sesungguhnya Allah Maha Tinggi lagi Maha Besar.'),
  ('id.indonesian', 4, 35, 'Dan jika kamu khawatirkan ada persengketaan antara keduanya, maka kirimlah seorang hakam dari keluarga laki-laki dan seorang hakam dari keluarga perempuan. Jika kedua orang hakam itu bermaksud mengadakan perbaikan, niscaya Allah memberi taufik kepada suami-isteri itu. Sesungguhnya Allah Maha Mengetahui lagi Maha Mengenal.'),
  ('id.indonesian', 4, 36, 'Sembahlah Allah dan janganlah kamu mempersekutukan-Nya dengan sesuatupun. Dan berbuat baiklah kepada dua orang ibu-bapa, karib-kerabat, anak-anak yatim, orang-orang miskin, tetangga yang dekat dan tetangga yang jauh, dan teman sejawat, ibnu sabil dan hamba sahayamu. Sesungguhnya Allah tidak menyukai orang-orang yang sombong dan membangga-banggakan diri,'),
  ('id.indonesian', 4, 37, '(yaitu) orang-orang yang kikir, dan menyuruh orang lain berbuat kikir, dan menyembunyikan karunia Allah yang telah diberikan-Nya kepada mereka. Dan Kami telah menyediakan untuk orang-orang kafir siksa yang menghinakan.'),
  ('id.indonesian', 4, 38, 'Dan (juga) orang-orang yang menafkahkan harta-harta mereka karena riya kepada manusia, dan orang-orang yang tidak beriman kepada Allah dan kepada hari kemudian. Barangsiapa yang mengambil syaitan itu menjadi temannya, maka syaitan itu adalah teman yang seburuk-buruknya.'),
  ('id.indonesian', 4, 39, 'Apakah kemudharatannya bagi mereka, kalau mereka beriman kepada Allah dan hari kemudian dan menafkahkan sebahagian rezeki yang telah diberikan Allah kepada mereka? Dan adalah Allah Maha Mengetahui keadaan mereka.'),
  ('id.indonesian', 4, 40, 'Sesungguhnya Allah tidak menganiaya seseorang walaupun sebesar zarrah, dan jika ada kebajikan sebesar zarrah, niscaya Allah akan melipat gandakannya dan memberikan dari sisi-Nya pahala yang besar.'),
  ('id.indonesian', 4, 41, 'Maka bagaimanakah (halnya orang kafir nanti), apabila Kami mendatangkan seseorang saksi (rasul) dari tiap-tiap umat dan Kami mendatangkan kamu (Muhammad) sebagai saksi atas mereka itu (sebagai umatmu).'),
  ('id.indonesian', 4, 42, 'Di hari itu orang-orang kafir dan orang-orang yang mendurhakai rasul, ingin supaya mereka disamaratakan dengan tanah, dan mereka tidak dapat menyembunyikan (dari Allah) sesuatu kejadianpun.'),
  ('id.indonesian', 4, 43, 'Hai orang-orang yang beriman, janganlah kamu shalat, sedang kamu dalam keadaan mabuk, sehingga kamu mengerti apa yang kamu ucapkan, (jangan pula hampiri mesjid) sedang kamu dalam keadaan junub, terkecuali sekedar berlalu saja, hingga kamu mandi. Dan jika kamu sakit atau sedang dalam musafir atau datang dari tempat buang air atau kamu telah menyentuh perempuan, kemudian kamu tidak mendapat air, maka bertayamumlah kamu dengan tanah yang baik (suci); sapulah mukamu dan tanganmu. Sesungguhnya Allah Maha Pemaaf lagi Maha Pengampun.'),
  ('id.indonesian', 4, 44, 'Apakah kamu tidak melihat orang-orang yang telah diberi bahagian dari Al Kitab (Taurat)? Mereka membeli (memilih) kesesatan (dengan petunjuk) dan mereka bermaksud supaya kamu tersesat (menyimpang) dari jalan (yang benar).'),
  ('id.indonesian', 4, 45, 'Dan Allah lebih mengetahui (dari pada kamu) tentang musuh-musuhmu. Dan cukuplah Allah menjadi Pelindung (bagimu). Dan cukuplah Allah menjadi Penolong (bagimu).'),
  ('id.indonesian', 4, 46, 'Yaitu orang-orang Yahudi, mereka mengubah perkataan dari tempat-tempatnya. Mereka berkata: "Kami mendengar", tetapi kami tidak mau menurutinya. Dan (mereka mengatakan pula): "Dengarlah" sedang kamu sebenarnya tidak mendengar apa-apa. Dan (mereka mengatakan): "Raa\'ina", dengan memutar-mutar lidahnya dan mencela agama. Sekiranya mereka mengatakan: "Kami mendengar dan menurut, dan dengarlah, dan perhatikanlah kami", tentulah itu lebih baik bagi mereka dan lebih tepat, akan tetapi Allah mengutuk mereka, karena kekafiran mereka. Mereka tidak beriman kecuali iman yang sangat tipis.'),
  ('id.indonesian', 4, 47, 'Hai orang-orang yang telah diberi Al Kitab, berimanlah kamu kepada apa yang telah Kami turunkan (Al Quran) yang membenarkan Kitab yang ada pada kamu sebelum Kami mengubah muka(mu), lalu Kami putarkan ke belakang atau Kami kutuki mereka sebagaimana Kami telah mengutuki orang-orang (yang berbuat maksiat) pada hari Sabtu. Dan ketetapan Allah pasti berlaku.'),
  ('id.indonesian', 4, 48, 'Sesungguhnya Allah tidak akan mengampuni dosa syirik, dan Dia mengampuni segala dosa yang selain dari (syirik) itu, bagi siapa yang dikehendaki-Nya. Barangsiapa yang mempersekutukan Allah, maka sungguh ia telah berbuat dosa yang besar.'),
  ('id.indonesian', 4, 49, 'Apakah kamu tidak memperhatikan orang yang menganggap dirinya bersih?. Sebenarnya Allah membersihkan siapa yang dikehendaki-Nya dan mereka tidak aniaya sedikitpun.'),
  ('id.indonesian', 4, 50, 'Perhatikanlah, betapakah mereka mengada-adakan dusta terhadap Allah? Dan cukuplah perbuatan itu menjadi dosa yang nyata (bagi mereka).'),
  ('id.indonesian', 4, 51, 'Apakah kamu tidak memperhatikan orang-orang yang diberi bahagian dari Al kitab? Mereka percaya kepada jibt dan thaghut, dan mengatakan kepada orang-orang Kafir (musyrik Mekah), bahwa mereka itu lebih benar jalannya dari orang-orang yang beriman.'),
  ('id.indonesian', 4, 52, 'Mereka itulah orang yang dikutuki Allah. Barangsiapa yang dikutuki Allah, niscaya kamu sekali-kali tidak akan memperoleh penolong baginya.'),
  ('id.indonesian', 4, 53, 'Ataukah ada bagi mereka bahagian dari kerajaan (kekuasaan)? Kendatipun ada, mereka tidak akan memberikan sedikitpun (kebajikan) kepada manusia.'),
  ('id.indonesian', 4, 54, 'ataukah mereka dengki kepada manusia (Muhammad) lantaran karunia yang Allah telah berikan kepadanya? Sesungguhnya Kami telah memberikan Kitab dan Hikmah kepada keluarga Ibrahim, dan Kami telah memberikan kepadanya kerajaan yang besar.'),
  ('id.indonesian', 4, 55, 'Maka di antara mereka (orang-orang yang dengki itu), ada orang-orang yang beriman kepadanya, dan di antara mereka ada orang-orang yang menghalangi (manusia) dari beriman kepadanya. Dan cukuplah (bagi mereka) Jahannam yang menyala-nyala apinya.'),
  ('id.indonesian', 4, 56, 'Sesungguhnya orang-orang yang kafir kepada ayat-ayat Kami, kelak akan Kami masukkan mereka ke dalam neraka. Setiap kali kulit mereka hangus, Kami ganti kulit mereka dengan kulit yang lain, supaya mereka merasakan azab. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 57, 'Dan orang-orang yang beriman dan mengerjakan amalan-amalan yang shaleh, kelak akan Kami masukkan mereka ke dalam surga yang di dalamnya mengalir sungai-sungai; kekal mereka di dalamnya; mereka di dalamnya mempunyai isteri-isteri yang suci, dan Kami masukkan mereka ke tempat yang teduh lagi nyaman.'),
  ('id.indonesian', 4, 58, 'Sesungguhnya Allah menyuruh kamu menyampaikan amanat kepada yang berhak menerimanya, dan (menyuruh kamu) apabila menetapkan hukum di antara manusia supaya kamu menetapkan dengan adil. Sesungguhnya Allah memberi pengajaran yang sebaik-baiknya kepadamu. Sesungguhnya Allah adalah Maha Mendengar lagi Maha Melihat.'),
  ('id.indonesian', 4, 59, 'Hai orang-orang yang beriman, taatilah Allah dan taatilah Rasul (Nya), dan ulil amri di antara kamu. Kemudian jika kamu berlainan pendapat tentang sesuatu, maka kembalikanlah ia kepada Allah (Al Quran) dan Rasul (sunnahnya), jika kamu benar-benar beriman kepada Allah dan hari kemudian. Yang demikian itu lebih utama (bagimu) dan lebih baik akibatnya.'),
  ('id.indonesian', 4, 60, 'Apakah kamu tidak memperhatikan orang-orang yang mengaku dirinya telah beriman kepada apa yang diturunkan kepadamu dan kepada apa yang diturunkan sebelum kamu? Mereka hendak berhakim kepada thaghut, padahal mereka telah diperintah mengingkari thaghut itu. Dan syaitan bermaksud menyesatkan mereka (dengan) penyesatan yang sejauh-jauhnya.'),
  ('id.indonesian', 4, 61, 'Apabila dikatakan kepada mereka: "Marilah kamu (tunduk) kepada hukum yang Allah telah turunkan dan kepada hukum Rasul", niscaya kamu lihat orang-orang munafik menghalangi (manusia) dengan sekuat-kuatnya dari (mendekati) kamu.'),
  ('id.indonesian', 4, 62, 'Maka bagaimanakah halnya apabila mereka (orang-orang munafik) ditimpa sesuatu musibah disebabkan perbuatan tangan mereka sendiri, kemudian mereka datang kepadamu sambil bersumpah: "Demi Allah, kami sekali-kali tidak menghendaki selain penyelesaian yang baik dan perdamaian yang sempurna".'),
  ('id.indonesian', 4, 63, 'Mereka itu adalah orang-orang yang Allah mengetahui apa yang di dalam hati mereka. Karena itu berpalinglah kamu dari mereka, dan berilah mereka pelajaran, dan katakanlah kepada mereka perkataan yang berbekas pada jiwa mereka.'),
  ('id.indonesian', 4, 64, 'Dan Kami tidak mengutus seseorang rasul melainkan untuk ditaati dengan seizin Allah. Sesungguhnya jikalau mereka ketika menganiaya dirinya datang kepadamu, lalu memohon ampun kepada Allah, dan Rasulpun memohonkan ampun untuk mereka, tentulah mereka mendapati Allah Maha Penerima Taubat lagi Maha Penyayang.'),
  ('id.indonesian', 4, 65, 'Maka demi Tuhanmu, mereka (pada hakekatnya) tidak beriman hingga mereka menjadikan kamu hakim terhadap perkara yang mereka perselisihkan, kemudian mereka tidak merasa dalam hati mereka sesuatu keberatan terhadap putusan yang kamu berikan, dan mereka menerima dengan sepenuhnya.'),
  ('id.indonesian', 4, 66, 'Dan sesungguhnya kalau Kami perintahkan kepada mereka: "Bunuhlah dirimu atau keluarlah kamu dari kampungmu", niscaya mereka tidak akan melakukannya kecuali sebagian kecil dari mereka. Dan sesungguhnya kalau mereka melaksanakan pelajaran yang diberikan kepada mereka, tentulah hal yang demikian itu lebih baik bagi mereka dan lebih menguatkan (iman mereka),'),
  ('id.indonesian', 4, 67, 'dan kalau demikian, pasti Kami berikan kepada mereka pahala yang besar dari sisi Kami,'),
  ('id.indonesian', 4, 68, 'dan pasti Kami tunjuki mereka kepada jalan yang lurus.'),
  ('id.indonesian', 4, 69, 'Dan barangsiapa yang mentaati Allah dan Rasul(Nya), mereka itu akan bersama-sama dengan orang-orang yang dianugerahi nikmat oleh Allah, yaitu: Nabi-nabi, para shiddiiqiin, orang-orang yang mati syahid, dan orang-orang saleh. Dan mereka itulah teman yang sebaik-baiknya.'),
  ('id.indonesian', 4, 70, 'Yang demikian itu adalah karunia dari Allah, dan Allah cukup mengetahui.'),
  ('id.indonesian', 4, 71, 'Hai orang-orang yang beriman, bersiap siagalah kamu, dan majulah (ke medan pertempuran) berkelompok-kelompok, atau majulah bersama-sama!'),
  ('id.indonesian', 4, 72, 'Dan sesungguhnya di antara kamu ada orang yang sangat berlambat-lambat (ke medan pertempuran). Maka jika kamu ditimpa musibah ia berkata: "Sesungguhnya Tuhan telah menganugerahkan nikmat kepada saya karena saya tidak ikut berperang bersama mereka.'),
  ('id.indonesian', 4, 73, 'Dan sungguh jika kamu beroleh karunia (kemenangan) dari Allah, tentulah dia mengatakan seolah-oleh belum pernah ada hubungan kasih sayang antara kamu dengan dia: "Wahai kiranya saya ada bersama-sama mereka, tentu saya mendapat kemenangan yang besar (pula)".'),
  ('id.indonesian', 4, 74, 'Karena itu hendaklah orang-orang yang menukar kehidupan dunia dengan kehidupan akhirat berperang di jalan Allah. Barangsiapa yang berperang di jalan Allah, lalu gugur atau memperoleh kemenangan maka kelak akan Kami berikan kepadanya pahala yang besar.'),
  ('id.indonesian', 4, 75, 'Mengapa kamu tidak mau berperang di jalan Allah dan (membela) orang-orang yang lemah baik laki-laki, wanita-wanita maupun anak-anak yang semuanya berdoa: "Ya Tuhan kami, keluarkanlah kami dari negeri ini (Mekah) yang zalim penduduknya dan berilah kami pelindung dari sisi Engkau, dan berilah kami penolong dari sisi Engkau!".'),
  ('id.indonesian', 4, 76, 'Orang-orang yang beriman berperang di jalan Allah, dan orang-orang yang kafir berperang di jalan thaghut, sebab itu perangilah kawan-kawan syaitan itu, karena sesungguhnya tipu daya syaitan itu adalah lemah.'),
  ('id.indonesian', 4, 77, 'Tidakkah kamu perhatikan orang-orang yang dikatakan kepada mereka: "Tahanlah tanganmu (dari berperang), dirikanlah sembahyang dan tunaikanlah zakat!" Setelah diwajibkan kepada mereka berperang, tiba-tiba sebahagian dari mereka (golongan munafik) takut kepada manusia (musuh), seperti takutnya kepada Allah, bahkan lebih sangat dari itu takutnya. Mereka berkata: "Ya Tuhan kami, mengapa Engkau wajibkan berperang kepada kami? Mengapa tidak Engkau tangguhkan (kewajiban berperang) kepada kami sampai kepada beberapa waktu lagi?" Katakanlah: "Kesenangan di dunia ini hanya sebentar dan akhirat itu lebih baik untuk orang-orang yang bertakwa, dan kamu tidak akan dianiaya sedikitpun.'),
  ('id.indonesian', 4, 78, 'Di mana saja kamu berada, kematian akan mendapatkan kamu, kendatipun kamu di dalam benteng yang tinggi lagi kokoh, dan jika mereka memperoleh kebaikan, mereka mengatakan: "Ini adalah dari sisi Allah", dan kalau mereka ditimpa sesuatu bencana mereka mengatakan: "Ini (datangnya) dari sisi kamu (Muhammad)". Katakanlah: "Semuanya (datang) dari sisi Allah". Maka mengapa orang-orang itu (orang munafik) hampir-hampir tidak memahami pembicaraan sedikitpun?'),
  ('id.indonesian', 4, 79, 'Apa saja nikmat yang kamu peroleh adalah dari Allah, dan apa saja bencana yang menimpamu, maka dari (kesalahan) dirimu sendiri. Kami mengutusmu menjadi Rasul kepada segenap manusia. Dan cukuplah Allah menjadi saksi.'),
  ('id.indonesian', 4, 80, 'Barangsiapa yang mentaati Rasul itu, sesungguhnya ia telah mentaati Allah. Dan barangsiapa yang berpaling (dari ketaatan itu), maka Kami tidak mengutusmu untuk menjadi pemelihara bagi mereka.'),
  ('id.indonesian', 4, 81, 'Dan mereka (orang-orang munafik) mengatakan: "(Kewajiban kami hanyalah) taat". Tetapi apabila mereka telah pergi dari sisimu, sebahagian dari mereka mengatur siasat di malam hari (mengambil keputusan) lain dari yang telah mereka katakan tadi. Allah menulis siasat yang mereka atur di malam hari itu, maka berpalinglah kamu dari mereka dan tawakallah kepada Allah. Cukuplah Allah menjadi Pelindung.'),
  ('id.indonesian', 4, 82, 'Maka apakah mereka tidak memperhatikan Al Quran? Kalau kiranya Al Quran itu bukan dari sisi Allah, tentulah mereka mendapat pertentangan yang banyak di dalamnya.'),
  ('id.indonesian', 4, 83, 'Dan apabila datang kepada mereka suatu berita tentang keamanan ataupun ketakutan, mereka lalu menyiarkannya. Dan kalau mereka menyerahkannya kepada Rasul dan Ulil Amri di antara mereka, tentulah orang-orang yang ingin mengetahui kebenarannya (akan dapat) mengetahuinya dari mereka (Rasul dan Ulil Amri). Kalau tidaklah karena karunia dan rahmat Allah kepada kamu, tentulah kamu mengikut syaitan, kecuali sebahagian kecil saja (di antaramu).'),
  ('id.indonesian', 4, 84, 'Maka berperanglah kamu pada jalan Allah, tidaklah kamu dibebani melainkan dengan kewajiban kamu sendiri. Kobarkanlah semangat para mukmin (untuk berperang). Mudah-mudahan Allah menolak serangan orang-orang yang kafir itu. Allah amat besar kekuatan dan amat keras siksaan(Nya).'),
  ('id.indonesian', 4, 85, 'Barangsiapa yang memberikan syafa\'at yang baik, niscaya ia akan memperoleh bahagian (pahala) dari padanya. Dan barangsiapa memberi syafa\'at yang buruk, niscaya ia akan memikul bahagian (dosa) dari padanya. Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 4, 86, 'Apabila kamu diberi penghormatan dengan sesuatu penghormatan, maka balaslah penghormatan itu dengan yang lebih baik dari padanya, atau balaslah penghormatan itu (dengan yang serupa). Sesungguhnya Allah memperhitungankan segala sesuatu.'),
  ('id.indonesian', 4, 87, 'Allah, tidak ada Tuhan (yang berhak disembah) selain Dia. Sesungguhnya Dia akan mengumpulkan kamu di hari kiamat, yang tidak ada keraguan terjadinya. Dan siapakah orang yang lebih benar perkataan(nya) dari pada Allah?'),
  ('id.indonesian', 4, 88, 'Maka mengapa kamu (terpecah) menjadi dua golongan dalam (menghadapi) orang-orang munafik, padahal Allah telah membalikkan mereka kepada kekafiran, disebabkan usaha mereka sendiri? Apakah kamu bermaksud memberi petunjuk kepada orang-orang yang telah disesatkan Allah? Barangsiapa yang disesatkan Allah, sekali-kali kamu tidak mendapatkan jalan (untuk memberi petunjuk) kepadanya.'),
  ('id.indonesian', 4, 89, 'Mereka ingin supaya kamu menjadi kafir sebagaimana mereka telah menjadi kafir, lalu kamu menjadi sama (dengan mereka). Maka janganlah kamu jadikan di antara mereka penolong-penolong(mu), hingga mereka berhijrah pada jalan Allah. Maka jika mereka berpaling, tawan dan bunuhlah mereka di mana saja kamu menemuinya, dan janganlah kamu ambil seorangpun di antara mereka menjadi pelindung, dan jangan (pula) menjadi penolong,'),
  ('id.indonesian', 4, 90, 'kecuali orang-orang yang meminta perlindungan kepada sesuatu kaum, yang antara kamu dan kaum itu telah ada perjanjian (damai) atau orang-orang yang datang kepada kamu sedang hati mereka merasa keberatan untuk memerangi kamu dan memerangi kaumnya. Kalau Allah menghendaki, tentu Dia memberi kekuasaan kepada mereka terhadap kamu, lalu pastilah mereka memerangimu. tetapi jika mereka membiarkan kamu, dan tidak memerangi kamu serta mengemukakan perdamaian kepadamu maka Allah tidak memberi jalan bagimu (untuk menawan dan membunuh) mereka.'),
  ('id.indonesian', 4, 91, 'Kelak kamu akan dapati (golongan-golongan) yang lain, yang bermaksud supaya mereka aman dari pada kamu dan aman (pula) dari kaumnya. Setiap mereka diajak kembali kepada fitnah (syirik), merekapun terjun kedalamnya. Karena itu jika mereka tidak membiarkan kamu dan (tidak) mau mengemukakan perdamaian kepadamu, serta (tidak) menahan tangan mereka (dari memerangimu), maka tawanlah mereka dan bunuhlah mereka dan merekalah orang-orang yang Kami berikan kepadamu alasan yang nyata (untuk menawan dan membunuh) mereka.'),
  ('id.indonesian', 4, 92, 'Dan tidak layak bagi seorang mukmin membunuh seorang mukmin (yang lain), kecuali karena tersalah (tidak sengaja), dan barangsiapa membunuh seorang mukmin karena tersalah (hendaklah) ia memerdekakan seorang hamba sahaya yang beriman serta membayar diat yang diserahkan kepada keluarganya (si terbunuh itu), kecuali jika mereka (keluarga terbunuh) bersedekah. Jika ia (si terbunuh) dari kaum (kafir) yang ada perjanjian (damai) antara mereka dengan kamu, maka (hendaklah si pembunuh) membayar diat yang diserahkan kepada keluarganya (si terbunuh) serta memerdekakan hamba sahaya yang beriman. Barangsiapa yang tidak memperolehnya, maka hendaklah ia (si pembunuh) berpuasa dua bulan berturut-turut untuk penerimaan taubat dari pada Allah. Dan adalah Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 93, 'Dan barangsiapa yang membunuh seorang mukmin dengan sengaja maka balasannya ialah Jahannam, kekal ia di dalamnya dan Allah murka kepadanya, dan mengutukinya serta menyediakan azab yang besar baginya.'),
  ('id.indonesian', 4, 94, 'Hai orang-orang yang beriman, apabila kamu pergi (berperang) di jalan Allah, maka telitilah dan janganlah kamu mengatakan kepada orang yang mengucapkan "salam" kepadamu: "Kamu bukan seorang mukmin" (lalu kamu membunuhnya), dengan maksud mencari harta benda kehidupan di dunia, karena di sisi Allah ada harta yang banyak. Begitu jugalah keadaan kamu dahulu, lalu Allah menganugerahkan nikmat-Nya atas kamu, maka telitilah. Sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 4, 95, 'Tidaklah sama antara mukmin yang duduk (yang tidak ikut berperang) yang tidak mempunyai \'uzur dengan orang-orang yang berjihad di jalan Allah dengan harta mereka dan jiwanya. Allah melebihkan orang-orang yang berjihad dengan harta dan jiwanya atas orang-orang yang duduk satu derajat. Kepada masing-masing mereka Allah menjanjikan pahala yang baik (surga) dan Allah melebihkan orang-orang yang berjihad atas orang yang duduk dengan pahala yang besar,'),
  ('id.indonesian', 4, 96, '(yaitu) beberapa derajat dari pada-Nya, ampunan serta rahmat. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 97, 'Sesungguhnya orang-orang yang diwafatkan malaikat dalam keadaan menganiaya diri sendiri, (kepada mereka) malaikat bertanya: "Dalam keadaan bagaimana kamu ini?". Mereka menjawab: "Adalah kami orang-orang yang tertindas di negeri (Mekah)". Para malaikat berkata: "Bukankah bumi Allah itu luas, sehingga kamu dapat berhijrah di bumi itu?". Orang-orang itu tempatnya neraka Jahannam, dan Jahannam itu seburuk-buruk tempat kembali,'),
  ('id.indonesian', 4, 98, 'kecuali mereka yang tertindas baik laki-laki atau wanita ataupun anak-anak yang tidak mampu berdaya upaya dan tidak mengetahui jalan (untuk hijrah),'),
  ('id.indonesian', 4, 99, 'mereka itu, mudah-mudahan Allah memaafkannya. Dan adalah Allah Maha Pemaaf lagi Maha Pengampun.'),
  ('id.indonesian', 4, 100, 'Barangsiapa berhijrah di jalan Allah, niscaya mereka mendapati di muka bumi ini tempat hijrah yang luas dan rezeki yang banyak. Barangsiapa keluar dari rumahnya dengan maksud berhijrah kepada Allah dan Rasul-Nya, kemudian kematian menimpanya (sebelum sampai ke tempat yang dituju), maka sungguh telah tetap pahalanya di sisi Allah. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 101, 'Dan apabila kamu bepergian di muka bumi, maka tidaklah mengapa kamu men-qashar sembahyang(mu), jika kamu takut diserang orang-orang kafir. Sesungguhnya orang-orang kafir itu adalah musuh yang nyata bagimu.'),
  ('id.indonesian', 4, 102, 'Dan apabila kamu berada di tengah-tengah mereka (sahabatmu) lalu kamu hendak mendirikan shalat bersama-sama mereka, maka hendaklah segolongan dari mereka berdiri (shalat) besertamu dan menyandang senjata, kemudian apabila mereka (yang shalat besertamu) sujud (telah menyempurnakan serakaat), maka hendaklah mereka pindah dari belakangmu (untuk menghadapi musuh) dan hendaklah datang golongan yang kedua yang belum bersembahyang, lalu bersembahyanglah mereka denganmu], dan hendaklah mereka bersiap siaga dan menyandang senjata. Orang-orang kafir ingin supaya kamu lengah terhadap senjatamu dan harta bendamu, lalu mereka menyerbu kamu dengan sekaligus. Dan tidak ada dosa atasmu meletakkan senjata-senjatamu, jika kamu mendapat sesuatu kesusahan karena hujan atau karena kamu memang sakit; dan siap siagalah kamu. Sesungguhnya Allah telah menyediakan azab yang menghinakan bagi orang-orang kafir itu.'),
  ('id.indonesian', 4, 103, 'Maka apabila kamu telah menyelesaikan shalat(mu), ingatlah Allah di waktu berdiri, di waktu duduk dan di waktu berbaring. Kemudian apabila kamu telah merasa aman, maka dirikanlah shalat itu (sebagaimana biasa). Sesungguhnya shalat itu adalah fardhu yang ditentukan waktunya atas orang-orang yang beriman.'),
  ('id.indonesian', 4, 104, 'Janganlah kamu berhati lemah dalam mengejar mereka (musuhmu). Jika kamu menderita kesakitan, maka sesungguhnya merekapun menderita kesakitan (pula), sebagaimana kamu menderitanya, sedang kamu mengharap dari pada Allah apa yang tidak mereka harapkan. Dan adalah Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 105, 'Sesungguhnya Kami telah menurunkan kitab kepadamu dengan membawa kebenaran, supaya kamu mengadili antara manusia dengan apa yang telah Allah wahyukan kepadamu, dan janganlah kamu menjadi penantang (orang yang tidak bersalah), karena (membela) orang-orang yang khianat,'),
  ('id.indonesian', 4, 106, 'dan mohonlah ampun kepada Allah. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 107, 'Dan janganlah kamu berdebat (untuk membela) orang-orang yang mengkhianati dirinya. Sesungguhnya Allah tidak menyukai orang-orang yang selalu berkhianat lagi bergelimang dosa,'),
  ('id.indonesian', 4, 108, 'mereka bersembunyi dari manusia, tetapi mereka tidak bersembunyi dari Allah, padahal Allah beserta mereka, ketika pada suatu malam mereka menetapkan keputusan rahasia yang Allah tidak redlai. Dan adalah Allah Maha Meliputi (ilmu-Nya) terhadap apa yang mereka kerjakan.'),
  ('id.indonesian', 4, 109, 'Beginilah kamu, kamu sekalian adalah orang-orang yang berdebat untuk (membela) mereka dalam kehidupan dunia ini. Maka siapakah yang akan mendebat Allah untuk (membela) mereka pada hari kiamat? Atau siapakah yang menjadi pelindung mereka (terhadap siksa Allah)?'),
  ('id.indonesian', 4, 110, 'Dan barangsiapa yang mengerjakan kejahatan dan menganiaya dirinya, kemudian ia mohon ampun kepada Allah, niscaya ia mendapati Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 111, 'Barangsiapa yang mengerjakan dosa, maka sesungguhnya ia mengerjakannya untuk (kemudharatan) dirinya sendiri. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 112, 'Dan barangsiapa yang mengerjakan kesalahan atau dosa, kemudian dituduhkannya kepada orang yang tidak bersalah, maka sesungguhnya ia telah berbuat suatu kebohongan dan dosa yang nyata.'),
  ('id.indonesian', 4, 113, 'Sekiranya bukan karena karunia Allah dan rahmat-Nya kepadamu, tentulah segolongan dari mereka berkeinginan keras untuk menyesatkanmu. Tetapi mereka tidak menyesatkan melainkan dirinya sendiri, dan mereka tidak dapat membahayakanmu sedikitpun kepadamu. Dan (juga karena) Allah telah menurunkan Kitab dan hikmah kepadamu, dan telah mengajarkan kepadamu apa yang belum kamu ketahui. Dan adalah karunia Allah sangat besar atasmu.'),
  ('id.indonesian', 4, 114, 'Tidak ada kebaikan pada kebanyakan bisikan-bisikan mereka, kecuali bisikan-bisikan dari orang yang menyuruh (manusia) memberi sedekah, atau berbuat ma\'ruf, atau mengadakan perdamaian di antara manusia. Dan barangsiapa yang berbuat demikian karena mencari keridhaan Allah, maka kelak Kami memberi kepadanya pahala yang besar.'),
  ('id.indonesian', 4, 115, 'Dan barangsiapa yang menentang Rasul sesudah jelas kebenaran baginya, dan mengikuti jalan yang bukan jalan orang-orang mukmin, Kami biarkan ia leluasa terhadap kesesatan yang telah dikuasainya itu dan Kami masukkan ia ke dalam Jahannam, dan Jahannam itu seburuk-buruk tempat kembali.'),
  ('id.indonesian', 4, 116, 'Sesungguhnya Allah tidak mengampuni dosa mempersekutukan (sesuatu) dengan Dia, dan dia mengampuni dosa yang selain syirik bagi siapa yang dikehendaki-Nya. Barangsiapa yang mempersekutukan (sesuatu) dengan Allah, maka sesungguhnya ia telah tersesat sejauh-jauhnya.'),
  ('id.indonesian', 4, 117, 'Yang mereka sembah selain Allah itu, tidak lain hanyalah berhala, dan (dengan menyembah berhala itu) mereka tidak lain hanyalah menyembah syaitan yang durhaka,'),
  ('id.indonesian', 4, 118, 'yang dilaknati Allah dan syaitan itu mengatakan: "Saya benar-benar akan mengambil dari hamba-hamba Engkau bahagian yang sudah ditentukan (untuk saya),'),
  ('id.indonesian', 4, 119, 'dan aku benar-benar akan menyesatkan mereka, dan akan membangkitkan angan-angan kosong pada mereka dan menyuruh mereka (memotong telinga-telinga binatang ternak), lalu mereka benar-benar memotongnya, dan akan aku suruh mereka (mengubah ciptaan Allah), lalu benar-benar mereka meubahnya". Barangsiapa yang menjadikan syaitan menjadi pelindung selain Allah, maka sesungguhnya ia menderita kerugian yang nyata.'),
  ('id.indonesian', 4, 120, 'Syaitan itu memberikan janji-janji kepada mereka dan membangkitkan angan-angan kosong pada mereka, padahal syaitan itu tidak menjanjikan kepada mereka selain dari tipuan belaka.'),
  ('id.indonesian', 4, 121, 'Mereka itu tempatnya Jahannam dan mereka tidak memperoleh tempat lari dari padanya.'),
  ('id.indonesian', 4, 122, 'Orang-orang yang beriman dan mengerjakan amalan saleh, kelak akan Kami masukkan ke dalam surga yang mengalir sungai-sungai di dalamnya, mereka kekal di dalamnya selama-lamanya. Allah telah membuat suatu janji yang benar. Dan siapakah yang lebih benar perkataannya dari pada Allah?'),
  ('id.indonesian', 4, 123, '(Pahala dari Allah) itu bukanlah menurut angan-anganmu yang kosong dan tidak (pula) menurut angan-angan Ahli Kitab. Barangsiapa yang mengerjakan kejahatan, niscaya akan diberi pembalasan dengan kejahatan itu dan ia tidak mendapat pelindung dan tidak (pula) penolong baginya selain dari Allah.'),
  ('id.indonesian', 4, 124, 'Barangsiapa yang mengerjakan amal-amal saleh, baik laki-laki maupun wanita sedang ia orang yang beriman, maka mereka itu masuk ke dalam surga dan mereka tidak dianiaya walau sedikitpun.'),
  ('id.indonesian', 4, 125, 'Dan siapakah yang lebih baik agamanya dari pada orang yang ikhlas menyerahkan dirinya kepada Allah, sedang diapun mengerjakan kebaikan, dan ia mengikuti agama Ibrahim yang lurus? Dan Allah mengambil Ibrahim menjadi kesayangan-Nya.'),
  ('id.indonesian', 4, 126, 'Kepunyaan Allah-lah apa yang di langit dan apa yang di bumi, dan adalah (pengetahuan) Allah Maha Meliputi segala sesuatu.'),
  ('id.indonesian', 4, 127, 'Dan mereka minta fatwa kepadamu tentang para wanita. Katakanlah: "Allah memberi fatwa kepadamu tentang mereka, dan apa yang dibacakan kepadamu dalam Al Quran (juga memfatwakan) tentang para wanita yatim yang kamu tidak memberikan kepada mereka apa yang ditetapkan untuk mereka, sedang kamu ingin mengawini mereka dan tentang anak-anak yang masih dipandang lemah. Dan (Allah menyuruh kamu) supaya kamu mengurus anak-anak yatim secara adil. Dan kebajikan apa saja yang kamu kerjakan, maka sesungguhnya Allah adalah Maha Mengetahuinya.'),
  ('id.indonesian', 4, 128, 'Dan jika seorang wanita khawatir akan nusyuz atau sikap tidak acuh dari suaminya, maka tidak mengapa bagi keduanya mengadakan perdamaian yang sebenar-benarnya, dan perdamaian itu lebih baik (bagi mereka) walaupun manusia itu menurut tabiatnya kikir. Dan jika kamu bergaul dengan isterimu secara baik dan memelihara dirimu (dari nusyuz dan sikap tak acuh), maka sesungguhnya Allah adalah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 4, 129, 'Dan kamu sekali-kali tidak akan dapat berlaku adil di antara isteri-isteri(mu), walaupun kamu sangat ingin berbuat demikian, karena itu janganlah kamu terlalu cenderung (kepada yang kamu cintai), sehingga kamu biarkan yang lain terkatung-katung. Dan jika kamu mengadakan perbaikan dan memelihara diri (dari kecurangan), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 130, 'Jika keduanya bercerai, maka Allah akan memberi kecukupan kepada masing-masingnya dari limpahan karunia-Nya. Dan adalah Allah Maha Luas (karunia-Nya) lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 131, 'Dan kepunyaan Allah-lah apa yang di langit dan yang di bumi, dan sungguh Kami telah memerintahkan kepada orang-orang yang diberi kitab sebelum kamu dan (juga) kepada kamu; bertakwalah kepada Allah. Tetapi jika kamu kafir maka (ketahuilah), sesungguhnya apa yang di langit dan apa yang di bumi hanyalah kepunyaan Allah dan Allah Maha Kaya dan Maha Terpuji.'),
  ('id.indonesian', 4, 132, 'Dan kepunyaan Allah-lah apa yang di langit dan apa yang di bumi. Cukuplah Allah sebagai Pemelihara.'),
  ('id.indonesian', 4, 133, 'Jika Allah menghendaki, niscaya Dia musnahkan kamu wahai manusia, dan Dia datangkan umat yang lain (sebagai penggantimu). Dan adalah Allah Maha Kuasa berbuat demikian.'),
  ('id.indonesian', 4, 134, 'Barangsiapa yang menghendaki pahala di dunia saja (maka ia merugi), karena di sisi Allah ada pahala dunia dan akhirat. Dan Allah Maha Mendengar lagi Maha Melihat.'),
  ('id.indonesian', 4, 135, 'Wahai orang-orang yang beriman, jadilah kamu orang yang benar-benar penegak keadilan, menjadi saksi karena Allah biarpun terhadap dirimu sendiri atau ibu bapa dan kaum kerabatmu. Jika ia kaya ataupun miskin, maka Allah lebih tahu kemaslahatannya. Maka janganlah kamu mengikuti hawa nafsu karena ingin menyimpang dari kebenaran. Dan jika kamu memutar balikkan (kata-kata) atau enggan menjadi saksi, maka sesungguhnya Allah adalah Maha Mengetahui segala apa yang kamu kerjakan.'),
  ('id.indonesian', 4, 136, 'Wahai orang-orang yang beriman, tetaplah beriman kepada Allah dan Rasul-Nya dan kepada kitab yang Allah turunkan kepada Rasul-Nya serta kitab yang Allah turunkan sebelumnya. Barangsiapa yang kafir kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, dan hari kemudian, maka sesungguhnya orang itu telah sesat sejauh-jauhnya.'),
  ('id.indonesian', 4, 137, 'Sesungguhnya orang-orang yang beriman kemudian kafir, kemudian beriman (pula), kamudian kafir lagi, kemudian bertambah kekafirannya, maka sekali-kali Allah tidak akan memberi ampunan kepada mereka, dan tidak (pula) menunjuki mereka kepada jalan yang lurus.'),
  ('id.indonesian', 4, 138, 'Kabarkanlah kepada orang-orang munafik bahwa mereka akan mendapat siksaan yang pedih,'),
  ('id.indonesian', 4, 139, '(yaitu) orang-orang yang mengambil orang-orang kafir menjadi teman-teman penolong dengan meninggalkan orang-orang mukmin. Apakah mereka mencari kekuatan di sisi orang kafir itu? Maka sesungguhnya semua kekuatan kepunyaan Allah.'),
  ('id.indonesian', 4, 140, 'Dan sungguh Allah telah menurunkan kekuatan kepada kamu di dalam Al Quran bahwa apabila kamu mendengar ayat-ayat Allah diingkari dan diperolok-olokkan (oleh orang-orang kafir), maka janganlah kamu duduk beserta mereka, sehingga mereka memasuki pembicaraan yang lain. Karena sesungguhnya (kalau kamu berbuat demikian), tentulah kamu serupa dengan mereka. Sesungguhnya Allah akan mengumpulkan semua orang-orang munafik dan orang-orang kafir di dalam Jahannam,'),
  ('id.indonesian', 4, 141, '(yaitu) orang-orang yang menunggu-nunggu (peristiwa) yang akan terjadi pada dirimu (hai orang-orang mukmin). Maka jika terjadi bagimu kemenangan dari Allah mereka berkata: "Bukankah kami (turut berperang) beserta kamu?" Dan jika orang-orang kafir mendapat keberuntungan (kemenangan) mereka berkata: "Bukankah kami turut memenangkanmu, dan membela kamu dari orang-orang mukmin?" Maka Allah akan memberi keputusan di antara kamu di hari kiamat dan Allah sekali-kali tidak akan memberi jalan kepada orang-orang kafir untuk memusnahkan orang-orang yang beriman.'),
  ('id.indonesian', 4, 142, 'Sesungguhnya orang-orang munafik itu menipu Allah, dan Allah akan membalas tipuan mereka. Dan apabila mereka berdiri untuk shalat mereka berdiri dengan malas. Mereka bermaksud riya (dengan shalat) di hadapan manusia. Dan tidaklah mereka menyebut Allah kecuali sedikit sekali.'),
  ('id.indonesian', 4, 143, 'Mereka dalam keadaan ragu-ragu antara yang demikian (iman atau kafir): tidak masuk kepada golongan ini (orang-orang beriman) dan tidak (pula) kepada golongan itu (orang-orang kafir), maka kamu sekali-kali tidak akan mendapat jalan (untuk memberi petunjuk) baginya.'),
  ('id.indonesian', 4, 144, 'Hai orang-orang yang beriman, janganlah kamu mengambil orang-orang kafir menjadi wali dengan meninggalkan orang-orang mukmin. Inginkah kamu mengadakan alasan yang nyata bagi Allah (untuk menyiksamu)?'),
  ('id.indonesian', 4, 145, 'Sesungguhnya orang-orang munafik itu (ditempatkan) pada tingkatan yang paling bawah dari neraka. Dan kamu sekali-kali tidak akan mendapat seorang penolongpun bagi mereka.'),
  ('id.indonesian', 4, 146, 'Kecuali orang-orang yang taubat dan mengadakan perbaikan dan berpegang teguh pada (agama) Allah dan tulus ikhlas (mengerjakan) agama mereka karena Allah. Maka mereka itu adalah bersama-sama orang yang beriman dan kelak Allah akan memberikan kepada orang-orang yang beriman pahala yang besar.'),
  ('id.indonesian', 4, 147, 'Mengapa Allah akan menyiksamu, jika kamu bersyukur dan beriman? Dan Allah adalah Maha Mensyukuri lagi Maha Mengetahui.'),
  ('id.indonesian', 4, 148, 'Allah tidak menyukai ucapan buruk, (yang diucapkan) dengan terus terang kecuali oleh orang yang dianiaya. Allah adalah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 4, 149, 'Jika kamu melahirkan sesuatu kebaikan atau menyembunyikan atau memaafkan sesuatu kesalahan (orang lain), maka sesungguhnya Allah Maha Pemaaf lagi Maha Kuasa.'),
  ('id.indonesian', 4, 150, 'Sesungguhnya orang-orang yang kafir kepada Allah dan rasul-rasul-Nya, dan bermaksud memperbedakan antara (keimanan kepada) Allah dan rasul-rasul-Nya, dengan mengatakan: "Kami beriman kepada yang sebahagian dan kami kafir terhadap sebahagian (yang lain)", serta bermaksud (dengan perkataan itu) mengambil jalan (tengah) di antara yang demikian (iman atau kafir),'),
  ('id.indonesian', 4, 151, 'merekalah orang-orang yang kafir sebenar-benarnya. Kami telah menyediakan untuk orang-orang yang kafir itu siksaan yang menghinakan.'),
  ('id.indonesian', 4, 152, 'Orang-orang yang beriman kepada Allah dan para rasul-Nya dan tidak membeda-bedakan seorangpun di antara mereka, kelak Allah akan memberikan kepada mereka pahalanya. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 4, 153, 'Ahli Kitab meminta kepadamu agar kamu menurunkan kepada mereka sebuah Kitab dari langit. Maka sesungguhnya mereka telah meminta kepada Musa yang lebih besar dari itu. Mereka berkata: "Perlihatkanlah Allah kepada kami dengan nyata". Maka mereka disambar petir karena kezalimannya, dan mereka menyembah anak sapi, sesudah datang kepada mereka bukti-bukti yang nyata, lalu Kami maafkan (mereka) dari yang demikian. Dan telah Kami berikan kepada Musa keterangan yang nyata.'),
  ('id.indonesian', 4, 154, 'Dan telah Kami angkat ke atas (kepala) mereka bukit Thursina untuk (menerima) perjanjian (yang telah Kami ambil dari) mereka. Dan kami perintahkan kepada mereka: "Masuklah pintu gerbang itu sambil bersujud", dan Kami perintahkan (pula) kepada mereka: "Janganlah kamu melanggar peraturan mengenai hari Sabtu", dan Kami telah mengambil dari mereka perjanjian yang kokoh.'),
  ('id.indonesian', 4, 155, 'Maka (Kami lakukan terhadap mereka beberapa tindakan), disebabkan mereka melanggar perjanjian itu, dan karena kekafiran mereka terhadap keterangan-keterangan Allah dan mereka membunuh nabi-nabi tanpa (alasan) yang benar dan mengatakan: "Hati kami tertutup". Bahkan, sebenarnya Allah telah mengunci mati hati mereka karena kekafirannya, karena itu mereka tidak beriman kecuali sebahagian kecil dari mereka.'),
  ('id.indonesian', 4, 156, 'Dan karena kekafiran mereka (terhadap Isa) dan tuduhan mereka terhadap Maryam dengan kedustaan besar (zina),'),
  ('id.indonesian', 4, 157, 'dan karena ucapan mereka: "Sesungguhnya kami telah membunuh Al Masih, Isa putra Maryam, Rasul Allah", padahal mereka tidak membunuhnya dan tidak (pula) menyalibnya, tetapi (yang mereka bunuh ialah) orang yang diserupakan dengan Isa bagi mereka. Sesungguhnya orang-orang yang berselisih paham tentang (pembunuhan) Isa, benar-benar dalam keragu-raguan tentang yang dibunuh itu. Mereka tidak mempunyai keyakinan tentang siapa yang dibunuh itu, kecuali mengikuti persangkaan belaka, mereka tidak (pula) yakin bahwa yang mereka bunuh itu adalah Isa.'),
  ('id.indonesian', 4, 158, 'Tetapi (yang sebenarnya), Allah telah mengangkat Isa kepada-Nya. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 159, 'Tidak ada seorangpun dari Ahli Kitab, kecuali akan beriman kepadanya (Isa) sebelum kematiannya. Dan di hari kiamat nanti Isa itu akan menjadi saksi terhadap mereka.'),
  ('id.indonesian', 4, 160, 'Maka disebabkan kezaliman orang-orang Yahudi, kami haramkan atas (memakan makanan) yang baik-baik (yang dahulunya) dihalalkan bagi mereka, dan karena mereka banyak menghalangi (manusia) dari jalan Allah,'),
  ('id.indonesian', 4, 161, 'dan disebabkan mereka memakan riba, padahal sesungguhnya mereka telah dilarang daripadanya, dan karena mereka memakan harta benda orang dengan jalan yang batil. Kami telah menyediakan untuk orang-orang yang kafir di antara mereka itu siksa yang pedih.'),
  ('id.indonesian', 4, 162, 'Tetapi orang-orang yang mendalam ilmunya di antara mereka dan orang-orang mukmin, mereka beriman kepada apa yang telah diturunkan kepadamu (Al Quran), dan apa yang telah diturunkan sebelummu dan orang-orang yang mendirikan shalat, menunaikan zakat, dan yang beriman kepada Allah dan hari kemudian. Orang-orang itulah yang akan Kami berikan kepada mereka pahala yang besar.'),
  ('id.indonesian', 4, 163, 'Sesungguhnya Kami telah memberikan wahyu kepadamu sebagaimana Kami telah memberikan wahyu kepada Nuh dan nabi-nabi yang kemudiannya, dan Kami telah memberikan wahyu (pula) kepada Ibrahim, Isma\'il, Ishak, Ya\'qub dan anak cucunya, Isa, Ayyub, Yunus, Harun dan Sulaiman. Dan Kami berikan Zabur kepada Daud.'),
  ('id.indonesian', 4, 164, 'Dan (Kami telah mengutus) rasul-rasul yang sungguh telah Kami kisahkan tentang mereka kepadamu dahulu, dan rasul-rasul yang tidak Kami kisahkan tentang mereka kepadamu. Dan Allah telah berbicara kepada Musa dengan langsung.'),
  ('id.indonesian', 4, 165, '(Mereka Kami utus) selaku rasul-rasul pembawa berita gembira dan pemberi peringatan agar supaya tidak ada alasan bagi manusia membantah Allah sesudah diutusnya rasul-rasul itu. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 166, '(Mereka tidak mau mengakui yang diturunkan kepadamu itu), tetapi Allah mengakui Al Quran yang diturunkan-Nya kepadamu. Allah menurunkannya dengan ilmu-Nya; dan malaikat-malaikat pun menjadi saksi (pula). Cukuplah Allah yang mengakuinya.'),
  ('id.indonesian', 4, 167, 'Sesungguhnya orang-orang yang kafir dan menghalang-halangi (manusia) dari jalan Allah, benar-benar telah sesat sejauh-jauhnya.'),
  ('id.indonesian', 4, 168, 'Sesungguhnya orang-orang yang kafir dan melakukan kezaliman, Allah sekali-kali tidak akan mengampuni (dosa) mereka dan tidak (pula) akan menunjukkan jalan kepada mereka,'),
  ('id.indonesian', 4, 169, 'kecuali jalan ke neraka Jahannam; mereka kekal di dalamnya selama-lamanya. Dan yang demikian itu adalah mudah bagi Allah.'),
  ('id.indonesian', 4, 170, 'Wahai manusia, sesungguhnya telah datang Rasul (Muhammad) itu kepadamu dengan (membawa) kebenaran dari Tuhanmu, maka berimanlah kamu, itulah yang lebih baik bagimu. Dan jika kamu kafir, (maka kekafiran itu tidak merugikan Allah sedikitpun) karena sesungguhnya apa yang di langit dan di bumi itu adalah kepunyaan Allah. Dan adalah Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 4, 171, 'Wahai Ahli Kitab, janganlah kamu melampaui batas dalam agamamu, dan janganlah kamu mengatakan terhadap Allah kecuali yang benar. Sesungguhnya Al Masih, Isa putera Maryam itu, adalah utusan Allah dan (yang diciptakan dengan) kalimat-Nya yang disampaikan-Nya kepada Maryam, dan (dengan tiupan) roh dari-Nya. Maka berimanlah kamu kepada Allah dan rasul-rasul-Nya dan janganlah kamu mengatakan: "(Tuhan itu) tiga", berhentilah (dari ucapan itu). (Itu) lebih baik bagimu. Sesungguhnya Allah Tuhan Yang Maha Esa, Maha Suci Allah dari mempunyai anak, segala yang di langit dan di bumi adalah kepunyaan-Nya. Cukuplah Allah menjadi Pemelihara.'),
  ('id.indonesian', 4, 172, 'Al Masih sekali-kali tidak enggan menjadi hamba bagi Allah, dan tidak (pula enggan) malaikat-malaikat yang terdekat (kepada Allah). Barangsiapa yang enggan dari menyembah-Nya, dan menyombongkan diri, nanti Allah akan mengumpulkan mereka semua kepada-Nya.'),
  ('id.indonesian', 4, 173, 'Adapun orang-orang yang beriman dan berbuat amal saleh, maka Allah akan menyempurnakan pahala mereka dan menambah untuk mereka sebagian dari karunia-Nya. Adapun orang-orang yang enggan dan menyombongkan diri, maka Allah akan menyiksa mereka dengan siksaan yang pedih, dan mereka tidak akan memperoleh bagi diri mereka, pelindung dan penolong selain dari pada Allah.'),
  ('id.indonesian', 4, 174, 'Hai manusia, sesungguhnya telah datang kepadamu bukti kebenaran dari Tuhanmu. (Muhammad dengan mukjizatnya) dan telah Kami turunkan kepadamu cahaya yang terang benderang (Al Quran).'),
  ('id.indonesian', 4, 175, 'Adapun orang-orang yang beriman kepada Allah dan berpegang teguh kepada (agama)-Nya niscaya Allah akan memasukkan mereka ke dalam rahmat yang besar dari-Nya (surga) dan limpahan karunia-Nya. Dan menunjuki mereka kepada jalan yang lurus (untuk sampai) kepada-Nya.'),
  ('id.indonesian', 4, 176, 'Mereka meminta fatwa kepadamu (tentang kalalah). Katakanlah: "Allah memberi fatwa kepadamu tentang kalalah (yaitu): jika seorang meninggal dunia, dan ia tidak mempunyai anak dan mempunyai saudara perempuan, maka bagi saudaranya yang perempuan itu seperdua dari harta yang ditinggalkannya, dan saudaranya yang laki-laki mempusakai (seluruh harta saudara perempuan), jika ia tidak mempunyai anak; tetapi jika saudara perempuan itu dua orang, maka bagi keduanya dua pertiga dari harta yang ditinggalkan oleh yang meninggal. Dan jika mereka (ahli waris itu terdiri dari) saudara-saudara laki dan perempuan, maka bahagian seorang saudara laki-laki sebanyak bahagian dua orang saudara perempuan. Allah menerangkan (hukum ini) kepadamu, supaya kamu tidak sesat. Dan Allah Maha Mengetahui segala sesuatu.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 5, 1, 'O you who have believed, fulfill [all] contracts. Lawful for you are the animals of grazing livestock except for that which is recited to you [in this Qur\'an] - hunting not being permitted while you are in the state of ihram. Indeed, Allah ordains what He intends.'),
  ('en.sahih', 5, 2, 'O you who have believed, do not violate the rites of Allah or [the sanctity of] the sacred month or [neglect the marking of] the sacrificial animals and garlanding [them] or [violate the safety of] those coming to the Sacred House seeking bounty from their Lord and [His] approval. But when you come out of ihram, then [you may] hunt. And do not let the hatred of a people for having obstructed you from al-Masjid al-Haram lead you to transgress. And cooperate in righteousness and piety, but do not cooperate in sin and aggression. And fear Allah; indeed, Allah is severe in penalty.'),
  ('en.sahih', 5, 3, 'Prohibited to you are dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah, and [those animals] killed by strangling or by a violent blow or by a head-long fall or by the goring of horns, and those from which a wild animal has eaten, except what you [are able to] slaughter [before its death], and those which are sacrificed on stone altars, and [prohibited is] that you seek decision through divining arrows. That is grave disobedience. This day those who disbelieve have despaired of [defeating] your religion; so fear them not, but fear Me. This day I have perfected for you your religion and completed My favor upon you and have approved for you Islam as religion. But whoever is forced by severe hunger with no inclination to sin - then indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 5, 4, 'They ask you, [O Muhammad], what has been made lawful for them. Say, "Lawful for you are [all] good foods and [game caught by] what you have trained of hunting animals which you train as Allah has taught you. So eat of what they catch for you, and mention the name of Allah upon it, and fear Allah." Indeed, Allah is swift in account.'),
  ('en.sahih', 5, 5, 'This day [all] good foods have been made lawful, and the food of those who were given the Scripture is lawful for you and your food is lawful for them. And [lawful in marriage are] chaste women from among the believers and chaste women from among those who were given the Scripture before you, when you have given them their due compensation, desiring chastity, not unlawful sexual intercourse or taking [secret] lovers. And whoever denies the faith - his work has become worthless, and he, in the Hereafter, will be among the losers.'),
  ('en.sahih', 5, 6, 'O you who have believed, when you rise to [perform] prayer, wash your faces and your forearms to the elbows and wipe over your heads and wash your feet to the ankles. And if you are in a state of janabah, then purify yourselves. But if you are ill or on a journey or one of you comes from the place of relieving himself or you have contacted women and do not find water, then seek clean earth and wipe over your faces and hands with it. Allah does not intend to make difficulty for you, but He intends to purify you and complete His favor upon you that you may be grateful.'),
  ('en.sahih', 5, 7, 'And remember the favor of Allah upon you and His covenant with which He bound you when you said, "We hear and we obey"; and fear Allah. Indeed, Allah is Knowing of that within the breasts.'),
  ('en.sahih', 5, 8, 'O you who have believed, be persistently standing firm for Allah, witnesses in justice, and do not let the hatred of a people prevent you from being just. Be just; that is nearer to righteousness. And fear Allah; indeed, Allah is Acquainted with what you do.'),
  ('en.sahih', 5, 9, 'Allah has promised those who believe and do righteous deeds [that] for them there is forgiveness and great reward.'),
  ('en.sahih', 5, 10, 'But those who disbelieve and deny Our signs - those are the companions of Hellfire.'),
  ('en.sahih', 5, 11, 'O you who have believed, remember the favor of Allah upon you when a people determined to extend their hands [in aggression] against you, but He withheld their hands from you; and fear Allah. And upon Allah let the believers rely.'),
  ('en.sahih', 5, 12, 'And Allah had already taken a covenant from the Children of Israel, and We delegated from among them twelve leaders. And Allah said, "I am with you. If you establish prayer and give zakah and believe in My messengers and support them and loan Allah a goodly loan, I will surely remove from you your misdeeds and admit you to gardens beneath which rivers flow. But whoever of you disbelieves after that has certainly strayed from the soundness of the way."'),
  ('en.sahih', 5, 13, 'So for their breaking of the covenant We cursed them and made their hearts hard. They distort words from their [proper] usages and have forgotten a portion of that of which they were reminded. And you will still observe deceit among them, except a few of them. But pardon them and overlook [their misdeeds]. Indeed, Allah loves the doers of good.'),
  ('en.sahih', 5, 14, 'And from those who say, "We are Christians" We took their covenant; but they forgot a portion of that of which they were reminded. So We caused among them animosity and hatred until the Day of Resurrection. And Allah is going to inform them about what they used to do.'),
  ('en.sahih', 5, 15, 'O People of the Scripture, there has come to you Our Messenger making clear to you much of what you used to conceal of the Scripture and overlooking much. There has come to you from Allah a light and a clear Book.'),
  ('en.sahih', 5, 16, 'By which Allah guides those who pursue His pleasure to the ways of peace and brings them out from darknesses into the light, by His permission, and guides them to a straight path.'),
  ('en.sahih', 5, 17, 'They have certainly disbelieved who say that Allah is Christ, the son of Mary. Say, "Then who could prevent Allah at all if He had intended to destroy Christ, the son of Mary, or his mother or everyone on the earth?" And to Allah belongs the dominion of the heavens and the earth and whatever is between them. He creates what He wills, and Allah is over all things competent.'),
  ('en.sahih', 5, 18, 'But the Jews and the Christians say, "We are the children of Allah and His beloved." Say, "Then why does He punish you for your sins?" Rather, you are human beings from among those He has created. He forgives whom He wills, and He punishes whom He wills. And to Allah belongs the dominion of the heavens and the earth and whatever is between them, and to Him is the [final] destination.'),
  ('en.sahih', 5, 19, 'O People of the Scripture, there has come to you Our Messenger to make clear to you [the religion] after a period [of suspension] of messengers, lest you say, "There came not to us any bringer of good tidings or a warner." But there has come to you a bringer of good tidings and a warner. And Allah is over all things competent.'),
  ('en.sahih', 5, 20, 'And [mention, O Muhammad], when Moses said to his people, "O my people, remember the favor of Allah upon you when He appointed among you prophets and made you possessors and gave you that which He had not given anyone among the worlds.'),
  ('en.sahih', 5, 21, 'O my people, enter the Holy Land which Allah has assigned to you and do not turn back [from fighting in Allah \'s cause] and [thus] become losers."'),
  ('en.sahih', 5, 22, 'They said, "O Moses, indeed within it is a people of tyrannical strength, and indeed, we will never enter it until they leave it; but if they leave it, then we will enter."'),
  ('en.sahih', 5, 23, 'Said two men from those who feared [to disobey] upon whom Allah had bestowed favor, "Enter upon them through the gate, for when you have entered it, you will be predominant. And upon Allah rely, if you should be believers."'),
  ('en.sahih', 5, 24, 'They said, "O Moses, indeed we will not enter it, ever, as long as they are within it; so go, you and your Lord, and fight. Indeed, we are remaining right here."'),
  ('en.sahih', 5, 25, '[Moses] said, "My Lord, indeed I do not possess except myself and my brother, so part us from the defiantly disobedient people."'),
  ('en.sahih', 5, 26, '[Allah] said, "Then indeed, it is forbidden to them for forty years [in which] they will wander throughout the land. So do not grieve over the defiantly disobedient people."'),
  ('en.sahih', 5, 27, 'And recite to them the story of Adam\'s two sons, in truth, when they both offered a sacrifice [to Allah], and it was accepted from one of them but was not accepted from the other. Said [the latter], "I will surely kill you." Said [the former], "Indeed, Allah only accepts from the righteous [who fear Him].'),
  ('en.sahih', 5, 28, 'If you should raise your hand against me to kill me - I shall not raise my hand against you to kill you. Indeed, I fear Allah, Lord of the worlds.'),
  ('en.sahih', 5, 29, 'Indeed I want you to obtain [thereby] my sin and your sin so you will be among the companions of the Fire. And that is the recompense of wrongdoers."'),
  ('en.sahih', 5, 30, 'And his soul permitted to him the murder of his brother, so he killed him and became among the losers.'),
  ('en.sahih', 5, 31, 'Then Allah sent a crow searching in the ground to show him how to hide the disgrace of his brother. He said, "O woe to me! Have I failed to be like this crow and hide the body of my brother?" And he became of the regretful.'),
  ('en.sahih', 5, 32, 'Because of that, We decreed upon the Children of Israel that whoever kills a soul unless for a soul or for corruption [done] in the land - it is as if he had slain mankind entirely. And whoever saves one - it is as if he had saved mankind entirely. And our messengers had certainly come to them with clear proofs. Then indeed many of them, [even] after that, throughout the land, were transgressors.'),
  ('en.sahih', 5, 33, 'Indeed, the penalty for those who wage war against Allah and His Messenger and strive upon earth [to cause] corruption is none but that they be killed or crucified or that their hands and feet be cut off from opposite sides or that they be exiled from the land. That is for them a disgrace in this world; and for them in the Hereafter is a great punishment,'),
  ('en.sahih', 5, 34, 'Except for those who return [repenting] before you apprehend them. And know that Allah is Forgiving and Merciful.'),
  ('en.sahih', 5, 35, 'O you who have believed, fear Allah and seek the means [of nearness] to Him and strive in His cause that you may succeed.'),
  ('en.sahih', 5, 36, 'Indeed, those who disbelieve - if they should have all that is in the earth and the like of it with it by which to ransom themselves from the punishment of the Day of Resurrection, it will not be accepted from them, and for them is a painful punishment'),
  ('en.sahih', 5, 37, 'They will wish to get out of the Fire, but never are they to emerge therefrom, and for them is an enduring punishment.'),
  ('en.sahih', 5, 38, '[As for] the thief, the male and the female, amputate their hands in recompense for what they committed as a deterrent [punishment] from Allah. And Allah is Exalted in Might and Wise.'),
  ('en.sahih', 5, 39, 'But whoever repents after his wrongdoing and reforms, indeed, Allah will turn to him in forgiveness. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 5, 40, 'Do you not know that to Allah belongs the dominion of the heavens and the earth? He punishes whom He wills and forgives whom He wills, and Allah is over all things competent.'),
  ('en.sahih', 5, 41, 'O Messenger, let them not grieve you who hasten into disbelief of those who say, "We believe" with their mouths, but their hearts believe not, and from among the Jews. [They are] avid listeners to falsehood, listening to another people who have not come to you. They distort words beyond their [proper] usages, saying "If you are given this, take it; but if you are not given it, then beware." But he for whom Allah intends fitnah - never will you possess [power to do] for him a thing against Allah. Those are the ones for whom Allah does not intend to purify their hearts. For them in this world is disgrace, and for them in the Hereafter is a great punishment.'),
  ('en.sahih', 5, 42, '[They are] avid listeners to falsehood, devourers of [what is] unlawful. So if they come to you, [O Muhammad], judge between them or turn away from them. And if you turn away from them - never will they harm you at all. And if you judge, judge between them with justice. Indeed, Allah loves those who act justly.'),
  ('en.sahih', 5, 43, 'But how is it that they come to you for judgement while they have the Torah, in which is the judgement of Allah? Then they turn away, [even] after that; but those are not [in fact] believers.'),
  ('en.sahih', 5, 44, 'Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted [to Allah] judged by it for the Jews, as did the rabbis and scholars by that with which they were entrusted of the Scripture of Allah, and they were witnesses thereto. So do not fear the people but fear Me, and do not exchange My verses for a small price. And whoever does not judge by what Allah has revealed - then it is those who are the disbelievers.'),
  ('en.sahih', 5, 45, 'And We ordained for them therein a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and for wounds is legal retribution. But whoever gives [up his right as] charity, it is an expiation for him. And whoever does not judge by what Allah has revealed - then it is those who are the wrongdoers.'),
  ('en.sahih', 5, 46, 'And We sent, following in their footsteps, Jesus, the son of Mary, confirming that which came before him in the Torah; and We gave him the Gospel, in which was guidance and light and confirming that which preceded it of the Torah as guidance and instruction for the righteous.'),
  ('en.sahih', 5, 47, 'And let the People of the Gospel judge by what Allah has revealed therein. And whoever does not judge by what Allah has revealed - then it is those who are the defiantly disobedient.'),
  ('en.sahih', 5, 48, 'And We have revealed to you, [O Muhammad], the Book in truth, confirming that which preceded it of the Scripture and as a criterion over it. So judge between them by what Allah has revealed and do not follow their inclinations away from what has come to you of the truth. To each of you We prescribed a law and a method. Had Allah willed, He would have made you one nation [united in religion], but [He intended] to test you in what He has given you; so race to [all that is] good. To Allah is your return all together, and He will [then] inform you concerning that over which you used to differ.'),
  ('en.sahih', 5, 49, 'And judge, [O Muhammad], between them by what Allah has revealed and do not follow their inclinations and beware of them, lest they tempt you away from some of what Allah has revealed to you. And if they turn away - then know that Allah only intends to afflict them with some of their [own] sins. And indeed, many among the people are defiantly disobedient.'),
  ('en.sahih', 5, 50, 'Then is it the judgement of [the time of] ignorance they desire? But who is better than Allah in judgement for a people who are certain [in faith].'),
  ('en.sahih', 5, 51, 'O you who have believed, do not take the Jews and the Christians as allies. They are [in fact] allies of one another. And whoever is an ally to them among you - then indeed, he is [one] of them. Indeed, Allah guides not the wrongdoing people.'),
  ('en.sahih', 5, 52, 'So you see those in whose hearts is disease hastening into [association with] them, saying, "We are afraid a misfortune may strike us." But perhaps Allah will bring conquest or a decision from Him, and they will become, over what they have been concealing within themselves, regretful.'),
  ('en.sahih', 5, 53, 'And those who believe will say, "Are these the ones who swore by Allah their strongest oaths that indeed they were with you?" Their deeds have become worthless, and they have become losers.'),
  ('en.sahih', 5, 54, 'O you who have believed, whoever of you should revert from his religion - Allah will bring forth [in place of them] a people He will love and who will love Him [who are] humble toward the believers, powerful against the disbelievers; they strive in the cause of Allah and do not fear the blame of a critic. That is the favor of Allah; He bestows it upon whom He wills. And Allah is all-Encompassing and Knowing.'),
  ('en.sahih', 5, 55, 'Your ally is none but Allah and [therefore] His Messenger and those who have believed - those who establish prayer and give zakah, and they bow [in worship].'),
  ('en.sahih', 5, 56, 'And whoever is an ally of Allah and His Messenger and those who have believed - indeed, the party of Allah - they will be the predominant.'),
  ('en.sahih', 5, 57, 'O you who have believed, take not those who have taken your religion in ridicule and amusement among the ones who were given the Scripture before you nor the disbelievers as allies. And fear Allah, if you should [truly] be believers.'),
  ('en.sahih', 5, 58, 'And when you call to prayer, they take it in ridicule and amusement. That is because they are a people who do not use reason.'),
  ('en.sahih', 5, 59, 'Say, "O People of the Scripture, do you resent us except [for the fact] that we have believed in Allah and what was revealed to us and what was revealed before and because most of you are defiantly disobedient?"'),
  ('en.sahih', 5, 60, 'Say, "Shall I inform you of [what is] worse than that as penalty from Allah? [It is that of] those whom Allah has cursed and with whom He became angry and made of them apes and pigs and slaves of Taghut. Those are worse in position and further astray from the sound way."'),
  ('en.sahih', 5, 61, 'And when they come to you, they say, "We believe." But they have entered with disbelief [in their hearts], and they have certainly left with it. And Allah is most knowing of what they were concealing.'),
  ('en.sahih', 5, 62, 'And you see many of them hastening into sin and aggression and the devouring of [what is] unlawful. How wretched is what they have been doing.'),
  ('en.sahih', 5, 63, 'Why do the rabbis and religious scholars not forbid them from saying what is sinful and devouring what is unlawful? How wretched is what they have been practicing.'),
  ('en.sahih', 5, 64, 'And the Jews say, "The hand of Allah is chained." Chained are their hands, and cursed are they for what they say. Rather, both His hands are extended; He spends however He wills. And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. And We have cast among them animosity and hatred until the Day of Resurrection. Every time they kindled the fire of war [against you], Allah extinguished it. And they strive throughout the land [causing] corruption, and Allah does not like corrupters.'),
  ('en.sahih', 5, 65, 'And if only the People of the Scripture had believed and feared Allah, We would have removed from them their misdeeds and admitted them to Gardens of Pleasure.'),
  ('en.sahih', 5, 66, 'And if only they upheld [the law of] the Torah, the Gospel, and what has been revealed to them from their Lord, they would have consumed [provision] from above them and from beneath their feet. Among them are a moderate community, but many of them - evil is that which they do.'),
  ('en.sahih', 5, 67, 'O Messenger, announce that which has been revealed to you from your Lord, and if you do not, then you have not conveyed His message. And Allah will protect you from the people. Indeed, Allah does not guide the disbelieving people.'),
  ('en.sahih', 5, 68, 'Say, "O People of the Scripture, you are [standing] on nothing until you uphold [the law of] the Torah, the Gospel, and what has been revealed to you from your Lord." And that which has been revealed to you from your Lord will surely increase many of them in transgression and disbelief. So do not grieve over the disbelieving people.'),
  ('en.sahih', 5, 69, 'Indeed, those who have believed [in Prophet Muhammad] and those [before Him] who were Jews or Sabeans or Christians - those [among them] who believed in Allah and the Last Day and did righteousness - no fear will there be concerning them, nor will they grieve.'),
  ('en.sahih', 5, 70, 'We had already taken the covenant of the Children of Israel and had sent to them messengers. Whenever there came to them a messenger with what their souls did not desire, a party [of messengers] they denied, and another party they killed.'),
  ('en.sahih', 5, 71, 'And they thought there would be no [resulting] punishment, so they became blind and deaf. Then Allah turned to them in forgiveness; then [again] many of them became blind and deaf. And Allah is Seeing of what they do.'),
  ('en.sahih', 5, 72, 'They have certainly disbelieved who say, "Allah is the Messiah, the son of Mary" while the Messiah has said, "O Children of Israel, worship Allah, my Lord and your Lord." Indeed, he who associates others with Allah - Allah has forbidden him Paradise, and his refuge is the Fire. And there are not for the wrongdoers any helpers.'),
  ('en.sahih', 5, 73, 'They have certainly disbelieved who say, "Allah is the third of three." And there is no god except one God. And if they do not desist from what they are saying, there will surely afflict the disbelievers among them a painful punishment.'),
  ('en.sahih', 5, 74, 'So will they not repent to Allah and seek His forgiveness? And Allah is Forgiving and Merciful.'),
  ('en.sahih', 5, 75, 'The Messiah, son of Mary, was not but a messenger; [other] messengers have passed on before him. And his mother was a supporter of truth. They both used to eat food. Look how We make clear to them the signs; then look how they are deluded.'),
  ('en.sahih', 5, 76, 'Say, "Do you worship besides Allah that which holds for you no [power of] harm or benefit while it is Allah who is the Hearing, the Knowing?"'),
  ('en.sahih', 5, 77, 'Say, "O People of the Scripture, do not exceed limits in your religion beyond the truth and do not follow the inclinations of a people who had gone astray before and misled many and have strayed from the soundness of the way."'),
  ('en.sahih', 5, 78, 'Cursed were those who disbelieved among the Children of Israel by the tongue of David and of Jesus, the son of Mary. That was because they disobeyed and [habitually] transgressed.'),
  ('en.sahih', 5, 79, 'They used not to prevent one another from wrongdoing that they did. How wretched was that which they were doing.'),
  ('en.sahih', 5, 80, 'You see many of them becoming allies of those who disbelieved. How wretched is that which they have put forth for themselves in that Allah has become angry with them, and in the punishment they will abide eternally.'),
  ('en.sahih', 5, 81, 'And if they had believed in Allah and the Prophet and in what was revealed to him, they would not have taken them as allies; but many of them are defiantly disobedient.'),
  ('en.sahih', 5, 82, 'You will surely find the most intense of the people in animosity toward the believers [to be] the Jews and those who associate others with Allah; and you will find the nearest of them in affection to the believers those who say, "We are Christians." That is because among them are priests and monks and because they are not arrogant.'),
  ('en.sahih', 5, 83, 'And when they hear what has been revealed to the Messenger, you see their eyes overflowing with tears because of what they have recognized of the truth. They say, "Our Lord, we have believed, so register us among the witnesses.'),
  ('en.sahih', 5, 84, 'And why should we not believe in Allah and what has come to us of the truth? And we aspire that our Lord will admit us [to Paradise] with the righteous people."'),
  ('en.sahih', 5, 85, 'So Allah rewarded them for what they said with gardens [in Paradise] beneath which rivers flow, wherein they abide eternally. And that is the reward of doers of good.'),
  ('en.sahih', 5, 86, 'But those who disbelieved and denied Our signs - they are the companions of Hellfire.'),
  ('en.sahih', 5, 87, 'O you who have believed, do not prohibit the good things which Allah has made lawful to you and do not transgress. Indeed, Allah does not like transgressors.'),
  ('en.sahih', 5, 88, 'And eat of what Allah has provided for you [which is] lawful and good. And fear Allah, in whom you are believers.'),
  ('en.sahih', 5, 89, 'Allah will not impose blame upon you for what is meaningless in your oaths, but He will impose blame upon you for [breaking] what you intended of oaths. So its expiation is the feeding of ten needy people from the average of that which you feed your [own] families or clothing them or the freeing of a slave. But whoever cannot find [or afford it] - then a fast of three days [is required]. That is the expiation for oaths when you have sworn. But guard your oaths. Thus does Allah make clear to you His verses that you may be grateful.'),
  ('en.sahih', 5, 90, 'O you who have believed, indeed, intoxicants, gambling, [sacrificing on] stone alters [to other than Allah], and divining arrows are but defilement from the work of Satan, so avoid it that you may be successful.'),
  ('en.sahih', 5, 91, 'Satan only wants to cause between you animosity and hatred through intoxicants and gambling and to avert you from the remembrance of Allah and from prayer. So will you not desist?'),
  ('en.sahih', 5, 92, 'And obey Allah and obey the Messenger and beware. And if you turn away - then know that upon Our Messenger is only [the responsibility for] clear notification.'),
  ('en.sahih', 5, 93, 'There is not upon those who believe and do righteousness [any] blame concerning what they have eaten [in the past] if they [now] fear Allah and believe and do righteous deeds, and then fear Allah and believe, and then fear Allah and do good; and Allah loves the doers of good.'),
  ('en.sahih', 5, 94, 'O you who have believed, Allah will surely test you through something of the game that your hands and spears [can] reach, that Allah may make evident those who fear Him unseen. And whoever transgresses after that - for him is a painful punishment.'),
  ('en.sahih', 5, 95, 'O you who have believed, do not kill game while you are in the state of ihram. And whoever of you kills it intentionally - the penalty is an equivalent from sacrificial animals to what he killed, as judged by two just men among you as an offering [to Allah] delivered to the Ka\'bah, or an expiation: the feeding of needy people or the equivalent of that in fasting, that he may taste the consequence of his deed. Allah has pardoned what is past; but whoever returns [to violation], then Allah will take retribution from him. And Allah is Exalted in Might and Owner of Retribution.'),
  ('en.sahih', 5, 96, 'Lawful to you is game from the sea and its food as provision for you and the travelers, but forbidden to you is game from the land as long as you are in the state of ihram. And fear Allah to whom you will be gathered.'),
  ('en.sahih', 5, 97, 'Allah has made the Ka\'bah, the Sacred House, standing for the people and [has sanctified] the sacred months and the sacrificial animals and the garlands [by which they are identified]. That is so you may know that Allah knows what is in the heavens and what is in the earth and that Allah is Knowing of all things.'),
  ('en.sahih', 5, 98, 'Know that Allah is severe in penalty and that Allah is Forgiving and Merciful.'),
  ('en.sahih', 5, 99, 'Not upon the Messenger is [responsibility] except [for] notification. And Allah knows whatever you reveal and whatever you conceal.'),
  ('en.sahih', 5, 100, 'Say, "Not equal are the evil and the good, although the abundance of evil might impress you." So fear Allah, O you of understanding, that you may be successful.'),
  ('en.sahih', 5, 101, 'O you who have believed, do not ask about things which, if they are shown to you, will distress you. But if you ask about them while the Qur\'an is being revealed, they will be shown to you. Allah has pardoned that which is past; and Allah is Forgiving and Forbearing.'),
  ('en.sahih', 5, 102, 'A people asked such [questions] before you; then they became thereby disbelievers.'),
  ('en.sahih', 5, 103, 'Allah has not appointed [such innovations as] bahirah or sa\'ibah or wasilah or ham. But those who disbelieve invent falsehood about Allah, and most of them do not reason.'),
  ('en.sahih', 5, 104, 'And when it is said to them, "Come to what Allah has revealed and to the Messenger," they say, "Sufficient for us is that upon which we found our fathers." Even though their fathers knew nothing, nor were they guided?'),
  ('en.sahih', 5, 105, 'O you who have believed, upon you is [responsibility for] yourselves. Those who have gone astray will not harm you when you have been guided. To Allah is you return all together; then He will inform you of what you used to do.'),
  ('en.sahih', 5, 106, 'O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - [that of] two just men from among you or two others from outside if you are traveling through the land and the disaster of death should strike you. Detain them after the prayer and let them both swear by Allah if you doubt [their testimony, saying], "We will not exchange our oath for a price, even if he should be a near relative, and we will not withhold the testimony of Allah. Indeed, we would then be of the sinful."'),
  ('en.sahih', 5, 107, 'But if it is found that those two were guilty of perjury, let two others stand in their place [who are] foremost [in claim] from those who have a lawful right. And let them swear by Allah, "Our testimony is truer than their testimony, and we have not transgressed. Indeed, we would then be of the wrongdoers."'),
  ('en.sahih', 5, 108, 'That is more likely that they will give testimony according to its [true] objective, or [at least] they would fear that [other] oaths might be taken after their oaths. And fear Allah and listen; and Allah does not guide the defiantly disobedient people.'),
  ('en.sahih', 5, 109, '[Be warned of] the Day when Allah will assemble the messengers and say, "What was the response you received?" They will say, "We have no knowledge. Indeed, it is You who is Knower of the unseen"'),
  ('en.sahih', 5, 110, '[The Day] when Allah will say, "O Jesus, Son of Mary, remember My favor upon you and upon your mother when I supported you with the Pure Spirit and you spoke to the people in the cradle and in maturity; and [remember] when I taught you writing and wisdom and the Torah and the Gospel; and when you designed from clay [what was] like the form of a bird with My permission, then you breathed into it, and it became a bird with My permission; and you healed the blind and the leper with My permission; and when you brought forth the dead with My permission; and when I restrained the Children of Israel from [killing] you when you came to them with clear proofs and those who disbelieved among them said, "This is not but obvious magic."'),
  ('en.sahih', 5, 111, 'And [remember] when I inspired to the disciples, "Believe in Me and in My messenger Jesus." They said, "We have believed, so bear witness that indeed we are Muslims [in submission to Allah]."'),
  ('en.sahih', 5, 112, '[And remember] when the disciples said, "O Jesus, Son of Mary, can your Lord send down to us a table [spread with food] from the heaven? [Jesus] said," Fear Allah, if you should be believers."'),
  ('en.sahih', 5, 113, 'They said, "We wish to eat from it and let our hearts be reassured and know that you have been truthful to us and be among its witnesses."'),
  ('en.sahih', 5, 114, 'Said Jesus, the son of Mary, "O Allah, our Lord, send down to us a table [spread with food] from the heaven to be for us a festival for the first of us and the last of us and a sign from You. And provide for us, and You are the best of providers."'),
  ('en.sahih', 5, 115, 'Allah said, "Indeed, I will sent it down to you, but whoever disbelieves afterwards from among you - then indeed will I punish him with a punishment by which I have not punished anyone among the worlds."'),
  ('en.sahih', 5, 116, 'And [beware the Day] when Allah will say, "O Jesus, Son of Mary, did you say to the people, \'Take me and my mother as deities besides Allah?\'" He will say, "Exalted are You! It was not for me to say that to which I have no right. If I had said it, You would have known it. You know what is within myself, and I do not know what is within Yourself. Indeed, it is You who is Knower of the unseen.'),
  ('en.sahih', 5, 117, 'I said not to them except what You commanded me - to worship Allah, my Lord and your Lord. And I was a witness over them as long as I was among them; but when You took me up, You were the Observer over them, and You are, over all things, Witness.'),
  ('en.sahih', 5, 118, 'If You should punish them - indeed they are Your servants; but if You forgive them - indeed it is You who is the Exalted in Might, the Wise.'),
  ('en.sahih', 5, 119, 'Allah will say, "This is the Day when the truthful will benefit from their truthfulness." For them are gardens [in Paradise] beneath which rivers flow, wherein they will abide forever, Allah being pleased with them, and they with Him. That is the great attainment.'),
  ('en.sahih', 5, 120, 'To Allah belongs the dominion of the heavens and the earth and whatever is within them. And He is over all things competent.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 5, 1, 'মুমিনগণ, তোমরা অঙ্গীকারসমূহ পূর্ন কর। তোমাদের জন্য চতুষ্পদ জন্তু হালাল করা হয়েছে, যা তোমাদের কাছে বিবৃত হবে তা ব্যতীত। কিন্তু এহরাম বাধাঁ অবস্থায় শিকারকে হালাল মনে করো না! নিশ্চয় আল্লাহ তা’আলা যা ইচ্ছা করেন, নির্দেশ দেন।'),
  ('bn.bengali', 5, 2, 'হে মুমিনগণ! হালাল মনে করো না আল্লাহর নিদর্শনসমূহ এবং সম্মানিত মাসসমূহকে এবং হরমে কুরবানীর জন্যে নির্দিষ্ট জন্তুকে এবং ঐসব জন্তুকে, যাদের গলায় কন্ঠাভরণ রয়েছে এবং ঐসব লোককে যারা সম্মানিত গৃহ অভিমুখে যাচ্ছে, যারা স্বীয় পালনকর্তার অনুগ্রহ ও সন্তুষ্টি কামনা করে। যখন তোমরা এহরাম থেকে বের হয়ে আস, তখন শিকার কর। যারা পবিত্র মসজিদ থেকে তোমাদেরকে বাধা প্রদান করেছিল, সেই সম্প্রদায়ের শুত্রুতা যেন তোমাদেরকে সীমালঙ্ঘনে প্ররোচিত না করে। সৎকর্ম ও খোদাভীতিতে একে অন্যের সাহায্য কর। পাপ ও সীমালঙ্ঘনের ব্যাপারে একে অন্যের সহায়তা করো না। আল্লাহকে ভয় কর। নিশ্চয় আল্লাহ তা’আলা কঠোর শাস্তিদাতা।'),
  ('bn.bengali', 5, 3, 'তোমাদের জন্যে হারাম করা হয়েছে মৃত জীব, রক্ত, শুকরের মাংস, যেসব জন্তু আল্লাহ ছাড়া অন্যের নামে উৎসর্গকৃত হয়, যা কন্ঠরোধে মারা যায়, যা আঘাত লেগে মারা যায়, যা উচ্চ স্থান থেকে পতনের ফলে মারা যা, যা শিং এর আঘাতে মারা যায় এবং যাকে হিংস্র জন্তু ভক্ষণ করেছে, কিন্তু যাকে তোমরা যবেহ করেছ। যে জন্তু যজ্ঞবেদীতে যবেহ করা হয় এবং যা ভাগ্য নির্ধারক শর দ্বারা বন্টন করা হয়। এসব গোনাহর কাজ। আজ কাফেররা তোমাদের দ্বীন থেকে নিরাশ হয়ে গেছে। অতএব তাদেরকে ভয় করো না বরং আমাকে ভয় কর। আজ আমি তোমাদের জন্যে তোমাদের দ্বীনকে পূর্নাঙ্গ করে দিলাম, তোমাদের প্রতি আমার অবদান সম্পূর্ণ করে দিলাম এবং ইসলামকে তোমাদের জন্যে দ্বীন হিসেবে পছন্দ করলাম। অতএব যে ব্যাক্তি তীব্র ক্ষুধায় কাতর হয়ে পড়ে; কিন্তু কোন গোনাহর প্রতি প্রবণতা না থাকে, তবে নিশ্চয়ই আল্লাহ তা’আলা ক্ষমাশীল।'),
  ('bn.bengali', 5, 4, 'তারা আপনাকে জিজ্ঞেস করে যে, কি বস্তু তাদের জন্যে হালাল? বলে দিন, তোমাদের জন্যে পবিত্র বস্তুসমূহ হালাল করা হয়েছে। যেসব শিকারী জন্তুকে তোমরা প্রশিক্ষণ দান কর শিকারের প্রতি প্রেরণের জন্যে এবং ওদেরকে ঐ পদ্ধতিতে প্রশিক্ষণ দাও, যা আল্লাহ তোমাদেরকে শিক্ষা দিয়েছেন। এমন শিকারী জন্তু যে শিকারকে তোমাদের জন্যে ধরে রাখে, তা খাও এবং তার উপর আল্লাহর নাম উচ্চারণ কর। আল্লাহকে ভয় করতে থাক। নিশ্চয় আল্লাহ সত্ত্বর হিসাব গ্রহণকারী।'),
  ('bn.bengali', 5, 5, 'আজ তোমাদের জন্য পবিত্র বস্তুসমূহ হালাল করা হল। আহলে কিতাবদের খাদ্য তোমাদের জন্যে হালাল এবং তোমাদের খাদ্য তাদের জন্য হালাল। তোমাদের জন্যে হালাল সতী-সাধ্বী মুসলমান নারী এবং তাদের সতী-সাধ্বী নারী, যাদেরকে কিতাব দেয়া হয়েছে তোমাদের পূর্বে, যখন তোমরা তাদেরকে মোহরানা প্রদান কর তাদেরকে স্ত্রী করার জন্যে, কামবাসনা চরিতার্থ করার জন্যে কিংবা গুপ্ত প্রেমে লিপ্ত হওয়ার জন্যে নয়। যে ব্যক্তি বিশ্বাসের বিষয় অবিশ্বাস করে, তার শ্রম বিফলে যাবে এবং পরকালে সে ক্ষতিগ্রস্ত হবে।'),
  ('bn.bengali', 5, 6, 'হে মুমিনগণ, যখন তোমরা নামাযের জন্যে উঠ, তখন স্বীয় মুখমন্ডল ও হস্তসমূহ কনুই পর্যন্ত ধৌত কর, মাথা মুছেহ কর এবং পদযুগল গিটসহ। যদি তোমরা অপবিত্র হও তবে সারা দেহ পবিত্র করে নাও এবং যদি তোমরা রুগ্ন হও, অথবা প্রবাসে থাক অথবা তোমাদের কেউ প্রসাব-পায়খানা সেরে আসে অথবা তোমরা স্ত্রীদের সাথে সহবাস কর, অতঃপর পানি না পাও, তবে তোমরা পবিত্র মাটি দ্বারা তায়াম্মুম করে নাও-অর্থাৎ, স্বীয় মুখ-মন্ডল ও হস্তদ্বয় মাটি দ্বারা মুছে ফেল। আল্লাহ তোমাদেরকে অসুবিধায় ফেলতে চান না; কিন্তু তোমাদেরকে পবিত্র রাখতে চান এবং তোমাদের প্রতি স্বীয় নেয়ামত পূর্ণ করতে চান-যাতে তোমরা কৃতজ্ঞাতা প্রকাশ কর।'),
  ('bn.bengali', 5, 7, 'তোমরা আল্লাহর নেয়ামতের কথা স্মরণ কর, যা তোমাদের প্রতি অবতীর্ণ হয়েছে এবং ঐ অঙ্গীকারকেও যা তোমাদের কাছ থেকে নিয়েছেন, যখন তোমরা বলেছিলেঃ আমরা শুনলাম এবং মেনে নিলাম। আল্লাহকে ভয় কর। নিশ্চয়ই আল্লাহ অন্তরের বিষয় সম্পর্কে পুরোপুরি খবর রাখেন।'),
  ('bn.bengali', 5, 8, 'হে মুমিনগণ, তোমরা আল্লাহর উদ্দেশে ন্যায় সাক্ষ্যদানের ব্যাপারে অবিচল থাকবে এবং কোন সম্প্রদায়ের শত্রুতার কারণে কখনও ন্যায়বিচার পরিত্যাগ করো না। সুবিচার কর এটাই খোদাভীতির অধিক নিকটবর্তী। আল্লাহকে ভয় কর। তোমরা যা কর, নিশ্চয় আল্লাহ সে বিষয়ে খুব জ্ঞাত।'),
  ('bn.bengali', 5, 9, 'যারা বিশ্বাস স্থাপন করে, এবং সৎকর্ম সম্পাদন করে, আল্লাহ তা˦#2503;দরকে ক্ষমা ও মহান প্রতিদানের প্রতিশ্রুতি দিয়েছেন।'),
  ('bn.bengali', 5, 10, 'যারা অবিশ্বাস করে এবং আমার নিদর্শনাবলীকে মিথ্যা বলে, তার দোযখী।'),
  ('bn.bengali', 5, 11, 'হে মুমিনগণ, তোমাদের প্রতি আল্লাহর অনুগ্রহ স্মরণ কর, যখন এক সম্প্রদায় তোমাদের দিকে স্বীয় হস্ত প্রসারিত করতে সচেষ্ট হয়েছিল, তখন তিনি তাদের হস্ত তোমাদের থেকে প্রতিহত করে দিলেন। আল্লাহকে ভয় কর এবং মুমিনদের আল্লাহর উপরই ভরসা করা উচিত।'),
  ('bn.bengali', 5, 12, 'আল্লাহ বনী-ইসরাঈলের কাছ থেকে অঙ্গীকার নিয়েছিলেন এবং আমি তাদের মধ্য থেকে বার জন সর্দার নিযুক্ত করেছিলাম। আল্লাহ বলে দিলেনঃ আমি তোমাদের সঙ্গে আছি। যদি তোমরা নামায প্রতিষ্ঠিত কর, যাকাত দিতে থাক, আমার পয়গম্বরদের প্রতি বিশ্বাস রাখ, তাঁদের সাহায্য কর এবং আল্লাহকে উত্তম পন্থায় ঋন দিতে থাক, তবে আমি অবশ্যই তোমাদের গোনাহ দুর করে দিব এবং অবশ্যই তোমাদেরকে উদ্যান সমূহে প্রবিষ্ট করব, যেগুলোর তলদেশ দিয়ে নিঝরিনীসমূহ প্রবাহিত হয়। অতঃপর তোমাদের মধ্য থেকে যে ব্যক্তি এরপরও কাফের হয়, সে নিশ্চিতই সরল পথ থেকে বিচ্যুত হয়ে পড়ে।'),
  ('bn.bengali', 5, 13, 'অতএব, তাদের অঙ্গীকার ভঙ্গের দরুন আমি তাদের উপর অভিসম্পাত করেছি এবং তাদের অন্তরকে কঠোর করে দিয়েছি। তারা কালামকে তার স্থান থেকে বিচ্যুত করে দেয় এবং তাদেরকে যে উপদেশ দেয়া হয়েছিল, তারা তা থেকে উপকার লাভ করার বিষয়টি বিস্মৃত হয়েছে। আপনি সর্বদা তাদের কোন না কোন প্রতারণা সম্পর্কে অবগত হতে থাকেন, তাদের অল্প কয়েকজন ছাড়া। অতএব, আপনি তাদেরকে ক্ষমা করুন এবং মার্জনা করুন। আল্লাহ অনুগ্রহকারীদেরকে ভালবাসেন।'),
  ('bn.bengali', 5, 14, 'যারা বলেঃ আমরা নাছারা, আমি তাদের কাছ থেকেও তাদের অঙ্গীকার নিয়েছিলাম। অতঃপর তারাও যে উপদেশ প্রাপ্ত হয়েছিল, তা থেকে উপকার লাভ করা ভুলে গেল। অতঃপর আমি কেয়ামত পর্যন্ত তাদের মধ্যে পারস্পরিক শত্রুতা ও বিদ্বেষ সঞ্চারিত করে দিয়েছি। অবশেষে আল্লাহ তাদেরকে তাদের কৃতকর্ম সম্পর্কে অবহিত করবেন।'),
  ('bn.bengali', 5, 15, 'হে আহলে-কিতাবগণ! তোমাদের কাছে আমার রাসূল আগমন করেছেন! কিতাবের যেসব বিষয় তোমরা গোপন করতে, তিনি তার মধ্য থেকে অনেক বিষয় প্রকাশ করেন এবং অনেক বিষয় মার্জনা করেন। তোমাদের কাছে একটি উজ্জল জ্যোতি এসেছে এবং একটি সমুজ্জল গ্রন্থ।'),
  ('bn.bengali', 5, 16, 'এর দ্বারা আল্লাহ যারা তাঁর সন্তুষ্টি কামনা করে, তাদেরকে নিরাপত্তার পথ প্রদর্শন করেন এবং তাদেরকে স্বীয় নির্দেশ দ্বারা অন্ধকার থেকে বের করে আলোর দিকে আনয়ন করেন এবং সরল পথে পরিচালনা করেন।'),
  ('bn.bengali', 5, 17, 'নিশ্চয় তারা কাফের, যারা বলে, মসীহ ইবনে মরিয়মই আল্লাহ। আপনি জিজ্ঞেস করুন, যদি তাই হয়, তবে বল যদি আল্লাহ মসীহ ইবনে মরিয়ম, তাঁর জননী এবং ভূমন্ডলে যারা আছে, তাদের সবাইকে ধ্বংস করতে চান, তবে এমন কারও সাধ্য আছে কি যে আল্লাহর কাছ থেকে তাদেরকে বিন্দুমাত্রও বাঁচাতে পারে? নভোমন্ডল, ভুমন্ডল ও এতদুভয়ের মধ্যে যা আছে, সবকিছুর উপর আল্লাহ তা’আলার আধিপত্য। তিনি যা ইচ্ছা সৃষ্টি করেন। আল্লাহ সবকিছুর উপর শক্তিমান।'),
  ('bn.bengali', 5, 18, 'ইহুদী ও খ্রীষ্টানরা বলে, আমরা আল্লাহর সন্তান ও তাঁর প্রিয়জন। আপনি বলুন, তবে তিনি তোমাদেরকে পাপের বিনিময়ে কেন শাস্তি দান করবেন? বরং তোমারও অন্যান্য সৃষ্ট মানবের অন্তর্ভুক্ত সাধারণ মানুষ। তিনি যাকে ইচ্ছা ক্ষমা করেন এবং যাকে ইচ্ছা শাস্তি প্রদান করেন। নভোমন্ডল, ভুমন্ডল ও এতদুভয়ের মধ্যে যা কিছু আছে, তাতে আল্লাহরই আধিপত্য রয়েছে এবং তাঁর দিকেই প্রত্যাবর্তন করতে হবে।'),
  ('bn.bengali', 5, 19, 'হে আহলে-কিতাবগণ! তোমাদের কাছে আমার রসূল আগমণ করেছেন, যিনি পয়গম্বরদের বিরতির পর তোমাদের কাছে পুঙ্খানুপুঙ্খ বর্ণনা করেন-যাতে তোমরা একথা বলতে না পার যে, আমাদের কাছে কোন সুসংবাদদাতা ও ভীতিপ্রদর্শক আগমন করে নি। অতএব, তোমাদের কাছে সুসংবাদদাতা ও ভীতি প্রদর্শক আগমন করেননি। অতএব, তোমাদের কাছে সুসংবাদদাতা ও ভয় প্রদর্শক এসে গেছেন। আল্লাহ সবকিছুর উপর শক্তিমান।'),
  ('bn.bengali', 5, 20, 'যখন মূসা স্বীয় সম্প্রদায়কে বললেনঃ হে আমার সম্প্রদায়, তোমাদের প্রতি আল্লাহর নেয়ামত স্মরণ কর, যখন তিনি তোমাদের মধ্যে পয়গম্বর সৃষ্টি করেছেন, তোমাদেরকে রাজ্যাধিপতি করেছেন এবং তোমাদেরকে এমন জিনিস দিয়েছেন, যা বিশ্বজগতের কাউকে দেননি।'),
  ('bn.bengali', 5, 21, 'হে আমার সম্প্রদায়, পবিত্র ভুমিতে প্রবেশ কর, যা আল্লাহ তোমাদের জন্যে নির্ধারিত করে দিয়েছেন এবং পেছন দিকে প্রত্যাবর্তন করো না। অন্যথায় তোমরা ক্ষতিগ্রস্ত হয়ে পড়বে।'),
  ('bn.bengali', 5, 22, 'তারা বললঃ হে মূসা, সেখানে একটি প্রবল পরাক্রান্ত জাতি রয়েছে। আমরা কখনও সেখানে যাব না, যে পর্যন্ত না তারা সেখান থেকে বের হয়ে যায়। তারা যদি সেখান থেকে বের হয়ে যায় তবে নিশ্চিতই আমরা প্রবেশ করব।’'),
  ('bn.bengali', 5, 23, 'খোদাভীরুদের মধ্য থেকে দু’ব্যক্তি বলল, যাদের প্রতি আল্লাহ অনুগ্রহ করেছিলেনঃ তোমরা তাদের উপর আক্রমণ করে দরজায় প্রবেশ কর। অতঃপর তোমরা যখন তাতে পবেশ করবে, তখন তোমরাই জয়ী হবে। আর আল্লাহর উপর ভরসা কর যদি তোমরা বিশ্বাসী হও।'),
  ('bn.bengali', 5, 24, 'তারা বললঃ হে মূসা, আমরা জীবনেও কখনো সেখানে যাব না, যতক্ষণ তারা সেখানে থাকবে। অতএব, আপনি ও আপনার পালনকর্তাই যান এবং উভয়ে যুদ্ধ করে নিন। আমরা তো এখানেই বসলাম।'),
  ('bn.bengali', 5, 25, 'মূসা বললঃ হে আমার পালনকর্তা, আমি শুধু নিজের উপর ও নিজের ভাইয়ের উপর ক্ষমতা রাখি। অতএব, আপনি আমাদের মধ্যে ও এ অবাধ্য সম্প্রদায়ের মধ্যে সম্পর্কচ্ছেদ করুন।'),
  ('bn.bengali', 5, 26, 'বললেনঃ এ দেশ চল্লিশ বছর পর্যন্ত তাদের জন্যে হারাম করা হল। তারা ভুপৃষ্ঠে উদভ্রান্ত হয়ে ফিরবে। অতএব, আপনি অবাধ্য সম্প্রদায়ের জন্যে দুঃখ করবেন না।'),
  ('bn.bengali', 5, 27, 'আপনি তাদেরকে আদমের দুই পুত্রের বাস্তব অবস্থা পাঠ করে শুনান। যখন তারা ভয়েই কিছু উৎসর্গ নিবেদন করেছিল, তখন তাদের একজনের উৎসর্গ গৃহীত হয়েছিল এবং অপরজনের গৃহীত হয়নি। সে বললঃ আমি অবশ্যই তোমাকে হত্যা করব। সে বললঃ আল্লাহ ধর্মভীরুদের পক্ষ থেকেই তো গ্রহণ করেন।'),
  ('bn.bengali', 5, 28, 'যদি তুমি আমাকে হত্যা করতে আমার দিকে হস্ত প্রসারিত কর, তবে আমি তোমাকে হত্যা করতে তোমার দিকে হস্ত প্রসারিত করব না। কেননা, আমি বিশ্বজগতের পালনকর্তা আল্লাহকে ভয় করি।'),
  ('bn.bengali', 5, 29, 'আমি চাই যে, আমার পাপ ও তোমার পাপ তুমি নিজের মাথায় চাপিয়ে নাও। অতঃপর তুমি দোযখীদের অন্তর্ভূক্ত হয়ে যাও। এটাই অত্যাচারীদের শাস্তি।'),
  ('bn.bengali', 5, 30, 'অতঃপর তার অন্তর তাকে ভ্রাতৃহত্যায় উদুদ্ধ করল। অনন্তর সে তাকে হত্যা করল। ফলে সে ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হয়ে গেল।'),
  ('bn.bengali', 5, 31, 'আল্লাহ এক কাক প্রেরণ করলেন। সে মাটি খনন করছিল যাতে তাকে শিক্ষা দেয় যে, আপন ভ্রাতার মৃতদেহ কিভাবে আবৃত করবে। সে বললঃ আফসোস, আমি কি এ কাকের সমতুল্যও হতে পারলাম না যে, আপন ভ্রাতার মৃতদেহ আবৃত করি। অতঃপর সে অনুতাপ করতে লাগল।'),
  ('bn.bengali', 5, 32, 'এ কারণেই আমি বনী-ইসলাঈলের প্রতি লিখে দিয়েছি যে, যে কেউ প্রাণের বিনিময়ে প্রাণ অথবাপৃথিবীতে অনর্থ সৃষ্টি করা ছাড়া কাউকে হত্যা করে সে যেন সব মানুষকেই হত্যা করে। এবং যে কারও জীবন রক্ষা করে, সে যেন সবার জীবন রক্ষা করে। তাদের কাছে আমার পয়গম্বরগণ প্রকাশ্য নিদর্শনাবলী নিয়ে এসেছেন। বস্তুতঃ এরপরও তাদের অনেক লোক পৃথিবীতে সীমাতিক্রম করে।'),
  ('bn.bengali', 5, 33, 'যারা আল্লাহ ও তাঁর রসূলের সাথে সংগ্রাম করে এবং দেশে হাঙ্গামা সৃষ্টি করতে সচেষ্ট হয়, তাদের শাস্তি হচ্ছে এই যে, তাদেরকে হত্যা করা হবে অথবা শূলীতে চড়ানো হবে অথবা তাদের হস্তপদসমূহ বিপরীত দিক থেকে কেটে দেয়া হবে অথবা দেশ থেকে বহিষ্কার করা হবে। এটি হল তাদের জন্য পার্থিব লাঞ্ছনা আর পরকালে তাদের জন্যে রয়েছে কঠোর শাস্তি।'),
  ('bn.bengali', 5, 34, 'কিন্তু যারা তোমাদের গ্রেফতারের পূর্বে তওবা করে; জেনে রাখ, আল্লাহ ক্ষমাকারী, দয়ালু।'),
  ('bn.bengali', 5, 35, 'হে মুমিনগণ! আল্লাহকে ভয় কর, তাঁর নৈকট্য অন্বেষন কর এবং তাঁর পথে জেহাদ কর যাতে তোমরা সফলকাম হও।'),
  ('bn.bengali', 5, 36, 'যারা কাফের, যদি তাদের কাছে পৃথিবীর সমুদয় সম্পদ এবং তৎসহ আরও তদনুরূপ সম্পদ থাকে আর এগুলো বিনিময়ে দিয়ে কিয়ামতের শাস্তি থেকে পরিত্রান পেতে চায়, তবুও তাদের কাছ থেকে তা কবুল করা হবে না। তাদের জন্যে যন্ত্রনাদায়ক শাস্তি রয়েছে।'),
  ('bn.bengali', 5, 37, 'তারা দোযখের আগুন থেকে বের হয়ে আসতে চাইবে কিন্তু তা থেকে বের হতে পারবে না। তারা চিরস্থায়ী শাস্তি ভোগ করবে।'),
  ('bn.bengali', 5, 38, 'যে পুরুষ চুরি করে এবং যে নারী চুরি করে তাদের হাত কেটে দাও তাদের কৃতকর্মের সাজা হিসেবে। আল্লাহর পক্ষ থেকে হুশিয়ারী। আল্লাহ পরাক্রান্ত, জ্ঞানময়।'),
  ('bn.bengali', 5, 39, 'অতঃপর যে তওবা করে স্বীয় অত্যাচারের পর এবং সংশোধিত হয়, নিশ্চয় আল্লাহ তার তওবা কবুল করেন। নিশ্চয় আল্লাহ ক্ষমাশীল, দয়ালু।'),
  ('bn.bengali', 5, 40, 'তুমি কি জান না যে আল্লাহর নিমিত্তেই নভোমন্ডল ও ভূমন্ডলের আধিপত্য। তিনি যাকে ইচ্ছা শাস্তি দেন এবং যাকে ইচ্ছা ক্ষমা করেন। আল্লাহ সবকিছুর উপর ক্ষমতাবান।'),
  ('bn.bengali', 5, 41, 'হে রসূল, তাদের জন্যে দুঃখ করবেন না, যারা দৌড়ে গিয়ে কুফরে পতিত হয়; যারা মুখে বলেঃ আমরা মুসলমান, অথচ তাদের অন্তর মুসলমান নয় এবং যারা ইহুদী; মিথ্যাবলার জন্যে তারা গুপ্তচর বৃত্তি করে। তারা অন্যদলের গুপ্তচর, যারা আপনার কাছে আসেনি। তারা বাক্যকে স্বস্থান থেকে পরিবর্তন করে। তারা বলেঃ যদি তোমরা এ নির্দেশ পাও, তবে কবুল করে নিও এবং যদি এ নির্দেশ না পাও, তবে বিরত থেকো। আল্লাহ যাকে পথভ্রষ্ট করতে চান, তার জন্যে আল্লাহর কাছে আপনি কিছু করতে পারবেন না। এরা এমনিই যে, আল্লাহ এদের অন্তরকে পবিত্র করতে চান না। তাদের জন্যে রয়েছে দুনিয়াতে লাঞ্ছনা এবং পরকালে বিরাট শাস্তি।'),
  ('bn.bengali', 5, 42, 'এরা মিথ্যা বলার জন্যে গুপ্তচরবৃত্তি করে, হারাম ভক্ষণ করে। অতএব, তারা যদি আপনার কাছে আসে, তবে হয় তাদের মধ্যে ফয়সালা করে দিন, না হয় তাদের ব্যাপারে নির্লিপ্ত থাকুন। যদি তাদের থেকে নির্লিপ্ত থাকেন, তবে তাদের সাধ্য নেই যে, আপনার বিন্দুমাত্র ক্ষতি করতে পারে। যদি ফয়সালা করেন, তবেন্যায় ভাবে ফয়সালা করুন। নিশ্চয় আল্লাহ সুবিচারকারীদেরকে ভালবাসেন।'),
  ('bn.bengali', 5, 43, 'তারা আপনাকে কেমন করে বিচারক নিয়োগ করবে অথচ তাদের কাছে তওরাত রয়েছে। তাতে আল্লাহর নির্দেশ আছে। অতঃপর এরা পেছন দিকে মুখ ফিরিয়ে নেয়। তারা কখনও বিশ্বাসী নয়।'),
  ('bn.bengali', 5, 44, 'আমি তওরাত অবর্তীর্ন করেছি। এতে হেদায়াত ও আলো রয়েছে। আল্লাহর আজ্ঞাবহ পয়গম্বর, দরবেশ ও আলেমরা এর মাধ্যমে ইহুদীদেরকে ফয়সালা দিতেন। কেননা, তাদেরকে এ খোদায়ী গ্রন্থের দেখাশোনা করার নির্দেশ দেয়া হয়েছিল এবং তাঁরা এর রক্ষণাবেক্ষণে নিযুক্ত ছিলেন। অতএব, তোমরা মানুষকে ভয় করো না এবং আমাকে ভয় কর এবং আমার আয়াত সমূহের বিনিময়ে স্বল্পমূল্যে গ্রহণ করো না, যেসব লোক আল্লাহ যা অবতীর্ণ করেছেন, তদনুযায়ী ফায়সালা করে না, তারাই কাফের।'),
  ('bn.bengali', 5, 45, 'আমি এ গ্রন্থে তাদের প্রতি লিখে দিয়েছি যে, প্রাণের বিনিময়ে প্রাণ, চক্ষুর বিনিময়ে চক্ষু, নাকের বিনিময়ে নাক, কানের বিনিময়ে কান, দাঁতের বিনিময়ে দাঁত এবং যখম সমূহের বিনিময়ে সমান যখম। অতঃপর যে ক্ষমা করে, সে গোনাহ থেকে পাক হয়ে যায়। যেসব লোক আল্লাহ যা অবতীর্ণ করেছেন, তদনুযায়ী ফয়সালা করে না তারাই জালেম।'),
  ('bn.bengali', 5, 46, 'আমি তাদের পেছনে মরিয়ম তনয় ঈসাকে প্রেরণ করেছি। তিনি পূর্ববর্তী গ্রন্থ তওরাতের সত্যায়নকারী ছিলেন। আমি তাঁকে ইঞ্জিল প্রদান করেছি। এতে হেদায়াত ও আলো রয়েছে। এটি পূর্ববতী গ্রন্থ তওরাতের সত্যায়ন করে পথ প্রদর্শন করে এবং এটি খোদাভীরুদের জন্যে হেদায়েত উপদেশ বানী।'),
  ('bn.bengali', 5, 47, 'ইঞ্জিলের অধিকারীদের উচিত, আল্লাহ তাতে যা অবতীর্ণ করেছেন। তদানুযায়ী ফয়সালা করা। যারা আল্লাহ যা অবতীর্ণ করেছেন, তদনুযায়ী ফয়সালা করে না, তারাই পাপাচারী।'),
  ('bn.bengali', 5, 48, 'আমি আপনার প্রতি অবতীর্ণ করেছি সত্যগ্রন্থ, যা পূর্ববতী গ্রন্থ সমূহের সত্যায়নকারী এবং সেগুলোর বিষয়বস্তুর রক্ষণাবেক্ষণকারী। অতএব, আপনি তাদের পারস্পারিক ব্যাপারাদিতে আল্লাহ যা অবতীর্ণ করেছেন, তদনুযায়ী ফয়সালা করুন এবং আপনার কাছে যে সৎপথ এসেছে, তা ছেড়ে তাদের প্রবৃত্তির অনুসরণ করবেন না। আমি তোমাদের প্রত্যেককে একটি আইন ও পথ দিয়েছি। যদি আল্লাহ চাইতেন, তবে তোমাদের সবাইকে এক উম্মত করে দিতেন, কিন্তু এরূপ করেননি-যাতে তোমাদেরকে যে ধর্ম দিয়েছেন, তাতে তোমাদের পরীক্ষা নেন। অতএব, দৌড়ে কল্যাণকর বিষয়াদি অর্জন কর। তোমাদের সবাইকে আল্লাহর কাছে প্রত্যাবর্তন করতে হবে। অতঃপর তিনি অবহিত করবেন সে বিষয়, যাতে তোমরা মতবিরোধ করতে।'),
  ('bn.bengali', 5, 49, 'আর আমি আদেশ করছি যে, আপনি তাদের পারস্পরিক ব্যাপারাদিতে আল্লাহ যা নাযিল করেছেন তদনুযায়ী ফয়সালা করুন; তাদের প্রবৃত্তির অনুসরণ করবেন না এবং তাদের থেকে সতর্ক থাকুন-যেন তারা আপনাকে এমন কোন নির্দেশ থেকে বিচ্যুত না করে, যা আল্লাহ আপনার প্রতি নাযিল করেছেন। অনন্তর যদি তার মুখ ফিরিয়ে নেয়, তবে জেনে নিন, আল্লাহ তাদেরকে তাদের গোনাহের কিছু শাস্তি দিতেই চেয়েছেন। মানুষের মধ্যে অনেকেই নাফরমান।'),
  ('bn.bengali', 5, 50, 'তারা কি জাহেলিয়াত আমলের ফয়সালা কামনা করে? আল্লাহ অপেক্ষা বিশ্বাসীদের জন্যে উত্তম ফয়সালাকারী কে?'),
  ('bn.bengali', 5, 51, 'হে মুমিণগণ! তোমরা ইহুদী ও খ্রীষ্টানদেরকে বন্ধু হিসাবে গ্রহণ করো না। তারা একে অপরের বন্ধু। তোমাদের মধ্যে যে তাদের সাথে বন্ধুত্ব করবে, সে তাদেরই অন্তর্ভুক্ত। আল্লাহ জালেমদেরকে পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 5, 52, 'বস্তুতঃ যাদের অন্তরে রোগ রয়েছে, তাদেরকে আপনি দেখবেন, দৌড়ে গিয়ে তাদেরই মধ্যে প্রবেশ করে। তারা বলেঃ আমরা আশঙ্কা করি, পাছে না আমরা কোন দুর্ঘটনায় পতিত হই। অতএব, সেদিন দুরে নয়, যেদিন আল্লাহ তা’আলা বিজয় প্রকাশ করবেন অথবা নিজের পক্ষ থেকে কোন নির্দেশ দেবেন-ফলে তারা স্বীয় গোপন মনোভাবের জন্যে অনুতপ্ত হবে।'),
  ('bn.bengali', 5, 53, 'মুসলমানরা বলবেঃ এরাই কি সেসব লোক, যারা আল্লাহর নামে প্রতিজ্ঞা করত যে, আমরা তোমাদের সাথে আছি? তাদের কৃতকর্মসমূহ বিফল হয়ে গেছে, ফলে তারা ক্ষতিগ্রস্ত হয়ে আছে।'),
  ('bn.bengali', 5, 54, 'হে মুমিনগণ, তোমাদের মধ্যে যে স্বীয় ধর্ম থেকে ফিরে যাবে, অচিরে আল্লাহ এমন সম্প্রদায় সৃষ্টি করবেন, যাদেরকে তিনি ভালবাসবেন এবং তারা তাঁকে ভালবাসবে। তারা মুসলমানদের প্রতি বিনয়-নম্র হবে এবং কাফেরদের প্রতি কঠোর হবে। তারা আল্লাহর পথে জেহাদ করবে এবং কোন তিরস্কারকারীর তিরস্কারে ভীত হবে না। এটি আল্লাহর অনুগ্রহ-তিনি যাকে ইচ্ছা দান করেন। আল্লাহ প্রাচুর্য দানকারী, মহাজ্ঞানী।'),
  ('bn.bengali', 5, 55, 'তোমাদের বন্ধু তো আল্লাহ তাঁর রসূল এবং মুমিনবৃন্দ-যারা নামায কায়েম করে, যাকাত দেয় এবং বিনম্র।'),
  ('bn.bengali', 5, 56, 'আর যারা আল্লাহ তাঁর রসূল এবং বিশ্বাসীদেরকে বন্ধুরূপে গ্রহণ করে, তারাই আল্লাহর দল এবং তারাই বিজয়ী।'),
  ('bn.bengali', 5, 57, 'হে মুমিনগণ, আহলে কিতাবদের মধ্য থেকে যারা তোমাদের ধর্মকে উপহাস ও খেলা মনে করে, তাদেরকে এবং অন্যান্য কাফেরকে বন্ধু রূপে গ্রহণ করো না। আল্লাহকে ভয় কর, যদি তোমরা ঈমানদার হও।'),
  ('bn.bengali', 5, 58, 'আর যখন তোমরা নামাযের জন্যে আহবান কর, তখন তারা একে উপহাস ও খেলা বলে মনে করে। কারণ, তারা নিবোর্ধ।'),
  ('bn.bengali', 5, 59, 'বলুনঃ হে আহলে কিতাবগণ, আমাদের সাথে তোমাদের এছাড়া কি শত্রুতা যে, আমরা বিশ্বাস স্থাপন করেছি আল্লাহর প্রতি, আমাদের উপর অবতীর্ণ গ্রন্থের প্রতি এবং পূর্বে অবতীর্ণ গ্রন্থের প্রতি। আর তোমাদের অধিকাংশই নাফরমান।'),
  ('bn.bengali', 5, 60, 'বলুনঃ আমি তোমাদেরকে বলি, তাদের মধ্যে কার মন্দ প্রতিফল রয়েছে আল্লাহর কাছে? যাদের প্রতি আল্লাহ অভিসম্পাত করেছেন, যাদের প্রতি তিনি ক্রোধাম্বিত হয়েছেন, যাদের কতককে বানর ও শুকরে রূপান্তরিত করে দিয়েছেন এবং যারা শয়তানের আরাধনা করেছে, তারাই মর্যাদার দিক দিয়ে নিকৃষ্টতর এবং সত্যপথ থেকেও অনেক দূরে।'),
  ('bn.bengali', 5, 61, 'যখন তারা তোমাদের কাছে আসে তখন বলে দাওঃ আমরা বিশ্বাস স্থাপন করেছি। অথচ তারা কুফর নিয়ে এসেছিল এবং কুফর নিয়েই প্রস্থান করেছে। তারা যা গোপন করত, আল্লাহ তা খুব জানেন।'),
  ('bn.bengali', 5, 62, 'আর আপনি তাদের অনেককে দেখবেন যে, দৌড়ে দৌড়ে পাপে, সীমালঙ্ঘনে এবং হারাম ভক্ষনে পতিত হয়। তারা অত্যন্ত মন্দ কাজ করছে।'),
  ('bn.bengali', 5, 63, 'দরবেশ ও আলেমরা কেন তাদেরকে পাপ কথা বলতে এবং হারাম ভক্ষণ করতে নিষেধ করে না? তারা খুবই মন্দ কাজ করছে।'),
  ('bn.bengali', 5, 64, 'আর ইহুদীরা বলেঃ আল্লাহর হাত বন্ধ হয়ে গেছে। তাদেরই হাত বন্ধ হোক। একথা বলার জন্যে তাদের প্রতি অভিসম্পাত। বরং তাঁর উভয় হস্ত উম্মুক্ত। তিনি যেরূপ ইচ্ছা ব্যয় করেন। আপনার প্রতি পলনকর্তার পক্ষ থেকে যে কালাম অবর্তীণ হয়েছে, তার কারণে তাদের অনেকের অবাধ্যতা ও কুফর পরিবর্ধিত হবে। আমি তাদের পরস্পরের মধ্যে কেয়ামত পর্যন্ত শত্রুতা ও বিদ্বেষ সঞ্চারিত করে দিয়েছি। তারা যখনই যুদ্ধের আগুন প্রজ্জ?482;িত করে, আল্লাহ তা নির্বাপিত করে দেন। তারা দেশে অশান্তি উৎপাদন করে বেড়ায়। আল্লাহ অশান্তি ও বিশৃঙ্খলা সৃষ্টিকারীদেরকে পছন্দ করেন না।'),
  ('bn.bengali', 5, 65, 'আর যদি আহলে-কিতাবরা বিশ্বাস স্থাপন করত এবং খোদাভীতি অবলম্বন করত, তবে আমি তাদের মন্দ বিষয়সমূহ ক্ষমা করে দিতাম এবং তাদেরকে নেয়ামতের উদ্যানসমূহে প্রবিষ্ট করতাম।'),
  ('bn.bengali', 5, 66, 'যদি তারা তওরাত, ইঞ্জিল এবং যা প্রতিপালকের পক্ষ থেকে তাদের প্রতি অবতীর্ণ হয়েছে, পুরোপুরি পালন করত, তবে তারা উপর থেকে এবং পায়ের নীচ থেকে ভক্ষণ করত। তাদের কিছুসংখ্যক লোক সৎপথের অনুগামী এবং অনেকেই মন্দ কাজ করে যাচ্ছে।'),
  ('bn.bengali', 5, 67, 'হে রসূল, পৌছে দিন আপনার প্রতিপালকের পক্ষ থেকে আপনার প্রতি যা অবতীর্ণ হয়েছে। আর যদি আপনি এরূপ না করেন, তবে আপনি তাঁর পয়গাম কিছুই পৌছালেন না। আল্লাহ আপনাকে মানুষের কাছ থেকে রক্ষা করবেন। নিশ্চয় আল্লাহ কাফেরদেরকে পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 5, 68, 'বলে দিনঃ হে আহলে কিতাবগণ, তোমরা কোন পথেই নও, যে পর্যন্ত না তোমরা তওরাত, ইঞ্জিল এবং যে গ্রন্থ তোমাদের পালনকর্তার পক্ষ থেকে তোমাদের প্রতি অবতীর্ণ হয়েছে তাও পুরোপুরি পালন না কর। আপনার পালনকর্তার কাছ থেকে আপনার প্রতি যা অবর্তীণ হয়েছে, তার কারণে তাদের অনেকের অবাধ্যতা ও কুফর বৃদ্ধি পাবে। অতএব, এ কাফের সম্প্রদায়ের জন্যে দুঃখ করবেন না।'),
  ('bn.bengali', 5, 69, 'নিশ্চয় যারা মুসলমান, যারা ইহুদী, ছাবেয়ী বা খ্রীষ্টান, তাদের মধ্যে যারা বিশ্বাস স্থাপন করে আল্লাহর প্রতি, কিয়ামতের প্রতি এবং সৎকর্ম সম্পাদন করে, তাদের কোন ভয় নেই এবং তারা দুঃখিত হবে না।'),
  ('bn.bengali', 5, 70, 'আমি বনী-ইসরাঈলের কাছ থেকে অঙ্গীকার নিয়েছিলাম এবং তাদের কাছে অনেক পয়গম্বর প্রেরণ করে ছিলাম। যখনই তাদের কাছে কোন পয়গম্বর এমন নির্দেশ নিয়ে আসত যা তাদের মনে চাইত না, তখন তাদের অনেকের প্রতি তারা মিথ্যারোপ করত এবংঅনেককে হত্যা করে ফেলত।'),
  ('bn.bengali', 5, 71, 'তারা ধারণা করেছে যে, কোন অনিষ্ট হবে না। ফলে তারা আরও অন্ধ ও বধির হয়ে গেল। অতঃপর আল্লাহ তাদের তওবা কবুল করলেন। এরপরও তাদের অধিকাংশই অন্ধ ও বধির হয়ে রইল। আল্লাহ দেখেন তারা যা কিছু করে।'),
  ('bn.bengali', 5, 72, 'তারা কাফের, যারা বলে যে, মরিময়-তনয় মসীহ-ই আল্লাহ; অথচ মসীহ বলেন, হে বণী-ইসরাঈল, তোমরা আল্লাহর এবাদত কর, যিনি আমার পালন কর্তা এবং তোমাদেরও পালনকর্তা। নিশ্চয় যে ব্যক্তি আল্লাহর সাথে অংশীদার স্থির করে, আল্লাহ তার জন্যে জান্নাত হারাম করে দেন। এবং তার বাসস্থান হয় জাহান্নাম। অত্যাচারীদের কোন সাহায্যকারী নেই।'),
  ('bn.bengali', 5, 73, 'নিশ্চয় তারা কাফের, যারা বলেঃ আল্লাহ তিনের এক; অথচ এক উপাস্য ছাড়া কোন উপাস্য নেই। যদি তারা স্বীয় উক্তি থেকে নিবৃত্ত না হয়, তবে তাদের মধ্যে যারা কুফরে অটল থাকবে, তাদের উপর যন্ত্রনাদায়ক শাস্তি পতিত হবে।'),
  ('bn.bengali', 5, 74, 'তারা আল্লাহর কাছে তওবা করে না কেন এবং ক্ষমা প্রার্থনা করে না কেন? আল্লাহ যে ক্ষমাশীল, দয়ালু।'),
  ('bn.bengali', 5, 75, 'মরিয়ম-তনয় মসীহ রসূল ছাড়া আর কিছু নন। তাঁর পূর্বে অনেক রসূল অতিক্রান্ত হয়েছেন আর তার জননী একজন ওলী। তাঁরা উভয়েই খাদ্য ভক্ষণ করতেন। দেখুন, আমি তাদের জন্যে কিরূপ যুক্তি-প্রমাণ বর্ননা করি, আবার দেখুন, তারা উল্টা কোন দিকে যাচেছ।'),
  ('bn.bengali', 5, 76, 'বলে দিনঃ তোমরা কি আল্লাহ ব্যতীত এমন বস্তুর এবাদত কর যে, তোমাদের অপকার বা উপকার করার ক্ষমতা রাখে না? অথচ আল্লাহ সব শুনেন ও জানেন।'),
  ('bn.bengali', 5, 77, 'বলুনঃ হে আহলে কিতাবগন, তোমরা স্বীয় ধর্মে অন্যায় বাড়াবাড়ি করো না এবং এতে ঐ সম্প্রদায়ের প্রবৃত্তির অনুসরণ করো না, যারা পূর্বে পথভ্রষ্ট হয়েছে এবং অনেককে পথভ্রষ্ট করেছে। তারা সরল পথ থেকে বিচ্যুত হয়ে পড়েছে।'),
  ('bn.bengali', 5, 78, 'বনী-ইসলাঈলের মধ্যে যারা কাফের, তাদেরকে দাউদ ও মরিয়মতনয় ঈসার মুখে অভিসম্পাত করা হয়েছে। এটা একারণে যে, তারা অবাধ্যতা করত এবং সীমা লংঘন করত।'),
  ('bn.bengali', 5, 79, 'তারা পরস্পরকে মন্দ কাজে নিষেধ করত না, যা তারা করত। তারা যা করত তা অবশ্যই মন্দ ছিল'),
  ('bn.bengali', 5, 80, 'আপনি তাদের অনেককে দেখবেন, কাফেরদের সাথে বন্ধুত্ব করে। তারা নিজেদের জন্য যা পাঠিয়েছে তা অবশ্যই মন্দ। তা এই যে, তাদের প্রতি আল্লাহ ক্রোধান্বিত হয়েছেন এবং তারা চিরকাল আযাবে থাকবে।'),
  ('bn.bengali', 5, 81, 'যদি তারা আল্লাহর প্রতি ও রসূলের প্রতি অবতীর্ণ বিষয়ের প্রতি বিশ্বাস স্থাপন করত, তবে কাফেরদেরকে বন্ধুরূপে গ্রহণ করত না। কিন্তু তাদের মধ্যে অনেকেই দুরাচার।'),
  ('bn.bengali', 5, 82, 'আপনি সব মানুষের চাইতে মুসলমানদের অধিক শত্রু ইহুদী ও মুশরেকদেরকে পাবেন এবং আপনি সবার চাইতে মুসলমানদের সাথে বন্ধুত্বে অধিক নিকটবর্তী তাদেরকে পাবেন, যারা নিজেদেরকে খ্রীষ্টান বলে। এর কারণ এই যে, খ্রীষ্টানদের মধ্যে আলেম রয়েছে, দরবেশ রয়েছে এবং তারা অহঙ্কার করে না।'),
  ('bn.bengali', 5, 83, 'আর তারা রসূলের প্রতি যা অবতীর্ণ হয়েছে, তা যখন শুনে, তখন আপনি তাদের চোখ অশ্রু সজল দেখতে পাবেন; এ কারণে যে, তারা সত্যকে চিনে নিয়েছে। তারা বলেঃ হে আমাদের প্রতি পালক, আমরা মুসলমান হয়ে গেলাম। অতএব, আমাদেরকেও মান্যকারীদের তালিকাভুক্ত করে নিন।'),
  ('bn.bengali', 5, 84, 'আমাদের কি ওযর থাকতে পারে যে, আমরা আল্লাহর প্রতি এবং যে সত্য আমাদের কাছে এসেছে, তৎপ্রতি বিশ্বাস স্থাপন করব না এবং এ আশা করবো না যে, আমদের প্রতিপালক আমাদেরকে সৎ লোকদের সাথে প্রবিষ্ট করবেন?'),
  ('bn.bengali', 5, 85, 'অতঃপর তাদেরকে আল্লাহ এ উক্তির প্রতিদান স্বরূপ এমন উদ্যান দিবেন যার তলদেশে নির্ঝরিণীসমূহ প্রবাহিত হবে। তারা তন্মধ্যে চিরকাল অবস্থান করবে। এটাই সৎকর্মশীলদের প্রতিদান।'),
  ('bn.bengali', 5, 86, 'যারা কাফের হয়েছে এবং আমার নিদর্শনাবলীকে মিথ্যা বলেছে, তারাই দোযখী।'),
  ('bn.bengali', 5, 87, 'হে মুমিনগণ, তোমরা ঐসব সুস্বাদু বস্তু হারাম করো না, যেগুলো আল্লাহ তোমাদের জন্য হালাল করেছেন এবং সীমা অতিক্রম করো না। নিশ্চয় আল্লাহ সীমা অতিক্রমকারীদেরকে পছন্দ করেন না।'),
  ('bn.bengali', 5, 88, 'আল্লাহ তা’য়ালা যেসব বস্তু তোমাদেরকে দিয়েছেন, তন্মধ্য থেকে হালাল ও পবিত্র বস্তু খাও এবং আল্লাহকে ভয় কর, যার প্রতি তোমরা বিশ্বাসী।'),
  ('bn.bengali', 5, 89, 'আল্লাহ তোমাদেরকে পাকড়াও করেন না তোমাদের অনর্থক শপথের জন্যে; কিন্তু পাকড়াও করেন ঐ শপথের জন্যে যা তোমরা মজবুত করে বাধ। অতএব, এর কাফফরা এই যে, দশজন দরিদ্রকে খাদ্য প্রদান করবে; মধ্যম শ্রেনীর খাদ্য যা তোমরা স্বীয় পরিবারকে দিয়ে থাক। অথবা, তাদেরকে বস্তু প্রদান করবে অথবা, একজন ক্রীতদাস কিংবা দাসী মুক্ত করে দিবে। যে ব্যক্তি সামর্থ্য রাখে না, সে তিন দিন রোযা রাখবে। এটা কাফফরা তোমাদের শপথের, যখন শপথ করবে। তোমরা স্বীয় শপথসমূহ রক্ষা কর এমনিভাবে আল্লাহ তোমাদের জন্য স্বীয় নির্দেশ বর্ণনা করেন, যাতে তোমরা কৃতজ্ঞতা স্বীকার কর।'),
  ('bn.bengali', 5, 90, 'হে মুমিনগণ, এই যে মদ, জুয়া, প্রতিমা এবং ভাগ্য-নির্ধারক শরসমূহ এসব শয়তানের অপবিত্র কার্য বৈ তো নয়। অতএব, এগুলো থেকে বেঁচে থাক-যাতে তোমরা কল্যাণপ্রাপ্ত হও।'),
  ('bn.bengali', 5, 91, 'শয়তান তো চায়, মদ ও জুয়ার মাধ্যমে তোমাদের পরস্পরের মাঝে শুত্রুতা ও বিদ্বেষ সঞ্চারিত করে দিতে এবং আল্লাহর স্মরণ ও নামায থেকে তোমাদেরকে বিরত রাখতে। অতএব, তোমরা এখন ও কি নিবৃত্ত হবে?'),
  ('bn.bengali', 5, 92, 'তোমরা আল্লাহর অনুগত হও, রসূলের অনুগত হও এবং আত্মরক্ষা কর। কিন্তু যদি তোমরা বিমুখ হও, তবে জেনে রাখ, আমার রসূলের দায়িত্ব প্রকাশ্য প্রচার বৈধ নয়।'),
  ('bn.bengali', 5, 93, 'যারা বিশ্বাস স্থাপন করেছে এবং সৎকর্ম করেছে, তারা পূর্বে যা ভক্ষণ করেছে, সে জন্য তাদের কোন গোনাহ নেই যখন ভবিষ্যতের জন্যে সংযত হয়েছে, বিশ্বাস স্থাপন করেছে এবং সৎকর্ম সম্পাদন করেছে। এরপর সংযত থাকে এবং বিশ্বাস স্থাপন করে। এরপর সংযত থাকে এবং সৎকর্ম করে। আল্লাহ সৎকর্মীদেরকে ভালবাসেন।'),
  ('bn.bengali', 5, 94, 'হে মুমিনগণ, আল্লাহ তোমাদেরকে এমন কিছু শিকারের মাধ্যমে পরীক্ষা করবেন, যে শিকার পর্যন্ত তোমাদের হাত ও বর্শা সহজেই পৌছতে পারবে-যাতে আল্লাহ বুঝতে পারেন যে, কে তাকে অদৃশ্যভাবে ভয়করে। অতএব, যে ব্যক্তি এরপর সীমা অতিক্রম করবে, তার জন্য যন্ত্রনাদায়ক শাস্তি রয়েছে।'),
  ('bn.bengali', 5, 95, 'মুমিনগণ, তোমরা এহরাম অবস্থায় শিকার বধ করো না। তোমাদের মধ্যে যে জেনেশুনে শিকার বধ করবে, তার উপর বিনিময় ওয়াজেব হবে, যা সমান হবে ঐ জন্তুর, যাকে সে বধ করেছে। দু’জন নির্ভরযোগ্য ব্যক্তি এর ফয়সালা করবে-বিনিময়ের জন্তুটি উৎসর্গ হিসেবে কাবায় পৌছাতে হবে। অথবা তার উপর কাফফারা ওয়াজেব-কয়েকজন দরিদ্রকে খাওয়ানো অথবা তার সমপরিমাণ রোযা রাখতে যাতে সে স্বীয় কৃতকর্মের প্রতিফল আস্বাদন করে। যা হয়ে গেছে, তা আল্লাহ মাফ করেছেন। যে পুনরায় এ কান্ড করবে, আল্লাহ তার কাছ থেকে প্রতিশোধ নিবেন। আল্লাহ পরাক্রান্ত, প্রতিশোধ গ্রহণে সক্ষম।'),
  ('bn.bengali', 5, 96, 'তোমাদের জন্য সমুদ্রের শিকার ও সুমুদ্রের খাদ্য হালাল করা হয়েছে তোমাদের উপকারার্থে এবং তোমাদের এহরামকারীদের জন্যে হারাম করা হয়েছে স্থল শিকার যতক্ষণ এহরাম অবস্থায় থাক। আল্লাহকে ভয় কর, যার কাছে তোমরা একত্রিত হবে।'),
  ('bn.bengali', 5, 97, 'আল্লাহ সম্মানিত গৃহ কাবাকে মানুষের স্থীতিশীলতার কারণ করেছেন এবং সম্মানিত মাসসমূকে, হারাম কোরবানীর জন্তুকে ও যাদের গলায় আবরণ রয়েছে। এর কারণ এই যে, যাতে তোমরা জেনে নাও যে, আল্লাহ নভোমন্ডল ও ভুমন্ডলের সব কিছু জানেন এবং আল্লাহ সর্ব বিষয়ে মহাজ্ঞানী।'),
  ('bn.bengali', 5, 98, 'জেনে নাও, নিশ্চয় আল্লাহ কঠোর শাস্তি দাতা ও নিশ্চয় আল্লাহ ক্ষমাশীল-দয়ালূ।'),
  ('bn.bengali', 5, 99, 'রসূলের দায়িত্ব শুধু পৌছিয়ে দেওয়া। আল্লাহ জানেন, যা কিছু তোমরা প্রকাশ্যে কর এবং যা কিছু গোপন কর।'),
  ('bn.bengali', 5, 100, 'বলে দিনঃ অপবিত্র ও পবিত্র সমান নয়, যদিও অপবিত্রের প্রাচুর্য তোমাকে বিস্মিত করে। অতএব, হে বুদ্ধিমানগণ, আল্লাহকে ভয় কর-যাতে তোমরা মুক্তি পাও।'),
  ('bn.bengali', 5, 101, 'হে মুমিণগন, এমন কথাবার্তা জিজ্ঞেস করো না, যা তোমাদের কাছে পরিব্যক্ত হলে তোমাদের খারাপ লাগবে। যদি কোরআন অবতরণকালে তোমরা এসব বিষয় জিজ্ঞেস কর, তবে তা তোমাদের জন্যে প্রকাশ করা হবে। অতীত বিষয় আল্লাহ ক্ষমা করেছেন আল্লাহ ক্ষমাশীল, সহনশীল।'),
  ('bn.bengali', 5, 102, 'এরূপ কথা বার্তা তোমাদের পুর্বে এক সম্প্রদায় জিজ্ঞেস করেছিল। এর পর তারা এসব বিষয়ে অবিশ্বাসী হয়ে গেল।'),
  ('bn.bengali', 5, 103, 'আল্লাহ ‘বহিরা’ ‘সায়েবা’ ওসীলা’ এবং ‘হামী’ কে শরীয়তসিদ্ধ করেননি। কিন্তু যারা কাফের, তারা আল্লাহর উপর মিথ্যা অপবাদ আরোপ করে। তাদের অধিকাংশেরই বিবেক বুদ্ধি নেই।'),
  ('bn.bengali', 5, 104, 'যখন তাদেরকে বলা হয় যে, আল্লাহর নাযিলকৃত বিধান এবং রসূলের দিকে এস, তখন তারা বলে, আমাদের জন্যে তাই যথেষ্ট, যার উপর আমরা আমাদের বাপ-দাদাকে পেয়েছি। যদি তাদের বাপ দাদারা কোন জ্ঞান না রাখে এবং হেদায়েত প্রাপ্ত না হয় তবুও কি তারা তাই করবে?'),
  ('bn.bengali', 5, 105, 'হে মুমিনগণ, তোমরা নিজেদের চিন্তা কর। তোমরা যখন সৎপথে রয়েছ, তখন কেউ পথভ্রান্ত হলে তাতে তোমাদের কোন ক্ষতি নাই। তোমাদের সবাইকে আল্লাহর কাছে ফিরে যেতে হবে। তখন তিনি তোমাদেরকে বলে দেবেন, যা কিছু তোমরা করতে।'),
  ('bn.bengali', 5, 106, 'হে, মুমিনগণ, তোমাদের মধ্যে যখন কারও মৃত্যু উপস্থিত হয়, তখন ওছিয়ত করার সময় তোমাদের মধ্য থেকে ধর্মপরায়ন দুজনকে সাক্ষী রেখো। তোমরা সফরে থাকলে এবং সে অবস্থায় তোমাদের মৃত্যু উপস্থিত হলে তোমরা তোমাদের ছাড়াও দু ব্যক্তিকে সাক্ষী রেখো। যদি তোমাদের সন্দেহ হয়, তবে উভয়কে নামাযের পর থাকতে বলবে। অতঃপর উভয়েই আল্লাহর নামে কসম খাবে যে, আমরা এ কসমের বিনিময়ে কোন উপকার গ্রহণ করতে চাই না, যদিও কোন আত্নীয়ও হয় এবং আল্লাহর সাক্ষ্য আমরা গোপন করব না। এমতাবস্থায় কঠোর গোনাহগার হব।'),
  ('bn.bengali', 5, 107, 'অতঃপর যদি জানা যায় যে, উভয় ওসি কোন গোনাহে জড়িত রয়েছে, তবে যাদের বিরুদ্ধে গোনাহ হয়েছিল, তাদের মধ্য থেকে মৃতু ব্যক্তির নিকটতম দু’ব্যক্তি তাদের স্থলাভিষিক্ত হবে। অতঃপর আল্লাহর নামে কসম খাবে যে, অবশ্যই আমাদের সাক্ষ্য তাদের সাক্ষ্যর চাইতে অধিক সত্য এবং আমরা সীমা অতিক্রম করিনি। এমতাবস্থায় আমরা অবশ্যই অত্যাচারী হব।'),
  ('bn.bengali', 5, 108, 'এটি এ বিষয়ের নিকটতম উপায় যে, তারা ঘটনাকে সঠিকভাবে প্রকাশ করবে অথবা আশঙ্কা করবে যে, তাদের কাছ থেকে কসম নেয়ার পর আবার কসম চাওয়া হবে। আল্লাহকে ভয় কর এবং শুন, আল্লাহ দুরাচারীদেরকে পথ-প্রদর্শন করবেন না।'),
  ('bn.bengali', 5, 109, 'যেদিন আল্লাহ সব পয়গম্বরকে একত্রিত করবেন, অতঃপর বলবেন তোমরা কি উত্তর পেয়েছিলে? তাঁরা বলবেনঃ আমরা অবগত নই, আপনিই অদৃশ্য বিষয়ে মহাজ্ঞানী।'),
  ('bn.bengali', 5, 110, 'যখন আল্লাহ বলবেনঃ হে ঈসা ইবনে মরিয়ম, তোমার প্রতি ও তোমার মাতার প্রতি আমার অনুগ্রহ স্মরণ কর, যখন আমি তোমাকে পবিত্র আত্মার দ্বারা সাহায্য করেছি। তুমি মানুষের সাথে কথা বলতে কোলে থাকতেও এবং পরিণত বয়সেও এবং যখন আমি তোমাকে গ্রন্থ, প্রগাঢ় জ্ঞান, তওরাত ও ইঞ্জিল শিক্ষা দিয়েছি এবং যখন তুমি কাদামাটি দিয়ে পাখীর প্রতিকৃতির মত প্রতিকৃতি নির্মাণ করতে আমার আদেশে, অতঃপর তুমি তাতে ফুঁ দিতে; ফলে তা আমার আদেশে পাখী হয়ে যেত এবং তুমি আমার আদেশে জন্মান্ধ ও কুষ্টরোগীকে নিরাময় করে দিতে এবং যখন আমি বনী-ইসরাঈলকে তোমা থেকে নিবৃত্ত রেখেছিলাম, যখন তুমি তাদের কাছে প্রমাণাদি নিয়ে এসেছিলে, অতঃপর তাদের মধ্যে যারা কাফের ছিল, তারা বললঃ এটা প্রকাশ্য জাদু ছাড়া কিছুই নয়।'),
  ('bn.bengali', 5, 111, 'আর যখন আমি হাওয়ারীদের মনে জাগ্রত করলাম যে, আমার প্রতি এবং আমার রসূলের প্রতি বিশ্বাস স্থাপন কর, তখন তারা বলতে লাগল, আমরা বিশ্বাস স্থাপন করলাম এবং আপনি সাক্ষী থাকুন যে, আমরা অনুগত্যশীল।'),
  ('bn.bengali', 5, 112, 'যখন হাওয়ারীরা বললঃ হে মরিয়ম তনয় ঈসা, আপনার পালনকর্তা কি এরূপ করতে পারেন যে, আমাদের জন্যে আকাশ থেকে খাদ্যভর্তি খাঞ্চা অবতরণ করে দেবেন? তিনি বললেনঃ যদি তোমরা ঈমানদার হও, তবে আল্লাহকে ভয় কর।'),
  ('bn.bengali', 5, 113, 'তারা বললঃ আমরা তা থেকে খেতে চাই; আমাদের অন্তর পরিতৃপ্ত হবে; আমরা জেনে নেব যে, আপনি সত্য বলেছেন এবং আমরা সাক্ষ্যদাতা হয়ে যাব।'),
  ('bn.bengali', 5, 114, 'ঈসা ইবনে মরিয়ম বললেনঃ হে আল্লাহ আমাদের পালনকর্তা আমাদের প্রতি আকাশ থেকে খাদ্যভর্তি খাঞ্চা অবতরণ করুন। তা আমাদের জন্যে অর্থাৎ, আমাদের প্রথম ও পরবর্তী সবার জন্যে আনন্দোৎসব হবে এবং আপনার পক্ষ থেকে একটি নিদর্শন হবে। আপনি আমাদের রুযী দিন। আপনিই শ্রেষ্ট রুযীদাতা।'),
  ('bn.bengali', 5, 115, 'আল্লাহ বললেনঃ নিশ্চয় আমি সে খাঞ্চা তোমাদের প্রতি অবতরণ করব। অতঃপর যে ব্যাক্তি এর পরেও অকৃতজ্ঞ হবে, আমি তাকে এমন শাস্তি দেব, যে শাস্তি বিশ্বজগতের অপর কাউকে দেব না।'),
  ('bn.bengali', 5, 116, 'যখন আল্লাহ বললেনঃ হে ঈসা ইবনে মরিয়ম! তুমি কি লোকদেরকে বলে দিয়েছিলে যে, আল্লাহকে ছেড়ে আমাকে ও আমার মাতাকে উপাস্য সাব্যস্ত কর? ঈসা বলবেন; আপনি পবিত্র! আমার জন্যে শোভা পায় না যে, আমি এমন কথা বলি, যা বলার কোন অধিকার আমার নেই। যদি আমি বলে থাকি, তবে আপনি অবশ্যই পরিজ্ঞাত; আপনি তো আমার মনের কথা ও জানেন এবং আমি জানি না যা আপনার মনে আছে। নিশ্চয় আপনিই অদৃশ্য বিষয়ে জ্ঞাত।'),
  ('bn.bengali', 5, 117, 'আমি তো তাদেরকে কিছুই বলিনি, শুধু সে কথাই বলেছি যা আপনি বলতে আদেশ করেছিলেন যে, তোমরা আল্লাহর দাসত্ব অবলম্বন কর যিনি আমার ও তোমাদের পালনকর্তা আমি তাদের সম্পর্কে অবগত ছিলাম যতদিন তাদের মধ্যে ছিলাম। অতঃপর যখন আপনি আমাকে লোকান্তরিত করলেন, তখন থেকে আপনিই তাদের সম্পর্কে অবগত রয়েছেন। আপনি সর্ববিষয়ে পূর্ণ পরিজ্ঞাত।'),
  ('bn.bengali', 5, 118, 'যদি আপনি তাদেরকে শাস্তি দেন, তবে তারা আপনার দাস এবং যদি আপনি তাদেরকে ক্ষমা করেন, তবে আপনিই পরাক্রান্ত, মহাবিজ্ঞ।'),
  ('bn.bengali', 5, 119, 'আল্লাহ বললেনঃ আজকের দিনে সত্যবাদীদের সত্যবাদিতা তাদের উপকারে আসবে। তাদের জন্যে উদ্যান রয়েছে, যার তলদেশে নির্ঝরিনী প্রবাহিত হবে; তারা তাতেই চিরকাল থাকবে। আল্লাহ তাদের প্রতি সন্তুষ্ট। এটিই মহান সফলতা।'),
  ('bn.bengali', 5, 120, 'নভোমন্ডল, ভূমন্ডল এবং এতদুভয়ে অবস্থিত সবকিছুর আধিপত্য আল্লাহরই। তিনি সবকিছুর উপর ক্ষমতাবান।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 5, 1, 'O ye who believe! Fulfil your indentures. The beast of cattle is made lawful unto you (for food) except that which is announced unto you (herein), game being unlawful when ye are on the pilgrimage. Lo! Allah ordaineth that which pleaseth Him.'),
  ('en.pickthall', 5, 2, 'O ye who believe! Profane not Allah\'s monuments nor the Sacred Month nor the offerings nor the garlands, nor those repairing to the Sacred House, seeking the grace and pleasure of their Lord. But when ye have left the sacred territory, then go hunting (if ye will). And let not your hatred of a folk who (once) stopped your going to the inviolable place of worship seduce you to transgress; but help ye one another unto righteousness and pious duty. Help not one another unto sin and transgression, but keep your duty to Allah. Lo! Allah is severe in punishment.'),
  ('en.pickthall', 5, 3, 'Forbidden unto you (for food) are carrion and blood and swineflesh, and that which hath been dedicated unto any other than Allah, and the strangled, and the dead through beating, and the dead through falling from a height, and that which hath been killed by (the goring of) horns, and the devoured of wild beasts, saving that which ye make lawful (by the death-stroke), and that which hath been immolated unto idols. And (forbidden is it) that ye swear by the divining arrows. This is an abomination. This day are those who disbelieve in despair of (ever harming) your religion; so fear them not, fear Me! This day have I perfected your religion for you and completed My favour unto you, and have chosen for you as religion al-Islam. Whoso is forced by hunger, not by will, to sin: (for him) lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 5, 4, 'They ask thee (O Muhammad) what is made lawful for them. Say: (all) good things are made lawful for you. And those beasts and birds of prey which ye have trained as hounds are trained, ye teach them that which Allah taught you; so eat of that which they catch for you and mention Allah\'s name upon it, and observe your duty to Allah. Lo! Allah is swift to take account.'),
  ('en.pickthall', 5, 5, 'This day are (all) good things made lawful for you. The food of those who have received the Scripture is lawful for you, and your food is lawful for them. And so are the virtuous women of the believers and the virtuous women of those who received the Scripture before you (lawful for you) when ye give them their marriage portions and live with them in honour, not in fornication, nor taking them as secret concubines. Whoso denieth the faith, his work is vain and he will be among the losers in the Hereafter.'),
  ('en.pickthall', 5, 6, 'O ye who believe! When ye rise up for prayer, wash you faces, and your hands up to the elbows, and lightly rub your heads and (wash) your feet up to the ankles. And if ye are unclean, purify yourselves. And if ye are sick or on a journey, or one of you cometh from the closet, or ye have had contact with women, and ye find not water, then go to clean, high ground and rub your faces and your hands with some of it. Allah would not place a burden on you, but He would purify you and would perfect His grace upon you, that ye may give thanks.'),
  ('en.pickthall', 5, 7, 'Remember Allah\'s grace upon you and His covenant by which He bound you when ye said: We hear and we obey; And keep your duty to Allah. Lo! He knoweth what is in the breasts (of men).'),
  ('en.pickthall', 5, 8, 'O ye who believe! Be steadfast witnesses for Allah in equity, and let not hatred of any people seduce you that ye deal not justly. Deal justly, that is nearer to your duty. Observe your duty to Allah. Lo! Allah is Informed of what ye do.'),
  ('en.pickthall', 5, 9, 'Allah hath promised those who believe and do good works: Theirs will be forgiveness and immense reward.'),
  ('en.pickthall', 5, 10, 'And they who disbelieve and deny Our revelations, such are rightful owners of hell.'),
  ('en.pickthall', 5, 11, 'O ye who believe! Remember Allah\'s favour unto you, how a people were minded to stretch out their hands against you but He withheld their hands from you; and keep your duty to Allah. In Allah let believers put their trust.'),
  ('en.pickthall', 5, 12, 'Allah made a covenant of old with the Children of Israel and We raised among them twelve chieftains, and Allah said: Lo! I am with you. If ye establish worship and pay the poor-due, and believe in My messengers and support them, and lend unto Allah a kindly loan, surely I shall remit your sins, and surely I shall bring you into Gardens underneath which rivers flow. Whoso among you disbelieveth after this will go astray from a plain road.'),
  ('en.pickthall', 5, 13, 'And because of their breaking their covenant, We have cursed them and made hard their hearts. They change words from their context and forget a part of that whereof they were admonished. Thou wilt not cease to discover treachery from all save a few of them. But bear with them and pardon them. Lo! Allah loveth the kindly.'),
  ('en.pickthall', 5, 14, 'And with those who say: "Lo! we are Christians," We made a covenant, but they forgot a part of that whereof they were admonished. Therefor We have stirred up enmity and hatred among them till the Day of Resurrection, when Allah will inform them of their handiwork.'),
  ('en.pickthall', 5, 15, 'O People of the Scripture! Now hath Our messenger come unto you, expounding unto you much of that which ye used to hide in the Scripture, and forgiving much. now hath come unto you light from Allah and plain Scripture,'),
  ('en.pickthall', 5, 16, 'Whereby Allah guideth him who seeketh His good pleasure unto paths of peace. He bringeth them out of darkness unto light by His decree, and guideth them unto a straight path.'),
  ('en.pickthall', 5, 17, 'They indeed have disbelieved who say: Lo! Allah is the Messiah, son of Mary. Say: Who then can do aught against Allah, if He had willed to destroy the Messiah son of Mary, and his mother and everyone on earth? Allah\'s is the Sovereignty of the heavens and the earth and all that is between them. He createth what He will. And Allah is Able to do all things.'),
  ('en.pickthall', 5, 18, 'The Jews and Christians say: We are sons of Allah and His loved ones. Say: Why then doth He chastise you for your sins? Nay, ye are but mortals of His creating. He forgiveth whom He will, and chastiseth whom He will. Allah\'s is the Sovereignty of the heavens and the earth and all that is between them, and unto Him is the journeying.'),
  ('en.pickthall', 5, 19, 'O People of the Scripture! Now hath Our messenger come unto you to make things plain unto you after an interval (of cessation) of the messengers, lest ye should say: There came not unto us a messenger of cheer nor any warner. Now hath a messenger of cheer and a warner come unto you. Allah is Able to do all things.'),
  ('en.pickthall', 5, 20, 'And (remember) when Moses said unto his people: O my people! Remember Allah\'s favour unto you, how He placed among you prophets, and He made you kings, and gave you that (which) He gave not to any (other) of (His) creatures.'),
  ('en.pickthall', 5, 21, 'O my people! Go into the holy land which Allah hath ordained for you. Turn not in flight, for surely ye turn back as losers:'),
  ('en.pickthall', 5, 22, 'They said: O Moses! Lo! a giant people (dwell) therein and lo! we go not in till they go forth from thence. When they go forth from thence, then we will enter (not till then).'),
  ('en.pickthall', 5, 23, 'Then out spake two of those who feared (their Lord, men) unto whom Allah had been gracious: Enter in upon them by the gate, for if ye enter by it, lo! ye will be victorious. So put your trust (in Allah) if ye are indeed believers.'),
  ('en.pickthall', 5, 24, 'They said: O Moses! We will never enter (the land) while they are in it. So go thou and thy Lord and fight! We will sit here.'),
  ('en.pickthall', 5, 25, 'He said: My Lord! I have control of none but myself and my brother, so distinguish between us and the wrong-doing folk.'),
  ('en.pickthall', 5, 26, '(Their Lord) said: For this the land will surely be forbidden them for forty years that they will wander in the earth, bewildered. So grieve not over the wrongdoing folk.'),
  ('en.pickthall', 5, 27, 'But recite unto them with truth the tale of the two sons of Adam, how they offered each a sacrifice, and it was accepted from the one of them and it was not accepted from the other. (The one) said: I will surely kill thee. (The other) answered: Allah accepteth only from those who ward off (evil).'),
  ('en.pickthall', 5, 28, 'Even if thou stretch out thy hand against me to kill me, I shall not stretch out my hand against thee to kill thee, lo! I fear Allah, the Lord of the Worlds.'),
  ('en.pickthall', 5, 29, 'Lo! I would rather thou shouldst bear the punishment of the sin against me and thine own sin and become one of the owners of the fire. That is the reward of evil-doers.'),
  ('en.pickthall', 5, 30, 'But (the other\'s) mind imposed on him the killing of his brother, so he slew him and became one of the losers.'),
  ('en.pickthall', 5, 31, 'Then Allah sent a raven scratching up the ground, to show him how to hide his brother\'s naked corpse. He said: Woe unto me! Am I not able to be as this raven and so hide my brother\'s naked corpse? And he became repentant.'),
  ('en.pickthall', 5, 32, 'For that cause We decreed for the Children of Israel that whosoever killeth a human being for other than manslaughter or corruption in the earth, it shall be as if he had killed all mankind, and whoso saveth the life of one, it shall be as if he had saved the life of all mankind. Our messengers came unto them of old with clear proofs (of Allah\'s Sovereignty), but afterwards lo! many of them became prodigals in the earth.'),
  ('en.pickthall', 5, 33, 'The only reward of those who make war upon Allah and His messenger and strive after corruption in the land will be that they will be killed or crucified, or have their hands and feet on alternate sides cut off, or will be expelled out of the land. Such will be their degradation in the world, and in the Hereafter theirs will be an awful doom;'),
  ('en.pickthall', 5, 34, 'Save those who repent before ye overpower them. For know that Allah is Forgiving, Merciful.'),
  ('en.pickthall', 5, 35, 'O ye who believe! Be mindful of your duty to Allah, and seek the way of approach unto Him, and strive in His way in order that ye may succeed.'),
  ('en.pickthall', 5, 36, 'As for those who disbelieve, lo! if all that is in the earth were theirs, and as much again therewith, to ransom them from the doom on the Day of Resurrection, it would not be accepted from them. Theirs will be a painful doom.'),
  ('en.pickthall', 5, 37, 'They will wish to come forth from the Fire, but they will not come forth from it. Theirs will be a lasting doom.'),
  ('en.pickthall', 5, 38, 'As for the thief, both male and female, cut off their hands. It is the reward of their own deeds, an exemplary punishment from Allah. Allah is Mighty, Wise.'),
  ('en.pickthall', 5, 39, 'But whoso repenteth after his wrongdoing and amendeth, lo! Allah will relent toward him. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 5, 40, 'Knowest thou not that unto Allah belongeth the Sovereignty of the heavens and the earth? He punisheth whom He will, and forgiveth whom He will. Allah is Able to do all things.'),
  ('en.pickthall', 5, 41, 'O Messenger! Let not them grieve thee who vie one with another in the race to disbelief, of such as say with their mouths: "We believe," but their hearts believe not, and of the Jews: listeners for the sake of falsehood, listeners on behalf of other folk who come not unto thee, changing words from their context and saying: If this be given unto you, receive it, but if this be not given unto you, then beware! He whom Allah doometh unto sin, thou (by thine efforts) wilt avail him naught against Allah. Those are they for whom the Will of Allah is that He cleanse not their hearts. Theirs in the world will be ignominy, and in the Hereafter an awful doom;'),
  ('en.pickthall', 5, 42, 'Listeners for the sake of falsehood! Greedy for illicit gain! If then they have recourse unto thee (Muhammad) judge between them or disclaim jurisdiction. If thou disclaimest jurisdiction, then they cannot harm thee at all. But if thou judgest, judge between them with equity. Lo! Allah loveth the equitable.'),
  ('en.pickthall', 5, 43, 'How come they unto thee for judgment when they have the Torah, wherein Allah hath delivered judgment (for them)? Yet even after that they turn away. Such (folk) are not believers.'),
  ('en.pickthall', 5, 44, 'Lo! We did reveal the Torah, wherein is guidance and a light, by which the prophets who surrendered (unto Allah) judged the Jews, and the rabbis and the priests (judged) by such of Allah\'s Scripture as they were bidden to observe, and thereunto were they witnesses. So fear not mankind, but fear Me. And My revelations for a little gain. Whoso judgeth not by that which Allah hath revealed: such are disbelievers.'),
  ('en.pickthall', 5, 45, 'And We prescribed for them therein: The life for the life, and the eye for the eye, and the nose for the nose, and the ear for the ear, and the tooth for the tooth, and for wounds retaliation. But whoso forgoeth it (in the way of charity) it shall be expiation for him. Whoso judgeth not by that which Allah hath revealed: such are wrong-doers.'),
  ('en.pickthall', 5, 46, 'And We caused Jesus, son of Mary, to follow in their footsteps, confirming that which was (revealed) before him in the Torah, and We bestowed on him the Gospel wherein is guidance and a light, confirming that which was (revealed) before it in the Torah - a guidance and an admonition unto those who ward off (evil).'),
  ('en.pickthall', 5, 47, 'Let the People of the Gospel judge by that which Allah hath revealed therein. Whoso judgeth not by that which Allah hath revealed: such are evil-livers.'),
  ('en.pickthall', 5, 48, 'And unto thee have We revealed the Scripture with the truth, confirming whatever Scripture was before it, and a watcher over it. So judge between them by that which Allah hath revealed, and follow not their desires away from the truth which hath come unto thee. For each We have appointed a divine law and a traced-out way. Had Allah willed He could have made you one community. But that He may try you by that which He hath given you (He hath made you as ye are). So vie one with another in good works. Unto Allah ye will all return, and He will then inform you of that wherein ye differ.'),
  ('en.pickthall', 5, 49, 'So judge between them by that which Allah hath revealed, and follow not their desires, but beware of them lest they seduce thee from some part of that which Allah hath revealed unto thee. And if they turn away, then know that Allah\'s Will is to smite them for some sin of theirs. Lo! many of mankind are evil-livers.'),
  ('en.pickthall', 5, 50, 'Is it a judgment of the time of (pagan) ignorance that they are seeking? Who is better than Allah for judgment to a people who have certainty (in their belief)?'),
  ('en.pickthall', 5, 51, 'O ye who believe! Take not the Jews and the Christians for friends. They are friends one to another. He among you who taketh them for friends is (one) of them. Lo! Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 5, 52, 'And thou seest those in whose heart is a disease race toward them, saying: We fear lest a change of fortune befall us. And it may happen that Allah will vouchsafe (unto thee) the victory, or a commandment from His presence. Then will they repent them of their secret thoughts.'),
  ('en.pickthall', 5, 53, 'Then will the believers say (unto the people of the Scripture): are these they who swore by Allah their most binding oaths that they were surely with you? Their works have failed, and they have become the losers.'),
  ('en.pickthall', 5, 54, 'O ye who believe! Whoso of you becometh a renegade from his religion, (know that in his stead) Allah will bring a people whom He loveth and who love Him, humble toward believers, stern toward disbelievers, striving in the way of Allah, and fearing not the blame of any blamer. Such is the grace of Allah which He giveth unto whom He will. Allah is All-Embracing, All-Knowing.'),
  ('en.pickthall', 5, 55, 'Your guardian can be only Allah; and His messenger and those who believe, who establish worship and pay the poordue, and bow down (in prayer).'),
  ('en.pickthall', 5, 56, 'And whoso taketh Allah and His messenger and those who believe for guardian (will know that), lo! the party of Allah, they are the victorious.'),
  ('en.pickthall', 5, 57, 'O Ye who believe! Choose not for guardians such of those who received the Scripture before you, and of the disbelievers, as make a jest and sport of your religion. But keep your duty to Allah if ye are true believers.'),
  ('en.pickthall', 5, 58, 'And when ye call to prayer they take it for a jest and sport. That is because they are a folk who understand not.'),
  ('en.pickthall', 5, 59, 'Say: O People of the Scripture! Do ye blame us for aught else than that we believe in Allah and that which is revealed unto us and that which was revealed aforetime, and because most of you are evil-livers?'),
  ('en.pickthall', 5, 60, 'Shall I tell thee of a worse (case) than theirs for retribution with Allah? (Worse is the case of him) whom Allah hath cursed, him on whom His wrath hath fallen and of whose sort Allah hath turned some to apes and swine, and who serveth idols. Such are in worse plight and further astray from the plain road.'),
  ('en.pickthall', 5, 61, 'When they come unto you (Muslims), they say: We believe; but they came in unbelief and they went out in the same; and Allah knoweth best what they were hiding.'),
  ('en.pickthall', 5, 62, 'And thou seest many of them vying one with another in sin and transgression and their devouring of illicit gain. Verily evil is what they do.'),
  ('en.pickthall', 5, 63, 'Why do not the rabbis and the priests forbid their evil-speaking and their devouring of illicit gain? Verily evil is their handiwork.'),
  ('en.pickthall', 5, 64, 'The Jews say: Allah\'s hand is fettered. Their hands are fettered and they are accursed for saying so. Nay, but both His hands are spread out wide in bounty. He bestoweth as He will. That which hath been revealed unto thee from thy Lord is certain to increase the contumacy and disbelief of many of them, and We have cast among them enmity and hatred till the Day of Resurrection. As often as they light a fire for war, Allah extinguisheth it. Their effort is for corruption in the land, and Allah loveth not corrupters.'),
  ('en.pickthall', 5, 65, 'If only the People of the Scripture would believe and ward off (evil), surely We should remit their sins from them and surely We should bring them into Gardens of Delight.'),
  ('en.pickthall', 5, 66, 'If they had observed the Torah and the Gospel and that which was revealed unto them from their Lord, they would surely have been nourished from above them and from beneath their feet. Among them there are people who are moderate, but many of them are of evil conduct.'),
  ('en.pickthall', 5, 67, 'O Messenger! Make known that which hath been revealed unto thee from thy Lord, for if thou do it not, thou wilt not have conveyed His message. Allah will protect thee from mankind. Lo! Allah guideth not the disbelieving folk.'),
  ('en.pickthall', 5, 68, 'Say O People of the Scripture! Ye have naught (of guidance) till ye observe the Torah and the Gospel and that which was revealed unto you from your Lord. That which is revealed unto thee (Muhammad) from thy Lord is certain to increase the contumacy and disbelief of many of them. But grieve not for the disbelieving folk.'),
  ('en.pickthall', 5, 69, 'Lo! those who believe, and those who are Jews, and Sabaeans, and Christians - Whosoever believeth in Allah and the Last Day and doeth right - there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 5, 70, 'We made a covenant of old with the Children of Israel and We sent unto them messengers. As often as a messenger came unto them with that which their souls desired not (they became rebellious). Some (of them) they denied and some they slew.'),
  ('en.pickthall', 5, 71, 'They thought no harm would come of it, so they were wilfully blind and deaf. And afterward Allah turned (in mercy) toward them. Now (even after that) are many of them wilfully blind and deaf. Allah is Seer of what they do.'),
  ('en.pickthall', 5, 72, 'They surely disbelieve who say: Lo! Allah is the Messiah, son of Mary. The Messiah (himself) said: O Children of Israel, worship Allah, my Lord and your Lord. Lo! whoso ascribeth partners unto Allah, for him Allah hath forbidden paradise. His abode is the Fire. For evil-doers there will be no helpers.'),
  ('en.pickthall', 5, 73, 'They surely disbelieve who say: Lo! Allah is the third of three; when there is no Allah save the One Allah. If they desist not from so saying a painful doom will fall on those of them who disbelieve.'),
  ('en.pickthall', 5, 74, 'Will they not rather turn unto Allah and seek forgiveness of Him? For Allah is Forgiving, Merciful.'),
  ('en.pickthall', 5, 75, 'The Messiah, son of Mary, was no other than a messenger, messengers (the like of whom) had passed away before him. And his mother was a saintly woman. And they both used to eat (earthly) food. See how We make the revelations clear for them, and see how they are turned away!'),
  ('en.pickthall', 5, 76, 'Say: Serve ye in place of Allah that which possesseth for you neither hurt nor use? Allah it is Who is the Hearer, the Knower.'),
  ('en.pickthall', 5, 77, 'Say: O People of the Scripture! Stress not in your religion other than the truth, and follow not the vain desires of folk who erred of old and led many astray, and erred from a plain road.'),
  ('en.pickthall', 5, 78, 'Those of the Children of Israel who went astray were cursed by the tongue of David, and of Jesus, son of Mary. That was because they rebelled and used to transgress.'),
  ('en.pickthall', 5, 79, 'They restrained not one another from the wickedness they did. Verily evil was that they used to do!'),
  ('en.pickthall', 5, 80, 'Thou seest many of them making friends with those who disbelieve. Surely ill for them is that which they themselves send on before them: that Allah will be wroth with them and in the doom they will abide.'),
  ('en.pickthall', 5, 81, 'If they believed in Allah and the Prophet and that which is revealed unto him, they would not choose them for their friends. But many of them are of evil conduct.'),
  ('en.pickthall', 5, 82, 'Thou wilt find the most vehement of mankind in hostility to those who believe (to be) the Jews and the idolaters. And thou wilt find the nearest of them in affection to those who believe (to be) those who say: Lo! We are Christians. That is because there are among them priests and monks, and because they are not proud.'),
  ('en.pickthall', 5, 83, 'When they listen to that which hath been revealed unto the messengers, thou seest their eyes overflow with tears because of their recognition of the Truth. They say: Our Lord, we believe. Inscribe us as among the witnesses.'),
  ('en.pickthall', 5, 84, 'How should we not believe in Allah and that which hath come unto us of the Truth. And (how should we not) hope that our Lord will bring us in along with righteous folk?'),
  ('en.pickthall', 5, 85, 'Allah hath rewarded them for that their saying - Gardens underneath which rivers flow, wherein they will abide for ever. That is the reward of the good.'),
  ('en.pickthall', 5, 86, 'But those who disbelieve and deny Our revelations, they are owners of hell-fire.'),
  ('en.pickthall', 5, 87, 'O ye who believe! Forbid not the good things which Allah hath made lawful for you, and transgress not, Lo! Allah loveth not transgressors.'),
  ('en.pickthall', 5, 88, 'Eat of that which Allah hath bestowed on you as food lawful and good, and keep your duty to Allah in Whom ye are believers.'),
  ('en.pickthall', 5, 89, 'Allah will not take you to task for that which is unintentional in your oaths, but He will take you to task for the oaths which ye swear in earnest. The expiation thereof is the feeding of ten of the needy with the average of that wherewith ye feed your own folk, or the clothing of them, or the liberation of a slave, and for him who findeth not (the wherewithal to do so) then a three days\' fast. This is the expiation of your oaths when ye have sworn; and keep your oaths. Thus Allah expoundeth unto you His revelations in order that ye may give thanks.'),
  ('en.pickthall', 5, 90, 'O ye who believe! Strong drink and games of chance and idols and divining arrows are only an infamy of Satan\'s handiwork. Leave it aside in order that ye may succeed.'),
  ('en.pickthall', 5, 91, 'Satan seeketh only to cast among you enmity and hatred by means of strong drink and games of chance, and to turn you from remembrance of Allah and from (His) worship. Will ye then have done?'),
  ('en.pickthall', 5, 92, 'Obey Allah and obey the messenger, and beware! But if ye turn away, then know that the duty of Our messenger is only plain conveyance (of the message).'),
  ('en.pickthall', 5, 93, 'There shall be no sin (imputed) unto those who believe and do good works for what they may have eaten (in the past). So be mindful of your duty (to Allah), and believe, and do good works; and again: be mindful of your duty, and believe; and once again: be mindful of your duty, and do right. Allah loveth the good.'),
  ('en.pickthall', 5, 94, 'O ye who believe! Allah will surely try you somewhat (in the matter) of the game which ye take with your hands and your spears, that Allah may know him who feareth Him in secret. Whoso transgresseth after this, for him there is a painful doom.'),
  ('en.pickthall', 5, 95, 'O ye who believe! Kill no wild game while ye are on the pilgrimage. Whoso of you killeth it of set purpose he shall pay its forfeit in the equivalent of that which he hath killed, of domestic animals, the judge to be two men among you known for justice, (the forfeit) to be brought as an offering to the Ka\'bah; or, for expiation, he shall feed poor persons, or the equivalent thereof in fasting, that he may taste the evil consequences of his deed. Allah forgiveth whatever (of this kind) may have happened in the past, but whoso relapseth, Allah will take retribution from him. Allah is Mighty, Able to Requite (the wrong).'),
  ('en.pickthall', 5, 96, 'To hunt and to eat the fish of the sea is made lawful for you, a provision for you and for seafarers; but to hunt on land is forbidden you so long as ye are on the pilgrimage. Be mindful of your duty to Allah, unto Whom ye will be gathered.'),
  ('en.pickthall', 5, 97, 'Allah hath appointed the Ka\'bah, the Sacred House, a standard for mankind, and the Sacred Month and the offerings and the garlands. That is so that ye may know that Allah knoweth whatsoever is in the heavens and whatsoever is in the earth, and that Allah is Knower of all things.'),
  ('en.pickthall', 5, 98, 'Know that Allah is severe in punishment, but that Allah (also) is Forgiving, Merciful.'),
  ('en.pickthall', 5, 99, 'The duty of the messenger is only to convey (the message). Allah knoweth what ye proclaim and what ye hide.'),
  ('en.pickthall', 5, 100, 'Say: The evil and the good are not alike even though the plenty of the evil attract thee. So be mindful of your duty to Allah, O men of understanding, that ye may succeed.'),
  ('en.pickthall', 5, 101, 'O ye who believe! Ask not of things which, if they were made unto you, would trouble you; but if ye ask of them when the Qur\'an is being revealed, they will be made known unto you. Allah pardoneth this, for Allah is Forgiving, Clement.'),
  ('en.pickthall', 5, 102, 'A folk before you asked (for such disclosures) and then disbelieved therein.'),
  ('en.pickthall', 5, 103, 'Allah hath not appointed anything in the nature of a Bahirah or a Sa\'ibah or a Wasilah or a Hami, but those who disbelieve invent a lie against Allah. Most of them have no sense.'),
  ('en.pickthall', 5, 104, 'And when it is said unto them: Come unto that which Allah hath revealed and unto the messenger, they say: Enough for us is that wherein we found our fathers. What! Even though their fathers had no knowledge whatsoever, and no guidance?'),
  ('en.pickthall', 5, 105, 'O ye who believe! Ye have charge of your own souls. He who erreth cannot injure you if ye are rightly guided. Unto Allah ye will all return; and then He will inform you of what ye used to do.'),
  ('en.pickthall', 5, 106, 'O ye who believe! Let there be witnesses between you when death draweth nigh unto one of you, at the time of bequest - two witnesses, just men from among you, or two others from another tribe, in case ye are campaigning in the land and the calamity of death befall you. Ye shall empanel them both after the prayer, and, if ye doubt, they shall be made to swear by Allah (saying): We will not take a bribe, even though it were (on behalf of) a near kinsman nor will we hide the testimony of Allah, for then indeed we should be of the sinful.'),
  ('en.pickthall', 5, 107, 'But then, if it is afterwards ascertained that both of them merit (the suspicion of) sin, let two others take their place of those nearly concerned, and let them swear by Allah, (saying): Verily our testimony is truer than their testimony and we have not transgressed (the bounds of duty), for them indeed we should be of the evil-doers.'),
  ('en.pickthall', 5, 108, 'Thus it is more likely that they will bear true witness or fear that after their oaths the oaths (of others) will be taken. So be mindful of your duty (to Allah) and hearken. Allah guideth not the froward folk.'),
  ('en.pickthall', 5, 109, 'In the day when Allah gathereth together the messengers, and saith: What was your response (from mankind)? they say: We have no knowledge. Lo! Thou, only Thou art the Knower of Things Hidden,'),
  ('en.pickthall', 5, 110, 'When Allah saith: O Jesus, son of Mary! Remember My favour unto thee and unto thy mother; how I strengthened thee with the holy Spirit, so that thou spakest unto mankind in the cradle as in maturity; and how I taught thee the Scripture and Wisdom and the Torah and the Gospel; and how thou didst shape of clay as it were the likeness of a bird by My permission, and didst blow upon it and it was a bird by My permission, and thou didst heal him who was born blind and the leper by My permission; and how thou didst raise the dead by My permission; and how I restrained the Children of Israel from (harming) thee when thou camest unto them with clear proofs, and those of them who disbelieved exclaimed: This is naught else than mere magic;'),
  ('en.pickthall', 5, 111, 'And when I inspired the disciples, (saying): Believe in Me and in My messenger, they said: We believe. Bear witness that we have surrendered (unto Thee) "we are muslims".'),
  ('en.pickthall', 5, 112, 'When the disciples said: O Jesus, son of Mary! Is thy Lord able to send down for us a table spread with food from heaven? He said: Observe your duty to Allah, if ye are true believers.'),
  ('en.pickthall', 5, 113, '(They said:) We wish to eat thereof, that we may satisfy our hearts and know that thou hast spoken truth to us, and that thereof we may be witnesses.'),
  ('en.pickthall', 5, 114, 'Jesus, son of Mary, said: O Allah, Lord of us! Send down for us a table spread with food from heaven, that it may be a feast for us, for the first of us and for the last of us, and a sign from Thee. Give us sustenance, for Thou art the Best of Sustainers.'),
  ('en.pickthall', 5, 115, 'Allah said: Lo! I send it down for you. And whoso disbelieveth of you afterward, him surely will I punish with a punishment wherewith I have not punished any of (My) creatures.'),
  ('en.pickthall', 5, 116, 'And when Allah saith: O Jesus, son of Mary! Didst thou say unto mankind: Take me and my mother for two gods beside Allah? he saith: Be glorified! It was not mine to utter that to which I had no right. If I used to say it, then Thou knewest it. Thou knowest what is in my mind, and I know not what is in Thy Mind. Lo! Thou, only Thou, art the Knower of Things Hidden?'),
  ('en.pickthall', 5, 117, 'I spake unto them only that which Thou commandedst me, (saying): Worship Allah, my Lord and your Lord. I was a witness of them while I dwelt among them, and when Thou tookest me Thou wast the Watcher over them. Thou art Witness over all things.'),
  ('en.pickthall', 5, 118, 'If Thou punish them, lo! they are Thy slaves, and if Thou forgive them (lo! they are Thy slaves). Lo! Thou, only Thou, art the Mighty, the Wise.'),
  ('en.pickthall', 5, 119, 'Allah saith: This is a day in which their truthfulness profiteth the truthful, for theirs are Gardens underneath which rivers flow, wherein they are secure for ever, Allah taking pleasure in them and they in Him. That is the great triumph.'),
  ('en.pickthall', 5, 120, 'Unto Allah belongeth the Sovereignty of the heavens and the earth and whatsoever is therein, and He is Able to do all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 5, 1, 'O ye who believe! fulfil (all) obligations. Lawful unto you (for food) are all four-footed animals, with the exceptions named: But animals of the chase are forbidden while ye are in the sacred precincts or in pilgrim garb: for Allah doth command according to His will and plan.'),
  ('en.yusufali', 5, 2, 'O ye who believe! Violate not the sanctity of the symbols of Allah, nor of the sacred month, nor of the animals brought for sacrifice, nor the garlands that mark out such animals, nor the people resorting to the sacred house, seeking of the bounty and good pleasure of their Lord. But when ye are clear of the sacred precincts and of pilgrim garb, ye may hunt and let not the hatred of some people in (once) shutting you out of the Sacred Mosque lead you to transgression (and hostility on your part). Help ye one another in righteousness and piety, but help ye not one another in sin and rancour: fear Allah: for Allah is strict in punishment.'),
  ('en.yusufali', 5, 3, 'Forbidden to you (for food) are: dead meat, blood, the flesh of swine, and that on which hath been invoked the name of other than Allah; that which hath been killed by strangling, or by a violent blow, or by a headlong fall, or by being gored to death; that which hath been (partly) eaten by a wild animal; unless ye are able to slaughter it (in due form); that which is sacrificed on stone (altars); (forbidden) also is the division (of meat) by raffling with arrows: that is impiety. This day have those who reject faith given up all hope of your religion: yet fear them not but fear Me. This day have I perfected your religion for you, completed My favour upon you, and have chosen for you Islam as your religion. But if any is forced by hunger, with no inclination to transgression, Allah is indeed Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 5, 4, 'They ask thee what is lawful to them (as food). Say: lawful unto you are (all) things good and pure: and what ye have taught your trained hunting animals (to catch) in the manner directed to you by Allah: eat what they catch for you, but pronounce the name of Allah over it: and fear Allah; for Allah is swift in taking account.'),
  ('en.yusufali', 5, 5, 'This day are (all) things good and pure made lawful unto you. The food of the People of the Book is lawful unto you and yours is lawful unto them. (Lawful unto you in marriage) are (not only) chaste women who are believers, but chaste women among the People of the Book, revealed before your time,- when ye give them their due dowers, and desire chastity, not lewdness, nor secret intrigues if any one rejects faith, fruitless is his work, and in the Hereafter he will be in the ranks of those who have lost (all spiritual good).'),
  ('en.yusufali', 5, 6, 'O ye who believe! when ye prepare for prayer, wash your faces, and your hands (and arms) to the elbows; Rub your heads (with water); and (wash) your feet to the ankles. If ye are in a state of ceremonial impurity, bathe your whole body. But if ye are ill, or on a journey, or one of you cometh from offices of nature, or ye have been in contact with women, and ye find no water, then take for yourselves clean sand or earth, and rub therewith your faces and hands, Allah doth not wish to place you in a difficulty, but to make you clean, and to complete his favour to you, that ye may be grateful.'),
  ('en.yusufali', 5, 7, 'And call in remembrance the favour of Allah unto you, and His covenant, which He ratified with you, when ye said: "We hear and we obey": And fear Allah, for Allah knoweth well the secrets of your hearts.'),
  ('en.yusufali', 5, 8, 'O ye who believe! stand out firmly for Allah, as witnesses to fair dealing, and let not the hatred of others to you make you swerve to wrong and depart from justice. Be just: that is next to piety: and fear Allah. For Allah is well-acquainted with all that ye do.'),
  ('en.yusufali', 5, 9, 'To those who believe and do deeds of righteousness hath Allah promised forgiveness and a great reward.'),
  ('en.yusufali', 5, 10, 'Those who reject faith and deny our signs will be companions of Hell-fire.'),
  ('en.yusufali', 5, 11, 'O ye who believe! Call in remembrance the favour of Allah unto you when certain men formed the design to stretch out their hands against you, but (Allah) held back their hands from you: so fear Allah. And on Allah let believers put (all) their trust.'),
  ('en.yusufali', 5, 12, 'Allah did aforetime take a covenant from the Children of Israel, and we appointed twelve captains among them. And Allah said: "I am with you: if ye (but) establish regular prayers, practise regular charity, believe in my messengers, honour and assist them, and loan to Allah a beautiful loan, verily I will wipe out from you your evils, and admit you to gardens with rivers flowing beneath; but if any of you, after this, resisteth faith, he hath truly wandered from the path or rectitude."'),
  ('en.yusufali', 5, 13, 'But because of their breach of their covenant, We cursed them, and made their hearts grow hard; they change the words from their (right) places and forget a good part of the message that was sent them, nor wilt thou cease to find them- barring a few - ever bent on (new) deceits: but forgive them, and overlook (their misdeeds): for Allah loveth those who are kind.'),
  ('en.yusufali', 5, 14, 'From those, too, who call themselves Christians, We did take a covenant, but they forgot a good part of the message that was sent them: so we estranged them, with enmity and hatred between the one and the other, to the day of judgment. And soon will Allah show them what it is they have done.'),
  ('en.yusufali', 5, 15, 'O people of the Book! There hath come to you our Messenger, revealing to you much that ye used to hide in the Book, and passing over much (that is now unnecessary): There hath come to you from Allah a (new) light and a perspicuous Book, -'),
  ('en.yusufali', 5, 16, 'Wherewith Allah guideth all who seek His good pleasure to ways of peace and safety, and leadeth them out of darkness, by His will, unto the light,- guideth them to a path that is straight.'),
  ('en.yusufali', 5, 17, 'In blasphemy indeed are those that say that Allah is Christ the son of Mary. Say: "Who then hath the least power against Allah, if His will were to destroy Christ the son of Mary, his mother, and all every - one that is on the earth? For to Allah belongeth the dominion of the heavens and the earth, and all that is between. He createth what He pleaseth. For Allah hath power over all things."'),
  ('en.yusufali', 5, 18, '(Both) the Jews and the Christians say: "We are sons of Allah, and his beloved." Say: "Why then doth He punish you for your sins? Nay, ye are but men,- of the men he hath created: He forgiveth whom He pleaseth, and He punisheth whom He pleaseth: and to Allah belongeth the dominion of the heavens and the earth, and all that is between: and unto Him is the final goal (of all)"'),
  ('en.yusufali', 5, 19, 'O People of the Book! Now hath come unto you, making (things) clear unto you, Our Messenger, after the break in (the series of) our messengers, lest ye should say: "There came unto us no bringer of glad tidings and no warner (from evil)": But now hath come unto you a bringer of glad tidings and a warner (from evil). And Allah hath power over all things.'),
  ('en.yusufali', 5, 20, 'Remember Moses said to his people: "O my people! Call in remembrance the favour of Allah unto you, when He produced prophets among you, made you kings, and gave you what He had not given to any other among the peoples.'),
  ('en.yusufali', 5, 21, '"O my people! Enter the holy land which Allah hath assigned unto you, and turn not back ignominiously, for then will ye be overthrown, to your own ruin."'),
  ('en.yusufali', 5, 22, 'They said: "O Moses! In this land are a people of exceeding strength: Never shall we enter it until they leave it: if (once) they leave, then shall we enter."'),
  ('en.yusufali', 5, 23, '(But) among (their) Allah-fearing men were two on whom Allah had bestowed His grace: They said: "Assault them at the (proper) Gate: when once ye are in, victory will be yours; But on Allah put your trust if ye have faith."'),
  ('en.yusufali', 5, 24, 'They said: "O Moses! while they remain there, never shall we be able to enter, to the end of time. Go thou, and thy Lord, and fight ye two, while we sit here (and watch)."'),
  ('en.yusufali', 5, 25, 'He said: "O my Lord! I have power only over myself and my brother: so separate us from this rebellious people!"'),
  ('en.yusufali', 5, 26, 'Allah said: "Therefore will the land be out of their reach for forty years: In distraction will they wander through the land: But sorrow thou not over these rebellious people.'),
  ('en.yusufali', 5, 27, 'Recite to them the truth of the story of the two sons of Adam. Behold! they each presented a sacrifice (to Allah): It was accepted from one, but not from the other. Said the latter: "Be sure I will slay thee." "Surely," said the former, "Allah doth accept of the sacrifice of those who are righteous.'),
  ('en.yusufali', 5, 28, '"If thou dost stretch thy hand against me, to slay me, it is not for me to stretch my hand against thee to slay thee: for I do fear Allah, the cherisher of the worlds.'),
  ('en.yusufali', 5, 29, '"For me, I intend to let thee draw on thyself my sin as well as thine, for thou wilt be among the companions of the fire, and that is the reward of those who do wrong."'),
  ('en.yusufali', 5, 30, 'The (selfish) soul of the other led him to the murder of his brother: he murdered him, and became (himself) one of the lost ones.'),
  ('en.yusufali', 5, 31, 'Then Allah sent a raven, who scratched the ground, to show him how to hide the shame of his brother. "Woe is me!" said he; "Was I not even able to be as this raven, and to hide the shame of my brother?" then he became full of regrets-'),
  ('en.yusufali', 5, 32, 'On that account: We ordained for the Children of Israel that if any one slew a person - unless it be for murder or for spreading mischief in the land - it would be as if he slew the whole people: and if any one saved a life, it would be as if he saved the life of the whole people. Then although there came to them Our messengers with clear signs, yet, even after that, many of them continued to commit excesses in the land.'),
  ('en.yusufali', 5, 33, 'The punishment of those who wage war against Allah and His Messenger, and strive with might and main for mischief through the land is: execution, or crucifixion, or the cutting off of hands and feet from opposite sides, or exile from the land: that is their disgrace in this world, and a heavy punishment is theirs in the Hereafter;'),
  ('en.yusufali', 5, 34, 'Except for those who repent before they fall into your power: in that case, know that Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 5, 35, 'O ye who believe! Do your duty to Allah, seek the means of approach unto Him, and strive with might and main in his cause: that ye may prosper.'),
  ('en.yusufali', 5, 36, 'As to those who reject Faith,- if they had everything on earth, and twice repeated, to give as ransom for the penalty of the Day of Judgment, it would never be accepted of them, theirs would be a grievous penalty.'),
  ('en.yusufali', 5, 37, 'Their wish will be to get out of the Fire, but never will they get out therefrom: their penalty will be one that endures.'),
  ('en.yusufali', 5, 38, 'As to the thief, Male or female, cut off his or her hands: a punishment by way of example, from Allah, for their crime: and Allah is Exalted in power.'),
  ('en.yusufali', 5, 39, 'But if the thief repents after his crime, and amends his conduct, Allah turneth to him in forgiveness; for Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 5, 40, 'Knowest thou not that to Allah (alone) belongeth the dominion of the heavens and the earth? He punisheth whom He pleaseth, and He forgiveth whom He pleaseth: and Allah hath power over all things.'),
  ('en.yusufali', 5, 41, 'O Messenger! let not those grieve thee, who race each other into unbelief: (whether it be) among those who say "We believe" with their lips but whose hearts have no faith; or it be among the Jews,- men who will listen to any lie,- will listen even to others who have never so much as come to thee. They change the words from their (right) times and places: they say, "If ye are given this, take it, but if not, beware!" If any one\'s trial is intended by Allah, thou hast no authority in the least for him against Allah. For such - it is not Allah\'s will to purify their hearts. For them there is disgrace in this world, and in the Hereafter a heavy punishment.'),
  ('en.yusufali', 5, 42, '(They are fond of) listening to falsehood, of devouring anything forbidden. If they do come to thee, either judge between them, or decline to interfere. If thou decline, they cannot hurt thee in the least. If thou judge, judge in equity between them. For Allah loveth those who judge in equity.'),
  ('en.yusufali', 5, 43, 'But why do they come to thee for decision, when they have (their own) law before them?- therein is the (plain) command of Allah; yet even after that, they would turn away. For they are not (really) People of Faith.'),
  ('en.yusufali', 5, 44, 'It was We who revealed the law (to Moses): therein was guidance and light. By its standard have been judged the Jews, by the prophets who bowed (as in Islam) to Allah\'s will, by the rabbis and the doctors of law: for to them was entrusted the protection of Allah\'s book, and they were witnesses thereto: therefore fear not men, but fear me, and sell not my signs for a miserable price. If any do fail to judge by (the light of) what Allah hath revealed, they are (no better than) Unbelievers.'),
  ('en.yusufali', 5, 45, 'We ordained therein for them: "Life for life, eye for eye, nose or nose, ear for ear, tooth for tooth, and wounds equal for equal." But if any one remits the retaliation by way of charity, it is an act of atonement for himself. And if any fail to judge by (the light of) what Allah hath revealed, they are (No better than) wrong-doers.'),
  ('en.yusufali', 5, 46, 'And in their footsteps We sent Jesus the son of Mary, confirming the Law that had come before him: We sent him the Gospel: therein was guidance and light, and confirmation of the Law that had come before him: a guidance and an admonition to those who fear Allah.'),
  ('en.yusufali', 5, 47, 'Let the people of the Gospel judge by what Allah hath revealed therein. If any do fail to judge by (the light of) what Allah hath revealed, they are (no better than) those who rebel.'),
  ('en.yusufali', 5, 48, 'To thee We sent the Scripture in truth, confirming the scripture that came before it, and guarding it in safety: so judge between them by what Allah hath revealed, and follow not their vain desires, diverging from the Truth that hath come to thee. To each among you have we prescribed a law and an open way. If Allah had so willed, He would have made you a single people, but (His plan is) to test you in what He hath given you: so strive as in a race in all virtues. The goal of you all is to Allah; it is He that will show you the truth of the matters in which ye dispute;'),
  ('en.yusufali', 5, 49, 'And this (He commands): Judge thou between them by what Allah hath revealed, and follow not their vain desires, but beware of them lest they beguile thee from any of that (teaching) which Allah hath sent down to thee. And if they turn away, be assured that for some of their crime it is Allah\'s purpose to punish them. And truly most men are rebellious.'),
  ('en.yusufali', 5, 50, 'Do they then seek after a judgment of (the days of) ignorance? But who, for a people whose faith is assured, can give better judgment than Allah?'),
  ('en.yusufali', 5, 51, 'O ye who believe! take not the Jews and the Christians for your friends and protectors: They are but friends and protectors to each other. And he amongst you that turns to them (for friendship) is of them. Verily Allah guideth not a people unjust.'),
  ('en.yusufali', 5, 52, 'Those in whose hearts is a disease - thou seest how eagerly they run about amongst them, saying: "We do fear lest a change of fortune bring us disaster." Ah! perhaps Allah will give (thee) victory, or a decision according to His will. Then will they repent of the thoughts which they secretly harboured in their hearts.'),
  ('en.yusufali', 5, 53, 'And those who believe will say: "Are these the men who swore their strongest oaths by Allah, that they were with you?" All that they do will be in vain, and they will fall into (nothing but) ruin.'),
  ('en.yusufali', 5, 54, 'O ye who believe! if any from among you turn back from his Faith, soon will Allah produce a people whom He will love as they will love Him,- lowly with the believers, mighty against the rejecters, fighting in the way of Allah, and never afraid of the reproaches of such as find fault. That is the grace of Allah, which He will bestow on whom He pleaseth. And Allah encompasseth all, and He knoweth all things.'),
  ('en.yusufali', 5, 55, 'Your (real) friends are (no less than) Allah, His Messenger, and the (fellowship of) believers,- those who establish regular prayers and regular charity, and they bow down humbly (in worship).'),
  ('en.yusufali', 5, 56, 'As to those who turn (for friendship) to Allah, His Messenger, and the (fellowship of) believers,- it is the fellowship of Allah that must certainly triumph.'),
  ('en.yusufali', 5, 57, 'O ye who believe! take not for friends and protectors those who take your religion for a mockery or sport,- whether among those who received the Scripture before you, or among those who reject Faith; but fear ye Allah, if ye have faith (indeed).'),
  ('en.yusufali', 5, 58, 'When ye proclaim your call to prayer they take it (but) as mockery and sport; that is because they are a people without understanding.'),
  ('en.yusufali', 5, 59, 'Say: "O people of the Book! Do ye disapprove of us for no other reason than that we believe in Allah, and the revelation that hath come to us and that which came before (us), and (perhaps) that most of you are rebellious and disobedient?"'),
  ('en.yusufali', 5, 60, 'Say: "Shall I point out to you something much worse than this, (as judged) by the treatment it received from Allah? those who incurred the curse of Allah and His wrath, those of whom some He transformed into apes and swine, those who worshipped evil;- these are (many times) worse in rank, and far more astray from the even path!"'),
  ('en.yusufali', 5, 61, 'When they come to thee, they say: "We believe": but in fact they enter with a mind against Faith, and they go out with the same but Allah knoweth fully all that they hide.'),
  ('en.yusufali', 5, 62, 'Many of them dost thou see, racing each other in sin and rancour, and their eating of things forbidden. Evil indeed are the things that they do.'),
  ('en.yusufali', 5, 63, 'Why do not the rabbis and the doctors of Law forbid them from their (habit of) uttering sinful words and eating things forbidden? Evil indeed are their works.'),
  ('en.yusufali', 5, 64, 'The Jews say: "Allah\'s hand is tied up." Be their hands tied up and be they accursed for the (blasphemy) they utter. Nay, both His hands are widely outstretched: He giveth and spendeth (of His bounty) as He pleaseth. But the revelation that cometh to thee from Allah increaseth in most of them their obstinate rebellion and blasphemy. Amongst them we have placed enmity and hatred till the Day of Judgment. Every time they kindle the fire of war, Allah doth extinguish it; but they (ever) strive to do mischief on earth. And Allah loveth not those who do mischief.'),
  ('en.yusufali', 5, 65, 'If only the People of the Book had believed and been righteous, We should indeed have blotted out their iniquities and admitted them to gardens of bliss.'),
  ('en.yusufali', 5, 66, 'If only they had stood fast by the Law, the Gospel, and all the revelation that was sent to them from their Lord, they would have enjoyed happiness from every side. There is from among them a party on the right course: but many of them follow a course that is evil.'),
  ('en.yusufali', 5, 67, 'O Messenger! proclaim the (message) which hath been sent to thee from thy Lord. If thou didst not, thou wouldst not have fulfilled and proclaimed His mission. And Allah will defend thee from men (who mean mischief). For Allah guideth not those who reject Faith.'),
  ('en.yusufali', 5, 68, 'Say: "O People of the Book! ye have no ground to stand upon unless ye stand fast by the Law, the Gospel, and all the revelation that has come to you from your Lord." It is the revelation that cometh to thee from thy Lord, that increaseth in most of them their obstinate rebellion and blasphemy. But sorrow thou not over (these) people without Faith.'),
  ('en.yusufali', 5, 69, 'Those who believe (in the Qur\'an), those who follow the Jewish (scriptures), and the Sabians and the Christians,- any who believe in Allah and the Last Day, and work righteousness,- on them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 5, 70, 'We took the covenant of the Children of Israel and sent them messengers, every time, there came to them a messenger with what they themselves desired not - some (of these) they called impostors, and some they (go so far as to) slay.'),
  ('en.yusufali', 5, 71, 'They thought there would be no trial (or punishment); so they became blind and deaf; yet Allah (in mercy) turned to them; yet again many of them became blind and deaf. But Allah sees well all that they do.'),
  ('en.yusufali', 5, 72, 'They do blaspheme who say: "Allah is Christ the son of Mary." But said Christ: "O Children of Israel! worship Allah, my Lord and your Lord." Whoever joins other gods with Allah,- Allah will forbid him the garden, and the Fire will be his abode. There will for the wrong-doers be no one to help.'),
  ('en.yusufali', 5, 73, 'They do blaspheme who say: Allah is one of three in a Trinity: for there is no god except One Allah. If they desist not from their word (of blasphemy), verily a grievous penalty will befall the blasphemers among them.'),
  ('en.yusufali', 5, 74, 'Why turn they not to Allah, and seek His forgiveness? For Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 5, 75, 'Christ the son of Mary was no more than a messenger; many were the messengers that passed away before him. His mother was a woman of truth. They had both to eat their (daily) food. See how Allah doth make His signs clear to them; yet see in what ways they are deluded away from the truth!'),
  ('en.yusufali', 5, 76, 'Say: "Will ye worship, besides Allah, something which hath no power either to harm or benefit you? But Allah,- He it is that heareth and knoweth all things."'),
  ('en.yusufali', 5, 77, 'Say: "O people of the Book! exceed not in your religion the bounds (of what is proper), trespassing beyond the truth, nor follow the vain desires of people who went wrong in times gone by,- who misled many, and strayed (themselves) from the even way.'),
  ('en.yusufali', 5, 78, 'Curses were pronounced on those among the Children of Israel who rejected Faith, by the tongue of David and of Jesus the son of Mary: because they disobeyed and persisted in excesses.'),
  ('en.yusufali', 5, 79, 'Nor did they (usually) forbid one another the iniquities which they committed: evil indeed were the deeds which they did.'),
  ('en.yusufali', 5, 80, 'Thou seest many of them turning in friendship to the Unbelievers. Evil indeed are (the works) which their souls have sent forward before them (with the result), that Allah\'s wrath is on them, and in torment will they abide.'),
  ('en.yusufali', 5, 81, 'If only they had believed in Allah, in the Prophet, and in what hath been revealed to him, never would they have taken them for friends and protectors, but most of them are rebellious wrong-doers.'),
  ('en.yusufali', 5, 82, 'Strongest among men in enmity to the believers wilt thou find the Jews and Pagans; and nearest among them in love to the believers wilt thou find those who say, "We are Christians": because amongst these are men devoted to learning and men who have renounced the world, and they are not arrogant.'),
  ('en.yusufali', 5, 83, 'And when they listen to the revelation received by the Messenger, thou wilt see their eyes overflowing with tears, for they recognise the truth: they pray: "Our Lord! we believe; write us down among the witnesses.'),
  ('en.yusufali', 5, 84, '"What cause can we have not to believe in Allah and the truth which has come to us, seeing that we long for our Lord to admit us to the company of the righteous?"'),
  ('en.yusufali', 5, 85, 'And for this their prayer hath Allah rewarded them with gardens, with rivers flowing underneath,- their eternal home. Such is the recompense of those who do good.'),
  ('en.yusufali', 5, 86, 'But those who reject Faith and belie our Signs,- they shall be companions of Hell-fire.'),
  ('en.yusufali', 5, 87, 'O ye who believe! make not unlawful the good things which Allah hath made lawful for you, but commit no excess: for Allah loveth not those given to excess.'),
  ('en.yusufali', 5, 88, 'Eat of the things which Allah hath provided for you, lawful and good; but fear Allah, in Whom ye believe.'),
  ('en.yusufali', 5, 89, 'Allah will not call you to account for what is futile in your oaths, but He will call you to account for your deliberate oaths: for expiation, feed ten indigent persons, on a scale of the average for the food of your families; or clothe them; or give a slave his freedom. If that is beyond your means, fast for three days. That is the expiation for the oaths ye have sworn. But keep to your oaths. Thus doth Allah make clear to you His signs, that ye may be grateful.'),
  ('en.yusufali', 5, 90, 'O ye who believe! Intoxicants and gambling, (dedication of) stones, and (divination by) arrows, are an abomination,- of Satan\'s handwork: eschew such (abomination), that ye may prosper.'),
  ('en.yusufali', 5, 91, 'Satan\'s plan is (but) to excite enmity and hatred between you, with intoxicants and gambling, and hinder you from the remembrance of Allah, and from prayer: will ye not then abstain?'),
  ('en.yusufali', 5, 92, 'Obey Allah, and obey the Messenger, and beware (of evil): if ye do turn back, know ye that it is Our Messenger\'s duty to proclaim (the message) in the clearest manner.'),
  ('en.yusufali', 5, 93, 'On those who believe and do deeds of righteousness there is no blame for what they ate (in the past), when they guard themselves from evil, and believe, and do deeds of righteousness,- (or) again, guard themselves from evil and believe,- (or) again, guard themselves from evil and do good. For Allah loveth those who do good.'),
  ('en.yusufali', 5, 94, 'O ye who believe! Allah doth but make a trial of you in a little matter of game well within reach of game well within reach of your hands and your lances, that He may test who feareth him unseen: any who transgress thereafter, will have a grievous penalty.'),
  ('en.yusufali', 5, 95, 'O ye who believe! Kill not game while in the sacred precincts or in pilgrim garb. If any of you doth so intentionally, the compensation is an offering, brought to the Ka\'ba, of a domestic animal equivalent to the one he killed, as adjudged by two just men among you; or by way of atonement, the feeding of the indigent; or its equivalent in fasts: that he may taste of the penalty of his deed. Allah forgives what is past: for repetition Allah will exact from him the penalty. For Allah is Exalted, and Lord of Retribution.'),
  ('en.yusufali', 5, 96, 'Lawful to you is the pursuit of water-game and its use for food,- for the benefit of yourselves and those who travel; but forbidden is the pursuit of land-game;- as long as ye are in the sacred precincts or in pilgrim garb. And fear Allah, to Whom ye shall be gathered back.'),
  ('en.yusufali', 5, 97, 'Allah made the Ka\'ba, the Sacred House, an asylum of security for men, as also the Sacred Months, the animals for offerings, and the garlands that mark them: That ye may know that Allah hath knowledge of what is in the heavens and on earth and that Allah is well acquainted with all things.'),
  ('en.yusufali', 5, 98, 'Know ye that Allah is strict in punishment and that Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 5, 99, 'The Messenger\'s duty is but to proclaim (the message). But Allah knoweth all that ye reveal and ye conceal.'),
  ('en.yusufali', 5, 100, 'Say: "Not equal are things that are bad and things that are good, even though the abundance of the bad may dazzle thee; so fear Allah, O ye that understand; that (so) ye may prosper."'),
  ('en.yusufali', 5, 101, 'O ye who believe! Ask not questions about things which, if made plain to you, may cause you trouble. But if ye ask about things when the Qur\'an is being revealed, they will be made plain to you, Allah will forgive those: for Allah is Oft-forgiving, Most Forbearing.'),
  ('en.yusufali', 5, 102, 'Some people before you did ask such questions, and on that account lost their faith.'),
  ('en.yusufali', 5, 103, 'It was not Allah who instituted (superstitions like those of) a slit-ear she-camel, or a she-camel let loose for free pasture, or idol sacrifices for twin-births in animals, or stallion-camels freed from work: It is blasphemers who invent a lie against Allah; but most of them lack wisdom.'),
  ('en.yusufali', 5, 104, 'When it is said to them: "Come to what Allah hath revealed; come to the Messenger": They say: "Enough for us are the ways we found our fathers following." what! even though their fathers were void of knowledge and guidance?'),
  ('en.yusufali', 5, 105, 'O ye who believe! Guard your own souls: If ye follow (right) guidance, no hurt can come to you from those who stray. the goal of you all is to Allah: it is He that will show you the truth of all that ye do.'),
  ('en.yusufali', 5, 106, 'O ye who believe! When death approaches any of you, (take) witnesses among yourselves when making bequests,- two just men of your own (brotherhood) or others from outside if ye are journeying through the earth, and the chance of death befalls you (thus). If ye doubt (their truth), detain them both after prayer, and let them both swear by Allah: "We wish not in this for any worldly gain, even though the (beneficiary) be our near relation: we shall hide not the evidence before Allah: if we do, then behold! the sin be upon us!"'),
  ('en.yusufali', 5, 107, 'But if it gets known that these two were guilty of the sin (of perjury), let two others stand forth in their places,- nearest in kin from among those who claim a lawful right: let them swear by Allah: "We affirm that our witness is truer than that of those two, and that we have not trespassed (beyond the truth): if we did, behold! the wrong be upon us!"'),
  ('en.yusufali', 5, 108, 'That is most suitable: that they may give the evidence in its true nature and shape, or else they would fear that other oaths would be taken after their oaths. But fear Allah, and listen (to His counsel): for Allah guideth not a rebellious people:'),
  ('en.yusufali', 5, 109, 'One day will Allah gather the messengers together, and ask: "What was the response ye received (from men to your teaching)?" They will say: "We have no knowledge: it is Thou Who knowest in full all that is hidden."'),
  ('en.yusufali', 5, 110, 'Then will Allah say: "O Jesus the son of Mary! Recount My favour to thee and to thy mother. Behold! I strengthened thee with the holy spirit, so that thou didst speak to the people in childhood and in maturity. Behold! I taught thee the Book and Wisdom, the Law and the Gospel and behold! thou makest out of clay, as it were, the figure of a bird, by My leave, and thou breathest into it and it becometh a bird by My leave, and thou healest those born blind, and the lepers, by My leave. And behold! thou bringest forth the dead by My leave. And behold! I did restrain the Children of Israel from (violence to) thee when thou didst show them the clear Signs, and the unbelievers among them said: \'This is nothing but evident magic.\''),
  ('en.yusufali', 5, 111, '"And behold! I inspired the disciples to have faith in Me and Mine Messenger: they said, \'We have faith, and do thou bear witness that we bow to Allah as Muslims\'".'),
  ('en.yusufali', 5, 112, 'Behold! the disciples, said: "O Jesus the son of Mary! can thy Lord send down to us a table set (with viands) from heaven?" Said Jesus: "Fear Allah, if ye have faith."'),
  ('en.yusufali', 5, 113, 'They said: "We only wish to eat thereof and satisfy our hearts, and to know that thou hast indeed told us the truth; and that we ourselves may be witnesses to the miracle."'),
  ('en.yusufali', 5, 114, 'Said Jesus the son of Mary: "O Allah our Lord! Send us from heaven a table set (with viands), that there may be for us - for the first and the last of us - a solemn festival and a sign from thee; and provide for our sustenance, for thou art the best Sustainer (of our needs)."'),
  ('en.yusufali', 5, 115, 'Allah said: "I will send it down unto you: But if any of you after that resisteth faith, I will punish him with a penalty such as I have not inflicted on any one among all the peoples."'),
  ('en.yusufali', 5, 116, 'And behold! Allah will say: "O Jesus the son of Mary! Didst thou say unto men, worship me and my mother as gods in derogation of Allah\'?" He will say: "Glory to Thee! never could I say what I had no right (to say). Had I said such a thing, thou wouldst indeed have known it. Thou knowest what is in my heart, Thou I know not what is in Thine. For Thou knowest in full all that is hidden.'),
  ('en.yusufali', 5, 117, '"Never said I to them aught except what Thou didst command me to say, to wit, \'worship Allah, my Lord and your Lord\'; and I was a witness over them whilst I dwelt amongst them; when Thou didst take me up Thou wast the Watcher over them, and Thou art a witness to all things.'),
  ('en.yusufali', 5, 118, '"If Thou dost punish them, they are Thy servant: If Thou dost forgive them, Thou art the Exalted in power, the Wise."'),
  ('en.yusufali', 5, 119, 'Allah will say: "This is a day on which the truthful will profit from their truth: theirs are gardens, with rivers flowing beneath,- their eternal Home: Allah well-pleased with them, and they with Allah: That is the great salvation, (the fulfilment of all desires).'),
  ('en.yusufali', 5, 120, 'To Allah doth belong the dominion of the heavens and the earth, and all that is therein, and it is He Who hath power over all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 5, 1, 'Yaaa aiyuhal lazeena aamanoo awfoo bil\'uqood; uhillat lakum baheematul an\'aami illaa maa yutlaa \'alaikum ghaira muhillis saidi wa antum hurum; innal laaha yahkumu maa yureed'),
  ('en.transliteration', 5, 2, 'Yaaa aiyuhal lazeena aamanoo laa tuhilloo sha\'aaa \'iral laahi wa lash Shahral Haraama wa lal hadya wa lal qalaaa\'ida wa laa aaammeenal Baital Haraama yabtaghoona fadlam mir Rabbihim wa ridwaanaa; wa izaa halaltum fastaadoo; wa laa yajrimannakum shana aanu qawmin an saddookum \'anil Masjidil-Haraami an ta\'tadoo; wa ta\'aawanoo \'alalbirri wattaqwaa; wa laa ta\'aawanoo \'alal ismi wal\'udwaan; wattaqul laah; innal laaha shadeedul \'iqaab'),
  ('en.transliteration', 5, 3, 'Hurrimat \'alaikumul maitatu waddamu wa lahmul khinzeeri wa maaa uhilla lighiril laahi bihee walmun khani qatu wal mawqoozatu wal mutarad diyatu wanna teehatu wa maaa akalas sabu\'u illaa maa zakkaitum wa maa zubiha \'alan nusubi wa an tastaqsimoo bil azlaam; zaalikum fisq; alyawma ya\'isal lazeena kafaroo min deenikum falaa takhshawhum wakh shawn; alyawma akmaltu lakum deenakum wa atmamtu \'alaikum ni\'matee wa radeetu lakumul Islaama deenaa; famanidturra fee makhmasatin ghaira mutajaanifil li ismin fa innallaaha Ghafoorur Raheem'),
  ('en.transliteration', 5, 4, 'Yas\'aloonaka maazaaa uhilla lahum; qul uhilla lakumuttaiyibaatu wa maa\'allamtum minal jawaarihi mukallibeena tu\'allimoonahunnamimmaa \'allamakumul laahu fakuloo mimmaaa amsakna \'alaikum wazkurus mal laahi \'alaih; wattaqul laah; innal laaha saree\'ul hisaab'),
  ('en.transliteration', 5, 5, 'Alyawma uhilla lakumut taiyibaatu wa ta\'aamul lazeena ootul Kitaaba hillul lakum wa ta\'aamukum hillul lahum wal muhsanaatu minal mu\'minaati walmuhsanaatu minal lazeena ootul Kitaaba min qablikum izaaa aataitumoohunna ujoorahunna muhsineena ghaira musaafiheena wa laa muttakhizeee akhdaan; wa mai yakfur bil eemaani faqad habita \'amaluhoo wa huwa fil Aaakhirati minal khaasireen'),
  ('en.transliteration', 5, 6, 'Yaaa aiyuhal lazeena aamanoo izaa qumtum ilas Salaati faghsiloo wujoohakum wa Aidiyakum ilal maraafiqi wamsahoo biru\'oosikum wa arjulakum ilal ka\'bayn; wa in kuntum junuban fattahharoo; wain kuntum mardaaa aw\'alaa safarin aw jaaa\'a ahadum minkum minal ghaaa\'iti aw laamastumunnisaaa\'a falam tajidoo maaa\'an fatayammamoo sa\'eedan taiyiban famsahoo biwujoohikum wa aideekum minh; ma yureedul laahu liyaj\'ala \'alaikum min harajinw wa laakidy yureedu liyutahhirakum wa liyutimma m\'matahoo \'alaikum la\'allakum tashkuroon'),
  ('en.transliteration', 5, 7, 'Wazkuroo ni\'matal laahi \'alaikum wa meesaaqahul lazee waasaqakum biheee iz qultum sami\'naa wa ata\'naa wattaqul laah; innal laaha \'aleemum bizaatis sudoor'),
  ('en.transliteration', 5, 8, 'Yaaa aiyuhal lazeena aamaanoo koonoo qawwaa meena lillaahi shuhadaaa\'a bilqist, wa laa yajrimannakum shana aanu qawmin \'alaaa allaa ta\'diloo; i\'diloo; huwa aqrabu littaqwaa wattaqul laah; innal laaha khabeerum bimaa ta\'maloon'),
  ('en.transliteration', 5, 9, 'Wa\'adal laahul lazeena aamanoo wa \'amilus saalihaati lahum maghfiratunw wa ajrun \'azeem'),
  ('en.transliteration', 5, 10, 'Wallazeena kafaroo wa kazzaboo bi Aayaatinaaa ulaaa\'ika Ashaabul Jaheem'),
  ('en.transliteration', 5, 11, 'Yaa aiyuhal lazeena aamanuz kuroo ni\'matallaahi \'alaikum iz hamma qawmun ai yabsutooo ilaikum aidiyahm fakaffa aidiyahum \'ankum wattaqullaah; wa\'alal laahi fal yatawakalil mu\'minoon'),
  ('en.transliteration', 5, 12, 'Wa laqad akhazal laahu meesaaqa Banee Israaa\'eela wa ba\'sanaa minhumus ani \'ashara naqeebanw wa qaalal laahu innee ma\'akum la\'in aqamtumus Salaata wa aataitumuz Zakaata wa aamantum bi Rusulee wa\'azzartumoohum wa aqradtumul laaha qardan hasanal la ukaffiranna \'ankum saiyiaatikum wa la udkhilan nakum Jannaatin tajree min tahtihal anhaar; faman kafara ba\'da zaalika minkum faqad dalla sawaaa\'as Sabeel'),
  ('en.transliteration', 5, 13, 'Fabimaa naqdihim meesaa qahum la\'annaahum wa ja\'alnaa quloobahum qaasiyatany yuharrifoonal kalima \'ammawaadi\'ihee wa nasoo hazzam mimmaa zukkiroo bih; khaaa\'inatim minhum illaa qaleelam minhum fa\'fu \'anhum wasfah; innal laaha yuhibbul muhsineen'),
  ('en.transliteration', 5, 14, 'Wa minal lazeena qaalooo innaa nasaaraaa akhaznaa meesaaqahum fanasoo hazzam mimmaa zukkiroo bihee fa aghrainaa binahumul \'adaawata walbaghdaaa\'a ilaa yawmil Qiyaamah; wa sawfa yunabbi\'uhumul laahu bimaa kaanoo yasna\'oon'),
  ('en.transliteration', 5, 15, 'yaaa Ahlal kitaabi qad jaaa\'akum Rasoolunaa yubaiyinu lakum kaseeram mimmmaa kuntum tukhfoona minal Kitaabi wa ya\'foo \'an kaseer; qad jaaa\'akum minal laahi noorunw wa Kitaabum Mubeen'),
  ('en.transliteration', 5, 16, 'Yahdee bihil laahu manit taba\'a ridwaanahoo subulas salaami wa yukhrijuhum minaz zulumaati ilan noori bi iznihee wa yahdeehim ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 5, 17, 'Laqad kafaral lazeena qaalooo innal laaha huwal maseehub nu Maryam; qul famany-yamliku minal laahi shai\'an in araada ai yuhlikal Maseehab na Maryama wa ummahoo wa man fil ardi jamee\'aa, wa lillaahi mmulkus samaawaati wal ardi wa maa bainahumaa; yakhluqu maa Yashaaa\'; wakhluqu maa yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 5, 18, 'Wa qaalatil Yahoodu wan Nasaaraa nahnu abnaaa\'ul laahi wa ahibbaaa\'uh; qul falima yu\'azzibukum bizunoobikum bal antum basharum mimmman khalaq; yaghfiru limai yashaaa\'u wa yu\'azzibu mai yashaaa\'; wa lillaahi mulkus samaawaati wal ardi wa maa bainahumaa wa ilaihil maseer'),
  ('en.transliteration', 5, 19, 'Yaaa Ahlal Kitaabi qad jaaa\'akum Rasoolunaa yubaiyinu lakum \'alaa fatratim minal Rusuli an taqooloo maa jaaa\'anaa mim basheerinw wa laa nazeerin faqad jaaa\'akum basheerunw wa nazeer; wallaahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 5, 20, 'Qa iz qaala Moosaa liqawmihee yaa qawmiz kuroo ni\'matal laahi \'alaikum iz ja\'ala feekum mulookanw wa aataakum maa lam yu\'ti ahadam minal \'aalameen'),
  ('en.transliteration', 5, 21, 'Yaa qawmid khulul Ardal MMuqaddasatal latee katabal laahu lakum wa laa tartaddoo \'alaaa adbaarikum fatanqaliboo khaasireen'),
  ('en.transliteration', 5, 22, 'Qaaloo yaa Moosaaa innaa feehaa qwman jabbaareena wa innaa lan nadkhulahaa hattaa yakhrujoo minhaa fa innaa daakhiloon'),
  ('en.transliteration', 5, 23, 'Qaala rajulaani minal lazeena yakhaafoona an\'amal laahu \'alaihimad khuloo \'alaihimul baab, fa izaa dakhaltumoohu fa innakum ghaaliboon; wa \'alal laahi fatawakkalooo in kuntum mu\'mineen'),
  ('en.transliteration', 5, 24, 'Qaaloo yaa Moosaaa innaa lan nadkhulahaa abadam maa daamoo feehaa fazhab anta wa Rabbuka faqaatilaaa innaa haahunaa qaa\'idoon'),
  ('en.transliteration', 5, 25, 'Qaala Rabbi innee laaa amliku illaa nafsee wa akhee fafruq bainanaa wa bainal qawmil faasiqeen'),
  ('en.transliteration', 5, 26, 'Qaala fa innahaa muhar ramatun \'alaihim arba\'eena sanah; yateehoona fil ard; falaa taasa \'alal qawmil faasiqeen'),
  ('en.transliteration', 5, 27, 'Watlu \'alaihim naba abnai Aadama bilhaqq; iz qarrabaa qurbaanan fatuqubbila min ahadihimaa wa lam yutaqabbal minal aakhari qaala la aqtulannnaka qaala innamaa yataqabbalul laahu minal muttaqeen'),
  ('en.transliteration', 5, 28, 'La\'im basatta ilaiya yadaka litaqtulanee maaa ana bibaasitiny yadiya ilaika li aqtulaka inneee akhaaful laaha Rabbal \'aalameen'),
  ('en.transliteration', 5, 29, 'Inee ureedu an tabooo\'a bi ismee wa ismika fatakoona min Ashaabin Naar; wa zaalika jazaaa\'uz zaalimeen'),
  ('en.transliteration', 5, 30, 'Fatawwa\'at lahoo nafsu hoo qatla akheehi faqatalahoo fa asbaha minal khaasireen'),
  ('en.transliteration', 5, 31, 'Faba\'asal laahu ghuraabai yabhasu fil ardi liyuriyahoo kaifa yuwaaree sawata akheeh; qaala yaa wailataaa a\'ajaztu an akoona misla haazal ghuraabi fa uwaariya saw ata akhee fa asbaha minan naadimeen'),
  ('en.transliteration', 5, 32, 'min ajli zaalika katabnaa \'alaa Banee Israaa\'eela annahoo man qatala nnafsam bighairi nafsin aw fasaadin fil ardi faka annnamaa qatalan fil ardi faka annammaa qatalan naasa jamee\'anw wa man ahyaahaa faka annamaaa ahyan naasa jamee\'aa; wa laqad jaaa\'at hum Rusulunaa bilbaiyinaati summa inna kaseeram minhum ba\'da zaalika fil ardi lamusrifoon'),
  ('en.transliteration', 5, 33, 'Innamaa jazaaa\'ul lazeena yuhaariboonal laaha wa Rasoolahoo wa yas\'awna fil ardi fasaadan ai yuqattalooo aw yusallabooo aw tuqatta\'a aideehim wa arjuluhum min khilaafin aw yunfaw minalard; zaalika lahum khizyun fid dunyaa wa lahum fil Aakhirati \'azaabun \'azeem'),
  ('en.transliteration', 5, 34, 'Illal lazeena taaboo min qabli an taqdiroo \'alaihim fa\'lamooo annnal laaha Ghafoorur Raheem'),
  ('en.transliteration', 5, 35, 'yaaa aiyuhal lazeena aamanut taqul laaha wabtaghooo ilaihil waseelata wa jaahidoo fee sabeelihee la\'allakum tuflihoon'),
  ('en.transliteration', 5, 36, 'Innal lazeena kafaroo law anna lahum maa fil ardi jamee\'anw wa mislahoo ma\'ahoo liyaftadoo bihee min \'azaabi Yawmil Qiyaamati maa tuqubbila minhum wa lahum azaabun aleem'),
  ('en.transliteration', 5, 37, 'Yureedoona ai yakhrujoo minan Naari wa maa hum bikhaari jeena minhaa wa lahum \'azaabum muqeem'),
  ('en.transliteration', 5, 38, 'Wassaariqu qassaariqatu faqta\'oo aidiyahumma jazaaa\'am bimaa kasabaa nakaalam minal laah; wallaahu \'Azeezun hakeem'),
  ('en.transliteration', 5, 39, 'Faman taaba mim ba\'di zulmihee wa aslaha fa innal laaha yatoobu \'alaih; innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 5, 40, 'Alam ta\'lam annal laaha lahoo mulkus samaawaati wal ardi yu\'az zibu many-yashaa\'u wa yaghfiru limany-yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 5, 41, 'Yaaa ayyuhar Rasoolu laa yahzukal lazeena yusaa ri\'oona fil kufri minal lazeena qaaloo aamannaa bi afwaahihim wa lam tu\'min quloobuhum; wa minal lazeena haadoo sammaa\'oona lilkazibi sammaa\'oona liqawmin aakhareena lam yaatooka yuharifoonal kalima mim ba\'di mawaadi\'ihee yaqooloona in ooteetum haazaa fakhuzoohu wa il lam tu\'tawhu fahzaroo; wa many-yuridil laahu fitnatahoo falan tamlika lahoo minal laahi shai\'aa; ulaaa \'ikal lazeena lam yuridil laahu any-yutahhira quloobahum; lahum fid dunyaa khizyunw wa lahum fil Aakhirati\'azaabun \'azeem'),
  ('en.transliteration', 5, 42, 'Sammaa\'oona lilkazibi akkaaloona lissuht; fa in jaaa\'ooka fahkum bainahum aw a\'rid anhum wa in tu\'rid \'anhum falany-yadurrooka shai\'anw wa in hakamta fahkum bainahum bilqist; innal laaha yuhibbul muqsiteen'),
  ('en.transliteration', 5, 43, 'Wa kaifa yuhakkimoonaka wa \'indahumut Tawraatu feehaa hukmul laahi summa yatawallawna mim ba\'di zaalik; wa maaa ulaaa\'ika bilmu\'mineen'),
  ('en.transliteration', 5, 44, 'Innaaa anzalnat Tawraata feehaa hudanw wa noor; yahkumu bihan Nabiyyoonal lazeena aslamoo lillazeena haadoo war rabbaaniyyoona wal ahbaaru bimas tuhfizoo min Kitaabil laahi wa kaanoo \'alaihi shuhadaaa\'; falaa takhshawun naasa wakhshawni wa laa tashtaroo bi aayaatee samanan qaleelaa; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa\'ika humul kaafiroon'),
  ('en.transliteration', 5, 45, 'Wa katabnaa \'alaihim feehaaa annan nafsa binnafsi wal\'aina bil\'aini wal anfa bilanfi wal uzuna bil uzuni wassinna bissinni waljurooha qisaas; faman tasaddaqa bihee fahuwa kaffaaratul lah; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa\'ika humuz zalimoon'),
  ('en.transliteration', 5, 46, 'Wa qaffainaa \'alaaa aasaaarihim bi \'Eesab ni Maryama musaddiqal limaa baina yadihi minat Tawraati wa aatainaahul Injeela feehi hudanw wa noorunw wa musaddiqal limaa baina yadaihi minat Tawraati wa hudanw wa maw\'izatal lilmuttaqeen'),
  ('en.transliteration', 5, 47, 'Walyahkum Ahlul Injeeli bimaaa anzalal laahu feeh; wa mal lam yahkum bimaaa anzalal laahu fa ulaaa\'ika humul faasiqoon'),
  ('en.transliteration', 5, 48, 'Wa anzalnaa ilaikal Kitaaba bilhaqqi musaddiqallimaa baina yadaihi minal Kitaabi wa muhaiminan \'alaihi fahkum bainahum bimaa anzalal laahu wa laa tattabi ahwaaa\'ahum \'ammaa jaaa\'aka minal haqq; likullin ja\'alnaa minkum shir\'atanw wa minhaajaa; wa law shaaa\'al laahu laja\'alakum ummatanw waahidatanw wa laakil liyabluwakum fee maa aataakum fastabiqul khairaat; ilal laahi arji\'ukum jamee\'an fayunab bi\'ukum bimaa kuntum feehi takhtalifoon'),
  ('en.transliteration', 5, 49, 'Wa anih kum bainahum bimaaa anzalal laahu wa laa tattabi\' ahwaaa\'ahum wahzarhum ai yaftinooka \'am ba\'di maaa anzalal laahu ilaika fa in tawallaw fa\'lam annamaa yureedul laahu ai yuseebahum biba\'di zunoobihim; wa inna kaseeram minan naasi lafaasiqoon'),
  ('en.transliteration', 5, 50, 'Afahukmal jaahiliyyati yabghoon; wa man ahsanu minal laahi hukmal liqawminy yooqinoon'),
  ('en.transliteration', 5, 51, 'Yaaa aiyuhal lazeena aamanoo laa tattakhizul Yahooda wan nasaaraaa awliyaaa\'; ba\'duhum awliyaaa\'u ba\'d; wa mai yatawallahum minkum fa innahoo minhum; innal laaha laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 5, 52, 'Fataral lazeena fee quloobihim maraduny yusaari\'oona feehim yaqooloona nakhshaaa an tuseebanaa daaa\'irah; fa\'asallaahu ai yaatiya bilfathi aw amrim min \'indihee fa yusbihoo \'alaa maaa asarroo feee anfusihim naadimeen'),
  ('en.transliteration', 5, 53, 'Wa yaqoolul lazeena aamanooo ahaaa\'ulaaa\'il lazeena aqsamoo billaahi jahda aimaanihim innahum lama\'akum; habitat a\'maaluhum fa asbahoo khaasireen'),
  ('en.transliteration', 5, 54, 'Yaa aiyuhal lazeena aamanoo mai yartadda minkum \'an deenihee fasawfa yaatil laahu biqawminy yuhibbuhum wa yuhibboonahoo azillatin \'alal mu\'mineena a\'izzatin \'alal kaafireena yujaahidoona fee sabeelil laahi wa laa yakhaafoona lawmata laaa\'im; zaalika fadlul laahi yu\'teehi mai yashaaa\'; wallaahu Waasi\'un \'Aleem'),
  ('en.transliteration', 5, 55, 'Innamaa waliyyukumul laahu wa Rasooluhoo wal lazeena aamanul lazeena yuqeemoonas Salaata wa yu\'toonaz Zakaata wa hum raaki\'oon'),
  ('en.transliteration', 5, 56, 'Wa mai yatawallal laaha wa Rasoolahoo wallazeena aamanoo fa inna hizbal laahi humul ghaaliboon'),
  ('en.transliteration', 5, 57, 'Yaaa aiyuhal lazeena aamanoo laa tattakhizul lazeenat takhazoo deenakum huzuwanw wa la\'ibam minal lazeena ootul Kitaaba min qablikum walkuffaara awliyaaa\'; wattaqul laaha in kuntum muu\'mineen'),
  ('en.transliteration', 5, 58, 'Wa izaa naadaitum ilas Salaatit takhazoohaa huzu wan\'w wa la\'ibaa; zaalika biannnahum qawmul laa ya\'qiloon'),
  ('en.transliteration', 5, 59, 'Qul yaaa Ahlal Kitaabi hal tanqimoona minnaaa illaaa an aamannaa billaahi wa maaa unzila ilainaa wa maa unzila min qablu wa annna aksarakum faasiqoon'),
  ('en.transliteration', 5, 60, 'Qul hal unabbi\'ukum bisharrim min zaalika masoobatan \'indal laah; malla\'ana hul laahu wa ghadiba \'alaihi wa ja\'ala minhumul qiradata wal khanaazeera wa \'abadat Taaghoot; ulaaa\'ika sharrum makaananw wa adallu \'an Sawaaa\'is Sabeel'),
  ('en.transliteration', 5, 61, 'Wa izaa jaaa\'ookum qaalooo aamannaa wa qad dakhaloo bilkufri wa hum qad kharajoo bih; wallaahu a\'lamu bimaa kaanoo yaktumoon'),
  ('en.transliteration', 5, 62, 'Wa taraa kaseeram minhum yusaari\'oona fil ismi wal\'udwaani wa aklihimus suht; labi\'sa maa kaanoo ya\'maloon'),
  ('en.transliteration', 5, 63, 'Law laa yanhaahumur rabbaaniyyoona wal ahbaaru \'an qawlihimul ismaa wa aklihimus suht; labi\'sa maa kaanoo yasna\'oon'),
  ('en.transliteration', 5, 64, 'Wa qaalatil Yahoodu Yadullaahi maghloolah; ghulla aideehim wa lu\'inoo bimaa qaaloo; bal yadaahu mabsoo tataani yunfiqu kaifa yashaaa\'; wa la yazeedanna kaseeramm minhum maaa unzila ilaika mir Rabbika tughyaananw wa kufraa; wa alqainaa bainahumul \'adaawata wal baghdaaa a\' ilaa Yawmil Qiyaamah; kullamaaa awqadoo naaral lilharbi at fa-ahal laah; wa yas\'awna fil ardi fasaadaa; wal laahu laa yuhibbul mufsideen'),
  ('en.transliteration', 5, 65, 'Wa law anna Ahlal Kitaabi aamanoo wattaqaw lakaffarnaa \'anhum saiyiaatihim wa la adkhalnaahu Jannaatin Na\'eem'),
  ('en.transliteration', 5, 66, 'Wa law annahum aqaamut Tawraata wal Injeela wa maaa unzila ilaihim mir Rabbihim la akaloo min fawqihim wa min tahti arjulihim; minhum ummatum muqta sidatunw wa kaseerum minhum saaa\'a maa ya\'maloon'),
  ('en.transliteration', 5, 67, 'Yaaa aiyuhar Rasoolu balligh maaa unzila ilaika mir Rabbika wa il lam taf\'al famaaa ballaghta Risaalatah; wallaahu ya\'simuka minan naas; innal laaha laa yahdil qawmal kaafireen'),
  ('en.transliteration', 5, 68, 'Qul yaaa Ahlal Kitaabi lastum \'alaa shai\'in hattaa tuqeemut Tawraata wal Injeela wa maaa unzila ilaikum mir Rabbikum; wa layazeedanna kaseeram minhum maa unzila ilaika mir Rabbika tugh yaananw wa kufran falaa taasa \'alal qawmil kaafireen'),
  ('en.transliteration', 5, 69, 'Innal lazeena aamanoo wallazeena haadoo was saabi\'oona wan Nasaaraa man aamana billaahi wal yawmil Aakhiri wa \'amila saalihan falaa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 5, 70, 'Laqad akhaznaa meesaaqa Banee Israaa\'eela wa arsalnaaa ilaihim Rusulan kullamaa jaaa\'ahum Rasoolum bimaa laa tahwaaa anfusuhum fareeqan kazzaboo wa fareeqany yaqtuloon'),
  ('en.transliteration', 5, 71, 'Wa hasibooo allaa takoona fitnaun fa\'amoo wa sammoo summa taabal laahu \'alaihim summa \'amoo wa sammoo kaseerum minhum; wallaahu baseerum bimaa ya\'maloon'),
  ('en.transliteration', 5, 72, 'Laqad kafaral lazeena qaalooo innal laaha Huwal maseehub nu Maryama wa qaalal Maseehu yaa Baneee Israaa\'eela budul laaha Rabbee wa Rabbakum innnahoo many-yushrik ballaahi faqad harramal laahu \'alaihil jannata wa maa waahun Naaru wa maa lizzaalimeena min ansaar'),
  ('en.transliteration', 5, 73, 'laqad kafaral lazeena qaalooo innal laaha saalisu salaasah; wa maa min ilaahin illaaa Ilaahunw Waahid; wa illam yantahoo \'ammaa yaqooloona layamas sannal lazeena kafaroo minhum \'azaabun aleem'),
  ('en.transliteration', 5, 74, 'Afalaa yatooboona ilal laahi wa yastaghfiroonah; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 5, 75, 'Mal Maseehub nu Maryama illaa Rasoolun qad khalat min qablihir Rusulu wa ummuhoo siddeeqatun kaanaa yaa kulaanit ta\'aam; unzur kaifa nubaiyinu lahumul Aayaati suman zur annaa yu\'fakoon'),
  ('en.transliteration', 5, 76, 'Qul ata\'budoona min doonil laahi maa laa yamliku lakum darranw wa laa naf\'aa; wallaahu Huwas Samee\'ul \'Aleem'),
  ('en.transliteration', 5, 77, 'Qul yaaa Ahlal Kitaabi laa taghloo fee deenikum ghairal haqqi wa laa tattabi\'ooo ahwaaa\'a qawmin qad dalloo min qablu wa adalloo kaseeranw wa dalloo \'an Sawaaa\'is Sabeel'),
  ('en.transliteration', 5, 78, 'Lu\'inal lazeena kafaroo mim Baneee israaa\'eela \'alaa lisaani Daawooda wa \'Eesab ni Maryam; zaalika bimaa \'asaw wa kaanoo ya tadoon'),
  ('en.transliteration', 5, 79, 'Kaanoo laa yatanaahawna \'am munkarin fa\'aluhoo; labi\'sa maa kaanoo yafa\'loon'),
  ('en.transliteration', 5, 80, 'Taraa kaseeram minhum yatawallawnal lazeena kafaroo; labi\'sa maa qaddamat lahum anfusuhum an sakhital laahu \'alaihim wa fil \'azaabi hum khaalidoon'),
  ('en.transliteration', 5, 81, 'Wa law kaanoo yu\'minoona billaahi wan nabiyyi wa maaa unzila ilaihi attakhazoohum awliyaaa\'a wa laakinna kaseeram minhum faasiqoon'),
  ('en.transliteration', 5, 82, 'Latajidanna ashad dan naasi \'adaawatal lillazeena aamanul Yahooda wallazeena ashrakoo wa latajidanna aqrabahum mawaddatal lil lazeena aamanul lazeena qaalooo innaa Nasaaraa; zaalika bi anna mminhum qiseeseena wa ruhbaananw wa annahum laa yastakbiroon'),
  ('en.transliteration', 5, 83, 'Wa izaa sami\'oo maaa unzila ilar Rasooli taraaa a\'yunahum tafeedu minad dam\'i mimmmaa \'arafoo minalhaqq; yaqooloona Rabbanaaa aamannaa faktubnaa ma\'ash shaahideen'),
  ('en.transliteration', 5, 84, 'Wa maa lanaa laa nu\'minu billaahi wa maa jaaa\'anaa minal haqqi wa natma\'u ai yudkhilanaa Rabbunaa ma\'al qawmis saaliheen'),
  ('en.transliteration', 5, 85, 'Fa asaabahumul laahu bimaa qaaloo Jannnaatin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalika jazaaa\'ul muhsineen'),
  ('en.transliteration', 5, 86, 'Wallazeena kafaroo wa kazzaboo bi Aayaatinaaa ulaaa\'ika Ashaabul Jaheem'),
  ('en.transliteration', 5, 87, 'Yaaa aiyuhal lazeena aamanoo laa tuharrimoo taiyibaati maaa ahallal laahu lakum wa laa ta\'tadooo; innal laaha laa yuhibbul mu\'tadeen'),
  ('en.transliteration', 5, 88, 'Wa kuloo mimmaa razaqakumul laahu halaalan taiyibaa; wattaqul laahallazeee antum bihee mu\'minon'),
  ('en.transliteration', 5, 89, 'Laa yu\'aakhizukumul laahu billaghwi feee aimaanikum wa laakiny ya\'aakhizukum bimaa \'aqqattumul aimaana fakaf faaratuhooo it\'aamu \'asharati masaakeena min awsati maa tut\'imoona ahleekum aw kiswatuhum aw tahreeru raqabatin famallam yajid fa Siyaamu salaasati aiyaam; zaalika kaffaaratu aimaanikum izaa halaftum; wahfazooo aimaanakum; kazaalika yubaiyinul laahu lakum Aayaatihee la\'allakum tashkuroon'),
  ('en.transliteration', 5, 90, 'yaaa aiyuhal lazeena aamanooo innamal khamru walmaisiru wal ansaabu wal azlaamu rijsum min \'amalish shaitaani fajtaniboohu la\'al lakum tuflihoon'),
  ('en.transliteration', 5, 91, 'Innamaa yureedush Shaitaanu ai yooqi\'a bainakumul \'adaawata wal baghdaaa\'a fil khamri wal maisiri wa yasuddakum \'an zikril laahi wa \'anis Salaati fahal antum muntahoon'),
  ('en.transliteration', 5, 92, 'Wa atee\'ul laaha wa atee\'ur Rasoola wahzaroo; fa in tawal laitum fa\'lamooo annamaa \'alaa Rasoolinal balaaghul mubeen'),
  ('en.transliteration', 5, 93, 'Laisa \'alal lazeena aamanoo wa \'amilus saalihaati junaahun feemaa ta\'imooo izaa mat taqaw wa aamanoo wa \'amilus saalihaati summat taqaw wa aamanoo summat taqaw wa ahsanoo; wallaahu yuhibbul muhsineen'),
  ('en.transliteration', 5, 94, 'Yaaa aiyuhal lazeena aamanoo la yabluwannnakumul laahu bishai\'im minas saidi tanaaluhooo aideekum wa rimaahukum liya\'lamal laahu mai yakhaafuhoo bilghaib; famani\' tadaa ba\'da zaalika falahoo \'azaabun aleem'),
  ('en.transliteration', 5, 95, 'Yaaa aiyuhal lazeena aamanoo laa taqtuslus saida wa antum hurum; wa man qatalahoo minkum mut\'am midan fajazaaa\'um mislu maa qatala minanna\'ami yahkumu bihee zawaa \'adlim minkum hadyam baalighal Ka\'bati aw kaffaaratun ta\'aamu masaakeena aw \'adlu zaalika Siyaamal liyazooqa wabaala amrih; \'afal laahu \'ammaa salaf; wa man \'aada fayanta qimul laahu minh; wallaahu \'azeezun zuntiqaam'),
  ('en.transliteration', 5, 96, 'Uhilla lakum saidul bahri wa ta\'aamuhoo mataa\'al lakum wa lissaiyaarati wa hurrima \'alaikum saidul barri maa dumtum hurumaa; wattaqul laahal lazeee ilaihi tuhsharoon'),
  ('en.transliteration', 5, 97, 'Ja\'alal laahul Ka\'batal Baital Haraama qiyaamal linnaasi wash Shahral Haraama walhadya walqalaaa\'id; zaalika lita\'lamooo annal laaha ya\'lamu maa fis samaawaati wa maa fil ardi wa annal laaha bikulli shai\'in \'Aleem'),
  ('en.transliteration', 5, 98, 'I\'lamooo annal laaha shadeedul \'iqaabi wa annal laaha Ghafoorur Raheem'),
  ('en.transliteration', 5, 99, 'Maa \'alar Rasooli illal balaagh; wallaahu ya\'lamu maa tubdoona wa maa taktumoon'),
  ('en.transliteration', 5, 100, 'Qul laa yastawil khabeesu wattaiyibu wa law a\'jabaka kasratul khabees; fattaqul laaha yaaa ulil albaabi la\'allakum tuflihoon'),
  ('en.transliteration', 5, 101, 'yaaa aiyuhal lazeena aamanoo laa tas\'aloo \'an ashyaaa\'a in tubda lakum tasu\'kum wa in tas\'aloo \'anhaa heena yunazzalul Qur\'aanu tubda lakum; \'afallaahu \'anhaa; wallaahu Ghafoorun Haleem'),
  ('en.transliteration', 5, 102, 'Qad sa alahaa qawmum min qablikum summa asbahoo bihaa kaafireen'),
  ('en.transliteration', 5, 103, 'Maa ja\'alal laahu mim baheeratinw wa laa saaa\'ibatinw wa laa waseelatinw wa laa haaminw wa laakinnal lazeena kafaroo yaftaroona \'alallaahil kazib; wa aksaruhum laa ya\'qiloon'),
  ('en.transliteration', 5, 104, 'Wa izaa qeela lahum ta\'aalaw ilaa maaa anzalallaahu wa ilar Rasooli qaaloo hasbunaa maa wajadnaa \'alaihi aabaaa\'anaa; awa law kaana aabaaa\'uhum laa ya\'lamoona shai\'anw wa laa yahtadoon'),
  ('en.transliteration', 5, 105, 'Yaaa aiyuhal lazeena aamanoo \'alaikum anfusakum laa yadurrukum man dalla izah tadaitum; ilal laahi marji\'ukum jamee\'an fayunabbi\'ukum bimaa kuntum ta\'maloon'),
  ('en.transliteration', 5, 106, 'Yaaa aiyuhal lazeena aamanoo shahaadatu bainikum izaa hadara ahadakumul mawtu heenal wasiyyatis naani zawaa \'adlim minkum aw aakharaani min ghairikum in antum darabtum fil ardi fa asaabatkum museebatul mawt; tahbi soonahumaa mim ba\'dis Salaati fa yuqsimaani billaahi inirtabtum laa nashtaree bihee samananw wa law kaana zaa qurbaa wa laa naktumu shahaadatal laahi innaaa izal laminal aasimeen'),
  ('en.transliteration', 5, 107, 'Fa in \'usira \'alaaa annahumas tahaqqaaa isman fa aakharaani yaqoomaani maqaamahumaa minal lazeenas tahaqqa \'alaihimul awlayaani fa yuqsimaani billaahi lashahaadatunaaa ahaqqu min shahaadatihimaaa wa ma\'tadainaaa innaaa izal laminaz zaalimeen'),
  ('en.transliteration', 5, 108, 'Zaalika adnaaa ai yaatoo bishshahaadati \'alaa wajhihaaa aw yakhaafooo an turadda aimaanum ba\'da aimaanihim; wattaqul laaha wasma\'oo; wallaahu laa yahdil qawmal faasiqeen'),
  ('en.transliteration', 5, 109, 'yawma yajma\'ul laahur Rusula fa yaqoolu maazaaa ujibtum qaaloo laa \'ilma lanaa innaka Anta \'Allaamul Ghuyoob'),
  ('en.transliteration', 5, 110, 'Iz qaalal laahu yaa \'Eesab-na-Maryamaz kur ni\'matee \'alaika wa \'alaa waalidatik; iz aiyattuka bi Roohil Qudusi tukallimun naasa fil mahdi wa kahlanw wa iz \'allamtukal kitaaba wal Hikmata wa Tawraata wal Injeela wa iz Takhluqu minat teeni kahai \'atit tairi bi iznee fatanfukhu feeha fatakoonu tairam bi iznee wa tubri\'ul akmaha wal abrasa bi iznee wa iz tukhrijul mawtaa bi iznee wa iz kafaftu Baneee Israaa\'eela \'anka iz ji\'tahum bil baiyinaati fa qaalal lazeena kafaroo minhum in haazaaa illaa sihrum mubeen'),
  ('en.transliteration', 5, 111, 'Wa iz awhaitu ilal hawaariyyeena an aaminoo bee wa bi Rasoolee qaalooo aamannaa washhad bi annanaa muslimoon'),
  ('en.transliteration', 5, 112, 'Iz qaalal hawaariyyoona yaa \'Eesab na Maryama hal yastatee\'u Rabbuka ai yunaz zila \'alinaa maaa\'idatam minas samaaa\'i qaalat taqul laaha in kuntum mu\'mineen'),
  ('en.transliteration', 5, 113, 'Qaaloo nureedu an naakula minhaa wa tatam\'inna quloo bunaa wa na\'lama an qad sadaqtana wa nakoona \'alaihaa minash shaahideen'),
  ('en.transliteration', 5, 114, 'Qaala \'Eesab nu Maryamal laahumma Rabbanaaa anzil \'alainaa maaa\'idatam minas samaaa\'i takoonu lanaa \'eedal li awwalinaa wa aakirinaa wa Aayatam minka warzuqnaa wa Anta khairur raaziqeen'),
  ('en.transliteration', 5, 115, 'Waalal laahu innee munaz ziluhaa \'alaikum faman yakfur ba\'du minkum fa inneee u\'azzibuhoo \'azaabal laaa u\'azzibuhooo ahadam minal \'aalameen'),
  ('en.transliteration', 5, 116, 'Wa iz qaalal laahu yaa \'Eesab na Maryama \'a-anta qulta linnaasit takhizoonee wa ummiya ilaahaini min doonil laahi qaala Subhaanaka maa yakoonu leee anaqoola maa yakkoonu leee an aqoola maa laisa lee bihaqq; in kuntu qultuhoo faqad \'alimtah; ta\'lamu maa fee nafsee wa laaa a\'almu maa fee nafsik; innaka Anta \'Allaamul Ghuyoob'),
  ('en.transliteration', 5, 117, 'Maa qultu lahum illaa maaa amartanee bihee ani\'budul laaha Rabbeee wa Rabbakum; wa kuntu \'alaihim shaheedam maa dumtu feehim falammaa tawaffaitanee kunta Antar Raqeeba \'alaihim; wa Anta \'alaa kulli shai\'in Shaheed'),
  ('en.transliteration', 5, 118, 'In tu\'azzibhum fa innahum ibaaduka wa in taghfir lahum fa innaka Antal \'Azzezul Hakeem'),
  ('en.transliteration', 5, 119, 'Qaalal laahu haaza yawmu yanfa\'us saadiqeena sidquhum; lahum janaatunn tajree min tahtihal anhaaru khaalideena feehaaa abadaa; radiyal laahu \'anhum wa radoo \'anh; zaalikal fawzul \'azeem'),
  ('en.transliteration', 5, 120, 'Lillaahi mulkus samaawaati wal ardi wa maa feehinn; wa Huwa \'alaa kulli shain\'in Qadeer')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 5, 1, 'اے ایمان والو! عہدوں کوپورا کرو تمہارے لیے چوپائے مویشی حلال ہیں سوائے ان کے جو تمہیں آگے سنائے جائیں گے مگر شکار کو احرام کی حالت میں حلال نہ جانو الله جو چاہے حکم دیتا ہے'),
  ('ur.ahmedali', 5, 2, 'اے ایمان والو! الله کی نشانیوں کو حلال نہ سمجھو اور نہ حرمت والے مہینے کو اور نہ حرم میں قربانی ہونے والے جانور کو اور نہ ان جانوروں کو جن کے گلے میں پٹے پڑے ہوئے ہوں اور نہ حرمت والے گھر کی طرف آنے والوں کو جو اپنے رب کا فضل اور اس کی خوشی ڈھونڈتے ہیں اور جب تم احرام کھول دو پھر شکار کرو اور تمہیں اس قوم کی دشمنی جو کہ تمہیں حرمت والی مسجد سے روکتی تھی اس بات کا باعث نہ بنے کہ زیادتی کرنے لگو اور آپس میں نیک کام اور پرہیز گاری پر مدد کرو اورگناہ اور ظلم پر مدد نہ کرو اور الله سے ڈرو بے شک الله سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 5, 3, 'تم پر مردار اور لہو اور سور کا گوشت حرام کیا گیا ہے اور وہ جانور جس پر الله کے سوا کسی اور کا نام پکارا جائے جو گلا گھوٹ کر یا چوٹ سے یا بلندی سے گر کر یا سینگ مارنے سے مر گیا ہو اور وہ جسے کسی درندے نے پھاڑ ڈالا ہو مگر جسے تم نے ذبح کر لیا ہو اور وہ جو کسی تھان پر ذبح کیا جائے اور یہ کہ جوئے کے تیروں سے تقسیم کرو یہ سب گناہ ہیں آج تمہارے دین سے کافر نا امید ہو گئے سو ان سے نہ ڈرو اور مجھ سے ڈرو آج میں تمہارے لیے تمہارا دین پورا کر چکا اور میں نے تم پر اپنا احسان پورا کر دیا اور میں نے تمہارے واسطے اسلام ہی کو دین پسند کیا ہے پھر جو کوئی بھوک سے بیتاب ہو جائے لیکن گناہ پر مائل نہ ہو تو الله معاف کرنے والا مہربان ہے'),
  ('ur.ahmedali', 5, 4, 'تجھ سے پوچھتے ہیں کہ ان کے لیے کیا چیز حلال ہے کہہ دو تمہارے واسطے سب پاکیزہ چیزیں حلا ل کی گئی ہیں اور جو شکاری جانور جسے شکار پر دوڑنے کی تعلیم دو کہ انہیں سکھاتے ہو اس میں سے جو الله نے تمہیں سکھایا ہے سو اس میں سے کھاؤ جو وہ تمہارے لیے پکڑ رکھیں اور اس پر الله کا نا م لو اور الله سے ڈرتے رہو بیشک الله جلد حساب لینے والا ہے'),
  ('ur.ahmedali', 5, 5, 'آج تمہارے واسطے سب پاکیزہ چیزیں حلا کی گئی ہیں اور اہلِ کتاب کا کھانا تمہیں حلال ہے اور تمہارا کھانا انہیں حلال ہے اور تمہارے لیے پاک دامن مسلمان عورتیں حلال ہیں اوران میں سے پاک دامن عورتیں جنہیں تم سے پہلے کتاب دی گئی ہےجب ان کے مہر انہیں دے دو ایسے حال میں کہ نکاح میں لانے والے ہو نہ بدکاری کرنے والے اورنہ خفیہ آشنائی کرنے والے اورجوایمان سے منکر ہوا تو اس کی محنت ضائع ہوئی اور وہ آخرت میں نقصان اٹھانے والوں میں سے ہو گا'),
  ('ur.ahmedali', 5, 6, 'اے ایمان والو! جب تم نماز کے لیے اٹھو تو اپنے منہ دھو لو اور ہاتھ کہنیوں تک اور اپنے سروں پر مسح کرو اور اپنے پاؤں ٹخنوں تک دھو لو اور اگر تم ناپاک ہو تو نہا لو اور اگرتم بیمار ہو یا سفر پر ہو یا کوئی تم میں سے جائے ضرور سے آیا ہو یا عورتوں کے پاس گئے ہو پھر تم پانی نہ پاؤ تو پاک مٹی سے تیمم کر لو اور اسے اپنے مونہوں او رہاتھوں پر مل لو الله تم پر تنگی کرنا نہیں چاہتا لیکن تمہیں پاک کرنا چاہتا ہے اور تاکہ اپنا احسان تم پر پورا کرے تاکہ تم شکر کرو'),
  ('ur.ahmedali', 5, 7, 'اور الله کا انعام جو تم پر ہوا ہے اسے یاد کرو اور اس کا عہد جس کا تم سے معاہدہ کیا ہے جب تم نے کہا تھا کہ ہم نے سنا اور مان لیا اور الله سے ڈرتے رہو الله دلو ں کی بات خوب جانتا ہے'),
  ('ur.ahmedali', 5, 8, 'اے ایمان والو! الله کے واسطے انصاف کی گواہی دینے کے لیے کھڑے ہو جاؤ اور کسی قوم کی دشمنی کا باعث انصاف کو ہر گز نہ چھوڑو انصاف کرو یہی بات تقویٰ کے زیادہ نزدیک ہے اور الله سے ڈرتے رہو جو کچھ تم کرتے ہو بے شک الله اس سے خبردارہے'),
  ('ur.ahmedali', 5, 9, 'الله نے ایمان والوں سے اور جو نیک کام کرتے ہیں بخشش اور بڑے اجر کا وعدہ کیا ہے'),
  ('ur.ahmedali', 5, 10, 'اور جن لوگو ں نے کفر کیا اور ہماری آیتیں جھٹلائیں وہ دوزخی ہیں'),
  ('ur.ahmedali', 5, 11, 'اے ایمان والو! الله کا احسان اپنے اوپر یاد کرو جب لوگو ں نے ارادہ کیا کہ تم پر دست درازی کریں پھر الله نے ان کے ہاتھ تم پر اٹھنے سےروک دیئے اور الله سے ڈرتے رہو اور ایمان والوں کو الله ہی پر بھروسہ کرنا چاہیے'),
  ('ur.ahmedali', 5, 12, 'اور الله نے بنی اسرائیل سے عہد لیا تھا اور ہم نے ان میں سے بارہ سردار مقرر کیے اور الله نےکہا میں تمہارے ساتھ ہوں اگر تم نماز کی پابندی کرو گے اور زکواة دیتے رہو گے اور میرے سب رسولوں پر ایمان لاؤ گے اور ان کی مدد کرو گے اور الله کواچھے طور پر قرض دیتے رہو گے تو میں ضرور تمہارے گناہ تم سےدور کردوں گا اور تمہیں باغوں میں داخل کروں گا جن کے نیچے نہریں بہتی ہیں پھر جوکوئی تم میں سے اس کے بعد کافر ہوا وہ بے شک سیدھے راستے سے گمراہ ہوا'),
  ('ur.ahmedali', 5, 13, 'پھر ان کی عہد شکنی کے باعث ہم نے ان پر لعنت کی اوران کے دلوں کوسخت کر دیا وہ لوگ کلام کو ا سکے ٹھکانے سے بدلتے ہیں اور اس نصیحت سے نفع اٹھانا بھول گئے جو انہوں کی گئی تھی اور تو ہمشیہ ان کی کسی نہ کسی خیانت پر اطلاع پاتا رہے گا مگر تھوڑے ان میں سے سو انہیں معاف کر اور درگزر کر بے شک الله نیکی کرنے والوں کو پسند کرتا ہے'),
  ('ur.ahmedali', 5, 14, 'اورجو لوگ اپنے آپ کو نصاریٰ کہتے ہیں ان سے بھی ہم نے عہد لیا تھا پھر وہ اس نصیحت سے نفع اٹھانا بھول گئے جو انہیں کی گئی تھی پھر ہم نے ان کے درمیان ایک دوسرے دشمنی اور بغض قیامت تک کے لیے ڈال دیا اور الله ان کا کیا ہوا انہیں جتلا دے گا'),
  ('ur.ahmedali', 5, 15, 'اے اہلِ کتاب تحقیق تمہارے پاس ہمارا رسول آیا ہے جو بہت سی چیزیں تم پر ظاہر کرتا ہے جنہیں تم کتاب سے چھاپتے تھے اوربہت سی چیزوں سے درگزرکرتا ہے بے شک تمہارے پاس الله کی طرف سے روشنی اور واضح کتاب آئی ہے'),
  ('ur.ahmedali', 5, 16, 'الله سلامتی کی راہیں دکھاتا ہے اسے جو اس کی رضا کا تابع ہو اور انہیں اپنے حکم سے اندھیروں سے روشنی کی طرف نکالتا ہے اور انہیں سیدھی راہ پر چلاتا ہے'),
  ('ur.ahmedali', 5, 17, 'بے شک وہ کافر ہوئے جنہوں نے کہا الله تو وہی مسیح مریم کا بیٹا ہے کہہ دے پھر الله کے سامنے کس کا بس چل سکتا ہے اگر وہ چاہے کہ مسیح مریم کے بیٹے اور اس کی ماں اور جتنے لوگ زمین میں ہیں سب کو ہلاک کر دے اور آسمانوں اور زمین اور ان دونوں کے درمیان کی سلطنت الله ہی کے واسطے ہے جو چاہے پیدا کرتا ہے اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 5, 18, 'اوریہود اور نصاریٰ کہتے ہیں کہ ہم الله کے بیٹے اور اس کے پیارے ہیں کہہ دو پھر تمہارے گناہوں کے باعث وہ تمہیں کیوں عذاب دیتا ہے بلکہ تم بھی اور مخلوقات کی طرح ایک آدمی ہو جسے چاہے بخش دے اور جسے چاہے سزا دے اور آسمانوں اور زمین اوران دونوں کے درمیان کی سلطنت الله ہی کے لیے ہے اور اسی کی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 5, 19, 'اے اہل کتاب تحقیق تمہارے پاس ہمارا پیغمبر آ یا جو تمہیں صاف صاف بتلاتا ہے ایسے وقت میں رسولوں کا سلسلہ موقوف تھا تاکہ تم یوں نہ کہنے لگو کہ ہمارے پاس کوئی خوشبخبری دینے والا اور ڈرانے والانہیں آیاسوتمہارےپاس خوشخبری دینے والااورڈرانےوالاآ گیا ہے اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 5, 20, 'اور جب موسیٰ نے اپنی قوم سے کہاکہ اے میری قوم الله کا احسان اپنے اوپر یاد کرو جب کہ تم میں نبی پیدا کیے اور تمہیں بادشاہ بنایا اور تمہیں وہ دیا جو جہان میں کسی کو نہ دیا تھا'),
  ('ur.ahmedali', 5, 21, 'اے میری قوم اس پاک زمین میں داخل ہو جاؤ جو الله نے تمہارے لیے مقرر کر دی اور پیچھے نہ ہٹو ورنہ نقصان میں جا پڑو گے'),
  ('ur.ahmedali', 5, 22, 'انہوں نے کہا اے موسیٰ بے شک وہاں ایک زبردست قوم ہے اور ہم وہاں ہرگز نہ جائیں گے یہاں تک کہ وہ وہاں سے نکل جائیں پھراگروہ وہاں سےنکل جائیں تو ہم ضرور داخل ہو ں گے'),
  ('ur.ahmedali', 5, 23, 'الله سے ڈرنے والوں میں سے دو مردوں نے کہا جن پر الله کا فضل تھا کہ ان پر حملہ کر کے دروازہ میں گھس جاؤ پھر جب تم اس میں گھس جاؤ گے تو تم ہی غالب ہو گے اور الله پر بھروسہ رکھو اگر تم ایمان دار ہو'),
  ('ur.ahmedali', 5, 24, 'کہا اے موسیٰ ہم کبھی وہاں داخل نہیں ہو ں گے جب تک کہ وہ اس میں ہیں سو تو اور تیرا رب جائے اور تم دونوں لڑو ہم تو یہیں بیٹھیں ہیں'),
  ('ur.ahmedali', 5, 25, 'موسیٰ نے کہا اے میرے رب میرے اختیار میں تو سوائے میری جان اور میرے بھائی کے اور کوئی نہیں سو ہمارے درمیان اور اس نافرمان قوم کے درمیان جدائی ڈال دے'),
  ('ur.ahmedali', 5, 26, 'فرمایا تحقیق وہ زمین ان پر چالیس بر س حرام کی گئی ہے اس ملک میں سرگرداں پھریں گے سو تو نافرمان قوم پر افسوس نہ کر'),
  ('ur.ahmedali', 5, 27, 'تو اہلِ کتاب کو آدم کے دو بیٹوں کا قصہ صحیح طور پر پڑھکر سنا دے جب ان دونوں نے قربانی کی ان میں سے ایک کی قربانی قبول ہو گئی اور دوسرے کی نہ ہوئی اس نے کہا میں تجھے مار ڈالوں گا اس نے جواب دیا الله پرہیز گاروں ہی سے قبول کرتا ہے'),
  ('ur.ahmedali', 5, 28, 'اگرتو مجھے قتل کرنے کے لیے ہاتھ اٹھائے گا تو میں تجھے قتل کرنے کے لیے ہاتھ نہ اٹھاؤں گا میں الله رب العالمین سے ڈرتا ہوں'),
  ('ur.ahmedali', 5, 29, 'میں چاہتا ہوں کہ میرا اور اپنا گناہ تو ہی سمیٹ لے اور دوزخی بن جائے اور ظالموں کی یہی سزا ہے'),
  ('ur.ahmedali', 5, 30, 'پھر اسے اس کے نفس نے اپنے بھائی کے خون پر راضی کر لیا پھر اسے مار ڈالا پس وہ نقصان اٹھانے والوں میں سے ہو گیا'),
  ('ur.ahmedali', 5, 31, 'پھر الله نے ایک کوا بھیجا جو زمین کریدتا تھا تاکہ اسے دکھلائے کہ اپنے بھائی کی لاش کو کس طرح چھپاتا ہے اس نے کہا افسوس مجھ پر اس کوے جیسا بھی نہ ہو سکا کہ اپنے بھائی کی لاش چھپانے کی تدبیر کرتا پھر پچھتانے لگا'),
  ('ur.ahmedali', 5, 32, 'اس سبب سے ہم نے بنی اسرائیل پر لکھا کہ جس نے کسی انسان کو خون کے بدلے یا زمین میں فساد پھیلانے کے سوا کسی اور وجہ سے قتل کیا گویا اس نے تمام انسانوں کو قتل کر دیا اورجس نے کسی کو زندگی بخشی اس نے گویا تمام انسانوں کی زندگی بخشی اورہمارے رسولوں ان کے پاس کھلے حکم لا چکے ہیں پھر بھی ان میں سے بہت لوگ زمین میں زیادتیاں کرنے والے ہیں'),
  ('ur.ahmedali', 5, 33, 'ان کی بھی یہی سزا ہے جو الله اوراس کے رسول سے لڑتے ہیں اورملک میں فساد کرنے کو دوڑتے ہیں یہ کہ ان کو قتل کیا جائے یا وہ سولی چڑھائے جائیں یا ان کے ہاتھ اور پاؤں مخالف جانب سے کاٹے جائیں یا وہ جلا وطن کر دیے جائیں یہ ذلت ان کے لیے دنیا میں ہے اور آخرت میں ان کے لیے بڑا عذاب ہے'),
  ('ur.ahmedali', 5, 34, 'مگر جنہوں نے تمہارے قابو پانے سے پہلے توبہ کر لی تو جان لو کہ الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 5, 35, 'اے ایمان والو الله سے ڈرو اور الله کا قرب تلاش کرو اور الله کی راہ میں جہاد کرو تاکہ تم کامیاب ہو جاؤ'),
  ('ur.ahmedali', 5, 36, 'بے شک جو لوگ کافر ہیں اگر ان کے پاس دنیا بھر کی چیزیں ہوں اور اس کے ساتھ اتنا ہی اور ہو تاکہ قیامت کے عذاب سے بچنے کے لیے بدلہ میں دیں تو بھی ان سے قبول نہ ہوگا اوران کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 5, 37, 'وہ چاہیں گے ُکہ آگ سے نکل جائیں حالانکہ وہ اس سے نکلنے والے نہیں اور ان کے لیے دائمی عذاب ہے'),
  ('ur.ahmedali', 5, 38, 'اور چور خواہ مرد ہو یا عورت دونوں کے ہاتھ کاٹ دو یہ ان کی کمائی کا بدلہ اور الله کی طرف سے عبرت ناک سزا ہے اور الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 5, 39, 'پھر جس نے اپنے ظلم کے بعد توبہ کی اور اصلاح کر لی تو الله اس کی توبہ قبول کر لے گا بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 5, 40, 'کیا تجھے معلوم نہیں کہ آسمانوں اور زمین کی سلطنت الله ہی کے واسطے ہے وہ جسے چاہے عذاب دے اور جسے چاہے بخش دے اور الله سب چیزوں پر قادر ہے'),
  ('ur.ahmedali', 5, 41, 'اے رسول انکا غم نہ کر جو دوڑ کر کفر میں گرتے ہیں وہ لوگ جو اپنے منہ سے کہتے ہیں کہ ہم مومن ہیں حالانکہ ان کے دل مومن نہیں ہیں اور وہ جو یہودی ہیں جھوٹ بولنے کے لیے جاسوسی کرتے ہیں وہ دوسری جماعت کے جاسوس ہیں جو تجھ تک نہیں آئی بات کو اس کےٹھکانے سے بدل دیتے ہیں کہتے ہیں کہ تمہیں یہ حکم ملے تو قبول کر لینا اور اگر یہ نہ ملے تو بچتے رہنا اور جسے الله گمراہ کرنا چاہے سو تو الله کے ہاں ا سکے لیے کچھ نہیں کر سکتا یہ وہی لوگ ہیں جن کے دل پاک کرنے کا الله نے ارادہ نہیں کیا ان کے لیے دنیا میں ذلت ہے اور آخرت میں بڑا عذا ب ہے'),
  ('ur.ahmedali', 5, 42, 'جھوٹ بولنے کے لیے جاسوسی کرنے والے ہیں اور بہت حرام کھانے والے ہیں سو اگر وہ تیرے پاس آئیں تو ان میں فیصلہ کر دے یا ان سے منہ پھیر لے اور اگر تو ان سے منہ پھیر لے گا تو وہ تیرا کچھ نہ بگاڑ سکیں گے اور اگر تو فیصلہ کرے تو ان میں انصاف سے فیصلہ کر بے شک الله انصاف کرنے والوں کو دوست رکھتا ہے'),
  ('ur.ahmedali', 5, 43, 'اور وہ تجھے کس طرح منصف بنائیں گے حالانکہ ان کے پاس تو تورات ہے جس میں الله کا حکم ہے پھر اس کے بعد ہٹ جاتے ہیں اور یہ مومن نہیں ہیں'),
  ('ur.ahmedali', 5, 44, 'ہم نے تورات نازل کی کہ اس میں ہدایت اور روشنی ہے اس پر پیغمبر جو الله کے فرمانبردار تھے یہود کو حکم کرتے تھے اور اس کی خبر گیری پر مقرر تھے سوتم لوگو ں سے نہ ڈرو اور مجھ سے ڈرو اور میری آیتوں کے بدلے میں تھوڑا مول مت لو اور جو کوئی اس کے موافق فیصلہ نہ کر لے جو الله نے اتارا تو وہی لوگ کافر ہیں'),
  ('ur.ahmedali', 5, 45, 'اور ہم نے ان پراس کتاب میں لکھا تھا کہ جان بدلے جان کے اور آنکھ بدلے آنکھ کے اور ناک بدلے ناک کے اور کان بدلے کان کے اور دانت بدلے دانت کے اور زخموں کا بدلہ ان کے برابر ہے پھر جس نے معاف کر دیا تو وہ گناہ سے پاک ہو گیا اور جو کوئی اس کے موافق حکم نہ کرے جو الله نے اتارا سو وہی لوگ ظالم ہیں'),
  ('ur.ahmedali', 5, 46, 'اور ہم نے ان کے پیچھے ان ہی کے قدموں پر عیسیٰ مریم کے بیٹے کو بھیجا جو اپنے سے پہلی کتاب تورات کی تصدیق کرنے والا تھا اور ہم نے اسے انجیل دی جس میں ہدایت اور روشنی تھی اپنے سے پہلی کتاب تورات کی تصدیق کرنے والا تھا اور راہ بتانے والی اور ڈرنے والوں کیلئے نصیحت تھی'),
  ('ur.ahmedali', 5, 47, 'اور چاہیئے کہ ابخیل والے اس کے موافق حکم کریں جو الله نےاس میں اتارا ہے اور جو چیز الله نے اتاری ہے جو شخص اس کے موافق حکم نہ کرے سو وہی لوگ نافرمان ہیں'),
  ('ur.ahmedali', 5, 48, 'ہم نے تجھ پر سچی کتاب اتاری جو اپنے سے پہلی کتابوں کی تصدیق کرنے والی ہے اور ان کے مضامین پر نگہبانی کرنے والی ہے سو تو ان میں اس کے موافق حکم کر جو الله نے اتارا ہے اور جو حق تیرے پاس آیا ہے اس سے منہ موڑ کر ان کی خواہشات کی پیروی نہ کر ہم نے تم میں سے ہر ایک کے لیے ایک شریعت اور واضح راہ مقرر کر دی ہے اور اگر الله چاہتا تو سب کو ایک ہی امت کر دیتا لیکن وہ تمہیں اپنے دیے ہوئے حکموں میں آزمانا چاہتا ہے لہذا نیکیوں میں ایک دوسرے سے بڑھنے کی کوشش کرو تو سب کو الله کے پاس پہنچنا ہے پھر تمہیں جتائے گا جس میں تم اختلاف کرتے تھے'),
  ('ur.ahmedali', 5, 49, 'اور فرمایا کہ تو ان میں اس کے موافق حکم کر جو الله نے تارا ہے اوران کی خواہشوں کی پیروی نہ کر اوران سے بچتا رہ کہ تجھے کسی ایسے حکم سے بہکا نہ دیں جو الله نے تجھ پر اتارا ہے پھر اگر یہ منہ موڑیں تو جان لو کہ الله کا اردہ انہیں ان کے بعض گناہوں کی پاداش میں مصیبت میں مبتلا کرنے کا ہے اور لوگوں میں بہت سے نافرمان ہیں'),
  ('ur.ahmedali', 5, 50, 'تو کیا پھر جاہلیت کا فیصلہ چاہتے ہیں حالانکہ جو لوگ یقین رکھنے والے ہیں ان کے ہاں الله سے بہتر اور کوئی فیصلہ کرنے والا نہیں'),
  ('ur.ahmedali', 5, 51, 'اے ایمان والو یہود اور نصاریٰ کو دوست نہ بناؤ وہ آپس میں ایک دوسرے کے دوست ہیں اور جو کوئی تم میں سے ان کے ساتھ دوستی کرے تو وہ ان میں سے ہے الله ظالموں کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 5, 52, 'پھر تو ان لوگوں کو دیکھے گا جن کے دلوں میں بیماری ہے ان میں دوڑ کر جا ملتے ہیں کہتے ہیں کہ ہمیں ڈر ہے کہ ہم پر زمانے کی گردش نہ آ جائے سو قریب ہے کہ الله جلدی فتح ظاہر فرماد ے یا کوئی اور حکم اپنے ہاں سے ظاہر کرے پھر یہ اپنے دل کی چھپی ہوئی بات پر شرمندہ ہوں گے'),
  ('ur.ahmedali', 5, 53, 'اور مسلمان کہتے ہیں کیا یہ وہی لوگ ہیں جو الله کے نام کی پکی قسمیں کھاتے تھے کہ ہم تمہارے ساتھ ہیں ان کے اعمال برباد ہو گئے پھر وہ نقصان اٹھانے والے ہو گئے'),
  ('ur.ahmedali', 5, 54, 'اے ایمان والو جو کوئی تم میں سے اپنے دین سے پھر جائے گا تو عنقریب الله ایسی قوم کو لائے گا کہ الله ان کو چاہتا ہے اور وہ اس کو چاہتے ہیں مسلمانوں پر نرم دل ہوں گے اور کافروں پر زبردست الله کی راہ میں لڑیں گے اور کسی کی ملامت سے نہیں ڈریں گے یہ الله کا فضل ہے جسے چاہے دیتا ہے اور الله کشائش والا جاننے والا ہے'),
  ('ur.ahmedali', 5, 55, 'تمہارا دوست تو الله اور اس کا رسول اور ایمان دار لوگ ہیں جو نماز قائم کرتے ہیں اور زکواة دیتے ہیں اور وہ عاجزی کرنے والے ہیں'),
  ('ur.ahmedali', 5, 56, 'اور جو شخص الله اور اس کے رسول اور ایمان داروں کو دوست رکھے تو الله کی جماعت وہی غالب ہونے والی ہے'),
  ('ur.ahmedali', 5, 57, 'اے ایمان والو! ان لوگوں کو اپنا دوست نہ بناؤ جنہوں نے تمہارے دین کو ہنسی اور کھیل بنا رکھا ہے ان لوگو ں میں سے جنہیں تم سے پہلے کتاب دی گئی اور کافروں کو اور الله سے ڈرو اگر تم ایمان دار ہو'),
  ('ur.ahmedali', 5, 58, 'اور جب تم نماز کے لیے پکارتے ہو تو وہ لوگ اس کے ساتھ ہنسی اور کھیل کرتے ہیں یہ ا س واسطے کہ وہ لوگ بے عقل ہیں'),
  ('ur.ahmedali', 5, 59, 'کہہ دو اے اہلِ کتاب تم ہم میں کون سا عیب پاتے ہو بجز اس کے کہ ہم الله پر ایمان لائے ہیں اوراس پر جو ہمارے پاس بھیجی گئی ہے اور اس پر جو پہلے بھیجی جا چکی ہے باوجود اس کے تم میں اکثر لوگ نافرمان ہیں'),
  ('ur.ahmedali', 5, 60, 'کہہ دو میں تم کو بتلاؤں الله کے ہاں ان میں سے کس کی بری جزا ہے وہی جس پر الله نے لعنت کی اور اس پر غضب نازل کیا اور بعضوں کو ان میں سے بندربنا دیا اور بعضوں کو سور اورجنہوں نے شیطان کی بندگی کی وہی لوگ درجہ میں بدتر ہیں اور راہِ راست سے بھی بہت دور ہیں'),
  ('ur.ahmedali', 5, 61, 'اور جب تمہارے پاس آتے ہیں تو کہتے ہیں کہ ہم ایمان لائے حالانکہ وہ کافر ہی آئے تھے اور کافر ہی گئے اور الله خوب جانتا ہے جو کچھ وہ چھپاتے تھے'),
  ('ur.ahmedali', 5, 62, 'اور تو ان میں سے اکثر کو دیکھے گا کہ گناہ اور ظلم پر اور حرام کھانے پر دوڑتے ہیں بہت برا ہے جو کچھ وہ کر رہے ہیں'),
  ('ur.ahmedali', 5, 63, 'ان کے فقراء اور علماء گناہ کی بات کہنے اور حرام مال کھانے سے انہیں کیوں نہیں منع کرتے البتہ بری ہے وہ چیز جو وہ کرتے ہیں'),
  ('ur.ahmedali', 5, 64, 'اور یہود کہتے ہیں الله کا ہاتھ بند ہوگیا ہے انہیں کے ہاتھ بند ہوں اور انہیں اس کہنے پر لعنت ہے بلکہ اس کے دونوں ہاتھ کھلے ہوئے ہیں جس طرح چاہے خرچ کرتا ہے جو کلام تیرے رب کی طرف سے تم پر نازل ہوا ہے وہ ان میں سے اکثر لوگوں کی سرکشی اور کفر میں زیادتی کا باعث بن گیا اور ہم نے ان کے درمیان قیامت تک عداوت اور دشمنی ڈال دی ہے جب کبھی لڑائی کے لیے آگ سلگاتے ہیں تو الله اس کو بجھا دیتا ہے یہ زمین میں فساد پھیلانے کی کوشش کرتے ہیں اور الله فساد کرنے والوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 5, 65, 'اور اگر اہل کتاب ایمان لاتے اور ڈرتے تو ہم ان میں سے ان کی برائياں دور کر دیتے اور ضرور انہیں نعمت کے باغوں میں داخل کر تے'),
  ('ur.ahmedali', 5, 66, 'اور اگر وہ تورات اور انجیل کوقائم رکھتے اور اس کو جو ان پر ان کے رب کی طرف سے نازل ہوا ہے تو اپنے اوپر سے اور اپنے پاؤں کے نیچے سے کھاتے کچھ لوگ ان میں سیدھی راہ پر ہیں اور اکثر ان میں سے برے کام کر رہے ہیں'),
  ('ur.ahmedali', 5, 67, 'اے رسول جو تجھ پر تیرے رب کی طرف سے اترا ہے اسے پہنچا دے اور اگر تو نے ایسا نہ کیا تو اس کی پیغمبری کا حق ادا نہیں کیا اور الله تجھے لوگوں سے بچائے گا بے شک الله کافروں کی قوم کو راستہ نہیں دکھاتا'),
  ('ur.ahmedali', 5, 68, 'کہہ دو اے اہل کتاب تم کسی راہ پر نہیں ہو جب تک کہ تم تورات اور انجیل اور جو چیز تمہارے رب کی طرف سے نازل کی گئی ہے قائم نہ کرو اور ضرور ہے کہ یہ فرمان جو تم پرنازل ہوا ہے ان میں سے اکثر کی سرکشی اور انکار کو اور زيادہ بڑھائے گا مگر انکار کرنے والاوں کے حال پر کچھ افسوس نہ کرو'),
  ('ur.ahmedali', 5, 69, 'بے شک جو مسلمان ہیں اور جو یہودی ہیں اور صائبی اور نصاریٰ جو کوئی الله اور قیامت پر ایمان لایا اور نیک کام کیے تو ان پر کوئی خوف نہیں ہوگا اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 5, 70, 'ہم نے بنی اسرائیل سے پختہ وعدہ لیا تھا اور ان کی طرف کئی رسول بھیجے تھے جب کبھی کوئی رسول ان کے پاس وہ حکم لایا جو ان کے نفس نہیں چاہتے تھے تو ایک جماعت کو جھٹلایا اور ایک جماعت کو قتل کر ڈالا'),
  ('ur.ahmedali', 5, 71, 'اور یہی گمان کیا کہ کوئی فتنہ نہیں ہوگا پھر اندھے اور بہرے ہوئے پھر الله نے ان کی توبہ قبول کی پھر ان میں سے اکثر اندھے اور بہرے ہو گئے اور جو کچھ وہ کرتے ہیں الله دیکھتا ہے'),
  ('ur.ahmedali', 5, 72, 'البتہ تحقیق وہ لوگ کافر ہوئے جنہوں نے کہا بے شک الله وہی مسیح مرین کا بیٹا ہی ہے حالانکہ مسیح نے کہا اے بنی اسرائیل اس الله کی بندگی کرو جو میرا اور تمہارا رب ہے بے شک جس نے الله کا شریک ٹھیرایا سو الله نے اس پر جنت حرام کی اور اس کا ٹھکانا دوزخ ہے اور ظالموں کا کوئی مددگار نہیں ہو گا'),
  ('ur.ahmedali', 5, 73, 'جنہوں نے کہا الله تین میں سے ایک ہے بے شک وہ کافر ہوئے حالانکہ سوائے ایک معبود کے اورکوئی معبود نہیں اور اگر وہ اس بات سے باز نہ آئيں گے جو وہ کہتے ہیں تو ان میں سے کفر پر قائم رہنے والوں کو دردناک عذاب پہنچے گا'),
  ('ur.ahmedali', 5, 74, 'الله کے آگے کیوں توبہ نہیں کرتے اور اس سے گناہ نہیں بخشواتے اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 5, 75, 'مسیح مریم کا بیٹا تو صرف ایک پیغمبر ہی ہے جس سے پہلے اور بھی پیغمبر گزر چکے ہیں اور اس کی ماں ولی ہے وہ دونوں کھانا کھاتے تھے دیکھ ہم انہیں کیسی دلیلیں بتلاتے ہیں پھر دیکھووہ کہاں الٹے جا تے ہیں'),
  ('ur.ahmedali', 5, 76, 'کہہ دو تم الله کر چوڑ کر ایسی چیز کی بندگی کرتے ہو جو تمہارے نقصان اور نفع کے مالک نہیں اور الله وہی ہے سننے والا جاننے والا'),
  ('ur.ahmedali', 5, 77, 'کہہ اے اہلِ کتاب تم اپنے دین میں ناحق زیادتی مت کرو اور ان لوگو ں کی خواہشات کی پیروی نہ کرو جو اس سے پہلے گمراہ ہو چکے اور انہوں نے بہتوں کو گمراہ کیا اور سیدھی راہ سے دور ہو گئے'),
  ('ur.ahmedali', 5, 78, 'بنی اسرائیل میں سے جو کافر ہوئے ان پر داؤد اور عیسیٰ بیٹے مریم کی زبان پر لعنت کی گئی یہ اس لیے کہ وہ نافرمان تھے اور حد سے گزر گئے تھے'),
  ('ur.ahmedali', 5, 79, 'آپس می ں برے کام سے منع نہ کرتے تھے جو وہ کر رہے تھے کیسا ہی برا کام ہےجووہ کرتے تھے'),
  ('ur.ahmedali', 5, 80, 'تو دیکھے گا تو ان میں سے بہت سے لوگ کافروں سے دوستی رکھتے ہیں انہوں نے کیسا ہی برا سامان اپنے نفسوں کے لیے آگے بھیجا اور وہ یہ کہ ان پر الله کا غضب ہوا اور وہ ہمیشہ عذاب میں رہنے والے ہیں'),
  ('ur.ahmedali', 5, 81, 'اور اگر وہ الله اور نبی پر اور اس چیز پر جواس کی طرف سے نازل کی گئی ہے ایمان لاتے تو کافروں کو دوست نہ بناتے لیکن ان میں سے اکثر لوگ نافرمان ہیں'),
  ('ur.ahmedali', 5, 82, 'تو سب لوگو ں سے زیادہ مسلمانوں کا دشمن یہودیوں اور مشرکوں کو پائے گا اور تو سب سے نزدیک محبت میں مسلمانوں سے ان لوگوں کو پائے گا جو کہتے ہیں کہ ہم نصاریٰ ہیں یہ اس لیے اکہ ان میں علماء اور فقراء ہیں اور اس لیے کہ وہ تکبر نہیں کرتے'),
  ('ur.ahmedali', 5, 83, 'اور جب اس چیز کو سنتے ہیں جو رسول پر اتری تو ان کی آنکھوں کو دیکھے گا کہ آنسوؤں سے بہتی ہیں اس لیے کہ انہوں نے حق کو پہچان لیا کہتے ہیں اے رب ہمارے کہ ہم ایمان لائے تو ہمیں ماننے والوں کے ساتھ لکھ لے'),
  ('ur.ahmedali', 5, 84, 'اور ہمیں کیا ہے ہم الله پر ایمان نہ لائيں اور اس چیز پر جو ہمیں حق سے پہنچی ہے اور اس کی طمع رکھتے ہیں کہ ہمیں ہمارا رب نیکو ں میں داخل کر ے گا'),
  ('ur.ahmedali', 5, 85, 'پھر الله نے انہیں اس کہنے کے بدلے ایسے باغ دئیے کہ جن کے نیچے نہریں بہتی ہیں ان میں ہمیشہ رہیں گے اور نیکی کرنے والوں کا یہی بدلہ ہے'),
  ('ur.ahmedali', 5, 86, 'اور وہ لوگ جو کافر ہوئے اور ہماری آیتوں کو جھٹلایا وہ دوزخ کے رہنے والے ہیں'),
  ('ur.ahmedali', 5, 87, 'اے ایمان والو ان ستھری چیزوں کو حرام نہ کرو جو الله نے تمہارے لیے حلال کی ہیں اور حد سے نہ بڑھو بے شک الله حد سے بڑھنے والوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 5, 88, 'اور الله کے رزق میں سے جو چیز حلال ستھری ہو کھاؤ اور الله سے ڈرو جس پر تم ایمان رکھتے ہو'),
  ('ur.ahmedali', 5, 89, 'الله تمہیں تمہاری بی ہودہ قسموں پر نہیں پکڑتا لیکن ان قسموں پرپکڑتا ہے جنہیں تم مستحکم کر دو سو اس کا کفارہ دس مسکینوں کو اوسط درجہ کا کھانا دینا ہے جو تم اپنے گھر والوں کو دیتے ہو یا دس مسکینوں کو کپڑا پہنانا یا گردن آزاد کرنی پھر جو شخص یہ نہ پائے تو تین دن کے روزے رکھنے ہیں اسی طرح تمہای قسموں کا کفارہ ہے جب تم قسم کھاؤ اور اپنی قسموں کی حفاظت کرو اسی طرح تمہارے لیے اپنے حکم بیان کرتا ہے تاکہ تم شکر کرو'),
  ('ur.ahmedali', 5, 90, 'اے ایمان والو شراب اور جوا اور بت اور فال کے تیر سب شیطان کے گندے کام ہیں سو ان سے بچتے رہو تاکہ تم نجات پاؤ'),
  ('ur.ahmedali', 5, 91, 'شیطان تو یہی چاہتا ہے کہ شراب اور جوئے کے ذریعے سےتم میں دشمنی اور بغض ڈال دے اور تمہیں الله کی یاد سے اور نماز سے روکے سو اب بھی باز آجاؤ'),
  ('ur.ahmedali', 5, 92, 'اور الله اور رسول کا حکم مانو اور بچتے رہو پھر اگر تم پھر جاوگےتوجان لو کہ ہمارے رسول کے ذمہ صرف کھول کر پہنچا دینا ہی ہے'),
  ('ur.ahmedali', 5, 93, 'جو لو گ ایمان لائے اور نیک کام کیے ان پر اس میں کوئی گناہ نہیں جو پہلے کھا چکے جب کہ آئندہ کو پرہیزگار ہوئے اور ایمان لائے اور عمل نیک کیے پھر پرہیزگار ہوئے اور نیکی کی اور الله نیکی کرنے والوں کو دوست رکھتا ہے'),
  ('ur.ahmedali', 5, 94, 'اے ایمان والو! البتہ ایک بات سے تمہیں آزمائے گا اس شکار سے جس پر تمہارے ہاتھ اور تمہارے نیزے پہنچیں گے تاکہ الله معلوم کرے کہ بن دیکھے اس سے کون ڈرتا ہے پھر جس نے اس کے بعد زیادتی کی تو اس کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 5, 95, 'اے ایمان والو! جس وقت تم احرام میں ہو تو شکار کونہ قتل کرو اور جو کوئی تم میں سے اسےجان بوجھ کر مارے تو اس مارے ہوئے کے برابر مویشی میں سے اس پر بدلہ لازم ہے جو تم میں سے دو معتبر آدمی تجویز کریں بشرطیکہ قربانی کعبہ تک پہنچنے والی ہو یا کفارہ مسکینوں کا کھانا کھلانا ہو یا اس کے برابر روزے تاکہ اپنے کام کا وبال چکھے الله نے اس چیز کو معاف کیا جو گزر چکی اور جو کوئی پھر کرے گا الله اس سے بدلہ لے گا اور الله غالب بدلہ لینے والا ہے'),
  ('ur.ahmedali', 5, 96, 'تمہارے لیے دریا کا شکار کرنا اوراس کا کھانا حلال کیا گیا ہے تمہارے واسطے اور مسافروں کے لیے فائدہ ہے اور تم پر جنگل کا شکار کرناحرام کیا گیا ہے جب تک کہ تم احرام میں ہو اور اس الله سے ڈرو جس کی طرف جمع کیے جاؤ گے'),
  ('ur.ahmedali', 5, 97, 'الله نے کعبہ کو جو بزرگی والا گھر ہے لوگوں کے لیے قیام کا باعث کر دیا ہے اور عزت والے مہینے کو اور حرم میں قربانی والے جانور کو بھی اور جن کے گلے میں پٹہ ڈال کر کر کعبہ کو لے جائیں یہ اس لیے ہے کہ تم جان لو کہ بے شک الله کو معلوم ہے کہ جو کچھ آسمانوں اور زمین میں ہے اور بے شک الله ہر چیز کو جاننے والا ہے'),
  ('ur.ahmedali', 5, 98, 'جان لو بے شک الله سخت عذاب والا ہے اور بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 5, 99, 'رسول کے ذمہ سوائے پہنچانے کے اورکچھ نہیں اور الله کو معلوم ہے جو تم ظاہر کرتے ہو اور جو چھپ کر کرتے ہو'),
  ('ur.ahmedali', 5, 100, 'کہہ دو کہ ناپاک اور پاک برابر نہیں اگرچہ تمہیں ناپاک کی کثرت بھی معلوم ہو سو اے عقل مندو الله سے ڈرتے رہو تاکہ تمہاری نجات ہو'),
  ('ur.ahmedali', 5, 101, 'اے ایمان والو! ایسی بات مت پوچھو کہ اگر تم پر ظاہر کی جائیں تو تمہیں بری لگیں اور اگر یہ باتیں یسے وقت میں پوچھو گے جب کہ قرآن نازل ہو رہا ہے تو تم پر ظاہر کر دی جائیں گی گذشتہ سوالات الله نے معاف کر دیے ہیں اور الله بخشنے والا بردبار ہے'),
  ('ur.ahmedali', 5, 102, 'ایسی باتیں تم سے پہلے ایک جماعت پوچھ چکی ہے پھر وہ ان باتوں کے وہ مخالف ہوگئے'),
  ('ur.ahmedali', 5, 103, 'الله نے بحیرہ اور سائبہ اور وصیلہ اور حام مقرر نہیں کیے لیکن کافر الله پر بہتان باندھتے ہیں اور ان میں سے اکثر بیوقوف ہیں'),
  ('ur.ahmedali', 5, 104, 'اور جب انہیں کہا جاتا ہے اس کی طرف آؤ جو الله نے نازل کیا ہ اور رسول کی طرف تو کہتے ہیں ہمیں وہ کافی ہے جس پر ہم نے باپ دادا کو پایا بھلا اگر چہ ان کے باپ دادانہ کچھ علم رکھتے ہوں نہ انہوں نے ہدایت پائی ہو تو بھی ایسا ہی کریں گے'),
  ('ur.ahmedali', 5, 105, 'اے ایمان والو! تم پر اپنی جان کی فکر لازم ہے تمہارا کچھ نہیں بگاڑتا جو کوئی گمراہ ہو جب کہ تم ہدایت یافتہ ہو تم سب کو الله کی طرف لوٹ کر جانا ہے پھر وہ تمہیں بتلا دے گا جو کچھ تم کرتے تھے'),
  ('ur.ahmedali', 5, 106, 'اے ایمان والو! جب کہ تم میں سے کسی کو موت آ پہنچے تو وصیت کے وقت تمہارے درمیان تم میں سے معتبر آدمی گواہ ہو نے چاہیئیں یا تمہارے سوا دو گواہ اور ہوں اگر تم نے زمین پر سفر کیاہو پھر تمہیں موت کی مصیبت آ پہچنے ان دونوں کو نماز کے بعد کھڑا کرو وہ دونوں الله کی قسمیں کھائیں اگر تمہیں کہیں شبہ ہو کہ ہم قسم کے بدلے مال نہیں لیتے اگرچہ رشتہ داری ہی کیوں نہ ہو اور ہم الله کی گواہی نہیں چھپاتے ورنہ ہم بے شک گناہگار ہوں گے'),
  ('ur.ahmedali', 5, 107, 'پھر اگر اس بات کی اطلاع ہو جائے کہ وہ دونوں گناہ کے مستحق ہوئے تو ان کی جگہ اور دو گواہ کھڑےہوں ان میں سے جن کا حق دبایا گیا ہے جو سب سے زیادہ میت کے قریب ہوں پھر الله کی قسم کھائیں کہ ہماری گواہی ان کی گواہی سے زیادہ سچی ہے اور ہم نے زیادتی نہیں کی ورنہ ہم بے شک ظالموں میں سے ہوں گے'),
  ('ur.ahmedali', 5, 108, 'یہ اس امر کا قریب ذریعہ ہے کہ وہ لوگ واقع کو ٹھیک طور پر ظاہر کر دیں یہ اس بات سے ڈر جائیں کہ قسمیں ان کی قسموں کے بعد رد کی جائیں گی ارو الله سے ڈرتے رہو اور سنو اور الله نافرمانوں کو سیدھی راہ پر نہیں چلاتا'),
  ('ur.ahmedali', 5, 109, 'جن دن الله سب پیغمبروں کو جمع کرے گا پھر کہے گا تمہیں کیا جواب دیا گیا تھا وہ کہیں گے ہمیں کچھ خبر نہیں تو ہی چھپی باتو ں کا جاننے والا ہے'),
  ('ur.ahmedali', 5, 110, 'جب الله کہے گا اے عیسیٰ مریم کے بیٹے میرا احسان یاد کر جو تجھ پر اور تیری ماں پر ہوا ہےجب میں نے روح پاک سے تیری مدد کی تو لوگوں سے گود میں اور ادھیڑ عمر میں بات کرتا تھا اور جب میں نے تجھے کتاب اورحکمت اور تورات اور انجیل سکھائی اور جب تو مٹی سے جانور کی صورت میرے حکم سے بناتا تھا پھرتو اس میں پھونک مارتا تھا تب وہ میرے حکم سے اڑنے والا ہو جاتا تھا اور مادر زاد اندھے کو اور کوڑھی کومیرے حکم سے اچھا کرتا تھا اور جب مردوں کو میرے حکم سے نکال کھڑا کرتا تھا اور جب میں نے بنی اسرائیل کو تجھ سے روکا جب تو ان کے پاس نشانیاں لے کر آیا تو جو ان میں کافر تھے وہ کہنے لگے اور کچھ نہیں یہ تو صریح جادو ہے'),
  ('ur.ahmedali', 5, 111, 'اورجب میں نے حواریوں کے دل میں ڈال دیا کہ مجھ پر اور میرے رسول پر ایمان لاؤ تو کہنے لگے ہم یمان لائے اور تو گواہ رہے کہ ہم الله کے فرمانبردار ہیں'),
  ('ur.ahmedali', 5, 112, 'جب حواریوں نے کہا اے عیسیٰ مریم کے بیٹے کیا تیرا رب کر سکتا ہے کہ ہم پر خوان بھرا ہوا آسمان سے اتارے کہا الله سے ڈرو اگر تم ایمان دار ہو'),
  ('ur.ahmedali', 5, 113, 'انہوں نے کہا ہم چاہتے ہیں کہ اس میں سے کھائیں اور ہمارے دل مطمئن ہو جائیں اور ہم جان لیں کہ تو نے ہم سے سچ کہا ہے اور ہم اس پر گواہ ر ہیں'),
  ('ur.ahmedali', 5, 114, 'عیسیٰ مریم کے بیٹے نے کہا اے اللهرب ہمارے ہم پر بھرا ہوا خوان آسمان سے اتار جو ہمارے پہلوں اور پچھلوں کیلئے عید ہو اور تیری طرف سےایک نشانی ہو اور ہمیں رزق دے اور تو ہی سب سے بہتر رزق دینے والا ہے'),
  ('ur.ahmedali', 5, 115, 'الله نے فرمایا بے شک میں وہ خوان تم پر اتارو ں گا پھر اس کے بعد جو کوئی تم میں سے ناشکری کرے گا تو میں اسے ایسی سزا دوں گا جو دنیا میں کسی کو نہ دی ہو گی'),
  ('ur.ahmedali', 5, 116, 'اور جب الله فرمائے گا اے عیسیٰ مریم کے بیٹے کیا تو نے لوگو ں سے کہا تھا کہ خدا کے سوا مجھے اور میری ماں کو بھی خدا بنا لو وہ عرض کرے گا تو پاک ہے مجھے لائق نہیں ایسی بات کہوں کہ جس کا مجھے حق نہیں اگر میں نے یہ کہا ہوگا تو تجھے ضرور معلوم ہو گا جو میرے دل میں ہے تو جانتا ہے اور جو تیرے دل میں ہے وہ میں نہیں جانتا بے شک تو ہی چھپی ہوئی باتو ں کا جاننے والا ہے'),
  ('ur.ahmedali', 5, 117, 'میں نے ان سے اس کے سوا کچھ نہیں کہا جس کا تو نے مجھے حکم دیا تھا کہ الله کی بندگی کرو جو میرا اور تمہارا رب ہے اور میں اس وقت تک ان کا نگران تھا جب تک ان میں رہا پھر جب تو نے مجھے اٹھا لیا تو تو ہی ان کا نگران تھا اور تو ہر چیز سے خبردار ہے'),
  ('ur.ahmedali', 5, 118, 'اگر تو انہیں عذاب دے تو وہ تیرے ہی بندے ہیں اور اگر تو انہیں معاف کر دے تو تو ہی زبردست حکمت والا ہے'),
  ('ur.ahmedali', 5, 119, 'الله فرمائے گا یہ وہ دن ہے جس میں سچوں کو ان کا سچ کام آئے گا ان کے لیے باغ ہیں جن کے نیچے نہریں بہتی ہیں ان میں سے ہمیشہ رہنے والے ہوں گے ان سے الله راضی ہوا اور وہ اس سے راضی ہوئے یہی بڑی کامیابی ہے'),
  ('ur.ahmedali', 5, 120, 'آسمانوں اور زمین اور جو کچھ ان کے درمیان ہے سب الله ہی کی سلطنت ہے اور وہ ہرچیز پر قادر ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 5, 1, 'Ey İnananlar! Akidleri yerine getirin. İhramda iken avlanmayı helal görmeksizin, size bildirilecek olanlar dışında, hayvanlar helal kılındı; Allah dilediği hükmü verir.'),
  ('tr.diyanet', 5, 2, 'Ey İnananlar! Allah\'ın nişanelerine, hürmet edilen aya, hediye olan kurbanlığa, gerdanlıklar takılan hayvanlara, Rab\'lerinden bol nimet ve rıza talep ederek Beyt-i Haram\'a gelenlere sakın hürmetsizlik etmeyin. İhramdan çıktığınız zaman avlanabilirsiniz. Sizi Mescid-i Haram\'dan menettiği için bir topluluğa olan kininiz, aşırı gitmenize sebep olmasın; iyilikte ve fenalıktan sakınmakta yardımlaşın, günah işlemek ve aşırı gitmekte yardımlaşmayın. Allah\'tan sakının, Allah\'ın cezası şiddetlidir.'),
  ('tr.diyanet', 5, 3, 'Leş, kan, domuz eti, Allah\'tan başkası adına kesilenler, -canları çıkmadan önce kesmemişseniz, boğulmuş, bir yerine vurularak öldürülmüş, düşüp yuvarlanmış, başka bir hayvan tarafından süsülmüş, yırtıcı hayvan tarafından yenmiş olanları- dikili taşlar üzerine boğazlananlar ile fal oklarıyla kısmet aramanız size haram kılındı; bunlar fasıklıktır. Bugün, inkar edenler sizi dininizden etmekten umutlarını kesmişlerdir, onlardan korkmayın, Benden korkun. Bugün, size dininizi bütünledim, üzerinize olan nimetimi tamamladım, din olarak sizin için İslam\'ı beğendim. Açlıktan darda kalan, günaha kaymaksızın yiyebilir. Doğrusu Allah Bağışlayan\'dır, merhametli olandır.'),
  ('tr.diyanet', 5, 4, 'Sana, kendilerine neyin helal kılındığını soruyorlar, de ki: Size temiz olanlar helal kılındı; Allah\'ın size öğrettiği üzere alıştırıp yetiştirerek öğrettiğiniz avcı hayvanların sizin için tuttuklarını yiyin ve üzerine Allah\'ın adını anın. Allah\'tan sakının, doğrusu Allah hesabı çabuk görür.'),
  ('tr.diyanet', 5, 5, 'Bugün, size temiz olanlar helal kılındı. Kitap verilenlerin yemeği size helal, sizin yemeğiniz de onlara helaldir. İnanan hür ve iffetli kadınlar ve sizden önce kitap verilenlerin hür ve iffetli kadınları -zina etmeksizin, gizli dost tutmaksızın ve mehirlerini verdiğiniz takdirde- size helaldir. Kim imanı inkar ederse, şüphesiz amelleri boşa gider. O, ahirette de kaybedenlerdendir.'),
  ('tr.diyanet', 5, 6, 'Ey İnananlar! Namaza kalktığınızda yüzlerinizi, dirseklere kadar ellerinizi, -başlarınızı meshedip- topuk kemiklerine kadar ayaklarınızı yıkayın. Eğer cünüpseniz yıkanıp temizlenin; şayet hasta veya yolculukta iseniz veya ayak yolundan gelmişseniz yahut kadınlara yaklaşmışsanız ve su bulamamışsanız temiz bir toprağa teyemmüm edin, yüzlerinizi, ellerinizi onunla meshedin. Allah sizi zorlamak istemez, Allah sizi arıtıp üzerinize olan nimetini tamamlamak ister ki şükredesiniz.'),
  ('tr.diyanet', 5, 7, 'Allah\'ın size olan nimetini ve "İşittik, itaat ettik" dediğinizde sizi andına bağladığı sözünü anın. Allah\'tan sakının, Allah içinizde olanı elbette bilir.'),
  ('tr.diyanet', 5, 8, 'Ey İnananlar! Allah için adaleti ayakta tutup gözeten şahidler olun. Bir topluluğa olan öfkeniz sizi adaletsizliğe sürüklemesin; adil olun; bu, Allah\'a karşı gelmekten sakınmaya daha yakındır. Allah\'tan sakının, doğrusu Allah işlediklerinizden Haberdar\'dır.'),
  ('tr.diyanet', 5, 9, 'Allah, inananlara ve yararlı işler işleyenlere mağfiret ve büyük ecir olduğunu vadetmiştir.'),
  ('tr.diyanet', 5, 10, 'İnkar edenler ve ayetlerimizi yalanlayanlar, işte onlar cehennemliklerdir.'),
  ('tr.diyanet', 5, 11, 'Ey İnananlar! Allah\'ın üzerinize olan nimetini anın: Hani bir topluluk size tecavüze kalkışmıştı da Allah onlara mani olmuştu. Allah\'tan sakının, inananlar Allah\'a güvensinler.'),
  ('tr.diyanet', 5, 12, 'And olsun ki, Allah, İsrailoğullarından söz almıştı. Onlardan oniki reis seçtik. Allah: "Ben şüphesiz sizinleyim, namaz kılarsanız, zekat verirseniz, peygamberlerime inanır ve onlara yardım ederseniz, Allah uğrunda güzel bir takdimede bulunursanız, and olsun ki kötülüklerinizi örterim. And olsun ki, sizi içlerinden ırmaklar akan cennetlere koyarım. Bundan sonra sizden kim inkar ederse şüphesiz doğru yoldan sapmış olur" dedi.'),
  ('tr.diyanet', 5, 13, 'Sözlerini bozdukları için onlara lanet ettik, kalblerini katılaştırdık. Onlar sözleri yerlerinden değiştirirler. Kendilerine belletilenin bir kısmını unuttular. İçlerinden pek azından başkasının daima hainliklerini görürsün, onları affet ve geç. Allah iyilik yapanları şüphesiz sever.'),
  ('tr.diyanet', 5, 14, '"Biz hıristiyanız" diyenlerden de söz almıştık; onlar, kendilerine belletilenin bir kısmını unuttular, bu yüzden aralarına kıyamete kadar düşmanlık ve kin saldık. Allah, yapmakta olduklarını kendilerine haber verecektir.'),
  ('tr.diyanet', 5, 15, 'Ey Kitap ehli! Kitap\'dan gizleyip durduğunuzun çoğunu size açıkça anlatan ve çoğundan da geçiveren peygamberimiz gelmiştir. Doğrusu size Allah\'tan bir nur ve apaçık bir Kitap gelmiştir.'),
  ('tr.diyanet', 5, 16, 'Allah, rızasını gözetenleri onunla, selamet yollarına eriştirir ve onları, izni ile, karanlıklardan aydınlığa çıkarır. Onları doğru yola iletir.'),
  ('tr.diyanet', 5, 17, '"Allah ancak Meryem oğlu Mesih\'tir" diyenler and olsun ki kafir olmuşlardır. De ki: "Allah Meryem oğlu Mesih\'i, anasını ve yeryüzünde olanların hepsini yok etmeyi dilerse kim O\'na karşı koyabilir?" Göklerin, yerin ve arasındakilerin hükümranlığı Allah\'ındır, dilediğini yaratır. Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 5, 18, 'Yahudiler ve hıristiyanlar, "Biz Allah\'ın oğulları ve sevgilileriyiz" dediler. "Öyleyse günahlarınızdan ötürü size niçin azabediyor? Bilakis siz O\'nun yarattığı insanlarsınız" de, Allah dilediğini bağışlar, dilediğine azab eder. Göklerin, yerin ve ikisinin arasındakilerin hükümranlığı Allah\'ındır. Dönüş O\'nadır.'),
  ('tr.diyanet', 5, 19, 'Ey Kitap ehli! Peygamberlerin arası kesildiğinde, "Bize müjdeci ve uyarıcı gelmedi" dersiniz diye, size açıkça anlatacak peygamberimiz geldi. Şüphesiz O, size müjdeci ve uyarıcı olarak gelmiştir. Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 5, 20, 'Musa, milletine: "Ey milletim! Allah\'ın size olan nimetini anın: içinizden peygamberler çıkarmış ve sizi hükümdar yapmıştır, dünyalarda kimseye vermediğini size vermiştir".'),
  ('tr.diyanet', 5, 21, '"Ey milletim! Allah\'ın size yazdığı kutsal yere girin, ardınıza dönmeyin, yoksa kaybedenler olarak dönersiniz" demişti.'),
  ('tr.diyanet', 5, 22, '"Ey Musa! Orada zorba bir millet vardır, onlar oradan çıkmadıkça biz oraya girmeyeceğiz, eğer çıkarlarsa, biz de gireriz" demişlerdi.'),
  ('tr.diyanet', 5, 23, 'Korkanlar arasında bulunan, Allah\'ın nimete erdirdiği iki adam: "Üstlerine kapıdan yürüyün, oradan girerseniz şüphesiz galip gelirsiniz; eğer inanıyorsanız Allah\'a güvenin" demişlerdi.'),
  ('tr.diyanet', 5, 24, '"Ey Musa! Onlar orada oldukça biz asla oraya girmeyeceğiz. Sen ve Rabbin gidin savaşın, doğrusu biz burada oturacağız" demişlerdi.'),
  ('tr.diyanet', 5, 25, 'Musa: "Rabbim! Ben ancak kendime ve kardeşime söz geçirebiliyorum; artık bizimle bu yoldan çıkmış milletin arasını ayır" dedi.'),
  ('tr.diyanet', 5, 26, 'Allah: "Orası onlara kırk yıl haram kılındı; yeryüzünde şaşkın şaşkın dolaşacaklar. Sen, yoldan çıkmış millet için tasalanma" dedi.'),
  ('tr.diyanet', 5, 27, 'Onlara, Adem\'in iki oğlunun kıssasını doğru olarak anlat: İkisi birer kurban sunmuşlar, birininki kabul edilmiş, diğerininki edilmemişti. Kabul edilmeyen, "And olsun seni öldüreceğim" deyince, kardeşi: "Allah ancak sakınanların takdimesini kabul eder" demişti.'),
  ('tr.diyanet', 5, 28, '"Beni öldürmek üzere elini bana uzatırsan, ben seni öldürmek için sana elimi uzatmam, çünkü ben, Alemlerin Rabbi olan Allah\'tan korkarım.'),
  ('tr.diyanet', 5, 29, 'Ben, hem benim hem de kendi günahını yüklenip cehennemliklerden olmanı isterim, zulmedenlerin cezası budur".'),
  ('tr.diyanet', 5, 30, 'Bunun üzerine, kardeşini öldürmekte nefsine uydu ve onu öldürerek, zarara uğrayanlardan oldu.'),
  ('tr.diyanet', 5, 31, 'Allah, kardeşinin ölüsünü nasıl gömeceğini göstermek üzere, ona yeri eşeleyen bir karga gönderdi. "Bana yazıklar olsun! Kardeşimin ölüsünü örtmek için bu karga kadar olmaktan aciz kaldım" dedi de ettiğine yananlardan oldu.'),
  ('tr.diyanet', 5, 32, 'Bunun için İsrailoğullarına şöyle yazdık: "Kim bir kimseyi bir kimseye veya yeryüzünde bozgunculuğa karşılık olmadan öldürürse, bütün insanları öldürmüş gibi olur. Kim de onu diriltirse (ölümden kurtarırsa) bütün insanları diriltmiş gibi olur". And olsun ki, onlara belgelerle peygamberlerimiz geldi, sonra buna rağmen, onların çoğu yeryüzünde taşkınlık edenler oldu.'),
  ('tr.diyanet', 5, 33, 'Allah ve Peygamberiyle savaşanların ve yeryüzünde bozgunculuğa uğraşanların cezası öldürülmek veya asılmak yahut çapraz olarak el ve ayakları kesilmek ya da yerlerinden sürülmektir. Bu onlara dünyada bir rezilliktir. Onlara ahirette büyük azab vardır.'),
  ('tr.diyanet', 5, 34, 'Ancak, onları yakalamanızdan önce tevbe edenler bunun dışındadır. Biliniz ki Allah, bağışlar ve merhamet eder.'),
  ('tr.diyanet', 5, 35, 'Ey İnananlar! Allah\'tan sakının, O\'na ulaşmaya yol arayın, yolunda cihad edin ki kurtulasınız.'),
  ('tr.diyanet', 5, 36, 'Doğrusu, yeryüzünde olan bütün şeyler ve onların bir katı daha kafirlerin olsa da, kıyamet gününün azabından kurtulmak için fidye verseler kabul edilmez. Onlara elem verici azab vardır.'),
  ('tr.diyanet', 5, 37, 'Ateşten çıkmak isterler, çıkamazlar. Onlara sürekli azab vardır.'),
  ('tr.diyanet', 5, 38, 'Erkek hırsız ve kadın hırsızın, yaptıklarından ötürü Allah tarafından ibret verici bir ceza olarak, ellerini kesin. Allah Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 5, 39, 'Ettiği zulümden sonra tevbe edip düzelen kimse, bilsin ki Allah onun tevbesini kabul eder. Allah şüphesiz Bağışlayan\'dır, merhametli olandır.'),
  ('tr.diyanet', 5, 40, 'Göklerin ve yerin hükümranlığının Allah\'ın olduğunu bilmiyor musun? Dilediğine azabeder, dilediğini bağışlar. Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 5, 41, 'Kalbleri inanmamışken, ağızlarıyla, "İnandık" diyenler, yahudilerden yalana kulak verenler ve başka bir topluluk hesabına casusluk edenlerden inkara koşanlar seni üzmesin. Sözleri asıl yerlerinden değiştirirler de, "Böyle bir fetva size verilirse alın, verilmezse kaçının" derler. Allah\'ın fitneye düşmesini dilediği kimse için Allah\'a karşı senin elinden bir şey gelmez. İşte onlar Allah\'ın, kalblerini arıtmak istemediği kimselerdir. Dünyada rezillik onlaradır. Onlara ahirette de büyük azab vardır.'),
  ('tr.diyanet', 5, 42, 'Onlar yalana kulak verirler, haram yerler. Eğer sana gelirlerse aralarında hükmet, yahut onlardan yüz çevir; yüz çevirirsen sana bir zarar veremezler. Eğer hükmedersen aralarında adaletle hüküm ver. Allah adil olanları sever.'),
  ('tr.diyanet', 5, 43, 'Allah\'ın hükmünün bulunduğu Tevrat yanlarında iken, ne yüzle seni hakem tayin ediyorlar da sonra bundan yüz çeviriyorlar? İşte onlar inanmış değillerdir.'),
  ('tr.diyanet', 5, 44, 'Doğrusu Biz yol gösterici olarak Tevrat\'ı indirdik. Kendisini Allah\'a teslim etmiş peygamberler, yahudi olanlara onunla ve Rabbe kul olanlar, bilginler de Allah\'ın Kitap\'ından elde mahfuz kalanla hükmederlerdi. Tevrat\'a şahiddiler. O halde insanlardan korkmayın, benden korkun, ayetlerimi hiçbir değerle değiştirmeyin; Allah\'ın indirdiği ile hükmetmeyenler, işte onlar kafirlerdir.'),
  ('tr.diyanet', 5, 45, 'Orada onlara cana can, göze göz, buruna burun, kulağa kulak, dişe dişle ve yaralara karşılıklı ödeşme yazdık. Kim hakkından vazgeçerse bu, onun günahlarına keffaret olur. Allah\'ın indirdiği ile hükmetmeyenler, işte onlar zalimlerdir.'),
  ('tr.diyanet', 5, 46, 'Onların izi üzerine arkalarından Meryem oğlu İsa\'yı, ondan önce gelmiş bulunan Tevrat\'ı doğrulayarak gönderdik. Ona, yol gösterici, aydınlatıcı olan ve önünde bulunan Tevrat\'ı doğrulayan İncil\'i sakınanlara öğüt ve yol gösterici olarak verdik.'),
  ('tr.diyanet', 5, 47, 'İncil sahibleri Allah\'ın onda indirdikleri ile hükmetsinler. Allah\'ın indirdiği ile hükmetmeyenler, işte onlar fasık olanlardır.'),
  ('tr.diyanet', 5, 48, 'Kuran\'ı, önce gelen Kitap\'ı tasdik ederek ve ona şahid olarak gerçekle sana indirdik. Allah\'ın indirdiği ile aralarında hükmet; gerçek olan sana gelmiş bulunduğuna göre, onların heveslerine uyma! Her biriniz için bir yol ve bir yöntem kıldık; eğer Allah dileseydi sizi bir tek ümmet yapardı, fakat bu, verdikleriyle sizi denemesi içindir; o halde iyiliklere koşuşun, hepinizin dönüşü Allah\'adır. O, ayrılığa düştüğünüz şeyleri size bildirir.'),
  ('tr.diyanet', 5, 49, 'O halde, Allah\'ın indirdiği Kitap ile aralarında hükmet, Allah\'ın sana indirdiği Kuran\'ın bir kısmından seni vazgeçirmelerinden sakın, heveslerine uyma; eğer yüz çevirirlerse bil ki, Allah bir kısım günahları yüzünden onları cezalandırmak istiyor. İnsanların çoğu gerçekten fasıktırlar.'),
  ('tr.diyanet', 5, 50, 'Cahiliye devri hükmünü mü istiyorlar? Yakinen bilen bir millet için Allah\'tan daha iyi hüküm veren kim vardır?'),
  ('tr.diyanet', 5, 51, 'Ey İnananlar! Yahudileri ve hıristiyanları dost olarak benimsemeyin, onlar birbirlerinin dostudurlar. Sizden kim onlara dost olursa o da onlardandır. Allah zulmeden kimseleri doğru yola eriştirmez.'),
  ('tr.diyanet', 5, 52, 'Kalblerinde hastalık olanların, "Bize bir felaket gelmesinden korkuyoruz" diyerek onlara koştuğunu görürsün. Olur ki Allah bir zafer verir veya katından bir emir getirir de kalblerinde gizlediklerine içleri yananlara dönerler.'),
  ('tr.diyanet', 5, 53, 'İnananlar, "Sizinle beraber olduklarına bütün güçleriyle Allah\'a yemin edenler bunlar mıdır?" derler. Onların amelleri boşa gitmiş ve kaybeden kimseler olmuşlardır.'),
  ('tr.diyanet', 5, 54, 'Ey İnananlar! Aranızda dininden kim dönerse bilsin ki, Allah, sevdiği ve onların O\'nu sevdiği, inananlara karşı alçak gönüllü, inkarcılara karşı güçlü, Allah yolunda cihad eden, yerenin yermesinden korkmayan bir millet getirir. Bu, Allah\'ın dilediğine verdiği bol nimetidir. Allah her şeyi kaplar ve bilir.'),
  ('tr.diyanet', 5, 55, 'Sizin dostunuz ancak Allah, O\'nun Peygamberi ve namaz kılan, zekat veren ve rüku eden müminlerdir.'),
  ('tr.diyanet', 5, 56, 'Kim Allah\'ı, Peygamberini ve inananları dost edinirse bilsin ki, şüphesiz Allah\'tan yana olanlar üstün gelirler.'),
  ('tr.diyanet', 5, 57, 'Ey İnananlar! Kendilerine sizden önce kitap verilenlerden, dininizi alaya ve eğlenceye alanları ve inkarcıları dost olarak benimsemeyin. İnanıyorsanız Allah\'tan sakının.'),
  ('tr.diyanet', 5, 58, 'Namaza çağırdığınızda onu alay ve eğlenceye alırlar. Bu, onların akletmeyen bir topluluk olmasındandır.'),
  ('tr.diyanet', 5, 59, 'De ki, "Ey kitap ehli! Allah\'a, bize indirilene ve daha önce indirilene inanmamızdan ve çoğunuzun fasık olmasından ötürü mü bizden hoşlanmıyorsunuz?"'),
  ('tr.diyanet', 5, 60, '"Allah katında bundan daha kötü bir karşılığın bulunduğunu size haber vereyim mi?" de, Allah kime lanet ve gazab ederse, kimlerden maymunlar, domuzlar ve şeytana kullar kılarsa, işte onlar yeri en kötü ve doğru yoldan en çok sapmış olanlardır.'),
  ('tr.diyanet', 5, 61, 'Size geldiklerinde "İnandık" derler, oysa yanınıza inkarcı olarak girmiş ve yine inkarcı olarak çıkmışlardır. Gizlemekte olduklarını Allah daha iyi bilir.'),
  ('tr.diyanet', 5, 62, 'Onlardan çoğunun günaha, haksızlığa ve haram yemeğe koşuştuklarını görürsün. Yaptıkları ne kötüdür!'),
  ('tr.diyanet', 5, 63, 'Rabbe kul olanlar ve bilginlerin onlara günah söz söylemeyi ve haram yemeyi yasak etmeleri gerekmez miydi? Yapmakta oldukları ne kötüdür!'),
  ('tr.diyanet', 5, 64, 'Yahudiler, "Allah\'ın eli sıkıdır" dediler; dediklerinden ötürü elleri bağlandı, lanetlendiler. Hayır, O\'nun iki eli de açıktır, nasıl dilerse sarfeder. And olsun ki, sana Rabbinden indirilen sözler onların çoğunun azgınlığını ve inkarını artıracaktır. Onların arasına kıyamete kadar sürecek düşmanlık ve kin saldık. Savaş ateşini ne zaman körükleseler Allah onu söndürmüştür. Yeryüzünde bozgunculuğa koşarlar. Allah bozguncuları sevmez.'),
  ('tr.diyanet', 5, 65, 'Şayet kitap ehli inanıp karşı gelmekten sakınsalardı, kötülüklerini örterdik ve onları nimet cennetlerine koyardık.'),
  ('tr.diyanet', 5, 66, 'Eğer onlar Tevrat\'ı, İncil\'i ve Rablerinden kendilerine indirilen Kuran\'ı gereğince uygulasalardı, her yönden nimete ermiş olurlardı. İçlerinde orta yolu tutan bir zümre vardı, çoğunun işledikleri ise kötü idi.'),
  ('tr.diyanet', 5, 67, 'Ey Peygamber! Rabbinden sana indirileni tebliğ et, eğer bunu yapmazsan O\'nun elçiliğini yapmamış olursun. Allah seni insanlardan korur. Doğrusu Allah kafirlere yol göstermez.'),
  ('tr.diyanet', 5, 68, '"Ey Kitap ehli! Tevrat\'ı, İncil\'i ve Rabbinizden size indirileni gereğince uygulamadıkça bir temeliniz olmaz" de. And olsun ki Rabbinden sana indirilen, Kuran, onlardan çoğunun azgınlık ve küfrünü artırır. Öyleyse kafirler için tasalanma.'),
  ('tr.diyanet', 5, 69, 'Doğrusu inananlar, yahudiler, sabiiler ve hıristiyanlardan Allah\'a ve ahiret gününe inanan, yararlı iş yapan kimselere korku yoktur, onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 5, 70, 'And olsun ki İsrailoğullarından söz aldık ve onlara peygamberler gönderdik. Nefislerinin hoşlanmadığı bir şeyle onlara her peygamber gelişte, bir kısmını yalanlarlar ve bir kısmını da öldürürlerdi.'),
  ('tr.diyanet', 5, 71, 'Bir fitne kopmayacağını sandılar, körleştiler, sağırlaştılar; sonra Allah tevbelerini kabul etti, yine de çoğu körleştiler ve sağırlaştılar. Allah, işlediklerini görür.'),
  ('tr.diyanet', 5, 72, 'And olsun ki, "Allah ancak Meryem oğlu Mesih\'tir" diyenler kafir oldular. Oysa Mesih, "Ey İsrailoğulları! Rabbim ve Rabbiniz olan Allah\'a kulluk edin; kim Allah\'a ortak koşarsa muhakkak Allah ona cenneti haram eder, varacağı yer ateştir, zulmedenlerin yardımcıları yoktur" dedi.'),
  ('tr.diyanet', 5, 73, 'And olsun ki, "Allah üçten biridir" diyenler kafir olmuştur; oysa tanrı ancak bir tek Tanrı\'dır. Dediklerinden vazgeçmezlerse, and olsun onlardan inkar edenler elem verici bir azaba uğrayacaktır.'),
  ('tr.diyanet', 5, 74, 'Allah\'a tevbe etmezler, O\'ndan mağfiret dilemezler mi? Oysa Allah Bağışlayan\'dır, merhamet edendir.'),
  ('tr.diyanet', 5, 75, 'Meryem oğlu Mesih sadece peygamberdir, -ondan önce de peygamberler geçmiştir- onun annesi dosdoğrudur, her ikisi de yemek yerlerdi. Onlara ayetleri nasıl açıkladığımıza bir bak, sonra da bak ki nasıl yüz çeviriyorlar!'),
  ('tr.diyanet', 5, 76, '"Size zarar da fayda da veremeyecek, Allah\'tan başka birine mi kulluk ediyorsunuz?" de. Allah hem işitir, hem bilir.'),
  ('tr.diyanet', 5, 77, '"Ey Kitap ehli! Haksız olarak dininizde taşkınlık etmeyin. Daha önce sapıtan, çoğunu saptıran ve doğru yoldan ayrılan bir milletin heveslerine uymayın" de.'),
  ('tr.diyanet', 5, 78, 'İsrailoğullarından inkar edenler, Davud\'un ve Meryem oğlu İsa\'nın diliyle lanetlenmişlerdi. Bu, baş kaldırmaları ve aşırı gitmelerindendi.'),
  ('tr.diyanet', 5, 79, 'Birbirlerinin yaptıkları fenalıklara mani olmuyorlardı. Yapmakta oldukları ne kötü idi!'),
  ('tr.diyanet', 5, 80, 'Çoğunun inkar edenleri dost edindiklerini görürsün. Nefislerinin önlerine sürdüğü ne kötüdür! Allah onlara gazabetmiştir, onlar azabta temellidirler.'),
  ('tr.diyanet', 5, 81, 'Eğer Allah\'a, Peygambere ve ona indirilen Kuran\'a inanmış olsalardı, onları dost edinmezlerdi, fakat onların çoğu fasıktır.'),
  ('tr.diyanet', 5, 82, 'İnananlara en şiddetli düşman olarak, insanlardan yahudileri ve Allah\'a eş koşanları bulursun. Onlardan, inananlara sevgice en yakın "Biz hıristiyanız" diyenleri bulursun. Bu, onların içinde bilginler ve rahibler bulunmasından ve büyüklük taslamamalarındandır.'),
  ('tr.diyanet', 5, 83, 'Peygambere indirilen Kuran\'ı işittiklerinde, gerçeği öğrenmelerinden gözlerinin yaşla dolarak, "Rabbimiz! İnandık, bizi de şahidlerden yaz. Rabbimizin bizi iyi milletle birlikte bulundurmasını umarken niçin Allah\'a ve bize gelen gerçeğe inanmayalım?" dediklerini görürsün.'),
  ('tr.diyanet', 5, 84, 'Peygambere indirilen Kuran\'ı işittiklerinde, gerçeği öğrenmelerinden gözlerinin yaşla dolarak, "Rabbimiz! İnandık, bizi de şahidlerden yaz. Rabbimizin bizi iyi milletle birlikte bulundurmasını umarken niçin Allah\'a ve bize gelen gerçeğe inanmayalım?" dediklerini görürsün.'),
  ('tr.diyanet', 5, 85, 'Allah onlara, dediklerine karşılık, temelli kalacakları, altından ırmaklar akan cennetler verdi. Bu, iyi davrananların mükafatıdır.'),
  ('tr.diyanet', 5, 86, 'İnkar edip ayetlerimizi yalanlayanlar, işte onlar cehennemliklerdir.'),
  ('tr.diyanet', 5, 87, 'Ey İnananlar! Allah\'ın size helal ettiği temiz şeyleri haram kılmayın, hududu da aşmayın, doğrusu Allah aşırı gidenleri sevmez.'),
  ('tr.diyanet', 5, 88, 'Allah\'ın size verdiği rızıktan temiz ve helal olarak yiyin. İnandığınız Allah\'tan sakının.'),
  ('tr.diyanet', 5, 89, 'Allah size rasgele yeminlerinizden dolayı değil, bile bile ettiğiniz yeminlerden ötürü hesap sorar. Yeminin keffareti, ailenize yedirdiğinizin ortalamasından on düşkünü yedirmek yahut giydirmek ya da bir köle azad etmektir. Bulamayan üç gün oruç tutmalıdır; yeminlerinizin keffareti budur. Yemin ettiğinizde yeminlerinizi tutun. Şükredesiniz diye Allah size böylece ayetlerini açıklıyor.'),
  ('tr.diyanet', 5, 90, 'Ey İnananlar! İçki, kumar, putlar ve fal okları şüphesiz şeytan işi pisliklerdir, bunlardan kaçının ki saadete eresiniz.'),
  ('tr.diyanet', 5, 91, 'Şeytan şüphesiz içki ve kumar yüzünden aranıza düşmanlık ve kin sokmak ve sizi Allah\'ı anmaktan, namazdan alıkoymak ister. Artık bunlardan vazgeçersiniz değil mi?'),
  ('tr.diyanet', 5, 92, 'Allah\'a itaat edin, Peygambere itaat edin, karşı gelmekten çekinin; eğer yüz çevirirseniz bilin ki, peygamberimize düşen sadece açıkça tebliğ etmektir.'),
  ('tr.diyanet', 5, 93, 'İnananlara ve yararlı iş işleyenlere, -sakınırlar, inanırlar, yararlı işler işlerler, sonra haramdan sakınıp inanırlar ve sonra isyandan sakınıp iyilik yaparlarsa- daha önceleri tatmış olduklarından dolayı bir sorumluluk yoktur. Allah iyi davrananları sever.'),
  ('tr.diyanet', 5, 94, 'Ey İnananlar! Gıyabında Kendisinden, kimin korktuğunu ortaya koymak için, (ihramlıyken) elinizin ve mızraklarınızın ulaştığı avdan bir şeyle Allah and olsun ki sizi dener. Bundan sonra kim haddi aşarsa ona elem verici azab vardır.'),
  ('tr.diyanet', 5, 95, 'Ey İnananlar! İhramlı iken avı öldürmeyin. Sizden bile bile onu öldürene, ehli hayvanlardan öldürdüğü kadar olduğuna içinizden iki adil kimsenin hükmedeceği, Kabe\'ye ulaşacak bir kurbanı ödeme, yahut düşkünlere yemek yedirme şeklinde keffaret ya da yaptığının ağırlığını tatmak üzere bunlara denk oruç tutma vardır. Allah geçmiştekileri affetmiştir, kim tekrar yaparsa Allah ondan öç alır. Allah Güçlü\'dür, Öçalıcı\'dır.'),
  ('tr.diyanet', 5, 96, 'Deniz avı ve onu yemek size de, yolculara da, geçimlik olarak helal kılınmıştır. İhramlı bulunduğunuz sürece kara avı size haram kılınmıştır. Huzuruna toplanacağınız Allah\'tan sakının.'),
  ('tr.diyanet', 5, 97, 'Allah, hürmetli ev Kabe\'yi, hürmetli ayı, kurbanı, boynu tasmalı kurbanlıkları insanların faydası için ortaya koydu. Bu, Allah\'ın göklerde ve yerde olanları bildiğini ve Allah\'ın şüphesiz her şeyi Bilen olduğunu bilmeniz içindir.'),
  ('tr.diyanet', 5, 98, 'Allah\'ın azabının şiddetli olduğunu ve Allah\'ın Bağışlayan, merhamet eden olduğunu bilin.'),
  ('tr.diyanet', 5, 99, 'Peygamberin görevi sadece tebliğ etmektir. Allah, sizin açıkladıklarınızı da gizlediklerinizi de bilir.'),
  ('tr.diyanet', 5, 100, 'De ki: "Helal ile haram, haram şeylerin çokluğundan hoşlansan bile, eşit değildir". Ey akıl sahibleri, Allah\'tan sakının ki kurtuluşa eresiniz.'),
  ('tr.diyanet', 5, 101, 'Ey İnananlar! Size açıklanınca hoşunuza gitmeyecek şeyleri sormayın. Kuran indirilirken onları sorarsanız size açıklanır (ama üzülürsünüz). Allah sorduğunuz şeyleri affetmiştir. Allah Bağışlayan\'dır, Halim\'dir.'),
  ('tr.diyanet', 5, 102, 'Sizden önce bir millet onları sormuştu, sonra da onları inkar etmişlerdi.'),
  ('tr.diyanet', 5, 103, 'Allah, kulağı çentilen, salıverilen, erkek dişi ikizler doğuran, on defa yavrulamasından ötürü yük vurulmayan hayvanların adanmasını emretmemiştir; fakat inkar edenler Allah\'a karşı yalan uydururlar ve çoğu da akletmezler.'),
  ('tr.diyanet', 5, 104, 'Onlara, "Gelin Allah\'ın indirdiği Kitap\'a ve peygambere uyun" dendiğinde, "Atalarımızı üzerinde bulduğumuz yol bize yeter" derler; ya ataları bir şey bilmeyen ve doğru yolda olmayan kimseler idiyseler?'),
  ('tr.diyanet', 5, 105, 'Ey İnananlar! Siz kendinize bakın; doğru yolda iseniz sapıtan kimse size zarar veremez. Hepinizin dönüşü Allah\'adır, işlemekte olduklarınızı size haber verecektir.'),
  ('tr.diyanet', 5, 106, 'Ey İnananlar! Ölüm birinize geldiği zaman vasiyet ederken içinizden iki adil kimseyi; şayet yolculukta olup başınıza da ölüm musibeti gelmişse, namazdan sonra alıkoyacağınız, şüpheleniyorsanız, "Akraba bile olsa yeminle hiçbir değeri değiştirmeyeceğiz, Allah\'ın şahidliğini gizlemeyeceğiz, yoksa şüphesiz günahkarlardan oluruz" diye yemin eden sizden olmayan iki kişiyi şahid tutun.'),
  ('tr.diyanet', 5, 107, 'Eğer bu şahidlerin günah işlemiş oldukları ortaya çıkarsa ölene daha yakın hak sahibi diğer iki kişi bunların yerine geçer ve "Bizim şahidliğimiz ikisininkinden de daha doğrudur, biz aşırı gitmedik, yoksa şüphesiz zulmedenlerden oluruz" diye Allah\'a yemin ederler.'),
  ('tr.diyanet', 5, 108, 'Bu, şahidliği gerektiği gibi yapmalarını veya yeminlerinden sonra yeminlerin kabul edilmemesinden korkmalarını daha iyi sağlar. Allah\'tan sakının, dinleyin. Allah fasık kimselere yol göstermez.'),
  ('tr.diyanet', 5, 109, 'Allah peygamberleri topladığı gün, "Size ne cevap verildi?" der; onlar, "Bizim bir bildiğimiz yoktur, doğrusu görülmeyenleri bilen ancak Sen\'sin" derler.'),
  ('tr.diyanet', 5, 110, 'Allah, "Ey Meryem oğlu İsa! Sana ve anana olan nimetimi an" demişti, "Seni Ruhul Kudüs ile desteklemiştim; beşikte ve yetişkin iken insanlarla konuşuyordun; sana Kitap\'ı, hikmeti, Tevrat\'ı ve İncil\'i öğretmiştim. Sen iznimle, çamurdan kuş gibi bir şey yapmış ona üflemiştin de iznimle kuş olmuştu; anadan doğma körü, alacalıyı iznimle iyi etmiştin. Ölüleri iznimle diriltiyordun. İsrailoğullarına belgelerle geldiğinde, onlardan inkar edenler, \'Bu apaçık bir büyüdür\' demişlerdi de Ben onların sana zarar vermelerini önlemiştim."'),
  ('tr.diyanet', 5, 111, 'Havarilere, "Bana ve peygamberime inanın" diye bildirmiştim, "İnandık, bizim müslimler olduğumuza şahid ol" demişlerdi.'),
  ('tr.diyanet', 5, 112, 'Havariler, "Ey Meryem oğlu İsa! Rabbin bize gökten bir sofra indirebilir mi?" demişlerdi de, "İnanıyorsanız Allah\'tan sakının" demişti.'),
  ('tr.diyanet', 5, 113, '"Ondan yemeyi, kalblerimizin kanmasını ve senin bize doğru söylediğini bilmeyi, ona şahid olmayı istiyoruz" dediler.'),
  ('tr.diyanet', 5, 114, 'Meryem oğlu İsa, "Allahım! Rabbimiz! Bize ve bizden sonra geleceklere bayram ve Sen\'den bir delil olarak gökten bir sofra indir, bizi rızıklandır, Sen rızık verenlerin en hayırlısısın" dedi.'),
  ('tr.diyanet', 5, 115, 'Allah, "Ben onu size indireceğim; bundan sonra içinizden kim inkar ederse, dünyalarda kimseye azabetmiyeceğim şekilde ona azabedeceğim" dedi.'),
  ('tr.diyanet', 5, 116, 'Allah, "Ey Meryem oğlu İsa! Sen mi insanlara Beni ve annemi Allah\'tan başka iki tanrı olarak benimseyin dedin?" demişti de, "Haşa, hak olmayan sözü söylemek bana yaraşmaz; eğer söylemişsem, şüphesiz Sen onu bilirsin; Sen, benim içimde olanı bilirsin; ben Senin içinde olanı bilmem; doğrusu görülmeyeni bilen ancak Sensin" demişti, "Ben onlara sadece \'Rabbim ve Rabbiniz olan Allah\'a kulluk edin\' diye bana emrettiğini söyledim. Aralarında bulunduğum müddetce onlar hakkında şahiddim, beni aralarından aldığında onları Sen gözlüyordun. Sen her şeye şahidsin."'),
  ('tr.diyanet', 5, 117, 'Allah, "Ey Meryem oğlu İsa! Sen mi insanlara Beni ve annemi Allah\'tan başka iki tanrı olarak benimseyin dedin?" demişti de, "Haşa, hak olmayan sözü söylemek bana yaraşmaz; eğer söylemişsem, şüphesiz Sen onu bilirsin; Sen, benim içimde olanı bilirsin; ben Senin içinde olanı bilmem; doğrusu görülmeyeni bilen ancak Sensin" demişti, "Ben onlara sadece \'Rabbim ve Rabbiniz olan Allah\'a kulluk edin\' diye bana emrettiğini söyledim. Aralarında bulunduğum müddetce onlar hakkında şahiddim, beni aralarından aldığında onları Sen gözlüyordun. Sen her şeye şahidsin."'),
  ('tr.diyanet', 5, 118, '"Onlara azabedersen, doğrusu onlar Senin kullarındır; onları bağışlarsan, Güçlü olan, Hakim olan şüphesiz ancak Sensin."'),
  ('tr.diyanet', 5, 119, 'Allah, "Bu, doğrulara doğruluklarının fayda verdiği gündür; ebedi ve temelli kalacakları, altlarından ırmaklar akan cennetler onlarındır. Allah onlardan hoşnud olmuştur, onlar da Allah\'tan hoşnud olmuşlardır, bu büyük kurtuluştur" dedi.'),
  ('tr.diyanet', 5, 120, 'Göklerin, yerin ve onlarda bulunanların hükümranlığı Allah\'ındır, Allah her şeye Kadir\'dir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 5, 1, 'Hai orang-orang yang beriman, penuhilah aqad-aqad itu. Dihalalkan bagimu binatang ternak, kecuali yang akan dibacakan kepadamu. (Yang demikian itu) dengan tidak menghalalkan berburu ketika kamu sedang mengerjakan haji. Sesungguhnya Allah menetapkan hukum-hukum menurut yang dikehendaki-Nya.'),
  ('id.indonesian', 5, 2, 'Hai orang-orang yang beriman, janganlah kamu melanggar syi\'ar-syi\'ar Allah, dan jangan melanggar kehormatan bulan-bulan haram, jangan (mengganggu) binatang-binatang had-ya, dan binatang-binatang qalaa-id, dan jangan (pula) mengganggu orang-orang yang mengunjungi Baitullah sedang mereka mencari kurnia dan keridhaan dari Tuhannya dan apabila kamu telah menyelesaikan ibadah haji, maka bolehlah berburu. Dan janganlah sekali-kali kebencian(mu) kepada sesuatu kaum karena mereka menghalang-halangi kamu dari Masjidilharam, mendorongmu berbuat aniaya (kepada mereka). Dan tolong-menolonglah kamu dalam (mengerjakan) kebajikan dan takwa, dan jangan tolong-menolong dalam berbuat dosa dan pelanggaran. Dan bertakwalah kamu kepada Allah, sesungguhnya Allah amat berat siksa-Nya.'),
  ('id.indonesian', 5, 3, 'Diharamkan bagimu (memakan) bangkai, darah, daging babi, (daging hewan) yang disembelih atas nama selain Allah, yang tercekik, yang terpukul, yang jatuh, yang ditanduk, dan diterkam binatang buas, kecuali yang sempat kamu menyembelihnya, dan (diharamkan bagimu) yang disembelih untuk berhala. Dan (diharamkan juga) mengundi nasib dengan anak panah, (mengundi nasib dengan anak panah itu) adalah kefasikan. Pada hari ini orang-orang kafir telah putus asa untuk (mengalahkan) agamamu, sebab itu janganlah kamu takut kepada mereka dan takutlah kepada-Ku. Pada hari ini telah Kusempurnakan untuk kamu agamamu, dan telah Ku-cukupkan kepadamu nikmat-Ku, dan telah Ku-ridhai Islam itu jadi agama bagimu. Maka barang siapa terpaksa karena kelaparan tanpa sengaja berbuat dosa, sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 5, 4, 'Mereka menanyakan kepadamu: "Apakah yang dihalalkan bagi mereka?". Katakanlah: "Dihalalkan bagimu yang baik-baik dan (buruan yang ditangkap) oleh binatang buas yang telah kamu ajar dengan melatih nya untuk berburu; kamu mengajarnya menurut apa yang telah diajarkan Allah kepadamu. Maka makanlah dari apa yang ditangkapnya untukmu, dan sebutlah nama Allah atas binatang buas itu (waktu melepaskannya). Dan bertakwalah kepada Allah, sesungguhnya Allah amat cepat hisab-Nya.'),
  ('id.indonesian', 5, 5, 'Pada hari ini dihalalkan bagimu yang baik-baik. Makanan (sembelihan) orang-orang yang diberi Al Kitab itu halal bagimu, dan makanan kamu halal (pula) bagi mereka. (Dan dihalalkan mangawini) wanita yang menjaga kehormatan diantara wanita-wanita yang beriman dan wanita-wanita yang menjaga kehormatan di antara orang-orang yang diberi Al Kitab sebelum kamu, bila kamu telah membayar mas kawin mereka dengan maksud menikahinya, tidak dengan maksud berzina dan tidak (pula) menjadikannya gundik-gundik. Barangsiapa yang kafir sesudah beriman (tidak menerima hukum-hukum Islam) maka hapuslah amalannya dan ia di hari kiamat termasuk orang-orang merugi.'),
  ('id.indonesian', 5, 6, 'Hai orang-orang yang beriman, apabila kamu hendak mengerjakan shalat, maka basuhlah mukamu dan tanganmu sampai dengan siku, dan sapulah kepalamu dan (basuh) kakimu sampai dengan kedua mata kaki, dan jika kamu junub maka mandilah, dan jika kamu sakit atau dalam perjalanan atau kembali dari tempat buang air (kakus) atau menyentuh perempuan, lalu kamu tidak memperoleh air, maka bertayammumlah dengan tanah yang baik (bersih); sapulah mukamu dan tanganmu dengan tanah itu. Allah tidak hendak menyulitkan kamu, tetapi Dia hendak membersihkan kamu dan menyempurnakan nikmat-Nya bagimu, supaya kamu bersyukur.'),
  ('id.indonesian', 5, 7, 'Dan ingatlah karunia Allah kepadamu dan perjanjian-Nya yang telah diikat-Nya dengan kamu, ketika kamu mengatakan: "Kami dengar dan kami taati". Dan bertakwalah kepada Allah, sesungguhnya Allah Mengetahui isi hati(mu).'),
  ('id.indonesian', 5, 8, 'Hai orang-orang yang beriman hendaklah kamu jadi orang-orang yang selalu menegakkan (kebenaran) karena Allah, menjadi saksi dengan adil. Dan janganlah sekali-kali kebencianmu terhadap sesuatu kaum, mendorong kamu untuk berlaku tidak adil. Berlaku adillah, karena adil itu lebih dekat kepada takwa. Dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 5, 9, 'Allah telah menjanjikan kepada orang-orang yang beriman dan yang beramal saleh, (bahwa) untuk mereka ampunan dan pahala yang besar.'),
  ('id.indonesian', 5, 10, 'Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itu adalah penghuni neraka.'),
  ('id.indonesian', 5, 11, 'Hai orang-orang yang beriman, ingatlah kamu akan nikmat Allah (yang diberikan-Nya) kepadamu, di waktu suatu kaum bermaksud hendak menggerakkan tangannya kepadamu (untuk berbuat jahat), maka Allah menahan tangan mereka dari kamu. Dan bertakwalah kepada Allah, dan hanya kepada Allah sajalah orang-orang mukmin itu harus bertawakkal.'),
  ('id.indonesian', 5, 12, 'Dan sesungguhnya Allah telah mengambil perjanjian (dari) Bani Israil dan telah Kami angkat diantara mereka 12 orang pemimpin dan Allah berfirman: "Sesungguhnya Aku beserta kamu, sesungguhnya jika kamu mendirikan shalat dan menunaikan zakat serta beriman kepada rasul-rasul-Ku dan kamu bantu mereka dan kamu pinjamkan kepada Allah pinjaman yang baik sesungguhnya Aku akan menutupi dosa-dosamu. Dan sesungguhnya kamu akan Kumasukkan ke dalam surga yang mengalir air didalamnya sungai-sungai. Maka barangsiapa yang kafir di antaramu sesudah itu, sesungguhnya ia telah tersesat dari jalan yang lurus.'),
  ('id.indonesian', 5, 13, '(Tetapi) karena mereka melanggar janjinya, Kami kutuki mereka, dan Kami jadikan hati mereka keras membatu. Mereka suka merubah perkataan (Allah) dari tempat-tempatnya, dan mereka (sengaja) melupakan sebagian dari apa yang mereka telah diperingatkan dengannya, dan kamu (Muhammad) senantiasa akan melihat kekhianatan dari mereka kecuali sedikit diantara mereka (yang tidak berkhianat), maka maafkanlah mereka dan biarkan mereka, sesungguhnya Allah menyukai orang-orang yang berbuat baik.'),
  ('id.indonesian', 5, 14, 'Dan diantara orang-orang yang mengatakan: "Sesungguhnya kami ini orang-orang Nasrani", ada yang telah kami ambil perjanjian mereka, tetapi mereka (sengaja) melupakan sebagian dari apa yang mereka telah diberi peringatan dengannya; maka Kami timbulkan di antara mereka permusuhan dan kebencian sampai hari kiamat. Dan kelak Allah akan memberitakan kepada mereka apa yang mereka kerjakan.'),
  ('id.indonesian', 5, 15, 'Hai Ahli Kitab, sesungguhnya telah datang kepadamu Rasul Kami, menjelaskan kepadamu banyak dari isi Al Kitab yang kamu sembunyi kan, dan banyak (pula yang) dibiarkannya. Sesungguhnya telah datang kepadamu cahaya dari Allah, dan Kitab yang menerangkan.'),
  ('id.indonesian', 5, 16, 'Dengan kitab itulah Allah menunjuki orang-orang yang mengikuti keridhaan-Nya ke jalan keselamatan, dan (dengan kitab itu pula) Allah mengeluarkan orang-orang itu dari gelap gulita kepada cahaya yang terang benderang dengan seizin-Nya, dan menunjuki mereka ke jalan yang lurus.'),
  ('id.indonesian', 5, 17, 'Sesungguhnya telah kafirlah orang-orang yang berkata: "Sesungguhnya Allah itu ialah Al Masih putera Maryam". Katakanlah: "Maka siapakah (gerangan) yang dapat menghalang-halangi kehendak Allah, jika Dia hendak membinasakan Al Masih putera Maryam itu beserta ibunya dan seluruh orang-orang yang berada di bumi kesemuanya?". Kepunyaan Allahlah kerajaan langit dan bumi dan apa yang ada diantara keduanya; Dia menciptakan apa yang dikehendaki-Nya. Dan Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 5, 18, 'Orang-orang Yahudi dan Nasrani mengatakan: "Kami ini adalah anak-anak Allah dan kekasih-kekasih-Nya". Katakanlah: "Maka mengapa Allah menyiksa kamu karena dosa-dosamu?" (Kamu bukanlah anak-anak Allah dan kekasih-kekasih-Nya), tetapi kamu adalah manusia(biasa) diantara orang-orang yang diciptakan-Nya. Dia mengampuni bagi siapa yang dikehendaki-Nya dan menyiksa siapa yang dikehendaki-Nya. Dan Kepunyaan Allah-lah kerajaan antara keduanya. Dan kepada Allah-lah kembali (segala sesuatu).'),
  ('id.indonesian', 5, 19, 'Hai Ahli Kitab, sesungguhnya telah datang kepada kamu Rasul Kami, menjelaskan (syari\'at Kami) kepadamu ketika terputus (pengiriman) rasul-rasul agar kamu tidak mengatakan: "Tidak ada datang kepada kami baik seorang pembawa berita gembira maupun seorang pemberi peringatan". Sesungguhnya telah datang kepadamu pembawa berita gembira dan pemberi peringatan. Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 5, 20, 'Dan (ingatlah) ketika Musa berkata kepada kaumnya: "Hai kaumku, ingatlah nikmat Allah atasmu ketika Dia mengangkat nabi nabi diantaramu, dan dijadikan-Nya kamu orang-orang merdeka, dan diberikan-Nya kepadamu apa yang belum pernah diberikan-Nya kepada seorangpun diantara umat-umat yang lain".'),
  ('id.indonesian', 5, 21, 'Hai kaumku, masuklah ke tanah suci (Palestina) yang telah ditentukan Allah bagimu, dan janganlah kamu lari kebelakang (karena takut kepada musuh), maka kamu menjadi orang-orang yang merugi.'),
  ('id.indonesian', 5, 22, 'Mereka berkata: "Hai Musa, sesungguhnya dalam negeri itu ada orang-orang yang gagah perkasa, sesungguhnya kami sekali-kali tidak akan memasukinya sebelum mereka ke luar daripadanya. Jika mereka ke luar daripadanya, pasti kami akan memasukinya".'),
  ('id.indonesian', 5, 23, 'Berkatalah dua orang diantara orang-orang yang takut (kepada Allah) yang Allah telah memberi nikmat atas keduanya: "Serbulah mereka dengan melalui pintu gerbang (kota) itu, maka bila kamu memasukinya niscaya kamu akan menang. Dan hanya kepada Allah hendaknya kamu bertawakkal, jika kamu benar-benar orang yang beriman".'),
  ('id.indonesian', 5, 24, 'Mereka berkata: "Hai Musa, kami sekali sekali tidak akan memasukinya selama-lamanya, selagi mereka ada didalamnya, karena itu pergilah kamu bersama Tuhanmu, dan berperanglah kamu berdua, sesungguhnya kami hanya duduk menanti disini saja".'),
  ('id.indonesian', 5, 25, 'Berkata Musa: "Ya Tuhanku, aku tidak menguasai kecuali diriku sendiri dan saudaraku. Sebab itu pisahkanlah antara kami dengan orang-orang yang fasik itu".'),
  ('id.indonesian', 5, 26, 'Allah berfirman: "(Jika demikian), maka sesungguhnya negeri itu diharamkan atas mereka selama empat puluh tahun, (selama itu) mereka akan berputar-putar kebingungan di bumi (padang Tiih) itu. Maka janganlah kamu bersedih hati (memikirkan nasib) orang-orang yang fasik itu".'),
  ('id.indonesian', 5, 27, 'Ceritakanlah kepada mereka kisah kedua putera Adam (Habil dan Qabil) menurut yang sebenarnya, ketika keduanya mempersembahkan korban, maka diterima dari salah seorang dari mereka berdua (Habil) dan tidak diterima dari yang lain (Qabil). Ia berkata (Qabil): "Aku pasti membunuhmu!". Berkata Habil: "Sesungguhnya Allah hanya menerima (korban) dari orang-orang yang bertakwa".'),
  ('id.indonesian', 5, 28, '"Sungguh kalau kamu menggerakkan tanganmu kepadaku untuk membunuhku, aku sekali-kali tidak akan menggerakkan tanganku kepadamu untuk membunuhmu. Sesungguhnya aku takut kepada Allah, Tuhan seru sekalian alam".'),
  ('id.indonesian', 5, 29, '"Sesungguhnya aku ingin agar kamu kembali dengan (membawa) dosa (membunuh)ku dan dosamu sendiri, maka kamu akan menjadi penghuni neraka, dan yang demikian itulah pembalasan bagi orang-orang yang zalim".'),
  ('id.indonesian', 5, 30, 'Maka hawa nafsu Qabil menjadikannya menganggap mudah membunuh saudaranya, sebab itu dibunuhnyalah, maka jadilah ia seorang diantara orang-orang yang merugi.'),
  ('id.indonesian', 5, 31, 'Kemudian Allah menyuruh seekor burung gagak menggali-gali di bumi untuk memperlihatkan kepadanya (Qabil) bagaimana seharusnya menguburkan mayat saudaranya. Berkata Qabil: "Aduhai celaka aku, mengapa aku tidak mampu berbuat seperti burung gagak ini, lalu aku dapat menguburkan mayat saudaraku ini?" Karena itu jadilah dia seorang diantara orang-orang yang menyesal.'),
  ('id.indonesian', 5, 32, 'Oleh karena itu Kami tetapkan (suatu hukum) bagi Bani Israil, bahwa: barangsiapa yang membunuh seorang manusia, bukan karena orang itu (membunuh) orang lain, atau bukan karena membuat kerusakan dimuka bumi, maka seakan-akan dia telah membunuh manusia seluruhnya. Dan barangsiapa yang memelihara kehidupan seorang manusia, maka seolah-olah dia telah memelihara kehidupan manusia semuanya. Dan sesungguhnya telah datang kepada mereka rasul-rasul Kami dengan (membawa) keterangan-keterangan yang jelas, kemudian banyak diantara mereka sesudah itu sungguh-sungguh melampaui batas dalam berbuat kerusakan dimuka bumi.'),
  ('id.indonesian', 5, 33, 'Sesungguhnya pembalasan terhadap orang-orang yang memerangi Allah dan Rasul-Nya dan membuat kerusakan di muka bumi, hanyalah mereka dibunuh atau disalib, atau dipotong tangan dan kaki mereka dengan bertimbal balik, atau dibuang dari negeri (tempat kediamannya). Yang demikian itu (sebagai) suatu penghinaan untuk mereka didunia, dan di akhirat mereka beroleh siksaan yang besar,'),
  ('id.indonesian', 5, 34, 'kecuali orang-orang yang taubat (di antara mereka) sebelum kamu dapat menguasai (menangkap) mereka; maka ketahuilah bahwasanya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 5, 35, 'Hai orang-orang yang beriman, bertakwalah kepada Allah dan carilah jalan yang mendekatkan diri kepada-Nya, dan berjihadlah pada jalan-Nya, supaya kamu mendapat keberuntungan.'),
  ('id.indonesian', 5, 36, 'Sesungguhnya orang-orang yang kafir sekiranya mereka mempunyai apa yang dibumi ini seluruhnya dan mempunyai yang sebanyak itu (pula) untuk menebusi diri mereka dengan itu dari azab hari kiamat, niscaya (tebusan itu) tidak akan diterima dari mereka, dan mereka beroleh azab yang pedih.'),
  ('id.indonesian', 5, 37, 'Mereka ingin keluar dari neraka, padahal mereka sekali-kali tidak dapat keluar daripadanya, dan mereka beroleh azab yang kekal.'),
  ('id.indonesian', 5, 38, 'Laki-laki yang mencuri dan perempuan yang mencuri, potonglah tangan keduanya (sebagai) pembalasan bagi apa yang mereka kerjakan dan sebagai siksaan dari Allah. Dan Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 5, 39, 'Maka barangsiapa bertaubat (di antara pencuri-pencuri itu) sesudah melakukan kejahatan itu dan memperbaiki diri, maka sesungguhnya Allah menerima taubatnya. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 5, 40, 'Tidakkah kamu tahu, sesungguhnya Allah-lah yang mempunyai kerajaan langit dan bumi, disiksa-Nya siapa yang dikehendaki-Nya dan diampuni-Nya bagi siapa yang dikehendaki-Nya. Dan Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 5, 41, 'Hari Rasul, janganlah hendaknya kamu disedihkan oleh orang-orang yang bersegera (memperlihatkan) kekafirannya, yaitu diantara orang-orang yang mengatakan dengan mulut mereka: "Kami telah beriman", padahal hati mereka belum beriman; dan (juga) di antara orang-orang Yahudi. (Orang-orang Yahudi itu) amat suka mendengar (berita-berita) bohong dan amat suka mendengar perkataan-perkataan orang lain yang belum pernah datang kepadamu; mereka merubah perkataan-perkataan (Taurat) dari tempat-tempatnya. Mereka mengatakan: "Jika diberikan ini (yang sudah di rubah-rubah oleh mereka) kepada kamu, maka terimalah, dan jika kamu diberi yang bukan ini maka hati-hatilah". Barangsiapa yang Allah menghendaki kesesatannya, maka sekali-kali kamu tidak akan mampu menolak sesuatupun (yang datang) daripada Allah. Mereka itu adalah orang-orang yang Allah tidak hendak mensucikan hati mereka. Mereka beroleh kehinaan di dunia dan di akhirat mereka beroleh siksaan yang besar.'),
  ('id.indonesian', 5, 42, 'Mereka itu adalah orang-orang yang suka mendengar berita bohong, banyak memakan yang haram. Jika mereka (orang Yahudi) datang kepadamu (untuk meminta putusan), maka putuskanlah (perkara itu) diantara mereka, atau berpalinglah dari mereka; jika kamu berpaling dari mereka maka mereka tidak akan memberi mudharat kepadamu sedikitpun. Dan jika kamu memutuskan perkara mereka, maka putuskanlah (perkara itu) diantara mereka dengan adil, sesungguhnya Allah menyukai orang-orang yang adil.'),
  ('id.indonesian', 5, 43, 'Dan bagaimanakah mereka mengangkatmu menjadi hakim mereka, padahal mereka mempunyai Taurat yang didalamnya (ada) hukum Allah, kemudian mereka berpaling sesudah itu (dari putusanmu)? Dan mereka sungguh-sungguh bukan orang yang beriman.'),
  ('id.indonesian', 5, 44, 'Sesungguhnya Kami telah menurunkan Kitab Taurat di dalamnya (ada) petunjuk dan cahaya (yang menerangi), yang dengan Kitab itu diputuskan perkara orang-orang Yahudi oleh nabi-nabi yang menyerah diri kepada Allah, oleh orang-orang alim mereka dan pendeta-pendeta mereka, disebabkan mereka diperintahkan memelihara kitab-kitab Allah dan mereka menjadi saksi terhadapnya. Karena itu janganlah kamu takut kepada manusia, (tetapi) takutlah kepada-Ku. Dan janganlah kamu menukar ayat-ayat-Ku dengan harga yang sedikit. Barangsiapa yang tidak memutuskan menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang kafir.'),
  ('id.indonesian', 5, 45, 'Dan Kami telah tetapkan terhadap mereka di dalamnya (At Taurat) bahwasanya jiwa (dibalas) dengan jiwa, mata dengan mata, hidung dengan hidung, telinga dengan telinga, gigi dengan gigi, dan luka luka (pun) ada qishaashnya. Barangsiapa yang melepaskan (hak qishaash)nya, maka melepaskan hak itu (menjadi) penebus dosa baginya. Barangsiapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang zalim.'),
  ('id.indonesian', 5, 46, 'Dan Kami iringkan jejak mereka (nabi nabi Bani Israil) dengan Isa putera Maryam, membenarkan Kitab yang sebelumnya, yaitu: Taurat. Dan Kami telah memberikan kepadanya Kitab Injil sedang didalamnya (ada) petunjuk dan dan cahaya (yang menerangi), dan membenarkan kitab yang sebelumnya, yaitu Kitab Taurat. Dan menjadi petunjuk serta pengajaran untuk orang-orang yang bertakwa.'),
  ('id.indonesian', 5, 47, 'Dan hendaklah orang-orang pengikut Injil, memutuskan perkara menurut apa yang diturunkan Allah didalamnya. Barangsiapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang fasik.'),
  ('id.indonesian', 5, 48, 'Dan Kami telah turunkan kepadamu Al Quran dengan membawa kebenaran, membenarkan apa yang sebelumnya, yaitu kitab-kitab (yang diturunkan sebelumnya) dan batu ujian terhadap kitab-kitab yang lain itu; maka putuskanlah perkara mereka menurut apa yang Allah turunkan dan janganlah kamu mengikuti hawa nafsu mereka dengan meninggalkan kebenaran yang telah datang kepadamu. Untuk tiap-tiap umat diantara kamu, Kami berikan aturan dan jalan yang terang. Sekiranya Allah menghendaki, niscaya kamu dijadikan-Nya satu umat (saja), tetapi Allah hendak menguji kamu terhadap pemberian-Nya kepadamu, maka berlomba-lombalah berbuat kebajikan. Hanya kepada Allah-lah kembali kamu semuanya, lalu diberitahukan-Nya kepadamu apa yang telah kamu perselisihkan itu,'),
  ('id.indonesian', 5, 49, 'dan hendaklah kamu memutuskan perkara di antara mereka menurut apa yang diturunkan Allah, dan janganlah kamu mengikuti hawa nafsu mereka. Dan berhati-hatilah kamu terhadap mereka, supaya mereka tidak memalingkan kamu dari sebahagian apa yang telah diturunkan Allah kepadamu. Jika mereka berpaling (dari hukum yang telah diturunkan Allah), maka ketahuilah bahwa sesungguhnya Allah menghendaki akan menimpakan mushibah kepada mereka disebabkan sebahagian dosa-dosa mereka. Dan sesungguhnya kebanyakan manusia adalah orang-orang yang fasik.'),
  ('id.indonesian', 5, 50, 'Apakah hukum Jahiliyah yang mereka kehendaki, dan (hukum) siapakah yang lebih baik daripada (hukum) Allah bagi orang-orang yang yakin?'),
  ('id.indonesian', 5, 51, 'Hai orang-orang yang beriman, janganlah kamu mengambil orang-orang Yahudi dan Nasrani menjadi pemimpin-pemimpin(mu); sebahagian mereka adalah pemimpin bagi sebahagian yang lain. Barangsiapa diantara kamu mengambil mereka menjadi pemimpin, maka sesungguhnya orang itu termasuk golongan mereka. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang zalim.'),
  ('id.indonesian', 5, 52, 'Maka kamu akan melihat orang-orang yang ada penyakit dalam hatinya (orang-orang munafik) bersegera mendekati mereka (Yahudi dan Nasrani), seraya berkata: "Kami takut akan mendapat bencana". Mudah-mudahan Allah akan mendatangkan kemenangan (kepada Rasul-Nya), atau sesuatu keputusan dari sisi-Nya. Maka karena itu, mereka menjadi menyesal terhadap apa yang mereka rahasiakan dalam diri mereka.'),
  ('id.indonesian', 5, 53, 'Dan orang-orang yang beriman akan mengatakan: "Inikah orang-orang yang bersumpah sungguh-sungguh dengan nama Allah, bahwasanya mereka benar-benar beserta kamu?" Rusak binasalah segala amal mereka, lalu mereka menjadi orang-orang yang merugi.'),
  ('id.indonesian', 5, 54, 'Hai orang-orang yang beriman, barangsiapa di antara kamu yang murtad dari agamanya, maka kelak Allah akan mendatangkan suatu kaum yang Allah mencintai mereka dan merekapun mencintai-Nya, yang bersikap lemah lembut terhadap orang yang mukmin, yang bersikap keras terhadap orang-orang kafir, yang berjihad dijalan Allah, dan yang tidak takut kepada celaan orang yang suka mencela. Itulah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya, dan Allah Maha Luas (pemberian-Nya), lagi Maha Mengetahui.'),
  ('id.indonesian', 5, 55, 'Sesungguhnya penolong kamu hanyalah Allah, Rasul-Nya, dan orang-orang yang beriman, yang mendirikan shalat dan menunaikan zakat, seraya mereka tunduk (kepada Allah).'),
  ('id.indonesian', 5, 56, 'Dan barangsiapa mengambil Allah, Rasul-Nya dan orang-orang yang beriman menjadi penolongnya, maka sesungguhnya pengikut (agama) Allah itulah yang pasti menang.'),
  ('id.indonesian', 5, 57, 'Hai orang-orang yang beriman, janganlah kamu mengambil jadi pemimpinmu, orang-orang yang membuat agamamu jadi buah ejekan dan permainan, (yaitu) di antara orang-orang yang telah diberi kitab sebelummu, dan orang-orang yang kafir (orang-orang musyrik). Dan bertakwalah kepada Allah jika kamu betul-betul orang-orang yang beriman.'),
  ('id.indonesian', 5, 58, 'Dan apabila kamu menyeru (mereka) untuk (mengerjakan) sembahyang, mereka menjadikannya buah ejekan dan permainan. Yang demikian itu adalah karena mereka benar-benar kaum yang tidak mau mempergunakan akal.'),
  ('id.indonesian', 5, 59, 'Katakanlah: "Hai Ahli Kitab, apakah kamu memandang kami salah, hanya lantaran kami beriman kepada Allah, kepada apa yang diturunkan kepada kami dan kepada apa yang diturunkan sebelumnya, sedang kebanyakan di antara kamu benar-benar orang-orang yang fasik?'),
  ('id.indonesian', 5, 60, 'Katakanlah: "Apakah akan aku beritakan kepadamu tentang orang-orang yang lebih buruk pembalasannya dari (orang-orang fasik) itu disisi Allah, yaitu orang-orang yang dikutuki dan dimurkai Allah, di antara mereka (ada) yang dijadikan kera dan babi dan (orang yang) menyembah thaghut?". Mereka itu lebih buruk tempatnya dan lebih tersesat dari jalan yang lurus.'),
  ('id.indonesian', 5, 61, 'Dan apabila orang-orang (Yahudi atau munafik) datang kepadamu, mereka mengatakan: "Kami telah beriman", padahal mereka datang kepadamu dengan kekafirannya dan mereka pergi (daripada kamu) dengan kekafirannya (pula); dan Allah lebih mengetahui apa yang mereka sembunyikan.'),
  ('id.indonesian', 5, 62, 'Dan kamu akan melihat kebanyakan dari mereka (orang-orang Yahudi) bersegera membuat dosa, permusuhan dan memakan yang haram. Sesungguhnya amat buruk apa yang mereka telah kerjakan itu.'),
  ('id.indonesian', 5, 63, 'Mengapa orang-orang alim mereka, pendeta-pendeta mereka tidak melarang mereka mengucapkan perkataan bohong dan memakan yang haram? Sesungguhnya amat buruk apa yang telah mereka kerjakan itu.'),
  ('id.indonesian', 5, 64, 'Orang-orang Yahudi berkata: "Tangan Allah terbelenggu", sebenarnya tangan merekalah yang dibelenggu dan merekalah yang dilaknat disebabkan apa yang telah mereka katakan itu. (Tidak demikian), tetapi kedua-dua tangan Allah terbuka; Dia menafkahkan sebagaimana Dia kehendaki. Dan Al Quran yang diturunkan kepadamu dari Tuhanmu sungguh-sungguh akan menambah kedurhakaan dan kekafiran bagi kebanyakan di antara mereka. Dan Kami telah timbulkan permusuhan dan kebencian di antara mereka sampai hari kiamat. Setiap mereka menyalakan api peperangan Allah memadamkannya dan mereka berbuat kerusakan dimuka bumi dan Allah tidak menyukai orang-orang yang membuat kerusakan.'),
  ('id.indonesian', 5, 65, 'Dan sekiranya Ahli Kitab beriman dan bertakwa, tentulah Kami tutup (hapus) kesalahan-kesalahan mereka dan tentulah Kami masukkan mereka kedalam surga-surga yang penuh kenikmatan.'),
  ('id.indonesian', 5, 66, 'Dan sekiranya mereka sungguh-sungguh menjalankan (hukum) Taurat dan Injil dan (Al Quran) yang diturunkan kepada mereka dari Tuhannya, niscaya mereka akan mendapat makanan dari atas dan dari bawah kaki mereka. Diantara mereka ada golongan yang pertengahan. Dan alangkah buruknya apa yang dikerjakan oleh kebanyakan mereka.'),
  ('id.indonesian', 5, 67, 'Hai Rasul, sampaikanlah apa yang diturunkan kepadamu dari Tuhanmu. Dan jika tidak kamu kerjakan (apa yang diperintahkan itu, berarti) kamu tidak menyampaikan amanat-Nya. Allah memelihara kamu dari (gangguan) manusia. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang kafir.'),
  ('id.indonesian', 5, 68, 'Katakanlah: "Hai Ahli Kitab, kamu tidak dipandang beragama sedikitpun hingga kamu menegakkan ajaran-ajaran Taurat, Injil, dan Al Quran yang diturunkan kepadamu dari Tuhanmu". Sesungguhnya apa yang diturunkan kepadamu (Muhammad) dari Tuhanmu akan menambah kedurhakaan dan kekafiran kepada kebanyakan dari mereka; maka janganlah kamu bersedih hati terhadap orang-orang yang kafir itu.'),
  ('id.indonesian', 5, 69, 'Sesungguhnya orang-orang mukmin, orang-orang Yahudi, Shabiin dan orang-orang Nasrani, siapa saja (diantara mereka) yang benar-benar saleh, maka tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 5, 70, 'Sesungguhnya Kami telah mengambil perjanjian dari Bani Israil, dan telah Kami utus kepada mereka rasul-rasul. Tetapi setiap datang seorang rasul kepada mereka dengan membawa apa yang yang tidak diingini oleh hawa nafsu mereka, (maka) sebagian dari rasul-rasul itu mereka dustakan dan sebagian yang lain mereka bunuh.'),
  ('id.indonesian', 5, 71, 'Dan mereka mengira bahwa tidak akan terjadi suatu bencanapun (terhadap mereka dengan membunuh nabi-nabi itu), maka (karena itu) mereka menjadi buta dan pekak, kemudian Allah menerima taubat mereka, kemudian kebanyakan dari mereka buta dan tuli (lagi). Dan Allah Maha Melihat apa yang mereka kerjakan.'),
  ('id.indonesian', 5, 72, 'Sesungguhnya telah kafirlah orang-orang yang berkata: "Sesungguhnya Allah ialah Al Masih putera Maryam", padahal Al Masih (sendiri) berkata: "Hai Bani Israil, sembahlah Allah Tuhanku dan Tuhanmu". Sesungguhnya orang yang mempersekutukan (sesuatu dengan) Allah, maka pasti Allah mengharamkan kepadanya surga, dan tempatnya ialah neraka, tidaklah ada bagi orang-orang zalim itu seorang penolongpun.'),
  ('id.indonesian', 5, 73, 'Sesungguhnya kafirlah orang0orang yang mengatakan: "Bahwasanya Allah salah seorang dari yang tiga", padahal sekali-kali tidak ada Tuhan selain dari Tuhan Yang Esa. Jika mereka tidak berhenti dari apa yang mereka katakan itu, pasti orang-orang yang kafir diantara mereka akan ditimpa siksaan yang pedih.'),
  ('id.indonesian', 5, 74, 'Maka mengapa mereka tidak bertaubat kepada Allah dan memohon ampun kepada-Nya?. Dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 5, 75, 'Al Masih putera Maryam itu hanyalah seorang Rasul yang sesungguhnya telah berlalu sebelumnya beberapa rasul, dan ibunya seorang yang sangat benar, kedua-duanya biasa memakan makanan. Perhatikan bagaimana Kami menjelaskan kepada mereka (ahli kitab) tanda-tanda kekuasaan (Kami), kemudian perhatikanlah bagaimana mereka berpaling (dari memperhatikan ayat-ayat Kami itu).'),
  ('id.indonesian', 5, 76, 'Katakanlah: "Mengapa kamu menyembah selain daripada Allah, sesuatu yang tidak dapat memberi mudharat kepadamu dan tidak (pula) memberi manfaat?" Dan Allah-lah Yang Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 5, 77, 'Katakanlah: "Hai Ahli Kitab, janganlah kamu berlebih-lebihan (melampaui batas) dengan cara tidak benar dalam agamamu. Dan janganlah kamu mengikuti hawa nafsu orang-orang yang telah sesat dahulunya (sebelum kedatangan Muhammad) dan mereka telah menyesatkan kebanyakan (manusia), dan mereka tersesat dari jalan yang lurus".'),
  ('id.indonesian', 5, 78, 'Telah dilaknati orang-orang kafir dari Bani Israil dengan lisan Daud dan Isa putera Maryam. Yang demikian itu, disebabkan mereka durhaka dan selalu melampaui batas.'),
  ('id.indonesian', 5, 79, 'Mereka satu sama lain selalu tidak melarang tindakan munkar yang mereka perbuat. Sesungguhnya amat buruklah apa yang selalu mereka perbuat itu.'),
  ('id.indonesian', 5, 80, 'Kamu melihat kebanyakan dari mereka tolong-menolong dengan orang-orang yang kafir (musyrik). Sesungguhnya amat buruklah apa yang mereka sediakan untuk diri mereka, yaitu kemurkaan Allah kepada mereka; dan mereka akan kekal dalam siksaan.'),
  ('id.indonesian', 5, 81, 'Sekiranya mereka beriman kepada Allah, kepada Nabi (Musa) dan kepada apa yang diturunkan kepadanya (Nabi), niscaya mereka tidak akan mengambil orang-orang musyrikin itu menjadi penolong-penolong, tapi kebanyakan dari mereka adalah orang-orang yang fasik.'),
  ('id.indonesian', 5, 82, 'Sesungguhnya kamu dapati orang-orang yang paling keras permusuhannya terhadap orang-orang yang beriman ialah orang-orang Yahudi dan orang-orang musyrik. Dan sesungguhnya kamu dapati yang paling dekat persahabatannya dengan orang-orang yang beriman ialah orang-orang yang berkata: "Sesungguhnya kami ini orang Nasrani". Yang demikian itu disebabkan karena di antara mereka itu (orang-orang Nasrani) terdapat pendeta-pendeta dan rahib-rahib, (juga) karena sesungguhnya mereka tidak menymbongkan diri.'),
  ('id.indonesian', 5, 83, 'Dan apabila mereka mendengarkan apa yang diturunkan kepada Rasul (Muhammad), kamu lihat mata mereka mencucurkan air mata disebabkan kebenaran (Al Quran) yang telah mereka ketahui (dari kitab-kitab mereka sendiri); seraya berkata: "Ya Tuhan kami, kami telah beriman, maka catatlah kami bersama orang-orang yang menjadi saksi (atas kebenaran Al Quran dan kenabian Muhammad s. a. w.).'),
  ('id.indonesian', 5, 84, 'Mengapa kami tidak akan beriman kepada Allah dan kepada kebenaran yang datang kepada kami, padahal kami sangat ingin agar Tuhan kami memasukkan kami ke dalam golongan orang-orang yang saleh?".'),
  ('id.indonesian', 5, 85, 'Maka Allah memberi mereka pahala terhadap perkataan yang mereka ucapkan, (yaitu) surga yang mengalir sungai-sungai di dalamnya, sedang mereka kekal di dalamnya. Dan itulah balasan (bagi) orang-orang yang berbuat kebaikan (yang ikhlas keimanannya).'),
  ('id.indonesian', 5, 86, 'Dan orang-orang kafir serta mendustakan ayat-ayat Kami, mereka itulah penghuni neraka.'),
  ('id.indonesian', 5, 87, 'Hai orang-orang yang beriman, janganlah kamu haramkan apa-apa yang baik yang telah Allah halalkan bagi kamu, dan janganlah kamu melampaui batas. Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas.'),
  ('id.indonesian', 5, 88, 'Dan makanlah makanan yang halal lagi baik dari apa yang Allah telah rezekikan kepadamu, dan bertakwalah kepada Allah yang kamu beriman kepada-Nya.'),
  ('id.indonesian', 5, 89, 'Allah tidak menghukum kamu disebabkan sumpah-sumpahmu yang tidak dimaksud (untuk bersumpah), tetapi Dia menghukum kamu disebabkan sumpah-sumpah yang kamu sengaja, maka kaffarat (melanggar) sumpah itu, ialah memberi makan sepuluh orang miskin, yaitu dari makanan yang biasa kamu berikan kepada keluargamu, atau memberi pakaian kepada mereka atau memerdekakan seorang budak. Barang siapa tidak sanggup melakukan yang demikian, maka kaffaratnya puasa selama tiga hari. Yang demikian itu adalah kaffarat sumpah-sumpahmu bila kamu bersumpah (dan kamu langgar). Dan jagalah sumpahmu. Demikianlah Allah menerangkan kepadamu hukum-hukum-Nya agar kamu bersyukur (kepada-Nya).'),
  ('id.indonesian', 5, 90, 'Hai orang-orang yang beriman, sesungguhnya (meminum) khamar, berjudi, (berkorban untuk) berhala, mengundi nasib dengan panah, adalah termasuk perbuatan syaitan. Maka jauhilah perbuatan-perbuatan itu agar kamu mendapat keberuntungan.'),
  ('id.indonesian', 5, 91, 'Sesungguhnya syaitan itu bermaksud hendak menimbulkan permusuhan dan kebencian di antara kamu lantaran (meminum) khamar dan berjudi itu, dan menghalangi kamu dari mengingat Allah dan sembahyang; maka berhentilah kamu (dari mengerjakan pekerjaan itu).'),
  ('id.indonesian', 5, 92, 'Dan taatlah kamu kepada Allah dan taatlah kamu kepada Rasul-(Nya) dan berhati-hatilah. Jika kamu berpaling, maka ketahuilah bahwa sesungguhnya kewajiban Rasul Kami, hanyalah menyampaikan (amanat Allah) dengan terang.'),
  ('id.indonesian', 5, 93, 'Tidak ada dosa bagi orang-orang yang beriman dan mengerjakan amalan yang saleh karena memakan makanan yang telah mereka makan dahulu, apabila mereka bertakwa serta beriman, dan mengerjakan amalan-amalan yang saleh, kemudian mereka tetap bertakwa dan beriman, kemudian mereka (tetap juga) bertakwa dan berbuat kebajikan. Dan Allah menyukai orang-orang yang berbuat kebajikan.'),
  ('id.indonesian', 5, 94, 'Hai orang-orang yang beriman, sesungguhnya Allah akan menguji kamu dengan sesuatu dari binatang buruan yang mudah didapat oleh tangan dan tombakmu supaya Allah mengetahui orang yang takut kepada-Nya, biarpun ia tidak dapat melihat-Nya. Barang siapa yang melanggar batas sesudah itu, maka baginya azab yang pedih.'),
  ('id.indonesian', 5, 95, 'Hai orang-orang yang beriman, janganlah kamu membunuh binatang buruan, ketika kamu sedang ihram. Barangsiapa di antara kamu membunuhnya dengan sengaja, maka dendanya ialah mengganti dengan binatang ternak seimbang dengan buruan yang dibunuhnya, menurut putusan dua orang yang adil di antara kamu sebagai had-yad yang dibawa sampai ke Ka\'bah atau (dendanya) membayar kaffarat dengan memberi makan orang-orang miskin atau berpuasa seimbang dengan makanan yang dikeluarkan itu, supaya dia merasakan akibat buruk dari perbuatannya. Allah telah memaafkan apa yang telah lalu. Dan barangsiapa yang kembali mengerjakannya, niscaya Allah akan menyiksanya. Allah Maha Kuasa lagi mempunyai (kekuasaan untuk) menyiksa.'),
  ('id.indonesian', 5, 96, 'Dihalalkan bagimu binatang buruan laut dan makanan (yang berasal) dari laut sebagai makanan yang lezat bagimu, dan bagi orang-orang yang dalam perjalanan; dan diharamkan atasmu (menangkap) binatang buruan darat, selama kamu dalam ihram. Dan bertakwalah kepada Allah Yang kepada-Nya-lah kamu akan dikumpulkan.'),
  ('id.indonesian', 5, 97, 'Allah telah menjadikan Ka\'bah, rumah suci itu sebagai pusat (peribadatan dan urusan dunia) bagi manusia, dan (demikian pula) bulan Haram, had-ya, qalaid. (Allah menjadikan yang) demikian itu agar kamu tahu, bahwa sesungguhnya Allah mengetahui apa yang ada di langit dan apa yang ada di bumi dan bahwa sesungguhnya Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 5, 98, 'Ketahuilah, bahwa sesungguhnya Allah amat berat siksa-Nya dan bahwa sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 5, 99, 'Kewajiban Rasul tidak lain hanyalah menyampaikan, dan Allah mengetahui apa yang kamu lahirkan dan apa yang kamu sembunyikan.'),
  ('id.indonesian', 5, 100, 'Katakanlah: "Tidak sama yang buruk dengan yang baik, meskipun banyaknya yang buruk itu menarik hatimu, maka bertakwalah kepada Allah hai orang-orang berakal, agar kamu mendapat keberuntungan".'),
  ('id.indonesian', 5, 101, 'Hai orang-orang yang beriman, janganlah kamu menanyakan (kepada Nabimu) hal-hal yang jika diterangkan kepadamu akan menyusahkan kamu dan jika kamu menanyakan di waktu Al Quran itu diturunkan, niscaya akan diterangkan kepadamu, Allah memaafkan (kamu) tentang hal-hal itu. Allah Maha Pengampun lagi Maha Penyantun.'),
  ('id.indonesian', 5, 102, 'Sesungguhnya telah ada segolongsn manusia sebelum kamu menanyakan hal-hal yang serupa itu (kepada Nabi mereka), kemudian mereka tidak percaya kepadanya.'),
  ('id.indonesian', 5, 103, 'Allah sekali-kali tidak pernah mensyari\'atkan adanya bahiirah, saaibah, washiilah dan haam. Akan tetapi orang-orang kafir membuat-buat kedustaan terhadap Allah, dan kebanyakan mereka tidak mengerti.'),
  ('id.indonesian', 5, 104, 'Apabila dikatakan kepada mereka: "Marilah mengikuti apa yang diturunkan Allah dan mengikuti Rasul". Mereka menjawab: "Cukuplah untuk kami apa yang kami dapati bapak-bapak kami mengerjakannya". Dan apakah mereka itu akan mengikuti nenek moyang mereka walaupun nenek moyang mereka itu tidak mengetahui apa-apa dan tidak (pula) mendapat petunjuk?.'),
  ('id.indonesian', 5, 105, 'Hai orang-orang yang beriman, jagalah dirimu; tiadalah orang yang sesat itu akan memberi mudharat kepadamu apabila kamu telah mendapat petunjuk. Hanya kepada Allah kamu kembali semuanya, maka Dia akan menerangkan kepadamu apa yang telah kamu kerjakan.'),
  ('id.indonesian', 5, 106, 'Hai orang-orang yang beriman, apabila salah seorang kamu menghadapi kematian, sedang dia akan berwasiat, maka hendaklah (wasiat itu) disaksikan oleh dua orang yang adil di antara kamu, atau dua orang yang berlainan agama dengan kamu, jika kamu dalam perjalanan dimuka bumi lalu kamu ditimpa bahaya kematian. Kamu tahan kedua saksi itu sesudah sembahyang (untuk bersumpah), lalu mereka keduanya bersumpah dengan nama Allah, jika kamu ragu-ragu: "(Demi Allah) kami tidak akan membeli dengan sumpah ini harga yang sedikit (untuk kepentingan seseorang), walaupun dia karib kerabat, dan tidak (pula) kami menyembunyikan persaksian Allah; sesungguhnya kami kalau demikian tentulah termasuk orang-orang yang berdosa".'),
  ('id.indonesian', 5, 107, 'Jika diketahui bahwa kedua (saksi itu) membuat dosa, maka dua orang yang lain di antara ahli waris yang berhak yang lebih dekat kepada orang yang meninggal (memajukan tuntutan) untuk menggantikannya, lalu keduanya bersumpah dengan nama Allah: "Sesungguhnya persaksian kami labih layak diterima daripada persaksian kedua saksi itu, dan kami tidak melanggar batas, sesungguhnya kami kalau demikian tentulah termasuk orang yang menganiaya diri sendiri".'),
  ('id.indonesian', 5, 108, 'Itu lebih dekat untuk (menjadikan para saksi) mengemukakan persaksiannya menurut apa yang sebenarnya, dan (lebih dekat untuk menjadikan mereka) merasa takut akan dikembalikan sumpahnya (kepada ahli waris) sesudah mereka bersumpah. Dan bertakwalah kepada Allah dan dengarkanlah (perintah-Nya). Allah tidak memberi petunjuk kepada orang-orang yang fasik.'),
  ('id.indonesian', 5, 109, '(Ingatlah), hari di waktu Allah mengumpulkan para rasul lalu Allah bertanya (kepada mereka): "Apa jawaban kaummu terhadap (seruan)mu?". Para rasul menjawab: "Tidak ada pengetahuan kami (tentang itu); sesungguhnya Engkau-lah yang mengetahui perkara yang ghaib".'),
  ('id.indonesian', 5, 110, '(Ingatlah), ketika Allah mengatakan: "Hai Isa putra Maryam, ingatlah nikmat-Ku kepadamu dan kepada ibumu di waktu Aku menguatkan kamu dengan ruhul qudus. Kamu dapat berbicara dengan manusia di waktu masih dalam buaian dan sesudah dewasa; dan (ingatlah) di waktu Aku mengajar kamu menulis, hikmah, Taurat dan Injil, dan (ingatlah pula) diwaktu kamu membentuk dari tanah (suatu bentuk) yang berupa burung dengan ijin-Ku, kemudian kamu meniup kepadanya, lalu bentuk itu menjadi burung (yang sebenarnya) dengan seizin-Ku. Dan (ingatlah) di waktu kamu menyembuhkan orang yang buta sejak dalam kandungan ibu dan orang yang berpenyakit sopak dengan seizin-Ku, dan (ingatlah) di waktu kamu mengeluarkan orang mati dari kubur (menjadi hidup) dengan seizin-Ku, dan (ingatlah) di waktu Aku menghalangi Bani Israil (dari keinginan mereka membunuh kamu) di kala kamu mengemukakan kepada mereka keterangan-keterangan yang nyata, lalu orang-orang kafir diantara mereka berkata: "Ini tidak lain melainkan sihir yang nyata".'),
  ('id.indonesian', 5, 111, 'Dan (ingatlah), ketika Aku ilhamkan kepada pengikut Isa yang setia: "Berimanlah kamu kepada-Ku dan kepada rasul-Ku". Mereka menjawab: Kami telah beriman dan saksikanlah (wahai rasul) bahwa sesungguhnya kami adalah orang-orang yang patuh (kepada seruanmu)".'),
  ('id.indonesian', 5, 112, '(Ingatlah), ketika pengikut-pengikut Isa berkata: "Hai Isa putera Maryam, sanggupkah Tuhanmu menurunkan hidangan dari langit kepada kami?". Isa menjawab: "Bertakwalah kepada Allah jika kamu betul-betul orang yang beriman".'),
  ('id.indonesian', 5, 113, 'Mereka berkata: "Kami ingin memakan hidangan itu dan supaya tenteram hati kami dan supaya kami yakin bahwa kamu telah berkata benar kepada kami, dan kami menjadi orang-orang yang menyaksikan hidangan itu".'),
  ('id.indonesian', 5, 114, 'Isa putera Maryam berdoa: "Ya Tuhan kami turunkanlah kiranya kepada kami suatu hidangan dari langit (yang hari turunnya) akan menjadi hari raya bagi kami yaitu orang-orang yang bersama kami dan yang datang sesudah kami, dan menjadi tanda bagi kekuasaan Engkau; beri rzekilah kami, dan Engkaulah pemberi rezeki Yang Paling Utama".'),
  ('id.indonesian', 5, 115, 'Allah berfirman: "Sesungguhnya Aku akan menurunkan hidangan itu kepadamu, barangsiapa yang kafir di antaramu sesudah (turun hidangan itu), maka sesungguhnya Aku akan menyiksanya dengan siksaan yang tidak pernah Aku timpakan kepada seorangpun di antara umat manusia".'),
  ('id.indonesian', 5, 116, 'Dan (ingatlah) ketika Allah berfirman: "Hai Isa putera Maryam, adakah kamu mengatakan kepada manusia: "Jadikanlah aku dan ibuku dua orang tuhan selain Allah?". Isa menjawab: "Maha Suci Engkau, tidaklah patut bagiku mengatakan apa yang bukan hakku (mengatakannya). Jika aku pernah mengatakan maka tentulah Engkau mengetahui apa yang ada pada diriku dan aku tidak mengetahui apa yang ada pada diri Engkau. Sesungguhnya Engkau Maha Mengetahui perkara yang ghaib-ghaib".'),
  ('id.indonesian', 5, 117, 'Aku tidak pernah mengatakan kepada mereka kecuali apa yang Engkau perintahkan kepadaku (mengatakan)nya yaitu: "Sembahlah Allah, Tuhanku dan Tuhanmu", dan adalah aku menjadi saksi terhadap mereka, selama aku berada di antara mereka. Maka setelah Engkau wafatkan aku, Engkau-lah yang mengawasi mereka. Dan Engkau adalah Maha Menyaksikan atas segala sesuatu.'),
  ('id.indonesian', 5, 118, 'Jika Engkau menyiksa mereka, maka sesungguhnya mereka adalah hamba-hamba Engkau, dan jika Engkau mengampuni mereka, maka sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 5, 119, 'Allah berfirman: "Ini adalah suatu hari yang bermanfaat bagi orang-orang yang benar kebenaran mereka. Bagi mereka surga yang dibawahnya mengalir sungai-sungai; mereka kekal di dalamnya selama-lamanya; Allah ridha terhadap-Nya. Itulah keberuntungan yang paling besar".'),
  ('id.indonesian', 5, 120, 'Kepunyaan Allah-lah kerajaan langit dan bumi dan apa yang ada di dalamnya; dan Dia Maha Kuasa atas segala sesuatu.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (4, 108, 601, 'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ ۚ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا', 96, 5, 38, 0),
  (4, 109, 602, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ جَٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًۭا', 96, 5, 38, 0),
  (4, 110, 603, 'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًۭا رَّحِيمًۭا', 96, 5, 38, 0),
  (4, 111, 604, 'وَمَن يَكْسِبْ إِثْمًۭا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 96, 5, 38, 0),
  (4, 112, 605, 'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًۭا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًۭٔا فَقَدِ ٱحْتَمَلَ بُهْتَٰنًۭا وَإِثْمًۭا مُّبِينًۭا', 96, 5, 38, 0),
  (4, 113, 606, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌۭ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ ۖ وَمَا يَضُرُّونَكَ مِن شَىْءٍۢ ۚ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ ۚ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًۭا', 96, 5, 38, 0),
  (4, 114, 607, '۞ لَّا خَيْرَ فِى كَثِيرٍۢ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَٰحٍۭ بَيْنَ ٱلنَّاسِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًۭا', 97, 5, 39, 0),
  (4, 115, 608, 'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا', 97, 5, 39, 0),
  (4, 116, 609, 'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 97, 5, 39, 0),
  (4, 117, 610, 'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثًۭا وَإِن يَدْعُونَ إِلَّا شَيْطَٰنًۭا مَّرِيدًۭا', 97, 5, 39, 0),
  (4, 118, 611, 'لَّعَنَهُ ٱللَّهُ ۘ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًۭا مَّفْرُوضًۭا', 97, 5, 39, 0),
  (4, 119, 612, 'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَءَامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَٰمِ وَلَءَامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ ۚ وَمَن يَتَّخِذِ ٱلشَّيْطَٰنَ وَلِيًّۭا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًۭا مُّبِينًۭا', 97, 5, 39, 0),
  (4, 120, 613, 'يَعِدُهُمْ وَيُمَنِّيهِمْ ۖ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 97, 5, 39, 0),
  (4, 121, 614, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًۭا', 97, 5, 39, 0),
  (4, 122, 615, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَنُدْخِلُهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ وَعْدَ ٱللَّهِ حَقًّۭا ۚ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًۭا', 98, 5, 39, 0),
  (4, 123, 616, 'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَٰبِ ۗ مَن يَعْمَلْ سُوٓءًۭا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّۭا وَلَا نَصِيرًۭا', 98, 5, 39, 0),
  (4, 124, 617, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌۭ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًۭا', 98, 5, 39, 0),
  (4, 125, 618, 'وَمَنْ أَحْسَنُ دِينًۭا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌۭ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۗ وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًۭا', 98, 5, 39, 0),
  (4, 126, 619, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍۢ مُّحِيطًۭا', 98, 5, 39, 0),
  (4, 127, 620, 'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ ۖ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَٰبِ فِى يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَٰمَىٰ بِٱلْقِسْطِ ۚ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍۢ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًۭا', 98, 5, 39, 0),
  (4, 128, 621, 'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًۭا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًۭا ۚ وَٱلصُّلْحُ خَيْرٌۭ ۗ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ ۚ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا', 99, 5, 39, 0),
  (4, 129, 622, 'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ ۖ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ ۚ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًۭا رَّحِيمًۭا', 99, 5, 39, 0),
  (4, 130, 623, 'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّۭا مِّن سَعَتِهِۦ ۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًۭا', 99, 5, 39, 0),
  (4, 131, 624, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًۭا', 99, 5, 39, 0),
  (4, 132, 625, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا', 99, 5, 39, 0),
  (4, 133, 626, 'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ ۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًۭا', 99, 5, 39, 0),
  (4, 134, 627, 'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۚ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًۭا', 99, 5, 39, 0),
  (4, 135, 628, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ ۚ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًۭا فَٱللَّهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ ۚ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا', 100, 5, 40, 0),
  (4, 136, 629, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ ۚ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْءَاخِرِ فَقَدْ ضَلَّ ضَلَٰلًۢا بَعِيدًا', 100, 5, 40, 0),
  (4, 137, 630, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًۭا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا', 100, 5, 40, 0),
  (4, 138, 631, 'بَشِّرِ ٱلْمُنَٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا', 100, 5, 40, 0),
  (4, 139, 632, 'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًۭا', 100, 5, 40, 0),
  (4, 140, 633, 'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ ۚ إِنَّكُمْ إِذًۭا مِّثْلُهُمْ ۗ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَٰفِقِينَ وَٱلْكَٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا', 100, 5, 40, 0),
  (4, 141, 634, 'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌۭ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَٰفِرِينَ نَصِيبٌۭ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا', 101, 5, 40, 0),
  (4, 142, 635, 'إِنَّ ٱلْمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًۭا', 101, 5, 40, 0),
  (4, 143, 636, 'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًۭا', 101, 5, 40, 0),
  (4, 144, 637, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَٰنًۭا مُّبِينًا', 101, 5, 40, 0),
  (4, 145, 638, 'إِنَّ ٱلْمُنَٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا', 101, 5, 40, 0),
  (4, 146, 639, 'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ ۖ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًۭا', 101, 5, 40, 0),
  (4, 147, 640, 'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ ۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًۭا', 101, 5, 40, 0),
  (4, 148, 641, '۞ لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ ۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا', 102, 6, 41, 0),
  (4, 149, 642, 'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍۢ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّۭا قَدِيرًا', 102, 6, 41, 0),
  (4, 150, 643, 'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍۢ وَنَكْفُرُ بِبَعْضٍۢ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا', 102, 6, 41, 0),
  (4, 151, 644, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ حَقًّۭا ۚ وَأَعْتَدْنَا لِلْكَٰفِرِينَ عَذَابًۭا مُّهِينًۭا', 102, 6, 41, 0),
  (4, 152, 645, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍۢ مِّنْهُمْ أُو۟لَٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 102, 6, 41, 0),
  (4, 153, 646, 'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَٰبًۭا مِّنَ ٱلسَّمَآءِ ۚ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةًۭ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ بِظُلْمِهِمْ ۚ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ فَعَفَوْنَا عَن ذَٰلِكَ ۚ وَءَاتَيْنَا مُوسَىٰ سُلْطَٰنًۭا مُّبِينًۭا', 102, 6, 41, 0),
  (4, 154, 647, 'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًۭا', 102, 6, 41, 0),
  (4, 155, 648, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ وَكُفْرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّۢ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ ۚ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًۭا', 103, 6, 41, 0),
  (4, 156, 649, 'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَٰنًا عَظِيمًۭا', 103, 6, 41, 0),
  (4, 157, 650, 'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ ۚ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّۢ مِّنْهُ ۚ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ ۚ وَمَا قَتَلُوهُ يَقِينًۢا', 103, 6, 41, 0),
  (4, 158, 651, 'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًۭا', 103, 6, 41, 0),
  (4, 159, 652, 'وَإِن مِّنْ أَهْلِ ٱلْكِتَٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ ۖ وَيَوْمَ ٱلْقِيَٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًۭا', 103, 6, 41, 0),
  (4, 160, 653, 'فَبِظُلْمٍۢ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًۭا', 103, 6, 41, 0),
  (4, 161, 654, 'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ ۚ وَأَعْتَدْنَا لِلْكَٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًۭا', 103, 6, 41, 0),
  (4, 162, 655, 'لَّٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ ۚ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ ۚ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ أُو۟لَٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا', 103, 6, 41, 0),
  (4, 163, 656, '۞ إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍۢ وَٱلنَّبِيِّۦنَ مِنۢ بَعْدِهِۦ ۚ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيْمَٰنَ ۚ وَءَاتَيْنَا دَاوُۥدَ زَبُورًۭا', 104, 6, 42, 0),
  (4, 164, 657, 'وَرُسُلًۭا قَدْ قَصَصْنَٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًۭا لَّمْ نَقْصُصْهُمْ عَلَيْكَ ۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًۭا', 104, 6, 42, 0),
  (4, 165, 658, 'رُّسُلًۭا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًۭا', 104, 6, 42, 0),
  (4, 166, 659, 'لَّٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ ۖ أَنزَلَهُۥ بِعِلْمِهِۦ ۖ وَٱلْمَلَٰٓئِكَةُ يَشْهَدُونَ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا', 104, 6, 42, 0),
  (4, 167, 660, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَٰلًۢا بَعِيدًا', 104, 6, 42, 0),
  (4, 168, 661, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا', 104, 6, 42, 0),
  (4, 169, 662, 'إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًۭا', 104, 6, 42, 0),
  (4, 170, 663, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًۭا لَّكُمْ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 104, 6, 42, 0),
  (4, 171, 664, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌۭ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًۭا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَٰهٌۭ وَٰحِدٌۭ ۖ سُبْحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌۭ ۘ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًۭا', 105, 6, 42, 0),
  (4, 172, 665, 'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًۭا لِّلَّهِ وَلَا ٱلْمَلَٰٓئِكَةُ ٱلْمُقَرَّبُونَ ۚ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًۭا', 105, 6, 42, 0),
  (4, 173, 666, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۖ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًۭا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّۭا وَلَا نَصِيرًۭا', 105, 6, 42, 0),
  (4, 174, 667, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَٰنٌۭ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًۭا مُّبِينًۭا', 105, 6, 42, 0),
  (4, 175, 668, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍۢ مِّنْهُ وَفَضْلٍۢ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًۭا مُّسْتَقِيمًۭا', 105, 6, 42, 0),
  (4, 176, 669, 'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَٰلَةِ ۚ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌۭ وَلَهُۥٓ أُخْتٌۭ فَلَهَا نِصْفُ مَا تَرَكَ ۚ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌۭ ۚ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ ۚ وَإِن كَانُوٓا۟ إِخْوَةًۭ رِّجَالًۭا وَنِسَآءًۭ فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۗ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 106, 6, 42, 0),
  (5, 1, 670, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ ۗ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ', 106, 6, 43, 0),
  (5, 2, 671, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًۭا مِّن رَّبِّهِمْ وَرِضْوَٰنًۭا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 106, 6, 43, 0),
  (5, 3, 672, 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَٰمِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ۚ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَٰمَ دِينًۭا ۚ فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍۢ لِّإِثْمٍۢ ۙ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 107, 6, 43, 0),
  (5, 4, 673, 'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ ۖ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ ۙ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ ۖ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 107, 6, 43, 0),
  (5, 5, 674, 'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ ۖ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حِلٌّۭ لَّكُمْ وَطَعَامُكُمْ حِلٌّۭ لَّهُمْ ۖ وَٱلْمُحْصَنَٰتُ مِنَ ٱلْمُؤْمِنَٰتِ وَٱلْمُحْصَنَٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍۢ ۗ وَمَن يَكْفُرْ بِٱلْإِيمَٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ', 107, 6, 43, 0),
  (5, 6, 675, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًۭا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌۭ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءًۭ فَتَيَمَّمُوا۟ صَعِيدًۭا طَيِّبًۭا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍۢ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 108, 6, 43, 0),
  (5, 7, 676, 'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 108, 6, 43, 0),
  (5, 8, 677, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ۚ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 108, 6, 43, 0),
  (5, 9, 678, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ۙ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌ عَظِيمٌۭ', 108, 6, 43, 0),
  (5, 10, 679, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 109, 6, 43, 0),
  (5, 11, 680, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 109, 6, 43, 0),
  (5, 12, 681, '۞ وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًۭا ۖ وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ ۖ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًۭا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 109, 6, 44, 0),
  (5, 13, 682, 'فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ لَعَنَّٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَٰسِيَةًۭ ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّۭا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍۢ مِّنْهُمْ إِلَّا قَلِيلًۭا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ', 109, 6, 44, 0),
  (5, 14, 683, 'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰٓ أَخَذْنَا مِيثَٰقَهُمْ فَنَسُوا۟ حَظًّۭا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۚ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ', 110, 6, 44, 0),
  (5, 15, 684, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًۭا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَٰبِ وَيَعْفُوا۟ عَن كَثِيرٍۢ ۚ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌۭ وَكِتَٰبٌۭ مُّبِينٌۭ', 110, 6, 44, 0),
  (5, 16, 685, 'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 110, 6, 44, 0),
  (5, 17, 686, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۚ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًۭا ۗ وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۚ يَخْلُقُ مَا يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 110, 6, 44, 0),
  (5, 18, 687, 'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَٰرَىٰ نَحْنُ أَبْنَٰٓؤُا۟ ٱللَّهِ وَأَحِبَّٰٓؤُهُۥ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌۭ مِّمَّنْ خَلَقَ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 111, 6, 44, 0),
  (5, 19, 688, 'يَٰٓأَهْلَ ٱلْكِتَٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍۢ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍۢ وَلَا نَذِيرٍۢ ۖ فَقَدْ جَآءَكُم بَشِيرٌۭ وَنَذِيرٌۭ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 111, 6, 44, 0),
  (5, 20, 689, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًۭا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًۭا مِّنَ ٱلْعَٰلَمِينَ', 111, 6, 44, 0),
  (5, 21, 690, 'يَٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَٰسِرِينَ', 111, 6, 44, 0),
  (5, 22, 691, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًۭا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ', 111, 6, 44, 0),
  (5, 23, 692, 'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَٰلِبُونَ ۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ', 111, 6, 44, 0),
  (5, 24, 693, 'قَالُوا۟ يَٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًۭا مَّا دَامُوا۟ فِيهَا ۖ فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَٰتِلَآ إِنَّا هَٰهُنَا قَٰعِدُونَ', 112, 6, 44, 0),
  (5, 25, 694, 'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى ۖ فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 112, 6, 44, 0),
  (5, 26, 695, 'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ ۛ أَرْبَعِينَ سَنَةًۭ ۛ يَتِيهُونَ فِى ٱلْأَرْضِ ۚ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 112, 6, 44, 0),
  (5, 27, 696, '۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًۭا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْءَاخَرِ قَالَ لَأَقْتُلَنَّكَ ۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ', 112, 6, 45, 0),
  (5, 28, 697, 'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍۢ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ ۖ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 112, 6, 45, 0),
  (5, 29, 698, 'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَٰبِ ٱلنَّارِ ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', 112, 6, 45, 0),
  (5, 30, 699, 'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَٰسِرِينَ', 112, 6, 45, 0),
  (5, 31, 700, 'فَبَعَثَ ٱللَّهُ غُرَابًۭا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ ۚ قَالَ يَٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى ۖ فَأَصْبَحَ مِنَ ٱلنَّٰدِمِينَ', 112, 6, 45, 0),
  (5, 32, 701, 'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍۢ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًۭا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًۭا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَٰتِ ثُمَّ إِنَّ كَثِيرًۭا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ', 113, 6, 45, 0),
  (5, 33, 702, 'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ۚ ذَٰلِكَ لَهُمْ خِزْىٌۭ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌ', 113, 6, 45, 0),
  (5, 34, 703, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ ۖ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 113, 6, 45, 0),
  (5, 35, 704, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ', 113, 6, 45, 0),
  (5, 36, 705, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًۭا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 113, 6, 45, 0),
  (5, 37, 706, 'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا ۖ وَلَهُمْ عَذَابٌۭ مُّقِيمٌۭ', 114, 6, 45, 0),
  (5, 38, 707, 'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَٰلًۭا مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌۭ', 114, 6, 45, 0),
  (5, 39, 708, 'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ ۗ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 114, 6, 45, 0),
  (5, 40, 709, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 114, 6, 45, 0),
  (5, 41, 710, '۞ يَٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ ۛ وَمِنَ ٱلَّذِينَ هَادُوا۟ ۛ سَمَّٰعُونَ لِلْكَذِبِ سَمَّٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ ۖ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ ۖ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ ۚ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌۭ ۖ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابٌ عَظِيمٌۭ', 114, 6, 46, 0),
  (5, 42, 711, 'سَمَّٰعُونَ لِلْكَذِبِ أَكَّٰلُونَ لِلسُّحْتِ ۚ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ۖ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًۭٔا ۖ وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 115, 6, 46, 0),
  (5, 43, 712, 'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 115, 6, 46, 0),
  (5, 44, 713, 'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًۭى وَنُورٌۭ ۚ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ ۚ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًۭا قَلِيلًۭا ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰفِرُونَ', 115, 6, 46, 0),
  (5, 45, 714, 'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌۭ ۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌۭ لَّهُۥ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 115, 6, 46, 0),
  (5, 46, 715, 'وَقَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ ۖ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ فِيهِ هُدًۭى وَنُورٌۭ وَمُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًۭى وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ', 116, 6, 46, 0),
  (5, 47, 716, 'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 116, 6, 46, 0),
  (5, 48, 717, 'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَٰبِ وَمُهَيْمِنًا عَلَيْهِ ۖ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ ۚ لِكُلٍّۢ جَعَلْنَا مِنكُمْ شِرْعَةًۭ وَمِنْهَاجًۭا ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَلَٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًۭا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 116, 6, 46, 0),
  (5, 49, 718, 'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ ۖ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ ۗ وَإِنَّ كَثِيرًۭا مِّنَ ٱلنَّاسِ لَفَٰسِقُونَ', 116, 6, 46, 0),
  (5, 50, 719, 'أَفَحُكْمَ ٱلْجَٰهِلِيَّةِ يَبْغُونَ ۚ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًۭا لِّقَوْمٍۢ يُوقِنُونَ', 116, 6, 46, 0),
  (5, 51, 720, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَٰرَىٰٓ أَوْلِيَآءَ ۘ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 117, 6, 47, 0),
  (5, 52, 721, 'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ يُسَٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌۭ ۚ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍۢ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَٰدِمِينَ', 117, 6, 47, 0),
  (5, 53, 722, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ ۙ إِنَّهُمْ لَمَعَكُمْ ۚ حَبِطَتْ أَعْمَٰلُهُمْ فَأَصْبَحُوا۟ خَٰسِرِينَ', 117, 6, 47, 0),
  (5, 54, 723, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍۢ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَٰفِرِينَ يُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍۢ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ', 117, 6, 47, 0),
  (5, 55, 724, 'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ', 117, 6, 47, 0),
  (5, 56, 725, 'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَٰلِبُونَ', 117, 6, 47, 0),
  (5, 57, 726, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًۭا وَلَعِبًۭا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ ۚ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 117, 6, 47, 0),
  (5, 58, 727, 'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًۭا وَلَعِبًۭا ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْقِلُونَ', 118, 6, 47, 0),
  (5, 59, 728, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَٰسِقُونَ', 118, 6, 47, 0),
  (5, 60, 729, 'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّۢ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ ۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّٰغُوتَ ۚ أُو۟لَٰٓئِكَ شَرٌّۭ مَّكَانًۭا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ', 118, 6, 47, 0),
  (5, 61, 730, 'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ ۚ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ', 118, 6, 47, 0),
  (5, 62, 731, 'وَتَرَىٰ كَثِيرًۭا مِّنْهُمْ يُسَٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ', 118, 6, 47, 0),
  (5, 63, 732, 'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ', 118, 6, 47, 0),
  (5, 64, 733, 'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ ۚ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ ۘ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ ۚ وَلَيَزِيدَنَّ كَثِيرًۭا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًۭا وَكُفْرًۭا ۚ وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۚ كُلَّمَآ أَوْقَدُوا۟ نَارًۭا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ ۚ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًۭا ۚ وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ', 118, 6, 47, 0),
  (5, 65, 734, 'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَٰهُمْ جَنَّٰتِ ٱلنَّعِيمِ', 119, 6, 47, 0),
  (5, 66, 735, 'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم ۚ مِّنْهُمْ أُمَّةٌۭ مُّقْتَصِدَةٌۭ ۖ وَكَثِيرٌۭ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ', 119, 6, 47, 0),
  (5, 67, 736, '۞ يَٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ ۚ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 119, 6, 48, 0),
  (5, 68, 737, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ ۗ وَلَيَزِيدَنَّ كَثِيرًۭا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَٰنًۭا وَكُفْرًۭا ۖ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 119, 6, 48, 0),
  (5, 69, 738, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـُٔونَ وَٱلنَّصَٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَعَمِلَ صَٰلِحًۭا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 119, 6, 48, 0),
  (5, 70, 739, 'لَقَدْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًۭا ۖ كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًۭا كَذَّبُوا۟ وَفَرِيقًۭا يَقْتُلُونَ', 119, 6, 48, 0),
  (5, 71, 740, 'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌۭ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌۭ مِّنْهُمْ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ', 120, 6, 48, 0),
  (5, 72, 741, 'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۖ وَقَالَ ٱلْمَسِيحُ يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۖ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ ۖ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍۢ', 120, 6, 48, 0),
  (5, 73, 742, 'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَٰثَةٍۢ ۘ وَمَا مِنْ إِلَٰهٍ إِلَّآ إِلَٰهٌۭ وَٰحِدٌۭ ۚ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ', 120, 6, 48, 0),
  (5, 74, 743, 'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 120, 6, 48, 0),
  (5, 75, 744, 'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌۭ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌۭ ۖ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ۗ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْءَايَٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ', 120, 6, 48, 0),
  (5, 76, 745, 'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّۭا وَلَا نَفْعًۭا ۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 120, 6, 48, 0),
  (5, 77, 746, 'قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍۢ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًۭا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ', 121, 6, 48, 0),
  (5, 78, 747, 'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ', 121, 6, 48, 0),
  (5, 79, 748, 'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍۢ فَعَلُوهُ ۚ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ', 121, 6, 48, 0),
  (5, 80, 749, 'تَرَىٰ كَثِيرًۭا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ ۚ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَٰلِدُونَ', 121, 6, 48, 0),
  (5, 81, 750, 'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَٰكِنَّ كَثِيرًۭا مِّنْهُمْ فَٰسِقُونَ', 121, 6, 48, 0),
  (5, 82, 751, '۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةًۭ لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ ۖ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةًۭ لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰ ۚ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًۭا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ', 121, 7, 49, 0),
  (5, 83, 752, 'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ ۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّٰهِدِينَ', 122, 7, 49, 0),
  (5, 84, 753, 'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّٰلِحِينَ', 122, 7, 49, 0),
  (5, 85, 754, 'فَأَثَٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 122, 7, 49, 0),
  (5, 86, 755, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 122, 7, 49, 0),
  (5, 87, 756, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 122, 7, 49, 0),
  (5, 88, 757, 'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًۭا طَيِّبًۭا ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 122, 7, 49, 0),
  (5, 89, 758, 'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَٰنَ ۖ فَكَفَّٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍۢ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍۢ ۚ ذَٰلِكَ كَفَّٰرَةُ أَيْمَٰنِكُمْ إِذَا حَلَفْتُمْ ۚ وَٱحْفَظُوٓا۟ أَيْمَٰنَكُمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ', 122, 7, 49, 0),
  (5, 90, 759, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌۭ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ', 123, 7, 49, 0),
  (5, 91, 760, 'إِنَّمَا يُرِيدُ ٱلشَّيْطَٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ ۖ فَهَلْ أَنتُم مُّنتَهُونَ', 123, 7, 49, 0),
  (5, 92, 761, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ ۚ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 123, 7, 49, 0),
  (5, 93, 762, 'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جُنَاحٌۭ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ', 123, 7, 49, 0),
  (5, 94, 763, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍۢ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ ۚ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌۭ', 123, 7, 49, 0),
  (5, 95, 764, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌۭ ۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًۭا فَجَزَآءٌۭ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍۢ مِّنكُمْ هَدْيًۢا بَٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّٰرَةٌۭ طَعَامُ مَسَٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًۭا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ ۗ عَفَا ٱللَّهُ عَمَّا سَلَفَ ۚ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ ۗ وَٱللَّهُ عَزِيزٌۭ ذُو ٱنتِقَامٍ', 123, 7, 49, 0),
  (5, 96, 765, 'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَٰعًۭا لَّكُمْ وَلِلسَّيَّارَةِ ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًۭا ۗ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 124, 7, 49, 0),
  (5, 97, 766, '۞ جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَٰمًۭا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَٰٓئِدَ ۚ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 124, 7, 50, 0),
  (5, 98, 767, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 124, 7, 50, 0),
  (5, 99, 768, 'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ۗ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 124, 7, 50, 0),
  (5, 100, 769, 'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ ۚ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تُفْلِحُونَ', 124, 7, 50, 0),
  (5, 101, 770, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌۭ', 124, 7, 50, 0),
  (5, 102, 771, 'قَدْ سَأَلَهَا قَوْمٌۭ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَٰفِرِينَ', 124, 7, 50, 0),
  (5, 103, 772, 'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍۢ وَلَا سَآئِبَةٍۢ وَلَا وَصِيلَةٍۢ وَلَا حَامٍۢ ۙ وَلَٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ', 124, 7, 50, 0),
  (5, 104, 773, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًۭٔا وَلَا يَهْتَدُونَ', 125, 7, 50, 0),
  (5, 105, 774, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ ۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًۭا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 125, 7, 50, 0),
  (5, 106, 775, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍۢ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ ۚ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًۭا وَلَوْ كَانَ ذَا قُرْبَىٰ ۙ وَلَا نَكْتُمُ شَهَٰدَةَ ٱللَّهِ إِنَّآ إِذًۭا لَّمِنَ ٱلْءَاثِمِينَ', 125, 7, 50, 0),
  (5, 107, 776, 'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًۭا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَٰدَتُنَآ أَحَقُّ مِن شَهَٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًۭا لَّمِنَ ٱلظَّٰلِمِينَ', 125, 7, 50, 0),
  (5, 108, 777, 'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَٰنٌۢ بَعْدَ أَيْمَٰنِهِمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 125, 7, 50, 0),
  (5, 109, 778, '۞ يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ ۖ قَالُوا۟ لَا عِلْمَ لَنَآ ۖ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 126, 7, 51, 0),
  (5, 110, 779, 'إِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًۭا ۖ وَإِذْ عَلَّمْتُكَ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ ۖ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى ۖ وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى ۖ وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى ۖ وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ', 126, 7, 51, 0),
  (5, 111, 780, 'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّۦنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ', 126, 7, 51, 0),
  (5, 112, 781, 'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةًۭ مِّنَ ٱلسَّمَآءِ ۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ', 126, 7, 51, 0),
  (5, 113, 782, 'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّٰهِدِينَ', 126, 7, 51, 0),
  (5, 114, 783, 'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةًۭ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًۭا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةًۭ مِّنكَ ۖ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ', 127, 7, 51, 0),
  (5, 115, 784, 'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ ۖ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًۭا لَّآ أُعَذِّبُهُۥٓ أَحَدًۭا مِّنَ ٱلْعَٰلَمِينَ', 127, 7, 51, 0),
  (5, 116, 785, 'وَإِذْ قَالَ ٱللَّهُ يَٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَٰهَيْنِ مِن دُونِ ٱللَّهِ ۖ قَالَ سُبْحَٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ ۚ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلْغُيُوبِ', 127, 7, 51, 0),
  (5, 117, 786, 'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۚ وَكُنتُ عَلَيْهِمْ شَهِيدًۭا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ ۚ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 127, 7, 51, 0),
  (5, 118, 787, 'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ ۖ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 127, 7, 51, 0),
  (5, 119, 788, 'قَالَ ٱللَّهُ هَٰذَا يَوْمُ يَنفَعُ ٱلصَّٰدِقِينَ صِدْقُهُمْ ۚ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 127, 7, 51, 0),
  (5, 120, 789, 'لِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۢ', 127, 7, 51, 0),
  (6, 1, 790, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ', 128, 7, 51, 0),
  (6, 2, 791, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍۢ ثُمَّ قَضَىٰٓ أَجَلًۭا ۖ وَأَجَلٌۭ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ', 128, 7, 51, 0),
  (6, 3, 792, 'وَهُوَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ', 128, 7, 51, 0),
  (6, 4, 793, 'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍۢ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ', 128, 7, 51, 0),
  (6, 5, 794, 'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ ۖ فَسَوْفَ يَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 128, 7, 51, 0),
  (6, 6, 795, 'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍۢ مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًۭا وَجَعَلْنَا ٱلْأَنْهَٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 128, 7, 51, 0),
  (6, 7, 796, 'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَٰبًۭا فِى قِرْطَاسٍۢ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ', 128, 7, 51, 0),
  (6, 8, 797, 'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌۭ ۖ وَلَوْ أَنزَلْنَا مَلَكًۭا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ', 128, 7, 51, 0),
  (6, 9, 798, 'وَلَوْ جَعَلْنَٰهُ مَلَكًۭا لَّجَعَلْنَٰهُ رَجُلًۭا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ', 129, 7, 51, 0),
  (6, 10, 799, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 129, 7, 51, 0),
  (6, 11, 800, 'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 129, 7, 51, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 6, 1, '[All] praise is [due] to Allah, who created the heavens and the earth and made the darkness and the light. Then those who disbelieve equate [others] with their Lord.'),
  ('en.sahih', 6, 2, 'It is He who created you from clay and then decreed a term and a specified time [known] to Him; then [still] you are in dispute.'),
  ('en.sahih', 6, 3, 'And He is Allah, [the only deity] in the heavens and the earth. He knows your secret and what you make public, and He knows that which you earn.'),
  ('en.sahih', 6, 4, 'And no sign comes to them from the signs of their Lord except that they turn away therefrom.'),
  ('en.sahih', 6, 5, 'For they had denied the truth when it came to them, but there is going to reach them the news of what they used to ridicule.'),
  ('en.sahih', 6, 6, 'Have they not seen how many generations We destroyed before them which We had established upon the earth as We have not established you? And We sent [rain from] the sky upon them in showers and made rivers flow beneath them; then We destroyed them for their sins and brought forth after them a generation of others.'),
  ('en.sahih', 6, 7, 'And even if We had sent down to you, [O Muhammad], a written scripture on a page and they touched it with their hands, the disbelievers would say, "This is not but obvious magic."'),
  ('en.sahih', 6, 8, 'And they say, "Why was there not sent down to him an angel?" But if We had sent down an angel, the matter would have been decided; then they would not be reprieved.'),
  ('en.sahih', 6, 9, 'And if We had made him an angel, We would have made him [appear as] a man, and We would have covered them with that in which they cover themselves.'),
  ('en.sahih', 6, 10, 'And already were messengers ridiculed before you, but those who mocked them were enveloped by that which they used to ridicule.'),
  ('en.sahih', 6, 11, 'Say, "Travel through the land; then observe how was the end of the deniers."'),
  ('en.sahih', 6, 12, 'Say, "To whom belongs whatever is in the heavens and earth?" Say, "To Allah." He has decreed upon Himself mercy. He will surely assemble you for the Day of Resurrection, about which there is no doubt. Those who will lose themselves [that Day] do not believe.'),
  ('en.sahih', 6, 13, 'And to Him belongs that which reposes by night and by day, and He is the Hearing, the Knowing.'),
  ('en.sahih', 6, 14, 'Say, "Is it other than Allah I should take as a protector, Creator of the heavens and the earth, while it is He who feeds and is not fed?" Say, [O Muhammad], "Indeed, I have been commanded to be the first [among you] who submit [to Allah] and [was commanded], \'Do not ever be of the polytheists.\' "'),
  ('en.sahih', 6, 15, 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."'),
  ('en.sahih', 6, 16, 'He from whom it is averted that Day - [Allah] has granted him mercy. And that is the clear attainment.'),
  ('en.sahih', 6, 17, 'And if Allah should touch you with adversity, there is no remover of it except Him. And if He touches you with good - then He is over all things competent.'),
  ('en.sahih', 6, 18, 'And He is the subjugator over His servants. And He is the Wise, the Acquainted [with all].'),
  ('en.sahih', 6, 19, 'Say, "What thing is greatest in testimony?" Say, "Allah is witness between me and you. And this Qur\'an was revealed to me that I may warn you thereby and whomever it reaches. Do you [truly] testify that with Allah there are other deities?" Say, "I will not testify [with you]." Say, "Indeed, He is but one God, and indeed, I am free of what you associate [with Him]."'),
  ('en.sahih', 6, 20, 'Those to whom We have given the Scripture recognize it as they recognize their [own] sons. Those who will lose themselves [in the Hereafter] do not believe.'),
  ('en.sahih', 6, 21, 'And who is more unjust than one who invents about Allah a lie or denies His verses? Indeed, the wrongdoers will not succeed.'),
  ('en.sahih', 6, 22, 'And [mention, O Muhammad], the Day We will gather them all together; then We will say to those who associated others with Allah, "Where are your \'partners\' that you used to claim [with Him]?"'),
  ('en.sahih', 6, 23, 'Then there will be no [excuse upon] examination except they will say, "By Allah, our Lord, we were not those who associated."'),
  ('en.sahih', 6, 24, 'See how they will lie about themselves. And lost from them will be what they used to invent.'),
  ('en.sahih', 6, 25, 'And among them are those who listen to you, but We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if they should see every sign, they will not believe in it. Even when they come to you arguing with you, those who disbelieve say, "This is not but legends of the former peoples."'),
  ('en.sahih', 6, 26, 'And they prevent [others] from him and are [themselves] remote from him. And they do not destroy except themselves, but they perceive [it] not.'),
  ('en.sahih', 6, 27, 'If you could but see when they are made to stand before the Fire and will say, "Oh, would that we could be returned [to life on earth] and not deny the signs of our Lord and be among the believers."'),
  ('en.sahih', 6, 28, 'But what they concealed before has [now] appeared to them. And even if they were returned, they would return to that which they were forbidden; and indeed, they are liars.'),
  ('en.sahih', 6, 29, 'And they say, "There is none but our worldly life, and we will not be resurrected."'),
  ('en.sahih', 6, 30, 'If you could but see when they will be made to stand before their Lord. He will say, "Is this not the truth?" They will say, "Yes, by our Lord." He will [then] say, "So taste the punishment because you used to disbelieve."'),
  ('en.sahih', 6, 31, 'Those will have lost who deny the meeting with Allah, until when the Hour [of resurrection] comes upon them unexpectedly, they will say, "Oh, [how great is] our regret over what we neglected concerning it," while they bear their burdens on their backs. Unquestionably, evil is that which they bear.'),
  ('en.sahih', 6, 32, 'And the worldly life is not but amusement and diversion; but the home of the Hereafter is best for those who fear Allah, so will you not reason?'),
  ('en.sahih', 6, 33, 'We know that you, [O Muhammad], are saddened by what they say. And indeed, they do not call you untruthful, but it is the verses of Allah that the wrongdoers reject.'),
  ('en.sahih', 6, 34, 'And certainly were messengers denied before you, but they were patient over [the effects of] denial, and they were harmed until Our victory came to them. And none can alter the words of Allah. And there has certainly come to you some information about the [previous] messengers.'),
  ('en.sahih', 6, 35, 'And if their evasion is difficult for you, then if you are able to seek a tunnel into the earth or a stairway into the sky to bring them a sign, [then do so]. But if Allah had willed, He would have united them upon guidance. So never be of the ignorant.'),
  ('en.sahih', 6, 36, 'Only those who hear will respond. But the dead - Allah will resurrect them; then to Him they will be returned.'),
  ('en.sahih', 6, 37, 'And they say, "Why has a sign not been sent down to him from his Lord?" Say, "Indeed, Allah is Able to send down a sign, but most of them do not know."'),
  ('en.sahih', 6, 38, 'And there is no creature on [or within] the earth or bird that flies with its wings except [that they are] communities like you. We have not neglected in the Register a thing. Then unto their Lord they will be gathered.'),
  ('en.sahih', 6, 39, 'But those who deny Our verses are deaf and dumb within darknesses. Whomever Allah wills - He leaves astray; and whomever He wills - He puts him on a straight path.'),
  ('en.sahih', 6, 40, 'Say, "Have you considered: if there came to you the punishment of Allah or there came to you the Hour - is it other than Allah you would invoke, if you should be truthful?"'),
  ('en.sahih', 6, 41, 'No, it is Him [alone] you would invoke, and He would remove that for which you invoked Him if He willed, and you would forget what you associate [with Him].'),
  ('en.sahih', 6, 42, 'And We have already sent [messengers] to nations before you, [O Muhammad]; then We seized them with poverty and hardship that perhaps they might humble themselves [to Us].'),
  ('en.sahih', 6, 43, 'Then why, when Our punishment came to them, did they not humble themselves? But their hearts became hardened, and Satan made attractive to them that which they were doing.'),
  ('en.sahih', 6, 44, 'So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair.'),
  ('en.sahih', 6, 45, 'So the people that committed wrong were eliminated. And praise to Allah, Lord of the worlds.'),
  ('en.sahih', 6, 46, 'Say, "Have you considered: if Allah should take away your hearing and your sight and set a seal upon your hearts, which deity other than Allah could bring them [back] to you?" Look how we diversify the verses; then they [still] turn away.'),
  ('en.sahih', 6, 47, 'Say, "Have you considered: if the punishment of Allah should come to you unexpectedly or manifestly, will any be destroyed but the wrongdoing people?"'),
  ('en.sahih', 6, 48, 'And We send not the messengers except as bringers of good tidings and warners. So whoever believes and reforms - there will be no fear concerning them, nor will they grieve.'),
  ('en.sahih', 6, 49, 'But those who deny Our verses - the punishment will touch them for their defiant disobedience.'),
  ('en.sahih', 6, 50, 'Say, [O Muhammad], "I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel. I only follow what is revealed to me." Say, "Is the blind equivalent to the seeing? Then will you not give thought?"'),
  ('en.sahih', 6, 51, 'And warn by the Qur\'an those who fear that they will be gathered before their Lord - for them besides Him will be no protector and no intercessor - that they might become righteous.'),
  ('en.sahih', 6, 52, 'And do not send away those who call upon their Lord morning and afternoon, seeking His countenance. Not upon you is anything of their account and not upon them is anything of your account. So were you to send them away, you would [then] be of the wrongdoers.'),
  ('en.sahih', 6, 53, 'And thus We have tried some of them through others that the disbelievers might say, "Is it these whom Allah has favored among us?" Is not Allah most knowing of those who are grateful?'),
  ('en.sahih', 6, 54, 'And when those come to you who believe in Our verses, say, "Peace be upon you. Your Lord has decreed upon Himself mercy: that any of you who does wrong out of ignorance and then repents after that and corrects himself - indeed, He is Forgiving and Merciful."'),
  ('en.sahih', 6, 55, 'And thus do We detail the verses, and [thus] the way of the criminals will become evident.'),
  ('en.sahih', 6, 56, 'Say, "Indeed, I have been forbidden to worship those you invoke besides Allah." Say, "I will not follow your desires, for I would then have gone astray, and I would not be of the [rightly] guided."'),
  ('en.sahih', 6, 57, 'Say, "Indeed, I am on clear evidence from my Lord, and you have denied it. I do not have that for which you are impatient. The decision is only for Allah. He relates the truth, and He is the best of deciders."'),
  ('en.sahih', 6, 58, 'Say, "If I had that for which you are impatient, the matter would have been decided between me and you, but Allah is most knowing of the wrongdoers."'),
  ('en.sahih', 6, 59, 'And with Him are the keys of the unseen; none knows them except Him. And He knows what is on the land and in the sea. Not a leaf falls but that He knows it. And no grain is there within the darknesses of the earth and no moist or dry [thing] but that it is [written] in a clear record.'),
  ('en.sahih', 6, 60, 'And it is He who takes your souls by night and knows what you have committed by day. Then He revives you therein that a specified term may be fulfilled. Then to Him will be your return; then He will inform you about what you used to do.'),
  ('en.sahih', 6, 61, 'And He is the subjugator over His servants, and He sends over you guardian-angels until, when death comes to one of you, Our messengers take him, and they do not fail [in their duties].'),
  ('en.sahih', 6, 62, 'Then they His servants are returned to Allah, their true Lord. Unquestionably, His is the judgement, and He is the swiftest of accountants.'),
  ('en.sahih', 6, 63, 'Say, "Who rescues you from the darknesses of the land and sea [when] you call upon Him imploring [aloud] and privately, \'If He should save us from this [crisis], we will surely be among the thankful.\' "'),
  ('en.sahih', 6, 64, 'Say, "It is Allah who saves you from it and from every distress; then you [still] associate others with Him."'),
  ('en.sahih', 6, 65, 'Say, "He is the [one] Able to send upon you affliction from above you or from beneath your feet or to confuse you [so you become] sects and make you taste the violence of one another." Look how We diversify the signs that they might understand.'),
  ('en.sahih', 6, 66, 'But your people have denied it while it is the truth. Say, "I am not over you a manager."'),
  ('en.sahih', 6, 67, 'For every happening is a finality; and you are going to know.'),
  ('en.sahih', 6, 68, 'And when you see those who engage in [offensive] discourse concerning Our verses, then turn away from them until they enter into another conversation. And if Satan should cause you to forget, then do not remain after the reminder with the wrongdoing people.'),
  ('en.sahih', 6, 69, 'And those who fear Allah are not held accountable for the disbelievers at all, but [only for] a reminder - that perhaps they will fear Him.'),
  ('en.sahih', 6, 70, 'And leave those who take their religion as amusement and diversion and whom the worldly life has deluded. But remind with the Qur\'an, lest a soul be given up to destruction for what it earned; it will have other than Allah no protector and no intercessor. And if it should offer every compensation, it would not be taken from it. Those are the ones who are given to destruction for what they have earned. For them will be a drink of scalding water and a painful punishment because they used to disbelieve.'),
  ('en.sahih', 6, 71, 'Say, "Shall we invoke instead of Allah that which neither benefits us nor harms us and be turned back on our heels after Allah has guided us? [We would then be] like one whom the devils enticed [to wander] upon the earth confused, [while] he has companions inviting him to guidance, [calling], \'Come to us.\' " Say, "Indeed, the guidance of Allah is the [only] guidance; and we have been commanded to submit to the Lord of the worlds.'),
  ('en.sahih', 6, 72, 'And to establish prayer and fear Him." And it is He to whom you will be gathered.'),
  ('en.sahih', 6, 73, 'And it is He who created the heavens and earth in truth. And the day He says, "Be," and it is, His word is the truth. And His is the dominion [on] the Day the Horn is blown. [He is] Knower of the unseen and the witnessed; and He is the Wise, the Acquainted.'),
  ('en.sahih', 6, 74, 'And [mention, O Muhammad], when Abraham said to his father Azar, "Do you take idols as deities? Indeed, I see you and your people to be in manifest error."'),
  ('en.sahih', 6, 75, 'And thus did We show Abraham the realm of the heavens and the earth that he would be among the certain [in faith]'),
  ('en.sahih', 6, 76, 'So when the night covered him [with darkness], he saw a star. He said, "This is my lord." But when it set, he said, "I like not those that disappear."'),
  ('en.sahih', 6, 77, 'And when he saw the moon rising, he said, "This is my lord." But when it set, he said, "Unless my Lord guides me, I will surely be among the people gone astray."'),
  ('en.sahih', 6, 78, 'And when he saw the sun rising, he said, "This is my lord; this is greater." But when it set, he said, "O my people, indeed I am free from what you associate with Allah.'),
  ('en.sahih', 6, 79, 'Indeed, I have turned my face toward He who created the heavens and the earth, inclining toward truth, and I am not of those who associate others with Allah."'),
  ('en.sahih', 6, 80, 'And his people argued with him. He said, "Do you argue with me concerning Allah while He has guided me? And I fear not what you associate with Him [and will not be harmed] unless my Lord should will something. My Lord encompasses all things in knowledge; then will you not remember?'),
  ('en.sahih', 6, 81, 'And how should I fear what you associate while you do not fear that you have associated with Allah that for which He has not sent down to you any authority? So which of the two parties has more right to security, if you should know?'),
  ('en.sahih', 6, 82, 'They who believe and do not mix their belief with injustice - those will have security, and they are [rightly] guided.'),
  ('en.sahih', 6, 83, 'And that was Our [conclusive] argument which We gave Abraham against his people. We raise by degrees whom We will. Indeed, your Lord is Wise and Knowing.'),
  ('en.sahih', 6, 84, 'And We gave to Abraham, Isaac and Jacob - all [of them] We guided. And Noah, We guided before; and among his descendants, David and Solomon and Job and Joseph and Moses and Aaron. Thus do We reward the doers of good.'),
  ('en.sahih', 6, 85, 'And Zechariah and John and Jesus and Elias - and all were of the righteous.'),
  ('en.sahih', 6, 86, 'And Ishmael and Elisha and Jonah and Lot - and all [of them] We preferred over the worlds.'),
  ('en.sahih', 6, 87, 'And [some] among their fathers and their descendants and their brothers - and We chose them and We guided them to a straight path.'),
  ('en.sahih', 6, 88, 'That is the guidance of Allah by which He guides whomever He wills of His servants. But if they had associated others with Allah, then worthless for them would be whatever they were doing.'),
  ('en.sahih', 6, 89, 'Those are the ones to whom We gave the Scripture and authority and prophethood. But if the disbelievers deny it, then We have entrusted it to a people who are not therein disbelievers.'),
  ('en.sahih', 6, 90, 'Those are the ones whom Allah has guided, so from their guidance take an example. Say, "I ask of you for this message no payment. It is not but a reminder for the worlds."'),
  ('en.sahih', 6, 91, 'And they did not appraise Allah with true appraisal when they said, "Allah did not reveal to a human being anything." Say, "Who revealed the Scripture that Moses brought as light and guidance to the people? You [Jews] make it into pages, disclosing [some of] it and concealing much. And you were taught that which you knew not - neither you nor your fathers." Say, "Allah [revealed it]." Then leave them in their [empty] discourse, amusing themselves.'),
  ('en.sahih', 6, 92, 'And this is a Book which We have sent down, blessed and confirming what was before it, that you may warn the Mother of Cities and those around it. Those who believe in the Hereafter believe in it, and they are maintaining their prayers.'),
  ('en.sahih', 6, 93, 'And who is more unjust than one who invents a lie about Allah or says, "It has been inspired to me," while nothing has been inspired to him, and one who says, "I will reveal [something] like what Allah revealed." And if you could but see when the wrongdoers are in the overwhelming pangs of death while the angels extend their hands, [saying], "Discharge your souls! Today you will be awarded the punishment of [extreme] humiliation for what you used to say against Allah other than the truth and [that] you were, toward His verses, being arrogant."'),
  ('en.sahih', 6, 94, '[It will be said to them], "And you have certainly come to Us alone as We created you the first time, and you have left whatever We bestowed upon you behind you. And We do not see with you your \'intercessors\' which you claimed that they were among you associates [of Allah]. It has [all] been severed between you, and lost from you is what you used to claim."'),
  ('en.sahih', 6, 95, 'Indeed, Allah is the cleaver of grain and date seeds. He brings the living out of the dead and brings the dead out of the living. That is Allah; so how are you deluded?'),
  ('en.sahih', 6, 96, '[He is] the cleaver of daybreak and has made the night for rest and the sun and moon for calculation. That is the determination of the Exalted in Might, the Knowing.'),
  ('en.sahih', 6, 97, 'And it is He who placed for you the stars that you may be guided by them through the darknesses of the land and sea. We have detailed the signs for a people who know.'),
  ('en.sahih', 6, 98, 'And it is He who produced you from one soul and [gave you] a place of dwelling and of storage. We have detailed the signs for a people who understand.'),
  ('en.sahih', 6, 99, 'And it is He who sends down rain from the sky, and We produce thereby the growth of all things. We produce from it greenery from which We produce grains arranged in layers. And from the palm trees - of its emerging fruit are clusters hanging low. And [We produce] gardens of grapevines and olives and pomegranates, similar yet varied. Look at [each of] its fruit when it yields and [at] its ripening. Indeed in that are signs for a people who believe.'),
  ('en.sahih', 6, 100, 'But they have attributed to Allah partners - the jinn, while He has created them - and have fabricated for Him sons and daughters. Exalted is He and high above what they describe'),
  ('en.sahih', 6, 101, '[He is] Originator of the heavens and the earth. How could He have a son when He does not have a companion and He created all things? And He is, of all things, Knowing.'),
  ('en.sahih', 6, 102, 'That is Allah, your Lord; there is no deity except Him, the Creator of all things, so worship Him. And He is Disposer of all things.'),
  ('en.sahih', 6, 103, 'Vision perceives Him not, but He perceives [all] vision; and He is the Subtle, the Acquainted.'),
  ('en.sahih', 6, 104, 'There has come to you enlightenment from your Lord. So whoever will see does so for [the benefit of] his soul, and whoever is blind [does harm] against it. And [say], "I am not a guardian over you."'),
  ('en.sahih', 6, 105, 'And thus do We diversify the verses so the disbelievers will say, "You have studied," and so We may make the Qur\'an clear for a people who know.'),
  ('en.sahih', 6, 106, 'Follow, [O Muhammad], what has been revealed to you from your Lord - there is no deity except Him - and turn away from those who associate others with Allah.'),
  ('en.sahih', 6, 107, 'But if Allah had willed, they would not have associated. And We have not appointed you over them as a guardian, nor are you a manager over them.'),
  ('en.sahih', 6, 108, 'And do not insult those they invoke other than Allah, lest they insult Allah in enmity without knowledge. Thus We have made pleasing to every community their deeds. Then to their Lord is their return, and He will inform them about what they used to do.'),
  ('en.sahih', 6, 109, 'And they swear by Allah their strongest oaths that if a sign came to them, they would surely believe in it. Say, "The signs are only with Allah." And what will make you perceive that even if a sign came, they would not believe.'),
  ('en.sahih', 6, 110, 'And We will turn away their hearts and their eyes just as they refused to believe in it the first time. And We will leave them in their transgression, wandering blindly.'),
  ('en.sahih', 6, 111, 'And even if We had sent down to them the angels [with the message] and the dead spoke to them [of it] and We gathered together every [created] thing in front of them, they would not believe unless Allah should will. But most of them, [of that], are ignorant.'),
  ('en.sahih', 6, 112, 'And thus We have made for every prophet an enemy - devils from mankind and jinn, inspiring to one another decorative speech in delusion. But if your Lord had willed, they would not have done it, so leave them and that which they invent.'),
  ('en.sahih', 6, 113, 'And [it is] so the hearts of those who disbelieve in the Hereafter will incline toward it and that they will be satisfied with it and that they will commit that which they are committing.'),
  ('en.sahih', 6, 114, '[Say], "Then is it other than Allah I should seek as judge while it is He who has revealed to you the Book explained in detail?" And those to whom We [previously] gave the Scripture know that it is sent down from your Lord in truth, so never be among the doubters.'),
  ('en.sahih', 6, 115, 'And the word of your Lord has been fulfilled in truth and in justice. None can alter His words, and He is the Hearing, the Knowing.'),
  ('en.sahih', 6, 116, 'And if you obey most of those upon the earth, they will mislead you from the way of Allah. They follow not except assumption, and they are not but falsifying.'),
  ('en.sahih', 6, 117, 'Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of the [rightly] guided.'),
  ('en.sahih', 6, 118, 'So eat of that [meat] upon which the name of Allah has been mentioned, if you are believers in His verses.'),
  ('en.sahih', 6, 119, 'And why should you not eat of that upon which the name of Allah has been mentioned while He has explained in detail to you what He has forbidden you, excepting that to which you are compelled. And indeed do many lead [others] astray through their [own] inclinations without knowledge. Indeed, your Lord - He is most knowing of the transgressors.'),
  ('en.sahih', 6, 120, 'And leave what is apparent of sin and what is concealed thereof. Indeed, those who earn [blame for] sin will be recompensed for that which they used to commit.'),
  ('en.sahih', 6, 121, 'And do not eat of that upon which the name of Allah has not been mentioned, for indeed, it is grave disobedience. And indeed do the devils inspire their allies [among men] to dispute with you. And if you were to obey them, indeed, you would be associators [of others with Him].'),
  ('en.sahih', 6, 122, 'And is one who was dead and We gave him life and made for him light by which to walk among the people like one who is in darkness, never to emerge therefrom? Thus it has been made pleasing to the disbelievers that which they were doing.'),
  ('en.sahih', 6, 123, 'And thus We have placed within every city the greatest of its criminals to conspire therein. But they conspire not except against themselves, and they perceive [it] not.'),
  ('en.sahih', 6, 124, 'And when a sign comes to them, they say, "Never will we believe until we are given like that which was given to the messengers of Allah." Allah is most knowing of where He places His message. There will afflict those who committed crimes debasement before Allah and severe punishment for what they used to conspire.'),
  ('en.sahih', 6, 125, 'So whoever Allah wants to guide - He expands his breast to [contain] Islam; and whoever He wants to misguide - He makes his breast tight and constricted as though he were climbing into the sky. Thus does Allah place defilement upon those who do not believe.'),
  ('en.sahih', 6, 126, 'And this is the path of your Lord, [leading] straight. We have detailed the verses for a people who remember.'),
  ('en.sahih', 6, 127, 'For them will be the Home of Peace with their Lord. And He will be their protecting friend because of what they used to do.'),
  ('en.sahih', 6, 128, 'And [mention, O Muhammad], the Day when He will gather them together [and say], "O company of jinn, you have [misled] many of mankind." And their allies among mankind will say, "Our Lord, some of us made use of others, and we have [now] reached our term, which you appointed for us." He will say, "The Fire is your residence, wherein you will abide eternally, except for what Allah wills. Indeed, your Lord is Wise and Knowing."'),
  ('en.sahih', 6, 129, 'And thus will We make some of the wrongdoers allies of others for what they used to earn.'),
  ('en.sahih', 6, 130, '"O company of jinn and mankind, did there not come to you messengers from among you, relating to you My verses and warning you of the meeting of this Day of yours?" They will say, "We bear witness against ourselves"; and the worldly life had deluded them, and they will bear witness against themselves that they were disbelievers.'),
  ('en.sahih', 6, 131, 'That is because your Lord would not destroy the cities for wrongdoing while their people were unaware.'),
  ('en.sahih', 6, 132, 'And for all are degrees from what they have done. And your Lord is not unaware of what they do.'),
  ('en.sahih', 6, 133, 'And your Lord is the Free of need, the possessor of mercy. If He wills, he can do away with you and give succession after you to whomever He wills, just as He produced you from the descendants of another people.'),
  ('en.sahih', 6, 134, 'Indeed, what you are promised is coming, and you will not cause failure [to Allah].'),
  ('en.sahih', 6, 135, 'Say, "O my people, work according to your position; [for] indeed, I am working. And you are going to know who will have succession in the home. Indeed, the wrongdoers will not succeed.'),
  ('en.sahih', 6, 136, 'And the polytheists assign to Allah from that which He created of crops and livestock a share and say, "This is for Allah," by their claim, "and this is for our partners [associated with Him]." But what is for their "partners" does not reach Allah, while what is for Allah - this reaches their "partners." Evil is that which they rule.'),
  ('en.sahih', 6, 137, 'And likewise, to many of the polytheists their partners have made [to seem] pleasing the killing of their children in order to bring about their destruction and to cover them with confusion in their religion. And if Allah had willed, they would not have done so. So leave them and that which they invent.'),
  ('en.sahih', 6, 138, 'And they say, "These animals and crops are forbidden; no one may eat from them except whom we will," by their claim. And there are those [camels] whose backs are forbidden [by them] and those upon which the name of Allah is not mentioned - [all of this] an invention of untruth about Him. He will punish them for what they were inventing.'),
  ('en.sahih', 6, 139, 'And they say, "What is in the bellies of these animals is exclusively for our males and forbidden to our females. But if it is [born] dead, then all of them have shares therein." He will punish them for their description. Indeed, He is Wise and Knowing.'),
  ('en.sahih', 6, 140, 'Those will have lost who killed their children in foolishness without knowledge and prohibited what Allah had provided for them, inventing untruth about Allah. They have gone astray and were not [rightly] guided.'),
  ('en.sahih', 6, 141, 'And He it is who causes gardens to grow, [both] trellised and untrellised, and palm trees and crops of different [kinds of] food and olives and pomegranates, similar and dissimilar. Eat of [each of] its fruit when it yields and give its due [zakah] on the day of its harvest. And be not excessive. Indeed, He does not like those who commit excess.'),
  ('en.sahih', 6, 142, 'And of the grazing livestock are carriers [of burdens] and those [too] small. Eat of what Allah has provided for you and do not follow the footsteps of Satan. Indeed, he is to you a clear enemy.'),
  ('en.sahih', 6, 143, '[They are] eight mates - of the sheep, two and of the goats, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Inform me with knowledge, if you should be truthful."'),
  ('en.sahih', 6, 144, 'And of the camels, two and of the cattle, two. Say, "Is it the two males He has forbidden or the two females or that which the wombs of the two females contain? Or were you witnesses when Allah charged you with this? Then who is more unjust than one who invents a lie about Allah to mislead the people by [something] other than knowledge? Indeed, Allah does not guide the wrongdoing people."'),
  ('en.sahih', 6, 145, 'Say, "I do not find within that which was revealed to me [anything] forbidden to one who would eat it unless it be a dead animal or blood spilled out or the flesh of swine - for indeed, it is impure - or it be [that slaughtered in] disobedience, dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit], then indeed, your Lord is Forgiving and Merciful."'),
  ('en.sahih', 6, 146, 'And to those who are Jews We prohibited every animal of uncloven hoof; and of the cattle and the sheep We prohibited to them their fat, except what adheres to their backs or the entrails or what is joined with bone. [By] that We repaid them for their injustice. And indeed, We are truthful.'),
  ('en.sahih', 6, 147, 'So if they deny you, [O Muhammad], say, "Your Lord is the possessor of vast mercy; but His punishment cannot be repelled from the people who are criminals."'),
  ('en.sahih', 6, 148, 'Those who associated with Allah will say, "If Allah had willed, we would not have associated [anything] and neither would our fathers, nor would we have prohibited anything." Likewise did those before deny until they tasted Our punishment. Say, "Do you have any knowledge that you can produce for us? You follow not except assumption, and you are not but falsifying."'),
  ('en.sahih', 6, 149, 'Say, "With Allah is the far-reaching argument. If He had willed, He would have guided you all."'),
  ('en.sahih', 6, 150, 'Say, [O Muhammad], "Bring forward your witnesses who will testify that Allah has prohibited this." And if they testify, do not testify with them. And do not follow the desires of those who deny Our verses and those who do not believe in the Hereafter, while they equate [others] with their Lord.'),
  ('en.sahih', 6, 151, 'Say, "Come, I will recite what your Lord has prohibited to you. [He commands] that you not associate anything with Him, and to parents, good treatment, and do not kill your children out of poverty; We will provide for you and them. And do not approach immoralities - what is apparent of them and what is concealed. And do not kill the soul which Allah has forbidden [to be killed] except by [legal] right. This has He instructed you that you may use reason."'),
  ('en.sahih', 6, 152, 'And do not approach the orphan\'s property except in a way that is best until he reaches maturity. And give full measure and weight in justice. We do not charge any soul except [with that within] its capacity. And when you testify, be just, even if [it concerns] a near relative. And the covenant of Allah fulfill. This has He instructed you that you may remember.'),
  ('en.sahih', 6, 153, 'And, [moreover], this is My path, which is straight, so follow it; and do not follow [other] ways, for you will be separated from His way. This has He instructed you that you may become righteous.'),
  ('en.sahih', 6, 154, 'Then We gave Moses the Scripture, making complete [Our favor] upon the one who did good and as a detailed explanation of all things and as guidance and mercy that perhaps in [the matter of] the meeting with their Lord they would believe.'),
  ('en.sahih', 6, 155, 'And this [Qur\'an] is a Book We have revealed [which is] blessed, so follow it and fear Allah that you may receive mercy.'),
  ('en.sahih', 6, 156, '[We revealed it] lest you say, "The Scripture was only sent down to two groups before us, but we were of their study unaware,"'),
  ('en.sahih', 6, 157, 'Or lest you say, "If only the Scripture had been revealed to us, we would have been better guided than they." So there has [now] come to you a clear evidence from your Lord and a guidance and mercy. Then who is more unjust than one who denies the verses of Allah and turns away from them? We will recompense those who turn away from Our verses with the worst of punishment for their having turned away.'),
  ('en.sahih', 6, 158, 'Do they [then] wait for anything except that the angels should come to them or your Lord should come or that there come some of the signs of your Lord? The Day that some of the signs of your Lord will come no soul will benefit from its faith as long as it had not believed before or had earned through its faith some good. Say, "Wait. Indeed, we [also] are waiting."'),
  ('en.sahih', 6, 159, 'Indeed, those who have divided their religion and become sects - you, [O Muhammad], are not [associated] with them in anything. Their affair is only [left] to Allah; then He will inform them about what they used to do.'),
  ('en.sahih', 6, 160, 'Whoever comes [on the Day of Judgement] with a good deed will have ten times the like thereof [to his credit], and whoever comes with an evil deed will not be recompensed except the like thereof; and they will not be wronged.'),
  ('en.sahih', 6, 161, 'Say, "Indeed, my Lord has guided me to a straight path - a correct religion - the way of Abraham, inclining toward truth. And he was not among those who associated others with Allah."'),
  ('en.sahih', 6, 162, 'Say, "Indeed, my prayer, my rites of sacrifice, my living and my dying are for Allah, Lord of the worlds.'),
  ('en.sahih', 6, 163, 'No partner has He. And this I have been commanded, and I am the first [among you] of the Muslims."'),
  ('en.sahih', 6, 164, 'Say, "Is it other than Allah I should desire as a lord while He is the Lord of all things? And every soul earns not [blame] except against itself, and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you concerning that over which you used to differ."'),
  ('en.sahih', 6, 165, 'And it is He who has made you successors upon the earth and has raised some of you above others in degrees [of rank] that He may try you through what He has given you. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 6, 1, 'সর্ববিধ প্রশংসা আল্লাহরই জন্য যিনি নভোমন্ডল ও ভূমন্ডল সৃষ্টি করেছেন এবং অন্ধকার ও আলোর উদ্ভব করেছেন। তথাপি কাফেররা স্বীয় পালনকর্তার সাথে অন্যান্যকে সমতুল্য স্থির করে।'),
  ('bn.bengali', 6, 2, 'তিনিই তোমাদেরকে মাটির দ্বারা সৃষ্টি করেছেন, অতঃপর নির্দিষ্টকাল নির্ধারণ করেছেন। আর অপর নির্দিষ্টকাল আল্লাহর কাছে আছে। তথাপি তোমরা সন্দেহ কর।'),
  ('bn.bengali', 6, 3, 'তিনিই আল্লাহ নভোমন্ডলে এবং ভূমন্ডলে। তিনি তোমাদের গোপন ও প্রকাশ্য বিষয় জানেন এবং তোমরা যা কর তাও অবগত।'),
  ('bn.bengali', 6, 4, 'তাদের কাছে তাদের প্রতিপালকের নিদর্শনাবলী থেকে কোন নিদর্শন আসেনি; যার প্রতি তারা বিমুখ হয় না।'),
  ('bn.bengali', 6, 5, 'অতএব, অবশ্য তারা সত্যকে মিথ্যা বলেছে যখন তা তাদের কাছে এসেছে। বস্তুতঃ অচিরেই তাদের কাছে ঐ বিষয়ের সংবাদ আসবে, যার সাথে তারা উপহাস করত।'),
  ('bn.bengali', 6, 6, 'তারা কি দেখেনি যে, আমি তাদের পুর্বে কত সম্প্রদায়কে ধ্বংস করে দিয়েছি, যাদেরকে আমি পৃথিবীতে এমন প্রতিষ্ঠা দিয়েছিলাম, যা তোমাদেরকে দেইনি। আমি আকাশকে তাদের উপর অনবরত বৃষ্টি বর্ষণ করতে দিয়েছি এবং তাদের তলদেশে নদী সৃষ্টি করে দিয়েছি, অতঃপর আমি তাদেরকে তাদের পাপের কারণে ধ্বংস করে দিয়েছি এবং তাদের পরে অন্য সম্প্রদায় সৃষ্টি করেছি।'),
  ('bn.bengali', 6, 7, 'যদি আমি কাগজে লিখিত কোন বিষয় তাদের প্রতি নাযিল করতাম, অতঃপর তারা তা সহস্তে স্পর্শ করত, তবুও অবিশ্বাসীরা একথাই বলত যে, এটা প্রকাশ্য জাদু বৈ কিছু নয়।'),
  ('bn.bengali', 6, 8, 'তারা আরও বলে যে, তাঁর কাছে কোন ফেরেশতা কেন প্রেরণ করা হল না ? যদি আমি কোন ফেরেশতা প্রেরণ করতাম, তবে গোটা ব্যাপারটাই শেষ হয়ে যেত। অতঃপর তাদেরকে সামান্যও অবকাশ দেওয়া হতনা।'),
  ('bn.bengali', 6, 9, 'যদি আমি কোন ফেরেশতাকে রসূল করে পাঠাতাম, তবে সে মানুষের আকারেই হত। এতেও ঐ সন্দেহই করত, যা এখন করছে।'),
  ('bn.bengali', 6, 10, 'নিশ্চয়ই আপনার পূর্ববর্তী পয়গম্বরগণের সাথেও উপহাস করা হয়েছে। অতঃপর যারা তাঁদের সাথে উপহাস করেছিল, তাদেরকে ঐ শাস্তি বেষ্টন করে নিল, যা নিয়ে তারা উপহাস করত।'),
  ('bn.bengali', 6, 11, 'বলে দিনঃ তোমরা পৃথিবীতে পরিভ্রমণ কর, অতপর দেখ, মিথ্যারোপ কারীদের পরিণাম কি হয়েছে?'),
  ('bn.bengali', 6, 12, 'জিজ্ঞেস করুন, নভোমন্ডল ও ভুমন্ডলে যা আছে, তার মালিক কে? বলে দিনঃআল্লাহ। তিনি অনুকম্পা প্রদর্শনকে নিজ দায়িত্বে লিপিবদ্ধ করে নিয়েছেন। তিনি অবশ্যই তোমাদেরকে কেয়ামতের দিন একত্রিত করবেন। এর আগমনে কোন সন্দেহ নেই। যারা নিজেদের কে ক্ষতিগ্রস্ত করেছে, তারাই বিশ্বাস স্থাপন করে না।'),
  ('bn.bengali', 6, 13, 'যা কিছু রাত ও দিনে স্থিতি লাভ করে, তাঁরই। তিনিই শ্রোতা, মহাজ্ঞানী।'),
  ('bn.bengali', 6, 14, 'আপনি বলে দিনঃ আমি কি আল্লাহ ব্যতীত-যিনি নভোমন্ডল ও ভুমন্ডলের স্রষ্টা এবং যিনি সবাইকে আহার্য দানকরেন ও তাঁকে কেউ আহার্য দান করে না অপরকে সাহায্যকারী স্থির করব? আপনি বলে দিনঃ আমি আদিষ্ট হয়েছি যে, সর্বাগ্রে আমিই আজ্ঞাবহ হব। আপনি কদাচ অংশীবাদীদের অন্তর্ভুক্ত হবেন না।'),
  ('bn.bengali', 6, 15, 'আপনি বলুন, আমি আমার প্রতিপালকের অবাধ্য হতে ভয় পাই কেননা, আমি একটি মহাদিবসের শাস্তিকে ভয় করি।'),
  ('bn.bengali', 6, 16, 'যার কাছ থেকে ঐদিন এ শাস্তি সরিয়ে নেওয়া হবে, তার প্রতি আল্লাহর অনুকম্পা হবে। এটাই বিরাট সাফল্য।'),
  ('bn.bengali', 6, 17, 'আর যদি আল্লাহ তোমাকে কোন কষ্ট দেন, তবে তিনি ব্যতীত তা অপসারণকারী কেউ নেই। পক্ষান্তরে যদি তোমার মঙ্গল করেন, তবে তিনি সবকিছুর উপর ক্ষমতাবান।'),
  ('bn.bengali', 6, 18, 'তিনিই পরাক্রান্ত স্বীয় বান্দাদের উপর। তিনিই জ্ঞানময়, সর্বজ্ঞ।'),
  ('bn.bengali', 6, 19, 'আপনি জিজ্ঞেস করুনঃ সর্ববৃহৎ সাক্ষ্যদাতা কে ? বলে দিনঃ আল্লাহ আমার ও তোমাদের মধ্যে সাক্ষী। আমার প্রতি এ কোরআন অবর্তীর্ণ হয়েছে-যাতে আমি তোমাদেরকে এবং যাদের কাছে এ কোরআন পৌঁছে সবাইকে ভীতি প্রদর্শন করি। তোমরা কি সাক্ষ্য দাও যে, আল্লাহর সাথে অন্যান্য উপাস্যও রয়েছে ? আপনি বলে দিনঃ আমি এরূপ সাক্ষ্য দেব না। বলে দিনঃ তিনিই একমাত্র উপাস্য; আমি অবশ্যই তোমাদের শিরক থেকে মুক্ত।'),
  ('bn.bengali', 6, 20, 'যাদেরকে আমি কিতাব দান করেছি, তারা তাকে চিনে, যেমন তাদের সন্তানদেরকে চিনে। যারা নিজেদেরকে ক্ষতির মধ্যে ফেলেছে, তারা বিশ্বাস স্থাপন করবে না।'),
  ('bn.bengali', 6, 21, 'আর যে, আল্লাহর প্রতি অপবাদ আরোপ করে অথবা তাঁর নিদর্শনাবলীকে মিথ্যা বলে, তার চাইতে বড় জালেম কে? নিশ্চয় জালেমরা সফলকাম হবে না।'),
  ('bn.bengali', 6, 22, 'আর যেদিন আমি তাদের সবাইকে একত্রিত করব, অতঃপর যারা শিরক করেছিল, তাদের বলবঃ যাদেরকে তোমরা অংশীদার বলে ধারণা করতে, তারা কোথায়?'),
  ('bn.bengali', 6, 23, 'অতঃপর তাদের কোন অপরিচ্ছন্নতা থাকবে না; তবে এটুকুই যে তারা বলবে আমাদের প্রতিপালক আল্লাহর কসম, আমরা মুশরিক ছিলাম না।'),
  ('bn.bengali', 6, 24, 'দেখতো, কিভাবে মিথ্যা বলছে নিজেদের বিপক্ষে ? এবং যেসব বিষয় তারা আপনার প্রতি মিছামিছি রচনা করত, তা সবই উধাও হয়ে গেছে।'),
  ('bn.bengali', 6, 25, 'তাদের কেউ কেউ আপনার দিকে কান লাগিয়ে থাকে। আমি তাদের অন্তরের উপর আবরণ রেখে দিয়েছি যাতে একে না বুঝে এবং তাদের কানে বোঝা ভরে দিয়েছি। যদি তারা সব নিদর্শন অবলোকন করে তবুও সেগুলো বিশ্বাস করবে না। এমনকি, তারা যখন আপনার কাছে ঝগড়া করতে আসে, তখন কাফেররা বলেঃ এটি পুর্ববর্তীদের কিচ্ছাকাহিনী বৈ তো নয়।'),
  ('bn.bengali', 6, 26, 'তারা এ থেকে বাধা প্রদান করে এবং এ থেকে পলায়ন করে। তারা নিজেদেরকে ধ্বংস করেছে, কিন্তু বুঝছে না।'),
  ('bn.bengali', 6, 27, 'আর আপনি যদি দেখেন, যখন তাদেরকে দোযখের উপর দাঁড় করানো হবে! তারা বলবেঃ কতই না ভাল হত, যদি আমরা পুনঃ প্রেরিত হতাম; তা হলে আমরা স্বীয় পালনকর্তার নিদর্শনসমূহে মিথ্যারোপ করতাম না এবং আমরা বিশ্বাসীদের অন্তর্ভুক্ত হয়ে যেতাম।'),
  ('bn.bengali', 6, 28, 'এবং তারা ইতি পূর্বে যা গোপন করত, তা তাদের সামনে প্রকাশ হয়ে পড়েছে। যদি তারা পুনঃ প্রেরিত হয়, তবুও তাই করবে, যা তাদেরকে নিষেধ করা হয়েছিল। নিশ্চয় তারা মিথ্যাবাদী।'),
  ('bn.bengali', 6, 29, 'তারা বলেঃ আমাদের এ পার্থিব জীবনই জীবন। আমাদেরকে পুনরায় জীবিত হতে হবে না।'),
  ('bn.bengali', 6, 30, 'আর যদি আপনি দেখেন; যখন তাদেরকে প্রতিপালকের সামনে দাঁড় করানো হবে। তিনি বলবেনঃ এটা কি বাস্তব সত্য নয়? তারা বলবেঃ হঁ্যা আমাদের প্রতিপালকের কসম। তিনি বলবেনঃ অতএব, স্বীয় কুফরের কারণে শাস্তি আস্বাদন কর।'),
  ('bn.bengali', 6, 31, 'নিশ্চয় তারা ক্ষতিগ্রস্ত, যারা আল্লাহর সাক্ষাৎকে মিথ্যা মনে করেছে। এমনকি, যখন কিয়ামত তাদের কাছে অকস্মাৎ এসে যাবে, তারা বলবেঃ হায় আফসোস, এর ব্যাপারে আমরা কতই না ক্রটি করেছি। তার স্বীয় বোঝা স্বীয় পৃষ্ঠে বহন করবে। শুনে রাখ, তারা যে বোঝা বহন করবে, তা নিকৃষ্টতর বোঝা।'),
  ('bn.bengali', 6, 32, 'পার্থিব জীবন ক্রীড়া ও কৌতুক ব্যতীত কিছুই নয়। পরকালের আবাস পরহেযগারদের জন্যে শ্রেষ্টতর। তোমরা কি বুঝ না ?'),
  ('bn.bengali', 6, 33, 'আমার জানা আছে যে, তাদের উক্তি আপনাকে দুঃখিত করে। অতএব, তারা আপনাকে মিথ্যা প্রতিপন্ন করে না, বরং জালেমরা আল্লাহর নিদর্শনাবলীকে অস্বীকার করে।'),
  ('bn.bengali', 6, 34, 'আপনার পূর্ববর্তী অনেক পয়গম্বরকে মিথ্যা বলা হয়েছে। তাঁরা এতে ছবর করেছেন। তাদের কাছে আমার সাহায্য পৌঁছে পর্যন্ত তারা নির্যাতিত হয়েছেন। আল্লাহর বানী কেউ পরিবর্তন করতে পারে না। আপনার কাছে পয়গম্বরদের কিছু কাহিনী পৌঁছেছে।'),
  ('bn.bengali', 6, 35, 'আর যদি তাদের বিমুখতা আপনার পক্ষে কষ্টকর হয়, তবে আপনি যদি ভূতলে কোন সুড়ঙ্গ অথবা আকাশে কোন সিড়ি অনুসন্ধান করতে সমর্থ হন, অতঃপর তাদের কাছে কোন একটি মোজেযা আনতে পারেন, তবে নিয়ে আসুন। আল্লাহ ইচ্ছা করলে সবাইকে সরল পথে সমবেত করতে পারতেন। অতএব, আপনি নির্বোধদের অন্তর্ভুক্ত হবেন না।'),
  ('bn.bengali', 6, 36, 'তারাই মানে, যারা শ্রবণ করে। আল্লাহ মৃতদেরকে জীবিত করে উত্থিত করবেন। অতঃপর তারা তাঁরই দিকে প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 6, 37, 'তারা বলেঃ তার প্রতি তার পালনকর্তার পক্ষ থেকে কোন নিদর্শন অবতীর্ণ হয়নি কেন? বলে দিনঃ আল্লাহ নিদর্শন অবতরণ করতে পূর্ন সক্ষম; কিন্তু তাদের অধিকাংশই জানে না।'),
  ('bn.bengali', 6, 38, 'আর যত প্রকার প্রাণী পৃথিবীতে বিচরণশীল রয়েছে এবং যত প্রকার পাখী দু’ ডানাযোগে উড়ে বেড়ায় তারা সবাই তোমাদের মতই একেকটি শ্রেণী। আমি কোন কিছু লিখতে ছাড়িনি। অতঃপর সবাই স্বীয় প্রতিপালকের কাছে সমবেত হবে।'),
  ('bn.bengali', 6, 39, 'যারা আমার নিদর্শনসমূহকে মিথ্যা বলে, তারা অন্ধকারের মধ্যে মূক ও বধির। আল্লাহ যাকে ইচ্ছা পথভ্রষ্ট করেন এবং যাকে ইচ্ছা সরল পথে পরিচালিত করেন।'),
  ('bn.bengali', 6, 40, 'বলুন, বলতো দেখি, যদি তোমাদের উপর আল্লাহর শাস্তি পতিত হয় কিংবা তোমাদের কাছে কিয়ামত এসে যায়, তবে তোমরা কি আল্লাহ ব্যতীত অন্যকে ডাকবে যদি তোমরা সত্যবাদী হও।'),
  ('bn.bengali', 6, 41, 'বরং তোমরা তো তাঁকেই ডাকবে। অতঃপর যে বিপদের জন্যে তাঁকে ডাকবে, তিনি ইচ্ছা করলে তা দুরও করে দেন। যাদেরকে অংশীদার করছ, তখন তাদেরকে ভুলে যাবে।'),
  ('bn.bengali', 6, 42, 'আর আমি আপনার পূর্ববর্তী উম্মতদের প্রতিও পয়গম্বর প্রেরণ করেছিলাম। অতঃপর আমি তাদেরকে অভাব-অনটন ও রোগ-ব্যধি দ্বারা পাকড়াও করেছিলাম যাতে তারা কাকুতি মিনতি করে।'),
  ('bn.bengali', 6, 43, 'অতঃপর তাদের কাছে যখন আমার আযাব আসল, তখন কেন কাকুতি-মিনতি করল না ? বস্তুতঃ তাদের অন্তর কঠোর হয়ে গেল এবং শয়তান তাদের কাছে সুশোভিত করে দেখাল, যে কাজ তারা করছিল।'),
  ('bn.bengali', 6, 44, 'অতঃপর তারা যখন ঐ উপদেশ ভুলে গেল, যা তাদেরকে দেয়া হয়েছিল, তখন আমি তাদের সামনে সব কিছুর দ্বার উম্মুক্ত করে দিলাম। এমনকি, যখন তাদেরকে প্রদত্ত বিষয়াদির জন্যে তারা খুব গর্বিত হয়ে পড়ল, তখন আমি অকস্মাৎ তাদেরকে পাকড়াও করলাম। তখন তারা নিরাশ হয়ে গেল।'),
  ('bn.bengali', 6, 45, 'অতঃপর জালেমদের মূল শিকড় কর্তিত হল। সমস্ত প্রশংসা আল্লাহরই জন্যে, যিনি বিশ্বজগতের পালনকর্তা।'),
  ('bn.bengali', 6, 46, 'আপনি বলুনঃ বল তো দেখি, যদি আল্লাহ তোমাদের কান ও চোখ নিয়ে যান এবং তোমাদের অন্তরে মোহর এঁটে দেন, তবে এবং তোমাদের আল্লাহ ব্যতীত এমন উপাস্য কে আছে, যে তোমাদেরকে এগুলো এনে দেবে? দেখ, আমি কিভাবে ঘুরিয়ে-ফিরিয়ে নিদর্শনাবলী বর্ণনা করি। তথাপি তারা বিমুখ হচ্ছে।'),
  ('bn.bengali', 6, 47, 'বলে দিনঃ দেখতো, যদি আল্লাহর শাস্তি, আকস্মিক কিংবা প্রকাশ্যে তোমাদের উপর আসে, তবে জালেম, সম্প্রদায় ব্যতীত কে ধ্বংস হবে?'),
  ('bn.bengali', 6, 48, 'আমি পয়গম্বরদেরকে প্রেরণ করি না, কিন্তু সুসংবাদাতা ও ভীতি প্রদর্শকরূপে অতঃপর যে বিশ্বাস স্থাপন করে এবং সংশোধিত হয়, তাদের কোন শঙ্কা নেই এবং তারা দুঃখিত হবে না।'),
  ('bn.bengali', 6, 49, 'যারা আমার নিদর্শনাবলীকে মিথ্যা বলে, তাদেরকে তাদের নাফরমানীর কারণে আযাব স্পর্শ করবে।'),
  ('bn.bengali', 6, 50, 'আপনি বলুনঃ আমি তোমাদেরকে বলি না যে, আমার কাছে আল্লাহর ভান্ডার রয়েছে। তাছাড়া আমি অদৃশ্য বিষয় অবগতও নই। আমি এমন বলি না যে, আমি ফেরেশতা। আমি তো শুধু ঐ ওহীর অনুসরণ করি, যা আমার কাছে আসে। আপনি বলে দিনঃ অন্ধ ও চক্ষুমান কি সমান হতে পারে? তোমরা কি চিন্তা কর না ?'),
  ('bn.bengali', 6, 51, 'আপনি এ কোরআন দ্বারা তাদেরকে ভয়-প্রদর্শন করুন, যারা আশঙ্কা করে স্বীয় পালনকর্তার কাছে এমতাবস্থায় একত্রিত হওয়ার যে, তাদের কোন সাহায্যকারী ও সুপারিশকারী হবে না-যাতে তারা গোনাহ থেকে বেঁচে থাকে।'),
  ('bn.bengali', 6, 52, 'আর তাদেরকে বিতাড়িত করবেন না, যারা সকাল-বিকাল স্বীয় পালকর্তার এবাদত করে, তাঁর সন্তুষ্টি কামনা করে। তাদের হিসাব বিন্দুমাত্রও আপনার দায়িত্বে নয় এবং আপনার হিসাব বিন্দুমাত্রও তাদের দায়িত্বে নয় যে, আপনি তাদেরকে বিতাড়িত করবেন। নতুবা আপনি অবিচারকারীদের অন্তর্ভূক্ত হয়ে যাবেন।'),
  ('bn.bengali', 6, 53, 'আর এভাবেই আমি কিছু লোককে কিছু লোক দ্বারা পরীক্ষায় ফেলেছি যাতে তারা বলে যে, এদেরকেই কি আমাদের সবার মধ্য থেকে আল্লাহ স্বীয় অনুগ্রহ দান করেছেন? আল্লাহ কি কৃতজ্ঞদের সম্পর্কে সুপরিজ্ঞাত নন ?'),
  ('bn.bengali', 6, 54, 'আর যখন তারা আপনার কাছে আসবে যারা আমার নিদর্শনসমূহে বিশ্বাস করে, তখন আপনি বলে দিনঃ তোমাদের উপর শান্তি বর্ষিত হোক। তোমাদের পালনকর্তা রহমত করা নিজ দায়িত্বে লিখে নিয়েছেন যে, তোমাদের মধ্যে যে কেউ অজ্ঞতাবশতঃ কোন মন্দ কাজ করে, অনন্তর এরপরে তওবা করে নেয় এবং সৎ হয়ে যায়, তবে তিনি অত্যন্ত ক্ষমাশীল, করুণাময়।'),
  ('bn.bengali', 6, 55, 'আর এমনিভাবে আমি নিদর্শনসমূহ বিস্তারিত বর্ণনা করি-যাতে অপরাধীদের পথ সুস্পষ্ট হয়ে উঠে।'),
  ('bn.bengali', 6, 56, 'আপনি বলে দিনঃ আমাকে তাদের এবাদত করতে নিষেধ করা হয়েছে, তোমরা আল্লাহকে ছেড়ে যাদের এবাদত কর। আপনি বলে দিনঃ আমি তোমাদের খুশীমত চলবো না। কেননা, তাহলে আমি পথভ্রান্ত হয়ে যাব এবং সুপথগামীদের অন্তর্ভুক্ত হব না।'),
  ('bn.bengali', 6, 57, 'আপনি বলে দিনঃ আমার কাছে প্রতিপালকের পক্ষ থেকে একটি প্রমাণ আছে এবং তোমরা তার প্রতি মিথ্যারোপ করেছ। তোমরা যে বস্তু শীঘ্র দাবী করছ, তা আমার কাছে নেই। আল্লাহ ছাড়া কারো নির্দেশ চলে না। তিনি সত্য বর্ণনা করেন এবং তিনিই শ্রেষ্ঠতম মীমাংসাকারী।'),
  ('bn.bengali', 6, 58, 'আপনি বলে দিনঃ যদি আমার কাছে তা থাকত, যা তোমরা শীঘ্র দাবী করছ, তবে আমার ও তোমাদের পারস্পরিক বিবাদ কবেই চুকে যেত। আল্লাহ জালেমদের সম্পর্কে যথেষ্ট পরিমাণে অবহিত।'),
  ('bn.bengali', 6, 59, 'তাঁর কাছেই অদৃশ্য জগতের চাবি রয়েছে। এ গুলো তিনি ব্যতীত কেউ জানে না। স্থলে ও জলে যা আছে, তিনিই জানেন। কোন পাতা ঝরে না; কিন্তু তিনি তা জানেন। কোন শস্য কণা মৃত্তিকার অন্ধকার অংশে পতিত হয় না এবং কোন আর্দ্র ও শুস্ক দ্রব্য পতিত হয় না; কিন্তু তা সব প্রকাশ্য গ্রন্থে রয়েছে।'),
  ('bn.bengali', 6, 60, 'তিনিই রাত্রি বেলায় তোমাদেরকে করায়ত্ত করে নেন এবং যা কিছু তোমরা দিনের বেলায় কর, তা জানেন। অতঃপর তোমাদেরকে দিবসে সম্মুখিত করেন-যাতে নির্দিষ্ট ওয়াদা পূর্ণ হয়।'),
  ('bn.bengali', 6, 61, 'অনন্তর তাঁরই দিকে তোমাদের প্রত্যাবর্তন। অতঃপর তোমাদেরকে বলে দিবেন, যা কিছু তোমরা করছিলে। তিনিই স্বীয় বান্দাদের উপর প্রবল। তিনি প্রেরণ করেন তোমাদের কাছে রক্ষণাবেক্ষণকারী। এমন কি, যখন তোমাদের কারও মৃত্যু আসে তখন আমার প্রেরিত ফেরেশতারা তার আত্মা হস্তগত করে নেয়।'),
  ('bn.bengali', 6, 62, 'অতঃপর সবাইকে সত্যিকার প্রভু আল্লাহর কাছে পৌঁছানো হবে। শুনে রাখ, ফয়সালা তাঁরই এবং তিনি দ্রুত হিসাব গ্রহণ করবেন।'),
  ('bn.bengali', 6, 63, 'আপনি বলুনঃ কে তোমাদেরকে স্থল ও জলের অন্ধকার থেকে উদ্ধার করেন, যখন তোমরা তাঁকে বিনীতভাবে ও গোপনে আহবান কর যে, যদি আপনি আমাদের কে এ থেকে উদ্ধার করে নেন, তবে আমরা অবশ্যই কৃতজ্ঞদের অন্তর্ভুক্ত হয়ে যাব।'),
  ('bn.bengali', 6, 64, 'আপনি বলে দিনঃ আল্লাহ তোমাদেরকে তা থেকে মুক্তি দেন এব সব দুঃখ-বিপদ থেকে। তথাপি তোমরা শেরক কর।'),
  ('bn.bengali', 6, 65, 'আপনি বলুনঃ তিনিই শক্তিমান যে, তোমাদের উপর কোন শাস্তি উপর দিক থেকে অথবা তোমাদের পদতল থেকে প্রেরণ করবেন অথবা তোমাদেরকে দলে-উপদলে বিভক্ত করে সবাইকে মুখোমুখী করে দিবেন এবং এককে অন্যের উপর আক্রমণের স্বাদ আস্বাদন করাবেন। দেখ, আমি কেমন ঘুরিয়ে-ফিরিয়ে নিদর্শনাবলী বর্ণনা করি যাতে তারা বুঝে নেয়।'),
  ('bn.bengali', 6, 66, 'আপনার সম্প্রদায় একে মিথ্যা বলছে, অথচ তা সত্য। আপনি বলে দিনঃ আমি তোমাদের উপর নিয়োজিত নই।'),
  ('bn.bengali', 6, 67, 'প্রত্যেক খবরের একটি সময় নির্দিষ্ট রয়েছে এবং অচিরেই তোমরা তা জেনে নিবে।'),
  ('bn.bengali', 6, 68, 'যখন আপনি তাদেরকে দেখেন, যারা আমার আয়াত সমূহে ছিদ্রান্বেষণ করে, তখন তাদের কাছ থেকে সরে যান যে পর্যন্ত তারা অন্য কথায় প্রবৃত্ত না হয়, যদি শয়তান আপনাকে ভূলিয়ে দেয় তবে স্মরণ হওয়ার পর জালেমদের সাথে উপবেশন করবেন না।'),
  ('bn.bengali', 6, 69, 'এদের যখন বিচার করা হবে তখন পরহেযগারদের উপর এর কোন প্রভাব পড়বে না; কিন্তু তাদের দায়িত্ব উপদেশ দান করা যাতে ওরা ভীত হয়।'),
  ('bn.bengali', 6, 70, 'তাদেরকে পরিত্যাগ করুন, যারা নিজেদের ধর্মকে ক্রীড়া ও কৌতুকরূপে গ্রহণ করেছে এবং পার্থিব জীবন যাদেরকে ধোঁকায় ফেলে রেখেছে। কোরআন দ্বারা তাদেরকে উপদেশ দিন, যাতে কেউ স্বীয় কর্মে এমন ভাবে গ্রেফতার না হয়ে যায় যে, আল্লাহ ব্যতীত তার কোন সাহায্যকারী ও সুপারিশকারী নেই এবং যদি তারা জগতের বিনিময়ও প্রদান কবে, তবু তাদের কাছ থেকে তা গ্রহণ করা হবে না। একাই স্বীয় কর্মে জড়িত হয়ে পড়েছে। তাদের জন্যে উত্তপ্ত পানি এবং যন্ত্রণাদায়ক শাস্তি রয়েছে-কুফরের কারণে।'),
  ('bn.bengali', 6, 71, 'আপনি বলে দিনঃ আমরা কি আল্লাহ ব্যতীত এমন বস্তুকে আহবান করব, যে আমাদের উপকার করতে পারে না এবং ক্ষতিও করতে পারে না এবং আমরা কি পশ্চাৎপদে ফিরে যাব, এরপর যে, আল্লাহ আমাদেরকে পথ প্রদর্শন করেছেন? ঐ ব্যক্তির মত, যাকে শয়তানরা বনভুমিতে বিপথগামী করে দিয়েছে-সে উদভ্রান্ত হয়ে ঘোরাফেরা করছে। তার সহচররা তাকে পথের দিকে ডেকে বলছেঃ আস, আমাদের কাছে। আপনি বলে দিনঃ নিশ্চয় আল্লাহর পথই সুপথ। আমরা আদিষ্ট হয়েছি যাতে স্বীয় পালনকর্তা আজ্ঞাবহ হয়ে যাই।'),
  ('bn.bengali', 6, 72, 'এবং তা এই যে, নামায কায়েম কর এবং তাঁকে ভয় কর। তাঁর সামনেই তোমরা একত্রিত হবে।'),
  ('bn.bengali', 6, 73, 'তিনিই সঠিকভাবে নভোমন্ডল সৃষ্টি করেছেন। যেদিন তিনি বলবেনঃ হয়ে যা, অতঃপর হয়ে যাবে। তাঁর কথা সত্য। যেদিন শিঙ্গায় ফুৎকার করা হবে, সেদিন তাঁরই আধিপত্য হবে। তিনি অদৃশ্য বিষয়ে এবং প্রত্যক্ষ বিষয়ে জ্ঞাত। তিনিই প্রজ্ঞাময়, সর্বজ্ঞ।'),
  ('bn.bengali', 6, 74, 'স্মরণ কর, যখন ইব্রাহীম পিতা আযরকে বললেনঃ তুমি কি প্রতিমা সমূহকে উপাস্য মনে কর? আমি দেখতে পাচ্ছি যে, তুমি ও তোমার সম্প্রদায় প্রকাশ্য পথভ্রষ্ট।'),
  ('bn.bengali', 6, 75, 'আমি এরূপ ভাবেই ইব্রাহীমকে নভোমন্ডল ও ভুমন্ডলের অত্যাশ্চর্য বস্তুসমূহ দেখাতে লাগলাম-যাতে সে দৃঢ় বিশ্বাসী হয়ে যায়।'),
  ('bn.bengali', 6, 76, 'অনন্তর যখন রজনীর অন্ধকার তার উপর সমাচ্ছন্ন হল, তখন সে একটি তারকা দেখতে পেল, বললঃ ইহা আমার প্রতিপালক। অতঃপর যখন তা অস্তমিত হল তখন বললঃ আমি অস্তগামীদেরকে ভালবাসি না।'),
  ('bn.bengali', 6, 77, 'অতঃপর যখন চন্দ্রকে ঝলমল করতে দেখল, বললঃ এটি আমার প্রতিপালক। অনন্তর যখন তা অদৃশ্য হয়ে গেল, তখন বলল যদি আমার প্রতিপালক আমাকে পথ-প্রদর্শন না করেন, তবে অবশ্যই আমি বিভ্রান্ত সম্প্রদায়ের অন্তর্ভুক্ত হয়ে যাব।'),
  ('bn.bengali', 6, 78, 'অতঃপর যখন সূর্যকে চকচক করতে দেখল, বললঃ এটি আমার পালনকর্তা, এটি বৃহত্তর। অতপর যখন তা ডুবে গেল, তখন বলল হে আমার সম্প্রদায়, তোমরা যেসব বিষয়কে শরীক কর, আমি ওসব থেকে মুক্ত।'),
  ('bn.bengali', 6, 79, 'আমি এক মুখী হয়ে স্বীয় আনন ঐ সত্তার দিকে করেছি, যিনি নভোমন্ডল ও ভুমন্ডল সৃষ্টি করেছেন এবং আমি মুশরেক নই।'),
  ('bn.bengali', 6, 80, 'তাঁর সাথে তার সম্প্রদায় বিতর্ক করল। সে বললঃ তোমরা কি আমার সাথে আল্লাহর একত্ববাদ সম্পর্কে বিতর্ক করছ; অথচ তিনি আমাকে পথ প্রদর্শন করেছেন। তোমরা যাদেরকে শরীক কর, আমি তাদেরকে ভয় করি না তবে আমার পালকর্তাই যদি কোন কষ্ট দিতে চান। আমার পালনকর্তাই প্রত্যেক বস্তুকে স্বীয় জ্ঞান দ্বারা বেষ্টন করে আছেন। তোমরা কি চিন্তা কর না ?'),
  ('bn.bengali', 6, 81, 'যাদেরকে তোমরা আল্লাহর সাথে শরীক করে রেখেছ, তাদেরকে কিরূপে ভয় কর, অথচ তোমরা ভয় কর না যে, তোমরা আল্লাহর সাথে এমন বস্তুকে শরীক করছ, যাদের সম্পর্কে আল্লাহ তোমাদের প্রতি কোন প্রমাণ অবতীর্ণ করেননি। অতএব, উভয় সম্প্রদায়ের মধ্যে শাস্তি লাভের অধিক যোগ্য কে, যদি তোমরা জ্ঞানী হয়ে থাক।'),
  ('bn.bengali', 6, 82, 'যারা ঈমান আনে এবং স্বীয় বিশ্বাসকে শেরেকীর সাথে মিশ্রিত করে না, তাদের জন্যেই শান্তি এবং তারাই সুপথগামী।'),
  ('bn.bengali', 6, 83, 'এটি ছিল আমার যুক্তি, যা আমি ইব্রাহীমকে তাঁর সম্প্রަ#2470;ায়ের বিপক্ষে প্রদান করেছিলাম। আমি যাকে ইচ্ছা মর্যাদায় সমুন্নত করি। আপনার পালনকর্তা প্রজ্ঞাময়, মহাজ্ঞানী'),
  ('bn.bengali', 6, 84, 'আমি তাঁকে দান করেছি ইসহাক এবং এয়াকুব। প্রত্যেককেই আমি পথ প্রদর্শন করেছি এবং পূর্বে আমি নূহকে পথ প্রদর্শন করেছি-তাঁর সন্তানদের মধ্যে দাউদ, সোলায়মান, আইউব, ইউসুফ, মূসা ও হারুনকে। এমনিভাবে আমি সৎকর্মীদেরকে প্রতিদান দিয়ে থাকি।'),
  ('bn.bengali', 6, 85, 'আর ও যাকারিয়া, ইয়াহিয়া, ঈসা এবং ইলিয়াসকে। তারা সবাই পুণ্যবানদের অন্তর্ভুক্ত ছিল।'),
  ('bn.bengali', 6, 86, 'এবং ইসরাঈল, ইয়াসা, ইউনূস, লূতকে প্রত্যেককেই আমি সারা বিশ্বের উপর গৌরবাম্বিত করেছি।'),
  ('bn.bengali', 6, 87, 'আর ও তাদের কিছু সংখ্যক পিতৃপুরুষ, সন্তান-সন্ততি ও ভ্রাতাদেরকে; আমি তাদেরকে মনোনীত করেছি এবং সরল পথ প্রদর্শন করেছি।'),
  ('bn.bengali', 6, 88, 'এটি আল্লাহর হেদায়েত। স্বীয় বান্দাদের মধ্যে যাকে ইচ্ছা, এপথে চালান। যদি তারা শেরেকী করত, তবে তাদের কাজ কর্ম তাদের জন্যে ব্যর্থ হয়ে যেত।'),
  ('bn.bengali', 6, 89, 'তাদেরকেই আমি গ্রন্থ, শরীয়ত ও নবুয়ত দান করেছি। অতএব, যদি এরা আপনার নবুয়ত অস্বীকার করে, তবে এর জন্যে এমন সম্প্রদায় নির্দিষ্ট করেছি, যারা এতে অবিশ্বাসী হবে না।'),
  ('bn.bengali', 6, 90, 'এরা এমন ছিল, যাদেরকে আল্লাহ পথ প্রদর্শন করেছিলেন। অতএব, আপনিও তাদের পথ অনুসরণ করুন। আপনি বলে দিনঃ আমি তোমাদের কাছে এর জন্যে কোন পারিশ্রমিক চাই না। এটি সারা বিশ্বের জন্যে একটি উপদেশমাত্র।'),
  ('bn.bengali', 6, 91, 'তারা আল্লাহকে যথার্থ মূল্যায়ন করতে পারেনি, যখন তারা বললঃ আল্লাহ কোন মানুষের প্রতি কোন কিছু অবতীর্ণ করেননি। আপনি জিজ্ঞেস করুনঃ ঐ গ্রন্থ কে নাযিল করেছে, যা মূসা নিয়ে এসেছিল ? যা জ্যোতিবিশেষ এবং মানব মন্ডলীর জন্যে হোদায়েতস্বরূপ, যা তোমরা বিক্ষিপ্তপত্রে রেখে লোকদের জন্যে প্রকাশ করছ এবং বহুলাংশকে গোপন করছ। তোমাদেরকে এমন অনেক বিষয় শিক্ষা দেয়া হয়েছে, যা তোমরা এবং তোমাদের পূর্বপুরুষরা জানতো না। আপনি বলে দিনঃ আল্লাহ নাযিল করেছেন। অতঃপর তাদেরকে তাদের ক্রীড়ামূলক বৃত্তিতে ব্যাপৃত থাকতে দিন।'),
  ('bn.bengali', 6, 92, 'এ কোরআন এমন গ্রন্থ, যা আমি অবতীর্ন করেছি; বরকতময়, পূর্ববর্তী গ্রন্থের সত্যতা প্রমাণকারী এবং যাতে আপনি মক্কাবাসী ও পাশ্ববর্তীদেরকে ভয় প্রদর্শন করেন। যারা পরকালে বিশ্বাস স্থাপন করে তারা এর প্রতি বিশ্বাস স্থাপন করে এবং তার স্বীয় নামায সংরক্ষণ করে।'),
  ('bn.bengali', 6, 93, 'ঐ ব্যক্তির চাইতে বড় জালেম কে হবে, যে আল্লাহর প্রতি মিথ্যা আরোপ করে অথবা বলেঃ আমার প্রতি ওহী অবতীর্ণ হয়েছে। অথচ তার প্রতি কোন ওহী আসেনি এবং যে দাবী করে যে, আমিও নাযিল করে দেখাচ্ছি যেমন আল্লাহ নাযিল করেছেন। যদি আপনি দেখেন যখন জালেমরা মৃত্যু যন্ত্রণায় থাকে এবং ফেরেশতারা স্বীয় হস্ত প্রসারিত করে বলে, বের কর স্বীয় আত্মা! অদ্য তোমাদেরকে অবমাননাকর শাস্তি প্রদান করা হবে। কারণ, তোমরা আল্লাহর উপর অসত্য বলতে এবং তাঁর আয়াত সমূহ থেকে অহংকার করতে।'),
  ('bn.bengali', 6, 94, 'তোমরা আমার কাছে নিঃসঙ্গ হয়ে এসেছ, আমি প্রথমবার তোমাদেরকে সৃষ্টি করেছিলাম। আমি তোদেরকে যা দিয়েছিলাম, তা পশ্চাতেই রেখে এসেছ। আমি তো তোমাদের সাথে তোমাদের সুপারিশকারীদের কে দেখছি না। যাদের সম্পর্কে তোমাদের দাবী ছিল যে, তারা তোমাদের ব্যাপারে অংশীদার। বাস্তুবিকই তোমাদের পরস্পরের সম্পর্ক ছিন্ন হয়ে গেছে এবং তোমাদের দাবী উধাও হয়ে গেছে।'),
  ('bn.bengali', 6, 95, 'নিশ্চয় আল্লাহই বীজ ও আঁটি থেকে অঙ্কুর সৃষ্টিকারী; তিনি জীবিতকে মৃত থেকে বের করেন ও মৃতকে জীবিত থেকে বের করেন। তিনি আল্লাহ অতঃপর তোমরা কোথায় বিভ্রান্ত হচ্ছ?'),
  ('bn.bengali', 6, 96, 'তিনি প্রভাত রশ্মির উন্মেষক। তিনি রাত্রিকে আরামদায়ক করেছেন এবং সূর্য ও চন্দ্রকে হিসেবের জন্য রেখেছেন। এটি পরাক্রান্ত, মহাজ্ঞানীর নির্ধারণ।'),
  ('bn.bengali', 6, 97, 'তিনিই তোমাদের জন্য নক্ষত্রপুঞ্জ সৃজন করেছেন যাতে তোমরা স্থল ও জলের অন্ধকারে পথ প্রাপ্ত হও। নিশ্চয় যারা জ্ঞানী তাদের জন্যে আমি নির্দেশনাবলী বিস্তারিত বর্ণনা করে দিয়েছি।'),
  ('bn.bengali', 6, 98, 'তিনিই তোমাদের কে এক ব্যক্তি থেকে সৃষ্টি করেছেন। অনন্তর একটি হচ্ছে তোমাদের স্থায়ী ঠিকানা ও একটি হচ্ছে গচ্ছিত স্থল। নিশ্চয় আমি প্রমাণাদি বিস্তারিত ভাবে বর্ণনা করে দিয়েছি তাদের জন্যে, যারা চিন্তা করে।'),
  ('bn.bengali', 6, 99, 'তিনিই আকাশ থেকে পানি বর্ষণ করেছেন অতঃপর আমি এর দ্বারা সর্বপ্রকার উদ্ভিদ উৎপন্ন করেছি, অতঃপর আমি এ থেকে সবুজ ফসল নির্গত করেছি, যা থেকে যুগ্ম বীজ উৎপন্ন করি। খেজুরের কাঁদি থেকে গুচ্ছ বের করি, যা নুয়ে থাকে এবং আঙ্গুরের বাগান, যয়তুন, আনার পরস্পর সাদৃশ্যযুক্ত এবং সাদৃশ্যহীন। বিভিন্ন গাছের ফলের প্রতি লক্ষ্য কর যখন সেুগুলো ফলন্ত হয় এবং তার পরিপক্কতার প্রতি লক্ষ্য কর। নিশ্চয় এ গুলোতে নিদর্শন রয়েছে ঈমানদারদের জন্যে।'),
  ('bn.bengali', 6, 100, 'তারা জিনদেরকে আল্লাহর অংশীদার স্থির করে; অথচ তাদেরকে তিনিই সৃস্টি করেছেন। তারা অজ্ঞতাবশতঃ আল্লাহর জন্যে পুত্র ও কন্যা সাব্যস্ত করে নিয়েছে। তিনি পবিত্র ও সমুন্নত, তাদের বর্ননা থেকে।'),
  ('bn.bengali', 6, 101, 'তিনি নভোমন্ডল ও ভূমন্ডলের আদি স্রষ্টা। কিরূপে আল্লাহর পুত্র হতে পারে, অথচ তাঁর কোন সঙ্গী নেই ? তিনি যাবতীয় কিছু সৃষ্টি করেছেন। তিনি সব বস্তু সম্পর্কে সুবিজ্ঞ।'),
  ('bn.bengali', 6, 102, 'তিনিই আল্লাহ তোমাদের পালনকর্তা। তিনি ব্যতীত কোন উপাস্য নেই। তিনিই সব কিছুর স্রষ্টা। অতএব, তোমরা তাঁরই এবাদত কর। তিনি প্রত্যেক বস্তুর কার্যনির্বাহী।'),
  ('bn.bengali', 6, 103, 'দৃষ্টিসমূহ তাঁকে পেতে পারে না, অবশ্য তিনি দৃষ্টিসমূহকে পেতে পারেন। তিনি অত্যন্ত সুক্ষদর্শী, সুবিজ্ঞ।'),
  ('bn.bengali', 6, 104, 'তোমাদের কাছে তোমাদের পালনকর্তার পক্ষ থেকে নিদর্শনাবলী এসে গেছে। অতএব, যে প্রত্যক্ষ করবে, সে নিজেরই উপকার করবে এবং যে অন্ধ হবে, সে নিজেরই ক্ষতি করবে। আমি তোমাদের পর্যবেক্ষক নই।'),
  ('bn.bengali', 6, 105, 'এমনি ভাবে আমি নিদর্শনাবলী ঘুরিয়ে-ফিরিয়ে বর্ণনা করি যাতে তারা না বলে যে, আপনি তো পড়ে নিয়েছেন এবং যাতে আমি একে সুধীবৃন্দের জন্যে খুব পরিব্যক্ত করে দেই।'),
  ('bn.bengali', 6, 106, 'আপনি পথ অনুসরণ করুন, যার আদেশ পালনকর্তার পক্ষ থেকে আসে। তিনি ব্যতীত কোন উপাস্য নেই এবং মুশরিকদের তরফ থেকে মুখ ফিরিয়ে নিন।'),
  ('bn.bengali', 6, 107, 'যদি আল্লাহ চাইতেন তবে তারা শেরক করত না। আমি আপনাকে তাদের সংরক্ষক করিনি এবং আপনি তাদের কার্যনির্বাহী নন।'),
  ('bn.bengali', 6, 108, 'তোমরা তাদেরকে মন্দ বলো না, যাদের তারা আরাধনা করে আল্লাহকে ছেড়ে। তাহলে তারা ধৃষ্টতা করে অজ্ঞতাবশতঃ আল্লাহকে মন্দ বলবে। এমনিভাবে আমি প্রত্যেক সম্প্রদায়ের দৃষ্টিতে তাদের কাজ কর্ম সুশোভিত করে দিয়েছি। অতঃপর স্বীয় পালনকর্তার কাছে তাদেরকে প্রত্যাবর্তন করতে হবে। তখন তিনি তাদেরকে বলে দেবেন যা কিছু তারা করত।'),
  ('bn.bengali', 6, 109, 'তারা জোর দিয়ে আল্লাহর কসম খায় যে, যদি তাদের কাছে কোন নিদর্শন আসে, তবে অবশ্যই তারা বিশ্বাস স্থাপন করবে। আপনি বলে দিনঃ নিদর্শনাবলী তো আল্লাহর কাছেই আছে। হে মুসলমানগণ, তোমাদেরকে কে বলল যে, যখন তাদের কাছে নিদর্শনাবলী আসবে, তখন তারা বিশ্বাস স্থাপন করবেই ?'),
  ('bn.bengali', 6, 110, 'আমি ঘুরিয়ে দিব তাদের অন্তর ও দৃষ্টিকে, যেমন-তারা এর প্রতি প্রথমবার বিশ্বাস স্থাপন করেনি এবং আমি তাদেরকে তাদের অবাধ্যতায় উদভ্রান্ত ছেড়ে দিব।'),
  ('bn.bengali', 6, 111, 'আমি যদি তাদের কাছে ফেরেশতাদেরকে অবতারণ করতাম এবং তাদের সাথে মৃতরা কথাবার্তা বলত এবং আমি সব বস্তুকে তাদের সামনে জীবিত করে দিতাম, তথাপি তারা কখনও বিশ্বাস স্থাপনকারী নয়; কিন্তু যদি আল্লাহ চান। কিন্তু তাদের অধিকাংশই মুর্খ।'),
  ('bn.bengali', 6, 112, 'এমনিভাবে আমি প্রত্যেক নবীর জন্যে শত্রু করেছি শয়তান, মানব ও জিনকে। তারা ধোঁকা দেয়ার জন্যে একে অপরকে কারুকার্যখচিত কথাবার্তা শিক্ষা দেয়। যদি আপনার পালনকর্তা চাইতেন, তবে তারা এ কাজ করত না।'),
  ('bn.bengali', 6, 113, 'অতএব, আপনি তাদেরকে এবং তাদের মিথ্যাপবাদকে মুক্ত ছেড়ে দিন যাতে কারুকার্যখচিত বাক্যের প্রতি তাদের মন আকৃষ্ট হয় যারা পরকালে বিশ্বাস করে না এবং তারা একেও পছন্দ করে নেয় এবং যাতে ঐসব কাজ করে, যা তারা করছে।'),
  ('bn.bengali', 6, 114, 'তবে কি আমি আল্লাহ ব্যতীত অন্য কোন বিচারক অনুসন্ধান করব, অথচ তিনিই তোমাদের প্রতি বিস্তারিত গ্রন্থ অবতীর্ন করেছেন? আমি যাদেরকে গ্রন্থ প্রদান করেছি, তারা নিশ্চিত জানে যে, এটি আপনার প্রতি পালকের পক্ষ থেকে সত্যসহ অবর্তীর্ন হয়েছে। অতএব, আপনি সংশয়কারীদের অন্তর্ভুক্ত হবেন না।'),
  ('bn.bengali', 6, 115, 'আপনার প্রতিপালকের বাক্য পূর্ণ সত্য ও সুষম। তাঁর বাক্যের কোন পরিবর্তনকারী নেই। তিনিই শ্রবণকারী, মহাজ্ঞানী।'),
  ('bn.bengali', 6, 116, 'আর যদি আপনি পৃথিবীর অধিকাংশ লোকের কথা মেনে নেন, তবে তারা আপনাকে আল্লাহর পথ থেকে বিপথগামী করে দেবে। তারা শুধু অলীক কল্পনার অনুসরণ করে এবং সম্পূর্ণ অনুমান ভিত্তিক কথাবার্তা বলে থাকে।'),
  ('bn.bengali', 6, 117, 'আপনার প্রতিপালক তাদের সম্পর্কে খুব জ্ঞাত রয়েছেন, যারা তাঁর পথ থেকে বিপথগামী হয় এবং তিনি তাদেরকেও খুব ভাল করে জানেন, যারা তাঁর পথে অনুগমন করে।'),
  ('bn.bengali', 6, 118, 'অতঃপর যে জন্তুর উপর আল্লাহর নাম উচ্চারিত হয়, তা থেকে ভক্ষণ কর যদি তোমরা তাঁর বিধানসমূহে বিশ্বাসী হও।'),
  ('bn.bengali', 6, 119, 'কোন কারণে তোমরা এমন জন্তু থেকে ভক্ষণ করবে না, যার উপর আল্লাহর নাম উচ্চারিত হয়, অথচ আল্লাহ ঐ সব জন্তুর বিশদ বিবরণ দিয়েছেন, যেগুলোকে তোমাদের জন্যে হারাম করেছেন; কিন্তু সেগুলোও তোমাদের জন্যে হালাল, যখন তোমরা নিরুপায় হয়ে যাও। অনেক লোক স্বীয় ভ্রান্ত প্রবৃত্তি দ্বারা না জেনে বিপথগামী করতে থাকে। আপনার প্রতিপালক সীমাতিক্রম কারীদেরকে যথার্থই জানেন।'),
  ('bn.bengali', 6, 120, 'তোমরা প্রকাশ্য ও প্রচ্ছন্ন গোনাহ পরিত্যাগ কর। নিশ্চয় যারা গোনাহ করেছে, তারা অতিসত্বর তাদের কৃতকর্মের শাস্তি পাবে।'),
  ('bn.bengali', 6, 121, 'যেসব জন্তুর উপর আল্লাহর নাম উচ্চারিত হয় না, সেগুলো থেকে ভক্ষণ করো না; এ ভক্ষণ করা গোনাহ। নিশ্চয় শয়তানরা তাদের বন্ধুদেরকে প্রত্যাদেশ করে-যেন তারা তোমাদের সাথে তর্ক করে। যদি তোমরা তাদের আনুগত্য কর, তোমরাও মুশরেক হয়ে যাবে।'),
  ('bn.bengali', 6, 122, 'আর যে মৃত ছিল অতঃপর আমি তাকে জীবিত করেছি এবং তাকে এমন একটি আলো দিয়েছি, যা নিয়ে সে মানুষের মধ্যে চলাফেরা করে। সে কি ঐ ব্যক্তির সমতুল্য হতে পারে, যে অন্ধকারে রয়েছে-সেখান থেকে বের হতে পারছে না? এমনিভাবে কাফেরদের দৃষ্টিতে তাদের কাজকর্মকে সুশোভিত করে দেয়া হয়েছে।'),
  ('bn.bengali', 6, 123, 'আর এমনিভাবে আমি প্রত্যেক জনপদে অপরাধীদের জন্য কিছু সর্দার নিয়োগ করেছি-যেন তারা সেখানে চক্রান্ত করে। তাদের সে চক্রান্ত তাদের নিজেদের বিরুদ্ধেই; কিন্তু তারা তা উপলব্ধি করতে পারে না।'),
  ('bn.bengali', 6, 124, 'যখন তাদের কাছে কোন আয়াত পৌঁছে, তখন বলে, আমরা কখনই মানব না যে, পর্যন্ত না আমরাও তা প্রদত্ত হই, যা আল্লাহর রসূলগণ প্রদত্ত হয়েছেন। আল্লাহ এ বিষয়ে সুপারিজ্ঞাত যে, কোথায় স্বীয় পয়গাম প্রেরণ করতে হবে। যারা অপরাধ করছে, তারা অতিসত্বর আল্লাহর কাছে পৌছে লাঞ্ছনা ও কঠোর শাস্তি পাবে, তাদের চক্রান্তের কারণে।'),
  ('bn.bengali', 6, 125, 'অতঃপর আল্লাহ যাকে পথ-প্রদর্শন করতে চান, তার বক্ষকে ইসলামের জন্যে উম্মুক্ত করে দেন এবং যাকে বিপথগামী করতে চান, তার বক্ষকে সংকীর্ণ অত্যধিক সংকীর্ণ করে দেন-যেন সে সবেগে আকাশে আরোহণ করছে। এমনি ভাবে যারা বিশ্বাস স্থাপন করে না। আল্লাহ তাদের উপর আযাব বর্ষন করেন।'),
  ('bn.bengali', 6, 126, 'আর এটাই আপনার পালনকর্তার সরল পথ। আমি উপদেশ গ্রহণকারীদের জন্যে আয়াতসমূহ পুঙ্খানুপুঙ্খ বর্ননা করেছি।'),
  ('bn.bengali', 6, 127, 'তাদের জন্যেই তাদের প্রতিপালকের কাছে নিরাপত্তার গৃহ রয়েছে এবং তিনি তাদের বন্ধু তাদের কর্মের কারণে।'),
  ('bn.bengali', 6, 128, 'যেদিন আল্লাহ সবাইকে একত্রিত করবেন, হে জিন সম্প্রদায়, তোমরা মানুষদের মধ্যে অনেককে অনুগামী করে নিয়েছ। তাদের মানব বন্ধুরা বলবেঃ হে আমাদের পালনকর্তা, আমরা পরস্পরে পরস্পরের মাধ্যমে ফল লাভ করেছি। আপনি আমাদের জন্যে যে সময় নির্ধারণ করেছিলেন, আমরা তাতে উপনীত হয়েছি। আল্লাহ বলবেনঃ আগুন হল তোমাদের বাসস্থান। তথায় তোমরা চিরকাল অবস্থান করবে; কিন্তু যখন চাইবেন আল্লাহ। নিশ্চয় আপনার পালনকর্তা প্রজ্ঞাময়, মহাজ্ঞানী।'),
  ('bn.bengali', 6, 129, 'এমনিভাবে আমি পাপীদেরকে একে অপরের সাথে যুক্ত করে দেব তাদের কাজকর্মের কারণে।'),
  ('bn.bengali', 6, 130, 'হে জ্বিন ও মানব সম্প্রদায়, তোমাদের কাছে কি তোমাদের মধ্য থেকে পয়গম্বরগণ আগমন করেনি? যাঁরা তোমাদেরকে আমার বিধানাবলী বর্ণনা করতেন এবং তোমাদেরকে আজকের এ দিনের সাক্ষাতের ভীতি প্রদর্শন করতেন? তারা বলবেঃ আমরা স্বীয় গোনাহ স্বীকার করে নিলাম। পার্থিব জীবন তাদেরকে প্রতারিত করেছে। তারা নিজেদের বিরুদ্ধে স্বীকার করে নিয়েছে যে, তারা কাফের ছিল।'),
  ('bn.bengali', 6, 131, 'এটা এ জন্যে যে, আপনার প্রতিপালক কোন জনপদের অধিবাসীদেরকে জুলুমের কারণে ধ্বংস করেন না এমতাবস্থায় যে, তথাকার অধিবাসীরা অজ্ঞ থাকে।'),
  ('bn.bengali', 6, 132, 'প্রত্যেকের জন্যে তাদের কর্মের আনুপাতিক মর্যাদা আছে এবং আপনার প্রতিপালক তাদের কর্ম সম্পর্কে বেখবর নন।'),
  ('bn.bengali', 6, 133, 'আপনার প্রতিপালক অমুখাপেক্ষী, করুণাময়। তিনি ইচ্ছা করলে তোমাদের সবাইকে উচ্ছেদ করে দিবেন এবং তোমাদের পর যাকে ইচ্ছা তোমাদের স্থলে অভিষিক্ত করবেন; যেমন তোমাদেরকে অন্য এক সম্প্রদায়ের বংশধর থেকে সৃষ্টি করেছেন।'),
  ('bn.bengali', 6, 134, 'যে বিষয়ের ওয়াদা তোমাদের সাথে করা হয়, তা অবশ্যই আগমন করবে এবং তোমরা অক্ষম করতে পারবে না।'),
  ('bn.bengali', 6, 135, 'আপনি বলে দিনঃ হে আমার সম্প্রদায়, তোমরা স্বস্থানে কাজ করে যাও, আমিও কাজ করি। অচিরেই জানতে পারবে যে, পরিণাম গৃহ কে লাভ করে। নিশ্চয় জালেমরা সুফলপ্রাপ্ত হবে না।'),
  ('bn.bengali', 6, 136, 'আল্লাহ যেসব শস্যক্ষেত্র ও জীবজন্তু সৃষ্টি করেছেন, সেগুলো থেকে তারা এক অংশ আল্লাহর জন্য নির্ধারণ করে অতঃপর নিজ ধারণা অনুসারে বলে এটা আল্লাহর এবং এটা আমাদের অংশীদারদের। অতঃপর যে অংশ তাদের অংশীদারদের, তা তো আল্লাহর দিকে পৌঁছে না এবং যা আল্লাহর তা তাদের উপাস্যদের দিকে পৌছে যায়। তাদের বিচার কতই না মন্দ।'),
  ('bn.bengali', 6, 137, 'এমনিভাবে অনেক মুশরেকের দৃষ্টিতে তাদের উপাস্যরা সন্তান হত্যাকে সুশোভিত করে দিয়েছে যেন তারা তাদেরকে বিনষ্ট করে দেয় এবং তাদের ধর্মমতকে তাদের কাছে বিভ্রান্ত করে দেয়। যদি আল্লাহ চাইতেন, তবে তারা এ কাজ করত না। অতএব, আপনি তাদেরকে এবং তাদের মনগড়া বুলিকে পরিত্যাগ করুন।'),
  ('bn.bengali', 6, 138, 'তারা বলেঃ এসব চতুষ্পদ জন্তু ও শস্যক্ষেত্র নিষিদ্ধ। আমরা যাকে ইচছা করি, সে ছাড়া এগুলো কেউ খেতে পারবে না, তাদের ধারণা অনুসারে। আর কিছুসংখ্যক চতুষ্পদ জন্তুর পিঠে আরোহন হারাম করা হয়েছে এবং কিছু সংখ্যক চতুষ্পদ জন্তুর উপর তারা ভ্রান্ত ধারনা বশতঃ আল্লাহর নাম উচ্চারণ করে না, তাদের মনগড়া বুলির কারণে, অচিরেই তিনি তাদের কে শাস্তি দিবেন।'),
  ('bn.bengali', 6, 139, 'তারা বলেঃ এসব চতুষ্পদ জন্তুর পেটে যা আছে, তা বিশেষ ভাবে আমাদের পুরুষদের জন্যে এবং আমাদের মহিলাদের জন্যে তা হারাম। যদি তা মৃত হয়, তবে তার প্রাপক হিসাবে সবাই সমান। অচিরেই তিনি তাদেরকে তাদের বর্ণনার শাস্তি দিবেন। তিনি প্রজ্ঞাময়, মহাজ্ঞানী।'),
  ('bn.bengali', 6, 140, 'নিশ্চয় তারা ক্ষতিগ্রস্ত হয়েছে, যারা নিজ সন্তানদেরকে নির্বুদ্ধিতাবশতঃ কোন প্রমাণ ছাড়াই হত্যা করেছে এবং আল্লাহ তাদেরকে যেসব দিয়েছিলেন, সেগুলোকে আল্লাহর প্রতি ভ্রান্ত ধারণা পোষণ করে হারাম করে নিয়েছে। নিশ্চিতই তারা পথভ্রষ্ট হয়েছে এবং সুপথগামী হয়নি।'),
  ('bn.bengali', 6, 141, 'তিনিই উদ্যান সমূহ সৃষ্টি করেছে-তাও, যা মাচার উপর তুলে দেয়া হয়, এবং যা মাচার উপর তোলা হয় না এবং খর্জুর বৃক্ষ ও শস্যক্ষেত্র যেসবের স্বাদবিশিষ্ট এবং যয়তুন ও আনার সৃষ্টি করেছেন-একে অন্যের সাদৃশ্যশীল এবং সাদৃশ্যহীন। এগুলোর ফল খাও, যখন ফলন্ত হয় এবং হক দান কর কর্তনের সময়ে এবং অপব্যয় করো না। নিশ্চয় তিনি অপব্যয়ীদেরকে পছন্দ করেন না।'),
  ('bn.bengali', 6, 142, 'তিনি সৃষ্টি করেছেন চতুষ্পদ জন্তুর মধ্যে বোঝা বহনকারীকে এবং খর্বাকৃতিকে। আল্লাহ তোমাদেরকে যা কিছু দিয়েছেন, তা থেকে খাও এবং শয়তানের পদাঙ্ক অনুসরণ করো না। সে তোমাদের প্রকাশ্য শত্রু।'),
  ('bn.bengali', 6, 143, 'সৃষ্টি করেছেন আটটি নর ও মাদী। ভেড়ার মধ্যে দুই প্রকার ও ছাগলের মধ্যে দুই প্রকার। জিজ্ঞেস করুন, তিনি কি উভয় নর হারাম করেছেন, না উভয় মাদীকে ? না যা উভয় মাদীর পেটে আছে? তোমরা আমাকে প্রমাণসহ বল, যদি তোমরা সত্যবাদী হও।'),
  ('bn.bengali', 6, 144, 'সৃষ্টি করেছেন উটের মধ্যে দুই প্রকার এবং গরুর মধ্যে দুই প্রকার। আপনি জিজ্ঞেস করুনঃ তিনি কি উভয় নর হারাম করেছেন, না উভয় মাদীকে, না যা উভয় মাদীর পেটে আছে? তোমরা কি উপস্থিত ছিলে, যখন আল্লাহ এ নির্দেশ দিয়েছিলেন? অতএব সে ব্যক্তি অপেক্ষা বেশী অত্যচারী কে, যে আল্লাহ সম্পর্কে মিথ্যা ধারণা পোষন করে যাতে করে মানুষকে বিনা প্রমাণে পথভ্রষ্ট করতে পারে? নিশ্চয় আল্লাহ অত্যাচারী সম্প্রদায়কে পথপ্রদর্শন করেন না।'),
  ('bn.bengali', 6, 145, 'আপনি বলে দিনঃ যা কিছু বিধান ওহীর মাধ্যমে আমার কাছে পৌঁছেছে, তন্মধ্যে আমি কোন হারাম খাদ্য পাই না কোন ভক্ষণকারীর জন্যে, যা সে ভক্ষণ করে; কিন্তু মৃত অথবা প্রবাহিত রক্ত অথবা শুকরের মাংস এটা অপবিত্র অথবা অবৈধ; যবেহ করা জন্তু যা আল্লাহ ছাড়া অন্যের নামে উৎসর্গ করা হয়। অতপর যে ক্ষুধায় কাতর হয়ে পড়ে এমতাবস্থায় যে অবাধ্যতা করে না এবং সীমালঙ্গন করে না, নিশ্চয় আপনার পালনকর্তা ক্ষমাশীল দয়ালু।'),
  ('bn.bengali', 6, 146, 'ইহুদীদের জন্যে আমি প্রত্যেক নখবিশিষ্ট জন্তু হারাম করেছিলাম এবং ছাগল ও গরু থেকে এতদুভয়ের চর্বি আমি তাদের জন্যে হারাম করেছিলাম, কিন্তু ঐ চর্বি, যা পৃষ্টে কিংবা অন্ত্রে সংযুক্ত থাকে অথবা অস্থির সাথে মিলিত থাকে। তাদের অবাধ্যতার কারণে আমি তাদেরকে এ শাস্তি দিয়েছিলাম। আর আমি অবশ্যই সত্যবাদী।'),
  ('bn.bengali', 6, 147, 'যদি তারা আপনাকে মিথ্যবাদী বলে, তবে বলে দিনঃ তোমার প্রতিপালক সুপ্রশস্ত করুণার মালিক। তাঁর শাস্তি অপরাধীদের উপর থেকে টলবে না।'),
  ('bn.bengali', 6, 148, 'এখন মুশরেকরা বলবেঃ যদি আল্লাহ ইচ্ছা করতেন, তবে না আমরা শিরক করতাম, না আমাদের বাপ দাদারা এবং না আমরা কোন বস্তুকে হারাম করতাম। এমনিভাবে তাদের পূর্ববর্তীরা মিথ্যারোপ করেছে, এমন কি তারা আমার শাস্তি আস্বাদন করেছে। আপনি বলুনঃ তোমাদের কাছে কি কোন প্রমাণ আছে যা আমাদেরকে দেখাতে পার। তোমরা শুধুমাত্র আন্দাজের অনুসরণ কর এবং তোমরা শুধু অনুমান করে কথা বল।'),
  ('bn.bengali', 6, 149, 'আপনি বলে দিনঃ অতএব, পরিপূর্ন যুক্তি আল্লাহরই। তিনি ইচ্ছা করলে তোমাদের সবাইকে পথ প্রদর্শন করতেন।'),
  ('bn.bengali', 6, 150, 'আপনি বলুনঃ তোমাদের সাক্ষীদেরকে আন, যারা সাক্ষ্য দেয় যে, আল্লাহ তা’আলা এগুলো হারাম করেছেন। যদি তারা সাক্ষ্য দেয়, তবে আপনি এ সাক্ষ্য গ্রহণ করবেন না এবং তাদের কুপ্রবৃত্তির অনুসরণ করবেন না, যারা আমার নির্দেশাবলীকে মিথ্যা বলে, যারা পরকালে বিশ্বাস করে না এবং যারা স্বীয় প্রতিপালকের সমতুল্য অংশীদার করে।'),
  ('bn.bengali', 6, 151, 'আপনি বলুনঃ এস, আমি তোমাদেরকে ঐসব বিষয় পাঠ করে শুনাই, যেগুলো তোমাদের প্রতিপালক তোমাদের জন্যে হারাম করেছেন। তাএই যে, আল্লাহর সাথে কোন কিছুকে অংশীদার করো না, পিতা-মাতার সাথে সদয় ব্যবহার করো স্বীয় সন্তানদেরকে দারিদ্রে?480; কারণে হত্যা করো না, আমি তোমাদেরকে ও তাদেরকে আহার দেই, নির্লজ্জতার কাছেও যেয়ো না, প্রকাশ্য হোক কিংবা অপ্রকাশ্য, যাকে হত্যা করা আল্লাহ হারাম করেছেন, তাকে হত্যা করো না; কিন্তু ন্যায়ভাবে। তোমাদেরকে এ নির্দেশ দিয়েছেন, যেন তোমরা বুঝ।'),
  ('bn.bengali', 6, 152, 'এতীমদের ধনসম্পদের কাছেও যেয়ো না; কিন্তু উত্তম পন্থায় যে পর্যন্ত সে বয়ঃপ্রাপ্ত না হয়। ওজন ও মাপ পূর্ণ কর ন্যায় সহকারে। আমি কাউকে তার সাধ্যের অতীত কষ্ট দেই না। যখন তোমরা কথা বল, তখন সুবিচার কর, যদিও সে আত্নীয়ও হয়। আল্লাহর অঙ্গীকার পূর্ণ কর।'),
  ('bn.bengali', 6, 153, 'তোমাদেরকে এ নির্দেশ দিয়েছেন, যেন তোমরা উপদেশ গ্রহণ কর। নিশ্চিত এটি আমার সরল পথ। অতএব, এ পথে চল এবং অন্যান্য পথে চলো না। তা হলে সেসব পথ তোমাদেরকে তাঁর পথ থেকে বিচ্ছিন্ন করে দিবে। তোমাদেরকে এ নির্দেশ দিয়েছেন, যাতে তোমরা সংযত হও।'),
  ('bn.bengali', 6, 154, 'অতঃপর আমি মূসাকে গ্রন্থ দিয়েছি, সৎকর্মীদের প্রতি নেয়ামতপূর্ণ করার জন্যে, প্রত্যেক বস্তুর বিশদ বিবরণের জন্যে, হোদায়াতের জন্যে এবং করুণার জন্যে-যাতে তারা স্বীয় পালনকর্তার সাথে সাক্ষাতে বিশ্বাসী হয়।'),
  ('bn.bengali', 6, 155, 'এটি এমন একটি গ্রন্থ, যা আমি অবতীর্ণ করেছি, খুব মঙ্গলময়, অতএব, এর অনুসরণ কর এবং ভয় কর-যাতে তোমরা করুণাপ্রাপ্ত হও।'),
  ('bn.bengali', 6, 156, 'এ জন্যে যে, কখনও তোমরা বলতে শুরু করঃ গ্রন্থ তো কেবল আমাদের পূর্ববর্তী দু\'সম্প্রদায়ের প্রতিই অবতীর্ণ হয়েছে এবং আমরা সেগুলোর পাঠ ও পঠন সম্পর্কে কিছুই জানতাম না।'),
  ('bn.bengali', 6, 157, 'কিংবা বলতে শুরু করঃ যদি আমাদের প্রতি কোন গ্রন্থ অবতীর্ণ হত, আমরা এদের চাইতে অধিক পথপ্রাপ্ত হতাম। অতএব, তোমাদের পালনকর্তার পক্ষ থেকে তোমাদের কাছে সুষ্পষ্ট প্রমাণ, হেদায়েত ও রহমত এসে গেছে। অতঃপর সে ব্যক্তির চাইতে অধিক অনাচারী কে হবে, যে আল্লাহর আয়াত সমূহকে মিথ্যা বলে এবং গা বাঁচিয়ে চলে। অতি সত্ত্বর আমি তাদেরকে শাস্তি দেব। যারা আমার আয়াত সমূহ থেকে গা বাঁচিয়ে চলে-জঘন্য শাস্তি তাদের গা বাঁচানোর কারণে।'),
  ('bn.bengali', 6, 158, 'তারা শুধু এ বিষয়ের দিকে চেয়ে আছে যে, তাদের কাছে ফেরেশতা আগমন করবে কিংবা আপনার পালনকর্তা আগমন করবেন অথবা আপনার পালনকর্তার কোন নির্দেশ আসবে। যেদিন আপনার পালনকর্তার কোন নিদর্শন আসবে, সেদিন এমন কোন ব্যক্তির বিশ্বাস স্থাপন তার জন্যে ফলপ্রসূ হবে না, যে পূর্ব থেকে বিশ্বাস স্থাপন করেনি কিংবা স্বীয় বিশ্বাস অনুযায়ী কোনরূপ সৎকর্ম করেনি। আপনি বলে দিনঃ তোমরা পথের দিকে চেয়ে থাক, আমরাও পথে দিকে তাকিয়ে রইলাম।'),
  ('bn.bengali', 6, 159, 'নিশ্চয় যারা স্বীয় ধর্মকে খন্ড-বিখন্ড করেছে এবং অনেক দল হয়ে গেছে, তাদের সাথে আপনার কোন সম্পর্ক নেই। তাদের ব্যাপার আল্লাহ তা\'আয়ালার নিকট সমর্পিত। অতঃপর তিনি বলে দেবেন যা কিছু তারা করে থাকে।'),
  ('bn.bengali', 6, 160, 'যে একটি সৎকর্ম করবে, সে তার দশগুণ পাবে এবং যে, একটি মন্দ কাজ করবে, সে তার সমান শাস্তিই পাবে। বস্তুতঃ তাদের প্রতি জুলুম করা হবে না।'),
  ('bn.bengali', 6, 161, 'আপনি বলে দিনঃ আমার প্রতিপালক আমাকে সরল পথ প্রদর্শন করেছেন একাগ্রচিত্ত ইব্রাহীমের বিশুদ্ধ ধর্ম। সে অংশীবাদীদের অন্তর্ভূক্ত ছিল না।'),
  ('bn.bengali', 6, 162, 'আপনি বলুনঃ আমার নামায, আমার কোরবাণী এবং আমার জীবন ও মরন বিশ্ব-প্রতিপালক আল্লাহরই জন্যে।'),
  ('bn.bengali', 6, 163, 'তাঁর কোন অংশীদার নেই। আমি তাই আদিষ্ট হয়েছি এবং আমি প্রথম আনুগত্যশীল।'),
  ('bn.bengali', 6, 164, 'আপনি বলুনঃ আমি কি আল্লাহ ব্যতীত অন্য প্রতিপালক খোঁজব, অথচ তিনিই সবকিছুর প্রতিপালক? যে ব্যক্তি কোন গোনাহ করে, তা তারই দায়িত্বে থাকে। কেউ অপরের বোঝা বহন করবে না। অতঃপর তোমাদেরকে সবাইকে প্রতিপালকের কাছে প্রত্যাবর্তন করতে হবে। অনন্তর তিনি তোমাদেরকে বলে দিবেন, যেসব বিষয়ে তোমরা বিরোধ করতে।'),
  ('bn.bengali', 6, 165, 'তিনিই তোমাদেরকে পৃথিবীতে প্রতিনিধি করেছেন এবং একে অন্যের উপর মর্যাদা সমুন্নত করেছেন, যাতে তোমাদের কে এ বিষয়ে পরীক্ষা করেন, যা তোমাদেরকে দিয়েছেন। আপনার প্রতিপালক দ্রুত শাস্তি দাতা এবং তিনি অত্যন্ত ক্ষমাশীল, দয়ালু।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 6, 1, 'Praise be to Allah, Who hath created the heavens and the earth, and hath appointed darkness and light. Yet those who disbelieve ascribe rivals unto their Lord.'),
  ('en.pickthall', 6, 2, 'He it is Who hath created you from clay, and hath decreed a term for you. A term is fixed with Him. Yet still ye doubt!'),
  ('en.pickthall', 6, 3, 'He is Allah in the heavens and in the earth. He knoweth both your secret and your utterance, and He knoweth what ye earn.'),
  ('en.pickthall', 6, 4, 'Never came there unto them a revelation of the revelations of Allah but they did turn away from it.'),
  ('en.pickthall', 6, 5, 'And they denied the truth when it came unto them. But there will come unto them the tidings of that which they used to deride.'),
  ('en.pickthall', 6, 6, 'See they not how many a generation We destroyed before them, whom We had established in the earth more firmly than We have established you, and We shed on them abundant showers from the sky, and made the rivers flow beneath them. Yet we destroyed them for their sins, and created after them another generation.'),
  ('en.pickthall', 6, 7, 'Had we sent down unto thee (Muhammad) (actual) writing upon parchment, so that they could feel it with their hands, those who disbelieve would have said: This is naught else than mere magic.'),
  ('en.pickthall', 6, 8, 'They say: Why hath not an angel been sent down unto him? If We sent down an angel, then the matter would be judged; no further time would be allowed them (for reflection).'),
  ('en.pickthall', 6, 9, 'Had we appointed him (Our messenger) an angel, We assuredly had made him (as) a man (that he might speak to men); and (thus) obscured for them (the truth) they (now) obscure.'),
  ('en.pickthall', 6, 10, 'Messengers (of Allah) have been derided before thee, but that whereat they scoffed surrounded such of them as did deride.'),
  ('en.pickthall', 6, 11, 'Say (unto the disbelievers): Travel in the land, and see the nature of the consequence for the rejecters!'),
  ('en.pickthall', 6, 12, 'Say: Unto whom belongeth whatsoever is in the heavens and the earth? Say: Unto Allah. He hath prescribed for Himself mercy, that He may bring you all together to the Day of Resurrection whereof there is no doubt. Those who ruin their souls will not believe.'),
  ('en.pickthall', 6, 13, 'Unto Him belongeth whatsoever resteth in the night and the day. He is the Hearer, the Knower.'),
  ('en.pickthall', 6, 14, 'Say: Shall I choose for a protecting friend other than Allah, the Originator of the heavens and the earth, Who feedeth and is never fed? Say: I am ordered to be the first to surrender (unto Him). And be not thou (O Muhammad) of the idolaters.'),
  ('en.pickthall', 6, 15, 'Say: I fear, if I rebel against my Lord, the retribution of an Awful Day.'),
  ('en.pickthall', 6, 16, 'He from whom (such retribution) is averted on that day, (Allah) hath in truth had mercy on him. That will be the signal triumph.'),
  ('en.pickthall', 6, 17, 'If Allah touch thee with affliction, there is none that can relieve therefrom save Him, and if He touch thee with good fortune (there is none that can impair it); for He is Able to do all things.'),
  ('en.pickthall', 6, 18, 'He is the Omnipotent over His slaves, and He is the Wise, the Knower.'),
  ('en.pickthall', 6, 19, 'Say (O Muhammad): What thing is of most weight in testimony? Say: Allah is Witness between me and you. And this Qur\'an hath been inspired in me, that I may warn therewith you and whomsoever it may reach. Do ye in sooth bear witness that there are gods beside Allah? Say: I bear no such witness. Say: He is only One Allah. Lo! I am innocent of that which ye associate (with Him).'),
  ('en.pickthall', 6, 20, 'Those unto whom We gave the Scripture recognise (this revelation) as they recognise their sons. Those who ruin their own souls will not believe.'),
  ('en.pickthall', 6, 21, 'Who doth greater wrong than he who inventeth a lie against Allah or denieth His revelations? Lo! the wrongdoers will not be successful.'),
  ('en.pickthall', 6, 22, 'And on the day We gather them together We shall say unto those who ascribed partners (unto Allah): Where are (now) those partners of your make-believe?'),
  ('en.pickthall', 6, 23, 'Then will they have no contention save that they will say: By Allah, our Lord, we never were idolaters.'),
  ('en.pickthall', 6, 24, 'See how they lie against themselves, and (how) the thing which they devised hath failed them!'),
  ('en.pickthall', 6, 25, 'Of them are some who listen unto thee, but We have placed upon their hearts veils, lest they should understand, and in their ears a deafness. If they saw every token they would not believe therein; to the point that, when they come unto thee to argue with thee, the disbelievers say: This is naught else than fables of the men of old.'),
  ('en.pickthall', 6, 26, 'And they forbid (men) from it and avoid it, and they ruin none save themselves, though they perceive not.'),
  ('en.pickthall', 6, 27, 'If thou couldst see when they are set before the Fire and say: Oh, would that we might return! Then would we not deny the revelations of our Lord but we would be of the believers!'),
  ('en.pickthall', 6, 28, 'Nay, but that hath become clear unto them which before they used to hide. And if they were sent back they would return unto that which they are forbidden. Lo! they are liars.'),
  ('en.pickthall', 6, 29, 'And they say: There is naught save our life of the world, and we shall not be raised (again).'),
  ('en.pickthall', 6, 30, 'If thou couldst see when they are set before their Lord! He will say: Is not this real? They will say: Yea, verily, by our Lord! He will say: Taste now the retribution for that ye used to disbelieve.'),
  ('en.pickthall', 6, 31, 'They indeed are losers who deny their meeting with Allah until, when the Hour cometh on them suddenly, they cry: Alas for us, that we neglected it! They bear upon their backs their burdens. Ah, evil is that which they bear!'),
  ('en.pickthall', 6, 32, 'Naught is the life of the world save a pastime and a sport. Better far is the abode of the Hereafter for those who keep their duty (to Allah). Have ye then no sense?'),
  ('en.pickthall', 6, 33, 'We know well how their talk grieveth thee, though in truth they deny not thee (Muhammad) but evil-doers flout the revelations of Allah.'),
  ('en.pickthall', 6, 34, 'Messengers indeed have been denied before thee, and they were patient under the denial and the persecution till Our succour reached them. There is none to alter the decisions of Allah. Already there hath reached thee (somewhat) of the tidings of the messengers (We sent before).'),
  ('en.pickthall', 6, 35, 'And if their aversion is grievous unto thee, then, if thou canst, seek a way down into the earth or a ladder unto the sky that thou mayst bring unto them a portent (to convince them all)! - If Allah willed, He could have brought them all together to the guidance - So be not thou among the foolish ones.'),
  ('en.pickthall', 6, 36, 'Only those can accept who hear. As for the dead, Allah will raise them up; then unto Him they will be returned.'),
  ('en.pickthall', 6, 37, 'They say: Why hath no portent been sent down upon him from his Lord? Say: Lo! Allah is Able to send down a portent. But most of them know not.'),
  ('en.pickthall', 6, 38, 'There is not an animal in the earth, nor a flying creature flying on two wings, but they are peoples like unto you. We have neglected nothing in the Book (of Our decrees). Then unto their Lord they will be gathered.'),
  ('en.pickthall', 6, 39, 'Those who deny Our revelations are deaf and dumb in darkness. Whom Allah will sendeth astray, and whom He will He placeth on a straight path.'),
  ('en.pickthall', 6, 40, 'Say: Can ye see yourselves, if the punishment of Allah come upon you or the Hour come upon you, (calling upon other than Allah)? Do ye then call (for help) to any other than Allah? (Answer that) if ye are truthful.'),
  ('en.pickthall', 6, 41, 'Nay, but unto Him ye call, and He removeth that because of which ye call unto Him, if He will, and ye forget whatever partners ye ascribed unto Him.'),
  ('en.pickthall', 6, 42, 'We have sent already unto peoples that were before thee, and We visited them with tribulation and adversity, in order that they might grow humble.'),
  ('en.pickthall', 6, 43, 'If only, when Our disaster came on them, they had been humble! But their hearts were hardened and the devil made all that they used to do seem fair unto them!'),
  ('en.pickthall', 6, 44, 'Then, when they forgot that whereof they had been reminded, We opened unto them the gates of all things till, even as they were rejoicing in that which they were given, We seized them unawares, and lo! they were dumbfounded.'),
  ('en.pickthall', 6, 45, 'So of the people who did wrong the last remnant was cut off. Praise be to Allah, Lord of the Worlds!'),
  ('en.pickthall', 6, 46, 'Say: Have ye imagined, if Allah should take away your hearing and your sight and seal your hearts, Who is the Allah Who could restore it to you save Allah? See how We display the revelations unto them! Yet still they turn away.'),
  ('en.pickthall', 6, 47, 'Say: Can ye see yourselves, if the punishment of Allah come upon you unawares or openly? Would any perish save wrongdoing folk?'),
  ('en.pickthall', 6, 48, 'We send not the messengers save as bearers of good news and warners. Whoso believeth and doeth right, there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 6, 49, 'But as for those who deny Our revelations, torment will afflict them for that they used to disobey.'),
  ('en.pickthall', 6, 50, 'Say (O Muhammad, to the disbelievers): I say not unto you (that) I possess the treasures of Allah, nor that I have knowledge of the Unseen; and I say not unto you: Lo! I am an angel. I follow only that which is inspired in me. Say: Are the blind man and the seer equal? Will ye not then take thought?'),
  ('en.pickthall', 6, 51, 'Warn hereby those who fear (because they know) that they will be gathered unto their Lord, for whom there is no protecting ally nor intercessor beside Him, that they may ward off (evil).'),
  ('en.pickthall', 6, 52, 'Repel not those who call upon their Lord at morn and evening, seeking His Countenance. Thou art not accountable for them in aught, nor are they accountable for thee in aught, that thou shouldst repel them and be of the wrong-doers.'),
  ('en.pickthall', 6, 53, 'And even so do We try some of them by others, that they say: Are these they whom Allah favoureth among us? Is not Allah best Aware of the thanksgivers?'),
  ('en.pickthall', 6, 54, 'And when those who believe in Our revelations come unto thee, say: Peace be unto you! Your Lord hath prescribed for Himself mercy, that whoso of you doeth evil through ignorance and repenteth afterward thereof and doeth right, (for him) lo! He is Forgiving, Merciful.'),
  ('en.pickthall', 6, 55, 'Thus do We expound the revelations that the way of the unrighteous may be manifest.'),
  ('en.pickthall', 6, 56, 'Say: I am forbidden to worship those on whom ye call instead of Allah. Say: I will not follow your desires, for then should I go astray and I should not be of the rightly guided.'),
  ('en.pickthall', 6, 57, 'Say: I am (relying) on clear proof from my Lord, while ye deny Him. I have not that for which ye are impatient. The decision is for Allah only. He telleth the truth and He is the Best of Deciders.'),
  ('en.pickthall', 6, 58, 'Say: If I had that for which ye are impatient, then would the case (ere this) have been decided between me and you. Allah is Best Aware of the wrong-doers.'),
  ('en.pickthall', 6, 59, 'And with Him are the keys of the Invisible. None but He knoweth them. And He knoweth what is in the land and the sea. Not a leaf falleth but He knoweth it, not a grain amid the darkness of the earth, naught of wet or dry but (it is noted) in a clear record.'),
  ('en.pickthall', 6, 60, 'He it is Who gathereth you at night and knoweth that which ye commit by day. Then He raiseth you again to life therein, that the term appointed (for you) may be accomplished. And afterward unto Him is your return. Then He will proclaim unto you what ye used to do.'),
  ('en.pickthall', 6, 61, 'He is the Omnipotent over His slaves. He sendeth guardians over you until, when death cometh unto one of you, Our messengers receive him, and they neglect not.'),
  ('en.pickthall', 6, 62, 'Then are they restored unto Allah, their Lord, the Just. Surely His is the judgment. And He is the most swift of reckoners.'),
  ('en.pickthall', 6, 63, 'Say: Who delivereth you from the darkness of the land and the sea? Ye call upon Him humbly and in secret, (saying): If we are delivered from this (fear) we truly will be of the thankful.'),
  ('en.pickthall', 6, 64, 'Say: Allah delivereth you from this and from all affliction. Yet ye attribute partners unto Him.'),
  ('en.pickthall', 6, 65, 'Say: He is able to send punishment upon you from above you or from beneath your feet, or to bewilder you with dissension and make you taste the tyranny one of another. See how We display the revelations so that they may understand.'),
  ('en.pickthall', 6, 66, 'Thy people (O Muhammad) have denied it, though it is the Truth. Say: I am not put in charge of you.'),
  ('en.pickthall', 6, 67, 'For every announcement there is a term, and ye will come to know.'),
  ('en.pickthall', 6, 68, 'And when thou seest those who meddle with Our revelations, withdraw from them until they meddle with another topic. And if the devil cause thee to forget, sit not, after the remembrance, with the congregation of wrong-doers.'),
  ('en.pickthall', 6, 69, 'Those who ward off (evil) are not accountable for them in aught, but the Reminder (must be given them) that haply they (too) may ward off (evil).'),
  ('en.pickthall', 6, 70, 'And forsake those who take their religion for a pastime and a jest, and whom the life of the world beguileth. Remind (mankind) hereby lest a soul be destroyed by what it earneth. It hath beside Allah no protecting ally nor intercessor, and though it offer every compensation it will not be accepted from it. Those are they who perish by their own deserts. For them is drink of boiling water and a painful doom, because they disbelieved.'),
  ('en.pickthall', 6, 71, 'Say: Shall we cry, instead of unto Allah, unto that which neither profiteth us nor hurteth us, and shall we turn back after Allah hath guided us, like one bewildered whom the devils have infatuated in the earth, who hath companions who invite him to the guidance (saying): Come unto us? Say: Lo! the guidance of Allah is Guidance, and we are ordered to surrender to the Lord of the Worlds,'),
  ('en.pickthall', 6, 72, 'And to establish worship and be dutiful to Him, and He it is unto Whom ye will be gathered.'),
  ('en.pickthall', 6, 73, 'He it is Who created the heavens and the earth in truth. In the day when He saith: Be! it is. His Word is the Truth, and His will be the Sovereignty on the day when the trumpet is blown. Knower of the Invisible and the Visible, He is the Wise, the Aware.'),
  ('en.pickthall', 6, 74, '(Remember) when Abraham said unto his father Azar: Takest thou idols for gods? Lo! I see thee and thy folk in error manifest.'),
  ('en.pickthall', 6, 75, 'Thus did We show Abraham the kingdom of the heavens and the earth that he might be of those possessing certainty:'),
  ('en.pickthall', 6, 76, 'When the night grew dark upon him he beheld a star. He said: This is my Lord. But when it set, he said: I love not things that set.'),
  ('en.pickthall', 6, 77, 'And when he saw the moon uprising, he exclaimed: This is my Lord. But when it set, he said: Unless my Lord guide me, I surely shall become one of the folk who are astray.'),
  ('en.pickthall', 6, 78, 'And when he saw the sun uprising, he cried: This is my Lord! This is greater! And when it set he exclaimed: O my people! Lo! I am free from all that ye associate (with Him).'),
  ('en.pickthall', 6, 79, 'Lo! I have turned my face toward Him Who created the heavens and the earth, as one by nature upright, and I am not of the idolaters.'),
  ('en.pickthall', 6, 80, 'His people argued with him. He said: Dispute ye with me concerning Allah when He hath guided me? I fear not at all that which ye set up beside Him unless my Lord willeth aught. My Lord includeth all things in His knowledge. Will ye not then remember?'),
  ('en.pickthall', 6, 81, 'How should I fear that which ye set up beside Him, when ye fear not to set up beside Allah that for which He hath revealed unto you no warrant? Which of the two factions hath more right to safety? (Answer me that) if ye have knowledge.'),
  ('en.pickthall', 6, 82, 'Those who believe and obscure not their belief by wrongdoing, theirs is safety; and they are rightly guided.'),
  ('en.pickthall', 6, 83, 'That is Our argument. We gave it unto Abraham against his folk. We raise unto degrees of wisdom whom We will. Lo! thy Lord is Wise, Aware.'),
  ('en.pickthall', 6, 84, 'And We bestowed upon him Isaac and Jacob; each of them We guided; and Noah did We guide aforetime; and of his seed (We guided) David and Solomon and Job and Joseph and Moses and Aaron. Thus do We reward the good.'),
  ('en.pickthall', 6, 85, 'And Zachariah and John and Jesus and Elias. Each one (of them) was of the righteous.'),
  ('en.pickthall', 6, 86, 'And Ishmael and Elisha and Jonah and Lot. Each one (of them) did We prefer above (Our) creatures,'),
  ('en.pickthall', 6, 87, 'With some of their forefathers and their offspring and their brethren; and We chose them and guided them unto a straight path.'),
  ('en.pickthall', 6, 88, 'Such is the guidance of Allah wherewith He guideth whom He will of His bondmen. But if they had set up (for worship) aught beside Him, (all) that they did would have been vain.'),
  ('en.pickthall', 6, 89, 'Those are they unto whom We gave the Scripture and command and prophethood. But if these disbelieve therein, then indeed We shall entrust it to a people who will not be disbelievers therein.'),
  ('en.pickthall', 6, 90, 'Those are they whom Allah guideth, so follow their guidance. Say (O Muhammad, unto mankind): I ask of you no fee for it. Lo! it is naught but a Reminder to (His) creatures.'),
  ('en.pickthall', 6, 91, 'And they measure not the power of Allah its true measure when they say: Allah hath naught revealed unto a human being. Say (unto the Jews who speak thus): Who revealed the Book which Moses brought, a light and guidance for mankind, which ye have put on parchments which ye show, but ye hide much (thereof), and (by which) ye were taught that which ye knew not yourselves nor (did) your fathers (know it)? Say: Allah. Then leave them to their play of cavilling.'),
  ('en.pickthall', 6, 92, 'And this is a blessed Scripture which We have revealed, confirming that which (was revealed) before it, that thou mayst warn the Mother of Villages and those around her. Those who believe in the Hereafter believe herein, and they are careful of their worship.'),
  ('en.pickthall', 6, 93, 'Who is guilty of more wrong than he who forgeth a lie against Allah, or saith: I am inspired, when he is not inspired in aught; and who saith: I will reveal the like of that which Allah hath revealed? If thou couldst see, when the wrong-doers reach the pangs of death and the angels stretch their hands out (saying): Deliver up your souls. This day ye are awarded doom of degradation for that ye spake concerning Allah other than the truth, and used to scorn His portents.'),
  ('en.pickthall', 6, 94, 'Now have ye come unto Us solitary as We did create you at the first, and ye have left behind you all that We bestowed upon you, and We behold not with you those your intercessors, of whom ye claimed that they possessed a share in you. Now is the bond between you severed, and that which ye presumed hath failed you.'),
  ('en.pickthall', 6, 95, 'Lo! Allah (it is) Who splitteth the grain of corn and the date-stone (for sprouting). He bringeth forth the living from the dead, and is the bringer-forth of the dead from the living. Such is Allah. How then are ye perverted?'),
  ('en.pickthall', 6, 96, 'He is the Cleaver of the Daybreak, and He hath appointed the night for stillness, and the sun and the moon for reckoning. That is the measuring of the Mighty, the Wise.'),
  ('en.pickthall', 6, 97, 'And He it is Who hath set for you the stars that ye may guide your course by them amid the darkness of the land and the sea. We have detailed Our revelations for a people who have knowledge.'),
  ('en.pickthall', 6, 98, 'And He it is Who hath produced you from a single being, and (hath given you) a habitation and a repository. We have detailed Our revelations for a people who have understanding.'),
  ('en.pickthall', 6, 99, 'He it is Who sendeth down water from the sky, and therewith We bring forth buds of every kind; We bring forth the green blade from which We bring forth the thick-clustered grain; and from the date-palm, from the pollen thereof, spring pendant bunches; and (We bring forth) gardens of grapes, and the olive and the pomegranate, alike and unlike. Look upon the fruit thereof, when they bear fruit, and upon its ripening. Lo! herein verily are portents for a people who believe.'),
  ('en.pickthall', 6, 100, 'Yet they ascribe as partners unto Him the jinn, although He did create them, and impute falsely, without knowledge, sons and daughters unto Him. Glorified be He and High Exalted above (all) that they ascribe (unto Him).'),
  ('en.pickthall', 6, 101, 'The Originator of the heavens and the earth! How can He have a child, when there is for Him no consort, when He created all things and is Aware of all things?'),
  ('en.pickthall', 6, 102, 'Such is Allah, your Lord. There is no Allah save Him, the Creator of all things, so worship Him. And He taketh care of all things.'),
  ('en.pickthall', 6, 103, 'Vision comprehendeth Him not, but He comprehendeth (all) vision. He is the Subtile, the Aware.'),
  ('en.pickthall', 6, 104, 'Proofs have come unto you from your Lord, so whoso seeth, it is for his own good, and whoso is blind is blind to his own hurt. And I am not a keeper over you.'),
  ('en.pickthall', 6, 105, 'Thus do We display Our revelations that they may say (unto thee, Muhammad): "Thou hast studied," and that We may make (it) clear for people who have knowledge.'),
  ('en.pickthall', 6, 106, 'Follow that which is inspired in thee from thy Lord; there is no Allah save Him; and turn away from the idolaters.'),
  ('en.pickthall', 6, 107, 'Had Allah willed, they had not been idolatrous. We have not set thee as a keeper over them, nor art thou responsible for them.'),
  ('en.pickthall', 6, 108, 'Revile not those unto whom they pray beside Allah lest they wrongfully revile Allah through ignorance. Thus unto every nation have We made their deed seem fair. Then unto their Lord is their return, and He will tell them what they used to do.'),
  ('en.pickthall', 6, 109, 'And they swear a solemn oath by Allah that if there come unto them a portent they will believe therein. Say; Portents are with Allah and (so is) that which telleth you that if such came unto them they would not believe.'),
  ('en.pickthall', 6, 110, 'We confound their hearts and their eyes. As they believed not therein at the first, We let them wander blindly on in their contumacy.'),
  ('en.pickthall', 6, 111, 'And though We should send down the angels unto them, and the dead should speak unto them, and We should gather against them all things in array, they would not believe unless Allah so willed. Howbeit, most of them are ignorant.'),
  ('en.pickthall', 6, 112, 'Thus have We appointed unto every prophet an adversary - devils of humankind and jinn who inspire in one another plausible discourse through guile. If thy Lord willed, they would not do so; so leave them alone with their devising;'),
  ('en.pickthall', 6, 113, 'That the hearts of those who believe not in the Hereafter may incline thereto, and that they may take pleasure therein, and that they may earn what they are earning.'),
  ('en.pickthall', 6, 114, 'Shall I seek other than Allah for judge, when He it is Who hath revealed unto you (this) Scripture, fully explained? Those unto whom We gave the Scripture (aforetime) know that it is revealed from thy Lord in truth. So be not thou (O Muhammad) of the waverers.'),
  ('en.pickthall', 6, 115, 'Perfected is the Word of thy Lord in truth and justice. There is naught that can change His words. He is the Hearer, the Knower.'),
  ('en.pickthall', 6, 116, 'If thou obeyedst most of those on earth they would mislead thee far from Allah\'s way. They follow naught but an opinion, and they do but guess.'),
  ('en.pickthall', 6, 117, 'Lo! thy Lord, He knoweth best who erreth from His way; and He knoweth best (who are) the rightly guided.'),
  ('en.pickthall', 6, 118, 'Eat of that over which the name of Allah hath been mentioned, if ye are believers in His revelations.'),
  ('en.pickthall', 6, 119, 'How should ye not eat of that over which the name of Allah hath been mentioned, when He hath explained unto you that which is forbidden unto you unless ye are compelled thereto. But lo! many are led astray by their own lusts through ignorance. Lo! thy Lord, He is Best Aware of the transgressors.'),
  ('en.pickthall', 6, 120, 'Forsake the outwardness of sin and the inwardness thereof. Lo! those who garner sin will be awarded that which they have earned.'),
  ('en.pickthall', 6, 121, 'And eat not of that whereon Allah\'s name hath not been mentioned, for lo! it is abomination. Lo! the devils do inspire their minions to dispute with you. But if ye obey them, ye will be in truth idolaters.'),
  ('en.pickthall', 6, 122, 'Is he who was dead and We have raised him unto life, and set for him a light wherein he walketh among men, as him whose similitude is in utter darkness whence he cannot emerge? Thus is their conduct made fairseeming for the disbelievers.'),
  ('en.pickthall', 6, 123, 'And thus have We made in every city great ones of its wicked ones, that they should plot therein. They do but plot against themselves, though they perceive not.'),
  ('en.pickthall', 6, 124, 'And when a token cometh unto them, they say: We will not believe till we are given that which Allah\'s messengers are given. Allah knoweth best with whom to place His message. Humiliation from Allah and heavy punishment will smite the guilty for their scheming.'),
  ('en.pickthall', 6, 125, 'And whomsoever it is Allah\'s will to guide, He expandeth his bosom unto the Surrender, and whomsoever it is His Will to send astray, He maketh his bosom close and narrow as if he were engaged in sheer ascent. Thus Allah layeth ignominy upon those who believe not.'),
  ('en.pickthall', 6, 126, 'This is the path of thy Lord, a straight path. We have detailed Our revelations for a people who take heed.'),
  ('en.pickthall', 6, 127, 'For them is the abode of peace with their Lord. He will be their Protecting Friend because of what they used to do.'),
  ('en.pickthall', 6, 128, 'In the day when He will gather them together (He will say): O ye assembly of the jinn! Many of humankind did ye seduce. And their adherents among humankind will say: Our Lord! We enjoyed one another, but now we have arrived at the appointed term which Thou appointedst for us. He will say: Fire is your home. Abide therein for ever, save him whom Allah willeth (to deliver). Lo! thy Lord is Wise, Aware.'),
  ('en.pickthall', 6, 129, 'Thus We let some of the wrong-doers have power over others because of what they are wont to earn.'),
  ('en.pickthall', 6, 130, 'O ye assembly of the jinn and humankind! Came there not unto you messengers of your own who recounted unto you My tokens and warned you of the meeting of this your Day? They will say: We testify against ourselves. And the life of the world beguiled them. And they testify against themselves that they were disbelievers.'),
  ('en.pickthall', 6, 131, 'This is because thy Lord destroyeth not the townships arbitrarily while their people are unconscious (of the wrong they do).'),
  ('en.pickthall', 6, 132, 'For all there will be ranks from what they did. Thy Lord is not unaware of what they do.'),
  ('en.pickthall', 6, 133, 'Thy Lord is the Absolute, the Lord of Mercy. If He will, He can remove you and can cause what He will to follow after you, even as He raised you from the seed of other folk.'),
  ('en.pickthall', 6, 134, 'Lo! that which ye are promised will surely come to pass, and ye cannot escape.'),
  ('en.pickthall', 6, 135, 'Say (O Muhammad): O my people! Work according to your power. Lo! I too am working. Thus ye will come to know for which of us will be the happy sequel. Lo! the wrong-doers will not be successful.'),
  ('en.pickthall', 6, 136, 'They assign unto Allah, of the crops and cattle which He created, a portion, and they say: "This is Allah\'s" - in their make-believe - "and this is for (His) partners in regard to us." Thus that which (they assign) unto His partners in them reacheth not Allah and that which (they assign) unto Allah goeth to their (so-called) partners. Evil is their ordinance.'),
  ('en.pickthall', 6, 137, 'Thus have their (so-called) partners (of Allah) made the killing of their children to seem fair unto many of the idolaters, that they may ruin them and make their faith obscure for them. Had Allah willed (it otherwise), they had not done so. So leave them alone with their devices.'),
  ('en.pickthall', 6, 138, 'And they say: Such cattle and crops are forbidden. No-one is to eat of them save whom we will - in their make-believe - cattle whose backs are forbidden, cattle over which they mention not the name of Allah. (All that is) a lie against Him. He will repay them for that which they invent.'),
  ('en.pickthall', 6, 139, 'And they say: That which is in the bellies of such cattle is reserved for our males and is forbidden to our wives; but if it be born dead, then they (all) may be partakers thereof. He will reward them for their attribution (of such ordinances unto Him). Lo, He is Wise, Aware.'),
  ('en.pickthall', 6, 140, 'They are losers who besottedly have slain their children without knowledge, and have forbidden that which Allah bestowed upon them, inventing a lie against Allah. They indeed have gone astray and are not guided.'),
  ('en.pickthall', 6, 141, 'He it is Who produceth gardens trellised and untrellised, and the date-palm, and crops of divers flavour, and the olive and the pomegranate, like and unlike. Eat ye of the fruit thereof when it fruiteth, and pay the due thereof upon the harvest day, and be not prodigal. Lo! Allah loveth not the prodigals.'),
  ('en.pickthall', 6, 142, 'And of the cattle (He produceth) some for burdens, some for food. Eat of that which Allah hath bestowed upon you, and follow not the footsteps of the devil, for lo! he is an open foe to you.'),
  ('en.pickthall', 6, 143, 'Eight pairs: Of the sheep twain, and of the goats twain. Say: Hath He forbidden the two males or the two females, or that which the wombs of the two females contain? Expound to me (the case) with knowledge, if ye are truthful.'),
  ('en.pickthall', 6, 144, 'And of the camels twain and of the oxen twain. Say: Hath He forbidden the two males or the two females, or that which the wombs of the two females contain; or were ye by to witness when Allah commanded you (all) this? Then who doth greater wrong than he who deviseth a lie concerning Allah, that he may lead mankind astray without knowledge. Lo! Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 6, 145, 'Say: I find not in that which is revealed unto me aught prohibited to an eater that he eat thereof, except it be carrion, or blood poured forth, or swineflesh - for that verily is foul - or the abomination which was immolated to the name of other than Allah. But whoso is compelled (thereto), neither craving nor transgressing, (for him) lo! thy Lord is Forgiving, Merciful.'),
  ('en.pickthall', 6, 146, 'Unto those who are Jews We forbade every animal with claws. And of the oxen and the sheep forbade We unto them the fat thereof save that upon the backs or the entrails, or that which is mixed with the bone. That we awarded them for their rebellion. And lo! we verily are truthful.'),
  ('en.pickthall', 6, 147, 'So if they give the lie to thee (Muhammad), say: Your Lord is a Lord of All-Embracing Mercy, and His wrath will never be withdrawn from guilty folk.'),
  ('en.pickthall', 6, 148, 'They who are idolaters will say: Had Allah willed, we had not ascribed (unto Him) partners neither had our fathers, nor had we forbidden aught. Thus did those who were before them give the lie (to Allah\'s messengers) till they tasted of the fear of Us. Say: Have ye any knowledge that ye can adduce for Us? Lo! ye follow naught but an opinion, Lo! ye do but guess.'),
  ('en.pickthall', 6, 149, 'Say - For Allah\'s is the final argument - Had He willed He could indeed have guided all of you.'),
  ('en.pickthall', 6, 150, 'Say: Come, bring your witnesses who can bear witness that Allah forbade (all) this. And if they bear witness, do not thou bear witness with them. Follow thou not the whims of those who deny Our revelations, those who believe not in the Hereafter and deem (others) equal with their Lord.'),
  ('en.pickthall', 6, 151, 'Say: Come, I will recite unto you that which your Lord hath made a sacred duty for you: That ye ascribe no thing as partner unto Him and that ye do good to parents, and that ye slay not your children because of penury - We provide for you and for them - and that ye draw not nigh to lewd things whether open or concealed. And that ye slay not the life which Allah hath made sacred, save in the course of justice. This He hath command you, in order that ye may discern.'),
  ('en.pickthall', 6, 152, 'And approach not the wealth of the orphan save with that which is better, till he reach maturity. Give full measure and full weight, in justice. We task not any soul beyond its scope. And if ye give your word, do justice thereunto, even though it be (against) a kinsman; and fulfil the covenant of Allah. This He commandeth you that haply ye may remember.'),
  ('en.pickthall', 6, 153, 'And (He commandeth you, saying): This is My straight path, so follow it. Follow not other ways, lest ye be parted from His way. This hath He ordained for you, that ye may ward off (evil).'),
  ('en.pickthall', 6, 154, 'Again, We gave the Scripture unto Moses, complete for him who would do good, an explanation of all things, a guidance and a mercy, that they might believe in the meeting with their Lord.'),
  ('en.pickthall', 6, 155, 'And this is a blessed Scripture which We have revealed. So follow it and ward off (evil), that ye may find mercy.'),
  ('en.pickthall', 6, 156, 'Lest ye should say: The Scripture was revealed only to two sects before us, and we in sooth were unaware of what they read;'),
  ('en.pickthall', 6, 157, 'Or lest ye should say: If the Scripture had been revealed unto us, we surely had been better guided than are they. Now hath there come unto you a clear proof from your Lord, a guidance and mercy; and who doeth greater wrong than he who denieth the revelations of Allah, and turneth away from them? We award unto those who turn away from Our revelations an evil doom because of their aversion.'),
  ('en.pickthall', 6, 158, 'Wait they, indeed, for nothing less than that the angels should come unto them, or thy Lord should come, or there should come one of the portents from thy Lord? In the day when one of the portents from thy Lord cometh, its belief availeth naught a soul which theretofore believed not, nor in its belief earned good (by works). Say: Wait ye! Lo! We (too) are waiting.'),
  ('en.pickthall', 6, 159, 'Lo! As for those who sunder their religion and become schismatics, no concern at all hast thou with them. Their case will go to Allah, Who then will tell them what they used to do.'),
  ('en.pickthall', 6, 160, 'Whoso bringeth a good deed will receive tenfold the like thereof, while whoso bringeth an ill-deed will be awarded but the like thereof; and they will not be wronged.'),
  ('en.pickthall', 6, 161, 'Say: Lo! As for me, my Lord hath guided me unto a straight path, a right religion, the community of Abraham, the upright, who was no idolater.'),
  ('en.pickthall', 6, 162, 'Say: Lo! my worship and my sacrifice and my living and my dying are for Allah, Lord of the Worlds.'),
  ('en.pickthall', 6, 163, 'He hath no partner. This am I commanded, and I am first of those who surrender (unto Him).'),
  ('en.pickthall', 6, 164, 'Say: Shall I seek another than Allah for Lord, when He is Lord of all things? Each soul earneth only on its own account, nor doth any laden bear another\'s load. Then unto your Lord is your return and He will tell you that wherein ye differed.'),
  ('en.pickthall', 6, 165, 'He it is Who hath placed you as viceroys of the earth and hath exalted some of you in rank above others, that He may try you by (the test of) that which He hath given you. Lo! Thy Lord is swift in prosecution, and Lo! He verily is Forgiving, Merciful.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 6, 1, 'Praise be Allah, Who created the heavens and the earth, and made the darkness and the light. Yet those who reject Faith hold (others) as equal, with their Guardian-Lord.'),
  ('en.yusufali', 6, 2, 'He it is created you from clay, and then decreed a stated term (for you). And there is in His presence another determined term; yet ye doubt within yourselves!'),
  ('en.yusufali', 6, 3, 'And He is Allah in the heavens and on earth. He knoweth what ye hide, and what ye reveal, and He knoweth the (recompense) which ye earn (by your deeds).'),
  ('en.yusufali', 6, 4, 'But never did a single one of the signs of their Lord reach them, but they turned away therefrom.'),
  ('en.yusufali', 6, 5, 'And now they reject the truth when it reaches them: but soon shall they learn the reality of what they used to mock at.'),
  ('en.yusufali', 6, 6, 'See they not how many of those before them We did destroy?- generations We had established on the earth, in strength such as We have not given to you - for whom We poured out rain from the skies in abundance, and gave (fertile) streams flowing beneath their (feet): yet for their sins We destroyed them, and raised in their wake fresh generations (to succeed them).'),
  ('en.yusufali', 6, 7, 'If We had sent unto thee a written (message) on parchment, so that they could touch it with their hands, the Unbelievers would have been sure to say: "This is nothing but obvious magic!"'),
  ('en.yusufali', 6, 8, 'They say: "Why is not an angel sent down to him?" If we did send down an angel, the matter would be settled at once, and no respite would be granted them.'),
  ('en.yusufali', 6, 9, 'If We had made it an angel, We should have sent him as a man, and We should certainly have caused them confusion in a matter which they have already covered with confusion.'),
  ('en.yusufali', 6, 10, 'Mocked were (many) messengers before thee; but their scoffers were hemmed in by the thing that they mocked.'),
  ('en.yusufali', 6, 11, 'Say: "Travel through the earth and see what was the end of those who rejected Truth."'),
  ('en.yusufali', 6, 12, 'Say: "To whom belongeth all that is in the heavens and on earth?" Say: "To Allah. He hath inscribed for Himself (the rule of) Mercy. That He will gather you together for the Day of Judgment, there is no doubt whatever. It is they who have lost their own souls, that will not believe.'),
  ('en.yusufali', 6, 13, 'To him belongeth all that dwelleth (or lurketh) in the night and the day. For he is the one who heareth and knoweth all things."'),
  ('en.yusufali', 6, 14, 'Say: "Shall I take for my protector any other than Allah, the Maker of the heavens and the earth? And He it is that feedeth but is not fed." Say: "Nay! but I am commanded to be the first of those who bow to Allah (in Islam), and be not thou of the company of those who join gods with Allah."'),
  ('en.yusufali', 6, 15, 'Say: "I would, if I disobeyed my Lord, indeed have fear of the penalty of a Mighty Day.'),
  ('en.yusufali', 6, 16, '"On that day, if the penalty is averted from any, it is due to Allah\'s mercy; And that would be (Salvation), the obvious fulfilment of all desire.'),
  ('en.yusufali', 6, 17, '"If Allah touch thee with affliction, none can remove it but He; if He touch thee with happiness, He hath power over all things.'),
  ('en.yusufali', 6, 18, '"He is the irresistible, (watching) from above over His worshippers; and He is the Wise, acquainted with all things."'),
  ('en.yusufali', 6, 19, 'Say: "What thing is most weighty in evidence?" Say: "Allah is witness between me and you; This Qur\'an hath been revealed to me by inspiration, that I may warn you and all whom it reaches. Can ye possibly bear witness that besides Allah there is another Allah?" Say: "Nay! I cannot bear witness!" Say: "But in truth He is the one Allah, and I truly am innocent of (your blasphemy of) joining others with Him."'),
  ('en.yusufali', 6, 20, 'Those to whom We have given the Book know this as they know their own sons. Those who have lost their own souls refuse therefore to believe.'),
  ('en.yusufali', 6, 21, 'Who doth more wrong than he who inventeth a lie against Allah or rejecteth His signs? But verily the wrong-doers never shall prosper.'),
  ('en.yusufali', 6, 22, 'One day shall We gather them all together: We shall say to those who ascribed partners (to Us): "Where are the partners whom ye (invented and) talked about?"'),
  ('en.yusufali', 6, 23, 'There will then be (left) no subterfuge for them but to say: "By Allah our Lord, we were not those who joined gods with Allah."'),
  ('en.yusufali', 6, 24, 'Behold! how they lie against their own souls! But the (lie) which they invented will leave them in the lurch.'),
  ('en.yusufali', 6, 25, 'Of them there are some who (pretend to) listen to thee; but We have thrown veils on their hearts, So they understand it not, and deafness in their ears; if they saw every one of the signs, not they will believe in them; in so much that when they come to thee, they (but) dispute with thee; the Unbelievers say: "These are nothing but tales of the ancients."'),
  ('en.yusufali', 6, 26, 'Others they keep away from it, and themselves they keep away; but they only destroy their own souls, and they perceive it not.'),
  ('en.yusufali', 6, 27, 'If thou couldst but see when they are confronted with the Fire! They will say: "Would that we were but sent back! Then would we not reject the signs of our Lord, but would be amongst those who believe!"'),
  ('en.yusufali', 6, 28, 'Yea, in their own (eyes) will become manifest what before they concealed. But if they were returned, they would certainly relapse to the things they were forbidden, for they are indeed liars.'),
  ('en.yusufali', 6, 29, 'And they (sometimes) say: "There is nothing except our life on this earth, and never shall we be raised up again."'),
  ('en.yusufali', 6, 30, 'If thou couldst but see when they are confronted with their Lord! He will say: "Is not this the truth?" They will say: "Yea, by our Lord!" He will say: "Taste ye then the penalty, because ye rejected Faith."'),
  ('en.yusufali', 6, 31, 'Lost indeed are they who treat it as a falsehood that they must meet Allah,- until on a sudden the hour is on them, and they say: "Ah! woe unto us that we took no thought of it"; for they bear their burdens on their backs, and evil indeed are the burdens that they bear?'),
  ('en.yusufali', 6, 32, 'What is the life of this world but play and amusement? But best is the home in the hereafter, for those who are righteous. Will ye not then understand?'),
  ('en.yusufali', 6, 33, 'We know indeed the grief which their words do cause thee: It is not thee they reject: it is the signs of Allah, which the wicked contemn.'),
  ('en.yusufali', 6, 34, 'Rejected were the messengers before thee: with patience and constancy they bore their rejection and their wrongs, until Our aid did reach them: there is none that can alter the words (and decrees) of Allah. Already hast thou received some account of those messengers.'),
  ('en.yusufali', 6, 35, 'If their spurning is hard on thy mind, yet if thou wert able to seek a tunnel in the ground or a ladder to the skies and bring them a sign,- (what good?). If it were Allah\'s will, He could gather them together unto true guidance: so be not thou amongst those who are swayed by ignorance (and impatience)!'),
  ('en.yusufali', 6, 36, 'Those who listen (in truth), be sure, will accept: as to the dead, Allah will raise them up; then will they be turned unto Him.'),
  ('en.yusufali', 6, 37, 'They say: "Why is not a sign sent down to him from his Lord?" Say: "Allah hath certainly power to send down a sign: but most of them understand not.'),
  ('en.yusufali', 6, 38, 'There is not an animal (that lives) on the earth, nor a being that flies on its wings, but (forms part of) communities like you. Nothing have we omitted from the Book, and they (all) shall be gathered to their Lord in the end.'),
  ('en.yusufali', 6, 39, 'Those who reject our signs are deaf and dumb,- in the midst of darkness profound: whom Allah willeth, He leaveth to wander: whom He willeth, He placeth on the way that is straight.'),
  ('en.yusufali', 6, 40, 'Say: "Think ye to yourselves, if there come upon you the wrath of Allah, or the Hour (that ye dread), would ye then call upon other than Allah?- (reply) if ye are truthful!'),
  ('en.yusufali', 6, 41, '"Nay,- On Him would ye call, and if it be His will, He would remove (the distress) which occasioned your call upon Him, and ye would forget (the false gods) which ye join with Him!"'),
  ('en.yusufali', 6, 42, 'Before thee We sent (messengers) to many nations, and We afflicted the nations with suffering and adversity, that they might learn humility.'),
  ('en.yusufali', 6, 43, 'When the suffering reached them from us, why then did they not learn humility? On the contrary their hearts became hardened, and Satan made their (sinful) acts seem alluring to them.'),
  ('en.yusufali', 6, 44, 'But when they forgot the warning they had received, We opened to them the gates of all (good) things, until, in the midst of their enjoyment of Our gifts, on a sudden, We called them to account, when lo! they were plunged in despair!'),
  ('en.yusufali', 6, 45, 'Of the wrong-doers the last remnant was cut off. Praise be to Allah, the Cherisher of the worlds.'),
  ('en.yusufali', 6, 46, 'Say: "Think ye, if Allah took away your hearing and your sight, and sealed up your hearts, who - a god other than Allah - could restore them to you?" See how We explain the signs by various (symbols); yet they turn aside.'),
  ('en.yusufali', 6, 47, 'Say: "Think ye, if the punishment of Allah comes to you, whether suddenly or openly, will any be destroyed except those who do wrong?'),
  ('en.yusufali', 6, 48, 'We send the messengers only to give good news and to warn: so those who believe and mend (their lives),- upon them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 6, 49, 'But those who reject our signs,- them shall punishment touch, for that they ceased not from transgressing.'),
  ('en.yusufali', 6, 50, 'Say: "I tell you not that with me are the treasures of Allah, nor do I know what is hidden, nor do I tell you I am an angel. I but follow what is revealed to me." Say: "can the blind be held equal to the seeing?" Will ye then consider not?'),
  ('en.yusufali', 6, 51, 'Give this warning to those in whose (hearts) is the fear that they will be brought (to judgment) before their Lord: except for Him they will have no protector nor intercessor: that they may guard (against evil).'),
  ('en.yusufali', 6, 52, 'Send not away those who call on their Lord morning and evening, seeking His face. In naught art thou accountable for them, and in naught are they accountable for thee, that thou shouldst turn them away, and thus be (one) of the unjust.'),
  ('en.yusufali', 6, 53, 'Thus did We try some of them by comparison with others, that they should say: "Is it these then that Allah hath favoured from amongst us?" Doth not Allah know best those who are grateful?'),
  ('en.yusufali', 6, 54, 'When those come to thee who believe in Our signs, Say: "Peace be on you: Your Lord hath inscribed for Himself (the rule of) mercy: verily, if any of you did evil in ignorance, and thereafter repented, and amend (his conduct), lo! He is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 6, 55, 'Thus do We explain the signs in detail: that the way of the sinners may be shown up.'),
  ('en.yusufali', 6, 56, 'Say: "I am forbidden to worship those - others than Allah - whom ye call upon." Say: "I will not follow your wain desires: If I did, I would stray from the path, and be not of the company of those who receive guidance."'),
  ('en.yusufali', 6, 57, 'Say: "For me, I (work) on a clear sign from my Lord, but ye reject Him. What ye would see hastened, is not in my power. The command rests with none but Allah: He declares the truth, and He is the best of judges."'),
  ('en.yusufali', 6, 58, 'Say: "If what ye would see hastened were in my power, the matter would be settled at once between you and me. But Allah knoweth best those who do wrong."'),
  ('en.yusufali', 6, 59, 'With Him are the keys of the unseen, the treasures that none knoweth but He. He knoweth whatever there is on the earth and in the sea. Not a leaf doth fall but with His knowledge: there is not a grain in the darkness (or depths) of the earth, nor anything fresh or dry (green or withered), but is (inscribed) in a record clear (to those who can read).'),
  ('en.yusufali', 6, 60, 'It is He who doth take your souls by night, and hath knowledge of all that ye have done by day: by day doth He raise you up again; that a term appointed be fulfilled; In the end unto Him will be your return; then will He show you the truth of all that ye did.'),
  ('en.yusufali', 6, 61, 'He is the irresistible, (watching) from above over His worshippers, and He sets guardians over you. At length, when death approaches one of you, Our angels take his soul, and they never fail in their duty.'),
  ('en.yusufali', 6, 62, 'Then are men returned unto Allah, their protector, the (only) reality: Is not His the command? and He is the swiftest in taking account.'),
  ('en.yusufali', 6, 63, 'Say: "Who is it that delivereth you from the dark recesses of land and sea, when ye call upon Him in humility and silent terror: \'If He only delivers us from these (dangers), (we vow) we shall truly show our gratitude\'?"'),
  ('en.yusufali', 6, 64, 'Say "It is Allah that delivereth you from these and all (other) distresses: and yet ye worship false gods!"'),
  ('en.yusufali', 6, 65, 'Say: "He hath power to send calamities on you, from above and below, or to cover you with confusion in party strife, giving you a taste of mutual vengeance - each from the other." See how We explain the signs by various (symbols); that they may understand.'),
  ('en.yusufali', 6, 66, 'But thy people reject this, though it is the truth. Say: "Not mine is the responsibility for arranging your affairs;'),
  ('en.yusufali', 6, 67, 'For every message is a limit of time, and soon shall ye know it."'),
  ('en.yusufali', 6, 68, 'When thou seest men engaged in vain discourse about Our signs, turn away from them unless they turn to a different theme. If Satan ever makes thee forget, then after recollection, sit not thou in the company of those who do wrong.'),
  ('en.yusufali', 6, 69, 'On their account no responsibility falls on the righteous, but (their duty) is to remind them, that they may (learn to) fear Allah.'),
  ('en.yusufali', 6, 70, 'Leave alone those who take their religion to be mere play and amusement, and are deceived by the life of this world. But proclaim (to them) this (truth): that every soul delivers itself to ruin by its own acts: it will find for itself no protector or intercessor except Allah: if it offered every ransom, (or reparation), none will be accepted: such is (the end of) those who deliver themselves to ruin by their own acts: they will have for drink (only) boiling water, and for punishment, one most grievous: for they persisted in rejecting Allah.'),
  ('en.yusufali', 6, 71, 'Say: "Shall we indeed call on others besides Allah,- things that can do us neither good nor harm,- and turn on our heels after receiving guidance from Allah? - like one whom the evil ones have made into a fool, wandering bewildered through the earth, his friends calling, come to us\', (vainly) guiding him to the path." Say: "Allah\'s guidance is the (only) guidance, and we have been directed to submit ourselves to the Lord of the worlds;-'),
  ('en.yusufali', 6, 72, '"To establish regular prayers and to fear Allah: for it is to Him that we shall be gathered together."'),
  ('en.yusufali', 6, 73, 'It is He who created the heavens and the earth in true (proportions): the day He saith, "Be," behold! it is. His word is the truth. His will be the dominion the day the trumpet will be blown. He knoweth the unseen as well as that which is open. For He is the Wise, well acquainted (with all things).'),
  ('en.yusufali', 6, 74, 'Lo! Abraham said to his father Azar: "Takest thou idols for gods? For I see thee and thy people in manifest error."'),
  ('en.yusufali', 6, 75, 'So also did We show Abraham the power and the laws of the heavens and the earth, that he might (with understanding) have certitude.'),
  ('en.yusufali', 6, 76, 'When the night covered him over, He saw a star: He said: "This is my Lord." But when it set, He said: "I love not those that set."'),
  ('en.yusufali', 6, 77, 'When he saw the moon rising in splendour, he said: "This is my Lord." But when the moon set, He said: "unless my Lord guide me, I shall surely be among those who go astray."'),
  ('en.yusufali', 6, 78, 'When he saw the sun rising in splendour, he said: "This is my Lord; this is the greatest (of all)." But when the sun set, he said: "O my people! I am indeed free from your (guilt) of giving partners to Allah.'),
  ('en.yusufali', 6, 79, '"For me, I have set my face, firmly and truly, towards Him Who created the heavens and the earth, and never shall I give partners to Allah."'),
  ('en.yusufali', 6, 80, 'His people disputed with him. He said: "(Come) ye to dispute with me, about Allah, when He (Himself) hath guided me? I fear not (the beings) ye associate with Allah: Unless my Lord willeth, (nothing can happen). My Lord comprehendeth in His knowledge all things. Will ye not (yourselves) be admonished?'),
  ('en.yusufali', 6, 81, '"How should I fear (the beings) ye associate with Allah, when ye fear not to give partners to Allah without any warrant having been given to you? Which of (us) two parties hath more right to security? (tell me) if ye know.'),
  ('en.yusufali', 6, 82, '"It is those who believe and confuse not their beliefs with wrong - that are (truly) in security, for they are on (right) guidance."'),
  ('en.yusufali', 6, 83, 'That was the reasoning about Us, which We gave to Abraham (to use) against his people: We raise whom We will, degree after degree: for thy Lord is full of wisdom and knowledge.'),
  ('en.yusufali', 6, 84, 'We gave him Isaac and Jacob: all (three) guided: and before him, We guided Noah, and among his progeny, David, Solomon, Job, Joseph, Moses, and Aaron: thus do We reward those who do good:'),
  ('en.yusufali', 6, 85, 'And Zakariya and John, and Jesus and Elias: all in the ranks of the righteous:'),
  ('en.yusufali', 6, 86, 'And Isma\'il and Elisha, and Jonas, and Lot: and to all We gave favour above the nations:'),
  ('en.yusufali', 6, 87, '(To them) and to their fathers, and progeny and brethren: We chose them, and we guided them to a straight way.'),
  ('en.yusufali', 6, 88, 'This is the guidance of Allah: He giveth that guidance to whom He pleaseth, of His worshippers. If they were to join other gods with Him, all that they did would be vain for them.'),
  ('en.yusufali', 6, 89, 'These were the men to whom We gave the Book, and authority, and prophethood: if these (their descendants) reject them, Behold! We shall entrust their charge to a new people who reject them not.'),
  ('en.yusufali', 6, 90, 'Those were the (prophets) who received Allah\'s guidance: Copy the guidance they received; Say: "No reward for this do I ask of you: This is no less than a message for the nations."'),
  ('en.yusufali', 6, 91, 'No just estimate of Allah do they make when they say: "Nothing doth Allah send down to man (by way of revelation)" Say: "Who then sent down the Book which Moses brought?- a light and guidance to man: But ye make it into (separate) sheets for show, while ye conceal much (of its contents): therein were ye taught that which ye knew not- neither ye nor your fathers." Say: "Allah (sent it down)": Then leave them to plunge in vain discourse and trifling.'),
  ('en.yusufali', 6, 92, 'And this is a Book which We have sent down, bringing blessings, and confirming (the revelations) which came before it: that thou mayest warn the mother of cities and all around her. Those who believe in the Hereafter believe in this (Book), and they are constant in guarding their prayers.'),
  ('en.yusufali', 6, 93, 'Who can be more wicked than one who inventeth a lie against Allah, or saith, "I have received inspiration," when he hath received none, or (again) who saith, "I can reveal the like of what Allah hath revealed"? If thou couldst but see how the wicked (do fare) in the flood of confusion at death! - the angels stretch forth their hands, (saying),"Yield up your souls: this day shall ye receive your reward,- a penalty of shame, for that ye used to tell lies against Allah, and scornfully to reject of His signs!"'),
  ('en.yusufali', 6, 94, '"And behold! ye come to us bare and alone as We created you for the first time: ye have left behind you all (the favours) which We bestowed on you: We see not with you your intercessors whom ye thought to be partners in your affairs: so now all relations between you have been cut off, and your (pet) fancies have left you in the lurch!"'),
  ('en.yusufali', 6, 95, 'It is Allah Who causeth the seed-grain and the date-stone to split and sprout. He causeth the living to issue from the dead, and He is the one to cause the dead to issue from the living. That is Allah: then how are ye deluded away from the truth?'),
  ('en.yusufali', 6, 96, 'He it is that cleaveth the day-break (from the dark): He makes the night for rest and tranquillity, and the sun and moon for the reckoning (of time): Such is the judgment and ordering of (Him), the Exalted in Power, the Omniscient.'),
  ('en.yusufali', 6, 97, 'It is He Who maketh the stars (as beacons) for you, that ye may guide yourselves, with their help, through the dark spaces of land and sea: We detail Our signs for people who know.'),
  ('en.yusufali', 6, 98, 'It is He Who hath produced you from a single person: here is a place of sojourn and a place of departure: We detail Our signs for people who understand.'),
  ('en.yusufali', 6, 99, 'It is He Who sendeth down rain from the skies: with it We produce vegetation of all kinds: from some We produce green (crops), out of which We produce grain, heaped up (at harvest); out of the date-palm and its sheaths (or spathes) (come) clusters of dates hanging low and near: and (then there are) gardens of grapes, and olives, and pomegranates, each similar (in kind) yet different (in variety): when they begin to bear fruit, feast your eyes with the fruit and the ripeness thereof. Behold! in these things there are signs for people who believe.'),
  ('en.yusufali', 6, 100, 'Yet they make the Jinns equals with Allah, though Allah did create the Jinns; and they falsely, having no knowledge, attribute to Him sons and daughters. Praise and glory be to Him! (for He is) above what they attribute to Him!'),
  ('en.yusufali', 6, 101, 'To Him is due the primal origin of the heavens and the earth: How can He have a son when He hath no consort? He created all things, and He hath full knowledge of all things.'),
  ('en.yusufali', 6, 102, 'That is Allah, your Lord! there is no god but He, the Creator of all things: then worship ye Him: and He hath power to dispose of all affairs.'),
  ('en.yusufali', 6, 103, 'No vision can grasp Him, but His grasp is over all vision: He is above all comprehension, yet is acquainted with all things.'),
  ('en.yusufali', 6, 104, '"Now have come to you, from your Lord, proofs (to open your eyes): if any will see, it will be for (the good of) his own soul; if any will be blind, it will be to his own (harm): I am not (here) to watch over your doings."'),
  ('en.yusufali', 6, 105, 'Thus do we explain the signs by various (symbols): that they may say, "Thou hast taught (us) diligently," and that We may make the matter clear to those who know.'),
  ('en.yusufali', 6, 106, 'Follow what thou art taught by inspiration from thy Lord: there is no god but He: and turn aside from those who join gods with Allah.'),
  ('en.yusufali', 6, 107, 'If it had been Allah\'s plan, they would not have taken false gods: but We made thee not one to watch over their doings, nor art thou set over them to dispose of their affairs.'),
  ('en.yusufali', 6, 108, 'Revile not ye those whom they call upon besides Allah, lest they out of spite revile Allah in their ignorance. Thus have We made alluring to each people its own doings. In the end will they return to their Lord, and We shall then tell them the truth of all that they did.'),
  ('en.yusufali', 6, 109, 'They swear their strongest oaths by Allah, that if a (special) sign came to them, by it they would believe. Say: "Certainly (all) signs are in the power of Allah: but what will make you (Muslims) realise that (even) if (special) signs came, they will not believe."?'),
  ('en.yusufali', 6, 110, 'We (too) shall turn to (confusion) their hearts and their eyes, even as they refused to believe in this in the first instance: We shall leave them in their trespasses, to wander in distraction.'),
  ('en.yusufali', 6, 111, 'Even if We did send unto them angels, and the dead did speak unto them, and We gathered together all things before their very eyes, they are not the ones to believe, unless it is in Allah\'s plan. But most of them ignore (the truth).'),
  ('en.yusufali', 6, 112, 'Likewise did We make for every Messenger an enemy,- evil ones among men and jinns, inspiring each other with flowery discourses by way of deception. If thy Lord had so planned, they would not have done it: so leave them and their inventions alone.'),
  ('en.yusufali', 6, 113, 'To such (deceit) let the hearts of those incline, who have no faith in the hereafter: let them delight in it, and let them earn from it what they may.'),
  ('en.yusufali', 6, 114, 'Say: "Shall I seek for judge other than Allah? - when He it is Who hath sent unto you the Book, explained in detail." They know full well, to whom We have given the Book, that it hath been sent down from thy Lord in truth. Never be then of those who doubt.'),
  ('en.yusufali', 6, 115, 'The word of thy Lord doth find its fulfilment in truth and in justice: None can change His words: for He is the one who heareth and knoweth all.'),
  ('en.yusufali', 6, 116, 'Wert thou to follow the common run of those on earth, they will lead thee away from the way of Allah. They follow nothing but conjecture: they do nothing but lie.'),
  ('en.yusufali', 6, 117, 'Thy Lord knoweth best who strayeth from His way: He knoweth best who they are that receive His guidance.'),
  ('en.yusufali', 6, 118, 'So eat of (meats) on which Allah\'s name hath been pronounced, if ye have faith in His signs.'),
  ('en.yusufali', 6, 119, 'Why should ye not eat of (meats) on which Allah\'s name hath been pronounced, when He hath explained to you in detail what is forbidden to you - except under compulsion of necessity? But many do mislead (men) by their appetites unchecked by knowledge. Thy Lord knoweth best those who transgress.'),
  ('en.yusufali', 6, 120, 'Eschew all sin, open or secret: those who earn sin will get due recompense for their "earnings."'),
  ('en.yusufali', 6, 121, 'Eat not of (meats) on which Allah\'s name hath not been pronounced: That would be impiety. But the evil ones ever inspire their friends to contend with you if ye were to obey them, ye would indeed be Pagans.'),
  ('en.yusufali', 6, 122, 'Can he who was dead, to whom We gave life, and a light whereby he can walk amongst men, be like him who is in the depths of darkness, from which he can never come out? Thus to those without faith their own deeds seem pleasing.'),
  ('en.yusufali', 6, 123, 'Thus have We placed leaders in every town, its wicked men, to plot (and burrow) therein: but they only plot against their own souls, and they perceive it not.'),
  ('en.yusufali', 6, 124, 'When there comes to them a sign (from Allah), They say: "We shall not believe until we receive one (exactly) like those received by Allah\'s messengers." Allah knoweth best where (and how) to carry out His mission. Soon will the wicked be overtaken by humiliation before Allah, and a severe punishment, for all their plots.'),
  ('en.yusufali', 6, 125, 'Those whom Allah (in His plan) willeth to guide,- He openeth their breast to Islam; those whom He willeth to leave straying,- He maketh their breast close and constricted, as if they had to climb up to the skies: thus doth Allah (heap) the penalty on those who refuse to believe.'),
  ('en.yusufali', 6, 126, 'This is the way of thy Lord, leading straight: We have detailed the signs for those who receive admonition.'),
  ('en.yusufali', 6, 127, 'For them will be a home of peace in the presence of their Lord: He will be their friend, because they practised (righteousness).'),
  ('en.yusufali', 6, 128, 'One day will He gather them all together, (and say): "O ye assembly of Jinns! Much (toll) did ye take of men." Their friends amongst men will say: "Our Lord! we made profit from each other: but (alas!) we reached our term - which thou didst appoint for us." He will say: "The Fire be your dwelling-place: you will dwell therein for ever, except as Allah willeth." for thy Lord is full of wisdom and knowledge.'),
  ('en.yusufali', 6, 129, 'Thus do we make the wrong-doers turn to each other, because of what they earn.'),
  ('en.yusufali', 6, 130, '"O ye assembly of Jinns and men! came there not unto you messengers from amongst you, setting forth unto you My signs, and warning you of the meeting of this Day of yours?" They will say: "We bear witness against ourselves." It was the life of this world that deceived them. So against themselves will they bear witness that they rejected Faith.'),
  ('en.yusufali', 6, 131, '(The messengers were sent) thus, for thy Lord would not destroy for their wrong-doing men\'s habitations whilst their occupants were unwarned.'),
  ('en.yusufali', 6, 132, 'To all are degrees (or ranks) according to their deeds: for thy Lord is not unmindful of anything that they do.'),
  ('en.yusufali', 6, 133, 'Thy Lord is self-sufficient, full of Mercy: if it were His will, He could destroy you, and in your place appoint whom He will as your successors, even as He raised you up from the posterity of other people.'),
  ('en.yusufali', 6, 134, 'All that hath been promised unto you will come to pass: nor can ye frustrate it (in the least bit).'),
  ('en.yusufali', 6, 135, 'Say: "O my people! Do whatever ye can: I will do (my part): soon will ye know who it is whose end will be (best) in the Hereafter: certain it is that the wrong-doers will not prosper."'),
  ('en.yusufali', 6, 136, 'Out of what Allah hath produced in abundance in tilth and in cattle, they assigned Him a share: they say, according to their fancies: "This is for Allah, and this" - for our "partners"! but the share of their" partners "reacheth not Allah, whilst the share of Allah reacheth their "partners"! evil (and unjust) is their assignment!'),
  ('en.yusufali', 6, 137, 'Even so, in the eyes of most of the pagans, their "partners" made alluring the slaughter of their children, in order to lead them to their own destruction, and cause confusion in their religion. If Allah had willed, they would not have done so: But leave alone them and their inventions.'),
  ('en.yusufali', 6, 138, 'And they say that such and such cattle and crops are taboo, and none should eat of them except those whom - so they say - We wish; further, there are cattle forbidden to yoke or burden, and cattle on which, (at slaughter), the name of Allah is not pronounced; - inventions against Allah\'s name: soon will He requite them for their inventions.'),
  ('en.yusufali', 6, 139, 'They say: "What is in the wombs of such and such cattle is specially reserved (for food) for our men, and forbidden to our women; but if it is still-born, then all have share therein. For their (false) attribution (of superstitions to Allah), He will soon punish them: for He is full of wisdom and knowledge.'),
  ('en.yusufali', 6, 140, 'Lost are those who slay their children, from folly, without knowledge, and forbid food which Allah hath provided for them, inventing (lies) against Allah. They have indeed gone astray and heeded no guidance.'),
  ('en.yusufali', 6, 141, 'It is He Who produceth gardens, with trellises and without, and dates, and tilth with produce of all kinds, and olives and pomegranates, similar (in kind) and different (in variety): eat of their fruit in their season, but render the dues that are proper on the day that the harvest is gathered. But waste not by excess: for Allah loveth not the wasters.'),
  ('en.yusufali', 6, 142, 'Of the cattle are some for burden and some for meat: eat what Allah hath provided for you, and follow not the footsteps of Satan: for he is to you and avowed enemy.'),
  ('en.yusufali', 6, 143, '(Take) eight (head of cattle) in (four) pairs: of sheep a pair, and of goats a pair; say, hath He forbidden the two males, or the two females, or (the young) which the wombs of the two females enclose? Tell me with knowledge if ye are truthful:'),
  ('en.yusufali', 6, 144, 'Of camels a pair, and oxen a pair; say, hath He forbidden the two males, or the two females, or (the young) which the wombs of the two females enclose? - Were ye present when Allah ordered you such a thing? But who doth more wrong than one who invents a lie against Allah, to lead astray men without knowledge? For Allah guideth not people who do wrong.'),
  ('en.yusufali', 6, 145, 'Say: "I find not in the message received by me by inspiration any (meat) forbidden to be eaten by one who wishes to eat it, unless it be dead meat, or blood poured forth, or the flesh of swine,- for it is an abomination - or, what is impious, (meat) on which a name has been invoked, other than Allah\'s". But (even so), if a person is forced by necessity, without wilful disobedience, nor transgressing due limits,- thy Lord is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 6, 146, 'For those who followed the Jewish Law, We forbade every (animal) with undivided hoof, and We forbade them that fat of the ox and the sheep, except what adheres to their backs or their entrails, or is mixed up with a bone: this in recompense for their wilful disobedience: for We are true (in Our ordinances).'),
  ('en.yusufali', 6, 147, 'If they accuse thee of falsehood, say: "Your Lord is full of mercy all-embracing; but from people in guilt never will His wrath be turned back.'),
  ('en.yusufali', 6, 148, 'Those who give partners (to Allah) will say: "If Allah had wished, we should not have given partners to Him nor would our fathers; nor should we have had any taboos." So did their ancestors argue falsely, until they tasted of Our wrath. Say: "Have ye any (certain) knowledge? If so, produce it before us. Ye follow nothing but conjecture: ye do nothing but lie."'),
  ('en.yusufali', 6, 149, 'Say: "With Allah is the argument that reaches home: if it had been His will, He could indeed have guided you all."'),
  ('en.yusufali', 6, 150, 'Say: "Bring forward your witnesses to prove that Allah did forbid so and so." If they bring such witnesses, be not thou amongst them: Nor follow thou the vain desires of such as treat our signs as falsehoods, and such as believe not in the Hereafter: for they hold others as equal with their Guardian-Lord.'),
  ('en.yusufali', 6, 151, 'Say: "Come, I will rehearse what Allah hath (really) prohibited you from": Join not anything as equal with Him; be good to your parents; kill not your children on a plea of want;- We provide sustenance for you and for them;- come not nigh to shameful deeds. Whether open or secret; take not life, which Allah hath made sacred, except by way of justice and law: thus doth He command you, that ye may learn wisdom.'),
  ('en.yusufali', 6, 152, 'And come not nigh to the orphan\'s property, except to improve it, until he attain the age of full strength; give measure and weight with (full) justice;- no burden do We place on any soul, but that which it can bear;- whenever ye speak, speak justly, even if a near relative is concerned; and fulfil the covenant of Allah: thus doth He command you, that ye may remember.'),
  ('en.yusufali', 6, 153, 'Verily, this is My way, leading straight: follow it: follow not (other) paths: they will scatter you about from His (great) path: thus doth He command you. that ye may be righteous.'),
  ('en.yusufali', 6, 154, 'Moreover, We gave Moses the Book, completing (Our favour) to those who would do right, and explaining all things in detail,- and a guide and a mercy, that they might believe in the meeting with their Lord.'),
  ('en.yusufali', 6, 155, 'And this is a Book which We have revealed as a blessing: so follow it and be righteous, that ye may receive mercy:'),
  ('en.yusufali', 6, 156, 'Lest ye should say: "The Book was sent down to two Peoples before us, and for our part, we remained unacquainted with all that they learned by assiduous study:"'),
  ('en.yusufali', 6, 157, 'Or lest ye should say: "If the Book had only been sent down to us, we should have followed its guidance better than they." Now then hath come unto you a clear (sign) from your Lord,- and a guide and a mercy: then who could do more wrong than one who rejecteth Allah\'s signs, and turneth away therefrom? In good time shall We requite those who turn away from Our signs, with a dreadful penalty, for their turning away.'),
  ('en.yusufali', 6, 158, 'Are they waiting to see if the angels come to them, or thy Lord (Himself), or certain of the signs of thy Lord! the day that certain of the signs of thy Lord do come, no good will it do to a soul to believe in them then if it believed not before nor earned righteousness through its faith. Say: "Wait ye: we too are waiting."'),
  ('en.yusufali', 6, 159, 'As for those who divide their religion and break up into sects, thou hast no part in them in the least: their affair is with Allah: He will in the end tell them the truth of all that they did.'),
  ('en.yusufali', 6, 160, 'He that doeth good shall have ten times as much to his credit: He that doeth evil shall only be recompensed according to his evil: no wrong shall be done unto (any of) them.'),
  ('en.yusufali', 6, 161, 'Say: "Verily, my Lord hath guided me to a way that is straight,- a religion of right,- the path (trod) by Abraham the true in Faith, and he (certainly) joined not gods with Allah."'),
  ('en.yusufali', 6, 162, 'Say: "Truly, my prayer and my service of sacrifice, my life and my death, are (all) for Allah, the Cherisher of the Worlds:'),
  ('en.yusufali', 6, 163, 'No partner hath He: this am I commanded, and I am the first of those who bow to His will.'),
  ('en.yusufali', 6, 164, 'Say: "Shall I seek for (my) Cherisher other than Allah, when He is the Cherisher of all things (that exist)? Every soul draws the meed of its acts on none but itself: no bearer of burdens can bear the burden of another. Your goal in the end is towards Allah: He will tell you the truth of the things wherein ye disputed."'),
  ('en.yusufali', 6, 165, 'It is He Who hath made you (His) agents, inheritors of the earth: He hath raised you in ranks, some above others: that He may try you in the gifts He hath given you: for thy Lord is quick in punishment: yet He is indeed Oft-forgiving, Most Merciful.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 6, 1, 'Alhamdu lillaahil lazee khalaqas samaawaati wal arda wa ja\'alaz zulumaati wannoor; summal lazeena kafaroo bi Rabbihim ya\'diloon'),
  ('en.transliteration', 6, 2, 'Huwal lazee khalaqakum min teenin summa qadaaa ajalanw wa ajalum musamman \'indahoo summa antum tamtaroon'),
  ('en.transliteration', 6, 3, 'Wa Huwal laahu fissamaawaati wa fil ardi ya\'lamu sirrakum wa jahrakum wa ya\'lamu maa taksiboon'),
  ('en.transliteration', 6, 4, 'Wa maa taateehim min Aayatim min Aayaati Rabbihim illaa kaanoo \'anhaa mu\'rideen'),
  ('en.transliteration', 6, 5, 'Faqad kazzaboo bilhaqqi lammaa jaaa\'ahum fasawfa yaateehim ambaaa\'u maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 6, 6, 'Alam yaraw kam ahlaknaa min qablihim min qarnim makkannaahum fil ardi maa lam numakkil lakum wa arsalnas samaaa\'a \'alaihim midraaranw wa ja\'alnal anhaara tajree min tahtihim fa ahlak naahum bizunoobihim wa anshaanaa mim ba\'dihim qarnan aakhareen'),
  ('en.transliteration', 6, 7, 'Wa law nazzalnaa \'alaika Kitaaban fee qirtaasin falamasoohu bi aideehim laqaalal lazeena kafarooo in haazaaa illaa sihrum mubeen'),
  ('en.transliteration', 6, 8, 'Wa qaaloo law laaa unzila alaihi malakunw wa law anzalna malakal laqudiyal amru summa laa yunzaroon'),
  ('en.transliteration', 6, 9, 'Wa law ja\'alnaahu malakal laja\'alnaahu rajulanw wa lalabasnaa \'alaihim maa yalbisoon'),
  ('en.transliteration', 6, 10, 'Wa laqadis tuhzi\'a bi-Rusulim min qablika fahaaqa billazeena sakhiroo minhum maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 6, 11, 'Qul seeroo fil ardi summan zuroo kaifa kaana \'aaqibatul mukazzibeen'),
  ('en.transliteration', 6, 12, 'Qul limam maa fis samaawaati wal ardi qul lillaah; kataba \'alaa nafsihir rahmah; la yajma \'annakum ilaa Yawmil Qiyaamati laa raiba feeh; allazeena khasirooo anfusahum fahum laa yu\'minoon'),
  ('en.transliteration', 6, 13, 'Wa lahoo maa sakana fillaili wannahaar; wa Huwas Samee\'ul Aleem'),
  ('en.transliteration', 6, 14, 'Qul aghairal laahi attakhizu waliyyan faatiris samaawaati wal ardi wa Huwa yut\'imu wa laa yut\'am; qul inneee umirtu an akoona awwala man salama wa laa takoonanna minal mushrikeen'),
  ('en.transliteration', 6, 15, 'Qul inneee akhaafu in \'asaitu Rabbee \'azaaba Yawmin \'Azeem'),
  ('en.transliteration', 6, 16, 'Mai yusraf \'anhu Yawma\'izin faqad rahimah; wa zaalikal fawzul mubeen'),
  ('en.transliteration', 6, 17, 'Wa iny-yamsaskal laahu bidurrin falaaa kaashifa lahoo illaa Huwa wa iny-yamsaska bikhairin fa Huwa \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 6, 18, 'Wa Huwal gaahiru fawqa \'ibaadih; wa Huwal Hakeemul Khabeer'),
  ('en.transliteration', 6, 19, 'Qul ayyu shai\'in akbaru shahaadatan qulil laahu shaheedum bainee wa bainakum; wa oohiya ilaiya haazal Qur\'aanu li unzirakum bihee wa mam balagh; a\'innakum latashhadoona anna ma\'al laahi aalihatan ukhraa; qul laaa ashhad; qul innamaa Huwa Ilaahunw Waahidunw wa innanee baree\'um mimmaa tushrikoon'),
  ('en.transliteration', 6, 20, 'Allazeena aatainaa humul Kitaaba ya\'rifoonahoo kamaa ya\'rifoona abnaaa\'ahum; allazeena khasirooo anfusahum fahum laa yu\'minoon'),
  ('en.transliteration', 6, 21, 'Wa man azlamu mim manif tara \'alal laahi kaziban aw kazzaba bi Aayaatih; innahoo laa yuflihuz zaalimoon'),
  ('en.transliteration', 6, 22, 'Wa yawma nahshuruhum jamee\'an summa naqoolu lillazeena ashrakooo ayna shurakaaa\' ukumul lazeena kuntum taz\'umoon'),
  ('en.transliteration', 6, 23, 'Summa lam takun fitnatuhum illaaa an qaaloo wallaahi Rabbinaa maa kunnaa mushrikeen'),
  ('en.transliteration', 6, 24, 'Unzur kaifa kazaboo \'alaaa anfusihim, wa dalla \'anhum maa kaanoo yaftaroon'),
  ('en.transliteration', 6, 25, 'Wa minhum mai yastami\'u ilaika wa ja\'alnaa \'alaa quloobihim akinnatan ai yafqahoohu wa feee aazaanihim waqraa; wa ai yaraw kulla Aayatil laa yu\'minoo bihaa; hattaaa izaa jaaa\'oka yujaadiloonaka yaqoolul lazeena kafaroo in haazaa illaaa asaateerul awwaleen'),
  ('en.transliteration', 6, 26, 'Wa hum yanhawna \'anhu wa yan\'awna \'anhu wa iny yuhlikoona illaa anfusahum wa maa yash\'uroon'),
  ('en.transliteration', 6, 27, 'Wa law taraaa iz wauqifoo \'alan Naari faqaaloo yaa laitanaa nuraddu wa laa nukaz ziba bi Aayaati Rabbinaa wa nakoona minal mu\'mineen'),
  ('en.transliteration', 6, 28, 'Bal badaa lahum maa kaanoo yukhfoona min qablu wa law ruddoo la\'aadoo limaa nuhoo \'anhu wa innahum lakaaziboon'),
  ('en.transliteration', 6, 29, 'Wa qaalooo in hiya illaa hayaatunad dunyaa wa maa nahnu bimab\'ooseen'),
  ('en.transliteration', 6, 30, 'Wa law taraa iz wuqifoo \'alaa Rabbihim; qaala alaisa haazaa bilhaqq; qaaloo balaa wa Rabbinaa; qaala fazooqul \'azaaba bimaa kuntum takfuroon'),
  ('en.transliteration', 6, 31, 'Qad khasiral lazeena kazzaboo biliqaaa\'il laahi hattaaa izaa jaaa\'at humus Saa\'atu baghtan qaaloo yaa hasratanaa \'alaa maa farratnaa feehaa wa hum yahmiloona awzaarahum \'alaa zuhoorihim; alaa saaa\'a ma yaziroon'),
  ('en.transliteration', 6, 32, 'Wa mal hayaatud dunyaaa illaa la\'ibunw wa lahwunw wa lad Daarul Aakhiratu kahyrul lillazeena yattaqoon; afalaa ta\'qiloon'),
  ('en.transliteration', 6, 33, 'Qad na\'lamu innahoo layahzunukal lazee yaqooloona fa innahum laa yukazziboonaka wa laakinnaz zaalimeena bi Aayaatil laahi yajhadoon'),
  ('en.transliteration', 6, 34, 'Wa laqad kuzzibat Rusulum min qablika fasabaroo \'alaa maa kuzziboo wa oozoo hattaaa ataahum nasrunaa; wa laa mubaddila li Kalimaatil laah; wa laqad jaaa\'aka min naba\'il mursaleen'),
  ('en.transliteration', 6, 35, 'Wa in kaana kabura \'alaika i\'raaduhum fa inistata\'ta an tabtaghiya nafaqan fil ardi aw sullaman fis samaaa\'i fataa tiyahum bi Aayah; wa law shaaa\'al laahu lajama\'ahum \'alal hudaa; falaa takoonanna minal jaahileen'),
  ('en.transliteration', 6, 36, 'Innamaa yastajeebul lazeena yasma\'oon; walmawtaa yab\'asuhumul laahu summa ilaihi yurja\'oon'),
  ('en.transliteration', 6, 37, 'Wa qaaloo law laa nuzzila \'alaihi Aayatum mir Rabbih; qul innal laaha qaadirun \'alaaa ai yunazzila Aayatanw wa laakinna aksarahum laa ya\'lamoon'),
  ('en.transliteration', 6, 38, 'Wa maa min daaabbatin fil ardi wa laa taaa\'iriny yateeru bijanaahaihi illaaa umamun amsaalukum; maa farratnaa fil Kitaabi min shai\'in summa ilaa Rabbihim yuhsharoon'),
  ('en.transliteration', 6, 39, 'Wallazeena kazzaboo bi Aayaatinaa summunw wa bukmun fiz zulumaat; mai yasha il laahu yudlilh; wa mai yashaa yaj\'alhu \'alaa Siraatim Mustaqeem'),
  ('en.transliteration', 6, 40, 'Qaul ara\'aytakum in ataakum \'azaabul laahi aw atatkumus Saa\'atu a-ghairal laahi tad\'oona in kuntum saadiqeen'),
  ('en.transliteration', 6, 41, 'Bal iyyaahu tad\'oona fa yakshifu maa tad\'oona ilaihi in shaaa\'a wa tansawna maa tushrikoon'),
  ('en.transliteration', 6, 42, 'Wa laqad arsalnaaa ilaaa umamim min qablika fa akhaznaahum bilbaasaaa\'i waddarraaa\'i la\'allahum yata darra\'oon'),
  ('en.transliteration', 6, 43, 'Falaw laaa iz jaaa\'ahum baasunaa tadarra\'oo wa laakin qasat quloobuhum wa zaiyana lahumush Shaitaanu maa kaanoo ya\'maloon'),
  ('en.transliteration', 6, 44, 'Falammaa nasoo maa zukkiroo bihee fatahnaa \'alaihim abwaaba kulli shai\'in hattaaa izaa farihoo bimaaa ootooo akhaznaahum baghtatan fa izaa hum mmublisoon'),
  ('en.transliteration', 6, 45, 'Faquti\'a daabirul qawmil lazeena zalamoo; walhamdu lillaahi Rabbil \'aalameen'),
  ('en.transliteration', 6, 46, 'Qul ara\'aitum in akhazal laahu sam\'akum wa absaarakum wa khatama \'alaa quloobikum man ilaahun ghairul laahi yaateekum bih; unzur kaifa nusarriful Aayaati summa hum yasdifoon'),
  ('en.transliteration', 6, 47, 'Qul ara\'aitakum in ataakum \'azaabul laahi baghtatan aw jahratan hal yuhlaku illal qawmuz zaalimoon'),
  ('en.transliteration', 6, 48, 'Wa maa nursilul mursaleena illaa mubashshireena wa munzireena faman aamana wa aslaha falaa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 6, 49, 'Wallazeena kazzaboo bi Aayaatinaa yamassuhumul \'azaabu bimaa kaanoo yafsuqoon'),
  ('en.transliteration', 6, 50, 'Qul laaa aqoolu lakum \'indee khazaaa\'inul laahi wa laaa a\'lamul ghaiba wa laaa aqoolu lakum innee malakun in attabi\'u illaa maa yoohaaa ilaiy; qul hal yastawil a\'maa walbaseer; afalaa tatafakkaroon'),
  ('en.transliteration', 6, 51, 'Wa anzir bihil lazeena yakhaafoona ai yuhsharooo ilaa Rabbihim laisa lahum min doonihee waliyyunw wa laa shafee\'ul la\'allahum yattaqoon'),
  ('en.transliteration', 6, 52, 'Wa laa tatrudil lazeena yad\'oona Rabbahum bilghadaati wal \'ashiyyi yureedoona Wajhahoo ma \'alaika min hisaabihim min shai\'inw wa maa min hisaabika \'alaihim min shai\'in fatatrudahum fatakoona minaz zaalimeen'),
  ('en.transliteration', 6, 53, 'Wa kazaalika fatannaa ba\'dahum biba\'dil liyaqoolooo ahaaa\'ulaaa\'i mannal laahu \'alaihim mim baininaa; alaisal laahu bi-a\'lama bish shaakireen'),
  ('en.transliteration', 6, 54, 'Wa izaa jaaa\'akal lazeena yu\'minoona bi Aayaatinaa faqul salaamun \'alaikum kataba Rabbukum \'alaa nafsihir rahmata annahoo man \'amila minkum sooo\'am bijahaalatin summa taaba mim ba\'dihee wa aslaha fa annahoo Ghafoorur Raheem'),
  ('en.transliteration', 6, 55, 'Wa kazaalika nufassilul Aayaati wa litastabeena sabeelul mujrimeen'),
  ('en.transliteration', 6, 56, 'Qul innee nuheetu an a\'budal lazeena tad\'oona min doonil laah; qul laaa attabi\'u ahwaaa\'akum qad dalaltu izanw wa maaa ana minal muhtadeen'),
  ('en.transliteration', 6, 57, 'Qul innee \'alaa baiyinatim mir Rabbee wa kazzabtum bih; maa \'indee maa tasta\'jiloona bih; inil hukmu illaa lillaahi yaqussul haqqa wa Huwa khairul faasileen'),
  ('en.transliteration', 6, 58, 'Qul law anna \'indee maa tasta\'jiloona bihee laqudiyal amru bainee wa bainakum; wallaahu a\'lamu bizzaalimeen'),
  ('en.transliteration', 6, 59, 'Wa \'indahoo mafaatihul ghaibi laa ya\'lamuhaaa illaa Hoo; wa ya\'lamu maa fil barri walbahr; wa maa tasqutu minw waraqatin illaa ya\'lamuhaa wa laa habbatin fee zulumaatil ardi wa laa ratbinw wa laa yaabisin illaa fee Kitaabim Mubeen'),
  ('en.transliteration', 6, 60, 'Wa Huwal lazee yatawaf faakum billaili wa ya\'lamu maa jarahtum binnahaari summa yab\'asukum fee liyuqdaaa ajalum musamman summa ilaihi marji\'ukum summa yunabbi \'ukum bimaa kuntum ta\'maloon'),
  ('en.transliteration', 6, 61, 'Wa huwal qaahiru fawqa \'ibaadihee wa yursilu \'alaikum hafazatan hattaaa izaa jaaa\'a ahadakumul mawtu tawaffathu rusulunaa wa hum laa yufarritoon'),
  ('en.transliteration', 6, 62, 'Summa ruddooo ilallaahi mawlaahumul haqq; alaa lahul hukmu wa Huwa asra\'ul haasibeen'),
  ('en.transliteration', 6, 63, 'Qul mai yunajjeekum min zulumaatil barri walbahri tad\'oonahoo tadarru\'anw wa khufyatann la\'in anjaanaa min haazihee lanakoonana minash shaakireen'),
  ('en.transliteration', 6, 64, 'Qulil laahu yunajjjeekum minhaa wa min kulli karbin summa antum tushrikoon'),
  ('en.transliteration', 6, 65, 'Qul huwal Qaadiru \'alaaa ai yab\'asa \'alaikum \'azaabam min fawqikum aw min tahti arjulikum aw yalbisakum shiya\'anw wa yuzeeqa ba\'dakum baasa ba\'d; unzur kaifa nusarriful Aayaati la\'allahum yafqahoon'),
  ('en.transliteration', 6, 66, 'Wa kaz zaba bihee qawmuka wa huwal haqq; qul lastu\'alaikum biwakeel'),
  ('en.transliteration', 6, 67, 'Likulli naba im mustaqar runw wa sawfa ta\'lamoon'),
  ('en.transliteration', 6, 68, 'Wa izaa ra aital lazeena yakhoodoona feee Aayaatinaa fa a\'rid \'anhum hattaa yakkhoodoo fee hadeesin ghairih; wa immaa yunsiyannakash Shaitaanu falaa taq\'ud ba\'dazzikraa ma\'al qawmiz zaalimeen'),
  ('en.transliteration', 6, 69, 'Wa maa \'alal lazeena yattaqoona min hisaabihim min shai\'inw wa laakin zikraa la\'allahum yattaqoon'),
  ('en.transliteration', 6, 70, 'Wa zaril lazeenat takhazoo deenahum la\'ibanwwa lahwanw wa gharrat humul ha yaatud dunyaa; wa zakkir biheee an tubsala nafsum bimaa kasabat laisa lahaa min doonil laahi waliyyunw wa laa shafee\'unw wa in ta\'dil kulla \'adlil laa yu\'khaz minhaa; ulaaa \'ikal lazeena ubsiloo bimaa kasaboo lahum sharaabum min hameeminw wa \'azaabun aleemum bimaa kaanoo yakkfuroon'),
  ('en.transliteration', 6, 71, 'Qul anad\'oo min doonil laahi maa laa yanfa\'unaa wa laa yadurrunaa wa nuraddu \'alaaa a\'qaabina ba\'da iz hadaanal laahu kallazis tahwat hush Shayaateenu fil ardi hairaana lahooo ashaabuny yad\'oo nahooo ilal huda\' tinaa; qul inna hudal laahi huwal hudaa wa umirnaa linuslima li Rabbil \'aalameen'),
  ('en.transliteration', 6, 72, 'Wa an aqeemus Salaata wattaqooh; wa Hual lazeee ilaihi tuhsharoon'),
  ('en.transliteration', 6, 73, 'Wa an Huwal lazee khalaqas samaawaati wal arda bilhaqq; wa Yawma yaqoolu kun fa yakoon; Qawluhul haqq; wa lahul mulku Yawma yunfakhu fis Soor; \'Aalimul Ghaibi wash shahaadah; wa Huwal Hakeemul Khabeer'),
  ('en.transliteration', 6, 74, 'Wa iz qaala Ibraaheemu li abeehi Aazara a-tattakhizu asnaaman aalihatan inneee araaka wa qawmaka fee dalaalim mmubeen'),
  ('en.transliteration', 6, 75, 'Wa kazaalika nureee Ibraaheema malakootas samaawaati wal ardi wa liyakoona minal mooqineen'),
  ('en.transliteration', 6, 76, 'Falammaa janna \'alaihil lailu ra aa kawkabaan qaala haaza Rabbee falammaaa afala qaala laaa uhibbul aafileen'),
  ('en.transliteration', 6, 77, 'Falammmaa ra al qamara baazighan qaala haazaa Rabbee falammmmaaa afala qaala la\'il lam yahdinee Rabbee la akoonanna minal qawmid daaalleen'),
  ('en.transliteration', 6, 78, 'Falammmaa ra ashshamsa baazighatan qaala haazaa Rabbee haazaaa akbaru falammaaa afalat qaala yaa qawmi innee bareee\'um mimmaa tushrikoon'),
  ('en.transliteration', 6, 79, 'Innnee wajjahtu wajhiya lillazee fataras samaawaati wal arda haneefanw wa maaa ana minal mushrikeen'),
  ('en.transliteration', 6, 80, 'Wa haaajjahoo qawmuh; qaala a-tuh aaajjooonnnee fillaahi wa qad hadaan; wa laaa akhaafu mmaa tushrikoona bihee illaaa ai yashaaa\'a Rabbee shai\'anw wasi\'a Rabbee kulla shai\'in \'ilman afalaa tatazakkaroon'),
  ('en.transliteration', 6, 81, 'Wa kaifa akhaafu maaa ashraktum wa laa takhaafoona annakum ashraktum billaahi maa lam yunazzil bihee \'alaikum sultaanaa; fa aiyul fareeqaini ahaqqu bil amni in kuntum ta\'lamoon'),
  ('en.transliteration', 6, 82, 'Allazeena aamanoo wa lam yalbisooo eemaanahum bizulmin ulaaa\'ika lahumul amnu wa hum muhtadoon'),
  ('en.transliteration', 6, 83, 'Wa tilka hujjatunaaa aatainaahaaa Ibraaheema \'alaa qawmih; narfa\'u darajaatim man nashaaa\'; inna Rabbaka Hakeemun \'Aleem'),
  ('en.transliteration', 6, 84, 'Wa wahabnaa lahoo ishaaqa wa ya\'qoob; kullan hadainaa; wa Noohan hadainaa min qablu wa min zurriyyatihee Daawooda wa Sulaimaana wa Ayyooba wa Yoosufa wa Moosaa wa haaroon; wa kazaalika najzil muhsineen'),
  ('en.transliteration', 6, 85, 'Wa Zakariyyaa wa Yahyaa wa \'Eesaa wa Illyaasa kullum minas saaliheen'),
  ('en.transliteration', 6, 86, 'Wa Ismaa\'eela wal Yasa\'a wa Yoonusa wa Lootaa; wa kullan faddalnaa \'alal \'aalameen'),
  ('en.transliteration', 6, 87, 'Wa min aabaaa\'ihim wa zurriyyaatihim wa ikhwaanihim wajtabainaahum wa hadainaahum ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 6, 88, 'Zaalika hudal laahi yahdee bihee mai yashaaa\'u min \'ibaadih; wa law ashrakoo lahabita \'anhum maa kaanoo ya\'maloon'),
  ('en.transliteration', 6, 89, 'Ulaaa\'ikal lazeena aatainaahumul Kitaaba wal hukma wan Nubuwwah; fa iny yakfur bihaa haaa\'ulaaa\'i faqad wakkalnaa bihaa qawmal laisoo bihaa bikaafireen'),
  ('en.transliteration', 6, 90, 'Ulaaa\'ikal lazeena hadal laahu fabihudaahumuq tadih; qul laaa as\'alukum \'alaihi ajran in huwa illaa zikraa lil \'aalameen'),
  ('en.transliteration', 6, 91, 'Wa maa qadarul laaha haqqa qadriheee iz qaaloo maaa anzalal laahu \'alaa basharim min shai\'; qul man anzalal Kitaabal lazee jaaa\'a bihee Moosaa nooranw wa hudal linnaasi taj\'aloonahoo qaraateesa tubdoonahaa wa tukhfoona kaseeranw wa \'ullimtum maa lam ta\'lamooo antum wa laaa aabaaa\'ukum qulil laahu summa zarhum fee khawdihim yal\'aboon'),
  ('en.transliteration', 6, 92, 'Wa haazaa Kitaabun anzalnaahu Mubaarakum musaddiqul lazee bainaa yadaihi wa litunzira ummal Quraa wa man hawlahaa; wallazeena yu\'minoona bil Aakhirati yu\'minoona bihee wa hum\'alaa Salaatihim yuhaafizoon'),
  ('en.transliteration', 6, 93, 'Wa man azlamu mimmanif taraa \'alal laahi kaziban aw qaala oohiya ilaiya wa lam yooha ilaihi shai\'un wa man qaala sa unzilu misla maaa anzalal laah; wa law taraaa iziz zaalimoona fee ghamaraatil mawti walmalaaa\'ikatu baasitooo aideehim akhrijooo anfusakum; al yawma tujzawna \'azaabal hooni bimaa kuntum taqooloona \'alal laahi ghairal haqqi wa kuntum \'an aayaatihee tastakbiroon'),
  ('en.transliteration', 6, 94, 'Wa laqad ji\'tumoonaa furaadaa kamaa khalaqnaakum awwala marratinw wa taraktum maa khawwalnaakum waraaa\'a zuhoorikum wa maa naraa ma\'akum shufa\'aaa\' akumul lazeena za\'amtum annahum feekum shurakaaa\'; laqat taqatta\'a bainakum wa dalla \'annkum maa kuntum taz\'umoon'),
  ('en.transliteration', 6, 95, 'Innal laaha faaliqul habbi wannawaa yukhrijul haiya minal maiyiti wa mukhrijul maiyiti minal haiy; zaalikumul laahu fa annaa tu\'fakoon'),
  ('en.transliteration', 6, 96, 'Faaliqul isbaahi wa ja\'alal laila sakananw washh shamsa walqamara husbaanaa; zaalika taqdeerul \'Azeezil \'Aleem'),
  ('en.transliteration', 6, 97, 'Wa Huwal lazee ja\'ala lakumun nujooma litahtadoo bihaa fee zulumaatil barri walbahr; qad fassalnal Aayaati liqawminy ya\'lamoon'),
  ('en.transliteration', 6, 98, 'Wa hhuwal lazeee ansha akum min nasinw waahidatin famustaqarrunw wa mustawda\'; qad fassalnal Aayaati liqaw miny-yafqahoon'),
  ('en.transliteration', 6, 99, 'Wa Huwal lazeee anzala minas samaaa\'i maaa\'an fa akhrajnaa bihee nabaata kulli shai\'in fa akhrajnaa minhu khadiran nukhriju minhu habbam mutaraakibanw wa minan nakhli min tal\'ihaa qinwaanun daaniyatunw wa jannaatim min a\'naabinw wazzaitoona warrummaana mushhtabihanw wa ghaira mutashaabih; unzurooo ilaa samariheee izaaa asmars wa yan\'ih; inna fee zaalikum la Aayaatil liqawminy yu\'minoon'),
  ('en.transliteration', 6, 100, 'Wa ja\'aloo lillaahi shurakaaa\'al jinna wa khalaqa hum wa kharaqoo lahoo baneena wa banaatim bighairi \'ilm Subhaanahoo wa Ta\'aalaa \'amma yasifoon'),
  ('en.transliteration', 6, 101, 'Badee\'us samaawaati wal ardi annnaa yakoonu lahoo waladunw wa lam takul lahoo saahibatunw wa khalaqa kulla shai\'in \'Aleem'),
  ('en.transliteration', 6, 102, 'Zaalikumul laahu Rabbukum laaa ilaaha illaa huwa khaaliqu kulli shai\'in fa\'budooh; wa huwa \'alaa kulli shai\'inw Wakeel'),
  ('en.transliteration', 6, 103, 'Laa tudrikuhul absaaru wa Huwa yudrikul absaara wa huwal Lateeful Khabeer'),
  ('en.transliteration', 6, 104, 'Qad jaaa\'akum basaaa\'iru mir Rabbikum faman absara falinafsihee wa man \'amiya fa\'alaihaa; wa maaa ana \'alaikum bihafeez'),
  ('en.transliteration', 6, 105, 'Wa kazaalika nusarriful Aayaati wa liyaqooloo darasta wa linubaiyinahoo liqawminy ya\'lamoon'),
  ('en.transliteration', 6, 106, 'ittabi\' maaa oohiya ilaika mir Rabbika laaa ilaaha illaa Huwa wa a\'rid \'anil mushrikeen'),
  ('en.transliteration', 6, 107, 'Wa law shaaa\'al laahu maaa ashrakoo; wa maa ja\'alnaaka \'alaihim hafeezanw wa maaa anta \'alaihim biwakeel'),
  ('en.transliteration', 6, 108, 'Wa laa tasubbul lazeena yad\'oona min doonil laahi fa yasubbul laaha \'adwam bighairi \'ilm; kazaalika zaiyannaa likulli ummatin \'amalahum summa ilaa Rabbihim marji\'uhum fa yunabbi\'uhum bimaa kaanooya\'maloon'),
  ('en.transliteration', 6, 109, 'Wa aqsamoo billaahi jahda aimaanihim la\'in jaaa\'at hum Aayatul la yu\'minunna bihaa; qul innamal Aayaatu \'indal laahi wa maa yush\'irukum annahaaa izaa jaaa\'at laa yu\'minoon'),
  ('en.transliteration', 6, 110, 'Wa nuqallibu af\'idatahum wa absaarahum kamaa lam yu\'minoo biheee awwala marratinw wa wa nazaruhum fee tughyaanihim ya\'mahoon'),
  ('en.transliteration', 6, 111, 'Wa law annanaa nazzal naaa ilaihimul malaaa\'ikata wa kallamahumul mawtaa wa hasharnaa \'alaihim kulla shai\'in qubulam maa kaanoo liyu\'minooo illaaa ai yashaaa\'al laahu wa laakinna aksarahum yajhaloon'),
  ('en.transliteration', 6, 112, 'Wa kazaalika ja\'alnaa likulli nabiyyin \'aduwwan Shayaateenal insi waljinni yoohee ba\'duhum ilaa ba\'din zukhrufal qawli ghurooraa; wa law shaaa\'a Rabbuka maa fa\'aloohu fazarhum wa maa yaftaroon'),
  ('en.transliteration', 6, 113, 'Wa litasghaaa ilaihi af\'idatul lazeena laa yu\'minoona bil Aakhirati wa liyardawhu wa liyaqtarifoo maa hum muqtarifoon'),
  ('en.transliteration', 6, 114, 'Afaghairal laahi abtaghee hakamanw wa Huwal lazee anzala ilaikumul Kitaaba mufassalaa; wallazeena atai naahumul Kitaaba ya\'lamoona annahoo munazzalum mir Rabbika bilhaqqi falaa takoonanna minal mumtareen'),
  ('en.transliteration', 6, 115, 'Wa tammat Kalimatu Rabbika sidqanw wa \'adlaa; laa mubaddila li Kalimaatih; wa Huwas Samee\'ul \'Aleem'),
  ('en.transliteration', 6, 116, 'Wa in tuti\' aksara man fil ardi yudillooka \'an sabeelil laah; iny yattabi\'oona illaz zanna wa in hum illaa yakhrusoon'),
  ('en.transliteration', 6, 117, 'Inna rabbaka Huwa a\'lamu mai yadillu \'an sabeelihee wa Huwa a\'lamu bilmuhtadeen'),
  ('en.transliteration', 6, 118, 'Fakuloo mimmmaa zukirasmul laahi \'alaihi in kuntum bi Aayaatihee mu\'mineen'),
  ('en.transliteration', 6, 119, 'Wa maa lakum allaa taakuloo mimmaa zukirasmul laahi \'alaihi wa qad fassala lakum maa harrama \'alaikum illaa mad turirtum ilaih; wa inna kaseeral la yudilloona bi ahwaaa\'ihim bighairi \'ilm; inna Rabbaka Huwa a\'lamu bilmu\'tadeen'),
  ('en.transliteration', 6, 120, 'Wa zaroo zaahiral ismi wa baatinah; innal lazeena yaksiboonal ismaa sa yujzawna bimaa kaanoo yaqtarifoon'),
  ('en.transliteration', 6, 121, 'Wa laa taakuloo mimaa lam yuzkaris mullaahi \'alaihi wa innahoo lafisq; wa innash Shayaateena la yoohoona ilaaa awliyaaa\'ihim liyujaadilookum wa in ata\'tumoohum innnakum lamushrikoon'),
  ('en.transliteration', 6, 122, 'Awa man kaana maitan fa ahyainaahu wa ja\'alnaa lahoo noorany yamshee bihee fin naasi kamamm masaluhoo fiz zulumaati laisa bikhaarijim minhaa; kazaalika zuyyina lilkaafireena maa kaanoo ya\'maloon'),
  ('en.transliteration', 6, 123, 'Wa kazaalika ja\'alnaa fee kulli qaryatin akaabira mujrimeehaa liyamkuroo feehaa wa maa yamkuroona illaa bi anfusihim wa maa yash\'uroon'),
  ('en.transliteration', 6, 124, 'Wa izaa jaaa\'athum Aayatun qaaloo lan nu\'mina hatta nu\'taa misla maaa ootiya Rusulul laah; Allahu a\'almu haisu yaj\'alu Risaalatah; sa yuseebul lazeena ajramoo saghaarun \'indal laahi wa \'azaabun shadeedum bimaa kaanoo yamkuroon'),
  ('en.transliteration', 6, 125, 'Famai yuridil laahu ai yahdiyahoo yashrah sadrahoo lil islaami wa mai yurid ai yudillaho yaj\'al sadrahoo daiyiqan harajan ka annamaa yassa\' \'adu fis samaaa\'; kazaalika yaj\'alul laahur rijsa \'alal lazeena la yu\'minoon'),
  ('en.transliteration', 6, 126, 'Wa haazaa siraatu Rabbika Mustaqeemaa; qad fassalnal Aayaati liqawminy yazzakkaroon'),
  ('en.transliteration', 6, 127, 'Lahum daarus salaami \'inda Rabbihim wa huwa waliyyuhum bimaa kaanoo ya\'maloon'),
  ('en.transliteration', 6, 128, 'Wa yamwa yahshuruhum jamee\'ai yaa ma\'sharal jinni qadistaksartum minal insi wa qaala awliyaaa\'uhy minal insi Rabbanas tamta\'a ba\'dunaa biba\'dinw wa balaghnaaa ajalannal lazeee ajjalta lanaa; qaalan Naaru maswaakum khaalideena feehaaa illaa maa shaaa\'allaah; inna Rabbaka Hakeemun \'Aleem'),
  ('en.transliteration', 6, 129, 'Wa kazaalika nuwallee ba\'daz zaalimeena ba\'dam bimaa kaanoo yaksiboon'),
  ('en.transliteration', 6, 130, 'Yaa ma\'sharal jinni wal insi alam yaatikum Rusulum minkum yaqussoona \'alaikum Aayaatee wa yunziroonakum liqaaa\'a Yawmikum haazaa; qaaloo shahidnaa \'alaaa anfusinaa wa gharrat humul hayaatud dunyaa wa shahidooo \'alaa anfusihim annahum kaanoo kaafireen'),
  ('en.transliteration', 6, 131, 'Zaalika al lam yakkur Rabbuka muhlikal quraa bizulminw wa ahluhaa ghaafiloon'),
  ('en.transliteration', 6, 132, 'Wa likullin darajaatum mimmaa \'amiloo; wa maa Rabbuka bighaafilin \'ammaa ya\'maloon'),
  ('en.transliteration', 6, 133, 'Wa Rabbukal ghaniyyu zur rahmah; iny yashaaa yuz hibkum wa yastakhlif mim ba\'dikum wa yastakhlif mim ba\'dikum maa yashaaa\'u kamaaa ansha akum min zurriyyati qawmin aakhareen'),
  ('en.transliteration', 6, 134, 'Inna maa too\'adoona la aatinw wa maaa antum bimu\'jizeen'),
  ('en.transliteration', 6, 135, 'Qul yaa qawmi\' maloo \'alaa makaanatikum innee \'aamilun fasawfa ta\'lamoona man takoonu lahoo \'aaqibatud daar; innahoo laa yuflihuz zaalimoon'),
  ('en.transliteration', 6, 136, 'Wa ja\'aloo lillaahi mimmaa zara-a minal harsi walan\'aami naseeban faqaaloo haazaa lillaahi biza\'mihim wa haaza lishurakaa\'inaa famaa kaana lishurakaaa\'ihim falaa yasilu ilal laahi wa maa kaana lillaahi fahuwa yasilu ilaa shurakaaa\'ihim; saaa\'a maa yahkumoon'),
  ('en.transliteration', 6, 137, 'Wa kazaalika zaiyana likaseerim minal mushrikeena qatla awlaadihim shurakaaa\'uhum liyurdoohum wa liyalbisoo \'alaihim deenahum wa law shaaa\'al laahu maa fa\'aloohu fazarhum wa maa yaftaroon'),
  ('en.transliteration', 6, 138, 'Wa qaaloo haaziheee an\'aamunw wa harsun hijrun laa yat\'amuhaaa illaa man nashaaa\'u biza\'mihim wa an\'aamun hurrimat zuhooruhaa wa an\'aamul laa yazkuroonas mal laahi \'alaihaf tiraaa\'an \'alaih; sa yajzeehim bimaa kaanoo yaftaroon'),
  ('en.transliteration', 6, 139, 'Wa qaaloo maa fee butooni haazihil an\'aami khaalisatul lizukoorinaa wa muharramun \'alaaa azwaajinaa wa iny yakum maitatan fahum feehi shurakaaa\'; sa yajzeehim wasfahum; innahoo Hakeemun \'Aleem'),
  ('en.transliteration', 6, 140, 'Qad khasiral lazeena qatalooo awlaadahum safaham bighairi \'ilminw wa harramoo maa razaqahumul laahuf tiraaa\'an \'alal laah; qad dalloo wa maa kaanoo muhtadeen'),
  ('en.transliteration', 6, 141, 'Wa Huwal lazee ansha-a jannaatim ma\'rooshaatinw wa ghaira ma\'rooshaatinw wan nakhla wazzar\'a mukhtalifan ukuluhoo wazzaitoona warrum maana mutashaabihanw wa ghaira mutashaabih; kuloo min samariheee izaaa asmara wa aatoo haqqahoo yawma hasaadihee wa laa tusrifoo; innahoo laa yuhibbul musrifeen'),
  ('en.transliteration', 6, 142, 'Wa minal an\'aami hamoolatanw wa farshaa; kuloo mimmaa razaqakumul laahu wa laa tattabi\'oo khutuwaatish Shaitaan; innahoo lakum \'aduwwum mubeen'),
  ('en.transliteration', 6, 143, 'Samaaniyata azwaaj minad daanis naini wa minal ma\'zis nain; qul \'aazzaka raini harrama amil unsaiyayni ammash tamalat \'alaihi arhaamul unsayaini nabbi \'oonee bi\'ilmin in kuntum saadiqeen'),
  ('en.transliteration', 6, 144, 'Wa minal ibilis naini wa minal baqaris nain; qul \'aaazzakaraini harrama amil unsayaini ammash tamalat \'alaihi arhaamul unsayaini am kuntum shuhadaaa\'a iz wassaakumul laahu bihaazaa; faman azlamu mimmanif taraa \'alal laahi kazibal liyuddillan naasa bighari \'ilm; innal laaha laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 6, 145, 'Qul laaa ajidu fee maaa oohiya ilaiya muharraman \'alaa taa\'iminy yat\'amuhooo illaaa ai yakoona maitatan aw damam masfoohan aw lahma khinzeerin fa innahoo rijsun aw fisqan uhilla lighairil laahi bih; famanid turra ghaira baa ghinw wa laa \'aadin fa inna Rabbaka Ghafoorur Raheem'),
  ('en.transliteration', 6, 146, 'Wa \'alal lazeena haadoo harramnaa kulla zee zufurinw wa minal baqari walghanami harramnaa \'alihim shuh oomahumaaa illaa maa hamalat zuhooruhumaaa awil hawaayaaa aw makhtalata bi\'azm zaalika jazainaahum bibaghyihim wa innaa lasaa diqoon'),
  ('en.transliteration', 6, 147, 'Fa in kazzabooka faqur Rabbukum zoo rahmatinw waasi\'atinw waasi\'atinw wa laa yuraddu baasuhoo \'anil qawmil mujrimeen'),
  ('en.transliteration', 6, 148, 'Sayaqoolul lazeena ashrakoo law shaaa\'al laahu maaa ashraknaa wa laaa aabaa\'unaa wa laa harramnaa min shai\'; kazaalika kazzabal lazeena min qablihim hattaa zaaqoo baasanaa; qul hal \'indakum min \'ilmin fatukh rijoohu lanaa in tattabi\'oona illaz zanna wa in antum illaa takhhrusoon'),
  ('en.transliteration', 6, 149, 'Qul falillaahil hujjatul baalighatu falaw shaaa\'a lahadaakum ajma\'een'),
  ('en.transliteration', 6, 150, 'Qul halumma shuhadaaa\'akumul lazeena yash hadoona annal laaha harrama haazaa fa in shahidoo falaa tashhad ma\'ahum; wa laa tattabi\' ahwaaa\'al lazeena kazzaboo bi Aayaatinaa wallazeena laa yu\'minoona bil Aakhirati wa hum bi Rabbihim ya\'diloon'),
  ('en.transliteration', 6, 151, 'Qul ta\'aalaw atlu maa harrama Rabbukum \'alaikum allaa tushrikoo bihee shai\'anw wa bilwaalidaini ihsaananw wa laa taqtulooo aw alaadakum min imlaaq; nahnu narzuqukum wa iyyaahum wa laa taqrabul fawaahisha maa zahara minhaa wa maa batana wa laa taqtulun nafsal latee harramal laahu illaa bilhaqq; zaalikum wassaakum bihee la\'allakum ta\'qiloon'),
  ('en.transliteration', 6, 152, 'Wa laa taqraboo maalal yateemi illaa billatee hiyaa ahsanu hattaa yablugha ashuddahoo wa awful kaila walmeezaana bilqisti laa nukallifu nafsan illaa wus\'ahaa wa izaa qultum fa\'diloo wa law kaana zaa qurbaa wa bi \'ahdil laahi awfoo; zaalikum wassaakum bihee la\'allakum tazakkarron'),
  ('en.transliteration', 6, 153, 'Wa annna haazaa Siraatee mustaqeeman fattabi\'oohu wa laa tattabi\'us subula fatafarraqa bikum \'an sabeelih; zaalikum wassaakum bihee la\'allakum tattaqoon'),
  ('en.transliteration', 6, 154, 'Summa aatainaa Moosal Kitaaba tammaaman \'alal lazeee ahsana wa tafseelal likulli shai\'inw wa hudanw wa rahmatal la\'allahum biliqaaa\'i Rabbihim yu\'minoon'),
  ('en.transliteration', 6, 155, 'Wa haazaa Kitaabun anzalnaahu Mubaarakun fattabi\'oohu wattaqoo la\'al lakum urhamoon'),
  ('en.transliteration', 6, 156, 'An taqooloo innammaaa unzilal Kitaabu \'alaa taaa\'ifataini min qablinaa wa in kunnaa \'an diraasatihim laghaafileen'),
  ('en.transliteration', 6, 157, 'Aw taqooloo law annaaa unzila \'alainal kitaabu lakunnaaa ahdaa minhum; faqad jaaa\'akum baiyinatum mir Rabbikum wa hudanw wa rahmah; faman azlamu mimman kazzaba bi Aayaatil laahi wa sadaf \'anhaa; sanajzil lazeena yasdifoona \'an Aayaatinaa sooo\'al \'azaabi bimaa kaanoo yasdifoon'),
  ('en.transliteration', 6, 158, 'hal yanzuroona illaaa an taatiyahumul malaaa\'ikatu aw yaatiya Rabbuka aw yaatiya ba\'du Aayaati Rabbik; yawma yaatee ba\'du Aayaati Rabbika laa yanfa\'u nafsan eemaanuhaa lam takun aamanat min qablu aw kasabat feee eemaanihaa khairaa; qulin tazirooo innaa muntaziroon'),
  ('en.transliteration', 6, 159, 'Innal lazeena farraqoo deenahum wa kaanoo shiya\'allasta minhum fee shai\'; innamaaa amruhum ilallaahi summma yunabbi\'uhum bimaa kaanoo yaf\'aloon'),
  ('en.transliteration', 6, 160, 'man jaaa\'a bilhasanati falahoo \'ashru amsaalihaa wa man jaaa\'a bissaiyi\'ati falaa yujzaaa illaa mislahaa wa hum laa yuzlamoon'),
  ('en.transliteration', 6, 161, 'Qul innanee hadaanee Rabbeee ilaa Siraatim Mustaqeemin deenan qiyamam Millata Ibraaheema haneefaa; wa maa kaana minal mushrikeen'),
  ('en.transliteration', 6, 162, 'Qul inna Salaatee wa nusukee wa mahyaaya wa mamaatee lillaahi Rabbil \'aalameen'),
  ('en.transliteration', 6, 163, 'Laa shareeka lahoo wa bizaalika umirtu wa ana awwalul muslimeen'),
  ('en.transliteration', 6, 164, 'Qul aghairal laahi abhee Rabbanw wa Huwa Rabbu kulli shai\'; wa laa taksibu kullu nafsin illaa \'alaihaa; wa laa taziru waaziratunw wizra ukhraa; summa ilaa Rabbikum marji\'ukum fa yunabbi\'ukum bimaa kuntum feehi takhtalifoon'),
  ('en.transliteration', 6, 165, 'Wa Huwal lazee ja\'alakum khalaaa\'ifal ardi wa rafa\'a ba\'dakum fawqa ba\'din darajaatil liyabluwakum fee maaa aataakum; inna Rabbaka saree\'ul \'iqaab; wa innahoo la Ghafoorur Raheem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 6, 1, 'سب تعریف الله ہی کے لیے ہے جس نے آسمان اور زمین بنائے اور اندھیرا اوراجالا بنایا پھر بھی یہ کافر اوروں کو اپنے رب کے ساتھ برابر ٹھیراتے ہیں'),
  ('ur.ahmedali', 6, 2, 'الله وہی ہے جس نے تمہیں مٹی سے پیدا کیا پھر ایک وقت مقرر کر دیا اور اس کےہاں ایک مدت مقرر ہے تم پھر بھی شک کرتے ہو'),
  ('ur.ahmedali', 6, 3, 'اور وہی ایک الله آسمانوں میں بھی ہے اور زمین میں بھی تمہارے ظاہر اور چھپے سب حال جانتا ہے او رجانتا ہے جو کچھ تم کرتے ہو'),
  ('ur.ahmedali', 6, 4, 'ان کے رب کی نشانیوں میں سے کوئی نشانی ایسی نہیں جو ان کے سامنے آئی ہو اور انہوں نے منہ نہ موڑا ہو'),
  ('ur.ahmedali', 6, 5, 'اب جو حق ان کے پاس آیا تو اسے بھی انہوں نے جھٹلا دیا جس چیز کا اب تک وہ مذاق اڑاتے رہے ہیں عنقریب اس کے متعلق کچھ خبریں ان کو پہنچیں گی'),
  ('ur.ahmedali', 6, 6, 'کیا وہ دیکھتے نہیں کہ ہم ان سے پہلے بھی کتنی امتیں ہلاک کر دیں ہم نے انہیں زمین میں وہ اقتدار بخشا تھا جو تمہیں نہیں بخشا اور ہم نے ان پر آسمان سے خوب بارشیں برسائیں اوران کے نیچے نہریں بہا دیں پھر ہم نے انہیں ان کے گناہوں کی پاداش میں ہلاک کر دیا اور ہم نے ان کے بعد اور امتوں کو پیدا کیا'),
  ('ur.ahmedali', 6, 7, 'اور اگر ہم تم پر کوئی کاغذ پر لکھی ہوئی کتاب اتار دیتے اور لوگوں سے اپنے ہاتھوں سے چھو کر بھی دیکھ لیتے تب بھی کافر یہی کہتے ہیں کہ یہ تو صریح جادو ہے'),
  ('ur.ahmedali', 6, 8, 'اور کہتے ہیں اس پر کوئی فرشتہ کیوں نہیں اتارا گیا اور اگر ہم فرشتہ اتارے تو اب تک فیصلہ ہو چکا ہوتا پھر انہیں مہلت نہ دی جاتی'),
  ('ur.ahmedali', 6, 9, 'اور اگر ہم کسی کو فرشتہ کو رسول بنا کر بھیجتے تو وہ بھی آدمی ہی کی صورت میں ہوتا اور انہیں اسی میں شبہ میں ڈالے جس میں اب مبتلا ہیں'),
  ('ur.ahmedali', 6, 10, 'اور تم سے پہلے بھی بہت سے رسولوں کا مذاق اڑایا جا چکا ہے پھر جن لوگوں نے ان سے مذاق کیا تھا انہیں اسی عذاب نے آ گھیرا جس کا مذاق اڑاتے تھے'),
  ('ur.ahmedali', 6, 11, 'کہہ دو کہ ملک میں سیر کرو پھر دیکھو جھٹلانے والوں کا کیا انجام ہوا'),
  ('ur.ahmedali', 6, 12, 'ان سے پوچھو آسمان اور زمین میں جو کچھ ہے وہ کس کا ہے کہہ دو سب کچھ الله ہی کا ہے اس نے اپنے اوپر رحم لازم کر لیا ہے وہ قیامت کے دن تم سب کو ضرور اکھٹا کرے گا جس میں کچھ شک نہیں جو لوگ اپنی جانوں کا نقصان میں ڈال چکے وہ ایمان نہیں لاتے'),
  ('ur.ahmedali', 6, 13, 'اور الله ہی کا ہے جو کچھ رات اور دن میں پایا جاتا ہے اور وہی سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 6, 14, 'کہہ دو جو الله آُسمانوں اور زمین کا بنانے والا ہے کیا اس کے سوا کسی اور کو اپنا مددگار بناؤں اور وہ سب کو کھلاتا ہے اور اسے کوئی نہیں کھلاتا کہہ دو مجھے تو حکم دیا گیا ہے کہ سب سے پہلے اس کا فرمانبردار ہو جاؤں اور تو ہرگز مشرکوں میں شامل نہ ہو'),
  ('ur.ahmedali', 6, 15, 'کہہ دو اگر میں اپنے رب کی نافرمانی کروں تو ایک بڑے دن کےعذاب سے ڈرتا ہوں'),
  ('ur.ahmedali', 6, 16, 'جس سے اس دن عذاب ٹل گیا تو اس پر الله نے رحم کر دیا اور یہی بڑی کامیابی ہے'),
  ('ur.ahmedali', 6, 17, 'اور اگر الله تجھے کوئی تکلیف پہنچائے تواس کے سوا اور کوئی دور کرنے والا نہیں اور اگر تجھے کوئی بھلائی پہنچائے تو وہ ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 6, 18, 'اوراپنے بندوں پر اسی کا زور ہے اور وہی حکمت والا خبردار ہے'),
  ('ur.ahmedali', 6, 19, 'تو پوچھ سب سے بڑا گواہ کون ہے کہہ دو الله میرے اور تمہارے درمیان گواہ ہے اور مجھ پر یہ قرآن اتارا گیا ہے تاکہ تمہیں اس کے ذریعہ سے ڈراؤں اور جس جس کو یہ قرآن پہنچے کیا تم گواہی دیتے ہو کہ الله کے ساتھ اور بھی کوئی معبود ہیں کہہ دو میں تو گواہی نہیں دیتا کہہ دو وہی ایک معبود ہے اور میں تمہارے شرک سے بیزار ہوں'),
  ('ur.ahmedali', 6, 20, 'جنہیں ہم نے کتاب دی ہے وہ اسے پہچانتے ہیں جیسے اپنے بیٹوں کو پہچانتے ہیں اور جو لوگ اپنی جانوں کو نقصان میں ڈال چکے ہیں وہی ایمان نہیں لاتے'),
  ('ur.ahmedali', 6, 21, 'جو شخص الله پر بہتان باندھے یا اس کی آیتوں کو جھٹلائے اس سے زیادہ ظالم کون ہے بے شک ظالم نجات نہیں پائیں گے'),
  ('ur.ahmedali', 6, 22, 'اور جس دن ہم ان سب کو جمع کریں گے پھر ان لوگوں سے کہیں گے جنہوں نے شرک کیا تھا تمہارے شریک کہاں ہیں جن کاتمہیں دعویٰ تھا'),
  ('ur.ahmedali', 6, 23, 'پھر سوائے اس کے ان کا اورکوئی بہانہ نہ ہوگا کہیں گے ہمیں الله اپنے پرودگار کی قسم ہے کہ ہم تو مشرک نہیں تھے'),
  ('ur.ahmedali', 6, 24, 'دیکھو اپنے اوپر انہوں نے کیسا جھوٹ بولا اور جو باتیں وہ بنایا کرتا تھے وہ سب غائب ہو گئیں'),
  ('ur.ahmedali', 6, 25, 'اور بعض ان میں سے تیری طرف کان لگائے رہتے ہیں اور ہم نے ان کے دلوں پر پردے ڈال رکھے ہیں جس کی وجہ سے وہ کچھ نہیں سمجھتے اور ان کے کانو ں میں گرانی ہے اور اگر یہ تمام نشانیاں بھی دیکھ لیں تو بھی ان پر ایمان نہ لادیں گے جب وہ تمہارے پاس آ کر تم سے جھگڑتے ہیں تو کافر کہتے ہیں کہ یہ تو پہلے لوگو ں کی کہانیاں ہی ہیں'),
  ('ur.ahmedali', 6, 26, 'اور یہ لوگ اس سے روکتے ہیں اور خود بھی اس سے دور بھاگتے ہیں اور انہیں ہلاک کر تے مگر اپنے آپ کو اور سمجھتے نہیں'),
  ('ur.ahmedali', 6, 27, 'کاش تم اس وقت کی حالت دیکھ سکتے جب وہ دوزخ کے کنارے کھڑے کیے جائیں گے اس وقت کہیں گے کاش کوئی صورت ایسی ہو کہ ہم واپس بھیج دیے جائیں اور اپنے رب کی نشانیوں کو نہ جھٹلائیں اور ایمان والوں میں ہوجائیں'),
  ('ur.ahmedali', 6, 28, 'بلکہ جس چیز کو اس سے پہلے چھپاتے تھے وہ ظاہر ہو گئی اور اگر یہ واپس بھیج دیے جائیں تب بھی وہی کام کریں گے جن سے انہیں منع کیا گیا تھا اور یقیناً یہ جھوٹے ہیں'),
  ('ur.ahmedali', 6, 29, 'اور کہتےہیں اس دنیا کی زندگی کے سوا ہمارے لیے اور کوئی زندگی نہیں اور ہم اٹھائے نہیں جائیں گے'),
  ('ur.ahmedali', 6, 30, 'اور کاش کہ تو دیکھے جس وقت وہ اپنے رب کے سامنے کھڑے کیے جائیں گے وہ فرمائے گا کیا یہ سچ نہیں کہیں گے ہاں ہمیں رب کی قسم ہے فرمائے گا تو اپنے کفر کے بدلے عذاب چکھو'),
  ('ur.ahmedali', 6, 31, 'وہ لوگ تباہ ہوئے جنہوں نے اپنے رب کی ملاقات کو جھٹلایا یہاں تک کہ جب ان پر قیامت اچانک آ پہنچے گی تو کہیں گے اے افسوس ہم نے اس میں کیسی کوتاہی کی اور وہ اپنے بوجھ اپنے پیٹوں پر اٹھائیں گےخبرداروہ برا بوجھ ہے جسے وہ اٹھائیں گے'),
  ('ur.ahmedali', 6, 32, 'اور دنیا کی زندگی تو ایک کھیل اور تماشہ ہے اور البتہ آخرت کا گھر ان لوگوں کے لیے بہتر ہے جو پرہیزگار ہوئے کیا تم نہیں سمجھتے'),
  ('ur.ahmedali', 6, 33, 'ہمیں معلوم ہے کہ ان کی باتیں تمہیں غم میں ڈالتی ہیں سو وہ تجھے نہیں جھٹلاتے بلکہ یہ ظالم الله کی آیتوں کا انکار کرتے ہیں'),
  ('ur.ahmedali', 6, 34, 'اور بہت سے رسول تم سے پہلے جھٹلائے گئے پھر انہوں نےجھٹلائے جانے پر صبر کیا اور ایذا دیے گئے یہاں تک کہ ان کو ہماری مدد پہنچی اور الله کے فیصلے کوئی بدل نہیں سکتا اور تمہیں پیغمبروں کے حالات کچھ پہنچ چکے ہیں'),
  ('ur.ahmedali', 6, 35, 'اور اگر ان کا منہ پھیرنا تم پر گراں ہو رہا ہے پھر اگر تم سے ہو سکے تو کوئی سرنگ زمین میں تلاش کر یا آسمان سے سیڑھی لگا پھر ان کے پاس کوئی معجزہ لا اور اگر الله چاہتا تو سب کو سیدھی راہ پر جمع کر دیتا سو تو نادانوں میں سے نہ ہو'),
  ('ur.ahmedali', 6, 36, 'وہی مانتے ہیں جو سنتے ہیں اور الله مردوں کو زندہ کرے گا پھر اس کی طرف لوٹائے جائیں گے'),
  ('ur.ahmedali', 6, 37, 'اور کہتے ہیں اس کے رب کی طرف سے اس پر کوئی نشانی کیوں نہیں اتری کہہ دو الله اس پر قادر ہے کہ نشانی اتارے اور لیکن ان میں سے اکثر نہیں جانتے'),
  ('ur.ahmedali', 6, 38, 'اور کوئی چلنے والا زمین میں نہیں اور نہ کوئی پرندہ کہ اپنے دوبازؤں سے اڑ تا ہے مگر یہ تمہاری ہی طرح کی جماعتیں ہیں ہم نے ان کی تقدیر کےلکھنے میں کوئی کسرنہیں چھوڑی پھر سب اپنے رب کے سامنے جمع کیے جائیں گے'),
  ('ur.ahmedali', 6, 39, 'اور جو لوگ ہماری آیتوں کو جھٹلاتے ہیں وہ بہرےاور گونگے ہیں اندھیروں میں ہیں الله جسے چاہے گمراہ کر دے اور جسے چاہے سیدھی راہ پر ڈال دے'),
  ('ur.ahmedali', 6, 40, 'کہہ دو دیکھو تو سہی اگر تم پرخدا کا عذاب آئے یا تم پر قیامت ہی آ جائے تو کیا خدا کے سوا کسی اور کو پکارو گے اگر تم سچے ہو'),
  ('ur.ahmedali', 6, 41, 'بلکہ اسی کو پکارتے ہو پھر اگر وہ چاہتا ہے تو اس مصیبت کو دور کر دیتا ہے جس کے لیے اسے پکارتے ہو اور جنہیں تم الله کا شریک بناتے ہو انہیں بھول جاتے ہو'),
  ('ur.ahmedali', 6, 42, 'اور ہم نے تجھ سے پہلے بہت سی امتوں کے ہاں رسول بھیجےتھے پھر ہم نے انہیں سختی اور تکلیف میں پکڑا تاکہ وہ عاجزی کریں'),
  ('ur.ahmedali', 6, 43, 'پھر کیوں نہ ہوا کہ جب ان پر ہمارا عذاب آیا تو عاجزی کرتے لیکن ان کے دل سخت ہو گئے اور شیطان نے انہیں وہ کام آراستہ کر دکھائے جو وہ کرتے تھے'),
  ('ur.ahmedali', 6, 44, 'پھر جب وہ اس نصیحت کو بھول گئے جو ان کو کی گئی تھی تو ہم نے ان پر ہر چیز کے دروازے کھول دیئے یہاں تک کہ جب وہ ان چیزوں پر خوش ہو گئےجو انہیں دی گئیں تھیں ہم نے انہیں اچانک پکڑ لیا وہ اس وقت نا امید ہوکر کر رہ گئے'),
  ('ur.ahmedali', 6, 45, 'پھر ان ظالموں کی جڑ کاٹ دی گئی اور الله ہی کے لیے سب تعریف ہے جو سارے جہان کا پالنے والا ہے'),
  ('ur.ahmedali', 6, 46, 'ان سے کہہ دو دیکھو تو سہی اگر الله ہی کے لیے سب تعریف ہے جو سارے جہان کا پالنے والا ہےاگر الله تمہارے کان اور آنکھیں چھین لے اور تمہارے دلوں پر مہر لگا دے تو الله کے سوا کوئی ایسا رب ہے جو تمہیں یہ چیزیں لادے دیکھ ہم کیوں کر طرح طرح کی نشانیاں بیان کرتے ہیں پھر بھی یہ منہ موڑتے ہیں'),
  ('ur.ahmedali', 6, 47, 'کہہ دو اگرتم پر الله کا عذاب اچانک یا ظاہر آ جائے تو ظالموں کے سوا اور کون ہلاک ہو گا'),
  ('ur.ahmedali', 6, 48, 'اور ہم پیغبروں کو صرف اس لیے بھیجا کرتے ہیں کہ وہ بشارت دیں اور ڈرائیں پھر جو شخص ایمان لے آوے اور اپنی اصلاح کر لے سو ان پر کوئی ڈر نہ ہوگا اور نہ وہ غم کھائيں گے'),
  ('ur.ahmedali', 6, 49, 'اور جنہوں نے ہماری آیتوں کو جھٹلایا انہیں عذاب پہنچے گا اس لیے کہ وہ نافرمانی کرتے تھے'),
  ('ur.ahmedali', 6, 50, 'کہہ دو میں تم سے یہ نہیں کہتا کہ میرے پاس الله کے خزانے ہیں اور نہ میں غیب کا علم رکھتا ہوں اور نہ یہ کہتا ہوں کہ میں فرشتہ ہوں میں تو صرف اس وحی کی پیروی کرتا ہوں جو مجھ پر نازل کی جاتی ہے کہہ دو کیا اندھا اور آنکھوں والا دونوں برابر ہو سکتے ہیں کیا تم غور نہیں کرتے'),
  ('ur.ahmedali', 6, 51, 'اور اس قرآن کے ذریعے سے ان لوگو ں کو ڈرا جنہیں اس کا ڈر ہے کہ وہ اپنے رب کے سامنے جمع کیے جائیں گے اس طرح پر کہ الله کے سوا ان کوئی مددگار اور سفارش کرنے والا نہ ہو گا تاکہ وہ پرہیزگار ہوجائیں'),
  ('ur.ahmedali', 6, 52, 'اور جو لوگ اپنے رب کو صبح و شام پکارتے ہیں انہیں اپنے سے دور نہ کر جو الله کی رضا چاہتے ہیں تیرے ذمہ ان کا کوئی حساب نہیں ہے اور نہ تیرا کوئی حساب ان کے ذمہ اگر تو نے انہیں دو ہٹا یا پس تو بے انصافوں میں سے ہوگا'),
  ('ur.ahmedali', 6, 53, 'اور اسی طرح ہم نے بعض کو بعض کے ذریعہ سے آزمایا ہے تاکہ یہ لوگ کہیں کیا یہی ہیں ہم میں سے جن پر الله نے فضل کیا ہے کیا الله شکر گزارو ں کو جاننے والا نہیں ہے'),
  ('ur.ahmedali', 6, 54, 'اور ہماری آیتوں کو ماننے والے جب تیرے پاس آئیں تو کہہ دو کہ تم پر سلام ہے تمہارے رب نے اپنے ذمہ رحمت لازم کی ہےجو تم میں سے ناواقفیت سے برائی کرے پھر اس کے بعد توبہ کرے اور نیک ہو جائے تو بےشک وہ بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 6, 55, 'اور اسی طرح ہم آیتوں کو تفصیل سے بیان کرتے ہیں اور تاکہ گنہگاروں کا راستہ واضح ہو جائے'),
  ('ur.ahmedali', 6, 56, 'کہہ دو مجھے منع کیا گیا ہے اس سے کہ میں بندگی کروں ان کی جنہیں تم الله کے سوا پکارتے ہو کہہ دو میں تمہاری خواہشات کے پیچھے نہیں چلتا کیوں کہ میں اس وقت گمراہ ہو جاؤں گا اور ہدایت پانے والوں میں سے نہ رہوں گا'),
  ('ur.ahmedali', 6, 57, 'کہہ دو میرے پاس تو میرے رب کی طرف سے ایک دلیل ہے اور تم اس کو جھٹلاتے ہو جس چیز کو تم جلدی چاہتے ہو وہ میرے پاس نہیں ہے الله کے سوا اور کسی کا حکم نہیں ہے وہ حق بیان کرتا ہے اور وہ بہترین فیصلہ کرنے والا ہے'),
  ('ur.ahmedali', 6, 58, 'کہہ دو اگر میرے پاس وہ چیز ہوتی جس کی تم جلدی کر رہے ہو تو اس معاملہ میں فیصلہ ہوگیا ہو تا جو میرے اور تمہارے درمیان ہے اور الله ظالموں کو خوب جانتا ہے'),
  ('ur.ahmedali', 6, 59, 'اور اسی کے پاس غیب کی کنجیاں ہیں جنہیں اس کےسوا کوئی نہیں جانتا جو کچھ جنگل اور دریا میں ہے وہ سب جانتا ہے اور کوئی پتہ نہیں گرتا مگر وہ اسے بھی جانتاہے اور کوئی دانہ زمین کے تاریک حصوں میں نہیں پڑتا اور نہ کوئی تر اور خشک چیز ہے مگر یہ سب کچھ کتاب روشن میں ہیں'),
  ('ur.ahmedali', 6, 60, 'اور وہ وہی ہے جو تمہیں رات کو اپنے قبضے میں لے لیتا ہے اور جو کچھ تم دن میں کر چکے ہو وہ جانتا ہے پھر تمہیں دن میں اٹھا دیتا ہے تاکہ وہ وعدہ پورا ہو جو مقرر ہو چکا ہے پھر اسی کی طرف تم لوٹائے جاؤ گے پھر تمہیں خبر دے گا اس کی جو کچھ تم کرتے تھے'),
  ('ur.ahmedali', 6, 61, 'اور وہی اپنے بندوں پر غالب ہے اور تم پر نگہبان بھیجتا ہے یہاں تک کہ جب تم میں سے کسی کو موت آ پہنچتی ہے تو ہمارے بھیجے ہوئے فرشتے اسے قبضہ میں لے لیتے اور وہ ذرا کوتاہی نہیں کرتے'),
  ('ur.ahmedali', 6, 62, 'پھر الله کی طرف پہنچائیں جائیں گے جو ا نکا سچا مالک ہے خوب سن لو کہ فیصلہ الله ہی کا ہوگا اور بہت جلدی حساب لینے والا ہے'),
  ('ur.ahmedali', 6, 63, 'کہہ دو تمہیں جنگل اور دریا کے اندھیروں سے کون بچا تا ہے جب اسے عاجزی سے اور چھپا کر پکارتے ہوکہ اگر ہمیں اس آفت سے بچا لے تو البتہ ہم ضرور شکر گزار کرنے والوں میں سے ہوں گے'),
  ('ur.ahmedali', 6, 64, 'کہہ دو الله تمہیں اس سے اور ہر سختی سے بچا تا ہے تم پھر بھی شرک کرتے ہو'),
  ('ur.ahmedali', 6, 65, 'کہہ دو وہ اس پر قادر ہے کہ تم پر عذاب اوپر سے بھیجے یا تمہارے پاؤں کے نیچے سے یا تمہیں مختلف فرقے کر کے ٹکرا دے اور ایک کودوسرے کی لڑائی کا مزہ چکھا دے دیکھو ہم کس طرح مختلف طریقوں سے دلائل بیان کرتے ہیں تاکہ وہ سمجھ جائیں'),
  ('ur.ahmedali', 6, 66, 'اور تیری قوم نے اسے جھٹلایا ہے حالانکہ وہ حق ہے کہہ دو میں تمہارا ذمہ دار نہیں بنایا گیا'),
  ('ur.ahmedali', 6, 67, 'ہر خبر کے ظاہر ہونے کا ایک وقت مقرر ہے اور عنقریب جان لو گے'),
  ('ur.ahmedali', 6, 68, 'اور جب تو ان لوگو ں کو دیکھے جو ہماری آیتو ں میں جھگڑتے ہیں تو ان سے الگ ہو جا یہاں تک کہ کسی اور بات میں بحث کرنے لگیں اور اگر تجھے شیطان بھلا دے تو یاد آجانے کے بعد ظالموں کے پاس نہ بیٹھ'),
  ('ur.ahmedali', 6, 69, 'اور جھگڑنے والوں کے حساب میں سے پرہیزگاروں کے ذمہ کوئی چیز نہیں لیکن نصیحت کرنی ہے شاید کہ وہ ڈر جائیں'),
  ('ur.ahmedali', 6, 70, 'اور انہیں چھوڑ دو جنہوں نے اپنے دین کو کھیل اور تماشا بنا رکھا ہے اور دنیاکی زندگی نے انہیں دھوکہ دیا ہے اور انہیں قرآن سے نصیحت کرتا تاکہ کوئی اپنے کیے میں گرفتار نہ ہو جائے کہ اس کے لیے الله کے سوا کوئی دوست اور سفارش کرنے والا نہ ہوگا اور اگر دنیا بھر کا معاوضہ بھی دے گا تب بھی اس سے نہ لیا جائے گا یہی وہ لوگ ہیں جو اپنے کیے میں گرفتار ہوئے ان کے پینے کے لیے گرم پانی ہوگا اور ان کے کفر کے بدلہ میں دردناک عذاب ہو گا'),
  ('ur.ahmedali', 6, 71, 'انہیں کہہ دوکہ کیا ہم الله کے سوا انہیں پکاریں جو ہمیں نہ نفع پہنچا سکیں اور نہ نقصان دے سکیں اور کیا ہم الٹے پاؤں پھر جائیں اس کے بعد کہ الله نے ہمیں سیدھی راہ دکھائی ہے اس شخص کی طرح جسےجنگل میں جنوں نے راستہ بھلا دیا ہو جب کہ وہ حیران ہو اس کے ساتھی اسے راستے کی طرف بلاتے ہوں کہ ہمارے پاس چلا آ کہہ دو الله نے جو راہ بتلائی وہی سیدھی ہے اور ہمیں حکم دیا گیا ہے کہ ہم پروردگار عالم کے تابع رہیں'),
  ('ur.ahmedali', 6, 72, 'اور یہ کہ نماز قائم رکھو اور الله سے ڈرتے رہو وہی ہے جس کے سامنے اکھٹے کیے جاؤ گے'),
  ('ur.ahmedali', 6, 73, 'اور وہی ہے جس نے آسمانوں اورزمین کو ٹھیک طور پر بنایا ہے اور جس دن کہے گا کہ ہو جا تو وہ ہو جائے گا اس کی بات سچی ہے جس دن صورمیں پھونکا جائے گاتو اسی کی بادشاہی ہو گی چھپی اور ظاہر باتوں کا جاننے والا ہے اور وہی حکمت والا خبردار ہے'),
  ('ur.ahmedali', 6, 74, 'اور یاد کر جب ابراہیم نے اپنے باپ آزر سے کہا کیا بتوں کو خدا جانتاہے میں تجھے اور تیرے قوم کو صریح گمراہی میں دیکھتا ہوں'),
  ('ur.ahmedali', 6, 75, 'اور ہم نے اسی طرح ابراھیم کو آسمانوں اور زمین کے عجائبات دکھائے ابور تاکہ وہ یقین کرنے والوں میں سے ہو جائے'),
  ('ur.ahmedali', 6, 76, 'پھر جب رات نے اس ہر اندھیرا کیا اس نے ایک ستارہ دیکھا کہا یہ میرا رب ہے پھر جب وہ غائب ہو گیا تو کہا میں غائب ہونے والوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 6, 77, 'پھر جب چاند کو چمکتا ہوا دیکھا کہا یہ میرا رب ہے پھر جب وہ غائب ہو گیا تو کہا اگر مجھے میرا رب ہدایت نہ کرے گا تو میں ضرور گمراہوں میں سے ہوجاؤں گا'),
  ('ur.ahmedali', 6, 78, 'پھر جب آفتاب کو چمکتاہوا دیکھا کہا یہی میرا رب ہے یہ سب سے بڑا ہے پھر جب وہ غائب ہو گیا کہا اے میری قوم میں ان سے بیزار ہوں جنہیں تم الله کا شریک بناتے ہو'),
  ('ur.ahmedali', 6, 79, 'سب سے یک سو ہو کر میں نے اپنے منہ کو اسی کی طرف متوجہ کیا جس نے آسمان اور زمین بنائی اور میں شرک کرنے والوں میں سے نہیں ہوں'),
  ('ur.ahmedali', 6, 80, 'اور اس کی قوم نے اس سے جھگڑا کیا اس نے کہا کیا تم مجھ سے الله کے ایک ہونے میں جھگڑتے ہو اور اس نے میری رہنمائی کی ہے اور جنہیں تم شریک کرتے ہو میں ان سے نہیں ڈرتا مگر یہ کہ میرا رب مجھے کوئی تکلیف پہنچانا چاہے میرے رب نے علم کے لحاظ سے سب چیزوں پر احاطہ کیا ہوا ہے کیا تم سوچتے نہیں'),
  ('ur.ahmedali', 6, 81, 'اور تمہارے شریکوں سے کیوں ڈروں حالانکہ تم اس بات سے نہیں ڑرتے کہ الله کا شریک ٹھیراتے ہو اس چیز کو جس کی الله نے تم پر کوئی دلیل نہیں اتاری اگر تم کو کچھ سمجھ ہے تو (بتاؤ) دونوں جماعتوں میں سے امن کا زیادہ مستحق کون ہے'),
  ('ur.ahmedali', 6, 82, 'جو لوگ ایمان لائے اور انہوں نے اپنے ایمان میں شرک نہیں ملایا امن انہیں کے لیے ہے اور وہی راہ راست پر ہیں'),
  ('ur.ahmedali', 6, 83, 'اور یہ ہماری دلیل ہے کہ ہم نے ابراہیم کو اس کی قوم کے مقابلہ میں دی تھی ہم جس کے چاہیں درجے بلند کرتے ہیں بے شک تیرا رب حکمت والا جاننے والا ہے'),
  ('ur.ahmedali', 6, 84, 'اور ہم نے ابراھیم کو اسحاق اور یعقوب بخشا ہم نے سب کو ہدایت دی اور اس سے پہلے ہم نے نوح کو ہدایت دی اور اس کی اولاد میں سے داؤد اور سلیمان اور ایوب اور یوسف اور موسیٰ اور ہارون ہیں اور اسی طرح ہم نیکو کاروں کو بدلہ دیتے ہیں'),
  ('ur.ahmedali', 6, 85, 'اور زکریا اور یحییٰ اور عیسیٰ اور الیاس سب نیکو کاروں سے ہیں'),
  ('ur.ahmedali', 6, 86, 'اور اسماعیل اورالیسع اوریونس اور لوط او رہم نے سب کو سارے جہان والوں پر بزرگی دی'),
  ('ur.ahmedali', 6, 87, 'اور ان کے باپ دادوں اور ان کی اولاد اور ان کے بھائیوں میں سے بعضوں کو ہم نے ہدایت دی اور ہم نے انہیں پسند کیا اور سیدھی راہ پر چلایا'),
  ('ur.ahmedali', 6, 88, 'یہ الله کی ہدایت ہے اپنے بندوں کو جسے چاہے اس پر چلاتا ہے اور اگر یہ لوگ شرک کرتے تو البتہ جو کچھ انہوں نے کیا تھا سب کچھ ضائع ہو جاتا'),
  ('ur.ahmedali', 6, 89, 'یہی لوگ تھے جنہیں ہم نے کتاب اور شریعت اور نبوت دی تھی پھر اگر مکہ والے ان باتو ں کو نہ مانیں تو ہم نے ان باتو ں کے ماننے کے لیے ایسے لوگ مقرر کر دیے جوان کے منکر نہیں ہیں'),
  ('ur.ahmedali', 6, 90, 'یہ وہ لوگ تھے جنہیں الله نے ہدایت دی سو تو ان کے طریقہ پر چل کہہ دو میں تم سے اس پر کوئی مزدوری نہیں مانگتا یہ تو جہان والوں کے لیے محض نصیحت ہے'),
  ('ur.ahmedali', 6, 91, 'اور انہوں نے الله کو صحیح طور پر نہیں پہچانا جب انہوں نے کہا الله نے کسی انسان پر کوئی چیز نہیں اتاری تھی جو لوگو ں کے واسطے روشنی اور ہدایت تھی جسے تم نے ورق ورق کر کےد کھلا یا اوربہت سی باتو ں کو چھپا رکھا اور تمہیں وہ چیزیں سکھائیں جنہیں تم اور تمہارے باپ دااد نہیں جانتے تھے تو کہہ دو الله ہی نے اتاری تھی پھرانہیں چھوڑ دو کہ اپنی بحث میں کھیلتے رہیں'),
  ('ur.ahmedali', 6, 92, 'اور یہ کتاب جسے ہم نے اتارا ہےبرکت والی ہے ان کی تصدیق کرنے والی ہے جو اس سے پہلے تھیں اور تاکہ تو مکہ والوں کو اور اس کے آس پاس والوں کو ڈرائے اور جو لوگ آخرت پر یقین رکھتے ہیں وہی اس پر ایمان لاتے ہیں اور وہی اپنی نماز کی حفاظت کرتے ہیں'),
  ('ur.ahmedali', 6, 93, 'اور اس سے زیادہ ظالم کون ہو گا جو الله پربہتان باندھے یا یہ کہے کہ مجھ پر وحی نازل ہوئی ہے حالانکہ اس پر وحی نہ اتری ہو اور جو کہے میں بھی ایسی چیز اتار سکتا ہوں جیسی کہ الله نے اتاری ہے اور اگر تو دیکھے جس وقت ظالم موت کی سختیوں میں ہوں گے اور فرشتے اپنے ہاتھ بڑھانے والےہوں گے کہ اپنی جانوں کو نکالو آج تمہیں ذلت کا عذاب ملے گا اس سبب سے کہ تم الله پر جھوٹی باتیں کہتے تھے اور اس کی آیتوں کے ماننے سے تکبر کرتے تھے'),
  ('ur.ahmedali', 6, 94, 'اور البتہ تم ہمارے پاس ایک ایک ہو کر آ گئے ہو جس طرح ہم نے تمہیں پہلی دفعہ پیدا کیا تھا اور جو کچھ ہم نے تمہیں دیا تھا وہ اپنے پیچھے ہی چھوڑ آئے ہو اور تمہارے ساتھ ان کی سفارش کرنے والوں کو نہیں دیکھتے جنہیں تم خیال کرتے تھے کہ وہ تمہارے معاملےمیں شریک ہیں تمہارا آپس میں قطع تعلق ہو گیا ہے اور جو تم خیال کرتے تھے وہ سب جاتا رہا'),
  ('ur.ahmedali', 6, 95, 'بے شک الله دانے اور گٹھلی کا پھاڑنے والا ہے مردہ سے زندہ کو نکالتا ہے اور زندہ سے مردہ نکالنے والا ہے الله یہی ہے پھر کدھر الٹے پھرے جا رہے ہو'),
  ('ur.ahmedali', 6, 96, 'وہ صبح کا نکالنے والا ہے اور اس نے آرام کے لیے رات بنائی اسی نے چاند اور سورج کا حساب مقرر کیا ہے یہ غالب جاننے والے کا اندازہ ہے'),
  ('ur.ahmedali', 6, 97, 'اور اسی نے تمہارے لیے ستارے بنائے ہیں تاکہ ان کے ذریعے سے جنگل اوردریا کےاندھیروں میں راستہ معلوم کر سکو تحقیق ہم نے کھول کر نشانیاں بیان کر دی ہیں ان لوگو ں کے لیے جو جانتے ہیں'),
  ('ur.ahmedali', 6, 98, 'اور الله وہی ہے جس نے ایک شخص سے تم سب کو پیدا کیا پھر ایک تو تمہارا ٹھکانا ہے اور ایک امانت رکھے جانےکی جگہ تحقحق ہم نے کھول کر نشانیاں بیان کر دی ہیں ان کے لیے جو سوچتے ہیں'),
  ('ur.ahmedali', 6, 99, 'اور اسی نے آسمان سے پانی اتارا پھر ہم نے اس سے ہر چیز اگنے والی نکالی پھر ہم نے اس سے سبز کھیتی نکالی جس سے ہم ایک دوسرے پرچڑھے ہوئے دانے نکالتے ہیں اور کھجور کے شگوفوں میں سے پھل کے جھکے ہوئے گچھے اور انگور اور زیتون اور انار کے باغ آپس میں ملتے جلتے اور جدا جدا بھی ہر ایک درخت کے پھل کو دیکھو جب وہ پھل لاتا ہے اور اس کے پکنے کو دیکھو ان چیزوں میں ایمان والوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 6, 100, 'اور اللہ کے شریک جنوں کو ٹھیراتے ہیں حالانکہ اس نے انہیں پیدا کیا ہے اور جہالت سے اس کے لیے بیٹے اور بیٹیاں تجویز کرتے ہیں وہ پاک ہے اور ان باتوں سے بھی بلند ہے جو وہ بیان کرتے ہیں'),
  ('ur.ahmedali', 6, 101, 'آسمانوں اور زمین کو از سر نو پیدا کرنے والا ہے اس کا بیٹا کیوں کر ہو سکتا ہے حالانکہ اس کی کوئی بیوی نہیں اور اس نے ہر چیز کو بنایاہے اور وہ ہر چیز کو جاننے والا ہے'),
  ('ur.ahmedali', 6, 102, 'یہی اللہ تمہارا رب ہے اس کے سوائے اورکوئی معبود نہیں ہر چیز کا پیدا کرنے والا ہے پس اسی کی عبادت کرو اور وہ ہر چیز کا کا رساز ہے'),
  ('ur.ahmedali', 6, 103, 'اسے آنکھیں نہیں دیکھ سکتیں اور وہ آنکھوں کو دیکھ سکتا ہے اوثر وہ نہایت باریک بین خبردار ہے'),
  ('ur.ahmedali', 6, 104, 'تحقیق تمہارے ہاں تمہارے رب کی طرف سے نشانیاں آ چکی ہیں پھر جس نے دیکھ لیا تو خود ہی نفع اٹھایا اور جو اندھا رہا سو اپنا نقصان کیا اور میں تمہارا نگہبان نہیں ہوں'),
  ('ur.ahmedali', 6, 105, 'اور اسی طرح ہم مختلف طریقوں سے دلائل بیان کرتے ہیں تاکہ وہ کہیں کہ تو نے کسی سے پڑھا ہے اور تاکہ ہم سمجھداروں کے لیے واضح کر دیں'),
  ('ur.ahmedali', 6, 106, 'تو اس کی تابعداری کر جو تیرےرب کی طرف سے وحی کی گئی ہے اس کے سوا اور کوئی معبود نہیں اور مشرکوں سے منہ پھیرے'),
  ('ur.ahmedali', 6, 107, 'اور اگر الله چاہتا تو وہ شرک نہ کرتے اور ہم نے تجھے ا ن پر نگہبان نہیں بنایا اور تو ان کا ذمہ دار نہیں ہے'),
  ('ur.ahmedali', 6, 108, 'اور جن کی یہ الله کے سوا پرستش کر تےہیں انہیں برا نہ کہوورنہ وہ بے سمجھی سے زیادتی کرکے الله کو برا کہیں گے اس طرح ہر ایک جماعت کی نظر میں ان کے اعمال کوہم نے آراستہ کر دیا ہے پھر ان سب کو اپنے رب کی طرف لوٹ کر آنا ہے تب وہ انہیں بتلائے گا جو کچھ کیا کرتے تھے'),
  ('ur.ahmedali', 6, 109, 'اور وہ الله کے نام کی پکی قسمیں کھاتے ہیں کہ اگر ان کے پاس کوئی نشانی آئے تو اس پر ضرور ایمان لاویں گے ان سے کہہ دو کہ نشانیاں تو اللہ کے ہاں ہیں اور تمہیں اے مسلمانو کیا خبر ہے کہ جب نشانیاں آہیں گی تو یہ لوگ ایمان لے ہی آئیں گے'),
  ('ur.ahmedali', 6, 110, 'اور ہم بھی ان کے دلوں کو اور ان کی نگاہوں کو پھیر دیں گے جس طرح یہ اس پر پہلی دفعہ ایمان نہیں لاتے اور ہم انہیں ان کی سرکشی میں حیران رہنے دیں گے'),
  ('ur.ahmedali', 6, 111, 'اور اگر ہم ان پر فرشتے بھی اتار دیں اور ان سے مردے باتیں بھی کریں اور ان کے سامنے ہم ہر چیز کو زندہ بھی کر دیں تو بھی یہ لوگ ایمان لانے والے نہیں مگر یہ کہ الله چاہے لیکن اکثر ان میں سے جاہل ہیں'),
  ('ur.ahmedali', 6, 112, 'اور اسی طرح ہم نے ہر نبی کے لیے شریر آدمیوں اور جنوں کو دشمن بنایا جو کہ ایک دوسرے کو طمع کرہوئی باتیں فریب دینے کے لیے سکھاتے ہیں اور اگر تیرا رب چاہتا تو یہ کام نہ کرتے سو تو انہیں اور جوجھوٹ بناتے ہیں اسے چھوڑ دے'),
  ('ur.ahmedali', 6, 113, 'اور تاکہ ان طمع کی ہوئی باتوں کی طرف ان لوگوں کے دل مائل ہوں جنہیں آخرت پر یقین نہیں اور تاکہ وہ لوگ ان باتو ں کو پسند کریں اور تاکہ وہ کریں جو برے کام وہ کر رہے ہیں'),
  ('ur.ahmedali', 6, 114, 'کیا میں الله کےسوا اور کسی کو منصف بناؤں حالانکہ اس نے تمہاری طرف ایک واضح کتاب اتاری ہے اور جنہیں ہم نے کتاب دی ہے وہ جانتے ہیں کہ یہ ٹھیک تیرے رب کی طرف سے نازل ہوئی ہے پس تو شک کرنے والوں میں سے نہ ہو'),
  ('ur.ahmedali', 6, 115, 'اور تیرے رب کی باتیں سچائی اور انصاف کی انتہائی حد تک پہنچی ہوئی ہیں اس کی باتو ں کو کوئی بدل نہیں سکتا اور وہ سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 6, 116, 'اور اگر تو کہا مانے گا اکثر ان لوگو ں کا جو دنیا میں ہیں تو تجھے الله کی راہ سے ہٹا دیں گے وہ تو اپنے خیال پر چلتے اور قیاس آرائیاں کرتے ہیں'),
  ('ur.ahmedali', 6, 117, 'تیرا رب خوب جانتا ہے اسے جو اس کے راہ سے ہٹ جاتا ہے اور سیدھے راستہ پر چلنے والوں کو بھی خوب جانتا ہے'),
  ('ur.ahmedali', 6, 118, 'سو تم اس جانوروں میں سے کھاؤ جس پر الله کا نام لیا گیا ہے اگر تم اس کے حکموں پر ایمان لانے والے ہو'),
  ('ur.ahmedali', 6, 119, 'کیا وجہ ہے کہ تم وہ چیز نہ کھاؤ جس پر الله کا نام لیا گیا ہو حالانکہ وہ واضح کر چکا ہے جو کچھ اس نے تم پر حرام کیا ہے ہاں مگر وہ چیز جس کی طرف تم مجبور ہو جاؤ اوربہت سے لوگ بےعلمی کے باعث اپنے خیالات کے باعث اپنے خیالات کی بناء پر لوگو ں کو بہکاتے ہیں تیرا رب حد سے بڑھنے والوں کو خوب جانتا ہے'),
  ('ur.ahmedali', 6, 120, 'تم ظاہری اورباطنی سب گناہ چھوڑ دو بے شک جو لوگ گناہ کرتے ہیں عنقریب اپنے کیے کی سزا پائیں گے'),
  ('ur.ahmedali', 6, 121, 'اور جس چیز پر الله کا نام نہیں لیا گیا اس میں سے نہ کھاؤ اور بے شک یہ کھانا گناہ ہے اور بے شک شیطان اپنے دوستوں کے دلو ں میں ڈالتے ہیں تاکہ وہ تم سے جھگڑیں اور اگر تم نے ان کا کہا مانا تو تم بھی مشرک ہو جاؤ گے'),
  ('ur.ahmedali', 6, 122, 'بھلا وہ شخص جو مردہ تھا پھر ہم نے اسے زندہ کر دیا اور ہم نے اسے روشنی دی کہ اسے لوگوں میں لیے پھرتا ہےوہ اس کے برابر ہو سکتا ہے جو اندھیروں میں پڑا ہو وہاں سے نکل نہیں سکتا اسی طرح کافروں کی نظر میں ان کے کام آراستہ کر دیئے گئے ہیں'),
  ('ur.ahmedali', 6, 123, 'اور اسی طرح ہر بستی میں ہم نے گناہگاروں کے سردار بنا دیےہیں تاکہ وہاں اپنے مکرو فریب کا جال پھیلائیں حالانکہ وہ اپنے فریب کے جال میں آپ پھنستے ہیں مگر وہ سمجھتے نہیں'),
  ('ur.ahmedali', 6, 124, 'جب ان کے پاس کوئی نشانی آتی ہے تو کہتے ہیں ہم نہیں مانیں گے جب تک کہ وہ چیز خود ہمیں نہ دی جائے جو الله کے رسولوں کو دی گئی ہے اور الله بہتر جانتا ہے کہ پیغمبری کا کام کس سے لے وہ وقت قریب ہے جب یہ مجرم اپنی مکاریو ں کی پاداش میں الله کے ہاں ذلت اور سخت عذاب میں مبتلا ہوں گے'),
  ('ur.ahmedali', 6, 125, 'سو جسے الله چاہتا ہے کہ ہدایت دے تو اس کے سینہ کو اسلام کے قبول کرنے کے لیے کھول دیتا ہے اور جس کے متعلق چاہتا ہے کہ گمراہ کرے اس کے سینہ کو بے حد تنگ کر دیتا ہے گو کہ وہ آسمان پر چڑھتا ہے اسی طرح الله تعالیٰ ایمان نہ لانے والوں پر پھٹکار ڈالتا ہے'),
  ('ur.ahmedali', 6, 126, 'اور یہ تیرے رب کا سیدھا راستہ ہے ہم نے نصیحت حاصل کرنے والوں کے لیے آیتوں کو صاف صاف کر کے بیان کر دیا ہے'),
  ('ur.ahmedali', 6, 127, 'ان کے لیے اپنے رب کے ہاں سلامتی کا گھر ہے اور وہ ان کے اعمال کے سبب سے ان کا مددگار ہے'),
  ('ur.ahmedali', 6, 128, 'اور جس دن ان سب کو جمع کرے گا جنوں کی جماعت سے فرمائے گا تم نے آدمیوں سے بہت سے اپنے تابع کر لئے تھے اور آدمیوں میں سے جو جنوں کے دوست تھے کہیں گے اے رب ہمارے ہم میں سے ہر ایک نے دوسرے سے کام نکالا اور ہم اپنی اس معیاد کو آ پہنچے جو تو نے ہمارے واسطے مقرر کی تھی فرمائے گا تم سب کا ٹھکانا آگ ہے اس میں ہمیشہ رہو گے اس سے صرف وہی بچیں گے جنہیں الله بچائے گا بے شک تیرا رب حکمت والا جاننے والا ہے'),
  ('ur.ahmedali', 6, 129, 'اور اسی طرح ہم گنہگاروں کو ایک دوسرے کے ساتھ ان کے اعمال کے سبب سے ملا دیں گے'),
  ('ur.ahmedali', 6, 130, 'اے جنو اور انسانو! کی جماعت کیا تمہارے پاس تم ہی میں سے رسول نہیں آئے تھے جو تمہیں میرے احکام سناتے تھے وہ اس دن کی ملاقات سے تمہیں ڈراتے تھے کہیں گے ہم اپنے گناہ کا راقرار کرتے ہیں اور انہیں دنیا کی زندگی نے دھوکہ دیا ہے او راپنے اوپر ہی گواہی دیں گے کہ وہ کافر تھے'),
  ('ur.ahmedali', 6, 131, 'یہ اس لیے ہوا کہ تیار رب بستیوں کو ظلم کرنے کے باوجود ہلاک نہیں کیاکرتا اس حال میں کہ وہ بے خبر ہوں'),
  ('ur.ahmedali', 6, 132, 'اور ہر ایک کے لیے ان کے عمل کے لحاظ سے درجے ہیں اور تیرا رب ان کے کاموں سے بے خبر نہیں'),
  ('ur.ahmedali', 6, 133, 'اور تیرا رب بے پرواہ رحمت والا ہے اگر وہ چاہے تم سب کو اٹھالے اور تمہارے بعد جسے چاہے تمہاری جگہ آباد کردے جس طرح تمہیں ایک دوسری قوم کی نسل سے پیدا کیا ہے'),
  ('ur.ahmedali', 6, 134, 'جس چیز کا تمہیں وعدہ دیا جاتا ہے وہ ضرور آنے والی ہے اور تم عاجز نہیں کر سکتے'),
  ('ur.ahmedali', 6, 135, 'کہہ دو اے لوگو تم اپنی جگہ پر کام کرتے رہو اور میں بھی کرتا ہوں عنقریب معلوم کر لو گے آخرت کا گھر کس کے لیے ہوتا ہے بے شک ظالم نجات نہیں پاتے'),
  ('ur.ahmedali', 6, 136, 'اور الله کی پیدا کی ہوئی کھیتی اور مویشیوں میں سے ایک حصہ اس کے لیے مقرر کرتے ہیں اور اپنے خیال کے مطابق کہتے ہیں کہ یہ الله کا حصہ ہے اور یہ ہمارے شریکوں کا ہے سو جو حصہ ان کے شریکوں کا ہے وہ الله کی طرف نہیں جا سکتا اور جو الله کا ہے وہ ان کے شریکوں کی طرف جا سکتا ہے کیسا برا فیصلہ کرتے ہیں'),
  ('ur.ahmedali', 6, 137, 'اور اسی طرح بہت سے مشرکوں کے خیال میں ان کے شریکوں نے اپنی اولاد کے قتل کرنے کو خوشنما بنا دیا ہے تاکہ انہیں ہلاکت میں مبتلا کر دیں اور ان پر ان کے دین کو مشتبہ بنا دیں اگر الله تعالیٰ چاہتا تو ایسا نہ کرتے سو انہیں چھوڑ دو اور جو وہ افتراء کر تے ہیں'),
  ('ur.ahmedali', 6, 138, 'اور کہتے ہیں یہ جانور اور کھیت محفوظ ہیں انہیں صرف وہی لوگ کھا سکتے ہیں جنہیں ہم چاہیں اورکچھ جانور ہیں جن پر سواری حرام کر دی گئی ہے اور کچھ جانور ہیں جن پر الله کا نام نہیں لیتے یہ سب الله پر افتراء ہے عنقریب الله انہیں اس افترا کی سزا دے گا'),
  ('ur.ahmedali', 6, 139, 'اور کہتے ہیں جو کچھ ان جانوروں کے پیٹ میں ہے یہ ہمارے مردوں کے لیے خاص ہے اور ہماری عورتو ں پر حرام ہے اور جو بچہ مردہ ہو تو دونوں اس کے کھانے میں برابر ہیں الله انہیں ان باتو ں کی سزا دے گا بے شک وہ حکمت والا جاننے والا ہے'),
  ('ur.ahmedali', 6, 140, 'تحقیق خسارے میں پڑے وہ لوگ جنہوں نے اپنی اولاد کو جہالت اور نادانی کی بنا پر قتل کیا اور الله پر بہتان باندھ کر اس رزق کو حرام کر لیا جو الله نے انہیں دیا تھا بے شک وہ گمراہ ہوئے اور سیدھی راہ پر نہ آئے'),
  ('ur.ahmedali', 6, 141, 'اور اسی نے وہ باغ پیدا کیے جو چھتو ں پر چڑھائے جاتے ہیں او رجو نہیں چڑھائے جاتے اور کھجور کے درخت او رکھیتی جن کے پھل مختلف ہیں اور زیتون اور انار پیدا کیے جو ایک دوسرے سے مشابہاور جدا جدا بھی ہیں ان کے پھل کھاؤ جب وہ پھل لائیں اور جس دن اسے کاٹو اس کا حق ادا کرو اور بے جا خرچ نہ کرو بے شک وہ بے جا خرچ کرنے والوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 6, 142, 'اور بوجھ اٹھانے والے مویشی پیدا کیے اور زمین سے لگے ہوئے اور الله کے رزق میں سے کھاؤ اور شیطان کے قدموں پر نہ چلو وہ تمہارا صریح دشمن ہے'),
  ('ur.ahmedali', 6, 143, 'آٹھ قسمیں پیدا کیں بھیڑ میں سے دو اور بکری میں سے دو تو پوچھ کہ دونوں نر الله نے حرام کیے ہیں یا دونوں مادہ یا وہ بچہ جو دونوں مادہ کے رحم میں ہے مجھے اس کی سند بتلاؤ اگر سچے ہو'),
  ('ur.ahmedali', 6, 144, 'اور اونٹ اور گائے سے دو دو قسمیں پیدا کیں تو پوچھ دونوں نر حرا م کیے ہیں یا دونوں مادہ یا وہ بچہ جو دونوں مادہ کے رحم میں ہے کیا تم موجود تھے جس وقت الله نے تمہیں حکم دیا تھا پھر اس سے زیادہ ظالم کون ہے جو الله پر جھوٹا بہتان باندھے تاکہ لوگو ں کو بلا تحقیق گمراہ کرے بے شک الله ظالموں کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 6, 145, 'کہہ دو کہ میں اس وحی میں جو مجھے پہنچی ہے کسی چیز کو کھانے والے پر حرام نہیں پاتا جو اسے کھائے مگر یہ کہ وہ مردار ہو یا بہتا ہوا خون یا سور کا گوشت کہ وہ ناپاک ہے یا وہ ناجائز ذبیحہ جس پر الله کے سوا کسی اور کا نام پکارا جائے پھر جو تمہیں بھوک سے بے اختیار ہوجائے ایسی حال میں کہ نہ بغاوت کرنے والا اور نہ حد سے گزرنے والا ہو تیرا رب بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 6, 146, 'یہود پرہم نے ایک ناخن والا جانور حرام کیا تھا اور گائے اوربکری میں سے ان دونوں کی چربی حرا م کی تھی مگر جو پشت پر یا انتڑیوں پر لگی ہوئی ہو یا جو ہڈی سے ملی ہوئی ہو ہم نے ان کی شرارت کے باعث انہیں یہ سزا دی تھی اور بے شک ہم سچے ہیں'),
  ('ur.ahmedali', 6, 147, 'پھر اگر تجھے جھٹلائیں تو کہہ دو تمہارا رب بہت وسیع رحمت والا ہے اورگناہگار لوگوں سے اس کا عذاب نہیں ٹلے گا'),
  ('ur.ahmedali', 6, 148, 'اب مشرک کہیں گے اگر الله چاہتا تو نہ ہم اور نہ ہمارے باپ دادا شرک کرتے اور نہ ہم کسی چیز کو حرام کرتے اورنہ ہم کسی چیز کو حرام کرتے اسی طرح ان لوگوں نے جھٹلایا جو ان سے پہلے تھے یہاں تک کہ انہو ں نے ہمارا عذاب چکھا کہہ دو تمہارے ہاں کوئی ثبوت ہے تو اسے ہمارے سامنے لاؤ تم فقط خیالی باتوں پر چلتے ہو اور صرف تخمینہ ہی کرتے ہو'),
  ('ur.ahmedali', 6, 149, 'کہہ دو پس الله کا الزام پورا ہو چکا پس اگر وہ چاہتا تو تم سب کو ہدایت کردیتا'),
  ('ur.ahmedali', 6, 150, 'ان سے کہہ دو اپنے گواہ لاؤ جو اس بات کی گواہی دیں کہ الله نے ان چیزوں کو حرام کیا ہے پھر اگر وہ ایسی گواہی دیں توتو ان کا اعتبار نہ کر اور جنہوں نے ہماری آیتوں کو جھٹلایا ہے اور جو آخرت پریقین نہیں رکھتے اور وہ اوروں کو اپنے رب کے برابر کرتے ہیں'),
  ('ur.ahmedali', 6, 151, 'کہہ دو آؤ میں تمہیں سنا دوں جو تمہارے رب نے تم پر حرام کیا ہے یہ کہ اس کے ساتھ کسی کو شریک نہ بناؤ اور ماں باپ کے ساتھ نیکی کرو اور تنگدستی کے سبب اپنی اولاد کو قتل نہ کرو ہم تمہیں اور انہیں رزق دیں گے اور بے حیائی کے ظاہر اور پوشیدہ کاموں کے قریب نہ جاؤ اور نا حق کسی جان کو قتل نہ کرو جس کا قتل الله نے حرام کیا ہے تمہیں یہ حکم دیتا ہے تاکہ تم سمجھ جاؤ'),
  ('ur.ahmedali', 6, 152, 'اور سوائے کسی بہتر طریقہ کے یتیم کے مال کے پاس نہ جاؤ یہاں تک کہ وہ اپنی جوانی کو پہنچے اور ناپ اور تول کو انصاف سے پورا کرو ہم کسی کو اس کی طاقت سے زیادہ تکلیف نہیں دیتے اور جب بات کہو انصاف سے کہو اگرچہ رشتہ داری ہو اور الله کا عہد پورا کرو تمہیں یہ حکم دیا ہے تاکہ تم نصیحت حاصل کرو'),
  ('ur.ahmedali', 6, 153, 'اور بے شک یہی میرا سیدھا راستہ ہے سو اسی کا اتباع کرواور دوسرے راستوں پر مت چلو وہ تمہیں الله کی راہ سے ہٹا دیں گے تمہیں اسی کا حکم دیا ہے تاکہ تم پرہیزگار ہو جاؤ'),
  ('ur.ahmedali', 6, 154, 'پھر ہم نےنیکوں پر نعمت پوری کرنے کے لیے موسیٰ کو کتاب دی جس میں ہر چیز کی تفصیل اور ہدایت اور رحمت تھی تاکہ وہ لوگ اپنے رب کی ملاقات پر ایمان لائیں'),
  ('ur.ahmedali', 6, 155, 'یہ برکت والی کتاب ہم نے اتاری ہے سو اس کا اتباع کرو اور ڈرو تاکہ تم پر رحم کیا جائے'),
  ('ur.ahmedali', 6, 156, 'تاکہ تم یہ نہ کہو کہ ہم سے پہلے دو فرقوں پر کتاب نازل ہوئی تھی اورہم تو ان کے پڑھنے پڑھانے سے بے خبر تھے'),
  ('ur.ahmedali', 6, 157, 'یا یہ کہو کہ اگر ہم پر کتاب نازل کی جاتی تو ہم ان سے بہتر راہ پر چلتے سو تمہارے پاس تمہارے رب کی ھرف سے ایک واضح کتاب اور ہدایت اور رحمت آ چکی ہے اب اس سے زیادہ کون ظالم ہے جو الله کی آیتوں کوجھٹلائے اور ان سے منہ موڑے جو لوگ ہماری آیتوں سے منہ موڑتے ہیں ہم انہیں ان کے منہ موڑنے کے باعث برے عذاب کی سزا دیں گے'),
  ('ur.ahmedali', 6, 158, 'یہ لوگ اس کے منتظر ہیں کہ ان کے پا س فرشتے آویں یا تیرا رب آئے یا تیرے رب کی کوئی نشانی آئے گی تو کسی ایسے شخص کا ایمان کام نہ آئے گا جو پہلے ایمان نہ لایا ہو یا اس نے ایمان لانے کے بعد کوئی نیک کام نہ کیا ہو کہہ دو انتظار کرو ہم بھی انتظار کرنے والے ہیں'),
  ('ur.ahmedali', 6, 159, 'جنہوں نے اپنے دین کو ٹکڑے ٹکڑے کر دیا اور کئی جماعتیں بن گئے تیرا ان سے کوئی تعلق نہیں اس کا کام الله ہی کے حوالے ہے پھر وہی انہیں بتلائے گا جو کچھ وہ کرتے تھے'),
  ('ur.ahmedali', 6, 160, 'جو کوئی ایک نیکی کرے گا اس کے لیے دس گنا اجر ہے اور جو بدی کرے گا سو اسے اسی کے برابر سزا دی جائے گی اور ان پر ظلم نہ کیا جائے گا'),
  ('ur.ahmedali', 6, 161, 'کہہ دو میرے رب نے مجھےایک سیدھا راستہ بتلا دیا ہے ایک صحیح دین ابراھیم کی ملت جو ایک ہی طرف کاتھا اور مشرکوں میں سے نہیں تھا'),
  ('ur.ahmedali', 6, 162, 'کہہ دو بے شک میری نماز اور میری قربانی اور میرا جینا اور میرا مرنا الله ہی کے لیے ہے جو سارے جہان کا پالنے والا ہے'),
  ('ur.ahmedali', 6, 163, 'اس کا کوئی شریک نہیں اور مجھے اسی کا حکم دیا گیا تھا اور میں سب سے پہلے فرمانبردار ہوں'),
  ('ur.ahmedali', 6, 164, 'کہہ دو کیا اب میں الله کے سوا اور کوئی رب تلاش کروں حالانکہ وہی ہر چیز کا رب ہے اور جو شخص کوئی گناہ کرے گاتو وہ اسی کے ذمہ ہے اور ایک شخص دوسرے کا بوجھ نہیں اٹھائے گا پھر تمہارے رب کے ہاں ہی سب کو لوٹ کر جانا ہے سو جن باتو ں میں تم جھگڑتے تھے وہ تمہیں بتلاد ے گا'),
  ('ur.ahmedali', 6, 165, 'اس نے تمہیں زمین میں نائب بنا یا ہے اور بعض کے بعض پر درجے بلند کر دیے ہیں تاکہ تمہیں اپنے دیے ہوئے حکموں میں آزمائے بے شک تیرا رب جلدی عذاب دینے والا ہے اور بے شک وہ بخشنے والا مہربان ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 6, 1, 'Hamd, gökleri ve yeri yaratan, karanlıkları ve aydınlığı vareden Allah\'a mahsustur. Öyle iken, inkar edenler Rablerine başkalarını eşit tutuyorlar.'),
  ('tr.diyanet', 6, 2, 'O, sizi çamurdan yaratan, sonra size bir ecel tayin edendir. Belirli bir ecel O\'nun katındadır; sonra bir de şüphe edersiniz.'),
  ('tr.diyanet', 6, 3, 'O, göklerin ve yerin Allah\'ı, içinizi dışınızı bilir, kazandıklarınızı da bilir.'),
  ('tr.diyanet', 6, 4, 'Onlara Rablerinin ayetlerinden bir ayet geldikçe ondan yüz çevirirlerdi.'),
  ('tr.diyanet', 6, 5, 'Gerçek kendilerine gelince onu yalanladılar. Alaya aldıkları şeyin haberleri kendilerine gelecektir.'),
  ('tr.diyanet', 6, 6, 'Onlardan önce nice nesilleri yok ettiğimizi görmediler mi? Onları, sizi yerleştirmediğimiz bir şekilde yeryüzüne yerleştirmiş, gökten bol yağmur yağdırmış, altlarından ırmaklar akıtmıştık. Fakat onları günahlarından ötürü yok ettik ve ardlarından başka bir nesil yetiştirdik.'),
  ('tr.diyanet', 6, 7, 'Sana Kitap\'ı kağıtta yazılı olarak indirmiş olsak da, elleriyle ona dokunsalar, inkar edenler yine de, "Bu apaçık bir büyüdür" derlerdi.'),
  ('tr.diyanet', 6, 8, '"Ona bir melek indirilmeli değil miydi?" dediler. Bir melek indirmiş olsaydık iş bitmiş olurdu da onlara göz bile açtırılmazdı.'),
  ('tr.diyanet', 6, 9, 'Biz onu melek kılsaydık, bir insan şeklinde yapardık da, düştükleri şüpheye onları yine düşürmüş olurduk.'),
  ('tr.diyanet', 6, 10, 'And olsun ki, senden önce birçok peygamberler alaya alınmıştı, onlarla eğlenenleri, alaya aldıkları şey mahvetti.'),
  ('tr.diyanet', 6, 11, 'De ki: "Yeryüzünde gezip dolaşın, sonra da, yalanlayanların sonunun nasıl olduğuna bir bakın."'),
  ('tr.diyanet', 6, 12, 'De ki: "göklerde ve yerde olanlar kimindir?", "Allah\'ındır" de. O, rahmet etmeyi kendi üzerine almıştır; and olsun ki, sizi vukuu şüphe götürmeyen kıyamet gününde toplayacaktır. Kendilerine yazık ettiler; çünkü onlar inanmazlar.'),
  ('tr.diyanet', 6, 13, 'Gecede ve gündüzde bulunan O\'nundur. O işitendir, Bilen\'dir.'),
  ('tr.diyanet', 6, 14, '"Gökleri ve yeri yaratan, beslenmeyip besleyen Allah\'tan başka bir dost mu edinirim?" de. "Doğrusu ben ilk müslüman olmakla emrolundum" de; asla ortak koşanlardan olma!'),
  ('tr.diyanet', 6, 15, '"Ben Rabbime karşı gelirsem, büyük günün azabından korkarım" de.'),
  ('tr.diyanet', 6, 16, 'O gün kim azabdan alıkonursa, şüphesiz o kimse rahmete erişmiştir. Bu, apaçık bir kurtuluştur.'),
  ('tr.diyanet', 6, 17, 'Allah sana bir sıkıntı verirse, O\'ndan başkası gideremez. Sana bir iyilik verirse başkası onu engelleyemez. O, her şeye Kadir\'dir.'),
  ('tr.diyanet', 6, 18, 'O, kullarının üstünde yegane tasarruf sahibidir. Hakim\'dir, haberdardır.'),
  ('tr.diyanet', 6, 19, '"Şahit olarak hangi şey daha büyüktür" de. "Allah benimle sizin aranızda şahiddir. Bu Kuran bana, sizi ve ulaştığı kimseleri uyarmam için vahyolundu; Allah\'la beraber başka tanrılar bulunduğuna siz mi şahidlik ediyorsunuz?" de. "Ben şehadet etmem" de. "O ancak tek Tanrıdır, doğrusu ben ortak koşmanızdan uzağım" de.'),
  ('tr.diyanet', 6, 20, 'Kendilerine Kitap verdiklerimiz, onu (peygamberi) çocuklarını tanıdıkları gibi tanırlar; fakat kendilerine yazık ettiler, çünkü onlar inanmazlar.'),
  ('tr.diyanet', 6, 21, 'Allah\'a karşı yalan uyduran veya ayetlerini yalanlayandan daha zalim kimdir? Zalimler bunun için saadete ulaşamazlar.'),
  ('tr.diyanet', 6, 22, 'Bir gün hepsini toplarız, sonra ortak koşanlara, "İddia ettiğiniz ortaklarınız nerede?" deriz.'),
  ('tr.diyanet', 6, 23, 'Sonra, "Rabbimiz Allah\'a and olsun ki bizler ortak koşanlar değildik" demekten başka çare bulamazlar.'),
  ('tr.diyanet', 6, 24, 'Kendilerine karşı nasıl yalan söylediklerine bak; uydurdukları şeyler de onlardan uzaklaştı.'),
  ('tr.diyanet', 6, 25, 'Onlardan seni dinleyenler vardır, Kuran\'ı anlarlar diye kalblerine örtüler kulaklarına da ağırlık koyduk. Onlar her türlü mucizeyi görseler bile, yine de ona inanmazlar, nihayet sana geldiklerinde de seninle çekişirler. İnkar edenler, "Bu, öncekilerin masallarından başka bir şey değildir" derler.'),
  ('tr.diyanet', 6, 26, 'Onlar Kuran\'dan alıkorlar ve ondan uzaklaşırlar. Böylece yalnız kendilerini mahvederler de farkına varamazlar.'),
  ('tr.diyanet', 6, 27, 'Onların, ateşin kenarına getirilip durdurulduklarında, "keşke dünyaya tekrar döndürülseydik, Rabbimiz\'in ayetlerini yalanlamasaydık ve inananlardan olsaydık" dediklerini bir görsen!'),
  ('tr.diyanet', 6, 28, 'Hayır; daha önce gizledikleri onlara göründü. Eğer geri döndürülseler yine kendilerine yasak edilen şeylere dönerler. Doğrusu onlar yalancıdırlar.'),
  ('tr.diyanet', 6, 29, '"Hayat ancak bu dünyadakinden ibarettir, biz dirilecek değiliz" dediler.'),
  ('tr.diyanet', 6, 30, 'Onları, Rablerinin huzuruna çıkarıldıkları zaman bir görsen! Allah: "Bu gerçek değil mi?" der; onlar, "Evet, Rabbimiz hakkı için gerçektir" derler. Allah da "Öyleyse inkar etmenizden ötürü azabı tadın" der.'),
  ('tr.diyanet', 6, 31, 'Allah\'a kavuşmayı yalanlayanlar doğrusu kaybedenlerdir ki kıyamet saati onlara ansızın gelince, ağırlıklarını arkalarına yüklenerek, "Dünyada işlediğimiz büyük kusurlardan ötürü yazıklar olsun bize" derler. Dikkat edin, yüklendikleri şeyler ne kötüdür!'),
  ('tr.diyanet', 6, 32, 'Dünya hayatı sadece oyun ve oyalanmadır; ahiret yurdu, sakınanlar için daha iyidir. Düşünmüyor musunuz?'),
  ('tr.diyanet', 6, 33, 'Onların söylediklerinin seni üzeceğini elbette biliyoruz; doğrusu onlar seni yalancı saymıyorlar, fakat zalimler Allah\'ın ayetlerini bile bile inkar ediyorlar.'),
  ('tr.diyanet', 6, 34, 'Senden önce nice peygamberler yalanlandı ve kendilerine yardımımız gelene kadar yalanlanmalarına ve sıkıştırılmaya katlandılar. Allah\'ın sözlerini değiştirebilecek yoktur; and olsun ki peygamberlerin haberi sana da geldi.'),
  ('tr.diyanet', 6, 35, 'Onların yüz çevirmesi sana ağır gelince, eğer gücün yeri delmeye veya göğe merdiven dayamağa yetmiş olsaydı, onlara bir mucize göstermek isterdin. Allah dileseydi onları doğru yolda toplardı. Sakın bilmeyenlerden olma.'),
  ('tr.diyanet', 6, 36, 'Ancak kulak verenler daveti kabul ederler. Ölüleri Allah diriltir, sonra O\'na dönerler.'),
  ('tr.diyanet', 6, 37, '"Rabbinden ona (Muhammed\'e) bir belge indirilseydi ya" dediler. De ki: "Doğrusu Allah bir belge indirmeye Kadir\'dir, fakat çoğu bilmezler."'),
  ('tr.diyanet', 6, 38, 'Yerde yürüyen hayvanlar ve kanatlarıyla uçan kuşlar da ancak sizin gibi birer toplulukturlar. Kitap\'da Biz hiçbir şeyi eksik bırakmadık; onlar sonra Rablerine toplanacaklardır.'),
  ('tr.diyanet', 6, 39, 'Ayetlerimizi yalanlayanlar karanlıklarda kalmış sağır ve dilsizlerdir. Allah kimi dilerse onu saptırır ve kimi dilerse onu doğru yola koyar.'),
  ('tr.diyanet', 6, 40, 'De ki, "Üzerinize Allah\'ın azabı gelse veya kıyamet saati size gelse, Allah\'tan başkasına mı yalvarırsınız? Doğru iseniz bana bildirin".'),
  ('tr.diyanet', 6, 41, 'Hayır; sadece O\'na yalvarırsınız; dilerse yalvardığınız şeyi giderir, siz de O\'na koştuğunuz ortakları unutursunuz.'),
  ('tr.diyanet', 6, 42, 'Şüphesiz ki, senden önce ümmetlere peygamberler göndermiştik; onları yalvarsınlar diye darlık ve sıkıntıya sokmuştuk.'),
  ('tr.diyanet', 6, 43, 'Hiç değilse, onlara şiddetimiz geldiği zaman yalvarıp yakarmalı değil miydiler? Lakin kalbleri katılaştı, şeytan da yaptıklarını onlara güzel gösterdi.'),
  ('tr.diyanet', 6, 44, 'Kendilerine hatırlatılanı unuttuklarında, onlara her şeyin kapısını açtık; kendilerine verilene sevinince ansızın onları yakaladık da umutsuz kalıverdiler.'),
  ('tr.diyanet', 6, 45, 'Zulmeden milletin kökü böylece kesildi. Hamd, Alemlerin Rabbi Allah\'a mahsustur.'),
  ('tr.diyanet', 6, 46, 'De ki: "Gördünüz mü? Allah, işitmenizi, gözlerinizi alsa, kalblerinizi kapasa, Allah\'tan başka hangi tanrı onu sizlere getirebilir?" Ayetleri nasıl türlü türlü açıkladığımıza bir baksana, sonra da onlar yüz çevirirler.'),
  ('tr.diyanet', 6, 47, 'De ki: "Allah\'ın azabı size ansızın veya açıkça gelirse, zalimlerden başkası mı yok olur? Bana bildirin."'),
  ('tr.diyanet', 6, 48, 'Peygamberleri ancak müjdeci ve uyarıcı olarak gönderiyoruz. Kim inanır ve nefsini ıslah ederse onlara korku yoktur, onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 6, 49, 'Ayetlerimizi inkar edenlere yoldan çıkmalarından ötürü azab dokunacaktır.'),
  ('tr.diyanet', 6, 50, 'De ki: "Size Allah\'ın hazineleri elimdedir, demiyorum; gaybı da bilmiyorum; size, ben meleğim demiyorum, ben ancak bana vahyolunana uyuyorum." De ki: "Görenle görmeyen bir midir? Düşünmüyor musunuz?"'),
  ('tr.diyanet', 6, 51, 'Rablerine toplanacaklarından korkanları Kuran ile uyar. O\'ndan başka bir dost ve aracıları yoktur. Umulur ki Allah\'tan sakınalar.'),
  ('tr.diyanet', 6, 52, 'Sabah akşam, Rabblerinin rızasını isteyerek O\'na yalvaranları kovma. Onların hesabından sana bir sorumluluk yoktur, senin hesabından da onlara bir sorumluluk yoktur ki onları kovarak zulmedenlerden olasın.'),
  ('tr.diyanet', 6, 53, 'Böylece, "Aramızdan Allah bunlara mı iyilikte bulundu?" demeleri için onları birbiriyle denedik. Allah şükredenleri iyi bilen değil midir?'),
  ('tr.diyanet', 6, 54, 'Ayetlerimize inananlar sana gelince: "Size selam olsun" de. Rabbiniz, sizden kim bilmeyerek fenalık işler de arkasından tövbe eder ve nefsini düzeltirse, ona rahmet etmeyi kendi üzerine almıştır. O, bağışlar ve merhamet eder.'),
  ('tr.diyanet', 6, 55, 'Suçluların yolu belli olsun diye, böylece ayetleri uzun uzun açıklarız.'),
  ('tr.diyanet', 6, 56, 'De ki: "Allah\'tan başka, yalvardıklarınıza kulluk etmekten menolundum." "Sizin heveslerinize uymayacağım, yoksa sapıtmış, doğru yolda gidenlerden olmamış olurum" de.'),
  ('tr.diyanet', 6, 57, 'De ki: "Ben Rabbim\'den bir belgeye dayanmaktayım, halbuki siz onu yalanladınız; acele istediğiniz de elimde değildir. Hüküm ancak Allah\'ındır. O, hükmedenlerin en iyisi olarak gerçeği anlatır."'),
  ('tr.diyanet', 6, 58, 'De ki: "Acele istediğiniz şey elimde olsaydı, benimle aranızdaki iş bitmiş olurdu." Allah zulmedenleri en iyi bilendir.'),
  ('tr.diyanet', 6, 59, 'Gaybın anahtarları O\'nun katındadır, onları ancak O bilir. Karada ve denizde olanı bilir. Düşen yaprağı, yerin karanlıklarında olan taneyi, yaşı kuruyu ki apaçık Kitap\'tadır ancak O bilir.'),
  ('tr.diyanet', 6, 60, 'Geceleyin sizi ölü gibi uyutan, gündüzün yaptıklarınızı bilen, mukadder olan hayat süreniz doluncaya kadar gündüzleri sizi tekrar kaldıran O\'dur. Sonra dönüşünüz O\'nadır, işlediklerinizi size bildirecektir.'),
  ('tr.diyanet', 6, 61, 'O, kulların üstünde yegane Hakim\'dir, size koruyucular gönderir. Artık birinize ölüm gelince elçilerimiz, bir eksiklik yapmaksızın onun canını alırlar, sonra gerçek Mevlalarına döndürürler. Haberiniz olsun, hüküm O\'nundur. O, hesap görenlerin en süratlisidir.'),
  ('tr.diyanet', 6, 62, 'O, kulların üstünde yegane Hakim\'dir, size koruyucular gönderir. Artık birinize ölüm gelince elçilerimiz, bir eksiklik yapmaksızın onun canını alırlar, sonra gerçek Mevlalarına döndürürler. Haberiniz olsun, hüküm O\'nundur. O, hesap görenlerin en süratlisidir.'),
  ('tr.diyanet', 6, 63, 'De ki: "Kara ve denizin karanlıklarından sizi kim kurtarır? Bundan bizi kurtarırsan şükredenlerden olacağız diye O\'na gizli gizli yalvarır yakarırsınız."'),
  ('tr.diyanet', 6, 64, 'De ki: "Allah sizi ondan ve her sıkıntıdan kurtarır, sonra da O\'na ortak koşarsınız."'),
  ('tr.diyanet', 6, 65, 'De ki: "Üstünüzden ve altınızdan size azab göndermeğe, sizi fırka fırka yapıp kiminize kiminizin hıncını tattırmağa Kadir olan O\'dur." Anlasınlar diye ayetleri nasıl yerli yerince açıkladığımıza bak.'),
  ('tr.diyanet', 6, 66, 'Gerçekten, senin milletin Kuran\'ı yalanladı. "Cezanızı ben verecek değilim" de.'),
  ('tr.diyanet', 6, 67, 'Her haberin gerçekleşeceği bir zaman vardır ki siz onu yakında bileceksiniz.'),
  ('tr.diyanet', 6, 68, 'Ayetlerimizi çekişmeye dalanları görünce, başka bir bahse geçmelerine kadar onlardan yüz çevir. Şeytan sana unutturursa hatırladıktan sonra artık zulmedenlerle beraber oturma.'),
  ('tr.diyanet', 6, 69, 'Sakınan kimselere, onların hesaplarından bir sorumluluk yoktur. Fakat bir hatırlatmadır; belki sakınırlar.'),
  ('tr.diyanet', 6, 70, 'Dinlerini oyun ve eğlenceye alanları, dünya hayatının aldattığı kimseleri bırak. Kuran ile öğüt ver ki, bir kimse kazandığıyla helake düşmeye görsün, o takdirde Allah\'dan başka ona ne bir yardımcı, ne de bir kurtarıcı bulunur; her türlü fidyeyi de verse kabul olunmaz. Kazandıklarından ötürü yok olanlar işte bunlardır. İnkar etmelerinden dolayı kızgın içecek ve can yakıcı azab onlaradır.'),
  ('tr.diyanet', 6, 71, 'De ki: "Arkadaşları bize gel diye doğru yola çağırırken, şeytanların yeryüzünde şaşırttıkları bir kimse gibi geriye mi dönelim. Allah bizi doğru yola eriştirdikten sonra, bize faydası olmayan, zarar da veremeyen Allah\'tan başka şeylere mi yalvaralım?" De ki, "Doğru yol ancak Allah\'ın yoludur. Alemlerin Rabbine teslim olarak namaz kılın, Allah\'tan sakının diye emrolunduk." Kendisine toplanacağınız O\'dur.'),
  ('tr.diyanet', 6, 72, 'De ki: "Arkadaşları bize gel diye doğru yola çağırırken, şeytanların yeryüzünde şaşırttıkları bir kimse gibi geriye mi dönelim. Allah bizi doğru yola eriştirdikten sonra, bize faydası olmayan, zarar da veremeyen Allah\'tan başka şeylere mi yalvaralım?" De ki, "Doğru yol ancak Allah\'ın yoludur. Alemlerin Rabbine teslim olarak namaz kılın, Allah\'tan sakının diye emrolunduk." Kendisine toplanacağınız O\'dur.'),
  ('tr.diyanet', 6, 73, 'Gökleri ve yeri gerçekle yaratan O\'dur ki "Ol" dediği gün (an) hemen olur; sözü gerçektir. Sura üfleneceği gün hükümranlık O\'nundur. Görülmeyeni de görüleni de bilir. O Hakim\'dir, haberdardır.'),
  ('tr.diyanet', 6, 74, 'İbrahim, babası Azer\'e, "Putları tanrı olarak mı benimsiyorsun? Doğrusu ben seni ve milletini açık bir sapıklık içinde görüyorum" demişti.'),
  ('tr.diyanet', 6, 75, 'Yakinen bilenlerden olması için İbrahim\'e göklerin ve yerin hükümranlığını şöylece gösteriyorduk:'),
  ('tr.diyanet', 6, 76, 'Gece basınca bir yıldız gördü, "işte bu benim Rabbim!" dedi; yıldız batınca, "batanları sevmem" dedi.'),
  ('tr.diyanet', 6, 77, 'Ayı doğarken görünce, "işte bu benim Rabbim!" dedi, batınca, "Rabbim beni doğruya eriştirmeseydi and olsun ki sapıklardan olurdum" dedi.'),
  ('tr.diyanet', 6, 78, 'Güneşi doğarken görünce "işte bu benim Rabbim, bu daha büyük!" dedi; batınca, "Ey milletim! Doğrusu ben ortak koştuklarınızdan uzağım" dedi.'),
  ('tr.diyanet', 6, 79, '"Doğrusu ben yüzümü, gökleri ve yeri yaratana, doğruya yönelerek çevirdim, ben ortak koşanlardan değilim."'),
  ('tr.diyanet', 6, 80, 'Milleti onunla tartışmaya girişti. "Beni doğru yola eriştirmişken, Allah hakkında benimle mi tartışıyorsunuz? O\'na ortak koştuklarınızdan korkmuyorum, meğer ki Rabbim bir şeyi dilemiş ola. Rabbim ilimce her şeyi kuşatmıştır; hala öğüt kabul etmez misiniz?" dedi.'),
  ('tr.diyanet', 6, 81, '"Allah\'a koştuğunuz ortaklardan nasıl korkarım? Oysa siz, Allah\'ın hakkında size bir delil indirmediği bir şeyi O\'na ortak koşmaktan korkmuyorsunuz. İki taraftan hangisine güvenmek daha gereklidir, bir bilseniz."'),
  ('tr.diyanet', 6, 82, 'İşte güven; onlara, inanıp haksızlık karıştırmayanlaradır. Onlar doğru yoldadırlar.'),
  ('tr.diyanet', 6, 83, 'Bu, İbrahim\'e, milletine karşı verdiğimiz hüccetimizdir. Dilediğimizi derecelerle yükseltiriz. Doğrusu Rabbin Hakim\'dir, Bilen\'dir.'),
  ('tr.diyanet', 6, 84, 'Ona İshak\'ı, Yakub\'u bağışladık, her birini doğru yola eriştirdik. Daha önce Nuh\'u ve soyundan Davud\'u, Süleyman\'ı, Eyyub\'u, Yusuf\'u, Musa\'yı ve Harun\'u -ki işlerini iyi yapanlara böylece karşılık veririz-, Zekeriya\'yı, Yahya\'yı, İsa\'yı ve İlyas\'ı -ki hepsi iyilerdendir-, İsmail\'i, Elyesa\'ı, Yunus\'u, Lut\'u -ki hepsini dünyalara üstün kıldık- doğru yola eriştirdik.'),
  ('tr.diyanet', 6, 85, 'Ona İshak\'ı, Yakub\'u bağışladık, her birini doğru yola eriştirdik. Daha önce Nuh\'u ve soyundan Davud\'u, Süleyman\'ı, Eyyub\'u, Yusuf\'u, Musa\'yı ve Harun\'u -ki işlerini iyi yapanlara böylece karşılık veririz-, Zekeriya\'yı, Yahya\'yı, İsa\'yı ve İlyas\'ı -ki hepsi iyilerdendir-, İsmail\'i, Elyesa\'ı, Yunus\'u, Lut\'u -ki hepsini dünyalara üstün kıldık- doğru yola eriştirdik.'),
  ('tr.diyanet', 6, 86, 'Ona İshak\'ı, Yakub\'u bağışladık, her birini doğru yola eriştirdik. Daha önce Nuh\'u ve soyundan Davud\'u, Süleyman\'ı, Eyyub\'u, Yusuf\'u, Musa\'yı ve Harun\'u -ki işlerini iyi yapanlara böylece karşılık veririz-, Zekeriya\'yı, Yahya\'yı, İsa\'yı ve İlyas\'ı -ki hepsi iyilerdendir-, İsmail\'i, Elyesa\'ı, Yunus\'u, Lut\'u -ki hepsini dünyalara üstün kıldık- doğru yola eriştirdik.'),
  ('tr.diyanet', 6, 87, 'Babalarından, soylarından, kardeşlerinden bir kısmını seçtik ve doğru yola eriştirdik.'),
  ('tr.diyanet', 6, 88, 'Bu, Allah\'ın kullarından dilediğini eriştirdiği yoludur. Eğer ortak koşsalarda amelleri boşa çıkardı.'),
  ('tr.diyanet', 6, 89, 'Kendilerine kitap, hüküm ve peygamberlik verdiklerimiz işte bunlardır. Kafirler onları inkar ederlerse, inkar etmeyecek bir milleti onlara vekil kılarız.'),
  ('tr.diyanet', 6, 90, 'İşte bunlar Allah\'ın doğru yola eriştirdikleridir, onların yoluna uy, "Sizden buna karşılık bir ücret istemem, bu sadece herkes için bir hatırlatmadır" de.'),
  ('tr.diyanet', 6, 91, '"Allah hiçbir insana bir şey indirmemiştir" demekle Allah\'ı gereği gibi değerlendiremediler. De ki: "Musa\'nın insanlara nur ve yol gösterici olarak getirdiği Kitap\'ı kim indirdi? Ki siz onu kağıtlara yazıp bir kısmını gösterip çoğunu gizlersiniz, atalarınızın ve sizin bilmediğiniz size onunla öğretilmiştir." "Allah" de, sonra da onları daldıkları sapıklıkta bırak, oynasınlar.'),
  ('tr.diyanet', 6, 92, 'Bu indirdiğimiz, kendinden öncekileri doğrulayan, Mekkelileri ve etrafındakileri uyaran mübarek Kitap\'dır. Ahirete inananlar buna inanırlar, namazlarına da devam ederler.'),
  ('tr.diyanet', 6, 93, 'Allah\'a karşı yalan uydurandan veya kendisine bir şey vahyedilmemişken "Bana vahyolundu, Allah\'ın indirdiği gibi ben de indireceğim" diyenden daha zalim kim olabilir? Bu zalimleri can çekişirlerken melekler ellerini uzatmış, "Canlarınızı verin, bugün Allah\'a karşı haksız yere söylediklerinizden, O\'nun ayetlerine büyüklük taslamanızdan ötürü alçaltıcı azabla cezalandırılacaksınız" derken bir görsen!'),
  ('tr.diyanet', 6, 94, 'Onlara: "And olsun ki, sizi ilk defa yarattığımız gibi size verdiklerimizi ardınızda bırakarak bize birer birer geldiniz; içinizde Allah\'ın ortakları olduğunu sandığınız şefaatçılarınızı beraber görmüyoruz. And olsun ki aranızdaki bağlar kopmuş, ortak sandıklarınız sizden ayrılmışlardır" denecek.'),
  ('tr.diyanet', 6, 95, 'Taneyi ve çekirdeği yaran şüphesiz Allah\'tır; ölüyü çıkarır. İşte Allah budur, nasıl yüz çevirirsiniz?'),
  ('tr.diyanet', 6, 96, 'Tanyerini ağartan, geceyi dinlenme zamanı, güneş ve ayı vakit ölçüsü kılandır. Bu, Güçlü olan\'ın, Bilen\'in nizamıdır.'),
  ('tr.diyanet', 6, 97, 'O, yıldızları kara ve denizin karanlıklarında yol bulasınız diye sizin için var edendir. Bilen millet için ayetleri uzun uzadıya açıkladık.'),
  ('tr.diyanet', 6, 98, 'O, sizi bir tek nefisten, babaların sulbünde kararlaşmış ve anaların rahminde kararlaşmakta olarak yaratandır. Anlayan millet için ayetleri uzun uzadıya açıkladık.'),
  ('tr.diyanet', 6, 99, 'O, gökten su indirendir. Her bitkiyi onunla bitirdik, ondan bitirdiğimiz yeşilden, birbirine benzeyen ve benzemeyen yığın yığın taneler, hurmaların tomurcuklarından sarkan salkımlar, üzüm bağları, zeytin ve nar çıkardık. Ürün verdiklerinde ürünlerine, olgunlaşmalarına bir bakın. Bunlarda, inananlar için, şüphesiz, deliller vardır.'),
  ('tr.diyanet', 6, 100, 'Cinleri O yaratmışken kafirler Allah\'a ortak koştular. Körü körüne O\'na oğullar ve kızlar uydurdular. Haşa, O onların vasıflandırmalarından yücedir.'),
  ('tr.diyanet', 6, 101, 'O, gökleri ve yeri yoktan yaratandır. Zevcesi olmadan nasıl çocuğu olabilir? Oysa her şeyi O yaratmıştır, her şeyi bilir.'),
  ('tr.diyanet', 6, 102, 'İşte Rabbiniz, Allah budur. O\'ndan başka tanrı yoktur, her şeyin yaratanıdır. Öyleyse O\'na kulluk edin; O her şeye de vekildir.'),
  ('tr.diyanet', 6, 103, 'Gözler O\'nu görmez, O bütün gözleri görür. O Latif\'tir, haberdardır.'),
  ('tr.diyanet', 6, 104, 'Doğrusu size Rabbiniz\'den açık belgeler gelmiştir; kim görürse kendi lehine ve kim körlük ederse kendi aleyhinedir. Ben sizin bekçiniz değilim.'),
  ('tr.diyanet', 6, 105, 'Sana, "Sen okumuşsun" derler; oysa Biz, öğrenecek kimselere ayetleri böylece türlü türlü açıklamaktayız.'),
  ('tr.diyanet', 6, 106, 'Rabbin\'den sana vahyolunana uy, O\'ndan başka tanrı yoktur, puta tapanlardan yüz çevir.'),
  ('tr.diyanet', 6, 107, 'Allah dileseydi puta tapmazlardı. Seni onlara koruyucu yapmadık, onların vekili de değilsin.'),
  ('tr.diyanet', 6, 108, 'Allah\'tan başka yalvardıklarına sövmeyin ki, onlar da cahillikle ileri giderek Allah\'a sövmesinler. Böylece her ümmete işini güzel gösterdik, sonra dönüşleri Rab\'lerinedir. O, işlediklerini haber verir.'),
  ('tr.diyanet', 6, 109, 'Kendilerine bir mucize gösterilirse, mutlaka ona inanacaklarına dair bütün güçleriyle Allah\'a yemin ederler. De ki: "Mucizeler, ancak Allah katındadır"; onların, mucize geldiği zaman da inanmayacaklarını anlamıyor musunuz?'),
  ('tr.diyanet', 6, 110, 'Onların kalblerini, gözlerini, ona ilk defa inanmadıkları gibi çeviririz; onları taşkınlıkları içinde şaşkın şaşkın bırakırız.'),
  ('tr.diyanet', 6, 111, 'Eğer biz onlara melekleri indirsek, ölüler onlarla konuşsa ve her şeyi karşılarına toplasaydık, Allah dilemedikçe, yine de inanmazlardı; fakat onların çoğu bunu bilmiyorlar.'),
  ('tr.diyanet', 6, 112, 'Aldatmak için birbirlerine cazip sözler fısıldayan cin ve insan şeytanlarını her peygambere düşman yaptık. Bu şeytanlar ahirete inanmayanların kalblerinin o sözlere yönelmesi, ondan hoşnut olması ve kendilerinin işledikleri suçları işlemeleri için böyle yaparlar. Rabbin dileseydi bunu yapamazlardı, sen onları iftiraları ile başbaşa bırak;'),
  ('tr.diyanet', 6, 113, 'Aldatmak için birbirlerine cazip sözler fısıldayan cin ve insan şeytanlarını her peygambere düşman yaptık. Bu şeytanlar ahirete inanmayanların kalblerinin o sözlere yönelmesi, ondan hoşnut olması ve kendilerinin işledikleri suçları işlemeleri için böyle yaparlar. Rabbin dileseydi bunu yapamazlardı, sen onları iftiraları ile başbaşa bırak;'),
  ('tr.diyanet', 6, 114, '"Allah size Kitap\'ı açık açık indirmişken O\'ndan başka bir hakem mi isteyeyim?" Kendilerine Kitap verdiklerimiz, onun gerçekten Rableri katından indirilmiş olduğunu bilirler. Öyleyse, sen şüpheye düşenlerden olma!'),
  ('tr.diyanet', 6, 115, 'Rabbinin sözü, doğruluk ve adaletle tamamlandı. O\'nun sözlerini değiştirebilecek yoktur. O, işitir ve bilir.'),
  ('tr.diyanet', 6, 116, 'Yeryüzündekilerin çoğunluğuna itaat edersen seni Allah yolundan saptırırlar. Onlar ancak zanna uyarlar, sadece tahminde bulunurlar.'),
  ('tr.diyanet', 6, 117, 'Doğrusu Rabbin, yolundan kimin saptığını daha iyi bilir. Doğru yolda olanları da en iyi O bilir.'),
  ('tr.diyanet', 6, 118, 'Allah\'ın ayetlerine inanıyorsanız, üzerine Allah\'ın adı anılmış olan şeyden yiyin.'),
  ('tr.diyanet', 6, 119, 'Size ne oluyor ki, Allah size darda kalmanızın dışında, haram olanları genişçe anlatmışken adının üzerine anıldığı şeyden yemiyorsunuz? Doğrusu çoğunluk, heva ve heveslerine uyarak, bilmeden sapıtıyorlar. Aşırı gidenleri en iyi bilen Rabbindir.'),
  ('tr.diyanet', 6, 120, 'Günahın açığını da gizlisini de bırakın. Günah kazananlar, kazandıklarına karşılık şüphesiz ceza göreceklerdir.'),
  ('tr.diyanet', 6, 121, 'Üzerine Allah\'ın adının anılmadığı kesilmiş hayvanları yemeyin, bunu yapmak Allah\'ın yolundan çıkmaktır. Doğrusu şeytanlar sizinle tartışmaları için dostlarına fısıldarlar, eğer onlara itaat ederseniz şüphesiz siz müşrik olursunuz.'),
  ('tr.diyanet', 6, 122, 'Ölü iken kalbini diriltip, insanlar arasında yürürken önünü aydınlatacak bir nur verdiğimiz kimsenin durumu, karanlıklarda kalıp çıkamayan kimsenin durumu gibi midir? Kafirlere de, işledikleri güzel gösterilmiştir.'),
  ('tr.diyanet', 6, 123, 'Bunun gibi, her kasabanın bir takım ileri gelenlerini orada hile yapan suçlular kıldık. Oysa yalnız kendilerine hile yaparlar da farkına varmazlar.'),
  ('tr.diyanet', 6, 124, 'Onlara bir ayet geldiği zaman, "Allah\'ın peygamberlerine verilen bize de verilmedikçe inanmayız" derler. Allah, peygamberliğini vereceği kimseyi daha iyi bilir. Suç işleyenlere Allah katından bir aşağılık ve hilelerinden ötürü de şiddetli bir azab erişecektir.'),
  ('tr.diyanet', 6, 125, 'Allah kimi doğru yola koymak isterse onun kalbini İslamiyet\'e açar, kimi de saptırmak isterse, göğe yükseliyormuş gibi, kalbini dar ve sıkıntılı kılar. Allah böylece, inanmayanları küfür bataklığında bırakır.'),
  ('tr.diyanet', 6, 126, 'Rabbinin, dosdoğru yolu işte budur. İbret alan kimselere ayetleri uzun uzadıya açıkladık.'),
  ('tr.diyanet', 6, 127, 'Rablerinin katında selamet yurdu onlarındır. O, işlediklerinden ötürü onların dostudur.'),
  ('tr.diyanet', 6, 128, 'Allah hepsini toplayacağı gün, "Ey cin topluluğu! İnsanların çoğunu yoldan çıkardınız" der, insanlardan onlara uymuş olanlar, "Rabbimiz! Bir kısmımız bir kısmımızdan faydalandık ve bize tayin ettiğin sürenin sonuna ulaştık" derler. "Cehennem, Allah\'ın dilemesine bağlı olarak, temelli kalacağınız durağınızdır" der. Doğrusu Rabbin hakimdir, bilendir.'),
  ('tr.diyanet', 6, 129, 'Zalimlerin bir kısmını, kazandıklarından ötürü diğer bir kısmına böylece musallat ederiz.'),
  ('tr.diyanet', 6, 130, '"Ey cin ve insan topluluğu! Size ayetlerimi anlatan, bugünle karşılaşmanızdan sizi uyaran peygamberler gelmedi mi?" "Kendi hakkımızda şahidiz" derler. Dünya hayatı onları aldattı da inkarcı olduklarına, kendi aleyhlerinde şahidlik ettiler.'),
  ('tr.diyanet', 6, 131, 'Bu, haberleri yokken kasabalar halkını Allah\'ın haksız yere yok etmeyeceğinden dolayıdır.'),
  ('tr.diyanet', 6, 132, 'İşlediklerine karşılık her birinin dereceleri vardır. Rabbin onların işlediklerinden habersiz değildir.'),
  ('tr.diyanet', 6, 133, 'Rabbin müstağni ve rahmet sahibidir. Dilerse, sizi başka bir milletin soyundan getirdiği gibi, sizi yok eder, dilediğini yerinize getirir.'),
  ('tr.diyanet', 6, 134, 'Size vadedilen, mutlaka yerine gelecektir; siz O\'nu aciz kılamazsınız.'),
  ('tr.diyanet', 6, 135, 'De ki, "Ey milletim! Durumunuzun gerektirdiğini yapın, doğrusu ben de yapacağım. Sonucun kimin için hayırlı olacağını bileceksiniz. Zulmedenler şüphesiz kurtulamazlar."'),
  ('tr.diyanet', 6, 136, 'Kendi zanlarına göre, "Bu Allah\'ındır, bu da putlarımızındır" diyerek, Allah\'ın yarattığı hayvanlar ve ekinlerden pay ayırdılar. Putları için ayırdıkları Allah için verilmez, ama Allah için ayırdıkları putlarına verilirdi; ne kötü hüküm veriyorlardı!'),
  ('tr.diyanet', 6, 137, 'Böylece, putlara hizmet edenler, puta tapanların çoğunu helake sürüklemek, dinlerini karma karışık etmek için çocuklarını öldürmelerini onlara iyi göstermişlerdir. Allah dileseydi bunu yapamazlardı. Sen onları ve iftiralarını bir tarafa bırak.'),
  ('tr.diyanet', 6, 138, '"Bu hayvanlar ve ekinleri dilediğimizden başkasının yemesi yasaktır; bir kısım hayvanların sırtlarına yük vurmak da haramdır" iddiasında bulunarak ve bir kısım hayvanları keserken de Allah\'ın adını anmamak suretiyle O\'na iftira ederler. Allah, yaptıkları iftiralara karşı onları cezalandıracaktır.'),
  ('tr.diyanet', 6, 139, '"Bu hayvanların karınlarında olan yavrular yalnız erkeklerimize mahsus olup, eşlerimize yasaktır. Ölü doğacak olursa hepsi ona ortak olurlar" dediler. Allah bu türlü sözlerin cezasını verecektir, çünkü O hakimdir, bilendir.'),
  ('tr.diyanet', 6, 140, 'Beyinsizlikleri yüzünden, körü körüne çocuklarını öldürenler ve Allah\'ın kendilerine verdiği nimetleri Allah\'a iftira ederek haram sayanlar mahvolmuşlardır; onlar sapıtmışlardır, zaten doğru yolda da değillerdi.'),
  ('tr.diyanet', 6, 141, 'Çardaklı ve çardaksız bağları inşa eden Allah\'tır. Tadları çeşitli ekin ve hurmaları, zeytin ve narı birbirine benzer ve benzemez şekilde yaratan O\'dur. Ürün verdiği zaman ürününden yiyin, devşirildiği ve biçildiği gün hakkını verin; israf etmeyin, çünkü Allah müsrifleri sevmez.'),
  ('tr.diyanet', 6, 142, 'Hayvanları da yük ve kesim için yaratan Allah\'tır. Allah\'ın size verdiği rızıktan yiyin, şeytana ayak uydurmayın, o size apaçık bir düşmandır.'),
  ('tr.diyanet', 6, 143, 'Sekiz çift: Koyundan iki ve keçiden iki; de ki: "İki erkeği mi, yoksa iki dişiyi mi veya o iki dişinin rahimlerinde bulunan yavruları mı haram kılmıştır? Doğru sözlü iseniz bana bilgiye dayanarak cevap verin."'),
  ('tr.diyanet', 6, 144, 'Deveden iki, sığırdan iki yaratmıştır; de ki: "İki erkeği mi, yoksa iki dişiyi mi veya o iki dişinin rahimlerinde bulunan yavruları mı haram kılmıştır? Yoksa Allah size bunları buyururken orada mı idiniz?" İnsanları, bilmediklerinden sapıtmak için Allah\'a karşı yalan uyduranlardan daha zalim kimdir? Allah, zalim milleti doğru yola eriştirmez.'),
  ('tr.diyanet', 6, 145, 'De ki: "Bana vahyolunanda, leş, akıtılmış kan, domuz eti ki pistir ve günah işlenerek Allah\'tan başkası adına kesilen hayvandan başkasını yemenin haram olduğuna dair bir emir bulamıyorum; fakat darda kalan, başkasının payına el uzatmamak ve zaruret miktarını aşmamak üzere bunlardan da yiyebilir." Doğrusu Rabbin bağışlar ve merhamet eder.'),
  ('tr.diyanet', 6, 146, 'Yahudilere tırnaklı her hayvanı haram kıldık. Onlara sığır ve davarın sırt, bağırsak ve kemik yağları hariç, iç yağlarını da haram kıldık. Aşırı gitmelerinden ötürü onları bu şekilde cezalandırdık. Biz şüphesiz doğru sözlüyüzdür.'),
  ('tr.diyanet', 6, 147, 'Seni yalanlarlarsa, "Rabbinizin rahmeti geniştir; O\'nun azabı suçlu milletten geri çevrilemez" de.'),
  ('tr.diyanet', 6, 148, 'Puta tapanlar, "Allah dileseydi babalarımız ve biz puta tapmaz ve hiçbir şeyi haram kılmazdık" diyecekler; onlardan öncekiler de, Bizim şiddetli azabımızı tadana kadar böyle demişlerdi. Onlara "Bize karşı çıkarabileceğiniz bir bilginiz var mı? Siz ancak zanna uyuyorsunuz ve sadece tahminde bulunuyorsunuz" de.'),
  ('tr.diyanet', 6, 149, '"Üstün delil Allah\'ın delilidir. O dileseydi hepinizi doğru yola eriştirirdi" de.'),
  ('tr.diyanet', 6, 150, 'De ki: "Allah\'ın bunu haram kıldığına şahidlik edecek şahidlerinizi getirin". Şahidlik ederlerse, onlarla beraber olup sözlerini kabullenme; ayetlerimizi yalanlayanların ve ahirete inanmayanların heveslerine uyma; onlar Rablerine başkalarını eşit tutuyorlar.'),
  ('tr.diyanet', 6, 151, 'De ki: "Gelin size Rabbinizin haram kıldığı şeyleri söyleyeyim: O\'na hiçbir şeyi ortak koşmayın, anaya babaya iyilik yapın, yoksulluk korkusuyla çocuklarınızı öldürmeyin, sizin ve onların rızkını veren Biziz, gizli ve açık kötülüklere yaklaşmayın, Allah\'ın haram kıldığı cana haksız yere kıymayın. Allah bunları size düşünesiniz diye buyurmaktadır."'),
  ('tr.diyanet', 6, 152, 'Yetim malına, erginlik çağına erişene kadar en iyi şeklin dışında yaklaşmayın; ölçüyü ve tartıyı doğru yapın. Biz kişiye ancak gücünün yeteceği kadar yükleriz. Konuştuğunuzda, akraba bile olsa sözünüzde adil olun. Allah\'ın ahdini yerine getirin. Allah size bunları öğüt almanız için buyurmaktadır.'),
  ('tr.diyanet', 6, 153, 'Bu, dosdoğru olan yoluma uyun. Sizi Allah yolundan ayrı düşürecek yollara uymayın. Allah size bunları sakınasınız diye buyurmaktadır.'),
  ('tr.diyanet', 6, 154, 'Sonra, iyilik işleyenlere nimeti tamamlamak, her şeyi uzun uzadıya açıklamak, doğruyu göstermek ve rahmet olmak üzere Musa\'ya Kitap\'ı verdik. Rablerine kavuşacaklarına belki artık inanırlar.'),
  ('tr.diyanet', 6, 155, 'Bu, indirdiğimiz kutsal Kitap\'dır, ona uyun. "Bizden önce iki topluluğa kitap indirildi, bizim onların okuduklarından haberimiz yok" demekten veya "Bize kitap indirilseydi onlardan daha doğru yolda olurduk" demekten sakının ki merhamet olunasınız. Şüphesiz o, size Rabbinizden belge, yol gösteren ve rahmet olarak gelmiştir. Allah\'ın ayetlerini yalanlayandan ve onlardan yüz çevirenden daha zalim kimdir? Ayetlerimizden yüz çevirenleri, yüz çevirmelerinden ötürü, kötü bir azabla cezalandıracağız.'),
  ('tr.diyanet', 6, 156, 'Bu, indirdiğimiz kutsal Kitap\'dır, ona uyun. "Bizden önce iki topluluğa kitap indirildi, bizim onların okuduklarından haberimiz yok" demekten veya "Bize kitap indirilseydi onlardan daha doğru yolda olurduk" demekten sakının ki merhamet olunasınız. Şüphesiz o, size Rabbinizden belge, yol gösteren ve rahmet olarak gelmiştir. Allah\'ın ayetlerini yalanlayandan ve onlardan yüz çevirenden daha zalim kimdir? Ayetlerimizden yüz çevirenleri, yüz çevirmelerinden ötürü, kötü bir azabla cezalandıracağız.'),
  ('tr.diyanet', 6, 157, 'Bu, indirdiğimiz kutsal Kitap\'dır, ona uyun. "Bizden önce iki topluluğa kitap indirildi, bizim onların okuduklarından haberimiz yok" demekten veya "Bize kitap indirilseydi onlardan daha doğru yolda olurduk" demekten sakının ki merhamet olunasınız. Şüphesiz o, size Rabbinizden belge, yol gösteren ve rahmet olarak gelmiştir. Allah\'ın ayetlerini yalanlayandan ve onlardan yüz çevirenden daha zalim kimdir? Ayetlerimizden yüz çevirenleri, yüz çevirmelerinden ötürü, kötü bir azabla cezalandıracağız.'),
  ('tr.diyanet', 6, 158, 'Onlar kendilerine meleklerin gelmesini mi, yoksa Rabbinin gelmesini mi, yahut Rablerinden bir takım mucizelerin gelmesini mi bekliyorlar? Rabbinin bir takım mucizeleri geldiği gün, bir kimse daha önce inanmamışsa veya imaniyle bir iyilik kazanmamışsa, imanı ona fayda vermez. Onlara: "Bekleyin, doğrusu biz de bekliyoruz" de.'),
  ('tr.diyanet', 6, 159, 'Fırka fırka olup dinlerini parçalayanlarla senin hiçbir ilişiğin olamaz. Onların işi Allah\'a kalmıştır, yaptıklarını onlara sonra bildirecektir.'),
  ('tr.diyanet', 6, 160, 'Kim ortaya bir iyilik koyarsa ona on katı verilir; ortaya bir kötülük koyan ise ancak misliyle cezalandırılır; onlara haksızlık yapılmaz.'),
  ('tr.diyanet', 6, 161, '"Şüphesiz Rabbim beni doğru yola, gerçek dine, doğruya yönelen ve puta tapanlardan olmayan İbrahim\'in dinine iletmiştir" de.'),
  ('tr.diyanet', 6, 162, 'De ki: "Namazım, ibadetlerim, hayatım ve ölümüm, alemlerin Rabbi Allah içindir.'),
  ('tr.diyanet', 6, 163, 'O\'nun hiçbir ortağı yoktur; böyle emrolundum ve ben Müslümanların ilkiyim."'),
  ('tr.diyanet', 6, 164, 'De ki: "Allah her şeyin Rabbi iken O\'ndan başka bir rab mi arayayım? Herkesin kazandığı kendisinedir, kimse başkasının yükünü taşımaz; sonunda dönüşünüz Rabbinizedir, ayrılığa düştüğünüz şeyleri size bildirecektir."'),
  ('tr.diyanet', 6, 165, 'Verdikleriyle denemek için sizi yeryüzünün halifeleri kılan ve kiminizi kiminize derecelerle üstün yapan O\'dur. Doğrusu Rabbinin cezalandırması süratlidir. Şüphesiz O bağışlar, merhamet eder.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 6, 1, 'Segala puji bagi Allah Yang telah menciptakan langit dan bumi dan mengadakan gelap dan terang, namun orang-orang yang kafir mempersekutukan (sesuatu) dengan Tuhan mereka.'),
  ('id.indonesian', 6, 2, 'Dialah Yang menciptakan kamu dari tanah, sesudah itu ditentukannya ajal (kematianmu), dan ada lagi suatu ajal yang ada pada sisi-Nya (yang Dia sendirilah mengetahuinya), kemudian kamu masih ragu-ragu (tentang berbangkit itu).'),
  ('id.indonesian', 6, 3, 'Dan Dialah Allah (yang disembah), baik di langit maupun di bumi; Dia mengetahui apa yang kamu rahasiakan dan apa yang kamu lahirkan dan mengetahui (pula) apa yang kamu usahakan.'),
  ('id.indonesian', 6, 4, 'Dan tidak ada suatu ayatpun dari ayat-ayat Tuhan sampai kepada mereka, melainkan mereka selalu berpaling dari padanya (mendustakannya).'),
  ('id.indonesian', 6, 5, 'Sesungguhnya mereka telah mendustakan yang haq (Al-Quran) tatkala sampai kepada mereka, maka kelak akan sampai kepada mereka (kenyataan dari) berita-berita yang selalu mereka perolok-olokkan.'),
  ('id.indonesian', 6, 6, 'Apakah mereka tidak memperhatikan berapa banyak generasi yang telah Kami binasakan sebelum mereka, padahal (generasi itu) telah Kami teguhkan kedudukan mereka di muka bumi, yaitu keteguhan yang belum pernah Kami berikan kepadamu, dan Kami curahkan hujan yang lebat atas mereka dan Kami jadikan sungai-sungai mengalir di bawah mereka, kemudian Kami binasakan mereka karena dosa mereka sendiri, dan Kami ciptakan sesudah mereka generasi yang lain.'),
  ('id.indonesian', 6, 7, 'Dan kalau Kami turunkan kepadamu tulisan di atas kertas, lalu mereka dapat menyentuhnya dengan tangan mereka sendiri, tentulah orang-orang kafir itu berkata: "Ini tidak lain hanyalah sihir yang nyata".'),
  ('id.indonesian', 6, 8, 'Dan mereka berkata: "Mengapa tidak diturunkan kepadanya (Muhammad) malaikat?" dan kalau Kami turunkan (kepadanya) malaikat, tentulah selesai urusan itu, kemudian mereka tidak diberi tangguh (sedikitpun).'),
  ('id.indonesian', 6, 9, 'Dan kalau Kami jadikan rasul itu malaikat, tentulah Kami jadikan dia seorang laki-laki dan (kalau Kami jadikan ia seorang laki-laki), tentulah Kami meragu-ragukan atas mereka apa yang mereka ragu-ragukan atas diri mereka sendiri.'),
  ('id.indonesian', 6, 10, 'Dan sungguh telah diperolok-olokkan beberapa rasul sebelum kamu, maka turunlah kepada orang-orang yang mencemoohkan di antara mereka balasan (azab) olok-olokan mereka.'),
  ('id.indonesian', 6, 11, 'Katakanlah: "Berjalanlah di muka bumi, kemudian perhatikanlah bagaimana kesudahan orang-orang yang mendustakan itu".'),
  ('id.indonesian', 6, 12, 'Katakanlah: "Kepunyaan siapakah apa yang ada di langit dan di bumi". Katakanlah: "Kepunyaan Allah". Dia telah menetapkan atas Diri-Nya kasih sayang. Dia sungguh akan menghimpun kamu pada hari kiamat yang tidak ada keraguan padanya. Orang-orang yang meragukan dirinya mereka itu tidak beriman.'),
  ('id.indonesian', 6, 13, 'Dan kepunyaan Allah-lah segala yang ada pada malam dan siang. Dan Dialah Yang Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 14, 'Katakanlah: "Apakah akan aku jadikan pelindung selain dari Allah yang menjadikan langit dan bumi, padahal Dia memberi makan dan tidak memberi makan?" Katakanlah: "Sesungguhnya aku diperintah supaya aku menjadi orang yang pertama kali menyerah diri (kepada Allah), dan jangan sekali-kali kamu masuk golongan orang musyrik".'),
  ('id.indonesian', 6, 15, 'Katakanlah: "Sesungguhnya aku takut akan azab hari yang besar (hari kiamat), jika aku mendurhakai Tuhanku".'),
  ('id.indonesian', 6, 16, 'Barang siapa yang dijauhkan azab dari padanya pada hari itu, maka sungguh Allah telah memberikan rahmat kepadanya. Dan itulah keberuntungan yang nyata.'),
  ('id.indonesian', 6, 17, 'Dan jika Allah menimpakan sesuatu kemudharatan kepadamu, maka tidak ada yang menghilangkannya melainkan Dia sendiri. Dan jika Dia mendatangkan kebaikan kepadamu, maka Dia Maha Kuasa atas tiap-tiap sesuatu.'),
  ('id.indonesian', 6, 18, 'Dan Dialah yang berkuasa atas sekalian hamba-hamba-Nya. Dan Dialah Yang Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 19, 'Katakanlah: "Siapakah yang lebih kuat persaksiannya?" Katakanlah: "Allah". Dia menjadi saksi antara aku dan kamu. Dan Al Quran ini diwahyukan kepadaku supaya dengan dia aku memberi peringatan kepadamu dan kepada orang-orang yang sampai Al-Quran (kepadanya). Apakah sesungguhnya kamu mengakui bahwa ada tuhan-tuhan lain di samping Allah?" Katakanlah: "Aku tidak mengakui". Katakanlah: "Sesungguhnya Dia adalah Tuhan Yang Maha Esa dan sesungguhnya aku berlepas diri dari apa yang kamu persekutukan (dengan Allah)".'),
  ('id.indonesian', 6, 20, 'Orang-orang yang telah Kami berikan kitab kepadanya, mereka mengenalnya (Muhammad) seperti mereka mengenal anak-anaknya sendiri. Orang-orang yang merugikan dirinya, mereka itu tidak beriman (kepada Allah).'),
  ('id.indonesian', 6, 21, 'Dan siapakah yang lebih aniaya daripada orang yang membuat-buat suatu kedustaan terhadap Allah, atau mendustakan ayat-ayat-Nya? Sesungguhnya orang-orang yang aniaya itu tidak mendapat keberuntungan.'),
  ('id.indonesian', 6, 22, 'Dan (ingatlah), hari yang di waktu itu Kami menghimpun mereka semuanya kemudian Kami berkata kepada orang-orang musyrik: "Di manakah sembahan-sembahan kamu yang dulu kamu katakan (sekutu-sekutu) Kami?".'),
  ('id.indonesian', 6, 23, 'Kemudian tiadalah fitnah mereka, kecuali mengatakan: "Demi Allah, Tuhan kami, tiadalah kami mempersekutukan Allah".'),
  ('id.indonesian', 6, 24, 'Lihatlah bagaimana mereka telah berdusta kepada diri mereka sendiri dan hilanglah daripada mereka sembahan-sembahan yang dahulu mereka ada-adakan.'),
  ('id.indonesian', 6, 25, 'Dan di antara mereka ada orang yang mendengarkani (bacaan)mu, padahal Kami telah meletakkan tutupan di atas hati mereka (sehingga mereka tidak) memahaminya dan (Kami letakkan) sumbatan di telinganya. Dan jikapun mereka melihat segala tanda (kebenaran), mereka tetap tidak mau beriman kepadanya. Sehingga apabila mereka datang kepadamu untuk membantahmu, orang-orang kafir itu berkata: "Al-Quran ini tidak lain hanyalah dongengan orang-orang dahulu".'),
  ('id.indonesian', 6, 26, 'Dan mereka melarang (orang lain) mendengarkan Al-Quran dan mereka sendiri menjauhkan diri daripadanya, dan mereka hanyalah membinasakan diri mereka sendiri, sedang mereka tidak menyadari.'),
  ('id.indonesian', 6, 27, 'Dan jika kamu (Muhammad) melihat ketika mereka dihadapkan ke neraka, lalu mereka berkata: "Kiranya kami dikembalikan (ke dunia) dan tidak mendustakan ayat-ayat Tuhan kami, serta menjadi orang-orang yang beriman", (tentulah kamu melihat suatu peristiwa yang mengharukan).'),
  ('id.indonesian', 6, 28, 'Tetapi (sebenarnya) telah nyata bagi mereka kejahatan yang mereka dahulu selalu menyembunyikannya. Sekiranya mereka dikembalikan ke dunia, tentulah mereka kembali kepada apa yang mereka telah dilarang mengerjakannya. Dan sesungguhnya mereka itu adalah pendusta belaka.'),
  ('id.indonesian', 6, 29, 'Dan tentu mereka akan mengatakan (pula): "Hidup hanyalah kehidupan kita di dunia ini saja, dan kita sekali-sekali tidak akan dibangkitkan".'),
  ('id.indonesian', 6, 30, 'Dan seandainya kamu melihat ketika mereka dihadapkan kepada Tuhannya (tentulah kamu melihat peristiwa yang mengharukan). Berfirman Allah: "Bukankah (kebangkitan ini benar?" Mereka menjawab: "Sungguh benar, demi Tuhan kami". Berfirman Allah: "Karena itu rasakanlah azab ini, disebabkan kamu mengingkari(nya)".'),
  ('id.indonesian', 6, 31, 'Sungguh telah rugilah orang-orang yang mendustakan pertemuan mereka dengan Tuhan; sehingga apabila kiamat datang kepada mereka dengan tiba-tiba, mereka berkata: "Alangkah besarnya penyesalan kami, terhadap kelalaian kami tentang kiamat itu!", sambil mereka memikul dosa-dosa di atas punggungnya. Ingatlah, amat buruklah apa yang mereka pikul itu.'),
  ('id.indonesian', 6, 32, 'Dan tiadalah kehidupan dunia ini, selain dari main-main dan senda gurau belaka. Dan sungguh kampung akhirat itu lebih baik bagi orang-orang yang bertakwa. Maka tidakkah kamu memahaminya?'),
  ('id.indonesian', 6, 33, 'Sesungguhnya Kami mengetahui bahwasanya apa yang mereka katakan itu menyedihkan hatimu, (janganlah kamu bersedih hati), karena mereka sebenarnya bukan mendustakan kamu, akan tetapi orang-orang yang zalim itu mengingkari ayat-ayat Allah.'),
  ('id.indonesian', 6, 34, 'Dan sesungguhnya telah didustakan (pula) rasul-rasul sebelum kamu, akan tetapi mereka sabar terhadap pendustaan dan penganiayaan (yang dilakukan) terhadap mereka, sampai datang pertolongan Allah kepada mereka. Tak ada seorangpun yang dapat merubah kalimat-kalimat (janji-janji) Allah. Dan sesungguhnya telah datang kepadamu sebahagian dari berita rasul-rasul itu.'),
  ('id.indonesian', 6, 35, 'Dan jika perpalingan mereka (darimu) terasa amat berat bagimu, maka jika kamu dapat membuat lobang di bumi atau tangga ke langit lalu kamu dapat mendatangkan mukjizat kepada mereka (maka buatlah). Kalau Allah menghendaki, tentu saja Allah menjadikan mereka semua dalam petunjuk sebab itu janganlah sekali-kali kamu termasuk orang-orang yang jahil'),
  ('id.indonesian', 6, 36, 'Hanya mereka yang mendengar sajalah yang mematuhi (seruan Allah), dan orang-orang yang mati (hatinya), akan dibangkitkan oleh Allah, kemudian kepada-Nya-lah mereka dikembalikan.'),
  ('id.indonesian', 6, 37, 'Dan mereka (orang-orang musyrik Mekah) berkata: "Mengapa tidak diturunkan kepadanya (Muhammad) suatu mukjizat dari Tuhannya?" Katakanlah: "Sesungguhnya Allah kuasa menurunkan suatu mukjizat, tetapi kebanyakan mereka tidak mengetahui".'),
  ('id.indonesian', 6, 38, 'Dan tiadalah binatang-binatang yang ada di bumi dan burung-burung yang terbang dengan kedua sayapnya, melainkan umat (juga) seperti kamu. Tiadalah Kami alpakan sesuatupun dalam Al-Kitab, kemudian kepada Tuhanlah mereka dihimpunkan.'),
  ('id.indonesian', 6, 39, 'Dan orang-orang yang mendustakan ayat-ayat Kami adalah pekak, bisu dan berada dalam gelap gulita. Barangsiapa yang dikehendaki Allah (kesesatannya), niscaya disesatkan-Nya. Dan barangsiapa yang dikehendaki Allah (untuk diberi-Nya petunjuk), niscaya Dia menjadikan-Nya berada di atas jalan yang lurus.'),
  ('id.indonesian', 6, 40, 'Katakanlah: "Terangkanlah kepadaku jika datang siksaan Allah kepadamu, atau datang kepadamu hari kiamat, apakah kamu menyeru (tuhan) selain Allah; jika kamu orang-orang yang benar!"'),
  ('id.indonesian', 6, 41, '(Tidak), tetapi hanya Dialah yang kamu seru, maka Dia menghilangkan bahaya yang karenanya kamu berdoa kepada-Nya, jika Dia menghendaki, dan kamu tinggalkan sembahan-sembahan yang kamu sekutukan (dengan Allah).'),
  ('id.indonesian', 6, 42, 'Dan sesungguhnya Kami telah mengutus (rasul-rasul) kepada umat-umat yang sebelum kamu, kemudian Kami siksa mereka dengan (menimpakan) kesengsaraan dan kemelaratan, supaya mereka memohon (kepada Allah) dengan tunduk merendahkan diri.'),
  ('id.indonesian', 6, 43, 'Maka mengapa mereka tidak memohon (kepada Allah) dengan tunduk merendahkan diri ketika datang siksaan Kami kepada mereka, bahkan hati mereka telah menjadi keras, dan syaitanpun menampakkan kepada mereka kebagusan apa yang selalu mereka kerjakan.'),
  ('id.indonesian', 6, 44, 'Maka tatkala mereka melupakan peringatan yang telah diberikan kepada mereka, Kamipun membukakan semua pintu-pintu kesenangan untuk mereka; sehingga apabila mereka bergembira dengan apa yang telah diberikan kepada mereka, Kami siksa mereka dengan sekonyong-konyong, maka ketika itu mereka terdiam berputus asa.'),
  ('id.indonesian', 6, 45, 'Maka orang-orang yang zalim itu dimusnahkan sampai ke akar-akarnya. Segala puji bagi Allah, Tuhan semesta alam.'),
  ('id.indonesian', 6, 46, 'Katakanlah: "Terangkanlah kepadaku jika Allah mencabut pendengaran dan penglihatan serta menutup hatimu, siapakah tuhan selain Allah yang kuasa mengembalikannya kepadamu?" Perhatikanlah bagaimana Kami berkali-kali memperlihatkan tanda-tanda kebesaran (Kami), kemudian mereka tetap berpaling (juga).'),
  ('id.indonesian', 6, 47, 'Katakanlah: "Terangkanlah kepadaku jika datang siksaan Allah kepadamu dengan sekonyong-konyong, atau terang-terangan, maka adakah yang dibinasakan (Allah) selain dari orang yang zalim?"'),
  ('id.indonesian', 6, 48, 'Dan tidaklah Kami mengutus para rasul itu melainkan untuk memberikan kabar gembira dan memberi peringatan. Barangsiapa yang beriman dan mengadakan perbaikan, maka tak ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati.'),
  ('id.indonesian', 6, 49, 'Dan orang-orang yang mendustakan ayat-ayat Kami, mereka akan ditimpa siksa disebabkan mereka selalu berbuat fasik.'),
  ('id.indonesian', 6, 50, 'Katakanlah: Aku tidak mengatakan kepadamu, bahwa perbendaharaan Allah ada padaku, dan tidak (pula) aku mengetahui yang ghaib dan tidak (pula) aku mengatakan kepadamu bahwa aku seorang malaikat. Aku tidak mengikuti kecuali apa yang diwahyukan kepadaku. Katakanlah: "Apakah sama orang yang buta dengan yang melihat?" Maka apakah kamu tidak memikirkan(nya)?"'),
  ('id.indonesian', 6, 51, 'Dan berilah peringatan dengan apa yang diwahyukan itu kepada orang-orang yang takut akan dihimpunkan kepada Tuhannya (pada hari kiamat), sedang bagi mereka tidak ada seorang pelindung dan pemberi syafa\'atpun selain daripada Allah, agar mereka bertakwa.'),
  ('id.indonesian', 6, 52, 'Dan janganlah kamu mengusir orang-orang yang menyeru Tuhannya di pagi dan petang hari, sedang mereka menghendaki keridhaan-Nya. Kamu tidak memikul tanggung jawab sedikitpun terhadap perbuatan mereka dan merekapun tidak memikul tanggung jawab sedikitpun terhadap perbuatanmu, yang menyebabkan kamu (berhak) mengusir mereka, (sehingga kamu termasuk orang-orang yang zalim).'),
  ('id.indonesian', 6, 53, 'Dan demikianlah telah Kami uji sebahagian mereka (orang-orang kaya) dengan sebahagian mereka (orang-orang miskin), supaya (orang-orang yang kaya itu) berkata: "Orang-orang semacam inikah di antara kita yang diberi anugerah Allah kepada mereka?" (Allah berfirman): "Tidakkah Allah lebih mengetahui tentang orang-orang yang bersyukur (kepada-Nya)?"'),
  ('id.indonesian', 6, 54, 'Apabila orang-orang yang beriman kepada ayat-ayat Kami itu datang kepadamu, maka katakanlah: "Salaamun alaikum. Tuhanmu telah menetapkan atas diri-Nya kasih sayang, (yaitu) bahwasanya barang siapa yang berbuat kejahatan di antara kamu lantaran kejahilan, kemudian ia bertaubat setelah mengerjakannya dan mengadakan perbaikan, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 6, 55, 'Dan demikianlah Kami terangkan ayat-ayat Al-Quran (supaya jelas jalan orang-orang yang saleh, dan supaya jelas (pula) jalan orang-orang yang berdosa.'),
  ('id.indonesian', 6, 56, 'Katakanlah: "Sesungguhnya aku dilarang menyembah tuhan-tuhan yang kamu sembah selain Allah". Katakanlah: "Aku tidak akan mengikuti hawa nafsumu, sungguh tersesatlah aku jika berbuat demikian dan tidaklah (pula) aku termasuk orang-orang yang mendapat petunjuk".'),
  ('id.indonesian', 6, 57, 'Katakanlah: "Sesungguhnya aku berada di atas hujjah yang nyata (Al Quran) dari Tuhanku, sedang kamu mendustakannya. Tidak ada padaku apa (azab) yang kamu minta supaya disegerakan kedatangannya. Menetapkan hukum itu hanyalah hak Allah. Dia menerangkan yang sebenarnya dan Dia Pemberi keputusan yang paling baik".'),
  ('id.indonesian', 6, 58, 'Katakanlah: "Kalau sekiranya ada padaku apa (azab) yang kamu minta supaya disegerakan, tentu telah diselesaikan Allah urusan yang ada antara aku dan kamu. Dan Allah lebih mengetahui tentang orang-orang yang zalim.'),
  ('id.indonesian', 6, 59, 'Dan pada sisi Allah-lah kunci-kunci semua yang ghaib; tidak ada yang mengetahuinya kecuali Dia sendiri, dan Dia mengetahui apa yang di daratan dan di lautan, dan tiada sehelai daun pun yang gugur melainkan Dia mengetahuinya (pula), dan tidak jatuh sebutir biji-pun dalam kegelapan bumi, dan tidak sesuatu yang basah atau yang kering, melainkan tertulis dalam kitab yang nyata (Lauh Mahfudz)"'),
  ('id.indonesian', 6, 60, 'Dan Dialah yang menidurkan kamu di malam hari dan Dia mengetahui apa yang kamu kerjakan di siang hari, kemudian Dia membangunkan kamu pada siang hari untuk disempurnakan umur(mu) yang telah ditentukan, kemudian kepada Allah-lah kamu kembali, lalu Dia memberitahukan kepadamu apa yang dahulu kamu kerjakan.'),
  ('id.indonesian', 6, 61, 'Dan Dialah yang mempunyai kekuasaan tertinggi di atas semua hamba-Nya, dan diutus-Nya kepadamu malaikat-malaikat penjaga, sehingga apabila datang kematian kepada salah seorang di antara kamu, ia diwafatkan oleh malaikat-malaikat Kami, dan malaikat-malaikat Kami itu tidak melalaikan kewajibannya.'),
  ('id.indonesian', 6, 62, 'Kemudian mereka (hamba Allah) dikembalikan kepada Allah, Penguasa mereka yang sebenarnya. Ketahuilah bahwa segala hukum (pada hari itu) kepunyaan-Nya. Dan Dialah Pembuat Perhitungan yang paling cepat.'),
  ('id.indonesian', 6, 63, 'Katakanlah: "Siapakah yang dapat menyelamatkan kamu dari bencana di darat dan di laut, yang kamu berdoa kepada-Nya dengan rendah diri dengan suara yang lembut (dengan mengatakan: "Sesungguhnya jika Dia menyelamatkan kami dari (bencana) ini, tentulah kami menjadi orang-orang yang bersyukur"".'),
  ('id.indonesian', 6, 64, 'Katakanlah: "Allah menyelamatkan kamu dari bencana itu dan dari segala macam kesusahan, kemudian kamu kembali mempersekutukan-Nya".'),
  ('id.indonesian', 6, 65, 'Katakanlah: "Dialah yang berkuasa untuk mengirimkan azab kepadamu, dari atas kamu atau dari bawah kakimu atau Dia mencampurkan kamu dalam golongan-golongan (yang saling bertentangan) dan merasakan kepada sebahagian kamu keganasan sebahagian yang lain. Perhatikanlah, betapa Kami mendatangkan tanda-tanda kebesaran Kami silih berganti agar mereka memahami(nya)".'),
  ('id.indonesian', 6, 66, 'Dan kaummu mendustakannya (azab) padahal azab itu benar adanya. Katakanlah: "Aku ini bukanlah orang yang diserahi mengurus urusanmu".'),
  ('id.indonesian', 6, 67, 'Untuk setiap berita (yang dibawa oleh rasul-rasul) ada (waktu) terjadinya dan kelak kamu akan mengetahui.'),
  ('id.indonesian', 6, 68, 'Dan apabila kamu melihat orang-orang memperolok-olokkan ayat-ayat Kami, maka tinggalkanlah mereka sehingga mereka membicarakan pembicaraan yang lain. Dan jika syaitan menjadikan kamu lupa (akan larangan ini), maka janganlah kamu duduk bersama orang-orang yang zalim itu sesudah teringat (akan larangan itu).'),
  ('id.indonesian', 6, 69, 'Dan tidak ada pertanggungjawaban sedikitpun atas orang-orang yang bertakwa terhadap dosa mereka; akan tetapi (kewajiban mereka ialah) mengingatkan agar mereka bertakwa.'),
  ('id.indonesian', 6, 70, 'Dan tinggalkan lah orang-orang yang menjadikan agama mereka sebagai main-main dan senda gurau, dan mereka telah ditipu oleh kehidupan dunia. Peringatkanlah (mereka) dengan Al-Quran itu agar masing-masing diri tidak dijerumuskan ke dalam neraka, karena perbuatannya sendiri. Tidak akan ada baginya pelindung dan tidak pula pemberi syafa\'at selain daripada Allah. Dan jika ia menebus dengan segala macam tebusanpun, niscaya tidak akan diterima itu daripadanya. Mereka itulah orang-orang yang dijerumuskan ke dalam neraka. Bagi mereka (disediakan) minuman dari air yang sedang mendidih dan azab yang pedih disebabkan kekafiran mereka dahulu.'),
  ('id.indonesian', 6, 71, 'Katakanlah: "Apakah kita akan menyeru selain daripada Allah, sesuatu yang tidak dapat mendatangkan kemanfaatan kepada kita dan tidak (pula) mendatangkan kemudharatan kepada kita dan (apakah) kita akan kembali ke belakang, sesudah Allah memberi petunjuk kepada kita, seperti orang yang telah disesatkan oleh syaitan di pesawangan yang menakutkan; dalam keadaan bingung, dia mempunyai kawan-kawan yang memanggilnya kepada jalan yang lurus (dengan mengatakan): "Marilah ikuti kami". Katakanlah: "Sesungguhnya petunjuk Allah itulah (yang sebenarnya) petunjuk; dan kita disuruh agar menyerahkan diri kepada Tuhan semesta alam,'),
  ('id.indonesian', 6, 72, 'dan agar mendirikan sembahyang serta bertakwa kepada-Nya". Dan Dialah Tuhan yang kepada-Nya-lah kamu akan dihimpunkan.'),
  ('id.indonesian', 6, 73, 'Dan Dialah yang menciptakan langit dan bumi dengan benar. Dan benarlah perkataan-Nya di waktu Dia mengatakan: "Jadilah, lalu terjadilah", dan di tangan-Nya-lah segala kekuasaan di waktu sangkakala ditiup. Dia mengetahui yang ghaib dan yang nampak. Dan Dialah Yang Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 74, 'Dan (ingatlah) di waktu Ibrahim berkata kepada bapaknya, Aazar, "Pantaskah kamu menjadikan berhala-berhala sebagai tuhan-tuhan? Sesungguhnya aku melihat kamu dan kaummu dalam kesesatan yang nyata".'),
  ('id.indonesian', 6, 75, 'Dan demikianlah Kami perlihatkan kepada Ibrahim tanda-tanda keagungan (Kami yang terdapat) di langit dan bumi dan (Kami memperlihatkannya) agar dia termasuk orang yang yakin.'),
  ('id.indonesian', 6, 76, 'Ketika malam telah gelap, dia melihat sebuah bintang (lalu) dia berkata: "Inilah Tuhanku", tetapi tatkala bintang itu tenggelam dia berkata: "Saya tidak suka kepada yang tenggelam".'),
  ('id.indonesian', 6, 77, 'Kemudian tatkala dia melihat bulan terbit dia berkata: "Inilah Tuhanku". Tetapi setelah bulan itu terbenam, dia berkata: "Sesungguhnya jika Tuhanku tidak memberi petunjuk kepadaku, pastilah aku termasuk orang yang sesat".'),
  ('id.indonesian', 6, 78, 'Kemudian tatkala ia melihat matahari terbit, dia berkata: "Inilah Tuhanku, ini yang lebih besar". Maka tatkala matahari itu terbenam, dia berkata: "Hai kaumku, sesungguhnya aku berlepas diri dari apa yang kamu persekutukan.'),
  ('id.indonesian', 6, 79, 'Sesungguhnya aku menghadapkan diriku kepada Rabb yang menciptakan langit dan bumi, dengan cenderung kepada agama yang benar, dan aku bukanlah termasuk orang-orang yang mempersekutukan Tuhan.'),
  ('id.indonesian', 6, 80, 'Dan dia dibantah oleh kaumnya. Dia berkata: "Apakah kamu hendak membantah tentang Allah, padahal sesungguhnya Allah telah memberi petunjuk kepadaku". Dan aku tidak takut kepada (malapetaka dari) sembahan-sembahan yang kamu persekutukan dengan Allah, kecuali di kala Tuhanku menghendaki sesuatu (dari malapetaka) itu. Pengetahuan Tuhanku meliputi segala sesuatu. Maka apakah kamu tidak dapat mengambil pelajaran (daripadanya)?"'),
  ('id.indonesian', 6, 81, 'Bagaimana aku takut kepada sembahan-sembahan yang kamu persekutukan (dengan Allah), padahal kamu tidak mempersekutukan Allah dengan sembahan-sembahan yang Allah sendiri tidak menurunkan hujjah kepadamu untuk mempersekutukan-Nya. Maka manakah di antara dua golongan itu yang lebih berhak memperoleh keamanan (dari malapetaka), jika kamu mengetahui?'),
  ('id.indonesian', 6, 82, 'Orang-orang yang beriman dan tidak mencampuradukkan iman mereka dengan kezaliman (syirik), mereka itulah yang mendapat keamanan dan mereka itu adalah orang-orang yang mendapat petunjuk.'),
  ('id.indonesian', 6, 83, 'Dan itulah hujjah Kami yang Kami berikan kepada Ibrahim untuk menghadapi kaumnya. Kami tinggikan siapa yang Kami kehendaki beberapa derajat. Sesungguhnya Tuhanmu Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 84, 'Dan Kami telah menganugerahkan Ishak dan Ya\'qub kepadanya. Kepada keduanya masing-masing telah Kami beri petunjuk; dan kepada Nuh sebelum itu (juga) telah Kami beri petunjuk, dan kepada sebahagian dari keturunannya (Nuh) yaitu Daud, Sulaiman, Ayyub, Yusuf, Musa dan Harun. Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 6, 85, 'dan Zakaria, Yahya, Isa dan Ilyas. Semuanya termasuk orang-orang yang shaleh.'),
  ('id.indonesian', 6, 86, 'dan Ismail, Alyasa\', Yunus dan Luth. Masing-masing Kami lebihkan derajatnya di atas umat (di masanya),'),
  ('id.indonesian', 6, 87, 'Dan Kami lebihkan (pula) derajat sebahagian dari bapak-bapak mereka, keturunan dan saudara-saudara mereka. Dan Kami telah memilih mereka (untuk menjadi nabi-nabi dan rasul-rasul) dan Kami menunjuki mereka ke jalan yang lurus.'),
  ('id.indonesian', 6, 88, 'Itulah petunjuk Allah, yang dengannya Dia memberi petunjuk kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya. Seandainya mereka mempersekutukan Allah, niscaya lenyaplah dari mereka amalan yang telah mereka kerjakan.'),
  ('id.indonesian', 6, 89, 'Mereka itulah orang-orang yang telah Kami berikan kitab, hikmat dan kenabian Jika orang-orang (Quraisy) itu mengingkarinya, maka sesungguhnya Kami akan menyerahkannya kepada kaum yang sekali-kali tidak akan mengingkarinya.'),
  ('id.indonesian', 6, 90, 'Mereka itulah orang-orang yang telah diberi petunjuk oleh Allah, maka ikutilah petunjuk mereka. Katakanlah: "Aku tidak meminta upah kepadamu dalam menyampaikan (Al-Quran)". Al-Quran itu tidak lain hanyalah peringatan untuk seluruh ummat.'),
  ('id.indonesian', 6, 91, 'Dan mereka tidak menghormati Allah dengan penghormatan yang semestinya, di kala mereka berkata: "Allah tidak menurunkan sesuatupun kepada manusia". Katakanlah: "Siapakah yang menurunkan kitab (Taurat) yang dibawa oleh Musa sebagai cahaya dan petunjuk bagi manusia, kamu jadikan kitab itu lembaran-lembaran kertas yang bercerai-berai, kamu perlihatkan (sebahagiannya) dan kamu sembunyikan sebahagian besarnya, padahal telah diajarkan kepadamu apa yang kamu dan bapak-bapak kamu tidak mengetahui(nya)?" Katakanlah: "Allah-lah (yang menurunkannya)", kemudian (sesudah kamu menyampaikan Al Quran kepada mereka), biarkanlah mereka bermain-main dalam kesesatannya.'),
  ('id.indonesian', 6, 92, 'Dan ini (Al Quran) adalah kitab yang telah Kami turunkan yang diberkahi; membenarkan kitab-kitab yang (diturunkan) sebelumnya dan agar kamu memberi peringatan kepada (penduduk) Ummul Qura (Mekah) dan orang-orang yang di luar lingkungannya. Orang-orang yang beriman kepada adanya kehidupan akhirat tentu beriman kepadanya (Al Quran) dan mereka selalu memelihara sembahyangnya.'),
  ('id.indonesian', 6, 93, 'Dan siapakah yang lebih zalim daripada orang yang membuat kedustaan terhadap Allah atau yang berkata: "Telah diwahyukan kepada saya", padahal tidak ada diwahyukan sesuatupun kepadanya, dan orang yang berkata: "Saya akan menurunkan seperti apa yang diturunkan Allah". Alangkah dahsyatnya sekiranya kamu melihat di waktu orang-orang yang zalim berada dalam tekanan sakratul maut, sedang para malaikat memukul dengan tangannya, (sambil berkata): "Keluarkanlah nyawamu" Di hari ini kamu dibalas dengan siksa yang sangat menghinakan, karena kamu selalu mengatakan terhadap Allah (perkataan) yang tidak benar dan (karena) kamu selalu menyombongkan diri terhadap ayat-ayat-Nya.'),
  ('id.indonesian', 6, 94, 'Dan sesungguhnya kamu datang kepada Kami sendiri-sendiri sebagaimana kamu Kami ciptakan pada mulanya, dan kamu tinggalkan di belakangmu (di dunia) apa yang telah Kami karuniakan kepadamu; dan Kami tiada melihat besertamu pemberi syafa\'at yang kamu anggap bahwa mereka itu sekutu-sekutu Tuhan di antara kamu. Sungguh telah terputuslah (pertalian) antara kamu dan telah lenyap daripada kamu apa yang dahulu kamu anggap (sebagai sekutu Allah).'),
  ('id.indonesian', 6, 95, 'Sesungguhnya Allah menumbuhkan butir tumbuh-tumbuhan dan biji buah-buahan. Dia mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup. (Yang memiliki sifat-sifat) demikian ialah Allah, maka mengapa kamu masih berpaling?'),
  ('id.indonesian', 6, 96, 'Dia menyingsingkan pagi dan menjadikan malam untuk beristirahat, dan (menjadikan) matahari dan bulan untuk perhitungan. Itulah ketentuan Allah Yang Maha Perkasa lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 97, 'Dan Dialah yang menjadikan bintang-bintang bagimu, agar kamu menjadikannya petunjuk dalam kegelapan di darat dan di laut. Sesungguhnya Kami telah menjelaskan tanda-tanda kebesaran (Kami) kepada orang-orang yang mengetahui.'),
  ('id.indonesian', 6, 98, 'Dan Dialah yang menciptakan kamu dari seorang diri, maka (bagimu) ada tempat tetap dan tempat simpanan. Sesungguhnya telah Kami jelaskan tanda-tanda kebesaran Kami kepada orang-orang yang mengetahui.'),
  ('id.indonesian', 6, 99, 'Dan Dialah yang menurunkan air hujan dari langit, lalu Kami tumbuhkan dengan air itu segala macam tumbuh-tumbuhan maka Kami keluarkan dari tumbuh-tumbuhan itu tanaman yang menghijau. Kami keluarkan dari tanaman yang menghijau itu butir yang banyak; dan dari mayang korma mengurai tangkai-tangkai yang menjulai, dan kebun-kebun anggur, dan (Kami keluarkan pula) zaitun dan delima yang serupa dan yang tidak serupa. Perhatikanlah buahnya di waktu pohonnya berbuah dan (perhatikan pulalah) kematangannya. Sesungguhnya pada yang demikian itu ada tanda-tanda (kekuasaan Allah) bagi orang-orang yang beriman.'),
  ('id.indonesian', 6, 100, 'Dan mereka (orang-orang musyrik) menjadikan jin itu sekutu bagi Allah, padahal Allah-lah yang menciptakan jin-jin itu, dan mereka membohong (dengan mengatakan): "Bahwasanya Allah mempunyai anak laki-laki dan perempuan", tanpa (berdasar) ilmu pengetahuan. Maha Suci Allah dan Maha Tinggi dari sifat-sifat yang mereka berikan.'),
  ('id.indonesian', 6, 101, 'Dia Pencipta langit dan bumi. Bagaimana Dia mempunyai anak padahal Dia tidak mempunyai isteri. Dia menciptakan segala sesuatu; dan Dia mengetahui segala sesuatu.'),
  ('id.indonesian', 6, 102, '(Yang memiliki sifat-sifat yang) demikian itu ialah Allah Tuhan kamu; tidak ada Tuhan selain Dia; Pencipta segala sesuatu, maka sembahlah Dia; dan Dia adalah Pemelihara segala sesuatu.'),
  ('id.indonesian', 6, 103, 'Dia tidak dapat dicapai oleh penglihatan mata, sedang Dia dapat melihat segala yang kelihatan; dan Dialah Yang Maha Halus lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 104, 'Sesungguhnya telah datang dari Tuhanmu bukti-bukti yang terang; maka barangsiapa melihat (kebenaran itu), maka (manfaatnya) bagi dirinya sendiri; dan barangsiapa buta (tidak melihat kebenaran itu), maka kemudharatannya kembali kepadanya. Dan aku (Muhammad) sekali-kali bukanlah pemelihara(mu).'),
  ('id.indonesian', 6, 105, 'Demikianlah Kami mengulang-ulangi ayat-ayat Kami supaya (orang-orang yang beriman mendapat petunjuk) dan supaya orang-orang musyrik mengatakan: "Kamu telah mempelajari ayat-ayat itu (dari Ahli Kitab)", dan supaya Kami menjelaskan Al Quran itu kepada orang-orang yang mengetahui.'),
  ('id.indonesian', 6, 106, 'Ikutilah apa yang telah diwahyukan kepadamu dari Tuhanmu; tidak ada Tuhan selain Dia; dan berpalinglah dari orang-orang musyrik.'),
  ('id.indonesian', 6, 107, 'Dan kalau Allah menghendaki, niscaya mereka tidak memperkutukan(Nya). Dan Kami tidak menjadikan kamu pemelihara bagi mereka; dan kamu sekali-kali bukanlah pemelihara bagi mereka.'),
  ('id.indonesian', 6, 108, 'Dan janganlah kamu memaki sembahan-sembahan yang mereka sembah selain Allah, karena mereka nanti akan memaki Allah dengan melampaui batas tanpa pengetahuan. Demikianlah Kami jadikan setiap umat menganggap baik pekerjaan mereka. Kemudian kepada Tuhan merekalah kembali mereka, lalu Dia memberitakan kepada mereka apa yang dahulu mereka kerjakan.'),
  ('id.indonesian', 6, 109, 'Mereka bersumpah dengan nama Allah dengan segala kesungguhan, bahwa sungguh jika datang kepada mereka sesuatu mu jizat, pastilah mereka beriman kepada-Nya. Katakanlah: "Sesungguhnya mukjizat-mukjizat itu hanya berada di sisi Allah". Dan apakah yang memberitahukan kepadamu bahwa apabila mukjizat datang mereka tidak akan beriman.'),
  ('id.indonesian', 6, 110, 'Dan (begitu pula) Kami memalingkan hati dan penglihatan mereka seperti mereka belum pernah beriman kepadanya (Al Quran) pada permulaannya, dan Kami biarkan mereka bergelimang dalam kesesatannya yang sangat.'),
  ('id.indonesian', 6, 111, 'Kalau sekiranya Kami turunkan malaikat kepada mereka, dan orang-orang yang telah mati berbicara dengan mereka dan Kami kumpulkan (pula) segala sesuatu ke hadapan mereka, niscaya mereka tidak (juga) akan beriman, kecuali jika Allah menghendaki, tetapi kebanyakan mereka tidak mengetahui.'),
  ('id.indonesian', 6, 112, 'Dan demikianlah Kami jadikan bagi tiap-tiap nabi itu musuh, yaitu syaitan-syaitan (dari jenis) manusia dan (dan jenis) jin, sebahagian mereka membisikkan kepada sebahagian yang lain perkataan-perkataan yang indah-indah untuk menipu (manusia). Jikalau Tuhanmu menghendaki, niscaya mereka tidak mengerjakannya, maka tinggalkanlah mereka dan apa yang mereka ada-adakan.'),
  ('id.indonesian', 6, 113, 'Dan (juga) agar hati kecil orang-orang yang tidak beriman kepada kehidupan akhirat cenderung kepada bisikan itu, mereka merasa senang kepadanya dan supaya mereka mengerjakan apa yang mereka (syaitan) kerjakan.'),
  ('id.indonesian', 6, 114, 'Maka patutkah aku mencari hakim selain daripada Allah, padahal Dialah yang telah menurunkan kitab (Al Quran) kepadamu dengan terperinci? Orang-orang yang telah Kami datangkan kitab kepada mereka, mereka mengetahui bahwa Al Quran itu diturunkan dari Tuhanmu dengan sebenarnya. Maka janganlah kamu sekali-kali termasuk orang yang ragu-ragu.'),
  ('id.indonesian', 6, 115, 'Telah sempurnalah kalimat Tuhanmu (Al-Quran) sebagai kalimat yang benar dan adil. Tidak ada yang dapat merubah rubah kalimat-kalimat-Nya dan Dialah yang Maha Mendenyar lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 116, 'Dan jika kamu menuruti kebanyakan orang-orang yang di muka bumi ini, niscaya mereka akan menyesatkanmu dari jalan Allah. Mereka tidak lain hanyalah mengikuti persangkaan belaka, dan mereka tidak lain hanyalah berdusta (terhadap Allah).'),
  ('id.indonesian', 6, 117, 'Sesungguhnya Tuhanmu, Dialah yang lebih mengetahui tentang orang yang tersesat dari jalan-Nya dan Dia lebih mengetahui tentang orang orang yang mendapat petunjuk.'),
  ('id.indonesian', 6, 118, 'Maka makanlah binatang-binatang (yang halal) yang disebut nama Allah ketika menyembelihnya, jika kamu beriman kepada ayat-ayat-Nya.'),
  ('id.indonesian', 6, 119, 'Mengapa kamu tidak mau memakan (binatang-binatang yang halal) yang disebut nama Allah ketika menyembelihnya, padahal sesungguhnya Allah telah menjelaskan kepada kamu apa yang diharamkan-Nya atasmu, kecuali apa yang terpaksa kamu memakannya. Dan sesungguhnya kebanyakan (dari manusia) benar benar hendak menyesatkan (orang lain) dengan hawa nafsu mereka tanpa pengetahuan. Sesungguhnya Tuhanmu, Dialah yang lebih mengetahui orang-orang yang melampaui batas.'),
  ('id.indonesian', 6, 120, 'Dan tinggalkanlah dosa yang nampak dan yang tersembunyi. Sesungguhnya orang yang mengerjakan dosa, kelak akan diberi pembalasan (pada hari kiamat), disebabkan apa yang mereka telah kerjakan.'),
  ('id.indonesian', 6, 121, 'Dan janganlah kamu memakan binatang-binatang yang tidak disebut nama Allah ketika menyembelihnya. Sesungguhnya perbuatan yang semacam itu adalah suatu kefasikan. Sesungguhnya syaitan itu membisikkan kepada kawan-kawannya agar mereka membantah kamu; dan jika kamu menuruti mereka, sesungguhnya kamu tentulah menjadi orang-orang yang musyrik.'),
  ('id.indonesian', 6, 122, 'Dan apakah orang yang sudah mati kemudian dia Kami hidupkan dan Kami berikan kepadanya cahaya yang terang, yang dengan cahaya itu dia dapat berjalan di tengah-tengah masyarakat manusia, serupa dengan orang yang keadaannya berada dalam gelap gulita yang sekali-kali tidak dapat keluar dari padanya? Demikianlah Kami jadikan orang yang kafir itu memandang baik apa yang telah mereka kerjakan.'),
  ('id.indonesian', 6, 123, 'Dan demikianlah Kami adakan pada tiap-tiap negeri penjahat-penjahat yang terbesar agar mereka melakukan tipu daya dalam negeri itu. Dan mereka tidak memperdayakan melainkan dirinya sendiri, sedang mereka tidak menyadarinya.'),
  ('id.indonesian', 6, 124, 'Apabila datang sesuatu ayat kepada mereka, mereka berkata: "Kami tidak akan beriman sehingga diberikan kepada kami yang serupa dengan apa yang telah diberikan kepada utusan-utusan Allah". Allah lebih mengetahui di mana Dia menempatkan tugas kerasulan. Orang-orang yang berdosa, nanti akan ditimpa kehinaan di sisi Allah dan siksa yang keras disebabkan mereka selalu membuat tipu daya.'),
  ('id.indonesian', 6, 125, 'Barangsiapa yang Allah menghendaki akan memberikan kepadanya petunjuk, niscaya Dia melapangkan dadanya untuk (memeluk agama) Islam. Dan barangsiapa yang dikehendaki Allah kesesatannya, niscaya Allah menjadikan dadanya sesak lagi sempit, seolah-olah ia sedang mendaki langit. Begitulah Allah menimpakan siksa kepada orang-orang yang tidak beriman.'),
  ('id.indonesian', 6, 126, 'Dan inilah jalan Tuhanmu; (jalan) yang lurus. Sesungguhnya Kami telah menjelaskan ayat-ayat (Kami) kepada orang-orang yang mengambil pelajaran.'),
  ('id.indonesian', 6, 127, 'Bagi mereka (disediakan) darussalam (surga) pada sisi Tuhannya dan Dialah Pelindung mereka disebabkan amal-amal saleh yang selalu mereka kerjakan.'),
  ('id.indonesian', 6, 128, 'Dan (ingatlah) hari diwaktu Allah menghimpunkan mereka semuanya (dan Allah berfirman): "Hai golongan jin, sesungguhnya kamu telah banyak menyesatkan manusia", lalu berkatalah kawan-kawan meraka dari golongan manusia: "Ya Tuhan kami, sesungguhnya sebahagian daripada kami telah dapat kesenangan dari sebahagian (yang lain) dan kami telah sampai kepada waktu yang telah Engkau tentukan bagi kami". Allah berfirman: "Neraka itulah tempat diam kamu, sedang kamu kekal di dalamnya, kecuali kalau Allah menghendaki (yang lain)". Sesungguhnya Tuhanmu Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 129, 'Dan demikianlah Kami jadikan sebahagian orang-orang yang zalim itu menjadi teman bagi sebahagian yang lain disebabkan apa yang mereka usahakan.'),
  ('id.indonesian', 6, 130, 'Hai golongan jin dan manusia, apakah belum datang kepadamu rasul-rasul dari golongan kamu sendiri, yang menyampaikan kepadamu ayat-ayat-Ku dan memberi peringatan kepadamu terhadap pertemuanmu dengan hari ini? Mereka berkata: "Kami menjadi saksi atas diri kami sendiri", kehidupan dunia telah menipu mereka, dan mereka menjadi saksi atas diri mereka sendiri, bahwa mereka adalah orang-orang yang kafir.'),
  ('id.indonesian', 6, 131, 'Yang demikian itu adalah karena Tuhanmu tidaklah membinasakan kota-kota secara aniaya, sedang penduduknya dalam keadaan lengah.'),
  ('id.indonesian', 6, 132, 'Dan masing-masing orang memperoleh derajat-derajat (seimbang) dengan apa yang dikerjakannya. Dan Tuhanmu tidak lengah dari apa yang mereka kerjakan.'),
  ('id.indonesian', 6, 133, 'Dan Tuhanmu Maha Kaya lagi mempunyai rahmat. Jika Dia menghendaki niscaya Dia memusnahkan kamu dan menggantimu dengan siapa yang dikehendaki-Nya setelah kamu (musnah), sebagaimana Dia telah menjadikan kamu dari keturunan orang-orang lain.'),
  ('id.indonesian', 6, 134, 'Sesungguhnya apa yang dijanjikan kepadamu pasti datang, dan kamu sekali-kali tidak sanggup menolaknya.'),
  ('id.indonesian', 6, 135, 'Katakanlah: "Hai kaumku, berbuatlah sepenuh kemampuanmu, sesungguhnya akupun berbuat (pula). Kelak kamu akan mengetahui, siapakah (di antara kita) yang akan memperoleh hasil yang baik di dunia ini. Sesungguhnya orang-orang yang zalim itu tidak akan mendapatkan keberuntungan.'),
  ('id.indonesian', 6, 136, 'Dan mereka memperuntukkan bagi Allah satu bagian dari tanaman dan ternak yang telah diciptakan Allah, lalu mereka berkata sesuai dengan persangkaan mereka: "Ini untuk Allah dan ini untuk berhala-berhala kami". Maka saji-sajian yang diperuntukkan bagi berhala-berhala mereka tidak sampai kepada Allah; dan saji-sajian yang diperuntukkan bagi Allah, maka sajian itu sampai kepada berhala-berhala mereka. Amat buruklah ketetapan mereka itu.'),
  ('id.indonesian', 6, 137, 'Dan demikianlah pemimpin-pemimpin mereka telah menjadikan kebanyakan dari orang-orang musyrik itu memandang baik membunuh anak-anak mereka untuk membinasakan mereka dan untuk mengaburkan bagi mereka agama-Nya. Dan kalau Allah menghendaki, niscaya mereka tidak mengerjakannya, maka tinggallah mereka dan apa yang mereka ada-adakan.'),
  ('id.indonesian', 6, 138, 'Dan mereka mengatakan: "Inilah hewan ternak dan tanaman yang dilarang; tidak boleh memakannya, kecuali orang yang kami kehendaki", menurut anggapan mereka, dan ada binatang ternak yang diharamkan menungganginya dan ada binatang ternak yang mereka tidak menyebut nama Allah waktu menyembelihnya, semata-mata membuat-buat kedustaan terhadap Allah. Kelak Allah akan membalas mereka terhadap apa yang selalu mereka ada-adakan.'),
  ('id.indonesian', 6, 139, 'Dan mereka mengatakan: "Apa yang ada dalam perut binatang ternak ini adalah khusus untuk pria kami dan diharamkan atas wanita kami," dan jika yang dalam perut itu dilahirkan mati, maka pria dan wanita sama-sama boleh memakannya. Kelak Allah akan membalas mereka terhadap ketetapan mereka. Sesungguhnya Allah Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 6, 140, 'Sesungguhnya rugilah orang yang membunuh anak-anak mereka, karena kebodohan lagi tidak mengetahui dan mereka mengharamkan apa yang Allah telah rezeki-kan pada mereka dengan semata-mata mengada-adakan terhadap Allah. Sesungguhnya mereka telah sesat dan tidaklah mereka mendapat petunjuk.'),
  ('id.indonesian', 6, 141, 'Dan Dialah yang menjadikan kebun-kebun yang berjunjung dan yang tidak berjunjung, pohon korma, tanam-tanaman yang bermacam-macam buahnya, zaitun dan delima yang serupa (bentuk dan warnanya) dan tidak sama (rasanya). Makanlah dari buahnya (yang bermacam-macam itu) bila dia berbuah, dan tunaikanlah haknya di hari memetik hasilnya (dengan disedekahkan kepada fakir miskin); dan janganlah kamu berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang yang berlebih-lebihan.'),
  ('id.indonesian', 6, 142, 'Dan di antara hewan ternak itu ada yang dijadikan untuk pengangkutan dan ada yang untuk disembelih. Makanlah dari rezeki yang telah diberikan Allah kepadamu, dan janganlah kamu mengikuti langkah-langkah syaitan. Sesungguhnya syaitan itu musuh yang nyata bagimu.'),
  ('id.indonesian', 6, 143, '(yaitu) delapan binatang yang berpasangan, sepasang domba, sepasang dari kambing. Katakanlah: "Apakah dua yang jantan yang diharamkan Allah ataukah dua yang betina, ataukah yang ada dalam kandungan dua betinanya?" Terangkanlah kepadaku dengan berdasar pengetahuan jika kamu memang orang-orang yang benar,'),
  ('id.indonesian', 6, 144, 'dan sepasang dari unta dan sepasang dari lembu. Katakanlah: "Apakah dua yang jantan yang diharamkan ataukah dua yang betina, ataukah yang ada dalam kandungan dua betinanya? Apakah kamu menyaksikan di waktu Allah menetapkan ini bagimu? Maka siapakah yang lebih zalim daripada orang-orang yang membuat-buat dusta terhadap Allah untuk menyesatkan manusia tanpa pengetahuan?" Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang zalim.'),
  ('id.indonesian', 6, 145, 'Katakanlah: "Tiadalah aku peroleh dalam wahyu yang diwahyukan kepadaku, sesuatu yang diharamkan bagi orang yang hendak memakannya, kecuali kalau makanan itu bangkai, atau darah yang mengalir atau daging babi -- karena sesungguhnya semua itu kotor -- atau binatang yang disembelih atas nama selain Allah. Barangsiapa yang dalam keadaan terpaksa, sedang dia tidak menginginkannya dan tidak (pula) melampaui batas, maka sesungguhnya Tuhanmu Maha Pengampun lagi Maha Penyayang".'),
  ('id.indonesian', 6, 146, 'Dan kepada orang-orang Yahudi, Kami haramkan segala binatang yang berkuku dan dari sapi dan domba, Kami haramkan atas mereka lemak dari kedua binatang itu, selain lemak yang melekat di punggung keduanya atau yang di perut besar dan usus atau yang bercampur dengan tulang. Demikianlah Kami hukum mereka disebabkan kedurhakaan mereka; dan sesungguhnya Kami adalah Maha Benar.'),
  ('id.indonesian', 6, 147, 'Maka jika mereka mendustakan kamu, katakanlah: "Tuhanmu mempunyai rahmat yang luas; dan siksa-Nya tidak dapat ditolak dari kaum yang berdosa".'),
  ('id.indonesian', 6, 148, 'Orang-orang yang mempersekutukan Tuhan, akan mengatakan: "Jika Allah menghendaki, niscaya kami dan bapak-bapak kami tidak mempersekutukan-Nya dan tidak (pula) kami mengharamkan barang sesuatu apapun". Demikian pulalah orang-orang sebelum mereka telah mendustakan (para rasul) sampai mereka merasakan siksaan Kami. Katakanlah: "Adakah kamu mempunyai sesuatu pengetahuan sehingga dapat kamu mengemukakannya kepada Kami?" Kamu tidak mengikuti kecuali persangkaan belaka, dan kamu tidak lain hanyalah berdusta.'),
  ('id.indonesian', 6, 149, 'Katakanlah: "Allah mempunyai hujjah yang jelas lagi kuat; maka jika Dia menghendaki, pasti Dia memberi petunjuk kepada kamu semuanya".'),
  ('id.indonesian', 6, 150, 'Katakanlah: "Bawalah kemari saksi-saksi kamu yang dapat mempersaksikan bahwasanya Allah telah mengharamkan (makanan yang kamu) haramkan ini" Jika mereka mempersaksikan, maka janganlah kamu ikut pula menjadi saksi bersama mereka; dan janganlah kamu mengikuti hawa nafsu orang-orang yang mendustakan ayat-ayat Kami, dan orang-orang yang tidak beriman kepada kehidupan akhirat, sedang mereka mempersekutukan Tuhan mereka.'),
  ('id.indonesian', 6, 151, 'Katakanlah: "Marilah kubacakan apa yang diharamkan atas kamu oleh Tuhanmu yaitu: janganlah kamu mempersekutukan sesuatu dengan Dia, berbuat baiklah terhadap kedua orang ibu bapa, dan janganlah kamu membunuh anak-anak kamu karena takut kemiskinan, Kami akan memberi rezeki kepadamu dan kepada mereka, dan janganlah kamu mendekati perbuatan-perbuatan yang keji, baik yang nampak di antaranya maupun yang tersembunyi, dan janganlah kamu membunuh jiwa yang diharamkan Allah (membunuhnya) melainkan dengan sesuatu (sebab) yang benar". Demikian itu yang diperintahkan kepadamu supaya kamu memahami(nya).'),
  ('id.indonesian', 6, 152, 'Dan janganlah kamu dekati harta anak yatim, kecuali dengan cara yang lebih bermanfaat, hingga sampai ia dewasa. Dan sempurnakanlah takaran dan timbangan dengan adil. Kami tidak memikulkan beban kepada sesorang melainkan sekedar kesanggupannya. Dan apabila kamu berkata, maka hendaklah kamu berlaku adil, kendatipun ia adalah kerabat(mu), dan penuhilah janji Allah. Yang demikian itu diperintahkan Allah kepadamu agar kamu ingat.'),
  ('id.indonesian', 6, 153, 'dan bahwa (yang Kami perintahkan ini) adalah jalan-Ku yang lurus, maka ikutilah dia, dan janganlah kamu mengikuti jalan-jalan (yang lain), karena jalan-jalan itu mencerai beraikan kamu dari jalan-Nya. Yang demikian itu diperintahkan Allah agar kamu bertakwa.'),
  ('id.indonesian', 6, 154, 'Kemudian Kami telah memberikan Al Kitab (Taurat) kepada Musa untuk menyempurnakan (nikmat Kami) kepada orang yang berbuat kebaikan, dan untuk menjelaskan segala sesuatu dan sebagai petunjuk dan rahmat, agar mereka beriman (bahwa) mereka akan menemui Tuhan mereka.'),
  ('id.indonesian', 6, 155, 'Dan Al-Quran itu adalah kitab yang Kami turunkan yang diberkati, maka ikutilah dia dan bertakwalah agar kamu diberi rahmat.'),
  ('id.indonesian', 6, 156, '(Kami turunkan al-Quran itu) agar kamu (tidak) mengatakan: "Bahwa kitab itu hanya diturunkan kepada dua golongan saja sebelum kami, dan sesungguhnya kami tidak memperhatikan apa yang mereka baca.'),
  ('id.indonesian', 6, 157, 'Atau agar kamu (tidak) mengatakan: "Sesungguhnya jikalau kitab ini diturunkan kepada kami, tentulah kami lebih mendapat petunjuk dari mereka". Sesungguhnya telah datang kepada kamu keterangan yang nyata dari Tuhanmu, petunjuk dan rahmat. Maka siapakah yang lebih zalim daripada orang yang mendustakan ayat-ayat Allah dan berpaling daripadanya? Kelak Kami akan memberi balasan kepada orang-orang yang berpaling dari ayat-ayat Kami dengan siksa yang buruk, disebabkan mereka selalu berpaling.'),
  ('id.indonesian', 6, 158, 'Yang mereka nanti-nanti tidak lain hanyalah kedatangan malaikat kepada mereka (untuk mencabut nyawa mereka) atau kedatangan (siksa) Tuhanmu atau kedatangan beberapa ayat Tuhanmu. Pada hari datangnya ayat dari Tuhanmu, tidaklah bermanfaat lagi iman seseorang kepada dirinya sendiri yang belum beriman sebelum itu, atau dia (belum) mengusahakan kebaikan dalam masa imannya. Katakanlah: "Tunggulah olehmu sesungguhnya Kamipun menunggu (pula)".'),
  ('id.indonesian', 6, 159, 'Sesungguhnya orang-orang yang memecah belah agama-Nya dan mereka menjadi bergolongan, tidak ada sedikitpun tanggung jawabmu kepada mereka. Sesungguhnya urusan mereka hanyalah terserah kepada Allah, kemudian Allah akan memberitahukan kepada mereka apa yang telah mereka perbuat.'),
  ('id.indonesian', 6, 160, 'Barangsiapa membawa amal yang baik, maka baginya (pahala) sepuluh kali lipat amalnya; dan barangsiapa yang membawa perbuatan jahat maka dia tidak diberi pembalasan melainkan seimbang dengan kejahatannya, sedang mereka sedikitpun tidak dianiaya (dirugikan).'),
  ('id.indonesian', 6, 161, 'Katakanlah: "Sesungguhnya aku telah ditunjuki oleh Tuhanku kepada jalan yang lurus, (yaitu) agama yang benar, agama Ibrahim yang lurus, dan Ibrahim itu bukanlah termasuk orang-orang musyrik".'),
  ('id.indonesian', 6, 162, 'Katakanlah: sesungguhnya sembahyangku, ibadatku, hidupku dan matiku hanyalah untuk Allah, Tuhan semesta alam.'),
  ('id.indonesian', 6, 163, 'Tiada sekutu bagi-Nya; dan demikian itulah yang diperintahkan kepadaku dan aku adalah orang yang pertama-tama menyerahkan diri (kepada Allah)".'),
  ('id.indonesian', 6, 164, 'Katakanlah: "Apakah aku akan mencari Tuhan selain Allah, padahal Dia adalah Tuhan bagi segala sesuatu. Dan tidaklah seorang membuat dosa melainkan kemudharatannya kembali kepada dirinya sendiri; dan seorang yang berdosa tidak akan memikul dosa orang lain. Kemudian kepada Tuhanmulah kamu kembali, dan akan diberitakan-Nya kepadamu apa yang kamu perselisihkan".'),
  ('id.indonesian', 6, 165, 'Dan Dialah yang menjadikan kamu penguasa-penguasa di bumi dan Dia meninggikan sebahagian kamu atas sebahagian (yang lain) beberapa derajat, untuk mengujimu tentang apa yang diberikan-Nya kepadamu. Sesungguhnya Tuhanmu amat cepat siksaan-Nya dan sesungguhnya Dia Maha Pengampun lagi Maha Penyayang.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (6, 12, 801, 'قُل لِّمَن مَّا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 129, 7, 51, 0),
  (6, 13, 802, '۞ وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 129, 7, 52, 0),
  (6, 14, 803, 'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّۭا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ ۗ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 129, 7, 52, 0),
  (6, 15, 804, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍۢ', 129, 7, 52, 0),
  (6, 16, 805, 'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍۢ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ', 129, 7, 52, 0),
  (6, 17, 806, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّۢ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍۢ فَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 129, 7, 52, 0),
  (6, 18, 807, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 129, 7, 52, 0),
  (6, 19, 808, 'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَٰدَةًۭ ۖ قُلِ ٱللَّهُ ۖ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ ۚ وَأُوحِىَ إِلَىَّ هَٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ ۚ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ ۚ قُل لَّآ أَشْهَدُ ۚ قُلْ إِنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ وَإِنَّنِى بَرِىٓءٌۭ مِّمَّا تُشْرِكُونَ', 130, 7, 52, 0),
  (6, 20, 809, 'ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ۘ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ', 130, 7, 52, 0),
  (6, 21, 810, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 130, 7, 52, 0),
  (6, 22, 811, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًۭا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ', 130, 7, 52, 0),
  (6, 23, 812, 'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ', 130, 7, 52, 0),
  (6, 24, 813, 'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ ۚ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 130, 7, 52, 0),
  (6, 25, 814, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًۭا ۚ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍۢ لَّا يُؤْمِنُوا۟ بِهَا ۚ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 130, 7, 52, 0),
  (6, 26, 815, 'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ ۖ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ', 130, 7, 52, 0),
  (6, 27, 816, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 130, 7, 52, 0),
  (6, 28, 817, 'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ ۖ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 131, 7, 52, 0),
  (6, 29, 818, 'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 131, 7, 52, 0),
  (6, 30, 819, 'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ ۚ قَالَ أَلَيْسَ هَٰذَا بِٱلْحَقِّ ۚ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 131, 7, 52, 0),
  (6, 31, 820, 'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةًۭ قَالُوا۟ يَٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ ۚ أَلَا سَآءَ مَا يَزِرُونَ', 131, 7, 52, 0),
  (6, 32, 821, 'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌۭ وَلَهْوٌۭ ۖ وَلَلدَّارُ ٱلْءَاخِرَةُ خَيْرٌۭ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ', 131, 7, 52, 0),
  (6, 33, 822, 'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَٰكِنَّ ٱلظَّٰلِمِينَ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 131, 7, 52, 0),
  (6, 34, 823, 'وَلَقَدْ كُذِّبَتْ رُسُلٌۭ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا ۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِ ۚ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ', 131, 7, 52, 0),
  (6, 35, 824, 'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًۭا فِى ٱلْأَرْضِ أَوْ سُلَّمًۭا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍۢ ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ ۚ فَلَا تَكُونَنَّ مِنَ ٱلْجَٰهِلِينَ', 131, 7, 52, 0),
  (6, 36, 825, '۞ إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ ۘ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ', 132, 7, 53, 0),
  (6, 37, 826, 'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦ ۚ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةًۭ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 132, 7, 53, 0),
  (6, 38, 827, 'وَمَا مِن دَآبَّةٍۢ فِى ٱلْأَرْضِ وَلَا طَٰٓئِرٍۢ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم ۚ مَّا فَرَّطْنَا فِى ٱلْكِتَٰبِ مِن شَىْءٍۢ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ', 132, 7, 53, 0),
  (6, 39, 828, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا صُمٌّۭ وَبُكْمٌۭ فِى ٱلظُّلُمَٰتِ ۗ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 132, 7, 53, 0),
  (6, 40, 829, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَٰدِقِينَ', 132, 7, 53, 0),
  (6, 41, 830, 'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ', 132, 7, 53, 0),
  (6, 42, 831, 'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍۢ مِّن قَبْلِكَ فَأَخَذْنَٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ', 132, 7, 53, 0),
  (6, 43, 832, 'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ مَا كَانُوا۟ يَعْمَلُونَ', 132, 7, 53, 0),
  (6, 44, 833, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةًۭ فَإِذَا هُم مُّبْلِسُونَ', 132, 7, 53, 0),
  (6, 45, 834, 'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ ۚ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 133, 7, 53, 0),
  (6, 46, 835, 'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْءَايَٰتِ ثُمَّ هُمْ يَصْدِفُونَ', 133, 7, 53, 0),
  (6, 47, 836, 'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّٰلِمُونَ', 133, 7, 53, 0),
  (6, 48, 837, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۖ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 133, 7, 53, 0),
  (6, 49, 838, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ', 133, 7, 53, 0),
  (6, 50, 839, 'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ ۚ أَفَلَا تَتَفَكَّرُونَ', 133, 7, 53, 0),
  (6, 51, 840, 'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ ۙ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّۭ وَلَا شَفِيعٌۭ لَّعَلَّهُمْ يَتَّقُونَ', 133, 7, 53, 0),
  (6, 52, 841, 'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍۢ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍۢ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّٰلِمِينَ', 133, 7, 53, 0),
  (6, 53, 842, 'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍۢ لِّيَقُولُوٓا۟ أَهَٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ ۗ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّٰكِرِينَ', 134, 7, 53, 0),
  (6, 54, 843, 'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَٰتِنَا فَقُلْ سَلَٰمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَٰلَةٍۢ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌۭ رَّحِيمٌۭ', 134, 7, 53, 0),
  (6, 55, 844, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ', 134, 7, 53, 0),
  (6, 56, 845, 'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ ۚ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ ۙ قَدْ ضَلَلْتُ إِذًۭا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ', 134, 7, 53, 0),
  (6, 57, 846, 'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ ۚ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ يَقُصُّ ٱلْحَقَّ ۖ وَهُوَ خَيْرُ ٱلْفَٰصِلِينَ', 134, 7, 53, 0),
  (6, 58, 847, 'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ ۗ وَٱللَّهُ أَعْلَمُ بِٱلظَّٰلِمِينَ', 134, 7, 53, 0),
  (6, 59, 848, '۞ وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ ۚ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ ۚ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍۢ فِى ظُلُمَٰتِ ٱلْأَرْضِ وَلَا رَطْبٍۢ وَلَا يَابِسٍ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍۢ', 134, 7, 54, 0),
  (6, 60, 849, 'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌۭ مُّسَمًّۭى ۖ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 135, 7, 54, 0),
  (6, 61, 850, 'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ', 135, 7, 54, 0),
  (6, 62, 851, 'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۚ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَٰسِبِينَ', 135, 7, 54, 0),
  (6, 63, 852, 'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًۭا وَخُفْيَةًۭ لَّئِنْ أَنجَىٰنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 135, 7, 54, 0),
  (6, 64, 853, 'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍۢ ثُمَّ أَنتُمْ تُشْرِكُونَ', 135, 7, 54, 0),
  (6, 65, 854, 'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًۭا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًۭا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْءَايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ', 135, 7, 54, 0),
  (6, 66, 855, 'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ ۚ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍۢ', 135, 7, 54, 0),
  (6, 67, 856, 'لِّكُلِّ نَبَإٍۢ مُّسْتَقَرٌّۭ ۚ وَسَوْفَ تَعْلَمُونَ', 135, 7, 54, 0),
  (6, 68, 857, 'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ ۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 135, 7, 54, 0),
  (6, 69, 858, 'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍۢ وَلَٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ', 136, 7, 54, 0),
  (6, 70, 859, 'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًۭا وَلَهْوًۭا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّۭ وَلَا شَفِيعٌۭ وَإِن تَعْدِلْ كُلَّ عَدْلٍۢ لَّا يُؤْخَذْ مِنْهَآ ۗ أُو۟لَٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ ۖ لَهُمْ شَرَابٌۭ مِّنْ حَمِيمٍۢ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 136, 7, 54, 0),
  (6, 71, 860, 'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَٰبٌۭ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 136, 7, 54, 0),
  (6, 72, 861, 'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ ۚ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 136, 7, 54, 0),
  (6, 73, 862, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ وَيَوْمَ يَقُولُ كُن فَيَكُونُ ۚ قَوْلُهُ ٱلْحَقُّ ۚ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ', 136, 7, 54, 0),
  (6, 74, 863, '۞ وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً ۖ إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 137, 7, 55, 0),
  (6, 75, 864, 'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ', 137, 7, 55, 0),
  (6, 76, 865, 'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًۭا ۖ قَالَ هَٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْءَافِلِينَ', 137, 7, 55, 0),
  (6, 77, 866, 'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًۭا قَالَ هَٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ', 137, 7, 55, 0),
  (6, 78, 867, 'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةًۭ قَالَ هَٰذَا رَبِّى هَٰذَآ أَكْبَرُ ۖ فَلَمَّآ أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّى بَرِىٓءٌۭ مِّمَّا تُشْرِكُونَ', 137, 7, 55, 0),
  (6, 79, 868, 'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ حَنِيفًۭا ۖ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 137, 7, 55, 0),
  (6, 80, 869, 'وَحَآجَّهُۥ قَوْمُهُۥ ۚ قَالَ أَتُحَٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ ۚ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًۭٔا ۗ وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا ۗ أَفَلَا تَتَذَكَّرُونَ', 137, 7, 55, 0),
  (6, 81, 870, 'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَٰنًۭا ۚ فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ ۖ إِن كُنتُمْ تَعْلَمُونَ', 137, 7, 55, 0),
  (6, 82, 871, 'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ أُو۟لَٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ', 138, 7, 55, 0),
  (6, 83, 872, 'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ ۚ نَرْفَعُ دَرَجَٰتٍۢ مَّن نَّشَآءُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌۭ', 138, 7, 55, 0),
  (6, 84, 873, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ ۚ كُلًّا هَدَيْنَا ۚ وَنُوحًا هَدَيْنَا مِن قَبْلُ ۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَٰرُونَ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 138, 7, 55, 0),
  (6, 85, 874, 'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ ۖ كُلٌّۭ مِّنَ ٱلصَّٰلِحِينَ', 138, 7, 55, 0),
  (6, 86, 875, 'وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًۭا ۚ وَكُلًّۭا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ', 138, 7, 55, 0),
  (6, 87, 876, 'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّٰتِهِمْ وَإِخْوَٰنِهِمْ ۖ وَٱجْتَبَيْنَٰهُمْ وَهَدَيْنَٰهُمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 138, 7, 55, 0),
  (6, 88, 877, 'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ', 138, 7, 55, 0),
  (6, 89, 878, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ۚ فَإِن يَكْفُرْ بِهَا هَٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًۭا لَّيْسُوا۟ بِهَا بِكَٰفِرِينَ', 138, 7, 55, 0),
  (6, 90, 879, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ ۖ فَبِهُدَىٰهُمُ ٱقْتَدِهْ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَٰلَمِينَ', 138, 7, 55, 0),
  (6, 91, 880, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍۢ مِّن شَىْءٍۢ ۗ قُلْ مَنْ أَنزَلَ ٱلْكِتَٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًۭا وَهُدًۭى لِّلنَّاسِ ۖ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًۭا ۖ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ ۖ قُلِ ٱللَّهُ ۖ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ', 139, 7, 55, 0),
  (6, 92, 881, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌۭ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا ۚ وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْءَاخِرَةِ يُؤْمِنُونَ بِهِۦ ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 139, 7, 55, 0),
  (6, 93, 882, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌۭ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ۖ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَٰتِهِۦ تَسْتَكْبِرُونَ', 139, 7, 55, 0),
  (6, 94, 883, 'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۢ وَتَرَكْتُم مَّا خَوَّلْنَٰكُمْ وَرَآءَ ظُهُورِكُمْ ۖ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَٰٓؤُا۟ ۚ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ', 139, 7, 55, 0),
  (6, 95, 884, '۞ إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ ۖ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ۚ ذَٰلِكُمُ ٱللَّهُ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 140, 7, 56, 0),
  (6, 96, 885, 'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًۭا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 140, 7, 56, 0),
  (6, 97, 886, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَٰتِ ٱلْبَرِّ وَٱلْبَحْرِ ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 140, 7, 56, 0),
  (6, 98, 887, 'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ فَمُسْتَقَرٌّۭ وَمُسْتَوْدَعٌۭ ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَفْقَهُونَ', 140, 7, 56, 0),
  (6, 99, 888, 'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍۢ فَأَخْرَجْنَا مِنْهُ خَضِرًۭا نُّخْرِجُ مِنْهُ حَبًّۭا مُّتَرَاكِبًۭا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌۭ دَانِيَةٌۭ وَجَنَّٰتٍۢ مِّنْ أَعْنَابٍۢ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًۭا وَغَيْرَ مُتَشَٰبِهٍ ۗ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ ۚ إِنَّ فِى ذَٰلِكُمْ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 140, 7, 56, 0),
  (6, 100, 889, 'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ ۖ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَٰتٍۭ بِغَيْرِ عِلْمٍۢ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَصِفُونَ', 140, 7, 56, 0),
  (6, 101, 890, 'بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌۭ وَلَمْ تَكُن لَّهُۥ صَٰحِبَةٌۭ ۖ وَخَلَقَ كُلَّ شَىْءٍۢ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 140, 7, 56, 0),
  (6, 102, 891, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ خَٰلِقُ كُلِّ شَىْءٍۢ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ', 141, 7, 56, 0),
  (6, 103, 892, 'لَّا تُدْرِكُهُ ٱلْأَبْصَٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 141, 7, 56, 0),
  (6, 104, 893, 'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ ۖ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ ۖ وَمَنْ عَمِىَ فَعَلَيْهَا ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍۢ', 141, 7, 56, 0),
  (6, 105, 894, 'وَكَذَٰلِكَ نُصَرِّفُ ٱلْءَايَٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍۢ يَعْلَمُونَ', 141, 7, 56, 0),
  (6, 106, 895, 'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 141, 7, 56, 0),
  (6, 107, 896, 'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ ۗ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًۭا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍۢ', 141, 7, 56, 0),
  (6, 108, 897, 'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍۢ ۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 141, 7, 56, 0),
  (6, 109, 898, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌۭ لَّيُؤْمِنُنَّ بِهَا ۚ قُلْ إِنَّمَا ٱلْءَايَٰتُ عِندَ ٱللَّهِ ۖ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ', 141, 7, 56, 0),
  (6, 110, 899, 'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍۢ وَنَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 141, 7, 56, 0),
  (6, 111, 900, '۞ وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍۢ قُبُلًۭا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ', 142, 8, 57, 0),
  (6, 112, 901, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّۭا شَيَٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍۢ زُخْرُفَ ٱلْقَوْلِ غُرُورًۭا ۚ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 142, 8, 57, 0),
  (6, 113, 902, 'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ', 142, 8, 57, 0),
  (6, 114, 903, 'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًۭا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَٰبَ مُفَصَّلًۭا ۚ وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌۭ مِّن رَّبِّكَ بِٱلْحَقِّ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 142, 8, 57, 0),
  (6, 115, 904, 'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًۭا وَعَدْلًۭا ۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 142, 8, 57, 0),
  (6, 116, 905, 'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 142, 8, 57, 0),
  (6, 117, 906, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 142, 8, 57, 0),
  (6, 118, 907, 'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤْمِنِينَ', 142, 8, 57, 0),
  (6, 119, 908, 'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ ۗ وَإِنَّ كَثِيرًۭا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ ۗ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ', 143, 8, 57, 0),
  (6, 120, 909, 'وَذَرُوا۟ ظَٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ ۚ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ', 143, 8, 57, 0),
  (6, 121, 910, 'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌۭ ۗ وَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَٰدِلُوكُمْ ۖ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ', 143, 8, 57, 0),
  (6, 122, 911, 'أَوَمَن كَانَ مَيْتًۭا فَأَحْيَيْنَٰهُ وَجَعَلْنَا لَهُۥ نُورًۭا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَٰتِ لَيْسَ بِخَارِجٍۢ مِّنْهَا ۚ كَذَٰلِكَ زُيِّنَ لِلْكَٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ', 143, 8, 57, 0),
  (6, 123, 912, 'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا ۖ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ', 143, 8, 57, 0),
  (6, 124, 913, 'وَإِذَا جَآءَتْهُمْ ءَايَةٌۭ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ۘ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ ۗ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌۭ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ', 143, 8, 57, 0),
  (6, 125, 914, 'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَٰمِ ۖ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًۭا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ ۚ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ', 144, 8, 57, 0),
  (6, 126, 915, 'وَهَٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًۭا ۗ قَدْ فَصَّلْنَا ٱلْءَايَٰتِ لِقَوْمٍۢ يَذَّكَّرُونَ', 144, 8, 57, 0),
  (6, 127, 916, '۞ لَهُمْ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمْ ۖ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 144, 8, 58, 0),
  (6, 128, 917, 'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًۭا يَٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ ۖ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍۢ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا ۚ قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌۭ', 144, 8, 58, 0),
  (6, 129, 918, 'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 144, 8, 58, 0),
  (6, 130, 919, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌۭ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا ۚ قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا ۖ وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 144, 8, 58, 0),
  (6, 131, 920, 'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍۢ وَأَهْلُهَا غَٰفِلُونَ', 144, 8, 58, 0),
  (6, 132, 921, 'وَلِكُلٍّۢ دَرَجَٰتٌۭ مِّمَّا عَمِلُوا۟ ۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ', 145, 8, 58, 0),
  (6, 133, 922, 'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ', 145, 8, 58, 0),
  (6, 134, 923, 'إِنَّ مَا تُوعَدُونَ لَءَاتٍۢ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ', 145, 8, 58, 0),
  (6, 135, 924, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌۭ ۖ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 145, 8, 58, 0),
  (6, 136, 925, 'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَٰمِ نَصِيبًۭا فَقَالُوا۟ هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَآئِنَا ۖ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ ۗ سَآءَ مَا يَحْكُمُونَ', 145, 8, 58, 0),
  (6, 137, 926, 'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍۢ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ ۖ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ', 145, 8, 58, 0),
  (6, 138, 927, 'وَقَالُوا۟ هَٰذِهِۦٓ أَنْعَٰمٌۭ وَحَرْثٌ حِجْرٌۭ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَٰمٌۭ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ ۚ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ', 146, 8, 58, 0),
  (6, 139, 928, 'وَقَالُوا۟ مَا فِى بُطُونِ هَٰذِهِ ٱلْأَنْعَٰمِ خَالِصَةٌۭ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا ۖ وَإِن يَكُن مَّيْتَةًۭ فَهُمْ فِيهِ شُرَكَآءُ ۚ سَيَجْزِيهِمْ وَصْفَهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌۭ', 146, 8, 58, 0),
  (6, 140, 929, 'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍۢ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ ۚ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ', 146, 8, 58, 0),
  (6, 141, 930, '۞ وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّٰتٍۢ مَّعْرُوشَٰتٍۢ وَغَيْرَ مَعْرُوشَٰتٍۢ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَٰبِهًۭا وَغَيْرَ مُتَشَٰبِهٍۢ ۚ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ ۖ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 146, 8, 59, 0),
  (6, 142, 931, 'وَمِنَ ٱلْأَنْعَٰمِ حَمُولَةًۭ وَفَرْشًۭا ۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ', 146, 8, 59, 0),
  (6, 143, 932, 'ثَمَٰنِيَةَ أَزْوَٰجٍۢ ۖ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 147, 8, 59, 0),
  (6, 144, 933, 'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَا ۚ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 147, 8, 59, 0),
  (6, 145, 934, 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍۢ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًۭا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍۢ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۚ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَإِنَّ رَبَّكَ غَفُورٌۭ رَّحِيمٌۭ', 147, 8, 59, 0),
  (6, 146, 935, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍۢ ۖ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍۢ ۚ ذَٰلِكَ جَزَيْنَٰهُم بِبَغْيِهِمْ ۖ وَإِنَّا لَصَٰدِقُونَ', 147, 8, 59, 0),
  (6, 147, 936, 'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍۢ وَٰسِعَةٍۢ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 148, 8, 59, 0),
  (6, 148, 937, 'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍۢ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا ۗ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍۢ فَتُخْرِجُوهُ لَنَآ ۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ', 148, 8, 59, 0),
  (6, 149, 938, 'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَٰلِغَةُ ۖ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 148, 8, 59, 0),
  (6, 150, 939, 'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَٰذَا ۖ فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ ۚ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ', 148, 8, 59, 0),
  (6, 151, 940, '۞ قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًۭٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًۭا ۖ وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُم مِّنْ إِمْلَٰقٍۢ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ', 148, 8, 60, 0),
  (6, 152, 941, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۖ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ', 149, 8, 60, 0),
  (6, 153, 942, 'وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًۭا فَٱتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ', 149, 8, 60, 0),
  (6, 154, 943, 'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًۭا لِّكُلِّ شَىْءٍۢ وَهُدًۭى وَرَحْمَةًۭ لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ', 149, 8, 60, 0),
  (6, 155, 944, 'وَهَٰذَا كِتَٰبٌ أَنزَلْنَٰهُ مُبَارَكٌۭ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 149, 8, 60, 0),
  (6, 156, 945, 'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَٰفِلِينَ', 149, 8, 60, 0),
  (6, 157, 946, 'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ ۚ فَقَدْ جَآءَكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ وَهُدًۭى وَرَحْمَةٌۭ ۚ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا ۗ سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ', 149, 8, 60, 0),
  (6, 158, 947, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَٰتِ رَبِّكَ ۗ يَوْمَ يَأْتِى بَعْضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَٰنِهَا خَيْرًۭا ۗ قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 150, 8, 60, 0),
  (6, 159, 948, 'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا لَّسْتَ مِنْهُمْ فِى شَىْءٍ ۚ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ', 150, 8, 60, 0),
  (6, 160, 949, 'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ', 150, 8, 60, 0),
  (6, 161, 950, 'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ دِينًۭا قِيَمًۭا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۚ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 150, 8, 60, 0),
  (6, 162, 951, 'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 150, 8, 60, 0),
  (6, 163, 952, 'لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ', 150, 8, 60, 0),
  (6, 164, 953, 'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّۭا وَهُوَ رَبُّ كُلِّ شَىْءٍۢ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 150, 8, 60, 0),
  (6, 165, 954, 'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍۢ دَرَجَٰتٍۢ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۗ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌۭ رَّحِيمٌۢ', 150, 8, 60, 0),
  (7, 1, 955, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓصٓ', 151, 8, 61, 0),
  (7, 2, 956, 'كِتَٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌۭ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 151, 8, 61, 0),
  (7, 3, 957, 'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۗ قَلِيلًۭا مَّا تَذَكَّرُونَ', 151, 8, 61, 0),
  (7, 4, 958, 'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَٰهَا فَجَآءَهَا بَأْسُنَا بَيَٰتًا أَوْ هُمْ قَآئِلُونَ', 151, 8, 61, 0),
  (7, 5, 959, 'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَٰلِمِينَ', 151, 8, 61, 0),
  (7, 6, 960, 'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ', 151, 8, 61, 0),
  (7, 7, 961, 'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍۢ ۖ وَمَا كُنَّا غَآئِبِينَ', 151, 8, 61, 0),
  (7, 8, 962, 'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ ۚ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 151, 8, 61, 0),
  (7, 9, 963, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَظْلِمُونَ', 151, 8, 61, 0),
  (7, 10, 964, 'وَلَقَدْ مَكَّنَّٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ ۗ قَلِيلًۭا مَّا تَشْكُرُونَ', 151, 8, 61, 0),
  (7, 11, 965, 'وَلَقَدْ خَلَقْنَٰكُمْ ثُمَّ صَوَّرْنَٰكُمْ ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ', 151, 8, 61, 0),
  (7, 12, 966, 'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ ۖ قَالَ أَنَا۠ خَيْرٌۭ مِّنْهُ خَلَقْتَنِى مِن نَّارٍۢ وَخَلَقْتَهُۥ مِن طِينٍۢ', 152, 8, 61, 0),
  (7, 13, 967, 'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ', 152, 8, 61, 0),
  (7, 14, 968, 'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 152, 8, 61, 0),
  (7, 15, 969, 'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ', 152, 8, 61, 0),
  (7, 16, 970, 'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ', 152, 8, 61, 0),
  (7, 17, 971, 'ثُمَّ لَءَاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ', 152, 8, 61, 0),
  (7, 18, 972, 'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًۭا مَّدْحُورًۭا ۖ لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ', 152, 8, 61, 0),
  (7, 19, 973, 'وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ', 152, 8, 61, 0),
  (7, 20, 974, 'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَٰلِدِينَ', 152, 8, 61, 0),
  (7, 21, 975, 'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ', 152, 8, 61, 0),
  (7, 22, 976, 'فَدَلَّىٰهُمَا بِغُرُورٍۢ ۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَٰنَ لَكُمَا عَدُوٌّۭ مُّبِينٌۭ', 152, 8, 61, 0),
  (7, 23, 977, 'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 153, 8, 61, 0),
  (7, 24, 978, 'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۭ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّۭ وَمَتَٰعٌ إِلَىٰ حِينٍۢ', 153, 8, 61, 0),
  (7, 25, 979, 'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ', 153, 8, 61, 0),
  (7, 26, 980, 'يَٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًۭا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًۭا ۖ وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌۭ ۚ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ', 153, 8, 61, 0),
  (7, 27, 981, 'يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ ۗ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ ۗ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ', 153, 8, 61, 0),
  (7, 28, 982, 'وَإِذَا فَعَلُوا۟ فَٰحِشَةًۭ قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا ۗ قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ ۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 153, 8, 61, 0),
  (7, 29, 983, 'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ ۖ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍۢ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۚ كَمَا بَدَأَكُمْ تَعُودُونَ', 153, 8, 61, 0),
  (7, 30, 984, 'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ ۗ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 153, 8, 61, 0),
  (7, 31, 985, '۞ يَٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍۢ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ', 154, 8, 62, 0),
  (7, 32, 986, 'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزْقِ ۚ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةًۭ يَوْمَ ٱلْقِيَٰمَةِ ۗ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 154, 8, 62, 0),
  (7, 33, 987, 'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 154, 8, 62, 0),
  (7, 34, 988, 'وَلِكُلِّ أُمَّةٍ أَجَلٌۭ ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةًۭ ۖ وَلَا يَسْتَقْدِمُونَ', 154, 8, 62, 0),
  (7, 35, 989, 'يَٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌۭ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى ۙ فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 154, 8, 62, 0),
  (7, 36, 990, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 154, 8, 62, 0),
  (7, 37, 991, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۚ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ', 154, 8, 62, 0),
  (7, 38, 992, 'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍۢ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ ۖ كُلَّمَا دَخَلَتْ أُمَّةٌۭ لَّعَنَتْ أُخْتَهَا ۖ حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًۭا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًۭا ضِعْفًۭا مِّنَ ٱلنَّارِ ۖ قَالَ لِكُلٍّۢ ضِعْفٌۭ وَلَٰكِن لَّا تَعْلَمُونَ', 155, 8, 62, 0),
  (7, 39, 993, 'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍۢ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ', 155, 8, 62, 0),
  (7, 40, 994, 'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ', 155, 8, 62, 0),
  (7, 41, 995, 'لَهُم مِّن جَهَنَّمَ مِهَادٌۭ وَمِن فَوْقِهِمْ غَوَاشٍۢ ۚ وَكَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 155, 8, 62, 0),
  (7, 42, 996, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 155, 8, 62, 0),
  (7, 43, 997, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّۢ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ ۖ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ ۖ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ ۖ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 155, 8, 62, 0),
  (7, 44, 998, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّۭا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّۭا ۖ قَالُوا۟ نَعَمْ ۚ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', 156, 8, 62, 0),
  (7, 45, 999, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًۭا وَهُم بِٱلْءَاخِرَةِ كَٰفِرُونَ', 156, 8, 62, 0),
  (7, 46, 1000, 'وَبَيْنَهُمَا حِجَابٌۭ ۚ وَعَلَى ٱلْأَعْرَافِ رِجَالٌۭ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ ۚ وَنَادَوْا۟ أَصْحَٰبَ ٱلْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ ۚ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ', 156, 8, 62, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 7, 1, 'Alif, Lam, Meem, Sad.'),
  ('en.sahih', 7, 2, '[This is] a Book revealed to you, [O Muhammad] - so let there not be in your breast distress therefrom - that you may warn thereby and as a reminder to the believers.'),
  ('en.sahih', 7, 3, 'Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember.'),
  ('en.sahih', 7, 4, 'And how many cities have We destroyed, and Our punishment came to them at night or while they were sleeping at noon.'),
  ('en.sahih', 7, 5, 'And their declaration when Our punishment came to them was only that they said, "Indeed, we were wrongdoers!"'),
  ('en.sahih', 7, 6, 'Then We will surely question those to whom [a message] was sent, and We will surely question the messengers.'),
  ('en.sahih', 7, 7, 'Then We will surely relate [their deeds] to them with knowledge, and We were not [at all] absent.'),
  ('en.sahih', 7, 8, 'And the weighing [of deeds] that Day will be the truth. So those whose scales are heavy - it is they who will be the successful.'),
  ('en.sahih', 7, 9, 'And those whose scales are light - they are the ones who will lose themselves for what injustice they were doing toward Our verses.'),
  ('en.sahih', 7, 10, 'And We have certainly established you upon the earth and made for you therein ways of livelihood. Little are you grateful.'),
  ('en.sahih', 7, 11, 'And We have certainly created you, [O Mankind], and given you [human] form. Then We said to the angels, "Prostrate to Adam"; so they prostrated, except for Iblees. He was not of those who prostrated.'),
  ('en.sahih', 7, 12, '[Allah] said, "What prevented you from prostrating when I commanded you?" [Satan] said, "I am better than him. You created me from fire and created him from clay."'),
  ('en.sahih', 7, 13, '[Allah] said, "Descend from Paradise, for it is not for you to be arrogant therein. So get out; indeed, you are of the debased.'),
  ('en.sahih', 7, 14, '[Satan] said, "Reprieve me until the Day they are resurrected."'),
  ('en.sahih', 7, 15, '[Allah] said, "Indeed, you are of those reprieved."'),
  ('en.sahih', 7, 16, '[Satan] said, "Because You have put me in error, I will surely sit in wait for them on Your straight path.'),
  ('en.sahih', 7, 17, 'Then I will come to them from before them and from behind them and on their right and on their left, and You will not find most of them grateful [to You]."'),
  ('en.sahih', 7, 18, '[Allah] said, "Get out of Paradise, reproached and expelled. Whoever follows you among them - I will surely fill Hell with you, all together."'),
  ('en.sahih', 7, 19, 'And "O Adam, dwell, you and your wife, in Paradise and eat from wherever you will but do not approach this tree, lest you be among the wrongdoers."'),
  ('en.sahih', 7, 20, 'But Satan whispered to them to make apparent to them that which was concealed from them of their private parts. He said, "Your Lord did not forbid you this tree except that you become angels or become of the immortal."'),
  ('en.sahih', 7, 21, 'And he swore [by Allah] to them, "Indeed, I am to you from among the sincere advisors."'),
  ('en.sahih', 7, 22, 'So he made them fall, through deception. And when they tasted of the tree, their private parts became apparent to them, and they began to fasten together over themselves from the leaves of Paradise. And their Lord called to them, "Did I not forbid you from that tree and tell you that Satan is to you a clear enemy?"'),
  ('en.sahih', 7, 23, 'They said, "Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers."'),
  ('en.sahih', 7, 24, '[Allah] said, "Descend, being to one another enemies. And for you on the earth is a place of settlement and enjoyment for a time."'),
  ('en.sahih', 7, 25, 'He said, "Therein you will live, and therein you will die, and from it you will be brought forth."'),
  ('en.sahih', 7, 26, 'O children of Adam, We have bestowed upon you clothing to conceal your private parts and as adornment. But the clothing of righteousness - that is best. That is from the signs of Allah that perhaps they will remember.'),
  ('en.sahih', 7, 27, 'O children of Adam, let not Satan tempt you as he removed your parents from Paradise, stripping them of their clothing to show them their private parts. Indeed, he sees you, he and his tribe, from where you do not see them. Indeed, We have made the devils allies to those who do not believe.'),
  ('en.sahih', 7, 28, 'And when they commit an immorality, they say, "We found our fathers doing it, and Allah has ordered us to do it." Say, "Indeed, Allah does not order immorality. Do you say about Allah that which you do not know?"'),
  ('en.sahih', 7, 29, 'Say, [O Muhammad], "My Lord has ordered justice and that you maintain yourselves [in worship of Him] at every place [or time] of prostration, and invoke Him, sincere to Him in religion." Just as He originated you, you will return [to life] -'),
  ('en.sahih', 7, 30, 'A group [of you] He guided, and a group deserved [to be in] error. Indeed, they had taken the devils as allies instead of Allah while they thought that they were guided.'),
  ('en.sahih', 7, 31, 'O children of Adam, take your adornment at every masjid, and eat and drink, but be not excessive. Indeed, He likes not those who commit excess.'),
  ('en.sahih', 7, 32, 'Say, "Who has forbidden the adornment of Allah which He has produced for His servants and the good [lawful] things of provision?" Say, "They are for those who believe during the worldly life [but] exclusively for them on the Day of Resurrection." Thus do We detail the verses for a people who know.'),
  ('en.sahih', 7, 33, 'Say, "My Lord has only forbidden immoralities - what is apparent of them and what is concealed - and sin, and oppression without right, and that you associate with Allah that for which He has not sent down authority, and that you say about Allah that which you do not know."'),
  ('en.sahih', 7, 34, 'And for every nation is a [specified] term. So when their time has come, they will not remain behind an hour, nor will they precede [it].'),
  ('en.sahih', 7, 35, 'O children of Adam, if there come to you messengers from among you relating to you My verses, then whoever fears Allah and reforms - there will be no fear concerning them, nor will they grieve.'),
  ('en.sahih', 7, 36, 'But the ones who deny Our verses and are arrogant toward them - those are the companions of the Fire; they will abide therein eternally.'),
  ('en.sahih', 7, 37, 'And who is more unjust than one who invents about Allah a lie or denies His verses? Those will attain their portion of the decree until when Our messengers come to them to take them in death, they will say, "Where are those you used to invoke besides Allah?" They will say, "They have departed from us," and will bear witness against themselves that they were disbelievers.'),
  ('en.sahih', 7, 38, '[Allah] will say, "Enter among nations which had passed on before you of jinn and mankind into the Fire." Every time a nation enters, it will curse its sister until, when they have all overtaken one another therein, the last of them will say about the first of them "Our Lord, these had misled us, so give them a double punishment of the Fire. He will say, "For each is double, but you do not know."'),
  ('en.sahih', 7, 39, 'And the first of them will say to the last of them, "Then you had not any favor over us, so taste the punishment for what you used to earn."'),
  ('en.sahih', 7, 40, 'Indeed, those who deny Our verses and are arrogant toward them - the gates of Heaven will not be opened for them, nor will they enter Paradise until a camel enters into the eye of a needle. And thus do We recompense the criminals.'),
  ('en.sahih', 7, 41, 'They will have from Hell a bed and over them coverings [of fire]. And thus do We recompense the wrongdoers.'),
  ('en.sahih', 7, 42, 'But those who believed and did righteous deeds - We charge no soul except [within] its capacity. Those are the companions of Paradise; they will abide therein eternally.'),
  ('en.sahih', 7, 43, 'And We will have removed whatever is within their breasts of resentment, [while] flowing beneath them are rivers. And they will say, "Praise to Allah, who has guided us to this; and we would never have been guided if Allah had not guided us. Certainly the messengers of our Lord had come with the truth." And they will be called, "This is Paradise, which you have been made to inherit for what you used to do."'),
  ('en.sahih', 7, 44, 'And the companions of Paradise will call out to the companions of the Fire, "We have already found what our Lord promised us to be true. Have you found what your Lord promised to be true?" They will say, "Yes." Then an announcer will announce among them, "The curse of Allah shall be upon the wrongdoers."'),
  ('en.sahih', 7, 45, 'Who averted [people] from the way of Allah and sought to make it [seem] deviant while they were, concerning the Hereafter, disbelievers.'),
  ('en.sahih', 7, 46, 'And between them will be a partition, and on [its] elevations are men who recognize all by their mark. And they call out to the companions of Paradise, "Peace be upon you." They have not [yet] entered it, but they long intensely.'),
  ('en.sahih', 7, 47, 'And when their eyes are turned toward the companions of the Fire, they say, "Our Lord, do not place us with the wrongdoing people."'),
  ('en.sahih', 7, 48, 'And the companions of the Elevations will call to men [within Hell] whom they recognize by their mark, saying, "Of no avail to you was your gathering and [the fact] that you were arrogant."'),
  ('en.sahih', 7, 49, '[Allah will say], "Are these the ones whom you [inhabitants of Hell] swore that Allah would never offer them mercy? Enter Paradise, [O People of the Elevations]. No fear will there be concerning you, nor will you grieve."'),
  ('en.sahih', 7, 50, 'And the companions of the Fire will call to the companions of Paradise, "Pour upon us some water or from whatever Allah has provided you." They will say, "Indeed, Allah has forbidden them both to the disbelievers."'),
  ('en.sahih', 7, 51, 'Who took their religion as distraction and amusement and whom the worldly life deluded." So today We will forget them just as they forgot the meeting of this Day of theirs and for having rejected Our verses.'),
  ('en.sahih', 7, 52, 'And We had certainly brought them a Book which We detailed by knowledge - as guidance and mercy to a people who believe.'),
  ('en.sahih', 7, 53, 'Do they await except its result? The Day its result comes those who had ignored it before will say, "The messengers of our Lord had come with the truth, so are there [now] any intercessors to intercede for us or could we be sent back to do other than we used to do?" They will have lost themselves, and lost from them is what they used to invent.'),
  ('en.sahih', 7, 54, 'Indeed, your Lord is Allah, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, [another night] chasing it rapidly; and [He created] the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allah, Lord of the worlds.'),
  ('en.sahih', 7, 55, 'Call upon your Lord in humility and privately; indeed, He does not like transgressors.'),
  ('en.sahih', 7, 56, 'And cause not corruption upon the earth after its reformation. And invoke Him in fear and aspiration. Indeed, the mercy of Allah is near to the doers of good.'),
  ('en.sahih', 7, 57, 'And it is He who sends the winds as good tidings before His mercy until, when they have carried heavy rainclouds, We drive them to a dead land and We send down rain therein and bring forth thereby [some] of all the fruits. Thus will We bring forth the dead; perhaps you may be reminded.'),
  ('en.sahih', 7, 58, 'And the good land - its vegetation emerges by permission of its Lord; but that which is bad - nothing emerges except sparsely, with difficulty. Thus do We diversify the signs for a people who are grateful.'),
  ('en.sahih', 7, 59, 'We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him. Indeed, I fear for you the punishment of a tremendous Day.'),
  ('en.sahih', 7, 60, 'Said the eminent among his people, "Indeed, we see you in clear error."'),
  ('en.sahih', 7, 61, '[Noah] said, "O my people, there is not error in me, but I am a messenger from the Lord of the worlds."'),
  ('en.sahih', 7, 62, 'I convey to you the messages of my Lord and advise you; and I know from Allah what you do not know.'),
  ('en.sahih', 7, 63, 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you and that you may fear Allah so you might receive mercy."'),
  ('en.sahih', 7, 64, 'But they denied him, so We saved him and those who were with him in the ship. And We drowned those who denied Our signs. Indeed, they were a blind people.'),
  ('en.sahih', 7, 65, 'And to the \'Aad [We sent] their brother Hud. He said, "O my people, worship Allah; you have no deity other than Him. Then will you not fear Him?"'),
  ('en.sahih', 7, 66, 'Said the eminent ones who disbelieved among his people, "Indeed, we see you in foolishness, and indeed, we think you are of the liars."'),
  ('en.sahih', 7, 67, '[Hud] said, "O my people, there is not foolishness in me, but I am a messenger from the Lord of the worlds."'),
  ('en.sahih', 7, 68, 'I convey to you the messages of my Lord, and I am to you a trustworthy adviser.'),
  ('en.sahih', 7, 69, 'Then do you wonder that there has come to you a reminder from your Lord through a man from among you, that he may warn you? And remember when He made you successors after the people of Noah and increased you in stature extensively. So remember the favors of Allah that you might succeed.'),
  ('en.sahih', 7, 70, 'They said, "Have you come to us that we should worship Allah alone and leave what our fathers have worshipped? Then bring us what you promise us, if you should be of the truthful."'),
  ('en.sahih', 7, 71, '[Hud] said, "Already have defilement and anger fallen upon you from your Lord. Do you dispute with me concerning [mere] names you have named them, you and your fathers, for which Allah has not sent down any authority? Then wait; indeed, I am with you among those who wait."'),
  ('en.sahih', 7, 72, 'So We saved him and those with him by mercy from Us. And We eliminated those who denied Our signs, and they were not [at all] believers.'),
  ('en.sahih', 7, 73, 'And to the Thamud [We sent] their brother Salih. He said, "O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. This is the she-camel of Allah [sent] to you as a sign. So leave her to eat within Allah \'s land and do not touch her with harm, lest there seize you a painful punishment.'),
  ('en.sahih', 7, 74, 'And remember when He made you successors after the \'Aad and settled you in the land, [and] you take for yourselves palaces from its plains and carve from the mountains, homes. Then remember the favors of Allah and do not commit abuse on the earth, spreading corruption."'),
  ('en.sahih', 7, 75, 'Said the eminent ones who were arrogant among his people to those who were oppressed - to those who believed among them, "Do you [actually] know that Salih is sent from his Lord?" They said, "Indeed we, in that with which he was sent, are believers."'),
  ('en.sahih', 7, 76, 'Said those who were arrogant, "Indeed we, in that which you have believed, are disbelievers."'),
  ('en.sahih', 7, 77, 'So they hamstrung the she-camel and were insolent toward the command of their Lord and said, "O Salih, bring us what you promise us, if you should be of the messengers."'),
  ('en.sahih', 7, 78, 'So the earthquake seized them, and they became within their home [corpses] fallen prone.'),
  ('en.sahih', 7, 79, 'And he turned away from them and said, "O my people, I had certainly conveyed to you the message of my Lord and advised you, but you do not like advisors."'),
  ('en.sahih', 7, 80, 'And [We had sent] Lot when he said to his people, "Do you commit such immorality as no one has preceded you with from among the worlds?'),
  ('en.sahih', 7, 81, 'Indeed, you approach men with desire, instead of women. Rather, you are a transgressing people."'),
  ('en.sahih', 7, 82, 'But the answer of his people was only that they said, "Evict them from your city! Indeed, they are men who keep themselves pure."'),
  ('en.sahih', 7, 83, 'So We saved him and his family, except for his wife; she was of those who remained [with the evildoers].'),
  ('en.sahih', 7, 84, 'And We rained upon them a rain [of stones]. Then see how was the end of the criminals.'),
  ('en.sahih', 7, 85, 'And to [the people of] Madyan [We sent] their brother Shu\'ayb. He said, "O my people, worship Allah; you have no deity other than Him. There has come to you clear evidence from your Lord. So fulfill the measure and weight and do not deprive people of their due and cause not corruption upon the earth after its reformation. That is better for you, if you should be believers.'),
  ('en.sahih', 7, 86, 'And do not sit on every path, threatening and averting from the way of Allah those who believe in Him, seeking to make it [seem] deviant. And remember when you were few and He increased you. And see how was the end of the corrupters.'),
  ('en.sahih', 7, 87, 'And if there should be a group among you who has believed in that with which I have been sent and a group that has not believed, then be patient until Allah judges between us. And He is the best of judges."'),
  ('en.sahih', 7, 88, 'Said the eminent ones who were arrogant among his people, "We will surely evict you, O Shu\'ayb, and those who have believed with you from our city, or you must return to our religion." He said, "Even if we were unwilling?"'),
  ('en.sahih', 7, 89, 'We would have invented against Allah a lie if we returned to your religion after Allah had saved us from it. And it is not for us to return to it except that Allah, our Lord, should will. Our Lord has encompassed all things in knowledge. Upon Allah we have relied. Our Lord, decide between us and our people in truth, and You are the best of those who give decision."'),
  ('en.sahih', 7, 90, 'Said the eminent ones who disbelieved among his people, "If you should follow Shu\'ayb, indeed, you would then be losers."'),
  ('en.sahih', 7, 91, 'So the earthquake seized them, and they became within their home [corpses] fallen prone.'),
  ('en.sahih', 7, 92, 'Those who denied Shu\'ayb - it was as though they had never resided there. Those who denied Shu\'ayb - it was they who were the losers.'),
  ('en.sahih', 7, 93, 'And he turned away from them and said, "O my people, I had certainly conveyed to you the messages of my Lord and advised you, so how could I grieve for a disbelieving people?"'),
  ('en.sahih', 7, 94, 'And We sent to no city a prophet [who was denied] except that We seized its people with poverty and hardship that they might humble themselves [to Allah].'),
  ('en.sahih', 7, 95, 'Then We exchanged in place of the bad [condition], good, until they increased [and prospered] and said, "Our fathers [also] were touched with hardship and ease." So We seized them suddenly while they did not perceive.'),
  ('en.sahih', 7, 96, 'And if only the people of the cities had believed and feared Allah, We would have opened upon them blessings from the heaven and the earth; but they denied [the messengers], so We seized them for what they were earning."'),
  ('en.sahih', 7, 97, 'Then, did the people of the cities feel secure from Our punishment coming to them at night while they were asleep?'),
  ('en.sahih', 7, 98, 'Or did the people of the cities feel secure from Our punishment coming to them in the morning while they were at play?'),
  ('en.sahih', 7, 99, 'Then did they feel secure from the plan of Allah? But no one feels secure from the plan of Allah except the losing people.'),
  ('en.sahih', 7, 100, 'Has it not become clear to those who inherited the earth after its [previous] people that if We willed, We could afflict them for their sins? But We seal over their hearts so they do not hear.'),
  ('en.sahih', 7, 101, 'Those cities - We relate to you, [O Muhammad], some of their news. And certainly did their messengers come to them with clear proofs, but they were not to believe in that which they had denied before. Thus does Allah seal over the hearts of the disbelievers.'),
  ('en.sahih', 7, 102, 'And We did not find for most of them any covenant; but indeed, We found most of them defiantly disobedient.'),
  ('en.sahih', 7, 103, 'Then We sent after them Moses with Our signs to Pharaoh and his establishment, but they were unjust toward them. So see how was the end of the corrupters.'),
  ('en.sahih', 7, 104, 'And Moses said, "O Pharaoh, I am a messenger from the Lord of the worlds'),
  ('en.sahih', 7, 105, '[Who is] obligated not to say about Allah except the truth. I have come to you with clear evidence from your Lord, so send with me the Children of Israel."'),
  ('en.sahih', 7, 106, '[Pharaoh] said, "If you have come with a sign, then bring it forth, if you should be of the truthful."'),
  ('en.sahih', 7, 107, 'So Moses threw his staff, and suddenly it was a serpent, manifest.'),
  ('en.sahih', 7, 108, 'And he drew out his hand; thereupon it was white [with radiance] for the observers.'),
  ('en.sahih', 7, 109, 'Said the eminent among the people of Pharaoh, "Indeed, this is a learned magician'),
  ('en.sahih', 7, 110, 'Who wants to expel you from your land [through magic], so what do you instruct?"'),
  ('en.sahih', 7, 111, 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers'),
  ('en.sahih', 7, 112, 'Who will bring you every learned magician."'),
  ('en.sahih', 7, 113, 'And the magicians came to Pharaoh. They said, "Indeed for us is a reward if we are the predominant."'),
  ('en.sahih', 7, 114, 'He said, "Yes, and, [moreover], you will be among those made near [to me]."'),
  ('en.sahih', 7, 115, 'They said, "O Moses, either you throw [your staff], or we will be the ones to throw [first]."'),
  ('en.sahih', 7, 116, 'He said, "Throw," and when they threw, they bewitched the eyes of the people and struck terror into them, and they presented a great [feat of] magic.'),
  ('en.sahih', 7, 117, 'And We inspired to Moses, "Throw your staff," and at once it devoured what they were falsifying.'),
  ('en.sahih', 7, 118, 'So the truth was established, and abolished was what they were doing.'),
  ('en.sahih', 7, 119, 'And Pharaoh and his people were overcome right there and became debased.'),
  ('en.sahih', 7, 120, 'And the magicians fell down in prostration [to Allah].'),
  ('en.sahih', 7, 121, 'They said, "We have believed in the Lord of the worlds,'),
  ('en.sahih', 7, 122, 'The Lord of Moses and Aaron."'),
  ('en.sahih', 7, 123, 'Said Pharaoh, "You believed in him before I gave you permission. Indeed, this is a conspiracy which you conspired in the city to expel therefrom its people. But you are going to know.'),
  ('en.sahih', 7, 124, 'I will surely cut off your hands and your feet on opposite sides; then I will surely crucify you all."'),
  ('en.sahih', 7, 125, 'They said, "Indeed, to our Lord we will return.'),
  ('en.sahih', 7, 126, 'And you do not resent us except because we believed in the signs of our Lord when they came to us. Our Lord, pour upon us patience and let us die as Muslims [in submission to You]."'),
  ('en.sahih', 7, 127, 'And the eminent among the people of Pharaoh said," Will you leave Moses and his people to cause corruption in the land and abandon you and your gods?" [Pharaoh] said, "We will kill their sons and keep their women alive; and indeed, we are subjugators over them."'),
  ('en.sahih', 7, 128, 'Said Moses to his people, "Seek help through Allah and be patient. Indeed, the earth belongs to Allah. He causes to inherit it whom He wills of His servants. And the [best] outcome is for the righteous."'),
  ('en.sahih', 7, 129, 'They said, "We have been harmed before you came to us and after you have come to us." He said, "Perhaps your Lord will destroy your enemy and grant you succession in the land and see how you will do."'),
  ('en.sahih', 7, 130, 'And We certainly seized the people of Pharaoh with years of famine and a deficiency in fruits that perhaps they would be reminded.'),
  ('en.sahih', 7, 131, 'But when good came to them, they said, "This is ours [by right]." And if a bad [condition] struck them, they saw an evil omen in Moses and those with him. Unquestionably, their fortune is with Allah, but most of them do not know.'),
  ('en.sahih', 7, 132, 'And they said, "No matter what sign you bring us with which to bewitch us, we will not be believers in you."'),
  ('en.sahih', 7, 133, 'So We sent upon them the flood and locusts and lice and frogs and blood as distinct signs, but they were arrogant and were a criminal people.'),
  ('en.sahih', 7, 134, 'And when the punishment descended upon them, they said, "O Moses, invoke for us your Lord by what He has promised you. If you [can] remove the punishment from us, we will surely believe you, and we will send with you the Children of Israel."'),
  ('en.sahih', 7, 135, 'But when We removed the punishment from them until a term which they were to reach, then at once they broke their word.'),
  ('en.sahih', 7, 136, 'So We took retribution from them, and We drowned them in the sea because they denied Our signs and were heedless of them.'),
  ('en.sahih', 7, 137, 'And We caused the people who had been oppressed to inherit the eastern regions of the land and the western ones, which We had blessed. And the good word of your Lord was fulfilled for the Children of Israel because of what they had patiently endured. And We destroyed [all] that Pharaoh and his people were producing and what they had been building.'),
  ('en.sahih', 7, 138, 'And We took the Children of Israel across the sea; then they came upon a people intent in devotion to [some] idols of theirs. They said, "O Moses, make for us a god just as they have gods." He said, "Indeed, you are a people behaving ignorantly.'),
  ('en.sahih', 7, 139, 'Indeed, those [worshippers] - destroyed is that in which they are [engaged], and worthless is whatever they were doing."'),
  ('en.sahih', 7, 140, 'He said, "Is it other than Allah I should desire for you as a god while He has preferred you over the worlds?"'),
  ('en.sahih', 7, 141, 'And [recall, O Children of Israel], when We saved you from the people of Pharaoh, [who were] afflicting you with the worst torment - killing your sons and keeping your women alive. And in that was a great trial from your Lord.'),
  ('en.sahih', 7, 142, 'And We made an appointment with Moses for thirty nights and perfected them by [the addition of] ten; so the term of his Lord was completed as forty nights. And Moses said to his brother Aaron, "Take my place among my people, do right [by them], and do not follow the way of the corrupters."'),
  ('en.sahih', 7, 143, 'And when Moses arrived at Our appointed time and his Lord spoke to him, he said, "My Lord, show me [Yourself] that I may look at You." [Allah] said, "You will not see Me, but look at the mountain; if it should remain in place, then you will see Me." But when his Lord appeared to the mountain, He rendered it level, and Moses fell unconscious. And when he awoke, he said, "Exalted are You! I have repented to You, and I am the first of the believers."'),
  ('en.sahih', 7, 144, '[Allah] said, "O Moses, I have chosen you over the people with My messages and My words [to you]. So take what I have given you and be among the grateful."'),
  ('en.sahih', 7, 145, 'And We wrote for him on the tablets [something] of all things - instruction and explanation for all things, [saying], "Take them with determination and order your people to take the best of it. I will show you the home of the defiantly disobedient."'),
  ('en.sahih', 7, 146, 'I will turn away from My signs those who are arrogant upon the earth without right; and if they should see every sign, they will not believe in it. And if they see the way of consciousness, they will not adopt it as a way; but if they see the way of error, they will adopt it as a way. That is because they have denied Our signs and they were heedless of them.'),
  ('en.sahih', 7, 147, 'Those who denied Our signs and the meeting of the Hereafter - their deeds have become worthless. Are they recompensed except for what they used to do?'),
  ('en.sahih', 7, 148, 'And the people of Moses made, after [his departure], from their ornaments a calf - an image having a lowing sound. Did they not see that it could neither speak to them nor guide them to a way? They took it [for worship], and they were wrongdoers.'),
  ('en.sahih', 7, 149, 'And when regret overcame them and they saw that they had gone astray, they said, "If our Lord does not have mercy upon us and forgive us, we will surely be among the losers."'),
  ('en.sahih', 7, 150, 'And when Moses returned to his people, angry and grieved, he said, "How wretched is that by which you have replaced me after [my departure]. Were you impatient over the matter of your Lord?" And he threw down the tablets and seized his brother by [the hair of] his head, pulling him toward him. [Aaron] said, "O son of my mother, indeed the people oppressed me and were about to kill me, so let not the enemies rejoice over me and do not place me among the wrongdoing people."'),
  ('en.sahih', 7, 151, '[Moses] said, "My Lord, forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful."'),
  ('en.sahih', 7, 152, 'Indeed, those who took the calf [for worship] will obtain anger from their Lord and humiliation in the life of this world, and thus do We recompense the inventors [of falsehood].'),
  ('en.sahih', 7, 153, 'But those who committed misdeeds and then repented after them and believed - indeed your Lord, thereafter, is Forgiving and Merciful.'),
  ('en.sahih', 7, 154, 'And when the anger subsided in Moses, he took up the tablets; and in their inscription was guidance and mercy for those who are fearful of their Lord.'),
  ('en.sahih', 7, 155, 'And Moses chose from his people seventy men for Our appointment. And when the earthquake seized them, he said, "My Lord, if You had willed, You could have destroyed them before and me [as well]. Would You destroy us for what the foolish among us have done? This is not but Your trial by which You send astray whom You will and guide whom You will. You are our Protector, so forgive us and have mercy upon us; and You are the best of forgivers.'),
  ('en.sahih', 7, 156, 'And decree for us in this world [that which is] good and [also] in the Hereafter; indeed, we have turned back to You." [Allah] said, "My punishment - I afflict with it whom I will, but My mercy encompasses all things." So I will decree it [especially] for those who fear Me and give zakah and those who believe in Our verses -'),
  ('en.sahih', 7, 157, 'Those who follow the Messenger, the unlettered prophet, whom they find written in what they have of the Torah and the Gospel, who enjoins upon them what is right and forbids them what is wrong and makes lawful for them the good things and prohibits for them the evil and relieves them of their burden and the shackles which were upon them. So they who have believed in him, honored him, supported him and followed the light which was sent down with him - it is those who will be the successful.'),
  ('en.sahih', 7, 158, 'Say, [O Muhammad], "O mankind, indeed I am the Messenger of Allah to you all, [from Him] to whom belongs the dominion of the heavens and the earth. There is no deity except Him; He gives life and causes death." So believe in Allah and His Messenger, the unlettered prophet, who believes in Allah and His words, and follow him that you may be guided.'),
  ('en.sahih', 7, 159, 'And among the people of Moses is a community which guides by truth and by it establishes justice.'),
  ('en.sahih', 7, 160, 'And We divided them into twelve descendant tribes [as distinct] nations. And We inspired to Moses when his people implored him for water, "Strike with your staff the stone," and there gushed forth from it twelve springs. Every people knew its watering place. And We shaded them with clouds and sent down upon them manna and quails, [saying], "Eat from the good things with which We have provided you." And they wronged Us not, but they were [only] wronging themselves.'),
  ('en.sahih', 7, 161, 'And [mention, O Muhammad], when it was said to them, "Dwell in this city and eat from it wherever you will and say, \'Relieve us of our burdens,\' and enter the gate bowing humbly; We will [then] forgive you your sins. We will increase the doers of good [in goodness and reward]."'),
  ('en.sahih', 7, 162, 'But those who wronged among them changed [the words] to a statement other than that which had been said to them. So We sent upon them a punishment from the sky for the wrong that they were doing.'),
  ('en.sahih', 7, 163, 'And ask them about the town that was by the sea - when they transgressed in [the matter of] the sabbath - when their fish came to them openly on their sabbath day, and the day they had no sabbath they did not come to them. Thus did We give them trial because they were defiantly disobedient.'),
  ('en.sahih', 7, 164, 'And when a community among them said, "Why do you advise [or warn] a people whom Allah is [about] to destroy or to punish with a severe punishment?" they [the advisors] said, "To be absolved before your Lord and perhaps they may fear Him."'),
  ('en.sahih', 7, 165, 'And when they forgot that by which they had been reminded, We saved those who had forbidden evil and seized those who wronged, with a wretched punishment, because they were defiantly disobeying.'),
  ('en.sahih', 7, 166, 'So when they were insolent about that which they had been forbidden, We said to them, "Be apes, despised."'),
  ('en.sahih', 7, 167, 'And [mention] when your Lord declared that He would surely [continue to] send upon them until the Day of Resurrection those who would afflict them with the worst torment. Indeed, your Lord is swift in penalty; but indeed, He is Forgiving and Merciful.'),
  ('en.sahih', 7, 168, 'And We divided them throughout the earth into nations. Of them some were righteous, and of them some were otherwise. And We tested them with good [times] and bad that perhaps they would return [to obedience].'),
  ('en.sahih', 7, 169, 'And there followed them successors who inherited the Scripture [while] taking the commodities of this lower life and saying, "It will be forgiven for us." And if an offer like it comes to them, they will [again] take it. Was not the covenant of the Scripture taken from them that they would not say about Allah except the truth, and they studied what was in it? And the home of the Hereafter is better for those who fear Allah, so will you not use reason?'),
  ('en.sahih', 7, 170, 'But those who hold fast to the Book and establish prayer - indeed, We will not allow to be lost the reward of the reformers.'),
  ('en.sahih', 7, 171, 'And [mention] when We raised the mountain above them as if it was a dark cloud and they were certain that it would fall upon them, [and Allah said], "Take what We have given you with determination and remember what is in it that you might fear Allah."'),
  ('en.sahih', 7, 172, 'And [mention] when your Lord took from the children of Adam - from their loins - their descendants and made them testify of themselves, [saying to them], "Am I not your Lord?" They said, "Yes, we have testified." [This] - lest you should say on the day of Resurrection, "Indeed, we were of this unaware."'),
  ('en.sahih', 7, 173, 'Or [lest] you say, "It was only that our fathers associated [others in worship] with Allah before, and we were but descendants after them. Then would You destroy us for what the falsifiers have done?"'),
  ('en.sahih', 7, 174, 'And thus do We [explain in] detail the verses, and perhaps they will return.'),
  ('en.sahih', 7, 175, 'And recite to them, [O Muhammad], the news of him to whom we gave [knowledge of] Our signs, but he detached himself from them; so Satan pursued him, and he became of the deviators.'),
  ('en.sahih', 7, 176, 'And if We had willed, we could have elevated him thereby, but he adhered [instead] to the earth and followed his own desire. So his example is like that of the dog: if you chase him, he pants, or if you leave him, he [still] pants. That is the example of the people who denied Our signs. So relate the stories that perhaps they will give thought.'),
  ('en.sahih', 7, 177, 'How evil an example [is that of] the people who denied Our signs and used to wrong themselves.'),
  ('en.sahih', 7, 178, 'Whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - it is those who are the losers.'),
  ('en.sahih', 7, 179, 'And We have certainly created for Hell many of the jinn and mankind. They have hearts with which they do not understand, they have eyes with which they do not see, and they have ears with which they do not hear. Those are like livestock; rather, they are more astray. It is they who are the heedless.'),
  ('en.sahih', 7, 180, 'And to Allah belong the best names, so invoke Him by them. And leave [the company of] those who practice deviation concerning His names. They will be recompensed for what they have been doing.'),
  ('en.sahih', 7, 181, 'And among those We created is a community which guides by truth and thereby establishes justice.'),
  ('en.sahih', 7, 182, 'But those who deny Our signs - We will progressively lead them [to destruction] from where they do not know.'),
  ('en.sahih', 7, 183, 'And I will give them time. Indeed, my plan is firm.'),
  ('en.sahih', 7, 184, 'Then do they not give thought? There is in their companion [Muhammad] no madness. He is not but a clear warner.'),
  ('en.sahih', 7, 185, 'Do they not look into the realm of the heavens and the earth and everything that Allah has created and [think] that perhaps their appointed time has come near? So in what statement hereafter will they believe?'),
  ('en.sahih', 7, 186, 'Whoever Allah sends astray - there is no guide for him. And He leaves them in their transgression, wandering blindly.'),
  ('en.sahih', 7, 187, 'They ask you, [O Muhammad], about the Hour: when is its arrival? Say, "Its knowledge is only with my Lord. None will reveal its time except Him. It lays heavily upon the heavens and the earth. It will not come upon you except unexpectedly." They ask you as if you are familiar with it. Say, "Its knowledge is only with Allah, but most of the people do not know."'),
  ('en.sahih', 7, 188, 'Say, "I hold not for myself [the power of] benefit or harm, except what Allah has willed. And if I knew the unseen, I could have acquired much wealth, and no harm would have touched me. I am not except a warner and a bringer of good tidings to a people who believe."'),
  ('en.sahih', 7, 189, 'It is He who created you from one soul and created from it its mate that he might dwell in security with her. And when he covers her, she carries a light burden and continues therein. And when it becomes heavy, they both invoke Allah, their Lord, "If You should give us a good [child], we will surely be among the grateful."'),
  ('en.sahih', 7, 190, 'But when He gives them a good [child], they ascribe partners to Him concerning that which He has given them. Exalted is Allah above what they associate with Him.'),
  ('en.sahih', 7, 191, 'Do they associate with Him those who create nothing and they are [themselves] created?'),
  ('en.sahih', 7, 192, 'And the false deities are unable to [give] them help, nor can they help themselves.'),
  ('en.sahih', 7, 193, 'And if you [believers] invite them to guidance, they will not follow you. It is all the same for you whether you invite them or you are silent.'),
  ('en.sahih', 7, 194, 'Indeed, those you [polytheists] call upon besides Allah are servants like you. So call upon them and let them respond to you, if you should be truthful.'),
  ('en.sahih', 7, 195, 'Do they have feet by which they walk? Or do they have hands by which they strike? Or do they have eyes by which they see? Or do they have ears by which they hear? Say, [O Muhammad], "Call your \'partners\' and then conspire against me and give me no respite.'),
  ('en.sahih', 7, 196, 'Indeed, my protector is Allah, who has sent down the Book; and He is an ally to the righteous.'),
  ('en.sahih', 7, 197, 'And those you call upon besides Him are unable to help you, nor can they help themselves."'),
  ('en.sahih', 7, 198, 'And if you invite them to guidance, they do not hear; and you see them looking at you while they do not see.'),
  ('en.sahih', 7, 199, 'Take what is given freely, enjoin what is good, and turn away from the ignorant.'),
  ('en.sahih', 7, 200, 'And if an evil suggestion comes to you from Satan, then seek refuge in Allah. Indeed, He is Hearing and Knowing.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 7, 201, 'Indeed, those who fear Allah - when an impulse touches them from Satan, they remember [Him] and at once they have insight.'),
  ('en.sahih', 7, 202, 'But their brothers - the devils increase them in error; then they do not stop short.'),
  ('en.sahih', 7, 203, 'And when you, [O Muhammad], do not bring them a sign, they say, "Why have you not contrived it?" Say, "I only follow what is revealed to me from my Lord. This [Qur\'an] is enlightenment from your Lord and guidance and mercy for a people who believe."'),
  ('en.sahih', 7, 204, 'So when the Qur\'an is recited, then listen to it and pay attention that you may receive mercy.'),
  ('en.sahih', 7, 205, 'And remember your Lord within yourself in humility and in fear without being apparent in speech - in the mornings and the evenings. And do not be among the heedless.'),
  ('en.sahih', 7, 206, 'Indeed, those who are near your Lord are not prevented by arrogance from His worship, and they exalt Him, and to Him they prostrate.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 7, 1, 'আলিফ, লাম, মীম, ছোয়াদ।'),
  ('bn.bengali', 7, 2, 'এটি একটি গ্রন্থ, যা আপনার প্রতি অবতীর্ণ হয়েছে, যাতে করে আপনি এর মাধ্যমে ভীতি-প্রদর্শন করেন। অতএব, এটি পৌছে দিতে আপনার মনে কোনরূপ সংকীর্ণতা থাকা উচিত নয়। আর এটিই বিশ্বাসীদের জন্যে উপদেশ।'),
  ('bn.bengali', 7, 3, 'তোমরা অনুসরণ কর, যা তোমাদের প্রতি পালকের পক্ষ থেকে অবতীর্ণ হয়েছে এবং আল্লাহকে বাদ দিয়ে অন্য সাথীদের অনুসরণ করো না।'),
  ('bn.bengali', 7, 4, 'আর তোমরা অল্পই উপদেশ গ্রহণ কর। অনেক জনপদকে আমি ধ্বংস করে দিয়েছি। তাদের কাছে আমার আযাব রাত্রি বেলায় পৌছেছে অথবা দ্বিপ্রহরে বিশ্রামরত অবস্থায়।'),
  ('bn.bengali', 7, 5, 'অনন্তর যখন তাদের কাছে আমার আযাব উপস্থিত হয়, তখন তাদের কথা এই ছিল যে, তারা বললঃ নিশ্চয় আমরা অত্যাচারী ছিলাম।'),
  ('bn.bengali', 7, 6, 'অতএব, আমি অবশ্যই তাদেরকে জিজ্ঞেস করব যাদের কাছে রসূল প্রেরিত হয়েছিল এবং আমি অবশ্যই তাদেরকে জিজ্ঞেস করব রসূলগণকে।'),
  ('bn.bengali', 7, 7, 'অতঃপর আমি স্বজ্ঞানে তাদের কাছে অবস্থা বর্ণনা করব। বস্তুতঃ আমি অনুপস্থিত তো ছিলাম না।'),
  ('bn.bengali', 7, 8, 'আর সেদিন যথার্থই ওজন হবে। অতঃপর যাদের পাল্লা ভারী হবে, তারাই সফলকাম হবে।'),
  ('bn.bengali', 7, 9, 'এবং যাদের পাল্লা হাল্কা হবে, তারাই এমন হবে, যারা নিজেদের ক্ষতি করেছে। কেননা, তারা আমার আয়াত সমূহ অস্বীকার করতো।'),
  ('bn.bengali', 7, 10, 'আমি তোমাদেরকে পৃথিবীতে ঠাই দিয়েছি এবং তোমাদের জীবিকা নির্দিষ্ট করে দিয়েছি। তোমরা অল্পই কৃতজ্ঞতা স্বীকার কর।'),
  ('bn.bengali', 7, 11, 'আর আমি তোমাদেরকে সৃষ্টি করেছি, এরপর আকার-অবয়ব, তৈরী করেছি। অতঃপর আমি ফেরেশতাদেরকে বলছি-আদমকে সেজদা কর তখন সবাই সেজদা করেছে, কিন্তু ইবলীস সে সেজদাকারীদের অন্তর্ভূক্ত ছিল না।'),
  ('bn.bengali', 7, 12, 'আল্লাহ বললেনঃ আমি যখন নির্দেশ দিয়েছি, তখন তোকে কিসে সেজদা করতে বারণ করল? সে বললঃ আমি তার চাইতে শ্রেষ্ট। আপনি আমাকে আগুন দ্বারা সৃষ্টি করেছেন এবং তাকে সৃষ্টি করেছেন মাটির দ্বারা।'),
  ('bn.bengali', 7, 13, 'বললেন তুই এখান থেকে যা। এখানে অহংকার করার কোন অধিকার তোর নাই। অতএব তুই বের হয়ে যা। তুই হীনতমদের অন্তর্ভুক্ত।'),
  ('bn.bengali', 7, 14, 'সে বললঃ আমাকে কেয়ামত দিবস পর্যন্ত অবকাশ দিন।'),
  ('bn.bengali', 7, 15, 'আল্লাহ বললেনঃ তোকে সময় দেয়া হল।'),
  ('bn.bengali', 7, 16, 'সে বললঃ আপনি আমাকে যেমন উদভ্রান্ত করেছেন, আমিও অবশ্য তাদের জন্যে আপনার সরল পথে বসে থাকবো।'),
  ('bn.bengali', 7, 17, 'এরপর তাদের কাছে আসব তাদের সামনের দিক থেকে, পেছন দিক থেকে, ডান দিক থেকে এবং বাম দিক থেকে। আপনি তাদের অধিকাংশকে কৃতজ্ঞ পাবেন না।'),
  ('bn.bengali', 7, 18, 'আল্লাহ বললেনঃ বের হয়ে যা এখান থেকে লাঞ্ছিত ও অপমানিত হয়ে। তাদের যে কেউ তোর পথেচলবে, নিশ্চয় আমি তোদের সবার দ্বারা জাহান্নাম পূর্ণ করে দিব।'),
  ('bn.bengali', 7, 19, 'হে আদম তুমি এবং তোমার স্ত্রী জান্নাতে বসবাস কর। অতঃপর সেখান থেকে যা ইচ্ছা খাও তবে এ বৃক্ষের কাছে যেয়োনা তাহলে তোমরা গোনাহগার হয়ে যাবে।'),
  ('bn.bengali', 7, 20, 'অতঃপর শয়তান উভয়কে প্ররোচিত করল, যাতে তাদের অঙ্গ, যা তাদের কাছে গোপন ছিল, তাদের সামনে প্রকাশ করে দেয়। সে বললঃ তোমাদের পালনকর্তা তোমাদেরকে এ বৃক্ষ থেকে নিষেধ করেননি; তবে তা এ কারণে যে, তোমরা না আবার ফেরেশতা হয়ে যাও-কিংবা হয়ে যাও চিরকাল বসবাসকারী।'),
  ('bn.bengali', 7, 21, 'সে তাদের কাছে কসম খেয়ে বললঃ আমি অবশ্যই তোমাদের হিতাকাঙ্খী।'),
  ('bn.bengali', 7, 22, 'অতঃপর প্রতারণাপূর্বক তাদেরকে সম্মত করে ফেলল। অনন্তর যখন তারা বৃক্ষ আস্বাদন করল, তখন তাদের লজ্জাস্থান তাদের সামনে খুলে গেল এবং তারা নিজের উপর বেহেশতের পাতা জড়াতে লাগল। তাদের প্রতিপালক তাদেরকে ডেকে বললেনঃ আমি কি তোমাদেরকে এ বৃক্ষ থেকে নিষেধ করিনি এবং বলিনি যে, শয়তান তোমাদের প্রকাশ্য শত্রু।'),
  ('bn.bengali', 7, 23, 'তারা উভয়ে বললঃ হে আমাদের পালনকর্তা আমরা নিজেদের প্রতি জুলম করেছি। যদি আপনি আমাদেরকে ক্ষমা না করেন এবং আমাদের প্রতি অনুগ্রহ না করেন, তবে আমরা অবশ্যই অবশ্যই ধ্বংস হয়ে যাব।'),
  ('bn.bengali', 7, 24, 'আল্লাহ বললেনঃ তোমরা নেমে যাও। তোমরা এক অপরের শত্রু। তোমাদের জন্যে পৃথিবীতে বাসস্থান আছে এবং একটি নির্দিষ্ট মেয়াদ পর্যন্ত ফল ভোগ আছে।'),
  ('bn.bengali', 7, 25, 'বললেনঃ তোমরা সেখানেই জীবিত থাকবে, সেখানেই মৃত্যুবরন করবে এবং সেখান থেকেই পুনরুঙ্খিত হবে।'),
  ('bn.bengali', 7, 26, 'হে বনী-আদম আমি তোমাদের জন্যে পোশাক অবর্তীণ করেছি, যা তোমাদের লজ্জাস্থান আবৃত করে এবং অবর্তীণ করেছি সাজ সজ্জার বস্ত্র এবং পরহেযগারীর পোশাক, এটি সর্বোত্তম। এটি আল্লাহর কুদরতেরঅন্যতম নিদর্শন, যাতে তারা চিন্তা-ভাবনা করে।'),
  ('bn.bengali', 7, 27, 'হে বনী-আদম শয়তান যেন তোমাদেরকে বিভ্রান্ত না করে; যেমন সে তোমাদের পিতামাতাকে জান্নাত থেকে বের করে দিয়েছে এমতাবস্থায় যে, তাদের পোশাক তাদের থেকে খুলিয়ে দিয়েছি-যাতে তাদেরকে লজ্জাস্থান দেখিয়ে দেয়। সে এবং তার দলবল তোমাদেরকে দেখে, যেখান থেকে তোমরা তাদেরকে দেখ না। আমি শয়তানদেরকে তাদের বন্ধু করে দিয়েছি, , যারা বিশ্বাস স্থাপন করে না।'),
  ('bn.bengali', 7, 28, 'তারা যখন কোন মন্দ কাজ করে, তখন বলে আমরা বাপ-দাদাকে এমনি করতে দেখেছি এবং আল্লাহও আমাদেরকে এ নির্দেশই দিয়েছেন। আল্লাহ মন্দকাজের আদেশ দেন না। এমন কথা আল্লাহর প্রতি কেন আরোপ কর, যা তোমরা জান না।'),
  ('bn.bengali', 7, 29, 'আপনি বলে দিনঃ আমার প্রতিপালক সুবিচারের নির্দেশ দিয়েছেন এবং তোমরা প্রত্যেক সেজদার সময় স্বীয় মুখমন্ডল সোজা রাখ এবং তাঁকে খাঁটি আনুগত্যশীল হয়ে ডাক। তোমাদেরকে প্রথমে যেমন সৃষ্টি করেছেন, পুনর্বারও সৃজিত হবে।'),
  ('bn.bengali', 7, 30, 'একদলকে পথ প্রদর্শন করেছেন এবং একদলের জন্যে পথভ্রষ্টতা অবধারিত হয়ে গেছে। তারা আল্লাহকে ছেড়ে শয়তানদেরকে বন্ধু হিসাবে গ্রহণ করেছে এবং ধারণা করে যে, তারা সৎপথে রয়েছে।'),
  ('bn.bengali', 7, 31, 'হে বনী-আদম! তোমরা প্রত্যেক নামাযের সময় সাজসজ্জা পরিধান করে নাও, খাও ও পান কর এবং অপব্যয় করো না। তিনি অপব্যয়ীদেরকে পছন্দ করেন না।'),
  ('bn.bengali', 7, 32, 'আপনি বলুনঃ আল্লাহর সাজ-সজ্জাকে, যা তিনি বান্দাদের জন্যে সৃষ্টি করেছেন এবং পবিত্র খাদ্রবস্তুসমূহকে কে হারাম করেছে? আপনি বলুনঃ এসব নেয়ামত আসলে পার্থিব জীবনে মুমিনদের জন্যে এবং কিয়ামতের দিন খাঁটিভাবে তাদেরই জন্যে। এমনিভাবে আমি আয়াতসমূহ বিস্তারিত বর্ণনা করি তাদের জন্যে যারা বুঝে।'),
  ('bn.bengali', 7, 33, 'আপনি বলে দিনঃ আমার পালনকর্তা কেবলমাত্র অশ্লীল বিষয়সমূহ হারাম করেছেন যা প্রকাশ্য ও অপ্রকাশ্য এবং হারাম করেছেন গোনাহ, অন্যায়-অত্যাচার আল্লাহর সাথে এমন বস্তুকে অংশীদার করা, তিনি যার কোন, সনদ অবতীর্ণ করেননি এবং আল্লাহর প্রতি এমন কথা আরোপ করা, যা তোমরা জান না।'),
  ('bn.bengali', 7, 34, 'প্রত্যেক সম্প্রদায়ের একটি মেয়াদ রয়েছে। যখন তাদের মেয়াদ এসে যাবে, তখন তারা না এক মুহুর্ত পিছে যেতে পারবে, আর না এগিয়ে আসতে পারবে।'),
  ('bn.bengali', 7, 35, 'হে বনী-আদম, যদি তোমাদের কাছে তোমাদেরই মধ্য থেকে পয়গম্বর আগমন করে তোমাদেরকে আমার আয়াত সমূহ শুনায়, তবে যে ব্যক্তি সংযত হয় এবং সৎকাজ অবলম্বন করে, তাদের কোন আশঙ্কা নেই এবং তারা দুঃখিত হবে না।'),
  ('bn.bengali', 7, 36, 'যারা আমার আয়াতসমূহকে মিথ্যা বলবে এবং তা থেকে অহংকার করবে, তারাই দোযখী এবং তথায় চিরকাল থাকবে।'),
  ('bn.bengali', 7, 37, 'অতঃপর ঐ ব্যক্তির চাইতে অধিক জালেম কে, যে আল্লাহর প্রতি মিথ্যা আরোপ করে অথবা তার নির্দেশাবলীকে মিথ্যা বলে? তারা তাদের গ্রন্থে লিখিত অংশ পেয়ে যাবে। এমন কি, যখন তাদের কাছে আমার প্রেরিত ফেরশতারা প্রাণ নেওয়ার জন্যে পৌছে, তখন তারা বলে; তারা কোথায় গেল, যাদের কে তোমরা আল্লাহ ব্যতীত আহবান করতে? তারা উত্তর দেবেঃ আমাদের কাছ থেকে উধাও হয়ে গেছে, তারা নিজেদের সম্পর্কে স্বীকার করবে যে, তারা অবশ্যই কাফের ছিল।'),
  ('bn.bengali', 7, 38, 'আল্লাহ বলবেনঃ তোমাদের পূর্বে জিন ও মানবের যেসব সম্প্রদায় চলে গেছে, তাদের সাথে তোমরাও দোযখে যাও। যখন এক সম্প্রদায় প্রবেশ করবে; তখন অন্য সম্প্রদায়কে অভিসম্পাত করবে। এমনকি, যখন তাতে সবাই পতিত হবে, তখন পরবর্তীরা পূর্ববর্তীদের সম্পর্কে বলবেঃ হে আমাদের প্রতিপালক এরাই আমাদেরকে বিপথগামী করেছিল। অতএব, আপনি তাদেরকে দ্বিগুণ শাস্তি দিন। আল্লাহ বলবেন প্রত্যেকেরই দ্বিগুণ; তোমরা জান না।'),
  ('bn.bengali', 7, 39, 'পূর্ববর্তীরা পরবর্তীদেরকে বলবেঃ তাহলে আমাদের উপর তোমাদের কোন শ্রেষ্ঠত্ব নেই অতএব, শাস্তি আস্বাদন কর স্বীয় কর্মের কারণে।'),
  ('bn.bengali', 7, 40, 'নিশ্চয়ই যারা আমার আয়াতসমূহকে মিথ্যা বলেছে এবং এগুলো থেকে অহংকার করেছে, তাদের জন্যে আকাশের দ্বার উম্মুক্ত করা হবে না এবং তারা জান্নাতে প্রবেশ করবে না। যে পর্যন্ত না সূচের ছিদ্র দিয়ে উট প্রবেশ করে। আমি এমনিভাবে পাপীদেরকে শাস্তি প্রদান করি।'),
  ('bn.bengali', 7, 41, 'তাদের জন্যে নরকাগ্নির শয্যা রয়েছে এবং উপর থেকে চাদর। আমি এমনিভাবে জালেমদেরকে শাস্তি প্রদান করি।'),
  ('bn.bengali', 7, 42, 'যারা বিশ্বাস স্থাপন করেছে এবং সৎকর্ম করেছে আমি কাউকে তার সামর্থ্যের চাইতে বেশী বোঝা দেই না। তারাই জান্নাতের অধিবাসী। তারা তাতেই চিরকাল থাকবে।'),
  ('bn.bengali', 7, 43, 'তাদের অন্তরে যা কিছু দুঃখ ছিল, আমি তা বের করে দেব। তাদের তলদেশ দিয়ে নির্ঝরণী প্রবাহিত হবে। তারা বলবেঃ আল্লাহ শোকর, যিনি আমাদেরকে এ পর্যন্ত পৌছিয়েছেন। আমরা কখনও পথ পেতাম না, যদি আল্লাহ আমাদেরকে পথ প্রদর্শন না করতেন। আমাদের প্রতিপালকের রসূল আমাদের কাছে সত্যকথা নিয়ে এসেছিলেন। আওয়াজ আসবেঃ এটি জান্নাত। তোমরা এর উত্তরাধিকারী হলে তোমাদের কর্মের প্রতিদানে।'),
  ('bn.bengali', 7, 44, 'জান্নাতীরা দোযখীদেরকে ডেকে বলবেঃ আমাদের সাথে আমাদের প্রতিপালক যে ওয়াদা করেছিলেন, তা আমরা সত্য পেয়েছি? অতএব, তোমরাও কি তোমাদের প্রতিপালকের ওয়াদা সত্য পেয়েছ? তারা বলবেঃ হ্যাঁ। অতঃপর একজন ঘোষক উভয়ের মাঝখানে ঘোষণা করবেঃ আল্লাহর অভিসম্পাত জালেমদের উপর।'),
  ('bn.bengali', 7, 45, 'যারা আল্লাহর পথে বাধা দিত এবং তাতে বক্রতা অন্বেষণ করত। তারা পরকালের বিষয়েও অবিশ্বাসী ছিল।'),
  ('bn.bengali', 7, 46, 'উভয়ের মাঝখানে একটি প্রাচীর থাকবে এবং আরাফের উপরে অনেক লোক থাকবে। তারা প্রত্যেককে তার চিহ্ন দ্বারা চিনে নেবে। তারা জান্নাতীদেরকে ডেকে বলবেঃ তোমাদের উপর শান্তি বর্ষিত হোক। তারা তখনও জান্নাতে প্রবেশ করবে না, কিন্তু প্রবেশ করার ব্যাপারে আগ্রহী হবে।'),
  ('bn.bengali', 7, 47, 'যখন তাদের দৃষ্টি দোযখীদের উপর পড়বে, তখন বলবেঃ হে আমাদের প্রতিপালক, আমাদেরকে এ জালেমদের সাথী করো না।'),
  ('bn.bengali', 7, 48, 'আরাফবাসীরা যাদেরকে তাদের চিহ্ন দ্বারা চিনবে, তাদেরকে ডেকে বলবে তোমাদের দলবল ও ঔদ্ধত্য তোমাদের কোন কাজে আসেনি।'),
  ('bn.bengali', 7, 49, 'এরা কি তারাই; যাদের সম্পর্কে তোমরা কসম খেয়ে বলতে যে, আল্লাহ এদের প্রতি অনুগ্রহ করবেন না। প্রবেশ কর জান্নাতে। তোমাদের কোন আশঙ্কা নেই এবং তোমরা দুঃখিত হবে না।'),
  ('bn.bengali', 7, 50, 'দোযখীরা জান্নাতীদেরকে ডেকে বলবেঃ আমাদের উপর সামান্য পানি নিক্ষেপ কর অথবা আল্লাহ তোমাদেরকে যে রুযী দিয়েছেন, তা থেকেই কিছু দাও। তারা বলবেঃ আল্লাহ এই উভয় বস্তু কাফেরদের জন্যে নিষিদ্ধ করেছেন,'),
  ('bn.bengali', 7, 51, 'তারা স্বীয় ধর্মকে তামাশা ও খেলা বানিয়ে নিয়েছিল এবং পার্থিব জীবন তাদের কে ধোকায় ফেলে রেখেছিল। অতএব, আমি আজকে তাদেরকে ভুলে যাব; যেমন তারা এ দিনের সাক্ষাৎকে ভুলে গিয়েছিল এবং যেমন তারা আয়াতসমূহকে অবিশ্বাস করত।'),
  ('bn.bengali', 7, 52, 'আমি তাদের কাছে গ্রন্থ পৌছিয়েছি, যা আমি স্বীয় জ্ঞানে বিস্তারিত বর্ণনা করেছি, যা পথপ্রদর্শক এবং মুমিনদের জন্যে রহমত।'),
  ('bn.bengali', 7, 53, 'তারা কি এখন এ অপেক্ষায়ই আছে যে, এর বিষয়বস্তু প্রকাশিত হোক? যেদিন এর বিষয়বস্তু প্রকাশিত হবে, সেদিন পূর্বে যারা একে ভূলে গিয়েছিল, তারা বলবেঃ বাস্তবিকই আমাদের প্রতিপালকের পয়গম্বরগণ সত্যসহ আগমন করেছিলেন। অতএব, আমাদের জন্যে কোন সুপারিশকারী আছে কি যে, সুপারিশ করবে অথবা আমাদেরকে পুনঃ প্রেরণ করা হলে আমরা পূর্বে যা করতাম তার বিপরীত কাজ করে আসতাম। নিশ্চয় তারা নিজেদেরকে ক্ষতিগ্রস্ত করেছে। তারা মনগড়া যা বলত, তা উধাও হয়ে যাবে।'),
  ('bn.bengali', 7, 54, 'নিশ্চয় তোমাদের প্রতিপালক আল্লাহ। তিনি নভোমন্ডল ও ভূমন্ডলকে ছয় দিনে সৃষ্টি করেছেন। অতঃপর আরশের উপর অধিষ্টিত হয়েছেন। তিনি পরিয়ে দেন রাতের উপর দিনকে এমতাবস্থায় যে, দিন দৌড়ে রাতের পিছনে আসে। তিনি সৃষ্টি করেছেন সূর্য, চন্দ্র ও নক্ষত্র দৌড় স্বীয় আদেশের অনুগামী। শুনে রেখ, তাঁরই কাজ সৃষ্টি করা এবং আদেশ দান করা। আল্লাহ, বরকতময় যিনি বিশ্বজগতের প্রতিপালক।'),
  ('bn.bengali', 7, 55, 'তোমরা স্বীয় প্রতিপালককে ডাক, কাকুতি-মিনতি করে এবং সংগোপনে। তিনি সীমা অতিক্রমকারীদেরকে পছন্দ করেন না।'),
  ('bn.bengali', 7, 56, 'পৃথিবীকে কুসংস্কারমুক্ত ও ঠিক করার পর তাতে অনর্থ সৃষ্টি করো না। তাঁকে আহবান কর ভয় ও আশা সহকারে। নিশ্চয় আল্লাহর করুণা সৎকর্মশীলদের নিকটবর্তী।'),
  ('bn.bengali', 7, 57, 'তিনিই বৃষ্টির পূর্বে সুসংবাদবাহী বায়ু পাঠিয়ে দেন। এমনকি যখন বায়ুরাশি পানিপূর্ন মেঘমালা বয়ে আনে, তখন আমি এ মেঘমালাকে একটি মৃত শহরের দিকে হঁ্যাকিয়ে দেই। অতঃপর এ মেঘ থেকে বৃষ্টি ধারা বর্ষণ করি। অতঃপর পানি দ্বারা সব রকমের ফল উৎপন্ন করি। এমনি ভাবে মৃতদেরকে বের করব-যাতে তোমরা চিন্তা কর।'),
  ('bn.bengali', 7, 58, 'যে শহর উৎকৃষ্ট, তার ফসল তার প্রতিপালকের নির্দেশে উৎপন্ন হয় এবং যা নিকৃষ্ট তাতে অল্পই ফসল উৎপন্ন হয়। এমনিভাবে আমি আয়াতসমূহ ঘুরিয়ে ফিরিয়ে বর্ণনা করি কৃতজ্ঞ সম্প্রদায়ের জন্যে।'),
  ('bn.bengali', 7, 59, 'নিশ্চয় আমি নূহকে তার সম্প্রদায়ের প্রতি পাঠিয়েছি। সে বললঃ হে আমার সম্প্রদায়, তোমরা আল্লাহর এবাদত কর। তিনি ব্যতীত তোমাদের কোন উপাস্য নেই। আমি তোমাদের জন্যে একটি মহাদিবসের শাস্তির আশঙ্কা করি।'),
  ('bn.bengali', 7, 60, 'তার সম্প্রদায়ের সর্দাররা বললঃ আমরা তোমাকে প্রকাশ্য পথভ্রষ্টতার মাঝে দেখতে পাচ্ছি।'),
  ('bn.bengali', 7, 61, 'সে বললঃ হে আমার সম্প্রদায়, আমি কখনও ভ্রান্ত নই; কিন্তু আমি বিশ্বপ্রতিপালকের রসূল।'),
  ('bn.bengali', 7, 62, 'তোমাদেরকে প্রতিপালকের পয়গাম পৌঁছাই এবং তোমাদেরকে সদুপদেশ দেই। আমি আল্লাহর পক্ষ থেকে এমনসব বিষয় জানি, যেগুলো তোমরা জান না।'),
  ('bn.bengali', 7, 63, 'তোমরা কি আশ্চর্যবোধ করছ যে, তোমাদের কাছে তোমাদের প্রতিপালকের পক্ষ থেকে তোমাদের মধ্য থেকেই একজনের বাচনিক উপদেশ এসেছে যাতে সে তোমাদেরকে ভীতি প্রদর্শন করে, যেন তোমরা সংযত হও এবং যেন তোমরা অনুগৃহীত হও।'),
  ('bn.bengali', 7, 64, 'অতঃপর তারা তাকে মিথ্যা প্রতিপন্ন করল। আমি তাকে এবং নৌকাস্থিত লোকদেরকে উদ্ধার করলাম এবং যারা মিথ্যারোপ করত, তাদেরকে ডুবিয়ে দিলাম। নিশ্চয় তারা ছিল অন্ধ।'),
  ('bn.bengali', 7, 65, 'আদ সম্প্রদায়ের কাছে প্রেরণ করেছি তাদের ভাই হুদকে। সে বললঃ হে আমার সম্প্রদায়, তোমরা আল্লাহর এবাদত কর। তিনি ব্যতিত তোমাদের কোন উপাস্য নেই।'),
  ('bn.bengali', 7, 66, 'তারা স্প্রদায়ের সর্দররা বললঃ আমরা তোমাকে নির্বোধ দেখতে পাচ্ছি এবং আমরা তোমাকে মিথ্যাবাদী মনে করি।'),
  ('bn.bengali', 7, 67, 'সে বললঃ হে আমার সম্প্রদায়, আমি মোটেই নির্বোধ নই, বরং আমি বিশ্ব প্রতিপালকের প্রেরিত পয়গম্বর।'),
  ('bn.bengali', 7, 68, 'তোমাদের কে প্রতিপালকের পয়গাম পৌঁছাই এবং আমি তোমাদের হিতাকাঙ্ক্ষী বিশ্বস্ত।'),
  ('bn.bengali', 7, 69, 'তোমরা কি আশ্চর্য্যবোধ করছ যে, তোমাদের কাছে তোমাদের পালনকর্তার পক্ষ থেকে তোমাদের মধ্য থেকেই একজনের বাচনিক উপদেশ এসেছে যাতে সে তোমাদেরকে ভীতি প্রদর্শন করে। তোমরা স্মরণ কর, যখন আল্লাহ তোমাদেরকে কওমে নূহের পর সর্দার করেছেন এবং তোমাদের দেহের বিস্তৃতি বেশী করেছেন। তোমরা আল্লাহর নেয়ামতসমূহ স্মরণ কর-যাতে তোমাদের মঙ্গল হয়।'),
  ('bn.bengali', 7, 70, 'তারা বললঃ তুমি কি আমাদের কাছে এজন্যে এসেছ যে আমরা এক আল্লাহর এবাদত করি এবং আমাদের বাপ-দাদা যাদের পূজা করত, তাদেরকে ছেড়ে দেই? অতএব নিয়ে আস আমাদের কাছে যাদ্দ্বারা আমাদেরকে ভয় দেখাচ্ছ, যদি তুমি সত্যবাদী হও।'),
  ('bn.bengali', 7, 71, 'সে বললঃ অবধারিত হয়ে গেছে তোমাদের উপর তোমাদের প্রতিপালকের পক্ষ থেকে শাস্তি ও ক্রোধ। আমার সাথে ঐসব নাম সম্পর্কে কেন তর্ক করছ, যেগুলো তোমরা ও তোমাদের বাপ-দাদারা রেখেছে। আল্লাহ এদের কোন মন্দ অবর্তীণ করেননি। অতএব অপেক্ষা কর। আমিও তোমাদের সাথে অপেক্ষা করছি।'),
  ('bn.bengali', 7, 72, 'অনন্তর আমি তাকে ও তার সঙ্গীদেরকে স্বীয় অনুগ্রহে রক্ষা করলাম এবং যারা আমার আয়াতসমূহে মিথ্যারোপ করত তাদের মূল কেটে দিলাম। তারা মান্যকারী ছিল না।'),
  ('bn.bengali', 7, 73, 'সামুদ সম্প্রদায়ের কাছে প্রেরণ করেছি তাদের ভাই সালেহকে। সে বললঃ হে আমার সম্প্রদায়, তোমরা আল্লাহর এবাদত কর। তিনি ব্যতিত তোমাদের কোন উপাস্য নেই। তোমাদের কাছে তোমাদের প্রতিপালকের পক্ষ থেকে একটি প্রমাণ এসে গেছে। এটি আল্লাহর উষ্টী তোমাদের জন্যে প্রমাণ। অতএব একে ছেড়ে দাও, আল্লাহর ভুমিতে চড়ে বেড়াবে। একে অসৎভাবে স্পর্শ করবে না। অন্যথায় তোমাদেরকে যন্ত্রনাদায়ক শাস্তি পাকড়াও করবে।'),
  ('bn.bengali', 7, 74, 'তোমরা স্মরণ কর, যখন তোমাদেরকে আদ জাতির পরে সর্দার করেছেন; তোমাদেরকে পৃথিবীতে ঠিকানা দিয়েছেন। তোমরা নরম মাটিতে অট্টালিকা নির্মান কর এবং পর্বত গাত্র খনন করে প্রকোষ্ঠ নির্মাণ কর। অতএব আল্লাহর অনুগ্রহ স্মরণ কর এবং পৃথিবীতে অনর্থ সৃষ্টি করো না।'),
  ('bn.bengali', 7, 75, 'তার সম্প্রদায়ের দাম্ভিক সর্দাররা ঈমানদার দারিদ্রদেরকে জিজ্ঞেস করলঃ তোমরা কি বিশ্বাস কর যে সালেহ কে তার পালনকর্তা প্রেরণ করেছেন; তারা বলল আমরা তো তার আনীত বিষয়ের প্রতি বিশ্বাসী।'),
  ('bn.bengali', 7, 76, 'দাম্ভিকরা বললঃ তোমরা যে বিষয়ে বিশ্বাস স্থাপন করেছ, আমরা তাতে অস্বীকৃত।'),
  ('bn.bengali', 7, 77, 'অতঃপর তারা উষ্ট্রীকে হত্যা করল এবং স্বীয় প্রতিপালকের আদেশ অমান্য করল। তারা বললঃ হে ছালেহ, নিয়ে এস যদ্দ্বারা আমাদেরকে ভয় দেখাতে, যদি তুমি রসূল হয়ে থাক।'),
  ('bn.bengali', 7, 78, 'অতঃপর পাকড়াও করল তাদেরকে ভূমিকম্প। ফলে সকাল বেলায় নিজ নিজ গৃহে উপুড় হয়ে পড়ে রইল।'),
  ('bn.bengali', 7, 79, 'ছালেহ তাদের কাছ থেকে প্রস্থান করলো এবং বললঃ হে আমার সম্প্রদায়, আমি তোমাদের কাছে স্বীয় প্রতিপালকের পয়গাম পৌছিয়েছি এবং তোমাদের মঙ্গল কামনা করেছি কিন্তু তোমরা মঙ্গলকাঙ্খীদেরকে ভালবাস না।'),
  ('bn.bengali', 7, 80, 'এবং আমি লূতকে প্রেরণ করেছি। যখন সে স্বীয় সম্প্রদায়কে বললঃ তোমরা কি এমন অশ্লীল কাজ করছ, যা তোমাদের পূর্বে সারা বিশ্বের কেউ করেনি ?'),
  ('bn.bengali', 7, 81, 'তোমরা তো কামবশতঃ পুরুষদের কাছে গমন কর নারীদেরকে ছেড়ে। বরং তোমরা সীমা অতিক্রম করেছ।'),
  ('bn.bengali', 7, 82, 'তাঁর সম্প্রদায় এ ছাড়া কোন উত্তর দিল না যে, বের করে দাও এদেরকে শহর থেকে। এরা খুব সাধু থাকতে চায়।'),
  ('bn.bengali', 7, 83, 'অতঃপর আমি তাকে ও তাঁর পরিবার পরিজনকে বাঁচিয়ে দিলাম, কিন্তু তার স্ত্রী। সে তাদের মধ্যেই রয়ে গেল, যারা রয়ে গিয়েছিল। আমি তাদের উপর প্রস্তর বৃষ্টি বর্ষণ করলাম।'),
  ('bn.bengali', 7, 84, 'অতএব, দেখ গোনাহগারদের পরিণতি কেমন হয়েছে।'),
  ('bn.bengali', 7, 85, 'আমি মাদইয়ানের প্রতি তাদের ভাই শোয়ায়েবকে প্রেরণ করেছি। সে বললঃ হে আমার সম্প্রদায়! তোমরা আল্লাহর এবাদত কর। তিনি ব্যতীত তোমাদের কোন উপাস্য নেই। তোমাদের কাছে তোমাদের প্রতিপালকের পক্ষ থেকে প্রমাণ এসে গেছে। অতএব তোমরা মাপ ও ওজন পূর্ন কর এবং মানুষকে তাদের দ্রব্যদি কম দিয়ো না এবং ভুপৃষ্টের সংস্কার সাধন করার পর তাতে অনর্থ সৃষ্টি করো না। এই হল তোমাদের জন্যে কল্যাণকর, যদি তোমরা বিশ্বাসী হও।'),
  ('bn.bengali', 7, 86, 'তোমরা পথে ঘাটে এ কারণে বসে থেকো না যে, আল্লাহ বিশ্বাসীদেরকে হুমকি দিবে, আল্লাহর পথে বাধা সৃষ্টি করবে এবং তাতে বক্রতা অনুসন্ধান করবে। স্মরণ কর, যখন তোমরা সংখ্যায় অল্প ছিলে অতঃপর আল্লাহ তোমাদেরকে অধিক করেছেন এবং লক্ষ্য কর কিরূপ অশুভ পরিণতি হয়েছে অনর্থকারীদের।'),
  ('bn.bengali', 7, 87, 'আর যদি তোমাদের একদল ঐ বিষয়ের প্রতি বিশ্বাস স্থাপন করে যা নিয়ে আমি প্রেরিত হয়েছি এবং একদল বিশ্বাস স্থাপন করে যা নিয়ে আমি প্রেরিত হয়েছি এবং একদল বিশ্বাস স্থাপন না করে, তবে ছবর কর যে পর্যন্ত আল্লাহ আমাদের মধ্যে মীমাংসা না করে দেন। তিনিই শ্রেষ্ট মীমাংসাকারী।'),
  ('bn.bengali', 7, 88, 'তার সম্প্রদায়ের দাম্ভিক সর্দাররা বললঃ হে শোয়ায়েব, আমরা অবশ্যই তোমাকে এবং তোমার সাথে বিশ্বাস স্থাপনকারীদেরকে শহর থেকে বের করে দেব অথবা তোমরা আমাদের ধর্মে প্রত্যাবর্তন করবে। শোয়ায়েব বললঃ আমরা অপছন্দ করলেও কি ?'),
  ('bn.bengali', 7, 89, 'আমরা আল্লাহর প্রতি মিথ্যা অপবাদকারী হয়ে যাব যদি আমরা তোমাদের ধর্মে প্রত্যাবর্তন করি, অথচ তিনি আমাদেরকে এ থেকে মুক্তি দিয়েছেন। আমাদের কাজ নয় এ ধর্মে প্রত্যাবর্তন করা, কিন্তু আমাদের প্রতি পালক আল্লাহ যদি চান। আমাদের প্রতিপালক প্রত্যেক বস্তুকে স্বীয় জ্ঞান দ্বারা বেষ্টন করে আছেন। আল্লাহর প্রতিই আমরা ভরসা করেছি। হে আমাদের প্রতিপালক আমাদের ও আমাদের সম্প্রদায়ের মধ্যে ফয়সালা করে ছিল যথার্থ ফয়সালা। আপনিই শ্রেষ্টতম ফসলা ফয়সালাকারী।'),
  ('bn.bengali', 7, 90, 'তার সম্প্রদায়ের কাফের সর্দাররা বললঃ যদি তোমরা শোয়ায়েবের অনুসরণ কর, তবে নিশ্চিতই ক্ষতিগ্রস্ত হবে।'),
  ('bn.bengali', 7, 91, 'অনন্তর পাকড়াও করল তাদেরকে ভূমিকম্প। ফলে তারা সকাল বেলায় গৃহ মধ্যে উপুড় হয়ে পড়ে রইল।'),
  ('bn.bengali', 7, 92, 'শোয়ায়েবের প্রতি মিথ্যারোপকারীরা যেন কোন দিন সেখানে বসবাসই করেনি। যারা শোয়ায়েবের প্রতি মিথ্যারোপ করেছিল, তারাই ক্ষতিগ্রস্থ হল।'),
  ('bn.bengali', 7, 93, 'অনন্তর সে তাদের কাছ থেকে প্রস্থান করল এবং বললঃ হে আমার সম্প্রদায়, আমি তোমাদেরকে প্রতিপালকের পয়গাম পৌছে দিয়েছি এবং তোমাদের হিত কামনা করেছি। এখন আমি কাফেরদের জন্যে কেন দুঃখ করব।'),
  ('bn.bengali', 7, 94, 'আর আমি কোন জনপদে কোন নবী পাঠাইনি, তবে (এমতাবস্থায়) যে পাকড়াও করেছি সে জনপদের অধিবাসীদিগকে কষ্ট ও কঠোরতার মধ্যে, যাতে তারা শিথিল হয়ে পড়ে।'),
  ('bn.bengali', 7, 95, 'অতঃপর অকল্যাণের স্থলে তা কল্যাণে বদলে দিয়েছে। এমনকি তারা অনেক বেড়ে গিয়েছি এবং বলতে শুরু করেছে, আমাদের বাপ-দাদাদের উপরও এমন আনন্দ-বেদনা এসেছে। অতঃপর আমি তাদেরকে পাকড়াও করেছি এমন আকস্মিকভাবে যে তারা টেরও পায়নি।'),
  ('bn.bengali', 7, 96, 'আর যদি সে জনপদের অধিবাসীরা ঈমান আনত এবং পরহেযগারী অবলম্বন করত, তবে আমি তাদের প্রতি আসমানী ও পার্থিব নেয়ামত সমূহ উম্মুক্ত করে দিতাম। কিন্তু তারা মিথ্যা প্রতিপন্ন করেছে। সুতরাং আমি তাদেরকে পাকড়াও করেছি তাদের কৃতকর্মের বদলাতে।'),
  ('bn.bengali', 7, 97, 'এখনও কি এই জনপদের অধিবাসীরা এ ব্যাপারে নিশ্চিন্ত যে, আমার আযাব তাদের উপর রাতের বেলায় এসে পড়বে অথচ তখন তারা থাকবে ঘুমে অচেতন।'),
  ('bn.bengali', 7, 98, 'আর এই জনপদের অধিবাসীরা কি নিশ্চিন্ত হয়ে পড়েছে যে, তাদের উপর আমার আযাব দিনের বেলাতে এসে পড়বে অথচ তারা তখন থাকবে খেলা-ধুলায় মত্ত।'),
  ('bn.bengali', 7, 99, 'তারা কি আল্লাহর পাকড়াওয়ের ব্যাপারে নিশ্চিন্ত হয়ে গেছে? বস্তুতঃ আল্লাহর পাকড়াও থেকে তারাই নিশ্চিন্ত হতে পারে, যাদের ধ্বংস ঘনিয়ে আসে।'),
  ('bn.bengali', 7, 100, 'তাদের নিকট কি একথা প্রকাশিত হয়নি, যারা উত্তারাধিকার লাভ করেছে। সেখানকার লোকদের ধ্বংসপ্রাপ্ত হবার পর যদি আমি ইচ্ছা করতাম, , তবে তাদেরকে তাদের পাপের দরুন পাকড়াও করে ফেলতাম। বস্তুতঃ আমি মোহর এঁটে দিয়েছি তাদের অন্তরসমূহের উপর। কাজেই এরা শুনতে পায় না।'),
  ('bn.bengali', 7, 101, 'এগুলো হল সে সব জনপদ যার কিছু বিবরণ আমি আপনাকে অবহিত করছি। আর নিশ্চিতই ওদের কাছে পৌছেছিলেন রসূল নিদর্শন সহকারে। অতঃপর কস্মিনকালও এরা ঈমান আনবার ছিল না, তারপরে যা তার ইতিপূর্বে মিথ্যা বলে প্রতিপন্ন করেছে। এভাবেই আল্লাহ কাফেরদের অন্তরে মোহর এঁটে দেন।'),
  ('bn.bengali', 7, 102, 'আর তাদের অধিকাংশ লোককেই আমি প্রতিজ্ঞা বাস্তবায়নকারীরূপে পাইনি; বরং তাদের অধিকাংশকে পেয়েছি হুকুম অমান্যকারী।'),
  ('bn.bengali', 7, 103, 'অতঃপর আমি তাদের পরে মূসাকে পাঠিয়েছি নিদর্শনাবলী দিয়ে ফেরাউন ও তার সভাসদদের নিকট। বস্তুতঃ ওরা তাঁর মোকাবেলায় কুফরী করেছে। সুতরাং চেয়ে দেখ, কি পরিণতি হয়েছে অনাচারীদের।'),
  ('bn.bengali', 7, 104, 'আর মূসা বললেন, হে ফেরাউন, আমি বিশ্ব-পালনকর্তার পক্ষ থেকে আগত রসূল।'),
  ('bn.bengali', 7, 105, 'আল্লাহর পক্ষ থেকে যে সত্য এসেছে, তার ব্যতিক্রম কিছু না বলার ব্যাপারে আমি সুদৃঢ়। আমি তোমাদের পরওয়ারদেগারের নিদর্শন নিয়ে এসেছি। সুতরাং তুমি বনী ইসরাঈলদেরকে আমার সাথে পাঠিয়ে দাও।'),
  ('bn.bengali', 7, 106, 'সে বলল, যদি তুমি কোন নিদর্শন নিয়ে এসে থাক, তাহলে তা উপস্থিত কর যদি তুমি সত্যবাদী হয়ে থাক।'),
  ('bn.bengali', 7, 107, 'তখন তিনি নিক্ষেপ করলেন নিজের লাঠিখানা এবং তাৎক্ষণাৎ তা জলজ্যান্ত এক অজগরে রূপান্তরিত হয়ে গেল।'),
  ('bn.bengali', 7, 108, 'আর বের করলেন নিজের হাত এবং তা সঙ্গে সঙ্গে দর্শকদের চোখে ধবধবে উজ্জ্বল দেখাতে লাগল।'),
  ('bn.bengali', 7, 109, 'ফেরাউনের সাঙ্গ-পাঙ্গরা বলতে লাগল, নিশ্চয় লোকটি বিজ্ঞ-যাদুকর।'),
  ('bn.bengali', 7, 110, 'সে তোমাদিগকে তোমাদের দেশ থেকে বের করে দিতে চায়। এ ব্যাপারে তোমাদের কি মত?'),
  ('bn.bengali', 7, 111, 'তারা বলল, আপনি তাকে ও তার ভাইকে অবকাশ দান করুন এবং শহরে বন্দরে লোক পাঠিয়ে দিন লোকদের সমবেত করার জন্য।'),
  ('bn.bengali', 7, 112, 'যাতে তারা পরাকাষ্ঠাসম্পন্ন বিজ্ঞ যাদুকরদের এনে সমবেত করে।'),
  ('bn.bengali', 7, 113, 'বস্তুতঃ যাদুকররা এসে ফেরাউনের কাছে উপস্থিত হল। তারা বলল, আমাদের জন্যে কি কোন পারিশ্রমিক নির্ধারিত আছে, যদি আমরা জয়লাভ করি?'),
  ('bn.bengali', 7, 114, 'সে বলল, হ্যাঁ এবং অবশ্যই তোমরা আমার নিকটবর্তী লোক হয়ে যাবে।'),
  ('bn.bengali', 7, 115, 'তারা বলল, হে মূসা! হয় তুমি নিক্ষেপ কর অথবা আমরা নিক্ষেপ করছি।'),
  ('bn.bengali', 7, 116, 'তিনি বললেন, তোমরাই নিক্ষেপ কর। যখন তারা নিক্ষেপ করল তখন লোকদের চোখগুলোকে বাধিয়ে দিল, ভীত-সন্ত্রস্ত করে তুলল এবং মহাযাদু প্রদর্শন করল।'),
  ('bn.bengali', 7, 117, 'তারপর আমি ওহীযোগে মূসাকে বললাম, এবার নিক্ষেপ কর তোমার লাঠিখানা। অতএব সঙ্গে সঙ্গে তা সে সমুদয়কে গিলতে লাগল, যা তারা বানিয়েছিল যাদু বলে।'),
  ('bn.bengali', 7, 118, 'সুতরাং এভাবে প্রকাশ হয়ে গেল সত্য বিষয় এবং ভুল প্রতিপন্ন হয়ে গেল যা কিছু তারা করেছিল।'),
  ('bn.bengali', 7, 119, 'সুতরাং তারা সেখানেই পরাজিত হয়ে গেল এবং অতীব লাঞ্ছিত হল।'),
  ('bn.bengali', 7, 120, 'এবং যাদুকররা সেজদায় পড়ে গেল।'),
  ('bn.bengali', 7, 121, 'বলল, আমরা ঈমান আনছি মহা বিশ্বের পরওয়ারদেগারের প্রতি।'),
  ('bn.bengali', 7, 122, 'যিনি মূসা ও হারুনের পরওয়ারদেগার।'),
  ('bn.bengali', 7, 123, 'ফেরাউন বলল, তোমরা কি (তাহলে) আমার অনুমতি দেয়ার আগেই ঈমান আনলে! এটা প্রতারণা, যা তোমরা এ নগরীতে প্রদর্শন করলে। যাতে করে এ শহরের অধিবাসীদিগকে শহর থেকে বের করে দিতে পার। সুতরাং তোমরা শীঘ্রই বুঝতে পারবে।'),
  ('bn.bengali', 7, 124, 'অবশ্যই আমি কেটে দেব তোমাদের হাত ও পা বিপরীত দিক থেকে। তারপর তোমাদের সবাইকে শূলীতে চড়িয়ে মারব।'),
  ('bn.bengali', 7, 125, 'তারা বলল, আমাদেরকে তো মৃত্যুর পর নিজেদের পরওয়ারদেগারের নিকট ফিরে যেতেই হবে।'),
  ('bn.bengali', 7, 126, 'বস্তুতঃ আমাদের সাথে তোমার শত্রুতা তো এ কারণেই যে, আমরা ঈমান এনেছি আমাদের পরওয়ারদেগারের নিদর্শনসমূহের প্রতি যখন তা আমাদের নিকট পৌঁছেছে। হে আমাদের পরওয়ারদেগার আমাদের জন্য ধৈর্য্যের দ্বার খুলে দাও এবং আমাদেরকে মুসলমান হিসাবে মৃত্যু দান কর।'),
  ('bn.bengali', 7, 127, 'ফেরাউনের সম্প্রদায়ের র্সদাররা বলল, তুমি কি এমনি ছেড়ে দেবে মূসা ও তার সম্প্রদায়কে। দেশময় হৈ-চৈ করার জন্য এবং তোমাকে ও তোমার দেব-দেবীকে বাতিল করে দেবার জন্য। সে বলল, আমি এখনি হত্যা করব তাদের পুত্র সন্তানদিগকে; আর জীবিত রাখব মেয়েদেরকে। বস্তুতঃ আমরা তাদের উপর প্রবল।'),
  ('bn.bengali', 7, 128, 'মূসা বললেন তার কওমকে, সাহায্য প্রার্থনা কর আল্লাহর নিকট এবং ধৈর্য্য ধারণ কর। নিশ্চয়ই এ পৃথিবী আল্লাহর। তিনি নিজের বান্দাদের মধ্যে যাকে ইচ্ছা এর উত্তরাধিকারী বানিয়ে দেন এবং শেষ কল্যাণ মুত্তাকীদের জন্যই নির্ধারিত রয়েছে।'),
  ('bn.bengali', 7, 129, 'তারা বলল, আমাদের কষ্ট ছিল তোমার আসার পূর্বে এবং তোমার আসার পরে। তিনি বললেন, তোমাদের পরওয়ারদেগার শীঘ্রই তোমাদের শক্রদের ধ্বংস করে দেবেন এবং তোমাদেরকে দেশে প্রতিনিধিত্ব দান করবেন। তারপর দেখবেন, তোমরা কেমন কাজ কর।'),
  ('bn.bengali', 7, 130, 'তারপর আমি পাকড়াও করেছি-ফেরাউনের অনুসারীদেরকে দুর্ভিক্ষের মাধ্যমে এবং ফল ফসলের ক্ষয়-ক্ষতির মাধ্যমে যাতে করে তারা উপদেশ গ্রহণ করে।'),
  ('bn.bengali', 7, 131, 'অতঃপর যখন শুভদিন ফিরে আসে, তখন তারা বলতে আরম্ভ করে যে, এটাই আমাদের জন্য উপযোগী। আর যদি অকল্যাণ এসে উপস্থিত হয় তবে তাতে মূসার এবং তাঁর সঙ্গীদের অলক্ষণ বলে অভিহিত করে। শুনে রাখ তাদের অলক্ষণ যে, আল্লাহরই এলেমে রয়েছে, অথচ এরা জানে না।'),
  ('bn.bengali', 7, 132, 'তারা আরও বলতে লাগল, আমাদের উপর জাদু করার জন্য তুমি যে নিদর্শনই নিয়ে আস না কেন আমরা কিন্তু তোমার উপর ঈমান আনছি না।'),
  ('bn.bengali', 7, 133, 'সুতরাং আমি তাদের উপর পাঠিয়ে দিলাম তুফান, পঙ্গপাল, উকুন, ব্যাঙ ও রক্ত প্রভৃতি বহুবিধ নিদর্শন একের পর এক। তারপরেও তারা গর্ব করতে থাকল। বস্তুতঃ তারা ছিল অপরাধপ্রবণ।'),
  ('bn.bengali', 7, 134, 'আর তাদের উপর যখন কোন আযাব পড়ে তখন বলে, হে মূসা আমাদের জন্য তোমার পরওয়ারদেগারের নিকট সে বিষয়ে দোয়া কর যা তিনি তোমার সাথে ওয়াদা করে রেখেছেন। যদি তুমি আমাদের উপর থেকে এ আযাব সরিয়ে দাও, তবে অবশ্যই আমরা ঈমান আনব তোমার উপর এবং তোমার সাথে বনী-ইসরাঈলদেরকে যেতে দেব।'),
  ('bn.bengali', 7, 135, 'অতঃপর যখন আমি তাদের উপর থেকে আযাব তুলে নিতাম নির্ধারিত একটি সময় পর্যন্ত-যেখান পর্যন্ত তাদেরকে পৌছানোর উদ্দেশ্য ছিল, তখন তড়িঘড়ি তারা প্রতিশ্রুতি ভঙ্গ করত।'),
  ('bn.bengali', 7, 136, 'সুতরাং আমি তাদের কাছে থেকে বদলা নিয়ে নিলাম-বস্তুতঃ তাদেরকে সাগরে ডুবিয়ে দিলাম। কারণ, তারা মিথ্যা প্রতিপন্ন করেছিল আমার নিদর্শনসমূহকে এবং তৎপ্রতি অনীহা প্রদর্শন করেছিল।'),
  ('bn.bengali', 7, 137, 'আর যাদেরকে দুর্বল মনে করা হত তাদেরকেও আমি উত্তরাধিকার দান করেছি এ ভুখন্ডের পূর্ব ও পশ্চিম অঞ্চলের যাতে আমি বরকত সন্নিহিত রেখেছি এবং পরিপূর্ণ হয়ে গেছে তোমার পালনকর্তার প্রতিশ্রুত কল্যাণ বনী-ইসরাঈলদের জন্য তাদের ধৈর্য্যধারণের দরুন। আর ধ্বংস করে দিয়েছে সে সবকিছু যা তৈরী করেছিল ফেরাউন ও তার সম্প্রদায় এবং ধ্বংস করেছি যা কিছু তারা সুউচ্চ নির্মাণ করেছিল।'),
  ('bn.bengali', 7, 138, 'বস্তুতঃ আমি সাগর পার করে দিয়েছি বনী-ইসরাঈলদিগকে। তখন তারা এমন এক সম্প্রদায়ের কাছে গিয়ে পৌছাল, যারা স্বহস্তনির্মিত মূর্তিপুজায় নিয়োজিত ছিল। তারা বলতে লাগল, হে মূসা; আমাদের উপাসনার জন্যও তাদের মূর্তির মতই একটি মূর্তি নির্মাণ করে দিন। তিনি বললেন, তোমাদের মধ্যে বড়ই অজ্ঞতা রয়েছে।'),
  ('bn.bengali', 7, 139, 'এরা যে, কাজে নিয়োজিত রয়েছে তা ধ্বংস হবে এবং যা কিছু তারা করেছে তা যে ভুল!'),
  ('bn.bengali', 7, 140, 'তিনি বললেন, তাহলে কি আল্লাহকে ছাড়া তোমাদের জন্য অন্য কোন উপাস্য অনুসন্ধান করব, অথচ তিনিই তোমাদিগকে সারা বিশ্বে শ্রেষ্ঠত্ব দান করেছেন।'),
  ('bn.bengali', 7, 141, 'আর সে সময়ের কথা স্মরণ কর, যখন আমি তোমাদেরকে ফেরাউনের লোকদের কবল থেকে মুক্তি দিয়েছি; তারা তোমাদেরকে দিত নিকৃষ্ট শাস্তি, তোমাদের পুত্র-সন্তানদের মেরে ফেলত এবং মেয়েদের বাঁচিয়ে রাখত। এতে তোমাদের প্রতি তোমাদের পরওয়ারদেগারের বিরাট পরীক্ষা রয়েছে।'),
  ('bn.bengali', 7, 142, 'আর আমি মূসাকে প্রতিশ্রুতি দিয়েছি ত্রিশ রাত্রির এবং সেগুলোকে পূর্ন করেছি আরো দশ দ্বারা। বস্তুতঃ এভাবে চল্লিশ রাতের মেয়াদ পূর্ণ হয়ে গেছে। আর মূসা তাঁর ভাই হারুনকে বললেন, আমার সম্প্রদায়ে তুমি আমার প্রতিনিধি হিসাবে থাক। তাদের সংশোধন করতে থাক এবং হাঙ্গামা সৃষ্টিকারীদের পথে চলো না।'),
  ('bn.bengali', 7, 143, 'তারপর মূসা যখন আমার প্রতিশ্রুত সময় অনুযায়ী এসে হাযির হলেন এবং তাঁর সাথে তার পরওয়ারদেগার কথা বললেন, তখন তিনি বললেন, হে আমার প্রভু, তোমার দীদার আমাকে দাও, যেন আমি তোমাকে দেখতে পাই। তিনি বললেন, তুমি আমাকে কস্মিনকালেও দেখতে পাবে না, তবে তুমি পাহাড়ের দিকে দেখতে থাক, সেটি যদি স্বস্থানে দঁড়িয়ে থাকে তবে তুমিও আমাকে দেখতে পাবে। তারপর যখন তার পরওয়ারদগার পাহাড়ের উপর আপন জ্যোতির বিকিরণ ঘটালেন, সেটিকে বিধ্বস্ত করে দিলেন এবং মূসা অজ্ঞান হয়ে পড়ে গেলেন। অতঃপর যখন তাঁর জ্ঞান ফিরে এল; বললেন, হে প্রভু! তোমার সত্তা পবিত্র, তোমার দরবারে আমি তওবা করছি এবং আমিই সর্বপ্রথম বিশ্বাস স্থাপন করছি।'),
  ('bn.bengali', 7, 144, '(পরওয়ারদেগার) বললেন, হে মূসা, আমি তোমাকে আমার বার্তা পাঠানোর এবং কথা বলার মাধ্যমে লোকদের উপর বিশিষ্টতা দান করেছি। সুতরাং যা কিছু আমি তোমাকে দান করলাম, গ্রহণ কর এবং কৃতজ্ঞ থাক।'),
  ('bn.bengali', 7, 145, 'আর আমি তোমাকে পটে লিখে দিয়েছি সর্বপ্রকার উপদেশ ও বিস্তারিত সব বিষয়। অতএব, এগুলোকে দৃঢ়ভাবে ধারণ কর এবং স্বজাতিকে এর কল্যাণকর বিষয়সমূহ দৃঢ়তার সাথে পালনের নির্দেশ দাও।'),
  ('bn.bengali', 7, 146, 'আমি আমার নিদর্শনসমূহ হতে তাদেরকে ফিরিয়ে রাখি, যারা পৃথিবীতে অন্যায়ভাবে গর্ব করে। যদি তারা সমস্ত নিদর্শন প্রত্যক্ষ করে ফেলে, তবুও তা বিশ্বাস করবে না। আর যদি হেদায়েতের পথ দেখে, তবে সে পথ গ্রহণ করে না। অথচ গোমরাহীর পথ দেখলে তাই গ্রহণ করে নেয়। এর কারণ, তারা আমার নিদর্শনসমূহকে মিথ্যা বলে মনে করেছে এবং তা থেকে বেখবর রয়ে গেছে।'),
  ('bn.bengali', 7, 147, 'বস্তুতঃ যারা মিথ্যা জেনেছে আমার আয়াতসমূকে এবং আখেরাতের সাক্ষাতকে, তাদের যাবতীয় কাজকর্ম ধ্বংস হয়ে গেছে। তেমন বদলাই সে পাবে যেমন আমল করত।'),
  ('bn.bengali', 7, 148, 'আর বানিয়ে নিল মূসার সম্প্রদায় তার অনুপস্থিতিতে নিজেদের অলংকারাদির দ্বারা একটি বাছুর তা থেকে বেরুচ্ছিল ‘হাম্বা হাম্বা’ শব্দ। তারা কি একথাও লক্ষ্য করল না যে, সেটি তাদের সাথে কথাও বলছে না এবং তাদেরকে কোন পথও বাতলে দিচ্ছে না! তারা সেটিকে উপাস্য বানিয়ে নিল। বস্তুতঃ তারা ছিল জালেম।'),
  ('bn.bengali', 7, 149, 'অতঃপর যখন তারা অনুতপ্ত হল এবং বুঝতে পারল যে, আমরা নিশ্চিতই গোমরাহ হয়ে পড়েছি, তখন বলতে লাগল, আমাদের প্রতি যদি আমাদের পরওয়ারদেগার করুণা না করেন, তবে অবশ্যই আমরা ধবংস হয়ে যাব।'),
  ('bn.bengali', 7, 150, 'তারপর যখন মূসা নিজ সম্প্রদায়ে ফিরে এলেন রাগাম্বিত ও অনুতপ্ত অবস্থায়, তখন বললেন, আমার অনুপস্থিতিতে তোমরা আমার কি নিকৃষ্ট প্রতিনিধিত্বটাই না করেছ। তোমরা নিজ পরওয়ারদেগারের হুকুম থেকে কি তাড়াহুড়া করে ফেললে এবং সে তখতীগুলো ছুঁড়ে ফেলে দিলেন এবং নিজের ভাইয়ের মাথার চুল চেপে ধরে নিজের দিকে টানতে লাগলেন। ভাই বললেন, হে আমার মায়ের পুত্র, লোকগুলো যে আমাকে দুর্বল মনে করল এবং আমাকে যে মেরে ফেলার উপক্রম করেছিল। সুতরাং আমার উপর আর শত্রুদের হাসিও না। আর আমাকে জালিমদের সারিতে গন্য করো না।'),
  ('bn.bengali', 7, 151, 'মূসা বললেন, হে আমার পরওয়ারদেগার, ক্ষমা কর আমাকে আর আমার ভাইকে এবং আমাদেরকে তোমার রহমতের অন্তর্ভুক্ত কর। তুমি যে সর্বাধিক করুণাময়।'),
  ('bn.bengali', 7, 152, 'অবশ্য যারা গোবৎসকে উপাস্য বানিয়ে নিয়েছে, তাদের উপর তাদের পরওয়ারদেগারের পক্ষ থেকে পার্থিব এ জীবনেই গযব ও লাঞ্জনা এসে পড়বে। এমনি আমি অপবাদ আরোপকারীদেরকে শাস্তি দিয়ে থাকি।'),
  ('bn.bengali', 7, 153, 'আর যারা মন্দ কাজ করে, তারপরে তওবা করে নেয় এবং ঈমান নিয়ে আসে, তবে নিশ্চয়ই তোমার পরওয়ারদেগার তওবার পর অবশ্য ক্ষমাকারী, করুণাময়।'),
  ('bn.bengali', 7, 154, 'তারপর যখন মূসার রাগ পড়ে গেল, তখন তিনি তখতীগুলো তুলে নিলেন। আর যা কিছু তাতে লেখা ছিল, তা ছিল সে সমস্ত লোকের জন্য হেদায়েত ও রহমত যারা নিজেদের পরওয়ারদেগারকে ভয় করে।'),
  ('bn.bengali', 7, 155, 'আর মূসা বেছে নিলেন নিজের সম্প্রদায় থেকে সত্তর জন লোক আমার প্রতিশ্রুত সময়ের জন্য। তারপর যখন তাদেরকে ভূমিকম্প পাকড়াও করল, তখন বললেন, হে আমার পরওয়ারদেগার, তুমি যদি ইচ্ছা করতে, তবে তাদেরকে আগেই ধ্বংস করে দিতে এবং আমাকেও। আমাদেরকে কি সে কর্মের কারণে ধ্বংস করছ, যা আমার সম্প্রদায়ের নির্বোধ লোকেরা করেছে? এসবই তোমার পরীক্ষা; তুমি যাকে ইচ্ছা এতে পথ ভ্রষ্ট করবে এবং যাকে ইচ্ছা সরলপথে রাখবে। তুমি যে আমাদের রক্ষক-সুতরাং আমাদেরকে ক্ষমা করে দাও এবং আমাদের উপর করুনা কর। তাছাড়া তুমিই তো সর্বাধিক ক্ষমাকারী।'),
  ('bn.bengali', 7, 156, 'আর পৃথিবীতে এবং আখেরাতে আমাদের জন্য কল্যাণ লিখে দাও। আমরা তোমার দিকে প্রত্যাবর্তন করছি। আল্লাহ তা’আলা বললেন, আমার আযাব তারই উপর পরিব্যাপ্ত। সুতরাং তা তাদের জন্য লিখে দেব যারা ভয় রাখে, যাকাত দান করে এবং যারা আমার আয়তসমুহের উপর বিশ্বাস স্থাপন করে।'),
  ('bn.bengali', 7, 157, 'সেসমস্ত লোক, যারা আনুগত্য অবলম্বন করে এ রসূলের, যিনি উম্মী নবী, যাঁর সম্পর্কে তারা নিজেদের কাছে রক্ষিত তওরাত ও ইঞ্জিলে লেখা দেখতে পায়, তিনি তাদেরকে নির্দেশ দেন সৎকর্মের, বারণ করেন অসৎকর্ম থেকে; তাদের জন্য যাবতীয় পবিত্র বস্তু হালাল ঘোষনা করেন ও নিষিদ্ধ করেন হারাম বস্তুসমূহ এবং তাদের উপর থেকে সে বোঝা নামিয়ে দেন এবং বন্দীত্ব অপসারণ করেন যা তাদের উপর বিদ্যমান ছিল। সুতরাং যেসব লোক তাঁর উপর ঈমান এনেছে, তাঁর সাহচর্য অবলম্বন করেছে, তাঁকে সাহায্য করেছে এবং সে নূরের অনুসরণ করেছে যা তার সাথে অবতীর্ণ করা হয়েছে, শুধুমাত্র তারাই নিজেদের উদ্দেশ্য সফলতা অর্জন করতে পেরেছে।'),
  ('bn.bengali', 7, 158, 'বলে দাও, হে মানব মন্ডলী। তোমাদের সবার প্রতি আমি আল্লাহ প্রেরিত রসূল, সমগ্র আসমান ও যমীনে তার রাজত্ব। একমাত্র তাঁকে ছাড়া আর কারো উপাসনা নয়। তিনি জীবন ও মৃত্যু দান করেন। সুতরাং তোমরা সবাই বিশ্বাস স্থাপন করো আল্লাহর উপর তাঁর প্রেরিত উম্মী নবীর উপর, যিনি বিশ্বাস রাখেন আল্লাহর এবং তাঁর সমস্ত কালামের উপর। তাঁর অনুসরণ কর যাতে সরল পথপ্রাপ্ত হতে পার।'),
  ('bn.bengali', 7, 159, 'বস্তুতঃ মূসার সম্প্রদায়ে একটি দল রয়েছে যারা সত্যপথ নির্দেশ করে এবং সে মতেই বিচার করে থাকে।'),
  ('bn.bengali', 7, 160, 'আর আমি পৃথক পৃথক করে দিয়েছি তাদের বার জন পিতামহের সন্তানদেরকে বিরাট বিরাট দলে, এবং নির্দেশ দিয়েছি মুসাকে, যখন তার কাছে তার সম্প্রদায় পানি চাইল যে, স্বীয় যষ্টির দ্বারা আঘাত কর এ পাথরের উপর। অতঃপর এর ভেতর থেকে ফুটে বের হল বারটি প্রস্রবণ। প্রতিটি গোত্র চিনে নিল নিজ নিজ ঘাঁটি। আর আমি ছায়া দান করলাম তাদের উপর মেঘের এবং তাদের জন্য অবতীর্ন করলাম মান্না ও সালওয়া। যে পরিচ্ছন্ন বস্তুত জীবিকারূপে আমি তোমাদের দিয়েছি, তা থেকে তোমরা ভক্ষণ কর। বস্তুতঃ তারা আমার কোন ক্ষতি করেনি, বরং ক্ষতি করেছে নিজেদেরই।'),
  ('bn.bengali', 7, 161, 'আর যখন তাদের প্রতি নির্দেশ হল যে, তোমরা এ নগরীতে বসবাস কর এবং খাও তা থেকে যেখান থেকে ইচ্ছা এবং বল, আমাদের ক্ষমা করুন। আর দরজা দিয়ে প্রবেশ কর প্রণত অবস্থায়। তবে আমি ক্ষমা করে দেব তোমাদের পাপসমুহ। অবশ্য আমি সৎকর্মীদিগকে অতিরিক্ত দান করব।'),
  ('bn.bengali', 7, 162, 'অনন্তর জালেমরা এতে অন্য শব্দ বদলে দিল তার পরিবর্তে, যা তাদেরকে বলা হয়েছিল। সুতরাং আমি তাদের উপর আযাব পাঠিয়েছি আসমান থেকে তাদের অপকর্মের কারণে।'),
  ('bn.bengali', 7, 163, 'আর তাদের কাছে সে জনপদের অবস্থা সম্পর্কে জিজ্ঞেস কর যা ছিল নদীর তীরে অবস্থিত। যখন শনিবার দিনের নির্দেশের ব্যাপারে সীমাতিক্রম করতে লাগল, যখন আসতে লাগল মাছগুলো তাদের কাছে শনিবার দিন পানির উপর, আর যেদিন শনিবার হত না, আসত না। এভাবে আমি তাদেরকে পরীক্ষা করেছি। কারণ, তারা ছিল নাফরমান।'),
  ('bn.bengali', 7, 164, 'আর যখন তাদের মধ্যে থেকে এক সম্প্রদায় বলল, কেন সে লোকদের সদুপদেশ দিচ্ছেন, যাদেরকে আল্লাহ ধ্বংস করে দিতে চান কিংবা আযাব দিতে চান কঠিন আযাব? সে বললঃ তোমাদের পালনকর্তার সামনে দোষ ফুরাবার জন্য এবং এজন্য যেন তারা ভীত হয়।'),
  ('bn.bengali', 7, 165, 'অতঃপর যখন তারা সেসব বিষয় ভুলে গেল, যা তাদেরকে বোঝানো হয়েছিল, তখন আমি সেসব লোককে মুক্তি দান করলাম যারা মন্দ কাজ থেকে বারণ করত। আর পাকড়াও করলাম, গোনাহগারদেরকে নিকৃষ্ট আযাবের মাধ্যমে তাদের না-ফরমানীর দরুন।'),
  ('bn.bengali', 7, 166, 'তারপর যখন তারা এগিয়ে যেতে লাগল সে কর্মে যা থেকে তাদের বারণ করা হয়েছিল, তখন আমি নির্দেশ দিলাম যে, তোমরা লাঞ্ছিত বানর হয়ে যাও।'),
  ('bn.bengali', 7, 167, 'আর সে সময়ের কথা স্মরণ কর, যখন তোমার পালনকর্তা সংবাদ দিয়েছেন যে, অবশ্যই কেয়ামত দিবস পর্যন্ত ইহুদীদের উপর এমন লোক পাঠাতে থাকবেন যারা তাদেরকে নিকৃষ্ট শাস্তি দান করতে থাকবে। নিঃসন্দেহে তোমার পালনকর্তা শীঘ্র শাস্তি দানকারী এবং তিনি ক্ষমাশীল, দয়ালু।'),
  ('bn.bengali', 7, 168, 'আর আমি তাদেরকে বিভক্ত করে দিয়েছি দেশময় বিভিন্ন শ্রেনীতে, তাদের মধ্যে কিছু রয়েছে ভাল আর কিছু রয়েছে অন্য রকম! তাছাড়া আমি তাদেরকে পরীক্ষা করেছি ভাল ও মন্দের মাধ্যমে যাতে তারা ফিরে আসে।'),
  ('bn.bengali', 7, 169, 'তারপর তাদের পেছনে এসেছে কিছু অপদার্থ, যারা উত্তরাধিকারী হয়েছে কিতাবের; তারা নিকৃষ্ট পার্থিব উপকরণ আহরণ করছে এবং বলছে, আমাদের ক্ষমা করে দেয়া হবে। বস্তুতঃ এমনি ধরনের উপকরণ যদি আবারো তাদের সামনে উপস্থিত হয়, তবে তাও তুলে নেবে। তাদের কাছথেকে কিতাবে কি অঙ্গীকার নেয়া হয়নি যে, আল্লাহর প্রতি সত্য ছাড়া কিছু বলবে না? অথচ তারা সে সবই পাঠ করেছে, যা তাতে লেখা রয়েছে। বস্তুতঃ আখেরাতের আলয় ভীতদের জন্য উত্তম-তোমরা কি তা বোঝ না ?'),
  ('bn.bengali', 7, 170, 'আর যেসব লোক সুদৃঢ়ভাবে কিতাবকে আঁকড়ে থাকে এবং নামায প্রতিষ্ঠা করে নিশ্চয়ই আমি বিনষ্ট করব না সৎকর্মীদের সওয়াব।'),
  ('bn.bengali', 7, 171, 'আর যখন আমি তুলে ধরলাম পাহাড়কে তাদের উপরে সামিয়ানার মত এবং তারা ভয় করতে লাগল যে, সেটি তাদের উপর পড়বে, তখন আমি বললাম, ধর, যা আমি তোমাদের দিয়েছি, দৃঢ়ভাবে এবং স্মরণ রেখো যা তাতে রয়েছে, যেন তোমরা বাঁচতে পার।'),
  ('bn.bengali', 7, 172, 'আর যখন তোমার পালনকর্তা বনী আদমের পৃষ্টদেশ থেকে বের করলেন তাদের সন্তানদেরকে এবং নিজের উপর তাদেরকে প্রতিজ্ঞা করালেন, আমি কি তোমাদের পালনকর্তা নই ? তারা বলল, অবশ্যই, আমরা অঙ্গীকার করছি। আবার না কেয়ামতের দিন বলতে শুরু কর যে, এ বিষয়টি আমাদের জানা ছিল না।'),
  ('bn.bengali', 7, 173, 'অথবা বলতে শুরু কর যে, অংশীদারিত্বের প্রথা তো আমাদের বাপ-দাদারা উদ্ভাবন করেছিল আমাদের পূর্বেই। আর আমরা হলাম তাদের পশ্চাৎবর্তী সন্তান-সন্ততি। তাহলে কি সে কর্মের জন্য আমাদেরকে ধ্বংস করবেন, যা পথভ্রষ্টরা করেছে?'),
  ('bn.bengali', 7, 174, 'বস্তুতঃ এভাবে আমি বিষয়সমূহ সবিস্তারে বর্ণনা করি, যাতে তারা ফিরে আসে।'),
  ('bn.bengali', 7, 175, 'আর আপনি তাদেরকে শুনিয়ে দিন, সে লোকের অবস্থা, যাকে আমি নিজের নিদর্শনসমূহ দান করেছিলাম, অথচ সে তা পরিহার করে বেরিয়ে গেছে। আর তার পেছনে লেগেছে শয়তান, ফলে সে পথভ্রষ্টদের অন্তর্ভূক্ত হয়ে পড়েছে।'),
  ('bn.bengali', 7, 176, 'অবশ্য আমি ইচ্ছা করলে তার মর্যাদা বাড়িয়ে দিতাম সে সকল নিদর্শনসমূহের দৌলতে। কিন্তু সে যে অধঃপতিত এবং নিজের রিপুর অনুগামী হয়ে রইল। সুতরাং তার অবস্থা হল কুকুরের মত; যদি তাকে তাড়া কর তবুও হাঁপাবে আর যদি ছেড়ে দাও তবুও হাঁপাবে। এ হল সেসব লোকের উদাহরণ; যারা মিথ্যা প্রতিপন্ন করেছে আমার নিদর্শনসমূহকে। অতএব, আপনি বিবৃত করুন এসব কাহিনী, যাতে তারা চিন্তা করে।'),
  ('bn.bengali', 7, 177, 'তাদের উদাহরণ অতি নিকৃষ্ট, যারা মিথ্যা প্রতিপন্ন করেছে আমার আয়াত সমূহকে এবং তারা নিজেদেরই ক্ষতি সাধন করেছে।'),
  ('bn.bengali', 7, 178, 'যাকে আল্লাহ পথ দেখাবেন, সেই পথপ্রাপ্ত হবে। আর যাকে তিনি পথ ভ্রষ্ট করবেন, সে হবে ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 7, 179, 'আর আমি সৃষ্টি করেছি দোযখের জন্য বহু জ্বিন ও মানুষ। তাদের অন্তর রয়েছে, তার দ্বারা বিবেচনা করে না, তাদের চোখ রয়েছে, তার দ্বারা দেখে না, আর তাদের কান রয়েছে, তার দ্বারা শোনে না। তারা চতুষ্পদ জন্তুর মত; বরং তাদের চেয়েও নিকৃষ্টতর। তারাই হল গাফেল, শৈথিল্যপরায়ণ।'),
  ('bn.bengali', 7, 180, 'আর আল্লাহর জন্য রয়েছে সব উত্তম নাম। কাজেই সে নাম ধরেই তাঁকে ডাক। আর তাদেরকে বর্জন কর, যারা তাঁর নামের ব্যাপারে বাঁকা পথে চলে। তারা নিজেদের কৃতকর্মের ফল শীঘ্রই পাবে।'),
  ('bn.bengali', 7, 181, 'আর যাদেরকে আমি সৃষ্টি করেছি, তাদের মধ্যে এমন এক দল রয়েছে যারা সত্য পথ দেখায় এবং সে অনুযায়ী ন্যায়চিার করে।'),
  ('bn.bengali', 7, 182, 'বস্তুতঃ যারা মিথ্যা প্রতিপন্ন করেছে আমার আয়াতসমূহকে, আমি তাদেরকে ক্রমান্বয়ে পাকড়াও করব এমন জায়গা থেকে, যার সম্পর্কে তাদের ধারণাও হবে না।'),
  ('bn.bengali', 7, 183, 'বস্তুতঃ আমি তাদেরকে ঢিল দিয়ে থাকি। নিঃসন্দেহে আমার কৌশল সুনিপুণ।'),
  ('bn.bengali', 7, 184, 'তারা কি লক্ষ্য করেনি যে, তাদের সঙ্গী লোকটির মস্তিষ্কে কোন বিকৃতি নেই? তিনি তো ভীতি প্রদর্শনকারী প্রকৃষ্টভাবে।'),
  ('bn.bengali', 7, 185, 'তারা কি প্রত্যক্ষ করেনি আকাশ ও পৃথিবীর রাজ্য সম্পর্কে এবং যা কিছু সৃষ্টি করেছেন আল্লাহ তা’আলা বস্তু সামগ্রী থেকে এবং এ ব্যাপারে যে, তাদের সাথে কৃত ওয়াদার সময় নিকটবর্তী হয়ে এসেছে? বস্তুতঃ এরপর কিসের উপর ঈমান আনবে?'),
  ('bn.bengali', 7, 186, 'আল্লাহ যাকে পথভ্রষ্ট করেন। তার কোন পথপ্রদর্শক নেই। আর আল্লাহ তাদেরকে তাদের দুষ্টামীতে মত্ত অবস্তায় ছেড়ে দিয়ে রাখেন।'),
  ('bn.bengali', 7, 187, 'আপনাকে জিজ্ঞেস করে, কেয়ামত কখন অনুষ্ঠিত হবে? বলে দিন এর খবর তো আমার পালনকর্তার কাছেই রয়েছে। তিনিই তা অনাবৃত করে দেখাবেন নির্ধারিত সময়ে। আসমান ও যমীনের জন্য সেটি অতি কঠিন বিষয়। যখন তা তোমাদের উপর আসবে অজান্তেই এসে যাবে। আপনাকে জিজ্ঞেস করতে থাকে, যেন আপনি তার অনুসন্ধানে লেগে আছেন। বলে দিন, এর সংবাদ বিশেষ করে আল্লাহর নিকটই রয়েছে। কিন্তু তা অধিকাংশ লোকই উপলব্ধি করে না।'),
  ('bn.bengali', 7, 188, 'আপনি বলে দিন, আমি আমার নিজের কল্যাণ সাধনের এবং অকল্যাণ সাধনের মালিক নই, কিন্তু যা আল্লাহ চান। আর আমি যদি গায়বের কথা জেনে নিতে পারতাম, তাহলে বহু মঙ্গল অর্জন করে নিতে পারতাম, ফলে আমার কোন অমঙ্গল কখনও হতে পারত না। আমি তো শুধুমাত্র একজন ভীতি প্রদর্শক ও সুসংবাদদাতা ঈমানদারদের জন্য।'),
  ('bn.bengali', 7, 189, 'তিনিই সে সত্তা যিনি তোমাদিগকে সৃষ্টি করেছেন একটি মাত্র সত্তা থেকে; আর তার থেকেই তৈরী করেছেন তার জোড়া, যাতে তার কাছে স্বস্তি পেতে পারে। অতঃপর পুরুষ যখন নারীকে আবৃত করল, তখন, সে গর্ভবতী হল। অতি হালকা গর্ভ। সে তাই নিয়ে চলাফেরা করতে থাকল। তারপর যখন বোঝা হয়ে গেল, তখন উভয়েই আল্লাহকে ডাকল যিনি তাদের পালনকর্তা যে, তুমি যদি আমাদিগকে সুস্থ ও ভাল দান কর তবে আমরা তোমার শুকরিয়া আদায় করব।'),
  ('bn.bengali', 7, 190, 'অতঃপর তাদেরকে যখন সুস্থ ও ভাল দান করা হল, তখন দানকৃত বিষয়ে তার অংশীদার তৈরী করতে লাগল। বস্তুতঃ আল্লাহ তাদের শরীক সাব্যস্ত করা থেকে বহু উর্ধে।'),
  ('bn.bengali', 7, 191, 'তারা কি এমন কাউকে শরীক সাব্যস্ত করে, যে একটি বস্তুও সৃষ্টি করেনি, বরং তাদেরকে সৃষ্টি করা হয়েছে।'),
  ('bn.bengali', 7, 192, 'আর তারা, না তাদের সাহায্য করতে পারে, না নিজের সাহায্য করতে পারে।'),
  ('bn.bengali', 7, 193, 'আর তোমরা যদি তাদেরকে আহবান কর সুপথের দিকে, তবে তারা তোমাদের আহবান অনুযায়ী চলবে না। তাদেরকে আহবান জানানো কিংবা নীরব থাকা উভয়টিই তোমাদের জন্য সমান।'),
  ('bn.bengali', 7, 194, 'আল্লাহকে বাদ দিয়ে তোমরা যাদেরকে ডাক, তারা সবাই তোমাদের মতই বান্দা। অতএব, তোমরা যাদেরকে ডাক, তখন তাদের পক্ষেও তো তোমাদের সে ডাক কবুল করা উচিত যদি তোমরা সত্যবাদী হয়ে থাক?'),
  ('bn.bengali', 7, 195, 'তাদের কি পা আছে, যদ্বারা তারা চলাফেরা করে, কিংবা তাদের কি হাত আছে, যদ্বারা তারা ধরে। অথবা তাদের কি চোখ আছে যদ্বারা তারা দেখতে পায় কিংবা তাদের কি কান আছে যদ্বারা শুনতে পায়? বলে দাও, তোমরা ডাক তোমাদের অংশীদারদিগকে, অতঃপর আমার অমঙ্গল কর এবং আমাকে অবকাশ দিও না।'),
  ('bn.bengali', 7, 196, 'আমার সহায় তো হলেন আল্লাহ, যিনি কিতাব অবতীর্ণ করেছেন। বস্তুত; তিনিই সাহায্য করেন সৎকর্মশীল বান্দাদের।'),
  ('bn.bengali', 7, 197, 'আর তোমরা তাঁকে বাদ দিয়ে যাদেরকে ডাক তারা না তোমাদের কোন সাহায্য করতে পারবে, না নিজেদের আত্নরক্ষা করতে পারবে।'),
  ('bn.bengali', 7, 198, 'আর তুমি যদি তাদেরকে সুপথে আহবান কর, তবে তারা তা কিছুই শুনবে না। আর তুমি তো তাদের দেখছই, তোমার দিকে তাকিয়ে আছে, অথচ তারা কিছুই দেখতে পাচ্ছে না।'),
  ('bn.bengali', 7, 199, 'আর ক্ষমা করার অভ্যাস গড়ে তোল, সৎকাজের নির্দেশ দাও এবং মূর্খ জাহেলদের থেকে দূরে সরে থাক।'),
  ('bn.bengali', 7, 200, 'আর যদি শয়তানের প্ররোচনা তোমাকে প্ররোচিত করে, তাহলে আল্লাহর শরণাপন্ন হও তিনিই শ্রবণকারী, মহাজ্ঞানী।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 7, 201, 'যাদের মনে ভয় রয়েছে, তাদের উপর শয়তানের আগমন ঘটার সাথে সাথেই তারা সতর্ক হয়ে যায় এবং তখনই তাদের বিবেচনাশক্তি জাগ্রত হয়ে উঠে।'),
  ('bn.bengali', 7, 202, 'পক্ষান্তরে যারা শয়তানের ভাই, তাদেরকে সে ক্রমাগত পথভ্রষ্ট তার দিকে নিয়ে যায় অতঃপর তাতে কোন কমতি করে না।'),
  ('bn.bengali', 7, 203, 'আর যখন আপনি তাদের নিকট কোন নিদর্শন নিয়ে না যান, তখন তারা বলে, আপনি নিজের পক্ষ থেকে কেন অমুকটি নিয়ে আসলেন না, তখন আপনি বলে দিন, আমি তো সে মতেই চলি যে হুকুম আমার নিকট আসে আমার পরওয়ারদেগারের কাছ থেকে। এটা ভাববার বিষয় তোমাদের পরওয়ারদেগারের পক্ষ থেকে এবং হেদায়েত ও রহমত সেসব লোকের জন্য যারা ঈমান এনেছে।'),
  ('bn.bengali', 7, 204, 'আর যখন কোরআন পাঠ করা হয়, তখন তাতে কান লাগিয়ে রাখ এবং নিশ্চুপ থাক যাতে তোমাদের উপর রহমত হয়।'),
  ('bn.bengali', 7, 205, 'আর স্মরণ করতে থাক স্বীয় পালনকর্তাকে আপন মনে ক্রন্দনরত ও ভীত-সন্ত্রস্ত অবস্থায় এবং এমন স্বরে যা চিৎকার করে বলা অপেক্ষা কম; সকালে ও সন্ধ্যায়। আর বে-খবর থেকো না।'),
  ('bn.bengali', 7, 206, 'নিশ্চয়ই যারা তোমার পরওয়ারদেগারের সান্নিধ্যে রয়েছেন, তারা তাঁর বন্দেগীর ব্যাপারে অহঙ্কার করেন না এবং স্মরণ করেন তাঁর পবিত্র সত্তাকে; আর তাঁকেই সেজদা করেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 7, 1, 'Alif. Lam. Mim. Sad.'),
  ('en.pickthall', 7, 2, '(It is) a Scripture that is revealed unto thee (Muhammad) - so let there be no heaviness in thy heart therefrom - that thou mayst warn thereby, and (it is) a Reminder unto believers.'),
  ('en.pickthall', 7, 3, '(Saying): Follow that which is sent down unto you from your Lord, and follow no protecting friends beside Him. Little do ye recollect!'),
  ('en.pickthall', 7, 4, 'How many a township have We destroyed! As a raid by night, or while they slept at noon, Our terror came unto them.'),
  ('en.pickthall', 7, 5, 'No plea had they, when Our terror came unto them, save that they said: Lo! We were wrong-doers.'),
  ('en.pickthall', 7, 6, 'Then verily We shall question those unto whom (Our message) hath been sent, and verily We shall question the messengers.'),
  ('en.pickthall', 7, 7, 'Then verily We shall narrate unto them (the event) with knowledge, for We were not absent (when it came to pass).'),
  ('en.pickthall', 7, 8, 'The weighing on that day is the true (weighing). As for those whose scale is heavy, they are the successful.'),
  ('en.pickthall', 7, 9, 'And as for those whose scale is light: those are they who lose their souls because they used to wrong Our revelations.'),
  ('en.pickthall', 7, 10, 'And We have given you (mankind) power in the earth, and appointed for you therein livelihoods. Little give ye thanks!'),
  ('en.pickthall', 7, 11, 'And We created you, then fashioned you, then told the angels: Fall ye prostrate before Adam! And they fell prostrate, all save Iblis, who was not of those who make prostration.'),
  ('en.pickthall', 7, 12, 'He said: What hindered thee that thou didst not fall prostrate when I bade thee? (Iblis) said: I am better than him. Thou createdst me of fire while him Thou didst create of mud.'),
  ('en.pickthall', 7, 13, 'He said: Then go down hence! It is not for thee to show pride here, so go forth! Lo! thou art of those degraded.'),
  ('en.pickthall', 7, 14, 'He said: Reprieve me till the day when they are raised (from the dead).'),
  ('en.pickthall', 7, 15, 'He said: Lo! thou art of those reprieved.'),
  ('en.pickthall', 7, 16, 'He said: Now, because Thou hast sent me astray, verily I shall lurk in ambush for them on Thy Right Path.'),
  ('en.pickthall', 7, 17, 'Then I shall come upon them from before them and from behind them and from their right hands and from their left hands, and Thou wilt not find most of them beholden (unto Thee).'),
  ('en.pickthall', 7, 18, 'He said: Go forth from hence, degraded, banished. As for such of them as follow thee, surely I will fill hell with all of you.'),
  ('en.pickthall', 7, 19, 'And (unto man): O Adam! Dwell thou and thy wife in the Garden and eat from whence ye will, but come not nigh this tree lest ye become wrong-doers.'),
  ('en.pickthall', 7, 20, 'Then Satan whispered to them that he might manifest unto them that which was hidden from them of their shame, and he said: Your Lord forbade you from this tree only lest ye should become angels or become of the immortals.'),
  ('en.pickthall', 7, 21, 'And he swore unto them (saying): Lo! I am a sincere adviser unto you.'),
  ('en.pickthall', 7, 22, 'Thus did he lead them on with guile. And when they tasted of the tree their shame was manifest to them and they began to hide (by heaping) on themselves some of the leaves of the Garden. And their Lord called them, (saying): Did I not forbid you from that tree and tell you: Lo! Satan is an open enemy to you?'),
  ('en.pickthall', 7, 23, 'They said: Our Lord! We have wronged ourselves. If thou forgive us not and have not mercy on us, surely we are of the lost!'),
  ('en.pickthall', 7, 24, 'He said: Go down (from hence), one of you a foe unto the other. There will be for you on earth a habitation and provision for a while.'),
  ('en.pickthall', 7, 25, 'He said: There shall ye live, and there shall ye die, and thence shall ye be brought forth.'),
  ('en.pickthall', 7, 26, 'O Children of Adam! We have revealed unto you raiment to conceal your shame, and splendid vesture, but the raiment of restraint from evil, that is best. This is of the revelations of Allah, that they may remember.'),
  ('en.pickthall', 7, 27, 'O Children of Adam! Let not Satan seduce you as he caused your (first) parents to go forth from the Garden and tore off from them their robe (of innocence) that he might manifest their shame to them. Lo! he seeth you, he and his tribe, from whence ye see him not. Lo! We have made the devils protecting friends for those who believe not.'),
  ('en.pickthall', 7, 28, 'And when they do some lewdness they say: We found our fathers doing it and Allah hath enjoined it on us. Say: Allah, verily, enjoineth not lewdness. Tell ye concerning Allah that which ye know not?'),
  ('en.pickthall', 7, 29, 'Say: My Lord enjoineth justice. And set your faces upright (toward Him) at every place of worship and call upon Him, making religion pure for Him (only). As He brought you into being, so return ye (unto Him).'),
  ('en.pickthall', 7, 30, 'A party hath He led aright, while error hath just hold over (another) party, for lo! they choose the devils for protecting supporters instead of Allah and deem that they are rightly guided.'),
  ('en.pickthall', 7, 31, 'O Children of Adam! Look to your adornment at every place of worship, and eat and drink, but be not prodigal. Lo! He loveth not the prodigals.'),
  ('en.pickthall', 7, 32, 'Say: Who hath forbidden the adornment of Allah which He hath brought forth for His bondmen, and the good things of His providing? Say: Such, on the Day of Resurrection, will be only for those who believed during the life of the world. Thus do we detail Our revelations for people who have knowledge.'),
  ('en.pickthall', 7, 33, 'Say: My Lord forbiddeth only indecencies, such of them as are apparent and such as are within, and sin and wrongful oppression, and that ye associate with Allah that for which no warrant hath been revealed, and that ye tell concerning Allah that which ye know not.'),
  ('en.pickthall', 7, 34, 'And every nation hath its term, and when its term cometh, they cannot put it off an hour nor yet advance (it).'),
  ('en.pickthall', 7, 35, 'O Children of Adam! When messengers of your own come unto you who narrate unto you My revelations, then whosoever refraineth from evil and amendeth - there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 7, 36, 'But they who deny Our revelations and scorn them - each are rightful owners of the Fire; they will abide therein.'),
  ('en.pickthall', 7, 37, 'Who doeth greater wrong than he who inventeth a lie concerning Allah or denieth Our tokens. (For such) their appointed portion of the Book (of destiny) reacheth them till, when Our messengers come to gather them, they say: Where (now) is that to which ye cried beside Allah? They say: They have departed from us. And they testify against themselves that they were disbelievers.'),
  ('en.pickthall', 7, 38, 'He saith: Enter into the Fire among nations of the jinn and humankind who passed away before you. Every time a nation entereth, it curseth its sister (nation) till, when they have all been made to follow one another thither, the last of them saith unto the first of them: Our Lord! These led us astray, so give them double torment of the Fire. He saith: For each one there is double (torment), but ye know not.'),
  ('en.pickthall', 7, 39, 'And the first of them saith unto the last of them: Ye were no whit better than us, so taste the doom for what ye used to earn.'),
  ('en.pickthall', 7, 40, 'Lo! they who deny Our revelations and scorn them, for them the gates of heaven will nor be opened not will they enter the Garden until the camel goeth through the needle\'s eye. Thus do We requite the guilty.'),
  ('en.pickthall', 7, 41, 'Theirs will be a bed of hell, and over them coverings (of hell). Thus do We requite wrong-doers.'),
  ('en.pickthall', 7, 42, 'But (as for) those who believe and do good works - We tax not any soul beyond its scope - Such are rightful owners of the Garden. They abide therein.'),
  ('en.pickthall', 7, 43, 'And We remove whatever rancour may be in their hearts. Rivers flow beneath them. And they say: The praise to Allah, Who hath guided us to this. We could not truly have been led aright if Allah had not guided us. Verily the messengers of our Lord did bring the Truth. And it is cried unto them: This is the Garden. Ye inherit it for what ye used to do.'),
  ('en.pickthall', 7, 44, 'And the dwellers of the Garden cry unto the dwellers of the Fire: We have found that which our Lord promised us (to be) the Truth. Have ye (too) found that which your Lord promised the Truth? They say: Yea, verily. And a crier in between them crieth: The curse of Allah is on evil-doers,'),
  ('en.pickthall', 7, 45, 'Who debar (men) from the path of Allah and would have it crooked, and who are disbelievers in the Last Day.'),
  ('en.pickthall', 7, 46, 'Between them is a veil. And on the Heights are men who know them all by their marks. And they call unto the dwellers of the Garden: Peace be unto you! They enter it not although they hope (to enter).'),
  ('en.pickthall', 7, 47, 'And when their eyes are turned toward the dwellers of the Fire, they say: Our Lord! Place us not with the wrong-doing folk.'),
  ('en.pickthall', 7, 48, 'And the dwellers on the Heights call unto men whom they know by their marks, (saying): What did your multitude and that in which ye took your pride avail you?'),
  ('en.pickthall', 7, 49, 'Are these they of whom ye swore that Allah would not show them mercy? (Unto them it hath been said): Enter the Garden. No fear shall come upon you nor is it ye who will grieve.'),
  ('en.pickthall', 7, 50, 'And the dwellers of the Fire cry out unto the dwellers of the Garden: Pour on us some water or some wherewith Allah hath provided you. They say: Lo! Allah hath forbidden both to disbelievers (in His guidance),'),
  ('en.pickthall', 7, 51, 'Who took their religion for a sport and pastime, and whom the life of the world beguiled. So this day We have forgotten them even as they forgot the meeting of this their Day and as they used to deny Our tokens.'),
  ('en.pickthall', 7, 52, 'Verily We have brought them a Scripture which We expounded with knowledge, a guidance and a mercy for a people who believe.'),
  ('en.pickthall', 7, 53, 'Await they aught save the fulfilment thereof? On the day when the fulfilment thereof cometh, those who were before forgetful thereof will say: The messengers of our Lord did bring the Truth! Have we any intercessors, that they may intercede for us? Or can we be returned (to life on earth), that we may act otherwise than we used to act? They have lost their souls, and that which they devised hath failed them.'),
  ('en.pickthall', 7, 54, 'Lo! your Lord is Allah Who created the heavens and the earth in six Days, then mounted He the Throne. He covereth the night with the day, which is in haste to follow it, and hath made the sun and the moon and the stars subservient by His command. His verily is all creation and commandment. Blessed be Allah, the Lord of the Worlds!'),
  ('en.pickthall', 7, 55, '(O mankind!) Call upon your Lord humbly and in secret. Lo! He loveth not aggressors.'),
  ('en.pickthall', 7, 56, 'Work not confusion in the earth after the fair ordering (thereof). and call on Him in fear and hope. Lo! the mercy of Allah is nigh unto the good.'),
  ('en.pickthall', 7, 57, 'And He it is Who sendeth the winds as tidings heralding His mercy, till, when they bear a cloud heavy (with rain), We lead it to a dead land, and then cause water to descend thereon and thereby bring forth fruits of every kind. Thus bring We forth the dead. Haply ye may remember.'),
  ('en.pickthall', 7, 58, 'As for the good land, its vegetation cometh forth by permission of its Lord; while as for that which is bad, only the useless cometh forth (from it). Thus do We recount the tokens for people who give thanks.'),
  ('en.pickthall', 7, 59, 'We sent Noah (of old) unto his people, and he said: O my people! Serve Allah. Ye have no other Allah save Him. Lo! I fear for you the retribution of an Awful Day.'),
  ('en.pickthall', 7, 60, 'The chieftains of his people said: Lo! we see thee surely in plain error.'),
  ('en.pickthall', 7, 61, 'He said: O my people! There is no error in me, but I am a messenger from the Lord of the Worlds.'),
  ('en.pickthall', 7, 62, 'I convey unto you the messages of my Lord and give good counsel unto you, and know from Allah that which ye know not.'),
  ('en.pickthall', 7, 63, 'Marvel ye that there should come unto you a Reminder from your Lord by means of a man among you, that he may warn you, and that ye may keep from evil, and that haply ye may find mercy.'),
  ('en.pickthall', 7, 64, 'But they denied him, so We saved him and those with him in the ship, and We drowned those who denied Our tokens. Lo! they were blind folk.'),
  ('en.pickthall', 7, 65, 'And unto (the tribe of) A\'ad (We sent) their brother, Hud. He said: O my people! Serve Allah. Ye have no other Allah save Him. Will ye not ward off (evil)?'),
  ('en.pickthall', 7, 66, 'The chieftains of his people, who were disbelieving, said: Lo! we surely see thee in foolishness, and lo! we deem thee of the liars.'),
  ('en.pickthall', 7, 67, 'He said: O my people! There is no foolishness in me, but I am a messenger from the Lord of the Worlds.'),
  ('en.pickthall', 7, 68, 'I convey unto you the messages of my Lord and am for you a true adviser.'),
  ('en.pickthall', 7, 69, 'Marvel ye that there should come unto you a Reminder from your Lord by means of a man among you, that he may warn you? Remember how He made you viceroys after Noah\'s folk, and gave you growth of stature. Remember (all) the bounties of your Lord, that haply ye may be successful.'),
  ('en.pickthall', 7, 70, 'They said: Hast come unto us that we should serve Allah alone, and forsake what our fathers worshipped? Then bring upon us that wherewith thou threatenest us if thou art of the truthful!'),
  ('en.pickthall', 7, 71, 'He said: Terror and wrath from your Lord have already fallen on you. Would ye wrangle with me over names which ye have named, ye and your fathers, for which no warrant from Allah hath been revealed? Then await (the consequence), lo! I (also) am of those awaiting (it).'),
  ('en.pickthall', 7, 72, 'And We saved him and those with him by a mercy from Us, and We cut the root of those who denied Our revelations and were not believers.'),
  ('en.pickthall', 7, 73, 'And to (the tribe of) Thamud (We sent) their brother Salih. He said: O my people! Serve Allah. Ye have no other Allah save Him. A wonder from your Lord hath come unto you. Lo! this is the camel of Allah, a token unto you; so let her feed in Allah\'s earth, and touch her not with hurt lest painful torment seize you.'),
  ('en.pickthall', 7, 74, 'And remember how He made you viceroys after A\'ad and gave you station in the earth. Ye choose castles in the plains and hew the mountains into dwellings. So remember (all) the bounties of Allah and do not evil, making mischief in the earth.'),
  ('en.pickthall', 7, 75, 'The chieftains of his people, who were scornful, said unto those whom they despised, unto such of them as believed: Know ye that Salih is one sent from his Lord? They said: Lo! In that wherewith he hath been sent we are believers.'),
  ('en.pickthall', 7, 76, 'Those who were scornful said: Lo! in that which ye believe we are disbelievers.'),
  ('en.pickthall', 7, 77, 'So they hamstrung the she-camel, and they flouted the commandment of their Lord, and they said: O Salih! Bring upon us that thou threatenest if thou art indeed of those sent (from Allah).'),
  ('en.pickthall', 7, 78, 'So the earthquake seized them, and morning found them prostrate in their dwelling-place.'),
  ('en.pickthall', 7, 79, 'And (Salih) turned from them and said: O my people! I delivered my Lord\'s message unto you and gave you good advice, but ye love not good advisers.'),
  ('en.pickthall', 7, 80, 'And Lot! (Remember) when he said unto his folk: Will ye commit abomination such as no creature ever did before you?'),
  ('en.pickthall', 7, 81, 'Lo! ye come with lust unto men instead of women. Nay, but ye are wanton folk.'),
  ('en.pickthall', 7, 82, 'And the answer of his people was only that they said (one to another): Turn them out of your township. They are folk, forsooth, who keep pure.'),
  ('en.pickthall', 7, 83, 'And We rescued him and his household, save his wife, who was of those who stayed behind.'),
  ('en.pickthall', 7, 84, 'And We rained a rain upon them. See now the nature of the consequence of evil-doers!'),
  ('en.pickthall', 7, 85, 'And unto Midian (We sent) their brother, Shu\'eyb. He said: O my people! Serve Allah. Ye have no other Allah save Him. Lo! a clear proof hath come unto you from your Lord; so give full measure and full weight and wrong not mankind in their goods, and work not confusion in the earth after the fair ordering thereof. That will be better for you, if ye are believers.'),
  ('en.pickthall', 7, 86, 'Lurk not on every road to threaten (wayfarers), and to turn away from Allah\'s path him who believeth in Him, and to seek to make it crooked. And remember, when ye were but few, how He did multiply you. And see the nature of the consequence for the corrupters!'),
  ('en.pickthall', 7, 87, 'And if there is a party of you which believeth in that wherewith I have been sent, and there is a party which believeth not, then have patience until Allah judge between us. He is the Best of all who deal in judgment.'),
  ('en.pickthall', 7, 88, 'The chieftains of his people, who were scornful, said: Surely we will drive thee out, O Shu\'eyb, and those who believe with thee, from our township, unless ye return to our religion. He said: Even though we hate it?'),
  ('en.pickthall', 7, 89, 'We should have invented a lie against Allah if we returned to your religion after Allah hath rescued us from it. It is not for us to return to it unless Allah our Lord should (so) will. Our Lord comprehendeth all things in knowledge. In Allah do we put our trust. Our Lord! Decide with truth between us and our folk, for Thou art the best of those who make decision.'),
  ('en.pickthall', 7, 90, 'But the chieftains of his people, who were disbelieving, said: If ye follow Shu\'eyb, then truly ye shall be the losers.'),
  ('en.pickthall', 7, 91, 'So the earthquake seized them and morning found them prostrate in their dwelling-place.'),
  ('en.pickthall', 7, 92, 'Those who denied Shu\'eyb became as though they had not dwelt there. Those who denied Shu\'eyb, they were the losers.'),
  ('en.pickthall', 7, 93, 'So he turned from them and said: O my people! I delivered my Lord\'s messages unto you and gave you good advice; then how can I sorrow for a people that rejected (truth)?'),
  ('en.pickthall', 7, 94, 'And We sent no prophet unto any township but We did afflict its folk with tribulation and adversity that haply they might grow humble.'),
  ('en.pickthall', 7, 95, 'Then changed We the evil plight for good till they grew affluent and said: Tribulation and distress did touch our fathers. Then We seized them unawares, when they perceived not.'),
  ('en.pickthall', 7, 96, 'And if the people of the townships had believed and kept from evil, surely We should have opened for them blessings from the sky and from the earth. But (unto every messenger) they gave the lie, and so We seized them on account of what they used to earn.'),
  ('en.pickthall', 7, 97, 'Are the people of the townships then secure from the coming of Our wrath upon them as a night-raid while they sleep?'),
  ('en.pickthall', 7, 98, 'Or are the people of the townships then secure from the coming of Our wrath upon them in the daytime while they play?'),
  ('en.pickthall', 7, 99, 'Are they then secure from Allah\'s scheme? None deemeth himself secure from Allah\'s scheme save folk that perish.'),
  ('en.pickthall', 7, 100, 'Is it not an indication to those who inherit the land after its people (who thus reaped the consequence of evil-doing) that, if We will, We can smite them for their sins and print upon their hearts so that they hear not?'),
  ('en.pickthall', 7, 101, 'Such were the townships. We relate some tidings of them unto thee (Muhammad). Their messengers verily came unto them with clear proofs (of Allah\'s Sovereignty), but they could not believe because they had before denied. Thus doth Allah print upon the hearts of disbelievers (that they hear not).'),
  ('en.pickthall', 7, 102, 'We found no (loyalty to any) covenant in most of them. Nay, most of them We found wrong-doers.'),
  ('en.pickthall', 7, 103, 'Then, after them, We sent Moses with our tokens unto Pharaoh and his chiefs, but they repelled them. Now, see the nature of the consequence for the corrupters!'),
  ('en.pickthall', 7, 104, 'Moses said: O Pharaoh! Lo! I am a messenger from the Lord of the Worlds,'),
  ('en.pickthall', 7, 105, 'Approved upon condition that I speak concerning Allah nothing but the truth. I come unto you (lords of Egypt) with a clear proof from your Lord. So let the Children of Israel go with me.'),
  ('en.pickthall', 7, 106, '(Pharaoh) said: If thou comest with a token, then produce it, if thou art of those who speak the truth.'),
  ('en.pickthall', 7, 107, 'Then he flung down his staff and lo! it was a serpent manifest;'),
  ('en.pickthall', 7, 108, 'And he drew forth his hand (from his bosom), and lo! it was white for the beholders.'),
  ('en.pickthall', 7, 109, 'The chiefs of Pharaoh\'s people said: Lo! this is some knowing wizard,'),
  ('en.pickthall', 7, 110, 'Who would expel you from your land. Now what do ye advise?'),
  ('en.pickthall', 7, 111, 'They said (unto Pharaoh): Put him off (a while) - him and his brother - and send into the cities summoners,'),
  ('en.pickthall', 7, 112, 'To bring each knowing wizard unto thee.'),
  ('en.pickthall', 7, 113, 'And the wizards came to Pharaoh, saying: Surely there will be a reward for us if we are victors.'),
  ('en.pickthall', 7, 114, 'He answered: Yes, and surely ye shall be of those brought near (to me).'),
  ('en.pickthall', 7, 115, 'They said: O Moses! Either throw (first) or let us be the first throwers?'),
  ('en.pickthall', 7, 116, 'He said: Throw! And when they threw they cast a spell upon the people\'s eyes, and overawed them, and produced a mighty spell.'),
  ('en.pickthall', 7, 117, 'And We inspired Moses (saying): Throw thy staff! And lo! it swallowed up their lying show.'),
  ('en.pickthall', 7, 118, 'Thus was the Truth vindicated and that which they were doing was made vain.'),
  ('en.pickthall', 7, 119, 'Thus were they there defeated and brought low.'),
  ('en.pickthall', 7, 120, 'And the wizards fell down prostrate,'),
  ('en.pickthall', 7, 121, 'Crying: We believe in the Lord of the Worlds,'),
  ('en.pickthall', 7, 122, 'The Lord of Moses and Aaron.'),
  ('en.pickthall', 7, 123, 'Pharaoh said: Ye believe in Him before I give you leave! Lo! this is the plot that ye have plotted in the city that ye may drive its people hence. But ye shall come to know!'),
  ('en.pickthall', 7, 124, 'Surely I shall have your hands and feet cut off upon alternate sides. Then I shall crucify you every one.'),
  ('en.pickthall', 7, 125, 'They said: Lo! We are about to return unto our Lord!'),
  ('en.pickthall', 7, 126, 'Thou takest vengeance on us only forasmuch as we believed the tokens of our Lord when they came unto us. Our Lord! Vouchsafe unto us steadfastness and make us die as men who have surrendered (unto Thee).'),
  ('en.pickthall', 7, 127, 'The chiefs of Pharaoh\'s people said: (O King), wilt thou suffer Moses and his people to make mischief in the land, and flout thee and thy gods? He said: We will slay their sons and spare their women, for lo! we are in power over them.'),
  ('en.pickthall', 7, 128, 'And Moses said unto his people: Seek help in Allah and endure. Lo! the earth is Allah\'s. He giveth it for an inheritance to whom He will. And lo! the sequel is for those who keep their duty (unto Him).'),
  ('en.pickthall', 7, 129, 'They said: We suffered hurt before thou camest unto us, and since thou hast come unto us. He said: It may be that your Lord is going to destroy your adversary and make you viceroys in the earth, that He may see how ye behave.'),
  ('en.pickthall', 7, 130, 'And we straitened Pharaoh\'s folk with famine and dearth of fruits, that peradventure they might heed.'),
  ('en.pickthall', 7, 131, 'But whenever good befell them, they said: This is ours; and whenever evil smote them they ascribed it to the evil auspices of Moses and those with him. Surely their evil auspice was only with Allah. But most of them knew not.'),
  ('en.pickthall', 7, 132, 'And they said: Whatever portent thou bringest wherewith to bewitch us, we shall not put faith in thee.'),
  ('en.pickthall', 7, 133, 'So We sent against them the flood and the locusts and the vermin and the frogs and the blood - a succession of clear signs. But they were arrogant and became a guilty folk.'),
  ('en.pickthall', 7, 134, 'And when the terror fell on them they cried: O Moses! Pray for us unto thy Lord, because He hath a covenant with thee. If thou removest the terror from us we verily will trust thee and will let the Children of Israel go with thee.'),
  ('en.pickthall', 7, 135, 'But when We did remove from them the terror for a term which they must reach, behold! they broke their covenant.'),
  ('en.pickthall', 7, 136, 'Therefore We took retribution from them; therefore We drowned them in the sea: because they denied Our revelations and were heedless of them.'),
  ('en.pickthall', 7, 137, 'And We caused the folk who were despised to inherit the eastern parts of the land and the western parts thereof which We had blessed. And the fair word of thy Lord was fulfilled for the Children of Israel because of their endurance; and We annihilated (all) that Pharaoh and his folk had done and that they had contrived.'),
  ('en.pickthall', 7, 138, 'And We brought the Children of Israel across the sea, and they came unto a people who were given up to idols which they had. They said: O Moses! Make for us a god even as they have gods. He said: Lo! ye are a folk who know not.'),
  ('en.pickthall', 7, 139, 'Lo! as for these, their way will be destroyed and all that they are doing is in vain.'),
  ('en.pickthall', 7, 140, 'He said: Shall I seek for you a god other than Allah when He hath favoured you above (all) creatures?'),
  ('en.pickthall', 7, 141, 'And (remember) when We did deliver you from Pharaoh\'s folk who were afflicting you with dreadful torment, slaughtering your sons and sparing your women. That was a tremendous trial from your Lord.'),
  ('en.pickthall', 7, 142, 'And when We did appoint for Moses thirty nights (of solitude), and added to them ten, and he completed the whole time appointed by his Lord of forty nights; and Moses said unto his brother, Aaron: Take my place among the people. Do right, and follow not the way of mischief-makers.'),
  ('en.pickthall', 7, 143, 'And when Moses came to Our appointed tryst and his Lord had spoken unto him, he said: My Lord! Show me (Thy Self), that I may gaze upon Thee. He said: Thou wilt not see Me, but gaze upon the mountain! If it stand still in its place, then thou wilt see Me. And when his Lord revealed (His) glory to the mountain He sent it crashing down. And Moses fell down senseless. And when he woke he said: Glory unto Thee! I turn unto Thee repentant, and I am the first of (true) believers.'),
  ('en.pickthall', 7, 144, 'He said: O Moses! I have preferred thee above mankind by My messages and by My speaking (unto thee). So hold that which I have given thee, and be among the thankful.'),
  ('en.pickthall', 7, 145, 'And We wrote for him, upon the tablets, the lesson to be drawn from all things and the explanation of all things, then (bade him): Hold it fast; and command thy people (saying): Take the better (course made clear) therein. I shall show thee the abode of evil-livers.'),
  ('en.pickthall', 7, 146, 'I shall turn away from My revelations those who magnify themselves wrongfully in the earth, and if they see each token believe it not, and if they see the way of righteousness choose it nor for (their) way, and if they see the way of error choose if for (their) way. That is because they deny Our revelations and are used to disregard them.'),
  ('en.pickthall', 7, 147, 'Those who deny Our revelations and the meeting of the Hereafter, their works are fruitless. Are they requited aught save what they used to do?'),
  ('en.pickthall', 7, 148, 'And the folk of Moses, after (he left them), chose a calf (for worship), (made) out of their ornaments, of saffron hue, which gave a lowing sound. Saw they not that it spake not unto them nor guided them to any way? They chose it, and became wrong-doers.'),
  ('en.pickthall', 7, 149, 'And when they feared the consequences thereof and saw that they had gone astray, they said: Unless our Lord have mercy on us and forgive us, we verily are of the lost.'),
  ('en.pickthall', 7, 150, 'And when Moses returned unto his people, angry and grieved, he said: Evil is that (course) which ye took after I had left you. Would ye hasten on the judgment of your Lord? And he cast down the tablets, and he seized his brother by the head, dragging him toward him. He said: Son of my mother! Lo! the folk did judge me weak and almost killed me. Oh, make not mine enemies to triumph over me and place me not among the evil-doers.'),
  ('en.pickthall', 7, 151, 'He said: My Lord! Have mercy on me and on my brother; bring us into Thy mercy, Thou the Most Merciful of all who show mercy.'),
  ('en.pickthall', 7, 152, 'Lo! Those who chose the calf (for worship), terror from their Lord and humiliation will come upon them in the life of the world. Thus do We requite those who invent a lie.'),
  ('en.pickthall', 7, 153, 'But those who do ill-deeds and afterward repent and believe - lo! for them, afterward, Allah is Forgiving, Merciful.'),
  ('en.pickthall', 7, 154, 'Then, when the anger of Moses abated, he took up the tablets, and in their inscription there was guidance and mercy for all those who fear their Lord.'),
  ('en.pickthall', 7, 155, 'And Moses chose of his people seventy men for Our appointed tryst and, when the trembling came on them, he said: My Lord! If Thou hadst willed Thou hadst destroyed them long before, and me with them. Wilt thou destroy us for that which the ignorant among us did? It is but Thy trial (of us). Thou sendest whom Thou wilt astray and guidest whom Thou wilt: Thou art our Protecting Friend, therefore forgive us and have mercy on us, Thou, the Best of all who show forgiveness.'),
  ('en.pickthall', 7, 156, 'And ordain for us in this world that which is good, and in the Hereafter (that which is good), Lo! We have turned unto Thee. He said: I smite with My punishment whom I will, and My mercy embraceth all things, therefore I shall ordain it for those who ward off (evil) and pay the poor-due, and those who believe Our revelations;'),
  ('en.pickthall', 7, 157, 'Those who follow the messenger, the Prophet who can neither read nor write, whom they will find described in the Torah and the Gospel (which are) with them. He will enjoin on them that which is right and forbid them that which is wrong. He will make lawful for them all good things and prohibit for them only the foul; and he will relieve them of their burden and the fetters that they used to wear. Then those who believe in him, and honour him, and help him, and follow the light which is sent down with him: they are the successful.'),
  ('en.pickthall', 7, 158, 'Say (O Muhammad): O mankind! Lo! I am the messenger of Allah to you all - (the messenger of) Him unto Whom belongeth the Sovereignty of the heavens and the earth. There is no Allah save Him. He quickeneth and He giveth death. So believe in Allah and His messenger, the Prophet who can neither read nor write, who believeth in Allah and in His Words, and follow him that haply ye may be led aright.'),
  ('en.pickthall', 7, 159, 'And of Moses\' folk there is a community who lead with truth and establish justice therewith.'),
  ('en.pickthall', 7, 160, 'We divided them into twelve tribes, nations; and We inspired Moses, when his people asked him for water, saying: Smite with thy staff the rock! And there gushed forth therefrom twelve springs, so that each tribe knew their drinking-place. And we caused the white cloud to overshadow them and sent down for them the manna and the quails (saying): Eat of the good things wherewith we have provided you. They wronged Us not, but they were wont to wrong themselves.'),
  ('en.pickthall', 7, 161, 'And when it was said unto them: Dwell in this township and eat therefrom whence ye will, and say "Repentance," and enter the gate prostrate; We shall forgive you your sins; We shall increase (reward) for the right-doers.'),
  ('en.pickthall', 7, 162, 'But those of them who did wrong changed the word which had been told them for another saying, and We sent down upon them wrath from heaven for their wrongdoing.'),
  ('en.pickthall', 7, 163, 'Ask them (O Muhammad) of the township that was by the sea, how they did break the Sabbath, how their big fish came unto them visibly upon their Sabbath day and on a day when they did not keep Sabbath came they not unto them. Thus did We try them for that they were evil-livers.'),
  ('en.pickthall', 7, 164, 'And when a community among them said: Why preach ye to a folk whom Allah is about to destroy or punish with an awful doom, they said: In order to be free from guilt before your Lord, and that haply they may ward off (evil).'),
  ('en.pickthall', 7, 165, 'And when they forgot that whereof they had been reminded, We rescued those who forbade wrong, and visited those who did wrong with dreadful punishment because they were evil-livers.'),
  ('en.pickthall', 7, 166, 'So when they took pride in that which they had been forbidden, We said unto them: Be ye apes despised and loathed!'),
  ('en.pickthall', 7, 167, 'And (remember) when thy Lord proclaimed that He would raise against them till the Day of Resurrection those who would lay on them a cruel torment. Lo! verily thy Lord is swift in prosecution and lo! verily He is Forgiving, Merciful.'),
  ('en.pickthall', 7, 168, 'And We have sundered them in the earth as (separate) nations. Some of them are righteous, and some far from that. And We have tried them with good things and evil things that haply they might return.'),
  ('en.pickthall', 7, 169, 'And a generation hath succeeded them who inherited the scriptures. They grasp the goods of this low life (as the price of evil-doing) and say: It will be forgiven us. And if there came to them (again) the offer of the like, they would accept it (and would sin again). Hath not the covenant of the Scripture been taken on their behalf that they should not speak aught concerning Allah save the truth? And they have studied that which is therein. And the abode of the Hereafter is better, for those who ward off (evil). Have ye then no sense?'),
  ('en.pickthall', 7, 170, 'And as for those who make (men) keep the Scripture, and establish worship - lo! We squander not the wages of reformers.'),
  ('en.pickthall', 7, 171, 'And when We shook the Mount above them as it were a covering, and they supposed that it was going to fall upon them (and We said): Hold fast that which We have given you, and remember that which is therein, that ye may ward off (evil).'),
  ('en.pickthall', 7, 172, 'And (remember) when thy Lord brought forth from the Children of Adam, from their reins, their seed, and made them testify of themselves, (saying): Am I not your Lord? They said: Yea, verily. We testify. (That was) lest ye should say at the Day of Resurrection: Lo! of this we were unaware;'),
  ('en.pickthall', 7, 173, 'Or lest ye should say: (It is) only (that) our fathers ascribed partners to Allah of old and we were (their) seed after them. Wilt Thou destroy us on account of that which those who follow falsehood did?'),
  ('en.pickthall', 7, 174, 'Thus we detail the revelations, that haply they may return.'),
  ('en.pickthall', 7, 175, 'Recite unto them the tale of him to whom We gave Our revelations, but he sloughed them off, so Satan overtook him and he became of those who lead astray.'),
  ('en.pickthall', 7, 176, 'And had We willed We could have raised him by their means, but he clung to the earth and followed his own lust. Therefor his likeness is as the likeness of a dog: if thou attackest him he panteth with his tongue out, and if thou leavest him he panteth with his tongue out. Such is the likeness of the people who deny Our revelations. Narrate unto them the history (of the men of old), that haply they may take thought.'),
  ('en.pickthall', 7, 177, 'Evil as an example are the folk who denied Our revelations, and were wont to wrong themselves.'),
  ('en.pickthall', 7, 178, 'He whom Allah leadeth, he indeed is led aright, while he whom Allah sendeth astray - they indeed are losers.'),
  ('en.pickthall', 7, 179, 'Already have We urged unto hell many of the jinn and humankind, having hearts wherewith they understand not, and having eyes wherewith they see not, and having ears wherewith they hear not. These are as the cattle - nay, but they are worse! These are the neglectful.'),
  ('en.pickthall', 7, 180, 'Allah\'s are the fairest names. Invoke Him by them. And leave the company of those who blaspheme His names. They will be requited what they do.'),
  ('en.pickthall', 7, 181, 'And of those whom We created there is a nation who guide with the Truth and establish justice therewith.'),
  ('en.pickthall', 7, 182, 'And those who deny Our revelations - step by step We lead them on from whence they know not.'),
  ('en.pickthall', 7, 183, 'I give them rein (for) lo! My scheme is strong.'),
  ('en.pickthall', 7, 184, 'Have they not bethought them (that) there is no madness in their comrade? He is but a plain warner.'),
  ('en.pickthall', 7, 185, 'Have they not considered the dominion of the heavens and the earth, and what things Allah hath created, and that it may be that their own term draweth nigh? In what fact after this will they believe?'),
  ('en.pickthall', 7, 186, 'Those whom Allah sendeth astray, there is no guide for them. He leaveth them to wander blindly on in their contumacy.'),
  ('en.pickthall', 7, 187, 'They ask thee of the (destined) Hour, when will it come to port. Say: Knowledge thereof is with my Lord only. He alone will manifest it at its proper time. It is heavy in the heavens and the earth. It cometh not to you save unawares. They question thee as if thou couldst be well informed thereof. Say: Knowledge thereof is with Allah only, but most of mankind know not.'),
  ('en.pickthall', 7, 188, 'Say: For myself I have no power to benefit, nor power to hurt, save that which Allah willeth. Had I knowledge of the Unseen, I should have abundance of wealth, and adversity would not touch me. I am but a warner, and a bearer of good tidings unto folk who believe.'),
  ('en.pickthall', 7, 189, 'He it is Who did create you from a single soul, and therefrom did make his mate that he might take rest in her. And when he covered her she bore a light burden, and she passed (unnoticed) with it, but when it became heavy they cried unto Allah, their Lord, saying: If thou givest unto us aright we shall be of the thankful.'),
  ('en.pickthall', 7, 190, 'But when He gave unto them aright, they ascribed unto Him partners in respect of that which He had given them. High is He Exalted above all that they associate (with Him).'),
  ('en.pickthall', 7, 191, 'Attribute they as partners to Allah those who created naught, but are themselves created,'),
  ('en.pickthall', 7, 192, 'And cannot give them help, nor can they help themselves?'),
  ('en.pickthall', 7, 193, 'And if ye call them to the Guidance, they follow you not. Whether ye call them or are silent is all one for you.'),
  ('en.pickthall', 7, 194, 'Lo! those on whom ye call beside Allah are slaves like unto you. Call on them now, and let them answer you, if ye are truthful!'),
  ('en.pickthall', 7, 195, 'Have they feet wherewith they walk, or have they hands wherewith they hold, or have they eyes wherewith they see, or have they ears wherewith they hear? Say: Call upon your (so-called) partners (of Allah), and then contrive against me, spare me not!'),
  ('en.pickthall', 7, 196, 'Lo! my Protecting Friend is Allah Who revealeth the Scripture. He befriendeth the righteous.'),
  ('en.pickthall', 7, 197, 'They on whom ye call beside Him have no power to help you, nor can they help you, nor can they help themselves.'),
  ('en.pickthall', 7, 198, 'And if ye (Muslims) call them to the guidance they hear not; and thou (Muhammad) seest them looking toward thee, but they see not.'),
  ('en.pickthall', 7, 199, 'Keep to forgiveness (O Muhammad), and enjoin kindness, and turn away from the ignorant.'),
  ('en.pickthall', 7, 200, 'And if a slander from the devil wound thee, then seek refuge in Allah. Lo! He is Hearer, Knower.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 7, 201, 'Lo! those who ward off (evil), when a glamour from the devil troubleth them, they do but remember (Allah\'s Guidance) and behold them seers!'),
  ('en.pickthall', 7, 202, 'Their brethren plunge them further into error and cease not.'),
  ('en.pickthall', 7, 203, 'And when thou bringest not a verse for them they say: Why hast thou not chosen it? Say: I follow only that which is inspired in me from my Lord. This (Qur\'an) is insight from your Lord, and a guidance and a mercy for a people that believe.'),
  ('en.pickthall', 7, 204, 'And when the Qur\'an is recited, give ear to it and pay heed, that ye may obtain mercy.'),
  ('en.pickthall', 7, 205, 'And do thou (O Muhammad) remember thy Lord within thyself humbly and with awe, below thy breath, at morn and evening. And be not thou of the neglectful.'),
  ('en.pickthall', 7, 206, 'Lo! those who are with thy Lord are not too proud to do Him service, but they praise Him and prostrate before Him.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 7, 1, 'Alif, Lam, Mim, Sad.'),
  ('en.yusufali', 7, 2, 'A Book revealed unto thee,- So let thy heart be oppressed no more by any difficulty on that account,- that with it thou mightest warn (the erring) and teach the Believers).'),
  ('en.yusufali', 7, 3, 'Follow (O men!) the revelation given unto you from your Lord, and follow not, as friends or protectors, other than Him. Little it is ye remember of admonition.'),
  ('en.yusufali', 7, 4, 'How many towns have We destroyed (for their sins)? Our punishment took them on a sudden by night or while they slept for their afternoon rest.'),
  ('en.yusufali', 7, 5, 'When (thus) Our punishment took them, no cry did they utter but this: "Indeed we did wrong."'),
  ('en.yusufali', 7, 6, 'Then shall we question those to whom Our message was sent and those by whom We sent it.'),
  ('en.yusufali', 7, 7, 'And verily, We shall recount their whole story with knowledge, for We were never absent (at any time or place).'),
  ('en.yusufali', 7, 8, 'The balance that day will be true (to nicety): those whose scale (of good) will be heavy, will prosper:'),
  ('en.yusufali', 7, 9, 'Those whose scale will be light, will be their souls in perdition, for that they wrongfully treated Our signs.'),
  ('en.yusufali', 7, 10, 'It is We Who have placed you with authority on earth, and provided you therein with means for the fulfilment of your life: small are the thanks that ye give!'),
  ('en.yusufali', 7, 11, 'It is We Who created you and gave you shape; then We bade the angels prostrate to Adam, and they prostrate; not so Iblis; He refused to be of those who prostrate.'),
  ('en.yusufali', 7, 12, '(Allah) said: "What prevented thee from prostrating when I commanded thee?" He said: "I am better than he: Thou didst create me from fire, and him from clay."'),
  ('en.yusufali', 7, 13, '(Allah) said: "Get thee down from this: it is not for thee to be arrogant here: get out, for thou art of the meanest (of creatures)."'),
  ('en.yusufali', 7, 14, 'He said: "Give me respite till the day they are raised up."'),
  ('en.yusufali', 7, 15, '(Allah) said: "Be thou among those who have respite."'),
  ('en.yusufali', 7, 16, 'He said: "Because thou hast thrown me out of the way, lo! I will lie in wait for them on thy straight way:'),
  ('en.yusufali', 7, 17, '"Then will I assault them from before them and behind them, from their right and their left: Nor wilt thou find, in most of them, gratitude (for thy mercies)."'),
  ('en.yusufali', 7, 18, '(Allah) said: "Get out from this, disgraced and expelled. If any of them follow thee,- Hell will I fill with you all.'),
  ('en.yusufali', 7, 19, '"O Adam! dwell thou and thy wife in the Garden, and enjoy (its good things) as ye wish: but approach not this tree, or ye run into harm and transgression."'),
  ('en.yusufali', 7, 20, 'Then began Satan to whisper suggestions to them, bringing openly before their minds all their shame that was hidden from them (before): he said: "Your Lord only forbade you this tree, lest ye should become angels or such beings as live for ever."'),
  ('en.yusufali', 7, 21, 'And he swore to them both, that he was their sincere adviser.'),
  ('en.yusufali', 7, 22, 'So by deceit he brought about their fall: when they tasted of the tree, their shame became manifest to them, and they began to sew together the leaves of the garden over their bodies. And their Lord called unto them: "Did I not forbid you that tree, and tell you that Satan was an avowed enemy unto you?"'),
  ('en.yusufali', 7, 23, 'They said: "Our Lord! We have wronged our own souls: If thou forgive us not and bestow not upon us Thy Mercy, we shall certainly be lost."'),
  ('en.yusufali', 7, 24, '(Allah) said: "Get ye down. With enmity between yourselves. On earth will be your dwelling-place and your means of livelihood,- for a time."'),
  ('en.yusufali', 7, 25, 'He said: "Therein shall ye live, and therein shall ye die; but from it shall ye be taken out (at last)."'),
  ('en.yusufali', 7, 26, 'O ye Children of Adam! We have bestowed raiment upon you to cover your shame, as well as to be an adornment to you. But the raiment of righteousness,- that is the best. Such are among the Signs of Allah, that they may receive admonition!'),
  ('en.yusufali', 7, 27, 'O ye Children of Adam! Let not Satan seduce you, in the same manner as He got your parents out of the Garden, stripping them of their raiment, to expose their shame: for he and his tribe watch you from a position where ye cannot see them: We made the evil ones friends (only) to those without faith.'),
  ('en.yusufali', 7, 28, 'When they do aught that is shameful, they say: "We found our fathers doing so"; and "Allah commanded us thus": Say: "Nay, Allah never commands what is shameful: do ye say of Allah what ye know not?"'),
  ('en.yusufali', 7, 29, 'Say: "My Lord hath commanded justice; and that ye set your whole selves (to Him) at every time and place of prayer, and call upon Him, making your devotion sincere as in His sight: such as He created you in the beginning, so shall ye return."'),
  ('en.yusufali', 7, 30, 'Some He hath guided: Others have (by their choice) deserved the loss of their way; in that they took the evil ones, in preference to Allah, for their friends and protectors, and think that they receive guidance.'),
  ('en.yusufali', 7, 31, 'O Children of Adam! wear your beautiful apparel at every time and place of prayer: eat and drink: But waste not by excess, for Allah loveth not the wasters.'),
  ('en.yusufali', 7, 32, 'Say: Who hath forbidden the beautiful (gifts) of Allah, which He hath produced for His servants, and the things, clean and pure, (which He hath provided) for sustenance? Say: They are, in the life of this world, for those who believe, (and) purely for them on the Day of Judgment. Thus do We explain the signs in detail for those who understand.'),
  ('en.yusufali', 7, 33, 'Say: the things that my Lord hath indeed forbidden are: shameful deeds, whether open or secret; sins and trespasses against truth or reason; assigning of partners to Allah, for which He hath given no authority; and saying things about Allah of which ye have no knowledge.'),
  ('en.yusufali', 7, 34, 'To every people is a term appointed: when their term is reached, not an hour can they cause delay, nor (an hour) can they advance (it in anticipation).'),
  ('en.yusufali', 7, 35, 'O ye Children of Adam! whenever there come to you messengers from amongst you, rehearsing My signs unto you,- those who are righteous and mend (their lives),- on them shall be no fear nor shall they grieve.'),
  ('en.yusufali', 7, 36, 'But those who reject Our signs and treat them with arrogance,- they are companions of the Fire, to dwell therein (for ever).'),
  ('en.yusufali', 7, 37, 'Who is more unjust than one who invents a lie against Allah or rejects His Signs? For such, their portion appointed must reach them from the Book (of decrees): until, when our messengers (of death) arrive and take their souls, they say: "Where are the things that ye used to invoke besides Allah?" They will reply, "They have left us in the lurch," And they will bear witness against themselves, that they had rejected Allah.'),
  ('en.yusufali', 7, 38, 'He will say: "Enter ye in the company of the peoples who passed away before you - men and jinns, - into the Fire." Every time a new people enters, it curses its sister-people (that went before), until they follow each other, all into the Fire. Saith the last about the first: "Our Lord! it is these that misled us: so give them a double penalty in the Fire." He will say: "Doubled for all": but this ye do not understand.'),
  ('en.yusufali', 7, 39, 'Then the first will say to the last: "See then! No advantage have ye over us; so taste ye of the penalty for all that ye did!"'),
  ('en.yusufali', 7, 40, 'To those who reject Our signs and treat them with arrogance, no opening will there be of the gates of heaven, nor will they enter the garden, until the camel can pass through the eye of the needle: Such is Our reward for those in sin.'),
  ('en.yusufali', 7, 41, 'For them there is Hell, as a couch (below) and folds and folds of covering above: such is Our requital of those who do wrong.'),
  ('en.yusufali', 7, 42, 'But those who believe and work righteousness,- no burden do We place on any soul, but that which it can bear,- they will be Companions of the Garden, therein to dwell (for ever).'),
  ('en.yusufali', 7, 43, 'And We shall remove from their hearts any lurking sense of injury;- beneath them will be rivers flowing;- and they shall say: "Praise be to Allah, who hath guided us to this (felicity): never could we have found guidance, had it not been for the guidance of Allah: indeed it was the truth, that the messengers of our Lord brought unto us." And they shall hear the cry: "Behold! the garden before you! Ye have been made its inheritors, for your deeds (of righteousness)."'),
  ('en.yusufali', 7, 44, 'The Companions of the Garden will call out to the Companions of the Fire: "We have indeed found the promises of our Lord to us true: Have you also found Your Lord\'s promises true?" They shall say, "Yes"; but a crier shall proclaim between them: "The curse of Allah is on the wrong-doers;-'),
  ('en.yusufali', 7, 45, '"Those who would hinder (men) from the path of Allah and would seek in it something crooked: they were those who denied the Hereafter."'),
  ('en.yusufali', 7, 46, 'Between them shall be a veil, and on the heights will be men who would know every one by his marks: they will call out to the Companions of the Garden, "peace on you": they will not have entered, but they will have an assurance (thereof).'),
  ('en.yusufali', 7, 47, 'When their eyes shall be turned towards the Companions of the Fire, they will say: "Our Lord! send us not to the company of the wrong-doers."'),
  ('en.yusufali', 7, 48, 'The men on the heights will call to certain men whom they will know from their marks, saying: "Of what profit to you were your hoards and your arrogant ways?'),
  ('en.yusufali', 7, 49, '"Behold! are these not the men whom you swore that Allah with His Mercy would never bless? Enter ye the Garden: no fear shall be on you, nor shall ye grieve."'),
  ('en.yusufali', 7, 50, 'The Companions of the Fire will call to the Companions of the Garden: "Pour down to us water or anything that Allah doth provide for your sustenance." They will say: "Both these things hath Allah forbidden to those who rejected Him."'),
  ('en.yusufali', 7, 51, '"Such as took their religion to be mere amusement and play, and were deceived by the life of the world." That day shall We forget them as they forgot the meeting of this day of theirs, and as they were wont to reject Our signs.'),
  ('en.yusufali', 7, 52, 'For We had certainly sent unto them a Book, based on knowledge, which We explained in detail,- a guide and a mercy to all who believe.'),
  ('en.yusufali', 7, 53, 'Do they just wait for the final fulfilment of the event? On the day the event is finally fulfilled, those who disregarded it before will say: "The messengers of our Lord did indeed bring true (tidings). Have we no intercessors now to intercede on our behalf? Or could we be sent back? then should we behave differently from our behaviour in the past." In fact they will have lost their souls, and the things they invented will leave them in the lurch.'),
  ('en.yusufali', 7, 54, 'Your Guardian-Lord is Allah, Who created the heavens and the earth in six days, and is firmly established on the throne (of authority): He draweth the night as a veil o\'er the day, each seeking the other in rapid succession: He created the sun, the moon, and the stars, (all) governed by laws under His command. Is it not His to create and to govern? Blessed be Allah, the Cherisher and Sustainer of the worlds!'),
  ('en.yusufali', 7, 55, 'Call on your Lord with humility and in private: for Allah loveth not those who trespass beyond bounds.'),
  ('en.yusufali', 7, 56, 'Do no mischief on the earth, after it hath been set in order, but call on Him with fear and longing (in your hearts): for the Mercy of Allah is (always) near to those who do good.'),
  ('en.yusufali', 7, 57, 'It is He Who sendeth the winds like heralds of glad tidings, going before His mercy: when they have carried the heavy-laden clouds, We drive them to a land that is dead, make rain to descend thereon, and produce every kind of harvest therewith: thus shall We raise up the dead: perchance ye may remember.'),
  ('en.yusufali', 7, 58, 'From the land that is clean and good, by the will of its Cherisher, springs up produce, (rich) after its kind: but from the land that is bad, springs up nothing but that which is niggardly: thus do we explain the signs by various (symbols) to those who are grateful.'),
  ('en.yusufali', 7, 59, 'We sent Noah to his people. He said: "O my people! worship Allah! ye have no other god but Him. I fear for you the punishment of a dreadful day!'),
  ('en.yusufali', 7, 60, 'The leaders of his people said: "Ah! we see thee evidently wandering (in mind)."'),
  ('en.yusufali', 7, 61, 'He said: "O my people! No wandering is there in my (mind): on the contrary I am a messenger from the Lord and Cherisher of the worlds!'),
  ('en.yusufali', 7, 62, '"I but fulfil towards you the duties of my Lord\'s mission: Sincere is my advice to you, and I know from Allah something that ye know not.'),
  ('en.yusufali', 7, 63, '"Do ye wonder that there hath come to you a message from your Lord, through a man of your own people, to warn you,- so that ye may fear Allah and haply receive His Mercy?"'),
  ('en.yusufali', 7, 64, 'But they rejected him, and We delivered him, and those with him, in the Ark: but We overwhelmed in the flood those who rejected Our signs. They were indeed a blind people!'),
  ('en.yusufali', 7, 65, 'To the \'Ad people, (We sent) Hud, one of their (own) brethren: He said: O my people! worship Allah! ye have no other god but Him will ye not fear (Allah)?"'),
  ('en.yusufali', 7, 66, 'The leaders of the Unbelievers among his people said: "Ah! we see thou art an imbecile!" and "We think thou art a liar!"'),
  ('en.yusufali', 7, 67, 'He said: "O my people! I am no imbecile, but (I am) a messenger from the Lord and Cherisher of the worlds!'),
  ('en.yusufali', 7, 68, '"I but fulfil towards you the duties of my Lord\'s mission: I am to you a sincere and trustworthy adviser.'),
  ('en.yusufali', 7, 69, '"Do ye wonder that there hath come to you a message from your Lord through a man of your own people, to warn you? call in remembrance that He made you inheritors after the people of Noah, and gave you a stature tall among the nations. Call in remembrance the benefits (ye have received) from Allah: that so ye may prosper."'),
  ('en.yusufali', 7, 70, 'They said: "Comest thou to us, that we may worship Allah alone, and give up the cult of our fathers? bring us what thou threatenest us with, if so be that thou tellest the truth!"'),
  ('en.yusufali', 7, 71, 'He said: "Punishment and wrath have already come upon you from your Lord: dispute ye with me over names which ye have devised - ye and your fathers,- without authority from Allah? then wait: I am amongst you, also waiting."'),
  ('en.yusufali', 7, 72, 'We saved him and those who adhered to him. By Our mercy, and We cut off the roots of those who rejected Our signs and did not believe.'),
  ('en.yusufali', 7, 73, 'To the Thamud people (We sent) Salih, one of their own brethren: He said: "O my people! worship Allah: ye have no other god but Him. Now hath come unto you a clear (Sign) from your Lord! This she-camel of Allah is a Sign unto you: So leave her to graze in Allah\'s earth, and let her come to no harm, or ye shall be seized with a grievous punishment.'),
  ('en.yusufali', 7, 74, '"And remember how He made you inheritors after the \'Ad people and gave you habitations in the land: ye build for yourselves palaces and castles in (open) plains, and carve out homes in the mountains; so bring to remembrance the benefits (ye have received) from Allah, and refrain from evil and mischief on the earth."'),
  ('en.yusufali', 7, 75, 'The leaders of the arrogant party among his people said to those who were reckoned powerless - those among them who believed: "know ye indeed that Salih is a messenger from his Lord?" They said: "We do indeed believe in the revelation which hath been sent through him."'),
  ('en.yusufali', 7, 76, 'The Arrogant party said: "For our part, we reject what ye believe in."'),
  ('en.yusufali', 7, 77, 'Then they ham-strung the she-camel, and insolently defied the order of their Lord, saying: "O Salih! bring about thy threats, if thou art a messenger (of Allah)!"'),
  ('en.yusufali', 7, 78, 'So the earthquake took them unawares, and they lay prostrate in their homes in the morning!'),
  ('en.yusufali', 7, 79, 'So Salih left them, saying: "O my people! I did indeed convey to you the message for which I was sent by my Lord: I gave you good counsel, but ye love not good counsellors!"'),
  ('en.yusufali', 7, 80, 'We also (sent) Lut: He said to his people: "Do ye commit lewdness such as no people in creation (ever) committed before you?'),
  ('en.yusufali', 7, 81, '"For ye practise your lusts on men in preference to women: ye are indeed a people transgressing beyond bounds."'),
  ('en.yusufali', 7, 82, 'And his people gave no answer but this: they said, "Drive them out of your city: these are indeed men who want to be clean and pure!"'),
  ('en.yusufali', 7, 83, 'But we saved him and his family, except his wife: she was of those who legged behind.'),
  ('en.yusufali', 7, 84, 'And we rained down on them a shower (of brimstone): Then see what was the end of those who indulged in sin and crime!'),
  ('en.yusufali', 7, 85, 'To the Madyan people We sent Shu\'aib, one of their own brethren: he said: "O my people! worship Allah; Ye have no other god but Him. Now hath come unto you a clear (Sign) from your Lord! Give just measure and weight, nor withhold from the people the things that are their due; and do no mischief on the earth after it has been set in order: that will be best for you, if ye have Faith.'),
  ('en.yusufali', 7, 86, '"And squat not on every road, breathing threats, hindering from the path of Allah those who believe in Him, and seeking in it something crooked; But remember how ye were little, and He gave you increase. And hold in your mind\'s eye what was the end of those who did mischief.'),
  ('en.yusufali', 7, 87, '"And if there is a party among you who believes in the message with which I have been sent, and a party which does not believe, hold yourselves in patience until Allah doth decide between us: for He is the best to decide.'),
  ('en.yusufali', 7, 88, 'The leaders, the arrogant party among his people, said: "O Shu\'aib! we shall certainly drive thee out of our city - (thee) and those who believe with thee; or else ye (thou and they) shall have to return to our ways and religion." He said: "What! even though we do detest (them)?'),
  ('en.yusufali', 7, 89, '"We should indeed invent a lie against Allah, if we returned to your ways after Allah hath rescued us therefrom; nor could we by any manner of means return thereto unless it be as in the will and plan of Allah, Our Lord. Our Lord can reach out to the utmost recesses of things by His knowledge. In the Allah is our trust. our Lord! decide Thou between us and our people in truth, for Thou art the best to decide."'),
  ('en.yusufali', 7, 90, 'The leaders, the unbelievers among his people, said: "If ye follow Shu\'aib, be sure then ye are ruined!"'),
  ('en.yusufali', 7, 91, 'But the earthquake took them unawares, and they lay prostrate in their homes before the morning!'),
  ('en.yusufali', 7, 92, 'The men who reject Shu\'aib became as if they had never been in the homes where they had flourished: the men who rejected Shu\'aib - it was they who were ruined!'),
  ('en.yusufali', 7, 93, 'So Shu\'aib left them, saying: "O my people! I did indeed convey to you the messages for which I was sent by my Lord: I gave you good counsel, but how shall I lament over a people who refuse to believe!"'),
  ('en.yusufali', 7, 94, 'Whenever We sent a prophet to a town, We took up its people in suffering and adversity, in order that they might learn humility.'),
  ('en.yusufali', 7, 95, 'Then We changed their suffering into prosperity, until they grew and multiplied, and began to say: "Our fathers (too) were touched by suffering and affluence"... Behold! We called them to account of a sudden, while they realised not (their peril).'),
  ('en.yusufali', 7, 96, 'If the people of the towns had but believed and feared Allah, We should indeed have opened out to them (All kinds of) blessings from heaven and earth; but they rejected (the truth), and We brought them to book for their misdeeds.'),
  ('en.yusufali', 7, 97, 'Did the people of the towns feel secure against the coming of Our wrath by night while they were asleep?'),
  ('en.yusufali', 7, 98, 'Or else did they feel secure against its coming in broad daylight while they played about (care-free)?'),
  ('en.yusufali', 7, 99, 'Did they then feel secure against the plan of Allah?- but no one can feel secure from the Plan of Allah, except those (doomed) to ruin!'),
  ('en.yusufali', 7, 100, 'To those who inherit the earth in succession to its (previous) possessors, is it not a guiding, (lesson) that, if We so willed, We could punish them (too) for their sins, and seal up their hearts so that they could not hear?'),
  ('en.yusufali', 7, 101, 'Such were the towns whose story We (thus) relate unto thee: There came indeed to them their messengers with clear (signs): But they would not believe what they had rejected before. Thus doth Allah seal up the hearts of those who reject faith.'),
  ('en.yusufali', 7, 102, 'Most of them We found not men (true) to their covenant: but most of them We found rebellious and disobedient.'),
  ('en.yusufali', 7, 103, 'Then after them We sent Moses with Our signs to Pharaoh and his chiefs, but they wrongfully rejected them: So see what was the end of those who made mischief.'),
  ('en.yusufali', 7, 104, 'Moses said: "O Pharaoh! I am a messenger from the Lord of the worlds,-'),
  ('en.yusufali', 7, 105, 'One for whom it is right to say nothing but truth about Allah. Now have I come unto you (people), from your Lord, with a clear (Sign): So let the Children of Israel depart along with me."'),
  ('en.yusufali', 7, 106, '(Pharaoh) said: "If indeed thou hast come with a Sign, show it forth,- if thou tellest the truth."'),
  ('en.yusufali', 7, 107, 'Then (Moses) threw his rod, and behold! it was a serpent, plain (for all to see)!'),
  ('en.yusufali', 7, 108, 'And he drew out his hand, and behold! it was white to all beholders!'),
  ('en.yusufali', 7, 109, 'Said the Chiefs of the people of Pharaoh: "This is indeed a sorcerer well-versed.'),
  ('en.yusufali', 7, 110, '"His plan is to get you out of your land: then what is it ye counsel?"'),
  ('en.yusufali', 7, 111, 'They said: "Keep him and his brother in suspense (for a while); and send to the cities men to collect-'),
  ('en.yusufali', 7, 112, 'And bring up to thee all (our) sorcerers well-versed."'),
  ('en.yusufali', 7, 113, 'So there came the sorcerers to Pharaoh: They said, "of course we shall have a (suitable) reward if we win!"'),
  ('en.yusufali', 7, 114, 'He said: "Yea, (and more),- for ye shall in that case be (raised to posts) nearest (to my person)."'),
  ('en.yusufali', 7, 115, 'They said: "O Moses! wilt thou throw (first), or shall we have the (first) throw?"'),
  ('en.yusufali', 7, 116, 'Said Moses: "Throw ye (first)." So when they threw, they bewitched the eyes of the people, and struck terror into them: for they showed a great (feat of) magic.'),
  ('en.yusufali', 7, 117, 'We put it into Moses\'s mind by inspiration: "Throw (now) thy rod": and behold! it swallows up straight away all the falsehoods which they fake!'),
  ('en.yusufali', 7, 118, 'Thus truth was confirmed, and all that they did was made of no effect.'),
  ('en.yusufali', 7, 119, 'So the (great ones) were vanquished there and then, and were made to look small.'),
  ('en.yusufali', 7, 120, 'But the sorcerers fell down prostrate in adoration.'),
  ('en.yusufali', 7, 121, 'Saying: "We believe in the Lord of the Worlds,-'),
  ('en.yusufali', 7, 122, '"The Lord of Moses and Aaron."'),
  ('en.yusufali', 7, 123, 'Said Pharaoh: "Believe ye in Him before I give you permission? Surely this is a trick which ye have planned in the city to drive out its people: but soon shall ye know (the consequences).'),
  ('en.yusufali', 7, 124, '"Be sure I will cut off your hands and your feet on apposite sides, and I will cause you all to die on the cross."'),
  ('en.yusufali', 7, 125, 'They said: "For us, We are but sent back unto our Lord:'),
  ('en.yusufali', 7, 126, '"But thou dost wreak thy vengeance on us simply because we believed in the Signs of our Lord when they reached us! Our Lord! pour out on us patience and constancy, and take our souls unto thee as Muslims (who bow to thy will)!'),
  ('en.yusufali', 7, 127, 'Said the chiefs of Pharaoh\'s people: "Wilt thou leave Moses and his people, to spread mischief in the land, and to abandon thee and thy gods?" He said: "Their male children will we slay; (only) their females will we save alive; and we have over them (power) irresistible."'),
  ('en.yusufali', 7, 128, 'Said Moses to his people: "Pray for help from Allah, and (wait) in patience and constancy: for the earth is Allah\'s, to give as a heritage to such of His servants as He pleaseth; and the end is (best) for the righteous.'),
  ('en.yusufali', 7, 129, 'They said: "We have had (nothing but) trouble, both before and after thou camest to us." He said: "It may be that your Lord will destroy your enemy and make you inheritors in the earth; that so He may try you by your deeds."'),
  ('en.yusufali', 7, 130, 'We punished the people of Pharaoh with years (of droughts) and shortness of crops; that they might receive admonition.'),
  ('en.yusufali', 7, 131, 'But when good (times) came, they said, "This is due to us;" When gripped by calamity, they ascribed it to evil omens connected with Moses and those with him! Behold! in truth the omens of evil are theirs in Allah\'s sight, but most of them do not understand!'),
  ('en.yusufali', 7, 132, 'They said (to Moses): "Whatever be the Signs thou bringest, to work therewith thy sorcery on us, we shall never believe in thee.'),
  ('en.yusufali', 7, 133, 'So We sent (plagues) on them: Wholesale death, Locusts, Lice, Frogs, And Blood: Signs openly self-explained: but they were steeped in arrogance,- a people given to sin.'),
  ('en.yusufali', 7, 134, 'Every time the penalty fell on them, they said: "O Moses! on your behalf call on thy Lord in virtue of his promise to thee: If thou wilt remove the penalty from us, we shall truly believe in thee, and we shall send away the Children of Israel with thee."'),
  ('en.yusufali', 7, 135, 'But every time We removed the penalty from them according to a fixed term which they had to fulfil,- Behold! they broke their word!'),
  ('en.yusufali', 7, 136, 'So We exacted retribution from them: We drowned them in the sea, because they rejected Our Signs and failed to take warning from them.'),
  ('en.yusufali', 7, 137, 'And We made a people, considered weak (and of no account), inheritors of lands in both east and west, - lands whereon We sent down Our blessings. The fair promise of thy Lord was fulfilled for the Children of Israel, because they had patience and constancy, and We levelled to the ground the great works and fine buildings which Pharaoh and his people erected (with such pride).'),
  ('en.yusufali', 7, 138, 'We took the Children of Israel (with safety) across the sea. They came upon a people devoted entirely to some idols they had. They said: "O Moses! fashion for us a god like unto the gods they have." He said: "Surely ye are a people without knowledge.'),
  ('en.yusufali', 7, 139, '"As to these folk,- the cult they are in is (but) a fragment of a ruin, and vain is the (worship) which they practise."'),
  ('en.yusufali', 7, 140, 'He said: "Shall I seek for you a god other than the (true) Allah, when it is Allah Who hath endowed you with gifts above the nations?"'),
  ('en.yusufali', 7, 141, 'And remember We rescued you from Pharaoh\'s people, who afflicted you with the worst of penalties, who slew your male children and saved alive your females: in that was a momentous trial from your Lord.'),
  ('en.yusufali', 7, 142, 'We appointed for Moses thirty nights, and completed (the period) with ten (more): thus was completed the term (of communion) with his Lord, forty nights. And Moses had charged his brother Aaron (before he went up): "Act for me amongst my people: Do right, and follow not the way of those who do mischief."'),
  ('en.yusufali', 7, 143, 'When Moses came to the place appointed by Us, and his Lord addressed him, He said: "O my Lord! show (Thyself) to me, that I may look upon thee." Allah said: "By no means canst thou see Me (direct); But look upon the mount; if it abide in its place, then shalt thou see Me." When his Lord manifested His glory on the Mount, He made it as dust. And Moses fell down in a swoon. When he recovered his senses he said: "Glory be to Thee! to Thee I turn in repentance, and I am the first to believe."'),
  ('en.yusufali', 7, 144, '(Allah) said: "O Moses! I have chosen thee above (other) men, by the mission I (have given thee) and the words I (have spoken to thee): take then the (revelation) which I give thee, and be of those who give thanks."'),
  ('en.yusufali', 7, 145, 'And We ordained laws for him in the tablets in all matters, both commanding and explaining all things, (and said): "Take and hold these with firmness, and enjoin thy people to hold fast by the best in the precepts: soon shall I show you the homes of the wicked,- (How they lie desolate)."'),
  ('en.yusufali', 7, 146, 'Those who behave arrogantly on the earth in defiance of right - them will I turn away from My signs: Even if they see all the signs, they will not believe in them; and if they see the way of right conduct, they will not adopt it as the way; but if they see the way of error, that is the way they will adopt. For they have rejected our signs, and failed to take warning from them.'),
  ('en.yusufali', 7, 147, 'Those who reject Our signs and the meeting in the Hereafter,- vain are their deeds: Can they expect to be rewarded except as they have wrought?'),
  ('en.yusufali', 7, 148, 'The people of Moses made, in his absence, out of their ornaments, the image of calf, (for worship): it seemed to low: did they not see that it could neither speak to them, nor show them the way? They took it for worship and they did wrong.'),
  ('en.yusufali', 7, 149, 'When they repented, and saw that they had erred, they said: "If our Lord have not mercy upon us and forgive us, we shall indeed be of those who perish."'),
  ('en.yusufali', 7, 150, 'When Moses came back to his people, angry and grieved, he said: "Evil it is that ye have done in my place in my absence: did ye make haste to bring on the judgment of your Lord?" He put down the tablets, seized his brother by (the hair of) his head, and dragged him to him. Aaron said: "Son of my mother! the people did indeed reckon me as naught, and went near to slaying me! Make not the enemies rejoice over my misfortune, nor count thou me amongst the people of sin."'),
  ('en.yusufali', 7, 151, 'Moses prayed: "O my Lord! forgive me and my brother! admit us to Thy mercy! for Thou art the Most Merciful of those who show mercy!"'),
  ('en.yusufali', 7, 152, 'Those who took the calf (for worship) will indeed be overwhelmed with wrath from their Lord, and with shame in this life: thus do We recompense those who invent (falsehoods).'),
  ('en.yusufali', 7, 153, 'But those who do wrong but repent thereafter and (truly) believe,- verily thy Lord is thereafter Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 7, 154, 'When the anger of Moses was appeased, he took up the tablets: in the writing thereon was guidance and Mercy for such as fear their Lord.'),
  ('en.yusufali', 7, 155, 'And Moses chose seventy of his people for Our place of meeting: when they were seized with violent quaking, he prayed: "O my Lord! if it had been Thy will Thou couldst have destroyed, long before, both them and me: wouldst Thou destroy us for the deeds of the foolish ones among us? this is no more than Thy trial: by it Thou causest whom Thou wilt to stray, and Thou leadest whom Thou wilt into the right path. Thou art our Protector: so forgive us and give us Thy mercy; for Thou art the best of those who forgive.'),
  ('en.yusufali', 7, 156, '"And ordain for us that which is good, in this life and in the Hereafter: for we have turned unto Thee." He said: "With My punishment I visit whom I will; but My mercy extendeth to all things. That (mercy) I shall ordain for those who do right, and practise regular charity, and those who believe in Our signs;-'),
  ('en.yusufali', 7, 157, '"Those who follow the messenger, the unlettered Prophet, whom they find mentioned in their own (scriptures),- in the law and the Gospel;- for he commands them what is just and forbids them what is evil; he allows them as lawful what is good (and pure) and prohibits them from what is bad (and impure); He releases them from their heavy burdens and from the yokes that are upon them. So it is those who believe in him, honour him, help him, and follow the light which is sent down with him,- it is they who will prosper."'),
  ('en.yusufali', 7, 158, 'Say: "O men! I am sent unto you all, as the Messenger of Allah, to Whom belongeth the dominion of the heavens and the earth: there is no god but He: it is He That giveth both life and death. So believe in Allah and His Messenger, the Unlettered Prophet, who believeth in Allah and His words: follow him that (so) ye may be guided."'),
  ('en.yusufali', 7, 159, 'Of the people of Moses there is a section who guide and do justice in the light of truth.'),
  ('en.yusufali', 7, 160, 'We divided them into twelve tribes or nations. We directed Moses by inspiration, when his (thirsty) people asked him for water: "Strike the rock with thy staff": out of it there gushed forth twelve springs: Each group knew its own place for water. We gave them the shade of clouds, and sent down to them manna and quails, (saying): "Eat of the good things We have provided for you": (but they rebelled); to Us they did no harm, but they harmed their own souls.'),
  ('en.yusufali', 7, 161, 'And remember it was said to them: "Dwell in this town and eat therein as ye wish, but say the word of humility and enter the gate in a posture of humility: We shall forgive you your faults; We shall increase (the portion of) those who do good."'),
  ('en.yusufali', 7, 162, 'But the transgressors among them changed the word from that which had been given them so we sent on them a plague from heaven. For that they repeatedly transgressed.'),
  ('en.yusufali', 7, 163, 'Ask them concerning the town standing close by the sea. Behold! they transgressed in the matter of the Sabbath. For on the day of their Sabbath their fish did come to them, openly holding up their heads, but on the day they had no Sabbath, they came not: thus did We make a trial of them, for they were given to transgression.'),
  ('en.yusufali', 7, 164, 'When some of them said: "Why do ye preach to a people whom Allah will destroy or visit with a terrible punishment?"- said the preachers:" To discharge our duty to your Lord, and perchance they may fear Him."'),
  ('en.yusufali', 7, 165, 'When they disregarded the warnings that had been given them, We rescued those who forbade Evil; but We visited the wrong-doers with a grievous punishment because they were given to transgression.'),
  ('en.yusufali', 7, 166, 'When in their insolence they transgressed (all) prohibitions, We said to them: "Be ye apes, despised and rejected."'),
  ('en.yusufali', 7, 167, 'Behold! thy Lord did declare that He would send against them, to the Day of Judgment, those who would afflict them with grievous penalty. Thy Lord is quick in retribution, but He is also Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 7, 168, 'We broke them up into sections on this earth. There are among them some that are the righteous, and some that are the opposite. We have tried them with both prosperity and adversity: In order that they might turn (to us).'),
  ('en.yusufali', 7, 169, 'After them succeeded an (evil) generation: They inherited the Book, but they chose (for themselves) the vanities of this world, saying (for excuse): "(Everything) will be forgiven us." (Even so), if similar vanities came their way, they would (again) seize them. Was not the covenant of the Book taken from them, that they would not ascribe to Allah anything but the truth? and they study what is in the Book. But best for the righteous is the home in the Hereafter. Will ye not understand?'),
  ('en.yusufali', 7, 170, 'As to those who hold fast by the Book and establish regular prayer,- never shall We suffer the reward of the righteous to perish.'),
  ('en.yusufali', 7, 171, 'When We shook the Mount over them, as if it had been a canopy, and they thought it was going to fall on them (We said): "Hold firmly to what We have given you, and bring (ever) to remembrance what is therein; perchance ye may fear Allah."'),
  ('en.yusufali', 7, 172, 'When thy Lord drew forth from the Children of Adam - from their loins - their descendants, and made them testify concerning themselves, (saying): "Am I not your Lord (who cherishes and sustains you)?"- They said: "Yea! We do testify!" (This), lest ye should say on the Day of Judgment: "Of this we were never mindful":'),
  ('en.yusufali', 7, 173, 'Or lest ye should say: "Our fathers before us may have taken false gods, but we are (their) descendants after them: wilt Thou then destroy us because of the deeds of men who were futile?"'),
  ('en.yusufali', 7, 174, 'Thus do We explain the signs in detail; and perchance they may turn (unto Us).'),
  ('en.yusufali', 7, 175, 'Relate to them the story of the man to whom We sent Our signs, but he passed them by: so Satan followed him up, and he went astray.'),
  ('en.yusufali', 7, 176, 'If it had been Our will, We should have elevated him with Our signs; but he inclined to the earth, and followed his own vain desires. His similitude is that of a dog: if you attack him, he lolls out his tongue, or if you leave him alone, he (still) lolls out his tongue. That is the similitude of those who reject Our signs; So relate the story; perchance they may reflect.'),
  ('en.yusufali', 7, 177, 'Evil as an example are people who reject Our signs and wrong their own souls.'),
  ('en.yusufali', 7, 178, 'Whom Allah doth guide,- he is on the right path: whom He rejects from His guidance,- such are the persons who perish.'),
  ('en.yusufali', 7, 179, 'Many are the Jinns and men we have made for Hell: They have hearts wherewith they understand not, eyes wherewith they see not, and ears wherewith they hear not. They are like cattle,- nay more misguided: for they are heedless (of warning).'),
  ('en.yusufali', 7, 180, 'The most beautiful names belong to Allah: so call on him by them; but shun such men as use profanity in his names: for what they do, they will soon be requited.'),
  ('en.yusufali', 7, 181, 'Of those We have created are people who direct (others) with truth. And dispense justice therewith.'),
  ('en.yusufali', 7, 182, 'Those who reject Our signs, We shall gradually visit with punishment, in ways they perceive not;'),
  ('en.yusufali', 7, 183, 'Respite will I grant unto them: for My scheme is strong (and unfailing).'),
  ('en.yusufali', 7, 184, 'Do they not reflect? Their companion is not seized with madness: he is but a perspicuous warner.'),
  ('en.yusufali', 7, 185, 'Do they see nothing in the government of the heavens and the earth and all that Allah hath created? (Do they not see) that it may well be that their terms is nigh drawing to an end? In what message after this will they then believe?'),
  ('en.yusufali', 7, 186, 'To such as Allah rejects from His guidance, there can be no guide: He will leave them in their trespasses, wandering in distraction.'),
  ('en.yusufali', 7, 187, 'They ask thee about the (final) Hour - when will be its appointed time? Say: "The knowledge thereof is with my Lord (alone): None but He can reveal as to when it will occur. Heavy were its burden through the heavens and the earth. Only, all of a sudden will it come to you." They ask thee as if thou Wert eager in search thereof: Say: "The knowledge thereof is with Allah (alone), but most men know not."'),
  ('en.yusufali', 7, 188, 'Say: "I have no power over any good or harm to myself except as Allah willeth. If I had knowledge of the unseen, I should have multiplied all good, and no evil should have touched me: I am but a warner, and a bringer of glad tidings to those who have faith."'),
  ('en.yusufali', 7, 189, 'It is He Who created you from a single person, and made his mate of like nature, in order that he might dwell with her (in love). When they are united, she bears a light burden and carries it about (unnoticed). When she grows heavy, they both pray to Allah their Lord, (saying): "If Thou givest us a goodly child, we vow we shall (ever) be grateful."'),
  ('en.yusufali', 7, 190, 'But when He giveth them a goodly child, they ascribe to others a share in the gift they have received: but Allah is exalted high above the partners they ascribe to Him.'),
  ('en.yusufali', 7, 191, 'Do they indeed ascribe to Him as partners things that can create nothing, but are themselves created?'),
  ('en.yusufali', 7, 192, 'No aid can they give them, nor can they aid themselves!'),
  ('en.yusufali', 7, 193, 'If ye call them to guidance, they will not obey: For you it is the same whether ye call them or ye hold your peace!'),
  ('en.yusufali', 7, 194, 'Verily those whom ye call upon besides Allah are servants like unto you: Call upon them, and let them listen to your prayer, if ye are (indeed) truthful!'),
  ('en.yusufali', 7, 195, 'Have they feet to walk with? Or hands to lay hold with? Or eyes to see with? Or ears to hear with? Say: "Call your \'god-partners\', scheme (your worst) against me, and give me no respite!'),
  ('en.yusufali', 7, 196, '"For my Protector is Allah, Who revealed the Book (from time to time), and He will choose and befriend the righteous.'),
  ('en.yusufali', 7, 197, '"But those ye call upon besides Him, are unable to help you, and indeed to help themselves."'),
  ('en.yusufali', 7, 198, 'If thou callest them to guidance, they hear not. Thou wilt see them looking at thee, but they see not.'),
  ('en.yusufali', 7, 199, 'Hold to forgiveness; command what is right; But turn away from the ignorant.'),
  ('en.yusufali', 7, 200, 'If a suggestion from Satan assail thy (mind), seek refuge with Allah; for He heareth and knoweth (all things).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 7, 201, 'Those who fear Allah, when a thought of evil from Satan assaults them, bring Allah to remembrance, when lo! they see (aright)!'),
  ('en.yusufali', 7, 202, 'But their brethren (the evil ones) plunge them deeper into error, and never relax (their efforts).'),
  ('en.yusufali', 7, 203, 'If thou bring them not a revelation, they say: "Why hast thou not got it together?" Say: "I but follow what is revealed to me from my Lord: this is (nothing but) lights from your Lord, and Guidance, and mercy, for any who have faith."'),
  ('en.yusufali', 7, 204, 'When the Qur\'an is read, listen to it with attention, and hold your peace: that ye may receive Mercy.'),
  ('en.yusufali', 7, 205, 'And do thou (O reader!) Bring thy Lord to remembrance in thy (very) soul, with humility and in reverence, without loudness in words, in the mornings and evenings; and be not thou of those who are unheedful.'),
  ('en.yusufali', 7, 206, 'Those who are near to thy Lord, disdain not to do Him worship: They celebrate His praises, and prostrate before Him.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 7, 1, 'Alif-Laaam-Meeem-Saaad'),
  ('en.transliteration', 7, 2, 'Kitaabun unzila ilaika falaa yakum fee sadrika harajum minhu litunzira bihee wa zikraa lilmu\'mineen'),
  ('en.transliteration', 7, 3, 'Ittabi\'oo maaa unzila \'ilaikum mir Rabbikum wa laa tattabi\'oo min dooniheee awliyaaa\'; qaleelam maa tazakkaroon'),
  ('en.transliteration', 7, 4, 'Wa kam min qaryatin ahlaknaahaa fajaaa\'ahaa baasunaa bayaatan aw hum qaaa\'iloon'),
  ('en.transliteration', 7, 5, 'Famaa kaana da\'waahum iz jaaa\'ahum baasunaa illaaa an qaalooo innaa kunnaa zaalimeen'),
  ('en.transliteration', 7, 6, 'Falanas \'alannal lazeena ursila ilaihim wa lanas \'alannal mursaleen'),
  ('en.transliteration', 7, 7, 'Falanaqussanna \'alaihim bi\'ilminw wa maa kunnaa ghaaa\'ibeen'),
  ('en.transliteration', 7, 8, 'Walwaznu Yawma\'izinil haqq; faman saqulat mawaa zeenuhoo fa-ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 7, 9, 'Wa man khaffat mawaazeenuhoo fa ulaaa\'ikal lazeena khasirooo anfusahum bimaa kaanoo bi Aayaatinaa yazlimoon'),
  ('en.transliteration', 7, 10, 'Wa laqad makkannaakum fil ardi wa ja\'alnaa lakum feehaa ma\'aayish; qaleelam maa tashkuroon'),
  ('en.transliteration', 7, 11, 'Wa laqad khalaqnaakum summa sawwarnaakum summa qulnaa lilmalaaa\'ikatis judoo li Aadama fa-sajadooo illaaa Ibleesa lam yakum minas saajideen'),
  ('en.transliteration', 7, 12, 'Qaala maa mana\'aka allaa tasjuda iz amartuka qaala ana khairum minhu khalaqtanee min naarinw wa khalaqtahoo min teen'),
  ('en.transliteration', 7, 13, 'Qaala fahbit minhaa famaa yakoonu laka an tatakabbara feehaa fakhruj innaka minas saaghireen'),
  ('en.transliteration', 7, 14, 'Qaala anzirneee ilaa Yawmi yub\'asoon'),
  ('en.transliteration', 7, 15, 'Qaala innaka minal munzareen'),
  ('en.transliteration', 7, 16, 'Qaala fabimaaa aghway tanee la aq\'udanna lahum Siraatakal Mustaqeem'),
  ('en.transliteration', 7, 17, 'Summa la aatiyannahum mim baine aideehim wa min khalfihim wa \'an aimaanihim wa \'an shamaaa\'ilihim wa laa tajidu aksarahum shaakireen'),
  ('en.transliteration', 7, 18, 'Qaalakh ruj mnhaa maz\'oomam madhooraa; laman tabi\'aka minhum la amla\'anna Jahannama minkum ajma\'een'),
  ('en.transliteration', 7, 19, 'Wa yaaa Aadamus kun anta wa zawjukal Jannata fakulaa min haisu shi\'tumaa wa laa taqrabaa haazihish shajarata fatakoonaa minza zaalimeen'),
  ('en.transliteration', 7, 20, 'Fawaswasa lahumash Shaitaanu liyubdiya lahumaa maa wooriya \'anhumaa min saw aatihimaa wa qaala maa nahaakumaa Rabbukumaa \'an haazihish shajarati illaaa an takoonaa malakaini aw takoonaa minal khaalideen'),
  ('en.transliteration', 7, 21, 'Wa qaasamahumaaa innee lakumaa laminan naasiheen'),
  ('en.transliteration', 7, 22, 'Fadallaahumaa bighuroor; falammaa zaaqash shajarata badat lahumaa saw aatuhumaa wa tafiqaa yakhsifaani \'alaihimaa minw waraqil jannati wa naadaahumaa Rabbuhumaaa alam anhakumaa \'an tilkumash shajarati wa aqul lakumaaa innash Shaitaana lakumaa \'aduwwum mubeen'),
  ('en.transliteration', 7, 23, 'Qaalaa Rabbanaa zalamnaaa anfusanaa wa illam taghfir lanaa wa tarhamnaa lanakoonanna minal khaasireen'),
  ('en.transliteration', 7, 24, 'Qaalah bitoo ba\'dukum liba\'din aduwwunw wa lakum fil ardi mmustaqarrunw wa mataa\'un ilaaheen'),
  ('en.transliteration', 7, 25, 'Qaala feehaa tahyawna wa feehaa tamootoona wa minhaa tukhrajoon'),
  ('en.transliteration', 7, 26, 'Yaa Baneee Aadama qad anzalnaa \'alaikum libaasany yuwaaree saw aatikum wa reeshanw wa libaasut taqwaa zaalika khair; zaalika min Aayaatil laahi la\'allahum yaz zakkaroon'),
  ('en.transliteration', 7, 27, 'Yaa Banee Aadama laa yaftinannnakumush Shaitaanu kamaaa akhraja abawaikum minal Jannati yanzi\'u \'anhumaa libaasahumaa liyuriyahumaa saw aatihimaaa; innahoo yaraakum huwa wa qabeeluhoo min haisu laa tarawnahum; innaa ja\'alnash Shayaateena awliyaaa\'a lillazeena laa yu\'minoon'),
  ('en.transliteration', 7, 28, 'Wa izaa fa\'aloo faahishatan qaaloo wajadnaa \'alaihaaa aabaaa\'ana wallaahu amaranaa bihaa; qul innal laaha laa yaamuru bilfahshaaa\'i a-taqooloona \'alal laahi mmaa laa ta\'lamoon'),
  ('en.transliteration', 7, 29, 'Qul amara Rabbee bilqisti wa aqeemoo wujoohakum \'inda kulli masjidin wad\'oohu mukhliseena lahud deen; kamaa bada akum ta\'oodoon'),
  ('en.transliteration', 7, 30, 'Fareeqan hadaa wa fareeqan haqqa \'alaihimud dalaalah; innahumut takhazush Shayaateena awliyaaa\'a min doonil laahi wa yahsaboona annnahum muhtadoon'),
  ('en.transliteration', 7, 31, 'Yaa Banneee Adama khuzoo zeenatakum \'inda kulli masjidinw wa kuloo washraboo wa laa tusrifoo; innahoo laa yuhibbul musrifeen'),
  ('en.transliteration', 7, 32, 'Qul man harrama zeenatal laahil lateee akhraja li\'ibaadihee wattaiyibaati minar rizq; qul hiya lillazeena aamanoo fil hayaatid dunyaa khaalisatany Yawmal Qiyaamah; kazaalika nufassihul Aayaati liqawminy ya\'lamoon'),
  ('en.transliteration', 7, 33, 'Qul innamaa harrama Rabbiyal fawaahisha maa zahara minhaa wa maa bataa wal isma walbaghya bighairil haqqi wa an tushrikoo billaahi maa lam yunazzil bihee sultaananw wa an taqooloo \'alal laahi maa laa ta\'lamoon'),
  ('en.transliteration', 7, 34, 'Wa likulli ummatin ajalun fa izaa jaaa\'a ajaluhum laa yastaakhiroona saa\'atanw wa laa yastaqdimoon'),
  ('en.transliteration', 7, 35, 'yaa Banee Aadama immaa yaatiyannakum Rusulum minkum yaqussoona \'alaikum Aayaatee famanit taqaa wa aslaha falaa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 7, 36, 'Wallazeena kazzaboo bi Aayaatinaa wastakbaroo \'anhhaaa ulaaa\'ika Ashaabun naari hum feehaa khaalidoon'),
  ('en.transliteration', 7, 37, 'Faman azlamu mimmanif taraa \'alal laahi kaziban aw kazzaba bi Aayaatih; ulaaa\'ika yanaaluhum naseebuhum minal Kitaab; hataaa izaa jaaa\'at hum rusulunaa yatawaf fawnahum qaalooo aina maa kuntum tad\'oonaa min doonil laahi qaaloo dalloo \'annaa wa shahidoo \'alaaa anfusihim annahum kaanoo kaafieen'),
  ('en.transliteration', 7, 38, 'Qaalad khuloo feee umamin qad khalat min qablikum minal jinni wal insifin naari kullamaa dakhalat ummatul la\'anat ukhtahaa hattaaa izad daarakoo feehaa jamee\'an qaalat ukhraahum li oolaahum Rabbannaa haaa\'u laaa\'i adalloonaa fa aatihim \'azaaban di\'fam minan naari qaala likullin di funw wa laakil laa ta\'lamoon'),
  ('en.transliteration', 7, 39, 'Wa qaalat oolaahum li ukhraahum famaa kaana lakum \'alainaa min fadlin fazooqul azaaba bimaa kuntum taksiboon'),
  ('en.transliteration', 7, 40, 'Innal lazeena kazzaboo bi Aayaatinaa wastakbaroo \'anhaa laa tufattahu lahum ahwaabus samaaa\'i wa laa yadkhuloonal jannata hattaa yalijal jamalu fee sammil khiyaat; wa kazaalika najzil mujrimeen'),
  ('en.transliteration', 7, 41, 'Lahum min jahannama mihaadunw wa min fawqihim ghawaash; wa kazaalika najziz zaalimeen'),
  ('en.transliteration', 7, 42, 'Wallazeena aamanoo wa \'amilus saalihaati la nukallifu nafsan illaa wus\'ahaaa ulaaa\'ika Ashaabul jannati hum feehaa khaalidoon'),
  ('en.transliteration', 7, 43, 'Wa naza\'naa maa fee sudoorihim min ghillin tajree min tahtihimul anhaaru wa qaalul hamdu lillaahil lazee hadaanaa lihaaza wa maa kunna linahtadiya law laaa ann hadaanal laahu laqad jaaa\'at Rusulu Rabbinaa bilhaqq; wa noodoo an tilkumul jannnatu ooristumoohaa bimaa kuntum ta\'maloon'),
  ('en.transliteration', 7, 44, 'Wa naadaa Ashaabul jannati ashaaban Naari an qad wajadnaa maa wa\'adannaa Rabbunaa haqqan fahal wajattum maa wa\'ada Rabbukum haqqan qaaloo na\'am; fa azzana mu\'azzinum bainahum al la\'natul laahi \'alaz zaalimeen'),
  ('en.transliteration', 7, 45, 'Allazeena yasuddoona \'an sabeelil laahi wa yabghoo nahaa \'iwajanw wa hum bil Aakhirati kaafiroon'),
  ('en.transliteration', 7, 46, 'Wa bainahumaa hijaab; wa \'alal A\'raafi rijaaluny ya\'rifoona kullam biseemaahum; wa naadaw Ashaabal jannati an salaamun \'alaikum; lam yadkhuloohaa wa hum yatma\'oon'),
  ('en.transliteration', 7, 47, 'Wa izaa surifat absaaruhum tilqaaa\'a Ashaabin Naari qaalo Rabbanaa laa taj\'alnaa ma\'al qawmiz zaalimneen'),
  ('en.transliteration', 7, 48, 'Wa naadaaa Ashaabul A\'raffi rijaalany ya\'rifoonahum biseemaahum qaaloo maaa aghnaa \'ankum jam\'ukum wa maa kuntum tastakbiroon'),
  ('en.transliteration', 7, 49, 'A haaa\'ulaaa\'il lazeena aqsamtum laa yanaaluhumul laahu birahma; udkhulul Jannata laa khawfun \'alaikum wa laaa antum tahzanoon'),
  ('en.transliteration', 7, 50, 'Wa naadaaa Ashaabun Naari Ashaabal jannati an afeedoo \'alainaa minal maaa\'i aw mimma razaqakumul laah; qaaloo innal laaha harrama humaa \'alal kaafireen'),
  ('en.transliteration', 7, 51, 'Allazeenat takhazoo deenahu lahwanw wa la\'i-banw wa gharrat humul hayaatud dunyaa; fal Yawma nnannsaahum kamaa nasoo liqaaa\'a Yawmihim haazaa wa maa kaanoo bi aayaatinaa yajhadoon'),
  ('en.transliteration', 7, 52, 'Wa laqad ji\'naahum bi Kitaabin fassalnaahu \'alaa \'ilmin hudanw wa rahmatal liqawminy-yu\'miinoon'),
  ('en.transliteration', 7, 53, 'hal yanzuroona illaa taa weelah; yawma yaatee taaweeluhoo yaqoolul lazeena nasoohu min qablu qad jaaa\'at Rusulu Rabbinaa bilhaqq; fahal lanaa min shufa\'aaa\'a fa yashfa\'oo lanaaa aw nuraddu fana\'mala ghairal lazee kunnaa na\'mal; qad khasirooo anfusahum wa dalla \'anhum maa kaanoo yaftaroon'),
  ('en.transliteration', 7, 54, 'Inna Rabbakkumul laahul lazee khalaqas sammaawaati wal arda fee sittati qiyaamin summmas tawaa \'alal \'arshi yughshil lailan nahaara yatlu buhoo haseesanw washshamsa walqamara wannujooma musakhkharaatim bi amrih; alaa lahul khalqu wal-amr; tabaarakal laahu Rabbul \'aalameen'),
  ('en.transliteration', 7, 55, 'Ud\'oo Rabbakum tadarru\'anw wa khufyah; innahoo laa yuhibbul mu\'tadeen'),
  ('en.transliteration', 7, 56, 'Wa laa tufsidoo fil ardi ba\'da islaahihaa wad\'oohu khawfanw wa tama\'aa; inna rahmatal laahi qareebum minal muhsineen'),
  ('en.transliteration', 7, 57, 'Wa Huwal lazee yursilur riyaaha bushram baina yadai rahmatihee hattaaa izaaa aqallat sahaaban siqaalan suqnaahu libaladim maiyitin fa annzalnaa bihil maaa\'a fa akhrajnaa bihee minn kullis samaraat; kazaalika nukhrijul mawtaa la\'allakum tazakkaroon'),
  ('en.transliteration', 7, 58, 'Walbaladut taiyibu yakhruju nabaatuhoo bi-izni Rabbihee wallazee khabusa laa yakhruju illaa nakidaa; kazaalika nusarriful Aayaati liqawminy yashkuroon'),
  ('en.transliteration', 7, 59, 'Laqad arsalnaa noohan ilaa qawmihee faqaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo inneee akhaafu \'alaikum \'azaaba Yawmin \'Azeem'),
  ('en.transliteration', 7, 60, 'Qaalal mala-u min qaw miheee innaa lanaraaka fee dalaalim mubeen'),
  ('en.transliteration', 7, 61, 'Qaala yaa qawmi laisa bee dalaalatunw wa laakinnee Rasoolum mir Rabbil \'aalameen'),
  ('en.transliteration', 7, 62, 'Uballighukum Risaalaati Rabbee wa ansahu lakum wa a\'lamu minal laahi maa laa ta\'lamoon'),
  ('en.transliteration', 7, 63, 'awa\'ajibtum an jaaa\'akum zikrum mir Rabbikum \'alaa rajulim minkum liyunzirakum wa litattaqoo wa la\'allakum turhamoon'),
  ('en.transliteration', 7, 64, 'Fakazzaboohu fa anjai naahu wallazeena ma\'ahoo fil fulki wa aghraqnal lazeena kazzaboo bi Aayaatinaa; innahum kaanoo qawman \'ameen'),
  ('en.transliteration', 7, 65, 'Wa ilaa \'aadin akhaahum Hoodaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuh; afalaa tattaqoon'),
  ('en.transliteration', 7, 66, 'Qaalal mala ul lazeena kafaroo min qawmiheee innaa lanaraaka fee safaahatinw wa innaa lannazunnuka minal kaazibeen'),
  ('en.transliteration', 7, 67, 'Qaala yaa qawmi laisa bee safaahatunw wa laakinnee Rasoolum mir Rabbil \'aalameen'),
  ('en.transliteration', 7, 68, 'Uballighukum Risaalaati Rabbee wa ana lakum naasihun ameen'),
  ('en.transliteration', 7, 69, 'awa \'ajibtum an jaaa\'akum zikrum mir Rabbikum \'alaa rajulim minkum liyunzirakum; wazkurooo iz ja\'alakum khulafaaa\'a mim ba\'di qawmi noohinw wa zaadakum filkhalqi bastatan fazkurooo aalaaa\'al laahi la\'allakum tuflihoon'),
  ('en.transliteration', 7, 70, 'Qaalooo aji\'tanaa lina\'budal laaha wahdahoo wa nazara maa kaana ya\'budu aabaaa\'u naa faatinaa bimaa ta\'idunaaa in kunta minas saadiqeen'),
  ('en.transliteration', 7, 71, 'Qaala qad waqa\'a alaikum mir Rabbikum rijsunw wa ghadab, atujaadiloonanee feee asmaaa\'in sammaitumoohaaa antum wa aabaaa\'ukum maa nazzalal laahu bihaa min sultaan; fantazirooo innee ma\'akum minal muntazireen'),
  ('en.transliteration', 7, 72, 'Fa anjainaahu wallazeena ma\'ahoo birahmatim minnaa wa qata\'naa daabiral lazeena kazzaboo bi Aayaatinaa wa maa kaanoo mu\'mineen'),
  ('en.transliteration', 7, 73, 'Wa ilaa Samooda akhaahum Saalihaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa\'atkum baiyinatum mir Rabbikum haazihee naaqatul laahi lakum Aayatan fazaroohaa taakul feee ardil laahi wa laa tamassoohaa bisooo\'in fa yaakhuzakum \'azaabun aleem'),
  ('en.transliteration', 7, 74, 'Wazkkurooo iz ja\'alakum khulafaaa\'a mim ba\'di \'Aadinw wa bawwa akum fil ardi tattakhizoona min suhoolihaa qusooranw wa tanhitoonal jibaala buyootan fazkurooo aalaaa\'al laahi wa laa ta\'saw fil ardi mufsideen'),
  ('en.transliteration', 7, 75, 'Qaalal mala ul lazeenas takbaroo min qawmihee lillazeenas tud\'ifoo liman aamana minhum ata\'almoona anna Saaliham mursalum mir Rabbih; qaalooo innaa bimaaa ursila bihee mu\'minoon'),
  ('en.transliteration', 7, 76, 'Qaalal lazeenas takbarooo innaa billazeee aamanntum bihee kaafiroon'),
  ('en.transliteration', 7, 77, 'Fa\'aqarun naaqata wa\'ataw \'an amri Rabbihim wa qaaloo yaa Saalihu\' tinaa bimaa ta\'idunaaa in kunta minal mursaleen'),
  ('en.transliteration', 7, 78, 'Fa akhazat humur rajftu fa asbahoo fee daarihim jaasimmeen'),
  ('en.transliteration', 7, 79, 'Fa tawalla \'anhum wa qaala yaa qawmi laqad ablaghtukum Risaalata Rabbee wa nasahtu lakum wa laakil laa tuhibboonan naasiheen'),
  ('en.transliteration', 7, 80, 'Wa Lootan iz qaala liqawmiheee ataatoonal faahishata maa sabaqakum bihaa min ahadim minal \'aalameen'),
  ('en.transliteration', 7, 81, 'Innakum lataatoonar rijaala shahwatam min doonin nisaaa\'; bal antumqawmum musrifoon'),
  ('en.transliteration', 7, 82, 'Wa maa kaana jawaaba qawmihee illaa an qaalooo akhrijoohum min qaryatikum innahum unaasuny yatatah haroon'),
  ('en.transliteration', 7, 83, 'Fa anjainaahu wa ahlahooo illam ra atahoo kaanat minal ghaabireen'),
  ('en.transliteration', 7, 84, 'Wa \'amtarnaa \'alaihim mataran fanzur kaifa kaana aaqibatul mujjrimeen'),
  ('en.transliteration', 7, 85, 'Wa ilaa Madyana akhaahum Shu\'aybaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo qad jaaa\'atkum baiyinatum mir Rabbikum fa awful kaila walmeezaana wa laa tabkhasun naasa ashyaa\'ahum wa laa tufsidoo fil ardi ba\'da islaahihaa; zaalikum khairul lakum in kuntum mu\'mineen'),
  ('en.transliteration', 7, 86, 'Wa laa taq\'udoo bikulli siraatin too\'idoona wa tasuddoona \'an sabeelil laahi man aamana bihee wa abghoonahaa \'iwajaa; waz kurooo iz kuntum qaleelan fakassarakum wanzuroo kaifa kaana \'aaqibatul mufsideen'),
  ('en.transliteration', 7, 87, 'Wa In kaana taaa\'ifatum minkum aamanoo billazeee ursiltu bihee wa taaa\'ifatul lam yu\'minoo fasbiroo hattaa yahkumual laahu bainanaa; wa Huwa khairul haakimeen'),
  ('en.transliteration', 7, 88, 'Qaalal mala ul lazeenas takbaroo min qawmihee lanukhrijannaka yaa Shu\'aibu wallazeena aamanoo ma\'aka min qaryatinaaa aw lata\'oo dunna fee millatinaa; qaala awa law kunnaa kaariheen'),
  ('en.transliteration', 7, 89, 'Qadif tarainaa \'alal laahi kaziban in \'udnaa fee millatikum ba\'da iz najjaanal laahu minhaa; wa maa yakoonu lanaaa an na\'ooda feehaaa illaaa ai yashaaa\'al laahu Rabbunaa; wasi\'a Rabbunaa kulla shai\'in \'ilmaa; \'alal laahi tawakkalnaa; Rabbanaf tah bainanaa wa baina qawminaa bilhaqqi wa Anta khairul faatiheen'),
  ('en.transliteration', 7, 90, 'Wa qaalal mala ul lazeena kafaroo min qawmihee la\'init taba\'tum Shu\'aiban innakum izal lakhaasiroon'),
  ('en.transliteration', 7, 91, 'Fa akhazat humur rajfatu fa asbahoo fee daarihim jaasimeen'),
  ('en.transliteration', 7, 92, 'Allazeena kazzaboo Shu\'aiban ka al alm yaghnaw feehaa; allazeena kazzaboo Shu\'aiban kaanoo humul khaasireen'),
  ('en.transliteration', 7, 93, 'Fatawalla \'anhum wa qaala yaa qawmi laqad ablaghtukum Risaalaati Rabbee wa nasahtu lakum fakaifa aasaa\'alaa qawmin kaafireen'),
  ('en.transliteration', 7, 94, 'Wa maaa arsalnaa fee qaryatim min Nabiyyin illaaa akhaznaaa ahlahaa bil baasaaa\'i waddarraaa\'i la\'allahum yaddarra\'oon'),
  ('en.transliteration', 7, 95, 'Summa baddalnaa makaa nas saiyi\'atil hasanata hattaa \'afaw wa qaaloo qad massa aabaa\'anad darraaa\'u wassarraaa\'u fa akhaznaahum baghtatanw wa hum laa yash\'uroon'),
  ('en.transliteration', 7, 96, 'Wa law anna ahlal quraaa aamanoo wattaqaw lafatahnaa \'alaihim barakaatim minas samaaa\'i wal ardi wa laakin kazzaboo fa akhaznaahum bimaa kaanoo yaksiboon'),
  ('en.transliteration', 7, 97, 'Afa amina ahlul quraaa ai yaatiyahum baasunaa bayaatanw wa hum naaa\'imoon'),
  ('en.transliteration', 7, 98, 'Awa amina ahlul quraaa ai yaatiyahum baasunaa duhanw wa hum yal\'aboon'),
  ('en.transliteration', 7, 99, 'Afa aminoo makral laah; falaa yaamanu makral laahi illal qawmul khaasiroon'),
  ('en.transliteration', 7, 100, 'Awa lam yahdi lillazeena yarisoonal arda mim ba\'di ahlihaaa al law nashaaa\'u asabnaahum bizunoobihim; wa natba\'u \'alaa quloobihim fahum laa yasma\'oon'),
  ('en.transliteration', 7, 101, 'Tilkal quraa naqussu \'alaika min ambaaa\'ihaa; wa laqad jaaa\'at hum Rusuluhum bilbaiyinaati famaa kaanoo liyu\'minoo bimaa kazzaboo min qabl; kazaalika yatba\'ul laahu \'alaa quloobil kaafireen'),
  ('en.transliteration', 7, 102, 'Wa maa wajadnaa li aksarihim min \'ahd; wa inw wajadnaaa aksarahum lafaasiqeen'),
  ('en.transliteration', 7, 103, 'Summa ba\'asnaa mim ba\'dihim Moosaa bi Aayaatinaaa ilaa Fir\'awana wa mala\'ihee fazalamoo bihaa fanzur kaifa kaana \'aaqibatul mufsideen'),
  ('en.transliteration', 7, 104, 'Wa qaala Moosaa yaa Fir\'awnu inee Rasoolum mir Rabbil \'aalameen'),
  ('en.transliteration', 7, 105, 'Haqeequn \'alaaa al laaa aqoola \'alal laahi illal haqq; qad ji\'tukum bibaiyinatim mir Rabbikum fa arsil ma\'iya Baneee Israaa\'eel'),
  ('en.transliteration', 7, 106, 'Qaala in kunta ji\'ta bi Aayatin faati bihaaa in kunta minas saadiqeen'),
  ('en.transliteration', 7, 107, 'Qa alqaa \'asaahu fa izaa hiya su\'baanum mubeen'),
  ('en.transliteration', 7, 108, 'Wa naza\'a yadahoo fa izaa hiya baidaaa\'u linnaazireen'),
  ('en.transliteration', 7, 109, 'Qaalal mala-u min qawmi Fir\'awna inna haazaa lasaa hirun \'aleem'),
  ('en.transliteration', 7, 110, 'Yureedu ai yukhrijakum min ardikum famaazaa taamuroon'),
  ('en.transliteration', 7, 111, 'Qaalooo arjih wa akhaahu wa arsil filmadaaa\'ini haashireen'),
  ('en.transliteration', 7, 112, 'Yaatooka bikulli saahirin \'aleem'),
  ('en.transliteration', 7, 113, 'Wa jaaa\'as saharatu Fir\'awna qaaloo inna lanaa la ajjran in kunnaa nahnul ghaalibeen'),
  ('en.transliteration', 7, 114, 'Qaala na\'am wa innakum laminal muqarrabeen'),
  ('en.transliteration', 7, 115, 'Qaaloo yaa Moosaaa immaaa an tulqiya wa immaaa an nakoona nahnul mulqeen'),
  ('en.transliteration', 7, 116, 'Qaala alqoo falam maaa alqaw saharooo a\'yunannaasi wastarhaboohum wa jaaa\'oo bisihrin \'azeem'),
  ('en.transliteration', 7, 117, 'Wa awhainaaa ilaa Moosaaa an alqi \'asaaka fa izaa hiya talqafu maa yaafikoon'),
  ('en.transliteration', 7, 118, 'Fawaqa\'al haqqu wa batala maa kaanoo ya\'maloon'),
  ('en.transliteration', 7, 119, 'Faghuliboo hunaalika wanqalaboo saaghireen'),
  ('en.transliteration', 7, 120, 'Wa ulqiyas saharatu saajideen'),
  ('en.transliteration', 7, 121, 'Qaaloo aamannaa bi Rabbil \'aalameen'),
  ('en.transliteration', 7, 122, 'Rabbi Moosaa wa Haaroon'),
  ('en.transliteration', 7, 123, 'Qaala Fir\'awnu aamantum bihee qabla an aazana lakum; inna haaza lamakrum makartumoohu filmadeenati litukhrijoo minhaaa ahlahaa fasawfa ta\'almoon'),
  ('en.transliteration', 7, 124, 'La uqatti\'anna aidiyakum wa arjulakum min khilaafin summa la usallibannakum ajma\'een'),
  ('en.transliteration', 7, 125, 'Qaaloo innaaa ilaa Rabbinaa munqaliboon'),
  ('en.transliteration', 7, 126, 'Wa maa tanqimu minnaaa illaaa an aamannaa bi Aayaati Rabbinaa lammaa jaaa\'atnaa; Rabbanaaa afrigh \'alainaa sabranw wa tawaffanaa muslimeen'),
  ('en.transliteration', 7, 127, 'Wa qaalal mala-u min qawmi Fir\'awna atazaru Moosaa wa qawmahoo liyufsidoo fil ardi wa yazaraka wa aalihatak; qaala sanuqattilu abnaaa \'ahum wa nastahyee nisaaa\'ahum wa innaa fawqahum qaahiroon'),
  ('en.transliteration', 7, 128, 'Qaala Moosaa liqawmihis ta\'eenoo billaahi wasbiroo innal arda lillaahi yoorisuhaa mai yashaaa\'u min \'ibaadihee wal \'aaqibatu lilmuttaqeen'),
  ('en.transliteration', 7, 129, 'Qaaloo oozeenaa min qabli an taatiyanaa wa mim ba\'di maa ji\'tanaa; qaala \'asaa Rabbukum ai yuhlika \'aduwwakum wa yastakhli fakum fil ardi fayanzura kaifa ta\'maloon'),
  ('en.transliteration', 7, 130, 'Wa laqad akhaznaaa Aala Fir\'awna bis sineena wa naqsim minas samaraati la\'allahum yazzakkaroon'),
  ('en.transliteration', 7, 131, 'Fa izaa jaaa\'at humul hasanatu qaaloo lanaa haazihee wa in tusibhum saiyi\'atuny yattaiyaroo bi Moosaa wa mam ma\'ah; alaaa innamaa taaa\'iruhum \'indal laahi wa laakinna aksarahum laa ya\'lamoon'),
  ('en.transliteration', 7, 132, 'Wa qaaloo mahmaa taatinaa bihee min Aayatil litasharanaa bihaa famaa nahnu laka bimu\'mineen'),
  ('en.transliteration', 7, 133, 'Fa arsalnaa \'alaihimut toofaana waljaraada walqum mala waddafaadi\'a waddama Aayaatim mufassalaatin fastakbaroo wa kaanoo qawmam mujrimeen'),
  ('en.transliteration', 7, 134, 'Wa lammaa waqa\'a \'alaihimur rijzu qaaloo ya Moosad-u lanaa rabbaka bimaa \'ahida \'indaka la\'in kashafta \'annar rijza lanu \'minanna laka wa lanursilanna ma\'aka Banee Israaa\'eel'),
  ('en.transliteration', 7, 135, 'Falammaa kashafnaa \'anhumur rijza ilaaa ajalin hum baalighoohu izaa hum yankusoon'),
  ('en.transliteration', 7, 136, 'Fantaqamnaa minhum fa aghraqnaahum kazzaboo bi Aayaatinaa wa kaanoo \'anhaa ghaafileen'),
  ('en.transliteration', 7, 137, 'Wa awrasnal qawmal lazeena kaanoo yustad\'afoona mashaariqal ardi wa maghaari bahal latee baaraknaa feehaa wa tammat kalimatu Rabbikal husnaa \'alaa Baneee Israaa\'eela bimaa sabaroo wa dammarnaa maa kaana yasna\'u Fir\'awnu wa qawmuhoo wa maa kaanoo ya\'rishoon'),
  ('en.transliteration', 7, 138, 'Wa jaawaznaa bi Banneee Israaa\'eelal bahra fa ataw \'alaa qawminy ya\'kufoona \'alaaa asnaamil lahum; qaaloo yaa Moosaj\'al lanaa ilaahan kamaa lahum aalihah; qaala innakum qawmun tajhaloon'),
  ('en.transliteration', 7, 139, 'Innaa haaa\'ulaaa\'i mutabbarum maa hum feehi wa baatilum maa kaanoo ya\'maloon'),
  ('en.transliteration', 7, 140, 'Qaala a-ghairal laahi abgheekum ilaahanw wa Huwa faddalakum \'alal \'aalameen'),
  ('en.transliteration', 7, 141, 'Wa iz anjainaakum min Aali Fir\'awna yasoomoo nakum sooo\'al \'azaab, yuqattiloona abnaaa\'akum wa yastahyoona nisaaa\'akum; wa fee zaalikum balaaa\'um mir Rabbikum \'azeem'),
  ('en.transliteration', 7, 142, 'Wa waa\'adnaa Moosaa salaaseena lailatanw wa at mamnaahaa bi\'ashrim fatamma meeqaatu Rabbihee arba\'eena lailah; wa qaala Moosaa liakheehi Haaroonakh lufnee fee qawmee wa aslih wa laa tattabi\' sabeelal mufsideen'),
  ('en.transliteration', 7, 143, 'Wa lammaa jaaa\'a Moosa limeeqaatinaa wa kallamahoo Rabbuhoo qaala Rabbi arineee anzur ilaik; qaala lan taraanee wa laakininzur ilal jabali fa inistaqarra makaanahoo faswfa taraanee; falammaa tajallaa Rabbuhoo liljabali ja\'alahoo dakkanw wa kharra Moosaa sa\'iqaa; falammaaa afaaqa qaala Subhaanaka tubtu ilaika wa ana awwalul mu\'mineen'),
  ('en.transliteration', 7, 144, 'Qaala yaa Moosaaa innis tafaituka \'alan naasi bi Risaalaatee wa bi kalaamee fakhuz maaa aataituka wa kum minash shaakireen'),
  ('en.transliteration', 7, 145, 'Wa katabnaa lahoo fil alwaahi minkulli shai\'immaw \'izaanw wa tafseelal likulli shai\'in fakhuzhaa biquwwatinw waamur qawmaka yaakhuzoo bi ahsanihaa; wa ooreekum daaral faasiqeen'),
  ('en.transliteration', 7, 146, 'Sa asrifu \'an Aayaatiyal lazeena yatakabbaroona fil ardi bighairil haqq; wa iny-yaraw kulla Aayatil laa yu\'minoo bihaa wa iny-yaraw sabeelar rushdi laa yattakhizoohu sabeelanw wa iny-yaraw sabeelal ghaiyi yatta khizoohu sabeelaa; zaalika bi annahum kazzaboo bi Aayaatinaa wa kaanoo \'anhaa ghaafileen'),
  ('en.transliteration', 7, 147, 'Wallazeena kazzaboo bi Aayaatinaa wa liqaaa\'il Aakhirati habitat \'amaaluhum; hal yujzawna illaa maa kaanoo ya\'maloon'),
  ('en.transliteration', 7, 148, 'Wattakhaza qawmu Moosaa mim ba\'dihee min huliyyihim \'ijlan jasadal lahoo khuwaar; alam yaraw annahoo laa yukallimuhum wa laa yahdeehim sabeelaa; ittakha zoohu wa kaanoo zaalimeen'),
  ('en.transliteration', 7, 149, 'Wa lammaa suqita feee aideehim wa ra aw annahum qad dalloo qaaloo la\'il lam yarhamnaa Rabbunaa wa yaghfir lanaa lanakoonanna minal khaasireen'),
  ('en.transliteration', 7, 150, 'Wa lammaa raja\'a Moosaaa ilaa qawmihee ghadbaana asifan qaala bi\'samaa khalaftumoonee mim ba\'dee a-\'ajiltum amra Rabbikum wa alqal alwaaha wa akhaza biraasi akheehi yajurruhoo ilaih; qaalab na umma innal qawmas tad\'afoonee wa kadoo yaqtu loonanee; falaa tushmit biyal a\'daaa\'a wa laa taj\'alnee ma\'al qawmiz zaalimeen'),
  ('en.transliteration', 7, 151, 'Qaala Rabbigh fir lee wa li akhee wa adkhilnaa fee rahmatika wa Anta arhamur raahimeen'),
  ('en.transliteration', 7, 152, 'Innal lazeenat takhazul \'ijla-sa yanaaluhum ghadabum mir Rabbihim wa zillatun fil hayaatid dunyaa; wa kazaalika najzil muftareen'),
  ('en.transliteration', 7, 153, 'Wallazeena \'amilus saiyiaati summa taaboo mim ba\'dihaa wa aamanooo inna Rabbaka mim ba\'dihaa la Ghafoorur Raheem'),
  ('en.transliteration', 7, 154, 'Wa lammaa sakata \'am Moosal ghadabu akhazal al waaha wa fee nnuskhatihaa hudanw wa rahmatul lillazeena hum li Rabbihim yarhaboon'),
  ('en.transliteration', 7, 155, 'Wakhtaara Moosaa qawmahoo sab\'eena rajjulal limeeqaatinaa falammaa akhazat humur rajfatu qaala Rabbi law shi\'ta ahlaktahum min qablu wa iyyaaya atuhlikunna bimaa fa\'alas sufahaaa\'u minnaa in hiya illaa fitnatuka tudillu bihaa man tashaaa\'u wa tahdee man tashaaa\'u Anta waliyyunaa faghfir lanaa warhammnnaa wa Anta khairul ghaafireen'),
  ('en.transliteration', 7, 156, 'Waktub lanaa fee haazi hid dunyaa hasanatanw wa fil Aakhirati innnaa hudnaaa ilaik; qaala \'azaabee useebu bihee man ashaaa\'u wa rahmatee wasi\'at kulla shai\'; fasa aktubuhaa lillazeena yattaqoona wa yu\'toonaz Zakaata wallazeena hum bi Aayaatinaa yu\'minoon'),
  ('en.transliteration', 7, 157, 'Allazeena yattabi\'oonar Rasoolan Nabiyyal ummiyyal lazee yajidoonahoo maktooban \'indahum fit Tawraati wal Injeeli yaa muruhum bilma\'roofi wa yanhaahum \'anil munkari wa yuhillu lahumul taiyibaati wa yuharrimu \'alaihimul khabaaa\'isa wa yada\'u \'anhum israhum wal aghlaalal latee kaanat \'alaihim; fallazeena aamanoo bihee wa \'azzaroohu wa nnasaroohu wattaba\'un nooral lazeee unzila ma\'ahooo ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 7, 158, 'Qul yaaa aiyuhan naasu innee Rasoohul laahi ilaikum jamee\'anil lazee lahoo mulkus samaawaati wal ardi laaa ilaaha illaa Huwa yuhyee wa yumeetu fa aaminoo billaahi wa Rasoolihin Nabiyyil ummiy yil lazee yu\'minu billaahi wa Kalimaatihee wattabi\'oohu la\'allakum tahtadoon'),
  ('en.transliteration', 7, 159, 'Wa min qawmi Moosaaa ummatuny yahdoona bilhaqqi wa bihee ya\'diloon'),
  ('en.transliteration', 7, 160, 'Wa qatta\' naahumus natai \'ashrata asbaatan umamaa; wa awhainaa ilaa Moosaaa izis tasqaahu qawmuhooo anid rib bi\'asaakal hajara fambajasat minhus nata \'ashrata \'ainan qad \'alima kullu unaasim mashrabahm; wa zallalnaa \'alaihimul ghammaamma wa anzalnaa \'alaihimul MManna was Salwaa kuloo min taiyibaati maa razaqnaakum; wa maa zalamoonaa wa laakin kaanooo anfusahum yazlimoon'),
  ('en.transliteration', 7, 161, 'Wa iz qeela lahumuskunoo haazihil qaryata wa kuloo minhaa haisu shi\'tum wa qooloo hittatunw wadkhulul baaba sujjadan naghfir lakum khateee\'aatikum; sanazeedul muhsineen'),
  ('en.transliteration', 7, 162, 'Fabaddalal lazeena zalamoo minhum qawlan ghairal lazee qeela lahum fa arsalnaa \'alaihim rijzam minas samaaa\'i bimaa kaanoo yazlimoon'),
  ('en.transliteration', 7, 163, 'Was\'alhum \'anil qaryatil latee kaanat haadiratal bahri iz ya\'doona fis Sabt iz taateehim heetaanuhum yawma Sabtihim shurra\'anw wa yawma laa yasbitoona laa taateehim; kazaalika nabloohum bimaa kaanoo yafsuqoon'),
  ('en.transliteration', 7, 164, 'Wa iz qaalat ummatum minhum lima ta\'izoona qaw manil laahu muhlikuhum aw mu\'azzibuhum \'azaaban shadeedan qaaloo ma\'ziratan ilaa Rabbikum wa la\'allahum tattaqoon'),
  ('en.transliteration', 7, 165, 'Falammaa nasoo maa zukkiroo bihee anjainal lazeena yanhawna \'anis sooo\'i wa akhaznal lazeena zalamoo bi\'azaabim ba\'eeim bimaa kaanooyafsuqoon'),
  ('en.transliteration', 7, 166, 'Falammaa \'ataw \'ammmaa nuhoo \'anhu qulna lahum kkoonoo qiradatan khaasi\'een'),
  ('en.transliteration', 7, 167, 'Wa iz ta azzana Rabbuka la yab\'asannna \'alaihim ilaa Yawmil Qiyaamati mai yasoomuhum sooo\'al \'azaab; inna Rabbaka lasaree\'ul \'iqaab; wa innahoo la Ghafoorur Raheem'),
  ('en.transliteration', 7, 168, 'Wa qatta\'naahum fil ardi umamam minhumus aalihoona wa min hum doona zaalika wa balawnaahum bilhasanaati wassaiyi aati la\'allahum yarji\'oon'),
  ('en.transliteration', 7, 169, 'Fakhalafa mim ba\'dihim khalfunw warisul Kitaaba yaa khuzoona \'arada haazal adnaa wa yaqooloona sayughfaru lanaa wa iny yaatihim \'aradum misluhoo yaakhuzooh; alam yu\'khaz \'alaihim \'aradum misluhoo yaakhuzooh; alam yu\'khaz \'alaihim meesaaqul Kitaabi al laa yaqooloo \'alal laahi illal haqqa wa darasoo maa feeh; wad Daarul Aakhirtu khairul lillazeena yattaqoon; afalaa ta\'qiloon'),
  ('en.transliteration', 7, 170, 'Wallazeena yumas sikoona bil Kitaabi wa aqaamus Salaata innaa laa nudee\'uajral musliheen'),
  ('en.transliteration', 7, 171, 'Wa iz nataqnal jabala fawqahum ka annahoo zullatunw wa zannooo annahoo waaqi\'um bihim khuzoo maaa aatainaakum biquwwatinw wazkuroo maa feehi la\'allakum tattaqoon'),
  ('en.transliteration', 7, 172, 'Wa iz akhaza Rabbuka mim Baneee Aadama min zuhoorihim zurriyyatahum wa ash hadahum \'alaa anfusihim alastu bi Rabbikum qaaloo balaa shahidnaaa; an taqooloo Yawmal Qiyaamati innaa kunnaa \'an haazaa ghaafileen'),
  ('en.transliteration', 7, 173, 'Aw taqoolooo innamaaa ashraka aabaaa \'unaa min qablu wa kunnaa zurriyyatam mim ba\'dihim afatuhlikunna bimaa fa\'alal mubtiloon'),
  ('en.transliteration', 7, 174, 'Wa kazaalika nufassihul Aayaati wa la\'allahum yarji\'oon'),
  ('en.transliteration', 7, 175, 'Watlu \'alaihim naba allazeee aatainaahu Aayaatinaa fansalakha minhaa fa atba\'a hush Shaytaano fakaana minal ghaaween'),
  ('en.transliteration', 7, 176, 'Wa law shi\'naa larafa\'naahu bihaa wa laakin nahooo akhlada ilal ardi watta ba\'a hawaah; famasaluhoo kamasalil kalb; in tahmil \'alaihi yalhas aw tatruk hu yalhas; zaalika masalul qawmil lazeena kazzaboo bi Aayaatinaa; faqsusil qasasa la\'allahum yatafakkaroon'),
  ('en.transliteration', 7, 177, 'Saaa\'a masalanil qawmul lazeena kazzaboo bi Aayaatinaa wa anfusahum kaanoo yazlimoon'),
  ('en.transliteration', 7, 178, 'mai yahdil laahu fa huwal muhtadee wa mai yudlil fa ulaaa\'ika humul khaasiroon'),
  ('en.transliteration', 7, 179, 'Wa laqad zaraanaa li jahannama kaseeram minal jinni wal insi lahum quloobul laa yafqahoona bihaa wa lahum a\'yunul laa yubisiroona bihaa wa lahum aazaanul laa yasma\'oona bihaa; ulaaa\'ika kal an\'aami bal hum adall; ulaaa\'ika humul ghaafiloon'),
  ('en.transliteration', 7, 180, 'Wa lillaahil Asmaaa \'ul Husnaa fad\'oohu bihaa wa zarul lazeena yulhidoona feee Asmaaa\'ih; sa yujzawna maa kaanoo ya\'maloon'),
  ('en.transliteration', 7, 181, 'Wa mimman khalaqnaaa ummatuny yahdoona bilhaqqi wa bihee ya\'diloon'),
  ('en.transliteration', 7, 182, 'Wallazeena kazzaboo bi Aayaatinaa sanastadrijuhum min haisu laa ya\'lamoon'),
  ('en.transliteration', 7, 183, 'Wa umlee lahum; inna kaidee mateen'),
  ('en.transliteration', 7, 184, 'Awalam yatafakkaroo maa bisaahibihim min jinnah; in huwa illaa nazeerum mubeen'),
  ('en.transliteration', 7, 185, 'Awalam yanzuroo fee malakootis samaawaati wal ardi wa maa khalaqal laahu min shai\'inw wa an \'asaaa ai yakoona qadiqtaraba ajaluhum fabi aiyi hadeesim ba\'dahoo yu\'minoon'),
  ('en.transliteration', 7, 186, 'Mai yadlilil laahu falaa haadiyaa lah; wa yazaruhum fee tughyaanihim ya\'mahoon'),
  ('en.transliteration', 7, 187, 'Yas\'aloonaka \'anis Saa\'ati aiyaana mursaahaa qul innamaa \'ilmuhaa \'inda Rabbee laa yujallaeehaa liwaqtihaaa illaa Hoo; saqulat fis samaawaati wal ard; laa taateekum illaa baghtah; yas\'aloonaka ka annaka hafiyyun \'anhaa qul innamaa \'ilmuhaa \'indal laahi wa laakinna aksaran naasi laa ya\'lamoon'),
  ('en.transliteration', 7, 188, 'Qul laaa amliku linafsee naf\'anw wa laa darran illaa maa shaaa\'al laah; wa law kuntu a\'alamul ghaiba lastaksartu minal khairi wa maa massaniyas soo\'; in ana illaa nazeerunw wa basheerul liqawminy yu\'minoon'),
  ('en.transliteration', 7, 189, 'Huwal lazee khalaqakum min nafsinw waahidatinw wa ja\'ala minhaa zawjahaa liyas kuna ilaihaa falammaa taghash shaahaa hamalat hamlan khafeefan famarrat bihee falammaaa asqalad da\'awal laaha Rabbahumaa la\'in aayaitanaa saalihal lanakoo nanna minash shaakireen'),
  ('en.transliteration', 7, 190, 'Falammaaa aataahumaa saalihan ja\'alaa lahoo shurakaaa\'a feemaaa aataahumaa; fata\'aalal laahu \'ammaa yushrikoon'),
  ('en.transliteration', 7, 191, 'A yushrikoona maa laa yakhluqu shai\'anw wa hum yukhlaqoon'),
  ('en.transliteration', 7, 192, 'Wa laa yastatee\'oona lahum nasranw wa laaa anfusahum yansuroon'),
  ('en.transliteration', 7, 193, 'Wa in tad\'oohum ilalhudaa laa yattabi\'ookum; sawaaa\'un \'alaikum a-da\'awtumoohum am antum saamitoon'),
  ('en.transliteration', 7, 194, 'Innal lazeena tad\'oona min doonil laahi \'ibaadun amsaalukum fad\'oohum fal yastajeeboo lakum in kuntum saadiqeen'),
  ('en.transliteration', 7, 195, 'A lahum arjuluny yamshoona bihaa am lahum aidiny yabtishoona bihaaa am lahum a\'yunuy yubsiroona bihaaa am lahum aazaanuny yasma\'oona bihaa; qulid\'oo shurakaaa\'akum summa keedooni falaa tunziroon'),
  ('en.transliteration', 7, 196, 'Inna waliyyial laahul lazee nazzalal Kitaaba wa Huwa yatawallas saaliheen'),
  ('en.transliteration', 7, 197, 'Wallazeena tad\'oona min doonihee laa yastatee\'oona nasrakum wa laaa anfusahum yansuroon'),
  ('en.transliteration', 7, 198, 'Wa in tad\'oohum ilal hudaa laa yasm\'oo wa taraahum yanzuroona ilaika wa hum laa yubsiroon'),
  ('en.transliteration', 7, 199, 'khuzil \'afwa waamur bil\'urfi waa\'rid \'anil jaahileen'),
  ('en.transliteration', 7, 200, 'Wa immaa yanzaghannaka minash Shaitaani nazghun fasta\'iz billaah; innahoo Samee\'un Aleem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 7, 201, 'Innal lazeenat taqaw izaa massahum taaa\'ifum minash Shaitaani tazakkaroo fa izaa hum mubsiroon'),
  ('en.transliteration', 7, 202, 'Wa ikhwaanuhum yamuddoonahum fil ghaiyi summa laa yuqsiroon'),
  ('en.transliteration', 7, 203, 'Wa izaa lam taatihim bi aayatin qaaloo law lajtabai tahaa; qul innamaaa attabi\'u maa yoohaaa ilaiya mir Rabbee; haazaa basaaa\'iru mir Rabbikum wa hudanw wa rahmatul liqawminy yu\'minoon'),
  ('en.transliteration', 7, 204, 'Wa izaa quri\'al Quraanu fastami\'oo lahoo wa ansitoo la \'allakum turhamoon'),
  ('en.transliteration', 7, 205, 'Wazkur Rabbaka fee nafsika tadarru\'anw wa kheefatanw wa doonal jahri minal qawli bilghuduwwi wal aasali wa laa takum minal ghaafileen'),
  ('en.transliteration', 7, 206, 'Innal lazeena \'inda Rabbika laa yastakbiroona \'an \'ibaadatihee wa yusabbihoonahoo wa lahoo yasjudoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 7, 1, 'المصۤ'),
  ('ur.ahmedali', 7, 2, 'یہ کتاب تیری طرف بھیجی گئی ہے تاکہ تو اس کے ذریعہ سے ڈرائے اور اس سے تیرے دل میں تنگی نہ ہونی چاہیئے اور یہ ایمان والوں کے لیے نصیحت ہے'),
  ('ur.ahmedali', 7, 3, 'جو چیز تمہارے رب کی طرف سے تم پر اتری ہے اس کا اتباع کرو اور الله کو چھوڑ کر دوسرے دوستوں کی تابعداری نہ کرو تم لوگ بہت ہی کم نصیحت مانتے ہو'),
  ('ur.ahmedali', 7, 4, 'اور کتنی بستیاں ہم نے ہلاک کر دی ہیں جن پر ہمارا عذاب رات کو آیا ایسی حالت میں کہ دوپہر کوسونے والے تھے'),
  ('ur.ahmedali', 7, 5, 'جس وقت ان پر ہمارا عذاب آیا پھر ان کی یہی پکار تھی کہتے تھے بے شک ہم ہی ظالم تھے'),
  ('ur.ahmedali', 7, 6, 'پھر ہم ان لوگوں سے ضرور سوال کریں گے جن کے پاس پیغمبر بھیجے گئے تھے اور ان پیغمبروں سے ضرور پوچھیں گے'),
  ('ur.ahmedali', 7, 7, 'پھر اپنے علم کی بناء پر ان کے سامنے بیان کر دیں گے اور ہم کہیں حاضر نہ تھے'),
  ('ur.ahmedali', 7, 8, 'اورواقعی اس دن وزن بھی ہوگا جس شخص کا پلہ بھاری ہو گا سو ایسے لوگ کامیاب ہوں گے'),
  ('ur.ahmedali', 7, 9, 'اور جس کا پلہ ہلکا ہو گا سو یہ لوگ ہوں گے جنہوں نے اپنا نقصان کیا اس لیے کہ ہماری آیتوں کا انکار کرتے تھے'),
  ('ur.ahmedali', 7, 10, 'اور ہم نے تمہیں زمین میں جگہ دی اور اس میں تمہاری زندگی کا سامان بنا دیا تم بہت کم شکر کرتے ہو'),
  ('ur.ahmedali', 7, 11, 'او رہم نے تمہیں پیدا کیا پھر تمہاری صورتیں بنائیں پھر فرشتوں کو حکم دیا کہ آدم کو سجدہ کرو پھر سوائے ابلیس کے سب نے سجدہ کیا وہ سجدہ کرنے والوں میں سے نہ تھا'),
  ('ur.ahmedali', 7, 12, 'فرمایاتجھے سجدہ کرنے سے کس چیز نے منع کیا ہے جب کہ میں نے تجھے حکم دیا کہا میں اس سے بہتر ہوں تو نے مجھے آگ سے بنایا اور اسے مٹی سے بنایا ہے'),
  ('ur.ahmedali', 7, 13, 'کہاتو یہاں سے اتر جا تجھے یہ لائق نہیں کہ یہاں تکبر کرے پس نکل جا بے شک تو ذلیلوں میں سے ہے'),
  ('ur.ahmedali', 7, 14, 'کہا مجھے اس دن تک مہلت دے جس دن لوگ قبرو ں سے اٹھائے جائیں گے'),
  ('ur.ahmedali', 7, 15, 'فرمایا تجھے مہلت دی گئی ہے'),
  ('ur.ahmedali', 7, 16, 'کہا جیسا تو نے مجھے گمراہ کیا ہے میں بھی ضرور ان کی تاک میں تیری سیدھی راہ پر بیٹھوں گا'),
  ('ur.ahmedali', 7, 17, 'پھر ان کے پاس ان کے آگے ان کے پیچھے ان کے دائیں اور ان کے بائیں سےآؤں گا اور تو اکثر کو ان میں سے شکر گزار نہیں پائے گا'),
  ('ur.ahmedali', 7, 18, 'فرمایا یہاں سے ذلیل و خوار ہو کر نکل جا جو شخص ان سے تیرا کہا مانے گا میں تم سب کو جہنم میں بھر دوں گا'),
  ('ur.ahmedali', 7, 19, 'اور اے آدم تو اور تیری عورت جنت میں رہو پھر جہاں سے چاہو کھاؤ اور اس درخت کے پاس نہ جاؤ ورنہ بے انصافوں میں سے ہو جاؤ گے'),
  ('ur.ahmedali', 7, 20, 'پھرانہیں شیطان نے بہکایا تاکہان کی شرم گاہیں جو ایک دوسرے سے چھپائی گئی تھیں ان کے سامنے کھول دے اور کہا تمہیں تمہارے رب نے اس درخت سے نہیں روکا مگر اس لیے کہ کہیں تم فرشتے ہو جاؤ یا ہمیشہ رہنے والے ہو جاؤ'),
  ('ur.ahmedali', 7, 21, 'اور ان کے روبرو قسم کھائی کہ البتہ میں تمہارا خیرا خواہ ہوں'),
  ('ur.ahmedali', 7, 22, 'پھر انہیں دھوکہ سے مائل کر لیا پھرجب ان دونوں نے درخت کو چکھا تو ان پر ان کی شرم گاہیں کھل گئیں اور اپنے اوپر بہشت کے پتے جوڑنے لگے اورانہیں ان کے رب نے پکارا کیا میں نے تمہیں اس درخت سے منع نہیں کیا تھا اور تمہیں کہ نہ دیا تھا کہ شیطان تمہارا کھلا دشمن ہے'),
  ('ur.ahmedali', 7, 23, 'ان دونوں نے کہا اے رب ہمارے ہم نے اپنی جانوں پر ظلم کیا اور اگر تو ہمیں نہ بخشے گا اور ہم پر رحم نہ کرے گا تو ہم ضرور تباہ ہوجائیں گے'),
  ('ur.ahmedali', 7, 24, 'فرمایا یہاں سے اترو تم ایک دوسرے کے دشمن ہو گے اور تمہارے لیے زمین میں ٹھکانا ہے اور ایک وقت تک نفع اٹھانا ہے'),
  ('ur.ahmedali', 7, 25, 'فرمایا تم اسی میں زندہ رہو گے اور اسی میں مرو گے اور اسی سے نکالے جاؤ گے'),
  ('ur.ahmedali', 7, 26, 'اے آدم کی اولاد ہم نے تم پر پوشاک اتاری جو تمہاری شرم گاہیں ڈھانکتی ہیں اور آرائش کے کپڑے بھی اتارے اور پرہیزگاری کا لباس وہ سب سے بہتر ہے یہ الله کی قدرت کی نشانیاں ہیں تاکہ وہ نصیحت حاصل کریں'),
  ('ur.ahmedali', 7, 27, 'اے آدم کی اولاد تمہیں شیطان نہ بہکائے جیسا کہ اس نے تمہارے ماں باپ کو بہشت سے نکال دیا ان سے ان کے کپڑے اتروائے تاکہ تمہیں ان کی شرمگاہیں دکھائے وہ اور اس کی قوم تمہیں دیکھتی ہے جہاں سے تم انہیں نہیں دیکھتے ہم نے شیطانوں کو ان لوگوں کا دوست بنادیا ہے جوایمان نہیں لاتے'),
  ('ur.ahmedali', 7, 28, 'اور جب کوئی برا کام کرتے ہیں تو کہتے ہیں کہ ہم نے اسی طرح اپنے باپ دادا کو کرتے دیکھا ہے اور الله نے بھی ہمیں یہ حکم دیا ہے کہہ دو بے شک الله بے حیائی کا حکم نہیں کرتا الله کے ذمہ وہ باتیں کیوں لگاتے ہو جو تمہیں معلوم نہیں'),
  ('ur.ahmedali', 7, 29, 'کہہ دو میرے رب نے انصاف کا حکم دیا ہے اور ہر نماز کےوقت اپنے منہ سیدھے کرو اور اس کے خالص فرمانبردار ہو کر اسے پکارو جس طرح تمہیں پہلے پیدا کیا ہے اسی طرح دوبارہ پیدا ہو گے'),
  ('ur.ahmedali', 7, 30, 'ایک جماعت کو ہدایت دی اور ایک جماعت پر گمراہی ثابت ہو چکی انہوں نے الله کو چھوڑ کر شیطان کو اپنا دوست بنایا ہے اور خیال کرتے ہیں کہ وہ ہدایت پر ہیں'),
  ('ur.ahmedali', 7, 31, 'اے آدم کی اولاد تم مسجد کی حاضری کے وقت اپنا لباس پہن لیا کرو اور کھاؤ اور پیئو اور حد سے نہ نکلو بے شک الله حد سے نکلنے والوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 7, 32, 'کہہ دو الله کی زینت کو کس نے حرام کیا ہے جو اس نے اپنے بندو ں کے واسطے پیدا کی ہے اورکس نے کھانے کی ستھری چیزیں (حرام کیں) کہہ دو دنیا کی زندگی میں یہ نعمتیں اصل میں ایمان والوں کے لیے ہیں قیامت کے دن خالص انہیں کے لیے ہوجائیں گی اسی طرح ہم آیتیں مفصل بیان کرتے ہیں ان کے لیے جو سمجھتے ہیں'),
  ('ur.ahmedali', 7, 33, 'کہہ دو میرے رب نے صرف بے حیائی کی باتو ں کو حرام کیا ہے خواہ وہ علانیہ ہوں یا پوشیدہ اور ہر گناہ کواور ناحق کسی پر ظلم کرنے کو بھی اور یہ کہ الله پر وہ باتیں کہو جو تم نہیں جانتے'),
  ('ur.ahmedali', 7, 34, 'اور ہر ایک گروہ کے لیے ایک معیاد معین ہے پھر جب وہ معیاد ختم ہو گی اور وقت نہ ایک گھڑی پیچھے ہٹیں گے اور نہ آگے بڑھیں گے'),
  ('ur.ahmedali', 7, 35, 'اے ادم کی اولاد اگر تم میں سے تمہارے پاس رسول آئیں جو تمہیں میری آیتیں سنائیں پھر جو شخص ڈرے گا اور اصلاح کرے گا ایسوں پر کوئی خوف نہ ہوگا اور نہ وہ غم کھائیں گے'),
  ('ur.ahmedali', 7, 36, 'اور جنہوں نے ہماری آیتو ں کو جھٹلایا اوران سے تکبر کیا وہی دوزخی ہیں وہ اس میں ہمیشہ رہنے والے ہوں گے'),
  ('ur.ahmedali', 7, 37, 'پھر اس سے زیادہ ظالم کون ہوگا الله پر بہتان باندھے یا اس کے حکموں کو جھٹلائے ان لوگوں کا جو کچھ نصیب ہے وہ ان کو مل جائے گا یہاں تک کہ جب ان کے ہاں ہمارے بھیجے ہوئے فرشتے ان کی روح قبض کرنے کے لیے آئيں گے تو کہیں گے کہ وہ کہاں گئے الله کو چھوڑ کر جن کی تم عبادت کرتے تھے کہیں گے ہم سے سب غائب ہو گئے اور اپنے کافر ہونے کااقرار کرنے لگیں گے'),
  ('ur.ahmedali', 7, 38, 'فرمائے گا جنوں اور آدمیوں میں سے جو امتیں تم سے پہلے ہو چکی ہیں ان کے ساتھ دوزخ میں داخل ہو جاؤ جب ایک امت داخل ہو گی تو دوسری پر لعنت کرے گی یہاں تک کہ جب اس میں سب گر جائیں گے تو ن کے پچھلے پہلوں سے کہیں گے اے رب ہمارے ہمیں انہوں نے گمراہ کیا سو تو انہیں آگ کا دگنا عذاب دے فرمائے گا کہ دونوں کو دگنا ہے لیکن تم نہیں جانتے'),
  ('ur.ahmedali', 7, 39, 'اور پہلے پچھلوں سے کہیں گے پس تمہیں ہم پر کوئی فضیلت نہیں پس بسب اپنی کمائی کے عذاب چکھو'),
  ('ur.ahmedali', 7, 40, 'بے شک جنہوں نے ہماری آیتو ں کو جھٹلایا اوران کے مقابلہ میں تکبر کیا ان کے لیے آسمان کے دروازے نہیں کھولے جائیں گے اورنہ وہ جنت میں داخل ہوں گے یہاں تک کہ اونٹ سوئی کے ناکے میں گھس جائے اور ہم گناہگاروں کو اسی طرح سزا دیتے ہیں'),
  ('ur.ahmedali', 7, 41, 'ان کے لیے دوزخ کا بچھونا اور اوپر سے اوڑھنا ہے اور ہم ظالموں کو ایسی ہی سزا دیا کرتے ہیں'),
  ('ur.ahmedali', 7, 42, 'اور جو ایمان لانے اور نیکیاں کیں ہم کسی پر بوجھ نہیں رکھتے مگر اس کی طاقت کےموافق وہی بہشتی ہیں وہ اس میں ہمیشہ رہنے والے ہیں'),
  ('ur.ahmedali', 7, 43, 'اور جوکچھ ان کے دلو ں میں خفگی ہو گی ہم اسے دور کردیں گے ان کے نیچے نہریں بہتی ہوں گی اور وہ کہیں گےکہ الله کاشکر ہے جس نے ہمیں یہاں تک پہنچایا اور ہم راہ نہ پاتے اگر الله ہماری رہنمائی نہ فرماتا بے شک ہمارے رب کے رسول سچی بات لائے تھے جور آواز آئے گی کہ یہ جنت ہے تم اپنے اعمال کے بدلے اس کے وارث ہو گئے ہو'),
  ('ur.ahmedali', 7, 44, 'اور بہشت والے دوزخیوں کو پکاریں گے کہ ہم نے وعدہ سچا پایا جو ہمارے رب نے ہم سے کیا تھا آیاتم بھی اپنے رب کے وعدہ کو سچا پایا وہ کہیں گے ہاں پھر ایک پکارنے والا ان کے درمیان پکارے گا کہ ان ظالمو ں پر الله کی لعنت ہے'),
  ('ur.ahmedali', 7, 45, 'جو الله کی راہ سے روکتے تھے اور اسے ٹیڑھا کرنا چاہتے تھے اور وہ آخرت کے منکر تھے'),
  ('ur.ahmedali', 7, 46, 'اور ان دونوں کے درمیان ایک دیوار ہو گی اور اعراف کے اوپر ایسے مرد ہوں گے کہ ہر ایک کو اس کی نشانی سے پہچان لیں گے اور جنت والوں کو پکار کر کہیں گے کہ تم پر سلام ہو وہ ابھی جنت میں داخل نہیں ہوئے اور امیدوار ہیں'),
  ('ur.ahmedali', 7, 47, 'اورجب ان کی نگاہ دوزخ والوں کی طرف پھرے گی تو کہیں گے اے رب ہمارے ہمیں ظالموں کے ساتھ نہ ملا'),
  ('ur.ahmedali', 7, 48, 'اور اعراف والے پکاریں گے جنہیں وہ ان کی نشانی سے پہچانتے ہوں گے کہیں گے تمہاری جماعت تمہارے کسی کام نہ آئی اور نہ وہ جو تم تکبر کیا کرتے تھے'),
  ('ur.ahmedali', 7, 49, 'یہ وہی ہیں جن کے متعلق تم قسم کھاتے تھے کہ انہیں الله کی رحمت نہیں پہنچے گی (انہیں کہا گیا ہے) جنت میں چلے جاؤ تم پر نہ ڈر ہے اور نہ تم غمگین ہو گے'),
  ('ur.ahmedali', 7, 50, 'اور دوزخ والے بہشت والوں کو پکاریں گے کہ ہم پر تھوڑا سا پانی بہا دو یا کچھ اس چیز میں سے دو جو تمہیں الله نے رزق دیا ہے کہیں گے بے شک الله نے انہیں دونوں چیزوں کو کافروں پر حرام کیا ہے'),
  ('ur.ahmedali', 7, 51, 'جنہوں نے اپنا دین تماشا اور کھیل بنایا اور انہیں دنیا کی زندگی نے دھوکے میں ڈال دیا ہے سو آج ہم انہیں بھلا دیں گے جس طرح انہوں نے اس دن کی ملاقات کو بھلا دیا تھا اور جیسا وہ ہماری آیتوں سے انکار کرتے تھے'),
  ('ur.ahmedali', 7, 52, 'اور ہم نے ان کے پاس ایک ایسی کتاب پہنچا دی ہے جسے ہم نے اپنے علم کامل سے بہت ہی واضح کر کے بیان کر دیا ہے وہ ہدایت ہے اوررحمت ہے'),
  ('ur.ahmedali', 7, 53, 'ان لوگو ں کے لیے ےجو ایمان لے آئے ہیں انہیں اور کسی بات کا انتظار نہیں صرف آخری نتیجہ کا انتظار ہے جس دن اس کا آخری نتیجہ سامنے آئے گا اس دن جو اسے پہلے بھولے ہوئے تھے کہیں گے کہ واقعی ہمارے رب کے رسول کی سچی باتیں لائے تھے سو اب کیا کوئی ہمارا سفارشی ہے جو ہماری سفارش کر ےیاکیا ہم پھر واپس بھیجے جا سکتے ہیں تاکہ ہم ان کے اعمال کے خلاف جنہیں کیا کرتے تھے دوسرے اعمال کریں بے شک انہوں نے اپنے آپ کو خسارے میں ڈا ل دیا اور جو باتیں بناتے تھے وہ سب گم ہو گئیں'),
  ('ur.ahmedali', 7, 54, 'بے شک تمہارا رب الله ہے جس نے آسمانوں اور زمین کو چھ دن میں پیدا کیا پھرعرش پر قرار پکڑا رات سے دن کو ڈھانک دیتا ہے وہ اس کے پیچھے دوڑتا ہوا آتا ہے اور سورج اورچاند اور ستارے اپنے حکم کے تابعدار بنا کر پیدا کیے اسی کا کام ہے پیدا کرنا اور حکم فرمانا الله بڑی برکت والا ہے جو سارے جہان کا رب ہے'),
  ('ur.ahmedali', 7, 55, 'اپنے رب کو عاجزی اور چپکے سے پکارو اسے حد سے بڑھنے والے پسند نہیں آتے'),
  ('ur.ahmedali', 7, 56, 'اور زمین میں اس کی اصلاح کے بعد فساد مت کرو اور اسے ڈر اور طمع سے پکارو بے شک اللهکی رحمت نیکو کاروں سے قریب ہے'),
  ('ur.ahmedali', 7, 57, 'اور وہی ہے جو مینہ سے پہلے خوشخبری دینے والی ہوائیں چلاتا ہے یہاں تک کہ جب ہوائیں بھاری بادلو ں کو اٹھا لاتی ہیں تو ہم ا س بادل کو مردہ شہر کی طرف ہانک دیتے ہیں پھر ہم ا س بادل سے پانی اتارتے ہیں پھر اس سے سب طرح کے پھل نکالتے ہیں اسی طرح ہم مردوں کو نکالیں گے تاکہ تم نصیحت حاصل کرو'),
  ('ur.ahmedali', 7, 58, 'اور جو شہر پاکیزہ ہے اس کا سبزہ اس کے رب کے حکم سے نکلتا ہے اور جو اس میں خراب ہے جو کچھ اس میں سے نکلتا ہے ناقص ہی ہوتا ہے اسی طرح ہم شکر گزاروں کے لیے مختلف طریقوں سے آیتیں بیان کرتے ہیں'),
  ('ur.ahmedali', 7, 59, 'بے شک ہم نے نوح کو اس کی قوم کی طرف بھیجا پس اس نے کہا اے میری قوم الله کی بندگی کرو اس کے سوا تمہارا کوئی معبود نہیں میں تم پر ایک بڑے دن کے عذاب سے ڈرتا ہوں'),
  ('ur.ahmedali', 7, 60, 'اس کی قو م کے سرداروں نے کہا ہم تجھے صریح گمراہی میں دیکھتے ہیں'),
  ('ur.ahmedali', 7, 61, 'فرمایا اے میری قوم میں ہرگز گمراہ نہیں ہوں لیکن میں جہان کے پروردگار کی طرف سے بھیجا ہوا ہوں'),
  ('ur.ahmedali', 7, 62, 'تمہیں اپنے رب کے پیغام پہنچاتا ہوں اور تمہیں نصیحت کرتا ہوں اور الله کی طرف سے وہ باتیں جانتا ہوں جو تم نہیں جانتے'),
  ('ur.ahmedali', 7, 63, 'کیا تمہیں اس بات سے تعجب ہوا کہ تمہارے رب کی طرف سے تم ہی میں سے ایک مرد کی زبانی تمہارے پاس نصیحت آئی ہے تاکہ وہ تمہیں ڈرائے اورتاکہ تم پرہیزگار ہو جاؤ اور تاکہ تم پرحم کیے جاؤ'),
  ('ur.ahmedali', 7, 64, 'پھر انہو ں نے اسے جھٹلایا پھر ہم نے اسے اور ا سکے ساتھیوں کو کشتی میں بچا لیا اور جو ہماری آیتوں کو جھٹلاتے تھے انہیں غرق کر دیا بے شک وہ لوگ اندھے تھے'),
  ('ur.ahmedali', 7, 65, 'اور قوم عاد کی طرف ان کے بھائی ہود کو بھیجا فرمایا اے میری قوم الله کی بندگی کرو اس کے سوا تمہارا کوئی معبود نہیں سو کیا تم ڈرتے نہیں'),
  ('ur.ahmedali', 7, 66, 'اس کی قوم کےکافر سردار بولےہم تو تمہیں بے وقوف سمجھتے ہیں اور ہم تجھے جھوٹا خیال کرتے ہیں'),
  ('ur.ahmedali', 7, 67, 'فرمایا اے میری قوم میں بے وقوف نہیں ہوں لیکن میں پروردگار عالم کی طرف سے بھیجا ہوا ہوں'),
  ('ur.ahmedali', 7, 68, 'تمہیں اپنے رب کے پیغام پہنچاتا ہوں اور تمہارا امانت دار خیر خواہ ہوں'),
  ('ur.ahmedali', 7, 69, 'کیا تمہیں تعجب ہوا کہ تمہارے رب کی طرف سے تمہیں میں سے ایک مرد کی زبانی تمہارے پاس نصیحت آئی ہے تاکہ تمہیں ڈرائے اور یاد کرو جب کہ تمہیں قوم نوح کے بعد جانشین بنا یا اورڈیل ڈول میں تمہیں پھیلاؤ زیادہ دیا سو الله کی نعمتوں کو یاد کرو تاکہ تم نجات پاؤ'),
  ('ur.ahmedali', 7, 70, 'انہوں نے کہا کیا تو ہمارے پاس اس لیے آیا ہے کہ ہم ایک الله کی بندگی کریں اور ہمارے باپ دادا جنہیں پوجتے رہے انہیں چھوڑ دیں پس جس چیز سے تو ہمیں ڈراتا ہے وہ لے آ اگرتو سچا ہے'),
  ('ur.ahmedali', 7, 71, 'فرمایا تمہارے رب کی طرف سے تم پر عذاب اور غصہ واقع ہو چکا مجھ سے ان ناموں پر کیوں جھگڑتے ہو جوتم نے اور تمہارے باپ دادؤں نے مقرر کیے ہیں الله نے ان کے لیے کوئی دلیل نہیں اتاری سو انتظار کرو میں بھی تمہارے ساتھ انتظار کرنے والا ہوں'),
  ('ur.ahmedali', 7, 72, 'پھر ہم نے اسے اور اس کے ساتھیوں کو اپنی رحمت سے بچا لیا اور جو ہماری آیتوں کو جھٹلاتے تھے ان کی جڑ کاٹ دی اور وہ مومن نہیں تھے'),
  ('ur.ahmedali', 7, 73, 'اور ثمود کی طرف ان کے بھائی صالح کو بھیجا فرمایا اے میری قوم الله کی بندگی کرو اس کے سوا تمہارا کوئی معبود نہیں تمہیں تمہراے رب کی طرف سے دلیل پہنچ چکی ہے یہ الله کی اونٹنی تمہارے لیے نشانی ہے سو اسے چھوڑ دو کہ الله کی زمین میں کھائے اور اسے بری طرح سے ہاتھ نہ لگاؤ ورنہ تمہیں دردناک عذاب پکڑے گا'),
  ('ur.ahmedali', 7, 74, 'اور یاد کرو جب کہ تمہیں عاد کے بعد جانشین بنایا اور تمہیں زمین میں جگہ دی کہ نرم زمین میں محل بناتے ہو اور پہاڑو ں میں گھر تراشتے ہو سو الله کے احسان کو یاد کرو اور زمین میں فساد مت مچاتے پھرو'),
  ('ur.ahmedali', 7, 75, 'اس قوم کے متکبر سرداروں نے غریبوں سے کہا جو ایمان لاچکے تھے کیا تمہیں یقن ہے کہ صالح کو اس کے رب نے بھیجا ہے انہوں نے کہا جو وہ لے کر آیا ہے ہم اس پرایمان لانے والے ہیں'),
  ('ur.ahmedali', 7, 76, 'متکبروں نے کہا جس پر تمہیں یقین ہے ہم اسے نہیں مانتے'),
  ('ur.ahmedali', 7, 77, 'پھر اونٹنی کے پاؤں کاٹ ڈالے اور اپنے رب کے حکم سے سرکشی کی اور کہا اے صالح لے آ ہم پر جس سے تو ہمیں ڈراتا تھا اگر تو رسول ہے'),
  ('ur.ahmedali', 7, 78, 'پس انہیں زلزلہ نے آ پکڑا پھر صبح کو اپنے گھروں میں اوندھے پڑے ہوئے رہ گئے'),
  ('ur.ahmedali', 7, 79, 'پھر صالح ان سے منہ موڑ کر چلے اور فرمایا اے میری قوم میں تمہیں اپنے رب کا پیغام پہنچا چکا اور تمہاری خیر خواہی کی لیکن تم خیر خواہوں کو پسند نہیں کرتے تھے'),
  ('ur.ahmedali', 7, 80, 'اور لوط کو بھیجا جب اس نے اپنی قوم کو کہا کیا تم ایسی بے حیائی کرتے ہو کہ تم سے پہلے اسے جہان میں کسی نے نہیں کیا'),
  ('ur.ahmedali', 7, 81, 'بے شک تم عورتوں کو چھوڑ کر مردوں سے شہوت رانی کرتے ہو بلکہ تم حد سے بڑھنے والے ہو'),
  ('ur.ahmedali', 7, 82, 'اور اس کی قوم نے کوئی جواب نہیں دیا مگر یہی کہا کہ انہیں اپنےشہر سے نکال دو یہ لوگ بہت ہی پاک بننا چاہتے ہیں'),
  ('ur.ahmedali', 7, 83, 'پھر ہم نے اسےاور اس کے گھر والوں کو سوائے اس کی بیوی کے بچا لیا کہ وہ وہاں رہنے والو ں میں رہ گئی'),
  ('ur.ahmedali', 7, 84, 'اور ہم نے ان پر مینہ برسایا پھر دیکھیئے گناہگاروں کا کیا انجام ہوا'),
  ('ur.ahmedali', 7, 85, 'اورمدین کی طرف اس کے بھائی شعیب کو بھیجا فرمایااے میری قوم الله کی بندگی کرو اس کے سوا تمہار کوئی معبود نہیں تمہارے رب کی طرف سے تمہارے پاس دلیل پہنچ چکی ہے سو ناپ او رتول کو پورا کرو اور لوگوں کو ان کی چیزیں گھٹا کر نہ دو اور زمین میں اس کی اصلاح کے بعد فساد مت کرو یہ تمہارے لیے بہتر ہے اگر تم ایمان دار ہو'),
  ('ur.ahmedali', 7, 86, 'اور سڑکوں پر اس غرض سے مت بیٹھا کرو کہ الله پر ایمان لانے والوں کو دھمکیاں دو اور الله کی راہ سے روکو اوراس میں ٹیڑھا پن تلاش کرو اور اس حلات کو یاد کرو جب کہ تم تھوڑے تھے پھر الله نے تمہیں زیادہ کر دیا اور دیکھو فساد کرنے والوں کا انجام کیا ہوا ہے'),
  ('ur.ahmedali', 7, 87, 'اور اگر تم میں سے ایک جماعت اس پر ایمان لے آئی ہے جو میرے ذریعے سے بھیجا گیا ہے اور ایک جماعت ایمان نہیں لائی پس صبر کرو جب تک الله ہمارے درمیان فیصلہ کرے اور وہ سب سے بہتر فیصلہ کرنے والا ہے'),
  ('ur.ahmedali', 7, 88, 'اس کی قوم کے متکبر سرداروں نے کہا اے شعیب ہم تجھے اور انہیں جو تجھ پر ایمان لائے ہیں اپنے شہر سے ضرور نکال دیں گے یا یہ کہ تم ہمارے دین میں واپس آ جاؤ فرمایا کیا اگرچہ ہم اس دین کو ناپسند کرنے والے ہوں'),
  ('ur.ahmedali', 7, 89, 'ہم تو الله پر بہتان باندھنے والے ہو جائیں اگر تمہارے مذہب میں واپس آئيں بعد اس کے کہ الله نے ہمیں اس سے نجات دی ہے اور ہمیں یہ حق نہیں کہ تمہارے دین میں لوٹ کر آئيں مگر یہ کہ الله چاہے جو ہمارا رب ہے ہمارے رب کا علم ہر چیز پر احاطہ کیے ہوئے ہے ہم الله ہی پر بھروسہ کرتے ہیں اے رب ہمارے اور ہماری قوم کے درمیان حق کے موافق فیصلہ کر دے اور تو بہتر فیصلہ کرنے والا ہے'),
  ('ur.ahmedali', 7, 90, 'اس کی قوم میں جو کافر سردار تھے انہوں نے کہا اگر تم شعیب کی تابعداری کرو گے تو بے شک نقصان اٹھاؤ گے'),
  ('ur.ahmedali', 7, 91, 'پھر انہیں زلزلہ نے آ پکڑا پھر وہ صبح تک اپنے گھرو ں میں اوندھے پڑے ہوئے رہ گئے'),
  ('ur.ahmedali', 7, 92, 'جنہوں نے شعیب کو جھٹلایا گو وہ وہاں کبھی بسے ہی نہیں تھے جنہوں نے شعیب کو جھٹلایا وہی نقصان اٹھانے والے ہوئے'),
  ('ur.ahmedali', 7, 93, 'پھر ان سے منہ پھیرا اور کہا اے میری قوم تحقیق میں نے تمہیں اپنے رب کے احکام پہنچا دیے اور میں نے تمہارے لیے خیر خواہی کی پھر کافروں کی قوم پر میں کیوں کر غم کھاؤں'),
  ('ur.ahmedali', 7, 94, 'او رہم نے کسی بستی میں کوئی پیغمبرنہیں بھیجا مگر وہاں کے لوگوں کو سختی اور تکلیف میں پکڑا تاکہ وہ عاجزی کریں'),
  ('ur.ahmedali', 7, 95, 'پھر ہم نے برائی کی جگہ بھلائی بدل دی یہاں تک کہ وہ زیادہ ہو گئے اور کہنے لگے کہ ہمارے باپ داداؤں کو بھی تکلیف اور خوشی کا وقت آیا تھا پھر ہم نے انہیں اچانک پکڑا اور ان کو خبر نہ ہوئی'),
  ('ur.ahmedali', 7, 96, 'اور اگر بستیوں والے ایمان لے آتے اور ڈرتے تو ہم ان پر آسمان اور زمین سے نعمتوں کے دروازے کھول دیتے لیکن انہوں نے جھٹلایا پھر ہم نے ان کے اعمال کے سبب سے گرفت کی'),
  ('ur.ahmedali', 7, 97, 'کیا بستی والے نڈر ہو چکے ہیں کہ ہماری طرف سے ان پر رات کو عذاب آئے جب وہ سو رہے ہوں'),
  ('ur.ahmedali', 7, 98, 'یا بستیوں والے اس بات سے نڈر ہو چکے ہیں کہ ان پر ہمارا عذاب دن چڑھے آئے جب وہ کھیل رہے ہوں'),
  ('ur.ahmedali', 7, 99, 'کیا وہ الله کی اچانک پکڑ سے بے فکر ہوئے ہیں بس الله کی اچانک پکڑ سے بے فکر ہو گئے ہیں پس الله کی اچانک پکڑ سے بے فکر نہیں ہوتے مگر نقصان اٹھانے والے'),
  ('ur.ahmedali', 7, 100, 'کیا ان لوگو ں پر جو زمین کے وارث ہوئے ہیں وہاں کے لوگوں کے ہلاک ہونے کے بعد یہ ظاہر نہیں ہوا کہ اگر ہم چاہیں تو انہیں ان کے گناہوں کے سبب سے پکڑ لیں اور ہم نے ان کے دلوں پر مہر لگا دی ہے پس وہ نہیں سنتے'),
  ('ur.ahmedali', 7, 101, 'یہ بستیاں ہیں جن کے حالات ہم تمہیں سناتے ہیں بے شک ان کے پاس ان کے رسولروشن نشانیاں لے کر آئے تھے پھر اس بات پر ہرگز ایمان نہ لائے جسے پہلے جھٹلا چلے تھے کافروں کے دلوں پر الله اسی طرح مہر لگا دیتا ہے'),
  ('ur.ahmedali', 7, 102, 'اور ہم نے ان کے اکثر لوگو ں میں عہد کا نباہ نہیں پایا اور ان میں سے اکثر نافرمان پایا'),
  ('ur.ahmedali', 7, 103, 'اس کے بعد ہم نے موسیٰ کو اپنی نشانیاں دے کر فرعون اور اس کے سرداروں کی طرف بھیجا پھر انہوں نے نشانیوں سے بے انصافی کی پھر دیکھ مفسدوں کا انجام کیا ہوا'),
  ('ur.ahmedali', 7, 104, 'اور موسیٰ نے کہا اے فرعون بے شک میں رب العالمین کی طرف سے رسول ہو کر آیا ہوں'),
  ('ur.ahmedali', 7, 105, 'میرے لیے یہی مناسب ہے کہ سوائے سچ کے کوئی بات خدا کی طرف منسوب نہ کروں میں تمہارے رب کی طرف سے تمہارے پاس ایک بڑی دلیل لایا ہوں پس بنی اسرائیل کو میرے ساتھ بھیج دے'),
  ('ur.ahmedali', 7, 106, 'کہا اگرتو کوئی نشانی لے کر آیا ہے تو وہ لا اگر تو سچا ہے'),
  ('ur.ahmedali', 7, 107, 'پھر اس نے اپنا عصا ڈال دیا وہ اس وقت صریح اژدھا ہو گیا'),
  ('ur.ahmedali', 7, 108, 'او راپنا ہاتھ نکالا تو اسی وقت دیکھنے والوں کے لیے سفید نظر آنے لگا'),
  ('ur.ahmedali', 7, 109, 'فرعون کی قوم کے سرداروں نے کہا بے شک یہ بڑا ماہر جادو گر ہے'),
  ('ur.ahmedali', 7, 110, 'تمہیں تمہارے ملک سے نکالنا چاہتا ہے پس تم کیا مشورہ دیتے ہو'),
  ('ur.ahmedali', 7, 111, 'انہوں نے کہا کہ اسے اور اس کے بھائی کو مہلت دے اور شہروں میں جمع کرنے والے بھیج دے'),
  ('ur.ahmedali', 7, 112, 'تاکہ تیرے پاس ماہر جادوگر کو لے آئيں'),
  ('ur.ahmedali', 7, 113, 'اور جادوگر فرعون کے پاس آئے کہا اگر ہم غالب آئے تو ہمیں کچھ صلہ بھی ملے گا'),
  ('ur.ahmedali', 7, 114, 'کہا ہاں اور بے شک تم مقرب ہو جاؤ گے'),
  ('ur.ahmedali', 7, 115, 'کہا اے موسیٰ یا تو تو ڈال یا ہم ڈالتے ہیں'),
  ('ur.ahmedali', 7, 116, 'کہا تم ڈالوپس جب انہوں نے ڈالا تو لوگو ں کی نظر بندی کر دی اور انہیں ڈرایا اور اک طرح کا بڑا جادو دکھایا'),
  ('ur.ahmedali', 7, 117, 'اور ہم نے موسیٰ کو وحی کے ذریعے سے حکم دیا اپنا عصا ڈال دے سو وہ اسی وقت نگلنے لگا جو کھیل انہو ں نے بنا رکھا تھا'),
  ('ur.ahmedali', 7, 118, 'پھر حق ظاہر ہو گیا اور جو انہوں نے بنایا تھا وہ غلط ہو گیا'),
  ('ur.ahmedali', 7, 119, 'پھر اس جگہ ہار گئے اور ذلیل ہو کر لوٹے'),
  ('ur.ahmedali', 7, 120, 'اور جادوگر سجدہ میں گر پڑے'),
  ('ur.ahmedali', 7, 121, 'کہاہم رب العالمین پر ایمان لائے'),
  ('ur.ahmedali', 7, 122, 'جو موسیٰ اور ہارون کا رب ہے'),
  ('ur.ahmedali', 7, 123, 'فرعون نے کہا تم اس پر میری اجازت سے پہلے ہی ایمان لے آئے یہ تو مکر ہے جو تم سب نے اس شہر میں بنایا ہے تاکہ اس شہر کے رہنے والوں کو نکال دو سو اب تمہیں معلوم ہو جائے گا'),
  ('ur.ahmedali', 7, 124, 'میں ضرور تمہارے ہاتھ اور دوسری طرف سے پاؤں کاٹوں گا پھر تم سب کو سولی چڑھا دوں گا'),
  ('ur.ahmedali', 7, 125, 'انہوں نے کہا ہمیں تو اپنے رب کی طرف لوٹ کر جانا ہی ہے'),
  ('ur.ahmedali', 7, 126, 'اور تمہیں ہم سے یہی دشمنی ہے کہ ہم نے اپنے رب کی نشانیوں کو مان لیا جب وہ ہمارے پاس آئیں اے ہمارے رب ہمارے اوپر صبر ڈال اورہمیں مسلمان کر کے موت دے'),
  ('ur.ahmedali', 7, 127, 'اور فرعون کی قوم کے سرداروں نے کہا کیا تو موسیٰ اور اس کی قوم کو چھوڑتا ہے تاکہ وہ ملک میں فساد کریں اور تجھے اورتیرے معبودوں کو چھوڑ دے کہا ہم ان کے بیٹوں کو قتل کریں گے اور ان کی عورتو ں کو زندہ رکھیں گے اور بے شک ہم ان پر غالب ہیں'),
  ('ur.ahmedali', 7, 128, 'موسیٰ نے اپنی قوم سے کہا الله سے مدد مانگو اور صبر کرو بے شک زمین الله کی ہے اپنے بندوں میں سے جسےچاہے اس کا وارث بنا دے اور انجام بخیر پرہیزگاروں کا ہی ہوتا ہے'),
  ('ur.ahmedali', 7, 129, 'انہوں نے کہا تیرے آنے سےپہلے بھی ہمیں تکلیفیں دی گئیں اور تیرے آنے کے بعد بھی فرمایا تمہارا رب بہت جلد تمہارے دشمن کو ہلاک کر دے گا اور اس کی بجائے تمہیں اس سرزمین کا مالک بنا دے گا پھر دیکھے گاتم کیا کرتے ہو'),
  ('ur.ahmedali', 7, 130, 'اور ہم نے فرعون والوں کو قحطوں میں اور میوں کی کمی میں پکڑ لیا تاکہ وہ نصیحت مانیں'),
  ('ur.ahmedali', 7, 131, 'جب ان پر خوشحالی آتی تو کہتے کہ یہ تو ہمارے لیے ہونا ہی چاہیئے اور اگر انہیں کوئی بدحالی پیش آتی تو موسیٰ اور ان کے ساتھیوں کی نحوست بتلاتے یاد رکھو ان کی نحوست الله کے علم میں ہے لیکن اکثر لوگ نہیں جانتے'),
  ('ur.ahmedali', 7, 132, 'اور کہا جوکوئی نشانی تو ہمارے پاس لائے گا ہم پر اس کے ذریعہ سے جادو کرے سو ہم تجھ پر ہر گز ایمان نہ لائیں گے'),
  ('ur.ahmedali', 7, 133, 'پھر ہم نے ان پر طوفان اور ٹدی اور جوئیں اورمینڈک اور خون یہ سب کھلے کھلےمعجزے بھیجے پھر بھی انہوں نے تکبر ہی کیا اور لوگ گناہگار تھے'),
  ('ur.ahmedali', 7, 134, 'اور جب ان پر کوئی عذاب آتا تو کہتے اے موسیٰ ہمارے لیے اپنے رب سے دعا کر جس کا اس نے تجھ سے عہد کر رکھا ہے اگر تو نے ہم سے یہ عذاب دور کر دیا تو بے شک ہم تجھ پر ایمان لے آئيں گے اور بنی اسرائیل کو تیرے ساتھ بھیج دیں گے'),
  ('ur.ahmedali', 7, 135, 'پھر جب ہم نےان سے ایک مدت تک عذاب اٹھا لیا کہ انہیں اس مدت تک پہنچنا تھا اس وقت وہ عہد توڑ ڈالتے'),
  ('ur.ahmedali', 7, 136, 'پھر ہم نے ان سے بدلہ لیا پھر ہم نے انہیں دریا میں ڈبو دیا اس لیے کہ انہوں نے ہماری آیتوں کو جھٹلایا اور وہ ان سے غافل تھے'),
  ('ur.ahmedali', 7, 137, 'اور ہم نے ان لوگوں کو وارث کر دیا جو اس زمین کے مشرق و مغرب میں کمزور سمجھے جاتے تھے کہ جس میں ہم نے برکت رکھی ہے او رتیرے رب کا نیک وعدہ بنی اسرائیلک کے حق میں ان کے صبر کے باعث پورا ہو گیا اور فرعون اور اس کی قوم نے جو کچھ بنایا تھا ہم نے اسے تباہ کر دیا اور جو وہ اونچی عمارتیں بناتے تھے'),
  ('ur.ahmedali', 7, 138, 'اور ہم نے بنی اسرائیل کو دریا سے پار اتارا تو ایک ایسی قوم پر پہنچے جو اپنے بتوں کے پوجنے میں لگے ہوئے تھے کہا اے موسیٰ ہمیں بھی ایک ایسا معبود بنا دے جیسے ان کے معبود ہیں فرمایا بے شک تم لوگ جاہل ہو'),
  ('ur.ahmedali', 7, 139, 'یہ لوگ جس چیز میں لگے ہوئے ہیں وہ تباہ ہونے والی ہے اور جو وہ کر رہے ہیں وہ غلط ہے'),
  ('ur.ahmedali', 7, 140, 'کہا کیا الله کے سوا تمہارے لیے اور معبود بنا دوں حالانکہ اس نے تمہیں سارے جہاں پر فضیلت دی ہے'),
  ('ur.ahmedali', 7, 141, 'اور یا د کرو جب ہم نے تمہیں فرعون والوں سے نجات دی جو تمہیں برا عذاب دیتے تھے تمہارے بیٹوں کو مار ڈال دیتے تھے اور تمہاری عورتوں کو زندہ رکھتے تھے اور اس میں تمہارے رب کا بڑا احسان تھا'),
  ('ur.ahmedali', 7, 142, 'اور موسیٰ سے ہم نے تیس رات کا وعدہ کیا اور انہیں اور دس سے پورا کیا پھر تیرے رب کی مدت چالیس راتیں پوری ہو گئی اور موسیٰ نے اپنے بھائی ہارون سے کہا کہ میری قوم میں میرا جانشین رہ اور اصلاح کرتے رہو اور مفسدوں کی راہ پر مت چل'),
  ('ur.ahmedali', 7, 143, 'اور جب موسیٰ ہمارے مقرر کردہ وقت پر آئے اور ان کے رب نے ان سے باتیں کیں تو عرض کیا کہ اے میرے رب مجھے دکھا کہ میں تجھے دیکھوں فرمایا کہ تو مجھے ہر گز نہیں دیکھ سکتا لیکن تو پہاڑ کی طرف دیکھتا رہ اگر وہ اپنی جگہ پر ٹھہرا رہا تو تو مجھے دیکھ سکے گا پھر جب اس کے رب نے پہاڑ کی طرف تجلی کی تو اس کو ریزہ ریزہ کر دیا اور موسیٰ بے ہوش ہو کر گر پڑے پھر جب ہوش میں آئے تو عرض کی کہ تیری ذات پاک ہے میں تیری جانب میں توبہ کرتا ہوں اور میں سب سے پہلا یقین لانے والا ہوں'),
  ('ur.ahmedali', 7, 144, 'فرمایا اے موسیٰ میں نے پیغمبری اور ہم کلامی سے دوسرے لوگوں پر تجھے امتیاز دیا ہے جو کچھ میں نے تجھے عطا کیا ہے اسے لے لو اور شکر کرنے والوں میں سے ہو جاؤ'),
  ('ur.ahmedali', 7, 145, 'اور ہم نے اسے تختیوں پر ہر قسم کی نصیحت اور ہر چیز کی تفصیل لکھ دی سو انہیں مضبوطی سے پکڑ لے او راپنی قوم کو حکم کر کہ اس کی بہتر باتوں پر عمل کریں عنقریب میں تمہیں نافرمانوں کا ٹھکانہ دکھاؤں گا'),
  ('ur.ahmedali', 7, 146, 'پھر میں اپنی آیتوں سے انہیں پھیر دوں گا جو زمین میں نا حق تکبر کرتے ہیں اور اگر وہ ساری نشانیاں بھی دیکھ لیں تو بھی ایمان نہیں لائیں گے اور اگر ہدایت کا راستہ دیکھیں تو اسے اپنا راہ نہیں بنائیں گے یہ اس لیے ہے کہ انہوں نے ہماری آیتو ں کو جھٹلایا اور ان سے بے خبر رہے'),
  ('ur.ahmedali', 7, 147, 'اور جنھوں نے ہماری آیتوں کو اور آخرت کی ملاقات کو جھٹلایا ان کے اعمال ضائع ہو گئے انہیں وہی سزا دی جائے گی جو کچھ وہ کیا کرتے تھے'),
  ('ur.ahmedali', 7, 148, 'اور موسیٰ کی قوم نے اس کے بعد اپنے زیوروں سے بچھڑا بنا لیا ایک جسم تھا جس میں گائے کی آواز تھی کیا انہوں نے یہ نہ دیکھا کہ وہ ان سے بات بھی نہیں کرتا اور نہ ہی انہیں راہ بتاتا ہے اسے معبود بنا لیا اور وہ ظالم تھے'),
  ('ur.ahmedali', 7, 149, 'اور جب نادم ہوئے اور معلوم کیا کہ بیشک وہ گمراہ ہوگئے تھےتو کہنے لگے اگر ہمارے رب نے ہم پر رحم نہ کیا اور ہمیں نہ بخشا تو بے شک ہم نقصان پانے والوں میں سے ہوں گے'),
  ('ur.ahmedali', 7, 150, 'اور جب موسیٰ اپنی قو م کےی طرف غصہ اور رنج میں بھرے ہوئے واپس آئے تو فرمایا تم نے میرے بعد یہ بڑی نامعقول حرکت کی کیا تم نے اپنے رب کے حکم سے پہلے ہی جلد بازی کر لی اور تختیاں پھینک دیں اور اپنے بھائی کا سر پکڑ ا اسے پنی طرف کھینچنے لگا اس نے کہا کہ اے میری ماں کے بیٹے لوگوں نے مجھے کمزور سمجھا اور قریب تھے کہ مجھے مار ڈالیں سو مجھ پر دشمنوں کو نہ ہنسا اور مجھے گناہگار لوگو ں میں نہ ملا'),
  ('ur.ahmedali', 7, 151, 'کہا اے میرے رب مجھے اور میرے بھائی کو معاف فرما اور ہمیں اپنی رحمت میں داخل کر اور تو سب سے زيادہ رحم کرنے والا ہے'),
  ('ur.ahmedali', 7, 152, 'بے شک جنہوں نے بچھڑے کو معبود بنایا انہیں ان کے رب کی طرف سے غضب اور دنیا کی زندگی میں ذلت پہنچے گی او رہم بہتان باندھنے والوں کو یہی سزا دیتے ہیں'),
  ('ur.ahmedali', 7, 153, 'اور جنہوں نے برے کام کیے پھراس کے بعد توبہ کی اور ایمان لے آئے تو بے شک تیرا رب توبہ کے بعد البتہ بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 7, 154, 'اور جب موسیٰ کا غصہ ٹھنڈا ہوا تو اس نے تختیوں کو اٹھایا اور جو ان میں لکھا ہو ا تھا اس میں ان کے واسطے ہدایت اور رحمت تھی جو اپنے رب سے ڈرتے ہیں'),
  ('ur.ahmedali', 7, 155, 'اور موسیٰ نے اپنی قوم میں سے ستر مرد ہمارے وعدہ گا ہ پر لانے کے لیے چن لیے پھر جب انہیں زلزلہ نے پکڑ ا تو کہا اے میرے رب اگر تو چاہتا تو پہلے ہی انہیں ہلاک کر دیتا کیا تو ہمیں اس کام پر ہلاک کرتا ہے جو ہماری قوموں کے بیوقوفوں نے کیا یہ سب تیری آزمائش ہے جسے تو چاہے اس سے گمراہ کر دے اور جسے چاہے سیدھا رکھے تو ہی ہمارا کارساز ہے سو ہمیں بخش دے اور ہم پر رحم کر اور تو سب سے بہتر بخشنے والا ہے'),
  ('ur.ahmedali', 7, 156, 'او رہمارے لیے اس دنیا میں اور آخرت میں بھلائی لکھ ہم نے تیری طرف رجوع کیا فرمایا میں اپنا عذاب جسے چاہتا ہوں کرتا ہوں اور میری رحمت سب چیزوں سے وسیع ہے پس وہ رحمت ان کے لیے لکھوں گا جو ڈرتے ہیں اجور جو زکواة دیتے ہیں اور جو ہماری آیتوں پر ایمان لاتے ہیں'),
  ('ur.ahmedali', 7, 157, 'وہ لوگ جو اس رسول کی پیروی کرتے ہیں اور جو نبی امی ہے جسے اپنے ہاں تورات اور انجیل میں لکھا ہوا پاتے ہیں وہ ان کو نیکی کا حکم کرتا ہے اور برے کام سے روکتا ہے اوران کے لیے سب پاک چیزیں حلا ل کرتا ہے اور ان پر ناپاک چیزیں حرام کرتا ہے اور ان پر سے ان کے بوجھ اور وہ قیدیں اتارتا ہے جو ان پر تھیں سو جو لوگ اس پر ایمان لائے اور اس کی حمایت کی اور اسے مدد دی اور اس کے نور کے تابع ہو ئے جو اس کے ساتھ بھیجا گیا ہے یہی لوگ نجات پانے والے ہیں'),
  ('ur.ahmedali', 7, 158, 'کہہ دو اے لوگو تم سب کی طرف الله کا رسول ہوں جس کی حکومت آسمانوں اور زمین میں ہے اس کے سوا اور کوئی معبود نہیں وہی زندہ کرتا اور مارتا ہے پس الله پر ایمان لاؤ اوراس کے رسول نبی امی پر جو کہ الله پر اور اس کے سب کلاموں پر یقین رکھتا ہے اور اس کی پیروی کرو تاکہ تم راہ پاؤ'),
  ('ur.ahmedali', 7, 159, 'اور موسیٰ کی قوم میں سے ایک جماعت ہے جو حق کی راہ بتاتے ہیں اور اسی کے موافق انصاف کرتے ہیں'),
  ('ur.ahmedali', 7, 160, 'اور ہم نے انہیں جدا جدا کر دیا بارہ دادوں کی اولاد جو بڑی بڑی جماعتیں تھیں اور موسیٰ کو ہم نے حکم بھیجا جب اس کی قوم نے اس سے پانی مانگا کہ اپنی لاٹھی اس پتھر پر مار تو اس سے بارہ چشمے پھوٹ نکلے ہر قبیلہ نے اپنے گھاٹ پہچان لیا اور ہم نے ان پر ابر کا سایہ کیا اور ہم نے من و سلویٰ اتارا ہم نے جو ستھری چیزیں تمہیں دی ہیں وہ کھاؤ اور انہوں نے ہمارا کوئی نقصان نہیں کیا لیکن اپنا ہی نقصان کرتے تھے'),
  ('ur.ahmedali', 7, 161, 'اور جب انہیں حکم دیا گیا کہ تم اس بستی میں جا کر رہو اور وہاں جہاں سے تم چاہو کھاؤ اور زباں سے یہ کہتے جاؤ توبہ ہے اور دروازہ میں جھک کر داخل ہو ہم تمہاری غلطیاں معاف کر دیں گے اور نیکو کاروں کو اور زیادہ اجر دیں گے'),
  ('ur.ahmedali', 7, 162, 'سو ان میں سے ظالموں نے دوسرا لفظ اس کے سوا بدل دیا جو ان سے کہا گیا تھا پھر ہم نے ان پر آسمان سے عذاب بھیجا اس لیے کہ وہ ظلم کرتے تھے'),
  ('ur.ahmedali', 7, 163, 'اور ان سے اس بستی کا حال پوچھ جو دریا کے کنارے پر تھی جب ہفتہ کے معاملہ میں حد سے بڑھنے لگے جب ان کے پاس مچھلیاں ہفتہ کے دن پانی کے اوپر آنے لگیں اور جس دن ہفتہ نہ ہو تو نہ آتی تھیں ہم نے انہیں اس طرح آزمایا اس لیے کہ وہ نافرمان تھے'),
  ('ur.ahmedali', 7, 164, 'اور جب ان میں سے ایک جماعت نے کہا ان لوگوں کو کیوں نصیحت کرتے ہو جنہیں الله ہلاک کرنے والا ہے انہیں سخت عذاب دینے والا ہے انہوں نے کہا تمہارے رب کے روبر عذر کرنے کے لیے اور شاید کہ یہ ڈر جائیں'),
  ('ur.ahmedali', 7, 165, 'پھر جب وہ بھول گئے اس چیز کو جو انہیں سمجھائی گئی تھی توہم نے انہیں نجات دی جو برے کام سے منع کرتے تھے اور ظالموں کو ان کی نافرمانی کے باعث برے عذاب میں پکڑا'),
  ('ur.ahmedali', 7, 166, 'پھر جب وہ اس کام میں حد سے آگے بڑھ گئے جس سے روکے گئے تھے تو ہم نے حکم دیا کہ ذلیل ہونے والے بندر ہو جاؤ'),
  ('ur.ahmedali', 7, 167, 'اور یاد کر جب تیرے رب نے خبر دی تھی کہ یہودپر قیامت کے دن تک ایسے شخص کو ضرور بھیجتا رہے گا جو انہیں براعذاب دیتا رہے بے شک تیرا رب جلدی عذاب دینے والا ہے اور تحقیق وہ بحشنے والا مہربان ہے'),
  ('ur.ahmedali', 7, 168, 'اورہم نے انہیں ملک میں مختلف جماعتوں میں متفرق کر دیا بعضے ان میں سے نیک ہیں اور بعضے اور طرح کے اور ہم نے انہیں بھلائیوں اور برائیوں سے آزمایاتاکہ وہ لوٹ آئيں'),
  ('ur.ahmedali', 7, 169, 'پھر ان کے بعد ان کے ایسے جانشین ہوئے جو کتاب کے وارث بنے اس ادنیٰ زندگی کا مال و متاع لےلیتے ہیں اور کہتے ہیں کہ ہمیں معاف کر دیا جائے گا اور اگر ایسا ہی مال ان کے سامنے پھر آئے تو اسے لے لیتے ہیں کیا ان سے کتاب میں عہد نہیں لے لیا گیا تھا کہ الله کے سوا سچ کے اور کچھ نہ کہیں اور انہوں نے جو کچھ اس میں لکھا ہے پڑھا ہے اور آخرت کا گھر ڈرنے والوں کے لیے بہتر ہے کیا تم سمجھتے نہیں'),
  ('ur.ahmedali', 7, 170, 'اور جو لوگ کتاب کے پابند ہیں اور نماز کی پابندی کرتے ہیں بے شک ہم نیکی کرنے والوں کا ثواب ضائع نہیں کریں گے'),
  ('ur.ahmedali', 7, 171, 'اورجب ہم نے ان پر پہاڑ اٹھایا گویا کہ وہ سائبان ہے اور وہ ڈرے کہ ان پر گرے گا ہم نے کہا جو ہم نے تمہیں دیا ہے اسے مضبوطی سے پکڑو اور جو اس میں ہے اسے یاد رکھو تاکہ تم پرہیزگار ہو جاؤ'),
  ('ur.ahmedali', 7, 172, 'اور جب تیرے رب نے بنی آدم کی پیٹھوں سے ان کی اولاد کو نکالا اور ان سے ان کی جانوں پر اقرار کرایا کہ میں تمہارا رب نہیں ہوں انہوں نے کہا ہاں ہے ہم اقرار کرتے ہیں کبھی قیامت کے دن کہنے لگو کہ ہمیں تو اس کی خبر نہیں تھی'),
  ('ur.ahmedali', 7, 173, 'یا کہنے لگو ہمارے باپ دادا نے ہم سے پہلے شرک کیاتھا اور ہم ان کے بعد ان کی اولاد تھے کیاتو ہمیں اس کام پر ہلاک کرتا ہے جو گمراہوں نے کیا'),
  ('ur.ahmedali', 7, 174, 'اور اسی طرح ہم کھول کر آیتیں بیان کرتے ہیں تاکہ وہ لوٹ آئيں'),
  ('ur.ahmedali', 7, 175, 'اور انہیں اس شخص کا حال سنا دے جسے ہم نے اپنی آیتیں دی تھیں پھر وہ ان سے نکل گیا پھر اس کے پیچھے شیطان لگا تو وہ گمراہوں میں سے ہو گیا'),
  ('ur.ahmedali', 7, 176, 'اور اگر ہم چاتے تو ان کی آیتو ں کی برکت سے اس کا رتبہ بلند کرتے لیکن وہ دنیا کی طرف مائل ہو گیا اور اپنی خواہش کے تابع ہو گیا اس کا تو ایسا حال ہے جیسے کتا اس پر تو سختی کرے تو بھی ہانپے اور اگر چھوڑ دے تو بھی ہانپے یہ ان لوگوں کی مثال ہے جنہوں نے ہماری آیتوں کو جھٹلایا سو یہ حالات بیان کر دے شاید کہ وہ فکر کریں'),
  ('ur.ahmedali', 7, 177, 'جنہوں نے ہماری آیتوں کو جھٹلایا ان کی بری مثال ہے اور وہ اپنا ہی نقصان کرتے رہے'),
  ('ur.ahmedali', 7, 178, 'جسے الله تعالیٰ ہدایت دے وہی راہ پاتا ہے اور جسے گمراہ کر دےپس وہی لوگ نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 7, 179, 'اور ہم نے دوزخ کے لیے بہت سے جن اور آدمی پیدا کیے ہیں ان کے دل ہیں کہ ان سے سمجھتے نہیں اور آنکھیں ہیں کہ ان سے دیکھتے نہیں اور کان ہیں کہ ان سے سنتے نہیں وہ ایسے ہیں جیسے چوپائے بلکہ ان سے بھی گمراہی میں زیادہ ہیں یہی لوگ غافل ہیں'),
  ('ur.ahmedali', 7, 180, 'اور سب اچھے نام الله ہی کے لیے ہیں سو اسے انہیں نامو ں سے پکارو اور چھوڑ دو ان کو جو الله کے نامو ں میں کجروی اختیار کرتے ہیں وہ اپنے کیے کی سزا پا کر رہیں گے'),
  ('ur.ahmedali', 7, 181, 'اور ان لوگوں میں سےجنہیں ہم نے پیدا کیا ایک جماعت ہے جو سچی راہ بتاتی ہے اور اسی کے موافق انصاف کرتے ہیں'),
  ('ur.ahmedali', 7, 182, 'اور جنہوں نے ہماری آیتوں کو جھٹلایا ہم انہیں آہستہ آہستہ پکڑیں گے ایسی جگہ سے جہاں انہیں خبر بھی نہ ہو گی'),
  ('ur.ahmedali', 7, 183, 'اور میں انہیں مہلت دوں گا بے شک میری تدبیر بڑی مضبوط ہے'),
  ('ur.ahmedali', 7, 184, 'کیا انہوں نے غور نہیں کیاکہ ان کے ساتھی کو جنوں تو نہیں ہے وہ تو کھلم کھلا ڈرانے والا ہے'),
  ('ur.ahmedali', 7, 185, 'اور کیا انہوں نے آسمان اور زمین کی سلطنت کو نہیں دیکھا اور دوسری چیزوں کو جو الله نے پیدا کی ہیں اور یہ کہ ممکن ہے کہ ان کی اجل قریب ہی ہو پھرقرآن کے بعد کس بات پر یہ لوگ ایمان لائيں گے'),
  ('ur.ahmedali', 7, 186, 'جسے الله گمراہ کر دے اسے کوئی راہ دکھانے والا نہیں اور انہیں الله چھوڑ دیتا ہے کہ اپنی سرکشی میں حیران پھیر یں'),
  ('ur.ahmedali', 7, 187, 'قیامت کے متعلق تجھ سے پوچھتے ہیں کہ اس کی آمد کا کونسا وقت ہے کہہ دو اس کی خبر تو میرے رب ہی کے ہاں ہے وہی اس کے وقت پر ظاہر کر دکھائے گا وہ آسمانو ں اور زمین میں بھاری بات ہے وہ تم پر محض اچانک آجائے گی تجھ سے پوچھتے ہیں گویا کہ تو اس کی تلاش میں لگا ہوا ہے کہہ دو اس کی خبر خاص الله ہی کے ہاں ہے لیکن اکثر لوگ نہیں سمجھتے'),
  ('ur.ahmedali', 7, 188, 'کہہ دو میں اپنی ذات کے نفع و نقصان کا بھی مالک نہیں مگرجو الله چاہے اور اگر میں غیب کی بات جان سکتا تو بہت کچھ بھلائیاں حاصل کر لیتا اور مجھے تکلیف نہ پہنچتی میں تو محض ڈرانے والا اور خوشخبری دینے والا ہوں ان لوگوں کو جو ایمان دار ہیں'),
  ('ur.ahmedali', 7, 189, 'وہ وہی ہے جس نے تمہیں ایک جان سے پیدا کیا اور اسی سے اس کا جوڑ بنایا تاکہ اس سے آرام پائے پھر جب میاں نے بیوی سے ہم بستری کی تو اس کو ہلکا سا حمل رہ گیا پھر اسے لیے پھرتی رہی پھر جب وہ بوجھل ہو گئی تب دونوں میاں بیوی نے الله سے جو ان کا مالک ہے دعا کی اگر آپ نے ہمیں صحیح سالم اولاد دے دی تو ہم ضرور شکر گزار ہوں گے'),
  ('ur.ahmedali', 7, 190, 'پھر جب الله نے انکو صحیح سالم اولاد دی تو الله کی دی ہوئی چیزوں میں وہ دونوں الله کا شریک بنانے لگے سو الله ان کے شرک سے پاک ہے'),
  ('ur.ahmedali', 7, 191, 'کیا ایسوں کو شریک بناتے ہیں جو کچھ بھھی نہیں بنا سکتے اور وہ خود بنائے ہوئے ہیں'),
  ('ur.ahmedali', 7, 192, 'اور نہ وہ ان کی مدد کر سکتے ہیں اور نہ اپنی ہی مدد کر سکتے ہیں'),
  ('ur.ahmedali', 7, 193, 'اور اگر تم انہیں راستہ کی طرف بلاؤ تو تمہاری تابعداری نہ کریں برابر ہے کہ تم انہیں پکارو یا چپکے رہو'),
  ('ur.ahmedali', 7, 194, 'بے شک جنہیں تم الله کے سوا پکارتے ہو وہ تمہاری طرح کے بندے ہیں پھر انہیں پکار کر دیکھو پھر چاہے کہ وہ تمہاری پکار کو قبول کریں اگر تم سچے ہو'),
  ('ur.ahmedali', 7, 195, 'کیا ان کے پاؤں ہیں جن سے وہ چلیں یا ان کے ہاتھ ہیں جن سے وہ پکڑیں یا ان کی آنکھیں ہیں جن سے وہ دیکھیں یا ان کے کان ہیں جن سے وہ سنیں کہ تو اپنے شریکوں کو پکارو پھر میری برائی کی تدبیر کرو پھر مجھے ذرا مہلت نہ دو'),
  ('ur.ahmedali', 7, 196, 'بےشک میرا حمایتی الله ہے جس نے کتاب نازل فرمائی اور وہ نیکو کاروں کی حمایت کرتا ہے'),
  ('ur.ahmedali', 7, 197, 'اور جنہیں تم پکارتے ہو وہ تمہاری مدد نہیں کر سکتے اور نہ اپنی جان کی مدد کر سکتے ہیں'),
  ('ur.ahmedali', 7, 198, 'اور اگر تم انہیں راستہ کی طرف پکارو تو وہ کچھ نہیں سنیں گے اور تو دیکھے گا کہ وہ تیری طرف دیکھتے ہیں حالانکہ وہ کچھ نہیں دیکھتے'),
  ('ur.ahmedali', 7, 199, 'درگزر کر اور نیکی کا حکم دے اور جاہلوں سے الگ رہ'),
  ('ur.ahmedali', 7, 200, 'اور اگر تجھے کوئی وسوسہ شیطان کی طرف سے آئے تو الله کی پناہ مانگ لیا کر بے شک وہ سننے والا جاننے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 7, 201, 'بے شک جو لوگ خدا سے ڈرتے ہیں جب انہیں کوئي خطرہ شیطان کی طرف سے آتا ہے تو وہ یاد میں لگ جاتے ہیں پھر اچانک ان کیآنکھیں کھل جاتی ہیں'),
  ('ur.ahmedali', 7, 202, 'اور جو شیاطین کے تابع ہیں وہ انہیں گمراہی میں کھینچے چلے جاتے ہیں پھر وہ باز نہیں آتے'),
  ('ur.ahmedali', 7, 203, 'اور جب توان کے پاس کوئی معجزہ نہیں لاتا تو کہتے ہیں کہ تو فلاں معجزہ کیوں نہیں لایا کہہ دو میں اس کا اتباع کرتا ہوں جو مجھ پر میرے رب کی طرف سے بھیجا جاتا ہے یہ تمہارے رب کی طرف سے بہت سی دلیلیں ہیں اور ہدایت اور رحمت ہے ان لوگو ں کے لیے جو ایمان دار ہیں'),
  ('ur.ahmedali', 7, 204, 'اورجب قرآن پڑھا جاتا جائے تو اسے کان لگا کر سنو اور چپ رہو تاکہ تم پر رحم کیا جائے'),
  ('ur.ahmedali', 7, 205, 'اوراپنے رب کو اپنے دل میں عاجزی کرتا ہوا اور ڈرتاہوا یاد کرتا رہ اور صبح اور شام بلند آواز کی نسبت ہلکی آواز سے اور غافلوں سے نہ ہو'),
  ('ur.ahmedali', 7, 206, 'بے شک جو تیرے رب کے ہاں ہیں وہ اس کی بندگی سے تکبر نہیں کرتے اور اس کی پاک ذات کو یاد کرتے ہیں اور اسی کو سجدہ کرتے ہیں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 7, 1, 'Elif, Lam, Mim, Sad.'),
  ('tr.diyanet', 7, 2, 'Sana bir Kitap indirildi. Onunla insanları uyarman ve inananlara öğüt vermen için kalbine bir darlık gelmesin.'),
  ('tr.diyanet', 7, 3, 'Rabbinizden size indirilen Kitap\'a uyun, O\'ndan başka dostlar edinerek onlara uymayın. Pek az öğüt dinliyorsunuz.'),
  ('tr.diyanet', 7, 4, 'Biz nice kentleri yok etmişizdir; geceleyin veya gündüz uykularında iken baskınımıza uğramışlardır.'),
  ('tr.diyanet', 7, 5, 'Baskınımıza uğradıklarında, sözleri, "Gerçekten biz haksızdık" demekten ibaret kalmıştır.'),
  ('tr.diyanet', 7, 6, 'And olsun ki, kendilerine peygamber gönderilenlere soracağız, peygamberlere de soracağız.'),
  ('tr.diyanet', 7, 7, 'And olsun ki, yaptıklarını kendilerine bir bir anlatacağız, zira onlardan uzak değildik.'),
  ('tr.diyanet', 7, 8, 'Gerçek tartı kıyamet günündedir. Tartıları ağır gelenler, işte onlar kurtulanlardır.'),
  ('tr.diyanet', 7, 9, 'Tartıları hafif gelenler, ayetlerimize yaptıkları haksızlıklardan ötürü kendilerini mahvetmiş olanlardır.'),
  ('tr.diyanet', 7, 10, 'Sizi yeryüzünde yerleştirdik ve orada size geçimlikler yarattık. Öyleyken pek az şükrediyorsunuz.'),
  ('tr.diyanet', 7, 11, 'And olsun ki, sizi yarattık, sonra şekil verdik, sonra meleklere, "Adem\'e secde edin" dedik; İblis\'ten başka hepsi secde etti, o secde edenlerden olmadı.'),
  ('tr.diyanet', 7, 12, 'Allah, "Sana emrettiğim halde, seni secdeden alıkoyan nedir?" dedi, "Beni ateşten onu çamurdan yarattın, ben ondan üstünüm" cevabını verdi.'),
  ('tr.diyanet', 7, 13, 'Ona, "İn oradan, orada büyüklenmek sana düşmez, defol, sen alçağın birisin" dedi.'),
  ('tr.diyanet', 7, 14, 'Ona, "İnsanların tekrar dirilecekleri güne kadar beni ertele" dedi.'),
  ('tr.diyanet', 7, 15, 'Allah; "Sen erteye bırakılanlardansın" dedi.'),
  ('tr.diyanet', 7, 16, '"Beni azdırdığın için, and olsun ki, Senin doğru yolun üzerinde onlara karşı duracağım; sonra önlerinden, ardlarından, sağ ve sollarından onlara sokulacağım; çoğunu Sana şükreder bulamayacaksın" dedi.'),
  ('tr.diyanet', 7, 17, '"Beni azdırdığın için, and olsun ki, Senin doğru yolun üzerinde onlara karşı duracağım; sonra önlerinden, ardlarından, sağ ve sollarından onlara sokulacağım; çoğunu Sana şükreder bulamayacaksın" dedi.'),
  ('tr.diyanet', 7, 18, 'Allah, "Yerilmiş ve kovulmuşsun, oradan defol; and olsun ki insanlardan sana kim uyarsa, hepinizi cehenneme dolduracağım" dedi.'),
  ('tr.diyanet', 7, 19, '"Ey Adem! Sen ve eşin cennette kalın ve istediğiniz yerden yiyin, yalnız şu ağaca yaklaşmayın yoksa zalimlerden olursunuz."'),
  ('tr.diyanet', 7, 20, 'Şeytan, ayıp yerlerini kendilerine göstermek için onlara fısıldadı: "Rabbinizin sizi bu ağaçtan menetmesi melek olmanız veya burada temelli kalmanızı önlemek içindir."'),
  ('tr.diyanet', 7, 21, '"Doğrusu ben size öğüt verenlerdenim" diye ikisine yemin etti.'),
  ('tr.diyanet', 7, 22, 'Böylece onların yanılmalarını sağladı. Ağaçtan meyve tattıklarında kendilerine ayıp yerleri göründü, cennet yapraklarından oralarına örtmeğe koyuldular. Rableri onlara, "Ben sizi o ağaçtan menetmemiş miydim? Şeytanın size apaçık bir düşman olduğunu söylememiş miydim?" diye seslendi.'),
  ('tr.diyanet', 7, 23, 'Her ikisi, "Rabbimiz! Kendimize yazık ettik; bizi bağışlamaz ve bize merhamet etmezsen biz kaybedenlerden oluruz" dediler.'),
  ('tr.diyanet', 7, 24, '"Birbirinize düşman olarak inin, siz yeryüzünde bir müddet için yerleşip geçineceksiniz."'),
  ('tr.diyanet', 7, 25, '"Orada yaşar, orada ölür ve oradan dirilip çıkarılırsınız" dedi.'),
  ('tr.diyanet', 7, 26, 'Ey İnsanoğulları! Ayıp yerlerinizi örtecek giyimlikle sizi süsleyecek elbiseler gönderdik. Takva örtüsü ise bunlardan daha hayırlıdır. Allah\'ın bu ayetleri öğüt almanız içindir.'),
  ('tr.diyanet', 7, 27, 'Ey İnsanoğulları! Şeytan, ayıp yerlerini kendilerine göstermek için elbiselerini soyarak ananızı babanızı cennetten çıkardığı gibi sizi de şaşırtmasın. Sizin onları görmediğiniz yerlerden o ve taraftarları sizi görürler. Biz şeytanları, inanmayanlara dost kılarız.'),
  ('tr.diyanet', 7, 28, 'Onlar bir fenalık yaptıkları zaman, "Babalarımızı bu yolda bulduk, Allah da bize bunu emretti" derler. De ki: "Allah fenalığı emretmez. Bilmediğiniz şeyi Allah\'a karşı mı söylüyorsunuz?"'),
  ('tr.diyanet', 7, 29, 'De ki: "Rabbim adaleti emretti; her secde yerinde yüzünüzü O\'na doğrultun; dinde samimi olarak O\'na yalvarın. Sizi yarattığı gibi yine O\'na döneceksiniz."'),
  ('tr.diyanet', 7, 30, 'Allah insanlardan bir takımını doğru yola eriştirdi, fakat bir takımı da sapıklığı haketti, çünkü bunlar Allah\'ı bırakıp şeytanları dost edinmiş ve kendilerini doğru yolda sanmışlardı.'),
  ('tr.diyanet', 7, 31, 'Ey Ademoğulları! Her mescide güzel elbiselerinizi giyinerek gidin; yiyin için fakat israf etmeyin, çünkü Allah müsrifleri sevmez.'),
  ('tr.diyanet', 7, 32, '"Allah\'ın kulları için yarattığı ziynet ve temiz rızıkları haram kılan kimdir?" "Bunlar, dünya hayatında inananlarındır, kıyamet gününde de yalnız onlar içindir" de. Bilen kimseler için ayetlerimizi böylece uzun uzun açıklıyoruz.'),
  ('tr.diyanet', 7, 33, 'De ki: "Rabbim sadece, açık ve gizli fenalıkları, günahı, haksız yere tecavüzü, hakkında hiçbir delil indirmediği şeyi Allah\'a ortak koşmanızı, Allah\'a karşı bilmediğiniz şeyleri söylemenizi haram kılmıştır."'),
  ('tr.diyanet', 7, 34, 'Her ümmet için belirli bir süre vardır; vakitleri dolunca ne bir saat gecikebilir ne de öne geçebilirler.'),
  ('tr.diyanet', 7, 35, 'Ey Adem oğulları! Size aranızdan ayetlerimizi okuyan peygamberler geldiğinde, onların bildirdiklerine karşı gelmekten sakınan ve gidişini düzeltenlere, işte onlara korku yoktur ve onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 7, 36, 'Ayetlerimizi yalanlayıp onlara karşı büyüklük taslayanlara gelince, işte onlar cehennemliklerdir, orada temelli kalacaklardır.'),
  ('tr.diyanet', 7, 37, 'Allah\'a karşı yalan uyduran veya ayetlerini yalan sayandan daha zalim kimdir? Kitap\'daki payları kendilerine erişecek olanlar onlardır. Elçilerimiz canlarını almak üzere geldiklerinde onlara, "Allah\'tan başka taptıklarınız nerede?" deyince, "Bizi koyup kaçtılar" derler, böylece inkarcı olduklarına kendi aleyhlerine şahidlik ederler.'),
  ('tr.diyanet', 7, 38, 'Allah, " Sizden önce geçmiş cin ve insan ümmetleriyle beraber ateşe girin" der. Her ümmet girdikçe kendi yoldaşına lanet eder. Hepsi birbiri ardından cehennemde toplanınca, sonrakiler öncekiler için, "Rabbimiz! Bizi sapıtanlar işte bunlardır, onlara ateş azabını kat kat ver" derler, Allah, "Hepsinin kat kattır, ama bilmezsiniz" der.'),
  ('tr.diyanet', 7, 39, 'Öncekiler sonrakilere, "Sizin bizden bir üstünlüğünüz yoktu, kazandığınıza karşılık azabı tadın" derler.'),
  ('tr.diyanet', 7, 40, 'Doğrusu ayetlerimizi yalan sayıp, onlara karşı büyüklük taslayanlara, göğün kapıları açılmaz; deve iğnenin deliğinden geçmedikçe cennete de giremezler. Suçluları böyle cezalandırırız.'),
  ('tr.diyanet', 7, 41, 'Onlar için cehennemden bir yatak ve üstlerine de örtüler vardır. Zalimleri böyle cezalandırırız.'),
  ('tr.diyanet', 7, 42, 'İnanan ve yararlı iş işleyenler ki kişiye ancak gücünün yeteceği kadar yükleriz işte cennetlikler onlardır, orada temelli kalacaklardır.'),
  ('tr.diyanet', 7, 43, 'Cennette altlarından ırmaklar akarken gönüllerinden kini çıkarıp atarız. "Bizi buraya eriştiren Allah\'a hamdolsun. Eğer Allah bizi doğru yola iletmeseydi, biz doğru yolu bulamazdık. And olsun ki Rabbimizin peygamberleri bize gerçeği getirmiştir" derler. Onlara, "İşlediğinize karşılık işte mirasçısı olduğunuz cennet" diye seslenilir.'),
  ('tr.diyanet', 7, 44, 'Cennetlikler, cehennemliklere: "Biz Rabbimizin bize vadettiğini gerçek bulduk, Rabbinizin size de vadettiğini gerçek buldunuz mu?" diye seslenirler, "Evet" derler. Aralarında bir münadi, "Allah\'ın laneti Allah yolundan alıkoyan, o yolun eğriliğini isteyen ve ahireti inkar eden zalimleredir" diye seslenir.'),
  ('tr.diyanet', 7, 45, 'Cennetlikler, cehennemliklere: "Biz Rabbimizin bize vadettiğini gerçek bulduk, Rabbinizin size de vadettiğini gerçek buldunuz mu?" diye seslenirler, "Evet" derler. Aralarında bir münadi, "Allah\'ın laneti Allah yolundan alıkoyan, o yolun eğriliğini isteyen ve ahireti inkar eden zalimleredir" diye seslenir.'),
  ('tr.diyanet', 7, 46, 'İki taraf arasında bir perde ve burçlar üzerinde her iki tarafı da simalarından tanıyan adamlar vardır; cennetliklere, "Size selam olsun" derler. Bunlar henüz girmeyen fakat cenneti uman kimselerdir.'),
  ('tr.diyanet', 7, 47, 'Gözleri cehennemlikler yönüne çevrilince: "Rabbimiz! Bizi zalimlerle beraber bulundurma" derler.'),
  ('tr.diyanet', 7, 48, 'Burçlarda olanlar, simalarından tanıdıkları adamlara; Topluluğunuz, topladığınız mal ve büyüklük taslamalarınız size fayda vermedi. Allah\'ın rahmetine erdirmeyeceğine yemin ettikleriniz bunlar mıydı? Oysa Allah onlara şöyle der: "Cennete girin, size korku yoktur, sizler mahzun da olmayacaksınız."'),
  ('tr.diyanet', 7, 49, 'Burçlarda olanlar, simalarından tanıdıkları adamlara; Topluluğunuz, topladığınız mal ve büyüklük taslamalarınız size fayda vermedi. Allah\'ın rahmetine erdirmeyeceğine yemin ettikleriniz bunlar mıydı? Oysa Allah onlara şöyle der: "Cennete girin, size korku yoktur, sizler mahzun da olmayacaksınız."'),
  ('tr.diyanet', 7, 50, 'Cehennemlikler cennetliklere, "Bize biraz su veya Allah\'ın size verdiği rızıktan gönderin" diye seslenirler, onlar da, "Doğrusu Allah dinlerini alay ve eğlenceye alan, dünya hayatına aldanan inkarcılara ikisini de haram etmiştir" derler. Bugünle karşılaşacaklarını unuttukları, ayetlerimizi bile bile inkar ettikleri gibi biz de onları unutuyoruz.'),
  ('tr.diyanet', 7, 51, 'Cehennemlikler cennetliklere, "Bize biraz su veya Allah\'ın size verdiği rızıktan gönderin" diye seslenirler, onlar da, "Doğrusu Allah dinlerini alay ve eğlenceye alan, dünya hayatına aldanan inkarcılara ikisini de haram etmiştir" derler. Bugünle karşılaşacaklarını unuttukları, ayetlerimizi bile bile inkar ettikleri gibi biz de onları unutuyoruz.'),
  ('tr.diyanet', 7, 52, 'And olsun ki Biz onlara bir Kitap getirdik, inanan bir millet için yol gösterici ve rahmet olarak onu bilgiyle uzun uzun açıkladık.'),
  ('tr.diyanet', 7, 53, 'Kitap\'ın haber verdiği sonuçtan başka bir şey mi bekliyorlar? Sonuç gelip çattığı gün, önceleri onu unutmuş olanlar, "Rabbimizin peygamberleri şüphesiz bize gerçeği getirmişti, şimdi bize şefaat etsin, yahut geriye çevrilsek de işlediklerimizin başka türlüsünü işlesek" derler. Doğrusu kendilerini mahvetmişlerdir, uydurdukları şeyler onları koyup kaçmışlardır.'),
  ('tr.diyanet', 7, 54, 'Rabbiniz, gökleri ve yeri altı günde yaratan ve sonra arşa hükmeden, gündüzü durmadan kovalayan gece ile bürüyen; güneşi, ayı, yıldızları, hepsini buyruğuna baş eğdirerek var eden Allah\'tır. Bilin ki yaratma da emir de O\'nun hakkıdır. Alemlerin Rabbiolan Allah Yüce\'dir.'),
  ('tr.diyanet', 7, 55, 'Rabbinize gönülden ve gizlice yalvarın. Doğrusu O aşırı gidenleri sevmez.'),
  ('tr.diyanet', 7, 56, 'Düzeltilmişken, yeryüzünde bozgunculuk yapmayın. Allah\'a korkarak ve umutla yalvarın. Doğrusu Allah\'ın rahmeti iyi davrananlara yakındır.'),
  ('tr.diyanet', 7, 57, 'Rahmetinin önünde, müjdeci olarak rüzgarları gönderen Allah\'tır. Rüzgarlar, yağmur yüklü bulutları taşıdığında, onu ölü bir memlekete gönderir, su indirir ve onunla her türlü ürünü yetiştiririz; ölüleri de bunun gibi diriltip, çıkarırız; belki bundan ibret alırsınız.'),
  ('tr.diyanet', 7, 58, 'İyi toprak Rabbinin izniyle bitki verir, çorak toprak kavruk bitki çıkarır. Şükredecek millet için böylece ayetleri yerli yerince açıklarız.'),
  ('tr.diyanet', 7, 59, 'And olsun ki Nuh\'u milletine gönderdik. "Ey milletim! Allah\'a kulluk edin, O\'ndan başka tanrınız yoktur; doğrusu sizin için büyük günün azabından korkuyorum" dedi.'),
  ('tr.diyanet', 7, 60, 'Milletinin ileri gelenleri: "Biz senin apaçık sapıklıkta olduğunu görüyoruz" dediler.'),
  ('tr.diyanet', 7, 61, '"Ey milletim! Bende bir sapıklık yoktur, ancak ben Alemlerin Rabbinin peygamberiyim, Rabbimin sözlerini size bildiriyor, öğüt veriyorum. Sizin bilmediğinizi Allah katından ben biliyorum. Sakınmanızı ve böylece merhamete uğramanızı sağlamak üzere sizi uyarmak için aranızdan biri vasıtasıyla Rabbinizden size haber gelmesine mi şaşıyorsunuz?" dedi.'),
  ('tr.diyanet', 7, 62, '"Ey milletim! Bende bir sapıklık yoktur, ancak ben Alemlerin Rabbinin peygamberiyim, Rabbimin sözlerini size bildiriyor, öğüt veriyorum. Sizin bilmediğinizi Allah katından ben biliyorum. Sakınmanızı ve böylece merhamete uğramanızı sağlamak üzere sizi uyarmak için aranızdan biri vasıtasıyla Rabbinizden size haber gelmesine mi şaşıyorsunuz?" dedi.'),
  ('tr.diyanet', 7, 63, '"Ey milletim! Bende bir sapıklık yoktur, ancak ben Alemlerin Rabbinin peygamberiyim, Rabbimin sözlerini size bildiriyor, öğüt veriyorum. Sizin bilmediğinizi Allah katından ben biliyorum. Sakınmanızı ve böylece merhamete uğramanızı sağlamak üzere sizi uyarmak için aranızdan biri vasıtasıyla Rabbinizden size haber gelmesine mi şaşıyorsunuz?" dedi.'),
  ('tr.diyanet', 7, 64, 'Onu yalanladılar; biz de onu ve gemide beraberinde olanları kurtardık, ayetlerimizi yalan sayanları suda boğduk, çünkü onlar kör bir milletti.'),
  ('tr.diyanet', 7, 65, 'Ad milletine de, kardeşleri Hud\'u gönderdik "Ey milletim! Allah\'a kulluk edin, O\'ndan başka tanrınız yoktur, karşı gelmekten sakınmaz mısınız?" dedi.'),
  ('tr.diyanet', 7, 66, 'Milletinin inkarcı ileri gelenleri, "Biz senin beyinsiz olduğunu görüyor ve seni yalancılardan sanıyoruz" dediler.'),
  ('tr.diyanet', 7, 67, '"Ey milletim! Ben beyinsiz değil, Alemlerin Rabbinin peygamberiyim.'),
  ('tr.diyanet', 7, 68, 'Size Rabbimin sözlerini bildiriyorum. Ben sizin için güvenilir bir öğütçüyüm; sizi uyarmak üzere, aranızdan bir adam vasıtasiyle Rabbinizden size bir haber gelmesine mi şaşıyorsunuz? Allah\'ın sizi Nuh\'un milleti yerine getirdiğini ve vücutça da onlardan üstün kıldığını hatırlayın, başarıya erişebilmeniz için Allah\'ın nimetlerini anın" dedi.'),
  ('tr.diyanet', 7, 69, 'Size Rabbimin sözlerini bildiriyorum. Ben sizin için güvenilir bir öğütçüyüm; sizi uyarmak üzere, aranızdan bir adam vasıtasiyle Rabbinizden size bir haber gelmesine mi şaşıyorsunuz? Allah\'ın sizi Nuh\'un milleti yerine getirdiğini ve vücutça da onlardan üstün kıldığını hatırlayın, başarıya erişebilmeniz için Allah\'ın nimetlerini anın" dedi.'),
  ('tr.diyanet', 7, 70, '"Bize yalnız Allah\'a kulluk etmemizi, babalarımızın taptıklarını bırakmamızı söylemek için mi geldin? Doğru sözlülerden isen haydi bizi tehdit ettiğin azaba uğrat" dediler.'),
  ('tr.diyanet', 7, 71, '"Hiç şüphesiz artık Rabbinizin azab ve öfkesini hakettiniz. Allah\'ın hiçbir delil indirmediği, isimlerini de siz ve babalarınızın koyduğu putlar hakkında mı benimle tartışıyorsunuz? Bekleyin, doğrusu ben de sizinle beraber bekleyenlerdenim" dedi.'),
  ('tr.diyanet', 7, 72, 'Biz, rahmetimizle, Hud\'u ve beraberinde bulunanları kurtardık, ayetlerimizi yalan sayarak inanmayanların kökünü kestik.'),
  ('tr.diyanet', 7, 73, 'Semud milletine de kardeşleri Salih\'i gönderdik. "Ey milletim! Allah\'a kulluk edin, O\'ndan başka tanrınız yoktur. Rabbinizden size bir belge geldi: Allah\'ın bu dişi devesi size bir delildir, onu bırakın, Allah\'ın toprağında otlasın; ona kötülük etmeyin, yoksa can yakıcı azaba uğrarsınız.'),
  ('tr.diyanet', 7, 74, 'Allah\'ın sizi Ad milleti yerine getirdiğini, ovalarında köşkler kurup dağlarında kayadan evler yonttuğunuz yeryüzünde yerleştirdiğini hatırlayın; Allah\'ın nimetlerini anın, yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın" dedi.'),
  ('tr.diyanet', 7, 75, 'Milletinin büyüklük taslayan ileri gelenleri, aralarından iman eden ve bu sebeple hor gördükleri kimselere, "Salih\'in Rabbi tarafından gönderildiğini sahiden biliyor musunuz?" dediler, onlar da, "Doğrusu biz onunla gönderilene inanıyoruz" dediler.'),
  ('tr.diyanet', 7, 76, 'Büyüklük taslayanlar, "Sizin inandığınızı biz inkar ediyoruz" dediler ve dişi deveyi kesip devirdiler; Rablerinin buyruğuna baş kaldırdılar, "Ey Salih, eğer sen peygambersen bizi tehdit ettiğin azaba uğrat bakalım" dediler.'),
  ('tr.diyanet', 7, 77, 'Büyüklük taslayanlar, "Sizin inandığınızı biz inkar ediyoruz" dediler ve dişi deveyi kesip devirdiler; Rablerinin buyruğuna baş kaldırdılar, "Ey Salih, eğer sen peygambersen bizi tehdit ettiğin azaba uğrat bakalım" dediler.'),
  ('tr.diyanet', 7, 78, 'Bu yüzden onları bir sarsıntı tuttu ve oldukları yerde diz üstü çöküverdiler.'),
  ('tr.diyanet', 7, 79, 'Salih de onlardan yüz çevirdi ve "Ey milletim! And olsun ki ben size Rabbimin sözünü bildirmiş ve öğüt vermiştim; fakat siz öğüt verenleri sevmiyorsunuz" dedi.'),
  ('tr.diyanet', 7, 80, 'Lut\'u da gönderdik, milletine "Dünyalarda hiç kimsenin sizden önce yapmadığı bir hayasızlığı mı yapıyorsunuz? Siz kadınları bırakıp erkeklere yaklaşıyorsunuz, doğrusu çok aşırı giden bir milletsiniz" dedi.'),
  ('tr.diyanet', 7, 81, 'Lut\'u da gönderdik, milletine "Dünyalarda hiç kimsenin sizden önce yapmadığı bir hayasızlığı mı yapıyorsunuz? Siz kadınları bırakıp erkeklere yaklaşıyorsunuz, doğrusu çok aşırı giden bir milletsiniz" dedi.'),
  ('tr.diyanet', 7, 82, 'Milletinin cevabı sadece, "Onları kasabanızdan çıkarın, güya onlar temiz kalmaya uğraşan insanlarmış" demek oldu.'),
  ('tr.diyanet', 7, 83, 'Bunun üzerine Lut\'u ve taraftarlarını kurtardık; yalnız karısı, geride kalıp helake uğrayanlardan oldu.'),
  ('tr.diyanet', 7, 84, 'Geriye kalanların üzerine öyle bir yağmur yağdırdık ki! Suçluların sonunun nasıl olduğuna bir bak!'),
  ('tr.diyanet', 7, 85, 'Medyen halkına da kardeşleri Şuayb\'ı gönderdik, onlara şöyle dedi: "Ey milletim! Allah\'a kulluk edin, O\'ndan başka tanrınız yoktur. Rabbinizden size bir belge geldi. Ölçü ve tartıyı tam yapın, insanların eşyasını eksik vermeyin, düzelttikten sonra yeryüzünde bozgunculuk etmeyin; inanıyorsanız bilin ki, bunlar sizin için hayırlıdır."'),
  ('tr.diyanet', 7, 86, '"Allah\'a inananları yolundan alıkoyup ve o yolun eğriliğini dileyerek tehdit edip her yolda pusu kurup oturmayın. Azken, Allah\'ın sizi çoğalttığını hatırlayın; bozguncuların sonunun nasıl olduğuna bir bakın."'),
  ('tr.diyanet', 7, 87, '"İçinizde mademki benimle gönderilene inanan bir topluluk ve inanmayan bir topluluk var, o halde Allah\'ın aramızda hükmünü bildirmesine kadar sabredin. Allah hükmedenlerin en iyisidir."'),
  ('tr.diyanet', 7, 88, 'Milletinin büyüklük taslayan ileri gelenleri, "Ey Şuayb! Ya dinimize dönersiniz ya da, and olsun ki seni ve inananları seninle beraber kentimizden çıkarırız" dediler. Şuayb, onlara: "İstemezsek de mi? Allah bizi dininizden kurtardıktan sonra ona dönecek olursak, doğrusu Allah\'a karşı yalan uydurmuş oluruz. Rabbimizin dilemesi bir yana, dininize dönmek bize yakışmaz. Rabbimizin ilmi her şeyi kuşatmıştır. Biz yalnız Allah\'a güvendik. Rabbimiz! Bizimle milletimiz arasında hak ile Sen hüküm ver, Sen hükmedenlerin en hayırlısısın" dedi.'),
  ('tr.diyanet', 7, 89, 'Milletinin büyüklük taslayan ileri gelenleri, "Ey Şuayb! Ya dinimize dönersiniz ya da, and olsun ki seni ve inananları seninle beraber kentimizden çıkarırız" dediler. Şuayb, onlara: "İstemezsek de mi? Allah bizi dininizden kurtardıktan sonra ona dönecek olursak, doğrusu Allah\'a karşı yalan uydurmuş oluruz. Rabbimizin dilemesi bir yana, dininize dönmek bize yakışmaz. Rabbimizin ilmi her şeyi kuşatmıştır. Biz yalnız Allah\'a güvendik. Rabbimiz! Bizimle milletimiz arasında hak ile Sen hüküm ver, Sen hükmedenlerin en hayırlısısın" dedi.'),
  ('tr.diyanet', 7, 90, 'Milletinin inkar eden ileri gelenleri, "Şuayb\'a uyarsanız, and olsun ki siz kaybedersiniz" dediler.'),
  ('tr.diyanet', 7, 91, 'Bu yüzden onları bir sarsıntı tuttu ve oldukları yerde diz üstü çöküverdiler.'),
  ('tr.diyanet', 7, 92, 'Şuayb\'ı yalanlayanlar, yurtlarında sanki hiç yaşamamışlar gibi oldular, izleri bile kalmadı. Mahvolanlar, Şuayb\'ı yalanlayanlar oldu.'),
  ('tr.diyanet', 7, 93, 'Şuayb onlardan döndü de, "Ey milletim! And olsun ki, Rabbimin sözlerini size bildirdim, öğüt verdim; inkarcı millet için niçin üzüleyim?" dedi.'),
  ('tr.diyanet', 7, 94, 'Biz hangi kente (ülkeye) bir peygamber gönderdikse, ora halkını, yalvarıp yakarsınlar diye, darlık ve sıkıntıya uğratmışızdır.'),
  ('tr.diyanet', 7, 95, 'Sonra kötülüğün yerine iyiliği koyduk, öyle ki, çoğalıp, "babalarımız da darlığa uğramış, bolluğa kavuşmuşlardı" dediler. Bu yüzden onları haberleri olmadan, ansızın yakalayıverdik.'),
  ('tr.diyanet', 7, 96, 'Eğer kentlerin halkı inanmış ve Bize karşı gelmekten sakınmış olsalardı, onlara göğün ve yerin bolluklarını verirdik. Ama yalanladılar; bu yüzden onları, yaptıklarına karşılık yakalayıverdik.'),
  ('tr.diyanet', 7, 97, 'Kentlerin halkı, geceleyin uyurlarken azabımızın kendilerine gelmesinden güvende miydiler?'),
  ('tr.diyanet', 7, 98, 'Yahut kentlerin halkı, kuşluk vakti eğlenirlerken azabımızın kendilerine gelmesinden güvende miydiler?'),
  ('tr.diyanet', 7, 99, 'Onlar Allah\'ın düzeninden güvende miydiler? Allah\'ın düzeninden ancak mahvolacak millet güvende olur. Sahiplerinden sonra yeryüzüne mirasçı olan kimselere hala şu açıkça anlaşılmadı mı ki Biz dileseydik onları da suçlarının cezasına uğratırdık.'),
  ('tr.diyanet', 7, 100, 'Kalblerini kapatıp mühürleriz de birşey duymazlar.'),
  ('tr.diyanet', 7, 101, 'İşte o kentlerin haberlerini sana anlatıyoruz. And olsun ki onlara peygamberler belgeler getirdi; önceleri yalanladıklarından ötürü inanamadılar. Allah kafirlerin kalblerini böylece kapatıp mühürler.'),
  ('tr.diyanet', 7, 102, 'Onların çoğunda ahde bağlılık görmedik, çoğunu fasık kimseler olarak bulduk.'),
  ('tr.diyanet', 7, 103, 'Sonra peygamberlerin ardından Musa\'yı ayetlerimizle Firavun ve erkanına gönderdik. Ayetlerimize karşı haksızlık ettiler. Bozguncuların sonunun nasıl olduğuna bir bak.'),
  ('tr.diyanet', 7, 104, 'Musa, "Ey Firavun! Ben alemlerin Rabbinin peygamberiyim.'),
  ('tr.diyanet', 7, 105, 'Bana Allah\'a karşı ancak gerçeği söylemek yaraşır. Size Rabbinizden bir mucize getirdim, İsrailoğullarını benimle beraber gönder" dedi.'),
  ('tr.diyanet', 7, 106, 'Firavun: "Bir mucize getirdiysen ortaya koy bakalım, doğru sözlülerden isen bunu yaparsın" dedi.'),
  ('tr.diyanet', 7, 107, 'Musa, asasını yere atar atmaz apaçık bir yılan (ejderha) oluverdi; elini çıkardı, bakanlar bembeyaz olduğunu gördüler.'),
  ('tr.diyanet', 7, 108, 'Musa, asasını yere atar atmaz apaçık bir yılan (ejderha) oluverdi; elini çıkardı, bakanlar bembeyaz olduğunu gördüler.'),
  ('tr.diyanet', 7, 109, 'Firavun milletinin ileri gelenleri, "Doğrusu bu bilgin bir sihirbazdır, sizi memleketinizden çıkarmak istiyor" dediler. Firavun: "Ne buyurursunuz?" dedi.'),
  ('tr.diyanet', 7, 110, 'Firavun milletinin ileri gelenleri, "Doğrusu bu bilgin bir sihirbazdır, sizi memleketinizden çıkarmak istiyor" dediler. Firavun: "Ne buyurursunuz?" dedi.'),
  ('tr.diyanet', 7, 111, '"Onu ve kardeşini eğle; şehirlere toplayıcılar gönder, bütün bilgin sihirbazları sana getirsinler" dediler.'),
  ('tr.diyanet', 7, 112, '"Onu ve kardeşini eğle; şehirlere toplayıcılar gönder, bütün bilgin sihirbazları sana getirsinler" dediler.'),
  ('tr.diyanet', 7, 113, 'Sihirbazlar Firavun\'a geldi, "Yenecek olursak bize şüphesiz bir mükafat var değil mi?" dediler.'),
  ('tr.diyanet', 7, 114, 'Firavun, "Evet, yenerseniz gözdelerden olacaksınız" dedi.'),
  ('tr.diyanet', 7, 115, 'Sihirbazlar: "Ey Musa! Marifetini ya sen ortaya koy veya biz koyalım" dediler.'),
  ('tr.diyanet', 7, 116, 'Musa: "Siz koyun" dedi. Sihirbazlar marifetlerini ortaya koyunca insanların gözlerini sihirlediler ve onları ürküttüler, büyük bir sihir yaptılar.'),
  ('tr.diyanet', 7, 117, 'Biz de Musa\'ya, "Asanı koyuver" dedik, o da koydu; hemen onların uydurduklarını yutmaya başladı.'),
  ('tr.diyanet', 7, 118, 'Hak tahakkuk etti, onların yaptıkları boşa gitti.'),
  ('tr.diyanet', 7, 119, 'İşte orada yenildiler, küçük düştüler.'),
  ('tr.diyanet', 7, 120, 'Sihirbazlar secdeye kapanıp, "Alemlerin Rabbine, Musa ve Harun\'un Rabbine inandık" dediler.'),
  ('tr.diyanet', 7, 121, 'Sihirbazlar secdeye kapanıp, "Alemlerin Rabbine, Musa ve Harun\'un Rabbine inandık" dediler.'),
  ('tr.diyanet', 7, 122, 'Sihirbazlar secdeye kapanıp, "Alemlerin Rabbine, Musa ve Harun\'un Rabbine inandık" dediler.'),
  ('tr.diyanet', 7, 123, 'Firavun: "Ben size izin vermeden mi O\'na inandınız? Doğrusu bu, halkı şehirden çıkarmak için düzdüğünüz bir hiledir, fakat siz göreceksiniz. And olsun ki, ellerinizi ayaklarınızı çaprazlama keseceğim, sonra da hepinizi asacağım" dedi.'),
  ('tr.diyanet', 7, 124, 'Firavun: "Ben size izin vermeden mi O\'na inandınız? Doğrusu bu, halkı şehirden çıkarmak için düzdüğünüz bir hiledir, fakat siz göreceksiniz. And olsun ki, ellerinizi ayaklarınızı çaprazlama keseceğim, sonra da hepinizi asacağım" dedi.'),
  ('tr.diyanet', 7, 125, 'Onlar da: "Doğrusu biz ancak Rabbimize döneriz. Rabbimizin ayetleri gelince, onlara inanmamızdan ötürü bizden öç alıyorsun. Rabbimiz! Bize sabır ver ve canımızı müslim olarak al" dediler.'),
  ('tr.diyanet', 7, 126, 'Onlar da: "Doğrusu biz ancak Rabbimize döneriz. Rabbimizin ayetleri gelince, onlara inanmamızdan ötürü bizden öç alıyorsun. Rabbimiz! Bize sabır ver ve canımızı müslim olarak al" dediler.'),
  ('tr.diyanet', 7, 127, 'Firavun milletinin ileri gelenleri: "Musa\'yı ve milletini yeryüzünde bozgunculuk yapsınlar, seni ve tanrılarını bıraksınlar diye mi koyveriyorsun?" dediler. Firavun: "Onların oğullarını öldüreceğiz, kadınlarını sağ bırakacağız. Elbette biz onları ezecek üstünlükteyiz" dedi.'),
  ('tr.diyanet', 7, 128, 'Musa milletine: "Allah\'tan yardım dileyin ve sabredin; yeryüzü şüphesiz Allah\'ındır, kullarından dilediğini ona mirasçı kılar; sonuç Allah\'a karşı gelmekten sakınanlarındır" dedi.'),
  ('tr.diyanet', 7, 129, 'Milleti: "Sen bize gelmeden önce de, geldikten sonra da eziyet çektik" dediler. Musa da: "Rabbinizin düşmanlarınızı yok etmesi ve yeryüzünde sizi onların yerine geçirmesi umulur. O zaman nasıl davranacağınıza bakar" dedi.'),
  ('tr.diyanet', 7, 130, 'And olsun ki, Biz de Firavun ailesini, ders alsınlar diye, yıllarca kuraklığa ve ürün kıtlığına uğrattık.'),
  ('tr.diyanet', 7, 131, 'Onlara bir iyilik geldiği zaman; "Bu bizden ötürüdür" derler, bir fenalığa uğrarlarsa da, Musa ve onunla beraber olanların uğursuzluğuna verirlerdi. Bilin ki, kendilerinin uğradığı uğursuzluk Allah katındandır, fakat çoğu bunu bilmezler.'),
  ('tr.diyanet', 7, 132, 'Firavun ailesi: "Bizi sihirlemek için ne mucize gösterirsen göster, sana inanmayacağız" dediler.'),
  ('tr.diyanet', 7, 133, 'Bunun üzerine su baskınını, çekirgeyi, haşeratı, kurbağaları ve kanı birbirinden ayrı mucizeler olarak onlara musallat kıldık; yine de büyüklük taslayıp suçlu bir millet oldular.'),
  ('tr.diyanet', 7, 134, 'Azab başlarına çökünce, "Ey Musa! Rabbine, sana verdiği ahde göre bizim için yalvar. Bizden azabı kaldırırsan sana, and olsun ki, inanacağız ve İsrailoğullarını seninle beraber göndereceğiz"dediler.'),
  ('tr.diyanet', 7, 135, 'Azabı nasıl olsa sonuna gelecekleri bir müddet için üzerlerinden kaldırınca, hemen sözlerinden cayıyorlardı.'),
  ('tr.diyanet', 7, 136, 'Bu sebeple onlardan öç aldık, ayetlerimizi yalan sayıp umursamadıkları için onları denizde boğduk.'),
  ('tr.diyanet', 7, 137, 'Hor görülen yahudileri, bereketlendirdiğimiz yerin doğularına ve batılarına mirasçı kıldık. Rabbinin İsrailoğullarına verdiği güzel söz, sabırlarına karşılık yerine geldi. Firavun ve milletinin yaptığını ve yükselttiklerini yıktık.'),
  ('tr.diyanet', 7, 138, 'İsrailoğullarının denizden geçmelerini sağladık. Puta gönülden tapan bir millete rastladılar. "Ey Musa! Onların tanrıları gibi bize de bir tanrı yap" dediler, Musa: " Doğrusu siz bilgisiz bir milletsiniz, bunlar yok olacaklar ve işledikleri boşa gidecektir" dedi.'),
  ('tr.diyanet', 7, 139, 'İsrailoğullarının denizden geçmelerini sağladık. Puta gönülden tapan bir millete rastladılar. "Ey Musa! Onların tanrıları gibi bize de bir tanrı yap" dediler, Musa: " Doğrusu siz bilgisiz bir milletsiniz, bunlar yok olacaklar ve işledikleri boşa gidecektir" dedi.'),
  ('tr.diyanet', 7, 140, '"Sizi alemlere üstün kılmış olan Allah\'tan başka bir tanrı mı arayacağım?" dedi.'),
  ('tr.diyanet', 7, 141, 'Sizi kötü azaba sokan, kadınlarınızı sağ bırakıp oğullarınızı öldüren Firavun ailesinden kurtarmıştık. Bunda, size Rabbiniz tarafından büyük bir imtihan vardı.'),
  ('tr.diyanet', 7, 142, 'Musa\'ya otuz gece vade verip sonra buna on gece daha kattık; böylece Rabbinin tayin ettiği müddet kırk geceye tamamlandı. Musa, kardeşi Harun\'a, "Milletim içinde benim yerime geç, onları ıslah et, bozguncuların yoluna gitme" dedi.'),
  ('tr.diyanet', 7, 143, 'Musa, tayin ettiğimiz vakitte gelip Rabbi onunla konuşunca, Musa: "Rabbim! Bana Kendini göster, Sana bakayım" dedi. Allah: "Sen Beni göremezsin ama dağa bak, eğer o yerinde kalırsa sen de Beni göreceksin" buyurdu. Rabbi dağa tecelli edince onu yerlebir etti ve Musa da baygın düştü; ayılınca: "Yarabbi, münezzehsin, Sana tevbe ettim, ben inananların ilkiyim" dedi.'),
  ('tr.diyanet', 7, 144, '"Ey Musa! Verdiklerimle ve seninle konuşmamla seni insanlar arasından seçtim; sana verdiğimi al ve şükret" dedi.'),
  ('tr.diyanet', 7, 145, 'Ona levhalarda her şeyden bir öğüt yazdık ve her şeyi uzun uzadıya açıkladık; onlara sıkıca sarıl, milletine de emret en güzel şekilde tutsunlar. Size Allah\'a karşı gelenlerin yurdunu göstereceğim.'),
  ('tr.diyanet', 7, 146, 'Yeryüzünde haksız yere büyüklük taslayanları, ayetlerimden yüz çevirteceğim. Onlar bütün ayetleri görseler yine de inanmazlar; doğru yolu görseler, yol olarak benimsemezler; azgınlık yolunu görseler, hemen onu yol edinirler. Bu, onların mucizelerimizi yalan saymaları ve onlardan habersiz görünmelerinden ileri gelir.'),
  ('tr.diyanet', 7, 147, 'Ayetlerimizi ve ahirete kavuşmayı yalan sayan kimselerin işleri boşa gitmiştir. Onlar işlediklerinin karşılığından başka bir şeyle mi cezalanırlar?'),
  ('tr.diyanet', 7, 148, 'Musa\'nın ardından milleti, ziynet takımlarından, canlıymış gibi böğüren bir buzağı heykeli yaparak onu tanrı edindiler. O buzağının kendileriyle konuşmadığını ve yol da göstermediğini görmediler mi? Onu tanrı olarak benimseyip kendilerine yazık ettiler.'),
  ('tr.diyanet', 7, 149, 'Elleri böğründe, çaresiz kalıp, kendilerinin sapıtmış olduklarını görünce: "Eğer Rabbimiz bize acımaz ve bizi bağışlamazsa, and olsun ki mahvoluruz" dediler.'),
  ('tr.diyanet', 7, 150, 'Musa, milletine, kızgın ve üzgün olarak dönünce "Benim arkamdan ne kötü olmuşsunuz! Rabbinizin emrinin çabucak gelmesini mi istiyorsunuz?" dedi, levhaları attı ve kardeşinin başından tutup kendine doğru çekti. Harun: "Ey annem oğlu! Bu millet beni küçümsedi; az kalsın öldürüyorlardı. Bana, düşmanları sevindirecek şekilde davranma, beni bu zalim milletle bir sayma" dedi.'),
  ('tr.diyanet', 7, 151, 'Musa "Rabbim! Beni ve kardeşimi bağışla, bize acı, Sen merhametlilerin merhametlisisin" dedi.'),
  ('tr.diyanet', 7, 152, 'Buzağıyı tanrı olarak benimseyenler Rablerinin öfkesine ve dünya hayatında alçaklığa uğrayacaklardır; iftira edenleri böylece cezalandırırız.'),
  ('tr.diyanet', 7, 153, 'Kötülük işleyip ardından tevbe edenler ve inananlar bilsinler ki Rabbin, bu hareketlerinin ardından onları şüphesiz bağışlar ve merhamet eder.'),
  ('tr.diyanet', 7, 154, 'Musa, öfkesi yatışınca, bir nüshasında Rablerinden korkanlar için doğru yol ve rahmet yazılı olan levhaları aldı.'),
  ('tr.diyanet', 7, 155, 'Musa, tayin ettiğimiz müddette milletinden yetmiş kişi seçti; onları sarsıntı tutunca dedi ki: "Rabbim! Dileseydin daha önce beni ve onları yok ederdin, aramızdaki beyinsizlerin yaptıklarından ötürü bizi yok eder misin? Bu, Senin imtihanından başka birşey değildir, bununla dilediğini saptırır, dilediğini doğru yola iletirsin; bizim dostumuz Sensin; bizi bağışla, bize merhamet et. Sen bağışlayanların en iyisisin."'),
  ('tr.diyanet', 7, 156, '"Bu dünyada ve ahirette bizim için güzel olanı yaz; biz Sana yöneldik" dedi. Allah: "Azabıma dilediğim kimseyi uğratırım, rahmetim herşeyi kaplamıştır; bunu Allah\'a karşı gelmekten sakınanlara, zekat verenlere, ayetlerimize inanıp, yanlarındaki Tevrat ve İncil\'de yazılı buldukları, okuyup yazması olmayan peygambere uyanlara yazacağız. O peygamber, onlara, uygun olanı emreder ve fenalıktan meneder, temiz şeyleri helal, murdar şeyleri haram kılar, onların ağır yüklerini indirir, zor tekliflerini hafifletir. Bu peygambere inanan, hürmet eden, yardım eden, onunla gönderilen nura uyanlar yok mu? İşte onlar saadete erenlerdir" dedi.'),
  ('tr.diyanet', 7, 157, '"Bu dünyada ve ahirette bizim için güzel olanı yaz; biz Sana yöneldik" dedi. Allah: "Azabıma dilediğim kimseyi uğratırım, rahmetim herşeyi kaplamıştır; bunu Allah\'a karşı gelmekten sakınanlara, zekat verenlere, ayetlerimize inanıp, yanlarındaki Tevrat ve İncil\'de yazılı buldukları, okuyup yazması olmayan peygambere uyanlara yazacağız. O peygamber, onlara, uygun olanı emreder ve fenalıktan meneder, temiz şeyleri helal, murdar şeyleri haram kılar, onların ağır yüklerini indirir, zor tekliflerini hafifletir. Bu peygambere inanan, hürmet eden, yardım eden, onunla gönderilen nura uyanlar yok mu? İşte onlar saadete erenlerdir" dedi.'),
  ('tr.diyanet', 7, 158, 'De ki: "Ey insanlar! Doğrusu ben, göklerin ve yerin hükümranı, O\'ndan başka tanrı bulunmayan, dirilten ve öldüren Allah\'ın, hepiniz için gönderdiği peygamberiyim. Allah\'a ve okuyup yazması olmayan, haber getiren peygamberine -ki o da Allah\'a ve sözlerine inanmıştır- inanın; ona uyun ki doğru yolu bulasınız."'),
  ('tr.diyanet', 7, 159, 'Musa\'nın milletinden bir topluluk hakkı gösterirler ve onunla hükmederlerdi.'),
  ('tr.diyanet', 7, 160, 'Biz İsrailoğullarını oymaklar halinde on iki topluluğa ayırdık. Milleti Musa\'dan su isteyince ona: "Asanla taşa vur" diye bildirdik; ondan on iki pınar fışkırdı. Herkes içeceği yeri öğrendi. Bulutla üzerlerine gölge yaptık, onlara kudret helvası ve bıldırcın indirdik, "Size verdiğimiz rızıkların temiz olanlarından yiyin" dedik. Onlar, karşı gelmekle, Bize değil kendilerine zulmediyorlardı.'),
  ('tr.diyanet', 7, 161, 'Onlara: "Şu şehirde oturun, dilediğiniz gibi yiyip için, "affet!" deyin ve secde ederek kapısından girin; Biz de yanılmalarınızı bağışlarız. İyi davrananlara daha da artıracağız" denmişti.'),
  ('tr.diyanet', 7, 162, 'Onların zulmedenleri, kendilerine söylenen sözü başkasiyle değiştirdiler. Biz de, o zalimlere, zulümlerinden ötürü gökten azab indirdik.'),
  ('tr.diyanet', 7, 163, 'Onlara, deniz kıyısındaki kasabanın durumunu sor. Cumartesi yasaklarına tecavüz ediyorlardı. Cumartesileri balıklar sürüyle geliyor, başka günler gelmiyorlardı. Biz onları, yoldan çıkmaları sebebiyle böylece deniyorduk.'),
  ('tr.diyanet', 7, 164, 'Aralarından bir topluluk: "Allah\'ın yok edeceği veya şiddetli azaba uğratacağı bir millete niçin öğüt veriyorsunuz?" dediler. Öğüt verenler: "Rabbinize, hiç değilse bir özür beyan edebilmemiz içindir, belki Allah\'a karşı gelmekten sakınırlar" dediler.'),
  ('tr.diyanet', 7, 165, 'Kendilerine yapılan öğütleri unutunca, Biz fenalıktan menedenleri kurtardık ve zalimleri, Allah\'a karşı gelmelerinden ötürü şiddetli azaba uğrattık.'),
  ('tr.diyanet', 7, 166, 'Kendilerine edilen yasakları aşınca, onlara: "Aşağılık birer maymun olun" dedik.'),
  ('tr.diyanet', 7, 167, 'Rabbin, kıyamet gününe kadar, onları, kötü azaba uğratacak kimseleri üzerlerine göndereceğini bildirmişti. Doğrusu Rabbin, cezayı çabuk verir. Doğrusu O bağışlar ve merhamet eder.'),
  ('tr.diyanet', 7, 168, 'Biz onları yeryüzünde iyiler ve aşağılıklar olarak bölük bölük ayırdık; iyiliğe dönerler diye onları güzellikler ve kötülüklerle sınadık.'),
  ('tr.diyanet', 7, 169, 'Ardlarından yerlerine gelen bir takım kötüler, Kitap\'a mirasçı oldular. "Biz nasıl olsa affedileceğiz" diyerek Kitap\'ın hükümlerini değiştirme karşılığı bu değersiz dünyanın mallarını alırlar; yine ona benzer geçici bir şey kendilerine gelince onu da kabul ederlerdi. Onlardan, Allah\'a karşı ancak gerçeği söyleyeceklerine dair Kitap üzerine söz alınmamış mıydı? Kitap\'da olanları okumamışlar mıydı? Allah\'a karşı gelmekten sakınanlar için, ahiret yurdu vardır, düşünmüyor musunuz? Biz, iyiliğe çalışanların ecrini elbette zayi etmeyiz.'),
  ('tr.diyanet', 7, 170, 'Ardlarından yerlerine gelen bir takım kötüler, Kitap\'a mirasçı oldular. "Biz nasıl olsa affedileceğiz" diyerek Kitap\'ın hükümlerini değiştirme karşılığı bu değersiz dünyanın mallarını alırlar; yine ona benzer geçici bir şey kendilerine gelince onu da kabul ederlerdi. Onlardan, Allah\'a karşı ancak gerçeği söyleyeceklerine dair Kitap üzerine söz alınmamış mıydı? Kitap\'da olanları okumamışlar mıydı? Allah\'a karşı gelmekten sakınanlar için, ahiret yurdu vardır, düşünmüyor musunuz? Biz, iyiliğe çalışanların ecrini elbette zayi etmeyiz.'),
  ('tr.diyanet', 7, 171, 'Tur dağını, gölgelik gibi onların üzerlerine yükseltmiştik, onlar tepelerine düşeceğini sanmışlardı. Onlara: "Size verdiğimiz Kitap\'a sıkıca sarılın, içinde olanı düşünün ki sakınanlardan olasınız" demiştik.'),
  ('tr.diyanet', 7, 172, 'Rabbin, insanoğlunun sulbünden soyunu alıp devam ettirmiş, onlara: "Ben sizin Rabbiniz değil miyim" demiş ve buna kendilerini şahit tutmuştu. Onlar da: "Evet şahidiz" demişlerdi. Bu, kıyamet günü, "Bizim bundan haberimiz yoktu" dersiniz veya "Daha önce babalarımız Allah\'a ortak koşmuşlardı, biz de onlardan sonra gelen bir soyuz, bizi, boşa çalışanların yaptıklarından ötürü yok eder misin?" dersiniz diyedir.'),
  ('tr.diyanet', 7, 173, 'Rabbin, insanoğlunun sulbünden soyunu alıp devam ettirmiş, onlara: "Ben sizin Rabbiniz değil miyim" demiş ve buna kendilerini şahit tutmuştu. Onlar da: "Evet şahidiz" demişlerdi. Bu, kıyamet günü, "Bizim bundan haberimiz yoktu" dersiniz veya "Daha önce babalarımız Allah\'a ortak koşmuşlardı, biz de onlardan sonra gelen bir soyuz, bizi, boşa çalışanların yaptıklarından ötürü yok eder misin?" dersiniz diyedir.'),
  ('tr.diyanet', 7, 174, 'Belki doğru yola dönerler diye ayetleri böylece uzun uzadıya açıklıyoruz.'),
  ('tr.diyanet', 7, 175, 'Onlara, şeytanın peşine takdığı ve kendisine verdiğimiz ayetlerden sıyrılarak azgınlıklardan olan kişinin olayını anlat.'),
  ('tr.diyanet', 7, 176, 'Dileseydik, onu ayetlerimizle üstün kılardık; fakat o, dünyaya meyletti ve hevesine uydu. Durumu, üstüne varsan da, kendi haline bıraksan da, dilini sarkıtıp soluyan köpeğin durumu gibidir. İşte ayetlerimizi yalan sayan kimselerin hali böyledir. Sen onlara bu kıssayı anlat, belki üzerinde düşünürler.'),
  ('tr.diyanet', 7, 177, 'Ayetlerimizi yalan sayan, kendine zulmeden millet ne kötü bir misaldir!'),
  ('tr.diyanet', 7, 178, 'Allah\'ın doğru yola sevkettiği kimse doğru yolda olur. Saptırdığı kimseler ise, işte onlar mahvolanlardır.'),
  ('tr.diyanet', 7, 179, 'And olsun ki, cehennem için de birçok cin ve insan yarattık; onların kalbleri vardır ama anlamazlar; gözleri vardır ama görmezler; kulakları vardır ama işitmezler. İşte bunlar hayvanlar gibi hatta daha sapıktırlar. İşte bunlar gafillerdir.'),
  ('tr.diyanet', 7, 180, 'En güzel isimler Allah\'ındır, O\'na o isimlerle dua edin, O\'nun isimleri konusunda eğriliğe sapanları bırakın. Onlar yaptıklarının cezasını göreceklerdir.'),
  ('tr.diyanet', 7, 181, 'Yarattıklarımızdan bir topluluk hakkı gösterirler ve onunla hükmederler.'),
  ('tr.diyanet', 7, 182, 'Ayetlerimizi yalan sayanları, bilmedikleri yönden, ağır ağır sonuçlarına yaklaştıracağız.'),
  ('tr.diyanet', 7, 183, 'Onlara mahsustan mühlet veririm, çünkü Benim düzenim çetindir.'),
  ('tr.diyanet', 7, 184, 'Düşünmüyorlar mı ki, arkadaşları olan peygamberde deliliğin eseri yoktur. O ancak açıkça uyaran bir kimsedir.'),
  ('tr.diyanet', 7, 185, 'Göklerin ve yerin hükümranlığını, Allah\'ın yarattığı her şeyi ve ecellerinin yaklaşmış olması ihtimalini düşünmüyorlar mı? Bundan sonra hangi söze inanacaklar?'),
  ('tr.diyanet', 7, 186, 'Allah\'ın saptırdığını yola getirecek yoktur. O, sapanları taşkınlıkları içinde bocalayıp dururlarken bırakır.'),
  ('tr.diyanet', 7, 187, 'Sana, kıyamet saatinin ne zaman gelip çatacağını soruyorlar, de ki: "Onu ancak Rabbim bilir, onun vaktini, O\'ndan başka belirtecek yoktur. Göklerin ve yerin, ağırlığını kaldıramayacağı o saat, sizlere ansızın gelecektir." Sen sanki öğrenmişsin gibi sana soruyorlar, de ki: "Onu bilmek ancak Allah\'a mahsustur, ama insanların çoğu bu gerçeği bilmezler."'),
  ('tr.diyanet', 7, 188, 'De ki: "Allah\'ın dilemesi dışında ben kendime bir fayda ve zarar verecek durumda değilim. Görülmeyeni bileydim, daha çok iyilik yapardım ve bana kötülük de gelmezdi. Ben sadece, inanan bir milleti uyaran ve müjdeleyen bir peygamberim."'),
  ('tr.diyanet', 7, 189, 'Sizi bir nefisten yaratan ve gönlünün huzura kavuşacağı eşini de ondan var eden Allah\'tır. Eşine yaklaşınca, eşi hafif bir yük yüklendi ve bu halde bir müddet taşıdı. Hamileliği ağırlaşınca, karı-koca, Rableri olan Allah\'a: "Bize kusursuz bir çocuk verirsen, and olsun ki şükredenlerden oluruz" diye yalvardılar.'),
  ('tr.diyanet', 7, 190, 'Allah onlara kusursuz bir çocuk verince, kendilerine verdiği şey hakkında Allah\'a ortaklar koştular. Allah, onların ortak koştukları şeylerden yücedir.'),
  ('tr.diyanet', 7, 191, 'Kendileri yaratılmışken, bir şey yaratamayan putları mı ortak koşuyorlar?'),
  ('tr.diyanet', 7, 192, 'Oysa putlar ne onlara yardım edebilir ve ne de kendilerine bir yardımları olur.'),
  ('tr.diyanet', 7, 193, 'Onları doğru yola çağırırsanız, size uymazlar; çağırmanız da, susmanız da onlar için birdir.'),
  ('tr.diyanet', 7, 194, 'Allah\'tan başka taptıklarınız putlar da, sizin gibi yaratıklardır. Eğer doğru sözlü iseniz, onları çağırın da size cevap versinler bakalım.'),
  ('tr.diyanet', 7, 195, 'Onların yürüyecek ayakları mı var, yoksa tutacak elleri mi var, ya da görecek gözleri mi var, veya işitecek kulakları mı var? De ki: "Ortaklarınızı çağırın elinizden gelirse bana tuzak kurun, göz açtırmayın."'),
  ('tr.diyanet', 7, 196, '"Çünkü benim dostum, Kitap\'ı indiren Allah\'tır. O, iyileri dost edinir."'),
  ('tr.diyanet', 7, 197, '"O\'nu bırakıp da taptıklarınız, kendilerine yardım edemezler ki size yardım etsinler."'),
  ('tr.diyanet', 7, 198, 'Onları doğru yola çağırırsanız duymazlar. Sana baktıklarını görürsün, oysa görmezler.'),
  ('tr.diyanet', 7, 199, 'Sen af yolunu tut, bağışla, uygun olanı emret, bilgisizlere aldırış etme.'),
  ('tr.diyanet', 7, 200, 'Şeytan seni dürtecek olursa Allah\'a sığın, doğrusu O işitir ve bilir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 7, 201, 'Allah\'a karşı gelmekten sakınanlar, şeytan tarafından bir vesveseye uğrayınca, Allah\'ı anarlar ve hemen gerçeği görürler.'),
  ('tr.diyanet', 7, 202, 'Şeytanın kardeşleri onları azgınlığa sürüklerler ve bundan hiç geri durmazlar.'),
  ('tr.diyanet', 7, 203, 'Onlara bir ayet getirmediğin zaman, "Sen bir tane yapsaydın ya" derler. De ki: "Ben ancak Rabbim tarafından bana vahyolunana uyarım. Bu Kitap inanan millete Rabbinizden açık belgeler, yol gösterme ve rahmettir."'),
  ('tr.diyanet', 7, 204, 'Kuran okunduğu zaman ona kulak verin, dinleyin ki merhamet olunasınız.'),
  ('tr.diyanet', 7, 205, 'Rabbini gönülden ve korkarak içinden hafif bir sesle sabah akşam an, gafillerden olma.'),
  ('tr.diyanet', 7, 206, 'Doğrusu Rabbinin katında olanlar, O\'na kulluk etmekten büyüklenmezler, O\'nu tenzih ederler ve yalnız O\'na secde ederler.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 7, 1, 'Alif laam mim shaad.'),
  ('id.indonesian', 7, 2, 'Ini adalah sebuah kitab yang diturunkan kepadamu, maka janganlah ada kesempitan di dalam dadamu karenanya, supaya kamu memberi peringatan dengan kitab itu (kepada orang kafir), dan menjadi pelajaran bagi orang-orang yang beriman.'),
  ('id.indonesian', 7, 3, 'Ikutilah apa yang diturunkan kepadamu dari Tuhanmu dan janganlah kamu mengikuti pemimpin-pemimpin selain-Nya. Amat sedikitlah kamu mengambil pelajaran (daripadanya).'),
  ('id.indonesian', 7, 4, 'Betapa banyaknya negeri yang telah Kami binasakan, maka datanglah siksaan Kami (menimpa penduduk)nya di waktu mereka berada di malam hari, atau di waktu mereka beristirahat di tengah hari.'),
  ('id.indonesian', 7, 5, 'Maka tidak adalah keluhan mereka di waktu datang kepada mereka siksaan Kami, kecuali mengatakan: "Sesungguhnya kami adalah orang-orang yang zalim".'),
  ('id.indonesian', 7, 6, 'Maka sesungguhnya Kami akan menanyai umat-umat yang telah diutus rasul-rasul kepada mereka dan sesungguhnya Kami akan menanyai (pula) rasul-rasul (Kami),'),
  ('id.indonesian', 7, 7, 'maka sesungguhnya akan Kami kabarkan kepada mereka (apa-apa yang telah mereka perbuat), sedang (Kami) mengetahui (keadaan mereka), dan Kami sekali-kali tidak jauh (dari mereka).'),
  ('id.indonesian', 7, 8, 'Timbangan pada hari itu ialah kebenaran (keadilan), maka barangsiapa berat timbangan kebaikannya, maka mereka itulah orang-orang yang beruntung.'),
  ('id.indonesian', 7, 9, 'Dan siapa yang ringan timbangan kebaikannya, maka itulah orang-orang yang merugikan dirinya sendiri, disebabkan mereka selalu mengingkari ayat-ayat Kami.'),
  ('id.indonesian', 7, 10, 'Sesungguhnya Kami telah menempatkan kamu sekalian di muka bumi dan Kami adakan bagimu di muka bumi (sumber) penghidupan. Amat sedikitlah kamu bersyukur.'),
  ('id.indonesian', 7, 11, 'Sesungguhnya Kami telah menciptakan kamu (Adam), lalu Kami bentuk tubuhmu, kemudian Kami katakan kepada para malaikat: "Bersujudlah kamu kepada Adam", maka merekapun bersujud kecuali iblis. Dia tidak termasuk mereka yang bersujud.'),
  ('id.indonesian', 7, 12, 'Allah berfirman: "Apakah yang menghalangimu untuk bersujud (kepada Adam) di waktu Aku menyuruhmu?" Menjawab iblis "Saya lebih baik daripadanya: Engkau ciptakan saya dari api sedang dia Engkau ciptakan dari tanah".'),
  ('id.indonesian', 7, 13, 'Allah berfirman: "Turunlah kamu dari surga itu; karena kamu sepatutnya menyombongkan diri di dalamnya, maka keluarlah, sesungguhnya kamu termasuk orang-orang yang hina".'),
  ('id.indonesian', 7, 14, 'Iblis menjawab: "Beri tangguhlah saya sampai waktu mereka dibangkitkan".'),
  ('id.indonesian', 7, 15, 'Allah berfirman: "Sesungguhnya kamu termasuk mereka yang diberi tangguh".'),
  ('id.indonesian', 7, 16, 'Iblis menjawab: "Karena Engkau telah menghukum saya tersesat, saya benar-benar akan (menghalang-halangi) mereka dari jalan Engkau yang lurus,'),
  ('id.indonesian', 7, 17, 'kemudian saya akan mendatangi mereka dari muka dan dari belakang mereka, dari kanan dan dari kiri mereka. Dan Engkau tidak akan mendapati kebanyakan mereka bersyukur (taat).'),
  ('id.indonesian', 7, 18, 'Allah berfirman: "Keluarlah kamu dari surga itu sebagai orang terhina lagi terusir. Sesungguhnya barangsiapa di antara mereka mengikuti kamu, benar-benar Aku akan mengisi neraka Jahannam dengan kamu semuanya".'),
  ('id.indonesian', 7, 19, '(Dan Allah berfirman): "Hai Adam bertempat tinggallah kamu dan isterimu di surga serta makanlah olehmu berdua (buah-buahan) di mana saja yang kamu sukai, dan janganlah kamu berdua mendekati pohon ini, lalu menjadilah kamu berdua termasuk orang-orang yang zalim".'),
  ('id.indonesian', 7, 20, 'Maka syaitan membisikkan pikiran jahat kepada keduanya untuk menampakkan kepada keduanya apa yang tertutup dari mereka yaitu auratnya dan syaitan berkata: "Tuhan kamu tidak melarangmu dan mendekati pohon ini, melainkan supaya kamu berdua tidak menjadi malaikat atau tidak menjadi orang-orang yang kekal (dalam surga)".'),
  ('id.indonesian', 7, 21, 'Dan dia (syaitan) bersumpah kepada keduanya. "Sesungguhnya saya adalah termasuk orang yang memberi nasehat kepada kamu berdua",'),
  ('id.indonesian', 7, 22, 'maka syaitan membujuk keduanya (untuk memakan buah itu) dengan tipu daya. Tatkala keduanya telah merasai buah kayu itu, nampaklah bagi keduanya aurat-auratnya, dan mulailah keduanya menutupinya dengan daun-daun surga. Kemudian Tuhan mereka menyeru mereka: "Bukankah Aku telah melarang kamu berdua dari pohon kayu itu dan Aku katakan kepadamu: "Sesungguhnya syaitan itu adalah musuh yang nyata bagi kamu berdua?"'),
  ('id.indonesian', 7, 23, 'Keduanya berkata: "Ya Tuhan kami, kami telah menganiaya diri kami sendiri, dan jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya pastilah kami termasuk orang-orang yang merugi.'),
  ('id.indonesian', 7, 24, 'Allah berfirman: "Turunlah kamu sekalian, sebahagian kamu menjadi musuh bagi sebahagian yang lain. Dan kamu mempunyai tempat kediaman dan kesenangan (tempat mencari kehidupan) di muka bumi sampai waktu yang telah ditentukan".'),
  ('id.indonesian', 7, 25, 'Allah berfirman: "Di bumi itu kamu hidup dan di bumi itu kamu mati, dan dari bumi itu (pula) kamu akan dibangkitkan.'),
  ('id.indonesian', 7, 26, 'Hai anak Adam, sesungguhnya Kami telah menurunkan kepadamu pakaian untuk menutup auratmu dan pakaian indah untuk perhiasan. Dan pakaian takwa itulah yang paling baik. Yang demikian itu adalah sebahagian dari tanda-tanda kekuasaan Allah, mudah-mudahan mereka selalu ingat.'),
  ('id.indonesian', 7, 27, 'Hai anak Adam, janganlah sekali-kali kamu dapat ditipu oleh syaitan sebagaimana ia telah mengeluarkan kedua ibu bapamu dari surga, ia menanggalkan dari keduanya pakaiannya untuk memperlihatkan kepada keduanya auratnya. Sesungguhnya ia dan pengikut-pengikutnya melihat kamu dan suatu tempat yang kamu tidak bisa melihat mereka. Sesungguhnya Kami telah menjadikan syaitan-syaitan itu pemimpin-pemimpim bagi orang-orang yang tidak beriman.'),
  ('id.indonesian', 7, 28, 'Dan apabila mereka melakukan perbuatan keji, mereka berkata: "Kami mendapati nenek moyang kami mengerjakan yang demikian itu, dan Allah menyuruh kami mengerjakannya". Katakanlah: "Sesungguhnya Allah tidak menyuruh (mengerjakan) perbuatan yang keji". Mengapa kamu mengada-adakan terhadap Allah apa yang tidak kamu ketahui?'),
  ('id.indonesian', 7, 29, 'Katakanlah: "Tuhanku menyuruh menjalankan keadilan". Dan (katakanlah): "Luruskanlah muka (diri)mu di setiap sembahyang dan sembahlah Allah dengan mengikhlaskan ketaatanmu kepada-Nya. Sebagaimana Dia telah menciptakan kamu pada permulaan (demikian pulalah kamu akan kembali kepada-Nya)".'),
  ('id.indonesian', 7, 30, 'Sebahagian diberi-Nya petunjuk dan sebahagian lagi telah pasti kesesatan bagi mereka. Sesungguhnya mereka menjadikan syaitan-syaitan pelindung (mereka) selain Allah, dan mereka mengira bahwa mereka mendapat petunjuk.'),
  ('id.indonesian', 7, 31, 'Hai anak Adam, pakailah pakaianmu yang indah di setiap (memasuki) mesjid, makan dan minumlah, dan janganlah berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang-orang yang berlebih-lebihan.'),
  ('id.indonesian', 7, 32, 'Katakanlah: "Siapakah yang mengharamkan perhiasan dari Allah yang telah dikeluarkan-Nya untuk hamba-hamba-Nya dan (siapa pulakah yang mengharamkan) rezeki yang baik?" Katakanlah: "Semuanya itu (disediakan) bagi orang-orang yang beriman dalam kehidupan dunia, khusus (untuk mereka saja) di hari kiamat". Demikianlah Kami menjelaskan ayat-ayat itu bagi orang-orang yang mengetahui.'),
  ('id.indonesian', 7, 33, 'Katakanlah: "Tuhanku hanya mengharamkan perbuatan yang keji, baik yang nampak ataupun yang tersembunyi, dan perbuatan dosa, melanggar hak manusia tanpa alasan yang benar, (mengharamkan) mempersekutukan Allah dengan sesuatu yang Allah tidak menurunkan hujjah untuk itu dan (mengharamkan) mengada-adakan terhadap Allah apa yang tidak kamu ketahui".'),
  ('id.indonesian', 7, 34, 'Tiap-tiap umat mempunyai batas waktu; maka apabila telah datang waktunya mereka tidak dapat mengundurkannya barang sesaatpun dan tidak dapat (pula) memajukannya.'),
  ('id.indonesian', 7, 35, 'Hai anak-anak Adam, jika datang kepadamu rasul-rasul daripada kamu yang menceritakan kepadamu ayat-ayat-Ku, maka barangsiapa yang bertakwa dan mengadakan perbaikan, tidaklah ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 7, 36, 'Dan orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri terhadapnya, mereka itu penghuni-penghuni neraka; mereka kekal di dalamnya.'),
  ('id.indonesian', 7, 37, 'Maka siapakah yang lebih zalim daripada orang yang membuat-buat dusta terhadap Allah atau mendustakan ayat-ayat-Nya? Orang-orang itu akan memperoleh bahagian yang telah ditentukan untuknya dalam Kitab (Lauh Mahfuzh); hingga bila datang kepada mereka utusan-utusan Kami (malaikat) untuk mengambil nyawanya, (di waktu itu) utusan Kami bertanya: "Di mana (berhala-berhala) yang biasa kamu sembah selain Allah?" Orang-orang musyrik itu menjawab: "Berhala-berhala itu semuanya telah lenyap dari kami," dan mereka mengakui terhadap diri mereka bahwa mereka adalah orang-orang yang kafir.'),
  ('id.indonesian', 7, 38, 'Allah berfirman: "Masuklah kamu sekalian ke dalam neraka bersama umat-umat jin dan manusia yang telah terdahulu sebelum kamu. Setiap suatu umat masuk (ke dalam neraka), dia mengutuk kawannya (menyesatkannya); sehingga apabila mereka masuk semuanya berkatalah orang-orang yang masuk kemudian di antara mereka kepada orang-orang yang masuk terdahulu: "Ya Tuhan kami, mereka telah menyesatkan kami, sebab itu datangkanlah kepada mereka siksaan yang berlipat ganda dari neraka". Allah berfirman: "Masing-masing mendapat (siksaan) yang berlipat ganda, akan tetapi kamu tidak mengetahui".'),
  ('id.indonesian', 7, 39, 'Dan berkata orang-orang yang masuk terdahulu di antara mereka kepada orang-orang yang masuk kemudian: "Kamu tidak mempunyai kelebihan sedikitpun atas kami, maka rasakanlah siksaan karena perbuatan yang telah kamu lakukan".'),
  ('id.indonesian', 7, 40, 'Sesungguhnya orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri terhadapnya, sekali-kali tidak akan dibukakan bagi mereka pintu-pintu langit dan tidak (pula) mereka masuk surga, hingga unta masuk ke lubang jarum. Demikianlah Kami memberi pembalasan kepada orang-orang yang berbuat kejahatan.'),
  ('id.indonesian', 7, 41, 'Mereka mempunyai tikar tidur dari api neraka dan di atas mereka ada selimut (api neraka). Demikianlah Kami memberi balasan kepada orang-orang yang zalim,'),
  ('id.indonesian', 7, 42, 'dan orang-orang yang beriman dan mengerjakan amal-amal yang saleh, Kami tidak memikulkan kewajiban kepada diri seseorang melainkan sekedar kesanggupannya, mereka itulah penghuni-penghuni surga; mereka kekal di dalamnya.'),
  ('id.indonesian', 7, 43, 'Dan Kami cabut segala macam dendam yang berada di dalam dada mereka; mengalir di bawah mereka sungai-sungai dan mereka berkata: "Segala puji bagi Allah yang telah menunjuki kami kepada (surga) ini. Dan kami sekali-kali tidak akan mendapat petunjuk kalau Allah tidak memberi kami petunjuk. Sesungguhnya telah datang rasul-rasul Tuhan kami, membawa kebenaran". Dan diserukan kepada mereka: "ltulah surga yang diwariskan kepadamu, disebabkan apa yang dahulu kamu kerjakan".'),
  ('id.indonesian', 7, 44, 'Dan penghuni-penghuni surga berseru kepada Penghuni-penghuni neraka (dengan mengatakan): "Sesungguhnya kami dengan sebenarnya telah memperoleh apa yang Tuhan kami menjanjikannya kepada kami. Maka apakah kamu telah memperoleh dengan sebenarnya apa (azab) yang Tuhan kamu menjanjikannya (kepadamu)?" Mereka (penduduk neraka) menjawab: "Betul". Kemudian seorang penyeru (malaikat) mengumumkan di antara kedua golongan itu: "Kutukan Allah ditimpakan kepada orang-orang yang zalim,'),
  ('id.indonesian', 7, 45, '(yaitu) orang-orang yang menghalang-halangi (manusia) dari jalan Allah dan menginginkan agar jalan itu menjadi bengkok, dan mereka kafir kepada kehidupan akhirat".'),
  ('id.indonesian', 7, 46, 'Dan di antara keduanya (penghuni surga dan neraka) ada batas; dan di atas A\'raaf itu ada orang-orang yang mengenal masing-masing dari dua golongan itu dengan tanda-tanda mereka. Dan mereka menyeru penduduk surga: "Salaamun \'alaikum". Mereka belum lagi memasukinya, sedang mereka ingin segera (memasukinya).'),
  ('id.indonesian', 7, 47, 'Dan apabila pandangan mereka dialihkan ke arah penghuni neraka, mereka berkata: "Ya Tuhan kami, janganlah Engkau tempatkan kami bersama-sama orang-orang yang zalim itu".'),
  ('id.indonesian', 7, 48, 'Dan orang-orang yang di atas A\'raaf memanggil beberapa orang (pemuka-pemuka orang kafir) yang mereka mengenalnya dengan tanda-tandanya dengan mengatakan: "Harta yang kamu kumpulkan dan apa yang selalu kamu sombongkan itu, tidaklah memberi manfaat kepadamu".'),
  ('id.indonesian', 7, 49, '(Orang-orang di atas A\'raaf bertanya kepada penghuni neraka): "Itukah orang-orang yang kamu telah bersumpah bahwa mereka tidak akan mendapat rahmat Allah?". (Kepada orang mukmin itu dikatakan): "Masuklah ke dalam surga, tidak ada kekhawatiran terhadapmu dan tidak (pula) kamu bersedih hati".'),
  ('id.indonesian', 7, 50, 'Dan penghuni neraka menyeru penghuni surga: "Limpahkanlah kepada kami sedikit air atau makanan yang telah direzekikan Allah kepadamu". Mereka (penghuni surga) menjawab: "Sesungguhnya Allah telah mengharamkan keduanya itu atas orang-orang kafir,'),
  ('id.indonesian', 7, 51, '(yaitu) orang-orang yang menjadikan agama mereka sebagai main-main dan senda gurau, dan kehidupan dunia telah menipu mereka". Maka pada hari (kiamat) ini, Kami melupakan mereka sebagaimana mereka melupakan pertemuan mereka dengan hari ini, dan (sebagaimana) mereka selalu mengingkari ayat-ayat Kami.'),
  ('id.indonesian', 7, 52, 'Dan sesungguhnya Kami telah mendatangkan sebuah Kitab (Al Quran) kepada mereka yang Kami telah menjelaskannya atas dasar pengetahuan Kami; menjadi petunjuk dan rahmat bagi orang-orang yang beriman.'),
  ('id.indonesian', 7, 53, 'Tiadalah mereka menunggu-nunggu kecuali (terlaksananya kebenaran) Al Quran itu. Pada hari datangnya kebenaran pemberitaan Al Quran itu, berkatalah orang-orang yang melupakannya sebelum itu: "Sesungguhnya telah datang rasul-rasul Tuhan kami membawa yang hak, maka adakah bagi kami pemberi syafa\'at yang akan memberi syafa\'at bagi kami, atau dapatkah kami dikembalikan (ke dunia) sehingga kami dapat beramal yang lain dari yang pernah kami amalkan?". Sungguh mereka telah merugikan diri mereka sendiri dan telah lenyaplah dari mereka tuhan-tuhan yang mereka ada-adakan.'),
  ('id.indonesian', 7, 54, 'Sesungguhnya Tuhan kamu ialah Allah yang telah menciptakan langit dan bumi dalam enam masa, lalu Dia bersemayam di atas \'Arsy. Dia menutupkan malam kepada siang yang mengikutinya dengan cepat, dan (diciptakan-Nya pula) matahari, bulan dan bintang-bintang (masing-masing) tunduk kepada perintah-Nya. Ingatlah, menciptakan dan memerintah hanyalah hak Allah. Maha Suci Allah, Tuhan semesta alam.'),
  ('id.indonesian', 7, 55, 'Berdoalah kepada Tuhanmu dengan berendah diri dan suara yang lembut. Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas.'),
  ('id.indonesian', 7, 56, 'Dan janganlah kamu membuat kerusakan di muka bumi, sesudah (Allah) memperbaikinya dan berdoalah kepada-Nya dengan rasa takut (tidak akan diterima) dan harapan (akan dikabulkan). Sesungguhnya rahmat Allah amat dekat kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 7, 57, 'Dan Dialah yang meniupkan angin sebagai pembawa berita gembira sebelum kedatangan rahmat-Nya (hujan); hingga apabila angin itu telah membawa awan mendung, Kami halau ke suatu daerah yang tandus, lalu Kami turunkan hujan di daerah itu, maka Kami keluarkan dengan sebab hujan itu pelbagai macam buah-buahan. Seperti itulah Kami membangkitkan orang-orang yang telah mati, mudah-mudahan kamu mengambil pelajaran.'),
  ('id.indonesian', 7, 58, 'Dan tanah yang baik, tanaman-tanamannya tumbuh subur dengan seizin Allah; dan tanah yang tidak subur, tanaman-tanamannya hanya tumbuh merana. Demikianlah Kami mengulangi tanda-tanda kebesaran (Kami) bagi orang-orang yang bersyukur.'),
  ('id.indonesian', 7, 59, 'Sesungguhnya Kami telah mengutus Nuh kepada kaumnya lalu ia berkata: "Wahai kaumku sembahlah Allah, sekali-kali tak ada Tuhan bagimu selain-Nya". Sesungguhnya (kalau kamu tidak menyembah Allah), aku takut kamu akan ditimpa azab hari yang besar (kiamat).'),
  ('id.indonesian', 7, 60, 'Pemuka-pemuka dari kaumnya berkata: "Sesungguhnya kami memandang kamu berada dalam kesesatan yang nyata".'),
  ('id.indonesian', 7, 61, 'Nuh menjawab: "Hai kaumku, tak ada padaku kesesatan sedikitpun tetapi aku adalah utusan dari Tuhan semesta alam".'),
  ('id.indonesian', 7, 62, '"Aku sampaikan kepadamu amanat-amanat Tuhanku dan aku memberi nasehat kepadamu. dan aku mengetahui dari Allah apa yang tidak kamu ketahui".'),
  ('id.indonesian', 7, 63, 'Dan apakah kamu (tidak percaya) dan heran bahwa datang kepada kamu peringatan dari Tuhanmu dengan perantaraan seorang laki-laki dari golonganmu agar dia memberi peringatan kepadamu dan mudah-mudahan kamu bertakwa dan supaya kamu mendapat rahmat?'),
  ('id.indonesian', 7, 64, 'Maka mereka mendustakan Nuh, kemudian Kami selamatkan dia dan orang-orang yang bersamanya dalam bahtera, dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami. Sesungguhnya mereka adalah kaum yang buta (mata hatinya).'),
  ('id.indonesian', 7, 65, 'Dan (Kami telah mengutus) kepada kaum \'Aad saudara mereka, Hud. Ia berkata: "Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain dari-Nya. Maka mengapa kamu tidak bertakwa kepada-Nya?"'),
  ('id.indonesian', 7, 66, 'Pemuka-pemuka yang kafir dari kaumnya berkata: "Sesungguhnya kami benar benar memandang kamu dalam keadaan kurang akal dan sesungguhnya kami menganggap kamu termasuk orang orang yang berdusta".'),
  ('id.indonesian', 7, 67, 'Hud herkata "Hai kaumku, tidak ada padaku kekurangan akal sedikitpun, tetapi aku ini adalah utusan dari Tuhan semesta alam.'),
  ('id.indonesian', 7, 68, 'Aku menyampaikan amanat-amanat Tuhanku kepadamu dan aku hanyalah pemberi nasehat yang terpercaya bagimu".'),
  ('id.indonesian', 7, 69, 'Apakah kamu (tidak percaya) dan heran bahwa datang kepadamu peringatan dari Tuhanmu yang dibawa oleh seorang laki-laki di antaramu untuk memberi peringatan kepadamu? Dan ingatlah oleh kamu sekalian di waktu Allah menjadikan kamu sebagai pengganti-pengganti (yang berkuasa) sesudah lenyapnya kaum Nuh, dan Tuhan telah melebihkan kekuatan tubuh dan perawakanmu (daripada kaum Nuh itu). Maka ingatlah nikmat-nikmat Allah supaya kamu mendapat keberuntungan.'),
  ('id.indonesian', 7, 70, 'Mereka berkata: "Apakah kamu datang kepada kami, agar kami hanya menyembah Allah saja dan meninggalkan apa yang biasa disembah oleh bapak-bapak kami? maka datangkanlah azab yang kamu ancamkan kepada kami jika kamu termasuk orang-orang yang benar".'),
  ('id.indonesian', 7, 71, 'Ia berkata: "Sungguh sudah pasti kamu akan ditimpa azab dan kemarahan dari Tuhanmu". Apakah kamu sekalian hendak berbantah dengan aku tentang nama-nama (berhala) yang kamu beserta nenek moyangmu menamakannya, padahal Allah sekali-kali tidak menurunkan hujjah untuk itu? Maka tunggulah (azab itu), sesungguhnya aku juga termasuk orang yamg menunggu bersama kamu".'),
  ('id.indonesian', 7, 72, 'Maka kami selamatkan Hud beserta orang-orang yang bersamanya dengan rahmat yang besar dari Kami, dan Kami tumpas orang-orang yang mendustakan ayat-ayat Kami, dan tiadalah mereka orang-orang yang beriman.'),
  ('id.indonesian', 7, 73, 'Dan (Kami telah mengutus) kepada kaum Tsamud saudara mereka Shaleh. Ia berkata: "Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang bukti yang nyata kepadamu dari Tuhanmu. Unta betina Allah ini menjadi tanda bagimu, maka biarkanlah dia makan di bumi Allah, dan janganlah kamu mengganggunya dengan gangguan apapun, (yang karenanya) kamu akan ditimpa siksaan yang pedih".'),
  ('id.indonesian', 7, 74, 'Dan ingatlah olehmu di waktu Tuhan menjadikam kamu pengganti-pengganti (yang berkuasa) sesudah kaum \'Aad dan memberikan tempat bagimu di bumi. Kamu dirikan istana-istana di tanah-tanahnya yang datar dan kamu pahat gunung-gunungnya untuk dijadikan rumah; maka ingatlah nikmat-nikmat Allah dan janganlah kamu merajalela di muka bumi membuat kerusakan.'),
  ('id.indonesian', 7, 75, 'Pemuka-pemuka yang menyombongkan diri di antara kaumnya berkata kepada orang-orang yang dianggap lemah yang telah beriman di antara mereka: "Tahukah kamu bahwa Shaleh di utus (menjadi rasul) oleh Tuhannya?". Mereka menjawab: "Sesungguhnya kami beriman kepada wahyu, yang Shaleh diutus untuk menyampaikannya".'),
  ('id.indonesian', 7, 76, 'Orang-orang yang menyombongkan diri berkata: "Sesungguhnya kami adalah orang yang tidak percaya kepada apa yang kamu imani itu".'),
  ('id.indonesian', 7, 77, 'Kemudian mereka sembelih unta betina itu, dan mereka berlaku angkuh terhadap perintah Tuhan. Dan mereka berkata: "Hai Shaleh, datangkanlah apa yang kamu ancamkan itu kepada kami, jika (betul) kamu termasuk orang-orang yang diutus (Allah)".'),
  ('id.indonesian', 7, 78, 'Karena itu mereka ditimpa gempa, maka jadilah mereka mayat-mayat yang bergelimpangan di tempat tinggal mereka.'),
  ('id.indonesian', 7, 79, 'Maka Shaleh meninggalkan mereka seraya berkata: "Hai kaumku sesungguhnya aku telah menyampaikan kepadamu amanat Tuhanku, dan aku telah memberi nasehat kepadamu, tetapi kamu tidak menyukai orang-orang yang memberi nasehat".'),
  ('id.indonesian', 7, 80, 'Dan (Kami juga telah mengutus) Luth (kepada kaumnya). (Ingatlah) tatkala dia berkata kepada mereka: "Mengapa kamu mengerjakan perbuatan faahisyah itu, yang belum pernah dikerjakan oleh seorangpun (di dunia ini) sebelummu?"'),
  ('id.indonesian', 7, 81, 'Sesungguhnya kamu mendatangi lelaki untuk melepaskan nafsumu (kepada mereka), bukan kepada wanita, malah kamu ini adalah kaum yang melampaui batas.'),
  ('id.indonesian', 7, 82, 'Jawab kaumnya tidak lain hanya mengatakan: "Usirlah mereka (Luth dan pengikut-pengikutnya) dari kotamu ini; sesungguhnya mereka adalah orang-orang yang berpura-pura mensucikan diri".'),
  ('id.indonesian', 7, 83, 'Kemudian Kami selamatkan dia dan pengikut-pengikutnya kecuali isterinya; dia termasuk orang-orang yang tertinggal (dibinasakan).'),
  ('id.indonesian', 7, 84, 'Dan Kami turunkan kepada mereka hujan (batu); maka perhatikanlah bagaimana kesudahan orang-orang yang berdosa itu.'),
  ('id.indonesian', 7, 85, 'Dan (Kami telah mengutus) kepada penduduk Mad-yan saudara mereka, Syu\'aib. Ia berkata: "Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang kepadamu bukti yang nyata dari Tuhanmu. Maka sempurnakanlah takaran dan timbangan dan janganlah kamu kurangkan bagi manusia barang-barang takaran dan timbangannya, dan janganlah kamu membuat kerusakan di muka bumi sesudah Tuhan memperbaikinya. Yang demikian itu lebih baik bagimu jika betul-betul kamu orang-orang yang beriman".'),
  ('id.indonesian', 7, 86, 'Dan janganlah kamu duduk di tiap-tiap jalan dengan menakut-nakuti dan menghalang-halangi orang yang beriman dari jalan Allah, dan menginginkan agar jalan Allah itu menjadi bengkok. Dan ingatlah di waktu dahulunya kamu berjumlah sedikit, lalu Allah memperbanyak jumlah kamu. Dan perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerusakan.'),
  ('id.indonesian', 7, 87, 'Jika ada segolongan daripada kamu beriman kepada apa yang aku diutus untuk menyampaikannya dan ada (pula) segolongan yang tidak beriman, maka bersabarlah, hingga Allah menetapkan hukumnya di antara kita; dan Dia adalah Hakim yang sebaik-baiknya.'),
  ('id.indonesian', 7, 88, 'Pemuka-pemuka dan kaum Syu\'aib yang menyombongkan dan berkata: "Sesungguhnya kami akan mengusir kamu hai Syu\'aib dan orang-orang yang beriman bersamamu dari kota kami, atau kamu kembali kepada agama kami". Berkata Syu\'aib: "Dan apakah (kamu akan mengusir kami), kendatipun kami tidak menyukainya?"'),
  ('id.indonesian', 7, 89, 'Sungguh kami mengada-adakan kebohongan yang benar terhadap Allah, jika kami kembali kepada agamamu, sesudah Allah melepaskan kami dari padanya. Dan tidaklah patut kami kembali kepadanya, kecuali jika Allah, Tuhan kami menghendaki(nya). Pengetahuan Tuhan kami meliputi segala sesuatu. Kepada Allah sajalah kami bertawakkal. Ya Tuhan kami, berilah keputusan antara kami dan kaum kami dengan hak (adil) dan Engkaulah Pemberi keputusan yang sebaik-baiknya.'),
  ('id.indonesian', 7, 90, 'Pemuka-pemuka kaum Syu\'aib yang kafir berkata (kepada sesamanya): "Sesungguhnya jika kamu mengikuti Syu\'aib, tentu kamu jika berbuat demikian (menjadi) orang-orang yang merugi".'),
  ('id.indonesian', 7, 91, 'Kemudian mereka ditimpa gempa, maka jadilah mereka mayat-mayat yang bergelimpangan di dalam rumah-rumah mereka,'),
  ('id.indonesian', 7, 92, '(yaitu) orang-orang yang mendustakan Syu\'aib seolah-olah mereka belum pernah berdiam di kota itu; orang-orang yang mendustakan Syu\'aib mereka itulah orang-orang yang merugi.'),
  ('id.indonesian', 7, 93, 'Maka Syu\'aib meninggalkan mereka seraya berkata: "Hai kaumku, sesungguhnya aku telah menyampaikan kepadamu amanat-amanat Tuhanku dan aku telah memberi nasehat kepadamu. Maka bagaimana aku akan bersedih hati terhadap orang-orang yang kafir?"'),
  ('id.indonesian', 7, 94, 'Kami tidaklah mengutus seseorang nabipun kepada sesuatu negeri, (lalu penduduknya mendustakan nabi itu), melainkan Kami timpakan kepada penduduknya kesempitan dan penderitaan supaya mereka tunduk dengan merendahkan diri.'),
  ('id.indonesian', 7, 95, 'Kemudian Kami ganti kesusahan itu dengan kesenangan hingga keturunan dan harta mereka bertambah banyak, dan mereka berkata: "Sesungguhnya nenek moyang kamipun telah merasai penderitaan dan kesenangan", maka Kami timpakan siksaan atas mereka dengan sekonyong-konyong sedang mereka tidak menyadarinya.'),
  ('id.indonesian', 7, 96, 'Jikalau sekiranya penduduk negeri-negeri beriman dan bertakwa, pastilah Kami akan melimpahkan kepada mereka berkah dari langit dan bumi, tetapi mereka mendustakan (ayat-ayat Kami) itu, maka Kami siksa mereka disebabkan perbuatannya.'),
  ('id.indonesian', 7, 97, 'Maka apakah penduduk negeri-negeri itu merasa aman dari kedatangan siksaan Kami kepada mereka di malam hari di waktu mereka sedang tidur?'),
  ('id.indonesian', 7, 98, 'Atau apakah penduduk negeri-negeri itu merasa aman dari kedatangan siksaan Kami kepada mereka di waktu matahari sepenggalahan naik ketika mereka sedang bermain?'),
  ('id.indonesian', 7, 99, 'Maka apakah mereka merasa aman dari azab Allah (yang tidak terduga-duga)? Tiada yang merasa aman dan azab Allah kecuali orang-orang yang merugi.'),
  ('id.indonesian', 7, 100, 'Dan apakah belum jelas bagi orang-orang yang mempusakai suatu negeri sesudah (lenyap) penduduknya, bahwa kalau Kami menghendaki tentu Kami azab mereka karena dosa-dosanya; dan Kami kunci mati hati mereka sehingga mereka tidak dapat mendengar (pelajaran lagi)?'),
  ('id.indonesian', 7, 101, 'Negeri-negeri (yang telah Kami binasakan) itu, Kami ceritakan sebagian dari berita-beritanya kepadamu. Dan sungguh telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti yang nyata, maka mereka (juga) tidak beriman kepada apa yang dahulunya mereka telah mendustakannya. Demikianlah Allah mengunci mata hati orang-orang kafir.'),
  ('id.indonesian', 7, 102, 'Dan Kami tidak mendapati kebanyakan mereka memenuhi janji. Sesungguhnya Kami mendapati kebanyakan mereka orang-orang yang fasik.'),
  ('id.indonesian', 7, 103, 'Kemudian Kami utus Musa sesudah rasul-rasul itu dengan membawa ayat-ayat Kami kepada Fir\'aun dan pemuka-pemuka kaumnya, lalu mereka mengingkari ayat-ayat itu. Maka perhatikanlah bagaimana akibat orang-orang yang membuat kerusakan.'),
  ('id.indonesian', 7, 104, 'Dan Musa berkata: "Hai Fir\'aun, sesungguhnya aku ini adalah seorang utusan dari Tuhan semesta alam,'),
  ('id.indonesian', 7, 105, 'wajib atasku tidak mengatakan sesuatu terhadap Allah, kecuali yang hak. Sesungguhnya aku datang kepadamu dengan membawa bukti yang nyata dari Tuhanmu, maka lepaskanlah Bani Israil (pergi) bersama aku".'),
  ('id.indonesian', 7, 106, 'Fir\'aun menjawab: "Jika benar kamu membawa sesuatu bukti, maka datangkanlah bukti itu jika (betul) kamu termasuk orang-orang yang benar".'),
  ('id.indonesian', 7, 107, 'Maka Musa menjatuhkan tongkat-nya, lalu seketika itu juga tongkat itu menjadi ular yang sebenarnya.'),
  ('id.indonesian', 7, 108, 'Dan ia mengeluarkan tangannya, maka ketika itu juga tangan itu menjadi putih bercahaya (kelihatan) oleh orang-orang yang melihatnya.'),
  ('id.indonesian', 7, 109, 'Pemuka-pemuka kaum Fir\'aun berkata: "Sesungguhnya Musa ini adalah ahli sihir yang pandai,'),
  ('id.indonesian', 7, 110, 'yang bermaksud hendak mengeluarkan kamu dari negerimu". (Fir\'aun berkata): "Maka apakah yang kamu anjurkan?"'),
  ('id.indonesian', 7, 111, 'Pemuka-pemuka itu menjawab: "Beri tangguhlah dia dan saudaranya serta kirimlah ke kota-kota beberapa orang yang akan mengumpulkan (ahli-ahli sihir),'),
  ('id.indonesian', 7, 112, 'supaya mereka membawa kepadamu semua ahli sihir yang pandai".'),
  ('id.indonesian', 7, 113, 'Dan beberapa ahli sihir itu datang kepada Fir\'aun mengatakan: "(Apakah) sesungguhnya kami akan mendapat upah, jika kamilah yang menang?"'),
  ('id.indonesian', 7, 114, 'Fir\'aun menjawab: "Ya, dan sesungguhnya kamu benar-benar akan termasuk orang-orang yang dekat (kepadaku)".'),
  ('id.indonesian', 7, 115, 'Ahli-ahli sihir berkata: "Hai Musa, kamukah yang akan melemparkan lebih dahulu, ataukah kami yang akan melemparkan?"'),
  ('id.indonesian', 7, 116, 'Musa menjawab: "Lemparkanlah (lebih dahulu)!" Maka tatkala mereka melemparkan, mereka menyulap mata orang dan menjadikan orang banyak itu takut, serta mereka mendatangkan sihir yang besar (mena\'jubkan).'),
  ('id.indonesian', 7, 117, 'Dan Kami wahyukan kepada Musa: "Lemparkanlah tongkatmu!". Maka sekonyong-konyong tongkat itu menelan apa yang mereka sulapkan.'),
  ('id.indonesian', 7, 118, 'Karena itu nyatalah yang benar dan batallah yang selalu mereka kerjakan.'),
  ('id.indonesian', 7, 119, 'Maka mereka kalah di tempat itu dan jadilah mereka orang-orang yang hina.'),
  ('id.indonesian', 7, 120, 'Dan ahli-ahli sihir itu serta merta meniarapkan diri dengan bersujud.'),
  ('id.indonesian', 7, 121, 'Mereka berkata: "Kami beriman kepada Tuhan semesta alam,'),
  ('id.indonesian', 7, 122, '"(yaitu) Tuhan Musa dan Harun".'),
  ('id.indonesian', 7, 123, 'Fir\'aun berkata: "Apakah kamu beriman kepadanya sebelum aku memberi izin kepadamu?, sesungguhnya (perbuatan ini) adalah suatu muslihat yang telah kamu rencanakan di dalam kota ini, untuk mengeluarkan penduduknya dari padanya; maka kelak kamu akan mengetahui (akibat perbuatanmu ini);'),
  ('id.indonesian', 7, 124, 'demi, sesungguhnya aku akan memotong tangan dan kakimu dengan bersilang secara bertimbal balik, kemudian sungguh-sungguh aku akan menyalib kamu semuanya".'),
  ('id.indonesian', 7, 125, 'Ahli-ahli sihir itu menjawab: "Sesungguhnya kepada Tuhanlah kami kembali.'),
  ('id.indonesian', 7, 126, 'Dan kamu tidak menyalahkan kami, melainkan karena kami telah beriman kepada ayat-ayat Tuhan kami ketika ayat-ayat itu datang kepada kami". (Mereka berdoa): "Ya Tuhan kami, limpahkanlah kesabaran kepada kami dan wafatkanlah kami dalam keadaan berserah diri (kepada-Mu)".'),
  ('id.indonesian', 7, 127, 'Berkatalah pembesar-pembesar dari kaum Fir\'aun (kepada Fir\'aun): "Apakah kamu membiarkan Musa dan kaumnya untuk membuat kerusakan di negeri ini (Mesir) dan meninggalkan kamu serta tuhan-tuhanmu?". Fir\'aun menjawab: "Akan kita bunuh anak-anak lelaki mereka dan kita biarkan hidup perempuan-perempuan mereka; dan sesungguhnya kita berkuasa penuh di atas mereka".'),
  ('id.indonesian', 7, 128, 'Musa berkata kepada kaumnya: "Mohonlah pertolongan kepada Allah dan bersabarlah; sesungguhnya bumi (ini) kepunyaan Allah; dipusakakan-Nya kepada siapa yang dihendaki-Nya dari hamba-hamba-Nya. Dan kesudahan yang baik adalah bagi orang-orang yang bertakwa".'),
  ('id.indonesian', 7, 129, 'Kaum Musa berkata: "Kami telah ditindas (oleh Fir\'aun) sebelum kamu datang kepada kami dan sesudah kamu datang. Musa menjawab: "Mudah-mudahan Allah membinasakan musuhmu dan menjadikan kamu khalifah di bumi(Nya), maka Allah akan melihat bagaimana perbuatanmu.'),
  ('id.indonesian', 7, 130, 'Dan sesungguhnya Kami telah menghukum (Fir\'aun dan) kaumnya dengan (mendatangkan) musim kemarau yang panjang dan kekurangan buah-buahan, supaya mereka mengambil pelajaran.'),
  ('id.indonesian', 7, 131, 'Kemudian apabila datang kepada mereka kemakmuran, mereka berkata: "Itu adalah karena (usaha) kami". Dan jika mereka ditimpa kesusahan, mereka lemparkan sebab kesialan itu kepada Musa dan orang-orang yang besertanya. Ketahuilah, sesungguhnya kesialan mereka itu adalah ketetapan dari Allah, akan tetapi kebanyakan mereka tidak mengetahui.'),
  ('id.indonesian', 7, 132, 'Mereka berkata: "Bagaimanapun kamu mendatangkan keterangan kepada kami untuk menyihir kami dengan keterangan itu, maka kami sekali-kali tidak akan beriman kepadamu".'),
  ('id.indonesian', 7, 133, 'Maka Kami kirimkan kepada mereka taufan, belalang, kutu, katak dan darah sebagai bukti yang jelas, tetapi mereka tetap menyombongkan diri dan mereka adalah kaum yang berdosa.'),
  ('id.indonesian', 7, 134, 'Dan ketika mereka ditimpa azab (yang telah diterangkan itu) merekapun berkata: "Hai Musa, mohonkanlah untuk kami kepada Tuhamnu dengan (perantaraan) kenabian yang diketahui Allah ada pada sisimu. Sesungguhnya jika kamu dapat menghilangkan azab itu dan pada kami, pasti kami akan beriman kepadamu dan akan kami biarkan Bani Israil pergi bersamamu".'),
  ('id.indonesian', 7, 135, 'Maka setelah Kami hilangkan azab itu dari mereka hingga batas waktu yang mereka sampai kepadanya, tiba-tiba mereka mengingkarinya.'),
  ('id.indonesian', 7, 136, 'Kemudian Kami menghukum mereka, maka Kami tenggelamkan mereka di laut disebabkan mereka mendustakan ayat-ayat Kami dan mereka adalah orang-orang yang melalaikan ayat-ayat Kami itu.'),
  ('id.indonesian', 7, 137, 'Dan Kami pusakakan kepada kaum yang telah ditindas itu, negeri-negeri bahagian timur bumi dan bahagian baratnya yang telah Kami beri berkah padanya. Dan telah sempurnalah perkataan Tuhanmu yang baik (sebagai janji) untuk Bani Israil disebabkan kesabaran mereka. Dan Kami hancurkan apa yang telah dibuat Fir\'aun dan kaumnya dan apa yang telah dibangun mereka.'),
  ('id.indonesian', 7, 138, 'Dan Kami seberangkan Bani Israil ke seberang lautan itu, maka setelah mereka sampai kepada suatu kaum yang tetap menyembah berhala mereka, Bani lsrail berkata: "Hai Musa. buatlah untuk kami sebuah tuhan (berhala) sebagaimana mereka mempunyai beberapa tuhan (berhala)". Musa menjawab: "Sesungguh-nya kamu ini adalah kaum yang tidak mengetahui (sifat-sifat Tuhan)".'),
  ('id.indonesian', 7, 139, 'Sesungguhnya mereka itu akan dihancurkan kepercayaan yang dianutnya dan akan batal apa yang seIalu mereka kerjakan.'),
  ('id.indonesian', 7, 140, 'Musa menjawab: "Patutkah aku mencari Tuhan untuk kamu yang selain dari pada Allah, padahal Dialah yang telah melebihkan kamu atas segala umat.'),
  ('id.indonesian', 7, 141, 'Dan (ingatlah hai Bani Israil), ketika Kami menyelamatkan kamu dari (Fir\'aun) dan kaumnya, yang mengazab kamu dengan azab yang sangat jahat, yaitu mereka membunuh anak-anak lelakimu dan membiarkan hidup wanita-wanitamu. Dan pada yang demikian itu cobaan yang besar dari Tuhanmu".'),
  ('id.indonesian', 7, 142, 'Dan telah Kami janjikan kepada Musa (memberikan Taurat) sesudah berlalu waktu tiga puluh malam, dan Kami sempurnakan jumlah malam itu dengan sepuluh (malam lagi), maka sempurnalah waktu yang telah ditentukan Tuhannya empat puluh malam. Dan berkata Musa kepada saudaranya yaitu Harun: "Gantikanlah aku dalam (memimpin) kaumku, dan perbaikilah, dan janganlah kamu mengikuti jalan orang-orang yang membuat kerusakan".'),
  ('id.indonesian', 7, 143, 'Dan tatkala Musa datang untuk (munajat dengan Kami) pada waktu yang telah Kami tentukan dan Tuhan telah berfirman (langsung) kepadanya, berkatalah Musa: "Ya Tuhanku, nampakkanlah (diri Engkau) kepadaku agar aku dapat melihat kepada Engkau". Tuhan berfirman: "Kamu sekali-kali tidak sanggup melihat-Ku, tapi lihatlah ke bukit itu, maka jika ia tetap di tempatnya (sebagai sediakala) niscaya kamu dapat melihat-Ku". Tatkala Tuhannya menampakkan diri kepada gunung itu, dijadikannya gunung itu hancur luluh dan Musa pun jatuh pingsan. Maka setelah Musa sadar kembali, dia berkata: "Maha Suci Engkau, aku bertaubat kepada Engkau dan aku orang yang pertama-tama beriman".'),
  ('id.indonesian', 7, 144, 'Allah berfirman: "Hai Musa, sesungguhnya Aku memilih (melebihkan) kamu dan manusia yang lain (di masamu) untuk membawa risalah-Ku dan untuk berbicara langsung dengan-Ku, sebab itu berpegang teguhlah kepada apa yang Aku berikan kepadamu dan hendaklah kamu termasuk orang-orang yang bersyukur".'),
  ('id.indonesian', 7, 145, 'Dan telah Kami tuliskan untuk Musa pada luh-luh (Taurat) segala sesuatu sebagai pelajaran dan penjelasan bagi segala sesuatu; maka (Kami berfirman): "Berpeganglah kepadanya dengan teguh dan suruhlah kaummu berpegang kepada (perintah-perintahnya) dengan sebaik-baiknya, nanti Aku akan memperlihatkan kepadamu negeri orang-orang yang fasik.'),
  ('id.indonesian', 7, 146, 'Aku akan memalingkan orang-orang yang menyombongkan dirinya di muka bumi tanpa alasan yang benar dari tanda-tanda kekuasaan-Ku. Mereka jika melihat tiap-tiap ayat(Ku), mereka tidak beriman kepadanya. Dan jika mereka melihat jalan yang membawa kepada petunjuk, mereka tidak mau menempuhnya, tetapi jika mereka melihat jalan kesesatan, mereka terus memenempuhnya. Yang demikian itu adalah karena mereka mendustakan ayat-ayat Kami dan mereka selalu lalai dari padanya.'),
  ('id.indonesian', 7, 147, 'Dan orang-orang yang mendustakan ayat-ayat Kami dan mendustakan akan menemui akhirat, sia-sialah perbuatan mereka. Mereka tidak diberi balasan selain dari apa yang telah mereka kerjakan.'),
  ('id.indonesian', 7, 148, 'Dan kaum Musa, setelah kepergian Musa ke gunung Thur membuat dari perhiasan-perhiasan (emas) mereka anak lembu yang bertubuh dan bersuara. Apakah mereka tidak mengetahui bahwa anak lembu itu tidak dapat berbicara dengan mereka dan tidak dapat (pula) menunjukkan jalan kepada mereka? Mereka menjadikannya (sebagai sembahan) dan mereka adalah orang-orang yang zalim.'),
  ('id.indonesian', 7, 149, 'Dan setelah mereka sangat menyesali perbuatannya dan mengetahui bahwa mereka telah sesat, merekapun berkata: "Sungguh jika Tuhan kami tidak memberi rahmat kepada kami dan tidak mengampuni kami, pastilah kami menjadi orang-orang yang merugi".'),
  ('id.indonesian', 7, 150, 'Dan tatkala Musa telah kembali kepada kaumnya dengan marah dan sedih hati berkatalah dia: "Alangkah buruknya perbuatan yang kamu kerjakan sesudah kepergianku! Apakah kamu hendak mendahului janji Tuhanmu? Dan Musapun melemparkan luh-luh (Taurat) itu dan memegang (rambut) kepala saudaranya (Harun) sambil menariknya ke arahnya, Harun berkata: "Hai anak ibuku, sesungguhnya kaum ini telah menganggapku lemah dan hampir-hampir mereka membunuhku, sebab itu janganlah kamu menjadikan musuh-musuh gembira melihatku, dan janganlah kamu masukkan aku ke dalam golongan orang-orang yang zalim"'),
  ('id.indonesian', 7, 151, 'Musa berdoa: "Ya Tuhanku, ampunilah aku dan saudaraku dan masukkanlah kami ke dalam rahmat Engkau, dan Engkau adalah Maha Penyayang di antara para penyayang".'),
  ('id.indonesian', 7, 152, 'Sesungguhnya orang-orang yang menjadikan anak lembu (sebagai sembahannya), kelak akan menimpa mereka kemurkaan dari Tuhan mereka dan kehinaan dalam kehidupan di dunia. Demikianlah Kami memberi balasan kepada orang-orang yang membuat-buat kebohongan.'),
  ('id.indonesian', 7, 153, 'Orang-orang yang mengerjakan kejahatan, kemudian bertaubat sesudah itu dan beriman; sesungguhnya Tuhan kamu sesudah taubat yang disertai dengan iman itu adalah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 7, 154, 'Sesudah amarah Musa menjadi reda, lalu diambilnya (kembali) luh-luh (Taurat) itu; dan dalam tulisannya terdapat petunjuk dan rahmat untuk orang-orang yang takut kepada Tuhannya.'),
  ('id.indonesian', 7, 155, 'Dan Musa memilih tujuh puluh orang dari kaumnya untuk (memohonkan taubat kepada Kami) pada waktu yang telah Kami tentukan. Maka ketika mereka digoncang gempa bumi, Musa berkata: "Ya Tuhanku, kalau Engkau kehendaki, tentulah Engkau membinasakan mereka dan aku sebelum ini. Apakah Engkau membinasakan kami karena perbuatan orang-orang yang kurang akal di antara kami? Itu hanyalah cobaan dari Engkau, Engkau sesatkan dengan cobaan itu siapa yang Engkau kehendaki dan Engkau beri petunjuk kepada siapa yang Engkau kehendaki. Engkaulah Yang memimpin kami, maka ampunilah kami dan berilah kami rahmat dan Engkaulah Pemberi ampun yang sebaik-baiknya".'),
  ('id.indonesian', 7, 156, 'Dan tetapkanlah untuk kami kebajikan di dunia ini dan di akhirat; sesungguhnya kami kembali (bertaubat) kepada Engkau. Allah berfirman: "Siksa-Ku akan Kutimpakan kepada siapa yang Aku kehendaki dan rahmat-Ku meliputi segala sesuatu. Maka akan Aku tetapkan rahmat-Ku untuk orang-orang yang bertakwa, yang menunaikan zakat dan orang-orang yang beriman kepada ayat-ayat Kami".'),
  ('id.indonesian', 7, 157, '(Yaitu) orang-orang yang mengikut Rasul, Nabi yang ummi yang (namanya) mereka dapati tertulis di dalam Taurat dan Injil yang ada di sisi mereka, yang menyuruh mereka mengerjakan yang ma\'ruf dan melarang mereka dari mengerjakan yang mungkar dan menghalalkan bagi mereka segala yang baik dan mengharamkan bagi mereka segala yang buruk dan membuang dari mereka beban-beban dan belenggu-belenggu yang ada pada mereka. Maka orang-orang yang beriman kepadanya. memuliakannya, menolongnya dan mengikuti cahaya yang terang yang diturunkan kepadanya (Al Quran), mereka itulah orang-orang yang beruntung.'),
  ('id.indonesian', 7, 158, 'Katakanlah: "Hai manusia sesungguhnya aku adalah utusan Allah kepadamu semua, yaitu Allah Yang mempunyai kerajaan langit dan bumi; tidak ada Tuhan (yang berhak disembah) selain Dia, Yang menghidupkan dan mematikan, maka berimanlah kamu kepada Allah dan Rasul-Nya, Nabi yang ummi yang beriman kepada Allah dan kepada kalimat-kalimat-Nya (kitab-kitab-Nya) dan ikutilah dia, supaya kamu mendapat petunjuk".'),
  ('id.indonesian', 7, 159, 'Dan di antara kaum Musa itu terdapat suatu umat yang memberi petunjuk (kepada manusia) dengan hak dan dengan yang hak itulah mereka menjalankan keadilan.'),
  ('id.indonesian', 7, 160, 'Dan mereka Kami bagi menjadi dua belas suku yang masing-masingnya berjumlah besar dan Kami wahyukan kepada Musa ketika kaumnya meminta air kepadanya: "Pukullah batu itu dengan tongkatmu!". Maka memancarlah dari padanya duabelas mata air. Sesungguhnya tiap-tiap suku mengetahui tempat minum masing-masing. Dan Kami naungkan awan di atas mereka dan Kami turunkan kepada mereka manna dan salwa. (Kami berfirman): "Makanlah yang baik-baik dari apa yang telah Kami rezekikan kepadamu". Mereka tidak menganiaya Kami, tapi merekalah yang selalu menganiaya dirinya sendiri.'),
  ('id.indonesian', 7, 161, 'Dan (ingatlah), ketika dikatakan kepada mereka (Bani Israil): "Diamlah di negeri ini saja (Baitul Maqdis) dan makanlah dari (hasil bumi)nya di mana saja kamu kehendaki". Dan katakanlah: "Bebaskanlah kami dari dosa kami dan masukilah pintu gerbangnya sambil membungkuk, niscaya Kami ampuni kesalahan-kesalahanmu". Kelak akan Kami tambah (pahala) kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 7, 162, 'Maka orang-orang yang zalim di antara mereka itu mengganti (perkataan itu) dengan perkataan yang tidak dikatakan kepada mereka, maka Kami timpakan kepada mereka azab dari langit disebabkan kezaliman mereka.'),
  ('id.indonesian', 7, 163, 'Dan tanyakanlah kepada Bani Israil tentang negeri yang terletak di dekat laut ketika mereka melanggar aturan pada hari Sabtu, di waktu datang kepada mereka ikan-ikan (yang berada di sekitar) mereka terapung-apung di permukaan air, dan di hari-hari yang bukan Sabtu, ikan-ikan itu tidak datang kepada mereka. Demikianlah Kami mencoba mereka disebabkan mereka berlaku fasik.'),
  ('id.indonesian', 7, 164, 'Dan (ingatlah) ketika suatu umat di antara mereka berkata: "Mengapa kamu menasehati kaum yang Allah akan membinasakan mereka atau mengazab mereka dengan azab yang amat keras?" Mereka menjawab: "Agar kami mempunyai alasan (pelepas tanggung jawab) kepada Tuhanmu, dan supaya mereka bertakwa.'),
  ('id.indonesian', 7, 165, 'Maka tatkala mereka melupakan apa yang diperingatkan kepada mereka, Kami selamatkan orang-orang yang melarang dari perbuatan jahat dan Kami timpakan kepada orang-orang yang zalim siksaan yang keras, disebabkan mereka selalu berbuat fasik.'),
  ('id.indonesian', 7, 166, 'Maka tatkala mereka bersikap sombong terhadap apa yang dilarang mereka mengerjakannya, Kami katakan kepadanya: "Jadilah kamu kera yang hina.'),
  ('id.indonesian', 7, 167, 'Dan (ingatlah), ketika Tuhanmu memberitahukan, bahwa sesungguhnya Dia akan mengirim kepada mereka (orang-orang Yahudi) sampai hari kiamat orang-orang yang akan menimpakan kepada mereka azab yang seburuk-buruknya. Sesungguhnya Tuhanmu amat cepat siksa-Nya, dan sesungguhnya Dia adalah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 7, 168, 'Dan Kami bagi-bagi mereka di dunia ini menjadi beberapa golongan; di antaranya ada orang-orang yang saleh dan di antaranya ada yang tidak demikian. Dan Kami coba mereka dengan (nikmat) yang baik-baik dan (bencana) yang buruk-buruk, agar mereka kembali (kepada kebenaran).'),
  ('id.indonesian', 7, 169, 'Maka datanglah sesudah mereka generasi (yang jahat) yang mewarisi Taurat, yang mengambil harta benda dunia yang rendah ini, dan berkata: "Kami akan diberi ampun". Dan kelak jika datang kepada mereka harta benda dunia sebanyak itu (pula), niscaya mereka akan mengambilnya (juga). Bukankah perjanjian Taurat sudah diambil dari mereka, yaitu bahwa mereka tidak akan mengatakan terhadap Allah kecuali yang benar, padahal mereka telah mempelajari apa yang tersebut di dalamnya?. Dan kampung akhirat itu lebih bagi mereka yang bertakwa. Maka apakah kamu sekalian tidak mengerti?'),
  ('id.indonesian', 7, 170, 'Dan orang-orang yang berpegang teguh dengan Al Kitab (Taurat) serta mendirikan shalat, (akan diberi pahala) karena sesungguhnya Kami tidak menyia-nyiakan pahala orang-orang yang mengadakan perbaikan.'),
  ('id.indonesian', 7, 171, 'Dan (ingatlah), ketika Kami mengangkat bukit ke atas mereka seakan-akan bukit itu naungan awan dan mereka yakin bahwa bukit itu akan jatuh menimpa mereka. (Dan Kami katakan kepada mereka): "Peganglah dengan teguh apa yang telah Kami berikan kepadamu, serta ingatlah selalu (amalkanlah) apa yang tersebut di dalamnya supaya kamu menjadi orang-orang yang bertakwa".'),
  ('id.indonesian', 7, 172, 'Dan (ingatlah), ketika Tuhanmu mengeluarkan keturunan anak-anak Adam dari sulbi mereka dan Allah mengambil kesaksian terhadap jiwa mereka (seraya berfirman): "Bukankah Aku ini Tuhanmu?" Mereka menjawab: "Betul (Engkau Tuhan kami), kami menjadi saksi". (Kami lakukan yang demikian itu) agar di hari kiamat kamu tidak mengatakan: "Sesungguhnya kami (bani Adam) adalah orang-orang yang lengah terhadap ini (keesaan Tuhan)",'),
  ('id.indonesian', 7, 173, 'atau agar kamu tidak mengatakan: "Sesungguhnya orang-orang tua kami telah mempersekutukan Tuhan sejak dahulu, sedang kami ini adalah anak-anak keturunan yang (datang) sesudah mereka. Maka apakah Engkau akan membinasakan kami karena perbuatan orang-orang yang sesat dahulu?"'),
  ('id.indonesian', 7, 174, 'Dan demikianlah Kami menjelaskan ayat-ayat itu, agar mereka kembali (kepada kebenaran).'),
  ('id.indonesian', 7, 175, 'Dan bacakanlah kepada mereka berita orang yang telah Kami berikan kepadanya ayat-ayat Kami (pengetahuan tentang isi Al Kitab), kemudian dia melepaskan diri dari pada ayat-ayat itu, lalu dia diikuti oleh syaitan (sampai dia tergoda), maka jadilah dia termasuk orang-orang yang sesat.'),
  ('id.indonesian', 7, 176, 'Dan kalau Kami menghendaki, sesungguhnya Kami tinggikan (derajat)nya dengan ayat-ayat itu, tetapi dia cenderung kepada dunia dan menurutkan hawa nafsunya yang rendah, maka perumpamaannya seperti anjing jika kamu menghalaunya diulurkannya lidahnya dan jika kamu membiarkannya dia mengulurkan lidahnya (juga). Demikian itulah perumpamaan orang-orang yang mendustakan ayat-ayat Kami. Maka ceritakanlah (kepada mereka) kisah-kisah itu agar mereka berfikir.'),
  ('id.indonesian', 7, 177, 'Amat buruklah perumpamaan orang-orang yang mendustakan ayat-ayat Kami dan kepada diri mereka sendirilah mereka berbuat zalim.'),
  ('id.indonesian', 7, 178, 'Barangsiapa yang diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk; dan barangsiapa yang disesatkan Allah, maka merekalah orang-orang yang merugi.'),
  ('id.indonesian', 7, 179, 'Dan sesungguhnya Kami jadikan untuk (isi neraka Jahannam) kebanyakan dari jin dan manusia, mereka mempunyai hati, tetapi tidak dipergunakannya untuk memahami (ayat-ayat Allah) dan mereka mempunyai mata (tetapi) tidak dipergunakannya untuk melihat (tanda-tanda kekuasaan Allah), dan mereka mempunyai telinga (tetapi) tidak dipergunakannya untuk mendengar (ayat-ayat Allah). Mereka itu sebagai binatang ternak, bahkan mereka lebih sesat lagi. Mereka itulah orang-orang yang lalai.'),
  ('id.indonesian', 7, 180, 'Hanya milik Allah asmaa-ul husna, maka bermohonlah kepada-Nya dengan menyebut asmaa-ul husna itu dan tinggalkanlah orang-orang yang menyimpang dari kebenaran dalam (menyebut) nama-nama-Nya. Nanti mereka akan mendapat balasan terhadap apa yang telah mereka kerjakan.'),
  ('id.indonesian', 7, 181, 'Dan di antara orang-orang yang Kami ciptakan ada umat yang memberi petunjuk dengan hak, dan dengan yang hak itu (pula) mereka menjalankan keadilan.'),
  ('id.indonesian', 7, 182, 'Dan orang-orang yang mendustakan ayat-ayat Kami, nanti Kami akan menarik mereka dengan berangaur-angsur (ke arah kebinasaan), dengan cara yang tidak mereka ketahui.'),
  ('id.indonesian', 7, 183, 'Dan Aku memberi tangguh kepada mereka. Sesungguhnya rencana-Ku amat teguh.'),
  ('id.indonesian', 7, 184, 'Apakah (mereka lalai) dan tidak memikirkan bahwa teman mereka (Muhammad) tidak berpenyakit gila. Dia (Muhammad itu) tidak lain hanyalah seorang pemberi peringatan lagi pemberi penjelasan.'),
  ('id.indonesian', 7, 185, 'Dan apakah mereka tidak memperhatikan kerajaan langit dan bumi dan segala sesuatu yang diciptakan Allah, dan kemungkinan telah dekatnya kebinasaan mereka? Maka kepada berita manakah lagi mereka akan beriman sesudah Al Quran itu?'),
  ('id.indonesian', 7, 186, 'Barangsiapa yang Allah sesatkan, maka baginya tak ada orang yang akan memberi petunjuk. Dan Allah membiarkan mereka terombang-ambing dalam kesesatan.'),
  ('id.indonesian', 7, 187, 'Mereka menanyakan kepadamu tentang kiamat: "Bilakah terjadinya?" Katakanlah: "Sesungguhnya pengetahuan tentang kiamat itu adalah pada sisi Tuhanku; tidak seorangpun yang dapat menjelaskan waktu kedatangannya selain Dia. Kiamat itu amat berat (huru haranya bagi makhluk) yang di langit dan di bumi. Kiamat itu tidak akan datang kepadamu melainkan dengan tiba-tiba". Mereka bertanya kepadamu seakan-akan kamu benar-benar mengetahuinya. Katakanlah: "Sesungguhnya pengetahuan tentang bari kiamat itu adalah di sisi Allah, tetapi kebanyakan manusia tidak mengetahui".'),
  ('id.indonesian', 7, 188, 'Katakanlah: "Aku tidak berkuasa menarik kemanfaatan bagi diriku dan tidak (pula) menolak kemudharatan kecuali yang dikehendaki Allah. Dan sekiranya aku mengetahui yang ghaib, tentulah aku membuat kebajikan sebanyak-banyaknya dan aku tidak akan ditimpa kemudharatan. Aku tidak lain hanyalah pemberi peringatan, dan pembawa berita gembira bagi orang-orang yang beriman".'),
  ('id.indonesian', 7, 189, 'Dialah Yang menciptakan kamu dari diri yang satu dan dari padanya Dia menciptakan isterinya, agar dia merasa senang kepadanya. Maka setelah dicampurinya, isterinya itu mengandung kandungan yang ringan, dan teruslah dia merasa ringan (beberapa waktu). Kemudian tatkala dia merasa berat, keduanya (suami-isteri) bermohon kepada Allah, Tuhannya seraya berkata: "Sesungguhnya jika Engkau memberi kami anak yang saleh, tentulah kami termasuk orang-orang yang bersyukur".'),
  ('id.indonesian', 7, 190, 'Tatkala Allah memberi kepada keduanya seorang anak yang sempurna, maka keduanya menjadikan sekutu bagi Allah terhadap anak yang telah dianugerahkan-Nya kepada keduanya itu. Maka Maha Tinggi Allah dari apa yang mereka persekutukan.'),
  ('id.indonesian', 7, 191, 'Apakah mereka mempersekutukan (Allah dengan) berhada-berhala yang tak dapat menciptakan sesuatupun? Sedangkan berhala-berhala itu sendiri buatan orang.'),
  ('id.indonesian', 7, 192, 'Dan berhala-berhala itu tidak mampu memberi pertolongan kepada penyembah-penyembahnya dan kepada dirinya sendiripun berhala-berha]a itu tidak dapat memberi pertolongan.'),
  ('id.indonesian', 7, 193, 'Dan jika kamu (hai orang-orang musyrik) menyerunya (berhala) untuk memberi petunjuk kepadamu, tidaklah berhala-berhala itu dapat memperkenankan seruanmu; sama saja (hasilnya) buat kamu menyeru mereka ataupun kamu herdiam diri.'),
  ('id.indonesian', 7, 194, 'Sesungguhnya berhala-berhala yang kamu seru selain Allah itu adalah makhluk (yang lemah) yang serupa juga dengan kamu. Maka serulah berhala-berhala itu lalu biarkanlah mereka mmperkenankan permintaanmu, jika kamu memang orang-orang yang benar.'),
  ('id.indonesian', 7, 195, 'Apakah berhala-berhala mempunyai kaki yang dengan itu ia dapat berjalan, atau mempunyai tangan yang dengan itu ia dapat memegang dengan keras, atau mempunyai mata yang dengan itu ia dapat melihat, atau mempunyai telinga yang dengan itu ia dapat mendengar? Katakanlah: "Panggillah berhala-berhalamu yang kamu jadikan sekutu Allah, kemudian lakukanlah tipu daya (untuk mencelakakan)-ku. tanpa memberi tangguh (kepada-ku)".'),
  ('id.indonesian', 7, 196, 'Sesungguhnya pelindungku ialahlah Yang telah menurunkan Al Kitab (Al Quran) dan Dia melindungi orang-orang yang saleh.'),
  ('id.indonesian', 7, 197, 'Dan berhala-berhala yang kamu seru selain Allah tidaklah sanggup menolongmu, bahkan tidak dapat menolong dirinya sendiri.'),
  ('id.indonesian', 7, 198, 'Dan jika kamu sekalian menyeru (berhala-berhala) untuk memberi petunjuk, niscaya berhala-herhala itu tidak dapat mendengarnya. Dan kamu melihat berhala-berhala itu memandang kepadamu padahal ia tidak melihat.'),
  ('id.indonesian', 7, 199, 'Jadilah engkau pemaaf dan suruhlah orang mengerjakan yang ma\'ruf, serta berpalinglah dari pada orang-orang yang bodoh.'),
  ('id.indonesian', 7, 200, 'Dan jika kamu ditimpa sesuatu godaan syaitan maka berlindunglah kepada Allah')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 7, 201, 'Sesungguhnya orang-orang yang bertakwa bila mereka ditimpa was-was dari syaitan, mereka ingat kepada Allah, maka ketika itu juga mereka melihat kesalahan-kesalahannya.'),
  ('id.indonesian', 7, 202, 'Dan teman-teman mereka (orang-orang kafir dan fasik) membantu syaitan-syaitan dalam menyesatkan dan mereka tidak henti-hentinya (menyesatkan).'),
  ('id.indonesian', 7, 203, 'Dan apabila kamu tidak membawa suatu ayat Al Quran kepada mereka, mereka berkata: "Mengapa tidak kamu buat sendiri ayat itu?" Katakanlah: "Sesungguhnya aku hanya mengikut apa yang diwahyukan dari Tuhanku kepadaku. Al Quran ini adalah bukti-bukti yang nyata dari Tuhanmu, petunjuk dan rahmat bagi orang-orang yang beriman".'),
  ('id.indonesian', 7, 204, 'Dan apabila dibacakan Al Quran, maka dengarkanlah baik-baik, dan perhatikanlah dengan tenang agar kamu mendapat rahmat.'),
  ('id.indonesian', 7, 205, 'Dan sebutlah (nama) Tuhanmu dalam hatimu dengan merendahkan diri dan rasa takut, dan dengan tidak mengeraskan suara, di waktu pagi dan petang, dan janganlah kamu termasuk orang-orang yang lalai.'),
  ('id.indonesian', 7, 206, 'Sesungguhnya malaikat-malaikat yang ada di sisi Tuhanmu tidaklah merasa enggan menyembah Allah dan mereka mentasbihkan-Nya dan hanya kepada-Nya-lah mereka bersujud.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (7, 47, 1001, '۞ وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 156, 8, 63, 0),
  (7, 48, 1002, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلْأَعْرَافِ رِجَالًۭا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ', 156, 8, 63, 0),
  (7, 49, 1003, 'أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ۚ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ', 156, 8, 63, 0),
  (7, 50, 1004, 'وَنَادَىٰٓ أَصْحَٰبُ ٱلنَّارِ أَصْحَٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ ۚ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَٰفِرِينَ', 156, 8, 63, 0),
  (7, 51, 1005, 'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًۭا وَلَعِبًۭا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 156, 8, 63, 0),
  (7, 52, 1006, 'وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍۢ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 157, 8, 63, 0),
  (7, 53, 1007, 'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ ۚ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ ۚ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 157, 8, 63, 0),
  (7, 54, 1008, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 157, 8, 63, 0),
  (7, 55, 1009, 'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًۭا وَخُفْيَةً ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ', 157, 8, 63, 0),
  (7, 56, 1010, 'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا وَٱدْعُوهُ خَوْفًۭا وَطَمَعًا ۚ إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌۭ مِّنَ ٱلْمُحْسِنِينَ', 157, 8, 63, 0),
  (7, 57, 1011, 'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۖ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًۭا ثِقَالًۭا سُقْنَٰهُ لِبَلَدٍۢ مَّيِّتٍۢ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ ۚ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ', 157, 8, 63, 0),
  (7, 58, 1012, 'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ ۖ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًۭا ۚ كَذَٰلِكَ نُصَرِّفُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَشْكُرُونَ', 158, 8, 63, 0),
  (7, 59, 1013, 'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍۢ', 158, 8, 63, 0),
  (7, 60, 1014, 'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 158, 8, 63, 0),
  (7, 61, 1015, 'قَالَ يَٰقَوْمِ لَيْسَ بِى ضَلَٰلَةٌۭ وَلَٰكِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 158, 8, 63, 0),
  (7, 62, 1016, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 158, 8, 63, 0),
  (7, 63, 1017, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌۭ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍۢ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ', 158, 8, 63, 0),
  (7, 64, 1018, 'فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ', 158, 8, 63, 0),
  (7, 65, 1019, '۞ وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۚ أَفَلَا تَتَّقُونَ', 158, 8, 64, 0),
  (7, 66, 1020, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍۢ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَٰذِبِينَ', 158, 8, 64, 0),
  (7, 67, 1021, 'قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌۭ وَلَٰكِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 158, 8, 64, 0),
  (7, 68, 1022, 'أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ', 159, 8, 64, 0),
  (7, 69, 1023, 'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌۭ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍۢ مِّنكُمْ لِيُنذِرَكُمْ ۚ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍۢ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةًۭ ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ', 159, 8, 64, 0),
  (7, 70, 1024, 'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا ۖ فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 159, 8, 64, 0),
  (7, 71, 1025, 'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌۭ وَغَضَبٌ ۖ أَتُجَٰدِلُونَنِى فِىٓ أَسْمَآءٍۢ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍۢ ۚ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 159, 8, 64, 0),
  (7, 72, 1026, 'فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۖ وَمَا كَانُوا۟ مُؤْمِنِينَ', 159, 8, 64, 0),
  (7, 73, 1027, 'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ ۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةًۭ ۖ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ ۖ وَلَا تَمَسُّوهَا بِسُوٓءٍۢ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌۭ', 159, 8, 64, 0),
  (7, 74, 1028, 'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍۢ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًۭا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًۭا ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 160, 8, 64, 0),
  (7, 75, 1029, 'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَٰلِحًۭا مُّرْسَلٌۭ مِّن رَّبِّهِۦ ۚ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ', 160, 8, 64, 0),
  (7, 76, 1030, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ', 160, 8, 64, 0),
  (7, 77, 1031, 'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ', 160, 8, 64, 0),
  (7, 78, 1032, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 160, 8, 64, 0),
  (7, 79, 1033, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ', 160, 8, 64, 0),
  (7, 80, 1034, 'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍۢ مِّنَ ٱلْعَٰلَمِينَ', 160, 8, 64, 0),
  (7, 81, 1035, 'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةًۭ مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌۭ مُّسْرِفُونَ', 160, 8, 64, 0),
  (7, 82, 1036, 'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌۭ يَتَطَهَّرُونَ', 161, 8, 64, 0),
  (7, 83, 1037, 'فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ', 161, 8, 64, 0),
  (7, 84, 1038, 'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًۭا ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ', 161, 8, 64, 0),
  (7, 85, 1039, 'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ ۖ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ', 161, 8, 64, 0),
  (7, 86, 1040, 'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍۢ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًۭا ۚ وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًۭا فَكَثَّرَكُمْ ۖ وَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 161, 8, 64, 0),
  (7, 87, 1041, 'وَإِن كَانَ طَآئِفَةٌۭ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌۭ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا ۚ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 161, 8, 64, 0),
  (7, 88, 1042, '۞ قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۚ قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ', 162, 9, 65, 0),
  (7, 89, 1043, 'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا ۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا ۚ وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا ۚ عَلَى ٱللَّهِ تَوَكَّلْنَا ۚ رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ', 162, 9, 65, 0),
  (7, 90, 1044, 'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًۭا لَّخَٰسِرُونَ', 162, 9, 65, 0),
  (7, 91, 1045, 'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ', 162, 9, 65, 0),
  (7, 92, 1046, 'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًۭا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ۚ ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًۭا كَانُوا۟ هُمُ ٱلْخَٰسِرِينَ', 162, 9, 65, 0),
  (7, 93, 1047, 'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّى وَنَصَحْتُ لَكُمْ ۖ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍۢ كَٰفِرِينَ', 162, 9, 65, 0),
  (7, 94, 1048, 'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍۢ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ', 162, 9, 65, 0),
  (7, 95, 1049, 'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 162, 9, 65, 0),
  (7, 96, 1050, 'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍۢ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ', 163, 9, 65, 0),
  (7, 97, 1051, 'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًۭا وَهُمْ نَآئِمُونَ', 163, 9, 65, 0),
  (7, 98, 1052, 'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًۭى وَهُمْ يَلْعَبُونَ', 163, 9, 65, 0),
  (7, 99, 1053, 'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ ۚ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَٰسِرُونَ', 163, 9, 65, 0),
  (7, 100, 1054, 'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَٰهُم بِذُنُوبِهِمْ ۚ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ', 163, 9, 65, 0),
  (7, 101, 1055, 'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَٰفِرِينَ', 163, 9, 65, 0),
  (7, 102, 1056, 'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍۢ ۖ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ', 163, 9, 65, 0),
  (7, 103, 1057, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ', 163, 9, 65, 0),
  (7, 104, 1058, 'وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 163, 9, 65, 0),
  (7, 105, 1059, 'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ قَدْ جِئْتُكُم بِبَيِّنَةٍۢ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ', 164, 9, 65, 0),
  (7, 106, 1060, 'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍۢ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 164, 9, 65, 0),
  (7, 107, 1061, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌۭ مُّبِينٌۭ', 164, 9, 65, 0),
  (7, 108, 1062, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 164, 9, 65, 0),
  (7, 109, 1063, 'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌۭ', 164, 9, 65, 0),
  (7, 110, 1064, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ ۖ فَمَاذَا تَأْمُرُونَ', 164, 9, 65, 0),
  (7, 111, 1065, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 164, 9, 65, 0),
  (7, 112, 1066, 'يَأْتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٍۢ', 164, 9, 65, 0),
  (7, 113, 1067, 'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 164, 9, 65, 0),
  (7, 114, 1068, 'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ', 164, 9, 65, 0),
  (7, 115, 1069, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ', 164, 9, 65, 0),
  (7, 116, 1070, 'قَالَ أَلْقُوا۟ ۖ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍۢ', 164, 9, 65, 0),
  (7, 117, 1071, '۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 164, 9, 66, 0),
  (7, 118, 1072, 'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ', 164, 9, 66, 0),
  (7, 119, 1073, 'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَٰغِرِينَ', 164, 9, 66, 0),
  (7, 120, 1074, 'وَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 164, 9, 66, 0),
  (7, 121, 1075, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 165, 9, 66, 0),
  (7, 122, 1076, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 165, 9, 66, 0),
  (7, 123, 1077, 'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّ هَٰذَا لَمَكْرٌۭ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا ۖ فَسَوْفَ تَعْلَمُونَ', 165, 9, 66, 0),
  (7, 124, 1078, 'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍۢ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 165, 9, 66, 0),
  (7, 125, 1079, 'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 165, 9, 66, 0),
  (7, 126, 1080, 'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا ۚ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًۭا وَتَوَفَّنَا مُسْلِمِينَ', 165, 9, 66, 0),
  (7, 127, 1081, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ ۚ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ', 165, 9, 66, 0),
  (7, 128, 1082, 'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ ۖ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ', 165, 9, 66, 0),
  (7, 129, 1083, 'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا ۚ قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', 165, 9, 66, 0),
  (7, 130, 1084, 'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍۢ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ', 165, 9, 66, 0),
  (7, 131, 1085, 'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَٰذِهِۦ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۭ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ ۗ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 166, 9, 66, 0),
  (7, 132, 1086, 'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍۢ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 166, 9, 66, 0),
  (7, 133, 1087, 'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٍۢ مُّفَصَّلَٰتٍۢ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًۭا مُّجْرِمِينَ', 166, 9, 66, 0),
  (7, 134, 1088, 'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ ۖ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ', 166, 9, 66, 0),
  (7, 135, 1089, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ', 166, 9, 66, 0),
  (7, 136, 1090, 'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 166, 9, 66, 0),
  (7, 137, 1091, 'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا ۖ وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ ۖ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ', 166, 9, 66, 0),
  (7, 138, 1092, 'وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍۢ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍۢ لَّهُمْ ۚ قَالُوا۟ يَٰمُوسَى ٱجْعَل لَّنَآ إِلَٰهًۭا كَمَا لَهُمْ ءَالِهَةٌۭ ۚ قَالَ إِنَّكُمْ قَوْمٌۭ تَجْهَلُونَ', 167, 9, 66, 0),
  (7, 139, 1093, 'إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٌۭ مَّا هُمْ فِيهِ وَبَٰطِلٌۭ مَّا كَانُوا۟ يَعْمَلُونَ', 167, 9, 66, 0),
  (7, 140, 1094, 'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًۭا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ', 167, 9, 66, 0),
  (7, 141, 1095, 'وَإِذْ أَنجَيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ ۖ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌۭ مِّن رَّبِّكُمْ عَظِيمٌۭ', 167, 9, 66, 0),
  (7, 142, 1096, '۞ وَوَٰعَدْنَا مُوسَىٰ ثَلَٰثِينَ لَيْلَةًۭ وَأَتْمَمْنَٰهَا بِعَشْرٍۢ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةًۭ ۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ', 167, 9, 67, 0),
  (7, 143, 1097, 'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ ۚ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى ۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّۭا وَخَرَّ مُوسَىٰ صَعِقًۭا ۚ فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ', 167, 9, 67, 0),
  (7, 144, 1098, 'قَالَ يَٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِى وَبِكَلَٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 168, 9, 67, 0),
  (7, 145, 1099, 'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍۢ مَّوْعِظَةًۭ وَتَفْصِيلًۭا لِّكُلِّ شَىْءٍۢ فَخُذْهَا بِقُوَّةٍۢ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا ۚ سَأُو۟رِيكُمْ دَارَ ٱلْفَٰسِقِينَ', 168, 9, 67, 0),
  (7, 146, 1100, 'سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍۢ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًۭا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًۭا ۚ ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ', 168, 9, 67, 0),
  (7, 147, 1101, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْءَاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ', 168, 9, 67, 0),
  (7, 148, 1102, 'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًۭا جَسَدًۭا لَّهُۥ خُوَارٌ ۚ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ۘ ٱتَّخَذُوهُ وَكَانُوا۟ ظَٰلِمِينَ', 168, 9, 67, 0),
  (7, 149, 1103, 'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 168, 9, 67, 0),
  (7, 150, 1104, 'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًۭا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ ۖ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ ۖ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ ۚ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 169, 9, 67, 0),
  (7, 151, 1105, 'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ ۖ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 169, 9, 67, 0),
  (7, 152, 1106, 'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌۭ مِّن رَّبِّهِمْ وَذِلَّةٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ', 169, 9, 67, 0),
  (7, 153, 1107, 'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌۭ', 169, 9, 67, 0),
  (7, 154, 1108, 'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ ۖ وَفِى نُسْخَتِهَا هُدًۭى وَرَحْمَةٌۭ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ', 169, 9, 67, 0),
  (7, 155, 1109, 'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًۭا لِّمِيقَٰتِنَا ۖ فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰىَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ ۖ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ ۖ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا ۖ وَأَنتَ خَيْرُ ٱلْغَٰفِرِينَ', 169, 9, 67, 0),
  (7, 156, 1110, '۞ وَٱكْتُبْ لَنَا فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةًۭ وَفِى ٱلْءَاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍۢ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤْمِنُونَ', 170, 9, 68, 0),
  (7, 157, 1111, 'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ ۙ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 170, 9, 68, 0),
  (7, 158, 1112, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ', 170, 9, 68, 0),
  (7, 159, 1113, 'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌۭ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 170, 9, 68, 0),
  (7, 160, 1114, 'وَقَطَّعْنَٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًۭا ۚ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًۭا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍۢ مَّشْرَبَهُمْ ۚ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ ۚ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 171, 9, 68, 0),
  (7, 161, 1115, 'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌۭ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًۭا نَّغْفِرْ لَكُمْ خَطِيٓـَٰٔتِكُمْ ۚ سَنَزِيدُ ٱلْمُحْسِنِينَ', 171, 9, 68, 0),
  (7, 162, 1116, 'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًۭا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ', 171, 9, 68, 0),
  (7, 163, 1117, 'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًۭا وَيَوْمَ لَا يَسْبِتُونَ ۙ لَا تَأْتِيهِمْ ۚ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ', 171, 9, 68, 0),
  (7, 164, 1118, 'وَإِذْ قَالَتْ أُمَّةٌۭ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ۙ ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًۭا شَدِيدًۭا ۖ قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ', 172, 9, 68, 0),
  (7, 165, 1119, 'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ', 172, 9, 68, 0),
  (7, 166, 1120, 'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ', 172, 9, 68, 0),
  (7, 167, 1121, 'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ ۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ ۖ وَإِنَّهُۥ لَغَفُورٌۭ رَّحِيمٌۭ', 172, 9, 68, 0),
  (7, 168, 1122, 'وَقَطَّعْنَٰهُمْ فِى ٱلْأَرْضِ أُمَمًۭا ۖ مِّنْهُمُ ٱلصَّٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ ۖ وَبَلَوْنَٰهُم بِٱلْحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ', 172, 9, 68, 0),
  (7, 169, 1123, 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌۭ وَرِثُوا۟ ٱلْكِتَٰبَ يَأْخُذُونَ عَرَضَ هَٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌۭ مِّثْلُهُۥ يَأْخُذُوهُ ۚ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَٰقُ ٱلْكِتَٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ ۗ وَٱلدَّارُ ٱلْءَاخِرَةُ خَيْرٌۭ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ', 172, 9, 68, 0),
  (7, 170, 1124, 'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ', 172, 9, 68, 0),
  (7, 171, 1125, '۞ وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌۭ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍۢ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ', 173, 9, 69, 0),
  (7, 172, 1126, 'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ ۛ شَهِدْنَآ ۛ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ', 173, 9, 69, 0),
  (7, 173, 1127, 'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةًۭ مِّنۢ بَعْدِهِمْ ۖ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ', 173, 9, 69, 0),
  (7, 174, 1128, 'وَكَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ', 173, 9, 69, 0),
  (7, 175, 1129, 'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ', 173, 9, 69, 0),
  (7, 176, 1130, 'وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ ۚ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۚ فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ', 173, 9, 69, 0),
  (7, 177, 1131, 'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ', 173, 9, 69, 0),
  (7, 178, 1132, 'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى ۖ وَمَن يُضْلِلْ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 173, 9, 69, 0),
  (7, 179, 1133, 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًۭا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ لَهُمْ قُلُوبٌۭ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌۭ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌۭ لَّا يَسْمَعُونَ بِهَآ ۚ أُو۟لَٰٓئِكَ كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 174, 9, 69, 0),
  (7, 180, 1134, 'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ', 174, 9, 69, 0),
  (7, 181, 1135, 'وَمِمَّنْ خَلَقْنَآ أُمَّةٌۭ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ', 174, 9, 69, 0),
  (7, 182, 1136, 'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 174, 9, 69, 0),
  (7, 183, 1137, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', 174, 9, 69, 0),
  (7, 184, 1138, 'أَوَلَمْ يَتَفَكَّرُوا۟ ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌۭ مُّبِينٌ', 174, 9, 69, 0),
  (7, 185, 1139, 'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍۢ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 174, 9, 69, 0),
  (7, 186, 1140, 'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ ۚ وَيَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 174, 9, 69, 0),
  (7, 187, 1141, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى ۖ لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ۚ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ لَا تَأْتِيكُمْ إِلَّا بَغْتَةًۭ ۗ يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 174, 9, 69, 0),
  (7, 188, 1142, 'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًۭا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ ۚ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ ۚ إِنْ أَنَا۠ إِلَّا نَذِيرٌۭ وَبَشِيرٌۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 175, 9, 69, 0),
  (7, 189, 1143, '۞ هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا ۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًۭا فَمَرَّتْ بِهِۦ ۖ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَٰلِحًۭا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 175, 9, 70, 0),
  (7, 190, 1144, 'فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحًۭا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا ۚ فَتَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ', 175, 9, 70, 0),
  (7, 191, 1145, 'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ', 175, 9, 70, 0),
  (7, 192, 1146, 'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًۭا وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 175, 9, 70, 0),
  (7, 193, 1147, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ ۚ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَٰمِتُونَ', 175, 9, 70, 0),
  (7, 194, 1148, 'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ ۖ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَٰدِقِينَ', 175, 9, 70, 0),
  (7, 195, 1149, 'أَلَهُمْ أَرْجُلٌۭ يَمْشُونَ بِهَآ ۖ أَمْ لَهُمْ أَيْدٍۢ يَبْطِشُونَ بِهَآ ۖ أَمْ لَهُمْ أَعْيُنٌۭ يُبْصِرُونَ بِهَآ ۖ أَمْ لَهُمْ ءَاذَانٌۭ يَسْمَعُونَ بِهَا ۗ قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ', 175, 9, 70, 0),
  (7, 196, 1150, 'إِنَّ وَلِۦِّىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَٰبَ ۖ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ', 176, 9, 70, 0),
  (7, 197, 1151, 'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ', 176, 9, 70, 0),
  (7, 198, 1152, 'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ ۖ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ', 176, 9, 70, 0),
  (7, 199, 1153, 'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ', 176, 9, 70, 0),
  (7, 200, 1154, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌۭ فَٱسْتَعِذْ بِٱللَّهِ ۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ', 176, 9, 70, 0),
  (7, 201, 1155, 'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَٰٓئِفٌۭ مِّنَ ٱلشَّيْطَٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ', 176, 9, 70, 0),
  (7, 202, 1156, 'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ', 176, 9, 70, 0),
  (7, 203, 1157, 'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍۢ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا ۚ قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى ۚ هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًۭى وَرَحْمَةٌۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 176, 9, 70, 0),
  (7, 204, 1158, 'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ', 176, 9, 70, 0),
  (7, 205, 1159, 'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًۭا وَخِيفَةًۭ وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْءَاصَالِ وَلَا تَكُن مِّنَ ٱلْغَٰفِلِينَ', 176, 9, 70, 0),
  (7, 206, 1160, 'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ ۩', 176, 9, 70, 1),
  (8, 1, 1161, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ ۖ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ', 177, 9, 71, 0),
  (8, 2, 1162, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَٰتُهُۥ زَادَتْهُمْ إِيمَٰنًۭا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 177, 9, 71, 0),
  (8, 3, 1163, 'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 177, 9, 71, 0),
  (8, 4, 1164, 'أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّۭا ۚ لَّهُمْ دَرَجَٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 177, 9, 71, 0),
  (8, 5, 1165, 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًۭا مِّنَ ٱلْمُؤْمِنِينَ لَكَٰرِهُونَ', 177, 9, 71, 0),
  (8, 6, 1166, 'يُجَٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَمَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ', 177, 9, 71, 0),
  (8, 7, 1167, 'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَٰفِرِينَ', 177, 9, 71, 0),
  (8, 8, 1168, 'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 177, 9, 71, 0),
  (8, 9, 1169, 'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍۢ مِّنَ ٱلْمَلَٰٓئِكَةِ مُرْدِفِينَ', 178, 9, 71, 0),
  (8, 10, 1170, 'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ ۚ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ', 178, 9, 71, 0),
  (8, 11, 1171, 'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةًۭ مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءًۭ لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ', 178, 9, 71, 0),
  (8, 12, 1172, 'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ ۚ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍۢ', 178, 9, 71, 0),
  (8, 13, 1173, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 178, 9, 71, 0),
  (8, 14, 1174, 'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَٰفِرِينَ عَذَابَ ٱلنَّارِ', 178, 9, 71, 0),
  (8, 15, 1175, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًۭا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ', 178, 9, 71, 0),
  (8, 16, 1176, 'وَمَن يُوَلِّهِمْ يَوْمَئِذٍۢ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًۭا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍۢ فَقَدْ بَآءَ بِغَضَبٍۢ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 178, 9, 71, 0),
  (8, 17, 1177, 'فَلَمْ تَقْتُلُوهُمْ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمْ ۚ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ ۚ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 179, 9, 71, 0),
  (8, 18, 1178, 'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَٰفِرِينَ', 179, 9, 71, 0),
  (8, 19, 1179, 'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ ۖ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌۭ لَّكُمْ ۖ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًۭٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ', 179, 9, 71, 0),
  (8, 20, 1180, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ', 179, 9, 71, 0),
  (8, 21, 1181, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ', 179, 9, 71, 0),
  (8, 22, 1182, '۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ', 179, 9, 72, 0),
  (8, 23, 1183, 'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًۭا لَّأَسْمَعَهُمْ ۖ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 179, 9, 72, 0),
  (8, 24, 1184, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ', 179, 9, 72, 0),
  (8, 25, 1185, 'وَٱتَّقُوا۟ فِتْنَةًۭ لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةًۭ ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 179, 9, 72, 0),
  (8, 26, 1186, 'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌۭ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمْ تَشْكُرُونَ', 180, 9, 72, 0),
  (8, 27, 1187, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَٰنَٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ', 180, 9, 72, 0),
  (8, 28, 1188, 'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌۭ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ', 180, 9, 72, 0),
  (8, 29, 1189, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًۭا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 180, 9, 72, 0),
  (8, 30, 1190, 'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ ۚ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَٰكِرِينَ', 180, 9, 72, 0),
  (8, 31, 1191, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَٰذَآ ۙ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 180, 9, 72, 0),
  (8, 32, 1192, 'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةًۭ مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍۢ', 180, 9, 72, 0),
  (8, 33, 1193, 'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ ۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ', 180, 9, 72, 0),
  (8, 34, 1194, 'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ ۚ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 181, 9, 72, 0),
  (8, 35, 1195, 'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءًۭ وَتَصْدِيَةًۭ ۚ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 181, 9, 72, 0),
  (8, 36, 1196, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةًۭ ثُمَّ يُغْلَبُونَ ۗ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ', 181, 9, 72, 0),
  (8, 37, 1197, 'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍۢ فَيَرْكُمَهُۥ جَمِيعًۭا فَيَجْعَلَهُۥ فِى جَهَنَّمَ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 181, 9, 72, 0),
  (8, 38, 1198, 'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ', 181, 9, 72, 0),
  (8, 39, 1199, 'وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌۭ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ ۚ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌۭ', 181, 9, 72, 0),
  (8, 40, 1200, 'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ ۚ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 181, 9, 72, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 8, 1, 'They ask you, [O Muhammad], about the bounties [of war]. Say, "The [decision concerning] bounties is for Allah and the Messenger." So fear Allah and amend that which is between you and obey Allah and His Messenger, if you should be believers.'),
  ('en.sahih', 8, 2, 'The believers are only those who, when Allah is mentioned, their hearts become fearful, and when His verses are recited to them, it increases them in faith; and upon their Lord they rely -'),
  ('en.sahih', 8, 3, 'The ones who establish prayer, and from what We have provided them, they spend.'),
  ('en.sahih', 8, 4, 'Those are the believers, truly. For them are degrees [of high position] with their Lord and forgiveness and noble provision.'),
  ('en.sahih', 8, 5, '[It is] just as when your Lord brought you out of your home [for the battle of Badr] in truth, while indeed, a party among the believers were unwilling,'),
  ('en.sahih', 8, 6, 'Arguing with you concerning the truth after it had become clear, as if they were being driven toward death while they were looking on.'),
  ('en.sahih', 8, 7, '[Remember, O believers], when Allah promised you one of the two groups - that it would be yours - and you wished that the unarmed one would be yours. But Allah intended to establish the truth by His words and to eliminate the disbelievers'),
  ('en.sahih', 8, 8, 'That He should establish the truth and abolish falsehood, even if the criminals disliked it.'),
  ('en.sahih', 8, 9, '[Remember] when you asked help of your Lord, and He answered you, "Indeed, I will reinforce you with a thousand from the angels, following one another."'),
  ('en.sahih', 8, 10, 'And Allah made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allah. Indeed, Allah is Exalted in Might and Wise.'),
  ('en.sahih', 8, 11, '[Remember] when He overwhelmed you with drowsiness [giving] security from Him and sent down upon you from the sky, rain by which to purify you and remove from you the evil [suggestions] of Satan and to make steadfast your hearts and plant firmly thereby your feet.'),
  ('en.sahih', 8, 12, '[Remember] when your Lord inspired to the angels, "I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip."'),
  ('en.sahih', 8, 13, 'That is because they opposed Allah and His Messenger. And whoever opposes Allah and His Messenger - indeed, Allah is severe in penalty.'),
  ('en.sahih', 8, 14, '"That [is yours], so taste it." And indeed for the disbelievers is the punishment of the Fire.'),
  ('en.sahih', 8, 15, 'O you who have believed, when you meet those who disbelieve advancing [for battle], do not turn to them your backs [in flight].'),
  ('en.sahih', 8, 16, 'And whoever turns his back to them on such a day, unless swerving [as a strategy] for war or joining [another] company, has certainly returned with anger [upon him] from Allah, and his refuge is Hell - and wretched is the destination.'),
  ('en.sahih', 8, 17, 'And you did not kill them, but it was Allah who killed them. And you threw not, [O Muhammad], when you threw, but it was Allah who threw that He might test the believers with a good test. Indeed, Allah is Hearing and Knowing.'),
  ('en.sahih', 8, 18, 'That [is so], and [also] that Allah will weaken the plot of the disbelievers.'),
  ('en.sahih', 8, 19, 'If you [disbelievers] seek the victory - the defeat has come to you. And if you desist [from hostilities], it is best for you; but if you return [to war], We will return, and never will you be availed by your [large] company at all, even if it should increase; and [that is] because Allah is with the believers.'),
  ('en.sahih', 8, 20, 'O you who have believed, obey Allah and His Messenger and do not turn from him while you hear [his order].'),
  ('en.sahih', 8, 21, 'And do not be like those who say, "We have heard," while they do not hear.'),
  ('en.sahih', 8, 22, 'Indeed, the worst of living creatures in the sight of Allah are the deaf and dumb who do not use reason.'),
  ('en.sahih', 8, 23, 'Had Allah known any good in them, He would have made them hear. And if He had made them hear, they would [still] have turned away, while they were refusing.'),
  ('en.sahih', 8, 24, 'O you who have believed, respond to Allah and to the Messenger when he calls you to that which gives you life. And know that Allah intervenes between a man and his heart and that to Him you will be gathered.'),
  ('en.sahih', 8, 25, 'And fear a trial which will not strike those who have wronged among you exclusively, and know that Allah is severe in penalty.'),
  ('en.sahih', 8, 26, 'And remember when you were few and oppressed in the land, fearing that people might abduct you, but He sheltered you, supported you with His victory, and provided you with good things - that you might be grateful.'),
  ('en.sahih', 8, 27, 'O you who have believed, do not betray Allah and the Messenger or betray your trusts while you know [the consequence].'),
  ('en.sahih', 8, 28, 'And know that your properties and your children are but a trial and that Allah has with Him a great reward.'),
  ('en.sahih', 8, 29, 'O you who have believed, if you fear Allah, He will grant you a criterion and will remove from you your misdeeds and forgive you. And Allah is the possessor of great bounty.'),
  ('en.sahih', 8, 30, 'And [remember, O Muhammad], when those who disbelieved plotted against you to restrain you or kill you or evict you [from Makkah]. But they plan, and Allah plans. And Allah is the best of planners.'),
  ('en.sahih', 8, 31, 'And when Our verses are recited to them, they say, "We have heard. If we willed, we could say [something] like this. This is not but legends of the former peoples."'),
  ('en.sahih', 8, 32, 'And [remember] when they said, "O Allah, if this should be the truth from You, then rain down upon us stones from the sky or bring us a painful punishment."'),
  ('en.sahih', 8, 33, 'But Allah would not punish them while you, [O Muhammad], are among them, and Allah would not punish them while they seek forgiveness.'),
  ('en.sahih', 8, 34, 'But why should Allah not punish them while they obstruct [people] from al-Masjid al- Haram and they were not [fit to be] its guardians? Its [true] guardians are not but the righteous, but most of them do not know.'),
  ('en.sahih', 8, 35, 'And their prayer at the House was not except whistling and handclapping. So taste the punishment for what you disbelieved.'),
  ('en.sahih', 8, 36, 'Indeed, those who disbelieve spend their wealth to avert [people] from the way of Allah. So they will spend it; then it will be for them a [source of] regret; then they will be overcome. And those who have disbelieved - unto Hell they will be gathered.'),
  ('en.sahih', 8, 37, '[This is] so that Allah may distinguish the wicked from the good and place the wicked some of them upon others and heap them all together and put them into Hell. It is those who are the losers.'),
  ('en.sahih', 8, 38, 'Say to those who have disbelieved [that] if they cease, what has previously occurred will be forgiven for them. But if they return [to hostility] - then the precedent of the former [rebellious] peoples has already taken place.'),
  ('en.sahih', 8, 39, 'And fight them until there is no fitnah and [until] the religion, all of it, is for Allah. And if they cease - then indeed, Allah is Seeing of what they do.'),
  ('en.sahih', 8, 40, 'But if they turn away - then know that Allah is your protector. Excellent is the protector, and Excellent is the helper.'),
  ('en.sahih', 8, 41, 'And know that anything you obtain of war booty - then indeed, for Allah is one fifth of it and for the Messenger and for [his] near relatives and the orphans, the needy, and the [stranded] traveler, if you have believed in Allah and in that which We sent down to Our Servant on the day of criterion - the day when the two armies met. And Allah, over all things, is competent.'),
  ('en.sahih', 8, 42, '[Remember] when you were on the near side of the valley, and they were on the farther side, and the caravan was lower [in position] than you. If you had made an appointment [to meet], you would have missed the appointment. But [it was] so that Allah might accomplish a matter already destined - that those who perished [through disbelief] would perish upon evidence and those who lived [in faith] would live upon evidence; and indeed, Allah is Hearing and Knowing.'),
  ('en.sahih', 8, 43, '[Remember, O Muhammad], when Allah showed them to you in your dream as few; and if He had shown them to you as many, you [believers] would have lost courage and would have disputed in the matter [of whether to fight], but Allah saved [you from that]. Indeed, He is Knowing of that within the breasts.'),
  ('en.sahih', 8, 44, 'And [remember] when He showed them to you, when you met, as few in your eyes, and He made you [appear] as few in their eyes so that Allah might accomplish a matter already destined. And to Allah are [all] matters returned.'),
  ('en.sahih', 8, 45, 'O you who have believed, when you encounter a company [from the enemy forces], stand firm and remember Allah much that you may be successful.'),
  ('en.sahih', 8, 46, 'And obey Allah and His Messenger, and do not dispute and [thus] lose courage and [then] your strength would depart; and be patient. Indeed, Allah is with the patient.'),
  ('en.sahih', 8, 47, 'And do not be like those who came forth from their homes insolently and to be seen by people and avert [them] from the way of Allah. And Allah is encompassing of what they do.'),
  ('en.sahih', 8, 48, 'And [remember] when Satan made their deeds pleasing to them and said, "No one can overcome you today from among the people, and indeed, I am your protector." But when the two armies sighted each other, he turned on his heels and said, "Indeed, I am disassociated from you. Indeed, I see what you do not see; indeed I fear Allah. And Allah is severe in penalty."'),
  ('en.sahih', 8, 49, '[Remember] when the hypocrites and those in whose hearts was disease said, "Their religion has deluded those [Muslims]." But whoever relies upon Allah - then indeed, Allah is Exalted in Might and Wise.'),
  ('en.sahih', 8, 50, 'And if you could but see when the angels take the souls of those who disbelieved... They are striking their faces and their backs and [saying], "Taste the punishment of the Burning Fire.'),
  ('en.sahih', 8, 51, 'That is for what your hands have put forth [of evil] and because Allah is not ever unjust to His servants."'),
  ('en.sahih', 8, 52, '[Theirs is] like the custom of the people of Pharaoh and of those before them. They disbelieved in the signs of Allah, so Allah seized them for their sins. Indeed, Allah is Powerful and severe in penalty.'),
  ('en.sahih', 8, 53, 'That is because Allah would not change a favor which He had bestowed upon a people until they change what is within themselves. And indeed, Allah is Hearing and Knowing.'),
  ('en.sahih', 8, 54, '[Theirs is] like the custom of the people of Pharaoh and of those before them. They denied the signs of their Lord, so We destroyed them for their sins, and We drowned the people of Pharaoh. And all [of them] were wrongdoers.'),
  ('en.sahih', 8, 55, 'Indeed, the worst of living creatures in the sight of Allah are those who have disbelieved, and they will not [ever] believe -'),
  ('en.sahih', 8, 56, 'The ones with whom you made a treaty but then they break their pledge every time, and they do not fear Allah.'),
  ('en.sahih', 8, 57, 'So if you, [O Muhammad], gain dominance over them in war, disperse by [means of] them those behind them that perhaps they will be reminded.'),
  ('en.sahih', 8, 58, 'If you [have reason to] fear from a people betrayal, throw [their treaty] back to them, [putting you] on equal terms. Indeed, Allah does not like traitors.'),
  ('en.sahih', 8, 59, 'And let not those who disbelieve think they will escape. Indeed, they will not cause failure [to Allah].'),
  ('en.sahih', 8, 60, 'And prepare against them whatever you are able of power and of steeds of war by which you may terrify the enemy of Allah and your enemy and others besides them whom you do not know [but] whom Allah knows. And whatever you spend in the cause of Allah will be fully repaid to you, and you will not be wronged.'),
  ('en.sahih', 8, 61, 'And if they incline to peace, then incline to it [also] and rely upon Allah. Indeed, it is He who is the Hearing, the Knowing.'),
  ('en.sahih', 8, 62, 'But if they intend to deceive you - then sufficient for you is Allah. It is He who supported you with His help and with the believers'),
  ('en.sahih', 8, 63, 'And brought together their hearts. If you had spent all that is in the earth, you could not have brought their hearts together; but Allah brought them together. Indeed, He is Exalted in Might and Wise.'),
  ('en.sahih', 8, 64, 'O Prophet, sufficient for you is Allah and for whoever follows you of the believers.'),
  ('en.sahih', 8, 65, 'O Prophet, urge the believers to battle. If there are among you twenty [who are] steadfast, they will overcome two hundred. And if there are among you one hundred [who are] steadfast, they will overcome a thousand of those who have disbelieved because they are a people who do not understand.'),
  ('en.sahih', 8, 66, 'Now, Allah has lightened [the hardship] for you, and He knows that among you is weakness. So if there are from you one hundred [who are] steadfast, they will overcome two hundred. And if there are among you a thousand, they will overcome two thousand by permission of Allah. And Allah is with the steadfast.'),
  ('en.sahih', 8, 67, 'It is not for a prophet to have captives [of war] until he inflicts a massacre [upon Allah \'s enemies] in the land. Some Muslims desire the commodities of this world, but Allah desires [for you] the Hereafter. And Allah is Exalted in Might and Wise.'),
  ('en.sahih', 8, 68, 'If not for a decree from Allah that preceded, you would have been touched for what you took by a great punishment.'),
  ('en.sahih', 8, 69, 'So consume what you have taken of war booty [as being] lawful and good, and fear Allah. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 8, 70, 'O Prophet, say to whoever is in your hands of the captives, "If Allah knows [any] good in your hearts, He will give you [something] better than what was taken from you, and He will forgive you; and Allah is Forgiving and Merciful."'),
  ('en.sahih', 8, 71, 'But if they intend to betray you - then they have already betrayed Allah before, and He empowered [you] over them. And Allah is Knowing and Wise.'),
  ('en.sahih', 8, 72, 'Indeed, those who have believed and emigrated and fought with their wealth and lives in the cause of Allah and those who gave shelter and aided - they are allies of one another. But those who believed and did not emigrate - for you there is no guardianship of them until they emigrate. And if they seek help of you for the religion, then you must help, except against a people between yourselves and whom is a treaty. And Allah is Seeing of what you do.'),
  ('en.sahih', 8, 73, 'And those who disbelieved are allies of one another. If you do not do so, there will be fitnah on earth and great corruption.'),
  ('en.sahih', 8, 74, 'But those who have believed and emigrated and fought in the cause of Allah and those who gave shelter and aided - it is they who are the believers, truly. For them is forgiveness and noble provision.'),
  ('en.sahih', 8, 75, 'And those who believed after [the initial emigration] and emigrated and fought with you - they are of you. But those of [blood] relationship are more entitled [to inheritance] in the decree of Allah. Indeed, Allah is Knowing of all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 8, 1, 'আপনার কাছে জিজ্ঞেস করে, গনীমতের হুকুম। বলে দিন, গণীমতের মাল হল আল্লাহর এবং রসূলের। অতএব, তোমরা আল্লাহকে ভয় কর এবং নিজেদের অবস্থা সংশোধন করে নাও। আর আল্লাহ এবং তাঁর রসূলের হুকুম মান্য কর, যদি ঈমানদার হয়ে থাক।'),
  ('bn.bengali', 8, 2, 'যারা ঈমানদার, তারা এমন যে, যখন আল্লাহর নাম নেয়া হয় তখন ভীত হয়ে পড়ে তাদের অন্তর। আর যখন তাদের সামনে পাঠ করা হয় কালাম, তখন তাদের ঈমান বেড়ে যায় এবং তারা স্বীয় পরওয়ার দেগারের প্রতি ভরসা পোষণ করে।'),
  ('bn.bengali', 8, 3, 'সে সমস্ত লোক যারা নামায প্রতিষ্ঠা করে এবং আমি তাদেরকে যে রুযী দিয়েছি তা থেকে ব্যয় করে।'),
  ('bn.bengali', 8, 4, 'তারাই হল সত্যিকার ঈমানদার! তাদের জন্য রয়েছে স্বীয় পরওয়ারদেগারের নিকট মর্যাদা, ক্ষমা এবং সম্মানজনক রুযী।'),
  ('bn.bengali', 8, 5, 'যেমন করে তোমাকে তোমার পরওয়ারদেগার ঘর থেকে বের করেছেন ন্যায় ও সৎকাজের জন্য, অথচ ঈমানদারদের একটি দল (তাতে) সম্মত ছিল না।'),
  ('bn.bengali', 8, 6, 'তারা তোমার সাথে বিবাদ করছিল সত্য ও ন্যায় বিষয়ে, তা প্রকাশিত হবার পর; তারা যেন মৃত্যুর দিকে ধাবিত হচ্ছে দেখতে দেখতে।'),
  ('bn.bengali', 8, 7, 'আর যখন আল্লাহ দু’টি দলের একটির ব্যাপারে তোমাদের সাথে ওয়াদা করেছিলেন যে, সেটি তোমাদের হস্তগত হবে, আর তোমরা কামনা করছিলে যাতে কোন রকম কন্টক নেই, তাই তোমাদের ভাগে আসুক; অথচ আল্লাহ চাইতেন সত্যকে স্বীয় কালামের মাধ্যমে সত্যে পরিণত করতে এবং কাফেরদের মূল কর্তন করে দিতে,'),
  ('bn.bengali', 8, 8, 'যাতে করে সত্যকে সত্য এবং মিথ্যাকে মিথ্যা প্রতিপন্ন করে দেন, যদিও পাপীরা অসন্তুষ্ট হয়।'),
  ('bn.bengali', 8, 9, 'তোমরা যখন ফরিয়াদ করতে আরম্ভ করেছিলে স্বীয় পরওয়ারদেগারের নিকট, তখন তিনি তোমাদের ফরিয়াদের মঞ্জুরী দান করলেন যে, আমি তোমাদিগকে সাহায্য করব ধারাবহিকভাবে আগত হাজার ফেরেশতার মাধ্যমে।'),
  ('bn.bengali', 8, 10, 'আর আল্লাহ তো শুধু সুসংবাদ দান করলেন যাতে তোমাদের মন আশ্বস্ত হতে পারে। আর সাহায্য আল্লাহর পক্ষ থেকে ছাড়া অন্য কারো পক্ষ থেকে হতে পারে না। নিঃসন্দেহে আল্লাহ মহাশক্তির অধিকারী হেকমত ওয়ালা।'),
  ('bn.bengali', 8, 11, 'যখন তিনি আরোপ করেন তোমাদের উপর তন্দ্রাচ্ছন্ন তা নিজের পক্ষ থেকে তোমাদের প্রশান্তির জন্য এবং তোমাদের উপর আকাশ থেকে পানি অবতরণ করেন, যাতে তোমাদিগকে পবিত্র করে দেন এবং যাতে তোমাদের থেকে অপসারিত করে দেন শয়তানের অপবিত্রতা। আর যাতে করে সুরক্ষিত করে দিতে পারেন তোমাদের অন্তরসমূহকে এবং তাতে যেন সুদৃঢ় করে দিতে পারেন তোমাদের পা গুলো।'),
  ('bn.bengali', 8, 12, 'যখন নির্দেশ দান করেন ফেরেশতাদিগকে তোমাদের পরওয়ারদেগার যে, আমি সাথে রয়েছি তোমাদের, সুতরাং তোমরা মুসলমানদের চিত্তসমূহকে ধীরস্থির করে রাখ। আমি কাফেরদের মনে ভীতির সঞ্চার করে দেব। কাজেই গর্দানের উপর আঘাত হান এবং তাদেরকে কাট জোড়ায় জোড়ায়।'),
  ('bn.bengali', 8, 13, 'যেহেতু তারা অবাধ্য হয়েছে আল্লাহ এবং তাঁর রসূলের, সেজন্য এই নির্দেশ। বস্তুতঃ যে লোক আল্লাহ ও রসূলের অবাধ্য হয়, নিঃসন্দেহে আল্লাহর শাস্তি অত্যন্ত কঠোর।'),
  ('bn.bengali', 8, 14, 'আপাততঃ বর্তমান এ শাস্তি তোমরা আস্বাদন করে নাও এবং জেনে রাখ যে, কাফেরদের জন্য রয়েছে দোযখের আযাব।'),
  ('bn.bengali', 8, 15, 'হে ঈমানদারগণ, তোমরা যখন কাফেরদের সাথে মুখোমুখী হবে, তখন পশ্চাদপসরণ করবে না।'),
  ('bn.bengali', 8, 16, 'আর যে লোক সেদিন তাদের থেকে পশ্চাদপসরণ করবে, অবশ্য যে লড়াইয়ের কৌশল পরিবর্তনকল্পে কিংবা যে নিজ সৈন্যদের নিকট আশ্রয় নিতে আসে সে ব্যতীত অন্যরা আল্লাহর গযব সাথে নিয়ে প্রত্যাবর্তন করবে। আর তার ঠিকানা হল জাহান্নাম। বস্তুতঃ সেটা হল নিকৃষ্ট অবস্থান।'),
  ('bn.bengali', 8, 17, 'সুতরাং তোমরা তাদেরকে হত্যা করনি, বরং আল্লাহই তাদেরকে হত্যা করেছেন। আর তুমি মাটির মুষ্ঠি নিক্ষেপ করনি, যখন তা নিক্ষেপ করেছিলে, বরং তা নিক্ষেপ করেছিলেন আল্লাহ স্বয়ং যেন ঈমানদারদের প্রতি এহসান করতে পারেন যথার্থভাবে। নিঃসন্দেহে আল্লাহ শ্রবণকারী; পরিজ্ঞাত।'),
  ('bn.bengali', 8, 18, 'এটাতো গেল, আর জেনে রেখো, আল্লাহ নস্যাৎ করে দেবেন কাফেরদের সমস্ত কলা-কৌশল।'),
  ('bn.bengali', 8, 19, 'তোমরা যদি মীমাংসা কামনা কর, তাহলে তোমাদের নিকট মীমাংসা পৌছে গেছে। আর যদি তোমরা প্রত্যাবর্তন কর, তবে তা তোমাদের জন্য উত্তম এবং তোমরা যদি তাই কর, তবে আমি ও তেমনি করব। বস্তুতঃ তোমাদের কোনই কাজে আসবে না তোমাদের দল-বল, তা যত বেশীই হোক। জেনে রেখ আল্লাহ রয়েছেন ঈমানদারদের সাথে।'),
  ('bn.bengali', 8, 20, 'হে ঈমানদারগণ, আল্লাহ ও তাঁর রসূলের নির্দেশ মান্য কর এবং শোনার পর তা থেকে বিমুখ হয়ো না।'),
  ('bn.bengali', 8, 21, 'আর তাদের অন্তর্ভুক্ত হয়ো না, যারা বলে যে, আমরা শুনেছি, অথচ তারা শোনেনা।'),
  ('bn.bengali', 8, 22, 'নিঃসন্দেহে আল্লাহ তা’আলার নিকট সমস্ত প্রাণীর তুলনায় তারাই মূক ও বধির, যারা উপলদ্ধি করে না।'),
  ('bn.bengali', 8, 23, 'বস্তুতঃ আল্লাহ যদি তাদের মধ্যে কিছুমাত্র শুভ চিন্তা জানতেন, তবে তাদেরকে শুনিয়ে দিতেন। আর এখনই যদি তাদের শুনিয়ে দেন, তবে তারা মুখ ঘুরিয়ে পালিয়ে যাবে।'),
  ('bn.bengali', 8, 24, 'হে ঈমানদারগণ, আল্লাহ ও তাঁর রসূলের নির্দেশ মান্য কর, যখন তোমাদের সে কাজের প্রতি আহবান করা হয়, যাতে রয়েছে তোমাদের জীবন। জেনে রেখো, আল্লাহ মানুষের এবং তার অন্তরের মাঝে অন্তরায় হয়ে যান। বস্তুতঃ তোমরা সবাই তাঁরই নিকট সমবেত হবে।'),
  ('bn.bengali', 8, 25, 'আর তোমরা এমন ফাসাদ থেকে বেঁচে থাক যা বিশেষতঃ শুধু তাদের উপর পতিত হবে না যারা তোমাদের মধ্যে জালেম এবং জেনে রেখ যে, আল্লাহর আযাব অত্যন্ত কঠোর।'),
  ('bn.bengali', 8, 26, 'আর স্মরণ কর, যখন তোমরা ছিলে অল্প, পরাজিত অবস্থায় পড়েছিলে দেশে; ভীত-সস্ত্রস্ত্র ছিলে যে, তোমাদের না অন্যেরা ছোঁ মেরে নিয়ে যায়। অতঃপর তিনি তোমাদিগকে আশ্রয়ের ঠিকানা দিয়েছেন, স্বীয় সাহায্যের দ্বারা তোমাদিগকে শক্তি দান করেছেন এবং পরিচ্ছন্ন জীবিকা দিয়েছেন যাতে তোমরা শুকরিয়া আদায় কর।'),
  ('bn.bengali', 8, 27, 'হে ঈমানদারগণ, খেয়ানত করোনা আল্লাহর সাথে ও রসূলের সাথে এবং খেয়ানত করো না নিজেদের পারস্পরিক আমানতে জেনে-শুনে।'),
  ('bn.bengali', 8, 28, 'আর জেনে রাখ, তোমাদের ধন-সম্পদ ও সন্তান-সন্ততি অকল্যাণের সম্মুখীনকারী। বস্তুতঃ আল্লাহর নিকট রয়েছে মহা সওয়াব।'),
  ('bn.bengali', 8, 29, 'হে ঈমানদারগণ তোমরা যদি আল্লাহকে ভয় করতে থাক, তবে তোমাদের মধ্যে ফয়সালা করে দেবেন এবং তোমাদের থেকে তোমাদের পাপকে সরিয়ে দেবেন এবং তোমাদের ক্ষমা করবেন। বস্তুতঃ আল্লাহর অনুগ্রহ অত্যন্ত মহান।'),
  ('bn.bengali', 8, 30, 'আর কাফেরেরা যখন প্রতারণা করত আপনাকে বন্দী অথবা হত্যা করার উদ্দেশ্যে কিংবা আপনাকে বের করে দেয়ার জন্য তখন তারা যেমন ছলনা করত তেমনি, আল্লাহও ছলনা করতেন। বস্তুতঃ আল্লাহর ছলনা সবচেয়ে উত্তম।'),
  ('bn.bengali', 8, 31, 'আর কেউ যখন তাদের নিকট আমার আয়াতসমূহ পাঠ করে তবে বলে, আমরা শুনেছি, ইচ্ছা করলে আমরাও এমন বলতে পারি; এ তো পূর্ববর্তী ইতিকথা ছাড়া আর কিছুই নয়।'),
  ('bn.bengali', 8, 32, 'তাছাড়া তারা যখন বলতে আরম্ভ করে যে, ইয়া আল্লাহ, এই যদি তোমার পক্ষ থেকে (আগত) সত্য দ্বীন হয়ে থাকে, তবে আমাদের উপর আকাশ থেকে প্রস্তর বর্ষণ কর কিংবা আমাদের উপর বেদনাদায়ক আযাব নাযিল কর।'),
  ('bn.bengali', 8, 33, 'অথচ আল্লাহ কখনই তাদের উপর আযাব নাযিল করবেন না যতক্ষণ আপনি তাদের মাঝে অবস্থান করবেন। তাছাড়া তারা যতক্ষণ ক্ষমা প্রার্থনা করতে থাকবে আল্লাহ কখনও তাদের উপর আযাব দেবেন না।'),
  ('bn.bengali', 8, 34, 'আর তাদের মধ্যে এমন কি বিষয় রয়েছে, যার ফলে আল্লাহ তাদের উপর আযাব দান করবেন না। অথচ তারা মসজিদে-হারামে যেতে বাধাদান করে, অথচ তাদের সে অধিকার নেই। এর অধিকার তো তাদেরই রয়েছে যারা পরহেযগার। কিন্তু তাদের অধিকাংশই সে বিষয়ে অবহিত নয়।'),
  ('bn.bengali', 8, 35, 'আর কা’বার নিকট তাদের নামায বলতে শিস দেয়া আর তালি বাজানো ছাড়া অন্য কোন কিছুই ছিল না। অতএব, এবার নিজেদের কৃত কুফরীর আযাবের স্বাদ গ্রহণ কর।'),
  ('bn.bengali', 8, 36, 'নিঃসন্দেহে যেসব লোক কাফের, তারা ব্যয় করে নিজেদের ধন-সম্পদ, যাতে করে বাধাদান করতে পারে আল্লাহর পথে। বস্তুতঃ এখন তারা আরো ব্যয় করবে। তারপর তাই তাদের জন্য আক্ষেপের কারণ হয়ে এবং শেষ পর্যন্ত তারা হেরে যাবে। আর যারা কাফের তাদেরকে দোযখের দিকে তাড়িয়ে নিয়ে যাওয়া হবে।'),
  ('bn.bengali', 8, 37, 'যাতে পৃথক করে দেন আল্লাহ অপবিত্র ও না-পাককে পবিত্র ও পাক থেকে। আর যাতে একটির পর একটিকে স্থাপন করে সমবেত স্তুপে পরিণত করেন এবং পরে দোযখে নিক্ষেপ করেন। এরাই হল ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 8, 38, 'তুমি বলে দাও, কাফেরদেরকে যে, তারা যদি বিরত হয়ে যায়, তবে যা কিছু ঘটে গেছে ক্ষমা হবে যাবে। পক্ষান্তরে আবারও যদি তাই করে, তবে পুর্ববর্তীদের পথ নির্ধারিত হয়ে গেছে।'),
  ('bn.bengali', 8, 39, 'আর তাদের সাথে যুদ্ধ করতে থাক যতক্ষণ না ভ্রান্তি শেষ হয়ে যায়; এবং আল্লাহর সমস্ত হুকুম প্রতিষ্ঠিত হয়ে যায়। তারপর যদি তারা বিরত হয়ে যায়, তবে আল্লাহ তাদের কার্যকলাপ লক্ষ্য করেন।'),
  ('bn.bengali', 8, 40, 'আর তারা যদি না মানে, তবে জেনে রাখ, আল্লাহ তোমাদের সমর্থক; এবং কতই না চমৎকার সাহায্যকারী।'),
  ('bn.bengali', 8, 41, 'আর এ কথাও জেনে রাখ যে, কোন বস্তু-সামগ্রীর মধ্য থেকে যা কিছু তোমরা গনীমত হিসাবে পাবে, তার এক পঞ্চমাংশ হল আল্লাহর জন্য, রসূলের জন্য, তাঁর নিকটাত্নীয়-স্বজনের জন্য এবং এতীম-অসহায় ও মুসাফিরদের জন্য; যদি তোমাদের বিশ্বাস থাকে আল্লাহর উপর এবং সে বিষয়ের উপর যা আমি আমার বান্দার প্রতি অবতীর্ণ করেছি ফয়সালার দিনে, যেদিন সম্মুখীন হয়ে যায় উভয় সেনাদল। আর আল্লাহ সব কিছুর উপরই ক্ষমতাশীল।'),
  ('bn.bengali', 8, 42, 'আর যখন তোমরা ছিলে সমরাঙ্গনের এ প্রান্তে আর তারা ছিল সে প্রান্তে অথচ কাফেলা তোমাদের থেকে নীচে নেমে গিয়েছিল। এমতাবস্থায় যদি তোমরা পারস্পরিক অঙ্গীকারাবদ্ধ হতে, তবে তোমরা এক সঙ্গে সে ওয়াদা পালন করতে পারতে না। কিন্তু আল্লাহ তা’আলা এমন এক কাজ করতে চেয়েছিলেন, যা নির্ধারিত হয়ে গিয়েছিল যাতে সে সব লোক নিহত হওয়ার ছিল, প্রমাণ প্রতিষ্ঠার পর এবং যাদের বাঁচার ছিল, তারা বেঁচে থাকে প্রমাণ প্রতিষ্ঠার পর। আর নিশ্চিতই আল্লাহ শ্রবণকারী, বিজ্ঞ।'),
  ('bn.bengali', 8, 43, 'আল্লাহ যখন তোমাকে স্বপ্নে সেসব কাফেরের পরিমাণ অল্প করে দেখালেন; বেশী করে দেখালে তোমরা কাপুরুষতা অবলম্বন করতে এবং কাজের বেলায় বিপদ সৃষ্টি করতে। কিন্তু আল্লাহ বাঁচিয়ে দিয়েছেন। তিনি অতি উত্তমভাবেই জানেন; যা কিছু অন্তরে রয়েছে।'),
  ('bn.bengali', 8, 44, 'আর যখন তোমাদেরকে দেখালেন সে সৈন্যদল মোকাবেলার সময় তোমাদের চোখে অল্প এবং তোমাদেরকে দেখালেন তাদের চোখে বেশী, যাতে আল্লাহ সে কাজ করে নিতে পারেন যা ছিল নির্ধারিত। আর সব কাজই আল্লাহর নিকট গিয়ে পৌছায়।'),
  ('bn.bengali', 8, 45, 'হে ঈমানদারগণ, তোমরা যখন কোন বাহিনীর সাথে সংঘাতে লিপ্ত হও, তখন সুদৃঢ় থাক এবং আল্লাহকে অধিক পরিমাণে স্মরণ কর যাতে তোমরা উদ্দেশ্যে কৃতকার্য হতে পার।'),
  ('bn.bengali', 8, 46, 'আর আল্লাহ তা’আলার নির্দেশ মান্য কর এবং তাঁর রসূলের। তাছাড়া তোমরা পরস্পরে বিবাদে লিপ্ত হইও না। যদি তা কর, তবে তোমরা কাপুরুষ হয়ে পড়বে এবং তোমাদের প্রভাব চলে যাবে। আর তোমরা ধৈর্য্যধারণ কর। নিশ্চয়ই আল্লাহ তা\'আলা রয়েছেন ধৈর্য্যশীলদের সাথে।'),
  ('bn.bengali', 8, 47, 'আর তাদের মত হয়ে যেয়ো না, যারা বেরিয়েছে নিজেদের অবস্থান থেকে গর্বিতভাবে এবং লোকদেরকে দেখাবার উদ্দেশে। আর আল্লাহর পথে তারা বাধা দান করত। বস্তুতঃ আল্লাহর আয়ত্বে রয়েছে সে সমস্ত বিষয় যা তারা করে।'),
  ('bn.bengali', 8, 48, 'আর যখন সুদৃশ্য করে দিল শয়তান তাদের দৃষ্টিতে তাদের কার্যকলাপকে এবং বলল যে, আজকের দিনে কোন মানুষই তোমাদের উপর বিজয়ী হতে পারবে না আর আমি হলাম তোমাদের সমর্থক, অতঃপর যখন সামনাসামনী হল উভয় বাহিনী তখন সে অতি দ্রুত পায়ে পেছনে দিকে পালিয়ে গেল এবং বলল, আমি তোমাদের সাথে না-আমি দেখছি, যা তোমরা দেখছ না; আমি ভয় করি আল্লাহকে। আর আল্লাহর আযাব অত্যন্ত কঠিন।'),
  ('bn.bengali', 8, 49, 'যখন মোনাফেকরা বলতে লাগল এবং যাদের অন্তর ব্যাধিগ্রস্ত, এরা নিজেদের ধর্মের উপর গর্বিত। বস্তুতঃ যারা ভরসা করে আল্লাহর উপর, সে নিশ্চিন্ত, কেননা আল্লাহ অতি পরাক্রমশীল, সুবিজ্ঞ।'),
  ('bn.bengali', 8, 50, 'আর যদি তুমি দেখ, যখন ফেরেশতারা কাফেরদের জান কবজ করে; প্রহার করে, তাদের মুখে এবং তাদের পশ্চাদদেশে আর বলে, জ্বলন্ত আযাবের স্বাদ গ্রহণ কর।'),
  ('bn.bengali', 8, 51, 'এই হলো সে সবের বিনিময় যা তোমরা তোমাদের পূর্বে পাঠিয়েছ নিজের হাতে। বস্তুতঃ এটি এ জন্য যে, আল্লাহ বান্দার উপর যুলুম করেন না।'),
  ('bn.bengali', 8, 52, 'যেমন, রীতি রয়েছে ফেরাউনের অনুসারীদের এবং তাদের পূর্বে যারা ছিল তাদের ব্যাপারে যে, এরা আল্লাহর নির্দেশের প্রতি অস্বীকৃতি জ্ঞাপন করেছে এবং সেজন্য আল্লাহ তা’আলা তাদের পাকড়াও করেছেন তাদেরই পাপের দরুন। নিঃসন্দেহে আল্লাহ মহাশক্তিশালী, কঠিন শাস্তিদাতা।'),
  ('bn.bengali', 8, 53, 'তার কারণ এই যে, আল্লাহ কখনও পরিবর্তন করেন না, সে সব নেয়ামত, যা তিনি কোন জাতিকে দান করেছিলেন, যতক্ষণ না সে জাতি নিজেই পরিবর্তিত করে দেয় নিজের জন্য নির্ধারিত বিষয়। বস্তুতঃ আল্লাহ শ্রবণকারী, মহাজ্ঞানী।'),
  ('bn.bengali', 8, 54, 'যেমন ছিল রীতি ফেরাউনের বংশধর এবং যারা তাদের পূর্বে ছিল, তারা মিথ্যা প্রতিপন্ন করেছিল স্বীয় পালনকর্তার নিদর্শনসমূহকে। অতঃপর আমি তাদেরকে ধ্বংস করে দিয়েছি তাদের পাপের দরুন এবং ডুবিয়ে মেরেছি ফেরাউনের বংশধরদেরকে। বস্তুতঃ এরা সবাই ছিল যালেম।'),
  ('bn.bengali', 8, 55, 'সমস্ত জীবের মাঝে আল্লাহর নিকট তারাই সবচেয়ে নিকৃষ্ট, যারা অস্বীকারকারী হয়েছে অতঃপর আর ঈমান আনেনি।'),
  ('bn.bengali', 8, 56, 'যাদের সাথে তুমি চুক্তি করেছ তাদের মধ্য থেকে অতঃপর প্রতিবার তারা নিজেদের কৃতচুক্তি লংঘন করে এবং ভয় করে না।'),
  ('bn.bengali', 8, 57, 'সুতরাং যদি কখনো তুমি তাদেরকে যুদ্ধে পেয়ে যাও, তবে তাদের এমন শাস্তি দাও, যেন তাদের উত্তরসূরিরা তাই দেখে পালিয়ে যায়; তাদেরও যেন শিক্ষা হয়।'),
  ('bn.bengali', 8, 58, 'তবে কোন সম্প্রদায়ের ধোঁকা দেয়ার ব্যাপারে যদি তোমাদের ভয় থাকে, তবে তাদের চুক্তি তাদের দিকেই ছুঁড়ে ফেলে দাও এমনভাবে যেন হয়ে যাও তোমরাও তারা সমান। নিশ্চয়ই আল্লাহ ধোকাবাজ, প্রতারককে পছন্দ করেন না।'),
  ('bn.bengali', 8, 59, 'আর কাফেররা যেন একা যা মনে না করে যে, তারা বেঁচে গেছে; কখনও এরা আমাকে পরিশ্রান্ত করতে পারবে না।'),
  ('bn.bengali', 8, 60, 'আর প্রস্তুত কর তাদের সাথে যুদ্ধের জন্য যাই কিছু সংগ্রহ করতে পার নিজের শক্তি সামর্থ্যের মধ্যে থেকে এবং পালিত ঘোড়া থেকে, যেন প্রভাব পড়ে আল্লাহর শুত্রুদের উপর এবং তোমাদের শত্রুদের উপর আর তাদেরকে ছাড়া অন্যান্যদের উপর ও যাদেরকে তোমরা জান না; আল্লাহ তাদেরকে চেনেন। বস্তুতঃ যা কিছু তোমরা ব্যয় করবে আল্লাহর রাহে, তা তোমরা পরিপূর্ণভাবে ফিরে পাবে এবং তোমাদের কোন হক অপূর্ণ থাকবে না।'),
  ('bn.bengali', 8, 61, 'আর যদি তারা সন্ধি করতে আগ্রহ প্রকাশ করে, তাহলে তুমিও সে দিকেই আগ্রহী হও এবং আল্লাহর উপর ভরসা কর। নিঃসন্দেহে তিনি শ্রবণকারী; পরিজ্ঞাত।'),
  ('bn.bengali', 8, 62, 'পক্ষান্তরে তারা যদি তোমাকে প্রতারণা করতে চায়, তবে তোমার জন্য আল্লাহই যথেষ্ট, তিনিই তোমাকে শক্তি যুগিয়েছেন স্বীয় সাহায্যে ও মুসলমানদের মাধ্যমে।'),
  ('bn.bengali', 8, 63, 'আর প্রীতি সঞ্চার করেছেন তাদের অন্তরে। যদি তুমি সেসব কিছু ব্যয় করে ফেলতে, যা কিছু যমীনের বুকে রয়েছে, তাদের মনে প্রীতি সঞ্চার করতে পারতে না। কিন্তু আল্লাহ তাদের মনে প্রীতি সঞ্চার করেছেন। নিঃসন্দেহে তিনি পরাক্রমশালী, সুকৌশলী।'),
  ('bn.bengali', 8, 64, 'হে নবী, আপনার জন্য এবং যেসব মুসলমান আপনার সাথে রয়েছে তাদের সবার জন্য আল্লাহ যথেষ্ট।'),
  ('bn.bengali', 8, 65, 'হে নবী, আপনি মুসলমানগণকে উৎসাহিত করুন জেহাদের জন্য। তোমাদের মধ্যে যদি বিশ জন দৃঢ়পদ ব্যক্তি থাকে, তবে জয়ী হবে দু’শর মোকাবেলায়। আর যদি তোমাদের মধ্যে থাকে একশ লোক, তবে জয়ী হবে হাজার কাফেরের উপর থেকে তার কারণ ওরা জ্ঞানহীন।'),
  ('bn.bengali', 8, 66, 'এখন বোঝা হালকা করে দিয়েছেন আল্লাহ তা’আলা তোমাদের উপর এবং তিনি জেনে নিয়েছেন যে, তোমাদের মধ্য দূর্বলতা রয়েছে। কাজেই তোমাদের মধ্যে যদি দৃঢ়চিত্ত একশ লোক বিদ্যমান থাকে, তবে জয়ী হবে দু’শর উপর। আর যদি তোমরা এক হাজার হও তবে আল্লাহর হুকুম অনুযায়ী জয়ী হবে দু’হাজারের উপর আর আল্লাহ রয়েছেন দৃঢ়চিত্ত লোকদের সাথে।'),
  ('bn.bengali', 8, 67, 'নবীর পক্ষে উচিত নয় বন্দীদিগকে নিজের কাছে রাখা, যতক্ষণ না দেশময় প্রচুর রক্তপাত ঘটাবে। তোমরা পার্থিব সম্পদ কামনা কর, অথচ আল্লাহ চান আখেরাত। আর আল্লাহ হচ্ছেন পরাক্রমশালী হেকমতওয়ালা।'),
  ('bn.bengali', 8, 68, 'যদি একটি বিষয় না হত যা পূর্ব থেকেই আল্লাহ লিখে রেখেছেন, তাহলে তোমরা যা গ্রহণ করছ সেজন্য বিরাট আযাব এসে পৌছাত।'),
  ('bn.bengali', 8, 69, 'সুতরাং তোমরা খাও গনীমত হিসাবে তোমরা যে পরিচ্ছন্ন ও হালাল বস্তু অর্জন করেছ তা থেকে। আর আল্লাহকে ভয় করতে থাক। নিশ্চয়ই আল্লাহ ক্ষমাশীল, মেহেরবান।'),
  ('bn.bengali', 8, 70, 'হে নবী, তাদেরকে বলে দাও, যারা তোমার হাতে বন্দী হয়ে আছে যে, আল্লাহ যদি তোমাদের অন্তরে কোন রকম মঙ্গলচিন্তা রয়েছে বলে জানেন, তবে তোমাদেরকে তার চেয়ে বহুগুণ বেশী দান করবেন যা তোমাদের কাছ থেকে বিনিময়ে নেয়া হয়েছে। তাছাড়া তোমাদেরকে তিনি ক্ষমা করে দিবেন। বস্তুতঃ আল্লাহ ক্ষমাশীল, করুণাময়।'),
  ('bn.bengali', 8, 71, 'আর যদি তারা তোমার সাথে প্রতারণা করতে চায়-বস্তুতঃ তারা আল্লাহর সাথেও ইতিপূর্বে প্রতারণা করেছে, অতঃপর তিনি তাদেরকে ধরিয়ে দিয়েছেন। আর আল্লাহ সর্ববিষয়ে পরিজ্ঞাত, সুকৌশলী।'),
  ('bn.bengali', 8, 72, 'এতে কোন সন্দেহ নেই যে, যারা ঈমান এনেছে, দেশ ত্যাগ করেছে, স্বীয় জান ও মাল দ্বারা আল্লাহর রাহে জেহাদ করেছে এবং যারা তাদেরকে আশ্রয় ও সাহায্য সহায়তা দিয়েছে, তারা একে অপরের সহায়ক। আর যারা ঈমান এনেছে কিন্তু দেশ ত্যাগ করেনি তাদের বন্ধুত্বে তোমাদের প্রয়োজন নেই যতক্ষণ না তারা দেশত্যাগ করে। অবশ্য যদি তারা ধর্মীয় ব্যাপারে তোমাদের সহায়তা কামনা করে, তবে তাদের সাহায্য করা তোমাদের কর্তব্য। কিন্তু তোমাদের সাথে যাদের সহযোগী চুক্তি বিদ্যমান রয়েছে, তাদের মোকাবেলায় নয়। বস্তুতঃ তোমরা যা কিছু কর, আল্লাহ সেসবই দেখেন।'),
  ('bn.bengali', 8, 73, 'আর যারা কাফের তারা পারস্পরিক সহযোগী, বন্ধু। তোমরা যদি এমন ব্যবস্থা না কর, তবে দাঙ্গা-হাঙ্গামা বিস্তার লাভ করবে এবং দেশময় বড়ই অকল্যাণ হবে।'),
  ('bn.bengali', 8, 74, 'আর যারা ঈমান এনেছে, নিজেদের ঘর-বাড়ী ছেড়েছে এবং আল্লাহর রাহে জেহাদ করেছে এবং যারা তাদেরকে আশ্রয় দিয়েছে, সাহায্য-সহায়তা করেছে, তাঁরা হলো সত্যিকার মুসলমান। তাঁদের জন্যে রয়েছে, ক্ষমা ও সম্মানজনক রুযী।'),
  ('bn.bengali', 8, 75, 'আর যারা ঈমান এনেছে পরবর্তী পর্যায়ে এবং ঘর-বাড়ী ছেড়েছে এবং তোমাদের সাথে সম্মিলিত হয়ে জেহাদ করেছে, তারাও তোমাদেরই অন্তর্ভুক্ত। বস্তুতঃ যারা আত্নীয়, আল্লাহর বিধান মতে তারা পরস্পর বেশী হকদার। নিশ্চয়ই আল্লাহ যাবতীয় বিষয়ে সক্ষম ও অবগত।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 8, 1, 'They ask thee (O Muhammad) of the spoils of war. Say: The spoils of war belong to Allah and the messenger, so keep your duty to Allah, and adjust the matter of your difference, and obey Allah and His messenger, if ye are (true) believers.'),
  ('en.pickthall', 8, 2, 'They only are the (true) believers whose hearts feel fear when Allah is mentioned, and when His revelations are recited unto them they increase their faith, and who trust in their Lord;'),
  ('en.pickthall', 8, 3, 'Who establish worship and spend of that We have bestowed on them.'),
  ('en.pickthall', 8, 4, 'Those are they who are in truth believers. For them are grades (of honour) with their Lord, and pardon, and a bountiful provision.'),
  ('en.pickthall', 8, 5, 'Even as thy Lord caused thee (Muhammad) to go forth from thy home with the Truth, and lo! a party of the believers were averse (to it).'),
  ('en.pickthall', 8, 6, 'Disputing with thee of the Truth after it had been made manifest, as if they were being driven to death visible.'),
  ('en.pickthall', 8, 7, 'And when Allah promised you one of the two bands (of the enemy) that it should be yours, and ye longed that other than the armed one might be yours. And Allah willed that He should cause the Truth to triumph by His words, and cut the root of the disbelievers;'),
  ('en.pickthall', 8, 8, 'That He might cause the Truth to triumph and bring vanity to naught, however much the guilty might oppose;'),
  ('en.pickthall', 8, 9, 'When ye sought help of your Lord and He answered you (saying): I will help you with a thousand of the angels, rank on rank.'),
  ('en.pickthall', 8, 10, 'Allah appointed it only as good tidings, and that your hearts thereby might be at rest. Victory cometh only by the help of Allah. Lo! Allah is Mighty, Wise.'),
  ('en.pickthall', 8, 11, 'When He made the slumber fall upon you as a reassurance from him and sent down water from the sky upon you, that thereby He might purify you, and remove from you the fear of Satan, and make strong your hearts and firm (your) feet thereby.'),
  ('en.pickthall', 8, 12, 'When thy Lord inspired the angels, (saying): I am with you. So make those who believe stand firm. I will throw fear into the hearts of those who disbelieve. Then smite the necks and smite of them each finger.'),
  ('en.pickthall', 8, 13, 'That is because they opposed Allah and His messenger. Whoso opposeth Allah and His messenger, (for him) lo! Allah is severe in punishment.'),
  ('en.pickthall', 8, 14, 'That (is the award), so taste it, and (know) that for disbelievers is the torment of the Fire.'),
  ('en.pickthall', 8, 15, 'O ye who believe! When ye meet those who disbelieve in battle, turn not your backs to them.'),
  ('en.pickthall', 8, 16, 'Whoso on that day turneth his back to them, unless manoeuvring for battle or intent to join a company, he truly hath incurred wrath from Allah, and his habitation will be hell, a hapless journey\'s end.'),
  ('en.pickthall', 8, 17, 'Ye (Muslims) slew them not, but Allah slew them. And thou (Muhammad) threwest not when thou didst throw, but Allah threw, that He might test the believers by a fair test from Him. Lo! Allah is Hearer, Knower.'),
  ('en.pickthall', 8, 18, 'That (is the case); and (know) that Allah (it is) Who maketh weak the plan of disbelievers.'),
  ('en.pickthall', 8, 19, '(O Qureysh!) If ye sought a judgment, now hath the judgment come unto you. And if ye cease (from persecuting the believers) it will be better for you, but if ye return (to the attack) We also shall return. And your host will avail you naught, however numerous it be, and (know) that Allah is with the believers (in His Guidance).'),
  ('en.pickthall', 8, 20, 'O ye who believe! Obey Allah and His messenger, and turn not away from him when ye hear (him speak).'),
  ('en.pickthall', 8, 21, 'Be not as those who say, we hear, and they hear not.'),
  ('en.pickthall', 8, 22, 'Lo! the worst of beasts in Allah\'s sight are the deaf, the dumb, who have no sense.'),
  ('en.pickthall', 8, 23, 'Had Allah known of any good in them He would have made them hear, but had He made them hear they would have turned away, averse.'),
  ('en.pickthall', 8, 24, 'O ye who believe! Obey Allah, and the messenger when He calleth you to that which quickeneth you, and know that Allah cometh in between the man and his own heart, and that He it is unto Whom ye will be gathered.'),
  ('en.pickthall', 8, 25, 'And guard yourselves against a chastisement which cannot fall exclusively on those of you who are wrong-doers, and know that Allah is severe in punishment.'),
  ('en.pickthall', 8, 26, 'And remember, when ye were few and reckoned feeble in the land, and were in fear lest men should extirpate you, how He gave you refuge, and strengthened you with His help, and made provision of good things for you, that haply ye might be thankful.'),
  ('en.pickthall', 8, 27, 'O ye who believe! Betray not Allah and His messenger, nor knowingly betray your trusts.'),
  ('en.pickthall', 8, 28, 'And know that your possessions and your children are a test, and that with Allah is immense reward.'),
  ('en.pickthall', 8, 29, 'O ye who believe! If ye keep your duty to Allah, He will give you discrimination (between right and wrong) and will rid you of your evil thoughts and deeds, and will forgive you. Allah is of Infinite Bounty.'),
  ('en.pickthall', 8, 30, 'And when those who disbelieve plot against thee (O Muhammad) to wound thee fatally, or to kill thee or to drive thee forth; they plot, but Allah (also) plotteth; and Allah is the best of plotters.'),
  ('en.pickthall', 8, 31, 'And when Our revelations are recited unto them they say: We have heard. If we wish we can speak the like of this. Lo! this is naught but fables of the men of old.'),
  ('en.pickthall', 8, 32, 'And when they said: O Allah! If this be indeed the truth from Thee, then rain down stones on us or bring on us some painful doom!'),
  ('en.pickthall', 8, 33, 'But Allah would not punish them while thou wast with them, nor will He punish them while they seek forgiveness.'),
  ('en.pickthall', 8, 34, 'What (plea) have they that Allah should not punish them, when they debar (His servants) from the Inviolable Place of Worship, though they are not its fitting guardians. Its fitting guardians are those only who keep their duty to Allah. But most of them know not.'),
  ('en.pickthall', 8, 35, 'And their worship at the (holy) House is naught but whistling and hand-clapping. Therefore (it is said unto them): Taste of the doom because ye disbelieve.'),
  ('en.pickthall', 8, 36, 'Lo! those who disbelieve spend their wealth in order that they may debar (men) from the way of Allah. They will spend it, then it will become an anguish for them, then they will be conquered. And those who disbelieve will be gathered unto hell,'),
  ('en.pickthall', 8, 37, 'That Allah may separate the wicked from the good, The wicked will He place piece upon piece, and heap them all together, and consign them unto hell. Such verily are the losers.'),
  ('en.pickthall', 8, 38, 'Tell those who disbelieve that if they cease (from persecution of believers) that which is past will be forgiven them; but if they return (thereto) then the example of the men of old hath already gone (before them, for a warning).'),
  ('en.pickthall', 8, 39, 'And fight them until persecution is no more, and religion is all for Allah. But if they cease, then lo! Allah is Seer of what they do.'),
  ('en.pickthall', 8, 40, 'And if they turn away, then know that Allah is your Befriender - a Transcendent Patron, a Transcendent Helper!'),
  ('en.pickthall', 8, 41, 'And know that whatever ye take as spoils of war, lo! a fifth thereof is for Allah, and for the messenger and for the kinsman (who hath need) and orphans and the needy and the wayfarer, if ye believe in Allah and that which We revealed unto Our slave on the Day of Discrimination, the day when the two armies met. And Allah is Able to do all things.'),
  ('en.pickthall', 8, 42, 'When ye were on the near bank (of the valley) and they were on the yonder bank, and the caravan was below you (on the coast plain). And had ye trysted to meet one another ye surely would have failed to keep the tryst, but (it happened, as it did, without the forethought of either of you) that Allah might conclude a thing that must be done; that he who perished (on that day) might perish by a clear proof (of His Sovereignty) and he who survived might survive by a clear proof (of His Sovereignty). Lo! Allah in truth is Hearer, Knower.'),
  ('en.pickthall', 8, 43, 'When Allah showed them unto thee (O Muhammad) in thy dream as few in number, and if He had shown them to thee as many, ye (Muslims) would have faltered and would have quarrelled over the affair. But Allah saved (you). Lo! He knoweth what is in the breasts (of men).'),
  ('en.pickthall', 8, 44, 'And when He made you (Muslims), when ye met (them), see them with your eyes as few, and lessened you in their eyes, (it was) that Allah might conclude a thing that must be done. Unto Allah all things are brought back.'),
  ('en.pickthall', 8, 45, 'O ye who believe! When ye meet an army, hold firm and think of Allah much, that ye may be successful.'),
  ('en.pickthall', 8, 46, 'And obey Allah and His messenger, and dispute not one with another lest ye falter and your strength depart from you; but be steadfast! Lo! Allah is with the steadfast.'),
  ('en.pickthall', 8, 47, 'Be not as those who came forth from their dwellings boastfully and to be seen of men, and debar (men) from the way of Allah, while Allah is surrounding all they do.'),
  ('en.pickthall', 8, 48, 'And when Satan made their deeds seem fair to them and said: No-one of mankind can conquer you this day, for I am your protector. But when the armies came in sight of one another, he took flight, saying: Lo! I am guiltless of you. Lo! I see that which ye see not. Lo! I fear Allah. And Allah is severe in punishment.'),
  ('en.pickthall', 8, 49, 'When the hypocrites and those in whose hearts is a disease said: Their religion hath deluded these. Whoso putteth his trust in Allah (will find that) lo! Allah is Mighty, Wise.'),
  ('en.pickthall', 8, 50, 'If thou couldst see how the angels receive those who disbelieve, smiting faces and their backs and (saying): Taste the punishment of burning!'),
  ('en.pickthall', 8, 51, 'This is for that which your own hands have sent before (to the Judgment), and (know) that Allah is not a tyrant to His slaves.'),
  ('en.pickthall', 8, 52, '(Their way is) as the way of Pharaoh\'s folk and those before them; they disbelieved the revelations of Allah, and Allah took them in their sins. Lo! Allah is Strong, severe in punishment.'),
  ('en.pickthall', 8, 53, 'That is because Allah never changeth the grace He hath bestowed on any people until they first change that which is in their hearts, and (that is) because Allah is Hearer, Knower.'),
  ('en.pickthall', 8, 54, '(Their way is) as the way of Pharaoh\'s folk and those before them; they denied the revelations of their Lord, so We destroyed them in their sins. And We drowned the folk of Pharaoh. All were evil-doers.'),
  ('en.pickthall', 8, 55, 'Lo! the worst of beasts in Allah\'s sight are the ungrateful who will not believe.'),
  ('en.pickthall', 8, 56, 'Those of them with whom thou madest a treaty, and then at every opportunity they break their treaty, and they keep not duty (to Allah).'),
  ('en.pickthall', 8, 57, 'If thou comest on them in the war, deal with them so as to strike fear in those who are behind them, that haply they may remember.'),
  ('en.pickthall', 8, 58, 'And if thou fearest treachery from any folk, then throw back to them (their treaty) fairly. Lo! Allah loveth not the treacherous.'),
  ('en.pickthall', 8, 59, 'And let not those who disbelieve suppose that they can outstrip (Allah\'s Purpose). Lo! they cannot escape.'),
  ('en.pickthall', 8, 60, 'Make ready for them all thou canst of (armed) force and of horses tethered, that thereby ye may dismay the enemy of Allah and your enemy, and others beside them whom ye know not. Allah knoweth them. Whatsoever ye spend in the way of Allah it will be repaid to you in full, and ye will not be wronged.'),
  ('en.pickthall', 8, 61, 'And if they incline to peace, incline thou also to it, and trust in Allah. Lo! He, even He, is the Hearer, the Knower.'),
  ('en.pickthall', 8, 62, 'And if they would deceive thee, then lo! Allah is Sufficient for thee. He it is Who supporteth thee with His help and with the believers,'),
  ('en.pickthall', 8, 63, 'And (as for the believers) hath attuned their hearts. If thou hadst spent all that is in the earth thou couldst not have attuned their hearts, but Allah hath attuned them. Lo! He is Mighty, Wise.'),
  ('en.pickthall', 8, 64, 'O Prophet! Allah is Sufficient for thee and those who follow thee of the believers.'),
  ('en.pickthall', 8, 65, 'O Prophet! Exhort the believers to fight. If there be of you twenty steadfast they shall overcome two hundred, and if there be of you a hundred (steadfast) they shall overcome a thousand of those who disbelieve, because they (the disbelievers) are a folk without intelligence.'),
  ('en.pickthall', 8, 66, 'Now hath Allah lightened your burden, for He knoweth that there is weakness in you. So if there be of you a steadfast hundred they shall overcome two hundred, and if there be of you a thousand (steadfast) they shall overcome two thousand by permission of Allah. Allah is with the steadfast.'),
  ('en.pickthall', 8, 67, 'It is not for any prophet to have captives until he hath made slaughter in the land. Ye desire the lure of this world and Allah desireth (for you) the Hereafter, and Allah is Mighty, Wise.'),
  ('en.pickthall', 8, 68, 'Had it not been for an ordinance of Allah which had gone before, an awful doom had come upon you on account of what ye took.'),
  ('en.pickthall', 8, 69, 'Now enjoy what ye have won, as lawful and good, and keep your duty to Allah. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 8, 70, 'O Prophet! Say unto those captives who are in your hands: If Allah knoweth any good in your hearts He will give you better than that which hath been taken from you, and will forgive you. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 8, 71, 'And if they would betray thee, they betrayed Allah before, and He gave (thee) power over them. Allah is Knower, Wise.'),
  ('en.pickthall', 8, 72, 'Lo! those who believed and left their homes and strove with their wealth and their lives for the cause of Allah, and those who took them in and helped them: these are protecting friends one of another. And those who believed but did not leave their homes, ye have no duty to protect them till they leave their homes; but if they seek help from you in the matter of religion then it is your duty to help (them) except against a folk between whom and you there is a treaty. Allah is Seer of what ye do.'),
  ('en.pickthall', 8, 73, 'And those who disbelieve are protectors one of another - If ye do not so, there will be confusion in the land, and great corruption.'),
  ('en.pickthall', 8, 74, 'Those who believed and left their homes and strove for the cause of Allah, and those who took them in and helped them - these are the believers in truth. For them is pardon, and bountiful provision.'),
  ('en.pickthall', 8, 75, 'And those who afterwards believed and left their homes and strove along with you, they are of you; and those who are akin are nearer one to another in the ordinance of Allah. Lo! Allah is Knower of all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 8, 1, 'They ask thee concerning (things taken as) spoils of war. Say: "(such) spoils are at the disposal of Allah and the Messenger: So fear Allah, and keep straight the relations between yourselves: Obey Allah and His Messenger, if ye do believe."'),
  ('en.yusufali', 8, 2, 'For, Believers are those who, when Allah is mentioned, feel a tremor in their hearts, and when they hear His signs rehearsed, find their faith strengthened, and put (all) their trust in their Lord;'),
  ('en.yusufali', 8, 3, 'Who establish regular prayers and spend (freely) out of the gifts We have given them for sustenance:'),
  ('en.yusufali', 8, 4, 'Such in truth are the believers: they have grades of dignity with their Lord, and forgiveness, and generous sustenance:'),
  ('en.yusufali', 8, 5, 'Just as thy Lord ordered thee out of thy house in truth, even though a party among the Believers disliked it,'),
  ('en.yusufali', 8, 6, 'Disputing with thee concerning the truth after it was made manifest, as if they were being driven to death and they (actually) saw it.'),
  ('en.yusufali', 8, 7, 'Behold! Allah promised you one of the two (enemy) parties, that it should be yours: Ye wished that the one unarmed should be yours, but Allah willed to justify the Truth according to His words and to cut off the roots of the Unbelievers;-'),
  ('en.yusufali', 8, 8, 'That He might justify Truth and prove Falsehood false, distasteful though it be to those in guilt.'),
  ('en.yusufali', 8, 9, 'Remember ye implored the assistance of your Lord, and He answered you: "I will assist you with a thousand of the angels, ranks on ranks."'),
  ('en.yusufali', 8, 10, 'Allah made it but a message of hope, and an assurance to your hearts: (in any case) there is no help except from Allah: and Allah is Exalted in Power, Wise.'),
  ('en.yusufali', 8, 11, 'Remember He covered you with a sort of drowsiness, to give you calm as from Himself, and he caused rain to descend on you from heaven, to clean you therewith, to remove from you the stain of Satan, to strengthen your hearts, and to plant your feet firmly therewith.'),
  ('en.yusufali', 8, 12, 'Remember thy Lord inspired the angels (with the message): "I am with you: give firmness to the Believers: I will instil terror into the hearts of the Unbelievers: smite ye above their necks and smite all their finger-tips off them."'),
  ('en.yusufali', 8, 13, 'This because they contended against Allah and His Messenger: If any contend against Allah and His Messenger, Allah is strict in punishment.'),
  ('en.yusufali', 8, 14, 'Thus (will it be said): "Taste ye then of the (punishment): for those who resist Allah, is the penalty of the Fire."'),
  ('en.yusufali', 8, 15, 'O ye who believe! when ye meet the Unbelievers in hostile array, never turn your backs to them.'),
  ('en.yusufali', 8, 16, 'If any do turn his back to them on such a day - unless it be in a stratagem of war, or to retreat to a troop (of his own)- he draws on himself the wrath of Allah, and his abode is Hell,- an evil refuge (indeed)!'),
  ('en.yusufali', 8, 17, 'It is not ye who slew them; it was Allah: when thou threwest (a handful of dust), it was not thy act, but Allah\'s: in order that He might test the Believers by a gracious trial from Himself: for Allah is He Who heareth and knoweth (all things).'),
  ('en.yusufali', 8, 18, 'That, and also because Allah is He Who makes feeble the plans and stratagem of the Unbelievers.'),
  ('en.yusufali', 8, 19, '(O Unbelievers!) if ye prayed for victory and judgment, now hath the judgment come to you: if ye desist (from wrong), it will be best for you: if ye return (to the attack), so shall We. Not the least good will your forces be to you even if they were multiplied: for verily Allah is with those who believe!'),
  ('en.yusufali', 8, 20, 'O ye who believe! Obey Allah and His Messenger, and turn not away from him when ye hear (him speak).'),
  ('en.yusufali', 8, 21, 'Nor be like those who say, "We hear," but listen not:'),
  ('en.yusufali', 8, 22, 'For the worst of beasts in the sight of Allah are the deaf and the dumb,- those who understand not.'),
  ('en.yusufali', 8, 23, 'If Allah had found in them any good. He would indeed have made them listen: (As it is), if He had made them listen, they would but have turned back and declined (Faith).'),
  ('en.yusufali', 8, 24, 'O ye who believe! give your response to Allah and His Messenger, when He calleth you to that which will give you life; and know that Allah cometh in between a man and his heart, and that it is He to Whom ye shall (all) be gathered.'),
  ('en.yusufali', 8, 25, 'And fear tumult or oppression, which affecteth not in particular (only) those of you who do wrong: and know that Allah is strict in punishment.'),
  ('en.yusufali', 8, 26, 'Call to mind when ye were a small (band), despised through the land, and afraid that men might despoil and kidnap you; But He provided a safe asylum for you, strengthened you with His aid, and gave you Good things for sustenance: that ye might be grateful.'),
  ('en.yusufali', 8, 27, 'O ye that believe! betray not the trust of Allah and the Messenger, nor misappropriate knowingly things entrusted to you.'),
  ('en.yusufali', 8, 28, 'And know ye that your possessions and your progeny are but a trial; and that it is Allah with Whom lies your highest reward.'),
  ('en.yusufali', 8, 29, 'O ye who believe! if ye fear Allah, He will grant you a criterion (to judge between right and wrong), remove from you (all) evil (that may afflict) you, and forgive you: for Allah is the Lord of grace unbounded.'),
  ('en.yusufali', 8, 30, 'Remember how the Unbelievers plotted against thee, to keep thee in bonds, or slay thee, or get thee out (of thy home). They plot and plan, and Allah too plans; but the best of planners is Allah.'),
  ('en.yusufali', 8, 31, 'When Our Signs are rehearsed to them, they say: "We have heard this (before): if we wished, we could say (words) like these: these are nothing but tales of the ancients."'),
  ('en.yusufali', 8, 32, 'Remember how they said: "O Allah if this is indeed the Truth from Thee, rain down on us a shower of stones form the sky, or send us a grievous penalty."'),
  ('en.yusufali', 8, 33, 'But Allah was not going to send them a penalty whilst thou wast amongst them; nor was He going to send it whilst they could ask for pardon.'),
  ('en.yusufali', 8, 34, 'But what plea have they that Allah should not punish them, when they keep out (men) from the sacred Mosque - and they are not its guardians? No men can be its guardians except the righteous; but most of them do not understand.'),
  ('en.yusufali', 8, 35, 'Their prayer at the House (of Allah) is nothing but whistling and clapping of hands: (Its only answer can be), "Taste ye the penalty because ye blasphemed."'),
  ('en.yusufali', 8, 36, 'The Unbelievers spend their wealth to hinder (man) from the path of Allah, and so will they continue to spend; but in the end they will have (only) regrets and sighs; at length they will be overcome: and the Unbelievers will be gathered together to Hell;-'),
  ('en.yusufali', 8, 37, 'In order that Allah may separate the impure from the pure, put the impure, one on another, heap them together, and cast them into Hell. They will be the ones to have lost.'),
  ('en.yusufali', 8, 38, 'Say to the Unbelievers, if (now) they desist (from Unbelief), their past would be forgiven them; but if they persist, the punishment of those before them is already (a matter of warning for them).'),
  ('en.yusufali', 8, 39, 'And fight them on until there is no more tumult or oppression, and there prevail justice and faith in Allah altogether and everywhere; but if they cease, verily Allah doth see all that they do.'),
  ('en.yusufali', 8, 40, 'If they refuse, be sure that Allah is your Protector - the best to protect and the best to help.'),
  ('en.yusufali', 8, 41, 'And know that out of all the booty that ye may acquire (in war), a fifth share is assigned to Allah,- and to the Messenger, and to near relatives, orphans, the needy, and the wayfarer,- if ye do believe in Allah and in the revelation We sent down to Our servant on the Day of Testing,- the Day of the meeting of the two forces. For Allah hath power over all things.'),
  ('en.yusufali', 8, 42, 'Remember ye were on the hither side of the valley, and they on the farther side, and the caravan on lower ground than ye. Even if ye had made a mutual appointment to meet, ye would certainly have failed in the appointment: But (thus ye met), that Allah might accomplish a matter already enacted; that those who died might die after a clear Sign (had been given), and those who lived might live after a Clear Sign (had been given). And verily Allah is He Who heareth and knoweth (all things).'),
  ('en.yusufali', 8, 43, 'Remember in thy dream Allah showed them to thee as few: if He had shown them to thee as many, ye would surely have been discouraged, and ye would surely have disputed in (your) decision; but Allah saved (you): for He knoweth well the (secrets) of (all) hearts.'),
  ('en.yusufali', 8, 44, 'And remember when ye met, He showed them to you as few in your eyes, and He made you appear as contemptible in their eyes: that Allah might accomplish a matter already enacted. For to Allah do all questions go back (for decision).'),
  ('en.yusufali', 8, 45, 'O ye who believe! When ye meet a force, be firm, and call Allah in remembrance much (and often); that ye may prosper:'),
  ('en.yusufali', 8, 46, 'And obey Allah and His Messenger; and fall into no disputes, lest ye lose heart and your power depart; and be patient and persevering: For Allah is with those who patiently persevere:'),
  ('en.yusufali', 8, 47, 'And be not like those who started from their homes insolently and to be seen of men, and to hinder (men) from the path of Allah: For Allah compasseth round about all that they do.'),
  ('en.yusufali', 8, 48, 'Remember Satan made their (sinful) acts seem alluring to them, and said: "No one among men can overcome you this day, while I am near to you": But when the two forces came in sight of each other, he turned on his heels, and said: "Lo! I am clear of you; lo! I see what ye see not; Lo! I fear Allah: for Allah is strict in punishment."'),
  ('en.yusufali', 8, 49, 'Lo! the hypocrites say, and those in whose hearts is a disease: "These people,- their religion has misled them." But if any trust in Allah, behold! Allah is Exalted in might, Wise.'),
  ('en.yusufali', 8, 50, 'If thou couldst see, when the angels take the souls of the Unbelievers (at death), (How) they smite their faces and their backs, (saying): "Taste the penalty of the blazing Fire-'),
  ('en.yusufali', 8, 51, '"Because of (the deeds) which your (own) hands sent forth; for Allah is never unjust to His servants:'),
  ('en.yusufali', 8, 52, '"(Deeds) after the manner of the people of Pharaoh and of those before them: They rejected the Signs of Allah, and Allah punished them for their crimes: for Allah is Strong, and Strict in punishment:'),
  ('en.yusufali', 8, 53, '"Because Allah will never change the grace which He hath bestowed on a people until they change what is in their (own) souls: and verily Allah is He Who heareth and knoweth (all things)."'),
  ('en.yusufali', 8, 54, '(Deeds) after the manner of the people of Pharaoh and those before them": They treated as false the Signs of their Lord: so We destroyed them for their crimes, and We drowned the people of Pharaoh: for they were all oppressors and wrong-doers.'),
  ('en.yusufali', 8, 55, 'For the worst of beasts in the sight of Allah are those who reject Him: They will not believe.'),
  ('en.yusufali', 8, 56, 'They are those with whom thou didst make a covenant, but they break their covenant every time, and they have not the fear (of Allah).'),
  ('en.yusufali', 8, 57, 'If ye gain the mastery over them in war, disperse, with them, those who follow them, that they may remember.'),
  ('en.yusufali', 8, 58, 'If thou fearest treachery from any group, throw back (their covenant) to them, (so as to be) on equal terms: for Allah loveth not the treacherous.'),
  ('en.yusufali', 8, 59, 'Let not the unbelievers think that they can get the better (of the godly): they will never frustrate (them).'),
  ('en.yusufali', 8, 60, 'Against them make ready your strength to the utmost of your power, including steeds of war, to strike terror into (the hearts of) the enemies, of Allah and your enemies, and others besides, whom ye may not know, but whom Allah doth know. Whatever ye shall spend in the cause of Allah, shall be repaid unto you, and ye shall not be treated unjustly.'),
  ('en.yusufali', 8, 61, 'But if the enemy incline towards peace, do thou (also) incline towards peace, and trust in Allah: for He is One that heareth and knoweth (all things).'),
  ('en.yusufali', 8, 62, 'Should they intend to deceive thee,- verily Allah sufficeth thee: He it is That hath strengthened thee with His aid and with (the company of) the Believers;'),
  ('en.yusufali', 8, 63, 'And (moreover) He hath put affection between their hearts: not if thou hadst spent all that is in the earth, couldst thou have produced that affection, but Allah hath done it: for He is Exalted in might, Wise.'),
  ('en.yusufali', 8, 64, 'O Prophet! sufficient unto thee is Allah,- (unto thee) and unto those who follow thee among the Believers.'),
  ('en.yusufali', 8, 65, 'O Prophet! rouse the Believers to the fight. If there are twenty amongst you, patient and persevering, they will vanquish two hundred: if a hundred, they will vanquish a thousand of the Unbelievers: for these are a people without understanding.'),
  ('en.yusufali', 8, 66, 'For the present, Allah hath lightened your (task), for He knoweth that there is a weak spot in you: But (even so), if there are a hundred of you, patient and persevering, they will vanquish two hundred, and if a thousand, they will vanquish two thousand, with the leave of Allah: for Allah is with those who patiently persevere.'),
  ('en.yusufali', 8, 67, 'It is not fitting for a prophet that he should have prisoners of war until he hath thoroughly subdued the land. Ye look for the temporal goods of this world; but Allah looketh to the Hereafter: And Allah is Exalted in might, Wise.'),
  ('en.yusufali', 8, 68, 'Had it not been for a previous ordainment from Allah, a severe penalty would have reached you for the (ransom) that ye took.'),
  ('en.yusufali', 8, 69, 'But (now) enjoy what ye took in war, lawful and good: but fear Allah: for Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 8, 70, 'O Prophet! say to those who are captives in your hands: "If Allah findeth any good in your hearts, He will give you something better than what has been taken from you, and He will forgive you: for Allah is Oft-forgiving, Most Merciful."'),
  ('en.yusufali', 8, 71, 'But if they have treacherous designs against thee, (O Messenger!), they have already been in treason against Allah, and so hath He given (thee) power over them. And Allah so He Who hath (full) knowledge and wisdom.'),
  ('en.yusufali', 8, 72, 'Those who believed, and adopted exile, and fought for the Faith, with their property and their persons, in the cause of Allah, as well as those who gave (them) asylum and aid,- these are (all) friends and protectors, one of another. As to those who believed but came not into exile, ye owe no duty of protection to them until they come into exile; but if they seek your aid in religion, it is your duty to help them, except against a people with whom ye have a treaty of mutual alliance. And (remember) Allah seeth all that ye do.'),
  ('en.yusufali', 8, 73, 'The Unbelievers are protectors, one of another: Unless ye do this, (protect each other), there would be tumult and oppression on earth, and great mischief.'),
  ('en.yusufali', 8, 74, 'Those who believe, and adopt exile, and fight for the Faith, in the cause of Allah as well as those who give (them) asylum and aid,- these are (all) in very truth the Believers: for them is the forgiveness of sins and a provision most generous.'),
  ('en.yusufali', 8, 75, 'And those who accept Faith subsequently, and adopt exile, and fight for the Faith in your company,- they are of you. But kindred by blood have prior rights against each other in the Book of Allah. Verily Allah is well-acquainted with all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 8, 1, 'Yas\'aloonaka \'anil anfaali qulil anfaalu lillaahi war Rasooli fattaqul laaha wa ahlihoo zaata bainikum wa atee\'ul laaha wa Rasoolahooo in kuntum mu\'mineen'),
  ('en.transliteration', 8, 2, 'Innamal mu\'minoonal lazeena izaa zukiral laahu wajilat quloobuhum wa izaa tuliyat \'alaihim Aayaatuhoo zaadat hum eemaananw wa \'alaa Rabbihim yatawakkaloon'),
  ('en.transliteration', 8, 3, 'Allazeena yuqeemoonas Salaata wa mimmaa razaqnaahum yunfiqoon'),
  ('en.transliteration', 8, 4, 'Ulaaa\'ika humul mu\'minoona haqqaa; lahum darajaatun \'inda Rabbihim wa magh firatunw wa rizqun kareem'),
  ('en.transliteration', 8, 5, 'Kaamaaa akhrajaka Rabbuka mim baitika bilhaqq; wa inna fareeqam minal mu\'mineena lakaarihoon'),
  ('en.transliteration', 8, 6, 'Yujaadiloonaka fil haqqi ba\'da maa tabaiyana kaannamaa yasaaqoona ilal mawti wa hum uanzuroon'),
  ('en.transliteration', 8, 7, 'Wa iz ya\'idukumul laahu ihdat taaa\'ifataini annahaa lakum wa tawaddoona anna ghaira zaatish shawkati takoonu lakum wa yureedul laahu ai yuhiqqal haqqa bikalimaatihee wa taqta\'a daabiral kaafireen'),
  ('en.transliteration', 8, 8, 'Liyuhiqqal haqqa wa tubtilal baatila wa law karihal mujrimoon'),
  ('en.transliteration', 8, 9, 'Iz tastagheesoona Rabbakum fastajaaba lakum annee mumiddukum bi alfim minal malaaa\'ikati murdifeen'),
  ('en.transliteration', 8, 10, 'Wa maa ja\'alahul laahu illaa bushraa wa litatma\'inna bihee quloobukum; wa man nasru illaa min \'indil laah; innal laaha Azeezun Hakeem'),
  ('en.transliteration', 8, 11, 'Iz yughashsheekumun nu\'assa amanatam minhu wa yunazzilu \'alaikum minas samaaa\'i maaa\'al liyutah hirakum bihee wa yuzhiba \'ankum rijzash Shaitaani wa liyarbita \'ala quloobikum wa yusabbita bihil aqdaam'),
  ('en.transliteration', 8, 12, 'Iz yoohee Rabbuka ilal malaaa\'ikati annee ma\'akum fasabbitul lazeena aamanoo; sa ulqee fee quloobil lazeena kafarur ru\'ba fadriboo fawqal a\'naaqi wadriboo minhum kulla banaan'),
  ('en.transliteration', 8, 13, 'Zaalika bi annahum shaaaqqul laaha wa Rasoolah; wa mai yushaqiqil laaha wa Rasoolahoo fa innal laaha shadeedul \'iqaab'),
  ('en.transliteration', 8, 14, 'Zaalikum fazooqoohu wa anna lilkaafireena \'azaaban Naar'),
  ('en.transliteration', 8, 15, 'Yaaa aiyuhal lazeena aamanoo izaa laqeetumul lazeena kafaroo zahfan falaa tuwalloohumul adbaar'),
  ('en.transliteration', 8, 16, 'Wa mai yuwallihim yawma\'izin duburahooo illaa mutaharrifal liqitaalin aw mutahaiyizan ilaa fi\'atin faqad baaa\'a bighadabim minal laahi wa maawaahu Jahannamu wa bi\'sal maseer'),
  ('en.transliteration', 8, 17, 'Falam taqtuloohum wa laakinnal laaha qatalahum; wa maa ramaita iz ramaita wa laakinnal laaha ramaa; wa liyubliyal mu\'mineena minhu balaaa\'an hasanaa; innal laaha Samee\'un Aleem'),
  ('en.transliteration', 8, 18, 'Zaalikum wa annal laaha moohinu kaidil kaafireen'),
  ('en.transliteration', 8, 19, 'In tastaftihoo faqad jaaa\'akumul fathu wa in tantahoo fahuwa khairul lakum wa in ta\'oodoo na\'ud wa lan tughniya \'ankum fi\'atukum shai\'anw wa law kasurat wa annal laaha ma\'al mu\'mineen'),
  ('en.transliteration', 8, 20, 'Yaaa aiyuhal lazeena aamanoo atee\'ul laaha wa Rasoolahoo wa laa tawallaw \'anhu wa antum tasm\'oon'),
  ('en.transliteration', 8, 21, 'Wa laa takoonoo kallazeena qaaloo sami\'naa wa hum laa yasma\'oon'),
  ('en.transliteration', 8, 22, 'Inna sharrad dawaaabbi \'indal laahis summul bukmul lazeena laa ya\'qiloon'),
  ('en.transliteration', 8, 23, 'Wa law \'alimal laahu feehim khairal la asma\'ahum; wa law asma\'ahum latawallaw wa hum mu\'ridoon'),
  ('en.transliteration', 8, 24, 'Yaaa aiyuhal lazeena aamanus tajeeboo lillaahi wa lir Rasooli izaa da\'aakum limaa yuhyeekum wa\'lamooo annal laaha yahoolu bainal mar\'i wa qalbihee wa anahooo ilaihi tuhsharoon'),
  ('en.transliteration', 8, 25, 'Wattaqoo fitnatal laa tuseebannal lazeena zalamoo minkum khaaaassatanw wa\'lamooo annal laaha shadeedul \'iqaab'),
  ('en.transliteration', 8, 26, 'Wazkurooo iz antum qaleelum mustad \'afoona filardi takhaafoona ai yatakhat tafakumun naasu fa aawaakum wa aiyadakum binasrihee wa razaqakum minat taiyibaati la\'allakum tashkuroon'),
  ('en.transliteration', 8, 27, 'Yaaa aiyuhal lazeena aamanoo laa takhoonal laaha war Rasoola wa takhoonooo amaanaatikum wa antum ta\'lamoon'),
  ('en.transliteration', 8, 28, 'Wa\'lamooo annamaaa amwaalukum wa awlaadukum fitnatunw wa annal laaha \'indahooo ajrun azeem'),
  ('en.transliteration', 8, 29, 'Yaaa aiyuhal lazeena aamanooo in tattaqul laaha yaj\'al lakum furqaananw wa yukaffir \'ankum saiyi aatikum wa yaghfir lakum; wallaahu zul fadlil \'azeem'),
  ('en.transliteration', 8, 30, 'Wa iz yamkuru bikal lazeena kafaroo liyusbitooka aw yaqtulooka aw yukhrijook; wa yamkuroona wa yamkurul laahu wallaahu khairul maakireen'),
  ('en.transliteration', 8, 31, 'Wa izaa tutlaa \'alaihim Aayaatunaa qaaloo qad sami\'naa law nashaaa\'u laqulnaa misla haazaaa in haazaaa illaaa asaateerul awwaleen'),
  ('en.transliteration', 8, 32, 'Wa iz qaalul laahumma in kaana haazaa huwal haqqa min \'indika fa amtir \'alainaa hijaaratam minas samaaa\'i awi\'tinaa bi \'azaabin alaeem'),
  ('en.transliteration', 8, 33, 'Wa maa kanal laahu liyu\'az zibahum wa anta feehim; wa maa kaanal laahu mu\'az zibahum wa hum yastaghfiroon'),
  ('en.transliteration', 8, 34, 'Wa maa lahum allaa yu\'az zibahumul laahu wa hum yasuddoona \'anil Masjidil-Haraami wa maa kaanooo awliyaaa\'ah; in awliyaaa\' uhooo illal muttaqoona wa laakinna aksarahum laa ya\'lamoon'),
  ('en.transliteration', 8, 35, 'Wa maa kaana Salaatuhum \'indal Baiti illa mukaaa anw-wa tasdiyah; fazooqul \'azaaba bimaa kuntum takfuroon'),
  ('en.transliteration', 8, 36, 'Innal lazeena kafaroo yunfiqoona amwaalahum liyasuddoo \'an sabeelil laah; fasayunfiqoonahaa summa takoonu \'alaihim hasratan summa yughlaboon; wal lazeena kafarooo ilaa Jahannnama yuhsharoona'),
  ('en.transliteration', 8, 37, 'Liyameezal laahul khabeesa minat taiyibi wa yaj\'alal khabeesa ba\'dahoo \'ala ba\'din fayarkumahoo jamee\'an fayaj\'alahoo fee Jahannnam; ulaaa\'ika humul khaasiroon'),
  ('en.transliteration', 8, 38, 'Qul lillazeena kafarooo iny yantahoo yughfar lahum maa qad salafa wa iny ya\'oodoo faqad madat sunnatul awwaleen'),
  ('en.transliteration', 8, 39, 'Wa qaatiloohum hattaa laa takoona fitnatunw wa yakoonaddeenu kulluhoo lillaah; fainin tahaw fa innallaaha bimaa ya\'maloona Baseer'),
  ('en.transliteration', 8, 40, 'Wa in tawallaw fa\'lamooo annal laaha mawlaakum; ni\'mal mawlaa wa ni\'man naseer'),
  ('en.transliteration', 8, 41, 'Wa\'lamooo annamaa ghanimtum min sha\'in fa anna lillaahi khumusahoo wa lir Rasooli wa lizil qurba walyataamaa walmasaakeeni wabnis sabeeli in kuntum aamantum billaahi wa maaa anzalnaa \'ala \'abdinaa yawmal Furqaani yawmaltaqal jam\'aan; wal laahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 8, 42, 'Iz antum bil\'udwatid dunyaa wa hum bil\'udwatil quswaa warrakbu asfala minkum; wa law tawaa\'attum lakhtalaftum fil mee\'aadi wa laakil liyaqdiyal laahu amran kaana maf\'oolal liyahlika man halaka \'am baiyinatinw wa yahyaa man haiya \'am baiyinah; wa innal laaha la Samee\'un \'Aleem'),
  ('en.transliteration', 8, 43, 'Iz yureekahumul laahu fee manaamika qaleela; wa law araakahum kaseeral lafashiltum wa latanaaza\'tum fil amri wa laakinnal laaha sallam; innahoo \'aleemum bizaatis sudoor'),
  ('en.transliteration', 8, 44, 'Wa iz yureekumoohum izil taqaitum feee a\'yunikum qaleelanw wa yuqallilukum feee a\'yunihim liyaqdiyal laahu amran kaana maf\'oolaa; wa ilal laahi turja\'ul umoor'),
  ('en.transliteration', 8, 45, 'Yaaa aiyuhal lazeena aamanooo izaa laqeetum fi\'atan fasbutoo wazkurul laaha kaseeral la\'allakum tuflihoon'),
  ('en.transliteration', 8, 46, 'Wa atee\'ul laaha wa Rasoolahoo wa laa tanaaza\'oo fatafshaloo wa tazhaba reehukum wasbiroo; innal laaha ma\'as saabireen'),
  ('en.transliteration', 8, 47, 'Wa laa takoonoo kallazeena kharajoo min diyaarihim bataranw wa ri\'aaa\'an naasi wa yasuddoona \'an sabeelil laah; wallaahu bimaa ya\'maloona muheet'),
  ('en.transliteration', 8, 48, 'Wa iz zaiyana lahumush shaitaanu a\'ma alahum wa qaala laa ghaaliba lakumul yawma minan naasi wa innee jaarul lakum falammaa taraaa\'atil fi\'ataani nakasa \'alaa aqibaihi wa qaala innee bareee\'um minkum innee araa maa laa tarawna inneee akhaaful laah; wallaahu shadeedul \'iqaab'),
  ('en.transliteration', 8, 49, 'Iz yaqoolul munaafiqoona wallazeena fee quloobihim maradun gharra haaa\'ulaaa\'i deenuhum; wa mai yatawakkal \'alal laahi fa innal laaha \'azee zun Hakeem'),
  ('en.transliteration', 8, 50, 'Wa law taraaa iz yatawaf fal lazeena kafarul malaaa\'ikatu yadriboona wujoohahum wa adbaarahum wa zooqoo \'azaabal hareeq'),
  ('en.transliteration', 8, 51, 'Zaalika bimaa qaddamat aideekum wa anal laaha laisa bizallaamil lil \'abeed'),
  ('en.transliteration', 8, 52, 'Kadaabi Aali Fir\'awna wal lazeena min qablihim; kafaroo bi Aayaatil laahi fa akhazahu mul laahu bizunoobihim; innal laaha qawiyyun shadeedul \'iqaab'),
  ('en.transliteration', 8, 53, 'Zaalika bi annal laaha lam yaku mughaiyiran ni matan an\'amahaa \'alaa qawmin hattaa yughaiyiroo maa bianfusihim wa annallaaha samee un \'Aleem'),
  ('en.transliteration', 8, 54, 'Kadaabi Aali Fir\'awna wallazeena min qablihim; kazzaboo bi Aayaati Rabbihim faahlaknaahum bizunoobihim wa aghraqnaa Aala Fir\'awn; wa kullun kaanoo zaalimeen'),
  ('en.transliteration', 8, 55, 'Inna sharrad dawaaabbi \'indal laahil lazeena kafaroo fahum laa yu\'minoon'),
  ('en.transliteration', 8, 56, 'Allazeena\'aahatta min hum summa yanqudoona \'ahdahum fee kulli marratinw wa hum laa yattaqoon'),
  ('en.transliteration', 8, 57, 'Fa immaa tasqafannahum fil harbi fasharrid bihim man khalfahum la\'allahum yazzakkaroon'),
  ('en.transliteration', 8, 58, 'Wa immaa takhaafana min qawmin khiyaanatan fambiz ilaihim \'alaa sawaaa\'; innal laaha laayuhibbul khaaa\'ineen'),
  ('en.transliteration', 8, 59, 'Wa laa yahsabannal lazeena kafaroo sabaqooo; innahum laa yu\'jizoon'),
  ('en.transliteration', 8, 60, 'Wa a\'iddoo lahum mastata\'tum min quwwatinw wa mirribaatil khaili turhiboona bihee \'aduwwal laahi wa \'aduwwakum wa aakhareena min doonihim laa ta\'lamoo nahum Allaahu ya\'lamuhum; wa maa tunfiqoo min shai\'in fee sabeelil laahi yuwaf failaikum wa antum laa tuzlamoon'),
  ('en.transliteration', 8, 61, 'Wa in janahoo lissalmi fajnah lahaa wa tawakkal \'alal laah; innahoo Huwas Samee\'ul \'Aleem'),
  ('en.transliteration', 8, 62, 'Wa iny yureedooo any-yakhda\'ooka fainna hasbakal laah; Huwal lazeee aiyadaka binasrihee wa bilmu\'mineen'),
  ('en.transliteration', 8, 63, 'Wa allafa baina quloobihim; law anfaqta maa fil ardi jamee\'am maaa allafta baina quloobihim wa laakinnallaaha allafa bainahum; innaahoo \'Azeezun Hakeem'),
  ('en.transliteration', 8, 64, 'Yaaa aiyuhan Nabiyyu hasbukal laahu wa manittaba \'aka minal mu\'mineen'),
  ('en.transliteration', 8, 65, 'Yaaa aiyuhan Nabiyyu harridil mu\'mineena \'alal qitaal; iny-yakum minkum \'ishroona saabiroona yaghliboo mi\'atayn; wa iny-yakum minkum min\'atuny yaghlibooo alfam minal lazeena kafaroo bi anahum qawmul laa yafqahoon'),
  ('en.transliteration', 8, 66, 'Al\'aana khaffafal laahu \'ankum wa \'alima anna feekum da\'faa; fa-iny yakum minkum mi\'atun saabiratuny yaghliboo mi\'atayn; wa iny-yakum minkum alfuny yaghlibooo alfaini bi iznil laah; wallaahu ma\'as saabireen'),
  ('en.transliteration', 8, 67, 'Maa kaana li Nabiyyin ai yakoona lahooo asraa hatta yuskhina fil ard; tureedoona aradad dunyaa wallaahu yureedul Aakhirah; wallaahu \'Azeezun Hakeem'),
  ('en.transliteration', 8, 68, 'Law laa Kitaabum minal laahi sabaqa lamassakum fee maaa akhaztum \'azaabun \'azeem'),
  ('en.transliteration', 8, 69, 'Fakuloo mimaa ghanimtum halaalan taiyibaa; watta qullaah; innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 8, 70, 'Yaaa aiyuhan Nabiyyu qul liman feee aideekum minal asraaa iny-ya lamillaahu fee quloobikum khairany yu\'tikum khayram mimmaaa ukhiza minkum wa yaghfir lakum; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 8, 71, 'Wa iny-yureedoo khiyaa nataka faqad khaanullaaha min qablu fa amkana minhum; wallaahu \'aleemum Hakeem'),
  ('en.transliteration', 8, 72, 'Innal lazeena aamanoo wa haajaroo wa jaahadoo bi amwaalihim wa anfusihim fee sabeelil laahi wallazeena aawaw wa nasarooo ulaaa\'ika ba\'duhum awliyaaa\'u ba\'d; wallazeena aamanoo wa lam yuhaajiroo maa lakum minw walaayatihim min shai\'in hatta yuhaajiroo; wa inistan sarookum fid deeni fa\'alaiku munnasru illaa \'alaa qawmim bainakum wa bainahum meesaaq; wallaahu bimaa ta\'maloona Baseer'),
  ('en.transliteration', 8, 73, 'Wallazeena kafaroo ba\'duhum awliyaaa\'u ba\'d; illaa taf\'aloohu takun fitnatun fil ardi wa fasaadun kabeer'),
  ('en.transliteration', 8, 74, 'Wallazeena aamanoo wa haajaroo wa jaahadoo fee sabeelil laahi wallazeena aawaw wa nasarooo ulaaa\'ika humul mu\'minoona haqqaa; lahum maghfiratunw wa rizqun kareem'),
  ('en.transliteration', 8, 75, 'Wallazeena aamanoo mim ba\'du wa haajaroo wa jaahadoo ma;akum faulaaa\'ika minkum; wa ulul arhaami baduhum awlaa biba\'din fee Kitaabil laah; innal laaha bikulli shai\'in \'Aleem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 8, 1, 'تجھ سے غنیمت کا حکم پوچھتے ہیں کہہ دے غنیمت کا مال الله اور رسول کا ہے سو الله سے ڈرو اور آپس میں صلح کرو اور الله اور اس کے رسول کا حکم مانو اگر ایمان دار ہو'),
  ('ur.ahmedali', 8, 2, 'ایمان والے وہی ہیں جب الله کا نام آئے تو ان کے دل ڈر جائیں اورجب اس کی آیتیں ان پر پڑھی جائیں تو ان کا ایمان زیادہ ہو جاتا ہے اور اور وہ اپنے رب پر بھروسہ رکھتے ہیں'),
  ('ur.ahmedali', 8, 3, 'وہ جو نماز قائم کرتے ہیں اور جو ہم نے انہیں رزق دیا ہے اس میں سے خرچ کرتے ہیں'),
  ('ur.ahmedali', 8, 4, 'یہی سچے ایمان والے ہیں ان کے رب کے ہاں ان کے لیے درجے ہیں اور بخشش ہے اور عزت کا رزق ہے'),
  ('ur.ahmedali', 8, 5, 'جیسے تیرے رب نے تیرے گھر سے سچائی کے ساتھ نکالا اور بے شک ایک جماعت مسلمانوں میں سے نا پسند کرنے والی تھی'),
  ('ur.ahmedali', 8, 6, 'وہ تجھ سے حق بات میں اس کے ظاہر ہو چکنے کے بعد جھگڑتے تھے گویا وہ آنکھوں سے دیکھتے ہوئے موت کی طرف ہانکے جاتے ہیں'),
  ('ur.ahmedali', 8, 7, 'اور جس وقت دو جماعتوں میں سے ایک کا الله تم سے وعدہ کرتا تھا کہ وہ تمہارے ہاتھ لگے گی اور تم چاہتے تھے جس میں کانٹا نہ ہو وہ تمہیں ملے اور الله چاہتا تھا کہ اپنے حکم سے حق کو ثابت کردے اور کافروں کی جڑ کاٹ دے'),
  ('ur.ahmedali', 8, 8, 'تاکہ حق کو ثابت کر دے اور باطل کو مٹا دے اگرچہ گناہگار ناراض ہوں'),
  ('ur.ahmedali', 8, 9, 'جب تم اپنے رب سے فریاد کر رہے تھے اس نے جواب میں فرمایا کہ میں تمہاری مدد کے لیے پے درپے ایک ہزار فرشتے بھیج رہا ہوں'),
  ('ur.ahmedali', 8, 10, 'اور یہ تو الله نے فقط خوش خبری دی تھی اور تاکہ تمہارے دل اس سے مطمئن ہو جائیں اور مدد تو صرف الله ہی کی طرف سے ہے بے شک الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 8, 11, 'جس وقت اس نے تم پر اپنی طرف سے تسکین کے لیے اونگھ ڈال دی اور تم پر آسمان سے پانی اتارا تاکہ اس سے تمہیں پاک کر دے اور شیطان کی نجاست تم سے دور کر دے اور تمہارے دلوں کو مضبوط کر دے اور اس سے تمہارے قدم جما دے'),
  ('ur.ahmedali', 8, 12, 'جب تیرے رب نے فرشتوں کو حکم بھیجا کہ میں تمہارے ساتھ ہوں تم مسلمانوں کے دل ثابت رکھو میں کافروں کے دلوں میں دہشت ڈال دوں گا سو گردنوں پر مارواور ان کے پور پور پر مارو'),
  ('ur.ahmedali', 8, 13, 'یہ اس لیے ہے کہ وہ الله اوراس کے رسول کے مخالف ہیں اور جو کوئی اللہ اور اس کےرسول کا مخالف ہو تو بے شک الله سخت عذب دینے والا ہے'),
  ('ur.ahmedali', 8, 14, 'یہ تو چکھ لو اور جان لو کہ بے شک کافروں کے لیے دوزخ کا عذاب ہے'),
  ('ur.ahmedali', 8, 15, 'اے ایمان والو جب تم کافروں سے میدان جنگ میں ملو تو ان سے پیٹھیں نہ پھیرو'),
  ('ur.ahmedali', 8, 16, 'اور جو کوئی اس دن ان سے پیٹھ پھیرے گا مگر یہ کہ لڑائی کا ہنر کرتا ہو یا فوج میں جا ملتا ہو سو وہ الله کا غضب لے کر پھرا اور اس کا ٹھکانا دوزخ ہے اور بہت برا ٹھکانا ہے'),
  ('ur.ahmedali', 8, 17, 'سو تم نے انہیں قتل نہیں کیا بلکہ الله نے انہیں قتل کیا اور تو نے مٹھی نہیں پھینکی جب کہ پھینکی تھی بلکہ الله نے پھینکی تھی اور تاکہ ایمان والوں پر اپنی طرف سے خوب احسان کرے بے شک الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 8, 18, 'یہ تو ہو چکا اور بےشک الله کافروں کی تدبیر کو کمزور کرنے والا ہے'),
  ('ur.ahmedali', 8, 19, 'اگر تم فیصلہ چاہتے ہو تو تمہارا فیصلہ آ چکا اور اگر باز آؤ تو تمہارے لیے بہتر ہے اور اگر پھر یہی کرو گے تو ہم بھی پھر یہی کریں گے اور تمہاری جمعیت ذرا بھی کام نہیں آئے گی اگرچہ وہ بہت ہوں اوربے شک اللہ ایمان والوں کے ساتھ ہے'),
  ('ur.ahmedali', 8, 20, 'اے ایمان والو الله اور اس کے رسول کا حکم مانو اور سن کر اس سے مت پھرو'),
  ('ur.ahmedali', 8, 21, 'اور ان لوگو ں کی طرح نہ ہو جنہوں نے کہا ہم نے سن لیا اور وہ سنتے نہیں'),
  ('ur.ahmedali', 8, 22, 'بے شک سب جانوں میں سے بدتر الله کے نزدیک وہی بہرے گونگے ہیں جو نہیں سمجھتے'),
  ('ur.ahmedali', 8, 23, 'اور اگر الله ان میں کچھ بھلائی جانتا تو انہیں سنا دیتا اور اگر انہیں اب سنا دے تو منہ پھیر کر بھاگیں'),
  ('ur.ahmedali', 8, 24, 'اے ایمان والو الله اور رسول کا حکم مانو جس وقت تمہیں اس کام کی طرف بلائے جس میں تمہاری زندگی ہے اور جان لو کہ الله آدمی اور اس کے دل کے درمیان آڑ بن جاتا ہے اور بے شک اسی کی طرف جمع کیے جاؤ گے'),
  ('ur.ahmedali', 8, 25, 'اور تم اس فتنہ سے بچتے رہو جو تم میں سے خاص ظالموں پر ہی نہ پڑے گا اور جان لو کہ بے شک الله سخت عذاب کرنے والا ہے'),
  ('ur.ahmedali', 8, 26, 'اور یاد کرو جس وقت تم تھوڑے تھے ملک میں کمزور سمجھے جاتے تھے تم ڈرتے تھے کہ لوگ تمہیں اچک لیں پھر اس نے تمہیں ٹھکانا بنا دیا اور اپنی مدد سے تمہیں قوت دی اور تمہیں ستھری چیزوں سے رزق دیاتاکہ تم شکر کرو'),
  ('ur.ahmedali', 8, 27, 'اے ایمان والو الله اور اس کے رسول سے خیانت نہ کرو اور آپس کی امانتوں میں بھی خیانت نہ کرو حالانکہ تم جانتے ہو'),
  ('ur.ahmedali', 8, 28, 'اور جان لو کہ تمہارے مال اور تمہاری اولاد ایک امتحان کی چیز ہے اور بے شک الله کہ ہاں بڑا اجر ہے'),
  ('ur.ahmedali', 8, 29, 'اے ایمان والو اگر تم الله سے ڑرتے رہو گے تو الله تمہیں ایک فیصلہ کی چیز دے گا اور تم سے تمہارے گناہ دور کر دے گا اور تمہیں بخش دے گا اور الله بڑے فضل والا ہے'),
  ('ur.ahmedali', 8, 30, 'اور جب کافر تیرے متعلق تدبیریں سوچ رہے تھے کہ تمہیں قید کر دیں یا تمہیں قتل کر دیں یا تمہیں دیس بدر کر دیں وہ اپنی تدبیریں کر رہے تھے اور الله ہی اپنی تدبیر کر ہا تھا اور الله بہترین تدبیر کرنے والا ہے'),
  ('ur.ahmedali', 8, 31, 'اور جب ان کے سامنے ہماری آیتیں پڑھی جاتی ہیں تو کہتے ہیں کہ ہم نے سن لیا اور اگر ہم چاہیں تو اس کے برابر ہم بھی کہہ دیں اس میں پہلو ں کے قصے کے سوا اور کچھ نہیں'),
  ('ur.ahmedali', 8, 32, 'اورجب انہوں نے کہا کہ اے الله اگر یہ دین تیری طرف سے حق ہے تو ہم پر آسمان سے پتھر برسا یا ہم پر دردناک عذاب لا'),
  ('ur.ahmedali', 8, 33, 'اور الله ایسا نہ کرے گا کہ انہیں تیرتے ہوئے عذاب دے اور الله عذاب کرنے الا نہیں درآنحالیکہ وہ بخشش مانگتے ہوں'),
  ('ur.ahmedali', 8, 34, 'اور الله انہیں عذاب کیوں نہ دے حالانکہ وہ مسجد حرام سے روکتے ہیں اور وہ اس کے اہل نہیں ہیں اس میں تو اہل پرہیزگاری ہیں لیکن ان میں سے اکثر نہیں سمجھتے'),
  ('ur.ahmedali', 8, 35, 'اورکعبہ کے پاس ان کی نماز سوائے سیٹیاں اور تالیاں بجانے کے اور کچھ نہیں تھی سو عذاب سبب اس کے کہ تم کفر کرتے تھے'),
  ('ur.ahmedali', 8, 36, 'بے شک جو لوگ کافر ہیں وہ اپنے مال خرچ کرتے ہیں تاکہ الله کی راہ سے روکیں سو ابھی اور بھی خرچ کریں گے پھر وہ ان کے لیے حسرت ہو گا پھر مغلوب کیے جائیں گے اور جو کافر ہیں وہ دوزخ کی طرف جمع کیے جائیں گے'),
  ('ur.ahmedali', 8, 37, 'تاکہ الله ناپاک کو پاک سے جدا کر دے اور ایک ناپاک کو دوسرے پر دھر کر ڈھیر بنائے پھر اسے دوزخ میں ڈال دے وہی لوگ نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 8, 38, 'کافروں سے کہہ دو اگر وہ باز آجائيں تو جو کچھ گزر چکا وہ انہیں معاف کر دیا جائے گا اور اگر لوٹیں گے تو پہلے کافروں کے حق میں قانون نافذ ہو چکا ہے'),
  ('ur.ahmedali', 8, 39, 'اور تم ان سے اس حد تک لڑو کہ شرک کا غلبہ نہ رہنے پائے اور سارا دین الله ہی کا ہو جکائے پھر اگر یہ باز آجائیں تو الله ان کے اعمال دیکھنے والا ہے'),
  ('ur.ahmedali', 8, 40, 'اور اگر وہ پھر جائیں تو جان لو کہ الله تمہارا دوست ہے اور بہت اچھا دوست ہے اوربہت اچھا مددگار ہے'),
  ('ur.ahmedali', 8, 41, 'اور جان لو کہ جو کچھ تمہیں بطور غنیمت ملے خواہ کوئی چیز ہو تو اس میں سے پانچواں حصہ الله اور اس کے رسول کا ہے اور رشتہ داروں اور یتیموں اور مسکینوں اور مسافروں کے لیے ہے اگر تمہیں الله پر یقین ہے اور اس چیز پر جو ہم نے اپنے بندے پر فیصلہ کے دن اتاری جس دن دونوں جماعتیں ملیں اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 8, 42, 'جس وقت تم درلے کنارے پر تھے اور وہ پرلےکنارے پر اور قافلہ تم سے نیچے اتر گیا تھا اور اگرتم آپس میں وعدہ کرتے تو ایک ساتھ وعدہ پر نہ پہنچتے لیکن الله کو ایک کام کرنا تھا جو مقرر ہو چکا تھا تاکہ جو ہلاک وہ اتمام حجت کے بعد ہلاک ہو اور جو زندہ رہے وہ اتمام حجت کے بعد زندہ رہے اور بے شک الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 8, 43, 'جب کہ الله نے وہ کافر تجھے تیرے خواب میں تھوڑے کر کے دکھلائے اور اگرتجھے بہت دکھلا دیتا تو تم لوگ نامردی کر تے اور کام میں جھگڑا ڈالتے لیکن الله نے بچا لیا جو بات دلوں میں ہے وہ اسے خوب معلوم ہے'),
  ('ur.ahmedali', 8, 44, 'اور جب تمہیں وہ فوج مقابلہ کے وقت تمہاری آنکھوں میں تھوڑی کر کے دکھائی اور تمہیں ان کی آنکھوں میں تھوڑا کر کے دکھایا تاکہ الله ایک کام پورا کر دے جو مقرر ہو چکا تھا اور ہر کام الله تک ہی پہنچتا ہے'),
  ('ur.ahmedali', 8, 45, 'اے ایمان والو! جب کسی فوج سے ملو تو ثابت قدم رہو اور الله کو بہت یاد کرو تاکہ تم نجات پاؤ'),
  ('ur.ahmedali', 8, 46, 'اور الله اوراس کے رسول کا کہا مانو اور آپس میں نہ جھگڑو ورنہ بزدل ہو جاؤ گے اور تمہاری ہوا اکھڑ جائے گی اور صبر کرو بے شک الله صبر کرنے والوں کے ساتھ ہے'),
  ('ur.ahmedali', 8, 47, 'اور ان لوگوں جیسا نہ ہونا جو اتراتے ہوئے اور لوگوں کو دکھانے کے لیے گھروں سے نکل آئے اور الله کی راہ سے روکتے تھے اور جو کچھ یہ کرتے ہیں الله اس پر احاطہ کرنے والا ہے'),
  ('ur.ahmedali', 8, 48, 'اورجس وقت شیطان نے ان کے اعمال کو ان کی نظروں میں خوشنما کر دیا اورکہا کہ آج کے دن لوگوں میں سے کوئی بھی تم پر غالب نہ ہوگا اور میں تمہارا حمایتی ہوں پھر جب دونوں فوجیں سامنے ہوئیں تووہ اپنے ایڑیوں پر الٹا پھرا اور کہا میں تمہارے ساتھ نہیں ہوں میں ایسی چیر دیکھتا ہوں جو تم نہیں دیکھتے میں الله سے ڈرتا ہوں اور الله سخت عذاب کرنے والا ہے'),
  ('ur.ahmedali', 8, 49, 'اس وقت منافق اور جن کے دلو ں میں مرض تھا کہتے تھے کہ انہیں ان کے دین نے مغلوب کر رکھا ہے اور جو کوئی الله پر بھروسہ کرے تو الله زبردست حکمت والا ہے'),
  ('ur.ahmedali', 8, 50, 'اور اگر تو دیکھے جس وقت فرشتے کافروں کی جان قبض کرتے ہیں ان کے مونہوں او رپیٹہوں پر مارتے ہیں اور کہتے ہیں جلنے کا عذاب چکھو'),
  ('ur.ahmedali', 8, 51, 'یہ اسی کا بدلہ ہے جو تمہارے ہاتھوں نے آگے بھیجا اور بے شک الله بندوں پر ظلم نہیں کرتا'),
  ('ur.ahmedali', 8, 52, 'جیسا فرعونیوں اوران سے پہلے لوگوں کا حال ہوا تھا انہوں نے الله کی آیتوں سے انکار کیا تو الله نے ان کے گناہوں کی سزا میں انہیں پکڑ لیا بے شک الله زبردست اور سخت عذاب کرنے والا ہے'),
  ('ur.ahmedali', 8, 53, 'اس کا سبب یہ ہے کہ الله ہر گز اس نعمت کو نہیں بدلتا جو اس نے کسی قوم کو دی تھی جب تک وہ خود اپنے دلوں کی حالت نہ بدلیں اوراس لیے کہ الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 8, 54, 'جیسے فرعونیوں اور ان سے پہلے لوگوں کاحال ہوا تھا انہوں نے اپنے رب کی آیتوں کو جھٹلایا تو ہم نے انہیں ان کے گناہوں کے سبب ہلاک کر ڈالا اور فرعونیوں کو ڈبو دیا اور سب ظالم تھے'),
  ('ur.ahmedali', 8, 55, 'اور الله کے ہاں سب جانداروں میں سے بدتر وہ ہیں جنہوں نے کفر کیا پھر وہ ایمان نہیں لاتے'),
  ('ur.ahmedali', 8, 56, 'جن لوگوں سے تو نے عہد لیا پھر وہ ہر دفعہ اپنے عہد کو توڑتے ہیں اور وہ نہیں ڈرتے'),
  ('ur.ahmedali', 8, 57, 'سو اگر کبھی تو انہیں لڑائی میں پائے تو انہیں ایسی سزا دے کہ ان کے پچھلے دیکھ کر بھاگ جائیں تاکہ انہیں عبرت ہو'),
  ('ur.ahmedali', 8, 58, 'اور اگر تمہیں کسی قوم سے دغابازی کا ڈر ہو تو ان کا عہد ان کی طرف پھینک دو ایسی طرح پر کہ تم اور وہ برابر ہو جاؤ بے شک الله دغا بازوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 8, 59, 'اور کافر یہ نہ خیال کریں کہ وہ بھاگ نکلے ہیں بے شک وہ ہمیں ہر گز عاجز نہ کر سکیں گے'),
  ('ur.ahmedali', 8, 60, 'اور ان سے لڑنے کے لیے جو کچھ (سپاہیانہ) قوت سے پلے ہوئے گھوڑوں سے جمع کر سکو سو تیار رکھو کہ اس سے الله کے دشمنوں پر اور تمہارے دشمنوں پر اور ان کےسوا دوسروں پر جنہیں تم نہیں جانتے الله انہیں جانتا ہے ہیبت پڑے اور الله کی راہ میں جو کچھ تم خرچ کرو گےتمہیں (اس کا ثواب) پورا ملے گا اور تم سے بے انصافی نہیں ہو گی'),
  ('ur.ahmedali', 8, 61, 'اور اگر وہ صلح کے لیے مائل ہوں تو تم بھی مائل ہو جاؤ اور الله پر بھروسہ کرو بے شک وہی سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 8, 62, 'اور اگر وہ چاہیں کہ تمہیں دھوکہ دیں تو تجھے الله کافی ہے جس نے تمہیں اپنی مدد سے اور مسلمانوں سے قوت بحشی'),
  ('ur.ahmedali', 8, 63, 'اور ان کے دلو ں میں الفت ڈال دی جو کچھ زمین میں ہے اگر سارا تو خرچ کر دیتا ان کے دلوں میں الفت نہ ڈال سکتا لیکن الله نے ان میں الفت ڈال دی بے شک الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 8, 64, 'اے نبی! تجھے اور مومنوں کو جو تیرے تابعدار ہیں الله کافی ہے'),
  ('ur.ahmedali', 8, 65, 'اے نبی! مسلمانوں کو جہاد کی ترغیب دو اگر تم میں بیس آدمی ثابت قدم رہنے والے ہوں گے تو وہ سو پر غالب آئیں گے اور اگر تم میں سو ہوں گے تو ہزار کافروں پر غالب آئیں گے اس لیے کہ وہ لوگ کچھ نہیں سمجھتے'),
  ('ur.ahmedali', 8, 66, 'اب الله نےتم سے بوجھ ہلکا کر دیا اور معلوم کر لیا کہ تم میں کس قدر کمزوری ہے پس اگر تم سو ثابت قدم رہنے والے ہوں گے تو دو سو پر غالب آئيں گے اور اگر ہرار ہوں گے تو الله کے حکم سے دو ہزار پر غالب آئيں گے اور الله صبر کرنے والوں کے ساتھ ہے'),
  ('ur.ahmedali', 8, 67, 'نبی کو نہیں چاہیئے کہ اپنے ہاں قیدیوں کو رکھے یہاں تک کہ ملک میں خوب خونریزی کر لے تم دنیا کی زندگی کا سامان چاہتے ہو اور الله آخرت کا ارادہ کرتا ہے اور الله غالب حکمت والا ہے'),
  ('ur.ahmedali', 8, 68, 'اگر الله کا حکم پہلے نہ ہو چکا ہوتا تو جو تم نے لیا اس کے بدلے تم پربڑا عذاب ہوتا'),
  ('ur.ahmedali', 8, 69, 'پس جو مال تمہیں غنیمت میں حلال اور طیب ملا ہے اسے کھاؤ اور الله سے ڈرو بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 8, 70, 'اے نبی! جو قیدی تمہارے ہاتھ میں ہیں ان سے کہہ دو کہ اگر الله تمہارے دلوں میں نیکی معلوم کر ے گا تو تمہیں اس سے بہتر دے گا جو تم سے لیا گیا ہے اور تمہیں بخشے گا اور الله بحشنے والا مہربان ہے'),
  ('ur.ahmedali', 8, 71, 'اور اگر یہ لوگ تم سے دغا کرنا چاہیں گےیہ تو پہلے ہی الله سے دغا کر چکے ہیں پھر الله نے انہیں گرفتار کرا دیا اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 8, 72, 'بے شک جو لوگ ایمان لائے اور گھر چھوڑا اور اپنے مالوں اور جانوں سے الله کی راہ میں لڑے اور جن لوگوں نے جگہ دی اور مدد کی وہ آپس میں ایک دوسرے کے رفیق ہیں اورجو ایمان لائے اور گھر نہیں چھوڑا تمہیں ان کی وراثت سے کوئی تعلق نہیں یہاں تک کہ وہ ہجرت کریں اور اگر وہ دین کے معاملہ میں مدد چاہیں تو تمہیں ان کی مدد کرنی لازم ہے مگران لوگو ں کے مقابلہ میں کہ ان میں اور تم میں عہد ہو اور جو تم کرتے ہو الله اسے دیکھتا ہے'),
  ('ur.ahmedali', 8, 73, 'اور جو لوگ کافر ہیں وہ ایک دوسرے کے رفیق ہیں اگر تم یوں نہ کرو گے تو ملک میں فتنہ پھیلے گا اوروہ بڑا فساد ہوگا'),
  ('ur.ahmedali', 8, 74, 'اور جو لوگ ایمان لائے اوراپنے گھر چھوڑے اور الله کی راہ میں لڑے اورجن لوگوں نے انہیں جگہ دی اور ان کی مدد کی وہی سچے مسلمان ہیں ان کے لیے بخشش اور عزت کی روزی ہے'),
  ('ur.ahmedali', 8, 75, 'اورجو لوگ اس کے بعد ایمان لائے اور گھر چھوڑے اور تمہارے ساتھ ہو کر لڑے سو وہ لوگ بھی تمہیں میں سے ہیں اور رشتہ دار آپس میں الله کے حکم کے مطابق ایک دوسرے کے زیادہ حق دار ہیں بے شک الله ہر چیز سے خبردار ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 8, 1, 'Sana, ganimetlere dair soru sorarlar, de ki: Ganimetler Allah\'ın ve Peygamberindir. İnanıyorsanız Allah\'tan sakının, aranızdaki münasebetleri düzeltin, Allah\'a ve Peygamberine itaat edin.'),
  ('tr.diyanet', 8, 2, 'İnananlar ancak, o kimselerdir ki Allah anıldığı zaman kalbleri titrer, ayetleri okunduğu zaman bu onların imanlarını artırır. Ve Rablerine güvenirler; namaz kılarlar; kendilerine verdiğimiz rızıktan yerli yerince sarf ederler.'),
  ('tr.diyanet', 8, 3, 'İnananlar ancak, o kimselerdir ki Allah anıldığı zaman kalbleri titrer, ayetleri okunduğu zaman bu onların imanlarını artırır. Ve Rablerine güvenirler; namaz kılarlar; kendilerine verdiğimiz rızıktan yerli yerince sarf ederler.'),
  ('tr.diyanet', 8, 4, 'İşte gerçekten inanmış olanlar bunlardır. Onlara Rablerinin katında mertebeler, mağfiret ve cömertçe verilmiş rızıklar vardır.'),
  ('tr.diyanet', 8, 5, 'Nitekim, Rabbin seni hak uğrunda evinden savaş için çıkarmıştı, oysa müslümanların bir takımı bundan hoşlanmamıştı.'),
  ('tr.diyanet', 8, 6, 'Sanki göz göre göre ölüme sürükleniyorlarmış gibi, gerçek ortaya çıktıktan sonra bile seninle tartışıyorlardı.'),
  ('tr.diyanet', 8, 7, 'Allah bu iki taifeden birini size vadetmişti; siz, kuvvetsiz olanın size düşmesini istiyordunuz. Oysa, suçluların hoşuna gitmese de, hakkı ortaya çıkarmak ve batılı tepelemek için, Allah sözleriyle hakkı ortaya koymak ve inkarcıların kökünü kesmek istiyordu.'),
  ('tr.diyanet', 8, 8, 'Allah bu iki taifeden birini size vadetmişti; siz, kuvvetsiz olanın size düşmesini istiyordunuz. Oysa, suçluların hoşuna gitmese de, hakkı ortaya çıkarmak ve batılı tepelemek için, Allah sözleriyle hakkı ortaya koymak ve inkarcıların kökünü kesmek istiyordu.'),
  ('tr.diyanet', 8, 9, 'Rabbinizin yardımına sığınıyordunuz. O, "Ben size, birbiri peşinden bin melekle yardım ederim" diye cevap vermişti.'),
  ('tr.diyanet', 8, 10, 'Allah bunu ancak bir müjde olması ve kalblerinizin yatışması için yapmıştı. Yardım ancak Allah katındandır. Doğrusu Allah güçlüdür, hakimdir.'),
  ('tr.diyanet', 8, 11, 'Allah kendi katından bir güven işareti olarak sizi hafif bir uykuya daldırmıştı. Sizi arıtmak, sizden şeytan vesvesesini gidermek, kalblerinizi pekiştirmek ve sebatınızı artırmak için gökten size su indirmişti.'),
  ('tr.diyanet', 8, 12, 'Rabbin meleklere, "Ben sizinleyim, inananları destekleyin" diye vahyetti. "Ben inkar edenlerin kalblerine korku salacağım, artık vurun onların boyunları üstüne, vurun her parmağına" dedi.'),
  ('tr.diyanet', 8, 13, 'Bu, onların Allah\'a ve Peygamberine karşı koymalarındandır. Kim Allah\'a ve peygamberine karşı koyarsa, bilsin ki, Allah\'ın cezası şiddetlidir.'),
  ('tr.diyanet', 8, 14, 'İşte bunu tadın, inkar edenlere cehennem azabı da vardır.'),
  ('tr.diyanet', 8, 15, 'Ey İnananlar! Savaş için ilerlerken, inkar edenlerle toplu halde karşılaştığınızda onlara arkanızı dönmeyin.'),
  ('tr.diyanet', 8, 16, 'Tekrar savaşmak için bir tarafa çekilmek veya bir başka topluluğa katılmak maksadı dışında, o gün arkasını düşmana dönen kimse Allah\'dan bir gazaba uğramış olur. Onun varacağı yer cehennemdir. Ne kötü bir dönüştür!'),
  ('tr.diyanet', 8, 17, 'Onları siz öldürmediniz fakat Allah öldürdü. Attığın zaman da sen atmamıştın, fakat Allah atmıştı. Allah bunu, inananları güzel bir imtihana tabi tutmak için yapmıştı. Doğrusu O işitir ve bilir.'),
  ('tr.diyanet', 8, 18, 'İşte bu, Allah\'ın inkarcıların düzenini zayıflatıp yok etmesidir.'),
  ('tr.diyanet', 8, 19, 'Ey inkarcılar! Zafer istiyorsanız, işte zafer geldi (aleyhinize çıktı). Peygambere karşı gelmekten vazgeçerseniz sizin iyiliğinize olur, yok tekrar dönerseniz biz de döneriz; topluluğunuz çok da olsa size hiçbir fayda vermez. Allah inananlarla beraberdir.'),
  ('tr.diyanet', 8, 20, 'Ey inananlar! Allah\'a ve Peygamberine itaat edin, Kuran\'ı dinleyip dururken yüz çevirmeyin, dinlemedikleri halde "dinledik" diyenler gibi olmayın.'),
  ('tr.diyanet', 8, 21, 'Ey inananlar! Allah\'a ve Peygamberine itaat edin, Kuran\'ı dinleyip dururken yüz çevirmeyin, dinlemedikleri halde "dinledik" diyenler gibi olmayın.'),
  ('tr.diyanet', 8, 22, 'Allah katında, yeryüzündeki canlıların en kötüsü gerçeği akletmeyen sağırlar ve dilsizlerdir.'),
  ('tr.diyanet', 8, 23, 'Allah onlarda bir iyilik görseydi onlara işittirirdi. Onlara işittirmiş olsaydı yine de yüz çevirirlerdi, zaten dönektirler.'),
  ('tr.diyanet', 8, 24, 'Ey inananlar! Allah ve Peygamber, sizi, hayat verecek şeye çağırdığı zaman icabet edin. Allah\'ın kişi ile kalbi arasına girdiğini ve sonunda O\'nun katında toplanacağınızı bilin.'),
  ('tr.diyanet', 8, 25, 'Aranızdan yalnız zalimlere erişmekle kalmayacak fitneden sakının, Allah\'ın azabının şiddetli olduğunu bilin.'),
  ('tr.diyanet', 8, 26, 'Yeryüzünde az sayıda olduğunuz ve zayıf sayıldığınız için insanların sizi esir olarak alıp götürmesinden korktuğunuz zamanları, hatırlayın. Allah, şükredesiniz diye sizi barındırmış, yardımıyla desteklemiş, temiz şeylerle rızıklandırmıştır.'),
  ('tr.diyanet', 8, 27, 'Ey inananlar! Allah\'a ve Peygambere karşı hainlik etmeyin, size güvenilen şeylere bile bile hıyanet etmiş olursunuz.'),
  ('tr.diyanet', 8, 28, 'Mallarınızın ve çocuklarınızın, aslında bir sınama olduğunu ve büyük ecrin Allah katında bulunduğunu bilin.'),
  ('tr.diyanet', 8, 29, 'Ey inananlar! Allah\'tan sakınırsanız, O size iyiyi kötüden ayırdedecek bir anlayış verir, kötülüklerinizi örter, sizi bağışlar. Allah büyük, bol nimet sahibidir.'),
  ('tr.diyanet', 8, 30, 'İnkar edenler, seni bağlayıp bir yere kapamak veya öldürmek, ya da sürmek için düzen kuruyorlardı. Onlar düzen kurarken, Allah da düzenlerini bozuyordu. Allah düzen yapanların en iyisidir.'),
  ('tr.diyanet', 8, 31, 'Ayetlerimiz onlara okunduğu zaman, "İşittik, işittik! İstesek biz de aynını söyleyebiliriz; bu sadece eskilerin masallarıdır" derlerdi.'),
  ('tr.diyanet', 8, 32, '"Allah\'ımız! Eğer bu Kitap, gerçekten Senin katından ise bize gökten taş yağdır veya can yakıcı bir azab ver" demişlerdi.'),
  ('tr.diyanet', 8, 33, 'Oysa, sen içlerinde iken Allah onlara azabetmez. Onlar bağışlanma dilerlerken de elbette Allah azab edecek değildir.'),
  ('tr.diyanet', 8, 34, 'Yoksa Mescidi Haram\'a girmekten menederlerken Allah onlara niçin azab etmesin? Hem de O\'nun dostu değiller; O\'nun dostları ancak karşı gelmekten sakınanlardır. Fakat çoğu bunu bilmiyorlar.'),
  ('tr.diyanet', 8, 35, 'Kabe\'deki tapınmaları sadece ıslık çalmak ve el çırpmaktan başka bir şey değildir. İnkarınıza karşılık artık azabı tadın.'),
  ('tr.diyanet', 8, 36, 'Doğrusu inkar edenler mallarını Allah\'ın yolundan insanları alıkoymak için sarfederler ve daha da sarfedeceklerdir; ama sonra içleri yanacak, hem de mağlup olacaklardır. Bu, Allah\'ın, temizi murdardan ayırması ve murdarları üstüste koyup hepsini yığarak cehenneme yerleştirmesi içindir; inkar edenler cehenneme toplanacaklardır. İşte onlar mahvolanlardır.'),
  ('tr.diyanet', 8, 37, 'Doğrusu inkar edenler mallarını Allah\'ın yolundan insanları alıkoymak için sarfederler ve daha da sarfedeceklerdir; ama sonra içleri yanacak, hem de mağlup olacaklardır. Bu, Allah\'ın, temizi murdardan ayırması ve murdarları üstüste koyup hepsini yığarak cehenneme yerleştirmesi içindir; inkar edenler cehenneme toplanacaklardır. İşte onlar mahvolanlardır.'),
  ('tr.diyanet', 8, 38, 'İnkar edenlere, eğer savaştan vazgeçerlerse, geçmişlerinin bağışlanacağını ve tekrar başlarlarsa evvelkilerin hükmünün uygulanacağını söyle.'),
  ('tr.diyanet', 8, 39, 'Fitne kalmayıp, yalnız Allah\'ın dini kalana kadar onlarla savaşın. Eğer vazgeçerlerse bilsinler ki Allah onların işlediklerini şüphesiz görür.'),
  ('tr.diyanet', 8, 40, 'Eğer yüz çevirirlerse Allah\'ın sizin dostunuz olduğunu bilin; O ne güzel dost, ne güzel yardımcıdır!'),
  ('tr.diyanet', 8, 41, 'Eğer Allah\'a ve hakkı batıldan ayıran o günde, iki topluluğun karşılaştığı günde kulumuza indirdiğimize inanıyorsanız, bilin ki, ele geçirdiğiniz ganimetin beşte biri Allah\'ın, Peygamber\'in ve yakınlarının, yetimlerin, düşkünlerin ve yolcularındır. Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 8, 42, 'Siz vadiye en yakın ve onlar da en uzak yamaçta idiler; kervanın süvarileri sizden daha aşağıdaydı. Savaş için buluşmak üzere sözleşmeye kalksaydınız, vaktini tayinde anlaşmazlığa düşerdiniz; fakat Allah mahvolan, apaçık belgeden ötürü mahvolsun, yaşayan da apaçık belgeden ötürü yaşasın diye olacak işi yaptı. Doğrusu Allah işitir ve bilir.'),
  ('tr.diyanet', 8, 43, 'Allah onları uykunda sana az gösteriyordu. Çok göstermiş olsaydı, yılacak ve bu hususta çekişmeye başlıyacaktınız, fakat Allah sizi kurtardı; çünkü O kalblerde olanı bilir.'),
  ('tr.diyanet', 8, 44, 'Karşılaştığınızda, olacak işi oldurmak için, onları gözlerinize az gösteriyor ve sizi de onların gözünde azaltıyordu. Bütün işler dönüp Allah\'a varır.'),
  ('tr.diyanet', 8, 45, 'Ey inananlar! Bir toplulukla karşılaşırsanız dayanın; başarıya erişebilmeniz için Allah\'ı çok anın.'),
  ('tr.diyanet', 8, 46, 'Allah\'a ve Peygamberine itaat edin; çekişmeyin, yoksa korkar başarısızlığa düşersiniz ve kuvvetiniz gider. Sabredin, doğrusu Allah sabredenlerle beraberdir.'),
  ('tr.diyanet', 8, 47, 'Yurtlarından böbürlenerek, insanlara gösteriş yaparak çıkan ve Allah yolundan men edenler gibi olmayın. Allah onların işlediklerini her yönüyle bilendir.'),
  ('tr.diyanet', 8, 48, 'Şeytan onlara işlediklerini güzel gösterdi ve "Bugün insanlardan sizi yenecek kimse yoktur; doğrusu ben de size yardımcıyım" dedi. İki ordu karşılaşınca da, geri dönüp, "Benim sizinle ilgim yok; doğrusu sizin görmediğinizi ben görüyorum ve şüphesiz Allah\'tan korkuyorum, Allah\'ın azabı şiddetlidir" dedi.'),
  ('tr.diyanet', 8, 49, 'İkiyüzlüler ve kalblerinde hastalık bulunanlar "Müslümanları dinleri aldattı" diyorlardı; oysa, kim Allah\'a güvenirse bilmelidir ki Allah güçlüdür, hakimdir.'),
  ('tr.diyanet', 8, 50, 'Melekler, inkar edenlerin yüzlerine ve sırtlarına vurarak, "Yakıcı azabı tadın, bu, kendi ellerinizle yaptığınızın karşılığıdır" diyerek canlarını alırken bir görseydin! Yoksa Allah kullara asla zulmetmez.'),
  ('tr.diyanet', 8, 51, 'Melekler, inkar edenlerin yüzlerine ve sırtlarına vurarak, "Yakıcı azabı tadın, bu, kendi ellerinizle yaptığınızın karşılığıdır" diyerek canlarını alırken bir görseydin! Yoksa Allah kullara asla zulmetmez.'),
  ('tr.diyanet', 8, 52, 'Firavun taifesi ve onlardan öncekilerin gidişi gibi, Allah\'ın ayetlerini yalanladılar da Allah onları günahlarından ötürü yoketti. Allah kuvvetlidir, cezalandırması şiddetlidir.'),
  ('tr.diyanet', 8, 53, 'Bu, bir topluluk iyi gidişini değiştirmedikçe Allah\'ın da verdiği nimeti değiştirmeyeceğinden ve Allah\'ın işiten, bilen olmasındandır.'),
  ('tr.diyanet', 8, 54, 'Firavun taifesi ve onlardan öncekilerin gidişi gibi, Rablerinin ayetlerini yalanladılar da onları günahlarından ötürü yok ettik. Firavun taifesini suda boğduk, hepsi zalimlerdi.'),
  ('tr.diyanet', 8, 55, 'Allah katında yeryüzünde yaşayanların en kötüsü, inkar edenlerdir. Onlar artık inanmazlar.'),
  ('tr.diyanet', 8, 56, 'Anlaşma yaptığın kimseler, sonucundan sakınmayarak anlaşmalarını her defasında bozarlar. Savaşta onları yakalarsan, arkalarındakilere ibret olacak şekilde, darmadağın et.'),
  ('tr.diyanet', 8, 57, 'Anlaşma yaptığın kimseler, sonucundan sakınmayarak anlaşmalarını her defasında bozarlar. Savaşta onları yakalarsan, arkalarındakilere ibret olacak şekilde, darmadağın et.'),
  ('tr.diyanet', 8, 58, 'Eğer bir topluluğun anlaşmaya hıyanet etmesinden korkarsan, sen de onlara karşı anlaşmayı bozarak aynı şekilde davran. Doğrusu Allah hainleri sevmez.'),
  ('tr.diyanet', 8, 59, 'İnkar edenler, asla öne geçtiklerini sanmasınlar, çünkü onlar bizi aciz bırakamıyacaklardır.'),
  ('tr.diyanet', 8, 60, 'Ey inananlar! Onlara karşı gücünüzün yettiği kadar Allah\'ın düşmanı ve sizin düşmanlarınızı ve bunların dışında Allah\'ın bilip sizin bilmediklerinizi yıldırmak üzere kuvvet ve savaş atları hazırlayın. Allah yolunda sarfettiğiniz her şey size haksızlık yapılmadan, tamamen ödenecektir.'),
  ('tr.diyanet', 8, 61, 'Eğer onlar barışa yanaşırlarsa, sen de yanaş ve Allah\'a güven. O, şüphesiz işitir ve bilir.'),
  ('tr.diyanet', 8, 62, 'Seni aldatmak isterlerse, bil ki şüphesiz Allah sana kafidir. Seni ve inananları yardımıyla destekleyen, kalblerini uzlaştıran O\'dur. Eğer yeryüzünde olan her şeyi sarfetsen bile, sen onların kalblerini uzlaştıramazdın, ama Allah onları uzlaştırdı. Doğrusu O Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 8, 63, 'Seni aldatmak isterlerse, bil ki şüphesiz Allah sana kafidir. Seni ve inananları yardımıyla destekleyen, kalblerini uzlaştıran O\'dur. Eğer yeryüzünde olan her şeyi sarfetsen bile, sen onların kalblerini uzlaştıramazdın, ama Allah onları uzlaştırdı. Doğrusu O Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 8, 64, 'Allah\'ın yardımı sana ve sana uyan müminlere yeter.'),
  ('tr.diyanet', 8, 65, 'Müminleri savaş için coştur. Sizin sabırlı yirmi kişiniz onlardan ikiyüz kişiyi yener. Sizin yüz kişiniz, inkar edenlerden bin kişiyi yener; çünkü onlar anlayışsız bir güruhtur. Şimdi Allah yükünüzü hafifletti, zira içinizde zaaf bulunduğunu biliyordu. Sizin sabırlı yüz kişiniz onlardan ikiyüz kişiyi yener; sizin bin kişiniz, Allah\'ın izniyle, ikibin kişiyi yener. Allah sabredenlerle beraberdir.'),
  ('tr.diyanet', 8, 66, 'Müminleri savaş için coştur. Sizin sabırlı yirmi kişiniz onlardan ikiyüz kişiyi yener. Sizin yüz kişiniz, inkar edenlerden bin kişiyi yener; çünkü onlar anlayışsız bir güruhtur. Şimdi Allah yükünüzü hafifletti, zira içinizde zaaf bulunduğunu biliyordu. Sizin sabırlı yüz kişiniz onlardan ikiyüz kişiyi yener; sizin bin kişiniz, Allah\'ın izniyle, ikibin kişiyi yener. Allah sabredenlerle beraberdir.'),
  ('tr.diyanet', 8, 67, 'Yeryüzünde savaşırken, düşmanı yere sermeden esir almak hiçbir peygambere yaraşmaz. Geçici dünya malını istiyorsunuz, oysa Allah ahireti kazanmanızı ister. Allah Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 8, 68, 'Daha önceden Allah\'tan verilmiş bir hüküm olmasaydı, aldıklarınızdan ötürü size büyük bir azab erişirdi.'),
  ('tr.diyanet', 8, 69, 'Elde ettiğiniz ganimetleri temiz ve helal olarak yiyin; Allah\'tan sakının, doğrusu Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 8, 70, 'Elinizde bulunan esirlere, "Allah kalblerinizde bir iyilik bulursa, size sizden alınanın daha hayırlısını verir, sizi bağışlar, Allah bağışlayandır, merhamet edendir" de.'),
  ('tr.diyanet', 8, 71, 'Esirler sana hıyanet etmek isterlerse, bilsinler ki esasen daha önce de Allah\'a hıyanet etmişlerdi, Allah bundan ötürü onları yenmen için sana imkan verdi. Allah Bilen\'dir, Hakim\'dir.'),
  ('tr.diyanet', 8, 72, 'Doğrusu inanıp hicret edenler, Allah yolunda mallarıyla canlarıyla cihat edenler ve muhacirleri barındırıp onlara yardım edenler, işte bunlar birbirinin dostudurlar. İnanıp hicret etmeyenlerle, hicret edene kadar sizin dostluğunuz yoktur. Fakat din uğrunda yardım isterlerse, aranızda anlaşma olmayan topluluktan başkasına karşı onlara yardım etmeniz gerekir. Allah işlediklerinizi görür.'),
  ('tr.diyanet', 8, 73, 'İnkar edenler birbirlerinin dostlarıdır. Eğer siz aranızda dost olmazsanız yeryüzünde kargaşalık, fitne ve büyük bozgun çıkar.'),
  ('tr.diyanet', 8, 74, 'İnanıp hicret eden, Allah yolunda savaşanlar ve muhacirleri barındırıp onlara yardım edenler, işte onlar gerçekten inanmış olanlardır. Onlara mağfiret ve cömertçe verilmiş rızıklar vardır.'),
  ('tr.diyanet', 8, 75, 'Sonra inanıp hicret eden ve sizinle birlikte savaşanlar, işte onlar sizdendir. Birbirinin mirasçısı olan akraba, Allah\'ın Kitap\'ına göre birbirine daha yakındır. Doğrusu Allah her şeyi bilir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 8, 1, 'Mereka menanyakan kepadamu tentang (pembagian) harta rampasan perang. Katakanlah: "Harta rampasan perang kepunyaan Allah dan Rasul, oleh sebab itu bertakwalah kepada Allah dan perbaikilah perhubungan di antara sesamamu; dan taatlah kepada Allah dan Rasul-Nya jika kamu adalah orang-orang yang beriman".'),
  ('id.indonesian', 8, 2, 'Sesungguhnya orang-orang yang beriman ialah mereka yang bila disebut nama Allah gemetarlah hati mereka, dan apabila dibacakan ayat-ayat-Nya bertambahlah iman mereka (karenanya), dan hanya kepada Tuhanlah mereka bertawakkal.'),
  ('id.indonesian', 8, 3, '(yaitu) orang-orang yang mendirikan shalat dan yang menafkahkan sebagian dari rezeki yang Kami berikan kepada mereka.'),
  ('id.indonesian', 8, 4, 'Itulah orang-orang yang beriman dengan sebenar-benarnya. Mereka akan memperoleh beberapa derajat ketinggian di sisi Tuhannya dan ampunan serta rezeki (nikmat) yang mulia.'),
  ('id.indonesian', 8, 5, 'Sebagaimana Tuhanmu menyuruhmu pergi dan rumahmu dengan kebenaran, padahal sesungguhnya sebagian dari orang-orang yang beriman itu tidak menyukainya,'),
  ('id.indonesian', 8, 6, 'mereka membantahmu tentang kebenaran sesudah nyata (bahwa mereka pasti menang), seolah-olah mereka dihalau kepada kematian, sedang mereka melihat (sebab-sebab kematian itu).'),
  ('id.indonesian', 8, 7, 'Dan (ingatlah), ketika Allah menjanjikan kepadamu bahwa salah satu dari dua golongan (yang kamu hadapi) adalah untukmu, sedang kamu menginginkan bahwa yang tidak mempunyai kekekuatan senjatalah yang untukmu, dan Allah menghendaki untuk membenarkan yang benar dengan ayat-ayat-Nya dan memusnahkan orang-orang kafir,'),
  ('id.indonesian', 8, 8, 'agar Allah menetapkan yang hak (Islam) dan membatalkan yang batil (syirik) walaupun orang-orang yang berdosa (musyrik) itu tidak menyukainya.'),
  ('id.indonesian', 8, 9, '(Ingatlah), ketika kamu memohon pertolongan kepada Tuhanmu, lalu diperkenankan-Nya bagimu: "Sesungguhnya Aku akan mendatangkan bala bantuan kepada kamu dengan seribu malaikat yang datang berturut-turut".'),
  ('id.indonesian', 8, 10, 'Dan Allah tidak menjadikannya (mengirim bala bantuan itu), melainkan sebagai kabar gembira dan agar hatimu menjadi tenteram karenanya. Dan kemenangan itu hanyalah dari sisi Allah. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 8, 11, '(Ingatlah), ketika Allah menjadikan kamu mengantuk sebagai suatu penenteraman daripada-Nya, dan Allah menurunkan kepadamu hujan dari langit untuk mensucikan kamu dengan hujan itu dan menghilangkan dari kamu gangguan-gangguan syaitan dan untuk menguatkan hatimu dan mesmperteguh dengannya telapak kaki(mu).'),
  ('id.indonesian', 8, 12, '(Ingatlah), ketika Tuhanmu mewahyukan kepada para malaikat: "Sesungguhnya Aku bersama kamu, maka teguhkan (pendirian) orang-orang yang telah beriman". Kelak akan Aku jatuhkan rasa ketakutan ke dalam hati orang-orang kafir, maka penggallah kepala mereka dan pancunglah tiap-tiap ujung jari mereka.'),
  ('id.indonesian', 8, 13, '(Ketentuan) yang demikian itu adalah karena sesungguhnya mereka menentang Allah dan Rasul-Nya; dan barangsiapa menentang Allah dan Rasul-Nya, maka sesungguhnya Allah amat keras siksaan-Nya.'),
  ('id.indonesian', 8, 14, 'Itulah (hukum dunia yang ditimpakan atasmu), maka rasakanlah hukuman itu. Sesungguhnya bagi orang-orang yang kafir itu ada (lagi) azab neraka.'),
  ('id.indonesian', 8, 15, 'Hai orang-orang yang beriman, apabila kamu bertemu dengan orang-orang yang kafir yang sedang menyerangmu, maka janganlah kamu membelakangi mereka (mundur).'),
  ('id.indonesian', 8, 16, 'Barangsiapa yang membelakangi mereka (mundur) di waktu itu, kecuali berbelok untuk (sisat) perang atau hendak menggabungkan diri dengan pasukan yang lain, maka sesungguhnya orang itu kembali dengan membawa kemurkaan dari Allah, dan tempatnya ialah neraka Jahannam. Dan amat buruklah tempat kembalinya.'),
  ('id.indonesian', 8, 17, 'Maka (yang sebenarnya) bukan kamu yang membunuh mereka, akan tetapi Allahlah yang membunuh mereka, dan bukan kamu yang melempar ketika kamu melempar, tetapi Allah-lah yang melempar. (Allah berbuat demikian untuk membinasakan mereka) dan untuk memberi kemenangan kepada orang-orang mukmin, dengan kemenangan yang baik. Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 8, 18, 'Itulah (karunia Allah yang dilimpahkan kepadamu), dan sesungguhnya Allah melemahkan tipu daya orang-orang yang kafir.'),
  ('id.indonesian', 8, 19, 'Jika kamu (orang-orang musyrikin) mencari keputusan, maka telah datang keputusan kepadamu; dan jika kamu berhenti; maka itulah yang lehih baik bagimu; dan jika kamu kembali, niscaya Kami kembali (pula); dan angkatan perangmu sekali-kali tidak akan dapat menolak dari kamu sesuatu bahayapun, biarpun dia banyak dan sesungguhnya Allah beserta orang-orang yang beriman.'),
  ('id.indonesian', 8, 20, 'Hai orang-orang yang beriman, taatlah kepada Allah dan Rasul-Nya, dan janganlah kamu berpaling dari pada-Nya, sedang kamu mendengar (perintah-perintah-Nya),'),
  ('id.indonesian', 8, 21, 'dan janganlah kamu menjadi seperti orang-orang (munafik) vang berkata "Kami mendengarkan, padahal mereka tidak mendengarkan.'),
  ('id.indonesian', 8, 22, 'Sesungguhnya binatang (makhluk) yang seburuk-buruknya pada sisi Allah ialah; orang-orang yang pekak dan tuli yang tidak mengerti apa-apapun.'),
  ('id.indonesian', 8, 23, 'Kalau sekiranya Allah mengetahui kebaikan ada pada mereka, tentulah Allah menjadikan mereka dapat mendengar. Dan jikalau Allah menjadikan mereka dapat mendengar, niscaya mereka pasti berpaling juga, sedang mereka memalingkan diri (dari apa yang mereka dengar itu).'),
  ('id.indonesian', 8, 24, 'Hai orang-orang yang beriman, penuhilah seruan Allah dan seruan Rasul apabila Rasul menyeru kamu kepada suatu yang memberi kehidupan kepada kamu, ketahuilah bahwa sesungguhnya Allah membatasi antara manusia dan hatinya dan sesungguhnya kepada-Nya-lah kamu akan dikumpulkan.'),
  ('id.indonesian', 8, 25, 'Dan peliharalah dirimu dari pada siksaan yang tidak khusus menimpa orang-orang yang zalim saja di antara kamu. Dan ketahuilah bahwa Allah amat keras siksaan-Nya.'),
  ('id.indonesian', 8, 26, 'Dan ingatlah (hai para muhajirin) ketika kamu masih berjumlah sedikit, lagi tertindas di muka bumi (Mekah), kamu takut orang-orang (Mekah) akan menculik kamu, maka Allah memberi kamu tempat menetap (Madinah) dan dijadikan-Nya kamu kuat dengan pertolongan-Nya dan diberi-Nya kamu rezeki dari yang baik-baik agar kamu bersyukur.'),
  ('id.indonesian', 8, 27, 'Hai orang-orang yang beriman, janganlah kamu mengkhianati Allah dan Rasul (Muhammad) dan (juga) janganlah kamu mengkhianati amanat-amanat yang dipercayakan kepadamu, sedang kamu mengetahui.'),
  ('id.indonesian', 8, 28, 'Dan ketahuilah, bahwa hartamu dan anak-anakmu itu hanyalah sebagai cobaan dan sesungguhnya di sisi Allah-lah pahala yang besar.'),
  ('id.indonesian', 8, 29, 'Hai orang-orang beriman, jika kamu bertakwa kepada Allah, Kami akan memberikan kepadamu Furqaan. Dan kami akan jauhkan dirimu dari kesalahan-kesalahanmu, dan mengampuni (dosa-dosa)mu. Dan Allah mempunyai karunia yang besar.'),
  ('id.indonesian', 8, 30, 'Dan (ingatlah), ketika orang-orang kafir (Quraisy) memikirkan daya upaya terhadapmu untuk menangkap dan memenjarakanmu atau membunuhmu, atau mengusirmu. Mereka memikirkan tipu daya dan Allah menggagalkan tipu daya itu. Dan Allah sebaik-baik Pembalas tipu daya.'),
  ('id.indonesian', 8, 31, 'Dan apabila dibacakan kepada mereka ayat-ayat Kami, mereka berkata: "Sesungguhnya kami telah mendengar (ayat-ayat yang seperti ini), kalau kami menhendaki niscaya kami dapat membacakan yang seperti ini, (Al Quran) ini tidak lain hanyalah dongeng-dongengan orang-orang purbakala".'),
  ('id.indonesian', 8, 32, 'Dan (ingatlah), ketika mereka (orang-orang musyrik) berkata: "Ya Allah, jika betul (Al Quran) ini, dialah yang benar dari sisi Engkau, maka hujanilah kami dengan batu dari langit, atau datangkanlah kepada kami azab yang pedih".'),
  ('id.indonesian', 8, 33, 'Dan Allah sekali-kali tidak akan mengazab mereka, sedang kamu berada di antara mereka. Dan tidaklah (pula) Allah akan mengazab mereka, sedang mereka meminta ampun'),
  ('id.indonesian', 8, 34, 'Kenapa Allah tidak mengazab mereka padahal mereka menghalangi orang untuk (mendatangi) Masjidilharam, dan mereka bukanlah orang-orang yang berhak menguasainya? Orang-orang yang berhak menguasai(nya) hanyalah orang-orang yang bertakwa. tetapi kebanyakan mereka tidak mengetahui.'),
  ('id.indonesian', 8, 35, 'Sembahyang mereka di sekitar Baitullah itu, lain tidak hanyalah siulan dan tepukan tangan. Maka rasakanlah azab disebabkan kekafiranmu itu.'),
  ('id.indonesian', 8, 36, 'Sesungguhnya orang-orang yang kafir menafkahkan harta mereka untuk menghalangi (orang) dari jalan Allah. Mereka akan menafkahkan harta itu, kemudian menjadi sesalan bagi mereka, dan mereka akan dikalahkan. Dan ke dalam Jahannamlah orang-orang yang kafir itu dikumpulkan,'),
  ('id.indonesian', 8, 37, 'supaya Allah memisahkan (golongan) yang buruk dari yang baik dan menjadikan (golongan) yang buruk itu sebagiannya di atas sebagian yang lain, lalu kesemuanya ditumpukkan-Nya, dan dimasukkan-Nya ke dalam neraka Jahannam. Mereka itulah orang-orang yang merugi.'),
  ('id.indonesian', 8, 38, 'Katakanlah kepada orang-orang yang kafir itu: "Jika mereka berhenti (dari kekafirannya), niscaya Allah akan mengampuni mereka tentang dosa-dosa mereka yang sudah lalu; dan jika mereka kembali lagi sesungguhnya akan berlaku (kepada mereka) sunnah (Allah tenhadap) orang-orang dahulu".'),
  ('id.indonesian', 8, 39, 'Dan perangilah mereka, supaya jangan ada fitnah dan supaya agama itu semata-mata untuk Allah. Jika mereka berhenti (dari kekafiran), maka sesungguhnya Allah Maha Melihat apa yang mereka kerjakan.'),
  ('id.indonesian', 8, 40, 'Dan jika mereka berpaling, maka ketahuilah bahwasanya Allah Pelindungmu. Dia adalah sebaik-baik Pelindung dan sebaik-baik Penolong.'),
  ('id.indonesian', 8, 41, 'Ketahuilah, sesungguhnya apa saja yang dapat kamu peroleh sebagai rampasan perang, maka sesungguhnya seperlima untuk Allah, Rasul, kerabat Rasul, anak-anak yatim, orang-orang miskin dan ibnussabil, jika kamu beriman kepada Allah dan kepada apa yang kami turunkan kepada hamba Kami (Muhammad) di hari Furqaan, yaitu di hari bertemunya dua pasukan. Dan Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 8, 42, '(Yaitu di hari) ketika kamu berada di pinggir lembah yang dekat dan mereka berada di pinggir lembah yang jauh sedang kafilah itu berada di bawah kamu. Sekiranya kamu mengadakan persetujuan (untuk menentukan hari pertempuran), pastilah kamu tidak sependapat dalam menentukan hari pertempuran itu, akan tetapi (Allah mempertemukan dua pasukan itu) agar Dia melakukan suatu urusan yang mesti dilaksanakan, yaitu agar orang yang binasa itu binasanya dengan keterangan yang nyata dan agar orang yang hidup itu hidupnya dengan keterangan yang nyata (pula). Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui,'),
  ('id.indonesian', 8, 43, '(yaitu) ketika Allah menampakkan mereka kepadamu di dalam mimpimu (berjumlah) sedikit. Dan sekiranya Allah memperlihatkan mereka kepada kamu (berjumlah) banyak tentu saja kamu menjadi gentar dan tentu saja kamu akan berbantah-bantahan dalam urusan itu, akan tetapi Allah telah menyelamatkan kamu. Sesungguhnya Allah Maha Mengetahui segala isi hati.'),
  ('id.indonesian', 8, 44, 'Dan ketika Allah menampakkan mereka kepada kamu sekalian, ketika kamu berjumpa dengan mereka berjumlah sedikit pada penglihatan matamu dan kamu ditampakkan-Nya berjumlah sedikit pada penglihatan mata mereka, karena Allah hendak melakukan suatu urusan yang mesti dilaksanakan. Dan hanyalah kepada Allahlah dikembalikan segala urusan.'),
  ('id.indonesian', 8, 45, 'Hai orang-orang yang beriman. apabila kamu memerangi pasukan (musuh), maka berteguh hatilah kamu dan sebutlah (nama) Allah sebanyak-banyaknya agar kamu beruntung.'),
  ('id.indonesian', 8, 46, 'Dan taatlah kepada Allah dan Rasul-Nya dan janganlah kamu berbantah-bantahan, yang menyebabkan kamu menjadi gentar dan hilang kekuatanmu dan bersabarlah. Sesungguhnya Allah beserta orang-orang yang sabar.'),
  ('id.indonesian', 8, 47, 'Dan janganlah kamu menjadi seperti orang-orang yang keluar dari kampungnya dengan rasa angkuh dan dengan maksud riya\' kepada manusia serta menghalangi (orang) dari jalan Allah. Dan (ilmu) Allah meliputi apa yang mereka kerjakan.'),
  ('id.indonesian', 8, 48, 'Dan ketika syaitan menjadikan mereka memandang baik pekerjaan mereka dan mengatakan: "Tidak ada seorang manusiapun yang dapat menang terhadapmu pada hari ini, dan sesungguhnya saya ini adalah pelindungmu". Maka tatkala kedua pasukan itu telah dapat saling lihat melihat (berhadapan), syaitan itu balik ke belakang seraya berkata: "Sesungguhnya saya berlepas diri daripada kamu, sesungguhnya saya dapat melihat apa yang kamu sekalian tidak dapat melihat; sesungguhnya saya takut kepada Allah". Dan Allah sangat keras siksa-Nya.'),
  ('id.indonesian', 8, 49, '(Ingatlah), ketika orang-orang munafik dan orang-orang yang ada penyakit di dalam hatinya berkata: "Mereka itu (orang-orang mukmin) ditipu oleh agamanya". (Allah berfirman): "Barangsiapa yang bertawakkal kepada Allah, maka sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana".'),
  ('id.indonesian', 8, 50, 'Kalau kamu melihat ketika para malaikat mencabut jiwa orang-orang yang kafir seraya memukul muka dan belakang mereka (dan berkata): "Rasakanlah olehmu siksa neraka yang membakar", (tentulah kamu akan merasa ngeri).'),
  ('id.indonesian', 8, 51, 'Demikian itu disebabkan oleh perbuatan tanganmu sendiri. Sesungguhnya Allah sekali-kali tidak menganiaya hamba-Nya,'),
  ('id.indonesian', 8, 52, '(keadaan mereka) serupa dengan keadaan Fir\'aun dan pengikut-pengikutnya serta orang-orang yang sebelumnya. Mereka mengingkari ayat-ayat Allah, maka Allah menyiksa mereka disebabkan dosa-dosanya. Sesungguhnya Allah Maha Kuat lagi amat keras siksaan-Nya.'),
  ('id.indonesian', 8, 53, '(Siksaan) yang demikian itu adalah karena sesungguhnya Allah sekali-kali tidak akan meubah sesuatu nikmat yang telah dianugerahkan-Nya kepada suatu kaum, hingga kaum itu meubah apa-apa yang ada pada diri mereka sendiri, dan sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 8, 54, '(keadaan mereka) serupa dengan keadaan Fir\'aun dan pengikut-pengikutnya serta orang-orang yang sebelumnya. Mereka mendustakan ayat-ayat Tuhannya maka Kami membinasakan mereka disebabkan dosa-dosanya dan Kami tenggelamkan Fir\'aun dan pengikut-pengikutnya; dan kesemuanya adalah orang-orang yang zalim.'),
  ('id.indonesian', 8, 55, 'Sesungguhnya binatang (makhluk) yang paling buruk di sisi Allah ialah orang-orang yang kafir, karena mereka itu tidak beriman.'),
  ('id.indonesian', 8, 56, '(Yaitu) orang-orang yang kamu telah mengambil perjanjian dari mereka, sesudah itu mereka mengkhianati janjinya pada setiap kalinya, dan mereka tidak takut (akibat-akibatnya).'),
  ('id.indonesian', 8, 57, 'Jika kamu menemui mereka dalam peperangan, maka cerai beraikanlah orang-orang yang di belakang mereka dengan (menumpas) mereka, supaya mereka mengambil pelajaran.'),
  ('id.indonesian', 8, 58, 'Dan jika kamu khawatir akan (terjadinya) pengkhianatan dari suatu golongan, maka kembalikanlah perjanjian itu kepada mereka dengan cara yang jujur. Sesungguhnya Allah tidak menyukai orang-orang yang berkhianat.'),
  ('id.indonesian', 8, 59, 'Dan janganlah orang-orang yang kafir itu mengira, bahwa mereka akan dapat lolos (dari kekuasaan Allah). Sesungguhnya mereka tidak dapat melemahkan (Allah).'),
  ('id.indonesian', 8, 60, 'Dan siapkanlah untuk menghadapi mereka kekuatan apa saja yang kamu sanggupi dan dari kuda-kuda yang ditambat untuk berperang (yang dengan persiapan itu) kamu menggentarkan musuh Allah dan musuhmu dan orang orang selain mereka yang kamu tidak mengetahuinya; sedang Allah mengetahuinya. Apa saja yang kamu nafkahkan pada jalan Allah niscaya akan dibalasi dengan cukup kepadamu dan kamu tidak akan dianiaya (dirugikan).'),
  ('id.indonesian', 8, 61, 'Dan jika mereka condong kepada perdamaian, maka condonglah kepadanya dan bertawakkallah kepada Allah. Sesungguhnya Dialah Yang Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 8, 62, 'Dan jika mereka bermaksud menipumu, maka sesungguhnya cukuplah Allah (menjadi pelindungmu). Dialah yang memperkuatmu dengan pertolongan-Nya dan dengan para mukmin,'),
  ('id.indonesian', 8, 63, 'dan Yang mempersatukan hati mereka (orang-orang yang beriman). Walaupun kamu membelanjakan semua (kekayaan) yang berada di bumi, niscaya kamu tidak dapat mempersatukan hati mereka, akan tetapi Allah telah mempersatukan hati mereka. Sesungguhnya Dia Maha Gagah lagi Maha Bijaksana.'),
  ('id.indonesian', 8, 64, 'Hai Nabi, cukuplah Allah (menjadi Pelindung) bagimu dan bagi orang-orang mukmin yang mengikutimu.'),
  ('id.indonesian', 8, 65, 'Hai Nabi, kobarkanlah semangat para mukmin untuk berperang. Jika ada dua puluh orang yang sabar diantaramu, niscaya mereka akan dapat mengalahkan dua ratus orang musuh. Dan jika ada seratus orang yang sabar diantaramu, niscaya mereka akan dapat mengalahkan seribu dari pada orang kafir, disebabkan orang-orang kafir itu kaum yang tidak mengerti.'),
  ('id.indonesian', 8, 66, 'Sekarang Allah telah meringankan kepadamu dan dia telah mengetahui bahwa padamu ada kelemahan. Maka jika ada diantaramu seratus orang yang sabar, niscaya mereka akan dapat mengalahkan dua ratus orang kafir; dan jika diantaramu ada seribu orang (yang sabar), niscaya mereka akan dapat mengalahkan dua ribu orang, dengan seizin Allah. Dan Allah beserta orang-orang yang sabar.'),
  ('id.indonesian', 8, 67, 'Tidak patut, bagi seorang Nabi mempunyai tawanan sebelum ia dapat melumpuhkan musuhnya di muka bumi. Kamu menghendaki harta benda duniawiyah sedangkan Allah menghendaki (pahala) akhirat (untukmu). Dan Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 8, 68, 'Kalau sekiranya tidak ada ketetapan yang telah terdahulu dari Allah, niscaya kamu ditimpa siksaan yang besar karena tebusan yang kamu ambil.'),
  ('id.indonesian', 8, 69, 'Maka makanlah dari sebagian rampasan perang yang telah kamu ambil itu, sebagai makanan yang halal lagi baik, dan bertakwalah kepada Allah; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 8, 70, 'Hai Nabi, katakanlah kepada tawanan-tawanan yang ada di tanganmu: "Jika Allah mengetahui ada kebaikan dalam hatimu, niscaya Dia akan memberikan kepadamu yang lebih baik dari apa yang telah diambil daripadamu dan Dia akan mengampuni kamu". Dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 8, 71, 'Akan tetapi jika mereka (tawanan-tawanan itu) bermaksud hendak berkhianat kepadamu, maka sesungguhnya mereka telah berkhianat kepada Allah sebelum ini, lalu Allah menjadikan(mu) berkuasa terhadap mereka. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 8, 72, 'Sesungguhnya orang-orang yang beriman dan berhijrah serta berjihad dengan harta dan jiwanya pada jalan Allah dan orang-orang yang memberikan tempat kediaman dan pertoIongan (kepada orang-orang muhajirin), mereka itu satu sama lain lindung-melindungi. Dan (terhadap) orang-orang yang beriman, tetapi belum berhijrah, maka tidak ada kewajiban sedikitpun atasmu melindungi mereka, sebelum mereka berhijrah. (Akan tetapi) jika mereka meminta pertolongan kepadamu dalam (urusan pembelaan) agama, maka kamu wajib memberikan pertolongan kecuali terhadap kaum yang telah ada perjanjian antara kamu dengan mereka. Dan Allah Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 8, 73, 'Adapun orang-orang yang kafir, sebagian mereka menjadi pelindung bagi sebagian yang lain. Jika kamu (hai para muslimin) tidak melaksanakan apa yang telah diperintahkan Allah itu, niscaya akan terjadi kekacauan di muka bumi dan kerusakan yang besar.'),
  ('id.indonesian', 8, 74, 'Dan orang-orang yang beriman dan berhijrah serta berjihad pada jalan Allah, dan orang-orang yang memberi tempat kediaman dan memberi pertolongan (kepada orang-orang muhajirin), mereka itulah orang-orang yang benar-benar beriman. Mereka memperoleh ampunan dan rezeki (nikmat) yang mulia.'),
  ('id.indonesian', 8, 75, 'Dan orang-orang yang beriman sesudah itu kemudian berhijrah serta berjihad bersamamu maka orang-orang itu termasuk golonganmu (juga). Orang-orang yang mempunyai hubungan kerabat itu sebagiannya lebih berhak terhadap sesamanya (daripada yang bukan kerabat) di dalam kitab Allah. Sesungguhnya Allah Maha Mengetahui segala sesuatu.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 9, 1, '[This is a declaration of] disassociation, from Allah and His Messenger, to those with whom you had made a treaty among the polytheists.'),
  ('en.sahih', 9, 2, 'So travel freely, [O disbelievers], throughout the land [during] four months but know that you cannot cause failure to Allah and that Allah will disgrace the disbelievers.'),
  ('en.sahih', 9, 3, 'And [it is] an announcement from Allah and His Messenger to the people on the day of the greater pilgrimage that Allah is disassociated from the disbelievers, and [so is] His Messenger. So if you repent, that is best for you; but if you turn away - then know that you will not cause failure to Allah. And give tidings to those who disbelieve of a painful punishment.'),
  ('en.sahih', 9, 4, 'Excepted are those with whom you made a treaty among the polytheists and then they have not been deficient toward you in anything or supported anyone against you; so complete for them their treaty until their term [has ended]. Indeed, Allah loves the righteous [who fear Him].'),
  ('en.sahih', 9, 5, 'And when the sacred months have passed, then kill the polytheists wherever you find them and capture them and besiege them and sit in wait for them at every place of ambush. But if they should repent, establish prayer, and give zakah, let them [go] on their way. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 9, 6, 'And if any one of the polytheists seeks your protection, then grant him protection so that he may hear the words of Allah. Then deliver him to his place of safety. That is because they are a people who do not know.'),
  ('en.sahih', 9, 7, 'How can there be for the polytheists a treaty in the sight of Allah and with His Messenger, except for those with whom you made a treaty at al-Masjid al-Haram? So as long as they are upright toward you, be upright toward them. Indeed, Allah loves the righteous [who fear Him].'),
  ('en.sahih', 9, 8, 'How [can there be a treaty] while, if they gain dominance over you, they do not observe concerning you any pact of kinship or covenant of protection? They satisfy you with their mouths, but their hearts refuse [compliance], and most of them are defiantly disobedient.'),
  ('en.sahih', 9, 9, 'They have exchanged the signs of Allah for a small price and averted [people] from His way. Indeed, it was evil that they were doing.'),
  ('en.sahih', 9, 10, 'They do not observe toward a believer any pact of kinship or covenant of protection. And it is they who are the transgressors.'),
  ('en.sahih', 9, 11, 'But if they repent, establish prayer, and give zakah, then they are your brothers in religion; and We detail the verses for a people who know.'),
  ('en.sahih', 9, 12, 'And if they break their oaths after their treaty and defame your religion, then fight the leaders of disbelief, for indeed, there are no oaths [sacred] to them; [fight them that] they might cease.'),
  ('en.sahih', 9, 13, 'Would you not fight a people who broke their oaths and determined to expel the Messenger, and they had begun [the attack upon] you the first time? Do you fear them? But Allah has more right that you should fear Him, if you are [truly] believers.'),
  ('en.sahih', 9, 14, 'Fight them; Allah will punish them by your hands and will disgrace them and give you victory over them and satisfy the breasts of a believing people'),
  ('en.sahih', 9, 15, 'And remove the fury in the believers\' hearts. And Allah turns in forgiveness to whom He wills; and Allah is Knowing and Wise.'),
  ('en.sahih', 9, 16, 'Do you think that you will be left [as you are] while Allah has not yet made evident those among you who strive [for His cause] and do not take other than Allah, His Messenger and the believers as intimates? And Allah is Acquainted with what you do.'),
  ('en.sahih', 9, 17, 'It is not for the polytheists to maintain the mosques of Allah [while] witnessing against themselves with disbelief. [For] those, their deeds have become worthless, and in the Fire they will abide eternally.'),
  ('en.sahih', 9, 18, 'The mosques of Allah are only to be maintained by those who believe in Allah and the Last Day and establish prayer and give zakah and do not fear except Allah, for it is expected that those will be of the [rightly] guided.'),
  ('en.sahih', 9, 19, 'Have you made the providing of water for the pilgrim and the maintenance of al-Masjid al-Haram equal to [the deeds of] one who believes in Allah and the Last Day and strives in the cause of Allah? They are not equal in the sight of Allah. And Allah does not guide the wrongdoing people.'),
  ('en.sahih', 9, 20, 'The ones who have believed, emigrated and striven in the cause of Allah with their wealth and their lives are greater in rank in the sight of Allah. And it is those who are the attainers [of success].'),
  ('en.sahih', 9, 21, 'Their Lord gives them good tidings of mercy from Him and approval and of gardens for them wherein is enduring pleasure.'),
  ('en.sahih', 9, 22, '[They will be] abiding therein forever. Indeed, Allah has with Him a great reward.'),
  ('en.sahih', 9, 23, 'O you who have believed, do not take your fathers or your brothers as allies if they have preferred disbelief over belief. And whoever does so among you - then it is those who are the wrongdoers.'),
  ('en.sahih', 9, 24, 'Say, [O Muhammad], "If your fathers, your sons, your brothers, your wives, your relatives, wealth which you have obtained, commerce wherein you fear decline, and dwellings with which you are pleased are more beloved to you than Allah and His Messenger and jihad in His cause, then wait until Allah executes His command. And Allah does not guide the defiantly disobedient people."'),
  ('en.sahih', 9, 25, 'Allah has already given you victory in many regions and [even] on the day of Hunayn, when your great number pleased you, but it did not avail you at all, and the earth was confining for you with its vastness; then you turned back, fleeing.'),
  ('en.sahih', 9, 26, 'Then Allah sent down His tranquillity upon His Messenger and upon the believers and sent down soldiers angels whom you did not see and punished those who disbelieved. And that is the recompense of the disbelievers.'),
  ('en.sahih', 9, 27, 'Then Allah will accept repentance after that for whom He wills; and Allah is Forgiving and Merciful.'),
  ('en.sahih', 9, 28, 'O you who have believed, indeed the polytheists are unclean, so let them not approach al-Masjid al-Haram after this, their [final] year. And if you fear privation, Allah will enrich you from His bounty if He wills. Indeed, Allah is Knowing and Wise.'),
  ('en.sahih', 9, 29, 'Fight those who do not believe in Allah or in the Last Day and who do not consider unlawful what Allah and His Messenger have made unlawful and who do not adopt the religion of truth from those who were given the Scripture - [fight] until they give the jizyah willingly while they are humbled.'),
  ('en.sahih', 9, 30, 'The Jews say, "Ezra is the son of Allah "; and the Christians say, "The Messiah is the son of Allah." That is their statement from their mouths; they imitate the saying of those who disbelieved [before them]. May Allah destroy them; how are they deluded?'),
  ('en.sahih', 9, 31, 'They have taken their scholars and monks as lords besides Allah, and [also] the Messiah, the son of Mary. And they were not commanded except to worship one God; there is no deity except Him. Exalted is He above whatever they associate with Him.'),
  ('en.sahih', 9, 32, 'They want to extinguish the light of Allah with their mouths, but Allah refuses except to perfect His light, although the disbelievers dislike it.'),
  ('en.sahih', 9, 33, 'It is He who has sent His Messenger with guidance and the religion of truth to manifest it over all religion, although they who associate others with Allah dislike it.'),
  ('en.sahih', 9, 34, 'O you who have believed, indeed many of the scholars and the monks devour the wealth of people unjustly and avert [them] from the way of Allah. And those who hoard gold and silver and spend it not in the way of Allah - give them tidings of a painful punishment.'),
  ('en.sahih', 9, 35, 'The Day when it will be heated in the fire of Hell and seared therewith will be their foreheads, their flanks, and their backs, [it will be said], "This is what you hoarded for yourselves, so taste what you used to hoard."'),
  ('en.sahih', 9, 36, 'Indeed, the number of months with Allah is twelve [lunar] months in the register of Allah [from] the day He created the heavens and the earth; of these, four are sacred. That is the correct religion, so do not wrong yourselves during them. And fight against the disbelievers collectively as they fight against you collectively. And know that Allah is with the righteous [who fear Him].'),
  ('en.sahih', 9, 37, 'Indeed, the postponing [of restriction within sacred months] is an increase in disbelief by which those who have disbelieved are led [further] astray. They make it lawful one year and unlawful another year to correspond to the number made unlawful by Allah and [thus] make lawful what Allah has made unlawful. Made pleasing to them is the evil of their deeds; and Allah does not guide the disbelieving people.'),
  ('en.sahih', 9, 38, 'O you who have believed, what is [the matter] with you that, when you are told to go forth in the cause of Allah, you adhere heavily to the earth? Are you satisfied with the life of this world rather than the Hereafter? But what is the enjoyment of worldly life compared to the Hereafter except a [very] little.'),
  ('en.sahih', 9, 39, 'If you do not go forth, He will punish you with a painful punishment and will replace you with another people, and you will not harm Him at all. And Allah is over all things competent.'),
  ('en.sahih', 9, 40, 'If you do not aid the Prophet - Allah has already aided him when those who disbelieved had driven him out [of Makkah] as one of two, when they were in the cave and he said to his companion, "Do not grieve; indeed Allah is with us." And Allah sent down his tranquillity upon him and supported him with angels you did not see and made the word of those who disbelieved the lowest, while the word of Allah - that is the highest. And Allah is Exalted in Might and Wise.'),
  ('en.sahih', 9, 41, 'Go forth, whether light or heavy, and strive with your wealth and your lives in the cause of Allah. That is better for you, if you only knew.'),
  ('en.sahih', 9, 42, 'Had it been an easy gain and a moderate trip, the hypocrites would have followed you, but distant to them was the journey. And they will swear by Allah, "If we were able, we would have gone forth with you," destroying themselves [through false oaths], and Allah knows that indeed they are liars.'),
  ('en.sahih', 9, 43, 'May Allah pardon you, [O Muhammad]; why did you give them permission [to remain behind]? [You should not have] until it was evident to you who were truthful and you knew [who were] the liars.'),
  ('en.sahih', 9, 44, 'Those who believe in Allah and the Last Day would not ask permission of you to be excused from striving with their wealth and their lives. And Allah is Knowing of those who fear Him.'),
  ('en.sahih', 9, 45, 'Only those would ask permission of you who do not believe in Allah and the Last Day and whose hearts have doubted, and they, in their doubt, are hesitating.'),
  ('en.sahih', 9, 46, 'And if they had intended to go forth, they would have prepared for it [some] preparation. But Allah disliked their being sent, so He kept them back, and they were told, "Remain [behind] with those who remain."'),
  ('en.sahih', 9, 47, 'Had they gone forth with you, they would not have increased you except in confusion, and they would have been active among you, seeking [to cause] you fitnah. And among you are avid listeners to them. And Allah is Knowing of the wrongdoers.'),
  ('en.sahih', 9, 48, 'They had already desired dissension before and had upset matters for you until the truth came and the ordinance of Allah appeared, while they were averse.'),
  ('en.sahih', 9, 49, 'And among them is he who says, "Permit me [to remain at home] and do not put me to trial." Unquestionably, into trial they have fallen. And indeed, Hell will encompass the disbelievers.'),
  ('en.sahih', 9, 50, 'If good befalls you, it distresses them; but if disaster strikes you, they say, "We took our matter [in hand] before," and turn away while they are rejoicing.'),
  ('en.sahih', 9, 51, 'Say, "Never will we be struck except by what Allah has decreed for us; He is our protector." And upon Allah let the believers rely.'),
  ('en.sahih', 9, 52, 'Say, "Do you await for us except one of the two best things while we await for you that Allah will afflict you with punishment from Himself or at our hands? So wait; indeed we, along with you, are waiting."'),
  ('en.sahih', 9, 53, 'Say, "Spend willingly or unwillingly; never will it be accepted from you. Indeed, you have been a defiantly disobedient people."'),
  ('en.sahih', 9, 54, 'And what prevents their expenditures from being accepted from them but that they have disbelieved in Allah and in His Messenger and that they come not to prayer except while they are lazy and that they do not spend except while they are unwilling.'),
  ('en.sahih', 9, 55, 'So let not their wealth or their children impress you. Allah only intends to punish them through them in worldly life and that their souls should depart [at death] while they are disbelievers.'),
  ('en.sahih', 9, 56, 'And they swear by Allah that they are from among you while they are not from among you; but they are a people who are afraid.'),
  ('en.sahih', 9, 57, 'If they could find a refuge or some caves or any place to enter [and hide], they would turn to it while they run heedlessly.'),
  ('en.sahih', 9, 58, 'And among them are some who criticize you concerning the [distribution of] charities. If they are given from them, they approve; but if they are not given from them, at once they become angry.'),
  ('en.sahih', 9, 59, 'If only they had been satisfied with what Allah and His Messenger gave them and said, "Sufficient for us is Allah; Allah will give us of His bounty, and [so will] His Messenger; indeed, we are desirous toward Allah," [it would have been better for them].'),
  ('en.sahih', 9, 60, 'Zakah expenditures are only for the poor and for the needy and for those employed to collect [zakah] and for bringing hearts together [for Islam] and for freeing captives [or slaves] and for those in debt and for the cause of Allah and for the [stranded] traveler - an obligation [imposed] by Allah. And Allah is Knowing and Wise.'),
  ('en.sahih', 9, 61, 'And among them are those who abuse the Prophet and say, "He is an ear." Say, "[It is] an ear of goodness for you that believes in Allah and believes the believers and [is] a mercy to those who believe among you." And those who abuse the Messenger of Allah - for them is a painful punishment.'),
  ('en.sahih', 9, 62, 'They swear by Allah to you [Muslims] to satisfy you. But Allah and His Messenger are more worthy for them to satisfy, if they should be believers.'),
  ('en.sahih', 9, 63, 'Do they not know that whoever opposes Allah and His Messenger - that for him is the fire of Hell, wherein he will abide eternally? That is the great disgrace.'),
  ('en.sahih', 9, 64, 'They hypocrites are apprehensive lest a surah be revealed about them, informing them of what is in their hearts. Say, "Mock [as you wish]; indeed, Allah will expose that which you fear."'),
  ('en.sahih', 9, 65, 'And if you ask them, they will surely say, "We were only conversing and playing." Say, "Is it Allah and His verses and His Messenger that you were mocking?"'),
  ('en.sahih', 9, 66, 'Make no excuse; you have disbelieved after your belief. If We pardon one faction of you - We will punish another faction because they were criminals.'),
  ('en.sahih', 9, 67, 'The hypocrite men and hypocrite women are of one another. They enjoin what is wrong and forbid what is right and close their hands. They have forgotten Allah, so He has forgotten them [accordingly]. Indeed, the hypocrites - it is they who are the defiantly disobedient.'),
  ('en.sahih', 9, 68, 'Allah has promised the hypocrite men and hypocrite women and the disbelievers the fire of Hell, wherein they will abide eternally. It is sufficient for them. And Allah has cursed them, and for them is an enduring punishment.'),
  ('en.sahih', 9, 69, '[You disbelievers are] like those before you; they were stronger than you in power and more abundant in wealth and children. They enjoyed their portion [of worldly enjoyment], and you have enjoyed your portion as those before you enjoyed their portion, and you have engaged [in vanities] like that in which they engaged. [It is] those whose deeds have become worthless in this world and in the Hereafter, and it is they who are the losers.'),
  ('en.sahih', 9, 70, 'Has there not reached them the news of those before them - the people of Noah and [the tribes of] \'Aad and Thamud and the people of Abraham and the companions of Madyan and the towns overturned? Their messengers came to them with clear proofs. And Allah would never have wronged them, but they were wronging themselves.'),
  ('en.sahih', 9, 71, 'The believing men and believing women are allies of one another. They enjoin what is right and forbid what is wrong and establish prayer and give zakah and obey Allah and His Messenger. Those - Allah will have mercy upon them. Indeed, Allah is Exalted in Might and Wise.'),
  ('en.sahih', 9, 72, 'Allah has promised the believing men and believing women gardens beneath which rivers flow, wherein they abide eternally, and pleasant dwellings in gardens of perpetual residence; but approval from Allah is greater. It is that which is the great attainment.'),
  ('en.sahih', 9, 73, 'O Prophet, fight against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.'),
  ('en.sahih', 9, 74, 'They swear by Allah that they did not say [anything against the Prophet] while they had said the word of disbelief and disbelieved after their [pretense of] Islam and planned that which they were not to attain. And they were not resentful except [for the fact] that Allah and His Messenger had enriched them of His bounty. So if they repent, it is better for them; but if they turn away, Allah will punish them with a painful punishment in this world and the Hereafter. And there will not be for them on earth any protector or helper.'),
  ('en.sahih', 9, 75, 'And among them are those who made a covenant with Allah, [saying], "If He should give us from His bounty, we will surely spend in charity, and we will surely be among the righteous."'),
  ('en.sahih', 9, 76, 'But when he gave them from His bounty, they were stingy with it and turned away while they refused.'),
  ('en.sahih', 9, 77, 'So He penalized them with hypocrisy in their hearts until the Day they will meet Him - because they failed Allah in what they promised Him and because they [habitually] used to lie.'),
  ('en.sahih', 9, 78, 'Did they not know that Allah knows their secrets and their private conversations and that Allah is the Knower of the unseen?'),
  ('en.sahih', 9, 79, 'Those who criticize the contributors among the believers concerning [their] charities and [criticize] the ones who find nothing [to spend] except their effort, so they ridicule them - Allah will ridicule them, and they will have a painful punishment.'),
  ('en.sahih', 9, 80, 'Ask forgiveness for them, [O Muhammad], or do not ask forgiveness for them. If you should ask forgiveness for them seventy times - never will Allah forgive them. That is because they disbelieved in Allah and His Messenger, and Allah does not guide the defiantly disobedient people.'),
  ('en.sahih', 9, 81, 'Those who remained behind rejoiced in their staying [at home] after [the departure of] the Messenger of Allah and disliked to strive with their wealth and their lives in the cause of Allah and said, "Do not go forth in the heat." Say, "The fire of Hell is more intensive in heat" - if they would but understand.'),
  ('en.sahih', 9, 82, 'So let them laugh a little and [then] weep much as recompense for what they used to earn.'),
  ('en.sahih', 9, 83, 'If Allah should return you to a faction of them [after the expedition] and then they ask your permission to go out [to battle], say, "You will not go out with me, ever, and you will never fight with me an enemy. Indeed, you were satisfied with sitting [at home] the first time, so sit [now] with those who stay behind."'),
  ('en.sahih', 9, 84, 'And do not pray [the funeral prayer, O Muhammad], over any of them who has died - ever - or stand at his grave. Indeed, they disbelieved in Allah and His Messenger and died while they were defiantly disobedient.'),
  ('en.sahih', 9, 85, 'And let not their wealth and their children impress you. Allah only intends to punish them through them in this world and that their souls should depart [at death] while they are disbelievers.'),
  ('en.sahih', 9, 86, 'And when a surah was revealed [enjoining them] to believe in Allah and to fight with His Messenger, those of wealth among them asked your permission [to stay back] and said, "Leave us to be with them who sit [at home]."'),
  ('en.sahih', 9, 87, 'They were satisfied to be with those who stay behind, and their hearts were sealed over, so they do not understand.'),
  ('en.sahih', 9, 88, 'But the Messenger and those who believed with him fought with their wealth and their lives. Those will have [all that is] good, and it is those who are the successful.'),
  ('en.sahih', 9, 89, 'Allah has prepared for them gardens beneath which rivers flow, wherein they will abide eternally. That is the great attainment.'),
  ('en.sahih', 9, 90, 'And those with excuses among the bedouins came to be permitted [to remain], and they who had lied to Allah and His Messenger sat [at home]. There will strike those who disbelieved among them a painful punishment.'),
  ('en.sahih', 9, 91, 'There is not upon the weak or upon the ill or upon those who do not find anything to spend any discomfort when they are sincere to Allah and His Messenger. There is not upon the doers of good any cause [for blame]. And Allah is Forgiving and Merciful.'),
  ('en.sahih', 9, 92, 'Nor [is there blame] upon those who, when they came to you that you might give them mounts, you said, "I can find nothing for you to ride upon." They turned back while their eyes overflowed with tears out of grief that they could not find something to spend [for the cause of Allah].'),
  ('en.sahih', 9, 93, 'The cause [for blame] is only upon those who ask permission of you while they are rich. They are satisfied to be with those who stay behind, and Allah has sealed over their hearts, so they do not know.'),
  ('en.sahih', 9, 94, 'They will make excuses to you when you have returned to them. Say, "Make no excuse - never will we believe you. Allah has already informed us of your news. And Allah will observe your deeds, and [so will] His Messenger; then you will be taken back to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."'),
  ('en.sahih', 9, 95, 'They will swear by Allah to you when you return to them that you would leave them alone. So leave them alone; indeed they are evil; and their refuge is Hell as recompense for what they had been earning.'),
  ('en.sahih', 9, 96, 'They swear to you so that you might be satisfied with them. But if you should be satisfied with them - indeed, Allah is not satisfied with a defiantly disobedient people.'),
  ('en.sahih', 9, 97, 'The bedouins are stronger in disbelief and hypocrisy and more likely not to know the limits of what [laws] Allah has revealed to His Messenger. And Allah is Knowing and Wise.'),
  ('en.sahih', 9, 98, 'And among the bedouins are some who consider what they spend as a loss and await for you turns of misfortune. Upon them will be a misfortune of evil. And Allah is Hearing and Knowing.'),
  ('en.sahih', 9, 99, 'But among the bedouins are some who believe in Allah and the Last Day and consider what they spend as means of nearness to Allah and of [obtaining] invocations of the Messenger. Unquestionably, it is a means of nearness for them. Allah will admit them to His mercy. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 9, 100, 'And the first forerunners [in the faith] among the Muhajireen and the Ansar and those who followed them with good conduct - Allah is pleased with them and they are pleased with Him, and He has prepared for them gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.'),
  ('en.sahih', 9, 101, 'And among those around you of the bedouins are hypocrites, and [also] from the people of Madinah. They have become accustomed to hypocrisy. You, [O Muhammad], do not know them, [but] We know them. We will punish them twice [in this world]; then they will be returned to a great punishment.'),
  ('en.sahih', 9, 102, 'And [there are] others who have acknowledged their sins. They had mixed a righteous deed with another that was bad. Perhaps Allah will turn to them in forgiveness. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 9, 103, 'Take, [O, Muhammad], from their wealth a charity by which you purify them and cause them increase, and invoke [Allah \'s blessings] upon them. Indeed, your invocations are reassurance for them. And Allah is Hearing and Knowing.'),
  ('en.sahih', 9, 104, 'Do they not know that it is Allah who accepts repentance from His servants and receives charities and that it is Allah who is the Accepting of repentance, the Merciful?'),
  ('en.sahih', 9, 105, 'And say, "Do [as you will], for Allah will see your deeds, and [so, will] His Messenger and the believers. And you will be returned to the Knower of the unseen and the witnessed, and He will inform you of what you used to do."'),
  ('en.sahih', 9, 106, 'And [there are] others deferred until the command of Allah - whether He will punish them or whether He will forgive them. And Allah is Knowing and Wise.'),
  ('en.sahih', 9, 107, 'And [there are] those [hypocrites] who took for themselves a mosque for causing harm and disbelief and division among the believers and as a station for whoever had warred against Allah and His Messenger before. And they will surely swear, "We intended only the best." And Allah testifies that indeed they are liars.'),
  ('en.sahih', 9, 108, 'Do not stand [for prayer] within it - ever. A mosque founded on righteousness from the first day is more worthy for you to stand in. Within it are men who love to purify themselves; and Allah loves those who purify themselves.'),
  ('en.sahih', 9, 109, 'Then is one who laid the foundation of his building on righteousness [with fear] from Allah and [seeking] His approval better or one who laid the foundation of his building on the edge of a bank about to collapse, so it collapsed with him into the fire of Hell? And Allah does not guide the wrongdoing people.'),
  ('en.sahih', 9, 110, 'Their building which they built will not cease to be a [cause of] skepticism in their hearts until their hearts are stopped. And Allah is Knowing and Wise.'),
  ('en.sahih', 9, 111, 'Indeed, Allah has purchased from the believers their lives and their properties [in exchange] for that they will have Paradise. They fight in the cause of Allah, so they kill and are killed. [It is] a true promise [binding] upon Him in the Torah and the Gospel and the Qur\'an. And who is truer to his covenant than Allah? So rejoice in your transaction which you have contracted. And it is that which is the great attainment.'),
  ('en.sahih', 9, 112, '[Such believers are] the repentant, the worshippers, the praisers [of Allah], the travelers [for His cause], those who bow and prostrate [in prayer], those who enjoin what is right and forbid what is wrong, and those who observe the limits [set by] Allah. And give good tidings to the believers.'),
  ('en.sahih', 9, 113, 'It is not for the Prophet and those who have believed to ask forgiveness for the polytheists, even if they were relatives, after it has become clear to them that they are companions of Hellfire.'),
  ('en.sahih', 9, 114, 'And the request of forgiveness of Abraham for his father was only because of a promise he had made to him. But when it became apparent to Abraham that his father was an enemy to Allah, he disassociated himself from him. Indeed was Abraham compassionate and patient.'),
  ('en.sahih', 9, 115, 'And Allah would not let a people stray after He has guided them until He makes clear to them what they should avoid. Indeed, Allah is Knowing of all things.'),
  ('en.sahih', 9, 116, 'Indeed, to Allah belongs the dominion of the heavens and the earth; He gives life and causes death. And you have not besides Allah any protector or any helper.'),
  ('en.sahih', 9, 117, 'Allah has already forgiven the Prophet and the Muhajireen and the Ansar who followed him in the hour of difficulty after the hearts of a party of them had almost inclined [to doubt], and then He forgave them. Indeed, He was to them Kind and Merciful.'),
  ('en.sahih', 9, 118, 'And [He also forgave] the three who were left behind [and regretted their error] to the point that the earth closed in on them in spite of its vastness and their souls confined them and they were certain that there is no refuge from Allah except in Him. Then He turned to them so they could repent. Indeed, Allah is the Accepting of repentance, the Merciful.'),
  ('en.sahih', 9, 119, 'O you who have believed, fear Allah and be with those who are true.'),
  ('en.sahih', 9, 120, 'It was not [proper] for the people of Madinah and those surrounding them of the bedouins that they remain behind after [the departure of] the Messenger of Allah or that they prefer themselves over his self. That is because they are not afflicted by thirst or fatigue or hunger in the cause of Allah, nor do they tread on any ground that enrages the disbelievers, nor do they inflict upon an enemy any infliction but that is registered for them as a righteous deed. Indeed, Allah does not allow to be lost the reward of the doers of good.'),
  ('en.sahih', 9, 121, 'Nor do they spend an expenditure, small or large, or cross a valley but that it is registered for them that Allah may reward them for the best of what they were doing.'),
  ('en.sahih', 9, 122, 'And it is not for the believers to go forth [to battle] all at once. For there should separate from every division of them a group [remaining] to obtain understanding in the religion and warn their people when they return to them that they might be cautious.'),
  ('en.sahih', 9, 123, 'O you who have believed, fight those adjacent to you of the disbelievers and let them find in you harshness. And know that Allah is with the righteous.'),
  ('en.sahih', 9, 124, 'And whenever a surah is revealed, there are among the hypocrites those who say, "Which of you has this increased faith?" As for those who believed, it has increased them in faith, while they are rejoicing.'),
  ('en.sahih', 9, 125, 'But as for those in whose hearts is disease, it has [only] increased them in evil [in addition] to their evil. And they will have died while they are disbelievers.'),
  ('en.sahih', 9, 126, 'Do they not see that they are tried every year once or twice but then they do not repent nor do they remember?'),
  ('en.sahih', 9, 127, 'And whenever a surah is revealed, they look at each other, [saying], "Does anyone see you?" and then they dismiss themselves. Allah has dismissed their hearts because they are a people who do not understand.'),
  ('en.sahih', 9, 128, 'There has certainly come to you a Messenger from among yourselves. Grievous to him is what you suffer; [he is] concerned over you and to the believers is kind and merciful.'),
  ('en.sahih', 9, 129, 'But if they turn away, [O Muhammad], say, "Sufficient for me is Allah; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 9, 1, 'সম্পর্কচ্ছেদ করা হল আল্লাহ ও তাঁর রসূলের পক্ষ থেকে সেই মুশরিকদের সাথে, যাদের সাথে তোমরা চুক্তিবদ্ধ হয়েছিলে।'),
  ('bn.bengali', 9, 2, 'অতঃপর তোমরা পরিভ্রমণ কর এ দেশে চার মাসকাল। আর জেনে রেখো, তোমরা আল্লাহকে পরাভূত করতে পারবে না, আর নিশ্চয়ই আল্লাহ কাফেরদিগকে লাঞ্ছিত করে থাকেন।'),
  ('bn.bengali', 9, 3, 'আর মহান হজ্বের দিনে আল্লাহ ও তাঁর রসূলের পক্ষ থেকে লোকদের প্রতি ঘোষণা করে দেয়া হচ্ছে যে, আল্লাহ মুশরেকদের থেকে দায়িত্ব মুক্ত এবং তাঁর রসূলও। অবশ্য যদি তোমরা তওবা কর, তবে তা, তোমাদের জন্যেও কল্যাণকর, আর যদি মুখ ফেরাও, তবে জেনে রেখো, আল্লাহকে তোমরা পরাভূত করতে পারবে না। আর কাফেরদেরকে মর্মান্তিক শাস্তির সুসংবাদ দাও।'),
  ('bn.bengali', 9, 4, 'তবে যে মুশরিকদের সাথে তোমরা চুক্তি বদ্ধ, অতপরঃ যারা তোমাদের ব্যাপারে কোন ত্রুটি করেনি এবং তোমাদের বিরুদ্ধে কাউকে সাহায্যও করেনি, তাদের সাথে কৃত চুক্তিকে তাদের দেয়া মেয়াদ পর্যন্ত পূরণ কর। অবশ্যই আল্লাহ সাবধানীদের পছন্দ করেন।'),
  ('bn.bengali', 9, 5, 'অতঃপর নিষিদ্ধ মাস অতিবাহিত হলে মুশরিকদের হত্যা কর যেখানে তাদের পাও, তাদের বন্দী কর এবং অবরোধ কর। আর প্রত্যেক ঘাঁটিতে তাদের সন্ধানে ওঁৎ পেতে বসে থাক। কিন্তু যদি তারা তওবা করে, নামায কায়েম করে, যাকাত আদায় করে, তবে তাদের পথ ছেড়ে দাও। নিশ্চয় আল্লাহ অতি ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 9, 6, 'আর মুশরিকদের কেউ যদি তোমার কাছে আশ্রয় প্রার্থনা করে, তবে তাকে আশ্রয় দেবে, যাতে সে আল্লাহর কালাম শুনতে পায়, অতঃপর তাকে তার নিরাপদ স্থানে পৌছে দেবে। এটি এজন্যে যে এরা জ্ঞান রাখে না।'),
  ('bn.bengali', 9, 7, 'মুশরিকদের চুক্তি আল্লাহর নিকট ও তাঁর রসূলের নিকট কিরূপে বলবৎ থাকবে। তবে যাদের সাথে তোমরা চুক্তি সম্পাদন করেছ মসজিদুল-হারামের নিকট। অতএব, যে পর্যন্ত তারা তোমাদের জন্যে সরল থাকে, তোমরাও তাদের জন্য সরল থাক। নিঃসন্দেহের আল্লাহ সাবধানীদের পছন্দ করেন।'),
  ('bn.bengali', 9, 8, 'কিরূপে? তারা তোমাদের উপর জয়ী হলে তোমাদের আত্নীয়তার ও অঙ্গীকারের কোন মর্যাদা দেবে না। তারা মুখে তোমাদের সন্তুষ্ট করে, কিন্তু তাদের অন্তরসমূহ তা অস্বীকার করে, আর তাদের অধিকাংশ প্রতিশ্রুতি ভঙ্গকারী।'),
  ('bn.bengali', 9, 9, 'তারা আল্লাহর আয়াত সমূহ নগন্য মুল্যে বিক্রয় করে, অতঃপর লোকদের নিবৃত রাখে তাঁর পথ থেকে, তারা যা করে চলছে, তা অতি নিকৃষ্ট।'),
  ('bn.bengali', 9, 10, 'তারা মর্যাদা দেয় না কোন মুসলমানের ক্ষেত্রে আত্নীয়তার, আর না অঙ্গীকারের। আর তারাই সীমালংঘনকারী।'),
  ('bn.bengali', 9, 11, 'অবশ্য তারা যদি তওবা করে, নামায কায়েম করে আর যাকাত আদায় করে, তবে তারা তোমাদের দ্বীনী ভাই। আর আমি বিধানসমূহে জ্ঞানী লোকদের জন্যে সর্বস্তরে র্বণনা করে থাকি।'),
  ('bn.bengali', 9, 12, 'আর যদি ভঙ্গ করে তারা তাদের শপথ প্রতিশ্রুতির পর এবং বিদ্রুপ করে তোমাদের দ্বীন সম্পর্কে, তবে কুফর প্রধানদের সাথে যুদ্ধ কর। কারণ, এদের কেন শপথ নেই যাতে তারা ফিরে আসে।'),
  ('bn.bengali', 9, 13, 'তোমরা কি সেই দলের সাথে যুদ্ধ করবে না; যারা ভঙ্গ করেছে নিজেদের শপথ এবং সঙ্কল্প নিয়েছে রসূলকে বহিস্কারের? আর এরাই প্রথম তোমাদের সাথে বিবাদের সূত্রপাত করেছে। তোমরা কি তাদের ভয় কর? অথচ তোমাদের ভয়ের অধিকতর যোগ্য হলেন আল্লাহ, যদি তোমরা মুমিন হও।'),
  ('bn.bengali', 9, 14, 'যুদ্ধ কর ওদের সাথে, আল্লাহ তোমাদের হস্তে তাদের শাস্তি দেবেন। তাদের লাঞ্ছিত করবেন, তাদের বিরুদ্ধে তোমাদের জয়ী করবেন এবং মুসলমানদের অন্তরসমূহ শান্ত করবেন।'),
  ('bn.bengali', 9, 15, 'এবং তাদের মনের ক্ষোভ দূর করবেন। আর আল্লাহ যার প্রতি ইচ্ছা ক্ষমাশীল হবে, আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 9, 16, 'তোমরা কি মনে কর যে, তোমাদের ছেড়ে দেয়া হবে এমনি, যতক্ষণ না আল্লাহ জেনে নেবেন তোমাদের কে যুদ্ধ করেছে এবং কে আল্লাহ, তাঁর রসূল ও মুসলমানদের ব্যতীত অন্য কাউকে অন্তরঙ্গ বন্ধুরূপে গ্রহণ করা থেকে বিরত রয়েছে। আর তোমরা যা কর সে বিষয়ে আল্লাহ সবিশেষ অবহিত।'),
  ('bn.bengali', 9, 17, 'মুশরিকরা যোগ্যতা রাখে না আল্লাহর মসজিদ আবাদ করার, যখন তারা নিজেরাই নিজেদের কুফরীর স্বীকৃতি দিচ্ছে। এদের আমল বরবাদ হবে এবং এরা আগুনে স্থায়ীভাবে বসবাস করবে।'),
  ('bn.bengali', 9, 18, 'নিঃসন্দেহে তারাই আল্লাহর মসজিদ আবাদ করবে যারা ঈমান এনেছে আল্লাহর প্রতি ও শেষ দিনের প্রতি এবং কায়েম করেছে নামায ও আদায় করে যাকাত; আল্লাহ ব্যতীত আর কাউকে ভয় করে না। অতএব, আশা করা যায়, তারা হেদায়েত প্রাপ্তদের অন্তর্ভূক্ত হবে।'),
  ('bn.bengali', 9, 19, 'তোমরা কি হাজীদের পানি সরবরাহ ও মসজিদুল-হারাম আবাদকরণকে সেই লোকের সমান মনে কর, যে ঈমান রাখে আল্লাহ ও শেষ দিনের প্রতি এবং যুদ্ধ করেছে আল্লাহর রাহে, এরা আল্লাহর দৃষ্টিতে সমান নয়, আর আল্লাহ জালেম লোকদের হেদায়েত করেন না।'),
  ('bn.bengali', 9, 20, 'যারা ঈমান এনেছে, দেশ ত্যাগ করেছে এবং আল্লাহর রাহে নিজেদের জান ও মাল দিয়ে জেহাদ করেছে, তাদের বড় মর্যাদা রয়েছে আল্লাহর কাছে আর তারাই সফলকাম।'),
  ('bn.bengali', 9, 21, 'তাদের সুসংবাদ দিচ্ছেন তাদের পরওয়ারদেগার স্বীয় দয়া ও সন্তোষের এবং জান্নাতের, সেখানে আছে তাদের জন্য স্থায়ী শান্তি।'),
  ('bn.bengali', 9, 22, 'তথায় তারা থাকবে চিরদিন। নিঃসন্দেহে আল্লাহর কাছে আছে মহাপুরস্কার।'),
  ('bn.bengali', 9, 23, 'হে ঈমানদারগণ! তোমরা স্বীয় পিতা ও ভাইদের অভিভাবকরূপে গ্রহণ করো না, যদি তারা ঈমান অপেক্ষা কুফরকে ভালবাসে। আর তোমাদের যারা তাদের অভিভাবকরূপে গ্রহণ করে তারা সীমালংঘনকারী।'),
  ('bn.bengali', 9, 24, 'বল, তোমাদের নিকট যদি তোমাদের পিতা তোমাদের সন্তান, তোমাদের ভাই তোমাদের পত্নী, তোমাদের গোত্র তোমাদের অর্জিত ধন-সম্পদ, তোমাদের ব্যবসা যা বন্ধ হয়ে যাওয়ার ভয় কর এবং তোমাদের বাসস্থান-যাকে তোমরা পছন্দ কর-আল্লাহ, তাঁর রসূল ও তাঁর রাহে জেহাদ করা থেকে অধিক প্রিয় হয়, তবে অপেক্ষা কর, আল্লাহর বিধান আসা পর্যন্ত, আর আল্লাহ ফাসেক সম্প্রদায়কে হেদায়েত করেন না।'),
  ('bn.bengali', 9, 25, 'আল্লাহ তোমাদের সাহায্য করেছেন অনেক ক্ষেত্রে এবং হোনাইনের দিনে, যখন তোমাদের সংখ্যধিক্য তোমাদের প্রফুল্ল করেছিল, কিন্তু তা তোমাদের কোন কাজে আসেনি এবং পৃথিবী প্রশস্ত হওয়া সত্তেও তোমাদের জন্য সংকুচিত হয়েছিল। অতঃপর পৃষ্ঠ প্রদর্শন করে পলায়ন করেছিলে।'),
  ('bn.bengali', 9, 26, 'তারপর আল্লাহ নাযিল করেন নিজের পক্ষ থেকে সান্ত্বনা, তাঁর রসূল ও মুমিনদের প্রতি এবং অবতীর্ণ করেন এমন সেনাবাহিনী যাদের তোমরা দেখতে পাওনি। আর শাস্তি প্রদান করেন কাফেরদের এবং এটি হল কাফেরদের কর্মফল।'),
  ('bn.bengali', 9, 27, 'এরপর আল্লাহ যাদের প্রতি ইচ্ছা তওবার তওফীক দেবেন, আর আল্লাহ অতীব ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 9, 28, 'হে ঈমানদারগণ! মুশরিকরা তো অপবিত্র। সুতরাং এ বছরের পর তারা যেন মসজিদুল-হারামের নিকট না আসে। আর যদি তোমরা দারিদ্রে?480; আশংকা কর, তবে আল্লাহ চাইলে নিজ করুনায় ভবিষ্যতে তোমাদের অভাবমুক্ত করে দেবেন। নিঃসন্দেহে আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 9, 29, 'তোমরা যুদ্ধ কর আহলে-কিতাবের ঐ লোকদের সাথে, যারা আল্লাহ ও রোজ হাশরে ঈমান রাখে না, আল্লাহ ও তাঁর রসূল যা হারাম করে দিয়েছেন তা হারাম করে না এবং গ্রহণ করে না সত্য ধর্ম, যতক্ষণ না করজোড়ে তারা জিযিয়া প্রদান করে।'),
  ('bn.bengali', 9, 30, 'ইহুদীরা বলে ওযাইর আল্লাহর পুত্র এবং নাসারারা বলে ‘মসীহ আল্লাহর পুত্র’। এ হচ্ছে তাদের মুখের কথা। এরা পূর্ববর্তী কাফেরদের মত কথা বলে। আল্লাহ এদের ধ্বংস করুন, এরা কোন উল্টা পথে চলে যাচ্ছে।'),
  ('bn.bengali', 9, 31, 'তারা তাদের পন্ডিত ও সংসার-বিরাগীদিগকে তাদের পালনকর্তারূপে গ্রহণ করেছে আল্লাহ ব্যতীত এবং মরিয়মের পুত্রকেও। অথচ তারা আদিষ্ট ছিল একমাত্র মাবুদের এবাদতের জন্য। তিনি ছাড়া কোন মাবুদ নেই, তারা তাঁর শরীক সাব্যস্ত করে, তার থেকে তিনি পবিত্র।'),
  ('bn.bengali', 9, 32, 'তারা তাদের মুখের ফুৎকারে আল্লাহর নূরকে নির্বাপিত করতে চায়। কিন্তু আল্লাহ অবশ্যই তাঁর নূরের পূর্ণতা বিধান করবেন, যদিও কাফেররা তা অপ্রীতিকর মনে করে।'),
  ('bn.bengali', 9, 33, 'তিনিই প্রেরণ করেছেন আপন রসূলকে হেদায়েত ও সত্য দ্বীন সহকারে, যেন এ দ্বীনকে অপরাপর দ্বীনের উপর জয়যুক্ত করেন, যদিও মুশরিকরা তা অপ্রীতিকর মনে করে।'),
  ('bn.bengali', 9, 34, 'হে ঈমানদারগণ! পন্ডিত ও সংসারবিরাগীদের অনেকে লোকদের মালামাল অন্যায়ভাবে ভোগ করে চলছে এবং আল্লাহর পথ থেকে লোকদের নিবৃত রাখছে। আর যারা স্বর্ণ ও রূপা জমা করে রাখে এবং তা ব্যয় করে না আল্লাহর পথে, তাদের কঠোর আযাবের সুসংবাদ শুনিয়ে দিন।'),
  ('bn.bengali', 9, 35, 'সে দিন জাহান্নামের আগুনে তা উত্তপ্ত করা হবে এবং তার দ্বারা তাদের ললাট, পার্শ্ব ও পৃষ্ঠদেশকে দগ্ধ করা হবে (সেদিন বলা হবে), এগুলো যা তোমরা নিজেদের জন্যে জমা রেখেছিলে, সুতরাং এক্ষণে আস্বাদ গ্রহণ কর জমা করে রাখার।'),
  ('bn.bengali', 9, 36, 'নিশ্চয় আল্লাহর বিধান ও গননায় মাস বারটি, আসমানসমূহ ও পৃথিবী সৃষ্টির দিন থেকে। তন্মধ্যে চারটি সম্মানিত। এটিই সুপ্রতিষ্ঠিত বিধান; সুতরাং এর মধ্যে তোমরা নিজেদের প্রতি অত্যাচার করো না। আর মুশরিকদের সাথে তোমরা যুদ্ধ কর সমবেতভাবে, যেমন তারাও তোমাদের সাথে যুদ্ধ করে যাচ্ছে সমবেতভাবে। আর মনে রেখো, আল্লাহ মুত্তাকীনদের সাথে রয়েছেন।'),
  ('bn.bengali', 9, 37, 'এই মাস পিছিয়ে দেয়ার কাজ কেবল কুফরীর মাত্রা বৃদ্ধি করে, যার ফলে কাফেরগণ গোমরাহীতে পতিত হয়। এরা হালাল করে নেয় একে এক বছর এবং হারাম করে নেয় অন্য বছর, যাতে তারা গণনা পূর্ণ করে নেয় আল্লাহর নিষিদ্ধ মাসগুলোর। অতঃপর হালাল করে নেয় আল্লাহর হারামকৃত মাসগুলোকে। তাদের মন্দকাজগুলো তাদের জন্যে শোভনীয় করে দেয়া হল। আর আল্লাহ কাফের সম্প্রদায়কে হেদায়েত করেন না।'),
  ('bn.bengali', 9, 38, 'হে ঈমানদারগণ, তোমাদের কি হল, যখন আল্লাহর পথে বের হবার জন্যে তোমাদের বলা হয়, তখন মাটি জড়িয়ে ধর, তোমরা কি আখেরাতের পরিবর্তে দুনিয়ার জীবনে পরিতুষ্ট হয়ে গেলে? অথচ আখেরাতের তুলনায় দুনিয়ার জীবনের উপকরণ অতি অল্প।'),
  ('bn.bengali', 9, 39, 'যদি বের না হও, তবে আল্লাহ তোমাদের মর্মন্তুদ আযাব দেবেন এবং অপর জাতিকে তোমাদের স্থলাভিষিক্ত করবেন। তোমরা তাঁর কোন ক্ষতি করতে পারবে না, আর আল্লাহ সর্ববিষয়ে শক্তিমান।'),
  ('bn.bengali', 9, 40, 'যদি তোমরা তাকে (রসূলকে) সাহায্য না কর, তবে মনে রেখো, আল্লাহ তার সাহায্য করেছিলেন, যখন তাকে কাফেররা বহিষ্কার করেছিল, তিনি ছিলেন দু’জনের একজন, যখন তারা গুহার মধ্যে ছিলেন। তখন তিনি আপন সঙ্গীকে বললেন বিষন্ন হয়ো না, আল্লাহ আমাদের সাথে আছেন। অতঃপর আল্লাহ তার প্রতি স্বীয় সান্তনা নাযিল করলেন এবং তাঁর সাহায্যে এমন বাহিনী পাঠালেন, যা তোমরা দেখনি। বস্তুতঃ আল্লাহ কাফেরদের মাথা নীচু করে দিলেন আর আল্লাহর কথাই সদা সমুন্নত এবং আল্লাহ পরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 9, 41, 'তোমরা বের হয়ে পড় স্বল্প বা প্রচুর সরঞ্জামের সাথে এবং জেহাদ কর আল্লাহর পথে নিজেদের মাল ও জান দিয়ে, এটি তোমাদের জন্যে অতি উত্তম, যদি তোমরা বুঝতে পার।'),
  ('bn.bengali', 9, 42, 'যদি আশু লাভের সম্ভাবনা থাকতো এবং যাত্রাপথও সংক্ষিপ্ত হতো, তবে তারা অবশ্যই আপনার সহযাত্রী হতো, কিন্তু তাদের নিকট যাত্রাপথ সুদীর্ঘ মনে হল। আর তারা এমনই শপথ করে বলবে, আমাদের সাধ্য থাকলে অবশ্যই তোমাদের সাথে বের হতাম, এরা নিজেরাই নিজেদের বিনষ্ট করছে, আর আল্লাহ জানেন যে, এরা মিথ্যাবাদী।'),
  ('bn.bengali', 9, 43, 'আল্লাহ আপনাকে ক্ষমা করুন, আপনি কেন তাদের অব্যাহতি দিলেন, যে পর্যন্ত না আপনার কাছে পরিষ্কার হয়ে যেত সত্যবাদীরা এবং জেনে নিতেন মিথ্যাবাদীদের।'),
  ('bn.bengali', 9, 44, 'আল্লাহ ও রোজ কেয়ামতের প্রতি যাদের ঈমান রয়েছে তারা মাল ও জান দ্বারা জেহাদ করা থেকে আপনার কাছে অব্যাহতি কামনা করবে না, আর আল্লাহ সাবধানীদের ভাল জানেন।'),
  ('bn.bengali', 9, 45, 'নিঃসন্দেহে তারাই আপনার কাছে অব্যাহতি চায়, যারা আল্লাহ ও রোজ কেয়ামতে ঈমান রাখে না এবং তাদের অন্তর সন্দেহগ্রস্ত হয়ে পড়েছে, সুতরাং সন্দেহের আবর্তে তারা ঘুরপাক খেয়ে চলেছে।'),
  ('bn.bengali', 9, 46, 'আর যদি তারা বের হবার সংকল্প নিত, তবে অবশ্যই কিছু সরঞ্জাম প্রস্তুত করতো। কিন্তু তাদের উত্থান আল্লাহর পছন্দ নয়, তাই তাদের নিবৃত রাখলেন এবং আদেশ হল বসা লোকদের সাথে তোমরা বসে থাক।'),
  ('bn.bengali', 9, 47, 'যদি তোমাদের সাথে তারা বের হত, তবে তোমাদের অনিষ্ট ছাড়া আর কিছু বৃদ্ধি করতো না, আর অশ্ব ছুটাতো তোমাদের মধ্যে বিভেদ সৃষ্টির উদ্দেশে। আর তোমাদের মাঝে রয়েছে তাদের গুপ্তচর। বস্তুতঃ আল্লাহ যালিমদের ভালভাবেই জানেন।'),
  ('bn.bengali', 9, 48, 'তারা পূর্বে থেকেই বিভেদ সৃষ্টির সুযোগ সন্ধানে ছিল এবং আপনার কার্যসমূহ উল্টা-পাল্টা করে দিচ্ছিল। শেষ পর্যন্ত সত্য প্রতিশ্রুতি এসে গেল এবং জয়ী হল আল্লাহর হুকুম, যে অবস্থায় তারা মন্দবোধ করল।'),
  ('bn.bengali', 9, 49, 'আর তাদের কেউ বলে, আমাকে অব্যাহতি দিন এবং পথভ্রষ্ট করবেন না। শোনে রাখ, তারা তো পূর্ব থেকেই পথভ্রষ্ট এবং নিঃসন্দেহে জাহান্নাম এই কাফেরদের পরিবেষ্টন করে রয়েছে।'),
  ('bn.bengali', 9, 50, 'আপনার কোন কল্যাণ হলে তারা মন্দবোধ করে এবং কোন বিপদ উপস্থিত হলে তারা বলে, আমরা পূর্ব থেকেই নিজেদের কাজ সামলে নিয়েছি এবং ফিরে যায় উল্লসিত মনে।'),
  ('bn.bengali', 9, 51, 'আপনি বলুন, আমাদের কাছে কিছুই পৌঁছবে না, কিন্তু যা আল্লাহ আমাদের জন্য রেখেছেন; তিনি আমাদের কার্যনির্বাহক। আল্লাহর উপরই মুমিনদের ভরসা করা উচিত।'),
  ('bn.bengali', 9, 52, 'আপনি বলুন, তোমরা তো তোমাদের জন্যে দুটি কল্যাণের একটি প্রত্যাশা কর; আর আমরা প্রত্যাশায় আছি তোমাদের জন্যে যে, আল্লাহ তোমাদের আযাব দান করুন নিজের পক্ষ থেকে অথবা আমাদের হস্তে। সুতরাং তোমরা অপেক্ষা কর, আমরাও তোমাদের সাথে অপেক্ষমাণ।'),
  ('bn.bengali', 9, 53, 'আপনি বলুন, তোমরা ইচ্ছায় অর্থ ব্যয় কর বা অনিচ্ছায়, তোমাদের থেকে তা কখনো কবুল হবে না, তোমরা নাফরমানের দল।'),
  ('bn.bengali', 9, 54, 'তাদের অর্থ ব্যয় কবুল না হওয়ার এছাড়া আর কোন কারণ নেই যে, তারা আল্লাহ ও তাঁর রসূলের প্রতি অবিশ্বাসী, তারা নামাযে আসে অলসতার সাথে ব্যয় করে সঙ্কুচিত মনে।'),
  ('bn.bengali', 9, 55, 'সুতরাং তাদের ধন-সম্পদ ও সন্তান-সন্ততি যেন আপনাকে বিস্মিত না করে। আল্লাহর ইচ্ছা হল এগুলো দ্বারা দুনিয়ার জীবনে তাদের আযাবে নিপতিত রাখা এবং প্রাণবিয়োগ হওয়া কুফরী অবস্থায়।'),
  ('bn.bengali', 9, 56, 'তারা আল্লাহর নামে হলফ করে বলে যে, তারা তোমাদেরই অন্তর্ভুক্ত, অথচ তারা তোমাদের অন্তর্ভূক্ত নয়, অবশ্য তারা তোমাদের ভয় করে।'),
  ('bn.bengali', 9, 57, 'তারা কোন আশ্রয়স্থল, কোন গুহা বা মাথা গোঁজার ঠাই পেলে সেদিকে পলায়ন করবে দ্রুতগতিতে।'),
  ('bn.bengali', 9, 58, 'তাদের মধ্যে এমন লোকও রয়েছে যারা সদকা বন্টনে আপনাকে দোষারূপ করে। এর থেকে কিছু পেলে সন্তুষ্ট হয় এবং না পেলে বিক্ষুব্ধ হয়।'),
  ('bn.bengali', 9, 59, 'কতই না ভাল হত, যদি তারা সন্তুষ্ট হত আল্লাহ ও তার রসূলের উপর এবং বলত, আল্লাহই আমাদের জন্যে যথেষ্ট, আল্লাহ আমাদের দেবেন নিজ করুণায় এবং তাঁর রসূলও, আমরা শুধু আল্লাহকেই কামনা করি।'),
  ('bn.bengali', 9, 60, 'যাকাত হল কেবল ফকির, মিসকীন, যাকাত আদায় কারী ও যাদের চিত্ত আকর্ষণ প্রয়োজন তাদে হক এবং তা দাস-মুক্তির জন্যে-ঋণ গ্রস্তদের জন্য, আল্লাহর পথে জেহাদকারীদের জন্যে এবং মুসাফিরদের জন্যে, এই হল আল্লাহর নির্ধারিত বিধান। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 9, 61, 'আর তাদের মধ্যে কেউ কেউ নবীকে ক্লেশ দেয়, এবং বলে, এ লোকটি তো কানসর্বস্ব। আপনি বলে দিন, কান হলেও তোমাদেরই মঙ্গলের জন্য, আল্লাহর উপর বিশ্বাস রাখে এবং বিশ্বাস রাখে মুসলমানদের কথার উপর। বস্তুতঃ তোমাদের মধ্যে যারা ঈমানদার তাদের জন্য তিনি রহমতবিশেষ। আর যারা আল্লাহর রসূলের প্রতি কুৎসা রটনা করে, তাদের জন্য রয়েছে বেদনাদায়ক আযাব।'),
  ('bn.bengali', 9, 62, 'তোমাদের সামনে আল্লাহর কসম খায় যাতে তোমাদের রাযী করতে পারে। অবশ্য তারা যদি ঈমানদার হয়ে থাকে, তবে আল্লাহকে এবং তাঁর রসূলকে রাযী করা অত্যন্ত জরুরী।'),
  ('bn.bengali', 9, 63, 'তারা কি একথা জেনে নেয়নি যে, আল্লাহর সাথে এবং তাঁর রসূলের সাথে যে মোকাবেলা করে তার জন্যে নির্ধারিত রয়েছে দোযখ; তাতে সব সময় থাকবে। এটিই হল মহা-অপমান।'),
  ('bn.bengali', 9, 64, 'মুনাফেকরা এ ব্যাপারে ভয় করে যে, মুসলমানদের উপর না এমন কোন সূরা নাযিল হয়, যাতে তাদের অন্তরের গোপন বিষয় অবহিত করা হবে। সুতরাং আপনি বলে দিন, ঠাট্টা-বিদ্রপ করতে থাক; আল্লাহ তা অবশ্যই প্রকাশ করবেন যার ব্যাপারে তোমরা ভয় করছ।'),
  ('bn.bengali', 9, 65, 'আর যদি তুমি তাদের কাছে জিজ্ঞেস কর, তবে তারা বলবে, আমরা তো কথার কথা বলছিলাম এবং কৌতুক করছিলাম। আপনি বলুন, তোমরা কি আল্লাহর সাথে, তাঁর হুকুম আহকামের সাথে এবং তাঁর রসূলের সাথে ঠাট্টা করছিলে?'),
  ('bn.bengali', 9, 66, 'ছলনা কর না, তোমরা যে কাফের হয়ে গেছ ঈমান প্রকাশ করার পর। তোমাদের মধ্যে কোন কোন লোককে যদি আমি ক্ষমা করে দেইও, তবে অবশ্য কিছু লোককে আযাবও দেব। কারণ, তারা ছিল গোনাহগার।'),
  ('bn.bengali', 9, 67, 'মুনাফেক নর-নারী সবারই গতিবিধি একরকম; শিখায় মন্দ কথা, ভাল কথা থেকে বারণ করে এবং নিজ মুঠো বন্ধ রাখে। আল্লাহকে ভুলে গেছে তার, কাজেই তিনিও তাদের ভূলে গেছেন নিঃসন্দেহে মুনাফেকরাই নাফরমান।'),
  ('bn.bengali', 9, 68, 'ওয়াদা করেছেন আল্লাহ, মুনাফেক পুরুষ ও মুনাফেক নারীদের এবং কাফেরদের জন্যে দোযখের আগুনের-তাতে পড়ে থাকবে সর্বদা। সেটাই তাদের জন্যে যথেষ্ট। আর আল্লাহ তাদের প্রতি অভিসম্পাত করেছেন এবং তাদের জন্যে রয়েছে স্থায়ী আযাব।'),
  ('bn.bengali', 9, 69, 'যেমন করে তোমাদের পূর্ববর্তী লোকেরা তোমাদের চেয়ে বেশী ছিল শক্তিতে এবং ধন-সম্পদের ও সন্তান-সন্ততির অধিকারীও ছিল বেশী; অতঃপর উপকৃত হয়েছে নিজেদের ভাগের দ্বারা আবার তোমরা ফায়দা উঠিয়েছ তোমাদের ভাগের দ্বারা-যেমন করে তোমাদের পূর্ববর্তীরা ফায়দা উঠিয়েছিল নিজেদের ভাগের দ্বারা। আর তোমরাও বলছ তাদেরই চলন অনুযায়ী। তারা ছিল সে লোক, যাদের আমলসমূহ নিঃশেষিত হয়ে গেছে দুনিয়া ও আখেরাতে। আর তারাই হয়েছে ক্ষতির সম্মুখীন।'),
  ('bn.bengali', 9, 70, 'তাদের সংবাদ কি এদের কানে এসে পৌঁছায়নি, যারা ছিল তাদের পূর্বে; নূহের আ’দের ও সামুদের সম্প্রদায় এবং ইব্রাহীমের সম্প্রদায়ের এবং মাদইয়ানবাসীদের? এবং সেসব জনপদের যেগুলোকে উল্টে দেয়া হয়েছিল? তাদের কাছে এসেছিলেন তাদের নবী পরিষ্কার নির্দেশ নিয়ে। বস্তুতঃ আল্লাহ তো এমন ছিলেন না যে, তাদের উপর জুলুম করতেন, কিন্তু তারা নিজেরাই নিজেদের উপর জুলুম করতো।'),
  ('bn.bengali', 9, 71, 'আর ঈমানদার পুরুষ ও ঈমানদার নারী একে অপরের সহায়ক। তারা ভাল কথার শিক্ষা দেয় এবং মন্দ থেকে বিরত রাখে। নামায প্রতিষ্ঠা করে, যাকাত দেয় এবং আল্লাহ ও তাঁর রসূলের নির্দেশ অনুযায়ী জীবন যাপন করে। এদেরই উপর আল্লাহ তা’আলা দয়া করবেন। নিশ্চয়ই আল্লাহ পরাক্রমশীল, সুকৌশলী।'),
  ('bn.bengali', 9, 72, 'আল্লাহ ঈমানদার পুরুষ ও ঈমানদার নারীদের প্রতিশ্রুতি দিয়েছেনে কানন-কুঞ্জের, যার তলদেশে প্রবাহিত হয় প্রস্রবণ। তারা সে গুলোরই মাঝে থাকবে। আর এসব কানন-কুঞ্জে থাকবে পরিচ্ছন্ন থাকার ঘর। বস্তুতঃ এ সমুদয়ের মাঝে সবচেয়ে বড় হল আল্লাহর সন্তুষ্টি। এটিই হল মহান কৃতকার্যতা।'),
  ('bn.bengali', 9, 73, 'হে নবী, কাফেরদের সাথে যুদ্ধ করুন এবং মুনাফেকদের সাথে তাদের সাথে কঠোরতা অবলম্বন করুন। তাদের ঠিকানা হল দোযখ এবং তাহল নিকৃষ্ট ঠিকানা।'),
  ('bn.bengali', 9, 74, 'তারা কসম খায় যে, আমরা বলিনি, অথচ নিঃসন্দেহে তারা বলেছে কুফরী বাক্য এবং মুসলমান হবার পর অস্বীকৃতিজ্ঞাপনকারী হয়েছে। আর তারা কামনা করেছিল এমন বস্তুর যা তারা প্রাপ্ত হয়নি। আর এসব তারই পরিণতি ছিল যে, আল্লাহ ও তাঁর রসূল তাদেরকে সম্পদশালী করে দিয়েছিলেন নিজের অনুগ্রহের মাধ্যমে। বস্তুতঃ এরা যদি তওবা করে নেয়, তবে তাদের জন্য মঙ্গল। আর যদি তা না মানে, তবে তাদের কে আযাব দেবেন আল্লাহ তা’আলা, বেদনাদায়ক আযাব দুনিয়া ও আখেরাতে। অতএব, বিশ্বচরাচরে তাদের জন্য কোন সাহায্যকারী-সমর্থক নেই।'),
  ('bn.bengali', 9, 75, 'তাদের মধ্যে কেউ কেউ রয়েছে যারা আল্লাহ তা’আলার সাথে ওয়াদা করেছিল যে, তিনি যদি আমাদের প্রতি অনুগ্রহ দান করেন, তবে অবশ্যই আমরা ব্যয় করব এবং সৎকর্মীদের অন্তর্ভুক্ত হয়ে থাকব।'),
  ('bn.bengali', 9, 76, 'অতঃপর যখন তাদেরকে স্বীয় অনুগ্রহের মাধ্যমে দান করা হয়, তখন তাতে কার্পণ্য করেছে এবং কৃত ওয়াদা থেকে ফিরে গেছে তা ভেঙ্গে দিয়ে।'),
  ('bn.bengali', 9, 77, 'তারপর এরই পরিণতিতে তাদের অন্তরে কপটতা স্থান করে নিয়েছে সেদিন পর্যন্ত, যেদিন তার তাঁর সাথে গিয়ে মিলবে। তা এজন্য যে, তারা আল্লাহর সাথে কৃত ওয়াদা লংঘন করেছিল এবং এজন্যে যে, তারা মিথ্যা কথা বলতো।'),
  ('bn.bengali', 9, 78, 'তারা কি জেনে নেয়নি যে, আল্লাহ তাদের রহস্য ও শলা-পরামর্শ সম্পর্কে অবগত এবং আল্লাহ খুব ভাল করেই জানেন সমস্ত গোপন বিষয় ?'),
  ('bn.bengali', 9, 79, 'সে সমস্ত লোক যারা ভৎর্সনা-বিদ্রূপ করে সেসব মুসলমানদের প্রতি যারা মন খুলে দান-খয়রাত করে এবং তাদের প্রতি যাদের কিছুই নেই শুধুমাত্র নিজের পরিশ্রমলব্দ বস্তু ছাড়া। অতঃপর তাদের প্রতি ঠাট্টা করে। আল্লাহ তাদের প্রতি ঠাট্টা করেছেন এবং তাদের জন্য রয়েছে বেদনাদায়ক আযাব।'),
  ('bn.bengali', 9, 80, 'তুমি তাদের জন্য ক্ষমা প্রার্থনা কর আর না কর। যদি তুমি তাদের জন্য সত্তর বারও ক্ষমাপ্রার্থনা কর, তথাপি কখনোই তাদেরকে আল্লাহ ক্ষমা করবেন না। তা এজন্য যে, তারা আল্লাহকে এবং তাঁর রসূলকে অস্বীকার করেছে। বস্তুতঃ আল্লাহ না-ফারমানদেরকে পথ দেখান না।'),
  ('bn.bengali', 9, 81, 'পেছনে থেকে যাওয়া লোকেরা আল্লাহর রসূল থেকে বিচ্ছিন্ন হয়ে বসে থাকতে পেরে আনন্দ লাভ করেছে; আর জান ও মালের দ্বারা আল্লাহর রাহে জেহাদ করতে অপছন্দ করেছে এবং বলেছে, এই গরমের মধ্যে অভিযানে বের হয়ো না। বলে দাও, উত্তাপে জাহান্নামের আগুন প্রচন্ডতম। যদি তাদের বিবেচনা শক্তি থাকত।'),
  ('bn.bengali', 9, 82, 'অতএব, তারা সামান্য হেসে নিক এবং তারা তাদের কৃতকর্মের বদলাতে অনেক বেশী কাঁদবে।'),
  ('bn.bengali', 9, 83, 'বস্তুতঃ আল্লাহ যদি তোমাকে তাদের মধ্য থেকে কোন শ্রেণীবিশেষের দিকে ফিরিয়ে নিয়ে যান এবং অতঃপর তারা তোমার কাছে অভিযানে বেরোবার অনুমতি কামনা করে, তবে তুমি বলো যে, তোমরা কখনো আমার সাথে বেরোবে না এবং আমার পক্ষ হয়ে কোন শত্রুর সাথে যুদ্ধ করবে না, তোমরা তো প্রথমবারে বসে থাকা পছন্দ করেছ, কাজেই পেছনে পড়ে থাকা লোকদের সাথেই বসে থাক।'),
  ('bn.bengali', 9, 84, 'আর তাদের মধ্য থেকে কারো মৃত্যু হলে তার উপর কখনও নামায পড়বেন না এবং তার কবরে দাঁড়াবেন না। তারা তো আল্লাহর প্রতি অস্বীকৃতি জ্ঞাপন করেছে এবং রসূলের প্রতিও। বস্তুতঃ তারা না ফরমান অবস্থায় মৃত্যু বরণ করেছে।'),
  ('bn.bengali', 9, 85, 'আর বিস্মিত হয়ো না তাদের ধন সম্পদ ও সন্তান-সন্তুতির দরুন। আল্লাহ তো এই চান যে, এ সবের কারণে তাদেরকে আযাবের ভেতরে রাখবেন দুনিয়ায় এবং তাদের প্রাণ নির্গত হওয়া পর্যন্ত যেন তারা কাফেরই থাকে।'),
  ('bn.bengali', 9, 86, 'আর যখন নাযিল হয় কোন সূরা যে, তোমরা ঈমান আন আল্লাহর উপর, তাঁর রসূলের সাথে একাত্ন হয়ে; তখন বিদায় কামনা করে তাদের সামর্থ?476;ান লোকেরা এবং বলে আমাদের অব্যাহতি দিন, যাতে আমরা (নিস্ক্রিয়ভাবে) বসে থাকা লোকদের সাথে থেকে যেতে পারি।'),
  ('bn.bengali', 9, 87, 'তারা পেছনে পড়ে থাকা লোকদের সাথে থেকে যেতে পেরে আনন্দিত হয়েছে এবং মোহর এঁটে দেয়া হয়েছে তাদের অন্তরসমূহের উপর। বস্তুতঃ তারা বোঝে না।'),
  ('bn.bengali', 9, 88, 'কিন্তু রসূল এবং সেসব লোক যারা ঈমান এনেছে, তাঁর সাথে তারা যুদ্ধ করেছে নিজেদের জান ও মালের দ্বারা। তাদেরই জন্য নির্ধারিত রয়েছে কল্যাণসমূহ এবং তারাই মুক্তির লক্ষ্যে উপনীত হয়েছে।'),
  ('bn.bengali', 9, 89, 'আল্লাহ তাদের জন্য তৈরী করে রেখেছেন কানন-কুঞ্জ, যার তলদেশে প্রবাহিত রয়েছে প্রস্রবণ। তারা তাতে বাস করবে অনন্তকাল। এটাই হল বিরাট কৃতকার্যতা।'),
  ('bn.bengali', 9, 90, 'আর ছলনাকারী বেদুঈন লোকেরা এলো, যাতে তাদের অব্যাহতি লাভ হতে পারে এবং নিবৃত্ত থাকতে পারে তাদেরই যারা আল্লাহ ও রসূলের সাথে মিথ্যা বলে ছিল। এবার তাদের উপর শীগ্রই আসবে বেদনাদায়ক আযাব যারা কাফের।'),
  ('bn.bengali', 9, 91, 'দূর্বল, রুগ্ন, ব্যয়ভার বহনে অসমর্থ লোকদের জন্য কোন অপরাধ নেই, যখন তারা মনের দিক থেকে পবিত্র হবে আল্লাহ ও রসূলের সাথে। নেককারদের উপর অভিযোগের কোন পথ নেই। আর আল্লাহ হচ্ছেন ক্ষমাকারী দয়ালু।'),
  ('bn.bengali', 9, 92, 'আর না আছে তাদের উপর যারা এসেছে তোমার নিকট যেন তুমি তাদের বাহন দান কর এবং তুমি বলেছ, আমার কাছে এমন কোন বস্তু নেই যে, তার উপর তোমাদের সওয়ার করাব তখন তারা ফিরে গেছে অথচ তখন তাদের চোখ দিয়ে অশ্রু বইতেছিল এ দুঃখে যে, তারা এমন কোন বস্তু পাচ্ছে না যা ব্যয় করবে।'),
  ('bn.bengali', 9, 93, 'অভিযোগের পথ তো তাদের ব্যাপারে রয়েছে, যারা তোমার নিকট অব্যাহতি কামনা করে অথচ তারা সম্পদশালী। যারা পেছনে পড়ে থাকা লোকদের সাথে থাকতে পেরে আনন্দিত হয়েছে। আর আল্লাহ মোহর এঁটে দিয়েছেন তাদের অন্তরসমূহে। বস্তুতঃ তারা জানতেও পারেনি।'),
  ('bn.bengali', 9, 94, 'তুমি যখন তাদের কাছে ফিরে আসবে, তখন তারা তোমাদের নিকট ছল-ছুতা নিয়ে উপস্থিত হবে; তুমি বলো, ছল কারো না, আমি কখনো তোমাদের কথা শুনব না; আমাকে আল্লাহ তা’আলা তোমাদের অবস্থা সম্পর্কে অবহিত করে দিয়েছেন। আর এখন তোমাদের কর্ম আল্লাহই দেখবেন এবং তাঁর রসূল। তারপর তোমরা প্রত্যাবর্তিত হবে সেই গোপন ও আগোপন বিষয়ে অবগত সত্তার নিকট। তিনিই তোমাদের বাতলে দেবেন যা তোমরা করছিলে।'),
  ('bn.bengali', 9, 95, 'এখন তারা তোমার সামনে আল্লাহর কসম খাবে, যখন তুমি তাদের কাছে ফিরে যাবে, যেন তুমি তাদের ক্ষমা করে দাও। সুতরাং তুমি তাদের ক্ষমা কর-নিঃসন্দেহে এরা অপবিত্র এবং তাদের কৃতকর্মের বদলা হিসাবে তাদের ঠিকানা হলো দোযখ।'),
  ('bn.bengali', 9, 96, 'তারা তোমার সামনে কসম খাবে যাতে তুমি তাদের প্রতি রাযী হয়ে যাও। অতএব, তুমি যদি রাযী হয়ে যাও তাদের প্রতি তবু আল্লাহ তা’আলা রাযী হবেন না, এ নাফরমান লোকদের প্রতি।'),
  ('bn.bengali', 9, 97, 'বেদুইনরা কুফর ও মোনাফেকীতে অত্যন্ত কঠোর হয়ে থাকে এবং এরা সেসব নীতি-কানুন না শেখারই যোগ্য যা আল্লাহ তা’আলা তাঁর রসূলের উপর নাযিল করেছেন। বস্তুতঃ আল্লাহ সব কিছুই জানেন এবং তিনি অত্যন্ত কুশলী।'),
  ('bn.bengali', 9, 98, 'আবার কোন কোন বেদুইন এমন ও রয়েছে যারা নিজেদের ব্যয় করাকে জরিমানা। বলে গন্য করে এবং তোমার উপর কোন দুর্দিন আসে কিনা সে অপেক্ষায় থাকে। তাদেরই উপর দুর্দিন আসুক। আর আল্লাহ হচ্ছেন শ্রবণকারী, পরিজ্ঞাত।'),
  ('bn.bengali', 9, 99, 'আর কোন কোন বেদুইন হল তারা, যারা ঈমান আনে আল্লাহর উপর, কেয়ামত দিনের উপর এবং নিজেদের ব্যয়কে আল্লাহর নৈকট্য এবং রসূলের দোয়া লাভের উপায় বলে গণ্য করে। জেনো! তাই হল তাদের ক্ষেত্রে নৈকট্য। আল্লাহ তাদেরকে নিজের রহমতের অন্তর্ভূক্ত করবেন। নিশ্চয়ই আল্লাহ ক্ষমাশীল, করুনাময়।'),
  ('bn.bengali', 9, 100, 'আর যারা সর্বপ্রথম হিজরতকারী ও আনছারদের মাঝে পুরাতন, এবং যারা তাদের অনুসরণ করেছে, আল্লাহ সে সমস্ত লোকদের প্রতি সন্তুষ্ট হয়েছেন এবং তারাও তাঁর প্রতি সন্তুষ্ট হয়েছে। আর তাদের জন্য প্রস্তুত রেখেছেন কানন-কুঞ্জ, যার তলদেশ দিয়ে প্রবাহিত প্রস্রবণসমূহ। সেখানে তারা থাকবে চিরকাল। এটাই হল মহান কৃতকার্যতা।'),
  ('bn.bengali', 9, 101, 'আর কিছু কিছু তোমার আশ-পাশের মুনাফেক এবং কিছু লোক মদীনাবাসী কঠোর মুনাফেকীতে অনঢ়। তুমি তাদের জান না; আমি তাদের জানি। আমি তাদেরকে আযাব দান করব দু’বার, তারপর তাদেরকে নিয়ে যাওয়া হবে মহান আযাবের দিকে।'),
  ('bn.bengali', 9, 102, 'আর কোন কোন লোক রয়েছে যারা নিজেদের পাপ স্বীকার করেছে, তারা মিশ্রিত করেছে একটি নেককাজ ও অন্য একটি বদকাজ। শীঘ্রই আল্লাহ হয়ত তাদেরকে ক্ষমা করে দেবেন। নিঃঃসন্দেহে আল্লাহ ক্ষমাশীল করুণাময়।'),
  ('bn.bengali', 9, 103, 'তাদের মালামাল থেকে যাকাত গ্রহণ কর যাতে তুমি সেগুলোকে পবিত্র করতে এবং সেগুলোকে বরকতময় করতে পার এর মাধ্যমে। আর তুমি তাদের জন্য দোয়া কর, নিঃসন্দেহে তোমার দোয়া তাদের জন্য সান্ত্বনা স্বরূপ। বস্তুতঃ আল্লাহ সবকিছুই শোনেন, জানেন।'),
  ('bn.bengali', 9, 104, 'তারা কি একথা জানতে পারেনি যে, আল্লাহ নিজেই স্বীয় বান্দাদের তওবা কবুল করেন এবং যাকাত গ্রহণ করেন? বস্তুতঃ আল্লাহই তওবা কবুলকারী, করুণাময়।'),
  ('bn.bengali', 9, 105, 'আর তুমি বলে দাও, তোমরা আমল করে যাও, তার পরবর্তীতে আল্লাহ দেখবেন তোমাদের কাজ এবং দেখবেন রসূল ও মুসলমানগণ। তাছাড়া তোমরা শীগ্রই প্রত্যাবর্তিত হবে তাঁর সান্নিধ্যে যিনি গোপন ও প্রকাশ্য বিষয়ে অবগত। তারপর তিনি জানিয়ে দেবেন তোমাদেরকে যা করতে।'),
  ('bn.bengali', 9, 106, 'আবার অনেক লোক রয়েছে যাদের কাজকর্ম আল্লাহর নির্দেশের উপর স্থগিত রয়েছে; তিনি হয় তাদের আযাব দেবেন না হয় তাদের ক্ষমা করে দেবেন। বস্তুতঃ আল্লাহ সব কিছুই জ্ঞাত, বিজ্ঞতাসম্পন্ন।'),
  ('bn.bengali', 9, 107, 'আর যারা নির্মাণ করেছে মসজিদ জিদের বশে এবং কুফরীর তাড়নায় মুমিনদের মধ্যে বিভেদ সৃস্টির উদ্দেশ্যে এবং ঐ লোকের জন্য ঘাটি স্বরূপ যে পূর্ব থেকে আল্লাহ ও তাঁর রসূলের সাথে যুদ্ধ করে আসছে, আর তারা অবশ্যই শপথ করবে যে, আমরা কেবল কল্যাণই চেয়েছি। পক্ষান্তরে আল্লাহ সাক্ষী যে, তারা সবাই মিথ্যুক।'),
  ('bn.bengali', 9, 108, 'তুমি কখনো সেখানে দাড়াবে না, তবে যে মসজিদের ভিত্তি রাখা হয়েছে তাকওয়ার উপর প্রথম দিন থেকে, সেটিই তোমার দাঁড়াবার যোগ্য স্থান। সেখানে রয়েছে এমন লোক, যারা পবিত্রতাকে ভালবাসে। আর আল্লাহ পবিত্র লোকদের ভালবাসেন।'),
  ('bn.bengali', 9, 109, 'যে ব্যাক্তি স্বীয় গৃহের ভিত্তি রেখেছে কোন গর্তের কিনারায় যা ধ্বসে পড়ার নিকটবর্তী এবং অতঃপর তা ওকে নিয়ে দোযখের আগুনে পতিত হয়। আর আল্লাহ জালেমদের পথ দেখান না।'),
  ('bn.bengali', 9, 110, 'তাদের নির্মিত গৃহটি তাদের অন্তরে সদা সন্দেহের উদ্রেক করে যাবে যে পর্যন্ত না তাদের অন্তরগুলো চৌচির হয়ে যায়। আর আল্লাহ সর্বজ্ঞ প্রজ্ঞাময়।'),
  ('bn.bengali', 9, 111, 'আল্লাহ ক্রয় করে নিয়েছেন মুসলমানদের থেকে তাদের জান ও মাল এই মূল্যে যে, তাদের জন্য রয়েছে জান্নাত। তারা যুদ্ধ করে আল্লাহর রাহেঃ অতঃপর মারে ও মরে। তওরাত, ইঞ্জিল ও কোরআনে তিনি এ সত্য প্রতিশ্রুতিতে অবিচল। আর আল্লাহর চেয়ে প্রতিশ্রুতি রক্ষায় কে অধিক? সুতরাং তোমরা আনন্দিত হও সে লেন-দেনের উপর, যা তোমরা করছ তাঁর সাথে। আর এ হল মহান সাফল্য।'),
  ('bn.bengali', 9, 112, 'তারা তওবাকারী, এবাদতকারী, শোকরগোযার, (দুনিয়ার সাথে) সম্পর্কচ্ছেদকারী, রুকু ও সিজদা আদায়কারী, সৎকাজের আদেশ দানকারী ও মন্দ কাজ থেকে নিবৃতকারী এবং আল্লাহর দেওয়া সীমাসমূহের হেফাযতকারী। বস্তুতঃ সুসংবাদ দাও ঈমানদারদেরকে।'),
  ('bn.bengali', 9, 113, 'নবী ও মুমিনের উচিত নয় মুশরেকদের মাগফেরাত কামনা করে, যদিও তারা আত্নীয় হোক একথা সুস্পষ্ট হওয়ার পর যে তারা দোযখী।'),
  ('bn.bengali', 9, 114, 'আর ইব্রাহীম কর্তৃক স্বীয় পিতার মাগফেরাত কামনা ছিল কেবল সেই প্রতিশ্রুতির কারণে, যা তিনি তার সাথে করেছিলেন। অতঃপর যখন তাঁর কাছে একথা প্রকাশ পেল যে, সে আল্লাহর শত্রু তখন তার সাথে সম্পর্ক ছিন্ন করে নিলেন। নিঃসন্দেহে ইব্রাহীম ছিলেন বড় কোমল হৃদয়, সহনশীল।'),
  ('bn.bengali', 9, 115, 'আর আল্লাহ কোন জাতিকে হেদায়েত করার পর পথভ্রষ্ট করেন না যতক্ষণ না তাদের জন্য পরিষ্কারভাবে বলে দেন সেসব বিষয় যা থেকে তাদের বেঁচে থাকা দরকার। নিঃসন্দেহে আল্লাহ সব বিষয়ে ওয়াকেফহাল।'),
  ('bn.bengali', 9, 116, 'নিশ্চয় আল্লাহরই জন্য আসমানসমূহ ও যমীনের সাম্রাজ্য। তিনিই জিন্দা করেন ও মৃত্যু ঘটান, আর আল্লাহ ব্যতীত তোমাদের জন্য কোন সহায়ও নেই, কোন সাহায্যকারীও নেই।'),
  ('bn.bengali', 9, 117, 'আল্লাহ দয়াশীল নবীর প্রতি এবং মুহাজির ও আনসারদের প্রতি, যারা কঠিন মহূর্তে নবীর সঙ্গে ছিল, যখন তাদের এক দলের অন্তর ফিরে যাওয়ার উপক্রম হয়েছিল। অতঃপর তিনি দয়াপরবশ হন তাদের প্রতি। নিঃসন্দেহে তিনি তাদের প্রতি দয়াশীল ও করুনাময়।'),
  ('bn.bengali', 9, 118, 'এবং অপর তিনজনকে যাদেরকে পেছনে রাখা হয়েছিল, যখন পৃথিবী বিস্তৃত হওয়া সত্বেও তাদের জন্য সঙ্কুচিত হয়ে গেল এবং তাদের জীবন দূর্বিসহ হয়ে উঠলো; আর তারা বুঝতে পারলো যে, আল্লাহ ব্যতীত আর কোন আশ্রয়স্থল নেই-অতঃপর তিনি সদয় হলেন তাদের প্রতি যাতে তারা ফিরে আসে। নিঃসন্দেহে আল্লাহ দয়াময় করুণাশীল।'),
  ('bn.bengali', 9, 119, 'হে ঈমানদারগণ, আল্লাহকে ভয় কর এবং সত্যবাদীদের সাথে থাক।'),
  ('bn.bengali', 9, 120, 'মদীনাবাসী ও পাশ্ববর্তী পল্লীবাসীদের উচিত নয় রসূলুল্লাহর সঙ্গ ত্যাগ করে পেছনে থেকে যাওয়া এবং রসূলের প্রাণ থেকে নিজেদের প্রাণকে অধিক প্রিয় মনে করা। এটি এজন্য যে, আল্লাহর পথে যে তৃষ্ণা, ক্লান্তি ও ক্ষুধা তাদের স্পর্শ করে এবং তাদের এমন পদক্ষেপ যা কাফেরদের মনে ক্রোধের কারণ হয় আর শত্রুদের পক্ষ থেকে তারা যা কিছু প্রাপ্ত হয়-তার প্রত্যেকটির পরিবর্তে তাদের জন্য লিখিত হয়ে নেক আমল। নিঃসন্দেহে আল্লাহ সৎকর্মশীল লোকদের হক নষ্ট করেন না।'),
  ('bn.bengali', 9, 121, 'আর তারা অল্প-বিস্তর যা কিছু ব্যয় করে, যত প্রান্তর তারা অতিক্রম করে, তা সবই তাদের নামে লেখা হয়, যেন আল্লাহ তাদের কৃতকর্মসমূহের উত্তম বিনিময় প্রদান করেন।'),
  ('bn.bengali', 9, 122, 'আর সমস্ত মুমিনের অভিযানে বের হওয়া সঙ্গত নয়। তাই তাদের প্রত্যেক দলের একটি অংশ কেন বের হলো না, যাতে দ্বীনের জ্ঞান লাভ করে এবং সংবাদ দান করে স্বজাতিকে, যখন তারা তাদের কাছে প্রত্যাবর্তন করবে, যেন তারা বাঁচতে পারে।'),
  ('bn.bengali', 9, 123, 'হে ঈমানদারগণ, তোমাদের নিকটবর্তী কাফেরদের সাথে যুদ্ধ চালিয়ে যাও এবং তারা তোমাদের মধ্যে কঠোরতা অনুভব করুক আর জেনে রাখ, আল্লাহ মুত্তাকীদের সাথে রয়েছেন।'),
  ('bn.bengali', 9, 124, 'আর যখন কোন সূরা অবতীর্ণ হয়, তখন তাদের কেউ কেউ বলে, এ সূরা তোমাদের মধ্যেকার ঈমান কতটা বৃদ্ধি করলো? অতএব যারা ঈমানদার, এ সূরা তাদের ঈমান বৃদ্ধি করেছে এবং তারা আনন্দিত হয়েছে।'),
  ('bn.bengali', 9, 125, 'বস্তুতঃ যাদের অন্তরে ব্যাধি রয়েছে এটি তাদের কলুষের সাথে আরো কলুষ বৃদ্ধি করেছে এবং তারা কাফের অবস্থায়ই মৃত্যু বরণ করলো।'),
  ('bn.bengali', 9, 126, 'তারা কি লক্ষ্য করে না, প্রতি বছর তারা দু’একবার বিপর্যস্ত হচ্ছে, অথচ, তারা এরপরও তওবা করে না কিংবা উপদেশ গ্রহণ করে না।'),
  ('bn.bengali', 9, 127, 'আর যখনই কোন সূরা অবতীর্ণ হয়, তখন তারা একে অন্যের দিকে তাকায় যে, কোন মুসলমান তোমাদের দেখছে কি-না-অতঃপর সরে পড়ে। আল্লাহ ওদের অন্তরকে সত্য বিমুখ করে দিয়েছেন! নিশ্চয়ই তারা নির্বোধ সম্প্রদায়।'),
  ('bn.bengali', 9, 128, 'তোমাদের কাছে এসেছে তোমাদের মধ্য থেকেই একজন রসূল। তোমাদের দুঃখ-কষ্ট তার পক্ষে দুঃসহ। তিনি তোমাদের মঙ্গলকামী, মুমিনদের প্রতি স্নেহশীল, দয়াময়।'),
  ('bn.bengali', 9, 129, 'এ সত্ত্বেও যদি তারা বিমুখ হয়ে থাকে, তবে বলে দাও, আল্লাহই আমার জন্য যথেষ্ট, তিনি ব্যতীত আর কারো বন্দেগী নেই। আমি তাঁরই ভরসা করি এবং তিনিই মহান আরশের অধিপতি।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 9, 1, 'Freedom from obligation (is proclaimed) from Allah and His messenger toward those of the idolaters with whom ye made a treaty.'),
  ('en.pickthall', 9, 2, 'Travel freely in the land four months, and know that ye cannot escape Allah and that Allah will confound the disbelievers (in His Guidance).'),
  ('en.pickthall', 9, 3, 'And a proclamation from Allah and His messenger to all men on the day of the Greater Pilgrimage that Allah is free from obligation to the idolaters, and (so is) His messenger. So, if ye repent, it will be better for you; but if ye are averse, then know that ye cannot escape Allah. Give tidings (O Muhammad) of a painful doom to those who disbelieve,'),
  ('en.pickthall', 9, 4, 'Excepting those of the idolaters with whom ye (Muslims) have a treaty, and who have since abated nothing of your right nor have supported anyone against you. (As for these), fulfil their treaty to them till their term. Lo! Allah loveth those who keep their duty (unto Him).'),
  ('en.pickthall', 9, 5, 'Then, when the sacred months have passed, slay the idolaters wherever ye find them, and take them (captive), and besiege them, and prepare for them each ambush. But if they repent and establish worship and pay the poor-due, then leave their way free. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 9, 6, 'And if anyone of the idolaters seeketh thy protection (O Muhammad), then protect him so that he may hear the Word of Allah, and afterward convey him to his place of safety. That is because they are a folk who know not.'),
  ('en.pickthall', 9, 7, 'How can there be a treaty with Allah and with His messenger for the idolaters save those with whom ye made a treaty at the Inviolable Place of Worship? So long as they are true to you, be true to them. Lo! Allah loveth those who keep their duty.'),
  ('en.pickthall', 9, 8, 'How (can there be any treaty for the others) when, if they have the upper hand of you, they regard not pact nor honour in respect of you? They satisfy you with their mouths the while their hearts refuse. And most of them are wrongdoers.'),
  ('en.pickthall', 9, 9, 'They have purchased with the revelations of Allah a little gain, so they debar (men) from His way. Lo! evil is that which they are wont to do.'),
  ('en.pickthall', 9, 10, 'And they observe toward a believer neither pact nor honour. These are they who are transgressors.'),
  ('en.pickthall', 9, 11, 'But if they repent and establish worship and pay the poor-due, then are they your brethren in religion. We detail Our revelations for a people who have knowledge.'),
  ('en.pickthall', 9, 12, 'And if they break their pledges after their treaty (hath been made with you) and assail your religion, then fight the heads of disbelief - Lo! they have no binding oaths - in order that they may desist.'),
  ('en.pickthall', 9, 13, 'Will ye not fight a folk who broke their solemn pledges, and purposed to drive out the messenger and did attack you first? What! Fear ye them? Now Allah hath more right that ye should fear Him, if ye are believers'),
  ('en.pickthall', 9, 14, 'Fight them! Allah will chastise them at your hands, and He will lay them low and give you victory over them, and He will heal the breasts of folk who are believers.'),
  ('en.pickthall', 9, 15, 'And He will remove the anger of their hearts. Allah relenteth toward whom He will. Allah is Knower, Wise.'),
  ('en.pickthall', 9, 16, 'Or deemed ye that ye would be left (in peace) when Allah yet knoweth not those of you who strive, choosing for familiar none save Allah and His messenger and the believers? Allah is Informed of what ye do.'),
  ('en.pickthall', 9, 17, 'It is not for the idolaters to tend Allah\'s sanctuaries, bearing witness against themselves of disbelief. As for such, their works are vain and in the Fire they will abide.'),
  ('en.pickthall', 9, 18, 'He only shall tend Allah\'s sanctuaries who believeth in Allah and the Last Day and observeth proper worship and payeth the poor-due and feareth none save Allah. For such (only) is it possible that they can be of the rightly guided.'),
  ('en.pickthall', 9, 19, 'Count ye the slaking of a pilgrim\'s thirst and tendance of the Inviolable Place of Worship as (equal to the worth of) him who believeth in Allah and the Last Day, and striveth in the way of Allah? They are not equal in the sight of Allah. Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 9, 20, 'Those who believe, and have left their homes and striven with their wealth and their lives in Allah\'s way are of much greater worth in Allah\'s sight. These are they who are triumphant.'),
  ('en.pickthall', 9, 21, 'Their Lord giveth them good tidings of mercy from Him, and acceptance, and Gardens where enduring pleasure will be theirs;'),
  ('en.pickthall', 9, 22, 'There they will abide for ever. Lo! with Allah there is immense reward.'),
  ('en.pickthall', 9, 23, 'O ye who believe! Choose not your fathers nor your brethren for friends if they take pleasure in disbelief rather than faith. Whoso of you taketh them for friends, such are wrong-doers.'),
  ('en.pickthall', 9, 24, 'Say: If your fathers, and your sons, and your brethren, and your wives, and your tribe, and the wealth ye have acquired, and merchandise for which ye fear that there will no sale, and dwellings ye desire are dearer to you than Allah and His messenger and striving in His way: then wait till Allah bringeth His command to pass. Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 9, 25, 'Allah hath given you victory on many fields and on the day of Huneyn, when ye exulted in your multitude but it availed you naught, and the earth, vast as it is, was straitened for you; then ye turned back in flight;'),
  ('en.pickthall', 9, 26, 'Then Allah sent His peace of reassurance down upon His messenger and upon the believers, and sent down hosts ye could not see, and punished those who disbelieved. Such is the reward of disbelievers.'),
  ('en.pickthall', 9, 27, 'Then afterward Allah will relent toward whom He will; for Allah is Forgiving, Merciful.'),
  ('en.pickthall', 9, 28, 'O ye who believe! The idolaters only are unclean. So let them not come near the Inviolable Place of Worship after this their year. If ye fear poverty (from the loss of their merchandise) Allah shall preserve you of His bounty if He will. Lo! Allah is Knower, Wise.'),
  ('en.pickthall', 9, 29, 'Fight against such of those who have been given the Scripture as believe not in Allah nor the Last Day, and forbid not that which Allah hath forbidden by His messenger, and follow not the Religion of Truth, until they pay the tribute readily, being brought low.'),
  ('en.pickthall', 9, 30, 'And the Jews say: Ezra is the son of Allah, and the Christians say: The Messiah is the son of Allah. That is their saying with their mouths. They imitate the saying of those who disbelieved of old. Allah (Himself) fighteth against them. How perverse are they!'),
  ('en.pickthall', 9, 31, 'They have taken as lords beside Allah their rabbis and their monks and the Messiah son of Mary, when they were bidden to worship only One Allah. There is no Allah save Him. Be He Glorified from all that they ascribe as partner (unto Him)!'),
  ('en.pickthall', 9, 32, 'Fain would they put out the light of Allah with their mouths, but Allah disdaineth (aught) save that He shall perfect His light, however much the disbelievers are averse.'),
  ('en.pickthall', 9, 33, 'He it is Who hath sent His messenger with the guidance and the Religion of Truth, that He may cause it to prevail over all religion, however much the idolaters may be averse.'),
  ('en.pickthall', 9, 34, 'O ye who believe! Lo! many of the (Jewish) rabbis and the (Christian) monks devour the wealth of mankind wantonly and debar (men) from the way of Allah. They who hoard up gold and silver and spend it not in the way of Allah, unto them give tidings (O Muhammad) of a painful doom,'),
  ('en.pickthall', 9, 35, 'On the day when it will (all) be heated in the fire of hell, and their foreheads and their flanks and their backs will be branded therewith (and it will be said unto them): Here is that which ye hoarded for yourselves. Now taste of what ye used to hoard.'),
  ('en.pickthall', 9, 36, 'Lo! the number of the months with Allah is twelve months by Allah\'s ordinance in the day that He created the heavens and the earth. Four of them are sacred: that is the right religion. So wrong not yourselves in them. And wage war on all of the idolaters as they are waging war on all of you. And know that Allah is with those who keep their duty (unto Him).'),
  ('en.pickthall', 9, 37, 'Postponement (of a sacred month) is only an excess of disbelief whereby those who disbelieve are misled; they allow it one year and forbid it (another) year, that they may make up the number of the months which Allah hath hallowed, so that they allow that which Allah hath forbidden. The evil of their deeds is made fairseeming unto them. Allah guideth not the disbelieving folk.'),
  ('en.pickthall', 9, 38, 'O ye who believe! What aileth you that when it is said unto you: Go forth in the way of Allah, ye are bowed down to the ground with heaviness. Take ye pleasure in the life of the world rather than in the Hereafter? The comfort of the life of the world is but little in the Hereafter.'),
  ('en.pickthall', 9, 39, 'If ye go not forth He will afflict you with a painful doom, and will choose instead of you a folk other than you. Ye cannot harm Him at all. Allah is Able to do all things.'),
  ('en.pickthall', 9, 40, 'If ye help him not, still Allah helped him when those who disbelieve drove him forth, the second of two; when they two were in the cave, when he said unto his comrade: Grieve not. Lo! Allah is with us. Then Allah caused His peace of reassurance to descend upon him and supported him with hosts ye cannot see, and made the word of those who disbelieved the nethermost, while Allah\'s Word it was that became the uppermost. Allah is Mighty, Wise.'),
  ('en.pickthall', 9, 41, 'Go forth, light-armed and heavy-armed, and strive with your wealth and your lives in the way of Allah! That is best for you if ye but knew.'),
  ('en.pickthall', 9, 42, 'Had it been a near adventure and an easy journey they had followed thee, but the distance seemed too far for them. Yet will they swear by Allah (saying): If we had been able we would surely have set out with you. They destroy their souls, and Allah knoweth that they verily are liars.'),
  ('en.pickthall', 9, 43, 'Allah forgive thee (O Muhammad)! Wherefor didst thou grant them leave ere those who told the truth were manifest to thee and thou didst know the liars?'),
  ('en.pickthall', 9, 44, 'Those who believe in Allah and the Last Day ask no leave of thee lest they should strive with their wealth and their lives. Allah is Aware of those who keep their duty (unto Him).'),
  ('en.pickthall', 9, 45, 'They alone ask leave of thee who believe not in Allah and the Last Day, and whose hearts feel doubt, so in their doubt they waver.'),
  ('en.pickthall', 9, 46, 'And if they had wished to go forth they would assuredly have made ready some equipment, but Allah was averse to their being sent forth and held them back and it was said (unto them): Sit ye with the sedentary!'),
  ('en.pickthall', 9, 47, 'Had they gone forth among you they had added to you naught save trouble and had hurried to and fro among you, seeking to cause sedition among you; and among you there are some who would have listened to them. Allah is Aware of evil-doers.'),
  ('en.pickthall', 9, 48, 'Aforetime they sought to cause sedition and raised difficulties for thee till the Truth came and the decree of Allah was made manifest, though they were loth.'),
  ('en.pickthall', 9, 49, 'Of them is he who saith: Grant me leave (to stay at home) and tempt me not. Surely it is into temptation that they (thus) have fallen. Lo! hell verily is all around the disbelievers.'),
  ('en.pickthall', 9, 50, 'If good befalleth thee (O Muhammad) it afflicteth them, and if calamity befalleth thee, they say: We took precaution, and they turn away well pleased.'),
  ('en.pickthall', 9, 51, 'Say: Naught befalleth us save that which Allah hath decreed for us. He is our Protecting Friend. In Allah let believers put their trust!'),
  ('en.pickthall', 9, 52, 'Say: Can ye await for us aught save one of two good things (death or victory in Allah\'s way)? while we await for you that Allah will afflict you with a doom from Him or at our hands. Await then! Lo! We are awaiting with you.'),
  ('en.pickthall', 9, 53, 'Say: Pay (your contribution), willingly or unwillingly, it will not be accepted from you. Lo! ye were ever froward folk.'),
  ('en.pickthall', 9, 54, 'And naught preventeth that their contributions should be accepted from them save that they have disbelieved in Allah and in His messenger, and they come not to worship save as idlers, and pay not (their contribution) save reluctantly.'),
  ('en.pickthall', 9, 55, 'So let not their riches nor their children please thee (O Muhammad). Allah thereby intendeth but to punish them in the life of the world and that their souls shall pass away while they are disbelievers.'),
  ('en.pickthall', 9, 56, 'And they swear by Allah that they are in truth of you, when they are not of you, but they are folk who are afraid.'),
  ('en.pickthall', 9, 57, 'Had they but found a refuge, or caverns, or a place to enter, they surely had resorted thither swift as runaways.'),
  ('en.pickthall', 9, 58, 'And of them is he who defameth thee in the matter of the alms. If they are given thereof they are content, and if they are not given thereof, behold! they are enraged.'),
  ('en.pickthall', 9, 59, '(How much more seemly) had they been content with that which Allah and His messenger had given them and had said: Allah sufficeth us. Allah will give us of His bounty, and (also) His messenger. Unto Allah we are suppliants.'),
  ('en.pickthall', 9, 60, 'The alms are only for the poor and the needy, and those who collect them, and those whose hearts are to be reconciled, and to free the captives and the debtors, and for the cause of Allah, and (for) the wayfarer; a duty imposed by Allah. Allah is Knower, Wise.'),
  ('en.pickthall', 9, 61, 'And of them are those who vex the Prophet and say: He is only a hearer. Say: A hearer of good for you, who believeth in Allah and is true to the believers, and a mercy for such of you as believe. Those who vex the messenger of Allah, for them there is a painful doom.'),
  ('en.pickthall', 9, 62, 'They swear by Allah to you (Muslims) to please you, but Allah, with His messenger, hath more right that they should please Him if they are believers.'),
  ('en.pickthall', 9, 63, 'Know they not that whoso opposeth Allah and His messenger, his verily is fire of hell, to abide therein? That is the extreme abasement.'),
  ('en.pickthall', 9, 64, 'The hypocrites fear lest a surah should be revealed concerning them, proclaiming what is in their hearts. Say: Scoff (your fill)! Lo! Allah is disclosing what ye fear.'),
  ('en.pickthall', 9, 65, 'And if thou ask them (O Muhammad) they will say: We did but talk and jest. Say: Was it at Allah and His revelations and His messenger that ye did scoff?'),
  ('en.pickthall', 9, 66, 'Make no excuse. Ye have disbelieved after your (confession of) belief. If We forgive a party of you, a party of you We shall punish because they have been guilty.'),
  ('en.pickthall', 9, 67, 'The hypocrites, both men and women, proceed one from another. They enjoin the wrong, and they forbid the right, and they withhold their hands (from spending for the cause of Allah). They forget Allah, so He hath forgotten them. Lo! the hypocrites, they are the transgressors.'),
  ('en.pickthall', 9, 68, 'Allah promiseth the hypocrites, both men and women, and the disbelievers fire of hell for their abode. It will suffice them. Allah curseth them, and theirs is lasting torment.'),
  ('en.pickthall', 9, 69, 'Even as those before you who were mightier than you in strength, and more affluent than you in wealth and children. They enjoyed their lot awhile, so ye enjoy your lot awhile even as those before you did enjoy their lot awhile. And ye prate even as they prated. Such are they whose works have perished in the world and the Hereafter. Such are they who are the losers.'),
  ('en.pickthall', 9, 70, 'Hath not the fame of those before them reached them - the folk of Noah, A\'ad, Thamud, the folk of Abraham, the dwellers of Midian and the disasters (which befell them)? Their messengers (from Allah) came unto them with proofs (of Allah\'s Sovereignty). So Allah surely wronged them not, but they did wrong themselves.'),
  ('en.pickthall', 9, 71, 'And the believers, men and women, are protecting friends one of another; they enjoin the right and forbid the wrong, and they establish worship and they pay the poor-due, and they obey Allah and His messenger. As for these, Allah will have mercy on them. Lo! Allah is Mighty, Wise.'),
  ('en.pickthall', 9, 72, 'Allah promiseth to the believers, men and women, Gardens underneath which rivers flow, wherein they will abide - blessed dwellings in Gardens of Eden. And - greater (far)! - acceptance from Allah. That is the supreme triumph.'),
  ('en.pickthall', 9, 73, 'O Prophet! Strive against the disbelievers and the hypocrites! Be harsh with them. Their ultimate abode is hell, a hapless journey\'s end.'),
  ('en.pickthall', 9, 74, 'They swear by Allah that they said nothing (wrong), yet they did say the word of disbelief, and did disbelieve after their Surrender (to Allah). And they purposed that which they could not attain, and they sought revenge only that Allah by His messenger should enrich them of His bounty. If they repent it will be better for them; and if they turn away, Allah will afflict them with a painful doom in the world and the Hereafter, and they have no protecting friend nor helper in the earth.'),
  ('en.pickthall', 9, 75, 'And of them is he who made a covenant with Allah (saying): If He give us of His bounty we will give alms and become of the righteous.'),
  ('en.pickthall', 9, 76, 'Yet when He gave them of His bounty, they hoarded it and turned away, averse;'),
  ('en.pickthall', 9, 77, 'So He hath made the consequence (to be) hypocrisy in their hearts until the day when they shall meet Him, because they broke their word to Allah that they promised Him, and because they lied.'),
  ('en.pickthall', 9, 78, 'Know they not that Allah knoweth both their secret and the thought that they confide, and that Allah is the Knower of Things Hidden?'),
  ('en.pickthall', 9, 79, 'Those who point at such of the believers as give the alms willingly and such as can find naught to give but their endeavours, and deride them - Allah (Himself) derideth them. Theirs will be a painful doom.'),
  ('en.pickthall', 9, 80, 'Ask forgiveness for them (O Muhammad), or ask not forgiveness for them; though thou ask forgiveness for them seventy times Allah will not forgive them. That is because they disbelieved in Allah and His messenger, and Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 9, 81, 'Those who were left behind rejoiced at sitting still behind the messenger of Allah, and were averse to striving with their wealth and their lives in Allah\'s way. And they said: Go not forth in the heat! Say: The fire of hell is more intense of heat, if they but understood.'),
  ('en.pickthall', 9, 82, 'Then let them laugh a little: they will weep much, as the reward of what they used to earn.'),
  ('en.pickthall', 9, 83, 'If Allah bring thee back (from the campaign) unto a party of them and they ask of thee leave to go out (to fight), then say unto them: Ye shall never more go out with me nor fight with me against a foe. Ye were content with sitting still the first time. So sit still, with the useless.'),
  ('en.pickthall', 9, 84, 'And never (O Muhammad) pray for one of them who dieth, nor stand by his grave. Lo! they disbelieved in Allah and His messenger, and they died while they were evil-doers.'),
  ('en.pickthall', 9, 85, 'Let not their wealth nor their children please thee! Allah purposeth only to punish them thereby in the world, and that their souls shall pass away while they are disbelievers.'),
  ('en.pickthall', 9, 86, 'And when a surah is revealed (which saith): Believe in Allah and strive along with His messenger, the men of wealth among them still ask leave of thee and say: Suffer us to be with those who sit (at home).'),
  ('en.pickthall', 9, 87, 'They are content that they should be with the useless and their hearts are sealed, so that they apprehend not.'),
  ('en.pickthall', 9, 88, 'But the messenger and those who believe with him strive with their wealth and their lives. Such are they for whom are the good things. Such are they who are the successful.'),
  ('en.pickthall', 9, 89, 'Allah hath made ready for them Gardens underneath which rivers flow, wherein they will abide. That is the supreme triumph.'),
  ('en.pickthall', 9, 90, 'And those among the wandering Arabs who had an excuse came in order that permission might be granted them. And those who lied to Allah and His messenger sat at home. A painful doom will fall on those of them who disbelieve.'),
  ('en.pickthall', 9, 91, 'Not unto the weak nor unto the sick nor unto those who can find naught to spend is any fault (to be imputed though they stay at home) if they are true to Allah and His messenger. Not unto the good is there any road (of blame). Allah is Forgiving, Merciful.'),
  ('en.pickthall', 9, 92, 'Nor unto those whom, when they came to thee (asking) that thou shouldst mount them, thou didst tell: I cannot find whereon to mount you. They turned back with eyes flowing with tears, for sorrow that they could not find the means to spend.'),
  ('en.pickthall', 9, 93, 'The road (of blame) is only against those who ask for leave of thee (to stay at home) when they are rich. They are content to be with the useless. Allah hath sealed their hearts so that they know not.'),
  ('en.pickthall', 9, 94, 'They will make excuse to you (Muslims) when ye return unto them. Say: Make no excuse, for we shall not believe you. Allah hath told us tidings of you. Allah and His messenger will see your conduct, and then ye will be brought back unto Him Who knoweth the Invisible as well as the Visible, and He will tell you what ye used to do.'),
  ('en.pickthall', 9, 95, 'They will swear by Allah unto you, when ye return unto them, that ye may let them be. Let them be, for lo! they are unclean, and their abode is hell as the reward for what they used to earn.'),
  ('en.pickthall', 9, 96, 'They swear unto you, that ye may accept them. Though ye accept them. Allah verily accepteth not wrongdoing folk.'),
  ('en.pickthall', 9, 97, 'The wandering Arabs are more hard in disbelief and hypocrisy, and more likely to be ignorant of the limits which Allah hath revealed unto His messenger. And Allah is Knower, Wise.'),
  ('en.pickthall', 9, 98, 'And of the wandering Arabs there is he who taketh that which he expendeth (for the cause of Allah) as a loss, and awaiteth (evil) turns of fortune for you (that he may be rid of it). The evil turn of fortune will be theirs. Allah is Hearer, Knower.'),
  ('en.pickthall', 9, 99, 'And of the wandering Arabs there is he who believeth in Allah and the Last Day, and taketh that which he expendeth and also the prayers of the messenger as acceptable offerings in the sight of Allah. Lo! verily it is an acceptable offering for them. Allah will bring them into His mercy. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 9, 100, 'And the first to lead the way, of the Muhajirin and the Ansar, and those who followed them in goodness - Allah is well pleased with them and they are well pleased with Him, and He hath made ready for them Gardens underneath which rivers flow, wherein they will abide for ever. That is the supreme triumph.'),
  ('en.pickthall', 9, 101, 'And among those around you of the wandering Arabs there are hypocrites, and among the townspeople of Al-Madinah (there are some who) persist in hypocrisy whom thou (O Muhammad) knowest not. We, We know them, and We shall chastise them twice; then they will be relegated to a painful doom.'),
  ('en.pickthall', 9, 102, 'And (there are) others who have acknowledged their faults. They mixed a righteous action with another that was bad. It may be that Allah will relent toward them. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 9, 103, 'Take alms of their wealth, wherewith thou mayst purify them and mayst make them grow, and pray for them. Lo! thy prayer is an assuagement for them. Allah is Hearer, Knower.'),
  ('en.pickthall', 9, 104, 'Know they not that Allah is He Who accepteth repentance from His bondmen and taketh the alms, and that Allah is He Who is the Relenting, the Merciful.'),
  ('en.pickthall', 9, 105, 'And say (unto them): Act! Allah will behold your actions, and (so will) His messenger and the believers, and ye will be brought back to the Knower of the Invisible and the Visible, and He will tell you what ye used to do.'),
  ('en.pickthall', 9, 106, 'And (there are) others who await Allah\'s decree, whether He will punish them or will forgive them. Allah is Knower, Wise.'),
  ('en.pickthall', 9, 107, 'And as for those who chose a place of worship out of opposition and disbelief, and in order to cause dissent among the believers, and as an outpost for those who warred against Allah and His messenger aforetime, they will surely swear: We purposed naught save good. Allah beareth witness that they verily are liars.'),
  ('en.pickthall', 9, 108, 'Never stand (to pray) there. A place of worship which was found upon duty (to Allah) from the first day is more worthy that thou shouldst stand (to pray) therein, wherein are men who love to purify themselves. Allah loveth the purifiers.'),
  ('en.pickthall', 9, 109, 'Is he who founded his building upon duty to Allah and His good pleasure better; or he who founded his building on the brink of a crumbling, overhanging precipice so that it toppled with him into the fire of hell? Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 9, 110, 'The building which they built will never cease to be a misgiving in their hearts unless their hearts be torn to pieces. Allah is Knower, Wise.'),
  ('en.pickthall', 9, 111, 'Lo! Allah hath bought from the believers their lives and their wealth because the Garden will be theirs: they shall fight in the way of Allah and shall slay and be slain. It is a promise which is binding on Him in the Torah and the Gospel and the Qur\'an. Who fulfilleth His covenant better than Allah? Rejoice then in your bargain that ye have made, for that is the supreme triumph.'),
  ('en.pickthall', 9, 112, '(Triumphant) are those who turn repentant (to Allah), those who serve (Him), those who praise (Him), those who fast, those who bow down, those who fall prostrate (in worship), those who enjoin the right and who forbid the wrong and those who keep the limits (ordained) of Allah - And give glad tidings to believers!'),
  ('en.pickthall', 9, 113, 'It is not for the Prophet, and those who believe, to pray for the forgiveness of idolaters even though they may be near of kin (to them) after it hath become clear that they are people of hell-fire.'),
  ('en.pickthall', 9, 114, 'The prayer of Abraham for the forgiveness of his father was only because of a promise he had promised him, but when it had become clear unto him that he (his father) was an enemy to Allah he (Abraham) disowned him. Lo! Abraham was soft of heart, long-suffering.'),
  ('en.pickthall', 9, 115, 'It was never Allah\'s (part) that He should send a folk astray after He had guided them until He had made clear unto them what they should avoid. Lo! Allah is Aware of all things.'),
  ('en.pickthall', 9, 116, 'Lo! Allah! Unto Him belongeth the Sovereignty of the heavens and the earth. He quickeneth and He giveth death. And ye have, instead of Allah, no protecting friend nor helper.'),
  ('en.pickthall', 9, 117, 'Allah hath turned in mercy to the Prophet, and to the Muhajirin and the Ansar who followed him in the hour of hardship. After the hearts of a party of them had almost swerved aside, then turned He unto them in mercy. Lo! He is Full of Pity, Merciful for them.'),
  ('en.pickthall', 9, 118, 'And to the three also (did He turn in mercy) who were left behind, when the earth, vast as it is, was straitened for them, and their own souls were straitened for them till they bethought them that there is no refuge from Allah save toward Him. Then turned He unto them in mercy that they (too) might turn (repentant unto Him). Lo! Allah! He is the Relenting, the Merciful.'),
  ('en.pickthall', 9, 119, 'O ye who believe! Be careful of your duty to Allah, and be with the truthful.'),
  ('en.pickthall', 9, 120, 'It is not for the townsfolk of Al-Madinah and for those around them of the wandering Arabs so stay behind the messenger of Allah and prefer their lives to his life. That is because neither thirst nor toil nor hunger afflicteth them in the way of Allah, nor step they any step that angereth the disbelievers, nor gain they from the enemy a gain, but a good deed is recorded for them therefor. Lo! Allah loseth not the wages of the good.'),
  ('en.pickthall', 9, 121, 'Nor spend they any spending, small or great, nor do they cross a valley, but it is recorded for them, that Allah may repay them the best of what they used to do.'),
  ('en.pickthall', 9, 122, 'And the believers should not all go out to fight. Of every troop of them, a party only should go forth, that they (who are left behind) may gain sound knowledge in religion, and that they may warn their folk when they return to them, so that they may beware.'),
  ('en.pickthall', 9, 123, 'O ye who believe! Fight those of the disbelievers who are near to you, and let them find harshness in you, and know that Allah is with those who keep their duty (unto Him).'),
  ('en.pickthall', 9, 124, 'And whenever a surah is revealed there are some of them who say: Which one of you hath thus increased in faith? As for those who believe, it hath increased them in faith and they rejoice (therefor).'),
  ('en.pickthall', 9, 125, 'But as for those in whose hearts is disease, it only addeth wickedness to their wickedness, and they die while they are disbelievers.'),
  ('en.pickthall', 9, 126, 'See they not that they are tested once or twice in every year? Still they turn not in repentance, neither pay they heed.'),
  ('en.pickthall', 9, 127, 'And whenever a surah is revealed, they look one at another (as who should say): Doth anybody see you? Then they turn away. Allah turneth away their hearts because they are a folk who understand not.'),
  ('en.pickthall', 9, 128, 'There hath come unto you a messenger, (one) of yourselves, unto whom aught that ye are overburdened is grievous, full of concern for you, for the believers full of pity, merciful.'),
  ('en.pickthall', 9, 129, 'Now, if they turn away (O Muhammad) say: Allah sufficeth me. There is no Allah save Him. In Him have I put my trust, and He is Lord of the Tremendous Throne.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 9, 1, 'A (declaration) of immunity from Allah and His Messenger, to those of the Pagans with whom ye have contracted mutual alliances:-'),
  ('en.yusufali', 9, 2, 'Go ye, then, for four months, backwards and forwards, (as ye will), throughout the land, but know ye that ye cannot frustrate Allah (by your falsehood) but that Allah will cover with shame those who reject Him.'),
  ('en.yusufali', 9, 3, 'And an announcement from Allah and His Messenger, to the people (assembled) on the day of the Great Pilgrimage,- that Allah and His Messenger dissolve (treaty) obligations with the Pagans. If then, ye repent, it were best for you; but if ye turn away, know ye that ye cannot frustrate Allah. And proclaim a grievous penalty to those who reject Faith.'),
  ('en.yusufali', 9, 4, '(But the treaties are) not dissolved with those Pagans with whom ye have entered into alliance and who have not subsequently failed you in aught, nor aided any one against you. So fulfil your engagements with them to the end of their term: for Allah loveth the righteous.'),
  ('en.yusufali', 9, 5, 'But when the forbidden months are past, then fight and slay the Pagans wherever ye find them, an seize them, beleaguer them, and lie in wait for them in every stratagem (of war); but if they repent, and establish regular prayers and practise regular charity, then open the way for them: for Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 9, 6, 'If one amongst the Pagans ask thee for asylum, grant it to him, so that he may hear the word of Allah; and then escort him to where he can be secure. That is because they are men without knowledge.'),
  ('en.yusufali', 9, 7, 'How can there be a league, before Allah and His Messenger, with the Pagans, except those with whom ye made a treaty near the sacred Mosque? As long as these stand true to you, stand ye true to them: for Allah doth love the righteous.'),
  ('en.yusufali', 9, 8, 'How (can there be such a league), seeing that if they get an advantage over you, they respect not in you the ties either of kinship or of covenant? With (fair words from) their mouths they entice you, but their hearts are averse from you; and most of them are rebellious and wicked.'),
  ('en.yusufali', 9, 9, 'The Signs of Allah have they sold for a miserable price, and (many) have they hindered from His way: evil indeed are the deeds they have done.'),
  ('en.yusufali', 9, 10, 'In a Believer they respect not the ties either of kinship or of covenant! It is they who have transgressed all bounds.'),
  ('en.yusufali', 9, 11, 'But (even so), if they repent, establish regular prayers, and practise regular charity,- they are your brethren in Faith: (thus) do We explain the Signs in detail, for those who understand.'),
  ('en.yusufali', 9, 12, 'But if they violate their oaths after their covenant, and taunt you for your Faith,- fight ye the chiefs of Unfaith: for their oaths are nothing to them: that thus they may be restrained.'),
  ('en.yusufali', 9, 13, 'Will ye not fight people who violated their oaths, plotted to expel the Messenger, and took the aggressive by being the first (to assault) you? Do ye fear them? Nay, it is Allah Whom ye should more justly fear, if ye believe!'),
  ('en.yusufali', 9, 14, 'Fight them, and Allah will punish them by your hands, cover them with shame, help you (to victory) over them, heal the breasts of Believers,'),
  ('en.yusufali', 9, 15, 'And still the indignation of their hearts. For Allah will turn (in mercy) to whom He will; and Allah is All-Knowing, All-Wise.'),
  ('en.yusufali', 9, 16, 'Or think ye that ye shall be abandoned, as though Allah did not know those among you who strive with might and main, and take none for friends and protectors except Allah, His Messenger, and the (community of) Believers? But Allah is well-acquainted with (all) that ye do.'),
  ('en.yusufali', 9, 17, 'It is not for such as join gods with Allah, to visit or maintain the mosques of Allah while they witness against their own souls to infidelity. The works of such bear no fruit: In Fire shall they dwell.'),
  ('en.yusufali', 9, 18, 'The mosques of Allah shall be visited and maintained by such as believe in Allah and the Last Day, establish regular prayers, and practise regular charity, and fear none (at all) except Allah. It is they who are expected to be on true guidance.'),
  ('en.yusufali', 9, 19, 'Do ye make the giving of drink to pilgrims, or the maintenance of the Sacred Mosque, equal to (the pious service of) those who believe in Allah and the Last Day, and strive with might and main in the cause of Allah? They are not comparable in the sight of Allah: and Allah guides not those who do wrong.'),
  ('en.yusufali', 9, 20, 'Those who believe, and suffer exile and strive with might and main, in Allah\'s cause, with their goods and their persons, have the highest rank in the sight of Allah: they are the people who will achieve (salvation).'),
  ('en.yusufali', 9, 21, 'Their Lord doth give them glad tidings of a Mercy from Himself, of His good pleasure, and of gardens for them, wherein are delights that endure:'),
  ('en.yusufali', 9, 22, 'They will dwell therein for ever. Verily in Allah\'s presence is a reward, the greatest (of all).'),
  ('en.yusufali', 9, 23, 'O ye who believe! take not for protectors your fathers and your brothers if they love infidelity above Faith: if any of you do so, they do wrong.'),
  ('en.yusufali', 9, 24, 'Say: If it be that your fathers, your sons, your brothers, your mates, or your kindred; the wealth that ye have gained; the commerce in which ye fear a decline: or the dwellings in which ye delight - are dearer to you than Allah, or His Messenger, or the striving in His cause;- then wait until Allah brings about His decision: and Allah guides not the rebellious.'),
  ('en.yusufali', 9, 25, 'Assuredly Allah did help you in many battle-fields and on the day of Hunain: Behold! your great numbers elated you, but they availed you naught: the land, for all that it is wide, did constrain you, and ye turned back in retreat.'),
  ('en.yusufali', 9, 26, 'But Allah did pour His calm on the Messenger and on the Believers, and sent down forces which ye saw not: He punished the Unbelievers; thus doth He reward those without Faith.'),
  ('en.yusufali', 9, 27, 'Again will Allah, after this, turn (in mercy) to whom He will: for Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 9, 28, 'O ye who believe! Truly the Pagans are unclean; so let them not, after this year of theirs, approach the Sacred Mosque. And if ye fear poverty, soon will Allah enrich you, if He wills, out of His bounty, for Allah is All-knowing, All-wise.'),
  ('en.yusufali', 9, 29, 'Fight those who believe not in Allah nor the Last Day, nor hold that forbidden which hath been forbidden by Allah and His Messenger, nor acknowledge the religion of Truth, (even if they are) of the People of the Book, until they pay the Jizya with willing submission, and feel themselves subdued.'),
  ('en.yusufali', 9, 30, 'The Jews call \'Uzair a son of Allah, and the Christians call Christ the son of Allah. That is a saying from their mouth; (in this) they but imitate what the unbelievers of old used to say. Allah\'s curse be on them: how they are deluded away from the Truth!'),
  ('en.yusufali', 9, 31, 'They take their priests and their anchorites to be their lords in derogation of Allah, and (they take as their Lord) Christ the son of Mary; yet they were commanded to worship but One Allah: there is no god but He. Praise and glory to Him: (Far is He) from having the partners they associate (with Him).'),
  ('en.yusufali', 9, 32, 'Fain would they extinguish Allah\'s light with their mouths, but Allah will not allow but that His light should be perfected, even though the Unbelievers may detest (it).'),
  ('en.yusufali', 9, 33, 'It is He Who hath sent His Messenger with guidance and the Religion of Truth, to proclaim it over all religion, even though the Pagans may detest (it).'),
  ('en.yusufali', 9, 34, 'O ye who believe! there are indeed many among the priests and anchorites, who in Falsehood devour the substance of men and hinder (them) from the way of Allah. And there are those who bury gold and silver and spend it not in the way of Allah: announce unto them a most grievous penalty-'),
  ('en.yusufali', 9, 35, 'On the Day when heat will be produced out of that (wealth) in the fire of Hell, and with it will be branded their foreheads, their flanks, and their backs, their flanks, and their backs.- "This is the (treasure) which ye buried for yourselves: taste ye, then, the (treasures) ye buried!"'),
  ('en.yusufali', 9, 36, 'The number of months in the sight of Allah is twelve (in a year)- so ordained by Him the day He created the heavens and the earth; of them four are sacred: that is the straight usage. So wrong not yourselves therein, and fight the Pagans all together as they fight you all together. But know that Allah is with those who restrain themselves.'),
  ('en.yusufali', 9, 37, 'Verily the transposing (of a prohibited month) is an addition to Unbelief: the Unbelievers are led to wrong thereby: for they make it lawful one year, and forbidden another year, in order to adjust the number of months forbidden by Allah and make such forbidden ones lawful. The evil of their course seems pleasing to them. But Allah guideth not those who reject Faith.'),
  ('en.yusufali', 9, 38, 'O ye who believe! what is the matter with you, that, when ye are asked to go forth in the cause of Allah, ye cling heavily to the earth? Do ye prefer the life of this world to the Hereafter? But little is the comfort of this life, as compared with the Hereafter.'),
  ('en.yusufali', 9, 39, 'Unless ye go forth, He will punish you with a grievous penalty, and put others in your place; but Him ye would not harm in the least. For Allah hath power over all things.'),
  ('en.yusufali', 9, 40, 'If ye help not (your leader), (it is no matter): for Allah did indeed help him, when the Unbelievers drove him out: he had no more than one companion; they two were in the cave, and he said to his companion, "Have no fear, for Allah is with us": then Allah sent down His peace upon him, and strengthened him with forces which ye saw not, and humbled to the depths the word of the Unbelievers. But the word of Allah is exalted to the heights: for Allah is Exalted in might, Wise.'),
  ('en.yusufali', 9, 41, 'Go ye forth, (whether equipped) lightly or heavily, and strive and struggle, with your goods and your persons, in the cause of Allah. That is best for you, if ye (but) knew.'),
  ('en.yusufali', 9, 42, 'If there had been immediate gain (in sight), and the journey easy, they would (all) without doubt have followed thee, but the distance was long, (and weighed) on them. They would indeed swear by Allah, "If we only could, we should certainly have come out with you": They would destroy their own souls; for Allah doth know that they are certainly lying.'),
  ('en.yusufali', 9, 43, 'Allah give thee grace! why didst thou grant them until those who told the truth were seen by thee in a clear light, and thou hadst proved the liars?'),
  ('en.yusufali', 9, 44, 'Those who believe in Allah and the Last Day ask thee for no exemption from fighting with their goods and persons. And Allah knoweth well those who do their duty.'),
  ('en.yusufali', 9, 45, 'Only those ask thee for exemption who believe not in Allah and the Last Day, and whose hearts are in doubt, so that they are tossed in their doubts to and fro.'),
  ('en.yusufali', 9, 46, 'If they had intended to come out, they would certainly have made some preparation therefor; but Allah was averse to their being sent forth; so He made them lag behind, and they were told, "Sit ye among those who sit (inactive)."'),
  ('en.yusufali', 9, 47, 'If they had come out with you, they would not have added to your (strength) but only (made for) disorder, hurrying to and fro in your midst and sowing sedition among you, and there would have been some among you who would have listened to them. But Allah knoweth well those who do wrong.'),
  ('en.yusufali', 9, 48, 'Indeed they had plotted sedition before, and upset matters for thee, until,- the Truth arrived, and the Decree of Allah became manifest much to their disgust.'),
  ('en.yusufali', 9, 49, 'Among them is (many) a man who says: "Grant me exemption and draw me not into trial." Have they not fallen into trial already? and indeed Hell surrounds the Unbelievers (on all sides).'),
  ('en.yusufali', 9, 50, 'If good befalls thee, it grieves them; but if a misfortune befalls thee, they say, "We took indeed our precautions beforehand," and they turn away rejoicing.'),
  ('en.yusufali', 9, 51, 'Say: "Nothing will happen to us except what Allah has decreed for us: He is our protector": and on Allah let the Believers put their trust.'),
  ('en.yusufali', 9, 52, 'Say: "Can you expect for us (any fate) other than one of two glorious things- (Martyrdom or victory)? But we can expect for you either that Allah will send his punishment from Himself, or by our hands. So wait (expectant); we too will wait with you."'),
  ('en.yusufali', 9, 53, 'Say: "Spend (for the cause) willingly or unwillingly: not from you will it be accepted: for ye are indeed a people rebellious and wicked."'),
  ('en.yusufali', 9, 54, 'The only reasons why their contributions are not accepted are: that they reject Allah and His Messenger; that they come to prayer without earnestness; and that they offer contributions unwillingly.'),
  ('en.yusufali', 9, 55, 'Let not their wealth nor their (following in) sons dazzle thee: in reality Allah\'s plan is to punish them with these things in this life, and that their souls may perish in their (very) denial of Allah.'),
  ('en.yusufali', 9, 56, 'They swear by Allah that they are indeed of you; but they are not of you: yet they are afraid (to appear in their true colours).'),
  ('en.yusufali', 9, 57, 'If they could find a place to flee to, or caves, or a place of concealment, they would turn straightaway thereto, with an obstinate rush.'),
  ('en.yusufali', 9, 58, 'And among them are men who slander thee in the matter of (the distribution of) the alms: if they are given part thereof, they are pleased, but if not, behold! they are indignant!'),
  ('en.yusufali', 9, 59, 'If only they had been content with what Allah and His Messenger gave them, and had said, "Sufficient unto us is Allah! Allah and His Messenger will soon give us of His bounty: to Allah do we turn our hopes!" (that would have been the right course).'),
  ('en.yusufali', 9, 60, 'Alms are for the poor and the needy, and those employed to administer the (funds); for those whose hearts have been (recently) reconciled (to Truth); for those in bondage and in debt; in the cause of Allah; and for the wayfarer: (thus is it) ordained by Allah, and Allah is full of knowledge and wisdom.'),
  ('en.yusufali', 9, 61, 'Among them are men who molest the Prophet and say, "He is (all) ear." Say, "He listens to what is best for you: he believes in Allah, has faith in the Believers, and is a Mercy to those of you who believe." But those who molest the Messenger will have a grievous penalty.'),
  ('en.yusufali', 9, 62, 'To you they swear by Allah. In order to please you: But it is more fitting that they should please Allah and His Messenger, if they are Believers.'),
  ('en.yusufali', 9, 63, 'Know they not that for those who oppose Allah and His Messenger, is the Fire of Hell?- wherein they shall dwell. That is the supreme disgrace.'),
  ('en.yusufali', 9, 64, 'The Hypocrites are afraid lest a Sura should be sent down about them, showing them what is (really passing) in their hearts. Say: "Mock ye! But verily Allah will bring to light all that ye fear (should be revealed).'),
  ('en.yusufali', 9, 65, 'If thou dost question them, they declare (with emphasis): "We were only talking idly and in play." Say: "Was it at Allah, and His Signs, and His Messenger, that ye were mocking?"'),
  ('en.yusufali', 9, 66, 'Make ye no excuses: ye have rejected Faith after ye had accepted it. If We pardon some of you, We will punish others amongst you, for that they are in sin.'),
  ('en.yusufali', 9, 67, 'The Hypocrites, men and women, (have an understanding) with each other: They enjoin evil, and forbid what is just, and are close with their hands. They have forgotten Allah; so He hath forgotten them. Verily the Hypocrites are rebellious and perverse.'),
  ('en.yusufali', 9, 68, 'Allah hath promised the Hypocrites men and women, and the rejecters, of Faith, the fire of Hell: Therein shall they dwell: Sufficient is it for them: for them is the curse of Allah, and an enduring punishment,-'),
  ('en.yusufali', 9, 69, 'As in the case of those before you: they were mightier than you in power, and more flourishing in wealth and children. They had their enjoyment of their portion: and ye have of yours, as did those before you; and ye indulge in idle talk as they did. They!- their work are fruitless in this world and in the Hereafter, and they will lose (all spiritual good).'),
  ('en.yusufali', 9, 70, 'Hath not the story reached them of those before them?- the People of Noah, and \'Ad, and Thamud; the People of Abraham, the men of Midian, and the cities overthrown. To them came their messengers with clear signs. It is not Allah Who wrongs them, but they wrong their own souls.'),
  ('en.yusufali', 9, 71, 'The Believers, men and women, are protectors one of another: they enjoin what is just, and forbid what is evil: they observe regular prayers, practise regular charity, and obey Allah and His Messenger. On them will Allah pour His mercy: for Allah is Exalted in power, Wise.'),
  ('en.yusufali', 9, 72, 'Allah hath promised to Believers, men and women, gardens under which rivers flow, to dwell therein, and beautiful mansions in gardens of everlasting bliss. But the greatest bliss is the good pleasure of Allah: that is the supreme felicity.'),
  ('en.yusufali', 9, 73, 'O Prophet! strive hard against the unbelievers and the Hypocrites, and be firm against them. Their abode is Hell,- an evil refuge indeed.'),
  ('en.yusufali', 9, 74, 'They swear by Allah that they said nothing (evil), but indeed they uttered blasphemy, and they did it after accepting Islam; and they meditated a plot which they were unable to carry out: this revenge of theirs was (their) only return for the bounty with which Allah and His Messenger had enriched them! If they repent, it will be best for them; but if they turn back (to their evil ways), Allah will punish them with a grievous penalty in this life and in the Hereafter: They shall have none on earth to protect or help them.'),
  ('en.yusufali', 9, 75, 'Amongst them are men who made a covenant with Allah, that if He bestowed on them of His bounty, they would give (largely) in charity, and be truly amongst those who are righteous.'),
  ('en.yusufali', 9, 76, 'But when He did bestow of His bounty, they became covetous, and turned back (from their covenant), averse (from its fulfilment).'),
  ('en.yusufali', 9, 77, 'So He hath put as a consequence hypocrisy into their hearts, (to last) till the Day, whereon they shall meet Him: because they broke their covenant with Allah, and because they lied (again and again).'),
  ('en.yusufali', 9, 78, 'Know they not that Allah doth know their secret (thoughts) and their secret counsels, and that Allah knoweth well all things unseen?'),
  ('en.yusufali', 9, 79, 'Those who slander such of the believers as give themselves freely to (deeds of) charity, as well as such as can find nothing to give except the fruits of their labour,- and throw ridicule on them,- Allah will throw back their ridicule on them: and they shall have a grievous penalty.'),
  ('en.yusufali', 9, 80, 'Whether thou ask for their forgiveness, or not, (their sin is unforgivable): if thou ask seventy times for their forgiveness, Allah will not forgive them: because they have rejected Allah and His Messenger: and Allah guideth not those who are perversely rebellious.'),
  ('en.yusufali', 9, 81, 'Those who were left behind (in the Tabuk expedition) rejoiced in their inaction behind the back of the Messenger of Allah: they hated to strive and fight, with their goods and their persons, in the cause of Allah: they said, "Go not forth in the heat." Say, "The fire of Hell is fiercer in heat." If only they could understand!'),
  ('en.yusufali', 9, 82, 'Let them laugh a little: much will they weep: a recompense for the (evil) that they do.'),
  ('en.yusufali', 9, 83, 'If, then, Allah bring thee back to any of them, and they ask thy permission to come out (with thee), say: "Never shall ye come out with me, nor fight an enemy with me: for ye preferred to sit inactive on the first occasion: Then sit ye (now) with those who lag behind."'),
  ('en.yusufali', 9, 84, 'Nor do thou ever pray for any of them that dies, nor stand at his grave; for they rejected Allah and His Messenger, and died in a state of perverse rebellion.'),
  ('en.yusufali', 9, 85, 'Nor let their wealth nor their (following in) sons dazzle thee: Allah\'s plan is to punish them with these things in this world, and that their souls may perish in their (very) denial of Allah.'),
  ('en.yusufali', 9, 86, 'When a Sura comes down, enjoining them to believe in Allah and to strive and fight along with His Messenger, those with wealth and influence among them ask thee for exemption, and say: "Leave us (behind): we would be with those who sit (at home)."'),
  ('en.yusufali', 9, 87, 'They prefer to be with (the women), who remain behind (at home): their hearts are sealed and so they understand not.'),
  ('en.yusufali', 9, 88, 'But the Messenger, and those who believe with him, strive and fight with their wealth and their persons: for them are (all) good things: and it is they who will prosper.'),
  ('en.yusufali', 9, 89, 'Allah hath prepared for them gardens under which rivers flow, to dwell therein: that is the supreme felicity.'),
  ('en.yusufali', 9, 90, 'And there were, among the desert Arabs (also), men who made excuses and came to claim exemption; and those who were false to Allah and His Messenger (merely) sat inactive. Soon will a grievous penalty seize the Unbelievers among them.'),
  ('en.yusufali', 9, 91, 'There is no blame on those who are infirm, or ill, or who find no resources to spend (on the cause), if they are sincere (in duty) to Allah and His Messenger: no ground (of complaint) can there be against such as do right: and Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 9, 92, 'Nor (is there blame) on those who came to thee to be provided with mounts, and when thou saidst, "I can find no mounts for you," they turned back, their eyes streaming with tears of grief that they had no resources wherewith to provide the expenses.'),
  ('en.yusufali', 9, 93, 'The ground (of complaint) is against such as claim exemption while they are rich. They prefer to stay with the (women) who remain behind: Allah hath sealed their hearts; so they know not (What they miss).'),
  ('en.yusufali', 9, 94, 'They will present their excuses to you when ye return to them. Say thou: "Present no excuses: we shall not believe you: Allah hath already informed us of the true state of matters concerning you: It is your actions that Allah and His Messenger will observe: in the end will ye be brought back to Him Who knoweth what is hidden and what is open: then will He show you the truth of all that ye did."'),
  ('en.yusufali', 9, 95, 'They will swear to you by Allah, when ye return to them, that ye may leave them alone. So leave them alone: For they are an abomination, and Hell is their dwelling-place,-a fitting recompense for the (evil) that they did.'),
  ('en.yusufali', 9, 96, 'They will swear unto you, that ye may be pleased with them but if ye are pleased with them, Allah is not pleased with those who disobey.'),
  ('en.yusufali', 9, 97, 'The Arabs of the desert are the worst in Unbelief and hypocrisy, and most fitted to be in ignorance of the command which Allah hath sent down to His Messenger: But Allah is All-knowing, All-Wise.'),
  ('en.yusufali', 9, 98, 'Some of the desert Arabs look upon their payments as a fine, and watch for disasters for you: on them be the disaster of evil: for Allah is He That heareth and knoweth (all things).'),
  ('en.yusufali', 9, 99, 'But some of the desert Arabs believe in Allah and the Last Day, and look on their payments as pious gifts bringing them nearer to Allah and obtaining the prayers of the Messenger. Aye, indeed they bring them nearer (to Him): soon will Allah admit them to His Mercy: for Allah is Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 9, 100, 'The vanguard (of Islam)- the first of those who forsook (their homes) and of those who gave them aid, and (also) those who follow them in (all) good deeds,- well-pleased is Allah with them, as are they with Him: for them hath He prepared gardens under which rivers flow, to dwell therein for ever: that is the supreme felicity.'),
  ('en.yusufali', 9, 101, 'Certain of the desert Arabs round about you are hypocrites, as well as (desert Arabs) among the Medina folk: they are obstinate in hypocrisy: thou knowest them not: We know them: twice shall We punish them: and in addition shall they be sent to a grievous penalty.'),
  ('en.yusufali', 9, 102, 'Others (there are who) have acknowledged their wrong-doings: they have mixed an act that was good with another that was evil. Perhaps Allah will turn unto them (in Mercy): for Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 9, 103, 'Of their goods, take alms, that so thou mightest purify and sanctify them; and pray on their behalf. Verily thy prayers are a source of security for them: And Allah is One Who heareth and knoweth.'),
  ('en.yusufali', 9, 104, 'Know they not that Allah doth accept repentance from His votaries and receives their gifts of charity, and that Allah is verily He, the Oft-Returning, Most Merciful?'),
  ('en.yusufali', 9, 105, 'And say: "Work (righteousness): Soon will Allah observe your work, and His Messenger, and the Believers: Soon will ye be brought back to the knower of what is hidden and what is open: then will He show you the truth of all that ye did."'),
  ('en.yusufali', 9, 106, 'There are (yet) others, held in suspense for the command of Allah, whether He will punish them, or turn in mercy to them: and Allah is All-Knowing, Wise.'),
  ('en.yusufali', 9, 107, 'And there are those who put up a mosque by way of mischief and infidelity - to disunite the Believers - and in preparation for one who warred against Allah and His Messenger aforetime. They will indeed swear that their intention is nothing but good; But Allah doth declare that they are certainly liars.'),
  ('en.yusufali', 9, 108, 'Never stand thou forth therein. There is a mosque whose foundation was laid from the first day on piety; it is more worthy of the standing forth (for prayer) therein. In it are men who love to be purified; and Allah loveth those who make themselves pure.'),
  ('en.yusufali', 9, 109, 'Which then is best? - he that layeth his foundation on piety to Allah and His good pleasure? - or he that layeth his foundation on an undermined sand-cliff ready to crumble to pieces? and it doth crumble to pieces with him, into the fire of Hell. And Allah guideth not people that do wrong.'),
  ('en.yusufali', 9, 110, 'The foundation of those who so build is never free from suspicion and shakiness in their hearts, until their hearts are cut to pieces. And Allah is All-Knowing, Wise.'),
  ('en.yusufali', 9, 111, 'Allah hath purchased of the believers their persons and their goods; for theirs (in return) is the garden (of Paradise): they fight in His cause, and slay and are slain: a promise binding on Him in truth, through the Law, the Gospel, and the Qur\'an: and who is more faithful to his covenant than Allah? then rejoice in the bargain which ye have concluded: that is the achievement supreme.'),
  ('en.yusufali', 9, 112, 'Those that turn (to Allah) in repentance; that serve Him, and praise Him; that wander in devotion to the cause of Allah,: that bow down and prostrate themselves in prayer; that enjoin good and forbid evil; and observe the limit set by Allah;- (These do rejoice). So proclaim the glad tidings to the Believers.'),
  ('en.yusufali', 9, 113, 'It is not fitting, for the Prophet and those who believe, that they should pray for forgiveness for Pagans, even though they be of kin, after it is clear to them that they are companions of the Fire.'),
  ('en.yusufali', 9, 114, 'And Abraham prayed for his father\'s forgiveness only because of a promise he had made to him. But when it became clear to him that he was an enemy to Allah, he dissociated himself from him: for Abraham was most tender-hearted, forbearing.'),
  ('en.yusufali', 9, 115, 'And Allah will not mislead a people after He hath guided them, in order that He may make clear to them what to fear (and avoid)- for Allah hath knowledge of all things.'),
  ('en.yusufali', 9, 116, 'Unto Allah belongeth the dominion of the heavens and the earth. He giveth life and He taketh it. Except for Him ye have no protector nor helper.'),
  ('en.yusufali', 9, 117, 'Allah turned with favour to the Prophet, the Muhajirs, and the Ansar,- who followed him in a time of distress, after that the hearts of a part of them had nearly swerved (from duty); but He turned to them (also): for He is unto them Most Kind, Most Merciful.'),
  ('en.yusufali', 9, 118, '(He turned in mercy also) to the three who were left behind; (they felt guilty) to such a degree that the earth seemed constrained to them, for all its spaciousness, and their (very) souls seemed straitened to them,- and they perceived that there is no fleeing from Allah (and no refuge) but to Himself. Then He turned to them, that they might repent: for Allah is Oft-Returning, Most Merciful.'),
  ('en.yusufali', 9, 119, 'O ye who believe! Fear Allah and be with those who are true (in word and deed).'),
  ('en.yusufali', 9, 120, 'It was not fitting for the people of Medina and the Bedouin Arabs of the neighbourhood, to refuse to follow Allah\'s Messenger, nor to prefer their own lives to his: because nothing could they suffer or do, but was reckoned to their credit as a deed of righteousness,- whether they suffered thirst, or fatigue, or hunger, in the cause of Allah, or trod paths to raise the ire of the Unbelievers, or received any injury whatever from an enemy: for Allah suffereth not the reward to be lost of those who do good;-'),
  ('en.yusufali', 9, 121, 'Nor could they spend anything (for the cause) - small or great- nor cut across a valley, but the deed is inscribed to their credit: that Allah may requite their deed with the best (possible reward).'),
  ('en.yusufali', 9, 122, 'Nor should the Believers all go forth together: if a contingent from every expedition remained behind, they could devote themselves to studies in religion, and admonish the people when they return to them,- that thus they (may learn) to guard themselves (against evil).'),
  ('en.yusufali', 9, 123, 'O ye who believe! fight the unbelievers who gird you about, and let them find firmness in you: and know that Allah is with those who fear Him.'),
  ('en.yusufali', 9, 124, 'Whenever there cometh down a sura, some of them say: "Which of you has had His faith increased by it?" Yea, those who believe,- their faith is increased and they do rejoice.'),
  ('en.yusufali', 9, 125, 'But those in whose hearts is a disease,- it will add doubt to their doubt, and they will die in a state of Unbelief.'),
  ('en.yusufali', 9, 126, 'See they not that they are tried every year once or twice? Yet they turn not in repentance, and they take no heed.'),
  ('en.yusufali', 9, 127, 'Whenever there cometh down a Sura, they look at each other, (saying), "Doth anyone see you?" Then they turn aside: Allah hath turned their hearts (from the light); for they are a people that understand not.'),
  ('en.yusufali', 9, 128, 'Now hath come unto you a Messenger from amongst yourselves: it grieves him that ye should perish: ardently anxious is he over you: to the Believers is he most kind and merciful.'),
  ('en.yusufali', 9, 129, 'But if they turn away, Say: "Allah sufficeth me: there is no god but He: On Him is my trust,- He the Lord of the Throne (of Glory) Supreme!"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 9, 1, 'Baraaa\'atum minal laahi wa Rasooliheee ilal lazeena \'anhattum minal mushrikeen'),
  ('en.transliteration', 9, 2, 'Faseehoo fil ardi arba\'ata ashhurinw wa\'lamoooannakum ghairu mu\'jizil laahi wa annal laaha mukhzil kaafireen'),
  ('en.transliteration', 9, 3, 'Wa azaanum minal laahi wa Rasooliheee ilan naasi yawmal Hajjil Akbari annal laaha bareee\'um minal mushrikeena wa Rasooluh; fa-in tubtum fahuwa khairullakum wa in tawallaitum fa\'lamooo annakum ghairu mu\'jizil laah; wa bashiril lazeena kafaroo biazaabin aleem'),
  ('en.transliteration', 9, 4, 'Illal lazeena \'aahattum minal mushrikeena summa lam yanqusookum shai\'anw-wa lam yuzaahiroo \'alaikum ahadan fa atimmooo ilaihim \'ahdahum ilaa muddatihim; innal laaha yuhibbul muttaqeen'),
  ('en.transliteration', 9, 5, 'Fa izansalakhal Ashhurul Hurumu faqtulul mushrikeena haisu wajattumoohum wa khuzoohum wahsuroohum qaq\'udoo lahum kulla marsad; fa-in taaboo wa aqaamus Salaata wa aatawuz Zakaata fakhalloo sabeelahum; innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 9, 6, 'Wa in ahadum minal mushrikeenas tajaaraka fa ajirhu hattaa yasma\'a Kalaamal laahi summa ablighhu maa manah; zaalika bi annahum qawmul laa ya\'lamoon'),
  ('en.transliteration', 9, 7, 'Kaifa yakoonu lilmush rikeena \'ahdun \'indallaahi wa \'inda Rasoolihee illal lazeena \'aahattum \'indal Masjidil Haraami famas taqaamoo lakum fastaqeemoo lahum; innallaaha yuhibbul muttaqeen'),
  ('en.transliteration', 9, 8, 'Kaifa wa iny-yazharoo \'alaikum laa yarquboo feekum illanw wa laa zimmah; yurdoo nakum biafwaahihim wa taabaa quloobuhum wa aksaruhum faasiqoon'),
  ('en.transliteration', 9, 9, 'Ishtaraw bi Aayaatil laahi samanan qaleelan fasaddoo \'an sabeelih; innahum saaa\'a maa kaanoo ya\'maloon'),
  ('en.transliteration', 9, 10, 'Laa yarquboona fee mu\'minin illanw wa laa zimmah wa ulaaa \'ika humulmu \'tadoon'),
  ('en.transliteration', 9, 11, 'Fa in taaboo wa aqaamus Salaata wa aatawuz Zakaata fa ikhwaanukum fid deen; wa nufassilul Aayaati liqawminy ya\'lamoon'),
  ('en.transliteration', 9, 12, 'Wa in nakasooo aimaanahum mim ba\'di \'ahdihim wa ta\'anoo fee deenikum faqaatilooo a\'immatal kufri innahum laaa aimaana lahum la\'allahum yantahoon'),
  ('en.transliteration', 9, 13, 'Alaa tuqaatiloona qawman nakasooo aimaanahum wa hammoo bi ikhraajir Rasooli wa hum bada\'ookum awwala marrah; atakhshawnahum; fallaahu ahaqqu an takhshawhu in kuntum mu\'mineen'),
  ('en.transliteration', 9, 14, 'Qaatiloohum yu\'az zibhumul laahu bi aideekum wa yukhzihim wa yansurkum \'alaihim wa yashfi sudoora qawmim mu \'mineen'),
  ('en.transliteration', 9, 15, 'Wa yuzhib ghaiza quloobihim; wa yatoobullaahu \'alaa mai yashaaa\'; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 9, 16, 'Am hasibtum an turakoo wa lammaa ya\'lamil laahul lazeena jaahadoo minkum wa lam yattakhizoo min doonil laahi wa laa Rasoolihee wa lalmu\'mineena waleejah; wallaahu khabeerum bimaa ta\'maloon'),
  ('en.transliteration', 9, 17, 'maa kaana lilmushrikeena ai ya\'muroo masaajidal laahi shaahideena \'alaaa anfusihim bilkufr; ulaaa\'ika habitat a\'maaluhum wa fin naari hum khaalidoon'),
  ('en.transliteration', 9, 18, 'Innamaa ya\'muru masaa jidal laahi man aamana billaahi wal Yawmil Aakhiri wa aqaamas Salaata wa aataz Zakaata wa lam yakkhsa illal laaha fa\'asaaa ulaaa\'ika ai yakoonoo minal muhtadeen'),
  ('en.transliteration', 9, 19, 'Aja\'altum siqaayatal haaajji wa \'imaaratal masjidil haraami kamman aamana billaahi wal Yawmil Aakhiri wa jaahada fee sabeelil laah; laa yastawoona \'indal laah; wallaahu laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 9, 20, 'Allazeena aamanoo wa haajaroo wa jaahadoo fee sabeelil laahi bi amwaalihim wa anufsihim a\'zamu darajatan \'indal laah; wa ulaaa\'ika humul faaa\'izoon'),
  ('en.transliteration', 9, 21, 'Yubashshiruhum Rabbuhum birahmatim minhu wa ridwaaninw wa Jannaatil lahum feehaa na\'eemum muqeem'),
  ('en.transliteration', 9, 22, 'Khaalideena feehaaa abadaa; innal laaha \'indahooo ajrun \'azeem'),
  ('en.transliteration', 9, 23, 'Yaaa aiyuhal lazeena aamanoo laa tattakhizooo aabaaa \'akum wa ikhwaanakum awliyaaa\'a inis tahabbul kufra \'alal eemaan; wa mai yatawal lahum minkum fa ulaaa\'ika humuz zaalimoon'),
  ('en.transliteration', 9, 24, 'Qul in kaana aabaaa\'ukum wa abnaaa\'ukum wa ikhwaanukum wa azwaajukum wa \'asheeratukum wa amwaaluniq taraftumoohaa wa tijaaratun takhshawna kasaadahaa wa masaakinu tardawnahaaa ahabba ilaikum minal laahi wa Rasoolihee wa Jihaadin fee Sabeelihee fatarabbasoo hattaa yaatiyallaahu bi amrih; wallaahu laa yahdil qawmal faasiqeen'),
  ('en.transliteration', 9, 25, 'Laqad nasarakumul laahu fee mawaatina kaseeratinw wa yawma Hunainin iz a\'jabatkum kasratukum falam tughni \'ankum shai\'anw wa daaqat \'alaikumul ardu bimaa rahubat summa wallaitum mudbireen'),
  ('en.transliteration', 9, 26, 'Summa anzalal laahu sakeenatahoo \'alaa Rasoolihee wa \'alalmu \'mineena wa anzala junoodal lam tarawhaa wa azzabal lazeena kafaroo; wa zaalika jazaaa\'ul kaafireen'),
  ('en.transliteration', 9, 27, 'Summa yatoobul laahu mim ba\'di zaalika \'alaa mai yashaaa\'; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 9, 28, 'Yaaa aiyuhal lazeena aamanooo innamal mushrikoona najasun falaa yaqrabul Masjidal Haraama ba\'da \'aamihim haaza; wa in khiftum \'ailatan fasawfa yughnee kumul laahu min fadliheee in shaaa\'; innallaaha \'Aleemun hakeem'),
  ('en.transliteration', 9, 29, 'Qaatilul lazeena laa yu\'minoona billaahi wa laa bil yawmil Aakhiri wa laa yuharrimoona maa harramal laahu wa Rasooluhoo wa laa yadeenoona deenal haqqi minal lazeena ootul Kitaaba hattaa yu\'tul jizyata ai yadinw wa hum saaghiroon'),
  ('en.transliteration', 9, 30, 'Q qaalatil yahoodu \'Uzairunib nul laahi wa qaalatin Nasaaral Maseehub nul laahi zaalika qawluhum bi afwaahihim yudaahi\'oona qawlal lazeena kafaroo min qabl; qatalahumul laah; annaa yu\'fakoon'),
  ('en.transliteration', 9, 31, 'ittakhazooo ahbaarahum wa ruhbaanahum arbaabammin doonil laahi wal Maseehab na Maryama wa maaa umirooo illaa liya\'budooo Ilaahanw Waa hidan laaa ilaaha illaa Hoo; Subhaanahoo \'ammaa yushrikoon'),
  ('en.transliteration', 9, 32, 'Yureedoona ai yutfi\'oo nooral laahi bi\'afwaahihim wa yaaballaahu illaaa ai yutimma noorahoo wa law karihal kaafiroon'),
  ('en.transliteration', 9, 33, 'huwal lazeee ar sala Rasoolahoo bilhudaa wa deenil haqqi liyuzhirahoo \'alad deeni kullihee wa law karihal mushrikoon'),
  ('en.transliteration', 9, 34, 'Yaaa aiyuhal lazeena aamanooo inna kaseeramminal ahbaari warruhbaani la yaakuloona amwaalan naasi bil baatili wa yasuddoona \'an sabeelil laah; wallazeena yaknizoonaz zahaba wal fiddata wa laayunfiqoonahaa fee sabeelil laahi fabashshirhum bi\'azaabin aleem'),
  ('en.transliteration', 9, 35, 'Yawma yuhmaa \'alaihaa fee naari jahannama fatukwaa bihaa jibaahuhum haazaa maa kanaztum li anfusikum fazooqoo maa kuntum taknizoon'),
  ('en.transliteration', 9, 36, 'Inna \'iddatash shuhoori \'indal laahis naa \'ashara shahran fee Kitaabil laahi yawma khalaqas samaawaati wal arda minhaaa arba\'atun hurum; zaalikad deenul qaiyim; falaa tazlimoo feehinna anfusakum; wa qaatilul mushrikeena kaaaf fattan kamaa yuqaati loonakum kaaaffah; wa\'lamooo annal laaha ma\'al muttaqeen'),
  ('en.transliteration', 9, 37, 'Innamma naseee\'u ziyaadatun filkufri yudallu bihillazeena kafaroo yuhil loonahoo \'aamanw wa yuhar rimoonahoo \'aamalliyu watti\'oo \'iddata maa harramal laah; zuyyina lahum sooo\'u a\'maalihim; wallaahu laa yahdil qawmal kaafireen'),
  ('en.transliteration', 9, 38, 'Yaaa aiyuhal lazeena aamanoo maa lakum izaa qeela lakumun firoo fee sabeelil laahis saaqaltum ilal ard; aradeetum bilhayaatid dunyaa minal Aakhirah; famaa ma taaul hayaatiddunyaa fil Aakhirati illaa qaleel'),
  ('en.transliteration', 9, 39, 'Illaa tanfiroo yu\'az zibkum \'azaaban aleemanw wa yastabdil qawman ghairakum wa laa tadurroohu shai\'aa; wal laahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 9, 40, 'Illaa tansuroohu faqad nasarahul laahu iz akhrajahul lazeena kafaroo saaniyasnaini iz humaa filghaari iz yaqoolu lisaahibihee la tahzan innnal laaha ma\'anaa fa anzalallaahu sakeenatahoo \'alaihi wa aiyadahoo bijunoodil lam tarawhaa wa ja\'ala kalimatal lazeena kafarus suflaa; wa Kalimatul laahi hiyal \'ulyaa; wallaahu \'Azeezun Hakeem;'),
  ('en.transliteration', 9, 41, 'Infiroo khifaafanw wa siqaalanw wa jaahidoo bi amwaalikum wa anfusikum fee sabeelil laah; zaalikum khairul lakum in kuntum ta\'lamoon'),
  ('en.transliteration', 9, 42, 'Law kaana \'aradan qareebanw wa safaran qaasidal lattaba\'ooka wa laakim ba\'udat \'alaihimush shuqqah; wa sayahlifoona billaahi lawis tata\'naa lakharajnaa ma\'akum; yuhlikoona anfusahum wal laahu ya\'lamu innahum lakaa ziboon'),
  ('en.transliteration', 9, 43, '\'Afal laahu \'anka lima azinta lahum hattaa yatabai yana lakal lazeena sadaqoo wa ta\'lamal kaazibeen'),
  ('en.transliteration', 9, 44, 'Laa yastaazinukal lazeena yu\'minoona billaahi wal Yawmil Aakhiri ai yujaa hidoo bi amwaalihim wa anfusihim; wallaahu \'aleemum bilmut taqeen'),
  ('en.transliteration', 9, 45, 'Innamaa yastaazinukal lazeena laa yu\'minoona billaahi wal Yawmil Aakhiri wartaabat quloobuhum fahum fee raibihim yataraddadoon'),
  ('en.transliteration', 9, 46, 'Wa law araadul khurooja la-\'addoo lahoo \'uddatanw wa laakin karihal laahum bi\'aasahum fasabbatahum wa qeelaq \'udoo ma\'al qaa\'ideen'),
  ('en.transliteration', 9, 47, 'Law kharajoo feekum maa zaadookum ilaa Khabaalanw wa la awda\'oo khilaalakum yabghoona kumul fitnata wa feekum sammaa\'oona lahum; wallaahu \'aleemum biz zaalimeen'),
  ('en.transliteration', 9, 48, 'Laqadib taghawul fitnata min qablu wa qallaboo lakal umoora hattaa jaaa\'al haqqu wa zahara amrul laahi wa hum kaarihoon'),
  ('en.transliteration', 9, 49, 'Wa minhum mai yaqoolu\' zal lee wa laa taftinneee; alaa fil fitnati saqatoo; wa inna Jahannama lamuheetatum bil kaafireen'),
  ('en.transliteration', 9, 50, 'in tusibka hasanatun tasu\'hum; wa in tusibka museebatuny yaqooloo qad akhaznaaa amranaa min qablu wa yatawallaw wa hum farihoon'),
  ('en.transliteration', 9, 51, 'Qul lany-yuseebanaaa illaa maa katabal laahu lanaa Huwa mawlaanaa; wa \'alal laahi falyatawak kalimu \'minoon'),
  ('en.transliteration', 9, 52, 'Qul hal tarabbasoona binaaa illaaa ihdal husnayayni wa nahnu natrabbasu bikum ai yus eebakumul laahu bi\'azaa bim min \'indiheee aw biaidee naa fatarabbasooo innaa ma\'akum mutarabbisoon'),
  ('en.transliteration', 9, 53, 'Qul anfiqoo taw\'an aw karhal lany yutaqabbala min kum innakum kuntum qawman faasiqeen'),
  ('en.transliteration', 9, 54, 'Wa maa mana\'ahum an tuqbala minhum nafaqaatuhum illaaa annnahum kafaroo billaahi wa bi Rasoolihee wa laa yaatoonas Salaata illaa wa hum kusaalaa wa laa yunfiqoona illaa wa hum kaarihoon'),
  ('en.transliteration', 9, 55, 'Falaa tu\'jibka amwaaluhum wa laaa awlaaduhum; innamaa yureedul laahu liyu\'az zibahum bihaa fil hayaatid dunyaa wa tazhaqa anfusuhum wa hum kaafiroon'),
  ('en.transliteration', 9, 56, 'Wa yahlifoona billaahi innnahum laminkum wa maa hum minkum wa laakinnahum qawmuny yafraqoon'),
  ('en.transliteration', 9, 57, 'Law yajidoona malja\'an aw maghaaraatin aw mudda khalal lawallaw ilaihi wa hum yajmahoon'),
  ('en.transliteration', 9, 58, 'Wa minhum mai yalmizuka fis sadaqaati fa-in u\'too minhaa radoo wa illam yu\'taw minhaaa izaa hum yaskhatoon'),
  ('en.transliteration', 9, 59, 'Wa law annahum radoo maaa aataahumul laahu wa Rasooluhoo wa qaaloo hasbunal laahu wayu\'teenallaahu min fadlihee wa Rasooluhooo innaaa ilallaahi raaghiboon'),
  ('en.transliteration', 9, 60, 'Innamas sadaqaatu lilfuqaraaa\'i walmasaakeeni wal \'aamileena \'alaihaa wal mu\'al lafati quloobuhum wa fir riqaabi walghaarimeena wa fee sabeelil laahi wabnis sabeeli fareedatam minal laah; wal laahu \'Aleemun Hakeem'),
  ('en.transliteration', 9, 61, 'Wa minhumul lazeena yu\'zoonan nabiyya wa yaqooloona huwa uzun; qul uzunu khairil lakum yu\'minu billaahi wa yu\'minu lilmu mi neena wa rahmatul lillazeena aamanoo minkum; wallazeena yu\'zoona Rasoolal laahi lahum \'azaabun aleem'),
  ('en.transliteration', 9, 62, 'yahlifoona billaahi lakum liyurdookum wallaahu wa Rasooluhoo ahaqqu ai yurdoohu in kaanoo mu\'mineen'),
  ('en.transliteration', 9, 63, 'Alam ya\'lamooo annahoo mai yuhaadidillaaha wa Rasoolahoo faanna lahoo Naara jahannama khaalidan feehaa; zaalikal khizyul \'Azeem'),
  ('en.transliteration', 9, 64, 'Yahzarul munaafiqoona an tunaz zala \'alaihim Sooratun tunabbi \'uhum bimaa feequloobihim; qulistahzi\'oo innal laaha mukhrijum maa tahzaroon'),
  ('en.transliteration', 9, 65, 'Wala\'in sa altahum layaqoolunna innamaa kunnaa nakhoodu wa nal\'ab; qul abillaahi wa \'Aayaatihee wa Rasoolihee kuntum tastahzi\'oon'),
  ('en.transliteration', 9, 66, 'Laa ta\'taziroo qad kafartum ba\'da eemaanikum; in na\'fu \'an taaa\'ifatim minkum nu\'az zib taaa\'ifatam bi annahum kaanoo mujrimeen'),
  ('en.transliteration', 9, 67, 'Almunaafiqoona wal munaafiqaatu ba\'duhum mim ba\'d; yaamuroona bilmunkari wa yanhawna \'anil ma\'roofi wa yaqbidoona aidiyahum; nasul laaha fanasiyahum; innal munaafiqeena humul faasiqoon'),
  ('en.transliteration', 9, 68, 'Wa\'adal laahul munafiqeena wal munaafiqaati wal kuffaara naara jahannnamma khaalideena feehaa; hiya hasbuhum; wa la\'annahumul laahu wa lahum \'azaabum muqeem'),
  ('en.transliteration', 9, 69, 'Kallazeena min qablikum kaanoo ashadda minkum quwwatanw wa aksara amwaalanw wa awlaadan fastamta\'oo bikhalaaqihim fastamta\'tum bikhalaaqikum kamas tamta\'al lazeena min qablikum bikhalaa qihim wa khudtum kallazee khaadooo; ulaaa\'ika habitat a\'maaluhum fid dunyaa wal Aakhirati wa ulaaa\'ika humul khaasiroon'),
  ('en.transliteration', 9, 70, 'Alam yaatihim naba ul lazeena min qablihim qawmi Noohinw wa \'Aadinw wa Samooda wa qawmi Ibraaheema wa ashaabi adyana walmu\'tafikaat; atathum Rusuluhum bilbaiyinaati famaa kaanal laahu liyazlimahum wa laakin kaanooo anfusahum yazlimoon'),
  ('en.transliteration', 9, 71, 'Walmu\'minoona wal mu\'minaatu ba\'duhum awliyaaa\'u ba;d; yaamuroona bilma\'roofi wa yanhawna \'anil munkari wa yuqeemoonas Salaata wa yu\'toonaz Zakaata wa yutee\'oonal laaha wa Rasoolah; ulaaa\'ika sayarhamuhumul laah; innallaaha \'Azeezun Hakeem'),
  ('en.transliteration', 9, 72, 'Wa\'adal laahulmu\' mineena walmu\'minaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa wa masaakina taiyibatan fee Jannnaati \'adn; wa ridwaanum minal laahi akbar; zaalika hual fawzul \'azeem'),
  ('en.transliteration', 9, 73, 'yaaa aiyuhan Nabiyyu jaahidil kuffaara walmunaafiqeena waghluz \'alaihim; wa maawaahum jahannnamu wa bi\'sal maseer'),
  ('en.transliteration', 9, 74, 'Yahlifoona billaahi wa qaaloo wa laqad qaaloo kalimatal kufri wa kafaroo ba\'da Islaamihim wa hammoo bimaa lam yanaaloo; wa maa naqamooo illaaa an aghnaa humullaahu wa Rasooluhoo min fadlih; fainy yatooboo yaku khairal lahum wa iny yatawal law yu\'az zibhumullaahu \'azaaban aleeman fiddunyaa wal Aakhirah; wamaa lahum fil ardi minw waliyyinw wa laa naseer'),
  ('en.transliteration', 9, 75, 'Wa minhum man \'aaha dal laaha la\'in aataanaa min fadlihee lanas saddaqanna wa lanakoonanna minassaaliheen'),
  ('en.transliteration', 9, 76, 'Falammaaa aataahum min fadlihee bakhiloo bihee wa tawallaw wa hum mu\'ridoon'),
  ('en.transliteration', 9, 77, 'Fa a\'qabahum nifaaqan fee quloobihim ilaa Yawmi yalqaw nahoo bimaaa akhlaful laaha maa wa\'adoohu wa bimaa kaanoo yakhziboon'),
  ('en.transliteration', 9, 78, 'Alam ya\'lamooo annal laaha ya\'lamu sirrahum wa najwaahum wa annal laaha \'Allaamul Ghuyoob'),
  ('en.transliteration', 9, 79, 'Allazeena yalmizoonal mut tawwi\'eena minalmu\'mineena fis sadaqaati wallazeena laa yajidoona illaa juhdahum fayaskharoona minhum sakhiral laahu minhum wa lahum azaabun aleem'),
  ('en.transliteration', 9, 80, 'istaghfir lahum aw laa tastaghfir lahum in tastaghfir lahum sab\'eena marratan falany yaghfiral laahu lahum; zaalika bi annahum kafaroo billaahi wa Rasoolih; wallaahu laa yahdil qawmal faasiqeen'),
  ('en.transliteration', 9, 81, 'Farihal mukhallafoona bimaq\'adihim khilaafa Rasoolil laahi wa karihooo ai yujaahidoo bi amwaalihim wa anfusihim fee sabeelil laahi wa qaaloo la tanfiroo fil harr; qul Naaru jahannama ashaddu harraa; law kaanoo yafqahoon'),
  ('en.transliteration', 9, 82, 'Falyadhakoo qaleelanw walyabkoo kaseeran jazaaa\'am bimaa kaanoo yaksiboon'),
  ('en.transliteration', 9, 83, 'Fa ir raja\'akal laahu ilaa taaa\'ifatim minhum fastaaa zanooka lilkhurooji faqul lan takhrujoo ma\'iya abadanw a lan tuqaatiloo ma\'iya \'aduwwan innakum radeetum bilqu\'oodi awwala marratin faq\'udoo ma\'al khaalifeen'),
  ('en.transliteration', 9, 84, 'Wa laa tusalli \'alaaa ahadim minhum maata abadanw wa laa taqum \'alaa qabriheee innahum kafaroo billaahi wa Rasoolihee wa maatoo wa hum faasiqoon'),
  ('en.transliteration', 9, 85, 'Wa laa tu\'jibka amwaa luhum wa awlaaduhum; innamaa yureedul laahu ai yu\'az zibahum bihaa fid dunyaa wa tazhaqa anfusuhum wa hum kaafiroon'),
  ('en.transliteration', 9, 86, 'Wa izaaa unzilat Sooratun an aaminoo billaahi wa jaahidoo ma\'a Rasoolihis taazanaka uluttawli minhum wa qaaloo zarnaa nakum ma\'alqaa \'ideen'),
  ('en.transliteration', 9, 87, 'Radoo bi ai yakoonoo ma\'al khawaalifi wa tubi\'a \'alaa quloobihim fahum laa yafqahoon'),
  ('en.transliteration', 9, 88, 'Laakinir Rasoolu wal lazeena aamanoo ma\'ahoo jaahadoo bi amwaalihim wa anfusihim; wa ulaaa\'ika lahumul khairaatu wa ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 9, 89, 'A\'addal laahu lahum Jannaatin tajree min tahtihal anhaaru khaalideena feehaa; zaalikal fawzul \'azeem'),
  ('en.transliteration', 9, 90, 'Wa jaaa\'al mu\'az ziroona minal A\'raabi liyu\'zana lahum wa qa\'adal lazeena kazabul laaha wa Rasoolah; sayuseebul lazeena kafaroo minhum \'azaabun aleem'),
  ('en.transliteration', 9, 91, 'Laisa \'alad du\'aaaa\'i wa laa \'alal mardaa wa laa \'alal lazeena laa yajidoona maa yunfiqoona harajun izaa nasahoo lillaahi wa Rasoolih; maa \'alal muhsineena min sabeel; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 9, 92, 'Wa laa \'alal lazeena izaa maaa atawka litahmilahum qulta laaa ajidu maaa ahmilukum \'alaihi tawallaw wa a\'yunuhum tafeedu minaddam\'i hazanan allaa yajidoo maa yunfiqoon'),
  ('en.transliteration', 9, 93, 'Innamas sabeelu \'alal lazeena yastaazinoonaka wa hum aghniyaaa\'; radoo biany-yakoonoo ma\'al khawaalifi wa taba\'al laahu \'alaa quloobihim fahum laa ya\'lamoon'),
  ('en.transliteration', 9, 94, 'ya\'taziroona ilaikum izaa raja\'tum ilaihim; qul laa ta\'taziroo lan nu\'mina lakum qad nabba annal laahu min akhbaarikum; wa sa yaral laahu \'amalakum wa Rasooluhoo suma turaddoona ilaa \'Aalimil Ghaibi washshahaadati fa yunabbi\'ukum bimaa kuntum ta\'maloon'),
  ('en.transliteration', 9, 95, 'Sa yahlifoona billaahi lakum izanqalabtum ilaihim litu\'ridoo \'anhum fa a\'ridoo \'anhum innahum rijsunw wa maawaahum jahannamu jazaaa \'ambimaa kaanoo yaksiboon'),
  ('en.transliteration', 9, 96, 'Yahlifoona lakum litardaw \'anhum fa in tardaw \'anhum fa innal laaha laa yardaa \'anil qawmil faasiqeen'),
  ('en.transliteration', 9, 97, 'Al A\'raabu ashaddu kufranw wa nifaaqanw wa ajdaru allaa ya\'lamoo hudooda maaa anzalal laahu \'alaa Rasoolih; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 9, 98, 'Wa minal A\'raabi mai yattakhizu maa yunfiqu maghramanw wa yatarabbasu bikumud dawaaa\'ir; alaihim daaa\'iratus saw\'; wallaahu Samee\'un \'Aleem'),
  ('en.transliteration', 9, 99, 'Wa minal A\'raabi mai yu\'minu billaahi wal yawmil AAkhiri wa yattakhizu maa yunfiqu qurubaatin \'indal laahi wa salawaatir Rasool; alaaa innahaa qurbatul lahum; sayudkhiluhumul laahu fee rahmatih; innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 9, 100, 'Was saabiqoonal awwa loona minal Muhaajireena wal Ansaari wallazeenat taba\'oo hum bi ihsaanir radiyal laahu \'anhum wa radoo \'anhu wa a\'adda lahum jannnaatin tajree tahtahal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul \'azeem'),
  ('en.transliteration', 9, 101, 'Wa mimmann hawlakum minal A\'raabi munaafiqoona wa min ahlil Madeenati maradoo \'alan nifaaq, laa ta\'lamuhum nahnu na\'lamuhum; sanu\'azzibuhum marrataini summa yuraddoona ilaa \'azaabin \'azeem'),
  ('en.transliteration', 9, 102, 'Wa aakharoona\' tarafoo bizunoobihim khalatoo \'amalan saalihanw wa aakhara saiyi\'an \'asal laahu ai yatooba \'alaihim; innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 9, 103, 'Khuz min amwaalihim sadaqtan tutahhiruhum wa tuzakkeehim bihaa wa salli \'alaihim inna salaataka sakanul lahum; wallaahu Samee\'un \'Aleem'),
  ('en.transliteration', 9, 104, 'Alam ya\'lamooo annnal laaha huwa yaqbalut tawbata \'an ibaadihee wa yaakhuzus sadaqaati wa annal laaha Huwat awwaabur Raheem'),
  ('en.transliteration', 9, 105, 'Wa quli\'maloo fasayaral laahu \'amalakum wa Rasooluhoo walmu\'minoona wa saturaddoona ilaa \'Aalimil Ghaibi washshahaadati fa yunabbi\'ukum bimaa kuntum ta\'maloon'),
  ('en.transliteration', 9, 106, 'Wa aakharoona murjawna li amril laahi imaa yu\'az zibuhum wa immaa yatoobu \'alaihim; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 9, 107, 'Wallazeenat takhazoo masjidan diraaranw wa kufranw wa tafreeqam bainal mu\'mineena wa irsaadal liman haarabal laaha wa Rasoolahoo min qabl; wa la yahlifunna in aradnaaa illal husnaa wallaahu yash hadu innahum lakaaziboon'),
  ('en.transliteration', 9, 108, 'Laa taqum feehi abadaa; lamasjidun ussisa \'alat taqwaa min awwali yawmin ahaqqu an taqooma feeh; feehi rijaaluny yuhibbona ai yatatahharoo, wallaahu yuhibbul mmuttah hireen'),
  ('en.transliteration', 9, 109, 'Afaman assasa bunyaa nahoo \'alaa taqwaa minal laahi wa ridwaanin khairun am man assasa bunyaanahoo \'alaa shafaa jurufin haarin fanhaara bihee fee Naari Jahannnam; wallaahu laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 9, 110, 'Laa yazaalu bunyaanu humul lazee banaw reebatan fee quloobihim illaaa an taqatta\'a quloobuhum; wal laahu \'Aleemun Hakeem'),
  ('en.transliteration', 9, 111, 'Innal laahash taraa minal mu\'mineena anfusahum wa amwaalahum bi anna lahumul jannah; yuqaatiloona fee sabeelil laahi fa yaqtuloona wa yuqtaloona wa\'dan \'alaihi haqqan fit Tawraati wal Injeeli wal Qur-aan; wa man awfaa be\'ahdihee minal laah; fastabshiroo bibai\'ikumul lazee baaya\'tum bih; wa zaalika huwal fawzul \'azeem'),
  ('en.transliteration', 9, 112, 'At taaa\'iboonal \'aabidoonal haamidoonas saaa\'ihoonar raaki\'oonas saajidoonal aamiroona bilma\'roofi wannaahoona \'anil munkari walhaafizoona lihudoodil laah; wa bashshiril mu\'mineen'),
  ('en.transliteration', 9, 113, 'Maa kaana lin nabiyyi wallazeena aamanooo ai yastaghfiroo lilmushrikeena wa law kaanoo ulee qurbaa mim ba\'di maa tabiyana lahum annahum Ashaabul jaheem'),
  ('en.transliteration', 9, 114, 'Wa maa kaanas tighfaaru ibraaheema li abeehi illaa \'ammaw \'idatinw wa \'adahaaa iyyaahu falammaa tabaiyana lahooo annahoo \'aduwwul lillaahi tabarra a minh; inna Ibraaheema la awwaahum haleem'),
  ('en.transliteration', 9, 115, 'Wa maa kaanal laahu liyudilla qawmam ba\'da iz hadaahum hatta yubaiyina lahum maa yattaqoon; innal laaha bikulli shai\'in \'Aleem'),
  ('en.transliteration', 9, 116, 'Innal laaha lahoo mulkus samaawaati wal ardi yuhyee wa yumeet; wa maa lakum min doonil laahi minw waliyyinw wa laa naseer'),
  ('en.transliteration', 9, 117, 'Laqat taabal laahu \'alan nabiyyi wal Muhaajireena wal Ansaaril lazeenat taba\'oohu fee saa\'atil \'usrati mim ba\'di maa kaada yazeeghu quloobu fareeqim minhum summma taaba \'alaihim; innahoo bihim Ra\'oofur Raheem'),
  ('en.transliteration', 9, 118, 'Wa \'alas salaasatil lazeena khullifoo hattaaa izaa daaqat \'alaihimul ardu bimaa rahubat wa daaqat \'alaihim anfusuhum wa zannnooo al laa malja-a minal laahi illaaa ilaihi summa taaba \'alaihim liyatooboo; innal laaha Huwat Tawwaabur Raheem'),
  ('en.transliteration', 9, 119, 'Yaaa aiyuhal lazeena aamanut taqul laaha wa koonoo ma\'as saadiqeen'),
  ('en.transliteration', 9, 120, 'Maa kaana li ahlil Madeenati wa man hawlahum minal A\'raabi ai yatakhallafoo \'ar-Rasoolil laahi wa laa yarghaboo bi anfusihim \'an nafsih; zaalika bi annahum laa yuseebuhum zama unw wa laa nasabunw wa laa makhmasatun fee sabeelil laahi wa laa yata\'oona mawti\'ai yagheezul kuffaara wa laa yanaaloona min \'aduwwin nailan illaa kutiba lahum bihee \'amalun saalih; innal laaha laa yudee\'u ajral muhsineen'),
  ('en.transliteration', 9, 121, 'Wa laa yunfiqoona nafa qatan sagheeratanw wa laa kabeeratanw wa laa yaqta\'oona waadiyan illaa kutiba lahum liyajziyahumul laahu ahsana maa kaanoo ya\'maloon'),
  ('en.transliteration', 9, 122, 'Wa maa kaanal mu\'minoona liyanfiroo kaaaffah; falaw laa nafara min kulli firqatim minhum taaa\'ifatul liyatafaqqahoo fiddeeni wa liyunziroo qawmahum izaa raja\'ooo ilaihim la\'allahum yahzaroon'),
  ('en.transliteration', 9, 123, 'Yaaa aiyuhal lazeena aamanoo qaatilul lazeena yaloonakum minal kuffaari walyajidoo feekum ghilzah; wa\'lamooo annal laaha ma\'al muttaqeen'),
  ('en.transliteration', 9, 124, 'Wa izaa maaa unzilat Sooratun faminhum mai yaqoolu aiyukum zaadat hu haazihee eemaanaa; fa ammal lazeena aamanoo fazaadat hum eemaananw wa hum yastabshiroon'),
  ('en.transliteration', 9, 125, 'Wa ammal lazeena fee quloobihim maradun fazaadat hum rijsan ilaa rijsihim wa maatoo wa hum kaafiroon'),
  ('en.transliteration', 9, 126, 'Awalaa yarawna annahum yuftanoona fee kulli \'aamim marratan aw marrataini summa laa yatooboona wa laa hum yazzakkkaroon'),
  ('en.transliteration', 9, 127, 'Wa izaa maaa unzilat Sooratun nazara ba\'duhum ilaa ba\'din hal yaraakum min ahadin summman sarafoo; sarafal laahu quloobahum bi annahum qawmul laa yafqahoon'),
  ('en.transliteration', 9, 128, 'Laqad jaaa\'akum Rasoolum min anfusikum \'azeezun \'alaihi maa \'anittum hareesun \'alaikum bilmu\'mineena ra\'oofur raheem'),
  ('en.transliteration', 9, 129, 'Fa in tawallaw faqul lhasbiyal laahu laaa ilaaha illaa Huwa \'alaihi tawakkkaltu wa Huwa Rabbul \'Arshil \'Azeem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 9, 1, 'الله اور اس کے رسول کی طرف سے ان مشرکوں سے بیزاری ہے جن سے تم نے عہد کیا تھا'),
  ('ur.ahmedali', 9, 2, 'سو اس ملک میں چار مہینے پھر لو اور جان لو کہ تم الله کو عاجز نہیں کر سکوگے اور بے شک الله کافروں کو ذلیل کرنے والا ہے'),
  ('ur.ahmedali', 9, 3, 'اور اللہ اور اس کے رسول کی طرف سے بڑے حج کے دن لوگوں کو آگاہ کیا جاتا ہے کہ اللہ اور اس کا رسول مشرکوں سے بیزار ہیں پس اگر تم توبہ کرو تو تمہارے لئے بہتر ہے اور اگر نہ مانو تو جان لو کہ تم اللہ کو ہرگز عاجز کرنے والے نہیں اور کافروں کو درد ناک عذاب کی خوشخبری سنادو'),
  ('ur.ahmedali', 9, 4, 'مگر جن مشرکوں سے تم نے عہد کیا تھا پھر انہوں نے تمہارے ساتھ کوئی قصور نہیں کیا اور تمہارے مقابلے میں کسی کی مد نہیں کی سو ان سے ان کا عہد ان کی مدت تک پورا کر دو بے شک الله پرہیز گارو ں کو پسند کرتا ہے'),
  ('ur.ahmedali', 9, 5, 'پھر جب عزت والے مہینے گزر جائیں تو مشرکوں کو جہاں پاؤ قتل کر دو اور پکڑو اور انہیں گھیر لو اور ان کی تاک میں ہر جگہ بیٹھو پھر اگر وہ توبہ کریں اور نماز قائم کریں اور زکواة دیں تو ان کا راستہ چھوڑ دو بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 6, 'اور اگر کوئی مشرک تم سے پناہ مانگے تو اسے پناہ دے دو یہاں تک کہ الله کا کلام سنے پھر اسے اس کی امن کی جگہ پہنچا دو یہ اس لیے ہے کہ وہ لوگ بے سمجھ ہیں'),
  ('ur.ahmedali', 9, 7, 'بھلا مشرکوں کے لیے الله اور اس کے رسول کے ہاں عہدکیوں کر ہو سکتا ہے ہاں جن لوگوں کے ساتھ تم نے مسجد حرام کے نزدیک عہد کیا ہے اگر وہ قائم رہیں توتم بھی قائم رہو بے شک الله پرہیزگاروں کو پسند کرتا ہے'),
  ('ur.ahmedali', 9, 8, 'کیوں کر صلح ہو اور اگر وہ تم پر غلبہ پائیں تو نہ تمہاری قرابت کا لحاظ کریں اور نہ عہد کا تمہیں اپنی منہ کی باتوں سے راضی کرتے ہیں اور ان کے دل نہیں مانتے اور ان میں سے اکثر بد عہد ہیں'),
  ('ur.ahmedali', 9, 9, 'انہوں نے الله کی آیتوں کو تھوڑی قیمت پر بیچ ڈالا پھر الله کے راستے سے روکتے ہیں بے شک وہ برا ہے جو کچھ وہ کرتے ہیں'),
  ('ur.ahmedali', 9, 10, 'یہ لوگ کسی مومن کے حق میں نہ رشتہ داری کا خیال کرتے ہیں اور نہ عہد اور یہی لوگ حد سے گزرنے والے ہیں'),
  ('ur.ahmedali', 9, 11, 'اگر یہ توبہ کریں اور نماز قائم کریں اور زکواة دیں تو دین میں تمہارے بھائی ہیں اور ہم سمجھ داروں کے لیے کھول کھول کر احکام بیان کرتے ہیں'),
  ('ur.ahmedali', 9, 12, 'اور اگر وہ عہد کرنے کے بعد اپنی قسمیں تو ڑ دیں اور تمہارے دین میں عیب نکالیں تو کفر کے سرداروں سے لڑو ان کی قسموں کوئی اعتبار نہیں تاکہ وہ باز آ آئیں'),
  ('ur.ahmedali', 9, 13, 'خبردار! تم ایسے لوگوں سے کیوں نہ لڑو جنہوں نے اپنی قسموں کو توڑ ڈالا اور پیغمبر کو جلا وطن کرنے کا ارادہ کیا اور انہوں نے پہلے تم سے عہد شکنی کی کیا تم ان سے ڈرتے ہو الله زيادہ حق دار ہے کہ تم اس سے ڈرو اگر تم ایمان دار ہو'),
  ('ur.ahmedali', 9, 14, 'ان سے لڑو تاکہ الله انہیں تمہارے ہاتھوں سے عذاب دے اور انہیں ذلیل کرے اور تمہیں ان پر غلبہ دے اور مسلمانوں کے دلوں کو ٹھنڈا کرے'),
  ('ur.ahmedali', 9, 15, 'اور ان کے دلوں سے غصہ دور کر ے اور الله جسے چاہے توبہ نصیب کرے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 9, 16, 'کیا تم یہ خیال کرتے ہو کہ چھوڑ دیے جاؤ گے حالانکہ ابھی الله نے ایسے لوگو ں کو جدا ہی نہیں کیا جنہوں نے تم میں سے جہاد کیا اور الله اور اس کے رسول اورمومنوں کے سوا کسی کو دلی دوست نہیں بنایا اور الله تمہارے سب کاموں سے با خبر ہے'),
  ('ur.ahmedali', 9, 17, 'مشرکوں کا کام نہیں کہ الله کی مسجدیں آباد کریں جب کہ وہ اپنے آپ پر کفر کی گواہی دے رہے ہوں ان لوگوں کے سب اعمال بے کار ہیں اور وہ ہمیشہ آگ میں رہیں گے'),
  ('ur.ahmedali', 9, 18, 'الله کی مسجدیں وہی آباد کرتا ہے جو الله پر اور آخرت پر ایمان لایا اور نماز قائم کی اور زکواة دی اور الله کے سوا کسی سے نہ ڈرا سو وہ لوگ امیدوار ہیں کہ ہدایت والوں میں سے ہوں'),
  ('ur.ahmedali', 9, 19, 'کیا تم نے حاجیوں کا پانی پلانا اور مسجد حرام کا آباد کرنا اس کے برابر کر دیا جو الله پر اور آخرت کے دن پر ایمان لایا اور الله کی راہ میں لڑا الله کہ ہاں یہ برابر نہیں ہیں اور الله ظالم لوگوں کو راستہ نہیں دکھاتا'),
  ('ur.ahmedali', 9, 20, 'جو لوگ ایمان لائے اور گھر چھوڑے اور الله کی راہ میں اپنے مالوں اور جانوں سے لڑے الله کے ہاں ان کے لیے بڑا درجہ ہے اور وہی لوگ مراد پانے والے ہیں'),
  ('ur.ahmedali', 9, 21, 'انہیں ان کا رب اپنی طرف سے مہربانی اور رضا مندی اور باغوں کی خوشخبری دیتا ہے جن میں انہیں ہمیشہ آرام ہوگا'),
  ('ur.ahmedali', 9, 22, 'ان میں ہمیشہ رہیں گے بے شک الله کے ہاں بڑا ثواب ہے'),
  ('ur.ahmedali', 9, 23, 'اے ایمان والو! اپنے باپوں اور بھائیوں سے دوستی نہ رکھو اگر وہ ایمان پر کفر کو پسند کریں اور تم میں سے جو ان سے دوستی رکھے گا سو وہی لوگ ظالم ہیں'),
  ('ur.ahmedali', 9, 24, 'کہہ دے اگر تمہارے باپ اور بیٹے اور بھائی اوربیویاں اور برادری اور مال جو تم نے کمائے ہیں اور سوداگری جس کے بند ہونے سے تم ڈرتے ہو اور مکانات جنہیں تم پسند کر تے ہو تمہیں الله اور اس کے رسول اوراس کی راہ میں لڑنے سے زیادہ پیارے ہیں تو انتظار کرو یہاں تک کہ الله اپنا حکم بھیجے اور الله نافرمانوں کو راستہ نہیں دکھاتا'),
  ('ur.ahmedali', 9, 25, 'الله بہت سے میدانوں میں تمہاری مدد کر چکا ہے اور حنین کے دن جب تم اپنی کثرت پر خوش ہوئے پھر وہ تمہارے کچھ کام نہ آئی اور تم پر زمین باوجود اپنی فراخی کے تنگ ہو گئی پھر تم پیٹھ پھیر کر ہٹ گئے'),
  ('ur.ahmedali', 9, 26, 'پھر الله نے اپنی طرف سے اپنے رسول پر اور ایمان والوں پر تسکین نازل فرمائی اور وہ فوجیں اتاریں کہ جنہیں تم نے نہیں دیکھا اور کافروں کو عذاب دیا اور کافروں کو یہی سزا ہے'),
  ('ur.ahmedali', 9, 27, 'پھر اس کے بعد جسے الله چاہے تو بہ نصیب کرے گا اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 28, 'اے ایمان والو! مشرک تو پلید ہیں سو اس برس کے بعد مسجد حرام کے نزدیک نہ آنے پائیں اور اگر تم تنگدستی سے ڈرتے ہو تو آئندہ اگر الله چاہے تمہیں اپنے فضل سے غنسی کر دے گا بے شک الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 9, 29, 'ان لوگوں سے لڑو جو الله پر اور آخرت کے دن پر ایمان نہیں لاتے اور نہ اسے حرام جانتے ہیں جسے الله اور اس کے رسول نے حرام کیا ہے اور سچا دین قبول نہیں کرتے ان لوگوں میں سے جو اہلِ کتاب ہیں یہاں تک کہ ذلیل ہو کر اپنے ہاتھ سے جزیہ دیں'),
  ('ur.ahmedali', 9, 30, 'اور یہود کہتے ہیں کہ عزیر الله کا بیٹا ہے اور عیسائی کہتے ہیں مسیح الله کا بیٹا ہے یہ ان کی منہ کی باتیں ہیں وہ کافروں کی سی باتیں بنانے لگے ہیں جو ان سے پہلے گزرے ہیں الله انہیں ہلاک کرے یہ کدھر الٹے جا رہے ہیں'),
  ('ur.ahmedali', 9, 31, 'انہوں نے اپنے عالموں اور درویشوں کو الله کے سوا خدا بنا لیا ہے اور مسیح مریم کے بیٹےکو بھی حالانکہ انہیں حکم یہی ہوا تھا کہ ایک الله کے سوا کسی کی عبادت نہ کریں اس کے سوا کوئی معبود نہیں وہ ان لوگوں کے شریک مقرر کرنے سے پاک ہے'),
  ('ur.ahmedali', 9, 32, 'چاہتے ہیں کہ الله کی روشنی کو اپنے مونہوں سے بجھا دیں الله اپنی روشنی کو پورا کیے بغیر نہیں رہے گا اور اگرچہ کافر ناپسند ہی کریں'),
  ('ur.ahmedali', 9, 33, 'اس نے اپنے رسول کو ہدایت اور سچا دین دے کر بھیجا ہے تاکہ اسے سب دینوں پر غالب کرے اور اگرچہ مشرک نا پسندکریں'),
  ('ur.ahmedali', 9, 34, 'اے ایمان والو! بہت سے عالم اور فقیر لوگوں کا مال ناحق کھاتے ہیں اور الله کی راہ سے روکتے ہیں اور جو لوگ سونا اورچاندی جمع کرتے ہیں اور اسے الله کی راہ میں خرچ نہیں کرتے انہیں دردناک عذاب کی خوشخبری سنا دیجیئے'),
  ('ur.ahmedali', 9, 35, 'جس دن وہ دوزخ کی آگ میں گرم کیا جائے گا پھر اس سے ان کی پیشانیاں اور پہلو اور پیٹھیں داغی جائیں گی یہ وہی ہے جو تم نے اپنے لیے جمع کیا تھا سو اس کا مزہ چکھو جوتم جمع کرتے تھے'),
  ('ur.ahmedali', 9, 36, 'بے شک الله کے ہاں مہینوں کی گنتی بارہ مہینے ہیں الله کی کتاب میں جس دن سے الله نے زمین اور آسمان پیدا کیے ان میں سے چار عزت والے ہیں یہی سیدھا دین ہے سو ان میں اپنے اوپر ظلم نہ کرو اور تم سب مشرکوں سے لڑو جیسے وہ سب تم سے لڑتے ہیں اور جان لو کہ الله پرہیزگاروں کے ساتھ ہے'),
  ('ur.ahmedali', 9, 37, 'یہ مہینوں کا ہٹا دینا کفر میں اور ترقی ہے اس سے کا فر گمراہی میں پڑتے ہیں اس مہینے کو ایک برس تو حلال کر لیتے ہیں اور دوسرے برس اسے حرام رکھتے ہیں تاکہ ان بارہ مہینوں کی گنتی پوری کر لیں جنہیں الله نے عزت دی ہے پھر حلا ل کر لیتے ہیں جو الله نے حرام کیا ہے ان کے برے اعمال انھیں بھلے دکھائی دیتے ہیں اور الله کافروں کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 9, 38, 'اے ایمان والو تمہیں کیا ہوا جب تمہیں کہا جاتا ہے کہ الله کی راہ میں کوچ کرو تو زمین پر گرے جاتے ہو کیا تم آخرت کو چھوڑ کر دنیا کی زندگی پر خوش ہو گئے ہو دنیا کی زندگی کا فائدہ تو آخرت کے مقابلہ میں بہت ہی کم ہے'),
  ('ur.ahmedali', 9, 39, 'اگر تم نہ نکلو گے تو الله تمہیں دردناک عذاب میں مبتلا کر ے گا اور تمہاری جگہ اور لوگ پیدا کر ے گا اور تم اسے کوئی نقصان نہیں پہنچا سکو گے اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 9, 40, 'اگرتم رسول کی مدد نہ کرو گے تو اس کی الله نے مدد کی ہے جس وقت اسے کافروں نے نکالا تھا کہ وہ دو میں سے دوسرا تھاجب وہ دونوں غار میں تھے جب وہ اپنے ساتھی سے کہہ رہا تھا تو غم نہ کھا بے شک الله ہمارے ساتھ ہے پھر الله نے اپنی طرف سے اس پر تسکین اتاری اور اس کی مدد کو وہ فوجیں بھیجیں جنہیں تم نے نہیں دیکھا اورکافروں کی بات کو پست کر دیا اور بات تو الله ہی کی بلند ہے اور الله زبردست (اور) حکمت والا ہے'),
  ('ur.ahmedali', 9, 41, 'تم ہلکے ہو یا بوجھل نکلو اور اپنے مالوں اور جانوں سے الله کی راہ میں لڑو یہ تمہارے حق میں بہتر ہے اگر تم سمجھتے ہو'),
  ('ur.ahmedali', 9, 42, 'اگر مال نزدیک ہوتا اور سفر ہلکا ہوتا تو وہ ضرور تیرے ساتھ ہوتے لیکن انہیں مسافت لمبی نظر آئی اور اب الله کی قسمیں کھائیں گے کہ اگر ہم سے ہو سکتا تو ہم تمہارے ساتھ ضرور چلتے اپنی جانوں کو ہلاک کرتے ہیں اور الله جانتا ہے کہ وہ جھوٹے ہیں'),
  ('ur.ahmedali', 9, 43, 'الله نے تمہیں معاف کر دیا تم نےانہیں کیوں رخصت دی یہاں تک کہ تیرے لیے سچے ظاہر ہو جاتے اور تو جھوٹوں کو جان لیتا'),
  ('ur.ahmedali', 9, 44, 'جو لوگ الله پر اور آخرت کے دن پر ایمان لاتے ہیں وہ تم سے رخصت نہیں مانگتے اس سے کہ اپنے مالوں اورجانوں سے جہاد کریں اور الله پرہیزگاروں کو خوب جانتا ہے'),
  ('ur.ahmedali', 9, 45, 'تم سے رخصت وہی مانگتے ہیں جو الله پر اور آخرت کے دن پر ایمان نہیں رکھتے اور ان کے دل شک میں پڑے ہوئے ہیں سو وہ اپنے شک میں بھٹک رہے ہیں'),
  ('ur.ahmedali', 9, 46, 'اور اگر وہ نکلنا چاہتے تو اس کے لیے کوئی سامان ضرور تیار کرتے لیکن الله نے ان کا اٹھنا پسند نہ کیا سو انہیں روک دیا اور حکم ہوا کہ بیٹھنے والوں کے ساتھ بیٹھے رہو'),
  ('ur.ahmedali', 9, 47, 'اگر وہ تم میں نکلتے تو سوائے فساد کے اور کچھ نہ بڑھاتے اور تم میں فساد ڈلوانے کی غرض سے دوڑے دوڑے پھرتے اورتم میں ان کے جاسوس بھی ہیں اور الله ظالموں کو خوب جانتا ہے'),
  ('ur.ahmedali', 9, 48, 'یہ پہلے بھی فساد کے طالب رہے ہیں اور بہت سی باتوں میں تمہارے لئےالٹ پھیر کرتے رہے ہیں یہاں تک کہ حق آ پہنچا اور الله کا حکم غالب ہوا اور وہ ناخوش ہی رہے'),
  ('ur.ahmedali', 9, 49, 'اور ان میں سے بعض کہتے ہیں کہ مجھے تو اجازت ہی دیجیئے اور فتنہ میں نہ ڈالیے خبردار! وہ فتنہ میں پڑ چکے ہیں اوربے شک دوزخ کافروں پر احاطہ کرنے والی ہے'),
  ('ur.ahmedali', 9, 50, 'اگر تمہیں آسائش حاصل ہوتی ہے تو انہیں بری لگتی ہے اور اگر کوئی مشکل پڑتی ہے تو کہتے ہیں کہ ہم نے تو اپنا کام پہلے ہی سنبھال لیا تھا اور خوشیاں مناتے لوٹ جاتے ہیں'),
  ('ur.ahmedali', 9, 51, 'کہہ دو ہمیں ہر گز نہ پہنچے گا مگر وہی جو الله نے ہمارے لیے لکھ دیا وہی ہمارا کارساز ہے اور الله ہی پر چاہیئے کہ مومن بھروسہ کریں'),
  ('ur.ahmedali', 9, 52, 'کہہ دو تم ہمارے حق میں دو بھلائیوں میں سے ایک کے منتظر ہو اور ہم تمہارے حق میں اس بات کے منتظر ہیں کہ الله اپنے ہاں سے تم پرکوئی عذاب نازل کرے یا ہمارے ہاتھوں سے تم بھی انتظار کرو ہم بھی تمہارے ساتھ انتظار کرتے ہیں'),
  ('ur.ahmedali', 9, 53, 'کہہ دو تم خوشی سے خر چ کرو یا ناخوشی سے تم سے ہرگز قبول نہیں کیا جائے گا بے شک تم نافرمان لوگ ہو'),
  ('ur.ahmedali', 9, 54, 'اور ان کے خر چ کے قبول ہونے سے کوئی چیز مانع نہیں ہوئی سوائے اس کے کہ انہوں نے الله اور اس کے رسول سے کفرکیا اورنماز میں سست ہو کر آتے ہیں اور ناخوش ہو کر خرچ کرتے ہیں'),
  ('ur.ahmedali', 9, 55, 'سو تو ان کے مال اور اولاد سے تعجب نہ کر الله یہی چاہتا ہے کہ ان چیزوں کی وجہ سے دنیا کی زندگی میں انہیں عذاب دے اور کفر کی حالت میں ان کی جانیں نکلیں'),
  ('ur.ahmedali', 9, 56, 'اور الله کی قسمیں کھاتے ہیں کہ وہ بے شک تم میں سے ہیں حالانکہ وہ تم میں سے نہیں لیکن وہ ڈرتے ہیں'),
  ('ur.ahmedali', 9, 57, 'اگر وہ کوئی پناہ کی جگہ یا غاریا گھسنے کی جگہ پائیں تو دوڑتے ہوئے ادھر جائیں'),
  ('ur.ahmedali', 9, 58, 'اور بعضے ان میں سے وہ ہیں جو خیرات مانگتے ہیں تجھے طعن دیتے ہیں سو اگر انہیں اس میں سے مل جائے تو راضی ہوتے ہیں اور اگر نہ ملے تو فوراً ناراض ہو جاتے ہیں'),
  ('ur.ahmedali', 9, 59, 'اور کیا اچھا ہوتا اگر وہ اس پر راضی ہو جاتے جو انہیں الله اور اس کے رسول نے دیا ہے اور کہتے ہیں ہمیں الله کافی ہے وہ ہمیں اپنے فضل سے دے گا اور اس کا رسول ہم الله ہی کی طرف رغبت کرنے والے ہیں'),
  ('ur.ahmedali', 9, 60, 'زکوة مفلسوں اور محتاجوں اوراس کا کام کرنے والوں کا حق ہے اورجن کی دلجوئی کرنی ہے اور غلاموں کی گردن چھوڑانے میں اور قرض داروں کے قرض میں اور الله کی راہ میں اورمسافر کو یہ الله کی طرف سے مقرر کیاہوا ہے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 9, 61, 'اور بعضے ان میں سے پیغمبر کو ایذا دیتے ہیں اور کہتے ہیں کہ یہ شخص نِرا کان ہے کہہ دے وہ کان تمہاری بھلائی کے لیے ہے الله پر یقین رکھتا ہے اور مسلمانوں کی بات کا یقین کرتا ہے اور تم میں سے ایمان والوں کے حق میں رحمت ہے اور جو لوگ رسول الله کو ایذا دیتے ہیں ان کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 9, 62, 'تمہارے سامنے الله کی قسمیں کھاتے ہیں تاکہ تمہیں راضی کریں اور الله اور اس کے رسول کو راضی کرنا بہت ضروری ہے اگر وہ ایمان رکھتے ہیں'),
  ('ur.ahmedali', 9, 63, 'کیا وہ نہیں جانتے کہ جو شخص الله اور اس کے رسول کا مقابلہ کرتا ہے تو اس کے واسطے دوزخ کی آگ ہے اس میں ہمیشہ رہے گا یہ بڑی ذلت ہے'),
  ('ur.ahmedali', 9, 64, 'منافق اس بات سے ڈرتے ہیں کہ مسلمانوں پر کوئی ایسی سورة نازل ہو کہ انہیں بتا دے جو منافقوں کے دل میں ہے کہہ دو ہنسی کیے جاؤ جس بات سے تم ڈرتے ہو الله اسے ضرور ظاہر کر دے گا'),
  ('ur.ahmedali', 9, 65, 'اور اگر تم ان سے دریافت کرو تو کہیں گے کہ ہم یونہی بات چیت اور دل لگی کر رہے تھےکہہ دو کیا الله سے اور اس کی آیتوں سے اور اس کے رسول سے تم ہنسی کرتے تھے'),
  ('ur.ahmedali', 9, 66, 'بہانے مت بناؤ ایمان لانے کے بعد تم کافر ہو گئے اگر ہم تم میں سے بعض کو معاف کر دیں گے تو بعض کو عذاب بھی دیں گے کیوں کہ وہ گناہ کرتے رہے ہیں'),
  ('ur.ahmedali', 9, 67, 'منافق مر د اور منافق عورتیں ایک دوسرے کے ہم جنس ہیں برے کامو ں کا حکم کرتے ہیں اور نیک کاموں سے منع کرتے ہیں او رہاتھ بند کیے رہتے ہیں وہ الله کو بھول گئے سوالله نے انہیں بھلا دیا بے شک منافق وہی نافرمان ہیں'),
  ('ur.ahmedali', 9, 68, 'الله نے منافق مردوں اورمنافق عورتوں اور کافروں کو دوزخ کی آگ کا وعدہ دیا ہے پڑے رہیں گے اس میں وہی انہیں کافی ہے اور الله نے ان پر لعنت کی ہے اوران کے لیے دائمی عذاب ہے'),
  ('ur.ahmedali', 9, 69, 'جس طرح تم سے پہلے لوگ تم سے طاقت میں زيادہ تھے اور مال اور اولاد میں بھی زيادہ تھے پھر وہ اپنے حصہ سے فائدہ اٹھا گئے اور تم نے اپنے حصہ سے فائدہ اٹھایا جیسے تم سے پہلہے لوگ اپنے حصہ سے فائدہ اٹھا گئے اور تم بھی انہیں کی سی چال چلتے ہو یہ وہ لوگ ہیں جن کے اعمال دنیا اور آخرت میں ضائع ہو گئے اور وہی نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 9, 70, 'کیا انہیں ان لوگو ں کی خبر نہیں پہنچی جو ان سے پہلے تھے نوح کی قوم اور عاد اور ثمود اورابراھیم کی قوم اورمدین والوں کی اوران بستیوں کی خبر جو الٹ دی گئی تھیں ان کے پاس ان کے رسول صاف احکام لے کر پہنچے سو الله ایسا نہ تھا کہ ان پر ظلم کرتا لیکن وہی اپنے آپ پر ظلم کرتے تھے'),
  ('ur.ahmedali', 9, 71, 'اور ایمان والے مرد اور ایمان والی عورتیں ایک دوسرے کےمددگار ہیں نیکی کا حکم کرتے ہیں اوربرائی سے روکتے ہیں اورنماز قائم کرتے ہیں اور زکواة دیتے ہیں اور الله اور اس کے رسول کی فرمانبرداری کرتے ہیں یہی لوگ ہیں جن پر الله رحم کرے گا بے شک الله زبردست حکمت والا ہے'),
  ('ur.ahmedali', 9, 72, 'الله نے ایمان دار مردوں اورایمان والی عورتوں کو باغوں کا وعدہ دیا ہے جن کے نیچے نہریں بہتی ہوں گیان میں ہمیشہ رہنے والے ہوں گے اورعمدہ مکانوں اور ہمیشگی کے باغوں میں اور الله کی رضا ان سب سے بڑی ہے یہی وہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 9, 73, 'اے نبی! کافروں اور منافقوں سے لڑائی کر اوران پر سختی کر اور ان کا ٹھکانا دوزخ ہے اور وہ بری جگہ ہے'),
  ('ur.ahmedali', 9, 74, 'الله کی قسمیں کھاتے ہیں کہ ہم نے نہیں کہا اوربے شک انہوں نے کفر کا کلمہ کہا ہے اورمسلمان ہونے کے بعد کافر ہوگئے اورانہوں نے قصد کیا تھا ایسی چیز کا جونہیں پا سکے اور یہ سب کچھ اسی کا بدلہ تھا کہ انہیں الله اور اس کے رسول نے اپنے فضل سے دولتمند کر دیا ہے سو اگر وہ توبہ کریں تو ان کے لیے بہتر ہے اور اگر وہ منہ پھیر لیں تو الله انہیں دنیا اور آخرت میں دردناک عذاب دے گا اور انہیں روئے زمین پر کوئی دوست اور کوئی مددگار نہیں ملے گا'),
  ('ur.ahmedali', 9, 75, 'اور بعضے ان میں سے وہ ہیں جنہوں نے الله سے عہد کیا تھا کہ اگر وہ ہمیں اپنے فضل سے دے تو ہم ضرور خیرات کیا کریں گے اور نیکو ں میں سےہو جائیں'),
  ('ur.ahmedali', 9, 76, 'پھر جب الله نے اپنے فضل سے دیا تو اس میں بخل کرنے لگے اورمنہ موڑ کر پھر بیٹھے'),
  ('ur.ahmedali', 9, 77, 'تو نتیجہ یہ ہوا کہ اس دن تک الله سے ملیں گے الله نے ان کے دلوں میں نفاق پیدا کر دیا اس لیے کہ انہوں نے جو الله سے وعدہ کیا تھا اسے پورا نہ کیا اوروہ اس لیے جھوٹ بولا کرتے تھے'),
  ('ur.ahmedali', 9, 78, 'کیا وہ نہیں جانتے کہ الله ان کا بھید اور ان کا مشورہ جانتا ہے اوریہ کہ الله غیب کی باتیں جاننے والا ہے'),
  ('ur.ahmedali', 9, 79, 'وہ لوگ جو ان مسلمانوں پر طعن کرتے ہیں جودل کھول کر خیرات کرتے ہیں اور جو لوگ اپنی محنت کے سوا طاقت نہیں رکھتے پھر ان پر ٹھٹھا کرتے ہیں الله ان سے ٹھٹھا کرتا ہے اوران کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 9, 80, 'تو ان کے لیے بخشش مانگ یا نہ مانگ اگر تو ان کے لیے ستر دفعہ بھی بخشش مانگے گا تو بھی الله انہیں ہر گز نہیں بخشے گا یہ اس لیے کہ انہوں نے الله اور اس کے رسول سےکفر کیا اور الله نافرمانوں کو راستہ نہیں دکھاتا'),
  ('ur.ahmedali', 9, 81, 'جو لوگ پیچھے رہ گئے وہ رسول الله کی مرضی کے خلاف بیٹھ رہنے سے خوش ہوتے ہیں اوراس بات کو ناپسند کیا کہ اپنے مالوں اور جانوں سے الله کی راہ میں جہاد کریں اور کہا گرمی میں مت نکلو کہہ دو کہ دوزخ کی آگ کہیں زیادہ گرم ہے کاش یہ سمجھ سکتے'),
  ('ur.ahmedali', 9, 82, 'سووہ تھوڑا سا ہنسیں اور زیادہ روئیں ان کے اعمال کے بدلے جو کرتے رہے ہیں'),
  ('ur.ahmedali', 9, 83, 'سواگر تجھے الله ان میں سے کسی فرقہ کی طرف پھر لے جائے پھر تجھ سے نکلنے کی اجازت چاہیں تو کہہ دو کہ تم میرے ساتھ کبھی بھی ہرگز نہ نکلو گے اور میرے ساتھ ہو کر کسی دشمن سے نہ لڑو گے تمہیں پہلی مرتبہ بیٹھنا پسند آیا سو پیچھے رہنے والوں کے ساتھ بیٹھے رہو'),
  ('ur.ahmedali', 9, 84, 'اوران میں سے جو مرجائے کسی پر کبھی نماز نہ پڑھ اور نہ اس کی قبر پر کھڑا ہو بے شک انہوں نے الله اور اس کے رسول سے کفر کیا اور نافرمانی کی حالت میں مر گئے'),
  ('ur.ahmedali', 9, 85, 'اور ان کے مالوں اوراولاد سے تعجب نہ کر الله یہی چاہتا ہے کہ انہیں ان چیزوں کے باعث دنیا میں عذاب دے اور ان کی جانیں نکلیں ایسے حال میں کہ وہ کافر ہی ہوں'),
  ('ur.ahmedali', 9, 86, 'اور جب کوئی سورة نازل ہوتی ہے کہ الله پر ایمان لاؤ اور اس کے رسول کےساتھ ہو کر جہاد کرو تو ان میں سے دولت مند بھی تجھ سے رخصت مانگتے ہیں اورکہتے ہیں کہ ہمیں چھوڑ دے کہ بیٹھنے والوں کے ساتھ ہو جائیں'),
  ('ur.ahmedali', 9, 87, 'وہ خوش ہیں کہ پیچھے رہ جانے والی عورتوں کے ساتھ رہ جائیں اور ان کے دلوں پر مہر کر دی گئی ہے سووہ نہیں سمجھتے'),
  ('ur.ahmedali', 9, 88, 'لیکن رسول اور جو لوگ ان کے ساتھ ایمان والے ہیں وہ اپنے مالوں اور جانوں سے جہاد کرتے ہیں اور انہیں لوگو ں کے لیے بھلائیاں ہیں اور وہی نجات پانے والے ہیں'),
  ('ur.ahmedali', 9, 89, 'الله نے ان کے لیے باغ تیار کیے ہیں جن کے نیچے نہریں بہتی ہیں ان میں ہمیشہ رہیں گےیہی بڑی کامیابی ہے'),
  ('ur.ahmedali', 9, 90, 'اور بہانے کرنے والے گنوار آئے تاکہ انہیں رخصت مل جائے اوربیٹھ رہے وہ جنہوں نے الله اوراس کے رسول سے جھوٹ بولا تھا جو ان میں سے کافر ہیں عنقریب انہیں دردناک عذاب پہنچے گا'),
  ('ur.ahmedali', 9, 91, 'ضعیفوں اور مریضوں پر اور ان لوگوں پر جو نہیں پاتے جو خر چ کریں کوئی گناہ نہیں ہے جب الله اور اس کے رسول کے ساتھ خیر خواہی کریں نیکو کاروں پر کوئی الزام نہیں ہے اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 92, 'اور ان لوگو ں پر بھی کوئی گناہ نہیں کہ جب وہ تیرے پاس آئیں کہ انہیں سواری دے تو نے کہا میرے پاس کوئی چیز نہیں کہ تمہیں اس پر سوار کر دوں تو وہ لوٹ گئے اوراس غم سے کہ ان کے پاس خرچ موجود نہیں تھا ان کی آنکھوں سے آنسو بہہ رہے تھے'),
  ('ur.ahmedali', 9, 93, 'الزام ان لوگوں پر ہے جو دولتمند ہیں اورتم سے اجازت طلب کرتے ہیں اس بات سے وہ خوش ہیں کہ پیچھے رہنے والیوں کے ساتھ رہ جائیں اور الله نے ان کے دلوں پر مہر کر دی ہے پس وہ نہیں سمجھتے'),
  ('ur.ahmedali', 9, 94, 'جب تم ان کی طرف واپس جاؤ گے تو تم سے عذر کریں گے کہہ دو عذر مت کرو ہم تمہاری بات ہرگز نہیں مانیں گے تمہارے سب حالات اللہ ہمیں بتاچکا ہے اور ابھی الله اور اس کا رسول تمہارے کام کو دیکھے گا پھر تم غائب اور حاضر کے جاننے والےکی طرف لوٹائے جاؤ گے سو وہ تمہیں بتا دے گا جو تم کر رہے تھے'),
  ('ur.ahmedali', 9, 95, 'جب تم ان کی طرف پھر جاؤ گے تو تمہارے سامنے الله کی قسمیں کھائیں گےتاکہ تم ان سے در گزر کرو بے شک وہ پلید ہیں اور جو کام کرتے رہے ہیں ان کے بدلے ان کا ٹھکانا دوزخ ہے'),
  ('ur.ahmedali', 9, 96, 'وہ لوگ تمہارے سامنے قسمیں کھائیں گے تاکہ تم ان سے خوش ہو جاؤ اگر تم ان سے خوش بھی ہو جاؤ تو بھی الله نافرمانوں سے خوش نہیں ہوتا'),
  ('ur.ahmedali', 9, 97, 'گنوار کفر اور نفاق میں بہت سخت ہیں اور اس قابل ہیں کہ جو احکام الله نے اپنے رسول پر نازل فرمائے ہیں ان سے واقف نہ ہوں اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 9, 98, 'اور بعض گنوار ایسے ہیں کہ جو کچھ خرچ کرتے ہیں اسے تاوان سمجھتے ہیں اور تم پر زمانہ کی گردشوں کا انتظار کرتے ہیں انہیں پر بری گردش آئے اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 9, 99, 'اور بعضے گنوار ایسے ہیں کہ الله پر اور قیامت کے دن پر ایمان لاتے ہیں اور جو کچھ خرچ کرتے ہیں اسے الله کے نزدیک ہونے اور پیغمبر کی دعاؤں کا ذریعہ سمجھتے ہیں خبردار بے شک وہ ان کے لیے نزدیکی کا سبب ہے عنقریب انہیں اللہ اپنی رحمت میں داخل کرے گا بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 100, 'اور جو لوگ قدیم میں پہلے ہجرت کرنے والوں اور مدد دینے والو ں میں سے اور وہ لوگ جو نیکی میں ان کی پیروی کرنے والے ہیں الله ان سے راضی ہوئےاوروہ اس سے راضی ہوئےان کے لیے ایسے باغ تیار کیے ہیں جن کے نیچے نہریں بہتی ہیں ان میں ہمیشہ رہیں گے یہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 9, 101, 'اور تمہارے گرد و نواح کے بعضے گنوار منافق ہیں اور بعض مدینہ والے بھی نفاق پر اڑے ہوئے ہیں تم انہیں نہیں جانتے ہم انہیں جانتے ہیں ہم انہیں دوہری سزا دیں گے پھر وہ بڑے عذاب کی طرف لوٹائے جائیں گے'),
  ('ur.ahmedali', 9, 102, 'اور کچھ اور بھی ہیں کہ انھوں نے اپنے گناہوں کا اقرار کیا ہے انہوں نے اپنے نیک اور بد کاموں کو ملا دیاہے قریب ہے کہ الله انہیں معاف کر دے بے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 103, 'ان کے مالوں میں سے زکواة لے کہ اس سے ان کے ظاہر کو پاک اور ان کے باطن کو صاف کر دے اورانہیں دعا دے بے شک تیری دعا ان کے لیے تسکین ہے اوراللہ سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 9, 104, 'کیا یہ لوگ نہیں جانتے الله ہی اپنے بندوں کی توبہ قبول فرماتا ہے اور صدقات لیتا ہے اور بے شک الله ہی توبہ قبول کرنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 105, 'اور کہہ دےکہ کام کیے جاؤ پھر عنقریب الله اور اس کا رسول اور مسلمان تمہارے کام کو دیکھ لیں گے اور عنقریب تم غائب اور حاضر کے جاننے والے کی طرف لوٹائے جاؤ گےپھر وہ تمہیں بتا دے گا جو کچھ تم کرتے تھے'),
  ('ur.ahmedali', 9, 106, 'اور کچھ اور لوگ ہیں جن کا کام الله کے حکم پر موقوف ہے خواہ انہیں عذاب دے یا انہیں معاف کر دے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 9, 107, 'اور جنہوں نے نقصان پہنچانے اور کفر کرنے اورمسلمانوں میں تفریق ڈالنے کے لیے مسجد بنائی ہے اورواسطے گھات لگانے ان لوگوں کے جو الله اور اس کے رسول سے پہلے لڑ چکے ہیں اور البتہ قسمیں کھائیں گہ ہمارا مقصد تو صرف بھلائی تھی اور اللهگواہی دیتا ہے کہ بے شک وہ جھوٹے ہیں'),
  ('ur.ahmedali', 9, 108, 'تو اس میں کبھی کھڑانہ ہو البتہ وہ مسجد جس کی بنیاد پہلے دن سے پرہیزگاری پر رکھی گئی ہے وہ اس کے قابل ہے تو اس میں کھڑا ہو اس میں ایسے لوگ ہیں جو پاک رہنے کو پسند کرتے ہیں اور الله پاک رہنے والوں کو پسند کرتا ہے'),
  ('ur.ahmedali', 9, 109, 'بھلا جس نے اپنی عمارت کی بنیاد الله سے ڈرنے اوراس کی رضا مندی پر رکھی ہو وہ بہتر ہے یا جس نے اپنی عمارت کی بنیاد ایک کھائی کے کنارے پررکھی جو گرنے والی ہے پھر وہ اسے دوزخ کی آگ میں لے گری اور الله ظالموں کو راہ نہیں دکھاتا'),
  ('ur.ahmedali', 9, 110, 'جوعمارت انہوں نے بنائی ہے ہمیشہ ان کے دلو ں میں کھٹکتی رہے گی مگر جب ان کے دل ٹکڑے ہوجائیں اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 9, 111, 'بے شک الله مسلمانوں سے ان کی جان اوران کا مال اس قیمت پر خرید لیے ہیں کہ ان کی جنت ہے الله کی راہ میں لڑتے ہیں پھر قتل کرتے ہیں اور قتل بھی کیے جاتے ہیں یہ توریت اور انجیل اور قرآن میں سچا وعدہ ہے جس کا پورا کرنااسے ضروری ہے اور الله سے زیادہ وعدہ پورا کرنے والا کون ہے جو سودا تم نے اس سے کیا ہے اس سے خوش رہو اور یہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 9, 112, 'توبہ کرنے والے عبادت کرنے والے شکر کرنے والے روزہ رکھنے والے رکوع کرنے والے سجدہ کرنے والے اچھے کاموں کا حکم کرنے والے بری باتوں سے روکنے والے الله کی حدوں کی حفاظت کرنے والے اور ایسے مومنو ں کو خوشخبری سنا دے'),
  ('ur.ahmedali', 9, 113, 'پیغمبراور مسلمانوں کو یہ بات مناسب نہیں کہ مشرکوں کے لیے بخشش کی دعا کریں اگرچہ وہ رشتہ دار ہی ہوں جب کہ ان پر ظاہر ہو گیا ہے کہ وہ دوزخی ہیں'),
  ('ur.ahmedali', 9, 114, 'اور ابراھیم کا اپنے باپ کے لیے بخشش کی دعا کرنا اور ایک وعدہ کے سبب سے تھا جو وہ اس سے کر چکے تھے پھر جب انہیں معلوم ہوا کہ وہ الله کا دشمن ہے تو اس سے بیزار ہو گئے بے شک ابراھیم بڑے نرم دل تحمل والے تھے'),
  ('ur.ahmedali', 9, 115, 'اورالله ایسا نہیں ہے کہ کسی قوم کو صحیح راستہ بتلانے کے بعد گمراہ کر دے جب تک ان پر واضح نہ کر دے وہ چیز جس سے انہیں بچنا چاہیے بے شک الله ہر چیز کو جاننے والا ہے'),
  ('ur.ahmedali', 9, 116, 'آسمانوں اور زمین میں الله ہی کی سلطنت ہے وہی جلاتا ہے اور مارتا ہے اور الله کے سوا تمہارا کوئی دوست اور مددگار نہیں'),
  ('ur.ahmedali', 9, 117, 'الله نے نبی کے حال پر رحمت سے توجہ فرمائی اور مہاجرین اور انصار کے حال پر بھی جنہوں نے ایسی تنگی کے وقت میں نبی کا ساتھ دیا بعد اس کے کہ ان میں سے بعض کے دل پھر جانے کے قریب تھے اپنی رحمت سے ان پر توجہ فرمائی بے شک وہ ان پر شفقت کرنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 118, 'اور ان تینوں پر بھی جن کا معاملہ ملتوی کیا گیا یہاں تک کہ جب ان پر زمین باوجود کشادہ ہونے کے تنگ ہوگئی اور ان کی جانیں بھی ان پر تنگ ہوگئیں اور انہوں نے سمجھ لیا کہ الله سے کوئی پناہ نہیں سو اسی کی طرف آنے کے پھر بھی اپنی رحمت سے ان پر متوجہ ہوا تاکہ وہ توبہ کریں بے شک الله توبہ قبول کرنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 119, 'اے ایمان والو! الله سے ڈرتے رہو اور سچوں کے ساتھ رہو'),
  ('ur.ahmedali', 9, 120, 'مدینہ والوں اور ان کے آس پاس دیہات کے رہنے والوں کو یہ مناسب نہیں تھا کہ الله کے رسول سے پیچھے رہ جائیں اور نہ یہ کہ اپنی جانوں کو اس کی جان سے زیادہ عزیز سمجھیں یہ اس لیے ہے کہ انہیں الله کی راہ میں جو تکلیف پہنچتی ہے پیاس کی یا ماندگی کی یا بھوک کی یاہ وہ ایسی جگہ چلتے ہیں جو کافروں کے غصہ کو بھڑکائے اور یا کافروں سے کوئی چیز چھین لیتے ہیں ہر بات پر ان کے لیے عمل صالح لکھا جاتا ہے بے شک الله نیکی کرنے والوں کا اجر ضائع نہیں کرتا'),
  ('ur.ahmedali', 9, 121, 'اور جو وہ تھوڑا یا بہت خرچ کرتے ہیں یا کوئی میدان طے کرتے ہیں تو یہ سب کچھ ان کے لیے لکھ لیا جاتا ہے تاکہ الله انہیں ان کے اعمال کا اچھا بدلہ دے'),
  ('ur.ahmedali', 9, 122, 'اورایسا تو نہیں ہوسکتا کہ مسلمان سب کے سب کوچ کریں سو کیوں نہ نکلا ہر فرقے میں سے ایک حصہ تاکہ دین میں سمجھ پیدا کریں اور جب اپنی قوم کی طرف واپس آئیں تو ان کو ڈرائیں تاکہ وہ بچتے رہیں'),
  ('ur.ahmedali', 9, 123, 'اے ایمان والو اپنے نزدیک کے کافروں سے لڑو اور چاہئے کہ وہ تم میں سختی پائیں اور جان لو کہ اللہ پر ہیزگاروں کے ساتھ ہے'),
  ('ur.ahmedali', 9, 124, 'اور جب کوئی سورت نازل ہوتی ہے تو ان میں سے بعض کہتے ہیں کہ اس سورت نےتم میں سے کس کے ایمان کو بڑھایا ہے سو جو لوگ ایمان والے ہیں اس سورت نے ان کے ایمان کو بڑھایا ہے اور وہ خوش ہوتے ہیں'),
  ('ur.ahmedali', 9, 125, 'اور جن کے دلوں میں مرض ہے سوان کے حق میں نجاست پر نجاست بڑھا دی اور وہ مرتے دم تک کافر ہی رہے'),
  ('ur.ahmedali', 9, 126, 'کیا وہ نہیں دیکھتے کہ وہ ہر سال میں ایک دفعہ یا دو دفعہ آزمائے جاتے ہیں پھر بھی توبہ نہیں کرتے اور نہ نصیحت حاصل کرتے ہیں'),
  ('ur.ahmedali', 9, 127, 'اورجب کوئی سورت نازل ہوتی ہے تو ان میں ایک دوسرے کی طرف دیکھنے لگتا ہے کہ کیا تمہیں کوئی مسلمان دیکھتا ہے پھر چل نکلتے ہیں الله نے ان کے دل پھیر دئے ہیں اور لیے کہ وہ لوگ سمجھ نہیں رکھتے'),
  ('ur.ahmedali', 9, 128, 'البتہ تحقیق تمہارے پاس تم ہی میں سے رسول آیا ہے اسے تمہاری تکلیف گراں معلوم ہوتی ہے تمہاری بھلائی پر وہ حریص ہے مومنوں پر نہایت شفقت کرنے والا مہربان ہے'),
  ('ur.ahmedali', 9, 129, 'پھر اگر یہ لوگ پھر جائیں تو کہہ دو مجھے الله ہی کافی ہے اس کے سوا اور کوئی معبود نہیں اسی پر میں بھروسہ کرتا ہوں اور وہی عرش عظیم کا مالک ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 9, 1, 'Allah\'tan ve Peygamberinden, kendileriyle andlaşma yaptığınız müşriklere ihtardır: Yeryüzünde dört ay daha dolaşabilirsiniz. Allah\'ı aciz bırakamayacağınızı, Allah\'ın inkarcıları rezil edeceğini bilin.'),
  ('tr.diyanet', 9, 2, 'Allah\'tan ve Peygamberinden, kendileriyle andlaşma yaptığınız müşriklere ihtardır: Yeryüzünde dört ay daha dolaşabilirsiniz. Allah\'ı aciz bırakamayacağınızı, Allah\'ın inkarcıları rezil edeceğini bilin.'),
  ('tr.diyanet', 9, 3, 'Allah\'ın ve Peygamberinin, ortak koşanlardan uzak olduğunu, büyük hac günü, Allah ve peygamberi insanlara ilan eder. Eğer tevbe ederseniz, bu sizin için daha hayırlı olur, yüz çevirirseniz, bilin ki siz Allah\'ı aciz bırakamazsınız. İnkar edenlere can yakıcı azabı müjdele.'),
  ('tr.diyanet', 9, 4, 'Yalnız, andlaşma hükümlerinde size karşı bir eksiklik yapmayan ve aleyhinizde kimseye yardım etmeyen müşriklerle yaptığınız andlaşmaya sonuna kadar riayet edin. Allah sakınanları sever.'),
  ('tr.diyanet', 9, 5, 'Hürmetli aylar çıkınca, puta tapanları bulduğunuz yerde öldürün; onları yakalayıp hapsedin; her gözetleme yerinde onları bekleyin. Eğer tevbe eder, namaz kılar ve zekat verirlerse yollarını serbest bırakın. Doğrusu Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 9, 6, 'Puta tapanlardan biri sana sığınırsa, onu güvene al; ta ki Allah\'ın sözünü dinlesin. Sonra onu güven içinde olacağı yere ulaştır. Çünkü onlar bilgisiz bir topluluktur.'),
  ('tr.diyanet', 9, 7, 'Mescidi Haram\'ın yanında andlaştıklarınızın dışında, puta tapanların Allah katında ve Peygamberi önünde nasıl bir andlaşmaları olabilir. Size doğru davrandıkça siz de onlara doğru davranın. Allah, sözleşmelerini bozmaktan sakınanları sever.'),
  ('tr.diyanet', 9, 8, 'Nasıl olabilir ki, size üstün gelselerdi ne bir yakınlık, ne de bir ahd gözetirlerdi. Kalpleriyle istemezlerken sizi ağızlarıyla hoşnut etmeye uğraşırlar; çokları fasıktırlar.'),
  ('tr.diyanet', 9, 9, 'Allah\'ın ayetlerini az bir değere değişip, O\'nun yolundan alıkoydular. Onların işledikleri gerçekten ne kötüdür!'),
  ('tr.diyanet', 9, 10, 'Onlar hiçbir müminin yakınlık veya ahdini gözetmezler. İşte aşırı gidenler bunlardır.'),
  ('tr.diyanet', 9, 11, 'Eğer tevbe eder, namaz kılar ve zekat verirlerse, sizin din kardeşiniz olurlar. Bilen kimseler için ayetleri uzun uzadıya açıklıyoruz.'),
  ('tr.diyanet', 9, 12, 'Eğer andlaşmalarından sonra, yeminlerini bozarlar, dininize dil uzatırlarsa, inkarda önde gidenlerle savaşın, çünkü onların yeminleri sayılmaz, belki vazgeçerler.'),
  ('tr.diyanet', 9, 13, 'Yeminlerini bozan, Peygamberi sürgüne göndermeye azmeden bir toplumla savaşmanız gerekmez mi ki, önce onlar başlamışlardır? Onlardan korkar mısınız? Eğer inanıyorsanız bilin ki asıl korkmanız gereken Allah\'tır.'),
  ('tr.diyanet', 9, 14, 'Onlarla savaşın ki Allah sizin elinizle onları azablandırsın, rezil etsin ve sizi üstün getirsin de müminlerin gönüllerini ferahlandırsın, kalblerindeki öfkeyi gidersin. Allah dilediğinin tevbesini kabul eder. Allah Bilendir, Hakimdir.'),
  ('tr.diyanet', 9, 15, 'Onlarla savaşın ki Allah sizin elinizle onları azablandırsın, rezil etsin ve sizi üstün getirsin de müminlerin gönüllerini ferahlandırsın, kalblerindeki öfkeyi gidersin. Allah dilediğinin tevbesini kabul eder. Allah Bilendir, Hakimdir.'),
  ('tr.diyanet', 9, 16, 'Allah, içinizden cihat edenleri; Allah\'tan, peygamberinden ve inananlardan başka sırdaş edinmeyenleri ortaya çıkarmadan sizi kendi halinize bırakacak mı zannediyorsunuz? Allah işlediklerinizden haberdardır.'),
  ('tr.diyanet', 9, 17, 'Puta tapanların kendilerinin inkarcı olduklarını itiraf edip dururken Allah\'ın mescidlerini onarmaları gerekmez. Onların işledikleri boşa gitmiştir, cehennemde temelli kalacaklardır.'),
  ('tr.diyanet', 9, 18, 'Allah\'ın mescidlerini sadece, Allah\'a ve ahiret gününe inanan, namaz kılan, zekat veren ve ancak Allah\'tan korkan kimseler onarır. İşte onlar doğru yolda bulunanlardan olabilirler.'),
  ('tr.diyanet', 9, 19, 'Hacca gelenlere su vermeyi, Mescidi Haramı onarmayı, Allah\'a ve ahiret gününe inananla, Allah yolunda cihat edenle bir mi tuttunuz? Allah katında bir olmazlar; Allah zulmeden milleti doğru yola eriştirmez.'),
  ('tr.diyanet', 9, 20, 'İnanan, hicret eden ve Allah yolunda mallarıyla, canlarıyla cihat eden kimselere Allah katında en büyük dereceler vardır. İşte kurtulanlar onlardır.'),
  ('tr.diyanet', 9, 21, 'Rableri onlara katından bir rahmet, hoşnutluk ve içinde tükenmez nimetler bulunan cennetleri müjdeler. Doğrusu büyük ecir Allah katındadır.'),
  ('tr.diyanet', 9, 22, 'Rableri onlara katından bir rahmet, hoşnutluk ve içinde tükenmez nimetler bulunan cennetleri müjdeler. Doğrusu büyük ecir Allah katındadır.'),
  ('tr.diyanet', 9, 23, 'Ey inananlar! Babalarınızı, kardeşlerinizi küfrü imana tercih ediyorlarsa dost edinmeyin. Sizden onları kim dost edinirse doğrusu kendine yazık etmiş olurlar.'),
  ('tr.diyanet', 9, 24, 'De ki: "Babalarınız, oğullarınız, kardeşleriniz, eşleriniz, akrabanız, elde ettiğiniz mallar, durgun gitmesinden korktuğunuz ticaret, hoşunuza giden evler sizce Allah\'tan, Peygamberinden ve Allah yolunda savaşmaktan daha sevgili ise, Allah\'ın buyruğu gelene kadar bekleyin. Allah fasık kimseleri doğru yola eriştirmez."'),
  ('tr.diyanet', 9, 25, 'And olsun ki Allah size birçok yerlerde, ve çokluğunuzun sizi böbürlendirdiği fakat bir faydası da olmadığı, yeryüzünün geniş olmasına rağmen size dar gelip de bozularak arkanıza döndüğünüz Huneyn gününde yardım etmişti.'),
  ('tr.diyanet', 9, 26, 'Bozgundan sonra Allah, Peygamberine, müminlere güvenlik verdi ve görmediğiniz askerler indirdi; inkar edenleri azaba uğrattı. İnkarcıların cezası budur.'),
  ('tr.diyanet', 9, 27, 'Allah bundan sonra da dilediğinin tevbesini kabul eder. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 9, 28, 'Ey inananlar! Doğrusu puta tapanlar pistirler, bu sebeple, bu yıllardan sonra Mescidi Haram\'a yaklaşmasınlar. Eğer fakirlikten korkarsanız, bilin ki Allah dilerse sizi bol nimetiyle zenginleştirecektir. Allah şüphesiz bilendir, hakimdir.'),
  ('tr.diyanet', 9, 29, 'Kitap verilenlerden, Allah\'a, ahiret gününe inanmayan, Allah\'ın ve Peygamberinin haram kıldığını haram saymayan, hak dinini din edinmeyenlerle, boyunlarını büküp kendi elleriyle cizye verene kadar savaşın.'),
  ('tr.diyanet', 9, 30, 'Yahudiler, "Üzeyr Allah\'ın oğludur" dediler; Hıristiyanlar, "Mesih Allah\'ın oğludur" dediler. Bu, daha önce inkar edenlerin sözlerine benzeterek ağızlarında geveledikleri sözdür. Allah onları yok etsin, nasıl da uyduruyorlar!'),
  ('tr.diyanet', 9, 31, 'Onlar Allah\'ı bırakıp hahamlarını, papazlarını ve Meryem oğlu Mesih\'i rableri olarak kabul ettiler. Oysa tek Tanrı\'dan başkasına kulluk etmemekle emrolunmuşlardı. Ondan başka tanrı yoktur. Allah, koştukları eşlerden münezzehtir.'),
  ('tr.diyanet', 9, 32, 'Allah\'ın nurunu ağızlarıyla söndürmek isterler. Kafirler istemese de Allah nurunu mutlaka tamamlayacaktır.'),
  ('tr.diyanet', 9, 33, 'Puta tapanlar hoşlanmasa da, dinini bütün dinlerden üstün kılmak üzere, Peygamberini doğru yol ve hak dinle gönderen Allah\'tır.'),
  ('tr.diyanet', 9, 34, 'Ey inananlar! Hahamlar ve rahiplerin çoğu, insanların mallarını haksızlıkla yerler. Allah yolundan alıkoyarlar. Altın ve gümüşü biriktirip Allah yolunda sarf etmeyenlere can yakıcı bir azabı müjdele.'),
  ('tr.diyanet', 9, 35, 'Bunlar cehennem ateşinde kızdırıldığı gün, alınları, böğürleri ve sırtları onlarla dağlanacak, "Bu, kendiniz için biriktirdiğinizdir; biriktirdiğinizi tadın" denecek.'),
  ('tr.diyanet', 9, 36, 'Allah\'ın gökleri ve yeri yarattığı günkü yazısında, Allah\'a göre ayların sayısı onikidir. Bunlardan dördü hürmetli aydır. Bu dosdoğru bir nizamdır. Öyleyse o aylar içinde kendinize yazık etmeyin, topyekun sizinle savaşan putperestlerle siz de topyekun savaşın, Allah\'ın sakınanlarla beraber olduğunu bilin.'),
  ('tr.diyanet', 9, 37, 'Sapıtmak için hürmetli ayların yerlerini değiştirip geciktirmek, küfürde gerçekten ileri gitmekdir. İnkar edenler Allah\'ın haram kıldığı ayların sayısına uydurmak için, onu bir yıl haram, bir yıl helal sayıyor, böylece Allah\'ın haram kıldığını helalkılıyorlar. Kötü işleri kendilerine güzel göründü. Allah inkar eden toplumu doğru yola eriştirmez.'),
  ('tr.diyanet', 9, 38, 'Ey inananlar! Size ne oldu ki, "Allah yolunda, savaşa çıkın" dendiği zaman yere çöküp kaldınız? Oysa dünya hayatının geçimi ahirete göre pek az bir şeydir.'),
  ('tr.diyanet', 9, 39, 'Çıkmazsanız Allah size can yakıcı azabla azabeder ve yerinize başka bir millet getirir. O\'na bir şey de yapamazsınız. Allah her şeye kadirdir.'),
  ('tr.diyanet', 9, 40, 'Ona (Muhammed\'e) yardım etmezseniz, bilin ki, inkar edenler onu Mekke\'den çıkardıklarında mağarada bulunan iki kişiden biri olarak Allah ona yardım etmişti. Arkadaşına (Ebu Bekir\'e) "Üzülme, Allah bizimledir" diyordu; Allah da ona güven vermiş, görmediğiniz askerlerle onu desteklemiş, inkar edenlerin sözünü alçaltmıştı. Ancak Allah\'ın sözü yücedir. Allah güçlüdür, hakimdir.'),
  ('tr.diyanet', 9, 41, 'İsteyen, istemeyen, hepiniz savaşa çıkın. Allah yolunda mallarınızla, canlarınızla cihat edin. Bilirseniz bu sizin için hayırlıdır.'),
  ('tr.diyanet', 9, 42, 'Kolay bir kazanç, normal bir yolculuk olsaydı sana uyarlardı, fakat çıkılacak yol onlara uzak geldi, kendilerini helak ederek, "Gücümüz yetseydi sizinle beraber çıkardık" diye Allah\'a yemin edeceklerdir. Allah, onların yalancı olduğunu elbette biliyor.'),
  ('tr.diyanet', 9, 43, 'Allah seni affetsin; doğrular sana belli olup, yalancıları bilmeden önce, niçin onlara izin verdin?'),
  ('tr.diyanet', 9, 44, 'Allah\'a ve ahiret gününe inananlar, mallariyle, canlariyle savaşmak istediklerinden ötürü geri kalmak için senden izin istemezler. Allah sakınanları bilir.'),
  ('tr.diyanet', 9, 45, 'Ancak Allah\'a ve ahiret gününe inanmayan, kalbleri şüpheye düşüp şüphelerinde bocalayan kimseler senden izin isterler.'),
  ('tr.diyanet', 9, 46, 'Eğer savaşa çıkmak isteselerdi bir hazırlık yaparlardı. Ama Allah davranışlarını beğenmedi de onları alıkoydu. "Acizlerle beraber oturun" denildi.'),
  ('tr.diyanet', 9, 47, 'Aranızda savaşa çıkmış olsalardı, ancak sizi bozmağa çalışırlar ve fitneye düşürmek için aranıza sokulurlardı. İçinizde onlara kulak verenler var. Allah kendilerine yazık edenleri bilir.'),
  ('tr.diyanet', 9, 48, 'And olsun ki, daha önce de fitne koparmak istemişlerdi. Sana karşı bir takım işler çeviriyorlardı, sonunda onlar istemedikleri halde hak ortaya çıktı, Allah\'ın emri üstün geldi.'),
  ('tr.diyanet', 9, 49, 'Onlardan, "Bana izin ver, beni fitneye düşürme" diyen vardır. Bilin ki onlar zaten fitneye düşmüşlerdi. Cehennem, inkar edenleri şüphesiz kuşatacaktır.'),
  ('tr.diyanet', 9, 50, 'Sana bir iyilik gelince onların fenasına gider; bir kötülük gelse, "Biz önceden ihtiyatlı davrandık" derler, sevinerek dönüp giderler.'),
  ('tr.diyanet', 9, 51, 'De ki: "Allah\'ın bize yazdığından başkası başımıza gelmez. O bizim Mevlamızdır, inananlar Allah\'a güvensin."'),
  ('tr.diyanet', 9, 52, 'De ki: "Bize iki iyiden, gazilik ve şehidlikten başka bir şeyin gelmesini mi bekliyorsunuz? Oysa biz Allah\'ın kendi katından veya elimizle, sizi bir azaba uğratmasını bekliyoruz. Bekleyiniz, doğrusu biz de sizinle birlikte beklemekteyiz."'),
  ('tr.diyanet', 9, 53, 'De ki: "İstekli yahut isteksiz olarak verin, nasıl olsa kabul edilmeyecektir. Siz şüphesiz fasık bir topluluksunuz."'),
  ('tr.diyanet', 9, 54, 'Verdiklerinin kabul olunmasına engel olan, Allah\'ı ve Peygamberini inkar etmeleri, namaza tembel tembel gelmeleri, istemeye istemeye vermeleridir.'),
  ('tr.diyanet', 9, 55, 'Artık onların malları ve çocukları seni imrendirmesin. Allah bunlarla onlara dünya hayatında azabetmek ve canlarının inkarcı olarak çıkmasını ister.'),
  ('tr.diyanet', 9, 56, 'Sizden olmadıkları halde, sizinle beraber olduklarına Allah\'a yemin ederler. Oysa onlar korkak bir topluluktur.'),
  ('tr.diyanet', 9, 57, 'Bir sığınak veya mağara yahut girecek bir yer bulmuş olsalardı, çarçabuk oraya yönelirlerdi.'),
  ('tr.diyanet', 9, 58, 'Sadakalar hakkında sana dil uzatanlar vardır. Onlara verilirse hoşnut olurlar, verilmezse, hemen öfkeleniverirler.'),
  ('tr.diyanet', 9, 59, 'Eğer onlar, Allah ve Peygamberinin kendilerine vermiş oldukları şeylere razı olsalar ve "Allah bize yeter, O ve Peygamberi bol nimetinden bize verecektir; doğrusu biz Allah\'a gönül bağlayanlardanız" deselerdi daha hayırlı olurdu.'),
  ('tr.diyanet', 9, 60, 'Zekatlar; Allah\'tan bir farz olarak yoksullara, düşkünlere, onu toplayan memurlara, kalbleri Müslümanlığa ısındırılacaklara verilir; kölelerin, borçluların, Allah yolunda olanların ve yolda kalanların uğrunda sarfedilir. Allah bilendir, hakimdir.'),
  ('tr.diyanet', 9, 61, 'İkiyüzlülerin içinde "O her şeye kulak kesiliyor" diyerek Peygamberi incitenler vardır. De ki: "O kulak, Allah\'a inanan ve müminlere inanan, sizin için hayırlı olan, içinizden inanan kimselere rahmet olan bir kulaktır." Allah\'ın Peygamberini incitenlere can yakıcı azab vardır.'),
  ('tr.diyanet', 9, 62, 'Sizi hoşnut etmek için Allah\'a yemin ederler. Eğer inanıyorlarsa Allah\'ı ve Peygamberini hoşnut etmeleri daha gereklidir.'),
  ('tr.diyanet', 9, 63, 'Allah\'a ve Peygamberine karşı koymağa kalkışana, ebedi kalacağı cehennem ateşi bulunduğunu bilmezler mi? Büyük rezillik budur.'),
  ('tr.diyanet', 9, 64, 'İkiyüzlüler, kalblerinde olanı haber verecek bir surenin inmesinden çekiniyorlar. De ki: "Alay edin bakalım, Allah çekindiğiniz şeyi ortaya koyacaktır."'),
  ('tr.diyanet', 9, 65, 'Onlara soracak olursan, "Biz and olsun ki, eğlenip oynuyorduk" diyecekler; De ki: "Allah\'la, ayetleriyle, Peygamberiyle mi alay ediyordunuz?"'),
  ('tr.diyanet', 9, 66, 'Özür beyan etmeyin, inandıktan sonra inkar ettiniz. İçinizden bir topluluğu affetsek bile, suçlarından ötürü bir topluluğa da azab ederiz.'),
  ('tr.diyanet', 9, 67, 'İkiyüzlü erkek ve kadınlar da birbirlerindendir: Kötülüğü emreder, iyiliğe engel olurlar; elleri de sıkıdır; Allah\'ı unuttular, bu yüzden Allah da onları unuttu. Doğrusu ikiyüzlüler fasıktırlar.'),
  ('tr.diyanet', 9, 68, 'Allah, ikiyüzlü erkek ve kadınlara ve inkarcılara, ebedi kalacakları cehennem ateşini hazırlamıştır. O, onlara yeter. Allah onları lanetlemiştir (rahmetinden uzak kılmıştır). Onlara devamlı azab vardır.'),
  ('tr.diyanet', 9, 69, 'Ey ikiyüzlüler! Siz, sizden önce daha kuvvetli, malları ve çocukları daha çok olup, hisselerince bunlardan faydalanan kimseler gibisiniz. Sizden öncekiler, hisselerince faydalandıkları gibi siz de hissenizce faydalandınız ve onların batıla daldıklarıgibi siz de daldınız. İşte bunlar dünyada ve ahirette işleri boşa çıkanlardır, işte bunlar mahvolanlardır.'),
  ('tr.diyanet', 9, 70, 'Kendilerinden önce olan Nuh, Ad, Semud milletlerinin, İbrahim milletinin, Medyen ve altüst olmuş şehirler halkının haberleri onlara gelmedi mi? Peygamberleri onlara belgeler getirmişlerdi. Allah onlara zulmetmemiş, onlar kendilerine yazık etmişlerdir.'),
  ('tr.diyanet', 9, 71, 'Mümin erkekler ve mümin kadınlar birbirlerinin velileridir; iyiyi emreder kötülükten alıkorlar; namaz kılarlar, zekat verirler, Allah\'a ve Peygamberine itaat ederler. İşte Allah bunlara rahmet edecektir. Allah şüphesiz güçlüdür, hakimdir.'),
  ('tr.diyanet', 9, 72, 'Allah mümin erkeklere ve mümin kadınlara, temelli kalacakları, içlerinden ırmaklar akan cennetler, Adn cennetlerinde hoş meskenler vadetmiştir. Allah\'ın hoşnut olması en büyük şeydir. İşte büyük kurtuluş budur.'),
  ('tr.diyanet', 9, 73, 'Ey Peygamber! İnkarcılarla, ikiyüzlülerle savaş; onlara karşı sert davran. Varacakları yer cehennemdir, ne kötü dönüştür.'),
  ('tr.diyanet', 9, 74, 'And olsun ki, müslüman olduktan sonra inkar edip küfür sözünü söylemişler iken, söylemedik diye Allah\'a yemin ettiler, başaramayacakları bir şeye giriştiler; Allah ve Peygamberi bol nimetinden onları zenginleştirdi ve öç almaya kalktılar. Eğer tevbe ederlerse iyiliklerine olur; şayet yüz çevirirlerse, Allah onları dünya ve ahirette can yakıcı azaba uğratır. Yeryüzünde bir dost ve yardımcıları yoktur.'),
  ('tr.diyanet', 9, 75, 'Aralarında: "Allah bize bol nimetinden verecek olursa, and olsun ki sadaka vereceğiz ve iyilerden olacağız" diye O\'na and verenler vardır.'),
  ('tr.diyanet', 9, 76, 'Allah onlara bol nimetinden verince, cimrilik ettiler, yüz çevirdiler. Zaten dönektirler.'),
  ('tr.diyanet', 9, 77, 'Allah\'a verdikleri sözden caydıkları ve yalancı oldukları için O\'nunla karşılaşacakları güne kadar Allah kalblerine nifak soktu.'),
  ('tr.diyanet', 9, 78, 'İkiyüzlüler, Allah\'ın onların sırlarını ve gizli toplantılarını bildiğini, Allah\'ın görünmeyenleri bilen olduğunu bilmiyorlar mıydı?'),
  ('tr.diyanet', 9, 79, 'Sadaka vermekte gönülden davranan müminlere dil uzatan ve ancak ellerinden geldiği kadar verebilenlerle alay eden kimselere bu davranışlarının cezasını Allah verir; onlara can yakıcı azab vardır.'),
  ('tr.diyanet', 9, 80, 'Onların ister bağışlanmasını dile, ister dileme, birdir. Onlara yetmiş defa bağışlanma dilesen Allah onları bağışlamayacaktır. Bu, Allah\'ı ve Peygamberini inkar etmelerinden ötürüdür. Allah fasık topluluğu doğru yola eriştirmez.'),
  ('tr.diyanet', 9, 81, 'Allah\'ın Peygamberinin hilafına geri kalanlar, oturup kalmalarına sevindiler. Allah yolunda mallariyle ve canlariyle cihat hoşlarına gitmedi. "Sıcakta savaşa çıkmayın" dediler. De ki: "Cehennem ateşi daha sıcaktır." Keşke bilseydiler!'),
  ('tr.diyanet', 9, 82, 'Yaptıklarının cezası olarak, bundan böyle az gülsünler, çok ağlasınlar.'),
  ('tr.diyanet', 9, 83, 'Allah seni geri döndürüp, onlardan bir toplulukla karşılaştırdığı zaman, senden savaşa çıkmak için izin isterlerse, de ki: "Benimle asla çıkamayacaksınız, benim yanımda hiçbir düşmanla savaşmıyacaksınız; çünkü baştan, oturup kalmaya razı oldunuz. Artık geri kalanlarla beraber oturun."'),
  ('tr.diyanet', 9, 84, 'Onlardan ölen kimsenin namazını sakın kılma, mezarı başında da durma! Çünkü onlar Allah\'ı ve peygamberini inkar ettiler, fasık olarak öldüler.'),
  ('tr.diyanet', 9, 85, 'Malları ve çocukları seni hayrete düşürmesin; Allah bunlarla onlara dünyada azabetmek ve canlarının inkarcı olarak çıkmasını ister.'),
  ('tr.diyanet', 9, 86, '"Allah\'a inanın ve Peygamberinin yanında savaşın" diye bir sure inmiş olsa, onların gücü yetenleri sizden izin isterler ve "Bizi bırak oturanlarla beraber kalalım" derler.'),
  ('tr.diyanet', 9, 87, 'Geri kalan kadınlarla beraber bulunmaya razı oldular. Kalbleri kapanmıştır, bu yüzden anlamazlar.'),
  ('tr.diyanet', 9, 88, 'Ama Peygamber ve onunla beraber bulunan müminler, mallariyle ve canlariyle savaştılar. İşte iyilikler onlaradır, saadete erişenler de onlardır.'),
  ('tr.diyanet', 9, 89, 'Allah onlara temelli kalacakları, içlerinden ırmaklar akan cennetler hazırlamıştır. Büyük kurtuluş budur.'),
  ('tr.diyanet', 9, 90, 'Bedevilerden, izin almak üzere, özür beyan eden kimseler geldiler. Allah\'a ve Peygamberine yalan söyleyenler ise, özür bile beyan etmeksizin geri kaldılar. Onlardan kafir olanlar can yakıcı azaba uğrayacaktır.'),
  ('tr.diyanet', 9, 91, 'Güçsüzlere, hastalara ve sarfedecek bir şeyi bulunmayanlara, Allah ve Peygamberine bağlı kaldıkları müddetçe sorumluluk yoktur. İyi davrananlara sorumluluk olmaz. Allah bağışlayandır, merhamet edendir.'),
  ('tr.diyanet', 9, 92, 'Binek vermen için sana geldiklerinde, "Size binek bulamıyorum" dediğin zaman, sarfedecek bir şey bulamadıkları için üzüntüden gözyaşı dökerek geri dönenlere de sorumluluk yoktur.'),
  ('tr.diyanet', 9, 93, 'Sorumluluk ancak, zengin oldukları halde senden izin isteyen, geride kalan kadınlarla bulunmaya razı olanlara ve Allah kalblerini mühürlemiş olduğu için bilmeyenleredir.'),
  ('tr.diyanet', 9, 94, 'Savaştan döndüğünüzde size özür beyan ederler. Onlara de ki: "özür beyan etmeyin, size inanmayacağız, Allah haberlerinizi bize bildirmiştir. Allah da, Peygamberi de işleyeceklerinizi görecektir. Sonunda, görülmeyeni ve görüneni bilen Allah\'a geri çevrileceksiniz. O, işlediklerinizi size haber verecektir."'),
  ('tr.diyanet', 9, 95, 'Döndüğünüzde kendilerine çıkışmamanız için, Allah\'a yemin edeceklerdir. Siz onlardan yüz çevirin; çünkü pistirler. Yaptıklarının karşılığı olarak varacakları yer cehennemdir.'),
  ('tr.diyanet', 9, 96, 'Kendilerinden hoşnut olasınız diye, size and verirler. Siz onlardan hoşnut olsanız bile, Allah, yoldan çıkmış kimselerden razı olmaz.'),
  ('tr.diyanet', 9, 97, 'Bedevilerin küfür ve nifakları her yönden, daha ileridir. Allah\'ın, Peygamberine indirdiğinin sınırlarını bilmemek, onlara daha layıktır. Allah bilendir, hakimdir.'),
  ('tr.diyanet', 9, 98, 'Bedevilerden, Allah yolunda sarfettiklerini angarya sayanlar ve sizin başınıza belalar gelmesini bekleyenler vardır. Belalar onlara olsun; Allah işitir ve bilir.'),
  ('tr.diyanet', 9, 99, 'Bedevilerden, Allah\'a ve ahiret gününe inanan, sarfettiğini, Allah katında ibadet ve Peygamberin dualarına nail olmağa vesile sayanlar da vardır. Bilin ki, verdikleri onlar için ibadettir. Allah, onlara rahmet edecektir. Allah şüphesiz bağışlar ve merhamet eder.'),
  ('tr.diyanet', 9, 100, 'İyilik yarışında önceliği kazanan Muhacirler ve Ensar ile, onlara güzelce uyanlardan Allah hoşnut olmuştur, onlar da Allah\'tan hoşnuddurlar. Allah onlara, içinde temelli ve ebedi kalacakları, içlerinden ırmaklar akan cennetler hazırlamıştır; işte büyük kurtuluş budur.'),
  ('tr.diyanet', 9, 101, 'Çevrenizdeki Bedeviler içinde ikiyüzlüler ve Medine\'liler içinde de ikiyüzlülükte direnenler vardır. Onları siz değil, ancak Biz biliriz. Kendilerine iki defa azabedeceğiz; onlar sonra da büyük bir azaba uğratılırlar.'),
  ('tr.diyanet', 9, 102, 'Savaştan geri kalanların bir kısmı da, suçlarını itiraf ettiler. Onlar iyi işi kötüyle karıştırmışlardı. Allah\'ın onların tevbesini kabul etmesi umulur; çünkü O bağışlayandır, merhamet edendir.'),
  ('tr.diyanet', 9, 103, 'Mallarının bir kısmını, kendilerini temizleyip arıtacak sadaka olarak al, onlara dua et; senin duan onlar için bir güvendir. Allah işitir ve bilir.'),
  ('tr.diyanet', 9, 104, 'Allah\'ın, kullarının tevbesini kabul ettiğini, sadakalar aldığını, Allah\'ın tevbeleri kabul ve merhamet eden olduğunu bilmiyorlar mı?'),
  ('tr.diyanet', 9, 105, 'De ki: "İstediğinizi işleyin; Allah, Peygamberi ve müminler işlediklerinizi görecektir. Hepiniz, görülmeyeni ve görüleni bilen Allah\'a döndürüleceksiniz. O size, işlediklerinizi bildirecektir."'),
  ('tr.diyanet', 9, 106, 'Savaştan geri kalanların bir kısmının işi de Allah\'ın buyruğuna kalmıştır. Allah onlara ya azabeder, ya da tevbelerini kabul eder. O bilendir, hakimdir.'),
  ('tr.diyanet', 9, 107, 'Zarar vermek, inkar etmek, müminlerin arasını ayırmak, Allah ve Peygamber\'ine karşı savaşanlara daha önceden gözcülük yapmak üzere bir mescid kurup: "Biz sadece iyilik yapmak istedik" diye yemin edenlerin yalancı olduklarına şüphesiz ki Allah şahiddir.'),
  ('tr.diyanet', 9, 108, 'O mescide hiç girme! İlk gününden beri Allah\'a karşı gelmekten sakınmak için kurulan mescidde bulunman daha uygundur. Orada, arınmak isteyen insanlar vardır. Allah, arınmak isteyenleri sever.'),
  ('tr.diyanet', 9, 109, 'Yapısını, Allah\'tan sakınmak ve Onun hoşnudluğuna ermek için yapan kimse mi daha hayırlıdır; yoksa, yapısını kayacak bir yar kıyısına yapıp da onunla beraber cehennem ateşine yuvarlanan kimse mi? Allah, zulmeden kimselere doğru yolu göstermez.'),
  ('tr.diyanet', 9, 110, 'Yaptıkları bina, kalblerinde şüphe ve ızdırap kaynağı olmakta kalbleri paralanana kadar devam edecektir. Allah bilendir, hakimdir.'),
  ('tr.diyanet', 9, 111, 'Allah şüphesiz, Allah yolunda savaşıp, öldüren ve öldürülen müminlerin canlarını ve mallarını Tevrat, İncil ve Kuran\'da söz verilmiş bir hak olarak cennete karşılık satın almıştır. Verdiği sözü Allah\'tan daha çok tutan kim vardır? Öyleyse, yaptığınız alışverişe sevinin; bu büyük başarıdır.'),
  ('tr.diyanet', 9, 112, 'Allah\'a tevbe eden, kullukta bulunan, O\'nu öven, O\'nun uğrunda gezen, rüku ve secde eden, uygun olanı buyurup fenalığı yasak eden ve Allah\'ın yasalarını koruyan müminlere de müjdele.'),
  ('tr.diyanet', 9, 113, 'Cehennemlik oldukları anlaşıldıktan sonra, akraba bile olsalar, puta tapanlar için mağfiret dilemek Peygamber\'e ve müminlere yaraşmaz.'),
  ('tr.diyanet', 9, 114, 'İbrahim\'in, babası için mağfiret dilemesi, sadece ona verdiği bir sözden ötürü idi.'),
  ('tr.diyanet', 9, 115, 'Allah, bir milleti doğru yola eriştirdikten sonra, sakınacakları şeyleri onlara açıklamadıkça, sapıklığa düşürmez. Allah şüphesiz her şeyi bilir.'),
  ('tr.diyanet', 9, 116, 'Göklerin ve yerin hükümranlığı elbette Allah\'ındır; dirilten ve öldüren O\'dur. Allah\'tan başka dost ve yardımcınız yoktur.'),
  ('tr.diyanet', 9, 117, 'And olsun ki, Allah, sıkıntılı bir zamanda bir kısmının kalbleri kaymak üzere iken Peygamber\'e uyan Muhacirlerle Ensarın ve Peygamberin tevbelerini kabul etti. Tevbelerini, onlara karşı şefkatli ve merhametli olduğu için kabul etmiştir.'),
  ('tr.diyanet', 9, 118, 'Bütün genişliğine rağmen yer onlara dar gelerek nefisleri kendilerini sıkıştırıp, Allah\'tan başka sığınacak kimse olmadığını anlayan, savaştan geri kalmış üç kişinin tevbesini de kabul etti. Allah, tevbe ettikleri için onların tevbesini kabul etmiştir. Çünkü O tevbeleri kabul eden, merhametli olandır.'),
  ('tr.diyanet', 9, 119, 'Ey inananlar! Allah\'tan sakının ve doğrularla beraber olun.'),
  ('tr.diyanet', 9, 120, 'Medinelilere ve çevrelerinde bulunan Bedevilere, savaşta Allah\'ın Peygamberinden geri kalmak, kendilerini ona tercih etmek yaraşmaz. Çünkü Allah yolunda susuzluğa, yorgunluğa, açlığa uğramak, kafirleri kızdıracak bir yeri işgal etmek ve düşmana başarı kazanmak karşılığında, onların yararlı bir iş yaptıkları mutlaka yazılır. Doğrusu Allah iyilik yapanların ecrini zayi etmez.'),
  ('tr.diyanet', 9, 121, 'Allah, yaptıklarının karşılığını en güzel şekilde kendilerine vermek üzere, az veya çok sarfettikleri her şey, yürüdükleri her yol, onlar için yazılır.'),
  ('tr.diyanet', 9, 122, 'İnananlar toptan savaşa çıkmamalıdır. Her topluluktan bir taifenin dini iyi öğrenmek ve milletlerini geri döndüklerinde uyarmak üzere geri kalmaları gerekli olmaz mı? Ki böylece belki yanlış hareketlerden çekinirler.'),
  ('tr.diyanet', 9, 123, 'Ey inananlar! Yakınınızda bulunan inkarcılarla savaşın; sizi kendilerine karşı sert bulsunlar. Bilin ki Allah, kendisine karşı gelmekten sakınanlarla beraberdir.'),
  ('tr.diyanet', 9, 124, 'Bir sure inince, aralarında "Bu, hanginizin imanını artırdı?" diyen ikiyüzlüler vardır. İnananların ise imanını artırmıştır; onlar birbirlerine bunu müjdelemek isterler.'),
  ('tr.diyanet', 9, 125, 'Kalblerinde hastalık olanların ise pisliklerine pislik katmıştır; onlar kafir olarak ölmüşlerdir.'),
  ('tr.diyanet', 9, 126, 'Onlar, yılda bir iki defa belaya uğratılıp imtihana çekildiklerini görmüyorlar mı? Böyleyken yine tevbe etmiyorlar, ibret de almıyorlar.'),
  ('tr.diyanet', 9, 127, 'Bir sure inince, "Sizi bir kimse görüyor mu?" diye birbirlerine bakarlar, sonra dönüp giderler. Anlamaz bir güruh olmalarına karşılık Allah onların kalblerini imandan döndürmüştür.'),
  ('tr.diyanet', 9, 128, 'Ey inananlar! And olsun ki, içinizden size, sıkıntıya uğramanız kendisine ağır gelen, size düşkün, inananlara şefkatli ve merhametli bir peygamber gelmiştir.'),
  ('tr.diyanet', 9, 129, 'Eğer yüz çevirirlerse de ki: "Allah bana yeter; O\'ndan başka tanrı yoktur, yalnız O\'na güveniyorum; O büyük arşın Rabbidir."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 9, 1, '(Inilah pernyataan) pemutusan hubungan dari Allah dan Rasul-Nya (yang dihadapkan) kepada orang-orang musyrikin yang kamu (kaum muslimin) telah mengadakan perjanjian (dengan mereka).'),
  ('id.indonesian', 9, 2, 'Maka berjalanlah kamu (kaum musyrikin) di muka bumi selama empat bulan dan ketahuilah bahwa sesungguhnya kamu tidak akan dapat melemahkan Allah, dan sesungguhnya Allah menghinakan orang-orang kafir.'),
  ('id.indonesian', 9, 3, 'Dan (inilah) suatu permakluman daripada Allah dan Rasul-Nya kepada umat manusia pada hari haji akbar bahwa sesungguhnya Allah dan Rasul-Nya berlepas diri dari orang-orang musyrikin. Kemudian jika kamu (kaum musyrikin) bertobat, maka bertaubat itu lebih baik bagimu; dan jika kamu berpaling, maka ketahuilah bahwa sesungguhnya kamu tidak dapat melemahkan Allah. Dan beritakanlah kepada orang-orang kafir (bahwa mereka akan mendapat) siksa yang pedih.'),
  ('id.indonesian', 9, 4, 'kecuali orang-orang musyrikin yang kamu telah mengadakan perjanjian (dengan mereka) dan mereka tidak mengurangi sesuatu pun (dari isi perjanjian)mu dan tidak (pula) mereka membantu seseorang yang memusuhi kamu, maka terhadap mereka itu penuhilah janjinya sampai batas waktunya. Sesungguhnya Allah menyukai orang-orang yang bertakwa.'),
  ('id.indonesian', 9, 5, 'Apabila sudah habis bulan-bulan Haram itu, maka bunuhlah orang-orang musyrikin itu dimana saja kamu jumpai mereka, dan tangkaplah mereka. Kepunglah mereka dan intailah ditempat pengintaian. Jika mereka bertaubat dan mendirikan sholat dan menunaikan zakat, maka berilah kebebasan kepada mereka untuk berjalan. Sesungguhnya Allah Maha Pengampun lagi maha Penyayang.'),
  ('id.indonesian', 9, 6, 'Dan jika seorang diantara orang-orang musyrikin itu meminta perlindungan kepadamu, maka lindungilah ia supaya ia sempat mendengar firman Allah, kemudian antarkanlah ia ketempat yang aman baginya. Demikian itu disebabkan mereka kaum yang tidak mengetahui.'),
  ('id.indonesian', 9, 7, 'Bagaimana bisa ada perjanjian (aman) dari sisi Allah dan Rasul-Nya dengan orang-orang musyrikin, kecuali orang-orang yang kamu telah mengadakan perjanjian (dengan mereka) di dekat Masjidil haraam? maka selama mereka berlaku lurus terhadapmu, hendaklah kamu berlaku lurus (pula) terhadap mereka. Sesungguhnya Allah menyukai orang-orang yang bertakwa.'),
  ('id.indonesian', 9, 8, 'Bagaimana bisa (ada perjanjian dari sisi Allah dan Rasul-Nya dengan orang-orang musyrikin), padahal jika mereka memperoleh kemenangan terhadap kamu, mereka tidak memelihara hubungan kekerabatan terhadap kamu dan tidak (pula mengindahkan) perjanjian. Mereka menyenangkan hatimu dengan mulutnya, sedang hatinya menolak. Dan kebanyakan mereka adalah orang-orang yang fasik (tidak menepati perjanjian).'),
  ('id.indonesian', 9, 9, 'Mereka menukarkan ayat-ayat Allah dengan harga yang sedikit, lalu mereka menghalangi (manusia) dari jalan Allah. Sesungguhnya amat buruklah apa yang mereka kerjakan itu.'),
  ('id.indonesian', 9, 10, 'Mereka tidak memelihara (hubungan) kerabat terhadap orang-orang mukmin dan tidak (pula mengindahkan) perjanjian. Dan mereka itulah orang-orang yang melampaui batas.'),
  ('id.indonesian', 9, 11, 'Jika mereka bertaubat, mendirikan sholat dan menunaikan zakat, maka (mereka itu) adalah saudara-saudaramu seagama. Dan Kami menjelaskan ayat-ayat itu bagi kaum yang mengetahui.'),
  ('id.indonesian', 9, 12, 'Jika mereka merusak sumpah (janji)nya sesudah mereka berjanji, dan mereka mencerca agamamu, maka perangilah pemimpin-pemimpin orang-orang kafir itu, karena sesungguhnya mereka itu adalah orang-orang (yang tidak dapat dipegang) janjinya, agar supaya mereka berhenti.'),
  ('id.indonesian', 9, 13, 'Mengapakah kamu tidak memerangi orang-orang yang merusak sumpah (janjinya), padahal mereka telah keras kemauannya untuk mengusir Rasul dan merekalah yang pertama mulai memerangi kamu? Mengapakah kamu takut kepada mereka padahal Allah-lah yang berhak untuk kamu takuti, jika kamu benar-benar orang yang beriman.'),
  ('id.indonesian', 9, 14, 'Perangilah mereka, niscaya Allah akan menghancurkan mereka dengan (perantaraan) tangan-tanganmu dan Allah akan menghinakan mereka dan menolong kamu terhadap mereka, serta melegakan hati orang-orang yang beriman.'),
  ('id.indonesian', 9, 15, 'dan menghilangkan panas hati orang-orang mukmin. Dan Allah menerima taubat orang yang dikehendaki-Nya. Allah maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 16, 'Apakah kamu mengira bahwa kamu akan dibiarkan, sedang Allah belum mengetahui (dalam kenyataan) orang-orang yang berjihad di antara kamu dan tidak mengambil menjadi teman yang setia selain Allah, Rasul-Nya dan orang-orang yang beriman. Dan Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 9, 17, 'Tidaklah pantas orang-orang musyrik itu memakmurkan mesjid-mesjid Allah, sedang mereka mengakui bahwa mereka sendiri kafir. Itulah orang-orang yang sia-sia pekerjaannya, dan mereka kekal di dalam neraka.'),
  ('id.indonesian', 9, 18, 'Hanya yang memakmurkan masjid-masjid Allah ialah orang-orang yang beriman kepada Allah dan Hari kemudian, serta tetap mendirikan shalat, menunaikan zakat dan tidak takut (kepada siapapun) selain kepada Allah, maka merekalah orang-orang yang diharapkan termasuk golongan orang-orang yang mendapat petunjuk.'),
  ('id.indonesian', 9, 19, 'Apakah (orang-orang) yang memberi minuman orang-orang yang mengerjakan haji dan mengurus Masjidilharam kamu samakan dengan orang-orang yang beriman kepada Allah dan hari kemudian serta bejihad di jalan Allah? Mereka tidak sama di sisi Allah; dan Allah tidak memberi petunjuk kepada kaum yang zalim.'),
  ('id.indonesian', 9, 20, 'orang-orang yang beriman dan berhijrah serta berjihad di jalan Allah dengan harta, benda dan diri mereka, adalah lebih tinggi derajatnya di sisi Allah; dan itulah orang-orang yang mendapat kemenangan.'),
  ('id.indonesian', 9, 21, 'Tuhan mereka menggembirakan mereka dengan memberikan rahmat dari pada-Nya, keridhaan dan surga, mereka memperoleh didalamnya kesenangan yang kekal,'),
  ('id.indonesian', 9, 22, 'mereka kekal di dalamnya selama-lamanya. Sesungguhnya di sisi Allah-lah pahala yang besar.'),
  ('id.indonesian', 9, 23, 'Hai orang-orang beriman, janganlah kamu jadikan bapa-bapa dan saudara-saudaramu menjadi wali(mu), jika mereka lebih mengutamakan kekafiran atas keimanan dan siapa di antara kamu yang menjadikan mereka wali, maka mereka itulah orang-orang yang zalim.'),
  ('id.indonesian', 9, 24, 'Katakanlah: "jika bapa-bapa, anak-anak, saudara-saudara, isteri-isteri, kaum keluargamu, harta kekayaan yang kamu usahakan, perniagaan yang kamu khawatiri kerugiannya, dan tempat tinggal yang kamu sukai, adalah lebih kamu cintai dari Allah dan Rasul-Nya dan dari berjihad di jalan-Nya, maka tunggulah sampai Allah mendatangkan keputusan-Nya". Dan Allah tidak memberi petunjuk kepada orang-orang yang fasik.'),
  ('id.indonesian', 9, 25, 'Sesungguhnya Allah telah menolong kamu (hai para mukminin) di medan peperangan yang banyak, dan (ingatlah) peperangan Hunain, yaitu diwaktu kamu menjadi congkak karena banyaknya jumlah(mu), maka jumlah yang banyak itu tidak memberi manfaat kepadamu sedikitpun, dan bumi yang luas itu telah terasa sempit olehmu, kemudian kamu lari kebelakang dengan bercerai-berai.'),
  ('id.indonesian', 9, 26, 'Kemudian Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang-orang yang beriman, dan Allah menurunkan bala tentara yang kamu tiada melihatnya, dan Allah menimpakan bencana kepada orang-orang yang kafir, dan demikianlah pembalasan kepada orang-orang yang kafir.'),
  ('id.indonesian', 9, 27, 'Sesudah itu Allah menerima taubat dari orang-orang yang dikehendaki-Nya. Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 9, 28, 'Hai orang-orang yang beriman, Sesungguhnya orang-orang yang musyrik itu najis, maka janganlah mereka mendekati Masjidilharam sesudah tahun ini. Dan jika kamu khawatir menjadi miskin, maka Allah nanti akan memberimu kekayaan kepadamu dari karunia-Nya, jika Dia menghendaki. Sesungguhnya Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 29, 'Perangilah orang-orang yang tidak beriman kepada Allah dan tidak (pula) kepada hari kemudian, dan mereka tidak mengharamkan apa yang diharamkan oleh Allah dan Rasul-Nya dan tidak beragama dengan agama yang benar (agama Allah), (yaitu orang-orang) yang diberikan Al-Kitab kepada mereka, sampai mereka membayar jizyah dengan patuh sedang mereka dalam keadaan tunduk.'),
  ('id.indonesian', 9, 30, 'Orang-orang Yahudi berkata: "Uzair itu putera Allah" dan orang-orang Nasrani berkata: "Al Masih itu putera Allah". Demikianlah itu ucapan mereka dengan mulut mereka, mereka meniru perkataan orang-orang kafir yang terdahulu. Dilaknati Allah mereka, bagaimana mereka sampai berpaling?'),
  ('id.indonesian', 9, 31, 'Mereka menjadikan orang-orang alimnya dan rahib-rahib mereka sebagai tuhan selain Allah dan (juga mereka mempertuhankan) Al Masih putera Maryam, padahal mereka hanya disuruh menyembah Tuhan yang Esa, tidak ada Tuhan (yang berhak disembah) selain Dia. Maha suci Allah dari apa yang mereka persekutukan.'),
  ('id.indonesian', 9, 32, 'Mereka berkehendak memadamkan cahaya (agama) Allah dengan mulut (ucapan-ucapan) mereka, dan Allah tidak menghendaki selain menyempurnakan cahaya-Nya, walaupun orang-orang yang kafir tidak menyukai.'),
  ('id.indonesian', 9, 33, 'Dialah yang telah mengutus Rasul-Nya (dengan membawa) petunjuk (Al-Quran) dan agama yang benar untuk dimenangkan-Nya atas segala agama, walaupun orang-orang musyrikin tidak menyukai.'),
  ('id.indonesian', 9, 34, 'Hai orang-orang yang beriman, sesungguhnya sebahagian besar dari orang-orang alim Yahudi dan rahib-rahib Nasrani benar-benar memakan harta orang dengan jalan batil dan mereka menghalang-halangi (manusia) dari jalan Allah. Dan orang-orang yang menyimpan emas dan perak dan tidak menafkahkannya pada jalan Allah, maka beritahukanlah kepada mereka, (bahwa mereka akan mendapat) siksa yang pedih,'),
  ('id.indonesian', 9, 35, 'pada hari dipanaskan emas perak itu dalam neraka jahannam, lalu dibakar dengannya dahi mereka, lambung dan punggung mereka (lalu dikatakan) kepada mereka: "Inilah harta bendamu yang kamu simpan untuk dirimu sendiri, maka rasakanlah sekarang (akibat dari) apa yang kamu simpan itu".'),
  ('id.indonesian', 9, 36, 'Sesungguhnya bilangan bulan pada sisi Allah adalah dua belas bulan, dalam ketetapan Allah di waktu Dia menciptakan langit dan bumi, di antaranya empat bulan haram. Itulah (ketetapan) agama yang lurus, maka janganlah kamu menganiaya diri kamu dalam bulan yang empat itu, dan perangilah kaum musyrikin itu semuanya sebagaimana merekapun memerangi kamu semuanya, dan ketahuilah bahwasanya Allah beserta orang-orang yang bertakwa.'),
  ('id.indonesian', 9, 37, 'Sesungguhnya mengundur-undurkan bulan haram itu adalah menambah kekafiran. Disesatkan orang-orang yang kafir dengan mengundur-undurkan itu, mereka menghalalkannya pada suatu tahun dan mengharamkannya pada tahun yang lain, agar mereka dapat mempersesuaikan dengan bilangan yang Allah mengharamkannya, maka mereka menghalalkan apa yang diharamkan Allah. (Syaitan) menjadikan mereka memandang perbuatan mereka yang buruk itu. Dan Allah tidak memberi petunjuk kepada orang-orang yang kafir.'),
  ('id.indonesian', 9, 38, 'Hai orang-orang yang beriman, apakah sebabnya bila dikatakan kepadamu: "Berangkatlah (untuk berperang) pada jalan Allah" kamu merasa berat dan ingin tinggal di tempatmu? Apakah kamu puas dengan kehidupan di dunia sebagai ganti kehidupan di akhirat? Padahal kenikmatan hidup di dunia ini (dibandingkan dengan kehidupan) diakhirat hanyalah sedikit.'),
  ('id.indonesian', 9, 39, 'Jika kamu tidak berangkat untuk berperang, niscaya Allah menyiksa kamu dengan siksa yang pedih dan digantinya (kamu) dengan kaum yang lain, dan kamu tidak akan dapat memberi kemudharatan kepada-Nya sedikitpun. Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 9, 40, 'Jikalau kamu tidak menolongnya (Muhammad) maka sesungguhnya Allah telah menolongnya (yaitu) ketika orang-orang kafir (musyrikin Mekah) mengeluarkannya (dari Mekah) sedang dia salah seorang dari dua orang ketika keduanya berada dalam gua, di waktu dia berkata kepada temannya: "Janganlah kamu berduka cita, sesungguhnya Allah beserta kita". Maka Allah menurunkan keterangan-Nya kepada (Muhammad) dan membantunya dengan tentara yang kamu tidak melihatnya, dan Al-Quran menjadikan orang-orang kafir itulah yang rendah. Dan kalimat Allah itulah yang tinggi. Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 41, 'Berangkatlah kamu baik dalam keadaan merasa ringan maupun berat, dan berjihadlah kamu dengan harta dan dirimu di jalan Allah. Yang demikian itu adalah lebih baik bagimu, jika kamu mengetahui.'),
  ('id.indonesian', 9, 42, 'Kalau yang kamu serukan kepada mereka itu keuntungan yang mudah diperoleh dan perjalanan yang tidak seberapa jauh, pastilah mereka mengikutimu, tetapi tempat yang dituju itu amat jauh terasa oleh mereka. Mereka akan bersumpah dengan (nama) Allah: "Jikalau kami sanggup tentulah kami berangkat bersama-samamu". Mereka membinasakan diri mereka sendiri dan Allah mengetahui bahwa sesungguhnya mereka benar-benar orang-orang yang berdusta.'),
  ('id.indonesian', 9, 43, 'Semoga Allah memaafkanmu. Mengapa kamu memberi izin kepada mereka (untuk tidak pergi berperang), sebelum jelas bagimu orang-orang yang benar (dalam keuzurannya) dan sebelum kamu ketahui orang-orang yang berdusta?'),
  ('id.indonesian', 9, 44, 'Orang-orang yang beriman kepada Allah dan hari kemudian, tidak akan meminta izin kepadamu untuk tidak ikut berjihad dengan harta dan diri mereka. Dan Allah mengetahui orang-orang yang bertakwa.'),
  ('id.indonesian', 9, 45, 'Sesungguhnya yang akan meminta izin kepadamu, hanyalah orang-orang yang tidak beriman kepada Allah dan hari kemudian, dan hati mereka ragu-ragu, karena itu mereka selalu bimbang dalam keraguannya.'),
  ('id.indonesian', 9, 46, 'Dan jika mereka mau berangkat, tentulah mereka menyiapkan persiapan untuk keberangkatan itu, tetapi Allah tidak menyukai keberangkatan mereka, maka Allah melemahkan keinginan mereka. dan dikatakan kepada mereka: "Tinggallah kamu bersama orang-orang yang tinggal itu".'),
  ('id.indonesian', 9, 47, 'Jika mereka berangkat bersama-sama kamu, niscaya mereka tidak menambah kamu selain dari kerusakan belaka, dan tentu mereka akan bergegas maju ke muka di celah-celah barisanmu, untuk mengadakan kekacauan di antara kamu; sedang di antara kamu ada orang-orang yang amat suka mendengarkan perkataan mereka. Dan Allah mengetahui orang-orang yang zalim.'),
  ('id.indonesian', 9, 48, 'Sesungguhnya dari dahulupun mereka telah mencari-cari kekacauan dan mereka mengatur pelbagai macam tipu daya untuk (merusakkan)mu, hingga datanglah kebenaran (pertolongan Allah) dan menanglah agama Allah, padahal mereka tidak menyukainya.'),
  ('id.indonesian', 9, 49, 'Di antara mereka ada orang yang berkata: "Berilah saya keizinan (tidak pergi berperang) dan janganlah kamu menjadikan saya terjerumus dalam fitnah". Ketahuilah bahwa mereka telah terjerumus ke dalam fitnah. Dan sesungguhnya Jahannam itu benar-benar meliputi orang-orang yang kafir.'),
  ('id.indonesian', 9, 50, 'Jika kamu mendapat suatu kebaikan, mereka menjadi tidak senang karenanya; dan jika kamu ditimpa oleh sesuatu bencana, mereka berkata: "Sesungguhnya kami sebelumnya telah memperhatikan urusan kami (tidak pergi perang)" dan mereka berpaling dengan rasa gembira.'),
  ('id.indonesian', 9, 51, 'Katakanlah: "Sekali-kali tidak akan menimpa kami melainkan apa yang telah ditetapkan Allah untuk kami. Dialah Pelindung kami, dan hanya kepada Allah orang-orang yang beriman harus bertawakal".'),
  ('id.indonesian', 9, 52, 'Katakanlah: "tidak ada yang kamu tunggu-tunggu bagi kami, kecuali salah satu dari dua kebaikan. Dan Kami menunggu-nunggu bagi kamu bahwa Allah akan menimpakan kepadamu azab (yang besar) dari sisi-Nya. Sebab itu tunggulah, sesungguhnya kami menunggu-nunggu bersamamu".'),
  ('id.indonesian', 9, 53, 'Katakanlah: "Nafkahkanlah hartamu, baik dengan sukarela ataupun dengan terpaksa, namun nafkah itu sekali-kali tidak akan diterima dari kamu. Sesungguhnya kamu adalah orang-orang yang fasik.'),
  ('id.indonesian', 9, 54, 'Dan tidak ada yang menghalangi mereka untuk diterima dari mereka nafkah-nafkahnya melainkan karena mereka kafir kepada Allah dan Rasul-Nya dan mereka tidak mengerjakan sembahyang, melainkan dengan malas dan tidak (pula) menafkahkan (harta) mereka, melainkan dengan rasa enggan.'),
  ('id.indonesian', 9, 55, 'Maka janganlah harta benda dan anak-anak mereka menarik hatimu. Sesungguhnya Allah menghendaki dengan (memberi) harta benda dan anak-anak itu untuk menyiksa mereka dalam kehidupan di dunia dan kelak akan melayang nyawa mereka, sedang mereka dalam keadaan kafir.'),
  ('id.indonesian', 9, 56, 'Dan mereka (orang-orang munafik) bersumpah dengan (nama) Allah, bahwa sesungguhnya mereka termasuk golonganmu; padahal mereka bukanlah dari golonganmu, akan tetapi mereka adalah orang-orang yang sangat takut (kepadamu).'),
  ('id.indonesian', 9, 57, 'Jikalau mereka memperoleh tempat perlindunganmu atau gua-gua atau lobang-lobang (dalam tanah) niscaya mereka pergi kepadanya dengan secepat-cepatnya.'),
  ('id.indonesian', 9, 58, 'Dan di antara mereka ada orang yang mencelamu tentang (distribusi) zakat; jika mereka diberi sebahagian dari padanya, mereka bersenang hati, dan jika mereka tidak diberi sebahagian dari padanya, dengan serta merta mereka menjadi marah.'),
  ('id.indonesian', 9, 59, 'Jikalau mereka sungguh-sungguh ridha dengan apa yang diberikan Allah dan Rasul-Nya kepada mereka, dan berkata: "Cukuplah Allah bagi kami, Allah akan memberikan sebagian dari karunia-Nya dan demikian (pula) Rasul-Nya, sesungguhnya kami adalah orang-orang yang berharap kepada Allah," (tentulah yang demikian itu lebih baik bagi mereka).'),
  ('id.indonesian', 9, 60, 'Sesungguhnya zakat-zakat itu, hanyalah untuk orang-orang fakir, orang-orang miskin, pengurus-pengurus zakat, para mu\'allaf yang dibujuk hatinya, untuk (memerdekakan) budak, orang-orang yang berhutang, untuk jalan Allah dan untuk mereka yuang sedang dalam perjalanan, sebagai suatu ketetapan yang diwajibkan Allah, dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 61, 'Di antara mereka (orang-orang munafik) ada yang menyakiti Nabi dan mengatakan: "Nabi mempercayai semua apa yang didengarnya". Katakanlah: "Ia mempercayai semua yang baik bagi kamu, ia beriman kepada Allah, mempercayai orang-orang mukmin, dan menjadi rahmat bagi orang-orang yang beriman di antara kamu". Dan orang-orang yang menyakiti Rasulullah itu, bagi mereka azab yang pedih.'),
  ('id.indonesian', 9, 62, 'Mereka bersumpah kepada kamu dengan (nama) Allah untuk mencari keridhaanmu, padahal Allah dan Rasul-Nya itulah yang lebih patut mereka cari keridhaannya jika mereka adalah orang-orang yang mukmin.'),
  ('id.indonesian', 9, 63, 'Tidaklah mereka (orang-orang munafik itu) mengetahui bahwasanya barangsiapa menentang Allah dan Rasul-Nya, maka sesungguhnya nerakan jahannamlah baginya, kekal mereka di dalamnya. Itu adalah kehinaan yang besar.'),
  ('id.indonesian', 9, 64, 'Orang-orang yang munafik itu takut akan diturunkan terhadap mereka sesuatu surat yang menerangkan apa yang tersembunyi dalam hati mereka. Katakanlah kepada mereka: "Teruskanlah ejekan-ejekanmu (terhadap Allah dan rasul-Nya)". Sesungguhnya Allah akan menyatakan apa yang kamu takuti itu.'),
  ('id.indonesian', 9, 65, 'Dan jika kamu tanyakan kepada mereka (tentang apa yang mereka lakukan itu), tentulah mereka akan manjawab, "Sesungguhnya kami hanyalah bersenda gurau dan bermain-main saja". Katakanlah: "Apakah dengan Allah, ayat-ayat-Nya dan Rasul-Nya kamu selalu berolok-olok?"'),
  ('id.indonesian', 9, 66, 'Tidak usah kamu minta maaf, karena kamu kafir sesudah beriman. Jika Kami memaafkan segolongan kamu (lantaran mereka taubat), niscaya Kami akan mengazab golongan (yang lain) disebabkan mereka adalah orang-orang yang selalu berbuat dosa.'),
  ('id.indonesian', 9, 67, 'Orang-orang munafik laki-laki dan perempuan. sebagian dengan sebagian yang lain adalah sama, mereka menyuruh membuat yang munkar dan melarang berbuat yang ma\'ruf dan mereka menggenggamkan tangannya. Mereka telah lupa kepada Allah, maka Allah melupakan mereka. Sesungguhnya orang-orang munafik itu adalah orang-orang yang fasik.'),
  ('id.indonesian', 9, 68, 'Allah mengancam orang-orang munafik laki-laki dan perempuan dan orang-orang kafir dengan neraka Jahannam, mereka kekal di dalamnya. Cukuplah neraka itu bagi mereka, dan Allah melaknati mereka, dan bagi mereka azab yang kekal.'),
  ('id.indonesian', 9, 69, '(keadaan kamu hai orang-orang munafik dan musyrikin) adalah seperti keadaan orang-orang sebelum kamu, mereka lebih kuat daripada kamu, dan lebih banyak harta dan anak-anaknya dari kamu. Maka mereka telah menikmati bagian mereka, dan kamu telah menikmati bagian kamu sebagaimana orang-orang yang sebelummu menikmati bagiannya, dan kamu mempercakapkan (hal yang batil) sebagaimana mereka mempercakapkannya. Mereka itu amalannya menjadi sia-sia di dunia dan di akhirat; dan mereka itulah orang-orang yang merugi.'),
  ('id.indonesian', 9, 70, 'Belumkah datang kepada mereka berita penting tentang orang-orang yang sebelum mereka, (yaitu) kaum Nuh, \'Aad, Tsamud, kaum Ibrahim, penduduk Madyan dan negeri-negeri yang telah musnah?. Telah datang kepada mereka rasul-rasul dengan membawa keterangan yang nyata, maka Allah tidaklah sekali-kali menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.'),
  ('id.indonesian', 9, 71, 'Dan orang-orang yang beriman, lelaki dan perempuan, sebahagian mereka (adalah) menjadi penolong bagi sebahagian yang lain. Mereka menyuruh (mengerjakan) yang ma\'ruf, mencegah dari yang munkar, mendirikan shalat, menunaikan zakat dan mereka taat pada Allah dan Rasul-Nya. Mereka itu akan diberi rahmat oleh Allah; sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 72, 'Allah menjanjikan kepada orang-orang mukmin, lelaki dan perempuan, (akan mendapat) surga yang dibawahnya mengalir sungai-sungai, kekal mereka di dalamnya, dan (mendapat) tempat-tempat yang bagus di surga \'Adn. Dan keridhaan Allah adalah lebih besar; itu adalah keberuntungan yang besar.'),
  ('id.indonesian', 9, 73, 'Hai Nabi, berjihadlah (melawan) orang-orang kafir dan orang-orang munafik itu, dan bersikap keraslah terhadap mereka. Tempat mereka ialah jahannam. Dan itu adalah tempat kembali yang seburuk-buruknya.'),
  ('id.indonesian', 9, 74, 'Mereka (orang-orang munafik itu) bersumpah dengan (nama) Allah, bahwa mereka tidak mengatakan (sesuatu yang menyakitimu). Sesungguhnya mereka telah mengucapkan perkataan kekafiran, dan telah menjadi kafir sesudah Islam dan mengingini apa yang mereka tidak dapat mencapainya, dan mereka tidak mencela (Allah dan Rasul-Nya), kecuali karena Allah dan Rasul-Nya telah melimpahkan karunia-Nya kepada mereka. Maka jika mereka bertaubat, itu adalah lebih baik bagi mereka, dan jika mereka berpaling, niscaya Allah akan mengazab mereka dengan azab yang pedih di dunia dan akhirat; dan mereka sekali-kali tidaklah mempunyai pelindung dan tidak (pula) penolong di muka bumi.'),
  ('id.indonesian', 9, 75, 'Dan diantara mereka ada orang yang telah berikrar kepada Allah: "Sesungguhnya jika Allah memberikan sebahagian karunia-Nya kepada kami, pastilah kami akan bersedekah dan pastilah kami termasuk orang-orang yang saleh.'),
  ('id.indonesian', 9, 76, 'Maka setelah Allah memberikan kepada mereka sebahagian dari karunia-Nya, mereka kikir dengan karunia itu, dan berpaling, dan mereka memanglah orang-orang yang selalu membelakangi (kebenaran).'),
  ('id.indonesian', 9, 77, 'Maka Allah menimbulkan kemunafikan pada hati mereka sampai kepada waktu mereka menemui Allah, karena mereka telah memungkiri terhadap Allah apa yang telah mereka ikrarkan kepada-Nya dan juga karena mereka selalu berdusta.'),
  ('id.indonesian', 9, 78, 'Tidaklah mereka tahu bahwasanya Allah mengetahui rahasia dan bisikan mereka, dan bahwasanya Allah amat mengetahui segala yang ghaib.'),
  ('id.indonesian', 9, 79, '(Orang-orang munafik itu) yaitu orang-orang yang mencela orang-orang mukmin yang memberi sedekah dengan sukarela dan (mencela) orang-orang yang tidak memperoleh (untuk disedekahkan) selain sekedar kesanggupannya, maka orang-orang munafik itu menghina mereka. Allah akan membalas penghinaan mereka itu, dan untuk mereka azab yang pedih.'),
  ('id.indonesian', 9, 80, 'Kamu memohonkan ampun bagi mereka atau tidak kamu mohonkan ampun bagi mereka (adalah sama saja). Kendatipun kamu memohonkan ampun bagi mereka tujuh puluh kali, namun Allah sekali-kali tidak akan memberi ampunan kepada mereka. Yang demikian itu adalah karena mereka kafir kepada Allah dan Rasul-Nya. Dan Allah tidak memberi petunjuk kepada kaum yang fasik.'),
  ('id.indonesian', 9, 81, 'Orang-orang yang ditinggalkan (tidak ikut perang) itu, merasa gembira dengan tinggalnya mereka di belakang Rasulullah, dan mereka tidak suka berjihad dengan harta dan jiwa mereka pada jalan Allah dan mereka berkata: "Janganlah kamu berangkat (pergi berperang) dalam panas terik ini". Katakanlah: "Api neraka jahannam itu lebih sangat panas(nya)" jika mereka mengetahui.'),
  ('id.indonesian', 9, 82, 'Maka hendaklah mereka tertawa sedikit dan menangis banyak, sebagai pembalasan dari apa yang selalu mereka kerjakan.'),
  ('id.indonesian', 9, 83, 'Maka jika Allah mengembalikanmu kepada suatu golongan dari mereka, kemudian mereka minta izin kepadamu untuk keluar (pergi berperang), maka Katakanlah: "Kamu tidak boleh keluar bersamaku selama-lamanya dan tidak boleh memerangi musuh bersamaku. Sesungguhnya kamu telah rela tidak pergi berperang kali yang pertama. Karena itu duduklah bersama orang-orang yang tidak ikut berperang".'),
  ('id.indonesian', 9, 84, 'Dan janganlah kamu sekali-kali menyembahyangkan (jenazah) seorang yang mati di antara mereka, dan janganlah kamu berdiri (mendoakan) di kuburnya. Sesungguhnya mereka telah kafir kepada Allah dan Rasul-Nya dan mereka mati dalam keadaan fasik.'),
  ('id.indonesian', 9, 85, 'Dan janganlah harta benda dan anak-anak mereka menarik hatimu. Sesungguhnya Allah menghendaki akan mengazab mereka di dunia dengan harta dan anak-anak itu dan agar melayang nyawa mereka, dalam keadaan kafir.'),
  ('id.indonesian', 9, 86, 'Dan apabila diturunkan suatu surat (yang memerintahkan kepada orang munafik itu): "Berimanlah kamu kepada Allah dan berjihadlah beserta Rasul-Nya", niscaya orang-orang yang sanggup di antara mereka meminta izin kepadamu (untuk tidak berjihad) dan mereka berkata: "Biarkanlah kami berada bersama orang-orang yang duduk".'),
  ('id.indonesian', 9, 87, 'Mereka rela berada bersama orang-orang yang tidak berperang, dan hati mereka telah dikunci mati maka mereka tidak mengetahui (kebahagiaan beriman dan berjihad).'),
  ('id.indonesian', 9, 88, 'Tetapi Rasul dan orang-orang yang beriman bersama dia, mereka berjihad dengan harta dan diri mereka. Dan mereka itulah orang-orang yang memperoleh kebaikan, dan mereka itulah orang-orang yang beruntung.'),
  ('id.indonesian', 9, 89, 'Allah telah menyediakan bagi mereka surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Itulah kemenangan yang besar.'),
  ('id.indonesian', 9, 90, 'Dan datang (kepada Nabi) orang-orang yang mengemukakan \'uzur, yaitu orang-orang Arab Baswi agar diberi izin bagi mereka (untuk tidak berjihad), sedang orang-orang yang mendustakan Allah dan Rasul-Nya, duduk berdiam diri saja. Kelak orang-orang yang kafir di antara mereka itu akan ditimpa azab yang pedih.'),
  ('id.indonesian', 9, 91, 'Tiada dosa (lantaran tidak pergi berjihad) atas orang-orang yang lemah, orang-orang yang sakit dan atas orang-orang yang tidak memperoleh apa yang akan mereka nafkahkan, apabila mereka berlaku ikhlas kepada Allah dan Rasul-Nya. Tidak ada jalan sedikitpun untuk menyalahkan orang-orang yang berbuat baik. Dan Allah Maha Pengampun lagi Maha Penyayang,'),
  ('id.indonesian', 9, 92, 'dan tiada (pula) berdosa atas orang-orang yang apabila mereka datang kepadamu, supaya kamu memberi mereka kendaraan, lalu kamu berkata: "Aku tidak memperoleh kendaraan untuk membawamu". lalu mereka kembali, sedang mata mereka bercucuran air mata karena kesedihan, lantaran mereka tidak memperoleh apa yang akan mereka nafkahkan.'),
  ('id.indonesian', 9, 93, 'Sesungguhnya jalan (untuk menyalahkan) hanyalah terhadap orang-orang yang meminta izin kepadamu, padahal mereka itu orang-orang kaya. Mereka rela berada bersama orang-orang yang tidak ikut berperang dan Allah telah mengunci mati hati mereka, maka mereka tidak mengetahui (akibat perbuatan mereka).'),
  ('id.indonesian', 9, 94, 'Mereka (orang-orang munafik) mengemukakan \'uzurnya kepadamu, apabila kamu telah kembali kepada mereka (dari medan perang). Katakanlah: "Janganlah kamu mengemukakan \'uzur; kami tidak percaya lagi kepadamu, (karena) sesungguhnya Allah telah memberitahukan kepada kami beritamu yang sebenarnya. Dan Allah serta Rasul-Nya akan melihat pekerjaanmu, kemudian kamu dikembalikan kepada Yang mengetahui yang ghaib dan yang nyata, lalu Dia memberitahukan kepadamu apa yang telah kamu kerjakan.'),
  ('id.indonesian', 9, 95, 'Kelak mereka akan bersumpah kepadamu dengan nama Allah, apabila kamu kembali kepada mereka, supaya kamu berpaling dari mereka. Maka berpalinglah dari mereka; karena sesungguhnya mereka itu adalah najis dan tempat mereka jahannam; sebagai balasan atas apa yang telah mereka kerjakan.'),
  ('id.indonesian', 9, 96, 'Mereka akan bersumpah kepadamu, agar kamu ridha kepada mereka. Tetapi jika sekiranya kamu ridha kepada mereka, sesungguhnya Allah tidak ridha kepada orang-orang yang fasik itu.'),
  ('id.indonesian', 9, 97, 'Orang-orang Arab Badwi itu, lebih sangat kekafiran dan kemunafikannya, dan lebih wajar tidak mengetahui hukum-hukum yang diturunkan Allah kepada Rasul-Nya. Dan Allah Maha mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 98, 'Di antara orang-orang Arab Badwi itu ada orang yang memandang apa yang dinafkahkannya (di jalan Allah), sebagi suatu kerugian, dan dia menanti-nanti marabahaya menimpamu, merekalah yang akan ditimpa marabahaya. Dan Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 9, 99, 'Di antara orang-orang Arab Badwi itu ada orang yang beriman kepada Allah dan hari kemudian, dan memandang apa yang dinafkahkannya (di jalan Allah) itu, sebagai jalan untuk mendekatkannya kepada Allah dan sebagai jalan untuk memperoleh doa Rasul. Ketahuilah, sesungguhnya nafkah itu adalah suatu jalan bagi mereka untuk mendekatkan diri (kepada Allah). Kelak Allah akan memasukan mereka kedalam rahmat (surga)Nya; Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 9, 100, 'Orang-orang yang terdahulu lagi yang pertama-tama (masuk Islam) dari golongan muhajirin dan anshar dan orang-orang yang mengikuti mereka dengan baik, Allah ridha kepada mereka dan merekapun ridha kepada Allah dan Allah menyediakan bagi mereka surga-surga yang mengalir sungai-sungai di dalamnya selama-lamanya. Mereka kekal di dalamnya. Itulah kemenangan yang besar.'),
  ('id.indonesian', 9, 101, 'Di antara orang-orang Arab Badwi yang di sekelilingmu itu, ada orang-orang munafik; dan (juga) di antara penduduk Madinah. Mereka keterlaluan dalam kemunafikannya. Kamu (Muhammad) tidak mengetahui mereka, (tetapi) Kamilah yang mengetahui mereka. Nanti mereka akan Kami siksa dua kali kemudian mereka akan dikembalikan kepada azab yang besar.'),
  ('id.indonesian', 9, 102, 'Dan (ada pula) orang-orang lain yang mengakui dosa-dosa mereka, mereka mencampurbaurkan pekerjaan yang baik dengan pekerjaan lain yang buruk. Mudah-mudahan Allah menerima taubat mereka. Sesungguhnya Allah Maha Pengampun lagi maha Penyayang.'),
  ('id.indonesian', 9, 103, 'Ambillah zakat dari sebagian harta mereka, dengan zakat itu kamu membersihkan dan mensucikan mereka dan mendoalah untuk mereka. Sesungguhnya doa kamu itu (menjadi) ketenteraman jiwa bagi mereka. Dan Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 9, 104, 'Tidaklah mereka mengetahui, bahwasanya Allah menerima taubat dari hamba-hamba-Nya dan menerima zakat dan bahwasanya Allah Maha Penerima taubat lagi Maha Penyayang?'),
  ('id.indonesian', 9, 105, 'Dan Katakanlah: "Bekerjalah kamu, maka Allah dan Rasul-Nya serta orang-orang mukmin akan melihat pekerjaanmu itu, dan kamu akan dikembalikan kepada (Allah) Yang Mengetahui akan yang ghaib dan yang nyata, lalu diberitakan-Nya kepada kamu apa yang telah kamu kerjakan.'),
  ('id.indonesian', 9, 106, 'Dan ada (pula) orang-orang lain yang ditangguhkan sampai ada keputusan Allah; adakalanya Allah akan mengazab mereka dan adakalanya Allah akan menerima taubat mereka. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 107, 'Dan (di antara orang-orang munafik itu) ada orang-orang yang mendirikan masjid untuk menimbulkan kemudharatan (pada orang-orang mukmin), untuk kekafiran dan untuk memecah belah antara orang-orang mukmin serta menunggu kedatangan orang-orang yang telah memerangi Allah dan Rasul-Nya sejak dahulu. Mereka Sesungguhnya bersumpah: "Kami tidak menghendaki selain kebaikan". Dan Allah menjadi saksi bahwa sesungguhnya mereka itu adalah pendusta (dalam sumpahnya).'),
  ('id.indonesian', 9, 108, 'Janganlah kamu bersembahyang dalam mesjid itu selama-lamanya. Sesungguhnya mesjid yang didirikan atas dasar takwa (mesjid Quba), sejak hari pertama adalah lebih patut kamu sholat di dalamnya. Di dalamnya mesjid itu ada orang-orang yang ingin membersihkan diri. Dan sesungguhnya Allah menyukai orang-orang yang bersih.'),
  ('id.indonesian', 9, 109, 'Maka apakah orang-orang yang mendirikan mesjidnya di atas dasar takwa kepada Allah dan keridhaan-(Nya) itu yang baik, ataukah orang-orang yang mendirikan bangunannya di tepi jurang yang runtuh, lalu bangunannya itu jatuh bersama-sama dengan dia ke dalam neraka Jahannam. Dan Allah tidak memberikan petunjuk kepada orang-orang yang zalim.'),
  ('id.indonesian', 9, 110, 'Bangunan-bangunan yang mereka dirikan itu senantiasa menjadi pangkal keraguan dalam hati mereka, kecuali bila hati mereka itu telah hancur. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 9, 111, 'Sesungguhnya Allah telah membeli dari orang-orang mukmin diri dan harta mereka dengan memberikan surga untuk mereka. Mereka berperang pada jalan Allah; lalu mereka membunuh atau terbunuh. (Itu telah menjadi) janji yang benar dari Allah di dalam Taurat, Injil dan Al Quran. Dan siapakah yang lebih menepati janjinya (selain) daripada Allah? Maka bergembiralah dengan jual beli yang telah kamu lakukan itu, dan itulah kemenangan yang besar.'),
  ('id.indonesian', 9, 112, 'Mereka itu adalah orang-orang yang bertaubat, yang beribadat, yang memuji, yang melawat, yang ruku\', yang sujud, yang menyuruh berbuat ma\'ruf dan mencegah berbuat munkar dan yang memelihara hukum-hukum Allah. Dan gembirakanlah orang-orang mukmin itu.'),
  ('id.indonesian', 9, 113, 'Tiadalah sepatutnya bagi Nabi dan orang-orang yang beriman memintakan ampun (kepada Allah) bagi orang-orang musyrik, walaupun orang-orang musyrik itu adalah kaum kerabat(nya), sesudah jelas bagi mereka, bahwasanya orang-orang musyrik itu adalah penghuni neraka jahanam.'),
  ('id.indonesian', 9, 114, 'Dan permintaan ampun dari Ibrahim (kepada Allah) untuk bapaknya tidak lain hanyalah karena suatu janji yang telah diikrarkannya kepada bapaknya itu. Maka, tatkala jelas bagi Ibrahim bahwa bapaknya itu adalah musuh Allah, maka Ibrahim berlepas diri dari padanya. Sesungguhnya Ibrahim adalah seorang yang sangat lembut hatinya lagi penyantun.'),
  ('id.indonesian', 9, 115, 'Dan Allah sekali-kali tidak akan menyesatkan suatu kaum, sesudah Allah memberi petunjuk kepada mereka sehingga dijelaskan-Nya kepada mereka apa yang harus mereka jauhi. Sesungguhnya Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 9, 116, 'Sesungguhnya kepunyaan Allah-lah kerajaan langit dan bumi. Dia menghidupkan dan mematikan. Dan sekali-kali tidak ada pelindung dan penolong bagimu selain Allah.'),
  ('id.indonesian', 9, 117, 'Sesungguhnya Allah telah menerima taubat Nabi, orang-orang muhajirin dan orang-orang anshar yang mengikuti Nabi dalam masa kesulitan, setelah hati segolongan dari mereka hampir berpaling, kemudian Allah menerima taubat mereka itu. Sesungguhnya Allah Maha Pengasih lagi Maha Penyayang kepada mereka,'),
  ('id.indonesian', 9, 118, 'dan terhadap tiga orang yang ditangguhkan (penerimaan taubat) mereka, hingga apabila bumi telah menjadi sempit bagi mereka, padahal bumi itu luas dan jiwa merekapun telah sempit (pula terasa) oleh mereka, serta mereka telah mengetahui bahwa tidak ada tempat lari dari (siksa) Allah, melainkan kepada-Nya saja. Kemudian Allah menerima taubat mereka agar mereka tetap dalam taubatnya. Sesungguhnya Allah-lah Yang maha Penerima taubat lagi Maha Penyayang.'),
  ('id.indonesian', 9, 119, 'Hai orang-orang yang beriman bertakwalah kepada Allah, dan hendaklah kamu bersama orang-orang yang benar.'),
  ('id.indonesian', 9, 120, 'Tidaklah sepatutnya bagi penduduk Madinah dan orang-orang Arab Badwi yang berdiam di sekitar mereka, tidak turut menyertai Rasulullah (berperang) dan tidak patut (pula) bagi mereka lebih mencintai diri mereka daripada mencintai diri Rasul. Yang demikian itu ialah karena mereka tidak ditimpa kehausan, kepayahan dan kelaparan pada jalan Allah, dan tidak (pula) menginjak suatu tempat yang membangkitkan amarah orang-orang kafir, dan tidak menimpakan sesuatu bencana kepada musuh, melainkan dituliskanlah bagi mereka dengan yang demikian itu suatu amal saleh. Sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik,'),
  ('id.indonesian', 9, 121, 'dan mereka tiada menafkahkan suatu nafkah yang kecil dan tidak (pula) yang besar dan tidak melintasi suatu lembah, melainkan dituliskan bagi mereka (amal saleh pula) karena Allah akan memberi balasan kepada mereka yang lebih baik dari apa yang telah mereka kerjakan.'),
  ('id.indonesian', 9, 122, 'Tidak sepatutnya bagi mukminin itu pergi semuanya (ke medan perang). Mengapa tidak pergi dari tiap-tiap golongan di antara mereka beberapa orang untuk memperdalam pengetahuan mereka tentang agama dan untuk memberi peringatan kepada kaumnya apabila mereka telah kembali kepadanya, supaya mereka itu dapat menjaga dirinya.'),
  ('id.indonesian', 9, 123, 'Hai orang-orang yang beriman, perangilah orang-orang kafir yang di sekitar kamu itu, dan hendaklah mereka menemui kekerasan daripadamu, dan ketahuilah, bahwasanya Allah bersama orang-orang yang bertakwa.'),
  ('id.indonesian', 9, 124, 'Dan apabila diturunkan suatu surat, maka di antara mereka (orang-orang munafik) ada yang berkata: "Siapakah di antara kamu yang bertambah imannya dengan (turannya) surat ini?" Adapun orang-orang yang beriman, maka surat ini menambah imannya, dan mereka merasa gembira.'),
  ('id.indonesian', 9, 125, 'Dan adapun orang-orang yang di dalam hati mereka ada penyakit, maka dengan surat itu bertambah kekafiran mereka, disamping kekafirannya (yang telah ada) dan mereka mati dalam keadaan kafir.'),
  ('id.indonesian', 9, 126, 'Dan tidaklah mereka (orang-orang munafik) memperhatikan bahwa mereka diuji sekali atau dua kali setiap tahun, dan mereka tidak (juga) bertaubat dan tidak (pula) mengambil pelajaran?'),
  ('id.indonesian', 9, 127, 'Dan apabila diturunkan satu surat, sebagian mereka memandang kepada yang lain (sambil berkata): "Adakah seorang dari (orang-orang muslimin) yang melihat kamu?" Sesudah itu merekapun pergi. Allah telah memalingkan hati mereka disebabkan mereka adalah kaum yang tidak mengerti.'),
  ('id.indonesian', 9, 128, 'Sungguh telah datang kepadamu seorang Rasul dari kaummu sendiri, berat terasa olehnya penderitaanmu, sangat menginginkan (keimanan dan keselamatan) bagimu, amat belas kasihan lagi penyayang terhadap orang-orang mukmin.'),
  ('id.indonesian', 9, 129, 'Jika mereka berpaling (dari keimanan), maka katakanlah: "Cukuplah Allah bagiku; tidak ada Tuhan selain Dia. Hanya kepada-Nya aku bertawakkal dan Dia adalah Tuhan yang memiliki \'Arsy yang agung".')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (8, 41, 1201, '۞ وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍۢ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 182, 10, 73, 0),
  (8, 42, 1202, 'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ ۚ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَٰدِ ۙ وَلَٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًۭا كَانَ مَفْعُولًۭا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍۢ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍۢ ۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ', 182, 10, 73, 0),
  (8, 43, 1203, 'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًۭا ۖ وَلَوْ أَرَىٰكَهُمْ كَثِيرًۭا لَّفَشِلْتُمْ وَلَتَنَٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَ ۗ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 182, 10, 73, 0),
  (8, 44, 1204, 'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًۭا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًۭا كَانَ مَفْعُولًۭا ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 182, 10, 73, 0),
  (8, 45, 1205, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةًۭ فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًۭا لَّعَلَّكُمْ تُفْلِحُونَ', 182, 10, 73, 0),
  (8, 46, 1206, 'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ ۖ وَٱصْبِرُوٓا۟ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ', 183, 10, 73, 0),
  (8, 47, 1207, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِم بَطَرًۭا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۚ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌۭ', 183, 10, 73, 0),
  (8, 48, 1208, 'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌۭ لَّكُمْ ۖ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌۭ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ ۚ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ', 183, 10, 73, 0),
  (8, 49, 1209, 'إِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمْ ۗ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 183, 10, 73, 0),
  (8, 50, 1210, 'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ۙ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 183, 10, 73, 0),
  (8, 51, 1211, 'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 183, 10, 73, 0),
  (8, 52, 1212, 'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ إِنَّ ٱللَّهَ قَوِىٌّۭ شَدِيدُ ٱلْعِقَابِ', 183, 10, 73, 0),
  (8, 53, 1213, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًۭا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۙ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 184, 10, 73, 0),
  (8, 54, 1214, 'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَٰتِ رَبِّهِمْ فَأَهْلَكْنَٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ ۚ وَكُلٌّۭ كَانُوا۟ ظَٰلِمِينَ', 184, 10, 73, 0),
  (8, 55, 1215, 'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ', 184, 10, 73, 0),
  (8, 56, 1216, 'ٱلَّذِينَ عَٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍۢ وَهُمْ لَا يَتَّقُونَ', 184, 10, 73, 0),
  (8, 57, 1217, 'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ', 184, 10, 73, 0),
  (8, 58, 1218, 'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةًۭ فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ', 184, 10, 73, 0),
  (8, 59, 1219, 'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ ۚ إِنَّهُمْ لَا يُعْجِزُونَ', 184, 10, 73, 0),
  (8, 60, 1220, 'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍۢ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍۢ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ', 184, 10, 73, 0),
  (8, 61, 1221, '۞ وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 184, 10, 74, 0),
  (8, 62, 1222, 'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ ۚ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ', 185, 10, 74, 0),
  (8, 63, 1223, 'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًۭا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُۥ عَزِيزٌ حَكِيمٌۭ', 185, 10, 74, 0),
  (8, 64, 1224, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ', 185, 10, 74, 0),
  (8, 65, 1225, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ ۚ إِن يَكُن مِّنكُمْ عِشْرُونَ صَٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌۭ يَغْلِبُوٓا۟ أَلْفًۭا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌۭ لَّا يَفْقَهُونَ', 185, 10, 74, 0),
  (8, 66, 1226, 'ٱلْـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًۭا ۚ فَإِن يَكُن مِّنكُم مِّا۟ئَةٌۭ صَابِرَةٌۭ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُمْ أَلْفٌۭ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ', 185, 10, 74, 0),
  (8, 67, 1227, 'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ ۚ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْءَاخِرَةَ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌۭ', 185, 10, 74, 0),
  (8, 68, 1228, 'لَّوْلَا كِتَٰبٌۭ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌۭ', 185, 10, 74, 0),
  (8, 69, 1229, 'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَٰلًۭا طَيِّبًۭا ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 185, 10, 74, 0),
  (8, 70, 1230, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًۭا يُؤْتِكُمْ خَيْرًۭا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 186, 10, 74, 0),
  (8, 71, 1231, 'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 186, 10, 74, 0),
  (8, 72, 1232, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۚ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ ۚ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَٰقٌۭ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 186, 10, 74, 0),
  (8, 73, 1233, 'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌۭ فِى ٱلْأَرْضِ وَفَسَادٌۭ كَبِيرٌۭ', 186, 10, 74, 0),
  (8, 74, 1234, 'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّۭا ۚ لَّهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 186, 10, 74, 0),
  (8, 75, 1235, 'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ مَعَكُمْ فَأُو۟لَٰٓئِكَ مِنكُمْ ۚ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍۢ فِى كِتَٰبِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 186, 10, 74, 0),
  (9, 1, 1236, 'بَرَآءَةٌۭ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ', 187, 10, 75, 0),
  (9, 2, 1237, 'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍۢ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۙ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَٰفِرِينَ', 187, 10, 75, 0),
  (9, 3, 1238, 'وَأَذَٰنٌۭ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌۭ مِّنَ ٱلْمُشْرِكِينَ ۙ وَرَسُولُهُۥ ۚ فَإِن تُبْتُمْ فَهُوَ خَيْرٌۭ لَّكُمْ ۖ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ', 187, 10, 75, 0),
  (9, 4, 1239, 'إِلَّا ٱلَّذِينَ عَٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًۭٔا وَلَمْ يُظَٰهِرُوا۟ عَلَيْكُمْ أَحَدًۭا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 187, 10, 75, 0),
  (9, 5, 1240, 'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍۢ ۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 187, 10, 75, 0),
  (9, 6, 1241, 'وَإِنْ أَحَدٌۭ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْلَمُونَ', 187, 10, 75, 0),
  (9, 7, 1242, 'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ فَمَا ٱسْتَقَٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ', 188, 10, 75, 0),
  (9, 8, 1243, 'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّۭا وَلَا ذِمَّةًۭ ۚ يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَٰسِقُونَ', 188, 10, 75, 0),
  (9, 9, 1244, 'ٱشْتَرَوْا۟ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًۭا قَلِيلًۭا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 188, 10, 75, 0),
  (9, 10, 1245, 'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّۭا وَلَا ذِمَّةًۭ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ', 188, 10, 75, 0),
  (9, 11, 1246, 'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ ۗ وَنُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 188, 10, 75, 0),
  (9, 12, 1247, 'وَإِن نَّكَثُوٓا۟ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ ۙ إِنَّهُمْ لَآ أَيْمَٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ', 188, 10, 75, 0),
  (9, 13, 1248, 'أَلَا تُقَٰتِلُونَ قَوْمًۭا نَّكَثُوٓا۟ أَيْمَٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ ۚ أَتَخْشَوْنَهُمْ ۚ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ', 188, 10, 75, 0),
  (9, 14, 1249, 'قَٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍۢ مُّؤْمِنِينَ', 189, 10, 75, 0),
  (9, 15, 1250, 'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ ۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 189, 10, 75, 0),
  (9, 16, 1251, 'أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَٰهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةًۭ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 189, 10, 75, 0),
  (9, 17, 1252, 'مَا كَانَ لِلْمُشْرِكِينَ أَن يَعْمُرُوا۟ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلْكُفْرِ ۚ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ وَفِى ٱلنَّارِ هُمْ خَٰلِدُونَ', 189, 10, 75, 0),
  (9, 18, 1253, 'إِنَّمَا يَعْمُرُ مَسَٰجِدَ ٱللَّهِ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمْ يَخْشَ إِلَّا ٱللَّهَ ۖ فَعَسَىٰٓ أُو۟لَٰٓئِكَ أَن يَكُونُوا۟ مِنَ ٱلْمُهْتَدِينَ', 189, 10, 75, 0),
  (9, 19, 1254, '۞ أَجَعَلْتُمْ سِقَايَةَ ٱلْحَآجِّ وَعِمَارَةَ ٱلْمَسْجِدِ ٱلْحَرَامِ كَمَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَجَٰهَدَ فِى سَبِيلِ ٱللَّهِ ۚ لَا يَسْتَوُۥنَ عِندَ ٱللَّهِ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 189, 10, 76, 0),
  (9, 20, 1255, 'ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ أَعْظَمُ دَرَجَةً عِندَ ٱللَّهِ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 189, 10, 76, 0),
  (9, 21, 1256, 'يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَةٍۢ مِّنْهُ وَرِضْوَٰنٍۢ وَجَنَّٰتٍۢ لَّهُمْ فِيهَا نَعِيمٌۭ مُّقِيمٌ', 190, 10, 76, 0),
  (9, 22, 1257, 'خَٰلِدِينَ فِيهَآ أَبَدًا ۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ', 190, 10, 76, 0),
  (9, 23, 1258, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوٓا۟ ءَابَآءَكُمْ وَإِخْوَٰنَكُمْ أَوْلِيَآءَ إِنِ ٱسْتَحَبُّوا۟ ٱلْكُفْرَ عَلَى ٱلْإِيمَٰنِ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 190, 10, 76, 0),
  (9, 24, 1259, 'قُلْ إِن كَانَ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ وَإِخْوَٰنُكُمْ وَأَزْوَٰجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَٰلٌ ٱقْتَرَفْتُمُوهَا وَتِجَٰرَةٌۭ تَخْشَوْنَ كَسَادَهَا وَمَسَٰكِنُ تَرْضَوْنَهَآ أَحَبَّ إِلَيْكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادٍۢ فِى سَبِيلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 190, 10, 76, 0),
  (9, 25, 1260, 'لَقَدْ نَصَرَكُمُ ٱللَّهُ فِى مَوَاطِنَ كَثِيرَةٍۢ ۙ وَيَوْمَ حُنَيْنٍ ۙ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْـًۭٔا وَضَاقَتْ عَلَيْكُمُ ٱلْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ', 190, 10, 76, 0),
  (9, 26, 1261, 'ثُمَّ أَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَنزَلَ جُنُودًۭا لَّمْ تَرَوْهَا وَعَذَّبَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ', 190, 10, 76, 0),
  (9, 27, 1262, 'ثُمَّ يَتُوبُ ٱللَّهُ مِنۢ بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 191, 10, 76, 0),
  (9, 28, 1263, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْمُشْرِكُونَ نَجَسٌۭ فَلَا يَقْرَبُوا۟ ٱلْمَسْجِدَ ٱلْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا ۚ وَإِنْ خِفْتُمْ عَيْلَةًۭ فَسَوْفَ يُغْنِيكُمُ ٱللَّهُ مِن فَضْلِهِۦٓ إِن شَآءَ ۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمٌۭ', 191, 10, 76, 0),
  (9, 29, 1264, 'قَٰتِلُوا۟ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَلَا بِٱلْيَوْمِ ٱلْءَاخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا يَدِينُونَ دِينَ ٱلْحَقِّ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ حَتَّىٰ يُعْطُوا۟ ٱلْجِزْيَةَ عَن يَدٍۢ وَهُمْ صَٰغِرُونَ', 191, 10, 76, 0),
  (9, 30, 1265, 'وَقَالَتِ ٱلْيَهُودُ عُزَيْرٌ ٱبْنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَٰرَى ٱلْمَسِيحُ ٱبْنُ ٱللَّهِ ۖ ذَٰلِكَ قَوْلُهُم بِأَفْوَٰهِهِمْ ۖ يُضَٰهِـُٔونَ قَوْلَ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ ۚ قَٰتَلَهُمُ ٱللَّهُ ۚ أَنَّىٰ يُؤْفَكُونَ', 191, 10, 76, 0),
  (9, 31, 1266, 'ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًۭا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًۭا وَٰحِدًۭا ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ۚ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ', 191, 10, 76, 0),
  (9, 32, 1267, 'يُرِيدُونَ أَن يُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَيَأْبَى ٱللَّهُ إِلَّآ أَن يُتِمَّ نُورَهُۥ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 192, 10, 76, 0),
  (9, 33, 1268, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 192, 10, 76, 0),
  (9, 34, 1269, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًۭا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۗ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍۢ', 192, 10, 77, 0),
  (9, 35, 1270, 'يَوْمَ يُحْمَىٰ عَلَيْهَا فِى نَارِ جَهَنَّمَ فَتُكْوَىٰ بِهَا جِبَاهُهُمْ وَجُنُوبُهُمْ وَظُهُورُهُمْ ۖ هَٰذَا مَا كَنَزْتُمْ لِأَنفُسِكُمْ فَذُوقُوا۟ مَا كُنتُمْ تَكْنِزُونَ', 192, 10, 77, 0),
  (9, 36, 1271, 'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًۭا فِى كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌۭ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ ۚ وَقَٰتِلُوا۟ ٱلْمُشْرِكِينَ كَآفَّةًۭ كَمَا يُقَٰتِلُونَكُمْ كَآفَّةًۭ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 192, 10, 77, 0),
  (9, 37, 1272, 'إِنَّمَا ٱلنَّسِىٓءُ زِيَادَةٌۭ فِى ٱلْكُفْرِ ۖ يُضَلُّ بِهِ ٱلَّذِينَ كَفَرُوا۟ يُحِلُّونَهُۥ عَامًۭا وَيُحَرِّمُونَهُۥ عَامًۭا لِّيُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَيُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُ ۚ زُيِّنَ لَهُمْ سُوٓءُ أَعْمَٰلِهِمْ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 193, 10, 77, 0),
  (9, 38, 1273, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَا لَكُمْ إِذَا قِيلَ لَكُمُ ٱنفِرُوا۟ فِى سَبِيلِ ٱللَّهِ ٱثَّاقَلْتُمْ إِلَى ٱلْأَرْضِ ۚ أَرَضِيتُم بِٱلْحَيَوٰةِ ٱلدُّنْيَا مِنَ ٱلْءَاخِرَةِ ۚ فَمَا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا فِى ٱلْءَاخِرَةِ إِلَّا قَلِيلٌ', 193, 10, 77, 0),
  (9, 39, 1274, 'إِلَّا تَنفِرُوا۟ يُعَذِّبْكُمْ عَذَابًا أَلِيمًۭا وَيَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّوهُ شَيْـًۭٔا ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 193, 10, 77, 0),
  (9, 40, 1275, 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا ۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍۢ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ ۗ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 193, 10, 77, 0),
  (9, 41, 1276, 'ٱنفِرُوا۟ خِفَافًۭا وَثِقَالًۭا وَجَٰهِدُوا۟ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ فِى سَبِيلِ ٱللَّهِ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 194, 10, 77, 0),
  (9, 42, 1277, 'لَوْ كَانَ عَرَضًۭا قَرِيبًۭا وَسَفَرًۭا قَاصِدًۭا لَّٱتَّبَعُوكَ وَلَٰكِنۢ بَعُدَتْ عَلَيْهِمُ ٱلشُّقَّةُ ۚ وَسَيَحْلِفُونَ بِٱللَّهِ لَوِ ٱسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَٱللَّهُ يَعْلَمُ إِنَّهُمْ لَكَٰذِبُونَ', 194, 10, 77, 0),
  (9, 43, 1278, 'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ ٱلَّذِينَ صَدَقُوا۟ وَتَعْلَمَ ٱلْكَٰذِبِينَ', 194, 10, 77, 0),
  (9, 44, 1279, 'لَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلْمُتَّقِينَ', 194, 10, 77, 0),
  (9, 45, 1280, 'إِنَّمَا يَسْتَـْٔذِنُكَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَٱرْتَابَتْ قُلُوبُهُمْ فَهُمْ فِى رَيْبِهِمْ يَتَرَدَّدُونَ', 194, 10, 77, 0),
  (9, 46, 1281, '۞ وَلَوْ أَرَادُوا۟ ٱلْخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةًۭ وَلَٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ ٱقْعُدُوا۟ مَعَ ٱلْقَٰعِدِينَ', 194, 10, 78, 0),
  (9, 47, 1282, 'لَوْ خَرَجُوا۟ فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًۭا وَلَأَوْضَعُوا۟ خِلَٰلَكُمْ يَبْغُونَكُمُ ٱلْفِتْنَةَ وَفِيكُمْ سَمَّٰعُونَ لَهُمْ ۗ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 194, 10, 78, 0),
  (9, 48, 1283, 'لَقَدِ ٱبْتَغَوُا۟ ٱلْفِتْنَةَ مِن قَبْلُ وَقَلَّبُوا۟ لَكَ ٱلْأُمُورَ حَتَّىٰ جَآءَ ٱلْحَقُّ وَظَهَرَ أَمْرُ ٱللَّهِ وَهُمْ كَٰرِهُونَ', 195, 10, 78, 0),
  (9, 49, 1284, 'وَمِنْهُم مَّن يَقُولُ ٱئْذَن لِّى وَلَا تَفْتِنِّىٓ ۚ أَلَا فِى ٱلْفِتْنَةِ سَقَطُوا۟ ۗ وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌۢ بِٱلْكَٰفِرِينَ', 195, 10, 78, 0),
  (9, 50, 1285, 'إِن تُصِبْكَ حَسَنَةٌۭ تَسُؤْهُمْ ۖ وَإِن تُصِبْكَ مُصِيبَةٌۭ يَقُولُوا۟ قَدْ أَخَذْنَآ أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوا۟ وَّهُمْ فَرِحُونَ', 195, 10, 78, 0),
  (9, 51, 1286, 'قُل لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوْلَىٰنَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 195, 10, 78, 0),
  (9, 52, 1287, 'قُلْ هَلْ تَرَبَّصُونَ بِنَآ إِلَّآ إِحْدَى ٱلْحُسْنَيَيْنِ ۖ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ ٱللَّهُ بِعَذَابٍۢ مِّنْ عِندِهِۦٓ أَوْ بِأَيْدِينَا ۖ فَتَرَبَّصُوٓا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ', 195, 10, 78, 0),
  (9, 53, 1288, 'قُلْ أَنفِقُوا۟ طَوْعًا أَوْ كَرْهًۭا لَّن يُتَقَبَّلَ مِنكُمْ ۖ إِنَّكُمْ كُنتُمْ قَوْمًۭا فَٰسِقِينَ', 195, 10, 78, 0),
  (9, 54, 1289, 'وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَٰتُهُمْ إِلَّآ أَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا يَأْتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَٰرِهُونَ', 195, 10, 78, 0),
  (9, 55, 1290, 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 196, 10, 78, 0),
  (9, 56, 1291, 'وَيَحْلِفُونَ بِٱللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌۭ يَفْرَقُونَ', 196, 10, 78, 0),
  (9, 57, 1292, 'لَوْ يَجِدُونَ مَلْجَـًٔا أَوْ مَغَٰرَٰتٍ أَوْ مُدَّخَلًۭا لَّوَلَّوْا۟ إِلَيْهِ وَهُمْ يَجْمَحُونَ', 196, 10, 78, 0),
  (9, 58, 1293, 'وَمِنْهُم مَّن يَلْمِزُكَ فِى ٱلصَّدَقَٰتِ فَإِنْ أُعْطُوا۟ مِنْهَا رَضُوا۟ وَإِن لَّمْ يُعْطَوْا۟ مِنْهَآ إِذَا هُمْ يَسْخَطُونَ', 196, 10, 78, 0),
  (9, 59, 1294, 'وَلَوْ أَنَّهُمْ رَضُوا۟ مَآ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسْبُنَا ٱللَّهُ سَيُؤْتِينَا ٱللَّهُ مِن فَضْلِهِۦ وَرَسُولُهُۥٓ إِنَّآ إِلَى ٱللَّهِ رَٰغِبُونَ', 196, 10, 78, 0),
  (9, 60, 1295, '۞ إِنَّمَا ٱلصَّدَقَٰتُ لِلْفُقَرَآءِ وَٱلْمَسَٰكِينِ وَٱلْعَٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ ۖ فَرِيضَةًۭ مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 196, 10, 79, 0),
  (9, 61, 1296, 'وَمِنْهُمُ ٱلَّذِينَ يُؤْذُونَ ٱلنَّبِىَّ وَيَقُولُونَ هُوَ أُذُنٌۭ ۚ قُلْ أُذُنُ خَيْرٍۢ لَّكُمْ يُؤْمِنُ بِٱللَّهِ وَيُؤْمِنُ لِلْمُؤْمِنِينَ وَرَحْمَةٌۭ لِّلَّذِينَ ءَامَنُوا۟ مِنكُمْ ۚ وَٱلَّذِينَ يُؤْذُونَ رَسُولَ ٱللَّهِ لَهُمْ عَذَابٌ أَلِيمٌۭ', 196, 10, 79, 0),
  (9, 62, 1297, 'يَحْلِفُونَ بِٱللَّهِ لَكُمْ لِيُرْضُوكُمْ وَٱللَّهُ وَرَسُولُهُۥٓ أَحَقُّ أَن يُرْضُوهُ إِن كَانُوا۟ مُؤْمِنِينَ', 197, 10, 79, 0),
  (9, 63, 1298, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًۭا فِيهَا ۚ ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ', 197, 10, 79, 0),
  (9, 64, 1299, 'يَحْذَرُ ٱلْمُنَٰفِقُونَ أَن تُنَزَّلَ عَلَيْهِمْ سُورَةٌۭ تُنَبِّئُهُم بِمَا فِى قُلُوبِهِمْ ۚ قُلِ ٱسْتَهْزِءُوٓا۟ إِنَّ ٱللَّهَ مُخْرِجٌۭ مَّا تَحْذَرُونَ', 197, 10, 79, 0),
  (9, 65, 1300, 'وَلَئِن سَأَلْتَهُمْ لَيَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلْعَبُ ۚ قُلْ أَبِٱللَّهِ وَءَايَٰتِهِۦ وَرَسُولِهِۦ كُنتُمْ تَسْتَهْزِءُونَ', 197, 10, 79, 0),
  (9, 66, 1301, 'لَا تَعْتَذِرُوا۟ قَدْ كَفَرْتُم بَعْدَ إِيمَٰنِكُمْ ۚ إِن نَّعْفُ عَن طَآئِفَةٍۢ مِّنكُمْ نُعَذِّبْ طَآئِفَةًۢ بِأَنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 197, 10, 79, 0),
  (9, 67, 1302, 'ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ بَعْضُهُم مِّنۢ بَعْضٍۢ ۚ يَأْمُرُونَ بِٱلْمُنكَرِ وَيَنْهَوْنَ عَنِ ٱلْمَعْرُوفِ وَيَقْبِضُونَ أَيْدِيَهُمْ ۚ نَسُوا۟ ٱللَّهَ فَنَسِيَهُمْ ۗ إِنَّ ٱلْمُنَٰفِقِينَ هُمُ ٱلْفَٰسِقُونَ', 197, 10, 79, 0),
  (9, 68, 1303, 'وَعَدَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْكُفَّارَ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۚ هِىَ حَسْبُهُمْ ۚ وَلَعَنَهُمُ ٱللَّهُ ۖ وَلَهُمْ عَذَابٌۭ مُّقِيمٌۭ', 197, 10, 79, 0),
  (9, 69, 1304, 'كَٱلَّذِينَ مِن قَبْلِكُمْ كَانُوٓا۟ أَشَدَّ مِنكُمْ قُوَّةًۭ وَأَكْثَرَ أَمْوَٰلًۭا وَأَوْلَٰدًۭا فَٱسْتَمْتَعُوا۟ بِخَلَٰقِهِمْ فَٱسْتَمْتَعْتُم بِخَلَٰقِكُمْ كَمَا ٱسْتَمْتَعَ ٱلَّذِينَ مِن قَبْلِكُم بِخَلَٰقِهِمْ وَخُضْتُمْ كَٱلَّذِى خَاضُوٓا۟ ۚ أُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 198, 10, 79, 0),
  (9, 70, 1305, 'أَلَمْ يَأْتِهِمْ نَبَأُ ٱلَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍۢ وَعَادٍۢ وَثَمُودَ وَقَوْمِ إِبْرَٰهِيمَ وَأَصْحَٰبِ مَدْيَنَ وَٱلْمُؤْتَفِكَٰتِ ۚ أَتَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ ۖ فَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 198, 10, 79, 0),
  (9, 71, 1306, 'وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۚ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌۭ', 198, 10, 79, 0),
  (9, 72, 1307, 'وَعَدَ ٱللَّهُ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةًۭ فِى جَنَّٰتِ عَدْنٍۢ ۚ وَرِضْوَٰنٌۭ مِّنَ ٱللَّهِ أَكْبَرُ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 198, 10, 79, 0),
  (9, 73, 1308, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 199, 10, 79, 0),
  (9, 74, 1309, 'يَحْلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدْ قَالُوا۟ كَلِمَةَ ٱلْكُفْرِ وَكَفَرُوا۟ بَعْدَ إِسْلَٰمِهِمْ وَهَمُّوا۟ بِمَا لَمْ يَنَالُوا۟ ۚ وَمَا نَقَمُوٓا۟ إِلَّآ أَنْ أَغْنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضْلِهِۦ ۚ فَإِن يَتُوبُوا۟ يَكُ خَيْرًۭا لَّهُمْ ۖ وَإِن يَتَوَلَّوْا۟ يُعَذِّبْهُمُ ٱللَّهُ عَذَابًا أَلِيمًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۚ وَمَا لَهُمْ فِى ٱلْأَرْضِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ', 199, 10, 79, 0),
  (9, 75, 1310, '۞ وَمِنْهُم مَّنْ عَٰهَدَ ٱللَّهَ لَئِنْ ءَاتَىٰنَا مِن فَضْلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّٰلِحِينَ', 199, 10, 80, 0),
  (9, 76, 1311, 'فَلَمَّآ ءَاتَىٰهُم مِّن فَضْلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ', 199, 10, 80, 0),
  (9, 77, 1312, 'فَأَعْقَبَهُمْ نِفَاقًۭا فِى قُلُوبِهِمْ إِلَىٰ يَوْمِ يَلْقَوْنَهُۥ بِمَآ أَخْلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ يَكْذِبُونَ', 199, 10, 80, 0),
  (9, 78, 1313, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ سِرَّهُمْ وَنَجْوَىٰهُمْ وَأَنَّ ٱللَّهَ عَلَّٰمُ ٱلْغُيُوبِ', 199, 10, 80, 0),
  (9, 79, 1314, 'ٱلَّذِينَ يَلْمِزُونَ ٱلْمُطَّوِّعِينَ مِنَ ٱلْمُؤْمِنِينَ فِى ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ ۙ سَخِرَ ٱللَّهُ مِنْهُمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 199, 10, 80, 0),
  (9, 80, 1315, 'ٱسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِن تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةًۭ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ ذَٰلِكَ بِأَنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 200, 10, 80, 0),
  (9, 81, 1316, 'فَرِحَ ٱلْمُخَلَّفُونَ بِمَقْعَدِهِمْ خِلَٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوٓا۟ أَن يُجَٰهِدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِى ٱلْحَرِّ ۗ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّۭا ۚ لَّوْ كَانُوا۟ يَفْقَهُونَ', 200, 10, 80, 0),
  (9, 82, 1317, 'فَلْيَضْحَكُوا۟ قَلِيلًۭا وَلْيَبْكُوا۟ كَثِيرًۭا جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 200, 10, 80, 0),
  (9, 83, 1318, 'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَآئِفَةٍۢ مِّنْهُمْ فَٱسْتَـْٔذَنُوكَ لِلْخُرُوجِ فَقُل لَّن تَخْرُجُوا۟ مَعِىَ أَبَدًۭا وَلَن تُقَٰتِلُوا۟ مَعِىَ عَدُوًّا ۖ إِنَّكُمْ رَضِيتُم بِٱلْقُعُودِ أَوَّلَ مَرَّةٍۢ فَٱقْعُدُوا۟ مَعَ ٱلْخَٰلِفِينَ', 200, 10, 80, 0),
  (9, 84, 1319, 'وَلَا تُصَلِّ عَلَىٰٓ أَحَدٍۢ مِّنْهُم مَّاتَ أَبَدًۭا وَلَا تَقُمْ عَلَىٰ قَبْرِهِۦٓ ۖ إِنَّهُمْ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمْ فَٰسِقُونَ', 200, 10, 80, 0),
  (9, 85, 1320, 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمْ ۚ إِنَّمَا يُرِيدُ ٱللَّهُ أَن يُعَذِّبَهُم بِهَا فِى ٱلدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَٰفِرُونَ', 200, 10, 80, 0),
  (9, 86, 1321, 'وَإِذَآ أُنزِلَتْ سُورَةٌ أَنْ ءَامِنُوا۟ بِٱللَّهِ وَجَٰهِدُوا۟ مَعَ رَسُولِهِ ٱسْتَـْٔذَنَكَ أُو۟لُوا۟ ٱلطَّوْلِ مِنْهُمْ وَقَالُوا۟ ذَرْنَا نَكُن مَّعَ ٱلْقَٰعِدِينَ', 200, 10, 80, 0),
  (9, 87, 1322, 'رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 201, 10, 80, 0),
  (9, 88, 1323, 'لَٰكِنِ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ جَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ وَأُو۟لَٰٓئِكَ لَهُمُ ٱلْخَيْرَٰتُ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 201, 10, 80, 0),
  (9, 89, 1324, 'أَعَدَّ ٱللَّهُ لَهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 201, 10, 80, 0),
  (9, 90, 1325, 'وَجَآءَ ٱلْمُعَذِّرُونَ مِنَ ٱلْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ ٱلَّذِينَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ سَيُصِيبُ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌۭ', 201, 10, 80, 0),
  (9, 91, 1326, 'لَّيْسَ عَلَى ٱلضُّعَفَآءِ وَلَا عَلَى ٱلْمَرْضَىٰ وَلَا عَلَى ٱلَّذِينَ لَا يَجِدُونَ مَا يُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦ ۚ مَا عَلَى ٱلْمُحْسِنِينَ مِن سَبِيلٍۢ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 201, 10, 80, 0),
  (9, 92, 1327, 'وَلَا عَلَى ٱلَّذِينَ إِذَا مَآ أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَآ أَجِدُ مَآ أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا۟ وَّأَعْيُنُهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ حَزَنًا أَلَّا يَجِدُوا۟ مَا يُنفِقُونَ', 201, 10, 80, 0),
  (9, 93, 1328, '۞ إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ وَهُمْ أَغْنِيَآءُ ۚ رَضُوا۟ بِأَن يَكُونُوا۟ مَعَ ٱلْخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَعْلَمُونَ', 201, 11, 81, 0),
  (9, 94, 1329, 'يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ ۚ قُل لَّا تَعْتَذِرُوا۟ لَن نُّؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا ٱللَّهُ مِنْ أَخْبَارِكُمْ ۚ وَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 202, 11, 81, 0),
  (9, 95, 1330, 'سَيَحْلِفُونَ بِٱللَّهِ لَكُمْ إِذَا ٱنقَلَبْتُمْ إِلَيْهِمْ لِتُعْرِضُوا۟ عَنْهُمْ ۖ فَأَعْرِضُوا۟ عَنْهُمْ ۖ إِنَّهُمْ رِجْسٌۭ ۖ وَمَأْوَىٰهُمْ جَهَنَّمُ جَزَآءًۢ بِمَا كَانُوا۟ يَكْسِبُونَ', 202, 11, 81, 0),
  (9, 96, 1331, 'يَحْلِفُونَ لَكُمْ لِتَرْضَوْا۟ عَنْهُمْ ۖ فَإِن تَرْضَوْا۟ عَنْهُمْ فَإِنَّ ٱللَّهَ لَا يَرْضَىٰ عَنِ ٱلْقَوْمِ ٱلْفَٰسِقِينَ', 202, 11, 81, 0),
  (9, 97, 1332, 'ٱلْأَعْرَابُ أَشَدُّ كُفْرًۭا وَنِفَاقًۭا وَأَجْدَرُ أَلَّا يَعْلَمُوا۟ حُدُودَ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 202, 11, 81, 0),
  (9, 98, 1333, 'وَمِنَ ٱلْأَعْرَابِ مَن يَتَّخِذُ مَا يُنفِقُ مَغْرَمًۭا وَيَتَرَبَّصُ بِكُمُ ٱلدَّوَآئِرَ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 202, 11, 81, 0),
  (9, 99, 1334, 'وَمِنَ ٱلْأَعْرَابِ مَن يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ وَيَتَّخِذُ مَا يُنفِقُ قُرُبَٰتٍ عِندَ ٱللَّهِ وَصَلَوَٰتِ ٱلرَّسُولِ ۚ أَلَآ إِنَّهَا قُرْبَةٌۭ لَّهُمْ ۚ سَيُدْخِلُهُمُ ٱللَّهُ فِى رَحْمَتِهِۦٓ ۗ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 202, 11, 81, 0),
  (9, 100, 1335, 'وَٱلسَّٰبِقُونَ ٱلْأَوَّلُونَ مِنَ ٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ وَٱلَّذِينَ ٱتَّبَعُوهُم بِإِحْسَٰنٍۢ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ وَأَعَدَّ لَهُمْ جَنَّٰتٍۢ تَجْرِى تَحْتَهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 203, 11, 81, 0),
  (9, 101, 1336, 'وَمِمَّنْ حَوْلَكُم مِّنَ ٱلْأَعْرَابِ مُنَٰفِقُونَ ۖ وَمِنْ أَهْلِ ٱلْمَدِينَةِ ۖ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعْلَمُهُمْ ۖ نَحْنُ نَعْلَمُهُمْ ۚ سَنُعَذِّبُهُم مَّرَّتَيْنِ ثُمَّ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظِيمٍۢ', 203, 11, 81, 0),
  (9, 102, 1337, 'وَءَاخَرُونَ ٱعْتَرَفُوا۟ بِذُنُوبِهِمْ خَلَطُوا۟ عَمَلًۭا صَٰلِحًۭا وَءَاخَرَ سَيِّئًا عَسَى ٱللَّهُ أَن يَتُوبَ عَلَيْهِمْ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 203, 11, 81, 0),
  (9, 103, 1338, 'خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةًۭ تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ ۖ إِنَّ صَلَوٰتَكَ سَكَنٌۭ لَّهُمْ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ', 203, 11, 81, 0),
  (9, 104, 1339, 'أَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ هُوَ يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَأْخُذُ ٱلصَّدَقَٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 203, 11, 81, 0),
  (9, 105, 1340, 'وَقُلِ ٱعْمَلُوا۟ فَسَيَرَى ٱللَّهُ عَمَلَكُمْ وَرَسُولُهُۥ وَٱلْمُؤْمِنُونَ ۖ وَسَتُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 203, 11, 81, 0),
  (9, 106, 1341, 'وَءَاخَرُونَ مُرْجَوْنَ لِأَمْرِ ٱللَّهِ إِمَّا يُعَذِّبُهُمْ وَإِمَّا يَتُوبُ عَلَيْهِمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 203, 11, 81, 0),
  (9, 107, 1342, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مَسْجِدًۭا ضِرَارًۭا وَكُفْرًۭا وَتَفْرِيقًۢا بَيْنَ ٱلْمُؤْمِنِينَ وَإِرْصَادًۭا لِّمَنْ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبْلُ ۚ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَآ إِلَّا ٱلْحُسْنَىٰ ۖ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', 204, 11, 81, 0),
  (9, 108, 1343, 'لَا تَقُمْ فِيهِ أَبَدًۭا ۚ لَّمَسْجِدٌ أُسِّسَ عَلَى ٱلتَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ ۚ فِيهِ رِجَالٌۭ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ ۚ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ', 204, 11, 81, 0),
  (9, 109, 1344, 'أَفَمَنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ تَقْوَىٰ مِنَ ٱللَّهِ وَرِضْوَٰنٍ خَيْرٌ أَم مَّنْ أَسَّسَ بُنْيَٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارٍۢ فَٱنْهَارَ بِهِۦ فِى نَارِ جَهَنَّمَ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 204, 11, 81, 0),
  (9, 110, 1345, 'لَا يَزَالُ بُنْيَٰنُهُمُ ٱلَّذِى بَنَوْا۟ رِيبَةًۭ فِى قُلُوبِهِمْ إِلَّآ أَن تَقَطَّعَ قُلُوبُهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 204, 11, 81, 0),
  (9, 111, 1346, '۞ إِنَّ ٱللَّهَ ٱشْتَرَىٰ مِنَ ٱلْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَٰلَهُم بِأَنَّ لَهُمُ ٱلْجَنَّةَ ۚ يُقَٰتِلُونَ فِى سَبِيلِ ٱللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّۭا فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ وَٱلْقُرْءَانِ ۚ وَمَنْ أَوْفَىٰ بِعَهْدِهِۦ مِنَ ٱللَّهِ ۚ فَٱسْتَبْشِرُوا۟ بِبَيْعِكُمُ ٱلَّذِى بَايَعْتُم بِهِۦ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 204, 11, 82, 0),
  (9, 112, 1347, 'ٱلتَّٰٓئِبُونَ ٱلْعَٰبِدُونَ ٱلْحَٰمِدُونَ ٱلسَّٰٓئِحُونَ ٱلرَّٰكِعُونَ ٱلسَّٰجِدُونَ ٱلْءَامِرُونَ بِٱلْمَعْرُوفِ وَٱلنَّاهُونَ عَنِ ٱلْمُنكَرِ وَٱلْحَٰفِظُونَ لِحُدُودِ ٱللَّهِ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 205, 11, 82, 0),
  (9, 113, 1348, 'مَا كَانَ لِلنَّبِىِّ وَٱلَّذِينَ ءَامَنُوٓا۟ أَن يَسْتَغْفِرُوا۟ لِلْمُشْرِكِينَ وَلَوْ كَانُوٓا۟ أُو۟لِى قُرْبَىٰ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَٰبُ ٱلْجَحِيمِ', 205, 11, 82, 0),
  (9, 114, 1349, 'وَمَا كَانَ ٱسْتِغْفَارُ إِبْرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍۢ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوٌّۭ لِّلَّهِ تَبَرَّأَ مِنْهُ ۚ إِنَّ إِبْرَٰهِيمَ لَأَوَّٰهٌ حَلِيمٌۭ', 205, 11, 82, 0),
  (9, 115, 1350, 'وَمَا كَانَ ٱللَّهُ لِيُضِلَّ قَوْمًۢا بَعْدَ إِذْ هَدَىٰهُمْ حَتَّىٰ يُبَيِّنَ لَهُم مَّا يَتَّقُونَ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 205, 11, 82, 0),
  (9, 116, 1351, 'إِنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ', 205, 11, 82, 0),
  (9, 117, 1352, 'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِىِّ وَٱلْمُهَٰجِرِينَ وَٱلْأَنصَارِ ٱلَّذِينَ ٱتَّبَعُوهُ فِى سَاعَةِ ٱلْعُسْرَةِ مِنۢ بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍۢ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ ۚ إِنَّهُۥ بِهِمْ رَءُوفٌۭ رَّحِيمٌۭ', 205, 11, 82, 0),
  (9, 118, 1353, 'وَعَلَى ٱلثَّلَٰثَةِ ٱلَّذِينَ خُلِّفُوا۟ حَتَّىٰٓ إِذَا ضَاقَتْ عَلَيْهِمُ ٱلْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوٓا۟ أَن لَّا مَلْجَأَ مِنَ ٱللَّهِ إِلَّآ إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوٓا۟ ۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ', 206, 11, 82, 0),
  (9, 119, 1354, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّٰدِقِينَ', 206, 11, 82, 0),
  (9, 120, 1355, 'مَا كَانَ لِأَهْلِ ٱلْمَدِينَةِ وَمَنْ حَوْلَهُم مِّنَ ٱلْأَعْرَابِ أَن يَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا يَرْغَبُوا۟ بِأَنفُسِهِمْ عَن نَّفْسِهِۦ ۚ ذَٰلِكَ بِأَنَّهُمْ لَا يُصِيبُهُمْ ظَمَأٌۭ وَلَا نَصَبٌۭ وَلَا مَخْمَصَةٌۭ فِى سَبِيلِ ٱللَّهِ وَلَا يَطَـُٔونَ مَوْطِئًۭا يَغِيظُ ٱلْكُفَّارَ وَلَا يَنَالُونَ مِنْ عَدُوٍّۢ نَّيْلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلٌۭ صَٰلِحٌ ۚ إِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 206, 11, 82, 0),
  (9, 121, 1356, 'وَلَا يُنفِقُونَ نَفَقَةًۭ صَغِيرَةًۭ وَلَا كَبِيرَةًۭ وَلَا يَقْطَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمْ لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا كَانُوا۟ يَعْمَلُونَ', 206, 11, 82, 0),
  (9, 122, 1357, '۞ وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةًۭ ۚ فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍۢ مِّنْهُمْ طَآئِفَةٌۭ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ', 206, 11, 83, 0),
  (9, 123, 1358, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قَٰتِلُوا۟ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلْكُفَّارِ وَلْيَجِدُوا۟ فِيكُمْ غِلْظَةًۭ ۚ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ', 207, 11, 83, 0),
  (9, 124, 1359, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌۭ فَمِنْهُم مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَٰذِهِۦٓ إِيمَٰنًۭا ۚ فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَزَادَتْهُمْ إِيمَٰنًۭا وَهُمْ يَسْتَبْشِرُونَ', 207, 11, 83, 0),
  (9, 125, 1360, 'وَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا۟ وَهُمْ كَٰفِرُونَ', 207, 11, 83, 0),
  (9, 126, 1361, 'أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِى كُلِّ عَامٍۢ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ', 207, 11, 83, 0),
  (9, 127, 1362, 'وَإِذَا مَآ أُنزِلَتْ سُورَةٌۭ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَىٰكُم مِّنْ أَحَدٍۢ ثُمَّ ٱنصَرَفُوا۟ ۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌۭ لَّا يَفْقَهُونَ', 207, 11, 83, 0),
  (9, 128, 1363, 'لَقَدْ جَآءَكُمْ رَسُولٌۭ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِٱلْمُؤْمِنِينَ رَءُوفٌۭ رَّحِيمٌۭ', 207, 11, 83, 0),
  (9, 129, 1364, 'فَإِن تَوَلَّوْا۟ فَقُلْ حَسْبِىَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 207, 11, 83, 0),
  (10, 1, 1365, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْحَكِيمِ', 208, 11, 83, 0),
  (10, 2, 1366, 'أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَآ إِلَىٰ رَجُلٍۢ مِّنْهُمْ أَنْ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِينَ ءَامَنُوٓا۟ أَنَّ لَهُمْ قَدَمَ صِدْقٍ عِندَ رَبِّهِمْ ۗ قَالَ ٱلْكَٰفِرُونَ إِنَّ هَٰذَا لَسَٰحِرٌۭ مُّبِينٌ', 208, 11, 83, 0),
  (10, 3, 1367, 'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ يُدَبِّرُ ٱلْأَمْرَ ۖ مَا مِن شَفِيعٍ إِلَّا مِنۢ بَعْدِ إِذْنِهِۦ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَٱعْبُدُوهُ ۚ أَفَلَا تَذَكَّرُونَ', 208, 11, 83, 0),
  (10, 4, 1368, 'إِلَيْهِ مَرْجِعُكُمْ جَمِيعًۭا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ إِنَّهُۥ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ لِيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ بِٱلْقِسْطِ ۚ وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ شَرَابٌۭ مِّنْ حَمِيمٍۢ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ', 208, 11, 83, 0),
  (10, 5, 1369, 'هُوَ ٱلَّذِى جَعَلَ ٱلشَّمْسَ ضِيَآءًۭ وَٱلْقَمَرَ نُورًۭا وَقَدَّرَهُۥ مَنَازِلَ لِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلْحَقِّ ۚ يُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَعْلَمُونَ', 208, 11, 83, 0),
  (10, 6, 1370, 'إِنَّ فِى ٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَّقُونَ', 208, 11, 83, 0),
  (10, 7, 1371, 'إِنَّ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا وَرَضُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱطْمَأَنُّوا۟ بِهَا وَٱلَّذِينَ هُمْ عَنْ ءَايَٰتِنَا غَٰفِلُونَ', 209, 11, 83, 0),
  (10, 8, 1372, 'أُو۟لَٰٓئِكَ مَأْوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ يَكْسِبُونَ', 209, 11, 83, 0),
  (10, 9, 1373, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ يَهْدِيهِمْ رَبُّهُم بِإِيمَٰنِهِمْ ۖ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ فِى جَنَّٰتِ ٱلنَّعِيمِ', 209, 11, 83, 0),
  (10, 10, 1374, 'دَعْوَىٰهُمْ فِيهَا سُبْحَٰنَكَ ٱللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَٰمٌۭ ۚ وَءَاخِرُ دَعْوَىٰهُمْ أَنِ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 209, 11, 83, 0),
  (10, 11, 1375, '۞ وَلَوْ يُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسْتِعْجَالَهُم بِٱلْخَيْرِ لَقُضِىَ إِلَيْهِمْ أَجَلُهُمْ ۖ فَنَذَرُ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 209, 11, 84, 0),
  (10, 12, 1376, 'وَإِذَا مَسَّ ٱلْإِنسَٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦٓ أَوْ قَاعِدًا أَوْ قَآئِمًۭا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُۥ مَرَّ كَأَن لَّمْ يَدْعُنَآ إِلَىٰ ضُرٍّۢ مَّسَّهُۥ ۚ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا۟ يَعْمَلُونَ', 209, 11, 84, 0),
  (10, 13, 1377, 'وَلَقَدْ أَهْلَكْنَا ٱلْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا۟ ۙ وَجَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَمَا كَانُوا۟ لِيُؤْمِنُوا۟ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 209, 11, 84, 0),
  (10, 14, 1378, 'ثُمَّ جَعَلْنَٰكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ مِنۢ بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ', 209, 11, 84, 0),
  (10, 15, 1379, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَاتُنَا بَيِّنَٰتٍۢ ۙ قَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا ٱئْتِ بِقُرْءَانٍ غَيْرِ هَٰذَآ أَوْ بَدِّلْهُ ۚ قُلْ مَا يَكُونُ لِىٓ أَنْ أُبَدِّلَهُۥ مِن تِلْقَآئِ نَفْسِىٓ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۖ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍۢ', 210, 11, 84, 0),
  (10, 16, 1380, 'قُل لَّوْ شَآءَ ٱللَّهُ مَا تَلَوْتُهُۥ عَلَيْكُمْ وَلَآ أَدْرَىٰكُم بِهِۦ ۖ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًۭا مِّن قَبْلِهِۦٓ ۚ أَفَلَا تَعْقِلُونَ', 210, 11, 84, 0),
  (10, 17, 1381, 'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْمُجْرِمُونَ', 210, 11, 84, 0),
  (10, 18, 1382, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰٓؤُلَآءِ شُفَعَٰٓؤُنَا عِندَ ٱللَّهِ ۚ قُلْ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا يَعْلَمُ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 210, 11, 84, 0),
  (10, 19, 1383, 'وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةًۭ وَٰحِدَةًۭ فَٱخْتَلَفُوا۟ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ', 210, 11, 84, 0),
  (10, 20, 1384, 'وَيَقُولُونَ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦ ۖ فَقُلْ إِنَّمَا ٱلْغَيْبُ لِلَّهِ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 210, 11, 84, 0),
  (10, 21, 1385, 'وَإِذَآ أَذَقْنَا ٱلنَّاسَ رَحْمَةًۭ مِّنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُمْ إِذَا لَهُم مَّكْرٌۭ فِىٓ ءَايَاتِنَا ۚ قُلِ ٱللَّهُ أَسْرَعُ مَكْرًا ۚ إِنَّ رُسُلَنَا يَكْتُبُونَ مَا تَمْكُرُونَ', 211, 11, 84, 0),
  (10, 22, 1386, 'هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ ۖ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍۢ طَيِّبَةٍۢ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌۭ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍۢ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ ۙ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ', 211, 11, 84, 0),
  (10, 23, 1387, 'فَلَمَّآ أَنجَىٰهُمْ إِذَا هُمْ يَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۗ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَا بَغْيُكُمْ عَلَىٰٓ أَنفُسِكُم ۖ مَّتَٰعَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ ثُمَّ إِلَيْنَا مَرْجِعُكُمْ فَنُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 211, 11, 84, 0),
  (10, 24, 1388, 'إِنَّمَا مَثَلُ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ مِمَّا يَأْكُلُ ٱلنَّاسُ وَٱلْأَنْعَٰمُ حَتَّىٰٓ إِذَآ أَخَذَتِ ٱلْأَرْضُ زُخْرُفَهَا وَٱزَّيَّنَتْ وَظَنَّ أَهْلُهَآ أَنَّهُمْ قَٰدِرُونَ عَلَيْهَآ أَتَىٰهَآ أَمْرُنَا لَيْلًا أَوْ نَهَارًۭا فَجَعَلْنَٰهَا حَصِيدًۭا كَأَن لَّمْ تَغْنَ بِٱلْأَمْسِ ۚ كَذَٰلِكَ نُفَصِّلُ ٱلْءَايَٰتِ لِقَوْمٍۢ يَتَفَكَّرُونَ', 211, 11, 84, 0),
  (10, 25, 1389, 'وَٱللَّهُ يَدْعُوٓا۟ إِلَىٰ دَارِ ٱلسَّلَٰمِ وَيَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 211, 11, 84, 0),
  (10, 26, 1390, '۞ لِّلَّذِينَ أَحْسَنُوا۟ ٱلْحُسْنَىٰ وَزِيَادَةٌۭ ۖ وَلَا يَرْهَقُ وُجُوهَهُمْ قَتَرٌۭ وَلَا ذِلَّةٌ ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 212, 11, 85, 0),
  (10, 27, 1391, 'وَٱلَّذِينَ كَسَبُوا۟ ٱلسَّيِّـَٔاتِ جَزَآءُ سَيِّئَةٍۭ بِمِثْلِهَا وَتَرْهَقُهُمْ ذِلَّةٌۭ ۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍۢ ۖ كَأَنَّمَآ أُغْشِيَتْ وُجُوهُهُمْ قِطَعًۭا مِّنَ ٱلَّيْلِ مُظْلِمًا ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 212, 11, 85, 0),
  (10, 28, 1392, 'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًۭا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوا۟ مَكَانَكُمْ أَنتُمْ وَشُرَكَآؤُكُمْ ۚ فَزَيَّلْنَا بَيْنَهُمْ ۖ وَقَالَ شُرَكَآؤُهُم مَّا كُنتُمْ إِيَّانَا تَعْبُدُونَ', 212, 11, 85, 0),
  (10, 29, 1393, 'فَكَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنَنَا وَبَيْنَكُمْ إِن كُنَّا عَنْ عِبَادَتِكُمْ لَغَٰفِلِينَ', 212, 11, 85, 0),
  (10, 30, 1394, 'هُنَالِكَ تَبْلُوا۟ كُلُّ نَفْسٍۢ مَّآ أَسْلَفَتْ ۚ وَرُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 212, 11, 85, 0),
  (10, 31, 1395, 'قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ أَمَّن يَمْلِكُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَمَن يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَيُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَىِّ وَمَن يُدَبِّرُ ٱلْأَمْرَ ۚ فَسَيَقُولُونَ ٱللَّهُ ۚ فَقُلْ أَفَلَا تَتَّقُونَ', 212, 11, 85, 0),
  (10, 32, 1396, 'فَذَٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلْحَقُّ ۖ فَمَاذَا بَعْدَ ٱلْحَقِّ إِلَّا ٱلضَّلَٰلُ ۖ فَأَنَّىٰ تُصْرَفُونَ', 212, 11, 85, 0),
  (10, 33, 1397, 'كَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ فَسَقُوٓا۟ أَنَّهُمْ لَا يُؤْمِنُونَ', 212, 11, 85, 0),
  (10, 34, 1398, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۚ قُلِ ٱللَّهُ يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 213, 11, 85, 0),
  (10, 35, 1399, 'قُلْ هَلْ مِن شُرَكَآئِكُم مَّن يَهْدِىٓ إِلَى ٱلْحَقِّ ۚ قُلِ ٱللَّهُ يَهْدِى لِلْحَقِّ ۗ أَفَمَن يَهْدِىٓ إِلَى ٱلْحَقِّ أَحَقُّ أَن يُتَّبَعَ أَمَّن لَّا يَهِدِّىٓ إِلَّآ أَن يُهْدَىٰ ۖ فَمَا لَكُمْ كَيْفَ تَحْكُمُونَ', 213, 11, 85, 0),
  (10, 36, 1400, 'وَمَا يَتَّبِعُ أَكْثَرُهُمْ إِلَّا ظَنًّا ۚ إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 213, 11, 85, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 10, 1, 'Alif, Lam, Ra. These are the verses of the wise Book'),
  ('en.sahih', 10, 2, 'Have the people been amazed that We revealed [revelation] to a man from among them, [saying], "Warn mankind and give good tidings to those who believe that they will have a [firm] precedence of honor with their Lord"? [But] the disbelievers say, "Indeed, this is an obvious magician."'),
  ('en.sahih', 10, 3, 'Indeed, your Lord is Allah, who created the heavens and the earth in six days and then established Himself above the Throne, arranging the matter [of His creation]. There is no intercessor except after His permission. That is Allah, your Lord, so worship Him. Then will you not remember?'),
  ('en.sahih', 10, 4, 'To Him is your return all together. [It is] the promise of Allah [which is] truth. Indeed, He begins the [process of] creation and then repeats it that He may reward those who have believed and done righteous deeds, in justice. But those who disbelieved will have a drink of scalding water and a painful punishment for what they used to deny.'),
  ('en.sahih', 10, 5, 'It is He who made the sun a shining light and the moon a derived light and determined for it phases - that you may know the number of years and account [of time]. Allah has not created this except in truth. He details the signs for a people who know'),
  ('en.sahih', 10, 6, 'Indeed, in the alternation of the night and the day and [in] what Allah has created in the heavens and the earth are signs for a people who fear Allah'),
  ('en.sahih', 10, 7, 'Indeed, those who do not expect the meeting with Us and are satisfied with the life of this world and feel secure therein and those who are heedless of Our signs'),
  ('en.sahih', 10, 8, 'For those their refuge will be the Fire because of what they used to earn.'),
  ('en.sahih', 10, 9, 'Indeed, those who have believed and done righteous deeds - their Lord will guide them because of their faith. Beneath them rivers will flow in the Gardens of Pleasure'),
  ('en.sahih', 10, 10, 'Their call therein will be, "Exalted are You, O Allah," and their greeting therein will be, "Peace." And the last of their call will be, "Praise to Allah, Lord of the worlds!"'),
  ('en.sahih', 10, 11, 'And if Allah was to hasten for the people the evil [they invoke] as He hastens for them the good, their term would have been ended for them. But We leave the ones who do not expect the meeting with Us, in their transgression, wandering blindly'),
  ('en.sahih', 10, 12, 'And when affliction touches man, he calls upon Us, whether lying on his side or sitting or standing; but when We remove from him his affliction, he continues [in disobedience] as if he had never called upon Us to [remove] an affliction that touched him. Thus is made pleasing to the transgressors that which they have been doing'),
  ('en.sahih', 10, 13, 'And We had already destroyed generations before you when they wronged, and their messengers had come to them with clear proofs, but they were not to believe. Thus do We recompense the criminal people'),
  ('en.sahih', 10, 14, 'Then We made you successors in the land after them so that We may observe how you will do.'),
  ('en.sahih', 10, 15, 'And when Our verses are recited to them as clear evidences, those who do not expect the meeting with Us say, "Bring us a Qur\'an other than this or change it." Say, [O Muhammad], "It is not for me to change it on my own accord. I only follow what is revealed to me. Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."'),
  ('en.sahih', 10, 16, 'Say, "If Allah had willed, I would not have recited it to you, nor would He have made it known to you, for I had remained among you a lifetime before it. Then will you not reason?"'),
  ('en.sahih', 10, 17, 'So who is more unjust than he who invents a lie about Allah or denies His signs? Indeed, the criminals will not succeed'),
  ('en.sahih', 10, 18, 'And they worship other than Allah that which neither harms them nor benefits them, and they say, "These are our intercessors with Allah " Say, "Do you inform Allah of something He does not know in the heavens or on the earth?" Exalted is He and high above what they associate with Him'),
  ('en.sahih', 10, 19, 'And mankind was not but one community [united in religion], but [then] they differed. And if not for a word that preceded from your Lord, it would have been judged between them [immediately] concerning that over which they differ.'),
  ('en.sahih', 10, 20, 'And they say, "Why is a sign not sent down to him from his Lord?" So say, "The unseen is only for Allah [to administer], so wait; indeed, I am with you among those who wait."'),
  ('en.sahih', 10, 21, 'And when We give the people a taste of mercy after adversity has touched them, at once they conspire against Our verses. Say, "Allah is swifter in strategy." Indeed, Our messengers record that which you conspire'),
  ('en.sahih', 10, 22, 'It is He who enables you to travel on land and sea until, when you are in ships and they sail with them by a good wind and they rejoice therein, there comes a storm wind and the waves come upon them from everywhere and they assume that they are surrounded, supplicating Allah, sincere to Him in religion, "If You should save us from this, we will surely be among the thankful."'),
  ('en.sahih', 10, 23, 'But when He saves them, at once they commit injustice upon the earth without right. O mankind, your injustice is only against yourselves, [being merely] the enjoyment of worldly life. Then to Us is your return, and We will inform you of what you used to do.'),
  ('en.sahih', 10, 24, 'The example of [this] worldly life is but like rain which We have sent down from the sky that the plants of the earth absorb - [those] from which men and livestock eat - until, when the earth has taken on its adornment and is beautified and its people suppose that they have capability over it, there comes to it Our command by night or by day, and We make it as a harvest, as if it had not flourished yesterday. Thus do We explain in detail the signs for a people who give thought.'),
  ('en.sahih', 10, 25, 'And Allah invites to the Home of Peace and guides whom He wills to a straight path'),
  ('en.sahih', 10, 26, 'For them who have done good is the best [reward] and extra. No darkness will cover their faces, nor humiliation. Those are companions of Paradise; they will abide therein eternally'),
  ('en.sahih', 10, 27, 'But they who have earned [blame for] evil doings - the recompense of an evil deed is its equivalent, and humiliation will cover them. They will have from Allah no protector. It will be as if their faces are covered with pieces of the night - so dark [are they]. Those are the companions of the Fire; they will abide therein eternally.'),
  ('en.sahih', 10, 28, 'And [mention, O Muhammad], the Day We will gather them all together - then We will say to those who associated others with Allah, "[Remain in] your place, you and your \'partners.\' " Then We will separate them, and their "partners" will say, "You did not used to worship us,'),
  ('en.sahih', 10, 29, 'And sufficient is Allah as a witness between us and you that we were of your worship unaware."'),
  ('en.sahih', 10, 30, 'There, [on that Day], every soul will be put to trial for what it did previously, and they will be returned to Allah, their master, the Truth, and lost from them is whatever they used to invent.'),
  ('en.sahih', 10, 31, 'Say, "Who provides for you from the heaven and the earth? Or who controls hearing and sight and who brings the living out of the dead and brings the dead out of the living and who arranges [every] matter?" They will say, "Allah," so say, "Then will you not fear Him?"'),
  ('en.sahih', 10, 32, 'For that is Allah, your Lord, the Truth. And what can be beyond truth except error? So how are you averted?'),
  ('en.sahih', 10, 33, 'Thus the word of your Lord has come into effect upon those who defiantly disobeyed - that they will not believe.'),
  ('en.sahih', 10, 34, 'Say, "Are there of your \'partners\' any who begins creation and then repeats it?" Say, "Allah begins creation and then repeats it, so how are you deluded?"'),
  ('en.sahih', 10, 35, 'Say, "Are there of your \'partners\' any who guides to the truth?" Say, "Allah guides to the truth. So is He who guides to the truth more worthy to be followed or he who guides not unless he is guided? Then what is [wrong] with you - how do you judge?"'),
  ('en.sahih', 10, 36, 'And most of them follow not except assumption. Indeed, assumption avails not against the truth at all. Indeed, Allah is Knowing of what they do.'),
  ('en.sahih', 10, 37, 'And it was not [possible] for this Qur\'an to be produced by other than Allah, but [it is] a confirmation of what was before it and a detailed explanation of the [former] Scripture, about which there is no doubt, from the Lord of the worlds.'),
  ('en.sahih', 10, 38, 'Or do they say [about the Prophet], "He invented it?" Say, "Then bring forth a surah like it and call upon [for assistance] whomever you can besides Allah, if you should be truthful."'),
  ('en.sahih', 10, 39, 'Rather, they have denied that which they encompass not in knowledge and whose interpretation has not yet come to them. Thus did those before them deny. Then observe how was the end of the wrongdoers.'),
  ('en.sahih', 10, 40, 'And of them are those who believe in it, and of them are those who do not believe in it. And your Lord is most knowing of the corrupters'),
  ('en.sahih', 10, 41, 'And if they deny you, [O Muhammad], then say, "For me are my deeds, and for you are your deeds. You are disassociated from what I do, and I am disassociated from what you do."'),
  ('en.sahih', 10, 42, 'And among them are those who listen to you. But can you cause the deaf to hear, although they will not use reason?'),
  ('en.sahih', 10, 43, 'And among them are those who look at you. But can you guide the blind although they will not [attempt to] see?'),
  ('en.sahih', 10, 44, 'Indeed, Allah does not wrong the people at all, but it is the people who are wronging themselves.'),
  ('en.sahih', 10, 45, 'And on the Day when He will gather them, [it will be] as if they had not remained [in the world] but an hour of the day, [and] they will know each other. Those will have lost who denied the meeting with Allah and were not guided'),
  ('en.sahih', 10, 46, 'And whether We show you some of what We promise them, [O Muhammad], or We take you in death, to Us is their return; then, [either way], Allah is a witness concerning what they are doing'),
  ('en.sahih', 10, 47, 'And for every nation is a messenger. So when their messenger comes, it will be judged between them in justice, and they will not be wronged'),
  ('en.sahih', 10, 48, 'And they say, "When is [the fulfillment of] this promise, if you should be truthful?"'),
  ('en.sahih', 10, 49, 'Say, "I possess not for myself any harm or benefit except what Allah should will. For every nation is a [specified] term. When their time has come, then they will not remain behind an hour, nor will they precede [it]."'),
  ('en.sahih', 10, 50, 'Say, "Have you considered: if His punishment should come to you by night or by day - for which [aspect] of it would the criminals be impatient?"'),
  ('en.sahih', 10, 51, 'Then is it that when it has [actually] occurred you will believe in it? Now? And you were [once] for it impatient'),
  ('en.sahih', 10, 52, 'Then it will be said to those who had wronged, "Taste the punishment of eternity; are you being recompensed except for what you used to earn?"'),
  ('en.sahih', 10, 53, 'And they ask information of you, [O Muhammad], "Is it true?" Say, "Yes, by my Lord. Indeed, it is truth; and you will not cause failure [to Allah]."'),
  ('en.sahih', 10, 54, 'And if each soul that wronged had everything on earth, it would offer it in ransom. And they will confide regret when they see the punishment; and they will be judged in justice, and they will not be wronged'),
  ('en.sahih', 10, 55, 'Unquestionably, to Allah belongs whatever is in the heavens and the earth. Unquestionably, the promise of Allah is truth, but most of them do not know'),
  ('en.sahih', 10, 56, 'He gives life and causes death, and to Him you will be returned'),
  ('en.sahih', 10, 57, 'O mankind, there has to come to you instruction from your Lord and healing for what is in the breasts and guidance and mercy for the believers.'),
  ('en.sahih', 10, 58, 'Say, "In the bounty of Allah and in His mercy - in that let them rejoice; it is better than what they accumulate."'),
  ('en.sahih', 10, 59, 'Say, "Have you seen what Allah has sent down to you of provision of which you have made [some] lawful and [some] unlawful?" Say, "Has Allah permitted you [to do so], or do you invent [something] about Allah?"'),
  ('en.sahih', 10, 60, 'And what will be the supposition of those who invent falsehood about Allah on the Day of Resurrection? Indeed, Allah is full of bounty to the people, but most of them are not grateful."'),
  ('en.sahih', 10, 61, 'And, [O Muhammad], you are not [engaged] in any matter or recite any of the Qur\'an and you [people] do not do any deed except that We are witness over you when you are involved in it. And not absent from your Lord is any [part] of an atom\'s weight within the earth or within the heaven or [anything] smaller than that or greater but that it is in a clear register.'),
  ('en.sahih', 10, 62, 'Unquestionably, [for] the allies of Allah there will be no fear concerning them, nor will they grieve'),
  ('en.sahih', 10, 63, 'Those who believed and were fearing Allah'),
  ('en.sahih', 10, 64, 'For them are good tidings in the worldly life and in the Hereafter. No change is there in the words of Allah. That is what is the great attainment.'),
  ('en.sahih', 10, 65, 'And let not their speech grieve you. Indeed, honor [due to power] belongs to Allah entirely. He is the Hearing, the Knowing.'),
  ('en.sahih', 10, 66, 'Unquestionably, to Allah belongs whoever is in the heavens and whoever is on the earth. And those who invoke other than Allah do not [actually] follow [His] "partners." They follow not except assumption, and they are not but falsifying'),
  ('en.sahih', 10, 67, 'It is He who made for you the night to rest therein and the day, giving sight. Indeed in that are signs for a people who listen.'),
  ('en.sahih', 10, 68, 'They have said, "Allah has taken a son." Exalted is He; He is the [one] Free of need. To Him belongs whatever is in the heavens and whatever is in the earth. You have no authority for this [claim]. Do you say about Allah that which you do not know?'),
  ('en.sahih', 10, 69, 'Say, "Indeed, those who invent falsehood about Allah will not succeed."'),
  ('en.sahih', 10, 70, '[For them is brief] enjoyment in this world; then to Us is their return; then We will make them taste the severe punishment because they used to disbelieve'),
  ('en.sahih', 10, 71, 'And recite to them the news of Noah, when he said to his people, "O my people, if my residence and my reminding of the signs of Allah has become burdensome upon you - then I have relied upon Allah. So resolve upon your plan and [call upon] your associates. Then let not your plan be obscure to you. Then carry it out upon me and do not give me respite.'),
  ('en.sahih', 10, 72, 'And if you turn away [from my advice] then no payment have I asked of you. My reward is only from Allah, and I have been commanded to be of the Muslims."'),
  ('en.sahih', 10, 73, 'And they denied him, so We saved him and those with him in the ship and made them successors, and We drowned those who denied Our signs. Then see how was the end of those who were warned.'),
  ('en.sahih', 10, 74, 'Then We sent after him messengers to their peoples, and they came to them with clear proofs. But they were not to believe in that which they had denied before. Thus We seal over the hearts of the transgressors'),
  ('en.sahih', 10, 75, 'Then We sent after them Moses and Aaron to Pharaoh and his establishment with Our signs, but they behaved arrogantly and were a criminal people'),
  ('en.sahih', 10, 76, 'So when there came to them the truth from Us, they said, "Indeed, this is obvious magic."'),
  ('en.sahih', 10, 77, 'Moses said, "Do you say [thus] about the truth when it has come to you? Is this magic? But magicians will not succeed."'),
  ('en.sahih', 10, 78, 'They said, "Have you come to us to turn us away from that upon which we found our fathers and so that you two may have grandeur in the land? And we are not believers in you."'),
  ('en.sahih', 10, 79, 'And Pharaoh said, "Bring to me every learned magician."'),
  ('en.sahih', 10, 80, 'So when the magicians came, Moses said to them, "Throw down whatever you will throw."'),
  ('en.sahih', 10, 81, 'And when they had thrown, Moses said, "What you have brought is [only] magic. Indeed, Allah will expose its worthlessness. Indeed, Allah does not amend the work of corrupters.'),
  ('en.sahih', 10, 82, 'And Allah will establish the truth by His words, even if the criminals dislike it."'),
  ('en.sahih', 10, 83, 'But no one believed Moses, except [some] youths among his people, for fear of Pharaoh and his establishment that they would persecute them. And indeed, Pharaoh was haughty within the land, and indeed, he was of the transgressors'),
  ('en.sahih', 10, 84, 'And Moses said, "O my people, if you have believed in Allah, then rely upon Him, if you should be Muslims."'),
  ('en.sahih', 10, 85, 'So they said, "Upon Allah do we rely. Our Lord, make us not [objects of] trial for the wrongdoing people'),
  ('en.sahih', 10, 86, 'And save us by Your mercy from the disbelieving people."'),
  ('en.sahih', 10, 87, 'And We inspired to Moses and his brother, "Settle your people in Egypt in houses and make your houses [facing the] qiblah and establish prayer and give good tidings to the believers."'),
  ('en.sahih', 10, 88, 'And Moses said, "Our Lord, indeed You have given Pharaoh and his establishment splendor and wealth in the worldly life, our Lord, that they may lead [men] astray from Your way. Our Lord, obliterate their wealth and harden their hearts so that they will not believe until they see the painful punishment."'),
  ('en.sahih', 10, 89, '[Allah] said, "Your supplication has been answered." So remain on a right course and follow not the way of those who do not know."'),
  ('en.sahih', 10, 90, 'And We took the Children of Israel across the sea, and Pharaoh and his soldiers pursued them in tyranny and enmity until, when drowning overtook him, he said, "I believe that there is no deity except that in whom the Children of Israel believe, and I am of the Muslims."'),
  ('en.sahih', 10, 91, 'Now? And you had disobeyed [Him] before and were of the corrupters?'),
  ('en.sahih', 10, 92, 'So today We will save you in body that you may be to those who succeed you a sign. And indeed, many among the people, of Our signs, are heedless'),
  ('en.sahih', 10, 93, 'And We had certainty settled the Children of Israel in an agreeable settlement and provided them with good things. And they did not differ until [after] knowledge had come to them. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ'),
  ('en.sahih', 10, 94, 'So if you are in doubt, [O Muhammad], about that which We have revealed to you, then ask those who have been reading the Scripture before you. The truth has certainly come to you from your Lord, so never be among the doubters.'),
  ('en.sahih', 10, 95, 'And never be of those who deny the signs of Allah and [thus] be among the losers.'),
  ('en.sahih', 10, 96, 'Indeed, those upon whom the word of your Lord has come into effect will not believe,'),
  ('en.sahih', 10, 97, 'Even if every sign should come to them, until they see the painful punishment.'),
  ('en.sahih', 10, 98, 'Then has there not been a [single] city that believed so its faith benefited it except the people of Jonah? When they believed, We removed from them the punishment of disgrace in worldly life and gave them enjoyment for a time.'),
  ('en.sahih', 10, 99, 'And had your Lord willed, those on earth would have believed - all of them entirely. Then, [O Muhammad], would you compel the people in order that they become believers?'),
  ('en.sahih', 10, 100, 'And it is not for a soul to believe except by permission of Allah, and He will place defilement upon those who will not use reason.'),
  ('en.sahih', 10, 101, 'Say, "Observe what is in the heavens and earth." But of no avail will be signs or warners to a people who do not believe'),
  ('en.sahih', 10, 102, 'So do they wait except for like [what occurred in] the days of those who passed on before them? Say, "Then wait; indeed, I am with you among those who wait."'),
  ('en.sahih', 10, 103, 'Then We will save our messengers and those who have believed. Thus, it is an obligation upon Us that We save the believers'),
  ('en.sahih', 10, 104, 'Say, [O Muhammad], "O people, if you are in doubt as to my religion - then I do not worship those which you worship besides Allah; but I worship Allah, who causes your death. And I have been commanded to be of the believers'),
  ('en.sahih', 10, 105, 'And [commanded], \'Direct your face toward the religion, inclining to truth, and never be of those who associate others with Allah;'),
  ('en.sahih', 10, 106, 'And do not invoke besides Allah that which neither benefits you nor harms you, for if you did, then indeed you would be of the wrongdoers.\'"'),
  ('en.sahih', 10, 107, 'And if Allah should touch you with adversity, there is no remover of it except Him; and if He intends for you good, then there is no repeller of His bounty. He causes it to reach whom He wills of His servants. And He is the Forgiving, the Merciful'),
  ('en.sahih', 10, 108, 'Say, "O mankind, the truth has come to you from your Lord, so whoever is guided is only guided for [the benefit of] his soul, and whoever goes astray only goes astray [in violation] against it. And I am not over you a manager."'),
  ('en.sahih', 10, 109, 'And follow what is revealed to you, [O Muhammad], and be patient until Allah will judge. And He is the best of judges.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 10, 1, 'আলিফ-লাম-র, এগুলো হেকমতপূর্ণ কিতাবের আয়াত।'),
  ('bn.bengali', 10, 2, 'মানুষের কাছে কি আশ্চর্য লাগছে যে, আমি ওহী পাঠিয়েছি তাদেরই মধ্য থেকে একজনের কাছে যেন তিনি মানুষকে সতর্ক করেন এবং সুসংবাদ শুনিয়ে দেন ঈমনাদারগণকে যে, তাঁদের জন্য সত্য মর্যাদা রয়েছে তাঁদের পালনকর্তার কাছে। কাফেররা বলতে লাগল, নিঃসন্দেহে এ লোক প্রকাশ্য যাদুকর।'),
  ('bn.bengali', 10, 3, 'নিশ্চয়ই তোমাদের পালনকর্তা আল্লাহ যিনি তৈরী করেছেন আসমান ও যমীনকে ছয় দিনে, অতঃপর তিনি আরশের উপর অধিষ্ঠিত হয়েছেন। তিনি কার্য পরিচালনা করেন। কেউ সুপারিশ করতে পাবে না তবে তাঁর অনুমতি ছাড়া ইনিই আল্লাহ তোমাদের পালনকর্তা। অতএব, তোমরা তাঁরই এবাদত কর। তোমরা কি কিছুই চিন্তা কর না ?'),
  ('bn.bengali', 10, 4, 'তাঁর কাছেই ফিরে যেতে হবে তোমাদের সবাইকে, আল্লাহর ওয়াদা সত্য, তিনিই সৃষ্টি করেন প্রথমবার আবার পুনর্বার তৈরী করবেন তাদেরকে বদলা দেয়ার জন্য যারা ঈমান এনেছে এবং নেক কাজ করেছে ইনসাফের সাথে। আর যারা কাফের হয়েছে, তাদের পান করতে হবে ফুটন্ত পানি এবং ভোগ করতে হবে যন্ত্রনাদায়ক আযাব এ জন্যে যে, তারা কুফরী করছিল।'),
  ('bn.bengali', 10, 5, 'তিনিই সে মহান সত্তা, যিনি বানিয়েছেন সুর্যকে উজ্জল আলোকময়, আর চন্দ্রকে স্নিগ্ধ আলো বিতরণকারীরূপে এবং অতঃপর নির্ধারিত করেছেন এর জন্য মনযিল সমূহ, যাতে করে তোমরা চিনতে পার বছরগুলোর সংখ্যা ও হিসাব। আল্লাহ এই সমস্ত কিছু এমনিতেই সৃষ্টি করেননি, কিন্তু যথার্থতার সাথে। তিনি প্রকাশ করেন লক্ষণসমূহ সে সমস্ত লোকের জন্য যাদের জ্ঞান আছে।'),
  ('bn.bengali', 10, 6, 'নিশ্চয়ই রাত-দিনের পরিবর্তনের মাঝে এবং যা কিছু তিনি সৃষ্টি করেছেন আসমান ও যমীনে, সবই হল নিদর্শন সেসব লোকের জন্য যারা ভয় করে।'),
  ('bn.bengali', 10, 7, 'অবশ্যই যেসব লোক আমার সাক্ষাৎ লাভের আশা রাখে না এবং পার্থিব জীবন নিয়েই উৎফুল্ল রয়েছে, তাতেই প্রশান্তি অনুভব করেছে এবং যারা আমার নির্দশনসমূহ সম্পর্কে বেখবর।'),
  ('bn.bengali', 10, 8, 'এমন লোকদের ঠিকানা হল আগুন সেসবের বদলা হিসাবে যা তারা অর্জন করছিল।'),
  ('bn.bengali', 10, 9, 'অবশ্য যেসব লোক ঈমান এনেছে এবং সৎকাজ করেছে, তাদেরকে হেদায়েত দান করবেন তাদের পালনকর্তা, তাদের ঈমানের মাধ্যমে। এমন সুসময় কানন-কুঞ্জের প্রতি যার তলদেশে প্রবাহিত হয় প্রস্রবণসমূহ।'),
  ('bn.bengali', 10, 10, 'সেখানে তাদের প্রার্থনা হল ‘পবিত্র তোমার সত্তা হে আল্লাহ’। আর শুভেচ্ছা হল সালাম আর তাদের প্রার্থনার সমাপ্তি হয়, ‘সমস্ত প্রশংসা বিশ্বপালক আল্লাহর জন্য’ বলে।'),
  ('bn.bengali', 10, 11, 'আর যদি আল্লাহ তা’আলা মানুষকে যথাশীঘ্র অকল্যাণ পৌঁছে দেন যতশীঘ্র তার কামনা করে, তাহলে তাদের আশাই শেষ করে দিতে হত। সুতরাং যাদের মনে আমার সাক্ষাতের আশা নেই, আমি তাদেরকে তাদের দুষ্টুমিতে ব্যতিব্যস্ত ছেড়ে দিয়ে রাখি।'),
  ('bn.bengali', 10, 12, 'আর যখন মানুষ কষ্টের সম্মুখীন হয়, শুয়ে বসে, দাঁড়িয়ে আমাকে ডাকতে থাকে। তারপর আমি যখন তা থেকে মুক্ত করে দেই, সে কষ্ট যখন চলে যায় তখন মনে হয় কখনো কোন কষ্টেরই সম্মুখীন হয়ে যেন আমাকে ডাকেইনি। এমনিভাবে মনঃপুত হয়েছে নির্ভয় লোকদের যা তারা করেছে।'),
  ('bn.bengali', 10, 13, 'অবশ্য তোমাদের পূর্বে বহু দলকে ধ্বংস করে দিয়েছি, তখন তারা জালেম হয়ে গেছে। অথচ রসূল তাদের কাছেও এসব বিষয়ের প্রকৃষ্ট নির্দেশ নিয়ে এসেছিলেন। কিন্তু কিছুতেই তারা ঈমান আনল না। এমনিভাবে আমি শাস্তি দিয়ে থাকি পাপি সম্প্রদায়কে।'),
  ('bn.bengali', 10, 14, 'অতঃপর আমি তোমাদেরকে যমীনে তাদের পর প্রতিনিধি বানিয়েছি যাতে দেখতে পারি তোমরা কি কর।'),
  ('bn.bengali', 10, 15, 'আর যখন তাদের কাছে আমার প্রকৃষ্ট আয়াত সমূহ পাঠ করা হয়, তখন সে সমস্ত লোক বলে, যাদের আশা নেই আমার সাক্ষাতের, নিয়ে এসো কোন কোরআন এটি ছাড়া, অথবা একে পরিবর্তিত করে দাও। তাহলে বলে দাও, একে নিজের পক্ষ থেকে পরিবর্তিত করা আমার কাজ নয়। আমি সে নির্দেশেরই আনুগত্য করি, যা আমার কাছে আসে। আমি যদি স্বীয় পরওয়ারদেগারের নাফরমানী করি, তবে কঠিন দিবসের আযাবের ভয় করি।'),
  ('bn.bengali', 10, 16, 'বলে দাও, যদি আল্লাহ চাইতেন, তবে আমি এটি তোমাদের সামনে পড়তাম না, আর নাইবা তিনি তোমাদেরেকে অবহিত করতেন এ সম্পর্কে। কারণ আমি তোমাদের মাঝে ইতিপূর্বেও একটা বয়স অতিবাহিত করেছি। তারপরেও কি তোমরা চিন্তা করবে না?'),
  ('bn.bengali', 10, 17, 'অতঃপর তার চেয়ে বড় জালেম, কে হবে, যে আল্লাহর প্রতি অপবাদ আরোপ করেছে কিংবা তাঁর আয়াতসমূহকে মিথ্যা বলে অভিহিত করছে? কস্মিনকালেও পাপীদের কোন কল্যাণ হয় না।'),
  ('bn.bengali', 10, 18, 'আর উপাসনা করে আল্লাহকে বাদ দিয়ে এমন বস্তুর, যা না তাদের কোন ক্ষতিসাধন করতে পারে, না লাভ এবং বলে, এরা তো আল্লাহর কাছে আমাদের সুপারিশকারী। তুমি বল, তোমরা কি আল্লাহকে এমন বিষয়ে অবহিত করছ, যে সম্পর্কে তিনি অবহিত নন আসমান ও যমীনের মাঝে ? তিনি পুতঃপবিত্র ও মহান সে সমস্ত থেকে যাকে তোমরা শরীক করছ।'),
  ('bn.bengali', 10, 19, 'আর সমস্ত মানুষ একই উম্মতভুক্ত ছিল, পরে পৃথক হয়ে গেছে। আর একটি কথা যদি তোমার পরওয়ারদেগারের পক্ষ থেকে পূর্ব নির্ধারিত না হয়ে যেত; তবে তারা যে বিষয়ে বিরোধ করছে তার মীমাংসা হয়ে যেত।'),
  ('bn.bengali', 10, 20, 'বস্তুতঃ তারা বলে, তাঁর কাছে তাঁর পরওয়ারদেগারের পক্ষ থেকে কোন নির্দেশ এল না কেন? বলে দাও গায়েবের কথা আল্লাহই জানেন। আমি ও তোমাদের সাথে অপেক্ষায় রইলাম।'),
  ('bn.bengali', 10, 21, 'আর যখন আমি আস্বাদন করাই স্বীয় রহমত সে কষ্টের পর, যা তাদের ভোগ করতে হয়েছিল, তখনই তারা আমার শক্তিমত্তার মাঝে নানা রকম ছলনা তৈরী করতে আরম্ভ করবে। আপনি বলে দিন, আল্লাহ সবচেয়ে দ্রুত কলা-কৌশল তৈরী করতে পারেন। নিশ্চয়ই আমাদের ফেরেশতারা লিখে রাখে তোমাদের ছল-চাতুরী।'),
  ('bn.bengali', 10, 22, 'তিনিই তোমাদের ভ্রমন করান স্থলে ও সাগরে। এমনকি যখন তোমরা নৌকাসমূহে আরোহণ করলে আর তা লোকজনকে অনুকূল হাওয়ায় বয়ে নিয়ে চলল এবং তাতে তারা আনন্দিত হল, নৌকাগুলোর উপর এল তীব্র বাতাস, আর সর্বদিক থেকে সেগুলোর উপর ঢেউ আসতে লাগল এবং তারা জানতে পারল যে, তারা অবরুদ্ধ হয়ে পড়েছে, তখন ডাকতে লাগল আল্লাহকে তাঁর এবাদতে নিঃস্বার্থ হয়ে যদি তুমি আমাদেরকে এ বিপদ থেকে উদ্ধার করে তোল, তাহলে নিঃসন্দেহে আমরা কৃতজ্ঞ থাকব।'),
  ('bn.bengali', 10, 23, 'তারপর যখন তাদেরকে আল্লাহ বাঁচিয়ে দিলেন, তখনই তারা পৃথিবীতে অনাচার করতে লাগল অন্যায় ভাবে। হে মানুষ! শোন, তোমাদের অনাচার তোমাদেরই উপর পড়বে। পার্থিব জীবনের সুফল ভোগ করে নাও-অতঃপর আমার নিকট প্রত্যাবর্তন করতে হবে। তখন আমি বাতলে দেব, যা কিছু তোমরা করতে।'),
  ('bn.bengali', 10, 24, 'পার্থিব জীবনের উদাহরণ তেমনি, যেমনি আমি আসমান থেকে পানি বর্ষন করলাম, পরে তা মিলিত সংমিশ্রিত হয়ে তা থেকে যমীনের শ্যামল উদ্ভিদ বেরিয়ে এল যা মানুষ ও জীব-জন্তুরা খেয়ে থাকে। এমনকি যমীন যখন সৌন্দর্য সুষমায় ভরে উঠলো আর যমীনের অধিকর্তারা ভাবতে লাগল, এগুলো আমাদের হাতে আসবে, হঠাৎ করে তার উপর আমার নির্দেশ এল রাত্রে কিংবা দিনে, তখন সেগুলোকে কেটে স্তুপাকার করে দিল যেন কাল ও এখানে কোন আবাদ ছিল না। এমনিভাবে আমি খোলাখুলি বর্ণনা করে থাকি নিদর্শণসমূহ সে সমস্ত লোকদের জন্য যারা লক্ষ্য করে।'),
  ('bn.bengali', 10, 25, 'আর আল্লাহ শান্তি-নিরাপত্তার আলয়ের প্রতি আহবান জানান এবং যাকে ইচ্ছা সরলপথ প্রদর্শন করেন।'),
  ('bn.bengali', 10, 26, 'যারা সৎকর্ম করেছে তাদের জন্য রয়েছে কল্যাণ এবং তারও চেয়ে বেশী। আর তাদের মুখমন্ডলকে আবৃত করবে না মলিনতা কিংবা অপমান। তারাই হল জান্নাতবাসী, এতেই তারা বসবাস করতে থাকবে অনন্তকাল।'),
  ('bn.bengali', 10, 27, 'আর যারা সঞ্চয় করেছে অকল্যাণ অসৎ কর্মের বদলায় সে পরিমাণ অপমান তাদের চেহারাকে আবৃত করে ফেলবে। কেউ নেই তাদেরকে বাঁচাতে পারে আল্লাহর হাত থেকে। তাদের মুখমন্ডল যেন ঢেকে দেয়া হয়েছে আধাঁর রাতের টুকরো দিয়ে। এরা হল দোযখবাসী। এরা এতেই থাকবে অনন্তকাল।'),
  ('bn.bengali', 10, 28, 'আর যেদিন আমি তাদের সবাইকে সমবেত করব; আর যারা শেরক করত তাদেরকে বলবঃ তোমরা এবং তোমাদের শরীকরা নিজ নিজ জায়গায় দাঁড়িয়ে যাও-অতঃপর তাদেরকে পারস্পরিক বিচ্ছিন্ন করে দেব, তখন তাদের শরীকরা বলবে, তোমরা তো আমাদের উপাসনা-বন্দেগী করনি।'),
  ('bn.bengali', 10, 29, 'বস্তুতঃ আল্লাহ আমাদের ও তোমাদের মাঝে সাক্ষী হিসাবে যথেষ্ট। আমরা তোমাদের বন্দেগী সম্পর্কে জানতাম না।'),
  ('bn.bengali', 10, 30, 'সেখানে প্রত্যেকে যাচাই করে নিতে পারবে যা কিছু সে ইতিপূর্বে করেছিল এবং আল্লাহর প্রতি প্রত্যাবর্তন করবে যিনি তাদের প্রকৃত মালিক, আর তাদের কাছ থেকে দূরে যেতে থাকবে যারা মিথ্যা বলত।'),
  ('bn.bengali', 10, 31, 'তুমি জিজ্ঞেস কর, কে রুযী দান করে তোমাদেরকে আসমান থেকে ও যমীন থেকে, কিংবা কে তোমাদের কান ও চোখের মালিক? তাছাড়া কে জীবিতকে মৃতের ভেতর থেকে বের করেন এবং কেইবা মৃতকে জীবিতের মধ্য থেকে বের করেন? কে করেন কর্ম সম্পাদনের ব্যবস্থাপনা? তখন তারা বলে উঠবে, আল্লাহ! তখন তুমি বলো তারপরেও ভয় করছ না?'),
  ('bn.bengali', 10, 32, 'অতএব, এ আল্লাহই তোমাদের প্রকৃত পালনকর্তা। আর সত্য প্রকাশের পরে (উদভ্রান্ত ঘুরার মাঝে) কি রয়েছে গোমরাহী ছাড়া? সুতরাং কোথায় ঘুরছ?'),
  ('bn.bengali', 10, 33, 'এমনিভাবে সপ্রমাণিত হয়ে গেছে তোমার পরওয়ারদেগারের বাণী সেসব নাফরমানের ব্যাপারে যে, এরা ঈমান আনবে না।'),
  ('bn.bengali', 10, 34, 'বল, আছে কি কেউ তোমাদের শরীকদের মাঝে যে সৃষ্টি কে পয়দা করতে পারে এবং আবার জীবিত করতে পারে? বল, আল্লাহই প্রথমবার সৃষ্টি করেন এবং অতঃপর তার পুনরুদ্ভব করবেন। অতএব, কোথায় ঘুরপাক খাচ্ছে?'),
  ('bn.bengali', 10, 35, 'জিজ্ঞেস কর, আছে কি কেউ তোমাদের শরীকদের মধ্যে যে সত্য-সঠিক পথ প্রদর্শন করবে? বল, আল্লাহই সত্য-সঠিক পথ প্রদর্শন করেন, সুতরাং এমন যে লোক সঠিক পথ দেখাবে তার কথা মান্য করা কিংবা যে লোক নিজে নিজে পথ খুঁজে পায় না, তাকে পথ দেখানো কর্তব্য। অতএব, তোমাদের কি হল, কেমন তোমাদের বিচার?'),
  ('bn.bengali', 10, 36, 'বস্তুতঃ তাদের অধিকাংশই শুধু আন্দাজ-অনুমানের উপর চলে, অথচ আন্দাজ-অনুমান সত্যের বেলায় কোন কাজেই আসে না। আল্লাহ ভাল করেই জানেন, তারা যা কিছু করে।'),
  ('bn.bengali', 10, 37, 'আর কোরআন সে জিনিস নয় যে, আল্লাহ ব্যতীত কেউ তা বানিয়ে নেবে। অবশ্য এটি পূর্ববর্তী কালামের সত্যায়ন করে এবং সে সমস্ত বিষয়ের বিশ্লেষণ দান করে যা তোমার প্রতি দেয়া হয়েছে, যাতে কোন সন্দেহ নেই-তোমার বিশ্বপালনকর্তার পক্ষ থেকে।'),
  ('bn.bengali', 10, 38, 'মানুষ কি বলে যে, এটি বানিয়ে এনেছ? বলে দাও, তোমরা নিয়ে এসো একটিই সূরা, আর ডেকে নাও, যাদেরকে নিতে সক্ষম হও আল্লাহ ব্যতীত, যদি তোমরা সত্যবাদী হয়ে থাক।'),
  ('bn.bengali', 10, 39, 'কিন্তু কথা হল এই যে, তারা মিথ্যা প্রতিপন্ন করতে আরম্ভ করেছে যাকে বুঝতে, তারা অক্ষম। অথচ এখনো এর বিশ্লেষণ আসেনি। এমনিভাবে মিথ্যা প্রতিপন্ন করেছে তাদের পূর্ববর্তীরা। অতএব, লক্ষ্য করে দেখ, কেমন হয়েছে পরিণতি।'),
  ('bn.bengali', 10, 40, 'আর তাদের মধ্যে কেউ কেউ কোরআনকে বিশ্বাস করবে এবং কেউ কেউ বিশ্বাস করবে না। বস্তুতঃ তোমার পরওয়ারদেগার যথার্থই জানেন দুরাচারদিগকে।'),
  ('bn.bengali', 10, 41, 'আর যদি তোমাকে মিথ্যা প্রতিপন্ন করে, তবে বল, আমার জন্য আমার কর্ম, আর তোমাদের জন্য তোমাদের কর্ম। তোমাদের দায়-দায়িত্ব নেই আমার কর্মের উপর এবং আমারও দায়-দায়িত্ব নেই তোমরা যা কর সেজন্য।'),
  ('bn.bengali', 10, 42, 'তাদের কেউ কেউ কান রাখে তোমাদের প্রতি; তুমি বধিরদেরকে কি শোনাবে যদি তাদের বিবেক-বুদ্ধি না থাকে!'),
  ('bn.bengali', 10, 43, 'আবার তাদের মধ্যে কেউ কেউ তোমাদের প্রতি দৃষ্টিনিবদ্ধ রাখে; তুমি অন্ধদেরকে কি পথ দেখাবে যদি তারা মোটেও দেখতে না পারে।'),
  ('bn.bengali', 10, 44, 'আল্লাহ জুলুম করেন না মানুষের উপর, বরং মানুষ নিজেই নিজের উপর জুলুম করে।'),
  ('bn.bengali', 10, 45, 'আর যেদিন তাদেরকে সমবেত করা হবে, যেন তারা অবস্থান করেনি, তবে দিনের একদন্ড একজন অপরজনকে চিনবে। নিঃসন্দেহে ক্ষতিগ্রস্ত হয়েছে যারা মিথ্যা প্রতিপন্ন করেছে আল্লাহর সাথে সাক্ষাতকে এবং সরলপথে আসেনি।'),
  ('bn.bengali', 10, 46, 'আর যদি আমি দেখাই তোমাকে সে ওয়াদাসমূহের মধ্য থেকে কোন কিছু যা আমি তাদের সাথে করেছি, অথবা তোমাকে মৃত্যুদান করি, যাহোক, আমার কাছেই তাদেরকে প্রত্যাবর্তন করতে হবে। বস্তুতঃ আল্লাহ সে সমস্ত কর্মের সাক্ষী যা তারা করে।'),
  ('bn.bengali', 10, 47, 'আর প্রত্যেক সম্প্রদায়ের একেকজন রসূল রয়েছে। যখন তাদের কাছে তাদের রসূল ন্যায়দন্ডসহ উপস্থিত হল, তখন আর তাদের উপর জুলুম হয় না।'),
  ('bn.bengali', 10, 48, 'তারা আরো বলে, এ ওয়াদা কবে আসবে, যদি তোমরা সত্যবাদী হয়ে থাক?'),
  ('bn.bengali', 10, 49, 'তুমি বল, আমি আমার নিজের ক্ষতি কিংবা লাভেরও মালিক নই, কিন্তু আল্লাহ যা ইচ্ছা করেন। প্রত্যেক সম্প্রদায়ের জন্যই একেকটি ওয়াদা রয়েছে, যখন তাদের সে ওয়াদা এসে পৌঁছে যাবে, তখন না একদন্ড পেছনে সরতে পারবে, না সামনে ফসকাতে পারবে,।'),
  ('bn.bengali', 10, 50, 'তুমি বল, আচ্ছা দেখ তো দেখি, যদি তোমাদের উপর তার আযাব রাতারাতি অথবা দিনের বেলায় এসে পৌঁছে যায়, তবে এর আগে পাপীরা কি করবে?'),
  ('bn.bengali', 10, 51, 'তাহলে কি আযাব সংঘটিত হয়ে যাবার পর এর প্রতি বিশ্বাস করবে? এখন স্বীকার করলে? অথচ তোমরা এরই তাকাদা করতে?'),
  ('bn.bengali', 10, 52, 'অতঃপর বলা হবে, গোনাহগারদিগকে, ভোগ করতে থাক অনন্ত আযাব-তোমরা যা কিছু করতে তার তাই প্রতিফল।'),
  ('bn.bengali', 10, 53, 'আর তোমার কাছে সংবাদ জিজ্ঞেস করে, এটা কি সত্য ? বলে দাও, অবশ্যই আমার পরওয়ারদেগারের কসম এটা সত্য। আর তোমরা পরিশ্রান্ত করে দিতে পারবে না।'),
  ('bn.bengali', 10, 54, 'বস্তুতঃ যদি প্রত্যেক গোনাহগারের কাছে এত পরিমাণ থাকে যা আছে সমগ্র যমীনের মাঝে, আর অবশ্যই যদি সেগুলো নিজের মুক্তির বিনিময়ে দিতে চাইবে আর গোপনে গোপনে অনুতাপ করবে, যখন আযাব দেখবে। বস্তুতঃ তাদের জন্য সিদ্ধান্ত হবে ন্যায়সঙ্গত এবং তাদের উপর জুলম হবে না।'),
  ('bn.bengali', 10, 55, 'শুনে রাখ, যা কিছু রয়েছে আসমানসমূহে ও যমীনে সবই আল্লাহর। শুনে রাখ, আল্লাহর প্রতিশ্রুতি সত্য। তবে অনেকেই জানে না।'),
  ('bn.bengali', 10, 56, 'তিনিই জীবন ও মরণ দান করেন এবং তাঁরই কাছে প্রত্যাবর্তন করতে হবে।'),
  ('bn.bengali', 10, 57, 'হে মানবকুল, তোমাদের কাছে উপদেশবানী এসেছে তোমাদের পরওয়ারদেগারের পক্ষ থেকে এবং অন্তরের রোগের নিরাময়, হেদায়েত ও রহমত মুসলমানদের জন্য।'),
  ('bn.bengali', 10, 58, 'বল, আল্লাহর দয়া ও মেহেরবাণীতে। সুতরাং এরই প্রতি তাদের সন্তুষ্ট থাকা উচিৎ। এটিই উত্তম সে সমুদয় থেকে যা সঞ্চয় করছ।'),
  ('bn.bengali', 10, 59, 'বল, আচ্ছা নিজেই লক্ষ্য করে দেখ, যা কিছু আল্লাহ তোমাদের জন্য রিযিক হিসাবে অবতীর্ণ করেছেন, তোমরা সেগুলোর মধ্য থেকে কোনটাকে হারাম আর কোনটাকে হালাল সাব্যস্ত করেছ? বল, তোমাদের কি আল্লাহ নির্দেশ দিয়েছেন, নাকি আল্লাহর উপর অপবাদ আরোপ করছ?'),
  ('bn.bengali', 10, 60, 'আর আল্লাহর প্রতি মিথ্যা অপবাদ আরোপকারীদের কি ধারণা কেয়ামত সম্পর্কে? আল্লাহ তো মানুষের প্রতি অনুগ্রহই করেন, কিন্তু অনেকেই কৃতজ্ঞতা স্বীকার করে না।'),
  ('bn.bengali', 10, 61, 'বস্তুতঃ যে কোন অবস্থাতেই তুমি থাক এবং কোরআনের যে কোন অংশ থেকেই পাঠ করা কিংবা যে কোন কাজই তোমরা কর অথচ আমি তোমাদের নিকটে উপস্থিত থাকি যখন তোমরা তাতে আত্ননিয়োগ কর। আর তোমার পরওয়ারদেগার থেকে গোপন থাকে না একটি কনাও, না যমীনের এবং না আসমানের। না এর চেয়ে ক্ষুদ্র কোন কিছু আছে, না বড় যা এই প্রকৃষ্ট কিতাবে নেই।'),
  ('bn.bengali', 10, 62, 'মনে রেখো যারা আল্লাহর বন্ধু, তাদের না কোন ভয় ভীতি আছে, না তারা চিন্তান্বিত হবে।'),
  ('bn.bengali', 10, 63, 'যারা ঈমান এনেছে এবং ভয় করতে রয়েছে।'),
  ('bn.bengali', 10, 64, 'তাদের জন্য সুসংবাদ পার্থিব জীবনে ও পরকালীন জীবনে। আল্লাহর কথার কখনো হের-ফের হয় না। এটাই হল মহা সফলতা।'),
  ('bn.bengali', 10, 65, 'আর তাদের কথায় দুঃখ নিয়ো না। আসলে সমস্ত ক্ষমতা আল্লাহর। তিনিই শ্রবণকারী, সর্বজ্ঞ।'),
  ('bn.bengali', 10, 66, 'শুনছ, আসমানসমূহে ও যমীনে যা কিছু রয়েছে সবই আল্লাহর। আর এরা যারা আল্লাহকে বাদ দিয়ে শরীকদের উপাসনার পেছনে পড়ে আছে-তা আসলে কিছুই নয়। এরা নিজেরই কল্পনার পেছনে পড়ে রয়েছে এবং এছাড়া আর কিছু নয় যে, এরা বুদ্ধি খাটাচ্ছে।'),
  ('bn.bengali', 10, 67, 'তিনি তোমাদের জন্য তৈরী করেছেন রাত, যাতে করে তোমরা তাতে প্রশান্তি লাভ করতে পার, আর দিন দিয়েছেন দর্শন করার জন্য। নিঃসন্দেহে এতে নিদর্শন রয়েছে সে সব লোকের জন্য যারা শ্রবণ করে।'),
  ('bn.bengali', 10, 68, 'তারা বলে, আল্লাহ পুত্র সাব্যস্ত করে নিয়েছেন-তিনি পবিত্র, তিনি অমুখাপেক্ষী। যাকিছু রয়েছে আসমান সমূহে ও যমীনে সবই তাঁর। তোমাদের কাছে তার কোন সনদ নেই। কেন তোমরা আল্লাহর প্রতি মিথ্যারোপ কর-যার কোন সনদই তোমাদের কাছে নেই?'),
  ('bn.bengali', 10, 69, 'বলে দাও, যারা এরূপ করে তারা অব্যাহতি পায় না।'),
  ('bn.bengali', 10, 70, 'পার্থিবজীবনে সামান্যই লাভ, অতঃপর আমার নিকট প্রত্যাবর্তন করতে হবে। তখন আমি তাদেরকে আস্বাদন করাব কঠিন আযাব-তাদেরই কৃত কুফরীর বদলাতে।'),
  ('bn.bengali', 10, 71, 'আর তাদেরকে শুনিয়ে দাও নূহের অবস্থা যখন সে স্বীয় সম্প্রদায়কে বলল, হে আমার সম্প্রদায়, যদি তোমাদের মাঝে আমার অবস্থিতি এবং আল্লাহর আয়াতসমূহের মাধ্যমে নসীহত করা ভারী বলে মনে হয়ে থাকে, তবে আমি আল্লাহর উপর ভরসা করছি। এখন তোমরা সবাই মিলে নিজেরদের কর্ম সাব্যস্ত কর এবং এতে তোমাদের শরীকদেরকে সমবেত করে নাও, যাতে তোমাদের মাঝে নিজেদের কাজের ব্যাপারে কোন সন্দেহ-সংশয় না থাকে। অতঃপর আমার সম্পর্কে যা কিছু করার করে ফেল এবং আমাকে অব্যাহতি দিও না।'),
  ('bn.bengali', 10, 72, 'তারপরও যদি বিমুখতা অবলম্বন কর, তবে আমি তোমাদের কাছে কোন রকম বিনিময় কামনা করি না। আমার বিনিময় হল আল্লাহর দায়িত্বে। আর আমার প্রতি নির্দেশ রয়েছে যেন আমি আনুগত্য অবলম্বন করি।'),
  ('bn.bengali', 10, 73, 'তারপরও এরা মিথ্যা প্রতিপন্ন করল। সুতরাং তাকে এবং তার সাথে নৌকায় যারা ছিল তাদের কে বাঁচিয়ে নিয়েছি এবং যথাস্থানে আবাদ করেছি। আর তাদেরকে ডুবিয়ে দিয়েছি যারা আমার কথাকে মিথ্যা প্রতিপন্ন করেছে। সুতরাং লক্ষ্য কর, কেমন পরিণতি ঘটেছে তাদের যাদেরকে ভীতি প্রদর্শন করা হয়েছিল।'),
  ('bn.bengali', 10, 74, 'অনন্তর আমি নূহের পরে বহু নবী-রসূল পাঠিয়েছি তাদের সম্প্রদায়ের প্রতি। তারপর তাদের কাছে তারা প্রকাশ্য দলীল-প্রমাণ উপস্থাপন করেছে, কিন্তু তাদের দ্বারা এমনটি হয়নি যে, ঈমান আনবে সে ব্যাপারে, যাকে তারা ইতিপূর্বে মিথ্যা প্রতিপন্ন করেছিল। এভাবেই আমি মোহর এঁটে দেই সীমালংঘনকারীদের অন্তরসমূহের উপর।'),
  ('bn.bengali', 10, 75, 'অতঃপর তাদের পেছনে পাঠিয়েছি আমি মূসা ও হারুনকে, ফেরাউন ও তার সর্দারের প্রতি স্বীয় নির্দেশাবলী সহকারে। অথচ তারা অহংকার করতে আরম্ভ করেছে।'),
  ('bn.bengali', 10, 76, 'বস্তুতঃ তারা ছিল গোনাহগার। তারপর আমার পক্ষ থেকে যখন তাদের কাছে সত্য বিষয় উপস্থিত হল, তখন বলতে লাগলো, এগুলো তো প্রকাশ্য যাদু।'),
  ('bn.bengali', 10, 77, 'মূসা বলল, সত্যের ব্যাপারে একথা বলছ, তা তোমাদের কাছে পৌঁছার পর? একি যাদু? অথচ যারা যাদুকর, তারা সফল হতে পারে না।'),
  ('bn.bengali', 10, 78, 'তারা বলল, তুমি কি আমাদেরকে সে পথ থেকে ফিরিয়ে দিতে এসেছ যাতে আমরা পেয়েছি আমাদের বাপ-দাদাদেরকে? আর যাতে তোমরা দুইজন এদেশের সর্দারী পেয়ে যেতে পার? আমরা তোমাদেরকে কিছুতেই মানব না।'),
  ('bn.bengali', 10, 79, 'আর ফেরাউন বলল, আমার কাছে নিয়ে এস সুদক্ষ যাদুকরদিগকে।'),
  ('bn.bengali', 10, 80, 'তারপর যখন যাদুকররা এল, মূসা তাদেরকে বলল, নিক্ষেপ কর, তোমরা যা কিছু নিক্ষেপ করে থাক।'),
  ('bn.bengali', 10, 81, 'অতঃপর যখন তারা নিক্ষেপ করল, মূসা বলল, যা কিছু তোমরা এনেছ তা সবই যাদু-এবার আল্লাহ এসব ভন্ডুল করে দিচ্ছেন। নিঃসন্দেহে আল্লাহ দুস্কর্মীদের কর্মকে সুষ্ঠুতা দান করেন না।'),
  ('bn.bengali', 10, 82, 'আল্লাহ সত্যকে সত্যে পরিণত করেন স্বীয় নির্দেশে যদিও পাপীদের তা মনঃপুত নয়।'),
  ('bn.bengali', 10, 83, 'আর কেউ ঈমান আনল না মূসার প্রতি তাঁর কওমের কতিপয় বালক ছাড়া-ফেরাউন ও তার সর্দারদের ভয়ে যে, এরা না আবার কোন বিপদে ফেলে দেয়। ফেরাউন দেশময় কর্তꦣ2499;ত্বের শিখরে আরোহণ করেছিল। আর সে তার হাত ছেড়ে রেখেছিল।'),
  ('bn.bengali', 10, 84, 'আর মূসা বলল, হে আমার সম্প্রদায়, তোমরা যদি আল্লাহর উপর ঈমান এনে থাক, তবে তারই উপর ভরসা কর যদি তোমরা ফরমাবরদার হয়ে থাক।'),
  ('bn.bengali', 10, 85, 'তখন তারা বলল, আমরা আল্লাহর উপর ভরসা করেছি। হে আমাদের পালনকর্তা, আমাদের উপর এ জালেম কওমের শক্তি পরীক্ষা করিও না।'),
  ('bn.bengali', 10, 86, 'আর আমাদেরকে অনুগ্রহ করে ছাড়িয়ে দাও এই কাফেরদের কবল থেকে।'),
  ('bn.bengali', 10, 87, 'আর আমি নির্দেশ পাঠালাম মূসা এবং তার ভাইয়ের প্রতি যে, তোমরা তোমাদের জাতির জন্য মিসরের মাটিতে বাস স্থান নির্ধারণ কর। আর তোমাদের ঘরগুলো বানাবে কেবলামুখী করে এবং নামায কায়েম কর আর যারা ঈমানদার তাদেরকে সুসংবাদ দান কর।'),
  ('bn.bengali', 10, 88, 'মূসা বলল, হে আমার পরওয়ারদেগার, তুমি ফেরাউনকে এবং তার সর্দারদেরকে পার্থব জীবনের আড়ম্বর দান করেছ, এবং সম্পদ দান করেছ-হে আমার পরওয়ারদেগার, এ জন্যই যে তারা তোমার পথ থেকে বিপথগামী করব! হে আমার পরওয়ারদেগার, তাদের ধন-সম্পদ ধ্বংস করে দাও এবং তাদের অন্তরগুলোকে কাঠোর করে দাও যাতে করে তারা ততক্ষণ পর্যন্ত ঈমান না আনে যতক্ষণ না বেদনাদায়ক আযাব প্রত্যক্ষ করে নেয়।'),
  ('bn.bengali', 10, 89, 'বললেন, তোমাদের দোয়া মঞ্জুর হয়েছে। অতএব তোমরা দুজন অটল থাকো এবং তাদের পথে চলো না যারা অজ্ঞ।'),
  ('bn.bengali', 10, 90, 'আর বনী-ইসরাঈলকে আমি পার করে দিয়েছি নদী। তারপর তাদের পশ্চাদ্ধাবন করেছে ফেরাউন ও তার সেনাবাহিনী, দুরাচার ও বাড়াবাড়ির উদ্দেশে। এমনকি যখন তারা ডুবতে আরম্ভ করল, তখন বলল, এবার বিশ্বাস করে নিচ্ছি যে, কোন মা’বুদ নেই তাঁকে ছাড়া যাঁর উপর ঈমান এনেছে বনী-ইসরাঈলরা। বস্তুতঃ আমিও তাঁরই অনুগতদের অন্তর্ভুক্ত।'),
  ('bn.bengali', 10, 91, 'এখন একথা বলছ! অথচ তুমি ইতিপূর্বে না-ফরমানী করছিলে। এবং পথভ্রষ্টদেরই অন্তর্ভুক্ত ছিলে।'),
  ('bn.bengali', 10, 92, 'অতএব আজকের দিনে বাঁচিয়ে দিচ্ছি আমি তোমার দেহকে যাতে তোমার পশ্চাদবর্তীদের জন্য নিদর্শন হতে পারে। আর নিঃসন্দেহে বহু লোক আমার মহাশক্তির প্রতি লক্ষ্য করে না।'),
  ('bn.bengali', 10, 93, 'আর আমি বনী-ইসরাঈলদিগকে দান করেছি উত্তম স্থান এবং তাদেরকে আহার্য দিয়েছি পবিত্র-পরিচ্ছন্ন বস্তু-সামগ্রী। বস্তুতঃ তাদের মধ্যে মতবিরোধ হয়নি যতক্ষণ না তাদের কাছে এসে পৌছেছে সংবাদ। নিঃসন্দেহে তোমার পরওয়ারদেগার তাদের মাঝে মীমাংসা করে দেবেন কেয়ামতের দিন; যে ব্যাপারে তাদের মাঝে মতবিরোধ হয়েছিল'),
  ('bn.bengali', 10, 94, 'সুতরাং তুমি যদি সে বস্তু সম্পর্কে কোন সন্দেহের সম্মুখীন হয়ে থাক যা তোমার প্রতি আমি নাযিল করেছি, তবে তাদেরকে জিজ্ঞেস করো যারা তোমার পূর্ব থেকে কিতাব পাঠ করছে। এতে কোন সন্দেহ নেই যে, তোমার পরওয়ারদেগারের নিকট থেকে তোমার নিকট সত্য বিষয় এসেছে। কাজেই তুমি কস্মিনকালেও সন্দেহকারী হয়ো না।'),
  ('bn.bengali', 10, 95, 'এবং তাদের অন্তর্ভুক্তও হয়ো না যারা মিথ্যা প্রতিপন্ন করেছে আল্লাহর বাণীকে। তাহলে তুমিও অকল্যাণে পতিত হয়ে যাবে।'),
  ('bn.bengali', 10, 96, 'যাদের ব্যাপারে তোমার পরওয়ারদেগারের সিদ্ধান্ত নির্ধারিত হয়ে গেছে তারা ঈমান আনবে না।'),
  ('bn.bengali', 10, 97, 'যদি তাদের সামনে সমস্ত নিদর্শনাবলী এসে উপস্থিত হয় তবুও যতক্ষণ না তারা দেখতে পায় বেদনাদায়ক আযাব।'),
  ('bn.bengali', 10, 98, 'সুতরাং কোন জনপদ কেন এমন হল না যা ঈমান এনেছে অতঃপর তার সে ঈমান গ্রহণ হয়েছে কল্যাণকর? অবশ্য ইউনুসের সম্প্রদায়ের কথা আলাদা। তারা যখন ঈমান আনে তখন আমি তুলে নেই তাদের উপর থেকে অপমানজনক আযাব-পার্থিব জীবনে এবং তাদের কে কল্যাণ পৌছাই এক নিধারিত সময় পর্যন্ত।'),
  ('bn.bengali', 10, 99, 'আর তোমার পরওয়ারদেগার যদি চাইতেন, তবে পৃথিবীর বুকে যারা রয়েছে, তাদের সবাই ঈমান নিয়ে আসতে সমবেতভাবে। তুমি কি মানুষের উপর জবরদস্তী করবে ঈমান আনার জন্য?'),
  ('bn.bengali', 10, 100, 'আর কারো ঈমান আনা হতে পারে না, যতক্ষণ না আল্লাহর হুকুম হয়। পক্ষান্তরে তিনি অপবিত্রতা আরোপ করেন যারা বুদ্ধি প্রয়োগ করে না তাদের উপর।'),
  ('bn.bengali', 10, 101, 'তাহলে আপনি বলে দিন, চেয়ে দেখ তো আসমানসমুহে ও যমীনে কি রয়েছে। আর কোন নিদর্শন এবং কোন ভীতিপ্রর্দশনই কোন কাজে আসে না সেসব লোকের জন্য যারা মান্য করে না।'),
  ('bn.bengali', 10, 102, 'সুতরাং এখন আর এমন কিছু নেই, যার অপেক্ষা করবে, কিন্তু সেসব দিনের মতই দিন, যা অতীত হয়ে গেছে এর পূর্বে। আপনি বলুন; এখন পথ দেখ; আমিও তোমাদের সাথে পথ চেয়ে রইলাম।'),
  ('bn.bengali', 10, 103, 'অতঃপর আমি বাঁচিয়ে নেই নিজের রসূলগণকে এবং তাদেরকে যারা ঈমান এনেছে এমনিভাবে। ঈমানদারদের বাঁচিয়ে নেয়া আমার দায়িত্বও বটে।'),
  ('bn.bengali', 10, 104, 'বলে দাও-হে মানবকুল, তোমরা যদি আমার দ্বীনের ব্যাপারে সন্দিহান হয়ে থাক, তবে (জেনো) আমি তাদের এবাদত করি না যাদের এবাদত তোমরা কর আল্লাহ ব্যতীত। কিন্তু আমি এবাদত করি আল্লাহ ত’য়ালার, যিনি তুলে নেন তোমাদেরকে। আর আমার প্রতি নির্দেশ হয়েছে যাতে আমি ঈমানদারদের অন্তর্ভুক্ত থাকি।'),
  ('bn.bengali', 10, 105, 'আর যেন সোজা দ্বীনের প্রতি মুখ করি সরল হয়ে এবং যেন মুশরেকদের অন্তর্ভুক্ত না হই।'),
  ('bn.bengali', 10, 106, 'আর নির্দেশ হয়েছে আল্লাহ ব্যতীত এমন কাউকে ডাকবে না, যে তোমার ভাল করবে না মন্দও করবে না। বস্তুতঃ তুমি যদি এমন কাজ কর, তাহলে তখন তুমিও জালেমদের অন্তর্ভুক্ত হয়ে যাবে।'),
  ('bn.bengali', 10, 107, 'আর আল্লাহ যদি তোমার উপর কোন কষ্ট আরোপ করেন তাহলে কেউ নেই তা খন্ডাবার মত তাঁকে ছাড়া। পক্ষান্তরে যদি তিনি কিছু কল্যাণ দান করেন, তবে তার মেহেরবানীকে রহিত করার মতও কেউ নেই। তিনি যার প্রতি অনুগ্রহ দান করতে চান স্বীয় বান্দাদের মধ্যে তাকেই দান করেন; বস্তুত; তিনিই ক্ষমাশীল দয়ালু।'),
  ('bn.bengali', 10, 108, 'বলে দাও, হে মানবকুল, সত্য তোমাদের কাছে পৌঁছে গেছে তোমাদের পরওয়ারদেগারের তরফ থেকে। এমন যে কেউ পথে আসে সেপথ প্রাপ্ত হয় স্বীয় মঙ্গলের জন্য। আর যে বিভ্রান্ত ঘুরতে থাকে, সে স্বীয় অমঙ্গলের জন্য বিভ্রান্ত অবস্থায় ঘুরতে থাকবে। অনন্তর আমি তোমাদের উপর অধিকারী নই।'),
  ('bn.bengali', 10, 109, 'আর তুমি চল সে অনুযায়ী যেমন নির্দেশ আসে তোমার প্রতি এবং সবর কর, যতক্ষণ না ফয়সালা করেন আল্লাহ। বস্তুতঃ তিনি হচ্ছেন সর্বোত্তম ফয়সালাকারী।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 10, 1, 'Alif. Lam. Ra. These are verses of the Wise Scripture.'),
  ('en.pickthall', 10, 2, 'Is it a wonder for mankind that We have inspired a man among them, saying: Warn mankind and bring unto those who believe the good tidings that they have a sure footing with their Lord? The disbelievers say: Lo! this is a mere wizard.'),
  ('en.pickthall', 10, 3, 'Lo! your Lord is Allah Who created the heavens and the earth in six Days, then He established Himself upon the Throne, directing all things. There is no intercessor (with Him) save after His permission. That is Allah, your Lord, so worship Him. Oh, will ye not remind?'),
  ('en.pickthall', 10, 4, 'Unto Him is the return of all of you; it is a promise of Allah in truth. Lo! He produceth creation, then reproduceth it, that He may reward those who believe and do good works with equity; while, as for those who disbelieve, theirs will be a boiling drink and painful doom because they disbelieved.'),
  ('en.pickthall', 10, 5, 'He it is Who appointed the sun a splendour and the moon a light, and measured for her stages, that ye might know the number of the years, and the reckoning. Allah created not (all) that save in truth. He detaileth the revelations for people who have knowledge.'),
  ('en.pickthall', 10, 6, 'Lo! in the difference of day and night and all that Allah hath created in the heavens and the earth are portents, verily, for folk who ward off (evil).'),
  ('en.pickthall', 10, 7, 'Lo! those who expect not the meeting with Us but desire the life of the world and feel secure therein, and those who are neglectful of Our revelations,'),
  ('en.pickthall', 10, 8, 'Their home will be the Fire because of what they used to earn.'),
  ('en.pickthall', 10, 9, 'Lo! those who believe and do good works, their Lord guideth them by their faith. Rivers will flow beneath them in the Gardens of Delight,'),
  ('en.pickthall', 10, 10, 'Their prayer therein will be: Glory be to Thee, O Allah! and their greeting therein will be: Peace. And the conclusion of their prayer will be: Praise be to Allah, Lord of the Worlds!'),
  ('en.pickthall', 10, 11, 'If Allah were to hasten on for men the ill (that they have earned) as they would hasten on the good, their respite would already have expired. But We suffer those who look not for the meeting with Us to wander blindly on in their contumacy.'),
  ('en.pickthall', 10, 12, 'And if misfortune touch a man he crieth unto Us, (while reclining) on his side, or sitting or standing, but when We have relieved him of the misfortune he goeth his way as though he had not cried unto Us because of a misfortune that afflicted him. Thus is what they do made (seeming) fair unto the prodigal.'),
  ('en.pickthall', 10, 13, 'We destroyed the generations before you when they did wrong; and their messengers (from Allah) came unto them with clear proofs (of His Sovereignty) but they would not believe. Thus do We reward the guilty folk.'),
  ('en.pickthall', 10, 14, 'Then We appointed you viceroys in the earth after them, that We might see how ye behave.'),
  ('en.pickthall', 10, 15, 'And when Our clear revelations are recited unto them, they who look not for the meeting with Us say: Bring a Lecture other than this, or change it. Say (O Muhammad): It is not for me to change it of my accord. I only follow that which is inspired in me. Lo! if I disobey my Lord I fear the retribution of an awful Day.'),
  ('en.pickthall', 10, 16, 'Say: If Allah had so willed I should not have recited it to you nor would He have made it known to you. I dwelt among you a whole lifetime before it (came to me). Have ye then no sense?'),
  ('en.pickthall', 10, 17, 'Who doeth greater wrong than he who inventeth a lie concerning Allah and denieth His revelations? Lo! the guilty never are successful.'),
  ('en.pickthall', 10, 18, 'They worship beside Allah that which neither hurteth them nor profiteth them, and they say: These are our intercessors with Allah. Say: Would ye inform Allah of (something) that He knoweth not in the heavens or in the earth? Praised be He and High Exalted above all that ye associate (with Him)!'),
  ('en.pickthall', 10, 19, 'Mankind were but one community; then they differed; and had it not been for a word that had already gone forth from thy Lord it had been judged between them in respect of that wherein they differ.'),
  ('en.pickthall', 10, 20, 'And they will say: If only a portent were sent down upon him from his Lord! Then say, (O Muhammad): The Unseen belongeth to Allah. So wait! Lo! I am waiting with you.'),
  ('en.pickthall', 10, 21, 'And when We cause mankind to taste of mercy after some adversity which had afflicted them, behold! they have some plot against Our revelations. Say: Allah is more swift in plotting. Lo! Our messengers write down that which ye plot.'),
  ('en.pickthall', 10, 22, 'He it is Who maketh you to go on the land and the sea till, when ye are in the ships and they sail with them with a fair breeze and they are glad therein, a storm-wind reacheth them and the wave cometh unto them from every side and they deem that they are overwhelmed therein; (then) they cry unto Allah, making their faith pure for Him only: If Thou deliver us from this, we truly will be of the thankful.'),
  ('en.pickthall', 10, 23, 'Yet when He hath delivered them, behold! they rebel in the earth wrongfully. O mankind! Your rebellion is only against yourselves. (Ye have) enjoyment of the life of the world; then unto Us is your return and We shall proclaim unto you what ye used to do.'),
  ('en.pickthall', 10, 24, 'The similitude of the life of the world is only as water which We send down from the sky, then the earth\'s growth of that which men and cattle eat mingleth with it till, when the earth hath taken on her ornaments and is embellished, and her people deem that they are masters of her, Our commandment cometh by night or by day and We make it as reaped corn as if it had not flourished yesterday. Thus do we expound the revelations for people who reflect.'),
  ('en.pickthall', 10, 25, 'And Allah summoneth to the abode of peace, and leadeth whom He will to a straight path.'),
  ('en.pickthall', 10, 26, 'For those who do good is the best (reward) and more (thereto). Neither dust nor ignominy cometh near their faces. Such are rightful owners of the Garden; they will abide therein.'),
  ('en.pickthall', 10, 27, 'And those who earn ill-deeds, (for them) requital of each ill-deed by the like thereof; and ignominy overtaketh them - They have no protector from Allah - as if their faces had been covered with a cloak of darkest night. Such are rightful owners of the Fire; they will abide therein.'),
  ('en.pickthall', 10, 28, 'On the day when We gather them all together, then We say unto those who ascribed partners (unto Us): Stand back, ye and your (pretended) partners (of Allah)! And We separate them, the one from the other, and their (pretended) partners say: It was not us ye worshipped.'),
  ('en.pickthall', 10, 29, 'Allah sufficeth as a witness between us and you, that we were unaware of your worship.'),
  ('en.pickthall', 10, 30, 'There doth every soul experience that which it did aforetime, and they are returned unto Allah, their rightful Lord, and that which they used to invent hath failed them.'),
  ('en.pickthall', 10, 31, 'Say (unto them, O Muhammad): Who provideth for you from the sky and the earth, or Who owneth hearing and sight; and Who bringeth forth the living from the dead and bringeth forth the dead from the living; and Who directeth the course? They will say: Allah. Then say: Will ye not then keep your duty (unto Him)?'),
  ('en.pickthall', 10, 32, 'Such then is Allah, your rightful Lord. After the Truth what is there saving error? How then are ye turned away!'),
  ('en.pickthall', 10, 33, 'Thus is the Word of thy Lord justified concerning those who do wrong: that they believe not.'),
  ('en.pickthall', 10, 34, 'Say: Is there of your partners (whom ye ascribe unto Allah) one that produceth Creation and then reproduceth it? Say: Allah produceth Creation, then reproduceth it. How then, are ye misled!'),
  ('en.pickthall', 10, 35, 'Say: Is there of your partners (whom ye ascribe unto Allah) one that leadeth to the Truth? Say: Allah leadeth to the Truth. Is He Who leadeth to the Truth more deserving that He should be followed, or he who findeth not the way unless he (himself) be guided. What aileth you? How judge ye?'),
  ('en.pickthall', 10, 36, 'Most of them follow not but conjecture. Assuredly conjecture can by no means take the place of truth. Lo! Allah is Aware of what they do.'),
  ('en.pickthall', 10, 37, 'And this Qur\'an is not such as could ever be invented in despite of Allah; but it is a confirmation of that which was before it and an exposition of that which is decreed for mankind - Therein is no doubt - from the Lord of the Worlds.'),
  ('en.pickthall', 10, 38, 'Or say they: He hath invented it? Say: Then bring a surah like unto it, and call (for help) on all ye can besides Allah, if ye are truthful.'),
  ('en.pickthall', 10, 39, 'Nay, but they denied that, the knowledge whereof they could not compass, and whereof the interpretation (in events) hath not yet come unto them. Even so did those before them deny. Then see what was the consequence for the wrong-doers!'),
  ('en.pickthall', 10, 40, 'And of them is he who believeth therein, and of them is he who believeth not therein, and thy Lord is Best Aware of the corrupters.'),
  ('en.pickthall', 10, 41, 'And if they deny thee, say: Unto me my work, and unto you your work. Ye are innocent of what I do, and I am innocent of what ye do.'),
  ('en.pickthall', 10, 42, 'And of them are some who listen unto thee. But canst thou make the deaf to hear even though they apprehend not?'),
  ('en.pickthall', 10, 43, 'And of them is he who looketh toward thee. But canst thou guide the blind even though they see not?'),
  ('en.pickthall', 10, 44, 'Lo! Allah wrongeth not mankind in aught; but mankind wrong themselves.'),
  ('en.pickthall', 10, 45, 'And on the day when He shall gather them together, (when it will seem) as though they had tarried but an hour of the day, recognising one another, those will verily have perished who denied the meeting with Allah and were not guided.'),
  ('en.pickthall', 10, 46, 'Whether We let thee (O Muhammad) behold something of that which We promise them or (whether We) cause thee to die, still unto Us is their return, and Allah, moreover, is Witness over what they do.'),
  ('en.pickthall', 10, 47, 'And for every nation there is a messenger. And when their messenger cometh (on the Day of Judgment) it will be judged between them fairly, and they will not be wronged.'),
  ('en.pickthall', 10, 48, 'And they say: When will this promise be fulfilled, if ye are truthful?'),
  ('en.pickthall', 10, 49, 'Say: I have no power to hurt or benefit myself, save that which Allah willeth. For every nation there is an appointed time. When their time cometh, then they cannot put it off an hour, nor hasten (it).'),
  ('en.pickthall', 10, 50, 'Say: Have ye thought: When His doom cometh unto you as a raid by night, or in the (busy) day; what is there of it that the guilty ones desire to hasten?'),
  ('en.pickthall', 10, 51, 'Is it (only) then, when it hath befallen you, that ye will believe? What! (Believe) now, when (until now) ye have been hastening it on (through disbelief)?'),
  ('en.pickthall', 10, 52, 'Then will it be said unto those who dealt unjustly Taste the torment of eternity. Are ye requited aught save what ye used to earn?'),
  ('en.pickthall', 10, 53, 'And they ask thee to inform them (saying): Is it true? Say: Yea, by my Lord, verily it is true, and ye cannot escape.'),
  ('en.pickthall', 10, 54, 'And if each soul that doeth wrong had all that is in the earth it would seek to ransom itself therewith; and they will feel remorse within them, when they see the doom. But it hath been judged between them fairly and they are not wronged.'),
  ('en.pickthall', 10, 55, 'Lo! verily all that is in the heavens and the earth is Allah\'s. Lo! verily Allah\'s promise is true. But most of them know not.'),
  ('en.pickthall', 10, 56, 'He quickeneth and giveth death, and unto Him ye will be returned.'),
  ('en.pickthall', 10, 57, 'O mankind! There hath come unto you an exhortation from your Lord, a balm for that which is in the breasts, a guidance and a mercy for believers.'),
  ('en.pickthall', 10, 58, 'Say: In the bounty of Allah and in His mercy: therein let them rejoice. It is better than what they hoard.'),
  ('en.pickthall', 10, 59, 'Say: Have ye considered what provision Allah hath sent down for you, how ye have made of it lawful and unlawful? Hath Allah permitted you, or do ye invent a lie concerning Allah?'),
  ('en.pickthall', 10, 60, 'And what think those who invent a lie concerning Allah (will be their plight) upon the Day of Resurrection? Lo! Allah truly is Bountiful toward mankind, but most of them give not thanks.'),
  ('en.pickthall', 10, 61, 'And thou (Muhammad) art not occupied with any business and thou recitest not a Lecture from this (Scripture), and ye (mankind) perform no act, but We are Witness of you when ye are engaged therein. And not an atom\'s weight in the earth or in the sky escapeth your Lord, nor what is less than that or greater than that, but it is (written) in a clear Book.'),
  ('en.pickthall', 10, 62, 'Lo! verily the friends of Allah are (those) on whom fear (cometh) not, nor do they grieve?'),
  ('en.pickthall', 10, 63, 'Those who believe and keep their duty (to Allah).'),
  ('en.pickthall', 10, 64, 'Theirs are good tidings in the life of the world and in the Hereafter - There is no changing the Words of Allah - that is the Supreme Triumph.'),
  ('en.pickthall', 10, 65, 'And let not their speech grieve thee (O Muhammad). Lo! power belongeth wholly to Allah. He is the Hearer, the Knower.'),
  ('en.pickthall', 10, 66, 'Lo! is it not unto Allah that belongeth whosoever is in the heavens and whosoever is in the earth? Those who follow aught instead of Allah follow not (His) partners. They follow only a conjecture, and they do but guess.'),
  ('en.pickthall', 10, 67, 'He it is Who hath appointed for you the night that ye should rest therein and the day giving sight. Lo! herein verily are portents for a folk that heed.'),
  ('en.pickthall', 10, 68, 'They say: Allah hath taken (unto Him) a son - Glorified be He! He hath no needs! His is all that is in the heavens and all that is in the earth. Ye have no warrant for this. Tell ye concerning Allah that which ye know not?'),
  ('en.pickthall', 10, 69, 'Say: Verily those who invent a lie concerning Allah will not succeed.'),
  ('en.pickthall', 10, 70, 'This world\'s portion (will be theirs), then unto Us is their return. Then We make them taste a dreadful doom because they used to disbelieve.'),
  ('en.pickthall', 10, 71, 'Recite unto them the story of Noah, when he told his people: O my people! If my sojourn (here) and my reminding you by Allah\'s revelations are an offence unto you, in Allah have I put my trust, so decide upon your course of action you and your partners. Let not your course of action be in doubt for you. Then have at me, give me no respite.'),
  ('en.pickthall', 10, 72, 'But if ye are averse I have asked of you no wage. My wage is the concern of Allah only, and I am commanded to be of those who surrender (unto Him).'),
  ('en.pickthall', 10, 73, 'But they denied him, so We saved him and those with him in the ship, and made them viceroys (in the earth), while We drowned those who denied Our revelations. See then the nature of the consequence for those who had been warned.'),
  ('en.pickthall', 10, 74, 'Then, after him, We sent messengers unto their folk, and they brought them clear proofs. But they were not ready to believe in that which they before denied. Thus print We on the hearts of the transgressors.'),
  ('en.pickthall', 10, 75, 'Then, after them, We sent Moses and Aaron unto Pharaoh and his chiefs with Our revelations, but they were arrogant and were a guilty folk.'),
  ('en.pickthall', 10, 76, 'And when the Truth from Our presence came unto them, they said: Lo! this is mere magic.'),
  ('en.pickthall', 10, 77, 'Moses said: Speak ye (so) of the Truth when it hath come unto you? Is this magic? Now magicians thrive not.'),
  ('en.pickthall', 10, 78, 'They said: Hast thou come unto us to pervert us from that (faith) in which we found our fathers, and that you two may own the place of greatness in the land? We will not believe you two.'),
  ('en.pickthall', 10, 79, 'And Pharaoh said: Bring every cunning wizard unto me.'),
  ('en.pickthall', 10, 80, 'And when the wizards came, Moses said unto them: Cast your cast!'),
  ('en.pickthall', 10, 81, 'And when they had cast, Moses said: That which ye have brought is magic. Lo! Allah will make it vain. Lo! Allah upholdeth not the work of mischief-makers.'),
  ('en.pickthall', 10, 82, 'And Allah will vindicate the Truth by His words, however much the guilty be averse.'),
  ('en.pickthall', 10, 83, 'But none trusted Moses, save some scions of his people, (and they were) in fear of Pharaoh and their chiefs, that he would persecute them. Lo! Pharaoh was verily a tyrant in the land, and lo! he verily was of the wanton.'),
  ('en.pickthall', 10, 84, 'And Moses said: O my people! If ye have believed in Allah then put trust in Him, if ye have indeed surrendered (unto Him)!'),
  ('en.pickthall', 10, 85, 'They said: In Allah we put trust. Our Lord! Oh, make us not a lure for the wrongdoing folk;'),
  ('en.pickthall', 10, 86, 'And, of Thy mercy, save us from the folk that disbelieve.'),
  ('en.pickthall', 10, 87, 'And We inspired Moses and his brother, (saying): Appoint houses for your people in Egypt and make your houses oratories, and establish worship. And give good news to the believers.'),
  ('en.pickthall', 10, 88, 'And Moses said: Our Lord! Lo! Thou hast given Pharaoh and his chiefs splendour and riches in the life of the world, Our Lord! that they may lead men astray from Thy way. Our Lord! Destroy their riches and harden their hearts so that they believe not till they see the painful doom.'),
  ('en.pickthall', 10, 89, 'He said: Your prayer is heard. Do ye twain keep to the straight path, and follow not the road of those who have no knowledge.'),
  ('en.pickthall', 10, 90, 'And We brought the Children of Israel across the sea, and Pharaoh with his hosts pursued them in rebellion and transgression, till, when the (fate of) drowning overtook him, he exclaimed: I believe that there is no Allah save Him in Whom the Children of Israel believe, and I am of those who surrender (unto Him).'),
  ('en.pickthall', 10, 91, 'What! Now! When hitherto thou hast rebelled and been of the wrong-doers?'),
  ('en.pickthall', 10, 92, 'But this day We save thee in thy body that thou mayst be a portent for those after thee. Lo! most of mankind are heedless of Our portents.'),
  ('en.pickthall', 10, 93, 'And We verily did allot unto the Children of Israel a fixed abode, and did provide them with good things; and they differed not until the knowledge came unto them. Lo! thy Lord will judge between them on the Day of Resurrection concerning that wherein they used to differ.'),
  ('en.pickthall', 10, 94, 'And if thou (Muhammad) art in doubt concerning that which We reveal unto thee, then question those who read the Scripture (that was) before thee. Verily the Truth from thy Lord hath come unto thee. So be not thou of the waverers.'),
  ('en.pickthall', 10, 95, 'And be not thou of those who deny the revelations of Allah, for then wert thou of the losers.'),
  ('en.pickthall', 10, 96, 'Lo! those for whom the word of thy Lord (concerning sinners) hath effect will not believe,'),
  ('en.pickthall', 10, 97, 'Though every token come unto them, till they see the painful doom.'),
  ('en.pickthall', 10, 98, 'If only there had been a community (of all those that were destroyed of old) that believed and profited by its belief as did the folk of Jonah! When they believed We drew off from them the torment of disgrace in the life of the world and gave them comfort for a while.'),
  ('en.pickthall', 10, 99, 'And if thy Lord willed, all who are in the earth would have believed together. Wouldst thou (Muhammad) compel men until they are believers?'),
  ('en.pickthall', 10, 100, 'It is not for any soul to believe save by the permission of Allah. He hath set uncleanness upon those who have no sense.'),
  ('en.pickthall', 10, 101, 'Say: Behold what is in the heavens and the earth! But revelations and warnings avail not folk who will not believe.'),
  ('en.pickthall', 10, 102, 'What expect they save the like of the days of those who passed away before them? Say: Expect then! I am with you among the expectant.'),
  ('en.pickthall', 10, 103, 'Then shall We save Our messengers and the believers, in like manner (as of old). It is incumbent upon Us to save believers.'),
  ('en.pickthall', 10, 104, 'Say (O Muhammad): O mankind! If ye are in doubt of my religion, then (know that) I worship not those whom ye worship instead of Allah, but I worship Allah Who causeth you to die, and I have been commanded to be of the believers.'),
  ('en.pickthall', 10, 105, 'And, (O Muhammad) set thy purpose resolutely for religion, as a man by nature upright, and be not of those who ascribe partners (to Allah).'),
  ('en.pickthall', 10, 106, 'And cry not, beside Allah, unto that which cannot profit thee nor hurt thee, for if thou didst so then wert thou of the wrong-doers.'),
  ('en.pickthall', 10, 107, 'If Allah afflicteth thee with some hurt, there is none who can remove it save Him; and if He desireth good for thee, there is none who can repel His bounty. He striketh with it whom He will of his bondmen. He is the Forgiving, the Merciful.'),
  ('en.pickthall', 10, 108, 'Say: O mankind! Now hath the Truth from your Lord come unto you. So whosoever is guided, is guided only for (the good of) his soul, and whosoever erreth erreth only against it. And I am not a warder over you.'),
  ('en.pickthall', 10, 109, 'And (O Muhammad) follow that which is inspired in thee, and forbear until Allah give judgment. And He is the Best of Judges.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 10, 1, 'A. L. R. These are the ayats of the Book of Wisdom.'),
  ('en.yusufali', 10, 2, 'Is it a matter of wonderment to men that We have sent Our inspiration to a man from among themselves?- that he should warn mankind (of their danger), and give the good news to the Believers that they have before their Lord the lofty rank of truth. (But) say the Unbelievers: "This is indeed an evident sorcerer!"'),
  ('en.yusufali', 10, 3, 'Verily your Lord is Allah, who created the heavens and the earth in six days, and is firmly established on the throne (of authority), regulating and governing all things. No intercessor (can plead with Him) except after His leave (hath been obtained). This is Allah your Lord; Him therefore serve ye: will ye not receive admonition?'),
  ('en.yusufali', 10, 4, 'To Him will be your return- of all of you. The promise of Allah is true and sure. It is He Who beginneth the process of creation, and repeateth it, that He may reward with justice those who believe and work righteousness; but those who reject Him will have draughts of boiling fluids, and a penalty grievous, because they did reject Him.'),
  ('en.yusufali', 10, 5, 'It is He Who made the sun to be a shining glory and the moon to be a light (of beauty), and measured out stages for her; that ye might know the number of years and the count (of time). Nowise did Allah create this but in truth and righteousness. (Thus) doth He explain His Signs in detail, for those who understand.'),
  ('en.yusufali', 10, 6, 'Verily, in the alternation of the night and the day, and in all that Allah hath created, in the heavens and the earth, are signs for those who fear Him.'),
  ('en.yusufali', 10, 7, 'Those who rest not their hope on their meeting with Us, but are pleased and satisfied with the life of the present, and those who heed not Our Signs,-'),
  ('en.yusufali', 10, 8, 'Their abode is the Fire, because of the (evil) they earned.'),
  ('en.yusufali', 10, 9, 'Those who believe, and work righteousness,- their Lord will guide them because of their faith: beneath them will flow rivers in gardens of bliss.'),
  ('en.yusufali', 10, 10, '(This will be) their cry therein: "Glory to Thee, O Allah!" And "Peace" will be their greeting therein! and the close of their cry will be: "Praise be to Allah, the Cherisher and Sustainer of the worlds!"'),
  ('en.yusufali', 10, 11, 'If Allah were to hasten for men the ill (they have earned) as they would fain hasten on the good,- then would their respite be settled at once. But We leave those who rest not their hope on their meeting with Us, in their trespasses, wandering in distraction to and fro.'),
  ('en.yusufali', 10, 12, 'When trouble toucheth a man, He crieth unto Us (in all postures)- lying down on his side, or sitting, or standing. But when We have solved his trouble, he passeth on his way as if he had never cried to Us for a trouble that touched him! thus do the deeds of transgressors seem fair in their eyes!'),
  ('en.yusufali', 10, 13, 'Generations before you We destroyed when they did wrong: their messengers came to them with clear-signs, but they would not believe! thus do We requite those who sin!'),
  ('en.yusufali', 10, 14, 'Then We made you heirs in the land after them, to see how ye would behave!'),
  ('en.yusufali', 10, 15, 'But when Our Clear Signs are rehearsed unto them, those who rest not their hope on their meeting with Us, Say: "Bring us a reading other than this, or change this," Say: "It is not for me, of my own accord, to change it: I follow naught but what is revealed unto me: if I were to disobey my Lord, I should myself fear the penalty of a Great Day (to come)."'),
  ('en.yusufali', 10, 16, 'Say: "If Allah had so willed, I should not have rehearsed it to you, nor would He have made it known to you. A whole life-time before this have I tarried amongst you: will ye not then understand?"'),
  ('en.yusufali', 10, 17, 'Who doth more wrong than such as forge a lie against Allah, or deny His Signs? But never will prosper those who sin.'),
  ('en.yusufali', 10, 18, 'They serve, besides Allah, things that hurt them not nor profit them, and they say: "These are our intercessors with Allah." Say: "Do ye indeed inform Allah of something He knows not, in the heavens or on earth?- Glory to Him! and far is He above the partners they ascribe (to Him)!"'),
  ('en.yusufali', 10, 19, 'Mankind was but one nation, but differed (later). Had it not been for a word that went forth before from thy Lord, their differences would have been settled between them.'),
  ('en.yusufali', 10, 20, 'They say: "Why is not a sign sent down to him from his Lord?" Say: "The Unseen is only for Allah (to know), then wait ye: I too will wait with you."'),
  ('en.yusufali', 10, 21, 'When We make mankind taste of some mercy after adversity hath touched them, behold! they take to plotting against Our Signs! Say: "Swifter to plan is Allah!" Verily, Our messengers record all the plots that ye make!'),
  ('en.yusufali', 10, 22, 'He it is Who enableth you to traverse through land and sea; so that ye even board ships;- they sail with them with a favourable wind, and they rejoice thereat; then comes a stormy wind and the waves come to them from all sides, and they think they are being overwhelmed: they cry unto Allah, sincerely offering (their) duty unto Him saying, "If thou dost deliver us from this, we shall truly show our gratitude!"'),
  ('en.yusufali', 10, 23, 'But when he delivereth them, behold! they transgress insolently through the earth in defiance of right! O mankind! your insolence is against your own souls,- an enjoyment of the life of the present: in the end, to Us is your return, and We shall show you the truth of all that ye did.'),
  ('en.yusufali', 10, 24, 'The likeness of the life of the present is as the rain which We send down from the skies: by its mingling arises the produce of the earth- which provides food for men and animals: (It grows) till the earth is clad with its golden ornaments and is decked out (in beauty): the people to whom it belongs think they have all powers of disposal over it: There reaches it Our command by night or by day, and We make it like a harvest clean-mown, as if it had not flourished only the day before! thus do We explain the Signs in detail for those who reflect.'),
  ('en.yusufali', 10, 25, 'But Allah doth call to the Home of Peace: He doth guide whom He pleaseth to a way that is straight.'),
  ('en.yusufali', 10, 26, 'To those who do right is a goodly (reward)- Yea, more (than in measure)! No darkness nor shame shall cover their faces! they are companions of the garden; they will abide therein (for aye)!'),
  ('en.yusufali', 10, 27, 'But those who have earned evil will have a reward of like evil: ignominy will cover their (faces): No defender will they have from (the wrath of) Allah: Their faces will be covered, as it were, with pieces from the depth of the darkness of night: they are companions of the Fire: they will abide therein (for aye)!'),
  ('en.yusufali', 10, 28, 'One day shall We gather them all together. Then shall We say to those who joined gods (with Us): "To your place! ye and those ye joined as \'partners\' We shall separate them, and their "Partners" shall say: "It was not us that ye worshipped!'),
  ('en.yusufali', 10, 29, '"Enough is Allah for a witness between us and you: we certainly knew nothing of your worship of us!"'),
  ('en.yusufali', 10, 30, 'There will every soul prove (the fruits of) the deeds it sent before: they will be brought back to Allah their rightful Lord, and their invented falsehoods will leave them in the lurch.'),
  ('en.yusufali', 10, 31, 'Say: "Who is it that sustains you (in life) from the sky and from the earth? or who is it that has power over hearing and sight? And who is it that brings out the living from the dead and the dead from the living? and who is it that rules and regulates all affairs?" They will soon say, "Allah". Say, "will ye not then show piety (to Him)?"'),
  ('en.yusufali', 10, 32, 'Such is Allah, your real Cherisher and Sustainer: apart from truth, what (remains) but error? How then are ye turned away?'),
  ('en.yusufali', 10, 33, 'Thus is the word of thy Lord proved true against those who rebel: Verily they will not believe.'),
  ('en.yusufali', 10, 34, 'Say: "Of your \'partners\', can any originate creation and repeat it?" Say: "It is Allah Who originates creation and repeats it: then how are ye deluded away (from the truth)?"'),
  ('en.yusufali', 10, 35, 'Say: "Of your \'partners\' is there any that can give any guidance towards truth?" Say: "It is Allah Who gives guidance towards truth, is then He Who gives guidance to truth more worthy to be followed, or he who finds not guidance (himself) unless he is guided? what then is the matter with you? How judge ye?"'),
  ('en.yusufali', 10, 36, 'But most of them follow nothing but fancy: truly fancy can be of no avail against truth. Verily Allah is well aware of all that they do.'),
  ('en.yusufali', 10, 37, 'This Qur\'an is not such as can be produced by other than Allah; on the contrary it is a confirmation of (revelations) that went before it, and a fuller explanation of the Book - wherein there is no doubt - from the Lord of the worlds.'),
  ('en.yusufali', 10, 38, 'Or do they say, "He forged it"? say: "Bring then a Sura like unto it, and call (to your aid) anyone you can besides Allah, if it be ye speak the truth!"'),
  ('en.yusufali', 10, 39, 'Nay, they charge with falsehood that whose knowledge they cannot compass, even before the elucidation thereof hath reached them: thus did those before them make charges of falsehood: but see what was the end of those who did wrong!'),
  ('en.yusufali', 10, 40, 'Of them there are some who believe therein, and some who do not: and thy Lord knoweth best those who are out for mischief.'),
  ('en.yusufali', 10, 41, 'If they charge thee with falsehood, say: "My work to me, and yours to you! ye are free from responsibility for what I do, and I for what ye do!"'),
  ('en.yusufali', 10, 42, 'Among them are some who (pretend to) listen to thee: But canst thou make the deaf to hear,- even though they are without understanding?'),
  ('en.yusufali', 10, 43, 'And among them are some who look at thee: but canst thou guide the blind,- even though they will not see?'),
  ('en.yusufali', 10, 44, 'Verily Allah will not deal unjustly with man in aught: It is man that wrongs his own soul.'),
  ('en.yusufali', 10, 45, 'One day He will gather them together: (It will be) as if they had tarried but an hour of a day: they will recognise each other: assuredly those will be lost who denied the meeting with Allah and refused to receive true guidance.'),
  ('en.yusufali', 10, 46, 'Whether We show thee (realised in thy life-time) some part of what We promise them,- or We take thy soul (to Our Mercy) (Before that),- in any case, to Us is their return: ultimately Allah is witness, to all that they do.'),
  ('en.yusufali', 10, 47, 'To every people (was sent) a messenger: when their messenger comes (before them), the matter will be judged between them with justice, and they will not be wronged.'),
  ('en.yusufali', 10, 48, 'They say: "When will this promise come to pass,- if ye speak the truth?"'),
  ('en.yusufali', 10, 49, 'Say: "I have no power over any harm or profit to myself except as Allah willeth. To every people is a term appointed: when their term is reached, not an hour can they cause delay, nor (an hour) can they advance (it in anticipation)."'),
  ('en.yusufali', 10, 50, 'Say: "Do ye see,- if His punishment should come to you by night or by day,- what portion of it would the sinners wish to hasten?'),
  ('en.yusufali', 10, 51, '"Would ye then believe in it at last, when it actually cometh to pass? (It will then be said): \'Ah! now? and ye wanted (aforetime) to hasten it on!\''),
  ('en.yusufali', 10, 52, '"At length will be said to the wrong-doers: \'Taste ye the enduring punishment! ye get but the recompense of what ye earned!\'"'),
  ('en.yusufali', 10, 53, 'They seek to be informed by thee: "Is that true?" Say: "Aye! by my Lord! it is the very truth! and ye cannot frustrate it!"'),
  ('en.yusufali', 10, 54, 'Every soul that hath sinned, if it possessed all that is on earth, would fain give it in ransom: They would declare (their) repentance when they see the penalty: but the judgment between them will be with justice, and no wrong will be done unto them.'),
  ('en.yusufali', 10, 55, 'Is it not (the case) that to Allah belongeth whatever is in the heavens and on earth? Is it not (the case) that Allah\'s promise is assuredly true? Yet most of them understand not.'),
  ('en.yusufali', 10, 56, 'It is He Who giveth life and who taketh it, and to Him shall ye all be brought back.'),
  ('en.yusufali', 10, 57, 'O mankind! there hath come to you a direction from your Lord and a healing for the (diseases) in your hearts,- and for those who believe, a guidance and a Mercy.'),
  ('en.yusufali', 10, 58, 'Say: "In the bounty of Allah. And in His Mercy,- in that let them rejoice": that is better than the (wealth) they hoard.'),
  ('en.yusufali', 10, 59, 'Say: "See ye what things Allah hath sent down to you for sustenance? Yet ye hold forbidden some things thereof and (some things) lawful." Say: "Hath Allah indeed permitted you, or do ye invent (things) to attribute to Allah?"'),
  ('en.yusufali', 10, 60, 'And what think those who invent lies against Allah, of the Day of Judgment? Verily Allah is full of bounty to mankind, but most of them are ungrateful.'),
  ('en.yusufali', 10, 61, 'In whatever business thou mayest be, and whatever portion thou mayest be reciting from the Qur\'an,- and whatever deed ye (mankind) may be doing,- We are witnesses thereof when ye are deeply engrossed therein. Nor is hidden from thy Lord (so much as) the weight of an atom on the earth or in heaven. And not the least and not the greatest of these things but are recorded in a clear record.'),
  ('en.yusufali', 10, 62, 'Behold! verily on the friends of Allah there is no fear, nor shall they grieve;'),
  ('en.yusufali', 10, 63, 'Those who believe and (constantly) guard against evil;-'),
  ('en.yusufali', 10, 64, 'For them are glad tidings, in the life of the present and in the Hereafter; no change can there be in the words of Allah. This is indeed the supreme felicity.'),
  ('en.yusufali', 10, 65, 'Let not their speech grieve thee: for all power and honour belong to Allah: It is He Who heareth and knoweth (all things).'),
  ('en.yusufali', 10, 66, 'Behold! verily to Allah belong all creatures, in the heavens and on earth. What do they follow who worship as His "partners" other than Allah? They follow nothing but fancy, and they do nothing but lie.'),
  ('en.yusufali', 10, 67, 'He it is That hath made you the night that ye may rest therein, and the day to make things visible (to you). Verily in this are signs for those who listen (to His Message).'),
  ('en.yusufali', 10, 68, 'They say: "Allah hath begotten a son!" - Glory be to Him! He is self-sufficient! His are all things in the heavens and on earth! No warrant have ye for this! say ye about Allah what ye know not?'),
  ('en.yusufali', 10, 69, 'Say: "Those who invent a lie against Allah will never prosper."'),
  ('en.yusufali', 10, 70, 'A little enjoyment in this world!- and then, to Us will be their return, then shall We make them taste the severest penalty for their blasphemies.'),
  ('en.yusufali', 10, 71, 'Relate to them the story of Noah. Behold! he said to his people: "O my people, if it be hard on your (mind) that I should stay (with you) and commemorate the signs of Allah,- yet I put my trust in Allah. Get ye then an agreement about your plan and among your partners, so your plan be on to you dark and dubious. Then pass your sentence on me, and give me no respite.'),
  ('en.yusufali', 10, 72, '"But if ye turn back, (consider): no reward have I asked of you: my reward is only due from Allah, and I have been commanded to be of those who submit to Allah\'s will (in Islam)."'),
  ('en.yusufali', 10, 73, 'They rejected Him, but We delivered him, and those with him, in the Ark, and We made them inherit (the earth), while We overwhelmed in the flood those who rejected Our Signs. Then see what was the end of those who were warned (but heeded not)!'),
  ('en.yusufali', 10, 74, 'Then after him We sent (many) messengers to their peoples: they brought them Clear Signs, but they would not believe what they had already rejected beforehand. Thus do We seal the hearts of the transgressors.'),
  ('en.yusufali', 10, 75, 'Then after them sent We Moses and Aaron to Pharaoh and his chiefs with Our Signs. But they were arrogant: they were a people in sin.'),
  ('en.yusufali', 10, 76, 'When the Truth did come to them from Us, they said: "This is indeed evident sorcery!"'),
  ('en.yusufali', 10, 77, 'Said Moses: "Say ye (this) about the truth when it hath (actually) reached you? Is sorcery (like) this? But sorcerers will not prosper."'),
  ('en.yusufali', 10, 78, 'They said: "Hast thou come to us to turn us away from the ways we found our fathers following,- in order that thou and thy brother may have greatness in the land? But not we shall believe in you!"'),
  ('en.yusufali', 10, 79, 'Said Pharaoh: "Bring me every sorcerer well versed."'),
  ('en.yusufali', 10, 80, 'When the sorcerers came, Moses said to them: "Throw ye what ye (wish) to throw!"'),
  ('en.yusufali', 10, 81, 'When they had had their throw, Moses said: "What ye have brought is sorcery: Allah will surely make it of no effect: for Allah prospereth not the work of those who make mischief.'),
  ('en.yusufali', 10, 82, '"And Allah by His words doth prove and establish His truth, however much the sinners may hate it!"'),
  ('en.yusufali', 10, 83, 'But none believed in Moses except some children of his people, because of the fear of Pharaoh and his chiefs, lest they should persecute them; and certainly Pharaoh was mighty on the earth and one who transgressed all bounds.'),
  ('en.yusufali', 10, 84, 'Moses said: "O my people! If ye do (really) believe in Allah, then in Him put your trust if ye submit (your will to His)."'),
  ('en.yusufali', 10, 85, 'They said: "In Allah do we put out trust. Our Lord! make us not a trial for those who practise oppression;'),
  ('en.yusufali', 10, 86, '"And deliver us by Thy Mercy from those who reject (Thee)."'),
  ('en.yusufali', 10, 87, 'We inspired Moses and his brother with this Message: "Provide dwellings for your people in Egypt, make your dwellings into places of worship, and establish regular prayers: and give glad tidings to those who believe!"'),
  ('en.yusufali', 10, 88, 'Moses prayed: "Our Lord! Thou hast indeed bestowed on Pharaoh and his chiefs splendour and wealth in the life of the present, and so, Our Lord, they mislead (men) from Thy Path. Deface, our Lord, the features of their wealth, and send hardness to their hearts, so they will not believe until they see the grievous penalty."'),
  ('en.yusufali', 10, 89, 'Allah said: "Accepted is your prayer (O Moses and Aaron)! So stand ye straight, and follow not the path of those who know not."'),
  ('en.yusufali', 10, 90, 'We took the Children of Israel across the sea: Pharaoh and his hosts followed them in insolence and spite. At length, when overwhelmed with the flood, he said: "I believe that there is no god except Him Whom the Children of Israel believe in: I am of those who submit (to Allah in Islam)."'),
  ('en.yusufali', 10, 91, '(It was said to him): "Ah now!- But a little while before, wast thou in rebellion!- and thou didst mischief (and violence)!'),
  ('en.yusufali', 10, 92, '"This day shall We save thee in the body, that thou mayest be a sign to those who come after thee! but verily, many among mankind are heedless of Our Signs!"'),
  ('en.yusufali', 10, 93, 'We settled the Children of Israel in a beautiful dwelling-place, and provided for them sustenance of the best: it was after knowledge had been granted to them, that they fell into schisms. Verily Allah will judge between them as to the schisms amongst them, on the Day of Judgment.'),
  ('en.yusufali', 10, 94, 'If thou wert in doubt as to what We have revealed unto thee, then ask those who have been reading the Book from before thee: the Truth hath indeed come to thee from thy Lord: so be in no wise of those in doubt.'),
  ('en.yusufali', 10, 95, 'Nor be of those who reject the signs of Allah, or thou shalt be of those who perish.'),
  ('en.yusufali', 10, 96, 'Those against whom the word of thy Lord hath been verified would not believe-'),
  ('en.yusufali', 10, 97, 'Even if every Sign was brought unto them,- until they see (for themselves) the penalty grievous.'),
  ('en.yusufali', 10, 98, 'Why was there not a single township (among those We warned), which believed,- so its faith should have profited it,- except the people of Jonah? When they believed, We removed from them the penalty of ignominy in the life of the present, and permitted them to enjoy (their life) for a while.'),
  ('en.yusufali', 10, 99, 'If it had been thy Lord\'s will, they would all have believed,- all who are on earth! wilt thou then compel mankind, against their will, to believe!'),
  ('en.yusufali', 10, 100, 'No soul can believe, except by the will of Allah, and He will place doubt (or obscurity) on those who will not understand.'),
  ('en.yusufali', 10, 101, 'Say: "Behold all that is in the heavens and on earth"; but neither Signs nor Warners profit those who believe not.'),
  ('en.yusufali', 10, 102, 'Do they then expect (any thing) but (what happened in) the days of the men who passed away before them? Say: "Wait ye then: for I, too, will wait with you."'),
  ('en.yusufali', 10, 103, 'In the end We deliver Our messengers and those who believe: Thus is it fitting on Our part that We should deliver those who believe!'),
  ('en.yusufali', 10, 104, 'Say: "O ye men! If ye are in doubt as to my religion, (behold!) I worship not what ye worship, other than Allah! But I worship Allah - Who will take your souls (at death): I am commanded to be (in the ranks) of the Believers,'),
  ('en.yusufali', 10, 105, '"And further (thus): \'set thy face towards religion with true piety, and never in any wise be of the Unbelievers;'),
  ('en.yusufali', 10, 106, '"\'Nor call on any, other than Allah;- Such will neither profit thee nor hurt thee: if thou dost, behold! thou shalt certainly be of those who do wrong.\'"'),
  ('en.yusufali', 10, 107, 'If Allah do touch thee with hurt, there is none can remove it but He: if He do design some benefit for thee, there is none can keep back His favour: He causeth it to reach whomsoever of His servants He pleaseth. And He is the Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 10, 108, 'Say: "O ye men! Now Truth hath reached you from your Lord! those who receive guidance, do so for the good of their own souls; those who stray, do so to their own loss: and I am not (set) over you to arrange your affairs."'),
  ('en.yusufali', 10, 109, 'Follow thou the inspiration sent unto thee, and be patient and constant, till Allah do decide: for He is the best to decide.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 10, 1, 'Alif-Laaam-Raa; tilka Aayaatul Kitaabil Hakeem'),
  ('en.transliteration', 10, 2, 'A kaana linnaasi \'aaban an awhainaaa ilaa rajulim minhum an anzirin naasa wa bashshiril lazeena aamanoo anna lahum qadama sidqin \'inda Rabbihim; qaalal kaafiroona inna haaza lasaahirum mubeen'),
  ('en.transliteration', 10, 3, 'Inna Rabbakumul laahul lazee khalaqas samaawaati wal arda fee sittati aiyaamin summas tawaa \'alal \'Arshi yudabbirul amra maa min shafee\'in illaa mim ba\'di iznih; zalikumul laahu Rabbukum fa\'budooh; afalaa tazakkaroon'),
  ('en.transliteration', 10, 4, 'Ilaihi marji\'ukum jamee \'anw wa\'dal laahi haqqaa; innahoo yabda\'ul khalqa summa yu\'eeduhoo liyajziyal lazeena aamanoo wa \'amilus saalihaati bilqist; wallazeena kafaroo lahum sharaabum min hamee minw wa \'azaabun aleemum bimaa kaanoo yakfuroon'),
  ('en.transliteration', 10, 5, 'Huwal lazee ja\'alash shamsa diyaaa\'anw walqamara nooranw wa qaddarahoo manaaz zila lita\'lamoo \'adadas sineena walhisaab; maa khalaqal laahu zaalika illa bilhaqq; yufassilul aayaati liqawminw ya\'lamoon'),
  ('en.transliteration', 10, 6, 'Inna fikh tilaafil laili wannahaari wa maa khalaqal laahu fis samaawaati wal ardi la Aayaatil liqawminy yattaqoon'),
  ('en.transliteration', 10, 7, 'Innal lazeena laa yarjoona liqaaa\'anaa wa radoo bilhayaatid dunyaa watma annoo bihaa wallazeena hum \'an Aayaatinaa ghaafiloon'),
  ('en.transliteration', 10, 8, 'Ulaaa\'ika maawaahumun Naaru bimaa kaanoo yaksiboon'),
  ('en.transliteration', 10, 9, 'Innal lazeena aamanoo wa \'amilus saalihaati yahdeehim Rabbuhum bi eemaanihim tajree min tahtihimul anhaaru fee jannaatin Na\'eem'),
  ('en.transliteration', 10, 10, 'Da\'waahum feehaa Subbaanakal laahumma wa tahiyyatuhum feehaa salaam; wa aakhiru da\'waahum anil hamdu lillaahi Rabbil \'aalameen'),
  ('en.transliteration', 10, 11, 'Wa law yu\'aijilul laahu linnaasish sharras ti\'jaalahum bilkhairi laqudiya ilaihim ajaluhum fanazarul lazeena laa yarjoona liqaaa\'anna fee tughyaanihim ya\'mahoon'),
  ('en.transliteration', 10, 12, 'Wa izaa massal insaanad durru da\'aanaa lijambiheee aw qaa\'idan aw qaaa\'iman falammaa kashafnaa \'anhu durrahoo marra ka al lam yad\'unaaa ilaa durrim massah; kazaalika zuyyina lilmusrifeena maa kaanoo ya\'maloon'),
  ('en.transliteration', 10, 13, 'Wa laqad ahlaknal quroona min qablikum lammaa zalamoo wa jaaa\'at hum Rusuluhum bil baiyinaati wa maa kaanoo liyu\'minoo; kazaalika najzil qawmal mujrimeen'),
  ('en.transliteration', 10, 14, 'Summa ja\'alnaakum khalaaa\'ifa fil ardi mim ba\'dihim linanzura kaifa ta\'maloon'),
  ('en.transliteration', 10, 15, 'Wa izaa tutlaa \'alaihim aayaatunaa baiyinaatin qaalal lazeena laa yarjoona liqaaa\'ana\'ti bi Quraanin ghairi haazaaa aw baddilh; qul maa yakoonu leee an ubaddilahoo min tilqaaa\'i nafsee in attabi\'u illaa maa yoohaaa ilaiya inneee akhaafu in \'asaytu Rabbee \'azaaba Yawmin \'Azeeem'),
  ('en.transliteration', 10, 16, 'Qul law shaaa\'al laahu maa talawtuhoo \'alaikum wa laaa adraakum bihee faqad labistu feekum \'umuram min qablih; afalaa ta\'qiloon'),
  ('en.transliteration', 10, 17, 'Faman azlamu mimmanif taraa \'alal laahi kaziban aw kazzaba bi Aayaatih; innahoo laa yuflihul mujrimoon'),
  ('en.transliteration', 10, 18, 'Wa ya\'budoona min doonil laahi maa laa yadurruhum wa laa yanfa\'uhum wa yaqooloona haaa\'ulaaa\'i shufa\'aaa \'unaa \'indal laah; qul atunabbi \'oonal laaha bima laa ya\'lamu fis samaawaati wa laa fil ard; subhaanahoo wa Ta\'aalaa \'ammaa yushrikoon'),
  ('en.transliteration', 10, 19, 'Wa maa kaanan naasu illaaa ummmatanw waahidatan fakh talafoo; wa law laa kalimatun sabaqat mir Rabbika laqudiya bainahum fee maa feehi yakhtalifoon'),
  ('en.transliteration', 10, 20, 'W yaqooloona law laaa unzila \'alaihi aayatum mir Rabbihee faqul innamal ghaibu lillaahi fantaziroo innee ma\'akum minal muntazireen'),
  ('en.transliteration', 10, 21, 'Wa izaaa azaqnan naasa rahmatam mim ba\'di darraaa\'a massat hum izaa lahum makrun feee aayaatinaa; qulil laahu asra\'u makraa; inna rusulanaa yaktuboona maa tamkuroon'),
  ('en.transliteration', 10, 22, 'Huwal lazee yusaiyirukum fil barri walbahri hattaaa izaa kuntum fil fulki wa jaraina bihim bireeh in taiyibatinw wa farihoo bihaa jaaa\'at haa reehun \'aasifunw wa jaaa\'ahumul mawju min kulli makaaninw wa zannooo annahum uheeta bihim da\'awul laaha mukhliseena lahud deena la\'in anjaitanaa min haazihee lanakoonannna minash shaakireen'),
  ('en.transliteration', 10, 23, 'Falammaaa anjaahum izaa hum yabghoona fil ardi bighairil haqq; yaaa aiyuhannaasu innamaa bagh yukum \'alaaa anfusikum mataa\'al hayaatid dunyaa summa ilainaa marji\'ukum fanunabbi \'ukum bimaa kuntum ta\'maloon'),
  ('en.transliteration', 10, 24, 'Innamaa masalul hayaatid dunyaa kammaaa\'in anzalnaahu minas sammaaa\'i fakhtalata bihee nabaatul ardi mimmaa yaakulun naasu wal an\'aam; hattaaa izaaa akhazatil ardu zukhrufahaa wazziyanat wa zanna ahluhaaa annahum qaadiroona \'alaihaaa ataahaaa amrunaa lailan aw nahaaran faja\'alnaahaa haseedan ka allam taghna bil-ams; kazaalika nufassilul aayaati liqawminy yatafakkaroon'),
  ('en.transliteration', 10, 25, 'Wallaahu yad\'ooo ilaa daaris salaami wa yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 10, 26, 'Lillazeena ahsanul husnaa wa ziyaadahtunw wa laa yarhaqu wujoohahum qatarunw wa laa zillah; ulaaa\'ika ashaabul jannnati hum feehaa khaalidoon'),
  ('en.transliteration', 10, 27, 'Wallazeena kasabus saiyi aati jazaaa\'u saiyi\'atim bimislihaa wa tarhaquhum zillah; maa lahum minal laahi min \'aasimin ka annamaaa ughshiyat wujoohuhum qita \'am minal laili muzlimaa; ulaaa\'ika Ashaabun Naari hum feeha khaalidoon'),
  ('en.transliteration', 10, 28, 'Wa yawma nahshuruhum jamee\'an summa naqoolu lillazeena ashrakoo makaanakum antum wa shurakaaa\'ukum; fazaiyalnaa bainahum wa qaala shurakaaa\'uhum maa kuntum iyyaanaa ta\'budoon'),
  ('en.transliteration', 10, 29, 'Fakafaa billaahi shaheedam bainanaa wa bainakum in kunnaa \'an \'ibaadatikum laghaafileen'),
  ('en.transliteration', 10, 30, 'Hunaalika tabloo kullu nafsim maaa aslafat; wa ruddoo ilal laahi mawlaahu mul haqqi wa dalla \'anhum maa kaanoo yaftaroon'),
  ('en.transliteration', 10, 31, 'Qul mai yarzuqukum minas samaaa\'i wal ardi ammany yamlikus sam\'a wal absaara wa mai yukhrijul haiya minal maiyiti wa yikhrijul maiyita minal haiyi wa mai yudabbirul amr; fasa yaqooloonal laah; faqul afalaa tattaqoon'),
  ('en.transliteration', 10, 32, 'Fazaalikumul laahu Rabbukumul haqq; famaazaa ba\'dal haqqi illad dalaalu fa annnaa tusrafoon'),
  ('en.transliteration', 10, 33, 'Kazaalika haqqat Kalimatu Rabbika \'alal lazeena fasaqooo annahum laa yu\'minoon'),
  ('en.transliteration', 10, 34, 'Qul hal min shurakaaa \'ikum mai yabda\'ul khalqa suma yu\'eeduh; qulil laahu yabda\'ul khalqa summa yu\'eeduhoo fa annaa tu\'fakoon'),
  ('en.transliteration', 10, 35, 'Qul hal min shurakaaa \'ikum mai yahdeee ilal haqq; qulil laahu yahdee lilhaqq; afamai yahdeee ilal haqqi ahaqqu ai yuttaba\'a ammal laa yahiddeee illaaa ai yuhdaa famaa lakum kaifa tahkumoon'),
  ('en.transliteration', 10, 36, 'Wa maa yattabi\'u aksaruhum illaa zannaa; innaz zanna laa yughnee minal haqqi shai\'aa; innal laaha \'Aleemum bimaa yaf\'aloon'),
  ('en.transliteration', 10, 37, 'Wa maa kaana haazal Quraanu ai yuftaraa min doonil laahi wa laakin tasdeeqal lazee baina yadaihi wa tafseelal Kitaabi laa raiba fee mir Rabbil \'aalameen'),
  ('en.transliteration', 10, 38, 'Am yaqooloonaf taraahu qul faatoo bisooratim mislihee wad\'oo manis tata\'tum min doonil laahi in kuntum saadiqeen'),
  ('en.transliteration', 10, 39, 'Bal kazzaboo bimaa lam yuheetoo bi\'ilmihee wa lammaa yaatihim taaweeluh; kazaalika kazzabal lazeena min qablihim fanzur kaifa kaana \'aaqibatuz zaalimeen'),
  ('en.transliteration', 10, 40, 'Wa minhum mai yu \'minu bihee wa minhum mal laa yu\'minu bih; wa Rabbuka a\'lamu bilmufsideen'),
  ('en.transliteration', 10, 41, 'Wa in kazzabooka faqul lee \'amalee wa lakum \'amalukum antum bareee\'oona mimmaaa a\'malu wa ana bareee\'um mimmaa ta\'maloon'),
  ('en.transliteration', 10, 42, 'Wa minhum mai yastami\'oona iliak; afa anta tusmi\'us summa wa law kaanoo la ya\'qiloon'),
  ('en.transliteration', 10, 43, 'Wa minhum mai yanzuru ilaik; afa anta tahdil \'umya wa law kaanoo laa yubsiroon'),
  ('en.transliteration', 10, 44, 'Innal laaha laa yazlimun naasa shai\'anw wa laakin nannaasa anfusahum yazlimoon'),
  ('en.transliteration', 10, 45, 'Wa Yawma yahshuruhum ka al lam yalbasooo illaa saa\'atam minan nahaari yata\'aarafoona bainahum; qad khasiral lazeena kazzaboo biliqaaa\'il laahi wa maa kaanoo muhtadeen'),
  ('en.transliteration', 10, 46, 'Wa imma nuriyannaka ba\'dal lazee na\'iduhum aw natawaffayannaka fa ilainaa marji\'uhum summal laahu shaheedun \'alaa maa yaf\'aloon'),
  ('en.transliteration', 10, 47, 'Wa likulli ummatir Rasoolun fa izaa jaaa\'a Rasooluhum qudiya bainahum bilqisti wa hum laa yuzlamoon'),
  ('en.transliteration', 10, 48, 'Wa yaqooloona mataa haazal wa\'du in kuntum saadiqeen'),
  ('en.transliteration', 10, 49, 'Qul laaa amliku linafsee darranw wa laa naf\'an illaa maa shaaa\'al laah; likulli ummatin ajalun izaa jaaa\'a ajaluhum falaaa yastaakhiroona saa\'a tanw wa laa yastaqdimoon'),
  ('en.transliteration', 10, 50, 'Qul ara\'aitum in ataakum \'azaabuhoo bayaatan aw nahaaram maazaa yasta\'jilu minhul mujrimoon'),
  ('en.transliteration', 10, 51, 'Asumma izaa maa waqa\'a aamantum bih; aaal\'aana wa qad kuntum bihee tasta\'jiloon'),
  ('en.transliteration', 10, 52, 'Summa qeela lillazeena zalamoo zooqoo \'azaabal khuld hal tujzawna illaa bimaa kuntum taksiboon'),
  ('en.transliteration', 10, 53, 'Wa yastambi\'oonaka ahaqqun huwa qul ee wa Rabbeee innahoo lahaqq; wa maaa antum bimu\'jizeen'),
  ('en.transliteration', 10, 54, 'Wa law anna likulli nafsin zalamat maa fil ardi laftadat bih; wa asarrun nadaamata lammaa ra awul \'azaab, wa qudiya bainahum bilqist; wa hum laa yuzlamoon'),
  ('en.transliteration', 10, 55, 'Alaaa inna lillaahi maa fis samaawaati wal ard; alaaa inna wa\'dal laahi haqqunw wa laakinna aksarahum laa ya\'lamoon'),
  ('en.transliteration', 10, 56, 'Huwa yuhyee wa yumeetu wailaihi turja\'oon'),
  ('en.transliteration', 10, 57, 'Yaaa aiyuhan naasu qad jaaa\'atkum maw \'izatum mir Rabbikum wa shifaaa\'ul limaa fis sudoori wa hudanw wa rahmatul lilmu\'mineen'),
  ('en.transliteration', 10, 58, 'Qul bifadlil laahi wa birahmatihii fabizaalika falyaf rahoo huwa khairum mimmaa yajma\'oon'),
  ('en.transliteration', 10, 59, 'Qul ara\'aitum maaa anzalal laahu lakum mir rizqin faja\'altum minhu haraamanw wa halaalan qul aaallaahu azina lakum am \'alal laahi taftaroon'),
  ('en.transliteration', 10, 60, 'Wa maa zannul lazeena yaftaroona \'alal laahil kaziba Yawmal Qiyaamah; innal laaha lazoo fadlin \'alan naasi wa laakinna aksarahum laa yashkuroon'),
  ('en.transliteration', 10, 61, 'Wa maa takoonu fee shaaninw wa maa tatloo minhu min quraaninw wa laa ta\'maloona min \'amalin illaa kunnaa \'alaikum shuhoodan iz tufeedoona feeh; wa maa ya\'zubu \'ar Rabbika mim mis qaali zarratin fil ardi wa laa fis samaaa\'i wa laaa asghara min zaalika wa laaa akbara illaa fee Kitaabim Mubeen'),
  ('en.transliteration', 10, 62, 'Alaa innaa awliyaaa\'al laahi laa khawfun \'alaihim wa laa hum yahzanoon'),
  ('en.transliteration', 10, 63, 'Allazeena aamanoo wa kaanoo yattaqoon'),
  ('en.transliteration', 10, 64, 'Lahumul bushraa filha yaatid dunyaa wa fil Aakhirah; laa tabdeela likalimaatil laah; zaalika huwal fawzul \'azeem'),
  ('en.transliteration', 10, 65, 'Wa laa yahzunka qawluhum; innal \'izzata lillaahi jamee\'aa; Huwas Samee\'ul \'Aleem'),
  ('en.transliteration', 10, 66, 'Alaaa inna lillaahi man fis samaawaati wa man fil ard; wa maa yattabi\'ul lazeena yad\'oona min doonil laahi shurakaaa\'; iny yattabi\'oona illaz zannna wa in hum illaa yakhrusoon'),
  ('en.transliteration', 10, 67, 'Huwal lazee ja\'ala lakumul laila litaskunoo feehi wannahaara mubsiraa; inna fee zaalika la Aayaatil liqawmai yasma\'oon'),
  ('en.transliteration', 10, 68, 'Qaalut takhazal laahu waladan Subhaanahoo Huwal Ghaniyyu lahoo maa fis samaawaati wa maa fil ard; in \'indakum min sultaanim bihaazaaa; ataqooloona \'alal laahi maa laa ta\'lamoon'),
  ('en.transliteration', 10, 69, 'Qul innal lazeena yaftaroona \'alal laahil kaziba laa yuflihoon'),
  ('en.transliteration', 10, 70, 'Mataa\'un fiddunyaa summa ilainaa marji\'uhum summa nuzeequhumul \'azaabash shadeeda bimaa kaanoo yakkfuroon'),
  ('en.transliteration', 10, 71, 'Watlu \'alaihim naba-a-Noohin iz qaala liqawmihee yaa qawmi in kaana kabura \'alaikum maqaamee wa tazkeeree bi Aayaatil laahi fa\'alal laahi tawakkaltu fa ajmi\'ooo amrakum wa shurakaaa\'akum summa laa yakun amrukum \'alaikum ghummatan summmaq dooo ilaiya wa laa tunziroon'),
  ('en.transliteration', 10, 72, 'Fa in tawallaitum famaa sa altukum min ajrin in ajriya illaa \'alal laahi wa umirtu an akoona minal muslimeen'),
  ('en.transliteration', 10, 73, 'Fakazzaboohu fanajjainaahu wa mamm\'ahoo fil fulki wa ja\'alnaahum khalaaa\'ifa wa aghraqnal lazeena kazzaboo bi aayaatinaa fanzur kaifa kaana \'aaqibatul munzareen'),
  ('en.transliteration', 10, 74, 'Summma ba\'asnaa mim ba\'dihee Rusulan ilaa qawmihim fajaaa\'oohum bilbaiyinaati famaa kaanoo liyu\'minoo bimaa kazzaboo bihee min qabl; kazaalika natba\'u \'alaa quloobil mu\'tadeen'),
  ('en.transliteration', 10, 75, 'Summa ba\'asnaa mim ba\'dihim Moosaa Wa Haaroona ilaa Fir\'awna wa mala\'ihee bi aayaatinaa fastakbaroo wa kaanoo qawmam mujrimeen'),
  ('en.transliteration', 10, 76, 'Falammaa jaaa\'ahumul haqqu min \'indinaa qaalooo inna haazaa lasihrum mubeen'),
  ('en.transliteration', 10, 77, 'Qaalaa Moosaaa ataqooloona lilhaqqi lammmaa jaaa\'a kum asihrun haazaa wa laa yuflihus saabiroon'),
  ('en.transliteration', 10, 78, 'Qaaloo aji\'tanaa litalfitanaa \'ammaa wajadnaa \'alaihi aabaaa\'anaa wa takoona lakumal kibriyaaa\'u fil ardi wa maa nahnu lakumaa bimu\' mineen'),
  ('en.transliteration', 10, 79, 'Wa qaala Fir\'awnu\' toonee bikulli saahirin \'aleem'),
  ('en.transliteration', 10, 80, 'Falammaa jaaa\'assa haratu qaala lahum Moosaaa alqoo maaa antum mulqoon'),
  ('en.transliteration', 10, 81, 'Falammaaa alqaw qaala Moosaa maa ji\'tum bihis sihru innal laaha sa yubtiluhoo innal laaha laa yuslihu \'amalal mufsideen'),
  ('en.transliteration', 10, 82, 'Wa yuhiqqul laahul haqqa bi Kalimaatihee wa law karihal mujrimoon'),
  ('en.transliteration', 10, 83, 'Famaaa aamana li-Moosaaa illaa zurriyyatum min qawmihee \'alaa khawfim min Fir\'awna wa mala\'ihim ai yaftinahum; wa inna Fir\'awna la\'aalin fil ardi wa innahoo laminal musrifeen'),
  ('en.transliteration', 10, 84, 'Wa qaala Moosaa yaa qawmi in kuntum aamantum billaahi fa\'alaihi tawakkalooo in kuntum muslimeen'),
  ('en.transliteration', 10, 85, 'Faqaaloo \'alal laahi tawakkalnaa Rabbanaa laa taj\'alnaa fitnatal lilqawmiz zaalimeen'),
  ('en.transliteration', 10, 86, 'Wa najjinaa birahmatika minal qawmil kaafireen'),
  ('en.transliteration', 10, 87, 'Wa awhainaaa ilaa Moosaa wa akheehi an tabaw wa aa liqawmikuma bi Misra bu yootanw waj\'aloo bu yootakum qiblatanw wa aqeemus Salaah; wa bashshiril mu\'mineen'),
  ('en.transliteration', 10, 88, 'Wa qaala Mosaa Rabbanaaa innaka aataita Fir\'awna wa mala ahoo zeenatanw wa amwaalan fil hayaatid dunyaa Rabbanaa liyudillo \'ansabeelika Rabbanat mis \'alaaa amwaalihim washdud \'alaa quloobihim falaa yu\'minoo hatta yarawul \'azaabal aleem'),
  ('en.transliteration', 10, 89, 'Qaala qad ujeebad da\'watukumaa fastaqeemaa wa laa tattabi\'aaanni sabeelal lazeena laaya\'lamoon'),
  ('en.transliteration', 10, 90, 'Wa jaawaznaa bi Baneee Israaa\'eelal bahra fa atba\'ahum Fir\'awnu wa junooduhoo baghyanw wa \'adwan hattaaa izaaa adrakahul gharaqu qaala aamantu annnahoo laaa ilaaha illal lazeee aamanat bihee Banooo Israaa\'eela wa ana minal muslimeen'),
  ('en.transliteration', 10, 91, 'Aaal\'aana wa qad \'asaita qablu wa kunta minal mufsideen'),
  ('en.transliteration', 10, 92, 'Falyawma nunajjeeka bibadanika litakoona liman khalfaka Aayah; wa inna kaseeram minan naasi \'an aayaatinaa laghaafiloon'),
  ('en.transliteration', 10, 93, 'Wa laqad bawwaanaa Baneee Israaa\'eela mubawwa-a sidqinw wa razaqnaahum minnat taiyibaati famakh talafoo hattaa jaaa\'ahmul \'ilm; inna Rabbaka yaqdee bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon'),
  ('en.transliteration', 10, 94, 'Fa in kunta fee shakkim mimmaaa anzalnaaa ilaika fas\'alil lazeena yaqra\'oonal Kitaaba min qablik; laqad jaaa\'akal haqqu mir Rabbika falaa takoonanna minal mumtareen'),
  ('en.transliteration', 10, 95, 'Wa laa takoonanna minal lazeena kazzaboo bi Aayaatil laahi fatakoona minal khaasireen'),
  ('en.transliteration', 10, 96, 'Innal lazeena haqqat \'alaihim Kalimatu Rabbika laa yu\'minoon'),
  ('en.transliteration', 10, 97, 'Wa law jaaa\'at hum kullu Aayatin hattaa yarawul \'azaabal aleem'),
  ('en.transliteration', 10, 98, 'Falaw laa kaanat qaryatun aamanat fanafa\'ahaaa eemaanuhaaa illaa qawma Yoonusa lammaaa aamanoo kashafnaa \'anhum \'azaabal khizyi fil hayaatid dunyaa wa matta\'naahum ilaa heen'),
  ('en.transliteration', 10, 99, 'Wa law shaaa\'a Rabbuka la aamana man fil ardi kulluhum jamee\'aa; afa anta tukrihun naasa hattaa yakoonoo mu\'mineen'),
  ('en.transliteration', 10, 100, 'Wa maa kaana linafsin an tu\'mina illaa bi iznil laah; wa yaj\'alur rijsa \'alal lazeena laa ya\'qiloon'),
  ('en.transliteration', 10, 101, 'Qulin zuroo maazaa fissamaawaati wal ard; wa maa tughnil Aayaatu wannuzuru \'an qawmil laa yu\'minoon'),
  ('en.transliteration', 10, 102, 'Fahal yantaziroona illaa misla ayyaamil lazeena khalaw min qablihim; qul fantazirooo innee ma\'akum minal muntazireen'),
  ('en.transliteration', 10, 103, 'Summma nunajjee Ruslanaa wallazeena aamanoo; kazaalika haqqan \'alainaa nunjil mu\'mineen'),
  ('en.transliteration', 10, 104, 'Qul yaaa ayyuhan naasu in kuntum fee shakkkim min deenee falaa a\'budul lazeena ta\'budoona min doonil laahi wa laakin a\'budul laahal lazee yatawaffaakum wa umirtu an akoona minal mu\'mineen'),
  ('en.transliteration', 10, 105, 'Wa an aqim wajhaka liddeeni Haneefanw wa laa takoonannna minal mushrikeen'),
  ('en.transliteration', 10, 106, 'Wa laa tad\'u min doonil laahi maa laa yanfa\'uka wa laa yadurruka fa in fa\'alta fa innaka izam minaz zaalimeen'),
  ('en.transliteration', 10, 107, 'Wa iny yamsaskal laahu bidurrin falaa kaashifa lahoo illaa Huwa wa iny yuridka bikhairin falaa raaadda lifadlih; yuseebu bihee man yashaaa\'u min \'ibaadih; wa huwal Ghafoorur Raheem'),
  ('en.transliteration', 10, 108, 'Qul yaaa aiyuhan naasu qad jaaa\'akumul haqqu mir Rabbikum famanih tadaa fa innamaa yahtadee linafsihee wa man dalla fa innamaa yadillu \'alaihaa wa maaa ana \'alaikum biwakeel'),
  ('en.transliteration', 10, 109, 'Qattabi\' maa yoohaaa ilaika wasbir hattaa yahkumal laah; wa Huwa khairul haakimeen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 10, 1, 'یہ حکمت والی کتا ب کی آیتیں ہیں'),
  ('ur.ahmedali', 10, 2, 'کیا اس بات سے لوگوں کو تعجب ہوا کہ ہم نے ان میں سے ایک شخص کے پاس وحی بھیج دی کہ سب آدمیوں کو ڈرائے اور جو ایمان لائیں انہیں یہ خوشخبری سنائے کہ انہیں اپنے رب کے ہاں پہنچ کر پورا مرتبہ ملے گا کافر کہتے ہیں کہ یہ شخص صریح جادوگر ہے'),
  ('ur.ahmedali', 10, 3, 'بے شک تمہارا رب الله ہی ہے جس نے آسمان اور زمین چھ دن میں بنائے پھر عرش پر قائم ہوا وہی ہر کام کا انتظام کرتا ہے اس کی اجازت کے سوا کوئی سفارش کرنے والا نہیں ہے یہی الله تمہارا پروردگار ہے سو اسی کی عبادت کرو کیا تم پھر بھی نہیں سمجھتے'),
  ('ur.ahmedali', 10, 4, 'تم سب کو اسی کی طرف لوٹ کر جانا ہے الله کا وعدہ سچا ہے وہی پہلی مرتبہ پیدا کرتا ہے پھر وہی دوبارہ پیدا کرے گا تاکہ جو لوگ ایمان لائے اورنیک کام کیے انہیں انصاف کے ساتھ بدلہ دے اور جن لوگو ں نے کفر کیا ان کے واسطے کھولتا ہوا پانی پینے کو ہوگا اوران کے کفر کے سبب سے دردناک عذاب ہوگا'),
  ('ur.ahmedali', 10, 5, 'وہی ہے جس نے سورج کو روشن بنایا اور چاند کو منور فرمایا اور چاند کی منزلیں مقرر کیں تاکہ تم برسوں کا شمار اور حساب معلوم کر سکو یہ سب کچھ الله نے تدبیر سے پیدا کیا ہے وہ اپنی آیتیں سمجھداروں کے لیے کھول کھول کر بیان فرماتا ہے'),
  ('ur.ahmedali', 10, 6, 'رات اور دن کے آنے جانے میں اور جو چیزیں الله نے آسمانوں اور زمین میں پیدا کی ہیں ان میں ان لوگو ں کے لیے نشانیاں ہیں جو ڈرتے ہیں'),
  ('ur.ahmedali', 10, 7, 'البتہ جو لوگ ہم سے ملنے کی امید نہیں رکھتے اور دنیاکی زندگی پر خوش ہوئے اور اسی پر مطمئن ہو گئے اور جو لوگ ہماری نشانیوں سے غافل ہیں'),
  ('ur.ahmedali', 10, 8, 'ان کا ٹھکانا آگ ہے بسبب اس کے جو کرتے تھے'),
  ('ur.ahmedali', 10, 9, 'بے شک جو لوگ ایمان لائے اورانہوں نے نیک کام کیے انہیں ان کا رب ان کے ایمان کے سبب ہدایت کرے گا ان کے نیچے نعمت کے باغوں میں نہریں بہتی ہوں گی'),
  ('ur.ahmedali', 10, 10, 'اس جگہ ان کی دعا یہ ہو گی کہ اے الله تیری ذات پاک ہے اوروہاں ان کا باہمی تحفہ سلام ہوگا اور ان کی دعا کا خاتمہ اس پر ہوگا سب تعریف الله کے لیے ہے جو سارے جہان کا پالنے والا ہے'),
  ('ur.ahmedali', 10, 11, 'اور اگر الله لوگوں کو برائی جلد پہنچا دے جس طرح وہ بھلائی جلدی مانگتے ہیں تو ان کی عمر ختم کر دی جائے سو ہم چھوڑے رکھتے ہیں ان لوگوں کو جنہیں ہماری ملاقات کی امید نہیں کہ اپنی سرکشی میں بھٹکتے رہیں'),
  ('ur.ahmedali', 10, 12, 'اورجب انسان کو تکلیف پہنچتی ہے تو لیٹے اور بیٹھے اورکھڑے ہونے کی حالت میں ہمیں پکارتا ہے پھر جب ہم اس سے اس تکلیف کودور کر دیتے ہیں تو اس طرح گزر جاتا ہے گویا کہ ہمیں کسی تکلیف پہنچنے پر پکارا ہی نہ تھا اس طرح بیباکوں کو پسند آیا ہے جو کچھ وہ کر رہے ہیں'),
  ('ur.ahmedali', 10, 13, 'اور البتہ ہم تم سے پہلے کئی امتوں کو ہلاک کر چکے ہیں جب انہوں نے ظلم اختیار کیا حالانکہ پیغمبر ان کے پاس کھلی نشانیاں لائے تھے اور وہ ہر گز ایمان لانے والے نہ تھے ہم گناہگارو ں کو ایسی ہی سزا دیا کرتے ہیں'),
  ('ur.ahmedali', 10, 14, 'پھر ہم نے تمہیں ان کے بعد زمین میں نائب بنایا تاکہ دیکھیں تم کیا کرتے ہو'),
  ('ur.ahmedali', 10, 15, 'اور جب ان کے سامنے ہماری واضح آیتیں پڑھی جاتی ہیں وہ لوگ کہتے ہیں جنہیں ہم سے ملاقات کی امید نہیں کہ اس کے سوا کوئی قرآن لے آ یا اسے بدل دے تو کہہ دے میرا کام نہیں کہ اپنی طرف سے اسے بدل دوں میں اس کی تابعداری کرتا ہوں جو میری طرف وحی کی جائے اگر میں اپنے رب کی نافرمانی کروں توبڑے دن کے عذاب سے ڈرتا ہوں'),
  ('ur.ahmedali', 10, 16, 'کہہ دو اگر الله چاہتا تو میں اسے تمہارےسامنے نہ پڑھتا اورنہ وہی تمہیں اس سے خبردار کرتا کیوں کہ اس سے پہلے تم میں ایک عمر گذار چکا ہوں کیا پھر تم نہیں سمجھتے'),
  ('ur.ahmedali', 10, 17, 'پھر اس سے بڑا ظالم کون ہو گا جو الله پر بہتان باندھے یا اس کی آیتوں کو جھٹلائے بے شک گناہگاروں کابھلا نہیں ہوتا'),
  ('ur.ahmedali', 10, 18, 'اور الله کے سوا اس چیز کی پرستش کرتے ہیں جونہ انہیں نقصان پہنچا سکے اورنہ انہیں نفع دے سکے اور کہتے ہیں الله کے ہاں یہ ہمارے سفارشی ہیں کہہ دو کیا تم الله کو بتلاتے ہو جو اسے آسمانوں اور زمین میں معلوم نہیں وہ پاک ہے اوران لوگو ں کے شرک سے بلند ہے'),
  ('ur.ahmedali', 10, 19, 'اوروہ لوگ ایک ہی امت تھے پھر جدا جدا ہو گئے اور اگر ایک بات تمہارے پرودگار کی طرف سے پہلے نہ ہو چکی ہو تی تو جن باتوں میں وہ اختلاف کر تے ہیں ان میں فیصلہ کر دیا جاتا ہے'),
  ('ur.ahmedali', 10, 20, 'اور کہتے ہیں اس پر اس کے رب سے کوئی نشانی کیوں نہ اتری سو تو کہہ دے کہ غیب کی بات الله ہی جانتا ہے سو تم انتظار کرو میں بھی تمہارے ساتھ انتظار کرتا ہوں'),
  ('ur.ahmedali', 10, 21, 'اورجب ہم لوگوں کو اپنی رحمت کا مزہ چکھاتے ہیں اس تکلیف کے بعد جو انہیں پہنچی تھی تو وہ ہماری آیتو ں کے متعلق حیلے کرنے لگتے ہیں کہہ دو کہ الله بہت جلد حیلہ کرنے والا ہے بے شک ہمارے فرشتے تمہارے سب حیلو ں کو لکھ رہے ہیں'),
  ('ur.ahmedali', 10, 22, 'وہ وہی ہے جو تمہیں جنگل اور دریا میں سیر کرنے کی توفیق دیتا ہے یہاں تک کہ جب تم کشتیوں میں بیٹھتے ہو اور وہ کشتیاں لوگو ں کو موافق ہوا کے ذریعہ سے لے کرچلتی ہیں اور وہ لوگ ان سے خوش ہوتے ہیں تو ناگہاں تیز ہوا چلتی ہے اور ہر طرف سے ان پر لہریں چھانے لگتی ہیں اور و ہ خیال کرتے ہیں کہ بےشک وہ لہروں میں گھر گئے ہیں تو سب خالص اعتقاد سے الله ہی کو پکارنے لگتے ہیں کہ اگر تو ہمیں اس مصیبت سے بچادے تو ہم ضرور شکر گزار رہیں گے'),
  ('ur.ahmedali', 10, 23, 'پھر جب الله انہیں نجات دے دیتا ہے تو ملک میں ناحق شرارت کرنے لگتے ہیں اے لوگو تمہاری شرارت کا وبال تمہاری جانو ں پر ہی پڑے گا دنیا کی زندگی کا نفع اٹھا لو پھر ہمارے ہاں ہی تمہیں لوٹ کر آناہے پھر ہم تمہیں بتلادیں گے جو کچھ تم کیا کرتے تھے'),
  ('ur.ahmedali', 10, 24, 'دنیا کی زندگی کی مثال مینہ کی سی ہے کہ اسے ہم نے آسمان سے اتارا پھراس کے ساتھ سبزہ مل کر نکلا جسے آدمی اور جانور کھاتے ہیں یہاں تک کہ جب زمین سبزے سے خوبصورت اور آراستہ ہو گئی اورزمین والوں نے خیال کیا کہ وہ اس پر بالکل قابض ہو چکے ہیں تو اس پر ہماری طرف سے دن یا رات میں کوئی حادثہ آ پڑا سو ہم نے اسے ایسا صاف کر دیا کہ گویا کل وہا ں کچھ بھی نہ تھا اس طرح ہم نشانیوں کو کھول کر بیان کرتے ہیں اور لوگو ں کے سامنے جو غور کرتے ہیں'),
  ('ur.ahmedali', 10, 25, 'اور الله سلامتی کے گھر کی طرف بلاتا ہے اور جسے چاہے سیدھا راستہ دکھاتا ہے'),
  ('ur.ahmedali', 10, 26, 'جنہوں نے بھلائی کی ان کے لئے بھلائی ہے اور زیادتی بھی اور ان کے منہ پر سیاہی اور رسوائی نہیں چڑھے گی وہ بہشتی ہیں وہ اسی میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 10, 27, 'اور جنہوں نے برے کام کئے تو برائی کا بدلہ ویسا ہی ہوگا کہ ان پر ذلت چھائے گی اور انہیں اللہ سے بچانے والا کوئی نہ ہوگا گویا کہ ان کے مونہوں پر اندھیری رات کے ٹکڑے اوڑدئے گئے ہیں یہی دوزخی ہیں وہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 10, 28, 'اور جس دن ہم ان سب کو جمع کرینگے پھر مشرکوں سے کہیں گے تم اور تمہارے شریک اپنی جگہ کھڑے رہو تو ہم ان میں پھوٹ ڈال دینگے اور ان کے شریک کہیں گے کہ تم ہماری عبادت نہیں کرتے تھے'),
  ('ur.ahmedali', 10, 29, 'سو اللہ ہمارے اور تمہارے درمیان گواہ کافی ہے کہ ہمیں تمہاری عبادت کی خبر ہی نہ تھی'),
  ('ur.ahmedali', 10, 30, 'اس جگہ ہر شخص اپنے پہلے کئے ہوئے کاموں کو جانچ لے گا اور یہ لوگ اللہ کی طرف لوٹائے جائینگے جو ان کا حقیقی مالک ہے اور جو جھوٹ وہ باندھا کرتے تھے ان سے جاتا رہے گا'),
  ('ur.ahmedali', 10, 31, 'کہو تمہیں آسمان اور زمین سے کون روزی دیتا ہے یا کانوں اور آنکھوں کا کون مالک ہے اور زندہ کو مردہ سے کون نکلتا ہے اور مردہ کو زندہ سے کون نکلتا ہے اور سب کاموں کا کون انتظام کرتا ہے سو کہیں گے کہ اللہ تو کہہ دو کہ پھر (اللہ) سے کیوں نہیں ڈرتے'),
  ('ur.ahmedali', 10, 32, 'یہی الله تمہارا سچا رب ہے حق کے بعد گمراہی کے سوا اور ہے کیا سوتم کدھر پھرے جاتے ہو'),
  ('ur.ahmedali', 10, 33, 'اسی طرح ان نافرمانوں کے حق میں تیرے رب کا فیصلہ ثابت ہو کر رہا کہ یہ ایمان نہیں لائیں گے'),
  ('ur.ahmedali', 10, 34, 'کہہ دو آیا تمہارے شریکوں میں کوئی ایسا ہے جو مخلوقات کو پیدا کرے پھر اسے دوبارہ زندہ کرے کہہ دو الله پہلے پیدا کرتا ہے پھر اسے لوٹائے گا سو تم کہاں پھیرے جاتے ہو'),
  ('ur.ahmedali', 10, 35, 'کہہ دو آیا تمہارے شریکوں میں کوئی ہے جو صحیح راہ بتلائے کہہ دو الله ہی صحیح راہ بتلاتا ہے تو جو اب صحیح راستہ بتلائے اسکی بات ماننی چاہیئے یا اس کی جو خود راہ نہ پائے مگر جب کوئی اوراسے راہ بتلائے سو تمہیں کیا ہوگیا کیا انصاف کرتے ہو'),
  ('ur.ahmedali', 10, 36, 'اور وہ اکثر اٹکل پر چلتے ہیں بےشک حق بات کے سمجھنے میں اٹکل ذرا بھی کام نہیں دیتی بے شک الله جانتا ہے جو کچھ وہ کرتے ہیں'),
  ('ur.ahmedali', 10, 37, 'اوریہ قرآن ایسا نہیں کہ الله کے سوا اسے کوئی اپنی طرف سے بنا لائے اور لیکن اپنے سے پہلے کلام کی تصدیق کرتا ہے اوران چیزوں کو بیان کرتا ہے جو تم پر لکھی گئی اس میں کوئی شک نہیں کہ یہ رب العالمین کی طرف سے ہے'),
  ('ur.ahmedali', 10, 38, 'کیا یہ لوگ کہتے ہیں اس نے اسے خود بنایا ہے کہہ دو تم ایک ہی ایسی سورت لے آؤ اور الله کے سوا جسے بلا سکو بلا لو اگر تم سچے ہو'),
  ('ur.ahmedali', 10, 39, 'بلکہ انہوں نے اس چیز کو جھٹلایا جسے وہ سمجھ نہ سکے اوربھی اس کی حقیقت ان پر کھلی نہیں اسی طرح جو لوگ ان سے پہلے تھے انہوں نے بھی جھٹلایا تھا سو دیکھ لو کہ ظالموں کاانجام کیسا ہوا'),
  ('ur.ahmedali', 10, 40, 'اور ان میں سے بعض ایسے ہیں کہ اس پر ایمان لے آتے ہیں اور بعض ایسے ہیں کہ ایمان نہیں لاتے اور تمہارا رب شریروں سے خوب واقف ہے'),
  ('ur.ahmedali', 10, 41, 'اوراگر تجھے جھٹلائیں تو کہہ دے میرے لیے میرا کام اور تمہارے لیے تمہارا کام تم میرے کام کے جواب دہ نہیں اور میں تمہارے کام کا جواب دہ نہیں ہوں'),
  ('ur.ahmedali', 10, 42, 'اور ان میں بعض ایسے ہیں کہ تمہاری طرف کان لگاتے ہیں کیا تم بہروں کو سنا سکتے ہو اگرچہ وہ نہ سمجھیں'),
  ('ur.ahmedali', 10, 43, 'اور ان میں بعض ایسے ہیں کہ تمہاری طرف دیکھتے ہیں کیا تم اندھوں کو راہ دکھا دوگے اگر کچھ بھی نہ دیکھتے ہوں'),
  ('ur.ahmedali', 10, 44, 'بے شک الله لوگوں پر ذرہ ظلم نہیں کرتا لیکن لوگ ہی اپنے آپ پر ظلم کرتے ہیں'),
  ('ur.ahmedali', 10, 45, 'اور جس دن انہیں جمع کرے گا گویا وہ نہیں رہے تھے مگر ایک گھڑی دن کی ایک دوسرے کو پہچانیں گے بے شک خسارے میں رہے جنہوں نے الله کی ملاقات کو جھٹلایا اور راہ پانے والے نہ ہوئے'),
  ('ur.ahmedali', 10, 46, 'اور اگر ہم تمہیں ان وعدوں میں سے کوئی چیز دکھا دیں جو ہم نے ان سے کیے ہیں یاتمہیں وفات دیں پھر انہیں ہماری طرف لوٹنا ہے پھرالله شاہدہے ان کاموں پر جو کرتے ہیں'),
  ('ur.ahmedali', 10, 47, 'اورہر امت کا یک رسول ہے پھر جب ان کے پاس ان کا رسول آیا تو ان کے درمیان انصاف سے فیصلہ کیا گیا اور ان پر ظلم نہیں کیا جاتا'),
  ('ur.ahmedali', 10, 48, 'اور کہتے ہیں یہ وعدہ کب ہے اگر تم سچے ہو'),
  ('ur.ahmedali', 10, 49, 'کہہ دومیں اپنی ذات کے برے اور بھلے کا بھی مالک نہیں مگر جو الله چاہے ہر امت کا ایک وقت مقرر ہے جب وہ وقت آتا ہے تو ایک گھڑی بھی دیر نہیں کر سکتےہیں اور نہ جلدی کر سکتے ہیں'),
  ('ur.ahmedali', 10, 50, 'کہہ دو بھلا دیکھو تو اگر تم پر اس کا عذاب رات یا دن کو آجائے تو عذاب میں سے کون سی ایسی چیز ہے کہ مجرم اس کو جلدی مانگتے ہیں'),
  ('ur.ahmedali', 10, 51, 'کیا پھر جب وہ آ چکے گا تب اس پر ایمان لاؤ گے اب مانتے ہو اور تم اس کی جلدی کرتے تھے'),
  ('ur.ahmedali', 10, 52, 'پھر ظالموں سے کہا جائے گا ہمیشگی کا عذاب چکھتے رہو تمہیں نہیں بدلا دیا جاتا مگر اس چیز کا جو تم کرتے تھے'),
  ('ur.ahmedali', 10, 53, 'اور تم سے پوچھتے ہیں کیا یہ بات سچ ہے کہہ دو ہاں میرے رب کی قسم بے شک یہ سچ ہے اور تم عاجز کرنے والے نہیں ہو'),
  ('ur.ahmedali', 10, 54, 'اور اگر ہر ایک نافرمان کے پاس روئے زمین کی تمام چیزیں ہوں البتہ اپنے بدلے میں دے ڈالے اور جب وہ عذاب دیکھیں گے تو دل میں نادم ہوں گے اور ان کے درمیان انصاف سے فیصلہ ہوگا اور ان پر ظلم نہیں کیا جائے گا'),
  ('ur.ahmedali', 10, 55, 'خبردار بےشک الله ہی کا ہے جو کچھ آسمان اور زمین میں ہے خبردار بے شک الله کا وعدہ سچا ہے لیکن اکثر لوگ نہیں جانتے'),
  ('ur.ahmedali', 10, 56, 'وہی زندہ کرتا ہے اور مارتا ہے اور اسی کی طرف پھر کر جاؤ گے'),
  ('ur.ahmedali', 10, 57, 'اے لوگو تمہارے رب سے نصیحت اور دلوں کے روگ کی شفا تمہارے پاس آئی ہے اور ایمان داروں کے لیے ہدایت اور رحمت ہے'),
  ('ur.ahmedali', 10, 58, 'کہہ دو (قرآن) الله کے فضل اور اس کی رحمت سےہے سو اسی پر انہیں خوش ہونا چاہیئے یہ ان چیزوں سے بہتر ہے جو جمع کرتے ہیں'),
  ('ur.ahmedali', 10, 59, 'کہہ دو بھلا دیکھو تو الله نے تمہارے لیے جو رزق نازل فرمایاہے تم نے اس میں سے بعض کو حرام اوربعض کو حلال کر دیا کہہ دو الله نے تمہیں حکم دیا ہے یا الله پر افترا کرتے ہو'),
  ('ur.ahmedali', 10, 60, 'اور جو لوگ الله پر افترا کرتے ہیں قیامت کے دن کی نسبت ان کا کیا خیال ہے بے شک الله لوگوں پر مہربان ہے لیکن اکثر لوگ شکر نہیں کرتے'),
  ('ur.ahmedali', 10, 61, 'اور تم جس حال میں ہوتے ہو یا قرآن میں سے کچھ پڑھتے ہو یا تم لوگ کوئی کام کرتے ہوتو ہم وہاں موجود ہوتے ہیں جب تم اس میں مصروف ہوتے ہو اور تمہارے رب سے ذرہ بھر بھی کوئی چیز پوشدیہ نہیں ہے نہ زمین میں اور نہ آسمان میں اور نہ کوئی چیز اس سے چھوٹی اور نہ بڑی مگر کتاب روشن میں ہے'),
  ('ur.ahmedali', 10, 62, 'خبردار بے شک جو الله کے دوست ہیں نہ ان پر ڈر ہے اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 10, 63, 'جو لوگ ایمان لائے اور ڈرتے رہے'),
  ('ur.ahmedali', 10, 64, 'ان کے لیے دنیا کی زندگی اور آخرت میں خوشخبری ہے الله کی باتوں میں تبدیلی نہیں ہوتی یہی بڑی کامیابی ہے'),
  ('ur.ahmedali', 10, 65, 'اور ان کی بات سے غم نہ کربے شک عزت سب الله ہی کے لیے ہے وہی سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 10, 66, 'خبردار جو کوئی آسمانوں میں ہے اور جو کوئی زمین میں ہے سب الله کا ہے اور یہ جو الله کے سوا شریکوں کو پکارتے ہیں وہ نہیں پیروی کرتے مگر گمان کی اور نہیں ہیں وہ مگر اٹکل کرتے ہیں'),
  ('ur.ahmedali', 10, 67, 'وہی تو ہے جس نے تمہارے لیے رات بنائی تاکہ اسمیں آرام کرو اور دن دکھلانے والا بنایا بے شک اس میں ان لوگوں کے لیے نشانیاں ہیں جو سنتے ہیں'),
  ('ur.ahmedali', 10, 68, 'کہتے ہیں الله نے بیٹا بنا لیا وہ پاک ہے وہ بے نیاز ہے جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے تمہارے پاس اس کی کوئی سند نہیں ہے تم الله پر ایسی باتیں کیوں کہتے ہو جو جانتے نہیں'),
  ('ur.ahmedali', 10, 69, 'کہہ دو جو لوگ الله پر افترا کرتے ہیں نجات نہیں پائیں گے'),
  ('ur.ahmedali', 10, 70, 'دنیا میں تھوڑا سا نفع اٹھا لینا ہے پھر ہماری طرف انہیں لوٹنا ہے پھر ہم انہیں سخت عذاب چکھائیں گے بسبب اس کے کہ کفر کرتے تھے'),
  ('ur.ahmedali', 10, 71, 'اور انہیں نوح کا حال سنا جب اس نے اپنی قوم سے کہا اے قوم اگر تمہیں میرا تم میں رہنا اور الله کی آیتوں سے نصیحت کرنا ناگوار ہو تو میں الله پر بھروسہ کرتا ہوں اب تم سب ملکر اپنا کام مقرر کرو اور اپنے شریکوں کو جمع کرو پھر تمہیں اپنے کام میں شبہ نہ رہے پھر وہ کام میرے ساتھ کر گزرو اور مجھے مہلت نہ دو'),
  ('ur.ahmedali', 10, 72, 'پھر اگر منہ پھیرو تو میں نے تم سے کچھ معاوضہ نہیں مانگا میرا معاوضہ الله پر ہے اور مجھے حکم دیا گیا ہے کہ فرمانبرداروں میں سے رہوں'),
  ('ur.ahmedali', 10, 73, 'پھر انہوں نے اسے جھٹلایا پھر ہم نے اسے اور اس کے ساتھیوں کو کشتی میں بچا لیا اور انہیں خلیفہ بنا دیا اور جن لوگو ں نے ہماری آیتوں کو جھٹلایا انہیں غرق کر دیا سو دیکھ لو کہ جو لوگ ڈرائے گئے تھے ان کا انجام کیسا ہوا'),
  ('ur.ahmedali', 10, 74, 'پھر ہم نے نوح کے بعد اور پیغمبر اپنی اپنی قوم کی طرف بھیجے تو وہ ان کے پاس کھلی نشانیاں لائے پھر بھی ان سے یہ نہ ہوا کہ اس بات پر ایمان لے آئيں جسے پہلے وہ جھٹلا چکے تھے اسی طرح ہم حد سے نکل جانے والوں کے دلوں پر مہر لگا دیتے ہیں'),
  ('ur.ahmedali', 10, 75, 'پھر ہم نے ان کے بعد موسیٰ اورہارون کو فرعون اور اس کےسرداروں کے پاس اپنی نشانیاں دے کر بھیجا پھر انہوں نے تکبر کیا اور وہ لوگ گنہگار تھے'),
  ('ur.ahmedali', 10, 76, 'پھر جب انہیں ہمارے ہاں سے سچی بات پہنچی کہنے لگے یہ تو کھلا جادو ہے'),
  ('ur.ahmedali', 10, 77, 'موسیٰ نے کہا کیاتم حق بات کو یہ کہتے ہو جب وہ تمہارے پاس آئی کیا یہ جادو ہے اور جادو کرنے والے نجات نہیں پاتے'),
  ('ur.ahmedali', 10, 78, 'انہوں نے کہا کیاتو ہمارے ہاں آیا ہے کہ ہمیں اس راستہ سے پھیر دے جس پر ہم نے اپنے باپ دادوں کو پایا ہے تم دونوں کو اس ملک میں سرداری مل جائے اور ہم تو تمہیں ماننے والے نہیں ہیں'),
  ('ur.ahmedali', 10, 79, 'اور فرعون نے کہا میرے پاس ہردانا جادوگر کو لے آؤ'),
  ('ur.ahmedali', 10, 80, 'پھر جب جادوگر آئے انہیں موسیٰ نے کہا ڈالو جو تم ڈالتے ہو'),
  ('ur.ahmedali', 10, 81, 'پھر جب انہوں نے ڈالا موسیٰ نے کہا جو تم لائے ہو وہ جادو ہے الله اسے ابھی درہم برہم کر دے گا بے شک الله شریروں کے کام نہیں سنوارتا'),
  ('ur.ahmedali', 10, 82, 'اور الله اپنے حکم سےحق بات کو سچا کرتا ہے اگرچہ گنہگار برا ہی مانیں'),
  ('ur.ahmedali', 10, 83, 'پھر کوئی بھی موسیٰ پر ایمان نہ لایا مگر اس کی قوم کے چند لڑکے اور وہ بھی فرعون اور ان کے سرداروں سے ڈرتے ڈرتے کہ کہیں وہ انہیں مصیبت میں نہ ڈال دے اور بے شک فرعون زمین میں سرکشی کرنے والا تھا اوربے شک وہ حد سے گزرنے والوں میں سے تھا'),
  ('ur.ahmedali', 10, 84, 'اور موسیٰ نے کہا اے میری قوم اگر تم الله پر ایمان لائے ہو تو اسی پر بھروسہ کرو اگر تم فرمانبردار ہو'),
  ('ur.ahmedali', 10, 85, 'تب وہ بولے ہم الله ہی پر بھروسہ کرتے ہیں اے رب ہمارے ہم پر اس ظالم قوم کا زور نہ آزما'),
  ('ur.ahmedali', 10, 86, 'اور ہمیں مہربانی فرما کر ان کافروں سے چھڑا دے'),
  ('ur.ahmedali', 10, 87, 'اور ہم نے موسیٰ اور اس کے بھائی کو حکم بھیجا کہ اپنی قوم کے واسطے مصر میں گھر بناؤ اوراپنے گھروں کو مسجدیں سمجھو اور نماز قائم کرو اورایمان والوں کو خوشخبری دو'),
  ('ur.ahmedali', 10, 88, 'اورموسیٰ نے کہا اے رب ہمارے تو نے فرعون اوراس کے سرداروں کو دنیا کی زندگی میں آرائش اور ہر طرح کا مال دیا ہے اے رب ہمارے یہاں تک کہ انہوں نےتیرے راستہ سے گمراہ کر دیا اے رب ہمارے ان کے مالوں کو برباد کر دے اور ان کے دلوں کو سخت کر دے پس یہ ایمان نہیں لائیں گے یہاں تک کہ دردناک عذاب دیکھیں'),
  ('ur.ahmedali', 10, 89, 'فرمایا تمہاری دعا قبول ہو چکی سو تم دونوں ثابت قدم رہو اوربے عقلوں کی راہ پر مت چلو'),
  ('ur.ahmedali', 10, 90, 'اور ہم نے بنی اسرائیل کو دریا سے پار کر دیا پھر فرعون اور اس کے لشکر نے ظلم اور زيادتی سے ان کا پیچھا کیا یہاں تک کہ جب ڈوبنےلگا کہا میں ایمان لایا کہ کوئی معبود نہیں مگر جس پر بنی اسرائیل ایمان لائے ہیں اور میں فرمانبردار میں سے ہوں'),
  ('ur.ahmedali', 10, 91, 'اب یہ کہتا ہے اورتو اس سے پہلے نافرمانی کرتا رہا اور مفسدوں میں داخل رہا'),
  ('ur.ahmedali', 10, 92, 'سو آج ہم تیرے بدن کو نکال لیں گے تاکہ تو پچھلوں کے لیے عبرت ہو اوربے شک بہت سے لوگ ہماری نشانیوں سے بے خبر ہیں'),
  ('ur.ahmedali', 10, 93, 'اور البتہ تحقیق ہم نے بنی اسرائیل کو رہنے کی عمدہ جگہ دی اور کھانے کو ستھری چیزیں دیں وہ باوجود علم ہونے کے خلاف کرتے رہے بےشک تیرا رب قیامت کے دن ان میں فیصلہ کرے گا جس بات میں کہ وہ اختلاف کرتے تھے'),
  ('ur.ahmedali', 10, 94, 'سو اگرتمہیں اس چیز میں شک ہے جو ہم نے تیری طرف اتاری تو ان سے پوچھ لے جو تجھ سے پہلے کتاب پڑھتے ہیں بے شک تیرے پاس تیرے رب سے حق بات آئی ہے سو شک کرنے والوں میں ہرگز نہ ہو'),
  ('ur.ahmedali', 10, 95, 'اوران میں سے بھی نہ ہو جنہوں نے الله کی آیتوں کو جھٹلایا پھر تو بھی نقصان اٹھانے والوں میں سے ہوگا'),
  ('ur.ahmedali', 10, 96, 'جن پر تیرے رب کی بات ثابت ہو چکی ہے وہ ایمان نہیں لائیں گے'),
  ('ur.ahmedali', 10, 97, 'اگرچہ انہیں ساری نشانیاں پہنچ جائیں جب تک کہ دردناک عذاب نہ دیکھ لیں'),
  ('ur.ahmedali', 10, 98, 'سو کوئی بستی ایسی کیوں نہ ہوئی جو ایمان لاتی تو اس کا ایمان اسے نفع دیتا سوائے یونس کی قوم کے کہ جب وہ ایمان لائے تو ہم نے دنیا کی زندگی میں ان سے ذلت کا عذاب دور کر دیا اور ہم نے انہیں ایک وقت تک فائدہ پہنچایا'),
  ('ur.ahmedali', 10, 99, 'اور اگر تیرا رب چاہتا تو جتنے لوگ زمین میں ہیں سب کے سب ایمان لے آتے پھر کیا تو لوگوں پر زبردستی کرے گا کہ وہ ایمان لے آئيں'),
  ('ur.ahmedali', 10, 100, 'اورکسی کے بھی بس میں نہیں کہ الله کے حکم کے سوا ایمان لے آئے اور الله انکے لیے کفر کا فیصلہ کرتا ہے جو نہیں سوچتے'),
  ('ur.ahmedali', 10, 101, 'کہہ دو دیکھوکہ آسمانوں اور زمین میں کیا کچھ ہے اور بے ایمان قوم کو معجزے اور ڈرانے والے کچھ فائدہ نہیں دیتے'),
  ('ur.ahmedali', 10, 102, 'پھر کیا وہ انہیں لوگوں کے دنوں کا سا انتظار کرتے ہیں جو ان سے پہلے گزرے ہیں کہہ دو اچھا انتظار کرو میں بھی تمہارے ساتھ انتظار کرتا ہوں'),
  ('ur.ahmedali', 10, 103, 'پھر ہم اپنے رسولوں اوران لوگوں کو جو ایمان لاتے ہیں بچا لیتے ہیں اسی طرح ہمارا ذمہ ہے کہ ایمان والوں کوبچا لیں'),
  ('ur.ahmedali', 10, 104, 'کہہ دو اے لوگو اگر تمہیں میرے دین میں شک ہے تو الله کے سوا جن کی تم عبادت کرتے ہو میں ان کی عبادت نہیں کرتا بلکہ میں الله کی عبادت کرتا ہوں جو تمہیں وفات دیتا ہے اور مجھے حکم ہوا ہے کہ ایمانداروں میں رہوں'),
  ('ur.ahmedali', 10, 105, 'اور یہ بھی کہ یک سوہوکر دین کی طرف رخ کیے رہو اور مشرکوں میں نہ ہو'),
  ('ur.ahmedali', 10, 106, 'اور الله کے سوا ایسی چیز کونہ پکار جو نہ تیرا بھلا کرے اور نہ برا پھر اگرتو نے ایسا کیا تو بے شک ظالموں میں سے ہو جائے گا'),
  ('ur.ahmedali', 10, 107, 'اوراگر الله تمہیں کوئی تکلیف پہنچائے تو اس کے سوا اسے ہٹانے والا کوئی نہیں اور اگر تمہیں کوئی بھلائی پہنچانا چاہے توکوئی اس کے فضل کو پھیرنے والا نہیں اپنے بندوں میں سے جسے چاہتا ہے اپنا فضل پہنچاتا ہے اور وہی بحشنے والا مہربان ہے'),
  ('ur.ahmedali', 10, 108, 'کہہ دو اے لوگو تمہیں تمہارے رب سے حق پہنچ چکا ہے پس جو کوئی راہ پر آئے سو وہ اپنے بھلے کے لیے راہ پاتا ہے اور جو گمراہ رہے گا اس کا وبال اسی پر پڑے گا اور میں تمہارا ذمہ دارنہیں ہوں'),
  ('ur.ahmedali', 10, 109, 'اورجو کچھ تیری طرف وحی کیا گیا ہے ا س پر چل اور صبر کر یہاں تک کہ الله فیصلہ کر دے اور وہ بہتر فیصلہ کرنے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 10, 1, 'Elif, Lam, Ra. İşte bunlar hikmetli Kitap\'ın ayetleridir.'),
  ('tr.diyanet', 10, 2, 'İçlerinden birine, "İnsanları uyar ve inananlara, Rableri katında yüksek makamlar olduğunu müjdele" diye vahyetmemiz, insanların tuhafına mı gitti ki, kafirler: "Bu apaçık bir büyücüdür" dediler?'),
  ('tr.diyanet', 10, 3, 'Doğrusu sizin Rabbiniz gökleri ve yeri altı günde yaratıp sonra arşa hükmeden, işi düzenleyen Allah\'tır, izni olmadan kimse şefaat edemez. İşte Rabbiniz olan Allah budur. O\'na kulluk edin. Nasihat dinlemez misiniz?'),
  ('tr.diyanet', 10, 4, 'Hepinizin dönüşü, O\'nadır. Allah\'ın vadi haktır. O, önce yaratır, sonra inanıp yararlı işler yapanların ve inkar edenlerin hareketlerinin karşılığını adaletle vermek için tekrar diriltir. İnkarcılara, inkarlarından ötürü kızgın bir içecek ve can yakıcı azab vardır.'),
  ('tr.diyanet', 10, 5, 'Güneşi ışıklı ve ayı nurlu yapan; yılların sayısını ve hesabı bilmeniz için, aya konak yerleri düzenleyen O\'dur. Allah bunları ancak gerçeğe göre yaratmıştır; bilen millete ayetleri uzun uzadıya açıklıyor.'),
  ('tr.diyanet', 10, 6, 'Gece ile gündüzün birbiri ardınca gelmesinde, Allah\'ın göklerde ve yerde yarattıklarında, O\'na karşı gelmekten sakınan kimseler için ayetler vardır.'),
  ('tr.diyanet', 10, 7, 'Bizimle karşılaşmayı ummayan ve dünya hayatından hoşnut olup ona bağlananların ve ayetlerimizden habersiz bulunanların, işte bunların kazandıklarına karşılık varacakları yer cehennemdir.'),
  ('tr.diyanet', 10, 8, 'Bizimle karşılaşmayı ummayan ve dünya hayatından hoşnut olup ona bağlananların ve ayetlerimizden habersiz bulunanların, işte bunların kazandıklarına karşılık varacakları yer cehennemdir.'),
  ('tr.diyanet', 10, 9, 'İnananlar ve yararlı iş yapanları, imanlarına karşılık Rableri doğru yola eriştirir; nimet cennetlerinde onların altlarından ırmaklar akar.'),
  ('tr.diyanet', 10, 10, 'Oradaki duaları: "Münezzehsin ey Allah\'ım", dirlik temennileri: "Selam size" ve dualarının sonu da: "Alemlerin Rabbi Allah\'a hamd olsun"dur.'),
  ('tr.diyanet', 10, 11, 'İyiliği acele isteyen kimselere Allah fenalığı da çarçabuk verseydi, süreleri hemen bitmiş olurdu. Bizimle karşılaşmayı ummayanları, azgınlıkları içinde bocalayıp dururlarken bırakırız.'),
  ('tr.diyanet', 10, 12, 'İnsana bir darlık gelince, yan yatarken, oturur veya ayakta iken bize yalvarıp yakarır; biz darlığını giderince, başına gelen darlıktan ötürü bize hiç yalvarmamışa döner. İşlerinde tutumsuz olanlara, yaptıkları böylece güzel görünür.'),
  ('tr.diyanet', 10, 13, 'And olsun ki, sizden önce nice nesilleri, peygamberleri onlara belgeler getirmişken, haksızlık ederek inanmadıkları zaman yok etmiştik. İşte biz suçlu milleti böyle cezalandırırız.'),
  ('tr.diyanet', 10, 14, 'Sonra onların ardından, nasıl davranacağınıza bakmak için sizi yeryüzünde onların yerine geçirdik.'),
  ('tr.diyanet', 10, 15, 'Ayetlerimiz onlara açık açık okununca, bizimle karşılaşmayı ummayanlar, "Bundan başka bir Kuran getir veya bunu değiştir" dediler. De ki: "Onu kendiliğimden değiştiremem, ben ancak, bana vahyolunana uyarım. Ben Rabbime karşı gelirsem, büyük günün azabına uğramaktan korkarım."'),
  ('tr.diyanet', 10, 16, 'De ki: "Allah dileseydi ben onu size okumazdım, size de bildirmemiş olurdu. Daha önce yıllarca aranızda bulundum, hiç düşünmüyor musunuz?"'),
  ('tr.diyanet', 10, 17, 'Allah\'a karşı yalan uyduran veya ayetlerini yalan sayandan daha zalim kim olabilir? Suçlular elbette saadete erişemezler.'),
  ('tr.diyanet', 10, 18, 'Onlar, Allah\'ı bırakarak, kendilerine fayda da zarar da veremeyen putlara taparlar: "Bunlar, Allah katında bizim şefaatçılarımızdır" derler. De ki: "Göklerde ve yerde, Allah\'ın bilmediği bir şeyi mi O\'na haber veriyorsunuz?" Allah, onların ortak koşmalarından münezzeh ve yücedir.'),
  ('tr.diyanet', 10, 19, 'İnsanlar bir tek ümmettiler, sonra ayrılığa düştüler; şayet Rabbinden, daha önce bir takdir geçmemiş olsaydı, aralarında ihtilafa düştükleri şeyler hakkında hüküm çoktan verilmiş olurdu.'),
  ('tr.diyanet', 10, 20, '"Rabbinden ona (Muhammed\'e) bir mucize indirilse ne olur!" derler. Onlara de ki: "Gaybı bilmek Allah\'a mahsustur; bekleyin, doğrusu ben de sizinle birlikte beklemekteyim."'),
  ('tr.diyanet', 10, 21, 'İnsanlara darlık geldikten sonra onlara bolluğu taddırdığımızda, hemen ayetlerimize dil uzatmağa kalkışırlar; onlara de ki: "Hile yapanın cezasını vermekte Allah daha çabuktur." Elçi meleklerimiz kurduğunuz tuzakları hiç şüphesiz yazmaktadırlar.'),
  ('tr.diyanet', 10, 22, 'Sizi karada ve denizde yürüten Allah\'tır. Bulunduğunuz gemi, içindekileri güzel bir rüzgarla götürürken yolcular neşelenirler; bir fırtına çıkıp da onları her taraftan dalgaların sardığı ve çepeçevre kuşatıldıklarını sandıkları anda ise Allah\'ın dinine sarılarak, "Bizi bu tehlikeden kurtarırsan and olsun ki şükredenlerden oluruz" diye O\'na yalvarırlar.'),
  ('tr.diyanet', 10, 23, 'Allah onları kurtarınca, hemen yeryüzünde haksız yere taşkınlıklara başlarlar. Ey insanlar! Geçici dünya hayatında yaptığınız taşkınlık aleyhinizedir. Sonra dönüşünüz Bizedir. Yaptıklarınızı size bildiririz.'),
  ('tr.diyanet', 10, 24, 'Dünya hayatı gökten indirdiğimiz su gibidir ki, onunla insan ve hayvanların yiyeceği bitkiler yetişip birbirine karışmıştır. Yeryüzünün süslenip bezendiği ve yerin sahiplerinin bütün bunlara malik olduklarını sandıkları sırada, gece veya gündüz buyruğumuz o yere gelmiş ve orayı hiçbir şey bitirmemişe çevirmişiz; bir gün önce birşey yokmuş gibi olmuştur. Düşünen millet için ayetleri böylece uzun açıklıyoruz.'),
  ('tr.diyanet', 10, 25, 'Allah, cennete çağırır ve dilediğini doğru yola eriştirir.'),
  ('tr.diyanet', 10, 26, 'İyi davrananlara; daima daha iyisi ve üstünü verilir. Onların yüzlerine ne bir karalık, ne de zillet bulaşır. İşte onlar cennetliklerdir, orada temelli kalırlar.'),
  ('tr.diyanet', 10, 27, 'Kötülük işleyenlere kötülükleri kadar ceza verilir; onların yüzlerini zillet bürür; Allah\'a karşı onları savunacak yoktur; yüzleri, geceden kara bir parçayla örtülmüş gibidir. Bunlar cehennemliklerdir, orada temelli kalırlar.'),
  ('tr.diyanet', 10, 28, 'Onların hepsini bir gün toplarız, sonra, puta tapanlara, "Siz ve putlarınız yerlerinize! deyip onları birbirlerinden ayırırız. Putları ise: "Bize tapmıyordunuz ki. Allah, sizinle bizim aramızda şahit olarak yeter. Sizin tapınmanızdan bizim haberimiz yoktu" derler.'),
  ('tr.diyanet', 10, 29, 'Onların hepsini bir gün toplarız, sonra, puta tapanlara, "Siz ve putlarınız yerlerinize! deyip onları birbirlerinden ayırırız. Putları ise: "Bize tapmıyordunuz ki. Allah, sizinle bizim aramızda şahit olarak yeter. Sizin tapınmanızdan bizim haberimiz yoktu" derler.'),
  ('tr.diyanet', 10, 30, 'İşte orada herkes dünyada yapmış olduğuyla imtihan verir ve gerçek Mevlaları olan Allah\'a döndürülür. Uydurdukları putlar da ortadan kaybolmuştur.'),
  ('tr.diyanet', 10, 31, 'De ki: "Gökten ve yerden size rızık veren kimdir? Kulak ve gözlerin sahibi kimdir? Diriyi ölüden çıkaran, ölüyü de diriden çıkaran kimdir? Her işi düzenleyen kimdir?" Onlar: "Allah\'tır! " diyecekler. "O halde O\'na karşı gelmekten sakınmaz mısınız?" de.'),
  ('tr.diyanet', 10, 32, 'İşte gerçek Rabbiniz Allah budur. Gerçeğin dışında sadece sapıklık vardır. Öyleyse nasıl olup da döndürülüyorsunuz?'),
  ('tr.diyanet', 10, 33, 'Böylece, fasık olanların inanmayacaklarına dair Rabbinin söylediği söz gerçekleşti.'),
  ('tr.diyanet', 10, 34, 'De ki: "Koştuğunuz ortaklardan, önce yaratan, sonra bunu tekrar eden var mıdır?" De ki: "Allah önce yaratır, sonra bunu tekrar eder. Nasıl da döndürülürsünüz! "'),
  ('tr.diyanet', 10, 35, 'De ki: "Koştuğunuz ortaklardan gerçeğe eriştiren var mıdır?" De ki: "Ama Allah gerçeğe eriştirir. Gerçeğe eriştiren mi, yoksa, birisi götürmezse gidemeyen mi uyulmağa daha layıktır? Ne biçim hüküm veriyorsunuz?"'),
  ('tr.diyanet', 10, 36, 'Onların çoğu zanna uyarlar; gerçekte ise zan, hakikat karşısında bir şey ifade etmez. Allah, yaptıklarını şüphesiz bilir.'),
  ('tr.diyanet', 10, 37, 'Bu Kuran, Allah\'tandır, başkası tarafından uydurulmuş değildir. Ancak kendinden öncekini doğrular ve O Kitap\'ı açıklar. Alemlerin Rabbinden geldiğinden şüphe yoktur.'),
  ('tr.diyanet', 10, 38, 'Senin için, "Onu uydurdu mu?" diyorlar. De ki: "Onun surelerine benzer bir sure meydana getirin, iddianızda samimi iseniz, Allah\'tan başka çağırabileceklerinizi de çağırın."'),
  ('tr.diyanet', 10, 39, 'Onlar, ilmini kavrayamadıkları ve henüz yorumu da kendilerine bildirilmemiş olan şeyi yalanladılar. Onlardan öncekiler de böylece yalanlamışlardı. Zalimlerin sonunun nasıl olduğuna bir bak.'),
  ('tr.diyanet', 10, 40, 'Aralarında ona inanan ve inanmayan vardır. Rabbin, bozguncuları daha iyi bilir.'),
  ('tr.diyanet', 10, 41, 'Seni yalanlarlarsa, "Benim yaptığım bana, sizin yaptığınız sizedir; siz benim yaptığımdan sorumlu değilsiniz, ben de sizin yaptığınızdan sorumlu değilim" de.'),
  ('tr.diyanet', 10, 42, 'Aralarında sana kulak veren vardır. Sen, sağırlara, üstelik akılları da almazsa, işittirebilir misin?'),
  ('tr.diyanet', 10, 43, 'Aralarında sana bakan vardır. Sen körleri, görmezlerken doğru yola iletebilir misin?'),
  ('tr.diyanet', 10, 44, 'Allah insanlara hiç zulmetmez, fakat insanlar kendilerine zulmederler.'),
  ('tr.diyanet', 10, 45, 'Onları toplayacağı kıyamet günü, sanki gündüz, birbirleriyle sadece tanışacakları bir saat kadar kalmış gibidirler. Allah\'ın karşısına çıkmayı yalan sayanlar kaybetmişlerdir.'),
  ('tr.diyanet', 10, 46, 'Onlara, söz verdiğimiz azabın bir kısmını ya dünyada sana gösteririz, veya senin ruhunu alırız da nasıl olsa onların dönüşü Bizedir; (ahirette görürsün) Allah onların yaptıklarına şahiddir.'),
  ('tr.diyanet', 10, 47, 'Her ümmetin bir peygamberi vardır. Onlara peygamberleri geldiğinde aralarında adaletle hüküm verilmiş olur. Onların hakları yenmez.'),
  ('tr.diyanet', 10, 48, '"Bu iddiada samimi iseniz, bu azabın gerçekleşmesi ne zamandır? söyle" derler.'),
  ('tr.diyanet', 10, 49, 'De ki: "Allah\'ın dilemesi dışında ben kendime bir fayda ve zarar verecek durumda değilim. Her ümmet için bir süre vardır; süreleri sona erince bir saat bile geciktirilmezler ve öne de alınmazlar."'),
  ('tr.diyanet', 10, 50, 'De ki: "Allah\'ın azabı size gece veya gündüz gelirse, ne yaparsınız? Suçlular neye bunda acele ediyorlar?"'),
  ('tr.diyanet', 10, 51, 'Vuku bulduktan sonra mı O\'na inanacaksınız? İnanmayanlar azabı görünce, "şimdi miydi?" derler. "Elbette, siz onu acele istiyordunuz" denir.'),
  ('tr.diyanet', 10, 52, 'Haksızlık edenlere de: "Sürekli azabı tadın, ancak yaptığınıza karşılık ceza çekiyorsunuz" denir.'),
  ('tr.diyanet', 10, 53, '"O gerçek midir?" diye senden sorarlar. De ki: "Evet, Rabbim hakkı için o gerçektir, siz aciz kılamazsınız (önleyemezsiniz)."'),
  ('tr.diyanet', 10, 54, 'Haksızlık etmiş olan her kişi, yeryüzünde olan her şeye sahip olsa, onu azabın fidyesi olarak verirdi. Azabı görünce pişmanlık gösterdiler. Haksızlığa uğratılmadan aralarında adaletle hükmolunmuştur.'),
  ('tr.diyanet', 10, 55, 'İyi bilin ki, Allah\'ın verdiği söz gerçektir, ama çoğu bunu bilmez.'),
  ('tr.diyanet', 10, 56, 'Dirilten ve öldüren O\'dur. O\'na döneceksiniz.'),
  ('tr.diyanet', 10, 57, 'Ey insanlar! Rabbinizden size bir öğüt ve kalblerde olana şifa, inananlara doğruyu gösteren bir rehber ve rahmet gelmiştir.'),
  ('tr.diyanet', 10, 58, 'De ki: "Bunlar, Allah\'ın bol nimeti ve rahmetiyledir." Buna sevinsinler. O, onların topladıklarından daha hayırlıdır.'),
  ('tr.diyanet', 10, 59, 'De ki: "Allah\'ın size indirdiği rızkın bir kısmını haram, bir kısmını helal kıldığınızı görmüyor musunuz?" De ki: "Size Allah mı izin verdi, yoksa Allah\'a karşı yalan mı uyduruyorsunuz?"'),
  ('tr.diyanet', 10, 60, 'Allah\'a karşı yalan uyduranlar kıyamet gününü ne zannederler? Doğrusu Allah\'ın insanlara olan nimeti boldur, fakat çoğu şükretmezler.'),
  ('tr.diyanet', 10, 61, 'Ne iş yaparsan yap ve sizler ona dair Kuran\'dan ne okursanız okuyun; ne yaparsanız yapın; yaptıklarınıza daldığınız anda, mutlaka Biz sizi görürüz. Yerde ve gökte hiçbir zerre Rabbinden gizli değildir. Bundan daha küçüğü veya daha büyüğü şüphesiz apaçık bir Kitap\'dadır.'),
  ('tr.diyanet', 10, 62, 'İyi bilin ki, Allah\'ın dostlarına korku yoktur, onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 10, 63, 'Onlar Allah\'a inanmış ve O\'na karşı gelmekten sakınmışlardır.'),
  ('tr.diyanet', 10, 64, 'Dünya hayatında da, ahirette de müjde onlaradır. Allah\'ın sözlerinde hiçbir değişme yoktur. Bu büyük başarıdır.'),
  ('tr.diyanet', 10, 65, 'İnkarcıların sözleri seni üzmesin, çünkü bütün kudret Allah\'ındır. O, işitir ve bilir.'),
  ('tr.diyanet', 10, 66, 'İyi bilin ki, göklerde ve yerde kim varsa hepsi Allah\'ındır. Allah\'ı bırakıp ortak koşanlar sadece zanna uyanlardır. Onlar ancak tahminde bulunuyorlar.'),
  ('tr.diyanet', 10, 67, 'Size geceyi dinlenesiniz diye karanlık ve gündüzü çalışasınız diye aydınlık olarak yaratan Allah\'tır. Kulak veren millet için bunlarda ayetler vardır.'),
  ('tr.diyanet', 10, 68, '"Allah çocuk edindi" dediler; haşa; O müstağnidir; göklerde ve yerde olanlara sahiptir. Elinizde, onun çocuk edindiğine dair bir delil yoktur, bilmediğiniz şeyi Allah\'a karşı nasıl söylüyorsunuz?'),
  ('tr.diyanet', 10, 69, 'De ki: "Allah\'a karşı yalan uyduranlar, kurtuluşa erişemezler."'),
  ('tr.diyanet', 10, 70, 'Onlar için dünyada bir müddet geçinme vardır, sonra dönüşleri Bizedir. İnkarlarına karşılık onlara çetin azab taddıracağız.'),
  ('tr.diyanet', 10, 71, 'Onlara Nuh\'un başından geçenleri anlat: Milletine, "Ey milletim! Eğer durumum, Allah\'ın ayetlerini hatırlatmam size ağır geliyorsa ki ben Allah\'a güvenmişimdir siz ve koştuğunuz ortaklar elbirliği edin; yapacağınız iş sonra size bir tasa vermesin. Sonra onu bana uygulayın ve beni ertelemeyin" demişti.'),
  ('tr.diyanet', 10, 72, '"Eğer yüz çevirirseniz bilin ki, ben sizden bir ücret istemiyorum. Benim ecrim Allah\'a aiddir. Müslimlerden olmakla emrolundum."'),
  ('tr.diyanet', 10, 73, 'Onu yalancı saydılar; ama Biz onu ve gemide beraberinde bulunanları kurtardık. Onları ötekilerin yerine geçirdik, ayetlerimizi yalanlayanları suda boğduk. Uyarılanlardan söz dinlemeyenlerin sonlarının nasıl olduğuna bir bak.'),
  ('tr.diyanet', 10, 74, 'Sonra onun ardından milletlere peygamberler gönderdik, onlara belgeler getirdiler. Diğerlerinin daha önce yalan saymış olduklarına bunlar da inanmadılar. Aşırı gidenlerin kalblerini işte böylece mühürleriz.'),
  ('tr.diyanet', 10, 75, 'Onların ardından da Firavun ve erkanına ayetlerimizle Musa ve Harun\'u gönderdik. Ama büyüklük tasladılar ve suçlu bir millet oldular.'),
  ('tr.diyanet', 10, 76, 'Gerçek, katımızdan onlara gelince: "Doğrusu bu apaçık bir büyüdür" dediler.'),
  ('tr.diyanet', 10, 77, 'Musa: "Size gelen gerçeğe dil mi uzatırsınız? Bu sihir midir? Sihirbazlar zaten başarı kazanamazlar" dedi.'),
  ('tr.diyanet', 10, 78, '"Siz ikiniz, bizi babalarımızı üzerinde bulduğumuz yoldan çevirmek ve yeryüzünün büyükleri olasınız diye mi geldiniz? Biz size inanmıyoruz" dediler.'),
  ('tr.diyanet', 10, 79, 'Firavun: "Bütün bilgin sihirbazları bana getirin" dedi.'),
  ('tr.diyanet', 10, 80, 'Sihirbazlar gelince Musa onlara: "Atacağınızı atın" dedi.'),
  ('tr.diyanet', 10, 81, 'Attıklarında, Musa: "Yaptığınız sihirdir, fakat Allah onu boşa çıkaracaktır. Allah bozguncuların işini elbette düzeltmez. Suçlular istemese de Allah sözleriyle hakkı gerçekleştirecektir" dedi.'),
  ('tr.diyanet', 10, 82, 'Attıklarında, Musa: "Yaptığınız sihirdir, fakat Allah onu boşa çıkaracaktır. Allah bozguncuların işini elbette düzeltmez. Suçlular istemese de Allah sözleriyle hakkı gerçekleştirecektir" dedi.'),
  ('tr.diyanet', 10, 83, 'Firavun ve erkanının kendilerine fenalık yapmasından korktuklarından, milletinin bir kısım gençleri dışında, kimse Musa\'ya inanmamıştı, çünkü Firavun o yerde hakimdi. O, gerçekten aşırı gidenlerdendi.'),
  ('tr.diyanet', 10, 84, 'Musa: "Ey milletim! Allah\'a inanıyorsanız ve teslim olmuşsanız O\'na güvenin" dedi.'),
  ('tr.diyanet', 10, 85, '"Allah\'a güvendik; Ey Rabbimiz! Zalim bir millet ile bizi sınama, rahmetinle bizi kafirlerden kurtar" dediler.'),
  ('tr.diyanet', 10, 86, '"Allah\'a güvendik; Ey Rabbimiz! Zalim bir millet ile bizi sınama, rahmetinle bizi kafirlerden kurtar" dediler.'),
  ('tr.diyanet', 10, 87, 'Musa ve kardeşine: "Mısır\'da milletinize evler hazırlayın; evlerinizi namazgah edinin, namaz kılın" diye vahyettik, "İnananlara müjde et."'),
  ('tr.diyanet', 10, 88, 'Musa: "Rabbimiz! Doğrusu sen Firavun\'a ve erkanına ziynetler ve dünya hayatında mallar verdin. Rabbimiz! Senin yolundan şaşırtmaları için mi? Rabbimiz! Mallarını yok et, kalblerini sık; çünkü onlar can yakıcı azabı görmedikçe inanmazlar" dedi.'),
  ('tr.diyanet', 10, 89, 'Allah: "İkinizin duası kabul olundu. Dürüst hareket edin; bilmeyenlerin yoluna asla uymayın" dedi.'),
  ('tr.diyanet', 10, 90, 'İsrailoğullarını denizden geçirdik, Firavun ve askerleri haksızlık ve düşmanlıkla ardlarına düştüler. Firavun boğulacağı anda: "İsrailoğullarının inandığından başka tanrı olmadığına inandım, artık ben O\'na teslim olanlardanım" dedi.'),
  ('tr.diyanet', 10, 91, 'O\'na: "Şimdi mi inandın? Daha önce baş kaldırmış ve bozgunculuk etmiştin" dendi.'),
  ('tr.diyanet', 10, 92, '"Senden sonrakilere bir ibret teşkil etmesi için bugün sadece senin cesedini çıkarıp (sahile) atacağız" dedik. Doğrusu insanların çoğu ayetlerimizden habersizdir.'),
  ('tr.diyanet', 10, 93, 'And olsun ki, İsrailoğullarını iyi bir yere yerleştirdik, onlara temiz rızıklar verdik, kendilerine bir bilgi gelene kadar ayrılığa düşmediler.'),
  ('tr.diyanet', 10, 94, 'Sana indirdiğimizden şüphede isen, senden önce indirdiğimiz Kitap\'ları okuyanlara sor. And olsun ki, sana Rabbinden gerçek gelmiştir, sakın şüphelenenlerden olma.'),
  ('tr.diyanet', 10, 95, 'Allah\'ın ayetlerini yalanlayanlardan da olma, yoksa kaybedenlerden olursun.'),
  ('tr.diyanet', 10, 96, 'Doğrusu Rabbinin söz verdiği azabı hak edenler, can yakıcı azabı görene kadar kendilerine her türlü belge gelse bile inanmazlar.'),
  ('tr.diyanet', 10, 97, 'Doğrusu Rabbinin söz verdiği azabı hak edenler, can yakıcı azabı görene kadar kendilerine her türlü belge gelse bile inanmazlar.'),
  ('tr.diyanet', 10, 98, 'Bir kent halkı inanmalı değil miydi ki, imanları kendilerine fayda versin! İşte Yunus\'un milleti, inandığı zaman, dünya hayatında rezilliği gerektiren azabı onlardan kaldırdık ve onları bir süre daha bu dünyada geçindirdik.'),
  ('tr.diyanet', 10, 99, 'Rabbin dileseydi, yeryüzünde bulunanların hepsi inanırdı. Öyle iken insanları inanmaya sen mi zorlayacaksın?'),
  ('tr.diyanet', 10, 100, 'Allah\'ın izni olmadıkça hiç kimse inanamaz. O, aklını kullanmayanlara kötü bir azab verir.'),
  ('tr.diyanet', 10, 101, '"Göklerde ve yerde neler var, bir bakın" de. İnanmayacak bir millete ayetler ve uyarmalar fayda vermez.'),
  ('tr.diyanet', 10, 102, 'Kendilerinden önce geçenlerin başlarına gelen olaylardan başka bir şey mi bekliyorlar? "Bekleyin, ben de sizinle beraber beklemekteyim" de.'),
  ('tr.diyanet', 10, 103, 'Sonra Biz, peygamberlerimizi ve inananları böylece kurtarırız, inananları (verdiğimiz söz gereğince) kurtarmamız Bize haktır.'),
  ('tr.diyanet', 10, 104, 'De ki: "Ey insanlar! Benim dinimden şüphede iseniz bilin ki ben Allah\'tan başka taptıklarınıza tapmam. Ancak, sizi öldürecek olan Allah\'a kulluk ederim. İnananlardan olmakla emrolundum."'),
  ('tr.diyanet', 10, 105, '(Muhammed\'e) "Yüzünü, doğruya yönelmiş olarak dine çevir, sakın ortak koşanlardan olma; sana fayda da zarar da veremeyecek, Allah\'tan başkasına yalvarma; öyle yaparsan şüphesiz, zalimlerden olursun" denildi.'),
  ('tr.diyanet', 10, 106, '(Muhammed\'e) "Yüzünü, doğruya yönelmiş olarak dine çevir, sakın ortak koşanlardan olma; sana fayda da zarar da veremeyecek, Allah\'tan başkasına yalvarma; öyle yaparsan şüphesiz, zalimlerden olursun" denildi.'),
  ('tr.diyanet', 10, 107, 'Allah sana bir sıkıntı verirse, onu O\'ndan başkası gideremez. Sana bir iyilik dilerse O\'nun nimetini engelleyecek yoktur. O\'nu kullarından dilediğine verir. O, bağışlayandır, merhametlidir.'),
  ('tr.diyanet', 10, 108, 'De ki: "Ey insanlar! Rabbinizden size gerçek gelmiştir. Doğru yola giren ancak kendisi için girmiş ve sapıtan da kendi zararına olarak sapıtmıştır. Ben sizin üzerinize vekil değilim."'),
  ('tr.diyanet', 10, 109, 'Sana vahyedilene uy; Allah hükmünü verene kadar sabret. O, hüküm verenlerin en iyisidir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 10, 1, 'Alif laam raa. Inilah ayat-ayat Al Quran yang mengandung hikmah.'),
  ('id.indonesian', 10, 2, 'Patutkah menjadi keheranan bagi manusia bahwa Kami mewahyukan kepada seorang laki-laki di antara mereka: "Berilah peringatan kepada manusia dan gembirakanlah orang-orang beriman bahwa mereka mempunyai kedudukan yang tinggi di sisi Tuhan mereka". Orang-orang kafir berkata: "Sesungguhnya orang ini (Muhammad) benar-benar adalah tukang sihir yang nyata".'),
  ('id.indonesian', 10, 3, 'Sesungguhnya Tuhan kamu ialah Allah Yang menciptakan langit dan bumi dalam enam masa, kemudian Dia bersemayam di atas \'Arsy untuk mengatur segala urusan. Tiada seorangpun yang akan memberi syafa\'at kecuali sesudah ada izin-Nya. (Dzat) yang demikian itulah Allah, Tuhan kamu, maka sembahlah Dia. Maka apakah kamu tidak mengambil pelajaran?'),
  ('id.indonesian', 10, 4, 'Hanya kepada-Nya-lah kamu semuanya akan kembali; sebagai janji yang benar daripada Allah, sesungguhnya Allah menciptakan makhluk pada permulaannya kemudian mengulanginya (menghidupkannya) kembali (sesudah berbangkit), agar Dia memberi pembalasan kepada orang-orang yang beriman dan yang mengerjakan amal saleh dengan adil. Dan untuk orang-orang kafir disediakan minuman air yang panas dan azab yang pedih disebabkan kekafiran mereka.'),
  ('id.indonesian', 10, 5, 'Dialah yang menjadikan matahari bersinar dan bulan bercahaya dan ditetapkan-Nya manzilah-manzilah (tempat-tempat) bagi perjalanan bulan itu, supaya kamu mengetahui bilangan tahun dan perhitungan (waktu). Allah tidak menciptakan yang demikian itu melainkan dengan hak. Dia menjelaskan tanda-tanda (kebesaran-Nya) kepada orang-orang yang mengetahui.'),
  ('id.indonesian', 10, 6, 'Sesungguhnya pada pertukaran malam dan siang itu dan pada apa yang diciptakan Allah di langit dan di bumi, benar-benar terdapat tanda-tanda (kekuasaan-Nya) bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 10, 7, 'Sesungguhnya orang-orang yang tidak mengharapkan (tidak percaya akan) pertemuan dengan Kami, dan merasa puas dengan kehidupan dunia serta merasa tenteram dengan kehidupan itu dan orang-orang yang melalaikan ayat-ayat Kami,'),
  ('id.indonesian', 10, 8, 'mereka itu tempatnya ialah neraka, disebabkan apa yang selalu mereka kerjakan.'),
  ('id.indonesian', 10, 9, 'Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh, mereka diberi petunjuk oleh Tuhan mereka karena keimanannya, di bawah mereka mengalir sungai-sungai di dalam surga yang penuh kenikmatan.'),
  ('id.indonesian', 10, 10, 'Do\'a mereka di dalamnya ialah: "Subhanakallahumma", dan salam penghormatan mereka ialah: "Salam". Dan penutup doa mereka ialah: "Alhamdulilaahi Rabbil \'aalamin".'),
  ('id.indonesian', 10, 11, 'Dan kalau sekiranya Allah menyegerakan kejahatan bagi manusia seperti permintaan mereka untuk menyegerakan kebaikan, pastilah diakhiri umur mereka. Maka Kami biarkan orang-orang yang tidak mengharapkan pertemuan dengan Kami, bergelimangan di dalam kesesatan mereka.'),
  ('id.indonesian', 10, 12, 'Dan apabila manusia ditimpa bahaya dia berdoa kepada Kami dalam keadaan berbaring, duduk atau berdiri, tetapi setelah Kami hilangkan bahaya itu daripadanya, dia (kembali) melalui (jalannya yang sesat), seolah-olah dia tidak pernah berdoa kepada Kami untuk (menghilangkan) bahaya yang telah menimpanya. Begitulah orang-orang yang melampaui batas itu memandang baik apa yang selalu mereka kerjakan.'),
  ('id.indonesian', 10, 13, 'Dan sesungguhnya Kami telah membinasakan umat-umat sebelum kamu, ketika mereka berbuat kezaliman, padahal rasul-rasul mereka telah datang kepada mereka dengan membawa keterangan-keterangan yang nyata, tetapi mereka sekali-kali tidak hendak beriman. Demikianlah Kami memberi pembalasan kepada orang-orang yang berbuat dosa.'),
  ('id.indonesian', 10, 14, 'Kemudian Kami jadikan kamu pengganti-pengganti (mereka) di muka bumi sesudah mereka, supaya Kami memperhatikan bagaimana kamu berbuat.'),
  ('id.indonesian', 10, 15, 'Dan apabila dibacakan kepada mereka ayat-ayat Kami yang nyata, orang-orang yang tidak mengharapkan pertemuan dengan Kami berkata: "Datangkanlah Al Quran yang lain dari ini atau gantilah dia". Katakanlah: "Tidaklah patut bagiku menggantinya dari pihak diriku sendiri. Aku tidak mengikut kecuali apa yang diwahyukan kepadaku. Sesungguhnya aku takut jika mendurhakai Tuhanku kepada siksa hari yang besar (kiamat)".'),
  ('id.indonesian', 10, 16, 'Katakanlah: "Jikalau Allah menghendaki, niscaya aku tidak membacakannya kepadamu dan Allah tidak (pula) memberitahukannya kepadamu". Sesungguhnya aku telah tinggal bersamamu beberapa lama sebelumnya. Maka apakah kamu tidak memikirkannya?'),
  ('id.indonesian', 10, 17, 'Maka siapakah yang lebih zalim daripada orang yang mengada-adakan kedustaan terhadap Allah atau mendustakan ayat-ayat-Nya? Sesungguhnya, tiadalah beruntung orang-orang yang berbuat dosa.'),
  ('id.indonesian', 10, 18, 'Dan mereka menyembah selain daripada Allah apa yang tidak dapat mendatangkan kemudharatan kepada mereka dan tidak (pula) kemanfaatan, dan mereka berkata: "Mereka itu adalah pemberi syafa\'at kepada kami di sisi Allah". Katakanlah: "Apakah kamu mengabarkan kepada Allah apa yang tidak diketahui-Nya baik di langit dan tidak (pula) dibumi?" Maha Suci Allah dan Maha Tinggi dan apa yang mereka mempersekutukan (itu).'),
  ('id.indonesian', 10, 19, 'Manusia dahulunya hanyalah satu umat, kemudian mereka berselisih. Kalau tidaklah karena suatu ketetapan yang telah ada dari Tuhanmu dahulu, pastilah telah diberi keputusan di antara mereka, tentang apa yang mereka perselisihkan itu.'),
  ('id.indonesian', 10, 20, 'Dan mereka berkata: "Mepada tidak diturunkan kepadanya (Muhammad) suatu keterangan (mukjizat) dari Tuhannya?" Maka katakanlah: "Sesungguhnya yang ghaib itu kepunyaan Allah, sebab itu tunggu (sajalah) olehmu, sesungguhnya aku bersama kamu termasuk orang-orang yang manunggu.'),
  ('id.indonesian', 10, 21, 'Dan apabila Kami merasakan kepada manusia suatu rahmat, sesudah (datangnya) bahaya menimpa mereka, tiba-tiba mereka mempunyai tipu daya dalam (menentang) tanda-tanda kekuasaan Kami. Katakanlah: "Allah lebih cepat pembalasannya (atas tipu daya itu)". Sesungguhnya malaikat-malaikat Kami menuliskan tipu dayamu.'),
  ('id.indonesian', 10, 22, 'Dialah Tuhan yang menjadikan kamu dapat berjalan di daratan, (berlayar) di lautan. Sehingga apabila kamu berada di dalam bahtera, dan meluncurlah bahtera itu membawa orang-orang yang ada di dalamnya dengan tiupan angin yang baik, dan mereka bergembira karenanya, datanglah angin badai, dan (apabila) gelombang dari segenap penjuru menimpanya, dan mereka yakin bahwa mereka telah terkepung (bahaya), maka mereka berdoa kepada Allah dengan mengikhlaskan ketaatan kepada-Nya semata-mata. (Mereka berkata): "Sesungguhnya jika Engkau menyelamatkan kami dari bahaya ini, pastilah kami akan termasuk orang-orang yang bersyukur".'),
  ('id.indonesian', 10, 23, 'Maka tatkala Allah menyelamatkan mereka, tiba-tiba mereka membuat kezaliman di muka bumi tanpa (alasan) yang benar. Hai manusia, sesungguhnya (bencana) kezalimanmu akan menimpa dirimu sendiri; (hasil kezalimanmu) itu hanyalah kenikmatan hidup duniawi, kemudian kepada Kami-lah kembalimu, lalu Kami kabarkan kepadamu apa yang telah kamu kerjakan.'),
  ('id.indonesian', 10, 24, 'Sesungguhnya perumpamaan kehidupan duniawi itu, adalah seperti air (hujan) yang Kami turunkan dan langit, lalu tumbuhlah dengan suburnya karena air itu tanam-tanaman bumi, di antaranya ada yang dimakan manusia dan binatang ternak. Hingga apabila bumi itu telah sempurna keindahannya, dan memakai (pula) perhiasannya, dan pemilik-permliknya mengira bahwa mereka pasti menguasasinya, tiba-tiba datanglah kepadanya azab Kami di waktu malam atau siang, lalu Kami jadikan (tanam-tanamannya) laksana tanam-tanaman yang sudah disabit, seakan-akan belum pernah tumbuh kemarin. Demikianlah Kami menjelaskan tanda-tanda kekuasaan (Kami) kepada orang-orang berfikir.'),
  ('id.indonesian', 10, 25, 'Allah menyeru (manusia) ke Darussalam (surga), dan menunjuki orang yang dikehendaki-Nya kepada jalan yang lurus (Islam).'),
  ('id.indonesian', 10, 26, 'Bagi orang-orang yang berbuat baik, ada pahala yang terbaik (surga) dan tambahannya. Dan muka mereka tidak ditutupi debu hitam dan tidak (pula) kehinaan. Mereka itulah penghuni surga, mereka kekal di dalamnya.'),
  ('id.indonesian', 10, 27, 'Dan orang-orang yang mengerjakan kejahatan (mendapat) balasan yang setimpal dan mereka ditutupi kehinaan. Tidak ada bagi mereka seorang pelindungpun dari (azab) Allah, seakan-akan muka mereka ditutupi dengan kepingan-kepingan malam yang gelap gelita. Mereka itulah penghuni neraka; mereka kekal di dalamnya.'),
  ('id.indonesian', 10, 28, '(Ingatlah) suatu hari (ketika itu). Kami mengumpulkan mereka semuanya, kemudian Kami berkata kepada orang-orang yang mempersekutukan (Tuhan): "Tetaplah kamu dan sekutu-sekutumu di tempatmu itu". Lalu Kami pisahkan mereka dan berkatalah sekutu-sekutu mereka: "Kamu sekali-kali tidak pernah menyembah kami.'),
  ('id.indonesian', 10, 29, 'Dan cukuplah Allah menjadi saksi antara kami dengan kamu, bahwa kami tidak tahu-menahu tentang penyembahan kamu (kepada kami).'),
  ('id.indonesian', 10, 30, 'Di tempat itu (padang Mahsyar), tiap-tiap diri merasakan pembalasan dari apa yang telah dikerjakannya dahulu dan mereka dikembalikan kepada Allah Pelindung mereka yang sebenarnya dan lenyaplah dari mereka apa yang mereka ada-adakan.'),
  ('id.indonesian', 10, 31, 'Katakanlah: "Siapakah yang memberi rezeki kepadamu dari langit dan bumi, atau siapakah yang kuasa (menciptakan) pendengaran dan penglihatan, dan siapakah yang mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup dan siapakah yang mengatur segala urusan?" Maka mereka akan menjawab: "Allah". Maka katakanlah "Mangapa kamu tidak bertakwa kepada-Nya)?"'),
  ('id.indonesian', 10, 32, 'Maka (Zat yang demikian) itulah Allah Tuhan kamu yang sebenarnya; maka tidak ada sesudah kebenaran itu, melainkan kesesatan. Maka bagaimanakah kamu dipalingkan (dari kebenaran)?'),
  ('id.indonesian', 10, 33, 'Demikianlah telah tetap hukuman Tuhanmu terhadap orang-orang yang fasik, karena sesungguhnya mereka tidak beriman.'),
  ('id.indonesian', 10, 34, 'Katakanlah: "Apakah di antara sekutu-sekutumu ada yang dapat memulai penciptaan makhluk, kemudian mengulanginya (menghidupkannya) kembali?" katakanlah: "Allah-lah yang memulai penciptaan makhluk, kemudian mengulanginya (menghidupkannya) kembali; maka bagaimanakah kamu dipalingkan (kepada menyembah yang selain Allah)?"'),
  ('id.indonesian', 10, 35, 'Katakanlah: "Apakah di antara sekutu-sekuturmu ada yang menunjuki kepada kebenaran?" Katakanlah "Allah-lah yang menunjuki kepada kebenaran". Maka apakah orang-orang yang menunjuki kepada kebenaran itu lebih berhak diikuti ataukah orang yang tidak dapat memberi petunjuk kecuali (bila) diberi petunjuk? Mengapa kamu (berbuat demikian)? Bagaimanakah kamu mengambil keputusan?'),
  ('id.indonesian', 10, 36, 'Dan kebanyakan mereka tidak mengikuti kecuali persangkaan saja. Sesungguhnya persangkaan itu tidak sedikitpun berguna untuk mencapai kebenaran. Sesungguhnya Allah Maha Mengetahui apa yang mereka kerjakan.'),
  ('id.indonesian', 10, 37, 'Tidaklah mungkin Al Quran ini dibuat oleh selain Allah; akan tetapi (Al Quran itu) membenarkan kitab-kitab yang sebelumnya dan menjelaskan hukum-hukum yang telah ditetapkannya, tidak ada keraguan di dalamnya, (diturunkan) dari Tuhan semesta alam.'),
  ('id.indonesian', 10, 38, 'Atau (patutkah) mereka mengatakan "Muhammad membuat-buatnya". Katakanlah: "(Kalau benar yang kamu katakan itu), maka cobalah datangkan sebuah surat seumpamanya dan panggillah siapa-siapa yang dapat kamu panggil (untuk membuatnya) selain Allah, jika kamu orang yang benar".'),
  ('id.indonesian', 10, 39, 'Bahkan yang sebenarnya, mereka mendustakan apa yang mereka belum mengetahuinya dengan sempurna padahal belum datang kepada mereka penjelasannya. Demikianlah orang-orang yang sebelum mereka telah mendustakan (rasul). Maka perhatikanlah bagaimana akibat orang-orang yang zalim itu.'),
  ('id.indonesian', 10, 40, 'Di antara mereka ada orang-orang yang beriman kepada Al Quran, dan di antaranya ada (pula) orang-orang yang tidak beriman kepadanya. Tuhanmu lebih mengetahui tentang orang-orang yang berbuat kerusakan.'),
  ('id.indonesian', 10, 41, 'Jika mereka mendustakan kamu, maka katakanlah: "Bagiku pekerjaanku dan bagimu pekerjaanmu. Kamu berlepas diri terhadap apa yang aku kerjakan dan akupun berlepas diri terhadap apa yang kamu kerjakan".'),
  ('id.indonesian', 10, 42, 'Dan di antara mereka ada orang yang mendengarkanmu. Apakah kamu dapat menjadikan orang-orang tuli itu mendengar walaupun mereka tidak mengerti.'),
  ('id.indonesian', 10, 43, 'Dan di antara mereka ada orang yang melihat kepadamu, apakah dapat kamu memberi petunjuk kepada orang-orang yang buta, walaupun mereka tidak dapat memperhatikan.'),
  ('id.indonesian', 10, 44, 'Sesungguhnya Allah tidak berbuat zalim kepada manusia sedikitpun, akan tetapi manusia itulah yang berbuat zalim kepada diri mereka sendiri.'),
  ('id.indonesian', 10, 45, 'Dan (ingatlah) akan hari (yang di waktu itu) Allah mengumpulkan mereka, (mereka merasa di hari itu) seakan-akan mereka tidak pernah berdiam (di dunia) hanya sesaat di siang hari, (di waktu itu) mereka saling berkenalan. Sesungguhnya rugilah orang-orang yang mendustakan pertemuan mereka dengan Allah dan mereka tidak mendapat petunjuk'),
  ('id.indonesian', 10, 46, 'Dan jika Kami perlihatkan kepadamu sebahagian dari (siksa) yang Kami ancamkan kepada mereka, (tentulah kamu akan melihatnya) atau (jika) Kami wafatkan kamu (sebelum itu), maka kepada Kami jualah mereka kembali, dan Allah menjadi saksi atas apa yang mereka kerjakan.'),
  ('id.indonesian', 10, 47, 'Tiap-tiap umat mempunyai rasul; maka apabila telah datang rasul mereka, diberikanlah keputusan antara mereka dengan adil dan mereka (sedikitpun) tidak dianiaya.'),
  ('id.indonesian', 10, 48, 'Mereka mengatakan: "Bilakah (datangnya) ancaman itu, jika memang kamu orang-orang yang benar?"'),
  ('id.indonesian', 10, 49, 'Katakanlah: "Aku tidak berkuasa mendatangkan kemudharatan dan tidak (pula) kemanfaatan kepada diriku, melainkan apa yang dikehendaki Allah". Tiap-tiap umat mempunyai ajal. Apabila telah datang ajal mereka, maka mereka tidak dapat mengundurkannya barang sesaatpun dan tidak (pula) mendahulukan(nya).'),
  ('id.indonesian', 10, 50, 'Katakanlah: "Terangkan kepadaku, jika datang kepada kamu sekalian sikaaan-Nya di waktu malam atau di siang hari, apakah orang-orang yang berdosa itu meminta disegerakan juga?"'),
  ('id.indonesian', 10, 51, 'Kemudian apakah setelah terjadinya (azab itu), kemudian itu kamu baru mempercayainya? Apakah sekarang (baru kamu mempercayai), padahal sebelumnya kamu selalu meminta supaya disegerakan?'),
  ('id.indonesian', 10, 52, 'Kemudian dikatakan kepada orang-orang yang zalim (musyrik) itu: "Rasakanlah olehmu siksaan yang kekal; kamu tidak diberi balasan melainkan dengan apa yang telah kamu kerjakan".'),
  ('id.indonesian', 10, 53, 'Dan mereka menanyakan kepadamu: "Benarkah (azab yang dijanjikan) itu? Katakanlah: "Ya, demi Tuhanku, sesungguhnya azab itu adalah benar dan kamu sekali-kali tidak bisa luput (daripadanya)".'),
  ('id.indonesian', 10, 54, 'Dan kalau setiap diri yang zalim (muayrik) itu mempunyai segala apa yang ada di bumi ini, tentu dia menebus dirinya dengan itu, dan mereka membunyikan penyesalannya ketika mereka telah menyaksikan azab itu. Dan telah diberi keputusan di antara mereka dengan adil, sedang mereka tidak dianiaya.'),
  ('id.indonesian', 10, 55, 'Ingatlah, sesungguhnya kepunyaan Allah apa yang ada di langit dan di bumi. Ingatlah, sesungguhnya janji Allah itu benar, tetapi kebanyakan mereka tidak mengetahui(nya).'),
  ('id.indonesian', 10, 56, 'Dialah yang menghidupkan dan mematikan dan hanya kepada-Nya-lah kamu dikembalikan.'),
  ('id.indonesian', 10, 57, 'Hai manusia, sesungguhnya telah datang kepadamu pelajaran dari Tuhanmu dan penyembuh bagi penyakit-penyakit (yang berada) dalam dada dan petunjuk serta rahmat bagi orang-orang yang beriman.'),
  ('id.indonesian', 10, 58, 'Katakanlah: "Dengan kurnia Allah dan rahmat-Nya, hendaklah dengan itu mereka bergembira. Kurnia Allah dan rahmat-Nya itu adalah lebih baik dari apa yang mereka kumpulkan".'),
  ('id.indonesian', 10, 59, 'Katakanlah: "Terangkanlah kepadaku tentang rezeki yang diturunkan Allah kepadamu, lalu kamu jadikan sebagiannya haram dan (sebagiannya) halal". Katakanlah: "Apakah Allah telah memberikan izin kepadamu (tentang ini) atau kamu mengada-adakan saja terhadap Allah?"'),
  ('id.indonesian', 10, 60, 'Apakah dugaan orang-orang yang mengada-adakan kebohongan terhadap Allah pada hari kiamat? Sesungguhnya Allah benar-benar mempunyai karunia (yang dilimpahkan) atas manusia, tetapi kebanyakan mereka tidak mensyukuri(nya).'),
  ('id.indonesian', 10, 61, 'Kamu tidak berada dalam suatu keadaan dan tidak membaca suatu ayat dari Al Quran dan kamu tidak mengerjakan suatu pekerjaan, melainkan Kami menjadi saksi atasmu di waktu kamu melakukannya. Tidak luput dari pengetahuan Tuhanmu biarpun sebesar zarrah (atom) di bumi ataupun di langit. Tidak ada yang lebih kecil dan tidak (pula) yang lebih besar dari itu, melainkan (semua tercatat) dalam kitab yang nyata (Lauh Mahfuzh).'),
  ('id.indonesian', 10, 62, 'Ingatlah, sesungguhnya wali-wali Allah itu, tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.'),
  ('id.indonesian', 10, 63, '(Yaitu) orang-orang yang beriman dan mereka selalu bertakwa.'),
  ('id.indonesian', 10, 64, 'Bagi mereka berita gembira di dalam kehidupan di dunia dan (dalam kehidupan} di akhirat. Tidak ada perubahan bagi kalimat-kalimat (janji-janji) Allah. Yang demikian itu adalah kemenangan yang besar.'),
  ('id.indonesian', 10, 65, 'Janganlah kamu sedih oleh perkataan mereka. Sesungguhnya kekuasaan itu seluruhnya adalah kepunyaan Allah. Dialah Yang Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 10, 66, 'Ingatlah, sesungguhnya kepunyaan Allah semua yang ada di langit dan semua yang ada di bumi. Dan orang-orang yang menyeru sekutu-sekutu selain Allah, tidaklah mengikuti (suatu keyakinan). Mereka tidak mengikuti kecuali prasangka belaka, dan mereka hanyalah menduga-duga.'),
  ('id.indonesian', 10, 67, 'Dialah yang menjadikan malam bagi kamu supaya kamu beristirahat padanya dan (menjadikan) siang terang benderang (supaya kamu mencari karunia Allah). Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang mendengar.'),
  ('id.indonesian', 10, 68, 'Mereka (orang-orang Yahudi dan Nasrani) berkata: "Allah mempuyai anak". Maha Suci Allah; Dialah Yang Maha Kaya; kepunyaan-Nya apa yang ada di langit dan apa yang di bumi. Kamu tidak mempunyai hujjah tentang ini. Pantaskah kamu mengatakan terhadap Allah apa yang tidak kamu ketahui?'),
  ('id.indonesian', 10, 69, 'Katakanlah: "Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah tidak beruntung".'),
  ('id.indonesian', 10, 70, '(Bagi mereka) kesenangan (sementara) di dunia, kemudian kepada Kami-lah mereka kembali, kemudian Kami rasakan kepada mereka siksa yang berat, disebabkan kekafiran mereka.'),
  ('id.indonesian', 10, 71, 'Dan bacakanIah kepada mereka berita penting tentang Nuh di waktu dia berkata kepada kaumnya: "Hai kaumku, jika terasa berat bagimu tinggal (bersamaku) dan peringatanku (kepadamu) dengan ayat-ayat Allah, maka kepada Allah-lah aku bertawakal, karena itu bulatkanlah keputusanmu dan (kumpulkanlah) sekutu-sekutumu (untuk membinasakanku). Kemudian janganlah keputusanmu itu dirahasiakan, lalu lakukanlah terhadap diriku, dan janganlah kamu memberi tangguh kepadaku.'),
  ('id.indonesian', 10, 72, 'Jika kamu berpaling (dari peringatanku), aku tidak meminta upah sedikitpun dari padamu. Upahku tidak lain hanyalah dari Allah belaka, dan aku disuruh supaya aku termasuk golongan orang-orang yang berserah diri (kepada-Nya)".'),
  ('id.indonesian', 10, 73, 'Lalu mereka mendustakan Nuh, maka Kami selamatkan dia dan orang-orang yang bersamanya di dalam bahtera, dan Kami jadikan mereka itu pemegang kekuasaan dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami. Maka perhatikanlah bagaimana kesesudahan orang-orang yang diberi peringatan itu.'),
  ('id.indonesian', 10, 74, 'Kemudian sesudah Nuh, Kami utus beberapa rasul kepada kaum mereka (masing-masing), maka rasul-rasul itu datang kepada mereka dengan membawa keterangan-keterangan yang nyata, tetapi mereka tidak hendak beriman karena mereka dahulu telah (biasa) mendustakannya. Demikianlah Kami mengunci mati hati orang-orang yang melampaui batas.'),
  ('id.indonesian', 10, 75, 'Kemudian sesudah rasul-rasul itu, Kami utus Musa dan Harun kepada Fir\'aun dan pemuka-pemuka kaumnya, dengan (membawa) tanda-tanda (mukjizat-mukjizat) Kami, maka mereka menyombongkan diri dan mereka adalah orang-orang yang berdosa.'),
  ('id.indonesian', 10, 76, 'Dan tatkala telah datang kepada mereka kebenaran dari sisi Kami, mereka berkata: "Sesungguhnya ini adalah sihir yang nyata".'),
  ('id.indonesian', 10, 77, 'Musa berkata: "Apakah kamu mengatakan terhadap kebenaran waktu ia datang kepadamu, sihirkah ini?" padahal ahli-ahli sihir itu tidaklah mendapat kemenangan".'),
  ('id.indonesian', 10, 78, 'Mereka berkata: "Apakah kamu datang kepada kami untuk memalingkan kami dari apa yang kami dapati nenek moyang kami mengerjakannya, dan supaya kamu berdua mempunyai kekuasaan di muka bumi? Kami tidak akan mempercayai kamu berdua".'),
  ('id.indonesian', 10, 79, 'Fir\'aun berkata (kepada pemuka kaumnya): "Datangkanlah kepadaku semua ahli-ahli sihir yang pandai!"'),
  ('id.indonesian', 10, 80, 'Maka tatkala ahli-ahli sihir itu datang, Musa berkata kepada mereka: "Lemparkanlah apa yang hendak kamu lemparkan".'),
  ('id.indonesian', 10, 81, 'Maka setelah mereka lemparkan, Musa berkata: "Apa yang kamu lakukan itu, itulah yang sihir, sesungguhnya Allah akan menampakkan ketidak benarannya" Sesungguhnya Allah tidak akan membiarkan terus berlangsungnya pekerjaan orang-yang membuat kerusakan.'),
  ('id.indonesian', 10, 82, 'Dan Allah akan mengokohkan yang benar dengan ketetapan-Nya, walaupun orang-orang yang berbuat dosa tidak menyukai(nya).'),
  ('id.indonesian', 10, 83, 'Maka tidak ada yang beriman kepada Musa, melainkan pemuda-pemuda dari kaumnya (Musa) dalam keadaan takut bahwa Fir\'aun dan pemuka-pemuka kaumnya akan menyiksa mereka. Sesungguhnya Fir\'aun itu berbuat sewenang-wenang di muka bumi. Dan sesungguhnya dia termasuk orang-orang yang melampaui batas.'),
  ('id.indonesian', 10, 84, 'Berkata Musa: "Hai kaumku, jika kamu beriman kepada Allah, maka bertawakkallah kepada-Nya saja, jika kamu benar-benar orang yang berserah diri".'),
  ('id.indonesian', 10, 85, 'Lalu mereka berkata: "Kepada Allahlah kami bertawakkal! Ya Tuhan kami; janganlah Engkau jadikan kami sasaran fitnah bagi kaum yang\'zalim,'),
  ('id.indonesian', 10, 86, 'dan selamatkanlah kami dengan rahmat Engkau dari (tipu daya) orang-orang yang kafir".'),
  ('id.indonesian', 10, 87, 'Dan Kami wahyukan kepada Musa dan saudaranya: "Ambillah olehmu berdua beberapa buah rumah di Mesir untuk tempat tinggal bagi kaummu dan jadikanlah olehmu rumah-rumahmu itu tempat shalat dan dirikanlah olehmu sembahyang serta gembirakanlah orang-orang yang beriman".'),
  ('id.indonesian', 10, 88, 'Musa berkata: "Ya Tuhan kami, sesungguhnya Engkau telah memberi kepada Fir\'aun dan pemuka-pemuka kaumnya perhiasan dan harta kekayaan dalam kehidupan dunia, ya Tuhan Kami -- akibatnya mereka menyesatkan (manusia) dari jalan Engkau. Ya Tuhan kami, binasakanlah harta benda mereka, dan kunci matilah hati mereka, maka mereka tidak beriman hingga mereka melihat siksaan yang pedih".'),
  ('id.indonesian', 10, 89, 'AlIah berfirman: "Sesungguhnya telah diperkenankan permohonan kamu berdua, sebab itu tetaplah kamu berdua pada jalan yang lurus dan janganlah sekali-kali kamu mengikuti jalan orang-orang yang tidak mengetahui".'),
  ('id.indonesian', 10, 90, 'Dan Kami memungkinkan Bani Israil melintasi laut, lalu mereka diikuti oleh Fir\'aun dan bala tentaranya, karena hendak menganiaya dan menindas (mereka); hingga bila Fir\'aun itu telah hampir tenggelam berkatalah dia: "Saya percaya bahwa tidak ada Tuhan melainkan Tuhan yang dipercayai oleh Bani Israil, dan saya termasuk orang-orang yang berserah diri (kepada Allah)".'),
  ('id.indonesian', 10, 91, 'Apakah sekarang (baru kamu percaya), padahal sesungguhnya kamu telah durhaka sejak dahulu, dan kamu termasuk orang-orang yang berbuat kerusakan.'),
  ('id.indonesian', 10, 92, 'Maka pada hari ini Kami selamatkan badanmu supaya kamu dapat menjadi pelajaran bagi orang-orang yang datang sesudahmu dan sesungguhnya kebanyakan dari manusia lengah dari tanda-tanda kekuasaan Kami.'),
  ('id.indonesian', 10, 93, 'Dan sesungguhnya Kami telah menempatkan Bani Israil di ternpat kediaman yang bagus dan Kami beri mereka rezeki dari yang baik-baik. Maka mereka tidak berselisih, kecuali setelah datang kepada mereka pengetahuan (yang tersebut dalam Taurat). Sesungguhnya Tuhan kamu akan memutuskan antara mereka di hari kiamat tentang apa yang mereka perselisihkan itu.'),
  ('id.indonesian', 10, 94, 'Maka jika kamu (Muhammad) berada dalam keragu-raguan tentang apa yang Kami turunkan kepadamu, maka tanyakanlah kepada orang-orang yang membaca kitab sebelum kamu. Sesungguhnya telah datang kebenaran kepadamu dari Tuhanmu, sebab itu janganlah sekali-kali kamu temasuk orang-orang yang ragu-ragu.'),
  ('id.indonesian', 10, 95, 'Dan sekali-kali janganlah kamu termasuk orang-orang yang mendustakan ayat-ayat Allah yang menyebabkan kamu termasuk orang-orang yang rugi.'),
  ('id.indonesian', 10, 96, 'Sesungguhnya orang-orang yang telah pasti terhadap mereka kalimat Tuhanmu, tidaklah akan beriman,'),
  ('id.indonesian', 10, 97, 'meskipun datang kepada mereka segala macam keterangan, hingga mereka menyaksikan azab yang pedih.'),
  ('id.indonesian', 10, 98, 'Dan mengapa tidak ada (penduduk) suatu kota yang beriman, lalu imannya itu bermanfaat kepadanya selain kaum Yunus? Tatkala mereka (kaum Yunus itu), beriman, Kami hilangkan dari mereka azab yang menghinakan dalam kehidupan dunia, dan Kami beri kesenangan kepada mereka sampai kepada waktu yang tertentu.'),
  ('id.indonesian', 10, 99, 'Dan jikalau Tuhanmu menghendaki, tentulah beriman semua orang yang di muka bumi seluruhnya. Maka apakah kamu (hendak) memaksa manusia supaya mereka menjadi orang-orang yang beriman semuanya?'),
  ('id.indonesian', 10, 100, 'Dan tidak ada seorangpun akan beriman kecuali dengan izin Allah; dan Allah menimpakan kemurkaan kepada orang-orang yang tidak mempergunakan akalnya.'),
  ('id.indonesian', 10, 101, 'Katakanlah: "Perhatikanlah apa yaag ada di langit dan di bumi. Tidaklah bermanfaat tanda kekuasaan Allah dan rasul-rasul yang memberi peringatan bagi orang-orang yang tidak beriman".'),
  ('id.indonesian', 10, 102, 'Mereka tidak menunggu-nunggu kecuali (kejadian-kejadian) yang sama dengan kejadian-kejadian (yang menimpa) orang-orang yang telah terdahulu sebelum mereka. Katakanlah: "Maka tunggulah, sesungguhnya akupun termasuk orang-orang yang menunggu bersama kamu".'),
  ('id.indonesian', 10, 103, 'Kemudian Kami selamatkan rasul-rasul Kami dan orang-orang yang beriman, demikianlah menjadi kewajiban atas Kami menyelamatkan orang-orang yang beriman.'),
  ('id.indonesian', 10, 104, 'Katakanlah: "Hai manusia, jika kamu masih dalam keragu-raguan tentang agamaku, maka (ketahuilah) aku tidak menyembah yang kamu sembah selain Allah, tetapi aku menyembah Allah yang akan mematikan kamu dan aku telah diperintah supaya termasuk orang-orang yang beriman",'),
  ('id.indonesian', 10, 105, 'dan (aku telah diperintah): "Hadapkanlah mukamu kepada agama dengan tulus dan ikhlas dan janganlah kamu termasuk orang-orang yang musyrik.'),
  ('id.indonesian', 10, 106, 'Dan janganlah kamu menyembah apa-apa yang tidak memberi manfaat dan tidak (pula) memberi mudharat kepadamu selain Allah; sebab jika kamu berbuat (yang demikian), itu, maka sesungguhnya kamu kalau begitu termasuk orang-orang yang zalim".'),
  ('id.indonesian', 10, 107, 'Jika Allah menimpakan sesuatu kemudharatan kepadamu, maka tidak ada yang dapat menghilangkannya kecuali Dia. Dan jika Allah menghendaki kebaikan bagi kamu, maka tak ada yang dapat menolak kurnia-Nya. Dia memberikan kebaikan itu kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya dan Dialah Yang Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 10, 108, 'Katakanlah: "Hai manusia, sesungguhnya teIah datang kepadamu kebenaran (Al Quran) dari Tuhanmu, sebab itu barangsiapa yang mendapat petunjuk maka sesungguhnya (petunjuk itu) untuk kebaikan dirinya sendiri. Dan barangsiapa yang sesat, maka sesungguhnya kesesatannya itu mencelakakan dirinya sendiri. Dan aku bukanlah seorang penjaga terhadap dirimu".'),
  ('id.indonesian', 10, 109, 'Dan ikutilah apa yang diwahyukan kepadamu, dan bersabarlah hingga Allah memberi keputusan dan Dia adalah Hakim yang sebaik-baiknya.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 11, 1, 'Alif, Lam, Ra. [This is] a Book whose verses are perfected and then presented in detail from [one who is] Wise and Acquainted.'),
  ('en.sahih', 11, 2, '[Through a messenger, saying], "Do not worship except Allah. Indeed, I am to you from Him a warner and a bringer of good tidings,"'),
  ('en.sahih', 11, 3, 'And [saying], "Seek forgiveness of your Lord and repent to Him, [and] He will let you enjoy a good provision for a specified term and give every doer of favor his favor. But if you turn away, then indeed, I fear for you the punishment of a great Day.'),
  ('en.sahih', 11, 4, 'To Allah is your return, and He is over all things competent."'),
  ('en.sahih', 11, 5, 'Unquestionably, they the disbelievers turn away their breasts to hide themselves from Him. Unquestionably, [even] when they cover themselves in their clothing, Allah knows what they conceal and what they declare. Indeed, He is Knowing of that within the breasts.'),
  ('en.sahih', 11, 6, 'And there is no creature on earth but that upon Allah is its provision, and He knows its place of dwelling and place of storage. All is in a clear register.'),
  ('en.sahih', 11, 7, 'And it is He who created the heavens and the earth in six days - and His Throne had been upon water - that He might test you as to which of you is best in deed. But if you say, "Indeed, you are resurrected after death," those who disbelieve will surely say, "This is not but obvious magic."'),
  ('en.sahih', 11, 8, 'And if We hold back from them the punishment for a limited time, they will surely say, "What detains it?" Unquestionably, on the Day it comes to them, it will not be averted from them, and they will be enveloped by what they used to ridicule.'),
  ('en.sahih', 11, 9, 'And if We give man a taste of mercy from Us and then We withdraw it from him, indeed, he is despairing and ungrateful.'),
  ('en.sahih', 11, 10, 'But if We give him a taste of favor after hardship has touched him, he will surely say, "Bad times have left me." Indeed, he is exultant and boastful -'),
  ('en.sahih', 11, 11, 'Except for those who are patient and do righteous deeds; those will have forgiveness and great reward.'),
  ('en.sahih', 11, 12, 'Then would you possibly leave [out] some of what is revealed to you, or is your breast constrained by it because they say, "Why has there not been sent down to him a treasure or come with him an angel?" But you are only a warner. And Allah is Disposer of all things.'),
  ('en.sahih', 11, 13, 'Or do they say, "He invented it"? Say, "Then bring ten surahs like it that have been invented and call upon [for assistance] whomever you can besides Allah, if you should be truthful."'),
  ('en.sahih', 11, 14, 'And if they do not respond to you - then know that the Qur\'an was revealed with the knowledge of Allah and that there is no deity except Him. Then, would you [not] be Muslims?'),
  ('en.sahih', 11, 15, 'Whoever desires the life of this world and its adornments - We fully repay them for their deeds therein, and they therein will not be deprived.'),
  ('en.sahih', 11, 16, 'Those are the ones for whom there is not in the Hereafter but the Fire. And lost is what they did therein, and worthless is what they used to do.'),
  ('en.sahih', 11, 17, 'So is one who [stands] upon a clear evidence from his Lord [like the aforementioned]? And a witness from Him follows it, and before it was the Scripture of Moses to lead and as mercy. Those [believers in the former revelations] believe in the Qur\'an. But whoever disbelieves in it from the [various] factions - the Fire is his promised destination. So be not in doubt about it. Indeed, it is the truth from your Lord, but most of the people do not believe.'),
  ('en.sahih', 11, 18, 'And who is more unjust than he who invents a lie about Allah? Those will be presented before their Lord, and the witnesses will say, "These are the ones who lied against their Lord." Unquestionably, the curse of Allah is upon the wrongdoers.'),
  ('en.sahih', 11, 19, 'Who averted [people] from the way of Allah and sought to make it [seem] deviant while they, concerning the Hereafter, were disbelievers.'),
  ('en.sahih', 11, 20, 'Those were not causing failure [to Allah] on earth, nor did they have besides Allah any protectors. For them the punishment will be multiplied. They were not able to hear, nor did they see.'),
  ('en.sahih', 11, 21, 'Those are the ones who will have lost themselves, and lost from them is what they used to invent.'),
  ('en.sahih', 11, 22, 'Assuredly, it is they in the Hereafter who will be the greatest losers.'),
  ('en.sahih', 11, 23, 'Indeed, they who have believed and done righteous deeds and humbled themselves to their Lord - those are the companions of Paradise; they will abide eternally therein.'),
  ('en.sahih', 11, 24, 'The example of the two parties is like the blind and deaf, and the seeing and hearing. Are they equal in comparison? Then, will you not remember?'),
  ('en.sahih', 11, 25, 'And We had certainly sent Noah to his people, [saying], "Indeed, I am to you a clear warner'),
  ('en.sahih', 11, 26, 'That you not worship except Allah. Indeed, I fear for you the punishment of a painful day."'),
  ('en.sahih', 11, 27, 'So the eminent among those who disbelieved from his people said, "We do not see you but as a man like ourselves, and we do not see you followed except by those who are the lowest of us [and] at first suggestion. And we do not see in you over us any merit; rather, we think you are liars."'),
  ('en.sahih', 11, 28, 'He said, "O my people have you considered: if I should be upon clear evidence from my Lord while He has given me mercy from Himself but it has been made unapparent to you, should we force it upon you while you are averse to it?'),
  ('en.sahih', 11, 29, 'And O my people, I ask not of you for it any wealth. My reward is not but from Allah. And I am not one to drive away those who have believed. Indeed, they will meet their Lord, but I see that you are a people behaving ignorantly.'),
  ('en.sahih', 11, 30, 'And O my people, who would protect me from Allah if I drove them away? Then will you not be reminded?'),
  ('en.sahih', 11, 31, 'And I do not tell you that I have the depositories [containing the provision] of Allah or that I know the unseen, nor do I tell you that I am an angel, nor do I say of those upon whom your eyes look down that Allah will never grant them any good. Allah is most knowing of what is within their souls. Indeed, I would then be among the wrongdoers."'),
  ('en.sahih', 11, 32, 'They said, "O Noah, you have disputed us and been frequent in dispute of us. So bring us what you threaten us, if you should be of the truthful."'),
  ('en.sahih', 11, 33, 'He said, "Allah will only bring it to you if He wills, and you will not cause [Him] failure.'),
  ('en.sahih', 11, 34, 'And my advice will not benefit you - although I wished to advise you - If Allah should intend to put you in error. He is your Lord, and to Him you will be returned."'),
  ('en.sahih', 11, 35, 'Or do they say [about Prophet Muhammad], "He invented it"? Say, "If I have invented it, then upon me is [the consequence of] my crime; but I am innocent of what [crimes] you commit."'),
  ('en.sahih', 11, 36, 'And it was revealed to Noah that, "No one will believe from your people except those who have already believed, so do not be distressed by what they have been doing.'),
  ('en.sahih', 11, 37, 'And construct the ship under Our observation and Our inspiration and do not address Me concerning those who have wronged; indeed, they are [to be] drowned."'),
  ('en.sahih', 11, 38, 'And he constructed the ship, and whenever an assembly of the eminent of his people passed by him, they ridiculed him. He said, "If you ridicule us, then we will ridicule you just as you ridicule.'),
  ('en.sahih', 11, 39, 'And you are going to know who will get a punishment that will disgrace him [on earth] and upon whom will descend an enduring punishment [in the Hereafter]."'),
  ('en.sahih', 11, 40, '[So it was], until when Our command came and the oven overflowed, We said, "Load upon the ship of each [creature] two mates and your family, except those about whom the word has preceded, and [include] whoever has believed." But none had believed with him, except a few.'),
  ('en.sahih', 11, 41, 'And [Noah] said, "Embark therein; in the name of Allah is its course and its anchorage. Indeed, my Lord is Forgiving and Merciful."'),
  ('en.sahih', 11, 42, 'And it sailed with them through waves like mountains, and Noah called to his son who was apart [from them], "O my son, come aboard with us and be not with the disbelievers."'),
  ('en.sahih', 11, 43, '[But] he said, "I will take refuge on a mountain to protect me from the water." [Noah] said, "There is no protector today from the decree of Allah, except for whom He gives mercy." And the waves came between them, and he was among the drowned.'),
  ('en.sahih', 11, 44, 'And it was said, "O earth, swallow your water, and O sky, withhold [your rain]." And the water subsided, and the matter was accomplished, and the ship came to rest on the [mountain of] Judiyy. And it was said, "Away with the wrongdoing people."'),
  ('en.sahih', 11, 45, 'And Noah called to his Lord and said, "My Lord, indeed my son is of my family; and indeed, Your promise is true; and You are the most just of judges!"'),
  ('en.sahih', 11, 46, 'He said, "O Noah, indeed he is not of your family; indeed, he is [one whose] work was other than righteous, so ask Me not for that about which you have no knowledge. Indeed, I advise you, lest you be among the ignorant."'),
  ('en.sahih', 11, 47, '[Noah] said, "My Lord, I seek refuge in You from asking that of which I have no knowledge. And unless You forgive me and have mercy upon me, I will be among the losers."'),
  ('en.sahih', 11, 48, 'It was said, "O Noah, disembark in security from Us and blessings upon you and upon nations [descending] from those with you. But other nations [of them] We will grant enjoyment; then there will touch them from Us a painful punishment."'),
  ('en.sahih', 11, 49, 'That is from the news of the unseen which We reveal to you, [O Muhammad]. You knew it not, neither you nor your people, before this. So be patient; indeed, the [best] outcome is for the righteous.'),
  ('en.sahih', 11, 50, 'And to \'Aad [We sent] their brother Hud. He said, "O my people, worship Allah; you have no deity other than Him. You are not but inventors [of falsehood].'),
  ('en.sahih', 11, 51, 'O my people, I do not ask you for it any reward. My reward is only from the one who created me. Then will you not reason?'),
  ('en.sahih', 11, 52, 'And O my people, ask forgiveness of your Lord and then repent to Him. He will send [rain from] the sky upon you in showers and increase you in strength [added] to your strength. And do not turn away, [being] criminals."'),
  ('en.sahih', 11, 53, 'They said, "O Hud, you have not brought us clear evidence, and we are not ones to leave our gods on your say-so. Nor are we believers in you.'),
  ('en.sahih', 11, 54, 'We only say that some of our gods have possessed you with evil." He said, "Indeed, I call Allah to witness, and witness [yourselves] that I am free from whatever you associate with Allah'),
  ('en.sahih', 11, 55, 'Other than Him. So plot against me all together; then do not give me respite.'),
  ('en.sahih', 11, 56, 'Indeed, I have relied upon Allah, my Lord and your Lord. There is no creature but that He holds its forelock. Indeed, my Lord is on a path [that is] straight."'),
  ('en.sahih', 11, 57, 'But if they turn away, [say], "I have already conveyed that with which I was sent to you. My Lord will give succession to a people other than you, and you will not harm Him at all. Indeed my Lord is, over all things, Guardian."'),
  ('en.sahih', 11, 58, 'And when Our command came, We saved Hud and those who believed with him, by mercy from Us; and We saved them from a harsh punishment.'),
  ('en.sahih', 11, 59, 'And that was \'Aad, who rejected the signs of their Lord and disobeyed His messengers and followed the order of every obstinate tyrant.'),
  ('en.sahih', 11, 60, 'And they were [therefore] followed in this world with a curse and [as well] on the Day of Resurrection. Unquestionably, \'Aad denied their Lord; then away with \'Aad, the people of Hud.'),
  ('en.sahih', 11, 61, 'And to Thamud [We sent] their brother Salih. He said, "O my people, worship Allah; you have no deity other than Him. He has produced you from the earth and settled you in it, so ask forgiveness of Him and then repent to Him. Indeed, my Lord is near and responsive."'),
  ('en.sahih', 11, 62, 'They said, "O Salih, you were among us a man of promise before this. Do you forbid us to worship what our fathers worshipped? And indeed we are, about that to which you invite us, in disquieting doubt."'),
  ('en.sahih', 11, 63, 'He said, "O my people, have you considered: if I should be upon clear evidence from my Lord and He has given me mercy from Himself, who would protect me from Allah if I disobeyed Him? So you would not increase me except in loss.'),
  ('en.sahih', 11, 64, 'And O my people, this is the she-camel of Allah - [she is] to you a sign. So let her feed upon Allah \'s earth and do not touch her with harm, or you will be taken by an impending punishment."'),
  ('en.sahih', 11, 65, 'But they hamstrung her, so he said, "Enjoy yourselves in your homes for three days. That is a promise not to be denied."'),
  ('en.sahih', 11, 66, 'So when Our command came, We saved Salih and those who believed with him, by mercy from Us, and [saved them] from the disgrace of that day. Indeed, it is your Lord who is the Powerful, the Exalted in Might.'),
  ('en.sahih', 11, 67, 'And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone'),
  ('en.sahih', 11, 68, 'As if they had never prospered therein. Unquestionably, Thamud denied their Lord; then, away with Thamud.'),
  ('en.sahih', 11, 69, 'And certainly did Our messengers come to Abraham with good tidings; they said, "Peace." He said, "Peace," and did not delay in bringing [them] a roasted calf.'),
  ('en.sahih', 11, 70, 'But when he saw their hands not reaching for it, he distrusted them and felt from them apprehension. They said, "Fear not. We have been sent to the people of Lot."'),
  ('en.sahih', 11, 71, 'And his Wife was standing, and she smiled. Then We gave her good tidings of Isaac and after Isaac, Jacob.'),
  ('en.sahih', 11, 72, 'She said, "Woe to me! Shall I give birth while I am an old woman and this, my husband, is an old man? Indeed, this is an amazing thing!"'),
  ('en.sahih', 11, 73, 'They said, "Are you amazed at the decree of Allah? May the mercy of Allah and His blessings be upon you, people of the house. Indeed, He is Praiseworthy and Honorable."'),
  ('en.sahih', 11, 74, 'And when the fright had left Abraham and the good tidings had reached him, he began to argue with Us concerning the people of Lot.'),
  ('en.sahih', 11, 75, 'Indeed, Abraham was forbearing, grieving and [frequently] returning [to Allah].'),
  ('en.sahih', 11, 76, '[The angels said], "O Abraham, give up this [plea]. Indeed, the command of your Lord has come, and indeed, there will reach them a punishment that cannot be repelled."'),
  ('en.sahih', 11, 77, 'And when Our messengers, [the angels], came to Lot, he was anguished for them and felt for them great discomfort and said, "This is a trying day."'),
  ('en.sahih', 11, 78, 'And his people came hastening to him, and before [this] they had been doing evil deeds. He said, "O my people, these are my daughters; they are purer for you. So fear Allah and do not disgrace me concerning my guests. Is there not among you a man of reason?"'),
  ('en.sahih', 11, 79, 'They said, "You have already known that we have not concerning your daughters any claim, and indeed, you know what we want."'),
  ('en.sahih', 11, 80, 'He said, "If only I had against you some power or could take refuge in a strong support."'),
  ('en.sahih', 11, 81, 'The angels said, "O Lot, indeed we are messengers of your Lord; [therefore], they will never reach you. So set out with your family during a portion of the night and let not any among you look back - except your wife; indeed, she will be struck by that which strikes them. Indeed, their appointment is [for] the morning. Is not the morning near?"'),
  ('en.sahih', 11, 82, 'So when Our command came, We made the highest part [of the city] its lowest and rained upon them stones of layered hard clay, [which were]'),
  ('en.sahih', 11, 83, 'Marked from your Lord. And Allah \'s punishment is not from the wrongdoers [very] far.'),
  ('en.sahih', 11, 84, 'And to Madyan [We sent] their brother Shu\'ayb. He said, "O my people, worship Allah; you have no deity other than Him. And do not decrease from the measure and the scale. Indeed, I see you in prosperity, but indeed, I fear for you the punishment of an all-encompassing Day.'),
  ('en.sahih', 11, 85, 'And O my people, give full measure and weight in justice and do not deprive the people of their due and do not commit abuse on the earth, spreading corruption.'),
  ('en.sahih', 11, 86, 'What remains [lawful] from Allah is best for you, if you would be believers. But I am not a guardian over you."'),
  ('en.sahih', 11, 87, 'They said, "O Shu\'ayb, does your prayer command you that we should leave what our fathers worship or not do with our wealth what we please? Indeed, you are the forbearing, the discerning!"'),
  ('en.sahih', 11, 88, 'He said, "O my people, have you considered: if I am upon clear evidence from my Lord and He has provided me with a good provision from Him...? And I do not intend to differ from you in that which I have forbidden you; I only intend reform as much as I am able. And my success is not but through Allah. Upon him I have relied, and to Him I return.'),
  ('en.sahih', 11, 89, 'And O my people, let not [your] dissension from me cause you to be struck by that similar to what struck the people of Noah or the people of Hud or the people of Salih. And the people of Lot are not from you far away.'),
  ('en.sahih', 11, 90, 'And ask forgiveness of your Lord and then repent to Him. Indeed, my Lord is Merciful and Affectionate."'),
  ('en.sahih', 11, 91, 'They said, "O Shu\'ayb, we do not understand much of what you say, and indeed, we consider you among us as weak. And if not for your family, we would have stoned you [to death]; and you are not to us one respected."'),
  ('en.sahih', 11, 92, 'He said, "O my people, is my family more respected for power by you than Allah? But you put Him behind your backs [in neglect]. Indeed, my Lord is encompassing of what you do.'),
  ('en.sahih', 11, 93, 'And O my people, work according to your position; indeed, I am working. You are going to know to whom will come a punishment that will disgrace him and who is a liar. So watch; indeed, I am with you a watcher, [awaiting the outcome]."'),
  ('en.sahih', 11, 94, 'And when Our command came, We saved Shu\'ayb and those who believed with him, by mercy from Us. And the shriek seized those who had wronged, and they became within their homes [corpses] fallen prone'),
  ('en.sahih', 11, 95, 'As if they had never prospered therein. Then, away with Madyan as Thamud was taken away.'),
  ('en.sahih', 11, 96, 'And We did certainly send Moses with Our signs and a clear authority'),
  ('en.sahih', 11, 97, 'To Pharaoh and his establishment, but they followed the command of Pharaoh, and the command of Pharaoh was not [at all] discerning.'),
  ('en.sahih', 11, 98, 'He will precede his people on the Day of Resurrection and lead them into the Fire; and wretched is the place to which they are led.'),
  ('en.sahih', 11, 99, 'And they were followed in this [world] with a curse and on the Day of Resurrection. And wretched is the gift which is given.'),
  ('en.sahih', 11, 100, 'That is from the news of the cities, which We relate to you; of them, some are [still] standing and some are [as] a harvest [mowed down].'),
  ('en.sahih', 11, 101, 'And We did not wrong them, but they wronged themselves. And they were not availed at all by their gods which they invoked other than Allah when there came the command of your Lord. And they did not increase them in other than ruin.'),
  ('en.sahih', 11, 102, 'And thus is the seizure of your Lord when He seizes the cities while they are committing wrong. Indeed, His seizure is painful and severe.'),
  ('en.sahih', 11, 103, 'Indeed in that is a sign for those who fear the punishment of the Hereafter. That is a Day for which the people will be collected, and that is a Day [which will be] witnessed.'),
  ('en.sahih', 11, 104, 'And We do not delay it except for a limited term.'),
  ('en.sahih', 11, 105, 'The Day it comes no soul will speak except by His permission. And among them will be the wretched and the prosperous.'),
  ('en.sahih', 11, 106, 'As for those who were [destined to be] wretched, they will be in the Fire. For them therein is [violent] exhaling and inhaling.'),
  ('en.sahih', 11, 107, '[They will be] abiding therein as long as the heavens and the earth endure, except what your Lord should will. Indeed, your Lord is an effecter of what He intends.'),
  ('en.sahih', 11, 108, 'And as for those who were [destined to be] prosperous, they will be in Paradise, abiding therein as long as the heavens and the earth endure, except what your Lord should will - a bestowal uninterrupted.'),
  ('en.sahih', 11, 109, 'So do not be in doubt, [O Muhammad], as to what these [polytheists] are worshipping. They worship not except as their fathers worshipped before. And indeed, We will give them their share undiminished.'),
  ('en.sahih', 11, 110, 'And We had certainly given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been judged between them. And indeed they are, concerning the Qur\'an, in disquieting doubt.'),
  ('en.sahih', 11, 111, 'And indeed, each [of the believers and disbelievers] - your Lord will fully compensate them for their deeds. Indeed, He is Acquainted with what they do.'),
  ('en.sahih', 11, 112, 'So remain on a right course as you have been commanded, [you] and those who have turned back with you [to Allah], and do not transgress. Indeed, He is Seeing of what you do.'),
  ('en.sahih', 11, 113, 'And do not incline toward those who do wrong, lest you be touched by the Fire, and you would not have other than Allah any protectors; then you would not be helped.'),
  ('en.sahih', 11, 114, 'And establish prayer at the two ends of the day and at the approach of the night. Indeed, good deeds do away with misdeeds. That is a reminder for those who remember.'),
  ('en.sahih', 11, 115, 'And be patient, for indeed, Allah does not allow to be lost the reward of those who do good.'),
  ('en.sahih', 11, 116, 'So why were there not among the generations before you those of enduring discrimination forbidding corruption on earth - except a few of those We saved from among them? But those who wronged pursued what luxury they were given therein, and they were criminals.'),
  ('en.sahih', 11, 117, 'And your Lord would not have destroyed the cities unjustly while their people were reformers.'),
  ('en.sahih', 11, 118, 'And if your Lord had willed, He could have made mankind one community; but they will not cease to differ.'),
  ('en.sahih', 11, 119, 'Except whom your Lord has given mercy, and for that He created them. But the word of your Lord is to be fulfilled that, "I will surely fill Hell with jinn and men all together."'),
  ('en.sahih', 11, 120, 'And each [story] We relate to you from the news of the messengers is that by which We make firm your heart. And there has come to you, in this, the truth and an instruction and a reminder for the believers.'),
  ('en.sahih', 11, 121, 'And say to those who do not believe, "Work according to your position; indeed, we are working.'),
  ('en.sahih', 11, 122, 'And wait, indeed, we are waiting."'),
  ('en.sahih', 11, 123, 'And to Allah belong the unseen [aspects] of the heavens and the earth and to Him will be returned the matter, all of it, so worship Him and rely upon Him. And your Lord is not unaware of that which you do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 11, 1, 'আলিফ, লা-ম, রা; এটি এমন এক কিতাব, যার আয়াত সমূহ সুপ্রতিষ্ঠিত অতঃপর সবিস্তারে বর্ণিত এক মহাজ্ঞানী, সর্বজ্ঞ সত্তার পক্ষ হতে।'),
  ('bn.bengali', 11, 2, 'যেন তোমরা আল্লাহ ব্যতীত অন্য কারো বন্দেগী না কর। নিশ্চয় আমি তোমাদের প্রতি তাঁরই পক্ষ হতে সতর্ককারী ও সুসংবাদ দাতা।'),
  ('bn.bengali', 11, 3, 'আর তোমরা নিজেদের পালনকর্তা সমীপে ক্ষমা প্রার্থনা কর। অনন্তর তাঁরই প্রতি মনোনিবেশ কর। তাহলে তিনি তোমাদেরকে নির্দিষ্ট সময় পর্যন্ত উৎকৃষ্ট জীবনোপকরণ দান করবেন এবং অধিক আমলকারীকে বেশী করে দেবেন আর যদি তোমরা বিমুখ হতে থাক, তবে আমি তোমাদের উপর এক মহা দিবসের আযাবের আশঙ্কা করছি।'),
  ('bn.bengali', 11, 4, 'আল্লাহর সান্নিধ্যেই তোমাদেরকে ফিরে যেতে হবে। আর তিনি সব কিছুর উপর ক্ষমতাবান।'),
  ('bn.bengali', 11, 5, 'জেনে রাখ, নিশ্চয়ই তারা নিজেদের বক্ষদেশ ঘুরিয়ে দেয় যেন আল্লাহর নিকট হতে লুকাতে পারে। শুন, তারা তখন কাপড়ে নিজেদেরকে আচ্ছাদিত করে, তিনি তখনও জানেন যা কিছু তারা চুপিসারে বলে আর প্রকাশ্যভাবে বলে। নিশ্চয় তিনি জানেন যা কিছু অন্তর সমূহে নিহিত রয়েছে।'),
  ('bn.bengali', 11, 6, 'আর পৃথিবীতে কোন বিচরণশীল নেই, তবে সবার জীবিকার দায়িত্ব আল্লাহ নিয়েছেন তিনি জানেন তারা কোথায় থাকে এবং কোথায় সমাপিত হয়। সবকিছুই এক সুবিন্যস্ত কিতাবে রয়েছে।'),
  ('bn.bengali', 11, 7, 'তিনিই আসমান ও যমীন ছয় দিনে তৈরী করেছেন, তাঁর আরশ ছিল পানির উপরে, তিনি তোমাদেরকে পরীক্ষা করতে চান যে, তোমাদের মধ্যে কে সবচেয়ে ভাল কাজ করে। আর যদি আপনি তাদেরকে বলেন যে, "নিশ্চয় তোমাদেরকে মৃত্যুর পরে জীবিত ওঠানো হবে, তখন কাফেরেরা অবশ্য বলে এটা তো স্পষ্ট যাদু!";'),
  ('bn.bengali', 11, 8, 'আর যদি আমি এক নির্ধারিত মেয়াদ পর্যন্ত তাদের আযাব স্থগিত রাখি, তাহলে তারা নিশ্চয়ই বলবে কোন জিনিসে আযাব ঠেকিয়ে রাখছে? শুনে রাখ, যেদিন তাদের উপর আযাব এসে পড়বে, সেদিন কিন্তু তা ফিরে যাওয়ার নয়; তারা যে ব্যাপারে উপহাস করত তাই তাদেরকে ঘিরে ফেলবে।'),
  ('bn.bengali', 11, 9, 'আর অবশ্যই যদি আমি মানুষকে আমার রহমতের আস্বাদ গ্রহণ করতে দেই, অতঃপর তা তার থেকে ছিনিয়ে নেই; তাহলে সে হতাশ ও কৃতঘ্ন হয়।'),
  ('bn.bengali', 11, 10, 'আর যদি তার উপর আপতিত দুঃখ কষ্টের পরে তাকে সুখভোগ করতে দেই, তবে সে বলতে থাকে যে, আমার অমঙ্গল দূর হয়ে গেছে, আর সে আনন্দে আত্নহারা হয়, অহঙ্কারে উদ্দত হয়ে পড়ে।'),
  ('bn.bengali', 11, 11, 'তবে যারা ধৈর্য্যধারণ করেছে এবং সৎকার্য করেছে তাদের জন্য ক্ষমা ও বিরাট প্রতিদান রয়েছে।'),
  ('bn.bengali', 11, 12, 'আর সম্ভবতঃ ঐসব আহকাম যা ওহীর মাধ্যমে তোমার নিকট পাঠানো হয়, তার কিছু অংশ বর্জন করবে? এবং এতে মন ছোট করে বসবে? তাদের এ কথায় যে, তাঁর উপর কোন ধন-ভান্ডার কেন অবতীর্ণ হয়নি? অথবা তাঁর সাথে কোন ফেরেশতা আসেনি কেন? তুমিতো শুধু সতর্ককারী মাত্র; আর সব কিছুরই দায়িত্বভার তো আল্লাহই নিয়েছেন।'),
  ('bn.bengali', 11, 13, 'তারা কি বলে? কোরআন তুমি তৈরী করেছ? তুমি বল, তবে তোমরাও অনুরূপ দশটি সূরা তৈরী করে নিয়ে আস এবং আল্লাহ ছাড়া যাকে পার ডেকে নাও, যদি তোমাদের কথা সত্য হয়ে থাকে।'),
  ('bn.bengali', 11, 14, 'অতঃপর তারা যদি তোমাদের কথা পুরণ করতে অপারগ হয়; তবে জেনে রাখ, এটি আল্লাহর এলম দ্বারা অবতীর্ণ হয়েছে; আরো একীন করে নাও যে, আল্লাহ ব্যতীত অন্য কোন মাবুদ নেই। অতএব, এখন কি তোমরা আত্নসমর্পন করবে?'),
  ('bn.bengali', 11, 15, 'যে ব্যক্তি পার্থিবজীবন ও তার চাকচিক্যই কামনা করে, হয় আমি তাদের দুনিয়াতেই তাদের আমলের প্রতিফল ভোগ করিয়ে দেব এবং তাতে তাদের প্রতি কিছুমাত্র কমতি করা হয় না।'),
  ('bn.bengali', 11, 16, 'এরাই হল সেসব লোক আখেরাতে যাদের জন্য আগুন ছাড়া নেই। তারা এখানে যা কিছু করেছিল সবই বরবাদ করেছে; আর যা কিছু উপার্জন করেছিল, সবই বিনষ্ট হল।'),
  ('bn.bengali', 11, 17, 'আচ্ছা বল তো, যে ব্যক্তি তার প্রভুর সুস্পষ্ট পথে রয়েছে, আর সাথে সাথে আল্লাহর তরফ থেকে একটি সাক্ষীও বর্তমান রয়েছে এবং তার পূর্ববর্তী মূসা (আঃ) এর কিতাবও সাক্ষী যা ছিল পথনির্দেশক ও রহমত স্বরূপ, (তিনি কি অন্যান্যের সমান) অতএব তাঁরা কোরআনের প্রতি ঈমান আনেন। আর ঐসব দলগুলি যে কেউ তা অস্বীকার করে, দোযখই হবে তার ঠিকানা। অতএব, আপনি তাতে কোন সন্দেহে থাকবেন না। নিঃসন্দেহে তা আপনার পালনকর্তার পক্ষ হতে ধ্রুব সত্য; তথাপি অনেকেই তা বিশ্বাস করে না।'),
  ('bn.bengali', 11, 18, 'আর তাদের চেয়ে বড় যালেম কে হতে পারে, যারা আল্লাহর প্রতি মিথ্যারোপ করে। এসব লোককে তাদের পালনকর্তার সাক্ষাত সম্মূখীন করা হবে আর সাক্ষিগণ বলতে থাকবে, এরাই ঐসব লোক, যারা তাদের পালনকর্তার প্রতি মিথ্যারোপ করেছিল। শুনে রাখ, যালেমদের উপর আল্লাহর অভিসম্পাত রয়েছে।'),
  ('bn.bengali', 11, 19, 'যারা আল্লাহর পথে বাধা দেয়, আর তাতে বক্রতা খুজে বেড়ায়, এরাই আখরাতকে অস্বীকার করে।'),
  ('bn.bengali', 11, 20, 'তারা পৃথিবীতেও আল্লাহকে অপারগ করতে পারবে না এবং আল্লাহ ব্যতীত তাদের কোন সাহায্যকারীও নেই, তাদের জন্য দ্বিগুণ শাস্তি রয়েছে; তারা শুনতে পারত না এবং দেখতেও পেত না।'),
  ('bn.bengali', 11, 21, 'এরা সে লোক, যারা নিজেরাই নিজেদেরকে ক্ষতিগ্রস্ত করেছে, আর এরা যা কিছু মিথ্যা মা’বুদ সাব্যস্ত করেছিল, তা সবই তাদের থেকে হারিয়ে গেছে।'),
  ('bn.bengali', 11, 22, 'আখেরাতে এরাই হবে সর্বাধিক ক্ষতিগ্রস্থ কোন সন্দেহ নেই।'),
  ('bn.bengali', 11, 23, 'নিশ্চয়ই যারা ঈমান এনেছে ও সৎকাজ করেছে এবং স্বীয় পালনকর্তার সমীপে বিনতি প্রকাশ করেছে তারাই বেহেশতবাসী, সেখানেই তারা চিরকাল থাকবে।'),
  ('bn.bengali', 11, 24, 'উভয় পক্ষের দৃষ্টান্ত হচ্ছে যেমন অন্ধ ও বধির এবং যে দেখতে পায় ও শুনতে পায় উভয়ের অবস্থা কি এক সমান? তবুও তোমরা কি ভেবে দেখ না?'),
  ('bn.bengali', 11, 25, 'আর অবশ্যই আমি নূহ (আঃ) কে তাঁর জাতির প্রতি প্রেরণ করেছি, (তিনি বললেন) নিশ্চয় আমি তোমাদের জন্য প্রকাশ্য সতর্ককারী।'),
  ('bn.bengali', 11, 26, 'তোমরা আল্লাহ ব্যতীত কারো এবাদত করবে না। নিশ্চয় আমি তোমাদের ব্যাপারে এক যন্ত্রণাদায়ক দিনের আযাবের ভয় করছি।'),
  ('bn.bengali', 11, 27, 'তখন তাঁর কওমের কাফের প্রধানরা বলল আমরা তো আপনাকে আমাদের মত একজন মানুষ ব্যতীত আর কিছু মনে করি না; আর আমাদের মধ্যে যারা ইতর ও স্থুল-বুদ্ধিসম্পন্ন তারা ব্যতীত কাউকে তো আপনার আনুগত্য করতে দেখি না এবং আমাদের উপর আপনাদের কেন প্রাধান্য দেখি না, বরং আপনারা সবাই মিথ্যাবাদী বলে আমারা মনে করি।'),
  ('bn.bengali', 11, 28, 'নূহ (আঃ) বললেন-হে আমার জাতি! দেখ তো আমি যদি আমার পালনকর্তার পক্ষ হতে স্পষ্ট দলীলের উপর থাক, আর তিনি যদি তাঁর পক্ষ হতে আমাকে রহমত দান করে থাকেন, তারপরেও তা তোমাদের চোখে না পড়ে, তাহলে আমি কি উহা তোমাদের উপর তোমাদের ইচ্ছার বিরুদ্ধেই চাপিয়ে দিতে পারি ?'),
  ('bn.bengali', 11, 29, 'আর হে আমার জাতি! আমি তো এজন্য তোমাদের কাছে কোন অর্থ চাই না; আমার পারিশ্রমিক তো আল্লাহর জিম্মায় রয়েছে। আমি কিন্তু ঈমানদারদের তাড়িয়ে দিতে পারি না। তারা অবশ্যই তাদের পালনকর্তার সাক্ষাত লাভ করবে। বরঞ্চ তোমাদেরই আমি অজ্ঞ সম্প্রদায় দেখছি।'),
  ('bn.bengali', 11, 30, 'আর হে আমার জাতি! আমি যদি তাদের তাড়িয়ে দেই তাহলে আমাকে আল্লাহ হতে রেহাই দেবে কে? তোমরা কি চিন্তা করে দেখ না?'),
  ('bn.bengali', 11, 31, 'আর আমি তোমাদেরকে বলি না যে, আমার কাছে আল্লাহর ভান্ডার রয়েছে এবং একথাও বলি না যে, আমি গায়বী খবরও জানি; একথাও বলি না যে, আমি একজন ফেরেশতা; আর তোমাদের দৃষ্টিতে যারা লাঞ্ছিত আল্লাহ তাদের কোন কল্যাণ দান করবেন না। তাদের মনের কথা আল্লাহ ভাল করেই জানেন। সুতরাং এমন কথা বললে আমি অন্যায় কারী হব।'),
  ('bn.bengali', 11, 32, 'তারা বলল-হে নূহ! আমাদের সাথে আপনি তর্ক করেছেন এবং অনেক কলহ করেছেন। এখন আপনার সেই আযাব নিয়ে আসুন, যে সম্পর্কে আপনি আমাদিগকে সতর্ক করেছেন, যদি আপনি সত্যবাদী হয়ে থাকেন।'),
  ('bn.bengali', 11, 33, 'তিনি বলেন, উহা তোমাদের কাছে আল্লাহই আনবেন, যদি তিনি ইচ্ছা করেন তখন তোমরা পালিয়ে তাঁকে অপারগ করতে পারবে না।'),
  ('bn.bengali', 11, 34, 'আর আমি তোমাদের নসীহত করতে চাইলেও তা তোমাদের জন্য ফলপ্রসূ হবে না, যদি আল্লাহ তোমাদেরকে গোমরাহ করতে চান; তিনিই তোমাদের পালনকর্তা এবং তাঁর কাছেই তোমাদের ফিরে যেতে হবে।'),
  ('bn.bengali', 11, 35, 'তারা কি বলে? আপনি কোরআন রচনা করে এনেছেন? আপনি বলে দিন আমি যদি রচনা করে এনে থাকি, তবে সে অপরাধ আমার, আর তোমরা যেসব অপরাধ কর তার সাথে আমার কোন সম্পর্ক নেই।'),
  ('bn.bengali', 11, 36, 'আর নূহ (আঃ) এর প্রতি ওহী প্রেরণ করা হলো যে, যারা ইতিমধ্যেই ঈমান এনেছে তাদের ছাড়া আপনার জাতির অন্য কেউ ঈমান আনবেনা এতএব তাদের কার্যকলাপে বিমর্ষ হবেন না।'),
  ('bn.bengali', 11, 37, 'আর আপনি আমার সম্মুখে আমারই নির্দেশ মোতাবেক একটি নৌকা তৈরী করুন এবং পাপিষ্ঠদের ব্যাপারে আমাকে কোন কথা বলবেন না। অবশ্যই তারা ডুবে মরবে।'),
  ('bn.bengali', 11, 38, 'তিনি নৌকা তৈরী করতে লাগলেন, আর তাঁর কওমের নেতৃস্থানীয় ব্যক্তিরা যখন পার্শ্ব দিয়ে যেত, তখন তাঁকে বিদ্রুপ করত। তিনি বললেন, তোমরা যদি আমাদের উপহাস করে থাক, তবে তোমরা যেমন উপহাস করছ আমরাও তদ্রুপ তোমাদের উপহাস করছি।'),
  ('bn.bengali', 11, 39, 'অতঃপর অচিরেই জানতে পারবে-লাঞ্ছনাজনক আযাব কার উপর আসে এবং চিরস্থায়ী আযাব কার উপর অবতরণ করে।'),
  ('bn.bengali', 11, 40, 'অবশেষে যখন আমার হুকুম এসে পৌঁছাল এবং ভুপৃষ্ঠ উচ্ছসিত হয়ে উঠল, আমি বললামঃ সর্বপ্রকার জোড়ার দুটি করে এবং যাদের উপরে পূর্বহেߦ#2439; হুকুম হয়ে গেছে তাদের বাদি দিয়ে, আপনার পরিজনবর্গ ও সকল ঈমানদারগণকে নৌকায় তুলে নিন। বলাবাহুল্য অতি অল্পসংখ্যক লোকই তাঁর সাথে ঈমান এনেছিল।'),
  ('bn.bengali', 11, 41, 'আর তিনি বললেন, তোমরা এতে আরোহন কর। আল্লাহর নামেই এর গতি ও স্থিতি। আমার পালনকর্তা অতি ক্ষমাপরায়ন, মেহেরবান।'),
  ('bn.bengali', 11, 42, 'আর নৌকাখানি তাদের বহন করে চলল পর্বত প্রমাণ তরঙ্গমালার মাঝে, আর নূহ (আঃ) তাঁর পুত্রকে ডাক দিলেন আর সে সরে রয়েছিল, তিনি বললেন, প্রিয় বৎস! আমাদের সাথে আরোহন কর এবং কাফেরদের সাথে থেকো না।'),
  ('bn.bengali', 11, 43, 'সে বলল, আমি অচিরেই কোন পাহাড়ে আশ্রয় নেব, যা আমাকে পানি হতে রক্ষা করবে। নূহ (আঃ) বল্লেন আজকের দিনে আল্লাহর হুকুম থেকে কোন রক্ষাকারী নেই। একমাত্র তিনি যাকে দয়া করবেন। এমন সময় উভয়ের মাঝে তরঙ্গ আড়াল হয়ে দাঁড়াল, ফলে সে নিমজ্জিত হল।'),
  ('bn.bengali', 11, 44, 'আর নির্দেশ দেয়া হল-হে পৃথিবী! তোমার পানি গিলে ফেল, আর হে আকাশ, ক্ষান্ত হও। আর পানি হ্রাস করা হল এবং কাজ শেষ হয়ে গেল, আর জুদী পর্বতে নৌকা ভিড়ল এবং ঘোষনা করা হল, দুরাত্না কাফেররা নিপাত যাক।'),
  ('bn.bengali', 11, 45, 'আর নূহ (আঃ) তাঁর পালনকর্তাকে ডেকে বললেন-হে পরওয়ারদেগার, আমার পুত্র তো আমার পরিজনদের অন্তর্ভুক্ত; আর আপনার ওয়াদাও নিঃসন্দেহে সত্য আর আপনিই সর্বাপেক্ষা বিজ্ঞ ফয়সালাকারী।'),
  ('bn.bengali', 11, 46, 'আল্লাহ বলেন, হে নূহ! নিশ্চয় সে আপনার পরিবারভুক্ত নয়। নিশ্চই সে দুরাচার! সুতরাং আমার কাছে এমন দরখাস্ত করবেন না, যার খবর আপনি জানেন না। আমি আপনাকে উপপদেশ দিচ্ছি যে, আপনি অজ্ঞদের দলভুক্ত হবেন না।'),
  ('bn.bengali', 11, 47, 'নূহ (আঃ) বলেন-হে আমার পালনকর্তা আমার যা জানা নেই এমন কোন দরখাস্ত করা হতে আমি আপনার কাছেই আশ্রয় প্রার্থনা করছি। আপনি যদি আমাকে ক্ষমা না করেন, দয়া না করেন, তাহলে আমি ক্ষতিগ্রস্ত হব।'),
  ('bn.bengali', 11, 48, 'হুকুম হল-হে নূহ (আঃ)! আমার পক্ষ হতে নিরাপত্তা এবং আপনার নিজের ও সঙ্গীয় সম্প্রদায়গুলির উপর বরকত সহকারে অবতরণ করুণ। আর অন্যান্য যেসব সম্প্রদায় রয়েছে আমি তাদের কেও উপকৃত হতে দেব। অতঃপর তাদের উপর আমার দরুন আযাব আপতিত হবে।'),
  ('bn.bengali', 11, 49, 'এটি গায়বের খবর, আমি আপনার প্রতি ওহী প্রেরন করছি। ইতিপূর্বে এটা আপনার এবং আপনার জাতির জানা ছিল না। আপনি ধৈর্য্যধারণ করুন। যারা ভয় করে চলে, তাদের পরিণাম ভাল, সন্দেহ নেই।'),
  ('bn.bengali', 11, 50, 'আর আদ জাতির প্রতি আমি তাদের ভাই হুদকে প্রেরণ করেছি; তিনি বলেন-হে আমার জাতি, আল্লাহর বন্দেগী কর, তিনি ভিন্ন তোমাদের কোন মাবুদ নেই, তোমরা সবাই মিথ্যা আরোপ করছ।'),
  ('bn.bengali', 11, 51, 'হে আমার জাতি! আমি এজন্য তোমাদের কাছে কোন মজুরী চাই না; আমার মজুরী তাঁরই কাছে যিনি আমাকে পয়দা করেছেন; তবু তোমরা কেন বোঝ না?'),
  ('bn.bengali', 11, 52, 'আর হে আমার কওম! তোমাদের পালন কর্তার কাছে তোমরা ক্ষমা প্রার্থনা কর, অতঃপর তাঁরই প্রতি মনোনিবেশ কর; তিনি আসমান থেকে তোমাদের উপর বৃষ্টি ধারা প্রেরণ করবেন এবং তোমাদের শক্তির উপর শক্তি বৃদ্ধি করবেন, তোমরা কিন্তু অপরাধীদের মত বিমুখ হয়ো না।'),
  ('bn.bengali', 11, 53, 'তারা বলল-হে হুদ, তুমি আমাদের কাছে কোন প্রমাণ নিয়ে আস নাই, আমরা তোমার কথায় আমাদের দেব-দেবীদের বর্জন করতে পারি না আর আমরা তোমার প্রতি ঈমান আনয়নকারীও নই।'),
  ('bn.bengali', 11, 54, 'বরং আমরাও তো বলি যে, আমাদের কোন দেবতা তোমার উপরে শোচনীয় ভূত চাপিয়ে দিয়েছে। হুদ বললেন-আমি আল্লাহকে সাক্ষী করেছি আর তোমাও সাক্ষী থাক যে, আমার কোন সম্পর্ক নাই তাঁদের সাথে যাদের কে তোমরা শরিক করছ;'),
  ('bn.bengali', 11, 55, 'তাকে ছাড়া, তোমরা সবাই মিলে আমার অনিষ্ট করার প্রয়াস চালাও, অতঃপর আমাকে কোন অবকাশ দিও না।'),
  ('bn.bengali', 11, 56, 'আমি আল্লাহর উপর নিশ্চিত ভরসা করেছি যিনি আমার এবং তোমাদের পরওয়ারদেগার। পৃথিবীর বুকে বিচরণকারী এমন কোন প্রাণী নাই যা তাঁর র্পূণ আয়ত্তাধীন নয়। আমার পালকর্তার সরল পথে সন্দেহ নেই।'),
  ('bn.bengali', 11, 57, 'তথাপি যদি তোমরা মুখ ফেরাও, তবে আমি তোমাদেরকে তা পৌছিয়েছি যা আমার কাছে তোমাদের প্রতি প্রেরিত হয়েছে; আর আমার পালনকর্তা অন্য কোন জাতিকে তোমাদের স্থলাভিষিক্ত করবেন, আর তোমরা তাঁর কিছুই বিগড়াতে পারবে না; নিশ্চয়ই আমার পরওয়ারদেগারই প্রতিটি বস্তুর হেফাজতকারী।'),
  ('bn.bengali', 11, 58, 'আর আমার আদেশ যখন উপস্থিত হল, তখন আমি নিজ রহমতে হুদ এবং তাঁর সঙ্গী ঈমানদারগণকে পরিত্রাণ করি এবং তাদেরকে এক কঠিন শাস্তি থেকে রক্ষা করি।'),
  ('bn.bengali', 11, 59, 'এ ছিল আদ জাতি, যারা তাদের পালনকর্তার আয়াতকে অমান্য করেছে, আর তদীয় রসূলগণের অবাধ্যতা করেছে এবং প্রত্যেক উদ্ধত বিরোধীদের আদেশ পালন করেছে।'),
  ('bn.bengali', 11, 60, 'এ দুনিয়ায় তাদের পিছনে পিছনে লা’নত রয়েছে এবং কেয়ামতের দিনেও; জেনে রাখ, আদ জাতি তাদের পালনকর্তাকে অস্বীকার করেছে, হুদের জ্ঞাতি আদ জাতির প্রতি অভিসম্পাত রয়েছে জেনে রাখ।'),
  ('bn.bengali', 11, 61, 'আর সামুদ জাতি প্রতি তাদের ভাই সালেহ কে প্রেরণ করি; তিনি বললেন, হে আমার জাতি। আল্লাহর বন্দেগী কর, তিনি ছাড়া তোমাদের কোন উপাস্য নাই। তিনিই যমীন হতে তোমাদেরকে পয়দা করেছেন, তন্মধ্যে তোমাদেরকে বসতি দান করেছেন। অতএব; তাঁর কাছে ক্ষমা প্রার্থনা কর অতঃপর তাঁরই দিকে ফিরে চল আমার পালনকর্তা নিকটেই আছেন, কবুল করে থাকেন; সন্দেহ নেই।'),
  ('bn.bengali', 11, 62, 'তারা বলল-হে সালেহ, ইতিপূর্বে তোমার কাছে আমাদের বড় আশা ছিল। আমাদের বাপ-দাদা যা পূজা করত তুমি কি আমাদেরকে তার পূজা করতে নিষেধ কর? কিন্তু যার প্রতি তুমি আমাদের আহবান জানাচ্ছ আমাদের তাতে এমন সন্দেহ রয়েছে যে, মন মোটেই সায় দিচ্ছে না।'),
  ('bn.bengali', 11, 63, 'সালেহ বললেন-হে আমার জাতি! তোমরা কি মনে কর, আমি যদি আমার পালনকর্তার পক্ষ হতে বুদ্ধি বিবেচনা লাভ করে থাকি আর তিনি যদি আমাকে নিজের তরফ হতে রহমত দান করে থাকেন, অতঃপর আমি যদি তাঁর অবাধ্য হই তবে তার থেকে কে আমায় রক্ষা করবে? তোমরা তো আমার ক্ষতি ছাড়া কিছুই বৃদ্ধি করতে পরবে না'),
  ('bn.bengali', 11, 64, 'আর হে আমার জাতি! আল্লাহর এ উষ্ট্রীটি তোমাদের জন্য নিদর্শন, অতএব তাকে আল্লাহর যমীনে বিচরণ করে খেতে দাও, এবং তাকে মন্দভাবে স্পর্শও করবে না। নতুবা অতি সত্বর তোমাদেরকে আযাব পাকড়াও করবে।'),
  ('bn.bengali', 11, 65, 'তবু তারা উহার পা কেটে দিল। তখন সালেহ বললেন-তোমরা নিজেদের গৃহে তিনটি দিন উপভোগ করে নাও। ইহা এমন ওয়াদা যা মিথ্যা হবে না।'),
  ('bn.bengali', 11, 66, 'অতঃপর আমার আযাব যখন উপস্থিত হল, তখন আমি সালেহকে ও তদীয় সঙ্গী ঈমানদারগণকে নিজ রহমতে উদ্ধার করি, এবং সেদিনকার অপমান হতে রক্ষা করি। নিশ্চয় তোমার পালনকর্তা তিনি সর্বশক্তিমান পরাক্রমশালী।'),
  ('bn.bengali', 11, 67, 'আর ভয়ঙ্কর গর্জন পাপিষ্ঠদের পাকড়াও করল, ফলে ভোর হতে না হতেই তারা নিজ নিজ গৃহসমূহে উপুর হয়ে পড়ে রইল।'),
  ('bn.bengali', 11, 68, 'যেন তাঁরা কোনদিনই সেখানে ছিল না। জেনে রাখ, নিশ্চয় সামুদ জাতি তাদের পালনকর্তার প্রতি অস্বীকার করেছিল। আরো শুনে রাখ, সামুদ জাতির জন্য অভিশাপ রয়েছে।'),
  ('bn.bengali', 11, 69, 'আর অবশ্যই আমার প্রেরিত ফেরেশতারা ইব্রাহীমেরে কাছে সুসংবাদ নিয়ে এসেছিল তারা বলল সালাম, তিনিও বললেন-সালাম। অতঃপর অল্পক্ষণের মধ্যেই তিনি একটি ভুনা করা বাছুর নিয়ে এলেন!'),
  ('bn.bengali', 11, 70, 'কিন্তু যখন দেখলেন যে, আহার্য্যের দিকে তাদের হস্ত প্রসারিত হচ্ছে না, তখন তিনি সন্ধিগ্ধ হলেন এবং মনে মনে তাঁদের সম্পর্কে ভয় অনুভব করতে লাগলেন। তারা বলল-ভয় পাবেন না। আমরা লূতের কওমের প্রতি প্রেরিত হয়েছি।'),
  ('bn.bengali', 11, 71, 'তাঁর স্ত্রীও নিকটেই দাড়িয়েছিল, সে হেসে ফেলল। অতঃপর আমি তাকে ইসহাকের জন্মের সুখবর দিলাম এবং ইসহাকের পরের ইয়াকুবেরও।'),
  ('bn.bengali', 11, 72, 'সে বলল-কি দুর্ভাগ্য আমার! আমি সন্তান প্রসব করব? অথচ আমি বার্ধক্যের শেষ প্রান্তে এসে উপনীত হয়েছি আর আমার স্বামীও বৃদ্ধ, এতো ভারী আশ্চর্য কথা।'),
  ('bn.bengali', 11, 73, 'তারা বলল-তুমি আল্লাহর হুকুম সম্পর্কে বিস্ময়বোধ করছ? হে গৃহবাসীরা, তোমাদের উপর আল্লাহর রহমত ও প্রভুত বরকত রয়েছে। নিশ্চয় আল্লাহ প্রশংসিত মহিমাময়।'),
  ('bn.bengali', 11, 74, 'অতঃপর যখন ইব্রাহীম (আঃ) এর আতঙ্ক দূর হল এবং তিনি সুসংবাদ প্রাপ্ত হলেন, তখন তিনি আমার সাথে তর্ক শুরু করলেন কওমে লূত সম্পর্কে।'),
  ('bn.bengali', 11, 75, 'ইব্রাহীম (আঃ) বড়ই ধৈর্য্যশীল, কোমল অন্তর, আল্লাহমুখী সন্দেহ নেই।'),
  ('bn.bengali', 11, 76, 'ইব্রাহীম, এহেন ধারণা পরিহার কর; তোমার পালনকর্তার হুকুম এসে গেছে, এবং তাদের উপর সে আযাব অবশ্যই আপতিত হবে, যা কখনো প্রতিহত হবার নয়।'),
  ('bn.bengali', 11, 77, 'আর যখন আমার প্রেরিত ফেরেশতাগণ লূত (আঃ) এর নিকট উপস্থিত হল। তখন তাঁদের আগমনে তিনি দুচিন্তাগ্রস্ত হলেন এবং তিনি বলতে লাগলেন, আজ অত্যন্ত কঠিন দিন।'),
  ('bn.bengali', 11, 78, 'আর তাঁর কওমের লোকেরা স্বতঃস্ফুর্তভাবে তার (গৃহ) পানে ছুটে আসতে লাগল। পূর্ব থেকেই তারা কু-কর্মে তৎপর ছিল। লূত (আঃ) বললেন-হে আমার কওম, এ আমার কন্যারা রয়েছে, এরা তোমাদের জন্য অধিক পবিত্রতমা। সুতরাং তোমরা আল্লাহকে ভয় কর এবং অতিথিদের ব্যাপারে আমাকে লজ্জিত করো না, তোমাদের মধ্যে কি কোন ভাল মানুষ নেই।'),
  ('bn.bengali', 11, 79, 'তারা বলল ু তুমি তো জানই, তোমার কন্যাদের নিয়ে আমাদের কোন গরজ নেই। আর আমরা কি চাই, তাও তুমি অবশ্যই জান।'),
  ('bn.bengali', 11, 80, 'লূত (আঃ) বললেন-হায়, তোমাদের বিরুদ্ধে যদি আমার শক্তি থাকত অথবা আমি কোন সূদৃঢ় আশ্রয় গ্রহণ করতে সক্ষম হতাম।'),
  ('bn.bengali', 11, 81, 'মেহমান ফেরেশতাগন বলল-হে লূত (আঃ) আমরা তোমাদের পালনকর্তার পক্ষ হতে প্রেরিত ফেরেশতা। এরা কখনো তোমার দিকে পৌঁছাতে পারবে না। ব্যস তুমি কিছুটা রাত থাকতে থাকতে নিজের লোকজন নিয়ে বাইরে চলে যাও। আর তোমাদের কেউ যেন পিছনে ফিরে না তাকায়। কিন্তু তোমার স্ত্রী নিশ্চয় তার উপরও তা আপতিত হবে, যা ওদের উপর আপতিত হবে। ভোর বেলাই তাদের প্রতিশ্রুতির সময়, ভোর কি খুব নিকটে নয়?'),
  ('bn.bengali', 11, 82, 'অবশেষে যখন আমার হুকুম এসে পৌঁছাল, তখন আমি উক্ত জনপদকে উপরকে নীচে করে দিলাম এবং তার উপর স্তরে স্তরে কাঁকর পাথর বর্ষণ করলাম।'),
  ('bn.bengali', 11, 83, 'যার প্রতিটি তোমার পালনকর্তার নিকট চিহ্নিত ছিল। আর সেই পাপিষ্ঠদের থেকে খুব দূরেও নয়।'),
  ('bn.bengali', 11, 84, 'আর মাদইয়ানবাসীদের প্রতি তাদের ভাই শোয়ায়েব (আঃ) কে প্রেরণ করেছি। তিনি বললেন-হে আমার কওম! আল্লাহর বন্দেগী কর, তিনি ছাড়া আমাদের কোন মাবুদ নাই। আর পরিমাপে ও ওজনে কম দিও না, আজ আমি তোমাদেরকে ভাল অবস্থায়ই দেখছি, কিন্তু আমি তোমাদের উপর এমন একদিনের আযাবের আশঙ্কা করছি যেদিনটি পরিবেষ্টনকারী।'),
  ('bn.bengali', 11, 85, 'আর হে আমার জাতি, ন্যায়নিষ্ঠার সাথে ঠিকভাবে পরিমাপ কর ও ওজন দাও এবং লোকদের জিনিসপত্রে কোনরূপ ক্ষতি করো না, আর পৃথিবীতে ফাসাদ করে বেড়াবে না।'),
  ('bn.bengali', 11, 86, 'আল্লাহ প্রদত্ত উদ্ধৃত্ত তোমাদের জন্য উত্তম, যদি তোমরা ঈমানদার হও, আর আমি তো তোমাদের উপর সদা পর্যবেক্ষণকারী নই।'),
  ('bn.bengali', 11, 87, 'তারা বলল-হে শোয়ায়েব (আঃ) আপনার নামায কি আপনাকে ইহাই শিক্ষা দেয় যে, আমরা ঐসব উপাস্যদেরকে পরিত্যাগ করব আমাদের বাপ-দাদারা যাদের উপাসনা করত? অথবা আমাদের ধন-সম্পদে ইচ্ছামত যা কিছু করে থাকি, তা ছেড়ে দেব? আপনি তো একজন খাস মহৎ ব্যক্তি ও সৎপথের পথিক।'),
  ('bn.bengali', 11, 88, 'শোয়ায়েব (আঃ) বললেন-হে দেশবাসী, তোমরা কি মনে কর! আমি যদি আমার পরওয়ারদেগারের পক্ষ হতে সুস্পষ্ট দলীলের উপর কায়েম থাকি আর তিনি যদি নিজের তরফ হতে আমাকে উত্তম রিযিক দান করে থাকেন, (তবে কি আমি তাঁর হুকুম অমান্য করতে পারি?) আর আমি চাই না যে তোমাদেরকে যা ছাড়াতে চাই পরে নিজেই সে কাজে লিপ্ত হব, আমি তো যথাসাধ্য শোধরাতে চাই। আল্লাহর মদদ দ্বারাই কিন্তু কাজ হয়ে থাকে, আমি তাঁর উপরই নির্ভর করি এবং তাঁরই প্রতি ফিরে যাই।'),
  ('bn.bengali', 11, 89, 'আর হে আমার জাতি! আমার সাথে জিদ করে তোমরা নূহ বা হুদ অথবা সালেহ (আঃ) এর কওমের মত নিজেদের উপর আযাব ডেকে আনবে না। আর লূতের জাতি তো তোমাদের থেকে খুব দূরে নয়।'),
  ('bn.bengali', 11, 90, 'আর তোমাদের পালনকর্তার কাছে মার্জনা চাও এবং তাঁরই পানে ফিরে এসো নিশ্চয়ই আমার পরওয়ারদেগার খুবই মেহেরবান অতিস্নেহময়।'),
  ('bn.bengali', 11, 91, 'তারা বলল-হে শোয়ায়েব (আঃ) আপনি যা বলেছেন তার অনেক কথাই আমরা বুঝি নাই, আমারা তো আপনাকে আমাদের মধ্যে দূর্বল ব্যক্তি রূপে মনে করি। আপনার ভাই বন্ধুরা না থাকলে আমরা আপনাকে প্রস্তরাঘাতে হত্যা করতাম। আমাদের দৃষ্টিতে আপনি কোন মর্যাদাবান ব্যক্তি নন।'),
  ('bn.bengali', 11, 92, 'শোয়ায়েব (আঃ) বলেন-হে আমার জাতি, আমার ভাই বন্ধুরা কি তোমাদের কাছে আল্লাহর চেয়ে প্রভাবশালী? আর তোমরা তাকে বিস্মৃত হয়ে পেছনে ফেলে রেখেছ, নিশ্চয় তোমাদের কার্যকলাপ আমার পালনকর্তার আয়ত্তে রয়েছে।'),
  ('bn.bengali', 11, 93, 'আর হে আমার জাতি, তোমরা নিজ স্থানে কাজ করে যাও, আমিও কাজ করছি, অচিরেই জানতে পারবে কার উপর অপমানকর আযাব আসে আর কে মিথ্যাবাদী? আর তোমরাও অপেক্ষায় থাক, আমিও তোমাদের সাথে অপেক্ষায় রইলাম।'),
  ('bn.bengali', 11, 94, 'আর আমার হুকুম যখন এল, আমি শোয়ায়েব (আঃ) ও তাঁর সঙ্গী ঈমানদারগণকে নিজ রহমতে রক্ষা করি আর পাপিষ্ঠদের উপর বিকট গর্জন পতিত হলো। ফলে ভোর না হতেই তারা নিজেদের ঘরে উপুড় হয়ে পড়ে রইল।'),
  ('bn.bengali', 11, 95, 'যেন তারা সেখানে কখনো বসবাসই করে নাই। জেনে রাখ, সামুদের প্রতি অভিসম্পাতের মত মাদইয়ানবাসীর উপরেও অভিসম্পাত।'),
  ('bn.bengali', 11, 96, 'আর আমি মূসা (আঃ) কে প্রেরণ করি আমার নিদর্শনাদি ও সুস্পষ্ট সনদসহ;'),
  ('bn.bengali', 11, 97, 'ফেরাউন ও তার পারিষদবর্গের কাছে, তবুও তারা ফেরাউনের হুকুমে চলতে থাকে, অথচ ফেরাউনের কোন কথা ন্যায় সঙ্গত ছিল না।'),
  ('bn.bengali', 11, 98, 'কেয়ামতের দিন সে তার জাতির লোকদের আগে আগে থাকবে এবং তাদেরকে জাহান্নামের আগুনে পৌঁছে দিবে। আর সেটা অতীব নিকৃষ্ট স্থান, সেখানে তারা পৌঁছেছে।।'),
  ('bn.bengali', 11, 99, 'আর এ জগতেও তাদের পেছনে লানত রয়েছে এবং কিয়ামতের দিনেও; অত্যন্ত জঘন্য প্রতিফল, যা তারা পেয়েছে।'),
  ('bn.bengali', 11, 100, 'এ হচ্ছে কয়েকটি জনপদের সামান্য ইতিবৃত্ত, যা আমি আপনাকে শোনাচ্ছি। তন্মধ্যে কোন কোনটি এখনও বর্তমান আছে আর কোন কোনটির শিকড় কেটে দেয়া হয়েছে।'),
  ('bn.bengali', 11, 101, 'আমি কিন্তু তাদের প্রতি জুলুম করি নাই বরং তারা নিজেরাই নিজের উপর অবিচার করেছে। ফলে আল্লাহকে বাদ দিয়ে তারা যেসব মাবুদকে ডাকতো আপনার পালনকর্তার হুকুম যখন এসে পড়ল, তখন কেউ কোন কাজে আসল না। তারা শুধু বিপর্যয়ই বৃদ্ধি করল।'),
  ('bn.bengali', 11, 102, 'আর তোমার পরওয়ারদেগার যখন কোন পাপপূর্ণ জনপদকে ধরেন, তখন এমনিভাবেই ধরে থাকেন। নিশ্চয় তাঁর পাকড়াও খুবই মারাত্নক, বড়ই কঠোর।'),
  ('bn.bengali', 11, 103, 'নিশ্চয় ইহার মধ্যে নিদর্শন রয়েছে এমন প্রতিটি মানুষের জন্য যে আখেরাতের আযাবকে ভয় করে। উহা এমন একদিন, যে দিন সব মানুষেই সমবেত হবে, সেদিনটি যে হাযিরের দিন।'),
  ('bn.bengali', 11, 104, 'আর আমি যে উহা বিলম্বিত করি, তা শুধু একটি ওয়াদার কারণে যা নির্ধারিত রয়েছে।'),
  ('bn.bengali', 11, 105, 'যেদিন তা আসবে সেদিন আল্লাহর অনুমতি ছাড়া কেউ কোন কথা বলতে পারে না। অতঃপর কিছু লোক হবে হতভাগ্য আর কিছু লোক সৌভাগ্যবান।'),
  ('bn.bengali', 11, 106, 'অতএব যারা হতভাগ্য তারা দোযখে যাবে, সেখানে তারা আর্তনাদ ও চিৎকার করতে থাকবে।'),
  ('bn.bengali', 11, 107, 'তারা সেখানে চিরকাল থাকবে, যতদিন আসমান ও যমীন বর্তমান থাকবে। তবে তোমার প্রতিপালক অন্য কিছু ইচ্ছা করলে ভিন্ন কথা। নিশ্চয় তোমার পরওয়ারদেগার যা ইচ্ছা করতে পারেন।'),
  ('bn.bengali', 11, 108, 'আর যারা সৌভাগ্যবান তারা বেহেশতের মাঝে, সেখানেই চিরদিন থাকবে, যতদিন আসমান ও যমীন বর্তমান থাকবে। তবে তোমার প্রভু অন্য কিছু ইচ্ছা করলে ভিন্ন কথা। এ দানের ধারাবাহিকতা কখনো ছিন্ন হওয়ার নয়।'),
  ('bn.bengali', 11, 109, 'অতএব, তারা যেসবের উপাসনা করে তুমি সে ব্যাপারে কোনরূপ ধোঁকায় পড়বে না। তাদের পূর্ববর্তী বাপ-দাদারা যেমন পূজা উপাসনা করত, এরাও তেমন করছে। আর নিশ্চয় আমি তাদেরকে আযাবের ভাগ কিছু মাত্রও কম না করেই পুরোপুরি দান করবো।'),
  ('bn.bengali', 11, 110, 'আর আমি মূসা (আঃ)-কে অবশ্যই কিতাব দিয়েছিলাম অতঃপর তাতে বিরোধ সৃষ্টি হল; বলাবাহুল্য তোমার পালনকর্তার পক্ষ হতে, একটি কথা যদি আগেই বলা না হত, তাহলে তাদের মধ্যে চুড়ান্ত ফয়সালা হয়ে যেত তারা এ ব্যাপারে এমনই সন্দেহ প্রবণ যে, কিছুতেই নিশ্চিত হতে পারছে না।'),
  ('bn.bengali', 11, 111, 'আর যত লোকই হোক না কেন, যখন সময় হবে, তোমার প্রভু তাদের সকলেরই আমলের প্রতিদান পুরোপুরি দান করবেন। নিশ্চয় তিনি তাদের যাবতীয় কার্যকলাপের খবর রাখেন।'),
  ('bn.bengali', 11, 112, 'অতএব, তুমি এবং তোমার সাথে যারা তওবা করেছে সবাই সোজা পথে চলে যাও-যেমন তোমায় হুকুম দেয়া হয়েছে এবং সীমা লঙ্ঘন করবে না, তোমরা যা কিছু করছ, নিশ্চয় তিনি তার প্রতি দৃষ্টি রাখেন।'),
  ('bn.bengali', 11, 113, 'আর পাপিষ্ঠদের প্রতি ঝুঁকবে না। নতুবা তোমাদেরকেও আগুনে ধরবে। আর আল্লাহ ব্যতীত তোমাদের কোন বন্ধু নাই। অতএব কোথাও সাহায্য পাবে না।'),
  ('bn.bengali', 11, 114, 'আর দিনের দুই প্রান্তেই নামায ঠিক রাখবে, এবং রাতের প্রান্তভাগে পূর্ণ কাজ অবশ্যই পাপ দূর করে দেয়, যারা স্মরণ রাখে তাদের জন্য এটি এক মহা স্মারক।'),
  ('bn.bengali', 11, 115, 'আর ধৈর্য্যধারণ কর, নিশ্চয়ই আল্লাহ পূণ্যবানদের প্রতিদান বিনষ্ট করেন না।'),
  ('bn.bengali', 11, 116, 'কাজেই, তোমাদের পূর্ববতী জাতি গুলির মধ্যে এমন সৎকর্মশীল কেন রইল না, যারা পৃথিবীতে বিপর্যয় সৃষ্টি করতে বাধা দিত; তবে মুষ্টিমেয় লোক ছিল যাদেরকে আমি তাদের মধ্য হতে রক্ষা করেছি। আর পাপিষ্ঠরা তো ভোগ বিলাসে মত্ত ছিল যার সামগ্রী তাদেরকে যথেষ্ট দেয়া হয়েছিল। আসলে তারা ছিল মহা অপরাধী।'),
  ('bn.bengali', 11, 117, 'আর তোমার পালনকর্তা এমন নন যে, জনবসতিগুলোকে অন্যায়ভাবে ধ্বংস করে দেবেন, সেখানকার লোকেরা সৎকর্মশীল হওয়া সত্ত্বেও।'),
  ('bn.bengali', 11, 118, 'আর তোমার পালনকর্তা যদি ইচ্ছা করতেন, তবে অবশ্যই সব মানুষকে একই জাতিসত্তায় পরিনত করতে পারতেন আর তারা বিভিন্ন ভাগে বিভক্ত হতো না।'),
  ('bn.bengali', 11, 119, 'তোমার পালনকর্তা যাদের উপর রহমত করেছেন, তারা ব্যতীত সবাই চিরদিন মতভেদ করতেই থাকবে এবং এজন্যই তাদেরকে সৃষ্টি করেছেন। আর তোমার আল্লাহর কথাই পূর্ণ হল যে, অবশ্যই আমি জাহান্নামকে জ্বিন ও মানুষ দ্বারা একযোগে ভর্তি করব।'),
  ('bn.bengali', 11, 120, 'আর আমি রসূলগণের সব বৃত্তান্তই তোমাকে বলছি, যদ্দ্বারা তোমার অন্তরকে মজবুত করছি। আর এভাবে তোমার নিকট মহাসত্য এবং ঈমানদারদের জন্য নসীহত ও স্বরণীয় বিষয়বস্তু এসেছে।'),
  ('bn.bengali', 11, 121, 'আর যারা ঈমান আনে না, তাদেরকে বলে দাও যে, তোমরা নিজ নিজ অবস্থায় কাজ করে যাও আমরাও কাজ করে যাই।'),
  ('bn.bengali', 11, 122, 'এবং তোমরাও অপেক্ষা করে থাক, আমরাও অপেক্ষায় রইলাম।'),
  ('bn.bengali', 11, 123, 'আর আল্লাহর কাছেই আছে আসমান ও যমীনের গোপন তথ্য; আর সকল কাজের প্রত্যাবর্তন তাঁরই দিকে; অতএব, তাঁরই বন্দেগী কর এবং তাঁর উপর ভরসা রাখ, আর তোমাদের কার্যকলাপ সম্বন্ধে তোমার পালনকর্তা কিন্তু বে-খবর নন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 11, 1, 'Alif. Lam. Ra. (This is) a Scripture the revelations whereof are perfected and then expounded. (It cometh) from One Wise, Informed,'),
  ('en.pickthall', 11, 2, '(Saying): Serve none but Allah. Lo! I am unto you from Him a warner and a bringer of good tidings.'),
  ('en.pickthall', 11, 3, 'And (bidding you): Ask pardon of your Lord and turn to Him repentant. He will cause you to enjoy a fair estate until a time appointed. He giveth His bounty unto every bountiful one. But if ye turn away, lo! (then) I fear for you the retribution of an awful Day.'),
  ('en.pickthall', 11, 4, 'Unto Allah is your return, and He is Able to do all things.'),
  ('en.pickthall', 11, 5, 'Lo! now they fold up their breasts that they may hide (their thoughts) from Him. At the very moment when they cover themselves with their clothing, Allah knoweth that which they keep hidden and that which they proclaim. Lo! He is Aware of what is in the breasts (of men).'),
  ('en.pickthall', 11, 6, 'And there is not a beast in the earth but the sustenance thereof dependeth on Allah. He knoweth its habitation and its repository. All is in a clear Record.'),
  ('en.pickthall', 11, 7, 'And He it is Who created the heavens and the earth in six Days - and His Throne was upon the water - that He might try you, which of you is best in conduct. Yet if thou (O Muhammad) sayest: Lo! ye will be raised again after death! those who disbelieve will surely say: This is naught but mere magic.'),
  ('en.pickthall', 11, 8, 'And if We delay for them the doom until a reckoned time, they will surely say: What withholdeth it? Verily on the day when it cometh unto them, it cannot be averted from them, and that which they derided will surround them.'),
  ('en.pickthall', 11, 9, 'And if we cause man to taste some mercy from Us and afterward withdraw it from him, lo! he is despairing, thankless.'),
  ('en.pickthall', 11, 10, 'And if We cause him to taste grace after some misfortune that had befallen him, he saith: The ills have gone from me. Lo! he is exultant, boastful;'),
  ('en.pickthall', 11, 11, 'Save those who persevere and do good works. Theirs will be forgiveness and a great reward.'),
  ('en.pickthall', 11, 12, 'A likely thing, that thou wouldst forsake aught of that which hath been revealed unto thee, and that thy breast should be straitened for it, because they say: Why hath not a treasure been sent down for him, or an angel come with him? Thou art but a warner, and Allah is in charge of all things.'),
  ('en.pickthall', 11, 13, 'Or they say: He hath invented it. Say: Then bring ten surahs, the like thereof, invented, and call on everyone ye can beside Allah, if ye are truthful!'),
  ('en.pickthall', 11, 14, 'And if they answer not your prayer, then know that it is revealed only in the knowledge of Allah; and that there is no Allah save Him. Will ye then be (of) those who surrender?'),
  ('en.pickthall', 11, 15, 'Whoso desireth the life of the world and its pomp, We shall repay them their deeds herein, and therein they will not be wronged.'),
  ('en.pickthall', 11, 16, 'Those are they for whom is naught in the Hereafter save the Fire. (All) that they contrive here is vain and (all) that they are wont to do is fruitless.'),
  ('en.pickthall', 11, 17, 'Is he (to be counted equal with them) who relieth on a clear proof from his Lord, and a witness from Him reciteth it, and before it was the Book of Moses, an example and a mercy? Such believe therein, and whoso disbelieveth therein of the clans, the Fire is his appointed place. So be not thou in doubt concerning it. Lo! it is the Truth from thy Lord; but most of mankind believe not.'),
  ('en.pickthall', 11, 18, 'Who doeth greater wrong than he who inventeth a lie concerning Allah? Such will be brought before their Lord, and the witnesses will say: These are they who lied concerning their Lord. Now the curse of Allah is upon wrong-doers,'),
  ('en.pickthall', 11, 19, 'Who debar (men) from the way of Allah and would have it crooked, and who are disbelievers in the Hereafter.'),
  ('en.pickthall', 11, 20, 'Such will not escape in the earth, nor have they any protecting friends beside Allah. For them the torment will be double. They could not bear to hear, and they used not to see.'),
  ('en.pickthall', 11, 21, 'Such are they who have lost their souls, and that which they used to invent hath failed them.'),
  ('en.pickthall', 11, 22, 'Assuredly in the Hereafter they will be the greatest losers.'),
  ('en.pickthall', 11, 23, 'Lo! those who believe and do good works and humble themselves before their Lord: such are rightful owners of the Garden; they will abide therein.'),
  ('en.pickthall', 11, 24, 'The similitude of the two parties is as the blind and the deaf and the seer and the hearer. Are they equal in similitude? Will ye not then be admonished?'),
  ('en.pickthall', 11, 25, 'And We sent Noah unto his folk (and he said): Lo! I am a plain warner unto you.'),
  ('en.pickthall', 11, 26, 'That ye serve none, save Allah. Lo! I fear for you the retribution of a painful Day.'),
  ('en.pickthall', 11, 27, 'The chieftains of his folk, who disbelieved, said: We see thee but a mortal like us, and we see not that any follow thee save the most abject among us, without reflection. We behold in you no merit above us - nay, we deem you liars.'),
  ('en.pickthall', 11, 28, 'He said: O my people! Bethink you, if I rely on a clear proof from my Lord and there hath come unto me a mercy from His presence, and it hath been made obscure to you, can we compel you to accept it when ye are averse thereto?'),
  ('en.pickthall', 11, 29, 'And O my people! I ask of you no wealth therefor. My reward is the concern only of Allah, and I am not going to thrust away those who believe - Lo! they have to meet their Lord! - but I see you a folk that are ignorant.'),
  ('en.pickthall', 11, 30, 'And, O my people! who would deliver me from Allah if I thrust them away? Will ye not then reflect?'),
  ('en.pickthall', 11, 31, 'I say not unto you: "I have the treasures of Allah" nor "I have knowledge of the Unseen," nor say I: "Lo! I am an angel!" Nor say I unto those whom your eyes scorn that Allah will not give them good - Allah knoweth best what is in their hearts - Lo! then indeed I should be of the wrong-doers.'),
  ('en.pickthall', 11, 32, 'They said: O Noah! Thou hast disputed with us and multiplied disputation with us; now bring upon us that wherewith thou threatenest us, if thou art of the truthful.'),
  ('en.pickthall', 11, 33, 'He said: Only Allah will bring it upon you if He will, and ye can by no means escape.'),
  ('en.pickthall', 11, 34, 'My counsel will not profit you if I were minded to advise you, if Allah\'s will is to keep you astray. He is your Lord and unto Him ye will be brought back.'),
  ('en.pickthall', 11, 35, 'Or say they (again): He hath invented it? Say: If I have invented it, upon me be my crimes, but I am innocent of (all) that ye commit.'),
  ('en.pickthall', 11, 36, 'And it was inspired in Noah, (saying): No-one of thy folk will believe save him who hath believed already. Be not distressed because of what they do.'),
  ('en.pickthall', 11, 37, 'Build the ship under Our eyes and by Our inspiration, and speak not unto Me on behalf of those who do wrong. Lo! they will be drowned.'),
  ('en.pickthall', 11, 38, 'And he was building the ship, and every time that chieftains of his people passed him, they made mock of him. He said: Though ye make mock of Us, yet We mock at you even as ye mock;'),
  ('en.pickthall', 11, 39, 'And ye shall know to whom a punishment that will confound him cometh, and upon whom a lasting doom will fall.'),
  ('en.pickthall', 11, 40, '(Thus it was) till, when Our commandment came to pass and the oven gushed forth water, We said: Load therein two of every kind, a pair (the male and female), and thy household, save him against whom the word hath gone forth already, and those who believe. And but a few were they who believed with him.'),
  ('en.pickthall', 11, 41, 'And he said: Embark therein! In the name of Allah be its course and its mooring. Lo! my Lord is Forgiving, Merciful.'),
  ('en.pickthall', 11, 42, 'And it sailed with them amid waves like mountains, and Noah cried unto his son - and he was standing aloof - O my son! Come ride with us, and be not with the disbelievers.'),
  ('en.pickthall', 11, 43, 'He said: I shall betake me to some mountain that will save me from the water. (Noah) said: This day there is none that saveth from the commandment of Allah save him on whom He hath had mercy. And the wave came in between them, so he was among the drowned.'),
  ('en.pickthall', 11, 44, 'And it was said: O earth! Swallow thy water and, O sky! be cleared of clouds! And the water was made to subside. And the commandment was fulfilled. And it (the ship) came to rest upon (the mount) Al-Judi and it was said: A far removal for wrongdoing folk!'),
  ('en.pickthall', 11, 45, 'And Noah cried unto his Lord and said: My Lord! Lo! my son is of my household! Surely Thy promise is the truth and Thou are the Most Just of Judges.'),
  ('en.pickthall', 11, 46, 'He said: O Noah! Lo! he is not of thy household; lo! he is of evil conduct, so ask not of Me that whereof thou hast no knowledge. I admonish thee lest thou be among the ignorant.'),
  ('en.pickthall', 11, 47, 'He said: My Lord! Lo! in Thee do I seek refuge (from the sin) that I should ask of Thee that whereof I have no knowledge. Unless Thou forgive me and have mercy on me I shall be among the lost.'),
  ('en.pickthall', 11, 48, 'It was said (unto him): O Noah! Go thou down (from the mountain) with peace from Us and blessings upon thee and some nations (that will spring) from those with thee. (There will be other) nations unto whom We shall give enjoyment a long while and then a painful doom from Us will overtake them.'),
  ('en.pickthall', 11, 49, 'This is of the tidings of the Unseen which We inspire in thee (Muhammad). Thou thyself knewest it not, nor did thy folk (know it) before this. Then have patience. Lo! the sequel is for those who ward off (evil).'),
  ('en.pickthall', 11, 50, 'And unto (the tribe of) A\'ad (We sent) their brother, Hud. He said: O my people! Serve Allah! Ye have no other Allah save Him. Lo! ye do but invent.'),
  ('en.pickthall', 11, 51, 'O my people! I ask of you no reward for it. Lo! my reward is the concern only of Him Who made me. Have ye then no sense?'),
  ('en.pickthall', 11, 52, 'And, O my people! Ask forgiveness of your Lord, then turn unto Him repentant; He will cause the sky to rain abundance on you and will add unto you strength to your strength. Turn not away, guilty!'),
  ('en.pickthall', 11, 53, 'They said: O Hud! Thou hast brought us no clear proof and we are not going to forsake our gods on thy (mere) saying, and we are not believers in thee.'),
  ('en.pickthall', 11, 54, 'We say naught save that one of our gods hath possessed thee in an evil way. He said: I call Allah to witness, and do ye (too) bear witness, that I am innocent of (all) that ye ascribe as partners (to Allah)'),
  ('en.pickthall', 11, 55, 'Beside Him. So (try to) circumvent me, all of you, give me no respite.'),
  ('en.pickthall', 11, 56, 'Lo! I have put my trust in Allah, my Lord and your Lord. Not an animal but He doth grasp it by the forelock! Lo! my Lord is on a straight path.'),
  ('en.pickthall', 11, 57, 'And if ye turn away, still I have conveyed unto you that wherewith I was sent unto you, and my Lord will set in place of you a folk other than you. Ye cannot injure Him at all. Lo! my Lord is Guardian over all things.'),
  ('en.pickthall', 11, 58, 'And when Our commandment came to pass We saved Hud and those who believed with him by a mercy from Us; We saved them from a harsh doom.'),
  ('en.pickthall', 11, 59, 'And such were A\'ad. They denied the revelations of their Lord and flouted His messengers and followed the command of every froward potentate.'),
  ('en.pickthall', 11, 60, 'And a curse was made to follow them in the world and on the Day of Resurrection. Lo! A\'ad disbelieved in their Lord. A far removal for A\'ad, the folk of Hud!'),
  ('en.pickthall', 11, 61, 'And unto (the tribe of) Thamud (We sent) their brother Salih. He said: O my people! Serve Allah, Ye have no other Allah save Him. He brought you forth from the earth and hath made you husband it. So ask forgiveness of Him and turn unto Him repentant. Lo! my Lord is Nigh, Responsive.'),
  ('en.pickthall', 11, 62, 'They said: O Salih! Thou hast been among us hitherto as that wherein our hope was placed. Dost thou ask us not to worship what our fathers worshipped? Lo! we verily are in grave doubt concerning that to which thou callest us.'),
  ('en.pickthall', 11, 63, 'He said: O my people! Bethink you: if I am (acting) on clear proof from my Lord and there hath come unto me a mercy from Him, who will save me from Allah if I disobey Him? Ye would add to me naught save perdition.'),
  ('en.pickthall', 11, 64, 'O my people! This is the camel of Allah, a token unto you, so suffer her to feed in Allah\'s earth, and touch her not with harm lest a near torment seize you.'),
  ('en.pickthall', 11, 65, 'But they hamstrung her, and then he said: Enjoy life in your dwelling-place three days! This is a threat that will not be belied.'),
  ('en.pickthall', 11, 66, 'So, when Our commandment came to pass, We saved Salih, and those who believed with him, by a mercy from Us, from the ignominy of that day. Lo, thy Lord! He is the Strong, the Mighty.'),
  ('en.pickthall', 11, 67, 'And the (awful) Cry overtook those who did wrong, so that morning found them prostrate in their dwellings,'),
  ('en.pickthall', 11, 68, 'As though they had not dwelt there. Lo! Thamud disbelieved in their Lord. A far removal for Thamud!'),
  ('en.pickthall', 11, 69, 'And Our messengers cam unto Abraham with good news. They said: Peace! He answered: Peace! and delayed not to bring a roasted calf.'),
  ('en.pickthall', 11, 70, 'And when he saw their hands reached not to it, he mistrusted them and conceived a fear of them. They said: Fear not! Lo! we are sent unto the folk of Lot.'),
  ('en.pickthall', 11, 71, 'And his wife, standing by laughed when We gave her good tidings (of the birth) of Isaac, and, after Isaac, of Jacob.'),
  ('en.pickthall', 11, 72, 'She said: Oh woe is me! Shall I bear a child when I am an old woman, and this my husband is an old man? Lo! this is a strange thing!'),
  ('en.pickthall', 11, 73, 'They said: Wonderest thou at the commandment of Allah? The mercy of Allah and His blessings be upon you, O people of the house! Lo! He is Owner of Praise, Owner of Glory!'),
  ('en.pickthall', 11, 74, 'And when the awe departed from Abraham, and the glad news reached him, he pleaded with Us on behalf of the folk of Lot.'),
  ('en.pickthall', 11, 75, 'Lo! Abraham was mild, imploring, penitent.'),
  ('en.pickthall', 11, 76, '(It was said) O Abraham! Forsake this! Lo! thy Lord\'s commandment hath gone forth, and lo! there cometh unto them a doom which cannot be repelled.'),
  ('en.pickthall', 11, 77, 'And when Our messengers came unto Lot, he was distressed and knew not how to protect them. He said: This is a distressful day.'),
  ('en.pickthall', 11, 78, 'And his people came unto him, running towards him - and before then they used to commit abominations - He said: O my people! Here are my daughters! They are purer for you. Beware of Allah, and degrade me not in (the person of) my guests. Is there not among you any upright man?'),
  ('en.pickthall', 11, 79, 'They said: Well thou knowest that we have no right to thy daughters, and well thou knowest what we want.'),
  ('en.pickthall', 11, 80, 'He said: Would that I had strength to resist you or had some strong support (among you)!'),
  ('en.pickthall', 11, 81, '(The messengers) said: O Lot! Lo! we are messengers of thy Lord; they shall not reach thee. So travel with thy people in a part of the night, and let not one of you turn round - (all) save thy wife. Lo! that which smiteth them will smite her (also). Lo! their tryst is (for) the morning. Is not the morning nigh?'),
  ('en.pickthall', 11, 82, 'So when Our commandment came to pass We overthrew (that township) and rained upon it stones of clay, one after another,'),
  ('en.pickthall', 11, 83, 'Marked with fire in the providence of thy Lord (for the destruction of the wicked). And they are never far from the wrong-doers.'),
  ('en.pickthall', 11, 84, 'And unto Midian (We sent) their brother Shu\'eyb. He said: O my people! Serve Allah. Ye have no other Allah save Him! And give not short measure and short weight. Lo! I see you well-to-do, and lo! I fear for you the doom of a besetting Day.'),
  ('en.pickthall', 11, 85, 'O my people! Give full measure and full weight in justice, and wrong not people in respect of their goods. And do not evil in the earth, causing corruption.'),
  ('en.pickthall', 11, 86, 'That which Allah leaveth with you is better for you if ye are believers; and I am not a keeper over you.'),
  ('en.pickthall', 11, 87, 'They said: O Shu\'eyb! Doth thy way of prayer command thee that we should forsake that which our fathers (used to) worship, or that we (should leave off) doing what we will with our own property. Lo! thou art the mild, the guide to right behaviour.'),
  ('en.pickthall', 11, 88, 'He said: O my people! Bethink you: if I am (acting) on a clear proof from my Lord and He sustaineth me with fair sustenance from Him (how can I concede aught to you)? I desire not to do behind your backs that which I ask you not to do. I desire naught save reform so far as I am able. My welfare is only in Allah. In Him I trust and unto Him I turn (repentant).'),
  ('en.pickthall', 11, 89, 'And, O my people! Let not the schism with me cause you to sin so that there befall you that which befell the folk of Noah and the folk of Hud, and the folk of Salih; and the folk of Lot are not far off from you.'),
  ('en.pickthall', 11, 90, 'Ask pardon of your Lord and then turn unto Him (repentant). Lo! my Lord is Merciful, Loving.'),
  ('en.pickthall', 11, 91, 'They said: O Shu\'eyb! We understand not much of that thou tellest, and lo! we do behold thee weak among us. But for thy family, we should have stoned thee, for thou art not strong against us.'),
  ('en.pickthall', 11, 92, 'He said: O my people! Is my family more to be honoured by you than Allah? and ye put Him behind you, neglected! Lo! my Lord surroundeth what ye do.'),
  ('en.pickthall', 11, 93, 'And, O my people! Act according to your power, lo! I (too) am acting. Ye will soon know on whom there cometh a doom that will abase him, and who it is that lieth. And watch! Lo! I am a watcher with you.'),
  ('en.pickthall', 11, 94, 'And when Our commandment came to pass We saved Shu\'eyb and those who believed with him by a mercy from Us; and the (Awful) Cry seized those who did injustice, and morning found them prostrate in their dwellings,'),
  ('en.pickthall', 11, 95, 'As though they had not dwelt there. A far removal for Midian, even as Thamud had been removed afar!'),
  ('en.pickthall', 11, 96, 'And verily We sent Moses with Our revelations and a clear warrant'),
  ('en.pickthall', 11, 97, 'Unto Pharaoh and his chiefs, but they did follow the command of Pharaoh, and the command of Pharaoh was no right guide.'),
  ('en.pickthall', 11, 98, 'He will go before his people on the Day of Resurrection and will lead them to the Fire for watering-place. Ah, hapless is the watering-place (whither they are) led.'),
  ('en.pickthall', 11, 99, 'A curse is made to follow them in the world and on the Day of Resurrection. Hapless is the gift (that will be) given (them).'),
  ('en.pickthall', 11, 100, 'That is (something) of the tidings of the townships (which were destroyed of old). We relate it unto thee (Muhammad). Some of them are standing and some (already) reaped.'),
  ('en.pickthall', 11, 101, 'We wronged them not, but they did wrong themselves; and their gods on whom they call beside Allah availed them naught when came thy Lord\'s command; they added to them naught save ruin.'),
  ('en.pickthall', 11, 102, 'Even thus is the grasp of thy Lord when He graspeth the townships while they are doing wrong. Lo! His grasp is painful, very strong.'),
  ('en.pickthall', 11, 103, 'Lo! herein verily there is a portent for those who fear the doom of the Hereafter. That is a day unto which mankind will be gathered, and that is a day that will be witnessed.'),
  ('en.pickthall', 11, 104, 'And We defer it only to a term already reckoned.'),
  ('en.pickthall', 11, 105, 'On the day when it cometh no soul will speak except by His permission; some among them will be wretched, (others) glad.'),
  ('en.pickthall', 11, 106, 'As for those who will be wretched (on that day) they will be in the Fire; sighing and wailing will be their portion therein,'),
  ('en.pickthall', 11, 107, 'Abiding there so long as the heavens and the earth endure save for that which thy Lord willeth. Lo! thy Lord is Doer of what He will.'),
  ('en.pickthall', 11, 108, 'And as for those who will be glad (that day) they will be in the Garden, abiding there so long as the heavens and the earth endure save for that which thy Lord willeth: a gift unfailing.'),
  ('en.pickthall', 11, 109, 'So be not thou in doubt concerning that which these (folk) worship. They worship only as their fathers worshipped aforetime. Lo! we shall pay them their whole due unabated.'),
  ('en.pickthall', 11, 110, 'And we verily gave unto Moses the Scripture, and there was strife thereupon; and had it not been for a Word that had already gone forth from thy Lord, the case would have been judged between them, and lo! they are in grave doubt concerning it.'),
  ('en.pickthall', 11, 111, 'And lo! unto each thy Lord will verily repay his works in full. Lo! He is Informed of what they do.'),
  ('en.pickthall', 11, 112, 'So tread thou the straight path as thou art commanded, and those who turn (unto Allah) with thee, and transgress not. Lo! He is Seer of what ye do.'),
  ('en.pickthall', 11, 113, 'And incline not toward those who do wrong lest the Fire touch you, and ye have no protecting friends against Allah, and afterward ye would not be helped.'),
  ('en.pickthall', 11, 114, 'Establish worship at the two ends of the day and in some watches of the night. Lo! good deeds annul ill-deeds. This is reminder for the mindful.'),
  ('en.pickthall', 11, 115, 'And have patience, (O Muhammad), for lo! Allah loseth not the wages of the good.'),
  ('en.pickthall', 11, 116, 'If only there had been among the generations before you men possessing a remnant (of good sense) to warn (their people) from corruption in the earth, as did a few of those whom We saved from them! The wrong-doers followed that by which they were made sapless, and were guilty.'),
  ('en.pickthall', 11, 117, 'In truth thy Lord destroyed not the townships tyrannously while their folk were doing right.'),
  ('en.pickthall', 11, 118, 'And if thy Lord had willed, He verily would have made mankind one nation, yet they cease not differing,'),
  ('en.pickthall', 11, 119, 'Save him on whom thy Lord hath mercy; and for that He did create them. And the Word of thy Lord hath been fulfilled: Verily I shall fill hell with the jinn and mankind together.'),
  ('en.pickthall', 11, 120, 'And all that We relate unto thee of the story of the messengers is in order that thereby We may make firm thy heart. And herein hath come unto thee the Truth and an exhortation and a reminder for believers.'),
  ('en.pickthall', 11, 121, 'And say unto those who believe not: Act according to your power. Lo! We (too) are acting.'),
  ('en.pickthall', 11, 122, 'And wait! Lo! We (too) are waiting.'),
  ('en.pickthall', 11, 123, 'And Allah\'s is the Invisible of the heavens and the earth, and unto Him the whole matter will be returned. So worship Him and put thy trust in Him. Lo! thy Lord is not unaware of what ye (mortals) do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 11, 1, 'A. L. R. (This is) a Book, with verses basic or fundamental (of established meaning), further explained in detail,- from One Who is Wise and Well-acquainted (with all things):'),
  ('en.yusufali', 11, 2, '(It teacheth) that ye should worship none but Allah. (Say): "Verily I am (sent) unto you from Him to warn and to bring glad tidings:'),
  ('en.yusufali', 11, 3, '"(And to preach thus), \'Seek ye the forgiveness of your Lord, and turn to Him in repentance; that He may grant you enjoyment, good (and true), for a term appointed, and bestow His abounding grace on all who abound in merit! But if ye turn away, then I fear for you the penalty of a great day:'),
  ('en.yusufali', 11, 4, '\'To Allah is your return, and He hath power over all things.\'"'),
  ('en.yusufali', 11, 5, 'Behold! they fold up their hearts, that they may lie hid from Him! Ah even when they cover themselves with their garments, He knoweth what they conceal, and what they reveal: for He knoweth well the (inmost secrets) of the hearts.'),
  ('en.yusufali', 11, 6, 'There is no moving creature on earth but its sustenance dependeth on Allah: He knoweth the time and place of its definite abode and its temporary deposit: All is in a clear Record.'),
  ('en.yusufali', 11, 7, 'He it is Who created the heavens and the earth in six Days - and His Throne was over the waters - that He might try you, which of you is best in conduct. But if thou wert to say to them, "Ye shall indeed be raised up after death", the Unbelievers would be sure to say, "This is nothing but obvious sorcery!"'),
  ('en.yusufali', 11, 8, 'If We delay the penalty for them for a definite term, they are sure to say, "What keeps it back?" Ah! On the day it (actually) reaches them, nothing will turn it away from them, and they will be completely encircled by that which they used to mock at!'),
  ('en.yusufali', 11, 9, 'If We give man a taste of Mercy from Ourselves, and then withdraw it from him, behold! he is in despair and (falls into) blasphemy.'),
  ('en.yusufali', 11, 10, 'But if We give him a taste of (Our) favours after adversity hath touched him, he is sure to say, "All evil has departed from me:" Behold! he falls into exultation and pride.'),
  ('en.yusufali', 11, 11, 'Not so do those who show patience and constancy, and work righteousness; for them is forgiveness (of sins) and a great reward.'),
  ('en.yusufali', 11, 12, 'Perchance thou mayest (feel the inclination) to give up a part of what is revealed unto thee, and thy heart feeleth straitened lest they say, "Why is not a treasure sent down unto him, or why does not an angel come down with him?" But thou art there only to warn! It is Allah that arrangeth all affairs!'),
  ('en.yusufali', 11, 13, 'Or they may say, "He forged it," Say, "Bring ye then ten suras forged, like unto it, and call (to your aid) whomsoever ye can, other than Allah!- If ye speak the truth!'),
  ('en.yusufali', 11, 14, '"If then they (your false gods) answer not your (call), know ye that this revelation is sent down (replete) with the knowledge of Allah, and that there is no god but He! will ye even then submit (to Islam)?"'),
  ('en.yusufali', 11, 15, 'Those who desire the life of the present and its glitter,- to them we shall pay (the price of) their deeds therein,- without diminution.'),
  ('en.yusufali', 11, 16, 'They are those for whom there is nothing in the Hereafter but the Fire: vain are the designs they frame therein, and of no effect and the deeds that they do!'),
  ('en.yusufali', 11, 17, 'Can they be (like) those who accept a Clear (Sign) from their Lord, and whom a witness from Himself doth teach, as did the Book of Moses before it,- a guide and a mercy? They believe therein; but those of the Sects that reject it,- the Fire will be their promised meeting-place. Be not then in doubt thereon: for it is the truth from thy Lord: yet many among men do not believe!'),
  ('en.yusufali', 11, 18, 'Who doth more wrong than those who invent a life against Allah? They will be turned back to the presence of their Lord, and the witnesses will say, "These are the ones who lied against their Lord! Behold! the Curse of Allah is on those who do wrong!-'),
  ('en.yusufali', 11, 19, '"Those who would hinder (men) from the path of Allah and would seek in it something crooked: these were they who denied the Hereafter!"'),
  ('en.yusufali', 11, 20, 'They will in no wise frustrate (His design) on earth, nor have they protectors besides Allah! Their penalty will be doubled! They lost the power to hear, and they did not see!'),
  ('en.yusufali', 11, 21, 'They are the ones who have lost their own souls: and the (fancies) they invented have left them in the lurch!'),
  ('en.yusufali', 11, 22, 'Without a doubt, these are the very ones who will lose most in the Hereafter!'),
  ('en.yusufali', 11, 23, 'But those who believe and work righteousness, and humble themselves before their Lord,- They will be companions of the gardens, to dwell therein for aye!'),
  ('en.yusufali', 11, 24, 'These two kinds (of men) may be compared to the blind and deaf, and those who can see and hear well. Are they equal when compared? Will ye not then take heed?'),
  ('en.yusufali', 11, 25, 'We sent Noah to his people (with a mission): "I have come to you with a Clear Warning:'),
  ('en.yusufali', 11, 26, '"That ye serve none but Allah: Verily I do fear for you the penalty of a grievous day."'),
  ('en.yusufali', 11, 27, 'But the chiefs of the Unbelievers among his people said: "We see (in) thee nothing but a man like ourselves: Nor do we see that any follow thee but the meanest among us, in judgment immature: Nor do we see in you (all) any merit above us: in fact we think ye are liars!"'),
  ('en.yusufali', 11, 28, 'He said: "O my people! See ye if (it be that) I have a Clear Sign from my Lord, and that He hath sent Mercy unto me from His own presence, but that the Mercy hath been obscured from your sight? shall we compel you to accept it when ye are averse to it?'),
  ('en.yusufali', 11, 29, '"And O my people! I ask you for no wealth in return: my reward is from none but Allah: But I will not drive away (in contempt) those who believe: for verily they are to meet their Lord, and ye I see are the ignorant ones!'),
  ('en.yusufali', 11, 30, '"And O my people! who would help me against Allah if I drove them away? Will ye not then take heed?'),
  ('en.yusufali', 11, 31, '"I tell you not that with me are the treasures of Allah, nor do I know what is hidden, nor claim I to be an angel. Nor yet do I say, of those whom your eyes do despise that Allah will not grant them (all) that is good: Allah knoweth best what is in their souls: I should, if I did, indeed be a wrong-doer."'),
  ('en.yusufali', 11, 32, 'They said: "O Noah! thou hast disputed with us, and (much) hast thou prolonged the dispute with us: now bring upon us what thou threatenest us with, if thou speakest the truth!?"'),
  ('en.yusufali', 11, 33, 'He said: "Truly, Allah will bring it on you if He wills,- and then, ye will not be able to frustrate it!'),
  ('en.yusufali', 11, 34, '"Of no profit will be my counsel to you, much as I desire to give you (good) counsel, if it be that Allah willeth to leave you astray: He is your Lord! and to Him will ye return!"'),
  ('en.yusufali', 11, 35, 'Or do they say, "He has forged it"? Say: "If I had forged it, on me were my sin! and I am free of the sins of which ye are guilty!'),
  ('en.yusufali', 11, 36, 'It was revealed to Noah: "None of thy people will believe except those who have believed already! So grieve no longer over their (evil) deeds.'),
  ('en.yusufali', 11, 37, '"But construct an Ark under Our eyes and Our inspiration, and address Me no (further) on behalf of those who are in sin: for they are about to be overwhelmed (in the Flood)."'),
  ('en.yusufali', 11, 38, 'Forthwith he (starts) constructing the Ark: Every time that the chiefs of his people passed by him, they threw ridicule on him. He said: "If ye ridicule us now, we (in our turn) can look down on you with ridicule likewise!'),
  ('en.yusufali', 11, 39, '"But soon will ye know who it is on whom will descend a penalty that will cover them with shame,- on whom will be unloosed a penalty lasting:"'),
  ('en.yusufali', 11, 40, 'At length, behold! there came Our command, and the fountains of the earth gushed forth! We said: "Embark therein, of each kind two, male and female, and your family - except those against whom the word has already gone forth,- and the Believers." but only a few believed with him.'),
  ('en.yusufali', 11, 41, 'So he said: "Embark ye on the Ark, In the name of Allah, whether it move or be at rest! For my Lord is, be sure, Oft-Forgiving, Most Merciful!"'),
  ('en.yusufali', 11, 42, 'So the Ark floated with them on the waves (towering) like mountains, and Noah called out to his son, who had separated himself (from the rest): "O my son! embark with us, and be not with the unbelievers!"'),
  ('en.yusufali', 11, 43, 'The son replied: "I will betake myself to some mountain: it will save me from the water." Noah said: "This day nothing can save, from the command of Allah, any but those on whom He hath mercy! "And the waves came between them, and the son was among those overwhelmed in the Flood.'),
  ('en.yusufali', 11, 44, 'Then the word went forth: "O earth! swallow up thy water, and O sky! Withhold (thy rain)!" and the water abated, and the matter was ended. The Ark rested on Mount Judi, and the word went forth: "Away with those who do wrong!"'),
  ('en.yusufali', 11, 45, 'And Noah called upon his Lord, and said: "O my Lord! surely my son is of my family! and Thy promise is true, and Thou art the justest of Judges!"'),
  ('en.yusufali', 11, 46, 'He said: "O Noah! He is not of thy family: For his conduct is unrighteous. So ask not of Me that of which thou hast no knowledge! I give thee counsel, lest thou act like the ignorant!"'),
  ('en.yusufali', 11, 47, 'Noah said: "O my Lord! I do seek refuge with Thee, lest I ask Thee for that of which I have no knowledge. And unless thou forgive me and have Mercy on me, I should indeed be lost!"'),
  ('en.yusufali', 11, 48, 'The word came: "O Noah! Come down (from the Ark) with peace from Us, and blessing on thee and on some of the peoples (who will spring) from those with thee: but (there will be other) peoples to whom We shall grant their pleasures (for a time), but in the end will a grievous penalty reach them from Us."'),
  ('en.yusufali', 11, 49, 'Such are some of the stories of the unseen, which We have revealed unto thee: before this, neither thou nor thy people knew them. So persevere patiently: for the End is for those who are righteous.'),
  ('en.yusufali', 11, 50, 'To the \'Ad People (We sent) Hud, one of their own brethren. He said: "O my people! worship Allah! ye have no other god but Him. (Your other gods) ye do nothing but invent!'),
  ('en.yusufali', 11, 51, '"O my people! I ask of you no reward for this (Message). My reward is from none but Him who created me: Will ye not then understand?'),
  ('en.yusufali', 11, 52, '"And O my people! Ask forgiveness of your Lord, and turn to Him (in repentance): He will send you the skies pouring abundant rain, and add strength to your strength: so turn ye not back in sin!"'),
  ('en.yusufali', 11, 53, 'They said: "O Hud! No Clear (Sign) that hast thou brought us, and we are not the ones to desert our gods on thy word! Nor shall we believe in thee!'),
  ('en.yusufali', 11, 54, '"We say nothing but that (perhaps) some of our gods may have seized thee with imbecility." He said: "I call Allah to witness, and do ye bear witness, that I am free from the sin of ascribing, to Him,'),
  ('en.yusufali', 11, 55, '"Other gods as partners! so scheme (your worst) against me, all of you, and give me no respite.'),
  ('en.yusufali', 11, 56, '"I put my trust in Allah, My Lord and your Lord! There is not a moving creature, but He hath grasp of its fore-lock. Verily, it is my Lord that is on a straight Path.'),
  ('en.yusufali', 11, 57, '"If ye turn away,- I (at least) have conveyed the Message with which I was sent to you. My Lord will make another people to succeed you, and you will not harm Him in the least. For my Lord hath care and watch over all things."'),
  ('en.yusufali', 11, 58, 'So when Our decree issued, We saved Hud and those who believed with him, by (special) Grace from Ourselves: We saved them from a severe penalty.'),
  ('en.yusufali', 11, 59, 'Such were the \'Ad People: they rejected the Signs of their Lord and Cherisher; disobeyed His messengers; And followed the command of every powerful, obstinate transgressor.'),
  ('en.yusufali', 11, 60, 'And they were pursued by a Curse in this life,- and on the Day of Judgment. Ah! Behold! for the \'Ad rejected their Lord and Cherisher! Ah! Behold! removed (from sight) were \'Ad the people of Hud!'),
  ('en.yusufali', 11, 61, 'To the Thamud People (We sent) Salih, one of their own brethren. He said: "O my people! Worship Allah: ye have no other god but Him. It is He Who hath produced you from the earth and settled you therein: then ask forgiveness of Him, and turn to Him (in repentance): for my Lord is (always) near, ready to answer."'),
  ('en.yusufali', 11, 62, 'They said: "O Salih! thou hast been of us! a centre of our hopes hitherto! dost thou (now) forbid us the worship of what our fathers worshipped? But we are really in suspicious (disquieting) doubt as to that to which thou invitest us."'),
  ('en.yusufali', 11, 63, 'He said: "O my people! do ye see? if I have a Clear (Sign) from my Lord and He hath sent Mercy unto me from Himself,- who then can help me against Allah if I were to disobey Him? What then would ye add to my (portion) but perdition?'),
  ('en.yusufali', 11, 64, '"And O my people! This she-camel of Allah is a symbol to you: leave her to feed on Allah\'s (free) earth, and inflict no harm on her, or a swift penalty will seize you!"'),
  ('en.yusufali', 11, 65, 'But they did ham-string her. So he said: "Enjoy yourselves in your homes for three days: (Then will be your ruin): (Behold) there a promise not to be belied!"'),
  ('en.yusufali', 11, 66, 'When Our Decree issued, We saved Salih and those who believed with him, by (special) Grace from Ourselves - and from the Ignominy of that day. For thy Lord - He is the Strong One, and able to enforce His Will.'),
  ('en.yusufali', 11, 67, 'The (mighty) Blast overtook the wrong-doers, and they lay prostrate in their homes before the morning,-'),
  ('en.yusufali', 11, 68, 'As if they had never dwelt and flourished there. Ah! Behold! for the Thamud rejected their Lord and Cherisher! Ah! Behold! removed (from sight) were the Thamud!'),
  ('en.yusufali', 11, 69, 'There came Our messengers to Abraham with glad tidings. They said, "Peace!" He answered, "Peace!" and hastened to entertain them with a roasted calf.'),
  ('en.yusufali', 11, 70, 'But when he saw their hands went not towards the (meal), he felt some mistrust of them, and conceived a fear of them. They said: "Fear not: We have been sent against the people of Lut."'),
  ('en.yusufali', 11, 71, 'And his wife was standing (there), and she laughed: But we gave her glad tidings of Isaac, and after him, of Jacob.'),
  ('en.yusufali', 11, 72, 'She said: "Alas for me! shall I bear a child, seeing I am an old woman, and my husband here is an old man? That would indeed be a wonderful thing!"'),
  ('en.yusufali', 11, 73, 'They said: "Dost thou wonder at Allah\'s decree? The grace of Allah and His blessings on you, o ye people of the house! for He is indeed worthy of all praise, full of all glory!"'),
  ('en.yusufali', 11, 74, 'When fear had passed from (the mind of) Abraham and the glad tidings had reached him, he began to plead with us for Lut\'s people.'),
  ('en.yusufali', 11, 75, 'For Abraham was, without doubt, forbearing (of faults), compassionate, and given to look to Allah.'),
  ('en.yusufali', 11, 76, 'O Abraham! Seek not this. The decree of thy Lord hath gone forth: for them there cometh a penalty that cannot be turned back!'),
  ('en.yusufali', 11, 77, 'When Our messengers came to Lut, he was grieved on their account and felt himself powerless (to protect) them. He said: "This is a distressful day."'),
  ('en.yusufali', 11, 78, 'And his people came rushing towards him, and they had been long in the habit of practising abominations. He said: "O my people! Here are my daughters: they are purer for you (if ye marry)! Now fear Allah, and cover me not with shame about my guests! Is there not among you a single right-minded man?"'),
  ('en.yusufali', 11, 79, 'They said: "Well dost thou know we have no need of thy daughters: indeed thou knowest quite well what we want!"'),
  ('en.yusufali', 11, 80, 'He said: "Would that I had power to suppress you or that I could betake myself to some powerful support."'),
  ('en.yusufali', 11, 81, '(The Messengers) said: "O Lut! We are Messengers from thy Lord! By no means shall they reach thee! now travel with thy family while yet a part of the night remains, and let not any of you look back: but thy wife (will remain behind): To her will happen what happens to the people. Morning is their time appointed: Is not the morning nigh?"'),
  ('en.yusufali', 11, 82, 'When Our Decree issued, We turned (the cities) upside down, and rained down on them brimstones hard as baked clay, spread, layer on layer,-'),
  ('en.yusufali', 11, 83, 'Marked as from thy Lord: Nor are they ever far from those who do wrong!'),
  ('en.yusufali', 11, 84, 'To the Madyan People (We sent) Shu\'aib, one of their own brethren: he said: "O my people! worship Allah: Ye have no other god but Him. And give not short measure or weight: I see you in prosperity, but I fear for you the penalty of a day that will compass (you) all round.'),
  ('en.yusufali', 11, 85, '"And O my people! give just measure and weight, nor withhold from the people the things that are their due: commit not evil in the land with intent to do mischief.'),
  ('en.yusufali', 11, 86, '"That which is left you by Allah is best for you, if ye (but) believed! but I am not set over you to keep watch!"'),
  ('en.yusufali', 11, 87, 'They said: "O Shu\'aib! Does thy (religion of) prayer command thee that we leave off the worship which our fathers practised, or that we leave off doing what we like with our property? truly, thou art the one that forbeareth with faults and is right-minded!"'),
  ('en.yusufali', 11, 88, 'He said: "O my people! see ye whether I have a Clear (Sign) from my Lord, and He hath given me sustenance (pure and) good as from Himself? I wish not, in opposition to you, to do that which I forbid you to do. I only desire (your) betterment to the best of my power; and my success (in my task) can only come from Allah. In Him I trust, and unto Him I look.'),
  ('en.yusufali', 11, 89, '"And O my people! let not my dissent (from you) cause you to sin, lest ye suffer a fate similar to that of the people of Noah or of Hud or of Salih, nor are the people of Lut far off from you!'),
  ('en.yusufali', 11, 90, '"But ask forgiveness of your Lord, and turn unto Him (in repentance): For my Lord is indeed full of mercy and loving-kindness."'),
  ('en.yusufali', 11, 91, 'They said: "O Shu\'aib! much of what thou sayest we do not understand! In fact among us we see that thou hast no strength! Were it not for thy family, we should certainly have stoned thee! for thou hast among us no great position!"'),
  ('en.yusufali', 11, 92, 'He said: "O my people! is then my family of more consideration with you than Allah? For ye cast Him away behind your backs (with contempt). But verily my Lord encompasseth on all sides all that ye do!'),
  ('en.yusufali', 11, 93, '"And O my people! Do whatever ye can: I will do (my part): Soon will ye know who it is on whom descends the penalty of ignominy; and who is a liar! and watch ye! for I too am watching with you!"'),
  ('en.yusufali', 11, 94, 'When Our decree issued, We saved Shu\'aib and those who believed with him, by (special) mercy from Ourselves: But the (mighty) blast did seize the wrong-doers, and they lay prostrate in their homes by the morning,-'),
  ('en.yusufali', 11, 95, 'As if they had never dwelt and flourished there! Ah! Behold! How the Madyan were removed (from sight) as were removed the Thamud!'),
  ('en.yusufali', 11, 96, 'And we sent Moses, with Our Clear (Signs) and an authority manifest,'),
  ('en.yusufali', 11, 97, 'Unto Pharaoh and his chiefs: but they followed the command of Pharaoh and the command of Pharaoh was no right (guide).'),
  ('en.yusufali', 11, 98, 'He will go before his people on the Day of Judgment, and lead them into the Fire (as cattle are led to water): But woeful indeed will be the place to which they are led!'),
  ('en.yusufali', 11, 99, 'And they are followed by a curse in this (life) and on the Day of Judgment: and woeful is the gift which shall be given (unto them)!'),
  ('en.yusufali', 11, 100, 'These are some of the stories of communities which We relate unto thee: of them some are standing, and some have been mown down (by the sickle of time).'),
  ('en.yusufali', 11, 101, 'It was not We that wronged them: They wronged their own souls: the deities, other than Allah, whom they invoked, profited them no whit when there issued the decree of thy Lord: Nor did they add aught (to their lot) but perdition!'),
  ('en.yusufali', 11, 102, 'Such is the chastisement of thy Lord when He chastises communities in the midst of their wrong: grievous, indeed, and severe is His chastisement.'),
  ('en.yusufali', 11, 103, 'In that is a Sign for those who fear the penalty of the Hereafter: that is a Day for which mankind will be gathered together: that will be a Day of Testimony.'),
  ('en.yusufali', 11, 104, 'Nor shall We delay it but for a term appointed.'),
  ('en.yusufali', 11, 105, 'The day it arrives, no soul shall speak except by His leave: of those (gathered) some will be wretched and some will be blessed.'),
  ('en.yusufali', 11, 106, 'Those who are wretched shall be in the Fire: There will be for them therein (nothing but) the heaving of sighs and sobs:'),
  ('en.yusufali', 11, 107, 'They will dwell therein for all the time that the heavens and the earth endure, except as thy Lord willeth: for thy Lord is the (sure) accomplisher of what He planneth.'),
  ('en.yusufali', 11, 108, 'And those who are blessed shall be in the Garden: They will dwell therein for all the time that the heavens and the earth endure, except as thy Lord willeth: a gift without break.'),
  ('en.yusufali', 11, 109, 'Be not then in doubt as to what these men worship. They worship nothing but what their fathers worshipped before (them): but verily We shall pay them back (in full) their portion without (the least) abatement.'),
  ('en.yusufali', 11, 110, 'We certainly gave the Book to Moses, but differences arose therein: had it not been that a word had gone forth before from thy Lord, the matter would have been decided between them, but they are in suspicious doubt concerning it.'),
  ('en.yusufali', 11, 111, 'And, of a surety, to all will your Lord pay back (in full the recompense) of their deeds: for He knoweth well all that they do.'),
  ('en.yusufali', 11, 112, 'Therefore stand firm (in the straight Path) as thou art commanded,- thou and those who with thee turn (unto Allah); and transgress not (from the Path): for He seeth well all that ye do.'),
  ('en.yusufali', 11, 113, 'And incline not to those who do wrong, or the Fire will seize you; and ye have no protectors other than Allah, nor shall ye be helped.'),
  ('en.yusufali', 11, 114, 'And establish regular prayers at the two ends of the day and at the approaches of the night: For those things, that are good remove those that are evil: Be that the word of remembrance to those who remember (their Lord):'),
  ('en.yusufali', 11, 115, 'And be steadfast in patience; for verily Allah will not suffer the reward of the righteous to perish.'),
  ('en.yusufali', 11, 116, 'Why were there not, among the generations before you, persons possessed of balanced good sense, prohibiting (men) from mischief in the earth - except a few among them whom We saved (from harm)? But the wrong-doers pursued the enjoyment of the good things of life which were given them, and persisted in sin.'),
  ('en.yusufali', 11, 117, 'Nor would thy Lord be the One to destroy communities for a single wrong-doing, if its members were likely to mend.'),
  ('en.yusufali', 11, 118, 'If thy Lord had so willed, He could have made mankind one people: but they will not cease to dispute.'),
  ('en.yusufali', 11, 119, 'Except those on whom thy Lord hath bestowed His Mercy: and for this did He create them: and the Word of thy Lord shall be fulfilled: "I will fill Hell with jinns and men all together."'),
  ('en.yusufali', 11, 120, 'All that we relate to thee of the stories of the messengers,- with it We make firm thy heart: in them there cometh to thee the Truth, as well as an exhortation and a message of remembrance to those who believe.'),
  ('en.yusufali', 11, 121, 'Say to those who do not believe: "Do what ever ye can: We shall do our part;'),
  ('en.yusufali', 11, 122, '"And wait ye! We too shall wait."'),
  ('en.yusufali', 11, 123, 'To Allah do belong the unseen (secrets) of the heavens and the earth, and to Him goeth back every affair (for decision): then worship Him, and put thy trust in Him: and thy Lord is not unmindful of aught that ye do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 11, 1, 'Alif-Laaam-Raa; Kitaabun uhkimat Aayaatuhoo summa fussilat mil ladun Hakeemin Khabeer'),
  ('en.transliteration', 11, 2, 'Allaa ta\'budooo illal laah; innanee lakum minhu nazeerunw wa basheer'),
  ('en.transliteration', 11, 3, 'Wa anis taghfiroo Rabbakum summa toobooo ilaihi yumatti\'kum mataa\'an hasanan ilaaa ajalim musammanw wa yu\'ti kulla zee fadlin fadlahoo wa in tawallaw fa inneee akhaafu \'alaikum \'azaaba Yawmin Kabeer'),
  ('en.transliteration', 11, 4, 'Ilal laahi marji\'ukum wa Huwa \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 11, 5, 'Alaa innahum yasnoona sudoorahum liyastakhfoo minh; alaa heena yastaghshoona siyaabahum ya\'lamu maa yusiroona wa maa yu\'linoon; innahoo \'aleemum bizaatis sudoor'),
  ('en.transliteration', 11, 6, 'Wa maa min daaabbatin fil ardi illaa \'alal laahi rizquhaa wa ya\'lamu mustaqarrahaa wa mustawda\'ahaa; kullun fee Kitaabim Mubeen'),
  ('en.transliteration', 11, 7, 'Wa Huwal lazee khalaqas samaawaati wal alrda fee sittati aiyaaminw wa kaana \'Arshuhoo alal maaa\'i liyablu wakum aiyukum ahsanu \'amalaa; wa la\'in qulta innakum mab\'oosoona mim ba\'dil mawti la yaqoolanal lazeena kafaroo in haazaaa illaa sihrum mubeen'),
  ('en.transliteration', 11, 8, 'Wala\'in akhkharnaa \'anhumul \'azaaba ilaaa ummatim ma\'doodatil la yaqoolunna maa yahbisuh; alaa yawma yaateehim laisa masroofan \'anhum wa haaqa bihim maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 11, 9, 'Wa la\'in azaqnal insaana minnaa rahmatan summa naza\'naahaa minhu, innahoo laya\'oosun kafoor'),
  ('en.transliteration', 11, 10, 'Wala\'in azaqnaahu na\'maaa\'a ba\'da darraaa\'a massat hu la yaqoolanna zahabas saiyiaatu \'anneee; innahoo lafarihun fakhoor'),
  ('en.transliteration', 11, 11, 'Illal lazeena sabaroo wa \'amilus saalihaati ulaaa\'ika lahum maghfiratunw wa ajrun kabeer'),
  ('en.transliteration', 11, 12, 'Fala\'allaka taarikum ba\'da maa yoohaaa ilaika wa daaa\'iqum bihee sadruka ai yaqooloo law laaa unzila \'alaihi kanzun aw jaaa\'a ma\'ahoo malak; innamaa anta nazeer; wallaahu \'alaa kulli shai\'inw wakeel'),
  ('en.transliteration', 11, 13, 'Am yaqooloonaf taraahu qul faatoo bi\'ashri Suwarim mislihee muftarayaatinw wad\'oo manis tata\'tum min doonil laahi in kuntum saadiqeen'),
  ('en.transliteration', 11, 14, 'Fa il lam yastajeeboo lakum fa\'lamooo annamaaa unzilla bi\'ilmil laahi wa al laaa ilaaha illaa Huwa fahal antum muslimoon'),
  ('en.transliteration', 11, 15, 'Man kaana yureedul hayaatad dunyaa zeenatahaa nuwaffi ilaihim a\'maa lahum feehaa wa hum feehaa laa yubkhasoon'),
  ('en.transliteration', 11, 16, 'Ulaaa\'ikal lazeena laisa lahum fil Aakhirati illan Naaru wa habita maa sana\'oo feehaa wa baatilum maa kaanoo ya\'maloon'),
  ('en.transliteration', 11, 17, 'Afaman kaana \'alas baiyinatim mir Rabbihee wa yatloohu shaahidum minhu wa min qablihee Kitaabu Moosaaa imaamanw wa rahmah; ulaaa \'ika yu\'minoona bih; wa mai yakfur bihee minal Ahzaabi fan Naaru maw\'iduh; falaa taku fee miryatim minh; innahul haqqu mir Rabbika wa laakinna aksaran naasi laa yu\'minoon'),
  ('en.transliteration', 11, 18, 'Wa man azlamu mimmanif taraa \'alal laahi kazibaa; ulaaa\'ika yu\'radoona \'alaa Rabbihim wa yaqoolul ashhaa duhaaa\'ulaaa\'il lazeena kazaboo \'alaa Rabbihim; alaa la\'natul laahi alaz zaalimeen'),
  ('en.transliteration', 11, 19, 'Allazeena yasuddoona \'an sabeelil laahi wa yabghoonahaa \'iwajanw wa hum bil Aakhiratihum kaafiroon'),
  ('en.transliteration', 11, 20, 'Ulaaa\'ika lam yakoonoo mu\'jizeena fil ardi wa maa kaana lahum min doonil laahi min awliyaaa\'; yudaa\'afu lahumul \'azaab; maa kaanoo yastatee\'oonas sam\'a wa maa kaanoo yubsiroon'),
  ('en.transliteration', 11, 21, 'Ulaaa\'ikal lazeena khasirooo anfusahum wa dalla \'anhum maa kaanoo yaftaroon'),
  ('en.transliteration', 11, 22, 'Laa jarama annahum fil Aakhirati humul akhsaroon'),
  ('en.transliteration', 11, 23, 'Innal lazeena aamanoo wa \'amilus saalihaati wa akhbatooo ilaa Rabbihim ulaaa\'ika Ashaabul Jannati hum feehaa khaalidoon'),
  ('en.transliteration', 11, 24, 'Masalul fareeqini kal a\'maa wal asammi walbaseeri wassamee\'; hal yastawiyaani masalaa; afalaa tazakkaroon'),
  ('en.transliteration', 11, 25, 'Wa laqad arsalnaa Noohan ilaa qawmihee innee lakum nazeerum mubeen'),
  ('en.transliteration', 11, 26, 'Al laa ta\'budooo illal laaha inneee akhaafu \'alaikum \'azaaba Yawmin aleem'),
  ('en.transliteration', 11, 27, 'Faqaalal mala ul lazeena kafaroo min qawmihee ma naraaka illaa basharam mislanaa wa maa naraakat taba\'aka illal lazeena hum araazilunaa baadiyar raayi wa maa naraa lakum \'alainaa min fadlim bal nazunnukum kaazibeen'),
  ('en.transliteration', 11, 28, 'Qaala yaa qawmi ara\'aitum in kuntu \'alaa baiyinatim mir Rabbee wa aataanee rahmatam min \'indihee fa\'um miyat \'alaikum anulzimuku moohaa wa antum lahaa kaarihoon'),
  ('en.transliteration', 11, 29, 'Wa yaa qawmi laaa as\'alukum \'alaihi maalan in ajriya illaa \'alal laah; wa maaa ana bitaaridil lazeena aamanoo; innahum mulaaqoo Rabbihim wa laakinneee araakum qawman tajhaloon'),
  ('en.transliteration', 11, 30, 'Wa yaa qawmi mai yansurunee minal laahi in tarattuhum; afalaa tazak karoon'),
  ('en.transliteration', 11, 31, 'Wa laa aqoolu lakum \'indee khazaa\'inul laahi wa laaa a\'lamul ghaiba wa laa aqoolu inee malakunw wa laaa aqoolu lillazeena tazdareee a\'yunukum lai yu\'tiyahumul laahu khairan Allaahu a\'lamu bimaa feee anfusihim innee izal laminaz zaalimeen'),
  ('en.transliteration', 11, 32, 'Qaaloo yaa Noohu qad jaadaltanaa fa aksarta jidaalanaa faatinaa bimaa ta\'idunaaa in kunta minas saadiqeen'),
  ('en.transliteration', 11, 33, 'Qaala innamaa yaateekum bihil laahu in shaaa\'a wa maaa antum bimu\'jizeen'),
  ('en.transliteration', 11, 34, 'Wa laa yanfa\'ukum nusheee in arattu an ansaha lakum in kaanal laahu yureedu ai yughwi yakum; Huwa Rabbukum wa ilaihi turja\'oon'),
  ('en.transliteration', 11, 35, 'Am yaqooloonaf taraahu qul inif taraituhoo fa\'alaiya ijraamee wa ana bareee\'um mimmaa tujrimoon'),
  ('en.transliteration', 11, 36, 'Wa oohiya ilaa Noohin annahoo lany-yu\'mina min qawmika illaa man qad aamana falaa tabta\'is bimaa kaanoo yaf\'aloon'),
  ('en.transliteration', 11, 37, 'Wasna\'il fulka bi-a\'yuninaa wa wahyinaa wa laa tukhaa tibnee fil lazeena zalamoo; innahum mughraqoon'),
  ('en.transliteration', 11, 38, 'Wa yasn\'ul fulka wa kullamaa marra \'alaihi malaum min qawmihee sakhiroo minh; qaala in taskharoo minnaa fa innaa naskharu minkum kamaa taskharoon'),
  ('en.transliteration', 11, 39, 'Fasawfa ta\'lamoona mai yaateehi \'azaabuny yaukhzeehi wa yahillu \'alaihi \'azaabum muqeem'),
  ('en.transliteration', 11, 40, 'Hattaaa izaa jaaa\'a amrunaa wa faarat tannooru qulnah mil feehaa min kullin zawjainis naini wa ahlaka illaa man sabaqa \'alaihil qawlu wa man aaman; wa maaa aamana ma\'ahooo illaa qaleel'),
  ('en.transliteration', 11, 41, 'Wa qaalar kaboo feehaa bismil laahi majraihaa wa mursaahaa; inna Rabbee la Ghafoorur Raheem'),
  ('en.transliteration', 11, 42, 'Wa hiya tajree bihim fee mawjin kaljibaali wa naadaa Noohunib nahoo wa kaana fee ma\'ziliny yaa bunai yarkam ma\'anaa wa laa takum ma\'al kaafireen'),
  ('en.transliteration', 11, 43, 'Qaala sa aaweee ilaa jabaliny ya\'simunee minal maaa\'; qaala laa \'aasimal yawma min amril laahi illaa mar rahim; wa haala bainahumal mawju fakaana minal mughraqeen'),
  ('en.transliteration', 11, 44, 'Wa qeela yaaa ardubla\'ee maaa\'aki wa yaa samaaa\'u aqi\'ee wa gheedal maaa\'u wa qudiyal amru wastawat \'alal joodiyyi wa qeela bu\'dal lilqawmiz zaalimeen'),
  ('en.transliteration', 11, 45, 'Wa naadaa noohur Rabbahoo faqaala Rabbi innabnee min ahlee wa inna wa\'dakal haqqu wa Anta ahkamul haakimeen'),
  ('en.transliteration', 11, 46, 'Qaala yaa Noohu innahoo laisa min ahlika innahoo \'amalun ghairu saalihin falaa tas\'alni mmaa laisa laka bihee \'ilmun inneee a\'izuka an takoona minal jaahileen'),
  ('en.transliteration', 11, 47, 'Qaala rabbi inneee a\'oozu bika an as\'alaka maa laisa lee bihee \'ilmunw wa illaa taghfir lee wa tarhamneee akum minal khaasireen'),
  ('en.transliteration', 11, 48, 'Qeela yaa Noohuh bit bisalaamim minnaa wa barakaatin \'alaika wa \'alaaa umamim mimmam ma\'ak; wa umamun sanumatti\'uhum summa yamassuhum minaa \'azaabun aleem'),
  ('en.transliteration', 11, 49, 'Tilka min ambaaa\'il ghaibi nooheehaaa ilaika maa kunta ta\'lamuhaaaa anta wa laa qawmuka min qabli haazaa fasbir innal \'aaqibata lilmuttaqeen'),
  ('en.transliteration', 11, 50, 'Wa ilaa \'aadin akhaahum Hoodaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhooo in antum illaa muftaroon'),
  ('en.transliteration', 11, 51, 'Yaa qawmi laaa as\'alukum \'alaihi ajran in ajriya illaa \'alal lazee fataranee; afalaa ta\'qiloon'),
  ('en.transliteration', 11, 52, 'Wa yaa qawmis taghfiroo Rabbakum summa toobooo ilaihi yursilis samaaa\'a \'alaikum midraaranw wa yazidkum quwwatan ilaa quwwatikum wa laa tatawallaw mujrimeen'),
  ('en.transliteration', 11, 53, 'Qaaloo yaa Hoodu maa ji\'tanaa bibaiyinatinw wa maa nahnu bitaarikeee aalihatinaa \'an qawlika wa maa nahnu laka bimu\'mineen'),
  ('en.transliteration', 11, 54, 'In naqoolu illa\' taraaka ba\'du aalihatinaa bisooo\'; qaala inneee ushhidul laaha wash hadooo annee bareee\'um mimmaa tushrikoon'),
  ('en.transliteration', 11, 55, 'Min doonihee fakeedoonee jamee\'an summa laa tunziroon'),
  ('en.transliteration', 11, 56, 'Innee tawakkaltu \'alallaahi Rabbee wa Rabbikum; maa min daaabbatin illaa Huwa aakhizum binaasiyatihaa; inna Rabbee \'alaa Siraatim mustaqeem'),
  ('en.transliteration', 11, 57, 'Fa in tawallaw faqad ablaghtukum maaa ursiltu biheee ilaikum; wa yastakhlifu Rabbee qawman ghairakum wa laa tadur roonahoo shai\'aa; inna Rabbee \'alaa kulli shai\'in Hafeez'),
  ('en.transliteration', 11, 58, 'Wa lammaa jaaa\'a amrunaa najainaa Hoodanw wallazeena aamanoo ma\'ahoo birahmatim minnaa wa najainaahum min \'azaabin ghaleez'),
  ('en.transliteration', 11, 59, 'Wa tilka \'aad, jahadoo bi Aayaati Rabbihim wa \'asaw Rusulahoo wattaba\'ooo amra kulli jabbaarin \'aneed'),
  ('en.transliteration', 11, 60, 'Wa utbi\'oo fee haazihid dunyaa la\'natanw wa Yawmal Qiyaamah; alaaa inna \'Aadan kafaroo Rabbahum; alaa bu\'dal li \'Aadin qawmin Hood'),
  ('en.transliteration', 11, 61, 'Wa ilaa Samooda akhaahum Saalihaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahim ghairuhoo Huwa ansha akum minal ardi wasta\' marakum feehaa fastaghfiroohu summa toobooo ilaih; inna Rabbee Qareebum Mujeeb'),
  ('en.transliteration', 11, 62, 'Qaaloo yaa Saalihu qad kunta feenaa marjuwwan qabla haazaaa atanhaanaaa an na\'bu da maa ya\'budu aabaaa\'unaa wa innanaa lafee shakkim mimmaa tad\'oonaaa ilaihi mureeb'),
  ('en.transliteration', 11, 63, 'Qaala yaa qawmi ara\'aytum in kuntu \'alaa baiyinatim mir Rabbee wa aataanee minhu rahmatan famai yansurunee minal laahi in \'asaituhoo famaa tazeedoonanee ghaira takhseer'),
  ('en.transliteration', 11, 64, 'Wa yaa qawmi haazihee naaqatul laahi lakum aayatan fazaroohaa taakul feee ardil laahi wa laa tamassoohaa bisooo\'in fa yaakhuzakum azaabun qareeb'),
  ('en.transliteration', 11, 65, 'Fa \'aqaroohaa faqaala tamatta\'oo fee daarikum salaasata aiyaamin zaalika wa\'dun ghairu makzoob'),
  ('en.transliteration', 11, 66, 'Falammaa jaaa\'a amrunaa najjainaa Saalihanw wal lazeena aamanoo ma\'ahoo birahmatim minnaa wa min khizyi Yawmi\'iz inna Rabbaka Huwal Qawiyyul \'Azeez'),
  ('en.transliteration', 11, 67, 'Wa akhazal lazeena zalamus saihatu fa asbahoo fee diyaarihim jaasimeena'),
  ('en.transliteration', 11, 68, 'Ka al lam yaghnaw feehaaa; alaaa inna Samooda kafaroo Rabbahum; alaa bu\'dal li Samood.'),
  ('en.transliteration', 11, 69, 'Wa laqad jaaa\'at Rusulunaaa Ibraaheema bilbushraa qaaloo salaaman qaala salaamun famaa labisa an jaaa\'a bi\'ijin haneez'),
  ('en.transliteration', 11, 70, 'Falammaa ra aaa aidiyahum laa tasilu ilaihi nakirahum wa awjasa minhum kheefah; qaaloo la takhaf innaaa ursilnaaa ilaa qawmi Loot'),
  ('en.transliteration', 11, 71, 'Wamra atuhoo qaaa\'imatun fadahikat fabashsharnaahaa bi Ishaaqa wa minw waraaa\'i Ishaaqa Ya\'qoob'),
  ('en.transliteration', 11, 72, 'Qaalat yaa wailataaa \'aalidu wa ana \'ajoozunw wa haaza ba\'lee shaikhan inna haazaa lashai\'un \'ajeeb'),
  ('en.transliteration', 11, 73, 'Qaalooo ata\'jabeena min amril laahi rahmatul laahi wa barakaatuho \'alaikum Ahlal Bayt; innahoo Hameedum Majeed'),
  ('en.transliteration', 11, 74, 'Falammaa zahaba an Ibraaheemar raw\'u wa jaaa\'at hul bushraaa yujaadilunaa fee qawmi Loot'),
  ('en.transliteration', 11, 75, 'Inna Ibraaheema lahaleemun awwwaahum muneeb'),
  ('en.transliteration', 11, 76, 'Yaaa Ibraaheemu a\'rid \'an haazaaa innahoo qad jaaa\'a amru Rabbika wa innahum aateehim \'azaabun ghairun mardood'),
  ('en.transliteration', 11, 77, 'Wa lammaa jaaa\'at Rusulunaa Lootan seee\'a bihim wa daaqa bihim zar\'anw wa qaala haazaa yawmun \'aseeb'),
  ('en.transliteration', 11, 78, 'Wa jaaa\'ahoo qawmuhoo yuhra\'oona ilaihi wa min qablu kaanoo ya\'maloonas saiyiaat; qaala yaa qawmi haaa\'ulaaa\'i banaatee hunna atharu lakum fattaqul laaha wa laa tukhzooni fee daifee alaisa minkum rajulur rasheed'),
  ('en.transliteration', 11, 79, 'Qaaloo laqad \'alimta maa lanaa fee banastika min haqq, wa innaka lata\'lamu maa nureed'),
  ('en.transliteration', 11, 80, 'Qaala law anna lee bikum quwwatan aw aaweee ilaa ruknin shadeed'),
  ('en.transliteration', 11, 81, 'Qaaloo yaa Lootu innaa Rusulu Rabbika lai yasiloo ilaika fa asri bi ahlika biqit \'im minal laili wa laa yaltafit minkum ahadun illam ra ataka innahoo museebuhaa maaa asaabahum; inna maw\'i dahumus subh; alaisas subhu biqareeb'),
  ('en.transliteration', 11, 82, 'Falammaa jaaa\'a amrunaa ja\'alnaa \'aaliyahaa saafilahaa wa amtamaa \'alaihaa hijaaratam min sijjeelim mandood'),
  ('en.transliteration', 11, 83, 'Musawwamatan \'inda Rabbik; wa maa hiya minaz zaalimena biba\'eed'),
  ('en.transliteration', 11, 84, 'Wa ilaa Madyana akhaahum Shu\'aibaa; qaala yaa qawmi\' budul laaha maa lakum min ilaahin ghairuhoo wa laa tanqusul mikyaala walmeezaan; inneee araakum bikhairinw wa innee akhaafu \'alaikum \'azaaba Yawmim muheet'),
  ('en.transliteration', 11, 85, 'Wa yaa qawmi awful mikyaala walmeezaana bilqisti wa laa tabkhasun naasa ashyaaa\'ahum wa laa ta\'saw fil ardi mufsideen'),
  ('en.transliteration', 11, 86, 'Baqiyyatul laahi khairul lakum in kuntum mu\'mineen; wa maa ana \'alaikum bihafeez'),
  ('en.transliteration', 11, 87, 'Qaaloo yaa Shu\'aybu asalaatuka taamuruka an natruka maa ya\'budu aabaaa\'unaaa aw an naf\'ala feee amwaalinaa maa nashaaa\'oo innaka la antal haleemur rasheed'),
  ('en.transliteration', 11, 88, 'Qaala yaa qawmi ara\'aitum in kuntu \'alaa baiyinatim mir Rabbee wa razaqanee minhu rizqan hasanaa; wa maaa ureedu an ukhaalifakum ilaa maaa anhaakum \'anh; in ureedu illal islaaha mastata\'t; wa maa tawfeeqeee illaa billaah; \'alaihi tawakkaltu wa ilaihi uneeb'),
  ('en.transliteration', 11, 89, 'Wa yaa qawmi laa yajri mannakum shiqaaqeee ai yuseebakum mislu maaa asaaba qawma Noohin aw qawma Hoodin aw qawma Saalih; wa maa qawmu Lootim minkum biba\'eed'),
  ('en.transliteration', 11, 90, 'Wastaghfiroo Rabbakum summa toobooo ilaih; inna Rabbee Raheemunw Wadood'),
  ('en.transliteration', 11, 91, 'Qaaloo yaa Shu\'aibu maa nafqahu kaseeram mimmaa taqoolu wa innaa lanaraaka feenaa da\'eefanw wa law laa rahtuka larajamnaaka wa maaa anta \'alainaa bi\'azeez'),
  ('en.transliteration', 11, 92, 'Qaala yaa qawmi arahteee a\'azzu \'alaikum minal laahi wattakhaztumoohu waraaa\'akum zihriyyan inna Rabbee bimaa ta\'maloona muheet'),
  ('en.transliteration', 11, 93, 'Wa yaa qawmi\' maloo \'alaa makaanatikum innee \'aamilun sawfa ta\'lamoona mai yaateehi \'azaabuny yukhzeehi wa man huwa kaazib; wartaqibooo innnee ma\'akum raqeeb'),
  ('en.transliteration', 11, 94, 'Wa lammaa jaaa\'a amrunaa najjainaa shu\'aibanw wal lazeena aamanoo ma\'ahoo birahmatim minnaa wa akhazatil lazeena zalamus saihatu fa asbahoo fee diyaarihim jaasimeen'),
  ('en.transliteration', 11, 95, 'Ka-al-lam yaghnaw feehaaa; alaa bu\'dal li Madyana Kamaa ba\'idat Samood'),
  ('en.transliteration', 11, 96, 'Wa laqad arsalnaa Moosaa bi Aayaatinaa wa sultaanim mubeen'),
  ('en.transliteration', 11, 97, 'Ilaa Fir\'awna wa mala\'ihee fattaba\'ooo amra Fir\'awna wa maaa amru Fir\'awna birasheed'),
  ('en.transliteration', 11, 98, 'Yaqdumu qawmahoo Yawmal Qiyaamati fa awrada humun Naara wa bi\'sal wirdul mawrood'),
  ('en.transliteration', 11, 99, 'Wa utbi\'oo fee haazihee la\'natanw wa Yawmal Qiyaamah; bi\'sar rifdul marfood'),
  ('en.transliteration', 11, 100, 'Zaalika min ambaaa\'il quraa naqussuhoo \'alaika minhaa qaaa\'imunw wa haseed'),
  ('en.transliteration', 11, 101, 'Wa maa zalamnaahum wa laakin zalamooo anfusahum famaaa aghnat \'anhum aalihatuhumul latee yad\'oona min doonil laahi min shai\'il lammaa jaaa\'a amru Rabbika wa maa zaadoohum ghaira tatbeeb'),
  ('en.transliteration', 11, 102, 'Wa kazaalika akhzu Rabbika izaaa akhazal quraa wa hiya zaalimah; inna akhzahooo aleemun shadeed'),
  ('en.transliteration', 11, 103, 'Inna fee zaalika la aayatal liman khaafa \'azaabal Aakhirah; zaalika Yawmum majmoo\'ul lahun naasu wa zaalika Yawmum mashhood'),
  ('en.transliteration', 11, 104, 'Wa maa nu\'akhkhiruhooo illaa li ajalim ma\'dood'),
  ('en.transliteration', 11, 105, 'Yawma yaati laa takallamu nafsun illaa bi iznih; faminhum shaqiyyunw wa sa\'eed'),
  ('en.transliteration', 11, 106, 'Fa ammal lazeena shaqoo fafin Naari lahum feehaa zafeerunw wa shaheeq'),
  ('en.transliteration', 11, 107, 'Khaalideena feehaa maa daamatis samaawaatu wal ardu illaa maa shaaa\'a Rabbuk; inna Rabbaka fa\' \'aalul limaa yureed'),
  ('en.transliteration', 11, 108, 'Wa ammal lazeena su\'idoo fafil Jannati khaalideena feehaa maa daamatis samaawaatu wal ardu illaa maa shaaa\'a Rabbuk; ataaa\'an ghaira majzooz'),
  ('en.transliteration', 11, 109, 'Falaa taku fee miryatim mimmmaa ya\'budu haaa\'ulaaa\'; maa ya\'budoona illaa kamaa ya\'budu aabaaa\'uhum min qabl; wa innaa lamuwaf foohum naseebahum ghaira manqoos'),
  ('en.transliteration', 11, 110, 'Wa laqad aatainaa Moosal Kitaaba fakhtulifa feeh; wa law laa Kalimatun sabaqat mir Rabbika laqudiya bainahum; wa innahum lafee shakkim minhu mureeb'),
  ('en.transliteration', 11, 111, 'Wa inna kullal lammaa la yuwaffiyannahum Rabbuka a\'maalahum; innahoo bimaa ya\'maloona Khabeer'),
  ('en.transliteration', 11, 112, 'Fastaqim kamaaa umirta wa man taaba ma\'aka wa laa tatghaw; innahoo bimaa ta\'maloona Baseer'),
  ('en.transliteration', 11, 113, 'Wa laa tarkanooo ilal lazeena zalamoo fatamassa kumun Naaru wa maa lakum min doonil laahi min awliyaaa\'a summa laa tunsaroon'),
  ('en.transliteration', 11, 114, 'Wa aqimis Salaata tarafayin nahaari wa zulafam minal layl; innal hasanaati yuzhibnas saiyi aat; zaalika zikraa liz zaakireen'),
  ('en.transliteration', 11, 115, 'Wasbir fa innal laaha laa yudee\'u ajral muhsineen'),
  ('en.transliteration', 11, 116, 'Falw laa kaana minal qurooni min qablikum ooloo baqiyyatiny yanhawna \'anil fasaadi fil ardi illaa qaleelam mimman anjainaa minhum; wattaba\'al lazeena zalamoo maaa utrifoo feehi wa kaanoo mujrimeen'),
  ('en.transliteration', 11, 117, 'Wa maa kaana Rabbuka liyuhlikal quraa bizulminw wa ahluhaa muslihoon'),
  ('en.transliteration', 11, 118, 'Wa law shaaa\'a Rabbuka laja\'alannnaasa ummatanw waa hidatanw wa laa yazaaloona mukhtalifeen'),
  ('en.transliteration', 11, 119, 'Illaa mar rahima Rabbuk; wa lizaalika khalaqahum; wa tammat Kalimatu Rabbika la amla\'ana Jahannama minal jinnati wannnaasi ajma\'een'),
  ('en.transliteration', 11, 120, 'Wa kullan naqussu \'alaika min ambaaa\'ir Rusuli maa nusabbitu bihee fu\'aadak; wa jaaa\'aka fee haazihil haqqu wa maw\'izatunw wa zikraa lilmu\' mineen'),
  ('en.transliteration', 11, 121, 'Wa qul lillazeena laa yu\'minoona\' maloo \'alaa makaanatikum innaa \'aamiloon'),
  ('en.transliteration', 11, 122, 'Wantaziroo innaa mun taziroon'),
  ('en.transliteration', 11, 123, 'Wa lillaahi ghaibus samaawaati wal ardi wa ilaihi yurja\'ul amru kulluhoo fa\'bu-dhu wa tawakkal \'alaih; wa maa Rabbuka bighaafilin \'ammaa ta\'maloon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 11, 1, 'یہ ایسی کتاب ہےکہ جس کی آیتیں حکیم خبردار کی طرف سے مستحکم کر دی گئی ہیں پھر مفصل بیان کی گئی ہیں'),
  ('ur.ahmedali', 11, 2, 'یہ کہ الله کے سوا کسی کی عبادت نہ کرو میں تمہارے لیے اس کی طرف سے ڈرانے والا اور خوشخبری دینے والا ہوں'),
  ('ur.ahmedali', 11, 3, 'اور یہ کہ تم اپنے رب سے معافی مانگو پھراس کی طرف رجوع کرو تاکہ تمہیں ایک وقت مقرر تک اچھا فائدپہنچائے اورجس نے بڑھ کر نیکی کی ہو اس کو بڑھ کر بدلہ دے اور اگر تم پھر جاؤ گے تو میں تم پر ایک بڑے دن کے عذاب سے ڈرتا ہوں'),
  ('ur.ahmedali', 11, 4, 'تمہیں الله کی طرف لوٹ کر جانا ہے اوروہ ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 11, 5, 'خبردار جس وقت وہ کپڑے ڈھانکتے ہیں وہ جانتا ہے جو کچھ وہ چھپا کر اور ظاہر کر کے کرتے ہیں بےشک وہ دلوں کی باتوں کو جاننے والا ہے'),
  ('ur.ahmedali', 11, 6, 'ارو زمین پر کوئی چلنے والا نہیں مگر اس کی روزی الله پر ہے اور جانتا ہے جہاں وہ ٹھیرتا ہے اور جہاں وہ سونپا جاتا ہے سب کچھ واضح کتاب میں ہے'),
  ('ur.ahmedali', 11, 7, 'اور وہی ہےجس نے آسمان اور زمین چھ دن میں بنائے اور اس کا تخت پانی پر تھا کہ تمہیں آزمائے کہ تم میں سے کون اچھا کام کرتا ہے اور اگر تو کہے کہ مرنے کے بعد اٹھو گے تو منکرین یہ کہیں گے کہ یہ تو صریح جادو ہے'),
  ('ur.ahmedali', 11, 8, 'اور اگر ہم ایک مدت معلوم تک ان سے عذاب کو روک رکھیں توضرور کہیں گے کس چیر نے عذاب کو روک دیا خبردار جس دن ان پر عذاب آئے گا ان سے نہ پھیرا جائے گا اور انہیں وہ چیز گھیرے گی جس پر ٹھٹایا کیاکرتے تھے'),
  ('ur.ahmedali', 11, 9, 'اور اگر ہم انسان کو اپنی رحمت کا مزہ چکھا کر پھر اس سے چھین لیتے ہیں تو وہ ناامید ناشکرا ہو جاتا ہے'),
  ('ur.ahmedali', 11, 10, 'اور اگر مصیبت پہنچنے کے بعد نعمتوں کا مزہ چکھاتے ہیں تو کہتا ہے کہ میری سختیاں جاتی رہیں کیوں کہ وہ اترانے والا شیخی خورا ہے'),
  ('ur.ahmedali', 11, 11, 'مگر جو لوگ صابر ہیں اور نیکیاں کرتے ہیں ان کے لیے بخشش اوربڑا ثواب ہے'),
  ('ur.ahmedali', 11, 12, 'پھر شاید آپ اس میں سے کچھ چھوڑ بیٹھیں گے جو آپ کی طرف وحی کیا گیا ہے اور ان کے اس کہنے سے آپ کا دل تنگ ہوگا کہ اس پر کوئی خزانہ کیوں نہ اتر آیا یا اس کے ساتھ کوئی فرشتہ کیوں نہ آیا آپ تو محض ڈرانے والے ہیں اور الله ہر چیز کا ذمہ دار ہے'),
  ('ur.ahmedali', 11, 13, 'کیا کہتے ہیں کہ تو نے قرآن خود بنا لیا ہے کہہ دو تم بھی ایسی دس سورتیں بنا لاؤ اور الله کے سوا جس کو بلا سکو بلا لو اگر تم سچے ہو'),
  ('ur.ahmedali', 11, 14, 'پھر اگر تمہارا کہنا پورا نہ کریں تو جان لو کہ قرآن الله کے علم سے نازل کیا گیا ہے اور یہ بھی کہ اس کے سوا کوئی معبود نہیں پس کیا تم فرمانبرداری کرنے والے ہو'),
  ('ur.ahmedali', 11, 15, 'جو کوئی دنیا کی زندگی اور اس کی آرائش چاہتا ہے تو انکے اعمال ہم یہیں پورے کر دیتے ہیں اور انہیں کچھ نقصان نہیں دیا جاتا'),
  ('ur.ahmedali', 11, 16, 'یہ وہی ہیں جن کیلئے آخرت میں آگ کے سوا کچھ نہیں اور برباد ہوگیا جو کچھ انہوں نے دنیا میں کیا تھا اور خراب ہو گیا جو کچھ کمایا تھا'),
  ('ur.ahmedali', 11, 17, 'بھلا وہ شخص جو اپنے رب کے صاف راستہ پر ہو اور اس کے ساتھ الله کی طرف سے ایک گواہ بھی ہو اور اس سے پہلے موسیٰ کی کتاب گواہ تھی جو امام اور رحمت تھی یہی لوگ قرآن کو مانتے ہیں اور جو کوئی سب فرقوں میں سے اس کا منکر ہوتو اس کا ٹھکانا دوزخ ہے سو تو قرآ ن کی طرف سے شبہ میں نہ رہ بے شک یہ تیرے رب کی طرف سے حق ہے لیکن اکثر لوگ ایمان نہیں لاتے'),
  ('ur.ahmedali', 11, 18, 'اور اس سے بڑھ کر ظالم کون ہوگا جو الله پر جھوٹ باندھے وہ لوگ اپنے رب کے روبر پیش کیے جائیں گے اور گواہ کہیں گے کہ یہی ہیں کہ جنہوں نے اپنے رب پر جھوٹ بولا تھا خبرادر ظالموں پر الله کی لعنت ہے'),
  ('ur.ahmedali', 11, 19, 'جو الله کی راہ سے روکتے ہیں اور اس میں کجی پیدا کرنا چاہتے ہیں اوروہی آخرت کے منکر ہیں'),
  ('ur.ahmedali', 11, 20, 'یہ لوگ زمین میں عاجز کرنے والے نہیں تھے اور ان کے لیے سوا الله کے کوئی دوست نہ تھا انہیں دگنا عذاب کیا جائے گا یہ لوگ نہ سن سکتے تھے اور نہ دیکھتے تھے'),
  ('ur.ahmedali', 11, 21, 'انہوں نے اپنے آپ کو خسارہ میں ڈال دیا اور ان سے ضائع ہوگیا جو جھوٹ وہ باندھتے تھے'),
  ('ur.ahmedali', 11, 22, 'بے شک یہی لوگ آخرت میں سب سے زیادہ نقصان میں ہوں گے'),
  ('ur.ahmedali', 11, 23, 'البتہ جولوگ ایمان لائے اورنیک کام کیے اور اپنے رب کے سامنے عاجزی کی وہ جنت میں رہنے والے ہیں وہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 11, 24, 'دونوں فریق کی مثال ایسی ہے جیسے ایک اندھا اوربہرا ہو اور دوسرا دیکھنے والا اور سننے والاکیا دونوں کا حال برابر ہے پھر تم کیوں نہیں سمجھتے'),
  ('ur.ahmedali', 11, 25, 'اور ہم نے نوح کو اس کی قوم کی طرف بھیجا بے شک میں تمہیں صاف ڈرانے والا ہوں'),
  ('ur.ahmedali', 11, 26, 'کہ الله کے سوا کسی کی عبادت نہ کرو بے شک میں تم پر دردناک دن کے عذاب سے ڈرتا ہوں'),
  ('ur.ahmedali', 11, 27, 'پھر اس کی قوم کے جو کافر سردار تھے وہ بولے ہمیں تو تم ہم جیسے ہی ایک آدمی نظر آتے ہو اور ہمیں تو تمہارے پیرو وہی نظر آتے ہیں جو ہم میں سے رذیل ہیں وہ بھی سرسری نظر سے اورہم تم میں اپنے سے کوئی فضیلت بھی نہیں پاتے بلکہ تمہیں جھوٹا خیال کرتے ہیں'),
  ('ur.ahmedali', 11, 28, 'اس نے کہا اے میری قوم دیکھو تو اگر میں اپنے رب کی طرف سے صاف راستہ پر ہوں اور اس نے مجھ پر اپنے ہاں سے رحمت بھیجی ہو پھر وہ تمہیں دکھائی نہ دے تو کیا میں زبردستی تمہارے گلے مڑھ دوں اور تم اس سے نفرت کرتے ہو'),
  ('ur.ahmedali', 11, 29, 'اور اے میری قوم میں تم سے اس پر کچھ مال نہیں مانگتا میری مزدوری الله ہی کے ذمہ ہے اور میں ایمانداروں کو ہٹانے والا نہیں بے شک و ہ اپنے رب سے ملنے والے ہیں لیکن تمہیں جاہل قوم دیکھتا ہوں'),
  ('ur.ahmedali', 11, 30, 'اور اے میری قوم اگر میں انہیں ہٹا دوں تو مجھے الله سے کون چھڑائے گا کیا پھر تم نہیں سمجھتے'),
  ('ur.ahmedali', 11, 31, 'اور میں تمہیں نہیں کہتا کہ میرے پاس الله کے خزانے ہیں اور نہ یہ کہ میں غیب دان ہوں اور نہ یہ کہتا ہوں کہ میں فرشتہ ہوں اور نہ یہ کہوں گاکہ جو لوگ تمہاری نظر میں حقیر ہیں الله ان کو بھلائی نہ دے گا الله خوب جانتا ہے جو کچھ ان کے دلوں میں ہے ایسا کہوں تو میں بے انصاف ہوں'),
  ('ur.ahmedali', 11, 32, 'کہا اے نوح تو نے ہم سے جھگڑا کیا او ربہت جھگڑا کر چکا اب لے آ جو تو ہم سے وعدہ کرتا ہے اگر تو سچا ہے'),
  ('ur.ahmedali', 11, 33, 'نوح نے کہا اسے تو اگرچاہے گا الله ہی لائے گا اور تم اسے روک نہ سکو گے'),
  ('ur.ahmedali', 11, 34, 'اور میری نصیحت تمہیں فائدہ نہ دے گی خواہ میں کتنی ہی نصیحت کرنا چاہوں اگر الله کو تمہیں گمراہ رکھنا ہی منظور ہے وہی تمہارا رب ہے اور اسی کی طرف تمہیں پھر جانا ہے'),
  ('ur.ahmedali', 11, 35, 'کیا کہتے ہیں کہ قرآن کو خود بنا لایا ہے کہہ دو اگر میں بنا لایا ہوں تو اس کا گناہ مجھ پر ہے اور میں تمہارے گناہوں سے بری ہوں'),
  ('ur.ahmedali', 11, 36, 'اور نوح کی طرف وحی کی گئی کہ تیری قوم میں سے اب کوئی ایمان نہیں لائے گا مگر جو لا چکا پھر غم نہ کر اور کاموں پر جو کر رہے ہیں'),
  ('ur.ahmedali', 11, 37, 'اور ہمارے روبرو اور ہمارے حکم سے کشتی بنا اور ظالمو ں کے حق میں مجھ سے کوئی بات نہ کر بے شک وہ غرق کیے جائیں گے'),
  ('ur.ahmedali', 11, 38, 'اور وہ کشتی بناتے تھے اور جب اس کی قوم کے سردار اس پر گزرتے اس سے ہنسی کرتے کہتے اگر تم ہم پر ہنستے ہو تو ہم بھی تم پر ہنسیں گے جیسے تم ہنستے ہو'),
  ('ur.ahmedali', 11, 39, 'تمہیں جلدی معلوم ہو جائے گا کہ کس پر عذاب آتا ہے جو اسے رسوا کرے گا اورکسی پر دائمی عذاب اترتا ہے'),
  ('ur.ahmedali', 11, 40, 'یہاں تک کہ جب ہمارا حکم پہنچا اور تنور نے جوش مارا ہم نے کہا کشتی میں ہر قسم کے جوڑا نر مادہ چڑھا لے اور اپنے گھر والوں کو مگر وہ جن کے متعلق فیصلہ ہو چکا ہے اور سب ایمان والوں کو اور اس کے ساتھ ایمان تو بہت کم لائے تھے'),
  ('ur.ahmedali', 11, 41, 'اور کہا اس میں سوار ہو جاؤ اس کا چلنا اور ٹھیرنا الله کے نا م سے ہےبے شک میرا رب بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 11, 42, 'اور وہ انہیں پہاڑ جیسی لہروں میں لیے جارہی تھی اورنوح نے اپنے بیٹے کو پکارا جب کہ وہ کنارے پر تھا اے بیٹے ہمارے ساتھ سوار ہو جا اور کافروں کے ساتھ نہ رہ'),
  ('ur.ahmedali', 11, 43, 'کہا میں ابھی کسی پہاڑ کی پناہ لے لیتا ہوں جو مجھے پانی سے بچا لے گا کہا آج الله کے حکم سے کوئی بچانے والا نہیں مگر جس پر وہی رحم کرے اور دونوں کے درمیان موج حائل ہو گئی پھر ڈوبنے والوں میں ہوگیا'),
  ('ur.ahmedali', 11, 44, 'اور حکم آیا اے زمین اپنا پانی نگل جا اور اے آسمان تھم جا اور پانی سکھا دیا گیا اور کام ہو چکا اور کشتی جودی پہاڑ پر ٹھری اور کہہ دیا گیا کہ ظالموں پر پھٹکار ہے'),
  ('ur.ahmedali', 11, 45, 'اور نوح نے اپنے رب کو پکارا اے رب میرا بیٹا میرے گھر والو ں میں سے ہے اوربے شک تیار وعدہ سچا ہے اور تو سب سے بڑا حاکم ہے'),
  ('ur.ahmedali', 11, 46, 'فرمایا اے نوح وہ تیرے گھر والو ں میں سے نہیں ہے کیوں کہ اس کے عمل اچھے نہیں ہیں سو مجھ سے مت پوچھ جس کا تجھے علم نہیں میں تمہیں نصیحت کرتا ہوں کہ کہیں جاہلوں میں نہ ہو جاؤ'),
  ('ur.ahmedali', 11, 47, 'کہا اے رب میں تیری پناہ لیتا ہوں اس بات سے کہ تجھ سے وہ بات پوچھوں جو مجھے معلوم نہیں اور اگر تو نے مجھے نہ بخشا اورمجھ پر رحم نہ کیا تو میں نقصان والوں میں ہو جاؤں گا'),
  ('ur.ahmedali', 11, 48, 'کہا گیا اے نوح ہماری طرف سے سلامتی اور برکتوں کے ساتھ جو تم پر اور تمہارے ساتھ والوں پر رہیں گی کشتی سے اتر اور دوسرے فرقے ہیں کہ ہم انھیں دنیا میں فائدہ دیں گے پھر انہیں ہماری طرف سے دردناک عذاب پہنچے گا'),
  ('ur.ahmedali', 11, 49, 'یہ غیب کی خبریں ہیں جنہیں ہم آپ کی طرف وحی کر رہے ہیں اس سے پہلے نہ تو آپ ہی جانتے تھے اور نہ آپ کی قوم جانتی تھی پس صبر کر کیوں کہ بہتر انجام پرہیزگاروں کے لیے ہے'),
  ('ur.ahmedali', 11, 50, 'اور ہم نے عاد کی طرف ان کے بھائی ہود کو بھیجا اے قوم الله کی بندگی کرو اس کے سوا تمہارا کوئی حاکم نہیں تم سب جھوٹ کہتے ہو'),
  ('ur.ahmedali', 11, 51, 'اے قوم میں اس پر تم سے مزدوری نہیں مانگتا میری مزدوری اسی پر ہے جس نے مجھے پیدا کیا پھر کیا تم نہیں سمجھتے'),
  ('ur.ahmedali', 11, 52, 'اور اے قوم اپنے رب سے معافی مانگو پھر اس کی طرف رجوع کرو وہ تم پر خوب بارشیں برسائے گا اور تمہاری قوت کو اوربڑھائے گا اورتم نافرمان ہو کر نہ پھر جاؤ'),
  ('ur.ahmedali', 11, 53, 'کہا اے ہود تو ہمارے پاس کوئی معجزہ بھی نہ لایا اور ہم تیرے کہنے سے اپنے معبودوں کو چھوڑنے والے نہیں اورنہ ہم تجھے ماننے والے ہیں'),
  ('ur.ahmedali', 11, 54, 'ہم تو یہی کہتے ہیں کہ تجھےہمارے کسی معبود نے بری طرح جھپٹ لیا ہے کہا بے شک میں الله کو گواہ کرتا ہوں اورتم بھی گواہ رہو کہ میں ان چیزوں سے بیزار ہوں جنہیں تم الله کے سوا شریک کرتے ہو'),
  ('ur.ahmedali', 11, 55, 'سوتم سب مل کر میرے حق میں برائی کرو پھر مجھے مہلت نہ دو'),
  ('ur.ahmedali', 11, 56, 'میں نے الله پر بھروسہ کیا ہے جو میرا اور تمہارا رب ہے کوئی بھی زمین پر ایسا چلنے والا نہیں کہ جس کی چوٹی اس نے نہ پکڑ رکھی ہو بے شک میرا رب سیدھے راستے پر ہے'),
  ('ur.ahmedali', 11, 57, 'پھر اگر تم منہ پھیرو گے تو جو مجھے دے کر بھیجا گیا تھا وہ تمہیں پہنچا دیا اور میرا رب تمہاری جگہ اور قوم پیدا کر دے گا اور تم اس کا کچھ بھی بگاڑنہیں سکو گے بے شک میرا رب ہر چیزپر نگہبان ہے'),
  ('ur.ahmedali', 11, 58, 'اور جب ہمارا حکم پہنچا تو ہم نے ہود کو اورانہیں جو اس کے ساتھ ایمان لائے تھے اپنی رحمت سے بچا لیا اور ہم نے انہیں سخت عذاب سے نجات دی'),
  ('ur.ahmedali', 11, 59, 'اور یہ عاد تھے کہ اپنے رب کی باتوں سے منکر ہوئے اوراس کے رسولوں کو نہ مانا اور ہر ایک جبار سرکش کا حکم مانتے تھے'),
  ('ur.ahmedali', 11, 60, 'اور اس دنیا میں بھی اپنے پیچھے لعنت چھوڑ گئے اور قیامت کے دن بھی خبردار بےشک عاد نے اپنے رب کا انکار کیا تھا خبردار عاد جو ہود کی قوم تھی الله کی رحمت سے دور کی گئی'),
  ('ur.ahmedali', 11, 61, 'اور ثمود کی طرف ان کے بھائی صالح کو بھیجا اے میری قوم الله کی بندگی کرو اس کے سوا تمہارا کوئی معبود نہیں اسی نے تمہیں زمین سے بنایا اورتمہیں اس میں آباد کیا پس اس سے معافی مانگو پھر اس کی طرف رجوع کرو بے شک میرا رب نزدیک ہے قبول کرنے والا'),
  ('ur.ahmedali', 11, 62, 'انہوں نے کہا اے صالح اس سے پہلے تو ہمیں تجھ سے بڑی امید تھی تم ہمیں ان معبودوں کے پوجنے سےمنع کرتے ہو جنہیں ہمارے باپ دادا پوجتے چلے آئے ہیں اورجس طرف تم ہمیں بلاتے ہو اس سے تو ہم بڑے شک میں ہیں'),
  ('ur.ahmedali', 11, 63, 'صالح نے کہا اےمیری قوم بھلا دیکھو تو اگر میں اپنے رب کی طرف سے کوئی کھلی دلیل رکھتا ہوں اور اس کی طرف سے میرے پاس رحمت بھی آ چکی ہو پھر اگر میں اس کی نافرمانی کروں تو مجھے اس سے کون بچا سکتا ہے پھر تم مجھے نقصان کے سوا اور کیا دے سکو گے'),
  ('ur.ahmedali', 11, 64, 'اور اےمیری قوم یہ الله کی اونٹنی تمہارے لیے نشانی ہے سواسے چھوڑ دو الله کی زمین میں کھاتی پھرے اور اسے برائی سے چھونا بھی نہیں (ورنہ) پھر تمہیں عذاب بہت جلد آ پکڑے گا'),
  ('ur.ahmedali', 11, 65, 'پھر انہوں نے اس کے پاؤں کاٹ ڈالے تب صالح نے کہا تین دن تک اپنے گھروں میں فائدہ اٹھا لو یہ وعدہ ہے جو جھوٹا نہ ہوگا'),
  ('ur.ahmedali', 11, 66, 'پھر جب ہمارا حکم آ پہنچا تو ہم نے صالح کو اورجو اس کے ساتھ ایمان لائے تھے اپنی رحمت سے بچا لیا اور اس دن کی رسوائی سے نجات دی بے شک تیرا رب وہی زور والا زبردست ہے'),
  ('ur.ahmedali', 11, 67, 'اوران ظالموں کو ہولناک آواز نے پکڑ لیا پھر صبح کو اپنے گھروں میں اوندھے پڑے ہوئے رہ گئے'),
  ('ur.ahmedali', 11, 68, 'گویا کہ کبھی وہاں رہے ہی نہ تھے خبردار ثمود نے اپنے رب کا انکار کیا تھا خبردار ثمود پر پھٹکار ہے'),
  ('ur.ahmedali', 11, 69, 'اور ہمارے بھیجے ہوئے ابراھیم کے پاس خوشخبری لے کر آئے انہوں نے کہا سلام اس نے کہا سلام پس دیر نہ کی کہ ایک بھنا ہوا بچھڑا لے آیا'),
  ('ur.ahmedali', 11, 70, 'پھر جب دیکھا کہ ان کے ہاتھ اس تک نہیں پہنچتے تو انہیں اجنبی سمجھا اوران سے ڈرا انہوں نے کہا خوف نہ کرو ہم تو لوط کی قوم کی طرف بھیجحے گئے ہیں'),
  ('ur.ahmedali', 11, 71, 'اور اس کی عورت کھڑی تھی تب وہ ہنس پڑی پھر ہم نے اسے اسحاق کے پیدا ہونے کی خوشخبری دی اور اسحاق کے بعد یعقوب کی'),
  ('ur.ahmedali', 11, 72, 'وہ بولی اے افسوس کیا میں بوڑھی ہو کر جنوں گی میرا خاوند بھی بوڑھا ہے یہ تو ایک عجیب بات ہے'),
  ('ur.ahmedali', 11, 73, 'انہوں نے کہا کیاتو الله کے حکم سے تعجب کرتی ہے تم پر اے گھر والو الله کی رحمت اور اس کی برکتیں ہیں بے شک وہ تعریف کیا ہوا بزرگ ہے'),
  ('ur.ahmedali', 11, 74, 'جب ابراھیم سے ڈر جاتا رہا اور اسے خوشخبری آئی ہم سے قوم لوط کے حق میں جھگڑنے لگا'),
  ('ur.ahmedali', 11, 75, 'بے شک ابراھیم بردبار نرم دل اور الله کی طرف رجوع کرنے والا تھا'),
  ('ur.ahmedali', 11, 76, 'اے ابراھیم یہ خیال چھوڑ دے کیوں کہ تیرے رب کا حکم آ چکا ہے اور بے شک ان پرعذاب آ کر ہی رہے گا جو ٹلنے والا نہیں'),
  ('ur.ahmedali', 11, 77, 'اور جب ہمارے بھیجے ہوئے لوط کے پاس پہنچے تو ان کے آنے سے غمگین ہوا اور دل میں تنگ ہوا اور کہا آج کا دن بڑا سخت ہے'),
  ('ur.ahmedali', 11, 78, 'اور اس کے پاس اس کی قوم بے اختیار دوڑتی آئی اور یہ لوگ پہلے ہی سے برے کام کیا کرتے تھے کہا اےمیری قوم یہ میری بیٹیاں ہیں یہ تمہارے لیے پاک ہیں سو تم الله سے ڈرو اور میرے مہمانو ں میں مجھے ذلیل نہ کرو کیا تم میں کوئی بھی بھلا آدمی نہیں'),
  ('ur.ahmedali', 11, 79, 'انہوں نے کہا البتہ تحقیق تو جانتا ہے کہ ہمیں تیری بیٹیوں سے کوئی غرض نہیں اور تجھے معلوم ہے جو ہم چاہتے ہیں'),
  ('ur.ahmedali', 11, 80, 'کہا کاش کہ مجھے تمہارے مقابلے کی طاقت ہو تی یا میں کسی زبردست سہارے کی پناہ جا لیتا'),
  ('ur.ahmedali', 11, 81, 'فرشتوں نے کہا اے لوط بے شک ہم تیرے رب کے بھیجے ہوئے ہیں یہ تم تک ہرگز نہ پہنچ سکیں گے سو کچھ حصہ رات رہے اپنے لوگوں کو لے نکل اور تم میں سے کوئی مڑ کر نہ دیکھے مگر تیری عورت کہ اس پر بھی وہی بلا آنے والی ہے جو ان پر آئے گی ان کے وعدہ کا وقت صبح ہے کیا صبح کا وقت نزدیک نہیں ہے'),
  ('ur.ahmedali', 11, 82, 'پھر جب ہمارا حکم پہنچا تو ہم نے وہ بستیاں الٹ دیں اور اس زمین پر کھنگر کے پتھر برسانا شروع کیے جو لگاتار گر رہے تھے'),
  ('ur.ahmedali', 11, 83, 'جن پر تیرے رب کے ہاں سے خاص نشان بھی تھا اور یہ بستیاں ان ظالموں سے کچھ دور نہیں ہیں'),
  ('ur.ahmedali', 11, 84, 'اورمدین کی طرف ان کے بھائی شعیب کو بھیجا کہ اے میری قوم الله کی بندگی کرو اس کے سوا تمہارا کوئی معبود نہیں اور ناپ اور تول کو نہ گھٹاؤ میں تمہیں آسودہ حال دیکھتا ہوں اور تم پر ایک گھیر لینے والے دن کے عذاب سے ڈرتا ہوں'),
  ('ur.ahmedali', 11, 85, 'اور اے میری قوم انصاف سے ناپ اور تول کو پورا کرو اور لوگو ں کو ان کی چیزیں گھٹا کر نہ دو اور زمین میں فساد نہ مچاؤ'),
  ('ur.ahmedali', 11, 86, 'الله کا دیا جو باقی بچ رہے وہ تمہارے لیے بہتر ہے اگر تم ایماندار ہو اور میں تمہارا نگہبان نہیں ہوں'),
  ('ur.ahmedali', 11, 87, 'انہوں نے کہا اے شعیب کیا تیری نماز تجھے یہی حکم دیتی ہے کہ ہم ان چیزوں کو چھوڑ دیں جنہیں ہمارے باپ باپ دادا پوجتے تھے یا اپنے مالوں میں اپنی خواہش کے مطابق معاملہ نہ کریں بے شک تو البتہ بردبار نیک چلن ہے'),
  ('ur.ahmedali', 11, 88, 'کہا اے میری قوم دیکھو تو سہی اگر مجھے اپنے رب کی طرف سے سمجھ آ گئی ہے اور اس نے مجھے عمدہ روزی دی ہے اور میں یہ نہیں چاہتا کہ جس کام سے تجھے منع کروں میں اس کے خلاف کروں میں تو اپنی طاقت کے مطابق اصلاح ہی چاہتا ہوں اور مجھے تو صرف الله ہی سے توفیق حاصل ہوتی ہے میں اسی پر بھروسہ کرتا ہوں اور اسی کی طرف رجوع کرتا ہوں'),
  ('ur.ahmedali', 11, 89, 'اوراے میری قوم کہیں میری ضد سے ایسا جرم نہ کر بیٹھنا جس سے وہی مصیبت نہ آ پڑے جیسی کہ قوم نوح یا قوم ہود یا قوم صالح پر پڑی تھی اور لوط کی قوم بھی تم سے دور نہیں'),
  ('ur.ahmedali', 11, 90, 'اور اپنے الله سے معافی مانگو پھر اس کی طرف رجوع کرو بے شک میرا رب مہربان محبت والا ہے'),
  ('ur.ahmedali', 11, 91, 'انہوں نے کہا اے شعیب ہم بہت سی باتیں نہیں سمجھتے جو تم کہتے ہو اوربے شک ہم البتہ تمہیں اپنےمیں کمزور پاتے ہیں اور اگر تیری برادری نہ ہوتی تو تجھے ہم سنگسارکردیتے اور ہماری نظر میں تیری کوئی عزت نہیں ہے'),
  ('ur.ahmedali', 11, 92, 'کہا اے میری قوم کیا میری برادری کا دباؤ تم پر الله سے زیادہ ہے اس کو تم نے پس پشت ڈال دیا ہے بے شک میرا رب تمہارے سب اعمال پر احاطہ کرنے والا ہے'),
  ('ur.ahmedali', 11, 93, 'اور اے میری قوم اپنی جگہ پر کام کیے جاؤ میں تم بھی کام کرتا ہوں آئندہ معلوم کر لو گے کس پر رسوا کرنے والا عذاب آتا ہے اور جھوٹا کون ہے اورانتظار کرو بے شک میں بھی تمہارے ساتھ انتظار کر رہا ہوں'),
  ('ur.ahmedali', 11, 94, 'اور جب ہمارا حکم آ گیا تو ہم نے شعیب کو اور ان لوگوں کو جو ان کے ساتھ ایمان لائے تھے اپنی رحمت سے بچا لیا اوران ظالموں کو کڑک نے آ پکڑا پھر صبح کو اپنے گھروں میں اوندھے پڑے ہوئے رہ گئے'),
  ('ur.ahmedali', 11, 95, 'گویا کبھی وہاں بسے ہی نہ تھے خبردار مدین پر پھٹکار ہے جیسے ثمود پر پھٹکار ہوئی تھی'),
  ('ur.ahmedali', 11, 96, 'اور البتہ تحقیق ہم نے موسیٰ کو اپنی نشانیاں اور واضع سند دے کر بھیجا'),
  ('ur.ahmedali', 11, 97, 'فرعون اور اس کے سرداروں کے ہاں پھر وہ فرعون کے حکم پر چلے اور فرعون کا حکم ٹھیک بھی نہ تھا'),
  ('ur.ahmedali', 11, 98, 'قیامت کے دن اپنی قوم کے آگے ہو گا پھر انہیں آگ میں لاڈالے گا اوربرا گھاٹ ہے جس پر وہ پہنچے'),
  ('ur.ahmedali', 11, 99, 'اور اپنے پیچھے اس جہان میں بھی لعنت چھوڑ گئے اور قیامت کے دن کے لیے بھی برا ہی انعام ہے جو انہیں دیا جائے گا'),
  ('ur.ahmedali', 11, 100, 'یہ بستیوں کے تھوڑے سے حالات ہیں کہ تجھے سنا رہے ہیں ان میں سے کچھ تو اب تک باقی ہیں اورکچھ اجڑی پڑی ہیں'),
  ('ur.ahmedali', 11, 101, 'اور ہم نے ان پر ظلم نہیں کیا لیکن وہی اپنی جانو ں پر ظلم کر گئے پھر ان کے وہ معبود کچھ کام نہ آئے جنہیں و ہ الله کے سوا پکارتے تھے جس وقت تیرے رب کا حکم آ پہنچا اور ان معبودوں نے سوا ہلاکت کے انہیں کچھ بھی فائدہ نہ دیا'),
  ('ur.ahmedali', 11, 102, 'اور تیرے رب کی پکڑ ایسی ہی ہوتی ہے جب وہ ظالم بستیوں کو پکڑتا ہے اور اس کی پکڑ سخت تکلیف دہ ہے'),
  ('ur.ahmedali', 11, 103, 'اس بات میں نشانی ہے اس کے لیے جو آخرت کے عذاب سے ڈرتا ہے یہ ایک ایسا دن ہوگا جس میں سب لوگ جمع ہوں گے اور یہی دن ہے جس میں سب حاضر کیے جائیں گے'),
  ('ur.ahmedali', 11, 104, 'اور ہم اسے تھوڑی مدت کے لیے ملتوی کیے ہوئے ہیں'),
  ('ur.ahmedali', 11, 105, 'جب وہ دن آئے گا تو کوئی شخص الله کی اجازت کے سوا بات بھی نہ کر سکے گا سو ان میں سے بعض بدبخت ہیں اوربعض نیک بخت'),
  ('ur.ahmedali', 11, 106, 'پھر جو بد ہوں گےتو وہ آگ میں ہوں گے کہ اس میں ان کی چیخ و پکار پڑی رہے گی'),
  ('ur.ahmedali', 11, 107, 'اس میں ہمیشہ رہیں گے جب تک آسمان زمین قائم ہیں ہاں اگر تیرے الله ہی کو منظور ہو (تو دوسری بات ہے) بے شک تیار رب جو چاہے اسے پورےطور سے کر سکتا ہے'),
  ('ur.ahmedali', 11, 108, 'اور جو لوگ نیک بخت ہیں سو جنت میں ہو ں گے اس میں ہمیشہ رہیں گے جب تک آسمان زمین قائم ہیں ہاں اگر تیرے الله ہی کو منظور ہو تو (دوسری بات ہے) یہ بے انتہا عطیہ ہو گا'),
  ('ur.ahmedali', 11, 109, 'سو تو ان چیزوں سے شک میں نہ رہ جنہیں یہ پوجتے ہیں یہ لوگ کچھ نہیں پوجتے مگر اسی طرح سے کہ جس طرح ان سے پہلے ان کے باپ دادا پوجتے تھے اور بے شک ہم انہیں عذاب کا پورا حصہ دے کر رہیں گے'),
  ('ur.ahmedali', 11, 110, 'اور البتہ ہم نے موسیٰ کو کتاب دی تھی پھراس میں اختلاف کیا گیا اور اگر تیرے رب کی طرف سے ایک بات مقرر نہ ہو چکی ہوتی تو ان میں فیصلہ ہو جاتا اور بے شک اس کی طرف سے ایسے شک میں ہیں کہ مطمئن نہیں ہو نے دیتا'),
  ('ur.ahmedali', 11, 111, 'اورجتنے لوگ ہیں جب وقت آیا تیرا رب انہیں ان کے اعمال پورے دے گا بےشک وہ خبردار ہے اس چیز سے جو کر رہے ہیں'),
  ('ur.ahmedali', 11, 112, 'سو تو پکا رجیسا تجھے حکم دیا گیا ہے اور جنہوں نے تیرے ساتھ توبہ کی ہے اور حد سے نہ بڑھو بے شک وہ دیکھتا ہے جو کچھ تم کرتے ہو'),
  ('ur.ahmedali', 11, 113, 'اوران کی طرف مت جھکو جو ظالم ہیں پھر تمہیں بھی آگ چھوئے گی اور الله کے سوا تمہارا کوئی مددگار نہیں ہے پھر کہیں سے مدد نہ پاؤ گے'),
  ('ur.ahmedali', 11, 114, 'اور دن کے دونو ں طرف اورکچھ حصہ رات کا نماز قائم کر بے شک نیکیاں برائیوں کو دور کرتی ہیں یہ نصیحت حاصل کرنے والوں کے لیے نصیحت ہے'),
  ('ur.ahmedali', 11, 115, 'اور صبر کر بے شک الله نیکی کرنے والوں کا اجر ضائع نہیں کرتا'),
  ('ur.ahmedali', 11, 116, 'سو ان جماعتوں میں ایسے لوگ کیوں نہ ہوئے جو تم سے پہلے تھیں جو ملک میں فساد پھیلانے سے منع کرتے بجز چند آدمیوں کے جنہیں ہم نے ان میں سے بچا لیا تھا اور جن لوگو ں نے نافرمانی کی تھی وہ تو انہیں لذتوں کے پیچھے پڑے رہے جو ان کو دی گئی تھیں اور وہ مجرم تھے'),
  ('ur.ahmedali', 11, 117, 'اور تیرا رب ہرگز ایسا نہیں جو بستیوں کو زبردستی ہلاک کر دے اور وہاں کے لوگ نیک ہوں'),
  ('ur.ahmedali', 11, 118, 'اور اگر تیرا رب چاہتا تو سب لوگو ں کو ایک رستہ پر ڈال دیتا اور ہمیشہ اختلاف میں رہیں گے'),
  ('ur.ahmedali', 11, 119, 'مگر جس پر تیرے رب نے رحم کیا اور اسی لیے انہیں پیدا کیا ہے اور تیرے رب کی یہ بات پوری ہو کر رہے گی کہ البتہ دوزخ کو اکھٹے جنوں اور آدمیوں سے بھر دوں گا'),
  ('ur.ahmedali', 11, 120, 'اور ہم رسولوں کے حالات تیرے پاس اس لیے بیان کرتے ہیں کہ ان سے تیرے دل کو مضبوط کر دیں اور ان واقعات میں تیرے پاس حق بات پہنچ جائے گی اور ایمانداروں کے لیے نصیحت اور یاد دہانی ہے'),
  ('ur.ahmedali', 11, 121, 'اوران سے کہہ دو جو ایمان نہیں لاتے اپنے جگہ پر کام کیے جاؤ ہم بھی کام کرتے ہیں'),
  ('ur.ahmedali', 11, 122, 'اور انتظار کرو ہم بھی منتظر ہیں'),
  ('ur.ahmedali', 11, 123, 'اور آسمانوں اور زمین کی پوشیدہ بات الله ہی جانتا ہے اور سب کام کا رجوع اسی کی طرف ہے پس اسی کی عبادت کرو اور اسی پر بھروسہ رکھ اور تیرا رب بے خبر نہیں اس سے جو کرتے ہو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 11, 1, 'Elif, Lam, Ra. Bu Kitap, hakim ve haberdar olan Allah tarafından, Allah\'tan başkasına kulluk etmeyesiniz diye ayetleri kesin kılınmış, sonra da uzun uzadıya açıklanmış bir Kitap\'dır. Ben size, O\'nun tarafından gönderilmiş bir uyarıcı ve müjdeciyim. Rabbinizden mağfiret dileyin ve O\'na tevbe edin ki, belli bir süreye kadar sizi güzelce geçindirsin ve her fazilet sahibine faziletinin karşılığını versin. Eğer yüz çevirirseniz o zaman ben doğrusu hakkınızda büyük günün azabından korkarım.'),
  ('tr.diyanet', 11, 2, 'Elif, Lam, Ra. Bu Kitap, hakim ve haberdar olan Allah tarafından, Allah\'tan başkasına kulluk etmeyesiniz diye ayetleri kesin kılınmış, sonra da uzun uzadıya açıklanmış bir Kitap\'dır. Ben size, O\'nun tarafından gönderilmiş bir uyarıcı ve müjdeciyim. Rabbinizden mağfiret dileyin ve O\'na tevbe edin ki, belli bir süreye kadar sizi güzelce geçindirsin ve her fazilet sahibine faziletinin karşılığını versin. Eğer yüz çevirirseniz o zaman ben doğrusu hakkınızda büyük günün azabından korkarım.'),
  ('tr.diyanet', 11, 3, 'Elif, Lam, Ra. Bu Kitap, hakim ve haberdar olan Allah tarafından, Allah\'tan başkasına kulluk etmeyesiniz diye ayetleri kesin kılınmış, sonra da uzun uzadıya açıklanmış bir Kitap\'dır. Ben size, O\'nun tarafından gönderilmiş bir uyarıcı ve müjdeciyim. Rabbinizden mağfiret dileyin ve O\'na tevbe edin ki, belli bir süreye kadar sizi güzelce geçindirsin ve her fazilet sahibine faziletinin karşılığını versin. Eğer yüz çevirirseniz o zaman ben doğrusu hakkınızda büyük günün azabından korkarım.'),
  ('tr.diyanet', 11, 4, 'Dönüşünüz ancak Allah\'adır. O her şeye Kadir\'dir.'),
  ('tr.diyanet', 11, 5, 'Bilin ki, onlar Kuran okunurken gizlenmek için iki büklüm olurlar. Bilin ki, elbiselerine büründüklerinde bile Allah onların gizlediklerini ve açığa vurduklarını bilir. Çünkü O, kalblerde olanı bilendir.'),
  ('tr.diyanet', 11, 6, 'Yeryüzünde yaşayan bütün canlıların rızkı ancak Allah\'a aittir. O, canlıları babaların sulbünde kararlaşmış ve anaların rahminde kararlaşmakta iken de bilir. Her şey apaçık bir Kitaptadır.'),
  ('tr.diyanet', 11, 7, 'Arş\'ı su üzerinde iken, hanginizin daha güzel işi işleyeceğini ortaya koymak için, gökleri ve yeri altı günde yaratan O\'dur. And olsun ki, "Siz gerçekten, ölümden sonra dirileceksiniz" desen, inkar edenler: "Bu, apaçık bir sihirden başka bir şey değildir" derler.'),
  ('tr.diyanet', 11, 8, 'And olsun ki, onların azabını sayılı bir süreye kadar ertelesek, "Onu alıkoyan nedir?" derler. Bilin ki, onlara azab geldiği gün, artık geri çevrilmez; alaya aldıkları şey onları mahvedecektir.'),
  ('tr.diyanet', 11, 9, 'And olsun ki, insana nimetimizi tattırır sonra onu ondan çekip alırsak, o şüphesiz umutsuz bir nanköre döner.'),
  ('tr.diyanet', 11, 10, 'Başına gelen sıkıntıdan sonra, ona bir nimet tattırırsak, "Musibetler başımdan gitti" der; doğrusu o, şımarıp böbürlenen biridir.'),
  ('tr.diyanet', 11, 11, 'Bunların dışında, sabredip iyi işler işleyen kimseler, işte onlara mağfiret ve büyük ecir vardır.'),
  ('tr.diyanet', 11, 12, 'Putperestlerin: "Ona bir hazine indirilmeli veya yanında bir melek gelmeli değil miydi?" demelerinden senin kalbin daralır ve belki de sana vahyolunanın bir kısmını terkedecek olursun. Sen ancak bir uyarıcısın, Allah her şeye vekildir.'),
  ('tr.diyanet', 11, 13, 'Senin için: "Onu uydurdu" diyorlar, öyle mi? De ki: "Öyleyse onun surelerine benzer uydurma on sure meydana getirin, iddianızda samimi iseniz, Allah\'tan başka çağırabileceklerinizi de çağırın."'),
  ('tr.diyanet', 11, 14, 'Söylediğinizi yapamazlarsa, bilin ki o, ancak Allah\'ın ilmiyle indirilmiştir. O\'ndan başka tanrı yoktur, artık müslümansınız değil mi?'),
  ('tr.diyanet', 11, 15, 'Dünya hayatını ve güzelliklerini isteyenlere, orada işlediklerinin karşılığını tastamam veririz; onlar orada bir eksikliğe de uğratılmazlar.'),
  ('tr.diyanet', 11, 16, 'İşte ahirette onlara ateşten başka bir şey yoktur. İşledikleri şeyler orada boşa gitmiştir. Zaten yapmakta oldukları da batıldır.'),
  ('tr.diyanet', 11, 17, 'Rabbinin katından bir belgesi ve onun arkasından da bir şahidi olanlar, önlerinde de Musa\'nın Kitap\'ı önder ve rahmet olarak bulunanlardır ki, işte onlar Kuran\'a inanırlar. Hangi topluluk onu inkar ederse yeri ateştir; senin de bundan şüphen olmasın. Doğrusu o, Rabbinden bir gerçektir, fakat insanların çoğu inanmazlar.'),
  ('tr.diyanet', 11, 18, 'Yalan söyleyerek Allah\'a iftira edenden daha zalim kim vardır? İşte bunlar Rablerine götürülürler ve şahidler: "Rablerine yalan söyleyenler bunlardır" derler. Bilin ki Allah\'ın laneti haksızlık yapanlaradır.'),
  ('tr.diyanet', 11, 19, 'Bunlar Allah\'ın yolundan alıkorlar ve o yolu eğriltmeğe çalışırlar; işte onlar ahireti inkar edenlerdir.'),
  ('tr.diyanet', 11, 20, 'Bunlar yeryüzünde Allah\'ı aciz bırakamazlar. Allah\'dan başka kendilerini kurtaracak dostları da yoktur. Azab onlara kat kat verilir; işitemezler ve göremezlerdi.'),
  ('tr.diyanet', 11, 21, 'İşte bunlar kendilerine yazık edenlerdir. Uydurdukları putlar da onlardan uzaklaşıp kaybolmuştur.'),
  ('tr.diyanet', 11, 22, 'Ahirette en çok kayba uğrayacaklar şüphesiz bunlardır.'),
  ('tr.diyanet', 11, 23, 'Doğrusu inanan ve yararlı iş yapanlar ve Rablerine boyun eğenler, işte onlar cennetliklerdir; orada temellidirler.'),
  ('tr.diyanet', 11, 24, 'Bu iki zümrenin durumu, kör ve sağır kimse ile gören ve işiten kimsenin durumuna benzer. Durumları hiç eşit olabilir mi? İbret almıyor musunuz?'),
  ('tr.diyanet', 11, 25, 'And olsun ki biz Nuh\'u kendi milletine gönderdik; "Ben sizin için apaçık bir uyarıcıyım; Allah\'tan başkasına kulluk etmeyin; doğrusu ben hakkınızda can yakıcı bir günün azabından korkuyorum" dedi.'),
  ('tr.diyanet', 11, 26, 'And olsun ki biz Nuh\'u kendi milletine gönderdik; "Ben sizin için apaçık bir uyarıcıyım; Allah\'tan başkasına kulluk etmeyin; doğrusu ben hakkınızda can yakıcı bir günün azabından korkuyorum" dedi.'),
  ('tr.diyanet', 11, 27, 'Milletinin inkarcı ileri gelenleri: "Senin ancak kendimiz gibi bir insan olduğunu görüyoruz. Daha başlangıçta, sana bizim ayak takımı dışında kimsenin uyduğunu görmüyoruz. Sizin bizden bir üstünlüğünüz yoktur; biz sizi yalancı sanıyoruz" dediler.'),
  ('tr.diyanet', 11, 28, 'Nuh: "Ey milletim! Rabbimin katından bir delilim bulunsa ve bana yine katından bir rahmet vermiş de bunlar sizden gizlenmiş olsa, söyleyin bana, hoşlanmadığınız halde zorla sizi bunlara mecbur mu ederiz?" dedi.'),
  ('tr.diyanet', 11, 29, '"Ey milletim! Buna karşılık ben sizden bir mal da istemiyorum. Benim ücretim Allah\'a aittir; inananları da kovacak değilim; çünkü onlar Rableriyle karşılaşacaklar; fakat ben sizi cahil bir millet olarak görüyorum."'),
  ('tr.diyanet', 11, 30, '"Ey milletim! Onları kovarsam, Allah\'a karşı beni kim savunur? Düşünmez misiniz?"'),
  ('tr.diyanet', 11, 31, '"Size, Allah\'ın hazineleri yanımdadır demiyorum; gaybı da bilmem; doğrusu melek olduğumu da söylemiyorum; küçük gördüklerinize Allah iyilik vermeyecektir diyemem; içlerinde olanı Allah daha iyi bilir. Yoksa şüphesiz haksızlık edenlerden olurum."'),
  ('tr.diyanet', 11, 32, '"Ey Nuh! Bizimle cidden tartıştın; hem de çok tartıştın. Doğru sözlülerden isen tehdit ettiğin azabı başımıza getir" dediler.'),
  ('tr.diyanet', 11, 33, '"Ancak Allah dilerse onu başınıza getirir, siz O\'nu aciz bırakamazsınız. Allah sizi azdırmak isterse, ben size öğüt vermek istesem de faydası olmaz. O, sizin Rabbinizdir, O\'na döndürüleceksiniz" dedi.'),
  ('tr.diyanet', 11, 34, '"Ancak Allah dilerse onu başınıza getirir, siz O\'nu aciz bırakamazsınız. Allah sizi azdırmak isterse, ben size öğüt vermek istesem de faydası olmaz. O, sizin Rabbinizdir, O\'na döndürüleceksiniz" dedi.'),
  ('tr.diyanet', 11, 35, 'Sana "Kuran\'ı kendiliğinden uydurdu" derler, de ki: "Uydurdumsa suçu bana aittir; oysa ben sizin işlediğiniz günahlardan uzağım."'),
  ('tr.diyanet', 11, 36, 'Nuh\'a, "Senin milletinden, inanmış olanlardan başkası inanmayacaktır; onların yapageldiklerine üzülme; nezaretimiz altında, sana bildirdiğimiz gibi gemiyi yap. Haksızlık yapanlar için Bana baş vurma, çünkü onlar suda boğulacaklardır" diye Allah tarafından vahyolundu.'),
  ('tr.diyanet', 11, 37, 'Nuh\'a, "Senin milletinden, inanmış olanlardan başkası inanmayacaktır; onların yapageldiklerine üzülme; nezaretimiz altında, sana bildirdiğimiz gibi gemiyi yap. Haksızlık yapanlar için Bana baş vurma, çünkü onlar suda boğulacaklardır" diye Allah tarafından vahyolundu.'),
  ('tr.diyanet', 11, 38, 'Gemiyi yaparken, milletinin inkarcı ileri gelenleri yanına uğradıkça onunla alay ederlerdi. O da: "Bizimle alay ediyorsunuz ama, alay ettiğiniz gibi biz de sizinle alay edeceğiz; rezil edecek olan azabın kime geleceğini ve kime sürekli azabın ineceğini göreceksiniz" dedi.'),
  ('tr.diyanet', 11, 39, 'Gemiyi yaparken, milletinin inkarcı ileri gelenleri yanına uğradıkça onunla alay ederlerdi. O da: "Bizimle alay ediyorsunuz ama, alay ettiğiniz gibi biz de sizinle alay edeceğiz; rezil edecek olan azabın kime geleceğini ve kime sürekli azabın ineceğini göreceksiniz" dedi.'),
  ('tr.diyanet', 11, 40, 'Buyruğumuz gelip tandırdan sular kaynamağa başlayınca, "Her cinsten birer çifti ve aleyhine hüküm verilmiş olanın dışında kalan çoluk çocuğunu ve inananları gemiye bindir" dedik. Pek az kimse onunla beraber inanmıştı.'),
  ('tr.diyanet', 11, 41, 'Allah "Oraya binin; yürümesi ve durması Allah\'ın ismiyledir, Rabbin bağışlar ve merhamet eder" dedi.'),
  ('tr.diyanet', 11, 42, 'Gemi, dağlar gibi dalgalar içinde onları götürürken, Nuh, bir kenarda ayrı kalmış olan oğluna "Ey oğulcuğum! Bizimle beraber gel, kafirlerle birlik olma" diye seslendi.'),
  ('tr.diyanet', 11, 43, 'Oğlu: "Dağa sığınırım, beni sudan kurtarır" deyince, Nuh: "Bugün Allah\'ın buyruğundan O\'nun acıdıkları dışında kurtulacak yoktur" dedi. Aralarına dalga girdi, oğlu da boğulanlara karıştı.'),
  ('tr.diyanet', 11, 44, 'Yere, "Suyunu çek!", göğe, "Ey gök sen de tut!" denildi. Su çekildi, iş de bitti; gemi Cudi\'ye oturdu. "Haksızlık yapan millet Allah\'ın rahmetinden uzak olsun" denildi.'),
  ('tr.diyanet', 11, 45, 'Nuh Rabbine seslendi: "Rabbim! Oğlum benim ailemdendi. Doğrusu Senin vadin haktır. Sen hükmedenlerin en iyi hükmedenisin" dedi.'),
  ('tr.diyanet', 11, 46, 'Allah: "Ey Nuh! O senin ailenden sayılmaz; çünkü kötü bir iş işlemiştir; öyleyse bilmediğin şeyi Benden isteme. İşte sana öğüt, bilgisizlerden olma" dedi.'),
  ('tr.diyanet', 11, 47, '"Rabbim! Bilmediğim şeyi Senden istemekten Sana sığınırım. Beni bağışlamaz ve bana merhamet etmezsen kaybedenlerden olurum" dedi.'),
  ('tr.diyanet', 11, 48, '"Ey Nuh! Sana ve seninle beraber olan topluluklara bizden bir selamet ve bereketle gemiden in. Ama birçok toplulukları da geçindireceğiz, sonra onlara can yakıcı bir azab vereceğiz" denildi.'),
  ('tr.diyanet', 11, 49, 'Bunlar sana vahyettiğimiz bilinmeyen olaylardır. Sen de, milletin de daha önce bunları bilmezdiniz. Sabret, sonuç, Allah\'tan sakınanlarındır.'),
  ('tr.diyanet', 11, 50, 'Ad milletine kardeşleri Hud\'u gönderdik. Şöyle dedi: "Ey milletim! Allah\'a kulluk edin. O\'ndan başka tanrınız yoktur; yoksa sadece yalan uyduran kimseler olursunuz."'),
  ('tr.diyanet', 11, 51, '"Ey milletim! Buna karşılık sizden bir ücret istemiyorum. Benim ücretim ancak beni yaratana aittir. Akletmez misiniz?"'),
  ('tr.diyanet', 11, 52, '"Ey milletim! Rabbinizden mağfiret dileyin, sonra O\'na tevbe edin ki size gökten bol bol yağmur göndersin, kuvvetinize kuvvet katsın; suçlular olarak yüz çevirmeyin."'),
  ('tr.diyanet', 11, 53, '"Ey Hud! Sen bize bir belge getirmeden, senin sözünden ötürü tanrılarımızı terketmeyiz ve sana inanmayız.'),
  ('tr.diyanet', 11, 54, 'Bir kısım tanrılarımız seni çarpmıştır, demekten başka birşey demeyiz" dediler. Hud: "Doğrusu ben Allah\'ı şahit tutuyorum; siz de şahit olun ki ben O\'nu bırakıp koştuğunuz ortaklardan uzağım. Hepiniz bana tuzak kurun sonra da ertelemeyin. Ben, ancak benim de sizin de Rabbiniz olan Allah\'a güvenirim. Hiçbir canlı yoktur ki Allah ona el koymamış bulunsun. Rabbim elbette doğru yoldadır. Eğer yüz çevirirseniz, şüphesiz ben size benimle gönderileni bildirdim. Rabbim sizden başka bir milleti yerinize getirebilir, O\'na bir şey de yapamazsınız. Doğrusu Rabbim herşeyi koruyandır" dedi.'),
  ('tr.diyanet', 11, 55, 'Bir kısım tanrılarımız seni çarpmıştır, demekten başka birşey demeyiz" dediler. Hud: "Doğrusu ben Allah\'ı şahit tutuyorum; siz de şahit olun ki ben O\'nu bırakıp koştuğunuz ortaklardan uzağım. Hepiniz bana tuzak kurun sonra da ertelemeyin. Ben, ancak benim de sizin de Rabbiniz olan Allah\'a güvenirim. Hiçbir canlı yoktur ki Allah ona el koymamış bulunsun. Rabbim elbette doğru yoldadır. Eğer yüz çevirirseniz, şüphesiz ben size benimle gönderileni bildirdim. Rabbim sizden başka bir milleti yerinize getirebilir, O\'na bir şey de yapamazsınız. Doğrusu Rabbim herşeyi koruyandır" dedi.'),
  ('tr.diyanet', 11, 56, 'Bir kısım tanrılarımız seni çarpmıştır, demekten başka birşey demeyiz" dediler. Hud: "Doğrusu ben Allah\'ı şahit tutuyorum; siz de şahit olun ki ben O\'nu bırakıp koştuğunuz ortaklardan uzağım. Hepiniz bana tuzak kurun sonra da ertelemeyin. Ben, ancak benim de sizin de Rabbiniz olan Allah\'a güvenirim. Hiçbir canlı yoktur ki Allah ona el koymamış bulunsun. Rabbim elbette doğru yoldadır. Eğer yüz çevirirseniz, şüphesiz ben size benimle gönderileni bildirdim. Rabbim sizden başka bir milleti yerinize getirebilir, O\'na bir şey de yapamazsınız. Doğrusu Rabbim herşeyi koruyandır" dedi.'),
  ('tr.diyanet', 11, 57, 'Bir kısım tanrılarımız seni çarpmıştır, demekten başka birşey demeyiz" dediler. Hud: "Doğrusu ben Allah\'ı şahit tutuyorum; siz de şahit olun ki ben O\'nu bırakıp koştuğunuz ortaklardan uzağım. Hepiniz bana tuzak kurun sonra da ertelemeyin. Ben, ancak benim de sizin de Rabbiniz olan Allah\'a güvenirim. Hiçbir canlı yoktur ki Allah ona el koymamış bulunsun. Rabbim elbette doğru yoldadır. Eğer yüz çevirirseniz, şüphesiz ben size benimle gönderileni bildirdim. Rabbim sizden başka bir milleti yerinize getirebilir, O\'na bir şey de yapamazsınız. Doğrusu Rabbim herşeyi koruyandır" dedi.'),
  ('tr.diyanet', 11, 58, 'Buyruğumuz gelince, Hud\'u ve beraberindeki inananları, rahmetimizle kurtardık. Onları çetin bir azabdan koruduk.'),
  ('tr.diyanet', 11, 59, 'İşte bu, Rablerinin ayetlerini bile bile inkar eden, peygamberlerine kafa tutan ve her inatçı zorbanın emrine uyan Ad milletidir.'),
  ('tr.diyanet', 11, 60, 'Bu dünyada da, kıyamet gününde de lanete uğradılar. Bilin ki Ad milleti Rablerini inkar etti ve yine bilin ki Hud\'un milleti Ad Allah\'ın rahmetinden uzaklaştı.'),
  ('tr.diyanet', 11, 61, 'Semud milletine kardeşleri Salih\'i gönderdik. "Ey milletim! Allah\'a kulluk edin; O\'ndan başka tanrınız yoktur; sizi yeryüzünde yaratıp orayı imar etmenizi dileyen O\'dur. Öyleyse O\'ndan mağfiret dileyin, sonra da O\'na tevbe edin. Doğrusu Rabbim size yakın ve duaları kabul edendir" dedi.'),
  ('tr.diyanet', 11, 62, '"Ey Salih! Sen bundan önce, aramızda kendisinden iyilik beklenir bir kimseydin; şimdi babalarımızın taptıklarına bizi tapmaktan men mi ediyorsun? Doğrusu bizi çağırdığın şeyden şüphe ve endişedeyiz" dediler.'),
  ('tr.diyanet', 11, 63, '"Ey milletim! Eğer Rabbimden bir belgem olur ve bana rahmet eder de ben O\'na baş kaldırırsam, söyleyin, Allah\'a karşı beni kim savunur? Bana zararımı artırmaktan başka birşey yapamazsınız" dedi.'),
  ('tr.diyanet', 11, 64, '"Ey milletim! Bu, size bir ayet olarak, Allah\'ın devesidir. Bırakın onu, Allah\'ın toprağında otlasın; ona fenalık etmeyin, yoksa siz hemen azaba uğrarsınız"'),
  ('tr.diyanet', 11, 65, 'Buna rağmen onu kesip devirdiler. O zaman Salih: "Yurdunuzda üç gün daha kalın. Bu, yalanlanmayacak bir sözdür" dedi.'),
  ('tr.diyanet', 11, 66, 'Buyruğumuz gelince, Salih\'i ve beraberindeki inananları katımızdan bir rahmet olarak o günün rezilliğinden kurtardık. Doğrusu Rabbin pek kuvvetli ve güçlüdür.'),
  ('tr.diyanet', 11, 67, 'Haksızlık yapanları bir çığlık tuttu, oldukları yerde diz üstü çöküverdiler.'),
  ('tr.diyanet', 11, 68, 'Sanki orada hiç yaşamamışlardı. Bilin ki, Semud milleti Rabbini inkar etmişti. Bilin ki, Semud milleti Allah\'ın rahmetinden uzaklaştı.'),
  ('tr.diyanet', 11, 69, 'And olsun ki, elçilerimiz müjde ile İbrahim\'e geldiler. "Selam sana" dediler, "Size de selam" dedi, hemen kızartılmış bir buzağı getirdi.'),
  ('tr.diyanet', 11, 70, 'Ellerini ona uzatmadıklarını görünce, durumlarını beğenmedi ve içine korku düştü. Onlar, "Korkma, biz Lut milletine gönderildik" dediler.'),
  ('tr.diyanet', 11, 71, 'Bu arada, İbrahim\'in ayakta duran karısı gülünce, "Ona İshak\'ı ardından Yakub\'u müjdeleriz" dediler.'),
  ('tr.diyanet', 11, 72, '"Vay başıma gelenler! Ben bir kocakarı, kocam da ihtiyar olmuşken nasıl doğurabilirim? Doğrusu bu şaşılacak bir şey" dedi.'),
  ('tr.diyanet', 11, 73, '"Ey evin hanımı! Allah\'ın rahmeti ve bereketleri üzerinize olmuşken, nasıl Allah\'ın işine şaşarsın? O, övülmeye layıktır, yücelerin yücesidir" dediler.'),
  ('tr.diyanet', 11, 74, 'İbrahim\'in korkusu gidip de müjde kendisine ulaşınca, Lut milleti hakkında elçilerimizle tartışmaya girişti.'),
  ('tr.diyanet', 11, 75, 'Doğrusu İbrahim çok içli, yumuşak huylu ve kendini Allah\'a vermiş bir kimse idi.'),
  ('tr.diyanet', 11, 76, 'Elçilerimiz, "Ey İbrahim! Bundan vazgeç, doğrusu Rabbinin emri gelmiştir. Onlara, şüphesiz, geri çevrilemeyecek bir azab gelmektedir" dediler.'),
  ('tr.diyanet', 11, 77, 'Elçilerimiz Lut\'a gelince, onun fenasına gitti; çok sıkıldı, "Bu çetin bir gündür" dedi.'),
  ('tr.diyanet', 11, 78, 'Milleti ona koşarak geldiler. Daha önce kötü işler işliyorlardı. "Ey milletim! İşte bunlar benim kızlarım, onlar sizin için daha temizdir. (size nikahlıyabilirim!) Allah\'tan sakının, konuklarımın önünde beni rezil etmeyin. İçinizde aklı başında kimse yok mudur?" dedi.'),
  ('tr.diyanet', 11, 79, '"And olsun ki, senin kızlarınla bir işimiz olmadığını biliyorsun; doğrusu, ne istediğimizin farkındasın" dediler.'),
  ('tr.diyanet', 11, 80, '"Keşke size yetecek bir kuvvetim olsa veya sağlam bir yere sığınsam" dedi.'),
  ('tr.diyanet', 11, 81, '"Ey Lut! Biz Rabbinin elçileriyiz, onlar sana ilişemiyecekler; geceleyin bir ara, ailenle beraber yola çık; karının dışında kimse geri kalmasın. Doğrusu onların başına gelen onun başına da gelecektir. Vadeleri gün doğana kadardır. Gün doğması yakın değil mi?" dediler.'),
  ('tr.diyanet', 11, 82, 'Buyruğumuz gelince oraların altını üstüne getirdik; üzerine Rabbinin katından, işaretli olarak yığın yığın sert taş yağdırdık. Bunlar zalimlerden hiçbir zaman uzak olmayacaktır.'),
  ('tr.diyanet', 11, 83, 'Buyruğumuz gelince oraların altını üstüne getirdik; üzerine Rabbinin katından, işaretli olarak yığın yığın sert taş yağdırdık. Bunlar zalimlerden hiçbir zaman uzak olmayacaktır.'),
  ('tr.diyanet', 11, 84, 'Medyen halkına kardeşleri Şuayb\'ı gönderdik. Şöyle dedi: "Ey milletim! Allah\'a kulluk edin; O\'ndan başka tanrınız yoktur. Ölçüyü tartıyı eksik tutmayın. Doğrusu ben sizi bolluk içinde görüyorum ve hakkınızda kuşatıcı bir günün azabından korkuyorum."'),
  ('tr.diyanet', 11, 85, '"Ey milletim! Ölçüyü ve tartıyı tamamı tamamına yapın; insanlara eşyalarını eksik vermeyin; yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın."'),
  ('tr.diyanet', 11, 86, '"İnanıyorsanız, Allah\'ın geri bıraktığı helal kar sizin için daha hayırlıdır. Ben size bekçi değilim."'),
  ('tr.diyanet', 11, 87, '"Ey Şuayb! Babalarımızın taptığını bırakmamızı emreden veya mallarımızı istediğimiz gibi kullanmamızı meneden senin namazın mıdır? Sen doğrusu aklı başında, yumuşak huylu birisin" dediler.'),
  ('tr.diyanet', 11, 88, '"Ey Milletim! Rabbimden benim bir belgem olduğu ve bana güzel bir rızık da verdiği halde, O\'na karşı gelebilir miyim? Söylesenize! Size yasak ettiğim şeylerde, aykırı hareket etmek istemem; gücümün yettiği kadar ıslah etmekten başka bir dileğim yoktur. Başarım ancak Allah\'tandır, O\'na güvendim; O\'na yöneliyorum" dedi.'),
  ('tr.diyanet', 11, 89, '"Ey Milletim! Bana karşı gelmeniz, Nuh milletine veya Hud milletine yahut da Salih milletine gelen felaketin bir benzerini, sakın başınıza getirmesin. Lut milleti sizden uzak değildir."'),
  ('tr.diyanet', 11, 90, '"Rabbinizden mağfiret dileyin; O\'na tevbe edin; doğrusu Rabbim merhamet eder ve çok sever."'),
  ('tr.diyanet', 11, 91, '"Ey Şuayb! Söylediklerinin çoğunu anlamıyor ve doğrusu seni aramızda güçsüz görüyoruz. Eğer taraftarların olmasaydı seni taşlardık. Esasen bizim gözümüzde pek itibarın da yoktur" dediler.'),
  ('tr.diyanet', 11, 92, '"Ey Milletim! Benim taraftarlarım size göre Allah\'tan daha mı değerlidir ki Allah\'a sırt çevirdiniz? Doğrusu Rabbim yaptıklarınızı bilgisiyle kuşatmıştır" dedi.'),
  ('tr.diyanet', 11, 93, '"Ey Milletim! Durumunuzun gerektirdiğini yapın, doğrusu ben de yapacağım. Kime rezil edici bir azabın geleceğini, kimin yalancı olduğunu bileceksiniz. Gözleyin, doğrusu ben de sizinle beraber gözlüyorum."'),
  ('tr.diyanet', 11, 94, 'Buyruğumuz gelince, Şuayb\'ı ve beraberindeki inananları katımızdan bir rahmet olarak kurtardık. Haksızlık yapanları bir çığlık yakaladı, oldukları yerde diz üstü çöküverdiler.'),
  ('tr.diyanet', 11, 95, 'Sanki orada hiç yaşamamışlardı. Bilin ki Semud milleti Allah\'ın rahmetinden uzaklaştığı gibi Medyen halkı da uzaklaştı.'),
  ('tr.diyanet', 11, 96, 'And olsun ki Musa\'yı Firavun ve erkanına mucizelerimizle, apaçık bir delil ile gönderdik. Firavun\'un buyruğuna uydular, oysa Firavun\'un buyurduğu sağduyuya uygun değildi.'),
  ('tr.diyanet', 11, 97, 'And olsun ki Musa\'yı Firavun ve erkanına mucizelerimizle, apaçık bir delil ile gönderdik. Firavun\'un buyruğuna uydular, oysa Firavun\'un buyurduğu sağduyuya uygun değildi.'),
  ('tr.diyanet', 11, 98, 'Firavun, kıyamet gününde milletine öncülük eder, onları cehenneme götürür. Gittikleri yer ne kötü yerdir!'),
  ('tr.diyanet', 11, 99, 'Hem burada ve hem kıyamet gününde lanete uğratılırlar. Bu ne kötü bir bağıştır!'),
  ('tr.diyanet', 11, 100, 'Bu sana anlattıklarımız, kasabaların başından geçenlerdir. Onların bir kısmı hala duruyor, bir kısmı ise silinip gitmiştir.'),
  ('tr.diyanet', 11, 101, 'Onlara Biz zulmetmedik, fakat onlar kendilerine yazık ettiler. Rabbinin buyruğu gelince, Allah\'ı bırakıp taptıkları tanrılar kendilerine bir fayda vermedi, kayıplarını artırmaktan başka bir şeye yaramadı.'),
  ('tr.diyanet', 11, 102, 'Allah, kasabaların zalim halkını yakalayınca, böyle yakalar; yakalaması da şiddetli ve elimdir.'),
  ('tr.diyanet', 11, 103, 'Ahiretin azabından korkanlara, bunda, hiç şüphesiz ibret vardır. Bu, insanların toplanacağı gündür; bu, görülecek bir gündür.'),
  ('tr.diyanet', 11, 104, 'Biz, o günü, ancak belli bir süreye kadar geciktiririz.'),
  ('tr.diyanet', 11, 105, 'O gün gelince, Allah\'ın izni olmaksızın hiç kimse konuşamaz: İçlerinde bedbaht olanlar da, mesut olanlar da vardır.'),
  ('tr.diyanet', 11, 106, 'Bedbaht olanlar cehennemdedirler. Onlar orada ah edip inlerler.'),
  ('tr.diyanet', 11, 107, 'Rabbinin dilemesi bir yana, gökler ve yer durdukça, orada temelli kalacaklardır. Rabbin, şüphesiz, her istediğini yapar.'),
  ('tr.diyanet', 11, 108, 'Mesud olanlar ise cennettedirler. Rabbinin dilemesi bir yana, sonsuz bir lütuf olarak, gökler ve yer durdukça, orada temelli kalacaklardır.'),
  ('tr.diyanet', 11, 109, 'Bu putperestlerin taptıklarının batıl olduğunda şüphen olmasın; daha önce babalarının tapmış oldukları gibi onlar da taparlar. Onlara paylarını şüphesiz eksiksiz olarak ödeyeceğiz.'),
  ('tr.diyanet', 11, 110, 'And olsun ki, Musa\'ya Kitap verdik; onda ayrılığa düştüler. Eğer Rabbinin verilmiş bir sözü olmasaydı, aralarında çoktan hükmedilmiş olurdu. Doğrusu onlar, Kitap\'ın Allah katından olduğunda şüphe ve endişe içindedirler.'),
  ('tr.diyanet', 11, 111, 'Rabbin, onların işlerinin karşılığını elbette tamamen verecektir. O, şüphesiz, onların yaptıklarını bilir.'),
  ('tr.diyanet', 11, 112, 'Sen, beraberindeki tevbe edenlerle birlikte emrolunduğun gibi dosdoğru ol. Aşırı gitmeyin, doğrusu Allah yaptıklarınızı görür.'),
  ('tr.diyanet', 11, 113, 'Haksızlık yapanlara yönelmeyin, yoksa ateş size de dokunur. Sizin Allah\'tan başka dostunuz yoktur; sonra, yardım da göremezsiniz.'),
  ('tr.diyanet', 11, 114, 'Gündüzün iki ucunda ve gecenin gündüze yakın zamanlarında namaz kıl. Doğrusu iyilikler kötülükleri giderir. Bu, öğüt kabul edenlere bir öğüttür.'),
  ('tr.diyanet', 11, 115, 'Sabret, Allah iyi davrananların ecrini elbette zayi etmez.'),
  ('tr.diyanet', 11, 116, 'Sizden önceki nesillerin ileri gelenleri, yeryüzünde bozgunculuğa engel olmalı değil miydiler? Onlardan kurtardıklarımız pek azdır. Kendilerine verilen nimete karşı haksızlık edenlere uyanlar ise suçlu oldular.'),
  ('tr.diyanet', 11, 117, 'Rabbin, kasabaların halkı ıslah olmuşken, haksız yere onları yok etmez.'),
  ('tr.diyanet', 11, 118, 'Eğer Rabbin dileseydi insanları tek bir ümmet kılardı. Fakat, Rabbinin merhamet ettikleri bir yana, hala ayrılıktadırlar, esasen onları bunun için yaratmıştır. Rabbinin "And olsun ki cehennemi hep insan ve cin ile dolduracağım" sözü yerine gelmiştir.'),
  ('tr.diyanet', 11, 119, 'Eğer Rabbin dileseydi insanları tek bir ümmet kılardı. Fakat, Rabbinin merhamet ettikleri bir yana, hala ayrılıktadırlar, esasen onları bunun için yaratmıştır. Rabbinin "And olsun ki cehennemi hep insan ve cin ile dolduracağım" sözü yerine gelmiştir.'),
  ('tr.diyanet', 11, 120, 'Peygamberlerin başlarından geçenlerden, sana anlattığımız her şey, senin gönlünü pekiştirmemizi sağlar; sana bu belgelerle gerçek; inananlara da öğüt ve hatırlatma gelmiştir.'),
  ('tr.diyanet', 11, 121, 'İnanmayanlara: "Durumunuzun gerektirdiğini yapın, doğrusu biz de yapıyoruz; bekleyin, biz de bekliyoruz" de.'),
  ('tr.diyanet', 11, 122, 'İnanmayanlara: "Durumunuzun gerektirdiğini yapın, doğrusu biz de yapıyoruz; bekleyin, biz de bekliyoruz" de.'),
  ('tr.diyanet', 11, 123, 'Göklerin ve yerin gaybı Allah\'a aittir. Bütün işler O\'na döndürülür. Öyleyse O\'na kulluk et, O\'na güven. Rabbin, yaptıklarınızdan habersiz değildir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 11, 1, 'Alif laam raa, (inilah) suatu kitab yang ayat-ayatnya disusun dengan rapi serta dijelaskan secara terperinci, yang diturunkan dari sisi (Allah) Yang Maha Bijaksana lagi Maha Tahu,'),
  ('id.indonesian', 11, 2, 'agar kamu tidak menyembah selain Allah. Sesungguhnya aku (Muhammad) adalah pemberi peringatan dan pembawa khabar gembira kepadamu daripada-Nya,'),
  ('id.indonesian', 11, 3, 'dan hendaklah kamu meminta ampun kepada Tuhanmu dan bertaubat kepada-Nya. (Jika kamu mengerjakan yang demikian), niscaya Dia akan memberi kenikmatan yang baik (terus menerus) kepadamu sampai kepada waktu yang telah ditentukan dan Dia akan memberikan kepada tiap-tiap orang yang mempunyai keutamaan (balasan) keutamaannya. Jika kamu berpaling, maka sesungguhnya aku takut kamu akan ditimpa siksa hari kiamat.'),
  ('id.indonesian', 11, 4, 'Kepada Allah-lah kembalimu, dan Dia Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 11, 5, 'Ingatlah, sesungguhnya (orang munafik itu) memalingkan dada mereka untuk menyembunyikan diri daripadanya (Muhammad). Ingatlah, di waktu mereka menyelimuti dirinya dengan kain, Allah mengetahui apa yang mereka sembunyikan dan apa yang mereka lahirkan, sesungguhnya Allah Maha Mengetahui segala isi hati.'),
  ('id.indonesian', 11, 6, 'Dan tidak ada suatu binatang melata pun di bumi melainkan Allah-lah yang memberi rezekinya, dan Dia mengetahui tempat berdiam binatang itu dan tempat penyimpanannya. Semuanya tertulis dalam Kitab yang nyata (Lauh mahfuzh).'),
  ('id.indonesian', 11, 7, 'Dan Dialah yang menciptakan langit dan bumi dalam enam masa, dan adalah singgasana-Nya (sebelum itu) di atas air, agar Dia menguji siapakah di antara kamu yang lebih baik amalnya, dan jika kamu berkata (kepada penduduk Mekah): "Sesungguhnya kamu akan dibangkitkan sesudah mati", niscaya orang-orang yang kafir itu akan berkata: "Ini tidak lain hanyalah sihir yang nyata".'),
  ('id.indonesian', 11, 8, 'Dan sesungguhnya jika Kami undurkan azab dari mereka sampai kepada suatu waktu yang ditentukan. niscaya mereka akan berkata: "Apakah yang menghalanginya?" lngatlah, diwaktu azab itu datang kepada mereka tidaklah dapat dipalingkan dari mereka dan mereka diliputi oleh azab yang dahulunya mereka selalu memperolok-olokkannya.'),
  ('id.indonesian', 11, 9, 'Dan jika Kami rasakan kepada manusia suatu rahmat (nikmat) dari Kami, kemudian rahmat itu Kami cabut daripadanya, pastilah dia menjadi putus asa lagi tidak berterima kasih.'),
  ('id.indonesian', 11, 10, 'Dan jika Kami rasakan kepadanya kebahagiaan sesudah bencana yang menimpanya, niscaya dia akan berkata: "Telah hilang bencana-bencana itu daripadaku"; sesungguhnya dia sangat gembira lagi bangga,'),
  ('id.indonesian', 11, 11, 'kecuali orang-orang yang sabar (terhadap bencana), dan mengerjakan amal-amal saleh; mereka itu beroleh ampunan dan pahala yang besar.'),
  ('id.indonesian', 11, 12, 'Maka boleh jadi kamu hendak meninggalkan sebahagian dari apa yang diwahyukan kepadamu dan sempit karenanya dadamu, karena khawatir bahwa mereka akan mengatakan: "Mengapa tidak diturunkan kepadanya perbendaharaan (kekayaan) atau datang bersama-sama dengan dia seorang malaikat?" Sesungguhnya kamu hanyalah seorang pemberi peringatan dan Allah Pemelihara segala sesuatu.'),
  ('id.indonesian', 11, 13, 'Bahkan mereka mengatakan: "Muhammad telah membuat-buat Al Quran itu", Katakanlah: "(Kalau demikian), maka datangkanlah sepuluh surat-surat yang dibuat-buat yang menyamainya, dan panggillah orang-orang yang kamu sanggup (memanggilnya) selain Allah, jika kamu memang orang-orang yang benar".'),
  ('id.indonesian', 11, 14, 'Jika mereka yang kamu seru itu tidak menerima seruanmu (ajakanmu) itu maka ketahuilah, sesungguhnya Al Quran itu diturunkan dengan ilmu Allah, dan bahwasanya tidak ada Tuhan selain Dia, maka maukah kamu berserah diri (kepada Allah)?'),
  ('id.indonesian', 11, 15, 'Barangsiapa yang menghendaki kehidupan dunia dan perhiasannya, niscaya Kami berikan kepada mereka balasan pekerjaan mereka di dunia dengan sempurna dan mereka di dunia itu tidak akan dirugikan.'),
  ('id.indonesian', 11, 16, 'Itulah orang-orang yang tidak memperoleh di akhirat, kecuali neraka dan lenyaplah di akhirat itu apa yang telah mereka usahakan di dunia dan sia-sialah apa yang telah mereka kerjakan.'),
  ('id.indonesian', 11, 17, 'Apakah (orang-orang kafir itu sama dengan) orang-orang yang ada mempunyai bukti yang nyata (Al Quran) dari Tuhannya, dan diikuti pula oleh seorang saksi (Muhammad) dari Allah dan sebelum Al Quran itu telah ada Kitab Musa yang menjadi pedoman dan rahmat? Mereka itu beriman kepada Al Quran. Dan barangsiapa di antara mereka (orang-orang Quraisy) dan sekutu-sekutunya yang kafir kepada Al Quran, maka nerakalah tempat yang diancamkan baginya, karena itu janganlah kamu ragu-ragu terhadap Al Quran itu. Sesungguhnya (Al Quran) itu benar-benar dari Tuhanmu, tetapi kebanyakan manusia tidak beriman.'),
  ('id.indonesian', 11, 18, 'Dan siapakah yang lebih zalim daripada orang yang membuat-buat dusta terhadap Allah? Mereka itu akan dihadapkan kepada Tuhan mereka, dan para saksi akan berkata: "Orang-orang inilah yang telah berdusta terhadap Tuhan mereka". Ingatlah, kutukan Allah (ditimpakan) atas orang-orang yang zalim,'),
  ('id.indonesian', 11, 19, '(yaitu) orang-orang yang menghalangi (manusia) dari jalan Allah dan menghendaki (supaya) jalan itu bengkok. Dan mereka itulah orang-orang yang tidak percaya akan adanya hari akhirat.'),
  ('id.indonesian', 11, 20, 'Orang-orang itu tidak mampu menghalang-halangi Allah untuk (mengazab mereka) di bumi ini, dan sekali-kali tidak adalah bagi mereka penolong selain Allah. Siksaan itu dilipat gandakan kepada mereka. Mereka selalu tidak dapat mendengar (kebenaran) dan mereka selalu tidak dapat melihat(nya).'),
  ('id.indonesian', 11, 21, 'Mereka itulah orang-orang yang merugikan dirinya sendiri, dan lenyaplah dari mereka apa yang selalu mereka ada-adakan.'),
  ('id.indonesian', 11, 22, 'Pasti mereka itu di akhirat menjadi orang-orang yang paling merugi.'),
  ('id.indonesian', 11, 23, 'Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh dan merendahkan diri kepada Tuhan mereka, mereka itu adalah penghuni-penghuni surga; mereka kekal di dalamnya.'),
  ('id.indonesian', 11, 24, 'Perbandingan kedua golongan itu (orang-orang kafir dan orang-orang mukmin), seperti orang buta dan tuli dengan orang yang dapat melihat dan dapat mendengar. Adakah kedua golongan itu sama keadaan dan sifatnya? Maka tidakkah kamu mengambil pelajaran (daripada perbandingan itu)?'),
  ('id.indonesian', 11, 25, 'Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, (dia berkata): "Sesungguhnya aku adalah pemberi peringatan yang nyata bagi kamu,'),
  ('id.indonesian', 11, 26, 'agar kamu tidak menyembah selain Allah. Sesungguhnya aku takut kamu akan ditimpa azab (pada) hari yang sangat menyedihkan".'),
  ('id.indonesian', 11, 27, 'Maka berkatalah pemimpin-pemimpin yang kafir dari kaumnya: "Kami tidak melihat kamu, melainkan (sebagai) seorang manusia (biasa) seperti kami, dan kami tidak melihat orang-orang yang mengikuti kamu, melainkan orang-orang yang hina dina di antara kami yang lekas percaya saja, dan kami tidak melihat kamu memiliki sesuatu kelebihan apapun atas kami, bahkan kami yakin bahwa kamu adalah orang-orang yang dusta".'),
  ('id.indonesian', 11, 28, 'Berkata Nuh: "Hai kaumku, bagaimana pikiranmu, jika aku ada mempunyai bukti yang nyata dari Tuhanku, dan diberinya aku rahmat dari sisi-Nya, tetapi rahmat itu disamarkan bagimu. Apa akan kami paksakankah kamu menerimanya, padahal kamu tiada menyukainya?"'),
  ('id.indonesian', 11, 29, 'Dan (dia berkata): "Hai kaumku, aku tiada meminta harta benda kepada kamu (sebagai upah) bagi seruanku. Upahku hanyalah dari Allah dan aku sekali-kali tidak akan mengusir orang-orang yang telah beriman. Sesungguhnya mereka akan bertemu dengan Tuhannya, akan tetapi aku memandangmu suatu kaum yang tidak mengetahui".'),
  ('id.indonesian', 11, 30, 'Dan (dia berkata): "Hai kaumku, siapakah yang akan menolongku dari (azab) Allah jika aku mengusir mereka. Maka tidakkah kamu mengambil pelajaran?'),
  ('id.indonesian', 11, 31, 'Dan aku tidak mengatakan kepada kamu (bahwa): "Aku mempunyai gudang-gudang rezeki dan kekayaan dari Allah, dan aku tiada mengetahui yang ghaib", dan tidak (pula) aku mengatakan: "Bahwa sesungguhnya aku adalah malaikat", dan tidak juga aku mengatakan kepada orang-orang yang dipandang hina oleh penglihatanmu: "Sekali-kali Allah tidak akan mendatangkan kebaikan kepada mereka". Allah lebih mengetahui apa yang ada pada diri mereka; sesungguhnya aku, kalau begitu benar-benar termasuk orang-orang yang zalim.'),
  ('id.indonesian', 11, 32, 'Mereka berkata "Hai Nuh, sesungguhnya kamu telah berbantah dengan kami, dan kamu telah memperpanjang bantahanmu terhadap kami, maka datangkanlah kepada kami azab yang kamu ancamkan kepada kami, jika kamu termasuk orang-orang yang benar".'),
  ('id.indonesian', 11, 33, 'Nuh menjawab: "Hanyalah Allah yang akan mendatangkan azab itu kepadamu jika Dia menghendaki, dan kamu sekali-kali tidak dapat melepaskan diri.'),
  ('id.indonesian', 11, 34, 'Dan tidaklah bermanfaat kepadamu nasehatku jika aku hendak memberi nasehat kepada kamu, sekiranya Allah hendak menyesatkan kamu, Dia adalah Tuhanmu, dan kepada-Nya-lah kamu dikembalikan".'),
  ('id.indonesian', 11, 35, 'Malahan kaum Nuh itu berkata: "Dia cuma membuat-buat nasihatnya saja". Katakanlah: "Jika aku membuat-buat nasihat itu, maka hanya akulah yang memikul dosaku, dan aku berlepas diri dari dosa yang kamu perbuat".'),
  ('id.indonesian', 11, 36, 'Dan diwahyukan kepada Nuh, bahwasanya sekali-kali tidak akan beriman di antara kaummu, kecuali orang yang telah beriman (saja), karena itu janganlah kamu bersedih hati tentang apa yang selalu mereka kerjakan.'),
  ('id.indonesian', 11, 37, 'Dan buatlah bahtera itu dengan pengawasan dan petunjuk wahyu Kami, dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang zalim itu; sesungguhnya mereka itu akan ditenggelamkan.'),
  ('id.indonesian', 11, 38, 'Dan mulailah Nuh membuat bahtera. Dan setiap kali pemimpin kaumnya berjalan meliwati Nuh, mereka mengejeknya. Berkatalah Nuh: "Jika kamu mengejek kami, maka sesungguhnya kami (pun) mengejekmu sebagaimana kamu sekalian mengejek (kami).'),
  ('id.indonesian', 11, 39, 'Kelak kamu akan mengetahui siapa yang akan ditimpa oleh azab yang menghinakannya dan yang akan ditimpa azab yang kekal".'),
  ('id.indonesian', 11, 40, 'Hingga apabila perintah Kami datang dan dapur telah memancarkan air, Kami berfirman: "Muatkanlah ke dalam bahtera itu dari masing-masing binatang sepasang (jantan dan betina), dan keluargamu kecuali orang yang telah terdahulu ketetapan terhadapnya dan (muatkan pula) orang-orang yang beriman". Dan tidak beriman bersama dengan Nuh itu kecuali sedikit.'),
  ('id.indonesian', 11, 41, 'Dan Nuh berkata: "Naiklah kamu sekalian ke dalamnya dengan menyebut nama Allah di waktu berlayar dan berlabuhnya". Sesungguhnya Tuhanku benar-benar Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 11, 42, 'Dan bahtera itu berlayar membawa mereka dalam gelombang laksana gunung. Dan Nuh memanggil anaknya, sedang anak itu berada di tempat yang jauh terpencil: "Hai anakku, naiklah (ke kapal) bersama kami dan janganlah kamu berada bersama orang-orang yang kafir".'),
  ('id.indonesian', 11, 43, 'Anaknya menjawab: "Aku akan mencari perlindungan ke gunung yang dapat memeliharaku dari air bah!" Nuh berkata: "Tidak ada yang melindungi hari ini dari azab Allah selain Allah (saja) Yang Maha Penyayang". Dan gelombang menjadi penghalang antara keduanya; maka jadilah anak itu termasuk orang-orang yang ditenggelamkan.'),
  ('id.indonesian', 11, 44, 'Dan difirmankan: "Hai bumi telanlah airmu, dan hai langit (hujan) berhentilah," dan airpun disurutkan, perintahpun diselesaikan dan bahtera itupun berlabuh di atas bukit Judi, dan dikatakan: "Binasalah orang-orang yang zalim".'),
  ('id.indonesian', 11, 45, 'Dan Nuh berseru kepada Tuhannya sambil berkata: "Ya Tuhanku, sesungguhnya anakku termasuk keluargaku, dan sesungguhnya janji Engkau itulah yang benar. Dan Engkau adalah Hakim yang seadil-adilnya".'),
  ('id.indonesian', 11, 46, 'Allah berfirman: "Hai Nuh, sesungguhnya dia bukanlah termasuk keluargamu (yang dijanjikan akan diselamatkan), sesungguhnya (perbuatan)nya perbuatan yang tidak baik. Sebab itu janganlah kamu memohon kepada-Ku sesuatu yang kamu tidak mengetahui (hakekat)nya. Sesungguhnya Aku memperingatkan kepadamu supaya kamu jangan termasuk orang-orang yang tidak berpengetahuan".'),
  ('id.indonesian', 11, 47, 'Nuh berkata: Ya Tuhanku, sesungguhnya aku berlindung kepada Engkau dari memohon kepada Engkau sesuatu yang aku tiada mengetahui (hakekat)nya. Dan sekiranya Engkau tidak memberi ampun kepadaku, dan (tidak) menaruh belas kasihan kepadaku, niscaya aku akan termasuk orang-orang yang merugi".'),
  ('id.indonesian', 11, 48, 'Difirmankan: "Hai Nuh, turunlah dengan selamat sejahtera dan penuh keberkatan dari Kami atasmu dan atas umat-umat (yang mukmin) dari orang-orang yang bersamamu. Dan ada (pula) umat-umat yang Kami beri kesenangan pada mereka (dalam kehidupan dunia), kemudian mereka akan ditimpa azab yang pedih dari Kami".'),
  ('id.indonesian', 11, 49, 'Itu adalah di antara berita-berita penting tentang yang ghaib yang Kami wahyukan kepadamu (Muhammad); tidak pernah kamu mengetahuinya dan tidak (pula) kaummu sebelum ini. Maka bersabarlah; sesungguhnya kesudahan yang baik adalah bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 11, 50, 'Dan kepada kaum \'Ad (Kami utus) saudara mereka, Huud. Ia berkata: "Hai kaumku, sembahlah Allah, sekali-kali tidak ada bagimu Tuhan selain Dia. Kamu hanyalah mengada-adakan saja.'),
  ('id.indonesian', 11, 51, 'Hai kaumku, aku tidak meminta upah kepadamu bagi seruanku ini. Upahku tidak lain hanyalah dari Allah yang telah menciptakanku. Maka tidakkah kamu memikirkan(nya)?"'),
  ('id.indonesian', 11, 52, 'Dan (dia berkata): "Hai kaumku, mohonlah ampun kepada Tuhanmu lalu bertobatlah kepada-Nya, niscaya Dia menurunkan hujan yang sangat deras atasmu, dan Dia akan menambahkan kekuatan kepada kekuatanmu, dan janganlah kamu berpaling dengan berbuat dosa".'),
  ('id.indonesian', 11, 53, 'Kaum \'Ad berkata: "Hai Huud, kamu tidak mendatangkan kepada kami suatu bukti yang nyata, dan kami sekali-kali tidak akan meninggalkan sembahan-sembahan kami karena perkataanmu, dan kami sekali-kali tidak akan mempercayai kamu.'),
  ('id.indonesian', 11, 54, 'Kami tidak mengatakan melainkan bahwa sebagian sembahan kami telah menimpakan penyakit gila atas dirimu". Huud menjawab: "Sesungguhnya aku bersaksi kepada Allah dan saksikanlah olehmu sekalian bahwa sesungguhnya aku berlepas diri dari apa yang kamu persekutukan,'),
  ('id.indonesian', 11, 55, 'dari selain-Nya, sebab itu jalankanlah tipu dayamu semuanya terhadapku dan janganlah kamu memberi tangguh kepadaku.'),
  ('id.indonesian', 11, 56, 'Sesungguhnya aku bertawakkal kepada Allah Tuhanku dan Tuhanmu. Tidak ada suatu binatang melatapun melainkan Dialah yang memegang ubun-ubunnya. Sesungguhnya Tuhanku di atas jalan yang lurus".'),
  ('id.indonesian', 11, 57, 'Jika kamu berpaling, maka sesungguhnya aku telah menyampaikan kepadamu apa (amanat) yang aku diutus (untuk menyampaikan)nya kepadamu. Dan Tuhanku akan mengganti (kamu) dengan kaum yang lain (dari) kamu; dan kamu tidak dapat membuat mudharat kepada-Nya sedikitpun. Sesungguhnya Tuhanku adalah Maha Pemelihara segala sesuatu.'),
  ('id.indonesian', 11, 58, 'Dan tatkala datang azab Kami, Kami selamatkan Huud dan orang-orang yang beriman bersama dia dengan rahmat dari Kami; dan Kami selamatkan (pula) mereka (di akhirat) dari azab yang berat.'),
  ('id.indonesian', 11, 59, 'Dan itulah (kisah) kaum \'Ad yang mengingkari tanda-tanda kekuasaan Tuhan mereka, dan mendurhakai rasul-rasul Allah dan mereka menuruti perintah semua penguasa yang sewenang-wenang lagi menentang (kebenaran).'),
  ('id.indonesian', 11, 60, 'Dan mereka selalu diikuti dengan kutukan di dunia ini dan (begitu pula) di hari kiamat. Ingatlah, sesungguhnya kaum \'Ad itu kafir kepada Tuhan mereka. Ingatlah kebinasaanlah bagi kaum \'Ad (yaitu) kaum Huud itu.'),
  ('id.indonesian', 11, 61, 'Dan kepada Tsamud (Kami utus) saudara mereka Shaleh. Shaleh berkata: "Hai kaumku, sembahlah Allah, sekali-kali tidak ada bagimu Tuhan selain Dia. Dia telah menciptakan kamu dari bumi (tanah) dan menjadikan kamu pemakmurnya, karena itu mohonlah ampunan-Nya, kemudian bertobatlah kepada-Nya, Sesungguhnya Tuhanku amat dekat (rahmat-Nya) lagi memperkenankan (doa hamba-Nya)".'),
  ('id.indonesian', 11, 62, 'Kaum Tsamud berkata: "Hai Shaleh, sesungguhnya kamu sebelum ini adalah seorang di antara kami yang kami harapkan, apakah kamu melarang kami untuk menyembah apa yang disembah oleh bapak-bapak kami? dan sesungguhnya kami betul-betul dalam keraguan yang menggelisahkan terhadap agama yang kamu serukan kepada kami".'),
  ('id.indonesian', 11, 63, 'Shaleh berkata: "Hai kaumku, bagaimana pikiranmu jika aku mempunyai bukti yang nyata dari Tuhanku dan diberi-Nya aku rahmat (kenabian) dari-Nya, maka siapakah yang akan menolong aku dari (azab) Allah jika aku mendurhakai-Nya. Sebab itu kamu tidak menambah apapun kepadaku selain daripada kerugian.'),
  ('id.indonesian', 11, 64, 'Hai kaumku, inilah unta betina dari Allah, sebagai mukjizat (yang menunjukkan kebenaran) untukmu, sebab itu biarkanlah dia makan di bumi Allah, dan janganlah kamu mengganggunya dengan gangguan apapun yang akan menyebabkan kamu ditimpa azab yang dekat".'),
  ('id.indonesian', 11, 65, 'Mereka membunuh unta itu, maka berkata Shaleh: "Bersukarialah kamu sekalian di rumahmu selama tiga hari, itu adalah janji yang tidak dapat didustakan".'),
  ('id.indonesian', 11, 66, 'Maka tatkala datang azab Kami, Kami selamatkan Shaleh beserta orang-orang yang beriman bersama dia dengan rahmat dari Kami dan dari kehinaan di hari itu. Sesungguhnya Tuhanmu Dia-Lah yang Maha Kuat lagi Maha Perkasa.'),
  ('id.indonesian', 11, 67, 'Dan satu suara keras yang mengguntur menimpa orang-orang yang zalim itu, lalu mereka mati bergelimpangan di rumahnya,'),
  ('id.indonesian', 11, 68, 'seolah-olah mereka belum pernah berdiam di tempat itu. Ingatlah, sesungguhnya kaum Tsamud mengingkari Tuhan mereka. Ingatlah, kebinasaanlah bagi kaum Tsamud.'),
  ('id.indonesian', 11, 69, 'Dan sesungguhnya utusan-utusan Kami (malaikat-malaikat) telah datang kepada lbrahim dengan membawa kabar gembira, mereka mengucapkan: "Selamat". Ibrahim menjawab: "Selamatlah," maka tidak lama kemudian Ibrahim menyuguhkan daging anak sapi yang dipanggang.'),
  ('id.indonesian', 11, 70, 'Maka tatkala dilihatnya tangan mereka tidak menjamahnya, Ibrahim memandang aneh perbuatan mereka, dan merasa takut kepada mereka. Malaikat itu berkata: "Jangan kamu takut, sesungguhnya kami adalah (malaikat-ma]aikat) yang diutus kepada kaum Luth".'),
  ('id.indonesian', 11, 71, 'Dan isterinya berdiri (dibalik tirai) lalu dia tersenyum, maka Kami sampaikan kepadanya berita gembira tentang (kelahiran) Ishak dan dari Ishak (akan lahir puteranya) Ya\'qub.'),
  ('id.indonesian', 11, 72, 'Isterinya berkata: "Sungguh mengherankan, apakah aku akan melahirkan anak padahal aku adalah seorang perempuan tua, dan ini suamikupun dalam keadaan yang sudah tua pula?. Sesungguhnya ini benar-benar suatu yang sangat aneh".'),
  ('id.indonesian', 11, 73, 'Para malaikat itu berkata: "Apakah kamu merasa heran tentang ketetapan Allah? (Itu adalah) rahmat Allah dan keberkatan-Nya, dicurahkan atas kamu, hai ahlulbait! Sesungguhnya Allah Maha Terpuji lagi Maha Pemurah".'),
  ('id.indonesian', 11, 74, 'Maka tatkala rasa takut hilang dari Ibrahim dan berita gembira telah datang kepadanya, diapun bersoal jawab dengan (malaikat-malaikat) Kami tentang kaum Luth.'),
  ('id.indonesian', 11, 75, 'Sesungguhnya Ibrahim itu benar-benar seorang yang penyantun lagi penghiba dan suka kembali kepada Allah.'),
  ('id.indonesian', 11, 76, 'Hai Ibrahim, tinggalkanlah soal jawab ini, sesungguhnya telah datang ketetapan Tuhanmu, dan sesungguhnya mereka itu akan didatangi azab yang tidak dapat ditolak.'),
  ('id.indonesian', 11, 77, 'Dan tatkala datang utusan-utusan Kami (para malaikat) itu kepada Luth, dia merasa susah dan merasa sempit dadanya karena kedatangan mereka, dan dia berkata: "Ini adalah hari yang amat sulit".'),
  ('id.indonesian', 11, 78, 'Dan datanglah kepadanya kaumnya dengan bergegas-gegas. Dan sejak dahulu mereka selalu melakukan perbuatan-perbuatan yang keji. Luth berkata: "Hai kaumku, inilah puteri-puteriku, mereka lebih suci bagimu, maka bertakwalah kepada Allah dan janganlah kamu mencemarkan (nama)ku terhadap tamuku ini. Tidak adakah di antaramu seorang yang berakal?"'),
  ('id.indonesian', 11, 79, 'Mereka menjawab: "Sesungguhnya kamu telah tahu bahwa kami tidak mempunyai keinginan terhadap puteri-puterimu; dan sesungguhnya kamu tentu mengetahui apa yang sebenarnya kami kehendaki".'),
  ('id.indonesian', 11, 80, 'Luth berkata: "Seandainya aku ada mempunyai kekuatan (untuk menolakmu) atau kalau aku dapat berlindung kepada keluarga yang kuat (tentu aku lakukan)".'),
  ('id.indonesian', 11, 81, 'Para utusan (malaikat) berkata: "Hai Luth, sesungguhnya kami adalah utusan-utusan Tuhanmu, sekali-kali mereka tidak akan dapat mengganggu kamu, sebab itu pergilah dengan membawa keluarga dan pengikut-pengikut kamu di akhir malam dan janganlah ada seorangpun di antara kamu yang tertinggal, kecuali isterimu. Sesungguhnya dia akan ditimpa azab yang menimpa mereka karena sesungguhnya saat jatuhnya azab kepada mereka ialah di waktu subuh; bukankah subuh itu sudah dekat?".'),
  ('id.indonesian', 11, 82, 'Maka tatkala datang azab Kami, Kami jadikan negeri kaum Luth itu yang di atas ke bawah (Kami balikkan), dan Kami hujani mereka dengan batu dari tanah yang terbakar dengan bertubi-tubi,'),
  ('id.indonesian', 11, 83, 'Yang diberi tanda oleh Tuhanmu, dan siksaan itu tiadalah jauh dari orang-orang yang zalim.'),
  ('id.indonesian', 11, 84, 'Dan kepada (penduduk) Mad-yan (Kami utus) saudara mereka, Syu\'aib. Ia berkata: "Hai kaumku, sembahlah Allah, sekali-kali tiada Tuhan bagimu selain Dia. Dan janganlah kamu kurangi takaran dan timbangan, sesungguhnya aku melihat kamu dalam keadaan yang baik (mampu) dan sesungguhnya aku khawatir terhadapmu akan azab hari yang membinasakan (kiamat)".'),
  ('id.indonesian', 11, 85, 'Dan Syu\'aib berkata: "Hai kaumku, cukupkanlah takaran dan timbangan dengan adil, dan janganlah kamu merugikan manusia terhadap hak-hak mereka dan janganlah kamu membuat kejahatan di muka bumi dengan membuat kerusakan.'),
  ('id.indonesian', 11, 86, 'Sisa (keuntungan) dari Allah adalah lebih baik bagimu jika kamu orang-orang yang beriman. Dan aku bukanlah seorang penjaga atas dirimu"'),
  ('id.indonesian', 11, 87, 'Mereka berkata: "Hai Syu\'aib, apakah sembahyangmu menyuruh kamu agar kami meninggalkan apa yang disembah oleh bapak-bapak kami atau melarang kami memperbuat apa yang kami kehendaki tentang harta kami. Sesungguhnya kamu adalah orang yang sangat penyantun lagi berakal".'),
  ('id.indonesian', 11, 88, 'Syu\'aib berkata: "Hai kaumku, bagaimana pikiranmu jika aku mempunyai bukti yang nyata dari Tuhanku dan dianugerahi-Nya aku dari pada-Nya rezeki yang baik (patutkah aku menyalahi perintah-Nya)? Dan aku tidak berkehendak menyalahi kamu (dengan mengerjakan) apa yang aku larang. Aku tidak bermaksud kecuali (mendatangkan) perbaikan selama aku masih berkesanggupan. Dan tidak ada taufik bagiku melainkan dengan (pertolongan) Allah. Hanya kepada Allah aku bertawakkal dan hanya kepada-Nya-lah aku kembali.'),
  ('id.indonesian', 11, 89, 'Hai kaumku, janganlah hendaknya pertentangan antara aku (dengan kamu) menyebabkan kamu menjadi jahat hingga kamu ditimpa azab seperti yang menimpa kaum Nuh atau kaum Hud atau kaum Shaleh, sedang kaum Luth tidak (pula) jauh (tempatnya) dari kamu.'),
  ('id.indonesian', 11, 90, 'Dan mohonlah ampun kepada Tuhanmu kemudian bertaubatlah kepada-Nya. Sesungguhnya Tuhanku Maha Penyayang lagi Maha Pengasih.'),
  ('id.indonesian', 11, 91, 'Mereka berkata: "Hai Syu\'aib, kami tidak banyak mengerti tentang apa yang kamu katakan itu dan sesungguhnya kami benar-benar melihat kamu seorang yang lemah di antara kami; kalau tidaklah karena keluargamu tentulah kami telah merajam kamu, sedang kamupun bukanlah seorang yang berwibawa di sisi kami".'),
  ('id.indonesian', 11, 92, 'Syu\'aib menjawab: "Hai kaumku, apakah keluargaku lebih terhormat menurut pandanganmu daripada Allah, sedang Allah kamu jadikan sesuatu yang terbuang di belakangmu?. Sesungguhnya (pengetahuan) Tuhanku meliputi apa yang kamu kerjakan".'),
  ('id.indonesian', 11, 93, 'Dan (dia berkata): "Hai kaumku, berbuatlah menurut kemampuanmu, sesungguhnya akupun berbuat (pula). Kelak kamu akan mengetahui siapa yang akan ditimpa azab yang menghinakannya dan siapa yang berdusta. Dan tunggulah azab (Tuhan), sesungguhnya akupun menunggu bersama kamu".'),
  ('id.indonesian', 11, 94, 'Dan tatkala datang azab Kami, Kami selamatkan Syu\'aib dan orang-orang yang beriman bersama-sama dengan dia dengan rahmat dari Kami, dan orang-orang yang zalim dibinasakan oleh satu suara yang mengguntur, lalu jadilah mereka mati bergelimpangan di rumahnya.'),
  ('id.indonesian', 11, 95, 'Seolah-olah mereka belum pernah berdiam di tempat itu. Ingatlah, kebinasaanlah bagi penduduk Mad-yan sebagaimana kaum Tsamud telah binasa.'),
  ('id.indonesian', 11, 96, 'Dan sesungguhnya Kami telah mengutus Musa dengan tanda-tanda (kekuasaan) Kami dan mukjizat yang nyata,'),
  ('id.indonesian', 11, 97, 'kepada Fir\'aun dan pemimpin-pemimpin kaumnya, tetapi mereka mengikut perintah Fir\'aun, padahal perintah Fir\'aun sekali-kali bukanlah (perintah) yang benar.'),
  ('id.indonesian', 11, 98, 'Ia berjalan di muka kaumnya di hari kiamat lalu memasukkan mereka ke dalam neraka. Neraka itu seburuk-buruk tempat yang didatangi.'),
  ('id.indonesian', 11, 99, 'Dan mereka selalu diikuti dengan kutukan di dunia ini dan (begitu pula) di hari kiamat. La\'nat itu seburuk-buruk pemberian yang diberikan.'),
  ('id.indonesian', 11, 100, 'Itu adalah sebahagian dan berita-berita negeri (yang telah dibinasakan) yang Kami ceritakan kepadamu (Muhammad); di antara negeri-negeri itu ada yang masih kedapatan bekas-bekasnya dan ada (pula) yang telah musnah.'),
  ('id.indonesian', 11, 101, 'Dan Kami tidaklah menganiaya mereka tetapi merekalah yang menganiaya diri mereka sendiri, karena itu tiadalah bermanfaat sedikitpun kepada mereka sembahan-sembahan yang mereka seru selain Allah, di waktu azab Tuhanmu datang. Dan sembahan-sembahan itu tidaklah menambah kepada mereka kecuali kebinasaan belaka.'),
  ('id.indonesian', 11, 102, 'Dan begitulah azab Tuhanmu, apabila Dia mengazab penduduk negeri-negeri yang berbuat zalim. Sesungguhnya azab-Nya itu adalah sangat pedih lagi keras.'),
  ('id.indonesian', 11, 103, 'Sesungguhnya pada yang demikian itu benar-benar terdapat pelajaran bagi orang-orang yang takut kepada azab akhirat. Hari kiamat itu adalah suatu hari yang semua manusia dikumpulkan untuk (menghadapi)nya, dan hari itu adalah suatu hari yang disaksikan (oleh segala makhluk).'),
  ('id.indonesian', 11, 104, 'Dan Kami tiadalah mengundurkannya, melainkan sampai waktu yang tertentu.'),
  ('id.indonesian', 11, 105, 'Di kala datang hari itu, tidak ada seorangun yang berbicara, melainkan dengan izin-Nya; maka di antara mereka ada yang celaka dan ada yang berbahagia.'),
  ('id.indonesian', 11, 106, 'Adapun orang-orang yang celaka, maka (tempatnya) di dalam neraka, di dalamnya mereka mengeluarkan dan menarik nafas (dengan merintih),'),
  ('id.indonesian', 11, 107, 'mereka kekal di dalamnya selama ada langit dan bumi, kecuali jika Tuhanmu menghendaki (yang lain). Sesungguhnya Tuhanmu Maha Pelaksana terhadap apa yang Dia kehendaki.'),
  ('id.indonesian', 11, 108, 'Adapun orang-orang yang berbahagia, maka tempatnya di dalam surga, mereka kekal di dalamnya selama ada langit dan bumi, kecuali jika Tuhanmu menghendaki (yang lain); sebagai karunia yang tiada putus-putusnya.'),
  ('id.indonesian', 11, 109, 'Maka janganlah kamu berada dalam keragu-raguan tentang apa yang disembah oleh mereka. Mereka tidak menyembah melainkan sebagaimana nenek moyang mereka menyembah dahulu. Dan sesungguhnya Kami pasti akan menyempurnakan dengan secukup-cukupnya pembalasan (terhadap) mereka dengan tidak dikurangi sedikitpun.'),
  ('id.indonesian', 11, 110, 'Dan sesungguhnya Kami telah memberikan Kitab (Taurat) kepada Musa, lalu diperselisihkan tentang Kitab itu. Dan seandainya tidak ada ketetapan yang telah terdahulu dari Tuhanmu, niscaya telah ditetapkan hukuman di antara mereka. Dan sesungguhnya mereka (orang-orang kafir Mekah) dalam keraguan yang menggelisahkan terhadap Al Quran.'),
  ('id.indonesian', 11, 111, 'Dan sesungguhnya kepada masing-masing (mereka yang berselisih itu) pasti Tuhanmu akan menyempurnakan dengan cukup, (balasan) pekerjaan mereka. Sesungguhnya Dia Maha Mengetahui apa yang mereka kerjakan.'),
  ('id.indonesian', 11, 112, 'Maka tetaplah kamu pada jalan yang benar, sebagaimana diperintahkan kepadamu dan (juga) orang yang telah taubat beserta kamu dan janganlah kamu melampaui batas. Sesungguhnya Dia Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 11, 113, 'Dan janganlah kamu cenderung kepada orang-orang yang zalim yang menyebabkan kamu disentuh api neraka, dan sekali-kali kamu tiada mempunyai seorang penolongpun selain daripada Allah, kemudian kamu tidak akan diberi pertolongan.'),
  ('id.indonesian', 11, 114, 'Dan dirikanlah sembahyang itu pada kedua tepi siang (pagi dan petang) dan pada bahagian permulaan daripada malam. Sesungguhnya perbuatan-perbuatan yang baik itu menghapuskan (dosa) perbuatan-perbuatan yang buruk. Itulah peringatan bagi orang-orang yang ingat.'),
  ('id.indonesian', 11, 115, 'Dan bersabarlah, karena sesungguhnya Allah tiada menyia-nyiakan pahala orang-orang yang berbuat kebaikan.'),
  ('id.indonesian', 11, 116, 'Maka mengapa tidak ada dari umat-umat yang sebelum kamu orang-orang yang mempunyai keutamaan yang melarang daripada (mengerjakan) kerusakan di muka bumi, kecuali sebahagian kecil di antara orang-orang yang telah Kami selamatkan di antara mereka, dan orang-orang yang zalim hanya mementingkan kenikmatan yang mewah yang ada pada mereka, dan mereka adalah orang-orang yang berdosa.'),
  ('id.indonesian', 11, 117, 'Dan Tuhanmu sekali-kali tidak akan membinasakan negeri-negeri secara zalim, sedang penduduknya orang-orang yang berbuat kebaikan.'),
  ('id.indonesian', 11, 118, 'Jikalau Tuhanmu menghendaki, tentu Dia menjadikan manusia umat yang satu, tetapi mereka senantiasa berselisih pendapat,'),
  ('id.indonesian', 11, 119, 'kecuali orang-orang yang diberi rahmat oleh Tuhanmu. Dan untuk itulah Allah menciptakan mereka. Kalimat Tuhanmu (keputusan-Nya) telah ditetapkan: sesungguhnya Aku akan memenuhi neraka Jahannam dengan jin dan manusia (yang durhaka) semuanya.'),
  ('id.indonesian', 11, 120, 'Dan semua kisah dari rasul-rasul Kami ceritakan kepadamu, ialah kisah-kisah yang dengannya Kami teguhkan hatimu; dan dalam surat ini telah datang kepadamu kebenaran serta pengajaran dan peringatan bagi orang-orang yang beriman.'),
  ('id.indonesian', 11, 121, 'Dan katakanlah kepada orang-orang yang tidak beriman: "Berbuatlah menurut kemampuanmu; sesungguhnya Kami-pun berbuat (pula)".'),
  ('id.indonesian', 11, 122, 'Dan tunggulah (akibat perbuatanmu); sesungguhnya kamipun menunggu (pula)".'),
  ('id.indonesian', 11, 123, 'Dan kepunyaan Allah-lah apa yang ghaib di langit dan di bumi dan kepada-Nya-lah dikembalikan urusan-urusan semuanya, maka sembahlah Dia, dan bertawakkallah kepada-Nya. Dan sekali-kali Tuhanmu tidak lalai dari apa yang kamu kerjakan.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (10, 37, 1401, 'وَمَا كَانَ هَٰذَا ٱلْقُرْءَانُ أَن يُفْتَرَىٰ مِن دُونِ ٱللَّهِ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ ٱلْكِتَٰبِ لَا رَيْبَ فِيهِ مِن رَّبِّ ٱلْعَٰلَمِينَ', 213, 11, 85, 0),
  (10, 38, 1402, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِسُورَةٍۢ مِّثْلِهِۦ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 213, 11, 85, 0),
  (10, 39, 1403, 'بَلْ كَذَّبُوا۟ بِمَا لَمْ يُحِيطُوا۟ بِعِلْمِهِۦ وَلَمَّا يَأْتِهِمْ تَأْوِيلُهُۥ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ', 213, 11, 85, 0),
  (10, 40, 1404, 'وَمِنْهُم مَّن يُؤْمِنُ بِهِۦ وَمِنْهُم مَّن لَّا يُؤْمِنُ بِهِۦ ۚ وَرَبُّكَ أَعْلَمُ بِٱلْمُفْسِدِينَ', 213, 11, 85, 0),
  (10, 41, 1405, 'وَإِن كَذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمْ عَمَلُكُمْ ۖ أَنتُم بَرِيٓـُٔونَ مِمَّآ أَعْمَلُ وَأَنَا۠ بَرِىٓءٌۭ مِّمَّا تَعْمَلُونَ', 213, 11, 85, 0),
  (10, 42, 1406, 'وَمِنْهُم مَّن يَسْتَمِعُونَ إِلَيْكَ ۚ أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ وَلَوْ كَانُوا۟ لَا يَعْقِلُونَ', 213, 11, 85, 0),
  (10, 43, 1407, 'وَمِنْهُم مَّن يَنظُرُ إِلَيْكَ ۚ أَفَأَنتَ تَهْدِى ٱلْعُمْىَ وَلَوْ كَانُوا۟ لَا يُبْصِرُونَ', 214, 11, 85, 0),
  (10, 44, 1408, 'إِنَّ ٱللَّهَ لَا يَظْلِمُ ٱلنَّاسَ شَيْـًۭٔا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمْ يَظْلِمُونَ', 214, 11, 85, 0),
  (10, 45, 1409, 'وَيَوْمَ يَحْشُرُهُمْ كَأَن لَّمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةًۭ مِّنَ ٱلنَّهَارِ يَتَعَارَفُونَ بَيْنَهُمْ ۚ قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ وَمَا كَانُوا۟ مُهْتَدِينَ', 214, 11, 85, 0),
  (10, 46, 1410, 'وَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا مَرْجِعُهُمْ ثُمَّ ٱللَّهُ شَهِيدٌ عَلَىٰ مَا يَفْعَلُونَ', 214, 11, 85, 0),
  (10, 47, 1411, 'وَلِكُلِّ أُمَّةٍۢ رَّسُولٌۭ ۖ فَإِذَا جَآءَ رَسُولُهُمْ قُضِىَ بَيْنَهُم بِٱلْقِسْطِ وَهُمْ لَا يُظْلَمُونَ', 214, 11, 85, 0),
  (10, 48, 1412, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 214, 11, 85, 0),
  (10, 49, 1413, 'قُل لَّآ أَمْلِكُ لِنَفْسِى ضَرًّۭا وَلَا نَفْعًا إِلَّا مَا شَآءَ ٱللَّهُ ۗ لِكُلِّ أُمَّةٍ أَجَلٌ ۚ إِذَا جَآءَ أَجَلُهُمْ فَلَا يَسْتَـْٔخِرُونَ سَاعَةًۭ ۖ وَلَا يَسْتَقْدِمُونَ', 214, 11, 85, 0),
  (10, 50, 1414, 'قُلْ أَرَءَيْتُمْ إِنْ أَتَىٰكُمْ عَذَابُهُۥ بَيَٰتًا أَوْ نَهَارًۭا مَّاذَا يَسْتَعْجِلُ مِنْهُ ٱلْمُجْرِمُونَ', 214, 11, 85, 0),
  (10, 51, 1415, 'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦٓ ۚ ءَآلْـَٰٔنَ وَقَدْ كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 214, 11, 85, 0),
  (10, 52, 1416, 'ثُمَّ قِيلَ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلْخُلْدِ هَلْ تُجْزَوْنَ إِلَّا بِمَا كُنتُمْ تَكْسِبُونَ', 214, 11, 85, 0),
  (10, 53, 1417, '۞ وَيَسْتَنۢبِـُٔونَكَ أَحَقٌّ هُوَ ۖ قُلْ إِى وَرَبِّىٓ إِنَّهُۥ لَحَقٌّۭ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ', 214, 11, 86, 0),
  (10, 54, 1418, 'وَلَوْ أَنَّ لِكُلِّ نَفْسٍۢ ظَلَمَتْ مَا فِى ٱلْأَرْضِ لَٱفْتَدَتْ بِهِۦ ۗ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ ۖ وَقُضِىَ بَيْنَهُم بِٱلْقِسْطِ ۚ وَهُمْ لَا يُظْلَمُونَ', 215, 11, 86, 0),
  (10, 55, 1419, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ أَلَآ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 215, 11, 86, 0),
  (10, 56, 1420, 'هُوَ يُحْىِۦ وَيُمِيتُ وَإِلَيْهِ تُرْجَعُونَ', 215, 11, 86, 0),
  (10, 57, 1421, 'يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَتْكُم مَّوْعِظَةٌۭ مِّن رَّبِّكُمْ وَشِفَآءٌۭ لِّمَا فِى ٱلصُّدُورِ وَهُدًۭى وَرَحْمَةٌۭ لِّلْمُؤْمِنِينَ', 215, 11, 86, 0),
  (10, 58, 1422, 'قُلْ بِفَضْلِ ٱللَّهِ وَبِرَحْمَتِهِۦ فَبِذَٰلِكَ فَلْيَفْرَحُوا۟ هُوَ خَيْرٌۭ مِّمَّا يَجْمَعُونَ', 215, 11, 86, 0),
  (10, 59, 1423, 'قُلْ أَرَءَيْتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزْقٍۢ فَجَعَلْتُم مِّنْهُ حَرَامًۭا وَحَلَٰلًۭا قُلْ ءَآللَّهُ أَذِنَ لَكُمْ ۖ أَمْ عَلَى ٱللَّهِ تَفْتَرُونَ', 215, 11, 86, 0),
  (10, 60, 1424, 'وَمَا ظَنُّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ يَوْمَ ٱلْقِيَٰمَةِ ۗ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ', 215, 11, 86, 0),
  (10, 61, 1425, 'وَمَا تَكُونُ فِى شَأْنٍۢ وَمَا تَتْلُوا۟ مِنْهُ مِن قُرْءَانٍۢ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ ۚ وَمَا يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍۢ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ وَلَآ أَصْغَرَ مِن ذَٰلِكَ وَلَآ أَكْبَرَ إِلَّا فِى كِتَٰبٍۢ مُّبِينٍ', 215, 11, 86, 0),
  (10, 62, 1426, 'أَلَآ إِنَّ أَوْلِيَآءَ ٱللَّهِ لَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 216, 11, 86, 0),
  (10, 63, 1427, 'ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 216, 11, 86, 0),
  (10, 64, 1428, 'لَهُمُ ٱلْبُشْرَىٰ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ ۚ لَا تَبْدِيلَ لِكَلِمَٰتِ ٱللَّهِ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 216, 11, 86, 0),
  (10, 65, 1429, 'وَلَا يَحْزُنكَ قَوْلُهُمْ ۘ إِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا ۚ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 216, 11, 86, 0),
  (10, 66, 1430, 'أَلَآ إِنَّ لِلَّهِ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ ۗ وَمَا يَتَّبِعُ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ شُرَكَآءَ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ', 216, 11, 86, 0),
  (10, 67, 1431, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَسْمَعُونَ', 216, 11, 86, 0),
  (10, 68, 1432, 'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًۭا ۗ سُبْحَٰنَهُۥ ۖ هُوَ ٱلْغَنِىُّ ۖ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ إِنْ عِندَكُم مِّن سُلْطَٰنٍۭ بِهَٰذَآ ۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ', 216, 11, 86, 0),
  (10, 69, 1433, 'قُلْ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 216, 11, 86, 0),
  (10, 70, 1434, 'مَتَٰعٌۭ فِى ٱلدُّنْيَا ثُمَّ إِلَيْنَا مَرْجِعُهُمْ ثُمَّ نُذِيقُهُمُ ٱلْعَذَابَ ٱلشَّدِيدَ بِمَا كَانُوا۟ يَكْفُرُونَ', 216, 11, 86, 0),
  (10, 71, 1435, '۞ وَٱتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِى وَتَذْكِيرِى بِـَٔايَٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلْتُ فَأَجْمِعُوٓا۟ أَمْرَكُمْ وَشُرَكَآءَكُمْ ثُمَّ لَا يَكُنْ أَمْرُكُمْ عَلَيْكُمْ غُمَّةًۭ ثُمَّ ٱقْضُوٓا۟ إِلَىَّ وَلَا تُنظِرُونِ', 217, 11, 87, 0),
  (10, 72, 1436, 'فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ', 217, 11, 87, 0),
  (10, 73, 1437, 'فَكَذَّبُوهُ فَنَجَّيْنَٰهُ وَمَن مَّعَهُۥ فِى ٱلْفُلْكِ وَجَعَلْنَٰهُمْ خَلَٰٓئِفَ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 217, 11, 87, 0),
  (10, 74, 1438, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِۦ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَآءُوهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبْلُ ۚ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ ٱلْمُعْتَدِينَ', 217, 11, 87, 0),
  (10, 75, 1439, 'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ وَهَٰرُونَ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ بِـَٔايَٰتِنَا فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًۭا مُّجْرِمِينَ', 217, 11, 87, 0),
  (10, 76, 1440, 'فَلَمَّا جَآءَهُمُ ٱلْحَقُّ مِنْ عِندِنَا قَالُوٓا۟ إِنَّ هَٰذَا لَسِحْرٌۭ مُّبِينٌۭ', 217, 11, 87, 0),
  (10, 77, 1441, 'قَالَ مُوسَىٰٓ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَآءَكُمْ ۖ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ ٱلسَّٰحِرُونَ', 217, 11, 87, 0),
  (10, 78, 1442, 'قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ', 217, 11, 87, 0),
  (10, 79, 1443, 'وَقَالَ فِرْعَوْنُ ٱئْتُونِى بِكُلِّ سَٰحِرٍ عَلِيمٍۢ', 218, 11, 87, 0),
  (10, 80, 1444, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 218, 11, 87, 0),
  (10, 81, 1445, 'فَلَمَّآ أَلْقَوْا۟ قَالَ مُوسَىٰ مَا جِئْتُم بِهِ ٱلسِّحْرُ ۖ إِنَّ ٱللَّهَ سَيُبْطِلُهُۥٓ ۖ إِنَّ ٱللَّهَ لَا يُصْلِحُ عَمَلَ ٱلْمُفْسِدِينَ', 218, 11, 87, 0),
  (10, 82, 1446, 'وَيُحِقُّ ٱللَّهُ ٱلْحَقَّ بِكَلِمَٰتِهِۦ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ', 218, 11, 87, 0),
  (10, 83, 1447, 'فَمَآ ءَامَنَ لِمُوسَىٰٓ إِلَّا ذُرِّيَّةٌۭ مِّن قَوْمِهِۦ عَلَىٰ خَوْفٍۢ مِّن فِرْعَوْنَ وَمَلَإِي۟هِمْ أَن يَفْتِنَهُمْ ۚ وَإِنَّ فِرْعَوْنَ لَعَالٍۢ فِى ٱلْأَرْضِ وَإِنَّهُۥ لَمِنَ ٱلْمُسْرِفِينَ', 218, 11, 87, 0),
  (10, 84, 1448, 'وَقَالَ مُوسَىٰ يَٰقَوْمِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ فَعَلَيْهِ تَوَكَّلُوٓا۟ إِن كُنتُم مُّسْلِمِينَ', 218, 11, 87, 0),
  (10, 85, 1449, 'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةًۭ لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 218, 11, 87, 0),
  (10, 86, 1450, 'وَنَجِّنَا بِرَحْمَتِكَ مِنَ ٱلْقَوْمِ ٱلْكَٰفِرِينَ', 218, 11, 87, 0),
  (10, 87, 1451, 'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰ وَأَخِيهِ أَن تَبَوَّءَا لِقَوْمِكُمَا بِمِصْرَ بُيُوتًۭا وَٱجْعَلُوا۟ بُيُوتَكُمْ قِبْلَةًۭ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 218, 11, 87, 0),
  (10, 88, 1452, 'وَقَالَ مُوسَىٰ رَبَّنَآ إِنَّكَ ءَاتَيْتَ فِرْعَوْنَ وَمَلَأَهُۥ زِينَةًۭ وَأَمْوَٰلًۭا فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا رَبَّنَا لِيُضِلُّوا۟ عَن سَبِيلِكَ ۖ رَبَّنَا ٱطْمِسْ عَلَىٰٓ أَمْوَٰلِهِمْ وَٱشْدُدْ عَلَىٰ قُلُوبِهِمْ فَلَا يُؤْمِنُوا۟ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 218, 11, 87, 0),
  (10, 89, 1453, 'قَالَ قَدْ أُجِيبَت دَّعْوَتُكُمَا فَٱسْتَقِيمَا وَلَا تَتَّبِعَآنِّ سَبِيلَ ٱلَّذِينَ لَا يَعْلَمُونَ', 219, 11, 87, 0),
  (10, 90, 1454, '۞ وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُۥ بَغْيًۭا وَعَدْوًا ۖ حَتَّىٰٓ إِذَآ أَدْرَكَهُ ٱلْغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱلَّذِىٓ ءَامَنَتْ بِهِۦ بَنُوٓا۟ إِسْرَٰٓءِيلَ وَأَنَا۠ مِنَ ٱلْمُسْلِمِينَ', 219, 11, 88, 0),
  (10, 91, 1455, 'ءَآلْـَٰٔنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنتَ مِنَ ٱلْمُفْسِدِينَ', 219, 11, 88, 0),
  (10, 92, 1456, 'فَٱلْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ ءَايَةًۭ ۚ وَإِنَّ كَثِيرًۭا مِّنَ ٱلنَّاسِ عَنْ ءَايَٰتِنَا لَغَٰفِلُونَ', 219, 11, 88, 0),
  (10, 93, 1457, 'وَلَقَدْ بَوَّأْنَا بَنِىٓ إِسْرَٰٓءِيلَ مُبَوَّأَ صِدْقٍۢ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخْتَلَفُوا۟ حَتَّىٰ جَآءَهُمُ ٱلْعِلْمُ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 219, 11, 88, 0),
  (10, 94, 1458, 'فَإِن كُنتَ فِى شَكٍّۢ مِّمَّآ أَنزَلْنَآ إِلَيْكَ فَسْـَٔلِ ٱلَّذِينَ يَقْرَءُونَ ٱلْكِتَٰبَ مِن قَبْلِكَ ۚ لَقَدْ جَآءَكَ ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ', 219, 11, 88, 0),
  (10, 95, 1459, 'وَلَا تَكُونَنَّ مِنَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلْخَٰسِرِينَ', 219, 11, 88, 0),
  (10, 96, 1460, 'إِنَّ ٱلَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَتُ رَبِّكَ لَا يُؤْمِنُونَ', 219, 11, 88, 0),
  (10, 97, 1461, 'وَلَوْ جَآءَتْهُمْ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُا۟ ٱلْعَذَابَ ٱلْأَلِيمَ', 219, 11, 88, 0),
  (10, 98, 1462, 'فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍۢ', 220, 11, 88, 0),
  (10, 99, 1463, 'وَلَوْ شَآءَ رَبُّكَ لَءَامَنَ مَن فِى ٱلْأَرْضِ كُلُّهُمْ جَمِيعًا ۚ أَفَأَنتَ تُكْرِهُ ٱلنَّاسَ حَتَّىٰ يَكُونُوا۟ مُؤْمِنِينَ', 220, 11, 88, 0),
  (10, 100, 1464, 'وَمَا كَانَ لِنَفْسٍ أَن تُؤْمِنَ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَيَجْعَلُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يَعْقِلُونَ', 220, 11, 88, 0),
  (10, 101, 1465, 'قُلِ ٱنظُرُوا۟ مَاذَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَا تُغْنِى ٱلْءَايَٰتُ وَٱلنُّذُرُ عَن قَوْمٍۢ لَّا يُؤْمِنُونَ', 220, 11, 88, 0),
  (10, 102, 1466, 'فَهَلْ يَنتَظِرُونَ إِلَّا مِثْلَ أَيَّامِ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِهِمْ ۚ قُلْ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ', 220, 11, 88, 0),
  (10, 103, 1467, 'ثُمَّ نُنَجِّى رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ حَقًّا عَلَيْنَا نُنجِ ٱلْمُؤْمِنِينَ', 220, 11, 88, 0),
  (10, 104, 1468, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى شَكٍّۢ مِّن دِينِى فَلَآ أَعْبُدُ ٱلَّذِينَ تَعْبُدُونَ مِن دُونِ ٱللَّهِ وَلَٰكِنْ أَعْبُدُ ٱللَّهَ ٱلَّذِى يَتَوَفَّىٰكُمْ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُؤْمِنِينَ', 220, 11, 88, 0),
  (10, 105, 1469, 'وَأَنْ أَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًۭا وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ', 220, 11, 88, 0),
  (10, 106, 1470, 'وَلَا تَدْعُ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكَ وَلَا يَضُرُّكَ ۖ فَإِن فَعَلْتَ فَإِنَّكَ إِذًۭا مِّنَ ٱلظَّٰلِمِينَ', 220, 11, 88, 0),
  (10, 107, 1471, 'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّۢ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يُرِدْكَ بِخَيْرٍۢ فَلَا رَآدَّ لِفَضْلِهِۦ ۚ يُصِيبُ بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 221, 11, 88, 0),
  (10, 108, 1472, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنَا۠ عَلَيْكُم بِوَكِيلٍۢ', 221, 11, 88, 0),
  (10, 109, 1473, 'وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ وَٱصْبِرْ حَتَّىٰ يَحْكُمَ ٱللَّهُ ۚ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 221, 11, 88, 0),
  (11, 1, 1474, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ كِتَٰبٌ أُحْكِمَتْ ءَايَٰتُهُۥ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', 221, 11, 88, 0),
  (11, 2, 1475, 'أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۚ إِنَّنِى لَكُم مِّنْهُ نَذِيرٌۭ وَبَشِيرٌۭ', 221, 11, 88, 0),
  (11, 3, 1476, 'وَأَنِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُمَتِّعْكُم مَّتَٰعًا حَسَنًا إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى وَيُؤْتِ كُلَّ ذِى فَضْلٍۢ فَضْلَهُۥ ۖ وَإِن تَوَلَّوْا۟ فَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍۢ كَبِيرٍ', 221, 11, 88, 0),
  (11, 4, 1477, 'إِلَى ٱللَّهِ مَرْجِعُكُمْ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 221, 11, 88, 0),
  (11, 5, 1478, 'أَلَآ إِنَّهُمْ يَثْنُونَ صُدُورَهُمْ لِيَسْتَخْفُوا۟ مِنْهُ ۚ أَلَا حِينَ يَسْتَغْشُونَ ثِيَابَهُمْ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 221, 11, 88, 0),
  (11, 6, 1479, '۞ وَمَا مِن دَآبَّةٍۢ فِى ٱلْأَرْضِ إِلَّا عَلَى ٱللَّهِ رِزْقُهَا وَيَعْلَمُ مُسْتَقَرَّهَا وَمُسْتَوْدَعَهَا ۚ كُلٌّۭ فِى كِتَٰبٍۢ مُّبِينٍۢ', 222, 12, 89, 0),
  (11, 7, 1480, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ وَكَانَ عَرْشُهُۥ عَلَى ٱلْمَآءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۗ وَلَئِن قُلْتَ إِنَّكُم مَّبْعُوثُونَ مِنۢ بَعْدِ ٱلْمَوْتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ', 222, 12, 89, 0),
  (11, 8, 1481, 'وَلَئِنْ أَخَّرْنَا عَنْهُمُ ٱلْعَذَابَ إِلَىٰٓ أُمَّةٍۢ مَّعْدُودَةٍۢ لَّيَقُولُنَّ مَا يَحْبِسُهُۥٓ ۗ أَلَا يَوْمَ يَأْتِيهِمْ لَيْسَ مَصْرُوفًا عَنْهُمْ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 222, 12, 89, 0),
  (11, 9, 1482, 'وَلَئِنْ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةًۭ ثُمَّ نَزَعْنَٰهَا مِنْهُ إِنَّهُۥ لَيَـُٔوسٌۭ كَفُورٌۭ', 222, 12, 89, 0),
  (11, 10, 1483, 'وَلَئِنْ أَذَقْنَٰهُ نَعْمَآءَ بَعْدَ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ ذَهَبَ ٱلسَّيِّـَٔاتُ عَنِّىٓ ۚ إِنَّهُۥ لَفَرِحٌۭ فَخُورٌ', 222, 12, 89, 0),
  (11, 11, 1484, 'إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌۭ', 222, 12, 89, 0),
  (11, 12, 1485, 'فَلَعَلَّكَ تَارِكٌۢ بَعْضَ مَا يُوحَىٰٓ إِلَيْكَ وَضَآئِقٌۢ بِهِۦ صَدْرُكَ أَن يَقُولُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ كَنزٌ أَوْ جَآءَ مَعَهُۥ مَلَكٌ ۚ إِنَّمَآ أَنتَ نَذِيرٌۭ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌ', 222, 12, 89, 0),
  (11, 13, 1486, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ فَأْتُوا۟ بِعَشْرِ سُوَرٍۢ مِّثْلِهِۦ مُفْتَرَيَٰتٍۢ وَٱدْعُوا۟ مَنِ ٱسْتَطَعْتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ', 223, 12, 89, 0),
  (11, 14, 1487, 'فَإِلَّمْ يَسْتَجِيبُوا۟ لَكُمْ فَٱعْلَمُوٓا۟ أَنَّمَآ أُنزِلَ بِعِلْمِ ٱللَّهِ وَأَن لَّآ إِلَٰهَ إِلَّا هُوَ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ', 223, 12, 89, 0),
  (11, 15, 1488, 'مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ', 223, 12, 89, 0),
  (11, 16, 1489, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْءَاخِرَةِ إِلَّا ٱلنَّارُ ۖ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَٰطِلٌۭ مَّا كَانُوا۟ يَعْمَلُونَ', 223, 12, 89, 0),
  (11, 17, 1490, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّهِۦ وَيَتْلُوهُ شَاهِدٌۭ مِّنْهُ وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًۭا وَرَحْمَةً ۚ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ ۚ وَمَن يَكْفُرْ بِهِۦ مِنَ ٱلْأَحْزَابِ فَٱلنَّارُ مَوْعِدُهُۥ ۚ فَلَا تَكُ فِى مِرْيَةٍۢ مِّنْهُ ۚ إِنَّهُ ٱلْحَقُّ مِن رَّبِّكَ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 223, 12, 89, 0),
  (11, 18, 1491, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا ۚ أُو۟لَٰٓئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ ٱلْأَشْهَٰدُ هَٰٓؤُلَآءِ ٱلَّذِينَ كَذَبُوا۟ عَلَىٰ رَبِّهِمْ ۚ أَلَا لَعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ', 223, 12, 89, 0),
  (11, 19, 1492, 'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًۭا وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 223, 12, 89, 0),
  (11, 20, 1493, 'أُو۟لَٰٓئِكَ لَمْ يَكُونُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ۘ يُضَٰعَفُ لَهُمُ ٱلْعَذَابُ ۚ مَا كَانُوا۟ يَسْتَطِيعُونَ ٱلسَّمْعَ وَمَا كَانُوا۟ يُبْصِرُونَ', 224, 12, 89, 0),
  (11, 21, 1494, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 224, 12, 89, 0),
  (11, 22, 1495, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْءَاخِرَةِ هُمُ ٱلْأَخْسَرُونَ', 224, 12, 89, 0),
  (11, 23, 1496, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَخْبَتُوٓا۟ إِلَىٰ رَبِّهِمْ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 224, 12, 89, 0),
  (11, 24, 1497, '۞ مَثَلُ ٱلْفَرِيقَيْنِ كَٱلْأَعْمَىٰ وَٱلْأَصَمِّ وَٱلْبَصِيرِ وَٱلسَّمِيعِ ۚ هَلْ يَسْتَوِيَانِ مَثَلًا ۚ أَفَلَا تَذَكَّرُونَ', 224, 12, 90, 0),
  (11, 25, 1498, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ إِنِّى لَكُمْ نَذِيرٌۭ مُّبِينٌ', 224, 12, 90, 0),
  (11, 26, 1499, 'أَن لَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍۢ', 224, 12, 90, 0),
  (11, 27, 1500, 'فَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرًۭا مِّثْلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمْ أَرَاذِلُنَا بَادِىَ ٱلرَّأْىِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍۭ بَلْ نَظُنُّكُمْ كَٰذِبِينَ', 224, 12, 90, 0),
  (11, 28, 1501, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَءَاتَىٰنِى رَحْمَةًۭ مِّنْ عِندِهِۦ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَٰرِهُونَ', 224, 12, 90, 0),
  (11, 29, 1502, 'وَيَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ مَالًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ ۚ وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓا۟ ۚ إِنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًۭا تَجْهَلُونَ', 225, 12, 90, 0),
  (11, 30, 1503, 'وَيَٰقَوْمِ مَن يَنصُرُنِى مِنَ ٱللَّهِ إِن طَرَدتُّهُمْ ۚ أَفَلَا تَذَكَّرُونَ', 225, 12, 90, 0),
  (11, 31, 1504, 'وَلَآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ إِنِّى مَلَكٌۭ وَلَآ أَقُولُ لِلَّذِينَ تَزْدَرِىٓ أَعْيُنُكُمْ لَن يُؤْتِيَهُمُ ٱللَّهُ خَيْرًا ۖ ٱللَّهُ أَعْلَمُ بِمَا فِىٓ أَنفُسِهِمْ ۖ إِنِّىٓ إِذًۭا لَّمِنَ ٱلظَّٰلِمِينَ', 225, 12, 90, 0),
  (11, 32, 1505, 'قَالُوا۟ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 225, 12, 90, 0),
  (11, 33, 1506, 'قَالَ إِنَّمَا يَأْتِيكُم بِهِ ٱللَّهُ إِن شَآءَ وَمَآ أَنتُم بِمُعْجِزِينَ', 225, 12, 90, 0),
  (11, 34, 1507, 'وَلَا يَنفَعُكُمْ نُصْحِىٓ إِنْ أَرَدتُّ أَنْ أَنصَحَ لَكُمْ إِن كَانَ ٱللَّهُ يُرِيدُ أَن يُغْوِيَكُمْ ۚ هُوَ رَبُّكُمْ وَإِلَيْهِ تُرْجَعُونَ', 225, 12, 90, 0),
  (11, 35, 1508, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَعَلَىَّ إِجْرَامِى وَأَنَا۠ بَرِىٓءٌۭ مِّمَّا تُجْرِمُونَ', 225, 12, 90, 0),
  (11, 36, 1509, 'وَأُوحِىَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن يُؤْمِنَ مِن قَوْمِكَ إِلَّا مَن قَدْ ءَامَنَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَفْعَلُونَ', 225, 12, 90, 0),
  (11, 37, 1510, 'وَٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۚ إِنَّهُم مُّغْرَقُونَ', 225, 12, 90, 0),
  (11, 38, 1511, 'وَيَصْنَعُ ٱلْفُلْكَ وَكُلَّمَا مَرَّ عَلَيْهِ مَلَأٌۭ مِّن قَوْمِهِۦ سَخِرُوا۟ مِنْهُ ۚ قَالَ إِن تَسْخَرُوا۟ مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ', 226, 12, 90, 0),
  (11, 39, 1512, 'فَسَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌۭ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌۭ مُّقِيمٌ', 226, 12, 90, 0),
  (11, 40, 1513, 'حَتَّىٰٓ إِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ قُلْنَا ٱحْمِلْ فِيهَا مِن كُلٍّۢ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ وَمَنْ ءَامَنَ ۚ وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌۭ', 226, 12, 90, 0),
  (11, 41, 1514, '۞ وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآ ۚ إِنَّ رَبِّى لَغَفُورٌۭ رَّحِيمٌۭ', 226, 12, 91, 0),
  (11, 42, 1515, 'وَهِىَ تَجْرِى بِهِمْ فِى مَوْجٍۢ كَٱلْجِبَالِ وَنَادَىٰ نُوحٌ ٱبْنَهُۥ وَكَانَ فِى مَعْزِلٍۢ يَٰبُنَىَّ ٱرْكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلْكَٰفِرِينَ', 226, 12, 91, 0),
  (11, 43, 1516, 'قَالَ سَـَٔاوِىٓ إِلَىٰ جَبَلٍۢ يَعْصِمُنِى مِنَ ٱلْمَآءِ ۚ قَالَ لَا عَاصِمَ ٱلْيَوْمَ مِنْ أَمْرِ ٱللَّهِ إِلَّا مَن رَّحِمَ ۚ وَحَالَ بَيْنَهُمَا ٱلْمَوْجُ فَكَانَ مِنَ ٱلْمُغْرَقِينَ', 226, 12, 91, 0),
  (11, 44, 1517, 'وَقِيلَ يَٰٓأَرْضُ ٱبْلَعِى مَآءَكِ وَيَٰسَمَآءُ أَقْلِعِى وَغِيضَ ٱلْمَآءُ وَقُضِىَ ٱلْأَمْرُ وَٱسْتَوَتْ عَلَى ٱلْجُودِىِّ ۖ وَقِيلَ بُعْدًۭا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 226, 12, 91, 0),
  (11, 45, 1518, 'وَنَادَىٰ نُوحٌۭ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبْنِى مِنْ أَهْلِى وَإِنَّ وَعْدَكَ ٱلْحَقُّ وَأَنتَ أَحْكَمُ ٱلْحَٰكِمِينَ', 226, 12, 91, 0),
  (11, 46, 1519, 'قَالَ يَٰنُوحُ إِنَّهُۥ لَيْسَ مِنْ أَهْلِكَ ۖ إِنَّهُۥ عَمَلٌ غَيْرُ صَٰلِحٍۢ ۖ فَلَا تَسْـَٔلْنِ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۖ إِنِّىٓ أَعِظُكَ أَن تَكُونَ مِنَ ٱلْجَٰهِلِينَ', 227, 12, 91, 0),
  (11, 47, 1520, 'قَالَ رَبِّ إِنِّىٓ أَعُوذُ بِكَ أَنْ أَسْـَٔلَكَ مَا لَيْسَ لِى بِهِۦ عِلْمٌۭ ۖ وَإِلَّا تَغْفِرْ لِى وَتَرْحَمْنِىٓ أَكُن مِّنَ ٱلْخَٰسِرِينَ', 227, 12, 91, 0),
  (11, 48, 1521, 'قِيلَ يَٰنُوحُ ٱهْبِطْ بِسَلَٰمٍۢ مِّنَّا وَبَرَكَٰتٍ عَلَيْكَ وَعَلَىٰٓ أُمَمٍۢ مِّمَّن مَّعَكَ ۚ وَأُمَمٌۭ سَنُمَتِّعُهُمْ ثُمَّ يَمَسُّهُم مِّنَّا عَذَابٌ أَلِيمٌۭ', 227, 12, 91, 0),
  (11, 49, 1522, 'تِلْكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهَآ إِلَيْكَ ۖ مَا كُنتَ تَعْلَمُهَآ أَنتَ وَلَا قَوْمُكَ مِن قَبْلِ هَٰذَا ۖ فَٱصْبِرْ ۖ إِنَّ ٱلْعَٰقِبَةَ لِلْمُتَّقِينَ', 227, 12, 91, 0),
  (11, 50, 1523, 'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًۭا ۚ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۖ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ', 227, 12, 91, 0),
  (11, 51, 1524, 'يَٰقَوْمِ لَآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ أَجْرِىَ إِلَّا عَلَى ٱلَّذِى فَطَرَنِىٓ ۚ أَفَلَا تَعْقِلُونَ', 227, 12, 91, 0),
  (11, 52, 1525, 'وَيَٰقَوْمِ ٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًۭا وَيَزِدْكُمْ قُوَّةً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا۟ مُجْرِمِينَ', 227, 12, 91, 0),
  (11, 53, 1526, 'قَالُوا۟ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةٍۢ وَمَا نَحْنُ بِتَارِكِىٓ ءَالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ', 227, 12, 91, 0),
  (11, 54, 1527, 'إِن نَّقُولُ إِلَّا ٱعْتَرَىٰكَ بَعْضُ ءَالِهَتِنَا بِسُوٓءٍۢ ۗ قَالَ إِنِّىٓ أُشْهِدُ ٱللَّهَ وَٱشْهَدُوٓا۟ أَنِّى بَرِىٓءٌۭ مِّمَّا تُشْرِكُونَ', 228, 12, 91, 0),
  (11, 55, 1528, 'مِن دُونِهِۦ ۖ فَكِيدُونِى جَمِيعًۭا ثُمَّ لَا تُنظِرُونِ', 228, 12, 91, 0),
  (11, 56, 1529, 'إِنِّى تَوَكَّلْتُ عَلَى ٱللَّهِ رَبِّى وَرَبِّكُم ۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذٌۢ بِنَاصِيَتِهَآ ۚ إِنَّ رَبِّى عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 228, 12, 91, 0),
  (11, 57, 1530, 'فَإِن تَوَلَّوْا۟ فَقَدْ أَبْلَغْتُكُم مَّآ أُرْسِلْتُ بِهِۦٓ إِلَيْكُمْ ۚ وَيَسْتَخْلِفُ رَبِّى قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُۥ شَيْـًٔا ۚ إِنَّ رَبِّى عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌۭ', 228, 12, 91, 0),
  (11, 58, 1531, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا هُودًۭا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَنَجَّيْنَٰهُم مِّنْ عَذَابٍ غَلِيظٍۢ', 228, 12, 91, 0),
  (11, 59, 1532, 'وَتِلْكَ عَادٌۭ ۖ جَحَدُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَعَصَوْا۟ رُسُلَهُۥ وَٱتَّبَعُوٓا۟ أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍۢ', 228, 12, 91, 0),
  (11, 60, 1533, 'وَأُتْبِعُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا لَعْنَةًۭ وَيَوْمَ ٱلْقِيَٰمَةِ ۗ أَلَآ إِنَّ عَادًۭا كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًۭا لِّعَادٍۢ قَوْمِ هُودٍۢ', 228, 12, 91, 0),
  (11, 61, 1534, '۞ وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًۭا ۚ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا فَٱسْتَغْفِرُوهُ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى قَرِيبٌۭ مُّجِيبٌۭ', 228, 12, 92, 0),
  (11, 62, 1535, 'قَالُوا۟ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوًّۭا قَبْلَ هَٰذَآ ۖ أَتَنْهَىٰنَآ أَن نَّعْبُدَ مَا يَعْبُدُ ءَابَآؤُنَا وَإِنَّنَا لَفِى شَكٍّۢ مِّمَّا تَدْعُونَآ إِلَيْهِ مُرِيبٍۢ', 228, 12, 92, 0),
  (11, 63, 1536, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَءَاتَىٰنِى مِنْهُ رَحْمَةًۭ فَمَن يَنصُرُنِى مِنَ ٱللَّهِ إِنْ عَصَيْتُهُۥ ۖ فَمَا تَزِيدُونَنِى غَيْرَ تَخْسِيرٍۢ', 229, 12, 92, 0),
  (11, 64, 1537, 'وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةًۭ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍۢ فَيَأْخُذَكُمْ عَذَابٌۭ قَرِيبٌۭ', 229, 12, 92, 0),
  (11, 65, 1538, 'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِى دَارِكُمْ ثَلَٰثَةَ أَيَّامٍۢ ۖ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍۢ', 229, 12, 92, 0),
  (11, 66, 1539, 'فَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا صَٰلِحًۭا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَمِنْ خِزْىِ يَوْمِئِذٍ ۗ إِنَّ رَبَّكَ هُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 229, 12, 92, 0),
  (11, 67, 1540, 'وَأَخَذَ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 229, 12, 92, 0),
  (11, 68, 1541, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَآ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمْ ۗ أَلَا بُعْدًۭا لِّثَمُودَ', 229, 12, 92, 0),
  (11, 69, 1542, 'وَلَقَدْ جَآءَتْ رُسُلُنَآ إِبْرَٰهِيمَ بِٱلْبُشْرَىٰ قَالُوا۟ سَلَٰمًۭا ۖ قَالَ سَلَٰمٌۭ ۖ فَمَا لَبِثَ أَن جَآءَ بِعِجْلٍ حَنِيذٍۢ', 229, 12, 92, 0),
  (11, 70, 1543, 'فَلَمَّا رَءَآ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۚ قَالُوا۟ لَا تَخَفْ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمِ لُوطٍۢ', 229, 12, 92, 0),
  (11, 71, 1544, 'وَٱمْرَأَتُهُۥ قَآئِمَةٌۭ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ', 229, 12, 92, 0),
  (11, 72, 1545, 'قَالَتْ يَٰوَيْلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٌۭ وَهَٰذَا بَعْلِى شَيْخًا ۖ إِنَّ هَٰذَا لَشَىْءٌ عَجِيبٌۭ', 230, 12, 92, 0),
  (11, 73, 1546, 'قَالُوٓا۟ أَتَعْجَبِينَ مِنْ أَمْرِ ٱللَّهِ ۖ رَحْمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيْكُمْ أَهْلَ ٱلْبَيْتِ ۚ إِنَّهُۥ حَمِيدٌۭ مَّجِيدٌۭ', 230, 12, 92, 0),
  (11, 74, 1547, 'فَلَمَّا ذَهَبَ عَنْ إِبْرَٰهِيمَ ٱلرَّوْعُ وَجَآءَتْهُ ٱلْبُشْرَىٰ يُجَٰدِلُنَا فِى قَوْمِ لُوطٍ', 230, 12, 92, 0),
  (11, 75, 1548, 'إِنَّ إِبْرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٌۭ مُّنِيبٌۭ', 230, 12, 92, 0),
  (11, 76, 1549, 'يَٰٓإِبْرَٰهِيمُ أَعْرِضْ عَنْ هَٰذَآ ۖ إِنَّهُۥ قَدْ جَآءَ أَمْرُ رَبِّكَ ۖ وَإِنَّهُمْ ءَاتِيهِمْ عَذَابٌ غَيْرُ مَرْدُودٍۢ', 230, 12, 92, 0),
  (11, 77, 1550, 'وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًۭا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًۭا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌۭ', 230, 12, 92, 0),
  (11, 78, 1551, 'وَجَآءَهُۥ قَوْمُهُۥ يُهْرَعُونَ إِلَيْهِ وَمِن قَبْلُ كَانُوا۟ يَعْمَلُونَ ٱلسَّيِّـَٔاتِ ۚ قَالَ يَٰقَوْمِ هَٰٓؤُلَآءِ بَنَاتِى هُنَّ أَطْهَرُ لَكُمْ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ فِى ضَيْفِىٓ ۖ أَلَيْسَ مِنكُمْ رَجُلٌۭ رَّشِيدٌۭ', 230, 12, 92, 0),
  (11, 79, 1552, 'قَالُوا۟ لَقَدْ عَلِمْتَ مَا لَنَا فِى بَنَاتِكَ مِنْ حَقٍّۢ وَإِنَّكَ لَتَعْلَمُ مَا نُرِيدُ', 230, 12, 92, 0),
  (11, 80, 1553, 'قَالَ لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍۢ شَدِيدٍۢ', 230, 12, 92, 0),
  (11, 81, 1554, 'قَالُوا۟ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓا۟ إِلَيْكَ ۖ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍۢ مِّنَ ٱلَّيْلِ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌ إِلَّا ٱمْرَأَتَكَ ۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمْ ۚ إِنَّ مَوْعِدَهُمُ ٱلصُّبْحُ ۚ أَلَيْسَ ٱلصُّبْحُ بِقَرِيبٍۢ', 230, 12, 92, 0),
  (11, 82, 1555, 'فَلَمَّا جَآءَ أَمْرُنَا جَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةًۭ مِّن سِجِّيلٍۢ مَّنضُودٍۢ', 231, 12, 92, 0),
  (11, 83, 1556, 'مُّسَوَّمَةً عِندَ رَبِّكَ ۖ وَمَا هِىَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٍۢ', 231, 12, 92, 0),
  (11, 84, 1557, '۞ وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًۭا ۚ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ وَلَا تَنقُصُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ ۚ إِنِّىٓ أَرَىٰكُم بِخَيْرٍۢ وَإِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍۢ مُّحِيطٍۢ', 231, 12, 93, 0),
  (11, 85, 1558, 'وَيَٰقَوْمِ أَوْفُوا۟ ٱلْمِكْيَالَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ', 231, 12, 93, 0),
  (11, 86, 1559, 'بَقِيَّتُ ٱللَّهِ خَيْرٌۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍۢ', 231, 12, 93, 0),
  (11, 87, 1560, 'قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ ۖ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ', 231, 12, 93, 0),
  (11, 88, 1561, 'قَالَ يَٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًۭا ۚ وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ ۚ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَٰحَ مَا ٱسْتَطَعْتُ ۚ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 231, 12, 93, 0),
  (11, 89, 1562, 'وَيَٰقَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِىٓ أَن يُصِيبَكُم مِّثْلُ مَآ أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَٰلِحٍۢ ۚ وَمَا قَوْمُ لُوطٍۢ مِّنكُم بِبَعِيدٍۢ', 232, 12, 93, 0),
  (11, 90, 1563, 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى رَحِيمٌۭ وَدُودٌۭ', 232, 12, 93, 0),
  (11, 91, 1564, 'قَالُوا۟ يَٰشُعَيْبُ مَا نَفْقَهُ كَثِيرًۭا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًۭا ۖ وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ ۖ وَمَآ أَنتَ عَلَيْنَا بِعَزِيزٍۢ', 232, 12, 93, 0),
  (11, 92, 1565, 'قَالَ يَٰقَوْمِ أَرَهْطِىٓ أَعَزُّ عَلَيْكُم مِّنَ ٱللَّهِ وَٱتَّخَذْتُمُوهُ وَرَآءَكُمْ ظِهْرِيًّا ۖ إِنَّ رَبِّى بِمَا تَعْمَلُونَ مُحِيطٌۭ', 232, 12, 93, 0),
  (11, 93, 1566, 'وَيَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌۭ ۖ سَوْفَ تَعْلَمُونَ مَن يَأْتِيهِ عَذَابٌۭ يُخْزِيهِ وَمَنْ هُوَ كَٰذِبٌۭ ۖ وَٱرْتَقِبُوٓا۟ إِنِّى مَعَكُمْ رَقِيبٌۭ', 232, 12, 93, 0),
  (11, 94, 1567, 'وَلَمَّا جَآءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًۭا وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ بِرَحْمَةٍۢ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُوا۟ ٱلصَّيْحَةُ فَأَصْبَحُوا۟ فِى دِيَٰرِهِمْ جَٰثِمِينَ', 232, 12, 93, 0),
  (11, 95, 1568, 'كَأَن لَّمْ يَغْنَوْا۟ فِيهَآ ۗ أَلَا بُعْدًۭا لِّمَدْيَنَ كَمَا بَعِدَتْ ثَمُودُ', 232, 12, 93, 0),
  (11, 96, 1569, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍۢ مُّبِينٍ', 232, 12, 93, 0),
  (11, 97, 1570, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱتَّبَعُوٓا۟ أَمْرَ فِرْعَوْنَ ۖ وَمَآ أَمْرُ فِرْعَوْنَ بِرَشِيدٍۢ', 232, 12, 93, 0),
  (11, 98, 1571, 'يَقْدُمُ قَوْمَهُۥ يَوْمَ ٱلْقِيَٰمَةِ فَأَوْرَدَهُمُ ٱلنَّارَ ۖ وَبِئْسَ ٱلْوِرْدُ ٱلْمَوْرُودُ', 233, 12, 93, 0),
  (11, 99, 1572, 'وَأُتْبِعُوا۟ فِى هَٰذِهِۦ لَعْنَةًۭ وَيَوْمَ ٱلْقِيَٰمَةِ ۚ بِئْسَ ٱلرِّفْدُ ٱلْمَرْفُودُ', 233, 12, 93, 0),
  (11, 100, 1573, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْقُرَىٰ نَقُصُّهُۥ عَلَيْكَ ۖ مِنْهَا قَآئِمٌۭ وَحَصِيدٌۭ', 233, 12, 93, 0),
  (11, 101, 1574, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن ظَلَمُوٓا۟ أَنفُسَهُمْ ۖ فَمَآ أَغْنَتْ عَنْهُمْ ءَالِهَتُهُمُ ٱلَّتِى يَدْعُونَ مِن دُونِ ٱللَّهِ مِن شَىْءٍۢ لَّمَّا جَآءَ أَمْرُ رَبِّكَ ۖ وَمَا زَادُوهُمْ غَيْرَ تَتْبِيبٍۢ', 233, 12, 93, 0),
  (11, 102, 1575, 'وَكَذَٰلِكَ أَخْذُ رَبِّكَ إِذَآ أَخَذَ ٱلْقُرَىٰ وَهِىَ ظَٰلِمَةٌ ۚ إِنَّ أَخْذَهُۥٓ أَلِيمٌۭ شَدِيدٌ', 233, 12, 93, 0),
  (11, 103, 1576, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّمَنْ خَافَ عَذَابَ ٱلْءَاخِرَةِ ۚ ذَٰلِكَ يَوْمٌۭ مَّجْمُوعٌۭ لَّهُ ٱلنَّاسُ وَذَٰلِكَ يَوْمٌۭ مَّشْهُودٌۭ', 233, 12, 93, 0),
  (11, 104, 1577, 'وَمَا نُؤَخِّرُهُۥٓ إِلَّا لِأَجَلٍۢ مَّعْدُودٍۢ', 233, 12, 93, 0),
  (11, 105, 1578, 'يَوْمَ يَأْتِ لَا تَكَلَّمُ نَفْسٌ إِلَّا بِإِذْنِهِۦ ۚ فَمِنْهُمْ شَقِىٌّۭ وَسَعِيدٌۭ', 233, 12, 93, 0),
  (11, 106, 1579, 'فَأَمَّا ٱلَّذِينَ شَقُوا۟ فَفِى ٱلنَّارِ لَهُمْ فِيهَا زَفِيرٌۭ وَشَهِيقٌ', 233, 12, 93, 0),
  (11, 107, 1580, 'خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۚ إِنَّ رَبَّكَ فَعَّالٌۭ لِّمَا يُرِيدُ', 233, 12, 93, 0),
  (11, 108, 1581, '۞ وَأَمَّا ٱلَّذِينَ سُعِدُوا۟ فَفِى ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا مَا دَامَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ إِلَّا مَا شَآءَ رَبُّكَ ۖ عَطَآءً غَيْرَ مَجْذُوذٍۢ', 233, 12, 94, 0),
  (11, 109, 1582, 'فَلَا تَكُ فِى مِرْيَةٍۢ مِّمَّا يَعْبُدُ هَٰٓؤُلَآءِ ۚ مَا يَعْبُدُونَ إِلَّا كَمَا يَعْبُدُ ءَابَآؤُهُم مِّن قَبْلُ ۚ وَإِنَّا لَمُوَفُّوهُمْ نَصِيبَهُمْ غَيْرَ مَنقُوصٍۢ', 234, 12, 94, 0),
  (11, 110, 1583, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ ۚ وَإِنَّهُمْ لَفِى شَكٍّۢ مِّنْهُ مُرِيبٍۢ', 234, 12, 94, 0),
  (11, 111, 1584, 'وَإِنَّ كُلًّۭا لَّمَّا لَيُوَفِّيَنَّهُمْ رَبُّكَ أَعْمَٰلَهُمْ ۚ إِنَّهُۥ بِمَا يَعْمَلُونَ خَبِيرٌۭ', 234, 12, 94, 0),
  (11, 112, 1585, 'فَٱسْتَقِمْ كَمَآ أُمِرْتَ وَمَن تَابَ مَعَكَ وَلَا تَطْغَوْا۟ ۚ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 234, 12, 94, 0),
  (11, 113, 1586, 'وَلَا تَرْكَنُوٓا۟ إِلَى ٱلَّذِينَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنْ أَوْلِيَآءَ ثُمَّ لَا تُنصَرُونَ', 234, 12, 94, 0),
  (11, 114, 1587, 'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَىِ ٱلنَّهَارِ وَزُلَفًۭا مِّنَ ٱلَّيْلِ ۚ إِنَّ ٱلْحَسَنَٰتِ يُذْهِبْنَ ٱلسَّيِّـَٔاتِ ۚ ذَٰلِكَ ذِكْرَىٰ لِلذَّٰكِرِينَ', 234, 12, 94, 0),
  (11, 115, 1588, 'وَٱصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 234, 12, 94, 0),
  (11, 116, 1589, 'فَلَوْلَا كَانَ مِنَ ٱلْقُرُونِ مِن قَبْلِكُمْ أُو۟لُوا۟ بَقِيَّةٍۢ يَنْهَوْنَ عَنِ ٱلْفَسَادِ فِى ٱلْأَرْضِ إِلَّا قَلِيلًۭا مِّمَّنْ أَنجَيْنَا مِنْهُمْ ۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُوا۟ مَآ أُتْرِفُوا۟ فِيهِ وَكَانُوا۟ مُجْرِمِينَ', 234, 12, 94, 0),
  (11, 117, 1590, 'وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍۢ وَأَهْلُهَا مُصْلِحُونَ', 234, 12, 94, 0),
  (11, 118, 1591, 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةًۭ وَٰحِدَةًۭ ۖ وَلَا يَزَالُونَ مُخْتَلِفِينَ', 235, 12, 94, 0),
  (11, 119, 1592, 'إِلَّا مَن رَّحِمَ رَبُّكَ ۚ وَلِذَٰلِكَ خَلَقَهُمْ ۗ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ', 235, 12, 94, 0),
  (11, 120, 1593, 'وَكُلًّۭا نَّقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَ ۚ وَجَآءَكَ فِى هَٰذِهِ ٱلْحَقُّ وَمَوْعِظَةٌۭ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 235, 12, 94, 0),
  (11, 121, 1594, 'وَقُل لِّلَّذِينَ لَا يُؤْمِنُونَ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنَّا عَٰمِلُونَ', 235, 12, 94, 0),
  (11, 122, 1595, 'وَٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ', 235, 12, 94, 0),
  (11, 123, 1596, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِلَيْهِ يُرْجَعُ ٱلْأَمْرُ كُلُّهُۥ فَٱعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ ۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ', 235, 12, 94, 0),
  (12, 1, 1597, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 235, 12, 94, 0),
  (12, 2, 1598, 'إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّۭا لَّعَلَّكُمْ تَعْقِلُونَ', 235, 12, 94, 0),
  (12, 3, 1599, 'نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ', 235, 12, 94, 0),
  (12, 4, 1600, 'إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ', 235, 12, 94, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 12, 1, 'Alif, Lam, Ra. These are the verses of the clear Book.'),
  ('en.sahih', 12, 2, 'Indeed, We have sent it down as an Arabic Qur\'an that you might understand.'),
  ('en.sahih', 12, 3, 'We relate to you, [O Muhammad], the best of stories in what We have revealed to you of this Qur\'an although you were, before it, among the unaware.'),
  ('en.sahih', 12, 4, '[Of these stories mention] when Joseph said to his father, "O my father, indeed I have seen [in a dream] eleven stars and the sun and the moon; I saw them prostrating to me."'),
  ('en.sahih', 12, 5, 'He said, "O my son, do not relate your vision to your brothers or they will contrive against you a plan. Indeed Satan, to man, is a manifest enemy.'),
  ('en.sahih', 12, 6, 'And thus will your Lord choose you and teach you the interpretation of narratives and complete His favor upon you and upon the family of Jacob, as He completed it upon your fathers before, Abraham and Isaac. Indeed, your Lord is Knowing and Wise."'),
  ('en.sahih', 12, 7, 'Certainly were there in Joseph and his brothers signs for those who ask,'),
  ('en.sahih', 12, 8, 'When they said, "Joseph and his brother are more beloved to our father than we, while we are a clan. Indeed, our father is in clear error.'),
  ('en.sahih', 12, 9, 'Kill Joseph or cast him out to [another] land; the countenance of your father will [then] be only for you, and you will be after that a righteous people."'),
  ('en.sahih', 12, 10, 'Said a speaker among them, "Do not kill Joseph but throw him into the bottom of the well; some travelers will pick him up - if you would do [something]."'),
  ('en.sahih', 12, 11, 'They said, "O our father, why do you not entrust us with Joseph while indeed, we are to him sincere counselors?'),
  ('en.sahih', 12, 12, 'Send him with us tomorrow that he may eat well and play. And indeed, we will be his guardians.'),
  ('en.sahih', 12, 13, '[Jacob] said, "Indeed, it saddens me that you should take him, and I fear that a wolf would eat him while you are of him unaware."'),
  ('en.sahih', 12, 14, 'They said, "If a wolf should eat him while we are a [strong] clan, indeed, we would then be losers."'),
  ('en.sahih', 12, 15, 'So when they took him [out] and agreed to put him into the bottom of the well... But We inspired to him, "You will surely inform them [someday] about this affair of theirs while they do not perceive [your identity]."'),
  ('en.sahih', 12, 16, 'And they came to their father at night, weeping.'),
  ('en.sahih', 12, 17, 'They said, "O our father, indeed we went racing each other and left Joseph with our possessions, and a wolf ate him. But you would not believe us, even if we were truthful."'),
  ('en.sahih', 12, 18, 'And they brought upon his shirt false blood. [Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. And Allah is the one sought for help against that which you describe."'),
  ('en.sahih', 12, 19, 'And there came a company of travelers; then they sent their water drawer, and he let down his bucket. He said, "Good news! Here is a boy." And they concealed him, [taking him] as merchandise; and Allah was knowing of what they did.'),
  ('en.sahih', 12, 20, 'And they sold him for a reduced price - a few dirhams - and they were, concerning him, of those content with little.'),
  ('en.sahih', 12, 21, 'And the one from Egypt who bought him said to his wife, "Make his residence comfortable. Perhaps he will benefit us, or we will adopt him as a son." And thus, We established Joseph in the land that We might teach him the interpretation of events. And Allah is predominant over His affair, but most of the people do not know.'),
  ('en.sahih', 12, 22, 'And when Joseph reached maturity, We gave him judgment and knowledge. And thus We reward the doers of good.'),
  ('en.sahih', 12, 23, 'And she, in whose house he was, sought to seduce him. She closed the doors and said, "Come, you." He said, "[I seek] the refuge of Allah. Indeed, he is my master, who has made good my residence. Indeed, wrongdoers will not succeed."'),
  ('en.sahih', 12, 24, 'And she certainly determined [to seduce] him, and he would have inclined to her had he not seen the proof of his Lord. And thus [it was] that We should avert from him evil and immorality. Indeed, he was of Our chosen servants.'),
  ('en.sahih', 12, 25, 'And they both raced to the door, and she tore his shirt from the back, and they found her husband at the door. She said, "What is the recompense of one who intended evil for your wife but that he be imprisoned or a painful punishment?"'),
  ('en.sahih', 12, 26, '[Joseph] said, "It was she who sought to seduce me." And a witness from her family testified. "If his shirt is torn from the front, then she has told the truth, and he is of the liars.'),
  ('en.sahih', 12, 27, 'But if his shirt is torn from the back, then she has lied, and he is of the truthful."'),
  ('en.sahih', 12, 28, 'So when her husband saw his shirt torn from the back, he said, "Indeed, it is of the women\'s plan. Indeed, your plan is great.'),
  ('en.sahih', 12, 29, 'Joseph, ignore this. And, [my wife], ask forgiveness for your sin. Indeed, you were of the sinful."'),
  ('en.sahih', 12, 30, 'And women in the city said, "The wife of al-\'Azeez is seeking to seduce her slave boy; he has impassioned her with love. Indeed, we see her [to be] in clear error."'),
  ('en.sahih', 12, 31, 'So when she heard of their scheming, she sent for them and prepared for them a banquet and gave each one of them a knife and said [to Joseph], "Come out before them." And when they saw him, they greatly admired him and cut their hands and said, "Perfect is Allah! This is not a man; this is none but a noble angel."'),
  ('en.sahih', 12, 32, 'She said, "That is the one about whom you blamed me. And I certainly sought to seduce him, but he firmly refused; and if he will not do what I order him, he will surely be imprisoned and will be of those debased."'),
  ('en.sahih', 12, 33, 'He said, "My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant."'),
  ('en.sahih', 12, 34, 'So his Lord responded to him and averted from him their plan. Indeed, He is the Hearing, the Knowing.'),
  ('en.sahih', 12, 35, 'Then it appeared to them after they had seen the signs that al-\'Azeez should surely imprison him for a time.'),
  ('en.sahih', 12, 36, 'And there entered the prison with him two young men. One of them said, "Indeed, I have seen myself [in a dream] pressing wine." The other said, "Indeed, I have seen myself carrying upon my head [some] bread, from which the birds were eating. Inform us of its interpretation; indeed, we see you to be of those who do good."'),
  ('en.sahih', 12, 37, 'He said, "You will not receive food that is provided to you except that I will inform you of its interpretation before it comes to you. That is from what my Lord has taught me. Indeed, I have left the religion of a people who do not believe in Allah, and they, in the Hereafter, are disbelievers.'),
  ('en.sahih', 12, 38, 'And I have followed the religion of my fathers, Abraham, Isaac and Jacob. And it was not for us to associate anything with Allah. That is from the favor of Allah upon us and upon the people, but most of the people are not grateful.'),
  ('en.sahih', 12, 39, 'O [my] two companions of prison, are separate lords better or Allah, the One, the Prevailing?'),
  ('en.sahih', 12, 40, 'You worship not besides Him except [mere] names you have named them, you and your fathers, for which Allah has sent down no authority. Legislation is not but for Allah. He has commanded that you worship not except Him. That is the correct religion, but most of the people do not know.'),
  ('en.sahih', 12, 41, 'O two companions of prison, as for one of you, he will give drink to his master of wine; but as for the other, he will be crucified, and the birds will eat from his head. The matter has been decreed about which you both inquire."'),
  ('en.sahih', 12, 42, 'And he said to the one whom he knew would go free, "Mention me before your master." But Satan made him forget the mention [to] his master, and Joseph remained in prison several years.'),
  ('en.sahih', 12, 43, 'And [subsequently] the king said, "Indeed, I have seen [in a dream] seven fat cows being eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry. O eminent ones, explain to me my vision, if you should interpret visions."'),
  ('en.sahih', 12, 44, 'They said, "[It is but] a mixture of false dreams, and we are not learned in the interpretation of dreams."'),
  ('en.sahih', 12, 45, 'But the one who was freed and remembered after a time said, "I will inform you of its interpretation, so send me forth."'),
  ('en.sahih', 12, 46, '[He said], "Joseph, O man of truth, explain to us about seven fat cows eaten by seven [that were] lean, and seven green spikes [of grain] and others [that were] dry - that I may return to the people; perhaps they will know [about you]."'),
  ('en.sahih', 12, 47, '[Joseph] said, "You will plant for seven years consecutively; and what you harvest leave in its spikes, except a little from which you will eat.'),
  ('en.sahih', 12, 48, 'Then will come after that seven difficult [years] which will consume what you saved for them, except a little from which you will store.'),
  ('en.sahih', 12, 49, 'Then will come after that a year in which the people will be given rain and in which they will press [olives and grapes]."'),
  ('en.sahih', 12, 50, 'And the king said, "Bring him to me." But when the messenger came to him, [Joseph] said, "Return to your master and ask him what is the case of the women who cut their hands. Indeed, my Lord is Knowing of their plan."'),
  ('en.sahih', 12, 51, 'Said [the king to the women], "What was your condition when you sought to seduce Joseph?" They said, "Perfect is Allah! We know about him no evil." The wife of al-\'Azeez said, "Now the truth has become evident. It was I who sought to seduce him, and indeed, he is of the truthful.'),
  ('en.sahih', 12, 52, 'That is so al-\'Azeez will know that I did not betray him in [his] absence and that Allah does not guide the plan of betrayers.'),
  ('en.sahih', 12, 53, 'And I do not acquit myself. Indeed, the soul is a persistent enjoiner of evil, except those upon which my Lord has mercy. Indeed, my Lord is Forgiving and Merciful."'),
  ('en.sahih', 12, 54, 'And the king said, "Bring him to me; I will appoint him exclusively for myself." And when he spoke to him, he said, "Indeed, you are today established [in position] and trusted."'),
  ('en.sahih', 12, 55, '[Joseph] said, "Appoint me over the storehouses of the land. Indeed, I will be a knowing guardian."'),
  ('en.sahih', 12, 56, 'And thus We established Joseph in the land to settle therein wherever he willed. We touch with Our mercy whom We will, and We do not allow to be lost the reward of those who do good.'),
  ('en.sahih', 12, 57, 'And the reward of the Hereafter is better for those who believed and were fearing Allah.'),
  ('en.sahih', 12, 58, 'And the brothers of Joseph came [seeking food], and they entered upon him; and he recognized them, but he was to them unknown.'),
  ('en.sahih', 12, 59, 'And when he had furnished them with their supplies, he said, "Bring me a brother of yours from your father. Do not you see that I give full measure and that I am the best of accommodators?'),
  ('en.sahih', 12, 60, 'But if you do not bring him to me, no measure will there be [hereafter] for you from me, nor will you approach me."'),
  ('en.sahih', 12, 61, 'They said, "We will attempt to dissuade his father from [keeping] him, and indeed, we will do [it]."'),
  ('en.sahih', 12, 62, 'And [Joseph] said to his servants, "Put their merchandise into their saddlebags so they might recognize it when they have gone back to their people that perhaps they will [again] return."'),
  ('en.sahih', 12, 63, 'So when they returned to their father, they said, "O our father, [further] measure has been denied to us, so send with us our brother [that] we will be given measure. And indeed, we will be his guardians."'),
  ('en.sahih', 12, 64, 'He said, "Should I entrust you with him except [under coercion] as I entrusted you with his brother before? But Allah is the best guardian, and He is the most merciful of the merciful."'),
  ('en.sahih', 12, 65, 'And when they opened their baggage, they found their merchandise returned to them. They said, "O our father, what [more] could we desire? This is our merchandise returned to us. And we will obtain supplies for our family and protect our brother and obtain an increase of a camel\'s load; that is an easy measurement."'),
  ('en.sahih', 12, 66, '[Jacob] said, "Never will I send him with you until you give me a promise by Allah that you will bring him [back] to me, unless you should be surrounded by enemies." And when they had given their promise, he said, "Allah, over what we say, is Witness."'),
  ('en.sahih', 12, 67, 'And he said, "O my sons, do not enter from one gate but enter from different gates; and I cannot avail you against [the decree of] Allah at all. The decision is only for Allah; upon Him I have relied, and upon Him let those who would rely [indeed] rely."'),
  ('en.sahih', 12, 68, 'And when they entered from where their father had ordered them, it did not avail them against Allah at all except [it was] a need within the soul of Jacob, which he satisfied. And indeed, he was a possessor of knowledge because of what We had taught him, but most of the people do not know.'),
  ('en.sahih', 12, 69, 'And when they entered upon Joseph, he took his brother to himself; he said, "Indeed, I am your brother, so do not despair over what they used to do [to me]."'),
  ('en.sahih', 12, 70, 'So when he had furnished them with their supplies, he put the [gold measuring] bowl into the bag of his brother. Then an announcer called out, "O caravan, indeed you are thieves."'),
  ('en.sahih', 12, 71, 'They said while approaching them, "What is it you are missing?"'),
  ('en.sahih', 12, 72, 'They said, "We are missing the measure of the king. And for he who produces it is [the reward of] a camel\'s load, and I am responsible for it."'),
  ('en.sahih', 12, 73, 'They said, "By Allah, you have certainly known that we did not come to cause corruption in the land, and we have not been thieves."'),
  ('en.sahih', 12, 74, 'The accusers said, "Then what would be its recompense if you should be liars?"'),
  ('en.sahih', 12, 75, '[The brothers] said, "Its recompense is that he in whose bag it is found - he [himself] will be its recompense. Thus do we recompense the wrongdoers."'),
  ('en.sahih', 12, 76, 'So he began [the search] with their bags before the bag of his brother; then he extracted it from the bag of his brother. Thus did We plan for Joseph. He could not have taken his brother within the religion of the king except that Allah willed. We raise in degrees whom We will, but over every possessor of knowledge is one [more] knowing.'),
  ('en.sahih', 12, 77, 'They said, "If he steals - a brother of his has stolen before." But Joseph kept it within himself and did not reveal it to them. He said, "You are worse in position, and Allah is most knowing of what you describe."'),
  ('en.sahih', 12, 78, 'They said, "O \'Azeez, indeed he has a father [who is] an old man, so take one of us in place of him. Indeed, we see you as a doer of good."'),
  ('en.sahih', 12, 79, 'He said, "[I seek] the refuge of Allah [to prevent] that we take except him with whom we found our possession. Indeed, we would then be unjust."'),
  ('en.sahih', 12, 80, 'So when they had despaired of him, they secluded themselves in private consultation. The eldest of them said, "Do you not know that your father has taken upon you an oath by Allah and [that] before you failed in [your duty to] Joseph? So I will never leave [this] land until my father permits me or Allah decides for me, and He is the best of judges.'),
  ('en.sahih', 12, 81, 'Return to your father and say, "O our father, indeed your son has stolen, and we did not testify except to what we knew. And we were not witnesses of the unseen,'),
  ('en.sahih', 12, 82, 'And ask the city in which we were and the caravan in which we came - and indeed, we are truthful,"'),
  ('en.sahih', 12, 83, '[Jacob] said, "Rather, your souls have enticed you to something, so patience is most fitting. Perhaps Allah will bring them to me all together. Indeed it is He who is the Knowing, the Wise."'),
  ('en.sahih', 12, 84, 'And he turned away from them and said, "Oh, my sorrow over Joseph," and his eyes became white from grief, for he was [of that] a suppressor.'),
  ('en.sahih', 12, 85, 'They said, "By Allah, you will not cease remembering Joseph until you become fatally ill or become of those who perish."'),
  ('en.sahih', 12, 86, 'He said, "I only complain of my suffering and my grief to Allah, and I know from Allah that which you do not know.'),
  ('en.sahih', 12, 87, 'O my sons, go and find out about Joseph and his brother and despair not of relief from Allah. Indeed, no one despairs of relief from Allah except the disbelieving people."'),
  ('en.sahih', 12, 88, 'So when they entered upon Joseph, they said, "O \'Azeez, adversity has touched us and our family, and we have come with goods poor in quality, but give us full measure and be charitable to us. Indeed, Allah rewards the charitable."'),
  ('en.sahih', 12, 89, 'He said, "Do you know what you did with Joseph and his brother when you were ignorant?"'),
  ('en.sahih', 12, 90, 'They said, "Are you indeed Joseph?" He said "I am Joseph, and this is my brother. Allah has certainly favored us. Indeed, he who fears Allah and is patient, then indeed, Allah does not allow to be lost the reward of those who do good."'),
  ('en.sahih', 12, 91, 'They said, "By Allah, certainly has Allah preferred you over us, and indeed, we have been sinners."'),
  ('en.sahih', 12, 92, 'He said, "No blame will there be upon you today. Allah will forgive you; and He is the most merciful of the merciful."'),
  ('en.sahih', 12, 93, 'Take this, my shirt, and cast it over the face of my father; he will become seeing. And bring me your family, all together."'),
  ('en.sahih', 12, 94, 'And when the caravan departed [from Egypt], their father said, "Indeed, I find the smell of Joseph [and would say that he was alive] if you did not think me weakened in mind."'),
  ('en.sahih', 12, 95, 'They said, "By Allah, indeed you are in your [same] old error."'),
  ('en.sahih', 12, 96, 'And when the bearer of good tidings arrived, he cast it over his face, and he returned [once again] seeing. He said, "Did I not tell you that I know from Allah that which you do not know?"'),
  ('en.sahih', 12, 97, 'They said, "O our father, ask for us forgiveness of our sins; indeed, we have been sinners."'),
  ('en.sahih', 12, 98, 'He said, "I will ask forgiveness for you from my Lord. Indeed, it is He who is the Forgiving, the Merciful."'),
  ('en.sahih', 12, 99, 'And when they entered upon Joseph, he took his parents to himself and said, "Enter Egypt, Allah willing, safe [and secure]."'),
  ('en.sahih', 12, 100, 'And he raised his parents upon the throne, and they bowed to him in prostration. And he said, "O my father, this is the explanation of my vision of before. My Lord has made it reality. And He was certainly good to me when He took me out of prison and brought you [here] from bedouin life after Satan had induced [estrangement] between me and my brothers. Indeed, my Lord is Subtle in what He wills. Indeed, it is He who is the Knowing, the Wise.'),
  ('en.sahih', 12, 101, 'My Lord, You have given me [something] of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and in the Hereafter. Cause me to die a Muslim and join me with the righteous."'),
  ('en.sahih', 12, 102, 'That is from the news of the unseen which We reveal, [O Muhammad], to you. And you were not with them when they put together their plan while they conspired.'),
  ('en.sahih', 12, 103, 'And most of the people, although you strive [for it], are not believers.'),
  ('en.sahih', 12, 104, 'And you do not ask of them for it any payment. It is not except a reminder to the worlds.'),
  ('en.sahih', 12, 105, 'And how many a sign within the heavens and earth do they pass over while they, therefrom, are turning away.'),
  ('en.sahih', 12, 106, 'And most of them believe not in Allah except while they associate others with Him.'),
  ('en.sahih', 12, 107, 'Then do they feel secure that there will not come to them an overwhelming [aspect] of the punishment of Allah or that the Hour will not come upon them suddenly while they do not perceive?'),
  ('en.sahih', 12, 108, 'Say, "This is my way; I invite to Allah with insight, I and those who follow me. And exalted is Allah; and I am not of those who associate others with Him."'),
  ('en.sahih', 12, 109, 'And We sent not before you [as messengers] except men to whom We revealed from among the people of cities. So have they not traveled through the earth and observed how was the end of those before them? And the home of the Hereafter is best for those who fear Allah; then will you not reason?'),
  ('en.sahih', 12, 110, '[They continued] until, when the messengers despaired and were certain that they had been denied, there came to them Our victory, and whoever We willed was saved. And Our punishment cannot be repelled from the people who are criminals.'),
  ('en.sahih', 12, 111, 'There was certainly in their stories a lesson for those of understanding. Never was the Qur\'an a narration invented, but a confirmation of what was before it and a detailed explanation of all things and guidance and mercy for a people who believe.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 12, 1, 'আলিফ-লা-ম-রা; এগুলো সুস্পষ্ট গ্রন্থের আয়াত।'),
  ('bn.bengali', 12, 2, 'আমি একে আরবী ভাষায় কোরআন রূপে অবতীর্ণ করেছি, যাতে তোমরা বুঝতে পার।'),
  ('bn.bengali', 12, 3, 'আমি তোমার নিকট উত্তম কাহিনী বর্ণনা করেছি, যেমতে আমি এ কোরআন তোমার নিকট অবতীর্ণ করেছি। তুমি এর আগে অবশ্যই এ ব্যাপারে অনবহিতদের অন্তর্ভূক্ত ছিলে।'),
  ('bn.bengali', 12, 4, 'যখন ইউসুফ পিতাকে বললঃ পিতা, আমি স্বপ্নে দেখেছি এগারটি নক্ষত্রকে। সুর্যকে এবং চন্দ্রকে। আমি তাদেরকে আমার উদ্দেশে সেজদা করতে দেখেছি।'),
  ('bn.bengali', 12, 5, 'তিনি বললেনঃ বৎস, তোমার ভাইদের সামনে এ স্বপ্ন বর্ণনা করো না। তাহলে তারা তোমার বিরুদ্ধে চক্রান্ত করবে। নিশ্চয় শয়তান মানুষের প্রকাশ্য।'),
  ('bn.bengali', 12, 6, 'এমনিভাবে তোমার পালনকর্তা তোমাকে মনোনীত করবেন এবং তোমাকে বাণীসমূহের নিগুঢ় তত্ত্ব শিক্ষা দেবেন এবং পূর্ণ করবেন স্বীয় অনুগ্রহ তোমার প্রতি ও ইয়াকুব পরিবার-পরিজনের প্রতি; যেমন ইতিপূর্বে তোমার পিতৃপুরুষ ইব্রাহীম ও ইসহাকের প্রতি পূর্ণ করেছেন। নিশ্চয় তোমার পালনকর্তা অত্যন্ত জ্ঞানী, প্রজ্ঞাময়।'),
  ('bn.bengali', 12, 7, 'অবশ্য ইউসুফ ও তাঁর ভাইদের কাহিনীতে জিজ্ঞাসুদের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 12, 8, 'যখন তারা বললঃ অবশ্যই ইউসুফ ও তাঁর ভাই আমাদের পিতার কাছে আমাদের চাইতে অধিক প্রিয় অথচ আমরা একটা সংহত শক্তি বিশেষ। নিশ্চয় আমাদের পিতা স্পষ্ট ভ্রান্তিতে রয়েছেন।'),
  ('bn.bengali', 12, 9, 'হত্যা কর ইউসুফকে কিংবা ফেলে আস তাকে অন্য কোন স্থানে। এতে শুধু তোমাদের প্রতিই তোমাদের পিতার মনোযোগ নিবিষ্ট হবে এবং এরপর তোমরা যোগ্য বিবেচিত হয়ে থাকবে।'),
  ('bn.bengali', 12, 10, 'তাদের মধ্য থেকে একজন বলল, তোমরা ইউসুফ কে হত্যা করো না, বরং ফেলে দাও তাকে অন্ধকূপে যাতে কোন পথিক তাকে উঠিয়ে নিয়ে যায়, যদি তোমাদের কিছু করতেই হয়।'),
  ('bn.bengali', 12, 11, 'তারা বললঃ পিতাঃ ব্যাপার কি, আপনি ইউসুফের ব্যাপারে আমাদেরকে বিশ্বাস করেন না ? আমরা তো তার হিতাকাংখী।'),
  ('bn.bengali', 12, 12, 'আগামীকাল তাকে আমাদের সাথে প্রেরণ করুন-তৃপ্তিসহ খাবে এবং খেলাধুলা করবে এবং আমরা অবশ্যই তার রক্ষণাবেক্ষন করব।'),
  ('bn.bengali', 12, 13, 'তিনি বললেনঃ আমার দুশ্চিন্তা হয় যে, তোমরা তাকে নিয়ে যাবে এবং আমি আশঙ্কা করি যে, ব্যাঘ্র তাঁকে খেয়ে ফেলবে এবং তোমরা তার দিক থেকে গাফেল থাকবে।'),
  ('bn.bengali', 12, 14, 'তারা বললঃ আমরা একটি ভারী দল থাকা সত্ত্বেও যদি ব্যাঘ্র তাকে খেয়ে ফেলে, তবে আমরা সবই হারালাম।'),
  ('bn.bengali', 12, 15, 'অতঃপর তারা যখন তাকে নিয়ে চলল এবং অন্ধকূপে নিক্ষেপ করতে একমত হল এবং আমি তাকে ইঙ্গিত করলাম যে, তুমি তাদেরকে তাদের এ কাজের কথা বলবে এমতাবস্থায় যে, তারা তোমাকে চিনবে না।'),
  ('bn.bengali', 12, 16, 'তারা রাতের বেলায় কাঁদতে কাঁদতে পিতার কাছে এল।'),
  ('bn.bengali', 12, 17, 'তারা বললঃ পিতাঃ আমরা দৌড় প্রতিযোগিতা করতে গিয়েছিলাম এবং ইউসুফকে আসবাব-পত্রের কাছে রেখে গিয়েছিলাম। অতঃপর তাকে বাঘে খেয়ে ফেলেছে। আপনি তো আমাদেরকে বিশ্বাস করবেন না, যদিও আমরা সত্যবাদী।'),
  ('bn.bengali', 12, 18, 'এবং তারা তার জামায় কৃত্রিম রক্ত লাগিয়ে আনল। বললেনঃ এটা কখনই নয়; বরং তোমাদের মন তোমাদেরকে একটা কথা সাজিয়ে দিয়েছে। সুতরাং এখন ছবর করাই শ্রেয়। তোমরা যা বর্ণনা করছ, সে বিষয়ে একমাত্র আল্লাহই আমার সাহায্য স্থল।'),
  ('bn.bengali', 12, 19, 'এবং একটি কাফেলা এল। অতঃপর তাদের পানি সংগ্রাহককে প্রেরণ করল। সে বালতি ফেলল। বললঃ কি আনন্দের কথা। এ তো একটি কিশোর তারা তাকে পন্যদ্রব্য গণ্য করে গোপন করে ফেলল। আল্লাহ খুব জানেন যা কিছু তারা করেছিল।'),
  ('bn.bengali', 12, 20, 'ওরা তাকে কম মূল্যে বিক্রি করে দিল গনাগুণতি কয়েক দেরহাম এবং তাঁর ব্যাপারে নিরাসক্ত ছিল।'),
  ('bn.bengali', 12, 21, 'মিসরে যে ব্যক্তি তাকে ক্রয় করল, সে তার স্ত্রীকে বললঃ একে সম্মানে রাখ। সম্ভবতঃ সে আমাদের কাছে আসবে অথবা আমরা তাকে পুত্ররূপে গ্রহণ করে নেব। এমনিভাবে আমি ইউসুফকে এদেশে প্রতিষ্ঠিত করলাম এবং এ জন্যে যে তাকে বাক্যাদির পূর্ণ মর্ম অনুধাবনের পদ্ধতি বিষয়ে শিক্ষা দেই। আল্লাহ নিজ কাজে প্রবল থাকেন, কিন্তু অধিকাংশ লোক তা জানে না।'),
  ('bn.bengali', 12, 22, 'যখন সে পূর্ণ যৌবনে পৌছে গেল, তখন তাকে প্রজ্ঞা ও ব্যুৎপত্তি দান করলাম। এমননিভাবে আমি সৎকর্মপরায়ণদেরকে প্রতিদান দেই।'),
  ('bn.bengali', 12, 23, 'আর সে যে মহিলার ঘরে ছিল, ঐ মহিলা তাকে ফুসলাতে লাগল এবং দরজাসমূহ বন্ধ করে দিল। সে মহিলা বললঃ শুন! তোমাকে বলছি, এদিকে আস, সে বললঃ আল্লাহ রক্ষা করুন; তোমার স্বামী আমার মালিক। তিনি আমাকে সযত্নে থাকতে দিয়েছেন। নিশ্চয় সীমা লংঘনকারীগণ সফল হয় না।'),
  ('bn.bengali', 12, 24, 'নিশ্চয় মহিলা তার বিষয়ে চিন্তা করেছিল এবং সেও মহিলার বিষয়ে চিন্তা করত। যদি না সে স্বীয় পালনকর্তার মহিমা অবলোকন করত। এমনিবাবে হয়েছে, যাতে আমি তার কাছ থেকে মন্দ বিষয় ও নিলজ্জ বিষয় সরিয়ে দেই। নিশ্চয় সে আমার মনোনীত বান্দাদের একজন।'),
  ('bn.bengali', 12, 25, 'তারা উভয়ে ছুটে দরজার দিকে গেল এবং মহিলা ইউসুফের জামা পিছন দিক থেকে ছিঁড়ে ফেলল। উভয়ে মহিলার স্বামীকে দরজার কাছে পেল। মহিলা বললঃ যে ব্যক্তি তোমার পরিজনের সাথে কুকর্মের ইচ্ছা করে, তাকে কারাগারে পাঠানো অথবা অন্য কোন যন্ত্রণাদায়ক শাস্তি দেয়া ছাড়া তার আর কি শাস্তি হতে পারে?'),
  ('bn.bengali', 12, 26, 'ইউসুফ (আঃ) বললেন, সেই আমাকে আত্মসংবরণ না করতে ফুসলিয়েছে। মহিলার পরিবারে জনৈক সাক্ষী দিল যে, যদি তার জামা সামনের দিক থেকে ছিন্ন থাকে, তবে মহিলা সত্যবাদিনী এবং সে মিথ্যাবাদি।'),
  ('bn.bengali', 12, 27, 'এবং যদি তার জামা পেছনের দিক থেকে ছিন্ন থাকে, তবে মহিলা মিথ্যাবাদিনী এবং সে সত্যবাদী।'),
  ('bn.bengali', 12, 28, 'অতঃপর গৃহস্বামী যখন দেখল যে, তার জামা পেছন দিক থেকে ছিন্ন, তখন সে বলল, নিশ্চয় এটা তোমাদের ছলনা। নিঃসন্দেহে তোমাদের ছলনা খুবই মারাত্নক।'),
  ('bn.bengali', 12, 29, 'ইউসুফ এ প্রসঙগ ছাড়! আর হে নারী, এ পাপের জন্য ক্ষমা প্রার্থনা কর নিঃসন্দেহে তুমি-ই পাপাচারিনী।'),
  ('bn.bengali', 12, 30, 'নগরে মহিলারা বলাবলি করতে লাগল যে, আযীযের স্ত্রী স্বীয় গোলামকে কুমতলব চরিতার্থ করার জন্য ফুসলায়। সে তার প্রেমে উম্মত্ত হয়ে গেছে। আমরা তো তাকে প্রকাশ্য ভ্রান্তিতে দেখতে পাচ্ছি।'),
  ('bn.bengali', 12, 31, 'যখন সে তাদের চক্রান্ত শুনল, তখন তাদেরকে ডেকে পাঠাল এবং তাদের জন্যে একটি ভোজ সভার আয়োজন করল। সে তাদের প্রত্যেককে একটি ছুরি দিয়ে বললঃ ইউসুফ এদের সামনে চলে এস। যখন তারা তাকে দেখল, হতভম্ব হয়ে গেল এবং আপন হাত কেটে ফেলল। তারা বললঃ কখনই নয় এ ব্যক্তি মানব নয়। এ তো কোন মহান ফেরেশতা।'),
  ('bn.bengali', 12, 32, 'মহিলা বললঃ এ ঐ ব্যক্তি, যার জন্যে তোমরা আমাকে ভৎর্সনা করছিলে। আমি ওরই মন জয় করতে চেয়েছিলাম। কিন্তু সে নিজেকে নিবৃত্ত রেখেছে। আর আমি যা আদেশ দেই, সে যদি তা না করে, তবে অবশ্যই সে কারাগারে প্রেরিত হবে এবং লাঞ্চিত হবে।'),
  ('bn.bengali', 12, 33, 'ইউসুফ বললঃ হে পালনকর্তা তারা আমাকে যে কাজের দিকে আহবান করে, তার চাইতে আমি কারাগারই পছন্দ করি। যদি আপনি তাদের চক্রান্ত আমার উপর থেকে প্রতিহত না করেন, তবে আমি তাদের প্রতি আকৃষ্ট হয়ে পড়ব এবং অজ্ঞদের অন্তর্ভূক্ত হয়ে যাব।'),
  ('bn.bengali', 12, 34, 'অতঃপর তার পালনকর্তা তার দোয়া কবুল করে নিলেন। অতঃপর তাদের চক্রান্ত প্রতিহত করলেন। নিশ্চয় তিনি সর্বশ্রোতা ও সর্বজ্ঞ।'),
  ('bn.bengali', 12, 35, 'অতঃপর এসব নিদর্শন দেখার পর তারা তাকে কিছুদিন কারাগারে রাখা সমীচীন মনে করল।'),
  ('bn.bengali', 12, 36, 'তাঁর সাথে কারাগারে দুজন যুবক প্রবেশ করল। তাদের একজন বললঃ আমি স্বপ্নে দেখলাম যে, আমি মদ নিঙড়াচ্ছি। অপরজন বললঃ আমি দেখলাম যে, নিজ মাথায় রুটি বহন করছি। তা থেকে পাখী ঠুকরিয়ে খাচ্ছে। আমাদের কে এর ব্যাখ্যা বলুন। আমরা আপনাকে সৎকর্মশীল দেখতে পাচ্ছি।'),
  ('bn.bengali', 12, 37, 'তিনি বললেনঃ তোমাদেরকে প্রত্যহ যে খাদ্য দেয়া হয়, তা তোমাদের কাছে আসার আগেই আমি তার ব্যাখ্যা বলে দেব। এ জ্ঞান আমার পালনকর্তা আমাকে শিক্ষা দিয়েছেন। আমি ঐসব লোকের ধর্ম পরিত্যাগ করেছি যারা আল্লাহর প্রতি বিশ্বাস স্থাপন করে না এবং পরকালে অবিশ্বাসী।'),
  ('bn.bengali', 12, 38, 'আমি আপন পিতৃপুরুষ ইব্রাহীম, ইসহাক ও ইয়াকুবের ধর্ম অনুসরণ করছি। আমাদের জন্য শোভা পায় না যে, কোন বস্তুকে আল্লাহর অংশীদার করি। এটা আমাদের প্রতি এবং অন্য সব লোকের প্রতি আল্লাহর অনুগ্রহ। কিন্ত অধিকাংশ লোক অনুগ্রহ স্বীকার করে না।'),
  ('bn.bengali', 12, 39, 'হে কারাগারের সঙ্গীরা! পৃথক পৃথক অনেক উপাস্য ভাল, না পরাক্রমশালী এক আল্লাহ?'),
  ('bn.bengali', 12, 40, 'তোমরা আল্লাহকে ছেড়ে নিছক কতগুলো নামের এবাদত কর, সেগুলো তোমরা এবং তোমাদের বাপ-দাদারা সাব্যস্ত করে নিয়েছে। আল্লাহ এদের কোন প্রমাণ অবতীর্ণ করেননি। আল্লাহ ছাড়া কারও বিধান দেবার ক্ষমতা নেই। তিনি আদেশ দিয়েছেন যে, তিনি ব্যতীত অন্য কারও এবাদত করো না। এটাই সরল পথ। কিন্তু অধিকাংশ লোক তা জানে না।'),
  ('bn.bengali', 12, 41, 'হে কারাগারের সঙ্গীরা! তোমাদের একজন আপন প্রভুকে মদ্যপান করাবে এবং দ্বিতীয়জন, তাকে শুলে চড়ানো হবে। অতঃপর তার মস্তক থেকে পাখী আহার করবে। তোমরা যে, বিষয়ে জানার আগ্রহী তার সিদ্ধান্ত হয়ে গেছে।'),
  ('bn.bengali', 12, 42, 'যে ব্যক্তি সম্পর্কে ধারণা ছিল যে, সে মুক্তি পাবে, তাকে ইউসুফ বলে দিলঃ আপন প্রভুর কাছে আমার আলোচনা করবে। অতঃপর শয়তান তাকে প্রভুর কাছে আলোচনার কথা ভুলিয়ে দিল। ফলে তাঁকে কয়েক বছর কারাগারে থাকতে হল।'),
  ('bn.bengali', 12, 43, 'বাদশাহ বললঃ আমি স্বপ্নে দেখলাম, সাতটি মোটাতাজা গাভী-এদেরকে সাতটি শীর্ণ গাভী খেয়ে যাচ্ছে এবং সাতটি সবুজ শীষ ও অন্যগুলো শুষ্ক। হে পরিষদবর্গ! তোমরা আমাকে আমার স্বপ্নের ব্যাখ্যা বল, যদি তোমরা স্বপ্নের ব্যাখ্যায় পারদর্শী হয়ে থাক।'),
  ('bn.bengali', 12, 44, 'তারা বললঃ এটা কল্পনাপ্রসূত স্বপ্ন। এরূপ স্বপ্নের ব্যাখ্যা আমাদের জানা নেই।'),
  ('bn.bengali', 12, 45, 'দু’জন কারারুদ্ধের মধ্য থেকে যে ব্যক্তি মুক্তি পেয়েছিল এবং দীর্ঘকাল পর স্মরণ হলে, সে বলল, আমি তোমাদেরকে এর ব্যাখ্যা বলছি। তোমরা আমাকে প্রেরণ কর।'),
  ('bn.bengali', 12, 46, 'সে তথায় পৌঁছে বললঃ হে ইউসুফ! হে সত্যবাদী! সাতটি মোটাতাজা গাভী-তাদেরকে খাচ্ছে সাতটি শীর্ণ গাভী এবং সাতটি সবুজ শীর্ষ ও অন্যগুলো শুষ্ক; আপনি আমাদেরকে এ স্বপ্ন সম্পর্কে পথনির্দেশ প্রদান করুনঃ যাতে আমি তাদের কাছে ফিরে গিয়ে তাদের অবগত করাতে পারি।'),
  ('bn.bengali', 12, 47, 'বললঃ তোমরা সাত বছর উত্তম রূপে চাষাবাদ করবে। অতঃপর যা কাটবে, তার মধ্যে যে সামান্য পরিমাণ তোমরা খাবে তা ছাড়া অবশিষ্ট শস্য শীষ সমেত রেখে দেবে।'),
  ('bn.bengali', 12, 48, 'এবং এরপরে আসবে দূর্ভিক্ষের সাত বছর; তোমরা এ দিনের জন্যে যা রেখেছিলে, তা খেয়ে যাবে, কিন্তু অল্প পরিমাণ ব্যতীত, যা তোমরা তুলে রাখবে।'),
  ('bn.bengali', 12, 49, 'এর পরেই আসবে একবছর-এতে মানুষের উপর বৃষ্টি বর্ষিত হবে এবং এতে তারা রস নিঙড়াবে।'),
  ('bn.bengali', 12, 50, 'বাদশাহ বললঃ ফিরে যাও তোমাদের প্রভুর কাছে এবং জিজ্ঞেস কর তাকে ঐ মহিলার স্বরূপ কি, যারা স্বীয় হস্ত কর্তন করেছিল! আমার পালনকর্তা তো তাদের ছলনা সবই জানেন।'),
  ('bn.bengali', 12, 51, 'বাদশাহ মহিলাদেরকে বললেনঃ তোমাদের হাল-হাকিকত কি, যখন তোমরা ইউসুফকে আত্মসংবরণ থেকে ফুসলিয়েছিলে? তারা বললঃ আল্লাহ মহান, আমরা তার সম্পর্কে মন্দ কিছু জানি না। আযীয-পত্মি বললঃ এখন সত্য কথা প্রকাশ হয়ে গেছে। আমিই তাকে আত্মসংবরণ থেকে ফুসলিয়েছিলাম এবং সে সত্যবাদী।'),
  ('bn.bengali', 12, 52, 'ইউসুফ বললেনঃ এটা এজন্য, যাতে আযীয জেনে নেয় যে, আমি গোপনে তার সাথে বিশ্বাসঘাতকতা করিনি। আরও এই যে, আল্লাহ বিশ্বাসঘাতকদের প্রতারণাকে এগুতে দেন না।'),
  ('bn.bengali', 12, 53, 'আমি নিজেকে নির্দোষ বলি না। নিশ্চয় মানুষের মন মন্দ কর্মপ্রবণ কিন্তু সে নয়-আমার পালনকর্তা যার প্রতি অনুগ্রহ করেন। নিশ্চয় আমার পালনকর্তা ক্ষমাশীল, দয়ালু।'),
  ('bn.bengali', 12, 54, 'বাদশাহ বললঃ তাকে আমার কাছে নিয়ে এসো। আমি তাকে নিজের বিশ্বস্ত সহচর করে রাখব। অতঃপর যখন তার সাথে মতবিনিময় করল, তখন বললঃ নিশ্চয়ই আপনি আমার কাছে আজ থেকে বিশ্বস্ত হিসাবে মর্যাদার স্থান লাভ করেছেন।'),
  ('bn.bengali', 12, 55, 'ইউসুফ বললঃ আমাকে দেশের ধন-ভান্ডারে নিযুক্ত করুন। আমি বিশ্বস্ত রক্ষক ও অধিক জ্ঞানবান।'),
  ('bn.bengali', 12, 56, 'এমনিভাবে আমি ইউসুফকে সে দেশের বুকে প্রতিষ্ঠা দান করেছি। সে তথায় যেখানে ইচ্ছা স্থান করে নিতে পারত। আমি স্বীয় রহমত যাকে ইচ্ছা পৌছে দেই এবং আমি পূণ্যবানদের প্রতিদান বিনষ্ট করি না।'),
  ('bn.bengali', 12, 57, 'এবং ঐ লোকদের জন্য পরকালে প্রতিদান উত্তম যারা ঈমান এনেছে ও সতর্কতা অবলম্বন করে।'),
  ('bn.bengali', 12, 58, 'ইউসুফের ভ্রাতারা আগমন করল, অতঃপর তার কাছে উপস্থিত হল। সে তাদেরকে চিনল এবং তারা তাকে চিনল না।'),
  ('bn.bengali', 12, 59, 'এবং সে যখন তাদেরকে তাদের রসদ প্রস্তুত করে দিল, তখন সে বললঃ তোমাদের বৈমাত্রেয় ভাইকে আমার কাছে নিয়ে এসো। তোমরা কি দেখ না যে, আমি পুরা মাপ দেই এবং মেহমানদেরকে উত্তম সমাদার করি?'),
  ('bn.bengali', 12, 60, 'অতঃপর যদি তাকে আমার কাছে না আন, তবে আমার কাছে তোমাদের কোন বরাদ্ধ নেই এবং তোমরা আমার কাছে আসতে পারবে না।'),
  ('bn.bengali', 12, 61, 'তারা বললঃ আমরা তার সম্পর্কে তার পিতাকে সম্মত করার চেষ্টা করব এবং আমাদেরকে একাজ করতেই হবে।'),
  ('bn.bengali', 12, 62, 'এবং সে ভৃত্যদেরকে বললঃ তাদের পণ্যমূল্য তাদের রসদ-পত্রের মধ্যে রেখে দাও-সম্ভবতঃ তারা গৃহে পৌঁছে তা বুঝতে পারবে, সম্ভবতঃ তারা পুনর্বার আসবে।'),
  ('bn.bengali', 12, 63, 'তারা যখন তাদের পিতার কাছে ফিরে এল তখন বললঃ হে আমাদের পিতা, আমাদের জন্যে খাদ্য শস্যের বরাদ্দ নিষিদ্ধ করা হয়েছে। অতএব আপনি আমাদের ভাইকে আমাদের সাথে প্রেরণ করুন; যাতে আমরা খাদ্য শস্যের বরাদ্দ আনতে পারি এবং আমরা অবশ্যই তার পুরোপুরি হেফাযত করব।'),
  ('bn.bengali', 12, 64, 'বললেন, আমি তার সম্পর্কে তোমাদেরকে কি সেরূপ বিশ্বাস করব, যেমন ইতিপূর্বে তার ভাই সম্পর্কে বিশ্বাস করেছিলাম? অতএব আল্লাহ উত্তম হেফাযতকারী এবং তিনিই সর্বাধিক দয়ালু।'),
  ('bn.bengali', 12, 65, 'এবং যখন তারা আসবাবপত্র খুলল, তখন দেখতে পেল যে, তাদেরকে তাদের পন্যমুল্য ফেরত দেয়া হয়েছে। তারা বললঃ হে আমাদের পিতা, আমরা আর কি চাইতে পারি। এই আমাদের প্রদত্ত পন্যমূল্য, আমাদেরকে ফেরত দেয়া হয়েছে। এখন আমরা আবার আমাদের পরিবারবর্গের জন্যে রসদ আনব এবং আমাদের ভাইয়ের দেখাশোনা করব এবং এক এক উটের বরাদ্দ খাদ্যশস্য আমরা অতিরিক্ত আনব। ঐ বরাদ্দ সহজ।'),
  ('bn.bengali', 12, 66, 'বললেন, তাকে ততক্ষণ তোমাদের সাথে পাঠাব না, যতক্ষণ তোমরা আমাকে আল্লাহর নামে অঙ্গীকার না দাও যে, তাকে অবশ্যই আমার কাছে পৌঁছে দেবে; কিন্তু যদি তোমরা সবাই একান্তই অসহায় না হয়ে যাও। অতঃপর যখন সবাই তাঁকে অঙ্গীকার দিল, তখন তিনি বললেনঃ আমাদের মধ্যে যা কথাবার্তা হলো সে ব্যাপারে আল্লাহই মধ্যস্থ রইলেন।'),
  ('bn.bengali', 12, 67, 'ইয়াকুব বললেনঃ হে আমার বৎসগণ! সবাই একই প্রবেশদ্বার দিয়ে যেয়ো না, বরং পৃথক পৃথক দরজা দিয়ে প্রবেশ করো। আল্লাহর কোন বিধান থেকে আমি তোমাদেরকে রক্ষা করতে পারি না। নির্দেশ আল্লাহরই চলে। তাঁরই উপর আমি ভরসা করি এবং তাঁরই উপর ভরসা করা উচিত ভরসাকারীদের।'),
  ('bn.bengali', 12, 68, 'তারা যখন পিতার কথামত প্রবেশ করল, তখন আল্লাহর বিধানের বিরুদ্ধে তা তাদের বাঁচাতে পারল না। কিন্তু ইয়াকুবের সিদ্ধান্তে তাঁর মনের একটি বাসনা ছিল, যা তিনি পূর্ণ করেছেন। এবং তিনি তো আমার শেখানো বিষয় অবগত ছিলেন। কিন্তু অনেক মানুষ অবগত নয়।'),
  ('bn.bengali', 12, 69, 'যখন তারা ইউসুফের কাছে উপস্থিত হল, তখন সে আপন ভ্রাতাকে নিজের কাছে রাখল। বললঃ নিশ্চই আমি তোমার সহোদর। অতএব তাদের কৃতকর্মের জন্যে দুঃখ করো না।'),
  ('bn.bengali', 12, 70, 'অতঃপর যখন ইউসুফ তাদের রসদপত্র প্রস্তুত করে দিল, তখন পানপাত্র আপন ভাইয়ের রসদের মধ্যে রেখে দিল। অতঃপর একজন ঘোষক ডেকে বললঃ হে কাফেলার লোকজন, তোমরা অবশ্যই চোর।'),
  ('bn.bengali', 12, 71, 'তারা ওদের দিকে মুখ করে বললঃ তোমাদের কি হারিয়েছে?'),
  ('bn.bengali', 12, 72, 'তারা বললঃ আমরা বাদশাহর পানপাত্র হারিয়েছি এবং যে কেউ এটা এনে দেবে সে এক উটের বোঝা পরিমাণ মাল পাবে এবং আমি এর যামিন।'),
  ('bn.bengali', 12, 73, 'তারা বললঃ আল্লাহর কসম, তোমরা তো জান, আমরা অনর্থ ঘটাতে এদেশে আসিনি এবং আমরা কখনও চোর ছিলাম না।'),
  ('bn.bengali', 12, 74, 'তারা বললঃ যদি তোমরা মিথ্যাবাদী হও, তবে যে, চুরি করেছে তার কি শাস্তি?'),
  ('bn.bengali', 12, 75, 'তারা বললঃ এর শাস্তি এই যে, যার রসদপত্র থেকে তা পাওয়া যাবে, এর প্রতিদানে সে দাসত্বে যাবে। আমরা যালেমদেরকে এভাবেই শাস্তি দেই।'),
  ('bn.bengali', 12, 76, 'অতঃপর ইউসুফ আপন ভাইদের থলের পূর্বে তাদের থলে তল্লাশী শুরু করলেন। অবশেষে সেই পাত্র আপন ভাইয়ের থলের মধ্য থেকে বের করলেন। এমনিভাবে আমি ইউসুফকে কৌশল শিক্ষা দিয়েছিলাম। সে বাদশাহর আইনে আপন ভাইকে কখনও দাসত্বে দিতে পারত না, কিু栦#2438;ল্লাহ যদি ইচ্ছা করেন। আমি যাকে ইচ্ছা, মর্যাদায় উন্নীত করি এবং প্রত্যেক জ্ঞানীর উপরে আছে অধিকতর এক জ্ঞানীজন।'),
  ('bn.bengali', 12, 77, 'তারা বলতে লাগলঃ যদি সে চুরি করে থাকে, তবে তার এক ভাইও ইতিপূর্বে চুরি করেছিল। তখন ইউসুফ প্রকৃত ব্যাপার নিজের মনে রাখলেন এবং তাদেরকে জানালেন না। মনে মনে বললেনঃ তোমরা লোক হিসাবে নিতান্ত মন্দ এবং আল্লাহ খুব জ্ঞাত রয়েছেন, যা তোমরা বর্ণনা করছ;'),
  ('bn.bengali', 12, 78, 'তারা বলতে লাগলঃ হে আযীয, তার পিতা আছেন, যিনি খুবই বৃদ্ধ বয়স্ক। সুতরাং আপনি আমাদের একজনকে তার বদলে রেখে দিন। আমরা আপনাকে অনুগ্রহশীল ব্যক্তিদের একজন দেখতে পাচ্ছি।'),
  ('bn.bengali', 12, 79, 'তিনি বললেনঃ যার কাছে আমরা আমাদের মাল পেয়েছি, তাকে ছাড়া আর কাউকে গ্রেফতার করা থেকে আল্লাহ আমাদের রক্ষা করুন। তা হলে তো আমরা নিশ্চিতই অন্যায়কারী হয়ে যাব।'),
  ('bn.bengali', 12, 80, 'অতঃপর যখন তারা তাঁর কাছ থেকে নিরাশ হয়ে গেল, তখন পরামর্শের জন্যে এখানে বসল। তাদের জ্যেষ্ঠ ভাই বললঃ তোমরা কি জান না যে, পিতা তোমাদের কাছ থেকে আল্লাহর নামে অঙ্গীকার নিয়েছেন এবং পূর্বে ইউসুফের ব্যাপারেও তোমরা অন্যায় করেছো? অতএব আমি তো কিছুতেই এদেশ ত্যাগ করব না, যে পর্যন্ত না পিতা আমাকে আদেশ দেন অথবা আল্লাহ আমার পক্ষে কোন ব্যবস্থা করে দেন। তিনিই সর্বোত্তম ব্যবস্থাপক।'),
  ('bn.bengali', 12, 81, 'তোমরা তোমাদের পিতার কাছে ফিরে যাও এবং বলঃ পিতা আপনার ছেলে চুরি করেছে। আমরা তাই বলে দিলাম, যা আমাদের জানা ছিল এবং অদৃশ্য বিষয়ের প্রতি আমাদের লক্ষ্য ছিল না।'),
  ('bn.bengali', 12, 82, 'জিজ্ঞেস করুন ঐ জনপদের লোকদেরকে যেখানে আমরা ছিলাম এবং ঐ কাফেলাকে, যাদের সাথে আমরা এসেছি। নিশ্চিতই আমরা সত্য বলছি।'),
  ('bn.bengali', 12, 83, 'তিনি বললেনঃ কিছুই না, তোমরা মনগড়া একটি কথা নিয়েই এসেছ। এখন ধৈর্য্যধারণই উত্তম। সম্ভবতঃ আল্লাহ তাদের সবাইকে একসঙ্গে আমার কাছে নিয়ে আসবেন তিনি সুবিজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 12, 84, 'এবং তাদের দিক থেকে তিনি মুখ ফিরিয়ে নিলেন এবং বললেনঃ হায় আফসোস ইউসুফের জন্যে। এবং দুঃখে তাঁর চক্ষুদ্বয় সাদা হয়ে গেল। এবং অসহনীয় মনস্তাপে তিনি ছিলেন ক্লিষ্ট।'),
  ('bn.bengali', 12, 85, 'তারা বলতে লাগলঃ আল্লাহর কসম আপনি তো ইউসুফের স্মরণ থেকে নিবৃত হবেন না, যে পর্যন্ত মরণপন্ন না হয়ে যান কিংবা মৃতবরণ না করেন'),
  ('bn.bengali', 12, 86, 'তিনি বললেনঃ আমি তো আমার দুঃখ ও অস্থিরতা আল্লাহর সমীপেই নিবেদন করছি এবং আল্লাহর পক্ষ থেকে আমি যা জানি, তা তোমরা জান না।'),
  ('bn.bengali', 12, 87, 'বৎসগণ! যাও, ইউসুফ ও তার ভাইকে তালাশ কর এবং আল্লাহর রহমত থেকে নিরাশ হয়ো না। নিশ্চয় আল্লাহর রহমত থেকে কাফের সম্প্রদায়, ব্যতীত অন্য কেউ নিরাশ হয় না।'),
  ('bn.bengali', 12, 88, 'অতঃপর যখন তারা ইউসুফের কাছে পৌঁছল তখন বললঃ হে আযীয, আমরা ও আমাদের পরিবারবর্গ কষ্টের সম্মুখীন হয়ে পড়েছি এবং আমরা অপর্যাপ্ত পুঁজি নিয়ে এসেছি। অতএব আপনি আমাদের পুরোপুরি বরাদ্দ দিন এবং আমাদের কে দান করুন। আল্লাহ দাতাদেরকে প্রতিদান দিয়ে থাকেন।'),
  ('bn.bengali', 12, 89, 'ইউসুফ বললেনঃ তোমাদের জানা আছে কি, যা তোমরা ইউসুফ ও তার ভাইয়ের সাথে করেছ, যখন তোমরা অপরিণামদর্শী ছিলে?'),
  ('bn.bengali', 12, 90, 'তারা বলল, তবে কি তুমিই ইউসুফ! বললেনঃ আমিই ইউসুফ এবং এ হল আমার সহোদর ভাই। আল্লাহ আমাদের প্রতি অনুগ্রহ করেছেন। নিশ্চয় যে তাকওয়া অবলম্বন করে এবং সবর করে, আল্লাহ এহেন সৎকর্মশীলদের প্রতিদান বিনষ্ট করেন না।'),
  ('bn.bengali', 12, 91, 'তারা বললঃ আল্লাহর কসম, আমাদের চাইতে আল্লাহ তোমাকে পছন্দ করেছেন এবং আমরা অবশ্যই অপরাধী ছিলাম।'),
  ('bn.bengali', 12, 92, 'বললেন, আজ তোমাদের বিরুদ্ধে কোন অভিযোগ নেই। আল্লাহ তোমাদের কে ক্ষমা করুন। তিনি সব মেহেরবানদের চাইতে অধিক মেহেরবান।'),
  ('bn.bengali', 12, 93, 'তোমরা আমার এ জামাটি নিয়ে যাও। এটি আমার পিতার মুখমন্ডলের উপর রেখে দিও, এতে তাঁর দৃষ্টি শক্তি ফিরে আসবে। আর তোমাদের পরিবারবর্গের সবাইকে আমার কাছে নিয়ে এস।'),
  ('bn.bengali', 12, 94, 'যখন কাফেলা রওয়ানা হল, তখন তাদের পিতা বললেনঃ যদি তোমরা আমাকে অপ্রকৃতিস্থ না বল, তবে বলিঃ আমি নিশ্চিতরূপেই ইউসুফের গন্ধ পাচ্ছি।'),
  ('bn.bengali', 12, 95, 'লোকেরা বললঃ আল্লাহর কসম, আপনি তো সেই পুরানো ভ্রান্তিতেই পড়ে আছেন।'),
  ('bn.bengali', 12, 96, 'অতঃপর যখন সুসংবাদদাতা পৌঁছল, সে জামাটি তাঁর মুখে রাখল। অমনি তিনি দৃষ্টি শক্তি ফিরে পেলেন। বললেনঃ আমি কি তোমাদেরকে বলিনি যে, আমি আল্লাহর পক্ষ থেকে যা জানি তোমরা তা জান না?'),
  ('bn.bengali', 12, 97, 'তারা বললঃ পিতা আমাদের অপরাধ ক্ষমা করান। নিশ্চয় আমরা অপরাধী ছিলাম।'),
  ('bn.bengali', 12, 98, 'বললেন, সত্বরই আমি পালনকর্তার কাছে তোমাদের জন্য ক্ষমা চাইব। নিশ্চয় তিনি ক্ষমাশীল, দয়ালূ।'),
  ('bn.bengali', 12, 99, 'অতঃপর যখন তারা ইউসুফের কাছে পৌঁছল, তখন ইউসুফ পিতা-মাতাকে নিজের কাছে জায়গা দিলেন এবং বললেনঃ আল্লাহ চাহেন তো শান্তি চিত্তে মিসরে প্রবেশ করুন।'),
  ('bn.bengali', 12, 100, 'এবং তিনি পিতা-মাতাকে সিংহাসনের উপর বসালেন এবং তারা সবাই তাঁর সামনে সেজদাবনত হল। তিনি বললেনঃ পিতা এ হচ্ছে আমার ইতিপূর্বেকার স্বপ্নের বর্ণনা আমার পালনকর্তা একে সত্যে পরিণত করেছেন এবং তিনি আমার প্রতি অনুগ্রহ করেছেন। আমাকে জেল থেকে বের করেছেন এবং আপনাদেরকে গ্রাম থেকে নিয়ে এসেছেন, শয়তান আমার ও আমার ভাইদের মধ্যে কলহ সৃষ্টি করে দেয়ার পর। আমার পালনকর্তা যা চান, কৌশলে সম্পন্ন করেন। নিশ্চয় তিনি বিজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 12, 101, 'হে পালনকর্তা আপনি আমাকে রাষ্ট্রক্ষমতাও দান করেছেন এবং আমাকে বিভিন্ন তাৎপর্য সহ ব্যাখ্যা করার বিদ্যা শিখিয়ে দিয়েছেন। হে নভোমন্ডল ও ভূ-মন্ডলের স্রষ্টা, আপনিই আমার কার্যনির্বাহী ইহকাল ও পরকালে। আমাকে ইসলামের উপর মৃত্যুদান করুন এবং আমাকে স্বজনদের সাথে মিলিত করুন।'),
  ('bn.bengali', 12, 102, 'এগুলো অদৃশ্যের খবর, আমি আপনার কাছে প্রেরণ করি। আপনি তাদের কাছে ছিলেন না, যখন তারা স্বীয় কাজ সাব্যস্ত করছিল এবং চক্রান্ত করছিল।'),
  ('bn.bengali', 12, 103, 'আপনি যতই চান, অধিকাংশ লোক বিশ্বাসকারী নয়।'),
  ('bn.bengali', 12, 104, 'আপনি এর জন্যে তাদের কাছে কোন বিনিময় চান না। এটা তো সারা বিশ্বের জন্যে উপদেশ বৈ নয়।'),
  ('bn.bengali', 12, 105, 'অনেক নিদর্শন রয়েছে নভোমন্ডলে ও ভু-মন্ডলে যেগুলোর উপর দিয়ে তারা পথ অতিক্রম করে এবং তারা এসবের দিকে মনোনিবেশ করে না।'),
  ('bn.bengali', 12, 106, 'অনেক মানুষ আল্লাহর প্রতি বিশ্বাস স্থাপন করে, কিন্তু সাথে সাথে শিরকও করে।'),
  ('bn.bengali', 12, 107, 'তারা কি নির্ভীক হয়ে গেছে এ বিষয়ে যে, আল্লাহর আযাবের কোন বিপদ তাদেরকে আবৃত করে ফেলবে অথবা তাদের কাছে হঠাৎ কেয়ামত এসে যাবে, অথচ তারা টেরও পাবে না?'),
  ('bn.bengali', 12, 108, 'বলে দিনঃ এই আমার পথ। আমি আল্লাহর দিকে বুঝে সুঝে দাওয়াত দেই আমি এবং আমার অনুসারীরা। আল্লাহ পবিত্র। আমি অংশীবাদীদের অন্তর্ভুক্ত নই।'),
  ('bn.bengali', 12, 109, 'আপনার পূর্বে আমি যতজনকে রসূল করে পাঠিয়েছি, তারা সবাই পুরুষই ছিল জনপদবাসীদের মধ্য থেকে। আমি তাঁদের কাছে ওহী প্রেরণ করতাম। তারা কি দেশ-বিদেশ ভ্রমণ করে না, যাতে দেখে নিত কিরূপ পরিণতি হয়েছে তাদের যারা পূর্বে ছিল ? সংযমকারীদের জন্যে পরকালের আবাসই উত্তম। তারা কি এখনও বোঝে না?'),
  ('bn.bengali', 12, 110, 'এমনকি যখন পয়গম্বরগণ নৈরাশ্যে পতিত হয়ে যেতেন, এমনকি এরূপ ধারণা করতে শুরু করতেন যে, তাদের অনুমান বুঝি মিথ্যায় পরিণত হওয়ার উপক্রম হয়েছিল, তখন তাদের কাছে আমার সাহায্য পৌছে। অতঃপর আমি যাদের চেয়েছি তারা উদ্ধার পেয়েছে। আমার শাস্তি অপরাধী সম্প্রদায় থেকে প্রতিহত হয় না।'),
  ('bn.bengali', 12, 111, 'তাদের কাহিনীতে বুদ্ধিমানদের জন্য রয়েছে প্রচুর শিক্ষণীয় বিষয়, এটা কোন মনগড়া কথা নয়, কিন্তু যারা বিশ্বাস স্থাপন করে তাদের জন্যে পূর্বেকার কালামের সমর্থন এবং প্রত্যেক বস্তুর বিবরণ রহমত ও হেদায়েত।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 12, 1, 'Alif. Lam. Ra. These are verse of the Scripture that maketh plain.'),
  ('en.pickthall', 12, 2, 'Lo! We have revealed it, a Lecture in Arabic, that ye may understand.'),
  ('en.pickthall', 12, 3, 'We narrate unto thee (Muhammad) the best of narratives in that We have inspired in thee this Qur\'an, though aforetime thou wast of the heedless.'),
  ('en.pickthall', 12, 4, 'When Joseph said unto his father: O my father! Lo! I saw in a dream eleven planets and the sun and the moon, I saw them prostrating themselves unto me.'),
  ('en.pickthall', 12, 5, 'He said: O my dear son! Tell not thy brethren of thy vision, lest they plot a plot against thee. Lo! Satan is for man an open foe.'),
  ('en.pickthall', 12, 6, 'Thus thy Lord will prefer thee and will teach thee the interpretation of events, and will perfect His grace upon thee and upon the family of Jacob as He perfected it upon thy forefathers, Abraham and Isaac. Lo! thy Lord is Knower, Wise.'),
  ('en.pickthall', 12, 7, 'Verily in Joseph and his brethren are signs (of Allah\'s Sovereignty) for the inquiring.'),
  ('en.pickthall', 12, 8, 'When they said: Verily Joseph and his brother are dearer to our father than we are, many though we be. Lo! our father is in plain aberration.'),
  ('en.pickthall', 12, 9, '(One said): Kill Joseph or cast him to some (other) land, so that your father\'s favour may be all for you, and (that) ye may afterward be righteous folk.'),
  ('en.pickthall', 12, 10, 'One among them said: Kill not Joseph but, if ye must be doing, fling him into the depth of the pit; some caravan will find him.'),
  ('en.pickthall', 12, 11, 'They said: O our father! Why wilt thou not trust us with Joseph, when lo! we are good friends to him?'),
  ('en.pickthall', 12, 12, 'Send him with us to-morrow that he may enjoy himself and play. And lo! we shall take good care of him.'),
  ('en.pickthall', 12, 13, 'He said: Lo! in truth it saddens me that ye should take him with you, and I fear less the wolf devour him while ye are heedless of him.'),
  ('en.pickthall', 12, 14, 'They said: If the wolf should devour him when we are (so strong) a band, then surely we should have already perished.'),
  ('en.pickthall', 12, 15, 'Then, when they led him off, and were of one mind that they should place him in the depth of the pit, We inspired in him: Thou wilt tell them of this deed of theirs when they know (thee) not.'),
  ('en.pickthall', 12, 16, 'And they came weeping to their father in the evening.'),
  ('en.pickthall', 12, 17, 'Saying: O our father! We went racing one with another, and left Joseph by our things, and the wolf devoured him, and thou believest not our saying even when we speak the truth.'),
  ('en.pickthall', 12, 18, 'And they came with false blood on his shirt. He said: Nay, but your minds have beguiled you into something. (My course is) comely patience. And Allah it is Whose help is to be sought in that (predicament) which ye describe.'),
  ('en.pickthall', 12, 19, 'And there came a caravan, and they sent their waterdrawer. He let down his pail (into the pit). He said: Good luck! Here is a youth. And they hid him as a treasure, and Allah was Aware of what they did.'),
  ('en.pickthall', 12, 20, 'And they sold him for a low price, a number of silver coins; and they attached no value to him.'),
  ('en.pickthall', 12, 21, 'And he of Egypt who purchased him said unto his wife: Receive him honourably. Perchance he may prove useful to us or we may adopt him as a son. Thus we established Joseph in the land that We might teach him the interpretation of events. And Allah was predominant in His career, but most of mankind know not.'),
  ('en.pickthall', 12, 22, 'And And when he reached his prime We gave him wisdom and knowledge. Thus We reward the good.'),
  ('en.pickthall', 12, 23, 'And she, in whose house he was, asked of him an evil act. She bolted the doors and said: Come! He said: I seek refuge in Allah! Lo! he is my lord, who hath treated me honourably. Lo! wrong-doers never prosper.'),
  ('en.pickthall', 12, 24, 'She verily desired him, and he would have desired her if it had not been that he saw the argument of his Lord. Thus it was, that We might ward off from him evil and lewdness. Lo! he was of Our chosen slaves.'),
  ('en.pickthall', 12, 25, 'And they raced with one another to the door, and she tore his shirt from behind, and they met her lord and master at the door. She said: What shall be his reward, who wisheth evil to thy folk, save prison or a painful doom?'),
  ('en.pickthall', 12, 26, '(Joseph) said: She it was who asked of me an evil act. And a witness of her own folk testified: If his shirt is torn from before, then she speaketh truth and he is of the liars.'),
  ('en.pickthall', 12, 27, 'And if his shirt is torn from behind, then she hath lied and he is of the truthful.'),
  ('en.pickthall', 12, 28, 'So when he saw his shirt torn from behind, he said: Lo! this is of the guile of you women. Lo! the guile of you is very great.'),
  ('en.pickthall', 12, 29, 'O Joseph! Turn away from this, and thou, (O woman), ask forgiveness for thy sin. Lo! thou art of the faulty.'),
  ('en.pickthall', 12, 30, 'And women in the city said: The ruler\'s wife is asking of her slave-boy an ill-deed. Indeed he has smitten her to the heart with love. We behold her in plain aberration.'),
  ('en.pickthall', 12, 31, 'And when she heard of their sly talk, she sent to them and prepared for them a cushioned couch (to lie on at the feast) and gave to every one of them a knife and said (to Joseph): Come out unto them! And when they saw him they exalted him and cut their hands, exclaiming: Allah Blameless! This is no a human being. This is not other than some gracious angel.'),
  ('en.pickthall', 12, 32, 'She said: This is he on whose account ye blamed me. I asked of him an evil act, but he proved continent, but if he do not my behest he verily shall be imprisoned, and verily shall be of those brought low.'),
  ('en.pickthall', 12, 33, 'He said: O my Lord! Prison is more dear than that unto which they urge me, and if Thou fend not off their wiles from me I shall incline unto them and become of the foolish.'),
  ('en.pickthall', 12, 34, 'So his Lord heard his prayer and fended off their wiles from him. Lo! He is Hearer, Knower.'),
  ('en.pickthall', 12, 35, 'And it seemed good to them (the men-folk) after they had seen the signs (of his innocence) to imprison him for a time.'),
  ('en.pickthall', 12, 36, 'And two young men went to prison with him. One of them said: I dreamed that I was pressing wine. The other said: I dreamed that I was carrying upon my head bread whereof the birds were eating. Announce unto us the interpretation, for we see thee of those good (at interpretation).'),
  ('en.pickthall', 12, 37, 'He said: The food which ye are given (daily) shall not come unto you but I shall tell you the interpretation ere it cometh unto you. This is of that which my Lord hath taught me. Lo! I have forsaken the religion of folk who believe not in Allah and are disbelievers in the Hereafter.'),
  ('en.pickthall', 12, 38, 'And I have followed the religion of my fathers, Abraham and Isaac and Jacob. It never was for us to attribute aught as partner to Allah. This is of the bounty of Allah unto us (the seed of Abraham) and unto mankind; but most men give not thanks.'),
  ('en.pickthall', 12, 39, 'O my fellow-prisoners! Are divers lords better, or Allah the One, Almighty?'),
  ('en.pickthall', 12, 40, 'Those whom ye worship beside Him are but names which ye have named, ye and your fathers. Allah hath revealed no sanction for them. The decision rests with Allah only, Who hath commanded you that ye worship none save Him. This is the right religion, but most men know not.'),
  ('en.pickthall', 12, 41, 'O my two fellow-prisoners! As for one of you, he will pour out wine for his lord to drink; and as for the other, he will be crucified so that the birds will eat from his head. Thus is the case judged concerning which ye did inquire.'),
  ('en.pickthall', 12, 42, 'And he said unto him of the twain who he knew would be released: Mention me in the presence of thy lord. But Satan caused him to forget to mention it to his lord, so he (Joseph) stayed in prison for some years.'),
  ('en.pickthall', 12, 43, 'And the king said: Lo! I saw in a dream seven fat kine which seven lean were eating, and seven green ears of corn and other (seven) dry. O notables! Expound for me my vision, if ye can interpret dreams.'),
  ('en.pickthall', 12, 44, 'They answered: Jumbled dreams! And we are not knowing in the interpretation of dreams.'),
  ('en.pickthall', 12, 45, 'And he of the two who was released, and (now) at length remembered, said: I am going to announce unto you the interpretation, therefore send me forth.'),
  ('en.pickthall', 12, 46, '(And when he came to Joseph in the prison, he exclaimed): Joseph! O thou truthful one! Expound for us the seven fat kine which seven lean were eating and the seven green ears of corn and other (seven) dry, that I may return unto the people, so that they may know.'),
  ('en.pickthall', 12, 47, 'He said: Ye shall sow seven years as usual, but that which ye reap, leave it in the ear, all save a little which ye eat.'),
  ('en.pickthall', 12, 48, 'Then after that will come seven hard years which will devour all that ye have prepared for them, save a little of that which ye have stored.'),
  ('en.pickthall', 12, 49, 'Then, after that, will come a year when the people will have plenteous crops and when they will press (wine and oil).'),
  ('en.pickthall', 12, 50, 'And the king said: Bring him unto me. And when the messenger came unto him, he (Joseph) said: Return unto thy lord and ask him what was the case of the women who cut their hands. Lo! my Lord knoweth their guile.'),
  ('en.pickthall', 12, 51, 'He (the king) (then sent for those women and) said: What happened when ye asked an evil act of Joseph? They answered: Allah Blameless! We know no evil of him. Said the wife of the ruler: Now the truth is out. I asked of him an evil act, and he is surely of the truthful.'),
  ('en.pickthall', 12, 52, '(Then Joseph said: I asked for) this, that he (my lord) may know that I betrayed him not in secret, and that surely Allah guideth not the snare of the betrayers.'),
  ('en.pickthall', 12, 53, 'I do not exculpate myself. Lo! the (human) soul enjoineth unto evil, save that whereon my Lord hath mercy. Lo! my Lord is Forgiving, Merciful.'),
  ('en.pickthall', 12, 54, 'And the king said: Bring him unto me that I may attach him to my person. And when he had talked with him he said: Lo! thou art to-day in our presence established and trusted.'),
  ('en.pickthall', 12, 55, 'He said: Set me over the storehouses of the land. Lo! I am a skilled custodian.'),
  ('en.pickthall', 12, 56, 'Thus gave We power to Joseph in the land. He was the owner of it where he pleased. We reach with Our mercy whom We will. We lose not the reward of the good.'),
  ('en.pickthall', 12, 57, 'And the reward of the Hereafter is better, for those who believe and ward off (evil).'),
  ('en.pickthall', 12, 58, 'And Joseph\'s brethren came and presented themselves before him, and he knew them but they knew him not.'),
  ('en.pickthall', 12, 59, 'And when he provided them with their provision he said: Bring unto me a brother of yours from your father. See ye not that I fill up the measure and I am the best of hosts?'),
  ('en.pickthall', 12, 60, 'And if ye bring him not unto me, then there shall be no measure for you with me, nor shall ye draw near.'),
  ('en.pickthall', 12, 61, 'They said: We will try to win him from his father: that we will surely do.'),
  ('en.pickthall', 12, 62, 'He said unto his young men: Place their merchandise in their saddlebags, so that they may know it when they go back to their folk, and so will come again.'),
  ('en.pickthall', 12, 63, 'So when they went back to their father they said: O our father! The measure is denied us, so send with us our brother that we may obtain the measure, surely we will guard him well.'),
  ('en.pickthall', 12, 64, 'He said: Can I entrust him to you save as I entrusted his brother to you aforetime? Allah is better at guarding, and He is the Most Merciful of those who show mercy.'),
  ('en.pickthall', 12, 65, 'And when they opened their belongings they discovered that their merchandise had been returned to them. They said: O our father! What (more) can we ask? Here is our merchandise returned to us. We shall get provision for our folk and guard our brother, and we shall have the extra measure of a camel (load). This (that we bring now) is a light measure.'),
  ('en.pickthall', 12, 66, 'He said: I will not send him with you till ye give me an undertaking in the name of Allah that ye will bring him back to me, unless ye are surrounded. And when they gave him their undertaking he said: Allah is the Warden over what we say.'),
  ('en.pickthall', 12, 67, 'And he said: O my sons! Go not in by one gate; go in by different gates. I can naught avail you as against Allah. Lo! the decision rests with Allah only. In Him do I put my trust, and in Him let all the trusting put their trust.'),
  ('en.pickthall', 12, 68, 'And when they entered in the manner which their father had enjoined, it would have naught availed them as against Allah; it was but a need of Jacob\'s soul which he thus satisfied; and lo! he was a lord of knowledge because We had taught him; but most of mankind know not.'),
  ('en.pickthall', 12, 69, 'And when they went in before Joseph, he took his brother unto him, saying: Lo! I, even I, am thy brother, therefore sorrow not for what they did.'),
  ('en.pickthall', 12, 70, 'And when he provided them with their provision, he put the drinking-cup in his brother\'s saddlebag, and then a crier cried: O camel-riders! Lo! ye are surely thieves!'),
  ('en.pickthall', 12, 71, 'They cried, coming toward them: What is it ye have lost?'),
  ('en.pickthall', 12, 72, 'They said: We have lost the king\'s cup, and he who bringeth it shall have a camel-load, and I (said Joseph) am answerable for it.'),
  ('en.pickthall', 12, 73, 'They said: By Allah, well ye know we came not to do evil in the land, and are no thieves.'),
  ('en.pickthall', 12, 74, 'They said: And what shall be the penalty for it, if ye prove liars?'),
  ('en.pickthall', 12, 75, 'They said: The penalty for it! He in whose bag (the cup) is found, he is the penalty for it. Thus we requite wrong-doers.'),
  ('en.pickthall', 12, 76, 'Then he (Joseph) began the search with their bags before his brother\'s bag, then he produced it from his brother\'s bag. Thus did We contrive for Joseph. He could not have taken his brother according to the king\'s law unless Allah willed. We raise by grades (of mercy) whom We will, and over every lord of knowledge there is one more knowing.'),
  ('en.pickthall', 12, 77, 'They said: If he stealeth, a brother of his stole before. But Joseph kept it secret in his soul and revealed it not unto them. He said (within himself): Ye are in worse case, and Allah knoweth best (the truth of) that which ye allege.'),
  ('en.pickthall', 12, 78, 'They said: O ruler of the land! Lo! he hath a very aged father, so take one of us instead of him. Lo! we behold thee of those who do kindness.'),
  ('en.pickthall', 12, 79, 'He said: Allah forbid that we should seize save him with whom we found our property; then truly we should be wrong-doers.'),
  ('en.pickthall', 12, 80, 'So, When they despaired of (moving) him, they conferred together apart. The eldest of them said: Know ye not how your father took an undertaking from you in Allah\'s name and how ye failed in the case of Joseph aforetime? Therefore I shall not go forth from the land until my father giveth leave or Allah judgeth for me. He is the Best of Judges.'),
  ('en.pickthall', 12, 81, 'Return unto your father and say: O our father! Lo! thy son hath stolen. We testify only to that which we know; we are not guardians of the Unseen.'),
  ('en.pickthall', 12, 82, 'Ask the township where we were, and the caravan with which we travelled hither. Lo! we speak the truth.'),
  ('en.pickthall', 12, 83, '(And when they came unto their father and had spoken thus to him) he said: Nay, but your minds have beguiled you into something. (My course is) comely patience! It may be that Allah will bring them all unto me. Lo! He, only He, is the Knower, the Wise.'),
  ('en.pickthall', 12, 84, 'And he turned away from them and said: Alas, my grief for Joseph! And his eyes were whitened with the sorrow that he was suppressing.'),
  ('en.pickthall', 12, 85, 'They said: By Allah, thou wilt never cease remembering Joseph till thy health is ruined or thou art of those who perish!'),
  ('en.pickthall', 12, 86, 'He said: I expose my distress and anguish only unto Allah, and I know from Allah that which ye know not.'),
  ('en.pickthall', 12, 87, 'Go, O my sons, and ascertain concerning Joseph and his brother, and despair not of the Spirit of Allah. Lo! none despaireth of the Spirit of Allah save disbelieving folk.'),
  ('en.pickthall', 12, 88, 'And when they came (again) before him (Joseph) they said: O ruler! Misfortune hath touched us and our folk, and we bring but poor merchandise, so fill for us the measure and be charitable unto us. Lo! Allah will requite the charitable,'),
  ('en.pickthall', 12, 89, 'He said: Know ye what ye did unto Joseph and his brother in your ignorance?'),
  ('en.pickthall', 12, 90, 'They said: Is it indeed thou who art Joseph? He said: I am Joseph and this is my brother. Allah hath shown us favour. Lo! he who wardeth off (evil) and endureth (findeth favour); for lo! Allah loseth not the wages of the kindly.'),
  ('en.pickthall', 12, 91, 'They said: By Allah, verily Allah hath preferred thee above us, and we were indeed sinful.'),
  ('en.pickthall', 12, 92, 'He said: Have no fear this day! May Allah forgive you, and He is the Most Merciful of those who show mercy.'),
  ('en.pickthall', 12, 93, 'Go with this shirt of mine and lay it on my father\'s face, he will become (again) a seer; and come to me with all your folk.'),
  ('en.pickthall', 12, 94, 'When the caravan departed their father had said: Truly I am conscious of the breath of Joseph, though ye call me dotard.'),
  ('en.pickthall', 12, 95, '(Those around him) said: By Allah, lo! thou art in thine old aberration.'),
  ('en.pickthall', 12, 96, 'Then, when the bearer of glad tidings came, he laid it on his face and he became a seer once more. He said: Said I not unto you that I know from Allah that which ye know not?'),
  ('en.pickthall', 12, 97, 'They said: O our father! Ask forgiveness of our sins for us, for lo! we were sinful.'),
  ('en.pickthall', 12, 98, 'He said: I shall ask forgiveness for you of my Lord. Lo! He is the Forgiving, the Merciful.'),
  ('en.pickthall', 12, 99, 'And when they came in before Joseph, he took his parents unto him, and said: Come into Egypt safe, if Allah will!'),
  ('en.pickthall', 12, 100, 'And he placed his parents on the dais and they fell down before him prostrate, and he said: O my father! This is the interpretation of my dream of old. My Lord hath made it true, and He hath shown me kindness, since He took me out of the prison and hath brought you from the desert after Satan had made strife between me and my brethren. Lo! my Lord is tender unto whom He will. He is the Knower, the Wise.'),
  ('en.pickthall', 12, 101, 'O my Lord! Thou hast given me (something) of sovereignty and hast taught me (something) of the interpretation of events - Creator of the heavens and the earth! Thou art my Protecting Guardian in the world and the Hereafter. Make me to die muslim (unto Thee), and join me to the righteous.'),
  ('en.pickthall', 12, 102, 'This is of the tidings of the Unseen which We inspire in thee (Muhammad). Thou wast not present with them when they fixed their plan and they were scheming.'),
  ('en.pickthall', 12, 103, 'And though thou try much, most men will not believe.'),
  ('en.pickthall', 12, 104, 'Thou askest them no fee for it. It is naught else than a reminder unto the peoples.'),
  ('en.pickthall', 12, 105, 'How many a portent is there in the heavens and the earth which they pass by with face averted!'),
  ('en.pickthall', 12, 106, 'And most of them believe not in Allah except that they attribute partners (unto Him).'),
  ('en.pickthall', 12, 107, 'Deem they themselves secure from the coming on them of a pall of Allah\'s punishment, or the coming of the Hour suddenly while they are unaware?'),
  ('en.pickthall', 12, 108, 'Say: This is my Way: I call on Allah with sure knowledge. I and whosoever followeth me - Glory be to Allah! - and I am not of the idolaters.'),
  ('en.pickthall', 12, 109, 'We sent not before thee (any messengers) save men whom We inspired from among the folk of the townships - Have they not travelled in the land and seen the nature of the consequence for those who were before them? And verily the abode of the Hereafter, for those who ward off (evil), is best. Have ye then no sense? -'),
  ('en.pickthall', 12, 110, 'Till, when the messengers despaired and thought that they were denied, then came unto them Our help, and whom We would was saved. And Our wrath cannot be warded from the guilty.'),
  ('en.pickthall', 12, 111, 'In their history verily there is a lesson for men of understanding. It is no invented story but a confirmation of the existing (Scripture) and a detailed explanation of everything, and a guidance and a mercy for folk who believe.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 12, 1, 'A. L. R. These are the symbols (or Verses) of the perspicuous Book.'),
  ('en.yusufali', 12, 2, 'We have sent it down as an Arabic Qur\'an, in order that ye may learn wisdom.'),
  ('en.yusufali', 12, 3, 'We do relate unto thee the most beautiful of stories, in that We reveal to thee this (portion of the) Qur\'an: before this, thou too was among those who knew it not.'),
  ('en.yusufali', 12, 4, 'Behold! Joseph said to his father: "O my father! I did see eleven stars and the sun and the moon: I saw them prostrate themselves to me!"'),
  ('en.yusufali', 12, 5, 'Said (the father): "My (dear) little son! relate not thy vision to thy brothers, lest they concoct a plot against thee: for Satan is to man an avowed enemy!'),
  ('en.yusufali', 12, 6, '"Thus will thy Lord choose thee and teach thee the interpretation of stories (and events) and perfect His favour to thee and to the posterity of Jacob - even as He perfected it to thy fathers Abraham and Isaac aforetime! for Allah is full of knowledge and wisdom."'),
  ('en.yusufali', 12, 7, 'Verily in Joseph and his brethren are signs (or symbols) for seekers (after Truth).'),
  ('en.yusufali', 12, 8, 'They said: "Truly Joseph and his brother are loved more by our father than we: But we are a goodly body! really our father is obviously wandering (in his mind)!'),
  ('en.yusufali', 12, 9, '"Slay ye Joseph or cast him out to some (unknown) land, that so the favour of your father may be given to you alone: (there will be time enough) for you to be righteous after that!"'),
  ('en.yusufali', 12, 10, 'Said one of them: "Slay not Joseph, but if ye must do something, throw him down to the bottom of the well: he will be picked up by some caravan of travellers."'),
  ('en.yusufali', 12, 11, 'They said: "O our father! why dost thou not trust us with Joseph,- seeing we are indeed his sincere well-wishers?'),
  ('en.yusufali', 12, 12, '"Send him with us tomorrow to enjoy himself and play, and we shall take every care of him."'),
  ('en.yusufali', 12, 13, '(Jacob) said: "Really it saddens me that ye should take him away: I fear lest the wolf should devour him while ye attend not to him."'),
  ('en.yusufali', 12, 14, 'They said: "If the wolf were to devour him while we are (so large) a party, then should we indeed (first) have perished ourselves!"'),
  ('en.yusufali', 12, 15, 'So they did take him away, and they all agreed to throw him down to the bottom of the well: and We put into his heart (this Message): \'Of a surety thou shalt (one day) tell them the truth of this their affair while they know (thee) not\''),
  ('en.yusufali', 12, 16, 'Then they came to their father in the early part of the night, weeping.'),
  ('en.yusufali', 12, 17, 'They said: "O our father! We went racing with one another, and left Joseph with our things; and the wolf devoured him.... But thou wilt never believe us even though we tell the truth."'),
  ('en.yusufali', 12, 18, 'They stained his shirt with false blood. He said: "Nay, but your minds have made up a tale (that may pass) with you, (for me) patience is most fitting: Against that which ye assert, it is Allah (alone) Whose help can be sought"..'),
  ('en.yusufali', 12, 19, 'Then there came a caravan of travellers: they sent their water-carrier (for water), and he let down his bucket (into the well)... He said: "Ah there! Good news! Here is a (fine) young man!" So they concealed him as a treasure! But Allah knoweth well all that they do!'),
  ('en.yusufali', 12, 20, 'The (Brethren) sold him for a miserable price, for a few dirhams counted out: in such low estimation did they hold him!'),
  ('en.yusufali', 12, 21, 'The man in Egypt who bought him, said to his wife: "Make his stay (among us) honourable: may be he will bring us much good, or we shall adopt him as a son." Thus did We establish Joseph in the land, that We might teach him the interpretation of stories (and events). And Allah hath full power and control over His affairs; but most among mankind know it not.'),
  ('en.yusufali', 12, 22, 'When Joseph attained His full manhood, We gave him power and knowledge: thus do We reward those who do right.'),
  ('en.yusufali', 12, 23, 'But she in whose house he was, sought to seduce him from his (true) self: she fastened the doors, and said: "Now come, thou (dear one)!" He said: "Allah forbid! truly (thy husband) is my lord! he made my sojourn agreeable! truly to no good come those who do wrong!"'),
  ('en.yusufali', 12, 24, 'And (with passion) did she desire him, and he would have desired her, but that he saw the evidence of his Lord: thus (did We order) that We might turn away from him (all) evil and shameful deeds: for he was one of Our servants, sincere and purified.'),
  ('en.yusufali', 12, 25, 'So they both raced each other to the door, and she tore his shirt from the back: they both found her lord near the door. She said: "What is the (fitting) punishment for one who formed an evil design against thy wife, but prison or a grievous chastisement?"'),
  ('en.yusufali', 12, 26, 'He said: "It was she that sought to seduce me - from my (true) self." And one of her household saw (this) and bore witness, (thus):- "If it be that his shirt is rent from the front, then is her tale true, and he is a liar!'),
  ('en.yusufali', 12, 27, '"But if it be that his shirt is torn from the back, then is she the liar, and he is telling the truth!"'),
  ('en.yusufali', 12, 28, 'So when he saw his shirt,- that it was torn at the back,- (her husband) said: "Behold! It is a snare of you women! truly, mighty is your snare!'),
  ('en.yusufali', 12, 29, '"O Joseph, pass this over! (O wife), ask forgiveness for thy sin, for truly thou hast been at fault!"'),
  ('en.yusufali', 12, 30, 'Ladies said in the City: "The wife of the (great) \'Aziz is seeking to seduce her slave from his (true) self: Truly hath he inspired her with violent love: we see she is evidently going astray."'),
  ('en.yusufali', 12, 31, 'When she heard of their malicious talk, she sent for them and prepared a banquet for them: she gave each of them a knife: and she said (to Joseph), "Come out before them." When they saw him, they did extol him, and (in their amazement) cut their hands: they said, "Allah preserve us! no mortal is this! this is none other than a noble angel!"'),
  ('en.yusufali', 12, 32, 'She said: "There before you is the man about whom ye did blame me! I did seek to seduce him from his (true) self but he did firmly save himself guiltless!.... and now, if he doth not my bidding, he shall certainly be cast into prison, and (what is more) be of the company of the vilest!"'),
  ('en.yusufali', 12, 33, 'He said: "O my Lord! the prison is more to my liking than that to which they invite me: Unless Thou turn away their snare from me, I should (in my youthful folly) feel inclined towards them and join the ranks of the ignorant."'),
  ('en.yusufali', 12, 34, 'So his Lord hearkened to him (in his prayer), and turned away from him their snare: Verily He heareth and knoweth (all things).'),
  ('en.yusufali', 12, 35, 'Then it occurred to the men, after they had seen the signs, (that it was best) to imprison him for a time.'),
  ('en.yusufali', 12, 36, 'Now with him there came into the prison two young men. Said one of them: "I see myself (in a dream) pressing wine." said the other: "I see myself (in a dream) carrying bread on my head, and birds are eating, thereof." "Tell us" (they said) "The truth and meaning thereof: for we see thou art one that doth good (to all)."'),
  ('en.yusufali', 12, 37, 'He said: "Before any food comes (in due course) to feed either of you, I will surely reveal to you the truth and meaning of this ere it befall you: that is part of the (duty) which my Lord hath taught me. I have (I assure you) abandoned the ways of a people that believe not in Allah and that (even) deny the Hereafter.'),
  ('en.yusufali', 12, 38, '"And I follow the ways of my fathers,- Abraham, Isaac, and Jacob; and never could we attribute any partners whatever to Allah: that (comes) of the grace of Allah to us and to mankind: yet most men are not grateful.'),
  ('en.yusufali', 12, 39, '"O my two companions of the prison! (I ask you): are many lords differing among themselves better, or the One Allah, Supreme and Irresistible?'),
  ('en.yusufali', 12, 40, '"If not Him, ye worship nothing but names which ye have named,- ye and your fathers,- for which Allah hath sent down no authority: the command is for none but Allah: He hath commanded that ye worship none but Him: that is the right religion, but most men understand not...'),
  ('en.yusufali', 12, 41, '"O my two companions of the prison! As to one of you, he will pour out the wine for his lord to drink: as for the other, he will hang from the cross, and the birds will eat from off his head. (so) hath been decreed that matter whereof ye twain do enquire"...'),
  ('en.yusufali', 12, 42, 'And of the two, to that one whom he consider about to be saved, he said: "Mention me to thy lord." But Satan made him forget to mention him to his lord: and (Joseph) lingered in prison a few (more) years.'),
  ('en.yusufali', 12, 43, 'The king (of Egypt) said: "I do see (in a vision) seven fat kine, whom seven lean ones devour, and seven green ears of corn, and seven (others) withered. O ye chiefs! Expound to me my vision if it be that ye can interpret visions."'),
  ('en.yusufali', 12, 44, 'They said: "A confused medley of dreams: and we are not skilled in the interpretation of dreams."'),
  ('en.yusufali', 12, 45, 'But the man who had been released, one of the two (who had been in prison) and who now bethought him after (so long) a space of time, said: "I will tell you the truth of its interpretation: send ye me (therefore)."'),
  ('en.yusufali', 12, 46, '"O Joseph!" (he said) "O man of truth! Expound to us (the dream) of seven fat kine whom seven lean ones devour, and of seven green ears of corn and (seven) others withered: that I may return to the people, and that they may understand."'),
  ('en.yusufali', 12, 47, '(Joseph) said: "For seven years shall ye diligently sow as is your wont: and the harvests that ye reap, ye shall leave them in the ear,- except a little, of which ye shall eat.'),
  ('en.yusufali', 12, 48, '"Then will come after that (period) seven dreadful (years), which will devour what ye shall have laid by in advance for them,- (all) except a little which ye shall have (specially) guarded.'),
  ('en.yusufali', 12, 49, '"Then will come after that (period) a year in which the people will have abundant water, and in which they will press (wine and oil)."'),
  ('en.yusufali', 12, 50, 'So the king said: "Bring ye him unto me." But when the messenger came to him, (Joseph) said: "Go thou back to thy lord, and ask him, \'What is the state of mind of the ladies who cut their hands\'? For my Lord is certainly well aware of their snare."'),
  ('en.yusufali', 12, 51, '(The king) said (to the ladies): "What was your affair when ye did seek to seduce Joseph from his (true) self?" The ladies said: "Allah preserve us! no evil know we against him!" Said the \'Aziz\'s wife: "Now is the truth manifest (to all): it was I who sought to seduce him from his (true) self: He is indeed of those who are (ever) true (and virtuous).'),
  ('en.yusufali', 12, 52, '"This (say I), in order that He may know that I have never been false to him in his absence, and that Allah will never guide the snare of the false ones.'),
  ('en.yusufali', 12, 53, '"Nor do I absolve my own self (of blame): the (human) soul is certainly prone to evil, unless my Lord do bestow His Mercy: but surely my Lord is Oft-forgiving, Most Merciful."'),
  ('en.yusufali', 12, 54, 'So the king said: "Bring him unto me; I will take him specially to serve about my own person." Therefore when he had spoken to him, he said: "Be assured this day, thou art, before our own presence, with rank firmly established, and fidelity fully proved!'),
  ('en.yusufali', 12, 55, '(Joseph) said: "Set me over the store-houses of the land: I will indeed guard them, as one that knows (their importance)."'),
  ('en.yusufali', 12, 56, 'Thus did We give established power to Joseph in the land, to take possession therein as, when, or where he pleased. We bestow of our Mercy on whom We please, and We suffer not, to be lost, the reward of those who do good.'),
  ('en.yusufali', 12, 57, 'But verily the reward of the Hereafter is the best, for those who believe, and are constant in righteousness.'),
  ('en.yusufali', 12, 58, 'Then came Joseph\'s brethren: they entered his presence, and he knew them, but they knew him not.'),
  ('en.yusufali', 12, 59, 'And when he had furnished them forth with provisions (suitable) for them, he said: "Bring unto me a brother ye have, of the same father as yourselves, (but a different mother): see ye not that I pay out full measure, and that I do provide the best hospitality?'),
  ('en.yusufali', 12, 60, '"Now if ye bring him not to me, ye shall have no measure (of corn) from me, nor shall ye (even) come near me."'),
  ('en.yusufali', 12, 61, 'They said: "We shall certainly seek to get our wish about him from his father: Indeed we shall do it."'),
  ('en.yusufali', 12, 62, 'And (Joseph) told his servants to put their stock-in-trade (with which they had bartered) into their saddle-bags, so they should know it only when they returned to their people, in order that they might come back.'),
  ('en.yusufali', 12, 63, 'Now when they returned to their father, they said: "O our father! No more measure of grain shall we get (unless we take our brother): So send our brother with us, that we may get our measure; and we will indeed take every care of him."'),
  ('en.yusufali', 12, 64, 'He said: "Shall I trust you with him with any result other than when I trusted you with his brother aforetime? But Allah is the best to take care (of him), and He is the Most Merciful of those who show mercy!"'),
  ('en.yusufali', 12, 65, 'Then when they opened their baggage, they found their stock-in-trade had been returned to them. They said: "O our father! What (more) can we desire? this our stock-in-trade has been returned to us: so we shall get (more) food for our family; We shall take care of our brother; and add (at the same time) a full camel\'s load (of grain to our provisions). This is but a small quantity.'),
  ('en.yusufali', 12, 66, '(Jacob) said: "Never will I send him with you until ye swear a solemn oath to me, in Allah\'s name, that ye will be sure to bring him back to me unless ye are yourselves hemmed in (and made powerless). And when they had sworn their solemn oath, he said: "Over all that we say, be Allah the witness and guardian!"'),
  ('en.yusufali', 12, 67, 'Further he said: "O my sons! enter not all by one gate: enter ye by different gates. Not that I can profit you aught against Allah (with my advice): None can command except Allah: On Him do I put my trust: and let all that trust put their trust on Him."'),
  ('en.yusufali', 12, 68, 'And when they entered in the manner their father had enjoined, it did not profit them in the least against (the plan of) Allah: It was but a necessity of Jacob\'s soul, which he discharged. For he was, by our instruction, full of knowledge (and experience): but most men know not.'),
  ('en.yusufali', 12, 69, 'Now when they came into Joseph\'s presence, he received his (full) brother to stay with him. He said (to him): "Behold! I am thy (own) brother; so grieve not at aught of their doings."'),
  ('en.yusufali', 12, 70, 'At length when he had furnished them forth with provisions (suitable) for them, he put the drinking cup into his brother\'s saddle-bag. Then shouted out a crier: "O ye (in) the caravan! behold! ye are thieves, without doubt!"'),
  ('en.yusufali', 12, 71, 'They said, turning towards them: "What is it that ye miss?"'),
  ('en.yusufali', 12, 72, 'They said: "We miss the great beaker of the king; for him who produces it, is (the reward of) a camel load; I will be bound by it."'),
  ('en.yusufali', 12, 73, '(The brothers) said: "By Allah! well ye know that we came not to make mischief in the land, and we are no thieves!"'),
  ('en.yusufali', 12, 74, '(The Egyptians) said: "What then shall be the penalty of this, if ye are (proved) to have lied?"'),
  ('en.yusufali', 12, 75, 'They said: "The penalty should be that he in whose saddle-bag it is found, should be held (as bondman) to atone for the (crime). Thus it is we punish the wrong-doers!"'),
  ('en.yusufali', 12, 76, 'So he began (the search) with their baggage, before (he came to) the baggage of his brother: at length he brought it out of his brother\'s baggage. Thus did We plan for Joseph. He could not take his brother by the law of the king except that Allah willed it (so). We raise to degrees (of wisdom) whom We please: but over all endued with knowledge is one, the All-Knowing.'),
  ('en.yusufali', 12, 77, 'They said: "If he steals, there was a brother of his who did steal before (him)." But these things did Joseph keep locked in his heart, revealing not the secrets to them. He (simply) said (to himself): "Ye are the worse situated; and Allah knoweth best the truth of what ye assert!"'),
  ('en.yusufali', 12, 78, 'They said: "O exalted one! Behold! he has a father, aged and venerable, (who will grieve for him); so take one of us in his place; for we see that thou art (gracious) in doing good."'),
  ('en.yusufali', 12, 79, 'He said: "Allah forbid that we take other than him with whom we found our property: indeed (if we did so), we should be acting wrongfully.'),
  ('en.yusufali', 12, 80, 'Now when they saw no hope of his (yielding), they held a conference in private. The leader among them said: "Know ye not that your father did take an oath from you in Allah\'s name, and how, before this, ye did fail in your duty with Joseph? Therefore will I not leave this land until my father permits me, or Allah commands me; and He is the best to command.'),
  ('en.yusufali', 12, 81, '"Turn ye back to your father, and say, \'O our father! behold! thy son committed theft! we bear witness only to what we know, and we could not well guard against the unseen!'),
  ('en.yusufali', 12, 82, '"\'Ask at the town where we have been and the caravan in which we returned, and (you will find) we are indeed telling the truth.\'"'),
  ('en.yusufali', 12, 83, 'Jacob said: "Nay, but ye have yourselves contrived a story (good enough) for you. So patience is most fitting (for me). Maybe Allah will bring them (back) all to me (in the end). For He is indeed full of knowledge and wisdom."'),
  ('en.yusufali', 12, 84, 'And he turned away from them, and said: "How great is my grief for Joseph!" And his eyes became white with sorrow, and he fell into silent melancholy.'),
  ('en.yusufali', 12, 85, 'They said: "By Allah! (never) wilt thou cease to remember Joseph until thou reach the last extremity of illness, or until thou die!"'),
  ('en.yusufali', 12, 86, 'He said: "I only complain of my distraction and anguish to Allah, and I know from Allah that which ye know not...'),
  ('en.yusufali', 12, 87, '"O my sons! go ye and enquire about Joseph and his brother, and never give up hope of Allah\'s Soothing Mercy: truly no one despairs of Allah\'s Soothing Mercy, except those who have no faith."'),
  ('en.yusufali', 12, 88, 'Then, when they came (back) into (Joseph\'s) presence they said: "O exalted one! distress has seized us and our family: we have (now) brought but scanty capital: so pay us full measure, (we pray thee), and treat it as charity to us: for Allah doth reward the charitable."'),
  ('en.yusufali', 12, 89, 'He said: "Know ye how ye dealt with Joseph and his brother, not knowing (what ye were doing)?"'),
  ('en.yusufali', 12, 90, 'They said: "Art thou indeed Joseph?" He said, "I am Joseph, and this is my brother: Allah has indeed been gracious to us (all): behold, he that is righteous and patient,- never will Allah suffer the reward to be lost, of those who do right."'),
  ('en.yusufali', 12, 91, 'They said: "By Allah! indeed has Allah preferred thee above us, and we certainly have been guilty of sin!"'),
  ('en.yusufali', 12, 92, 'He said: "This day let no reproach be (cast) on you: Allah will forgive you, and He is the Most Merciful of those who show mercy!'),
  ('en.yusufali', 12, 93, '"Go with this my shirt, and cast it over the face of my father: he will come to see (clearly). Then come ye (here) to me together with all your family."'),
  ('en.yusufali', 12, 94, 'When the caravan left (Egypt), their father said: "I do indeed scent the presence of Joseph: Nay, think me not a dotard."'),
  ('en.yusufali', 12, 95, 'They said: "By Allah! truly thou art in thine old wandering mind."'),
  ('en.yusufali', 12, 96, 'Then when the bearer of the good news came, He cast (the shirt) over his face, and he forthwith regained clear sight. He said: "Did I not say to you, \'I know from Allah that which ye know not?\'"'),
  ('en.yusufali', 12, 97, 'They said: "O our father! ask for us forgiveness for our sins, for we were truly at fault."'),
  ('en.yusufali', 12, 98, 'He said: "Soon will I ask my Lord for forgiveness for you: for he is indeed Oft-Forgiving, Most Merciful."'),
  ('en.yusufali', 12, 99, 'Then when they entered the presence of Joseph, he provided a home for his parents with himself, and said: "Enter ye Egypt (all) in safety if it please Allah."'),
  ('en.yusufali', 12, 100, 'And he raised his parents high on the throne (of dignity), and they fell down in prostration, (all) before him. He said: "O my father! this is the fulfilment of my vision of old! Allah hath made it come true! He was indeed good to me when He took me out of prison and brought you (all here) out of the desert, (even) after Satan had sown enmity between me and my brothers. Verily my Lord understandeth best the mysteries of all that He planneth to do, for verily He is full of knowledge and wisdom.'),
  ('en.yusufali', 12, 101, '"O my Lord! Thou hast indeed bestowed on me some power, and taught me something of the interpretation of dreams and events,- O Thou Creator of the heavens and the earth! Thou art my Protector in this world and in the Hereafter. Take Thou my soul (at death) as one submitting to Thy will (as a Muslim), and unite me with the righteous."'),
  ('en.yusufali', 12, 102, 'Such is one of the stories of what happened unseen, which We reveal by inspiration unto thee; nor wast thou (present) with them then when they concerted their plans together in the process of weaving their plots.'),
  ('en.yusufali', 12, 103, 'Yet no faith will the greater part of mankind have, however ardently thou dost desire it.'),
  ('en.yusufali', 12, 104, 'And no reward dost thou ask of them for this: it is no less than a message for all creatures.'),
  ('en.yusufali', 12, 105, 'And how many Signs in the heavens and the earth do they pass by? Yet they turn (their faces) away from them!'),
  ('en.yusufali', 12, 106, 'And most of them believe not in Allah without associating (other as partners) with Him!'),
  ('en.yusufali', 12, 107, 'Do they then feel secure from the coming against them of the covering veil of the wrath of Allah,- or of the coming against them of the (final) Hour all of a sudden while they perceive not?'),
  ('en.yusufali', 12, 108, 'Say thou: "This is my way: I do invite unto Allah,- on evidence clear as the seeing with one\'s eyes,- I and whoever follows me. Glory to Allah! and never will I join gods with Allah!"'),
  ('en.yusufali', 12, 109, 'Nor did We send before thee (as messengers) any but men, whom we did inspire,- (men) living in human habitations. Do they not travel through the earth, and see what was the end of those before them? But the home of the hereafter is best, for those who do right. Will ye not then understand?'),
  ('en.yusufali', 12, 110, '(Respite will be granted) until, when the messengers give up hope (of their people) and (come to) think that they were treated as liars, there reaches them Our help, and those whom We will are delivered into safety. But never will be warded off our punishment from those who are in sin.'),
  ('en.yusufali', 12, 111, 'There is, in their stories, instruction for men endued with understanding. It is not a tale invented, but a confirmation of what went before it,- a detailed exposition of all things, and a guide and a mercy to any such as believe.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 12, 1, 'Alif-Laaam-Raa; tilka Aayaatul Kitaabil Mubeen'),
  ('en.transliteration', 12, 2, 'Innaaa anzalnaahu quraanan \'Arabiyyal la \'allakum ta\'qiloon'),
  ('en.transliteration', 12, 3, 'Nahnu naqussu \'alaika ahsanal qasasi bimaaa awhainaaa ilaika haazal quraana wa in kunta min qablihee laminal ghaafileen'),
  ('en.transliteration', 12, 4, 'Iz qaala Yoosufu li abeehi yaaa abati innee ra aytu ahada \'ashara kawkabanw wash shamsa walqamara ra aytuhum lee saajideen'),
  ('en.transliteration', 12, 5, 'Qaala yaa bunaiya laa taqsus ru\'yaaka \'alaaa ikhwatika fayakeedoo laka kaidaa; innash Shaitaana lil insaani \'aduwwum mubeen'),
  ('en.transliteration', 12, 6, 'Wa kazaalika yajtabeeka rabbuka wa yu\'allimuka min taaweelil ahaadeesi wa yutimmu ni\'matahoo \'alaika wa \'alaaa Aali Ya\'qooba kamaaa atammahaa \'alaaa abawaika min qablu Ibraaheema wa Ishaaq; inna Rabbaka \'Aleemun hakeem'),
  ('en.transliteration', 12, 7, 'Laqad kaana fee Yoosufa wa ikhwatiheee Aayaatul lissaaa\'ileen'),
  ('en.transliteration', 12, 8, 'Iz qaaloo la Yoosufu wa akhoohu ahabbu ilaaa Abeenaa minnaa wa nahnu \'usbah; inna abaanaa lafee dalaalim mubeen'),
  ('en.transliteration', 12, 9, 'Uqtuloo Yoosufa awitra hoohu ardany yakhlu lakum wajhu abeekum wa takoonoo mim ba\'dihee qawman saaliheen'),
  ('en.transliteration', 12, 10, 'Qaalaa qaaa\'ilum minhum laa taqtuloo Yoosufa wa alqoohu fee ghayaabatil jubbi yaltaqithu badus sai yaarati in kuntum faa \'ileen'),
  ('en.transliteration', 12, 11, 'Qaaloo yaaa abaanaa maa laka laa taamannaa \'alaa Yoosufa wa innaa lahoo lanaa sihoon'),
  ('en.transliteration', 12, 12, 'Arilhu ma\'anaa ghadany yarta\'wa yal\'ab wa innaa lahoo lahaafizoon'),
  ('en.transliteration', 12, 13, 'Qaala innee la yahzununeee an tazhaboo bihee wa akhaafu anyyaakulahuz zi\'bu wa antum \'anhu ghaafiloon'),
  ('en.transliteration', 12, 14, 'Qaaloo la in akalahuzzi\'bu wa nahnu \'usbatun innaaa izal lakhaasiroon'),
  ('en.transliteration', 12, 15, 'Falammaa zahaboo bihee wa ajma\'ooo anyyaj\'aloohu fee ghayaabatil jubb; wa awyainaaa ilaihi latunabbi \'annahum bi amrihim haaza wa hum laa yash\'uroon'),
  ('en.transliteration', 12, 16, 'Wa jaaa\'ooo abaahum \'ishaaa \'any yabkoon'),
  ('en.transliteration', 12, 17, 'Qaaloo yaaa abaanaaa innaa zahabnaa nastabiqu wa taraknaa Yoosufa \'inda mataa\'inaa fa akhalahuz zi\'b, wa maaa anta bimu\'minil lanaa wa law kunnaa saadiqeen'),
  ('en.transliteration', 12, 18, 'Wa jaaa\'oo \'alaa qamee shihee bidamin kazi\' qaala bal sawwalat lakum anfusukum amraa; fasabrun jameel; wallaahul musta\'aanu \'alaa man tasifoon'),
  ('en.transliteration', 12, 19, 'Wa jaaa\'at saiyaaratun fa-arsaloo waaridahum fa adlaa dalwah; qaala yaa bushraa haaza ghulaam; wa asarroohu bi-daa\'ah; wallaahu \'aleemum bimaa ya\'maloon'),
  ('en.transliteration', 12, 20, 'Wa sharawhu bisamanim bakhsin daraahima ma\'doo datinw wa kaanoo feehi minaz zaahideen'),
  ('en.transliteration', 12, 21, 'Wa qaalal lazish taraahu mim Misra limra atiheee akrimee maswaahu \'asaaa any-yanfa\'anaaa aw nattakhizahoo waladaa; wa kazaalika mak-kannaa li-Yoosufa fil ardi wa linu\'allimahoo min taaweelil ahaadees; wallaahu ghaalibun \'alaaa amrihee wa laakinna aksaran naasi laa ya\'lamoon'),
  ('en.transliteration', 12, 22, 'Wa lammaa balagha ashuddahooo aatainaahu bukmanw wa \'ilmaa; wa kazaa lika najzil muhsineen'),
  ('en.transliteration', 12, 23, 'Wa raawadat hul latee huwa fee baitihaa \'an nafsihee wa ghallaqatil abwaaba wa qaalat haita lak; qaala ma\'aazal laahi innahoo rabbeee ahsana maswaay; innahoo laa yuflihuz-zaalimoon'),
  ('en.transliteration', 12, 24, 'Wa laqad hammat bihee wa hamma bihaa law laaa ar ra-aa burhaana rabbih;; kazaalika linasrifa \'anhu sooo\'a walfa hshaaa\'; innahoo min \'ibaadi nal mukhlaseen'),
  ('en.transliteration', 12, 25, 'Wastabaqal baaba wa qaddat qameesahoo min dubu rinw wa alfayaa saiyidahaa ladal baab; qaalat maa jazaaa\'u man araada bi ahlika sooo\'an illaaa any-yusjana aw azaabun aleem'),
  ('en.transliteration', 12, 26, 'Qaala hiya raawadatnee \'an nafsee wa shahida shaahidum min ahlihaa in kaana qameesuhoo qudda min qubulin fasadaqat wa huwa minal kaazibeen'),
  ('en.transliteration', 12, 27, 'Wa in kaana qameesuhoo qudda min duburin fakazabat wa huwa minas saadiqeen'),
  ('en.transliteration', 12, 28, 'Falammaa ra-aa qamee sahoo qudda min duburin qaala innahoo min kaidikunna inna kaidakunna \'azeem'),
  ('en.transliteration', 12, 29, 'Yoosofu a\'rid \'an haaza wastaghfiree lizambiki innaki kunti minal khaati\'een'),
  ('en.transliteration', 12, 30, 'Wa qaala niswatun filma deenatim ra atul\'Azeezi turaawidu fataahaa \'an nafsihee qad shaghafahaa bubbaa; innaa lana raahaa fee dalaalim mubeen'),
  ('en.transliteration', 12, 31, 'Falammaa sami\'at bimak rihinna arsalat ilaihinna wa a\'tadat lahunna muttaka anw wa aatat kulla waahidatim min hunna sikkeenanw wa qaala tikh ruj \'alaihinna falammaa ra aynahooo akbarnahoo wa qatta\'na aydiyahunna wa qulna haasha lillaahi maa haaza basharaa; in haazaaa illaa malakun kareem'),
  ('en.transliteration', 12, 32, 'Qaalat fazaalikunnal lazee lumtunnanee feeh; wa laqad raawattuhoo \'an nafsihee fasta\'sam; wa la\'il lam yaf\'al maaa aamuruhoo la yusjananna wa la yakoonam minas saaghireen'),
  ('en.transliteration', 12, 33, 'Qaala rabbis sijnu ahabbu ilaiya mimma yad\'oo naneee \'ilaihi wa illaa tasrif \'annee kaidahunna asbu ilaihinna wa akum minal jaahileen'),
  ('en.transliteration', 12, 34, 'Fastajaaba lahoo rabbuhoo fasarafa \'anhu kaidahunn; innahoo Huswas_Samee\'ul \'Aleem'),
  ('en.transliteration', 12, 35, 'Summa badaa lahum mim ba\'di maa ra-awul Aayaati layasjununnahoo hatta heen'),
  ('en.transliteration', 12, 36, 'Wa dakhala ma\'ahussijna fata yaan; qaala ahaduhumaaa inneee araaneee a\'siru khamranw wa qaalal aakharu inneee khubzan taakulut tairu minh; nabbi \'naa bitaaweelihee innaa naraaka minal muhsineen'),
  ('en.transliteration', 12, 37, 'Qaala laa yaateekumaa ta\'aamun turzaqaaniheee illaa nabbaatukumaa bitaaweelihee qabla any yaatiyakumaa; zaali kumaa mimmaa \'allamanee rabbee; innee taraktu millata qawmil laa yu\'minoona billaahi wahum bil aakhirati hum kaafiroon'),
  ('en.transliteration', 12, 38, 'Wattab\'tu millata aabaaa\'eee Ibraaheema wa Ishaaqa wa Ya\'qoob; maa kaana lanaaa an nushrika billaahi min shai\' zaalikamin fadlil laahi \'alainaa wa \'alan naasi wa laakinna aksaran naasi laa yashkuroon'),
  ('en.transliteration', 12, 39, 'Yaa saahibayis sijni \'a-arbaabum mutafarriqoona khayrun amil laahul waahidul qahhaar'),
  ('en.transliteration', 12, 40, 'Maa ta\'budoona min doonihee illaaa asmaaa\'an sam maitumoohaaa antum wa aabaaa\'ukum maaa anzalal laahu bihaa min sultan; inilhukmu illaa lillaah; amara allaa ta\'budooo illaaa iyyaah; zaalikad deenul qaiyimu wa laakinna aksaran naasi laa ya\'lamoon'),
  ('en.transliteration', 12, 41, 'Yaa saahibayis sijni ammaaa ahadukumaa fa yasqee rabbahoo khamranw wa ammal aakharu fa yuslabu fataakulut tairu mir raasih; qudiyal amrul lazee feehi tastaftiyaan'),
  ('en.transliteration', 12, 42, 'Wa qaala lillazee zanna annahoo najim minhumaz kurnee \'inda rabbika fa-ansaahush Shaitaanu zikra Rabbihee falabisa fis sijni bad\'a sineen'),
  ('en.transliteration', 12, 43, 'Wa qaalal maliku inneee araa sab\'a baqaraatin simaaniny yaakuluhunna sab\'un \'ijaafunw wa sab\'a sumbulaatinkhudrinw wa ukhara yaabisaat; yaaa ayuhal mala-u aftoonee fee nu\'yaaya in kuntum lirru\'yaa ta\'buroon'),
  ('en.transliteration', 12, 44, 'Qaalooo adghaasu ahlaa minw wa maa nahnu bitaaweelil ahlaami bi\'aalimeen'),
  ('en.transliteration', 12, 45, 'Wa qaalal lazee najaa minhumaa waddakara ba\'da ummatin ana unabbi\'ukum bitalweelihee fa-arsiloon'),
  ('en.transliteration', 12, 46, 'Yoosufu ayyuhas siddee qu aftinaa fee sab\'i baqaraatin simaaniny yaakuluhunna sab\'un \'ijaafunw wa sabi\'i sumbulaatin khudrinw wa ukhara yaabisaatil la\'alleee arj\'u ilan naasi la\'allahum ya\'lamoon'),
  ('en.transliteration', 12, 47, 'Qaala tazra\'oona sab\'a sineena da aban famaa basattum fazaroohu fee sumbu liheee illaa qaleelam mimmaa taakuloon'),
  ('en.transliteration', 12, 48, 'Summa yaatee mim ba\'di zaalika sab\'un shidaaduny yaa kulna maa qaddamtum lahunna illaa qaleelam mimma tuhsinoon'),
  ('en.transliteration', 12, 49, 'Summa yadtee mim ba\'di zaalika \'aamun feehi yughaa sun naasu wa feehi ya\'siroon'),
  ('en.transliteration', 12, 50, 'Wa qaalal maliku\'toonee bihee falammaa jaaa\'ahur rasoolu qaalar-ji ilaa rabbika fas\'alhu maa baalun niswatil laatee qatta\'na aydiyahunn; inna Rabbee bikaidihinna \'Aleem'),
  ('en.transliteration', 12, 51, 'Qaala maa khatbukunna iz raawattunna Yoosufa \'annafsih; qulna haasha lillaahi maa \'alimnaa \'alaihi min sooo\'; qaalatim ra atul \'Azeezil \'aana hashasal haqq, ana raawat tuhoo \'an nafsihee wa innahoo laminas saadiqeen'),
  ('en.transliteration', 12, 52, 'Zaalika liya\'lama annee lam akhunhu bilghaibi wa annal laaha laa yahdee kaidal khaaa\'ineen'),
  ('en.transliteration', 12, 53, 'Wa maa ubarri\'u nafsee; innan nafsa la ammaaratum bissooo\'i illaa maa rahima Rabbee; inna Rabbee Ghafoorur Raheem'),
  ('en.transliteration', 12, 54, 'Wa qaalal maliku\' toonee biheee astakhlishu linafsee falammaa kallamahoo qaala innakal yawma ladainaa makeenun ameen'),
  ('en.transliteration', 12, 55, 'Qaalaj \'alnee \'alaa khazaaa\'inil ardi innee hafeezun \'aleem'),
  ('en.transliteration', 12, 56, 'Wa kazaalika makkannaa li Yoosufa fil ardi yatabawwa\'u minhaa haisu yashaaaa\'; nuseebu birahmatinaa man nashaaa\'u wa laa nudee\'u ajral muhsineen'),
  ('en.transliteration', 12, 57, 'Wa la ajrul Aakhirati khairul lillazeena aamanoo wa kaanoo yattaqoon'),
  ('en.transliteration', 12, 58, 'Wa jaaa\'a ikhwatu Yoosufa fadakhaloo \'alaihi fa\'arafahum wa hum lahoo munkiroon'),
  ('en.transliteration', 12, 59, 'Wa lammaa jahhazahum bijahaazihim qaala\' toonee bi akhil lakum min abeekum; alaa tarawna anneee oofil kaila wa ana khairul munzileen'),
  ('en.transliteration', 12, 60, 'Fa il lam taatoonee bihee falaa kaila lakum \'indee wa laa taqraboon'),
  ('en.transliteration', 12, 61, 'Qaaloo sanuraawidu \'anhu abaahu wa innaa lafaa\'iloon'),
  ('en.transliteration', 12, 62, 'Wa qaala lifityaanihij \'aloo bidaa\'atahum fee rihaalihim la\'allahum ya\'rifoonahaaa izan qalabooo ilaaa ahlihim la\'allahum yarji\'oon'),
  ('en.transliteration', 12, 63, 'Falammaa raja\'ooo ilaaa abeehim qaaloo yaaa abaanaa muni\'a minnal kailu fa arsil ma\'anaaa akhaanaa naktal wa innaa lahoo lahaafizoon'),
  ('en.transliteration', 12, 64, 'Qaala hal aamanukum \'alihi illaa kamaa amintukum \'alaaa akheehimin qabl; fal laahu khairun haafizanw wa Huwa arhamur Raahimeen'),
  ('en.transliteration', 12, 65, 'Wa lammaa fatahoo mataa \'ahum wajadoo bidaa\'atahum ruddat ilaihim qaaloo yaaa abaanaa maa nabghee; haazihee bida \'atunaa ruddat ilainaa wa nameeru ahlanaa wa nahfazu akhaanaa wa nazdaadu kaila ba\'eer; zaalika kailuny yaseer'),
  ('en.transliteration', 12, 66, 'Qaala lan ursilahoo ma\'akum hattaa tu\'tooni mawsiqam minal laahis lataa tunnanee biheee illaaa nay yuhaata bikum falammaaa aatawhu mawsiqahum qaalal laahu \'alaa maa naqoolu Wakeel'),
  ('en.transliteration', 12, 67, 'Wa qaala yaa baniyya laa tadkhuloo mim baabinw waa hidinw wadkhuloo min abwaabim mutafarriqah; wa maaa ughnee \'ankum minal laahi min shai\'in; inil hukmu illaa lillaahi \'alaihi tawakkaltu wa \'alaihi fal yatawakkalil Mutawakkiloon'),
  ('en.transliteration', 12, 68, 'Wa lammaa dakhaloo min haisu amarahum aboohum maa kaana yughnee \'anhum minal laahi min shai\'in illaa haajatan fee nafsi Ya\'qooba qadaahaa; wa innahoo lazoo \'ilmil limaa \'allamnaahu wa laakinna aksaran naasi laa ya\'lamoon'),
  ('en.transliteration', 12, 69, 'Wa lammaa dakhaloo \'alaa Yoosufa aawaaa ilaihi akhaahu qaala inneee ana akhooka falaa tabta\'is bimaa kaanoo ya\'maloon'),
  ('en.transliteration', 12, 70, 'Falammaa jahhazahum bijahaazihim ja\'alas siqaayata fee rahli akheehi summa azzana mu\'azzinun ayyatuhal\'eeru innakum lasaariqoon'),
  ('en.transliteration', 12, 71, 'Qaaloo wa aqbaloo \'alaihim maazaa tafqidoon'),
  ('en.transliteration', 12, 72, 'Qaaloo nafqidu suwaa\'al maliki wa liman jaaa\'a bihee himlu ba\'eerinw wa ana bihee za\'eem'),
  ('en.transliteration', 12, 73, 'Qaaloo tallaahi laqad \'alimtum maa ji\'na linufsida fil ardi wa maa kunnaa saariqeen'),
  ('en.transliteration', 12, 74, 'Qaaloo famaa jazaaa\'u hooo in kuntum kaazibeen'),
  ('en.transliteration', 12, 75, 'Qaaloo jazaaa\'uhoo manw wujida fee rahlihee fahuwa jazaaa\'uh; kazaalika najziz zaalimeen'),
  ('en.transliteration', 12, 76, 'Fabada-a bi-aw\'iyatihim qabla wi\'aaa\'i akheehi summas takhrajahaa minw wi \'aaa\'i akheeh; kazaalika kidnaa li Yoosuf; maa kaana liyaakhuza akhaahu fee deenil maliki illaaa any yashaaa\'al laah; narfa\'u darajaatim man nashaaa\'; wa fawqa kulli zee \'ilmin \'Aleem'),
  ('en.transliteration', 12, 77, 'Qaaloo iny yasriq faqad saraqa akhul lahoo min qabl; fa asarrahaa Yoosufu fee nafsihee wa lam yubdihaa lahum; qaala antum sharrum makaananw wallaahu a\'lamu bimaa tasifoon'),
  ('en.transliteration', 12, 78, 'Qaaloo yaaa ayyuhal \'Azeezu inna lahooo aban shaikhan kabeeran fakhuz ahadanaa makaanahoo innaa naraaka minal muhsineen'),
  ('en.transliteration', 12, 79, 'Qaala ma\'aazal laahi an naakhuza illaa manw wajadnaa mataa\'anaa \'indahoo innaaa izal lazaalimoon'),
  ('en.transliteration', 12, 80, 'Falammas tay\'asoo minhu khalasoo najiyyan qaala kabeeruhum alam ta\'lamoon anna abaakum qad akhaza \'alaikum mawsiqam minal laahi wa min qablu maa farrattum fee Yoosufa falan abrahal arda hattaa yaazana leee abeee aw yahkumal laahu lee wa huwa khairul lhaakimeen'),
  ('en.transliteration', 12, 81, 'Irji\'ooo ilaaa abeekum faqooloo yaaa abaanaaa innab naka saraq; wa maa shahidnaaa illaa bimaa \'alimnaa wa maa kunnaa lilghaibi haafizeen'),
  ('en.transliteration', 12, 82, 'Was\'alil qaryatal latee kunnaa feehaa wal\'eeral lateee aqbalnaa feehaa wa innaa lasaadiqoon'),
  ('en.transliteration', 12, 83, 'Qaala bal sawwalat lakum anfusukum amran fasabrun jameelun \'asal laahu any yaa tiyanee bihim jamee\'aa; innahoo Huwal \'Aleemul Hakeem'),
  ('en.transliteration', 12, 84, 'Wa tawallaa \'anhum wa qaala yaaa asafaa \'alaa Yoosufa wabyaddat \'aynaahu minal huzni fahuwa kazeem'),
  ('en.transliteration', 12, 85, 'Qaaloo tallaahi tafta\'u tazkuru Yoosufa hattaa takoona haradan aw takoona minal haalikeen'),
  ('en.transliteration', 12, 86, 'Qaala innamaaa ashkoo bassee wa huzneee ilal laahi wa a\'lamu minal laahi maa laa ta\'lamoon'),
  ('en.transliteration', 12, 87, 'Yaa baniyyaz haboo fatahassasoo miny Yoosufa wa akheehi wa laa tai\'asoo mir rawhil laahi innahoo laa yai\'asu mir rawhil laahi illal qawmul kaafiroon'),
  ('en.transliteration', 12, 88, 'Falammaa dakhaloo \'alaihi qaaloo yaaa ayyuhal \'Azeezu massanaa wa ahlanad durru wa ji\'naa bibidaa \'timmuzjaatin fa awfi lanal kaila wa tasaddaq \'alainaa innal laaha yajzil mutasaddiqeen'),
  ('en.transliteration', 12, 89, 'Qaala hal \'alimtum maa fa\'altum bi Yoosufa wa akheehi iz antum jaahiloon'),
  ('en.transliteration', 12, 90, 'Qaaloo \'a innaka la anta Yoosufu qaala ana Yoosufu wa haazaaa akhee qad mannal laahu \'alainaa innahoo mai yattaqi wa yasbir fa innal laaha laa yudee\'u ajral muhsineen'),
  ('en.transliteration', 12, 91, 'Qaaloo tallaahi laqad aasarakal laahu \'alainaa wa in kunnaa lakhaati\'een'),
  ('en.transliteration', 12, 92, 'Qaala laa tasreeba \'alaikumul yawma yaghfirul laahu lakum wa Huwa arhamur raahimeen'),
  ('en.transliteration', 12, 93, 'Izhaboo biqameesee haazaa fa alqoohu \'alaa wajhi abee yaati baseeranw waatoonee bi ahlikum ajma\'een'),
  ('en.transliteration', 12, 94, 'Wa lammaa fasalatil \'eeru qaala aboohum innee la ajidu reeha Yoosufa law laaa an tufannidoon'),
  ('en.transliteration', 12, 95, 'Qaaloo tallaahi innaka lafee dalaalikal qadeem'),
  ('en.transliteration', 12, 96, 'Falammaaa an jaaa\'albasheeru alqaahu \'alaa wajhihee fartadda baseeran qaala alam aqul lakum inneee a\'lamu minal laahi maa laa ta\'lamoon'),
  ('en.transliteration', 12, 97, 'Qaaloo yaaa abaanas taghfir lanaa zunoo =banaaa innaa kunnaa khaati\'een'),
  ('en.transliteration', 12, 98, 'Qaala sawfa astaghfiru lakum Rabbeee innahoo Huwal Ghafoorur Raheem'),
  ('en.transliteration', 12, 99, 'Falammaa dakhaloo \'alaa Yoosufa aawaaa ilaihi abayaihi wa qaalad khuloo Misra inshaaa\'al laahu aamineen'),
  ('en.transliteration', 12, 100, 'Wa raf\'a abawaihi \'alal \'arshi wa kharroo lahoo sujjadaa; wa qaala yaaa abati haaza taaweelu ru\'yaaya min qablu qad ja\'alahaa Rabbee haqqaa; wa qad ahsana beee iz akhrajanee minas sijni wa jaaa\'a bikum minal badwi mim ba\'di an nazaghash Shaitaanu bainee wa baina ikhwatee; inna Rabbee lateeful limaa yashaaa\'; innahoo Huwal \'Aleemul Hakeem'),
  ('en.transliteration', 12, 101, 'Rabbi qad aataitanee minal mulki wa \'allamtanee min taaweelil ahaadees; faati ras samaawaati wal ardi Anta waliyyee fid dunyaa wal Aakhirati tawaffanee muslimanw wa alhiqnee bissaaliheen'),
  ('en.transliteration', 12, 102, 'Zaalika min ambaaa\'il ghaibi nooheehi ilaika wa maa kunta ladaihim iz ajma\'ooo amrahum wa hum yamkuroon'),
  ('en.transliteration', 12, 103, 'Wa maa aksarun naasi wa law harasta bimu\'mineen'),
  ('en.transliteration', 12, 104, 'Wa maa tas\'aluhum \'alaihi min ajr; in huwa illaa zikrul lil\'aalameen'),
  ('en.transliteration', 12, 105, 'Wa ka ayyim min Aayatin fis samaawaati wal ardi yamurroona \'alaihaa wa hum \'anhaa mu\'ridoon'),
  ('en.transliteration', 12, 106, 'Wa maa yu\'minu aksaru hum billaahi illaa wa hum mushrikoon'),
  ('en.transliteration', 12, 107, 'Afa aminooo an taatiya hum ghaashiyatum min \'azaabil laahi aw taatiyahumus Saa\'atu baghtatanw wa hum laa yash\'uroon'),
  ('en.transliteration', 12, 108, 'Qul haazihee sabeeleee ad\'ooo ilal laah; \'alaa baseera tin ana wa manit taba\'anee wa Subhaanal laahi wa maaa ana minal mushrikeen'),
  ('en.transliteration', 12, 109, 'Wa maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim min ahlil quraa; afalam yaseeroo fil ardi fa yanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; wa la Daarul Aakhirati Khairul lillazeenat taqaw; afalaa ta\'qiloon'),
  ('en.transliteration', 12, 110, 'Hattaaa izas tai\'asar Rusulu wa zannooo annahum qad kuziboo jaaa\'ahum nas runaa fanujjiya man nashaaa\'u wa laa yuraddu baasunna \'anil qawmil mujrimeen'),
  ('en.transliteration', 12, 111, 'Laqad kaana fee qasasihim \'ibratul li ulil albaa; maa kaana hadeesany yuftaraa wa laakin tasdeeqal lazee baina yadihi wa tafseela kulli shai\'inw wa hudanw wa rahmatal liqawminy yu\'minoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 12, 1, 'یہ روشن کتاب کی آیتیں ہیں'),
  ('ur.ahmedali', 12, 2, 'ہم نے اس قرآن کو عربی زبان میں تمہارے سمجھنے کے لیے نازل کیا'),
  ('ur.ahmedali', 12, 3, 'ہم تیرے پاس بہت اچھا قصہ بیان کرتے ہیں اس واسطے کہ ہم نے تیری طرف یہ قرآن بھیجا ہے اور تو اس سے پہلے البتہ بے خبروں میں سے تھا'),
  ('ur.ahmedali', 12, 4, 'جس وقت یوسف نے اپنے باپ سے کہا اے باپ میں گیارہ ستاروں اور سورج اور چاند کو خواب میں دیکھا کہ وہ مجھے سجدہ کر رہے ہیں'),
  ('ur.ahmedali', 12, 5, 'کہا اے بیٹا اپنا خواب بھائیوں کے سامنے بیان مت کرنا وہ تیرے لیے کوئی نہ کوئی فریب بنا دیں گے شیطان انسان کا صریح دشمن ہے'),
  ('ur.ahmedali', 12, 6, 'اوراسی طرح تیرا رب تجھے برگزیدہ کرے گا اور تجھےخواب کی تعبیر سکھائے گا اور اپنی نعمتیں تجھ پر اور یعقوب کے گھرانے پر پوری کرے گا جس طرح کہ اس سے پہلے تیرے باپ دادا ابراھیم اور اسحاق پر پوری کر چکا ہےبے شک تیرا رب جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 12, 7, 'البتہ یوسف اور اس کے بھائیوں کے قصہ میں پوچھنے والو ں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 12, 8, 'جب انہوں نے کہا البتہ یوسف اور اس کا بھائی ہمارے باپ کو ہم سے زیادہ پیارا ہے حالانکہ ہم طاقتور جماعت ہیں بے شک ہمارا باپ صریح غلطی پر ہے'),
  ('ur.ahmedali', 12, 9, 'یوسف کو مار ڈالو یا کسی ملک میں پھینک دو تاکہ باپ کی توجہ اکیلے تم پر رہے اور اس کے بعد نیک آدمی ہو جانا'),
  ('ur.ahmedali', 12, 10, 'ان میں سے ایک کہنے والے نے کہا کہ یوسف کو قتل نہ کرواور اسے گمنام کنوئیں میں ڈال دو کہ اسے کوئی مسافر اٹھا لے جائے اگر تم کرنے ہی والے ہو'),
  ('ur.ahmedali', 12, 11, 'انہوں نے کہااےباپ کیا بات ہے کہ تو یوسف پر ہمارا اعتبار نہیں کرتا اور ہم تو اس کے خیر خواہ ہیں'),
  ('ur.ahmedali', 12, 12, 'کل اسے ہمارے ساتھ بھیج دے کہ وہ کھائے اور کھیلے اوربےشک ہم ا سکے نگہبان ہیں'),
  ('ur.ahmedali', 12, 13, 'اس نے کہا مجھے اس سے غم ہوتا ہے کہ تم اسے لے جاؤ اور اس سے ڈرتا ہوں کہ اسے بھیڑیا کھا جائے اورتم اس سے بے خبر رہو'),
  ('ur.ahmedali', 12, 14, 'انہوں نے کہا اگر اسے بھیڑیا کھا گیا اور ہم ایک طاقتور جماعت ہیں بے شک ہم اس وقت البتہ نقصان اٹھانے والے ہوں گے'),
  ('ur.ahmedali', 12, 15, 'جب اسے لے کر چلے اور متفق ہوئے کہ اسے گمنام کنوئیں میں ڈالیں تو ہم نے یوسف کی طرف وحی بھیجی کہ تو ضرور انہیں ایک دن آگاہ کرے گا ان کے اس کام سے اور وہ تجھے نہ پہچانیں گے'),
  ('ur.ahmedali', 12, 16, 'اور کچھ رات گئی اپنےباپ کے پاس روتے ہوئے آئے'),
  ('ur.ahmedali', 12, 17, 'کہا اے ہمارے باپ ہم تو آپس میں دوڑنے میں مصروف ہوئے اور یوسف کو اپنے اسباب کے پاس چھوڑ گئے تب اسے بھیڑیا کھا گیا او رتو ہمارے کہنے پر یقین نہیں کرے گا اگرچہ ہم سچےہی ہوں'),
  ('ur.ahmedali', 12, 18, 'اور اسی کے کرتے پر جھوٹ موٹ کا خون بھی لگا لائے اس نے کہا نہیں بلکہ تم نے دل سے ایک بات بنائی ہے اب صبر ہی بہتر ہے اورالله ہی سے مدد مانگتا ہوں اس بات پر جو تم بیان کر تے ہو'),
  ('ur.ahmedali', 12, 19, 'اور ایک قافلہ آیا پھر انہوں نے اپنا پانی بھرنے والا بھیجا اس نے اپنا ڈول لٹکایا کہا کیا خوشی کی بات ہے یہ ایک لڑکا ہے اور اسے تجارت کا مال سمجھ کر چھپا لیا اور الله خوب جانتا ہے جو کچھ وہ کر رہے تھے'),
  ('ur.ahmedali', 12, 20, 'اسے بھائی ناقص قیمت پر بیچ آئے گنتی کی چونیوں پر اور اس سے بیزار ہو رہے تھے'),
  ('ur.ahmedali', 12, 21, 'اور جس نے اسے مصر میں خرید کیا اس نے اپنی عورت سے کہا اس کی عزت کر شاید ہمارے کام آئے یا ہم اسے بیٹا بنا لیں اس طرح ہم نے یوسف کو اس ملک میں جگہ دی اور تاکہ ہم اسے خواب کی تعبیر سکھائیں اور الله اپنا کام جیت کر رہتا ہے لیکن اکثر لوگ نہیں جانتے'),
  ('ur.ahmedali', 12, 22, 'اور جب اپنی جوانی کو پہنچا تو ہم نے اسے حکم اور علم دیا اور نیکوں کو ایسا ہی بدلہ دیتے ہیں'),
  ('ur.ahmedali', 12, 23, 'اورجس عورت کے گھر میں تھا وہ اسے پھسلا نے لگی اور دروازے بند کر لیے اور کہنے لگی لو آؤ اس نے کہا الله کی پناہ وہ تو میرا آقا ہے جس نے مجھے عزت سے رکھا ہے بے شک ظالم نجات نہیں پاتے'),
  ('ur.ahmedali', 12, 24, 'اور البتہ اس عورت نے تو اس پر ارادہ کر لیا تھا اور اگر وہ اپنے رب کی دلیل نہ دیکھ لیتا تو اس کا اردہ کر لیتا اسی طرح ہوا تاکہ ہم اس سے برائی اور بے حیائی کو ٹال دیں بے شک وہ ہمارے چنے ہوئے بندوں میں سے تھا'),
  ('ur.ahmedali', 12, 25, 'اور دونوں دروازے کی طرف دوڑے اور عورت نے اس کا کرتہ پیچھے سےپھاڑ ڈالا اور دونوں نے عور ت کے خاوند کو دروازے کے پاس پایا کہنے لگی کہ جو تیرے گھر کے لوگوں سے برااردہ کرے اس کی تو یہی سزا ہے کہ قید کیا جائے یا سخت سزا دی جائے'),
  ('ur.ahmedali', 12, 26, 'کہا یہی مجھ سے اپنا مطلب نکالنے کو پھسلاتی تھی اور عورت کے گھر والوں میں سے ایک گواہ نے گواہی دی اگر اس کا کرتہ آگے سے پھٹا ہوا ہے تو عورت سچی ہے اور وہ جھوٹا ہے'),
  ('ur.ahmedali', 12, 27, 'اور اگر اس کا کرتہ پیچھے سے پھٹاہوا ہے تو یہ جھوٹی ہے اور وہ سچا ہے'),
  ('ur.ahmedali', 12, 28, 'پھر جب عزیز نے اس کا کرتہ پیچھے سے پھٹا ہوا دیکھا کہابے شک یہ تم عورتوں کا ایک فریب ہے بے شک تمہارا فریب بڑا ہوتا ہے'),
  ('ur.ahmedali', 12, 29, 'یوسف تو اس سے درگزر کر اور تو اے عورت اپنے گنا ہ کی معافی مانگ کیوں کہ تو ہی خطا کار ہے'),
  ('ur.ahmedali', 12, 30, 'اورعوتوں نے شہر میں چرچا کیا کہ عزیز کی عورت اپنے غلام کو چاہتی ہے بے شک اس کی محبت میں فریفتہ ہوگئی ہے ہم تو اسے صریح غلطی پر دیکھتے ہیں'),
  ('ur.ahmedali', 12, 31, 'پھر جب عزیز کی بیوی نے ان کی ملامت سنی تو انہیں بھلا بھیجا اور ان کے واسطے ایک مجلس تیار کی اور ان میں سے ہر ایک کے ہاتھ میں ایک چھری دی اور کہا ان کے سامنے نکل آ پھر جب انہوں نےاسے دیکھا تو حیرت میں رہ گئیں اور اپنے ہاتھ کاٹ لیے اور کہا الله پاک ہے یہ انسان تو نہیں ہے یہ تو کوئی بزرگ فرشتہ ہے'),
  ('ur.ahmedali', 12, 32, 'کہا یہی وہ ہے کہ جس کے معاملہ میں تم نے مجھےملامت کی تھی اور البتہ تحقیق میں نے اس سے دلی خواہش ظاہر کی تھی پھر اس نے اپنے آپ کو روک لیا اور اگر وہ میرا کہنا نہ مانے گا تو ضرور قید کر دیا جائے گا اور ذلیل ہو کررہے گا'),
  ('ur.ahmedali', 12, 33, 'یوسف نے کہا اے میرے رب میرے لیے قید حانہ بہتر ہے اس کام سے کہ جس کی طرف مجھے بلا رہی ہیں اوراگر تو مجھ سے ان کا فریب دفع نہ کرے گا تو ان کی طرف مائل ہوجاؤں گا اور جاہلوں میں سے ہو جاؤں گا'),
  ('ur.ahmedali', 12, 34, 'پھر اس کے رب نے اس کی دعا قبول کی پس ان کا فریب ان سے دور کر دیا گیا کیوں کہ وہی سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 12, 35, 'ان لوگو ں کو نشانیاں دیکھنے کے بعد یوں سمجھ میں آیا کہ اسے ایک مدت تک قید کر دیں'),
  ('ur.ahmedali', 12, 36, 'اور اس کے ساتھ دو جوان قید خانہ میں داخل ہوئے ان میں سے ایک نے کہا میں دیکھتا ہوں کہ شراب نچوڑتا ہوں اور دوسرے نے کہا میں دیکھتا ہوں کہ اپنے سر پر روٹی اٹھا رہا ہوں کہ اس میں سے جانور کھاتے ہیں ہمیں اس کی تعبیر بتلا ہم تجھے نیکو کار سمجھتے ہیں'),
  ('ur.ahmedali', 12, 37, 'کہا جو کھانا تمہیں دیا جاتا ہے وہ ابھی آنے نہ پائے گا کہ اس سے پہلے میں تمہیں اس کی تعبیر بتلا دوں گا یہ ان چیزو ں سے ہے جو میرے رب نے مجھے سکھائی ہیں بے شک میں نے اس قوم کا مذہب ترک کر دیا ہے جو الله پرایمان نہیں لاتی اور وہ آخرت کے بھی منکر ہیں'),
  ('ur.ahmedali', 12, 38, 'اور میں اپنے باپ دادا ابراھیم اور اسحاق اور یعقوب کے مذہب کا تابع ہو گیا ہوں ہمیں یہ جائز نہیں کی اللہ کے ساتھ کسی کو بھی شریک کریں یہ ہم پر اور سب لوگوں پر اللہ کا فضل ہے لیکن بہت لوگ شکر نہیں کرتے'),
  ('ur.ahmedali', 12, 39, 'اے قید خانہ کے رفیقو کیا کئی جدا جدا معبود بہتر ہیں یا اکیلا الله جو زبردست ہے'),
  ('ur.ahmedali', 12, 40, 'تم اس کے سوا کچھ نہیں پوجتے مگر چند ناموں کو جو تم نے اور تمہارے باپ داداؤں نے مقرر کر لیے ہیں الله نے ان کے متعلق کوئی سند نہیں اتاری حکومت سوا الله کے کسی کی نہیں ہے اس نے حکم دیا ہے کہ اس کے سوا کسی کی عبادت نہ کرو یہی سیدھا راستہ ہے لیکن اکثر آدمی نہیں جانتے'),
  ('ur.ahmedali', 12, 41, 'اے قید خانہ کے رفیقو تم دونوں میں سے ایک جو ہے وہ اپنے آقا کو شراب پلائے گا جو دوسرا ہے وہ سولی دیا جائے گا پھر اس کے سر میں سے پرندے کھائیں گے اس کام کا فیصلہ ہو گیا ہے جس کی تم تحقیق چاہتے تھے'),
  ('ur.ahmedali', 12, 42, 'اوران دونو ں میں سے جسے شیطان نے اسے اپنے آقا سے ذکر کرنا بھلا دیا پھر قید میں کئی برس رہا'),
  ('ur.ahmedali', 12, 43, 'اور بادشاہ نے کہا میں خواب دیکھتا ہوں کہ سات موٹی گائیں ہیں انہیں سات دبلی گائی ں کھاتی ہیں اور سات سبز خوشے ہیں اور سات خشک اے دربار والو مجھے میرے خواب کی تعبیر بتلاؤ اگر تم خواب کی تعبیر دینے والے ہو'),
  ('ur.ahmedali', 12, 44, 'انہوں نے کہا یہ خیالی خواب ہیں اور ہم ایسے خوابوں کی تعبیر نہیں جانتے'),
  ('ur.ahmedali', 12, 45, 'اور وہ بولا جو ان دونو ں میں سے بچا تھا اور اسے مدت کے بعد یاد آ گیا میں تمہیں اس کی تعبیر بتلاؤں گا سو تم مجھے بھیج دو'),
  ('ur.ahmedali', 12, 46, 'اے یوسف اے سچے ہمیں اس کی تعبیر بتلا کہ سات موٹی گایوں کو سات دبلی کھا رہی ہیں اور سات سبز خوشےہیں اور سات خشک تاکہ میں لوگو ں کے پاس لے جاؤں شاید وہ سمجھ جائیں'),
  ('ur.ahmedali', 12, 47, 'کہا تم سات برس لگاتار کھیتی کرو گے پھر جو کاٹو تو اسے اس کے خوشوں میں رہن ے دو مگر تھوڑا سا جو تم کھاؤ'),
  ('ur.ahmedali', 12, 48, 'پھر اس کے بعد سات برس سختی کے آئيں گے جو تم نے ان کے لیے رکھا تھا کھا جائیں گے مگر تھوڑا سا جوتم بیج کے واسطے روک رکھو گے'),
  ('ur.ahmedali', 12, 49, 'پھر اس کے بعد ایک سال آئے گا اس میں لوگوں پر مینہ برسے گا اسمیں رس نچوڑیں گے'),
  ('ur.ahmedali', 12, 50, 'اور بادشاہ نے کہا اسے میرے پاس لے آؤ پھر جب اس کے پاس قاصد پہنچا کہا اپنے آقا کے ہاں واپس جا اور اس سے پوچھ ان عورتوں کا کیا حال ہے جنہوں نے اپنے ہاتھ کاٹے تھے بے شک میرا رب ان کے فریب سے خوب واقف ہے'),
  ('ur.ahmedali', 12, 51, 'کہاتمہارا کیا واقعہ تھا جب تم نے یوسف کو پھسلایا تھا انہوں نے کہا الله پاک ہے ہمیں اس میں کوئی برائی معلوم نہیں ہوئی عزیز کی عورت بولی اب سچی بات ظاہر ہو گئی میں نے ہی اسے پھسلانا چاہا تھا اور وہ سچا ہے'),
  ('ur.ahmedali', 12, 52, 'یہ اس لیے کیا تاکہ عزیز معلوم کر لے کہ میں نے اس کی غائبانہ خیانت نہیں کی تھی اوربے شک الله خیانت کرنے والوں کے فریب کو چلنے نہیں دیتا'),
  ('ur.ahmedali', 12, 53, 'اور میں اپنے نفس کو پاک نہیں کہتا بے شک نفس تو برائی سکھاتاہے مگر جس پرمیرا رب مہربانی کرے بے شک میرا رب بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 12, 54, 'اور بادشاہ نے کہا کہ اسے میرے پاس لے آؤ تاکہ اسے خاص اپنے پاس رکھوں پھر جب اس سے بات چیت کی کہا بے شک تو آج سے ہمارے ہاں تو بڑا معزز اور معتبر ہے'),
  ('ur.ahmedali', 12, 55, 'کہا مجھے ملکی خزانوں پر مامور کر دو بے شک میں خوب حفاظت کرنے والا جاننے والا ہوں'),
  ('ur.ahmedali', 12, 56, 'اور ہم نے اس طور پر یوسف کو اس ملک میں بااختیار بنا دیا کہ اس میں جہاں چاہے رہےہم جس پر چاہیں اپنی رحمت متوجہ کر دیں اور ہم نیکی کرنے والوں کا اجر ضائع نہیں کرتے'),
  ('ur.ahmedali', 12, 57, 'اور آخرت کا ثواب ان کے لیے بہتر ہے جو ایمان لائے اور پرہیزگاری میں رہے'),
  ('ur.ahmedali', 12, 58, 'اور یوسف کے بھائی آئے پھر اس کے ہاں داخل ہوئے تواس نے انہیں پہچان لیا اور وہ پہچان نہیں سکے'),
  ('ur.ahmedali', 12, 59, 'اور جب انہیں ان کا سامان تیار کر دیا کہا میرے پاس وہ بھائی بھی لے آنا جو تمہارے باپ کی طرف سے ہے تم نہیں دیکھتے میں ناپ پورا دیتا ہوں اوربڑا مہمان نواز ہوں'),
  ('ur.ahmedali', 12, 60, 'پھر اگر تم اسے میرے پاس نہ لائے تو نہ تمہیں میرے ہاں سے پیمانہ ملے گا اور نہ تم میرے پاس آنا'),
  ('ur.ahmedali', 12, 61, 'انہوں نے کہا اس کے باپ سے خواہش کریں گے اور ہم یہ کر کے ہی رہیں گے'),
  ('ur.ahmedali', 12, 62, 'اور اپنے خدمتگاروں سے کہہ دیا کہ ان کی پونجی ان کے اسباب میں رکھ دو تاکہ وہ اسے پہچانیں جب وہ لوٹ کر اپنےگھر جائیں شاید وہ پھر آجائیں'),
  ('ur.ahmedali', 12, 63, 'پھر جب اپنے باپ کے ہاں پہنچے کہا اے باپ! ہمارا پیمانہ روک لیا گیا پس آپ ہمارے ساتھ ہمارے بھائی کو بھیج دیجیئے کہ ہم پیمانہ لائیں اور بے شک ہم اس کا نگہبان ہیں'),
  ('ur.ahmedali', 12, 64, 'کہا میں تمہارا اس پرکیا اعتبارکروں مگر وہی جیسا اس سے پہلے اس کے بھائی پر اعتبار کیا تھا سو الله بہتر نگہبان ہے اور وہ سب مہربانوں سے مہربان ہے'),
  ('ur.ahmedali', 12, 65, 'اورجب انہوں نے اپنا اسباب کھولا انہوں نے اپنی پونجی پائی جو انہیں واپس کر دی گئی تھی کہا اے ہمارے باپ! ہمیں اور کیا چاہیئے یہ ہماری پونجی ہمیں واپس کر دی گئی ہے اور اپنے گھر والوں کے لیے غلہ لائیں گے او راپنے بھائی کی حفاظت کریں گے اور ایک اونٹ کا بوجھ اور زیادہ لائیں گے اور یہ بوجھ ملنا آسان ہے'),
  ('ur.ahmedali', 12, 66, 'کہا اسے ہرگز تمہارے ساتھ نہیں بھیجوں گا یہاں تک کہ مجھے الله کا عہد دو کہ البتہ اسے میرے ہاں ضرور پہنچا دویں گے مگر یہ کہ تم سب گھر جاؤ پھر جب سب نے اسے عہد دیا کہا ہماری باتوں کا الله شاہد ہے'),
  ('ur.ahmedali', 12, 67, 'اور کہا اے میرے بیٹو! ایک دروازے سے داخل نہ ہونا اور مختلف دروازوں سے داخل ہونا اور میں تمہیں الله کی کیسی بات سے بچا نہیں سکتا الله کے سوا کسی کا حکم نہیں ہے اسی پر میرا بھروسہ ہے اوربھروسہ کرنے والوں کو اسی پر بھروسہ کرنا چاہئے'),
  ('ur.ahmedali', 12, 68, 'اور جب کہ اسی طرح داخل ہوئے جس طرح ان کے باپ نے حکم دیا تھا انہیں الله کی کسی بات سے کچھ نہ بچا سکتا تھا مگر یعقوب کے دل میں ایک خواہش تھی جسے اس نے پورا کیا اور وہ تو ہمارے سکھلانے سے علم والا تھا لیکن اکثر آدمی نہیں جانتے'),
  ('ur.ahmedali', 12, 69, 'اور جب وہ یوسف کے پاس گئے تو اس نے اپنے بھائی کو اپنے پاس جگہ دی کہا کہ بے شک میں تیرا بھائی ہوں پس جو کچھ یہ کرتے رہے ہیں اس پر غم نہ کر'),
  ('ur.ahmedali', 12, 70, 'پھر جب یوسف نے اس کا سامان تیار کر دیا تو اپنے بھائی کے اسباب میں کٹورا رکھ دیا پھر پکارے نے والے نے پکارا اے قافلہ والو! بے شک تم البتہ چور ہو'),
  ('ur.ahmedali', 12, 71, 'اس کی طرف متوجہ ہو کر کہنے لگے تمہاری کیا چیز گم ہوگئی ہے'),
  ('ur.ahmedali', 12, 72, 'انہوں نے کہا ہمیں بادشاہ کا کٹورا نہیں ملتا جو اسے لا ئےگا ایک اونٹ بھر کا غلہ پائے گا اور میں اس کا ضامن ہوں'),
  ('ur.ahmedali', 12, 73, 'انہوں نے کہا الله کی قسم تمہیں معلوم ہے ہم اس ملک میں شرارت کرنے کے لیے نہیں آئے اور نہ ہم کبھی چور تھے'),
  ('ur.ahmedali', 12, 74, 'انہوں نے کہا پھر اس کی کیا سزا ہے اگر تم جھوٹے نکلو'),
  ('ur.ahmedali', 12, 75, 'انہوں نے کہا اس کی سزا یہ ہے کہ جس کےاسباب میں سے پایا جائے پس وہی اس کے بدلہ میں جائے ہم ظالموں کو یہی سزا دیتے ہیں'),
  ('ur.ahmedali', 12, 76, 'پھر یوسف نے اپنے بھائی کے اسباب سے پہلےان کے اسباب دیکھنے شروع کیے پھر وہ کٹورا اپنے بھائی کے اسباب سے نکالا ہم نے یوسف کو ایسی تدبیر بتائی تھی بادشاہ کے قانون سے تو وہ اپنے بھائی کو ہرگز نہ لے سکتا تھا مگر یہ کہ الله چاہے ہم جس کے چاہیں درجے بلند کرتے ہیں اور ہر ایک دانا سے بڑھ کر دوسرا دانا ہے'),
  ('ur.ahmedali', 12, 77, 'انہوں نے کہا اگر اس نے چوری کی ہے تو اس سے پہلے اس کے بھائی نے بھی چوری کی تھی تب یوسف نے اپنے دل میں آہستہ سے کہا اور انہیں نہیں جتایا کہا تم درجے میں بدتر ہو اور الله خوب جانتا ہے جو کچھ تم بیان کرتے ہو'),
  ('ur.ahmedali', 12, 78, 'انہوں نے کہا اے عزیز! بے شک اس کا باپ بوڑھا بڑی عمر کا ہے سو اسکی جگہ ہم میں سے ایک کو رکھ لے ہم تم کو احسان کرنے والا دیکھتے ہیں'),
  ('ur.ahmedali', 12, 79, 'کہا الله کی پناہ کہ ہم بجز اس کے جس کے پاس اپنا اسباب پایا کسی اور کو پکڑیں تب تو ہم بڑے ظالم ہیں'),
  ('ur.ahmedali', 12, 80, 'پھر جب اس سےناامید ہوئے مشورہ کرنے کے لیے اکیلے ہو بیٹھے ان میں سے بڑے نے کہا کیا تمہیں معلوم نہیں کہ تمہارے باپ نے تم سے الله کا عہد لیا تھا اور پہلے جویوسف کے حق میں قصور کر چکے ہو سو میں تو اس ملک سے ہرگز نہیں جاؤں گا یہاں تک کہ میرا با پ مجھے حکم دے یا میرے لیے الله کوئی حکم فرمائے اور وہ بہتر فیصلہ کرنے والا ہے'),
  ('ur.ahmedali', 12, 81, 'تم اپنے باپ کے پاس لوٹ جاؤ اور کہو اے ہمارے باپ! تیرے بیٹے نے چوری کی اور ہم نے وہی کہا تھا جس کا ہمیں علم تھا اور ہمیں غیب کی خبر نہ تھی'),
  ('ur.ahmedali', 12, 82, 'اوراس گاؤں سے پوچھ لیجیئے جس میں ہم تھے اور اس قافلہ سے بھی جس میں ہم آئے ہیں اور بے شک ہم سچے ہیں'),
  ('ur.ahmedali', 12, 83, 'کہا بلکہ تم نے دل سے ایک بات بنا لی ہے اب صبر ہی بہتر ہے الله سے امید ہے کہ شاید الله ان سب کو میرے پاس لے آئے وہی جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 12, 84, 'اور اس نے ان سے منہ پھیر لیا اور کہا ہائے یوسف! اور غم سے اس کی آنکھیں سفید ہو گئیں پس وہ سخت غمگین ہوا'),
  ('ur.ahmedali', 12, 85, 'انہوں نے کہا الله کی قسم تو یوسف کی یاد کو نہیں چھوڑے گا یہاں تک کہ نکما ہو جائے یا ہلاک ہوجائے'),
  ('ur.ahmedali', 12, 86, 'کہا میں تو اپنی پریشانی اور غم کا اظہار الله ہی کے سامنے کرتا ہوں اور الله کی طرف سے میں وہ جانتا ہوں جو تم نہیں جانتے'),
  ('ur.ahmedali', 12, 87, 'اے میرے بیٹو! جاؤ یوسف اور اس کے بھائی کی تلاش کرو اور الله کی رحمت سے نا امید نہ ہو بے شک الله کی رحمت سے نا امید نہیں ہوتے مگر وہی لوگ جو کافر ہیں'),
  ('ur.ahmedali', 12, 88, 'پھر جب وہ ان کے پاس آئے تو کہا اے عزیز! ہمیں اور ہمارے گھر والوں کو قحط کی وجہ سے بڑی تکلیف ہے اور کچھ نکمی چیز لائے ہیں سو آپ پورا غلہ بھر دیجیئے اورخیرات دیجئے بے شک الله خیرات دینے والوں کو ثواب دیتا ہے'),
  ('ur.ahmedali', 12, 89, 'کہا تمہیں یاد ہے جو کچھ تم نے یوسف اور اس کے بھائی کے ساتھ کیا تھا جب تمہیں سمجھ نہ تھی'),
  ('ur.ahmedali', 12, 90, 'کہا کیا تو ہی یوسف ہے کہا میں ہی یوسف ہوں اور یہ میرا بھائی ہے الله نے ہم پر احسان کیابے شک جو ڈرتا ہے اور صبر کتا ہے تو الله بھی نیکوں کا اجر ضائع نہیں کرتا'),
  ('ur.ahmedali', 12, 91, 'انہوں نے کہا الله کی قسم البتہ تحقیق الله نے تمہیں ہم پر بزرگی دی اوربے شک ہم غلط کار تھے'),
  ('ur.ahmedali', 12, 92, 'کہا آج تم پر کوئی الزام نہیں الله تمہیں بخشے اور وہ سب سے زیادہ مہربان ہے'),
  ('ur.ahmedali', 12, 93, 'یہ کرتہ میرا لے جاؤ اور اسے میرے باپ کے منہ پر ڈال دو کہ وہ بینا ہوجائے اور میرے پاس اپنے سب کنبے کو لے آؤ'),
  ('ur.ahmedali', 12, 94, 'اور جب قافلہ روانہ ہوا تو ان کے باپ نے کہا بے شک میں یوسف کی بو پاتا ہوں اگر مجھے دیوانہ نہ بناؤ'),
  ('ur.ahmedali', 12, 95, 'لوگو ں نے کہا الله کی قسم بے شک تو البتہ اپنی گمراہی میں مبتلا ہے'),
  ('ur.ahmedali', 12, 96, 'پھر جب خوشخبری دینے والا آیا اس نے وہ کرتہ اس کے منہ پر ڈال دیا تو بینا ہو گیا کہا میں نے تمہیں نہیں کہا تھا کہ میں الله کی طرف سے وہ جانتا ہوں جو تم نہیں جانتے'),
  ('ur.ahmedali', 12, 97, 'انہوں نے کہا اے ہمارے باپ! ہمارے گناہ بحشوا دیجیئے بے شک ہم ہی غلط کار تھے'),
  ('ur.ahmedali', 12, 98, 'کہا عنقریب اپنے رب سے تمہارے لی معافی مانگوں گا بے شک وہ غفور رحیم ہے'),
  ('ur.ahmedali', 12, 99, 'پھر جب یوسف کے پاس آئے تو اس نے اپنے ماں باپ کو اپنے پاس جگہ دی اور کہا مصر میں داخل ہو جاؤ اگر الله نے چاہا تو امن سے رہو گے'),
  ('ur.ahmedali', 12, 100, 'اور اپنے ماں باپ کو تخت پر اونچا بٹھایا اور اس کے آگے سب سجدہ میں گر پڑے اور کہا اےباپ میرے اس پہلے خواب کی یہ تعبیر ہے اسے میرے رب نے سچ کر دکھایا اوراس نے مجھ پر احسان کیا جب مجھے قید خانے سے نکالا اور تمہیں گاؤں سے لے آیا اس کے بعد کہ شیطان مجھ میں اورمیرے بھائیوں میں جھگڑا ڈال چکا بے شک میرا رب جس کے لیے چاہتا ہے مہربانی فرماتا ہے بے شک وہی جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 12, 101, 'اے میرے رب تو نے مجھےکچھ حکومت دی ہے اور مجھے خوابوں کی تعبیر کا علم بھی سکھلایا ہے اے آسمانو ں اور زمین کے بنانے والے! دنیا اور آخرت میں تو ہی میرا کارساز ہے تو مجھے اسلام پر موت دے اور مجھے نیک بختوں میں شامل کر دے'),
  ('ur.ahmedali', 12, 102, 'یہ غیب کی خبریں کہیں جو ہم تیرے ہاں بھیجتے ہیں اور تو ان کے پاس نہیں تھا جب کہ انہوں نے اپنا ارادہ پکا کر لیا اور وہ تدبیریں کر رہے تھے'),
  ('ur.ahmedali', 12, 103, 'اور اکثر لوگ ایمان لانے والے نہیں خواہ تو کتنا ہی چاہے'),
  ('ur.ahmedali', 12, 104, 'اور آپ اس پر ان سے کوئی مزدوری بھی تو نہیں مانگتے یہ تو صرف تمام جہانوں کے لیے نصیحت ہے'),
  ('ur.ahmedali', 12, 105, 'اور آسمانوں اور زمین میں بہتی سی نشانیاں ہیں جن پر سے یہ گزرتے ہیں اوران سے منہ پھیر لیتے ہیں'),
  ('ur.ahmedali', 12, 106, 'اوران میں سے اکثر ایسے بھی ہیں جو الله کو مانتے بھی ہیں اور شرک بھی کرتے ہیں'),
  ('ur.ahmedali', 12, 107, 'کیا اس سے بے خوف ہو چکے ہیں کہ انہیں الله کے عذاب کی ایک آفت آپہنچے یا اچانک قیامت ان پر آ جائے اور انہیں خبر بھی نہ ہو'),
  ('ur.ahmedali', 12, 108, 'کہہ دو میرا اور میرے تابعداروں کا بصیرت کے ساتھ یہ راستہ ہے کہ میں لوگوں کو الله کی طرف بلا رہا ہوں اور الله پا ک ہے اور میں شرک کرنے والوں میں سے نہیں ہوں'),
  ('ur.ahmedali', 12, 109, 'ااور تجھ سے پہلے ہم نے جتنے پیغمبر بھیجے وہ سب بستیو ں کے رہنے و الے مرد ہی تھے ہم ان کی طرف وحی بھیجتے تھے پھر وہ زمین میں سیر کر کے کیوں نہیں دیکھتے کہ ان لوگو ں کا انجام کیا ہوا جوان سے پہلے تھے اور البتہ آخرت کا گھر پرہیز کرنے والوں کے لیے بہتر ہے پھر تم کیوں نہیں سمجھتے'),
  ('ur.ahmedali', 12, 110, 'یہاں تک کہ جب رسول ناامید ہونے لگے اورخیال کیا کہ ان سے جھوٹ کہا گیا تھا تب انہیں ہماری مدد پہنچی پھر جنہیں ہم نے چاہا بچا لیا اور ہمارے عذاب کو نافرمانوں سے کوئی بھی روک نہیں سکتا'),
  ('ur.ahmedali', 12, 111, 'البتہ ان لوگو ں کے حالات میں عقلمندوں کے لیے عبرت ہے کوئی بنائی ہوئی بات نہیں ہے بلکہ اس کلام کے موافق ہے جو اس سے پہلے ہے اور ہر چیز کا بیان اور ہدایت اور رحمت ان لوگوں کے لیے ہے جو ایمان لاتے ہیں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 12, 1, 'Elif, Lam, Ra. Bunlar, gerçeği açıklayan Kitap\'ın ayetleridir.'),
  ('tr.diyanet', 12, 2, 'Biz onu, anlayasınız diye, Arapça bir Kuran olarak indirdik.'),
  ('tr.diyanet', 12, 3, 'Biz bu Kuran\'ı vahyederek, sana en güzel kıssaları anlatıyoruz.. Oysa daha önce sen bunlardan habersizdin.'),
  ('tr.diyanet', 12, 4, 'Yusuf babasına: "Babacığım! "Rüyamda onbir yıldız, güneş ve ayın bana secde ettiklerini gördüm" demişti.'),
  ('tr.diyanet', 12, 5, 'Babası şunları söyledi: "Oğulcuğum! Rüyanı kardeşlerine anlatma, yoksa sana tuzak kurarlar; zira şeytan insanın apaçık düşmanıdır".'),
  ('tr.diyanet', 12, 6, '"Rabbin seni böylece rüyandaki gibi seçecek, sana rüyaları yorumlamayı öğretecek; daha önce, ataların İbrahim ve İshak\'a nimetlerini tamamladığı gibi, sana ve Yakub soyuna da tamamlayacaktır. Doğrusu Rabbin bilir, hakimdir."'),
  ('tr.diyanet', 12, 7, 'And olsun ki, Yusuf ve kardeşlerinin olayında, soranlara nice ibretler vardır.'),
  ('tr.diyanet', 12, 8, 'Kardeşleri demişlerdi ki: "Yusuf ve özkardeşi babamıza bizden daha sevgilidir. Oysa biz bir cemaatiz. Babamız açık bir yanlışlık içindedir."'),
  ('tr.diyanet', 12, 9, '"Yusuf\'u öldürün veya onu ıssız bir yere bırakıverin ki babanız size kalsın; ondan sonra da iyi kimseler olursunuz"'),
  ('tr.diyanet', 12, 10, 'İçlerinden biri: "Yusuf\'u öldürmeyin, onu bir kuyunun derinliklerine bırakın. Böyle yaparsanız yolculardan onu bulup alan olur" dedi.'),
  ('tr.diyanet', 12, 11, 'Bunun üzerine "Ey babamız! Yusuf\'un iyiliğini istediğimiz halde, onu niçin bize emniyet etmiyorsun? Yarın onu bizimle beraber gönder de gezsin oynasın, biz onu herhalde koruruz" dediler.'),
  ('tr.diyanet', 12, 12, 'Bunun üzerine "Ey babamız! Yusuf\'un iyiliğini istediğimiz halde, onu niçin bize emniyet etmiyorsun? Yarın onu bizimle beraber gönder de gezsin oynasın, biz onu herhalde koruruz" dediler.'),
  ('tr.diyanet', 12, 13, 'Babaları, "Onu götürmeniz beni üzüyor; siz farkına varmadan onu kurdun yemesinden korkarım" dedi.'),
  ('tr.diyanet', 12, 14, '"And olsun ki, biz kuvvetli bir toplulukken kurt onu yerse, biz aciz sayılırız" dediler.'),
  ('tr.diyanet', 12, 15, 'Yusuf\'u oturup bir kuyunun derinliklerine bırakmayı kararlaştırdılar. Biz ona, kardeşlerinin bu işlerini kendileri farkına varmadan haber vereceksin, diye vahyettik.'),
  ('tr.diyanet', 12, 16, 'Akşam üstü ağlayarak babalarına geldiklerinde: "Ey babamız! İnan olsun biz yarış yapıyorduk; Yusuf\'u eşyamızın yanına bırakmıştık; bir kurt onu yedi. Her ne kadar doğru söylüyorsak da sen bize inanmazsın" dediler.'),
  ('tr.diyanet', 12, 17, 'Akşam üstü ağlayarak babalarına geldiklerinde: "Ey babamız! İnan olsun biz yarış yapıyorduk; Yusuf\'u eşyamızın yanına bırakmıştık; bir kurt onu yedi. Her ne kadar doğru söylüyorsak da sen bize inanmazsın" dediler.'),
  ('tr.diyanet', 12, 18, 'Üzerine başka bir kan bulaşmış olarak Yusuf\'un gömleğini de getirmişlerdi. Babaları: "Sizi nefsiniz bir iş yapmaya sürükledi; artık bana güzelce sabır gerekir. Anlattıklarınıza ancak Allah\'tan yardım istenir" dedi.'),
  ('tr.diyanet', 12, 19, 'Bir kervan geldi, sucularını gönderdiler; sucu kovasını kuyuya saldı, "Müjde! İşte bir oğlan" dedi. Yusuf\'u alıp onu ticari bir mal olarak sakladılar. Oysa Allah yaptıklarını bilir.'),
  ('tr.diyanet', 12, 20, 'Onu yanlarında alıkoymak istemedikleri için ucuz bir fiyata, birkaç dirheme sattılar.'),
  ('tr.diyanet', 12, 21, 'Mısır\'da onu satın alan kimse karısına: "Ona güzel bak, belki bize faydası olur yahut ta onu evlat ediniriz" dedi. Biz işte böylece Yusuf\'u o yere yerleştirdik; ona, rüyaların nasıl yorumlanacağını öğrettik. Allah, işinde hakimdir, fakat insanların çoğu bunu bilmezler.'),
  ('tr.diyanet', 12, 22, 'Erginlik çağına erince ona hikmet ve bilgi verdik. İyi davrananları böyle mükafatlandırırız.'),
  ('tr.diyanet', 12, 23, 'Evinde bulunduğu kadın onu kendine çağırdı, kapıları sıkı sıkı kapadı ve "gelsene" dedi. Yusuf: "Günah işlemekten Allah\'a sığınırım, doğrusu senin kocan benim efendimdir; bana iyi baktı. Haksızlık yapanlar şüphesiz başarıya ulaşamazlar." dedi.'),
  ('tr.diyanet', 12, 24, 'And olsun ki kadın Yusuf\'a karşı istekli idi; Rabbin\'den bir işaret görmeseydi Yusuf da onu isteyecekti. İşte ondan kötülüğü ve fenalığı böylece engelledik. Doğrusu o bizim çok samimi kullarımızdandır.'),
  ('tr.diyanet', 12, 25, 'İkisi de kapıya koştu, kadın arkadan Yusuf\'un gömleğini yırttı; kapının önünde kocasına rastladılar. Kadın kocasına "Ailene fenalık etmek isteyen bir kimsenin cezası ya hapis ya da can yakıcı bir azab olmalıdır" dedi.'),
  ('tr.diyanet', 12, 26, 'Yusuf: "Beni kendine o çağırdı" dedi. Kadın tarafından bir şahit, "Eğer gömleği önden yırtılmışsa kadın doğru söylemiş, erkek yalancılardandır; şayet gömleği arkadan yırtılmışsa kadın yalan söylemiştir, erkek doğrulardandır" diye şahidlik etti.'),
  ('tr.diyanet', 12, 27, 'Yusuf: "Beni kendine o çağırdı" dedi. Kadın tarafından bir şahit, "Eğer gömleği önden yırtılmışsa kadın doğru söylemiş, erkek yalancılardandır; şayet gömleği arkadan yırtılmışsa kadın yalan söylemiştir, erkek doğrulardandır" diye şahidlik etti.'),
  ('tr.diyanet', 12, 28, 'Kocası gömleğin arkadan yırtılmış olduğunu görünce, karısına hitaben "Doğrusu bu sizin hilenizdir, siz kadınların fendi büyüktür" dedi. Yusuf\'a dönerek: "Yusuf! Sen bundan kimseye bahsetme"; kadına dönerek: "Sen de günahının bağışlanmasını dile, çünkü suçlulardansın" dedi.'),
  ('tr.diyanet', 12, 29, 'Kocası gömleğin arkadan yırtılmış olduğunu görünce, karısına hitaben "Doğrusu bu sizin hilenizdir, siz kadınların fendi büyüktür" dedi. Yusuf\'a dönerek: "Yusuf! Sen bundan kimseye bahsetme"; kadına dönerek: "Sen de günahının bağışlanmasını dile, çünkü suçlulardansın" dedi.'),
  ('tr.diyanet', 12, 30, 'Şehirde bir takım kadınlar: "Vezirin karısı kölesinin olmak istiyormuş; sevgisi bağrını yakmış; doğrusu onun besbelli sapıtmış olduğunu görüyoruz." dediler.'),
  ('tr.diyanet', 12, 31, 'Kadınların kendisini yermesini işitince onları davet etti; koltuklar hazırladı; geldiklerinde her birine birer bıçak verdi. Yusuf\'a: "Yanlarına çık" dedi. Kadınlar Yusuf\'u görünce şaşıp ellerini kestiler ve "Allah\'ı tenzih ederiz ama, bu insan değil ancak çok güzel bir melektir" dediler.'),
  ('tr.diyanet', 12, 32, 'Vezirin karısı: "İşte sözünü edip beni yerdiğiniz budur. And olsun ki onun olmak istedim, fakat o iffetinden dolayı çekindi. Emrimi yine yapmazsa, and olsun ki hapse tıkılacak ve kahre uğrayanlardan olacak."'),
  ('tr.diyanet', 12, 33, 'Yusuf: "Rabbim! Hapis benim için, bunların istediklerini yapmaktan daha iyidir. Eğer tuzaklarını benden uzaklaştırmazsan onlara meyleder ve bilmeyenlerden olurum." dedi.'),
  ('tr.diyanet', 12, 34, 'Rabbi onun duasını kabul etti ve kadınların tuzağına engel oldu. Zira O, işitir ve bilir.'),
  ('tr.diyanet', 12, 35, 'Sonra, kadının ailesi delilleri Yusuf\'un lehinde gördüğü halde, onu bir süre için hapsetmeyi uygun buldu.'),
  ('tr.diyanet', 12, 36, 'Hapse, onunla beraber, iki genç daha girdi. Biri, "Rüyamda şaraplık üzüm sıktığımı gördüm" dedi; diğeri "Başımın üzerinde, kuşların yediği bir ekmek taşıdığımı gördüm" dedi. "Bize bunu yorumla; senin iyi bir kimse olduğunu görüyoruz"'),
  ('tr.diyanet', 12, 37, 'Yusuf: "Rabbimin bana öğrettiği bilgi ile, daha yiyeceğiniz yemek gelmeden size onu yorumlarım. Doğrusu ben, Allah\'a inanmayan ve ahireti inkar eden, bir milletin dinini bırakmışımdır.'),
  ('tr.diyanet', 12, 38, 'Atalarım İbrahim, İshak ve Yakub\'un dinine uydum. Allah\'a herhangi bir ortak koşmak bize yaraşmaz; bu, Allah\'ın bize ve insanlara olan lütfudur; fakat insanların çoğu şükretmez" dedi.'),
  ('tr.diyanet', 12, 39, '"Ey mahpus arkadaşlarım! Ayrı ayrı bir sürü uydurma rabler mi daha iyidir, yoksa her şeyden üstün tek Allah mı?"'),
  ('tr.diyanet', 12, 40, '"Allah\'ı bırakıp taptığınız, sizin ve babalarınızın adlandırdığı putlardan başka bir şey değildir. Allah onların doğru olduğuna dair bir delil indirmemiştir. Hüküm vermek ancak Allah\'a aittir; kendisinden başkasına değil, O\'na tapmanızı emretmiştir. Bu, dosdoğru dindir, fakat insanların çoğu bilmezler".'),
  ('tr.diyanet', 12, 41, '"Ey mahpus arkadaşlarım! Biriniz efendinize şarap sunacak, diğeri asılacak ve kuşlar başından yiyecektir. Sorduğunuz iş işte böylece kesinleşmiştir."'),
  ('tr.diyanet', 12, 42, 'İkisinden, kurtulacağını sandığı kimseye Yusuf: "Efendinin yanında beni an" dedi. Ama şeytan efendisine onu hatırlatmayı unutturdu ve Yusuf bu yüzden daha birkaç yıl hapiste kaldı.'),
  ('tr.diyanet', 12, 43, 'Hükümdar: "Ben, yedi semiz ineği yedi zayıf ineğin yediğini; yedi yeşil başak ve bir o kadar da kurumuş başak görüyorum. Ey ileri gelenler! Eğer rüya yormasını biliyorsanız rüyamı söyleyiniz." dedi.'),
  ('tr.diyanet', 12, 44, 'Etrafındakiler: "Bir takım karışık rüyalar; biz böyle rüyaların yorumunu bilmeyiz" dediler.'),
  ('tr.diyanet', 12, 45, 'Hapisteki iki kişiden kurtulmuş olanı, nice zaman sonra Yusuf\'u hatırladı ve: "Ben size bunu yorumlayacağım, hele beni gönderin" dedi.'),
  ('tr.diyanet', 12, 46, 'Hapishaneye varıp: "Ey doğru sözlü Yusuf! Rüyada görülen yedi semiz ineği yedi zayıf ineğin yemesi; yedi yeşil başak ve bir o kadar kuru başak nedir? Bize yorumla, ben de insanlara ulaştırayım da bilsinler" dedi.'),
  ('tr.diyanet', 12, 47, 'Yusuf: "Devamlı yedi sene ekin ekip, biçtiğiniz ekinin yediğinizden artanını başağında bırakın."'),
  ('tr.diyanet', 12, 48, '"Sonra bunun ardından yedi kurak yıl gelir, bütün biriktirdiğinizi yer, yalnız az bir miktar saklarsınız."'),
  ('tr.diyanet', 12, 49, '"Sonra, halkın yağmur göreceği bir yıl gelir, o zaman sıkıp sağarlar" dedi.'),
  ('tr.diyanet', 12, 50, 'Hükümdar: "Onu bana getirin" dedi. Yusuf\'a elçi gelince, "Efendine dön, kadınlar niçin ellerini kesmişlerdi bir sor; doğrusu Rabbim onların hilesini bilir" dedi.'),
  ('tr.diyanet', 12, 51, 'Hükümdar kadınlara: "Yusuf\'un olmak istediğiniz zaman durumunuz neydi?" dedi. Kadınlar, "Haşa! Onun bir fenalığını görmedik" dediler. Vezirin karısı: "Şimdi gerçek ortaya çıktı; onun olmak isteyen bendim; doğrusu Yusuf doğrulardandır" dedi.'),
  ('tr.diyanet', 12, 52, 'Yusuf, "Maksadım, vezire, gıyabında ihanet etmediğimi, hainlerin tuzaklarını Allah\'ın başarıya erdirmediğini bilmesini sağlamaktı" dedi.'),
  ('tr.diyanet', 12, 53, '"Ben nefsimi temize çıkarmam; çünkü nefs, Rabbimin merhameti olmadıkça, kötülüğü emreder. Doğrusu Rabbim bağışlayandır, merhamet edendir."'),
  ('tr.diyanet', 12, 54, 'Hükümdar: "Onu bana getirin, yanıma alayım" dedi. Onunla konuşunca: "Bugün senin yanımızda önemli bir yerin ve güvenilir bir durumun vardır." dedi.'),
  ('tr.diyanet', 12, 55, 'Yusuf: "Beni memleketin hazinelerine memur et, çünkü ben korumasını ve yönetmesini bilirim" dedi.'),
  ('tr.diyanet', 12, 56, 'Yusuf\'u böylece o memlekete yerleştirdik; istediği yerlerde oturabilirdi. Rahmetimizi tıpkı bu misalde olduğu gibi istediğimize veririz; iyi davrananların ecrini zayi etmeyiz.'),
  ('tr.diyanet', 12, 57, 'Ama ahiret ecri, inananlar ve Allah\'a karşı gelmekten sakınanlar için daha iyidir.'),
  ('tr.diyanet', 12, 58, 'Yusuf\'un kardeşleri gelip yanına girdiler. Kendisini tanımadıkları halde o onları tanıdı.'),
  ('tr.diyanet', 12, 59, 'Onların yüklerini hazırlatınca şöyle dedi: "Baba bir kardeşinizi bana getirin. Sizlere ölçüyü bol tuttuğumu ve benim misafir konuklayanların en iyisi olduğumu görmüyor musunuz?"'),
  ('tr.diyanet', 12, 60, '"Eğer onu bana getirmezseniz bundan böyle benden bir ölçek bile alamazsınız ve bana artık yaklaşmayın da."'),
  ('tr.diyanet', 12, 61, 'Kardeşleri: "Babasını ikna etmeye çalışacağız ve her halde bunu yaparız" dediler.'),
  ('tr.diyanet', 12, 62, 'Yusuf adamlarına: "Karşılık olarak getirdiklerini de yüklerine koyun. Belki ailelerine varınca, onu anlarlar da bir daha dönerler" dedi.'),
  ('tr.diyanet', 12, 63, 'Babalarına döndüklerinde, "Ey babamız! Bize yiyecek yasak edildi, kardeşimizi bizimle beraber gönder de yiyecek alalım. Onu elbette koruruz" dediler.'),
  ('tr.diyanet', 12, 64, '"Daha önce kardeşini size emanet ettiğim gibi, şimdi onu emanet eder miyim? Ama Allah en iyi koruyandır, O merhametlilerin merhametlisidir" dedi.'),
  ('tr.diyanet', 12, 65, 'Yüklerini açınca karşılık olarak götürdükleri mallarının kendilerine iade edilmiş olduğunu gördüler. "Ey babamız! Daha ne isteriz; işte mallarımız da bize iade edilmiş; ailemize onunla yine yiyecek getirir, kardeşimizi de korur ve bir deve yükü de artırmış oluruz; esasen bu az bir şeydir" dediler.'),
  ('tr.diyanet', 12, 66, 'Babaları: "Hepiniz helak olmadıkça onu bana geri getireceğinize dair Allah\'a karşı sağlam bir söz vermezseniz, sizinle göndermeyeceğim" dedi. Söz verdiklerinde: "Sözümüze Allah vekildir" dedi.'),
  ('tr.diyanet', 12, 67, 'Babaları: "Oğullarım! Tek bir kapıdan değil, ayrı ayrı kapılardan girin. Ama Allah katında size bir faydam olmaz, hüküm ancak Allah\'ındır, O\'na güvendim, güvenenler de O\'na güvensinler" dedi.'),
  ('tr.diyanet', 12, 68, 'Babalarının emrettiği gibi girdiler. Esasen bu, Allah katında onlara bir fayda sağlamazdı, ancak Yakub içindeki arzuyu ortaya koymuş oldu. O, şüphesiz kendisine öğrettiğimizi bilir fakat insanların çoğu bilmezler.'),
  ('tr.diyanet', 12, 69, 'Yusuf\'un yanına girdiklerinde, kardeşini bağrına bastı ve: "Ben senin kardeşinim, onların yaptıklarına artık üzülme" dedi.'),
  ('tr.diyanet', 12, 70, 'Yusuf onların yüklerini yükletirken, bir su kabını kardeşinin yüküne koydurdu. Sonra bir münadi şöyle bağırdı: "Ey kervancılar, siz hırsızsınız!"'),
  ('tr.diyanet', 12, 71, 'Geri dönerek, "Ne kaybettiniz?" dediler.'),
  ('tr.diyanet', 12, 72, '"Hükümdarın su kabını kaybettik, onu getirene bir deve yükü mükafat verilecek, buna ben kefil oluyorum" dediler.'),
  ('tr.diyanet', 12, 73, '"Allah\'a yemin ederiz ki memleketi ifsat etmeğe gelmediğimizi ve hırsız da olmadığımızı biliyorsunuz" dediler.'),
  ('tr.diyanet', 12, 74, '"Yalancı iseniz, hırsızlığın cezası nedir?" dediler.'),
  ('tr.diyanet', 12, 75, '"Cezası, kimin yükünde bulunursa, ceza olarak ona el konulur; biz zalimleri böyle cezalandırırız" dediler.'),
  ('tr.diyanet', 12, 76, 'Yusuf kardeşinin yükünden önce onlarınkini aramaya başladı; sonra kardeşinin yükünden su kabını çıkardı. İşte biz Yusuf\'a böyle bir plan kullanmasını vahyettik. Çünkü hükümdarın kanunlarına göre kardeşini alıkoyamazdı, meğer ki Allah dileye. Dilediğimizi derecelerle yükseltiriz. Her ilim sahibinden üstün bir bilen bulunur.'),
  ('tr.diyanet', 12, 77, '"Çalmışsa, daha önce kardeşi de çalmıştı" dediler. Yusuf bunu içinde sakladı, onlara açmadı. İçinden, "Durumunuz pek kötüdür; anlattığınızı Allah daha iyi bilir" dedi.'),
  ('tr.diyanet', 12, 78, 'Kardeşleri: "Ey Vezir! Onun yaşlanmış, kocamış bir babası vardır. Bizden birini onun yerine al. Doğrusu biz senin iyi davrananlardan olduğunu görüyoruz" dediler.'),
  ('tr.diyanet', 12, 79, '"Maazallah! Biz, malımızı kimde bulmuşsak ancak onu alıkoruz, yoksa haksızlık etmiş oluruz" dedi.'),
  ('tr.diyanet', 12, 80, 'Ümidsizliğe düşünce, konuşmak üzere bir kenara çekildiler. Büyükleri şöyle dedi: "Babanızın Allah\'a karşı sizden bir söz aldığını, daha önce Yusuf meselesinde de ileri gittiğinizi bilmiyor musunuz? Artık babam bana izin verene veya Allah hakkımda hüküm verene kadar ki O, hükmedenlerin en iyisidir bu yerden ayrılmayacağım. Siz dönün, babanıza gidin ve deyin ki: Ey Babamız! Senin oğlun hırsızlık yaptı, bu bildiğimizden başka bir şey görmedik; görülmeyeni de bilmeyiz; bulunduğumuz kasabanın halkına ve beraberinde olduğumuz kervana da sorabilirsin; biz şüphesiz doğru söylüyoruz."'),
  ('tr.diyanet', 12, 81, 'Yakup: "Sizi nefsiniz bir iş yapmaya sürükledi, artık bana güzelce sabır gerekir; belki Allah hepsini birden bana getirecektir, çünkü O bilendir, hakimdir" dedi.'),
  ('tr.diyanet', 12, 82, 'Onlara sırt çevirdi, "Vah, Yusuf\'a yazık oldu!" dedi ve üzüntüden gözlerine ak düştü. Artık acısını içinde saklıyordu.'),
  ('tr.diyanet', 12, 83, 'Onlara sırt çevirdi, "Vah, Yusuf\'a yazık oldu!" dedi ve üzüntüden gözlerine ak düştü. Artık acısını içinde saklıyordu.'),
  ('tr.diyanet', 12, 84, 'Onlara sırt çevirdi, "Vah, Yusuf\'a yazık oldu!" dedi ve üzüntüden gözlerine ak düştü. Artık acısını içinde saklıyordu.'),
  ('tr.diyanet', 12, 85, '"Allah\'a yemin ederiz ki, Yusuf\'u anıp durman seni bitkin düşürecek veya helak olacaksın" dediler.'),
  ('tr.diyanet', 12, 86, 'Yakup: "Ben üzüntü ve tasamı yalnız Allah\'a açarım. Allah katından, sizin bilmediklerinizi bilirim" dedi.'),
  ('tr.diyanet', 12, 87, '"Ey Oğullarım! Gidin, Yusuf\'u ve kardeşini arayın. Allah\'ın rahmetinden ümidinizi kesmeyin; doğrusu kafirlerden başkası Allah\'ın rahmetinden ümidini kesmez."'),
  ('tr.diyanet', 12, 88, 'Kardeşleri vezirin yanına vardıklarında: "Ey Vezir! Biz ve çoluk çocuğumuz darlığa uğradık; pek değersiz bir malla geldik; ölçeği bize tam yap ve sadaka ver; Allah sadaka verenleri şüphesiz mükafatlandırır" dediler.'),
  ('tr.diyanet', 12, 89, '"Siz, Yusuf ve kardeşine bilmeden neler yaptığınızın farkında mısınız?" dedi.'),
  ('tr.diyanet', 12, 90, '"Yoksa sen Yusuf musun?" dediler. "Ben Yusuf\'um, bu da kardeşim. Allah bize iyilikte bulundu; doğrusu kim kötülükten sakınır ve sabrederse bilsin ki Allah iyi davrananların ecrini katiyen zayi etmez" dedi..'),
  ('tr.diyanet', 12, 91, '"Allah\'a yemin ederiz ki, Allah seni bizden üstün tutmuştur; doğrusu biz suç işlemiştik" dediler.'),
  ('tr.diyanet', 12, 92, 'Yusuf: "Bugün azarlanacak değilsiniz, Allah sizi bağışlar. O, merhametlilerin merhametlisidir. Bu gömleğimi götürün, babamın yüzüne sürün, görmeğe başlar; bütün çoluk çocuğunuzla bana gelin" dedi.'),
  ('tr.diyanet', 12, 93, 'Yusuf: "Bugün azarlanacak değilsiniz, Allah sizi bağışlar. O, merhametlilerin merhametlisidir. Bu gömleğimi götürün, babamın yüzüne sürün, görmeğe başlar; bütün çoluk çocuğunuzla bana gelin" dedi.'),
  ('tr.diyanet', 12, 94, 'Kervan, memleketlerine dönmek üzere ayrıldığında, babaları: "Doğrusu ben Yusuf\'un kokusunu duyuyorum; ne olur bana bunak demeyin" dedi.'),
  ('tr.diyanet', 12, 95, 'Çevresindekiler: "Allah\'a yemin ederiz ki sen, hala eski şaşkınlığındasın" dediler.'),
  ('tr.diyanet', 12, 96, 'Müjdeci gelip, gömleği Yakub\'un yüzüne bırakınca, hemen gözleri açıldı. Bunun üzerine Yakub "Ben size, Allah katından sizin bilmediğinizi biliyorum dememiş miydim?" dedi.'),
  ('tr.diyanet', 12, 97, 'Oğulları: "Ey Babamız! Suçlarımızın bağışlanmasını dile, bizler hiç şüphesiz suçluyuz" dediler.'),
  ('tr.diyanet', 12, 98, 'Yakub: "Rabbim\'den bağışlanmanızı dileyeceğim; O şüphesiz bağışlar ve merhamet eder" dedi.'),
  ('tr.diyanet', 12, 99, 'Yusuf\'un yanına geldiklerinde, o, anasını babasını bağrına bastı, "Allah\'ın dileğince, güven içinde Mısır\'da yerleşin" dedi.'),
  ('tr.diyanet', 12, 100, 'Ana babasını tahtın üzerine oturttu, hepsi onun önünde (Allah\'a secde edip) eğildiler. O zaman Yusuf: "Babacığım! İşte bu, vaktiyle gördüğüm rüyanın çıkışıdır; Rabbim onu gerçekleştirdi. Şeytan, benimle kardeşlerimin arasını bozduktan sonra, beni hapisten çıkaran, sizi çölden getiren Rabbim bana pek çok iyilikte bulundu. Doğrusu Rabbim dilediğine lütufkardır, O şüphesiz bilendir, Hakim\'dir" dedi.'),
  ('tr.diyanet', 12, 101, '"Rabbim! Bana hükümranlık verdin, rüyaların yorumunu öğrettin. Ey göklerin ve yerin yaradanı! Dünya ve ahirette işlerimi yoluna koyan sensin; benim canımı müslüman olarak al ve beni iyilere kat."'),
  ('tr.diyanet', 12, 102, 'Sana böylece vahyettiklerimiz, gaybe ait haberlerdir. Onlar elbirliği edip düzen kurdukları zaman yanlarında değildin; sen ne kadar yürekten istersen iste, insanların çoğu inanmazlar.'),
  ('tr.diyanet', 12, 103, 'Sana böylece vahyettiklerimiz, gaybe ait haberlerdir. Onlar elbirliği edip düzen kurdukları zaman yanlarında değildin; sen ne kadar yürekten istersen iste, insanların çoğu inanmazlar.'),
  ('tr.diyanet', 12, 104, 'Oysa sen buna karşılık onlardan bir ücret de istemiyorsun. Kuran, alemler için sadece bir öğüttür.'),
  ('tr.diyanet', 12, 105, 'Göklerde ve yerde nice belgeler vardır ki, yanlarından yüzlerini çevirerek geçerler.'),
  ('tr.diyanet', 12, 106, 'Onların çoğu, ortak koşmadan Allah\'a inanmazlar.'),
  ('tr.diyanet', 12, 107, 'Allah tarafından, onları kuşatacak bir azaba uğramalarından veya farkına varmadan, kıyamet saatinin ansızın gelmesinden güvende midirler?'),
  ('tr.diyanet', 12, 108, 'De ki: "Benim yolum budur; ben ve bana uyanlar bilerek insanları Allah\'a çağırırız. Allah\'ı noksan sıfatlardan tenzih ederim. Ben asla Allah\'a eş koşanlardan değilim."'),
  ('tr.diyanet', 12, 109, 'Senden önce kasabalar halkından şüphesiz, kendilerine vahyettiğimiz bir takım insanlar gönderdik. Yeryüzünde dolaşmıyorlar mı ki, kendilerinden önce geçenlerin sonlarının ne olduğunu görsünler? Ahiret yurdu Allah\'a karşı gelmekten sakınanlar için hayırlıdır. Akletmez misiniz?'),
  ('tr.diyanet', 12, 110, 'Öyle ki, peygamberler ümitsizliğe düşüp, yalanlandıklarını sandıkları bir sırada onlara yardımımız gelmiştir. Böylece, istediğimizi kurtarırız. Azabımız suçlu milletten geri çevrilemeyecektir.'),
  ('tr.diyanet', 12, 111, 'And olsun ki, peygamberlerin kıssalarında, aklı olanlar için ibretler vardır. Kuran uydurulabilen bir söz değildir. Fakat kendinden önceki Kitapları tasdik eden, inanan millete her şeyi açıklayan, doğru yolu gösteren bir rehber ve rahmettir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 12, 1, 'Alif, laam, raa. Ini adalah ayat-ayat Kitab (Al Quran) yang nyata (dari Allah).'),
  ('id.indonesian', 12, 2, 'Sesungguhnya Kami menurunkannya berupa Al Quran dengan berbahasa Arab, agar kamu memahaminya.'),
  ('id.indonesian', 12, 3, 'Kami menceritakan kepadamu kisah yang paling baik dengan mewahyukan Al Quran ini kepadamu, dan sesungguhnya kamu sebelum (Kami mewahyukan)nya adalah termasuk orang-orang yang belum mengetahui.'),
  ('id.indonesian', 12, 4, '(Ingatlah), ketika Yusuf berkata kepada ayahnya: "Wahai ayahku, sesungguhnya aku bermimpi melihat sebelas bintang, matahari dan bulan; kulihat semuanya sujud kepadaku".'),
  ('id.indonesian', 12, 5, 'Ayahnya berkata: "Hai anakku, janganlah kamu ceritakan mimpimu itu kepada saudara-saudaramu, maka mereka membuat makar (untuk membinasakan)mu. Sesungguhnya syaitan itu adalah musuh yang nyata bagi manusia".'),
  ('id.indonesian', 12, 6, 'Dan demikianlah Tuhanmu, memilih kamu (untuk menjadi Nabi) dan diajarkan-Nya kepadamu sebahagian dari ta\'bir mimpi-mimpi dan disempurnakan-Nya nikmat-Nya kepadamu dan kepada keluarga Ya\'qub, sebagaimana Dia telah menyempurnakan nikmat-Nya kepada dua orang bapakmu sebelum itu, (yaitu) Ibrahim dan Ishak. Sesungguhnya Tuhanmu Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 12, 7, 'Sesungguhnya ada beberapa tanda-tanda kekuasaan Allah pada (kisah) Yusuf dan saudara-saudaranya bagi orang-orang yang bertanya.'),
  ('id.indonesian', 12, 8, '(Yaitu) ketika mereka berkata: "Sesungguhnya Yusuf dan saudara kandungnya (Bunyamin) lebih dicintai oleh ayah kita dari pada kita sendiri, padahal kita (ini) adalah satu golongan (yang kuat). Sesungguhnya ayah kita adalah dalam kekeliruan yang nyata.'),
  ('id.indonesian', 12, 9, 'Bunuhlah Yusuf atau buanglah dia kesuatu daerah (yang tak dikenal) supaya perhatian ayahmu tertumpah kepadamu saja, dan sesudah itu hendaklah kamu menjadi orang-orang yang baik".'),
  ('id.indonesian', 12, 10, 'Seorang diantara mereka berkata: "Janganlah kamu bunuh Yusuf, tetapi masukkanlah dia ke dasar sumur supaya dia dipungut oleh beberapa orang musafir, jika kamu hendak berbuat".'),
  ('id.indonesian', 12, 11, 'Mereka berkata: "Wahai ayah kami, apa sebabnya kamu tidak mempercayai kami terhadap Yusuf, padahal sesungguhnya kami adalah orang-orang yang mengingini kebaikan baginya.'),
  ('id.indonesian', 12, 12, 'Biarkanlah dia pergi bersama kami besok pagi, agar dia (dapat) bersenang-senang dan (dapat) bermain-main, dan sesungguhnya kami pasti menjaganya".'),
  ('id.indonesian', 12, 13, 'Berkata Ya\'qub: "Sesungguhnya kepergian kamu bersama Yusuf amat menyedihkanku dan aku khawatir kalau-kalau dia dimakan serigala, sedang kamu lengah dari padanya".'),
  ('id.indonesian', 12, 14, 'Mereka berkata: "Jika ia benar-benar dimakan serigala, sedang kami golongan (yang kuat), sesungguhnya kami kalau demikian adalah orang-orang yang merugi".'),
  ('id.indonesian', 12, 15, 'Maka tatkala mereka membawanya dan sepakat memasukkannya ke dasar sumur (lalu mereka masukkan dia), dan (di waktu dia sudah dalam sumur) Kami wahyukan kepada Yusuf: "Sesungguhnya kamu akan menceritakan kepada mereka perbuatan mereka ini, sedang mereka tiada ingat lagi".'),
  ('id.indonesian', 12, 16, 'Kemudian mereka datang kepada ayah mereka di sore hari sambil menangis.'),
  ('id.indonesian', 12, 17, 'Mereka berkata: "Wahai ayah kami, sesungguhnya kami pergi berlomba-lomba dan kami tinggalkan Yusuf di dekat barang-barang kami, lalu dia dimakan serigala; dan kamu sekali-kali tidak akan percaya kepada kami, sekalipun kami adalah orang-orang yang benar".'),
  ('id.indonesian', 12, 18, 'Mereka datang membawa baju gamisnya (yang berlumuran) dengan darah palsu. Ya\'qub berkata: "Sebenarnya dirimu sendirilah yang memandang baik perbuatan (yang buruk) itu; maka kesabaran yang baik itulah (kesabaranku). Dan Allah sajalah yang dimohon pertolongan-Nya terhadap apa yang kamu ceritakan".'),
  ('id.indonesian', 12, 19, 'Kemudian datanglah kelompok orang-orang musafir, lalu mereka menyuruh seorang pengambil air, maka dia menurunkan timbanya, dia berkata: "Oh; kabar gembira, ini seorang anak muda!" Kemudian mereka menyembunyikan dia sebagai barang dagangan. Dan Allah Maha Mengetahui apa yang mereka kerjakan.'),
  ('id.indonesian', 12, 20, 'Dan mereka menjual Yusuf dengan harga yang murah, yaitu beberapa dirham saja, dan mereka merasa tidak tertarik hatinya kepada Yusuf.'),
  ('id.indonesian', 12, 21, 'Dan orang Mesir yang membelinya berkata kepada isterinya: "Berikanlah kepadanya tempat (dan layanan) yang baik, boleh jadi dia bermanfaat kepada kita atau kita pungut dia sebagai anak". Dan demikian pulalah Kami memberikan kedudukan yang baik kepada Yusuf di muka bumi (Mesir), dan agar Kami ajarkan kepadanya ta\'bir mimpi. Dan Allah berkuasa terhadap urusan-Nya, tetapi kebanyakan manusia tiada mengetahuinya.'),
  ('id.indonesian', 12, 22, 'Dan tatkala dia cukup dewasa Kami berikan kepadanya hikmah dan ilmu. Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 12, 23, 'Dan wanita (Zulaikha) yang Yusuf tinggal di rumahnya menggoda Yusuf untuk menundukkan dirinya (kepadanya) dan dia menutup pintu-pintu, seraya berkata: "Marilah ke sini". Yusuf berkata: "Aku berlindung kepada Allah, sungguh tuanku telah memperlakukan aku dengan baik". Sesungguhnya orang-orang yang zalim tiada akan beruntung.'),
  ('id.indonesian', 12, 24, 'Sesungguhnya wanita itu telah bermaksud (melakukan perbuatan itu) dengan Yusuf, dan Yusufpun bermaksud (melakukan pula) dengan wanita itu andaikata dia tidak melihat tanda (dari) Tuhannya. Demikianlah, agar Kami memalingkan dari padanya kemungkaran dan kekejian. Sesungguhnya Yusuf itu termasuk hamba-hamba Kami yang terpilih.'),
  ('id.indonesian', 12, 25, 'Dan keduanya berlomba-lomba menuju pintu dan wanita itu menarik baju gamis Yusuf dari belakang hingga koyak dan kedua-duanya mendapati suami wanita itu di muka pintu. Wanita itu berkata: "Apakah pembalasan terhadap orang yang bermaksud berbuat serong dengan isterimu, selain dipenjarakan atau (dihukum) dengan azab yang pedih?"'),
  ('id.indonesian', 12, 26, 'Yusuf berkata: "Dia menggodaku untuk menundukkan diriku (kepadanya)", dan seorang saksi dari keluarga wanita itu memberikan kesaksiannya: "Jika baju gamisnya koyak di muka, maka wanita itu benar dan Yusuf termasuk orang-orang yang dusta.'),
  ('id.indonesian', 12, 27, 'Dan jika baju gamisnya koyak di belakang, maka wanita itulah yang dusta, dan Yusuf termasuk orang-orang yang benar".'),
  ('id.indonesian', 12, 28, 'Maka tatkala suami wanita itu melihat baju gamis Yusuf koyak di belakang berkatalah dia: "Sesungguhnya (kejadian) itu adalah diantara tipu daya kamu, sesungguhnya tipu daya kamu adalah besar".'),
  ('id.indonesian', 12, 29, '(Hai) Yusuf: "Berpalinglah dari ini, dan (kamu hai isteriku) mohon ampunlah atas dosamu itu, karena kamu sesungguhnya termasuk orang-orang yang berbuat salah".'),
  ('id.indonesian', 12, 30, 'Dan wanita-wanita di kota berkata: "Isteri Al Aziz menggoda bujangnya untuk menundukkan dirinya (kepadanya), sesungguhnya cintanya kepada bujangnya itu adalah sangat mendalam. Sesungguhnya kami memandangnya dalam kesesatan yang nyata".'),
  ('id.indonesian', 12, 31, 'Maka tatkala wanita itu (Zulaikha) mendengar cercaan mereka, diundangnyalah wanita-wanita itu dan disediakannya bagi mereka tempat duduk, dan diberikannya kepada masing-masing mereka sebuah pisau (untuk memotong jamuan), kemudian dia berkata (kepada Yusuf): "Keluarlah (nampakkanlah dirimu) kepada mereka". Maka tatkala wanita-wanita itu melihatnya, mereka kagum kepada (keelokan rupa)nya, dan mereka melukai (jari) tangannya dan berkata: "Maha sempurna Allah, ini bukanlah manusia. Sesungguhnya ini tidak lain hanyalah malaikat yang mulia".'),
  ('id.indonesian', 12, 32, 'Wanita itu berkata: "Itulah dia orang yang kamu cela aku karena (tertarik) kepadanya, dan sesungguhnya aku telah menggoda dia untuk menundukkan dirinya (kepadaku) akan tetapi dia menolak. Dan sesungguhnya jika dia tidak mentaati apa yang aku perintahkan kepadanya, niscaya dia akan dipenjarakan dan dia akan termasuk golongan orang-orang yang hina".'),
  ('id.indonesian', 12, 33, 'Yusuf berkata: "Wahai Tuhanku, penjara lebih aku sukai daripada memenuhi ajakan mereka kepadaku. Dan jika tidak Engkau hindarkan dari padaku tipu daya mereka, tentu aku akan cenderung untuk (memenuhi keinginan mereka) dan tentulah aku termasuk orang-orang yang bodoh".'),
  ('id.indonesian', 12, 34, 'Maka Tuhannya memperkenankan doa Yusuf dan Dia menghindarkan Yusuf dari tipu daya mereka. Sesungguhnya Dialah Yang Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 12, 35, 'Kemudian timbul pikiran pada mereka setelah melihat tanda-tanda (kebenaran Yusuf) bahwa mereka harus memenjarakannya sampai sesuatu waktu.'),
  ('id.indonesian', 12, 36, 'Dan bersama dengan dia masuk pula ke dalam penjara dua orang pemuda. Berkatalah salah seorang diantara keduanya: "Sesungguhnya aku bermimpi, bahwa aku memeras anggur". Dan yang lainnya berkata: "Sesungguhnya aku bermimpi, bahwa aku membawa roti di atas kepalaku, sebahagiannya dimakan burung". Berikanlah kepada kami ta\'birnya; sesungguhnya kami memandang kamu termasuk orang-orang yang pandai (mena\'birkan mimpi).'),
  ('id.indonesian', 12, 37, 'Yusuf berkata: "Tidak disampaikan kepada kamu berdua makanan yang akan diberikan kepadamu melainkan aku telah dapat menerangkan jenis makanan itu, sebelum makanan itu sampai kepadamu. Yang demikian itu adalah sebagian dari apa yang diajarkan kepadaku oleh Tuhanku. Sesungguhnya aku telah meninggalkan agama orang-orang yang tidak beriman kepada Allah, sedang mereka ingkar kepada hari kemudian.'),
  ('id.indonesian', 12, 38, 'Dan aku pengikut agama bapak-bapakku yaitu Ibrahim, Ishak dan Ya\'qub. Tiadalah patut bagi kami (para Nabi) mempersekutukan sesuatu apapun dengan Allah. Yang demikian itu adalah dari karunia Allah kepada kami dan kepada manusia (seluruhnya); tetapi kebanyakan manusia tidak mensyukuri (Nya).'),
  ('id.indonesian', 12, 39, 'Hai kedua penghuni penjara, manakah yang baik, tuhan-tuhan yang bermacam-macam itu ataukah Allah Yang Maha Esa lagi Maha Perkasa?'),
  ('id.indonesian', 12, 40, 'Kamu tidak menyembah yang selain Allah kecuali hanya (menyembah) nama-nama yang kamu dan nenek moyangmu membuat-buatnya. Allah tidak menurunkan suatu keteranganpun tentang nama-nama itu. Keputusan itu hanyalah kepunyaan Allah. Dia telah memerintahkan agar kamu tidak menyembah selain Dia. Itulah agama yang lurus, tetapi kebanyakan manusia tidak mengetahui".'),
  ('id.indonesian', 12, 41, 'Hai kedua penghuni penjara: "Adapun salah seorang diantara kamu berdua, akan memberi minuman tuannya dengan khamar; adapun yang seorang lagi maka ia akan disalib, lalu burung memakan sebagian dari kepalanya. Telah diputuskan perkara yang kamu berdua menanyakannya (kepadaku)".'),
  ('id.indonesian', 12, 42, 'Dan Yusuf berkata kepada orang yang diketahuinya akan selamat diantara mereka berdua: "Terangkanlah keadaanku kepada tuanmu". Maka syaitan menjadikan dia lupa menerangkan (keadaan Yusuf) kepada tuannya. Karena itu tetaplah dia (Yusuf) dalam penjara beberapa tahun lamanya.'),
  ('id.indonesian', 12, 43, 'Raja berkata (kepada orang-orang terkemuka dari kaumnya): "Sesungguhnya aku bermimpi melihat tujuh ekor sapi betina yang gemuk-gemuk dimakan oleh tujuh ekor sapi betina yang kurus-kurus dan tujuh bulir (gandum) yang hijau dan tujuh bulir lainnya yang kering". Hai orang-orang yang terkemuka: "Terangkanlah kepadaku tentang ta\'bir mimpiku itu jika kamu dapat mena\'birkan mimpi".'),
  ('id.indonesian', 12, 44, 'Mereka menjawab: "(Itu) adalah mimpi-mimpi yang kosong dan kami sekali-kali tidak tahu menta\'birkan mimpi itu".'),
  ('id.indonesian', 12, 45, 'Dan berkatalah orang yang selamat diantara mereka berdua dan teringat (kepada Yusuf) sesudah beberapa waktu lamanya: "Aku akan memberitakan kepadamu tentang (orang yang pandai) mena\'birkan mimpi itu, maka utuslah aku (kepadanya)".'),
  ('id.indonesian', 12, 46, '(Setelah pelayan itu berjumpa dengan Yusuf dia berseru): "Yusuf, hai orang yang amat dipercaya, terangkanlah kepada kami tentang tujuh ekor sapi betina yang gemuk-gemuk yang dimakan oleh tujuh ekor sapi betina yang kurus-kurus dan tujuh bulir (gandum) yang hijau dan (tujuh) lainnya yang kering agar aku kembali kepada orang-orang itu, agar mereka mengetahuinya".'),
  ('id.indonesian', 12, 47, 'Yusuf berkata: "Supaya kamu bertanam tujuh tahun (lamanya) sebagaimana biasa; maka apa yang kamu tuai hendaklah kamu biarkan dibulirnya kecuali sedikit untuk kamu makan.'),
  ('id.indonesian', 12, 48, 'Kemudian sesudah itu akan datang tujuh tahun yang amat sulit, yang menghabiskan apa yang kamu simpan untuk menghadapinya (tahun sulit), kecuali sedikit dari (bibit gandum) yang kamu simpan.'),
  ('id.indonesian', 12, 49, 'Kemudian setelah itu akan datang tahun yang padanya manusia diberi hujan (dengan cukup) dan dimasa itu mereka memeras anggur".'),
  ('id.indonesian', 12, 50, 'Raja berkata: "Bawalah dia kepadaku". Maka tatkala utusan itu datang kepada Yusuf, berkatalah Yusuf: "Kembalilah kepada tuanmu dan tanyakanlah kepadanya bagaimana halnya wanita-wanita yang telah melukai tangannya. Sesungguhnya Tuhanku, Maha Mengetahui tipu daya mereka".'),
  ('id.indonesian', 12, 51, 'Raja berkata (kepada wanita-wanita itu): "Bagaimana keadaanmu ketika kamu menggoda Yusuf untuk menundukkan dirinya (kepadamu)?" Mereka berkata: "Maha Sempurna Allah, kami tiada mengetahui sesuatu keburukan dari padanya". Berkata isteri Al Aziz: "Sekarang jelaslah kebenaran itu, akulah yang menggodanya untuk menundukkan dirinya (kepadaku), dan sesungguhnya dia termasuk orang-orang yang benar".'),
  ('id.indonesian', 12, 52, '(Yusuf berkata): "Yang demikian itu agar dia (Al Aziz) mengetahui bahwa sesungguhnya aku tidak berkhianat kepadanya di belakangnya, dan bahwasanya Allah tidak meridhai tipu daya orang-orang yang berkhianat.'),
  ('id.indonesian', 12, 53, 'Dan aku tidak membebaskan diriku (dari kesalahan), karena sesungguhnya nafsu itu selalu menyuruh kepada kejahatan, kecuali nafsu yang diberi rahmat oleh Tuhanku. Sesungguhnya Tuhanku Maha Pengampun lagi Maha Penyanyang.'),
  ('id.indonesian', 12, 54, 'Dan raja berkata: "Bawalah Yusuf kepadaku, agar aku memilih dia sebagai orang yang rapat kepadaku". Maka tatkala raja telah bercakap-cakap dengan dia, dia berkata: "Sesungguhnya kamu (mulai) hari ini menjadi seorang yang berkedudukan tinggi lagi dipercayai pada sisi kami".'),
  ('id.indonesian', 12, 55, 'Berkata Yusuf: "Jadikanlah aku bendaharawan negara (Mesir); sesungguhnya aku adalah orang yang pandai menjaga, lagi berpengetahuan".'),
  ('id.indonesian', 12, 56, 'Dan demikianlah Kami memberi kedudukan kepada Yusuf di negeri Mesir; (dia berkuasa penuh) pergi menuju kemana saja ia kehendaki di bumi Mesir itu. Kami melimpahkan rahmat Kami kepada siapa yang Kami kehendaki dan Kami tidak menyia-nyiakan pahala orang-orang yang berbuat baik.'),
  ('id.indonesian', 12, 57, 'Dan sesungguhnya pahala di akhirat itu lebih baik, bagi orang-orang yang beriman dan selalu bertakwa.'),
  ('id.indonesian', 12, 58, 'Dan saudara-saudara Yusuf datang (ke Mesir} lalu mereka masuk ke (tempat)nya. Maka Yusuf mengenal mereka, sedang mereka tidak kenal (lagi) kepadanya.'),
  ('id.indonesian', 12, 59, 'Dan tatkala Yusuf menyiapkan untuk mereka bahan makanannya, ia berkata: "Bawalah kepadaku saudaramu yang seayah dengan kamu (Bunyamin), tidakkah kamu melihat bahwa aku menyempurnakan sukatan dan aku adalah sebaik-baik penerima tamu?'),
  ('id.indonesian', 12, 60, 'Jika kamu tidak membawanya kepadaku, maka kamu tidak akan mendapat sukatan lagi dari padaku dan jangan kamu mendekatiku".'),
  ('id.indonesian', 12, 61, 'Mereka berkata: "Kami akan membujuk ayahnya untuk membawanya (ke mari) dan sesungguhnya kami benar-benar akan melaksanakannya".'),
  ('id.indonesian', 12, 62, 'Yusuf berkata kepada bujang-bujangnya: "Masukkanlah barang-barang (penukar kepunyaan mereka) ke dalam karung-karung mereka, supaya mereka mengetahuinya apabila mereka telah kembali kepada keluarganya, mudah-mudahan mereka kembali lagi".'),
  ('id.indonesian', 12, 63, 'Maka tatkala mereka telah kembali kepada ayah mereka (Ya\'qub) mereka berkata: "Wahai ayah kami, kami tidak akan mendapat sukatan (gandum) lagi, (jika tidak membawa saudara kami), sebab itu biarkanlah saudara kami pergi bersama-sama kami supaya kami mendapat sukatan, dan sesungguhnya kami benar benar akan menjaganya".'),
  ('id.indonesian', 12, 64, 'Berkata Ya\'qub: "Bagaimana aku akan mempercayakannya (Bunyamin) kepadamu, kecuali seperti aku telah mempercayakan saudaranya (Yusuf) kepada kamu dahulu?". Maka Allah adalah sebaik-baik Penjaga dan Dia adalah Maha Penyanyang diantara para penyanyang.'),
  ('id.indonesian', 12, 65, 'Tatkala mereka membuka barang-barangnya, mereka menemukan kembali barang-barang (penukaran) mereka, dikembalikan kepada mereka. Mereka berkata: "Wahai ayah kami apa lagi yang kita inginkan. Ini barang-barang kita dikembalikan kepada kita, dan kami akan dapat memberi makan keluarga kami, dan kami akan dapat memelihara saudara kami, dan kami akan mendapat tambahan sukatan (gandum) seberat beban seekor unta. Itu adalah sukatan yang mudah (bagi raja Mesir)".'),
  ('id.indonesian', 12, 66, 'Ya\'qub berkata: "Aku sekali-kali tidak akan melepaskannya (pergi) bersama-sama kamu, sebelum kamu memberikan kepadaku janji yang teguh atas nama Allah, bahwa kamu pasti akan membawanya kepadaku kembali, kecuali jika kamu dikepung musuh". Tatkala mereka memberikan janji mereka, maka Ya\'qub berkata: "Allah adalah saksi terhadap apa yang kita ucapkan (ini)".'),
  ('id.indonesian', 12, 67, 'Dan Ya\'qub berkata: "Hai anak-anakku janganlah kamu (bersama-sama) masuk dari satu pintu gerbang, dan masuklah dari pintu-pintu gerbang yang berlain-lain; namun demikian aku tiada dapat melepaskan kamu barang sedikitpun dari pada (takdir) Allah. Keputusan menetapkan (sesuatu) hanyalah hak Allah; kepada-Nya-lah aku bertawakkal dan hendaklah kepada-Nya saja orang-orang yang bertawakkal berserah diri".'),
  ('id.indonesian', 12, 68, 'Dan tatkala mereka masuk menurut yang diperintahkan ayah mereka, maka (cara yang mereka lakukan itu) tiadalah melepaskan mereka sedikitpun dari takdir Allah, akan tetapi itu hanya suatu keinginan pada diri Ya\'qub yang telah ditetapkannya. Dan sesungguhnya dia mempunyai pengetahuan, karena Kami telah mengajarkan kepadanya. Akan tetapi kebanyakan manusia tiada mengetahui.'),
  ('id.indonesian', 12, 69, 'Dan tatkala mereka masuk ke (tempat) Yusuf. Yusuf membawa saudaranya (Bunyamin) ke tempatnya, Yusuf berkata: "Sesungguhnya aku (ini) adalah saudaramu, maka janganlah kamu berdukacita terhadap apa yang telah mereka kerjakan".'),
  ('id.indonesian', 12, 70, 'Maka tatkala telah disiapkan untuk mereka bahan makanan mereka, Yusuf memasukkan piala (tempat minum) ke dalam karung saudaranya. Kemudian berteriaklah seseorang yang menyerukan: "Hai kafilah, sesungguhnya kamu adalah orang-orang yang mencuri".'),
  ('id.indonesian', 12, 71, 'Mereka menjawab, sambil menghadap kepada penyeru-penyeru itu: "Barang apakah yang hilang dari pada kamu?"'),
  ('id.indonesian', 12, 72, 'Penyeru-penyeru itu berkata: "Kami kehilangan piala raja, dan siapa yang dapat mengembalikannya akan memperoleh bahan makanan (seberat) beban unta, dan aku menjamin terhadapnya".'),
  ('id.indonesian', 12, 73, 'Saudara-saudara Yusuf menjawab "Demi Allah sesungguhnya kamu mengetahui bahwa kami datang bukan untuk membuat kerusakan di negeri (ini) dan kami bukanlah para pencuri".'),
  ('id.indonesian', 12, 74, 'Mereka berkata: "Tetapi apa balasannya jikalau kamu betul-betul pendusta? "'),
  ('id.indonesian', 12, 75, 'Mereka menjawab: "Balasannya, ialah pada siapa diketemukan (barang yang hilang) dalam karungnya, maka dia sendirilah balasannya (tebusannya)". Demikianlah kami memberi pembalasan kepada orang-orang yang zalim.'),
  ('id.indonesian', 12, 76, 'Maka mulailah Yusuf (memeriksa) karung-karung mereka sebelum (memeriksa) karung saudaranya sendiri, kemudian dia mengeluarkan piala raja itu dari karung saudaranya. Demikianlah Kami atur untuk (mencapai maksud) Yusuf. Tiadalah patut Yusuf menghukum saudaranya menurut undang-undang raja, kecuali Allah menghendaki-Nya. Kami tinggikan derajat orang yang Kami kehendaki; dan di atas tiap-tiap orang yang berpengetahuan itu ada lagi Yang Maha Mengetahui.'),
  ('id.indonesian', 12, 77, 'Mereka berkata: "Jika ia mencuri, maka sesungguhnya, telah pernah mencuri pula saudaranya sebelum itu". Maka Yusuf menyembunyikan kejengkelan itu pada dirinya dan tidak menampakkannya kepada mereka. Dia berkata (dalam hatinya): "Kamu lebih buruk kedudukanmu (sifat-sifatmu) dan Allah Maha Mengetahui apa yang kamu terangkan itu".'),
  ('id.indonesian', 12, 78, 'Mereka berkata: "Wahai Al Aziz, sesungguhnya ia mempunyai ayah yang sudah lanjut usianya, lantaran itu ambillah salah seorang diantara kami sebagai gantinya, sesungguhnya kami melihat kamu termasuk oranng-orang yang berbuat baik".'),
  ('id.indonesian', 12, 79, 'Berkata Yusuf: "Aku mohon perlindungan kepada Allah daripada menahan seorang, kecuali orang yang kami ketemukan harta benda kami padanya, jika kami berbuat demikian, maka benar-benarlah kami orang-orang yang zalim".'),
  ('id.indonesian', 12, 80, 'Maka tatkala mereka berputus asa dari pada (putusan) Yusuf mereka menyendiri sambil berunding dengan berbisik-bisik. Berkatalah yang tertua diantara mereka: "Tidakkah kamu ketahui bahwa sesungguhnya ayahmu telah mengambil janji dari kamu dengan nama Allah dan sebelum itu kamu telah menyia-nyiakan Yusuf. Sebab itu aku tidak akan meninggalkan negeri Mesir, sampai ayahku mengizinkan kepadaku (untuk kembali), atau Allah memberi keputusan terhadapku. Dan Dia adalah Hakim yang sebaik-baiknya".'),
  ('id.indonesian', 12, 81, 'Kembalilah kepada ayahmu dan katakanlah: "Wahai ayah kami! Sesungguhnya anakmu telah mencuri, dan kami hanya menyaksikan apa yang kami ketahui, dan sekali-kali kami tidak dapat menjaga (mengetahui) barang yang ghaib.'),
  ('id.indonesian', 12, 82, 'Dan tanyalah (penduduk) negeri yang kami berada disitu, dan kafilah yang kami datang bersamanya, dan sesungguhnya kami adalah orang-orang yang benar".'),
  ('id.indonesian', 12, 83, 'Ya\'qub berkata: "Hanya dirimu sendirilah yang memandang baik perbuatan (yang buruk) itu. Maka kesabaran yang baik itulah (kesabaranku). Mudah-mudahan Allah mendatangkan mereka semuanya kepadaku; sesungguhnya Dialah Yang Maha Mengetahui lagi Maha Bijaksana".'),
  ('id.indonesian', 12, 84, 'Dan Ya\'qub berpaling dari mereka (anak-anaknya) seraya berkata: "Aduhai duka citaku terhadap Yusuf", dan kedua matanya menjadi putih karena kesedihan dan dia adalah seorang yang menahan amarahnya (terhadap anak-anaknya).'),
  ('id.indonesian', 12, 85, 'Mereka berkata: "Demi Allah, senantiasa kamu mengingati Yusuf, sehingga kamu mengidapkan penyakit yang berat atau termasuk orang-orang yang binasa".'),
  ('id.indonesian', 12, 86, 'Ya\'qub menjawab: "Sesungguhnya hanyalah kepada Allah aku mengadukan kesusahan dan kesedihanku, dan aku mengetahui dari Allah apa yang kamu tiada mengetahuinya".'),
  ('id.indonesian', 12, 87, 'Hai anak-anakku, pergilah kamu, maka carilah berita tentang Yusuf dan saudaranya dan jangan kamu berputus asa dari rahmat Allah. Sesungguhnya tiada berputus asa dari rahmat Allah, melainkan kaum yang kafir".'),
  ('id.indonesian', 12, 88, 'Maka ketika mereka masuk ke (tempat) Yusuf, mereka berkata: "Hai Al Aziz, kami dan keluarga kami telah ditimpa kesengsaraan dan kami datang membawa barang-barang yang tak berharga, maka sempurnakanlah sukatan untuk kami, dan bersedekahlah kepada kami, sesungguhnya Allah memberi balasan kepada orang-orang yang bersedekah".'),
  ('id.indonesian', 12, 89, 'Yusuf berkata: "Apakah kamu mengetahui (kejelekan) apa yang telah kamu lakukan terhadap Yusuf dan saudaranya ketika kamu tidak mengetahui (akibat) perbuatanmu itu?".'),
  ('id.indonesian', 12, 90, 'Mereka berkata: "Apakah kamu ini benar-benar Yusuf?". Yusuf menjawab: "Akulah Yusuf dan ini saudaraku. Sesungguhnya Allah telah melimpahkan karunia-Nya kepada kami". Sesungguhnya barang siapa yang bertakwa dan bersabar, maka sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik"'),
  ('id.indonesian', 12, 91, 'Mereka berkata: "Demi Allah, sesungguhnya Allah telah melebihkan kamu atas kami, dan sesungguhnya kami adalah orang-orang yang bersalah (berdosa)".'),
  ('id.indonesian', 12, 92, 'Dia (Yusuf) berkata: "Pada hari ini tak ada cercaan terhadap kamu, mudah-mudahan Allah mengampuni (kamu), dan Dia adalah Maha Penyayang diantara para penyayang".'),
  ('id.indonesian', 12, 93, 'Pergilah kamu dengan membawa baju gamisku ini, lalu letakkanlah dia kewajah ayahku, nanti ia akan melihat kembali; dan bawalah keluargamu semuanya kepadaku".'),
  ('id.indonesian', 12, 94, 'Tatkala kafilah itu telah ke luar (dari negeri Mesir) berkata ayah mereka: "Sesungguhnya aku mencium bau Yusuf, sekiranya kamu tidak menuduhku lemah akal (tentu kamu membenarkan aku)".'),
  ('id.indonesian', 12, 95, 'Keluarganya berkata: "Demi Allah, sesungguhnya kamu masih dalam kekeliruanmu yang dahulu".'),
  ('id.indonesian', 12, 96, 'Tatkala telah tiba pembawa kabar gembira itu, maka diletakkannya baju gamis itu ke wajah Ya\'qub, lalu kembalilah dia dapat melihat. Berkata Ya\'qub: "Tidakkah aku katakan kepadamu, bahwa aku mengetahui dari Allah apa yang kamu tidak mengetahuinya".'),
  ('id.indonesian', 12, 97, 'Mereka berkata: "Wahai ayah kami, mohonkanlah ampun bagi kami terhadap dosa-dosa kami, sesungguhnya kami adalah orang-orang yang bersalah (berdosa)".'),
  ('id.indonesian', 12, 98, 'Ya\'qub berkata: "Aku akan memohonkan ampun bagimu kepada Tuhanku. Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang".'),
  ('id.indonesian', 12, 99, 'Maka tatkala mereka masuk ke (tempat) Yusuf: Yusuf merangkul ibu bapanya dan dia berkata: "Masuklah kamu ke negeri Mesir, insya Allah dalam keadaan aman".'),
  ('id.indonesian', 12, 100, 'Dan ia menaikkan kedua ibu-bapanya ke atas singgasana. Dan mereka (semuanya) merebahkan diri seraya sujud kepada Yusuf. Dan berkata Yusuf: "Wahai ayahku inilah ta\'bir mimpiku yang dahulu itu; sesungguhnya Tuhanku telah menjadikannya suatu kenyataan. Dan sesungguhnya Tuhanku telah berbuat baik kepadaku, ketika Dia membebaskan aku dari rumah penjara dan ketika membawa kamu dari dusun padang pasir, setelah syaitan merusakkan (hubungan) antaraku dan saudara-saudaraku. Sesungguhnya Tuhanku Maha Lembut terhadap apa yang Dia kehendaki. Sesungguhnya Dialah Yang Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 12, 101, 'Ya Tuhanku, sesungguhnya Engkau telah menganugerahkan kepadaku sebahagian kerajaan dan telah mengajarkan kepadaku sebahagian ta\'bir mimpi. (Ya Tuhan) Pencipta langit dan bumi. Engkaulah Pelindungku di dunia dan di akhirat, wafatkanlah aku dalam keadaan Islam dan gabungkanlah aku dengan orang-orang yang saleh.'),
  ('id.indonesian', 12, 102, 'Demikian itu (adalah) diantara berita-berita yang ghaib yang Kami wahyukan kepadamu (Muhammad); padahal kamu tidak berada pada sisi mereka, ketika mereka memutuskan rencananya (untuk memasukkan Yusuf ke dalam sumur) dan mereka sedang mengatur tipu daya.'),
  ('id.indonesian', 12, 103, 'Dan sebahagian besar manusia tidak akan beriman -- walaupun kamu sangat menginginkannya.'),
  ('id.indonesian', 12, 104, 'Dan kamu sekali-kali tidak meminta upah kepada mereka (terhadap seruanmu ini), itu tidak lain hanyalah pengajaran bagi semesta alam.'),
  ('id.indonesian', 12, 105, 'Dan banyak sekali tanda-tanda (kekuasaan Allah) di langit dan di bumi yang mereka melaluinya, sedang mereka berpaling dari padanya.'),
  ('id.indonesian', 12, 106, 'Dan sebahagian besar dari mereka tidak beriman kepada Allah, melainkan dalam keadaan mempersekutukan Allah (dengan sembahan-sembahan lain).'),
  ('id.indonesian', 12, 107, 'Apakah mereka merasa aman dari kedatangan siksa Allah yang meliputi mereka, atau kedatangan kiamat kepada mereka secara mendadak, sedang mereka tidak menyadarinya?'),
  ('id.indonesian', 12, 108, 'Katakanlah: "Inilah jalan (agama)ku, aku dan orang-orang yang mengikutiku mengajak (kamu) kepada Allah dengan hujjah yang nyata, Maha Suci Allah, dan aku tiada termasuk orang-orang yang musyrik".'),
  ('id.indonesian', 12, 109, 'Kami tidak mengutus sebelum kamu, melainkan orang laki-laki yang Kami berikan wahyu kepadanya diantara penduduk negeri. Maka tidakkah mereka bepergian di muka bumi lalu melihat bagaimana kesudahan orang-orang sebelum mereka (yang mendustakan rasul) dan sesungguhnya kampung akhirat adalah lebih baik bagi orang-orang yang bertakwa. Maka tidakkah kamu memikirkannya?'),
  ('id.indonesian', 12, 110, 'Sehingga apabila para rasul tidak mempunyai harapan lagi (tentang keimanan mereka) dan telah meyakini bahwa mereka telah didustakan, datanglah kepada para rasul itu pertolongan Kami, lalu diselamatkan orang-orang yang Kami kehendaki. Dan tidak dapat ditolak siksa Kami dari pada orang-orang yang berdosa.'),
  ('id.indonesian', 12, 111, 'Sesungguhnya pada kisah-kisah mereka itu terdapat pengajaran bagi orang-orang yang mempunyai akal. Al Quran itu bukanlah cerita yang dibuat-buat, akan tetapi membenarkan (kitab-kitab) yang sebelumnya dan menjelaskan segala sesuatu, dan sebagai petunjuk dan rahmat bagi kaum yang beriman.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 13, 1, 'Alif, Lam, Meem, Ra. These are the verses of the Book; and what has been revealed to you from your Lord is the truth, but most of the people do not believe.'),
  ('en.sahih', 13, 2, 'It is Allah who erected the heavens without pillars that you [can] see; then He established Himself above the Throne and made subject the sun and the moon, each running [its course] for a specified term. He arranges [each] matter; He details the signs that you may, of the meeting with your Lord, be certain.'),
  ('en.sahih', 13, 3, 'And it is He who spread the earth and placed therein firmly set mountains and rivers; and from all of the fruits He made therein two mates; He causes the night to cover the day. Indeed in that are signs for a people who give thought.'),
  ('en.sahih', 13, 4, 'And within the land are neighboring plots and gardens of grapevines and crops and palm trees, [growing] several from a root or otherwise, watered with one water; but We make some of them exceed others in [quality of] fruit. Indeed in that are signs for a people who reason.'),
  ('en.sahih', 13, 5, 'And if you are astonished, [O Muhammad] - then astonishing is their saying, "When we are dust, will we indeed be [brought] into a new creation?" Those are the ones who have disbelieved in their Lord, and those will have shackles upon their necks, and those are the companions of the Fire; they will abide therein eternally.'),
  ('en.sahih', 13, 6, 'They impatiently urge you to bring about evil before good, while there has already occurred before them similar punishments [to what they demand]. And indeed, your Lord is full of forgiveness for the people despite their wrongdoing, and indeed, your Lord is severe in penalty.'),
  ('en.sahih', 13, 7, 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" You are only a warner, and for every people is a guide.'),
  ('en.sahih', 13, 8, 'Allah knows what every female carries and what the wombs lose [prematurely] or exceed. And everything with Him is by due measure.'),
  ('en.sahih', 13, 9, '[He is] Knower of the unseen and the witnessed, the Grand, the Exalted.'),
  ('en.sahih', 13, 10, 'It is the same [to Him] concerning you whether one conceals [his] speech or one publicizes it and whether one is hidden by night or conspicuous [among others] by day.'),
  ('en.sahih', 13, 11, 'For each one are successive [angels] before and behind him who protect him by the decree of Allah. Indeed, Allah will not change the condition of a people until they change what is in themselves. And when Allah intends for a people ill, there is no repelling it. And there is not for them besides Him any patron.'),
  ('en.sahih', 13, 12, 'It is He who shows you lightening, [causing] fear and aspiration, and generates the heavy clouds.'),
  ('en.sahih', 13, 13, 'And the thunder exalts [Allah] with praise of Him - and the angels [as well] from fear of Him - and He sends thunderbolts and strikes therewith whom He wills while they dispute about Allah; and He is severe in assault.'),
  ('en.sahih', 13, 14, 'To Him [alone] is the supplication of truth. And those they call upon besides Him do not respond to them with a thing, except as one who stretches his hands toward water [from afar, calling it] to reach his mouth, but it will not reach it [thus]. And the supplication of the disbelievers is not but in error [i.e. futility].'),
  ('en.sahih', 13, 15, 'And to Allah prostrates whoever is within the heavens and the earth, willingly or by compulsion, and their shadows [as well] in the mornings and the afternoons.'),
  ('en.sahih', 13, 16, 'Say, "Who is Lord of the heavens and earth?" Say, "Allah." Say, "Have you then taken besides Him allies not possessing [even] for themselves any benefit or any harm?" Say, "Is the blind equivalent to the seeing? Or is darkness equivalent to light? Or have they attributed to Allah partners who created like His creation so that the creation [of each] seemed similar to them?" Say, "Allah is the Creator of all things, and He is the One, the Prevailing."'),
  ('en.sahih', 13, 17, 'He sends down from the sky, rain, and valleys flow according to their capacity, and the torrent carries a rising foam. And from that [ore] which they heat in the fire, desiring adornments and utensils, is a foam like it. Thus Allah presents [the example of] truth and falsehood. As for the foam, it vanishes, [being] cast off; but as for that which benefits the people, it remains on the earth. Thus does Allah present examples.'),
  ('en.sahih', 13, 18, 'For those who have responded to their Lord is the best [reward], but those who did not respond to Him - if they had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby. Those will have the worst account, and their refuge is Hell, and wretched is the resting place.'),
  ('en.sahih', 13, 19, 'Then is he who knows that what has been revealed to you from your Lord is the truth like one who is blind? They will only be reminded who are people of understanding -'),
  ('en.sahih', 13, 20, 'Those who fulfill the covenant of Allah and do not break the contract,'),
  ('en.sahih', 13, 21, 'And those who join that which Allah has ordered to be joined and fear their Lord and are afraid of the evil of [their] account,'),
  ('en.sahih', 13, 22, 'And those who are patient, seeking the countenance of their Lord, and establish prayer and spend from what We have provided for them secretly and publicly and prevent evil with good - those will have the good consequence of [this] home -'),
  ('en.sahih', 13, 23, 'Gardens of perpetual residence; they will enter them with whoever were righteous among their fathers, their spouses and their descendants. And the angels will enter upon them from every gate, [saying],'),
  ('en.sahih', 13, 24, '"Peace be upon you for what you patiently endured. And excellent is the final home."'),
  ('en.sahih', 13, 25, 'But those who break the covenant of Allah after contracting it and sever that which Allah has ordered to be joined and spread corruption on earth - for them is the curse, and they will have the worst home.'),
  ('en.sahih', 13, 26, 'Allah extends provision for whom He wills and restricts [it]. And they rejoice in the worldly life, while the worldly life is not, compared to the Hereafter, except [brief] enjoyment.'),
  ('en.sahih', 13, 27, 'And those who disbelieved say, "Why has a sign not been sent down to him from his Lord?" Say, [O Muhammad], "Indeed, Allah leaves astray whom He wills and guides to Himself whoever turns back [to Him] -'),
  ('en.sahih', 13, 28, 'Those who have believed and whose hearts are assured by the remembrance of Allah. Unquestionably, by the remembrance of Allah hearts are assured."'),
  ('en.sahih', 13, 29, 'Those who have believed and done righteous deeds - a good state is theirs and a good return.'),
  ('en.sahih', 13, 30, 'Thus have We sent you to a community before which [other] communities have passed on so you might recite to them that which We revealed to you, while they disbelieve in the Most Merciful. Say, "He is my Lord; there is no deity except Him. Upon Him I rely, and to Him is my return."'),
  ('en.sahih', 13, 31, 'And if there was any qur\'an by which the mountains would be removed or the earth would be broken apart or the dead would be made to speak, [it would be this Qur\'an], but to Allah belongs the affair entirely. Then have those who believed not accepted that had Allah willed, He would have guided the people, all of them? And those who disbelieve do not cease to be struck, for what they have done, by calamity - or it will descend near their home - until there comes the promise of Allah. Indeed, Allah does not fail in [His] promise.'),
  ('en.sahih', 13, 32, 'And already were [other] messengers ridiculed before you, and I extended the time of those who disbelieved; then I seized them, and how [terrible] was My penalty.'),
  ('en.sahih', 13, 33, 'Then is He who is a maintainer of every soul, [knowing] what it has earned, [like any other]? But to Allah they have attributed partners. Say, "Name them. Or do you inform Him of that which He knows not upon the earth or of what is apparent of speech?" Rather, their [own] plan has been made attractive to those who disbelieve, and they have been averted from the way. And whomever Allah leaves astray - there will be for him no guide.'),
  ('en.sahih', 13, 34, 'For them will be punishment in the life of [this] world, and the punishment of the Hereafter is more severe. And they will not have from Allah any protector.'),
  ('en.sahih', 13, 35, 'The example of Paradise, which the righteous have been promised, is [that] beneath it rivers flow. Its fruit is lasting, and its shade. That is the consequence for the righteous, and the consequence for the disbelievers is the Fire.'),
  ('en.sahih', 13, 36, 'And [the believers among] those to whom We have given the [previous] Scripture rejoice at what has been revealed to you, [O Muhammad], but among the [opposing] factions are those who deny part of it. Say, "I have only been commanded to worship Allah and not associate [anything] with Him. To Him I invite, and to Him is my return."'),
  ('en.sahih', 13, 37, 'And thus We have revealed it as an Arabic legislation. And if you should follow their inclinations after what has come to you of knowledge, you would not have against Allah any ally or any protector.'),
  ('en.sahih', 13, 38, 'And We have already sent messengers before you and assigned to them wives and descendants. And it was not for a messenger to come with a sign except by permission of Allah. For every term is a decree.'),
  ('en.sahih', 13, 39, 'Allah eliminates what He wills or confirms, and with Him is the Mother of the Book.'),
  ('en.sahih', 13, 40, 'And whether We show you part of what We promise them or take you in death, upon you is only the [duty of] notification, and upon Us is the account.'),
  ('en.sahih', 13, 41, 'Have they not seen that We set upon the land, reducing it from its borders? And Allah decides; there is no adjuster of His decision. And He is swift in account.'),
  ('en.sahih', 13, 42, 'And those before them had plotted, but to Allah belongs the plan entirely. He knows what every soul earns, and the disbelievers will know for whom is the final home.'),
  ('en.sahih', 13, 43, 'And those who have disbelieved say, "You are not a messenger." Say, [O Muhammad], "Sufficient is Allah as Witness between me and you, and [the witness of] whoever has knowledge of the Scripture."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 13, 1, 'আলিফ-লাম-মীম-রা; এগুলো কিতাবের আয়াত। যা কিছু আপনার পালনকর্তার পক্ষ থেকে অবতীর্ণ হয়েছে, তা সত্য। কিন্তু অধিকাংশ মানুষ এতে বিশ্বাস করে না।'),
  ('bn.bengali', 13, 2, 'আল্লাহ, যিনি উর্ধ্বদেশে স্থাপন করেছেন আকাশমন্ডলীকে স্তম্ভ ব্যতীত। তোমরা সেগুলো দেখ। অতঃপর তিনি আরশের উপর অধিষ্ঠিত হয়েছেন। এবং সূর্য ও চন্দ্রকে কর্মে নিয়োজিত করেছেন। প্রত্যেকে নির্দিষ্ট সময় মোতাবেক আবর্তন করে। তিনি সকল বিষয় পরিচালনা করেন, নিদর্শনসমূহ প্রকাশ করেন, যাতে তোমরা স্বীয় পালনকর্তার সাথে সাক্ষাত সম্বন্ধে নিশ্চিত বিশ্বাসী হও।'),
  ('bn.bengali', 13, 3, 'তিনিই ভুমন্ডলকে বিস্তৃত করেছেন এবং তাতে পাহাড় পর্বত ও নদ-নদী স্থাপন করেছেন এবং প্রত্যেক ফলের মধ্যে দু’দু প্রকার সৃষ্টি করে রেখেছেন। তিনি দিনকে রাত্রি দ্বারা আবৃত করেন। এতে তাদের জন্যে নিদর্শণ রয়েছে, যারা চিন্তা করে।'),
  ('bn.bengali', 13, 4, 'এবং যমিনে বিভিন্ন শস্য ক্ষেত্র রয়েছে-একটি অপরটির সাথে সংলগ্ন এবং আঙ্গুরের বাগান আছে আর শস্য ও খজ্জꦣ2497;র রয়েছে-একটির মূল অপরটির সাথে মিলিত এবং কতক মিলিত নয়। এগুলো কে একই পানি দ্বারা সেচ করা হয়। আর আমি স্বাদে একটিকে অপরটির চাইতে উৎকৃষ্টতর করে দেই। এগুলোর মধ্যে নিদর্শণ রয়েছে তাদের জন্য যারা চিন্তা ভাবনা করে।'),
  ('bn.bengali', 13, 5, 'যদি আপনি বিস্ময়ের বিষয় চান, তবে তাদের একথা বিস্ময়কর যে, আমরা যখন মাটি হয়ে যাব, তখনও কি নতুন ভাবে সৃজিত হব? এরাই স্বীয় পালনকর্তার সত্তায় অবিশ্বাসী হয়ে গেছে, এদের গর্দানেই লৌহ-শৃংখল পড়বে এবং এরাই দোযখী এরা তাতে চিরকাল থাকবে।'),
  ('bn.bengali', 13, 6, 'এরা আপনার কাছে মঙ্গলের পরিবর্তে দ্রুত অমঙ্গল কামনা করে। তাদের পূর্বে অনুরূপ অনেক শাস্তিপ্রাপ্ত জনগোষ্ঠী অতিক্রান্ত হয়েছে। আপনার পালনকর্তা মানুষকে তাদের অন্যায় সত্বেও ক্ষমা করেন এবং আপনার পালনকর্তা কঠিন শাস্তিদাতা ও বটে।'),
  ('bn.bengali', 13, 7, 'কাফেররা বলেঃ তাঁর প্রতি তাঁর পালনকর্তার পক্ষ থেকে কোন নিদর্শন অবতীর্ণ হল না কেন? আপনার কাজ তো ভয় প্রদর্শন করাই এবং প্রত্যেক সম্প্রদায়ের জন্যে পথপ্রদর্শক হয়েছে।'),
  ('bn.bengali', 13, 8, 'আল্লাহ জানেন প্রত্যেক নারী যা গর্ভধারণ করে এবং গর্ভাশয়ে যা সঙ্কুচিত ও বর্ধিত হয়। এবং তাঁর কাছে প্রত্যেক বস্তুরই একটা পরিমাণ রয়েছে।'),
  ('bn.bengali', 13, 9, 'তিনি সকল গোপন ও প্রকাশ্য বিষয় অবগত, মহোত্তম, সর্বোচ্চ মর্যাদাবান।'),
  ('bn.bengali', 13, 10, 'তোমাদের মধ্যে কেউ গোপনে কথা বলুক বা তা সশব্দে প্রকাশ করুক, রাতের অন্ধকারে সে আত্নগোপন করুক বা প্রকাশ্য দিবালোকে বিচরণ করুক, সবাই তাঁর নিকট সমান।'),
  ('bn.bengali', 13, 11, 'তাঁর পক্ষ থেকে অনুসরণকারী রয়েছে তাদের অগ্রে এবং পশ্চাতে, আল্লাহর নির্দেশে তারা ওদের হেফাযত করে। আল্লাহ কোন জাতির অবস্থা পরিবর্তন করেন না, যে পর্যন্ত না তারা তাদের নিজেদের অবস্থা পরিবর্তন করে। আল্লাহ যখন কোন জাতির উপর বিপদ চান, তখন তা রদ হওয়ার নয় এবং তিনি ব্যতীত তাদের কোন সাহায্যকারী নেই।'),
  ('bn.bengali', 13, 12, 'তিনিই তোমাদেরকে বিদ্যুৎ দেখান ভয়ের জন্যে এবং আশার জন্যে এবং উক্ষিত করেন ঘন মেঘমালা।'),
  ('bn.bengali', 13, 13, 'তাঁর প্রশংসা পাঠ করে বজ্র এবং সব ফেরেশতা, সভয়ে। তিনি বজ্রপাত করেন, অতঃপর যাকে ইচছা, তাকে তা দ্বারা আঘাত করেন; তথাপি তারা আল্লাহ সম্পর্কে বিতন্ডা করে, অথচ তিনি মহাশক্তিশালী।'),
  ('bn.bengali', 13, 14, 'সত্যের আহবান একমাত্র তাঁরই এবং তাকে ছাড়া যাদেরকে ডাকে, তারা তাদের কোন কাজে আসে না; ওদের দৃষ্টান্ত সেরূপ, যেমন কেউ দু’ হাত পানির দিকে প্রসারিত করে যাতে পানি তার মুখে পৌঁছে যায়। অথচ পানি কোন সময় পৌঁছাবে না। কাফেরদের যত আহবান তার সবই পথভ্রষ্টতা।'),
  ('bn.bengali', 13, 15, 'আল্লাহকে সেজদা করে যা কিছু নভোমন্ডলে ও ভূমন্ডলে আছে ইচ্ছায় অথবা অনিচ্ছায় এবং তাদের প্রতিচ্ছায়াও সকাল-সন্ধ্যায়।'),
  ('bn.bengali', 13, 16, 'জিজ্ঞেস করুন নভোমন্ডল ও ভুমন্ডলের পালনকর্তা কে? বলে দিনঃ আল্লাহ! বলুনঃ তবে কি তোমরা আল্লাহ ব্যতীত এমন অভিভাবক স্থির করেছ, যারা নিজেদের ভাল-মন্দের ও মালিক নয়? বলুনঃ অন্ধ চক্ষুষ্মান কি সমান হয়? অথবা কোথাও কি অন্ধকার ও আলো সমান হয়। তবে কি তারা আল্লাহর জন্য এমন অংশীদার স্থির করেছে যে, তারা কিছু সৃষ্টি করেছে, যেমন সৃষ্টি করেছেন আল্লাহ? অতঃপর তাদের সৃষ্টি এরূপ বিভ্রান্তি ঘটিয়েছে? বলুনঃ আল্লাহই প্রত্যেক বস্তুর স্রষ্টা এবং তিনি একক, পরাক্রমশালী।'),
  ('bn.bengali', 13, 17, 'তিনি আকাশ থেকে পানি বর্ষণ করেন। অতঃপর স্রোতধারা প্রবাহিত হতে থাকে নিজ নিজ পরিমাণ অনুযায়ী। অতঃপর স্রোতধারা স্ফীত ফেনারাশি উপরে নিয়ে আসে। এবং অলঙ্কার অথবা তৈজসপত্রের জন্যে যে বস্তুকে আগুনে উত্তপ্ত করে, তাতেও তেমনি ফেনারাশি থাকে। এমনি ভাবে আল্লাহ সত্য ও অসত্যের দৃষ্টান্ত প্রদান করেন। অতএব, ফেনা তো শুকিয়ে খতম হয়ে যায় এবং যা মানুষের উপকারে আসে, তা জমিতে অবশিষ্ট থাকে। আল্লাহ এমনিভাবে দৃষ্টান্তসমূহ বর্ণনা করেন।'),
  ('bn.bengali', 13, 18, 'যারা পালনকর্তার আদেশ পালন করে, তাদের জন্য উত্তম প্রতিদান রয়েছে এবং যারা আদেশ পালন করে না, যদি তাদের কাছে জগতের সবকিছু থাকে এবং তার সাথে তার সমপরিমাণ আরও থাকে, তবে সবই নিজেদের মুক্তিপণ স্বরূপ দিয়ে দেবে। তাদের জন্যে রয়েছে কঠোর হিসাব। তাদের আবাস হবে জাহান্নাম। সেটা কতইনা নিকৃষ্ট অবস্থান।'),
  ('bn.bengali', 13, 19, 'যে ব্যক্তি জানে যে, যা কিছু পালনকর্তার পক্ষ থেকে আপনার প্রতি অবর্তীর্ণ হয়েছে তা সত্য সে কি ঐ ব্যক্তির সমান, যে অন্ধ? তারাই বোঝে, যারা বোধশক্তি সম্পন্ন।'),
  ('bn.bengali', 13, 20, 'এরা এমন লোক, যারা আল্লাহর প্রতিশ্রুতি পূর্ণ করে এবং অঙ্গীকার ভঙ্গ করে না।'),
  ('bn.bengali', 13, 21, 'এবং যারা বজায় রাখে ঐ সম্পর্ক, যা বজায় রাখতে আল্লাহ আদেশ দিয়েছেন এবং স্বীয় পালনকর্তাকে ভয় করে এবং কঠোর হিসাবের আশঙ্কা রাখে।'),
  ('bn.bengali', 13, 22, 'এবং যারা স্বীয় পালনকর্তার সন্তুষ্টির জন্যে সবর করে, নামায প্রতিষ্টা করে আর আমি তাদেরকে যা দিয়েছি, তা থেকে গোপনে ও প্রকাশ্য ব্যয় করে এবং যারা মন্দের বিপরীতে ভাল করে, তাদের জন্যে রয়েছে পরকালের গৃহ।'),
  ('bn.bengali', 13, 23, 'তা হচ্ছে বসবাসের বাগান। তাতে তারা প্রবেশ করবে এবং তাদের সৎকর্মশীল বাপ-দাদা, স্বামী-স্ত্রী ও সন্তানেরা। ফেরেশতারা তাদের কাছে আসবে প্রত্যেক দরজা দিয়ে।'),
  ('bn.bengali', 13, 24, 'বলবেঃ তোমাদের সবরের কারণে তোমাদের উপর শান্তি বর্ষিত হোক। আর তোমাদের এ পরিণাম-গৃহ কতই না চমৎকার।'),
  ('bn.bengali', 13, 25, 'এবং যারা আল্লাহর অঙ্গীকারকে দৃঢ় ও পাকা-পোক্ত করার পর তা ভঙ্গ করে, আল্লাহ যে, সম্পর্ক বজায় রাখতে আদেশ করেছেন, তা ছিন্ন করে এবং পৃথিবীতে অশান্তি সৃষ্টি করে, ওরা ঐ সমস্ত লোক যাদের জন্যে রয়েছে অভিসম্পাত এবং ওদের জন্যে রয়েছে কঠিন আযাব।'),
  ('bn.bengali', 13, 26, 'আল্লাহ যার জন্যে ইচ্ছা রুযী প্রশস্ত করেন এবং সংকুচিত করেন। তারা পার্থিব জীবনের প্রতি মুগ্ধ। পার্থিবজীবন পরকালের সামনে অতি সামান্য সম্পদ বৈ নয়।'),
  ('bn.bengali', 13, 27, 'কাফেররা বলেঃ তাঁর প্রতি তাঁর পালনকর্তার পক্ষ থেকে কোন নিদর্শন কেন অবতীর্ণ হলো না? বলে দিন, আল্লাহ যাকে ইচ্ছা পথভ্রষ্ট করেন এবং যে, মনোনিবেশ করে, তাকে নিজের দিকে পথপ্রদর্শন করেন।'),
  ('bn.bengali', 13, 28, 'যারা বিশ্বাস স্থাপন করে এবং তাদের অন্তর আল্লাহর যিকির দ্বারা শান্তি লাভ করে; জেনে রাখ, আল্লাহর যিকির দ্বারাই অন্তর সমূহ শান্তি পায়।'),
  ('bn.bengali', 13, 29, 'যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে, তাদের জন্যে রয়েছে সুসংবাদ এবং মনোরম প্রত্যাবর্তণস্থল।'),
  ('bn.bengali', 13, 30, 'এমনিভাবে আমি আপনাকে একটি উম্মতের মধ্যে প্রেরণ করেছি। তাদের পূর্বে অনেক উম্মত অতিক্রান্ত হয়েছে। যাতে আপনি তাদেরকে ঐ নির্দেশ শুনিয়ে দেন, যা আমি আপনার কাছে প্রেরণ করেছি। তথাপি তারা দয়াময়কে অস্বীকার করে। বলুনঃ তিনিই আমার পালনকর্তা। তিনি ব্যতীত কারও উপাসনা নাই। আমি তাঁর উপরই ভরসা করেছি এবং তাঁর দিকেই আমার প্রত্যাবর্তণ।'),
  ('bn.bengali', 13, 31, 'যদি কোন কোরআন এমন হত, যার সাহায্যে পাহাড় চলমান হয় অথবা যমীন খন্ডিত হয় অথবা মৃতরা কথা বলে, তবে কি হত? বরং সব কাজ তো আল্লাহর হাতে। ঈমানদাররা কি এ ব্যাপারে নিশ্চিত নয় যে, যদি আল্লাহ চাইতেন, তবে সব মানুষকে সৎপথে পরিচালিত করতেন? কাফেররা তাদের কৃতকর্মের কারণে সব সময় আঘাত পেতে থাকবে অথবা তাদের গৃহের নিকটবর্তী স্থানে আঘাত নেমে আসবে, যে, পর্যন্ত আল্লাহর ওয়াদা না আসে। নিশ্চয় আল্লাহ ওয়াদার খেলাফ করেন না।'),
  ('bn.bengali', 13, 32, 'আপনার পূর্বে কত রাসূলের সাথে ঠাট্টা করা হয়েছে। অতঃপর আমি কাফেরদেরকে কিছু অবকাশ দিয়েছি। , এর পর তাদেরকে পাকড়াও করেছি। অতএব কেমন ছিল আমার শাস্তি।'),
  ('bn.bengali', 13, 33, 'ওরা প্রত্যেকেই কি মাথার উপর স্ব স্ব কৃতকর্ম নিয়ে দন্ডায়মান নয়? এবং তারা আল্লাহর জন্য অংশীদার সাব্যস্ত করে। বলুন; নাম বল অথবা খবর দাও পৃথিবীর এমন কিছু জিনিস সম্পর্কে যা তিনি জানেন না? অথবা অসার কথাবার্তা বলছ? বরং সুশোভিত করা হয়েছে কাফেরদের জন্যে তাদের প্রতারণাকে এবং তাদেরকে সৎপথ থেকে বাধা দান করা হয়েছে। আল্লাহ যাকে পথভ্রষ্ট করেন, তার কোন পথ প্রদর্শক নেই।'),
  ('bn.bengali', 13, 34, 'দুনিয়ার জীবনেই এদের জন্য রয়েছে আযাব এবং অতি অবশ্য আখেরাতের জীবন কঠোরতম। আল্লাহর কবল থেকে তাদের কোন রক্ষাকারী নেই।'),
  ('bn.bengali', 13, 35, 'পরহেযগারদের জন্যে প্রতিশ্রুত জান্নাতের অবস্থা এই যে, তার নিম্নে নির্ঝরিণীসমূহ প্রবাহিত হয়। তার ফলসমূহ চিরস্থায়ী এবং ছায়াও। এটা তাদের প্রতিদান, যারা সাবধান হয়েছে এবং কাফেরদের প্রতিফল অগ্নি।'),
  ('bn.bengali', 13, 36, 'এবং যাদেরকে আমি গ্রন্থ দিয়েছি, তারা আপনার প্রতি যা অবতীর্ণ হয়েছে, তজ্জন্যে আনন্দিত হয় এবং কোন কোন দল এর কোন কোন বিষয় অস্বীকার করে। বলুন, আমাকে এরূপ আদেশই দেয়া হয়েছে যে, আমি আল্লাহর এবাদত করি। এবং তাঁর সাথে অংশীদার না করি। আমি তাঁর দিকেই দাওয়াত দেই এবং তাঁর কাছেই আমার প্রত্যাবর্তন।'),
  ('bn.bengali', 13, 37, 'এমনিভাবেই আমি এ কোরআনকে আরবী ভাষায় নির্দেশরূপে অবতীর্ণ করেছি। যদি আপনি তাদের প্রবৃত্তির অনুসরণ করেন আপনার কাছে জ্ঞান পৌঁছার পর, তবে আল্লাহর কবল থেকে আপনার না কোন সাহায্যকারী আছে এবং না কোন রক্ষাকারী।'),
  ('bn.bengali', 13, 38, 'আপনার পূর্বে আমি অনেক রসূল প্রেরণ করেছি এবং তাঁদেরকে পত্নী ও সন্তান-সন্ততি দিয়েছি। কোন রসূলের এমন সাধ্য ছিল না যে আল্লাহর নির্দেশ ছাড়া কোন নিদর্শন উপস্থিত করে। প্রত্যেকটি ওয়াদা লিখিত আছে।'),
  ('bn.bengali', 13, 39, 'আল্লাহ যা ইচ্ছা মিটিয়ে দেন এবং বহাল রাখেন এবং মূলগ্রন্থ তাঁর কাছেই রয়েছে।'),
  ('bn.bengali', 13, 40, 'আমি তাদের সাথে যে ওয়াদা করেছি, তার কোন একটি যদি আপনাকে দেখিয়ে দেই কিংবা আপনাকে উঠিয়ে নেই, তাতে কি আপনার দায়িত্ব তো পৌছে দেয়া এবং আমার দায়িত্ব হিসাব নেয়া।'),
  ('bn.bengali', 13, 41, 'তারা কি দেখে না যে, আমি তাদের দেশকে চতুর্দিক থেকে সমানে সঙ্কুচিত করে আসছি? আল্লাহ নির্দেশ দেন। তাঁর নির্দেশকে পশ্চাতে নিক্ষেপকারী কেউ নেই। তিনি দ্রুত হিসাব গ্রহণ করেন।'),
  ('bn.bengali', 13, 42, 'তাদের পূর্বে যারা ছিল, তারা চক্রান্ত করেছে। আর সকল চক্রান্ত তো আল্লাহর হাতেই আছে। তিনি জানেন প্রত্যেক ব্যক্তি যা কিছু করে। কাফেররা জেনে নেবে যে, পর জীবনের আবাসস্থল কাদের জন্য রয়েছে।'),
  ('bn.bengali', 13, 43, 'কাফেররা বলেঃ আপনি প্রেরিত ব্যক্তি নন। বলে দিন, আমার ও তোমাদের মধ্যে প্রকৃষ্ট সাক্ষী হচ্ছেন আল্লাহ এবং ঐ ব্যক্তি, যার কাছে গ্রন্থের জ্ঞান আছে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 13, 1, 'Alif. Lam. Mim. Ra. These are verses of the Scripture. That which is revealed unto thee from thy Lord is the Truth, but most of mankind believe not.'),
  ('en.pickthall', 13, 2, 'Allah it is Who raised up the heavens without visible supports, then mounted the Throne, and compelled the sun and the moon to be of service, each runneth unto an appointed term; He ordereth the course; He detaileth the revelations, that haply ye may be certain of the meeting with your Lord.'),
  ('en.pickthall', 13, 3, 'And He it is Who spread out the earth and placed therein firm hills and flowing streams, and of all fruits He placed therein two spouses (male and female). He covereth the night with the day. Lo! herein verily are portents for people who take thought.'),
  ('en.pickthall', 13, 4, 'And in the Earth are neighbouring tracts, vineyards and ploughed lands, and date-palms, like and unlike, which are watered with one water. And we have made some of them to excel others in fruit. Lo! herein verily are portents for people who have sense.'),
  ('en.pickthall', 13, 5, 'And if thou wonderest, then wondrous is their saying: When we are dust, are we then forsooth (to be raised) in a new creation? Such are they who disbelieve in their Lord; such have carcans on their necks; such are rightful owners of the Fire, they will abide therein.'),
  ('en.pickthall', 13, 6, 'And they bid thee hasten on the evil rather than the good, when exemplary punishments have indeed occurred before them. But lo! thy Lord is rich in pardon for mankind despite their wrong, and lo! thy Lord is strong in punishment.'),
  ('en.pickthall', 13, 7, 'Those who disbelieve say: If only some portent were sent down upon him from his Lord! Thou art a warner only, and for every folk a guide.'),
  ('en.pickthall', 13, 8, 'Allah knoweth that which every female beareth and that which the wombs absorb and that which they grow. And everything with Him is measured.'),
  ('en.pickthall', 13, 9, 'He is the Knower of the Invisible and the Visible, the Great, the High Exalted.'),
  ('en.pickthall', 13, 10, 'Alike of you is he who hideth the saying and he who noiseth it abroad, he who lurketh in the night and he who goeth freely in the daytime.'),
  ('en.pickthall', 13, 11, 'For him are angels ranged before him and behind him, who guard him by Allah\'s command. Lo! Allah changeth not the condition of a folk until they (first) change that which is in their hearts; and if Allah willeth misfortune for a folk there is none that can repel it, nor have they a defender beside Him.'),
  ('en.pickthall', 13, 12, 'He it is Who showeth you the lightning, a fear and a hope, and raiseth the heavy clouds.'),
  ('en.pickthall', 13, 13, 'The thunder hymneth His praise and (so do) the angels for awe of Him. He launcheth the thunderbolts and smiteth with them whom He will while they dispute (in doubt) concerning Allah, and He is mighty in wrath.'),
  ('en.pickthall', 13, 14, 'Unto Him is the real prayer. Those unto whom they pray beside Allah respond to them not at all, save as (is the response to) one who stretcheth forth his hands toward water (asking) that it may come unto his mouth, and it will never reach it. The prayer of disbelievers goeth (far) astray.'),
  ('en.pickthall', 13, 15, 'And unto Allah falleth prostrate whosoever is in the heavens and the earth, willingly or unwillingly, as do their shadows in the morning and the evening hours.'),
  ('en.pickthall', 13, 16, 'Say (O Muhammad): Who is Lord of the heavens and the earth? Say: Allah. Say: Take ye then (others) beside Him for protectors, which, even for themselves, have neither benefit nor hurt? Say: Is the blind man equal to the seer, or is darkness equal to light? Or assign they unto Allah partners who created the like of His creation so that the creation (which they made and His creation) seemed alike to them? Say: Allah is the Creator of all things, and He is the One, the Almighty.'),
  ('en.pickthall', 13, 17, 'He sendeth down water from the sky, so that valleys flow according to their measure, and the flood beareth (on its surface) swelling foam - from that which they smelt in the fire in order to make ornaments and tools riseth a foam like unto it - thus Allah coineth (the similitude of) the true and the false. Then, as for the foam, it passeth away as scum upon the banks, while, as for that which is of use to mankind, it remaineth in the earth. Thus Allah coineth the similitudes.'),
  ('en.pickthall', 13, 18, 'For those who answered Allah\'s call is bliss; and for those who answered not His call, if they had all that is in the earth, and therewith the like thereof, they would proffer it as ransom. Such will have a woeful reckoning, and their habitation will be hell, a dire abode.'),
  ('en.pickthall', 13, 19, 'Is he who knoweth that what is revealed unto thee from thy Lord is the truth like him who is blind? But only men of understanding heed;'),
  ('en.pickthall', 13, 20, 'Such as keep the pact of Allah, and break not the covenant;'),
  ('en.pickthall', 13, 21, 'Such as unite that which Allah hath commandeth should be joined, and fear their Lord, and dread a woeful reckoning;'),
  ('en.pickthall', 13, 22, 'Such as persevere in seeking their Lord\'s Countenance and are regular in prayer and spend of that which We bestow upon them secretly and openly, and overcome evil with good. Theirs will be the sequel of the (heavenly) Home,'),
  ('en.pickthall', 13, 23, 'Gardens of Eden which they enter, along with all who do right of their fathers and their helpmeets and their seed. The angels enter unto them from every gate,'),
  ('en.pickthall', 13, 24, '(Saying): Peace be unto you because ye persevered. Ah, passing sweet will be the sequel of the (heavenly) Home.'),
  ('en.pickthall', 13, 25, 'And those who break the covenant of Allah after ratifying it, and sever that which Allah hath commanded should be joined, and make mischief in the earth: theirs is the curse and theirs the ill abode.'),
  ('en.pickthall', 13, 26, 'Allah enlargeth livelihood for whom He will, and straiteneth (it for whom He will); and they rejoice in the life of the world, whereas the life of the world is but brief comfort as compared with the Hereafter.'),
  ('en.pickthall', 13, 27, 'Those who disbelieve say: If only a portent were sent down upon him from his Lord! Say: Lo! Allah sendeth whom He will astray, and guideth unto Himself all who turn (unto Him),'),
  ('en.pickthall', 13, 28, 'Who have believed and whose hearts have rest in the remembrance of Allah. Verily in the remembrance of Allah do hearts find rest!'),
  ('en.pickthall', 13, 29, 'Those who believe and do right: Joy is for them, and bliss (their) journey\'s end.'),
  ('en.pickthall', 13, 30, 'Thus We send thee (O Muhammad) unto a nation, before whom other nations have passed away, that thou mayst recite unto them that which We have inspired in thee, while they are disbelievers in the Beneficent. Say: He is my Lord; there is no Allah save Him. In Him do I put my trust and unto Him is my recourse.'),
  ('en.pickthall', 13, 31, 'Had it been possible for a Lecture to cause the mountains to move, or the earth to be torn asunder, or the dead to speak, (this Qur\'an would have done so). Nay, but Allah\'s is the whole command. Do not those who believe know that, had Allah willed, He could have guided all mankind? As for those who disbelieve, disaster ceaseth not to strike them because of what they do, or it dwelleth near their home until the threat of Allah come to pass. Lo! Allah faileth not to keep the tryst.'),
  ('en.pickthall', 13, 32, 'And verily messengers (of Allah) were mocked before thee, but long I bore with those who disbelieved. At length I seized them, and how (awful) was My punishment!'),
  ('en.pickthall', 13, 33, 'Is He Who is aware of the deserts of every soul (as he who is aware of nothing)? Yet they ascribe unto Allah partners. Say: Name them. Is it that ye would inform Him of something which He knoweth not in the earth? Or is it but a way of speaking? Nay but their contrivance is made seeming fair for those who disbelieve and they are kept from the right road. He whom Allah sendeth astray, for him there is no guide.'),
  ('en.pickthall', 13, 34, 'For them is torment in the life of the world, and verily the doom of the Hereafter is more painful, and they have no defender from Allah.'),
  ('en.pickthall', 13, 35, 'A similitude of the Garden which is promised unto those who keep their duty (to Allah): Underneath it rivers flow; its food is everlasting, and its shade; this is the reward of those who keep their duty, while the reward of disbelievers is the Fire.'),
  ('en.pickthall', 13, 36, 'Those unto whom We gave the Scripture rejoice in that which is revealed unto thee. And of the clans there are who deny some of it. Say: I am commanded only that I serve Allah and ascribe unto Him no partner. Unto Him I cry, and unto Him is my return.'),
  ('en.pickthall', 13, 37, 'Thus have We revealed it, a decisive utterance in Arabic; and if thou shouldst follow their desires after that which hath come unto thee of knowledge, then truly wouldst thou have from Allah no protecting friend nor defender.'),
  ('en.pickthall', 13, 38, 'And verily We sent messengers (to mankind) before thee, and We appointed for them wives and offspring, and it was not (given) to any messenger that he should bring a portent save by Allah\'s leave. For everything there is a time prescribed.'),
  ('en.pickthall', 13, 39, 'Allah effaceth what He will, and establisheth (what He will), and with Him is the source of ordinance.'),
  ('en.pickthall', 13, 40, 'Whether We let thee see something of that which We have promised them, or make thee die (before its happening), thine is but conveyance (of the message). Ours the reckoning.'),
  ('en.pickthall', 13, 41, 'See they not how we aim to the land, reducing it of its outlying parts? (When) Allah doometh there is none that can postpone His doom, and He is swift at reckoning.'),
  ('en.pickthall', 13, 42, 'Those who were before them plotted; but all plotting is Allah\'s. He knoweth that which each soul earneth. The disbelievers will come to know for whom will be the sequel of the (heavenly) Home.'),
  ('en.pickthall', 13, 43, 'They who disbelieve say: Thou art no messenger (of Allah). Say: Allah, and whosoever hath knowledge of the Scripture, is sufficient witness between me and you.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 13, 1, 'A. L. M. R. These are the signs (or verses) of the Book: that which hath been revealed unto thee from thy Lord is the Truth; but most men believe not.'),
  ('en.yusufali', 13, 2, 'Allah is He Who raised the heavens without any pillars that ye can see; is firmly established on the throne (of authority); He has subjected the sun and the moon (to his Law)! Each one runs (its course) for a term appointed. He doth regulate all affairs, explaining the signs in detail, that ye may believe with certainty in the meeting with your Lord.'),
  ('en.yusufali', 13, 3, 'And it is He who spread out the earth, and set thereon mountains standing firm and (flowing) rivers: and fruit of every kind He made in pairs, two and two: He draweth the night as a veil o\'er the Day. Behold, verily in these things there are signs for those who consider!'),
  ('en.yusufali', 13, 4, 'And in the earth are tracts (diverse though) neighbouring, and gardens of vines and fields sown with corn, and palm trees - growing out of single roots or otherwise: watered with the same water, yet some of them We make more excellent than others to eat. Behold, verily in these things there are signs for those who understand!'),
  ('en.yusufali', 13, 5, 'If thou dost marvel (at their want of faith), strange is their saying: "When we are (actually) dust, shall we indeed then be in a creation renewed?" They are those who deny their Lord! They are those round whose necks will be yokes (of servitude): they will be Companions of the Fire, to dwell therein (for aye)!'),
  ('en.yusufali', 13, 6, 'They ask thee to hasten on the evil in preference to the good: Yet have come to pass, before them, (many) exemplary punishments! But verily thy Lord is full of forgiveness for mankind for their wrong-doing, and verily thy Lord is (also) strict in punishment.'),
  ('en.yusufali', 13, 7, 'And the Unbelievers say: "Why is not a sign sent down to him from his Lord?" But thou art truly a warner, and to every people a guide.'),
  ('en.yusufali', 13, 8, 'Allah doth know what every female (womb) doth bear, by how much the wombs fall short (of their time or number) or do exceed. Every single thing is before His sight, in (due) proportion.'),
  ('en.yusufali', 13, 9, 'He knoweth the unseen and that which is open: He is the Great, the Most High.'),
  ('en.yusufali', 13, 10, 'It is the same (to Him) whether any of you conceal his speech or declare it openly; whether he lie hid by night or walk forth freely by day.'),
  ('en.yusufali', 13, 11, 'For each (such person) there are (angels) in succession, before and behind him: They guard him by command of Allah. Allah does not change a people\'s lot unless they change what is in their hearts. But when (once) Allah willeth a people\'s punishment, there can be no turning it back, nor will they find, besides Him, any to protect.'),
  ('en.yusufali', 13, 12, 'It is He Who doth show you the lightning, by way both of fear and of hope: It is He Who doth raise up the clouds, heavy with (fertilising) rain!'),
  ('en.yusufali', 13, 13, 'Nay, thunder repeateth His praises, and so do the angels, with awe: He flingeth the loud-voiced thunder-bolts, and therewith He striketh whomsoever He will.. yet these (are the men) who (dare to) dispute about Allah, with the strength of His power (supreme)!'),
  ('en.yusufali', 13, 14, 'For Him (alone) is prayer in Truth: any others that they call upon besides Him hear them no more than if they were to stretch forth their hands for water to reach their mouths but it reaches them not: for the prayer of those without Faith is nothing but (futile) wandering (in the mind).'),
  ('en.yusufali', 13, 15, 'Whatever beings there are in the heavens and the earth do prostrate themselves to Allah (Acknowledging subjection),- with good-will or in spite of themselves: so do their shadows in the morning and evenings.'),
  ('en.yusufali', 13, 16, 'Say: "Who is the Lord and Sustainer of the heavens and the earth?" Say: "(It is) Allah." Say: "Do ye then take (for worship) protectors other than Him, such as have no power either for good or for harm to themselves?" Say: "Are the blind equal with those who see? Or the depths of darkness equal with light?" Or do they assign to Allah partners who have created (anything) as He has created, so that the creation seemed to them similar? Say: "Allah is the Creator of all things: He is the One, the Supreme and Irresistible."'),
  ('en.yusufali', 13, 17, 'He sends down water from the skies, and the channels flow, each according to its measure: But the torrent bears away to foam that mounts up to the surface. Even so, from that (ore) which they heat in the fire, to make ornaments or utensils therewith, there is a scum likewise. Thus doth Allah (by parables) show forth Truth and Vanity. For the scum disappears like forth cast out; while that which is for the good of mankind remains on the earth. Thus doth Allah set forth parables.'),
  ('en.yusufali', 13, 18, 'For those who respond to their Lord, are (all) good things. But those who respond not to Him,- Even if they had all that is in the heavens and on earth, and as much more, (in vain) would they offer it for ransom. For them will the reckoning be terrible: their abode will be Hell,- what a bed of misery!'),
  ('en.yusufali', 13, 19, 'Is then one who doth know that that which hath been revealed unto thee from thy Lord is the Truth, like one who is blind? It is those who are endued with understanding that receive admonition;-'),
  ('en.yusufali', 13, 20, 'Those who fulfil the covenant of Allah and fail not in their plighted word;'),
  ('en.yusufali', 13, 21, 'Those who join together those things which Allah hath commanded to be joined, hold their Lord in awe, and fear the terrible reckoning;'),
  ('en.yusufali', 13, 22, 'Those who patiently persevere, seeking the countenance of their Lord; Establish regular prayers; spend, out of (the gifts) We have bestowed for their sustenance, secretly and openly; and turn off Evil with good: for such there is the final attainment of the (eternal) home,-'),
  ('en.yusufali', 13, 23, 'Gardens of perpetual bliss: they shall enter there, as well as the righteous among their fathers, their spouses, and their offspring: and angels shall enter unto them from every gate (with the salutation):'),
  ('en.yusufali', 13, 24, '"Peace unto you for that ye persevered in patience! Now how excellent is the final home!"'),
  ('en.yusufali', 13, 25, 'But those who break the Covenant of Allah, after having plighted their word thereto, and cut asunder those things which Allah has commanded to be joined, and work mischief in the land;- on them is the curse; for them is the terrible home!'),
  ('en.yusufali', 13, 26, 'Allah doth enlarge, or grant by (strict) measure, the sustenance (which He giveth) to whomso He pleaseth. (The wordly) rejoice in the life of this world: But the life of this world is but little comfort in the Hereafter.'),
  ('en.yusufali', 13, 27, 'The Unbelievers say: "Why is not a sign sent down to him from his Lord?" Say: "Truly Allah leaveth, to stray, whom He will; But He guideth to Himself those who turn to Him in penitence,-'),
  ('en.yusufali', 13, 28, '"Those who believe, and whose hearts find satisfaction in the remembrance of Allah: for without doubt in the remembrance of Allah do hearts find satisfaction.'),
  ('en.yusufali', 13, 29, '"For those who believe and work righteousness, is (every) blessedness, and a beautiful place of (final) return."'),
  ('en.yusufali', 13, 30, 'Thus have we sent thee amongst a People before whom (long since) have (other) Peoples (gone and) passed away; in order that thou mightest rehearse unto them what We send down unto thee by inspiration; yet do they reject (Him), the Most Gracious! Say: "He is my Lord! There is no god but He! On Him is my trust, and to Him do I turn!"'),
  ('en.yusufali', 13, 31, 'If there were a Qur\'an with which mountains were moved, or the earth were cloven asunder, or the dead were made to speak, (this would be the one!) But, truly, the command is with Allah in all things! Do not the Believers know, that, had Allah (so) willed, He could have guided all mankind (to the right)? But the Unbelievers,- never will disaster cease to seize them for their (ill) deeds, or to settle close to their homes, until the promise of Allah come to pass, for, verily, Allah will not fail in His promise.'),
  ('en.yusufali', 13, 32, 'Mocked were (many) messengers before thee: but I granted respite to the unbelievers, and finally I punished them: Then how (terrible) was my requital!'),
  ('en.yusufali', 13, 33, 'Is then He who standeth over every soul (and knoweth) all that it doth, (like any others)? And yet they ascribe partners to Allah. Say: "But name them! is it that ye will inform Him of something he knoweth not on earth, or is it (just) a show of words?" Nay! to those who believe not, their pretence seems pleasing, but they are kept back (thereby) from the path. And those whom Allah leaves to stray, no one can guide.'),
  ('en.yusufali', 13, 34, 'For them is a penalty in the life of this world, but harder, truly, is the penalty of the Hereafter: and defender have they none against Allah.'),
  ('en.yusufali', 13, 35, 'The parable of the Garden which the righteous are promised!- beneath it flow rivers: perpetual is the enjoyment thereof and the shade therein: such is the end of the Righteous; and the end of Unbelievers in the Fire.'),
  ('en.yusufali', 13, 36, 'Those to whom We have given the Book rejoice at what hath been revealed unto thee: but there are among the clans those who reject a part thereof. Say: "I am commanded to worship Allah, and not to join partners with Him. Unto Him do I call, and unto Him is my return."'),
  ('en.yusufali', 13, 37, 'Thus have We revealed it to be a judgment of authority in Arabic. Wert thou to follow their (vain) desires after the knowledge which hath reached thee, then wouldst thou find neither protector nor defender against Allah.'),
  ('en.yusufali', 13, 38, 'We did send messengers before thee, and appointed for them wives and children: and it was never the part of a messenger to bring a sign except as Allah permitted (or commanded). For each period is a Book (revealed).'),
  ('en.yusufali', 13, 39, 'Allah doth blot out or confirm what He pleaseth: with Him is the Mother of the Book.'),
  ('en.yusufali', 13, 40, 'Whether We shall show thee (within thy life-time) part of what we promised them or take to ourselves thy soul (before it is all accomplished),- thy duty is to make (the Message) reach them: it is our part to call them to account.'),
  ('en.yusufali', 13, 41, 'See they not that We gradually reduce the land (in their control) from its outlying borders? (Where) Allah commands, there is none to put back His Command: and He is swift in calling to account.'),
  ('en.yusufali', 13, 42, 'Those before them did (also) devise plots; but in all things the master-planning is Allah\'s He knoweth the doings of every soul: and soon will the Unbelievers know who gets home in the end.'),
  ('en.yusufali', 13, 43, 'The Unbelievers say: "No messenger art thou." Say: "Enough for a witness between me and you is Allah, and such as have knowledge of the Book."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 13, 1, 'Alif-Laaam-Meeem-Raa; tilka Aayaatul Kitaab; wallazee unzila ilaika mir Rabbikal haqqu wa laakinna aksaran naasi laa yu\'minoon'),
  ('en.transliteration', 13, 2, 'Allaahul lazee raf\'as samaawaati bighairi \'amadin tarawnahaa summas tawaa \'alal \'Arshi wa sakhkharash shamsa walqamara kulluny yajree li ajalim musammaa; yudabbirul amra yufassilil Aayaati la\'allakum biliqaaa\'i Rabbikum tooqinoon'),
  ('en.transliteration', 13, 3, 'Wa Huwal lazee maddal arda wa ja\'ala feehaa rawaasiya wa anhaaraa; wa min kullis samaraati ja\'ala feehaa zawjainis yaini Yughshil lailan nahaar; inna fee zaalika la aayaatil liqawminy yatafakkaroon'),
  ('en.transliteration', 13, 4, 'Wa fil ardi qita\'um muta jaawiraatunw wa jannaatum min a\'naabinw wa zar\'unw wa nakheelun sinwaanunw wa ghairu sinwaaniny yusqaa bimaaa\'inw waahid; wa nufaddilu ba\'dahaa \'alaa ba\'din fil-ukul; inna fee zaalika la aayaatil liqawminy ya\'qiloon'),
  ('en.transliteration', 13, 5, 'Wa in ta\'jab fa\'ajabun qawluhm \'a-izaa kunna turaaban \'a-inna lafee khalqin jadeed; ulaaa \'ikal lazeena kafaroo bi Rabbihim wa ulaaa\'ikal aghlaalu feee a\'naaqihim wa ulaa\'ika Ashaabun Naari hum feehaa khaalidoon'),
  ('en.transliteration', 13, 6, 'Wa yasta\'jiloonaka bis saiyi\'ati qablal hasanati wa qad khalat min qablihimul masulaat; wa inna Rabbaka lazoo maghfiratil linnaasi \'alaa zulmihim wa inna Rabbaka lashadeedul \'iqaab'),
  ('en.transliteration', 13, 7, 'Wa yaqoolul lazeena kafaroo law laaa unzila \'alaihi Aayatum mir Rabbih; innamaaa anta munzirunw wa likulli qawmin haad'),
  ('en.transliteration', 13, 8, 'Allaahu ya\'lamu maa tahmilu kullu unsaa wa maa tagheedul arhaamu wa maa tazdaad, wa kullu shai\'in \'indahoo bimiqdaar'),
  ('en.transliteration', 13, 9, '\'Aalimul Ghaibi wash shahaadatil Kaabeerul Muta\'aal'),
  ('en.transliteration', 13, 10, 'Sawaaa\'um minkum man asarral qawla wa man jahara bihee wa man huwa mustakhfim billaili wa saaribum binnahaar'),
  ('en.transliteration', 13, 11, 'Lahoo mu\'aqqibaatum mim baini yadaihi wa min khalfihee yahfazoonahoo min amril laah; innal laaha laa yughaiyiru maa biqawmin hattaa yughaiyiroo maa bianfusihim; wa izaaa araadal laahu biqawmin sooo\'an falaa maradda lah; wa maa lahum min dooniheeminw waal'),
  ('en.transliteration', 13, 12, 'Huwal lazee yureekumul barqa khawfanw wa tama\'anw wa yunshi\'us sahaabas siqaal'),
  ('en.transliteration', 13, 13, 'Wa yusabbihur ra\'du bihamdihee walmalaaa\'ikatu min kheefatihee wa yursilus sawaa\'iqa fa yuseebu bihaa mai yashaaa\'u wa hum yujaadiloona fil laahi wa Huwa shadeedul mihaal'),
  ('en.transliteration', 13, 14, 'Lahoo da\'watul haqq; wallazeena yad\'oona min doonihee laa yastajeeboona lahum bishai\'in illaa kabaasiti kaffaihi ilal maaa\'i liyablugha faahu wa maa huwa bibaalighih; wa maa du\'aaa\'ul aafireena illaa fee dalaal'),
  ('en.transliteration', 13, 15, 'Wa lillaahi yasjudu man fis samaawaati wal ardi taw \'anw wa karhanw wa zilaaluhum bilghuduwwi wal aasaal'),
  ('en.transliteration', 13, 16, 'Wul mar Rabbus samaawaati wal ard; qulillaah; qul afattakhaztum min dooniheee awliyaaa\'a laa yamlikoona li anfusihim naf\'anw wa laa darraa; qul hal yastawil a\'maa wal baseeru am hal tastawiz zulumaatu wannoor; am ja\'aloo lillaahi shurakaaa\'a khalaqoo kakhalqihee fatashaa bahal khalqu \'alaihim; qulil laahu Khaaliqu kulli shai\'inw wa Huwal Waahidul Qahhar'),
  ('en.transliteration', 13, 17, 'Anzala minas samaaa\'i maaa\'an fasaalat awdiyatum biqadarihaa fahtamalas sailu zabadar raabiyaa; wa mimmmaa yooqidoona \'alaihi fin naarib tighaaa\'a bilyatin aw mataa\'in zabadum misluh; kazaalika yadribul laahul haqqa wal baatil; fa ammaz zabadu fa yazhabu jufaaa\'aa; wa ammaa maa yanfa\'un naasa fa yamkusu fil ard; kazaalika yadribul laahul amsaal'),
  ('en.transliteration', 13, 18, 'Lillazeenas tajaaboo lirabbihimul husnaa; wallazeena lam yastajeeboo lahoo law anna lahum maa fil ardi jamee\'anw wa mislahoo ma\'ahoo laftadaw bih; ulaaa\'ika lahum sooo\'ul hisaab; wa maawaahum Jahannamu wa bi\'sal mihaad'),
  ('en.transliteration', 13, 19, 'Afamai ya\'lamu annamaaa unzila ilaika mir Rabbikal haqqu kaman huwa a\'maa; innamaa yatazakkaru ulul albaab'),
  ('en.transliteration', 13, 20, 'Allazeena yoofoona bi\'ahdil laahi wa laa yanqu doonal meesaaq'),
  ('en.transliteration', 13, 21, 'Wallazeena yasiloona maaa amaral laahu bihee an yoosala wa yakhshawna Rabbahum wa yakhaafoona sooo\'al hisaab'),
  ('en.transliteration', 13, 22, 'Wallazeena sabarub tighaaa\'a Wajhi Rabbihim wa aqaamus Salaata wa anfaqoo mimmaa razaqnaahum sirranw wa \'alaaniyatanw wa yadra\'oona bilhasanatis saiyi\'ata ulaaa\'ika lahum \'uqbad daar'),
  ('en.transliteration', 13, 23, 'jannaatu \'adiny yadkhu loonahaa wa man salaha min aabaaa\'ihim wa man salaha min aabaaa\'ihim wa azwaajihim wa zurriyyaatihim walmalaaa\'i katu yadkhuloona \'alaihim min kulli baab'),
  ('en.transliteration', 13, 24, 'Salaamun \'alaikum bimaa sabartum; fani\'ma \'uqbad daar'),
  ('en.transliteration', 13, 25, 'Wallazeena yanqudoona \'Ahdal laahi mim ba\'di meesaaqihee wa yaqta\'oona maaa amaral laahu biheee ai yoosala wa yufsidoona fil ardi ulaaa\'ika lahumul la\'natu wa lahum sooo\'ud daar'),
  ('en.transliteration', 13, 26, 'Allaahu yabsutur rizqa limai yashaaa\'u wa yaqdir; wa farihoo bilhayaatid dunyaa wa mal hayaatud dunya fil Aakhirati illaa mataa\''),
  ('en.transliteration', 13, 27, 'Wa yaqoolul lazeena kafaroo law laaa unzila \'alaihi Aayatum mir Rabbih; qul innal laaha yudillu mai yashaa\'u wa yahdeee ilaihi man anaab'),
  ('en.transliteration', 13, 28, 'Allazeena aamanoo wa tatma\'innu quloobuhum bizikril laah; alaa bizikril laahi tatma\'innul quloob'),
  ('en.transliteration', 13, 29, 'Allazeena aamanoo w a\'amilus saalihaati toobaa lahum wa husnu ma aab'),
  ('en.transliteration', 13, 30, 'Kazaalika arsalnaaka feee ummatin qad khalat min qablihaaa umamul litatluwa \'alaihimul lazeee awhainaaa ilaika wa hum yakfuroona bir Rahmaaan; qul Huwa Rabbee laaa ilaaha illaa Huwa Rabbee laaa ilaaha illaa Huwa \'alaihi tawakkaltu wa ilaihi mataab'),
  ('en.transliteration', 13, 31, 'Wa law anna Quraanan suyyirat bihil jibaalu aw qutti\'at bihil ardu aw kullima bihil mawtaa; bal lillaahil amru jamee\'aa; afalam yai\'asil lazeena aamanooo al law yashaaa \'ullaahu lahadan naasa jamee\'aa; wa laa yazaalul lazeena kafaroo tuseebuhum bimaa sana\'oo qaari\'atun aw tahullu qareebam min daarihim hatta yaatiya wa\'dul laah; innal laaha laa yukhliful mee\'aad'),
  ('en.transliteration', 13, 32, 'Wa laqadis tuhzi\'a bi Rusulim min qablika fa amlaitu lillazeena kafaroo summa akhaztuhum fakaifa kaana \'iqaab'),
  ('en.transliteration', 13, 33, 'Afaman Huwa qaaa\'imun \'alaa kulli nafsim bimaa kasabat; wa ja\'aloo illlaahi shurakaaa\'a qul samoohum; am tunabbi\'oona hoo bimaa laa ya\'lamu fil ardi; am bizaahirim minal qawl; bal zuyyina lillazeena kafaroo makruhum wa suddoo \'anis sabeel; wa mai yudlilil laaahu famaa lahoo min haad;'),
  ('en.transliteration', 13, 34, 'Lahum \'azaabun fil hayaatid dunyaa wa la\'azaabul Aakhirati ashaaq, wa maa lahum minal laahi min-waaq'),
  ('en.transliteration', 13, 35, 'Masalul Jannatil latee wu\'idal muttaqoona tajree min tahtihal anhaaru ukuluhaa daaa\'imunw wa zilluhaa; tilka uqbal lazeenat taqaw wa \'uqbal kafireenan Naar'),
  ('en.transliteration', 13, 36, 'Wallazeena aatainaa humul Kitaaba yafrahoona bimaa unzila ilaika wa minal Ahzaabi mai yunkiru ba\'dah; qul innamaa umirtu an a\'budal laaha wa laaa ushrika bih; ilaihi ad\'oo wa ilaihi maab'),
  ('en.transliteration', 13, 37, 'Wa kazaalika anzalnaahu hukman \'Arabiyyaa; wa la\'init taba\'ta ahwaaa \'ahum ba\'da maa jaaa\'aka minal \'ilmi maa laka minal laahi minw waliyinw wa laa waaq'),
  ('en.transliteration', 13, 38, 'Wa laqad arsalnaa Rusulam min qablika wa ja\'alnaa lahum azwaajanw wa zurriyyah; wa maa kaana lirasoolin ai yaatiya bi aayatin illaa bi iznil laah; likulli ajalin kitaab'),
  ('en.transliteration', 13, 39, 'Yamhul laahu maa yashaaa\'u wa yusbitu wa \'indahooo ummul Kitaab'),
  ('en.transliteration', 13, 40, 'Wa im maa nurriyannaka ba\'dal lazee na\'iduhum aw nata waffayannaka fa innamaa \'alaikal balaaghu wa \'alainal hisaab'),
  ('en.transliteration', 13, 41, 'Awalam yaraw annaa naatil arda nanqusuhaa min atraafihaa; wallaahu yahkumu laa mu\'aqqiba lihukmih; wa Huwa saree\'ul hisaab'),
  ('en.transliteration', 13, 42, 'Wa qad makaral lazeena min qablihim falillaahil makru jamee\'aa; ya\'lamu maa taksibu kullu nafs; wa sa ya\'lamul kuffaaru liman \'uqbad daar'),
  ('en.transliteration', 13, 43, 'Wa yaqoolul lazeena kafaroo lasta mursalaa; qul kafaa billaahi shaheedam bainee wa bainakum wa man \'indahoo \'ilmul Kitaab')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 13, 1, 'یہ کتاب کی آیتیں ہیں اور جو کچھ تجھ پر تیرے رب سے اترا سوحق ہے اورلیکن اکثر آدمی ایمان نہیں لاتے'),
  ('ur.ahmedali', 13, 2, 'الله وہ ہے جس نے آسمانوں کو ستونوں کے بغیر بلند کیا جنہیں تم دیکھ رہے ہو پھر عرش پر قائم ہوا اور سورج اور چاند کو کام پر لگا دیا ہر ایک اپنے وقت معین پر چل رہا ہے وہ ہر ایک کام کاانتظام کرتا ہے نشانیاں کھول کر بتاتا ہے تاکہ تم اپنے رب سے ملنے کا یقین کر لو'),
  ('ur.ahmedali', 13, 3, 'اور اسی نے زمین کو پھیلایا اور اس میں پہاڑاور دریا بنائے اور زمین میں ہر ایک پھل دوقسم کا بنایا دن کو رات سے چھپا دیتا ہے بے شک اس میں سوچنے والوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 13, 4, 'اور زمین میں ٹکڑے ایک دوسرے سے ملے ہوئے ہیں اور انگور کے باغ ہیں اور کھیتیاں اور کھجوریں ہیں ایک کی جڑ ملی ہوئی بعض بن ملی انہیں پانی بھی ایک ہی دیا جاتا ہے اور ہم ایک کو دوسرے پر پھلوں میں فضیلت دیتے ہیں بے شک اسمیں عقل مندوں کے لیے بڑی نشانیاں ہیں'),
  ('ur.ahmedali', 13, 5, 'اگر تو عجیب بات چاہے تو ان کا یہ کہنا عجب ہے کہ کیا جب ہم مٹی ہو گئے کیا نئے سرے سے بنائیں جائیں گے یہی وہ ہیں جو اپنے رب سے منکر ہو گئے اور انہیں کی گردنوں میں طوق ہوں گے اور یہی دوزخی ہیں و ہ اس میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 13, 6, 'اور تجھ سے بھلائی سے پہلے برائی کو جلد مانگتے ہیں اور ان سے پہلے بہت سے عذاب سے گزر چکے ہیں اور بے شک تیرا رب لوگو ں کو باوجود ان کے ظلم کے معاف بھی کرتا ہے اور تیرے رب کا عذاب بھی سخت ہے'),
  ('ur.ahmedali', 13, 7, 'اورکافر کہتے ہیں اس کے رب سے اس پر کوئی نشانی کیوں نہیں اتری تم تومحض ڈرانے والے ہوں اور ہر قوم کے لیے ایک رہبر ہوتا آیا ہے'),
  ('ur.ahmedali', 13, 8, 'الله کو معلوم ہے کہ جو کچھ ہر مادہ اپنے پیٹ میں لیے ہوئے ہے اورجو کچھ پیٹ میں سکڑتا اور بڑھتا ہے اور اس کے ہاں ہر چیز کا اندازہ ہے'),
  ('ur.ahmedali', 13, 9, 'پوشیدہ اور ظاہر کا جاننے والا ہے سب سے بڑا بلند مرتبہ ہے'),
  ('ur.ahmedali', 13, 10, 'تم میں سے جو شخص کوئی بات چپکے سے کہے یا پکار کرکہے اور جو شخص رات میں کہیں چھپ جائے یا دن میں چلے پھرے یہ سب برابر ہیں'),
  ('ur.ahmedali', 13, 11, 'ہر شخص حفاظت کے لیے کچھ فرشتے ہیں اس کے آگے اورپیچھے الله کے حکم سے اس کی نگہبانی کرتے ہیں بے شک الله کسی قوم کی حالت نہیں بدلتا جب تک وہ خود اپنی حالت کو نہ بدلے اور جب الله کو کسی قوم کی برائی چاہتا ہے پھر اسے کوئی نہیں روک سکتا اور اس کے سوا ان کا کوئی مددگار نہیں ہو سکتا'),
  ('ur.ahmedali', 13, 12, 'وہی ہے جو تمہیں خوف یا امید دلانے کے لیے بجلی دکھاتا اور بھاری بادلوں کو اٹھاتا ہے'),
  ('ur.ahmedali', 13, 13, 'اور رعد ا سکی پاکی کے ساتھ ا سکی تعریف کرتا ہے اور سب فرشتے اس کے ڈر سے اور بجلیاں بھیجتا ہے پھر انہیں جس پر چاہتا ہے گرا دیتا ہے اور یہ تو الله کے بارے میں جھگڑتے ہیں حالانکہ وہ بڑی قوت والا ہے'),
  ('ur.ahmedali', 13, 14, 'اسی کو پکارنا بجا ہے اوراس کے سوا جن لوگوں کو پکارتے ہیں وہ ان کے کچھ بھی کام نہیں آتے مگر جیسا کوئی پانی کی طرف اپنے دونوں ہاتھ پھیلائے کہ اس کے منہ میں آجائے حالانکہ وہ اس کے منہ تک نہیں پہنچتا اور کافروں کی جتنی پکار ہے سب گمراہی ہے'),
  ('ur.ahmedali', 13, 15, 'اور چارو ناچار الله ہی کو آسمان والے اور زمین والے سجدہ کرتے ہیں اور ان کے سائے بھی صبح اور شام'),
  ('ur.ahmedali', 13, 16, 'کہو آسمانوں اور زمین کا رب کون ہے کہہ دو الله کہو پھر کیا تم نے الله کے سوا ان چیزوں کو معبود نہیں بنا رکھا جو اپنے نفسوں کے نفع اور نقصان کےبھی مالک نہیں کہو کیا اندھا اور دیکھنے والا برابر ہوسکتا ہے یا کہیں اندھیرا اور روشنی برابر ہو سکتے ہیں کیا جنہیں انہوں نے الله کا شریک بنا رکھا ہے انہو ں نے بھی الله کی مخلوق جیسی کوئی مخلوق بنائی ہے پھر مخلوق ان کی نظر میں مشتبہ ہو گئی ہے پیدا کرنے والااللہ ہے اور وہ اکیلا زبردست ہے'),
  ('ur.ahmedali', 13, 17, 'اس نے آسمان سے پانی اتارا پھر اس سے اپنی مقدار میں نالے بہنے لگے پھر وہ سیلاب پھولا ہوا جھاگ اوپر لایا اور جس چیز کو آگ میں زیور یا کسی اور اسباب بنانے کے لیے پگھلاتے ہیں اس پر بھی ویسا ہی جھاگ ہوتا ہے الله حق اور باطل کی مثال بیان فرماتا ہے پھر جو جھاگ ہے وہ یونہی جاتا رہتا ہے اور جو لوگوں کو فائدہ دے وہ زمین میں ٹھیر جاتا ہے اسی طرح الله مثالیں بیان فرماتا ہے'),
  ('ur.ahmedali', 13, 18, 'جنہو ں نے اپنے رب کا حکم مانا ان کے واسطے بھلائی ہے اور جنہوں نے اس کا حکم نہ مانا اگر ان کے پاس سارا ہو جو کچھ زمین میں ہے اور اس کے ساتھ اتنا ہی او رہو تو سب جرمانہ میں دینا قبول کریں گے ان لوگو ں کے لیے برا حساب ہے اور ان کا ٹھکانا دوزخ ہے اوروہ برا ٹھکانا ہے'),
  ('ur.ahmedali', 13, 19, 'بھلا جو شخص جانتا ہے کہ تیرے رب سے تجھ پر جو کچھ اترا ہے حق ہے اس کےبرابر ہو سکتا ہے جو اندھا ہے سمجھتے تو عقل والے ہی ہیں'),
  ('ur.ahmedali', 13, 20, 'وہ لوگ جو الله کے عہد کو پوراکرتے ہیں اور اس عہد کو نہیں توڑتے'),
  ('ur.ahmedali', 13, 21, 'اور وہ لوگ جو ملاتے ہیں جس کے ملانے کو الله نے فرمایا ہے اور اپنے رب سے ڈرتے ہیں اور برے حساب کا خوف رکھتے ہیں'),
  ('ur.ahmedali', 13, 22, 'وہ جنہوں نے اپنے رب کی رضا مندی کے لیے صبر کیا اور نماز قائم کی اور ہمارے دیئے ہوئے میں سے پوشیدہ اور ظاہر خرچ کیا اور برائی کے مقابلے میں بھلائی کرتے ہیں انہیں کے لیے آخرت کا گھر ہے'),
  ('ur.ahmedali', 13, 23, 'ہمیشہ رہنے کے باغ جن میں وہ خود بھی رہیں گے اور ان کے باپ دادا اوربیویوں اور اولاد میں سے بھی جو نیکو کار ہیں اور ان کے پاس فرشتے ہر دروازے سے آئیں گے'),
  ('ur.ahmedali', 13, 24, 'کہیں گے تم پر سلامتی ہو تمہارے صبر کرنے کی وجہ سے پھر آخرت کا گھر کیا ہی اچھا ہے'),
  ('ur.ahmedali', 13, 25, 'اور جو لو گ الله کا عہد مضبوط کرنے کے بعد توڑ تے ہیں اور اس چیز کو توڑتے ہیں جسے الله نے جوڑنے کا حکم فرمایا اور ملک میں فساد کرتے ہیں ان کے لیے لعنت ہے اور ان کے لیے برا گھر ہے'),
  ('ur.ahmedali', 13, 26, 'الله ہی جس کے لیے چاہتا ہے روزی فراخ اور تنگ کرتا ہے اور دنیا کی زندگی پر خوش ہیں اور دنیا کی زندگی آخرت کے مقابلے میں کچھ نہیں مگر تھوڑاسا اسباب'),
  ('ur.ahmedali', 13, 27, 'اور کافر کہتے ہیں اس پراس کے رب سے کوئی نشانی کیوں نہیں اتری کہہ دو الله جس کو چاہتا ہے گمراہ کر دیتاہے اور جو اس کی طرف رجوع کرتا ہے اسے اپنے تک پہنچنے کا راستہ دکھاتا ہے'),
  ('ur.ahmedali', 13, 28, 'وہ لوگ جو ایمان لائے اور ان کے دلوں کو الله کی یاد سے تسکین ہوتی ہے خبردار! الله کی یاد ہی سے دل تسکین پاتے ہیں'),
  ('ur.ahmedali', 13, 29, 'جو لوگ ایمان لائے او راچھے کام کیے ان کے لیے خوشخبری اور اچھا ٹھکانا ہے'),
  ('ur.ahmedali', 13, 30, 'اسی طرح ہم نے تجھےایک امت میں بھیجا ہے کہ اس سے پہلے کئی امتیں گزرچکی ہیں تاکہ تو انہیں سناد ے جو ہم نے تیری طرف حکم بھیجا ہے اور وہ تو رحمنٰ کے منکر ہیں کہہ دو وہی میرا رب ہے جس کے سوا کوئی معبود نہیں اسی پر میں نے بھروسہ کیا ہے اور اسی کی طرف میرا رجوع ہے'),
  ('ur.ahmedali', 13, 31, 'اور اگر تحقیق کوئی ایسا قرآن نازل ہوتا جس سے پہاڑ چلتے یا اس سے زمین کے ٹکڑے ہو جاتے یا اس سے مردے بول اٹھتے (تب بھی نہ مانتے) بلکہ سب کام الله کے ہاتھ میں ہیں پھر کیا ایمان والے اس بات سے نا امید ہو گئے ہیں کہ اگر الله چاہتا تو سب آدمیوں کو ہدایت کر دیتا اور کافروں پر تو ہمیشہ ان کی بداعمالی سے کوئی نہ کوئی مصیبت آتی رہے گی یا وہ بلا ان کے گھر کے قریب نازل ہوگی یہاں تک کہ الله کا وعدہ پورا ہو بے شک الله اپنے وعدے کے خلاف نہیں کرتا'),
  ('ur.ahmedali', 13, 32, 'اور تجھ سے پہلے کئی رسولوں سے ہنسی کی گئی ہے پھر میں نے کافروں کو مہلت دی پھر انہیں پکڑ لیا پھر ہمارا عذاب کیسا تھا'),
  ('ur.ahmedali', 13, 33, 'بھلا جو ہر کسی کے سر پر لیے کھڑا ہے جو اس نے کیا ہے اور انہوں نے الله کے لیے شریک بنا رکھے ہیں کہہ دو ان کے نام بتلاؤ کیا الله کو وہ بات بتاتے ہو جسے وہ زمین میں نہیں جانتا یا اوپر ہی کی باتیں کرتے ہو بلکہ کافروں کے فریب انہیں بھلے معلوم کرائے گئے ہیں اور وہ راستہ سے روکے گئے ہیں اور جسے الله گمراہ کرے پھر اسے کوئی بھی ہدایت دینے والا نہیں ہے'),
  ('ur.ahmedali', 13, 34, 'ان کے لیے دنیا کی زندگی میں عذاب ہے اور البتہ آخرت کا عذاب تو بہت ہی سخت ہے اور انہیں الله سے بچانےوالا کوئی نہیں ہو گا'),
  ('ur.ahmedali', 13, 35, 'اس جنت کا حال جس کا پرہیزگاروں سے وعدہ کیا گیا ہے اس کے نیچے نہریں بہتی ہیں جس کے میوے اور سائے ہمیشہ رہیں گے یہ پرہیزگاروں کا انجام ہے اور کافروں کا انجام آگ ہے'),
  ('ur.ahmedali', 13, 36, 'اور وہ لوگ جنہیں ہم نے کتاب دی ہے اس سےخوش ہوتے ہیں جو تجھ پر نازل ہوا اور جماعتوں میں سے بعض لوگ اس کی بعضی بات نہیں مانتے کہہ دو مجھے تو یہی حکم ہوا ہے کہ الله کی بندگی کروں اور اس کے ساتھ کسی کو شریک نہ کروں اس کی طرف بلاتا ہوں اور اسی کی طرف میرا ٹھکانا ہے'),
  ('ur.ahmedali', 13, 37, 'اور اسی طرح ہم نے یہ کلام اتارا کتاب عربی زبان میں اور اگرتو ان کی خواہش کے مطابق چلے بعد اس علم کے جو تجھے پہنچ چکا ہے تیرا الله سے کوئی حمایتی اور بچانے والا نہ ہوگا'),
  ('ur.ahmedali', 13, 38, 'او رالبتہ تحقیق ہم نے تجھ سے پہلے کئی رسول بھیجے اور ہم نے انہیں بیویاں اور اولاد بھی دی تھی اور کسی رسول کے اختیار میں نہ تھا کہ وہ الله کے حکم کے سوا کوئی معجزہ لاتا ہر زمانے کے مناسب احکام ہوتے ہیں'),
  ('ur.ahmedali', 13, 39, 'الله جو چاہے موقوف کر دیتا ہے اور باقی رکھتا ہے اور اسی کے پاس اصل کتاب ہے'),
  ('ur.ahmedali', 13, 40, 'اور اگر ہم تجھے کوئی وعدہ دکھا دیں جو ہم نے ان سے کیا ہے یا تجھے اٹھا لیں سوتیرے ذمہ تو پہنچا دینا ہے اور ہمارے ذمہ حساب لینا ہے'),
  ('ur.ahmedali', 13, 41, 'کیا وہ نہیں دیکھتے کہ ہم زمین کو اس کے کناروں سے گھٹاتے چلے آتے ہیں اور الله حکم کرتاہے کوئی اس کے حکم کو ہٹا نہیں سکتا اور وہ جلد حساب لینے والا ہے'),
  ('ur.ahmedali', 13, 42, 'اور ان سے پہلےلوگ بھی تدبیریں کر چکے ہیں سو اصل تدبیر تو الله ہی کی ہےجو کچھ کوئی کرتا ہے اسے سب خبر رہتی ہے اورابھی کافروں کو معلوم ہو جائے گا کہ نیک انجام کس کا ہے'),
  ('ur.ahmedali', 13, 43, 'اور کہتے ہیں کہ تو رسول نہیں ہے کہہ دو میرے اور تمہارے درمیان الله گواہ کافی ہے اور وہ شخص جس کے پاس کتاب کا علم ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 13, 1, 'Elif, Lam, Mim, Ra. Bunlar Kitap\'ın ayetleridir. Sana Rabbinden indirilen Kitap haktır; fakat insanların çoğu inanmazlar.'),
  ('tr.diyanet', 13, 2, 'Gökleri, gördüğünüz gibi, direksiz yükselten, sonra arşa hükmeden, her biri belli bir süreye kadar hareket edecek olan Güneş ve Ay\'ı buyruğu altına alan, işleri yürüten, ayetleri uzun uzun açıklayan Allah\'tır; ola ki Rabbinize kavuşacağınıza kesin olarak inanırsınız.'),
  ('tr.diyanet', 13, 3, 'Yeri düzleyen, orada dağlar, nehirler var eden, her türlü üründen çift çift yetiştiren, gündüzü geceyle bürüyen de O\'dur. Doğrusu bunlarda, düşünen kimseler için ibretler vardır.'),
  ('tr.diyanet', 13, 4, 'Yeryüzünde, hepsi de aynı su ile sulanan, birbirine komşu toprak parçaları, tek ve çok köklü üzüm bağları, ekinler, hurma ağaçları vardır. Fakat onları şekil ve lezzetçe birbirinden farklı kılmışızdır. Düşünen kimseler için bunda ibretler vardır.'),
  ('tr.diyanet', 13, 5, 'Şaşacaksan, onların: "Biz toprak olunca mı yeniden yaratılacağız?" demelerine şaşmak gerekir. İşte onlar Rablerini inkar edenlerdir. İşte onlar boyunlarına demir halkalar vurulanlardır. İşte onlar cehennemliklerdir, orada temelli kalacaklardır.'),
  ('tr.diyanet', 13, 6, 'Puta tapanlar senden, iyilikten önce kötülük isterler, oysa onlardan önce nice ibret alınacak cezalar verilmiştir. Doğrusu Rabbinin, insanların zulümlerine rağmen onlara mağfireti vardır. Rabbinin cezalandırması çetindir.'),
  ('tr.diyanet', 13, 7, 'İnkar edenler: "Rabbinden ona bir mucize indirilmeli değil miydi?" derler. Sen ancak bir uyarıcısın. Her milletin bir yol göstereni vardır.'),
  ('tr.diyanet', 13, 8, 'Allah her dişinin rahminde taşıdığını, rahimlerin düşürdüğünü ve alıkoyduğunu bilir. O\'nun katında her şey bir ölçüye göredir.'),
  ('tr.diyanet', 13, 9, 'Görüleni de görülmeyeni de bilen, yücelerin yücesi büyük Allah\'a göre, aranızdan sözü gizleyen ile, açığa vuran ve geceye bürünerek gizlenip gündüzün ortaya çıkan arasında fark yoktur.'),
  ('tr.diyanet', 13, 10, 'Görüleni de görülmeyeni de bilen, yücelerin yücesi büyük Allah\'a göre, aranızdan sözü gizleyen ile, açığa vuran ve geceye bürünerek gizlenip gündüzün ortaya çıkan arasında fark yoktur.'),
  ('tr.diyanet', 13, 11, 'Ardında ve önünde insanoğlunu takip edenler vardır; Allah\'ın emriyle onu gözetirler. Bir millet kendini bozmadıkça Allah onların durumunu değiştirmez. Allah bir milletin fenalığını dileyince artık onun önüne geçilmez. Onlar için Allah\'tan başka hamide bulunmaz.'),
  ('tr.diyanet', 13, 12, 'Korku ve ümide düşürmek için size şimşeği gösteren, yağmurla yüklü bulutları meydana getiren O\'dur.'),
  ('tr.diyanet', 13, 13, 'O\'nu, gök gürlemesi hamd ile, melekler de korkularından tesbih ederler. Onlar pek kuvvetli olan Allah hakkında çekişirken, O, yıldırımları gönderir de onlarla dilediğini çarpar.'),
  ('tr.diyanet', 13, 14, 'Gerçek dua ve ibadet ancak O\'nadır. O\'ndan başka çağırdıkları putlar kendilerine hiçbir cevap vermezler. Durumları, suyun ağzına gelmesi için avuçlarını ona açmış bekleyen adamın durumu gibidir. Hiçbir zaman suya kavuşamaz. İşte kafirlerin yalvarışıda böyle, boşunadır.'),
  ('tr.diyanet', 13, 15, 'Yerde ve göklerdeki kimseler de, gölgeleri de, sabah akşam, ister istemez Allah\'a secde ederler.'),
  ('tr.diyanet', 13, 16, 'De ki: "Göklerin ve yerin Rabbi kimdir?", "Allah\'tır" de. "Onu bırakıp, kendilerine bir fayda ve zararı olmayan dostlar mı edindiniz?" de. "Kör ile gören bir olur mu? Veya karanlıkla aydınlık bir midir?" de. Yoksa Allah\'a, Allah gibi yaratması olan ortaklar buldular da, yaratmaları birbirine mi benzettiler? De ki: "Her şeyi yaratan Allah\'tır. O, her şeye üstün gelen tek Tanrı\'dır."'),
  ('tr.diyanet', 13, 17, 'Allah gökten su indirir, dereler onunla dolar taşar. Sel, üste çıkan köpüğü alır götürür. Süslenmek veya faydalanmak için ateşte erittiklerinizin üzerinde de buna benzer bir köpük vardır. Allah, hak ve batıl için şöyle misal verir: Köpük uçup gider, insanlara fayda veren ise yerde kalır. Allah bunun gibi daha nice misaller verir.'),
  ('tr.diyanet', 13, 18, 'Rablerinin çağrısına gelenlere en güzel karşılık vardır. O\'nun çağrısına uymayanlar ise, yeryüzünde olan her şey ve daha bir katı onların olsa, kurtulmak için fidye verirlerdi. İşte hesapları kötü olanlar bunlardır. Varacakları yer cehennemdir; ne kötü konaktır!'),
  ('tr.diyanet', 13, 19, 'Sana Rabbinden indirilenin gerçek olduğunu bilen kimse, onu bilmeyen köre benzer mi? Ancak akıl sahipleri ibret alırlar.'),
  ('tr.diyanet', 13, 20, 'Onlar, Allah\'ın ahdini yerine getirirler, anlaşmayı bozmazlar.'),
  ('tr.diyanet', 13, 21, 'Onlar, Allah\'ın birleştirilmesini emrettiği şeyi birleştirirler, Rablerinden korkarlar; kötü hesaptan ürkerler.'),
  ('tr.diyanet', 13, 22, 'Onlar, Rablerinin rızasını dileyerek sabrederler, namazı kılarlar; kendilerine verdiğimiz rızıktan, gizlice ve açıkça sarfederler; iyilik yaparak kötülüğü ortadan kaldırırlar; işte onlara bu dünyanın iyi sonucu, girecekleri Adn cennetleri vardır; babalarının, eşlerinin, çocuklarının iyi olanları da oraya girerler. Melekler her kapıdan yanlarına girip: "Sabretmenize karşılık size selam olsun; burası dünyanın ne güzel bir sonucudur!" derler.'),
  ('tr.diyanet', 13, 23, 'Onlar, Rablerinin rızasını dileyerek sabrederler, namazı kılarlar; kendilerine verdiğimiz rızıktan, gizlice ve açıkça sarfederler; iyilik yaparak kötülüğü ortadan kaldırırlar; işte onlara bu dünyanın iyi sonucu, girecekleri Adn cennetleri vardır; babalarının, eşlerinin, çocuklarının iyi olanları da oraya girerler. Melekler her kapıdan yanlarına girip: "Sabretmenize karşılık size selam olsun; burası dünyanın ne güzel bir sonucudur!" derler.'),
  ('tr.diyanet', 13, 24, 'Onlar, Rablerinin rızasını dileyerek sabrederler, namazı kılarlar; kendilerine verdiğimiz rızıktan, gizlice ve açıkça sarfederler; iyilik yaparak kötülüğü ortadan kaldırırlar; işte onlara bu dünyanın iyi sonucu, girecekleri Adn cennetleri vardır; babalarının, eşlerinin, çocuklarının iyi olanları da oraya girerler. Melekler her kapıdan yanlarına girip: "Sabretmenize karşılık size selam olsun; burası dünyanın ne güzel bir sonucudur!" derler.'),
  ('tr.diyanet', 13, 25, 'Sağlam söz verdikten sonra Allah\'ın ahdini bozanlar ve Allah\'ın birleştirilmesini emrettiğini ayıranlar ve yeryüzünde bozgunculuk yapanlar, işte lanet onlara ve kötü yurt, cehennem, onlaradır.'),
  ('tr.diyanet', 13, 26, 'Allah dilediği kimsenin rızkını genişletir ve bir ölçüye göre verir. Dünya hayatıyla övünenler bilsinler ki dünyadaki hayat ahiret yanında sadece bir geçimlikten ibarettir.'),
  ('tr.diyanet', 13, 27, 'İnkar edenler: "Rabbinden ona bir mucize indirilmeli değil miydi?" derler. De ki: "Doğrusu Allah dileyeni saptırır ve Kendisine yöneleni doğru yola eriştirir."'),
  ('tr.diyanet', 13, 28, 'Onlar inanmışlar, kalbleri Allah\'ı anmakla huzura kavuşmuştur. Dikkat edin, kalbler ancak Allah\'ı anmakla huzura kavuşur.'),
  ('tr.diyanet', 13, 29, 'İnanan ve yararlı iş işleyen kimseler için hoş bir hayat ve dönülecek güzel bir yer vardır.'),
  ('tr.diyanet', 13, 30, 'Sana vahyettiğimizi okuman için, seni de onlardan önce nice ümmetlerin gelip geçtiği bir ümmete gönderdik; o ümmet merhametli olan Allah\'ı inkar eder; de ki: "O benim Rabbim\'dir, O\'ndan başka Tanrı yoktur, yalnız O\'na güvenirim, dönüşüm de O\'nadır."'),
  ('tr.diyanet', 13, 31, 'Eğer Kuran ile dağlar yürütülmüş veya yeryüzü parçalanmış yahut ölüler konuşturulmuş olsaydı, kafirler yine de inanmazlardı. Oysa bütün işler Allah\'a aittir. İnananların, "Allah dilese bütün insanları doğru yola eriştirebilir" gerçeğini akılları kesmedi mi? Allah\'ın sözü yerine gelinceye kadar, yaptıkları işler sebebiyle inkar edenlere bir belanın dokunması veya evlerinin yakınına inmesi devam eder durur. Allah, verdiği sözden şüphesiz caymaz.'),
  ('tr.diyanet', 13, 32, 'And olsun ki, senden önce de nice peygamberler alaya alınmıştı. İnkar edenleri önce erteledim, sonra cezalarını verdim. Cezalandırmam nasıldı?'),
  ('tr.diyanet', 13, 33, 'Herkesin yaptığını gözeten Allah, bunu yapamayan putlarla bir olur mu? Onlar Allah\'a ortak koştular. De ki: "Onlara bir ad bulun bakalım; yeryüzünde bilmediği bir şeyi mi Allah\'a haber veriyorsunuz? Yoksa kuru sözlere mi aldanıyorsunuz? Fakat inkar edenlere, kurdukları düzenler güzel gösterildi ve doğru yoldan alıkonuldular. Zaten Allah\'ın saptırdığına yol gösteren bulunmaz.'),
  ('tr.diyanet', 13, 34, 'Onlara, dünya hayatında azap vardır, ahiret azabı ise daha çetindir. Allah\'a karşı onları bir koruyan da yoktur.'),
  ('tr.diyanet', 13, 35, 'Allah\'a karşı gelmekten sakınanlara vadedilen cennetin altından ırmaklar akar; oranın yiyecekleri ve gölgeleri devamlıdır. Bu, sakınanların elde edeceği sonuçtur, inkarcıların varacağı sonuç ise ateştir.'),
  ('tr.diyanet', 13, 36, 'Kendilerine kitap verdiklerimiz, sana indirilenden memnun olurlar. Karşı guruplar içinde ise, onun bir kısmını inkar edenler vardır. De ki: "Ben ancak Allah\'a kulluk etmekle ve O\'na asla ortak koşmamakla emrolundum. Hepinizi ancak O\'na çağırıyorum vedönüşüm O\'nadır."'),
  ('tr.diyanet', 13, 37, 'Böylece Biz Kuran\'ı Arapça bir hüküm ve hikmet olarak indirdik. Sana ilim geldikten sonra onların heveslerine uyarsan, and olsun ki, Allah katında sana bir dost ve seni koruyan çıkmaz.'),
  ('tr.diyanet', 13, 38, 'And olsun ki, senden önce nice peygamberler gönderdik; onlara eşler ve çocuklar verdik. Allah\'ın izni olmadan hiçbir peygamber bir ayet getiremez. Her şeyin vakti ve süresi yazılıdır.'),
  ('tr.diyanet', 13, 39, 'Allah dilediğini siler, dilediğini bırakır; Ana Kitap O\'nun katındadır.'),
  ('tr.diyanet', 13, 40, 'Onlara vadettiğimiz azabın bir kısmını sana göstersek de senin canını alsak da, vazifen sadece tebliğ etmektir. Hesap görmek Bize düşer.'),
  ('tr.diyanet', 13, 41, 'Görmüyorlar mı ki, Biz yeryüzünü etrafından gitgide eksiltmekteyiz. Hüküm Allah\'ındır, O\'nun hükmünü takip edip bozacak yoktur. O, hesabı çabuk görür.'),
  ('tr.diyanet', 13, 42, 'Onlardan öncekiler de tuzak kurdular, oysa bütün tuzaklar(ın cezası) Allah\'ındır, Herkesin yaptığını bilir. İnkarcılar da, neticenin kimin olduğunu göreceklerdir.'),
  ('tr.diyanet', 13, 43, 'İnkar edenler: "Sen peygamber değilsin" derler; de ki: "Benimle sizin aranızda şahit olarak Allah ve Kitap\'ı bilenler yeter."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 13, 1, 'Alif laam miim raa. Ini adalah ayat-ayat Al Kitab (Al Quran). Dan Kitab yang diturunkan kepadamu daripada Tuhanmu itu adalah benar: akan tetapi kebanyakan manusia tidak beriman (kepadanya).'),
  ('id.indonesian', 13, 2, 'Allah-lah Yang meninggikan langit tanpa tiang (sebagaimana) yang kamu lihat, kemudian Dia bersemayam di atas \'Arasy, dan menundukkan matahari dan bulan. Masing-masing beredar hingga waktu yang ditentukan. Allah mengatur urusan (makhluk-Nya), menjelaskan tanda-tanda (kebesaran-Nya), supaya kamu meyakini pertemuan(mu) dengan Tuhanmu.'),
  ('id.indonesian', 13, 3, 'Dan Dialah Tuhan yang membentangkan bumi dan menjadikan gunung-gunung dan sungai-sungai padanya. Dan menjadikan padanya semua buah-buahan berpasang-pasangan, Allah menutupkan malam kepada siang. Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kebesaran Allah) bagi kaum yang memikirkan.'),
  ('id.indonesian', 13, 4, 'Dan di bumi ini terdapat bagian-bagian yang berdampingan, dan kebun-kebun anggur, tanaman-tanaman dan pohon korma yang bercabang dan yang tidak bercabang, disirami dengan air yang sama. Kami melebihkan sebahagian tanam-tanaman itu atas sebahagian yang lain tentang rasanya. Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kebesaran Allah) bagi kaum yang berfikir.'),
  ('id.indonesian', 13, 5, 'Dan jika (ada sesuatu) yang kamu herankan, maka yang patut mengherankan adalah ucapan mereka: "Apabila kami telah menjadi tanah, apakah kami sesungguhnya akan (dikembalikan) menjadi makhluk yang baru?" Orang-orang itulah yang kafir kepada Tuhannya; dan orang-orang itulah (yang dilekatkan) belenggu di lehernya; mereka itulah penghuni neraka, mereka kekal di dalamnya.'),
  ('id.indonesian', 13, 6, 'Mereka meminta kepadamu supaya disegerakan (datangnya) siksa, sebelum (mereka meminta) kebaikan, padahal telah terjadi bermacam-macam contoh siksa sebelum mereka. Sesungguhnya Tuhanmu benar-benar mempunyai ampunan (yang luas) bagi manusia sekalipun mereka zalim, dan sesungguhnya Tuhanmu benar-benar sangat keras siksanya.'),
  ('id.indonesian', 13, 7, 'Orang-orang yang kafir berkata: "Mengapa tidak diturunkan kepadanya (Muhammad) suatu tanda (kebesaran) dari Tuhannya?" Sesungguhnya kamu hanyalah seorang pemberi peringatan; dan bagi tiap-tiap kaum ada orang yang memberi petunjuk.'),
  ('id.indonesian', 13, 8, 'Allah mengetahui apa yang dikandung oleh setiap perempuan, dan kandungan rahim yang kurang sempurna dan yang bertambah. Dan segala sesuatu pada sisi-Nya ada ukurannya.'),
  ('id.indonesian', 13, 9, 'Yang mengetahui semua yang ghaib dan yang nampak; Yang Maha Besar lagi Maha Tinggi.'),
  ('id.indonesian', 13, 10, 'Sama saja (bagi Tuhan), siapa diantaramu yang merahasiakan ucapannya, dan siapa yang berterus-terang dengan ucapan itu, dan siapa yang bersembunyi di malam hari dan yang berjalan (menampakkan diri) di siang hari.'),
  ('id.indonesian', 13, 11, 'Bagi manusia ada malaikat-malaikat yang selalu mengikutinya bergiliran, di muka dan di belakangnya, mereka menjaganya atas perintah Allah. Sesungguhnya Allah tidak merubah keadaan sesuatu kaum sehingga mereka merubah keadaan yang ada pada diri mereka sendiri. Dan apabila Allah menghendaki keburukan terhadap sesuatu kaum, maka tak ada yang dapat menolaknya; dan sekali-kali tak ada pelindung bagi mereka selain Dia.'),
  ('id.indonesian', 13, 12, 'Dialah Tuhan yang memperlihatkan kilat kepadamu untuk menimbulkan ketakutan dan harapan, dan Dia mengadakan awan mendung.'),
  ('id.indonesian', 13, 13, 'Dan guruh itu bertasbih dengan memuji Allah, (demikian pula) para malaikat karena takut kepada-Nya, dan Allah melepaskan halilintar, lalu menimpakannya kepada siapa yang Dia kehendaki, dan mereka berbantah-bantahan tentang Allah, dan Dialah Tuhan Yang Maha keras siksa-Nya.'),
  ('id.indonesian', 13, 14, 'Hanya bagi Allah-lah (hak mengabulkan) doa yang benar. Dan berhala-berhala yang mereka sembah selain Allah tidak dapat memperkenankan sesuatupun bagi mereka, melainkan seperti orang yang membukakan kedua telapak tangannya ke dalam air supaya sampai air ke mulutnya, padahal air itu tidak dapat sampai ke mulutnya. Dan doa (ibadat) orang-orang kafir itu, hanyalah sia-sia belaka.'),
  ('id.indonesian', 13, 15, 'Hanya kepada Allah-lah sujud (patuh) segala apa yang di langit dan di bumi, baik dengan kemauan sendiri ataupun terpaksa (dan sujud pula) bayang-bayangnya di waktu pagi dan petang hari.'),
  ('id.indonesian', 13, 16, 'Katakanlah: "Siapakah Tuhan langit dan bumi?" Jawabnya: "Allah". Katakanlah: "Maka patutkah kamu mengambil pelindung-pelindungmu dari selain Allah, padahal mereka tidak menguasai kemanfaatan dan tidak (pula) kemudharatan bagi diri mereka sendiri?". Katakanlah: "Adakah sama orang buta dan yang dapat melihat, atau samakah gelap gulita dan terang benderang; apakah mereka menjadikan beberapa sekutu bagi Allah yang dapat menciptakan seperti ciptaan-Nya sehingga kedua ciptaan itu serupa menurut pandangan mereka?" Katakanlah: "Allah adalah Pencipta segala sesuatu dan Dialah Tuhan Yang Maha Esa lagi Maha Perkasa".'),
  ('id.indonesian', 13, 17, 'Allah telah menurunkan air (hujan) dari langit, maka mengalirlah air di lembah-lembah menurut ukurannya, maka arus itu membawa buih yang mengambang. Dan dari apa (logam) yang mereka lebur dalam api untuk membuat perhiasan atau alat-alat, ada (pula) buihnya seperti buih arus itu. Demikianlah Allah membuat perumpamaan (bagi) yang benar dan yang bathil. Adapun buih itu, akan hilang sebagai sesuatu yang tak ada harganya; adapun yang memberi manfaat kepada manusia, maka ia tetap di bumi. Demikianlah Allah membuat perumpamaan-perumpamaan.'),
  ('id.indonesian', 13, 18, 'Bagi orang-orang yang memenuhi seruan Tuhannya, (disediakan) pembalasan yang baik. Dan orang-orang yang tidak memenuhi seruan Tuhan, sekiranya mereka mempunyai semua (kekayaan) yang ada di bumi dan (ditambah) sebanyak isi bumi itu lagi besertanya, niscaya mereka akan menebus dirinya dengan kekayaan itu. Orang-orang itu disediakan baginya hisab yang buruk dan tempat kediaman mereka ialah Jahanam dan itulah seburuk-buruk tempat kediaman.'),
  ('id.indonesian', 13, 19, 'Adakah orang yang mengetahui bahwasanya apa yang diturunkan kepadamu dari Tuhanmu itu benar sama dengan orang yang buta? Hanyalah orang-orang yang berakal saja yang dapat mengambil pelajaran,'),
  ('id.indonesian', 13, 20, '(yaitu) orang-orang yang memenuhi janji Allah dan tidak merusak perjanjian,'),
  ('id.indonesian', 13, 21, 'dan orang-orang yang menghubungkan apa-apa yang Allah perintahkan supaya dihubungkan, dan mereka takut kepada Tuhannya dan takut kepada hisab yang buruk.'),
  ('id.indonesian', 13, 22, 'Dan orang-orang yang sabar karena mencari keridhaan Tuhannya, mendirikan shalat, dan menafkahkan sebagian rezeki yang Kami berikan kepada mereka, secara sembunyi atau terang-terangan serta menolak kejahatan dengan kebaikan; orang-orang itulah yang mendapat tempat kesudahan (yang baik),'),
  ('id.indonesian', 13, 23, '(yaitu) surga \'Adn yang mereka masuk ke dalamnya bersama-sama dengan orang-orang yang saleh dari bapak-bapaknya, isteri-isterinya dan anak cucunya, sedang malaikat-malaikat masuk ke tempat-tempat mereka dari semua pintu;'),
  ('id.indonesian', 13, 24, '(sambil mengucapkan): "Salamun \'alaikum bima shabartum". Maka alangkah baiknya tempat kesudahan itu.'),
  ('id.indonesian', 13, 25, 'Orang-orang yang merusak janji Allah setelah diikrarkan dengan teguh dan memutuskan apa-apa yang Allah perintahkan supaya dihubungkan dan mengadakan kerusakan di bumi, orang-orang itulah yang memperoleh kutukan dan bagi mereka tempat kediaman yang buruk (Jahannam).'),
  ('id.indonesian', 13, 26, 'Allah meluaskan rezeki dan menyempitkannya bagi siapa yang Dia kehendaki. Mereka bergembira dengan kehidupan di dunia, padahal kehidupan dunia itu (dibanding dengan) kehidupan akhirat, hanyalah kesenangan (yang sedikit).'),
  ('id.indonesian', 13, 27, 'Orang-orang kafir berkata: "Mengapa tidak diturunkan kepadanya (Muhammad) tanda (mukjizat) dari Tuhannya?" Katakanlah: "Sesungguhnya Allah menyesatkan siapa yang Dia kehendaki dan menunjuki orang-orang yang bertaubat kepada-Nya",'),
  ('id.indonesian', 13, 28, '(yaitu) orang-orang yang beriman dan hati mereka manjadi tenteram dengan mengingat Allah. Ingatlah, hanya dengan mengingati Allah-lah hati menjadi tenteram.'),
  ('id.indonesian', 13, 29, 'Orang-orang yang beriman dan beramal saleh, bagi mereka kebahagiaan dan tempat kembali yang baik.'),
  ('id.indonesian', 13, 30, 'Demikianlah, Kami telah mengutus kamu pada suatu umat yang sungguh telah berlalu beberapa umat sebelumnya, supaya kamu membacakan kepada mereka (Al Quran) yang Kami wahyukan kepadamu, padahal mereka kafir kepada Tuhan Yang Maha Pemurah. Katakanlah: "Dialah Tuhanku tidak ada Tuhan selain Dia; hanya kepada-Nya aku bertawakkal dan hanya kepada-Nya aku bertaubat".'),
  ('id.indonesian', 13, 31, 'Dan sekiranya ada suatu bacaan (kitab suci) yang dengan bacaan itu gunung-gunung dapat digoncangkan atau bumi jadi terbelah atau oleh karenanya orang-orang yang sudah mati dapat berbicara, (tentulah Al Quran itulah dia). Sebenarnya segala urusan itu adalah kepunyaan Allah. Maka tidakkah orang-orang yang beriman itu mengetahui bahwa seandainya Allah menghendaki (semua manusia beriman), tentu Allah memberi petunjuk kepada manusia semuanya. Dan orang-orang yang kafir senantiasa ditimpa bencana disebabkan perbuatan mereka sendiri atau bencana itu terjadi dekat tempat kediaman mereka, sehingga datanglah janji Allah. Sesungguhnya Allah tidak menyalahi janji.'),
  ('id.indonesian', 13, 32, 'Dan sesungguhnya telah diperolok-olokkan beberapa rasul sebelum kamu, maka Aku beri tangguh kepada orang-orang kafir itu kemudian Aku binasakan mereka. Alangkah hebatnya siksaan-Ku itu!'),
  ('id.indonesian', 13, 33, 'Maka apakah Tuhan yang menjaga setiap diri terhadap apa yang diperbuatnya (sama dengan yang tidak demikian sifatnya)? Mereka menjadikan beberapa sekutu bagi Allah. Katakanlah: "Sebutkanlah sifat-sifat mereka itu". Atau apakah kamu hendak memberitakan kepada Allah apa yang tidak diketahui-Nya di bumi, atau kamu mengatakan (tentang hal itu) sekadar perkataan pada lahirnya saja. Sebenarnya orang-orang kafir itu dijadikan (oleh syaitan) memandang baik tipu daya mereka dan dihalanginya dari jalan (yang benar). Dan barangsiapa yang disesatkan Allah, maka baginya tak ada seorangpun yang akan memberi petunjuk.'),
  ('id.indonesian', 13, 34, 'Bagi mereka azab dalam kehidupan dunia dan sesungguhnya azab akhirat adalah lebih keras dan tak ada bagi mereka seorang pelindungpun dari (azab) Allah.'),
  ('id.indonesian', 13, 35, 'Perumpamaan surga yang dijanjikan kepada orang-orang yang takwa ialah (seperti taman); mengalir sungai-sungai di dalamnya; buahnya tak henti-henti sedang naungannya (demikian pula). Itulah tempat kesudahan bagi orang-orang yang bertakwa, sedang tempat kesudahan bagi orang-orang kafir ialah neraka.'),
  ('id.indonesian', 13, 36, 'Orang-orang yang telah Kami berikan kitab kepada mereka bergembira dengan kitab yang diturunkan kepadamu, dan di antara golongan-golongan (Yahudi dan Nasrani) yang bersekutu, ada yang mengingkari sebahagiannya. Katakanlah "Sesungguhnya aku hanya diperintah untuk menyembah Allah dan tidak mempersekutukan sesuatupun dengan Dia. Hanya kepada-Nya aku seru (manusia) dan hanya kepada-Nya aku kembali".'),
  ('id.indonesian', 13, 37, 'Dan demikianlah, Kami telah menurunkan Al Quran itu sebagai peraturan (yang benar) dalam bahasa Arab. Dan seandainya kamu mengikuti hawa nafsu mereka setelah datang pengetahuan kepadamu, maka sekali-kali tidak ada pelindung dan pemelihara bagimu terhadap (siksa) Allah.'),
  ('id.indonesian', 13, 38, 'Dan sesungguhnya Kami telah mengutus beberapa Rasul sebelum kamu dan Kami memberikan kepada mereka isteri-isteri dan keturunan. Dan tidak ada hak bagi seorang Rasul mendatangkan sesuatu ayat (mukjizat) melainkan dengan izin Allah. Bagi tiap-tiap masa ada Kitab (yang tertentu).'),
  ('id.indonesian', 13, 39, 'Allah menghapuskan apa yang Dia kehendaki dan menetapkan (apa yang Dia kehendaki), dan di sisi-Nya-lah terdapat Ummul-Kitab (Lauh mahfuzh).'),
  ('id.indonesian', 13, 40, 'Dan jika Kami perlihatkan kepadamu sebahagian (siksa) yang Kami ancamkan kepada mereka atau Kami wafatkan kamu (hal itu tidak penting bagimu) karena sesungguhnya tugasmu hanya menyampaikan saja, sedang Kami-lah yang menghisab amalan mereka.'),
  ('id.indonesian', 13, 41, 'Dan apakah mereka tidak melihat bahwa sesungguhnya Kami mendatangi daerah-daerah (orang-orang kafir), lalu Kami kurangi daerah-daerah itu (sedikit demi sedikit) dari tepi-tepinya? Dan Allah menetapkan hukum (menurut kehendak-Nya), tidak ada yang dapat menolak ketetapan-Nya; dan Dialah Yang Maha cepat hisab-Nya.'),
  ('id.indonesian', 13, 42, 'Dan sungguh orang-orang kafir yang sebelum mereka (kafir Mekah) telah mengadakan tipu daya, tetapi semua tipu daya itu adalah dalam kekuasaan Allah. Dia mengetahui apa yang diusahakan oleh setiap diri, dan orang-orang kafir akan mengetahui untuk siapa tempat kesudahan (yang baik) itu.'),
  ('id.indonesian', 13, 43, 'Berkatalah orang-orang kafir: "Kamu bukan seorang yang dijadikan Rasul". Katakanlah: "Cukuplah Allah menjadi saksi antaraku dan kamu, dan antara orang yang mempunyai ilmu Al Kitab".')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (12, 5, 1601, 'قَالَ يَٰبُنَىَّ لَا تَقْصُصْ رُءْيَاكَ عَلَىٰٓ إِخْوَتِكَ فَيَكِيدُوا۟ لَكَ كَيْدًا ۖ إِنَّ ٱلشَّيْطَٰنَ لِلْإِنسَٰنِ عَدُوٌّۭ مُّبِينٌۭ', 236, 12, 94, 0),
  (12, 6, 1602, 'وَكَذَٰلِكَ يَجْتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأْوِيلِ ٱلْأَحَادِيثِ وَيُتِمُّ نِعْمَتَهُۥ عَلَيْكَ وَعَلَىٰٓ ءَالِ يَعْقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيْكَ مِن قَبْلُ إِبْرَٰهِيمَ وَإِسْحَٰقَ ۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٌۭ', 236, 12, 94, 0),
  (12, 7, 1603, '۞ لَّقَدْ كَانَ فِى يُوسُفَ وَإِخْوَتِهِۦٓ ءَايَٰتٌۭ لِّلسَّآئِلِينَ', 236, 12, 95, 0),
  (12, 8, 1604, 'إِذْ قَالُوا۟ لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰٓ أَبِينَا مِنَّا وَنَحْنُ عُصْبَةٌ إِنَّ أَبَانَا لَفِى ضَلَٰلٍۢ مُّبِينٍ', 236, 12, 95, 0),
  (12, 9, 1605, 'ٱقْتُلُوا۟ يُوسُفَ أَوِ ٱطْرَحُوهُ أَرْضًۭا يَخْلُ لَكُمْ وَجْهُ أَبِيكُمْ وَتَكُونُوا۟ مِنۢ بَعْدِهِۦ قَوْمًۭا صَٰلِحِينَ', 236, 12, 95, 0),
  (12, 10, 1606, 'قَالَ قَآئِلٌۭ مِّنْهُمْ لَا تَقْتُلُوا۟ يُوسُفَ وَأَلْقُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ يَلْتَقِطْهُ بَعْضُ ٱلسَّيَّارَةِ إِن كُنتُمْ فَٰعِلِينَ', 236, 12, 95, 0),
  (12, 11, 1607, 'قَالُوا۟ يَٰٓأَبَانَا مَا لَكَ لَا تَأْمَ۫نَّا عَلَىٰ يُوسُفَ وَإِنَّا لَهُۥ لَنَٰصِحُونَ', 236, 12, 95, 0),
  (12, 12, 1608, 'أَرْسِلْهُ مَعَنَا غَدًۭا يَرْتَعْ وَيَلْعَبْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 236, 12, 95, 0),
  (12, 13, 1609, 'قَالَ إِنِّى لَيَحْزُنُنِىٓ أَن تَذْهَبُوا۟ بِهِۦ وَأَخَافُ أَن يَأْكُلَهُ ٱلذِّئْبُ وَأَنتُمْ عَنْهُ غَٰفِلُونَ', 236, 12, 95, 0),
  (12, 14, 1610, 'قَالُوا۟ لَئِنْ أَكَلَهُ ٱلذِّئْبُ وَنَحْنُ عُصْبَةٌ إِنَّآ إِذًۭا لَّخَٰسِرُونَ', 236, 12, 95, 0),
  (12, 15, 1611, 'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجْمَعُوٓا۟ أَن يَجْعَلُوهُ فِى غَيَٰبَتِ ٱلْجُبِّ ۚ وَأَوْحَيْنَآ إِلَيْهِ لَتُنَبِّئَنَّهُم بِأَمْرِهِمْ هَٰذَا وَهُمْ لَا يَشْعُرُونَ', 237, 12, 95, 0),
  (12, 16, 1612, 'وَجَآءُوٓ أَبَاهُمْ عِشَآءًۭ يَبْكُونَ', 237, 12, 95, 0),
  (12, 17, 1613, 'قَالُوا۟ يَٰٓأَبَانَآ إِنَّا ذَهَبْنَا نَسْتَبِقُ وَتَرَكْنَا يُوسُفَ عِندَ مَتَٰعِنَا فَأَكَلَهُ ٱلذِّئْبُ ۖ وَمَآ أَنتَ بِمُؤْمِنٍۢ لَّنَا وَلَوْ كُنَّا صَٰدِقِينَ', 237, 12, 95, 0),
  (12, 18, 1614, 'وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٍۢ كَذِبٍۢ ۚ قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًۭا ۖ فَصَبْرٌۭ جَمِيلٌۭ ۖ وَٱللَّهُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 237, 12, 95, 0),
  (12, 19, 1615, 'وَجَآءَتْ سَيَّارَةٌۭ فَأَرْسَلُوا۟ وَارِدَهُمْ فَأَدْلَىٰ دَلْوَهُۥ ۖ قَالَ يَٰبُشْرَىٰ هَٰذَا غُلَٰمٌۭ ۚ وَأَسَرُّوهُ بِضَٰعَةًۭ ۚ وَٱللَّهُ عَلِيمٌۢ بِمَا يَعْمَلُونَ', 237, 12, 95, 0),
  (12, 20, 1616, 'وَشَرَوْهُ بِثَمَنٍۭ بَخْسٍۢ دَرَٰهِمَ مَعْدُودَةٍۢ وَكَانُوا۟ فِيهِ مِنَ ٱلزَّٰهِدِينَ', 237, 12, 95, 0),
  (12, 21, 1617, 'وَقَالَ ٱلَّذِى ٱشْتَرَىٰهُ مِن مِّصْرَ لِٱمْرَأَتِهِۦٓ أَكْرِمِى مَثْوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوْ نَتَّخِذَهُۥ وَلَدًۭا ۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ وَلِنُعَلِّمَهُۥ مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمْرِهِۦ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 237, 12, 95, 0),
  (12, 22, 1618, 'وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيْنَٰهُ حُكْمًۭا وَعِلْمًۭا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 237, 12, 95, 0),
  (12, 23, 1619, 'وَرَٰوَدَتْهُ ٱلَّتِى هُوَ فِى بَيْتِهَا عَن نَّفْسِهِۦ وَغَلَّقَتِ ٱلْأَبْوَٰبَ وَقَالَتْ هَيْتَ لَكَ ۚ قَالَ مَعَاذَ ٱللَّهِ ۖ إِنَّهُۥ رَبِّىٓ أَحْسَنَ مَثْوَاىَ ۖ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّٰلِمُونَ', 238, 12, 95, 0),
  (12, 24, 1620, 'وَلَقَدْ هَمَّتْ بِهِۦ ۖ وَهَمَّ بِهَا لَوْلَآ أَن رَّءَا بُرْهَٰنَ رَبِّهِۦ ۚ كَذَٰلِكَ لِنَصْرِفَ عَنْهُ ٱلسُّوٓءَ وَٱلْفَحْشَآءَ ۚ إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُخْلَصِينَ', 238, 12, 95, 0),
  (12, 25, 1621, 'وَٱسْتَبَقَا ٱلْبَابَ وَقَدَّتْ قَمِيصَهُۥ مِن دُبُرٍۢ وَأَلْفَيَا سَيِّدَهَا لَدَا ٱلْبَابِ ۚ قَالَتْ مَا جَزَآءُ مَنْ أَرَادَ بِأَهْلِكَ سُوٓءًا إِلَّآ أَن يُسْجَنَ أَوْ عَذَابٌ أَلِيمٌۭ', 238, 12, 95, 0),
  (12, 26, 1622, 'قَالَ هِىَ رَٰوَدَتْنِى عَن نَّفْسِى ۚ وَشَهِدَ شَاهِدٌۭ مِّنْ أَهْلِهَآ إِن كَانَ قَمِيصُهُۥ قُدَّ مِن قُبُلٍۢ فَصَدَقَتْ وَهُوَ مِنَ ٱلْكَٰذِبِينَ', 238, 12, 95, 0),
  (12, 27, 1623, 'وَإِن كَانَ قَمِيصُهُۥ قُدَّ مِن دُبُرٍۢ فَكَذَبَتْ وَهُوَ مِنَ ٱلصَّٰدِقِينَ', 238, 12, 95, 0),
  (12, 28, 1624, 'فَلَمَّا رَءَا قَمِيصَهُۥ قُدَّ مِن دُبُرٍۢ قَالَ إِنَّهُۥ مِن كَيْدِكُنَّ ۖ إِنَّ كَيْدَكُنَّ عَظِيمٌۭ', 238, 12, 95, 0),
  (12, 29, 1625, 'يُوسُفُ أَعْرِضْ عَنْ هَٰذَا ۚ وَٱسْتَغْفِرِى لِذَنۢبِكِ ۖ إِنَّكِ كُنتِ مِنَ ٱلْخَاطِـِٔينَ', 238, 12, 95, 0),
  (12, 30, 1626, '۞ وَقَالَ نِسْوَةٌۭ فِى ٱلْمَدِينَةِ ٱمْرَأَتُ ٱلْعَزِيزِ تُرَٰوِدُ فَتَىٰهَا عَن نَّفْسِهِۦ ۖ قَدْ شَغَفَهَا حُبًّا ۖ إِنَّا لَنَرَىٰهَا فِى ضَلَٰلٍۢ مُّبِينٍۢ', 238, 12, 96, 0),
  (12, 31, 1627, 'فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَـًۭٔا وَءَاتَتْ كُلَّ وَٰحِدَةٍۢ مِّنْهُنَّ سِكِّينًۭا وَقَالَتِ ٱخْرُجْ عَلَيْهِنَّ ۖ فَلَمَّا رَأَيْنَهُۥٓ أَكْبَرْنَهُۥ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَٰشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَآ إِلَّا مَلَكٌۭ كَرِيمٌۭ', 239, 12, 96, 0),
  (12, 32, 1628, 'قَالَتْ فَذَٰلِكُنَّ ٱلَّذِى لُمْتُنَّنِى فِيهِ ۖ وَلَقَدْ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ فَٱسْتَعْصَمَ ۖ وَلَئِن لَّمْ يَفْعَلْ مَآ ءَامُرُهُۥ لَيُسْجَنَنَّ وَلَيَكُونًۭا مِّنَ ٱلصَّٰغِرِينَ', 239, 12, 96, 0),
  (12, 33, 1629, 'قَالَ رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ', 239, 12, 96, 0),
  (12, 34, 1630, 'فَٱسْتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنْهُ كَيْدَهُنَّ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 239, 12, 96, 0),
  (12, 35, 1631, 'ثُمَّ بَدَا لَهُم مِّنۢ بَعْدِ مَا رَأَوُا۟ ٱلْءَايَٰتِ لَيَسْجُنُنَّهُۥ حَتَّىٰ حِينٍۢ', 239, 12, 96, 0),
  (12, 36, 1632, 'وَدَخَلَ مَعَهُ ٱلسِّجْنَ فَتَيَانِ ۖ قَالَ أَحَدُهُمَآ إِنِّىٓ أَرَىٰنِىٓ أَعْصِرُ خَمْرًۭا ۖ وَقَالَ ٱلْءَاخَرُ إِنِّىٓ أَرَىٰنِىٓ أَحْمِلُ فَوْقَ رَأْسِى خُبْزًۭا تَأْكُلُ ٱلطَّيْرُ مِنْهُ ۖ نَبِّئْنَا بِتَأْوِيلِهِۦٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 239, 12, 96, 0),
  (12, 37, 1633, 'قَالَ لَا يَأْتِيكُمَا طَعَامٌۭ تُرْزَقَانِهِۦٓ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِۦ قَبْلَ أَن يَأْتِيَكُمَا ۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِى رَبِّىٓ ۚ إِنِّى تَرَكْتُ مِلَّةَ قَوْمٍۢ لَّا يُؤْمِنُونَ بِٱللَّهِ وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 239, 12, 96, 0),
  (12, 38, 1634, 'وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ ۚ مَا كَانَ لَنَآ أَن نُّشْرِكَ بِٱللَّهِ مِن شَىْءٍۢ ۚ ذَٰلِكَ مِن فَضْلِ ٱللَّهِ عَلَيْنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 240, 12, 96, 0),
  (12, 39, 1635, 'يَٰصَىٰحِبَىِ ٱلسِّجْنِ ءَأَرْبَابٌۭ مُّتَفَرِّقُونَ خَيْرٌ أَمِ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 240, 12, 96, 0),
  (12, 40, 1636, 'مَا تَعْبُدُونَ مِن دُونِهِۦٓ إِلَّآ أَسْمَآءًۭ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۚ أَمَرَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 240, 12, 96, 0),
  (12, 41, 1637, 'يَٰصَىٰحِبَىِ ٱلسِّجْنِ أَمَّآ أَحَدُكُمَا فَيَسْقِى رَبَّهُۥ خَمْرًۭا ۖ وَأَمَّا ٱلْءَاخَرُ فَيُصْلَبُ فَتَأْكُلُ ٱلطَّيْرُ مِن رَّأْسِهِۦ ۚ قُضِىَ ٱلْأَمْرُ ٱلَّذِى فِيهِ تَسْتَفْتِيَانِ', 240, 12, 96, 0),
  (12, 42, 1638, 'وَقَالَ لِلَّذِى ظَنَّ أَنَّهُۥ نَاجٍۢ مِّنْهُمَا ٱذْكُرْنِى عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيْطَٰنُ ذِكْرَ رَبِّهِۦ فَلَبِثَ فِى ٱلسِّجْنِ بِضْعَ سِنِينَ', 240, 12, 96, 0),
  (12, 43, 1639, 'وَقَالَ ٱلْمَلِكُ إِنِّىٓ أَرَىٰ سَبْعَ بَقَرَٰتٍۢ سِمَانٍۢ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌۭ وَسَبْعَ سُنۢبُلَٰتٍ خُضْرٍۢ وَأُخَرَ يَابِسَٰتٍۢ ۖ يَٰٓأَيُّهَا ٱلْمَلَأُ أَفْتُونِى فِى رُءْيَٰىَ إِن كُنتُمْ لِلرُّءْيَا تَعْبُرُونَ', 240, 12, 96, 0),
  (12, 44, 1640, 'قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۢ ۖ وَمَا نَحْنُ بِتَأْوِيلِ ٱلْأَحْلَٰمِ بِعَٰلِمِينَ', 241, 12, 96, 0),
  (12, 45, 1641, 'وَقَالَ ٱلَّذِى نَجَا مِنْهُمَا وَٱدَّكَرَ بَعْدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأْوِيلِهِۦ فَأَرْسِلُونِ', 241, 12, 96, 0),
  (12, 46, 1642, 'يُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفْتِنَا فِى سَبْعِ بَقَرَٰتٍۢ سِمَانٍۢ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌۭ وَسَبْعِ سُنۢبُلَٰتٍ خُضْرٍۢ وَأُخَرَ يَابِسَٰتٍۢ لَّعَلِّىٓ أَرْجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمْ يَعْلَمُونَ', 241, 12, 96, 0),
  (12, 47, 1643, 'قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًۭا فَمَا حَصَدتُّمْ فَذَرُوهُ فِى سُنۢبُلِهِۦٓ إِلَّا قَلِيلًۭا مِّمَّا تَأْكُلُونَ', 241, 12, 96, 0),
  (12, 48, 1644, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ سَبْعٌۭ شِدَادٌۭ يَأْكُلْنَ مَا قَدَّمْتُمْ لَهُنَّ إِلَّا قَلِيلًۭا مِّمَّا تُحْصِنُونَ', 241, 12, 96, 0),
  (12, 49, 1645, 'ثُمَّ يَأْتِى مِنۢ بَعْدِ ذَٰلِكَ عَامٌۭ فِيهِ يُغَاثُ ٱلنَّاسُ وَفِيهِ يَعْصِرُونَ', 241, 12, 96, 0),
  (12, 50, 1646, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦ ۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرْجِعْ إِلَىٰ رَبِّكَ فَسْـَٔلْهُ مَا بَالُ ٱلنِّسْوَةِ ٱلَّٰتِى قَطَّعْنَ أَيْدِيَهُنَّ ۚ إِنَّ رَبِّى بِكَيْدِهِنَّ عَلِيمٌۭ', 241, 12, 96, 0),
  (12, 51, 1647, 'قَالَ مَا خَطْبُكُنَّ إِذْ رَٰوَدتُّنَّ يُوسُفَ عَن نَّفْسِهِۦ ۚ قُلْنَ حَٰشَ لِلَّهِ مَا عَلِمْنَا عَلَيْهِ مِن سُوٓءٍۢ ۚ قَالَتِ ٱمْرَأَتُ ٱلْعَزِيزِ ٱلْـَٰٔنَ حَصْحَصَ ٱلْحَقُّ أَنَا۠ رَٰوَدتُّهُۥ عَن نَّفْسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', 241, 12, 96, 0),
  (12, 52, 1648, 'ذَٰلِكَ لِيَعْلَمَ أَنِّى لَمْ أَخُنْهُ بِٱلْغَيْبِ وَأَنَّ ٱللَّهَ لَا يَهْدِى كَيْدَ ٱلْخَآئِنِينَ', 241, 12, 96, 0),
  (12, 53, 1649, '۞ وَمَآ أُبَرِّئُ نَفْسِىٓ ۚ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ ۚ إِنَّ رَبِّى غَفُورٌۭ رَّحِيمٌۭ', 242, 13, 97, 0),
  (12, 54, 1650, 'وَقَالَ ٱلْمَلِكُ ٱئْتُونِى بِهِۦٓ أَسْتَخْلِصْهُ لِنَفْسِى ۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلْيَوْمَ لَدَيْنَا مَكِينٌ أَمِينٌۭ', 242, 13, 97, 0),
  (12, 55, 1651, 'قَالَ ٱجْعَلْنِى عَلَىٰ خَزَآئِنِ ٱلْأَرْضِ ۖ إِنِّى حَفِيظٌ عَلِيمٌۭ', 242, 13, 97, 0),
  (12, 56, 1652, 'وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِى ٱلْأَرْضِ يَتَبَوَّأُ مِنْهَا حَيْثُ يَشَآءُ ۚ نُصِيبُ بِرَحْمَتِنَا مَن نَّشَآءُ ۖ وَلَا نُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 242, 13, 97, 0),
  (12, 57, 1653, 'وَلَأَجْرُ ٱلْءَاخِرَةِ خَيْرٌۭ لِّلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 242, 13, 97, 0),
  (12, 58, 1654, 'وَجَآءَ إِخْوَةُ يُوسُفَ فَدَخَلُوا۟ عَلَيْهِ فَعَرَفَهُمْ وَهُمْ لَهُۥ مُنكِرُونَ', 242, 13, 97, 0),
  (12, 59, 1655, 'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ قَالَ ٱئْتُونِى بِأَخٍۢ لَّكُم مِّنْ أَبِيكُمْ ۚ أَلَا تَرَوْنَ أَنِّىٓ أُوفِى ٱلْكَيْلَ وَأَنَا۠ خَيْرُ ٱلْمُنزِلِينَ', 242, 13, 97, 0),
  (12, 60, 1656, 'فَإِن لَّمْ تَأْتُونِى بِهِۦ فَلَا كَيْلَ لَكُمْ عِندِى وَلَا تَقْرَبُونِ', 242, 13, 97, 0),
  (12, 61, 1657, 'قَالُوا۟ سَنُرَٰوِدُ عَنْهُ أَبَاهُ وَإِنَّا لَفَٰعِلُونَ', 242, 13, 97, 0),
  (12, 62, 1658, 'وَقَالَ لِفِتْيَٰنِهِ ٱجْعَلُوا۟ بِضَٰعَتَهُمْ فِى رِحَالِهِمْ لَعَلَّهُمْ يَعْرِفُونَهَآ إِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمْ لَعَلَّهُمْ يَرْجِعُونَ', 242, 13, 97, 0),
  (12, 63, 1659, 'فَلَمَّا رَجَعُوٓا۟ إِلَىٰٓ أَبِيهِمْ قَالُوا۟ يَٰٓأَبَانَا مُنِعَ مِنَّا ٱلْكَيْلُ فَأَرْسِلْ مَعَنَآ أَخَانَا نَكْتَلْ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 242, 13, 97, 0),
  (12, 64, 1660, 'قَالَ هَلْ ءَامَنُكُمْ عَلَيْهِ إِلَّا كَمَآ أَمِنتُكُمْ عَلَىٰٓ أَخِيهِ مِن قَبْلُ ۖ فَٱللَّهُ خَيْرٌ حَٰفِظًۭا ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 243, 13, 97, 0),
  (12, 65, 1661, 'وَلَمَّا فَتَحُوا۟ مَتَٰعَهُمْ وَجَدُوا۟ بِضَٰعَتَهُمْ رُدَّتْ إِلَيْهِمْ ۖ قَالُوا۟ يَٰٓأَبَانَا مَا نَبْغِى ۖ هَٰذِهِۦ بِضَٰعَتُنَا رُدَّتْ إِلَيْنَا ۖ وَنَمِيرُ أَهْلَنَا وَنَحْفَظُ أَخَانَا وَنَزْدَادُ كَيْلَ بَعِيرٍۢ ۖ ذَٰلِكَ كَيْلٌۭ يَسِيرٌۭ', 243, 13, 97, 0),
  (12, 66, 1662, 'قَالَ لَنْ أُرْسِلَهُۥ مَعَكُمْ حَتَّىٰ تُؤْتُونِ مَوْثِقًۭا مِّنَ ٱللَّهِ لَتَأْتُنَّنِى بِهِۦٓ إِلَّآ أَن يُحَاطَ بِكُمْ ۖ فَلَمَّآ ءَاتَوْهُ مَوْثِقَهُمْ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلٌۭ', 243, 13, 97, 0),
  (12, 67, 1663, 'وَقَالَ يَٰبَنِىَّ لَا تَدْخُلُوا۟ مِنۢ بَابٍۢ وَٰحِدٍۢ وَٱدْخُلُوا۟ مِنْ أَبْوَٰبٍۢ مُّتَفَرِّقَةٍۢ ۖ وَمَآ أُغْنِى عَنكُم مِّنَ ٱللَّهِ مِن شَىْءٍ ۖ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ عَلَيْهِ تَوَكَّلْتُ ۖ وَعَلَيْهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 243, 13, 97, 0),
  (12, 68, 1664, 'وَلَمَّا دَخَلُوا۟ مِنْ حَيْثُ أَمَرَهُمْ أَبُوهُم مَّا كَانَ يُغْنِى عَنْهُم مِّنَ ٱللَّهِ مِن شَىْءٍ إِلَّا حَاجَةًۭ فِى نَفْسِ يَعْقُوبَ قَضَىٰهَا ۚ وَإِنَّهُۥ لَذُو عِلْمٍۢ لِّمَا عَلَّمْنَٰهُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 243, 13, 97, 0),
  (12, 69, 1665, 'وَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَخَاهُ ۖ قَالَ إِنِّىٓ أَنَا۠ أَخُوكَ فَلَا تَبْتَئِسْ بِمَا كَانُوا۟ يَعْمَلُونَ', 243, 13, 97, 0),
  (12, 70, 1666, 'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمْ جَعَلَ ٱلسِّقَايَةَ فِى رَحْلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلْعِيرُ إِنَّكُمْ لَسَٰرِقُونَ', 244, 13, 97, 0),
  (12, 71, 1667, 'قَالُوا۟ وَأَقْبَلُوا۟ عَلَيْهِم مَّاذَا تَفْقِدُونَ', 244, 13, 97, 0),
  (12, 72, 1668, 'قَالُوا۟ نَفْقِدُ صُوَاعَ ٱلْمَلِكِ وَلِمَن جَآءَ بِهِۦ حِمْلُ بَعِيرٍۢ وَأَنَا۠ بِهِۦ زَعِيمٌۭ', 244, 13, 97, 0),
  (12, 73, 1669, 'قَالُوا۟ تَٱللَّهِ لَقَدْ عَلِمْتُم مَّا جِئْنَا لِنُفْسِدَ فِى ٱلْأَرْضِ وَمَا كُنَّا سَٰرِقِينَ', 244, 13, 97, 0),
  (12, 74, 1670, 'قَالُوا۟ فَمَا جَزَٰٓؤُهُۥٓ إِن كُنتُمْ كَٰذِبِينَ', 244, 13, 97, 0),
  (12, 75, 1671, 'قَالُوا۟ جَزَٰٓؤُهُۥ مَن وُجِدَ فِى رَحْلِهِۦ فَهُوَ جَزَٰٓؤُهُۥ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 244, 13, 97, 0),
  (12, 76, 1672, 'فَبَدَأَ بِأَوْعِيَتِهِمْ قَبْلَ وِعَآءِ أَخِيهِ ثُمَّ ٱسْتَخْرَجَهَا مِن وِعَآءِ أَخِيهِ ۚ كَذَٰلِكَ كِدْنَا لِيُوسُفَ ۖ مَا كَانَ لِيَأْخُذَ أَخَاهُ فِى دِينِ ٱلْمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ نَرْفَعُ دَرَجَٰتٍۢ مَّن نَّشَآءُ ۗ وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌۭ', 244, 13, 97, 0),
  (12, 77, 1673, '۞ قَالُوٓا۟ إِن يَسْرِقْ فَقَدْ سَرَقَ أَخٌۭ لَّهُۥ مِن قَبْلُ ۚ فَأَسَرَّهَا يُوسُفُ فِى نَفْسِهِۦ وَلَمْ يُبْدِهَا لَهُمْ ۚ قَالَ أَنتُمْ شَرٌّۭ مَّكَانًۭا ۖ وَٱللَّهُ أَعْلَمُ بِمَا تَصِفُونَ', 244, 13, 98, 0),
  (12, 78, 1674, 'قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ إِنَّ لَهُۥٓ أَبًۭا شَيْخًۭا كَبِيرًۭا فَخُذْ أَحَدَنَا مَكَانَهُۥٓ ۖ إِنَّا نَرَىٰكَ مِنَ ٱلْمُحْسِنِينَ', 244, 13, 98, 0),
  (12, 79, 1675, 'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأْخُذَ إِلَّا مَن وَجَدْنَا مَتَٰعَنَا عِندَهُۥٓ إِنَّآ إِذًۭا لَّظَٰلِمُونَ', 245, 13, 98, 0),
  (12, 80, 1676, 'فَلَمَّا ٱسْتَيْـَٔسُوا۟ مِنْهُ خَلَصُوا۟ نَجِيًّۭا ۖ قَالَ كَبِيرُهُمْ أَلَمْ تَعْلَمُوٓا۟ أَنَّ أَبَاكُمْ قَدْ أَخَذَ عَلَيْكُم مَّوْثِقًۭا مِّنَ ٱللَّهِ وَمِن قَبْلُ مَا فَرَّطتُمْ فِى يُوسُفَ ۖ فَلَنْ أَبْرَحَ ٱلْأَرْضَ حَتَّىٰ يَأْذَنَ لِىٓ أَبِىٓ أَوْ يَحْكُمَ ٱللَّهُ لِى ۖ وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ', 245, 13, 98, 0),
  (12, 81, 1677, 'ٱرْجِعُوٓا۟ إِلَىٰٓ أَبِيكُمْ فَقُولُوا۟ يَٰٓأَبَانَآ إِنَّ ٱبْنَكَ سَرَقَ وَمَا شَهِدْنَآ إِلَّا بِمَا عَلِمْنَا وَمَا كُنَّا لِلْغَيْبِ حَٰفِظِينَ', 245, 13, 98, 0),
  (12, 82, 1678, 'وَسْـَٔلِ ٱلْقَرْيَةَ ٱلَّتِى كُنَّا فِيهَا وَٱلْعِيرَ ٱلَّتِىٓ أَقْبَلْنَا فِيهَا ۖ وَإِنَّا لَصَٰدِقُونَ', 245, 13, 98, 0),
  (12, 83, 1679, 'قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًۭا ۖ فَصَبْرٌۭ جَمِيلٌ ۖ عَسَى ٱللَّهُ أَن يَأْتِيَنِى بِهِمْ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 245, 13, 98, 0),
  (12, 84, 1680, 'وَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبْيَضَّتْ عَيْنَاهُ مِنَ ٱلْحُزْنِ فَهُوَ كَظِيمٌۭ', 245, 13, 98, 0),
  (12, 85, 1681, 'قَالُوا۟ تَٱللَّهِ تَفْتَؤُا۟ تَذْكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوْ تَكُونَ مِنَ ٱلْهَٰلِكِينَ', 245, 13, 98, 0),
  (12, 86, 1682, 'قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 245, 13, 98, 0),
  (12, 87, 1683, 'يَٰبَنِىَّ ٱذْهَبُوا۟ فَتَحَسَّسُوا۟ مِن يُوسُفَ وَأَخِيهِ وَلَا تَا۟يْـَٔسُوا۟ مِن رَّوْحِ ٱللَّهِ ۖ إِنَّهُۥ لَا يَا۟يْـَٔسُ مِن رَّوْحِ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْكَٰفِرُونَ', 246, 13, 98, 0),
  (12, 88, 1684, 'فَلَمَّا دَخَلُوا۟ عَلَيْهِ قَالُوا۟ يَٰٓأَيُّهَا ٱلْعَزِيزُ مَسَّنَا وَأَهْلَنَا ٱلضُّرُّ وَجِئْنَا بِبِضَٰعَةٍۢ مُّزْجَىٰةٍۢ فَأَوْفِ لَنَا ٱلْكَيْلَ وَتَصَدَّقْ عَلَيْنَآ ۖ إِنَّ ٱللَّهَ يَجْزِى ٱلْمُتَصَدِّقِينَ', 246, 13, 98, 0),
  (12, 89, 1685, 'قَالَ هَلْ عَلِمْتُم مَّا فَعَلْتُم بِيُوسُفَ وَأَخِيهِ إِذْ أَنتُمْ جَٰهِلُونَ', 246, 13, 98, 0),
  (12, 90, 1686, 'قَالُوٓا۟ أَءِنَّكَ لَأَنتَ يُوسُفُ ۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِى ۖ قَدْ مَنَّ ٱللَّهُ عَلَيْنَآ ۖ إِنَّهُۥ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجْرَ ٱلْمُحْسِنِينَ', 246, 13, 98, 0),
  (12, 91, 1687, 'قَالُوا۟ تَٱللَّهِ لَقَدْ ءَاثَرَكَ ٱللَّهُ عَلَيْنَا وَإِن كُنَّا لَخَٰطِـِٔينَ', 246, 13, 98, 0),
  (12, 92, 1688, 'قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ', 246, 13, 98, 0),
  (12, 93, 1689, 'ٱذْهَبُوا۟ بِقَمِيصِى هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِى يَأْتِ بَصِيرًۭا وَأْتُونِى بِأَهْلِكُمْ أَجْمَعِينَ', 246, 13, 98, 0),
  (12, 94, 1690, 'وَلَمَّا فَصَلَتِ ٱلْعِيرُ قَالَ أَبُوهُمْ إِنِّى لَأَجِدُ رِيحَ يُوسُفَ ۖ لَوْلَآ أَن تُفَنِّدُونِ', 246, 13, 98, 0),
  (12, 95, 1691, 'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِى ضَلَٰلِكَ ٱلْقَدِيمِ', 246, 13, 98, 0),
  (12, 96, 1692, 'فَلَمَّآ أَن جَآءَ ٱلْبَشِيرُ أَلْقَىٰهُ عَلَىٰ وَجْهِهِۦ فَٱرْتَدَّ بَصِيرًۭا ۖ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ', 247, 13, 98, 0),
  (12, 97, 1693, 'قَالُوا۟ يَٰٓأَبَانَا ٱسْتَغْفِرْ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ', 247, 13, 98, 0),
  (12, 98, 1694, 'قَالَ سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّىٓ ۖ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 247, 13, 98, 0),
  (12, 99, 1695, 'فَلَمَّا دَخَلُوا۟ عَلَىٰ يُوسُفَ ءَاوَىٰٓ إِلَيْهِ أَبَوَيْهِ وَقَالَ ٱدْخُلُوا۟ مِصْرَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ', 247, 13, 98, 0),
  (12, 100, 1696, 'وَرَفَعَ أَبَوَيْهِ عَلَى ٱلْعَرْشِ وَخَرُّوا۟ لَهُۥ سُجَّدًۭا ۖ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأْوِيلُ رُءْيَٰىَ مِن قَبْلُ قَدْ جَعَلَهَا رَبِّى حَقًّۭا ۖ وَقَدْ أَحْسَنَ بِىٓ إِذْ أَخْرَجَنِى مِنَ ٱلسِّجْنِ وَجَآءَ بِكُم مِّنَ ٱلْبَدْوِ مِنۢ بَعْدِ أَن نَّزَغَ ٱلشَّيْطَٰنُ بَيْنِى وَبَيْنَ إِخْوَتِىٓ ۚ إِنَّ رَبِّى لَطِيفٌۭ لِّمَا يَشَآءُ ۚ إِنَّهُۥ هُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 247, 13, 98, 0),
  (12, 101, 1697, '۞ رَبِّ قَدْ ءَاتَيْتَنِى مِنَ ٱلْمُلْكِ وَعَلَّمْتَنِى مِن تَأْوِيلِ ٱلْأَحَادِيثِ ۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَنتَ وَلِىِّۦ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۖ تَوَفَّنِى مُسْلِمًۭا وَأَلْحِقْنِى بِٱلصَّٰلِحِينَ', 247, 13, 99, 0),
  (12, 102, 1698, 'ذَٰلِكَ مِنْ أَنۢبَآءِ ٱلْغَيْبِ نُوحِيهِ إِلَيْكَ ۖ وَمَا كُنتَ لَدَيْهِمْ إِذْ أَجْمَعُوٓا۟ أَمْرَهُمْ وَهُمْ يَمْكُرُونَ', 247, 13, 99, 0),
  (12, 103, 1699, 'وَمَآ أَكْثَرُ ٱلنَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ', 247, 13, 99, 0),
  (12, 104, 1700, 'وَمَا تَسْـَٔلُهُمْ عَلَيْهِ مِنْ أَجْرٍ ۚ إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 248, 13, 99, 0),
  (12, 105, 1701, 'وَكَأَيِّن مِّنْ ءَايَةٍۢ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَمُرُّونَ عَلَيْهَا وَهُمْ عَنْهَا مُعْرِضُونَ', 248, 13, 99, 0),
  (12, 106, 1702, 'وَمَا يُؤْمِنُ أَكْثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشْرِكُونَ', 248, 13, 99, 0),
  (12, 107, 1703, 'أَفَأَمِنُوٓا۟ أَن تَأْتِيَهُمْ غَٰشِيَةٌۭ مِّنْ عَذَابِ ٱللَّهِ أَوْ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 248, 13, 99, 0),
  (12, 108, 1704, 'قُلْ هَٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ ۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى ۖ وَسُبْحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ', 248, 13, 99, 0),
  (12, 109, 1705, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًۭا نُّوحِىٓ إِلَيْهِم مِّنْ أَهْلِ ٱلْقُرَىٰٓ ۗ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۗ وَلَدَارُ ٱلْءَاخِرَةِ خَيْرٌۭ لِّلَّذِينَ ٱتَّقَوْا۟ ۗ أَفَلَا تَعْقِلُونَ', 248, 13, 99, 0),
  (12, 110, 1706, 'حَتَّىٰٓ إِذَا ٱسْتَيْـَٔسَ ٱلرُّسُلُ وَظَنُّوٓا۟ أَنَّهُمْ قَدْ كُذِبُوا۟ جَآءَهُمْ نَصْرُنَا فَنُجِّىَ مَن نَّشَآءُ ۖ وَلَا يُرَدُّ بَأْسُنَا عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ', 248, 13, 99, 0),
  (12, 111, 1707, 'لَقَدْ كَانَ فِى قَصَصِهِمْ عِبْرَةٌۭ لِّأُو۟لِى ٱلْأَلْبَٰبِ ۗ مَا كَانَ حَدِيثًۭا يُفْتَرَىٰ وَلَٰكِن تَصْدِيقَ ٱلَّذِى بَيْنَ يَدَيْهِ وَتَفْصِيلَ كُلِّ شَىْءٍۢ وَهُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 248, 13, 99, 0),
  (13, 1, 1708, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓمٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ۗ وَٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 249, 13, 99, 0),
  (13, 2, 1709, 'ٱللَّهُ ٱلَّذِى رَفَعَ ٱلسَّمَٰوَٰتِ بِغَيْرِ عَمَدٍۢ تَرَوْنَهَا ۖ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّۭ يَجْرِى لِأَجَلٍۢ مُّسَمًّۭى ۚ يُدَبِّرُ ٱلْأَمْرَ يُفَصِّلُ ٱلْءَايَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمْ تُوقِنُونَ', 249, 13, 99, 0),
  (13, 3, 1710, 'وَهُوَ ٱلَّذِى مَدَّ ٱلْأَرْضَ وَجَعَلَ فِيهَا رَوَٰسِىَ وَأَنْهَٰرًۭا ۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوْجَيْنِ ٱثْنَيْنِ ۖ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 249, 13, 99, 0),
  (13, 4, 1711, 'وَفِى ٱلْأَرْضِ قِطَعٌۭ مُّتَجَٰوِرَٰتٌۭ وَجَنَّٰتٌۭ مِّنْ أَعْنَٰبٍۢ وَزَرْعٌۭ وَنَخِيلٌۭ صِنْوَانٌۭ وَغَيْرُ صِنْوَانٍۢ يُسْقَىٰ بِمَآءٍۢ وَٰحِدٍۢ وَنُفَضِّلُ بَعْضَهَا عَلَىٰ بَعْضٍۢ فِى ٱلْأُكُلِ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ', 249, 13, 99, 0),
  (13, 5, 1712, '۞ وَإِن تَعْجَبْ فَعَجَبٌۭ قَوْلُهُمْ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِى خَلْقٍۢ جَدِيدٍ ۗ أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ وَأُو۟لَٰٓئِكَ ٱلْأَغْلَٰلُ فِىٓ أَعْنَاقِهِمْ ۖ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 249, 13, 100, 0),
  (13, 6, 1713, 'وَيَسْتَعْجِلُونَكَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ وَقَدْ خَلَتْ مِن قَبْلِهِمُ ٱلْمَثُلَٰتُ ۗ وَإِنَّ رَبَّكَ لَذُو مَغْفِرَةٍۢ لِّلنَّاسِ عَلَىٰ ظُلْمِهِمْ ۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلْعِقَابِ', 250, 13, 100, 0),
  (13, 7, 1714, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦٓ ۗ إِنَّمَآ أَنتَ مُنذِرٌۭ ۖ وَلِكُلِّ قَوْمٍ هَادٍ', 250, 13, 100, 0),
  (13, 8, 1715, 'ٱللَّهُ يَعْلَمُ مَا تَحْمِلُ كُلُّ أُنثَىٰ وَمَا تَغِيضُ ٱلْأَرْحَامُ وَمَا تَزْدَادُ ۖ وَكُلُّ شَىْءٍ عِندَهُۥ بِمِقْدَارٍ', 250, 13, 100, 0),
  (13, 9, 1716, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْكَبِيرُ ٱلْمُتَعَالِ', 250, 13, 100, 0),
  (13, 10, 1717, 'سَوَآءٌۭ مِّنكُم مَّنْ أَسَرَّ ٱلْقَوْلَ وَمَن جَهَرَ بِهِۦ وَمَنْ هُوَ مُسْتَخْفٍۭ بِٱلَّيْلِ وَسَارِبٌۢ بِٱلنَّهَارِ', 250, 13, 100, 0),
  (13, 11, 1718, 'لَهُۥ مُعَقِّبَٰتٌۭ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍۢ سُوٓءًۭا فَلَا مَرَدَّ لَهُۥ ۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ', 250, 13, 100, 0),
  (13, 12, 1719, 'هُوَ ٱلَّذِى يُرِيكُمُ ٱلْبَرْقَ خَوْفًۭا وَطَمَعًۭا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ', 250, 13, 100, 0),
  (13, 13, 1720, 'وَيُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِۦ وَٱلْمَلَٰٓئِكَةُ مِنْ خِيفَتِهِۦ وَيُرْسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمْ يُجَٰدِلُونَ فِى ٱللَّهِ وَهُوَ شَدِيدُ ٱلْمِحَالِ', 250, 13, 100, 0),
  (13, 14, 1721, 'لَهُۥ دَعْوَةُ ٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَسْتَجِيبُونَ لَهُم بِشَىْءٍ إِلَّا كَبَٰسِطِ كَفَّيْهِ إِلَى ٱلْمَآءِ لِيَبْلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦ ۚ وَمَا دُعَآءُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍۢ', 251, 13, 100, 0),
  (13, 15, 1722, 'وَلِلَّهِ يَسْجُدُ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ طَوْعًۭا وَكَرْهًۭا وَظِلَٰلُهُم بِٱلْغُدُوِّ وَٱلْءَاصَالِ ۩', 251, 13, 100, 1),
  (13, 16, 1723, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ ۚ قُلْ أَفَٱتَّخَذْتُم مِّن دُونِهِۦٓ أَوْلِيَآءَ لَا يَمْلِكُونَ لِأَنفُسِهِمْ نَفْعًۭا وَلَا ضَرًّۭا ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ أَمْ هَلْ تَسْتَوِى ٱلظُّلُمَٰتُ وَٱلنُّورُ ۗ أَمْ جَعَلُوا۟ لِلَّهِ شُرَكَآءَ خَلَقُوا۟ كَخَلْقِهِۦ فَتَشَٰبَهَ ٱلْخَلْقُ عَلَيْهِمْ ۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍۢ وَهُوَ ٱلْوَٰحِدُ ٱلْقَهَّٰرُ', 251, 13, 100, 0),
  (13, 17, 1724, 'أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَسَالَتْ أَوْدِيَةٌۢ بِقَدَرِهَا فَٱحْتَمَلَ ٱلسَّيْلُ زَبَدًۭا رَّابِيًۭا ۚ وَمِمَّا يُوقِدُونَ عَلَيْهِ فِى ٱلنَّارِ ٱبْتِغَآءَ حِلْيَةٍ أَوْ مَتَٰعٍۢ زَبَدٌۭ مِّثْلُهُۥ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْحَقَّ وَٱلْبَٰطِلَ ۚ فَأَمَّا ٱلزَّبَدُ فَيَذْهَبُ جُفَآءًۭ ۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمْكُثُ فِى ٱلْأَرْضِ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ', 251, 13, 100, 0),
  (13, 18, 1725, 'لِلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمُ ٱلْحُسْنَىٰ ۚ وَٱلَّذِينَ لَمْ يَسْتَجِيبُوا۟ لَهُۥ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًۭا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦٓ ۚ أُو۟لَٰٓئِكَ لَهُمْ سُوٓءُ ٱلْحِسَابِ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمِهَادُ', 251, 13, 100, 0),
  (13, 19, 1726, '۞ أَفَمَن يَعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ٱلْحَقُّ كَمَنْ هُوَ أَعْمَىٰٓ ۚ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 252, 13, 101, 0),
  (13, 20, 1727, 'ٱلَّذِينَ يُوفُونَ بِعَهْدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلْمِيثَٰقَ', 252, 13, 101, 0),
  (13, 21, 1728, 'وَٱلَّذِينَ يَصِلُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوٓءَ ٱلْحِسَابِ', 252, 13, 101, 0),
  (13, 22, 1729, 'وَٱلَّذِينَ صَبَرُوا۟ ٱبْتِغَآءَ وَجْهِ رَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّۭا وَعَلَانِيَةًۭ وَيَدْرَءُونَ بِٱلْحَسَنَةِ ٱلسَّيِّئَةَ أُو۟لَٰٓئِكَ لَهُمْ عُقْبَى ٱلدَّارِ', 252, 13, 101, 0),
  (13, 23, 1730, 'جَنَّٰتُ عَدْنٍۢ يَدْخُلُونَهَا وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۖ وَٱلْمَلَٰٓئِكَةُ يَدْخُلُونَ عَلَيْهِم مِّن كُلِّ بَابٍۢ', 252, 13, 101, 0),
  (13, 24, 1731, 'سَلَٰمٌ عَلَيْكُم بِمَا صَبَرْتُمْ ۚ فَنِعْمَ عُقْبَى ٱلدَّارِ', 252, 13, 101, 0),
  (13, 25, 1732, 'وَٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ ۙ أُو۟لَٰٓئِكَ لَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 252, 13, 101, 0),
  (13, 26, 1733, 'ٱللَّهُ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ وَفَرِحُوا۟ بِٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا فِى ٱلْءَاخِرَةِ إِلَّا مَتَٰعٌۭ', 252, 13, 101, 0),
  (13, 27, 1734, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ ءَايَةٌۭ مِّن رَّبِّهِۦ ۗ قُلْ إِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَنْ أَنَابَ', 252, 13, 101, 0),
  (13, 28, 1735, 'ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', 252, 13, 101, 0),
  (13, 29, 1736, 'ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ طُوبَىٰ لَهُمْ وَحُسْنُ مَـَٔابٍۢ', 253, 13, 101, 0),
  (13, 30, 1737, 'كَذَٰلِكَ أَرْسَلْنَٰكَ فِىٓ أُمَّةٍۢ قَدْ خَلَتْ مِن قَبْلِهَآ أُمَمٌۭ لِّتَتْلُوَا۟ عَلَيْهِمُ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَهُمْ يَكْفُرُونَ بِٱلرَّحْمَٰنِ ۚ قُلْ هُوَ رَبِّى لَآ إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ', 253, 13, 101, 0),
  (13, 31, 1738, 'وَلَوْ أَنَّ قُرْءَانًۭا سُيِّرَتْ بِهِ ٱلْجِبَالُ أَوْ قُطِّعَتْ بِهِ ٱلْأَرْضُ أَوْ كُلِّمَ بِهِ ٱلْمَوْتَىٰ ۗ بَل لِّلَّهِ ٱلْأَمْرُ جَمِيعًا ۗ أَفَلَمْ يَا۟يْـَٔسِ ٱلَّذِينَ ءَامَنُوٓا۟ أَن لَّوْ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعًۭا ۗ وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ تُصِيبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوْ تَحُلُّ قَرِيبًۭا مِّن دَارِهِمْ حَتَّىٰ يَأْتِىَ وَعْدُ ٱللَّهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 253, 13, 101, 0),
  (13, 32, 1739, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَأَمْلَيْتُ لِلَّذِينَ كَفَرُوا۟ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ', 253, 13, 101, 0),
  (13, 33, 1740, 'أَفَمَنْ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفْسٍۭ بِمَا كَسَبَتْ ۗ وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ قُلْ سَمُّوهُمْ ۚ أَمْ تُنَبِّـُٔونَهُۥ بِمَا لَا يَعْلَمُ فِى ٱلْأَرْضِ أَم بِظَٰهِرٍۢ مِّنَ ٱلْقَوْلِ ۗ بَلْ زُيِّنَ لِلَّذِينَ كَفَرُوا۟ مَكْرُهُمْ وَصُدُّوا۟ عَنِ ٱلسَّبِيلِ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍۢ', 253, 13, 101, 0),
  (13, 34, 1741, 'لَّهُمْ عَذَابٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَشَقُّ ۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقٍۢ', 253, 13, 101, 0),
  (13, 35, 1742, '۞ مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ أُكُلُهَا دَآئِمٌۭ وَظِلُّهَا ۚ تِلْكَ عُقْبَى ٱلَّذِينَ ٱتَّقَوا۟ ۖ وَّعُقْبَى ٱلْكَٰفِرِينَ ٱلنَّارُ', 254, 13, 102, 0),
  (13, 36, 1743, 'وَٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَفْرَحُونَ بِمَآ أُنزِلَ إِلَيْكَ ۖ وَمِنَ ٱلْأَحْزَابِ مَن يُنكِرُ بَعْضَهُۥ ۚ قُلْ إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ وَلَآ أُشْرِكَ بِهِۦٓ ۚ إِلَيْهِ أَدْعُوا۟ وَإِلَيْهِ مَـَٔابِ', 254, 13, 102, 0),
  (13, 37, 1744, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ حُكْمًا عَرَبِيًّۭا ۚ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَمَا جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّۢ وَلَا وَاقٍۢ', 254, 13, 102, 0),
  (13, 38, 1745, 'وَلَقَدْ أَرْسَلْنَا رُسُلًۭا مِّن قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَٰجًۭا وَذُرِّيَّةًۭ ۚ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ لِكُلِّ أَجَلٍۢ كِتَابٌۭ', 254, 13, 102, 0),
  (13, 39, 1746, 'يَمْحُوا۟ ٱللَّهُ مَا يَشَآءُ وَيُثْبِتُ ۖ وَعِندَهُۥٓ أُمُّ ٱلْكِتَٰبِ', 254, 13, 102, 0),
  (13, 40, 1747, 'وَإِن مَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ وَعَلَيْنَا ٱلْحِسَابُ', 254, 13, 102, 0),
  (13, 41, 1748, 'أَوَلَمْ يَرَوْا۟ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَا ۚ وَٱللَّهُ يَحْكُمُ لَا مُعَقِّبَ لِحُكْمِهِۦ ۚ وَهُوَ سَرِيعُ ٱلْحِسَابِ', 254, 13, 102, 0),
  (13, 42, 1749, 'وَقَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَلِلَّهِ ٱلْمَكْرُ جَمِيعًۭا ۖ يَعْلَمُ مَا تَكْسِبُ كُلُّ نَفْسٍۢ ۗ وَسَيَعْلَمُ ٱلْكُفَّٰرُ لِمَنْ عُقْبَى ٱلدَّارِ', 254, 13, 102, 0),
  (13, 43, 1750, 'وَيَقُولُ ٱلَّذِينَ كَفَرُوا۟ لَسْتَ مُرْسَلًۭا ۚ قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَٰبِ', 255, 13, 102, 0),
  (14, 1, 1751, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ بِإِذْنِ رَبِّهِمْ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 255, 13, 102, 0),
  (14, 2, 1752, 'ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَوَيْلٌۭ لِّلْكَٰفِرِينَ مِنْ عَذَابٍۢ شَدِيدٍ', 255, 13, 102, 0),
  (14, 3, 1753, 'ٱلَّذِينَ يَسْتَحِبُّونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْءَاخِرَةِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا ۚ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۭ بَعِيدٍۢ', 255, 13, 102, 0),
  (14, 4, 1754, 'وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ ۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 255, 13, 102, 0),
  (14, 5, 1755, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنْ أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّكُلِّ صَبَّارٍۢ شَكُورٍۢ', 255, 13, 102, 0),
  (14, 6, 1756, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ أَنجَىٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ وَيُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌۭ مِّن رَّبِّكُمْ عَظِيمٌۭ', 256, 13, 102, 0),
  (14, 7, 1757, 'وَإِذْ تَأَذَّنَ رَبُّكُمْ لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَئِن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌۭ', 256, 13, 102, 0),
  (14, 8, 1758, 'وَقَالَ مُوسَىٰٓ إِن تَكْفُرُوٓا۟ أَنتُمْ وَمَن فِى ٱلْأَرْضِ جَمِيعًۭا فَإِنَّ ٱللَّهَ لَغَنِىٌّ حَمِيدٌ', 256, 13, 102, 0),
  (14, 9, 1759, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ مِن قَبْلِكُمْ قَوْمِ نُوحٍۢ وَعَادٍۢ وَثَمُودَ ۛ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۛ لَا يَعْلَمُهُمْ إِلَّا ٱللَّهُ ۚ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرَدُّوٓا۟ أَيْدِيَهُمْ فِىٓ أَفْوَٰهِهِمْ وَقَالُوٓا۟ إِنَّا كَفَرْنَا بِمَآ أُرْسِلْتُم بِهِۦ وَإِنَّا لَفِى شَكٍّۢ مِّمَّا تَدْعُونَنَآ إِلَيْهِ مُرِيبٍۢ', 256, 13, 102, 0),
  (14, 10, 1760, '۞ قَالَتْ رُسُلُهُمْ أَفِى ٱللَّهِ شَكٌّۭ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يَدْعُوكُمْ لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ۚ قَالُوٓا۟ إِنْ أَنتُمْ إِلَّا بَشَرٌۭ مِّثْلُنَا تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتُونَا بِسُلْطَٰنٍۢ مُّبِينٍۢ', 256, 13, 103, 0),
  (14, 11, 1761, 'قَالَتْ لَهُمْ رُسُلُهُمْ إِن نَّحْنُ إِلَّا بَشَرٌۭ مِّثْلُكُمْ وَلَٰكِنَّ ٱللَّهَ يَمُنُّ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَمَا كَانَ لَنَآ أَن نَّأْتِيَكُم بِسُلْطَٰنٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 257, 13, 103, 0),
  (14, 12, 1762, 'وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدْ هَدَىٰنَا سُبُلَنَا ۚ وَلَنَصْبِرَنَّ عَلَىٰ مَآ ءَاذَيْتُمُونَا ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُتَوَكِّلُونَ', 257, 13, 103, 0),
  (14, 13, 1763, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِرُسُلِهِمْ لَنُخْرِجَنَّكُم مِّنْ أَرْضِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۖ فَأَوْحَىٰٓ إِلَيْهِمْ رَبُّهُمْ لَنُهْلِكَنَّ ٱلظَّٰلِمِينَ', 257, 13, 103, 0),
  (14, 14, 1764, 'وَلَنُسْكِنَنَّكُمُ ٱلْأَرْضَ مِنۢ بَعْدِهِمْ ۚ ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ', 257, 13, 103, 0),
  (14, 15, 1765, 'وَٱسْتَفْتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِيدٍۢ', 257, 13, 103, 0),
  (14, 16, 1766, 'مِّن وَرَآئِهِۦ جَهَنَّمُ وَيُسْقَىٰ مِن مَّآءٍۢ صَدِيدٍۢ', 257, 13, 103, 0),
  (14, 17, 1767, 'يَتَجَرَّعُهُۥ وَلَا يَكَادُ يُسِيغُهُۥ وَيَأْتِيهِ ٱلْمَوْتُ مِن كُلِّ مَكَانٍۢ وَمَا هُوَ بِمَيِّتٍۢ ۖ وَمِن وَرَآئِهِۦ عَذَابٌ غَلِيظٌۭ', 257, 13, 103, 0),
  (14, 18, 1768, 'مَّثَلُ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ ۖ أَعْمَٰلُهُمْ كَرَمَادٍ ٱشْتَدَّتْ بِهِ ٱلرِّيحُ فِى يَوْمٍ عَاصِفٍۢ ۖ لَّا يَقْدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَىْءٍۢ ۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', 257, 13, 103, 0),
  (14, 19, 1769, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍۢ جَدِيدٍۢ', 258, 13, 103, 0),
  (14, 20, 1770, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍۢ', 258, 13, 103, 0),
  (14, 21, 1771, 'وَبَرَزُوا۟ لِلَّهِ جَمِيعًۭا فَقَالَ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًۭا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا مِنْ عَذَابِ ٱللَّهِ مِن شَىْءٍۢ ۚ قَالُوا۟ لَوْ هَدَىٰنَا ٱللَّهُ لَهَدَيْنَٰكُمْ ۖ سَوَآءٌ عَلَيْنَآ أَجَزِعْنَآ أَمْ صَبَرْنَا مَا لَنَا مِن مَّحِيصٍۢ', 258, 13, 103, 0),
  (14, 22, 1772, 'وَقَالَ ٱلشَّيْطَٰنُ لَمَّا قُضِىَ ٱلْأَمْرُ إِنَّ ٱللَّهَ وَعَدَكُمْ وَعْدَ ٱلْحَقِّ وَوَعَدتُّكُمْ فَأَخْلَفْتُكُمْ ۖ وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَٰنٍ إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى ۖ فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم ۖ مَّآ أَنَا۠ بِمُصْرِخِكُمْ وَمَآ أَنتُم بِمُصْرِخِىَّ ۖ إِنِّى كَفَرْتُ بِمَآ أَشْرَكْتُمُونِ مِن قَبْلُ ۗ إِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌۭ', 258, 13, 103, 0),
  (14, 23, 1773, 'وَأُدْخِلَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا بِإِذْنِ رَبِّهِمْ ۖ تَحِيَّتُهُمْ فِيهَا سَلَٰمٌ', 258, 13, 103, 0),
  (14, 24, 1774, 'أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًۭا كَلِمَةًۭ طَيِّبَةًۭ كَشَجَرَةٍۢ طَيِّبَةٍ أَصْلُهَا ثَابِتٌۭ وَفَرْعُهَا فِى ٱلسَّمَآءِ', 258, 13, 103, 0),
  (14, 25, 1775, 'تُؤْتِىٓ أُكُلَهَا كُلَّ حِينٍۭ بِإِذْنِ رَبِّهَا ۗ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَالَ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ', 259, 13, 103, 0),
  (14, 26, 1776, 'وَمَثَلُ كَلِمَةٍ خَبِيثَةٍۢ كَشَجَرَةٍ خَبِيثَةٍ ٱجْتُثَّتْ مِن فَوْقِ ٱلْأَرْضِ مَا لَهَا مِن قَرَارٍۢ', 259, 13, 103, 0),
  (14, 27, 1777, 'يُثَبِّتُ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ بِٱلْقَوْلِ ٱلثَّابِتِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ ۖ وَيُضِلُّ ٱللَّهُ ٱلظَّٰلِمِينَ ۚ وَيَفْعَلُ ٱللَّهُ مَا يَشَآءُ', 259, 13, 103, 0),
  (14, 28, 1778, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ بَدَّلُوا۟ نِعْمَتَ ٱللَّهِ كُفْرًۭا وَأَحَلُّوا۟ قَوْمَهُمْ دَارَ ٱلْبَوَارِ', 259, 13, 104, 0),
  (14, 29, 1779, 'جَهَنَّمَ يَصْلَوْنَهَا ۖ وَبِئْسَ ٱلْقَرَارُ', 259, 13, 104, 0),
  (14, 30, 1780, 'وَجَعَلُوا۟ لِلَّهِ أَندَادًۭا لِّيُضِلُّوا۟ عَن سَبِيلِهِۦ ۗ قُلْ تَمَتَّعُوا۟ فَإِنَّ مَصِيرَكُمْ إِلَى ٱلنَّارِ', 259, 13, 104, 0),
  (14, 31, 1781, 'قُل لِّعِبَادِىَ ٱلَّذِينَ ءَامَنُوا۟ يُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُنفِقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّۭا وَعَلَانِيَةًۭ مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خِلَٰلٌ', 259, 13, 104, 0),
  (14, 32, 1782, 'ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًۭا لَّكُمْ ۖ وَسَخَّرَ لَكُمُ ٱلْفُلْكَ لِتَجْرِىَ فِى ٱلْبَحْرِ بِأَمْرِهِۦ ۖ وَسَخَّرَ لَكُمُ ٱلْأَنْهَٰرَ', 259, 13, 104, 0),
  (14, 33, 1783, 'وَسَخَّرَ لَكُمُ ٱلشَّمْسَ وَٱلْقَمَرَ دَآئِبَيْنِ ۖ وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', 259, 13, 104, 0),
  (14, 34, 1784, 'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ ۚ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱلْإِنسَٰنَ لَظَلُومٌۭ كَفَّارٌۭ', 260, 13, 104, 0),
  (14, 35, 1785, 'وَإِذْ قَالَ إِبْرَٰهِيمُ رَبِّ ٱجْعَلْ هَٰذَا ٱلْبَلَدَ ءَامِنًۭا وَٱجْنُبْنِى وَبَنِىَّ أَن نَّعْبُدَ ٱلْأَصْنَامَ', 260, 13, 104, 0),
  (14, 36, 1786, 'رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًۭا مِّنَ ٱلنَّاسِ ۖ فَمَن تَبِعَنِى فَإِنَّهُۥ مِنِّى ۖ وَمَنْ عَصَانِى فَإِنَّكَ غَفُورٌۭ رَّحِيمٌۭ', 260, 13, 104, 0),
  (14, 37, 1787, 'رَّبَّنَآ إِنِّىٓ أَسْكَنتُ مِن ذُرِّيَّتِى بِوَادٍ غَيْرِ ذِى زَرْعٍ عِندَ بَيْتِكَ ٱلْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا۟ ٱلصَّلَوٰةَ فَٱجْعَلْ أَفْـِٔدَةًۭ مِّنَ ٱلنَّاسِ تَهْوِىٓ إِلَيْهِمْ وَٱرْزُقْهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَشْكُرُونَ', 260, 13, 104, 0),
  (14, 38, 1788, 'رَبَّنَآ إِنَّكَ تَعْلَمُ مَا نُخْفِى وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى ٱللَّهِ مِن شَىْءٍۢ فِى ٱلْأَرْضِ وَلَا فِى ٱلسَّمَآءِ', 260, 13, 104, 0),
  (14, 39, 1789, 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى وَهَبَ لِى عَلَى ٱلْكِبَرِ إِسْمَٰعِيلَ وَإِسْحَٰقَ ۚ إِنَّ رَبِّى لَسَمِيعُ ٱلدُّعَآءِ', 260, 13, 104, 0),
  (14, 40, 1790, 'رَبِّ ٱجْعَلْنِى مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِى ۚ رَبَّنَا وَتَقَبَّلْ دُعَآءِ', 260, 13, 104, 0),
  (14, 41, 1791, 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', 260, 13, 104, 0),
  (14, 42, 1792, 'وَلَا تَحْسَبَنَّ ٱللَّهَ غَٰفِلًا عَمَّا يَعْمَلُ ٱلظَّٰلِمُونَ ۚ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍۢ تَشْخَصُ فِيهِ ٱلْأَبْصَٰرُ', 260, 13, 104, 0),
  (14, 43, 1793, 'مُهْطِعِينَ مُقْنِعِى رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ ۖ وَأَفْـِٔدَتُهُمْ هَوَآءٌۭ', 261, 13, 104, 0),
  (14, 44, 1794, 'وَأَنذِرِ ٱلنَّاسَ يَوْمَ يَأْتِيهِمُ ٱلْعَذَابُ فَيَقُولُ ٱلَّذِينَ ظَلَمُوا۟ رَبَّنَآ أَخِّرْنَآ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَ ۗ أَوَلَمْ تَكُونُوٓا۟ أَقْسَمْتُم مِّن قَبْلُ مَا لَكُم مِّن زَوَالٍۢ', 261, 13, 104, 0),
  (14, 45, 1795, 'وَسَكَنتُمْ فِى مَسَٰكِنِ ٱلَّذِينَ ظَلَمُوٓا۟ أَنفُسَهُمْ وَتَبَيَّنَ لَكُمْ كَيْفَ فَعَلْنَا بِهِمْ وَضَرَبْنَا لَكُمُ ٱلْأَمْثَالَ', 261, 13, 104, 0),
  (14, 46, 1796, 'وَقَدْ مَكَرُوا۟ مَكْرَهُمْ وَعِندَ ٱللَّهِ مَكْرُهُمْ وَإِن كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ ٱلْجِبَالُ', 261, 13, 104, 0),
  (14, 47, 1797, 'فَلَا تَحْسَبَنَّ ٱللَّهَ مُخْلِفَ وَعْدِهِۦ رُسُلَهُۥٓ ۗ إِنَّ ٱللَّهَ عَزِيزٌۭ ذُو ٱنتِقَامٍۢ', 261, 13, 104, 0),
  (14, 48, 1798, 'يَوْمَ تُبَدَّلُ ٱلْأَرْضُ غَيْرَ ٱلْأَرْضِ وَٱلسَّمَٰوَٰتُ ۖ وَبَرَزُوا۟ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 261, 13, 104, 0),
  (14, 49, 1799, 'وَتَرَى ٱلْمُجْرِمِينَ يَوْمَئِذٍۢ مُّقَرَّنِينَ فِى ٱلْأَصْفَادِ', 261, 13, 104, 0),
  (14, 50, 1800, 'سَرَابِيلُهُم مِّن قَطِرَانٍۢ وَتَغْشَىٰ وُجُوهَهُمُ ٱلنَّارُ', 261, 13, 104, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 14, 1, 'Alif, Lam, Ra. [This is] a Book which We have revealed to you, [O Muhammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -'),
  ('en.sahih', 14, 2, 'Allah, to whom belongs whatever is in the heavens and whatever is on the earth. And woe to the disbelievers from a severe punishment'),
  ('en.sahih', 14, 3, 'The ones who prefer the worldly life over the Hereafter and avert [people] from the way of Allah, seeking to make it (seem) deviant. Those are in extreme error.'),
  ('en.sahih', 14, 4, 'And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allah sends astray [thereby] whom He wills and guides whom He wills. And He is the Exalted in Might, the Wise.'),
  ('en.sahih', 14, 5, 'And We certainly sent Moses with Our signs, [saying], "Bring out your people from darknesses into the light and remind them of the days of Allah." Indeed in that are signs for everyone patient and grateful.'),
  ('en.sahih', 14, 6, 'And [recall, O Children of Israel], when Moses said to His people, "Remember the favor of Allah upon you when He saved you from the people of Pharaoh, who were afflicting you with the worst torment and were slaughtering your [newborn] sons and keeping your females alive. And in that was a great trial from your Lord.'),
  ('en.sahih', 14, 7, 'And [remember] when your Lord proclaimed, \'If you are grateful, I will surely increase you [in favor]; but if you deny, indeed, My punishment is severe.\' "'),
  ('en.sahih', 14, 8, 'And Moses said, "If you should disbelieve, you and whoever is on the earth entirely - indeed, Allah is Free of need and Praiseworthy."'),
  ('en.sahih', 14, 9, 'Has there not reached you the news of those before you - the people of Noah and \'Aad and Thamud and those after them? No one knows them but Allah. Their messengers brought them clear proofs, but they returned their hands to their mouths and said, "Indeed, we disbelieve in that with which you have been sent, and indeed we are, about that to which you invite us, in disquieting doubt."'),
  ('en.sahih', 14, 10, 'Their messengers said, "Can there be doubt about Allah, Creator of the heavens and earth? He invites you that He may forgive you of your sins, and He delays your death for a specified term." They said, "You are not but men like us who wish to avert us from what our fathers were worshipping. So bring us a clear authority."'),
  ('en.sahih', 14, 11, 'Their messengers said to them, "We are only men like you, but Allah confers favor upon whom He wills of His servants. It has never been for us to bring you evidence except by permission of Allah. And upon Allah let the believers rely.'),
  ('en.sahih', 14, 12, 'And why should we not rely upon Allah while He has guided us to our [good] ways. And we will surely be patient against whatever harm you should cause us. And upon Allah let those who would rely [indeed] rely."'),
  ('en.sahih', 14, 13, 'And those who disbelieved said to their messengers, "We will surely drive you out of our land, or you must return to our religion." So their Lord inspired to them, "We will surely destroy the wrongdoers.'),
  ('en.sahih', 14, 14, 'And We will surely cause you to dwell in the land after them. That is for he who fears My position and fears My threat."'),
  ('en.sahih', 14, 15, 'And they requested victory from Allah, and disappointed, [therefore], was every obstinate tyrant.'),
  ('en.sahih', 14, 16, 'Before him is Hell, and he will be given a drink of purulent water.'),
  ('en.sahih', 14, 17, 'He will gulp it but will hardly [be able to] swallow it. And death will come to him from everywhere, but he is not to die. And before him is a massive punishment.'),
  ('en.sahih', 14, 18, 'The example of those who disbelieve in their Lord is [that] their deeds are like ashes which the wind blows forcefully on a stormy day; they are unable [to keep] from what they earned a [single] thing. That is what is extreme error.'),
  ('en.sahih', 14, 19, 'Have you not seen that Allah created the heavens and the earth in truth? If He wills, He can do away with you and produce a new creation.'),
  ('en.sahih', 14, 20, 'And that is not difficult for Allah.'),
  ('en.sahih', 14, 21, 'And they will come out [for judgement] before Allah all together, and the weak will say to those who were arrogant, "Indeed, we were your followers, so can you avail us anything against the punishment of Allah?" They will say, "If Allah had guided us, we would have guided you. It is all the same for us whether we show intolerance or are patient: there is for us no place of escape."'),
  ('en.sahih', 14, 22, 'And Satan will say when the matter has been concluded, "Indeed, Allah had promised you the promise of truth. And I promised you, but I betrayed you. But I had no authority over you except that I invited you, and you responded to me. So do not blame me; but blame yourselves. I cannot be called to your aid, nor can you be called to my aid. Indeed, I deny your association of me [with Allah] before. Indeed, for the wrongdoers is a painful punishment."'),
  ('en.sahih', 14, 23, 'And those who believed and did righteous deeds will be admitted to gardens beneath which rivers flow, abiding eternally therein by permission of their Lord; and their greeting therein will be, "Peace!"'),
  ('en.sahih', 14, 24, 'Have you not considered how Allah presents an example, [making] a good word like a good tree, whose root is firmly fixed and its branches [high] in the sky?'),
  ('en.sahih', 14, 25, 'It produces its fruit all the time, by permission of its Lord. And Allah presents examples for the people that perhaps they will be reminded.'),
  ('en.sahih', 14, 26, 'And the example of a bad word is like a bad tree, uprooted from the surface of the earth, not having any stability.'),
  ('en.sahih', 14, 27, 'Allah keeps firm those who believe, with the firm word, in worldly life and in the Hereafter. And Allah sends astray the wrongdoers. And Allah does what He wills.'),
  ('en.sahih', 14, 28, 'Have you not considered those who exchanged the favor of Allah for disbelief and settled their people [in] the home of ruin?'),
  ('en.sahih', 14, 29, '[It is] Hell, which they will [enter to] burn, and wretched is the settlement.'),
  ('en.sahih', 14, 30, 'And they have attributed to Allah equals to mislead [people] from His way. Say, "Enjoy yourselves, for indeed, your destination is the Fire."'),
  ('en.sahih', 14, 31, '[O Muhammad], tell My servants who have believed to establish prayer and spend from what We have provided them, secretly and publicly, before a Day comes in which there will be no exchange, nor any friendships.'),
  ('en.sahih', 14, 32, 'It is Allah who created the heavens and the earth and sent down rain from the sky and produced thereby some fruits as provision for you and subjected for you the ships to sail through the sea by His command and subjected for you the rivers.'),
  ('en.sahih', 14, 33, 'And He subjected for you the sun and the moon, continuous [in orbit], and subjected for you the night and the day.'),
  ('en.sahih', 14, 34, 'And He gave you from all you asked of Him. And if you should count the favor of Allah, you could not enumerate them. Indeed, mankind is [generally] most unjust and ungrateful.'),
  ('en.sahih', 14, 35, 'And [mention, O Muhammad], when Abraham said, "My Lord, make this city [Makkah] secure and keep me and my sons away from worshipping idols.'),
  ('en.sahih', 14, 36, 'My Lord, indeed they have led astray many among the people. So whoever follows me - then he is of me; and whoever disobeys me - indeed, You are [yet] Forgiving and Merciful.'),
  ('en.sahih', 14, 37, 'Our Lord, I have settled some of my descendants in an uncultivated valley near Your sacred House, our Lord, that they may establish prayer. So make hearts among the people incline toward them and provide for them from the fruits that they might be grateful.'),
  ('en.sahih', 14, 38, 'Our Lord, indeed You know what we conceal and what we declare, and nothing is hidden from Allah on the earth or in the heaven.'),
  ('en.sahih', 14, 39, 'Praise to Allah, who has granted to me in old age Ishmael and Isaac. Indeed, my Lord is the Hearer of supplication.'),
  ('en.sahih', 14, 40, 'My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.'),
  ('en.sahih', 14, 41, 'Our Lord, forgive me and my parents and the believers the Day the account is established."'),
  ('en.sahih', 14, 42, 'And never think that Allah is unaware of what the wrongdoers do. He only delays them for a Day when eyes will stare [in horror].'),
  ('en.sahih', 14, 43, 'Racing ahead, their heads raised up, their glance does not come back to them, and their hearts are void.'),
  ('en.sahih', 14, 44, 'And, [O Muhammad], warn the people of a Day when the punishment will come to them and those who did wrong will say, "Our Lord, delay us for a short term; we will answer Your call and follow the messengers." [But it will be said], "Had you not sworn, before, that for you there would be no cessation?'),
  ('en.sahih', 14, 45, 'And you lived among the dwellings of those who wronged themselves, and it had become clear to you how We dealt with them. And We presented for you [many] examples."'),
  ('en.sahih', 14, 46, 'And they had planned their plan, but with Allah is [recorded] their plan, even if their plan had been [sufficient] to do away with the mountains.'),
  ('en.sahih', 14, 47, 'So never think that Allah will fail in His promise to His messengers. Indeed, Allah is Exalted in Might and Owner of Retribution.'),
  ('en.sahih', 14, 48, '[It will be] on the Day the earth will be replaced by another earth, and the heavens [as well], and all creatures will come out before Allah, the One, the Prevailing.'),
  ('en.sahih', 14, 49, 'And you will see the criminals that Day bound together in shackles,'),
  ('en.sahih', 14, 50, 'Their garments of liquid pitch and their faces covered by the Fire.'),
  ('en.sahih', 14, 51, 'So that Allah will recompense every soul for what it earned. Indeed, Allah is swift in account.'),
  ('en.sahih', 14, 52, 'This [Qur\'an] is notification for the people that they may be warned thereby and that they may know that He is but one God and that those of understanding will be reminded.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 14, 1, 'আলিফ-লাম-রা; এটি একটি গ্রন্থ, যা আমি আপনার প্রতি নাযিল করেছি-যাতে আপনি মানুষকে অন্ধকার থেকে আলোর দিকে বের করে আনেন-পরাক্রান্ত, প্রশংসার যোগ্য পালনকর্তার নির্দেশে তাঁরই পথের দিকে।'),
  ('bn.bengali', 14, 2, 'তিনি আল্লাহ; যিনি নভোমন্ডল ও ভূ-মন্ডলের সবকিছুর মালিক। কাফেরদের জন্যে বিপদ রয়েছে, কঠোর আযাব;'),
  ('bn.bengali', 14, 3, 'যারা পরকালের চাইতে পার্থিব জীবনকে পছন্দ করে; আল্লাহর পথে বাধা দান করে এবং তাতে বক্রতা অন্বেষণ করে, তারা পথ ভুলে দূরে পড়ে আছে।'),
  ('bn.bengali', 14, 4, 'আমি সব পয়গম্বরকেই তাদের স্বজাতির ভাষাভাষী করেই প্রেরণ করেছি, যাতে তাদেরকে পরিষ্কার বোঝাতে পারে। অতঃপর আল্লাহ যাকে ইচ্ছা, পথঃভ্রষ্ট করেন এবং যাকে ইচ্ছা সৎপথ প্রদর্শন করেন। তিনি পরাক্রান্ত, প্রজ্ঞাময়।'),
  ('bn.bengali', 14, 5, 'আমি মূসাকে নিদর্শনাবলী সহ প্রেরণ করেছিলাম যে, স্বজাতিকে অন্ধকার থেকে আলোর দিকে আনয়ন এবং তাদেরকে আল্লাহর দিনসমূহ স্মরণ করান। নিশ্চয় এতে প্রত্যেক ধৈর্যশীল কৃতজ্ঞের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 14, 6, 'যখন মূসা স্বজাতিকে বললেনঃ তোমাদের প্রতি আল্লাহর অনুগ্রহ স্মরণ কর যখন তিনি তোমাদেরকে ফেরাউনের সম্প্রদায়ের কবল থেকে মুক্তি দেন। তারা তোমাদেরকে অত্যন্ত নিকৃষ্ট ধরনের শাস্তি দিত, তোমাদের ছেলেদেরকে হত্যা করত এবং তোমাদের মেয়েদেরকে জীবিত রাখত। এবং এতে তোমাদের পালনকর্তার পক্ষ থেকে বিরাট পরীক্ষা হয়েছিল।'),
  ('bn.bengali', 14, 7, 'যখন তোমাদের পালনকর্তা ঘোষণা করলেন যে, যদি কৃতজ্ঞতা স্বীকার কর, তবে তোমাদেরকে আরও দেব এবং যদি অকৃতজ্ঞ হও তবে নিশ্চয়ই আমার শাস্তি হবে কঠোর।'),
  ('bn.bengali', 14, 8, 'এবং মূসা বললেনঃ তোমরা এবং পৃথিবীর সবাই যদি কুফরী কর, তথাপি আল্লাহ অমুখাপেক্ষী, যাবতীয় গুনের আধার।'),
  ('bn.bengali', 14, 9, 'তোমাদের কাছে কি তোমাদের পূর্ববর্তী কওমে নূহ, আদ ও সামুদের এবং তাদের পরবর্তীদের খবর পৌছেনি? তাদের বিষয়ে আল্লাহ ছাড়া আর কেউ জানে না। তাদের কাছে তাদের পয়গম্বর প্রমানাদি নিয়ে আগমন করেন। অতঃপর তারা নিজেদের হাত নিজেদের মুখে রেখে দিয়েছে এবং বলেছে, যা কিছু সহ তোমাদেরকে প্রেরণ করা হয়েছে, আমরা তা মানি না এবং যে পথের দিকে তোমরা আমাদেরকে দাওয়াত দাও, সে সম্পর্কে আমাদের মনে সন্দেহ আছে, যা আমাদেরকে উৎকন্ঠায় ফেলে রেখেছে।'),
  ('bn.bengali', 14, 10, 'তাদের পয়গম্বরগণ বলেছিলেনঃ আল্লাহ সম্পর্কে কি সন্দেহ আছে, যিনি নভোমন্ডল ও ভুমন্ডলের স্রষ্টা? তিনি তোমাদেরকে আহবান করেন যাতে তোমাদের কিছু গুনাহ ক্ষমা করেন এবং নির্দিষ্ট মেয়াদ পর্যন্ত তোমাদের সময় দেন। তারা বলতঃ তোমরা তো আমাদের মতই মানুষ! তোমরা আমাদেরকে ঐ উপাস্য থেকে বিরত রাখতে চাও, যার এবাদত আমাদের পিতৃপুরুষগণ করত। অতএব তোমরা কোন সুস্পষ্ট প্রমাণ আনয়ন কর।'),
  ('bn.bengali', 14, 11, 'তাদের পয়গম্বর তাদেরকে বলেনঃ আমারাও তোমাদের মত মানুষ, কিন্তু আল্লাহ বান্দাদের মধ্য থেকে যার উপরে ইচ্ছা, অনুগ্রহ করেন। আল্লাহর নির্দেশ ব্যতীত তোমাদের কাছে প্রমাণ নিয়ে আসা আমাদের কাজ নয়; ঈমানদারদের আল্লাহর উপর ভরসা করা চাই।'),
  ('bn.bengali', 14, 12, 'আমাদের আল্লাহর উপর ভরসা না করার কি কারণ থাকতে পারে, অথচ তিনি আমাদেরকে আমাদের পথ বলে দিয়েছেন। তোমরা আমাদেরকে যে পীড়ন করেছ, তজ্জন্যে আমরা সবর করব। ভরসাকারিগণের আল্লাহর উপরই ভরসা করা উচিত।'),
  ('bn.bengali', 14, 13, 'কাফেররা পয়গম্বরগণকে বলেছিলঃ আমরা তোমাদেরকে দেশ থেকে বের করে দেব অথবা তোমরা আমাদের ধর্মে ফিরে আসবে। তখন তাদের কাছে তাদের পালনকর্তা ওহী প্রেরণ করলেন যে, আমি জালিমদেরকে অবশ্যই ধ্বংস করে দেব।'),
  ('bn.bengali', 14, 14, 'তাদের পর তোমাদেরকে দেশে আবাদ করব। এটা ঐ ব্যক্তি পায়, যে আমার সামনে দন্ডায়মান হওয়াকে এবং আমার আযাবের ওয়াদাকে ভয় করে।'),
  ('bn.bengali', 14, 15, 'পয়গম্বরগণ ফয়সালা চাইতে লাগলেন এবং প্রত্যেক অবাধ্য, হঠকারী ব্যর্থ কাম হল।'),
  ('bn.bengali', 14, 16, 'তার পেছনে দোযখ রয়েছে। তাতে পূঁজ মিশানো পানি পান করানো হবে।'),
  ('bn.bengali', 14, 17, 'ঢোক গিলে তা পান করবে। এবং গলার ভিতরে প্রবেশ করতে পারবে না। প্রতি দিক থেকে তার কাছে মৃত্যু আগমন করবে এবং সে মরবে না। তার পশ্চাতেও রয়েছে কঠোর আযাব।'),
  ('bn.bengali', 14, 18, 'যারা স্বীয় পালনকর্তার সত্তার অবিশ্বাসী তাদের অবস্থা এই যে, তাদের কর্মসমূহ ছাইভস্মের মত যার উপর দিয়ে প্রবল বাতাস বয়ে যায় ধূলিঝড়ের দিন। তাদের উপার্জনের কোন অংশই তাদের করতলগত হবে না। এটাই দুরবর্তী পথভ্রষ্টতা।'),
  ('bn.bengali', 14, 19, 'তুমি কি দেখনি যে, আল্লাহ নভোমন্ডল ও ভুমন্ডল যথাবিধি সৃষ্টি করেছেন? যদি তিনি ইচ্ছা করেন, তবে তোমাদেরকে বিলুপ্তিতে নিয়ে যাবেন এবং নতুন সৃষ্টি আনয়ন করবেন।'),
  ('bn.bengali', 14, 20, 'এটা আল্লাহর পক্ষে মোটেই কঠিন নয়।'),
  ('bn.bengali', 14, 21, 'সবাই আল্লাহর সামনে দন্ডায়মান হবে এবং দুর্বলেরা বড়দেরকে বলবেঃ আমরা তো তোমাদের অনুসারী ছিলাম-অতএব, তোমরা আল্লাহর আযাব থেকে আমাদেরকে কিছুমাত্র রক্ষা করবে কি? তারা বলবেঃ যদি আল্লাহ আমাদেরকে সৎপথ দেখাতেন, তবে আমরা অবশ্যই তোমাদের কে সৎপথ দেখাতাম। এখন তো আমাদের ধৈর্য্যচ্যুত হই কিংবা সবর করি-সবই আমাদের জন্যে সমান আমাদের রেহাই নেই।'),
  ('bn.bengali', 14, 22, 'যখন সব কাজের ফায়সলা হয়ে যাবে, তখন শয়তান বলবেঃ নিশ্চয় আল্লাহ তোমাদেরকে সত্য ওয়াদা দিয়েছিলেন এবং আমি তোমাদের সাথে ওয়াদা করেছি, অতঃপর তা ভঙ্গ করেছি। তোমাদের উপর তো আমার কোন ক্ষমতা ছিল না, কিন্তু এতটুকু যে, আমি তোমাদেরকে ডেকেছি, অতঃপর তোমরা আমার কথা মেনে নিয়েছ। অতএব তোমরা আমাকে ভৎর্সনা করো না এবং নিজেদেরকেই ভৎর্সনা কর। আমি তোমাদের উদ্ধারে সাহায্যকারী নই। এবং তোমরাও আমার উদ্ধারে সাহায্যকারী নও। ইতোপূর্বে তোমরা আমাকে যে আল্লাহর শরীক করেছিলে, আমি তা অস্বীকার করি। নিশ্চয় যারা জালেম তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 14, 23, 'এবং যারা বিশ্বাস স্থাপণ করে এবং সৎকর্ম সম্পাদন করে তাদেরকে এমন উদ্যানে প্রবেশ করানো হবে, যার পাদদেশ দিয়ে নির্ঝরিনী সমূহ প্রবাহিত হবে তারা তাতে পালনকর্তার নির্দেশে অনন্তকাল থাকবে। যেখানে তাদের সম্ভাষণ হবে সালাম।'),
  ('bn.bengali', 14, 24, 'তুমি কি লক্ষ্য কর না, আল্লাহ তা’আলা কেমন উপমা বর্ণনা করেছেনঃ পবিত্র বাক্য হলো পবিত্র বৃক্ষের মত। তার শিকড় মজবুত এবং শাখা আকাশে উত্থিত।'),
  ('bn.bengali', 14, 25, 'সে পালনকর্তার নির্দেশে অহরহ ফল দান করে। আল্লাহ মানুষের জন্যে দৃষ্টান্ত বর্ণণা করেন-যাতে তারা চিন্তা-ভাবনা করে।'),
  ('bn.bengali', 14, 26, 'এবং নোংরা বাক্যের উদাহরণ হলো নোংরা বৃক্ষ। একে মাটির উপর থেকে উপড়ে নেয়া হয়েছে। এর কোন স্থিতি নেই।'),
  ('bn.bengali', 14, 27, 'আল্লাহ তা’আলা মুমিনদেরকে মজবুত বাক্য দ্বারা মজবুত করেন। পার্থিবজীবনে এবং পরকালে। এবং আল্লাহ জালেমদেরকে পথভ্রষ্ট করেন। আল্লাহ যা ইচ্ছা, তা করেন।'),
  ('bn.bengali', 14, 28, 'তুমি কি তাদের কে দেখনি, যারা আল্লাহর নেয়ামতকে কুফরে পরিণত করেছে এবং স্ব-জাতিকে সম্মুখীন করেছে ধ্বংসের আলয়ে।'),
  ('bn.bengali', 14, 29, 'দোযখের? তারা তাতে প্রবেশ করবে সেটা কতই না মন্দ আবাস।'),
  ('bn.bengali', 14, 30, 'এবং তারা আল্লাহর জন্যে সমকক্ষ স্থির করেছে, যাতে তারা তার পথ থেকে বিচ্যুত করে দেয়। বলুনঃ মজা উপভোগ করে নাও। অতঃপর তোমাদেরকে অগ্নির দিকেই ফিরে যেতে হবে।'),
  ('bn.bengali', 14, 31, 'আমার বান্দাদেরকে বলে দিন যারা বিশ্বাস স্থাপন করেছে, তারা নামায কায়েম রাখুক এবং আমার দেয়া রিযিক থেকে গোপনে ও প্রকাশ্যে ব্যয় করুক ঐদিন আসার আগে, যেদিন কোন বেচা কেনা নেই এবং বন্ধুত্বও নেই।'),
  ('bn.bengali', 14, 32, 'তিনিই আল্লাহ, যিনি নভোমন্ডল ও ভুমন্ডল সৃজন করেছেন এবং আকাশ থেকে পানি বর্ষণ করে অতঃপর তা দ্বারা তোমাদের জন্যে ফলের রিযিক উৎপন্ন করেছেন এবং নৌকাকে তোমাদের আজ্ঞাবহ করেছেন, যাতে তাঁর আদেশে সমুদ্রে চলা ফেরা করে এবং নদ-নদীকে তোমাদের সেবায় নিয়োজিত করেছেন।'),
  ('bn.bengali', 14, 33, 'এবং তোমাদের সেবায় নিয়োজিত করেছেন সূর্যকে এবং চন্দ্রকে সর্বদা এক নিয়মে এবং রাত্রি ও দিবাকে তোমাদের কাজে লাগিয়েছেন।'),
  ('bn.bengali', 14, 34, 'যে সকল বস্তু তোমরা চেয়েছ, তার প্রত্যেকটি থেকেই তিনি তোমাদেরকে দিয়েছেন। যদি আল্লাহর নেয়ামত গণনা কর, তবে গুণে শেষ করতে পারবে না। নিশ্চয় মানুষ অত্যন্ত অন্যায়কারী, অকৃতজ্ঞ।'),
  ('bn.bengali', 14, 35, 'যখন ইব্রাহীম বললেনঃ হে পালনকর্তা, এ শহরকে শান্তিময় করে দিন এবং আমাকে ও আমার সন্তান সন্ততিকে মূর্তি পূজা থেকে দূরে রাখুন।'),
  ('bn.bengali', 14, 36, 'হে পালনকর্তা, এরা অনেক মানুষকে বিপথগামী করেছে। অতএব যে আমার অনুসরণ করে, সে আমার এবং কেউ আমার অবাধ্যতা করলে নিশ্চয় আপনি ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 14, 37, 'হে আমাদের পালনকর্তা, আমি নিজের এক সন্তানকে তোমার পবিত্র গৃহের সন্নিকটে চাষাবাদহীন উপত্যকায় আবাদ করেছি; হে আমাদের পালনকর্তা, যাতে তারা নামায কায়েম রাখে। অতঃপর আপনি কিছু লোকের অন্তরকে তাদের প্রতি আকৃষ্ট করুন এবং তাদেরকে ফলাদি দ্বারা রুযী দান করুন, সম্ভবতঃ তারা কৃতজ্ঞতা প্রকাশ করবে'),
  ('bn.bengali', 14, 38, 'হে আমাদের পালনকর্তা, আপনি তো জানেন আমরা যা কিছু গোপনে করি এবং যা কিছু প্রকাশ্য করি। আল্লাহর কাছে পৃথিবীতে ও আকাশে কোন কিছুই গোপন নয়।'),
  ('bn.bengali', 14, 39, 'সমস্ত প্রশংসা আল্লাহরই, যিনি আমাকে এই বার্ধক্যে ইসমাঈল ও ইসহাক দান করেছেন নিশ্চয় আমার পালনকর্তা দোয়া শ্রবণ করেন।'),
  ('bn.bengali', 14, 40, 'হে আমার পালনকর্তা, আমাকে নামায কায়েমকারী করুন এবং আমার সন্তানদের মধ্যে থেকেও। হে আমাদের পালনকর্তা, এবং কবুল করুন আমাদের দোয়া।'),
  ('bn.bengali', 14, 41, 'হে আমাদের পালনকর্তা, আমাকে, আমার পিতা-মাতাকে এবং সব মুমিনকে ক্ষমা করুন, যেদিন হিসাব কায়েম হবে।'),
  ('bn.bengali', 14, 42, 'জালেমরা যা করে, সে সম্পর্কে আল্লাহকে কখনও বেখবর মনে করো না তাদেরকে তো ঐ দিন পর্যন্ত অবকাশ দিয়ে রেখেছেন, যেদিন চক্ষুসমূহ বিস্ফোরিত হবে।'),
  ('bn.bengali', 14, 43, 'তারা মস্তক উপরে তুলে ভীত-বিহবল চিত্তে দৌড়াতে থাকবে। তাদের দিকে তাদের দৃষ্টি ফিরে আসবে না এবং তাদের অন্তর উড়ে যাবে।'),
  ('bn.bengali', 14, 44, 'মানুষকে ঐ দিনের ভয় প্রদর্শন করুন, যেদিন তাদের কাছে আযাব আসবে। তখন জালেমরা বলবেঃ হে আমাদের পালনকর্তা, আমাদেরকে সামান্য মেয়াদ পর্যন্ত সময় দিন, যাতে আমরা আপনার আহবানে সাড়া দিতে এবং পয়গম্বরগণের অনুসরণ করতে পারি। তোমরা কি ইতোপূর্বে কসম খেতে না যে, তোমাদেরকে দুনিয়া থেকে যেতে হবে না?'),
  ('bn.bengali', 14, 45, 'তোমরা তাদের বাসভূমিতেই বসবাস করতে, যারা নিজেদের উপর জুলুম করেছে এবং তোমাদের জানা হয়ে গিয়েছিল যে, আমি তাদের সাথে কিরূপ ব্যবহার করেছি এবং আমি তোমাদেরকে ওদের সব কাহিনীই বর্ণনা করেছি।'),
  ('bn.bengali', 14, 46, 'তারা নিজেদের মধ্যে ভীষণ চক্রান্ত করে নিয়েছে এবং আল্লাহর সামনে রক্ষিত আছে তাদের কু-চক্রান্ত। তাদের কুটকৌশল পাহাড় টলিয়ে দেয়ার মত হবে না।'),
  ('bn.bengali', 14, 47, 'অতএব আল্লাহর প্রতি ধারণা করো না যে, তিনি রসূলগণের সাথে কৃত ওয়াদা ভঙ্গ করবেন নিশ্চয় আল্লাহ পরাক্রমশালী, প্রতিশোধ গ্রহণকারী।'),
  ('bn.bengali', 14, 48, 'যেদিন পরিবর্তিত করা হবে এ পৃথিবীকে অন্য পৃথিবীতে এবং পরিবর্তিত করা হবে আকাশ সমূহকে এবং লোকেরা পরাক্রমশালী এবং আল্লাহর সামনে পেশ হবে।'),
  ('bn.bengali', 14, 49, 'তুমি ঐদিন পাপীদেরকে পরস্পরে শৃংখলা বদ্ধ দেখবে।'),
  ('bn.bengali', 14, 50, 'তাদের জামা হবে দাহ্য আলকাতরার এবং তাদের মুখমন্ডলকে আগুন আচ্ছন্ন করে ফেলবে।'),
  ('bn.bengali', 14, 51, 'যাতে আল্লাহ প্রত্যেককে তার কৃতকর্মের প্রতিদান দেন। নিশ্চয় আল্লাহ দ্রুত হিসাব গ্রহণকারী।'),
  ('bn.bengali', 14, 52, 'এটা মানুষের একটি সংবাদনামা এবং যাতে এতদ্বারা ভীত হয় এবং যাতে জেনে নেয় যে, উপাস্য তিনিই-একক; এবং যাতে বুদ্ধিমানরা চিন্তা-ভাবনা করে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 14, 1, 'Alif. Lam. Ra. (This is) a Scripture which We have revealed unto thee (Muhammad) that thereby thou mayst bring forth mankind from darkness unto light, by the permission of their Lord, unto the path of the Mighty, the Owner of Praise,'),
  ('en.pickthall', 14, 2, 'Allah, unto Whom belongeth whatsoever is in the heavens and whatsoever is in the earth. and woe unto the disbelievers from an awful doom;'),
  ('en.pickthall', 14, 3, 'Those who love the life of the world more than the Hereafter, and debar (men) from the way of Allah and would have it crooked: such are far astray.'),
  ('en.pickthall', 14, 4, 'And We never sent a messenger save with the language of his folk, that he might make (the message) clear for them. Then Allah sendeth whom He will astray, and guideth whom He will. He is the Mighty, the Wise.'),
  ('en.pickthall', 14, 5, 'We verily sent Moses with Our revelations, saying: Bring thy people forth from darkness unto light. And remind them of the days of Allah. Lo! therein are revelations for each steadfast, thankful (heart).'),
  ('en.pickthall', 14, 6, 'And (remind them) how Moses said unto his people: Remember Allah\'s favour unto you when He delivered you from Pharaoh\'s folk who were afflicting you with dreadful torment, and were slaying your sons and sparing your women; that was a tremendous trial from your Lord.'),
  ('en.pickthall', 14, 7, 'And when your Lord proclaimed: If ye give thanks, I will give you more; but if ye are thankless, lo! My punishment is dire.'),
  ('en.pickthall', 14, 8, 'And Moses said: Though ye and all who are in the earth prove thankless, lo! Allah verily is Absolute, Owner of Praise.'),
  ('en.pickthall', 14, 9, 'Hath not the history of those before you reached you: the folk of Noah, and (the tribes of) A\'ad and Thamud, and those after them? None save Allah knoweth them. Their messengers came unto them with clear proofs, but they thrust their hands into their mouths, and said: Lo! we disbelieve in that wherewith ye have been sent, and lo! we are in grave doubt concerning that to which ye call us.'),
  ('en.pickthall', 14, 10, 'Their messengers said: Can there be doubt concerning Allah, the Creator of the heavens and the earth? He calleth you that He may forgive you your sins and reprieve you unto an appointed term. They said: Ye are but mortals like us, who would fain turn us away from what our fathers used to worship. Then bring some clear warrant.'),
  ('en.pickthall', 14, 11, 'Their messengers said unto them: We are but mortals like you, but Allah giveth grace unto whom He will of His slaves. It is not ours to bring you a warrant unless by the permission of Allah. In Allah let believers put their trust!'),
  ('en.pickthall', 14, 12, 'How should we not put our trust in Allah when He hath shown us our ways? We surely will endure the hurt ye do us. In Allah let the trusting put their trust.'),
  ('en.pickthall', 14, 13, 'And those who disbelieved said unto their messengers: Verily we will drive you out from our land, unless ye return to our religion. Then their Lord inspired them, (saying): Verily we shall destroy the wrong-doers,'),
  ('en.pickthall', 14, 14, 'And verily We shall make you to dwell in the land after them. This is for him who feareth My Majesty and feareth My threats.'),
  ('en.pickthall', 14, 15, 'And they sought help (from their Lord) and every froward potentate was bought to naught;'),
  ('en.pickthall', 14, 16, 'Hell is before him, and he is made to drink a festering water,'),
  ('en.pickthall', 14, 17, 'Which he sippeth but can hardly swallow, and death cometh unto him from every side while yet he cannot die, and before him is a harsh doom.'),
  ('en.pickthall', 14, 18, 'A similitude of those who disbelieve in their Lord: Their works are as ashes which the wind bloweth hard upon a stormy day. They have no control of aught that they have earned. That is the extreme failure.'),
  ('en.pickthall', 14, 19, 'Hast thou not seen that Allah hath created the heavens and the earth with truth? If He will, He can remove you and bring (in) some new creation;'),
  ('en.pickthall', 14, 20, 'And that is no great matter for Allah.'),
  ('en.pickthall', 14, 21, 'They all come forth unto their Lord. Then those who were despised say unto those who were scornful: We were unto you a following, can ye then avert from us aught of Allah\'s doom? They say: Had Allah guided us, we should have guided you. Whether we rage or patiently endure is (now) all one for us; we have no place of refuge.'),
  ('en.pickthall', 14, 22, 'And Satan saith, when the matter hath been decided: Lo! Allah promised you a promise of truth; and I promised you, then failed you. And I had no power over you save that I called unto you and ye obeyed me. So blame not, but blame yourselves. I cannot help you, nor can ye help me, Lo! I disbelieved in that which ye before ascribed to me. Lo! for wrong-doers is a painful doom.'),
  ('en.pickthall', 14, 23, 'And those who believed and did good works are made to enter Gardens underneath which rivers flow, therein abiding by permission of their Lord, their greeting therein: Peace!'),
  ('en.pickthall', 14, 24, 'Seest thou not how Allah coineth a similitude: A goodly saying, as a goodly tree, its root set firm, its branches reaching into heaven,'),
  ('en.pickthall', 14, 25, 'Giving its fruit at every season by permission of its Lord? Allah coineth the similitudes for mankind in order that they may reflect.'),
  ('en.pickthall', 14, 26, 'And the similitude of a bad saying is as a bad tree, uprooted from upon the earth, possessing no stability.'),
  ('en.pickthall', 14, 27, 'Allah confirmeth those who believe by a firm saying in the life of the world and in the Hereafter, and Allah sendeth wrong-doers astray. And Allah doeth what He will.'),
  ('en.pickthall', 14, 28, 'Hast thou not seen those who gave the grace of Allah in exchange for thanklessness and led their people down to the Abode of Loss,'),
  ('en.pickthall', 14, 29, '(Even to) hell? They are exposed thereto. A hapless end!'),
  ('en.pickthall', 14, 30, 'And they set up rivals to Allah that they may mislead (men) from His way. Say: Enjoy life (while ye may) for lo! your journey\'s end will be the Fire.'),
  ('en.pickthall', 14, 31, 'Tell My bondmen who believe to establish worship and spend of that which We have given them, secretly and publicly, before a day cometh wherein there will be neither traffick nor befriending.'),
  ('en.pickthall', 14, 32, 'Allah is He Who created the heavens and the earth, and causeth water to descend from the sky, thereby producing fruits as food for you, and maketh the ships to be of service unto you, that they may run upon the sea at His command, and hath made of service unto you the rivers;'),
  ('en.pickthall', 14, 33, 'And maketh the sun and the moon, constant in their courses, to be of service unto you, and hath made of service unto you the night and the day.'),
  ('en.pickthall', 14, 34, 'And He giveth you of all ye ask of Him, and if ye would count the bounty of Allah ye cannot reckon it. Lo! man is verily a wrong-doer, an ingrate.'),
  ('en.pickthall', 14, 35, 'And when Abraham said: My Lord! Make safe this territory, and preserve me and my sons from serving idols.'),
  ('en.pickthall', 14, 36, 'My Lord! Lo! they have led many of mankind astray. But whoso followeth me, he verily is of me. And whoso disobeyeth me - Still Thou art Forgiving, Merciful.'),
  ('en.pickthall', 14, 37, 'Our Lord! Lo! I have settled some of my posterity in an uncultivable valley near unto Thy holy House, our Lord! that they may establish proper worship; so incline some hearts of men that they may yearn toward them, and provide Thou them with fruits in order that they may be thankful.'),
  ('en.pickthall', 14, 38, 'Our Lord! Lo! Thou knowest that which we hide and that which we proclaim. Nothing in the earth or in the heaven is hidden from Allah.'),
  ('en.pickthall', 14, 39, 'Praise be to Allah Who hath given me, in my old age, Ishmael and Isaac! Lo! my Lord is indeed the Hearer of Prayer.'),
  ('en.pickthall', 14, 40, 'My Lord! Make me to establish proper worship, and some of my posterity (also); our Lord! and accept my prayer.'),
  ('en.pickthall', 14, 41, 'Our Lord! Forgive me and my parents and believers on the day when the account is cast.'),
  ('en.pickthall', 14, 42, 'Deem not that Allah is unaware of what the wicked do. He but giveth them a respite till a day when eyes will stare (in terror),'),
  ('en.pickthall', 14, 43, 'As they come hurrying on in fear, their heads upraised, their gaze returning not to them, and their hearts as air.'),
  ('en.pickthall', 14, 44, 'And warn mankind of a day when the doom will come upon them, and those who did wrong will say: Our Lord! Reprieve us for a little while. We will obey Thy call and will follow the messengers. (It will be answered): Did ye not swear before that there would be no end for you?'),
  ('en.pickthall', 14, 45, 'And (have ye not) dwelt in the dwellings of those who wronged themselves (of old) and (hath it not) become plain to you how We dealt with them and made examples for you?'),
  ('en.pickthall', 14, 46, 'Verily they have plotted their plot, and their plot is with Allah, though their plot were one whereby the mountains should be moved.'),
  ('en.pickthall', 14, 47, 'So think not that Allah will fail to keep His promise to His messengers. Lo! Allah is Mighty, Able to Requite (the wrong).'),
  ('en.pickthall', 14, 48, 'On the day when the earth will be changed to other than the earth, and the heavens (also will be changed) and they will come forth unto Allah, the One, the Almighty,'),
  ('en.pickthall', 14, 49, 'Thou wilt see the guilty on that day linked together in chains,'),
  ('en.pickthall', 14, 50, 'Their raiment of pitch, and the Fire covering their faces,'),
  ('en.pickthall', 14, 51, 'That Allah may repay each soul what it hath earned. Lo! Allah is swift at reckoning.'),
  ('en.pickthall', 14, 52, 'This is a clear message for mankind in order that they may be warned thereby, and that they may know that He is only One Allah, and that men of understanding may take heed.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 14, 1, 'A. L. R. A Book which We have revealed unto thee, in order that thou mightest lead mankind out of the depths of darkness into light - by the leave of their Lord - to the Way of (Him) the Exalted in power, worthy of all praise!-'),
  ('en.yusufali', 14, 2, 'Of Allah, to Whom do belong all things in the heavens and on earth! But alas for the Unbelievers for a terrible penalty (their Unfaith will bring them)!-'),
  ('en.yusufali', 14, 3, 'Those who love the life of this world more than the Hereafter, who hinder (men) from the Path of Allah and seek therein something crooked: they are astray by a long distance.'),
  ('en.yusufali', 14, 4, 'We sent not a messenger except (to teach) in the language of his (own) people, in order to make (things) clear to them. Now Allah leaves straying those whom He pleases and guides whom He pleases: and He is Exalted in power, full of Wisdom.'),
  ('en.yusufali', 14, 5, 'We sent Moses with Our signs (and the command). "Bring out thy people from the depths of darkness into light, and teach them to remember the Days of Allah." Verily in this there are Signs for such as are firmly patient and constant,- grateful and appreciative.'),
  ('en.yusufali', 14, 6, 'Remember! Moses said to his people: "Call to mind the favour of Allah to you when He delivered you from the people of Pharaoh: they set you hard tasks and punishments, slaughtered your sons, and let your women-folk live: therein was a tremendous trial from your Lord."'),
  ('en.yusufali', 14, 7, 'And remember! your Lord caused to be declared (publicly): "If ye are grateful, I will add more (favours) unto you; But if ye show ingratitude, truly My punishment is terrible indeed."'),
  ('en.yusufali', 14, 8, 'And Moses said: "If ye show ingratitude, ye and all on earth together, yet is Allah free of all wants, worthy of all praise.'),
  ('en.yusufali', 14, 9, 'Has not the story reached you, (O people!), of those who (went) before you? - of the people of Noah, and \'Ad, and Thamud? - And of those who (came) after them? None knows them but Allah. To them came messengers with Clear (Signs); but they put their hands up to their mouths, and said: "We do deny (the mission) on which ye have been sent, and we are really in suspicious (disquieting) doubt as to that to which ye invite us."'),
  ('en.yusufali', 14, 10, 'Their messengers said: "Is there a doubt about Allah, The Creator of the heavens and the earth? It is He Who invites you, in order that He may forgive you your sins and give you respite for a term appointed!" They said: "Ah! ye are no more than human, like ourselves! Ye wish to turn us away from the (gods) our fathers used to worship: then bring us some clear authority."'),
  ('en.yusufali', 14, 11, 'Their messengers said to them: "True, we are human like yourselves, but Allah doth grant His grace to such of his servants as He pleases. It is not for us to bring you an authority except as Allah permits. And on Allah let all men of faith put their trust.'),
  ('en.yusufali', 14, 12, '"No reason have we why we should not put our trust on Allah. Indeed He Has guided us to the Ways we (follow). We shall certainly bear with patience all the hurt you may cause us. For those who put their trust should put their trust on Allah."'),
  ('en.yusufali', 14, 13, 'And the Unbelievers said to their messengers: "Be sure we shall drive you out of our land, or ye shall return to our religion." But their Lord inspired (this Message) to them: "Verily We shall cause the wrong-doers to perish!'),
  ('en.yusufali', 14, 14, '"And verily We shall cause you to abide in the land, and succeed them. This for such as fear the Time when they shall stand before My tribunal,- such as fear the punishment denounced."'),
  ('en.yusufali', 14, 15, 'But they sought victory and decision (there and then), and frustration was the lot of every powerful obstinate transgressor.'),
  ('en.yusufali', 14, 16, 'In front of such a one is Hell, and he is given, for drink, boiling fetid water.'),
  ('en.yusufali', 14, 17, 'In gulps will he sip it, but never will he be near swallowing it down his throat: death will come to him from every quarter, yet will he not die: and in front of him will be a chastisement unrelenting.'),
  ('en.yusufali', 14, 18, 'The parable of those who reject their Lord is that their works are as ashes, on which the wind blows furiously on a tempestuous day: No power have they over aught that they have earned: that is the straying far, far (from the goal).'),
  ('en.yusufali', 14, 19, 'Seest thou not that Allah created the heavens and the earth in Truth? If He so will, He can remove you and put (in your place) a new creation?'),
  ('en.yusufali', 14, 20, 'Nor is that for Allah any great matter.'),
  ('en.yusufali', 14, 21, 'They will all be marshalled before Allah together: then will the weak say to those who were arrogant, "For us, we but followed you; can ye then avail us to all against the wrath of Allah?" They will reply, "If we had received the Guidance of Allah, we should have given it to you: to us it makes no difference (now) whether we rage, or bear (these torments) with patience: for ourselves there is no way of escape."'),
  ('en.yusufali', 14, 22, 'And Satan will say when the matter is decided: "It was Allah Who gave you a promise of Truth: I too promised, but I failed in my promise to you. I had no authority over you except to call you but ye listened to me: then reproach not me, but reproach your own souls. I cannot listen to your cries, nor can ye listen to mine. I reject your former act in associating me with Allah. For wrong-doers there must be a grievous penalty."'),
  ('en.yusufali', 14, 23, 'But those who believe and work righteousness will be admitted to gardens beneath which rivers flow,- to dwell therein for aye with the leave of their Lord. Their greeting therein will be: "Peace!"'),
  ('en.yusufali', 14, 24, 'Seest thou not how Allah sets forth a parable? - A goodly word like a goodly tree, whose root is firmly fixed, and its branches (reach) to the heavens,- of its Lord. So Allah sets forth parables for men, in order that they may receive admonition.'),
  ('en.yusufali', 14, 25, 'It brings forth its fruit at all times, by the leave of its Lord. So Allah sets forth parables for men, in order that they may receive admonition.'),
  ('en.yusufali', 14, 26, 'And the parable of an evil Word is that of an evil tree: It is torn up by the root from the surface of the earth: it has no stability.'),
  ('en.yusufali', 14, 27, 'Allah will establish in strength those who believe, with the word that stands firm, in this world and in the Hereafter; but Allah will leave, to stray, those who do wrong: Allah doeth what He willeth.'),
  ('en.yusufali', 14, 28, 'Hast thou not turned thy vision to those who have changed the favour of Allah. Into blasphemy and caused their people to descend to the House of Perdition?-'),
  ('en.yusufali', 14, 29, 'Into Hell? They will burn therein,- an evil place to stay in!'),
  ('en.yusufali', 14, 30, 'And they set up (idols) as equal to Allah, to mislead (men) from the Path! Say: "Enjoy (your brief power)! But verily ye are making straightway for Hell!"'),
  ('en.yusufali', 14, 31, 'Speak to my servants who have believed, that they may establish regular prayers, and spend (in charity) out of the sustenance we have given them, secretly and openly, before the coming of a Day in which there will be neither mutual bargaining nor befriending.'),
  ('en.yusufali', 14, 32, 'It is Allah Who hath created the heavens and the earth and sendeth down rain from the skies, and with it bringeth out fruits wherewith to feed you; it is He Who hath made the ships subject to you, that they may sail through the sea by His command; and the rivers (also) hath He made subject to you.'),
  ('en.yusufali', 14, 33, 'And He hath made subject to you the sun and the moon, both diligently pursuing their courses; and the night and the day hath he (also) made subject to you.'),
  ('en.yusufali', 14, 34, 'And He giveth you of all that ye ask for. But if ye count the favours of Allah, never will ye be able to number them. Verily, man is given up to injustice and ingratitude.'),
  ('en.yusufali', 14, 35, 'Remember Abraham said: "O my Lord! make this city one of peace and security: and preserve me and my sons from worshipping idols.'),
  ('en.yusufali', 14, 36, '"O my Lord! they have indeed led astray many among mankind; He then who follows my (ways) is of me, and he that disobeys me,- but Thou art indeed Oft-forgiving, Most Merciful.'),
  ('en.yusufali', 14, 37, '"O our Lord! I have made some of my offspring to dwell in a valley without cultivation, by Thy Sacred House; in order, O our Lord, that they may establish regular Prayer: so fill the hearts of some among men with love towards them, and feed them with fruits: so that they may give thanks.'),
  ('en.yusufali', 14, 38, '"O our Lord! truly Thou dost know what we conceal and what we reveal: for nothing whatever is hidden from Allah, whether on earth or in heaven.'),
  ('en.yusufali', 14, 39, '"Praise be to Allah, Who hath granted unto me in old age Isma\'il and Isaac: for truly my Lord is He, the Hearer of Prayer!'),
  ('en.yusufali', 14, 40, 'O my Lord! make me one who establishes regular Prayer, and also (raise such) among my offspring O our Lord! and accept Thou my Prayer.'),
  ('en.yusufali', 14, 41, '"O our Lord! cover (us) with Thy Forgiveness - me, my parents, and (all) Believers, on the Day that the Reckoning will be established!'),
  ('en.yusufali', 14, 42, 'Think not that Allah doth not heed the deeds of those who do wrong. He but giveth them respite against a Day when the eyes will fixedly stare in horror,-'),
  ('en.yusufali', 14, 43, 'They running forward with necks outstretched, their heads uplifted, their gaze returning not towards them, and their hearts a (gaping) void!'),
  ('en.yusufali', 14, 44, 'So warn mankind of the Day when the Wrath will reach them: then will the wrong-doers say: "Our Lord! respite us (if only) for a short term: we will answer Thy call, and follow the messengers!" "What! were ye not wont to swear aforetime that ye should suffer no decline?'),
  ('en.yusufali', 14, 45, '"And ye dwelt in the dwellings of men who wronged their own souls; ye were clearly shown how We dealt with them; and We put forth (many) parables in your behoof!"'),
  ('en.yusufali', 14, 46, 'Mighty indeed were the plots which they made, but their plots were (well) within the sight of Allah, even though they were such as to shake the hills!'),
  ('en.yusufali', 14, 47, 'Never think that Allah would fail his messengers in His promise: for Allah is Exalted in power, - the Lord of Retribution.'),
  ('en.yusufali', 14, 48, 'One day the earth will be changed to a different earth, and so will be the heavens, and (men) will be marshalled forth, before Allah, the One, the Irresistible;'),
  ('en.yusufali', 14, 49, 'And thou wilt see the sinners that day bound together in fetters;-'),
  ('en.yusufali', 14, 50, 'Their garments of liquid pitch, and their faces covered with Fire;'),
  ('en.yusufali', 14, 51, 'That Allah may requite each soul according to its deserts; and verily Allah is swift in calling to account.'),
  ('en.yusufali', 14, 52, 'Here is a Message for mankind: Let them take warning therefrom, and let them know that He is (no other than) One Allah: let men of understanding take heed.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 14, 1, 'Alif-Laaam-Raa; Kitaabun anzalnaahu ilaika litukhrijan-naasa minaz zulumaati ilan noori bi-izni Rabbihim ilaa siraatil \'Azeezil Hameed'),
  ('en.transliteration', 14, 2, 'Allaahil lazee lahoo maa fis samaawaati wa maa fill ard; wa wailul lilkaafireena min \'azaabin shadeed'),
  ('en.transliteration', 14, 3, 'Allazeena yastahibboo nal hayaatad dunyaa \'alal aakhirati wa yasuddoona \'ansabeelil laahi wa yabghoonahaa \'iwajaa; ulaaa \'ika fee dalaalim ba\'eed'),
  ('en.transliteration', 14, 4, 'Wa maaa arsalnaa mir Rasoolin illaa bilisaani qawmihee liyubaiyina lahum faiudillul laahu mai yashaaa\'u wa yahde mai yashaaa\'; wa Huwal \'Azeezul Hakeem'),
  ('en.transliteration', 14, 5, 'Wa laqad arsalnaa Moosaa bi Aayaatinaa an akhrij qawmaka minaz zulumaati ilan noori wa zak kirhum bi ayyaamil laah; inna fee zaalika la aayaatil likulli sabbaarin shakoor'),
  ('en.transliteration', 14, 6, 'Wa iz qaala Moosaa liqawmihiz kuroo ni\'matal laahi \'alaikum iz anjaakum min Aali Fir\'awna yasoomoo nakum sooo\'al \'azaabi wa yuzabbihoona abnaaa\'akum wa yastahyoona nisaaa\'akum; wa fee zaalikum balaaa\'um mir Rabbikum \'azeem'),
  ('en.transliteration', 14, 7, 'Wa iz ta azzana Rabbukum la\'in shakartum la azeedannakum wa la\'in kafartum inn\'azaabee lashadeed'),
  ('en.transliteration', 14, 8, 'Wa qaala Moosaaa in takfurooo antum wa man fil ardi jamee\'an fa innal laaha la Ghaniyyun Hameed'),
  ('en.transliteration', 14, 9, 'Alam yaatikum naba\'ul lazeena min qablikum qawmi Noohinw wa \'Aadinw wa Samood, wallazeena mim ba\'dihim; laa ya\'lamuhum illallaah; jaaa\'at hum Rusuluhum bilbaiyinaati faraddooo aydiyahum feee afwaahihim wa qaalooo innaa kafarnaa bimaaa ursiltum bihee wa innaa lafee shakkim mimmaa tad\'oonanaaa ilaihi mureeb'),
  ('en.transliteration', 14, 10, 'Qaalat Rusuluhum afillaahi shakkun faatiris samaawaati wal ardi yad\'ookum liyaghfira lakum min zunoobikum wa yu\'akhkhirakum ilaaa ajalim musam maa; qaaloo in antum illaa basharum mislunaa tureedoona an tasuddoonaa \'ammaa kaana ya\'budu aabaaa\'unaa faatoonaa bisul taanim mubeen'),
  ('en.transliteration', 14, 11, 'Qaalat lahum Rusuluhum in nahnu illaa basharum mislukum wa laakinnal laaha yamunnu \'alaa mai yashaaa\'u min \'ibaadihee wa maa kaana lanaaa an naatiyakum bisul taanin illaa bi iznil laah; wa \'alal laahi falyatawakkalil mu\'minonn'),
  ('en.transliteration', 14, 12, 'Wa maa lanaa allaa natawakkala \'alal laahi wa qad hadaanaa subulanaa; wa lanasbiranna \'alaa maaa aazaitumoonaa; wa \'alal laahi falyatawakkalil mutawakkiloon'),
  ('en.transliteration', 14, 13, 'Wa qaalal lazeena kafaroo li Rusulihim lanukhrijanna kum min aardinaaa aw lata\'oo dunna fee millatinaa fa awhaaa ilaihim Rabbuhum lanuhlikannaz zalimeen'),
  ('en.transliteration', 14, 14, 'Wa lanuskinan nakumul arda mim ba\'dihim; zaalika liman khaafa maqaamee wa khaafa wa\'eed'),
  ('en.transliteration', 14, 15, 'Wastaftahoo wa khaaba kullu jabbaarin \'aneed'),
  ('en.transliteration', 14, 16, 'Minw waraaa\'ihee jahannamu wa yusqaa mim maaa\'in sadeed'),
  ('en.transliteration', 14, 17, 'Yatajarra\'uhoo wa laa yakaadu yuseeghuhoo wa yaateehil mawtu min kulli makaaninw wa maa huwa bimaiyitinw wa minw waraaa\'ihee \'azaabun ghaleez'),
  ('en.transliteration', 14, 18, 'Masalul lazeena kafaroo bi Rabbihim a\'maaluhum karamaadinish taddat bihir reehu fee yawmin \'aasif; laa yaqdiroona mimmaa kasaboo \'alaa shai\'; zaalika huwad dalaalul ba\'eed'),
  ('en.transliteration', 14, 19, 'Alam tara annal laaha khalaqas samaawaati wal arda bilhaqq; iny yashaa yuzhibkum wa yaati bikhalqin jadeed'),
  ('en.transliteration', 14, 20, 'Wa maa zaalika \'alal laahi bi \'azeez'),
  ('en.transliteration', 14, 21, 'Wa barazoo lillaahi jamee\'an faqaalad du\'afaaa\'u lillazeenas takbarooo innaa kunnaa lakum taba\'an fahal antum mughnoona \'annaa min \'azaabil laahi min shai\'; qaaloo law hadaanal laahu lahadai naakum sawaaa\'un \'alainaaa ajazi\'naa am sabarnaa maa lanaa mim mahees'),
  ('en.transliteration', 14, 22, 'Wa qaalash Shaitaanu lammaa qudiyal amru innal laaha wa\'adakum wa\'dal haqqi wa wa\'attukum faakhlaftukum wa maa kaana liya \'alaikum min sultaanin illaaa an da\'awtukum fastajabtum lee falaa taloomoonee wa loomooo anfusakum maaa ana bimusrikhikum wa maaa antum bimusrikhiyya innee kafartu bimaaa ashraktumooni min qabl; innaz zaalimeena lahum azaabun aleem'),
  ('en.transliteration', 14, 23, 'Wa udkhilal lazeena aamanoo wa \'amilus saalihaati Jannaatin tajree min tahtihal anhaaru khaalideena feehaa bi izni Rabbihim tahiyyatuhum feeha salaam'),
  ('en.transliteration', 14, 24, 'Alam tara kaifa darabal laahu masalan kalimatan taiyibatan kashajaratin taiyibatin asluhaa saabitunw wa far\'uhaa fis samaaa\''),
  ('en.transliteration', 14, 25, 'Tu\'teee ukulahaa kulla heenim bi izni Rabbihaa; wa yadribul laahul amsaala linnaasi la\'allahum yatazak karoon'),
  ('en.transliteration', 14, 26, 'Wa masalu kalimatin khabeesatin kashajaratin khabee satinij tussat min fawqil ardi maa lahaa min qaraar'),
  ('en.transliteration', 14, 27, 'Yusabbitul laahul lazeena aamanoo bilqawlis saabiti fil hayaatid dunyaa wa fil Aakhirati wa yudillul laahuz zaalimeen; wa yaf\'alul laahu maa yashaaa\''),
  ('en.transliteration', 14, 28, 'Alam tara ilal lazeena baddaloo ni\'matal laahi kufranw wa ahalloo qawmahum daaral bawaar'),
  ('en.transliteration', 14, 29, 'Jahannama yaslawnahaa wa bi\'sal qaraar'),
  ('en.transliteration', 14, 30, 'Wa ja\'aloo lillaahi andaadal liyudilloo \'an sabeelih; qul tamatta\'oo fa innaa maseerakum ilan Naar'),
  ('en.transliteration', 14, 31, 'Qul li\'ibaadiyal lazeena aamanoo yuqeemus Salaata wa yunfiqoo mimmaa razaqnaahum sirranw wa \'alaaniyatam min qabli any yaatiya Yawmul laa bai\'un feehi wa laa khilaal'),
  ('en.transliteration', 14, 32, 'Allaahul lazee khalaqas samaawaati wal arda wa anzala minas samaaa\'i maaa\'an faakhraja bihee minas samaraati rizqal lakum wa sakhkhara lakumul fulka litajriya fil bahri bi amrihee wa sakhkhara lakumul anhaar'),
  ('en.transliteration', 14, 33, 'Wa sakhkhara lakumush shamsa walqamara daaa\'ibaini wa sakhkhara lakumul laila wannahaar'),
  ('en.transliteration', 14, 34, 'Wa aataakum min kulli maa sa altumooh; wa in ta\'uddoo ni\'matal laahi laa tuhsoohaa; innal insaana lazaloo mun kaffaar'),
  ('en.transliteration', 14, 35, 'Wa iz qaala Ibraaheemu Rabbij \'al haazal balada aaminanw wajnubnee wa baniyya an na\'budal asnaam'),
  ('en.transliteration', 14, 36, 'Rabbi innahunna adlalna kaseeram minan naasi faman tabi\'anee fa innahoo minnee wa man \'asaanee fa innaka Ghafoorur Raheem'),
  ('en.transliteration', 14, 37, 'Rabbanaaa inneee askantu min zurriyyatee biwaadin ghairi zee zar\'in \'inda Baitikal Muharrami Rabbanaa liyuqeemus Salaata faj\'al af\'idatam minan naasi tahweee ilaihim warzuqhum minas samaraati la\'allahum yashkuroon'),
  ('en.transliteration', 14, 38, 'Rabbanaaa innaka ta\'lamu maa nukhfee wa maa nu\'lin; wa maa yakhfaa \'alal laahi min shai\'in fil ardi wa laa fis samaaa\''),
  ('en.transliteration', 14, 39, 'Alhamdu lillaahil lazee wahaba lee \'alal kibari Ismaa\'eela wa Ishaaq; inna Rabbee lasamee\'ud du\'aaa'),
  ('en.transliteration', 14, 40, 'Rabbij \'alnee muqeemas Salaati wa min zurriyyatee Rabbanaa wa taqabbal du\'aaa\''),
  ('en.transliteration', 14, 41, 'Rabbanagh fir lee wa liwaalidaiya wa lilmu\'mineena Yawma yaqoomul hisaab'),
  ('en.transliteration', 14, 42, 'Wa laa tahsabannal laaha ghaafilan \'ammaa ya\'maluz zaalimoon; innamaa yu\'akh khiruhum li Yawmin tashkhasu feehil absaar'),
  ('en.transliteration', 14, 43, 'Muhti\'eena muqni\'ee ru\'oosihim laa yartaddu ilaihim tarfuhum wa af\'idatuhum hawaaa\''),
  ('en.transliteration', 14, 44, 'Wa anzirin naasa Yawma yaateehimul \'azaabu fa yaqoolul lazeena zalamoo Rabbanaaa akhkhirnaaa ilaaa ajalin qareebin nujib da\'wataka wa nattabi \'ir Rusul; awalam takoonooo aqsamtum min qablu maa lakum min zawaal'),
  ('en.transliteration', 14, 45, 'Wa sakantum fee masaakinil lazeena zalamooo anfusahum wa tabaiyana lakum kaifa fa\'alnaa bihim wa darabnaa lakumul amsaal'),
  ('en.transliteration', 14, 46, 'Wa qad makaroo makrahum wa \'indal laahi makruhum wa in kaana makruhum litazoola minhul jibaal'),
  ('en.transliteration', 14, 47, 'Falaa tahsabannal laaha mukhlifa wa\'dihee Rusulah; innal laaha \'azeezun zuntiqaam'),
  ('en.transliteration', 14, 48, 'Yawma tubaddalul ardu ghairal ardi wassamaawaatu wa barazoo lillaahil Waahidil Qahhaar'),
  ('en.transliteration', 14, 49, 'Wa taral mujrimeena Yawma \'izim muqarraneena filasfaad'),
  ('en.transliteration', 14, 50, 'Saraabeeluhum min qatiraaninw wa taghshaa wujoohahumun Naar'),
  ('en.transliteration', 14, 51, 'Liyajziyal laahu kulla nafsim maa kasabat; innal laaha saree\'ul hisaab'),
  ('en.transliteration', 14, 52, 'Haaza balaaghul linnaasi wa liyunzaroo bihee wa liya\'lamooo annamaa Huwa Illaahunw Waahidunw wa liyaz zakkara ulul albaab')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 14, 1, 'یہ ایک کتا ب ہے ہم نے اسے تیری طرف نازل کیا ہے تاکہ تو لوگوں کو ان کے رب کے حکم سے اندھیروں سے روشنی کی طرف غالب تعرف کیے ہوئے راستہ کی طرف نکالے'),
  ('ur.ahmedali', 14, 2, 'یعنی الله جس کے لیے ہے جو کچھ آسمانوں اور زمین میں ہے اور کافروں پر افسوس کہ انہیں سخت عذاب ہونا ہے'),
  ('ur.ahmedali', 14, 3, 'جو دنیا کی زندگی کو آخرت کے مقابلہ میں پسند کرتے ہیں اور الله کی راہ سے روکتے ہیں اور اس میں کجی تلاش کرتے ہیں وہ دور کی گمراہی میں پڑے ہوئے ہیں'),
  ('ur.ahmedali', 14, 4, 'اور ہم نے ہر پیغمبر کو اس کی قوم کی زبان میں پیغمبر بنا کر بھیجا ہے تاکہ انہیں سمجھا سکے پھر الله جسے چاہتا ہے گمراہ کرتا ہے اور جسے چاہتا ہے ہدایت دیتا ہے اوروہ غالب حکمت والا ہے'),
  ('ur.ahmedali', 14, 5, 'اورالبتہ تحقیق ہم نے موسیٰ کو اپنی نشانیاں دےکر بھیجا تھا کہاپنی قوم کو اندھیروں سے روشنی کی طرف نکال اورانہیں الله کے دن یاد دلا بے شک اس میں ہر ایک صبر شکر کرنے والے کے لیے بڑی نشانیاں ہیں'),
  ('ur.ahmedali', 14, 6, 'اورجب موسیٰ نے اپنی قوم سے کہا الله کا احسان اپنے اوپر یاد کرو جب تمہیں فرعون کی قوم سے چھڑا یا وہ تمہیں برا عذاب چکھاتے تھے اور تمہارے بیٹوں کو ذبح کرتے تھے اور تمہاری عورتوں کو زندہ رکھتے تھے اور اسمیں تمہارے رب کی طرف سے بڑی آزمائش تھی'),
  ('ur.ahmedali', 14, 7, 'اور جب تمہارے رب نے سنا دیا تھا کہ البتہ اگر تم شکر گزاری کرو گے تو اور زیادہ دوں گا اور اگر ناشکری کرو گے تو میرا عذاب بھی سخت ہے'),
  ('ur.ahmedali', 14, 8, 'اور موسیٰ نے کہا اگر تم اور جو لوگ زمین میں ہیں سارے کفر کرو گے تو الله بے پروا تعریف کیا ہوا ہے'),
  ('ur.ahmedali', 14, 9, 'کیا تمہیں ان لوگوں کی خبر نہیں پہنچی جوتم سے پہلے تھے نوح کی قوم اور عاد اور ثمود اورجو ان کے بعد ہوئے الله کےسوا جنہیں کوئی نہیں جانتا ان کے پاس ان کے رسول نشانیاں لے کر آئے پھرانہوں نے اپنے ہاتھ اپنے مونہوں میں لوٹائے اور کہا ہم نہیں مانتے جو تمہیں دے کر بھیجا گیا ہے اور جس دین کی طرف تم ہمیں بلاتے ہو ہمیں تو اس میں بڑا شک ہے'),
  ('ur.ahmedali', 14, 10, 'ان کے رسولوں نے کہا کیا تمہیں الله میں شک ہے جس نے آسمان او زمین بنائے وہ تمہیں بلاتا ہے تاکہ تمہارے کچھ گناہ بخشے اور تمہیں ایک مقررہ وقت تک مہلت دے انہوں نے کہا تم بھی تو ہمارے جیسے انسان ہو تم چاہتے ہو کہ ہمیں ان چیزوں سے روک دو جنہیں ہمارے باپ دادا پوجتے رہے سو کوئی کھلا ہوامعجزہ لاؤ'),
  ('ur.ahmedali', 14, 11, 'ان سے ان کے رسولوں نے کہا ضرور ہم بھی تمہارے جیسے ہی آدمی ہیں لیکن الله اپنے بندوں میں جس پر چاھتا ہے احسان کرتا ہے اور ہمارا کام نہیں کہ ہم الله کی اجازت کے سوا تمہیں کوئی معجزہ لا کر دکھائیں اور ایمان والوں کا بھروسہ اللهہی پر ہونا چاہیئے'),
  ('ur.ahmedali', 14, 12, 'اور ہم کیوں الله پر بھروسہ نہ کریں حالانکہ اسی نے ہمیں (سیدھے) راستوں کی راہ نمائی کی ہے اور ہم ضرور صبر کریں گے اس ایذاپر جو تم ہمیں دیتے ہو اور توکل کرنے والوں کو الله ہی پر بھروسہ کرنا چاہیے'),
  ('ur.ahmedali', 14, 13, 'اور کافروں نے اپنے رسولوں سے کہا ہم تمہیں اپنے ملک سے نکال دیں گے یا ہمارے دین میں لوٹ آؤ تب انہیں ان کے رب نے حکم بھیجا کہ ہم ان ظالموں کو ضرور ہلاک کر دیں گے'),
  ('ur.ahmedali', 14, 14, 'اور ان کے بعد اس زمین میں تمہیں آباد کر دیں گے یہ اس کے لیے ہے جو میرے سامنے کھڑا ہونے سے ڈرا اور جس نے میرے عذاب سے خوف کھایا'),
  ('ur.ahmedali', 14, 15, 'اور پیغمبروں نے فیصلہ چاہا اور ہر ایک سرکش ضدی نامراد ہوا'),
  ('ur.ahmedali', 14, 16, 'اوراس کے پیچھے دوزخ ہے اور اسے پیپ کا پانی پلایا جائے گا'),
  ('ur.ahmedali', 14, 17, 'جسے گھونٹ گھونٹ پیے گا اور اسے گلےسے نہ اتار سکے گا اور اس پر ہر طرف سے موت آئے گی اور وہ نہیں مرے گا اوراس کے پیچھے سخت عذاب ہوگا'),
  ('ur.ahmedali', 14, 18, 'ان کی مثال جنہوں نے اپنے رب سے انکار کیا ایسی ہے کہ ان کے اعمال گویا راکھ ہیں کہ جیسی آندھی کے دن ہوا اڑا کر لے گئی ہو جوکچھ انہوں نے کمایا تھا اس میں کچھ بھی ان کے ہاتھ میں نہ رہا ہویہ بھی بڑی دو رکی گمراہی ہے'),
  ('ur.ahmedali', 14, 19, 'کیا تو نے نہیں دیکھا کہ الله نے آسمانوں اور زمین کو ٹھیک طور پر بنایا اگر وہ چاہے تو تمہیں لے جائے اور نئی مخلوق لے آئے'),
  ('ur.ahmedali', 14, 20, 'اور یہ الله پر کچھ مشکل نہیں ہے'),
  ('ur.ahmedali', 14, 21, 'اوریہ سب الله کے سامنے کھڑیں ہوں گے تب کمزور متکبروں سے کہیں گے ہم تو تمہارے تابع تھے سوہمیں الله کے عذاب سے کچھ بچاؤ گے وہ کہیں گے اگر ہمیں الله ہدایت کرتا تو ہم تمہیں ہدایت کرتے اب ہمارے لیے برابر ہے کہ ہم چیخیں چلائیں یا صبر کریں ہمارے بچنے کی کوئی صورت نہیں'),
  ('ur.ahmedali', 14, 22, 'اور جب فیصلہ ہو چکے گا تو شیطان کہے گا بےشک الله نے تم سے سچا وعدہ کیا تھا اورمیں نے بھی تم سے وعدہ کیا تھا پھر میں نے وعدہ خلافی کی اور میرا تم پر اس کے سوا کوئی زور نہ تھا کہ میں نے تمہیں بلایا پھر تم نے میری بات کو مان لیا پھر مجھے الزام نہ دو اور اپنے آپ کو الزام دونہ میں تمہارا فریادرس ہوں اور نہ تم میرے فریاد رس ہو میں خود تمہارے اس فعل سے بیزار ہوں کہ تم اس سےپہلے مجھے شریک بناتے تھے بے شک ظالموں کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 14, 23, 'اور جو لوگ ایمان لائے تھے اورنیک کام کیے تھے وہ باغوں میں داخل کیے جائیں گے جن کے نیچے نہریں بہتی ہوں گی ان میں اپنے رب کے حکم سے ہمیشہ رہیں گے آپس میں دعائے خیر ان کی سلام ہو گی'),
  ('ur.ahmedali', 14, 24, 'کیاتو نےنہیں دیکھا کہ الله نے کلمہ پاک کی ایک مثال بیان کی ہے گویا وہ ایک پاک درخت ہے کہ جس کی جڑ مضبوط اور اس کی شاخ آسمان ہے'),
  ('ur.ahmedali', 14, 25, 'وہ اپنے رب کے حکم سے ہر وقت اپنا پھل لاتا ہے اور الله لوگوں کے واسطے مثالیں بیان کرتا ہے تاکہ وہ سمجھیں'),
  ('ur.ahmedali', 14, 26, 'اور ناپاک کلمہ کی مثال ایک ناپاک درخت کی سی ہے جو زمین کے اوپر ہی سے اکھاڑ لیا جائے اسے کچھ ٹھیراؤ نہیں ہے'),
  ('ur.ahmedali', 14, 27, 'الله ایمان والوں کو دنیا اور آخرت کی زندگی میں سچی بات پر ثابت قدم رکھتا ہے اور ظالمو ں کو گمراہ کر تا ہے اور الله جوچاہتا ہے کرتا ہے'),
  ('ur.ahmedali', 14, 28, 'کیاتو نے انہیں نہیں دیکھا کہ جنہوں نے الله کی نعمت کےبدلے میں ناشکری کی اور اپنی قوم کو تباہی کے گھر میں اتارا'),
  ('ur.ahmedali', 14, 29, 'جو دوزخ ہے اس میں داخل ہوں گے اور وہ برا ٹھکانا ہے'),
  ('ur.ahmedali', 14, 30, 'اور لوگو ں نے الله کی راہ سے بہکانے کے لیے شریک بنا رکھے ہیں کہہ دو نفع اٹھا لو پھر تمہیں آگ کی طرف لوٹنا ہے'),
  ('ur.ahmedali', 14, 31, 'میرے بندوں کو کہہ دو جو ایمان لائے ہیں نماز قائم رکھیں اور ہمارے دیے ہوئے رزق میں سے پوشیدہ اور ظاہر خرچ کریں اس سے پہلے کہ وہ دن آئے جس میں نہ خرید و فروخت ہے نہ دوستی'),
  ('ur.ahmedali', 14, 32, 'الله وہ ہے جس نے آسمان اور زمین بنائے اور آسمان سے پانی نازل کیا پھر اس سے تمہارے کھانے کو پھل نکالے اور کشتیاں تمہارے تابع کر دیں تاکہ دریا میں اس کے حکم سے چلتی رہیں اور نہریں تمہارے تابع کر دیں'),
  ('ur.ahmedali', 14, 33, 'اور سورج اور چاند کو تمہارے تابع کر دیا جو ہمیشہ چلنے والے ہیں اور تمہارے لیے رات اور دن کوتابع کیا'),
  ('ur.ahmedali', 14, 34, 'اور جو چیز تم نے ان سے مانگی اس نے تمہیں دی اور اگر الله کی نعمتیں شمار کرنے لگو تو انہیں شمار نہ کر سکو بے شک انسان بڑا بےانصاف اور ناشکرا ہے'),
  ('ur.ahmedali', 14, 35, 'اورجس وقت ابراھیم نے کہا اے میرے رب! اس شہر کوامن والا کر دے اور مجھے اور میری اولاد کو بت پرستی سے بچا'),
  ('ur.ahmedali', 14, 36, 'اے میرے رب! انہوں نے بہت لوگوں کو گمراہ کیا ہے پس جس نے میری پیروی کی وہ تو میرا ہے اورجس نے نافرمانی کی پس تحقیق تو بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 14, 37, 'اے رب میرے! میں نے اپنی کچھ اولاد ایسےمیدان میں بسائی ہے جہاں کھیتی نہیں تیرے عزت والے گھر کے پاس اے رب ہمارے! تاکہ نماز کو قائم رکھیں پھرکچھ لوگو ں کے دل ان کی طرف مائل کر دے اور انہیں میووں کی روزی دے تاکہ وہ شکر کریں'),
  ('ur.ahmedali', 14, 38, 'اے رب ہمارے! بے شک تو جانتا ہے جو کچھ ہم چھپاتے ہیں اورجو کچھ ظاہر کرتے ہیں اور الله پر کوئی چیز زمین اورآسمان میں پوشیدہ نہیں'),
  ('ur.ahmedali', 14, 39, 'الله کا شکر ہے جس نے مجھے اتنی بڑی عمر میں اسماعیل اور اسحاق بخشے بے شک میرا رب دعاؤں کا سننے والا ہے'),
  ('ur.ahmedali', 14, 40, 'اے میرے رب! مجھے اور میری اولاد کو نماز قائم کرنے والا بنا دے اے ہمارے رب! اورمیری دعا قبول فرما'),
  ('ur.ahmedali', 14, 41, 'اے ہمارے رب! مجھے اورمیرے ماں باپ کو اور ایمانداروں کو حساب قائم ہونے کے دن بخش دے'),
  ('ur.ahmedali', 14, 42, 'تو ہر گز خیال نہ کر کہ الله ان کاموں سے بے خبر ہے جو ظالم کرتے ہیں انہیں صرف اس دن تک مہلت دے رکھی ہے جس میں نگاہیں پھٹی رہ جائیں گی'),
  ('ur.ahmedali', 14, 43, 'وہ سرا اٹھائے ہوئے دوڑتے چلے جارہے ہوں گے کہ ا ن کی نظر ان کی طرف ہٹ کرنہیں آوے گی اور ان کے دل اڑ گئے ہوں گے'),
  ('ur.ahmedali', 14, 44, 'اور لوگوں کو اس دن سے ڈراوے کہ ان پر عذاب آئے گا تب ظالم کہیں گے اے رب ہمارے! ہمیں تھوڑی مدت تک مہلت دے کہ ہم تیرا بلانا قبول کر لیں اور رسولوں کی پیروی کر لیں کیاتم نے پہلے قسم نہیں کھائی تھی کہ تمہیں کہیں جانا ہی نہیں ہے'),
  ('ur.ahmedali', 14, 45, 'اور تم انہیں لوگو ں کی بستیوں میں آباد تھے جنہوں نے اپنی جانوں پر ظلم کیا تھا اور تمہیں معلوم ہو چکا تھا کہ ہم نے ان کے ساتھ کیا کیا تھا او رہم نے تمہیں سب قصے بتلائے تھے'),
  ('ur.ahmedali', 14, 46, 'اور ان لوگو ں نے اپنی تدبیریں کی تھیں اوران کی تدبیریں الله کے سامنے تھیں اگرچہ ان کی تدبیریں ایسی تھی کہ ان سے پہاڑ بھی ٹل جائیں'),
  ('ur.ahmedali', 14, 47, 'پس الله کو اپنے رسولوں سے وعدہ خلافی کرنے والا خیال نہ کریں بے شک الله زبردست بدلہ لینے والا ہے'),
  ('ur.ahmedali', 14, 48, 'جس دن اس زمین میں سے اور زمین بدلی جائے گی اور آسمان بدلے جاویں گے اور سب کے سب ایک زبردست الله کے روبرو پیش ہوں گے'),
  ('ur.ahmedali', 14, 49, 'اورتو اس دن گناہگاروں کو زنجیروں میں جکڑے ہوئے دیکھے گا'),
  ('ur.ahmedali', 14, 50, 'کرتےان کے گندھک کے ہوں گے اوران کے چہرو ں پر آگ لپٹی ہو گی'),
  ('ur.ahmedali', 14, 51, 'تاکہ الله ہر شخص کو اس کے کیے کی سزا دے بے شک الله بڑی جلدی حساب لینے والا ہے'),
  ('ur.ahmedali', 14, 52, 'یہ قرآن لوگو ں کے لیے اعلان ہے اور تاکہ اس کے ذریعے سے لوگوں کو ڈرایا جائے اور تاکہ وہ معلوم کر لیں کہ وہی ایک معبود ہے اور تاکہ عقلمند نصیحت حاصل کریں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 14, 1, 'Elif, Lam, Ra; Bu, Allah\'ın izniyle, insanları karanlıklardan aydınlığa, güçlü ve övülmeğe layık, göklerde ve yerde olanların sahibi Allah\'ın yoluna çıkarman için, sana indirdiğimiz Kitaptır. Uğrayacakları çetin azabdan dolayı vay kafirlerin haline!'),
  ('tr.diyanet', 14, 2, 'Elif, Lam, Ra; Bu, Allah\'ın izniyle, insanları karanlıklardan aydınlığa, güçlü ve övülmeğe layık, göklerde ve yerde olanların sahibi Allah\'ın yoluna çıkarman için, sana indirdiğimiz Kitaptır. Uğrayacakları çetin azabdan dolayı vay kafirlerin haline!'),
  ('tr.diyanet', 14, 3, 'Onlar dünya hayatını ahirete tercih ederler, Allah\'ın yolundan alıkoyup onun eğriliğini isterler. İşte onlar uzak bir sapıklık içindedirler.'),
  ('tr.diyanet', 14, 4, 'Kendilerine apaçık anlatabilsin diye, her peygamberi kendi milletinin diliyle gönderdik. Allah dilediğini saptırır ve dilediğini de doğru yola eriştirir; güçlü olan, Hakim olan O\'dur.'),
  ('tr.diyanet', 14, 5, 'And olsun ki Musa\'yı ayetlerimizle, "Milletini karanlıklardan aydınlığa çıkar ve Allah\'ın günlerini onlara hatırlat" diye göndermiştik. Bunlarda, çokça sabreden ve şükreden herkes için dersler vardır.'),
  ('tr.diyanet', 14, 6, 'Musa, milletine dedi ki: "Allah\'ın size olan nimetlerini anın; size işkence eden, kadınlarınızı sağ bırakıp oğullarınızı boğazlayan Firavun ailesinden sizi kurtardı; bütün bunlarda Rabbinizden size büyük bir imtihan vardır."'),
  ('tr.diyanet', 14, 7, 'Rabbiniz: "Şükrederseniz and olsun ki, size karşılığını artıracağım; nankörlük ederseniz bilin ki azabım pek çetindir" diye bildirmişti.'),
  ('tr.diyanet', 14, 8, 'Musa: "Siz ve yeryüzünde olanlar, hepiniz nankörlük etseniz, Allah yine de müstağni ve övülmeğe layık olandır" demişti.'),
  ('tr.diyanet', 14, 9, 'Sizden önce gecen Nuh, Ad, Semud milletlerinin ve onlardan sonra gelenlerin haberleri ki onları Allah\'tan başkası bilmez size ulaşmadı mı? Onlara peygamberleri belgelerle geldiler, fakat ellerini ağızlarına götürüp: "Biz sizinle gönderilene inanmıyoruz. Bizi çağırdığınız şeyden de şüphe ve endişe içindeyiz" dediler.'),
  ('tr.diyanet', 14, 10, 'Onların peygamberleri: "Gökleri ve yeri yaratan, günahlarınızı bağışlamaya çağıran ve bir süreye kadar sizi erteleyen Allah\'tan mı şüphe ediyorsunuz?" dediler. Onlar da: "Siz de sadece bizim gibi birer insansınız; bizi babalarımızın taptıklarından alıkoymak istiyorsunuz. Öyleyse bize apaçık bir delil getirmelisiniz" dediler.'),
  ('tr.diyanet', 14, 11, 'Peygamberleri onlara şöyle dedi: "Biz ancak sizin gibi birer insanız ama, Allah, kullarından dilediğine iyilikte bulunur. Allah\'ın izni olmadıkça biz size delil getiremeyiz. İnananlar sadece Allah\'a güvensin."'),
  ('tr.diyanet', 14, 12, '"Bize yollarımızı gösteren Allah\'a niçin güvenmeyelim? Bize ettiğiniz eziyete elbette katlanacağız. Güvenenler ancak Allah\'a güvensinler."'),
  ('tr.diyanet', 14, 13, 'İnkar edenler, peygamberlerine: "Ya bizim dinimize dönersiniz ya da sizi memleketimizden çıkarırız" dediler. Rableri peygamberlere: "Biz, haksızlık edenleri yok edeceğiz, onlardan sonra yeryüzüne sizi yerleştireceğiz. Bu, makamımdan ve tehdidimden korkanlar içindir." diye vahyetti.'),
  ('tr.diyanet', 14, 14, 'İnkar edenler, peygamberlerine: "Ya bizim dinimize dönersiniz ya da sizi memleketimizden çıkarırız" dediler. Rableri peygamberlere: "Biz, haksızlık edenleri yok edeceğiz, onlardan sonra yeryüzüne sizi yerleştireceğiz. Bu, makamımdan ve tehdidimden korkanlar içindir." diye vahyetti.'),
  ('tr.diyanet', 14, 15, 'Peygamberler yardım istediler ve her inatçı zorba hüsrana uğradı.'),
  ('tr.diyanet', 14, 16, 'Ardında cehennem vardır; orada kendisine irinli su içirilecektir.'),
  ('tr.diyanet', 14, 17, 'Onu yudum yudum alacak fakat yutamıyacaktır. Ölüm ona her taraftan geldiği halde, ölemiyecek, arkasından da çetin bir azap gelecektir.'),
  ('tr.diyanet', 14, 18, 'Rablerini inkar edenlerin işleri, fırtınalı bir günde, rüzgarın şiddetle savurduğu küle benzer; yaptıklarından hiçbir şey elde edemezler. İşte bu uzak sapıklıktır.'),
  ('tr.diyanet', 14, 19, 'Gökleri ve yeri gerçekten Allah\'ın yarattığını bilmiyor musun? Dilerse sizi yok edip yeni bir topluluk var eder.'),
  ('tr.diyanet', 14, 20, 'Bu, Allah için güç değildir.'),
  ('tr.diyanet', 14, 21, 'İnsanların hepsi Allah\'ın huzuruna çıkarlar; güçsüzler, büyüklük taslayanlara: "Doğrusu biz size uymuştuk, Allah\'ın azabından bizi koruyabilecek misiniz?" derler. Cevap olarak: "Allah bizi doğru yola eriştirseydi biz de sizi eriştirirdik. Artık sızlansak da sabretsek de birdir, çünkü kaçacak yerimiz yoktur" derler.'),
  ('tr.diyanet', 14, 22, 'İş olup bitince, şeytan: "Doğrusu Allah size gerçeği söz vermişti. Ben de size söz verdim ama, sonra caydım; esasen sizi zorlayacak bir nüfuzum yoktu; sadece çağırdım, siz de geldiniz. O halde, beni değil kendinizi kınayın. Artık ben sizi kurtaramam, siz de beni kurtaramazsınız. Beni Allah\'a ortak koşmanızı daha önce kabul etmemiştim; doğrusu zalimlere can yakan bir azap vardır" der.'),
  ('tr.diyanet', 14, 23, 'İnanan ve yararlı işleri yapanlar, içlerinden ırmaklar akan cennetlere konulurlar, Rablerinin izniyle orada temelli kalırlar. Oradaki dirlik temennileri: "Selam!"dır.'),
  ('tr.diyanet', 14, 24, 'Allah\'ın, hoş bir sözü; kökü sağlam, dalları göğe doğru olan, Rabbinin izniyle her zaman meyve veren hoş bir ağaca benzeterek nasıl misal verdiğini görmüyor musun? İnsanlar ibret alsın diye Allah onlara misal gösteriyor.'),
  ('tr.diyanet', 14, 25, 'Allah\'ın, hoş bir sözü; kökü sağlam, dalları göğe doğru olan, Rabbinin izniyle her zaman meyve veren hoş bir ağaca benzeterek nasıl misal verdiğini görmüyor musun? İnsanlar ibret alsın diye Allah onlara misal gösteriyor.'),
  ('tr.diyanet', 14, 26, 'Çirkin bir söz de, yerden koparılmış, kökü olmayan kötü bir ağaca benzer.'),
  ('tr.diyanet', 14, 27, 'Allah inananları, dünya hayatında ve ahirette sağlam bir söz üzerinde tutar; zalimleri de saptırır. Allah dilediğini yapar.'),
  ('tr.diyanet', 14, 28, 'Allah\'ın verdiği nimeti nankörlükle karşılayanları ve milletlerini helak olacakları yere, yaslanacakları cehenneme götürenleri görmüyor musun?'),
  ('tr.diyanet', 14, 29, 'Allah\'ın verdiği nimeti nankörlükle karşılayanları ve milletlerini helak olacakları yere, yaslanacakları cehenneme götürenleri görmüyor musun?'),
  ('tr.diyanet', 14, 30, 'Allah\'ın yolundan sapıtmak için O\'na eşler koşmuşlardı. De ki: "Yaşayın bakalım, hiç şüphesiz varacağınız yer ateş olacaktır."'),
  ('tr.diyanet', 14, 31, 'İnanan kullarıma söyle, namazı kılsınlar; alışveriş ve dostluğun olmayacağı günün gelmesinden önce, kendilerine verdiğimiz rızıktan açık ve gizli sarfetsinler.'),
  ('tr.diyanet', 14, 32, 'Gökleri ve yeri yaratan, yukardan indirdiği su ile rızık olarak ürünler yetiştiren, emri gereğince denizde yüzmek üzere gemileri, nehirleri, belli yörüngelerinde yürüyen ay ve güneşi, geceyle gündüzü sizin buyruğunuza veren Allah\'tır.'),
  ('tr.diyanet', 14, 33, 'Gökleri ve yeri yaratan, yukardan indirdiği su ile rızık olarak ürünler yetiştiren, emri gereğince denizde yüzmek üzere gemileri, nehirleri, belli yörüngelerinde yürüyen ay ve güneşi, geceyle gündüzü sizin buyruğunuza veren Allah\'tır.'),
  ('tr.diyanet', 14, 34, 'Kendisinden isteyebileceğiniz her şeyi size vermiştir. Allah\'ın nimetini sayacak olsanız bitiremezsiniz. Doğrusu insan pek zalim ve çok nankördür.'),
  ('tr.diyanet', 14, 35, 'İbrahim şöyle demişti: "Rabbim! Bu şehri güvenli kıl; beni ve oğullarımı putlara tapmaktan uzak tut."'),
  ('tr.diyanet', 14, 36, '"Rabbim! O putlar çok insanları saptırdı; bana uyan bendendir, bana karşı gelen kimseyi Sana bırakırım; Sen bağışlarsın, merhamet edersin."'),
  ('tr.diyanet', 14, 37, '"Rabbimiz! Ben çocuklarımdan kimini, namaz kılabilmeleri için Senin kutsal evinin yanında, ziraata elverişsiz bir vadiye yerleştirdim. Rabbimiz! İnsanların gönüllerini onlara meylettir, şükretmeleri için onları ürünlerle rızıklandır."'),
  ('tr.diyanet', 14, 38, '"Rabbimiz! Doğrusu Sen gizlediğimizi de, açığa vurduğumuzu da bilirsin. Yerde ve gökte hiçbir şey Allah\'tan gizli kalmaz."'),
  ('tr.diyanet', 14, 39, '"Kocamışken, bana İsmail ve İshak\'ı veren Allah\'a hamdolsun. Doğrusu Rabbim duaları işitendir."'),
  ('tr.diyanet', 14, 40, '"Rabbim! Beni ve çocuklarımı namaz kılanlardan eyle. Rabbimiz! Duamı kabul buyur."'),
  ('tr.diyanet', 14, 41, '"Rabbimiz! Hesap görülecek günde, beni, anamı babamı ve inananları bağışla."'),
  ('tr.diyanet', 14, 42, 'Sakın Allah\'ı, zalimlerin yaptıklarından habersiz sanma; gözlerin dışarı fırlayacağı bir güne kadar onları ertelemektedir.'),
  ('tr.diyanet', 14, 43, 'O gün başları kalkmış, gözleri kendilerine dönemeyecek şekilde sabit kalmış, gönülleri bomboş halde koşup duracaklardır.'),
  ('tr.diyanet', 14, 44, 'İnsanları, kendilerine azabın geleceği gün ile uyar. Haksızlık edenler: "Rabbimiz! Bizi yakın bir süreye kadar ertele de çağrına gelelim, peygamberlere uyalım" derler. Siz daha önce, sonunuzun gelmeyeceğine yemin etmemiş miydiniz! Üstelik kendilerine yazık edenlerin yerlerinde oturdunuz. Onlara, yaptıklarımız da sizlere açıklanmıştı. Size misaller de vermiştik.'),
  ('tr.diyanet', 14, 45, 'İnsanları, kendilerine azabın geleceği gün ile uyar. Haksızlık edenler: "Rabbimiz! Bizi yakın bir süreye kadar ertele de çağrına gelelim, peygamberlere uyalım" derler. Siz daha önce, sonunuzun gelmeyeceğine yemin etmemiş miydiniz! Üstelik kendilerine yazık edenlerin yerlerinde oturdunuz. Onlara, yaptıklarımız da sizlere açıklanmıştı. Size misaller de vermiştik.'),
  ('tr.diyanet', 14, 46, 'Şüphesiz onlar düzenlerini kurdular; oysa dağları yerinden oynatacak olsa bile, bu düzenleri hep Allah\'ın elindeydi.'),
  ('tr.diyanet', 14, 47, 'Yerin başka bir yerle, göklerin de başka göklerle değiştirildiği, her şeye üstün gelen tek Allah\'ın huzuruna çıktıkları günde, sakın Allah\'ın peygamberlerine verdiği sözden cayacağını sanma; doğrusu Allah güçlüdür, öç alandır.'),
  ('tr.diyanet', 14, 48, 'Yerin başka bir yerle, göklerin de başka göklerle değiştirildiği, her şeye üstün gelen tek Allah\'ın huzuruna çıktıkları günde, sakın Allah\'ın peygamberlerine verdiği sözden cayacağını sanma; doğrusu Allah güçlüdür, öç alandır.'),
  ('tr.diyanet', 14, 49, 'O gün, suçluları zincirlere vurulmuş olarak görürsün.'),
  ('tr.diyanet', 14, 50, 'Gömlekleri katrandan olacak, yüzlerini ateş bürüyecektir.'),
  ('tr.diyanet', 14, 51, 'Bu, Allah herkese yaptığının karşılığını vereceği için böyledir. Doğrusu Allah hesabı çabuk görür.'),
  ('tr.diyanet', 14, 52, 'Bu Kuran, onunla uyarılsınlar ve tek bir Tanrı bulunduğunu bilsinler ve akıl sahipleri öğüt alsınlar diye insanlara tebliğ edilmiştir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 14, 1, 'Alif, laam raa. (Ini adalah) Kitab yang Kami turunkan kepadamu supaya kamu mengeluarkan manusia dari gelap gulita kepada cahaya terang benderang dengan izin Tuhan mereka, (yaitu) menuju jalan Tuhan Yang Maha Perkasa lagi Maha Terpuji.'),
  ('id.indonesian', 14, 2, 'Allah-lah yang memiliki segala apa yang di langit dan di bumi. Dan kecelakaanlah bagi orang-orang kafir karena siksaan yang sangat pedih,'),
  ('id.indonesian', 14, 3, '(yaitu) orang-orang yang lebih menyukai kehidupan dunia dari pada kehidupan akhirat, dan menghalang-halangi (manusia) dari jalan Allah dan menginginkan agar jalan Allah itu bengkok. Mereka itu berada dalam kesesatan yang jauh.'),
  ('id.indonesian', 14, 4, 'Kami tidak mengutus seorang rasulpun, melainkan dengan bahasa kaumnya, supaya ia dapat memberi penjelasan dengan terang kepada mereka. Maka Allah menyesatkan siapa yang Dia kehendaki, dan memberi petunjuk kepada siapa yang Dia kehendaki. Dan Dialah Tuhan Yang Maha Kuasa lagi Maha Bijaksana.'),
  ('id.indonesian', 14, 5, 'Dan sesungguhnya Kami telah mengutus Musa dengan membawa ayat-ayat Kami, (dan Kami perintahkan kepadanya): "Keluarkanlah kaummu dari gelap gulita kepada cahaya terang benderang dan ingatkanlah mereka kepada hari-hari Allah". Sesunguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi setiap orang penyabar dan banyak bersyukur.'),
  ('id.indonesian', 14, 6, 'Dan (ingatlah), ketika Musa berkata kepada kaumnya: "Ingatlah nikmat Allah atasmu ketika Dia menyelamatkan kamu dari (Fir\'aun dan) pengikut-pengikutnya, mereka menyiksa kamu dengan siksa yang pedih, mereka menyembelih anak-anak laki-lakimu, membiarkan hidup anak-anak perempuanmu; dan pada yang demikian itu ada cobaan yang besar dari Tuhanmu".'),
  ('id.indonesian', 14, 7, 'Dan (ingatlah juga), tatkala Tuhanmu memaklumkan; "Sesungguhnya jika kamu bersyukur, pasti Kami akan menambah (nikmat) kepadamu, dan jika kamu mengingkari (nikmat-Ku), maka sesungguhnya azab-Ku sangat pedih".'),
  ('id.indonesian', 14, 8, 'Dan Musa berkata: "Jika kamu dan orang-orang yang ada di muka bumi semuanya mengingkari (nikmat Allah) maka sesungguhnya Allah Maha Kaya lagi Maha Terpuji".'),
  ('id.indonesian', 14, 9, 'Belumkah sampai kepadamu berita orang-orang sebelum kamu (yaitu) kaum Nuh, \'Ad, Tsamud dan orang-orang sesudah mereka. Tidak ada yang mengetahui mereka selain Allah. Telah datang rasul-rasul kepada mereka (membawa) bukti-bukti yang nyata lalu mereka menutupkan tangannya ke mulutnya (karena kebencian), dan berkata: "Sesungguhnya kami mengingkari apa yang kamu disuruh menyampaikannya (kepada kami), dan sesungguhnya kami benar-benar dalam keragu-raguan yang menggelisahkan terhadap apa yang kamu ajak kami kepadanya".'),
  ('id.indonesian', 14, 10, 'Berkata rasul-rasul mereka: "Apakah ada keragu-raguan terhadap Allah, Pencipta langit dan bumi? Dia menyeru kamu untuk memberi ampunan kepadamu dari dosa-dosamu dan menangguhkan (siksaan)mu sampai masa yang ditentukan?" Mereka berkata: "Kamu tidak lain hanyalah manusia seperti kami juga. Kamu menghendaki untuk menghalang-halangi (membelokkan) kami dari apa yang selalu disembah nenek moyang kami, karena itu datangkanlah kepada kami, bukti yang nyata".'),
  ('id.indonesian', 14, 11, 'Rasul-rasul mereka berkata kepada mereka: "Kami tidak lain hanyalah manusia seperti kamu, akan tetapi Allah memberi karunia kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya. Dan tidak patut bagi kami mendatangkan suatu bukti kepada kamu melainkan dengan izin Allah. Dan hanya kepada Allah sajalah hendaknya orang-orang mukmin bertawakkal.'),
  ('id.indonesian', 14, 12, 'Mengapa kami tidak akan bertawakkal kepada Allah padahal Dia telah menunjukkan jalan kepada kami, dan kami sungguh-sungguh akan bersabar terhadap gangguan-gangguan yang kamu lakukan kepada kami. Dan hanya kepada Allah saja orang-orang yang bertawakkal itu, berserah diri".'),
  ('id.indonesian', 14, 13, 'Orang-orang kafir berkata kepada Rasul-rasul mereka: "Kami sungguh-sungguh akan mengusir kamu dari negeri kami atau kamu kembali kepada agama kami". Maka Tuhan mewahyukan kepada mereka: "Kami pasti akan membinasakan orang-orang yang zalim itu,'),
  ('id.indonesian', 14, 14, 'dan Kami pasti akan menempatkan kamu di negeri-negeri itu sesudah mereka. Yang demikian itu (adalah untuk) orang-orang yang takut (akan menghadap) kehadirat-Ku dan yang takut kepada ancaman-Ku".'),
  ('id.indonesian', 14, 15, 'Dan mereka memohon kemenangan (atas musuh-musuh mereka) dan binasalah semua orang yang berlaku sewenang-wenang lagi keras kepala,'),
  ('id.indonesian', 14, 16, 'di hadapannya ada Jahannam dan dia akan diberi minuman dengan air nanah,'),
  ('id.indonesian', 14, 17, 'diminumnnya air nanah itu dan hampir dia tidak bisa menelannya dan datanglah (bahaya) maut kepadanya dari segenap penjuru, tetapi dia tidak juga mati, dan dihadapannya masih ada azab yang berat.'),
  ('id.indonesian', 14, 18, 'Orang-orang yang kafir kepada Tuhannya, amalan-amalan mereka adalah seperti abu yang ditiup angin dengan keras pada suatu hari yang berangin kencang. Mereka tidak dapat mengambil manfaat sedikitpun dari apa yang telah mereka usahakan (di dunia). Yang demikian itu adalah kesesatan yang jauh.'),
  ('id.indonesian', 14, 19, 'Tidakkah kamu perhatikan, bahwa sesungguhnya Allah telah menciptakan langit dan bumi dengan hak? Jika Dia menghendaki, niscaya Dia membinasakan kamu dan mengganti(mu) dengan makhluk yang baru,'),
  ('id.indonesian', 14, 20, 'dan yang demikian itu sekali-kali tidak sukar bagi Allah.'),
  ('id.indonesian', 14, 21, 'Dan mereka semuanya (di padang Mahsyar) akan berkumpul menghadap ke hadirat Allah, lalu berkatalah orang-orang yang lemah kepada orang-orang yang sombong: "Sesungguhnya kami dahulu adalah pengikut-pengikutmu, maka dapatkah kamu menghindarkan daripada kami azab Allah (walaupun) sedikit saja? Mereka menjawab: "Seandainya Allah memberi petunjuk kepada kami, niscaya kami dapat memberi petunjuk kepadamu. Sama saja bagi kita, apakah kita mengeluh ataukah bersabar. Sekali-kali kita tidak mempunyai tempat untuk melarikan diri".'),
  ('id.indonesian', 14, 22, 'Dan berkatalah syaitan tatkala perkara (hisab) telah diselesaikan: "Sesungguhnya Allah telah menjanjikan kepadamu janji yang benar, dan akupun telah menjanjikan kepadamu tetapi aku menyalahinya. Sekali-kali tidak ada kekuasaan bagiku terhadapmu, melainkan (sekedar) aku menyeru kamu lalu kamu mematuhi seruanku, oleh sebab itu janganlah kamu mencerca aku akan tetapi cercalah dirimu sendiri. Aku sekali-kali tidak dapat menolongmu dan kamupun sekali-kali tidak dapat menolongku. Sesungguhnya aku tidak membenarkan perbuatanmu mempersekutukan aku (dengan Allah) sejak dahulu". Sesungguhnya orang-orang yang zalim itu mendapat siksaan yang pedih.'),
  ('id.indonesian', 14, 23, 'Dan dimasukkanlah orang-orang yang beriman dan beramal saleh ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya dengan seizin Tuhan mereka. Ucapan penghormatan mereka dalam surga itu ialah "salaam".'),
  ('id.indonesian', 14, 24, 'Tidakkah kamu perhatikan bagaimana Allah telah membuat perumpamaan kalimat yang baik seperti pohon yang baik, akarnya teguh dan cabangnya (menjulang) ke langit,'),
  ('id.indonesian', 14, 25, 'pohon itu memberikan buahnya pada setiap musim dengan seizin Tuhannya. Allah membuat perumpamaan-perumpamaan itu untuk manusia supaya mereka selalu ingat.'),
  ('id.indonesian', 14, 26, 'Dan perumpamaan kalimat yang buruk seperti pohon yang buruk, yang telah dicabut dengan akar-akarnya dari permukaan bumi; tidak dapat tetap (tegak) sedikitpun.'),
  ('id.indonesian', 14, 27, 'Allah meneguhkan (iman) orang-orang yang beriman dengan ucapan yang teguh itu dalam kehidupan di dunia dan di akhirat; dan Allah menyesatkan orang-orang yang zalim dan memperbuat apa yang Dia kehendaki.'),
  ('id.indonesian', 14, 28, 'Tidakkah kamu perhatikan orang-orang yang telah menukar nikmat Allah dengan kekafiran dan menjatuhkan kaumnya ke lembah kebinasaan?,'),
  ('id.indonesian', 14, 29, 'yaitu neraka jahannam; mereka masuk kedalamnya; dan itulah seburuk-buruk tempat kediaman.'),
  ('id.indonesian', 14, 30, 'Orang-orang kafir itu telah menjadikan sekutu-sekutu bagi Allah supaya mereka menyesatkan (manusia) dari jalan-Nya. Katakanlah: "Bersenang-senanglah kamu, karena sesungguhnya tempat kembalimu ialah neraka".'),
  ('id.indonesian', 14, 31, 'Katakanlah kepada hamba-hamba-Ku yang telah beriman: "Hendaklah mereka mendirikan shalat, menafkahkan sebahagian rezeki yang Kami berikan kepada mereka secara sembunyi ataupun terang-terangan sebelum datang hari (kiamat) yang pada bari itu tidak ada jual beli dan persahabatan.'),
  ('id.indonesian', 14, 32, 'Allah-lah yang telah menciptakan langit dan bumi dan menurunkan air hujan dari langit, kemudian Dia mengeluarkan dengan air hujan itu berbagai buah-buahan menjadi rezeki untukmu; dan Dia telah menundukkan bahtera bagimu supaya bahtera itu, berlayar di lautan dengan kehendak-Nya, dan Dia telah menundukkan (pula) bagimu sungai-sungai.'),
  ('id.indonesian', 14, 33, 'Dan Dia telah menundukkan (pula) bagimu matahari dan bulan yang terus menerus beredar (dalam orbitnya); dan telah menundukkan bagimu malam dan siang.'),
  ('id.indonesian', 14, 34, 'Dan Dia telah memberikan kepadamu (keperluanmu) dan segala apa yang kamu mohonkan kepadanya. Dan jika kamu menghitung nikmat Allah, tidaklah dapat kamu menghinggakannya. Sesungguhnya manusia itu, sangat zalim dan sangat mengingkari (nikmat Allah).'),
  ('id.indonesian', 14, 35, 'Dan (ingatlah), ketika Ibrahim berkata: "Ya Tuhanku, jadikanlah negeri ini (Mekah), negeri yang aman, dan jauhkanlah aku beserta anak cucuku daripada menyembah berhala-berhala.'),
  ('id.indonesian', 14, 36, 'Ya Tuhanku, sesungguhnya berhala-berhala itu telah menyesatkan kebanyakan daripada manusia, maka barangsiapa yang mengikutiku, maka sesungguhnya orang itu termasuk golonganku, dan barangsiapa yang mendurhakai aku, maka sesungguhnya Engkau, Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 14, 37, 'Ya Tuhan kami, sesungguhnya aku telah menempatkan sebahagian keturunanku di lembah yang tidak mempunyai tanam-tanaman di dekat rumah Engkau (Baitullah) yang dihormati, ya Tuhan kami (yang demikian itu) agar mereka mendirikan shalat, maka jadikanlah hati sebagian manusia cenderung kepada mereka dan beri rezekilah mereka dari buah-buahan, mudah-mudahan mereka bersyukur.'),
  ('id.indonesian', 14, 38, 'Ya Tuhan kami, sesungguhnya Engkau mengetahui apa yang kami sembunyikan dan apa yang kami lahirkan; dan tidak ada sesuatupun yang tersembunyi bagi Allah, baik yang ada di bumi maupun yang ada di langit.'),
  ('id.indonesian', 14, 39, 'Segala puji bagi Allah yang telah menganugerahkan kepadaku di hari tua(ku) Ismail dan Ishaq. Sesungguhnya Tuhanku, benar-benar Maha Mendengar (memperkenankan) doa.'),
  ('id.indonesian', 14, 40, 'Ya Tuhanku, jadikanlah aku dan anak cucuku orang-orang yang tetap mendirikan shalat, ya Tuhan kami, perkenankanlah doaku.'),
  ('id.indonesian', 14, 41, 'Ya Tuhan kami, beri ampunlah aku dan kedua ibu bapaku dan sekalian orang-orang mukmin pada hari terjadinya hisab (hari kiamat)".'),
  ('id.indonesian', 14, 42, 'Dan janganlah sekali-kali kamu (Muhammad) mengira, bahwa Allah lalai dari apa yang diperbuat oleh orang-orang yang zalim. Sesungguhnya Allah memberi tangguh kepada mereka sampai hari yang pada waktu itu mata (mereka) terbelalak,'),
  ('id.indonesian', 14, 43, 'mereka datang bergegas-gegas memenuhi panggilan dengan mangangkat kepalanya, sedang mata mereka tidak berkedip-kedip dan hati mereka kosong.'),
  ('id.indonesian', 14, 44, 'Dan berikanlah peringatan kepada manusia terhadap hari (yang pada waktu itu) datang azab kepada mereka, maka berkatalah orang-orang yang zalim: "Ya Tuhan kami, beri tangguhlah kami (kembalikanlah kami ke dunia) walaupun dalam waktu yang sedikit, niscaya kami akan mematuhi seruan Engkau dan akan mengikuti rasul-rasul". (Kepada mereka dikatakan): "Bukankah kamu telah bersumpah dahulu (di dunia) bahwa sekali-kali kamu tidak akan binasa?'),
  ('id.indonesian', 14, 45, 'dan kamu telah berdiam di tempat-tempat kediaman orang-orang yang menganiaya diri mereka sendiri, dan telah nyata bagimu bagaimana Kami telah berbuat terhadap mereka dan telah Kami berikan kepadamu beberapa perumpamaan".'),
  ('id.indonesian', 14, 46, 'Dan sesungguhnya mereka telah membuat makar yang besar padahal di sisi Allah-lah (balasan) makar mereka itu. Dan sesungguhnya makar mereka itu (amat besar) sehingga gunung-gunung dapat lenyap karenanya.'),
  ('id.indonesian', 14, 47, 'Karena itu janganlah sekali-kali kamu mengira Allah akan menyalahi janji-Nya kepada rasul-raaul-Nya; sesungguhnya Allah Maha Perkasa, lagi mempunyai pembalasan.'),
  ('id.indonesian', 14, 48, '(Yaitu) pada hari (ketika) bumi diganti dengan bumi yang lain dan (demikian pula) langit, dan meraka semuanya (di padang Mahsyar) berkumpul menghadap ke hadirat Allah yang Maha Esa lagi Maha Perkasa.'),
  ('id.indonesian', 14, 49, 'Dan kamu akan melihat orang-orang yang berdosa pada hari itu diikat bersama-sama dengan belenggu.'),
  ('id.indonesian', 14, 50, 'Pakaian mereka adalah dari pelangkin (ter) dan muka mereka ditutup oleh api neraka,'),
  ('id.indonesian', 14, 51, 'agar Allah memberi pembalasan kepada tiap-tiap orang terhadap apa yang ia usahakan. Sesungguhnya Allah Maha cepat hisab-Nya.'),
  ('id.indonesian', 14, 52, '(Al Quran) ini adalah penjelasan yang sempurna bagi manusia, dan supaya mereka diberi peringatan dengan-Nya, dan supaya mereka mengetahui bahwasanya Dia adalah Tuhan Yang Maha Esa dan agar orang-orang yang berakal mengambil pelajaran.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 15, 1, 'Alif, Lam, Ra. These are the verses of the Book and a clear Qur\'an.'),
  ('en.sahih', 15, 2, 'Perhaps those who disbelieve will wish that they had been Muslims.'),
  ('en.sahih', 15, 3, 'Let them eat and enjoy themselves and be diverted by [false] hope, for they are going to know.'),
  ('en.sahih', 15, 4, 'And We did not destroy any city but that for it was a known decree.'),
  ('en.sahih', 15, 5, 'No nation will precede its term, nor will they remain thereafter.'),
  ('en.sahih', 15, 6, 'And they say, "O you upon whom the message has been sent down, indeed you are mad.'),
  ('en.sahih', 15, 7, 'Why do you not bring us the angels, if you should be among the truthful?"'),
  ('en.sahih', 15, 8, 'We do not send down the angels except with truth; and the disbelievers would not then be reprieved.'),
  ('en.sahih', 15, 9, 'Indeed, it is We who sent down the Qur\'an and indeed, We will be its guardian.'),
  ('en.sahih', 15, 10, 'And We had certainly sent [messengers] before you, [O Muhammad], among the sects of the former peoples.'),
  ('en.sahih', 15, 11, 'And no messenger would come to them except that they ridiculed him.'),
  ('en.sahih', 15, 12, 'Thus do We insert denial into the hearts of the criminals.'),
  ('en.sahih', 15, 13, 'They will not believe in it, while there has already occurred the precedent of the former peoples.'),
  ('en.sahih', 15, 14, 'And [even] if We opened to them a gate from the heaven and they continued therein to ascend,'),
  ('en.sahih', 15, 15, 'They would say, "Our eyes have only been dazzled. Rather, we are a people affected by magic."'),
  ('en.sahih', 15, 16, 'And We have placed within the heaven great stars and have beautified it for the observers.'),
  ('en.sahih', 15, 17, 'And We have protected it from every devil expelled [from the mercy of Allah]'),
  ('en.sahih', 15, 18, 'Except one who steals a hearing and is pursued by a clear burning flame.'),
  ('en.sahih', 15, 19, 'And the earth - We have spread it and cast therein firmly set mountains and caused to grow therein [something] of every well-balanced thing.'),
  ('en.sahih', 15, 20, 'And We have made for you therein means of living and [for] those for whom you are not providers.'),
  ('en.sahih', 15, 21, 'And there is not a thing but that with Us are its depositories, and We do not send it down except according to a known measure.'),
  ('en.sahih', 15, 22, 'And We have sent the fertilizing winds and sent down water from the sky and given you drink from it. And you are not its retainers.'),
  ('en.sahih', 15, 23, 'And indeed, it is We who give life and cause death, and We are the Inheritor.'),
  ('en.sahih', 15, 24, 'And We have already known the preceding [generations] among you, and We have already known the later [ones to come].'),
  ('en.sahih', 15, 25, 'And indeed, your Lord will gather them; indeed, He is Wise and Knowing.'),
  ('en.sahih', 15, 26, 'And We did certainly create man out of clay from an altered black mud.'),
  ('en.sahih', 15, 27, 'And the jinn We created before from scorching fire.'),
  ('en.sahih', 15, 28, 'And [mention, O Muhammad], when your Lord said to the angels, "I will create a human being out of clay from an altered black mud.'),
  ('en.sahih', 15, 29, 'And when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."'),
  ('en.sahih', 15, 30, 'So the angels prostrated - all of them entirely,'),
  ('en.sahih', 15, 31, 'Except Iblees, he refused to be with those who prostrated.'),
  ('en.sahih', 15, 32, '[Allah] said, O Iblees, what is [the matter] with you that you are not with those who prostrate?"'),
  ('en.sahih', 15, 33, 'He said, "Never would I prostrate to a human whom You created out of clay from an altered black mud."'),
  ('en.sahih', 15, 34, '[Allah] said, "Then get out of it, for indeed, you are expelled.'),
  ('en.sahih', 15, 35, 'And indeed, upon you is the curse until the Day of Recompense."'),
  ('en.sahih', 15, 36, 'He said, "My Lord, then reprieve me until the Day they are resurrected."'),
  ('en.sahih', 15, 37, '[Allah] said, "So indeed, you are of those reprieved'),
  ('en.sahih', 15, 38, 'Until the Day of the time well-known."'),
  ('en.sahih', 15, 39, '[Iblees] said, "My Lord, because You have put me in error, I will surely make [disobedience] attractive to them on earth, and I will mislead them all'),
  ('en.sahih', 15, 40, 'Except, among them, Your chosen servants."'),
  ('en.sahih', 15, 41, '[Allah] said, "This is a path [of return] to Me [that is] straight.'),
  ('en.sahih', 15, 42, 'Indeed, My servants - no authority will you have over them, except those who follow you of the deviators.'),
  ('en.sahih', 15, 43, 'And indeed, Hell is the promised place for them all.'),
  ('en.sahih', 15, 44, 'It has seven gates; for every gate is of them a portion designated."'),
  ('en.sahih', 15, 45, 'Indeed, the righteous will be within gardens and springs.'),
  ('en.sahih', 15, 46, '[Having been told], "Enter it in peace, safe [and secure]."'),
  ('en.sahih', 15, 47, 'And We will remove whatever is in their breasts of resentment, [so they will be] brothers, on thrones facing each other.'),
  ('en.sahih', 15, 48, 'No fatigue will touch them therein, nor from it will they [ever] be removed.'),
  ('en.sahih', 15, 49, '[O Muhammad], inform My servants that it is I who am the Forgiving, the Merciful.'),
  ('en.sahih', 15, 50, 'And that it is My punishment which is the painful punishment.'),
  ('en.sahih', 15, 51, 'And inform them about the guests of Abraham,'),
  ('en.sahih', 15, 52, 'When they entered upon him and said, "Peace." [Abraham] said, "Indeed, we are fearful of you."'),
  ('en.sahih', 15, 53, '[The angels] said, "Fear not. Indeed, we give you good tidings of a learned boy."'),
  ('en.sahih', 15, 54, 'He said, "Have you given me good tidings although old age has come upon me? Then of what [wonder] do you inform?"'),
  ('en.sahih', 15, 55, 'They said, "We have given you good tidings in truth, so do not be of the despairing."'),
  ('en.sahih', 15, 56, 'He said, "And who despairs of the mercy of his Lord except for those astray?"'),
  ('en.sahih', 15, 57, '[Abraham] said, "Then what is your business [here], O messengers?"'),
  ('en.sahih', 15, 58, 'They said, "Indeed, we have been sent to a people of criminals,'),
  ('en.sahih', 15, 59, 'Except the family of Lot; indeed, we will save them all'),
  ('en.sahih', 15, 60, 'Except his wife." Allah decreed that she is of those who remain behind.'),
  ('en.sahih', 15, 61, 'And when the messengers came to the family of Lot,'),
  ('en.sahih', 15, 62, 'He said, "Indeed, you are people unknown."'),
  ('en.sahih', 15, 63, 'They said, "But we have come to you with that about which they were disputing,'),
  ('en.sahih', 15, 64, 'And we have come to you with truth, and indeed, we are truthful.'),
  ('en.sahih', 15, 65, 'So set out with your family during a portion of the night and follow behind them and let not anyone among you look back and continue on to where you are commanded."'),
  ('en.sahih', 15, 66, 'And We conveyed to him [the decree] of that matter: that those [sinners] would be eliminated by early morning.'),
  ('en.sahih', 15, 67, 'And the people of the city came rejoicing.'),
  ('en.sahih', 15, 68, '[Lot] said, "Indeed, these are my guests, so do not shame me.'),
  ('en.sahih', 15, 69, 'And fear Allah and do not disgrace me."'),
  ('en.sahih', 15, 70, 'They said, "Have we not forbidden you from [protecting] people?"'),
  ('en.sahih', 15, 71, '[Lot] said, "These are my daughters - if you would be doers [of lawful marriage]."'),
  ('en.sahih', 15, 72, 'By your life, [O Muhammad], indeed they were, in their intoxication, wandering blindly.'),
  ('en.sahih', 15, 73, 'So the shriek seized them at sunrise.'),
  ('en.sahih', 15, 74, 'And We made the highest part [of the city] its lowest and rained upon them stones of hard clay.'),
  ('en.sahih', 15, 75, 'Indeed in that are signs for those who discern.'),
  ('en.sahih', 15, 76, 'And indeed, those cities are [situated] on an established road.'),
  ('en.sahih', 15, 77, 'Indeed in that is a sign for the believers.'),
  ('en.sahih', 15, 78, 'And the companions of the thicket were [also] wrongdoers.'),
  ('en.sahih', 15, 79, 'So We took retribution from them, and indeed, both [cities] are on a clear highway.'),
  ('en.sahih', 15, 80, 'And certainly did the companions of Thamud deny the messengers.'),
  ('en.sahih', 15, 81, 'And We gave them Our signs, but from them they were turning away.'),
  ('en.sahih', 15, 82, 'And they used to carve from the mountains, houses, feeling secure.'),
  ('en.sahih', 15, 83, 'But the shriek seized them at early morning.'),
  ('en.sahih', 15, 84, 'So nothing availed them [from] what they used to earn.'),
  ('en.sahih', 15, 85, 'And We have not created the heavens and earth and that between them except in truth. And indeed, the Hour is coming; so forgive with gracious forgiveness.'),
  ('en.sahih', 15, 86, 'Indeed, your Lord - He is the Knowing Creator.'),
  ('en.sahih', 15, 87, 'And We have certainly given you, [O Muhammad], seven of the often repeated [verses] and the great Qur\'an.'),
  ('en.sahih', 15, 88, 'Do not extend your eyes toward that by which We have given enjoyment to [certain] categories of the disbelievers, and do not grieve over them. And lower your wing to the believers'),
  ('en.sahih', 15, 89, 'And say, "Indeed, I am the clear warner" -'),
  ('en.sahih', 15, 90, 'Just as We had revealed [scriptures] to the separators'),
  ('en.sahih', 15, 91, 'Who have made the Qur\'an into portions.'),
  ('en.sahih', 15, 92, 'So by your Lord, We will surely question them all'),
  ('en.sahih', 15, 93, 'About what they used to do.'),
  ('en.sahih', 15, 94, 'Then declare what you are commanded and turn away from the polytheists.'),
  ('en.sahih', 15, 95, 'Indeed, We are sufficient for you against the mockers'),
  ('en.sahih', 15, 96, 'Who make [equal] with Allah another deity. But they are going to know.'),
  ('en.sahih', 15, 97, 'And We already know that your breast is constrained by what they say.'),
  ('en.sahih', 15, 98, 'So exalt [Allah] with praise of your Lord and be of those who prostrate [to Him].'),
  ('en.sahih', 15, 99, 'And worship your Lord until there comes to you the certainty (death).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 15, 1, 'আলিফ-লা-ম-রা; এগুলো পরিপূর্ণ গ্রন্থ ও সুস্পষ্ট কোরআনের আয়াত।'),
  ('bn.bengali', 15, 2, 'কোন সময় কাফেররা আকাঙ্ক্ষা করবে যে, কি চমৎকার হত, যদি তারা মুসলমান হত।'),
  ('bn.bengali', 15, 3, 'আপনি ছেড়ে দিন তাদেরকে, খেয়ে নিক এবং ভোগ করে নিক এবং আশায় ব্যাপৃত থাকুক। অতি সত্বর তারা জেনে নেবে।'),
  ('bn.bengali', 15, 4, 'আমি কোন জনপদ ধবংস করিনি; কিন্ত তার নির্দিষ্ট সময় লিখিত ছিল।'),
  ('bn.bengali', 15, 5, 'কোন সম্প্রদায় তার নির্দিষ্ট সময়ের অগ্রে যায় না এবং পশ্চাতে থাকে না।'),
  ('bn.bengali', 15, 6, 'তারা বললঃ হে ঐ ব্যক্তি, যার প্রতি কোরআন নাযিল হয়েছে, আপনি তো একজন উম্মাদ।'),
  ('bn.bengali', 15, 7, 'যদি আপনি সত্যবাদী হন, তবে আমাদের কাছে ফেরেশতাদেরকে আনেন না কেন?'),
  ('bn.bengali', 15, 8, 'আমি ফেরেশতাদেরকে একমাত্র ফায়সালার জন্যেই নাযিল করি। তখন তাদেরকে অবকাশ দেয়া হবে না।'),
  ('bn.bengali', 15, 9, 'আমি স্বয়ং এ উপদেশ গ্রন্থ অবতারণ করেছি এবং আমি নিজেই এর সংরক্ষক।'),
  ('bn.bengali', 15, 10, 'আমি আপনার পূর্বে পূর্ববর্তী সম্প্রদায়ের মধ্যে রসূল প্রেরণ করেছি।'),
  ('bn.bengali', 15, 11, 'ওদের কাছে এমন কোন রসূল আসেননি, যাদের সাথে ওরা ঠাট্টাবিদ্রূপ করতে থাকেনি।'),
  ('bn.bengali', 15, 12, 'এমনিভাবে আমি এ ধরনের আচরণ পাপীদের অন্তরে বদ্ধমূল করে দেই।'),
  ('bn.bengali', 15, 13, 'ওরা এর প্রতি বিশ্বাস করবে না। পূর্ববর্তীদের এমন রীতি চলে আসছে।'),
  ('bn.bengali', 15, 14, 'যদি আমি ওদের সামনে আকাশের কোন দরজাও খুলে দেই আর তাতে ওরা দিনভর আরোহণ ও করতে থাকে।'),
  ('bn.bengali', 15, 15, 'তবুও ওরা একথাই বলবে যে, আমাদের দৃষ্টির বিভ্রাট ঘটানো হয়েছে না বরং আমরা যাদুগ্রস্ত হয়ে পড়েছি।'),
  ('bn.bengali', 15, 16, 'নিশ্চয় আমি আকাশে রাশিচক্র সৃষ্টি করেছি এবং তাকে দর্শকদের জন্যে সুশোভিত করে দিয়েছি।'),
  ('bn.bengali', 15, 17, 'আমি আকাশকে প্রত্যেক বিতাড়িত শয়তান থেকে নিরাপদ করে দিয়েছি।'),
  ('bn.bengali', 15, 18, 'কিন্তু যে চুরি করে শুনে পালায়, তার পশ্চাদ্ধাবন করে উজ্জ্বল উল্কাপিন্ড।'),
  ('bn.bengali', 15, 19, 'আমি ভু-পৃষ্ঠকে বিস্তৃত করেছি এবং তার উপর পর্বতমালা স্থাপন করেছি এবং তাতে প্রত্যেক বস্তু সুপরিমিতভাবে উৎপন্ন করেছি।'),
  ('bn.bengali', 15, 20, 'আমি তোমাদের জন্যে তাতে জীবিকার উপকরন সৃষ্টি করছি এবং তাদের জন্যেও যাদের অন্নদাতা তোমরা নও।'),
  ('bn.bengali', 15, 21, 'আমার কাছে প্রত্যেক বস্তুর ভান্ডার রয়েছে। আমি নির্দিষ্ট পরিমানেই তা অবতরণ করি।'),
  ('bn.bengali', 15, 22, 'আমি বৃষ্টিগর্ভ বায়ু পরিচালনা করি অতঃপর আকাশ থেকে পানি বর্ষণ করি, এরপর তোমাদেরকে তা পান করাই। বস্তুতঃ তোমাদের কাছে এর ভান্ডার নেই।'),
  ('bn.bengali', 15, 23, 'আমিই জীবনদান করি, মৃত্যুদান করি এবং আমিই চুড়ান্ত মালিকানার অধিকারী।'),
  ('bn.bengali', 15, 24, 'আমি জেনে রেখেছি তোমাদের অগ্রগামীদেরকে এবং আমি জেনে রেখেছি পশ্চাদগামীদেরকে।'),
  ('bn.bengali', 15, 25, 'আপনার পালনকর্তাই তাদেরকে একত্রিত করে আনবেন। নিশ্চয় তিনি প্রজ্ঞাবান, জ্ঞানময়।'),
  ('bn.bengali', 15, 26, 'আমি মানবকে পচা কর্দম থেকে তৈরী বিশুস্ক ঠনঠনে মাটি দ্বারা সৃষ্টি করেছি।'),
  ('bn.bengali', 15, 27, 'এবং জিনকে এর আগে লু এর আগুনের দ্বারা সৃজিত করেছি।'),
  ('bn.bengali', 15, 28, 'আর আপনার পালনকর্তা যখন ফেরেশতাদেরকে বললেনঃ আমি পচা কর্দম থেকে তৈরী বিশুষ্ক ঠনঠনে মাটি দ্বারা সৃষ্ট একটি মানব জাতির পত্তন করব।'),
  ('bn.bengali', 15, 29, 'অতঃপর যখন তাকে ঠিকঠাক করে নেব এবং তাতে আমার রূহ থেকে ফঁুক দেব, তখন তোমরা তার সামনে সেজদায় পড়ে যেয়ো।'),
  ('bn.bengali', 15, 30, 'তখন ফেরেশতারা সবাই মিলে সেজদা করল।'),
  ('bn.bengali', 15, 31, 'কিন্তু ইবলীস-সে সেজদাকারীদের অন্তর্ভূক্ত হতে স্বীকৃত হল না।'),
  ('bn.bengali', 15, 32, 'আল্লাহ বললেনঃ হে ইবলিস, তোমার কি হলো যে তুমি সেজদাকারীদের অন্তর্ভূক্ত হতে স্বীকৃত হলে না?'),
  ('bn.bengali', 15, 33, 'বললঃ আমি এমন নই যে, একজন মানবকে সেজদা করব, যাকে আপনি পচা কর্দম থেকে তৈরী ঠনঠনে বিশুষ্ক মাটি দ্বারা সৃষ্টি করেছেন।'),
  ('bn.bengali', 15, 34, 'আল্লাহ বললেনঃ তবে তুমি এখান থেকে বের হয়ে যাও। তুমি বিতাড়িত।'),
  ('bn.bengali', 15, 35, 'এবং তোমার প্রতি ন্যায় বিচারের দিন পর্যন্ত অভিসম্পাত।'),
  ('bn.bengali', 15, 36, 'সে বললঃ হে আমার পালনকর্তা, আপনি আমাকে পুনরুত্থান দিবস পর্যন্ত অবকাশ দিন।'),
  ('bn.bengali', 15, 37, 'আল্লাহ বললেনঃ তোমাকে অবকাশ দেয়া হল।'),
  ('bn.bengali', 15, 38, 'সেই অবধারিত সময় উপস্থিত হওয়ার দিন পর্যন্ত।'),
  ('bn.bengali', 15, 39, 'সে বললঃ হে আমার পলনকর্তা, আপনি যেমন আমাকে পথ ভ্রষ্ট করেছেন, আমিও তাদের সবাইকে পৃথিবীতে নানা সৌন্দর্যে আকৃষ্ট করব এবং তাদের সবাইকে পথ ভ্রষ্ঠ করে দেব।'),
  ('bn.bengali', 15, 40, 'আপনার মনোনীত বান্দাদের ব্যতীত।'),
  ('bn.bengali', 15, 41, 'আল্লাহ বললেনঃ এটা আমা পর্যন্ত সোজা পথ।'),
  ('bn.bengali', 15, 42, 'যারা আমার বান্দা, তাদের উপর তোমার কোন ক্ষমতা নেই; কিন্তু পথভ্রান্তদের মধ্য থেকে যারা তোমার পথে চলে।'),
  ('bn.bengali', 15, 43, 'তাদের সবার নির্ধারিত স্থান হচ্ছে জাহান্নাম।'),
  ('bn.bengali', 15, 44, 'এর সাতটি দরজা আছে। প্রত্যেক দরজার জন্যে এক একটি পৃথক দল আছে।'),
  ('bn.bengali', 15, 45, 'নিশ্চয় খোদাভীরুরা বাগান ও নির্ঝরিনীসহূহে থাকবে।'),
  ('bn.bengali', 15, 46, 'বলা হবেঃ এগুলোতে নিরাপত্তা ও শান্তি সহকরে প্রবেশ কর।'),
  ('bn.bengali', 15, 47, 'তাদের অন্তরে যে ক্রোধ ছিল, আমি তা দূর করে দেব। তারা ভাই ভাইয়ের মত সামনা-সামনি আসনে বসবে।'),
  ('bn.bengali', 15, 48, 'সেখানে তাদের মোটেই কষ্ট হবে না এবং তারা সেখান থেকে বহিস্কৃত হবে না।'),
  ('bn.bengali', 15, 49, 'আপনি আমার বান্দাদেরকে জানিয়ে দিন যে, আমি অত্যন্ত ক্ষমাশীল দয়ালু।'),
  ('bn.bengali', 15, 50, 'এবং ইহাও যে, আমার শাস্তিই যন্ত্রনাদায়ক শাস্তি।'),
  ('bn.bengali', 15, 51, 'আপনি তাদেরকে ইব্রাহীমের মেহমানদের অবস্থা শুনিয়ে দিন।'),
  ('bn.bengali', 15, 52, 'যখন তারা তাঁর গৃহে আগমন করল এবং বললঃ সালাম। তিনি বললেনঃ আমরা তোমাদের ব্যাপারে ভীত।'),
  ('bn.bengali', 15, 53, 'তারা বললঃ ভয় করবেন না। আমরা আপনাকে একজন জ্ঞানবান ছেলে-সন্তানের সুসংবাদ দিচ্ছি।'),
  ('bn.bengali', 15, 54, 'তিনি বললেনঃ তোমরা কি আমাকে এমতাবস্থায় সুসংবাদ দিচ্ছ, যখন আমি বার্ধক্যে পৌছে গেছি ?'),
  ('bn.bengali', 15, 55, 'তারা বললঃ আমরা আপনাকে সত্য সু-সংবাদ দিচ্ছি! অতএব আপনি নিরাশ হবেন না।'),
  ('bn.bengali', 15, 56, 'তিনি বললেনঃ পালনকর্তার রহমত থেকে পথভ্রষ্টরা ছাড়া কে নিরাশ হয় ?'),
  ('bn.bengali', 15, 57, 'তিনি বললেনঃ অতঃপর তোমাদের প্রধান উদ্দেশ্য কি হে আল্লাহর প্রেরিতগণ ?'),
  ('bn.bengali', 15, 58, 'তারা বললঃ আমরা একটি অপরাধী সম্প্রদায়ের প্রতি প্রেরিত হয়েছি।'),
  ('bn.bengali', 15, 59, 'কিন্তু লূতের পরিবার-পরিজন। আমরা অবশ্যই তাদের সবাইকে বাঁচিয়ে নেব।'),
  ('bn.bengali', 15, 60, 'তবে তার স্ত্রী। আমরা স্থির করেছি যে, সে থেকে যাওয়াদের দলভূক্ত হবে।'),
  ('bn.bengali', 15, 61, 'অতঃপর যখন প্রেরিতরা লূতের গৃহে পৌছল।'),
  ('bn.bengali', 15, 62, 'তিনি বললেনঃ তোমরা তো অপরিচিত লোক।'),
  ('bn.bengali', 15, 63, 'তারা বললঃ না বরং আমরা আপনার কাছে ঐ বস্তু নিয়ে এসেছি, যে সম্পর্কে তারা বিবাদ করত।'),
  ('bn.bengali', 15, 64, 'এবং আমরা আপনার কাছে সত্য বিষয় নিয়ে এসেছি এবং আমরা সত্যবাদী।'),
  ('bn.bengali', 15, 65, 'অতএব আপনি শেষরাত্রে পরিবারের সকলকে নিয়ে চলে যান এবং আপনি তাদের পশ্চাদনুসরণ করবেন না এবং আপনাদের মধ্যে কেউ যেন পিছন ফিরে না দেখে। আপনারা যেখানে আদেশ প্রাপ্ত হচ্ছেন সেখানে যান।'),
  ('bn.bengali', 15, 66, 'আমি লূতকে এ বিষয় পরিজ্ঞাত করে দেই যে, সকাল হলেই তাদেরকে সমুলে বিনাশ করে দেয়া হবে।'),
  ('bn.bengali', 15, 67, 'শহরবাসীরা আনন্দ-উল্লাস করতে করতে পৌছল।'),
  ('bn.bengali', 15, 68, 'লূত বললেনঃ তারা আমার মেহমান। অতএব আমাকে লাঞ্ছিত করো না।'),
  ('bn.bengali', 15, 69, 'তোমরা আল্লাহকে ভয় কর এবং আমার ইযযত নষ্ট করো না।'),
  ('bn.bengali', 15, 70, 'তার বললঃ আমরা কি আপনাকে জগৎদ্বাসীর সমর্থন করতে নিষেধ করিনি।'),
  ('bn.bengali', 15, 71, 'তিনি বললেনঃ যদি তোমরা একান্ত কিছু করতেই চাও, তবে আমার কন্যারা উপস্থিত আছে।'),
  ('bn.bengali', 15, 72, 'আপনার প্রাণের কসম, তারা আপন নেশায় প্রমত্ত ছিল।'),
  ('bn.bengali', 15, 73, 'অতঃপর সুর্যোদয়ের সময় তাদেরকে প্রচন্ড একটি শব্দ এসে পাকড়াও করল।'),
  ('bn.bengali', 15, 74, 'অতঃপর আমি জনপদটিকে উল্টে দিলাম এবং তাদের উপর কঙ্করের প্রস্থর বর্ষণ করলাম।'),
  ('bn.bengali', 15, 75, 'নিশ্চয় এতে চিন্তাশীলদের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 15, 76, 'জনপদটি সোজা পথে অবস্থিত রয়েছে।'),
  ('bn.bengali', 15, 77, 'নিশ্চয় এতে ঈমানদারদের জন্যে নিদর্শণ আছে।'),
  ('bn.bengali', 15, 78, 'নিশ্চয় গহীন বনের অধিবাসীরা পাপী ছিল।'),
  ('bn.bengali', 15, 79, 'অতঃপর আমি তাদের কাছ থেকে প্রতিশোধ নিয়েছি। উভয় বস্তি প্রকাশ্য রাস্তার উপর অবস্থিত।'),
  ('bn.bengali', 15, 80, 'নিশ্চয় হিজরের বাসিন্দারা পয়গম্বরগণের প্রতি মিথ্যারোপ করেছে।'),
  ('bn.bengali', 15, 81, 'আমি তাদেরকে নিজের নিদর্শনাবলী দিয়েছি। অতঃপর তারা এগুলো থেকে মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 15, 82, 'তারা পাহাড়ে নিশ্চিন্তে ঘর খোদাই করত।'),
  ('bn.bengali', 15, 83, 'অতঃপর এক প্রত্যুষে তাদের উপর একটা শব্দ এসে আঘাত করল।'),
  ('bn.bengali', 15, 84, 'তখন কোন উপকারে আসল না যা তারা উপার্জন করেছিল।'),
  ('bn.bengali', 15, 85, 'আমি নভোমন্ডল, ভুমন্ডল এবং এতদুভয়ের মধ্যবর্তী যা আছে তা তাৎপর্যহীন সৃষ্টি করিনি। কেয়ামত অবশ্যই আসবে। অতএব পরম ঔদাসীন্যের সাথে ওদের ক্রিয়াকর্ম উপক্ষো করুন।'),
  ('bn.bengali', 15, 86, 'নিশ্চয় আপনার পালনকর্তাই স্রষ্টা, সর্বজ্ঞ।'),
  ('bn.bengali', 15, 87, 'আমি আপনাকে সাতটি বার বার পঠিতব্য আয়াত এবং মহান কোরআন দিয়েছি।'),
  ('bn.bengali', 15, 88, 'আপনি চক্ষু তুলে ঐ বস্তুর প্রতি দেখবেন না, যা আমি তাদের মধ্যে কয়েক প্রকার লোককে ভোগ করার জন্যে দিয়েছি, তাদের জন্যে চিন্তিত হবেন না আর ঈমানদারদের জন্যে স্বীয় বাহু নত করুন।'),
  ('bn.bengali', 15, 89, 'আর বলুনঃ আমি প্রকাশ্য ভয় প্রদর্শক।'),
  ('bn.bengali', 15, 90, 'যেমন আমি নাযিল করেছি যারা বিভিন্ন মতে বিভক্ত তাদের উপর।'),
  ('bn.bengali', 15, 91, 'যারা কোরআনকে খন্ড খন্ড করেছে।'),
  ('bn.bengali', 15, 92, 'অতএব আপনার পালনকর্তার কসম, আমি অবশ্যই ওদের সবাইকে জিজ্ঞাসাবাদ করব।'),
  ('bn.bengali', 15, 93, 'ওদের কাজকর্ম সম্পর্কে।'),
  ('bn.bengali', 15, 94, 'অতএব আপনি প্রকাশ্যে শুনিয়ে দিন যা আপনাকে আদেশ করা হয় এবং মুশরিকদের পরওয়া করবেন না।'),
  ('bn.bengali', 15, 95, 'বিদ্রুপকারীদের জন্যে আমি আপনার পক্ষ থেকে যথেষ্ট।'),
  ('bn.bengali', 15, 96, 'যারা আল্লাহর সাথে অন্য উপাস্য সাব্যস্ত করে। অতএব অতিসত্তর তারা জেনে নেবে।'),
  ('bn.bengali', 15, 97, 'আমি জানি যে আপনি তাদের কথাবর্তায় হতোদ্যম হয়ে পড়েন।'),
  ('bn.bengali', 15, 98, 'অতএব আপনি পালনকর্তার সৌন্দর্য স্মরণ করুন এবং সেজদাকারীদের অন্তর্ভূক্ত হয়ে যান।'),
  ('bn.bengali', 15, 99, 'এবং পালনকর্তার এবাদত করুন, যে পর্যন্ত আপনার কাছে নিশ্চিত কথা না আসে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 15, 1, 'Alif. Lam. Ra. These are verses of the Scripture and a plain Reading.'),
  ('en.pickthall', 15, 2, 'It may be that those who disbelieve wish ardently that they were Muslims.'),
  ('en.pickthall', 15, 3, 'Let them eat and enjoy life, and let (false) hope beguile them. They will come to know!'),
  ('en.pickthall', 15, 4, 'And We destroyed no township but there was a known decree for it.'),
  ('en.pickthall', 15, 5, 'No nation can outstrip its term nor can they lag behind.'),
  ('en.pickthall', 15, 6, 'And they say: O thou unto whom the Reminder is revealed, lo! thou art indeed a madman!'),
  ('en.pickthall', 15, 7, 'Why bringest thou not angels unto us, if thou art of the truthful?'),
  ('en.pickthall', 15, 8, 'We send not down the angels save with the Fact, and in that case (the disbelievers) would not be tolerated.'),
  ('en.pickthall', 15, 9, 'Lo! We, even We, reveal the Reminder, and lo! We verily are its Guardian.'),
  ('en.pickthall', 15, 10, 'We verily sent (messengers) before thee among the factions of the men of old.'),
  ('en.pickthall', 15, 11, 'And never came there unto them a messenger but they did mock him.'),
  ('en.pickthall', 15, 12, 'Thus do We make it traverse the hearts of the guilty:'),
  ('en.pickthall', 15, 13, 'They believe not therein, though the example of the men of old hath gone before.'),
  ('en.pickthall', 15, 14, 'And even if We opened unto them a gate of heaven and they kept mounting through it,'),
  ('en.pickthall', 15, 15, 'They would say: Our sight is wrong - nay, but we are folk bewitched.'),
  ('en.pickthall', 15, 16, 'And verily in the heaven we have set mansions of the stars, and We have beautified it for beholders.'),
  ('en.pickthall', 15, 17, 'And We have guarded it from every outcast devil,'),
  ('en.pickthall', 15, 18, 'Save him who stealeth the hearing, and them doth a clear flame pursue.'),
  ('en.pickthall', 15, 19, 'And the earth have We spread out, and placed therein firm hills, and caused each seemly thing to grow therein.'),
  ('en.pickthall', 15, 20, 'And we have given unto you livelihoods therein, and unto those for whom ye provide not.'),
  ('en.pickthall', 15, 21, 'And there is not a thing but with Us are the stores thereof. And we send it not down save in appointed measure.'),
  ('en.pickthall', 15, 22, 'And We send the winds fertilising, and cause water to descend from the sky, and give it you to drink. It is not ye who are the holders of the store thereof.'),
  ('en.pickthall', 15, 23, 'Lo! and it is We, even We, Who quicken and give death, and We are the Inheritor.'),
  ('en.pickthall', 15, 24, 'And verily We know the eager among you and verily We know the laggards.'),
  ('en.pickthall', 15, 25, 'Lo! thy Lord will gather them together. Lo! He is Wise, Aware.'),
  ('en.pickthall', 15, 26, 'Verily We created man of potter\'s clay of black mud altered,'),
  ('en.pickthall', 15, 27, 'And the jinn did We create aforetime of essential fire.'),
  ('en.pickthall', 15, 28, 'And (remember) when thy Lord said unto the angels: Lo! I am creating a mortal out of potter\'s clay of black mud altered,'),
  ('en.pickthall', 15, 29, 'So, when I have made him and have breathed into him of My Spirit, do ye fall down, prostrating yourselves unto him.'),
  ('en.pickthall', 15, 30, 'So the angels fell prostrate, all of them together'),
  ('en.pickthall', 15, 31, 'Save Iblis. He refused to be among the prostrate.'),
  ('en.pickthall', 15, 32, 'He said: O Iblis! What aileth thee that thou art not among the prostrate?'),
  ('en.pickthall', 15, 33, 'He said: I am not one to prostrate myself unto a mortal whom Thou hast created out of potter\'s clay of black mud altered!'),
  ('en.pickthall', 15, 34, 'He said: Then go thou forth from hence, for lo! thou art outcast.'),
  ('en.pickthall', 15, 35, 'And lo! the curse shall be upon thee till the Day of Judgment.'),
  ('en.pickthall', 15, 36, 'He said: My Lord! Reprieve me till the day when they are raised.'),
  ('en.pickthall', 15, 37, 'He said: Then lo! thou art of those reprieved'),
  ('en.pickthall', 15, 38, 'Till the Day of appointed time.'),
  ('en.pickthall', 15, 39, 'He said: My Lord! Because Thou hast sent me astray, I verily shall adorn the path of error for them in the earth, and shall mislead them every one,'),
  ('en.pickthall', 15, 40, 'Save such of them as are Thy perfectly devoted slaves.'),
  ('en.pickthall', 15, 41, 'He said: This is a right course incumbent upon Me:'),
  ('en.pickthall', 15, 42, 'Lo! as for My slaves, thou hast no power over any of them save such of the froward as follow thee,'),
  ('en.pickthall', 15, 43, 'And lo! for all such, hell will be the promised place.'),
  ('en.pickthall', 15, 44, 'It hath seven gates, and each gate hath an appointed portion.'),
  ('en.pickthall', 15, 45, 'Lo! those who ward off (evil) are among gardens and watersprings.'),
  ('en.pickthall', 15, 46, '(And it is said unto them): Enter them in peace, secure.'),
  ('en.pickthall', 15, 47, 'And We remove whatever rancour may be in their breasts. As brethren, face to face, (they rest) on couches raised.'),
  ('en.pickthall', 15, 48, 'Toil cometh not unto them there, nor will they be expelled from thence.'),
  ('en.pickthall', 15, 49, 'Announce, (O Muhammad) unto My slaves that verily I am the Forgiving, the Merciful,'),
  ('en.pickthall', 15, 50, 'And that My doom is the dolorous doom.'),
  ('en.pickthall', 15, 51, 'And tell them of Abraham\'s guests,'),
  ('en.pickthall', 15, 52, '(How) when they came in unto him, and said: Peace. He said: Lo! we are afraid of you.'),
  ('en.pickthall', 15, 53, 'They said: Be not afraid! Lo! we bring thee good tidings of a boy possessing wisdom.'),
  ('en.pickthall', 15, 54, 'He said: Bring ye me good tidings (of a son) when old age hath overtaken me? Of what then can ye bring good tidings?'),
  ('en.pickthall', 15, 55, 'They said: We bring thee good tidings in truth. So be not thou of the despairing.'),
  ('en.pickthall', 15, 56, 'He said: And who despaireth of the mercy of his Lord save those who are astray?'),
  ('en.pickthall', 15, 57, 'He said: And afterward what is your business, O ye messengers (of Allah)?'),
  ('en.pickthall', 15, 58, 'They said: We have been sent unto a guilty folk,'),
  ('en.pickthall', 15, 59, '(All) save the family of Lot. Them we shall deliver every one,'),
  ('en.pickthall', 15, 60, 'Except his wife, of whom We had decreed that she should be of those who stay behind.'),
  ('en.pickthall', 15, 61, 'And when the messengers came unto the family of Lot,'),
  ('en.pickthall', 15, 62, 'He said: Lo! ye are folk unknown (to me).'),
  ('en.pickthall', 15, 63, 'They said: Nay, but we bring thee that concerning which they keep disputing,'),
  ('en.pickthall', 15, 64, 'And bring thee the Truth, and lo! we are truth-tellers.'),
  ('en.pickthall', 15, 65, 'So travel with thy household in a portion of the night, and follow thou their backs. Let none of you turn round, but go whither ye are commanded.'),
  ('en.pickthall', 15, 66, 'And We made plain the case to him, that the root of them (who did wrong) was to be cut at early morn.'),
  ('en.pickthall', 15, 67, 'And the people of the city came, rejoicing at the news (of new arrivals).'),
  ('en.pickthall', 15, 68, 'He said: Lo! they are my guests. Affront me not!'),
  ('en.pickthall', 15, 69, 'And keep your duty to Allah, and shame me not!'),
  ('en.pickthall', 15, 70, 'They said; Have we not forbidden you from (entertaining) anyone?'),
  ('en.pickthall', 15, 71, 'He said: Here are my daughters, if ye must be doing (so).'),
  ('en.pickthall', 15, 72, 'By thy life (O Muhammad) they moved blindly in the frenzy of approaching death.'),
  ('en.pickthall', 15, 73, 'Then the (Awful) Cry overtook them at the sunrise.'),
  ('en.pickthall', 15, 74, 'And We utterly confounded them, and We rained upon them stones of heated clay.'),
  ('en.pickthall', 15, 75, 'Lo! therein verily are portents for those who read the signs.'),
  ('en.pickthall', 15, 76, 'And lo! it is upon a road still uneffaced.'),
  ('en.pickthall', 15, 77, 'Lo! therein is indeed a portent for believers.'),
  ('en.pickthall', 15, 78, 'And the dwellers in the wood indeed were evil-doers.'),
  ('en.pickthall', 15, 79, 'So we took vengeance on them; and lo! they both are on a high-road plain to see.'),
  ('en.pickthall', 15, 80, 'And the dwellers in Al-Hijr denied (Our) messengers.'),
  ('en.pickthall', 15, 81, 'And we gave them Our revelations, but they were averse to them.'),
  ('en.pickthall', 15, 82, 'And they used to hew out dwellings from the hills, (wherein they dwelt) secure.'),
  ('en.pickthall', 15, 83, 'But the (Awful) Cry overtook them at the morning hour,'),
  ('en.pickthall', 15, 84, 'And that which they were wont to count as gain availed them not.'),
  ('en.pickthall', 15, 85, 'We created not the heavens and the earth and all that is between them save with truth, and lo! the Hour is surely coming. So forgive, (O Muhammad), with a gracious forgiveness.'),
  ('en.pickthall', 15, 86, 'Lo! Thy Lord! He is the All-Wise Creator.'),
  ('en.pickthall', 15, 87, 'We have given thee seven of the oft-repeated (verses) and the great Qur\'an.'),
  ('en.pickthall', 15, 88, 'Strain not thine eyes toward that which We cause some wedded pairs among them to enjoin, and be not grieved on their account, and lower thy wing (in tenderness) for the believers.'),
  ('en.pickthall', 15, 89, 'And say: Lo! I, even I, am a plain warner,'),
  ('en.pickthall', 15, 90, 'Such as We send down for those who make division,'),
  ('en.pickthall', 15, 91, 'Those who break the Qur\'an into parts.'),
  ('en.pickthall', 15, 92, 'Them, by thy Lord, We shall question, every one,'),
  ('en.pickthall', 15, 93, 'Of what they used to do.'),
  ('en.pickthall', 15, 94, 'So proclaim that which thou art commanded, and withdraw from the idolaters.'),
  ('en.pickthall', 15, 95, 'Lo! We defend thee from the scoffers,'),
  ('en.pickthall', 15, 96, 'Who set some other god along with Allah. But they will come to know.'),
  ('en.pickthall', 15, 97, 'Well know We that thy bosom is oppressed by what they say,'),
  ('en.pickthall', 15, 98, 'But hymn the praise of thy Lord, and be of those who make prostration (unto Him).'),
  ('en.pickthall', 15, 99, 'And serve thy Lord till the Inevitable cometh unto thee.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 15, 1, 'A. L. R. These are the Ayats of Revelation,- of a Qur\'an that makes things clear.'),
  ('en.yusufali', 15, 2, 'Again and again will those who disbelieve, wish that they had bowed (to Allah\'s will) in Islam.'),
  ('en.yusufali', 15, 3, 'Leave them alone, to enjoy (the good things of this life) and to please themselves: let (false) hope amuse them: soon will knowledge (undeceive them).'),
  ('en.yusufali', 15, 4, 'Never did We destroy a population that had not a term decreed and assigned beforehand.'),
  ('en.yusufali', 15, 5, 'Neither can a people anticipate its term, nor delay it.'),
  ('en.yusufali', 15, 6, 'They say: "O thou to whom the Message is being revealed! truly thou art mad (or possessed)!'),
  ('en.yusufali', 15, 7, '"Why bringest thou not angels to us if it be that thou hast the Truth?"'),
  ('en.yusufali', 15, 8, 'We send not the angels down except for just cause: if they came (to the ungodly), behold! no respite would they have!'),
  ('en.yusufali', 15, 9, 'We have, without doubt, sent down the Message; and We will assuredly guard it (from corruption).'),
  ('en.yusufali', 15, 10, 'We did send messengers before thee amongst the religious sects of old:'),
  ('en.yusufali', 15, 11, 'But never came a messenger to them but they mocked him.'),
  ('en.yusufali', 15, 12, 'Even so do we let it creep into the hearts of the sinners -'),
  ('en.yusufali', 15, 13, 'That they should not believe in the (Message); but the ways of the ancients have passed away.'),
  ('en.yusufali', 15, 14, 'Even if We opened out to them a gate from heaven, and they were to continue (all day) ascending therein,'),
  ('en.yusufali', 15, 15, 'They would only say: "Our eyes have been intoxicated: Nay, we have been bewitched by sorcery."'),
  ('en.yusufali', 15, 16, 'It is We Who have set out the zodiacal signs in the heavens, and made them fair-seeming to (all) beholders;'),
  ('en.yusufali', 15, 17, 'And (moreover) We have guarded them from every cursed devil:'),
  ('en.yusufali', 15, 18, 'But any that gains a hearing by stealth, is pursued by a flaming fire, bright (to see).'),
  ('en.yusufali', 15, 19, 'And the earth We have spread out (like a carpet); set thereon mountains firm and immovable; and produced therein all kinds of things in due balance.'),
  ('en.yusufali', 15, 20, 'And We have provided therein means of subsistence,- for you and for those for whose sustenance ye are not responsible.'),
  ('en.yusufali', 15, 21, 'And there is not a thing but its (sources and) treasures (inexhaustible) are with Us; but We only send down thereof in due and ascertainable measures.'),
  ('en.yusufali', 15, 22, 'And We send the fecundating winds, then cause the rain to descend from the sky, therewith providing you with water (in abundance), though ye are not the guardians of its stores.'),
  ('en.yusufali', 15, 23, 'And verily, it is We Who give life, and Who give death: it is We Who remain inheritors (after all else passes away).'),
  ('en.yusufali', 15, 24, 'To Us are known those of you who hasten forward, and those who lag behind.'),
  ('en.yusufali', 15, 25, 'Assuredly it is thy Lord Who will gather them together: for He is perfect in Wisdom and Knowledge.'),
  ('en.yusufali', 15, 26, 'We created man from sounding clay, from mud moulded into shape;'),
  ('en.yusufali', 15, 27, 'And the Jinn race, We had created before, from the fire of a scorching wind.'),
  ('en.yusufali', 15, 28, 'Behold! thy Lord said to the angels: "I am about to create man, from sounding clay from mud moulded into shape;'),
  ('en.yusufali', 15, 29, '"When I have fashioned him (in due proportion) and breathed into him of My spirit, fall ye down in obeisance unto him."'),
  ('en.yusufali', 15, 30, 'So the angels prostrated themselves, all of them together:'),
  ('en.yusufali', 15, 31, 'Not so Iblis: he refused to be among those who prostrated themselves.'),
  ('en.yusufali', 15, 32, '(Allah) said: "O Iblis! what is your reason for not being among those who prostrated themselves?"'),
  ('en.yusufali', 15, 33, '(Iblis) said: "I am not one to prostrate myself to man, whom Thou didst create from sounding clay, from mud moulded into shape."'),
  ('en.yusufali', 15, 34, '(Allah) said: "Then get thee out from here; for thou art rejected, accursed.'),
  ('en.yusufali', 15, 35, '"And the curse shall be on thee till the day of Judgment."'),
  ('en.yusufali', 15, 36, '(Iblis) said: "O my Lord! give me then respite till the Day the (dead) are raised."'),
  ('en.yusufali', 15, 37, '(Allah) said: "Respite is granted thee'),
  ('en.yusufali', 15, 38, '"Till the Day of the Time appointed."'),
  ('en.yusufali', 15, 39, '(Iblis) said: "O my Lord! because Thou hast put me in the wrong, I will make (wrong) fair-seeming to them on the earth, and I will put them all in the wrong,-'),
  ('en.yusufali', 15, 40, '"Except Thy servants among them, sincere and purified (by Thy Grace)."'),
  ('en.yusufali', 15, 41, '(Allah) said: "This (way of My sincere servants) is indeed a way that leads straight to Me.'),
  ('en.yusufali', 15, 42, '"For over My servants no authority shalt thou have, except such as put themselves in the wrong and follow thee."'),
  ('en.yusufali', 15, 43, 'And verily, Hell is the promised abode for them all!'),
  ('en.yusufali', 15, 44, 'To it are seven gates: for each of those gates is a (special) class (of sinners) assigned.'),
  ('en.yusufali', 15, 45, 'The righteous (will be) amid gardens and fountains (of clear-flowing water).'),
  ('en.yusufali', 15, 46, '(Their greeting will be): "Enter ye here in peace and security."'),
  ('en.yusufali', 15, 47, 'And We shall remove from their hearts any lurking sense of injury: (they will be) brothers (joyfully) facing each other on thrones (of dignity).'),
  ('en.yusufali', 15, 48, 'There no sense of fatigue shall touch them, nor shall they (ever) be asked to leave.'),
  ('en.yusufali', 15, 49, 'Tell My servants that I am indeed the Oft-forgiving, Most Merciful;'),
  ('en.yusufali', 15, 50, 'And that My Penalty will be indeed the most grievous Penalty.'),
  ('en.yusufali', 15, 51, 'Tell them about the guests of Abraham.'),
  ('en.yusufali', 15, 52, 'When they entered his presence and said, "Peace!" He said, "We feel afraid of you!"'),
  ('en.yusufali', 15, 53, 'They said: "Fear not! We give thee glad tidings of a son endowed with wisdom."'),
  ('en.yusufali', 15, 54, 'He said: "Do ye give me glad tidings that old age has seized me? Of what, then, is your good news?"'),
  ('en.yusufali', 15, 55, 'They said: "We give thee glad tidings in truth: be not then in despair!"'),
  ('en.yusufali', 15, 56, 'He said: "And who despairs of the mercy of his Lord, but such as go astray?"'),
  ('en.yusufali', 15, 57, 'Abraham said: "What then is the business on which ye (have come), O ye messengers (of Allah)?"'),
  ('en.yusufali', 15, 58, 'They said: "We have been sent to a people (deep) in sin,'),
  ('en.yusufali', 15, 59, '"Excepting the adherents of Lut: them we are certainly (charged) to save (from harm),- All -'),
  ('en.yusufali', 15, 60, '"Except his wife, who, We have ascertained, will be among those who will lag behind."'),
  ('en.yusufali', 15, 61, 'At length when the messengers arrived among the adherents of Lut,'),
  ('en.yusufali', 15, 62, 'He said: "Ye appear to be uncommon folk."'),
  ('en.yusufali', 15, 63, 'They said: "Yea, we have come to thee to accomplish that of which they doubt.'),
  ('en.yusufali', 15, 64, '"We have brought to thee that which is inevitably due, and assuredly we tell the truth.'),
  ('en.yusufali', 15, 65, '"Then travel by night with thy household, when a portion of the night (yet remains), and do thou bring up the rear: let no one amongst you look back, but pass on whither ye are ordered."'),
  ('en.yusufali', 15, 66, 'And We made known this decree to him, that the last remnants of those (sinners) should be cut off by the morning.'),
  ('en.yusufali', 15, 67, 'The inhabitants of the city came in (mad) joy (at news of the young men).'),
  ('en.yusufali', 15, 68, 'Lut said: "These are my guests: disgrace me not:'),
  ('en.yusufali', 15, 69, '"But fear Allah, and shame me not."'),
  ('en.yusufali', 15, 70, 'They said: "Did we not forbid thee (to speak) for all and sundry?"'),
  ('en.yusufali', 15, 71, 'He said: "There are my daughters (to marry), if ye must act (so)."'),
  ('en.yusufali', 15, 72, 'Verily, by thy life (O Prophet), in their wild intoxication, they wander in distraction, to and fro.'),
  ('en.yusufali', 15, 73, 'But the (mighty) Blast overtook them before morning,'),
  ('en.yusufali', 15, 74, 'And We turned (the cities) upside down, and rained down on them brimstones hard as baked clay.'),
  ('en.yusufali', 15, 75, 'Behold! in this are Signs for those who by tokens do understand.'),
  ('en.yusufali', 15, 76, 'And the (cities were) right on the high-road.'),
  ('en.yusufali', 15, 77, 'Behold! in this is a sign for those who believed.'),
  ('en.yusufali', 15, 78, 'And the Companions of the Wood were also wrong-doers;'),
  ('en.yusufali', 15, 79, 'So We exacted retribution from them. They were both on an open highway, plain to see.'),
  ('en.yusufali', 15, 80, 'The Companions of the Rocky Tract also rejected the messengers:'),
  ('en.yusufali', 15, 81, 'We sent them Our Signs, but they persisted in turning away from them.'),
  ('en.yusufali', 15, 82, 'Out of the mountains did they hew (their) edifices, (feeling themselves) secure.'),
  ('en.yusufali', 15, 83, 'But the (mighty) Blast seized them of a morning,'),
  ('en.yusufali', 15, 84, 'And of no avail to them was all that they did (with such art and care)!'),
  ('en.yusufali', 15, 85, 'We created not the heavens, the earth, and all between them, but for just ends. And the Hour is surely coming (when this will be manifest). So overlook (any human faults) with gracious forgiveness.'),
  ('en.yusufali', 15, 86, 'For verily it is thy Lord who is the Master-Creator, knowing all things.'),
  ('en.yusufali', 15, 87, 'And We have bestowed upon thee the Seven Oft-repeated (verses) and the Grand Qur\'an.'),
  ('en.yusufali', 15, 88, 'Strain not thine eyes. (Wistfully) at what We have bestowed on certain classes of them, nor grieve over them: but lower thy wing (in gentleness) to the believers.'),
  ('en.yusufali', 15, 89, 'And say: "I am indeed he that warneth openly and without ambiguity,"-'),
  ('en.yusufali', 15, 90, '(Of just such wrath) as We sent down on those who divided (Scripture into arbitrary parts),-'),
  ('en.yusufali', 15, 91, '(So also on such) as have made Qur\'an into shreds (as they please).'),
  ('en.yusufali', 15, 92, 'Therefore, by the Lord, We will, of a surety, call them to account,'),
  ('en.yusufali', 15, 93, 'For all their deeds.'),
  ('en.yusufali', 15, 94, 'Therefore expound openly what thou art commanded, and turn away from those who join false gods with Allah.'),
  ('en.yusufali', 15, 95, 'For sufficient are We unto thee against those who scoff,-'),
  ('en.yusufali', 15, 96, 'Those who adopt, with Allah, another god: but soon will they come to know.'),
  ('en.yusufali', 15, 97, 'We do indeed know how thy heart is distressed at what they say.'),
  ('en.yusufali', 15, 98, 'But celebrate the praises of thy Lord, and be of those who prostrate themselves in adoration.'),
  ('en.yusufali', 15, 99, 'And serve thy Lord until there come unto thee the Hour that is Certain.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 15, 1, 'Alif-Laaam-Raa; tilka Aayaatul Kitaabi wa Qur-aa-nim Mubeen'),
  ('en.transliteration', 15, 2, 'Rubamaa yawaddul lazeena kafaroo law kaanoo muslimeen'),
  ('en.transliteration', 15, 3, 'Zarhum yaakuloo wa tatamatta\'oo wa yulhihimul amalu fasawfa ya\'lamoon'),
  ('en.transliteration', 15, 4, 'Wa maaa ahlaknaa min qaryatin illaa wa lahaa kitaabum ma\'loom'),
  ('en.transliteration', 15, 5, 'Maa tasbiqu min ummatin ajalahaa wa maa yastaakhiroon'),
  ('en.transliteration', 15, 6, 'Wa qaaloo yaaa aiyuhal lazee nuzzila \'alaihiz Zikru innaka lamajnoon'),
  ('en.transliteration', 15, 7, 'Law maa taateenaa bil malaaa\'ikati in kunta minas saadiqeen'),
  ('en.transliteration', 15, 8, 'Maa nunazzilul malaaa\'i kata illaa bilhaqqi wa maa kaanooo izam munzareen'),
  ('en.transliteration', 15, 9, 'Innaa Nahnu nazalnaz Zikra wa Innaa lahoo lahaa fizoon'),
  ('en.transliteration', 15, 10, 'Wa laqad arsalnaa min qablika fee shiya\'il awwaleen'),
  ('en.transliteration', 15, 11, 'Wa maa yaateehim mir Rasoolin illaa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 15, 12, 'kazaalika naslukuhoo fee quloobil mujrimeen'),
  ('en.transliteration', 15, 13, 'Laa yu\'minoona bihee wa qad khalat sunnatul awwaleen'),
  ('en.transliteration', 15, 14, 'Wa law fatahnaa \'alaihim baabam minas samaaa\'i fazaloo feehi ya\'rujoon'),
  ('en.transliteration', 15, 15, 'Laqaaloo innamaa sukkirat absaarunaa bal nahnu qawmum mashooroon'),
  ('en.transliteration', 15, 16, 'Wa laqad ja\'alnaa fissamaaa\'i buroojanw wa zaiyannaahaa linnaazireen'),
  ('en.transliteration', 15, 17, 'Wa hafiznaahaa min kulli Shaitaanir rajeem'),
  ('en.transliteration', 15, 18, 'Illaa manis taraqas sam\'a fa atba\'ahoo shihaabum mubeen'),
  ('en.transliteration', 15, 19, 'Wal arda madadnaahaa wa alqainaa feehaa rawaasiya wa ambatnaa feehaa min kulli shai\'im mawzoon'),
  ('en.transliteration', 15, 20, 'Wa ja\'alnaa lakum feehaa ma\'aayisha wa mal lastum lahoo biraaziqeen'),
  ('en.transliteration', 15, 21, 'Wa im min shai\'in illaa \'indanaa khazaaa \'inuhoo wa maa nunazziluhooo illaa biqadarim ma\'loom'),
  ('en.transliteration', 15, 22, 'Wa arsalnar riyaaha la waaqiha fa anzalnaa minas samaaa\'i maaa\'an fa asqai naakumoohu wa maaa antum lahoo bikhaazineen'),
  ('en.transliteration', 15, 23, 'Wa innnaa la nahnu nuhyee wa numeetu wa nahnul waarisoon'),
  ('en.transliteration', 15, 24, 'Wa la qad \'alimnal mustaqdimeena minkum wa laqad \'alimnal mustaakhireen'),
  ('en.transliteration', 15, 25, 'Wa inna Rabbaka Huwa yahshuruhum; innahoo Hakeem \'Aleem'),
  ('en.transliteration', 15, 26, 'Wa laqad khalaqnal insaana min salsaalim min hama im masnoon'),
  ('en.transliteration', 15, 27, 'Waljaaanna khalaqnaahu min qablu min naaris samoom'),
  ('en.transliteration', 15, 28, 'Wa iz qaala Rabbuka lilmalaaa\' ikati innee khaaliqum basharam min salsaalim min hama im masnoon'),
  ('en.transliteration', 15, 29, 'Fa izaa sawwaituhoo wa nafakhtu feehi mir roohee faqa\'oo lahoo saajideen'),
  ('en.transliteration', 15, 30, 'Fasajadal malaaa\'ikatu kulluhum ajma\'oon'),
  ('en.transliteration', 15, 31, 'Illaaa ibleesa abaaa ai yakoona ma\'as saajideen'),
  ('en.transliteration', 15, 32, 'Qaala yaaa Ibleesu maa laka allaa takoona ma\'as saajideen'),
  ('en.transliteration', 15, 33, 'Qaala lam akul li asjuda libasharin khalaqtahoo min salsaalim min hama im masnoon'),
  ('en.transliteration', 15, 34, 'Qaala fakhruj minhaa fa innaka rajeem'),
  ('en.transliteration', 15, 35, 'Wa inna \'alikal la\'nata ilaa Yawmid Deen'),
  ('en.transliteration', 15, 36, 'Qaala Rabbi fa anzirneee ilaa Yawmi yub\'asoon'),
  ('en.transliteration', 15, 37, 'Qaala fa innaka minal munzareen'),
  ('en.transliteration', 15, 38, 'Ilaa Yawmil waqtil ma\'loom'),
  ('en.transliteration', 15, 39, 'Qaala Rabbi bimaaa aghwaitanee la uzayyinaana lahum fil ardi wa la ughwiyan nahum ajma\'een'),
  ('en.transliteration', 15, 40, 'Illaa \'ibaadaka minhumul mukhlaseen'),
  ('en.transliteration', 15, 41, 'Qaala haaza Siraatun \'alaiya Mustaqeem'),
  ('en.transliteration', 15, 42, 'Inna \'ibaadee laisa laka \'alaihim sultaanun illaa manittaba\'aka minal ghaaween'),
  ('en.transliteration', 15, 43, 'Wa inna jahannama lamaw\'iduhum ajma\'een'),
  ('en.transliteration', 15, 44, 'Lahaa sab\'atu abwaab; likulli baabim minhum juz\'um maqsoom'),
  ('en.transliteration', 15, 45, 'Innal muttaqeena fee Jannaatinw wa \'uyoon'),
  ('en.transliteration', 15, 46, 'Udkhuloohaa bisalaamin aamineen'),
  ('en.transliteration', 15, 47, 'Wa naza\'naa ma fee sudoorihim min ghillin ikhwaanan \'alaa sururim mutaqaabileen'),
  ('en.transliteration', 15, 48, 'Laa yamas suhum feehaa nasabunw wa maa hum minhaa bimukhrajeen'),
  ('en.transliteration', 15, 49, 'Nabbi\' \'ibaadeee annneee anal Ghafoorur Raheem'),
  ('en.transliteration', 15, 50, 'Wa anna \'azaabee uwal \'azaabul aleem'),
  ('en.transliteration', 15, 51, 'Wa nabbi\'hum \'an daifi Ibraaheem'),
  ('en.transliteration', 15, 52, 'Iz dakhaloo \'alaihi faqaaloo salaaman qaala innaa minkum wajiloon'),
  ('en.transliteration', 15, 53, 'Qaaloo la tawjal innaa nubashshiruka bighulaamin \'aleem'),
  ('en.transliteration', 15, 54, 'Qaala abashshartumoonee \'alaaa am massaniyal kibaru fabima tubashshiroon'),
  ('en.transliteration', 15, 55, 'Qaaloo bashsharnaaka bilhaqqi falaa takum minal qaaniteen'),
  ('en.transliteration', 15, 56, 'Qaala wa mai yaqnatu mir rahmati Rabbiheee illad daaaloon'),
  ('en.transliteration', 15, 57, 'Qaala famaa khatbukum aiyuhal mursaloon'),
  ('en.transliteration', 15, 58, 'Qaaloo innaaa ursilnaaa ilaa qawmim mujrimeen'),
  ('en.transliteration', 15, 59, 'Illaaa Aala Loot; innaa lamunajjoohum ajma\'een'),
  ('en.transliteration', 15, 60, 'Illam ra atahoo qaddarnaaa innahaa laminal ghaabireen'),
  ('en.transliteration', 15, 61, 'Falamma jaaa\'a Aala Lootinil mursaloon'),
  ('en.transliteration', 15, 62, 'Qaala innakum qawmum munkaroon'),
  ('en.transliteration', 15, 63, 'Qaaloo bal ji\'naaka bimaa kaanoo feehi yamtaroon'),
  ('en.transliteration', 15, 64, 'Wa atainaaka bilhaqqi wa innaa lasaadiqoon'),
  ('en.transliteration', 15, 65, 'Fa asri bi ahlika biqit\'im minal laili wattabi\' adbaarahum wa laa yaltafit minkum ahadunw wamdoo haisu tu\'maroon'),
  ('en.transliteration', 15, 66, 'Wa qadainaaa ilaihi zaalikal amra anna daabira haaa\'ulaaa\'i maqtoo\'um musbiheen'),
  ('en.transliteration', 15, 67, 'Wa jaaa\'a ahlul madeenati yastabshiroon'),
  ('en.transliteration', 15, 68, 'Qaala inna haaa\'ulaaa\'i daifee falaa tafdahoon'),
  ('en.transliteration', 15, 69, 'Wattaqul laaha wa laa tukhzoon'),
  ('en.transliteration', 15, 70, 'Qaalooo awalam nanhaka \'anil \'aalameen'),
  ('en.transliteration', 15, 71, 'Qaala haaa\'ulaaa\'i banaateee in kuntum faa\'ileen'),
  ('en.transliteration', 15, 72, 'La\'amruka innahum lafee sakratihim ya\'mahoon'),
  ('en.transliteration', 15, 73, 'Fa akhazat humus saihatu mushriqeen'),
  ('en.transliteration', 15, 74, 'Faja\'alnaa \'aaliyahaa saafilahaa wa amtamaa \'alaihim hijaaratam min sjijjeel'),
  ('en.transliteration', 15, 75, 'Inna fee zaalika la Aayaatil lilmutawassimeen'),
  ('en.transliteration', 15, 76, 'Wa innahaa labi sabeelim muqeem'),
  ('en.transliteration', 15, 77, 'Inna fee zaalika la Aayatal lilmu\'mineen'),
  ('en.transliteration', 15, 78, 'Wa in kaana Ashaabul Aikati lazaalimeen'),
  ('en.transliteration', 15, 79, 'Fantaqamnaa minhum wa innahumaa labi imaamim mubeen'),
  ('en.transliteration', 15, 80, 'Wa laqad kazzaba ashaabul Hijril mursaleen'),
  ('en.transliteration', 15, 81, 'Wa aatainaahum Aayaatinaa fakaanoo \'anhaa mu\'rideen'),
  ('en.transliteration', 15, 82, 'Wa kaanoo yanhitoona minal jibaali buyootan aamineen'),
  ('en.transliteration', 15, 83, 'Fa akhazat humus saihatu musbiheen'),
  ('en.transliteration', 15, 84, 'Famaaa aghnaa \'anhum maa kaanoo yaksiboon'),
  ('en.transliteration', 15, 85, 'Wa maa khalaqnas samaawaati wal arda wa maa bainahumaaa illaa bilhaqq; wa innas Saa\'ata la aatiyatun fasfahis safhal jameel'),
  ('en.transliteration', 15, 86, 'Inna Rabbaka Huwal khallaaqul \'aleem'),
  ('en.transliteration', 15, 87, 'Wa laqad aatainaaka sab\'am mnal masaanee wal Qur-aanal \'azeem'),
  ('en.transliteration', 15, 88, 'Laa tamuddanna \'ainaika ilaa maa matta \'naa biheee azwaajam minhum wa laa tahzan \'alaihim wakhfid janaahaka lilmu \'mineen'),
  ('en.transliteration', 15, 89, 'Wa qul inneee anan nazeerul mubeen'),
  ('en.transliteration', 15, 90, 'Kamaaa anzalnaa \'alal muqtasimeen'),
  ('en.transliteration', 15, 91, 'Allazeena ja\'alul Quraana\'ideen'),
  ('en.transliteration', 15, 92, 'Fawa Rabbika lanas\'a lannahum ajma\'een'),
  ('en.transliteration', 15, 93, '\'Ammaa kaanoo ya\'maloon'),
  ('en.transliteration', 15, 94, 'Fasda\' bimaa tu\'maru wa a\'rid anil mushrikeen'),
  ('en.transliteration', 15, 95, 'Innaa kafainaakal mustahzi\'een'),
  ('en.transliteration', 15, 96, 'Allazeena yaj\'aloona ma\'al laahi ilaahan aakhar; fasawfa ya\'lamoon'),
  ('en.transliteration', 15, 97, 'Wa laqad na\'lamu annak yadeequ sadruka bimaa yaqooloon'),
  ('en.transliteration', 15, 98, 'Fasbbih bihamdi Rabbika wa kum minas saajideen'),
  ('en.transliteration', 15, 99, 'Wa\'bud Rabbaka hattaa yaatiyakal yaqeen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 15, 1, 'یہ آیتیں کتاب کی ہیں اور قرآن واضح کی'),
  ('ur.ahmedali', 15, 2, 'کافر بڑی حسرت کریں گے کہ کاش وہ مسلمان ہو جاتے'),
  ('ur.ahmedali', 15, 3, 'انہیں چھوڑ دو کھا لیں اور فائدہ اٹھا لیں اور انہیں آرزو بھلائے رکھے سو آئندہ معلوم کر لیں گے'),
  ('ur.ahmedali', 15, 4, 'اور ہم نے جتنی بستیاں ہلاک کی ہیں ان سب کے لیے ایک مقرر وقت لکھا ہوا تھا'),
  ('ur.ahmedali', 15, 5, 'کوئی قوم اپنے وقت مقرر سے نہ پہلے ہلاک ہوئی ہے نہ پیچھے رہی ہے'),
  ('ur.ahmedali', 15, 6, 'اور انہوں نے کہا اے وہ شخص جس پر قرآن نازل کیا گیا ہے بے شک تو مجنون ہے'),
  ('ur.ahmedali', 15, 7, 'اگر تم سچے ہو تو ہمارے پاس فرشتوں کو کیوں نہیں لاتے'),
  ('ur.ahmedali', 15, 8, 'ہم فرشتہ تو فیصلہ ہی کے لیے بھیجا کرتے ہیں اور اس وقت انہیں مہلت نہیں ملے گی'),
  ('ur.ahmedali', 15, 9, 'ہم نے یہ نصیحت اتار دی ہے اور بے شک ہم اس کے نگہبان ہیں'),
  ('ur.ahmedali', 15, 10, 'اور تجھ سے پہلے ہم پہلی قوموں میں بھی رسول بھیج چکے ہیں'),
  ('ur.ahmedali', 15, 11, 'اور وہ بھی جب کوئی رسول ان کے پاس آتا ہے تو اس سے ٹھٹھا ہی کرتے'),
  ('ur.ahmedali', 15, 12, 'اسی طرح ہم یہ ٹھٹھا ان مجرمو ں کے دلوں میں ڈال دیتے ہیں'),
  ('ur.ahmedali', 15, 13, 'یہ لوگ قرآن پر ایمان نہیں لاتے اور یہ پہلوں کا دستور چلا آیا ہے'),
  ('ur.ahmedali', 15, 14, 'اور اگر ہم ان پر آسمان سے دروازہ کھول دیں پھراس میں سے چڑھ جائیں'),
  ('ur.ahmedali', 15, 15, 'البتہ کہیں گے کہ ہماری نظر بندی کر دی گئی تھی بلکہ ہم پر جادو کیا گیا ہے'),
  ('ur.ahmedali', 15, 16, 'او رالبتہ تحقیق ہم نے آسمان پر برج بنائے ہیں اور دیکھنے والو ں کی نطر میں اسے رونق دی ہے'),
  ('ur.ahmedali', 15, 17, 'اور ہم نے اسے ہرشیطان مردود سے محفوظ رکھا'),
  ('ur.ahmedali', 15, 18, 'مگر جس نے چوری سے سن لیا تو اس کے پیچھے چمکتا ہوا انگارہ پڑا'),
  ('ur.ahmedali', 15, 19, 'اور ہم نے زمین کو پھیلایا اور اس پر پہاڑ رکھ دیے اوراس میں ہر چیز اندازے سے اگائی'),
  ('ur.ahmedali', 15, 20, 'اوراس میں تمہارے لیے روزی کے اسباب بنا دیئے اوران کے لیے بھی جنہیں تم روزی دینے والے نہیں ہو'),
  ('ur.ahmedali', 15, 21, 'او رہر چیز کے ہمارے پاس خزانے ہیں اورہم صرف اسے اندازہ معین پر نازل کرتے ہیں'),
  ('ur.ahmedali', 15, 22, 'اور ہم نے بادل اٹھانے والی ہوائیں بھیجیں پھر ہم نے آسمان سے پانی نازل کیا پھر وہ تمہیں پلایا اور تمہارے پاس اس کا خزانہ نہیں ہے'),
  ('ur.ahmedali', 15, 23, 'اور بے شک ہم ہی زندہ کرتے اور مارتے ہیں اورا خیر مالک بھی ہم ہی ہیں'),
  ('ur.ahmedali', 15, 24, 'اور ہمیں تم میں سے اگلے او رپچھلے سب معلوم کر لیں'),
  ('ur.ahmedali', 15, 25, 'اور بے شک تیرا رب ہی انہیں جمع کرے گا بے شک وہ حکمت والا خبردار ہے'),
  ('ur.ahmedali', 15, 26, 'اور البتہ تحقیق ہم نے انسان کو بجتی ہوئی مٹی سے جو سڑے ہوئے گارے سے تھی پیدا کیا'),
  ('ur.ahmedali', 15, 27, 'اور ہم نے اس سے پہلے جنوں کو آگ کے شعلے سے بنایا تھا'),
  ('ur.ahmedali', 15, 28, 'اور جب تیرے رب نے فرشتوں سے کہا کہ میں ایک بشر کو بجتی ہوئی مٹی سے جو کےسڑے ہوئے گارے کی ہو گی پیدا کرنے والا ہوں'),
  ('ur.ahmedali', 15, 29, 'پھر جب میں اسے ٹھیک بنالوں اور اس میں اپنی روح پھونک دوں تو تم اس کے آگے سجدہ میں گر پڑنا'),
  ('ur.ahmedali', 15, 30, 'پھر سب کے سب فرشتوں نے سجدہ کیا'),
  ('ur.ahmedali', 15, 31, 'مگر ابلیس نے انکار کیا کہ سجدہ کرنے والوں کے ساتھ ہو'),
  ('ur.ahmedali', 15, 32, 'فرمایا اے ابلیس! تجھے کیا ہوا کہ سجدہ کرنے والوں کے ساتھ نہ ہوا'),
  ('ur.ahmedali', 15, 33, 'کہا میں ایسا نہ تھا کہ ایک ایسے بشر کو سجدہ کروں جسے تو نے بجتی ہوئی مٹی سے جو سڑے ہوئے گارے کی تھی پیدا کیا ہے'),
  ('ur.ahmedali', 15, 34, 'کہا تو آسمان سے نکل جا بے شک تو مردود ہو گیا'),
  ('ur.ahmedali', 15, 35, 'اور بے شک تجھ پر قیامت کے دن تک لعنت رہے گی'),
  ('ur.ahmedali', 15, 36, 'کہا اے میرے رب! تو پھر مجھے قیامت کے دن تک مہلت دے'),
  ('ur.ahmedali', 15, 37, 'فرمایا بےشک تجھے مہلت ہے'),
  ('ur.ahmedali', 15, 38, 'وقت معلوم کے دن تک'),
  ('ur.ahmedali', 15, 39, 'کہا اے میرے رب! جیسا تو نے مجھے گمراہ لیا ہے البتہ ضرور ضرور میں زمین میں انہیں ان کے گناہوں کو مرغوب کر کے دکھاؤں گا اور ان سب کو گمراہ کروں گا'),
  ('ur.ahmedali', 15, 40, 'سوائے تیرے ان بندوں کے جو ان میں مخلص ہو ں گے'),
  ('ur.ahmedali', 15, 41, 'فرمایا یہ راستہ مجھ پر سیدھا ہے'),
  ('ur.ahmedali', 15, 42, 'بے شک میرے بندوں پر تیرا کچھ بھی بس نہیں چلے گا مگر جو گمراہوں میں سے تیرا تابعدار ہوا'),
  ('ur.ahmedali', 15, 43, 'اور بے شک ان سب کا وعدہ دوزخ پر ہے'),
  ('ur.ahmedali', 15, 44, 'اس کے سات دروازے ہیں ہر دروازے کے لیے ان کے الگ الگ حصے ہیں'),
  ('ur.ahmedali', 15, 45, 'بے شک پرہیزگار باغوں اور چشموں میں رہیں گے'),
  ('ur.ahmedali', 15, 46, 'ان باغوں میں سلامتی اور امن سے جا کر رہو'),
  ('ur.ahmedali', 15, 47, 'اور ان کے دلوں میں جو کینہ تھا ہم وہ سب دور کر دیں گے سب بھائی بھائی ہوں گے تختوں پر آمنے سامنے بیٹھنے والے ہوں گے'),
  ('ur.ahmedali', 15, 48, 'انہیں وہاں کوئی تکلیف نہیں پہنچے گی اور نہ وہ وہاں سے نکالے جائیں گے'),
  ('ur.ahmedali', 15, 49, 'میرے بندوں کو اطلاع دے کہ بےشک میں بحشنے والا مہربان ہوں'),
  ('ur.ahmedali', 15, 50, 'اور بے شک میرا عذاب وہی دردناک عذاب ہے'),
  ('ur.ahmedali', 15, 51, 'اور انہیں ابراھیم کے مہمانوں کا حال سنا دو'),
  ('ur.ahmedali', 15, 52, 'جب اس کے گھر میں داخل ہوئے اور کہا سلام اس نے کہا بے شک ہمیں تم سے ڈر معلوم ہوتا ہے'),
  ('ur.ahmedali', 15, 53, 'کہا ڈرو مت بے شک ہم تمہیں ایک دن لڑکے کی خوشخبری سناتے ہیں'),
  ('ur.ahmedali', 15, 54, 'کہا مجھے اب بڑھاپے میں خوشخبری سناتے ہو سو کس چیز کی خوشخبری سناتے ہو'),
  ('ur.ahmedali', 15, 55, 'انہوں نے کہا ہم نے تمہیں بھی سچی خوشخبری سنائی ہے سو تو نا امید نہ ہو'),
  ('ur.ahmedali', 15, 56, 'کہا اپنے رب کی رحمت سے نا امید تو گمراہ لوگ ہی ہوا کرتے ہیں'),
  ('ur.ahmedali', 15, 57, 'کہا اے فرشتو! پھر تمہارا کیا مقصد ہے'),
  ('ur.ahmedali', 15, 58, 'انہوں نے کہا ہم ایک نافرمان قوم کی طرف بھیجے گئے ہیں'),
  ('ur.ahmedali', 15, 59, 'مگر لوط کے گھر والے کہ ہم ان سب کو بچا لیں گے'),
  ('ur.ahmedali', 15, 60, 'مگر اس کی بیوی ہم نے فیصلہ کیا ہے کہ وہ پیچھے رہنے والو ں میں سے ہے'),
  ('ur.ahmedali', 15, 61, 'پھر جب لوط کے گھر فرشتے پہنچے'),
  ('ur.ahmedali', 15, 62, 'کہا بے شک تم اجنبی لوگ ہو'),
  ('ur.ahmedali', 15, 63, 'انہوں نے کہا بلکہ ہم تیرے پاس وہ چیز لے کر آئے ہیں جس میں وہ جھگڑتے تھے'),
  ('ur.ahmedali', 15, 64, 'او رہم تیرے پاس پکی بات لائے ہیں اوربے شک ہم سچ کہتے ہیں'),
  ('ur.ahmedali', 15, 65, 'پس تم اپنے گھر والوں کو کچھ رات رہے لے نکلو اور تو ان کے پیچھے چل اور تم میں سے کوئی مڑ کر نہ دیکھے اور چلے جاؤ جہاں تمہیں حکم ہے'),
  ('ur.ahmedali', 15, 66, 'اور ہم نے لوط کو قطعی طور پر یہ بات واضح کر دی تھی کہ صبح ہوتے ہی ان کی جڑ کاٹ دی جائے گی'),
  ('ur.ahmedali', 15, 67, 'اور شہر والے خوشیاں کرتے ہوئے آئے'),
  ('ur.ahmedali', 15, 68, 'لوط نے کہا یہ لوگ میرے مہمان ہیں سو مجھے ذلیل نہ کرو'),
  ('ur.ahmedali', 15, 69, 'اور الله سے ڈرو اور مجھے بے آبرو نہ کرو'),
  ('ur.ahmedali', 15, 70, 'انہوں نے کہا کیاہم نے تمہیں دنیا بھر کی حمایت سے منع نہیں کیا ہے'),
  ('ur.ahmedali', 15, 71, 'کہا یہ میری بیٹیاں حاضر ہیں اگر تم کرنے والے ہو'),
  ('ur.ahmedali', 15, 72, 'تیری جان کی قسم ہے وہ اپنی مستی میں اندھے ہو رہے تھے'),
  ('ur.ahmedali', 15, 73, 'پھر دن نکلتے ہی انہیں ہولناک آواز نے آ لیا'),
  ('ur.ahmedali', 15, 74, 'پھر ہم نے ان بستیوں کو زیرو زبر کر دیا اور ان پر کنکر کے پتھر برسائے'),
  ('ur.ahmedali', 15, 75, 'بے شک اس واقعہ میں اہلِ بصیرت کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 15, 76, 'اور بے شک یہ بستیاں سیدھے راستے پر واقع ہیں'),
  ('ur.ahmedali', 15, 77, 'بے شک اس میں ایمانداروں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 15, 78, 'اوربن کے لوگ بھی بدکار تھے'),
  ('ur.ahmedali', 15, 79, 'پھر ہم نےان سےبھی بدلہ لیا اور یہ دونوں بستیاں کھلے راستہ پر واقع ہیں'),
  ('ur.ahmedali', 15, 80, 'او ربے شک حجر والوں نے رسولوں کو جھٹلایا تھا'),
  ('ur.ahmedali', 15, 81, 'اور ہم نے انہیں اپنی نشانیاں بھی دی تھیں پر وہ ان سے روگردانی کرتے تھے'),
  ('ur.ahmedali', 15, 82, 'او وہ لوگ پہاڑوں کو تراش کر گھر بناتے تھے کہ امن میں رہیں'),
  ('ur.ahmedali', 15, 83, 'پھر انہیں صبح کے وقت سخت آواز نے آ پکڑا'),
  ('ur.ahmedali', 15, 84, 'پھر ان کے دنیاوی ہنر ان کے کچھ بھی کام نہ آئے'),
  ('ur.ahmedali', 15, 85, 'اور ہم نے آسمانوں اور زمین اور ان کی درمیانی چیزوں کو بغیر حکمت کے پیدا نہیں کیا اور قیامت ضرور آنے والی ہے پر تو ان سے خوش خلقی کے ساتھ کنارہ کر'),
  ('ur.ahmedali', 15, 86, 'بے شک تیار رب وہی پیدا کرنے والا جاننے والا ہے'),
  ('ur.ahmedali', 15, 87, 'اور ہم نے تمہیں سات آیتیں دیں جو (نماز میں) دہرائی جاتی ہیں اور قرآن عظمت والا دیا'),
  ('ur.ahmedali', 15, 88, 'اور تو اپنی آنکھ اٹھا کر بھی ان چیزوں کو نہ دیکھ جو ہم نے مختلف قسم کے کافروں کو استعمال کے لیے دے رکھی ہیں اور ان پر غم نہ کر اور اپنے بازو ایمان والوں کے لیے جھکا دے'),
  ('ur.ahmedali', 15, 89, 'اور کہہ دو بے شک میں کھلم کھلا ڈرانے والا ہوں'),
  ('ur.ahmedali', 15, 90, 'جیسا ہم نے (عذاب) ان بانٹنے والو ں پر بھیجا ہے'),
  ('ur.ahmedali', 15, 91, 'جنہوں نے قرآن کو ٹکڑے ٹکڑے کیا ہے'),
  ('ur.ahmedali', 15, 92, 'پھر تیرے رب کی قسم ہے البتہ ہم ان سب سے سوال کریں گے'),
  ('ur.ahmedali', 15, 93, 'اس چیز سے کہ وہ کرتے تھے'),
  ('ur.ahmedali', 15, 94, 'سو تو کھول کر سنا دے جو تجھے حکم دیا گیا ہے اور مشرکوں کی پروا نہ کر'),
  ('ur.ahmedali', 15, 95, 'بے شک ہم تیری طرف سے ٹھٹھا کرنے والوں کے لیے کافی ہیں'),
  ('ur.ahmedali', 15, 96, 'اور جو الله کے ساتھ دوسرا خدا مقرر کرتے ہیں سو عنقریب معلوم کر لیں گے'),
  ('ur.ahmedali', 15, 97, 'اور ہم جانتے ہیں کہ تیرا دل ان باتوں سے تنگ ہوتا ہے جو وہ کہتے ہیں'),
  ('ur.ahmedali', 15, 98, 'سو تو اپنے رب کی تسبیح حمد کے ساتھ کیے جا اور سجدہ کرنے والوں میں سے ہو'),
  ('ur.ahmedali', 15, 99, 'اور اپنے رب کی عبادت کرتے رہو یہاں تک کہ تمہیں موت آجائے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 15, 1, 'Elif, Lam, Ra. Bunlar Kitap\'ın ve apaçık olan Kuran\'ın ayetleridir.'),
  ('tr.diyanet', 15, 2, 'İnkar edenler, keşke müslüman olsaydık temennisinde bulunacaklardır.'),
  ('tr.diyanet', 15, 3, 'Bırak onları yesinler, zevk alsınlar; ümit onları avundursun; ilerde öğrenecekler.'),
  ('tr.diyanet', 15, 4, 'Yok ettiğimiz herhangi bir kasabanın elbette belli bir yazısı vardır.'),
  ('tr.diyanet', 15, 5, 'Hiçbir ümmet kendi süresini öne alamaz, geciktiremez de.'),
  ('tr.diyanet', 15, 6, 'Onlar: "Ey kendisine Kitap indirilen kimse! Sen mutlaka delisin. Doğrulardan isen melekleri bize getirsene" dediler.'),
  ('tr.diyanet', 15, 7, 'Onlar: "Ey kendisine Kitap indirilen kimse! Sen mutlaka delisin. Doğrulardan isen melekleri bize getirsene" dediler.'),
  ('tr.diyanet', 15, 8, 'Biz melekleri ancak gerekince indiririz. O takdirde de ceza görecekler asla geri bırakılmazlar.'),
  ('tr.diyanet', 15, 9, 'Doğrusu Kitap\'ı Biz indirdik, onun koruyucusu elbette Biziz.'),
  ('tr.diyanet', 15, 10, 'And olsun ki, senden önce çeşitli ümmetlere peygamber göndermiştik.'),
  ('tr.diyanet', 15, 11, 'Onlara gelen her peygamberi alaya alıyorlardı.'),
  ('tr.diyanet', 15, 12, 'Aynı şekilde biz de Kitap\'ı suçluların kalblerine sokarız, ama ona yine de inanmazlar. Oysa kendilerinden öncekilerin uğradıkları meydandadır.'),
  ('tr.diyanet', 15, 13, 'Aynı şekilde biz de Kitap\'ı suçluların kalblerine sokarız, ama ona yine de inanmazlar. Oysa kendilerinden öncekilerin uğradıkları meydandadır.'),
  ('tr.diyanet', 15, 14, 'Onlara gökten bir kapı açsak da, oradan çıkmağa koyulsalar: "Gözlerimiz döndü, biz herhalde büyülendik" derler.'),
  ('tr.diyanet', 15, 15, 'Onlara gökten bir kapı açsak da, oradan çıkmağa koyulsalar: "Gözlerimiz döndü, biz herhalde büyülendik" derler.'),
  ('tr.diyanet', 15, 16, 'And olsun ki, gökte burçlar meydana getirdik, onları bakanlar için donattık.'),
  ('tr.diyanet', 15, 17, 'Onları, kovulmuş her şeytandan koruduk.'),
  ('tr.diyanet', 15, 18, 'Fakat kulak hırsızlığı yapan olursa, parlak bir ateş onu kovalar.'),
  ('tr.diyanet', 15, 19, 'Yeri yaydık, oraya sabit dağlar yerleştirdik, orada her şeyi bir ölçüye göre bitirdik.'),
  ('tr.diyanet', 15, 20, 'Orada sizin ve rızık veremeyeceğiniz kimseler için geçimlikler meydana getirdik.'),
  ('tr.diyanet', 15, 21, 'Hazinesi Bizim katımızda olmayan hiçbir şey yoktur. Biz onu ancak belli bir ölçüye göre indiririz.'),
  ('tr.diyanet', 15, 22, 'Rüzgarları aşılayıcı olarak gönderdik; yukarıdan su indirdik de sizi onunla suladık. Yoksa siz onu toplayamazdınız.'),
  ('tr.diyanet', 15, 23, 'Doğrusu dirilten ve öldüren Biziz; hepsinin gerisinde de Biz kalırız.'),
  ('tr.diyanet', 15, 24, 'And olsun ki, sizden önce geçenleri biliriz; and olsun ki, geri kalanları da biliriz.'),
  ('tr.diyanet', 15, 25, 'Doğrusu Rabbin onları diriltip bir araya getirecektir. Şüphesiz O Hakim\'dir, Herşeyi Bilen\'dir.'),
  ('tr.diyanet', 15, 26, 'And olsun ki, insanı kuru balçıktan, işlenebilen kara topraktan yarattık.'),
  ('tr.diyanet', 15, 27, 'Cinleri de, daha önce, dumansız ateşten yarattık.'),
  ('tr.diyanet', 15, 28, '\'Rabbin meleklere: "Ben, balçıktan, işlenebilen kara topraktan bir insan yaratacağım. Onu yapıp ruhumdan üflediğimde ona secdeye kapanın" demişti.'),
  ('tr.diyanet', 15, 29, '\'Rabbin meleklere: "Ben, balçıktan, işlenebilen kara topraktan bir insan yaratacağım. Onu yapıp ruhumdan üflediğimde ona secdeye kapanın" demişti.'),
  ('tr.diyanet', 15, 30, 'Bunun üzerine, İblis\'in dışında bütün melekler hemen secde ettiler. O, secde edenlerle beraber olmaktan çekindi.'),
  ('tr.diyanet', 15, 31, 'Bunun üzerine, İblis\'in dışında bütün melekler hemen secde ettiler. O, secde edenlerle beraber olmaktan çekindi.'),
  ('tr.diyanet', 15, 32, 'Allah: "Ey İblis! Secde edenlerle beraber olmaktan seni alıkoyan nedir?" dedi.'),
  ('tr.diyanet', 15, 33, 'O: "Balçıktan, işlenebilen kara topraktan yarattığın insana secde edemem" dedi.'),
  ('tr.diyanet', 15, 34, '"Öyleyse defol oradan, sen artık kovulmuş birisin. Doğrusu hesap gününe kadar lanet sanadır" dedi.'),
  ('tr.diyanet', 15, 35, '"Öyleyse defol oradan, sen artık kovulmuş birisin. Doğrusu hesap gününe kadar lanet sanadır" dedi.'),
  ('tr.diyanet', 15, 36, '"Rabbim! Beni hiç olmazsa, tekrar dirilecekleri güne kadar ertele" dedi.'),
  ('tr.diyanet', 15, 37, 'Allah: "Sen, bilinen gün gelene kadar bırakılanlardansın" dedi.'),
  ('tr.diyanet', 15, 38, 'Allah: "Sen, bilinen gün gelene kadar bırakılanlardansın" dedi.'),
  ('tr.diyanet', 15, 39, '"Rabbim! Beni saptırdığın için, and olsun ki yeryüzünde fenalıkları onlara güzel göstereceğim; halis kıldığın kulların bir yana, onların hepsini saptıracağım" dedi.'),
  ('tr.diyanet', 15, 40, '"Rabbim! Beni saptırdığın için, and olsun ki yeryüzünde fenalıkları onlara güzel göstereceğim; halis kıldığın kulların bir yana, onların hepsini saptıracağım" dedi.'),
  ('tr.diyanet', 15, 41, '\'Allah şöyle dedi: "Benim gerekli kıldığım dosdoğru yol budur; kullarımın üzerinde senin bir nüfuzun olamaz. Ancak sana uyan sapıklar bunun dışındadır."'),
  ('tr.diyanet', 15, 42, '\'Allah şöyle dedi: "Benim gerekli kıldığım dosdoğru yol budur; kullarımın üzerinde senin bir nüfuzun olamaz. Ancak sana uyan sapıklar bunun dışındadır."'),
  ('tr.diyanet', 15, 43, '"Ve Cehennem onların hepsinin toplanacağı yerdir."'),
  ('tr.diyanet', 15, 44, 'O cehennemin yedi kapısı olup, her kapıdan onların girecekleri ayrılmış bir kısım vardır.'),
  ('tr.diyanet', 15, 45, 'Allah\'a karşı gelmekten sakınanlar ise, cennetlerde, pınar başlarındadırlar.'),
  ('tr.diyanet', 15, 46, '"Oraya güven içinde, esenlikle girin" denilir.'),
  ('tr.diyanet', 15, 47, 'Biz onların gönüllerinde olan kini çıkardık, artık onlar sedirler üzerinde karşılıklı oturan kardeşlerdir.'),
  ('tr.diyanet', 15, 48, 'Onlar orada bir yorgunluk hissetmezler. Oradan çıkarılacak da değillerdir.'),
  ('tr.diyanet', 15, 49, 'Kullarıma Benim bağışlayan, merhamet eden olduğumu, azabımın can yakıcı bir azap olduğunu haber ver.'),
  ('tr.diyanet', 15, 50, 'Kullarıma Benim bağışlayan, merhamet eden olduğumu, azabımın can yakıcı bir azap olduğunu haber ver.'),
  ('tr.diyanet', 15, 51, 'Onlara İbrahim\'in konuklarını da anlat:'),
  ('tr.diyanet', 15, 52, 'İbrahim\'in yanına girdiklerinde selam vermişlerdi. O: "Doğrusu biz sizden korkuyoruz" demişti de: "Korkma, biz sana, bilgin bir oğlun olacağını müjdelemeye geldik" demişlerdi.'),
  ('tr.diyanet', 15, 53, 'İbrahim\'in yanına girdiklerinde selam vermişlerdi. O: "Doğrusu biz sizden korkuyoruz" demişti de: "Korkma, biz sana, bilgin bir oğlun olacağını müjdelemeye geldik" demişlerdi.'),
  ('tr.diyanet', 15, 54, '"Ben kocamışken bana müjde mi veriyorsunuz? Neye dayanarak müjdeliyorsunuz?" deyince:'),
  ('tr.diyanet', 15, 55, '"Seni gerçekten müjdeliyoruz, umutsuzlardan olma" demişlerdi.'),
  ('tr.diyanet', 15, 56, '"Zaten sapıklardan başka kim Rabbinin rahmetinden umudunu keser!" diyerek sormuştu: "Ey elçiler! İşiniz nedir?"'),
  ('tr.diyanet', 15, 57, '"Zaten sapıklardan başka kim Rabbinin rahmetinden umudunu keser!" diyerek sormuştu: "Ey elçiler! İşiniz nedir?"'),
  ('tr.diyanet', 15, 58, 'Şöyle cevap vermişlerdi: "Biz şüphesiz suçlu bir millete gönderildik. Lut\'un ailesi bunun dışındadır. Karısı hariç hepsini kurtaracağız. Karısının geride kalanlardan olmasını gerekli bulduk."'),
  ('tr.diyanet', 15, 59, 'Şöyle cevap vermişlerdi: "Biz şüphesiz suçlu bir millete gönderildik. Lut\'un ailesi bunun dışındadır. Karısı hariç hepsini kurtaracağız. Karısının geride kalanlardan olmasını gerekli bulduk."'),
  ('tr.diyanet', 15, 60, 'Şöyle cevap vermişlerdi: "Biz şüphesiz suçlu bir millete gönderildik. Lut\'un ailesi bunun dışındadır. Karısı hariç hepsini kurtaracağız. Karısının geride kalanlardan olmasını gerekli bulduk."'),
  ('tr.diyanet', 15, 61, 'Elçiler Lut\'un ailesine gelince, Lut: "Doğrusu siz tanınmayan kimselersiniz" dedi.'),
  ('tr.diyanet', 15, 62, 'Elçiler Lut\'un ailesine gelince, Lut: "Doğrusu siz tanınmayan kimselersiniz" dedi.'),
  ('tr.diyanet', 15, 63, '"Biz sana sadece şüphe edip durdukları azabı getirdik. Sana gerçekle geldik. Şüphesiz biz doğru söyleyenleriz. Artık, geceleyin bir ara, aileni yola çıkar, sen de arkalarından git; hiçbiriniz arkaya bakmasın; emrolunduğunuz yere doğru yürüyün" dediler.'),
  ('tr.diyanet', 15, 64, '"Biz sana sadece şüphe edip durdukları azabı getirdik. Sana gerçekle geldik. Şüphesiz biz doğru söyleyenleriz. Artık, geceleyin bir ara, aileni yola çıkar, sen de arkalarından git; hiçbiriniz arkaya bakmasın; emrolunduğunuz yere doğru yürüyün" dediler.'),
  ('tr.diyanet', 15, 65, '"Biz sana sadece şüphe edip durdukları azabı getirdik. Sana gerçekle geldik. Şüphesiz biz doğru söyleyenleriz. Artık, geceleyin bir ara, aileni yola çıkar, sen de arkalarından git; hiçbiriniz arkaya bakmasın; emrolunduğunuz yere doğru yürüyün" dediler.'),
  ('tr.diyanet', 15, 66, 'Böylece Lut\'a bunların sonlarının kesilmiş olarak sabahlıyacaklarını bildirdik.'),
  ('tr.diyanet', 15, 67, 'Şehir halkı, sevinerek geldiler.'),
  ('tr.diyanet', 15, 68, 'Lut: "Bunlar benim konuklarımdır, onlara karşı beni rüsvay etmeyin, Allah\'tan korkun, beni utandırmayın" dedi.'),
  ('tr.diyanet', 15, 69, 'Lut: "Bunlar benim konuklarımdır, onlara karşı beni rüsvay etmeyin, Allah\'tan korkun, beni utandırmayın" dedi.'),
  ('tr.diyanet', 15, 70, '"Biz sana kimseyi misafir kabul etmeyi yasak etmemiş miydik?" dediler.'),
  ('tr.diyanet', 15, 71, 'Lut: "Alacaksanız, işte benim kızlarım" dedi.'),
  ('tr.diyanet', 15, 72, 'Senin hayatına and olsun ki, onlar sarhoşlukları içinde bocalayıp duruyorlardı.'),
  ('tr.diyanet', 15, 73, 'Tanyeri ağarırken, çığlık onları yakalayıverdi.'),
  ('tr.diyanet', 15, 74, 'Memleketlerini alt üst ettik, üzerlerine sert taş yağdırdık.'),
  ('tr.diyanet', 15, 75, 'Bunda, görebilen insanlar için ibretler vardır.'),
  ('tr.diyanet', 15, 76, 'O şehrin kalıntıları işlek yollar üzerinde hala durmaktadır.'),
  ('tr.diyanet', 15, 77, 'Bunda inananlar için ibret vardır.'),
  ('tr.diyanet', 15, 78, 'Eykeliler de, şüphesiz zalim kimselerdi.'),
  ('tr.diyanet', 15, 79, 'Bunun için onlardan da öç aldık. Hala her iki memleket de işlek bir yol üzerindedirler.'),
  ('tr.diyanet', 15, 80, 'And olsun ki, Hicr halkı peygamberi yalanlamışlardı.'),
  ('tr.diyanet', 15, 81, 'Onlara ayetlerimizi verdiğimiz halde, yüz çevirmişlerdi.'),
  ('tr.diyanet', 15, 82, 'Dağlarda, güven içinde olarak evler yontuyorlardı.'),
  ('tr.diyanet', 15, 83, 'Sabaha karşı çığlık onları yakalayıverdi.'),
  ('tr.diyanet', 15, 84, 'Yaptıkları kendilerine bir fayda sağlamadı.'),
  ('tr.diyanet', 15, 85, 'Biz, gökleri, yeri ve her ikisi arasında bulunanları gereğince yarattık. Kıyamet günü şüphesiz gelecektir. O halde yumuşak ve iyi davran.'),
  ('tr.diyanet', 15, 86, 'Doğrusu yaratan ve bilen ancak Rabbindir.'),
  ('tr.diyanet', 15, 87, 'And olsun ki, sana daima tekrarlanan yedi ayetli Fatiha\'yı ve Kuran-ı Azim\'i verdik.'),
  ('tr.diyanet', 15, 88, 'Kafirler içinde bazı kimselere verdiğimiz kat kat servete gözünü dikme, onlara üzülme; inananları kanatların altına al.'),
  ('tr.diyanet', 15, 89, 'De ki: "Doğrusu ben apaçık bir uyarıcıyım."'),
  ('tr.diyanet', 15, 90, 'Kuran\'ı işlerine geldiği gibi bölenlere de, kendi Kitablarının bir kısmına inanıp bir kısmını kabul etmeyen yahudi ve hıristiyanlara da nitekim Kitap indirmiştik; Rabbine and olsun ki hepsini, yaptıklarından sorumlu tutacağız.'),
  ('tr.diyanet', 15, 91, 'Kuran\'ı işlerine geldiği gibi bölenlere de, kendi Kitablarının bir kısmına inanıp bir kısmını kabul etmeyen yahudi ve hıristiyanlara da nitekim Kitap indirmiştik; Rabbine and olsun ki hepsini, yaptıklarından sorumlu tutacağız.'),
  ('tr.diyanet', 15, 92, 'Kuran\'ı işlerine geldiği gibi bölenlere de, kendi Kitablarının bir kısmına inanıp bir kısmını kabul etmeyen yahudi ve hıristiyanlara da nitekim Kitap indirmiştik; Rabbine and olsun ki hepsini, yaptıklarından sorumlu tutacağız.'),
  ('tr.diyanet', 15, 93, 'Kuran\'ı işlerine geldiği gibi bölenlere de, kendi Kitablarının bir kısmına inanıp bir kısmını kabul etmeyen yahudi ve hıristiyanlara da nitekim Kitap indirmiştik; Rabbine and olsun ki hepsini, yaptıklarından sorumlu tutacağız.'),
  ('tr.diyanet', 15, 94, 'Artık buyrulanı açıkça ortaya koy, puta tapanlara aldırış etme.'),
  ('tr.diyanet', 15, 95, 'Allah\'la beraber başka bir tanrının bulunduğunu kabul eden alaycılara karşı şüphesiz Biz sana kafiyiz. Yakında ne olduğunu öğreneceklerdir.'),
  ('tr.diyanet', 15, 96, 'Allah\'la beraber başka bir tanrının bulunduğunu kabul eden alaycılara karşı şüphesiz Biz sana kafiyiz. Yakında ne olduğunu öğreneceklerdir.'),
  ('tr.diyanet', 15, 97, 'And olsun ki, söyledikleri şeylerden senin gönlünün daraldığını biliyoruz.'),
  ('tr.diyanet', 15, 98, 'Rabbini hamd ile an, secde edenlerden ol ve ölünceye kadar Rabbine kulluk et.'),
  ('tr.diyanet', 15, 99, 'Rabbini hamd ile an, secde edenlerden ol ve ölünceye kadar Rabbine kulluk et.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 15, 1, 'Alif, laam, raa. (Surat) ini adalah (sebagian dari) ayat-ayat Al-Kitab (yang sempurna), yaitu (ayat-ayat) Al Quran yang memberi penjelasan.'),
  ('id.indonesian', 15, 2, 'Orang-orang yang kafir itu seringkali (nanti di akhirat) menginginkan, kiranya mereka dahulu (di dunia) menjadi orang-orang muslim.'),
  ('id.indonesian', 15, 3, 'Biarkanlah mereka (di dunia ini) makan dan bersenang-senang dan dilalaikan oleh angan-angan (kosong), maka kelak mereka akan mengetahui (akibat perbuatan mereka).'),
  ('id.indonesian', 15, 4, 'Dan Kami tiada membinasakan sesuatu negeripun, melainkan ada baginya ketentuan masa yang telah ditetapkan.'),
  ('id.indonesian', 15, 5, 'Tidak ada suatu umatpun yang dapat mendahului ajalnya, dan tidak (pula) dapat mengundurkan(nya).'),
  ('id.indonesian', 15, 6, 'Mereka berkata: "Hai orang yang diturunkan Al Quran kepadanya, sesungguhnya kamu benar-benar orang yang gila.'),
  ('id.indonesian', 15, 7, 'Mengapa kamu tidak mendatangkan malaikat kepada kami, jika kamu termasuk orang-orang yang benar?"'),
  ('id.indonesian', 15, 8, 'Kami tidak menurunkan malaikat melainkan dengan benar (untuk membawa azab) dan tiadalah mereka ketika itu diberi tangguh.'),
  ('id.indonesian', 15, 9, 'Sesungguhnya Kami-lah yang menurunkan Al Quran, dan sesungguhnya Kami benar-benar memeliharanya.'),
  ('id.indonesian', 15, 10, 'Dan sesungguhnya Kami telah mengutus (beberapa rasul) sebelum kamu kepada umat-umat yang terdahulu.'),
  ('id.indonesian', 15, 11, 'Dan tidak datang seorang rasulpun kepada mereka, melainkan mereka selalu memperolok-olokkannya.'),
  ('id.indonesian', 15, 12, 'Demikianlah, Kami mamasukkan (rasa ingkar dan memperolok-olokkan itu) kedalam hati orang-orang yang berdosa (orang-orang kafir),'),
  ('id.indonesian', 15, 13, 'mereka tidak beriman kepadanya (Al Quran) dan sesungguhnya telah berlalu sunnatullah terhadap orang-orang dahulu.'),
  ('id.indonesian', 15, 14, 'Dan jika seandainya Kami membukakan kepada mereka salah satu dari (pintu-pintu) langit, lalu mereka terus menerus naik ke atasnya,'),
  ('id.indonesian', 15, 15, 'tentulah mereka berkata: "Sesungguhnya pandangan kamilah yang dikaburkan, bahkan kami adalah orang orang yang kena sihir".'),
  ('id.indonesian', 15, 16, 'Dan sesungguhnya Kami telah menciptakan gugusan bintang-bintang (di langit) dan Kami telah menghiasi langit itu bagi orang-orang yang memandang(nya),'),
  ('id.indonesian', 15, 17, 'dan Kami menjaganya dari tiap-tiap syaitan yang terkutuk,'),
  ('id.indonesian', 15, 18, 'kecuali syaitan yang mencuri-curi (berita) yang dapat didengar (dari malaikat) lalu dia dikejar oleh semburan api yang terang.'),
  ('id.indonesian', 15, 19, 'Dan Kami telah menghamparkan bumi dan menjadikan padanya gunung-gunung dan Kami tumbuhkan padanya segala sesuatu menurut ukuran.'),
  ('id.indonesian', 15, 20, 'Dan Kami telah menjadikan untukmu di bumi keperluan-keperluan hidup, dan (Kami menciptakan pula) makhluk-makhluk yang kamu sekali-kali bukan pemberi rezeki kepadanya.'),
  ('id.indonesian', 15, 21, 'Dan tidak ada sesuatupun melainkan pada sisi Kami-lah khazanahnya; dan Kami tidak menurunkannya melainkan dengan ukuran yang tertentu.'),
  ('id.indonesian', 15, 22, 'Dan Kami telah meniupkan angin untuk mengawinkan (tumbuh-tumbuhan) dan Kami turunkan hujan dari langit, lalu Kami beri minum kamu dengan air itu, dan sekali-kali bukanlah kamu yang menyimpannya.'),
  ('id.indonesian', 15, 23, 'Dan sesungguhnya benar-benar Kami-lah yang menghidupkan dan mematikan dan Kami (pulalah) yang mewarisi.'),
  ('id.indonesian', 15, 24, 'Dan sesungguhnya Kami telah mengetahui orang-orang yang terdahulu daripada-mu dan sesungguhnya Kami mengetahui pula orang-orang yang terkemudian (daripadamu).'),
  ('id.indonesian', 15, 25, 'Sesungguhnya Tuhanmu, Dialah yang akan menghimpunkan mereka. Sesungguhnya Dia adalah Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 15, 26, 'Dan sesungguhnya Kami telah menciptakan manusia (Adam) dari tanah liat kering (yang berasal) dari lumpur hitam yang diberi bentuk.'),
  ('id.indonesian', 15, 27, 'Dan Kami telah menciptakan jin sebelum (Adam) dari api yang sangat panas.'),
  ('id.indonesian', 15, 28, 'Dan (ingatlah), ketika Tuhanmu berfirman kepada para malaikat: "Sesungguhnya Aku akan menciptakan seorang manusia dari tanah liat kering (yang berasal) dari lumpur hitam yang diberi bentuk,'),
  ('id.indonesian', 15, 29, 'Maka apabila Aku telah menyempurnakan kejadiannya, dan telah meniup kan kedalamnya ruh (ciptaan)-Ku, maka tunduklah kamu kepadanya dengan bersujud.'),
  ('id.indonesian', 15, 30, 'Maka bersujudlah para malaikat itu semuanya bersama-sama,'),
  ('id.indonesian', 15, 31, 'kecuali iblis. Ia enggan ikut besama-sama (malaikat) yang sujud itu.'),
  ('id.indonesian', 15, 32, 'Allah berfirman: "Hai iblis, apa sebabnya kamu tidak (ikut sujud) bersama-sama mereka yang sujud itu?"'),
  ('id.indonesian', 15, 33, 'Berkata Iblis: "Aku sekali-kali tidak akan sujud kepada manusia yang Engkau telah menciptakannya dari tanah liat kering (yang berasal) dari lumpur hitam yang diberi bentuk"'),
  ('id.indonesian', 15, 34, 'Allah berfirman: "Keluarlah dari surga, karena sesungguhnya kamu terkutuk,'),
  ('id.indonesian', 15, 35, 'dan sesungguhnya kutukan itu tetap menimpamu sampai hari kiamat".'),
  ('id.indonesian', 15, 36, 'Berkata iblis: "Ya Tuhanku, (kalau begitu) maka beri tangguhlah kepadaku sampai hari (manusia) dibangkitkan,'),
  ('id.indonesian', 15, 37, 'Allah berfirman: "(Kalau begitu) maka sesungguhnya kamu termasuk orang-orang yang diberi tangguh,'),
  ('id.indonesian', 15, 38, 'sampai hari (suatu) waktu yang telah ditentukan,'),
  ('id.indonesian', 15, 39, 'Iblis berkata: "Ya Tuhanku, oleh sebab Engkau telah memutuskan bahwa aku sesat, pasti aku akan menjadikan mereka memandang baik (perbuatan maksiat) di muka bumi, dan pasti aku akan menyesatkan mereka semuanya,'),
  ('id.indonesian', 15, 40, 'kecuali hamba-hamba Engkau yang mukhlis di antara mereka".'),
  ('id.indonesian', 15, 41, 'Allah berfirman: "Ini adalah jalan yang lurus, kewajiban Aku-lah (menjaganya).'),
  ('id.indonesian', 15, 42, 'Sesungguhnya hamba-hamba-Ku tidak ada kekuasaan bagimu terhadap mereka, kecuali orang-orang yang mengikut kamu, yaitu orang-orang yang sesat.'),
  ('id.indonesian', 15, 43, 'Dan sesungguhnya Jahannam itu benar-benar tempat yang telah diancamkan kepada mereka (pengikut-pengikut syaitan) semuanya.'),
  ('id.indonesian', 15, 44, 'Jahannam itu mempunyai tujuh pintu. Tiap-tiap pintu (telah ditetapkan) untuk golongan yang tertentu dari mereka.'),
  ('id.indonesian', 15, 45, 'Sesungguhnya orang-orang yang bertakwa itu berada dalam surga (taman-taman) dan (di dekat) mata air-mata air (yang mengalir).'),
  ('id.indonesian', 15, 46, '(Dikatakan kepada mereka): "Masuklah ke dalamnya dengan sejahtera lagi aman"'),
  ('id.indonesian', 15, 47, 'Dan Kami lenyapkan segala rasa dendam yang berada dalam hati mereka, sedang mereka merasa bersaudara duduk berhadap-hadapan di atas dipan-dipan.'),
  ('id.indonesian', 15, 48, 'Mereka tidak merasa lelah di dalamnya dan mereka sekali-kali tidak akan dikeluarkan daripadanya.'),
  ('id.indonesian', 15, 49, 'Kabarkanlah kepada hamba-hamba-Ku, bahwa sesungguhnya Aku-lah Yang Maha Pengampun lagi Maha Penyayang,'),
  ('id.indonesian', 15, 50, 'dan bahwa sesungguhnya azab-Ku adalah azab yang sangat pedih.'),
  ('id.indonesian', 15, 51, 'Dan kabarkanlah kepada mereka tentang tamu-tamu Ibrahim.'),
  ('id.indonesian', 15, 52, 'Ketika mereka masuk ke tempatnya, lalu mereka mengucapkan: "Salaam". Berkata Ibrahim: "Sesungguhnya kami merasa takut kepadamu".'),
  ('id.indonesian', 15, 53, 'Mereka berkata: "Janganlah kamu merasa takut, sesungguhnya kami memberi kabar gembira kepadamu dengan (kelahiran seorang) anak laki-laki (yang akan menjadi) orang yang alim".'),
  ('id.indonesian', 15, 54, 'Berkata Ibrahim: "Apakah kamu memberi kabar gembira kepadaku padahal usiaku telah lanjut, maka dengan cara bagaimanakah (terlaksananya) berita gembira yang kamu kabarkan ini?"'),
  ('id.indonesian', 15, 55, 'Mereka menjawab: "Kami menyampaikan kabar gembira kepadamu dengan benar, maka janganlah kamu termasuk orang-orang yang berputus asa".'),
  ('id.indonesian', 15, 56, 'Ibrahim berkata: "Tidak ada orang yang berputus asa dari rahmat Tuhan-nya, kecuali orang-orang yang sesat".'),
  ('id.indonesian', 15, 57, 'Berkata (pula) Ibrahim: "Apakah urusanmu yang penting (selain itu), hai para utusan?"'),
  ('id.indonesian', 15, 58, 'Mereka menjawab: "Kami sesungguhnya diutus kepada kaum yang berdosa,'),
  ('id.indonesian', 15, 59, 'kecuali Luth beserta pengikut-pengikutnya. Sesungguhnya Kami akan menyelamatkan mereka semuanya,'),
  ('id.indonesian', 15, 60, 'kecuali istrinya. Kami telah menentukan, bahwa sesungguhnya ia itu termasuk orang-orang yang tertinggal (bersama-sama dengan orang kafir lainnya)".'),
  ('id.indonesian', 15, 61, 'Maka tatkala para utusan itu datang kepada kaum Luth, beserta pengikut pengikutnya,'),
  ('id.indonesian', 15, 62, 'ia berkata: "Sesungguhnya kamu adalah orang-orang yang tidak dikenal".'),
  ('id.indonesian', 15, 63, 'Para utusan menjawab: "Sebenarnya kami ini datang kepadamu dengan membawa azab yang selalu mereka dustakan.'),
  ('id.indonesian', 15, 64, 'Dan kami datang kepadamu membawa kebenaran dan sesungguhnya kami betul-betul orang-orang benar.'),
  ('id.indonesian', 15, 65, 'Maka pergilah kamu di akhir malam dengan membawa keluargamu, dan ikutlah mereka dari belakang dan janganlah seorangpun di antara kamu menoleh kebelakang dan teruskanlah perjalanan ke tempat yang di perintahkan kepadamu".'),
  ('id.indonesian', 15, 66, 'Dan telah Kami wahyukan kepadanya (Luth) perkara itu, yaitu bahwa mereka akan ditumpas habis di waktu subuh.'),
  ('id.indonesian', 15, 67, 'Dan datanglah penduduk kota itu (ke rumah Luth) dengan gembira (karena) kedatangan tamu-tamu itu.'),
  ('id.indonesian', 15, 68, 'Luth berkata: "Sesungguhnya mereka adalah tamuku; maka janganlah kamu memberi malu (kepadaku),'),
  ('id.indonesian', 15, 69, 'dan bertakwalah kepada Allah dan janganlah kamu membuat aku terhina".'),
  ('id.indonesian', 15, 70, 'Mereka berkata: "Dan bukankah kami telah melarangmu dari (melindungi) manusia?"'),
  ('id.indonesian', 15, 71, 'Luth berkata: "Inilah puteri-puteriku (kawinlah dengan mereka), jika kamu hendak berbuat (secara yang halal)".'),
  ('id.indonesian', 15, 72, '(Allah berfirman): "Demi umurmu (Muhammad), sesungguhnya mereka terombang-ambing di dalam kemabukan (kesesatan)".'),
  ('id.indonesian', 15, 73, 'Maka mereka dibinasakan oleh suara keras yang mengguntur, ketika matahari akan terbit.'),
  ('id.indonesian', 15, 74, 'Maka Kami jadikan bahagian atas kota itu terbalik ke bawah dan Kami hujani mereka dengan batu dari tanah yang keras.'),
  ('id.indonesian', 15, 75, 'Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang memperhatikan tanda-tanda.'),
  ('id.indonesian', 15, 76, 'Dan sesungguhnya kota itu benar-benar terletak di jalan yang masih tetap (dilalui manusia).'),
  ('id.indonesian', 15, 77, 'Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang beriman.'),
  ('id.indonesian', 15, 78, 'Dan sesungguhnya adalah penduduk Aikah itu benar-benar kaum yang zalim,'),
  ('id.indonesian', 15, 79, 'maka Kami membinasakan mereka. Dan sesungguhnya kedua kota itu benar-benar terletak di jalan umum yang terang.'),
  ('id.indonesian', 15, 80, 'Dan sesungguhnya penduduk-penduduk kota Al Hijr telah mendustakan rasul-rasul,'),
  ('id.indonesian', 15, 81, 'dan Kami telah mendatangkan kepada mereka tanda-tanda (kekuasaan) Kami, tetapi mereka selalu berpaling daripadanya,'),
  ('id.indonesian', 15, 82, 'dan mereka memahat rumah-rumah dari gunung-gunung batu (yang didiami) dengan aman.'),
  ('id.indonesian', 15, 83, 'Maka mereka dibinasakan oleh suara keras yang mengguntur di waktu pagi,'),
  ('id.indonesian', 15, 84, 'maka tak dapat menolong mereka, apa yang telah mereka usahakan.'),
  ('id.indonesian', 15, 85, 'Dan tidaklah Kami ciptakan langit dan bumi dan apa yang ada di antara keduanya, melainkan dengan benar. Dan sesungguhnya saat (kiamat) itu pasti akan datang, maka maafkanlah (mereka) dengan cara yang baik.'),
  ('id.indonesian', 15, 86, 'Sesungguhnya Tuhanmu, Dialah Yang Maha Pencipta lagi Maha Mengetahui.'),
  ('id.indonesian', 15, 87, 'Dan sesungguhnya Kami telah berikan kepadamu tujuh ayat yang dibaca berulang-ulang dan Al Quran yang agung.'),
  ('id.indonesian', 15, 88, 'Janganlah sekali-kali kamu menunjukkan pandanganmu kepada kenikmatan hidup yang telah Kami berikan kepada beberapa golongan di antara mereka (orang-orang kafir itu), dan janganlah kamu bersedih hati terhadap mereka dan berendah dirilah kamu terhadap orang-orang yang beriman.'),
  ('id.indonesian', 15, 89, 'Dan katakanlah: "Sesungguhnya aku adalah pemberi peringatan yang menjelaskan".'),
  ('id.indonesian', 15, 90, 'Sebagaimana (Kami telah memberi peringatan), Kami telah menurunkan (azab) kepada orang-orang yang membagi-bagi (Kitab Allah),'),
  ('id.indonesian', 15, 91, '(yaitu) orang-orang yang telah menjadikan Al Quran itu terbagi-bagi.'),
  ('id.indonesian', 15, 92, 'Maka demi Tuhanmu, Kami pasti akan menanyai mereka semua,'),
  ('id.indonesian', 15, 93, 'tentang apa yang telah mereka kerjakan dahulu.'),
  ('id.indonesian', 15, 94, 'Maka sampaikanlah olehmu secara terang-terangan segala apa yang diperintahkan (kepadamu) dan berpalinglah dari orang-orang yang musyrik.'),
  ('id.indonesian', 15, 95, 'Sesungguhnya Kami memelihara kamu daripada (kejahatan) orang-orang yang memperolok-olokkan (kamu),'),
  ('id.indonesian', 15, 96, '(Yaitu) orang-orang yang menganggap adanya tuhan yang lain di samping Allah; maka mereka kelak akan mengetahui (akibat-akibatnya).'),
  ('id.indonesian', 15, 97, 'Dan Kami sungguh-sungguh mengetahui, bahwa dadamu menjadi sempit disebabkan apa yang mereka ucapkan,'),
  ('id.indonesian', 15, 98, 'maka bertasbihlah dengan memuji Tuhanmu dan jadilah kamu di antara orang-orang yang bersujud (shalat),'),
  ('id.indonesian', 15, 99, 'dan sembahlah Tuhanmu sampai datang kepadamu yang diyakini (ajal).')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (14, 51, 1801, 'لِيَجْزِىَ ٱللَّهُ كُلَّ نَفْسٍۢ مَّا كَسَبَتْ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 261, 13, 104, 0),
  (14, 52, 1802, 'هَٰذَا بَلَٰغٌۭ لِّلنَّاسِ وَلِيُنذَرُوا۟ بِهِۦ وَلِيَعْلَمُوٓا۟ أَنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ وَلِيَذَّكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 261, 13, 104, 0),
  (15, 1, 1803, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ وَقُرْءَانٍۢ مُّبِينٍۢ', 262, 14, 105, 0),
  (15, 2, 1804, 'رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ لَوْ كَانُوا۟ مُسْلِمِينَ', 262, 14, 105, 0),
  (15, 3, 1805, 'ذَرْهُمْ يَأْكُلُوا۟ وَيَتَمَتَّعُوا۟ وَيُلْهِهِمُ ٱلْأَمَلُ ۖ فَسَوْفَ يَعْلَمُونَ', 262, 14, 105, 0),
  (15, 4, 1806, 'وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلَّا وَلَهَا كِتَابٌۭ مَّعْلُومٌۭ', 262, 14, 105, 0),
  (15, 5, 1807, 'مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 262, 14, 105, 0),
  (15, 6, 1808, 'وَقَالُوا۟ يَٰٓأَيُّهَا ٱلَّذِى نُزِّلَ عَلَيْهِ ٱلذِّكْرُ إِنَّكَ لَمَجْنُونٌۭ', 262, 14, 105, 0),
  (15, 7, 1809, 'لَّوْ مَا تَأْتِينَا بِٱلْمَلَٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 262, 14, 105, 0),
  (15, 8, 1810, 'مَا نُنَزِّلُ ٱلْمَلَٰٓئِكَةَ إِلَّا بِٱلْحَقِّ وَمَا كَانُوٓا۟ إِذًۭا مُّنظَرِينَ', 262, 14, 105, 0),
  (15, 9, 1811, 'إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 262, 14, 105, 0),
  (15, 10, 1812, 'وَلَقَدْ أَرْسَلْنَا مِن قَبْلِكَ فِى شِيَعِ ٱلْأَوَّلِينَ', 262, 14, 105, 0),
  (15, 11, 1813, 'وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 262, 14, 105, 0),
  (15, 12, 1814, 'كَذَٰلِكَ نَسْلُكُهُۥ فِى قُلُوبِ ٱلْمُجْرِمِينَ', 262, 14, 105, 0),
  (15, 13, 1815, 'لَا يُؤْمِنُونَ بِهِۦ ۖ وَقَدْ خَلَتْ سُنَّةُ ٱلْأَوَّلِينَ', 262, 14, 105, 0),
  (15, 14, 1816, 'وَلَوْ فَتَحْنَا عَلَيْهِم بَابًۭا مِّنَ ٱلسَّمَآءِ فَظَلُّوا۟ فِيهِ يَعْرُجُونَ', 262, 14, 105, 0),
  (15, 15, 1817, 'لَقَالُوٓا۟ إِنَّمَا سُكِّرَتْ أَبْصَٰرُنَا بَلْ نَحْنُ قَوْمٌۭ مَّسْحُورُونَ', 262, 14, 105, 0),
  (15, 16, 1818, 'وَلَقَدْ جَعَلْنَا فِى ٱلسَّمَآءِ بُرُوجًۭا وَزَيَّنَّٰهَا لِلنَّٰظِرِينَ', 263, 14, 105, 0),
  (15, 17, 1819, 'وَحَفِظْنَٰهَا مِن كُلِّ شَيْطَٰنٍۢ رَّجِيمٍ', 263, 14, 105, 0),
  (15, 18, 1820, 'إِلَّا مَنِ ٱسْتَرَقَ ٱلسَّمْعَ فَأَتْبَعَهُۥ شِهَابٌۭ مُّبِينٌۭ', 263, 14, 105, 0),
  (15, 19, 1821, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ شَىْءٍۢ مَّوْزُونٍۢ', 263, 14, 105, 0),
  (15, 20, 1822, 'وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ وَمَن لَّسْتُمْ لَهُۥ بِرَٰزِقِينَ', 263, 14, 105, 0),
  (15, 21, 1823, 'وَإِن مِّن شَىْءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٍۢ مَّعْلُومٍۢ', 263, 14, 105, 0),
  (15, 22, 1824, 'وَأَرْسَلْنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَسْقَيْنَٰكُمُوهُ وَمَآ أَنتُمْ لَهُۥ بِخَٰزِنِينَ', 263, 14, 105, 0),
  (15, 23, 1825, 'وَإِنَّا لَنَحْنُ نُحْىِۦ وَنُمِيتُ وَنَحْنُ ٱلْوَٰرِثُونَ', 263, 14, 105, 0),
  (15, 24, 1826, 'وَلَقَدْ عَلِمْنَا ٱلْمُسْتَقْدِمِينَ مِنكُمْ وَلَقَدْ عَلِمْنَا ٱلْمُسْتَـْٔخِرِينَ', 263, 14, 105, 0),
  (15, 25, 1827, 'وَإِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌۭ', 263, 14, 105, 0),
  (15, 26, 1828, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن صَلْصَٰلٍۢ مِّنْ حَمَإٍۢ مَّسْنُونٍۢ', 263, 14, 105, 0),
  (15, 27, 1829, 'وَٱلْجَآنَّ خَلَقْنَٰهُ مِن قَبْلُ مِن نَّارِ ٱلسَّمُومِ', 263, 14, 105, 0),
  (15, 28, 1830, 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًۭا مِّن صَلْصَٰلٍۢ مِّنْ حَمَإٍۢ مَّسْنُونٍۢ', 263, 14, 105, 0),
  (15, 29, 1831, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 263, 14, 105, 0),
  (15, 30, 1832, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 263, 14, 105, 0),
  (15, 31, 1833, 'إِلَّآ إِبْلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ', 263, 14, 105, 0),
  (15, 32, 1834, 'قَالَ يَٰٓإِبْلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّٰجِدِينَ', 264, 14, 105, 0),
  (15, 33, 1835, 'قَالَ لَمْ أَكُن لِّأَسْجُدَ لِبَشَرٍ خَلَقْتَهُۥ مِن صَلْصَٰلٍۢ مِّنْ حَمَإٍۢ مَّسْنُونٍۢ', 264, 14, 105, 0),
  (15, 34, 1836, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌۭ', 264, 14, 105, 0),
  (15, 35, 1837, 'وَإِنَّ عَلَيْكَ ٱللَّعْنَةَ إِلَىٰ يَوْمِ ٱلدِّينِ', 264, 14, 105, 0),
  (15, 36, 1838, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 264, 14, 105, 0),
  (15, 37, 1839, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 264, 14, 105, 0),
  (15, 38, 1840, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 264, 14, 105, 0),
  (15, 39, 1841, 'قَالَ رَبِّ بِمَآ أَغْوَيْتَنِى لَأُزَيِّنَنَّ لَهُمْ فِى ٱلْأَرْضِ وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 264, 14, 105, 0),
  (15, 40, 1842, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 264, 14, 105, 0),
  (15, 41, 1843, 'قَالَ هَٰذَا صِرَٰطٌ عَلَىَّ مُسْتَقِيمٌ', 264, 14, 105, 0),
  (15, 42, 1844, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلْغَاوِينَ', 264, 14, 105, 0),
  (15, 43, 1845, 'وَإِنَّ جَهَنَّمَ لَمَوْعِدُهُمْ أَجْمَعِينَ', 264, 14, 105, 0),
  (15, 44, 1846, 'لَهَا سَبْعَةُ أَبْوَٰبٍۢ لِّكُلِّ بَابٍۢ مِّنْهُمْ جُزْءٌۭ مَّقْسُومٌ', 264, 14, 105, 0),
  (15, 45, 1847, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَعُيُونٍ', 264, 14, 105, 0),
  (15, 46, 1848, 'ٱدْخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ', 264, 14, 105, 0),
  (15, 47, 1849, 'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ إِخْوَٰنًا عَلَىٰ سُرُرٍۢ مُّتَقَٰبِلِينَ', 264, 14, 105, 0),
  (15, 48, 1850, 'لَا يَمَسُّهُمْ فِيهَا نَصَبٌۭ وَمَا هُم مِّنْهَا بِمُخْرَجِينَ', 264, 14, 105, 0),
  (15, 49, 1851, '۞ نَبِّئْ عِبَادِىٓ أَنِّىٓ أَنَا ٱلْغَفُورُ ٱلرَّحِيمُ', 264, 14, 105, 0),
  (15, 50, 1852, 'وَأَنَّ عَذَابِى هُوَ ٱلْعَذَابُ ٱلْأَلِيمُ', 264, 14, 106, 0),
  (15, 51, 1853, 'وَنَبِّئْهُمْ عَن ضَيْفِ إِبْرَٰهِيمَ', 264, 14, 106, 0),
  (15, 52, 1854, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًۭا قَالَ إِنَّا مِنكُمْ وَجِلُونَ', 265, 14, 106, 0),
  (15, 53, 1855, 'قَالُوا۟ لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٍۢ', 265, 14, 106, 0),
  (15, 54, 1856, 'قَالَ أَبَشَّرْتُمُونِى عَلَىٰٓ أَن مَّسَّنِىَ ٱلْكِبَرُ فَبِمَ تُبَشِّرُونَ', 265, 14, 106, 0),
  (15, 55, 1857, 'قَالُوا۟ بَشَّرْنَٰكَ بِٱلْحَقِّ فَلَا تَكُن مِّنَ ٱلْقَٰنِطِينَ', 265, 14, 106, 0),
  (15, 56, 1858, 'قَالَ وَمَن يَقْنَطُ مِن رَّحْمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ', 265, 14, 106, 0),
  (15, 57, 1859, 'قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 265, 14, 106, 0),
  (15, 58, 1860, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍۢ مُّجْرِمِينَ', 265, 14, 106, 0),
  (15, 59, 1861, 'إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمْ أَجْمَعِينَ', 265, 14, 106, 0),
  (15, 60, 1862, 'إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَآ ۙ إِنَّهَا لَمِنَ ٱلْغَٰبِرِينَ', 265, 14, 106, 0),
  (15, 61, 1863, 'فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلْمُرْسَلُونَ', 265, 14, 106, 0),
  (15, 62, 1864, 'قَالَ إِنَّكُمْ قَوْمٌۭ مُّنكَرُونَ', 265, 14, 106, 0),
  (15, 63, 1865, 'قَالُوا۟ بَلْ جِئْنَٰكَ بِمَا كَانُوا۟ فِيهِ يَمْتَرُونَ', 265, 14, 106, 0),
  (15, 64, 1866, 'وَأَتَيْنَٰكَ بِٱلْحَقِّ وَإِنَّا لَصَٰدِقُونَ', 265, 14, 106, 0),
  (15, 65, 1867, 'فَأَسْرِ بِأَهْلِكَ بِقِطْعٍۢ مِّنَ ٱلَّيْلِ وَٱتَّبِعْ أَدْبَٰرَهُمْ وَلَا يَلْتَفِتْ مِنكُمْ أَحَدٌۭ وَٱمْضُوا۟ حَيْثُ تُؤْمَرُونَ', 265, 14, 106, 0),
  (15, 66, 1868, 'وَقَضَيْنَآ إِلَيْهِ ذَٰلِكَ ٱلْأَمْرَ أَنَّ دَابِرَ هَٰٓؤُلَآءِ مَقْطُوعٌۭ مُّصْبِحِينَ', 265, 14, 106, 0),
  (15, 67, 1869, 'وَجَآءَ أَهْلُ ٱلْمَدِينَةِ يَسْتَبْشِرُونَ', 265, 14, 106, 0),
  (15, 68, 1870, 'قَالَ إِنَّ هَٰٓؤُلَآءِ ضَيْفِى فَلَا تَفْضَحُونِ', 265, 14, 106, 0),
  (15, 69, 1871, 'وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخْزُونِ', 265, 14, 106, 0),
  (15, 70, 1872, 'قَالُوٓا۟ أَوَلَمْ نَنْهَكَ عَنِ ٱلْعَٰلَمِينَ', 265, 14, 106, 0),
  (15, 71, 1873, 'قَالَ هَٰٓؤُلَآءِ بَنَاتِىٓ إِن كُنتُمْ فَٰعِلِينَ', 266, 14, 106, 0),
  (15, 72, 1874, 'لَعَمْرُكَ إِنَّهُمْ لَفِى سَكْرَتِهِمْ يَعْمَهُونَ', 266, 14, 106, 0),
  (15, 73, 1875, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُشْرِقِينَ', 266, 14, 106, 0),
  (15, 74, 1876, 'فَجَعَلْنَا عَٰلِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهِمْ حِجَارَةًۭ مِّن سِجِّيلٍ', 266, 14, 106, 0),
  (15, 75, 1877, 'إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّلْمُتَوَسِّمِينَ', 266, 14, 106, 0),
  (15, 76, 1878, 'وَإِنَّهَا لَبِسَبِيلٍۢ مُّقِيمٍ', 266, 14, 106, 0),
  (15, 77, 1879, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّلْمُؤْمِنِينَ', 266, 14, 106, 0),
  (15, 78, 1880, 'وَإِن كَانَ أَصْحَٰبُ ٱلْأَيْكَةِ لَظَٰلِمِينَ', 266, 14, 106, 0),
  (15, 79, 1881, 'فَٱنتَقَمْنَا مِنْهُمْ وَإِنَّهُمَا لَبِإِمَامٍۢ مُّبِينٍۢ', 266, 14, 106, 0),
  (15, 80, 1882, 'وَلَقَدْ كَذَّبَ أَصْحَٰبُ ٱلْحِجْرِ ٱلْمُرْسَلِينَ', 266, 14, 106, 0),
  (15, 81, 1883, 'وَءَاتَيْنَٰهُمْ ءَايَٰتِنَا فَكَانُوا۟ عَنْهَا مُعْرِضِينَ', 266, 14, 106, 0),
  (15, 82, 1884, 'وَكَانُوا۟ يَنْحِتُونَ مِنَ ٱلْجِبَالِ بُيُوتًا ءَامِنِينَ', 266, 14, 106, 0),
  (15, 83, 1885, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ مُصْبِحِينَ', 266, 14, 106, 0),
  (15, 84, 1886, 'فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 266, 14, 106, 0),
  (15, 85, 1887, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ ۗ وَإِنَّ ٱلسَّاعَةَ لَءَاتِيَةٌۭ ۖ فَٱصْفَحِ ٱلصَّفْحَ ٱلْجَمِيلَ', 266, 14, 106, 0),
  (15, 86, 1888, 'إِنَّ رَبَّكَ هُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ', 266, 14, 106, 0),
  (15, 87, 1889, 'وَلَقَدْ ءَاتَيْنَٰكَ سَبْعًۭا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ', 266, 14, 106, 0),
  (15, 88, 1890, 'لَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًۭا مِّنْهُمْ وَلَا تَحْزَنْ عَلَيْهِمْ وَٱخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ', 266, 14, 106, 0),
  (15, 89, 1891, 'وَقُلْ إِنِّىٓ أَنَا ٱلنَّذِيرُ ٱلْمُبِينُ', 266, 14, 106, 0),
  (15, 90, 1892, 'كَمَآ أَنزَلْنَا عَلَى ٱلْمُقْتَسِمِينَ', 266, 14, 106, 0),
  (15, 91, 1893, 'ٱلَّذِينَ جَعَلُوا۟ ٱلْقُرْءَانَ عِضِينَ', 267, 14, 106, 0),
  (15, 92, 1894, 'فَوَرَبِّكَ لَنَسْـَٔلَنَّهُمْ أَجْمَعِينَ', 267, 14, 106, 0),
  (15, 93, 1895, 'عَمَّا كَانُوا۟ يَعْمَلُونَ', 267, 14, 106, 0),
  (15, 94, 1896, 'فَٱصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ', 267, 14, 106, 0),
  (15, 95, 1897, 'إِنَّا كَفَيْنَٰكَ ٱلْمُسْتَهْزِءِينَ', 267, 14, 106, 0),
  (15, 96, 1898, 'ٱلَّذِينَ يَجْعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۚ فَسَوْفَ يَعْلَمُونَ', 267, 14, 106, 0),
  (15, 97, 1899, 'وَلَقَدْ نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ بِمَا يَقُولُونَ', 267, 14, 106, 0),
  (15, 98, 1900, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَكُن مِّنَ ٱلسَّٰجِدِينَ', 267, 14, 106, 0),
  (15, 99, 1901, 'وَٱعْبُدْ رَبَّكَ حَتَّىٰ يَأْتِيَكَ ٱلْيَقِينُ', 267, 14, 106, 0),
  (16, 1, 1902, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَتَىٰٓ أَمْرُ ٱللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 267, 14, 107, 0),
  (16, 2, 1903, 'يُنَزِّلُ ٱلْمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦٓ أَنْ أَنذِرُوٓا۟ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ', 267, 14, 107, 0),
  (16, 3, 1904, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۚ تَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 267, 14, 107, 0),
  (16, 4, 1905, 'خَلَقَ ٱلْإِنسَٰنَ مِن نُّطْفَةٍۢ فَإِذَا هُوَ خَصِيمٌۭ مُّبِينٌۭ', 267, 14, 107, 0),
  (16, 5, 1906, 'وَٱلْأَنْعَٰمَ خَلَقَهَا ۗ لَكُمْ فِيهَا دِفْءٌۭ وَمَنَٰفِعُ وَمِنْهَا تَأْكُلُونَ', 267, 14, 107, 0),
  (16, 6, 1907, 'وَلَكُمْ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسْرَحُونَ', 267, 14, 107, 0),
  (16, 7, 1908, 'وَتَحْمِلُ أَثْقَالَكُمْ إِلَىٰ بَلَدٍۢ لَّمْ تَكُونُوا۟ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلْأَنفُسِ ۚ إِنَّ رَبَّكُمْ لَرَءُوفٌۭ رَّحِيمٌۭ', 268, 14, 107, 0),
  (16, 8, 1909, 'وَٱلْخَيْلَ وَٱلْبِغَالَ وَٱلْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةًۭ ۚ وَيَخْلُقُ مَا لَا تَعْلَمُونَ', 268, 14, 107, 0),
  (16, 9, 1910, 'وَعَلَى ٱللَّهِ قَصْدُ ٱلسَّبِيلِ وَمِنْهَا جَآئِرٌۭ ۚ وَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ', 268, 14, 107, 0),
  (16, 10, 1911, 'هُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ ۖ لَّكُم مِّنْهُ شَرَابٌۭ وَمِنْهُ شَجَرٌۭ فِيهِ تُسِيمُونَ', 268, 14, 107, 0),
  (16, 11, 1912, 'يُنۢبِتُ لَكُم بِهِ ٱلزَّرْعَ وَٱلزَّيْتُونَ وَٱلنَّخِيلَ وَٱلْأَعْنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 268, 14, 107, 0),
  (16, 12, 1913, 'وَسَخَّرَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ وَٱلنُّجُومُ مُسَخَّرَٰتٌۢ بِأَمْرِهِۦٓ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَعْقِلُونَ', 268, 14, 107, 0),
  (16, 13, 1914, 'وَمَا ذَرَأَ لَكُمْ فِى ٱلْأَرْضِ مُخْتَلِفًا أَلْوَٰنُهُۥٓ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَذَّكَّرُونَ', 268, 14, 107, 0),
  (16, 14, 1915, 'وَهُوَ ٱلَّذِى سَخَّرَ ٱلْبَحْرَ لِتَأْكُلُوا۟ مِنْهُ لَحْمًۭا طَرِيًّۭا وَتَسْتَخْرِجُوا۟ مِنْهُ حِلْيَةًۭ تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ مَوَاخِرَ فِيهِ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 268, 14, 107, 0),
  (16, 15, 1916, 'وَأَلْقَىٰ فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِكُمْ وَأَنْهَٰرًۭا وَسُبُلًۭا لَّعَلَّكُمْ تَهْتَدُونَ', 269, 14, 107, 0),
  (16, 16, 1917, 'وَعَلَٰمَٰتٍۢ ۚ وَبِٱلنَّجْمِ هُمْ يَهْتَدُونَ', 269, 14, 107, 0),
  (16, 17, 1918, 'أَفَمَن يَخْلُقُ كَمَن لَّا يَخْلُقُ ۗ أَفَلَا تَذَكَّرُونَ', 269, 14, 107, 0),
  (16, 18, 1919, 'وَإِن تَعُدُّوا۟ نِعْمَةَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱللَّهَ لَغَفُورٌۭ رَّحِيمٌۭ', 269, 14, 107, 0),
  (16, 19, 1920, 'وَٱللَّهُ يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ', 269, 14, 107, 0),
  (16, 20, 1921, 'وَٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ لَا يَخْلُقُونَ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ', 269, 14, 107, 0),
  (16, 21, 1922, 'أَمْوَٰتٌ غَيْرُ أَحْيَآءٍۢ ۖ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ', 269, 14, 107, 0),
  (16, 22, 1923, 'إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۚ فَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ قُلُوبُهُم مُّنكِرَةٌۭ وَهُم مُّسْتَكْبِرُونَ', 269, 14, 107, 0),
  (16, 23, 1924, 'لَا جَرَمَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْتَكْبِرِينَ', 269, 14, 107, 0),
  (16, 24, 1925, 'وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمْ ۙ قَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 269, 14, 107, 0),
  (16, 25, 1926, 'لِيَحْمِلُوٓا۟ أَوْزَارَهُمْ كَامِلَةًۭ يَوْمَ ٱلْقِيَٰمَةِ ۙ وَمِنْ أَوْزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيْرِ عِلْمٍ ۗ أَلَا سَآءَ مَا يَزِرُونَ', 269, 14, 107, 0),
  (16, 26, 1927, 'قَدْ مَكَرَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَى ٱللَّهُ بُنْيَٰنَهُم مِّنَ ٱلْقَوَاعِدِ فَخَرَّ عَلَيْهِمُ ٱلسَّقْفُ مِن فَوْقِهِمْ وَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 269, 14, 107, 0),
  (16, 27, 1928, 'ثُمَّ يَوْمَ ٱلْقِيَٰمَةِ يُخْزِيهِمْ وَيَقُولُ أَيْنَ شُرَكَآءِىَ ٱلَّذِينَ كُنتُمْ تُشَٰٓقُّونَ فِيهِمْ ۚ قَالَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ إِنَّ ٱلْخِزْىَ ٱلْيَوْمَ وَٱلسُّوٓءَ عَلَى ٱلْكَٰفِرِينَ', 270, 14, 107, 0),
  (16, 28, 1929, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ ۖ فَأَلْقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعْمَلُ مِن سُوٓءٍۭ ۚ بَلَىٰٓ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا كُنتُمْ تَعْمَلُونَ', 270, 14, 107, 0),
  (16, 29, 1930, 'فَٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۖ فَلَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 270, 14, 107, 0),
  (16, 30, 1931, '۞ وَقِيلَ لِلَّذِينَ ٱتَّقَوْا۟ مَاذَآ أَنزَلَ رَبُّكُمْ ۚ قَالُوا۟ خَيْرًۭا ۗ لِّلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌۭ ۚ وَلَدَارُ ٱلْءَاخِرَةِ خَيْرٌۭ ۚ وَلَنِعْمَ دَارُ ٱلْمُتَّقِينَ', 270, 14, 108, 0),
  (16, 31, 1932, 'جَنَّٰتُ عَدْنٍۢ يَدْخُلُونَهَا تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ لَهُمْ فِيهَا مَا يَشَآءُونَ ۚ كَذَٰلِكَ يَجْزِى ٱللَّهُ ٱلْمُتَّقِينَ', 270, 14, 108, 0),
  (16, 32, 1933, 'ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ طَيِّبِينَ ۙ يَقُولُونَ سَلَٰمٌ عَلَيْكُمُ ٱدْخُلُوا۟ ٱلْجَنَّةَ بِمَا كُنتُمْ تَعْمَلُونَ', 270, 14, 108, 0),
  (16, 33, 1934, 'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَٰٓئِكَةُ أَوْ يَأْتِىَ أَمْرُ رَبِّكَ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 270, 14, 108, 0),
  (16, 34, 1935, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 270, 14, 108, 0),
  (16, 35, 1936, 'وَقَالَ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَا عَبَدْنَا مِن دُونِهِۦ مِن شَىْءٍۢ نَّحْنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن دُونِهِۦ مِن شَىْءٍۢ ۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ فَهَلْ عَلَى ٱلرُّسُلِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 271, 14, 108, 0),
  (16, 36, 1937, 'وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍۢ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّٰغُوتَ ۖ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَٰلَةُ ۚ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 271, 14, 108, 0),
  (16, 37, 1938, 'إِن تَحْرِصْ عَلَىٰ هُدَىٰهُمْ فَإِنَّ ٱللَّهَ لَا يَهْدِى مَن يُضِلُّ ۖ وَمَا لَهُم مِّن نَّٰصِرِينَ', 271, 14, 108, 0),
  (16, 38, 1939, 'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ ۙ لَا يَبْعَثُ ٱللَّهُ مَن يَمُوتُ ۚ بَلَىٰ وَعْدًا عَلَيْهِ حَقًّۭا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 271, 14, 108, 0),
  (16, 39, 1940, 'لِيُبَيِّنَ لَهُمُ ٱلَّذِى يَخْتَلِفُونَ فِيهِ وَلِيَعْلَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ كَانُوا۟ كَٰذِبِينَ', 271, 14, 108, 0),
  (16, 40, 1941, 'إِنَّمَا قَوْلُنَا لِشَىْءٍ إِذَآ أَرَدْنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ', 271, 14, 108, 0),
  (16, 41, 1942, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمْ فِى ٱلدُّنْيَا حَسَنَةًۭ ۖ وَلَأَجْرُ ٱلْءَاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 271, 14, 108, 0),
  (16, 42, 1943, 'ٱلَّذِينَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 271, 14, 108, 0),
  (16, 43, 1944, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًۭا نُّوحِىٓ إِلَيْهِمْ ۚ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 272, 14, 108, 0),
  (16, 44, 1945, 'بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ ۗ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', 272, 14, 108, 0),
  (16, 45, 1946, 'أَفَأَمِنَ ٱلَّذِينَ مَكَرُوا۟ ٱلسَّيِّـَٔاتِ أَن يَخْسِفَ ٱللَّهُ بِهِمُ ٱلْأَرْضَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 272, 14, 108, 0),
  (16, 46, 1947, 'أَوْ يَأْخُذَهُمْ فِى تَقَلُّبِهِمْ فَمَا هُم بِمُعْجِزِينَ', 272, 14, 108, 0),
  (16, 47, 1948, 'أَوْ يَأْخُذَهُمْ عَلَىٰ تَخَوُّفٍۢ فَإِنَّ رَبَّكُمْ لَرَءُوفٌۭ رَّحِيمٌ', 272, 14, 108, 0),
  (16, 48, 1949, 'أَوَلَمْ يَرَوْا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَىْءٍۢ يَتَفَيَّؤُا۟ ظِلَٰلُهُۥ عَنِ ٱلْيَمِينِ وَٱلشَّمَآئِلِ سُجَّدًۭا لِّلَّهِ وَهُمْ دَٰخِرُونَ', 272, 14, 108, 0),
  (16, 49, 1950, 'وَلِلَّهِ يَسْجُدُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مِن دَآبَّةٍۢ وَٱلْمَلَٰٓئِكَةُ وَهُمْ لَا يَسْتَكْبِرُونَ', 272, 14, 108, 0),
  (16, 50, 1951, 'يَخَافُونَ رَبَّهُم مِّن فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ ۩', 272, 14, 108, 1),
  (16, 51, 1952, '۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓا۟ إِلَٰهَيْنِ ٱثْنَيْنِ ۖ إِنَّمَا هُوَ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَإِيَّٰىَ فَٱرْهَبُونِ', 272, 14, 109, 0),
  (16, 52, 1953, 'وَلَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا ۚ أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', 272, 14, 109, 0),
  (16, 53, 1954, 'وَمَا بِكُم مِّن نِّعْمَةٍۢ فَمِنَ ٱللَّهِ ۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيْهِ تَجْـَٔرُونَ', 272, 14, 109, 0),
  (16, 54, 1955, 'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمْ إِذَا فَرِيقٌۭ مِّنكُم بِرَبِّهِمْ يُشْرِكُونَ', 272, 14, 109, 0),
  (16, 55, 1956, 'لِيَكْفُرُوا۟ بِمَآ ءَاتَيْنَٰهُمْ ۚ فَتَمَتَّعُوا۟ ۖ فَسَوْفَ تَعْلَمُونَ', 273, 14, 109, 0),
  (16, 56, 1957, 'وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًۭا مِّمَّا رَزَقْنَٰهُمْ ۗ تَٱللَّهِ لَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَفْتَرُونَ', 273, 14, 109, 0),
  (16, 57, 1958, 'وَيَجْعَلُونَ لِلَّهِ ٱلْبَنَٰتِ سُبْحَٰنَهُۥ ۙ وَلَهُم مَّا يَشْتَهُونَ', 273, 14, 109, 0),
  (16, 58, 1959, 'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلْأُنثَىٰ ظَلَّ وَجْهُهُۥ مُسْوَدًّۭا وَهُوَ كَظِيمٌۭ', 273, 14, 109, 0),
  (16, 59, 1960, 'يَتَوَٰرَىٰ مِنَ ٱلْقَوْمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓ ۚ أَيُمْسِكُهُۥ عَلَىٰ هُونٍ أَمْ يَدُسُّهُۥ فِى ٱلتُّرَابِ ۗ أَلَا سَآءَ مَا يَحْكُمُونَ', 273, 14, 109, 0),
  (16, 60, 1961, 'لِلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ مَثَلُ ٱلسَّوْءِ ۖ وَلِلَّهِ ٱلْمَثَلُ ٱلْأَعْلَىٰ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 273, 14, 109, 0),
  (16, 61, 1962, 'وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍۢ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَـْٔخِرُونَ سَاعَةًۭ ۖ وَلَا يَسْتَقْدِمُونَ', 273, 14, 109, 0),
  (16, 62, 1963, 'وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ وَتَصِفُ أَلْسِنَتُهُمُ ٱلْكَذِبَ أَنَّ لَهُمُ ٱلْحُسْنَىٰ ۖ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفْرَطُونَ', 273, 14, 109, 0),
  (16, 63, 1964, 'تَٱللَّهِ لَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍۢ مِّن قَبْلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيْطَٰنُ أَعْمَٰلَهُمْ فَهُوَ وَلِيُّهُمُ ٱلْيَوْمَ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 273, 14, 109, 0),
  (16, 64, 1965, 'وَمَآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِى ٱخْتَلَفُوا۟ فِيهِ ۙ وَهُدًۭى وَرَحْمَةًۭ لِّقَوْمٍۢ يُؤْمِنُونَ', 273, 14, 109, 0),
  (16, 65, 1966, 'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَآ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَسْمَعُونَ', 274, 14, 109, 0),
  (16, 66, 1967, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةًۭ ۖ نُّسْقِيكُم مِّمَّا فِى بُطُونِهِۦ مِنۢ بَيْنِ فَرْثٍۢ وَدَمٍۢ لَّبَنًا خَالِصًۭا سَآئِغًۭا لِّلشَّٰرِبِينَ', 274, 14, 109, 0),
  (16, 67, 1968, 'وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلْأَعْنَٰبِ تَتَّخِذُونَ مِنْهُ سَكَرًۭا وَرِزْقًا حَسَنًا ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَعْقِلُونَ', 274, 14, 109, 0),
  (16, 68, 1969, 'وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًۭا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ', 274, 14, 109, 0),
  (16, 69, 1970, 'ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًۭا ۚ يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌۭ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌۭ لِّلنَّاسِ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 274, 14, 109, 0),
  (16, 70, 1971, 'وَٱللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّىٰكُمْ ۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَىْ لَا يَعْلَمَ بَعْدَ عِلْمٍۢ شَيْـًٔا ۚ إِنَّ ٱللَّهَ عَلِيمٌۭ قَدِيرٌۭ', 274, 14, 109, 0),
  (16, 71, 1972, 'وَٱللَّهُ فَضَّلَ بَعْضَكُمْ عَلَىٰ بَعْضٍۢ فِى ٱلرِّزْقِ ۚ فَمَا ٱلَّذِينَ فُضِّلُوا۟ بِرَآدِّى رِزْقِهِمْ عَلَىٰ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَهُمْ فِيهِ سَوَآءٌ ۚ أَفَبِنِعْمَةِ ٱللَّهِ يَجْحَدُونَ', 274, 14, 109, 0),
  (16, 72, 1973, 'وَٱللَّهُ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا وَجَعَلَ لَكُم مِّنْ أَزْوَٰجِكُم بَنِينَ وَحَفَدَةًۭ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ۚ أَفَبِٱلْبَٰطِلِ يُؤْمِنُونَ وَبِنِعْمَتِ ٱللَّهِ هُمْ يَكْفُرُونَ', 274, 14, 109, 0),
  (16, 73, 1974, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَهُمْ رِزْقًۭا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ شَيْـًۭٔا وَلَا يَسْتَطِيعُونَ', 275, 14, 109, 0),
  (16, 74, 1975, 'فَلَا تَضْرِبُوا۟ لِلَّهِ ٱلْأَمْثَالَ ۚ إِنَّ ٱللَّهَ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 275, 14, 109, 0),
  (16, 75, 1976, '۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبْدًۭا مَّمْلُوكًۭا لَّا يَقْدِرُ عَلَىٰ شَىْءٍۢ وَمَن رَّزَقْنَٰهُ مِنَّا رِزْقًا حَسَنًۭا فَهُوَ يُنفِقُ مِنْهُ سِرًّۭا وَجَهْرًا ۖ هَلْ يَسْتَوُۥنَ ۚ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 275, 14, 110, 0),
  (16, 76, 1977, 'وَضَرَبَ ٱللَّهُ مَثَلًۭا رَّجُلَيْنِ أَحَدُهُمَآ أَبْكَمُ لَا يَقْدِرُ عَلَىٰ شَىْءٍۢ وَهُوَ كَلٌّ عَلَىٰ مَوْلَىٰهُ أَيْنَمَا يُوَجِّههُّ لَا يَأْتِ بِخَيْرٍ ۖ هَلْ يَسْتَوِى هُوَ وَمَن يَأْمُرُ بِٱلْعَدْلِ ۙ وَهُوَ عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 275, 14, 110, 0),
  (16, 77, 1978, 'وَلِلَّهِ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَآ أَمْرُ ٱلسَّاعَةِ إِلَّا كَلَمْحِ ٱلْبَصَرِ أَوْ هُوَ أَقْرَبُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 275, 14, 110, 0),
  (16, 78, 1979, 'وَٱللَّهُ أَخْرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمْ لَا تَعْلَمُونَ شَيْـًۭٔا وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۙ لَعَلَّكُمْ تَشْكُرُونَ', 275, 14, 110, 0),
  (16, 79, 1980, 'أَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ مُسَخَّرَٰتٍۢ فِى جَوِّ ٱلسَّمَآءِ مَا يُمْسِكُهُنَّ إِلَّا ٱللَّهُ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 275, 14, 110, 0),
  (16, 80, 1981, 'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمْ سَكَنًۭا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلْأَنْعَٰمِ بُيُوتًۭا تَسْتَخِفُّونَهَا يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ ۙ وَمِنْ أَصْوَافِهَا وَأَوْبَارِهَا وَأَشْعَارِهَآ أَثَٰثًۭا وَمَتَٰعًا إِلَىٰ حِينٍۢ', 276, 14, 110, 0),
  (16, 81, 1982, 'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلًۭا وَجَعَلَ لَكُم مِّنَ ٱلْجِبَالِ أَكْنَٰنًۭا وَجَعَلَ لَكُمْ سَرَٰبِيلَ تَقِيكُمُ ٱلْحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأْسَكُمْ ۚ كَذَٰلِكَ يُتِمُّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تُسْلِمُونَ', 276, 14, 110, 0),
  (16, 82, 1983, 'فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْكَ ٱلْبَلَٰغُ ٱلْمُبِينُ', 276, 14, 110, 0),
  (16, 83, 1984, 'يَعْرِفُونَ نِعْمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكْثَرُهُمُ ٱلْكَٰفِرُونَ', 276, 14, 110, 0),
  (16, 84, 1985, 'وَيَوْمَ نَبْعَثُ مِن كُلِّ أُمَّةٍۢ شَهِيدًۭا ثُمَّ لَا يُؤْذَنُ لِلَّذِينَ كَفَرُوا۟ وَلَا هُمْ يُسْتَعْتَبُونَ', 276, 14, 110, 0),
  (16, 85, 1986, 'وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُوا۟ ٱلْعَذَابَ فَلَا يُخَفَّفُ عَنْهُمْ وَلَا هُمْ يُنظَرُونَ', 276, 14, 110, 0),
  (16, 86, 1987, 'وَإِذَا رَءَا ٱلَّذِينَ أَشْرَكُوا۟ شُرَكَآءَهُمْ قَالُوا۟ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدْعُوا۟ مِن دُونِكَ ۖ فَأَلْقَوْا۟ إِلَيْهِمُ ٱلْقَوْلَ إِنَّكُمْ لَكَٰذِبُونَ', 276, 14, 110, 0),
  (16, 87, 1988, 'وَأَلْقَوْا۟ إِلَى ٱللَّهِ يَوْمَئِذٍ ٱلسَّلَمَ ۖ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ', 276, 14, 110, 0),
  (16, 88, 1989, 'ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ زِدْنَٰهُمْ عَذَابًۭا فَوْقَ ٱلْعَذَابِ بِمَا كَانُوا۟ يُفْسِدُونَ', 277, 14, 110, 0),
  (16, 89, 1990, 'وَيَوْمَ نَبْعَثُ فِى كُلِّ أُمَّةٍۢ شَهِيدًا عَلَيْهِم مِّنْ أَنفُسِهِمْ ۖ وَجِئْنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِ ۚ وَنَزَّلْنَا عَلَيْكَ ٱلْكِتَٰبَ تِبْيَٰنًۭا لِّكُلِّ شَىْءٍۢ وَهُدًۭى وَرَحْمَةًۭ وَبُشْرَىٰ لِلْمُسْلِمِينَ', 277, 14, 110, 0),
  (16, 90, 1991, '۞ إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 277, 14, 111, 0),
  (16, 91, 1992, 'وَأَوْفُوا۟ بِعَهْدِ ٱللَّهِ إِذَا عَٰهَدتُّمْ وَلَا تَنقُضُوا۟ ٱلْأَيْمَٰنَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ ٱللَّهَ عَلَيْكُمْ كَفِيلًا ۚ إِنَّ ٱللَّهَ يَعْلَمُ مَا تَفْعَلُونَ', 277, 14, 111, 0),
  (16, 92, 1993, 'وَلَا تَكُونُوا۟ كَٱلَّتِى نَقَضَتْ غَزْلَهَا مِنۢ بَعْدِ قُوَّةٍ أَنكَٰثًۭا تَتَّخِذُونَ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ أَن تَكُونَ أُمَّةٌ هِىَ أَرْبَىٰ مِنْ أُمَّةٍ ۚ إِنَّمَا يَبْلُوكُمُ ٱللَّهُ بِهِۦ ۚ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ ٱلْقِيَٰمَةِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 277, 14, 111, 0),
  (16, 93, 1994, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَلَتُسْـَٔلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ', 277, 14, 111, 0),
  (16, 94, 1995, 'وَلَا تَتَّخِذُوٓا۟ أَيْمَٰنَكُمْ دَخَلًۢا بَيْنَكُمْ فَتَزِلَّ قَدَمٌۢ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوٓءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ ٱللَّهِ ۖ وَلَكُمْ عَذَابٌ عَظِيمٌۭ', 278, 14, 111, 0),
  (16, 95, 1996, 'وَلَا تَشْتَرُوا۟ بِعَهْدِ ٱللَّهِ ثَمَنًۭا قَلِيلًا ۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 278, 14, 111, 0),
  (16, 96, 1997, 'مَا عِندَكُمْ يَنفَدُ ۖ وَمَا عِندَ ٱللَّهِ بَاقٍۢ ۗ وَلَنَجْزِيَنَّ ٱلَّذِينَ صَبَرُوٓا۟ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 278, 14, 111, 0),
  (16, 97, 1998, 'مَنْ عَمِلَ صَٰلِحًۭا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌۭ فَلَنُحْيِيَنَّهُۥ حَيَوٰةًۭ طَيِّبَةًۭ ۖ وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا۟ يَعْمَلُونَ', 278, 14, 111, 0),
  (16, 98, 1999, 'فَإِذَا قَرَأْتَ ٱلْقُرْءَانَ فَٱسْتَعِذْ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ', 278, 14, 111, 0),
  (16, 99, 2000, 'إِنَّهُۥ لَيْسَ لَهُۥ سُلْطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 278, 14, 111, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 16, 1, 'The command of Allah is coming, so be not impatient for it. Exalted is He and high above what they associate with Him.'),
  ('en.sahih', 16, 2, 'He sends down the angels, with the inspiration of His command, upon whom He wills of His servants, [telling them], "Warn that there is no deity except Me; so fear Me."'),
  ('en.sahih', 16, 3, 'He created the heavens and earth in truth. High is He above what they associate with Him.'),
  ('en.sahih', 16, 4, 'He created man from a sperm-drop; then at once, he is a clear adversary.'),
  ('en.sahih', 16, 5, 'And the grazing livestock He has created for you; in them is warmth and [numerous] benefits, and from them you eat.'),
  ('en.sahih', 16, 6, 'And for you in them is [the enjoyment of] beauty when you bring them in [for the evening] and when you send them out [to pasture].'),
  ('en.sahih', 16, 7, 'And they carry your loads to a land you could not have reached except with difficulty to yourselves. Indeed, your Lord is Kind and Merciful.'),
  ('en.sahih', 16, 8, 'And [He created] the horses, mules and donkeys for you to ride and [as] adornment. And He creates that which you do not know.'),
  ('en.sahih', 16, 9, 'And upon Allah is the direction of the [right] way, and among the various paths are those deviating. And if He willed, He could have guided you all.'),
  ('en.sahih', 16, 10, 'It is He who sends down rain from the sky; from it is drink and from it is foliage in which you pasture [animals].'),
  ('en.sahih', 16, 11, 'He causes to grow for you thereby the crops, olives, palm trees, grapevines, and from all the fruits. Indeed in that is a sign for a people who give thought.'),
  ('en.sahih', 16, 12, 'And He has subjected for you the night and day and the sun and moon, and the stars are subjected by His command. Indeed in that are signs for a people who reason.'),
  ('en.sahih', 16, 13, 'And [He has subjected] whatever He multiplied for you on the earth of varying colors. Indeed in that is a sign for a people who remember.'),
  ('en.sahih', 16, 14, 'And it is He who subjected the sea for you to eat from it tender meat and to extract from it ornaments which you wear. And you see the ships plowing through it, and [He subjected it] that you may seek of His bounty; and perhaps you will be grateful.'),
  ('en.sahih', 16, 15, 'And He has cast into the earth firmly set mountains, lest it shift with you, and [made] rivers and roads, that you may be guided,'),
  ('en.sahih', 16, 16, 'And landmarks. And by the stars they are [also] guided.'),
  ('en.sahih', 16, 17, 'Then is He who creates like one who does not create? So will you not be reminded?'),
  ('en.sahih', 16, 18, 'And if you should count the favors of Allah, you could not enumerate them. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 16, 19, 'And Allah knows what you conceal and what you declare.'),
  ('en.sahih', 16, 20, 'And those they invoke other than Allah create nothing, and they [themselves] are created.'),
  ('en.sahih', 16, 21, 'They are, [in fact], dead, not alive, and they do not perceive when they will be resurrected.'),
  ('en.sahih', 16, 22, 'Your god is one God. But those who do not believe in the Hereafter - their hearts are disapproving, and they are arrogant.'),
  ('en.sahih', 16, 23, 'Assuredly, Allah knows what they conceal and what they declare. Indeed, He does not like the arrogant.'),
  ('en.sahih', 16, 24, 'And when it is said to them, "What has your Lord sent down?" They say, "Legends of the former peoples,"'),
  ('en.sahih', 16, 25, 'That they may bear their own burdens in full on the Day of Resurrection and some of the burdens of those whom they misguide without knowledge. Unquestionably, evil is that which they bear.'),
  ('en.sahih', 16, 26, 'Those before them had already plotted, but Allah came at their building from the foundations, so the roof fell upon them from above them, and the punishment came to them from where they did not perceive.'),
  ('en.sahih', 16, 27, 'Then on the Day of Resurrection He will disgrace them and say, "Where are My \'partners\' for whom you used to oppose [the believers]?" Those who were given knowledge will say, "Indeed disgrace, this Day, and evil are upon the disbelievers" -'),
  ('en.sahih', 16, 28, 'The ones whom the angels take in death [while] wronging themselves, and [who] then offer submission, [saying], "We were not doing any evil." But, yes! Indeed, Allah is Knowing of what you used to do.'),
  ('en.sahih', 16, 29, 'So enter the gates of Hell to abide eternally therein, and how wretched is the residence of the arrogant.'),
  ('en.sahih', 16, 30, 'And it will be said to those who feared Allah, "What did your Lord send down?" They will say, "[That which is] good." For those who do good in this world is good; and the home of the Hereafter is better. And how excellent is the home of the righteous -'),
  ('en.sahih', 16, 31, 'Gardens of perpetual residence, which they will enter, beneath which rivers flow. They will have therein whatever they wish. Thus does Allah reward the righteous -'),
  ('en.sahih', 16, 32, 'The ones whom the angels take in death, [being] good and pure; [the angels] will say, "Peace be upon you. Enter Paradise for what you used to do."'),
  ('en.sahih', 16, 33, 'Do the disbelievers await [anything] except that the angels should come to them or there comes the command of your Lord? Thus did those do before them. And Allah wronged them not, but they had been wronging themselves.'),
  ('en.sahih', 16, 34, 'So they were struck by the evil consequences of what they did and were enveloped by what they used to ridicule.'),
  ('en.sahih', 16, 35, 'And those who associate others with Allah say, "If Allah had willed, we would not have worshipped anything other than Him, neither we nor our fathers, nor would we have forbidden anything through other than Him." Thus did those do before them. So is there upon the messengers except [the duty of] clear notification?'),
  ('en.sahih', 16, 36, 'And We certainly sent into every nation a messenger, [saying], "Worship Allah and avoid Taghut." And among them were those whom Allah guided, and among them were those upon whom error was [deservedly] decreed. So proceed through the earth and observe how was the end of the deniers.'),
  ('en.sahih', 16, 37, '[Even] if you should strive for their guidance, [O Muhammad], indeed, Allah does not guide those He sends astray, and they will have no helpers.'),
  ('en.sahih', 16, 38, 'And they swear by Allah their strongest oaths [that] Allah will not resurrect one who dies. But yes - [it is] a true promise [binding] upon Him, but most of the people do not know.'),
  ('en.sahih', 16, 39, '[It is] so He will make clear to them [the truth of] that wherein they differ and so those who have disbelieved may know that they were liars.'),
  ('en.sahih', 16, 40, 'Indeed, Our word to a thing when We intend it is but that We say to it, "Be," and it is.'),
  ('en.sahih', 16, 41, 'And those who emigrated for [the cause of] Allah after they had been wronged - We will surely settle them in this world in a good place; but the reward of the Hereafter is greater, if only they could know.'),
  ('en.sahih', 16, 42, '[They are] those who endured patiently and upon their Lord relied.'),
  ('en.sahih', 16, 43, 'And We sent not before you except men to whom We revealed [Our message]. So ask the people of the message if you do not know.'),
  ('en.sahih', 16, 44, '[We sent them] with clear proofs and written ordinances. And We revealed to you the message that you may make clear to the people what was sent down to them and that they might give thought.'),
  ('en.sahih', 16, 45, 'Then, do those who have planned evil deeds feel secure that Allah will not cause the earth to swallow them or that the punishment will not come upon them from where they do not perceive?'),
  ('en.sahih', 16, 46, 'Or that He would not seize them during their [usual] activity, and they could not cause failure?'),
  ('en.sahih', 16, 47, 'Or that He would not seize them gradually [in a state of dread]? But indeed, your Lord is Kind and Merciful.'),
  ('en.sahih', 16, 48, 'Have they not considered what things Allah has created? Their shadows incline to the right and to the left, prostrating to Allah, while they are humble.'),
  ('en.sahih', 16, 49, 'And to Allah prostrates whatever is in the heavens and whatever is on the earth of creatures, and the angels [as well], and they are not arrogant.'),
  ('en.sahih', 16, 50, 'They fear their Lord above them, and they do what they are commanded.'),
  ('en.sahih', 16, 51, 'And Allah has said, "Do not take for yourselves two deities. He is but one God, so fear only Me."'),
  ('en.sahih', 16, 52, 'And to Him belongs whatever is in the heavens and the earth, and to Him is [due] worship constantly. Then is it other than Allah that you fear?'),
  ('en.sahih', 16, 53, 'And whatever you have of favor - it is from Allah. Then when adversity touches you, to Him you cry for help.'),
  ('en.sahih', 16, 54, 'Then when He removes the adversity from you, at once a party of you associates others with their Lord'),
  ('en.sahih', 16, 55, 'So they will deny what We have given them. Then enjoy yourselves, for you are going to know.'),
  ('en.sahih', 16, 56, 'And they assign to what they do not know a portion of that which We have provided them. By Allah, you will surely be questioned about what you used to invent.'),
  ('en.sahih', 16, 57, 'And they attribute to Allah daughters - exalted is He - and for them is what they desire.'),
  ('en.sahih', 16, 58, 'And when one of them is informed of [the birth of] a female, his face becomes dark, and he suppresses grief.'),
  ('en.sahih', 16, 59, 'He hides himself from the people because of the ill of which he has been informed. Should he keep it in humiliation or bury it in the ground? Unquestionably, evil is what they decide.'),
  ('en.sahih', 16, 60, 'For those who do not believe in the Hereafter is the description of evil; and for Allah is the highest attribute. And He is Exalted in Might, the Wise.'),
  ('en.sahih', 16, 61, 'And if Allah were to impose blame on the people for their wrongdoing, He would not have left upon the earth any creature, but He defers them for a specified term. And when their term has come, they will not remain behind an hour, nor will they precede [it].'),
  ('en.sahih', 16, 62, 'And they attribute to Allah that which they dislike, and their tongues assert the lie that they will have the best [from Him]. Assuredly, they will have the Fire, and they will be [therein] neglected.'),
  ('en.sahih', 16, 63, 'By Allah, We did certainly send [messengers] to nations before you, but Satan made their deeds attractive to them. And he is the disbelievers\' ally today [as well], and they will have a painful punishment.'),
  ('en.sahih', 16, 64, 'And We have not revealed to you the Book, [O Muhammad], except for you to make clear to them that wherein they have differed and as guidance and mercy for a people who believe.'),
  ('en.sahih', 16, 65, 'And Allah has sent down rain from the sky and given life thereby to the earth after its lifelessness. Indeed in that is a sign for a people who listen.'),
  ('en.sahih', 16, 66, 'And indeed, for you in grazing livestock is a lesson. We give you drink from what is in their bellies - between excretion and blood - pure milk, palatable to drinkers.'),
  ('en.sahih', 16, 67, 'And from the fruits of the palm trees and grapevines you take intoxicant and good provision. Indeed in that is a sign for a people who reason.'),
  ('en.sahih', 16, 68, 'And your Lord inspired to the bee, "Take for yourself among the mountains, houses, and among the trees and [in] that which they construct.'),
  ('en.sahih', 16, 69, 'Then eat from all the fruits and follow the ways of your Lord laid down [for you]." There emerges from their bellies a drink, varying in colors, in which there is healing for people. Indeed in that is a sign for a people who give thought.'),
  ('en.sahih', 16, 70, 'And Allah created you; then He will take you in death. And among you is he who is reversed to the most decrepit [old] age so that he will not know, after [having had] knowledge, a thing. Indeed, Allah is Knowing and Competent.'),
  ('en.sahih', 16, 71, 'And Allah has favored some of you over others in provision. But those who were favored would not hand over their provision to those whom their right hands possess so they would be equal to them therein. Then is it the favor of Allah they reject?'),
  ('en.sahih', 16, 72, 'And Allah has made for you from yourselves mates and has made for you from your mates sons and grandchildren and has provided for you from the good things. Then in falsehood do they believe and in the favor of Allah they disbelieve?'),
  ('en.sahih', 16, 73, 'And they worship besides Allah that which does not possess for them [the power of] provision from the heavens and the earth at all, and [in fact], they are unable.'),
  ('en.sahih', 16, 74, 'So do not assert similarities to Allah. Indeed, Allah knows and you do not know.'),
  ('en.sahih', 16, 75, 'Allah presents an example: a slave [who is] owned and unable to do a thing and he to whom We have provided from Us good provision, so he spends from it secretly and publicly. Can they be equal? Praise to Allah! But most of them do not know.'),
  ('en.sahih', 16, 76, 'And Allah presents an example of two men, one of them dumb and unable to do a thing, while he is a burden to his guardian. Wherever he directs him, he brings no good. Is he equal to one who commands justice, while he is on a straight path?'),
  ('en.sahih', 16, 77, 'And to Allah belongs the unseen [aspects] of the heavens and the earth. And the command for the Hour is not but as a glance of the eye or even nearer. Indeed, Allah is over all things competent.'),
  ('en.sahih', 16, 78, 'And Allah has extracted you from the wombs of your mothers not knowing a thing, and He made for you hearing and vision and intellect that perhaps you would be grateful.'),
  ('en.sahih', 16, 79, 'Do they not see the birds controlled in the atmosphere of the sky? None holds them up except Allah. Indeed in that are signs for a people who believe.'),
  ('en.sahih', 16, 80, 'And Allah has made for you from your homes a place of rest and made for you from the hides of the animals tents which you find light on your day of travel and your day of encampment; and from their wool, fur and hair is furnishing and enjoyment for a time.'),
  ('en.sahih', 16, 81, 'And Allah has made for you, from that which He has created, shadows and has made for you from the mountains, shelters and has made for you garments which protect you from the heat and garments which protect you from your [enemy in] battle. Thus does He complete His favor upon you that you might submit [to Him].'),
  ('en.sahih', 16, 82, 'But if they turn away, [O Muhammad] - then only upon you is [responsibility for] clear notification.'),
  ('en.sahih', 16, 83, 'They recognize the favor of Allah; then they deny it. And most of them are disbelievers.'),
  ('en.sahih', 16, 84, 'And [mention] the Day when We will resurrect from every nation a witness. Then it will not be permitted to the disbelievers [to apologize or make excuses], nor will they be asked to appease [Allah].'),
  ('en.sahih', 16, 85, 'And when those who wronged see the punishment, it will not be lightened for them, nor will they be reprieved.'),
  ('en.sahih', 16, 86, 'And when those who associated others with Allah see their "partners," they will say," Our Lord, these are our partners [to You] whom we used to invoke besides You." But they will throw at them the statement, "Indeed, you are liars."'),
  ('en.sahih', 16, 87, 'And they will impart to Allah that Day [their] submission, and lost from them is what they used to invent.'),
  ('en.sahih', 16, 88, 'Those who disbelieved and averted [others] from the way of Allah - We will increase them in punishment over [their] punishment for what corruption they were causing.'),
  ('en.sahih', 16, 89, 'And [mention] the Day when We will resurrect among every nation a witness over them from themselves. And We will bring you, [O Muhammad], as a witness over your nation. And We have sent down to you the Book as clarification for all things and as guidance and mercy and good tidings for the Muslims.'),
  ('en.sahih', 16, 90, 'Indeed, Allah orders justice and good conduct and giving to relatives and forbids immorality and bad conduct and oppression. He admonishes you that perhaps you will be reminded.'),
  ('en.sahih', 16, 91, 'And fulfill the covenant of Allah when you have taken it, [O believers], and do not break oaths after their confirmation while you have made Allah, over you, a witness. Indeed, Allah knows what you do.'),
  ('en.sahih', 16, 92, 'And do not be like she who untwisted her spun thread after it was strong [by] taking your oaths as [means of] deceit between you because one community is more plentiful [in number or wealth] than another community. Allah only tries you thereby. And He will surely make clear to you on the Day of Resurrection that over which you used to differ.'),
  ('en.sahih', 16, 93, 'And if Allah had willed, He could have made you [of] one religion, but He causes to stray whom He wills and guides whom He wills. And you will surely be questioned about what you used to do.'),
  ('en.sahih', 16, 94, 'And do not take your oaths as [means of] deceit between you, lest a foot slip after it was [once] firm, and you would taste evil [in this world] for what [people] you diverted from the way of Allah, and you would have [in the Hereafter] a great punishment.'),
  ('en.sahih', 16, 95, 'And do not exchange the covenant of Allah for a small price. Indeed, what is with Allah is best for you, if only you could know.'),
  ('en.sahih', 16, 96, 'Whatever you have will end, but what Allah has is lasting. And We will surely give those who were patient their reward according to the best of what they used to do.'),
  ('en.sahih', 16, 97, 'Whoever does righteousness, whether male or female, while he is a believer - We will surely cause him to live a good life, and We will surely give them their reward [in the Hereafter] according to the best of what they used to do.'),
  ('en.sahih', 16, 98, 'So when you recite the Qur\'an, [first] seek refuge in Allah from Satan, the expelled [from His mercy].'),
  ('en.sahih', 16, 99, 'Indeed, there is for him no authority over those who have believed and rely upon their Lord.'),
  ('en.sahih', 16, 100, 'His authority is only over those who take him as an ally and those who through him associate others with Allah.'),
  ('en.sahih', 16, 101, 'And when We substitute a verse in place of a verse - and Allah is most knowing of what He sends down - they say, "You, [O Muhammad], are but an inventor [of lies]." But most of them do not know.'),
  ('en.sahih', 16, 102, 'Say, [O Muhammad], "The Pure Spirit has brought it down from your Lord in truth to make firm those who believe and as guidance and good tidings to the Muslims."'),
  ('en.sahih', 16, 103, 'And We certainly know that they say, "It is only a human being who teaches the Prophet." The tongue of the one they refer to is foreign, and this Qur\'an is [in] a clear Arabic language.'),
  ('en.sahih', 16, 104, 'Indeed, those who do not believe in the verses of Allah - Allah will not guide them, and for them is a painful punishment.'),
  ('en.sahih', 16, 105, 'They only invent falsehood who do not believe in the verses of Allah, and it is those who are the liars.'),
  ('en.sahih', 16, 106, 'Whoever disbelieves in Allah after his belief... except for one who is forced [to renounce his religion] while his heart is secure in faith. But those who [willingly] open their breasts to disbelief, upon them is wrath from Allah, and for them is a great punishment;'),
  ('en.sahih', 16, 107, 'That is because they preferred the worldly life over the Hereafter and that Allah does not guide the disbelieving people.'),
  ('en.sahih', 16, 108, 'Those are the ones over whose hearts and hearing and vision Allah has sealed, and it is those who are the heedless.'),
  ('en.sahih', 16, 109, 'Assuredly, it is they, in the Hereafter, who will be the losers.'),
  ('en.sahih', 16, 110, 'Then, indeed your Lord, to those who emigrated after they had been compelled [to renounce their religion] and thereafter fought [for the cause of Allah] and were patient - indeed, your Lord, after that, is Forgiving and Merciful'),
  ('en.sahih', 16, 111, 'On the Day when every soul will come disputing for itself, and every soul will be fully compensated for what it did, and they will not be wronged.'),
  ('en.sahih', 16, 112, 'And Allah presents an example: a city which was safe and secure, its provision coming to it in abundance from every location, but it denied the favors of Allah. So Allah made it taste the envelopment of hunger and fear for what they had been doing.'),
  ('en.sahih', 16, 113, 'And there had certainly come to them a Messenger from among themselves, but they denied him; so punishment overtook them while they were wrongdoers.'),
  ('en.sahih', 16, 114, 'Then eat of what Allah has provided for you [which is] lawful and good. And be grateful for the favor of Allah, if it is [indeed] Him that you worship.'),
  ('en.sahih', 16, 115, 'He has only forbidden to you dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah. But whoever is forced [by necessity], neither desiring [it] nor transgressing [its limit] - then indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 16, 116, 'And do not say about what your tongues assert of untruth, "This is lawful and this is unlawful," to invent falsehood about Allah. Indeed, those who invent falsehood about Allah will not succeed.'),
  ('en.sahih', 16, 117, '[It is but] a brief enjoyment, and they will have a painful punishment.'),
  ('en.sahih', 16, 118, 'And to those who are Jews We have prohibited that which We related to you before. And We did not wrong them [thereby], but they were wronging themselves.'),
  ('en.sahih', 16, 119, 'Then, indeed your Lord, to those who have done wrong out of ignorance and then repent after that and correct themselves - indeed, your Lord, thereafter, is Forgiving and Merciful.'),
  ('en.sahih', 16, 120, 'Indeed, Abraham was a [comprehensive] leader, devoutly obedient to Allah, inclining toward truth, and he was not of those who associate others with Allah.'),
  ('en.sahih', 16, 121, '[He was] grateful for His favors. Allah chose him and guided him to a straight path.'),
  ('en.sahih', 16, 122, 'And We gave him good in this world, and indeed, in the Hereafter he will be among the righteous.'),
  ('en.sahih', 16, 123, 'Then We revealed to you, [O Muhammad], to follow the religion of Abraham, inclining toward truth; and he was not of those who associate with Allah.'),
  ('en.sahih', 16, 124, 'The sabbath was only appointed for those who differed over it. And indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.'),
  ('en.sahih', 16, 125, 'Invite to the way of your Lord with wisdom and good instruction, and argue with them in a way that is best. Indeed, your Lord is most knowing of who has strayed from His way, and He is most knowing of who is [rightly] guided.'),
  ('en.sahih', 16, 126, 'And if you punish [an enemy, O believers], punish with an equivalent of that with which you were harmed. But if you are patient - it is better for those who are patient.'),
  ('en.sahih', 16, 127, 'And be patient, [O Muhammad], and your patience is not but through Allah. And do not grieve over them and do not be in distress over what they conspire.'),
  ('en.sahih', 16, 128, 'Indeed, Allah is with those who fear Him and those who are doers of good.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 16, 1, 'আল্লাহর নির্দেশ এসে গেছে। অতএব এর জন্যে তাড়াহুড়া করো না। ওরা যেসব শরীক সাব্যস্ত করছে সেসব থেকে তিনি পবিত্র ও বহু উর্ধ্বে।'),
  ('bn.bengali', 16, 2, 'তিনি স্বীয় নির্দেশে বান্দাদের মধ্যে যার কাছে ইচ্ছা, নির্দেশসহ ফেরেশতাদেরকে এই মর্মে নাযিল করেন যে, হুশিয়ার করে দাও, আমি ছাড়া কোন উপাস্য নেই। অতএব আমাকে ভয় কর।'),
  ('bn.bengali', 16, 3, 'যিনি যথাবিধি আকাশরাজি ও ভূ-মন্ডল সৃষ্টি করেছেন। তারা যাকে শরীক করে তিনি তার বহু উর্ধ্বে।'),
  ('bn.bengali', 16, 4, 'তিনি মানবকে এক ফোটা বীর্য থেকে সৃষ্টি করেছেন। এতদসত্বেও সে প্রকাশ্য বিতন্ডাকারী হয়ে গেছে।'),
  ('bn.bengali', 16, 5, 'চতুষ্পদ জন্তুকে তিনি সৃষ্টি করেছেন। এতে তোমাদের জন্যে শীত বস্ত্রের উপকরণ আছে। আর অনেক উপকার হয়েছে এবং কিছু সংখ্যককে তোমরা আহার্যে?2474;রিণত করে থাক।'),
  ('bn.bengali', 16, 6, 'এদের দ্বারা তোমাদের সম্মান হয়, যখন বিকালে চারণভূমি থেকে নিয়ে আস এবং সকালে চারণ ভূমিতে নিয়ে যাও।'),
  ('bn.bengali', 16, 7, 'এরা তোমাদের বোঝা এমন শহর পর্যন্ত বহন করে নিয়ে যায়, যেখানে তোমরা প্রাণান্তকর পরিশ্রۦ#2478; ব্যতীত পৌছাতে পারতে না। নিশ্চয় তোমাদের প্রভু অত্যন্ত দয়াদ্র, পরম দয়ালু।'),
  ('bn.bengali', 16, 8, 'তোমাদের আরোহণের জন্যে এবং শোভার জন্যে তিনি ঘোড়া, খচ্চর ও গাধা সৃষ্টি করেছেন। আর তিনি এমন জিনিস সৃষ্টি করেন যা তোমরা জান না।'),
  ('bn.bengali', 16, 9, 'সরল পথ আল্লাহ পর্যন্ত পৌছে এবং পথগুলোর মধ্যে কিছু বক্র পথও রয়েছে। তিনি ইচ্ছা করলে তোমাদের সবাইকে সৎপথে পরিচালিত করতে পারতেন।'),
  ('bn.bengali', 16, 10, 'তিনি তোমাদের জন্যে আকাশ থেকে পানি বর্ষণ করেছেন। এই পানি থেকে তোমরা পান কর এবং এ থেকেই উদ্ভিদ উৎপন্ন হয়, যাতে তোমরা পশুচারণ কর।'),
  ('bn.bengali', 16, 11, 'এ পানি দ্বারা তোমাদের জন্যে উৎপাদন করেন ফসল, যয়তুন, খেজুর, আঙ্গুর ও সর্বপ্রকার ফল। নিশ্চয় এতে চিন্তাশীলদের জন্যে নিদর্শন রয়েছে।'),
  ('bn.bengali', 16, 12, 'তিনিই তোমাদের কাজে নিয়োজিত করেছেন রাত্রি, দিন, সূর্য এবং চন্দ্রকে। তারকাসমূহ তাঁরই বিধানের কর্মে নিয়োজিত রয়েছে। নিশ্চয়ই এতে বোধশক্তিসম্পন্নদের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 16, 13, 'তোমাদের জন্যে পৃথিবীতে যেসব রং-বেরঙের বস্তু ছড়িয়ে দিয়েছেন, সেগুলোতে নিদর্শন রয়েছে তাদের জন্যে যারা চিন্তা-ভাবনা করে।'),
  ('bn.bengali', 16, 14, 'তিনিই কাজে লাগিয়ে দিয়েছেন সমুদ্রকে, যাতে তা থেকে তোমরা তাজা মাংস খেতে পার এবং তা থেকে বের করতে পার পরিধেয় অলঙ্কার। তুমি তাতে জলযান সমূহকে পানি চিরে চলতে দেখবে এবং যাতে তোমরা আল্লাহর কৃপা অন্বেষণ কর এবং যাতে তার অনুগ্রহ স্বীকার কর।'),
  ('bn.bengali', 16, 15, 'এবং তিনি পৃথিবীর উপর বোঝা রেখেছেন যে, কখনো যেন তা তোমাদেরকে নিয়ে হেলে-দুলে না পড়ে এবং নদী ও পথ তৈরী করেছেন, যাতে তোমরা পথ প্রদর্শিত হও।'),
  ('bn.bengali', 16, 16, 'এবং তিনি পথ নির্ণয়ক বহু চিহ্ন সৃষ্টি করেছেন, এবং তারকা দ্বারা ও মানুষ পথের নির্দেশ পায়।'),
  ('bn.bengali', 16, 17, 'যিনি সৃষ্টি করে, তিনি কি সে লোকের সমতুল্য যে সৃষ্টি করতে পারে না? তোমরা কি চিন্তা করবে না?'),
  ('bn.bengali', 16, 18, 'যদি আল্লাহর নেয়ামত গণনা কর, শেষ করতে পারবে না। নিশ্চয় আল্লাহ ক্ষমাশীল, দয়ালু।'),
  ('bn.bengali', 16, 19, 'আল্লাহ জানেন যা তোমরা গোপন কর এবং যা তোমরা প্রকাশ কর।'),
  ('bn.bengali', 16, 20, 'এবং যারা আল্লাহকে ছেড়ে অন্যদের ডাকে, ওরা তো কোন বস্তুই সৃষ্টি করে না; বরং ওরা নিজেরাই সৃজিত।'),
  ('bn.bengali', 16, 21, 'তারা মৃত-প্রাণহীন এবং কবে পুনরুত্থিত হবে, জানে না।'),
  ('bn.bengali', 16, 22, 'আমাদের ইলাহ একক ইলাহ। অনন্তর যারা পরজীবনে বিশ্বাস করে না, তাদের অন্তর সত্যবিমুখ এবং তারা অহংকার প্রদর্শন করেছে।'),
  ('bn.bengali', 16, 23, 'নিঃসন্দেহে আল্লাহ তাদের গোপন ও প্রকাশ্য যাবতীয় বিষয়ে অবগত। নিশ্চিতই তিনি অহংকারীদের পছন্দ করেন না।'),
  ('bn.bengali', 16, 24, 'যখন তাদেরকে বলা হয়ঃ তোমাদের পালনকর্তা কি নাযিল করেছেন? তারা বলেঃ পূর্ববর্তীদের কিসসা-কাহিনী।'),
  ('bn.bengali', 16, 25, 'ফলে কেয়ামতের দিন ওরা পূর্ণমাত্রায় বহন করবে ওদের পাপভার এবং পাপভার তাদেরও যাদেরকে তারা তাদের অজ্ঞতাহেতু বিপথগামী করে শুনে নাও, খুবই নিকৃষ্ট বোঝা যা তারা বহন করে।'),
  ('bn.bengali', 16, 26, 'নিশ্চয় চক্রান্ত করেছে তাদের পূর্ববর্তীরা, অতঃপর আল্লাহ তাদের চক্রান্তের ইমারতের ভিত্তিমূলে আঘাত করেছিলেন। এরপর উপর থেকে তাদের মাথায় ছাদ ধ্বসে পড়ে গেছে এবং তাদের উপর আযাব এসেছে যেখান থেকে তাদের ধারণা ছিল না।'),
  ('bn.bengali', 16, 27, 'অতঃপর কেয়ামতের দিন তিনি তাদেরকে লাঞ্ছিত করবেন এবং বলবেনঃ আমার অংশীদাররা কোথায়, যাদের ব্যাপারে তোমরা খুব হঠকারিতা করতে ? যারা জ্ঞানপ্রাপ্ত হয়েছিল তারা বলবেঃ নিশ্চয়ই আজকের দিনে লাঞ্ছনা ও দুর্গতি কাফেরদের জন্যে,'),
  ('bn.bengali', 16, 28, 'ফেরেশতারা তাদের জান এমতাঅবস্থায় কবজ করে যে, তারা নিজেদের উপর যুলুম করেছে। তখন তারা অনুগত্য প্রকাশ করবে যে, আমরা তো কোন মন্দ কাজ করতাম না। হঁ্যা নিশ্চয় আল্লাহ সববিষয় অবগত আছেন, যা তোমরা করতে।'),
  ('bn.bengali', 16, 29, 'অতএব, জাহান্নামের দরজসমূহে প্রবেশ কর, এতেই অনন্তকাল বাস কর। আর অহংকারীদের আবাসস্থল কতই নিকৃষ্ট।'),
  ('bn.bengali', 16, 30, 'পরহেযগারদেরকে বলা হয়ঃ তোমাদের পালনকর্তা কি নাযিল করেছেন? তারা বলেঃ মহাকল্যাণ। যারা এ জগতে সৎকাজ করে, তাদের জন্যে কল্যাণ রয়েছে এবং পরকালের গৃহ আরও উত্তম। পরহেযগারদের গৃহ কি চমৎকার?'),
  ('bn.bengali', 16, 31, 'সর্বদা বসবাসের উদ্যান, তারা যাতে প্রবেশ করবে। এর পাদদেশে দিয়ে স্রোতস্বিনী প্রবাহিত হয় তাদের জন্যে তাতে তা-ই রয়েছে, যা তারা চায় এমনিভাবে প্রতিদান দেবেন আল্লাহর পরহেযগারদেরকে,'),
  ('bn.bengali', 16, 32, 'ফেরেশতা যাদের জান কবজ করেন তাদের পবিত্র থাকা অবস্থায়। ফেরেশতারা বলেঃ তোমাদের প্রতি শাস্তি বর্ষিত হোক। তোমরা যা করতে, তার প্রতিদানে জান্নাতে প্রবেশ কর।'),
  ('bn.bengali', 16, 33, 'কাফেররা কি এখন অপেক্ষা করছে যে, তাদের কাছে ফেরেশতারা আসবে কিংবা আপনার পালনকর্তার নির্দেশ পৌছবে? তাদের পূর্ববর্তীরা এমনই করেছিল। আল্লাহ তাদের প্রতি অবিচার করেননি; কিন্তু তারা স্বয়ং নিজেদের প্রতি জুলুম করেছিল।'),
  ('bn.bengali', 16, 34, 'সুতরাং তাদের মন্দ কাজের শাস্তি তাদেরই মাথায় আপতিত হয়েছে এবং তারা যে ঠাট্টা বিদ্রুপ করত, তাই উল্টে তাদের উপর পড়েছে।'),
  ('bn.bengali', 16, 35, 'মুশরিকরা বললঃ যদি আল্লাহ চাইতেন, তবে আমরা তাঁকে ছাড়া কারও এবাদত করতাম না এবং আমাদের পিতৃপুরুষেরাও করত না এবং তাঁর নির্দেশ ছাড়া কোন বস্তুই আমরা হারাম করতাম না। তাদের পূর্ববর্তীরা এমনই করেছে। রাসূলের দায়িত্ব তো শুধুমাত্র সুস্পষ্ট বাণী পৌছিয়ে দেয়া।'),
  ('bn.bengali', 16, 36, 'আমি প্রত্যেক উম্মতের মধ্যেই রাসূল প্রেরণ করেছি এই মর্মে যে, তোমরা আল্লাহর এবাদত কর এবং তাগুত থেকে নিরাপদ থাক। অতঃপর তাদের মধ্যে কিছু সংখ্যককে আল্লাহ হেদায়েত করেছেন এবং কিছু সংখ্যকের জন্যে বিপথগামিতা অবধারিত হয়ে গেল। সুতরাং তোমরা পৃথিবীতে ভ্রমণ কর এবং দেখ মিথ্যারোপকারীদের কিরূপ পরিণতি হয়েছে।'),
  ('bn.bengali', 16, 37, 'আপনি তাদেরকে সুপথে আনতে আগ্রহী হলেও আল্লাহ যাকে বিপথগামী করেন তিনি তাকে পথ দেখান না এবং তাদের কোন সাহায্যকারী ও নেই।'),
  ('bn.bengali', 16, 38, 'তারা আল্লাহর নামে কঠোর শপথ করে যে, যার মৃত্যু হয় আল্লাহ তাকে পুনরুজ্জীবিত করবেন না। অবশ্যই এর পাকাপোক্ত ওয়াদা হয়ে গেছে। কিন্তু, অধিকাংশ লোক জানে না।'),
  ('bn.bengali', 16, 39, 'তিনি পুনরুজ্জীবিত করবেনই, যাতে যে বিষয়ে তাদের মধ্যে মতানৈক্য ছিল তা প্রকাশ করা যায় এবং যাতে কাফেরেরা জেনে নেয় যে, তারা মিথ্যাবাদী ছিল।'),
  ('bn.bengali', 16, 40, 'আমি যখন কোন কিছু করার ইচ্ছা করি; তখন তাকে কেবল এতটুকুই বলি যে, হয়ে যাও,। সুতরাং তা হয়ে যায়।'),
  ('bn.bengali', 16, 41, 'যারা নির্যাতিত হওয়ার পর আল্লাহর জন্যে গৃহত্যাগ করেছে, আমি অবশ্যই তাদেরকে দুনিয়াতে উত্তম আবাস দেব এবং পরকালের পুরস্কার তো সর্বাধিক; হায়! যদি তারা জানত।'),
  ('bn.bengali', 16, 42, 'যারা দৃঢ়পদ রয়েছে এবং তাদের পালনকর্তার উপর ভরসা করেছে।'),
  ('bn.bengali', 16, 43, 'আপনার পূর্বেও আমি প্রত্যাদেশসহ মানবকেই তাদের প্রতি প্রেরণ করেছিলাম অতএব জ্ঞানীদেরকে জিজ্ঞেস কর, যদি তোমাদের জানা না থাকে;'),
  ('bn.bengali', 16, 44, 'প্রেরণ করেছিলাম তাদেরকে নিꦣ2503;দশাবলী ও অবতীর্ণ গ্রন্থসহ এবং আপনার কাছে আমি স্মরণিকা অবতীর্ণ করেছি, যাতে আপনি লোকদের সামনে ঐসব বিষয় বিবৃত করেন, যে গুলো তোদের প্রতি নাযিল করা হয়েছে, যাতে তারা চিন্তা-ভাবনা করে।'),
  ('bn.bengali', 16, 45, 'যারা কুচক্র করে, তারা কি এ বিষয়ে ভয় করে না যে, আল্লাহ তাদেরকে ভূগর্ভে বিলীন করে দিবেন কিংবা তাদের কাছে এমন জায়গা থেকে আযাব আসবে যা তাদের ধারণাতীত।'),
  ('bn.bengali', 16, 46, 'কিংবা চলাফেরার মধ্যেই তাদেরকে পাকড়াও করবে, তারা তো তা ব্যর্থ করতে পারবে না।'),
  ('bn.bengali', 16, 47, 'কিংবা ভীতি প্রদর্শনের পর তাদেরকে পাকড়াও করবেন? তোমাদের পালনকর্তা তো অত্যন্ত নম্র, দয়ালু।'),
  ('bn.bengali', 16, 48, 'তারা কি আল্লাহর সৃজিত বস্তু দেখে না, যার ছায়া আল্লাহর প্রতি বিনীতভাবে সেজদাবনত থেকে ডান ও বাম দিকে ঝুঁকে পড়ে।'),
  ('bn.bengali', 16, 49, 'আল্লাহকে সেজদা করে যা কিছু নভোমন্ডলে আছে এবং যা কিছু ভুমন্ডলে আছে এবং ফেরেশতাগণ; তারা অহংকার করে না।'),
  ('bn.bengali', 16, 50, 'তারা তাদের উপর পরাক্রমশালী তাদের পালনকর্তাকে ভয় করে এবং তারা যা আদেশ পায়, তা করে'),
  ('bn.bengali', 16, 51, 'আল্লাহ বললেনঃ তোমরা দুই উপাস্য গ্রহণ করো না উপাস্য তো মাত্র একজনই। অতএব আমাকেই ভয় কর।'),
  ('bn.bengali', 16, 52, 'যা কিছু নভোমন্ডল ও ভুমন্ডলে আছে তা তাঁরই এবাদত করা শাশ্বত কর্তব্য। তোমরা কি আল্লাহ ব্যতীত কাউকে ভয় করবে?'),
  ('bn.bengali', 16, 53, 'তোমাদের কাছে যে সমস্ত নেয়ামত আছে, তা আল্লাহরই পক্ষ থেকে। অতঃপর তোমরা যখন দুঃখে-কষ্টে পতিত হও তখন তাঁরই নিকট কান্নাকাটি কর।'),
  ('bn.bengali', 16, 54, 'এরপর যখন আল্লাহ তোমাদের কষ্ট দুরীভূত করে দেন, তখনই তোমাদের একদল স্বীয় পালনকর্তার সাথে অংশীদার সাব্যস্ত করতে থাকে।'),
  ('bn.bengali', 16, 55, 'যাতে ঐ নেয়ামত অস্বীকার করে, যা আমি তাদেরকে দিয়েছি। অতএব মজা ভোগ করে নাও-সত্বরই তোমরা জানতে পারবে।'),
  ('bn.bengali', 16, 56, 'তারা আমার দেয়া জীবনোপকরণ থেকে তাদের জন্যে একটি অংশ নির্ধারিত করে, যাদের কোন খবরই তারা রাখে না। আল্লাহর কসম, তোমরা যে অপবাদ আরোপ করছ, সে সম্পর্কে অবশ্যই জিজ্ঞাসিত হবে।'),
  ('bn.bengali', 16, 57, 'তারা আল্লাহর জন্যে কন্যা সন্তান নির্ধারণ করে-তিনি পবিত্র মহিমান্বিত এবং নিজেদের জন্যে ওরা তাই স্থির করে যা ওরা চায়।'),
  ('bn.bengali', 16, 58, 'যখন তাদের কাউকে কন্যা সন্তানের সুসংবাদ দেয়া হয়, তখন তারা মুখ কাল হয়ে যায় এবং অসহ্য মনস্তাপে ক্লিষ্ট হতে থাকে।'),
  ('bn.bengali', 16, 59, 'তাকে শোনানো সুসংবাদের দুঃখে সে লোকদের কাছ থেকে মুখ লুকিয়ে থাকে। সে ভাবে, অপমান সহ্য করে তাকে থাকতে দেবে, না তাকে মাটির নীচে পুতে ফেলবে। শুনে রাখ, তাদের ফয়সালা খুবই নিকৃষ্ট।'),
  ('bn.bengali', 16, 60, 'যারা পরকাল বিশ্বাস করে না, তাদের উদাহরণ নিকৃষ্ট এবং আল্লাহর উদাহরণই মহান, তিনি পরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 16, 61, 'যদি আল্লাহ লোকদেরকে তাদের অন্যায় কাজের কারণে পাকড়াও করতেন, তবে ভুপৃষ্ঠে চলমান কোন কিছুকেই ছাড়তেন না। কিন্তু তিনি প্রতিশ্রুতি সময় পর্যন্ত তাদেরকে অবকাশ দেন। অতঃপর নির্ধারিত সময়ে যখন তাদের মৃত্যু এসে যাবে, তখন এক মুহুর্তও বিলম্বিত কিংবা তরাম্বিত করতে পারবে না।'),
  ('bn.bengali', 16, 62, 'যা নিজেদের মন চায় না তারই তারা আল্লাহর জন্যে সাব্যস্ত করে এবং তাদের জিহবা মিথ্যা বর্ণনা করে যে, তাদের জন্যে রয়েছে কল্যাণ। স্বতঃসিদ্ধ কথা যে, তাদের জন্যে রয়েছে আগুন এবং তাদেরকেই সর্বাগ্রে নিক্ষেপ করা হবে।'),
  ('bn.bengali', 16, 63, 'আল্লাহর কসম, আমি আপনার পূর্বে বিভিন্ন সম্প্রদায়ে রাসূল প্রেরণ করেছি, অতঃপর শয়তান তাদেরকে কর্ম সমূহ শোভনীয় করে দেখিয়েছে। আজ সেই তাদের অভিভাবক এবং তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 16, 64, 'আমি আপনার প্রতি এ জন্যেই গ্রন্থ নাযিল করেছি, যাতে আপনি সরল পথ প্রদর্শনের জন্যে তাদের কে পরিষ্কার বর্ণনা করে দেন, যে বিষয়ে তারা মতবিরোধ করছে এবং ঈমানদারকে ক্ষমা করার জন্যে।'),
  ('bn.bengali', 16, 65, 'আল্লাহ আকাশ থেকে পানি বর্ষণ করেছেন, তদ্বারা যমীনকে তার মৃত্যুর পর পুনর্জীবিত করেছেন। নিশ্চয় এতে তাদের জন্যে নিদর্শন রয়েছে, যারা শ্রবণ করে।'),
  ('bn.bengali', 16, 66, 'তোমাদের জন্যে চতুস্পদ জন্তুদের মধ্যে চিন্তা করার অবকাশ রয়েছে। আমি তোমাদেরকে পান করাই তাদের উদরস্থিত বস্তুসমুহের মধ্যে থেকে গোবর ও রক্ত নিঃসৃত দুগ্ধ যা পানকারীদের জন্যে উপাদেয়।'),
  ('bn.bengali', 16, 67, 'এবং খেজুর বৃক্ষ ও আঙ্গুর ফল থেকে তোমরা মধ্য ও উত্তম খাদ্য তৈরী করে থাক, এতে অবশ্যই বোধশক্তি সম্পন্ন সম্প্রদায়ের জন্যে নিদর্শন রয়েছে।'),
  ('bn.bengali', 16, 68, 'আপনার পালনকর্তা মধু মক্ষিকাকে আদেশ দিলেনঃ পর্বতগাহ্রে, বৃক্ষ এবং উঁচু চালে গৃহ তৈরী কর,'),
  ('bn.bengali', 16, 69, 'এরপর সর্বপ্রকার ফল থেকে ভক্ষণ কর এবং আপন পালনকর্তার উম্মুক্ত পথ সমূহে চলমান হও। তার পেট থেকে বিভিন্ন রঙে পানীয় নির্গত হয়। তাতে মানুষের জন্যে রয়েছে রোগের প্রতিকার। নিশ্চয় এতে চিন্তাশীল সম্প্রদায়ের জন্যে নিদর্শন রয়েছে।'),
  ('bn.bengali', 16, 70, 'আল্লাহ তোমাদেরকে সৃষ্টি করেছেন এরপর তোমাদের মৃত্যুদান করেন। তোমাদের মধ্যে কেউ কেউ পৌছে যায় জরাগ্রস্ত অকর্মন্য বয়সে, ফলে যা কিছু তারা জানত সে সম্পর্কে তারা সজ্ঞান থাকবে না। নিশ্চয় আল্লাহ সু-বিজ্ঞ সর্বশক্তিমান।'),
  ('bn.bengali', 16, 71, 'আল্লাহ তা’আলা জীবনোপকরণে তোমাদের একজনকে অন্যজনের চাইতে শ্রেষ্টত্ব দিয়েছেন। অতএব যাদেরকে শ্রেষ্ঠত্ব দেয়া হয়েছে, তারা তাদের অধীনস্থ দাস-দাসীদেরকে স্বীয় জীবিকা থেকে এমন কিছু দেয় না, যাতে তারা এ বিষয়ে তাদের সমান হয়ে যাবে। তবে কি তারা আল্লাহর নেয়ামত অস্বীকার করে।'),
  ('bn.bengali', 16, 72, 'আল্লাহ তোমাদের জন্যে তোমাদেরই শ্রেণী থেকে জোড়া পয়দা করেছেন এবং তোমাদের যুগল থেকে তোমাদেরকে পুত্র ও পৌত্রাদি দিয়েছেন এবং তোমাদেরকে উত্তম জীবনোপকরণ দান করেছেন। অতএব তারা কি মিথ্যা বিষয়ে বিশ্বাস স্থাপন করে এবং আল্লাহর অনুগ্রহ অস্বীকার করে?'),
  ('bn.bengali', 16, 73, 'তারা আল্লাহ ব্যতীত এমন বস্তুর ইবাদত করে, যে তাদের জন্যে ভুমন্ডল ও নভোমন্ডল থেকে সামান্য রুযী দেওয়ার ও অধিকার রাখে না এবং মুক্তি ও রাখে না।'),
  ('bn.bengali', 16, 74, 'অতএব, আল্লাহর কোন সদৃশ সাব্যস্ত করো না, নিশ্চয় আল্লাহ জানেন এবং তোমরা জান না।'),
  ('bn.bengali', 16, 75, 'আল্লাহ একটি দৃষ্টান্ত বর্ণনা করেছেন, অপরের মালিকানাধীন গোলামের যে, কোন কিছুর উপর শক্তি রাখে না এবং এমন একজন যাকে আমি নিজের পক্ষ থেকে চমৎকার রুযী দিয়েছি। অতএব, সে তা থেকে ব্যয় করে গোপনে ও প্রকাশ্যে উভয়ে কি সমান হয়? সব প্রশংসা আল্লাহর, কিন্তু অনেক মানুষ জানে না।'),
  ('bn.bengali', 16, 76, 'আল্লাহ আরেকটি দৃষ্টান্ত বর্ণনা করেছেন, দু’ব্যক্তির, একজন বোবা কোন কাজ করতে পারে না। সে মালিকের উপর বোঝা। যেদিকে তাকে পাঠায়, কোন সঠিক কাজ করে আসে না। সে কি সমান হবে ঐ ব্যক্তির, যে ন্যায় বিচারের আদেশ করে এবং সরল পথে কায়েম রয়েছে।'),
  ('bn.bengali', 16, 77, 'নভোমন্ডল ও ভূমন্ডলের গোপন রহস্য আল্লাহর কাছেই রয়েছে। কিয়ামতের ব্যাপারটি তো এমন, যেমন চোখের পলক অথবা তার চাইতেও নিকটবর্তী। নিশ্চয় আল্লাহ সব কিছুর উপর শক্তিমান।'),
  ('bn.bengali', 16, 78, 'আল্লাহ তোমাদেরকে তোমাদের মায়ের গর্ভ থেকে বের করেছেন। তোমরা কিছুই জানতে না। তিনি তোমাদেরকে কর্ণ, চক্ষু ও অন্তর দিয়েছেন, যাতে তোমরা অনুগ্রহ স্বীকার কর।'),
  ('bn.bengali', 16, 79, 'তারা কি উড়ন্ত পাখীকে দেখে না? এগুলো আকাশের অন্তরীক্ষে আজ্ঞাধীন রয়েছে। আল্লাহ ছাড়া কেউ এগুলোকে আগলে রাখে না। নিশ্চয় এতে বিশ্বাসীদের জন্যে নিদর্শনবলী রয়েছে।'),
  ('bn.bengali', 16, 80, 'আল্লাহ করে দিয়েছেন তোমাদের গৃহকে অবস্থানের জায়গা এবং চতুস্পদ জন্তুর চামড়া দ্বারা করেছেন তোমার জন্যে তাঁবুর ব্যবস্থা। তোমরা এগুলোকে সফরকালে ও অবস্থান কালে পাও। ভেড়ার পশম, উটের বাবরি চুল ও ছাগলের লোম দ্বারা কত আসবাবপত্র ও ব্যবহারের সামগ্রী তৈরী করেছেন এক নির্দিষ্ট সময় পর্যন্ত।'),
  ('bn.bengali', 16, 81, 'আল্লাহ তোমাদের জন্যে সৃজিত বস্তু দ্বারা ছায়া করে দিয়েছেন এবং পাহাড় সমূহে তোমাদের জন্যে আত্ন গোপনের জায়গা করেছেন এবং তোমাদের জন্যে পোশাক তৈরী করে দিয়েছেন, যা তোমাদেরকে গ্রীষ্ম এবং বিপদের সময় রক্ষা করে। এমনিভাবে তিনি তোমাদের প্রতি স্বীয় অনুগ্রহের পূর্ণতা দান করেন, যাতে তোমরা আত্নসমর্পণ কর।'),
  ('bn.bengali', 16, 82, 'অতঃপর যদি তারা পৃষ্ঠ প্রদর্শন করে, তবে আপনার কাজ হল সুস্পষ্ট ভাবে পৌছে দেয়া মাত্র।'),
  ('bn.bengali', 16, 83, 'তারা আল্লাহর অনুগ্রহ চিনে, এরপর অস্বীকার করে এবং তাদের অধিকাংশই অকৃতজ্ঞ।'),
  ('bn.bengali', 16, 84, 'যেদিন আমি প্রত্যেক উম্মত থেকে একজন বর্ণনাকারী দাঁড় করাব, তখন কাফেরদেরকে অনুমতি দেয়া হবে না এবং তাদের তওবা ও গ্রহণ করা হবে না।'),
  ('bn.bengali', 16, 85, 'যখন জালেমরা আযাব প্রত্যক্ষ করবে, তখন তাদের থেকে তা লঘু করা হবে না এবং তাদেরকে কোন অবকাশ দেয়া হবে না।'),
  ('bn.bengali', 16, 86, 'মুশরিকরা যখন ঐ সব বস্তুকে দেখবে, যেসবকে তারা আল্লাহর সাথে শরীক সাব্যস্ত করেছিল, তখন বলবেঃ হে আমাদের পালনকর্তা এরাই তারা যারা আমাদের শেরেকীর উপাদান, তোমাকে ছেড়ে আমরা যাদেরকে ডাকতাম। তখন ওরা তাদেরকে বলবেঃ তোমরা মিথ্যাবাদী।'),
  ('bn.bengali', 16, 87, 'সেদিন তারা আল্লাহর সামনে আত্নসমর্পন করবে এবং তারা যে মিথ্যা অপবাদ দিত তা বিস্মৃত হবে।'),
  ('bn.bengali', 16, 88, 'যারা কাফের হয়েছে এবং আল্লাহর পথে বাধা সৃষ্টি করেছে, আমি তাদেরকে আযাবের পর আযাব বাড়িয়ে দেব। কারণ, তারা অশান্তি সৃষ্টি করত।'),
  ('bn.bengali', 16, 89, 'সেদিন প্রত্যেক উম্মতের মধ্যে আমি একজন বর্ণনাকারী দাঁড় করাব তাদের বিপক্ষে তাদের মধ্য থেকেই এবং তাদের বিষয়ে আপনাকে সাক্ষী স্বরূপ উপস্থাপন করব। আমি আপনার প্রতি গ্রন্থ নাযিল করেছি যেটি এমন যে তা প্রত্যেক বস্তুর সুস্পষ্ট বর্ণনা, হেদায়েত, রহমত এবং মুসলমানদের জন্যে সুসংবাদ।'),
  ('bn.bengali', 16, 90, 'আল্লাহ ন্যায়পরায়ণতা, সদাচরণ এবং আত্নীয়-স্বজনকে দান করার আদেশ দেন এবং তিনি অশ্লীলতা, অসঙ্গত কাজ এবং অবাধ্যতা করতে বারণ করেন। তিনি তোমাদের উপদেশ দেন যাতে তোমরা স্মরণ রাখ।'),
  ('bn.bengali', 16, 91, 'আল্লাহর নামে অঙ্গীকার করার পর সে অঙ্গীকার পূর্ণ কর এবং পাকাপাকি কসম করার পর তা ভঙ্গ করো না, অথচ তোমরা আল্লাহকে জামিন করেছ। তোমরা যা কর আল্লাহ তা জানেন।'),
  ('bn.bengali', 16, 92, 'তোমরা ঐ মহিলার মত হয়ো না, যে পরিশ্রমের পর কাটা সূতা টুকরো টুকরো করে ছিড়ে ফেলে, তোমরা নিজেদের কসমসমূহকে পারস্পরিক প্রবঞ্চনার বাহানা রূপে গ্রহণ কর এজন্যে যে, অন্য দল অপেক্ষা এক দল অধিক ক্ষমতাবান হয়ে যায়। এতদ্বারা তো আল্লাহ শুধু তোমাদের পরীক্ষা করেন। আল্লাহ অবশ্যই কিয়ামতের দিন প্রকাশ করে দেবেন, যে বিষয়ে তোমরা কলহ করতে।'),
  ('bn.bengali', 16, 93, 'আল্লাহ ইচ্ছা করলে তোমাদের সবাইকে এক জাতি করে দিতে পারতেন, কিন্তু তিনি যাকে ইচ্ছা বিপথগামী করেন এবং যাকে ইচ্ছা পথ প্রদর্শন করেন। তোমরা যা কর সে বিষয়ে অবশ্যই জিজ্ঞাসিত হবে।'),
  ('bn.bengali', 16, 94, 'তোমরা স্বীয় কসমসমূহকে পারস্পরিক কলহ দ্বন্দ্বের বাহানা করো না। তা হলে দৃঢ়ভাবে প্রতিষ্ঠিত হওয়ার পর পা ফসকে যাবে এবং তোমরা শাস্তির স্বাদ আস্বাদন করবে এ কারণে যে, তোমরা আমার পথে বাধা দান করেছ এবং তোমাদের কঠোর শাস্তি হবে।'),
  ('bn.bengali', 16, 95, 'তোমরা আল্লাহর অঙ্গীকারের বিনিময়ে সামান্য মূল্য গ্রহণ করো না। নিশ্চয় আল্লাহর কাছে যা আছে, তা উত্তম তোমাদের জন্যে, যদি তোমরা জ্ঞানী হও।'),
  ('bn.bengali', 16, 96, 'তোমাদের কাছে যা আছে নিঃশেষ হয়ে যাবে এবং আল্লাহর কাছে যা আছে, কখনও তা শেষ হবে না। যারা সবর করে, আমি তাদেরকে প্রাপ্য প্রতিদান দেব তাদের উত্তম কর্মের প্রতিদান স্বরূপ যা তারা করত।'),
  ('bn.bengali', 16, 97, 'যে সৎকর্ম সম্পাদন করে এবং সে ঈমাণদার, পুরুষ হোক কিংবা নারী আমি তাকে পবিত্র জীবন দান করব এবং প্রতিদানে তাদেরকে তাদের উত্তম কাজের কারণে প্রাপ্য পুরষ্কার দেব যা তারা করত।'),
  ('bn.bengali', 16, 98, 'অতএব, যখন আপনি কোরআন পাঠ করেন তখন বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় গ্রহণ করুন।'),
  ('bn.bengali', 16, 99, 'তার আধিপত্য চলে না তাদের উপর যারা বিশ্বাস স্থাপন করে এবং আপন পালন কর্তার উপর ভরসা রাখে।'),
  ('bn.bengali', 16, 100, 'তার আধিপত্য তো তাদের উপরই চলে, যারা তাকে বন্ধু মনে করে এবং যারা তাকে অংশীদার মানে।'),
  ('bn.bengali', 16, 101, 'এবং যখন আমি এক আয়াতের স্থলে অন্য আয়াত উপস্থিত করি এবং আল্লাহ যা অবতীর্ণ করেন তিনিই সে সম্পর্কে ভাল জানেন; তখন তারা বলেঃ আপনি তো মনগড়া উক্তি করেন; বরং তাদের অধিকাংশ লোকই জানে না।'),
  ('bn.bengali', 16, 102, 'বলুন, একে পবিত্র ফেরেশতা পালনকর্তার পক্ষ থেকে নিশ্চিত সত্যসহ নাযিল করেছেন, যাতে মুমিনদেরকে প্রতিষ্ঠিত করেন এবং এটা মুসলমানদের জন্যে পথ নির্দেশ ও সু-সংবাদ স্বরূপ।'),
  ('bn.bengali', 16, 103, 'আমি তো ভালভাবেই জানি যে, তারা বলেঃ তাকে জনৈক ব্যক্তি শিক্ষা দেয়। যার দিকে তারা ইঙ্গিত করে, তার ভাষা তো আরবী নয় এবং এ কোরআন পরিষ্কার আরবী ভাষায়।'),
  ('bn.bengali', 16, 104, 'যারা আল্লাহর কথায় বিশ্বাস করে না, তাদেরকে আল্লাহ পথ প্রদর্শন করেন না এবং তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 16, 105, 'মিথ্যা কেবল তারা রচনা করে, যারা আল্লাহর নিদর্শনে বিশ্বাস করে না এবং তারাই মিথ্যাবাদী।'),
  ('bn.bengali', 16, 106, 'যার উপর জবরদস্তি করা হয় এবং তার অন্তর বিশ্বাসে অটল থাকে সে ব্যতীত যে কেউ বিশ্বাসী হওয়ার পর আল্লাহতে অবিশ্বাসী হয় এবং কুফরীর জন্য মন উম্মুক্ত করে দেয় তাদের উপর আপতিত হবে আল্লাহর গযব এবং তাদের জন্যে রয়েছে শাস্তি।'),
  ('bn.bengali', 16, 107, 'এটা এ জন্যে যে, তারা পার্থিব জীবনকে পরকালের চাইতে প্রিয় মনে করেছে এবং আল্লাহ অবিশ্বাসীদেরকে পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 16, 108, 'এরাই তারা, আল্লাহ তা’য়ালা এদেরই অন্তর, কর্ণ ও চক্ষুর উপর মোহর মেরে দিয়েছেন এবং এরাই কান্ড জ্ঞানহীন।'),
  ('bn.bengali', 16, 109, 'বলাবাহুল্য পরকালে এরাই ক্ষতি গ্রস্ত হবে।'),
  ('bn.bengali', 16, 110, 'যারা দুঃখ-কষ্ট ভোগের পর দেশত্যাগী হয়েছে অতঃপর জেহাদ করেছে, নিশ্চয় আপনার পালনকর্তা এসব বিষয়ের পরে অবশ্যই ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 16, 111, 'যেদিন প্রত্যেক ব্যক্তি আত্ন-সমর্থনে সওয়াল জওয়াব করতে করতে আসবে এবং প্রত্যেক ব্যক্তি তাদের কৃতকর্মের পূর্ণ ফল পাবে এবং তাদের উপর জুলুম করা হবে না।'),
  ('bn.bengali', 16, 112, 'আল্লাহ দৃষ্টান্ত বর্ণনা করেছেন একটি জনপদের, যা ছিল নিরাপদ ও নিশ্চিন্ত, তথায় প্রত্যেক জায়গা থেকে আসত প্রচুর জীবনোপকরণ। অতঃপর তারা আল্লাহর নেয়ামতের প্রতি অকৃতজ্ঞতা প্রকাশ করল। তখন আল্লাহ তাদেরকে তাদের কৃতকর্মের কারণে স্বাদ আস্বাদন করালেন, ক্ষুধা ও ভীতির।'),
  ('bn.bengali', 16, 113, 'তাদের কাছে তাদের মধ্য থেকেই একজন রাসূল আগমন করেছিলেন। অনন্তর ওরা তাঁর প্রতি মিথ্যারোপ করল। তখন আযাব এসে তাদরকে পাকড়াও করল এবং নিশ্চিতই ওরা ছিল পাপাচারী।'),
  ('bn.bengali', 16, 114, 'অতএব, আল্লাহ তোমাদেরকে যেসব হালাল ও পবিত্র বস্তু দিয়েছেন, তা তোমরা আহার কর এবং আল্লাহর অনুগ্রহের জন্যে কৃতজ্ঞতা প্রকাশ কর যদি তোমরা তাঁরই এবাদতকারী হয়ে থাক।'),
  ('bn.bengali', 16, 115, 'অবশ্যই আল্লাহ তোমাদের জন্যে হারাম করেছেন রক্ত, শুকরের মাংস এবং যা জবাই কালে আল্লাহ ছাড়া অন্যের নাম উচ্চারণ করা হয়েছে। অতঃপর কেউ সীমালঙ্ঘন কারী না হয়ে নিরুপায় হয়ে পড়লে তবে, আল্লাহ ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 16, 116, 'তোমাদের মুখ থেকে সাধারনতঃ যেসব মিথ্যা বের হয়ে আসে তেমনি করে তোমরা আল্লাহর বিরুদ্ধে মিথ্যা অপবাদ আরোপ করে বল না যে, এটা হালাল এবং ওটা হারাম। নিশ্চয় যারা আল্লাহর বিরুদ্ধে মিথ্যা আরোপ করে, তাদের মঙ্গল হবে না।'),
  ('bn.bengali', 16, 117, 'যৎসামান্য সুখ-সম্ভোগ ভোগ করে নিক। তাদের জন্যে যন্ত্রনাদায়ক শাস্তি রয়েছে।'),
  ('bn.bengali', 16, 118, 'ইহুদীদের জন্যে আমি তো কেবল তাই হারাম করেছিলাম যা ইতিপূর্বে আপনার নিকট উল্লেখ করেছি। আমি তাদের প্রতি কোন জুলুম করিনি, কিন্তু তারাই নিজেদের উপর জুলুম করত।'),
  ('bn.bengali', 16, 119, 'অনন্তর যারা অজ্ঞতাবশতঃ মন্দ কাজ করে, অতঃপর তওবা করে এবং নিজেকে সংশোধন করে নেয়, আপনার পালনকর্তা এসবের পরে তাদের জন্যে অবশ্যই ক্ষমাশীল, দয়ালু।'),
  ('bn.bengali', 16, 120, 'নিশ্চয় ইব্রাহীম ছিলেন এক সম্প্রদায়ের প্রতীক, সবকিছু থেকে মুখ ফিরিয়ে এক আল্লাহরই অনুগত এবং তিনি শেরককারীদের অন্তর্ভুক্ত ছিলেন না।'),
  ('bn.bengali', 16, 121, 'তিনি তাঁর অনুগ্রহের প্রতি কৃতজ্ঞতা প্রকাশকারী ছিলেন। আল্লাহ তাঁকে মনোনীত করেছিলেন এবং সরল পথে পরিচালিত করেছিলেন।'),
  ('bn.bengali', 16, 122, 'আমি তাঁকে দুনিয়াতে দান করেছি কল্যাণ এবং তিনি পরকালেও সৎকর্মশীলদের অন্তর্ভূক্ত।'),
  ('bn.bengali', 16, 123, 'অতঃপর আপনার প্রতি প্রত্যাদেশ প্রেরণ করেছি যে, ইব্রাহীমের দ্বীন অনুসরণ করুন, যিনি একনিষ্ঠ ছিলেন এবং শিরককারীদের অন্তর্ভূক্ত ছিলেন না।'),
  ('bn.bengali', 16, 124, 'শনিবার দিন পালন যে, নির্ধারণ করা হয়েছিল, তা তাদের জন্যেই যারা এতে মতবিরোধ করেছিল। আপনার পালনকর্তা কিয়ামতের দিন তাদের মধ্যে ফয়সালা করবেন যে বিষয়ে তারা মতবিরোধ করত।'),
  ('bn.bengali', 16, 125, 'আপন পালনকর্তার পথের প্রতি আহবান করুন জ্ঞানের কথা বুঝিয়ে ও উপদেশ শুনিয়ে উত্তমরূপে এবং তাদের সাথে বিতর্ক করুন পছন্দ যুক্ত পন্থায়। নিশ্চয় আপনার পালনকর্তাই ঐ ব্যক্তি সম্পর্কে বিশেষ ভাবে জ্ঞাত রয়েছেন, যে তাঁর পথ থেকে বিচ্যুত হয়ে পড়েছে এবং তিনিই ভাল জানেন তাদেরকে, যারা সঠিক পথে আছে।'),
  ('bn.bengali', 16, 126, 'আর যদি তোমরা প্রতিশোধ গ্রহণ কর, তবে ঐ পরিমাণ প্রতিশোধ গ্রহণ করবে, যে পরিমাণ তোমাদেরকে কষ্ট দেয়া হয়। যদি সবর কর, তবে তা সবরকারীদের জন্যে উত্তম।'),
  ('bn.bengali', 16, 127, 'আপনি সবর করবেন। আপনার সবর আল্লাহর জন্য ব্যতীত নয়, তাদের জন্যে দুঃখ করবেন না এবং তাদের চক্রান্তের কারণে মন ছোট করবেন না।'),
  ('bn.bengali', 16, 128, 'নিশ্চয় আল্লাহ তাদের সঙ্গে আছেন, যারা পরহেযগার এবং যারা সৎকর্ম করে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 16, 1, 'The commandment of Allah will come to pass, so seek not ye to hasten it. Glorified and Exalted be He above all that they associate (with Him).'),
  ('en.pickthall', 16, 2, 'He sendeth down the angels with the Spirit of His command unto whom He will of His bondmen, (saying): Warn mankind that there is no Allah save Me, so keep your duty unto Me.'),
  ('en.pickthall', 16, 3, 'He hath created the heavens and the earth with truth. High be He Exalted above all that they associate (with Him).'),
  ('en.pickthall', 16, 4, 'He hath created man from a drop of fluid, yet behold! he is an open opponent.'),
  ('en.pickthall', 16, 5, 'And the cattle hath He created, whence ye have warm clothing and uses, and whereof ye eat;'),
  ('en.pickthall', 16, 6, 'And wherein is beauty for you, when ye bring them home, and when ye take them out to pasture.'),
  ('en.pickthall', 16, 7, 'And they bear your loads for you unto a land ye could not reach save with great trouble to yourselves. Lo! your Lord is Full of Pity, Merciful.'),
  ('en.pickthall', 16, 8, 'And horses and mules and asses (hath He created) that ye may ride them, and for ornament. And He createth that which ye know not.'),
  ('en.pickthall', 16, 9, 'And Allah\'s is the direction of the way, and some (roads) go not straight. And had He willed He would have led you all aright.'),
  ('en.pickthall', 16, 10, 'He it is Who sendeth down water from the sky, whence ye have drink, and whence are trees on which ye send your beasts to pasture.'),
  ('en.pickthall', 16, 11, 'Therewith He causeth crops to grow for you, and the olive and the date-palm and grapes and all kinds of fruit. Lo! herein is indeed a portent for people who reflect.'),
  ('en.pickthall', 16, 12, 'And He hath constrained the night and the day and the sun and the moon to be of service unto you, and the stars are made subservient by His command. Lo! herein indeed are portents for people who have sense.'),
  ('en.pickthall', 16, 13, 'And whatsoever He hath created for you in the earth of divers hues, lo! therein is indeed a portent for people who take heed.'),
  ('en.pickthall', 16, 14, 'And He it is Who hath constrained the sea to be of service that ye eat fresh meat from thence, and bring forth from thence ornaments which ye wear. And thou seest the ships ploughing it that ye (mankind) may seek of His bounty and that haply ye may give thanks.'),
  ('en.pickthall', 16, 15, 'And He hath cast into the earth firm hills that it quake not with you, and streams and roads that ye may find a way.'),
  ('en.pickthall', 16, 16, 'And landmarks (too), and by the star they find a way.'),
  ('en.pickthall', 16, 17, 'Is He then Who createth as him who createth not? Will ye not then remember?'),
  ('en.pickthall', 16, 18, 'And if ye would count the favour of Allah ye cannot reckon it. Lo! Allah is indeed Forgiving, Merciful.'),
  ('en.pickthall', 16, 19, 'And Allah knoweth that which ye keep hidden and that which ye proclaim.'),
  ('en.pickthall', 16, 20, 'Those unto whom they cry beside Allah created naught, but are themselves created.'),
  ('en.pickthall', 16, 21, '(They are) dead, not living. And they know not when they will be raised.'),
  ('en.pickthall', 16, 22, 'Your Allah is One Allah. But as for those who believe not in the Hereafter their hearts refuse to know, for they are proud.'),
  ('en.pickthall', 16, 23, 'Assuredly Allah knoweth that which they keep hidden and that which they proclaim. Lo! He loveth not the proud.'),
  ('en.pickthall', 16, 24, 'And when it is said unto them: What hath your Lord revealed? they say: (Mere) fables of the men of old,'),
  ('en.pickthall', 16, 25, 'That they may bear their burdens undiminished on the Day of Resurrection, with somewhat of the burdens of those whom they mislead without knowledge. Ah! evil is that which they bear!'),
  ('en.pickthall', 16, 26, 'Those before them plotted, so Allah struck at the foundations of their building, and then the roof fell down upon them from above them, and the doom came on them whence they knew not;'),
  ('en.pickthall', 16, 27, 'Then on the Day of Resurrection He will disgrace them and will say: Where are My partners, for whose sake ye opposed (My guidance)? Those who have been given knowledge will say: Disgrace this day and evil are upon the disbelievers,'),
  ('en.pickthall', 16, 28, 'Whom the angels cause to die while they are wronging themselves. Then will they make full submission (saying): We used not to do any wrong. Nay! Surely Allah is Knower of what ye used to do.'),
  ('en.pickthall', 16, 29, 'So enter the gates of hell, to dwell therein for ever. Woeful indeed will be the lodging of the arrogant.'),
  ('en.pickthall', 16, 30, 'And it is said unto those who ward off (evil): What hath your Lord revealed? They say: Good. For those who do good in this world there is a good (reward) and the home of the Hereafter will be better. Pleasant indeed will be the home of those who ward off (evil) -'),
  ('en.pickthall', 16, 31, 'Gardens of Eden which they enter, underneath which rivers flow, wherein they have what they will. Thus Allah repayeth those who ward off (evil),'),
  ('en.pickthall', 16, 32, 'Those whom the angels cause to die (when they are) good. They say: Peace be unto you! Enter the Garden because of what ye used to do.'),
  ('en.pickthall', 16, 33, 'Await they aught say that the angels should come unto them or thy Lord\'s command should come to pass? Even so did those before them. Allah wronged them not, but they did wrong themselves,'),
  ('en.pickthall', 16, 34, 'So that the evils of what they did smote them, and that which they used to mock surrounded them.'),
  ('en.pickthall', 16, 35, 'And the idolaters say: Had Allah willed, we had not worshipped aught beside Him, we and our fathers, nor had we forbidden aught without (command from) Him. Even so did those before them. Are the messengers charged with aught save plain conveyance (of the message)?'),
  ('en.pickthall', 16, 36, 'And verily We have raised in every nation a messenger, (proclaiming): Serve Allah and shun false gods. Then some of them (there were) whom Allah guided, and some of them (there were) upon whom error had just hold. Do but travel in the land and see the nature of the consequence for the deniers!'),
  ('en.pickthall', 16, 37, 'Even if thou (O Muhammad) desirest their right guidance, still Allah assuredly will not guide him who misleadeth. Such have no helpers.'),
  ('en.pickthall', 16, 38, 'And they swear by Allah their most binding oaths (that) Allah will not raise up him who dieth. Nay, but it is a promise (binding) upon Him in truth, but most of mankind know not,'),
  ('en.pickthall', 16, 39, 'That He may explain unto them that wherein they differ, and that those who disbelieved may know that they were liars.'),
  ('en.pickthall', 16, 40, 'And Our word unto a thing, when We intend it, is only that We say unto it: Be! and it is.'),
  ('en.pickthall', 16, 41, 'And those who became fugitives for the cause of Allah after they had been oppressed, We verily shall give them goodly lodging in the world, and surely the reward of the Hereafter is greater, if they but knew;'),
  ('en.pickthall', 16, 42, 'Such as are steadfast and put their trust in Allah.'),
  ('en.pickthall', 16, 43, 'And We sent not (as Our messengers) before thee other than men whom We inspired - Ask the followers of the Remembrance if ye know not! -'),
  ('en.pickthall', 16, 44, 'With clear proofs and writings; and We have revealed unto thee the Remembrance that thou mayst explain to mankind that which hath been revealed for them, and that haply they may reflect.'),
  ('en.pickthall', 16, 45, 'Are they who plan ill-deeds then secure that Allah will not cause the earth to swallow them, or that the doom will not come on them whence they know not?'),
  ('en.pickthall', 16, 46, 'Or that He will not seize them in their going to and fro so that there be no escape for them?'),
  ('en.pickthall', 16, 47, 'Or that He will not seize them with a gradual wasting? Lo! thy Lord is indeed Full of Pity, Merciful.'),
  ('en.pickthall', 16, 48, 'Have they not observed all things that Allah hath created, how their shadows incline to the right and to the left, making prostration unto Allah, and they are lowly?'),
  ('en.pickthall', 16, 49, 'And unto Allah maketh prostration whatsoever is in the heavens and whatsoever is in the earth of living creatures, and the angels (also) and they are not proud.'),
  ('en.pickthall', 16, 50, 'They fear their Lord above them, and do what they are bidden.'),
  ('en.pickthall', 16, 51, 'Allah hath said: Choose not two gods. There is only One Allah. So of Me, Me only, be in awe.'),
  ('en.pickthall', 16, 52, 'Unto Him belongeth whatsoever is in the heavens and the earth, and religion is His for ever. Will ye then fear any other than Allah?'),
  ('en.pickthall', 16, 53, 'And whatever of comfort ye enjoy, it is from Allah. Then, when misfortune reacheth you, unto Him ye cry for help.'),
  ('en.pickthall', 16, 54, 'And afterward, when He hath rid you of the misfortune, behold! a set of you attribute partners to their Lord,'),
  ('en.pickthall', 16, 55, 'So as to deny that which We have given them. Then enjoy life (while ye may), for ye will come to know.'),
  ('en.pickthall', 16, 56, 'And they assign a portion of that which We have given them unto what they know not. By Allah! but ye will indeed be asked concerning (all) that ye used to invent.'),
  ('en.pickthall', 16, 57, 'And they assign unto Allah daughters - Be He Glorified! - and unto themselves what they desire;'),
  ('en.pickthall', 16, 58, 'When if one of them receiveth tidings of the birth of a female, his face remaineth darkened, and he is wroth inwardly.'),
  ('en.pickthall', 16, 59, 'He hideth himself from the folk because of the evil of that whereof he hath had tidings, (asking himself): Shall he keep it in contempt, or bury it beneath the dust. Verily evil is their judgment.'),
  ('en.pickthall', 16, 60, 'For those who believe not in the Hereafter is an evil similitude, and Allah\'s is the Sublime Similitude. He is the Mighty, the Wise.'),
  ('en.pickthall', 16, 61, 'If Allah were to take mankind to task for their wrong-doing, he would not leave hereon a living creature, but He reprieveth them to an appointed term, and when their term cometh they cannot put (it) off an hour nor (yet) advance (it).'),
  ('en.pickthall', 16, 62, 'And they assign unto Allah that which they (themselves) dislike, and their tongues expound the lie that the better portion will be theirs. Assuredly theirs will be the Fire, and they will be abandoned.'),
  ('en.pickthall', 16, 63, 'By Allah, We verily sent messengers unto the nations before thee, but the devil made their deeds fairseeming unto them. So he is their patron this day, and theirs will be a painful doom.'),
  ('en.pickthall', 16, 64, 'And We have revealed the Scripture unto thee only that thou mayst explain unto them that wherein they differ, and (as) a guidance and a mercy for a people who believe.'),
  ('en.pickthall', 16, 65, 'Allah sendeth down water from the sky and therewith reviveth the earth after her death. Lo! herein is indeed a portent for a folk who hear.'),
  ('en.pickthall', 16, 66, 'And lo! in the cattle there is a lesson for you. We give you to drink of that which is in their bellies, from betwixt the refuse and the blood, pure milk palatable to the drinkers.'),
  ('en.pickthall', 16, 67, 'And of the fruits of the date-palm, and grapes, whence ye derive strong drink and (also) good nourishment. Lo! therein is indeed a portent for people who have sense.'),
  ('en.pickthall', 16, 68, 'And thy Lord inspired the bee, saying: Choose thou habitations in the hills and in the trees and in that which they thatch;'),
  ('en.pickthall', 16, 69, 'Then eat of all fruits, and follow the ways of thy Lord, made smooth (for thee). There cometh forth from their bellies a drink divers of hues, wherein is healing for mankind. Lo! herein is indeed a portent for people who reflect.'),
  ('en.pickthall', 16, 70, 'And Allah createth you, then causeth you to die, and among you is he who is brought back to the most abject stage of life, so that he knoweth nothing after (having had) knowledge. Lo! Allah is Knower, Powerful.'),
  ('en.pickthall', 16, 71, 'And Allah hath favoured some of you above others in provision. Now those who are more favoured will by no means hand over their provision to those (slaves) whom their right hands possess, so that they may be equal with them in respect thereof. Is it then the grace of Allah that they deny?'),
  ('en.pickthall', 16, 72, 'And Allah hath given you wives of your own kind, and hath given you, from your wives, sons and grandsons, and hath made provision of good things for you. Is it then in vanity that they believe and in the grace of Allah that they disbelieve?'),
  ('en.pickthall', 16, 73, 'And they worship beside Allah that which owneth no provision whatsoever for them from the heavens or the earth, nor have they (whom they worship) any power.'),
  ('en.pickthall', 16, 74, 'So coin not similitudes for Allah. Lo! Allah knoweth; ye know not.'),
  ('en.pickthall', 16, 75, 'Allah coineth a similitude: (on the one hand) a (mere) chattel slave, who hath control of nothing, and (on the other hand) one on whom we have bestowed a fair provision from Us, and he spendeth thereof secretly and openly. Are they equal? Praise be to Allah! But most of them know not.'),
  ('en.pickthall', 16, 76, 'And Allah coineth a similitude: Two men, one of them dumb, having control of nothing, and he is a burden on his owner; whithersoever he directeth him to go, he bringeth no good. Is he equal with one who enjoineth justice and followeth a straight path (of conduct)?'),
  ('en.pickthall', 16, 77, 'And unto Allah belongeth the Unseen of the heavens and the earth, and the matter of the Hour (of Doom) is but as a twinkling of the eye, or it is nearer still. Lo! Allah is Able to do all things.'),
  ('en.pickthall', 16, 78, 'And Allah brought you forth from the wombs of your mothers knowing nothing, and gave you hearing and sight and hearts that haply ye might give thanks.'),
  ('en.pickthall', 16, 79, 'Have they not seen the birds obedient in mid-air? None holdeth them save Allah. Lo! herein, verily, are portents for a people who believe.'),
  ('en.pickthall', 16, 80, 'And Allah hath given you in your houses an abode, and hath given you (also), of the hides of cattle, houses which ye find light (to carry) on the day of migration and on the day of pitching camp; and of their wool and their fur and their hair, caparison and comfort for a while.'),
  ('en.pickthall', 16, 81, 'And Allah hath given you, of that which He hath created, shelter from the sun; and hath given you places of refuge in the mountains, and hath given you coats to ward off the heat from you, and coats (of armour) to save you from your own foolhardiness. Thus doth He perfect His favour unto you, in order that ye may surrender (unto Him).'),
  ('en.pickthall', 16, 82, 'Then, if they turn away, thy duty (O Muhammad) is but plain conveyance (of the message).'),
  ('en.pickthall', 16, 83, 'They know the favour of Allah and then deny it. Most of them are ingrates.'),
  ('en.pickthall', 16, 84, 'And (bethink you of) the day when we raise up of every nation a witness, then there is no leave for disbelievers, nor are they allowed to make amends.'),
  ('en.pickthall', 16, 85, 'And when those who did wrong behold the doom, it will not be made light for them, nor will they be reprieved.'),
  ('en.pickthall', 16, 86, 'And when those who ascribed partners to Allah behold those partners of theirs, they will say: Our Lord! these are our partners unto whom we used to cry instead of Thee. But they will fling to them the saying: Lo! ye verily are liars!'),
  ('en.pickthall', 16, 87, 'And they proffer unto Allah submission on that day, and all that they used to invent hath failed them.'),
  ('en.pickthall', 16, 88, 'For those who disbelieve and debar (men) from the way of Allah, We add doom to doom because they wrought corruption,'),
  ('en.pickthall', 16, 89, 'And (bethink you of) the day when We raise in every nation a witness against them of their own folk, and We bring thee (Muhammad) as a witness against these. And We reveal the Scripture unto thee as an exposition of all things, and a guidance and a mercy and good tidings for those who have surrendered (to Allah).'),
  ('en.pickthall', 16, 90, 'Lo! Allah enjoineth justice and kindness, and giving to kinsfolk, and forbiddeth lewdness and abomination and wickedness. He exhorteth you in order that ye may take heed.'),
  ('en.pickthall', 16, 91, 'Fulfil the covenant of Allah when ye have covenanted, and break not your oaths after the asseveration of them, and after ye have made Allah surety over you. Lo! Allah knoweth what ye do.'),
  ('en.pickthall', 16, 92, 'And be not like unto her who unravelleth the thread, after she hath made it strong, to thin filaments, making your oaths a deceit between you because of a nation being more numerous than (another) nation. Allah only trieth you thereby, and He verily will explain to you on the Day of Resurrection that wherein ye differed.'),
  ('en.pickthall', 16, 93, 'Had Allah willed He could have made you (all) one nation, but He sendeth whom He will astray and guideth whom He will, and ye will indeed be asked of what ye used to do.'),
  ('en.pickthall', 16, 94, 'Make not your oaths a deceit between you, lest a foot should slip after being firmly planted and ye should taste evil forasmuch as ye debarred (men) from the way of Allah, and yours should be an awful doom.'),
  ('en.pickthall', 16, 95, 'And purchase not a small gain at the price of Allah\'s covenant. Lo! that which Allah hath is better for you, if ye did but know.'),
  ('en.pickthall', 16, 96, 'That which ye have wasteth away, and that which Allah hath remaineth. And verily We shall pay those who are steadfast a recompense in proportion to the best of what they used to do.'),
  ('en.pickthall', 16, 97, 'Whosoever doeth right, whether male or female, and is a believer, him verily we shall quicken with good life, and We shall pay them a recompense in proportion to the best of what they used to do.'),
  ('en.pickthall', 16, 98, 'And when thou recitest the Qur\'an, seek refuge in Allah from Satan the outcast.'),
  ('en.pickthall', 16, 99, 'Lo! he hath no power over those who believe and put trust in their Lord.'),
  ('en.pickthall', 16, 100, 'His power is only over those who make a friend of him, and those who ascribe partners unto Him (Allah).'),
  ('en.pickthall', 16, 101, 'And when We put a revelation in place of (another) revelation, - and Allah knoweth best what He revealeth - they say: Lo! thou art but inventing. Most of them know not.'),
  ('en.pickthall', 16, 102, 'Say: The holy Spirit hath delivered it from thy Lord with truth, that it may confirm (the faith of) those who believe, and as guidance and good tidings for those who have surrendered (to Allah).'),
  ('en.pickthall', 16, 103, 'And We know well that they say: Only a man teacheth him. The speech of him at whom they falsely hint is outlandish, and this is clear Arabic speech.'),
  ('en.pickthall', 16, 104, 'Lo! those who disbelieve the revelations of Allah, Allah guideth them not and theirs will be a painful doom.'),
  ('en.pickthall', 16, 105, 'Only they invent falsehood who believe not Allah\'s revelations, and (only) they are the liars.'),
  ('en.pickthall', 16, 106, 'Whoso disbelieveth in Allah after his belief - save him who is forced thereto and whose heart is still content with the Faith - but whoso findeth ease in disbelief: On them is wrath from Allah. Theirs will be an awful doom.'),
  ('en.pickthall', 16, 107, 'That is because they have chosen the life of the world rather than the Hereafter, and because Allah guideth not the disbelieving folk.'),
  ('en.pickthall', 16, 108, 'Such are they whose hearts and ears and eyes Allah hath sealed. And such are the heedless.'),
  ('en.pickthall', 16, 109, 'Assuredly in the Hereafter they are the losers.'),
  ('en.pickthall', 16, 110, 'Then lo! thy Lord - for those who became fugitives after they had been persecuted, and then fought and were steadfast - lo! thy Lord afterward is (for them) indeed Forgiving, Merciful.'),
  ('en.pickthall', 16, 111, 'On the Day when every soul will come pleading for itself, and every soul will be repaid what it did, and they will not be wronged.'),
  ('en.pickthall', 16, 112, 'Allah coineth a similitude: a township that dwelt secure and well content, its provision coming to it in abundance from every side, but it disbelieved in Allah\'s favours, so Allah made it experience the garb of dearth and fear because of what they used to do.'),
  ('en.pickthall', 16, 113, 'And verily there had come unto them a messenger from among them, but they had denied him, and so the torment seized them while they were wrong-doers.'),
  ('en.pickthall', 16, 114, 'So eat of the lawful and good food which Allah hath provided for you, and thank the bounty of your Lord if it is Him ye serve.'),
  ('en.pickthall', 16, 115, 'He hath forbidden for you only carrion and blood and swineflesh and that which hath been immolated in the name of any other than Allah; but he who is driven thereto, neither craving nor transgressing, lo! then Allah is Forgiving, Merciful.'),
  ('en.pickthall', 16, 116, 'And speak not, concerning that which your own tongues qualify (as clean or unclean), the falsehood: "This is lawful, and this is forbidden," so that ye invent a lie against Allah. Lo! those who invent a lie against Allah will not succeed.'),
  ('en.pickthall', 16, 117, 'A brief enjoyment (will be theirs); and theirs a painful doom.'),
  ('en.pickthall', 16, 118, 'And unto those who are Jews We have forbidden that which We have already related unto thee. And We wronged them not, but they were wont to wrong themselves.'),
  ('en.pickthall', 16, 119, 'Then lo! thy Lord - for those who do evil in ignorance and afterward repent and amend - lo! (for them) thy Lord is afterward indeed Forgiving, Merciful.'),
  ('en.pickthall', 16, 120, 'Lo! Abraham was a nation obedient to Allah, by nature upright, and he was not of the idolaters;'),
  ('en.pickthall', 16, 121, 'Thankful for His bounties; He chose him and He guided him unto a straight path.'),
  ('en.pickthall', 16, 122, 'And We gave him good in the world, and in the Hereafter he is among the righteous.'),
  ('en.pickthall', 16, 123, 'And afterward We inspired thee (Muhammad, saying): Follow the religion of Abraham, as one by nature upright. He was not of the idolaters.'),
  ('en.pickthall', 16, 124, 'The Sabbath was appointed only for those who differed concerning it, and lo! thy Lord will judge between them on the Day of Resurrection concerning that wherein they used to differ.'),
  ('en.pickthall', 16, 125, 'Call unto the way of thy Lord with wisdom and fair exhortation, and reason with them in the better way. Lo! thy Lord is Best Aware of him who strayeth from His way, and He is Best Aware of those who go aright.'),
  ('en.pickthall', 16, 126, 'If ye punish, then punish with the like of that wherewith ye were afflicted. But if ye endure patiently, verily it is better for the patient.'),
  ('en.pickthall', 16, 127, 'Endure thou patiently (O Muhammad). Thine endurance is only by (the help of) Allah. Grieve not for them, and be not in distress because of that which they devise.'),
  ('en.pickthall', 16, 128, 'Lo! Allah is with those who keep their duty unto Him and those who are doers of good.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 16, 1, '(Inevitable) cometh (to pass) the Command of Allah: seek ye not then to hasten it: Glory to Him, and far is He above having the partners they ascribe unto Him!'),
  ('en.yusufali', 16, 2, 'He doth send down His angels with inspiration of His Command, to such of His servants as He pleaseth, (saying): "Warn (Man) that there is no god but I: so do your duty unto Me."'),
  ('en.yusufali', 16, 3, 'He has created the heavens and the earth for just ends: Far is He above having the partners they ascribe to Him!'),
  ('en.yusufali', 16, 4, 'He has created man from a sperm-drop; and behold this same (man) becomes an open disputer!'),
  ('en.yusufali', 16, 5, 'And cattle He has created for you (men): from them ye derive warmth, and numerous benefits, and of their (meat) ye eat.'),
  ('en.yusufali', 16, 6, 'And ye have a sense of pride and beauty in them as ye drive them home in the evening, and as ye lead them forth to pasture in the morning.'),
  ('en.yusufali', 16, 7, 'And they carry your heavy loads to lands that ye could not (otherwise) reach except with souls distressed: for your Lord is indeed Most Kind, Most Merciful,'),
  ('en.yusufali', 16, 8, 'And (He has created) horses, mules, and donkeys, for you to ride and use for show; and He has created (other) things of which ye have no knowledge.'),
  ('en.yusufali', 16, 9, 'And unto Allah leads straight the Way, but there are ways that turn aside: if Allah had willed, He could have guided all of you.'),
  ('en.yusufali', 16, 10, 'It is He who sends down rain from the sky: from it ye drink, and out of it (grows) the vegetation on which ye feed your cattle.'),
  ('en.yusufali', 16, 11, 'With it He produces for you corn, olives, date-palms, grapes and every kind of fruit: verily in this is a sign for those who give thought.'),
  ('en.yusufali', 16, 12, 'He has made subject to you the Night and the Day; the sun and the moon; and the stars are in subjection by His Command: verily in this are Signs for men who are wise.'),
  ('en.yusufali', 16, 13, 'And the things on this earth which He has multiplied in varying colours (and qualities): verily in this is a sign for men who celebrate the praises of Allah (in gratitude).'),
  ('en.yusufali', 16, 14, 'It is He Who has made the sea subject, that ye may eat thereof flesh that is fresh and tender, and that ye may extract therefrom ornaments to wear; and thou seest the ships therein that plough the waves, that ye may seek (thus) of the bounty of Allah and that ye may be grateful.'),
  ('en.yusufali', 16, 15, 'And He has set up on the earth mountains standing firm, lest it should shake with you; and rivers and roads; that ye may guide yourselves;'),
  ('en.yusufali', 16, 16, 'And marks and sign-posts; and by the stars (men) guide themselves.'),
  ('en.yusufali', 16, 17, 'Is then He Who creates like one that creates not? Will ye not receive admonition?'),
  ('en.yusufali', 16, 18, 'If ye would count up the favours of Allah, never would ye be able to number them: for Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 16, 19, 'And Allah doth know what ye conceal, and what ye reveal.'),
  ('en.yusufali', 16, 20, 'Those whom they invoke besides Allah create nothing and are themselves created.'),
  ('en.yusufali', 16, 21, '(They are things) dead, lifeless: nor do they know when they will be raised up.'),
  ('en.yusufali', 16, 22, 'Your Allah is one Allah: as to those who believe not in the Hereafter, their hearts refuse to know, and they are arrogant.'),
  ('en.yusufali', 16, 23, 'Undoubtedly Allah doth know what they conceal, and what they reveal: verily He loveth not the arrogant.'),
  ('en.yusufali', 16, 24, 'When it is said to them, "What is it that your Lord has revealed?" they say, "Tales of the ancients!"'),
  ('en.yusufali', 16, 25, 'Let them bear, on the Day of Judgment, their own burdens in full, and also (something) of the burdens of those without knowledge, whom they misled. Alas, how grievous the burdens they will bear!'),
  ('en.yusufali', 16, 26, 'Those before them did also plot (against Allah\'s Way): but Allah took their structures from their foundations, and the roof fell down on them from above; and the Wrath seized them from directions they did not perceive.'),
  ('en.yusufali', 16, 27, 'Then, on the Day of Judgment, He will cover them with shame, and say: "Where are My \'partners\' concerning whom ye used to dispute (with the godly)?" Those endued with knowledge will say: "This Day, indeed, are the Unbelievers covered with shame and misery,-'),
  ('en.yusufali', 16, 28, '"(Namely) those whose lives the angels take in a state of wrong-doing to their own souls." Then would they offer submission (with the pretence), "We did no evil (knowingly)." (The angels will reply), "Nay, but verily Allah knoweth all that ye did;'),
  ('en.yusufali', 16, 29, '"So enter the gates of Hell, to dwell therein. Thus evil indeed is the abode of the arrogant."'),
  ('en.yusufali', 16, 30, 'To the righteous (when) it is said, "What is it that your Lord has revealed?" they say, "All that is good." To those who do good, there is good in this world, and the Home of the Hereafter is even better and excellent indeed is the Home of the righteous,-'),
  ('en.yusufali', 16, 31, 'Gardens of Eternity which they will enter: beneath them flow (pleasant) rivers: they will have therein all that they wish: thus doth Allah reward the righteous,-'),
  ('en.yusufali', 16, 32, '(Namely) those whose lives the angels take in a state of purity, saying (to them), "Peace be on you; enter ye the Garden, because of (the good) which ye did (in the world)."'),
  ('en.yusufali', 16, 33, 'Do the (ungodly) wait until the angels come to them, or there comes the Command of thy Lord (for their doom)? So did those who went before them. But Allah wronged them not: nay, they wronged their own souls.'),
  ('en.yusufali', 16, 34, 'But the evil results of their deeds overtook them, and that very (Wrath) at which they had scoffed hemmed them in.'),
  ('en.yusufali', 16, 35, 'The worshippers of false gods say: "If Allah had so willed, we should not have worshipped aught but Him - neither we nor our fathers,- nor should we have prescribed prohibitions other than His." So did those who went before them. But what is the mission of messengers but to preach the Clear Message?'),
  ('en.yusufali', 16, 36, 'For We assuredly sent amongst every People a messenger, (with the Command), "Serve Allah, and eschew Evil": of the People were some whom Allah guided, and some on whom error became inevitably (established). So travel through the earth, and see what was the end of those who denied (the Truth).'),
  ('en.yusufali', 16, 37, 'If thou art anxious for their guidance, yet Allah guideth not such as He leaves to stray, and there is none to help them.'),
  ('en.yusufali', 16, 38, 'They swear their strongest oaths by Allah, that Allah will not raise up those who die: Nay, but it is a promise (binding) on Him in truth: but most among mankind realise it not.'),
  ('en.yusufali', 16, 39, '(They must be raised up), in order that He may manifest to them the truth of that wherein they differ, and that the rejecters of Truth may realise that they had indeed (surrendered to) Falsehood.'),
  ('en.yusufali', 16, 40, 'For to anything which We have willed, We but say the word, "Be", and it is.'),
  ('en.yusufali', 16, 41, 'To those who leave their homes in the cause of Allah, after suffering oppression,- We will assuredly give a goodly home in this world; but truly the reward of the Hereafter will be greater. If they only realised (this)!'),
  ('en.yusufali', 16, 42, '(They are) those who persevere in patience, and put their trust on their Lord.'),
  ('en.yusufali', 16, 43, 'And before thee also the messengers We sent were but men, to whom We granted inspiration: if ye realise this not, ask of those who possess the Message.'),
  ('en.yusufali', 16, 44, '(We sent them) with Clear Signs and Books of dark prophecies; and We have sent down unto thee (also) the Message; that thou mayest explain clearly to men what is sent for them, and that they may give thought.'),
  ('en.yusufali', 16, 45, 'Do then those who devise evil (plots) feel secure that Allah will not cause the earth to swallow them up, or that the Wrath will not seize them from directions they little perceive?-'),
  ('en.yusufali', 16, 46, 'Or that He may not call them to account in the midst of their goings to and fro, without a chance of their frustrating Him?-'),
  ('en.yusufali', 16, 47, 'Or that He may not call them to account by a process of slow wastage - for thy Lord is indeed full of kindness and mercy.'),
  ('en.yusufali', 16, 48, 'Do they not look at Allah\'s creation, (even) among (inanimate) things,- How their (very) shadows turn round, from the right and the left, prostrating themselves to Allah, and that in the humblest manner?'),
  ('en.yusufali', 16, 49, 'And to Allah doth obeisance all that is in the heavens and on earth, whether moving (living) creatures or the angels: for none are arrogant (before their Lord).'),
  ('en.yusufali', 16, 50, 'They all revere their Lord, high above them, and they do all that they are commanded.'),
  ('en.yusufali', 16, 51, 'Allah has said: "Take not (for worship) two gods: for He is just One Allah: then fear Me (and Me alone)."'),
  ('en.yusufali', 16, 52, 'To Him belongs whatever is in the heavens and on earth, and to Him is duty due always: then will ye fear other than Allah?'),
  ('en.yusufali', 16, 53, 'And ye have no good thing but is from Allah: and moreover, when ye are touched by distress, unto Him ye cry with groans;'),
  ('en.yusufali', 16, 54, 'Yet, when He removes the distress from you, behold! some of you turn to other gods to join with their Lord-'),
  ('en.yusufali', 16, 55, '(As if) to show their ingratitude for the favours we have bestowed on them! then enjoy (your brief day): but soon will ye know (your folly)!'),
  ('en.yusufali', 16, 56, 'And they (even) assign, to things they do not know, a portion out of that which We have bestowed for their sustenance! By Allah, ye shall certainly be called to account for your false inventions.'),
  ('en.yusufali', 16, 57, 'And they assign daughters for Allah! - Glory be to Him! - and for themselves (sons,- the issue) they desire!'),
  ('en.yusufali', 16, 58, 'When news is brought to one of them, of (the birth of) a female (child), his face darkens, and he is filled with inward grief!'),
  ('en.yusufali', 16, 59, 'With shame does he hide himself from his people, because of the bad news he has had! Shall he retain it on (sufferance and) contempt, or bury it in the dust? Ah! what an evil (choice) they decide on?'),
  ('en.yusufali', 16, 60, 'To those who believe not in the Hereafter, applies the similitude of evil: to Allah applies the highest similitude: for He is the Exalted in Power, full of Wisdom.'),
  ('en.yusufali', 16, 61, 'If Allah were to punish men for their wrong-doing, He would not leave, on the (earth), a single living creature: but He gives them respite for a stated Term: When their Term expires, they would not be able to delay (the punishment) for a single hour, just as they would not be able to anticipate it (for a single hour).'),
  ('en.yusufali', 16, 62, 'They attribute to Allah what they hate (for themselves), and their tongues assert the falsehood that all good things are for themselves: without doubt for them is the Fire, and they will be the first to be hastened on into it!'),
  ('en.yusufali', 16, 63, 'By Allah, We (also) sent (Our messengers) to Peoples before thee; but Satan made, (to the wicked), their own acts seem alluring: He is also their patron today, but they shall have a most grievous penalty.'),
  ('en.yusufali', 16, 64, 'And We sent down the Book to thee for the express purpose, that thou shouldst make clear to them those things in which they differ, and that it should be a guide and a mercy to those who believe.'),
  ('en.yusufali', 16, 65, 'And Allah sends down rain from the skies, and gives therewith life to the earth after its death: verily in this is a Sign for those who listen.'),
  ('en.yusufali', 16, 66, 'And verily in cattle (too) will ye find an instructive sign. From what is within their bodies between excretions and blood, We produce, for your drink, milk, pure and agreeable to those who drink it.'),
  ('en.yusufali', 16, 67, 'And from the fruit of the date-palm and the vine, ye get out wholesome drink and food: behold, in this also is a sign for those who are wise.'),
  ('en.yusufali', 16, 68, 'And thy Lord taught the Bee to build its cells in hills, on trees, and in (men\'s) habitations;'),
  ('en.yusufali', 16, 69, 'Then to eat of all the produce (of the earth), and find with skill the spacious paths of its Lord: there issues from within their bodies a drink of varying colours, wherein is healing for men: verily in this is a Sign for those who give thought.'),
  ('en.yusufali', 16, 70, 'It is Allah who creates you and takes your souls at death; and of you there are some who are sent back to a feeble age, so that they know nothing after having known (much): for Allah is All-Knowing, All-Powerful.'),
  ('en.yusufali', 16, 71, 'Allah has bestowed His gifts of sustenance more freely on some of you than on others: those more favoured are not going to throw back their gifts to those whom their right hands possess, so as to be equal in that respect. Will they then deny the favours of Allah?'),
  ('en.yusufali', 16, 72, 'And Allah has made for you mates (and companions) of your own nature, and made for you, out of them, sons and daughters and grandchildren, and provided for you sustenance of the best: will they then believe in vain things, and be ungrateful for Allah\'s favours?-'),
  ('en.yusufali', 16, 73, 'And worship others than Allah,- such as have no power of providing them, for sustenance, with anything in heavens or earth, and cannot possibly have such power?'),
  ('en.yusufali', 16, 74, 'Invent not similitudes for Allah: for Allah knoweth, and ye know not.'),
  ('en.yusufali', 16, 75, 'Allah sets forth the Parable (of two men: one) a slave under the dominion of another; He has no power of any sort; and (the other) a man on whom We have bestowed goodly favours from Ourselves, and he spends thereof (freely), privately and publicly: are the two equal? (By no means;) praise be to Allah. But most of them understand not.'),
  ('en.yusufali', 16, 76, 'Allah sets forth (another) Parable of two men: one of them dumb, with no power of any sort; a wearisome burden is he to his master; whichever way be directs him, he brings no good: is such a man equal with one who commands Justice, and is on a Straight Way?'),
  ('en.yusufali', 16, 77, 'To Allah belongeth the Mystery of the heavens and the earth. And the Decision of the Hour (of Judgment) is as the twingkling of an eye, or even quicker: for Allah hath power over all things.'),
  ('en.yusufali', 16, 78, 'It is He Who brought you forth from the wombs of your mothers when ye knew nothing; and He gave you hearing and sight and intelligence and affections: that ye may give thanks (to Allah).'),
  ('en.yusufali', 16, 79, 'Do they not look at the birds, held poised in the midst of (the air and) the sky? Nothing holds them up but (the power of) Allah. Verily in this are signs for those who believe.'),
  ('en.yusufali', 16, 80, 'It is Allah Who made your habitations homes of rest and quiet for you; and made for you, out of the skins of animals, (tents for) dwellings, which ye find so light (and handy) when ye travel and when ye stop (in your travels); and out of their wool, and their soft fibres (between wool and hair), and their hair, rich stuff and articles of convenience (to serve you) for a time.'),
  ('en.yusufali', 16, 81, 'It is Allah Who made out of the things He created, some things to give you shade; of the hills He made some for your shelter; He made you garments to protect you from heat, and coats of mail to protect you from your (mutual) violence. Thus does He complete His favours on you, that ye may bow to His Will (in Islam).'),
  ('en.yusufali', 16, 82, 'But if they turn away, thy duty is only to preach the clear Message.'),
  ('en.yusufali', 16, 83, 'They recognise the favours of Allah; then they deny them; and most of them are (creatures) ungrateful.'),
  ('en.yusufali', 16, 84, 'One Day We shall raise from all Peoples a Witness: then will no excuse be accepted from Unbelievers, nor will they receive any favours.'),
  ('en.yusufali', 16, 85, 'When the wrong-doers (actually) see the Penalty, then will it in no way be mitigated, nor will they then receive respite.'),
  ('en.yusufali', 16, 86, 'When those who gave partners to Allah will see their "partners", they will say: "Our Lord! these are our \'partners,\' those whom we used to invoke besides Thee." But they will throw back their word at them (and say): "Indeed ye are liars!"'),
  ('en.yusufali', 16, 87, 'That Day shall they (openly) show (their) submission to Allah; and all their inventions shall leave them in the lurch.'),
  ('en.yusufali', 16, 88, 'Those who reject Allah and hinder (men) from the Path of Allah - for them will We add Penalty to Penalty; for that they used to spread mischief.'),
  ('en.yusufali', 16, 89, 'One day We shall raise from all Peoples a witness against them, from amongst themselves: and We shall bring thee as a witness against these (thy people): and We have sent down to thee the Book explaining all things, a Guide, a Mercy, and Glad Tidings to Muslims.'),
  ('en.yusufali', 16, 90, 'Allah commands justice, the doing of good, and liberality to kith and kin, and He forbids all shameful deeds, and injustice and rebellion: He instructs you, that ye may receive admonition.'),
  ('en.yusufali', 16, 91, 'Fulfil the Covenant of Allah when ye have entered into it, and break not your oaths after ye have confirmed them; indeed ye have made Allah your surety; for Allah knoweth all that ye do.'),
  ('en.yusufali', 16, 92, 'And be not like a woman who breaks into untwisted strands the yarn which she has spun, after it has become strong. Nor take your oaths to practise deception between yourselves, lest one party should be more numerous than another: for Allah will test you by this; and on the Day of Judgment He will certainly make clear to you (the truth of) that wherein ye disagree.'),
  ('en.yusufali', 16, 93, 'If Allah so willed, He could make you all one people: But He leaves straying whom He pleases, and He guides whom He pleases: but ye shall certainly be called to account for all your actions.'),
  ('en.yusufali', 16, 94, 'And take not your oaths, to practise deception between yourselves, with the result that someone\'s foot may slip after it was firmly planted, and ye may have to taste the evil (consequences) of having hindered (men) from the Path of Allah, and a Mighty Wrath descend on you.'),
  ('en.yusufali', 16, 95, 'Nor sell the covenant of Allah for a miserable price: for with Allah is (a prize) far better for you, if ye only knew.'),
  ('en.yusufali', 16, 96, 'What is with you must vanish: what is with Allah will endure. And We will certainly bestow, on those who patiently persevere, their reward according to the best of their actions.'),
  ('en.yusufali', 16, 97, 'Whoever works righteousness, man or woman, and has Faith, verily, to him will We give a new Life, a life that is good and pure and We will bestow on such their reward according to the best of their actions.'),
  ('en.yusufali', 16, 98, 'When thou dost read the Qur\'an, seek Allah\'s protection from Satan the rejected one.'),
  ('en.yusufali', 16, 99, 'No authority has he over those who believe and put their trust in their Lord.'),
  ('en.yusufali', 16, 100, 'His authority is over those only, who take him as patron and who join partners with Allah.'),
  ('en.yusufali', 16, 101, 'When We substitute one revelation for another,- and Allah knows best what He reveals (in stages),- they say, "Thou art but a forger": but most of them understand not.'),
  ('en.yusufali', 16, 102, 'Say, the Holy Spirit has brought the revelation from thy Lord in Truth, in order to strengthen those who believe, and as a Guide and Glad Tidings to Muslims.'),
  ('en.yusufali', 16, 103, 'We know indeed that they say, "It is a man that teaches him." The tongue of him they wickedly point to is notably foreign, while this is Arabic, pure and clear.'),
  ('en.yusufali', 16, 104, 'Those who believe not in the Signs of Allah,- Allah will not guide them, and theirs will be a grievous Penalty.'),
  ('en.yusufali', 16, 105, 'It is those who believe not in the Signs of Allah, that forge falsehood: it is they who lie!'),
  ('en.yusufali', 16, 106, 'Any one who, after accepting faith in Allah, utters Unbelief,- except under compulsion, his heart remaining firm in Faith - but such as open their breast to Unbelief, on them is Wrath from Allah, and theirs will be a dreadful Penalty.'),
  ('en.yusufali', 16, 107, 'This because they love the life of this world better than the Hereafter: and Allah will not guide those who reject Faith.'),
  ('en.yusufali', 16, 108, 'Those are they whose hearts, ears, and eyes Allah has sealed up, and they take no heed.'),
  ('en.yusufali', 16, 109, 'Without doubt, in the Hereafter they will perish.'),
  ('en.yusufali', 16, 110, 'But verily thy Lord,- to those who leave their homes after trials and persecutions,- and who thereafter strive and fight for the faith and patiently persevere,- Thy Lord, after all this is oft-forgiving, Most Merciful.'),
  ('en.yusufali', 16, 111, 'One Day every soul will come up struggling for itself, and every soul will be recompensed (fully) for all its actions, and none will be unjustly dealt with.'),
  ('en.yusufali', 16, 112, 'Allah sets forth a Parable: a city enjoying security and quiet, abundantly supplied with sustenance from every place: Yet was it ungrateful for the favours of Allah: so Allah made it taste of hunger and terror (in extremes) (closing in on it) like a garment (from every side), because of the (evil) which (its people) wrought.'),
  ('en.yusufali', 16, 113, 'And there came to them a Messenger from among themselves, but they falsely rejected him; so the Wrath seized them even in the midst of their iniquities.'),
  ('en.yusufali', 16, 114, 'So eat of the sustenance which Allah has provided for you, lawful and good; and be grateful for the favours of Allah, if it is He Whom ye serve.'),
  ('en.yusufali', 16, 115, 'He has only forbidden you dead meat, and blood, and the flesh of swine, and any (food) over which the name of other than Allah has been invoked. But if one is forced by necessity, without wilful disobedience, nor transgressing due limits,- then Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 16, 116, 'But say not - for any false thing that your tongues may put forth,- "This is lawful, and this is forbidden," so as to ascribe false things to Allah. For those who ascribe false things to Allah, will never prosper.'),
  ('en.yusufali', 16, 117, '(In such falsehood) is but a paltry profit; but they will have a most grievous Penalty.'),
  ('en.yusufali', 16, 118, 'To the Jews We prohibited such things as We have mentioned to thee before: We did them no wrong, but they were used to doing wrong to themselves.'),
  ('en.yusufali', 16, 119, 'But verily thy Lord,- to those who do wrong in ignorance, but who thereafter repent and make amends,- thy Lord, after all this, is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 16, 120, 'Abraham was indeed a model, devoutly obedient to Allah, (and) true in Faith, and he joined not gods with Allah:'),
  ('en.yusufali', 16, 121, 'He showed his gratitude for the favours of Allah, who chose him, and guided him to a Straight Way.'),
  ('en.yusufali', 16, 122, 'And We gave him Good in this world, and he will be, in the Hereafter, in the ranks of the Righteous.'),
  ('en.yusufali', 16, 123, 'So We have taught thee the inspired (Message), "Follow the ways of Abraham the True in Faith, and he joined not gods with Allah."'),
  ('en.yusufali', 16, 124, 'The Sabbath was only made (strict) for those who disagreed (as to its observance); But Allah will judge between them on the Day of Judgment, as to their differences.'),
  ('en.yusufali', 16, 125, 'Invite (all) to the Way of thy Lord with wisdom and beautiful preaching; and argue with them in ways that are best and most gracious: for thy Lord knoweth best, who have strayed from His Path, and who receive guidance.'),
  ('en.yusufali', 16, 126, 'And if ye do catch them out, catch them out no worse than they catch you out: But if ye show patience, that is indeed the best (course) for those who are patient.'),
  ('en.yusufali', 16, 127, 'And do thou be patient, for thy patience is but from Allah; nor grieve over them: and distress not thyself because of their plots.'),
  ('en.yusufali', 16, 128, 'For Allah is with those who restrain themselves, and those who do good.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 16, 1, 'Ataaa amrullaahi falaa tasta\'jilooh; Subhaanahoo wa Ta\'aalaa \'ammaa yushrikoon'),
  ('en.transliteration', 16, 2, 'Yunazzilul malaaa \'ikata birroohi min amrihee \'alaa mai yashaaa\'u min \'ibaadiheee an anzirooo annahoo laaa ilaaha illaaa ana fattaqoon'),
  ('en.transliteration', 16, 3, 'Khalaqas samaawaati wal arda bilhaqq; Ta\'aalaa \'ammaa yushrikoon'),
  ('en.transliteration', 16, 4, 'Khalaqal insaana min nutfatin fa izaa huwa khaseemum mubeen'),
  ('en.transliteration', 16, 5, 'Wal an \'amaa khalaqahaa; lakum feehaa dif\'unw wa manaafi\'u wa minhaa taakuloon'),
  ('en.transliteration', 16, 6, 'Wa lakum feehaa jamaalun heena tureehoona wa heena tasrahoon'),
  ('en.transliteration', 16, 7, 'Wa tahmilu asqaalakum ilaa baladil lam takoonoo baaligheehi illaa bishiqqil anfus; inna Rabbakum la Ra\'oofur Raheem'),
  ('en.transliteration', 16, 8, 'Walkhaila wal bighaala wal hameera litarkaboohaa wa zeenah; wa yakhluqu maa laa ta\'lamoon'),
  ('en.transliteration', 16, 9, 'Wa \'alal laahi qasdus sabeeli wa minhaa jaaa\'ir; wa law shaaa\'a lahadaakum ajma\'een'),
  ('en.transliteration', 16, 10, 'Huwal lazeee anzala minas samaaa\'i maaa\'al lakum minhu sharaabunw wa minhu shajarun feehi tuseemoon'),
  ('en.transliteration', 16, 11, 'Yumbitu lakum bihiz zar\'a wazzaitoona wanna kheela wal-a\'naaba wa min kullis samaraat, inna fee zaalika la Aayatal liqawminy yatafakkaroon'),
  ('en.transliteration', 16, 12, 'Wa sakkhkhara lakumul laila wannahaara wash shamsa walqamara wannujoomu musakhkharaatum bi amrih; inna fee zaalika la Aayaatil liqawminy ya\'qiloon'),
  ('en.transliteration', 16, 13, 'Wa maa zara a lakum fil ardi mukhtalifan alwaanuh; inna fee zaalika la Aayatal liqawminy yazakkaroon'),
  ('en.transliteration', 16, 14, 'Wa Huwal lazee sakhkharal bahra litaakuloo minhu lahman tariyyanw wa tastakhrijoo minhu hilyatan talbasoonahaa wa taral fulka mawaakhira feehi wa litabtaghoo min fadlihee wa la\'allakum tashkuroon'),
  ('en.transliteration', 16, 15, 'Wa alqaa fil ardi rawaasiya an tameeda bikum wa anhaaranw wa sublulal la \'allakum tahtadoon'),
  ('en.transliteration', 16, 16, 'Wa \'alaamaat; wa bin najmi hum yahtadoon'),
  ('en.transliteration', 16, 17, 'Afamany yakhluqu kamallaa yakhluq; afalaa tazak karoon'),
  ('en.transliteration', 16, 18, 'Wa in ta\'uddoo ni\'matal laahi laa tuhsoohaa; innal laaha la Ghafoorur Raheem'),
  ('en.transliteration', 16, 19, 'Wallaahu ya\'lamu maa tusirroona wa maa tu\'linoon'),
  ('en.transliteration', 16, 20, 'Wallazeena yad\'oona min doonil laahi laa yakhluqoona shai\'anw wa hum yukhlaqoon'),
  ('en.transliteration', 16, 21, 'Amwaatun ghairu ahyaaa\'inw wa maa yash\'uroona aiyaana yub\'asoon'),
  ('en.transliteration', 16, 22, 'Illahukum Ilaahunw Waahid; fallazeena laa yu\'minoona bil Aakhirati quloobuhum munkiratunw wa hum mustakbiroon'),
  ('en.transliteration', 16, 23, 'Laa jarama annal laaha ya\'lamu maa yusirrona wa ma yu\'linoon; innahoo laa yuhibbul mustakbireen'),
  ('en.transliteration', 16, 24, 'Wa izaa qeela lahum maazaaa anzala Rabbukum qaaloo asaateerul awwaleen'),
  ('en.transliteration', 16, 25, 'Liyahmilooo awzaarahum kaamilatany Yawmal Qiyaamati wa min awzaaril lazeena yudilloonahum bighairi \'ilm; alaa saaa\'a maa yaziroon'),
  ('en.transliteration', 16, 26, 'Qad makaral lazeena min qablihim fa atal laahu bunyaa nahum minal qawaa\'idi fakharra \'alaihimus saqfu min fawqihim wa ataahumul \'azaabu min haisu laa yash\'uroon'),
  ('en.transliteration', 16, 27, 'Summa Yawmal Qiyaamati yukhzeehim wa yaqoolu aina shurakaaa\'iyal lazeena kuntum tushaaaqqoona feehim; qaalal lazeena ootul \'ilma innal khizyal Yawma wassooo\'a \'alal kaafireen'),
  ('en.transliteration', 16, 28, 'Allazeena tatawaf faahu mul malaaa\'ikatu zaalimeee anfusihim fa alqawus salama maa kunnaa na\'malu min sooo\'; balaaa innal laaha \'aleemum bimaa kuntum ta\'maloon'),
  ('en.transliteration', 16, 29, 'Fadkhulooo abwaaba jahannama khaalideena feeha falabi\'sa maswal mutakab bireen'),
  ('en.transliteration', 16, 30, 'Wa qeela lillazeenat taqaw maazaaa anzala Rabbukum; qaaloo khairaa; lillazeena absanoo fee haazihid dunyaa hasanah; wa la Daarul Aakhirati khair; wa lani\'ma daarul muttaqeen'),
  ('en.transliteration', 16, 31, 'Jannaatu \'Adniny yadkhuloonahaa tajree min tahtihal anhaaru lahum feehaa maa yashaaa\'oon; kazaalika yajzil laahul muttaqeen'),
  ('en.transliteration', 16, 32, 'Allazeena tatawaf faahumul malaaa\'ikatu taiyibeena yaqooloona salaamun \'alai kumud khulul Jannata bimaa kuntum ta\'maloon'),
  ('en.transliteration', 16, 33, 'Hal yanzuroona illaaa an taatiyahumul malaaa\'ikatu aw yaatiya amru Rabbik; kazaalika fa\'alal lazeena min qablihim; wa maa zalamahumul laahu wa laakin kaanoo anfusahum yazlimoon'),
  ('en.transliteration', 16, 34, 'Fa asaabahum saiyi aatu maa \'amiloo wa haaqa bihim maa kaano bihee yastahzi\'oon'),
  ('en.transliteration', 16, 35, 'Wa qaalal lazeena ashrakoo law shaaa\'al laahu ma \'abadnaa min doonihee min shai\'in nahnu wa laaa aabaaa\'unaa wa laa harramnaa min doonihee min shai\'; kazaalika fa\'alal lazeena min qablihim fahal \'alar Rusuli illal balaaghul mubeen'),
  ('en.transliteration', 16, 36, 'Wa laqad ba\'asnaa fee kulli ummatir Rasoolan ani\'budul laaha wajtanibut Taaghoota faminhum man hadal laahu wa minhum man haqqat \'alaihid dalaalah; faseeroo fil ardi fanzuroo kaifa kaana \'aaqibatul mukazzibeen'),
  ('en.transliteration', 16, 37, 'In tahris \'alaa hudaahum fa innal laaha laa yahdee mai yudillu wa maa lahum min naasireen'),
  ('en.transliteration', 16, 38, 'Wa aqsamoo billaahi jahda aimaanihim laa yab\'asul laahu mai yamoot; balaa wa\'dan \'alaihi haqqanw wa laakinna aksaran naasi laa ya\'lamoon'),
  ('en.transliteration', 16, 39, 'Liyubaiyina lahumul lazee yakhtalifoona feehi wa liya\'lamal lazeena kafarooo annahum kaanoo kaazibeen'),
  ('en.transliteration', 16, 40, 'Innamaa qawlunaa lisha y\'in izaa aradnaahu an naqoola lahoo kun fa yakoon'),
  ('en.transliteration', 16, 41, 'Wallazeena haajaroo fil laahi mim ba\'di maa zulimoo lanubawwi\' annahum fiddunyaa hasanatanw wa la ajrul Aakhirati akbar; law kaanoo ya\'lamoon'),
  ('en.transliteration', 16, 42, 'Allazeena sabaroo wa \'alaa Rabbihim yatawak kaloon'),
  ('en.transliteration', 16, 43, 'Wa maaa arsalnaa min qablika illaa rijaalan nooheee ilaihim; fas\'alooo ahlaz zikri in kuntum laa ta\'lamoon'),
  ('en.transliteration', 16, 44, 'Bilbaiyinaati waz Zubur; wa anzalnaaa ilaikaz Zikra litubaiyina linnaasi maa nuzzila ilaihim wa la\'allahum yatafakkaroon'),
  ('en.transliteration', 16, 45, 'Afa aminal lazeena makarus saiyi aati ai yakhsifal laahu bihimul arda aw yaaa tiyahumul \'azaabu min haisu laa yash\'uroon'),
  ('en.transliteration', 16, 46, 'Aw yaakhuzahum fee taqallubihim famaa hum bi mu\'jizeen'),
  ('en.transliteration', 16, 47, 'Aw yaakhuzahum \'alaa takhawwuf; fa inna Rabbakum la Ra\'oofur Raheem'),
  ('en.transliteration', 16, 48, 'Awa lam yaraw ilaa maa khalaqal laahu min shai\'iny-yatafaiya\'u zilaaluhoo \'anil yameeni washshamaaa\' ili sujjadal lillaahi wa hum daakhiroon'),
  ('en.transliteration', 16, 49, 'Wa lillaahi yasjudu maa fis samaawaati wa maa fil ardi min daaabbatinw walma laaa\'ikatu wa hum laa yastakbiroon'),
  ('en.transliteration', 16, 50, 'yakhaafoona Rabbahum min fawqihim wa yaf\'aloona maa yu\'maroon'),
  ('en.transliteration', 16, 51, 'Wa qaalal laahu laa tatta khizooo ilaahainis naini innamaa Huwa Ilaahunw Waahid; fa iyyaaya farhaboon'),
  ('en.transliteration', 16, 52, 'Wa lahoo maa fis samaawaati wal ardi wa lahud deenu waasibaa; afaghairal laahi tattaqoon'),
  ('en.transliteration', 16, 53, 'Wa maa bikum minni\'matin faminal laahi summa izaa massakumud durru fa ilaihi taj\'aroon'),
  ('en.transliteration', 16, 54, 'Summaa izaa kashafad durra \'ankum izaa fareequm minkum bi Rabbihim yushrikoon'),
  ('en.transliteration', 16, 55, 'Liyakfuroo bimaa aatainaahum; fatamatta\'oo, faswfa ta\'lamoon'),
  ('en.transliteration', 16, 56, 'Wa yaj\'aloona limaa laa ya\'lamoona naseebam mimmaa razaqnnaahum; tallaahi latus\'alunaa \'ammaa kuntum taftaroon'),
  ('en.transliteration', 16, 57, 'Wa yaj\'aloona lillaahil banaati Subhaanahoo wa lahum maa yashtahoon'),
  ('en.transliteration', 16, 58, 'Wa izaa bushshira ahaduhum bil unsaa zalla wajhuhoo muswaddanw wa huwa kazeem'),
  ('en.transliteration', 16, 59, 'yatawaaraa minal qawmimin sooo\'i maa bushshira bih; a-yumsikuhoo \'alaa hoonin am yadussuhoo fit turaab; alaa saaa\'a maa yahkumoon'),
  ('en.transliteration', 16, 60, 'Lillazeena laa yu\'minoona bil Aakhirati masalus saw\'i wa lillaahil masalul a\'laa; wa Huwal \'Azeezul Hakeem'),
  ('en.transliteration', 16, 61, 'Wa law yu\'aakhizul laahun naasa bizulminhim maa taraka \'alaihaa min daaabbatinw wa laakiny yu\'akhkhiruhum ilaaa ajalim musamman fa izaa jaaa\'a ajaluhum laa yastaakhiroona saa\'atanw wa laa yastaqdimoon'),
  ('en.transliteration', 16, 62, 'Wa yaj\'aloona lillaahi maa yakrahoona wa tasifu alsinatuhumul kaziba anna lahumul husnaa laa jarama anna lahumun Naara wa annahum mufratoon'),
  ('en.transliteration', 16, 63, 'Tallaahi laqad arsalnaaa ilaaa umamim min qablika fazayyana lahumush Shaitaanu a\'maalahum fahuwa waliyyuhumul yawma wa lahum \'azaabun aleem'),
  ('en.transliteration', 16, 64, 'Wa maaa anzalnaa \'alaikal Kitaaba illaa litubaiyina lahumul lazikh talafoo feehi wa hudanw wa rahmatal liqawminy yu\'minoon'),
  ('en.transliteration', 16, 65, 'Wallaahu anzala minas samaaa\'i maaa\'an fa ahyaa bihil arda ba\'da mawtihaa; inna fee zaalika la aayatal liqaw miny yasma\'oon'),
  ('en.transliteration', 16, 66, 'Wa inna lakum fil an\'aami la\'ibrah; nusqeekum mimmmaa fee butoonihee mim baini farsinw wa damil labanann khaalisan saaa\'ighallish shaaribeen'),
  ('en.transliteration', 16, 67, 'Wa min samaraatin nakheeli wal a\'nnaabi tattakhizoona minhu sakaranw wa rizqann hasanaa; inna fee zaalika la Aayatal liqawminy ya\'qiloon'),
  ('en.transliteration', 16, 68, 'Wa awhaa Rabbuka ilannnabli anit takhizee minal jabaali buyootanw wa minash shajari wa mimmaa ya\'rishoon'),
  ('en.transliteration', 16, 69, 'Summma kulee min kullis samaraati faslukee subula Rabbiki zululaa; yakhruju mim butoonihaa sharaabum mukh talifun alwaanuhoo feehi shifaaa\'ul linnaas, innna fee zaalika la Aayatal liqawminy yatafakkaroon'),
  ('en.transliteration', 16, 70, 'Wallaahu khalaqakum suma tatawaffaakum; wa minkum many-yuradu ilaaa arzalil \'umuri likai laa ya\'lama ba\'da \'ilmin shai\'aa; innal laaha \'Aleemun Qadeer'),
  ('en.transliteration', 16, 71, 'Wallaahu faddala ba\'dakum \'alaa ba\'din fir rizq; famal lazeena fuddiloo biraaaddee rizqihim \'alaa maa malakat aimaanuhum fahum feehi sawaaa\'; afabini\'matil laahi yajhadoon'),
  ('en.transliteration', 16, 72, 'Wallaahu ja\'ala lakum min anfusikum azwaajanw wa ja\'ala lakum min azwaajikum baneena wa hafadatanw wa razaqakum minat yaiyibaat; afabil baatili yu\'minoona wa bini\'matil laahi hum yakkfuroon'),
  ('en.transliteration', 16, 73, 'Wa ya\'budoona min doonil laahi maa laa yamliku lahum rizqam minas samaawaati wal ardi shai\'anw wa laa yastatee\'oon'),
  ('en.transliteration', 16, 74, 'Falaa tadriboo lillaahil amsaal; innal laaha ya\'lamu wa antum laa ta\'lamoon'),
  ('en.transliteration', 16, 75, 'Darabal laahu masalan \'abdam mammlookal laa yaqdiru \'alaa shai\'inw wa marrazaqnaahu mminnaa rizqan hasanan fahuwa yunfiqu minhu sirranw wa jahra; hal yasta-woon; alhamdu lillaah; bal aksaruhum laa ya\'lamoon'),
  ('en.transliteration', 16, 76, 'Wa darabal laahu masalar rajulaini ahaduhumaaa abkamu laa yaqdiru \'alaa shai\'inw wa huwa kallun \'alaa mawlaahu ainamaa yuwajjihhu laa yaati bikhairin hal yastawee huwa wa many-yaamuru bil\'adli wa huwa \'alaa Siraatim MMustaqeem'),
  ('en.transliteration', 16, 77, 'Wa lillaahi ghaibus samaawaati wal ard; wa maaa amrus Saa\'ati illaa kalamhil basari aw huwa aqrab; innal laaha \'alaaa kulli shai\'in Qadeer'),
  ('en.transliteration', 16, 78, 'Wallaahu akhrajakum mim butooni ummahaatikum laa ta\'lamoona shai\'anw wa ja\'ala lakumus sam\'a wal absaara wal af\'idata la\'allakum tashkuroon'),
  ('en.transliteration', 16, 79, 'Alam yaraw ilat tairi musakhkharaatin fee jawwis samaaa\'i maa yumsikuhunna illal laah; inna fee zaalika la Aayaatil liqawminy yu\'minoon'),
  ('en.transliteration', 16, 80, 'Wallaahu ja\'ala lakum min juloodil an\'aami buyootan tastakhif foonahaa yawma za\'nikum wa yawma iqaamatikum wa min aswaafihaa wa awbaarihaa wa ash\'aarihaaa asaasanw wa mataa\'an ilaa been'),
  ('en.transliteration', 16, 81, 'Wallaahu ja\'ala lakum mimmaa khalaqa zilaalanw wa ja\'ala lakum minal jibaali aknaananw wa ja\'ala lakum saraabeela taqeekumul harra wa saraabeela taqeekum baasakum; kazaalika yutimmu ni\'matahoo alaikum la\'allakum tuslimoon'),
  ('en.transliteration', 16, 82, 'Fa in tawallaw fa innamaa \'alaikal balaaghul mubeen'),
  ('en.transliteration', 16, 83, 'Ya\'rifoona ni\'matal laahi summa yunkiroonahaa wa aksaruhumul kaafiroon'),
  ('en.transliteration', 16, 84, 'Wa yawma nab\'asu min kulli ummatin shaheedan summa laa yu\'zanu lillazeena kafaroo wa laa hum yusta\'taboon'),
  ('en.transliteration', 16, 85, 'Wa izaa ra al lazeena zalamul \'azaaba falaa yukhaf fafu \'anhum wa laa hum yunzaroon'),
  ('en.transliteration', 16, 86, 'Wa izaa ra al lazeena ashrakoo shurakaaa\'ahum qaaloo Rabbana haaa\'ulaaa\'i shurakaaa\'unal lazeena kunnaa nad\'oo min doonika fa alqaw ilaihimul qawla innakum lakaaziboon'),
  ('en.transliteration', 16, 87, 'Wa alqaw ilal laahi yawma\'izinis salama wa dalla \'anhum maa kaanoo yaftaroon'),
  ('en.transliteration', 16, 88, 'Allazeena kafaroo wa saddoo \'an sabeelil laahi zidnaahum \'azaaban fawqal \'azaabi bimaa kaanoo yufsidoon'),
  ('en.transliteration', 16, 89, 'Wa yawma nab\'asu fee kulli ummmatin shaheedan \'alaihim min anfusihim wa ji\'naa bika shaheedan \'alaa haaa\'ulaaa\'; wa nazzalnaa \'alaikal Kitaaba tibyaanal likulli shai\'inw wa hudanw wa rahmatanw wa bushraa lilmuslimeen'),
  ('en.transliteration', 16, 90, 'Innal laaha yaamaru bil \'adli wal ihsaani wa eetaaa\'i zil qurbaa wa yanhaa \'anil fahshaaa\'i wal munkari walbagh-i\' ya\'izukum la\'allakum tazakkkaroon'),
  ('en.transliteration', 16, 91, 'Wa awfoo bi Ahdil laahi izaa \'aahattum wa laa tanqudul aimaana ba\'da tawkeedihaa wa qad ja\'altumul laaha \'alaikum kafeelaa; innal laaha ya\'lamu maa taf\'aloon'),
  ('en.transliteration', 16, 92, 'Wa laa takoonoo kallatee naqadat ghazlahaa mim ba\'di quwwatin ankaasaa; tattakhizoona aimaanakum dakhlalam bainakum an takoona ummatun hiya arbaa min ummah; innnamaa yablookumul laahu bih; wa la yubaiyinanna lakum yawmal Qiyaamati maa kuntum fee takhtalifoon'),
  ('en.transliteration', 16, 93, 'Wa law shaaa\'al laahu laja\'alakum ummmatanw waahidatanw wa laakiny yudillu many-yashaaa\'u wa yahdee many-yashaaa\'; wa latus\'alunna \'ammaa kuntum ta\'maloon'),
  ('en.transliteration', 16, 94, 'Wa laa tattakhizooo aimaanakum dakhalam bainakum ftazilla qadamum ba\'da subootihaa wa tazooqus sooo\'a bimmaa sadattum \'an sabeelil laahi wa lakum \'azaabun \'azeem'),
  ('en.transliteration', 16, 95, 'Wa laa tashtaroo bi \'ahdil laahi samanan qaleelaa; innamaa \'indal laahi huwa khairul lakum in kuntum ta\'lamoon'),
  ('en.transliteration', 16, 96, 'maa \'indakum yanfadu wa maa \'indal laahi baaq; wa lanajziyannal lazeena sabarooo ajjrahum bi ahsani maa kaanoo ya\'maloon'),
  ('en.transliteration', 16, 97, 'Man \'amila saaliham min zakarin aw unsaa wa huwa mu\'minun falanuhyiyannahoo hayaatan taiiyibatanw wa lanajzi yannnahum ajrahum bi ahsani maa kaanoo ya\'maloon'),
  ('en.transliteration', 16, 98, 'Fa izaa qara tal Quraana fasta\'iz billaahi minashh Shai taanir rajeem'),
  ('en.transliteration', 16, 99, 'Innahoo laisa lahoo sultaanun \'alal lazeena aamanoo wa \'alaa Rabbihim yatawakkaloon'),
  ('en.transliteration', 16, 100, 'Innnamaa sultaanuhoo \'alal lazeena yatawallawnahoo wallazeena hum bihee mushrikoon'),
  ('en.transliteration', 16, 101, 'Wa izaa baddalnaaa Aayatam makaana Aayatinw wal laahu a\'lamu bimaa yunazzilu qaalooo innamaa anta muftar; bal aksaruhum laa ya\'lamoon'),
  ('en.transliteration', 16, 102, 'Qul nazzalahoo Roohul Qudusi mir Rabbika bilhaqqi liyusabbital lazeena aamanoo wa hudanw wa bushraa lilmuslimeen'),
  ('en.transliteration', 16, 103, 'Wa laqad na\'lamu annahum yaqooloona innamaa yu\'allimuhoo bashar; lisaanul lazee yulhidoona ilaihi a\'ja miyyunw wa haaza lisaanun \'Arabiyyum mubeen'),
  ('en.transliteration', 16, 104, 'Innal lazeena laa yu\'minoona bi Aayaatil laahi laa yahdehimul laahu wa lahum \'azaabun aleem'),
  ('en.transliteration', 16, 105, 'Innamaa yaftaril kazibal lazeena laa yu\'minoona bi Aayaatil laahi wa ulaaa\'ika humul kaaziboon'),
  ('en.transliteration', 16, 106, 'man kafara billaahi mim ba\'di eemaanihee illaa man ukriha wa qalbuhoo mutmma\'innum bil eemaani wa laakim man sharaha bilkufri sadran fa\'alaihim ghadabum minal laahi wa lahum \'azaabun \'azeem'),
  ('en.transliteration', 16, 107, 'Zaalika bi annahumus tahabbul hayaatad dunyaa \'alal Aakhirati wa annal laaha laa yahdil qawmal kaafireen'),
  ('en.transliteration', 16, 108, 'Ulaaa\'ikal lazeena taba\'al laahu \'alaa quloobihim wa sam\'ihim wa absaarihim wa ulaaa\'ika humul ghaafiloon'),
  ('en.transliteration', 16, 109, 'Laa jarama annnahum fil Aakhirati humul khassiroon'),
  ('en.transliteration', 16, 110, 'Summa inna Rabbaka lillazeena haajaroo mim ba\'dimaa futinoo summma jaahadoo wa sabaroo inna Rabbaka mim ba\'dihaa la Ghafoorur Raheem'),
  ('en.transliteration', 16, 111, 'Yawma taatee kullu nafsin tujaadilu \'an nafsihaa wa tuwaffaa kullu nafsim maa \'amilat wa hum laa yuzlamoon'),
  ('en.transliteration', 16, 112, 'Wa darabal laahu masalan qaryatan kaanat aaminatam mutma\'innatany yaaateehaa rizquhaa rghadam min kulli makaanin fakafarat bi an\'umil laahi fa azaaqahal laahu libaasal joo\'i walkhawfi bimaa kaanoo yasna\'oon'),
  ('en.transliteration', 16, 113, 'Wa laqad jaaa\'ahum Rasoolum minhum fakazzaboohu fa akhazahumul \'azaabu wa hum zaalimoon'),
  ('en.transliteration', 16, 114, 'Fakuloo mimmaa razaqa kumul laahu halaalan taiyibanw washkuroo ni\'matal laahi in kuntum iyyaahu ta\'budoon'),
  ('en.transliteration', 16, 115, 'Innamaa harrma \'alai kumul maitata waddama wa lahmal khinzeeri wa maaa uhilla lighairil laahi bihee famanid turra ghaira baaghinw wa laa \'aadin fa innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 16, 116, 'Wa laa taqooloo limaa tasifu alsinatukumul kaziba haaza halaalunw wa haazaa haraamul litaftaroo \'alal laahil kazib; innal lazeena yaftaroona \'alal laahil kaziba laa yuflihoon'),
  ('en.transliteration', 16, 117, 'Mata\'un qaleelunw wa lahum \'azaabun aleem'),
  ('en.transliteration', 16, 118, 'Wa \'alal lazeena haadoo harramnaa ma qasasnaa \'alaika min qablu wa maa zalamanaahum wa laakin kaanoo anfusahum wa laakin kaanoo anfusahum yazlimoon'),
  ('en.transliteration', 16, 119, 'Summma inna Rabbaka lillazeena \'amilus sooo\'a bijahaalatin summa taaboo mim ba\'di zaaalika wa aslahoo inna Rabbaka mim ba\'dihaa la Ghafoorur Raheem'),
  ('en.transliteration', 16, 120, 'Inna Ibraaheema kaana ummatan qaanital lillaahi Haneefanw wa lam yakuminal mushrikeen'),
  ('en.transliteration', 16, 121, 'Shaakiral li an\'umih; ijtabaahu wa hadaahu ilaa Siraatim Muustaqeem'),
  ('en.transliteration', 16, 122, 'Wa aatainaahu fid dunyaa hasanah; wa innahoo fil Aakhirati laminas saaliheen'),
  ('en.transliteration', 16, 123, 'Summma awhainaa ilaika anit tabi\' Millata Ibraaheema haneefaa; wa maa kaana minal mushrikeen'),
  ('en.transliteration', 16, 124, 'Innnamaa ju\'ilas Sabtu \'alal lazeenakhtalafoo feeh; wa inna Rabbaka la yahkumu bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon'),
  ('en.transliteration', 16, 125, 'Ud\'u ilaa sabeeli Rabbika bilhikmati walmaw \'izatil hasanati wa jaadilhum billatee hiya ahsan; inna Rabbaka huwa a\'almu biman dalla \'an sabeelihee wa Huwa a\'lamu bilmuhtadeen'),
  ('en.transliteration', 16, 126, 'Wa in \'aaqabtum fa\'aaqiboo bimisli maa \'ooqibtum bihee wa la\'in sabartum lahuwa khairul lissaabireen'),
  ('en.transliteration', 16, 127, 'Wasbir wa maa sabruka illaa billaah; wa laa tahzan \'alaihim wa laa taku fee daiqim mimmaa yamkuroon'),
  ('en.transliteration', 16, 128, 'Innal laaha ma\'al lazeenat taqaw wal lazeena hum muhsinoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 16, 1, 'الله کا حکم آ پہنچا تم اس میں جلدی مت کرو وہ لوگو ں کے شرک سے پاک اور برتر ہے'),
  ('ur.ahmedali', 16, 2, 'وہ اپنے بندوں سے جس کے پاس چاہتا ہے فرشتوں کو وحی دے کر بھیج دیتا ہے یہ کہ خبردار کر دو کہ میرے سوا کوئی عبادت کے لائق نہیں پس مجھ سے ڈرتے رہو'),
  ('ur.ahmedali', 16, 3, 'اسی نے آسمان اور زمین کو ٹھیک طور پر بنایا ہے وہ ان کے شرک سے پاک ہے'),
  ('ur.ahmedali', 16, 4, 'اسی نے آدمی کو ایک بوند سے پیدا کیا پھر وہ یکایک کھلم کھلا جھگڑنے لگا'),
  ('ur.ahmedali', 16, 5, 'اور تمہارے واسطے چار پایوں کو بھی اسی نے بنایا ان میں تمہارے لیے جاڑے کابھی سامان ہے اوربھی بہت سے فائدے ہیں اور ان میں سے کھاتے بھی ہو'),
  ('ur.ahmedali', 16, 6, 'اور تمہاے لیے ان میں زینت بھی ہے جب شام کو چرا کر لاتے ہو اور جب چرانے لے جاتے ہو'),
  ('ur.ahmedali', 16, 7, 'اور وہ تمہارے بوجھ اٹھا کر ان شہروں تک لے جاتے ہیں کہ جہاں تک تم جان کو تکلیف میں ڈالنے کے سوا نہیں پہنچ سکتے تھے بے شک تمہارا رب شفقت کرنے والا مہربان ہے'),
  ('ur.ahmedali', 16, 8, 'اور گھوڑے خچر اور گدھے پیدا کیے کہ ان پر سوار ہو اور زینت کے لیے اور وہ چیزیں پیدا کرتا ہے جو تم نہیں جانتے'),
  ('ur.ahmedali', 16, 9, 'اور الله تک سیدھی راہ پہنچتی ہے اور بعض ان میں ٹیڑھی بھی ہیں اور اگر الله چاہتا تو تم سب کو سیدھی راہ بھی دکھا دیتا'),
  ('ur.ahmedali', 16, 10, 'وہی ہے جس نے آسمان سے تمہارے لیے پانی نازل کیا اسی میں سے پیتے ہو اور اسی سے درخت ہوتے ہیں جن میں چراتے ہو'),
  ('ur.ahmedali', 16, 11, 'تمہارے واسطے اسی سے کھیتی اور زیتوں اورکھجوریں اورانگور اور ہر قسم کے میوے اگاتا ہے بے شک اس میں ان لوگو ں کے لیے نشانی ہے جو غور کرتے ہیں'),
  ('ur.ahmedali', 16, 12, 'اور رات اور دن اور سورج اور چاند کو تمہارے کام میں لگا دیا ہے اور اسی کے حکم سے ستارے بھی کام میں لگے ہوئے ہیں بے شک اس میں لوگوں کے لیے نشانیاں ہیں جو سمجھ رکھتے ہیں'),
  ('ur.ahmedali', 16, 13, 'اور تمہارے واسطے جو چیزیں زمین میں رنگ برنگ کی پھیلائی ہیں ان میں لوگوں کے لیے نشانی ہے ہے جو سوچتے ہیں'),
  ('ur.ahmedali', 16, 14, 'اور وہ وہی ہے جس نے دریا کو کام میں لگا دیا کہ اس میں تازہ گوشت کھاؤ اور اسی سے زیور نکالو جسے تم پہنتے ہو اور تو اس میں جہازوں کو دیکھتا ہے کہ پانی کو چیرتے ہوئے چلے جاتے ہیں اور تاکہ تم اس کے فضل کو تلاش کرو اور تاکہ تم شکر کرو'),
  ('ur.ahmedali', 16, 15, 'اور زمین پر پہاڑوں کے بوجھ ڈال دیے تاکہ تمہیں لے کر نہ ڈگمگائے اور تمہارے لیے نہریں اور راستے بنا دیے تاکہ تم راہ پاؤ'),
  ('ur.ahmedali', 16, 16, 'اور نشانیاں بنائیں اور ستاروں سے لوگ راہ پاتے ہیں'),
  ('ur.ahmedali', 16, 17, 'پھر کیا جو شخص پیدا کرے اس کے برابر ہے جو کچھ بھی پیدا نہ کرے کیا تم سوچتے نہیں'),
  ('ur.ahmedali', 16, 18, 'اور اگر تم الله کی نعمتو ں کو گننے لگو تو ان کا شمار نہیں کر سکو گےبے شک الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 16, 19, 'اور الله جانتا ہے جو تم چھپاتے ہو اور جو تم ظاہر کرتےہو'),
  ('ur.ahmedali', 16, 20, 'اور جنہیں الله کے سوا پکارتے ہیں وہ کچھ بھی پیدانہیں کرتے اور وہ خود پیدا کیے ہوئے ہیں'),
  ('ur.ahmedali', 16, 21, 'وہ تو مردے ہیں جن میں جان نہیں اور وہ نہیں جانتے کہ لوگ کب اٹھائے جائیں گے'),
  ('ur.ahmedali', 16, 22, 'تمہارا معبود اکیلا معبود ہے پھر جو آخرت پر ایمان نہیں رکھتے ان کے دل نہیں مانتے اور وہ تکبر کرنے والے ہیں'),
  ('ur.ahmedali', 16, 23, 'ضرور الله جانتا ہے جو کچھ چھپاتے ہیں اور جو کچھ ظاہر کرتے ہیں بے شک وہ غرور کرنے والوں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 16, 24, 'اور جب ان سے کہا جائے کہ تمہارے رب نے کیا نازل کیا ہے کہتے ہیں پہلے لوگوں کے قصے ہیں تاکہ قیامت کے دن اپنے بوجھ پورے اٹھائيں اورکچھ ان کے بوجھ جنہیں بے علمی سے گمراہ کرتے ہیں خبردار برا بوجھ ہے جواٹھاتے ہیں'),
  ('ur.ahmedali', 16, 25, 'ان سے پہلےلوگوں نے بھی مکر کیا تھا پھر الله نے ان کی عمارت کو جڑوں سے ڈھا دیا پھر ان پر اوپر سے چھت گر پڑی اور ان پر عذاب آیا جہاں سے انہیں خبر بھی نہ تھی'),
  ('ur.ahmedali', 16, 26, 'پھر قیامت کے دن انہیں رسوا کرے گا اور کہے گا میرے شریک کہاں ہیں جن پر تمہیں بڑی ضد تھی جنہیں علم دیا گیا تھا وہ کہیں گے کہ بے شک آج کافروں کے لیے رسوائی اور برائی ہے'),
  ('ur.ahmedali', 16, 27, 'یہ وہ لوگ ہیں کہ فرشتوں نے ان کی ایسی حالت میں روح نکالی تھی کہ وہ اپنے آپ پر ظلم کر رہے تھے'),
  ('ur.ahmedali', 16, 28, 'پھر وہ صلح کا پیغام بھیجیں گے کہ ہم تو کوئی برا کام نہ کرتے تھے کیوں نہیں بے شک الله کو تمہارے اعمال کی پوری خبر ہے'),
  ('ur.ahmedali', 16, 29, 'سو دوزخ کے دروازوں میں داخل ہو جاؤ اس میں ہمیشہ رہو پس متکبرین کا کیا ہی برا ٹھکانہ ہے'),
  ('ur.ahmedali', 16, 30, 'اور پرہیزگاروں سے کہا جاتا ہے کہ تمہارے رب نے کیا نازل کیا ہے تو کہتے ہیں اچھی چیز جنہوں نے نیکی کی ہے (ان کے لیے) اس دنیا میں بھی بہتری ہے اور البتہ آخرت کا گھر تو بہت ہی بہتر ہے اور پرہیزگاروں کا کیا ہی اچھا گھر ہے'),
  ('ur.ahmedali', 16, 31, 'ہمیشہ رہنے کے باغ ہیں جن میں وہ داخل ہوں گے اور ان کے نیچے نہریں بہتی ہوں گی جو چاہیں گے انہیں وہاں ملے گا الله پرہیزگاروں کو ایسا ہی بدلہ دے گا'),
  ('ur.ahmedali', 16, 32, 'جن کی جان فرشتے قبض کرتے ہیں ایسے حال میں کہ وہ پاک ہیں فرشتے کہیں گے تم پر سلامتی ہو بہشت میں داخل ہو جاؤ بسبب ان کاموں کے جو تم کرتے تھے'),
  ('ur.ahmedali', 16, 33, 'کیا اب اس کے منتظر ہیں کہ ان پر فرشتے آویں یا تیرے رب کا حکم آئے اسی طرح ان سے پہلوں نے بھی کیا تھا اور الله نے ان پر ظلم نہیں کیا اور لیکن وہ اپنے نفسوں پر ظلم کرتے تھے'),
  ('ur.ahmedali', 16, 34, 'پھر انہیں ان کے بد اعمال کے نتیجے مل کر رہے اورجس کی وہ ہنسی اڑایا کرتے تھے وہی ان پر نازل ہوا'),
  ('ur.ahmedali', 16, 35, 'اور مشرک کہتے ہیں اگر الله چاہتا تو ہم اس کے سوا کسی چیز کی عبادت نہ کرتے اور نہ ہمارے باپ دادا اور اس کے حکم کے سوا ہم کسی چیز کو حرام نہ ٹھیراتے اسی طرح کیا ان لوگو ں نے جو ان سے پہلے تھے پھر رسولوں کے ذمہ تو صرف صاف پہنچا دینا ہے'),
  ('ur.ahmedali', 16, 36, 'اور البتہ تحقیق ہم نے ہر امت میں یہ پیغام دے کر رسول بھیجا کہ الله کی عبادت کرو اور شیطان سے بچو پھر ان میں سے بعض کو الله نے ہدایت دی اوربعض پر گمراہی ثابت ہوئی پھر ملک میں پھر کر دیکھو کہ جھٹلانے والوں کا انجام کیا ہوا'),
  ('ur.ahmedali', 16, 37, 'اگر تو انہیں ہدایت پرلانے کی طمع کرے تو الله ہدایت نہیں دیتا اس شخص کو جسے گمراہ کر دے اور نہ ان کے لیے کوئی مددگار ہوگا'),
  ('ur.ahmedali', 16, 38, 'اور الله کی سخت قسمیں کھا کر کہتے ہیں کہ الله انہیں اٹھائے گا اس شخص کو جو مر جائے گا ہاں اس نے اپنے ذمہ پکا وعدہ کر لیا ہے لیکن بہت سے لوگ نہیں جانتے'),
  ('ur.ahmedali', 16, 39, 'تاکہ ان پر ظاہر کر دے وہ بات جس میں یہ جھگڑتے ہیں اور تاکہ کافر معلوم کر لیں کہ وہ جھوٹے تھے'),
  ('ur.ahmedali', 16, 40, 'ہم جس کام کےکرنے کا ارادہ کرتے ہیں تو اس کے لیے ہمارا اتنا ہی کہنا کافی ہے کہ ہم اسے کہہ دیں کہ ہو جا پھر ہو جاتا ہے'),
  ('ur.ahmedali', 16, 41, 'اورجنہوں نے الله کے واسطے گھر چھوڑا اس کےبعد ان پر ظلم کیا گیا تھا تو البتہ ہم نے انہیں دنیا میں اچھی جگہ دیں گے اور آخرت کا ثواب تو بہت ہی بڑا ہے کاش یہ لوگ سمجھ جاتے'),
  ('ur.ahmedali', 16, 42, 'جو لوگ ثابت قدم رہے اور اپنے رب پر بھروسہ کیا'),
  ('ur.ahmedali', 16, 43, 'اور ہم نے تجھ سے پہلے بھی تو انسان ہی بھیجے تھے جن کی طرف ہم وحی بھیجا کرتے تھے سو اگر تمہیں معلوم نہیں تو اہلِ علم سے پوچھ لو'),
  ('ur.ahmedali', 16, 44, 'ہم نے انہیں معجزات اور کتابیں دے کر بھیجا تھا اور ہم نے تیری طرف قرآن نازل کیا تاکہ لوگو ں کے لیے واضح کر دے جو ان کی طرف نازل کیا گیا ہے اور تاکہ وہ سوچ لیں'),
  ('ur.ahmedali', 16, 45, 'پس کیا وہ لوگ نڈر ہو گئے ہیں جو برے فریب کرتے ہیں اس سے کہ الله انہیں زمین میں دھنسا دے یاان پر عذاب آئے جہاں سے انہیں خبر بھی نہ ہو'),
  ('ur.ahmedali', 16, 46, 'یا انہیں چلتے پھرتے پکڑے پس وہ عاجز کرنے والے نہیں ہیں'),
  ('ur.ahmedali', 16, 47, 'یا انہیں ڈرانے کے بعد پکڑے پس تحقیق تمہارا رب نہایت ہی شفیق رحم کرنے والا ہے'),
  ('ur.ahmedali', 16, 48, 'کیا وہ الله کی پیدا کی ہوئی چیزوں کونہیں دیکھتے کہ کے سائے دائیں اوربائیں طرف جھکے جارہے ہیں اور نہایت عاجزی کے ساتھ الله کو سجدہ کررہے ہیں'),
  ('ur.ahmedali', 16, 49, 'اور جو آسمان میں ہے اور جو زمین میں ہے جانداروں سے اور فرشتے سب الله ہی کو سجدہ کرتے ہیں اوروہ تکبرنہیں کرتے'),
  ('ur.ahmedali', 16, 50, 'وہ اپنے بالادست رب سے ڈرتے ہیں اور انہیں جو حکم دیا جاتا ہے وہ بجا لاتے ہیں'),
  ('ur.ahmedali', 16, 51, 'الله نے کہا ہے دو معبود نہ بناؤ وہ ایک ہی معبود ہے پھر مجھ ہی سے ڈرو'),
  ('ur.ahmedali', 16, 52, 'اوراسی کا ہے جوکچھ آسمانوں اور زمین میں ہے اور عبادت اسی کی لازم ہے پھرکیا الله کے سوا اوروں سے ڈرتے ہو'),
  ('ur.ahmedali', 16, 53, 'اور تمہارے پاس جو نعمت بھی ہے سو الله کی طرف سے ہے پھر جب تمہیں تکلیف پہنچتی ہے تواسی سے فریاد کرتے ہو'),
  ('ur.ahmedali', 16, 54, 'پھر جب تم سے تکلیف دور کر دیتا ہےتو فوراً تم میں سے ایک جماعت اپنے رب کے ساتھ شریک بنانے لگتی ہے'),
  ('ur.ahmedali', 16, 55, 'تاکہ جو نعمتیں ہم نےانہیں دی تھیں ان کی ناشکری کریں خیر نفع اٹھالو آ گے چل کر معلوم کر لو گے'),
  ('ur.ahmedali', 16, 56, 'اور جنہیں وہ جانتے بھی نہیں ان کے لیے ہماری دی ہوئی چیزوں میں سے ایک حصہ مقرر کرتے ہیں الله کی قسم البتہ تم سے ان بہتانوں کی ضرور باز پرس ہوگی'),
  ('ur.ahmedali', 16, 57, 'اور الله کے لیے بیٹیاں ٹھیراتے ہیں وہ اس سے پاک ہے اور اپنے لیے جو دل چاہتا ہے'),
  ('ur.ahmedali', 16, 58, 'اور جب ان میں سے کسی کی بیٹی کی خوشخبری دی جائے اس کا منہ سیاہ ہو جاتا ہے اور وہ غمگین ہوتا ہے'),
  ('ur.ahmedali', 16, 59, 'اس خوشخبری کی برائی باعث لوگوں سے چھپتا پھرتا ہے آیا اسے ذلت قبول کر کے رہنے دے یااس کو مٹی میں دفن کر دے دیکھو کیا ہی برا فیصلہ کرتے ہیں'),
  ('ur.ahmedali', 16, 60, 'جو آخرت کو نہیں مانتے ان کی بری مثال ہے اور الله کی شان سب سے بلند ہے اور وہی زبردست حکمت والا ہے'),
  ('ur.ahmedali', 16, 61, 'اور اگر الله لوگوں کوانکی بے انصافی پر پکڑے تو زمین پر کسی جاندار کو نہ چھوڑے لیکن ایک مدت مقرر تک انہیں مہلت دیتا ہے پھر جب ان کا وقت آتا ہے تو نہ ایک گھڑی پیچھے ہٹ سکتے ہیں اورنہ آگے بڑھ سکتے ہیں'),
  ('ur.ahmedali', 16, 62, 'اور اللهکے لیے وہ چیزیں تجویز کرتے ہیں جنہیں آپ بھی پسند نہیں کرتے اورزبان سے جھوٹے دعوے کرتے ہیں کہ آخرت کی بھلائی انہیں کے لیے ہے اسمیں شک نہیں کہ ان کے لیے آگ ہے اور بے شک وہ سب سے پہلے دوزخ میں بھیجے جائیں گے'),
  ('ur.ahmedali', 16, 63, 'الله کی قسم ہے! ہم نے تجھ سے پہلے بھی قوموں میں رسول بھیجے تھے پھر شیطان نے لوگوں کو ان کی بداعمالیاں اچھی کر دکھائیں سو آج بھی ان کا وہی دوست ہے اور ان کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 16, 64, 'اور ہم نے اسی لیے تجھ پر کتاب اتاری ہے کہ تو انہیں وہ چیز کھول کر سنا دے جس میں وہ جھگڑ رہے ہیں اور ایمانداروں کے لیے ہدایت اور رحمت بھی ہے'),
  ('ur.ahmedali', 16, 65, 'اور الله نے آسمان سے پانی اتارا پھراس سے مردہ زمین کو زندہ کر دیا اس میں ان لوگو ں کے لیے نشانی ہے جو سنتے ہیں'),
  ('ur.ahmedali', 16, 66, 'اوربے شک تمہارے لیے چارپایوں میں سوچنے کی جگہ ہے ہم نےان کے جسم سے خون او رگوبر کے درمیان خالص دودھ پیدا کردیتے ہیں جو پینے والوں کے لیے خوشگوار ہے'),
  ('ur.ahmedali', 16, 67, 'اور کھجور اور انگور کے پھلوں سے نشہ اور اچھی غذا بھی بناتے ہو اس میں لوگوں کے لیے نشانی ہے جو سمجھتے ہیں'),
  ('ur.ahmedali', 16, 68, 'اور تیرے رب نے شہد کی مکھی کو حکم دیا کہ پہاڑوں میں اور درختوں میں اور ان چھتوں میں گھر بنائے جو اس کے لیے بناتے ہیں'),
  ('ur.ahmedali', 16, 69, 'پھر ہر قسم کے میوں سے کھا پھر اپنے رب کی تجویز کردہ آسان راہوں پر چل ان کے پیٹ سے پینے کی چیز نکلتی ہے جس کے رنگ مختلف ہیں اس میں لوگوں کے لیے شفا ہے بے شک اس میں ان لوگو ں کے لیے نشانی ہے جو سوچتے ہیں'),
  ('ur.ahmedali', 16, 70, 'اور الله نے تمہیں پیدا کیا پھر وہی تمہیں مارتاہے اور کوئی تم میں سے نکمی عمر تک پہنچایا جاتا ہے جو سمجھ دار ہونے کے بعد نادان ہو جاتا ہے بےشک الله جاننے والا قدرت والا ہے'),
  ('ur.ahmedali', 16, 71, 'اور الله نے تم میں سے بعض کو بعض پر روزی میں فضیلت دی پھر جنہیں فضیلت دی گئی وہ اپنے حصہ کا مال اپنے غلاموں کو دینےو الے نہیں کہ وہ اس میں برابر ہو جائیں پھر کیا الله کی نعمت کا انکار کرتے ہیں'),
  ('ur.ahmedali', 16, 72, 'اور الله نے تمہارے واسطے تمہاری ہی قسم سے عورتیں پیدا کیں اور تمہیں تمہاری عورتوں سے بیٹے اور پوتے دیئے اور تمہیں کھانے کے لیے اچھی چیزیں دیں پھرکیا جھوٹی باتیں تو مان لیتے ہیں اور الله کی نعمتوں کا انکار کرتے ہیں'),
  ('ur.ahmedali', 16, 73, 'اور الله کے سوا ان کی عبادت کرتے ہیں جو آسمانوں ارو زمین سے انہیں رزق پہنچانے میں کچھ بھی اختیارنہیں رکھتے اور نہ رکھ سکتے ہیں'),
  ('ur.ahmedali', 16, 74, 'پس الله کے لئے مثالیں نہ گھڑو بے شک الله جانتا ہے اور تم نہیں جانتے'),
  ('ur.ahmedali', 16, 75, 'الله ایک مثال بیان فرماتا ہے ایک غلام ہے کسی دوسرے کی ملک میں جو کسی چیز کا اختیارنہیں رکھتا اور ایک دوسرا آدمی ہے جسے ہم نے اچھی روزی دے رکھی ہے اور وہ ظاہر اور پوشیدہ اسے خرچ کرتا ہے کیا دونوں برابر ہیں سب تعریف الله کے لیے ہے مگر اکثر ان میں سے نہیں جانتے'),
  ('ur.ahmedali', 16, 76, 'اور الله ایک او رمثال دو آدمیوں کی بیان فرماتا ہے ایک ان میں سے گونگا ہے کچھ بھی نہیں کر سکتااور اپنے آقا پر ایک بوجھ ہے جہاں کہیں اسے بھیجے اس سے کوئی خوبی کی بات بن نہ آئے کیا یہ اور وہ برابر ہے جو لوگوں کو انصاف کا حکم دیتا ہے اور وہ خود بھی سیدھے راستے پر قائم ہے'),
  ('ur.ahmedali', 16, 77, 'اور آسمانوں اور زمین کی پوشیدہ باتیں تو الله ہی کو معلوم ہیں اور قیامت کا معاملہ تو ایسا ہے جیسا آنکھ کا جھپکنا یا اس سےبھی قریب تر بے شک الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 16, 78, 'اور الله نے تمہیں تمہاری ماؤں کے پیٹ سے نکالا تم کسی چیز کو نہ جانتے تھے اور تمہیں کان اور آنکھیں اور دل دیئے تاکہ تم شکر کرو'),
  ('ur.ahmedali', 16, 79, 'کیا پرندوں کو نہیں دیکھتے کہ آسمان کی فضا میں تھمے ہوئے ہیں انہیں الله کے سوا کون تھامے ہوئے ہے بے شک اس میں بھی ایمانداروں کے لیے بڑی نشانیاں ہیں'),
  ('ur.ahmedali', 16, 80, 'اور الله نے تمہارے گھروں کو تمہارے لیے آرام کی جگہ بنایا ہے اور تمہارے لیے چارپایوں کی کھالوں سے خیمے بنائے جنہیں تم اپنے سفر اور قیام کے دن ہلکے پاتے ہو اوربھیڑوں کی اون سے اور اونٹوں کی روؤں سے اوربکریوں کے بالوں سے کتنے ہی سامان اور مفید چیزیں وقت مقرر تک کے لیے بنا دیں'),
  ('ur.ahmedali', 16, 81, 'اور الله نے تمہارے لیے اپنی بنائی ہوئی چیزوں کے سائےبنا دیئے اور تمہارے لیے پہاڑوں میں چھپنے کی جگہیں بنا دیں اور تمہارے لیے کرتے بنا دیئے جو تمہیں گرمی سے بچاتے ہیں اور زرہیں جو تمہیں لڑائیں میں بچاتی ہیں اسی طرح الله اپنا احسان تم پر پورا کرتا ہے تاکہ تم فرمانبردار ہو جاؤ'),
  ('ur.ahmedali', 16, 82, 'پھربھی اگر نہ مانیں تو تم پر صاف صاف پیغام پہنچا دینا ہی ہے'),
  ('ur.ahmedali', 16, 83, 'وہ الله کی نعمتیں پہچانتے ہیں پھر منکر ہو جاتے ہیں اوراکثر ان میں سے ناشکر گزار ہیں'),
  ('ur.ahmedali', 16, 84, 'اور جس دن ہم ہر قوم میں سے ایک گواہ کھڑا کریں گے پھر نہ کافروں کو اجازت دی جائے گی اورنہ ان کا کوئی عذر قبول کیا جائے گا'),
  ('ur.ahmedali', 16, 85, 'اور جب ظالم عذاب دیکھیں گے پھر نہ ان سے ہلکا کیا جائے گا اورنہ انہیں مہلت دی جائے گی'),
  ('ur.ahmedali', 16, 86, 'اور جب مشرک اپنے شریکوں کو دیکھیں گے تو کہیں گے اے ہمارے رب! یہی ہمارے شریک ہیں جنہیں ہم تیرے سوا پکارتے تھے پھر وہ انہیں جواب دیں گے کہ تم سراسر جھوٹے ہو'),
  ('ur.ahmedali', 16, 87, 'اور وہ اس دن الله کے سامنے سر جھکا دیں گے اور بھول جائیں گے وہ جو جھوٹ بناتے تھے'),
  ('ur.ahmedali', 16, 88, 'جو لوگ منکر ہوئے اور الله کی راہ سے روکتے رہے ہم ان پر عذاب پر عذاب بڑھاتے جائیں گے بسبب اس کے کہ وہ فساد کرتے تھے'),
  ('ur.ahmedali', 16, 89, 'اور جس دن ہر ایک گروہ میں سے ان پر انہیں میں سے ایک گواہ کھڑا کریں گے اور تجھے ان پر گواہ بنائیں گے اور ہم نے تجھ پر ایک ایسی کتاب نازل کی ہے جس میں ہر چیز کا کافی بیان ہے اور وہ مسلمانوں کے لیے ہدات اور رحمت اور خوشخبری ہے'),
  ('ur.ahmedali', 16, 90, 'بے شک الله انصاف کرنے کا اوربھلائی کرنے کا اور رشتہ داروں کو دینے کا حکم کرتا ہے اوربے حیائی اوربری بات اور ظلم سے منع کرتا ہے تمہیں سمجھاتا ہے تاکہ تم سمجھو'),
  ('ur.ahmedali', 16, 91, 'اور الله کا عہد پورا کرو جب آپس میں عہد کرو اور قسموں کو پکاکرنے کے بعد نہ توڑو حالانکہ تم نے الله کو اپنے اوپر گواہ بنا یا ہے بے شک الله جانتا ہے جو تم کرتے ہو'),
  ('ur.ahmedali', 16, 92, 'اور اس عورت جیسے نہ بنو جواپنا سوت محنت کے بعد کاٹ کر توڑ ڈالے کہ تم اپنی قسموں کو آپس میں فساد کا ذریعہ بنانے لگو محض اس لیے کہ ایک گروہ دوسرے گروہ سے بڑھ جائے الله اس میں تمہاری آزمائش کرتا ہے اور جس چیز میں تم اختلاف کرتے ہو الله اسے ضرور قیامت کے دن ظاہر کردے گا'),
  ('ur.ahmedali', 16, 93, 'اور اگر الله چاہتا تو تم سب کو ایک ہی جماعت بنا دیتا اورلیکن وہ جسے چاہتا ہے گمراہی میں پڑا رہنے دیتا ہے اور جسے چاہتاہے ہدایت دیتا ہے اور البتہ تم سے پوچھا جائے گا کہ کیا کرتےتھے'),
  ('ur.ahmedali', 16, 94, 'اور تم اپنی قسموں کو آپس میں فساد کا ذریعہ نہ بناؤ کبھی قدم جمنے کے بعد پھسل نہ جائے پھر تمہیں اس سبب سے کہ تم نے راہِ خدا سے روکا تکلیف اٹھانی پڑے اور تمہیں بڑا عذاب ہو'),
  ('ur.ahmedali', 16, 95, 'اور الله سے عہد کو تھوڑے سے داموں پر نہ بیچو جو کچھ الله کے ہاں ہے وہی تمہارے لیے بہتر ہے اگر تم جانتے ہو'),
  ('ur.ahmedali', 16, 96, 'جو تمہارے پاس ہے ختم ہو جائے گا اور جو الله کے پاس ہے کبھی ختم نہ ہوگا اور ہم صبر کرنے والوں کو ان کے اچھے کاموں کا جو کرتے تھے ضرور بدلہ دیں گے'),
  ('ur.ahmedali', 16, 97, 'جس نے نیک کام کیا مرد ہو یا عورت اور وہ ایمان بھی رکھتا ہے تو ہم اسے ضروراچھی زندگی بسر کرائیں گے اور ان کا حق انہیں بدلےمیں دیں گے انکےاچھے کاموں کے عوض میں جو کرتے تھے'),
  ('ur.ahmedali', 16, 98, 'سو جب تو قرآن پڑھنے لگے تو شیطان مردود سے الله کی پناہ لے'),
  ('ur.ahmedali', 16, 99, 'اس کا زور ان پرنہیں چلتا جو ایمان رکھتے ہیں اور اپنے رب پر بھروسہ کرتے ہیں'),
  ('ur.ahmedali', 16, 100, 'اس کا زور تو انہیں پر ہے جو اسے دوست بناتے ہیں اور جو الله کے ساتھ شریک مانتے ہیں'),
  ('ur.ahmedali', 16, 101, 'اورجب ہم ایک آیت کی جگہ دوسری بدلتے ہیں اور الله خوب جانتا ہے جو اتارتا ہے تو کہتے ہیں کہ تو بنا لاتا ہے یہ بات نہیں لیکن اکثر ان میں سے نہیں سمجھتے'),
  ('ur.ahmedali', 16, 102, 'تو کہہ دے اسےتیرے رب کی طرف سے پاک فرشتے نے سچائی کے ساتھ اتارا ہے تاکہ ایمان والوں کے دل جما دے اور فرمانبرداروں کے لیے ہدایت اور خوشخبری ہے'),
  ('ur.ahmedali', 16, 103, 'اور ہمیں خوب معلوم ہے کہ وہ کہتے ہیں اسے تو ایک آدمی سکھاتا ہے حالانکہ جس کی طرف نسبت کرتے ہیں اس کی زبان عجمی ہے اور یہ صاف عربی زبان ہے'),
  ('ur.ahmedali', 16, 104, 'وہ لوگ جنہیں الله کی باتوں پر یقین نہیں الله بھی انہیں ہدایت نہیں دیتا اور ان کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 16, 105, 'جھوٹ تو وہ لوگ بناتے ہیں جنہیں الله کی باتوں پر یقین نہیں اور وہی لوگ جھوٹے ہیں'),
  ('ur.ahmedali', 16, 106, 'جو کوئی ایمان لانے کے بعد الله سے منکر ہوا مگر وہ جو مجبور کیا گیا ہو اور اس کا دل ایمان پر مطمئن ہو اور لیکن وہ جو دل کھول کر منکر ہوا تو ان پر الله کا غضب ہے اور ان کے لیے بہت بڑا عذاب ہے'),
  ('ur.ahmedali', 16, 107, 'یہ اس لیے کہ انہوں نے دنیا کی زندگی کو آخرت پر محبوب بنایا اور نیز اس لیے کہ الله کافروں کو ہدایت نہیں دیتا'),
  ('ur.ahmedali', 16, 108, 'یہ وہی ہیں کہ الله نے ان کے دلوں پر اورکانوں پر اور آنکھوں پر مہر کر دی اور وہی غافل بھی ہیں'),
  ('ur.ahmedali', 16, 109, 'ضرور وہی لوگ آخرت میں نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 16, 110, 'پھر بے شک تیرا رب ان کے لئے جنہوں نےمصیبت میں پڑنے کے بعد ہجرت کی پھر جہاد کیا اور صبر کیا بے شک تیرارب ان باتو ں کے بعد بحشنے والا مہربان ہے'),
  ('ur.ahmedali', 16, 111, 'ٰجس دن ہر شخص اپنے ہی لیے جھگڑتا ہو آئے گا اور ہر شخص کو اس کے عمل کا پورا بدلہ دیا جائے گا اوران پر کچھ بھی ظلم نہ ہوگا'),
  ('ur.ahmedali', 16, 112, 'اور الله ایک ایسی بستی کی مثال بیان فرماتا ہے جہاں ہر طرح کا امن چین تھا اس کی روزی بافراغت ہر جگہ سے چلی آتی تھی پھر الله کےاحسانوں کی ناشکری کی پھر الله نے ان کے برے کاموں کے سبب سے جو وہ کیا کرتے تھے یہ مزہ چکھایا کہ ان پر فاقہ اور خوف چھا گیا'),
  ('ur.ahmedali', 16, 113, 'اور البتہ ان کے پاس انہیں میں سے رسول بھی آیا مگر انہوں نے اسے جھٹلایا پھر انہیں عذاب نے آ پکڑا ایسے حال میں کہ وہ ظالم تھے'),
  ('ur.ahmedali', 16, 114, 'پھر تمہیں جو الله نے حلال طیب روزی دی ہے کھاؤ اور الله کے احسان کا شکر کرو اگر تم صرف اسی کو پوجتے ہو'),
  ('ur.ahmedali', 16, 115, 'تم پر صرف مردار اور خون اور سور کا گوشت حرام کیا ہے اوروہ چیز بھی جو الله کے سوا کسی اور کے نام سے پکاری گئی ہو پھر جوبھوک کے مارے بیتاب ہو جائے نہ وہ باغی ہو اورنہ حد سے گزرنے والا توالله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 16, 116, 'اور اپنی زبانوں سے جھوٹ بنا کر نہ کہو کہ یہ حلا ل ہے اوریہ حرا م ہے تاکہ الله پر بہتان باندھو بے شک جو الله پر بہتان باندھتے ہیں انکا بھلانہ ہوگا'),
  ('ur.ahmedali', 16, 117, 'تھوڑا سا فائدہ اٹھا لیں اوران کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 16, 118, 'اورجو لوگ یہودی ہیں ہم نے ان پر حرا م کی جو تجھے پہلے سنا چکے ہیں اورہم نے ان پر ظلم نہیں کیا لیکن وہ اپنے اوپر آپ ظلم کرتے تھے'),
  ('ur.ahmedali', 16, 119, 'پھر تیرا رب ان کے لیے جو جہالت سے برے کام کرتے رہے پھر اس کے بعد انہوں نے توبہ کر لی اور سدھر گئے بے شک تیرا رب اس کے بعد البتہ بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 16, 120, 'بے شک ابراہیم ایک پوری امت تھا الله کا فرمانبردار تمام راہوں سے ہٹا ہوا اور مشرکوں میں سے نہ تھا'),
  ('ur.ahmedali', 16, 121, 'اس کی نعمتوں کا شکر کرنے والا اسے الله نے چن لیا اور اسے سیدھی راہ پر چلایا'),
  ('ur.ahmedali', 16, 122, 'اور ہم نے اسے دنیا میں بھی خوبی دی تھی اور وہ آخرت میں بھی اچھے لوگو ں میں ہو گا'),
  ('ur.ahmedali', 16, 123, 'پھر ہم نے تیرے پاس وحی بھیجی کہ تمام راہوں سے ہٹنے والے ابراہیم کے دین پر چل اور وہ مشرکوں میں سے نہ تھا'),
  ('ur.ahmedali', 16, 124, 'ہفتہ کا دن انہی پر مقرر کیا گیا تھا جو اس میں اختلاف کرتےتھے او رتیرا رب ان میں قیامت کےدن فیصلہ کرے گا جس میں وہ اختلاف کرتے تھے'),
  ('ur.ahmedali', 16, 125, 'اپنے رب کے راستے کی طرف دانشمندی اور عمدہ نصیحت سے بلا اور ان سے پسندیدہ طریقہ سے بحث کر بے شک تیرا رب خوب جانتا ہے کہ کون اس کے راستہ سے بھٹکا ہوا ہے اور ہدایت یافتہ کو بھی خوب جانتا ہے'),
  ('ur.ahmedali', 16, 126, 'اور اگر بدلہ لو تو اتنا بدلہ لو جتنی تمہیں تکلیف پہنچائی گئی ہے اور اگر صبر کرو تو یہ صبر کرنے والوں کے لیے بہتر ہے'),
  ('ur.ahmedali', 16, 127, 'اورصبر کر اور تیرا صبر کرنا الله ہی کی توفیق سے ہے اور ان پر غم نہ کھا اور ان کے مکروں سے تنگ دل نہ ہو'),
  ('ur.ahmedali', 16, 128, 'بے شک الله ان کے ساتھ ہے جو پرہیزگار ہیں اور جو نیکی کرتے ہیں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 16, 1, 'Allah\'ın buyruğu gelecektir; acele gelmesini istemeyin, Allah, ortak koştukları şeylerden münezzehtir, yücedir.'),
  ('tr.diyanet', 16, 2, 'Allah kullarından dilediğine buyruğunu bildirmek için meleklerini vahiyle indirerek şöyle der: "İnsanları uyarın ki, Benden başka tanrı yoktur. Benden sakının."'),
  ('tr.diyanet', 16, 3, 'Gökleri ve yeri gereğince yaratmıştır. Onların eş koştukları şeylerden yücedir.'),
  ('tr.diyanet', 16, 4, 'İnsanı nutfeden yaratmıştır. Öyleyken o nasıl da açıkça karşı koymaktadır!'),
  ('tr.diyanet', 16, 5, 'Hayvanları da yaratmıştır. Onlarda sizi ısıtacak şeyler ve birçok faydalar vardır. Onların etlerini de yersiniz.'),
  ('tr.diyanet', 16, 6, 'Onları getirirken de, gönderirken de zevk alırsınız.'),
  ('tr.diyanet', 16, 7, 'Kendi kendinize zor varacağınız memleketlere, yüklerinizi taşırlar. Doğrusu Rabbiniz şefkatlidir, merhametlidir.'),
  ('tr.diyanet', 16, 8, 'Sizin için atları, katırları ve merkebleri binek ve süs hayvanı olarak yaratmıştır. Bilmediğiniz daha nice şeyleri de yaratır.'),
  ('tr.diyanet', 16, 9, 'Yolun eğri olanı da vardır. Allah dileseydi hepinizi doğru yola iletirdi.'),
  ('tr.diyanet', 16, 10, 'Yukarıdan size su indiren O\'dur. Ondan içersiniz; hayvanları otlattığınız bitkiler de onunla biter.'),
  ('tr.diyanet', 16, 11, 'Allah onunla size ekinler, zeytin ve hurma ağaçları, üzümler ve her türlü ürünü yetiştirir. Düşünen kimseler için bunda ders vardır.'),
  ('tr.diyanet', 16, 12, 'Geceyi gündüzü, güneşi ayı sizin istifadenize vermiştir. Yıldızlar da O\'nun buyruğuna boyun eğmiştir. Bunlarda, akleden kimseler için dersler vardır.'),
  ('tr.diyanet', 16, 13, 'Yeryüzünde rengarenk şeyleri de sizin için yaratmıştır. Bunda, öğüt alan kimseler için ibret vardır.'),
  ('tr.diyanet', 16, 14, 'Taze et yemeniz, takındığınız süsleri edinmeniz ve Allah\'ın bol nimetinden faydalanmanız için denize -ki gemilerin onu yara yara gittiğini görürsün- boyun eğdiren de O\'dur. Artık belki şükredersiniz.'),
  ('tr.diyanet', 16, 15, 'Yeryüzünde, sarsılmayasınız diye, sabit dağlar, nehirler ve belki yolunuzu bulursunuz diye yollar ve işaretler meydana getirmiştir. Onlar yıldızla da yollarını bulurlar.'),
  ('tr.diyanet', 16, 16, 'Yeryüzünde, sarsılmayasınız diye, sabit dağlar, nehirler ve belki yolunuzu bulursunuz diye yollar ve işaretler meydana getirmiştir. Onlar yıldızla da yollarını bulurlar.'),
  ('tr.diyanet', 16, 17, 'Hiç yaratan yaratamayana benzer mi? İbret almaz mısınız?'),
  ('tr.diyanet', 16, 18, 'Allah\'ın verdiği nimetleri sayacak olsanız bitiremezsiniz; doğrusu Allah bağışlar, merhamet eder.'),
  ('tr.diyanet', 16, 19, 'Allah, gizlediklerinizi de, açığa vurduklarınızı da bilir.'),
  ('tr.diyanet', 16, 20, 'Allah\'ı bırakıp taptıkları şeyler, hiçbir şey yaratmazlar; esasen kendileri yaratıktır.'),
  ('tr.diyanet', 16, 21, 'Onlar cansız, ölüdürler. Ne zaman dirileceklerini de bilemezler.'),
  ('tr.diyanet', 16, 22, 'Tanrınız tek bir Tanrıdır. Ahirete inanmayanların kalbleri bunu inkar eder; onlar büyüklük taslarlar.'),
  ('tr.diyanet', 16, 23, 'Onların gizlediklerini de, açığa vurduklarını da Allah\'ın bildiğinde şüphe yoktur. O, büyüklük taslayanları sevmez.'),
  ('tr.diyanet', 16, 24, 'Onlara: "Rabbiniz ne indirdi?" diye sorulsa: "öncekilerin masalları" derler.'),
  ('tr.diyanet', 16, 25, 'Böylece kıyamet günü kendi günahlarını tam olarak, bilmeden saptırdıkları kimselerin günahlarını kısmen yüklenirler. Dikkat edin, yüklendikleri yük ne kötüdür!'),
  ('tr.diyanet', 16, 26, 'Onlardan öncekiler düzen kurmuşlardı. Bunun üzerine Allah, binalarının temelini çökertti de tavanları başlarına yıkıldı. Azap, onlara farketmedikleri yerden geldi.'),
  ('tr.diyanet', 16, 27, 'Sonra kıyamet günü onları rezil eder ve: "Haklarında tartıştığınız Benim ortaklarım nerede?" der. İlim sahibleri şöyle derler: "Doğrusu bugün inkarcılara rezillik ve iğrençlik vardır."'),
  ('tr.diyanet', 16, 28, 'Melekler kendilerine yazık etmiş kimselerin canlarını alırken: "Biz hiçbir kötülük yapmıyorduk" diyerek teslim olurlar. Hayır; öyle değil; doğrusu Allah onların yaptıklarını bilmektedir.'),
  ('tr.diyanet', 16, 29, 'Temelli kalacağınız cehennemin kapılarından girin. Büyüklenenlerin durağı ne kötüdür!'),
  ('tr.diyanet', 16, 30, 'Sakınan kimselere: "Rabbiniz ne indirdi?" denince, "İyilik" derler. Bu dünyada iyi davrananlara iyilik vardır. Ahiret yurdu ise daha iyidir. Sakınanların yurdu ne güzeldir!'),
  ('tr.diyanet', 16, 31, 'İçlerinden ırmaklar akan Adn cennetlerine girerler. Orada, diledikleri kendilerine verilir. Allah sakınanları böylece mükafatlandırır.'),
  ('tr.diyanet', 16, 32, 'Melekler onların canını temizlenmiş olarak alırken: "Selam size; yaptıklarınıza karşılık haydi cennete girin" derler.'),
  ('tr.diyanet', 16, 33, 'Onlar kendilerine yalnız meleklerin veya senin Rabbinin buyruğunun gelmesini mi bekliyorlar? Onlardan öncekiler de böyle yapmışlardı. Allah onlara zulmetmemişti, ama onlar kendilerine yazık ediyorlardı.'),
  ('tr.diyanet', 16, 34, 'Bu yüzden, işledikleri kötülüklere uğradılar ve alay ettikleri şey onları kuşattı.'),
  ('tr.diyanet', 16, 35, 'Allah\'a eş koşanlar: "Allah dileseydi O\'ndan başka hiçbir şeye ne biz ve ne de babalarımız tapardı. O\'nun buyruğu olmaksızın hiçbir şeyi haram kılmazdık" dediler. Kendilerinden öncekiler de böyle yapmıştı. Peygamberlere apaçık tebliğden başka ne vazife düşer?'),
  ('tr.diyanet', 16, 36, 'And olsun ki, her ümmete: "Allah\'a kulluk edin, azdırıcılardan kaçının" diyen peygamber göndermişizdir. Allah içlerinden kimini doğru yola eriştirdi, kimi de sapıklığı haketti. Yeryüzünde gezin; peygamberleri yalanlayanların sonlarının nasıl olduğunugörün.'),
  ('tr.diyanet', 16, 37, 'Onların doğru yolda olmalarına ne kadar özensen, yine de Allah, saptırdığını doğru yola iletmez. Onların yardımcıları da olmaz.'),
  ('tr.diyanet', 16, 38, 'Ölen kimseyi Allah\'ın diriltmeyeceği üzerine bütün güçleriyle Allah\'a yemin ederler. Hayır; öyle değil, ayrılığa düştükleri şeyi onlara açıklamayı, inkar edenlerin kendilerinin yalancı olduklarını bileceklerini, Allah gerçekten vadetmiştir, fakat insanların çoğu bilmezler.'),
  ('tr.diyanet', 16, 39, 'Ölen kimseyi Allah\'ın diriltmeyeceği üzerine bütün güçleriyle Allah\'a yemin ederler. Hayır; öyle değil, ayrılığa düştükleri şeyi onlara açıklamayı, inkar edenlerin kendilerinin yalancı olduklarını bileceklerini, Allah gerçekten vadetmiştir, fakat insanların çoğu bilmezler.'),
  ('tr.diyanet', 16, 40, 'Bir şeyin olmasını istediğimiz zaman sözümüz sadece ona "Ol" dememizdir ve hemen olur.'),
  ('tr.diyanet', 16, 41, 'Haksızlığa uğratıldıktan sonra, Allah yolunda hicret eden kimseleri, and olsun ki, dünyada güzel bir yerde yerleştiririz. Ahiret ecri ise daha büyüktür, keşki bilseler!'),
  ('tr.diyanet', 16, 42, 'Onlar sabreden ve yalnız Rablerine güvenen kimselerdir.'),
  ('tr.diyanet', 16, 43, 'Doğrusu senden önce de kendilerine kitablar ve belgelerle vahyettiğimiz bir takım adamlar gönderdik. Bilmiyorsanız kitablılara sorun. Sana da, insanlara gönderileni açıklayasın diye Kuran\'ı indirdik. Belki düşünürler.'),
  ('tr.diyanet', 16, 44, 'Doğrusu senden önce de kendilerine kitablar ve belgelerle vahyettiğimiz bir takım adamlar gönderdik. Bilmiyorsanız kitablılara sorun. Sana da, insanlara gönderileni açıklayasın diye Kuran\'ı indirdik. Belki düşünürler.'),
  ('tr.diyanet', 16, 45, 'Kötü işler düzenleyenler Allah\'ın kendilerini yere batırmasından yahut farketmedikleri bir yerden onlara azabın gelmesinden güvende midirler?'),
  ('tr.diyanet', 16, 46, 'Veya hareket halindelerken -ki Allah\'ı aciz bırakamazlar- ya da yok olmak endişesindeyken onlara azabın gelmesinden güvende midirler? Doğrusu Rabbin şefkatlidir, merhametlidir.'),
  ('tr.diyanet', 16, 47, 'Veya hareket halindelerken -ki Allah\'ı aciz bırakamazlar- ya da yok olmak endişesindeyken onlara azabın gelmesinden güvende midirler? Doğrusu Rabbin şefkatlidir, merhametlidir.'),
  ('tr.diyanet', 16, 48, 'Allah\'ın yarattığı şeylerin, gölgeleri sağa sola vurarak, Allah\'a boyun eğerek secde etmekte olduklarını görmüyorlar mı?'),
  ('tr.diyanet', 16, 49, 'Göklerde ve yerde bulunan her canlı ve melekler, büyüklük taslamaksızın Allah\'a secde ederler.'),
  ('tr.diyanet', 16, 50, 'Üstün olan Rablerinden korkarlar ve emrolundukları şeyleri yaparlar.'),
  ('tr.diyanet', 16, 51, 'Allah, "İki tanrı edinmeyin, O ancak bir tek Tanrı\'dır. Yalnız Ben\'den korkun" dedi.'),
  ('tr.diyanet', 16, 52, 'Göklerde ve yerde olan O\'nundur. Kulluk da daima O\'nadır. Allah\'tan başkasından mı sakınıyorsunuz?'),
  ('tr.diyanet', 16, 53, 'Size gelen her nimet Allah\'tandır. Sonra, bir sıkıntıya uğradığınızda yalnız O\'na sığınırsınız.'),
  ('tr.diyanet', 16, 54, 'Sıkıntılarınızı giderince de, içinizden bazıları kendilerine verdiğimize nankörlük ederek Rablerine eş koşarlar. Geçinin bakalım, yakında öğreneceksiniz.'),
  ('tr.diyanet', 16, 55, 'Sıkıntılarınızı giderince de, içinizden bazıları kendilerine verdiğimize nankörlük ederek Rablerine eş koşarlar. Geçinin bakalım, yakında öğreneceksiniz.'),
  ('tr.diyanet', 16, 56, 'Kendilerine verdiğimiz rızıktan, onların ne olduğunu bilmeyen putlara pay ayırırlar. Allah\'a and olsun ki, uydurup durduğunuz şeylerden elbette sorguya çekileceksiniz.'),
  ('tr.diyanet', 16, 57, 'Beğendikleri erkek çocukları kendilerine; kızları da Allah\'a malediyorlar. O bundan münezzehtir.'),
  ('tr.diyanet', 16, 58, 'Aralarından birine bir kızı olduğu müjdelendiği zaman içi gamla dolarak yüzü simsiyah kesilir.'),
  ('tr.diyanet', 16, 59, 'Kendisine verilen kötü müjde yüzünden, halktan gizlenmeye çalışır; onu utana utana tutsun mu, yoksa toprağa mı gömsün? Ne kötü hükmediyorlar!'),
  ('tr.diyanet', 16, 60, 'Ahirete inanmayanlar kötülük misalidirler. En üstün misali ise Allah verir. O Güçlü\'dür, Hakim\'dir.'),
  ('tr.diyanet', 16, 61, 'Allah insanları haksızlıklarından ötürü yakalayacak olsaydı, yeryüzünde canlı bırakmazdı. Fakat onları belirli bir süreye kadar erteler. Süreleri dolunca onu ne bir saat geciktirebilirler ne de öne alabilirler.'),
  ('tr.diyanet', 16, 62, 'Beğenmediklerini Allah\'a malederler. Dilleri, güzel şeylerin kendilerine ait olduğunu yalan yere söyler durur. Cehennemin onların olduğunda ve önceden oraya gideceklerinde şüphe yoktur.'),
  ('tr.diyanet', 16, 63, 'Allah\'a and olsun ki, senden önceki ümmetlere peygamberler gönderdik. Şeytan yaptıklarını onlara hep güzel gösterdi. Bugün de dostları odur. Onlara can yakıcı azap vardır.'),
  ('tr.diyanet', 16, 64, 'Sana Kitap\'ı, ayrılığa düştükleri şeyleri onlara açıklaman için, inanan kimselere de doğru yol rehberi ve rahmet olarak indirdik.'),
  ('tr.diyanet', 16, 65, 'Allah gökten su indirir ve ölümünden sonra yeryüzünü diriltir. Kulak veren kimseler için bunda ibret vardır.'),
  ('tr.diyanet', 16, 66, 'Hayvanlarda da size ibretler vardır. Bağırsaklarındakiler ile kan arasından, içenlere halis ve içimi kolay süt içiririz.'),
  ('tr.diyanet', 16, 67, 'Hurma ağaçlarının meyvelerinden ve üzümlerden şerbet, şıra (içecek) ve güzel rızık elde edersiniz. Düşünen millet için bunda ibret vardır.'),
  ('tr.diyanet', 16, 68, 'Rabbin bal arısına: "Dağlarda, ağaçlarda ve hazırlanmış kovanlarda yuva edin; sonra her çeşit üründen ye; sonra da Rabbinin işlemen için gösterdiği yollardan yürü" diye öğretti. Karınlarından insanlara şifa olan çeşitli renklerde bal çıkar. Düşünen bir millet için bunda ibret vardır.'),
  ('tr.diyanet', 16, 69, 'Rabbin bal arısına: "Dağlarda, ağaçlarda ve hazırlanmış kovanlarda yuva edin; sonra her çeşit üründen ye; sonra da Rabbinin işlemen için gösterdiği yollardan yürü" diye öğretti. Karınlarından insanlara şifa olan çeşitli renklerde bal çıkar. Düşünen bir millet için bunda ibret vardır.'),
  ('tr.diyanet', 16, 70, 'Allah sizi yaratmıştır, sonra öldürecektir, içinizden bir kısmı da ömrünün en fena zamanına ulaştırılır ki, bilirken bilmez olurlar. Doğrusu Allah bilendir, her şeye Kadir\'dir.'),
  ('tr.diyanet', 16, 71, 'Allah rızıkda kiminizi diğerlerine üstün tutmuştur. Üstün kılınanlar, emirleri altında bulunanların rızıklarını vermezler. Oysa rızıkta hepsi eşittir. Allah\'ın nimetini bile bile inkar mı ediyorlar?'),
  ('tr.diyanet', 16, 72, 'Allah size kendinizden eşler var eder. Eşlerinizden de oğullar ve torunlar var eder. Size temiz şeylerden rızık verir. Öyleyken batıla inanıyorlar ve Allah\'ın nimetini inkar mı ediyorlar?'),
  ('tr.diyanet', 16, 73, 'Allah\'ı bırakıp, göklerden ve yerden kendilerine verecek rızıkları olmayan ve vermeye güç yetiremeyen şeylere mi tapıyorlar?'),
  ('tr.diyanet', 16, 74, 'Allah\'a benzerler koşmaya kalkmayın. Şüphesiz Allah bilir, siz bilmezsiniz.'),
  ('tr.diyanet', 16, 75, 'Allah, hiçbir şeye gücü yetmeyen ve başkasının malı olan bir köle ile, kendisine verdiğimiz güzel nimetlerden gizlice ve açıkça sarfeden kimseyi misal gösterir: Hiç bunlar eşit olur mu? Övülmeğe layık olan Allah\'tır, fakat çoğu bilmezler.'),
  ('tr.diyanet', 16, 76, 'Allah iki adamı misal veriyor: Biri hiçbir şeye gücü yetmeyen bir dilsiz ki efendisine yüktür, nereye gönderse bir hayır çıkmaz; bu, doğru yolda olan, adaletle emreden kimse ile bir olabilir mi?'),
  ('tr.diyanet', 16, 77, 'Göklerin ve yerin gaybı Allah\'a aittir, kıyamet saatinin kopuşu bir göz kırpması kadar veya daha çabuk bir zaman içinde olur. Şüphesiz Allah her şeye Kadir\'dir.'),
  ('tr.diyanet', 16, 78, 'Allah sizi annelerinizin karnından bir şey bilmez halde çıkarmıştır. Belki şükredersiniz diye size kulak, göz ve kalp vermiştir.'),
  ('tr.diyanet', 16, 79, 'Göğün boşluğunda Allah\'ın buyruğuna boyun eğerek uçan kuşlara bakmıyorlar mı? Onları Allah\'tan başka tutan kimse yoktur. İnanan millet için bunda dersler vardır.'),
  ('tr.diyanet', 16, 80, 'Allah size evlerinizi dinlenme yeri kıldı. Hayvanların derilerinden, yolculukta ve ikamet zamanlarınızda kolayca taşıyacağınız evler; yün, tüy ve kıllarından bir süre kullanacağınız giyimlikler ve geçimlikler var etmiştir.'),
  ('tr.diyanet', 16, 81, 'Allah yarattıklarından size gölgeler yapmış; dağlarda sığınacağınız barınaklar var etmiş, sizi sıcaktan koruyacak elbiseler, harpte sizi koruyacak zırhlar vermiştir. Size olan nimetini müslüman olasınız diye işte bu şekilde tamamlamaktadır.'),
  ('tr.diyanet', 16, 82, 'Eğer yüz çevirirlerse, sana düşenin sadece açıkça tebliğ olduğunu bil.'),
  ('tr.diyanet', 16, 83, 'Allah\'ın nimetini hem bilirler hem de inkar ederler. Zaten çoğu kafir kimselerdir.'),
  ('tr.diyanet', 16, 84, 'Kıyamet günü her ümmetten bir şahit getiririz; inkar edenlere itiraz için izin de verilmez, onların özürleri de dinlenmez.'),
  ('tr.diyanet', 16, 85, 'Zulmedenler, azap görürlerken azabları hafifletilmez de geciktirilmez de.'),
  ('tr.diyanet', 16, 86, 'Allah\'a ortak koşanlar, koştukları ortakları gördüklerinde: "Rabbimiz! Seni bırakıp yalvardığımız ortaklarımız bunlardır" derler. Koştukları ortaklar: "Doğrusu siz yalancısınız" diye söz atarlar.'),
  ('tr.diyanet', 16, 87, 'Puta tapanlar o gün Allah\'ın hükmüne teslim olurlar; uydurdukları şeyler onlardan uzaklaşırlar.'),
  ('tr.diyanet', 16, 88, 'İnkar eden, Allah\'ın yolundan alıkoyanlara, bozgunculuklarına karşılık azap üstüne azap veririz.'),
  ('tr.diyanet', 16, 89, 'O gün her ümmetten bir kişiyi onlara şahit tutarız. Seni de ümmetine şahit getiririz. Sana her şeyi açıklayan ve Müslümanlara doğruyu gösteren bir rehber, rahmet ve müjde olarak Kuran\'ı indirdik.'),
  ('tr.diyanet', 16, 90, 'Allah şüphesiz adaleti, iyilik yapmayı, yakınlara bakmayı emreder; hayasızlığı, fenalığı ve haddi aşmayı yasak eder. Tutasınız diye size öğüt verir.'),
  ('tr.diyanet', 16, 91, 'Ahitleştiğiniz zaman Allah\'ın ahdini yerine getirin. Allah\'ı kendinize kefil kılarak sağlama bağladığınız yeminleri bozmayın. Allah yaptıklarınızı şüphesiz bilir.'),
  ('tr.diyanet', 16, 92, 'Bir ümmetin diğerinden daha çok olmasından ötürü, aranızdaki yeminleri bozarak, ipliğini iyice eğirip katladıktan sonra bozan kadın gibi olmayın. Allah onunla sizi dener. And olsun ki, ayrılığa düştüğünüz şeyleri size kıyamet günü açıklar.'),
  ('tr.diyanet', 16, 93, 'Allah dileseydi sizi tek bir ümmet yapardı. Ama O, istediğini saptırır, istediğini doğru yola eriştirir. İşlediklerinizden, and olsun ki, sorumlu tutulacaksınız.'),
  ('tr.diyanet', 16, 94, 'Birbirinizi aldatmak için yemin etmeyin ki, bu yüzden sağlamca yere basmakta olan ayak sürçebilir; Allah yolundan alıkoymanıza karşılık kötü bir azap tadarsınız ve (ahirette de) büyük bir azaba uğrarsınız.'),
  ('tr.diyanet', 16, 95, 'Allah\'ın ahdini hiçbir değere değişmeyin. Eğer bilirseniz, Allah katında olan sizin için daha iyidir.'),
  ('tr.diyanet', 16, 96, 'Sizde olanlar tükenir ama, Allah katında olanlar sonsuzdur, tükenmez. Sabredenlere ecirlerini, yaptıklarından daha güzeli ile ödeyeceğiz.'),
  ('tr.diyanet', 16, 97, 'Kadın, erkek, inanmış olarak kim iyi iş işlerse, ona hoş bir hayat yaşatacağız. Ecirlerini yaptıklarından daha güzeli ile ödeyeceğiz.'),
  ('tr.diyanet', 16, 98, 'Kuran okuyacağın zaman, kovulmuş şeytandan Allah\'a sığın.'),
  ('tr.diyanet', 16, 99, 'Doğrusu şeytanın, inananlar ve yalnız Rablerine güvenenler üzerinde bir nüfuzu yoktur.'),
  ('tr.diyanet', 16, 100, 'O\'nun nüfuzu sadece, O\'nu dost edinenler ve Allah\'a ortak koşanlar üzerindedir.'),
  ('tr.diyanet', 16, 101, 'Bir ayetin yerini başka bir ayetle değiştirdiğimizde, ki Allah ne indirdiğini gayet iyi bilir onlar, "Sen sadece uyduruyorsun" derler. Hayır, öyle değildir, ama onların çoğu bunu bilmezler.'),
  ('tr.diyanet', 16, 102, 'De ki: "Kuran\'ı; Ruhul Kudüs (Cebrail) Rabbinin katından, inananların inançlarını pekiştirmek, Müslümanlara doğruluk rehberi ve müjde olmak üzere gerçekle indirmiştir."'),
  ('tr.diyanet', 16, 103, 'And olsun ki: "Ona elbette bir insan öğretiyor" dediklerini biliyoruz. Kast ettikleri kimsenin dili yabancıdır, Kuran ise fasih Arapça\'dır.'),
  ('tr.diyanet', 16, 104, 'Allah\'ın ayetlerine inanmayanları Allah doğru yola eriştirmez. Onlara can yakıcı azap vardır.'),
  ('tr.diyanet', 16, 105, 'Yalan uyduranlar ancak Allah\'ın ayetlerine inanmayanlardır. Yalancılar işte onlardır.'),
  ('tr.diyanet', 16, 106, 'Gönlü imanla dolu olduğu halde, zor altında olan kimse müstesna, inandıktan sonra Allah\'ı inkar edip, gönlünü kafirliğe açanlara Allah katından bir gazap vardır; büyük azap da onlar içindir.'),
  ('tr.diyanet', 16, 107, 'Bu, dünya hayatını ahirete tercih etmelerinden ve Allah\'ın da, inkarcı milleti doğru yola eriştirmemesinden ötürü böyledir.'),
  ('tr.diyanet', 16, 108, 'İşte Allah\'ın kalblerini, kulaklarını ve gözlerini mühürlediği kimseler bunlardır. Gafiller de işte bunlardır.'),
  ('tr.diyanet', 16, 109, 'Ahirette zarara uğrayacakların bunlar olduğunda şüphe yoktur.'),
  ('tr.diyanet', 16, 110, 'Rabbin, türlü eziyete uğratıldıktan sonra hicret eden, sonra Allah uğrunda savaşan ve sabreden kimselerden yanadır. Rabbin şüphesiz bundan sonra da bağışlar ve merhamet eder.'),
  ('tr.diyanet', 16, 111, 'O gün, herkesin kendi derdine düşüp çabalayacağı ve herkesin işlediğinin haksızlığa uğratılmadan kendisine ödeneceği bir gündür.'),
  ('tr.diyanet', 16, 112, 'Allah size güven ve huzur içinde olan bir kasabayı misal verir: Her taraftan oraya bolca rızık geliyordu. Ama Allah\'ın nimetlerine nankörlük ettiler; bu yüzden Allah onlara yaptıklarına karşılık açlık ve korku belasını tattırdı.'),
  ('tr.diyanet', 16, 113, 'And olsun ki, aralarından kendilerine bir peygamber gelmişti, onu yalancı saydılar. Haksızlık ederlerken azaba uğradılar.'),
  ('tr.diyanet', 16, 114, 'Yalnız Allah\'a kulluk ediyorsanız, Allah\'ın size helal ve temiz olarak verdiği rızıklardan yiyin, O\'nun nimetine şükredin.'),
  ('tr.diyanet', 16, 115, 'Allah size ancak leşi, kanı, domuz etini ve Allah\'tan başkasının adına kesilenleri haram etmiştir. Darda kalan, aşırı gitmemek ve başkasının hakkına el uzatmamak şartiyle bunun dışındadır. Allah şüphesiz bağışlar, merhamet eder.'),
  ('tr.diyanet', 16, 116, 'Diliniz yalana alışmış olduğu için, "şu haram, bu helaldir" demeyin, zira Allah\'a karşı yalan uydurmuş olursunuz. Allah\'a karşı yalan uyduranlar ise, saadete şüphesiz erişemezler.'),
  ('tr.diyanet', 16, 117, 'Az bir geçim ama ardından can yakıcı bir azap onlaradır.'),
  ('tr.diyanet', 16, 118, 'Sana anlattıklarımızı, daha önce, yahudi olanlara da haram kılmıştık; biz onlara zulmetmedik, onlar kendilerine zulmediyorlardı.'),
  ('tr.diyanet', 16, 119, 'Sonra doğrusu Rabbin, bilmeyerek kötülük işleyip ardından tevbe eden ve ıslah olanlardan yanadır. Rabbin bundan sonra da bağışlar ve merhamet eder.'),
  ('tr.diyanet', 16, 120, 'İbrahim, şüphesiz Allah\'a boyun eğen ve O\'na yönelen bir önderdi; puta tapanlardan değildi.'),
  ('tr.diyanet', 16, 121, 'Rabbinin nimetlerine şükrederdi; Rabbi de onu seçti ve doğru yola eriştirdi.'),
  ('tr.diyanet', 16, 122, 'Dünyada ona güzellik verdik, ahirette de o mutlaka barışsever iyiler arasında yer alacaktır.'),
  ('tr.diyanet', 16, 123, 'Şimdi sana, "Doğruya yönelen, puta tapanlardan olmayan İbrahim\'in dinine uy" diye vahyettik.'),
  ('tr.diyanet', 16, 124, 'Cumartesi ibadeti, ancak o gün üzerinde çekişenlere farz kılındı. Rabbin, ayrılığa düştükleri şeylerde, kıyamet günü aralarında hükmedecektir.'),
  ('tr.diyanet', 16, 125, 'Rabbinin yoluna, hikmetle, güzel öğütle çağır; onlarla en güzel şekilde tartış; doğrusu Rabbin, kendi yolundan sapanları daha iyi bilir. O, doğru yolda olanları da en iyi bilir.'),
  ('tr.diyanet', 16, 126, 'Eğer ceza vermek isterseniz size yapılanın aynıyla mukabele edin. Sabrederseniz and olsun ki bu, sabredenler için daha iyidir.'),
  ('tr.diyanet', 16, 127, 'Sabret, senin sabrın ancak Allah\'ın yardımıyladır; onlara üzülme, kurdukları düzenlerden de endişe etme.'),
  ('tr.diyanet', 16, 128, 'Allah şüphesiz sakınanlarla ve iyilik yapanlarla beraberdir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 16, 1, 'Telah pasti datangnya ketetapan Allah maka janganlah kamu meminta agar disegerakan (datang)nya. Maha Suci Allah dan Maha Tinggi dari apa yang mereka persekutukan.'),
  ('id.indonesian', 16, 2, 'Dia menurunkan para malaikat dengan (membawa) wahyu dengan perintah-Nya kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya, yaitu: "Peringatkanlah olehmu sekalian, bahwasanya tidak ada Tuhan (yang hak) melainkan Aku, maka hendaklah kamu bertakwa kepada-Ku".'),
  ('id.indonesian', 16, 3, 'Dia menciptakan langit dan bumi dengan hak. Maha Tinggi Allah daripada apa yang mereka persekutukan.'),
  ('id.indonesian', 16, 4, 'Dia telah menciptakan manusia dari mani, tiba-tiba ia menjadi pembantah yang nyata.'),
  ('id.indonesian', 16, 5, 'Dan Dia telah menciptakan binatang ternak untuk kamu; padanya ada (bulu) yang menghangatkan dan berbagai-bagai manfaat, dan sebahagiannya kamu makan.'),
  ('id.indonesian', 16, 6, 'Dan kamu memperoleh pandangan yang indah padanya, ketika kamu membawanya kembali ke kandang dan ketika kamu melepaskannya ke tempat penggembalaan.'),
  ('id.indonesian', 16, 7, 'Dan ia memikul beban-bebanmu ke suatu negeri yang kamu tidak sanggup sampai kepadanya, melainkan dengan kesukaran-kesukaran (yang memayahkan) diri. Sesungguhnya Tuhanmu benar-benar Maha Pengasih lagi Maha Penyayang,'),
  ('id.indonesian', 16, 8, 'dan (Dia telah menciptakan) kuda, bagal dan keledai, agar kamu menungganginya dan (menjadikannya) perhiasan. Dan Allah menciptakan apa yang kamu tidak mengetahuinya.'),
  ('id.indonesian', 16, 9, 'Dan hak bagi Allah (menerangkan) jalan yang lurus, dan di antara jalan-jalan ada yang bengkok. Dan jikalau Dia menghendaki, tentulah Dia memimpin kamu semuanya (kepada jalan yang benar).'),
  ('id.indonesian', 16, 10, 'Dialah, Yang telah menurunkan air hujan dari langit untuk kamu, sebahagiannya menjadi minuman dan sebahagiannya (menyuburkan) tumbuh-tumbuhan, yang pada (tempat tumbuhnya) kamu menggembalakan ternakmu.'),
  ('id.indonesian', 16, 11, 'Dia menumbuhkan bagi kamu dengan air hujan itu tanam-tanaman; zaitun, korma, anggur dan segala macam buah-buahan. Sesungguhnya pada yang demikian itu benar-benar ada tanda (kekuasaan Allah) bagi kaum yang memikirkan.'),
  ('id.indonesian', 16, 12, 'Dan Dia menundukkan malam dan siang, matahari dan bulan untukmu. Dan bintang-bintang itu ditundukkan (untukmu) dengan perintah-Nya. Sesungguhnya pada yang demikian itu benar-benar ada tanda-tanda (kekuasaan Allah) bagi kaum yang memahami(nya),'),
  ('id.indonesian', 16, 13, 'dan Dia (menundukkan pula) apa yang Dia ciptakan untuk kamu di bumi ini dengan berlain-lainan macamnya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah) bagi kaum yang mengambil pelajaran.'),
  ('id.indonesian', 16, 14, 'Dan Dialah, Allah yang menundukkan lautan (untukmu), agar kamu dapat memakan daripadanya daging yang segar (ikan), dan kamu mengeluarkan dari lautan itu perhiasan yang kamu pakai; dan kamu melihat bahtera berlayar padanya, dan supaya kamu mencari (keuntungan) dari karunia-Nya, dan supaya kamu bersyukur.'),
  ('id.indonesian', 16, 15, 'Dan Dia menancapkan gunung-gunung di bumi supaya bumi itu tidak goncang bersama kamu, (dan Dia menciptakan) sungai-sungai dan jalan-jalan agar kamu mendapat petunjuk,'),
  ('id.indonesian', 16, 16, 'dan (Dia ciptakan) tanda-tanda (penunjuk jalan). Dan dengan bintang-bintang itulah mereka mendapat petunjuk.'),
  ('id.indonesian', 16, 17, 'Maka apakah (Allah) yang menciptakan itu sama dengan yang tidak dapat menciptakan (apa-apa)?. Maka mengapa kamu tidak mengambil pelajaran.'),
  ('id.indonesian', 16, 18, 'Dan jika kamu menghitung-hitung nikmat Allah, niscaya kamu tak dapat menentukan jumlahnya. Sesungguhnya Allah benar-benar Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 16, 19, 'Dan Allah mengetahui apa yang kamu rahasiakan dan apa yang kamu lahirkan.'),
  ('id.indonesian', 16, 20, 'Dan berhala-berhala yang mereka seru selain Allah, tidak dapat membuat sesuatu apapun, sedang berhala-berhala itu (sendiri) dibuat orang.'),
  ('id.indonesian', 16, 21, '(Berhala-berhala itu) benda mati tidak hidup, dan berhala-berhala tidak mengetahui bilakah penyembah-penyembahnya akan dibangkitkan.'),
  ('id.indonesian', 16, 22, 'Tuhan kamu adalah Tuhan Yang Maha Esa. Maka orang-orang yang tidak beriman kepada akhirat, hati mereka mengingkari (keesaaan Allah), sedangkan mereka sendiri adalah orang-orang yang sombong.'),
  ('id.indonesian', 16, 23, 'Tidak diragukan lagi bahwa sesungguhnya Allah mengetahui apa yang mereka rahasiakan dan apa yang mereka lahirkan. Sesungguhnya Allah tidak menyukai orang-orang yang sombong.'),
  ('id.indonesian', 16, 24, 'Dan apabila dikatakan kepada mereka "Apakah yang telah diturunkan Tuhanmu?" Mereka menjawab: "Dongeng-dongengan orang-orang dahulu",'),
  ('id.indonesian', 16, 25, '(ucapan mereka) menyebabkan mereka memikul dosa-dosanya dengan sepenuh-penuhnya pada hari kiamat, dan sebahagian dosa-dosa orang yang mereka sesatkan yang tidak mengetahui sedikitpun (bahwa mereka disesatkan). Ingatlah, amat buruklah dosa yang mereka pikul itu.'),
  ('id.indonesian', 16, 26, 'Sesungguhnya orang-orang yang sebelum mereka telah mengadakan makar, maka Allah menghancurkan rumah-rumah mereka dari fondasinya, lalu atap (rumah itu) jatuh menimpa mereka dari atas, dan datanglah azab itu kepada mereka dari tempat yang tidak mereka sadari.'),
  ('id.indonesian', 16, 27, 'Kemudian Allah menghinakan mereka di hari kiamat, dan berfirman: "Di manakah sekutu-sekutu-Ku itu (yang karena membelanya) kamu selalu memusuhi mereka (nabi-nabi dan orang-orang mukmin)?" Berkatalah orang-orang yang telah diberi ilmu: "Sesungguhnya kehinaan dan azab hari ini ditimpakan atas orang-orang yang kafir",'),
  ('id.indonesian', 16, 28, '(yaitu) orang-orang yang dimatikan oleh para malaikat dalam keadaan berbuat zalim kepada diri mereka sendiri, lalu mereka menyerah diri (sambil berkata); "Kami sekali-kali tidak ada mengerjakan sesuatu kejahatanpun". (Malaikat menjawab): "Ada, sesungguhnya Allah Maha Mengetahui apa yang telah kamu kerjakan".'),
  ('id.indonesian', 16, 29, 'Maka masukilah pintu-pintu neraka Jahannam, kamu kekal di dalamnya. Maka amat buruklah tempat orang-orang yang menyombongkan diri itu.'),
  ('id.indonesian', 16, 30, 'Dan dikatakan kepada orang-orang yang bertakwa: "Apakah yang telah diturunkan oleh Tuhanmu?" Mereka menjawab: "(Allah telah menurunkan) kebaikan". Orang-orang yang berbuat baik di dunia ini mendapat (pembalasan) yang baik. Dan sesungguhnya kampung akhirat adalah lebih baik dan itulah sebaik-baik tempat bagi orang yang bertakwa,'),
  ('id.indonesian', 16, 31, '(yaitu) surga \'Adn yang mereka masuk ke dalamnya, mengalir di bawahnya sungai-sungai, di dalam surga itu mereka mendapat segala apa yang mereka kehendaki. Demikianlah Allah memberi balasan kepada orang-orang yang bertakwa,'),
  ('id.indonesian', 16, 32, '(yaitu) orang-orang yang diwafatkan dalam keadaan baik oleh para malaikat dengan mengatakan (kepada mereka): "Salaamun\'alaikum, masuklah kamu ke dalam surga itu disebabkan apa yang telah kamu kerjakan".'),
  ('id.indonesian', 16, 33, 'Tidak ada yang ditunggu-tunggu orang kafir selain dari datangnya para malaikat kepada mereka atau datangnya perintah Tuhanmu. Demikianlah yang telah diperbuat oleh orang-orang (kafir) sebelum mereka. Dan Allah tidak menganiaya mereka, akan tetapi merekalah yang selalu menganiaya diri mereka sendiri,'),
  ('id.indonesian', 16, 34, 'Maka mereka ditimpa oleh (akibat) kejahatan perbuatan mereka dan mereka diliputi oleh azab yang selalu mereka perolok-olokan.'),
  ('id.indonesian', 16, 35, 'Dan berkatalah orang-orang musyrik: "Jika Allah menghendaki, niscaya kami tidak akan menyembah sesuatu apapun selain Dia, baik kami maupun bapak-bapak kami, dan tidak pula kami mengharamkan sesuatupun tanpa (izin)-Nya". Demikianlah yang diperbuat orang-orang sebelum mereka; maka tidak ada kewajiban atas para rasul, selain dari menyampaikan (amanat Allah) dengan terang.'),
  ('id.indonesian', 16, 36, 'Dan sungguhnya Kami telah mengutus rasul pada tiap-tiap umat (untuk menyerukan): "Sembahlah Allah (saja), dan jauhilah Thaghut itu", maka di antara umat itu ada orang-orang yang diberi petunjuk oleh Allah dan ada pula di antaranya orang-orang yang telah pasti kesesatan baginya. Maka berjalanlah kamu dimuka bumi dan perhatikanlah bagaimana kesudahan orang-orang yang mendustakan (rasul-rasul).'),
  ('id.indonesian', 16, 37, 'Jika kamu sangat mengharapkan agar mereka dapat petunjuk, maka sesungguhnya Allah tiada memberi petunjuk kepada orang yang disesatkan-Nya, dan sekali-kali mereka tiada mempunyai penolong.'),
  ('id.indonesian', 16, 38, 'Mereka bersumpah dengan nama Allah dengan sumpahnya yang sungguh-sungguh: "Allah tidak akan akan membangkitkan orang yang mati". (Tidak demikian), bahkan (pasti Allah akan membangkitnya), sebagai suatu janji yang benar dari Allah, akan tetapi kebanyakan manusia tiada mengetahui,'),
  ('id.indonesian', 16, 39, 'agar Allah menjelaskan kepada mereka apa yang mereka perselisihkan itu, agar orang-orang kafir itu mengetahui bahwasanya mereka adalah orang-orang yang berdusta.'),
  ('id.indonesian', 16, 40, 'Sesungguhnya perkataan Kami terhadap sesuatu apabila Kami menghendakinya, Kami hanya mengatakan kepadanya: "kun (jadilah)", maka jadilah ia.'),
  ('id.indonesian', 16, 41, 'Dan orang-orang yang berhijrah karena Allah sesudah mereka dianiaya, pasti Kami akan memberikan tempat yang bagus kepada mereka di dunia. Dan sesungguhnya pahala di akhirat adalah lebih besar, kalau mereka mengetahui,'),
  ('id.indonesian', 16, 42, '(yaitu) orang-orang yang sabar dan hanya kepada Tuhan saja mereka bertawakkal.'),
  ('id.indonesian', 16, 43, 'Dan Kami tidak mengutus sebelum kamu, kecuali orang-orang lelaki yang Kami beri wahyu kepada mereka; maka bertanyalah kepada orang yang mempunyai pengetahuan jika kamu tidak mengetahui,'),
  ('id.indonesian', 16, 44, 'keterangan-keterangan (mukjizat) dan kitab-kitab. Dan Kami turunkan kepadamu Al Quran, agar kamu menerangkan pada umat manusia apa yang telah diturunkan kepada mereka dan supaya mereka memikirkan,'),
  ('id.indonesian', 16, 45, 'maka apakah orang-orang yang membuat makar yang jahat itu, merasa aman (dari bencana) ditenggelamkannya bumi oleh Allah bersama mereka, atau datangnya azab kepada mereka dari tempat yang tidak mereka sadari,'),
  ('id.indonesian', 16, 46, 'atau Allah mengazab mereka diwaktu mereka dalam perjalanan, maka sekali-kali mereka tidak dapat menolak (azab itu),'),
  ('id.indonesian', 16, 47, 'atau Allah mengazab mereka dengan berangsur-angsur (sampai binasa). Maka sesungguhnya Tuhanmu adalah Maha Pengasih lagi Maha Penyayang.'),
  ('id.indonesian', 16, 48, 'Dan apakah mereka tidak memperhatikan segala sesuatu yang telah diciptakan Allah yang bayangannya berbolak-balik ke kanan dan ke kiri dalam keadaan sujud kepada Allah, sedang mereka berendah diri?'),
  ('id.indonesian', 16, 49, 'Dan kepada Allah sajalah bersujud segala apa yang berada di langit dan semua makhluk yang melata di bumi dan (juga) para ma]aikat, sedang mereka (malaikat) tidak menyombongkan diri.'),
  ('id.indonesian', 16, 50, 'Mereka takut kepada Tuhan mereka yang di atas mereka dan melaksanakan apa yang diperintahkan (kepada mereka).'),
  ('id.indonesian', 16, 51, 'Allah berfirman: "Janganlah kamu menyembah dua tuhan; sesungguhnya Dialah Tuhan Yang Maha Esa, maka hendaklah kepada-Ku saja kamu takut".'),
  ('id.indonesian', 16, 52, 'Dan kepunyaan-Nya-lah segala apa yang ada di langit dan di bumi, dan untuk-Nya-lah ketaatan itu selama-lamanya. Maka mengapa kamu bertakwa kepada selain Allah?'),
  ('id.indonesian', 16, 53, 'Dan apa saja nikmat yang ada pada kamu, maka dari Allah-lah (datangnya), dan bila kamu ditimpa oleh kemudharatan, maka hanya kepada-Nya-lah kamu meminta pertolongan.'),
  ('id.indonesian', 16, 54, 'Kemudian apabila Dia telah menghilangkan kemudharatan itu dari pada kamu, tiba-tiba sebahagian dari pada kamu mempersekutukan Tuhannya dengan (yang lain),'),
  ('id.indonesian', 16, 55, 'Biarlah mereka mengingkari nikmat yang telah Kami berikan kepada mereka; maka bersenang-senanglah kamu. Kelak kamu akan mengetahui (akibatnya).'),
  ('id.indonesian', 16, 56, 'Dan mereka sediakan untuk berhala-berhala yang mereka tiada mengetahui (kekuasaannya), satu bahagian dari rezeki yang telah Kami berikan kepada mereka. Demi Allah, sesungguhnya kamu akan ditanyai tentang apa yang telah kamu ada-adakan.'),
  ('id.indonesian', 16, 57, 'Dan mereka menetapkan bagi Allah anak-anak perempuan. Maha Suci Allah, sedang untuk mereka sendiri (mereka tetapkan) apa yang mereka sukai (yaitu anak-anak laki-laki).'),
  ('id.indonesian', 16, 58, 'Dan apabila seseorang dari mereka diberi kabar dengan (kelahiran) anak perempuan, hitamlah (merah padamlah) mukanya, dan dia sangat marah.'),
  ('id.indonesian', 16, 59, 'Ia menyembunyikan dirinya dari orang banyak, disebabkan buruknya berita yang disampaikan kepadanya. Apakah dia akan memeliharanya dengan menanggung kehinaan ataukah akan menguburkannya ke dalam tanah (hidup-hidup)?. Ketahuilah, alangkah buruknya apa yang mereka tetapkan itu.'),
  ('id.indonesian', 16, 60, 'Orang-orang yang tidak beriman kepada kehidupan akhirat, mempunyai sifat yang buruk; dan Allah mempunyai sifat yang Maha Tinggi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 16, 61, 'Jikalau Allah menghukum manusia karena kezalimannya, niscaya tidak akan ditinggalkan-Nya di muka bumi sesuatupun dari makhluk yang melata, tetapi Allah menangguhkan mereka sampai kepada waktu yang ditentukan. Maka apabila telah tiba waktunya (yang ditentukan) bagi mereka, tidaklah mereka dapat mengundurkannya barang sesaatpun dan tidak (pula) mendahulukannya.'),
  ('id.indonesian', 16, 62, 'Dan mereka menetapkan bagi Allah apa yang mereka sendiri membencinya, dan lidah mereka mengucapkan kedustaan, yaitu bahwa sesungguhnya merekalah yang akan mendapat kebaikan. Tiadalah diragukan bahwa nerakalah bagi mereka, dan sesungguhnya mereka segera dimasukkan (ke dalamnya).'),
  ('id.indonesian', 16, 63, 'Demi Allah, sesungguhnya Kami telah mengutus rasul-rasul Kami kepada umat-umat sebelum kamu, tetapi syaitan menjadikan umat-umat itu memandang baik perbuatan mereka (yang buruk), maka syaitan menjadi pemimpin mereka di hari itu dan bagi mereka azab yang sangat pedih.'),
  ('id.indonesian', 16, 64, 'Dan Kami tidak menurunkan kepadamu Al-Kitab (Al Quran) ini, melainkan agar kamu dapat menjelaskan kepada mereka apa yang mereka perselisihkan itu dan menjadi petunjuk dan rahmat bagi kaum yang beriman.'),
  ('id.indonesian', 16, 65, 'Dan Allah menurunkan dari langit air (hujan) dan dengan air itu dihidupkan-Nya bumi sesudah matinya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Tuhan) bagi orang-orang yang mendengarkan (pelajaran).'),
  ('id.indonesian', 16, 66, 'Dan sesungguhnya pada binatang ternak itu benar-benar terdapat pelajaran bagi kamu. Kami memberimu minum dari pada apa yang berada dalam perutnya (berupa) susu yang bersih antara tahi dan darah, yang mudah ditelan bagi orang-orang yang meminumnya.'),
  ('id.indonesian', 16, 67, 'Dan dari buah korma dan anggur, kamu buat minimuman yang memabukkan dan rezeki yang baik. Sesunggguhnya pada yang demikian itu benar-benar terdapat tanda (kebesaran Allah) bagi orang yang memikirkan.'),
  ('id.indonesian', 16, 68, 'Dan Tuhanmu mewahyukan kepada lebah: "Buatlah sarang-sarang di bukit-bukit, di pohon-pohon kayu, dan di tempat-tempat yang dibikin manusia",'),
  ('id.indonesian', 16, 69, 'kemudian makanlah dari tiap-tiap (macam) buah-buahan dan tempuhlah jalan Tuhanmu yang telah dimudahkan (bagimu). Dari perut lebah itu ke luar minuman (madu) yang bermacam-macam warnanya, di dalamnya terdapat obat yang menyembuhkan bagi manusia. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kebesaran Tuhan) bagi orang-orang yang memikirkan.'),
  ('id.indonesian', 16, 70, 'Allah menciptakan kamu, kemudian mewafatkan kamu; dan di antara kamu ada yang dikembalikan kepada umur yang paling lemah (pikun), supaya dia tidak mengetahui lagi sesuatupun yang pernah diketahuinya. Sesungguhnya Allah Maha Mengetahui lagi Maha Kuasa.'),
  ('id.indonesian', 16, 71, 'Dan Allah melebihkan sebahagian kamu dari sebagian yang lain dalam hal rezeki, tetapi orang-orang yang dilebihkan (rezekinya itu) tidak mau memberikan rezeki mereka kepada budak-budak yang mereka miliki, agar mereka sama (merasakan) rezeki itu. Maka mengapa mereka mengingkari nikmat Allah?.'),
  ('id.indonesian', 16, 72, 'Allah menjadikan bagi kamu isteri-isteri dari jenis kamu sendiri dan menjadikan bagimu dari isteri-isteri kamu itu, anak-anak dan cucu-cucu, dan memberimu rezeki dari yang baik-baik. Maka mengapakah mereka beriman kepada yang bathil dan mengingkari nikmat Allah?"'),
  ('id.indonesian', 16, 73, 'Dan mereka menyembah selain Allah, sesuatu yang tidak dapat memberikan rezeki kepada mereka sedikitpun dari langit dan bumi, dan tidak berkuasa (sedikit juapun).'),
  ('id.indonesian', 16, 74, 'Maka janganlah kamu mengadakan sekutu-sekutu bagi Allah. Sesungguhnya Allah mengetahui, sedang kamu tidak mengetahui.'),
  ('id.indonesian', 16, 75, 'Allah membuat perumpamaan dengan seorang hamba sahaya yang dimiliki yang tidak dapat bertindak terhadap sesuatupun dan seorang yang Kami beri rezeki yang baik dari Kami, lalu dia menafkahkan sebagian dari rezeki itu secara sembunyi dan secara terang-terangan, adakah mereka itu sama? Segala puji hanya bagi Allah, tetapi kebanyakan mereka tiada mengetahui.'),
  ('id.indonesian', 16, 76, 'Dan Allah membuat (pula) perumpamaan: dua orang lelaki yang seorang bisu, tidak dapat berbuat sesuatupun dan dia menjadi beban atas penanggungnya, ke mana saja dia disuruh oleh penanggungnya itu, dia tidak dapat mendatangkan suatu kebajikanpun. Samakah orang itu dengan orang yang menyuruh berbuat keadilan, dan dia berada pula di atas jalan yang lurus?'),
  ('id.indonesian', 16, 77, 'Dan kepunyaan Allah-lah segala apa yang tersembunyi di langit dan di bumi. Tidak adalah kejadian kiamat itu, melainkan seperti sekejap mata atau lebih cepat (lagi). Sesungguhnya Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 16, 78, 'Dan Allah mengeluarkan kamu dari perut ibumu dalam keadaan tidak mengetahui sesuatupun, dan Dia memberi kamu pendengaran, penglihatan dan hati, agar kamu bersyukur.'),
  ('id.indonesian', 16, 79, 'Tidakkah mereka memperhatikan burung-burung yang dimudahkan terbang diangkasa bebas. Tidak ada yang menahannya selain daripada Allah. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Tuhan) bagi orang-orang yang beriman.'),
  ('id.indonesian', 16, 80, 'Dan Allah menjadikan bagimu rumah-rumahmu sebagai tempat tinggal dan Dia menjadikan bagi kamu rumah-rumah (kemah-kemah) dari kulit binatang ternak yang kamu merasa ringan (membawa)nya di waktu kamu berjalan dan waktu kamu bermukim dan (dijadikan-Nya pula) dari bulu domba, bulu unta dan bulu kambing, alat-alat rumah tangga dan perhiasan (yang kamu pakai) sampai waktu (tertentu).'),
  ('id.indonesian', 16, 81, 'Dan Allah menjadikan bagimu tempat bernaung dari apa yang telah Dia ciptakan, dan Dia jadikan bagimu tempat-tempat tinggal di gunung-gunung, dan Dia jadikan bagimu pakaian yang memeliharamu dari panas dan pakaian (baju besi) yang memelihara kamu dalam peperangan. Demikianlah Allah menyempurnakan nikmat-Nya atasmu agar kamu berserah diri (kepada-Nya).'),
  ('id.indonesian', 16, 82, 'Jika mereka tetap berpaling, maka sesungguhnya kewajiban yang dibebankan atasmu (Muhammad) hanyalah menyampaikan (amanat Allah) dengan terang.'),
  ('id.indonesian', 16, 83, 'Mereka mengetahui nikmat Allah, kemudian mereka mengingkarinya dan kebanyakan mereka adalah orang-orang yang kafir.'),
  ('id.indonesian', 16, 84, 'Dan (ingatlah) akan hari (ketika) Kami bangkitkan dari tiap-tiap umat seorang saksi (rasul), kemudian tidak diizinkan kepada orang-orang yang kafir (untuk membela diri) dan tidak (pula) mereka dibolehkan meminta maaf.'),
  ('id.indonesian', 16, 85, 'Dan apabila orang-orang zalim telah menyaksikan azab, maka tidaklah diringankan azab bagi mereka dan tidak puIa mereka diberi tangguh.'),
  ('id.indonesian', 16, 86, 'Dan apabila orang-orang yang mempersekutukan (Allah) melihat sekutu-sekutu mereka, mereka berkata: "Ya Tuhan kami mereka inilah sekutu-sekutu kami yang dahulu kami sembah selain dari Engkau". Lalu sekutu-sekutu mereka mengatakan kepada mereka: "Sesungguhnya kamu benar-benar orang-orang yang dusta".'),
  ('id.indonesian', 16, 87, 'Dan mereka menyatakan ketundukannya kepada Allah pada hari itu dan hilanglah dari mereka apa yang selalu mereka ada-adakan.'),
  ('id.indonesian', 16, 88, 'Orang-orang yang kafir dan menghalangi (manusia) dari jalan Allah, Kami tambahkan kepada mereka siksaan di atas siksaan disebabkan mereka selalu berbuat kerusakan.'),
  ('id.indonesian', 16, 89, '(Dan ingatlah) akan hari (ketika) Kami bangkitkan pada tiap-tiap umat seorang saksi atas mereka dari mereka sendiri dan Kami datangkan kamu (Muhammad) menjadi saksi atas seluruh umat manusia. Dan Kami turunkan kepadamu Al Kitab (Al Quran) untuk menjelaskan segala sesuatu dan petunjuk serta rahmat dan kabar gembira bagi orang-orang yang berserah diri.'),
  ('id.indonesian', 16, 90, 'Sesungguhnya Allah menyuruh (kamu) berlaku adil dan berbuat kebajikan, memberi kepada kaum kerabat, dan Allah melarang dari perbuatan keji, kemungkaran dan permusuhan. Dia memberi pengajaran kepadamu agar kamu dapat mengambil pelajaran.'),
  ('id.indonesian', 16, 91, 'Dan tepatilah perjanjian dengan Allah apabila kamu berjanji dan janganlah kamu membatalkan sumpah-sumpah(mu) itu, sesudah meneguhkannya, sedang kamu telah menjadikan Allah sebagai saksimu (terhadap sumpah-sumpahmu itu). Sesungguhnya Allah mengetahui apa yang kamu perbuat.'),
  ('id.indonesian', 16, 92, 'Dan janganlah kamu seperti seorang perempuan yang menguraikan benangnya yang sudah dipintal dengan kuat, menjadi cerai berai kembali, kamu menjadikan sumpah (perjanjian)mu sebagai alat penipu di antaramu, disebabkan adanya satu golongan yang lebih banyak jumlahnya dari golongan yang lain. Sesungguhnya Allah hanya menguji kamu dengan hal itu. Dan sesungguhnya di hari kiamat akan dijelaskan-Nya kepadamu apa yang dahulu kamu perselisihkan itu.'),
  ('id.indonesian', 16, 93, 'Dan kalau Allah menghendaki, niscaya Dia menjadikan kamu satu umat (saja), tetapi Allah menyesatkan siapa yang dikehendaki-Nya dan memberi petunjuk kepada siapa yang dikehendaki-Nya. Dan sesungguhnya kamu akan ditanya tentang apa yang telah kamu kerjakan.'),
  ('id.indonesian', 16, 94, 'Dan janganlah kamu jadikan sumpah-sumpahmu sebagai alat penipu di antaramu, yang menyebabkan tergelincir kaki(mu) sesudah kokoh tegaknya, dan kamu rasakan kemelaratan (di dunia) karena kamu menghalangi (manusia) dari jalan Allah; dan bagimu azab yang besar.'),
  ('id.indonesian', 16, 95, 'Dan janganlah kamu tukar perjanjianmu dengan Allah dengan harga yang sedikit (murah), sesungguhnya apa yang ada di sisi Allah, itulah yang lebih baik bagimu jika kamu mengetahui.'),
  ('id.indonesian', 16, 96, 'Apa yang di sisimu akan lenyap, dan apa yang ada di sisi Allah adalah kekal. Dan sesungguhnya Kami akan memberi balasan kepada orang-orang yang sabar dengan pahala yang lebih baik dari apa yang telah mereka kerjakan.'),
  ('id.indonesian', 16, 97, 'Barangsiapa yang mengerjakan amal saleh, baik laki-laki maupun perempuan dalam keadaan beriman, maka sesungguhnya akan Kami berikan kepadanya kehidupan yang baik dan sesungguhnya akan Kami beri balasan kepada mereka dengan pahala yang lebih baik dari apa yang telah mereka kerjakan.'),
  ('id.indonesian', 16, 98, 'Apabila kamu membaca Al Quran hendaklah kamu meminta perlindungan kepada Allah dari syaitan yang terkutuk.'),
  ('id.indonesian', 16, 99, 'Sesungguhnya syaitan itu tidak ada kekuasaannya atas orang-orang yang beriman dan bertawakkal kepada Tuhannya.'),
  ('id.indonesian', 16, 100, 'Sesungguhnya kekuasaannya (syaitan) hanyalah atas orang-orang yang mengambilnya jadi pemimpin dan atas orang-orang yang mempersekutukannya dengan Allah.'),
  ('id.indonesian', 16, 101, 'Dan apabila Kami letakkan suatu ayat di tempat ayat yang lain sebagai penggantinya padahal Allah lebih mengetahui apa yang diturunkan-Nya, mereka berkata: "Sesungguhnya kamu adalah orang yang mengada-adakan saja". Bahkan kebanyakan mereka tiada mengetahui.'),
  ('id.indonesian', 16, 102, 'Katakanlah: "Ruhul Qudus (Jibril) menurunkan Al Quran itu dari Tuhanmu dengan benar, untuk meneguhkan (hati) orang-orang yang telah beriman, dan menjadi petunjuk serta kabar gembira bagi orang-orang yang berserah diri (kepada Allah)".'),
  ('id.indonesian', 16, 103, 'Dan sesungguhnya Kami mengetahui bahwa mereka berkata: "Sesungguhnya Al Quran itu diajarkan oleh seorang manusia kepadanya (Muhammad)". Padahal bahasa orang yang mereka tuduhkan (bahwa) Muhammad belajar kepadanya bahasa \'Ajam, sedang Al Quran adalah dalam bahasa Arab yang terang.'),
  ('id.indonesian', 16, 104, 'Sesungguhnya orang-orang yang tidak beriman kepada ayat-ayat Allah (Al Quran), Allah tidak akan memberi petunjuk kepada mereka dan bagi mereka azab yang pedih.'),
  ('id.indonesian', 16, 105, 'Sesungguhnya yang mengada-adakan kebohongan, hanyalah orang-orang yang tidak beriman kepada ayat-ayat Allah, dan mereka itulah orang-orang pendusta.'),
  ('id.indonesian', 16, 106, 'Barangsiapa yang kafir kepada Allah sesudah dia beriman (dia mendapat kemurkaan Allah), kecuali orang yang dipaksa kafir padahal hatinya tetap tenang dalam beriman (dia tidak berdosa), akan tetapi orang yang melapangkan dadanya untuk kekafiran, maka kemurkaan Allah menimpanya dan baginya azab yang besar.'),
  ('id.indonesian', 16, 107, 'Yang demikian itu disebabkan karena sesungguhnya mereka mencintai kehidupan di dunia lebih dari akhirat, dan bahwasanya Allah tiada memberi petunjuk kepada kaum yang kafir.'),
  ('id.indonesian', 16, 108, 'Mereka itulah orang-orang yang hati, pendengaran dan penglihatannya telah dikunci mati oleh Allah, dan mereka itulah orang-orang yang lalai.'),
  ('id.indonesian', 16, 109, 'Pastilah bahwa mereka di akhirat nanti adalah orang-orang yang merugi.'),
  ('id.indonesian', 16, 110, 'Dan sesungguhnya Tuhanmu (pelindung) bagi orang-orang yang berhijrah sesudah menderita cobaan, kemudian mereka berjihad dan sabar; sesungguhnya Tuhanmu sesudah itu benar-benar Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 16, 111, '(Ingatlah) suatu hari (ketika) tiap-tiap diri datang untuk membela dirinya sendiri dan bagi tiap-tiap diri disempurnakan (balasan) apa yang telah dikerjakannya, sedangkan mereka tidak dianiaya (dirugikan).'),
  ('id.indonesian', 16, 112, 'Dan Allah telah membuat suatu perumpamaan (dengan) sebuah negeri yang dahulunya aman lagi tenteram, rezekinya datang kepadanya melimpah ruah dari segenap tempat, tetapi (penduduk)nya mengingkari nikmat-nikmat Allah; karena itu Allah merasakan kepada mereka pakaian kelaparan dan ketakutan, disebabkan apa yang selalu mereka perbuat.'),
  ('id.indonesian', 16, 113, 'Dan sesungguhnya telah datang kepada mereka seorang rasul dari mereka sendiri, tetapi mereka mendustakannya; karena itu mereka dimusnahkan azab dan mereka adalah orang-orang yang zalim.'),
  ('id.indonesian', 16, 114, 'Maka makanlah yang halal lagi baik dari rezeki yang telah diberikan Allah kepadamu; dan syukurilah nikmat Allah, jika kamu hanya kepada-Nya saja menyembah.'),
  ('id.indonesian', 16, 115, 'Sesungguhnya Allah hanya mengharamkan atasmu (memakan) bangkai, darah, daging babi dan apa yang disembelih dengan menyebut nama selain Allah; tetapi barangsiapa yang terpaksa memakannya dengan tidak menganiaya dan tidak pula melampaui batas, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 16, 116, 'Dan janganlah kamu mengatakan terhadap apa yang disebut-sebut oleh lidahmu secara dusta "ini halal dan ini haram", untuk mengada-adakan kebohongan terhadap Allah. Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah tiadalah beruntung.'),
  ('id.indonesian', 16, 117, '(Itu adalah) kesenangan yang sedikit, dan bagi mereka azab yang pedih.'),
  ('id.indonesian', 16, 118, 'Dan terhadap orang-orang Yahudi, Kami haramkan apa yang telah Kami ceritakan dahulu kepadamu; dan Kami tiada menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.'),
  ('id.indonesian', 16, 119, 'Kemudian, sesungguhnya Tuhanmu (mengampuni) bagi orang-orang yang mengerjakan kesalahan karena kebodohannya, kemudian mereka bertaubat sesudah itu dan memperbaiki (dirinya), sesungguhnya Tuhanmu sesudah itu benar-benar Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 16, 120, 'Sesungguhnya Ibrahim adalah seorang imam yang dapat dijadikan teladan lagi patuh kepada Allah dan hanif. Dan sekali-kali bukanlah dia termasuk orang-orang yang mempersekutukan (Tuhan),'),
  ('id.indonesian', 16, 121, '(lagi) yang mensyukuri nikmat-nikmat Allah. Allah telah memilihnya dan menunjukinya kepada jalan yang lurus.'),
  ('id.indonesian', 16, 122, 'Dan Kami berikan kepadanya kebaikan di dunia. Dan sesungguhnya dia di akhirat benar-benar termasuk orang-orang yang saleh.'),
  ('id.indonesian', 16, 123, 'Kemudian Kami wahyukan kepadamu (Muhammad): "Ikutilah agama Ibrahim seorang yang hanif" dan bukanlah dia termasuk orang-orang yang mempersekutukan Tuhan.'),
  ('id.indonesian', 16, 124, 'Sesungguhnya diwajibkan (menghormati) hari Sabtu atas orang-orang (Yahudi) yang berselisih padanya. Dan sesungguhnya Tuhanmu benar-benar akan memberi putusan di antara mereka di hari kiamat terhadap apa yang telah mereka perselisihkan itu.'),
  ('id.indonesian', 16, 125, 'Serulah (manusia) kepada jalan Tuhan-mu dengan hikmah dan pelajaran yang baik dan bantahlah mereka dengan cara yang baik. Sesungguhnya Tuhanmu Dialah yang lebih mengetahui tentang siapa yang tersesat dari jalan-Nya dan Dialah yang lebih mengetahui orang-orang yang mendapat petunjuk.'),
  ('id.indonesian', 16, 126, 'Dan jika kamu memberikan balasan, maka balaslah dengan balasan yang sama dengan siksaan yang ditimpakan kepadamu. Akan tetapi jika kamu bersabar, sesungguhnya itulah yang lebih baik bagi orang-orang yang sabar.'),
  ('id.indonesian', 16, 127, 'Bersabarlah (hai Muhammad) dan tiadalah kesabaranmu itu melainkan dengan pertolongan Allah dan janganlah kamu bersedih hati terhadap (kekafiran) mereka dan janganlah kamu bersempit dada terhadap apa yang mereka tipu dayakan.'),
  ('id.indonesian', 16, 128, 'Sesungguhnya Allah beserta orang-orang yang bertakwa dan orang-orang yang berbuat kebaikan.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 17, 1, 'Exalted is He who took His Servant by night from al-Masjid al-Haram to al-Masjid al-Aqsa, whose surroundings We have blessed, to show him of Our signs. Indeed, He is the Hearing, the Seeing.'),
  ('en.sahih', 17, 2, 'And We gave Moses the Scripture and made it a guidance for the Children of Israel that you not take other than Me as Disposer of affairs,'),
  ('en.sahih', 17, 3, 'O descendants of those We carried [in the ship] with Noah. Indeed, he was a grateful servant.'),
  ('en.sahih', 17, 4, 'And We conveyed to the Children of Israel in the Scripture that, "You will surely cause corruption on the earth twice, and you will surely reach [a degree of] great haughtiness.'),
  ('en.sahih', 17, 5, 'So when the [time of] promise came for the first of them, We sent against you servants of Ours - those of great military might, and they probed [even] into the homes, and it was a promise fulfilled.'),
  ('en.sahih', 17, 6, 'Then We gave back to you a return victory over them. And We reinforced you with wealth and sons and made you more numerous in manpower'),
  ('en.sahih', 17, 7, '[And said], "If you do good, you do good for yourselves; and if you do evil, [you do it] to yourselves." Then when the final promise came, [We sent your enemies] to sadden your faces and to enter the temple in Jerusalem, as they entered it the first time, and to destroy what they had taken over with [total] destruction.'),
  ('en.sahih', 17, 8, '[Then Allah said], "It is expected, [if you repent], that your Lord will have mercy upon you. But if you return [to sin], We will return [to punishment]. And We have made Hell, for the disbelievers, a prison-bed."'),
  ('en.sahih', 17, 9, 'Indeed, this Qur\'an guides to that which is most suitable and gives good tidings to the believers who do righteous deeds that they will have a great reward.'),
  ('en.sahih', 17, 10, 'And that those who do not believe in the Hereafter - We have prepared for them a painful punishment.'),
  ('en.sahih', 17, 11, 'And man supplicates for evil as he supplicates for good, and man is ever hasty.'),
  ('en.sahih', 17, 12, 'And We have made the night and day two signs, and We erased the sign of the night and made the sign of the day visible that you may seek bounty from your Lord and may know the number of years and the account [of time]. And everything We have set out in detail.'),
  ('en.sahih', 17, 13, 'And [for] every person We have imposed his fate upon his neck, and We will produce for him on the Day of Resurrection a record which he will encounter spread open.'),
  ('en.sahih', 17, 14, '[It will be said], "Read your record. Sufficient is yourself against you this Day as accountant."'),
  ('en.sahih', 17, 15, 'Whoever is guided is only guided for [the benefit of] his soul. And whoever errs only errs against it. And no bearer of burdens will bear the burden of another. And never would We punish until We sent a messenger.'),
  ('en.sahih', 17, 16, 'And when We intend to destroy a city, We command its affluent but they defiantly disobey therein; so the word comes into effect upon it, and We destroy it with [complete] destruction.'),
  ('en.sahih', 17, 17, 'And how many have We destroyed from the generations after Noah. And sufficient is your Lord, concerning the sins of His servants, as Acquainted and Seeing.'),
  ('en.sahih', 17, 18, 'Whoever should desire the immediate - We hasten for him from it what We will to whom We intend. Then We have made for him Hell, which he will [enter to] burn, censured and banished.'),
  ('en.sahih', 17, 19, 'But whoever desires the Hereafter and exerts the effort due to it while he is a believer - it is those whose effort is ever appreciated [by Allah].'),
  ('en.sahih', 17, 20, 'To each [category] We extend - to these and to those - from the gift of your Lord. And never has the gift of your Lord been restricted.'),
  ('en.sahih', 17, 21, 'Look how We have favored [in provision] some of them over others. But the Hereafter is greater in degrees [of difference] and greater in distinction.'),
  ('en.sahih', 17, 22, 'Do not make [as equal] with Allah another deity and [thereby] become censured and forsaken.'),
  ('en.sahih', 17, 23, 'And your Lord has decreed that you not worship except Him, and to parents, good treatment. Whether one or both of them reach old age [while] with you, say not to them [so much as], "uff," and do not repel them but speak to them a noble word.'),
  ('en.sahih', 17, 24, 'And lower to them the wing of humility out of mercy and say, "My Lord, have mercy upon them as they brought me up [when I was] small."'),
  ('en.sahih', 17, 25, 'Your Lord is most knowing of what is within yourselves. If you should be righteous [in intention] - then indeed He is ever, to the often returning [to Him], Forgiving.'),
  ('en.sahih', 17, 26, 'And give the relative his right, and [also] the poor and the traveler, and do not spend wastefully.'),
  ('en.sahih', 17, 27, 'Indeed, the wasteful are brothers of the devils, and ever has Satan been to his Lord ungrateful.'),
  ('en.sahih', 17, 28, 'And if you [must] turn away from the needy awaiting mercy from your Lord which you expect, then speak to them a gentle word.'),
  ('en.sahih', 17, 29, 'And do not make your hand [as] chained to your neck or extend it completely and [thereby] become blamed and insolvent.'),
  ('en.sahih', 17, 30, 'Indeed, your Lord extends provision for whom He wills and restricts [it]. Indeed He is ever, concerning His servants, Acquainted and Seeing.'),
  ('en.sahih', 17, 31, 'And do not kill your children for fear of poverty. We provide for them and for you. Indeed, their killing is ever a great sin.'),
  ('en.sahih', 17, 32, 'And do not approach unlawful sexual intercourse. Indeed, it is ever an immorality and is evil as a way.'),
  ('en.sahih', 17, 33, 'And do not kill the soul which Allah has forbidden, except by right. And whoever is killed unjustly - We have given his heir authority, but let him not exceed limits in [the matter of] taking life. Indeed, he has been supported [by the law].'),
  ('en.sahih', 17, 34, 'And do not approach the property of an orphan, except in the way that is best, until he reaches maturity. And fulfill [every] commitment. Indeed, the commitment is ever [that about which one will be] questioned.'),
  ('en.sahih', 17, 35, 'And give full measure when you measure, and weigh with an even balance. That is the best [way] and best in result.'),
  ('en.sahih', 17, 36, 'And do not pursue that of which you have no knowledge. Indeed, the hearing, the sight and the heart - about all those [one] will be questioned.'),
  ('en.sahih', 17, 37, 'And do not walk upon the earth exultantly. Indeed, you will never tear the earth [apart], and you will never reach the mountains in height.'),
  ('en.sahih', 17, 38, 'All that - its evil is ever, in the sight of your Lord, detested.'),
  ('en.sahih', 17, 39, 'That is from what your Lord has revealed to you, [O Muhammad], of wisdom. And, [O mankind], do not make [as equal] with Allah another deity, lest you be thrown into Hell, blamed and banished.'),
  ('en.sahih', 17, 40, 'Then, has your Lord chosen you for [having] sons and taken from among the angels daughters? Indeed, you say a grave saying.'),
  ('en.sahih', 17, 41, 'And We have certainly diversified [the contents] in this Qur\'an that mankind may be reminded, but it does not increase the disbelievers except in aversion.'),
  ('en.sahih', 17, 42, 'Say, [O Muhammad], "If there had been with Him [other] gods, as they say, then they [each] would have sought to the Owner of the Throne a way."'),
  ('en.sahih', 17, 43, 'Exalted is He and high above what they say by great sublimity.'),
  ('en.sahih', 17, 44, 'The seven heavens and the earth and whatever is in them exalt Him. And there is not a thing except that it exalts [Allah] by His praise, but you do not understand their [way of] exalting. Indeed, He is ever Forbearing and Forgiving.'),
  ('en.sahih', 17, 45, 'And when you recite the Qur\'an, We put between you and those who do not believe in the Hereafter a concealed partition.'),
  ('en.sahih', 17, 46, 'And We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And when you mention your Lord alone in the Qur\'an, they turn back in aversion.'),
  ('en.sahih', 17, 47, 'We are most knowing of how they listen to it when they listen to you and [of] when they are in private conversation, when the wrongdoers say, "You follow not but a man affected by magic."'),
  ('en.sahih', 17, 48, 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.'),
  ('en.sahih', 17, 49, 'And they say, "When we are bones and crumbled particles, will we [truly] be resurrected as a new creation?"'),
  ('en.sahih', 17, 50, 'Say, "Be you stones or iron'),
  ('en.sahih', 17, 51, 'Or [any] creation of that which is great within your breasts." And they will say, "Who will restore us?" Say, "He who brought you forth the first time." Then they will nod their heads toward you and say, "When is that?" Say, "Perhaps it will be soon -'),
  ('en.sahih', 17, 52, 'On the Day He will call you and you will respond with praise of Him and think that you had not remained [in the world] except for a little."'),
  ('en.sahih', 17, 53, 'And tell My servants to say that which is best. Indeed, Satan induces [dissension] among them. Indeed Satan is ever, to mankind, a clear enemy.'),
  ('en.sahih', 17, 54, 'Your Lord is most knowing of you. If He wills, He will have mercy upon you; or if He wills, He will punish you. And We have not sent you, [O Muhammad], over them as a manager.'),
  ('en.sahih', 17, 55, 'And your Lord is most knowing of whoever is in the heavens and the earth. And We have made some of the prophets exceed others [in various ways], and to David We gave the book [of Psalms].'),
  ('en.sahih', 17, 56, 'Say, "Invoke those you have claimed [as gods] besides Him, for they do not possess the [ability for] removal of adversity from you or [for its] transfer [to someone else]."'),
  ('en.sahih', 17, 57, 'Those whom they invoke seek means of access to their Lord, [striving as to] which of them would be nearest, and they hope for His mercy and fear His punishment. Indeed, the punishment of your Lord is ever feared.'),
  ('en.sahih', 17, 58, 'And there is no city but that We will destroy it before the Day of Resurrection or punish it with a severe punishment. That has ever been in the Register inscribed.'),
  ('en.sahih', 17, 59, 'And nothing has prevented Us from sending signs except that the former peoples denied them. And We gave Thamud the she-camel as a visible sign, but they wronged her. And We send not the signs except as a warning.'),
  ('en.sahih', 17, 60, 'And [remember, O Muhammad], when We told you, "Indeed, your Lord has encompassed the people." And We did not make the sight which We showed you except as a trial for the people, as was the accursed tree [mentioned] in the Qur\'an. And We threaten them, but it increases them not except in great transgression.'),
  ('en.sahih', 17, 61, 'And [mention] when We said to the angles, "Prostrate to Adam," and they prostrated, except for Iblees. He said, "Should I prostrate to one You created from clay?"'),
  ('en.sahih', 17, 62, '[Iblees] said, "Do You see this one whom You have honored above me? If You delay me until the Day of Resurrection, I will surely destroy his descendants, except for a few."'),
  ('en.sahih', 17, 63, '[Allah] said, "Go, for whoever of them follows you, indeed Hell will be the recompense of you - an ample recompense.'),
  ('en.sahih', 17, 64, 'And incite [to senselessness] whoever you can among them with your voice and assault them with your horses and foot soldiers and become a partner in their wealth and their children and promise them." But Satan does not promise them except delusion.'),
  ('en.sahih', 17, 65, 'Indeed, over My [believing] servants there is for you no authority. And sufficient is your Lord as Disposer of affairs.'),
  ('en.sahih', 17, 66, 'It is your Lord who drives the ship for you through the sea that you may seek of His bounty. Indeed, He is ever, to you, Merciful.'),
  ('en.sahih', 17, 67, 'And when adversity touches you at sea, lost are [all] those you invoke except for Him. But when He delivers you to the land, you turn away [from Him]. And ever is man ungrateful.'),
  ('en.sahih', 17, 68, 'Then do you feel secure that [instead] He will not cause a part of the land to swallow you or send against you a storm of stones? Then you would not find for yourselves an advocate.'),
  ('en.sahih', 17, 69, 'Or do you feel secure that He will not send you back into the sea another time and send upon you a hurricane of wind and drown you for what you denied? Then you would not find for yourselves against Us an avenger.'),
  ('en.sahih', 17, 70, 'And We have certainly honored the children of Adam and carried them on the land and sea and provided for them of the good things and preferred them over much of what We have created, with [definite] preference.'),
  ('en.sahih', 17, 71, '[Mention, O Muhammad], the Day We will call forth every people with their record [of deeds]. Then whoever is given his record in his right hand - those will read their records, and injustice will not be done to them, [even] as much as a thread [inside the date seed].'),
  ('en.sahih', 17, 72, 'And whoever is blind in this [life] will be blind in the Hereafter and more astray in way.'),
  ('en.sahih', 17, 73, 'And indeed, they were about to tempt you away from that which We revealed to you in order to [make] you invent about Us something else; and then they would have taken you as a friend.'),
  ('en.sahih', 17, 74, 'And if We had not strengthened you, you would have almost inclined to them a little.'),
  ('en.sahih', 17, 75, 'Then [if you had], We would have made you taste double [punishment in] life and double [after] death. Then you would not find for yourself against Us a helper.'),
  ('en.sahih', 17, 76, 'And indeed, they were about to drive you from the land to evict you therefrom. And then [when they do], they will not remain [there] after you, except for a little.'),
  ('en.sahih', 17, 77, '[That is Our] established way for those We had sent before you of Our messengers; and you will not find in Our way any alteration.'),
  ('en.sahih', 17, 78, 'Establish prayer at the decline of the sun [from its meridian] until the darkness of the night and [also] the Qur\'an of dawn. Indeed, the recitation of dawn is ever witnessed.'),
  ('en.sahih', 17, 79, 'And from [part of] the night, pray with it as additional [worship] for you; it is expected that your Lord will resurrect you to a praised station.'),
  ('en.sahih', 17, 80, 'And say, "My Lord, cause me to enter a sound entrance and to exit a sound exit and grant me from Yourself a supporting authority."'),
  ('en.sahih', 17, 81, 'And say, "Truth has come, and falsehood has departed. Indeed is falsehood, [by nature], ever bound to depart."'),
  ('en.sahih', 17, 82, 'And We send down of the Qur\'an that which is healing and mercy for the believers, but it does not increase the wrongdoers except in loss.'),
  ('en.sahih', 17, 83, 'And when We bestow favor upon the disbeliever, he turns away and distances himself; and when evil touches him, he is ever despairing.'),
  ('en.sahih', 17, 84, 'Say, "Each works according to his manner, but your Lord is most knowing of who is best guided in way."'),
  ('en.sahih', 17, 85, 'And they ask you, [O Muhammad], about the soul. Say, "The soul is of the affair of my Lord. And mankind have not been given of knowledge except a little."'),
  ('en.sahih', 17, 86, 'And if We willed, We could surely do away with that which We revealed to you. Then you would not find for yourself concerning it an advocate against Us.'),
  ('en.sahih', 17, 87, 'Except [We have left it with you] as a mercy from your Lord. Indeed, His favor upon you has ever been great.'),
  ('en.sahih', 17, 88, 'Say, "If mankind and the jinn gathered in order to produce the like of this Qur\'an, they could not produce the like of it, even if they were to each other assistants."'),
  ('en.sahih', 17, 89, 'And We have certainly diversified for the people in this Qur\'an from every [kind] of example, but most of the people refused [anything] except disbelief.'),
  ('en.sahih', 17, 90, 'And they say, "We will not believe you until you break open for us from the ground a spring.'),
  ('en.sahih', 17, 91, 'Or [until] you have a garden of palm tress and grapes and make rivers gush forth within them in force [and abundance]'),
  ('en.sahih', 17, 92, 'Or you make the heaven fall upon us in fragments as you have claimed or you bring Allah and the angels before [us]'),
  ('en.sahih', 17, 93, 'Or you have a house of gold or you ascend into the sky. And [even then], we will not believe in your ascension until you bring down to us a book we may read." Say, "Exalted is my Lord! Was I ever but a human messenger?"'),
  ('en.sahih', 17, 94, 'And what prevented the people from believing when guidance came to them except that they said, "Has Allah sent a human messenger?"'),
  ('en.sahih', 17, 95, 'Say, "If there were upon the earth angels walking securely, We would have sent down to them from the heaven an angel [as a] messenger."'),
  ('en.sahih', 17, 96, 'Say, "Sufficient is Allah as Witness between me and you. Indeed he is ever, concerning His servants, Acquainted and Seeing."'),
  ('en.sahih', 17, 97, 'And whoever Allah guides - he is the [rightly] guided; and whoever He sends astray - you will never find for them protectors besides Him, and We will gather them on the Day of Resurrection [fallen] on their faces - blind, dumb and deaf. Their refuge is Hell; every time it subsides We increase them in blazing fire.'),
  ('en.sahih', 17, 98, 'That is their recompense because they disbelieved in Our verses and said, "When we are bones and crumbled particles, will we [truly] be resurrected [in] a new creation?"'),
  ('en.sahih', 17, 99, 'Do they not see that Allah, who created the heavens and earth, is [the one] Able to create the likes of them? And He has appointed for them a term, about which there is no doubt. But the wrongdoers refuse [anything] except disbelief.'),
  ('en.sahih', 17, 100, 'Say [to them], "If you possessed the depositories of the mercy of my Lord, then you would withhold out of fear of spending." And ever has man been stingy.'),
  ('en.sahih', 17, 101, 'And We had certainly given Moses nine evident signs, so ask the Children of Israel [about] when he came to them and Pharaoh said to him, "Indeed I think, O Moses, that you are affected by magic."'),
  ('en.sahih', 17, 102, '[Moses] said, "You have already known that none has sent down these [signs] except the Lord of the heavens and the earth as evidence, and indeed I think, O Pharaoh, that you are destroyed."'),
  ('en.sahih', 17, 103, 'So he intended to drive them from the land, but We drowned him and those with him all together.'),
  ('en.sahih', 17, 104, 'And We said after Pharaoh to the Children of Israel, "Dwell in the land, and when there comes the promise of the Hereafter, We will bring you forth in [one] gathering."'),
  ('en.sahih', 17, 105, 'And with the truth We have sent the Qur\'an down, and with the truth it has descended. And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner.'),
  ('en.sahih', 17, 106, 'And [it is] a Qur\'an which We have separated [by intervals] that you might recite it to the people over a prolonged period. And We have sent it down progressively.'),
  ('en.sahih', 17, 107, 'Say, "Believe in it or do not believe. Indeed, those who were given knowledge before it - when it is recited to them, they fall upon their faces in prostration,'),
  ('en.sahih', 17, 108, 'And they say, "Exalted is our Lord! Indeed, the promise of our Lord has been fulfilled."'),
  ('en.sahih', 17, 109, 'And they fall upon their faces weeping, and the Qur\'an increases them in humble submission.'),
  ('en.sahih', 17, 110, 'Say, "Call upon Allah or call upon the Most Merciful. Whichever [name] you call - to Him belong the best names." And do not recite [too] loudly in your prayer or [too] quietly but seek between that an [intermediate] way.'),
  ('en.sahih', 17, 111, 'And say, "Praise to Allah, who has not taken a son and has had no partner in [His] dominion and has no [need of a] protector out of weakness; and glorify Him with [great] glorification."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 17, 1, 'পরম পবিত্র ও মহিমাময় সত্তা তিনি, যিনি স্বীয় বান্দাকে রাত্রি বেলায় ভ্রমণ করিয়েছিলেন মসজিদে হারাম থেকে মসজিদে আকসা পর্যান্ত-যার চার দিকে আমি পর্যাপ্ত বরকত দান করেছি যাতে আমি তাঁকে কুদরতের কিছু নিদর্শন দেখিয়ে দেই। নিশ্চয়ই তিনি পরম শ্রবণকারী ও দর্শনশীল।'),
  ('bn.bengali', 17, 2, 'আমি মূসাকে কিতাব দিয়েছি এবং সেটিকে বনী-ইসরাঈলের জন্যে হেদায়েতে পরিণত করেছি যে, তোমরা আমাকে ছাড়া কাউকে কার্যনিবাহী স্থির করো না।'),
  ('bn.bengali', 17, 3, 'তোমরা তাদের সন্তান, যাদেরকে আমি নূহের সাথে সওয়ার করিয়েছিলাম। নিশ্চয় সে ছিল কৃতজ্ঞ বান্দা।'),
  ('bn.bengali', 17, 4, 'আমি বনী ইসরাঈলকে কিতাবে পরিষ্কার বলে দিয়েছি যে, তোমরা পৃথিবীর বুকে দুবার অনর্থ সৃষ্টি করবে এবং অত্যন্ত বড় ধরনের অবাধ্যতায় লিপ্ত হবে।'),
  ('bn.bengali', 17, 5, 'অতঃপর যখন প্রতিশ্রুতি সেই প্রথম সময়টি এল, তখন আমি তোমাদের বিরুদ্ধে প্রেরণ করলাম আমার কঠোর যোদ্ধা বান্দাদেরকে। অতঃপর তারা প্রতিটি জনপদের আনাচে-কানাচে পর্যন্ত ছড়িয়ে পড়ল। এ ওয়াদা পূর্ণ হওয়ারই ছিল।'),
  ('bn.bengali', 17, 6, 'অতঃপর আমি তোমাদের জন্যে তাদের বিরুদ্ধে পালা ঘুয়িয়ে দিলাম, তোমাদেরকে ধন-সম্পদ ও পুত্রসন্তান দ্বারা সাহায্য করলাম এবং তোমাদেরকে জনসংখ্যার দিক দিয়ে একটা বিরাট বাহিনীতে পরিণত করলাম।'),
  ('bn.bengali', 17, 7, 'তোমরা যদি ভাল কর, তবে নিজেদেরই ভাল করবে এবং যদি মন্দ কর তবে তাও নিজেদের জন্যেই। এরপর যখন দ্বিতীয় সে সময়টি এল, তখন অন্য বান্দাদেরকে প্রেরণ করলাম, যাতে তোমাদের মুখমন্ডল বিকৃত করে দেয়, আর মসজিদে ঢুকে পড়ে যেমন প্রথমবার ঢুকেছিল এবং যেখানেই জয়ী হয়, সেখানেই পুরোপুরি ধ্বংসযজ্ঞ চালায়।'),
  ('bn.bengali', 17, 8, 'হয়ত তোমাদের পালনকর্তা তোমাদের প্রতি অনুগ্রহ করবেন। কিন্তু যদি পুনরায় তদ্রূপ কর, আমিও পুনরায় তাই করব। আমি জাহান্নামকে কাফেরদের জন্যে কয়েদখানা করেছি।'),
  ('bn.bengali', 17, 9, 'এই কোরআন এমন পথ প্রদর্শন করে, যা সর্বাধিক সরল এবং সৎকর্ম পরায়ণ মুমিনদেরকে সুসংবাদ দেয় যে, তাদের জন্যে মহা পুরস্কার রয়েছে।'),
  ('bn.bengali', 17, 10, 'এবং যারা পরকালে বিশ্বাস করে না, আমি তাদের জন্যে যন্ত্রণাদায়ক শাস্তি প্রস্তুত করেছি।'),
  ('bn.bengali', 17, 11, 'মানুষ যেভাবে কল্যাণ কামনা করে, সেভাবেই অকল্যাণ কামনা করে। মানুষ তো খুবই দ্রুততা প্রিয়।'),
  ('bn.bengali', 17, 12, 'আমি রাত্রি ও দিনকে দুটি নিদর্শন করেছি। অতঃপর নিস্প্রভ করে দিয়েছি রাতের নিদর্শন এবং দিনের নিদর্শনকে দেখার উপযোগী করেছি, যাতে তোমরা তোমাদের পালনকর্তার অনুগ্রহ অন্বেষণ কর এবং যাতে তোমরা স্থির করতে পার বছরসমূহের গণনা ও হিসাব এবং আমি সব বিষয়কে বিস্তারিত ভাবে বর্ণনা করেছি।'),
  ('bn.bengali', 17, 13, 'আমি প্রত্যেক মানুষের কর্মকে তার গ্রীবলগ্ন করে রেখেছি। কেয়ামতের দিন বের করে দেখাব তাকে একটি কিতাব, যা সে খোলা অবস্থায় পাবে।'),
  ('bn.bengali', 17, 14, 'পাঠ কর তুমি তোমার কিতাব। আজ তোমার হিসাব গ্রহণের জন্যে তুমিই যথেষ্ট।'),
  ('bn.bengali', 17, 15, 'যে কেউ সৎপথে চলে, তারা নিজের মঙ্গলের জন্যেই সৎ পথে চলে। আর যে পথভ্রষ্ট হয়, তারা নিজের অমঙ্গলের জন্যেই পথ ভ্রষ্ট হয়। কেউ অপরের বোঝা বহন করবে না। কোন রাসূল না পাঠানো পর্যন্ত আমি কাউকেই শাস্তি দান করি না।'),
  ('bn.bengali', 17, 16, 'যখন আমি কোন জনপদকে ধ্বংস করার ইচ্ছা করি তখন তার অবস্থাপন্ন লোকদেরকে উদ্ধুদ্ধ করি অতঃপর তারা পাপাচারে মেতে উঠে। তখন সে জনগোষ্টীর উপর আদেশ অবধারিত হয়ে যায়। অতঃপর আমি তাকে উঠিয়ে আছাড় দেই।'),
  ('bn.bengali', 17, 17, 'নূহের পর আমি অনেক উম্মতকে ধ্বংস করেছি। আপনার পালনকর্তাই বান্দাদের পাপাচারের সংবাদ জানা ও দেখার জন্যে যথেষ্ট।'),
  ('bn.bengali', 17, 18, 'যে কেউ ইহকাল কামনা করে, আমি সেসব লোককে যা ইচ্ছা সত্ত্বর দিয়ে দেই। অতঃপর তাদের জন্যে জাহান্নাম নির্ধারণ করি। ওরা তাতে নিন্দিত-বিতাড়িত অবস্থায় প্রবেশ করবে।'),
  ('bn.bengali', 17, 19, 'আর যারা পরকাল কামনা করে এবং মুমিন অবস্থায় তার জন্য যথাযথ চেষ্টা-সাধনা করে, এমন লোকদের চেষ্টা স্বীকৃত হয়ে থাকে।'),
  ('bn.bengali', 17, 20, 'এদেরকে এবং ওদেরকে প্রত্যেককে আমি আপনার পালনকর্তার দান পৌছে দেই এবং আপনার পালকর্তার দান অবধারিত।'),
  ('bn.bengali', 17, 21, 'দেখুন, আমি তাদের একদলকে অপরের উপর কিভাবে শ্রেষ্ঠত্ব দান করলাম। পরকাল তো নিশ্চয়ই মর্তবায় শ্রেষ্ঠ এবং ফযীলতে শ্রেষ্ঠতম।'),
  ('bn.bengali', 17, 22, 'স্থির করো না আল্লাহর সাথে অন্য কোন উপাস্য। তাহলে তুমি নিন্দিত ও অসহায় হয়ে পড়বে।'),
  ('bn.bengali', 17, 23, 'তোমার পালনকর্তা আদেশ করেছেন যে, তাঁকে ছাড়া অন্য কারও এবাদত করো না এবং পিতা-মাতার সাথে সদ্ব-ব্যবহার কর। তাদের মধ্যে কেউ অথবা উভয়েই যদি তোমার জীবদ্দশায় বার্ধক্যে উপনীত হয়; তবে তাদেরকে ‘উহ’ শব্দটিও বলো না এবং তাদেরকে ধমক দিও না এবং বল তাদেরকে শিষ্ঠাচারপূর্ণ কথা।'),
  ('bn.bengali', 17, 24, 'তাদের সামনে ভালবাসার সাথে, নম্রভাবে মাথা নত করে দাও এবং বলঃ হে পালনকর্তা, তাদের উভয়ের প্রতি রহম কর, যেমন তারা আমাকে শৈশবকালে লালন-পালন করেছেন।'),
  ('bn.bengali', 17, 25, 'তোমাদের পালনকর্তা তোমাদের মনে যা আছে তা ভালই জানেন। যদি তোমরা সৎ হও, তবে তিনি তওবাকারীদের জন্যে ক্ষমাশীল।'),
  ('bn.bengali', 17, 26, 'আত্নীয়-স্বজনকে তার হক দান কর এবং অভাবগ্রস্ত ও মুসাফিরকেও। এবং কিছুতেই অপব্যয় করো না।'),
  ('bn.bengali', 17, 27, 'নিশ্চয় অপব্যয়কারীরা শয়তানের ভাই। শয়তান স্বীয় পালনকর্তার প্রতি অতিশয় অকৃতজ্ঞ।'),
  ('bn.bengali', 17, 28, 'এবং তোমার পালনকর্তার করুণার প্রত্যাশায় অপেক্ষামান থাকাকালে যদি কোন সময় তাদেরকে বিমুখ করতে হয়, তখন তাদের সাথে নম্রভাবে কথা বল।'),
  ('bn.bengali', 17, 29, 'তুমি একেবারে ব্যয়-কুষ্ঠ হয়োনা এবং একেবারে মুক্ত হস্তও হয়ো না। তাহলে তুমি তিরস্কৃতি, নিঃস্ব হয়ে বসে থাকবে।'),
  ('bn.bengali', 17, 30, 'নিশ্চয় তোমার পালকর্তা যাকে ইচ্ছা অধিক জীবনোপকরণ দান করেন এবং তিনিই তা সংকুচিতও করে দেন। তিনিই তাঁর বান্দাদের সম্পর্কে ভালোভাবে অবহিত,-সব কিছু দেখছেন।'),
  ('bn.bengali', 17, 31, 'দারিদ্রের ভয়ে তোমাদের সন্তানদেরকে হত্যা করো না। তাদেরকে এবং তোমাদেরকে আমিই জীবনোপকরণ দিয়ে থাকি। নিশ্চয় তাদেরকে হত্যা করা মারাত্নক অপরাধ।'),
  ('bn.bengali', 17, 32, 'আর ব্যভিচারের কাছেও যেয়ো না। নিশ্চয় এটা অশ্লীল কাজ এবং মন্দ পথ।'),
  ('bn.bengali', 17, 33, 'সে প্রাণকে হত্যা করো না, যাকে আল্লাহ হারাম করেছেন; কিন্তু ন্যায়ভাবে। যে ব্যক্তি অন্যায়ভাবে নিহত হয়, আমি তার উত্তরাধিকারীকে ক্ষমতা দান করি। অতএব, সে যেন হত্যার ব্যাপারে সীমা লঙ্ঘন না করে। নিশ্চয় সে সাহায্যপ্রাপ্ত।'),
  ('bn.bengali', 17, 34, 'আর, এতিমের মালের কাছেও যেয়ো না, একমাত্র তার কল্যাণ আকাংখা ছাড়া; সংশ্লিষ্ট ব্যক্তির যৌবনে পদার্পন করা পর্যন্ত এবং অঙ্গীকার পূর্ন কর। নিশ্চয় অঙ্গীকার সম্পর্কে জিজ্ঞাসাবাদ করা হবে।'),
  ('bn.bengali', 17, 35, 'মেপে দেয়ার সময় পূর্ণ মাপে দেবে এবং সঠিক দাঁড়িপালায় ওজন করবে। এটা উত্তম; এর পরিণাম শুভ।'),
  ('bn.bengali', 17, 36, 'যে বিষয়ে তোমার কোন জ্ঞান নেই, তার পিছনে পড়ো না। নিশ্চয় কান, চক্ষু ও অন্তঃকরণ এদের প্রত্যেকটিই জিজ্ঞাসিত হবে।'),
  ('bn.bengali', 17, 37, 'পৃথিবীতে দম্ভভরে পদচারণা করো না। নিশ্চয় তুমি তো ভূ পৃষ্ঠকে কখনই বিদীর্ণ করতে পারবে না এবং উচ্চতায় তুমি কখনই পর্বত প্রমাণ হতে পারবে না।'),
  ('bn.bengali', 17, 38, 'এ সবের মধ্যে যেগুলো মন্দকাজ, সেগুলো তোমার পালনকর্তার কাছে অপছন্দনীয়।'),
  ('bn.bengali', 17, 39, 'এটা ঐ হিকমতের অন্তর্ভূক্ত, যা আপনার পালনকর্তা আপনাকে ওহী মারফত দান করেছেন। আল্লাহর সাথে অন্য কোন উপাস্য স্থির করবেন না। তাহলে অভিযুক্ত ও আল্লাহর অনুগ্রহ থেকে বিতাড়িত অবস্থায় জাহান্নামে নিক্ষিপ্ত হবেন।'),
  ('bn.bengali', 17, 40, 'তোমাদের পালনকর্তা কি তোমাদের জন্যে পুত্র সন্তান নির্ধারিত করেছেন এবং নিজের জন্যে ফেরেশতাদেরকে কন্যারূপে গ্রহণ করেছেন? নিশ্চয় তোমরা গুরুতর গর্হিত কথাবার্তা বলছ।'),
  ('bn.bengali', 17, 41, 'আমি এই কোরআনে নানাভাবে বুঝিয়েছি, যাতে তারা চিন্তা করে। অথচ এতে তাদের কেবল বিমুখতাই বৃদ্ধি পায়।'),
  ('bn.bengali', 17, 42, 'বলুনঃ তাদের কথামত যদি তাঁর সাথে অন্যান্য উপাস্য থাকত; তবে তারা আরশের মালিক পর্যন্ত পৌছার পথ অন্বেষন করত।'),
  ('bn.bengali', 17, 43, 'তিনি নেহায়েত পবিত্র ও মহিমান্বিত এবং তারা যা বলে থাকে তা থেকে বহু উর্ধ্বে।'),
  ('bn.bengali', 17, 44, 'সপ্ত আকাশ ও পৃথিবী এবং এগুলোর মধ্যে যাকিছু আছে সমস্ত কিছু তাঁরই পবিত্রতা ও মহিমা ঘোষণা করে। এবং এমন কিছু নেই যা তার সপ্রশংস পবিত্রতা ও মহিমা ঘোষনা করে না। কিন্তু তাদের পবিত্রতা, মহিমা ঘোষণা তোমরা অনুধাবন করতে পার না। নিশ্চয় তিনি অতি সহনশীল, ক্ষমাপরায়ণ।'),
  ('bn.bengali', 17, 45, 'যখন আপনি কোরআন পাঠ করেন, তখন আমি আপনার মধ্যে ও পরকালে অবিশ্বাসীদের মধ্যে প্রচ্ছন্ন পর্দা ফেলে দেই।'),
  ('bn.bengali', 17, 46, 'আমি তাদের অন্তরের উপর আবরণ রেখে দেই, যাতে তারা একে উপলব্ধি করতে না পারে এবং তাদের কর্ণকুহরে বোঝা চাপিয়ে দেই। যখন আপনি কোরআনে পালনকর্তার একত্ব আবৃত্তি করেন, তখন ও অনীহাবশতঃ ওরা পৃষ্ট প্রদর্শন করে চলে যায়।'),
  ('bn.bengali', 17, 47, 'যখন তারা কান পেতে আপনার কথা শোনে, তখন তারা কেন কান পেতে তা শোনে, তা আমি ভাল জানি এবং এও জানি গোপনে আলোচনাকালে যখন জালেমরা বলে, তোমরা তো এক যাদুগ্রস্থ ব্যক্তির অনুসরণ করছ।'),
  ('bn.bengali', 17, 48, 'দেখুন, ওরা আপনার জন্যে কেমন উপমা দেয়। ওরা পথভ্রষ্ট হয়েছে। অতএব, ওরা পথ পেতে পারে না।'),
  ('bn.bengali', 17, 49, 'তারা বলেঃ যখন আমরা অস্থিতে পরিণত ও চূর্ণ বিচূর্ণ হয়ে যাব, তখনও কি নতুন করে সৃজিত হয়ে উত্থিত হব?'),
  ('bn.bengali', 17, 50, 'বলুনঃ তোমরা পাথর হয়ে যাও কিংবা লোহা।'),
  ('bn.bengali', 17, 51, 'অথবা এমন কোন বস্তু, যা তোমাদের ধারণায় খুবই কঠিন; তথাপি তারা বলবেঃ আমাদের কে পুর্নবার কে সৃষ্টি করবে। বলুনঃ যিনি তোমাদেরকে প্রথমবার সৃজন করেছেন। অতঃপর তারা আপনার সামনে মাথা নাড়বে এবং বলবেঃ এটা কবে হবে? বলুনঃ হবে, সম্ভবতঃ শ্রীঘ্রই।'),
  ('bn.bengali', 17, 52, 'যেদিন তিনি তোমাদেরকে আহবান করবেন, অতঃপর তোমরা তাঁর প্রশংসা করতে করতে চলে আসবে। এবং তোমরা অনুমান করবে যে, সামান্য সময়ই অবস্থান করেছিলে।'),
  ('bn.bengali', 17, 53, 'আমার বান্দাদেরকে বলে দিন, তারা যেন যা উত্তম এমন কথাই বলে। শয়তান তাদের মধ্যে সংঘর্ষ বাধায়। নিশ্চয় শয়তান মানুষের প্রকাশ্য শত্রু।'),
  ('bn.bengali', 17, 54, 'তোমাদের পালনকর্তা তোমাদের সম্পর্কে ভালভাবে জ্ঞাত আছেন। তিনি যদি চান, তোমাদের প্রতি রহমত করবেন কিংবা যদি চান, তোমাদের আযাব দিবেন। আমি আপনাকে ওদের সবার তত্ত্বাবধায়ক রূপে প্রেরণ করিনি।'),
  ('bn.bengali', 17, 55, 'আপনার পালনকর্তা তাদের সম্পর্কে ভালভাবে জ্ঞাত আছেন, যারা আকাশসমূহে ও ভুপৃষ্ঠে রয়েছে। আমি তো কতক পয়গম্বরকে কতক পয়গম্বরের উপর শ্রেষ্ঠত্ব দান করেছি এবং দাউদকে যবুর দান করেছি।'),
  ('bn.bengali', 17, 56, 'বলুনঃ আল্লাহ ব্যতীত যাদেরকে তোমরা উপাস্য মনে কর, তাদেরকে আহবান কর। অথচ ওরা তো তোমাদের কষ্ট দুর করার ক্ষমতা রাখে না এবং তা পরিবর্তনও করতে পারে না।'),
  ('bn.bengali', 17, 57, 'যাদেরকে তারা আহবান করে, তারা নিজেরাই তো তাদের পালনকর্তার নৈকট্য লাভের জন্য মধ্যস্থ তালাশ করে যে, তাদের মধ্যে কে নৈকট্যশীল। তারা তাঁর রহমতের আশা করে এবং তাঁর শাস্তিকে ভয় করে। নিশ্চয় আপনার পালনকর্তার শাস্তি ভয়াবহ।'),
  ('bn.bengali', 17, 58, 'এমন কোন জনপদ নেই, যাকে আমি কেয়ামত দিবসের পূর্বে ধ্বংস করব না অথবা যাকে কঠোর শাস্তি দেব না। এটা তো গ্রন্থে লিপিবদ্ধ হয়ে গেছে।'),
  ('bn.bengali', 17, 59, 'পূর্ববর্তীগণ কতৃꦣ2453; নিদর্শন অস্বীকার করার ফলেই আমাকে নিদর্শনাবলী প্রেরণ থেকে বিরত থাকতে হয়েছে। আমি তাদেরকে বোঝাবার জন্যে সামুদকে উষ্ট্রী দিয়েছিলাম। অতঃপর তারা তার প্রতি জুলুম করেছিল। আমি ভীতি প্রদর্শনের উদ্দেশেই নিদর্শন প্রেরণ করি।'),
  ('bn.bengali', 17, 60, 'এবং স্মরণ করুন, আমি আপনাকে বলে দিয়েছিলাম যে, আপনার পালনকর্তা মানুষকে পরিবেষ্টন করে রেখেছেন এবং যে দৃশ্য আমি আপনাকে দেখিয়েছি তাও কোরআনে উল্লেখিত অভিশপ্ত বৃক্ষ কেবল মানুষের পরীক্ষার জন্যে। আমি তাদেরকে ভয় প্রদর্শন করি। কিন্তু এতে তাদের অবাধ্যতাই আরও বৃদ্ধি পায়।'),
  ('bn.bengali', 17, 61, 'স্মরণ কর, যখন আমি ফেরেশতাদেরকে বললামঃ আদমকে সেজদা কর, তখন ইবলীস ব্যতীত সবাই সেজদায় পড়ে গেল। কিন্তু সে বললঃ আমি কি এমন ব্যক্তিকে সেজদা করব, যাকে আপনি মাটির দ্বারা সৃষ্টি করেছেন?'),
  ('bn.bengali', 17, 62, 'সে বললঃ দেখুন তো, এনা সে ব্যক্তি, যাকে আপনি আমার চাইতেও উচ্চ মার্যাদা দিয়ে দিয়েছেন। যদি আপনি আমাকে কেয়ামত দিবস পর্যন্ত সময় দেন, তবে আমি সামান্য সংখ্যক ছাড়া তার বংশধরদেরকে সমূলে নষ্ট করে দেব।'),
  ('bn.bengali', 17, 63, 'আল্লাহ বলেনঃ চলে যা, অতঃপর তাদের মধ্য থেকে যে তোর অনুগামী হবে, জাহান্নামই হবে তাদের সবার শাস্তি-ভরপুর শাস্তি।'),
  ('bn.bengali', 17, 64, 'তুই সত্যচ্যুত করে তাদের মধ্য থেকে যাকে পারিস স্বীয় আওয়ায দ্বারা, স্বীয় অশ্বারোহী ও পদাতিক বাহিনী নিয়ে তাদেরকে আক্রমণ কর, তাদের অর্থ-সম্পদ ও সন্তান-সন্ততিতে শরীক হয়ে যা এবং তাদেরকে প্রতিশ্রুতি দে। ছলনা ছাড়া শয়তান তাদেরকে কোন প্রতিশ্রুতি দেয় না।'),
  ('bn.bengali', 17, 65, 'আমার বান্দাদের উপর তোর কোন ক্ষমতা নেই আপনার পালনকর্তা যথেষ্ট কার্যনির্বাহী।'),
  ('bn.bengali', 17, 66, 'তোমাদের পালনকর্তা তিনিই, যিনি তোমাদের জন্যে সমুদ্রে জলযান চালনা করেন, যাতে তোমরা তার অনুগ্রহ অন্বেষন করতে পারো। নিঃ সন্দেহে তিনি তোমাদের প্রতি পরম দয়ালূ।'),
  ('bn.bengali', 17, 67, 'যখন সমুদ্রে তোমাদের উপর বিপদ আসে, তখন শুধু আল্লাহ ব্যতীত যাদেরকে তোমরা আহবান করে থাক তাদেরকে তোমরা বিস্মৃত হয়ে যাও। অতঃপর তিনি যখন তোমাদেরকে স্থলে ভিড়িয়ে উদ্ধার করে নেন, তখন তোমরা মুখ ফিরিয়ে নাও। মানুষ বড়ই অকৃতজ্ঞ।'),
  ('bn.bengali', 17, 68, 'তোমরা কি এ বিষয়ে নিশ্চিন্ত রয়েছ যে, তিনি তোমাদেরকে স্থলভাগে কোথাও ভূগর্ভস্থ করবেন না। অথবা তোমাদের উপর প্রস্তর বর্ষণকারী ঘুর্ণিঝড় প্রেরণ করবেন না, তখন তোমরা নিজেদের জন্যে কোন কর্মবিধায়ক পাবে না।'),
  ('bn.bengali', 17, 69, 'অথবা তোমরা কি এ বিষয়ে নিশ্চিন্ত যে, তিনি তোমাদেরকে আরেকবার সমুদ্রে নিয়ে যাবেন না, অতঃপর তোমাদের জন্যে মহা ঝটিকা প্রেরণ করবেন না, অতঃপর অকৃতজ্ঞতার শাস্তিস্বরূপ তোমাদেরকে নিমজ্জত করবেন না, তখন তোমরা আমার বিরুদ্ধে এ বিষয়ে সাহায্যকারী কাউকে পাবে না।'),
  ('bn.bengali', 17, 70, 'নিশ্চয় আমি আদম সন্তানকে মর্যাদা দান করেছি, আমি তাদেরকে স্থলে ও জলে চলাচলের বাহন দান করেছি; তাদেরকে উত্তম জীবনোপকরণ প্রদান করেছি এবং তাদেরকে অনেক সৃষ্ট বস্তুর উপর শ্রেষ্ঠত্ব দান করেছি।'),
  ('bn.bengali', 17, 71, 'স্মরণ কর, যেদিন আমি প্রত্যেক দলকে তাদের নেতাসহ আহবান করব, অতঃপর যাদেরকে তাদের ডান হাতে আমলনামা দেয়া হবে, তারা নিজেদের আমলনামা পাঠ করবে এবং তাদের প্রতি সামান্য পরিমাণও জুলুম হবে না।'),
  ('bn.bengali', 17, 72, 'যে ব্যক্তি ইহকালে অন্ধ ছিল সে পরকালেও অন্ধ এবং অধিকতর পথভ্রান্ত।'),
  ('bn.bengali', 17, 73, 'তারা তো আপনাকে হটিয়ে দিতে চাচ্ছিল যে বিষয় আমি আপনার প্রতি ওহীর মাধ্যমে যা প্রেরণ করেছি তা থেকে আপনার পদঙ্খলন ঘটানোর জন্যে তারা চুড়ান্ত চেষ্টা করেছে, যাতে আপনি আমার প্রতি কিছু মিথ্যা সম্বন্ধযুক্ত করেন। এতে সফল হলে তারা আপনাকে বন্ধুরূপে গ্রহণ করে নিত।'),
  ('bn.bengali', 17, 74, 'আমি আপনাকে দৃঢ়পদ না রাখলে আপনি তাদের প্রতি কিছুটা ঝুঁকেই পড়তেন।'),
  ('bn.bengali', 17, 75, 'তখন আমি অবশ্যই আপনাকে ইহজীবনে ও পরজীবনে দ্বিগুণ শাস্তির আস্বাদন করাতাম। এ সময় আপনি আমার মোকাবিলায় কোন সাহায্যকারী পেতেন না।'),
  ('bn.bengali', 17, 76, 'তারা তো আপনাকে এ ভুখন্ড থেকে উৎখাত করে দিতে চুড়ান্ত চেষ্টা করেছিল যাতে আপনাকে এখান থেকে বহিস্কার করে দেয়া যায়। তখন তারাও আপনার পর সেখানে অল্প কালই মাত্র টিকে থাকত।'),
  ('bn.bengali', 17, 77, 'আপনার পূর্বে আমি যত রসূল প্রেরণ করেছি, তাদের ক্ষেত্রেও এরূপ নিয়ম ছিল। আপনি আমার নিয়মের কোন ব্যতিক্রম পাবেন না।'),
  ('bn.bengali', 17, 78, 'সূর্য ঢলে পড়ার সময় থেকে রাত্রির অন্ধকার পর্যন্ত নামায কায়েম করুন এবং ফজরের কোরআন পাঠও। নিশ্চয় ফজরের কোরআন পাঠ মুখোমুখি হয়।'),
  ('bn.bengali', 17, 79, 'রাত্রির কিছু অংশ কোরআন পাঠ সহ জাগ্রত থাকুন। এটা আপনার জন্যে অতিরিক্ত। হয়ত বা আপনার পালনকর্তা আপনাকে মোকামে মাহমুদে পৌঁছাবেন।'),
  ('bn.bengali', 17, 80, 'বলুনঃ হে পালনকর্তা! আমাকে দাখিল করুন সত্যরূপে এবং আমাকে বের করুন সত্যরূপে এবং দান করুন আমাকে নিজের কাছ থেকে রাষ্ট্রীয় সাহায্য।'),
  ('bn.bengali', 17, 81, 'বলুনঃ সত্য এসেছে এবং মিথ্যা বিলুপ্ত হয়েছে। নিশ্চয় মিথ্যা বিলুপ্ত হওয়ারই ছিল।'),
  ('bn.bengali', 17, 82, 'আমি কোরআনে এমন বিষয় নাযিল করি যা রোগের সুচিকিৎসা এবং মুমিনের জন্য রহমত। গোনাহগারদের তো এতে শুধু ক্ষতিই বৃদ্ধি পায়।'),
  ('bn.bengali', 17, 83, 'আমি মানুষকে নেয়ামত দান করলে সে মুখ ফিরিয়ে নেয় এবং অহংকারে দুরে সরে যায়; যখন তাকে কোন অনিষ্ট স্পর্শ করে, তখন সে একেবারে হতাশ হয়ে পড়ে।'),
  ('bn.bengali', 17, 84, 'বলুনঃ প্রত্যেকেই নিজ রীতি অনুযায়ী কাজ করে। অতঃপর আপনার পালনকর্তা বিশেষ রূপে জানেন, কে সর্বাপেক্ষা নির্ভূল পথে আছে।'),
  ('bn.bengali', 17, 85, 'তারা আপনাকে রূহ সম্পর্কে জিজ্ঞেস করে। বলে দিনঃ রূহ আমার পালনকর্তার আদেশ ঘটিত। এ বিষয়ে তোমাদেরকে সামান্য জ্ঞানই দান করা হয়েছে।'),
  ('bn.bengali', 17, 86, 'আমি ইচ্ছা করলে আপনার কাছে ওহীর মাধমে যা প্রেরণ করেছি তা অবশ্যই প্রত্যাহার করতে পারতাম। অতঃপর আপনি নিজের জন্যে তা আনয়নের ব্যাপারে আমার মোকাবিলায় কোন দায়িত্ব বহনকারী পাবেন না।'),
  ('bn.bengali', 17, 87, 'এ প্রত্যাহার না করা আপনার পালনকর্তার মেহেরবানী। নিশ্চয় আপনার প্রতি তাঁর করুণা বিরাট।'),
  ('bn.bengali', 17, 88, 'বলুনঃ যদি মানব ও জ্বিন এই কোরআনের অনুরূপ রচনা করে আনয়নের জন্যে জড়ো হয়, এবং তারা পরস্পরের সাহায্যকারী হয়; তবুও তারা কখনও এর অনুরূপ রচনা করে আনতে পারবে না।'),
  ('bn.bengali', 17, 89, 'আমি এই কোরআনে মানুষকে বিভিন্ন উপকার দ্বারা সব রকম বিষয়বস্তু বুঝিয়েছি। কিন্তু অধিকাংশ লোক অস্বীকার না করে থাকেনি।'),
  ('bn.bengali', 17, 90, 'এবং তারা বলেঃ আমরা কখনও আপনাকে বিশ্বাস করব না, যে পর্যন্ত না আপনি ভূপৃষ্ঠ থেকে আমাদের জন্যে একটি ঝরণা প্রবাহিত করে দিন।'),
  ('bn.bengali', 17, 91, 'অথবা আপনার জন্যে খেজুরের ও আঙ্গুরের একটি বাগান হবে, অতঃপর আপনি তার মধ্যে নির্ঝরিনীসমূহ প্রবাহিত করে দেবেন।'),
  ('bn.bengali', 17, 92, 'অথবা আপনি যেমন বলে থাকেন, তেমনিভাবে আমাদের উপর আসমানকে খন্ড-বিখন্ড করে ফেলে দেবেন অথবা আল্লাহ ও ফেরেশতাদেরকে আমাদের সামনে নিয়ে আসবেন।'),
  ('bn.bengali', 17, 93, 'অথবা আপনার কোন সোনার তৈরী গৃহ হবে অথবা আপনি আকাশে আরোহণ করবেন এবং আমরা আপনার আকাশে আরোহণকে কখনও বিশ্বাস করবনা, যে পর্যন্ত না আপনি অবতীর্ণ করেন আমাদের প্রতি এক গ্রন্থ, যা আমরা পাঠ করব। বলুনঃ পবিত্র মহান আমার পালনকর্তা, একজন মানব, একজন রসূল বৈ আমি কে?'),
  ('bn.bengali', 17, 94, 'আল্লাহ কি মানুষকে পয়গম্বর করে পাঠিয়েছেন? তাদের এই উক্তিই মানুষকে ঈমান আনয়ন থেকে বিরত রাখে, যখন তাদের নিকট আসে হেদায়েত।'),
  ('bn.bengali', 17, 95, 'বলুনঃ যদি পৃথিবীতে ফেরেশতারা স্বচ্ছন্দে বিচরণ করত, তবে আমি আকাশ থেকে কোন ফেরেশতাকেই তাদের নিকট পয়গাম্বর করে প্রেরণ করতাম।'),
  ('bn.bengali', 17, 96, 'বলুনঃ আমার ও তোমাদের মধ্যে সত্য প্রতিষ্ঠাকারী হিসেবে আল্লাহই যথেষ্ট। তিনি তো স্বীয় বান্দাদের বিষয়ে খবর রাখেন ও দেখেন।'),
  ('bn.bengali', 17, 97, 'আল্লাহ যাকে পথ প্রদর্শন করেন, সেই তো সঠিক পথ প্রাপ্ত এবং যাকে পথ ভ্রষ্ট করেন, তাদের জন্যে আপনি আল্লাহ ছাড়া কোন সাহায্যকারী পাবেন না। আমি কেয়ামতের দিন তাদের সমবেত করব তাদের মুখে ভর দিয়ে চলা অবস্থায়, অন্ধ অবস্থায়, মুক অবস্থায় এবং বধির অবস্থায়। তাদের আবাসস্থল জাহান্নাম। যখনই নির্বাপিত হওয়ার উপক্রম হবে আমি তখন তাদের জন্যে অগ্নি আরও বৃদ্ধি করে দিব।'),
  ('bn.bengali', 17, 98, 'এটাই তাদের শাস্তি। কারণ, তারা আমার নিদর্শনসমূহ অস্বীকার করেছে এবং বলেছেঃ আমরা যখন অস্থিতে পরিণত ও চুর্ণ-বিচুর্ণ হয়ে যাব, তখনও কি আমরা নতুনভাবে সৃজিত হয়ে উত্থিত হব?'),
  ('bn.bengali', 17, 99, 'তারা কি দেখেনি যে, যে আল্লাহ আসমান ও যমিন সৃজিত করেছেন, তিনি তাদের মত মানুষও পুনরায় সৃষ্টি করতে সক্ষম? তিনি তাদের জন্যে স্থির করেছেন একটি নির্দিষ্ট কাল, এতে কোন সন্দেহ নেই; অতঃপর জালেমরা অস্বীকার ছাড়া কিছু করেনি।'),
  ('bn.bengali', 17, 100, 'বলুনঃ যদি আমার পালনকর্তার রহমতের ভান্ডার তোমাদের হাতে থাকত, তবে ব্যয়িত হয়ে যাওয়ার আশঙ্কায় অবশ্যই তা ধরে রাখতে। মানুষ তো অতিশয় কৃপণ।'),
  ('bn.bengali', 17, 101, 'আপনি বণী-ইসরাঈলকে জিজ্ঞেস করুন, আমি মূসাকে নয়টি প্রকাশ্য নিদর্শন দান করেছি। যখন তিনি তাদের কাছে আগমন করেন, ফেরাউন তাকে বললঃ হে মূসা, আমার ধারনায় তুমি তো জাদুগ্রস্থ।'),
  ('bn.bengali', 17, 102, 'তিনি বললেনঃ তুমি জান যে, আসমান ও যমীনের পালনকর্তাই এসব নিদর্শনাবলী প্রত্যক্ষ প্রমাণস্বরূপ নাযিল করেছেন। হে ফেরাউন, আমার ধারণায় তুমি ধ্বংস হতে চলেছো।'),
  ('bn.bengali', 17, 103, 'অতঃপর সে বনী ইসরাঈলকে দেশ থেকে উৎখাত করতে চাইল, তখন আমি তাকে ও তার সঙ্গীদের সবাইকে নিমজ্জত করে দিলাম।'),
  ('bn.bengali', 17, 104, 'তারপর আমি বনী ইসলাঈলকে বললামঃ এ দেশে তোমরা বসবাস কর। অতঃপর যখন পরকালের ওয়াদা বাস্তবায়িত হবে, তখন তোমাদের কে জড়ো করে নিয়ে উপস্থিত হব।'),
  ('bn.bengali', 17, 105, 'আমি সত্যসহ এ কোরআন নাযিল করেছি এবং সত্য সহ এটা নাযিল হয়েছে। আমি তো আপনাকে শুধু সুসংবাদাতা ও ভয়প্রদর্শক করেই প্রেরণ করেছি।'),
  ('bn.bengali', 17, 106, 'আমি কোরআনকে যতিচিহ্ন সহ পৃথক পৃথকভাবে পাঠের উপযোগী করেছি, যাতে আপনি একে লোকদের কাছে ধীরে ধীরে পাঠ করেন এবং আমি একে যথাযথ ভাবে অবতীর্ণ করেছি।'),
  ('bn.bengali', 17, 107, 'বলুনঃ তোমরা কোরআনকে মান্য কর অথবা অমান্য কর; যারা এর পূর্ব থেকে এলেম প্রাপ্ত হয়েছে, যখন তাদের কাছে এর তেলাওয়াত করা হয়, তখন তারা নতমস্তকে সেজদায় লুটিয়ে পড়ে।'),
  ('bn.bengali', 17, 108, 'এবং বলেঃ আমাদের পালনকর্তা পবিত্র, মহান। নিঃসন্দেহে আমাদের পালকর্তার ওয়াদা অবশ্যই পূর্ণ হবে।'),
  ('bn.bengali', 17, 109, 'তারা ক্রন্দন করতে করতে নতমস্তকে ভুমিতে লুটিয়ে পড়ে এবং তাদের বিনয়ভাব আরো বৃদ্ধি পায়।'),
  ('bn.bengali', 17, 110, 'বলুনঃ আল্লাহ বলে আহবান কর কিংবা রহমান বলে, যে নামেই আহবান কর না কেন, সব সুন্দর নাম তাঁরই। আপনি নিজের নামায আদায়কালে স্বর উচ্চগ্রাসে নিয়ে গিয়ে পড়বেন না এবং নিঃশব্দেও পড়বেন না। এতদুভয়ের মধ্যমপন্থা অবলম্বন করুন।'),
  ('bn.bengali', 17, 111, 'বলুনঃ সমস্ত প্রশংসা আল্লাহর যিনি না কোন সন্তান রাখেন, না তাঁর সার্বভৌমত্বে কোন শরীক আছে এবং যিনি দুর্দশাগ্রস্ত হন না, যে কারণে তাঁর কোন সাহয্যকারীর প্রয়োজন হতে পারে। সুতরাং আপনি স-সম্ভ্রমে তাঁর মাহাত্ন?2476;র্ণনা করতে থাকুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 17, 1, 'Glorified be He Who carried His servant by night from the Inviolable Place of Worship to the Far distant place of worship the neighbourhood whereof We have blessed, that We might show him of Our tokens! Lo! He, only He, is the Hearer, the Seer.'),
  ('en.pickthall', 17, 2, 'We gave unto Moses the Scripture, and We appointed it a guidance for the children of Israel, saying: Choose no guardian beside Me.'),
  ('en.pickthall', 17, 3, '(They were) the seed of those whom We carried (in the ship) along with Noah. Lo! he was a grateful slave.'),
  ('en.pickthall', 17, 4, 'And We decreed for the Children of Israel in the Scripture: Ye verily will work corruption in the earth twice, and ye will become great tyrants.'),
  ('en.pickthall', 17, 5, 'So when the time for the first of the two came, We roused against you slaves of Ours of great might who ravaged (your) country, and it was a threat performed.'),
  ('en.pickthall', 17, 6, 'Then we gave you once again your turn against them, and We aided you with wealth and children and made you more in soldiery.'),
  ('en.pickthall', 17, 7, '(Saying): If ye do good, ye do good for your own souls, and if ye do evil, it is for them (in like manner). So, when the time for the second (of the judgments) came (We roused against you others of Our slaves) to ravage you, and to enter the Temple even as they entered it the first time, and to lay waste all that they conquered with an utter wasting.'),
  ('en.pickthall', 17, 8, 'It may be that your Lord will have mercy on you, but if ye repeat (the crime) We shall repeat (the punishment), and We have appointed hell a dungeon for the disbelievers.'),
  ('en.pickthall', 17, 9, 'Lo! this Qur\'an guideth unto that which is straightest, and giveth tidings unto the believers who do good works that theirs will be a great reward.'),
  ('en.pickthall', 17, 10, 'And that those who believe not in the Hereafter, for them We have prepared a painful doom.'),
  ('en.pickthall', 17, 11, 'Man prayeth for evil as he prayeth for good; for man was ever hasty.'),
  ('en.pickthall', 17, 12, 'And We appoint the night and the day two portents. Then We make dark the portent of the night, and We make the portent of the day sight-giving, that ye may seek bounty from your Lord, and that ye may know the computation of the years, and the reckoning; and everything have We expounded with a clear expounding.'),
  ('en.pickthall', 17, 13, 'And every man\'s augury have We fastened to his own neck, and We shall bring forth for him on the Day of Resurrection a book which he will find wide open.'),
  ('en.pickthall', 17, 14, '(And it will be said unto him): Read thy Book. Thy soul sufficeth as reckoner against thee this day.'),
  ('en.pickthall', 17, 15, 'Whosoever goeth right, it is only for (the good of) his own soul that he goeth right, and whosoever erreth, erreth only to its hurt. No laden soul can bear another\'s load, We never punish until we have sent a messenger.'),
  ('en.pickthall', 17, 16, 'And when We would destroy a township We send commandment to its folk who live at ease, and afterward they commit abomination therein, and so the Word (of doom) hath effect for it, and we annihilate it with complete annihilation.'),
  ('en.pickthall', 17, 17, 'How many generations have We destroyed since Noah! And Allah sufficeth as Knower and Beholder of the sins of His slaves.'),
  ('en.pickthall', 17, 18, 'Whoso desireth that (life) which hasteneth away, We hasten for him therein what We will for whom We please. And afterward We have appointed for him hell; he will endure the heat thereof, condemned, rejected.'),
  ('en.pickthall', 17, 19, 'And whoso desireth the Hereafter and striveth for it with the effort necessary, being a believer; for such, their effort findeth favour (with their Lord).'),
  ('en.pickthall', 17, 20, 'Each do We supply, both these and those, from the bounty of thy Lord. And the bounty of thy Lord can never be walled up.'),
  ('en.pickthall', 17, 21, 'See how We prefer one of them above another, and verily the Hereafter will be greater in degrees and greater in preferment.'),
  ('en.pickthall', 17, 22, 'Set not up with Allah any other god (O man) lest thou sit down reproved, forsaken.'),
  ('en.pickthall', 17, 23, 'Thy Lord hath decreed, that ye worship none save Him, and (that ye show) kindness to parents. If one of them or both of them attain old age with thee, say not "Fie" unto them nor repulse them, but speak unto them a gracious word.'),
  ('en.pickthall', 17, 24, 'And lower unto them the wing of submission through mercy, and say: My Lord! Have mercy on them both as they did care for me when I was little.'),
  ('en.pickthall', 17, 25, 'Your Lord is Best Aware of what is in your minds. If ye are righteous, then lo! He was ever Forgiving unto those who turn (unto Him).'),
  ('en.pickthall', 17, 26, 'Give the kinsman his due, and the needy, and the wayfarer, and squander not (thy wealth) in wantonness.'),
  ('en.pickthall', 17, 27, 'Lo! the squanderers were ever brothers of the devils, and the devil was ever an ingrate to his Lord.'),
  ('en.pickthall', 17, 28, 'But if thou turn away from them, seeking mercy from thy Lord, for which thou hopest, then speak unto them a reasonable word.'),
  ('en.pickthall', 17, 29, 'And let not thy hand be chained to thy neck nor open it with a complete opening, lest thou sit down rebuked, denuded.'),
  ('en.pickthall', 17, 30, 'Lo! thy Lord enlargeth the provision for whom He will, and straiteneth (it for whom He will). Lo, He was ever Knower, Seer of His slaves.'),
  ('en.pickthall', 17, 31, 'Slay not your children, fearing a fall to poverty, We shall provide for them and for you. Lo! the slaying of them is great sin.'),
  ('en.pickthall', 17, 32, 'And come not near unto adultery. Lo! it is an abomination and an evil way.'),
  ('en.pickthall', 17, 33, 'And slay not the life which Allah hath forbidden save with right. Whoso is slain wrongfully, We have given power unto his heir, but let him not commit excess in slaying. Lo! he will be helped.'),
  ('en.pickthall', 17, 34, 'Come not near the wealth of the orphan save with that which is better till he come to strength; and keep the covenant. Lo! of the covenant it will be asked.'),
  ('en.pickthall', 17, 35, 'Fill the measure when ye measure, and weigh with a right balance; that is meet, and better in the end.'),
  ('en.pickthall', 17, 36, '(O man), follow not that whereof thou hast no knowledge. Lo! the hearing and the sight and the heart - of each of these it will be asked.'),
  ('en.pickthall', 17, 37, 'And walk not in the earth exultant. Lo! thou canst not rend the earth, nor canst thou stretch to the height of the hills.'),
  ('en.pickthall', 17, 38, 'The evil of all that is hateful in the sight of thy Lord.'),
  ('en.pickthall', 17, 39, 'This is (part) of that wisdom wherewith thy Lord hath inspired thee (O Muhammad). And set not up with Allah any other god, lest thou be cast into hell, reproved, abandoned.'),
  ('en.pickthall', 17, 40, 'Hath your Lord then distinguished you (O men of Makka) by giving you sons, and hath chosen for Himself females from among the angels? Lo! verily ye speak an awful word!'),
  ('en.pickthall', 17, 41, 'We verily have displayed (Our warnings) in this Qur\'an that they may take heed, but it increaseth them in naught save aversion.'),
  ('en.pickthall', 17, 42, 'Say (O Muhammad, to the disbelievers): If there were other gods along with Him, as they say, then had they sought a way against the Lord of the Throne.'),
  ('en.pickthall', 17, 43, 'Glorified is He, and High Exalted above what they say!'),
  ('en.pickthall', 17, 44, 'The seven heavens and the earth and all that is therein praise Him, and there is not a thing but hymneth His praise; but ye understand not their praise. Lo! He is ever Clement, Forgiving.'),
  ('en.pickthall', 17, 45, 'And when thou recitest the Qur\'an we place between thee and those who believe not in the Hereafter a hidden barrier;'),
  ('en.pickthall', 17, 46, 'And We place upon their hearts veils lest they should understand it, and in their ears a deafness; and when thou makest mention of thy Lord alone in the Qur\'an, they turn their backs in aversion.'),
  ('en.pickthall', 17, 47, 'We are Best Aware of what they wish to hear when they give ear to thee and when they take secret counsel, when the evil-doers say: Ye follow but a man bewitched.'),
  ('en.pickthall', 17, 48, 'See what similitudes they coin for thee, and thus are all astray, and cannot find a road!'),
  ('en.pickthall', 17, 49, 'And they say: When we are bones and fragments, shall we forsooth, be raised up as a new creation?'),
  ('en.pickthall', 17, 50, 'Say: Be ye stones or iron'),
  ('en.pickthall', 17, 51, 'Or some created thing that is yet greater in your thoughts! Then they will say: Who shall bring us back (to life). Say: He Who created you at the first. Then will they shake their heads at thee, and say: When will it be? Say: It will perhaps be soon;'),
  ('en.pickthall', 17, 52, 'A day when He will call you and ye will answer with His praise, and ye will think that ye have tarried but a little while.'),
  ('en.pickthall', 17, 53, 'Tell My bondmen to speak that which is kindlier. Lo! the devil soweth discord among them. Lo! the devil is for man an open foe.'),
  ('en.pickthall', 17, 54, 'Your Lord is Best Aware of you. If He will, He will have mercy on you, or if He will, He will punish you. We have not sent thee (O Muhammad) as a warden over them.'),
  ('en.pickthall', 17, 55, 'And thy Lord is Best Aware of all who are in the heavens and the earth. And we preferred some of the prophets above others, and unto David We gave the Psalms.'),
  ('en.pickthall', 17, 56, 'Say: Cry unto those (saints and angels) whom ye assume (to be gods) beside Him, yet they have no power to rid you of misfortune nor to change.'),
  ('en.pickthall', 17, 57, 'Those unto whom they cry seek the way of approach to their Lord, which of them shall be the nearest; they hope for His mercy and they fear His doom. Lo! the doom of thy Lord is to be shunned.'),
  ('en.pickthall', 17, 58, 'There is not a township but We shall destroy it ere the Day of Resurrection, or punish it with dire punishment. That is set forth in the Book (of Our decrees).'),
  ('en.pickthall', 17, 59, 'Naught hindereth Us from sending portents save that the folk of old denied them. And We gave Thamud the she-camel - a clear portent save to warn.'),
  ('en.pickthall', 17, 60, 'And (it was a warning) when we told thee: Lo! thy Lord encompasseth mankind, and We appointed the sight which We showed thee as an ordeal for mankind, and (likewise) the Accursed Tree in the Qur\'an. We warn them, but it increaseth them in naught save gross impiety.'),
  ('en.pickthall', 17, 61, 'And when We said unto the angels: Fall down prostrate before Adam and they fell prostrate all save Iblis, he said: Shall I fall prostrate before that which Thou hast created of clay?'),
  ('en.pickthall', 17, 62, 'He said: Seest Thou this (creature) whom Thou hast honoured above me, if Thou give me grace until the Day of Resurrection I verily will seize his seed, save but a few.'),
  ('en.pickthall', 17, 63, 'He said: Go, and whosoever of them followeth thee - lo! hell will be your payment, ample payment.'),
  ('en.pickthall', 17, 64, 'And excite any of them whom thou canst with thy voice, and urge thy horse and foot against them, and be a partner in their wealth and children, and promise them. Satan promiseth them only to deceive.'),
  ('en.pickthall', 17, 65, 'Lo! My (faithful) bondmen - over them thou hast no power, and thy Lord sufficeth as (their) guardian.'),
  ('en.pickthall', 17, 66, '(O mankind), your Lord is He Who driveth for you the ship upon the sea that ye may seek of His bounty. Lo! He was ever Merciful toward you.'),
  ('en.pickthall', 17, 67, 'And when harm toucheth you upon the sea, all unto whom ye cry (for succour) fail save Him (alone), but when He bringeth you safe to land, ye turn away, for man was ever thankless.'),
  ('en.pickthall', 17, 68, 'Feel ye then secure that He will not cause a slope of the land to engulf you, or send a sand-storm upon you, and then ye will find that ye have no protector?'),
  ('en.pickthall', 17, 69, 'Or feel ye secure that He will not return you to that (plight) a second time, and send against you a hurricane of wind and drown you for your thanklessness, and then ye will not find therein that ye have any avenger against Us?'),
  ('en.pickthall', 17, 70, 'Verily we have honoured the Children of Adam. We carry them on the land and the sea, and have made provision of good things for them, and have preferred them above many of those whom We created with a marked preferment.'),
  ('en.pickthall', 17, 71, 'On the day when We shall summon all men with their record, whoso is given his book in his right hand - such will read their book and they will not be wronged a shred.'),
  ('en.pickthall', 17, 72, 'Whoso is blind here will be blind in the Hereafter, and yet further from the road.'),
  ('en.pickthall', 17, 73, 'And they indeed strove hard to beguile thee (Muhammad) away from that wherewith We have inspired thee, that thou shouldst invent other than it against Us; and then would they have accepted thee as a friend.'),
  ('en.pickthall', 17, 74, 'And if We had not made thee wholly firm thou mightest almost have inclined unto them a little.'),
  ('en.pickthall', 17, 75, 'Then had we made thee taste a double (punishment) of living and a double (punishment) of dying, then hadst thou found no helper against Us.'),
  ('en.pickthall', 17, 76, 'And they indeed wished to scare thee from the land that they might drive thee forth from thence, and then they would have stayed (there) but a little after thee.'),
  ('en.pickthall', 17, 77, '(Such was Our) method in the case of those whom We sent before thee (to mankind), and thou wilt not find for Our method aught of power to change.'),
  ('en.pickthall', 17, 78, 'Establish worship at the going down of the sun until the dark of night, and (the recital of) the Qur\'an at dawn. Lo! (the recital of) the Qur\'an at dawn is ever witnessed.'),
  ('en.pickthall', 17, 79, 'And some part of the night awake for it, a largess for thee. It may be that thy Lord will raise thee to a praised estate.'),
  ('en.pickthall', 17, 80, 'And say: My Lord! Cause me to come in with a firm incoming and to go out with a firm outgoing. And give me from Thy presence a sustaining Power.'),
  ('en.pickthall', 17, 81, 'And say: Truth hath come and falsehood hath vanished away. Lo! falsehood is ever bound to vanish.'),
  ('en.pickthall', 17, 82, 'And We reveal of the Qur\'an that which is a healing and a mercy for believers though it increase the evil-doers in naught save ruin.'),
  ('en.pickthall', 17, 83, 'And when We make life pleasant unto man, he turneth away and is averse; and when ill toucheth him he is in despair.'),
  ('en.pickthall', 17, 84, 'Say: Each one doth according to his rule of conduct, and thy Lord is Best Aware of him whose way is right.'),
  ('en.pickthall', 17, 85, 'They are asking thee concerning the Spirit. Say: The Spirit is by command of my Lord, and of knowledge ye have been vouchsafed but little.'),
  ('en.pickthall', 17, 86, 'And if We willed We could withdraw that which We have revealed unto thee, then wouldst thou find no guardian for thee against Us in respect thereof.'),
  ('en.pickthall', 17, 87, '(It is naught) save mercy from thy Lord. Lo! His kindness unto thee was ever great.'),
  ('en.pickthall', 17, 88, 'Say: Verily, though mankind and the jinn should assemble to produce the like of this Qur\'an, they could not produce the like thereof though they were helpers one of another.'),
  ('en.pickthall', 17, 89, 'And verily We have displayed for mankind in this Qur\'an all kind of similitudes, but most of mankind refuse aught save disbelief.'),
  ('en.pickthall', 17, 90, 'And they say: We will not put faith in thee till thou cause a spring to gush forth from the earth for us;'),
  ('en.pickthall', 17, 91, 'Or thou have a garden of date-palms and grapes, and cause rivers to gush forth therein abundantly;'),
  ('en.pickthall', 17, 92, 'Or thou cause the heaven to fall upon us piecemeal, as thou hast pretended, or bring Allah and the angels as a warrant;'),
  ('en.pickthall', 17, 93, 'Or thou have a house of gold; or thou ascend up into heaven, and even then we will put no faith in thine ascension till thou bring down for us a book that we can read. Say (O Muhammad): My Lord be Glorified! Am I aught save a mortal messenger?'),
  ('en.pickthall', 17, 94, 'And naught prevented mankind from believing when the guidance came unto them save that they said: Hath Allah sent a mortal as (His) messenger?'),
  ('en.pickthall', 17, 95, 'Say: If there were in the earth angels walking secure, We had sent down for them from heaven an angel as messenger.'),
  ('en.pickthall', 17, 96, 'Say: Allah sufficeth for a witness between me and you. Lo! He is Knower, Seer of His slaves.'),
  ('en.pickthall', 17, 97, 'And he whom Allah guideth, he is led aright; while, as for him whom He sendeth astray, for them thou wilt find no protecting friends beside Him, and We shall assemble them on the Day of Resurrection on their faces, blind, dumb and deaf; their habitation will be hell; whenever it abateth, We increase the flame for them.'),
  ('en.pickthall', 17, 98, 'That is their reward because they disbelieved Our revelations and said: When we are bones and fragments shall we, forsooth, be raised up as a new creation?'),
  ('en.pickthall', 17, 99, 'Have they not seen that Allah Who created the heavens and the earth is Able to create the like of them, and hath appointed for them an end whereof there is no doubt? But the wrong-doers refuse aught save disbelief.'),
  ('en.pickthall', 17, 100, 'Say (unto them): If ye possessed the treasures of the mercy of my Lord, ye would surely hold them back for fear of spending, for man was ever grudging.'),
  ('en.pickthall', 17, 101, 'And verily We gave unto Moses nine tokens, clear proofs (of Allah\'s Sovereignty). Do but ask the Children of Israel how he came unto them, then Pharaoh said unto him: Lo! I deem thee one bewitched, O Moses.'),
  ('en.pickthall', 17, 102, 'He said: In truth thou knowest that none sent down these (portents) save the Lord of the heavens and the earth as proofs, and lo! (for my part) I deem thee lost, O Pharaoh.'),
  ('en.pickthall', 17, 103, 'And he wished to scare them from the land, but We drowned him and those with him, all together.'),
  ('en.pickthall', 17, 104, 'And We said unto the Children of Israel after him: Dwell in the land; but when the promise of the Hereafter cometh to pass We shall bring you as a crowd gathered out of various nations.'),
  ('en.pickthall', 17, 105, 'With truth have We sent it down, and with truth hath it descended. And We have sent thee as naught else save a bearer of good tidings and a warner.'),
  ('en.pickthall', 17, 106, 'And (it is) a Qur\'an that We have divided, that thou mayst recite it unto mankind at intervals, and We have revealed it by (successive) revelation.'),
  ('en.pickthall', 17, 107, 'Say: Believe therein or believe not, lo! those who were given knowledge before it, when it is read unto them, fall down prostrate on their faces, adoring,'),
  ('en.pickthall', 17, 108, 'Saying: Glory to our Lord! Verily the promise of our Lord must be fulfilled.'),
  ('en.pickthall', 17, 109, 'They fall down on their faces, weeping, and it increaseth humility in them.'),
  ('en.pickthall', 17, 110, 'Say (unto mankind): Cry unto Allah, or cry unto the Beneficent, unto whichsoever ye cry (it is the same). His are the most beautiful names. And thou (Muhammad), be not loud-voiced in thy worship nor yet silent therein, but follow a way between.'),
  ('en.pickthall', 17, 111, 'And say: Praise be to Allah, Who hath not taken unto Himself a son, and Who hath no partner in the Sovereignty, nor hath He any protecting friend through dependence. And magnify Him with all magnificence.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 17, 1, 'Glory to (Allah) Who did take His servant for a Journey by night from the Sacred Mosque to the farthest Mosque, whose precincts We did bless,- in order that We might show him some of Our Signs: for He is the One Who heareth and seeth (all things).'),
  ('en.yusufali', 17, 2, 'We gave Moses the Book, and made it a Guide to the Children of Israel, (commanding): "Take not other than Me as Disposer of (your) affairs."'),
  ('en.yusufali', 17, 3, 'O ye that are sprung from those whom We carried (in the Ark) with Noah! Verily he was a devotee most grateful.'),
  ('en.yusufali', 17, 4, 'And We gave (Clear) Warning to the Children of Israel in the Book, that twice would they do mischief on the earth and be elated with mighty arrogance (and twice would they be punished)!'),
  ('en.yusufali', 17, 5, 'When the first of the warnings came to pass, We sent against you Our servants given to terrible warfare: They entered the very inmost parts of your homes; and it was a warning (completely) fulfilled.'),
  ('en.yusufali', 17, 6, 'Then did We grant you the Return as against them: We gave you increase in resources and sons, and made you the more numerous in man-power.'),
  ('en.yusufali', 17, 7, 'If ye did well, ye did well for yourselves; if ye did evil, (ye did it) against yourselves. So when the second of the warnings came to pass, (We permitted your enemies) to disfigure your faces, and to enter your Temple as they had entered it before, and to visit with destruction all that fell into their power.'),
  ('en.yusufali', 17, 8, 'It may be that your Lord may (yet) show Mercy unto you; but if ye revert (to your sins), We shall revert (to Our punishments): And we have made Hell a prison for those who reject (all Faith).'),
  ('en.yusufali', 17, 9, 'Verily this Qur\'an doth guide to that which is most right (or stable), and giveth the Glad Tidings to the Believers who work deeds of righteousness, that they shall have a magnificent reward;'),
  ('en.yusufali', 17, 10, 'And to those who believe not in the Hereafter, (it announceth) that We have prepared for them a Penalty Grievous (indeed).'),
  ('en.yusufali', 17, 11, 'The prayer that man should make for good, he maketh for evil; for man is given to hasty (deeds).'),
  ('en.yusufali', 17, 12, 'We have made the Night and the Day as two (of Our) Signs: the Sign of the Night have We obscured, while the Sign of the Day We have made to enlighten you; that ye may seek bounty from your Lord, and that ye may know the number and count of the years: all things have We explained in detail.'),
  ('en.yusufali', 17, 13, 'Every man\'s fate We have fastened on his own neck: On the Day of Judgment We shall bring out for him a scroll, which he will see spread open.'),
  ('en.yusufali', 17, 14, '(It will be said to him:) "Read thine (own) record: Sufficient is thy soul this day to make out an account against thee."'),
  ('en.yusufali', 17, 15, 'Who receiveth guidance, receiveth it for his own benefit: who goeth astray doth so to his own loss: No bearer of burdens can bear the burden of another: nor would We visit with Our Wrath until We had sent an messenger (to give warning).'),
  ('en.yusufali', 17, 16, 'When We decide to destroy a population, We (first) send a definite order to those among them who are given the good things of this life and yet transgress; so that the word is proved true against them: then (it is) We destroy them utterly.'),
  ('en.yusufali', 17, 17, 'How many generations have We destroyed after Noah? and enough is thy Lord to note and see the sins of His servants.'),
  ('en.yusufali', 17, 18, 'If any do wish for the transitory things (of this life), We readily grant them - such things as We will, to such person as We will: in the end have We provided Hell for them: they will burn therein, disgraced and rejected.'),
  ('en.yusufali', 17, 19, 'Those who do wish for the (things of) the Hereafter, and strive therefor with all due striving, and have Faith,- they are the ones whose striving is acceptable (to Allah).'),
  ('en.yusufali', 17, 20, 'Of the bounties of thy Lord We bestow freely on all- These as well as those: The bounties of thy Lord are not closed (to anyone).'),
  ('en.yusufali', 17, 21, 'See how We have bestowed more on some than on others; but verily the Hereafter is more in rank and gradation and more in excellence.'),
  ('en.yusufali', 17, 22, 'Take not with Allah another object of worship; or thou (O man!) wilt sit in disgrace and destitution.'),
  ('en.yusufali', 17, 23, 'Thy Lord hath decreed that ye worship none but Him, and that ye be kind to parents. Whether one or both of them attain old age in thy life, say not to them a word of contempt, nor repel them, but address them in terms of honour.'),
  ('en.yusufali', 17, 24, 'And, out of kindness, lower to them the wing of humility, and say: "My Lord! bestow on them thy Mercy even as they cherished me in childhood."'),
  ('en.yusufali', 17, 25, 'Your Lord knoweth best what is in your hearts: If ye do deeds of righteousness, verily He is Most Forgiving to those who turn to Him again and again (in true penitence).'),
  ('en.yusufali', 17, 26, 'And render to the kindred their due rights, as (also) to those in want, and to the wayfarer: But squander not (your wealth) in the manner of a spendthrift.'),
  ('en.yusufali', 17, 27, 'Verily spendthrifts are brothers of the Evil Ones; and the Evil One is to his Lord (himself) ungrateful.'),
  ('en.yusufali', 17, 28, 'And even if thou hast to turn away from them in pursuit of the Mercy from thy Lord which thou dost expect, yet speak to them a word of easy kindness.'),
  ('en.yusufali', 17, 29, 'Make not thy hand tied (like a niggard\'s) to thy neck, nor stretch it forth to its utmost reach, so that thou become blameworthy and destitute.'),
  ('en.yusufali', 17, 30, 'Verily thy Lord doth provide sustenance in abundance for whom He pleaseth, and He provideth in a just measure. For He doth know and regard all His servants.'),
  ('en.yusufali', 17, 31, 'Kill not your children for fear of want: We shall provide sustenance for them as well as for you. Verily the killing of them is a great sin.'),
  ('en.yusufali', 17, 32, 'Nor come nigh to adultery: for it is a shameful (deed) and an evil, opening the road (to other evils).'),
  ('en.yusufali', 17, 33, 'Nor take life - which Allah has made sacred - except for just cause. And if anyone is slain wrongfully, we have given his heir authority (to demand qisas or to forgive): but let him not exceed bounds in the matter of taking life; for he is helped (by the Law).'),
  ('en.yusufali', 17, 34, 'Come not nigh to the orphan\'s property except to improve it, until he attains the age of full strength; and fulfil (every) engagement, for (every) engagement will be enquired into (on the Day of Reckoning).'),
  ('en.yusufali', 17, 35, 'Give full measure when ye measure, and weigh with a balance that is straight: that is the most fitting and the most advantageous in the final determination.'),
  ('en.yusufali', 17, 36, 'And pursue not that of which thou hast no knowledge; for every act of hearing, or of seeing or of (feeling in) the heart will be enquired into (on the Day of Reckoning).'),
  ('en.yusufali', 17, 37, 'Nor walk on the earth with insolence: for thou canst not rend the earth asunder, nor reach the mountains in height.'),
  ('en.yusufali', 17, 38, 'Of all such things the evil is hateful in the sight of thy Lord.'),
  ('en.yusufali', 17, 39, 'These are among the (precepts of) wisdom, which thy Lord has revealed to thee. Take not, with Allah, another object of worship, lest thou shouldst be thrown into Hell, blameworthy and rejected.'),
  ('en.yusufali', 17, 40, 'Has then your Lord (O Pagans!) preferred for you sons, and taken for Himself daughters among the angels? Truly ye utter a most dreadful saying!'),
  ('en.yusufali', 17, 41, 'We have explained (things) in various (ways) in this Qur\'an, in order that they may receive admonition, but it only increases their flight (from the Truth)!'),
  ('en.yusufali', 17, 42, 'Say: If there had been (other) gods with Him, as they say,- behold, they would certainly have sought out a way to the Lord of the Throne!'),
  ('en.yusufali', 17, 43, 'Glory to Him! He is high above all that they say!- Exalted and Great (beyond measure)!'),
  ('en.yusufali', 17, 44, 'The seven heavens and the earth, and all beings therein, declare His glory: there is not a thing but celebrates His praise; And yet ye understand not how they declare His glory! Verily He is Oft-Forbear, Most Forgiving!'),
  ('en.yusufali', 17, 45, 'When thou dost recite the Qur\'an, We put, between thee and those who believe not in the Hereafter, a veil invisible:'),
  ('en.yusufali', 17, 46, 'And We put coverings over their hearts (and minds) lest they should understand the Qur\'an, and deafness into their ears: when thou dost commemorate thy Lord and Him alone in the Qur\'an, they turn on their backs, fleeing (from the Truth).'),
  ('en.yusufali', 17, 47, 'We know best why it is they listen, when they listen to thee; and when they meet in private conference, behold, the wicked say, "Ye follow none other than a man bewitched!"'),
  ('en.yusufali', 17, 48, 'See what similes they strike for thee: but they have gone astray, and never can they find a way.'),
  ('en.yusufali', 17, 49, 'They say: "What! when we are reduced to bones and dust, should we really be raised up (to be) a new creation?"'),
  ('en.yusufali', 17, 50, 'Say: "(Nay!) be ye stones or iron,'),
  ('en.yusufali', 17, 51, '"Or created matter which, in your minds, is hardest (to be raised up),- (Yet shall ye be raised up)!" then will they say: "Who will cause us to return?" Say: "He who created you first!" Then will they wag their heads towards thee, and say, "When will that be?" Say, "May be it will be quite soon!'),
  ('en.yusufali', 17, 52, '"It will be on a Day when He will call you, and ye will answer (His call) with (words of) His praise, and ye will think that ye tarried but a little while!"'),
  ('en.yusufali', 17, 53, 'Say to My servants that they should (only) say those things that are best: for Satan doth sow dissensions among them: For Satan is to man an avowed enemy.'),
  ('en.yusufali', 17, 54, 'It is your Lord that knoweth you best: If He please, He granteth you mercy, or if He please, punishment: We have not sent thee to be a disposer of their affairs for them.'),
  ('en.yusufali', 17, 55, 'And it is your Lord that knoweth best all beings that are in the heavens and on earth: We did bestow on some prophets more (and other) gifts than on others: and We gave to David (the gift of) the Psalms.'),
  ('en.yusufali', 17, 56, 'Say: "Call on those - besides Him - whom ye fancy: they have neither the power to remove your troubles from you nor to change them."'),
  ('en.yusufali', 17, 57, 'Those whom they call upon do desire (for themselves) means of access to their Lord, - even those who are nearest: they hope for His Mercy and fear His Wrath: for the Wrath of thy Lord is something to take heed of.'),
  ('en.yusufali', 17, 58, 'There is not a population but We shall destroy it before the Day of Judgment or punish it with a dreadful Penalty: that is written in the (eternal) Record.'),
  ('en.yusufali', 17, 59, 'And We refrain from sending the signs, only because the men of former generations treated them as false: We sent the she-camel to the Thamud to open their eyes, but they treated her wrongfully: We only send the Signs by way of terror (and warning from evil).'),
  ('en.yusufali', 17, 60, 'Behold! We told thee that thy Lord doth encompass mankind round about: We granted the vision which We showed thee, but as a trial for men,- as also the Cursed Tree (mentioned) in the Qur\'an: We put terror (and warning) into them, but it only increases their inordinate transgression!'),
  ('en.yusufali', 17, 61, 'Behold! We said to the angels: "Bow down unto Adam": They bowed down except Iblis: He said, "Shall I bow down to one whom Thou didst create from clay?"'),
  ('en.yusufali', 17, 62, 'He said: "Seest Thou? this is the one whom Thou hast honoured above me! If Thou wilt but respite me to the Day of Judgment, I will surely bring his descendants under my sway - all but a few!"'),
  ('en.yusufali', 17, 63, '(Allah) said: "Go thy way; if any of them follow thee, verily Hell will be the recompense of you (all)- an ample recompense.'),
  ('en.yusufali', 17, 64, '"Lead to destruction those whom thou canst among them, with thy (seductive) voice; make assaults on them with thy cavalry and thy infantry; mutually share with them wealth and children; and make promises to them." But Satan promises them nothing but deceit.'),
  ('en.yusufali', 17, 65, '"As for My servants, no authority shalt thou have over them:" Enough is thy Lord for a Disposer of affairs.'),
  ('en.yusufali', 17, 66, 'Your Lord is He That maketh the Ship go smoothly for you through the sea, in order that ye may seek of his Bounty. For he is unto you most Merciful.'),
  ('en.yusufali', 17, 67, 'When distress seizes you at sea, those that ye call upon - besides Himself - leave you in the lurch! but when He brings you back safe to land, ye turn away (from Him). Most ungrateful is man!'),
  ('en.yusufali', 17, 68, 'Do ye then feel secure that He will not cause you to be swallowed up beneath the earth when ye are on land, or that He will not send against you a violent tornado (with showers of stones) so that ye shall find no one to carry out your affairs for you?'),
  ('en.yusufali', 17, 69, 'Or do ye feel secure that He will not send you back a second time to sea and send against you a heavy gale to drown you because of your ingratitude, so that ye find no helper. Therein against Us?'),
  ('en.yusufali', 17, 70, 'We have honoured the sons of Adam; provided them with transport on land and sea; given them for sustenance things good and pure; and conferred on them special favours, above a great part of our creation.'),
  ('en.yusufali', 17, 71, 'One day We shall call together all human beings with their (respective) Imams: those who are given their record in their right hand will read it (with pleasure), and they will not be dealt with unjustly in the least.'),
  ('en.yusufali', 17, 72, 'But those who were blind in this world, will be blind in the hereafter, and most astray from the Path.'),
  ('en.yusufali', 17, 73, 'And their purpose was to tempt thee away from that which We had revealed unto thee, to substitute in our name something quite different; (in that case), behold! they would certainly have made thee (their) friend!'),
  ('en.yusufali', 17, 74, 'And had We not given thee strength, thou wouldst nearly have inclined to them a little.'),
  ('en.yusufali', 17, 75, 'In that case We should have made thee taste an equal portion (of punishment) in this life, and an equal portion in death: and moreover thou wouldst have found none to help thee against Us!'),
  ('en.yusufali', 17, 76, 'Their purpose was to scare thee off the land, in order to expel thee; but in that case they would not have stayed (therein) after thee, except for a little while.'),
  ('en.yusufali', 17, 77, '(This was Our) way with the messengers We sent before thee: thou wilt find no change in Our ways.'),
  ('en.yusufali', 17, 78, 'Establish regular prayers - at the sun\'s decline till the darkness of the night, and the morning prayer and reading: for the prayer and reading in the morning carry their testimony.'),
  ('en.yusufali', 17, 79, 'And pray in the small watches of the morning: (it would be) an additional prayer (or spiritual profit) for thee: soon will thy Lord raise thee to a Station of Praise and Glory!'),
  ('en.yusufali', 17, 80, 'Say: "O my Lord! Let my entry be by the Gate of Truth and Honour, and likewise my exit by the Gate of Truth and Honour; and grant me from Thy Presence an authority to aid (me)."'),
  ('en.yusufali', 17, 81, 'And say: "Truth has (now) arrived, and Falsehood perished: for Falsehood is (by its nature) bound to perish."'),
  ('en.yusufali', 17, 82, 'We send down (stage by stage) in the Qur\'an that which is a healing and a mercy to those who believe: to the unjust it causes nothing but loss after loss.'),
  ('en.yusufali', 17, 83, 'Yet when We bestow Our favours on man, he turns away and becomes remote on his side (instead of coming to Us), and when evil seizes him he gives himself up to despair!'),
  ('en.yusufali', 17, 84, 'Say: "Everyone acts according to his own disposition: But your Lord knows best who it is that is best guided on the Way."'),
  ('en.yusufali', 17, 85, 'They ask thee concerning the Spirit (of inspiration). Say: "The Spirit (cometh) by command of my Lord: of knowledge it is only a little that is communicated to you, (O men!)"'),
  ('en.yusufali', 17, 86, 'If it were Our Will, We could take away that which We have sent thee by inspiration: then wouldst thou find none to plead thy affair in that matter as against Us,-'),
  ('en.yusufali', 17, 87, 'Except for Mercy from thy Lord: for his bounty is to thee (indeed) great.'),
  ('en.yusufali', 17, 88, 'Say: "If the whole of mankind and Jinns were to gather together to produce the like of this Qur\'an, they could not produce the like thereof, even if they backed up each other with help and support.'),
  ('en.yusufali', 17, 89, 'And We have explained to man, in this Qur\'an, every kind of similitude: yet the greater part of men refuse (to receive it) except with ingratitude!'),
  ('en.yusufali', 17, 90, 'They say: "We shall not believe in thee, until thou cause a spring to gush forth for us from the earth,'),
  ('en.yusufali', 17, 91, '"Or (until) thou have a garden of date trees and vines, and cause rivers to gush forth in their midst, carrying abundant water;'),
  ('en.yusufali', 17, 92, '"Or thou cause the sky to fall in pieces, as thou sayest (will happen), against us; or thou bring Allah and the angels before (us) face to face:'),
  ('en.yusufali', 17, 93, '"Or thou have a house adorned with gold, or thou mount a ladder right into the skies. No, we shall not even believe in thy mounting until thou send down to us a book that we could read." Say: "Glory to my Lord! Am I aught but a man,- a messenger?"'),
  ('en.yusufali', 17, 94, 'What kept men back from belief when Guidance came to them, was nothing but this: they said, "Has Allah sent a man (like us) to be (His) Messenger?"'),
  ('en.yusufali', 17, 95, 'Say, "If there were settled, on earth, angels walking about in peace and quiet, We should certainly have sent them down from the heavens an angel for a messenger."'),
  ('en.yusufali', 17, 96, 'Say: "Enough is Allah for a witness between me and you: for He is well acquainted with His servants, and He sees (all things).'),
  ('en.yusufali', 17, 97, 'It is he whom Allah guides, that is on true Guidance; but he whom He leaves astray - for such wilt thou find no protector besides Him. On the Day of Judgment We shall gather, them together, prone on their faces, blind, dumb, and deaf: their abode will be Hell: every time it shows abatement, We shall increase from them the fierceness of the Fire.'),
  ('en.yusufali', 17, 98, 'That is their recompense, because they rejected Our signs, and said, "When we are reduced to bones and broken dust, should we really be raised up (to be) a new Creation?"'),
  ('en.yusufali', 17, 99, 'See they not that Allah, Who created the heavens and the earth, has power to create the like of them (anew)? Only He has decreed a term appointed, of which there is no doubt. But the unjust refuse (to receive it) except with ingratitude.'),
  ('en.yusufali', 17, 100, 'Say: "If ye had control of the Treasures of the Mercy of my Lord, behold, ye would keep them back, for fear of spending them: for man is (every) niggardly!"'),
  ('en.yusufali', 17, 101, 'To Moses We did give Nine Clear Signs: As the Children of Israel: when he came to them, Pharaoh said to him: "O Moses! I consider thee, indeed, to have been worked upon by sorcery!'),
  ('en.yusufali', 17, 102, 'Moses said, "Thou knowest well that these things have been sent down by none but the Lord of the heavens and the earth as eye-opening evidence: and I consider thee indeed, O Pharaoh, to be one doomed to destruction!"'),
  ('en.yusufali', 17, 103, 'So he resolved to remove them from the face of the earth: but We did drown him and all who were with him.'),
  ('en.yusufali', 17, 104, 'And We said thereafter to the Children of Israel, "Dwell securely in the land (of promise)": but when the second of the warnings came to pass, We gathered you together in a mingled crowd.'),
  ('en.yusufali', 17, 105, 'We sent down the (Qur\'an) in Truth, and in Truth has it descended: and We sent thee but to give Glad Tidings and to warn (sinners).'),
  ('en.yusufali', 17, 106, '(It is) a Qur\'an which We have divided (into parts from time to time), in order that thou mightest recite it to men at intervals: We have revealed it by stages.'),
  ('en.yusufali', 17, 107, 'Say: "Whether ye believe in it or not, it is true that those who were given knowledge beforehand, when it is recited to them, fall down on their faces in humble prostration,'),
  ('en.yusufali', 17, 108, '"And they say: \'Glory to our Lord! Truly has the promise of our Lord been fulfilled!\'"'),
  ('en.yusufali', 17, 109, 'They fall down on their faces in tears, and it increases their (earnest) humility.'),
  ('en.yusufali', 17, 110, 'Say: "Call upon Allah, or call upon Rahman: by whatever name ye call upon Him, (it is well): for to Him belong the Most Beautiful Names. Neither speak thy Prayer aloud, nor speak it in a low tone, but seek a middle course between."'),
  ('en.yusufali', 17, 111, 'Say: "Praise be to Allah, who begets no son, and has no partner in (His) dominion: Nor (needs) He any to protect Him from humiliation: yea, magnify Him for His greatness and glory!"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 17, 1, 'Subhaanal lazeee asraa bi\'abdihee lailam minal Masjidil Haraami ilal Masjidil Aqsal-lazee baaraknaa haw lahoo linuriyahoo min aayaatinaa;innahoo Huwas Samee\'ul-Baseer'),
  ('en.transliteration', 17, 2, 'Wa aatainaa Moosal-Kitaaba wa ja\'alnaahu hudal-liBaneee Israaa\'eel;'),
  ('en.transliteration', 17, 3, 'Zurriyyata man hamalnaa ma\'a Nooh innahoo kaana \'abdan shakooraa'),
  ('en.transliteration', 17, 4, 'Wa qadainaaa ilaa Baneee Israaa\'eela fil Kitaabi latufsidunna fil ardi marratain; wa lata\'lunna\'uluwwan kabeeraa'),
  ('en.transliteration', 17, 5, 'Fa-izaa jaaa\'a wa\'duoolaahumaa ba\'asnaaa \'alykurr \'ibaadai-lanaaa ulee baasin shadeedin fajaasoo khilaalad diyaar; wa kaana wa\'dam maf\'oolaa'),
  ('en.transliteration', 17, 6, 'Summa radadnaa lakumul karrata \'alaihim wa amdad-naakum-bi amwaalinuw wa baneen; wa ja\'alnaakum aksara nafeeraa'),
  ('en.transliteration', 17, 7, 'In ahsantum ahsantum li anfusikum wa in asaatum falahaa; fa izaa jaaa\'a wa\'dul aakhirati liyasooo\'oo wujoo hakum wa liyadkhulul masjida kamaa dakhaloohu awwala marratinw wa liyutabbiroo mass\'alaw tatbeera'),
  ('en.transliteration', 17, 8, '\'Asaa rabbukum anyyarhamakum; wa in \'uttum \'udnaa; wa ja\'alnaa jahannama lilkaafireena haseera'),
  ('en.transliteration', 17, 9, 'Inna haazal Quraana yahdee lillatee hiya aqwamu wa yubashshirul mu\'mineenal lazeena ya\'maloonas saalihaati anna lahum ajran kabeeraa'),
  ('en.transliteration', 17, 10, 'Wa annal lazeena laa yu\'minoona bil aakhirati a\'tadnaa lahum \'azaaban aleemaa'),
  ('en.transliteration', 17, 11, 'Wa yad\'ul insaanu bishsharri du\'aaa \'ahoo bilkhayr; wa kaanal insaanu \'ajoola'),
  ('en.transliteration', 17, 12, 'Wa ja\'alnal laila wannahaara Aayatayni famahawnaaa Aayatal laili wa ja\'alnaaa Aayatan nahaari mubsiratal litabtaghoo fadlam mir Rabbikum wa lita\'lamoo \'adadas sineena walhisaab; wa kulla shai\'in fassalnaahu tafseelaa'),
  ('en.transliteration', 17, 13, 'Wa kulla insaanin alzamnaahu taaa\'irahoo fe \'unuqihee wa nukhriji lahoo Yawmal Qiyaamati kitaabany yalqaahu manshooraa'),
  ('en.transliteration', 17, 14, 'Iqra kitaabak kafaa binafsikal Yawma \'alaika haseebaa'),
  ('en.transliteration', 17, 15, 'Manihtadaa fa innamaa yahtadee linafsihee wa man dalla fa innamaa yadillu \'alaihaa; wa laa taziru waaziratunw wizra ukhraa; wa maa kunnaa mu\'azzibeena hatta nab\'asa Rasoola'),
  ('en.transliteration', 17, 16, 'Wa izaaa aradnaaa an nuhlika qaryatan amarnaa mutrafeehaa fafasaqoo feehaa fahaqqa \'alaihal qawlu fadammarnaahaa tadmeeraa'),
  ('en.transliteration', 17, 17, 'Wa kam ahlaknaa minal qurooni mim ba\'di Nooh; wa kafaa bi Rabbika bizunoobi \'ibaadihee Khabeeram Baseeraa'),
  ('en.transliteration', 17, 18, 'Man kaana yureedul \'aajilata \'ajjalnaa lahoo feehaa maa nashaaa\'u liman nureedu summa ja\'alnaa lahoo Jahannama yaslaahaa mazmoomammad hooraa'),
  ('en.transliteration', 17, 19, 'Wa man araadal Aakhirata wa sa\'aa lahaa sa\'yahaa wa huwa mu\'minun fa ulaaa\'ika kaana sa\'yuhum mashkooraa'),
  ('en.transliteration', 17, 20, 'Kullan numiddu haaa \'ulaaa\'i wa haaa\'ulaaa\'i min \'ataaa\'i rabbik; wa maa kaana \'ataaa\'u rabbika mahzooraa'),
  ('en.transliteration', 17, 21, 'Unzur kaifa faddalnaa ba\'dahum \'alaa ba\'d; wa lal Aakhiratu akbaru darajaatinw wa akbaru tafdeelaa'),
  ('en.transliteration', 17, 22, 'Laa taj\'al ma\'al laahi ilaahan aakhara fataq\'uda mazoomam makhzoolaa'),
  ('en.transliteration', 17, 23, 'Wa qadaa Rabbuka allaa ta\'budooo illaaa iyyaahu wa bilwaalidaini ihsaanaa; immaa yablughanna \'indakal kibara ahaduhumaaa aw kilaahumaa falaa taqul lahumaaa uffinw wa laa tanharhumaa wa qullahumaa qawlan kareemaa'),
  ('en.transliteration', 17, 24, 'Wakhfid lahumaa janaahaz zulli minar rahmati wa qur Rabbir hamhumaa kamaa rabbayaanee sagheera'),
  ('en.transliteration', 17, 25, 'Rabbukum a\'lamu bimaa fee nufoosikum; in takoonoo saaliheena fa innahoo kaana lil awwaabeena Ghafoooraa'),
  ('en.transliteration', 17, 26, 'Wa aati zal qurbaa haqqahoo walmiskeena wabnas sabeeli wa laa tubazzir tabzeeraa'),
  ('en.transliteration', 17, 27, 'Innal mubazzireena kaanoo ikhwaanash shayaateeni wa kaanash shaytaanu li Rabbihee kafooraa'),
  ('en.transliteration', 17, 28, 'Wa immaa turidanna \'anhumub tighaaa\'a rahmatim mir rabbika tarjoohaa faqul lahum qawlam maisooraa'),
  ('en.transliteration', 17, 29, 'Wa laa taj\'al yadaka maghloolatan il \'unuqika wa laa tabsut haa kullal basti fataq\'uda maloomam mahsooraa'),
  ('en.transliteration', 17, 30, 'Inna Rabbaka yabsuturrizqa limai yashaaa\'u wa yaqdir; innahoo kaana bi\'ibaadihee Khabeeram Baseera'),
  ('en.transliteration', 17, 31, 'Wa laa taqtulooo awlaadakum khashyata imlaaq; nahnu narzuquhum wa iyyaakum; inna qatlahum kaana khitan kabeeraa'),
  ('en.transliteration', 17, 32, 'Wa laa taqrabuz zinaaa innahoo kaana faahishatanw wa saaa\'a sabeelaa'),
  ('en.transliteration', 17, 33, 'Wa laa taqtulun nafsal latee harramal laahu illaa bilhaqq; wa man qutila mazlooman faqad ja\'alnaa liwaliyyihee sultaanan falaa yusrif fil qatli innahoo kaana mansooraa'),
  ('en.transliteration', 17, 34, 'Wa laa taqraboo maalal yateemi illaa billatee hiya ahsanu hattaa yablugha ashuddah; wa awfoo bil\'ahd, innal \'ahda kaana mas\'oolaa'),
  ('en.transliteration', 17, 35, 'Wa awful kaila izaa kiltum wa zinoo bilqistaasil mustaqeem; zaalika khairunw wa ahsanu taaweelaa'),
  ('en.transliteration', 17, 36, 'Wa laa taqfu maa laisa laka bihee \'ilm; innas sam\'a walbasara walfu\'aada kullu ulaaa\'ika kaana \'anhu mas\'oolaa'),
  ('en.transliteration', 17, 37, 'Wa laa tamshi fil ardi marahan innaka lan takhriqal arda wa lan tablughal jibaala toola'),
  ('en.transliteration', 17, 38, 'Kullu zaalika kaana sayyi\'uhoo inda Rabbika makroohaa'),
  ('en.transliteration', 17, 39, 'Zaalika mimmaaa awhaaa ilaika Rabbuka minal hikmah; wa laa taj\'al ma\'allaahi ilaahan aakhara fatulqaa fee Jahannama maloomam mad hooraa'),
  ('en.transliteration', 17, 40, 'Afa asfaakum rabbukum bilbaneena wattakhaza minal malaaa\'ikati inaasaa; innakum lataqooloona qawlan \'azeema'),
  ('en.transliteration', 17, 41, 'Wa laqad sarrafnaa fee haazal Quraani liyazzakkaroo wa maa yazeeduhum illaa nufooraa'),
  ('en.transliteration', 17, 42, 'Qul law kaana ma\'ahooo aalihatun kamaa yaqooloona izal labtaghaw ilaa zil \'Arshi Sabeela'),
  ('en.transliteration', 17, 43, 'Subhaanahoo wa Ta\'aalaa \'ammaa yaqooloona \'uluwwan kabeeraa'),
  ('en.transliteration', 17, 44, 'Tusabbihu lahus samaawaatus sab\'u wal ardu wa man feehinn; wa im min shai\'in illaa yusabbihu bihamdihee wa laakil laa tafqahoona tasbeehahum; innahoo kaana Haleeman Ghafooraa'),
  ('en.transliteration', 17, 45, 'Wa izaa qaraatal Quraana ja\'alnaa bainaka wa bainal lazeena laa yu\'minoona bil aakhirati hijaabam mastooraa'),
  ('en.transliteration', 17, 46, 'Wa ja\'alnaa \'alaa quloo bihim akinnatan any yafqahoohu wa feee aazaanihim waqraa; wa izaa zakarta Rabbaka fil Quraani wahdahoo wallaw \'alaaa adbaarihim nufooraa'),
  ('en.transliteration', 17, 47, 'nahnu a\'lamu bimaa yastami\'oona biheee iz yastami\'oona ilaika wa iz hum najwaaa iz yaqooluz zaalimoona in tattabi\'oona illaa rajulam mas hooraa'),
  ('en.transliteration', 17, 48, 'Unzur kaifa daraboo lakal amsaala fadalloo falaa yastatee\'oona sabeelaa'),
  ('en.transliteration', 17, 49, 'Wa qaalooo\'a izaa kunnaa \'izaamanw wa rufaatan \'a innaa lamab\'oosoona khalqan jadeedaa'),
  ('en.transliteration', 17, 50, 'Qul koonoo jijaaratan aw hadeedaa'),
  ('en.transliteration', 17, 51, 'aw khalqam mimmaa yakburu fee sudoorikum; fasa yaqooloona mai yu\'eedunaa qulil lazee fatarakum awwala marrah; fasa yunghidoona ilaika ru\'oosahum wa yaqooloona mataa huwa qul \'asaaa any yakoona qareeba'),
  ('en.transliteration', 17, 52, 'Yawma yad\'ookum fatastajeeboona bihamdihee wa tazunnoona il labistum illaa qaleela'),
  ('en.transliteration', 17, 53, 'Wa qul li\'ibaadee yaqoolul latee hiya ahsan; innash shaitaana yanzaghu bainahum; innash shaitaana kaana lil insaani \'aduwwam mubeenaa'),
  ('en.transliteration', 17, 54, 'Rabbukum a\'lamu bikum iny yashaaa yarhamkum aw iny yashaa yu\'azzibkum; wa maaa arsalnaaka \'alaihim wakeelaa'),
  ('en.transliteration', 17, 55, 'Wa Rabbuka a\'lamu biman fis samaawaati wal lard; wa laqad faddalnaa ba\'dan Nabiyyeena \'alaa ba\'dinw wa aatainaaa Daawooda Zabooraa'),
  ('en.transliteration', 17, 56, 'Qulid \'ul lazeena za\'amtum min doonihee falaa yamlikoona kashfad durri\'ankum wa laa tahweelaa'),
  ('en.transliteration', 17, 57, 'Ulaaa\'ikal lazeena yad\'oona yabtaghoona ilaa Rabbihimul waseelata ayyuhum aqrabu wa yarjoona rahmatahoo wa yakhaafoona \'azaabah; inna \'azaaba rabbika kaana mahzooraa'),
  ('en.transliteration', 17, 58, 'Wa im min qaryatin illaa Nahnu muhlikoohaa qabla Yawmil Qiyaamati aw mu\'az ziboohaa \'azaaban shadeedaa; kaana zaalika fil Kitaabi mastooraa'),
  ('en.transliteration', 17, 59, 'Wa maa mana\'anaaa an nursila bil aayaati illaaa an kazzaba bihal awwaloon; wa aatainaa Samoodan naaqata mubsiratan fazalamoo bihaa; wa maa nursilu bil aayaati illaa takhweefaa'),
  ('en.transliteration', 17, 60, 'Wa iz qulnaa laka inna rabbaka ahaata binnaas; wa maa ja\'alnar ru\'yal lateee arainaaka illaa fitnatal linnaasi washshajaratal mal\'oonata fil quraan; wa nukhaw wifuhum famaa yazeeduhum illa tughyaanan kabeeraa'),
  ('en.transliteration', 17, 61, 'Wa iz qulnaa lilma laaa\'ikatis judoo li Aadama fasajadooo illaaa Ibleesa qaala \'a-asjudu liman khalaqta teena'),
  ('en.transliteration', 17, 62, 'Qaala ara\'aytaka haazal lazee karramta \'alaiya la\'in akhhartani ilaa Yawmil Qiyaamati la-ah tanikanna zurriyyatahooo illaa qaleelaa'),
  ('en.transliteration', 17, 63, 'Qaalaz hab faman tabi\'aka minhum fa inna Jahannama jazaaa\'ukum jazaaa\'am mawfooraa'),
  ('en.transliteration', 17, 64, 'Wastafziz manis tat\'ta minhum bisawtika wa ajlib \'alaihim bikhailika wa rajilika wa shaarik hum fil amwaali wal awlaadi wa \'idhum; wa maa ya\'iduhumush Shaitaanu illaa ghurooraa'),
  ('en.transliteration', 17, 65, 'Inna \'ibaadee laisa laka \'alaihim sultaan; wa kafaa bi Rabbika Wakeelaa'),
  ('en.transliteration', 17, 66, 'Rabbukumul lazee yuzjee lakumul fulka fil bahri litabtaghoo min fadlih; innahoo kaana bikum Raheemaa'),
  ('en.transliteration', 17, 67, 'Wa izaa massakumuddurru fil bahri dalla man tad\'oona illaaa iyyaahu falammaa najjaakum ilal barri a\'radtum; wa kaanal insaanu kafooraa'),
  ('en.transliteration', 17, 68, 'Afa amintum any yakhsifa bikum jaanibal barri aw yursil \'alaikum haasiban summa laa tajidoo lakum wakeelaa'),
  ('en.transliteration', 17, 69, 'Am amintum any yu\'eedakum feehi taaratan ukhraa fa yursila \'alaikum qaasifam minar reehi fa yugh riqakum bimaa kafartum summa laa tajidoo lakum \'alainaa bihee tabee\'aa'),
  ('en.transliteration', 17, 70, 'Wa laqad karramnaa Baneee aadama wa hamalnaahum fil barri walbahri wa razaqnaahum minat taiyibaati wa faddalnaahum \'alaa kaseerim mimman khalaqnaa tafdeelaa'),
  ('en.transliteration', 17, 71, 'Yawma nad\'oo kulla unaasim bi imaamihim faman ootiya kitaabahoo bi yameenihee fa ulaaa\'ika yaqra\'oona kitaabahum wa laa yuzlamoona fateelaa'),
  ('en.transliteration', 17, 72, 'Wa man kaana fee haaziheee a\'maa fahuwa fil aakhirati a\'maa wa adallu sabeelaa'),
  ('en.transliteration', 17, 73, 'Wa in kaadoo la yaftinoonaka \'anil lazeee awhainaaa ilaika litaftariya \'alainaaa ghairahoo wa izallat takhazooka khaleelaa'),
  ('en.transliteration', 17, 74, 'Wa law laaa an sabbatnaaka laqad kitta tarkanu ilaihim sha\'an qaleela'),
  ('en.transliteration', 17, 75, 'Izal la azaqnaaka di\'falhayaati wa di\'fal mamaati summa laa tajidu laka \'alainaa naseeraa'),
  ('en.transliteration', 17, 76, 'Wa in kaadoo la yastafizzoonaka minal ardi liyukhri jooka minhaa wa izal laa yalbasoona khilaafaka illaa qaleelaa'),
  ('en.transliteration', 17, 77, 'Sunnata man qad arsalnaa qablakamir Rusulinaa wa laa tajidu lisunnatinaa tahhweelaa'),
  ('en.transliteration', 17, 78, 'Aqimis Salaata liduloo kish shamsi ilaa ghasaqil laili wa quraanal Fajri inna quraa nal Fajri kaana mashhoodaa'),
  ('en.transliteration', 17, 79, 'Wa minal laili fatahajjad bihee naafilatal laka \'asaaa any yab\'asaka Rabbuka Maqaamam Mahmoodaa'),
  ('en.transliteration', 17, 80, 'Wa qur Rabbi adkhilnee mudkhala sidqinw wa akhrijnee mukhraja sidqinw waj\'al lee milladunka sultaanan naseeraa'),
  ('en.transliteration', 17, 81, 'Wa qul jaaa\'al haqqu wa zahaqal baatil; innal baatila kaana zahooqaa'),
  ('en.transliteration', 17, 82, 'Wa nunazzilu minal quraani maa huwa shifaaa\'unw wa rahmatul lilmu;mineena wa laa yazeeduz zaalimeena illaa khasaaraa'),
  ('en.transliteration', 17, 83, 'Wa izaaa an\'amnaa \'alal insaani a\'rada wa na-aa bijaani bihee wa izaa massahush sharru kaana ya\'oosaa'),
  ('en.transliteration', 17, 84, 'Qul kulluny ya\'malu \'alaa shaakilatihee fa rabbukum a\'lamu biman huwa ahdaa sabeelaa'),
  ('en.transliteration', 17, 85, 'Wa yas\'aloonaka \'anirrooh; qulir roohu min amri rabbee wa maaa ooteetum minal \'ilmi illaa qaleelaa'),
  ('en.transliteration', 17, 86, 'Wa la\'in shi\'naa lanaz habanna billazeee awhainaaa ilaika summa laa tajidu laka bihee \'alainaa wakeelaa'),
  ('en.transliteration', 17, 87, 'Illaa rahmatam mir Rabbik; inna fadlahoo kaana \'alaika kabeeraa'),
  ('en.transliteration', 17, 88, 'Qul la\'inij tama\'atil insu waljinnu \'alaaa any yaatoo bimisli haazal quraani laa yaatoona bimislihee wa law kaana ba\'duhum liba \'din zaheeraa'),
  ('en.transliteration', 17, 89, 'Qa laqad sarrafnaa linnaasi fee haazal quraani min kulli masalin fa abaaa aksarun naasi illaa kufooraa'),
  ('en.transliteration', 17, 90, 'Wa qaaloo lan nu\'mina laka hattaa tafjura lanaa minal ardi yamboo\'aa'),
  ('en.transliteration', 17, 91, 'Aw takoona laka jannatum min nakheelinw wa \'inabin fatufajjiral anhaara khilaalahaa tafjeeraa'),
  ('en.transliteration', 17, 92, 'Aw tusqitas samaaa\'a kamaa za\'amta \'alainaa kisafan aw taatiya billaahi walma laaa\'ikati qabeelaa'),
  ('en.transliteration', 17, 93, 'Aw yakoona laka baitum min zukhrufin aw tarqaa fis samaaa\'i wa lan nu\'mina liruqiyyika hatta tunazzila \'alainaa kitaaban naqra\'uh; qul Subhaana Rabbee hal kuntu illaa basharar Rasoolaa'),
  ('en.transliteration', 17, 94, 'Wa maa mana\'an naasa any yu\'minooo iz jaaa\'ahumul hudaaa illaaa an qaalooo aba\'asal laahu basharar Rasoolaa'),
  ('en.transliteration', 17, 95, 'Qul law kaana fil ardi malaaa \'ikatuny yamshoona mutma\'inneena lanazzalnaa \'alaihim minas samaaa\'i malakar Rasoolaa'),
  ('en.transliteration', 17, 96, 'Qul kafaa billaahi shaheedam bainee wa bainakum; innahoo kaana bi\'ibaadihee Khabeeram Baseeraa'),
  ('en.transliteration', 17, 97, 'Wa mai yahdil laahu fahuwal muhtad; wa mai yudlil falan tajida lahum awliyaaa\'a min doonih; wa nahshuruhum Yawmal Qiyaamati \'alaa wujoohihim umyanw wa bukmanw wa summaa; maa waahum Jahannamu kullamaa khabat zidnaahum sa\'eeraa'),
  ('en.transliteration', 17, 98, 'Zaalika jazaa\'uhum biannahum kafaroo bi aayaatinaa wa qaalooo \'a izaa kunnaa \'izaamanw wa rufaatan\'a innaa lamaboosoona khalqan jadeedaa'),
  ('en.transliteration', 17, 99, 'Awalam yaraw annal laahal lazee khalaqas samaawaati wal arda qaadirun \'alaaa any yakhluqa mislahum wa ja\'ala lahum ajalal laa raiba fee; fa abaz zaalimoona illaa kufooraa'),
  ('en.transliteration', 17, 100, 'Qul law antum tamlikoona khazaaa\'ina rahmati Rabbeee izal la amsaktum khash yatal infaaq; wa kaanal insaanu qatooraa'),
  ('en.transliteration', 17, 101, 'Wa laqad aatainaa Moosaa tis\'a Aayaatim baiyinaatin fas\'al Baneee Israaa\'eela iz jaaa\'ahum faqaala lahoo Fir\'awnu inee la azunnuka yaa Moosaa mas hooraa'),
  ('en.transliteration', 17, 102, 'Qaala laqad \'alimta maaa anzala haaa\'ulaaa\'i illaa Rabbus samaawaati wal ardi basaaa\'ira wa innee la azun nuka yaa Fir\'awnu masbooraa'),
  ('en.transliteration', 17, 103, 'Fa araada any yastafizzahum minal ardi fa aghraqnaahu wa mam ma\'ahoo jamee\'aa'),
  ('en.transliteration', 17, 104, 'Wa qulnaa mim ba\'dihee li Baneee Israaa\'eelas kunul arda faizaa jaaa\'a wa\'dulaakhirati ji\'naa bikum lafeefaa'),
  ('en.transliteration', 17, 105, 'Wa bilhaqqi anzalnaahu wa bilhaqqi nazal; wa maaa arsalnaaka illaa mubash shiranw wa nazeeraa'),
  ('en.transliteration', 17, 106, 'Wa quraanan faraqnaahu litaqra ahoo \'alan naasi \'alaa muksinw wa nazzalnaahu tanzeelaa'),
  ('en.transliteration', 17, 107, 'Qul aaaniminoo biheee aw laa tu\'minoo; innal lazeena ootul \'ilma min qabliheee izaa yutlaa \'alaihim yakhirroona lil azqaani sujjadaa'),
  ('en.transliteration', 17, 108, 'Wa yaqooloona Subhaana Rabbinaaa in kaana wa\'du Rabbinaa lamaf\'oolaa'),
  ('en.transliteration', 17, 109, 'Wa yakhirroona lil azqaani yabkoona wa yazeeduhum khushoo\'aa'),
  ('en.transliteration', 17, 110, 'Qulid\'ul laaha awid\'ur Rahmaana ayyam maa tad\'oo falahul asmaaa\'ul Husnaa; wa laa tajhar bi Salaatika wa laa tukhaafit bihaa wabtaghi baina zaalika sabeela'),
  ('en.transliteration', 17, 111, 'Wa qulil hamdu lillaahil lazee lam yattakhiz waladanw wa lam yakul lahoo shareekun fil mulki wa lam yakul lahoo waliyyum minaz zulli wa kabbirhu takbeeraa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 17, 1, 'وہ پاک ہے جس نے راتوں رات اپنے بندے کو مسجدحرام سے مسجد اقصیٰ تک سیر کرائی جس کے اردگرد ہم نے برکت رکھی ہے تاکہ ہم اسے اپنی کچھ نشانیاں دکھائیں بے شک وہ سننے والا دیکھنے ولا ہے'),
  ('ur.ahmedali', 17, 2, 'اور ہم نے موسیٰ کو کتاب دی اور اسے بنی اسرائیل کے لیے ہدایت بنایا کہ میرے سوا کسی کو کارساز نہ بناؤ'),
  ('ur.ahmedali', 17, 3, 'اے ان کی نسل جنہیں ہم نے نوح کے ساتھ سوار کیا تھا بے شک وہ شکر گزار بندہ تھا'),
  ('ur.ahmedali', 17, 4, 'اور ہم نے بنی اسرائیل کو کتاب میں یہ بات بتلا دی تھی کہ تم ضرور ملک میں دو مرتبہ خرابی کرو گے اوربڑی سرکشی کرو گے'),
  ('ur.ahmedali', 17, 5, 'پھر جب پہلا وعدہ آیا تو ہم نے تم پر اپنے بندے سخت لڑائی والے بھیجے پھر وہ تمہارے گھروں میں گھس گئے اور الله کا وعدہ تو پورا ہونا ہی تھا'),
  ('ur.ahmedali', 17, 6, 'پھر ہم نے تمہیں دشمنوں پر غلبہ دیا اور تمہیں مال اور اولاد میں ترقی دی اور تمہیں بڑی جماعت والا بنا دیا'),
  ('ur.ahmedali', 17, 7, 'اگر تم نے بھلائی کی تو اپنے ہی لیےکی اور اگر برائی کی تو وہ بھی اپنے ہی لیےکی پھر جب دوسرا وعدہ آیا تاکہ تمہارے چہروں پر رسوائی پھیر دیں اور مسجد میں گھس جائیں جس طرح پہلی بار گھس گئے تھے اور جس چیز پر قابو پائیں اس کا ستیاناس کر دیں'),
  ('ur.ahmedali', 17, 8, 'تمہارا رب قریب ہے کہ تم پر رحم کرے اور اگر تم پھر وہی کرو گے تو ہم بھی پھر وہی کریں گے اور ہم نے دوزخ کو کافروں کے لیے قید خانہ بنایا ہے'),
  ('ur.ahmedali', 17, 9, 'بے شک یہ قرآن وہ راہ بتاتا ہے جو سب سے سیدھی ہے اور ایمان والوں کو جو نیک کام کرتے ہیں اس بات کی خوشخبری دیتاہے ان کے لیے بڑا ثواب ہے'),
  ('ur.ahmedali', 17, 10, 'اور یہ بھی بتاتا ہے کہ جو لوگ آخرت پر ایمان نہیں لاتے ہم نے ان کے لیے دردناک عذاب تیار کیا ہے'),
  ('ur.ahmedali', 17, 11, 'اور انسان برائی مانگتا ہے جس طرح وہ بھلائی مانگتا ہے اور انسان جلد باز ہے'),
  ('ur.ahmedali', 17, 12, 'اور ہم نے رات اور دن کے دو نمونے بنا دیے پھر رات کے نمونے کو دھندلا کر دیا اور دن کا نمونہ نظر آنے کے لیے روشن کر دیا تاکہ تم اپنے رب کا فضل تلاش کرو اور تاکہ تم برسوں کی گنتی اور حساب معلوم کر لو اور ہم نے ہر چیز کی تفصیل کر دی'),
  ('ur.ahmedali', 17, 13, 'اور ہم نے ہر آدمی کا نامہ اعمال اس کی گردن کےساتھ لگادیا ہے اور قیامت کے دن ہم اس کا نامہ اعمال نکال کر سامنے کردیں گے'),
  ('ur.ahmedali', 17, 14, 'اپنا نامہ اعمال پڑھ لے آج اپنا حساب لینے کے لیے تو ہی کافی ہے'),
  ('ur.ahmedali', 17, 15, 'جو سیدھے راستے پر چلا تو اپنے ہی لیے چلا اور جو بھٹک گیا تو بھٹکنے کا نقصان بھی وہی اٹھائے گا اور کوئی بوجھ اٹھانے والا دوسرے کا بوجھ نہیں اٹھائے گا اور ہم سزا نہیں دیتے جب تک کسی رسول کو نہیں بھیج لیتے'),
  ('ur.ahmedali', 17, 16, 'اور جب ہم کسی بستی کو ہلاک کرنا چاہتے ہیں تو وہاں کے دولتمندوں کو کوئی حکم دیتے ہیں پھر وہ وہاں نافرمانی کرتے ہیں تب ان پر حجت تمام ہوجاتی ہے اور ہم اسے برباد کر دیتے ہیں'),
  ('ur.ahmedali', 17, 17, 'اور نوح کے بعد ہم نےقوموں کے کئی دور ہلاک کر دیئے ہیں اور تیرا رب اپنے بندوں کے گناہوں کا جاننے والا دیکھنے والا کافی ہے'),
  ('ur.ahmedali', 17, 18, 'جو کوئی دنیا چاہتا ہے تو ہم اسے سردست دنیا میں سے جس قدر چاہتے ہیں دیتے ہیں پھر ہم نے اس کے لیے جہنم تیار کر رکھی ہے جس میں وہ ذلیل و خوار ہوکر رہے گا'),
  ('ur.ahmedali', 17, 19, 'اورجو آخرت چاہتا ہے اوراس کے لیے مناسب کوشش بھی کرتا ہے اور وہ مومن بھی ہے تو ایسے لوگوں کی کوشش مقبول ہو گی'),
  ('ur.ahmedali', 17, 20, 'ہم ہر فریق کو اپنی پروردگاری بخششوں سے مدد دیتے ہیں ان کو بھی اور تیرے رب کی بخشش کسی پر بند نہیں'),
  ('ur.ahmedali', 17, 21, 'دیکھو ہم نے ایک کو دوسرے پر کیسی فضیلت دی ہے اور آخرت کے تو بڑے درجے اوربڑی فضیلت ہے'),
  ('ur.ahmedali', 17, 22, 'الله کے ساتھ اور کوئی معبود نہ بنا ورنہ تو ذلیل بے کس ہو کر بیٹھے گا'),
  ('ur.ahmedali', 17, 23, 'اور تیرا رب فیصلہ کر چکا ہے اس کے سوا کسی کی عبادت نہ کرو اور ماں باپ کے ساتھ نیکی کرو اور اگر تیرے سامنے ان میں سے ایک یا دونوں بڑھاپے کو پہنچ جائیں تو انہیں اف بھی نہ کہو اور نہ انہیں جھڑکو اور ان سے ادب سے بات کرو'),
  ('ur.ahmedali', 17, 24, 'اوران کے سامنے شفقت سے عاجزی کے ساتھ جھکے رہو اور کہو اے میرے رب جس طرح انہوں نے مجھے بچپن سےپالا ہے اسی طرح تو بھی ان پر رحم فرما'),
  ('ur.ahmedali', 17, 25, 'جو تمہارے دلوں میں ہے تمہارا رب خوب جانتا ہے اگر تم نیک ہو گے تو وہ توبہ کرنے والوں کو بخشنے والا ہے'),
  ('ur.ahmedali', 17, 26, 'اور رشتہ دار اور مسکین اور مسافر کو اس کا حق دے دو اور مال کو بے جا خرچ نہ کرو'),
  ('ur.ahmedali', 17, 27, 'بے شک بیجا خرچ کرنے والے شیطانو ں کے بھائی ہیں اور شیطان اپنے رب کا ناشکر گزار ہے'),
  ('ur.ahmedali', 17, 28, 'اوراگر تجھے اپنے رب کے فضل کے انتظار میں کہ جس کی تجھے امید ہے منہ پھیرنا پڑے تو ان سے نرم بات کہہ دے'),
  ('ur.ahmedali', 17, 29, 'اور اپنا ہاتھ اپنی گردن کے ساتھ بندھا ہوانہ رکھ اور نہ اسے کھول دے بالکل ہی کھول دینا پھر تو پشیمان تہی دست ہو کر بیٹھ رہے گا'),
  ('ur.ahmedali', 17, 30, 'بے شک تیرا رب جس کے لئے چاہے رزق کشادہ کر تا ہے اور تنگ بھی کرتا ہے بے شک وہ اپنے بندوں کو جاننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 17, 31, 'اور اپنی اولاد کو تنگدستی کے ڈر سے قتل نہ کرو ہم انہیں بھی رزق دیتے ہیں اور تمہیں بھی بے شک ان کا قتل کرنا بڑا گناہ ہے'),
  ('ur.ahmedali', 17, 32, 'اور زنا کے قریب نہ جاؤ بے شک وہ بے حیائی ہے اور بری راہ ہے'),
  ('ur.ahmedali', 17, 33, 'اور جس جان کو قتل کرنا الله نے حرام کر دیا ہے اسے ناحق قتل نہ کرنا اور جو کوئی ظلم سے مارا جائے تو ہم نے اس کے ولی کے واسطے اختیار دے دیا ہے لہذاا قصاص میں زيادتی نہ کرے بے شک اس کی مدد کی گئی ہے'),
  ('ur.ahmedali', 17, 34, 'اور یتیم کے مال کے پاس نہ جاؤ مگر جس طریقہ سے بہتر ہو جب تک وہ اپنی جوانی کو پہنچے اور عہد کو پورا کرو بے شک عہد کی بازپرس ہو گی'),
  ('ur.ahmedali', 17, 35, 'اور ناپ تول کر دو تو پورا ناپو اور صحیح ترازو سے تول کر دو یہ بہتر ہے اور انجام بھی اس کا اچھا ہے'),
  ('ur.ahmedali', 17, 36, 'اورجس بات کی تجھے خبر نہیں اس کے پیچھے نہ پڑ بے شک کان اورآنکھ اور دل ہر ایک سے باز پرس ہو گی'),
  ('ur.ahmedali', 17, 37, 'اور زمین پر اتراتا ہوا نہ چل بے شک تو نہ زمین کو پھاڑ ڈالے گا او رنہ لمبائی میں پہاڑوں تک پہنچے گا'),
  ('ur.ahmedali', 17, 38, 'ان میں سے ہر ایک بات تیرے رب کے ہاں ناپسند ہے'),
  ('ur.ahmedali', 17, 39, 'یہ اس حکمت میں سے ہے جسے تیرے رب نے تیری طرف وحی کیا ہے اور الله کے ساتھ اور کسی کو معبود نہ بنا ورنہ تو ملزم مردود بنا کر جہنم میں ڈال دیا جائے گا'),
  ('ur.ahmedali', 17, 40, 'کیا تمہارے رب نے تمہیں چن کر بیٹے دے دیئے اور اپنے لئےفرشتوں کو بیٹیاں بنا لیا تم بڑی بات کہتے ہو'),
  ('ur.ahmedali', 17, 41, 'اور ہم نے اس قرآن میں کئی طرح سے بیان کیا تاکہ وہ سمجھیں حالانکہ اس سے انہیں نفرت ہی بڑھتی جاتی ہے'),
  ('ur.ahmedali', 17, 42, 'کہہ دو اگر اس کے ساتھ اور بھی معبود ہوتے جیسا وہ کہتے ہیں تب تو انہوں نے عرش والے تک کوئی راستہ نکال لیا ہوتا'),
  ('ur.ahmedali', 17, 43, 'وہ پاک ہے اور جو کچھ وہ کہتے ہیں اس سے وہ بہت ہی بلند ہے'),
  ('ur.ahmedali', 17, 44, 'ساتوں آسمان اور زمین اور جو کوئی ان میں ہے اس کی پاکی بیان کرتے ہیں اور ایسی کوئی چیز نہیں جو ا سکی حمد کے ساتھ تسبیح نہ کرتی ہو لیکن تم ان کی تسبیح کو نہیں سمجھتے بے شک وہ بردبار بخشنے والا ہے'),
  ('ur.ahmedali', 17, 45, 'اورجب تو قرآن پڑھتا ہے ہم تیرے اور ان لوگو ں کے درمیان جو آخرت کو نہیں مانتے ایک چھپا ہو ا پردہ کر دیتے ہیں'),
  ('ur.ahmedali', 17, 46, 'اور ہم نے ان کے دلو ں پر پردے کر دیے ہیں تاکہ اسے نہ سمجھیں اور ان کے کانوں میں گرانی ڈال دی ہے اور جب تو قرآن میں صرف اپنے رب ہی کا ذکر کرتا ہے تو پیٹھ پھیر کر کفرت سے بھاگتے ہیں'),
  ('ur.ahmedali', 17, 47, 'ہم خوب جانتے ہیں جس غرض سے یہ سنتے ہیں جب یہ لوگ تیری طرف کان لگاتے ہیں اور جس وقت آپس میں سرگوشیاں کرتے ہیں جب یہ ظالم کہتے ہیں کہ تم محض ایسے شخص کا ساتھ دیتے ہو جس پر جادو کیا گیا ہے'),
  ('ur.ahmedali', 17, 48, 'دیکھ تیرے لیے کیسی مثالیں بیان کرتے ہیں سو گمراہ ہو گئے پھر وہ راستہ نہیں پا سکتے'),
  ('ur.ahmedali', 17, 49, 'اور کہتے ہیں کیا جب ہم ہڈیاں اور چورا ہو جائیں گے پھر نئے بن کر اٹھیں گے'),
  ('ur.ahmedali', 17, 50, 'کہہ دو تم پتھر یا لوہا ہوجاؤ'),
  ('ur.ahmedali', 17, 51, 'یا کوئی اور چیز جسے تم اپنے دلوں میں مشکل سمجھتے ہو پھر وہ کہیں گے ہمیں دوبارہ کون لوٹائے گا کہہ دو وہی جس نے تمہیں پہلی مرتبہ پیدا کیا ہے پھر تمہارے سامنے سروں کو ہلاکر کہیں گے کہ وہ کب ہو گا کہہ دو شاید وہ وقت بھی قریب آ گیا ہو'),
  ('ur.ahmedali', 17, 52, 'جس دن تمہیں پکارے گا پھر اس کی تعریف کرتے ہوئے چلے آؤ گے اور خیال کرو گے کہ بہت ہی کم ٹھہرے تھے'),
  ('ur.ahmedali', 17, 53, 'اور میرے بندوں سے کہہ دو کہ وہی بات کہیں جو بہتر ہو بےشک شیطان آپس میں لڑا دیتا ہے بے شک شیطان انسان کا کھلا دشمن ہے'),
  ('ur.ahmedali', 17, 54, 'تمہارا رب خوب جانتا ہے اگر چاہے تم پر رحم کرے اور اگر چاہے تمہیں عذاب دے او رہم نے تجھے ان پر ذمہ دار بنا کر نہیں بھیجا'),
  ('ur.ahmedali', 17, 55, 'اور تیرا رب خوب جانتا ہے جو آسمانوں اور زمین میں ہے اور ہم نے بعض پیغمبروں کو بعض پر فضیلت دی ہے او رہم نے داؤد کو زبور دی تھی'),
  ('ur.ahmedali', 17, 56, 'کہہ دو انہیں پکارو جنہیں تم اس کے سوا سمجھتے ہو وہ نہ تمہاری تکلیف دور کر سکیں گے اور نہ اسے بدلیں گے'),
  ('ur.ahmedali', 17, 57, 'وہ لوگ جنہیں یہ پکارتے ہیں جو ان میں سے زیادہ مقرب ہیں وہ بھی اپنے رب کی طرف نیکیوں کا ذریعہ تلاش کرتے ہیں اور اس کی مہربانی کی امید رکھتے ہیں اور اس کے عذاب سے ڈرتے ہیں بےشک تیرے رب کا عذاب ڈرنے کی چیز ہے'),
  ('ur.ahmedali', 17, 58, 'اور ایسی کوئی بستی نہیں جسے ہم قیامت سے پہلے ہلاک نہ کریں یا اسے سخت عذاب نہ دیں یہ بات کتاب میں لکھی ہوئی ہے'),
  ('ur.ahmedali', 17, 59, 'اور ہم نے اس لیےمعجزات بھیجنے موقوف کر دیےکہ پہلوں نے انہیں جھٹلایا تھا اور ہم نے ثمود کو اونٹنی کا کھلا ہوا معجزہ دیا تھا پھر بھی انہوں نے اس پر ظلم کیا اور یہ معجزات تو ہم محض ڈرانے کے لیے بھیجتے ہیں'),
  ('ur.ahmedali', 17, 60, 'اور جب ہم نے تم سے کہہ دیا کہ تیرے رب نے سب کو قابو میں کر رکھا ہے اور وہ خواب جو ہم نے تمہیں دکھایا اور وہ خبیث درخت جس کا ذکر قرآن میں ہے ان سب کو ان لوگو ں کے لیے فتنہ بنا دیا اور ہم تو انہیں ڈراتے ہیں سو اس سے ان کی شرارت اوربھی بڑھتی جاتی ہے'),
  ('ur.ahmedali', 17, 61, 'اور جب ہم نے فرشتوں سے کہا آدم کو سجدہ کرو تو سوائے ابلیس کے سب سجدہ میں گر پڑے کہا کیا میں ایسے شخص کو سجدہ کروں جسےتو نے مٹی بنایا ہے'),
  ('ur.ahmedali', 17, 62, 'کہا بھلا دیکھ تو یہ شخص جسے تو نے مجھ سے بڑھایا اگرتو مجھے قیامت کے دن تک مہلت دے تو میں بھی سوائے چند لوگوں کے اس کی نسل کو قابو میں کر کے رہونگا'),
  ('ur.ahmedali', 17, 63, 'فرمایا جا۔ پھر ان میں سے جو کوئی تیرے ساتھ ہوا تو جہنم تم سب کی پوری سزا ہے'),
  ('ur.ahmedali', 17, 64, 'ان میں سے جسے تو اپنی آواز سنا کر بہکا سکتا ہے بہکا لے اور ان پر اپنے سوار اور پیادے بھی چڑھا دے اوران کے مال اور اولاد میں بھی شریک ہو جا اور ان سے وعدے کر اور شیطان کے وعدے بھی محض فریب ہی تو ہیں'),
  ('ur.ahmedali', 17, 65, 'بے شک میرے بندوں پر تیرا غلبہ نہیں ہو گا اور تیرا رب کافی کارساز ہے'),
  ('ur.ahmedali', 17, 66, 'تمہارا رب وہ ہے جو تمہارے لیے دریا میں کشتیاں چلاتا ہے تاکہ تم اس کا فضل تلاش کرو بے شک وہی تم پر بڑا مہربان ہے'),
  ('ur.ahmedali', 17, 67, 'اور جب تم پر دریا میں کوئی مصیبت آتی ہے تو بھول جاتے ہو جنہیں الله کے سوا پکارتے تھےپھر جب وہ تمہیں خشکی کی طرف بچا لاتا ہے تو تم اس سے منہ موڑ لیتے ہو اور انسان بڑا ہی ناشکرا ہے'),
  ('ur.ahmedali', 17, 68, 'پھر کیا تم اس بات سے نڈر ہو گئے کہ وہ تمہیں خشکی کی طرف لاکر زمین میں دھنسا دے یا تم پر پتھر برسانے والی آندھی بھیج دے پھر تم کسی کو اپنا مددگار نہ پاؤ'),
  ('ur.ahmedali', 17, 69, 'یا تم اس بات سے بالکل نڈر ہو گئے ہو کہ وہ دوبارہ تمہیں پھر دریا میں لوٹا لائے پھر تم پر ہوا کا سخت طوفان بھیج دے پھر تمہاری ناشکری سے تمہیں غرق کر دے پھر اپنی طرف سے ہم پر کوئی باز پرس کرنے والا بھی نہ پاؤ'),
  ('ur.ahmedali', 17, 70, 'اور ہم نے آدم کی اولاد کو عزت دی ہے اور خشکی اور دریا میں اسے سوار کیا اور ہم نے انہیں ستھری چیزو ں سے رزق دیا اور اپنی بہت سی مخلوقات پر انہیں فضیلت عطا کی'),
  ('ur.ahmedali', 17, 71, 'جس دن ہم ہر فرقہ کو ان کے سرداروں کے ساتھ بلائیں گے سوجسے اس کا اعمال نامہ ا سکے داہنے ہاتھ میں دیا گیا سو وہ لوگ اپنا اعمال نامہ پڑھیں گے اور وہ تاگے کے برابر ظلم نہیں کئے جائیں گے'),
  ('ur.ahmedali', 17, 72, 'اور جو کوئی اس جہان میں اندھا رہا تو وہ آخرت میں بھی اندھا ہو گا اور راستہ سے بہت دور ہٹا ہوا'),
  ('ur.ahmedali', 17, 73, 'اور بے شک وہ قریب تھے کہ تجھے اس چیز سے بہکا دیں جو ہم نے تجھ پر بذریعہ وحی بھیجی ہے تاکہ تو اس کے سوا ہم پر بہتان باندھنے لگے اور پھر تجھے اپنا دوست بنا لیں'),
  ('ur.ahmedali', 17, 74, 'اور اگرہم تجھے ثابت قدم نہ رکھتے تو کچھ تھوڑا سا ان کی طرف جھکنے کے قریب تھا'),
  ('ur.ahmedali', 17, 75, 'اس وقت ہم تجھے زندگی میں اور موت کے بعد دہرا عذاب چکھاتے پھر تو اپنے واسطے ہمارے مقابلے میں کوئی مددگار نہ پاتا'),
  ('ur.ahmedali', 17, 76, 'اور وہ تو تجھے اس زمین سے دھکیل دینے کو تھے تاکہ تجھے اس سے نکال دیں پھر وہ بھی تیرے بعد بہت ہی کم ٹھرتے'),
  ('ur.ahmedali', 17, 77, 'تم سے پہلے جتنے رسول ہم نے بھیجے ہیں ان کا یہی دستور رہا ہے او رہمارے دستور میں تم تبدیلی نہیں پاؤ گے'),
  ('ur.ahmedali', 17, 78, 'آفتاب کے ڈھلنےسے رات کے اندھیرے تک نماز پڑھا کرو اور صبح کی نماز بھی بے شک صبح کی نماز میں مجمع ہو تا ہے'),
  ('ur.ahmedali', 17, 79, 'اور کسی وقت رات میں تہجد پڑھا کرو جو تیرے لیے زائد چیز ہے قریب ہے کہ تیرا رب مقام محمود میں پہنچا دے'),
  ('ur.ahmedali', 17, 80, 'اور کہہ اے میرے رب مجھے خوبی کے ساتھ پہنچا دے اور مجھے خوبی کے ساتھ نکال لے اور میرے لیے اپنی طرف سے غلبہ دے جس کے ساتھ نصرت ہو'),
  ('ur.ahmedali', 17, 81, 'اور کہہ دو کہ حق آیا اور باطل مٹ گیا بے شک باطل مٹنے ہی والا تھا'),
  ('ur.ahmedali', 17, 82, 'اور ہم قرآن میں ایسی چیزیں نازل کرتے ہیں کہ وہ ایمانداروں کے حق میں شفا اور رحمت ہیں اور ظالموں کو اس سےاور زیادہ نقصان پہنچتا ہے'),
  ('ur.ahmedali', 17, 83, 'اورجب ہم انسان پر انعام کرتے ہیں تو منہ پھیر لیتا ہے اور پہلو تہی کرتا ہے اور جب اسے کوئی تکلیف پہنچتی ہے تو نا امیدہوجاتا ہے'),
  ('ur.ahmedali', 17, 84, 'کہہ دو کہ ہر شخص اپنے طریقہ پر کام کرتا ہے پھر تمہارا رب خوب جانتا ہے کہ سب سے زیادہ ٹھیک راہ پر کون ہے'),
  ('ur.ahmedali', 17, 85, 'اور یہ لوگ تجھے رو ح کے متعلق سوال کرتے ہیں کہہ دو روح میرے رب کے حکم سے ہے اور تمہیں جو علم دیا گیا ہے وہ بہت ہی تھوڑا ہے'),
  ('ur.ahmedali', 17, 86, 'او راگر ہم چاہیں تو جو کچھ ہم نے تیری طرف وحی کی ہے اسے اٹھا لیں پھر تجھے اس کے لیے ہمارے مقابلہ میں کوئی حمایتی نہ ملے'),
  ('ur.ahmedali', 17, 87, 'مگر یہ صرف تیرے رب کی رحمت ہے بے شک تجھ پر اس کی بڑی عنایت ہے'),
  ('ur.ahmedali', 17, 88, 'کہہ دو اگر سب آدمی اور سب جن مل کر بھی ایسا قرآن لانا چاہیں تو ایسا نہیں لا سکتے اگرچہ ان میں سے ہر ایک دوسرے کا مددگار کیوں نہ ہو'),
  ('ur.ahmedali', 17, 89, 'او رہم نے اس قرآن میں لوگوں کے لیے ہر ایک قسم کی مثال بھی کھول کر بیان کر دی ہے پھر بھی اکثر لوگ انکار کیے بغیر نہ رہے'),
  ('ur.ahmedali', 17, 90, 'اور کہا ہم تمہیں ہرگز نہ مانیں گے یہاں تک کہ تو ہمارے لیے زمین میں سے کوئی چشمہ جاری کر دے'),
  ('ur.ahmedali', 17, 91, 'یا تیرے لیے کھجور اور انگور کا کوئی باغ ہو پھر تو اس باغ میں بہت سی نہریں جاری کر دے'),
  ('ur.ahmedali', 17, 92, 'یا جیسا تو خیال کرتا ہے ہم پرکوئی آسمان کا ٹکڑا گرادے یا تو الله اور فرشتوں کو روبرو لے آ'),
  ('ur.ahmedali', 17, 93, 'یا تیرے پاس کوئی سونے کا گھر ہو یا تو آسمان پر چڑھ جائے او رہم تو تیرے چڑھنے کا بھی یقین نہیں کریں گے یہاں تک کہ توہمارے پاس ایسی کتاب لائے جسے ہم بھی پڑھ سکیں کہہ دو میرا رب پاک ہے میں تو فقط ایک بھیجا ہوا انسان ہوں'),
  ('ur.ahmedali', 17, 94, 'اورلوگوں کو ایمان لانے سے جب کہ ان کے پاس ہدایت آ گئی صرف اسی چیز نے روکا ہے کہ کہنے لگے کیا الله نے آدمی کو رسول بنا کر بھیجا ہے'),
  ('ur.ahmedali', 17, 95, 'کہہ دو اگر زمین میں فرشتے اطمینان سے چلتے پھرتے ہوتے تو ہم آسمان سے ان پر فرشتہ ہی رسول بنا کر بھیجتے'),
  ('ur.ahmedali', 17, 96, 'کہہ دوکہ الله میرے اور تمہارے درمیان گواہ کافی ہے بے شک وہ اپنے بندوں سے خبردار دیکھنے والا ہے'),
  ('ur.ahmedali', 17, 97, 'اور جسے الله راہ دکھا دے وہی راہ پانے والا ہے اورجسے گمراہ کر دے پھر تو ان کے لیے الله کے سوا کوئی دوست نہیں پائے گا اور ہم نے انہیں قیامت کے دن مونہوں کے بل اندھے گونگے بہرے کر کے اٹھائیں گے ان کا ٹھکانا دوزخ ہے جب بجھنے لگے گی تو ان پر اوربھڑکا دیں گے'),
  ('ur.ahmedali', 17, 98, 'یہ ان کی سزا اس لیے ہے کہ انہوں نے ہماری آیتوں کا انکار کیا اور کہا کہ کیا جب ہم ہڈیاں اور چورا ہو جائیں گے توپھر نئے ے سرے سے بنا کر اٹھائے جائیں گے'),
  ('ur.ahmedali', 17, 99, 'کیا انہوں نے نہیں دیکھا جس الله نے آسمانوں اور زمین کوبنایا ہے وہ ان جیسے اوپر بھی بنا سکتا ہے اور اس نے ان کے لیے ایک وقت مقرر کر رکھا ہے جس میں کوئی شک نہیں اس پر بھی ظالم انکار کیئے بغیر نہ رہے'),
  ('ur.ahmedali', 17, 100, 'کہہ دو اگر میرے رب کی رحمت کے خزانے تمہارے ہاتھ میں ہوتے تو تم انہیں خرچ ہو جانے کے ڈر سے بند ہی کر رکھتے اور انسان بڑا تنگ دل ہے'),
  ('ur.ahmedali', 17, 101, 'اور البتہ تحقیق ہم نے موسیٰ کو نو کھلی نشانیاں دی تھیں پھر بھی بنی اسرائیل سےبھی پوچھ لو جب موسیٰ ان کے پاس آئے تو فرعون نے اسے کہا اے موسیٰ میں تو تجھے جادو کیا ہوا خیال کرتا ہوں'),
  ('ur.ahmedali', 17, 102, 'کہا یہ تو تجھے معلوم ہے کہ یہ آسمانوں اور زمین کے مالک ہی نے لوگوں کو سوجھانے کے لیے نازل کی ہیں اور بے شک میں تجھے اے فرعون ہلاک کیا ہوا خیال کرتا ہوں'),
  ('ur.ahmedali', 17, 103, 'پھر اس نے ارادہ کیا کہ انہیں اس زمین سے نکال دے تب ہم نے اسے اور اس کے سب ساتھیوں کو غرق کر دیا'),
  ('ur.ahmedali', 17, 104, 'اور اس کے بعد ہم نے بنی اسرائیل سے کہا کہ تم اس زمین میں آباد رہو پھر جب آخرت کا وعدہ آ ئے گا ہم تمہیں سمیٹ کر لے آئیں گے'),
  ('ur.ahmedali', 17, 105, 'اور ہم نے اس قرآن کو سچائی سے نازل کیا اور وہ سچائی سے ہی نازل ہوا اور ہم نے تجھے صرف خوشی سنانے والا اور ڈرانے والا بنا کر بھیجا ہے'),
  ('ur.ahmedali', 17, 106, 'اور ہم نے قرآن کو تھوڑا تھوڑا کر کے اتارا تاکہ تو مہلت کے ساتھ اسے لوگوں کو پڑھ کر سنائے اور ہم نے اسے آہستہ آہستہ اتارا ہے'),
  ('ur.ahmedali', 17, 107, 'کہہ دوتم اسے مانو یا نہ مانو بے شک وہ لوگ جنہیں اس سے پہلے علم دیا گیا ہے جب ان پر پڑھا جاتا ہے تو تھوڑیوں پر سجدہ میں گرتے ہیں'),
  ('ur.ahmedali', 17, 108, 'اورکہتے ہیں ہمارا رب پاک ہے بے شک ہمارے رب کا وعدہ ہو کر رہے گا'),
  ('ur.ahmedali', 17, 109, 'اور تھوڑیوں پر روتے ہوئے گرتے ہیں اور ان میں عاجزی زیادہ کر دیتا ہے'),
  ('ur.ahmedali', 17, 110, 'کہہ دو الله کہہ کر یا رحمٰن کہہ کر پکارو جس نام سے پکاروسب اسی کے عمدہ نام ہیں اور اپنی نماز میں نہ چلا کر پڑھ اور نہ بالکل ہی آہستہ پڑھ اور اس کے درمیان راستہ اختیار کر'),
  ('ur.ahmedali', 17, 111, 'اور کہہ دو سب تعریفیں الله کے لیے ہیں جس کی نہ کوئی اولاد ہے اورنہ کوئی اس کا سلطنت میں شریک ہے اور نہ کوئی کمزوری کی وجہ سے اس کا مددگار ہے اور اس کی بڑائی بیان کرتےر ہو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 17, 1, 'Kulunu (Muhammed\'i) bir gece Mescidi Haram\'dan (Mekke\'den), kendisine bir kısım ayetlerimizi göstermek için, çevresini mübarek kıldığımız Mescidi Aksa\'ya (Kudüs\'e) götüren Allah\'ın şanı yücedir. Doğrusu O, işitir ve görür.'),
  ('tr.diyanet', 17, 2, 'Musa\'ya kitap verdik. Ey Nuh\'la beraber taşıyarak kurtardığımız kimselerin soyundan olanlar! Beni bırakıp başkasını vekil edinmeyesiniz diye onu İsrailoğullarına doğruluk rehberi kıldık. Doğrusu Nuh, çok şükreden bir kuldu.'),
  ('tr.diyanet', 17, 3, 'Musa\'ya kitap verdik. Ey Nuh\'la beraber taşıyarak kurtardığımız kimselerin soyundan olanlar! Beni bırakıp başkasını vekil edinmeyesiniz diye onu İsrailoğullarına doğruluk rehberi kıldık. Doğrusu Nuh, çok şükreden bir kuldu.'),
  ('tr.diyanet', 17, 4, 'İsrailoğullarına Kitap\'da: "Doğrusu yeryüzünde iki defa bozgunculuk yapacak ve kibirlendikçe kibirleneceksiniz" diye bildirdik.'),
  ('tr.diyanet', 17, 5, '"Bu ikiden birincisinin vakti gelince, üzerinize pek güçlü olan kullarımızı salacağız. Onlar memleketlerinizde her köşeyi kontrollerine alacaklar. Bu, yerine gelecek bir vaaddir."'),
  ('tr.diyanet', 17, 6, '"Bunun ardından sizi onlara galip getireceğiz; mallar ve oğullarla size yardım edecek ve sizin sayınızı artıracağız."'),
  ('tr.diyanet', 17, 7, 'İyilik ederseniz kendinize iyilik etmiş olursunuz. Kötülük ederseniz o da kendinizedir. İki vaadden ikincisinin vakti gelince, yüzünüzü üzüntüye sokmaları, kötülük yapmaları, önceden Mescid\'e girdikleri gibi girmeleri, ele geçirdikleri yerleri harap etmeleri için onları tekrar göndereceğiz.'),
  ('tr.diyanet', 17, 8, 'Umulur ki Rabbiniz size acır; ama siz dönerseniz Biz de döneriz. Cehennemi, inkarcılara bir zindan kılmışızdır.'),
  ('tr.diyanet', 17, 9, 'Doğrusu bu Kuran en doğru yola götürür ve yararlı iş yapan müminlere büyük ecir olduğunu, ahirete inanmayanlara can yakıcı bir azap hazırladığımızı müjdeler.'),
  ('tr.diyanet', 17, 10, 'Doğrusu bu Kuran en doğru yola götürür ve yararlı iş yapan müminlere büyük ecir olduğunu, ahirete inanmayanlara can yakıcı bir azap hazırladığımızı müjdeler.'),
  ('tr.diyanet', 17, 11, 'İnsan iyiliğin gelmesine dua ettiği gibi, kötülüğün gelmesine de dua eder. Esasen insanoğlu acelecidir.'),
  ('tr.diyanet', 17, 12, 'Gece ve gündüzü varlığımıza birer delil kıldık. Bir delil olan geceyi kaldırıp yine bir delil olan gündüzü Rabbinizin bol nimetini aramanız, yılların sayısını ve hesabını bilmeniz için aydınlık kıldık. Her şeyi uzun uzadıya açıkladık.'),
  ('tr.diyanet', 17, 13, 'Her insanın boynuna işlediklerini dolarız ve kıyamet günü açılmış bulacağı Kitap\'ı önüne çıkarırız.'),
  ('tr.diyanet', 17, 14, '"Kitabını oku, bugün, hesap görücü olarak sen kendine yetersin."'),
  ('tr.diyanet', 17, 15, 'Kim doğru yola gelirse ancak kendi lehine yola gelmiş ve kim de saparsa ancak kendi aleyhine sapmıştır. Kimse kimsenin günahını çekmez. Biz peygamber göndermedikçe kimseye azabetmeyiz.'),
  ('tr.diyanet', 17, 16, 'Bir şehri yok etmek istediğimiz zaman, şımarık varlıklarına yola gelmelerini emrederiz, ama onlar yoldan çıkarlar. Artık o şehir yok olmayı hakeder. Biz de onu yerle bir ederiz.'),
  ('tr.diyanet', 17, 17, 'Nuh\'dan sonra nice nesilleri yok etmişizdir. Kullarının günahlarından haberdar ve onları gören olarak Rabbin yeter.'),
  ('tr.diyanet', 17, 18, 'Dünyayı isteyene istediğimiz kimseye dilediğimiz kadar hemen veririz. Sonra ona cehennemi hazırlarız; yerilmiş ve kovulmuş olarak oraya girer.'),
  ('tr.diyanet', 17, 19, 'Ahireti isteyip, inanmış olarak onun için gerekli çalışmada bulunan kimselerin, işte onların çalışmaları şükre değer.'),
  ('tr.diyanet', 17, 20, 'Onların ve bunların her birine Rabbinin nimetinden ulaştırırız. Esasen Rabbinin nimeti kimseye yasak kılınmış değildir.'),
  ('tr.diyanet', 17, 21, 'Onları birbirlerinden nasıl üstün kıldığımıza bir bak! Doğrusu ahirette daha büyük dereceler ve daha büyük üstünlükler vardır.'),
  ('tr.diyanet', 17, 22, 'Allah\'la beraber başka bir tanrı edinme, yoksa yerilmiş ve tek başına kalmış olursun.'),
  ('tr.diyanet', 17, 23, 'Rabbin, yalnız Kendisine tapmanızı ve ana babaya iyilik etmeyi buyurmuştur. Eğer ikisinden biri veya her ikisi, senin yanında iken ihtiyarlayacak olursa, onlara karşı "Öf" bile demeyesin, onları azarlamayasın. İkisine de hep tatlı söz söyleyesin.'),
  ('tr.diyanet', 17, 24, 'Onlara acıyarak alçak gönüllülük kanatlarını ger ve: "Rabbim! Küçükken beni yetiştirdikleri gibi sen de onlara merhamet et!" de.'),
  ('tr.diyanet', 17, 25, 'İçinizde olanı en iyi Rabbiniz bilir. İyi kimselerseniz bilin ki O şüphesiz, Kendine baş vuranları bağışlar.'),
  ('tr.diyanet', 17, 26, 'Yakınına, düşküne, yolcuya hakkını ver; elindekileri saçıp savurma.'),
  ('tr.diyanet', 17, 27, 'Saçıp savuranlar, şüphesiz şeytanlarla kardeş olmuş olurlar; şeytan ise Rabbine karşı pek nankördür.'),
  ('tr.diyanet', 17, 28, 'Rabbin\'den umduğun rahmeti elde etmek için, hak sahiblerinden yüz çevirmek zorunda kalırsan, onlara hiç değilse tatlı bir söz söyle.'),
  ('tr.diyanet', 17, 29, 'Elini boynuna bağlayıp cimri kesilme, büsbütün de açıp tutumsuz olma, yoksa pişman olur, açıkta kalırsın.'),
  ('tr.diyanet', 17, 30, 'Doğrusu senin Rabbin dilediği kimsenin rızkını genişletir ve bir ölçüye göre verir. O kullarını gören ve haberdar olandır.'),
  ('tr.diyanet', 17, 31, 'Çocuklarınızı yoksulluk korkusuyla öldürmeyin. Biz onlara da size de rızık veririz. Onları öldürmek, şüphesiz büyük bir günahtır.'),
  ('tr.diyanet', 17, 32, 'Sakın zinaya yaklaşmayın; doğrusu bu çirkindir, kötü bir yoldur.'),
  ('tr.diyanet', 17, 33, 'Allah\'ın haram kıldığı cana haksız yere kıymayın. Haksız yere öldürülenin velisine bir yetki tanımışızdır. Artık o da öldürmekte aşırı gitmesin. Zira kendisi ne de olsa yardım görmüştür.'),
  ('tr.diyanet', 17, 34, 'Yetimin malına ergin çağa ulaşana kadar en güzel şeklin dışında yaklaşmayın. Ahdi de yerine getirin, doğrusu verilen ahidde sorumluluk vardır.'),
  ('tr.diyanet', 17, 35, 'Bir şeyi ölçtüğünüz zaman, ölçüyü tam tutun, doğru teraziyle tartın. Böyle yapmak, sonuç itibariyle daha güzel ve daha iyidir.'),
  ('tr.diyanet', 17, 36, 'Bilmediğin şeyin ardına düşme; doğrusu kulak, göz ve kalp, bunların hepsi o şeyden sorumlu olur.'),
  ('tr.diyanet', 17, 37, 'Yeryüzünde böbürlenerek yürüme, çünkü sen ne yeri delebilir ve ne de boyca dağlara ulaşabilirsin.'),
  ('tr.diyanet', 17, 38, 'Rabbinin katında bunların hepsi beğenilmeyen kötü şeylerdir.'),
  ('tr.diyanet', 17, 39, 'Bunlar Rabbinin sana bildirdiği hikmetlerdir. Sakın Allah\'la beraber başka tanrı edinme. Yoksa yerilmiş ve kovulmuş olarak cehenneme atılırsın.'),
  ('tr.diyanet', 17, 40, 'Rabbiniz oğulları size ayırdı, seçti de kendisi için kız olarak melekleri mi edindi? Doğrusu siz büyük söz söylüyorsunuz.'),
  ('tr.diyanet', 17, 41, 'Biz, and olsun ki öğüt almaları için bu Kuran\'da bunları türlü türlü açıkladık. Fakat bu açıklamalar ancak onların nefretini artırmıştır.'),
  ('tr.diyanet', 17, 42, 'De ki: "Eğer dedikleri gibi Allah\'la beraber tanrılar bulunsaydı, o takdirde hepsi arşın sahibiyle savaşmaya bir yol ararlardı."'),
  ('tr.diyanet', 17, 43, 'O, onların söylediklerinden Münezzeh\'tir, Yüce\'dir, Ulu\'dur.'),
  ('tr.diyanet', 17, 44, 'Yedi gök, yer ve bunlarda bulunanlar O\'nu tesbih eder; O\'nu hamd ile tesbih etmeyen hiçbir şey yoktur; fakat siz onların tesbihlerini anlamazsınız. Doğrusu O Halim olandır, Bağışlayan\'dır.'),
  ('tr.diyanet', 17, 45, 'Kuran okuduğun zaman senin ile ahirete inanmayan kimseler arasına görünmeyen bir perde çekeriz.'),
  ('tr.diyanet', 17, 46, 'Kuran\'ı anlarlar diye kalblerine örtüler ve kulaklarına da ağırlık koyduk. Kuran\'da Rabbini bir tek olarak andığın zaman, onlar ürkerek ardlarına dönerler.'),
  ('tr.diyanet', 17, 47, 'Seni dinledikleri zaman neye kulak verdiklerini ve gizli toplantılarında zalimlerin: "Siz sadece büyülenmiş bir adama uyuyorsunuz" dediklerini Biz çok iyi biliriz.'),
  ('tr.diyanet', 17, 48, 'Sana nasıl misaller verdiklerine bir bak! Bu yüzden sapmışlardır, artık bir yol da bulamamaktadırlar.'),
  ('tr.diyanet', 17, 49, '"Biz kemik ve ufalanmış toprak olduğumuz zaman, yeniden mutlaka dirilecek miyiz? derler.'),
  ('tr.diyanet', 17, 50, 'De ki: "İster taş veya demir ya da kalbinizde büyüttüğünüz başka bir yaratık olun, yine de dirileceksiniz." "Bizi tekrar kim diriltir?" derler; de ki: "Sizi ilk defa yaratan." Sana başlarını sallayarak: "Ne zamandır bu?" derler. "Yakında olması mümkündür" de.'),
  ('tr.diyanet', 17, 51, 'De ki: "İster taş veya demir ya da kalbinizde büyüttüğünüz başka bir yaratık olun, yine de dirileceksiniz." "Bizi tekrar kim diriltir?" derler; de ki: "Sizi ilk defa yaratan." Sana başlarını sallayarak: "Ne zamandır bu?" derler. "Yakında olması mümkündür" de.'),
  ('tr.diyanet', 17, 52, 'Sizi çağırdığı gün, O\'na hamdederek davetine uyarsınız ve kabirlerinizde pek az bir müddet kaldığınızı sanırsınız.'),
  ('tr.diyanet', 17, 53, 'İnanan kullarıma söyle, en güzel şekilde konuşsunlar. Doğrusu şeytan aralarını bozmak ister. Şeytan şüphesiz insanın apaçık düşmanıdır.'),
  ('tr.diyanet', 17, 54, 'Rabbiniz sizi daha iyi bilir. Dilerse size merhamet eder veya dilerse size azabeder. Biz seni onlara vekil olarak göndermedik.'),
  ('tr.diyanet', 17, 55, 'Göklerde ve yerde olan kimseleri Rabbin daha iyi bilir. And olsun ki peygamberleri birbirinden üstün kılmış ve Davud\'a Zebur vermişizdir.'),
  ('tr.diyanet', 17, 56, 'De ki: "Allah\'tan başka tanrı olduğunu sandıklarınızı çağırın; sizin bir sıkıntınızı gidermeye ve onu değiştirmeye güçleri yetmez."'),
  ('tr.diyanet', 17, 57, 'Taptıkları putlar Rablerine daha yakın olmak için vesile ararlar. O\'nun rahmetini umar, azabından korkarlar. Zira Rabbinin azabı korkmağa değer.'),
  ('tr.diyanet', 17, 58, 'Kıyamet gününden önce ortadan kaldırmayacağımız veya çetin azaba uğratmayacağımız bir şehir yoktur. Bu, Kitap\'da yazılıdır.'),
  ('tr.diyanet', 17, 59, 'Bizi mucize göndermekten alıkoyan, ancak, öncekilerin onları yalanlamış olmalarıdır. Semud milletine gözle görülebilen bir mucize, bir dişi deve vermiştik de ona zulmetmişlerdi. Oysa Biz mucizeleri yalnız korkutmak için göndeririz.'),
  ('tr.diyanet', 17, 60, 'Sana: "Rabbin şüphesiz insanları kuşatmıştır" demiştik; sana gösterdiğimiz rüya ile ve Kuran\'da lanetlenmiş ağaçla, sadece insanları denedik. Biz onları korkutuyoruz, fakat bu onlara büyük taşkınlık vermekten başka birşeye yaramıyor.'),
  ('tr.diyanet', 17, 61, 'Meleklere: "Adem\'e secde edin" demiştik, İblis\'ten başka hepsi secde etmiş, o ise: "çamurdan yarattığına mı secde edeceğim?" demişti.'),
  ('tr.diyanet', 17, 62, '"Benden üstün kıldığını görüyor musun? Kıyamet gününe kadar beni ertelersen, and olsun ki, azı bir yana, onun soyunu kendi buyruğum altına alacağım" demişti.'),
  ('tr.diyanet', 17, 63, 'Allah: "Haydi git! Onlardan sana kim uyarsa bil ki, cehennem hepinizin cezası olur, hem de tam bir ceza" dedi.'),
  ('tr.diyanet', 17, 64, '"Sesinle, gücünün yettiğini yerinden oynat, onlara karşı yaya ve atlılarınla haykırarak yürü, mallarına ve çocuklarına ortak ol, onlara vaadlerde bulun ama şeytan sadece onları aldatmak için vaadeder.'),
  ('tr.diyanet', 17, 65, 'Doğrusu Benim mümin kullarım üzerinde senin bir hakimiyetin olamaz. Rabbin vekil olarak yeter."'),
  ('tr.diyanet', 17, 66, 'Rabbiniz, bol nimetinden elde edesiniz diye, denizde gemileri sizin için yüzdürür. O, size merhamet eder.'),
  ('tr.diyanet', 17, 67, 'Denizde bir sıkıntıya düştüğünüz zaman, Allah\'tan başka yalvardıklarınız kaybolup gider, fakat O sizi karaya çıkararak kurtarınca yüz çevirirsiniz. Zaten insan pek nankördür.'),
  ('tr.diyanet', 17, 68, 'Onun karada da, sizi yere batırmasından veya başınıza taş yağdırmasından güvende misiniz? Sonra kendinize bir koruyucu da bulamazsınız.'),
  ('tr.diyanet', 17, 69, 'Yoksa sizi tekrar denize döndürüp, üzerinize ortalığı yıkan bir fırtına gönderip, inkarlarınızdan ötürü sizi suda boğmasından güvende misiniz? O zaman bize soru soracak bir yardımcı da bulamazsınız.'),
  ('tr.diyanet', 17, 70, 'And olsun ki, biz insanoğullarını şerefli kıldık, onların karada ve denizde gezmesini sağladık, temiz şeylerle onları rızıklandırdık, yaratıklarımızın pek çoğundan üstün kıldık.'),
  ('tr.diyanet', 17, 71, 'Bir gün bütün insanları önderleriyle beraber çağırırız. O gün kitabı sağından verilenler, işte onlar kitablarını okurlar. Onlara kıl kadar haksizlik edilmez.'),
  ('tr.diyanet', 17, 72, 'Bu dünyada kalbi kör olan, ahirette de kör ve daha şaşkındır.'),
  ('tr.diyanet', 17, 73, 'Seni, sana vahyettiğimizden ayırıp başka bir şeyi Bize karşı uydurman için uğraşırlar. O zaman seni dost edinirler.'),
  ('tr.diyanet', 17, 74, 'Sana sebat vermemiş olsaydık, and olsun ki, az da olsa onlara meyledecektin.'),
  ('tr.diyanet', 17, 75, 'O takdirde sana, hayatın da ölümün de, kat kat azabını tattırırdık. Sonra bize karşı bir yardımcı da bulamazdın.'),
  ('tr.diyanet', 17, 76, 'Memleketinden çıkarmak için seni nerdeyse zorlayacaklardı. O takdirde senin ardından onlar da pek az kalabilirlerdi.'),
  ('tr.diyanet', 17, 77, 'Bu, senden önce gönderdiğimiz peygamberlerimize de uyguladığımız yasadır. Sen bizim yasamızda değişiklik bulamazsın.'),
  ('tr.diyanet', 17, 78, 'Güneşin batıya yönelmesinden gecenin kararmasına kadar namaz kıl; sabah vakti de namaz kıl, zira sabah namazına melekler şahit olur.'),
  ('tr.diyanet', 17, 79, 'Geceleyin uyanıp, yalnız sana mahsus olarak fazladan namaz kıl. Belki de Rabbin seni övülecek makama yükseltir.'),
  ('tr.diyanet', 17, 80, 'De ki: "Rabbim! Beni dahil edeceğin yere hoşnutluk ve esenlikle dahil et; çıkaracağın yerden de hoşnutluk ve esenlikle çıkar. Katından beni destekleyecek bir kuvvet ver."'),
  ('tr.diyanet', 17, 81, 'De ki: "Hak geldi, batıl ortadan kalkmaya mahkumdur."'),
  ('tr.diyanet', 17, 82, 'Kuran\'dan inananlara rahmet ve şifa olan şeyler indiriyoruz. O, zalimlerin ise sadece kaybını artırır.'),
  ('tr.diyanet', 17, 83, 'İnsana nimet verdiğimiz zaman yüz çevirerek yan çizer; başına bir kötülük gelince de yese düşer.'),
  ('tr.diyanet', 17, 84, 'De ki: "Herkes yaradılışına göre davranır. Rabbiniz kimin en doğru yolda olduğunu bilir."'),
  ('tr.diyanet', 17, 85, 'Sana ruhun ne olduğunu soruyorlar, de ki: "Ruh, Rabbimin emrinden ibarettir. Bu hususta size pek az bilgi verilmiştir."'),
  ('tr.diyanet', 17, 86, 'Dileseydik and olsun ki, sana vahyettiğimizi alıp götürürdük. Sonra bize karşı duracak bir vekil de bulamazdın.'),
  ('tr.diyanet', 17, 87, 'Bunu yapmayışı ancak Rabbinin sana merhamet etmesindendir. Çünkü O\'nun sana olan nimeti büyüktür.'),
  ('tr.diyanet', 17, 88, 'De ki: "İnsanlar ve cinler, birbirine yardımcı olarak bu Kuran\'ın bir benzerini ortaya koymak için bir araya gelseler, and olsun ki, yine de benzerini ortaya koyamazlar."'),
  ('tr.diyanet', 17, 89, 'And olsun ki, biz Kuran\'da insanlara türlü türlü misal gösterip açıkladık. Öyleyken insanların çoğu nankör olmakta direndiler.'),
  ('tr.diyanet', 17, 90, 'Şöyle söylediler: "Bize, yerden kaynaklar fışkırtmadıkça sana inanmayacağız",'),
  ('tr.diyanet', 17, 91, '"Veya hurmalıkların, bağların olup, aralarında ırmaklar akıtmalısın."'),
  ('tr.diyanet', 17, 92, '"Yahut da iddia ettiğin gibi, göğü tepemize parça parça düşürmeli, ya da Allah\'ı ve melekleri karşımıza getirmelisin."'),
  ('tr.diyanet', 17, 93, '"Veya altın bir evin olmalı, yahut göğe yükselmelisin ama oradan okuyacağımız bir kitap indirmezsen yine o yükselmene inanmayacağız." De ki: "Fesubhanallah! Ben peygamber olan bir insandan başka bir şey miyim? "'),
  ('tr.diyanet', 17, 94, 'İnsanlara doğruluk rehberi geldiği zaman, inanmalarına engel olan, sadece: "Allah peygamber olarak bir insan mı gönderdi?" demiş olmalarıdır.'),
  ('tr.diyanet', 17, 95, 'De ki: "Yeryüzünde yerleşip dolaşanlar melek olsalardı, biz de onlara gökten peygamber olarak bir melek gönderirdik."'),
  ('tr.diyanet', 17, 96, 'De ki: "Benimle sizin aranızda şahit olarak Allah yeter. Doğrusu O, kullarını görür, haberdardır."'),
  ('tr.diyanet', 17, 97, 'Allah\'ın doğru yola eriştirdiği kimse hak yoldadır. Kimleri de saptırırsa, artık onlar için Allah\'dan başka dostlar bulamazsın. Biz onları kıyamet günü yüzükoyun, körler, dilsizler ve sağırlar olarak haşrederiz. Varacakları yer cehennemdir. Onun ateşi ne zaman sönmeye yüz tutsa hemen alevini artırırız.'),
  ('tr.diyanet', 17, 98, 'Bu, ayetlerimizi inkar etmelerinin ve: "Kemik ve ufalanmış toprak olduğumuzda mı yeniden dirileceğiz?" demelerinin cezasıdır.'),
  ('tr.diyanet', 17, 99, 'Gökleri ve yeri yaratan Allah\'ın, onların benzerlerini de tekrar yaratmaya Kadir olduğunu görmezler mi? Onlar için şüphe götürmeyen bir süre tayin etmiştir. Öyleyken, zalimler, inkarcılıkta hala direnirler.'),
  ('tr.diyanet', 17, 100, 'De ki: "Rabbimin rahmet hazinelerine siz sahip olsaydınız, tükenir korkusuyla yine de cimrilik ederdiniz. Zaten insanlar pek cimridir."'),
  ('tr.diyanet', 17, 101, 'And olsun ki, Musa\'ya dokuz tane apaçık mucize verdik. İsrailoğullarına sor, Musa onlara geldiğinde, Firavun kendisine: "Ey Musa! Ben seni büyülenmiş sanıyorum" demişti.'),
  ('tr.diyanet', 17, 102, 'Musa da: "And olsun ki, bunları göklerin ve yerin Rabbinin açık belgeler olarak indirdiğini biliyorsun. Ey Firavun! Doğrusu senin mahvolacağını sanıyorum" demişti.'),
  ('tr.diyanet', 17, 103, 'Firavun bunun üzerine onları memleketten sürmek istedi. Biz de onu ve beraberindekilerin hepsini suda boğduk.'),
  ('tr.diyanet', 17, 104, 'Sonra İsrailoğullarına: "Bu memlekette siz oturun, kıyamet koptuğunda hepinizi bir araya getiririz." dedik.'),
  ('tr.diyanet', 17, 105, 'Kuran\'ı ancak hak olarak indirdik ve o da indiği gibi hak olarak kaldı. Seni de yalnız müjdeci ve uyarıcı olarak gönderdik.'),
  ('tr.diyanet', 17, 106, 'Kuran\'ı, insanlara ağır ağır okuman için, bölüm bölüm indirdik ve onu gerektikçe indirdik.'),
  ('tr.diyanet', 17, 107, 'De ki: "Kuran\'a ister inanın, isten inanmayın, O\'ndan önceki bilginlere o okunduğu zaman, yüzleri üzerine secdeye varırlar" ve "Rabbimiz münezzehtir. Rabbimiz\'in sözü şüphesiz yerine gelecektir" derler.'),
  ('tr.diyanet', 17, 108, 'De ki: "Kuran\'a ister inanın, isten inanmayın, O\'ndan önceki bilginlere o okunduğu zaman, yüzleri üzerine secdeye varırlar" ve "Rabbimiz münezzehtir. Rabbimiz\'in sözü şüphesiz yerine gelecektir" derler.'),
  ('tr.diyanet', 17, 109, 'Ağlayarak yüz üstü yere kapanırlar; bu, onların gönüllerindeki saygıyı artırır.'),
  ('tr.diyanet', 17, 110, 'De ki: "İster Allah deyin, ister Rahman deyin, hangisini derseniz deyin, en güzel isimler O\'nundur." Namaz kılarken sesini yükseltme, gizli de okuma, ikisi ortasında bir yol tut.'),
  ('tr.diyanet', 17, 111, 'De ki: "Hamd, çocuk edinmemiş olan, hükümranlığında ortağı bulunmayan, düşkün olmayıp yardımcıya da ihtiyaç göstermeyen Allah\'a mahsustur." O\'nu gereği gibi büyükle.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 17, 1, 'Maha Suci Allah, yang telah memperjalankan hamba-Nya pada suatu malam dari Al Masjidil Haram ke Al Masjidil Aqsha yang telah Kami berkahi sekelilingnya agar Kami perlihatkan kepadanya sebagian dari tanda-tanda (kebesaran) Kami. Sesungguhnya Dia adalah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 17, 2, 'Dan Kami berikan kepada Musa kitab (Taurat) dan Kami jadikan kitab Taurat itu petunjuk bagi Bani Israil (dengan firman): "Janganlah kamu mengambil penolong selain Aku,'),
  ('id.indonesian', 17, 3, '(yaitu) anak cucu dari orang-orang yang Kami bawa bersama-sama Nuh. Sesungguhnya dia adalah hamba (Allah) yang banyak bersyukur.'),
  ('id.indonesian', 17, 4, 'Dan telah Kami tetapkan terhadap Bani Israil dalam Kitab itu: "Sesungguhnya kamu akan membuat kerusakan di muka bumi ini dua kali dan pasti kamu akan menyombongkan diri dengan kesombongan yang besar".'),
  ('id.indonesian', 17, 5, 'Maka apabila datang saat hukuman bagi (kejahatan) pertama dari kedua (kejahatan) itu, Kami datangkan kepadamu hamba-hamba Kami yang mempunyai kekuatan yang besar, lalu mereka merajalela di kampung-kampung, dan itulah ketetapan yang pasti terlaksana.'),
  ('id.indonesian', 17, 6, 'Kemudian Kami berikan kepadamu giliran untuk mengalahkan mereka kembali dan Kami membantumu dengan harta kekayaan dan anak-anak dan Kami jadikan kamu kelompok yang lebih besar.'),
  ('id.indonesian', 17, 7, 'Jika kamu berbuat baik (berarti) kamu berbuat baik bagi dirimu sendiri dan jika kamu berbuat jahat, maka (kejahatan) itu bagi dirimu sendiri, dan apabila datang saat hukuman bagi (kejahatan) yang kedua, (Kami datangkan orang-orang lain) untuk menyuramkan muka-muka kamu dan mereka masuk ke dalam mesjid, sebagaimana musuh-musuhmu memasukinya pada kali pertama dan untuk membinasakan sehabis-habisnya apa saja yang mereka kuasai.'),
  ('id.indonesian', 17, 8, 'Mudah-mudahan Tuhanmu akan melimpahkan rahmat(Nya) kepadamu; dan sekiranya kamu kembali kepada (kedurhakaan) niscaya Kami kembali (mengazabmu) dan Kami jadikan neraka Jahannam penjara bagi orang-orang yang tidak beriman.'),
  ('id.indonesian', 17, 9, 'Sesungguhnya Al Quran ini memberikan petunjuk kepada (jalan) yang lebih lurus dan memberi khabar gembira kepada orang-orang Mu\'min yang mengerjakan amal saleh bahwa bagi mereka ada pahala yang besar,'),
  ('id.indonesian', 17, 10, 'dan sesungguhnya orang-orang yang tidak beriman kepada kehidupan akhirat, Kami sediakan bagi mereka azab yang pedih.'),
  ('id.indonesian', 17, 11, 'Dan manusia mendoa untuk kejahatan sebagaimana ia mendoa untuk kebaikan. Dan adalah manusia bersifat tergesa-gesa.'),
  ('id.indonesian', 17, 12, 'Dan Kami jadikan malam dan siang sebagai dua tanda, lalu Kami hapuskan tanda malam dan Kami jadikan tanda siang itu terang, agar kamu mencari kurnia dari Tuhanmu, dan supaya kamu mengetahui bilangan tahun-tahun dan perhitungan. Dan segala sesuatu telah Kami terangkan dengan jelas.'),
  ('id.indonesian', 17, 13, 'Dan tiap-tiap manusia itu telah Kami tetapkan amal perbuatannya (sebagaimana tetapnya kalung) pada lehernya. Dan Kami keluarkan baginya pada hari kiamat sebuah kitab yang dijumpainya terbuka.'),
  ('id.indonesian', 17, 14, '"Bacalah kitabmu, cukuplah dirimu sendiri pada waktu ini sebagai penghisab terhadapmu".'),
  ('id.indonesian', 17, 15, 'Barangsiapa yang berbuat sesuai dengan hidayah (Allah), maka sesungguhnya dia berbuat itu untuk (keselamatan) dirinya sendiri; dan barangsiapa yang sesat maka sesungguhnya dia tersesat bagi (kerugian) dirinya sendiri. Dan seorang yang berdosa tidak dapat memikul dosa orang lain, dan Kami tidak akan mengazab sebelum Kami mengutus seorang rasul.'),
  ('id.indonesian', 17, 16, 'Dan jika Kami hendak membinasakan suatu negeri, maka Kami perintahkan kepada orang-orang yang hidup mewah di negeri itu (supaya mentaati Allah) tetapi mereka melakukan kedurhakaan dalam negeri itu, maka sudah sepantasnya berlaku terhadapnya perkataan (ketentuan Kami), kemudian Kami hancurkan negeri itu sehancur-hancurnya.'),
  ('id.indonesian', 17, 17, 'Dan berapa banyaknya kaum sesudah Nuh telah Kami binasakan. Dan cukuplah Tuhanmu Maha Mengetahui lagi Maha Melihat dosa hamba-hamba-Nya.'),
  ('id.indonesian', 17, 18, 'Barangsiapa menghendaki kehidupan sekarang (duniawi), maka Kami segerakan baginya di dunia itu apa yang kami kehendaki bagi orang yang kami kehendaki dan Kami tentukan baginya neraka jahannam; ia akan memasukinya dalam keadaan tercela dan terusir.'),
  ('id.indonesian', 17, 19, 'Dan barangsiapa yang menghendaki kehidupan akhirat dan berusaha ke arah itu dengan sungguh-sungguh sedang ia adalah mukmin, maka mereka itu adalah orang-orang yang usahanya dibalasi dengan baik.'),
  ('id.indonesian', 17, 20, 'Kepada masing-masing golongan baik golongan ini maupun golongan itu Kami berikan bantuan dari kemurahan Tuhanmu. Dan kemurahan Tuhanmu tidak dapat dihalangi.'),
  ('id.indonesian', 17, 21, 'Perhatikanlah bagaimana Kami lebihkan sebagian dari mereka atas sebagian (yang lain). Dan pasti kehidupan akhirat lebih tinggi tingkatnya dan lebih besar keutamaannya.'),
  ('id.indonesian', 17, 22, 'Janganlah kamu adakan tuhan yang lain di samping Allah, agar kamu tidak menjadi tercela dan tidak ditinggalkan (Allah).'),
  ('id.indonesian', 17, 23, 'Dan Tuhanmu telah memerintahkan supaya kamu jangan menyembah selain Dia dan hendaklah kamu berbuat baik pada ibu bapakmu dengan sebaik-baiknya. Jika salah seorang di antara keduanya atau kedua-duanya sampai berumur lanjut dalam pemeliharaanmu, maka sekali-kali janganlah kamu mengatakan kepada keduanya perkataan "ah" dan janganlah kamu membentak mereka dan ucapkanlah kepada mereka perkataan yang mulia.'),
  ('id.indonesian', 17, 24, 'Dan rendahkanlah dirimu terhadap mereka berdua dengan penuh kesayangan dan ucapkanlah: "Wahai Tuhanku, kasihilah mereka keduanya, sebagaimana mereka berdua telah mendidik aku waktu kecil".'),
  ('id.indonesian', 17, 25, 'Tuhanmu lebih mengetahui apa yang ada dalam hatimu; jika kamu orang-orang yang baik, maka sesungguhnya Dia Maha Pengampun bagi orang-orang yang bertaubat.'),
  ('id.indonesian', 17, 26, 'Dan berikanlah kepada keluarga-keluarga yang dekat akan haknya, kepada orang miskin dan orang yang dalam perjalanan dan janganlah kamu menghambur-hamburkan (hartamu) secara boros.'),
  ('id.indonesian', 17, 27, 'Sesungguhnya pemboros-pemboros itu adalah saudara-saudara syaitan dan syaitan itu adalah sangat ingkar kepada Tuhannya.'),
  ('id.indonesian', 17, 28, 'Dan jika kamu berpaling dari mereka untuk memperoleh rahmat dari Tuhanmu yang kamu harapkan, maka katakanlah kepada mereka ucapan yang pantas.'),
  ('id.indonesian', 17, 29, 'Dan janganlah kamu jadikan tanganmu terbelenggu pada lehermu dan janganlah kamu terlalu mengulurkannya karena itu kamu menjadi tercela dan menyesal.'),
  ('id.indonesian', 17, 30, 'Sesungguhnya Tuhanmu melapangkan rezeki kepada siapa yang Dia kehendaki dan menyempitkannya; sesungguhnya Dia Maha Mengetahui lagi Maha Melihat akan hamba-hamba-Nya.'),
  ('id.indonesian', 17, 31, 'Dan janganlah kamu membunuh anak-anakmu karena takut kemiskinan. Kamilah yang akan memberi rezeki kepada mereka dan juga kepadamu. Sesungguhnya membunuh mereka adalah suatu dosa yang besar.'),
  ('id.indonesian', 17, 32, 'Dan janganlah kamu mendekati zina; sesungguhnya zina itu adalah suatu perbuatan yang keji. Dan suatu jalan yang buruk.'),
  ('id.indonesian', 17, 33, 'Dan janganlah kamu membunuh jiwa yang diharamkan Allah (membunuhnya), melainkan dengan suatu (alasan) yang benar. Dan barangsiapa dibunuh secara zalim, maka sesungguhnya Kami telah memberi kekuasaan kepada ahli warisnya, tetapi janganlah ahli waris itu melampaui batas dalam membunuh. Sesungguhnya ia adalah orang yang mendapat pertolongan.'),
  ('id.indonesian', 17, 34, 'Dan janganlah kamu mendekati harta anak yatim, kecuali dengan cara yang lebih baik (bermanfaat) sampai ia dewasa dan penuhilah janji; sesungguhnya janji itu pasti diminta pertanggungan jawabnya.'),
  ('id.indonesian', 17, 35, 'Dan sempurnakanlah takaran apabila kamu menakar, dan timbanglah dengan neraca yang benar. Itulah yang lebih utama (bagimu) dan lebih baik akibatnya.'),
  ('id.indonesian', 17, 36, 'Dan janganlah kamu mengikuti apa yang kamu tidak mempunyai pengetahuan tentangnya. Sesungguhnya pendengaran, penglihatan dan hati, semuanya itu akan diminta pertanggungan jawabnya.'),
  ('id.indonesian', 17, 37, 'Dan janganlah kamu berjalan di muka bumi ini dengan sombong, karena sesungguhnya kamu sekali-kali tidak dapat menembus bumi dan sekali-kali kamu tidak akan sampai setinggi gunung.'),
  ('id.indonesian', 17, 38, 'Semua itu kejahatannya amat dibenci di sisi Tuhanmu.'),
  ('id.indonesian', 17, 39, 'Itulah sebagian hikmah yang diwahyukan Tuhanmu kepadamu. Dan janganlah kamu mengadakan tuhan yang lain di samping Allah, yang menyebabkan kamu dilemparkan ke dalam neraka dalam keadaan tercela lagi dijauhkan (dari rahmat Allah).'),
  ('id.indonesian', 17, 40, 'Maka apakah patut Tuhan memilihkan bagimu anak-anak laki-laki sedang Dia sendiri mengambil anak-anak perempuan di antara para malaikat? Sesungguhnya kamu benar-benar mengucapkan kata-kata yang besar (dosanya).'),
  ('id.indonesian', 17, 41, 'Dan sesungguhnya dalam Al Quran ini Kami telah ulang-ulangi (peringatan-peringatan), agar mereka selalu ingat. Dan ulangan peringatan itu tidak lain hanyalah menambah mereka lari (dari kebenaran).'),
  ('id.indonesian', 17, 42, 'Katakanlah: "Jikalau ada tuhan-tuhan di samping-Nya, sebagaimana yang mereka katakan, niscaya tuhan-tuhan itu mencari jalan kepada Tuhan yang mempunyai \'Arsy".'),
  ('id.indonesian', 17, 43, 'Maha Suci dan Maha Tinggi Dia dari apa yang mereka katakan dengan ketinggian yang sebesar-besarnya.'),
  ('id.indonesian', 17, 44, 'Langit yang tujuh, bumi dan semua yang ada di dalamnya bertasbih kepada Allah. Dan tak ada suatupun melainkan bertasbih dengan memuji-Nya, tetapi kamu sekalian tidak mengerti tasbih mereka. Sesungguhnya Dia adalah Maha Penyantun lagi Maha Pengampun.'),
  ('id.indonesian', 17, 45, 'Dan apabila kamu membaca Al Quran niscaya Kami adakan antara kamu dan orang-orang yang tidak beriman kepada kehidupan akhirat, suatu dinding yang tertutup,'),
  ('id.indonesian', 17, 46, 'dan Kami adakan tutupan di atas hati mereka dan sumbatan di telinga mereka, agar mereka tidak dapat memahaminya. Dan apabila kamu menyebut Tuhanmu saja dalam Al Quran, niscaya mereka berpaling ke belakang karena bencinya,'),
  ('id.indonesian', 17, 47, 'Kami lebih mengetahui dalam keadaan bagaimana mereka mendengarkan sewaktu mereka mendengarkan kamu, dan sewaktu mereka berbisik-bisik (yaitu) ketika orang-orang zalim itu berkata: "Kamu tidak lain hanyalah mengikuti seorang laki-laki yang kena sihir".'),
  ('id.indonesian', 17, 48, 'Lihatlah bagaimana mereka membuat perumpamaan-perumpamaan terhadapmu; karena itu mereka menjadi sesat dan tidak dapat lagi menemukan jalan (yang benar).'),
  ('id.indonesian', 17, 49, 'Dan mereka berkata: "Apakah bila kami telah menjadi tulang belulang dan benda-benda yang hancur, apa benar-benarkah kami akan dibangkitkan kembali sebagai makhluk yang baru?"'),
  ('id.indonesian', 17, 50, 'Katakanlah: "Jadilah kamu sekalian batu atau besi,'),
  ('id.indonesian', 17, 51, 'atau suatu makhluk dari makhluk yang tidak mungkin (hidup) menurut pikiranmu". Maka mereka akan bertanya: "Siapa yang akan menghidupkan kami kembali?" Katakanlah: "Yang telah menciptakan kamu pada kali yang pertama". Lalu mereka akan menggeleng-gelengkan kepala mereka kepadamu dan berkata: "Kapan itu (akan terjadi)?" Katakanlah: "Mudah-mudahan waktu berbangkit itu dekat",'),
  ('id.indonesian', 17, 52, 'yaitu pada hari Dia memanggil kamu, lalu kamu mematuhi-Nya sambil memuji-Nya dan kamu mengira, bahwa kamu tidak berdiam (di dalam kubur) kecuali sebentar saja.'),
  ('id.indonesian', 17, 53, 'Dan katakanlah kepada hamha-hamba-Ku: "Hendaklah mereka mengucapkan perkataan yang lebih baik (benar). Sesungguhnya syaitan itu menimbulkan perselisihan di antara mereka. Sesungguhnya syaitan itu adalah musuh yang nyata bagi manusia.'),
  ('id.indonesian', 17, 54, 'Tuhanmu lebih mengetahui tentang kamu. Dia akan memberi rahmat kepadamu jika Dia menghendaki dan Dia akan mengazabmu, jika Dia menghendaki. Dan, Kami tidaklah mengutusmu untuk menjadi penjaga bagi mereka.'),
  ('id.indonesian', 17, 55, 'Dan Tuhan-mu lebih mengetahui siapa yang (ada) di langit dan di bumi. Dan sesungguhnya telah Kami lebihkan sebagian nabi-nabi itu atas sebagian (yang lain), dan Kami berikan Zabur kepada Daud.'),
  ('id.indonesian', 17, 56, 'Katakanlah: "Panggillah mereka yang kamu anggap (tuhan) selain Allah, maka mereka tidak akan mempunyai kekuasaan untuk menghilangkan bahaya daripadamu dan tidak pula memindahkannya".'),
  ('id.indonesian', 17, 57, 'Orang-orang yang mereka seru itu, mereka sendiri mencari jalan kepada Tuhan mereka siapa di antara mereka yang lebih dekat (kepada Allah) dan mengharapkan rahmat-Nya dan takut akan azab-Nya; sesungguhnya azab Tuhanmu adalah suatu yang (harus) ditakuti.'),
  ('id.indonesian', 17, 58, 'Tak ada suatu negeripun (yang durhaka penduduknya), melainkan Kami membinasakannya sebelum hari kiamat atau Kami azab (penduduknya) dengan azab yang sangat keras. Yang demikian itu telah tertulis di dalam kitab (Lauh Mahfuzh).'),
  ('id.indonesian', 17, 59, 'Dan sekali-kali tidak ada yang menghalangi Kami untuk mengirimkan (kepadamu) tanda-tanda (kekuasan Kami), melainkan karena tanda-tanda itu telah didustakan oleh orang-orang dahulu. Dan telah Kami berikan kepada Tsamud unta betina itu (sebagai mukjizat) yang dapat dilihat, tetapi mereka menganiaya unta betina itu. Dan Kami tidak memberi tanda-tanda itu melainkan untuk menakuti.'),
  ('id.indonesian', 17, 60, 'Dan (ingatlah), ketika Kami wahyukan kepadamu: "Sesungguhnya (ilmu) Tuhanmu meliputi segala manusia". Dan Kami tidak menjadikan mimpi yang telah Kami perlihatkan kepadamu, melainkan sebagai ujian bagi manusia dan (begitu pula) pohon kayu yang terkutuk dalam Al Quran. Dan Kami menakut-nakuti mereka, tetapi yang demikian itu hanyalah menambah besar kedurhakaan mereka.'),
  ('id.indonesian', 17, 61, 'Dan (ingatlah), tatkala Kami berfirman kepada para malaikat: "Sujudlah kamu semua kepada Adam", lalu mereka sujud kecuali iblis. Dia berkata: "Apakah aku akan sujud kepada orang yang Engkau ciptakan dari tanah?"'),
  ('id.indonesian', 17, 62, 'Dia (iblis) berkata: "Terangkanlah kepadaku inikah orangnya yang Engkau muliakan atas diriku? Sesungguhnya jika Engkau memberi tangguh kepadaku sampai hari kiamat, niscaya benar-benar akan aku sesatkan keturunannya, kecuali sebahagian kecil".'),
  ('id.indonesian', 17, 63, 'Tuhan berfirman: "Pergilah, barangsiapa di antara mereka yang mengikuti kamu, maka sesungguhnya neraka Jahannam adalah balasanmu semua, sebagai suatu pembalasan yang cukup.'),
  ('id.indonesian', 17, 64, 'Dan hasunglah siapa yang kamu sanggupi di antara mereka dengan ajakanmu, dan kerahkanlah terhadap mereka pasukan berkuda dan pasukanmu yang berjalan kaki dan berserikatlah dengan mereka pada harta dan anak-anak dan beri janjilah mereka. Dan tidak ada yang dijanjikan oleh syaitan kepada mereka melainkan tipuan belaka.'),
  ('id.indonesian', 17, 65, 'Sesungguhnya hamba-hamba-Ku, kamu tidak dapat berkuasa atas mereka. Dan cukuplah Tuhan-mu sebagai Penjaga".'),
  ('id.indonesian', 17, 66, 'Tuhan-mu adalah yang melayarkan kapal-kapal di lautan untukmu, agar kamu mencari sebahagian dari karunia-Nya. Sesungguhnya Dia adalah Maha Penyayang terhadapmu.'),
  ('id.indonesian', 17, 67, 'Dan apabila kamu ditimpa bahaya di lautan, niscaya hilanglah siapa yang kamu seru kecuali Dia, Maka tatkala Dia menyelamatkan kamu ke daratan, kamu berpaling. Dan manusia itu adalah selalu tidak berterima kasih.'),
  ('id.indonesian', 17, 68, 'Maka apakah kamu merasa aman (dari hukuman Tuhan) yang menjungkir balikkan sebagian daratan bersama kamu atau Dia meniupkan (angin keras yang membawa) batu-batu kecil? dan kamu tidak akan mendapat seorang pelindungpun bagi kamu,'),
  ('id.indonesian', 17, 69, 'atau apakah kamu merasa aman dari dikembalikan-Nya kamu ke laut sekali lagi, lalu Dia meniupkan atas kamu angin taupan dan ditenggelamkan-Nya kamu disebabkan kekafiranmu. Dan kamu tidak akan mendapat seorang penolongpun dalam hal ini terhadap (siksaan) Kami.'),
  ('id.indonesian', 17, 70, 'Dan sesungguhnya telah Kami muliakan anak-anak Adam, Kami angkut mereka di daratan dan di lautan, Kami beri mereka rezeki dari yang baik-baik dan Kami lebihkan mereka dengan kelebihan yang sempurna atas kebanyakan makhluk yang telah Kami ciptakan.'),
  ('id.indonesian', 17, 71, '(Ingatlah) suatu hari (yang di hari itu) Kami panggil tiap umat dengan pemimpinnya; dan barangsiapa yang diberikan kitab amalannya di tangan kanannya maka mereka ini akan membaca kitabnya itu, dan mereka tidak dianiaya sedikitpun.'),
  ('id.indonesian', 17, 72, 'Dan barangsiapa yang buta (hatinya) di dunia ini, niscaya di akhirat (nanti) ia akan lebih buta (pula) dan lebih tersesat dari jalan (yang benar).'),
  ('id.indonesian', 17, 73, 'Dan sesungguhnya mereka hampir memalingkan kamu dari apa yang telah Kami wahyukan kepadamu, agar kamu membuat yang lain secara bohong terhadap Kami; dan kalau sudah begitu tentulah mereka mengambil kamu jadi sahabat yang setia.'),
  ('id.indonesian', 17, 74, 'Dan kalau Kami tidak memperkuat (hati)mu, niscaya kamu hampir-hampir condong sedikit kepada mereka,'),
  ('id.indonesian', 17, 75, 'kalau terjadi demikian, benar-benarlah Kami akan rasakan kepadamu (siksaan) berlipat ganda di dunia ini dan begitu (pula siksaan) berlipat ganda sesudah mati, dan kamu tidak akan mendapat seorang penolongpun terhadap Kami.'),
  ('id.indonesian', 17, 76, 'Dan sesungguhnya benar-benar mereka hampir membuatmu gelisah di negeri (Mekah) untuk mengusirmu daripadanya dan kalau terjadi demikian, niscaya sepeninggalmu mereka tidak tinggal, melainkan sebentar saja.'),
  ('id.indonesian', 17, 77, '(Kami menetapkan yang demikian) sebagai suatu ketetapan terhadap rasul-rasul Kami yang Kami utus sebelum kamu dan tidak akan kamu dapati perubahan bagi ketetapan Kami itu.'),
  ('id.indonesian', 17, 78, 'Dirikanlah shalat dari sesudah matahari tergelincir sampai gelap malam dan (dirikanlah pula shalat) subuh. Sesungguhnya shalat subuh itu disaksikan (oleh malaikat).'),
  ('id.indonesian', 17, 79, 'Dan pada sebahagian malam hari bersembahyang tahajudlah kamu sebagai suatu ibadah tambahan bagimu; mudah-mudahan Tuhan-mu mengangkat kamu ke tempat yang terpuji.'),
  ('id.indonesian', 17, 80, 'Dan katakanlah: "Ya Tuhan-ku, masukkanlah aku secara masuk yang benar dan keluarkanlah (pula) aku secara keluar yang benar dan berikanlah kepadaku dari sisi Engkau kekuasaan yang menolong.'),
  ('id.indonesian', 17, 81, 'Dan katakanlah: "Yang benar telah datang dan yang batil telah lenyap". Sesungguhnya yang batil itu adalah sesuatu yang pasti lenyap.'),
  ('id.indonesian', 17, 82, 'Dan Kami turunkan dari Al Quran suatu yang menjadi penawar dan rahmat bagi orang-orang yang beriman dan Al Quran itu tidaklah menambah kepada orang-orang yang zalim selain kerugian.'),
  ('id.indonesian', 17, 83, 'Dan apabila Kami berikan kesenangan kepada manusia niscaya berpalinglah dia; dan membelakang dengan sikap yang sombong; dan apabila dia ditimpa kesusahan niscaya dia berputus asa.'),
  ('id.indonesian', 17, 84, 'Katakanlah: "Tiap-tiap orang berbuat menurut keadaannya masing-masing". Maka Tuhanmu lebih mengetahui siapa yang lebih benar jalannya.'),
  ('id.indonesian', 17, 85, 'Dan mereka bertanya kepadamu tentang roh. Katakanlah: "Roh itu termasuk urusan Tuhan-ku, dan tidaklah kamu diberi pengetahuan melainkan sedikit".'),
  ('id.indonesian', 17, 86, 'Dan sesungguhnya jika Kami menghendaki, niscaya Kami lenyapkan apa yang telah Kami wahyukan kepadamu, dan dengan pelenyapan itu, kamu tidak akan mendapatkan seorang pembelapun terhadap Kami,'),
  ('id.indonesian', 17, 87, 'kecuali karena rahmat dari Tuhanmu. Sesungguhnya karunia-Nya atasmu adalah besar.'),
  ('id.indonesian', 17, 88, 'Katakanlah: "Sesungguhnya jika manusia dan jin berkumpul untuk membuat yang serupa Al Quran ini, niscaya mereka tidak akan dapat membuat yang serupa dengan dia, sekalipun sebagian mereka menjadi pembantu bagi sebagian yang lain".'),
  ('id.indonesian', 17, 89, 'Dan sesungguhnya Kami telah mengulang-ulang kepada manusia dalam Al Quran ini tiap-tiap macam perumpamaan, tapi kebanyakan manusia tidak menyukai kecuali mengingkari(nya).'),
  ('id.indonesian', 17, 90, 'Dan mereka berkata: "Kami sekali-kali tidak percaya kepadamu hingga kamu memancarkan mata air dan bumi untuk kami,'),
  ('id.indonesian', 17, 91, 'atau kamu mempunyai sebuah kebun korma dan anggur, lalu kamu alirkan sungai-sungai di celah kebun yang deras alirannya,'),
  ('id.indonesian', 17, 92, 'atau kamu jatuhkan langit berkeping-keping atas kami, sebagaimana kamu katakan atau kamu datangkan Allah dan malaikat-malaikat berhadapan muka dengan kami.'),
  ('id.indonesian', 17, 93, 'Atau kamu mempunyai sebuah rumah dari emas, atau kamu naik ke langit. Dan kami sekali-kali tidak akan mempercayai kenaikanmu itu hingga kamu turunkan atas kami sebuah kitab yang kami baca". Katakanlah: "Maha Suci Tuhanku, bukankah aku ini hanya seorang manusia yang menjadi rasul?"'),
  ('id.indonesian', 17, 94, 'Dan tidak ada sesuatu yang menghalangi manusia untuk beriman tatkala datang petunjuk kepadanya, kecuali perkataan mereka: "Adakah Allah mengutus seorang manusia menjadi rasuI?"'),
  ('id.indonesian', 17, 95, 'Katakanlah: "Kalau seandainya ada malaikat-malaikat yang berjalan-jalan sebagai penghuni di bumi, niscaya Kami turunkan dari langit kepada mereka seorang malaikat menjadi rasul".'),
  ('id.indonesian', 17, 96, 'Katakanlah: "Cukuplah Allah menjadi saksi antara aku dan kamu sekalian. Sesungguhnya Dia adalah Maha Mengetahui lagi Maha Melihat akan hamba-hamba-Nya".'),
  ('id.indonesian', 17, 97, 'Dan barangsiapa yang ditunjuki Allah, dialah yang mendapat petunjuk dan barangsiapa yang Dia sesatkan maka sekali-kali kamu tidak akan mendapat penolong-penolong bagi mereka selain dari Dia. Dan Kami akan mengumpulkan mereka pada hari kiamat (diseret) atas muka mereka dalam keadaan buta, bisu dan pekak. Tempat kediaman mereka adalah neraka jahannam. Tiap-tiap kali nyala api Jahannam itu akan padam, Kami tambah lagi bagi mereka nyalanya.'),
  ('id.indonesian', 17, 98, 'Itulah balasan bagi mereka, karena sesungguhnya mereka kafir kepada ayat-ayat Kami dan (karena mereka) berkata: "Apakah bila kami telah menjadi tulang belulang dan benda-benda yang hancur, apakah kami benar-benar akan dibangkitkan kembali sebagai makhluk baru?"'),
  ('id.indonesian', 17, 99, 'Dan apakah mereka tidak memperhatikan bahwasanya Allah yang menciptakan langit dan bumi adalah kuasa (pula) menciptakan yang serupa dengan mereka, dan telah menetapkan waktu yang tertentu bagi mereka yang tidak ada keraguan padanya? Maka orang-orang zalim itu tidak menghendaki kecuali kekafiran.'),
  ('id.indonesian', 17, 100, 'Katakanlah: "Kalau seandainya kamu menguasai perbendaharaan-perbendaharaan rahmat Tuhanku, niscaya perbendaharaan itu kamu tahan, karena takut membelanjakannya". Dan adalah manusia itu sangat kikir.'),
  ('id.indonesian', 17, 101, 'Dan sesungguhnya Kami telah memberikan kepada Musa sembilan buah mukjizat yang nyata, maka tanyakanlah kepada Bani Israil, tatkala Musa datang kepada mereka lalu Fir\'aun berkata kepadanya: "Sesungguhnya aku sangka kamu, hai Musa, seorang yang kena sihir".'),
  ('id.indonesian', 17, 102, 'Musa menjawab: "Sesungguhnya kamu telah mengetahui, bahwa tiada yang menurunkan mukjizat-mukjizat itu kecuali Tuhan Yang memelihara langit dan bumi sebagai bukti-bukti yang nyata; dan sesungguhnya aku mengira kamu, hai Fir\'aun, seorang yang akan binasa".'),
  ('id.indonesian', 17, 103, 'Kemudian (Fir\'aun) hendak mengusir mereka (Musa dan pengikut-pengikutnya) dari bumi (Mesir) itu, maka Kami tenggelamkan dia (Fir\'aun) serta orang-orang yang bersama-sama dia seluruhnya,'),
  ('id.indonesian', 17, 104, 'dan Kami berfirman sesudah itu kepada Bani Israil: "Diamlah di negeri ini, maka apabila datang masa berbangkit, niscaya Kami datangkan kamu dalam keadaan bercampur baur (dengan musuhmu)".'),
  ('id.indonesian', 17, 105, 'Dan Kami turunkan (Al Quran) itu dengan sebenar-benarnya dan Al Quran itu telah turun dengan (membawa) kebenaran. Dan Kami tidak mengutus kamu, melainkan sebagai pembawa berita gembira dan pemberi peringatan.'),
  ('id.indonesian', 17, 106, 'Dan Al Quran itu telah Kami turunkan dengan berangsur-angsur agar kamu membacakannya perlahan-lahan kepada manusia dan Kami menurunkannya bagian demi bagian.'),
  ('id.indonesian', 17, 107, 'Katakanlah: "Berimanlah kamu kepadanya atau tidak usah beriman (sama saja bagi Allah). Sesungguhnya orang-orang yang diberi pengetahuan sebelumnya apabila Al Quran dibacakan kepada mereka, mereka menyungkur atas muka mereka sambil bersujud,'),
  ('id.indonesian', 17, 108, 'dan mereka berkata: "Maha Suci Tuhan kami, sesungguhnya janji Tuhan kami pasti dipenuhi".'),
  ('id.indonesian', 17, 109, 'Dan mereka menyungkur atas muka mereka sambil menangis dan mereka bertambah khusyu\'.'),
  ('id.indonesian', 17, 110, 'Katakanlah: "Serulah Allah atau serulah Ar-Rahman. Dengan nama yang mana saja kamu seru, Dia mempunyai al asmaaul husna (nama-nama yang terbaik) dan janganlah kamu mengeraskan suaramu dalam shalatmu dan janganlah pula merendahkannya dan carilah jalan tengah di antara kedua itu".'),
  ('id.indonesian', 17, 111, 'Dan katakanlah: "Segala puji bagi Allah Yang tidak mempunyai anak dan tidak mempunyai sekutu dalam kerajaan-Nya dan Dia bukan pula hina yang memerlukan penolong dan agungkanlah Dia dengan pengagungan yang sebesar-besarnya.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (16, 100, 2001, 'إِنَّمَا سُلْطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوْنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشْرِكُونَ', 278, 14, 111, 0),
  (16, 101, 2002, 'وَإِذَا بَدَّلْنَآ ءَايَةًۭ مَّكَانَ ءَايَةٍۢ ۙ وَٱللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ قَالُوٓا۟ إِنَّمَآ أَنتَ مُفْتَرٍۭ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 278, 14, 111, 0),
  (16, 102, 2003, 'قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًۭى وَبُشْرَىٰ لِلْمُسْلِمِينَ', 278, 14, 111, 0),
  (16, 103, 2004, 'وَلَقَدْ نَعْلَمُ أَنَّهُمْ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٌۭ ۗ لِّسَانُ ٱلَّذِى يُلْحِدُونَ إِلَيْهِ أَعْجَمِىٌّۭ وَهَٰذَا لِسَانٌ عَرَبِىٌّۭ مُّبِينٌ', 279, 14, 111, 0),
  (16, 104, 2005, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهْدِيهِمُ ٱللَّهُ وَلَهُمْ عَذَابٌ أَلِيمٌ', 279, 14, 111, 0),
  (16, 105, 2006, 'إِنَّمَا يَفْتَرِى ٱلْكَذِبَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِـَٔايَٰتِ ٱللَّهِ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْكَٰذِبُونَ', 279, 14, 111, 0),
  (16, 106, 2007, 'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعْدِ إِيمَٰنِهِۦٓ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُۥ مُطْمَئِنٌّۢ بِٱلْإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلْكُفْرِ صَدْرًۭا فَعَلَيْهِمْ غَضَبٌۭ مِّنَ ٱللَّهِ وَلَهُمْ عَذَابٌ عَظِيمٌۭ', 279, 14, 111, 0),
  (16, 107, 2008, 'ذَٰلِكَ بِأَنَّهُمُ ٱسْتَحَبُّوا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا عَلَى ٱلْءَاخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ', 279, 14, 111, 0),
  (16, 108, 2009, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَسَمْعِهِمْ وَأَبْصَٰرِهِمْ ۖ وَأُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ', 279, 14, 111, 0),
  (16, 109, 2010, 'لَا جَرَمَ أَنَّهُمْ فِى ٱلْءَاخِرَةِ هُمُ ٱلْخَٰسِرُونَ', 279, 14, 111, 0),
  (16, 110, 2011, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا۟ مِنۢ بَعْدِ مَا فُتِنُوا۟ ثُمَّ جَٰهَدُوا۟ وَصَبَرُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌۭ', 279, 14, 111, 0),
  (16, 111, 2012, '۞ يَوْمَ تَأْتِى كُلُّ نَفْسٍۢ تُجَٰدِلُ عَن نَّفْسِهَا وَتُوَفَّىٰ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ وَهُمْ لَا يُظْلَمُونَ', 280, 14, 112, 0),
  (16, 112, 2013, 'وَضَرَبَ ٱللَّهُ مَثَلًۭا قَرْيَةًۭ كَانَتْ ءَامِنَةًۭ مُّطْمَئِنَّةًۭ يَأْتِيهَا رِزْقُهَا رَغَدًۭا مِّن كُلِّ مَكَانٍۢ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ', 280, 14, 112, 0),
  (16, 113, 2014, 'وَلَقَدْ جَآءَهُمْ رَسُولٌۭ مِّنْهُمْ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلْعَذَابُ وَهُمْ ظَٰلِمُونَ', 280, 14, 112, 0),
  (16, 114, 2015, 'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلًۭا طَيِّبًۭا وَٱشْكُرُوا۟ نِعْمَتَ ٱللَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 280, 14, 112, 0),
  (16, 115, 2016, 'إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 280, 14, 112, 0),
  (16, 116, 2017, 'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌۭ وَهَٰذَا حَرَامٌۭ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ ۚ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ', 280, 14, 112, 0),
  (16, 117, 2018, 'مَتَٰعٌۭ قَلِيلٌۭ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 280, 14, 112, 0),
  (16, 118, 2019, 'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا مَا قَصَصْنَا عَلَيْكَ مِن قَبْلُ ۖ وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ', 280, 14, 112, 0),
  (16, 119, 2020, 'ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُوا۟ ٱلسُّوٓءَ بِجَهَٰلَةٍۢ ثُمَّ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌۭ رَّحِيمٌ', 281, 14, 112, 0),
  (16, 120, 2021, 'إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةًۭ قَانِتًۭا لِّلَّهِ حَنِيفًۭا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ', 281, 14, 112, 0),
  (16, 121, 2022, 'شَاكِرًۭا لِّأَنْعُمِهِ ۚ ٱجْتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 281, 14, 112, 0),
  (16, 122, 2023, 'وَءَاتَيْنَٰهُ فِى ٱلدُّنْيَا حَسَنَةًۭ ۖ وَإِنَّهُۥ فِى ٱلْءَاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ', 281, 14, 112, 0),
  (16, 123, 2024, 'ثُمَّ أَوْحَيْنَآ إِلَيْكَ أَنِ ٱتَّبِعْ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًۭا ۖ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ', 281, 14, 112, 0),
  (16, 124, 2025, 'إِنَّمَا جُعِلَ ٱلسَّبْتُ عَلَى ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ ۚ وَإِنَّ رَبَّكَ لَيَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 281, 14, 112, 0),
  (16, 125, 2026, 'ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 281, 14, 112, 0),
  (16, 126, 2027, 'وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا۟ بِمِثْلِ مَا عُوقِبْتُم بِهِۦ ۖ وَلَئِن صَبَرْتُمْ لَهُوَ خَيْرٌۭ لِّلصَّٰبِرِينَ', 281, 14, 112, 0),
  (16, 127, 2028, 'وَٱصْبِرْ وَمَا صَبْرُكَ إِلَّا بِٱللَّهِ ۚ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِى ضَيْقٍۢ مِّمَّا يَمْكُرُونَ', 281, 14, 112, 0),
  (16, 128, 2029, 'إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَوا۟ وَّٱلَّذِينَ هُم مُّحْسِنُونَ', 281, 14, 112, 0),
  (17, 1, 2030, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سُبْحَٰنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِۦ لَيْلًۭا مِّنَ ٱلْمَسْجِدِ ٱلْحَرَامِ إِلَى ٱلْمَسْجِدِ ٱلْأَقْصَا ٱلَّذِى بَٰرَكْنَا حَوْلَهُۥ لِنُرِيَهُۥ مِنْ ءَايَٰتِنَآ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 282, 15, 113, 0),
  (17, 2, 2031, 'وَءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَٰهُ هُدًۭى لِّبَنِىٓ إِسْرَٰٓءِيلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِى وَكِيلًۭا', 282, 15, 113, 0),
  (17, 3, 2032, 'ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ ۚ إِنَّهُۥ كَانَ عَبْدًۭا شَكُورًۭا', 282, 15, 113, 0),
  (17, 4, 2033, 'وَقَضَيْنَآ إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ فِى ٱلْكِتَٰبِ لَتُفْسِدُنَّ فِى ٱلْأَرْضِ مَرَّتَيْنِ وَلَتَعْلُنَّ عُلُوًّۭا كَبِيرًۭا', 282, 15, 113, 0),
  (17, 5, 2034, 'فَإِذَا جَآءَ وَعْدُ أُولَىٰهُمَا بَعَثْنَا عَلَيْكُمْ عِبَادًۭا لَّنَآ أُو۟لِى بَأْسٍۢ شَدِيدٍۢ فَجَاسُوا۟ خِلَٰلَ ٱلدِّيَارِ ۚ وَكَانَ وَعْدًۭا مَّفْعُولًۭا', 282, 15, 113, 0),
  (17, 6, 2035, 'ثُمَّ رَدَدْنَا لَكُمُ ٱلْكَرَّةَ عَلَيْهِمْ وَأَمْدَدْنَٰكُم بِأَمْوَٰلٍۢ وَبَنِينَ وَجَعَلْنَٰكُمْ أَكْثَرَ نَفِيرًا', 282, 15, 113, 0),
  (17, 7, 2036, 'إِنْ أَحْسَنتُمْ أَحْسَنتُمْ لِأَنفُسِكُمْ ۖ وَإِنْ أَسَأْتُمْ فَلَهَا ۚ فَإِذَا جَآءَ وَعْدُ ٱلْءَاخِرَةِ لِيَسُۥٓـُٔوا۟ وُجُوهَكُمْ وَلِيَدْخُلُوا۟ ٱلْمَسْجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٍۢ وَلِيُتَبِّرُوا۟ مَا عَلَوْا۟ تَتْبِيرًا', 282, 15, 113, 0),
  (17, 8, 2037, 'عَسَىٰ رَبُّكُمْ أَن يَرْحَمَكُمْ ۚ وَإِنْ عُدتُّمْ عُدْنَا ۘ وَجَعَلْنَا جَهَنَّمَ لِلْكَٰفِرِينَ حَصِيرًا', 283, 15, 113, 0),
  (17, 9, 2038, 'إِنَّ هَٰذَا ٱلْقُرْءَانَ يَهْدِى لِلَّتِى هِىَ أَقْوَمُ وَيُبَشِّرُ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًۭا كَبِيرًۭا', 283, 15, 113, 0),
  (17, 10, 2039, 'وَأَنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ أَعْتَدْنَا لَهُمْ عَذَابًا أَلِيمًۭا', 283, 15, 113, 0),
  (17, 11, 2040, 'وَيَدْعُ ٱلْإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلْخَيْرِ ۖ وَكَانَ ٱلْإِنسَٰنُ عَجُولًۭا', 283, 15, 113, 0),
  (17, 12, 2041, 'وَجَعَلْنَا ٱلَّيْلَ وَٱلنَّهَارَ ءَايَتَيْنِ ۖ فَمَحَوْنَآ ءَايَةَ ٱلَّيْلِ وَجَعَلْنَآ ءَايَةَ ٱلنَّهَارِ مُبْصِرَةًۭ لِّتَبْتَغُوا۟ فَضْلًۭا مِّن رَّبِّكُمْ وَلِتَعْلَمُوا۟ عَدَدَ ٱلسِّنِينَ وَٱلْحِسَابَ ۚ وَكُلَّ شَىْءٍۢ فَصَّلْنَٰهُ تَفْصِيلًۭا', 283, 15, 113, 0),
  (17, 13, 2042, 'وَكُلَّ إِنسَٰنٍ أَلْزَمْنَٰهُ طَٰٓئِرَهُۥ فِى عُنُقِهِۦ ۖ وَنُخْرِجُ لَهُۥ يَوْمَ ٱلْقِيَٰمَةِ كِتَٰبًۭا يَلْقَىٰهُ مَنشُورًا', 283, 15, 113, 0),
  (17, 14, 2043, 'ٱقْرَأْ كِتَٰبَكَ كَفَىٰ بِنَفْسِكَ ٱلْيَوْمَ عَلَيْكَ حَسِيبًۭا', 283, 15, 113, 0),
  (17, 15, 2044, 'مَّنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًۭا', 283, 15, 113, 0),
  (17, 16, 2045, 'وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَٰهَا تَدْمِيرًۭا', 283, 15, 113, 0),
  (17, 17, 2046, 'وَكَمْ أَهْلَكْنَا مِنَ ٱلْقُرُونِ مِنۢ بَعْدِ نُوحٍۢ ۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا', 283, 15, 113, 0),
  (17, 18, 2047, 'مَّن كَانَ يُرِيدُ ٱلْعَاجِلَةَ عَجَّلْنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلْنَا لَهُۥ جَهَنَّمَ يَصْلَىٰهَا مَذْمُومًۭا مَّدْحُورًۭا', 284, 15, 113, 0),
  (17, 19, 2048, 'وَمَنْ أَرَادَ ٱلْءَاخِرَةَ وَسَعَىٰ لَهَا سَعْيَهَا وَهُوَ مُؤْمِنٌۭ فَأُو۟لَٰٓئِكَ كَانَ سَعْيُهُم مَّشْكُورًۭا', 284, 15, 113, 0),
  (17, 20, 2049, 'كُلًّۭا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنْ عَطَآءِ رَبِّكَ ۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحْظُورًا', 284, 15, 113, 0),
  (17, 21, 2050, 'ٱنظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍۢ ۚ وَلَلْءَاخِرَةُ أَكْبَرُ دَرَجَٰتٍۢ وَأَكْبَرُ تَفْضِيلًۭا', 284, 15, 113, 0),
  (17, 22, 2051, 'لَّا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقْعُدَ مَذْمُومًۭا مَّخْذُولًۭا', 284, 15, 113, 0),
  (17, 23, 2052, '۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا', 284, 15, 114, 0),
  (17, 24, 2053, 'وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا', 284, 15, 114, 0),
  (17, 25, 2054, 'رَّبُّكُمْ أَعْلَمُ بِمَا فِى نُفُوسِكُمْ ۚ إِن تَكُونُوا۟ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلْأَوَّٰبِينَ غَفُورًۭا', 284, 15, 114, 0),
  (17, 26, 2055, 'وَءَاتِ ذَا ٱلْقُرْبَىٰ حَقَّهُۥ وَٱلْمِسْكِينَ وَٱبْنَ ٱلسَّبِيلِ وَلَا تُبَذِّرْ تَبْذِيرًا', 284, 15, 114, 0),
  (17, 27, 2056, 'إِنَّ ٱلْمُبَذِّرِينَ كَانُوٓا۟ إِخْوَٰنَ ٱلشَّيَٰطِينِ ۖ وَكَانَ ٱلشَّيْطَٰنُ لِرَبِّهِۦ كَفُورًۭا', 284, 15, 114, 0),
  (17, 28, 2057, 'وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ٱبْتِغَآءَ رَحْمَةٍۢ مِّن رَّبِّكَ تَرْجُوهَا فَقُل لَّهُمْ قَوْلًۭا مَّيْسُورًۭا', 285, 15, 114, 0),
  (17, 29, 2058, 'وَلَا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبْسُطْهَا كُلَّ ٱلْبَسْطِ فَتَقْعُدَ مَلُومًۭا مَّحْسُورًا', 285, 15, 114, 0),
  (17, 30, 2059, 'إِنَّ رَبَّكَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا', 285, 15, 114, 0),
  (17, 31, 2060, 'وَلَا تَقْتُلُوٓا۟ أَوْلَٰدَكُمْ خَشْيَةَ إِمْلَٰقٍۢ ۖ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ ۚ إِنَّ قَتْلَهُمْ كَانَ خِطْـًۭٔا كَبِيرًۭا', 285, 15, 114, 0),
  (17, 32, 2061, 'وَلَا تَقْرَبُوا۟ ٱلزِّنَىٰٓ ۖ إِنَّهُۥ كَانَ فَٰحِشَةًۭ وَسَآءَ سَبِيلًۭا', 285, 15, 114, 0),
  (17, 33, 2062, 'وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۗ وَمَن قُتِلَ مَظْلُومًۭا فَقَدْ جَعَلْنَا لِوَلِيِّهِۦ سُلْطَٰنًۭا فَلَا يُسْرِف فِّى ٱلْقَتْلِ ۖ إِنَّهُۥ كَانَ مَنصُورًۭا', 285, 15, 114, 0),
  (17, 34, 2063, 'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۚ وَأَوْفُوا۟ بِٱلْعَهْدِ ۖ إِنَّ ٱلْعَهْدَ كَانَ مَسْـُٔولًۭا', 285, 15, 114, 0),
  (17, 35, 2064, 'وَأَوْفُوا۟ ٱلْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا۟ بِٱلْقِسْطَاسِ ٱلْمُسْتَقِيمِ ۚ ذَٰلِكَ خَيْرٌۭ وَأَحْسَنُ تَأْوِيلًۭا', 285, 15, 114, 0),
  (17, 36, 2065, 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۚ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًۭا', 285, 15, 114, 0),
  (17, 37, 2066, 'وَلَا تَمْشِ فِى ٱلْأَرْضِ مَرَحًا ۖ إِنَّكَ لَن تَخْرِقَ ٱلْأَرْضَ وَلَن تَبْلُغَ ٱلْجِبَالَ طُولًۭا', 285, 15, 114, 0),
  (17, 38, 2067, 'كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكْرُوهًۭا', 285, 15, 114, 0),
  (17, 39, 2068, 'ذَٰلِكَ مِمَّآ أَوْحَىٰٓ إِلَيْكَ رَبُّكَ مِنَ ٱلْحِكْمَةِ ۗ وَلَا تَجْعَلْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلْقَىٰ فِى جَهَنَّمَ مَلُومًۭا مَّدْحُورًا', 286, 15, 114, 0),
  (17, 40, 2069, 'أَفَأَصْفَىٰكُمْ رَبُّكُم بِٱلْبَنِينَ وَٱتَّخَذَ مِنَ ٱلْمَلَٰٓئِكَةِ إِنَٰثًا ۚ إِنَّكُمْ لَتَقُولُونَ قَوْلًا عَظِيمًۭا', 286, 15, 114, 0),
  (17, 41, 2070, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِيَذَّكَّرُوا۟ وَمَا يَزِيدُهُمْ إِلَّا نُفُورًۭا', 286, 15, 114, 0),
  (17, 42, 2071, 'قُل لَّوْ كَانَ مَعَهُۥٓ ءَالِهَةٌۭ كَمَا يَقُولُونَ إِذًۭا لَّٱبْتَغَوْا۟ إِلَىٰ ذِى ٱلْعَرْشِ سَبِيلًۭا', 286, 15, 114, 0),
  (17, 43, 2072, 'سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوًّۭا كَبِيرًۭا', 286, 15, 114, 0),
  (17, 44, 2073, 'تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَٰكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ ۗ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًۭا', 286, 15, 114, 0),
  (17, 45, 2074, 'وَإِذَا قَرَأْتَ ٱلْقُرْءَانَ جَعَلْنَا بَيْنَكَ وَبَيْنَ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ حِجَابًۭا مَّسْتُورًۭا', 286, 15, 114, 0),
  (17, 46, 2075, 'وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًۭا ۚ وَإِذَا ذَكَرْتَ رَبَّكَ فِى ٱلْقُرْءَانِ وَحْدَهُۥ وَلَّوْا۟ عَلَىٰٓ أَدْبَٰرِهِمْ نُفُورًۭا', 286, 15, 114, 0),
  (17, 47, 2076, 'نَّحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِۦٓ إِذْ يَسْتَمِعُونَ إِلَيْكَ وَإِذْ هُمْ نَجْوَىٰٓ إِذْ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًۭا مَّسْحُورًا', 286, 15, 114, 0),
  (17, 48, 2077, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَالَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًۭا', 286, 15, 114, 0),
  (17, 49, 2078, 'وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًۭا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًۭا جَدِيدًۭا', 286, 15, 114, 0),
  (17, 50, 2079, '۞ قُلْ كُونُوا۟ حِجَارَةً أَوْ حَدِيدًا', 287, 15, 115, 0),
  (17, 51, 2080, 'أَوْ خَلْقًۭا مِّمَّا يَكْبُرُ فِى صُدُورِكُمْ ۚ فَسَيَقُولُونَ مَن يُعِيدُنَا ۖ قُلِ ٱلَّذِى فَطَرَكُمْ أَوَّلَ مَرَّةٍۢ ۚ فَسَيُنْغِضُونَ إِلَيْكَ رُءُوسَهُمْ وَيَقُولُونَ مَتَىٰ هُوَ ۖ قُلْ عَسَىٰٓ أَن يَكُونَ قَرِيبًۭا', 287, 15, 115, 0),
  (17, 52, 2081, 'يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِۦ وَتَظُنُّونَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًۭا', 287, 15, 115, 0),
  (17, 53, 2082, 'وَقُل لِّعِبَادِى يَقُولُوا۟ ٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ ٱلشَّيْطَٰنَ يَنزَغُ بَيْنَهُمْ ۚ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلْإِنسَٰنِ عَدُوًّۭا مُّبِينًۭا', 287, 15, 115, 0),
  (17, 54, 2083, 'رَّبُّكُمْ أَعْلَمُ بِكُمْ ۖ إِن يَشَأْ يَرْحَمْكُمْ أَوْ إِن يَشَأْ يُعَذِّبْكُمْ ۚ وَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ وَكِيلًۭا', 287, 15, 115, 0),
  (17, 55, 2084, 'وَرَبُّكَ أَعْلَمُ بِمَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَلَقَدْ فَضَّلْنَا بَعْضَ ٱلنَّبِيِّۦنَ عَلَىٰ بَعْضٍۢ ۖ وَءَاتَيْنَا دَاوُۥدَ زَبُورًۭا', 287, 15, 115, 0),
  (17, 56, 2085, 'قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِهِۦ فَلَا يَمْلِكُونَ كَشْفَ ٱلضُّرِّ عَنكُمْ وَلَا تَحْوِيلًا', 287, 15, 115, 0),
  (17, 57, 2086, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَىٰ رَبِّهِمُ ٱلْوَسِيلَةَ أَيُّهُمْ أَقْرَبُ وَيَرْجُونَ رَحْمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓ ۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحْذُورًۭا', 287, 15, 115, 0),
  (17, 58, 2087, 'وَإِن مِّن قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا قَبْلَ يَوْمِ ٱلْقِيَٰمَةِ أَوْ مُعَذِّبُوهَا عَذَابًۭا شَدِيدًۭا ۚ كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًۭا', 287, 15, 115, 0),
  (17, 59, 2088, 'وَمَا مَنَعَنَآ أَن نُّرْسِلَ بِٱلْءَايَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلْأَوَّلُونَ ۚ وَءَاتَيْنَا ثَمُودَ ٱلنَّاقَةَ مُبْصِرَةًۭ فَظَلَمُوا۟ بِهَا ۚ وَمَا نُرْسِلُ بِٱلْءَايَٰتِ إِلَّا تَخْوِيفًۭا', 288, 15, 115, 0),
  (17, 60, 2089, 'وَإِذْ قُلْنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِ ۚ وَمَا جَعَلْنَا ٱلرُّءْيَا ٱلَّتِىٓ أَرَيْنَٰكَ إِلَّا فِتْنَةًۭ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلْمَلْعُونَةَ فِى ٱلْقُرْءَانِ ۚ وَنُخَوِّفُهُمْ فَمَا يَزِيدُهُمْ إِلَّا طُغْيَٰنًۭا كَبِيرًۭا', 288, 15, 115, 0),
  (17, 61, 2090, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ قَالَ ءَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًۭا', 288, 15, 115, 0),
  (17, 62, 2091, 'قَالَ أَرَءَيْتَكَ هَٰذَا ٱلَّذِى كَرَّمْتَ عَلَىَّ لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَأَحْتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلًۭا', 288, 15, 115, 0),
  (17, 63, 2092, 'قَالَ ٱذْهَبْ فَمَن تَبِعَكَ مِنْهُمْ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمْ جَزَآءًۭ مَّوْفُورًۭا', 288, 15, 115, 0),
  (17, 64, 2093, 'وَٱسْتَفْزِزْ مَنِ ٱسْتَطَعْتَ مِنْهُم بِصَوْتِكَ وَأَجْلِبْ عَلَيْهِم بِخَيْلِكَ وَرَجِلِكَ وَشَارِكْهُمْ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ وَعِدْهُمْ ۚ وَمَا يَعِدُهُمُ ٱلشَّيْطَٰنُ إِلَّا غُرُورًا', 288, 15, 115, 0),
  (17, 65, 2094, 'إِنَّ عِبَادِى لَيْسَ لَكَ عَلَيْهِمْ سُلْطَٰنٌۭ ۚ وَكَفَىٰ بِرَبِّكَ وَكِيلًۭا', 288, 15, 115, 0),
  (17, 66, 2095, 'رَّبُّكُمُ ٱلَّذِى يُزْجِى لَكُمُ ٱلْفُلْكَ فِى ٱلْبَحْرِ لِتَبْتَغُوا۟ مِن فَضْلِهِۦٓ ۚ إِنَّهُۥ كَانَ بِكُمْ رَحِيمًۭا', 288, 15, 115, 0),
  (17, 67, 2096, 'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِى ٱلْبَحْرِ ضَلَّ مَن تَدْعُونَ إِلَّآ إِيَّاهُ ۖ فَلَمَّا نَجَّىٰكُمْ إِلَى ٱلْبَرِّ أَعْرَضْتُمْ ۚ وَكَانَ ٱلْإِنسَٰنُ كَفُورًا', 289, 15, 115, 0),
  (17, 68, 2097, 'أَفَأَمِنتُمْ أَن يَخْسِفَ بِكُمْ جَانِبَ ٱلْبَرِّ أَوْ يُرْسِلَ عَلَيْكُمْ حَاصِبًۭا ثُمَّ لَا تَجِدُوا۟ لَكُمْ وَكِيلًا', 289, 15, 115, 0),
  (17, 69, 2098, 'أَمْ أَمِنتُمْ أَن يُعِيدَكُمْ فِيهِ تَارَةً أُخْرَىٰ فَيُرْسِلَ عَلَيْكُمْ قَاصِفًۭا مِّنَ ٱلرِّيحِ فَيُغْرِقَكُم بِمَا كَفَرْتُمْ ۙ ثُمَّ لَا تَجِدُوا۟ لَكُمْ عَلَيْنَا بِهِۦ تَبِيعًۭا', 289, 15, 115, 0),
  (17, 70, 2099, '۞ وَلَقَدْ كَرَّمْنَا بَنِىٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَىٰ كَثِيرٍۢ مِّمَّنْ خَلَقْنَا تَفْضِيلًۭا', 289, 15, 116, 0),
  (17, 71, 2100, 'يَوْمَ نَدْعُوا۟ كُلَّ أُنَاسٍۭ بِإِمَٰمِهِمْ ۖ فَمَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُو۟لَٰٓئِكَ يَقْرَءُونَ كِتَٰبَهُمْ وَلَا يُظْلَمُونَ فَتِيلًۭا', 289, 15, 116, 0),
  (17, 72, 2101, 'وَمَن كَانَ فِى هَٰذِهِۦٓ أَعْمَىٰ فَهُوَ فِى ٱلْءَاخِرَةِ أَعْمَىٰ وَأَضَلُّ سَبِيلًۭا', 289, 15, 116, 0),
  (17, 73, 2102, 'وَإِن كَادُوا۟ لَيَفْتِنُونَكَ عَنِ ٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ لِتَفْتَرِىَ عَلَيْنَا غَيْرَهُۥ ۖ وَإِذًۭا لَّٱتَّخَذُوكَ خَلِيلًۭا', 289, 15, 116, 0),
  (17, 74, 2103, 'وَلَوْلَآ أَن ثَبَّتْنَٰكَ لَقَدْ كِدتَّ تَرْكَنُ إِلَيْهِمْ شَيْـًۭٔا قَلِيلًا', 289, 15, 116, 0),
  (17, 75, 2104, 'إِذًۭا لَّأَذَقْنَٰكَ ضِعْفَ ٱلْحَيَوٰةِ وَضِعْفَ ٱلْمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيْنَا نَصِيرًۭا', 289, 15, 116, 0),
  (17, 76, 2105, 'وَإِن كَادُوا۟ لَيَسْتَفِزُّونَكَ مِنَ ٱلْأَرْضِ لِيُخْرِجُوكَ مِنْهَا ۖ وَإِذًۭا لَّا يَلْبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلًۭا', 290, 15, 116, 0),
  (17, 77, 2106, 'سُنَّةَ مَن قَدْ أَرْسَلْنَا قَبْلَكَ مِن رُّسُلِنَا ۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحْوِيلًا', 290, 15, 116, 0),
  (17, 78, 2107, 'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمْسِ إِلَىٰ غَسَقِ ٱلَّيْلِ وَقُرْءَانَ ٱلْفَجْرِ ۖ إِنَّ قُرْءَانَ ٱلْفَجْرِ كَانَ مَشْهُودًۭا', 290, 15, 116, 0),
  (17, 79, 2108, 'وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةًۭ لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًۭا مَّحْمُودًۭا', 290, 15, 116, 0),
  (17, 80, 2109, 'وَقُل رَّبِّ أَدْخِلْنِى مُدْخَلَ صِدْقٍۢ وَأَخْرِجْنِى مُخْرَجَ صِدْقٍۢ وَٱجْعَل لِّى مِن لَّدُنكَ سُلْطَٰنًۭا نَّصِيرًۭا', 290, 15, 116, 0),
  (17, 81, 2110, 'وَقُلْ جَآءَ ٱلْحَقُّ وَزَهَقَ ٱلْبَٰطِلُ ۚ إِنَّ ٱلْبَٰطِلَ كَانَ زَهُوقًۭا', 290, 15, 116, 0),
  (17, 82, 2111, 'وَنُنَزِّلُ مِنَ ٱلْقُرْءَانِ مَا هُوَ شِفَآءٌۭ وَرَحْمَةٌۭ لِّلْمُؤْمِنِينَ ۙ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارًۭا', 290, 15, 116, 0),
  (17, 83, 2112, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ ۖ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسًۭا', 290, 15, 116, 0),
  (17, 84, 2113, 'قُلْ كُلٌّۭ يَعْمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمْ أَعْلَمُ بِمَنْ هُوَ أَهْدَىٰ سَبِيلًۭا', 290, 15, 116, 0),
  (17, 85, 2114, 'وَيَسْـَٔلُونَكَ عَنِ ٱلرُّوحِ ۖ قُلِ ٱلرُّوحُ مِنْ أَمْرِ رَبِّى وَمَآ أُوتِيتُم مِّنَ ٱلْعِلْمِ إِلَّا قَلِيلًۭا', 290, 15, 116, 0),
  (17, 86, 2115, 'وَلَئِن شِئْنَا لَنَذْهَبَنَّ بِٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيْنَا وَكِيلًا', 290, 15, 116, 0),
  (17, 87, 2116, 'إِلَّا رَحْمَةًۭ مِّن رَّبِّكَ ۚ إِنَّ فَضْلَهُۥ كَانَ عَلَيْكَ كَبِيرًۭا', 291, 15, 116, 0),
  (17, 88, 2117, 'قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍۢ ظَهِيرًۭا', 291, 15, 116, 0),
  (17, 89, 2118, 'وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍۢ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًۭا', 291, 15, 116, 0),
  (17, 90, 2119, 'وَقَالُوا۟ لَن نُّؤْمِنَ لَكَ حَتَّىٰ تَفْجُرَ لَنَا مِنَ ٱلْأَرْضِ يَنۢبُوعًا', 291, 15, 116, 0),
  (17, 91, 2120, 'أَوْ تَكُونَ لَكَ جَنَّةٌۭ مِّن نَّخِيلٍۢ وَعِنَبٍۢ فَتُفَجِّرَ ٱلْأَنْهَٰرَ خِلَٰلَهَا تَفْجِيرًا', 291, 15, 116, 0),
  (17, 92, 2121, 'أَوْ تُسْقِطَ ٱلسَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِٱللَّهِ وَٱلْمَلَٰٓئِكَةِ قَبِيلًا', 291, 15, 116, 0),
  (17, 93, 2122, 'أَوْ يَكُونَ لَكَ بَيْتٌۭ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِى ٱلسَّمَآءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَٰبًۭا نَّقْرَؤُهُۥ ۗ قُلْ سُبْحَانَ رَبِّى هَلْ كُنتُ إِلَّا بَشَرًۭا رَّسُولًۭا', 291, 15, 116, 0),
  (17, 94, 2123, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰٓ إِلَّآ أَن قَالُوٓا۟ أَبَعَثَ ٱللَّهُ بَشَرًۭا رَّسُولًۭا', 291, 15, 116, 0),
  (17, 95, 2124, 'قُل لَّوْ كَانَ فِى ٱلْأَرْضِ مَلَٰٓئِكَةٌۭ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ ٱلسَّمَآءِ مَلَكًۭا رَّسُولًۭا', 291, 15, 116, 0),
  (17, 96, 2125, 'قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًۢا بَصِيرًۭا', 291, 15, 116, 0),
  (17, 97, 2126, 'وَمَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَآءَ مِن دُونِهِۦ ۖ وَنَحْشُرُهُمْ يَوْمَ ٱلْقِيَٰمَةِ عَلَىٰ وُجُوهِهِمْ عُمْيًۭا وَبُكْمًۭا وَصُمًّۭا ۖ مَّأْوَىٰهُمْ جَهَنَّمُ ۖ كُلَّمَا خَبَتْ زِدْنَٰهُمْ سَعِيرًۭا', 292, 15, 116, 0),
  (17, 98, 2127, 'ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمْ كَفَرُوا۟ بِـَٔايَٰتِنَا وَقَالُوٓا۟ أَءِذَا كُنَّا عِظَٰمًۭا وَرُفَٰتًا أَءِنَّا لَمَبْعُوثُونَ خَلْقًۭا جَدِيدًا', 292, 15, 116, 0),
  (17, 99, 2128, '۞ أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ قَادِرٌ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًۭا لَّا رَيْبَ فِيهِ فَأَبَى ٱلظَّٰلِمُونَ إِلَّا كُفُورًۭا', 292, 15, 117, 0),
  (17, 100, 2129, 'قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَآئِنَ رَحْمَةِ رَبِّىٓ إِذًۭا لَّأَمْسَكْتُمْ خَشْيَةَ ٱلْإِنفَاقِ ۚ وَكَانَ ٱلْإِنسَٰنُ قَتُورًۭا', 292, 15, 117, 0),
  (17, 101, 2130, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ تِسْعَ ءَايَٰتٍۭ بَيِّنَٰتٍۢ ۖ فَسْـَٔلْ بَنِىٓ إِسْرَٰٓءِيلَ إِذْ جَآءَهُمْ فَقَالَ لَهُۥ فِرْعَوْنُ إِنِّى لَأَظُنُّكَ يَٰمُوسَىٰ مَسْحُورًۭا', 292, 15, 117, 0),
  (17, 102, 2131, 'قَالَ لَقَدْ عَلِمْتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ بَصَآئِرَ وَإِنِّى لَأَظُنُّكَ يَٰفِرْعَوْنُ مَثْبُورًۭا', 292, 15, 117, 0),
  (17, 103, 2132, 'فَأَرَادَ أَن يَسْتَفِزَّهُم مِّنَ ٱلْأَرْضِ فَأَغْرَقْنَٰهُ وَمَن مَّعَهُۥ جَمِيعًۭا', 292, 15, 117, 0),
  (17, 104, 2133, 'وَقُلْنَا مِنۢ بَعْدِهِۦ لِبَنِىٓ إِسْرَٰٓءِيلَ ٱسْكُنُوا۟ ٱلْأَرْضَ فَإِذَا جَآءَ وَعْدُ ٱلْءَاخِرَةِ جِئْنَا بِكُمْ لَفِيفًۭا', 292, 15, 117, 0),
  (17, 105, 2134, 'وَبِٱلْحَقِّ أَنزَلْنَٰهُ وَبِٱلْحَقِّ نَزَلَ ۗ وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًۭا وَنَذِيرًۭا', 293, 15, 117, 0),
  (17, 106, 2135, 'وَقُرْءَانًۭا فَرَقْنَٰهُ لِتَقْرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكْثٍۢ وَنَزَّلْنَٰهُ تَنزِيلًۭا', 293, 15, 117, 0),
  (17, 107, 2136, 'قُلْ ءَامِنُوا۟ بِهِۦٓ أَوْ لَا تُؤْمِنُوٓا۟ ۚ إِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مِن قَبْلِهِۦٓ إِذَا يُتْلَىٰ عَلَيْهِمْ يَخِرُّونَ لِلْأَذْقَانِ سُجَّدًۭا', 293, 15, 117, 0),
  (17, 108, 2137, 'وَيَقُولُونَ سُبْحَٰنَ رَبِّنَآ إِن كَانَ وَعْدُ رَبِّنَا لَمَفْعُولًۭا', 293, 15, 117, 0),
  (17, 109, 2138, 'وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًۭا ۩', 293, 15, 117, 1),
  (17, 110, 2139, 'قُلِ ٱدْعُوا۟ ٱللَّهَ أَوِ ٱدْعُوا۟ ٱلرَّحْمَٰنَ ۖ أَيًّۭا مَّا تَدْعُوا۟ فَلَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَٱبْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًۭا', 293, 15, 117, 0),
  (17, 111, 2140, 'وَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَمْ يَتَّخِذْ وَلَدًۭا وَلَمْ يَكُن لَّهُۥ شَرِيكٌۭ فِى ٱلْمُلْكِ وَلَمْ يَكُن لَّهُۥ وَلِىٌّۭ مِّنَ ٱلذُّلِّ ۖ وَكَبِّرْهُ تَكْبِيرًۢا', 293, 15, 117, 0),
  (18, 1, 2141, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَنزَلَ عَلَىٰ عَبْدِهِ ٱلْكِتَٰبَ وَلَمْ يَجْعَل لَّهُۥ عِوَجَا ۜ', 293, 15, 117, 0),
  (18, 2, 2142, 'قَيِّمًۭا لِّيُنذِرَ بَأْسًۭا شَدِيدًۭا مِّن لَّدُنْهُ وَيُبَشِّرَ ٱلْمُؤْمِنِينَ ٱلَّذِينَ يَعْمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًۭا', 293, 15, 117, 0),
  (18, 3, 2143, 'مَّٰكِثِينَ فِيهِ أَبَدًۭا', 293, 15, 117, 0),
  (18, 4, 2144, 'وَيُنذِرَ ٱلَّذِينَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًۭا', 293, 15, 117, 0),
  (18, 5, 2145, 'مَّا لَهُم بِهِۦ مِنْ عِلْمٍۢ وَلَا لِءَابَآئِهِمْ ۚ كَبُرَتْ كَلِمَةًۭ تَخْرُجُ مِنْ أَفْوَٰهِهِمْ ۚ إِن يَقُولُونَ إِلَّا كَذِبًۭا', 294, 15, 117, 0),
  (18, 6, 2146, 'فَلَعَلَّكَ بَٰخِعٌۭ نَّفْسَكَ عَلَىٰٓ ءَاثَٰرِهِمْ إِن لَّمْ يُؤْمِنُوا۟ بِهَٰذَا ٱلْحَدِيثِ أَسَفًا', 294, 15, 117, 0),
  (18, 7, 2147, 'إِنَّا جَعَلْنَا مَا عَلَى ٱلْأَرْضِ زِينَةًۭ لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًۭا', 294, 15, 117, 0),
  (18, 8, 2148, 'وَإِنَّا لَجَٰعِلُونَ مَا عَلَيْهَا صَعِيدًۭا جُرُزًا', 294, 15, 117, 0),
  (18, 9, 2149, 'أَمْ حَسِبْتَ أَنَّ أَصْحَٰبَ ٱلْكَهْفِ وَٱلرَّقِيمِ كَانُوا۟ مِنْ ءَايَٰتِنَا عَجَبًا', 294, 15, 117, 0),
  (18, 10, 2150, 'إِذْ أَوَى ٱلْفِتْيَةُ إِلَى ٱلْكَهْفِ فَقَالُوا۟ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحْمَةًۭ وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًۭا', 294, 15, 117, 0),
  (18, 11, 2151, 'فَضَرَبْنَا عَلَىٰٓ ءَاذَانِهِمْ فِى ٱلْكَهْفِ سِنِينَ عَدَدًۭا', 294, 15, 117, 0),
  (18, 12, 2152, 'ثُمَّ بَعَثْنَٰهُمْ لِنَعْلَمَ أَىُّ ٱلْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوٓا۟ أَمَدًۭا', 294, 15, 117, 0),
  (18, 13, 2153, 'نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ ۚ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَٰهُمْ هُدًۭى', 294, 15, 117, 0),
  (18, 14, 2154, 'وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَن نَّدْعُوَا۟ مِن دُونِهِۦٓ إِلَٰهًۭا ۖ لَّقَدْ قُلْنَآ إِذًۭا شَطَطًا', 294, 15, 117, 0),
  (18, 15, 2155, 'هَٰٓؤُلَآءِ قَوْمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةًۭ ۖ لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَٰنٍۭ بَيِّنٍۢ ۖ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا', 294, 15, 117, 0),
  (18, 16, 2156, 'وَإِذِ ٱعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا ٱللَّهَ فَأْوُۥٓا۟ إِلَى ٱلْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًۭا', 295, 15, 117, 0),
  (18, 17, 2157, '۞ وَتَرَى ٱلشَّمْسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهْفِهِمْ ذَاتَ ٱلْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ ٱلشِّمَالِ وَهُمْ فِى فَجْوَةٍۢ مِّنْهُ ۚ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ ۗ مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِ ۖ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُۥ وَلِيًّۭا مُّرْشِدًۭا', 295, 15, 118, 0),
  (18, 18, 2158, 'وَتَحْسَبُهُمْ أَيْقَاظًۭا وَهُمْ رُقُودٌۭ ۚ وَنُقَلِّبُهُمْ ذَاتَ ٱلْيَمِينِ وَذَاتَ ٱلشِّمَالِ ۖ وَكَلْبُهُم بَٰسِطٌۭ ذِرَاعَيْهِ بِٱلْوَصِيدِ ۚ لَوِ ٱطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًۭا وَلَمُلِئْتَ مِنْهُمْ رُعْبًۭا', 295, 15, 118, 0),
  (18, 19, 2159, 'وَكَذَٰلِكَ بَعَثْنَٰهُمْ لِيَتَسَآءَلُوا۟ بَيْنَهُمْ ۚ قَالَ قَآئِلٌۭ مِّنْهُمْ كَمْ لَبِثْتُمْ ۖ قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍۢ ۚ قَالُوا۟ رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَٱبْعَثُوٓا۟ أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِۦٓ إِلَى ٱلْمَدِينَةِ فَلْيَنظُرْ أَيُّهَآ أَزْكَىٰ طَعَامًۭا فَلْيَأْتِكُم بِرِزْقٍۢ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا', 295, 15, 118, 0),
  (18, 20, 2160, 'إِنَّهُمْ إِن يَظْهَرُوا۟ عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِى مِلَّتِهِمْ وَلَن تُفْلِحُوٓا۟ إِذًا أَبَدًۭا', 295, 15, 118, 0),
  (18, 21, 2161, 'وَكَذَٰلِكَ أَعْثَرْنَا عَلَيْهِمْ لِيَعْلَمُوٓا۟ أَنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَأَنَّ ٱلسَّاعَةَ لَا رَيْبَ فِيهَآ إِذْ يَتَنَٰزَعُونَ بَيْنَهُمْ أَمْرَهُمْ ۖ فَقَالُوا۟ ٱبْنُوا۟ عَلَيْهِم بُنْيَٰنًۭا ۖ رَّبُّهُمْ أَعْلَمُ بِهِمْ ۚ قَالَ ٱلَّذِينَ غَلَبُوا۟ عَلَىٰٓ أَمْرِهِمْ لَنَتَّخِذَنَّ عَلَيْهِم مَّسْجِدًۭا', 296, 15, 118, 0),
  (18, 22, 2162, 'سَيَقُولُونَ ثَلَٰثَةٌۭ رَّابِعُهُمْ كَلْبُهُمْ وَيَقُولُونَ خَمْسَةٌۭ سَادِسُهُمْ كَلْبُهُمْ رَجْمًۢا بِٱلْغَيْبِ ۖ وَيَقُولُونَ سَبْعَةٌۭ وَثَامِنُهُمْ كَلْبُهُمْ ۚ قُل رَّبِّىٓ أَعْلَمُ بِعِدَّتِهِم مَّا يَعْلَمُهُمْ إِلَّا قَلِيلٌۭ ۗ فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَآءًۭ ظَٰهِرًۭا وَلَا تَسْتَفْتِ فِيهِم مِّنْهُمْ أَحَدًۭا', 296, 15, 118, 0),
  (18, 23, 2163, 'وَلَا تَقُولَنَّ لِشَا۟ىْءٍ إِنِّى فَاعِلٌۭ ذَٰلِكَ غَدًا', 296, 15, 118, 0),
  (18, 24, 2164, 'إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ وَٱذْكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلْ عَسَىٰٓ أَن يَهْدِيَنِ رَبِّى لِأَقْرَبَ مِنْ هَٰذَا رَشَدًۭا', 296, 15, 118, 0),
  (18, 25, 2165, 'وَلَبِثُوا۟ فِى كَهْفِهِمْ ثَلَٰثَ مِا۟ئَةٍۢ سِنِينَ وَٱزْدَادُوا۟ تِسْعًۭا', 296, 15, 118, 0),
  (18, 26, 2166, 'قُلِ ٱللَّهُ أَعْلَمُ بِمَا لَبِثُوا۟ ۖ لَهُۥ غَيْبُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ أَبْصِرْ بِهِۦ وَأَسْمِعْ ۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِىٍّۢ وَلَا يُشْرِكُ فِى حُكْمِهِۦٓ أَحَدًۭا', 296, 15, 118, 0),
  (18, 27, 2167, 'وَٱتْلُ مَآ أُوحِىَ إِلَيْكَ مِن كِتَابِ رَبِّكَ ۖ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلْتَحَدًۭا', 296, 15, 118, 0),
  (18, 28, 2168, 'وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ تُرِيدُ زِينَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُۥ عَن ذِكْرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمْرُهُۥ فُرُطًۭا', 297, 15, 118, 0),
  (18, 29, 2169, 'وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْ ۚ إِنَّآ أَعْتَدْنَا لِلظَّٰلِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا ۚ وَإِن يَسْتَغِيثُوا۟ يُغَاثُوا۟ بِمَآءٍۢ كَٱلْمُهْلِ يَشْوِى ٱلْوُجُوهَ ۚ بِئْسَ ٱلشَّرَابُ وَسَآءَتْ مُرْتَفَقًا', 297, 15, 118, 0),
  (18, 30, 2170, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا', 297, 15, 118, 0),
  (18, 31, 2171, 'أُو۟لَٰٓئِكَ لَهُمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍۢ وَيَلْبَسُونَ ثِيَابًا خُضْرًۭا مِّن سُندُسٍۢ وَإِسْتَبْرَقٍۢ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۚ نِعْمَ ٱلثَّوَابُ وَحَسُنَتْ مُرْتَفَقًۭا', 297, 15, 118, 0),
  (18, 32, 2172, '۞ وَٱضْرِبْ لَهُم مَّثَلًۭا رَّجُلَيْنِ جَعَلْنَا لِأَحَدِهِمَا جَنَّتَيْنِ مِنْ أَعْنَٰبٍۢ وَحَفَفْنَٰهُمَا بِنَخْلٍۢ وَجَعَلْنَا بَيْنَهُمَا زَرْعًۭا', 297, 15, 119, 0),
  (18, 33, 2173, 'كِلْتَا ٱلْجَنَّتَيْنِ ءَاتَتْ أُكُلَهَا وَلَمْ تَظْلِم مِّنْهُ شَيْـًۭٔا ۚ وَفَجَّرْنَا خِلَٰلَهُمَا نَهَرًۭا', 297, 15, 119, 0),
  (18, 34, 2174, 'وَكَانَ لَهُۥ ثَمَرٌۭ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكْثَرُ مِنكَ مَالًۭا وَأَعَزُّ نَفَرًۭا', 297, 15, 119, 0),
  (18, 35, 2175, 'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٌۭ لِّنَفْسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدًۭا', 298, 15, 119, 0),
  (18, 36, 2176, 'وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةًۭ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّى لَأَجِدَنَّ خَيْرًۭا مِّنْهَا مُنقَلَبًۭا', 298, 15, 119, 0),
  (18, 37, 2177, 'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرْتَ بِٱلَّذِى خَلَقَكَ مِن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ سَوَّىٰكَ رَجُلًۭا', 298, 15, 119, 0),
  (18, 38, 2178, 'لَّٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّى وَلَآ أُشْرِكُ بِرَبِّىٓ أَحَدًۭا', 298, 15, 119, 0),
  (18, 39, 2179, 'وَلَوْلَآ إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِ ۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالًۭا وَوَلَدًۭا', 298, 15, 119, 0),
  (18, 40, 2180, 'فَعَسَىٰ رَبِّىٓ أَن يُؤْتِيَنِ خَيْرًۭا مِّن جَنَّتِكَ وَيُرْسِلَ عَلَيْهَا حُسْبَانًۭا مِّنَ ٱلسَّمَآءِ فَتُصْبِحَ صَعِيدًۭا زَلَقًا', 298, 15, 119, 0),
  (18, 41, 2181, 'أَوْ يُصْبِحَ مَآؤُهَا غَوْرًۭا فَلَن تَسْتَطِيعَ لَهُۥ طَلَبًۭا', 298, 15, 119, 0),
  (18, 42, 2182, 'وَأُحِيطَ بِثَمَرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيْتَنِى لَمْ أُشْرِكْ بِرَبِّىٓ أَحَدًۭا', 298, 15, 119, 0),
  (18, 43, 2183, 'وَلَمْ تَكُن لَّهُۥ فِئَةٌۭ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا', 298, 15, 119, 0),
  (18, 44, 2184, 'هُنَالِكَ ٱلْوَلَٰيَةُ لِلَّهِ ٱلْحَقِّ ۚ هُوَ خَيْرٌۭ ثَوَابًۭا وَخَيْرٌ عُقْبًۭا', 298, 15, 119, 0),
  (18, 45, 2185, 'وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًۭا تَذْرُوهُ ٱلرِّيَٰحُ ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ مُّقْتَدِرًا', 298, 15, 119, 0),
  (18, 46, 2186, 'ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًۭا وَخَيْرٌ أَمَلًۭا', 299, 15, 119, 0),
  (18, 47, 2187, 'وَيَوْمَ نُسَيِّرُ ٱلْجِبَالَ وَتَرَى ٱلْأَرْضَ بَارِزَةًۭ وَحَشَرْنَٰهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًۭا', 299, 15, 119, 0),
  (18, 48, 2188, 'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفًّۭا لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَٰكُمْ أَوَّلَ مَرَّةٍۭ ۚ بَلْ زَعَمْتُمْ أَلَّن نَّجْعَلَ لَكُم مَّوْعِدًۭا', 299, 15, 119, 0),
  (18, 49, 2189, 'وَوُضِعَ ٱلْكِتَٰبُ فَتَرَى ٱلْمُجْرِمِينَ مُشْفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيْلَتَنَا مَالِ هَٰذَا ٱلْكِتَٰبِ لَا يُغَادِرُ صَغِيرَةًۭ وَلَا كَبِيرَةً إِلَّآ أَحْصَىٰهَا ۚ وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرًۭا ۗ وَلَا يَظْلِمُ رَبُّكَ أَحَدًۭا', 299, 15, 119, 0),
  (18, 50, 2190, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ كَانَ مِنَ ٱلْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِۦٓ ۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوْلِيَآءَ مِن دُونِى وَهُمْ لَكُمْ عَدُوٌّۢ ۚ بِئْسَ لِلظَّٰلِمِينَ بَدَلًۭا', 299, 15, 119, 0),
  (18, 51, 2191, '۞ مَّآ أَشْهَدتُّهُمْ خَلْقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ ٱلْمُضِلِّينَ عَضُدًۭا', 299, 15, 120, 0),
  (18, 52, 2192, 'وَيَوْمَ يَقُولُ نَادُوا۟ شُرَكَآءِىَ ٱلَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا۟ لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًۭا', 299, 15, 120, 0),
  (18, 53, 2193, 'وَرَءَا ٱلْمُجْرِمُونَ ٱلنَّارَ فَظَنُّوٓا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا۟ عَنْهَا مَصْرِفًۭا', 299, 15, 120, 0),
  (18, 54, 2194, 'وَلَقَدْ صَرَّفْنَا فِى هَٰذَا ٱلْقُرْءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٍۢ ۚ وَكَانَ ٱلْإِنسَٰنُ أَكْثَرَ شَىْءٍۢ جَدَلًۭا', 300, 15, 120, 0),
  (18, 55, 2195, 'وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤْمِنُوٓا۟ إِذْ جَآءَهُمُ ٱلْهُدَىٰ وَيَسْتَغْفِرُوا۟ رَبَّهُمْ إِلَّآ أَن تَأْتِيَهُمْ سُنَّةُ ٱلْأَوَّلِينَ أَوْ يَأْتِيَهُمُ ٱلْعَذَابُ قُبُلًۭا', 300, 15, 120, 0),
  (18, 56, 2196, 'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ ۖ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَمَآ أُنذِرُوا۟ هُزُوًۭا', 300, 15, 120, 0),
  (18, 57, 2197, 'وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعْرَضَ عَنْهَا وَنَسِىَ مَا قَدَّمَتْ يَدَاهُ ۚ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًۭا ۖ وَإِن تَدْعُهُمْ إِلَى ٱلْهُدَىٰ فَلَن يَهْتَدُوٓا۟ إِذًا أَبَدًۭا', 300, 15, 120, 0),
  (18, 58, 2198, 'وَرَبُّكَ ٱلْغَفُورُ ذُو ٱلرَّحْمَةِ ۖ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلْعَذَابَ ۚ بَل لَّهُم مَّوْعِدٌۭ لَّن يَجِدُوا۟ مِن دُونِهِۦ مَوْئِلًۭا', 300, 15, 120, 0),
  (18, 59, 2199, 'وَتِلْكَ ٱلْقُرَىٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُوا۟ وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًۭا', 300, 15, 120, 0),
  (18, 60, 2200, 'وَإِذْ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبْرَحُ حَتَّىٰٓ أَبْلُغَ مَجْمَعَ ٱلْبَحْرَيْنِ أَوْ أَمْضِىَ حُقُبًۭا', 300, 15, 120, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 18, 1, '[All] praise is [due] to Allah, who has sent down upon His Servant the Book and has not made therein any deviance.'),
  ('en.sahih', 18, 2, '[He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward'),
  ('en.sahih', 18, 3, 'In which they will remain forever'),
  ('en.sahih', 18, 4, 'And to warn those who say, "Allah has taken a son."'),
  ('en.sahih', 18, 5, 'They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie.'),
  ('en.sahih', 18, 6, 'Then perhaps you would kill yourself through grief over them, [O Muhammad], if they do not believe in this message, [and] out of sorrow.'),
  ('en.sahih', 18, 7, 'Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed.'),
  ('en.sahih', 18, 8, 'And indeed, We will make that which is upon it [into] a barren ground.'),
  ('en.sahih', 18, 9, 'Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder?'),
  ('en.sahih', 18, 10, '[Mention] when the youths retreated to the cave and said, "Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance."'),
  ('en.sahih', 18, 11, 'So We cast [a cover of sleep] over their ears within the cave for a number of years.'),
  ('en.sahih', 18, 12, 'Then We awakened them that We might show which of the two factions was most precise in calculating what [extent] they had remained in time.'),
  ('en.sahih', 18, 13, 'It is We who relate to you, [O Muhammad], their story in truth. Indeed, they were youths who believed in their Lord, and We increased them in guidance.'),
  ('en.sahih', 18, 14, 'And We made firm their hearts when they stood up and said, "Our Lord is the Lord of the heavens and the earth. Never will we invoke besides Him any deity. We would have certainly spoken, then, an excessive transgression.'),
  ('en.sahih', 18, 15, 'These, our people, have taken besides Him deities. Why do they not bring for [worship of] them a clear authority? And who is more unjust than one who invents about Allah a lie?"'),
  ('en.sahih', 18, 16, '[The youths said to one another], "And when you have withdrawn from them and that which they worship other than Allah, retreat to the cave. Your Lord will spread out for you of His mercy and will prepare for you from your affair facility."'),
  ('en.sahih', 18, 17, 'And [had you been present], you would see the sun when it rose, inclining away from their cave on the right, and when it set, passing away from them on the left, while they were [laying] within an open space thereof. That was from the signs of Allah. He whom Allah guides is the [rightly] guided, but he whom He leaves astray - never will you find for him a protecting guide.'),
  ('en.sahih', 18, 18, 'And you would think them awake, while they were asleep. And We turned them to the right and to the left, while their dog stretched his forelegs at the entrance. If you had looked at them, you would have turned from them in flight and been filled by them with terror.'),
  ('en.sahih', 18, 19, 'And similarly, We awakened them that they might question one another. Said a speaker from among them, "How long have you remained [here]?" They said, "We have remained a day or part of a day." They said, "Your Lord is most knowing of how long you remained. So send one of you with this silver coin of yours to the city and let him look to which is the best of food and bring you provision from it and let him be cautious. And let no one be aware of you.'),
  ('en.sahih', 18, 20, 'Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever."'),
  ('en.sahih', 18, 21, 'And similarly, We caused them to be found that they [who found them] would know that the promise of Allah is truth and that of the Hour there is no doubt. [That was] when they disputed among themselves about their affair and [then] said, "Construct over them a structure. Their Lord is most knowing about them." Said those who prevailed in the matter, "We will surely take [for ourselves] over them a masjid."'),
  ('en.sahih', 18, 22, 'They will say there were three, the fourth of them being their dog; and they will say there were five, the sixth of them being their dog - guessing at the unseen; and they will say there were seven, and the eighth of them was their dog. Say, [O Muhammad], "My Lord is most knowing of their number. None knows them except a few. So do not argue about them except with an obvious argument and do not inquire about them among [the speculators] from anyone."'),
  ('en.sahih', 18, 23, 'And never say of anything, "Indeed, I will do that tomorrow,"'),
  ('en.sahih', 18, 24, 'Except [when adding], "If Allah wills." And remember your Lord when you forget [it] and say, "Perhaps my Lord will guide me to what is nearer than this to right conduct."'),
  ('en.sahih', 18, 25, 'And they remained in their cave for three hundred years and exceeded by nine.'),
  ('en.sahih', 18, 26, 'Say, "Allah is most knowing of how long they remained. He has [knowledge of] the unseen [aspects] of the heavens and the earth. How Seeing is He and how Hearing! They have not besides Him any protector, and He shares not His legislation with anyone."'),
  ('en.sahih', 18, 27, 'And recite, [O Muhammad], what has been revealed to you of the Book of your Lord. There is no changer of His words, and never will you find in other than Him a refuge.'),
  ('en.sahih', 18, 28, 'And keep yourself patient [by being] with those who call upon their Lord in the morning and the evening, seeking His countenance. And let not your eyes pass beyond them, desiring adornments of the worldly life, and do not obey one whose heart We have made heedless of Our remembrance and who follows his desire and whose affair is ever [in] neglect.'),
  ('en.sahih', 18, 29, 'And say, "The truth is from your Lord, so whoever wills - let him believe; and whoever wills - let him disbelieve." Indeed, We have prepared for the wrongdoers a fire whose walls will surround them. And if they call for relief, they will be relieved with water like murky oil, which scalds [their] faces. Wretched is the drink, and evil is the resting place.'),
  ('en.sahih', 18, 30, 'Indeed, those who have believed and done righteous deeds - indeed, We will not allow to be lost the reward of any who did well in deeds.'),
  ('en.sahih', 18, 31, 'Those will have gardens of perpetual residence; beneath them rivers will flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein on adorned couches. Excellent is the reward, and good is the resting place.'),
  ('en.sahih', 18, 32, 'And present to them an example of two men: We granted to one of them two gardens of grapevines, and We bordered them with palm trees and placed between them [fields of] crops.'),
  ('en.sahih', 18, 33, 'Each of the two gardens produced its fruit and did not fall short thereof in anything. And We caused to gush forth within them a river.'),
  ('en.sahih', 18, 34, 'And he had fruit, so he said to his companion while he was conversing with him, "I am greater than you in wealth and mightier in [numbers of] men."'),
  ('en.sahih', 18, 35, 'And he entered his garden while he was unjust to himself. He said, "I do not think that this will perish - ever.'),
  ('en.sahih', 18, 36, 'And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return."'),
  ('en.sahih', 18, 37, 'His companion said to him while he was conversing with him, "Have you disbelieved in He who created you from dust and then from a sperm-drop and then proportioned you [as] a man?'),
  ('en.sahih', 18, 38, 'But as for me, He is Allah, my Lord, and I do not associate with my Lord anyone.'),
  ('en.sahih', 18, 39, 'And why did you, when you entered your garden, not say, \'What Allah willed [has occurred]; there is no power except in Allah \'? Although you see me less than you in wealth and children,'),
  ('en.sahih', 18, 40, 'It may be that my Lord will give me [something] better than your garden and will send upon it a calamity from the sky, and it will become a smooth, dusty ground,'),
  ('en.sahih', 18, 41, 'Or its water will become sunken [into the earth], so you would never be able to seek it."'),
  ('en.sahih', 18, 42, 'And his fruits were encompassed [by ruin], so he began to turn his hands about [in dismay] over what he had spent on it, while it had collapsed upon its trellises, and said, "Oh, I wish I had not associated with my Lord anyone."'),
  ('en.sahih', 18, 43, 'And there was for him no company to aid him other than Allah, nor could he defend himself.'),
  ('en.sahih', 18, 44, 'There the authority is [completely] for Allah, the Truth. He is best in reward and best in outcome.'),
  ('en.sahih', 18, 45, 'And present to them the example of the life of this world, [its being] like rain which We send down from the sky, and the vegetation of the earth mingles with it and [then] it becomes dry remnants, scattered by the winds. And Allah is ever, over all things, Perfect in Ability.'),
  ('en.sahih', 18, 46, 'Wealth and children are [but] adornment of the worldly life. But the enduring good deeds are better to your Lord for reward and better for [one\'s] hope.'),
  ('en.sahih', 18, 47, 'And [warn of] the Day when We will remove the mountains and you will see the earth prominent, and We will gather them and not leave behind from them anyone.'),
  ('en.sahih', 18, 48, 'And they will be presented before your Lord in rows, [and He will say], "You have certainly come to Us just as We created you the first time. But you claimed that We would never make for you an appointment."'),
  ('en.sahih', 18, 49, 'And the record [of deeds] will be placed [open], and you will see the criminals fearful of that within it, and they will say, "Oh, woe to us! What is this book that leaves nothing small or great except that it has enumerated it?" And they will find what they did present [before them]. And your Lord does injustice to no one.'),
  ('en.sahih', 18, 50, 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except for Iblees. He was of the jinn and departed from the command of his Lord. Then will you take him and his descendants as allies other than Me while they are enemies to you? Wretched it is for the wrongdoers as an exchange.'),
  ('en.sahih', 18, 51, 'I did not make them witness to the creation of the heavens and the earth or to the creation of themselves, and I would not have taken the misguiders as assistants.'),
  ('en.sahih', 18, 52, 'And [warn of] the Day when He will say, "Call \'My partners\' whom you claimed," and they will invoke them, but they will not respond to them. And We will put between them [a valley of] destruction.'),
  ('en.sahih', 18, 53, 'And the criminals will see the Fire and will be certain that they are to fall therein. And they will not find from it a way elsewhere.'),
  ('en.sahih', 18, 54, 'And We have certainly diversified in this Qur\'an for the people from every [kind of] example; but man has ever been, most of anything, [prone to] dispute.'),
  ('en.sahih', 18, 55, 'And nothing has prevented the people from believing when guidance came to them and from asking forgiveness of their Lord except that there [must] befall them the [accustomed] precedent of the former peoples or that the punishment should come [directly] before them.'),
  ('en.sahih', 18, 56, 'And We send not the messengers except as bringers of good tidings and warners. And those who disbelieve dispute by [using] falsehood to [attempt to] invalidate thereby the truth and have taken My verses, and that of which they are warned, in ridicule.'),
  ('en.sahih', 18, 57, 'And who is more unjust than one who is reminded of the verses of his Lord but turns away from them and forgets what his hands have put forth? Indeed, We have placed over their hearts coverings, lest they understand it, and in their ears deafness. And if you invite them to guidance - they will never be guided, then - ever.'),
  ('en.sahih', 18, 58, 'And your Lord is the Forgiving, full of mercy. If He were to impose blame upon them for what they earned, He would have hastened for them the punishment. Rather, for them is an appointment from which they will never find an escape.'),
  ('en.sahih', 18, 59, 'And those cities - We destroyed them when they wronged, and We made for their destruction an appointed time.'),
  ('en.sahih', 18, 60, 'And [mention] when Moses said to his servant, "I will not cease [traveling] until I reach the junction of the two seas or continue for a long period."'),
  ('en.sahih', 18, 61, 'But when they reached the junction between them, they forgot their fish, and it took its course into the sea, slipping away.'),
  ('en.sahih', 18, 62, 'So when they had passed beyond it, [Moses] said to his boy, "Bring us our morning meal. We have certainly suffered in this, our journey, [much] fatigue."'),
  ('en.sahih', 18, 63, 'He said, "Did you see when we retired to the rock? Indeed, I forgot [there] the fish. And none made me forget it except Satan - that I should mention it. And it took its course into the sea amazingly".'),
  ('en.sahih', 18, 64, '[Moses] said, "That is what we were seeking." So they returned, following their footprints.'),
  ('en.sahih', 18, 65, 'And they found a servant from among Our servants to whom we had given mercy from us and had taught him from Us a [certain] knowledge.'),
  ('en.sahih', 18, 66, 'Moses said to him, "May I follow you on [the condition] that you teach me from what you have been taught of sound judgement?"'),
  ('en.sahih', 18, 67, 'He said, "Indeed, with me you will never be able to have patience.'),
  ('en.sahih', 18, 68, 'And how can you have patience for what you do not encompass in knowledge?"'),
  ('en.sahih', 18, 69, '[Moses] said, "You will find me, if Allah wills, patient, and I will not disobey you in [any] order."'),
  ('en.sahih', 18, 70, 'He said, "Then if you follow me, do not ask me about anything until I make to you about it mention."'),
  ('en.sahih', 18, 71, 'So they set out, until when they had embarked on the ship, al-Khidh r tore it open. [Moses] said, "Have you torn it open to drown its people? You have certainly done a grave thing."'),
  ('en.sahih', 18, 72, '[Al-Khidh r] said, "Did I not say that with me you would never be able to have patience?"'),
  ('en.sahih', 18, 73, '[Moses] said, "Do not blame me for what I forgot and do not cover me in my matter with difficulty."'),
  ('en.sahih', 18, 74, 'So they set out, until when they met a boy, al-Khidh r killed him. [Moses] said, "Have you killed a pure soul for other than [having killed] a soul? You have certainly done a deplorable thing."'),
  ('en.sahih', 18, 75, '[Al-Khidh r] said, "Did I not tell you that with me you would never be able to have patience?"'),
  ('en.sahih', 18, 76, '[Moses] said, "If I should ask you about anything after this, then do not keep me as a companion. You have obtained from me an excuse."'),
  ('en.sahih', 18, 77, 'So they set out, until when they came to the people of a town, they asked its people for food, but they refused to offer them hospitality. And they found therein a wall about to collapse, so al-Khidh r restored it. [Moses] said, "If you wished, you could have taken for it a payment."'),
  ('en.sahih', 18, 78, '[Al-Khidh r] said, "This is parting between me and you. I will inform you of the interpretation of that about which you could not have patience.'),
  ('en.sahih', 18, 79, 'As for the ship, it belonged to poor people working at sea. So I intended to cause defect in it as there was after them a king who seized every [good] ship by force.'),
  ('en.sahih', 18, 80, 'And as for the boy, his parents were believers, and we feared that he would overburden them by transgression and disbelief.'),
  ('en.sahih', 18, 81, 'So we intended that their Lord should substitute for them one better than him in purity and nearer to mercy.'),
  ('en.sahih', 18, 82, 'And as for the wall, it belonged to two orphan boys in the city, and there was beneath it a treasure for them, and their father had been righteous. So your Lord intended that they reach maturity and extract their treasure, as a mercy from your Lord. And I did it not of my own accord. That is the interpretation of that about which you could not have patience."'),
  ('en.sahih', 18, 83, 'And they ask you, [O Muhammad], about Dhul-Qarnayn. Say, "I will recite to you about him a report."'),
  ('en.sahih', 18, 84, 'Indeed We established him upon the earth, and We gave him to everything a way.'),
  ('en.sahih', 18, 85, 'So he followed a way'),
  ('en.sahih', 18, 86, 'Until, when he reached the setting of the sun, he found it [as if] setting in a spring of dark mud, and he found near it a people. Allah said, "O Dhul-Qarnayn, either you punish [them] or else adopt among them [a way of] goodness."'),
  ('en.sahih', 18, 87, 'He said, "As for one who wrongs, we will punish him. Then he will be returned to his Lord, and He will punish him with a terrible punishment.'),
  ('en.sahih', 18, 88, 'But as for one who believes and does righteousness, he will have a reward of Paradise, and we will speak to him from our command with ease."'),
  ('en.sahih', 18, 89, 'Then he followed a way'),
  ('en.sahih', 18, 90, 'Until, when he came to the rising of the sun, he found it rising on a people for whom We had not made against it any shield.'),
  ('en.sahih', 18, 91, 'Thus. And We had encompassed [all] that he had in knowledge.'),
  ('en.sahih', 18, 92, 'Then he followed a way'),
  ('en.sahih', 18, 93, 'Until, when he reached [a pass] between two mountains, he found beside them a people who could hardly understand [his] speech.'),
  ('en.sahih', 18, 94, 'They said, "O Dhul-Qarnayn, indeed Gog and Magog are [great] corrupters in the land. So may we assign for you an expenditure that you might make between us and them a barrier?"'),
  ('en.sahih', 18, 95, 'He said, "That in which my Lord has established me is better [than what you offer], but assist me with strength; I will make between you and them a dam.'),
  ('en.sahih', 18, 96, 'Bring me sheets of iron" - until, when he had leveled [them] between the two mountain walls, he said, "Blow [with bellows]," until when he had made it [like] fire, he said, "Bring me, that I may pour over it molten copper."'),
  ('en.sahih', 18, 97, 'So Gog and Magog were unable to pass over it, nor were they able [to effect] in it any penetration.'),
  ('en.sahih', 18, 98, '[Dhul-Qarnayn] said, "This is a mercy from my Lord; but when the promise of my Lord comes, He will make it level, and ever is the promise of my Lord true."'),
  ('en.sahih', 18, 99, 'And We will leave them that day surging over each other, and [then] the Horn will be blown, and We will assemble them in [one] assembly.'),
  ('en.sahih', 18, 100, 'And We will present Hell that Day to the Disbelievers, on display -'),
  ('en.sahih', 18, 101, 'Those whose eyes had been within a cover [removed] from My remembrance, and they were not able to hear.'),
  ('en.sahih', 18, 102, 'Then do those who disbelieve think that they can take My servants instead of Me as allies? Indeed, We have prepared Hell for the disbelievers as a lodging.'),
  ('en.sahih', 18, 103, 'Say, [O Muhammad], "Shall we [believers] inform you of the greatest losers as to [their] deeds?'),
  ('en.sahih', 18, 104, '[They are] those whose effort is lost in worldly life, while they think that they are doing well in work."'),
  ('en.sahih', 18, 105, 'Those are the ones who disbelieve in the verses of their Lord and in [their] meeting Him, so their deeds have become worthless; and We will not assign to them on the Day of Resurrection any importance.'),
  ('en.sahih', 18, 106, 'That is their recompense - Hell - for what they denied and [because] they took My signs and My messengers in ridicule.'),
  ('en.sahih', 18, 107, 'Indeed, those who have believed and done righteous deeds - they will have the Gardens of Paradise as a lodging,'),
  ('en.sahih', 18, 108, 'Wherein they abide eternally. They will not desire from it any transfer.'),
  ('en.sahih', 18, 109, 'Say, "If the sea were ink for [writing] the words of my Lord, the sea would be exhausted before the words of my Lord were exhausted, even if We brought the like of it as a supplement."'),
  ('en.sahih', 18, 110, 'Say, "I am only a man like you, to whom has been revealed that your god is one God. So whoever would hope for the meeting with his Lord - let him do righteous work and not associate in the worship of his Lord anyone."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 18, 1, 'সব প্রশংসা আল্লাহর যিনি নিজের বান্দার প্রতি এ গ্রন্থ নাযিল করেছেন এবং তাতে কোন বক্রতা রাখেননি।'),
  ('bn.bengali', 18, 2, 'একে সুপ্রতিষ্ঠিত করেছেন যা আল্লাহর পক্ষ থেকে একটি ভীষণ বিপদের ভয় প্রদর্শন করে এবং মুমিনদেরকে যারা সৎকর্ম সম্পাদন করে-তাদেরকে সুসংবাদ দান করে যে, তাদের জন্যে উত্তম প্রতিদান রয়েছে।'),
  ('bn.bengali', 18, 3, 'তারা তাতে চিরকাল অবস্থান করবে।'),
  ('bn.bengali', 18, 4, 'এবং তাদেরকে ভয় প্রদর্শন করার জন্যে যারা বলে যে, আল্লাহর সন্তান রয়েছে।'),
  ('bn.bengali', 18, 5, 'এ সম্পর্কে তাদের কোন জ্ঞান নেই এবং তাদের পিতৃপুরুষদেরও নেই। কত কঠিন তাদের মুখের কথা। তারা যা বলে তা তো সবই মিথ্যা।'),
  ('bn.bengali', 18, 6, 'যদি তারা এই বিষয়বস্তুর প্রতি বিশ্বাস স্থাপন না করে, তবে তাদের পশ্চাতে সম্ভবতঃ আপনি পরিতাপ করতে করতে নিজের প্রাণ নিপাত করবেন।'),
  ('bn.bengali', 18, 7, 'আমি পৃথিবীস্থ সব কিছুকে পৃথিবীর জন্যে শোভা করেছি, যাতে লোকদের পরীক্ষা করি যে, তাদের মধ্যে কে ভাল কাজ করে।'),
  ('bn.bengali', 18, 8, 'এবং তার উপর যাকিছু রয়েছে, অবশ্যই তা আমি উদ্ভিদশূন্য মাটিতে পরিণত করে দেব।'),
  ('bn.bengali', 18, 9, 'আপনি কি ধারণা করেন যে, গুহা ও গর্তের অধিবাসীরা আমার নিদর্শনাবলীর মধ্যে বিস্ময়কর ছিল ?'),
  ('bn.bengali', 18, 10, 'যখন যুবকরা পাহাড়ের গুহায় আশ্রয়গ্রহণ করে তখন দোআ করেঃ হে আমাদের পালনকর্তা, আমাদেরকে নিজের কাছ থেকে রহমত দান করুন এবং আমাদের জন্যে আমাদের কাজ সঠিকভাবে পূর্ণ করুন।'),
  ('bn.bengali', 18, 11, 'তখন আমি কয়েক বছরের জন্যে গুহায় তাদের কানের উপর নিদ্রার পর্দা ফেলে দেই।'),
  ('bn.bengali', 18, 12, 'অতঃপর আমি তাদেরকে পুনরত্থিত করি, একথা জানার জন্যে যে, দুই দলের মধ্যে কোন দল তাদের অবস্থানকাল সম্পর্কে অধিক নির্ণয় করতে পারে।'),
  ('bn.bengali', 18, 13, 'আপনার কাছে তাদের ইতিবৃত্তান্ত সঠিকভাবে বর্ণনা করছি। তারা ছিল কয়েকজন যুবক। তারা তাদের পালনকর্তার প্রতি বিশ্বাস স্থাপন করেছিল এবং আমি তাদের সৎপথে চলার শক্তি বাড়িয়ে দিয়েছিলাম।'),
  ('bn.bengali', 18, 14, 'আমি তাদের মন দৃঢ় করেছিলাম, যখন তারা উঠে দাঁড়িয়েছিল। অতঃপর তারা বললঃ আমাদের পালনকর্তা আসমান ও যমীনের পালনকর্তা আমরা কখনও তার পরিবর্তে অন্য কোন উপাস্যকে আহবান করব না। যদি করি, তবে তা অত্যন্ত গর্হিত কাজ হবে।'),
  ('bn.bengali', 18, 15, 'এরা আমাদেরই স্ব-জাতি, এরা তাঁর পরিবর্তে অনেক উপাস্য গ্রহণ করেছে। তারা এদের সম্পর্কে প্রকাশ্য প্রমাণ উপস্থিত করে না কেন? যে আল্লাহ সম্পর্কে মিথ্যা উদ্ভাবন করে, তার চাইতে অধিক গোনাহগার আর কে?'),
  ('bn.bengali', 18, 16, 'তোমরা যখন তাদের থেকে পৃথক হলে এবং তারা আল্লাহর পরিবর্তে যাদের এবাদত করে তাদের থেকে, তখন তোমরা গুহায় আশ্রয়গ্রহণ কর। তোমাদের পালনকর্তা তোমাদের জন্যে দয়া বিস্তার করবেন এবং তিনি তোমাদের জন্য তোমাদের কাজ কর্মকে ফলপ্রসু করার ব্যবস্থা করবেন।'),
  ('bn.bengali', 18, 17, 'তুমি সূর্যকে দেখবে, যখন উদিত হয়, তাদের গুহা থেকে পাশ কেটে ডান দিকে চলে যায় এবং যখন অস্ত যায়, তাদের থেকে পাশ কেটে বামদিকে চলে যায়, অথচ তারা গুহার প্রশস্ত চত্বরে অবস্থিত। এটা আল্লাহর নিদর্শনাবলীর অন্যতম। আল্লাহ যাকে সৎপথে চালান, সেই সৎপথ প্রাপ্ত এবং তিনি যাকে পথভ্রষ্ট করেন, আপনি কখনও তার জন্যে পথপ্রদর্শনকারী ও সাহায্যকারী পাবেন না।'),
  ('bn.bengali', 18, 18, 'তুমি মনে করবে তারা জাগ্রত, অথচ তারা নিদ্রিত। আমি তাদেরকে পার্শ্ব পরিবর্তন করাই ডান দিকে ও বাম দিকে। তাদের কুকুর ছিল সামনের পা দুটি গুহাদ্বারে প্রসারিত করে। যদি তুমি উঁকি দিয়ে তাদেরকে দেখতে, তবে পেছন ফিরে পলায়ন করতে এবং তাদের ভয়ে আতংক গ্রস্ত হয়ে পড়তে।'),
  ('bn.bengali', 18, 19, 'আমি এমনি ভাবে তাদেরকে জাগ্রত করলাম, যাতে তারা পরস্পর জিজ্ঞাসাবাদ করে। তাদের একজন বললঃ তোমরা কতকাল অবস্থান করেছ? তাদের কেউ বললঃ একদিন অথবা একদিনের কিছু অংশ অবস্থান করছি। কেউ কেউ বললঃ তোমাদের পালনকর্তাই ভাল জানেন তোমরা কতকাল অবস্থান করেছ। এখন তোমাদের একজনকে তোমাদের এই মুদ্রাসহ শহরে প্রেরণ কর; সে যেন দেখে কোন খাদ্য পবিত্র। অতঃপর তা থেকে যেন কিছু খাদ্য নিয়ে আসে তোমাদের জন্য; সে যেন নম্রতা সহকারে যায় ও কিছুতেই যেন তোমাদের খবর কাউকে না জানায়।'),
  ('bn.bengali', 18, 20, 'তারা যদি তোমাদের খবর জানতে পারে, তবে পাথর মেরে তোমাদেরকে হত্যা করবে, অথবা তোমাদেরকে তাদের ধর্মে ফিরিয়ে নেবে। তাহলে তোমরা কখনই সাফল্য লাভ করবে না।'),
  ('bn.bengali', 18, 21, 'এমনিভাবে আমি তাদের খবর প্রকাশ করে দিলাম, যাতে তারা জ্ঞাত হয় যে, আল্লাহর ওয়াদা সত্য এবং কেয়ামতে কোন সন্দেহ নেই। যখন তারা নিজেদের কর্তব্য বিষয়ে পরস্পর বিতর্ক করছিল, তখন তারা বললঃ তাদের উপর সৌধ নির্মাণ কর। তাদের পালনকর্তা তাদের বিষয়ে ভাল জানেন। তাদের কর্তব্য বিষয়ে যাদের মত প্রবল হল, তারা বললঃ আমরা অবশ্যই তাদের স্থানে মসজিদ নির্মান করব।'),
  ('bn.bengali', 18, 22, 'অজ্ঞাত বিষয়ে অনুমানের উপর ভিত্তি করে এখন তারা বলবেঃ তারা ছিল তিন জন; তাদের চতুর্থটি তাদের কুকুর। একথাও বলবে; তারা পাঁচ জন। তাদের ছষ্ঠটি ছিল তাদের কুকুর। আরও বলবেঃ তারা ছিল সাত জন। তাদের অষ্টমটি ছিল তাদের কুকুর। বলুনঃ আমার পালনকর্তা তাদের সংখ্যা ভাল জানেন। তাদের খবর অল্প লোকই জানে। সাধারণ আলোচনা ছাড়া আপনি তাদের সম্পর্কে বিতর্ক করবেন না এবং তাদের অবস্থা সম্পর্কে তাদের কাউকে জিজ্ঞাসাবাদ ও করবেন না।'),
  ('bn.bengali', 18, 23, 'আপনি কোন কাজের বিষয়ে বলবেন না যে, সেটি আমি আগামী কাল করব।'),
  ('bn.bengali', 18, 24, '‘আল্লাহ ইচ্ছা করলে’ বলা ব্যতিরেকে। যখন ভুলে যান, তখন আপনার পালনকর্তাকে স্মরণ করুন এবং বলুনঃ আশা করি আমার পালনকর্তা আমাকে এর চাইতেও নিকটতম সত্যের পথ নির্দেশ করবেন।'),
  ('bn.bengali', 18, 25, 'তাদের উপর তাদের গুহায় তিনশ বছর, অতিরিক্ত আরও নয় বছর অতিবাহিত হয়েছে।'),
  ('bn.bengali', 18, 26, 'বলুনঃ তারা কতকাল অবস্থান করেছে, তা আল্লাহই ভাল জানেন। নভোমন্ডল ও ভুমন্ডলের অদৃশ্য বিষয়ের জ্ঞান তাঁরই কাছে রয়েছে। তিনি কত চমৎকার দেখেন ও শোনেন। তিনি ব্যতীত তাদের জন্য কোন সাহায্যকারী নেই। তিনি কাউকে নিজ কর্তৃত্বে শরীক করেন না।'),
  ('bn.bengali', 18, 27, 'আপনার প্রতি আপনার পালনকর্তার যে, কিতাব প্রত্যাদিষ্ট করা হয়েছে, তা পাঠ করুন। তাঁর বাক্য পরিবর্তন করার কেউ নাই। তাঁকে ব্যতীত আপনি কখনই কোন আশ্রয় স্থল পাবেন না।'),
  ('bn.bengali', 18, 28, 'আপনি নিজেকে তাদের সংসর্গে আবদ্ধ রাখুন যারা সকাল ও সন্ধ্যায় তাদের পালনকর্তাকে তাঁর সন্তুষ্টি অর্জনের উদ্দেশ্যে আহবান করে এবং আপনি পার্থিব জীবনের সৌন্দর্য কামনা করে তাদের থেকে নিজের দৃষ্টি ফিরিয়ে নেবেন না। যার মনকে আমার স্মরণ থেকে গাফেল করে দিয়েছি, যে, নিজের প্রবৃত্তির অনুসরণ করে এবং যার কার্য কলাপ হচ্ছে সীমা অতিক্রম করা, আপনি তার অনুগত্য করবেন না।'),
  ('bn.bengali', 18, 29, 'বলুনঃ সত্য তোমাদের পালনকর্তার পক্ষ থেকে আগত। অতএব, যার ইচ্ছা, বিশ্বাস স্থাপন করুক এবং যার ইচ্ছা অমান্য করুক। আমি জালেমদের জন্যে অগ্নি প্রস্তুত করে রেখেছি, যার বেষ্টনী তাদের কে পরিবেষ্টন করে থাকবে। যদি তারা পানীয় প্রার্থনা করে, তবে পুঁজের ন্যায় পানীয় দেয়া হবে যা তাদের মুখমন্ডল দগ্ধ করবে। কত নিকৃষ্ট পানীয় এবং খুবই মন্দ আশ্রয়।'),
  ('bn.bengali', 18, 30, 'যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে আমি সৎকর্মশীলদের পুরস্কার নষ্ট করি না।'),
  ('bn.bengali', 18, 31, 'তাদেরই জন্যে আছে বসবাসের জান্নাত। তাদের পাদদেশে প্রবাহিত হয় নহরসমূহ। তাদের তথায় স্বর্ণ-কংকনে অলংকৃত করা হবে এবং তারা পাতলা ও মোটা রেশমের সবুজ কাপর পরিধান করবে এমতাবস্থায় যে, তারা সিংহাসনে সমাসীন হবে। চমৎকার প্রতিদান এবং কত উত্তম আশ্রয়।'),
  ('bn.bengali', 18, 32, 'আপনি তাদের কাছে দু ব্যক্তির উদাহরণ বর্ণনা করুন। আমি তাদের একজনকে দুটি আঙ্গুরের বাগান দিয়েছি এবং এ দু’টিকে খর্জুর বৃক্ষ দ্বারা পরিবেষ্টিত করেছি এবং দু এর মাঝখানে করেছি শস্যক্ষেত্র।'),
  ('bn.bengali', 18, 33, 'উভয় বাগানই ফলদান করে এবং তা থেকে কিছুই হ্রাস করত না এবং উভয়ের ফাঁকে ফাঁকে আমি নহর প্রবাহিত করেছি।'),
  ('bn.bengali', 18, 34, 'সে ফল পেল। অতঃপর কথা প্রসঙ্গে সঙ্গীকে বললঃ আমার ধন-সম্পদ তোমার চাইতে বেশী এবং জনবলে আমি অধিক শক্তিশালী।'),
  ('bn.bengali', 18, 35, 'নিজের প্রতি জুলুম করে সে তার বাগানে প্রবেশ করল। সে বললঃ আমার মনে হয় না যে, এ বাগান কখনও ধ্বংস হয়ে যাবে।'),
  ('bn.bengali', 18, 36, 'এবং আমি মনে করি না যে, কেয়ামত অনুষ্ঠিত হবে। যদি কখনও আমার পালনকর্তার কাছে আমাকে পৌঁছে দেয়া হয়, তবে সেখানে এর চাইতে উৎকৃষ্ট পাব।'),
  ('bn.bengali', 18, 37, 'তার সঙ্গী তাকে কথা প্রসঙ্গে বললঃ তুমি তাঁকে অস্বীকার করছ, যিনি তোমাকে সৃষ্টি করেছেন মাটি থেকে, অতঃপর বীর্য থেকে, অতঃপর র্পূনাঙ্গ করেছেন তোমাকে মানবাকৃতিতে?'),
  ('bn.bengali', 18, 38, 'কিন্তু আমি তো একথাই বলি, আল্লাহই আমার পালনকর্তা এবং আমি কাউকে আমার পালনকর্তার শরীক মানি না।'),
  ('bn.bengali', 18, 39, 'যদি তুমি আমাকে ধনে ও সন্তানে তোমার চাইতে কম দেখ, তবে যখন তুমি তোমার বাগানে প্রবেশ করলে, তখন একথা কেন বললে না; আল্লাহ যা চান, তাই হয়। আল্লাহর দেয়া ব্যতীত কোন শক্তি নেই।'),
  ('bn.bengali', 18, 40, 'আশাকরি আমার পালকর্তা আমাকে তোমার বাগান অপেক্ষা উৎকৃষ্টতর কিছু দেবেন এবং তার (তোমার বাগানের) উপর আসমান থেকে আগুন প্রেরণ করবেন। অতঃপর সকাল বেলায় তা পরিষ্কার ময়দান হয়ে যাবে।'),
  ('bn.bengali', 18, 41, 'অথবা সকালে তার পানি শুকিয়ে যাবে। অতঃপর তুমি তা তালাশ করে আনতে পারবে না।'),
  ('bn.bengali', 18, 42, 'অতঃপর তার সব ফল ধ্বংস হয়ে গেল এবং সে তাতে যা ব্যয় করেছিল, তার জন্য সকালে হাত কচলিয়ে আক্ষেপ করতে লাগল। বাগনটি কাঠসহ পুড়ে গিয়েছিল। সে বলতে লাগলঃ হায়, আমি যদি কাউকে আমার পালনকর্তার সাথে শরীক না করতাম।'),
  ('bn.bengali', 18, 43, 'আল্লাহ ব্যতীত তাকে সাহায্য করার কোন লোক হল না এবং সে নিজেও প্রতিকার করতে পারল না।'),
  ('bn.bengali', 18, 44, 'এরূপ ক্ষেত্রে সব অধিকার সত্য আল্লাহর। তারই পুরস্কার উত্তম এবং তারই প্রদত্ত প্রতিদান শ্রেষ্ঠ।'),
  ('bn.bengali', 18, 45, 'তাদের কাছে পার্থিব জীবনের উপমা বর্ণনা করুন। তা পানির ন্যায়, যা আমি আকাশ থেকে নাযিল করি। অতঃপর এর সংমিশ্রণে শ্যামল সবুজ ভূমিজ লতা-পাতা নির্গত হয়; অতঃপর তা এমন শুস্ক চুর্ণ-বিচুর্ণ হয় যে, বাতাসে উড়ে যায়। আল্লাহ এ সবকিছুর উপর শক্তিমান।'),
  ('bn.bengali', 18, 46, 'ধনৈশ্বর্য ও সন্তান-সন্ততি পার্থিব জীবনের সৌন্দর্য এবং স্থায়ী সৎকর্মসমূহ আপনার পালনকর্তার কাছে প্রতিদান প্রাপ্তি ও আশা লাভের জন্যে উত্তম।'),
  ('bn.bengali', 18, 47, 'যেদিন আমি পর্বতসমূহকে পরিচালনা করব এবং আপনি পৃথিবীকে দেখবেন একটি উম্মুক্ত প্রান্তর এবং আমি মানুষকে একত্রিত করব অতঃপর তাদের কাউকে ছাড়ব না।'),
  ('bn.bengali', 18, 48, 'তারা আপনার পালনকর্তার সামনে পেশ হবে সারিবদ্ধ ভাবে এবং বলা হবেঃ তোমরা আমার কাছে এসে গেছ; যেমন তোমাদেরকে প্রথম বার সৃষ্টি করেছিলাম। না, তোমরা তো বলতে যে, আমি তোমাদের জন্যে কোন প্রতিশ্রুত সময় নির্দিষ্ট করব না।'),
  ('bn.bengali', 18, 49, 'আর আমলনামা সামনে রাখা হবে। তাতে যা আছে; তার কারণে আপনি অপরাধীদেরকে ভীত-সন্ত্রস্ত দেখবেন। তারা বলবেঃ হায় আফসোস, এ কেমন আমলনামা। এ যে ছোট বড় কোন কিছুই বাদ দেয়নি-সবই এতে রয়েছে। তারা তাদের কৃতকর্মকে সামনে উপস্থিত পাবে। আপনার পালনকর্তা কারও প্রতি জুলুম করবেন না।'),
  ('bn.bengali', 18, 50, 'যখন আমি ফেরেশতাদেরকে বললামঃ আদমকে সেজদা কর, তখন সবাই সেজদা করল ইবলীস ব্যতীত। সে ছিল জিনদের একজন। সে তার পালনকর্তার আদেশ অমান্য করল। অতএব তোমরা কি আমার পরিবর্তে তাকে এবং তার বংশধরকে বন্ধুরূপে গ্রহণ করছ? অথচ তারা তোমাদের শত্রু। এটা জালেমদের জন্যে খুবই নিকৃষ্ট বদল।'),
  ('bn.bengali', 18, 51, 'নভোমন্ডল ও ভুমন্ডলের সৃজনকালে আমি তাদেরকে সাক্ষ্য রাখিনি এবং তাদের নিজেদের সৃজনকালেও না। এবং আমি এমনও নই যে, বিভ্রান্ত কারীদেরকে সাহায্যকারীরূপে গ্রহণ করবো।'),
  ('bn.bengali', 18, 52, 'যেদিন তিনি বলবেনঃ তোমরা যাদেরকে আমার শরীক মনে করতে তাদেরকে ডাক। তারা তখন তাদেরকে ডাকবে, কিন্তু তারা এ আহবানে সাড়া দেবে না। আমি তাদের মধ্যস্থলে রেখে দেব একটি মৃত্যু গহবর।'),
  ('bn.bengali', 18, 53, 'অপরাধীরা আগুন দেখে বোঝে নেবে যে, তাদেরকে তাতে পতিত হতে হবে এবং তারা তা থেকে রাস্তা পরিবর্তন করতে পারবে না।'),
  ('bn.bengali', 18, 54, 'নিশ্চয় আমি এ কোরআনে মানুষকে নানাভাবে বিভিন্ন উপমার দ্বারা আমার বাণী বুঝিয়েছি। মানুষ সব বস্তু থেকে অধিক তর্কপ্রিয়।'),
  ('bn.bengali', 18, 55, 'হেদায়েত আসার পর এ প্রতীক্ষাই শুধু মানুষকে বিশ্বাস স্থাপন করতে এবং তাদের পালনকর্তার কাছে ক্ষমা প্রার্থনা করতে বিরত রাখে যে, কখন আসবে তাদের কাছে পূর্ববর্তীদের রীতিনীতি অথবা কখন আসবে তাদের কাছেআযাব সামনাসামনি।'),
  ('bn.bengali', 18, 56, 'আমি রাসূলগনকে সুসংবাদ দাতা ও ভয় প্রদর্শন কারীরূপেই প্রেরণ করি এবং কাফেররাই মিথ্যা অবলম্বনে বিতর্ক করে, তা দ্বারা সত্যকে ব্যর্থ করে দেয়ার উদ্দেশে এবং তারা আমার নিদর্শনাবলীও যদ্বারা তাদেরকে ভয় প্রদর্শন করা হয়, সেগুলোকে ঠাট্টারূপে গ্রহণ করেছে।'),
  ('bn.bengali', 18, 57, 'তার চাইতে অধিক জালেম কে, যাকে তার পালনকর্তার কালাম দ্বারা বোঝানো হয়, অতঃপর সে তা থেকে মুখ ফিরিয়ে নেয় এবং তার পূর্ববর্তী কৃতকর্মসমূহ ভুলে যায়? আমি তাদের অন্তরের উপর পর্দা রেখে দিয়েছি, যেন তা না বোঝে এবং তাদের কানে রয়েছে বধিরতার বোঝা। যদি আপনি তাদেরকে সৎপথের প্রতি দাওয়াত দেন, তবে কখনই তারা সৎপথে আসবে না।'),
  ('bn.bengali', 18, 58, 'আপনার পালনকর্তা ক্ষমাশীল, দয়ালু, যদি তিনি তাদেরকে তাদের কৃতকর্মের জন্যে পাকড়াও করেন তবে তাদের শাস্তি ত্বরাম্বিত করতেন, কিন্তু তাদের জন্য রয়েছে একটি প্রতিশ্রুত সময়, যা থেকে তারা সরে যাওয়ার জায়গা পাবে না।'),
  ('bn.bengali', 18, 59, 'এসব জনপদও তাদেরকে আমি ধংস করে দিয়েছি, যখন তারা জালেম হয়ে গিয়েছিল এবং আমি তাদের ধ্বংসের জন্যে একটি প্রতিশ্রুত সময় নির্দিষ্ট করেছিলাম।'),
  ('bn.bengali', 18, 60, 'যখন মূসা তাঁর যুবক (সঙ্গী) কে বললেনঃ দুই সমুদ্রের সঙ্গমস্থলে না পৌছা পর্যন্ত আমি আসব না অথবা আমি যুগ যুগ ধরে চলতে থাকব।'),
  ('bn.bengali', 18, 61, 'অতঃপর যখন তাঁরা দুই সুমুদ্রের সঙ্গমস্থলে পৌছালেন, তখন তাঁরা নিজেদের মাছের কথা ভুলে গেলেন। অতঃপর মাছটি সমুদ্রে সুড়ঙ্গ পথ সৃষ্টি করে নেমে গেল।'),
  ('bn.bengali', 18, 62, 'যখন তাঁরা সে স্থানটি অতিক্রম করে গেলেন, মূসা সঙ্গী কে বললেনঃ আমাদের নাশতা আন। আমরা এই সফরে পরিশ্রান্ত হয়ে পড়েছি।'),
  ('bn.bengali', 18, 63, 'সে বললঃ আপনি কি লক্ষ্য করেছেন, আমরা যখন প্রস্তর খন্ডে আশ্রয় নিয়েছিলাম, তখন আমি মাছের কথা ভুলে গিয়েছিলাম। শয়তানই আমাকে একথা স্মরণ রাখতে ভুলিয়ে দিয়েছিল। মাছটি আশ্চর্য জনক ভাবে সমুদ্রে নিজের পথ করে নিয়েছে।'),
  ('bn.bengali', 18, 64, 'মূসা বললেনঃ আমরা তো এ স্থানটিই খুঁজছিলাম। অতঃপর তাঁরা নিজেদের চিহ্ন ধরে ফিরে চললেন।'),
  ('bn.bengali', 18, 65, 'অতঃপর তাঁরা আমার বান্দাদের মধ্যে এমন একজনের সাক্ষাত পেলেন, যাকে আমি আমার পক্ষ থেকে রহমত দান করেছিলাম ও আমার পক্ষ থেকে দিয়েছিলাম এক বিশেষ জ্ঞান।'),
  ('bn.bengali', 18, 66, 'মূসা তাঁকে বললেনঃ আমি কি এ শর্তে আপনার অনুসরণ করতে পারি যে, সত্যপথের যে জ্ঞান আপনাকে শেখানো হয়েছে, তা থেকে আমাকে কিছু শিক্ষা দেবেন?'),
  ('bn.bengali', 18, 67, 'তিনি বললেনঃ আপনি আমার সাথে কিছুতেই ধৈর্য্যধারণ করে থাকতে পারবেন না।'),
  ('bn.bengali', 18, 68, 'যে বিষয় বোঝা আপনার আয়ত্তাধীন নয়, তা দেখে আপনি ধৈর্য্যধারণ করবেন কেমন করে?'),
  ('bn.bengali', 18, 69, 'মূসা বললেনঃ আল্লাহ চাহেন তো আপনি আমাকে ধৈর্য্যশীল পাবেন এবং আমি আপনার কোন আদেশ অমান্য করব না।'),
  ('bn.bengali', 18, 70, 'তিনি বললেনঃ যদি আপনি আমার অনুসরণ করেনই তবে কোন বিষয়ে আমাকে প্রশ্ন করবেন না, যে পর্যন্ত না আমি নিজেই সে সম্পর্কে আপনাকে কিছু বলি।'),
  ('bn.bengali', 18, 71, 'অতঃপর তারা চলতে লাগলঃ অবশেষে যখন তারা নৌকায় আরোহণ করল, তখন তিনি তাতে ছিদ্র করে দিলেন। মূসা বললেনঃ আপনি কি এর আরোহীদেরকে ডুবিয়ে দেয়ার জন্যে এতে ছিদ্র করে দিলেন? নিশ্চয়ই আপনি একটি গুরুতর মন্দ কাজ করলেন।'),
  ('bn.bengali', 18, 72, 'তিনি বললেনঃ আমি কি বলিনি যে, আপনি আমার সাথে কিছুতেই ধৈর্য্য ধরতে পারবেন না ?'),
  ('bn.bengali', 18, 73, 'মূসা বললেনঃ আমাকে আমার ভুলের জন্যে অপরাধী করবেন না এবং আমার কাজে আমার উপর কঠোরতা আরোপ করবেন না।'),
  ('bn.bengali', 18, 74, 'অতঃপর তারা চলতে লাগল। অবশেষে যখন একটি বালকের সাক্ষাত পেলেন, তখন তিনি তাকে হত্যা করলেন। মূসা বললেন? আপনি কি একটি নিস্পাপ জীবন শেষ করে দিলেন প্রাণের বিনিময় ছাড়াই? নিশ্চয়ই আপনি তো এক গুরুতর অন্যায় কাজ করলেন।'),
  ('bn.bengali', 18, 75, 'তিনি বললেনঃ আমি কি বলিনি যে, আপনি আমার সাথে ধৈর্য্য ধরে থাকতে পারবেন না।'),
  ('bn.bengali', 18, 76, 'মূসা বললেনঃ এরপর যদি আমি আপনাকে কোন বিষয়ে প্রশ্ন করি, তবে আপনি আমাকে সাথে রাখবেন না। আপনি আমার পক্ষ থেকে অভিযোগ মুক্ত হয়ে গেছেন।'),
  ('bn.bengali', 18, 77, 'অতঃপর তারা চলতে লাগল, অবশেষে যখন একটি জনপদের অধিবাসীদের কাছে পৌছে তাদের কাছে খাবার চাইল, তখন তারা তাদের অতিথেয়তা করতে অস্বীকার করল। অতঃপর তারা সেখানে একটি পতনোম্মুখ প্রাচীর দেখতে পেলেন, সেটি তিনি সোজা করে দাঁড় করিয়ে দিলেন। মূসা বললেনঃ আপনি ইচ্ছা করলে তাদের কাছ থেকে এর পারিশ্রমিক আদায় করতে পারতেন।'),
  ('bn.bengali', 18, 78, 'তিনি বললেনঃ এখানেই আমার ও আপনার মধ্যে সম্পর্কচ্ছেদ হল। এখন যে বিষয়ে আপনি ধৈর্য্য ধরতে পারেননি, আমি তার তাৎপর্য বলে দিচ্ছি।'),
  ('bn.bengali', 18, 79, 'নৌকাটির ব্যাপারে-সেটি ছিল কয়েকজন দরিদ্র ব্যক্তির। তারা সমুদ্রে জীবিকা অন্বেষন করত। আমি ইচ্ছা করলাম যে, সেটিকে ক্রটিযুক্ত করে দেই। তাদের অপরদিকে ছিল এক বাদশাহ। সে বলপ্রয়োগে প্রত্যেকটি নৌকা ছিনিয়ে নিত।'),
  ('bn.bengali', 18, 80, 'বালকটির ব্যাপার তার পিতা-মাতা ছিল ঈমানদার। আমি আশঙ্কা করলাম যে, সে অবাধ্যতা ও কুফর দ্বারা তাদেরকে প্রভাবিত করবে।'),
  ('bn.bengali', 18, 81, 'অতঃপর আমি ইচ্ছা করলাম যে, তাদের পালনকর্তা তাদেরকে মহত্তর, তার চাইতে পবিত্রতায় ও ভালবাসায় ঘনিষ্ঠতর একটি শ্রেষ্ঠ সন্তান দান করুক।'),
  ('bn.bengali', 18, 82, 'প্রাচীরের ব্যাপার-সেটি ছিল নগরের দুজন পিতৃহীন বালকের। এর নীচে ছিল তাদের গুপ্তধন এবং তাদের পিতা ছিল সৎকর্ম পরায়ন। সুতরাং আপনার পালনকর্তা দায়বশতঃ ইচ্ছা করলেন যে, তারা যৌবনে পদার্পন করুক এবং নিজেদের গুপ্তধন উদ্ধার করুক। আমি নিজ মতে এটা করিনি। আপনি যে বিষয়ে ধৈর্য্যধারণ করতে অক্ষম হয়েছিলেন, এই হল তার ব্যাখ্যা।'),
  ('bn.bengali', 18, 83, 'তারা আপনাকে যুলকারনাইন সম্পর্কে জিজ্ঞাসা করে। বলুনঃ আমি তোমাদের কাছে তাঁর কিছু অবস্থা বর্ণনা করব।'),
  ('bn.bengali', 18, 84, 'আমি তাকে পৃথিবীতে প্রতিষ্ঠিত করেছিলাম এবং প্রত্যেক বিষয়ের কার্যোপকরণ দান করেছিলাম।'),
  ('bn.bengali', 18, 85, 'অতঃপর তিনি এক কার্যোপকরণ অবলম্বন করলেন।'),
  ('bn.bengali', 18, 86, 'অবশেষে তিনি যখন সুর্যের অস্তাচলে পৌছলেন; তখন তিনি সুর্যকে এক পঙ্কিল জলাশয়ে অস্ত যেতে দেখলেন এবং তিনি সেখানে এক সম্প্রদায়কে দেখতে পেলেন। আমি বললাম, হে যুলকারনাইন! আপনি তাদেরকে শাস্তি দিতে পারেন অথবা তাদেরকে সদয়ভাবে গ্রহণ করতে পারেন।'),
  ('bn.bengali', 18, 87, 'তিনি বললেনঃ যে কেউ সীমালঙ্ঘনকারী হবে আমি তাকে শাস্তি দেব। অতঃপর তিনি তাঁর পালনকর্তার কাছে ফিরে যাবেন। তিনি তাকে কঠোর শাস্তি দেবেন।'),
  ('bn.bengali', 18, 88, 'এবং যে বিশ্বাস স্থাপন করে ও সৎকর্ম করে তার জন্য প্রতিদান রয়েছে কল্যাণ এবং আমার কাজে তাকে সহজ নির্দেশ দেব।'),
  ('bn.bengali', 18, 89, 'অতঃপর তিনি এক উপায় অবলম্বন করলেন।'),
  ('bn.bengali', 18, 90, 'অবশেষে তিনি যখন সূর্যের উদয়াচলে পৌছলেন, তখন তিনি তাকে এমন এক সম্প্রদায়ের উপর উদয় হতে দেখলেন, যাদের জন্যে সূর্যতাপ থেকে আত্নরক্ষার কোন আড়াল আমি সৃষ্টি করিনি।'),
  ('bn.bengali', 18, 91, 'প্রকৃত ঘটনা এমনিই। তার বৃত্তান্ত আমি সম্যক অবগত আছি।'),
  ('bn.bengali', 18, 92, 'আবার তিনি এক পথ ধরলেন।'),
  ('bn.bengali', 18, 93, 'অবশেষে যখন তিনি দুই পর্বত প্রচীরের মধ্যস্থলে পৌছলেন, তখন তিনি সেখানে এক জাতিকে পেলেন, যারা তাঁর কথা একেবারেই বুঝতে পারছিল না।'),
  ('bn.bengali', 18, 94, 'তারা বললঃ হে যুলকারনাইন, ইয়াজুজ ও মাজুজ দেশে অশান্তি সৃষ্টি করেছে। আপনি বললে আমরা আপনার জন্যে কিছু কর ধার্য করব এই শর্তে যে, আপনি আমাদের ও তাদের মধ্যে একটি প্রাচীর নির্মাণ করে দেবেন।'),
  ('bn.bengali', 18, 95, 'তিনি বললেনঃ আমার পালনকর্তা আমাকে যে সামর্থ?2470;িয়েছেন, তাই যথেষ্ট। অতএব, তোমরা আমাকে শ্রম দিয়ে সাহায্য কর। আমি তোমাদের ও তাদের মধ্যে একটি সুদৃঢ় প্রাচীর নির্মাণ করে দেব।'),
  ('bn.bengali', 18, 96, 'তোমরা আমাকে লোহার পাত এনে দাও। অবশেষে যখন পাহাড়ের মধ্যবর্তী ফাঁকা স্থান পূর্ণ হয়ে গেল, তখন তিনি বললেনঃ তোমরা হাঁপরে দম দিতে থাক। অবশেষে যখন তা আগুনে পরিণত হল, তখন তিনি বললেনঃ তোমরা গলিত তামা নিয়ে এস, আমি তা এর উপরে ঢেলে দেই।'),
  ('bn.bengali', 18, 97, 'অতঃপর ইয়াজুজ ও মাজুজ তার উপরে আরোহণ করতে পারল না এবং তা ভেদ করতে ও সক্ষম হল না।'),
  ('bn.bengali', 18, 98, 'যুলকারনাইন বললেনঃ এটা আমার পালনকর্তার অনুগ্রহ। যখন আমার পালনকর্তার প্রতিশ্রুত সময় আসবে, তখন তিনি একে চূর্ণ-বিচূর্ণ করে দেবেন এবং আমার পালনকর্তার প্রতিশ্রুতি সত্য।'),
  ('bn.bengali', 18, 99, 'আমি সেদিন তাদেরকে দলে দলে তরঙ্গের আকারে ছেড়ে দেব এবং শিঙ্গায় ফুঁৎকার দেয়া হবে। অতঃপর আমি তাদের সবাইকে একত্রিত করে আনব।'),
  ('bn.bengali', 18, 100, 'সেদিন আমি কাফেরদের কাছে জাহান্নামকে প্রত্যক্ষ ভাবে উপস্থিত করব।'),
  ('bn.bengali', 18, 101, 'যাদের চক্ষুসমূহের উপর পর্দা ছিল আমার স্মরণ থেকে এবং যারা শুনতেও সক্ষম ছিল না।'),
  ('bn.bengali', 18, 102, 'কাফেররা কি মনে করে যে, তারা আমার পরিবর্তে আমার বান্দাদেরকে অভিভাবক রূপে গ্রহণ করবে? আমি কাফেরদের অভ্যর্থনার জন্যে জাহান্নামকে প্রস্তুত করে রেখেছি।'),
  ('bn.bengali', 18, 103, 'বলুনঃ আমি কি তোমাদেরকে সেসব লোকের সংবাদ দেব, যারা কর্মের দিক দিয়ে খুবই ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 18, 104, 'তারাই সে লোক, যাদের প্রচেষ্টা পার্থিবজীবনে বিভ্রান্ত হয়, অথচ তারা মনে করে যে, তারা সৎকর্ম করেছে।'),
  ('bn.bengali', 18, 105, 'তারাই সে লোক, যারা তাদের পালনকর্তার নিদর্শনাবলী এবং তাঁর সাথে সাক্ষাতের বিষয় অস্বীকার করে। ফলে তাদের কর্ম নিষ্ফল হয়ে যায়। সুতরাং কেয়ামতের দিন তাদের জন্য আমি কোন গুরুত্ব স্থির করব না।'),
  ('bn.bengali', 18, 106, 'জাহান্নাম-এটাই তাদের প্রতিফল; কারণ, তারা কাফের হয়েছে এবং আমার নিদর্শনাবলী ও রসূলগণকে বিদ্রূপের বিষয় রূপে গ্রহণ করেছে।'),
  ('bn.bengali', 18, 107, 'যারা বিশ্বাস স্থাপন করে ও সৎকর্ম সম্পাদন করে, তাদের অভ্যর্থনার জন্যে আছে জান্নাতুল ফেরদাউস।'),
  ('bn.bengali', 18, 108, 'সেখানে তারা চিরকাল থাকবে, সেখান থেকে স্থান পরিবর্তন করতে চাইবে না।'),
  ('bn.bengali', 18, 109, 'বলুনঃ আমার পালনকর্তার কথা, লেখার জন্যে যদি সমুদ্রের পানি কালি হয়, তবে আমার পালনকর্তার কথা, শেষ হওয়ার আগেই সে সমুদ্র নিঃশেষিত হয়ে যাবে। সাহায্যার্থে অনুরূপ আরেকটি সমুদ্র এনে দিলেও।'),
  ('bn.bengali', 18, 110, 'বলুনঃ আমি ও তোমাদের মতই একজন মানুষ, আমার প্রতি প্রত্যাদেশ হয় যে, তোমাদের ইলাহই একমাত্র ইলাহ। অতএব, যে ব্যক্তি তার পালনকর্তার সাক্ষাত কামনা করে, সে যেন, সৎকর্ম সম্পাদন করে এবং তার পালনকর্তার এবাদতে কাউকে শরীক না করে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 18, 1, 'Praise be to Allah Who hath revealed the Scripture unto His slave, and hath not placed therein any crookedness,'),
  ('en.pickthall', 18, 2, '(But hath made it) straight, to give warning of stern punishment from Him, and to bring unto the believers who do good works the news that theirs will be a fair reward,'),
  ('en.pickthall', 18, 3, 'Wherein they will abide for ever;'),
  ('en.pickthall', 18, 4, 'And to warn those who say: Allah hath chosen a son,'),
  ('en.pickthall', 18, 5, '(A thing) whereof they have no knowledge, nor (had) their fathers, Dreadful is the word that cometh out of their mouths. They speak naught but a lie.'),
  ('en.pickthall', 18, 6, 'Yet it may be, if they believe not in this statement, that thou (Muhammad) wilt torment thy soul with grief over their footsteps.'),
  ('en.pickthall', 18, 7, 'Lo! We have placed all that is on the earth as an ornament thereof that We may try them: which of them is best in conduct.'),
  ('en.pickthall', 18, 8, 'And lo! We shall make all that is thereon a barren mound.'),
  ('en.pickthall', 18, 9, 'Or deemest thou that the People of the Cave and the Inscription are a wonder among Our portents?'),
  ('en.pickthall', 18, 10, 'When the young men fled for refuge to the Cave and said: Our Lord! Give us mercy from Thy presence, and shape for us right conduct in our plight.'),
  ('en.pickthall', 18, 11, 'Then We sealed up their hearing in the Cave for a number of years.'),
  ('en.pickthall', 18, 12, 'And afterward We raised them up that We might know which of the two parties would best calculate the time that they had tarried.'),
  ('en.pickthall', 18, 13, 'We narrate unto thee their story with truth. Lo! they were young men who believed in their Lord, and We increased them in guidance.'),
  ('en.pickthall', 18, 14, 'And We made firm their hearts when they stood forth and said: Our Lord is the Lord of the heavens and the earth. We cry unto no Allah beside Him, for then should we utter an enormity.'),
  ('en.pickthall', 18, 15, 'These, our people, have chosen (other) gods beside Him though they bring no clear warrant (vouchsafed) to them. And who doth greater wrong than he who inventeth a lie concerning Allah?'),
  ('en.pickthall', 18, 16, 'And when ye withdraw from them and that which they worship except Allah, then seek refuge in the Cave; your Lord will spread for you of His mercy and will prepare for you a pillow in your plight.'),
  ('en.pickthall', 18, 17, 'And thou mightest have seen the sun when it rose move away from their cave to the right, and when it set go past them on the left, and they were in the cleft thereof. That was (one) of the portents of Allah. He whom Allah guideth, he indeed is led aright, and he whom He sendeth astray, for him thou wilt not find a guiding friend.'),
  ('en.pickthall', 18, 18, 'And thou wouldst have deemed them waking though they were asleep, and We caused them to turn over to the right and the left, and their dog stretching out his paws on the threshold. If thou hadst observed them closely thou hadst assuredly turned away from them in flight, and hadst been filled with awe of them.'),
  ('en.pickthall', 18, 19, 'And in like manner We awakened them that they might question one another. A speaker from among them said: How long have ye tarried? They said: We have tarried a day or some part of a day, (Others) said: Your Lord best knoweth what ye have tarried. Now send one of you with this your silver coin unto the city, and let him see what food is purest there and bring you a supply thereof. Let him be courteous and let no man know of you.'),
  ('en.pickthall', 18, 20, 'For they, if they should come to know of you, will stone you or turn you back to their religion; then ye will never prosper.'),
  ('en.pickthall', 18, 21, 'And in like manner We disclosed them (to the people of the city) that they might know that the promise of Allah is true, and that, as for the Hour, there is no doubt concerning it. When (the people of the city) disputed of their case among themselves, they said: Build over them a building; their Lord knoweth best concerning them. Those who won their point said: We verily shall build a place of worship over them.'),
  ('en.pickthall', 18, 22, '(Some) will say: They were three, their dog the fourth, and (some) say: Five, their dog the sixth, guessing at random; and (some) say: Seven, and their dog the eighth. Say (O Muhammad): My Lord is Best Aware of their number. None knoweth them save a few. So contend not concerning them except with an outward contending, and ask not any of them to pronounce concerning them.'),
  ('en.pickthall', 18, 23, 'And say not of anything: Lo! I shall do that tomorrow,'),
  ('en.pickthall', 18, 24, 'Except if Allah will. And remember thy Lord when thou forgettest, and say: It may be that my Lord guideth me unto a nearer way of truth than this.'),
  ('en.pickthall', 18, 25, 'And (it is said) they tarried in their Cave three hundred years and add nine.'),
  ('en.pickthall', 18, 26, 'Say: Allah is Best Aware how long they tarried. His is the Invisible of the heavens and the earth. How clear of sight is He and keen of hearing! They have no protecting friend beside Him, and He maketh none to share in His government.'),
  ('en.pickthall', 18, 27, 'And recite that which hath been revealed unto thee of the Scripture of thy Lord. There is none who can change His words, and thou wilt find no refuge beside Him.'),
  ('en.pickthall', 18, 28, 'Restrain thyself along with those who cry unto their Lord at morn and evening, seeking His Countenance; and let not thine eyes overlook them, desiring the pomp of the life of the world; and obey not him whose heart We have made heedless of Our remembrance, who followeth his own lust and whose case hath been abandoned.'),
  ('en.pickthall', 18, 29, 'Say: (It is) the truth from the Lord of you (all). Then whosoever will, let him believe, and whosoever will, let him disbelieve. Lo! We have prepared for disbelievers Fire. Its tent encloseth them. If they ask for showers, they will be showered with water like to molten lead which burneth the faces. Calamitous the drink and ill the resting-place!'),
  ('en.pickthall', 18, 30, 'Lo! as for those who believe and do good works - Lo! We suffer not the reward of one whose work is goodly to be lost.'),
  ('en.pickthall', 18, 31, 'As for such, theirs will be Gardens of Eden, wherein rivers flow beneath them; therein they will be given armlets of gold and will wear green robes of finest silk and gold embroidery, reclining upon throne therein. Blest the reward, and fair the resting-place!'),
  ('en.pickthall', 18, 32, 'Coin for them a similitude: Two men, unto one of whom We had assigned two gardens of grapes, and We had surrounded both with date-palms and had put between them tillage.'),
  ('en.pickthall', 18, 33, 'Each of the gardens gave its fruit and withheld naught thereof. And We caused a river to gush forth therein.'),
  ('en.pickthall', 18, 34, 'And he had fruit. And he said unto his comrade, when he spake with him: I am more than thee in wealth, and stronger in respect of men.'),
  ('en.pickthall', 18, 35, 'And he went into his garden, while he (thus) wronged himself. He said: I think not that all this will ever perish.'),
  ('en.pickthall', 18, 36, 'I think not that the Hour will ever come, and if indeed I am brought back unto my Lord I surely shall find better than this as a resort.'),
  ('en.pickthall', 18, 37, 'His comrade, when he (thus) spake with him, exclaimed: Disbelievest thou in Him Who created thee of dust, then of a drop (of seed), and then fashioned thee a man?'),
  ('en.pickthall', 18, 38, 'But He is Allah, my Lord, and I ascribe unto my Lord no partner.'),
  ('en.pickthall', 18, 39, 'If only, when thou enteredst thy garden, thou hadst said: That which Allah willeth (will come to pass)! There is no strength save in Allah! Though thou seest me as less than thee in wealth and children,'),
  ('en.pickthall', 18, 40, 'Yet it may be that my Lord will give me better than thy garden, and will send on it a bolt from heaven, and some morning it will be a smooth hillside,'),
  ('en.pickthall', 18, 41, 'Or some morning the water thereof will be lost in the earth so that thou canst not make search for it.'),
  ('en.pickthall', 18, 42, 'And his fruit was beset (with destruction). Then began he to wring his hands for all that he had spent upon it, when (now) it was all ruined on its trellises, and to say: Would that I had ascribed no partner to my Lord!'),
  ('en.pickthall', 18, 43, 'And he had no troop of men to help him as against Allah, nor could he save himself.'),
  ('en.pickthall', 18, 44, 'In this case is protection only from Allah, the True, He is Best for reward, and best for consequence.'),
  ('en.pickthall', 18, 45, 'And coin for them the similitude of the life of the world as water which We send down from the sky, and the vegetation of the earth mingleth with it and then becometh dry twigs that the winds scatter. Allah is able to do all things.'),
  ('en.pickthall', 18, 46, 'Wealth and children are an ornament of the life of the world. But the good deeds which endure are better in thy Lord\'s sight for reward, and better in respect of hope.'),
  ('en.pickthall', 18, 47, 'And (bethink you of) the Day when we remove the hills and ye see the earth emerging, and We gather them together so as to leave not one of them behind.'),
  ('en.pickthall', 18, 48, 'And they are set before thy Lord in ranks (and it is said unto them): Now verily have ye come unto Us as We created you at the first. But ye thought that We had set no tryst for you.'),
  ('en.pickthall', 18, 49, 'And the Book is placed, and thou seest the guilty fearful of that which is therein, and they say: What kind of a Book is this that leaveth not a small thing nor a great thing but hath counted it! And they find all that they did confronting them, and thy Lord wrongeth no-one.'),
  ('en.pickthall', 18, 50, 'And (remember) when We said unto the angels: Fall prostrate before Adam, and they fell prostrate, all save Iblis. He was of the jinn, so he rebelled against his Lord\'s command. Will ye choose him and his seed for your protecting friends instead of Me, when they are an enemy unto you? Calamitous is the exchange for evil-doers.'),
  ('en.pickthall', 18, 51, 'I made them not to witness the creation of the heavens and the earth, nor their own creation; nor choose I misleaders for (My) helpers.'),
  ('en.pickthall', 18, 52, 'And (be mindful of) the Day when He will say: Call those partners of Mine whom ye pretended. Then they will cry unto them, but they will not hear their prayer, and We shall set a gulf of doom between them.'),
  ('en.pickthall', 18, 53, 'And the guilty behold the Fire and know that they are about to fall therein, and they find no way of escape thence.'),
  ('en.pickthall', 18, 54, 'And verily We have displayed for mankind in this Qur\'an all manner of similitudes, but man is more than anything contentious.'),
  ('en.pickthall', 18, 55, 'And naught hindereth mankind from believing when the guidance cometh unto them, and from asking forgiveness of their Lord unless (it be that they wish) that the judgment of the men of old should come upon them or (that) they should be confronted with the Doom.'),
  ('en.pickthall', 18, 56, 'We send not the messengers save as bearers of good news and warners. Those who disbelieve contend with falsehood in order to refute the Truth thereby. And they take Our revelations and that wherewith they are threatened as a jest.'),
  ('en.pickthall', 18, 57, 'And who doth greater wrong than he who hath been reminded of the revelations of his Lord, yet turneth away from them and forgetteth what his hands send forward (to the Judgment)? Lo! on their hearts We have placed coverings so that they understand not, and in their ears a deafness. And though thou call them to the guidance, in that case they can never be led aright.'),
  ('en.pickthall', 18, 58, 'Thy Lord is the Forgiver, Full of Mercy. If He took them to task (now) for what they earn, He would hasten on the doom for them; but theirs is an appointed term from which they will find no escape.'),
  ('en.pickthall', 18, 59, 'And (all) those townships! We destroyed them when they did wrong, and We appointed a fixed time for their destruction.'),
  ('en.pickthall', 18, 60, 'And when Moses said unto his servant: I will not give up until I reach the point where the two rivers meet, though I march on for ages.'),
  ('en.pickthall', 18, 61, 'And when they reached the point where the two met, they forgot their fish, and it took its way into the waters, being free.'),
  ('en.pickthall', 18, 62, 'And when they had gone further, he said unto his servant: Bring us our breakfast. Verily we have found fatigue in this our journey.'),
  ('en.pickthall', 18, 63, 'He said: Didst thou see, when we took refuge on the rock, and I forgot the fish - and none but Satan caused me to forget to mention it - it took its way into the waters by a marvel.'),
  ('en.pickthall', 18, 64, 'He said: This is that which we have been seeking. So they retraced their steps again.'),
  ('en.pickthall', 18, 65, 'Then found they one of Our slaves, unto whom We had given mercy from Us, and had taught him knowledge from Our presence.'),
  ('en.pickthall', 18, 66, 'Moses said unto him: May I follow thee, to the end that thou mayst teach me right conduct of that which thou hast been taught?'),
  ('en.pickthall', 18, 67, 'He said: Lo! thou canst not bear with me.'),
  ('en.pickthall', 18, 68, 'How canst thou bear with that whereof thou canst not compass any knowledge?'),
  ('en.pickthall', 18, 69, 'He said: Allah willing, thou shalt find me patient and I shall not in aught gainsay thee.'),
  ('en.pickthall', 18, 70, 'He said: Well, if thou go with me, ask me not concerning aught till I myself make mention of it unto thee.'),
  ('en.pickthall', 18, 71, 'So they twain set out till, when they were in the ship, he made a hole therein. (Moses) said: Hast thou made a hole therein to drown the folk thereof? Thou verily hast done a dreadful thing.'),
  ('en.pickthall', 18, 72, 'He said: Did I not tell thee that thou couldst not bear with me?'),
  ('en.pickthall', 18, 73, '(Moses) said: Be not wroth with me that I forgot, and be not hard upon me for my fault.'),
  ('en.pickthall', 18, 74, 'So they twain journeyed on till, when they met a lad, he slew him. (Moses) said: What! Hast thou slain an innocent soul who hath slain no man? Verily thou hast done a horrid thing.'),
  ('en.pickthall', 18, 75, 'He said: Did I not tell thee that thou couldst not bear with me?'),
  ('en.pickthall', 18, 76, '(Moses) said: If I ask thee after this concerning aught, keep not company with me. Thou hast received an excuse from me.'),
  ('en.pickthall', 18, 77, 'So they twain journeyed on till, when they came unto the folk of a certain township, they asked its folk for food, but they refused to make them guests. And they found therein a wall upon the point of falling into ruin, and he repaired it. (Moses) said: If thou hadst wished, thou couldst have taken payment for it.'),
  ('en.pickthall', 18, 78, 'He said: This is the parting between thee and me! I will announce unto thee the interpretation of that thou couldst not bear with patience.'),
  ('en.pickthall', 18, 79, 'As for the ship, it belonged to poor people working on the river, and I wished to mar it, for there was a king behind them who is taking every ship by force.'),
  ('en.pickthall', 18, 80, 'And as for the lad, his parents were believers and we feared lest he should oppress them by rebellion and disbelief.'),
  ('en.pickthall', 18, 81, 'And we intended that their Lord should change him for them for one better in purity and nearer to mercy.'),
  ('en.pickthall', 18, 82, 'And as for the wall, it belonged to two orphan boys in the city, and there was beneath it a treasure belonging to them, and their father had been righteous, and thy Lord intended that they should come to their full strength and should bring forth their treasure as a mercy from their Lord; and I did it not upon my own command. Such is the interpretation of that wherewith thou couldst not bear.'),
  ('en.pickthall', 18, 83, 'They will ask thee of Dhu\'l-Qarneyn. Say: I shall recite unto you a remembrance of him.'),
  ('en.pickthall', 18, 84, 'Lo! We made him strong in the land and gave him unto every thing a road.'),
  ('en.pickthall', 18, 85, 'And he followed a road'),
  ('en.pickthall', 18, 86, 'Till, when he reached the setting-place of the sun, he found it setting in a muddy spring, and found a people thereabout. We said: O Dhu\'l-Qarneyn! Either punish or show them kindness.'),
  ('en.pickthall', 18, 87, 'He said: As for him who doeth wrong, we shall punish him, and then he will be brought back unto his Lord, Who will punish him with awful punishment!'),
  ('en.pickthall', 18, 88, 'But as for him who believeth and doeth right, good will be his reward, and We shall speak unto him a mild command.'),
  ('en.pickthall', 18, 89, 'Then he followed a road'),
  ('en.pickthall', 18, 90, 'Till, when he reached the rising-place of the sun, he found it rising on a people for whom We had appointed no shelter therefrom.'),
  ('en.pickthall', 18, 91, 'So (it was). And We knew all concerning him.'),
  ('en.pickthall', 18, 92, 'Then he followed a road'),
  ('en.pickthall', 18, 93, 'Till, when he came between the two mountains, he found upon their hither side a folk that scarce could understand a saying.'),
  ('en.pickthall', 18, 94, 'They said: O Dhu\'l-Qarneyn! Lo! Gog and Magog are spoiling the land. So may we pay thee tribute on condition that thou set a barrier between us and them?'),
  ('en.pickthall', 18, 95, 'He said: That wherein my Lord hath established me is better (than your tribute). Do but help me with strength (of men), I will set between you and them a bank.'),
  ('en.pickthall', 18, 96, 'Give me pieces of iron - till, when he had levelled up (the gap) between the cliffs, he said: Blow! - till, when he had made it a fire, he said: Bring me molten copper to pour thereon.'),
  ('en.pickthall', 18, 97, 'And (Gog and Magog) were not able to surmount, nor could they pierce (it).'),
  ('en.pickthall', 18, 98, 'He said: This is a mercy from my Lord; but when the promise of my Lord cometh to pass, He will lay it low, for the promise of my Lord is true.'),
  ('en.pickthall', 18, 99, 'And on that day we shall let some of them surge against others, and the Trumpet will be blown. Then We shall gather them together in one gathering.'),
  ('en.pickthall', 18, 100, 'On that day we shall present hell to the disbelievers, plain to view,'),
  ('en.pickthall', 18, 101, 'Those whose eyes were hoodwinked from My reminder, and who could not bear to hear.'),
  ('en.pickthall', 18, 102, 'Do the disbelievers reckon that they can choose My bondmen as protecting friends beside Me? Lo! We have prepared hell as a welcome for the disbelievers.'),
  ('en.pickthall', 18, 103, 'Say: Shall We inform you who will be the greatest losers by their works?'),
  ('en.pickthall', 18, 104, 'Those whose effort goeth astray in the life of the world, and yet they reckon that they do good work.'),
  ('en.pickthall', 18, 105, 'Those are they who disbelieve in the revelations of their Lord and in the meeting with Him. Therefor their works are vain, and on the Day of Resurrection We assign no weight to them.'),
  ('en.pickthall', 18, 106, 'That is their reward: hell, because they disbelieved, and made a jest of Our revelations and Our messengers.'),
  ('en.pickthall', 18, 107, 'Lo! those who believe and do good works, theirs are the Gardens of Paradise for welcome,'),
  ('en.pickthall', 18, 108, 'Wherein they will abide, with no desire to be removed from thence.'),
  ('en.pickthall', 18, 109, 'Say: Though the sea became ink for the Words of my Lord, verily the sea would be used up before the words of my Lord were exhausted, even though We brought the like thereof to help.'),
  ('en.pickthall', 18, 110, 'Say: I am only a mortal like you. My Lord inspireth in me that your Allah is only One Allah. And whoever hopeth for the meeting with his Lord, let him do righteous work, and make none sharer of the worship due unto his Lord.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 18, 1, 'Praise be to Allah, Who hath sent to His Servant the Book, and hath allowed therein no Crookedness:'),
  ('en.yusufali', 18, 2, '(He hath made it) Straight (and Clear) in order that He may warn (the godless) of a terrible Punishment from Him, and that He may give Glad Tidings to the Believers who work righteous deeds, that they shall have a goodly Reward,'),
  ('en.yusufali', 18, 3, 'Wherein they shall remain for ever:'),
  ('en.yusufali', 18, 4, 'Further, that He may warn those (also) who say, "Allah hath begotten a son":'),
  ('en.yusufali', 18, 5, 'No knowledge have they of such a thing, nor had their fathers. It is a grievous thing that issues from their mouths as a saying what they say is nothing but falsehood!'),
  ('en.yusufali', 18, 6, 'Thou wouldst only, perchance, fret thyself to death, following after them, in grief, if they believe not in this Message.'),
  ('en.yusufali', 18, 7, 'That which is on earth we have made but as a glittering show for the earth, in order that We may test them - as to which of them are best in conduct.'),
  ('en.yusufali', 18, 8, 'Verily what is on earth we shall make but as dust and dry soil (without growth or herbage).'),
  ('en.yusufali', 18, 9, 'Or dost thou reflect that the Companions of the Cave and of the Inscription were wonders among Our Sign?'),
  ('en.yusufali', 18, 10, 'Behold, the youths betook themselves to the Cave: they said, "Our Lord! bestow on us Mercy from Thyself, and dispose of our affair for us in the right way!"'),
  ('en.yusufali', 18, 11, 'Then We draw (a veil) over their ears, for a number of years, in the Cave, (so that they heard not):'),
  ('en.yusufali', 18, 12, 'Then We roused them, in order to test which of the two parties was best at calculating the term of years they had tarried!'),
  ('en.yusufali', 18, 13, 'We relate to thee their story in truth: they were youths who believed in their Lord, and We advanced them in guidance:'),
  ('en.yusufali', 18, 14, 'We gave strength to their hearts: Behold, they stood up and said: "Our Lord is the Lord of the heavens and of the earth: never shall we call upon any god other than Him: if we did, we should indeed have uttered an enormity!'),
  ('en.yusufali', 18, 15, '"These our people have taken for worship gods other than Him: why do they not bring forward an authority clear (and convincing) for what they do? Who doth more wrong than such as invent a falsehood against Allah?'),
  ('en.yusufali', 18, 16, '"When ye turn away from them and the things they worship other than Allah, betake yourselves to the Cave: Your Lord will shower His mercies on you and disposes of your affair towards comfort and ease."'),
  ('en.yusufali', 18, 17, 'Thou wouldst have seen the sun, when it rose, declining to the right from their Cave, and when it set, turning away from them to the left, while they lay in the open space in the midst of the Cave. Such are among the Signs of Allah: He whom Allah, guides is rightly guided; but he whom Allah leaves to stray,- for him wilt thou find no protector to lead him to the Right Way.'),
  ('en.yusufali', 18, 18, 'Thou wouldst have deemed them awake, whilst they were asleep, and We turned them on their right and on their left sides: their dog stretching forth his two fore-legs on the threshold: if thou hadst come up on to them, thou wouldst have certainly turned back from them in flight, and wouldst certainly have been filled with terror of them.'),
  ('en.yusufali', 18, 19, 'Such (being their state), we raised them up (from sleep), that they might question each other. Said one of them, "How long have ye stayed (here)?" They said, "We have stayed (perhaps) a day, or part of a day." (At length) they (all) said, "Allah (alone) knows best how long ye have stayed here.... Now send ye then one of you with this money of yours to the town: let him find out which is the best food (to be had) and bring some to you, that (ye may) satisfy your hunger therewith: And let him behave with care and courtesy, and let him not inform any one about you.'),
  ('en.yusufali', 18, 20, '"For if they should come upon you, they would stone you or force you to return to their cult, and in that case ye would never attain prosperity."'),
  ('en.yusufali', 18, 21, 'Thus did We make their case known to the people, that they might know that the promise of Allah is true, and that there can be no doubt about the Hour of Judgment. Behold, they dispute among themselves as to their affair. (Some) said, "Construct a building over them": Their Lord knows best about them: those who prevailed over their affair said, "Let us surely build a place of worship over them."'),
  ('en.yusufali', 18, 22, '(Some) say they were three, the dog being the fourth among them; (others) say they were five, the dog being the sixth,- doubtfully guessing at the unknown; (yet others) say they were seven, the dog being the eighth. Say thou: "My Lord knoweth best their number; It is but few that know their (real case)." Enter not, therefore, into controversies concerning them, except on a matter that is clear, nor consult any of them about (the affair of) the Sleepers.'),
  ('en.yusufali', 18, 23, 'Nor say of anything, "I shall be sure to do so and so tomorrow"-'),
  ('en.yusufali', 18, 24, 'Without adding, "So please Allah!" and call thy Lord to mind when thou forgettest, and say, "I hope that my Lord will guide me ever closer (even) than this to the right road."'),
  ('en.yusufali', 18, 25, 'So they stayed in their Cave three hundred years, and (some) add nine (more)'),
  ('en.yusufali', 18, 26, 'Say: "Allah knows best how long they stayed: with Him is (the knowledge of) the secrets of the heavens and the earth: how clearly He sees, how finely He hears (everything)! They have no protector other than Him; nor does He share His Command with any person whatsoever.'),
  ('en.yusufali', 18, 27, 'And recite (and teach) what has been revealed to thee of the Book of thy Lord: none can change His Words, and none wilt thou find as a refuge other than Him.'),
  ('en.yusufali', 18, 28, 'And keep thy soul content with those who call on their Lord morning and evening, seeking His Face; and let not thine eyes pass beyond them, seeking the pomp and glitter of this Life; no obey any whose heart We have permitted to neglect the remembrance of Us, one who follows his own desires, whose case has gone beyond all bounds.'),
  ('en.yusufali', 18, 29, 'Say, "The truth is from your Lord": Let him who will believe, and let him who will, reject (it): for the wrong-doers We have prepared a Fire whose (smoke and flames), like the walls and roof of a tent, will hem them in: if they implore relief they will be granted water like melted brass, that will scald their faces, how dreadful the drink! How uncomfortable a couch to recline on!'),
  ('en.yusufali', 18, 30, 'As to those who believe and work righteousness, verily We shall not suffer to perish the reward of any who do a (single) righteous deed.'),
  ('en.yusufali', 18, 31, 'For them will be Gardens of Eternity; beneath them rivers will flow; they will be adorned therein with bracelets of gold, and they will wear green garments of fine silk and heavy brocade: They will recline therein on raised thrones. How good the recompense! How beautiful a couch to recline on!'),
  ('en.yusufali', 18, 32, 'Set forth to them the parable of two men: for one of them We provided two gardens of grape-vines and surrounded them with date palms; in between the two We placed corn-fields.'),
  ('en.yusufali', 18, 33, 'Each of those gardens brought forth its produce, and failed not in the least therein: in the midst of them We caused a river to flow.'),
  ('en.yusufali', 18, 34, '(Abundant) was the produce this man had: he said to his companion, in the course of a mutual argument: "more wealth have I than you, and more honour and power in (my following of) men."'),
  ('en.yusufali', 18, 35, 'He went into his garden in a state (of mind) unjust to his soul: He said, "I deem not that this will ever perish,'),
  ('en.yusufali', 18, 36, '"Nor do I deem that the Hour (of Judgment) will (ever) come: Even if I am brought back to my Lord, I shall surely find (there) something better in exchange."'),
  ('en.yusufali', 18, 37, 'His companion said to him, in the course of the argument with him: "Dost thou deny Him Who created thee out of dust, then out of a sperm-drop, then fashioned thee into a man?'),
  ('en.yusufali', 18, 38, '"But (I think) for my part that He is Allah, My Lord, and none shall I associate with my Lord.'),
  ('en.yusufali', 18, 39, '"Why didst thou not, as thou wentest into thy garden, say: \'Allah\'s will (be done)! There is no power but with Allah!\' If thou dost see me less than thee in wealth and sons,'),
  ('en.yusufali', 18, 40, '"It may be that my Lord will give me something better than thy garden, and that He will send on thy garden thunderbolts (by way of reckoning) from heaven, making it (but) slippery sand!-'),
  ('en.yusufali', 18, 41, '"Or the water of the garden will run off underground so that thou wilt never be able to find it."'),
  ('en.yusufali', 18, 42, 'So his fruits (and enjoyment) were encompassed (with ruin), and he remained twisting and turning his hands over what he had spent on his property, which had (now) tumbled to pieces to its very foundations, and he could only say, "Woe is me! Would I had never ascribed partners to my Lord and Cherisher!"'),
  ('en.yusufali', 18, 43, 'Nor had he numbers to help him against Allah, nor was he able to deliver himself.'),
  ('en.yusufali', 18, 44, 'There, the (only) protection comes from Allah, the True One. He is the Best to reward, and the Best to give success.'),
  ('en.yusufali', 18, 45, 'Set forth to them the similitude of the life of this world: It is like the rain which we send down from the skies: the earth\'s vegetation absorbs it, but soon it becomes dry stubble, which the winds do scatter: it is (only) Allah who prevails over all things.'),
  ('en.yusufali', 18, 46, 'Wealth and sons are allurements of the life of this world: But the things that endure, good deeds, are best in the sight of thy Lord, as rewards, and best as (the foundation for) hopes.'),
  ('en.yusufali', 18, 47, 'One Day We shall remove the mountains, and thou wilt see the earth as a level stretch, and We shall gather them, all together, nor shall We leave out any one of them.'),
  ('en.yusufali', 18, 48, 'And they will be marshalled before thy Lord in ranks, (with the announcement), "Now have ye come to Us (bare) as We created you first: aye, ye thought We shall not fulfil the appointment made to you to meet (Us)!":'),
  ('en.yusufali', 18, 49, 'And the Book (of Deeds) will be placed (before you); and thou wilt see the sinful in great terror because of what is (recorded) therein; they will say, "Ah! woe to us! what a Book is this! It leaves out nothing small or great, but takes account thereof!" They will find all that they did, placed before them: And not one will thy Lord treat with injustice.'),
  ('en.yusufali', 18, 50, 'Behold! We said to the angels, "Bow down to Adam": They bowed down except Iblis. He was one of the Jinns, and he broke the Command of his Lord. Will ye then take him and his progeny as protectors rather than Me? And they are enemies to you! Evil would be the exchange for the wrong-doers!'),
  ('en.yusufali', 18, 51, 'I called them not to witness the creation of the heavens and the earth, nor (even) their own creation: nor is it for helpers such as Me to take as lead (men) astray!'),
  ('en.yusufali', 18, 52, 'One Day He will say, "Call on those whom ye thought to be My partners," and they will call on them, but they will not listen to them; and We shall make for them a place of common perdition.'),
  ('en.yusufali', 18, 53, 'And the Sinful shall see the fire and apprehend that they have to fall therein: no means will they find to turn away therefrom.'),
  ('en.yusufali', 18, 54, 'We have explained in detail in this Qur\'an, for the benefit of mankind, every kind of similitude: but man is, in most things, contentious.'),
  ('en.yusufali', 18, 55, 'And what is there to keep back men from believing, now that Guidance has come to them, nor from praying for forgiveness from their Lord, but that (they ask that) the ways of the ancients be repeated with them, or the Wrath be brought to them face to face?'),
  ('en.yusufali', 18, 56, 'We only send the messengers to give Glad Tidings and to give warnings: But the unbelievers dispute with vain argument, in order therewith to weaken the truth, and they treat My Signs as a jest, as also the fact that they are warned!'),
  ('en.yusufali', 18, 57, 'And who doth more wrong than one who is reminded of the Signs of his Lord, but turns away from them, forgetting the (deeds) which his hands have sent forth? Verily We have set veils over their hearts lest they should understand this, and over their ears, deafness, if thou callest them to guidance, even then will they never accept guidance.'),
  ('en.yusufali', 18, 58, 'But your Lord is Most forgiving, full of Mercy. If He were to call them (at once) to account for what they have earned, then surely He would have hastened their punishment: but they have their appointed time, beyond which they will find no refuge.'),
  ('en.yusufali', 18, 59, 'Such were the populations we destroyed when they committed iniquities; but we fixed an appointed time for their destruction.'),
  ('en.yusufali', 18, 60, 'Behold, Moses said to his attendant, "I will not give up until I reach the junction of the two seas or (until) I spend years and years in travel."'),
  ('en.yusufali', 18, 61, 'But when they reached the Junction, they forgot (about) their Fish, which took its course through the sea (straight) as in a tunnel.'),
  ('en.yusufali', 18, 62, 'When they had passed on (some distance), Moses said to his attendant: "Bring us our early meal; truly we have suffered much fatigue at this (stage of) our journey."'),
  ('en.yusufali', 18, 63, 'He replied: "Sawest thou (what happened) when we betook ourselves to the rock? I did indeed forget (about) the Fish: none but Satan made me forget to tell (you) about it: it took its course through the sea in a marvellous way!"'),
  ('en.yusufali', 18, 64, 'Moses said: "That was what we were seeking after:" So they went back on their footsteps, following (the path they had come).'),
  ('en.yusufali', 18, 65, 'So they found one of Our servants, on whom We had bestowed Mercy from Ourselves and whom We had taught knowledge from Our own Presence.'),
  ('en.yusufali', 18, 66, 'Moses said to him: "May I follow thee, on the footing that thou teach me something of the (Higher) Truth which thou hast been taught?"'),
  ('en.yusufali', 18, 67, '(The other) said: "Verily thou wilt not be able to have patience with me!"'),
  ('en.yusufali', 18, 68, '"And how canst thou have patience about things about which thy understanding is not complete?"'),
  ('en.yusufali', 18, 69, 'Moses said: "Thou wilt find me, if Allah so will, (truly) patient: nor shall I disobey thee in aught."'),
  ('en.yusufali', 18, 70, 'The other said: "If then thou wouldst follow me, ask me no questions about anything until I myself speak to thee concerning it."'),
  ('en.yusufali', 18, 71, 'So they both proceeded: until, when they were in the boat, he scuttled it. Said Moses: "Hast thou scuttled it in order to drown those in it? Truly a strange thing hast thou done!"'),
  ('en.yusufali', 18, 72, 'He answered: "Did I not tell thee that thou canst have no patience with me?"'),
  ('en.yusufali', 18, 73, 'Moses said: "Rebuke me not for forgetting, nor grieve me by raising difficulties in my case."'),
  ('en.yusufali', 18, 74, 'Then they proceeded: until, when they met a young man, he slew him. Moses said: "Hast thou slain an innocent person who had slain none? Truly a foul (unheard of) thing hast thou done!"'),
  ('en.yusufali', 18, 75, 'He answered: "Did I not tell thee that thou canst have no patience with me?"'),
  ('en.yusufali', 18, 76, '(Moses) said: "If ever I ask thee about anything after this, keep me not in thy company: then wouldst thou have received (full) excuse from my side."'),
  ('en.yusufali', 18, 77, 'Then they proceeded: until, when they came to the inhabitants of a town, they asked them for food, but they refused them hospitality. They found there a wall on the point of falling down, but he set it up straight. (Moses) said: "If thou hadst wished, surely thou couldst have exacted some recompense for it!"'),
  ('en.yusufali', 18, 78, 'He answered: "This is the parting between me and thee: now will I tell thee the interpretation of (those things) over which thou wast unable to hold patience.'),
  ('en.yusufali', 18, 79, '"As for the boat, it belonged to certain men in dire want: they plied on the water: I but wished to render it unserviceable, for there was after them a certain king who seized on every boat by force.'),
  ('en.yusufali', 18, 80, '"As for the youth, his parents were people of Faith, and we feared that he would grieve them by obstinate rebellion and ingratitude (to Allah and man).'),
  ('en.yusufali', 18, 81, '"So we desired that their Lord would give them in exchange (a son) better in purity (of conduct) and closer in affection.'),
  ('en.yusufali', 18, 82, '"As for the wall, it belonged to two youths, orphans, in the Town; there was, beneath it, a buried treasure, to which they were entitled: their father had been a righteous man: So thy Lord desired that they should attain their age of full strength and get out their treasure - a mercy (and favour) from thy Lord. I did it not of my own accord. Such is the interpretation of (those things) over which thou wast unable to hold patience."'),
  ('en.yusufali', 18, 83, 'They ask thee concerning Zul-qarnain. Say, "I will rehearse to you something of his story."'),
  ('en.yusufali', 18, 84, 'Verily We established his power on earth, and We gave him the ways and the means to all ends.'),
  ('en.yusufali', 18, 85, 'One (such) way he followed,'),
  ('en.yusufali', 18, 86, 'Until, when he reached the setting of the sun, he found it set in a spring of murky water: Near it he found a People: We said: "O Zul-qarnain! (thou hast authority,) either to punish them, or to treat them with kindness."'),
  ('en.yusufali', 18, 87, 'He said: "Whoever doth wrong, him shall we punish; then shall he be sent back to his Lord; and He will punish him with a punishment unheard-of (before).'),
  ('en.yusufali', 18, 88, '"But whoever believes, and works righteousness,- he shall have a goodly reward, and easy will be his task as We order it by our Command."'),
  ('en.yusufali', 18, 89, 'Then followed he (another) way,'),
  ('en.yusufali', 18, 90, 'Until, when he came to the rising of the sun, he found it rising on a people for whom We had provided no covering protection against the sun.'),
  ('en.yusufali', 18, 91, '(He left them) as they were: We completely understood what was before him.'),
  ('en.yusufali', 18, 92, 'Then followed he (another) way,'),
  ('en.yusufali', 18, 93, 'Until, when he reached (a tract) between two mountains, he found, beneath them, a people who scarcely understood a word.'),
  ('en.yusufali', 18, 94, 'They said: "O Zul-qarnain! the Gog and Magog (People) do great mischief on earth: shall we then render thee tribute in order that thou mightest erect a barrier between us and them?'),
  ('en.yusufali', 18, 95, 'He said: "(The power) in which my Lord has established me is better (than tribute): Help me therefore with strength (and labour): I will erect a strong barrier between you and them:'),
  ('en.yusufali', 18, 96, '"Bring me blocks of iron." At length, when he had filled up the space between the two steep mountain-sides, He said, "Blow (with your bellows)" Then, when he had made it (red) as fire, he said: "Bring me, that I may pour over it, molten lead."'),
  ('en.yusufali', 18, 97, 'Thus were they made powerless to scale it or to dig through it.'),
  ('en.yusufali', 18, 98, 'He said: "This is a mercy from my Lord: But when the promise of my Lord comes to pass, He will make it into dust; and the promise of my Lord is true."'),
  ('en.yusufali', 18, 99, 'On that day We shall leave them to surge like waves on one another: the trumpet will be blown, and We shall collect them all together.'),
  ('en.yusufali', 18, 100, 'And We shall present Hell that day for Unbelievers to see, all spread out,-'),
  ('en.yusufali', 18, 101, '(Unbelievers) whose eyes had been under a veil from remembrance of Me, and who had been unable even to hear.'),
  ('en.yusufali', 18, 102, 'Do the Unbelievers think that they can take My servants as protectors besides Me? Verily We have prepared Hell for the Unbelievers for (their) entertainment.'),
  ('en.yusufali', 18, 103, 'Say: "Shall we tell you of those who lose most in respect of their deeds?-'),
  ('en.yusufali', 18, 104, '"Those whose efforts have been wasted in this life, while they thought that they were acquiring good by their works?"'),
  ('en.yusufali', 18, 105, 'They are those who deny the Signs of their Lord and the fact of their having to meet Him (in the Hereafter): vain will be their works, nor shall We, on the Day of Judgment, give them any weight.'),
  ('en.yusufali', 18, 106, 'That is their reward, Hell, because they rejected Faith, and took My Signs and My Messengers by way of jest.'),
  ('en.yusufali', 18, 107, 'As to those who believe and work righteous deeds, they have, for their entertainment, the Gardens of Paradise,'),
  ('en.yusufali', 18, 108, 'Wherein they shall dwell (for aye): no change will they wish for from them.'),
  ('en.yusufali', 18, 109, 'Say: "If the ocean were ink (wherewith to write out) the words of my Lord, sooner would the ocean be exhausted than would the words of my Lord, even if we added another ocean like it, for its aid."'),
  ('en.yusufali', 18, 110, 'Say: "I am but a man like yourselves, (but) the inspiration has come to me, that your Allah is one Allah: whoever expects to meet his Lord, let him work righteousness, and, in the worship of his Lord, admit no one as partner.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 18, 1, 'Alhamdu lillaahil lazeee anzala \'alaa \'abdihil kitaaba wa lam yaj\'al lahoo \'iwajaa'),
  ('en.transliteration', 18, 2, 'Qaiyimal liyunzira baasan shadeedam mil ladunhu wa yubashshiral mu\'mineenal lazeena ya\'maloonas saalihaati anna lahum ajran hasanaa'),
  ('en.transliteration', 18, 3, 'Maakiseena feehi abadaa'),
  ('en.transliteration', 18, 4, 'Wa yunziral lazeena qaalut takhazal laahu waladaa'),
  ('en.transliteration', 18, 5, 'Maa lahum bihee min \'ilminw wa laa li aabaaa\'ihim; kaburat kalimatan takhruju min afwaahihim; iny yaqooloona illaa kazibaa'),
  ('en.transliteration', 18, 6, 'Fala\'allaka baakhi\'un nafsaka \'alaaa aasaarihim illam yu;minoo bihaazal hadeesi asafaa'),
  ('en.transliteration', 18, 7, 'Innaa ja\'alnaa ma \'alal ardi zeenatal lahaa linabluwahum ayyuhum ahsanu \'amalaa'),
  ('en.transliteration', 18, 8, 'Wa innaa lajaa \'iloona maa \'alaihaa sa\'aeedan juruzaa'),
  ('en.transliteration', 18, 9, 'Am hasibta anna Ashaabal Kahfi war Raqeemi kaanoo min Aayaatinaa \'ajabaa'),
  ('en.transliteration', 18, 10, 'Iz awal fityatu ilal Kahfi faqaaloo Rabbanaaa aatinaa mil ladunka rahmatanw wa haiyi\' lanaa min amrinaa rashadaa'),
  ('en.transliteration', 18, 11, 'Fadarabnaa \'alaaa aazaanihim fil Kahfi seneena \'adadaa'),
  ('en.transliteration', 18, 12, 'Summa ba\'asnaahum lina\'lama ayyul hizbaini ahsaa limaa labisooo amadaa'),
  ('en.transliteration', 18, 13, 'Nahnu naqussu \'alaika naba ahum bilhaqq; innahum fityatun aamanoo bi Rabbihim wa zidnaahum hudaa'),
  ('en.transliteration', 18, 14, 'Wa rabatnaa \'alaa quloo bihim iz qaamoo faqaaloo Rabbunaa Rabbus samaawaati wal ardi lan nad\'uwa min dooniheee ilaahal laqad qulnaaa izan shatataa'),
  ('en.transliteration', 18, 15, 'Haaa\'ulaaa\'i qawmunat takhazoo min dooniheee aalihatal law laa yaatoona \'alaihim bisultaanim baiyin; faman azlamu mimmaniftaraa \'alal laahi kazibaa'),
  ('en.transliteration', 18, 16, 'Wa izi\'tazal tumoohum wa maa ya\'budoona illal laaha faawooo ilal kahfi yanshur lakum Rabbukum mir rahmatihee wa yuhaiyi\' lakum min amrikum mirfaqa'),
  ('en.transliteration', 18, 17, 'Wa tarash shamsa izaa tala\'at tazaawaru \'an kahfihim zaatal yameeni wa izaa gharabat taqriduhum zaatash shimaali wa hum fee fajwatim minh; zaalika min Aayaatillaah; mai yahdil laahu fahuwal muhtad, wa mai yudlil falan tajida lahoo waliyyam murshidaa'),
  ('en.transliteration', 18, 18, 'Wa tahsabuhum ayqaazanw wa hum ruqood; wa nuqallibuhum zaatal yameeni wa zaatash shimaali wa kalbuhum baasitun ziraa\'ayhi bilwaseed; lawit tala\'ta \'alaihim la wallaita minhum firaaranw wa lamuli\'ta minhum rubaa'),
  ('en.transliteration', 18, 19, 'Wa kazaalika ba\'asnaahum liyatasaaa\'aloo bainahum; qaala qaaa\'ilum minhum kam labistum qaaloo labisnaa yawman aw ba\'da yawm; qaaloo Rabbukum a\'almu bimaa labistum fab\'asooo ahadakum biwariqikum haazihee ilal madeenati falyanzur ayyuhaaa azkaa ta\'aaman falyaatikum birizqim minhu walyatalattaf wa laa yush\'iranna bikum ahadaa'),
  ('en.transliteration', 18, 20, 'Innahum iny yazharoo \'alaikum yarjumookum aw yu\'eedookum fee millatihim wa lan tuflihooo izan abadaa'),
  ('en.transliteration', 18, 21, 'Wa kazaalika a\'sarnaa \'alaihim liya\'lamooo anna wa\'dal laahi haqqunw wa annas Saa\'ata laa raiba feehaa iz yatanaaza\'oona bainahum amrahum faqaalub noo \'alaihim bunyaanaa; Rabbuhum a\'lamu bihim; qaalal lazeena ghalaboo \'alaaa amrihim lanat takhizanna \'alaihim masjidaa'),
  ('en.transliteration', 18, 22, 'Sa yaqooloona salaasatur raabi\'uhum kalbuhum wa yaqooloona khamsatun saadisuhum kalbuhum rajmam bilghaib; wa yaqooloona sab\'atunw wa saaminuhum kalbuhum; qur Rabbeee a\'lamu bi\'iddatihim maa ya\'lamuhum illaa qaleel; falaa tumaari feehim illaa miraaa\'an zaahiranw wa laa tastafti feehim minhum ahadaa'),
  ('en.transliteration', 18, 23, 'Wa laa taqoolanna lishai\'in innee faa\'ilun zaalika ghadaa'),
  ('en.transliteration', 18, 24, 'Illaaa any yashaaa\'al laah; wazkur Rabbaka izaa naseeta wa qul \'asaaa any yahdiyani Rabbee li aqraba min haazaa rashadaa'),
  ('en.transliteration', 18, 25, 'Wa labisoo fee kahfihim salaasa mi\'atin sineena wazdaadoo tis\'aa'),
  ('en.transliteration', 18, 26, 'Qulil laahu a\'lamu bimaa labisoo lahoo ghaibus samaawaati wal ardi absir bihee wa asmi\'; maa lahum min doonihee minw waliyyinw wa laa yushriku fee hukmihee ahadaa'),
  ('en.transliteration', 18, 27, 'Watlu maaa oohiya ilaika min Kitaabi Rabbika laa mubaddila li Kalimaatihee wa lan tajida min doonihee multahadaa'),
  ('en.transliteration', 18, 28, 'Wasbir nafsaka ma\'al lazeena yad\'oona Rabbahum bilghadaati wal\'ashiyyi yureedoona Wajhahoo wa laa ta\'du \'aynaaka \'anhum tureedu zeenatal hayaatid dunyaa wa laa tuti\' man aghfalnaa qalbahoo \'an zikrinaa wattaba\'a hawaahu wa kaana amruhoo furutaa'),
  ('en.transliteration', 18, 29, 'Wa qulil haqqu mir Rabbikum faman shaaa\'a falyu minw wa man shaaa\'a falyakfur; innaaa a\'tadnaa lizzaalimeena Naaran ahaata bihim suraadiquhaa; wa iny yastagheesoo yaghaasoo bimaaa\'in kalmuhli yashwil wujooh\' bi\'sash-sharaab; wa saaa\'at murtafaqaa'),
  ('en.transliteration', 18, 30, 'Innal lazeena aamanoo wa \'amilus saalihaati innaa laa nudee\'u ajra man ahsana \'amalaa'),
  ('en.transliteration', 18, 31, 'Ulaaa\'ika lahum Jannaatu \'Adnin tajree min tahtihimul anhaaru yuhallawna feehaa min asaawira min zahabinw wa yalbasoona siyaaban khudram min sundusinw wa istabraqim muttaki\'eena feehaa \'alal araaa\'ik; ni\'mas sawaab; wa hasunat murtafaqaa'),
  ('en.transliteration', 18, 32, 'Wadrib lahum masalar rajulaini ja\'alnaa li ahadihimaa jannataini min a\'naabinw wa hafafnaahumaa binakhilinw wa ja\'alnaa bainahumaa zar\'aa'),
  ('en.transliteration', 18, 33, 'Kiltal jannataini aatat ukulahaa wa lam tazlim minhu shai\'anw wa fajjarnaa khi laalahumaa naharaa'),
  ('en.transliteration', 18, 34, 'Wa kaana lahoo samarun faqaala lisaahibihee wa huwa yuhaawiruhoo ana aksaru minka maalanw wa a\'azzu nafaraa'),
  ('en.transliteration', 18, 35, 'Wa dakhala jannatahoo wa huwa zaalimul linafsihee qaala maaa azunnu an tabeeda haaziheee abadaa'),
  ('en.transliteration', 18, 36, 'Wa maaa azunnus Saa\'ata qaaa\'imatanw wa la\'ir rudittu ilaa Rabbee la ajidanna khairam minhaa munqalabaa'),
  ('en.transliteration', 18, 37, 'Qaala lahoo saahibuhoo wa huwa yuhaawiruhooo akafarta billazee khalaqaka min turaabin summa min nutfatin summa sawwaaka rajulaa'),
  ('en.transliteration', 18, 38, 'Laakinaa Huwal laahu Rabbee wa laa ushriku bi Rabbeee ahadaa'),
  ('en.transliteration', 18, 39, 'Wa law laaa iz dakhalta jannataka qulta maa shaaa\'al laahu laa quwwata illaa billaah; in tarani ana aqalla minka maalanw wa waladaa'),
  ('en.transliteration', 18, 40, 'Fa\'asaa Rabeee any yu\'tiyani khairam min jannatika wa yursila \'alaihaa husbaanam minas samaaa\'i fatusbiha sa\'eedan zalaqaa'),
  ('en.transliteration', 18, 41, 'Aw yusbiha maaa\'uhaaa ghawran falan tastatee\'a lahoo talabaa'),
  ('en.transliteration', 18, 42, 'Wa uheeta bisamarihee faasbaha yuqallibu kaffaihi \'alaa maaa anfaqa feehaa wa hiya khaawiyatun \'alaa \'urooshihaa wa yaqoolu yaalaitanee lam ushrik bi Rabbeee ahadaa'),
  ('en.transliteration', 18, 43, 'Wa lam takul lahoo fi\'atuny yansuroonahoo min doonil laahi wa maa kaana muntasiraa'),
  ('en.transliteration', 18, 44, 'Hunaalikal walaayatu lillaahil haqq; huwa khairun sawaabanw wa khairun \'uqbaa'),
  ('en.transliteration', 18, 45, 'Wadrib lahum masalal hayaatid dunyaa kamaaa\'in anzalnaahu minas samaaa\'i fakhtalata bihee nabaatul ardi fa asbaha hasheeman tazroo hur riyaah; wa kaanal laahu \'alaa kulli shai\'im muqtadiraa'),
  ('en.transliteration', 18, 46, 'Almaalu walbanoona zeenatul hayaatid dunya wal baaqiyaatus saalihaatu khairun \'inda Rabbika sawaabanw wa khairun amalaa'),
  ('en.transliteration', 18, 47, 'Wa yawma nusaiyirul jibaala wa taral arda baariza tanw wa hasharnaahum falam nughaadir minhum ahadaa'),
  ('en.transliteration', 18, 48, 'Wa \'uridoo \'alaa Rabbika saffaa, laqad ji\'tumoonaa kamaa khalaqnaakum awala marrah; bal za\'amtum allannaj\'ala lakum maw\'idaa'),
  ('en.transliteration', 18, 49, 'Wa wudi\'al kitaabu fataral mujrimeena mushfiqeena mimmaa feehi wa yaqooloona yaa wailatanaa maa lihaazal kitaabi laa yughaadiru saghee ratanw wa laa kabeeratan illaaa ahsaahaa; wa wajadoo maa \'amiloo haadiraa; wa laa yazlimu Rabbuka ahadaa'),
  ('en.transliteration', 18, 50, 'Wa iz qulnaa lilma laaa\'ikatis judoo li Aadama fasajadooo illaaa Ibleesa kaana minal jinni fafasaqa \'an amri Rabbih; afatattakhizoonahoo wa zurriyatahooo awliyaaa\'a min doonee wa hum lakum \'aduww; bi\'sa lizzaalimeena badalaa'),
  ('en.transliteration', 18, 51, 'Maaa ash hattuhum khalqas samaawaati wal ardi wa laa khalqa anfusihim wa maa kuntu muttakizal mudilleena \'adudaa'),
  ('en.transliteration', 18, 52, 'Wa Yawma yaqoolu naadoo shurakaaa\'i yal lazeena za\'amtum fada\'awhum falam yastajeeboo lahum wa ja\'alnaa bainahum maw biqaa'),
  ('en.transliteration', 18, 53, 'Wa ra al mujrimoonan Naara fazannooo annahum muwaaqi\'oohaa wa lam yajidoo \'anhaa masrifaa'),
  ('en.transliteration', 18, 54, 'Wa laqad sarrafnaa fee haazal quraani linnaasi mn kulli masal; wa kaanal insaanu aksara shai\'in jadalaa'),
  ('en.transliteration', 18, 55, 'Wa maa mana\'an naasa any yu\'minooo iz jaaa\'ahumul hudaa wa yastaghfiroo Rabbahum illaaa an taatiyahum sunnatul awwaleena aw yaatiyahumul \'azaabu qubulaa'),
  ('en.transliteration', 18, 56, 'Wa maa nursilul mursaleena illaa mubashshireena wa munzireen; wa yujaadilul lazeena kafaroo bilbaatili liyudhidoo bihil haqqa wattakhazooo Aayaatee wa maaa unziroo huzuwaa'),
  ('en.transliteration', 18, 57, 'Wa man azlamu mimman zukkira bi ayaati Rabbihee fa-a\'rada \'anhaa wa nasiya maa qaddamat yadaah; innaa ja\'alnaa \'alaa quloobihim akinnatan any yafqahoohu wa feee aazaanihim waqraa; wa in tad\'uhum ilal hudaa falany yahtadooo izan abadaa'),
  ('en.transliteration', 18, 58, 'Wa Rabbukal Ghafooru zur rahmati law yu\'aakhi zuhum bimaa kasaboo la\'ajala lahumul \'azaab; bal lahum maw\'idul lany yajidoo min doonihee maw\'ilaa'),
  ('en.transliteration', 18, 59, 'Wa tkal quraaa ahlak nahum lammaa zulamoo wa ja\'alnaa limahlikihim maw\'idaa'),
  ('en.transliteration', 18, 60, 'Wa iz qaalaa Moosaa lifataahu laaa abrahu hattaaa ablugha majma\'al bahrayni aw amdiya huqubaa'),
  ('en.transliteration', 18, 61, 'Falammaa balaghaa majma\'a bainihimaa nasiyaa hootahumaa fattakhaza sabeelahoo fil bahri sarabaa'),
  ('en.transliteration', 18, 62, 'Falammaa jaawazaa qaala lifataahu aatinaa ghadaaa\'anaa laqad laqeena min safarinaa haazaa nasabaa'),
  ('en.transliteration', 18, 63, 'Qaala ara\'ayta iz awainaaa ilas sakhrati fa innee naseetul hoota wa maaa ansaaneehu illash Shaitaanu an azkurah; wattakhaza sabeelahoo fil bahri\'ajabaa'),
  ('en.transliteration', 18, 64, 'Qaala zaalika maa kunnaa nabgh; fartaddaa \'alaa aasaari him maa qasasaa'),
  ('en.transliteration', 18, 65, 'Fa wajadaa \'abdam min \'ibaadinaaa aatainaahu Rahmatam min \'indinaa wa \'allamnaahu mil ladunnaa \'ilmaa'),
  ('en.transliteration', 18, 66, 'Qaala lahoo Moosaa hal attabi\'uka \'alaaa an tu\'allimani mimmaa \'ullimta rushdaa'),
  ('en.transliteration', 18, 67, 'Qaalaa innaka lan tastatee\'a ma\'iya sabraa'),
  ('en.transliteration', 18, 68, 'Wa kaifa tasbiru \'alaa maa lam tuhit bihee khubraa'),
  ('en.transliteration', 18, 69, 'Qaala satajiduneee in shaa \'al laahu saabiranw wa laaa a\'see laka amraa'),
  ('en.transliteration', 18, 70, 'Qaala fa init taba\'tanee falaa tas\'alnee \'an shai\'in hattaaa uhdisa laka minhu zikraa'),
  ('en.transliteration', 18, 71, 'Fantalaqaa hattaaa izaa rakibaa fis safeenati kharaqahaa qaala akharaqtahaa litughriqa ahlahaa laqad ji\'ta shai\'an imraa'),
  ('en.transliteration', 18, 72, 'Qaala alam aqul innaka lan tastatee\'a ma\'iya sabraa'),
  ('en.transliteration', 18, 73, 'Qaala laa tu\'aakhiznee bimaa naseetu wa laa turhiqnee min amree \'usraa'),
  ('en.transliteration', 18, 74, 'Fantalaqaa hattaa izaa laqiyaa ghulaaman faqatalahoo qaala aqatalta nafsan zakiy yatam bighairi nafs; laqad ji\'ta shai\'an nukraa'),
  ('en.transliteration', 18, 75, 'Qaala alam aqul laka innaka lan tastatee\'a ma\'iya sabraa'),
  ('en.transliteration', 18, 76, 'Qaala in sa altuka \'an shai\'im ba\'dahaa falaa tusaahibnee qad balaghta mil ladunnee \'uzraa'),
  ('en.transliteration', 18, 77, 'Fantalaqaa hattaaa izaaa atayaaa ahla qaryatinis tat\'amaaa ahlahaa fa abaw any yudaiyifoohumaa fawajadaa feehaa jidaarany yureedu any yanqadda fa aqaamah; qaala law shi\'ta lattakhazta \'alaihi ajraa'),
  ('en.transliteration', 18, 78, 'Qaala haazaa firaaqu bainee wa bainik; sa unabi \'uka bitaaweeli maa lam tastati\' \'alaihi sabraa'),
  ('en.transliteration', 18, 79, 'Ammas safeenatu fakaanat limasaakeena ya\'maloona fil bahri fa arattu an a\'eebahaa wa kaana waraaa\' ahum malikuny yaakhuzu kulla safeenatin ghasbaa'),
  ('en.transliteration', 18, 80, 'Wa aammal ghulaamu fakaana abawaahu mu\'minaini fakhasheenaaa any yurhiqa humaa tughyaananw wa kufraa'),
  ('en.transliteration', 18, 81, 'Faradnaa any yubdila humaa Rabbuhumaa khairam minhu zakaatanw wa aqraba ruhmaa'),
  ('en.transliteration', 18, 82, 'Wa ammal jidaaru fakaana lighulaamaini yateemaini fil madeenati wa kaana tahtahoo kanzul lahumaa wa kaana aboohumaa saalihan fa araada Rabbuka any yablughaaa ashuddahumaa wa yastakhrijaa kanzahumaa rahmatam mir Rabbik; wa maa fa\'altuhoo \'an amree; zaalika taaweelu maa lam tasti\' \'alaihi sabra'),
  ('en.transliteration', 18, 83, 'Wa yas\'aloonaka \'an Zil Qarnaini qul sa atloo \'alaikum minhu zikraa'),
  ('en.transliteration', 18, 84, 'Innaa makkannaa lahoo fil ardi wa aatainaahu min kulli shai\'in sababaa'),
  ('en.transliteration', 18, 85, 'Fa atba\'a sababaa'),
  ('en.transliteration', 18, 86, 'Hattaaa izaa balagha maghribash shamsi wajadahaaa taghrubu fee \'aynin hami\'a tinw wa wajada \'indahaa qawmaa; qulnaa yaa Zal Qarnaini immaaa an tu\'az ziba wa immaaa an tattakhiza feehim husnaa'),
  ('en.transliteration', 18, 87, 'Qaala amaa man zalama fasawfa nu\'azzibuhoo summa yuraddu ilaa Rabbihee fa yu \'azzibuhoo azaaban nukraa'),
  ('en.transliteration', 18, 88, 'Wa ammaa man aamana wa \'amila saalihan falahoo jazaaa\'anil husnaa wa sanaqoolu lahoo min amrinaa yusraa'),
  ('en.transliteration', 18, 89, 'Summa atba\'a sababaa'),
  ('en.transliteration', 18, 90, 'Hattaaa izaa balagha matli\'ash shamsi wajdahaa tatlu\'u alaa qawmil lam naj\'al lahum min doonihaa sitraa'),
  ('en.transliteration', 18, 91, 'Kazaalika wa qad ahatnaa bimaa ladaihi khubraa'),
  ('en.transliteration', 18, 92, 'Summa atba\'a sababaa'),
  ('en.transliteration', 18, 93, 'Hattaaa izaa balagha bainas saddaini wajada min doonihimaa qawmal laa yakaa doona yafqahoona qawlaa'),
  ('en.transliteration', 18, 94, 'Qaaloo yaa Zal qarnaini inna Yaajooja wa Maajooja mufsidoona fil ardi fahal naj\'alu laka kharjan \'alaaa an taj\'ala bainanaa wa bainahum saddas'),
  ('en.transliteration', 18, 95, 'Qaala maa makkannee feehi Rabbee khairun fa-a\'eenoonee biquwwatin aj\'al bainakum wa bainahum radmaa'),
  ('en.transliteration', 18, 96, 'Aatoonee zubaral hadeed, hattaaa izaa saawaa bainas sadafaini qaalan fukhoo hattaaa izaa ja\'alahoo naaran qaala aatooneee ufrigh \'alaihi qitraa'),
  ('en.transliteration', 18, 97, 'Famas taa\'ooo any yazharoohu wa mastataa\'oo lahoo naqbaa'),
  ('en.transliteration', 18, 98, 'Qaala haaza rahmatummir Rabbee fa izaa jaaa\'a wa\'du Rabbee ja\'alahoo dakkaaa\'a; wa kaana; wa du Rabbee haqqaa'),
  ('en.transliteration', 18, 99, 'Wa taraknaa ba\'dahum Yawma\'iziny yamooju fee ba\'dinw wa nufikha fis Soori fajama\'naahum jam\'aa'),
  ('en.transliteration', 18, 100, 'Wa \'aradnaa jahannama Yawma\'izil lilkaafireena \'ardaa'),
  ('en.transliteration', 18, 101, 'Allazeena kaanat a\'yunuhum fee ghitaaa\'in \'an zikree wa kaanoo la yastatee\'oona sam\'aa'),
  ('en.transliteration', 18, 102, 'Afahasibal lazeena kafarooo any yattakhizoo \'ibaadee min dooneee awliyaaa\'; innaaa a\'tadnaa jahannama lilkaafi reena nuzulaa'),
  ('en.transliteration', 18, 103, 'Qul hal nunabbi\'ukum bilakhsareena a\'maalaa'),
  ('en.transliteration', 18, 104, 'Allazeena dalla sa\'yuhum fil hayaatid dunyaa wa hum yahsaboona annahum yuhsinoona sun\'aa'),
  ('en.transliteration', 18, 105, 'Ulaaa\'ikal lazeena kafaroo bi aayaati Rabbihim wa liqaaa\'ihee fahabitat a\'maaluhum falaa nuqeemu lahum Yawmal Qiyaamati waznaa'),
  ('en.transliteration', 18, 106, 'Zaalika jazaaa\'uhum jahannamu bimaa kafaroo wattakhazooo Aayaatee wa Rusulee huzuwaa'),
  ('en.transliteration', 18, 107, 'Innal lazeena aamanoo wa \'amilus saalihaati kaanat lahum Jannaatul Firdawsi nuzulaa'),
  ('en.transliteration', 18, 108, 'Khaalideena feeha la yabghoona \'anhaa hiwalaa'),
  ('en.transliteration', 18, 109, 'Qul law kaanal bahru midaadal lik Kalimaati Rabbee lanafidal bahru qabla an tanfada Kalimaatu Rabbee wa law ji\'naa bimislihee madadaa'),
  ('en.transliteration', 18, 110, 'Qul innamaaa ana basharum mislukum yoohaaa ilaiya annamaa ilaahukum Ilaahunw Waahid; faman kaana yarjoo liqaaa\'a Rabbihee falya\'mal \'amalan saalihanw wa laa yushrik bi\'ibaadati Rabbiheee ahadaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 18, 1, 'سب تعریف الله کے لیے جس نے اپنے بندہ پر کتاب اتاری اور اس میں ذرا بھی کجی نہیں رکھی'),
  ('ur.ahmedali', 18, 2, 'ٹھیک اتاری تاکہ اس سخت عذاب سے ڈراوے جو اس کے ہاں ہے اورایمان داروں کو خوشخبری دے جو اچھے کام کرتے ہیں کہ ان کے لیے اچھا بدلہ ہے'),
  ('ur.ahmedali', 18, 3, 'جس میں وہ ہمیشہ رہیں گے'),
  ('ur.ahmedali', 18, 4, 'اور انہیں بھی ڈرائے جو کہتے ہیں کہ الله اولاد رکھتا ہے'),
  ('ur.ahmedali', 18, 5, 'ان کے پاس اس کی کوئی دلیل نہیں ہے اور نہ ان کے باپ دادا کے پاس تھی کیسی سخت بات ہے جو ان کے منہ سے نکلتی ہے وہ لوگ بالکل جھوٹ کہتے ہیں'),
  ('ur.ahmedali', 18, 6, 'پھر شایدتو ان کے پیچھے افسوس سے اپنی جان ہلاک کر دے گا اگر یہ لوگ اس بات پر ایمان نہ لائے'),
  ('ur.ahmedali', 18, 7, 'جو کچھ زمین پر ہے بے شک ہم نے اسے زمین کی زینت بنا دیا ہے تاکہ ہم انہیں آزمائیں کہ ان میں کون اچھے کام کرتا ہے'),
  ('ur.ahmedali', 18, 8, 'اورجو کچھ اس پر ہے بے شک ہم سب کو چٹیل میدان کر دیں گے'),
  ('ur.ahmedali', 18, 9, 'کیا تم خیال کرتے ہو کہ غار اور کتبہ والے ہماری نشانیوں والے عجیب چیز تھے'),
  ('ur.ahmedali', 18, 10, 'جب کہ چند جوان اس غار میں آ بیٹھے پھر کہا اے ہمارے رب ہم پر اپنی طرف سے رحمت نازل فرما اور ہمارے اس کام کے لیے کامیابی کا سامان کر دے'),
  ('ur.ahmedali', 18, 11, 'پھر ہم نے کئی سال تک غار میں ان کے کان بند کر دیے'),
  ('ur.ahmedali', 18, 12, 'پھر ہم نے انہیں اٹھایا تاکہ معلوم کریں کہ دونوں جماعتوں میں سے کس نے یاد رکھی ہے جتنی مدت وہ رہے'),
  ('ur.ahmedali', 18, 13, 'ہم تمہیں ان کا صحیح حال سناتے ہیں بے شک وہ کئی جوان تھے جو اپنے رب پر ایمان لائے اور ہم نے انہیں اور زيادہ ہدایت دی'),
  ('ur.ahmedali', 18, 14, 'اورہم نے ان کے دل مضبوط کر دیے جب وہ یہ کہہ کر اٹھ کھڑے ہوئے کہ ہمارا رب آسمانوں اور زمین کا رب ہے ہم اس کے سوا کسی معبود کو ہرگز نہ پکاریں گے ورنہ ہم نے بڑی ہی بیجا بات کہی'),
  ('ur.ahmedali', 18, 15, 'یہ ہماری قوم ہے انہوں نے الله کے سوا اورمعبود بنا لیے ہیں ان پر کوئی کھلی دلیل کیوں نہیں لاتے پھر اس سے بڑا ظالم کون ہوگا جس نے الله پر جھوٹ باندھا'),
  ('ur.ahmedali', 18, 16, 'اور جب تم ان سے الگ ہو گئے ہواور الله کے سوا جنہیں وہ معبود بناتے ہیں تب غار میں چل کر پناہ لو تم پر تمہارا رب اپنی رحمت پھیلا دے گا اور تمہارے لیے تمہارےاس کام میں آرام کا سامان کر دے گا'),
  ('ur.ahmedali', 18, 17, 'اور تو سورج کو دیکھے گا جب وہ نکلتا ہے تو ان کے غار کے دائیں طرف سے ہٹا ہوا رہتا ہے اور جب ڈوبتا ہے تو ان کی بائیں طرف سے کتراتا ہو گزر جاتا ہے وہ اس کے میدان میں ہیں یہ الله کی نشانیوں میں سے ہے جسے الله ہدایت دے وہی ہدایت پانے والا ہے اور جسے وہ گمراہ کر دے پھر اس کے لیے تمہیں کوئی بھی کارساز پر لانے والا نہیں ملے گا'),
  ('ur.ahmedali', 18, 18, 'اور تو انہیں جاگتا ہوا خیال کرے گا حالانکہ وہ سو رہے ہیں اورہم انہیں دائیں بائیں پلٹتے رہتے ہیں اور ان کا کتا چوکھٹ کی جگہ اپنے دونوں بازو پھیلائے بیٹھا ہے اگر تم انہیں جھانک کر دیکھو تو الٹے پاؤں بھاگ کھڑے ہوئے اورالبتہ تم پر ان کی دہشت چھا جائے'),
  ('ur.ahmedali', 18, 19, 'اوراسی طرح ہم نے انہیں جگا دیا تاکہ ایک دوسرے سے پوچھیں ان میں سے ایک نے کہا تم کتنی دیر ٹہرے ہو انہوں نے کہا ہم ایک دن یا دن سے کم ٹھیرے ہیں کہا تمہارا رب خوب جانتا ہے جتنی دیر تم ٹھہرے ہو اب اپنے میں سے ایک کو یہ اپنا روپیہ دے کر اس شہر میں بھیجو پھر دیکھے کون سا کھانا ستھرا ہے پھر تمہارے پاس اس میں سے کھانا لائے اور نرمی سے جائے اور تمہارے متعلق کسی کو نہ بتائے'),
  ('ur.ahmedali', 18, 20, 'بے شک وہ لوگ اگر تمہاری اطلاع پائیں گے تو تمہیں سنگسار کر دیں گےیا اپنے دین میں لوٹا لیں گے پھر تم کبھی فلاح نہیں پا سکو گے'),
  ('ur.ahmedali', 18, 21, 'اور اسی طرح ہم نے ان کی خبر ظاہر کر دی تاکہ لوگ سمجھ لیں کہ الله کا وعدہ سچا ہے اور قیامت میں کوئی شک نہیں جبکہ لوگ ان کے معاملہ میں جھگڑ رہے تھے پھر کہا ان پر ایک عمارت بنا دو انکا رب ان کا حال خوب جانتا ہے ان لوگوں نے کہا جو اپنے معاملے میں غالب آ گئے تھے کہ ہم ان پر ضرور ایک مسجد بنائیں گے'),
  ('ur.ahmedali', 18, 22, 'بعض کہیں گے تین ہیں چوتھا ان کا کتا ہے اور بعض اٹکل پچو سے کہیں گے پانچ ہیں چھٹا ان کا کتا ہے اور بعض کہیں گے سات ہیں آٹھواں ان کا کتا ہے کہہ دو ان کی گنتی میرا رب ہی خوب جانتا ہے ان کا اصلی حال تو بہت ہی کم لوگ جانتے ہیں سو تو ان کے بارے میں سرسری گفتگو کے سوا جھگڑا نہ کرو ان میں سے کسی سےبھی انکا حال دریافت نہ کر'),
  ('ur.ahmedali', 18, 23, 'اورکسی چیز کے متعلق یہ ہر گز نہ کہو کہ میں کل اسے کر ہی دوں گا'),
  ('ur.ahmedali', 18, 24, 'مگر یہ کہ الله چاہے اور اپنے رب کو یاد کر لے جب بھول جائے اور کہہ دو امید ہے کہ میرا رب مجھے اس سے بھی بہتر راستہ دکھائے'),
  ('ur.ahmedali', 18, 25, 'اور وہ اپنے غار میں تین سو سے زائد نو برس رہے ہیں'),
  ('ur.ahmedali', 18, 26, 'کہہ دو الله بہتر جانتا ہے کہ کتنی مدت رہے تمام آسمانوں اور زمین کا علم غیب اسی کو ہے کیا عجیب دیکھتا اور سنتا ہے ان کا الله کے سوا کوئی بھی مددگار نہیں اور نہ ہی وہ اپنے حکم میں کسی کو شریک کرتا ہے'),
  ('ur.ahmedali', 18, 27, 'اور اپنے رب کی کتاب سے جو تیری طرف وحی کی گئی ہے پڑھا کرو اس کی باتوں کوکوئی بدلنے والا نہیں ہے اور تو اس کے سوا کوئی پناہ کی جگہ نہیں پائے گا'),
  ('ur.ahmedali', 18, 28, 'تو ان لوگو ں کی صحبت میں رہ جو صبح اور شام اپنے رب کو پکارتے ہیں اسی کی رضا مندی چاہتے ہیں اور تو اپنی آنکھوں کو ان سے نہ ہٹا کہ دنیا کی زندگی کی زینت تلاش کرنے لگ جائے اور اس شخص کا کہنا نہ مان جس کے دل کو ہم نے اپنی یاد سے غافل کر دیاہے اور اپنی خواہش کے تابع ہو گیا ہے اور ا سکا معاملہ حد سے گزر ا ہوا ہے'),
  ('ur.ahmedali', 18, 29, 'اور کہہ دو سچی بات تمہارے رب کی طرف سے ہے پھر جو چاہے مان لے اور جو چاہے انکار کر دے بے شک ہم نے ظالموں کے لیے آگ تیار کر رکھی ہے انہیں اس کی قناتیں گھیر لیں گی اور اگر فریاد کریں گے تو ایسے پانی سے فریاد رسی کیے جائیں گے جو تانبے کی طرح پگھلا ہوا ہو گا مونہوں کو جھلس دے گا کیا ہی برا پانی ہو گا او رکیا ہی بری آرام گاہ ہو گی'),
  ('ur.ahmedali', 18, 30, 'بے شک جو لوگ ایمان لائے اور اچھے کام کیے ہم بھی اس کا اجر ضائع نہیں کریں گے جس نے اچھے کام کیے'),
  ('ur.ahmedali', 18, 31, 'وہی لوگ ہیں جن کے لیے ہمیشہ رہنے کے باغ ہیں جن کے نیچے نہریں بہہ رہی ہوں گی انہیں وہاں سونے کے کنگن پہنائے جائیں گے اور باریک اور موٹے ریشم کا سبز لباس پہنیں گے وہاں تختوں پر تکیے لگانے والے ہوں گے کیا ہی اچھا بدلہ ہے اور کیا ہی اچھی آرام گا ہے'),
  ('ur.ahmedali', 18, 32, 'اور انہیں دو شحصوں کی مثال سنا دو ان دونوں میں سے ایک لیے ہم نے انگور کے دو باغ تیار کیے اور ان کے گرد اگر کھجوریں لگائیں اوران دونو ں کے درمیان کھیتی بھی لگا رکھی تھی'),
  ('ur.ahmedali', 18, 33, 'دونوں باغ اپنے پھل لاتے ہیں اور پھل لانے میں کچھ کمی نہیں کرتے اور ان دونوں کے درمیان ہم نے ایک نہر بھی جاری کردی ہے'),
  ('ur.ahmedali', 18, 34, 'اور اسے پھل مل گیا پھر اس نے اپنے ساتھی سے باتیں کرتے ہوئے کہا کہ میں تجھ سے مال میں بھی زيادہ ہوں اور جماعت کے لحاظ سے بھی زیادہ معزز ہوں'),
  ('ur.ahmedali', 18, 35, 'اور اپنے باغ میں داخل ہوا ایسے حال میں کہ وہ اپنی جان پر ظلم کرنے والا تھا کہا میں نہیں خیال کرتا کہ یہ باغ کبھی برباد ہو گا'),
  ('ur.ahmedali', 18, 36, 'اورمیں قیامت کو ہونے والی خیال نہیں کرتا اور البتہ اگر میں اپنے رب کے ہاں لوٹایا بھی گیا تو اس سے بھی بہتر جگہ پاؤں گا'),
  ('ur.ahmedali', 18, 37, 'اسے اس کے ساتھی نے گفتگو کے دوران میں نے کہا کیا تو اس کا منکر ہو گیا ہے جس نے تجھے مٹی سے پھر نطفہ سے بنایا پھر تجھے پورا آدمی بنا دیا'),
  ('ur.ahmedali', 18, 38, 'لیکن میرا تو الله ہی رب ہے اور میں اس کے ساتھ کسی کو شریک نہیں کروں گا'),
  ('ur.ahmedali', 18, 39, 'اور جب تو اپنے باغ میں آیا تھا تو نے کیوں نہ کہا جو الله چاہے تو ہوتا ہے اور الله کی مدد کے سوا کوئی طاقت نہیں اگر تو مجھے دیکھتا ہے کہ میں تجھ سے مال اور اولاد میں کم ہوں'),
  ('ur.ahmedali', 18, 40, 'پھر امید ہے کہ میرا رب مجھے تیرے باغ سے بہتر دے اور اس پر لو کا ایک جھونکا آسمان سے بھیج دے پھر وہ چٹیل میدان ہوجائے'),
  ('ur.ahmedali', 18, 41, 'یا اس کا پانی خشک ہوجائے پھر تو اسے ہرگز تلاش کرکے نہ لاسکے گا'),
  ('ur.ahmedali', 18, 42, 'اور اس کا پھل سمیٹ لیا گیا پھر وہ اپنے ہاتھ ہی ملتا رہ گیا اس پر جو اس نے اس باغ میں خرچ کیا تھا اور وہ اپنی چھتریوں پر گرا پڑا تھا اور کہا کاش میں اپنے رب کے ساتھ کسی کو شریک نہیں کرتا'),
  ('ur.ahmedali', 18, 43, 'اور اس کی کوئی جماعت نہ تھی جو الله کےسوا اس کی مدد کرتے اور نہ وہ خود ہی بدلہ لے سکا'),
  ('ur.ahmedali', 18, 44, 'یہاں سب اختیار الله سچے ہی کا ہے اسی کا انعام بہتر ہے اور اسی کا دیاہوا بدلہ اچھا ہے'),
  ('ur.ahmedali', 18, 45, 'اور ان سے دنیا کی زندگی کی مثال بیان کرو مثل ایک پانی کے ہے جسے ہم نے آسمان سے برسایا پھر زمین کی روئیدگی پانی کے ساتھ مل گئی پھر وہ ریزہ ریز ہ ہو گئی کہ اسے ہوا ئیں اڑاتی پھرتی ہیں اور الله ہر چیز پر قدرت رکنے والا ہے'),
  ('ur.ahmedali', 18, 46, 'مال اور اولاد تو دنیا کی زندگی کی رونق ہیں اور تیرے رب کے ہاں باقی رہنے والی نیکیاں ثواب اور آخرت کی امید کے لحاظ سے بہتر ہیں'),
  ('ur.ahmedali', 18, 47, 'اورجس دن ہم پہاڑوں کو چلائیں گے اور تو زمین کو صاف میدان دیکھے گا اور سب کو جمع کریں گے اور ان میں سے کسی کو بھی نہ چھوڑیں گے'),
  ('ur.ahmedali', 18, 48, 'اور سب تیرے رب کے سامنے صف باندھ کر پیش کیے جائیں گے البتہ تحقیق تم ہمارے پاس آئے ہو جیسا ہم نے تم کو پہلی بار پیدا کیا تھا بلکہ تم نے خیال کیا تھا کہ ہم تمہارے لیے کوئی وعدہ مقرر نہ کریں گے'),
  ('ur.ahmedali', 18, 49, 'اور اعمال نامہ رکھ دیا جائے گا پھر مجرموں کو دیکھے گا اس چیز سے ڈرنے والے ہوں گے جو اس میں ہے اور کہیں گے افسوس ہم پر یہ کیسا اعمال نامہ ہے کہ اس نے کوئی چھوٹی یا بڑی بات نہیں چھوڑی مگر سب کو محفوظ کیا ہوا ہے اورجو کچھ انہوں نے کیا تھا سب کو موجود پائیں گے اور تیرا رب کسی پر ظلم نہیں کرے گا'),
  ('ur.ahmedali', 18, 50, 'اور جب ہم نے فرشتوں سے کہا آدم کو سجدہ کرو تو سوائے ابلیس کے سب نے سجدہ کیا وہ جنوں میں سے تھا سو اپنے رب کے حکم کی نافرمانی کی پھر کیا تم مجھے چھوڑ کر اسے اور اس کی اولاد کو کارساز بناتے ہو حالانکہ وہ تمہارے دشمن ہیں بے انصافوں کو برا بدل ملا'),
  ('ur.ahmedali', 18, 51, 'نہ تو آسمان اور زمین کے بناتے وقت اور نہ انہیں بناتے وقت میں نے انہیں بلایا اورمیں گمراہ کرنے والوں کو اپنا مددگار بنانے والا نہ تھا'),
  ('ur.ahmedali', 18, 52, 'اورجس دن فرمائے گا میرے شریکوں کو پکارو جنہیں تم مانتے تھے پھر وہ انہیں پکاریں گے سو وہ انہیں جواب نہیں دیں گے اور ہم نے ان کے درمیان ہلاکت کی جگہ بنا دی ہے'),
  ('ur.ahmedali', 18, 53, 'اور گناہگار آگ کو دیکھیں گے اور سمجھیں گے کہ وہ اس میں گرنے والے ہیں اور اس سے بچنے کی کوئی راہ نہ پائیں گے'),
  ('ur.ahmedali', 18, 54, 'اور البتہ تحقیق ہم نے اس قرآن میں ان لوگوں کے لیے ہر ایک مثال کو کئی طرح سے بیان کیا ہے اور انسان بڑا ہی جھگڑالو ہے'),
  ('ur.ahmedali', 18, 55, 'اور جب ان کے پاس ہدایت آئی تو انہیں ایمان لانے اور اپنے رب سے معافی مانگنے سے کوئی چیز مانع نہیں ہوئی سوائے اس کے کہ انہیں پہلی امتوں کا سا معاملہ پیش آئے یا عذاب ان کے سامنے آجائے'),
  ('ur.ahmedali', 18, 56, 'اور ہم رسولوں کو صرف خوشخبری دینے اور ڈرانے والا بنا کر بھیجتے ہیں اور کافر نا حق جھگڑا کرتے ہیں تاکہ ا س سے سچی بات کو ٹلا دیں اور انہوں نے میری آیتوں کو اور جس سے انہیں ڈرایا گیا ہے مذاق بنا لیا ہے'),
  ('ur.ahmedali', 18, 57, 'اور اس سے زیادہ ظالم کون ہے جسے اس کے رب کی آیتوں سے نصیحت کی جائے پھر ان سے منہ پھیر لے اور جو کچھ اس کے ہاتھوں نے آگے بھیجا ہے بھول جائے بے شک ہم نے ان کے دلوں پر پردے ڈال دیے ہیں کہ اسے نہ سمجھیں اور ان کے کانوں میں گرانی ہے اور اگر تو انہیں ہدایت کی طرف بلائے تو بھی وہ ہر گز کبھی راہ پر نہ آئیں گے'),
  ('ur.ahmedali', 18, 58, 'اور تیرا رب بڑا بخنشے والا رحمت والا ہے اگر ان کے کیے پر انہیں پکڑنا چاہتا تو فوراً ہی عذاب بھیج دیتا بلکہ ان کے لیے ایک معیاد مقرر ہے اس کے سوا کوئی پناہ کی جگہ نہیں پائیں گے'),
  ('ur.ahmedali', 18, 59, 'اور یہ بستیاں ہیں جنہیں ہم نے ہلک کیا ہے جب انہوں نے ظلم کیا تھا اور ہم نے ان کی ہلاکت کا بھی ایک وقت مقرر کیا تھا'),
  ('ur.ahmedali', 18, 60, 'اورجب موسیٰ نے اپنے جوان سے کہا کہ میں نہ ہٹوں گا یہاں تک کہ دو دریاؤں کے ملنے کی جگہ پر پہنچ جاؤں یا سالہا سال چلتا جاؤں'),
  ('ur.ahmedali', 18, 61, 'پھر جب وہ دو دریاؤں کے جمع ہونے کی جگہ پر پہنچے دونوں اپنی مچھلی کو بھول گئے پھر مچھلی نے دریا میں سرنگ کی طرح کا راستہ بنا لیا'),
  ('ur.ahmedali', 18, 62, 'پھر جب وہ دونوں آگے بڑھ گئے تو اپنے جوان سے کہا کہ ہمارا ناشہ لے آ۔ البتہ تحقیق ہم نے اس سفر میں تکلیف اٹھائی ہے'),
  ('ur.ahmedali', 18, 63, 'کہا کیا تو نے دیکھا جب ہم اس پتھر کے پاس ٹھرے تومیں مچھلی کو وہیں بھول آیا اور مجھے شیطان ہی نے بھلایا ہے کہ اس کا ذکر کروں اور اس نے اپنی راہ سمندر میں عجیب طرح سے بنا لی'),
  ('ur.ahmedali', 18, 64, 'کہا یہی ہے جو ہم چاہتے تھے پھر اپنے قدموں کے نشان دیکھتے ہی الٹے پھرے'),
  ('ur.ahmedali', 18, 65, 'پھر ہمارے بندوں میں سے ایک بندہ کو پایا جسے ہم نے اپنے ہاں سے رحمت دی تھی اوراسے ہم نے اپنے پاس سے ایک علم سکھایا تھا'),
  ('ur.ahmedali', 18, 66, 'اسے موسیٰ نے کہا کیا میں تیرے ساتھ رہوں اس شرط پر کہ تو مجھے سکھائے اس میں سے جو تجھے ہدایت کا طریقہ سکھایا گیا ہے'),
  ('ur.ahmedali', 18, 67, 'کہا بے شک تو میرے ساتھ ہر گز صبر نہیں کر سکے گا'),
  ('ur.ahmedali', 18, 68, 'اورتو صبر کیسے کرے گا اس بات پر جو تیری سمجھ میں نہیں آئے گی'),
  ('ur.ahmedali', 18, 69, 'کہا انشاالله تو مجھے صابر ہی پائے گا اور میں کسی بات میں بھی تیری مخالفت نہیں کروں گا'),
  ('ur.ahmedali', 18, 70, 'کہا پس اگر تو میرے ساتھ رہے تو مجھ سے کسی بات کا سوال نہ کر یہاں تک کہ میں تیرے سامنے اس کا ذکر کروں پس دونوں چلے'),
  ('ur.ahmedali', 18, 71, 'یہاں تک کہ جب کشتی میں سوار ہوئے تو اسے پھاڑ دیا کہا کیا تو نے اس لیے پھاڑا ہے کہ کشتی کے لوگوں کو غرق کر دے البتہ تو نے خطرناک بات کی ہے'),
  ('ur.ahmedali', 18, 72, 'کہا کیا میں نے تجھے نہیں کہا تھا کہ تو میرے ساتھ صبر نہیں کر سکے گا'),
  ('ur.ahmedali', 18, 73, 'کہا میرے بھول جانے پر گرفت نہ کر اورمیرے معاملہ میں سختی نہ کر'),
  ('ur.ahmedali', 18, 74, 'پھر دونوں چلے یہاں تک کہ انہیں ایک لڑکا ملا تو اسے مار ڈالا کہا تو نے ایک بے گناہ کو ناحق مار ڈالا البتہ تو نے بڑی بات کی'),
  ('ur.ahmedali', 18, 75, 'کہا کیا میں نے تجھے نہیں کہا تھا کہ تو میرے ساتھ صبر نہیں کر سکے گا'),
  ('ur.ahmedali', 18, 76, 'کہا اگراس کے بعدمیں آپ سے کسی چیز کا سوال کروں تو مجھے ساتھ نہ رکھیں آپ میری طرف سے معذوری تک پہنچ جائیں گے'),
  ('ur.ahmedali', 18, 77, 'پھر ودنوں چلے یہاں تک کہ جب ایک گاؤں والوں پر گزرے توان سے کھانا مانگا انہوں نے مہمان نوازی سے انکار کر دیا پھر انہوں نے وہاں ایک دیوار پائی جو گرنےہی والی تھی تب اسے سیدھا کر دیا کہا اگر آپ چاہتے تو اس کام پر کوئی اجرت ہی لے لیتے'),
  ('ur.ahmedali', 18, 78, 'کہا اب میرے اور تیرے درمیان جدائی ہے اب میں تجھے ان باتوں کا راز بتاتا ہوں جن پر تو صبر نہ کر سکا'),
  ('ur.ahmedali', 18, 79, 'جو کشتی تھی سو وہ محتاج لوگوں کی تھی جو دریا میں مزدوری کرتے تھے پھر میں نے اس میں عیب کر دینا چاہا اور ان کے آگے ایک بادشاہ تھا جو ہر ایک کشتی کو زبردستی پکڑ رہا تھا'),
  ('ur.ahmedali', 18, 80, 'اور رہا لڑکا سو اس کے ماں باپ ایمان دار تھے سو ہم ڈرے کہ انہیں بھی سر کشی اور کفر میں مبتلا نہ کرے'),
  ('ur.ahmedali', 18, 81, 'پھر ہم نے چاہا کہ ان کا رب اس کے بدلہ میں انہیں ایسی اولاد دے جو پاکیزگی میں اس سے بہتر اور محبت میں اس سے بڑھ کر ہو'),
  ('ur.ahmedali', 18, 82, 'اور جو دیوار تھی سو وہ اس شہر کے دو یتیم بچوں کی تھی اور اس کے نیچے ان کا خزانہ تھا اور ان کا باپ نیک آدمی تھا پس تیرے رب نے چاہا کہ وہ جوان ہو کر اپنا خزانہ تیرے رب کی مہربانی سے نکالیں اور یہ کام میں نے اپنے ارادے سے نہیں کیا یہ حقیقت ہے اس کی جس پر تو صبر نہیں کر سکا'),
  ('ur.ahmedali', 18, 83, 'اور آپ سے ذوالقرنین کا حال پوچھتے ہیں کہہ دو کہ اب میں تمہیں اس کا حال سناتا ہوں'),
  ('ur.ahmedali', 18, 84, 'ہم نے اسے زمین میں حکمرانی دی تھی اور اسے ہر طرح کا سازو سامان دیا تھا'),
  ('ur.ahmedali', 18, 85, 'تو اس نے ایک ساز و سامان تار کیا'),
  ('ur.ahmedali', 18, 86, 'یہاں تک کہ جب سورج ڈوبنے کی جگہ پہنچا تو اسے ایک گرم چشمے میں ڈوبتا ہوا پایا اور وہاں ایک قوم بھی پائی ہم نے کہااے ذوالقرنین یا انھیں سزا دے اور یا ان سے نیک سلوک کر'),
  ('ur.ahmedali', 18, 87, 'کہا جو ان میں ظالم ہے اسے تو ہم سزا ہی دیں گے پھر وہ اپنے رب کے ہاں لوٹایا جائے گا پھر وہ اسے اوربھی سخت سزا دے گا'),
  ('ur.ahmedali', 18, 88, 'اور جو کوئی ایمان لائے گا اور نیکی کرے گا تو اسے نیک بدلہ ملے گا اور ہم بھی اپنے معاملے میں اسے آسان ہی حکم دیں گے'),
  ('ur.ahmedali', 18, 89, 'پھر اس نے ایک ساز و سامان تیار کیا'),
  ('ur.ahmedali', 18, 90, 'یہاں تک کہ جب سورج نکلنے کی جگہ پہنچا تو اس نے سورج کو ایک ایسی قوم پر نکلتے ہوئے پایا کہ جس کے لیے ہم نے سورج کے ادھر کوئی آڑ نہیں رکھی تھی'),
  ('ur.ahmedali', 18, 91, 'اسی طرح ہی ہے اور اس کے حال کی پوری خبر ہمارےہی پاس ہے'),
  ('ur.ahmedali', 18, 92, 'پھر اس نے ایک ساز و سامان تیار کیا'),
  ('ur.ahmedali', 18, 93, 'یہاں تک کہ جب دو پہاڑوں کے درمیان پہنچا ان دونوں سے اس طرف ایک ایسی قوم کو دیکھا جو بات نہیں سمجھ سکتی تھی'),
  ('ur.ahmedali', 18, 94, 'انہوں نے کہا کہ اے ذوالقرنین بے شک یاجوج ماجوج اس ملک میں فساد کرنے والے ہیں پھر کیا ہم آپ کے لیے کچھ محصول مقرر کر دیں اس شرط پر کہ آپ ہمارےاور ان کے درمیان ایک دیوار بنا دیں'),
  ('ur.ahmedali', 18, 95, 'کہا جو میرے رب نے قدرت دی ہے کافی ہے سو طاقت سے میری مدد کرو کہ میں تمہارے اور ان کے درمیان ایک مضبوط دیوار بنا دوں'),
  ('ur.ahmedali', 18, 96, 'مجھے لوہے کے تختے لا دو یہاں تک کہ جب دونوں سروں کے بیچ کو برابر کر دیا تو کہا کہ دھونکو یہاں تک کہ جب اسے آگ کر دیا تو کہا کہ تم میرے پاس تانبا لاؤ تاکہ اس پر ڈال دوں'),
  ('ur.ahmedali', 18, 97, 'پھر وہ نہ اس پر چڑھ سکتے تھے اور نہ اس میں نقب لگا سکتے تھے'),
  ('ur.ahmedali', 18, 98, 'کہا یہ میرے رب کی رحمت ہے پھر جب میرے رب کا وعدہ آئے گا تو اسے ریزہ ریزہ کر دے گا اور میرے رب کا وعدہ سچا ہے'),
  ('ur.ahmedali', 18, 99, 'اور ہم چھوڑدیں گے بعض ان کے اس دن بعض میں گھسیں گے اور صورمیں پھونکا جائے گا پھر ہم ان سب کو جمع کر یں گے'),
  ('ur.ahmedali', 18, 100, 'اور ہم دوزخ کو اس دن کافروں کے سامنے پیش کریں گے'),
  ('ur.ahmedali', 18, 101, 'جن کی آنکھوں پر ہماری یاد سے پردہ پڑا ہوا تھا اور وہ سن بھی نہ سکتے تھے'),
  ('ur.ahmedali', 18, 102, 'پھر کافر کیا خیال کرتے ہیں کہ میرے سوا میرےبندوں کو اپنا کارساز بنا لیں گے بے شک ہم نے کافروں کے لیے دوزخ کو مہمانی بنایاہے'),
  ('ur.ahmedali', 18, 103, 'کہہ دو کیا میں تمہیں بتاؤں جو اعمال کے لحاظ سے بالکل خسارے میں ہیں'),
  ('ur.ahmedali', 18, 104, 'وہ جن کی ساری کوشش دنیا کی زندگی میں کھوئی گئی اور وہ خیال کرتے ہیں کہ بے شک وہ اچھے کام کر رہے ہیں'),
  ('ur.ahmedali', 18, 105, 'یہ وہی لوگ ہیں جنہوں نے اپنے رب کی نشانیوں کا اور اس کے روبرو جانے کا انکار کیا ہے پھر ان کے سارے اعمال ضائع ہو گئے سو ہم ان کے لیے قیامت کے دن کوئی وزن قائم نہیں کریں گے'),
  ('ur.ahmedali', 18, 106, 'یہ سزا ا ن کی جہنم ہے ا سلیے کہ انہوں نے کفر کیا اور میری آیتوں اور میرے رسولوں کا مذاق بنایا تھا'),
  ('ur.ahmedali', 18, 107, 'بے شک جو لوگ ایمان لائے اور اچھے کام کئے ان کی مہمانی کے لیے فردوس کے باغ ہوں گےبے شک جو لوگ ایمان لائے اور اچھےکام کئےان کی مہمانی کے لیے فردوس کے باغ ہوں گے'),
  ('ur.ahmedali', 18, 108, 'ان میں ہمیشہ رہیں گے وہاں سے جگہ بدلنی نہ چاہیں گے'),
  ('ur.ahmedali', 18, 109, 'کہہ دو اگر میرے رب کی باتیں لکھنےکے لئے سمندر سیاہی بن جائے تو میرے رب کی باتیں ختم ہونے سے پہلے سمندر ختم ہو جائے اور اگرچہ اس کی مدد کے لیے ہم ایسا ہی اور سمندر لائیں'),
  ('ur.ahmedali', 18, 110, 'کہہ دو کہ میں بھی تمہارے جیسا آدمی ہی ہوں میری طرف وحی کی جاتی ہے کہ تمہارا معبود ایک ہی معبود ہے پھر جو کوئی اپنے رب سے ملنے کی امید رکھے تو اسے چاہیئے کہ اچھے کام کرے اور اپنے رب کی عبادت میں کسی کو شریک نہ بنائے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 18, 1, 'Hamd Allah\'a mahsustur ki, kendi katından şiddetli bir baskını haber vermek ve yararlı iş yapan müminlere, içinde temelli kalacakları güzel bir mükafatı müjdelemek ve: "Allah çocuk edindi" diyenleri uyarmak için kuluna eğri bir taraf bırakmadığı dosdoğru Kitap\'ı indirmiştir.'),
  ('tr.diyanet', 18, 2, 'Hamd Allah\'a mahsustur ki, kendi katından şiddetli bir baskını haber vermek ve yararlı iş yapan müminlere, içinde temelli kalacakları güzel bir mükafatı müjdelemek ve: "Allah çocuk edindi" diyenleri uyarmak için kuluna eğri bir taraf bırakmadığı dosdoğru Kitap\'ı indirmiştir.'),
  ('tr.diyanet', 18, 3, 'Hamd Allah\'a mahsustur ki, kendi katından şiddetli bir baskını haber vermek ve yararlı iş yapan müminlere, içinde temelli kalacakları güzel bir mükafatı müjdelemek ve: "Allah çocuk edindi" diyenleri uyarmak için kuluna eğri bir taraf bırakmadığı dosdoğru Kitap\'ı indirmiştir.'),
  ('tr.diyanet', 18, 4, 'Hamd Allah\'a mahsustur ki, kendi katından şiddetli bir baskını haber vermek ve yararlı iş yapan müminlere, içinde temelli kalacakları güzel bir mükafatı müjdelemek ve: "Allah çocuk edindi" diyenleri uyarmak için kuluna eğri bir taraf bırakmadığı dosdoğru Kitap\'ı indirmiştir.'),
  ('tr.diyanet', 18, 5, 'Allah\'ın çocuk edindiğine dair ne kendilerinin ve ne de babalarının bir bilgisi vardır. Ağızlarından çıkan söz ne büyük iftiradır. Onlar yalnız ve yalnız yalan söylerler.'),
  ('tr.diyanet', 18, 6, 'Bu söze inanmayanların ardından üzülerek nerdeyse kendini mahvedeceksin!'),
  ('tr.diyanet', 18, 7, 'İnsanların hangisinin daha iyi iş işlediğini ortaya koyalım diye, yeryüzünde olan şeyleri, yeryüzünün süsü yaptık.'),
  ('tr.diyanet', 18, 8, 'Şüphesiz Biz, yeryüzünde olanları kupkuru bir toprak haline getirebiliriz.'),
  ('tr.diyanet', 18, 9, 'Yoksa sen Mağara ve Kitap ehlini şaşılacak ayetlerimizden mi zannettin?'),
  ('tr.diyanet', 18, 10, 'Birkaç genç mağaraya sığınmış: "Rabbimiz! Katından bize rahmet ver ve işimizde doğruyu göster, bizi başarılı kıl" demişlerdi.'),
  ('tr.diyanet', 18, 11, 'Mağaranın içinde onları yıllarca uyuttuk; sonra, iki taraftan hangisinin bekledikleri sonucu iyi hesaplamış olduğunu belirtmek için onları uyandırdık.'),
  ('tr.diyanet', 18, 12, 'Mağaranın içinde onları yıllarca uyuttuk; sonra, iki taraftan hangisinin bekledikleri sonucu iyi hesaplamış olduğunu belirtmek için onları uyandırdık.'),
  ('tr.diyanet', 18, 13, 'Onların olayını sana Biz gerçek olarak anlatıyoruz: Onlar Rablerine inanmış birkaç gençti. Onların hidayetlerini artırmış ve kalblerini pekiştirmiştik. Durup, şöyle demişlerdi: "Rabbimiz göklerin ve yerin Rabbidir, O\'nu bırakıp başka bir tanrıya yalvarmayız, yoksa and olsun ki, batıl söz söylemiş oluruz. Şu bizim milletimiz, Allah\'ı bırakıp O\'ndan başka tanrılar edindiler. Onların gerçek olduğuna apaçık delil getirmeleri gerekmez mi? Allah\'a karşı yalan uydurandan daha zalim kimdir?"'),
  ('tr.diyanet', 18, 14, 'Onların olayını sana Biz gerçek olarak anlatıyoruz: Onlar Rablerine inanmış birkaç gençti. Onların hidayetlerini artırmış ve kalblerini pekiştirmiştik. Durup, şöyle demişlerdi: "Rabbimiz göklerin ve yerin Rabbidir, O\'nu bırakıp başka bir tanrıya yalvarmayız, yoksa and olsun ki, batıl söz söylemiş oluruz. Şu bizim milletimiz, Allah\'ı bırakıp O\'ndan başka tanrılar edindiler. Onların gerçek olduğuna apaçık delil getirmeleri gerekmez mi? Allah\'a karşı yalan uydurandan daha zalim kimdir?"'),
  ('tr.diyanet', 18, 15, 'Onların olayını sana Biz gerçek olarak anlatıyoruz: Onlar Rablerine inanmış birkaç gençti. Onların hidayetlerini artırmış ve kalblerini pekiştirmiştik. Durup, şöyle demişlerdi: "Rabbimiz göklerin ve yerin Rabbidir, O\'nu bırakıp başka bir tanrıya yalvarmayız, yoksa and olsun ki, batıl söz söylemiş oluruz. Şu bizim milletimiz, Allah\'ı bırakıp O\'ndan başka tanrılar edindiler. Onların gerçek olduğuna apaçık delil getirmeleri gerekmez mi? Allah\'a karşı yalan uydurandan daha zalim kimdir?"'),
  ('tr.diyanet', 18, 16, 'Onlara: "Siz onlardan ve Allah\'tan başka taptıklarından ayrıldınız, bunun için mağaraya girin ki, Rabbiniz size rahmetini yaysın ve size işinizde kolaylık göstersin" denildi.'),
  ('tr.diyanet', 18, 17, 'Baksaydın, güneşin mağaralarının sağ tarafından doğup meylettiğini, sol tarafından onlara dokunmadan battığını, onların da mağaranın genişçe bir yerinde bulunduğunu görürdün. Bu, Allah\'ın mucizelerindendir; Allah\'ın doğru yola eriştirdiği kimse hak yoldadır. Kimi de saptırırsa artık ona, doğru yola götürecek bir rehber bulamazsın.'),
  ('tr.diyanet', 18, 18, 'Mağara ehli uykuda iken sen onları uyanık sanırdın. Biz onları sağa ve sola döndürürdük. Köpekleri dirseklerini eşiğe uzatmıştı. Onları görsen, için korkuyla dolar, geri dönüp kaçardın.'),
  ('tr.diyanet', 18, 19, 'Birbirlerine sorsunlar diye onları uyandırdık. İçlerinden biri: "Ne kadar kaldınız?" dedi. "Bir gün veya daha az bir müddet kaldık" dediler. "Ne kadar kaldığınızı Rabbiniz daha iyi bilir. Paranızla birinizi şehre gönderin, sakın sizi kimseye duyurmasın" dediler.'),
  ('tr.diyanet', 18, 20, '"Zira onların sizden haberi olacak olursa, ya taşlayarak öldürürler veya dinlerine döndürürler ve bu takdirde asla kurtulamazsınız."'),
  ('tr.diyanet', 18, 21, 'Böylece, Allah\'ın sözünün gerçek olduğunu ve kıyametin kopmasından şüphe edilemeyeceğini bilmeleri için, insanların onları bulmalarını sağladık. Nitekim halk, bunların hakkında çekişip duruyor: "Onların mağaralarının çevresine bir bina kurun" diyorlardı. Oysa, Rableri onları çok iyi bilir. Tartışmayı kazananlar: "Onların mağaralarının çevresinde mutlaka bir mescid kuracağız" dediler.'),
  ('tr.diyanet', 18, 22, 'Karanlığa taş atar gibi, "Mağara ehli üçtür, dördüncüleri köpekleridir" derler, yahut, "Beştir, altıncıları köpekleridir" derler, yahut "Yedidir, sekizincileri köpekleridir" derler. De ki: "Onların sayısını en iyi bilen Rabbim\'dir. Onları pek az kimseden başkası bilmez." Bunun için, onlar hakkında, bu kısaca anlatılanın dışında, kimseyle tartışma ve onlar hakkında kimseden bir şey sorma.'),
  ('tr.diyanet', 18, 23, 'Herhangi bir şey için, Allah\'ın dilemesi dışında: "Ben yarın onu yapacağım" deme. Unuttuğun zaman Rabbini an ve şöyle de: "Umulur ki, Rabbim beni doğruya daha yakın olana eriştirir."'),
  ('tr.diyanet', 18, 24, 'Herhangi bir şey için, Allah\'ın dilemesi dışında: "Ben yarın onu yapacağım" deme. Unuttuğun zaman Rabbini an ve şöyle de: "Umulur ki, Rabbim beni doğruya daha yakın olana eriştirir."'),
  ('tr.diyanet', 18, 25, 'Onlar mağaralarında üçyüz dokuz yıl kaldılar.'),
  ('tr.diyanet', 18, 26, 'De ki: "Onların ne kadar kaldıklarını en iyi Allah bilir. Göklerin ve yerin gaybı O\'na aittir. O, ne mükemmel görendir! O ne mükemmel işitendir! İnsanların O\'ndan başka dostu yoktur. O, hiç kimseyi hükümranlığa ortak kılmaz."'),
  ('tr.diyanet', 18, 27, 'Rabbinin Kitap\'ından sana vahyolunanı oku; O\'nun sözlerini değiştirecek yoktur. O\'ndan başka bir sığınılacak da bulamazsın.'),
  ('tr.diyanet', 18, 28, 'Sabah akşam Rablerinin rızasını dileyerek O\'na yalvaranlarla beraber sen de sabret. Dünya hayatının güzelliklerini isteyerek gözlerini o kimselerden ayırma. Bizi anmasını kendisine unutturduğumuz ve işinde aşırı giderek hevesine uyan kimseye uyma.'),
  ('tr.diyanet', 18, 29, 'De ki: "Gerçek Rabbinizdendir." Dileyen inansın, dileyen inkar etsin. Şüphesiz zalimler için, duvarları çepeçevre onları içine alacak bir ateş hazırlamışızdır. Onlar yardım istediklerinde, erimiş maden gibi yüzleri kavuran bir su kendilerine sunulur. Bu ne kötü bir içecek ve cehennem ne kötü bir duraktır!'),
  ('tr.diyanet', 18, 30, 'İyi hareket edenin ecrini zayi etmeyiz. Doğrusu, inanıp yararlı iş yapanlara, işte onlara, içlerinden ırmaklar akan Adn cennetleri vardır. Orada altın bilezikler takınırlar, ince ve kalın ipekliden yeşil elbiseler giyerek tahtları üzerinde otururlar. Ne güzel bir mükafat ve ne güzel yaslanacak yer!'),
  ('tr.diyanet', 18, 31, 'İyi hareket edenin ecrini zayi etmeyiz. Doğrusu, inanıp yararlı iş yapanlara, işte onlara, içlerinden ırmaklar akan Adn cennetleri vardır. Orada altın bilezikler takınırlar, ince ve kalın ipekliden yeşil elbiseler giyerek tahtları üzerinde otururlar. Ne güzel bir mükafat ve ne güzel yaslanacak yer!'),
  ('tr.diyanet', 18, 32, 'Onlara iki adamı misal olarak göster: Birine iki üzüm bağı verip, etrafını hurmalıklarla çevirmiş ve aralarında ekinler bitirmiştik.'),
  ('tr.diyanet', 18, 33, 'Her iki bahçe de ürünlerini vermişlerdi, hiçbir şeyi de eksik bırakmamışlardı. İkisinin arasından bir de ırmak akıtmıştık.'),
  ('tr.diyanet', 18, 34, 'Onun gelirleri de vardı. Bu yüzden, arkadaşiyle konuşurken: "Ben malca senden zengin, nüfusça da senden daha itibarlıyım" dedi.'),
  ('tr.diyanet', 18, 35, 'Kendisine böylece yazık ederek bahçesine girerken: "Bu bahçenin batacağını hiç zannetmem. Kıyametin kopacağını da sanmıyorum. Eğer Rabbime döndürülürsem, and olsun ki orada bundan daha iyisini bulurum" dedi.'),
  ('tr.diyanet', 18, 36, 'Kendisine böylece yazık ederek bahçesine girerken: "Bu bahçenin batacağını hiç zannetmem. Kıyametin kopacağını da sanmıyorum. Eğer Rabbime döndürülürsem, and olsun ki orada bundan daha iyisini bulurum" dedi.'),
  ('tr.diyanet', 18, 37, 'Kendisiyle konuştuğu arkadaşı ona: "Seni topraktan, sonra nutfeden yaratanı, sonunda de seni insan kılığına koyanı mı inkar ediyorsun? İşte O benim Rabbim olan Allah\'tır. Rabbime kimseyi ortak koşmam. Bahçene girdiğin zaman, her ne kadar beni kendinden mal ve nüfus bakımından daha az buluyorsan da: "Maşallah! Kuvvet ancak Allah\'a mahsustur!" demen gerekmez mi? Rabbim, senin bahçenden daha iyisini bana verebilir ve seninkinin üzerine gökten bir felaket gönderir de bahçen yerle bir olabilir. Yahut suyu çekilir bir daha da bulamazsın" dedi.'),
  ('tr.diyanet', 18, 38, 'Kendisiyle konuştuğu arkadaşı ona: "Seni topraktan, sonra nutfeden yaratanı, sonunda de seni insan kılığına koyanı mı inkar ediyorsun? İşte O benim Rabbim olan Allah\'tır. Rabbime kimseyi ortak koşmam. Bahçene girdiğin zaman, her ne kadar beni kendinden mal ve nüfus bakımından daha az buluyorsan da: "Maşallah! Kuvvet ancak Allah\'a mahsustur!" demen gerekmez mi? Rabbim, senin bahçenden daha iyisini bana verebilir ve seninkinin üzerine gökten bir felaket gönderir de bahçen yerle bir olabilir. Yahut suyu çekilir bir daha da bulamazsın" dedi.'),
  ('tr.diyanet', 18, 39, 'Kendisiyle konuştuğu arkadaşı ona: "Seni topraktan, sonra nutfeden yaratanı, sonunda de seni insan kılığına koyanı mı inkar ediyorsun? İşte O benim Rabbim olan Allah\'tır. Rabbime kimseyi ortak koşmam. Bahçene girdiğin zaman, her ne kadar beni kendinden mal ve nüfus bakımından daha az buluyorsan da: "Maşallah! Kuvvet ancak Allah\'a mahsustur!" demen gerekmez mi? Rabbim, senin bahçenden daha iyisini bana verebilir ve seninkinin üzerine gökten bir felaket gönderir de bahçen yerle bir olabilir. Yahut suyu çekilir bir daha da bulamazsın" dedi.'),
  ('tr.diyanet', 18, 40, 'Kendisiyle konuştuğu arkadaşı ona: "Seni topraktan, sonra nutfeden yaratanı, sonunda de seni insan kılığına koyanı mı inkar ediyorsun? İşte O benim Rabbim olan Allah\'tır. Rabbime kimseyi ortak koşmam. Bahçene girdiğin zaman, her ne kadar beni kendinden mal ve nüfus bakımından daha az buluyorsan da: "Maşallah! Kuvvet ancak Allah\'a mahsustur!" demen gerekmez mi? Rabbim, senin bahçenden daha iyisini bana verebilir ve seninkinin üzerine gökten bir felaket gönderir de bahçen yerle bir olabilir. Yahut suyu çekilir bir daha da bulamazsın" dedi.'),
  ('tr.diyanet', 18, 41, 'Kendisiyle konuştuğu arkadaşı ona: "Seni topraktan, sonra nutfeden yaratanı, sonunda de seni insan kılığına koyanı mı inkar ediyorsun? İşte O benim Rabbim olan Allah\'tır. Rabbime kimseyi ortak koşmam. Bahçene girdiğin zaman, her ne kadar beni kendinden mal ve nüfus bakımından daha az buluyorsan da: "Maşallah! Kuvvet ancak Allah\'a mahsustur!" demen gerekmez mi? Rabbim, senin bahçenden daha iyisini bana verebilir ve seninkinin üzerine gökten bir felaket gönderir de bahçen yerle bir olabilir. Yahut suyu çekilir bir daha da bulamazsın" dedi.'),
  ('tr.diyanet', 18, 42, 'Nitekim, ürünleri yok edildi; bağın altüst olmuş çardakları karşısında, sarfettiği emeğe içi yanarak ellerini oğuşturup "Keşke Rabbime kimseyi ortak koşmasaydım" diyordu.'),
  ('tr.diyanet', 18, 43, 'Ona, Allah\'tan başka yardım edebilecek adamları da yoktu, kendi kendini de kurtaramadı.'),
  ('tr.diyanet', 18, 44, 'İşte burada kudret ve hakimiyet, varlığı gerçek olan Allah\'ındır. Mükafatlandırma bakımından hayırlı olan da, sonuçlandırma yönünden hayırlı olan da O\'dur.'),
  ('tr.diyanet', 18, 45, 'Onlara, dünya hayatı misalinin tıpkı şöyle olduğunu anlat: Gökten indirdiğimiz su ile yeryüzünde yetişen bitkiler birbirine karışır, ama sonunda rüzgarın savuracağı çerçöpe döner. Allah her şeyin üstünde bir kudrete sahip olandır.'),
  ('tr.diyanet', 18, 46, 'Mal ve oğullar, dünya hayatının süsüdür. Ama baki kalacak yararlı işler, sevab olarak da, emel olarak da, Rabbinin katında daha hayırlıdır.'),
  ('tr.diyanet', 18, 47, 'Bir gün dağları yürütürüz de yeri dümdüz görürsün. Hiçbirini bırakmaksızın diriltip bir araya toplarız.'),
  ('tr.diyanet', 18, 48, 'Dizi dizi Rabbine sunulduklarında onlara: "And olsun ki, sizi ilk defa yarattığımız gibi Bize geldiniz. Sizi bir yere toplamak için söz vermediğimizi iddia etmiştiniz değil mi?" denir.'),
  ('tr.diyanet', 18, 49, 'Amel defteri ortaya konunca, suçluların, onda yazılı olanlardan korktuklarını görürsün, "Vah bize, eyvah bize! Bu defter nasıl olmuş da küçük büyük bir şey bırakmadan hepsini saymış!" derler. İşlediklerini hazır bulurlar. Rabbin kimseye haksızlık etmez.'),
  ('tr.diyanet', 18, 50, 'Meleklere: "Adem\'e secde edin" demiştik. İblis\'ten başka hepsi secde etmişti. O, cinlerden idi. Rabbinin buyruğu dışına çıktı. Ey insanoğulları! Siz Beni bırakıp onu ve soyunu dost mu ediniyorsunuz? Halbuki onlar size düşmandır. Kendilerine yazık edenler için bu ne kötü değişmedir!'),
  ('tr.diyanet', 18, 51, 'Oysa Ben onları ne göklerin ve yerin yaratılmasında ve ne de kendilerinin yaratılmasında hazır bulundurdum. Saptıranları hiçbir işte asla yardımcı da edinmedim.'),
  ('tr.diyanet', 18, 52, 'O gün Allah: "Bana ortak olduklarını iddia ettiklerinize seslenin" der. Onları çağırırlar, fakat hiçbirisi onların çağrılarına gelmez. Aralarına bir cehennem deresi koyarız.'),
  ('tr.diyanet', 18, 53, 'Suçlular ateşi görürler ve ona düşeceklerini anlarlar, fakat ondan kaçacak yer bulamazlar.'),
  ('tr.diyanet', 18, 54, 'And olsun ki, Biz bu Kuran\'da insanlara türlü türlü misali gösterip açıkladık. İnsanın en çok yaptığı iş tartışmadır.'),
  ('tr.diyanet', 18, 55, 'İnsanlara doğruluk rehberi gelmişken, onları inanmaktan, Rablerinden mağfiret dilemekten alıkoyan öncekilere uygulananın kendilerine de uygulanmasını veya gözleri göre göre azaba uğramayı beklemeleridir.'),
  ('tr.diyanet', 18, 56, 'Biz peygamberleri ancak müjdeci ve uyarıcı olarak göndeririz. Oysa inkarcılar hakkı batılla ortadan kaldırmak için çekişirler. Ayetlerimizi ve kendilerine yapılan uyarmaları alaya alırlar.'),
  ('tr.diyanet', 18, 57, 'Rabbinin ayetleri kendisine hatırlatılmışken onlardan yüz çeviren ve önceden yaptıklarını unutan kimseden daha zalim var mıdır? Kuran\'ı anlarlar diye kalblerine örtüler, kulaklarına da ağırlık koyduk. Sen onları doğru yola çağırsan da asla doğru yolagelmezler.'),
  ('tr.diyanet', 18, 58, 'Bununla beraber, Rabbin mağfiret ve merhamet sahibidir. Eğer onları, yaptıklarından dolayı hemen hesaba çekmek isteseydi, azaba uğratmakta acele ederdi. Ama onların bir vadesi vardır. Ondan kaçıp sığınacak yer bulamazlar.'),
  ('tr.diyanet', 18, 59, 'Haksızlıklarından ötürü işte yok ettiğimiz şehirler! Onları yok etmek için bir süre tayin etmiştik.'),
  ('tr.diyanet', 18, 60, 'Musa, genç arkadaşına: "Ben iki denizin birleştiği yere ulaşmağa, yahut yıllarca yürümeye kararlıyım" demişti.'),
  ('tr.diyanet', 18, 61, 'İkisi, iki denizin birleştiği yere ulaşınca, balıklarını unutmuşlardı, balık bir delikten kayıp denizi boyladı.'),
  ('tr.diyanet', 18, 62, 'Oradan uzaklaştıklarında Musa, yanındaki gence: "Azığımızı çıkar, and olsun bu yolculuğumuzda yorgun düştük" dedi.'),
  ('tr.diyanet', 18, 63, 'O da: "Bak sen! Kayalığa vardığımızda balığı unutmuştum. Bana onu hatırlamamı unutturan ancak şeytandır. Balık şaşılacak şekilde denizde yolunu tutup gitmiş" dedi.'),
  ('tr.diyanet', 18, 64, 'Musa: "İstediğimiz zaten buydu" dedi. Hemen geldikleri yoldan izleri üzerinde geri döndüler.'),
  ('tr.diyanet', 18, 65, 'Bu arada ikisi katımızdan kendisine bir rahmet verdiğimiz ve kendisine ilim öğrettiğimiz kullarımızdan birini buldular.'),
  ('tr.diyanet', 18, 66, 'Musa ona: "Sana öğretileni bana hayra götüren bir bilgi olarak öğretmen için peşinden gelebilir miyim?" dedi.'),
  ('tr.diyanet', 18, 67, 'O: "Sen doğrusu benim yaptıklarıma dayanamazsın, bilgice kavrayamadığın bir şeye nasıl dayanabilirsin?" dedi.'),
  ('tr.diyanet', 18, 68, 'Musa: "İnşallah sabrettiğimi göreceksin, sana hiçbir işte baş kaldırmayacağım" dedi.'),
  ('tr.diyanet', 18, 69, 'O da: "O halde, bana uyacaksan, ben sana anlatmadıkça herhangi bir şey hakkında bana soru sormayacaksın" dedi.'),
  ('tr.diyanet', 18, 70, 'O da: "O halde, bana uyacaksan, ben sana anlatmadıkça herhangi bir şey hakkında bana soru sormayacaksın" dedi.'),
  ('tr.diyanet', 18, 71, 'Bunun üzerine kalkıp gittiler; sonunda bir gemiye bindiklerinde, o gemiyi deliverdi; Musa: "Gemiyi içindekileri boğmak için mi deldin? Doğrusu şaşılacak bir şey yaptın" dedi.'),
  ('tr.diyanet', 18, 72, 'Musa\'ya: "Ben sana yaptığım işlere dayanamazsın demedim mi?" dedi.'),
  ('tr.diyanet', 18, 73, 'Musa: "Unuttuğum için bana çıkışma, gücümün yetmediği şeyden beni sorumlu tutma" dedi.'),
  ('tr.diyanet', 18, 74, 'Yine gittiler; sonunda bir erkek çocuğa rastladılar, o hemen onu öldürdü. Musa: "Bir cana karşılık olmaksızın masum bir cana mı kıydın? Doğrusu pek kötü bir şey yaptın" dedi.'),
  ('tr.diyanet', 18, 75, 'O: "Ben sana, yaptığım işlere dayanamazsın demedim mi?" dedi.'),
  ('tr.diyanet', 18, 76, 'Musa: "Bundan sonra sana bir şey sorarsam bana arkadaş olma, o zaman benim tarafımdan mazur sayılırsın" dedi.'),
  ('tr.diyanet', 18, 77, 'Yine yola koyuldular; sonunda vardıkları bir kasaba halkından yiyecek istediler. Kasaba halkı, bu ikisini misafir etmek istemedi. İkisi, şehrin içinde yıkılmağa yüz tutan bir duvar gördüler, Musa\'nın arkadaşı onu doğrultuverdi; Musa: "Dileseydin buna karşı bir ücret alabilirdin" dedi.'),
  ('tr.diyanet', 18, 78, 'O şöyle söyledi: "İşte bu, seninle benim ayrılmamızı gerektiriyor; dayanamadığın işlerin yorumunu sana anlatacağım"'),
  ('tr.diyanet', 18, 79, '"Gemi, denizde çalışan birkaç yoksula aitti; onu kusurlu kılmak istedim, çünkü peşlerinde her sağlam gemiye zorla el koyan bir hükümdar vardı."'),
  ('tr.diyanet', 18, 80, '"Oğlana gelince; onun ana babası inanmış kimselerdi. Çocuğun onları azdırmasından ve inkara sürüklemesinden korkmuştuk.'),
  ('tr.diyanet', 18, 81, 'Rablerinin o çocuktan daha temiz ve onlara daha çok merhamet eden birini vermesini istedik."'),
  ('tr.diyanet', 18, 82, '"Duvar ise, şehirde iki yetim erkek çocuğa aitti. Duvarın altında onların bir hazinesi vardı; babaları da iyi bir kimseydi. Rabbin onların erginlik çağına ulaşmasını ve Rabbinden bir rahmet olarak hazinelerini çıkarmalarını istedi. Ben bunları kendiliğimden yapmadım. İşte dayanamadığın işlerin içyüzleri budur."'),
  ('tr.diyanet', 18, 83, 'Sana Zülkarneyn\'i sorarlar, "Onu size anlatacağım" de.'),
  ('tr.diyanet', 18, 84, 'Doğrusu biz onu yeryüzüne yerleştirmiş ve her şeyin yolunu ona öğretmiştik.'),
  ('tr.diyanet', 18, 85, 'O da bir yol tuttu.'),
  ('tr.diyanet', 18, 86, 'Sonunda güneşin battığı yere ulaşınca onu, kara balçıklı bir suda batıyor gördü. Orada bir millete rastladı. "Zülkarneyn! Onlara azap da edebilirsin, iyi muamelede de bulunabilirsin" dedik.'),
  ('tr.diyanet', 18, 87, '"Haksızlık yapana azap edeceğiz, sonra Rabbine döndürülür, onu görülmemiş bir azaba uğratır; ama inanıp yararlı iş işleyene, mükafat olarak güzel şeyler vardır, ona buyruğumuzdan kolay olanı söyleriz" dedi.'),
  ('tr.diyanet', 18, 88, '"Haksızlık yapana azap edeceğiz, sonra Rabbine döndürülür, onu görülmemiş bir azaba uğratır; ama inanıp yararlı iş işleyene, mükafat olarak güzel şeyler vardır, ona buyruğumuzdan kolay olanı söyleriz" dedi.'),
  ('tr.diyanet', 18, 89, 'Sonra yine bir yol tuttu.'),
  ('tr.diyanet', 18, 90, 'Sonunda güneşin doğduğu yere ulaşınca, güneşi, kendilerini elbise, bina gibi şeylerle örtmediğimiz bir millet üzerine doğuyor buldu.'),
  ('tr.diyanet', 18, 91, 'İşte bunun gibi, onun yaptıklarının hepsini baştanbaşa biliyorduk.'),
  ('tr.diyanet', 18, 92, 'Sonra yine bir yol tuttu.'),
  ('tr.diyanet', 18, 93, 'Sonunda, iki dağın arasına varınca, orada nerdeyse hiç laf anlamayan bir millete rastladı.'),
  ('tr.diyanet', 18, 94, 'Dediler ki: Zülkarneyn! Doğrusu Yecüc ve Mecüc bu ülkede bozgunculuk yapıyorlar. Bizimle onların arasına bir sed yapman için sana bir vergi verelim mi?'),
  ('tr.diyanet', 18, 95, '"Rabbimin bana verdikleri sizinkinden daha iyidir. Bana gücünüzle yardım edin de sizinle onların arasına sağlam bir sed yapayım. Bana demir kütleleri getirin" dedi. Bunlar iki dağın arasını doldurunca: "Körükleyin" dedi. Demirler akkor haline gelince; "Bana erimiş bakır getirin de üzerine dökeyim" dedi.'),
  ('tr.diyanet', 18, 96, '"Rabbimin bana verdikleri sizinkinden daha iyidir. Bana gücünüzle yardım edin de sizinle onların arasına sağlam bir sed yapayım. Bana demir kütleleri getirin" dedi. Bunlar iki dağın arasını doldurunca: "Körükleyin" dedi. Demirler akkor haline gelince; "Bana erimiş bakır getirin de üzerine dökeyim" dedi.'),
  ('tr.diyanet', 18, 97, 'Artık Yecüc ve Mecüc onu ne aşabildiler ve ne de delip geçebildiler.'),
  ('tr.diyanet', 18, 98, 'Zülkarneyn: "İşte bu, Rabbimin bir rahmetidir. Rabbimin tayin ettiği zaman gelince onu yerle bir eder; Rabbimin verdiği söz gerçektir" dedi.'),
  ('tr.diyanet', 18, 99, 'Biz o gün onları bırakırız, dalgalar halinde birbirlerine girerler. Sura üflenince hepsini bir araya toplarız.'),
  ('tr.diyanet', 18, 100, 'Gözleri bizim öğüdümüze karşı kapalı olan ve öfkelerinden onu dinlemeye tahammül edemeyen kafirlere o gün cehennemi öyle bir gösteririz ki!'),
  ('tr.diyanet', 18, 101, 'Gözleri bizim öğüdümüze karşı kapalı olan ve öfkelerinden onu dinlemeye tahammül edemeyen kafirlere o gün cehennemi öyle bir gösteririz ki!'),
  ('tr.diyanet', 18, 102, 'İnkar edenler, Beni bırakıp da kullarımı dost edinmelerini yeterli mi sandılar? Doğrusu biz cehennemi inkarcılara konak olarak hazırladık.'),
  ('tr.diyanet', 18, 103, '"Size, amelce en çok kayıpta bulunanları haber verelim mi?" de.'),
  ('tr.diyanet', 18, 104, 'Dünya hayatında, çalışmaları boşa gitmiştir, oysa onlar güzel iş yaptıklarını sanıyorlardı.'),
  ('tr.diyanet', 18, 105, 'Bunlar, Rablerinin ayetlerini ve O\'na kavuşmayı inkar edenlerdir. Bu yüzden işleri boşa gitmiştir. Kıyamet günü Biz onlara değer vermeyeceğiz.'),
  ('tr.diyanet', 18, 106, 'İşte onların cezası; inkarlarına, peygamberlerimi ve ayetlerimi alaya almalarına karşılık olarak, cehennemdir.'),
  ('tr.diyanet', 18, 107, 'Ama inanıp yararlı iş işleyenlerin konakları Firdevs cennetleridir.'),
  ('tr.diyanet', 18, 108, 'Orada temelli kalırlar, başka bir yere gitmek istemezler.'),
  ('tr.diyanet', 18, 109, 'De ki: "Rabbimin sözlerini yazmak için denizler mürekkep olsa ve bir o kadarını da katsak, Rabbimin sözleri tükenmeden denizler tükenirdi."'),
  ('tr.diyanet', 18, 110, 'De ki: "Ben de ancak sizin gibi bir insanım; ancak bana tanrınızın tek bir Tanrı olduğu vahyolunuyor. Rabbine kavuşmayı uman kimse yararlı iş işleşin ve Rabbine kullukta hiç ortak koşmasın."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 18, 1, 'Segala puji bagi Allah yang telah menurunkan kepada hamba-Nya Al Kitab (Al-Quran) dan Dia tidak mengadakan kebengkokan di dalamnya;'),
  ('id.indonesian', 18, 2, 'sebagai bimbingan yang lurus, untuk memperingatkan siksaan yang sangat pedih dari sisi Allah dan memberi berita gembira kepada orang-orang yang beriman, yang mengerjakan amal saleh, bahwa mereka akan mendapat pembalasan yang baik,'),
  ('id.indonesian', 18, 3, 'mereka kekal di dalamnya untuk selama-lamanya.'),
  ('id.indonesian', 18, 4, 'Dan untuk memperingatkan kepada orang-orang yang berkata: "Allah mengambil seorang anak".'),
  ('id.indonesian', 18, 5, 'Mereka sekali-kali tidak mempunyai pengetahuan tentang hal itu, begitu pula nenek moyang mereka. Alangkah buruknya kata-kata yang keluar dari mulut mereka; mereka tidak mengatakan (sesuatu) kecuali dusta.'),
  ('id.indonesian', 18, 6, 'Maka (apakah) barangkali kamu akan membunuh dirimu karena bersedih hati setelah mereka berpaling, sekiranya mereka tidak beriman kepada keterangan ini (Al-Quran).'),
  ('id.indonesian', 18, 7, 'Sesungguhnya Kami telah menjadikan apa yang di bumi sebagai perhiasan baginya, agar Kami menguji mereka siapakah di antara mereka yang terbaik perbuatannya.'),
  ('id.indonesian', 18, 8, 'Dan sesungguhnya Kami benar-benar akan menjadikan (pula) apa yang di atasnya menjadi tanah rata lagi tandus.'),
  ('id.indonesian', 18, 9, 'Atau kamu mengira bahwa orang-orang yang mendiami gua dan (yang mempunyai) raqim itu, mereka termasuk tanda-tanda kekuasaan Kami yang mengherankan?'),
  ('id.indonesian', 18, 10, '(Ingatlah) tatkala para pemuda itu mencari tempat berlindung ke dalam gua, lalu mereka berdoa: "Wahai Tuhan kami, berikanlah rahmat kepada kami dari sisi-Mu dan sempurnakanlah bagi kami petunjuk yang lurus dalam urusan kami (ini)".'),
  ('id.indonesian', 18, 11, 'Maka Kami tutup telinga mereka beberapa tahun dalam gua itu,'),
  ('id.indonesian', 18, 12, 'Kemudian Kami bangunkan mereka, agar Kami mengetahui manakah di antara kedua golongan itu] yang lebih tepat dalam menghitung berapa lama mereka tinggal (dalam gua itu).'),
  ('id.indonesian', 18, 13, 'Kami kisahkan kepadamu (Muhammad) cerita ini dengan benar. Sesungguhnya mereka adalah pemuda-pemuda yang beriman kepada Tuhan mereka, dan Kami tambah pula untuk mereka petunjuk.'),
  ('id.indonesian', 18, 14, 'Dan Kami meneguhkan hati mereka diwaktu mereka berdiri, lalu mereka pun berkata, "Tuhan kami adalah Tuhan seluruh langit dan bumi; kami sekali-kali tidak menyeru Tuhan selain Dia, sesungguhnya kami kalau demikian telah mengucapkan perkataan yang amat jauh dari kebenaran".'),
  ('id.indonesian', 18, 15, 'Kaum kami ini telah menjadikan selain Dia sebagai tuhan-tuhan (untuk disembah). Mengapa mereka tidak mengemukakan alasan yang terang (tentang kepercayaan mereka)? Siapakah yang lebih zalim daripada orang-orang yang mengada-adakan kebohongan terhadap Allah?'),
  ('id.indonesian', 18, 16, 'Dan apabila kamu meninggalkan mereka dan apa yang mereka sembah selain Allah, maka carilah tempat berlindung ke dalam gua itu, niscaya Tuhanmu akan melimpahkan sebagian rahmat-Nya kepadamu dan menyediakan sesuatu yang berguna bagimu dalam urusan kamu.'),
  ('id.indonesian', 18, 17, 'Dan kamu akan melihat matahari ketika terbit, condong dari gua mereka ke sebelah kanan, dan bila matahari terbenam menjauhi mereka ke sebelah kiri sedang mereka berada dalam tempat yang luas dalam gua itu. Itu adalah sebagian dari tanda-tanda (kebesaran) Allah. Barangsiapa yang diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk; dan barangsiapa yang disesatkan-Nya, maka kamu tidak akan mendapatkan seorang pemimpinpun yang dapat memberi petunjuk kepadanya.'),
  ('id.indonesian', 18, 18, 'Dan kamu mengira mereka itu bangun, padahal mereka tidur; Dan kami balik-balikkan mereka ke kanan dan ke kiri, sedang anjing mereka mengunjurkan kedua lengannya di muka pintu gua. Dan jika kamu menyaksikan mereka tentulah kamu akan berpaling dari mereka dengan melarikan diri dan tentulah (hati) kamu akan dipenuhi oleh ketakutan terhadap mereka.'),
  ('id.indonesian', 18, 19, 'Dan demikianlah Kami bangunkan mereka agar mereka saling bertanya di antara mereka sendiri. Berkatalah salah seorang di antara mereka: Sudah berapa lamakah kamu berada (disini?)". Mereka menjawab: "Kita berada (disini) sehari atau setengah hari". Berkata (yang lain lagi): "Tuhan kamu lebih mengetahui berapa lamanya kamu berada (di sini). Maka suruhlah salah seorang di antara kamu untuk pergi ke kota dengan membawa uang perakmu ini, dan hendaklah dia lihat manakah makanan yang lebih baik, maka hendaklah ia membawa makanan itu untukmu, dan hendaklah ia berlaku lemah-lembut dan janganlah sekali-kali menceritakan halmu kepada seorangpun.'),
  ('id.indonesian', 18, 20, 'Sesungguhnya jika mereka dapat mengetahui tempatmu, niscaya mereka akan melempar kamu dengan batu, atau memaksamu kembali kepada agama mereka, dan jika demikian niscaya kamu tidak akan beruntung selama lamanya".'),
  ('id.indonesian', 18, 21, 'Dan demikian (pula) Kami mempertemukan (manusia) dengan mereka, agar manusia itu mengetahui, bahwa janji Allah itu benar, dan bahwa kedatangan hari kiamat tidak ada keraguan padanya. Ketika orang-orang itu berselisih tentang urusan mereka, orang-orang itu berkata: "Dirikan sebuah bangunan di atas (gua) mereka, Tuhan mereka lebih mengetahui tentang mereka". Orang-orang yang berkuasa atas urusan mereka berkata: "Sesungguhnya kami akan mendirikan sebuah rumah peribadatan di atasnya".'),
  ('id.indonesian', 18, 22, 'Nanti (ada orang yang akan) mengatakan (jumlah mereka) adalah tiga orang yang keempat adalah anjingnya, dan (yang lain) mengatakan: "(jumlah mereka) adalah lima orang yang keenam adalah anjing nya", sebagai terkaan terhadap barang yang gaib; dan (yang lain lagi) mengatakan: "(jumlah mereka) tujuh orang, yang ke delapan adalah anjingnya". Katakanlah: "Tuhanku lebih mengetahui jumlah mereka; tidak ada orang yang mengetahui (bilangan) mereka kecuali sedikit". Karena itu janganlah kamu (Muhammad) bertengkar tentang hal mereka, kecuali pertengkaran lahir saja dan jangan kamu menanyakan tentang mereka (pemuda-pemuda itu) kepada seorangpun di antara mereka.'),
  ('id.indonesian', 18, 23, 'Dan jangan sekali-kali kamu mengatakan tentang sesuatu: "Sesungguhnya aku akan mengerjakan ini besok pagi,'),
  ('id.indonesian', 18, 24, 'kecuali (dengan menyebut): "Insya Allah". Dan ingatlah kepada Tuhanmu jika kamu lupa dan katakanlah: "Mudah-mudahan Tuhanku akan memberiku petunjuk kepada yang lebih dekat kebenarannya dari pada ini".'),
  ('id.indonesian', 18, 25, 'Dan mereka tinggal dalam gua mereka tiga ratus tahun dan ditambah sembilan tahun (lagi).'),
  ('id.indonesian', 18, 26, 'Katakanlah: "Allah lebih mengetahui berapa lamanya mereka tinggal (di gua); kepunyaan-Nya-lah semua yang tersembunyi di langit dan di bumi. Alangkah terang penglihatan-Nya dan alangkah tajam pendengaran-Nya; tak ada seorang pelindungpun bagi mereka selain dari pada-Nya; dan Dia tidak mengambil seorangpun menjadi sekutu-Nya dalam menetapkan keputusan".'),
  ('id.indonesian', 18, 27, 'Dan bacakanlah apa yang diwahyukan kepadamu, yaitu kitab Tuhanmu (Al Quran). Tidak ada (seorangpun) yang dapat merubah kalimat-kalimat-Nya. Dan kamu tidak akan dapat menemukan tempat berlindung selain dari pada-Nya.'),
  ('id.indonesian', 18, 28, 'Dan bersabarlah kamu bersama-sama dengan orang-orang yang menyeru Tuhannya di pagi dan senja hari dengan mengharap keridhaan-Nya; dan janganlah kedua matamu berpaling dari mereka (karena) mengharapkan perhiasan dunia ini; dan janganlah kamu mengikuti orang yang hatinya telah Kami lalaikan dari mengingati Kami, serta menuruti hawa nafsunya dan adalah keadaannya itu melewati batas.'),
  ('id.indonesian', 18, 29, 'Dan katakanlah: "Kebenaran itu datangnya dari Tuhanmu; maka barangsiapa yang ingin (beriman) hendaklah ia beriman, dan barangsiapa yang ingin (kafir) biarlah ia kafir". Sesungguhnya Kami telah sediakan bagi orang orang zalim itu neraka, yang gejolaknya mengepung mereka. Dan jika mereka meminta minum, niscaya mereka akan diberi minum dengan air seperti besi yang mendidih yang menghanguskan muka. Itulah minuman yang paling buruk dan tempat istirahat yang paling jelek.'),
  ('id.indonesian', 18, 30, 'Sesunggunya mereka yang beriman dan beramal saleh, tentulah Kami tidak akan menyia-nyiakan pahala orang-orang yang mengerjakan amalan(nya) dengan yang baik.'),
  ('id.indonesian', 18, 31, 'Mereka itulah (orang-orang yang) bagi mereka surga \'Adn, mengalir sungai-sungai di bawahnya; dalam surga itu mereka dihiasi dengan gelang mas dan mereka memakai pakaian hijau dari sutera halus dan sutera tebal, sedang mereka duduk sambil bersandar di atas dipan-dipan yang indah. Itulah pahala yang sebaik-baiknya, dan tempat istirahat yang indah;'),
  ('id.indonesian', 18, 32, 'Dan berikanlah kepada mereka sebuah perumpamaan dua orang laki-laki, Kami jadikan bagi seorang di antara keduanya (yang kafir) dua buah kebun anggur dan kami kelilingi kedua kebun itu dengan pohon-pohon korma dan di antara kedua kebun itu Kami buatkan ladang.'),
  ('id.indonesian', 18, 33, 'Kedua buah kebun itu menghasilkan buahnya, dan kebun itu tiada kurang buahnya sedikitpun, dan Kami alirkan sungai di celah-celah kedua kebun itu,'),
  ('id.indonesian', 18, 34, 'dan dia mempunyai kekayaan besar, maka ia berkata kepada kawannya (yang mukmin) ketika bercakap-cakap dengan dia: "Hartaku lebih banyak dari pada hartamu dan pengikut-pengikutku lebih kuat"'),
  ('id.indonesian', 18, 35, 'Dan dia memasuki kebunnya sedang dia zalim terhadap dirinya sendiri; ia berkata: "Aku kira kebun ini tidak akan binasa selama-lamanya,'),
  ('id.indonesian', 18, 36, 'dan aku tidak mengira hari kiamat itu akan datang, dan jika sekiranya aku kembalikan kepada Tuhanku, pasti aku akan mendapat tempat kembali yang lebih baik dari pada kebun-kebun itu".'),
  ('id.indonesian', 18, 37, 'Kawannya (yang mukmin) berkata kepadanya -- sedang dia bercakap-cakap dengannya: "Apakah kamu kafir kepada (Tuhan) yang menciptakan kamu dari tanah, kemudian dari setetes air mani, lalu Dia menjadikan kamu seorang laki-laki yang sempurna?'),
  ('id.indonesian', 18, 38, 'Tetapi aku (percaya bahwa): Dialah Allah, Tuhanku, dan aku tidak mempersekutukan seorangpun dengan Tuhanku.'),
  ('id.indonesian', 18, 39, 'Dan mengapa kamu tidak mengatakan waktu kamu memasuki kebunmu "maasyaallaah, laa quwwata illaa billaah (sungguh atas kehendak Allah semua ini terwujud, tiada kekuatan kecuali dengan pertolongan Allah). Sekiranya kamu anggap aku lebih sedikit darimu dalam hal harta dan keturunan,'),
  ('id.indonesian', 18, 40, 'maka mudah-mudahan Tuhanku, akan memberi kepadaku (kebun) yang lebih baik dari pada kebunmu (ini); dan mudah-mudahan Dia mengirimkan ketentuan (petir) dari langit kepada kebunmu; hingga (kebun itu) menjadi tanah yang licin;'),
  ('id.indonesian', 18, 41, 'atau airnya menjadi surut ke dalam tanah, maka sekali-kali kamu tidak dapat menemukannya lagi".'),
  ('id.indonesian', 18, 42, 'Dan harta kekayaannya dibinasakan; lalu ia membulak-balikkan kedua tangannya (tanda menyesal) terhadap apa yang ia telah belanjakan untuk itu, sedang pohon anggur itu roboh bersama para-paranya dan dia berkata: "Aduhai kiranya dulu aku tidak mempersekutukan seorangpun dengan Tuhanku".'),
  ('id.indonesian', 18, 43, 'Dan tidak ada bagi dia segolonganpun yang akan menolongnya selain Allah; dan sekali-kali ia tidak dapat membela dirinya.'),
  ('id.indonesian', 18, 44, 'Di sana pertolongan itu hanya dari Allah Yang Hak. Dia adalah sebaik-baik Pemberi pahala dan sebaik-baik Pemberi balasan.'),
  ('id.indonesian', 18, 45, 'Dan berilah perumpamaan kepada mereka (manusia), kehidupan dunia sebagai air hujan yang Kami turunkan dari langit, maka menjadi subur karenanya tumbuh-tumbuhan di muka bumi, kemudian tumbuh-tumbuhan itu menjadi kering yang diterbangkan oleh angin. Dan adalah Allah, Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 18, 46, 'Harta dan anak-anak adalah perhiasan kehidupan dunia tetapi amalan-amalan yang kekal lagi saleh adalah lebih baik pahalanya di sisi Tuhanmu serta lebih baik untuk menjadi harapan.'),
  ('id.indonesian', 18, 47, 'Dan (ingatlah) akan hari (yang ketika itu) Kami perjalankan gunung-gunung dan kamu akan dapat melihat bumi itu datar dan Kami kumpulkan seluruh manusia, dan tidak kami tinggalkan seorangpun dari mereka.'),
  ('id.indonesian', 18, 48, 'Dan mereka akan dibawa ke hadapan Tuhanmu dengan berbaris. Sesungguhnya kamu datang kepada Kami, sebagaimana Kami menciptakan kamu pada kali yang pertama; bahkan kamu mengatakan bahwa Kami sekali-kali tidak akan menetapkan bagi kamu waktu (memenuhi) perjanjian.'),
  ('id.indonesian', 18, 49, 'Dan diletakkanlah kitab, lalu kamu akan melihat orang-orang bersalah ketakutan terhadap apa yang (tertulis) di dalamnya, dan mereka berkata: "Aduhai celaka kami, kitab apakah ini yang tidak meninggalkan yang kecil dan tidak (pula) yang besar, melainkan ia mencatat semuanya; dan mereka dapati apa yang telah mereka kerjakan ada (tertulis). Dan Tuhanmu tidak menganiaya seorang juapun".'),
  ('id.indonesian', 18, 50, 'Dan (ingatlah) ketika Kami berfirman kepada para malaikat: "Sujudlah kamu kepada Adam, maka sujudlah mereka kecuali Iblis. Dia adalah dari golongan jin, maka ia mendurhakai perintah Tuhannya. Patutkah kamu mengambil dia dan turanan-turunannya sebagai pemimpin selain daripada-Ku, sedang mereka adalah musuhmu? Amat buruklah iblis itu sebagai pengganti (dari Allah) bagi orang-orang yang zalim.'),
  ('id.indonesian', 18, 51, 'Aku tidak menghadirkan mereka (iblis dan anak cucunya) untuk menyaksikan penciptaan langit dan bumi dan tidak (pula) penciptaan diri mereka sendiri; dan tidaklah Aku mengambil orang-orang yang menyesatkan itu sebagai penolong.'),
  ('id.indonesian', 18, 52, 'Dan (ingatlah) akan hari (yang ketika itu) Dia berfirman: "Serulah olehmu sekalian sekutu-sekutu-Ku yang kamu katakan itu". Mereka lalu memanggilnya tetapi sekutu-sekutu itu tidak membalas seruan mereka dan Kami adakan untuk mereka tempat kebinasaan (neraka).'),
  ('id.indonesian', 18, 53, 'Dan orang-orang yang berdosa melihat neraka, maka mereka meyakini, bahwa mereka akan jatuh ke dalamnya dan mereka tidak menemukan tempat berpaling dari padanya.'),
  ('id.indonesian', 18, 54, 'Dan sesungguhnya Kami telah mengulang-ulangi bagi manusia dalam Al Quran ini bermacam-macam perumpamaan. Dan manusia adalah makhluk yang paling banyak membantah.'),
  ('id.indonesian', 18, 55, 'Dam tidak ada sesuatupun yang menghalangi manusia dari beriman, ketika petunjuk telah datang kepada mereka, dan dari memohon ampun kepada Tuhannya, kecuali (keinginan menanti) datangnya hukum (Allah yang telah berlalu pada) umat-umat yang dahulu atau datangnya azab atas mereka dengan nyata.'),
  ('id.indonesian', 18, 56, 'Dan tidaklah Kami mengutus rasul-rasul hanyalah sebagai pembawa berita gembira dan sebagai pemberi peringatan; tetapi orang-orang yang kafir membantah dengan yang batil agar dengan demikian mereka dapat melenyap kan yang hak, dan mereka menganggap ayat-ayat kami dan peringatan-peringatan terhadap mereka sebagai olok-olokan.'),
  ('id.indonesian', 18, 57, 'Dan siapakah yang lebih zalim dari pada orang yang telah diperingatkan dengan ayat-ayat Tuhannya lalu dia berpaling dari padanya dan melupakan apa yang telah dikerjakan oleh kedua tangannya? Sesungguhnya Kami telah meletakkan tutupan di atas hati mereka, (sehingga mereka tidak) memahaminya, dan (Kami letakkan pula) sumbatan di telinga mereka; dan kendatipun kamu menyeru mereka kepada petunjuk, niscaya mereka tidak akan mendapat petunjuk selama-lamanya.'),
  ('id.indonesian', 18, 58, 'Dan Tuhanmulah yang Maha Pengampun, lagi mempunyai rahmat. Jika Dia mengazab mereka karena perbuatan mereka, tentu Dia akan menyegerakan azab bagi mereka. Tetapi bagi mereka ada waktu yang tertentu (untuk mendapat azab) yang mereka sekali-kali tidak akan menemukan tempat berlindung dari padanya.'),
  ('id.indonesian', 18, 59, 'Dan (penduduk) negeri telah Kami binasakan ketika mereka berbuat zalim, dan telah Kami tetapkan waktu tertentu bagi kebinasaan mereka.'),
  ('id.indonesian', 18, 60, 'Dan (ingatlah) ketika Musa berkata kepada muridnya: "Aku tidak akan berhenti (berjalan) sebelum sampai ke pertemuan dua buah lautan; atau aku akan berjalan sampai bertahun-tahun".'),
  ('id.indonesian', 18, 61, 'Maka tatkala mereka sampai ke pertemuan dua buah laut itu, mereka lalai akan ikannya, lalu ikan itu melompat mengambil jalannya ke laut itu.'),
  ('id.indonesian', 18, 62, 'Maka tatkala mereka berjalan lebih jauh, berkatalah Musa kepada muridnya: "Bawalah kemari makanan kita; sesungguhnya kita telah merasa letih karena perjalanan kita ini".'),
  ('id.indonesian', 18, 63, 'Muridnya menjawab: "Tahukah kamu tatkala kita mencari tempat berlindung di batu tadi, maka sesungguhnya aku lupa (menceritakan tentang) ikan itu dan tidak adalah yang melupakan aku untuk menceritakannya kecuali syaitan dan ikan itu mengambil jalannya ke laut dengan cara yang aneh sekali".'),
  ('id.indonesian', 18, 64, 'Musa berkata: "Itulah (tempat) yang kita cari". Lalu keduanya kembali, mengikuti jejak mereka semula.'),
  ('id.indonesian', 18, 65, 'Lalu mereka bertemu dengan seorang hamba di antara hamba-hamba Kami, yang telah Kami berikan kepadanya rahmat dari sisi Kami, dan yang telah Kami ajarkan kepadanya ilmu dari sisi Kami.'),
  ('id.indonesian', 18, 66, 'Musa berkata kepada Khidhr: "Bolehkah aku mengikutimu supaya kamu mengajarkan kepadaku ilmu yang benar di antara ilmu-ilmu yang telah diajarkan kepadamu?"'),
  ('id.indonesian', 18, 67, 'Dia menjawab: "Sesungguhnya kamu sekali-kali tidak akan sanggup sabar bersama aku.'),
  ('id.indonesian', 18, 68, 'Dan bagaimana kamu dapat sabar atas sesuatu, yang kamu belum mempunyai pengetahuan yang cukup tentang hal itu?"'),
  ('id.indonesian', 18, 69, 'Musa berkata: "Insya Allah kamu akan mendapati aku sebagai orang yang sabar, dan aku tidak akan menentangmu dalam sesuatu urusanpun".'),
  ('id.indonesian', 18, 70, 'Dia berkata: "Jika kamu mengikutiku, maka janganlah kamu menanyakan kepadaku tentang sesuatu apapun, sampai aku sendiri menerangkannya kepadamu".'),
  ('id.indonesian', 18, 71, 'Maka berjalanlah keduanya, hingga tatkala keduanya menaiki perahu lalu Khidhr melobanginya. Musa berkata: "Mengapa kamu melobangi perahu itu akibatnya kamu menenggelamkan penumpangnya?" Sesungguhnya kamu telah berbuat sesuatu kesalahan yang besar.'),
  ('id.indonesian', 18, 72, 'Dia (Khidhr) berkata: "Bukankah aku telah berkata: "Sesungguhnya kamu sekali-kali tidak akan sabar bersama dengan aku".'),
  ('id.indonesian', 18, 73, 'Musa berkata: "Janganlah kamu menghukum aku karena kelupaanku dan janganlah kamu membebani aku dengan sesuatu kesulitan dalam urusanku".'),
  ('id.indonesian', 18, 74, 'Maka berjalanlah keduanya; hingga tatkala keduanya berjumpa dengan seorang anak, maka Khidhr membunuhnya. Musa berkata: "Mengapa kamu membunuh jiwa yang bersih, bukan karena dia membunuh orang lain? Sesungguhnya kamu telah melakukan suatu yang mungkar".'),
  ('id.indonesian', 18, 75, 'Khidhr berkata: "Bukankah sudah kukatakan kepadamu, bahwa sesungguhnya kamu tidak akan dapat sabar bersamaku?"'),
  ('id.indonesian', 18, 76, 'Musa berkata: "Jika aku bertanya kepadamu tentang sesuatu sesudah (kali) ini, maka janganlah kamu memperbolehkan aku menyertaimu, sesungguhnya kamu sudah cukup memberikan uzur padaku".'),
  ('id.indonesian', 18, 77, 'Maka keduanya berjalan; hingga tatkala keduanya sampai kepada penduduk suatu negeri, mereka minta dijamu kepada penduduk negeri itu, tetapi penduduk negeri itu tidak mau menjamu mereka, kemudian keduanya mendapatkan dalam negeri itu dinding rumah yang hampir roboh, maka Khidhr menegakkan dinding itu. Musa berkata: "Jikalau kamu mau, niscaya kamu mengambil upah untuk itu".'),
  ('id.indonesian', 18, 78, 'Khidhr berkata: "Inilah perpisahan antara aku dengan kamu; kelak akan kuberitahukan kepadamu tujuan perbuatan-perbuatan yang kamu tidak dapat sabar terhadapnya.'),
  ('id.indonesian', 18, 79, 'Adapun bahtera itu adalah kepunyaan orang-orang miskin yang bekerja di laut, dan aku bertujuan merusakkan bahtera itu, karena di hadapan mereka ada seorang raja yang merampas tiap-tiap bahtera.'),
  ('id.indonesian', 18, 80, 'Dan adapun anak muda itu, maka keduanya adalah orang-orang mukmin, dan kami khawatir bahwa dia akan mendorong kedua orang tuanya itu kepada kesesatan dan kekafiran.'),
  ('id.indonesian', 18, 81, 'Dan kami menghendaki, supaya Tuhan mereka mengganti bagi mereka dengan anak lain yang lebih baik kesuciannya dari anaknya itu dan lebih dalam kasih sayangnya (kepada ibu bapaknya).'),
  ('id.indonesian', 18, 82, 'Adapun dinding rumah adalah kepunyaan dua orang anak yatim di kota itu, dan di bawahnya ada harta benda simpanan bagi mereka berdua, sedang ayahnya adalah seorang yang saleh, maka Tuhanmu menghendaki agar supaya mereka sampai kepada kedewasaannya dan mengeluarkan simpanannya itu, sebagai rahmat dari Tuhanmu; dan bukanlah aku melakukannya itu menurut kemauanku sendiri. Demikian itu adalah tujuan perbuatan-perbuatan yang kamu tidak dapat sabar terhadapnya".'),
  ('id.indonesian', 18, 83, 'Mereka akan bertanya kepadamu (Muhammad) tentang Dzulkarnain. Katakanlah: "Aku akan bacakan kepadamu cerita tantangnya".'),
  ('id.indonesian', 18, 84, 'Sesungguhnya Kami telah memberi kekuasaan kepadanya di (muka) bumi, dan Kami telah memberikan kepadanya jalan (untuk mencapai) segala sesuatu,'),
  ('id.indonesian', 18, 85, 'maka diapun menempuh suatu jalan.'),
  ('id.indonesian', 18, 86, 'Hingga apabila dia telah sampai ketempat terbenam matahari, dia melihat matahari terbenam di dalam laut yang berlumpur hitam, dan dia mendapati di situ segolongan umat. Kami berkata: "Hai Dzulkarnain, kamu boleh menyiksa atau boleh berbuat kebaikan terhadap mereka.'),
  ('id.indonesian', 18, 87, 'Berkata Dzulkarnain: "Adapun orang yang aniaya, maka kami kelak akan mengazabnya, kemudian dia kembalikan kepada Tuhannya, lalu Tuhan mengazabnya dengan azab yang tidak ada taranya.'),
  ('id.indonesian', 18, 88, 'Adapun orang-orang yang beriman dan beramal saleh, maka baginya pahala yang terbaik sebagai balasan, dan akan kami titahkan kepadanya (perintah) yang mudah dari perintah-perintah kami".'),
  ('id.indonesian', 18, 89, 'Kemudian dia menempuh jalan (yang lain).'),
  ('id.indonesian', 18, 90, 'Hingga apabila dia telah sampai ke tempat terbit matahari (sebelah Timur) dia mendapati matahari itu menyinari segolongan umat yang Kami tidak menjadikan bagi mereka sesuatu yang melindunginya dari (cahaya) matahari itu,'),
  ('id.indonesian', 18, 91, 'demikianlah. dan sesungguhnya ilmu Kami meliputi segala apa yang ada padanya.'),
  ('id.indonesian', 18, 92, 'Kemudian dia menempuh suatu jalan (yang lain lagi).'),
  ('id.indonesian', 18, 93, 'Hingga apabila dia telah sampai di antara dua buah gunung, dia mendapati di hadapan kedua bukit itu suatu kaum yang hampir tidak mengerti pembicaraan.'),
  ('id.indonesian', 18, 94, 'Mereka berkata: "Hai Dzulkarnain, sesungguhnya Ya\'juj dan Ma\'juj itu orang-orang yang membuat kerusakan di muka bumi, maka dapatkah kami memberikan sesuatu pembayaran kepadamu, supaya kamu membuat dinding antara kami dan mereka?"'),
  ('id.indonesian', 18, 95, 'Dzulkarnain berkata: "Apa yang telah dikuasakan oleh Tuhanku kepadaku terhadapnya adalah lebih baik, maka tolonglah aku dengan kekuatan (manusia dan alat-alat), agar aku membuatkan dinding antara kamu dan mereka,'),
  ('id.indonesian', 18, 96, 'berilah aku potongan-potongan besi". Hingga apabila besi itu telah sama rata dengan kedua (puncak) gunung itu, berkatalah Dzulkarnain: "Tiuplah (api itu)". Hingga apabila besi itu sudah menjadi (merah seperti) api, diapun berkata: "Berilah aku tembaga (yang mendidih) agar aku kutuangkan ke atas besi panas itu".'),
  ('id.indonesian', 18, 97, 'Maka mereka tidak bisa mendakinya dan mereka tidak bisa (pula) melobanginya.'),
  ('id.indonesian', 18, 98, 'Dzulkarnain berkata: "Ini (dinding) adalah rahmat dari Tuhanku, maka apabila sudah datang janji Tuhanku, Dia akan menjadikannya hancur luluh; dan janji Tuhanku itu adalah benar".'),
  ('id.indonesian', 18, 99, 'Kami biarkan mereka di hari itu bercampur aduk antara satu dengan yang lain, kemudian ditiup lagi sangkakala, lalu Kami kumpulkan mereka itu semuanya,'),
  ('id.indonesian', 18, 100, 'dan Kami nampakkan Jahannam pada hari itu kepada orang-orang kafir dengan jelas,'),
  ('id.indonesian', 18, 101, 'yaitu orang-orang yang matanya dalam keadaan tertutup dari memperhatikan tanda-tanda kebesaran-Ku, dan adalah mereka tidak sanggup mendengar.'),
  ('id.indonesian', 18, 102, 'maka apakah orang-orang kafir menyangka bahwa mereka (dapat) mengambil hamba-hamba-Ku menjadi penolong selain Aku? Sesungguhnya Kami telah menyediakan neraka Jahannam tempat tinggal bagi orang-orang kafir.'),
  ('id.indonesian', 18, 103, 'Katakanlah: "Apakah akan Kami beritahukan kepadamu tentang orang-orang yang paling merugi perbuatannya?"'),
  ('id.indonesian', 18, 104, 'Yaitu orang-orang yang telah sia-sia perbuatannya dalam kehidupan dunia ini, sedangkan mereka menyangka bahwa mereka berbuat sebaik-baiknya.'),
  ('id.indonesian', 18, 105, 'Mereka itu orang-orang yang telah kufur terhadap ayat-ayat Tuhan mereka dan (kufur terhadap) perjumpaan dengan Dia, maka hapuslah amalan-amalan mereka, dan Kami tidak mengadakan suatu penilaian bagi (amalan) mereka pada hari kiamat.'),
  ('id.indonesian', 18, 106, 'Demikianlah balasan mereka itu neraka Jahannam, disebabkan kekafiran mereka dan disebabkan mereka menjadikan ayat-ayat-Ku dan rasul-rasul-Ku sebagai olok-olok.'),
  ('id.indonesian', 18, 107, 'Sesungguhnya orang-orang yang beriman dan beramal saleh, bagi mereka adalah surga Firdaus menjadi tempat tinggal,'),
  ('id.indonesian', 18, 108, 'mereka kekal di dalamnya, mereka tidak ingin berpindah dari padanya.'),
  ('id.indonesian', 18, 109, 'Katakanlah: Sekiranya lautan menjadi tinta untuk (menulis) kalimat-kalimat Tuhanku, sungguh habislah lautan itu sebelum habis (ditulis) kalimat-kalimat Tuhanku, meskipun Kami datangkan tambahan sebanyak itu (pula)".'),
  ('id.indonesian', 18, 110, 'Katakanlah: Sesungguhnya aku ini manusia biasa seperti kamu, yang diwahyukan kepadaku: "Bahwa sesungguhnya Tuhan kamu itu adalah Tuhan yang Esa". Barangsiapa mengharap perjumpaan dengan Tuhannya, maka hendaklah ia mengerjakan amal yang saleh dan janganlah ia mempersekutukan seorangpun dalam beribadat kepada Tuhannya".')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 19, 1, 'Kaf, Ha, Ya, \'Ayn, Sad.'),
  ('en.sahih', 19, 2, '[This is] a mention of the mercy of your Lord to His servant Zechariah'),
  ('en.sahih', 19, 3, 'When he called to his Lord a private supplication.'),
  ('en.sahih', 19, 4, 'He said, "My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy.'),
  ('en.sahih', 19, 5, 'And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir'),
  ('en.sahih', 19, 6, 'Who will inherit me and inherit from the family of Jacob. And make him, my Lord, pleasing [to You]."'),
  ('en.sahih', 19, 7, '[He was told], "O Zechariah, indeed We give you good tidings of a boy whose name will be John. We have not assigned to any before [this] name."'),
  ('en.sahih', 19, 8, 'He said, "My Lord, how will I have a boy when my wife has been barren and I have reached extreme old age?"'),
  ('en.sahih', 19, 9, '[An angel] said, "Thus [it will be]; your Lord says, \'It is easy for Me, for I created you before, while you were nothing.\' "'),
  ('en.sahih', 19, 10, '[Zechariah] said, "My Lord, make for me a sign." He said, "Your sign is that you will not speak to the people for three nights, [being] sound."'),
  ('en.sahih', 19, 11, 'So he came out to his people from the prayer chamber and signaled to them to exalt [Allah] in the morning and afternoon.'),
  ('en.sahih', 19, 12, '[Allah] said, "O John, take the Scripture with determination." And We gave him judgement [while yet] a boy'),
  ('en.sahih', 19, 13, 'And affection from Us and purity, and he was fearing of Allah'),
  ('en.sahih', 19, 14, 'And dutiful to his parents, and he was not a disobedient tyrant.'),
  ('en.sahih', 19, 15, 'And peace be upon him the day he was born and the day he dies and the day he is raised alive.'),
  ('en.sahih', 19, 16, 'And mention, [O Muhammad], in the Book [the story of] Mary, when she withdrew from her family to a place toward the east.'),
  ('en.sahih', 19, 17, 'And she took, in seclusion from them, a screen. Then We sent to her Our Angel, and he represented himself to her as a well-proportioned man.'),
  ('en.sahih', 19, 18, 'She said, "Indeed, I seek refuge in the Most Merciful from you, [so leave me], if you should be fearing of Allah."'),
  ('en.sahih', 19, 19, 'He said, "I am only the messenger of your Lord to give you [news of] a pure boy."'),
  ('en.sahih', 19, 20, 'She said, "How can I have a boy while no man has touched me and I have not been unchaste?"'),
  ('en.sahih', 19, 21, 'He said, "Thus [it will be]; your Lord says, \'It is easy for Me, and We will make him a sign to the people and a mercy from Us. And it is a matter [already] decreed.\' "'),
  ('en.sahih', 19, 22, 'So she conceived him, and she withdrew with him to a remote place.'),
  ('en.sahih', 19, 23, 'And the pains of childbirth drove her to the trunk of a palm tree. She said, "Oh, I wish I had died before this and was in oblivion, forgotten."'),
  ('en.sahih', 19, 24, 'But he called her from below her, "Do not grieve; your Lord has provided beneath you a stream.'),
  ('en.sahih', 19, 25, 'And shake toward you the trunk of the palm tree; it will drop upon you ripe, fresh dates.'),
  ('en.sahih', 19, 26, 'So eat and drink and be contented. And if you see from among humanity anyone, say, \'Indeed, I have vowed to the Most Merciful abstention, so I will not speak today to [any] man.\' "'),
  ('en.sahih', 19, 27, 'Then she brought him to her people, carrying him. They said, "O Mary, you have certainly done a thing unprecedented.'),
  ('en.sahih', 19, 28, 'O sister of Aaron, your father was not a man of evil, nor was your mother unchaste."'),
  ('en.sahih', 19, 29, 'So she pointed to him. They said, "How can we speak to one who is in the cradle a child?"'),
  ('en.sahih', 19, 30, '[Jesus] said, "Indeed, I am the servant of Allah. He has given me the Scripture and made me a prophet.'),
  ('en.sahih', 19, 31, 'And He has made me blessed wherever I am and has enjoined upon me prayer and zakah as long as I remain alive'),
  ('en.sahih', 19, 32, 'And [made me] dutiful to my mother, and He has not made me a wretched tyrant.'),
  ('en.sahih', 19, 33, 'And peace is on me the day I was born and the day I will die and the day I am raised alive."'),
  ('en.sahih', 19, 34, 'That is Jesus, the son of Mary - the word of truth about which they are in dispute.'),
  ('en.sahih', 19, 35, 'It is not [befitting] for Allah to take a son; exalted is He! When He decrees an affair, He only says to it, "Be," and it is.'),
  ('en.sahih', 19, 36, '[Jesus said], "And indeed, Allah is my Lord and your Lord, so worship Him. That is a straight path."'),
  ('en.sahih', 19, 37, 'Then the factions differed [concerning Jesus] from among them, so woe to those who disbelieved - from the scene of a tremendous Day.'),
  ('en.sahih', 19, 38, 'How [clearly] they will hear and see the Day they come to Us, but the wrongdoers today are in clear error.'),
  ('en.sahih', 19, 39, 'And warn them, [O Muhammad], of the Day of Regret, when the matter will be concluded; and [yet], they are in [a state of] heedlessness, and they do not believe.'),
  ('en.sahih', 19, 40, 'Indeed, it is We who will inherit the earth and whoever is on it, and to Us they will be returned.'),
  ('en.sahih', 19, 41, 'And mention in the Book [the story of] Abraham. Indeed, he was a man of truth and a prophet.'),
  ('en.sahih', 19, 42, '[Mention] when he said to his father, "O my father, why do you worship that which does not hear and does not see and will not benefit you at all?'),
  ('en.sahih', 19, 43, 'O my father, indeed there has come to me of knowledge that which has not come to you, so follow me; I will guide you to an even path.'),
  ('en.sahih', 19, 44, 'O my father, do not worship Satan. Indeed Satan has ever been, to the Most Merciful, disobedient.'),
  ('en.sahih', 19, 45, 'O my father, indeed I fear that there will touch you a punishment from the Most Merciful so you would be to Satan a companion [in Hellfire]."'),
  ('en.sahih', 19, 46, '[His father] said, "Have you no desire for my gods, O Abraham? If you do not desist, I will surely stone you, so avoid me a prolonged time."'),
  ('en.sahih', 19, 47, '[Abraham] said, "Peace will be upon you. I will ask forgiveness for you of my Lord. Indeed, He is ever gracious to me.'),
  ('en.sahih', 19, 48, 'And I will leave you and those you invoke other than Allah and will invoke my Lord. I expect that I will not be in invocation to my Lord unhappy."'),
  ('en.sahih', 19, 49, 'So when he had left them and those they worshipped other than Allah, We gave him Isaac and Jacob, and each [of them] We made a prophet.'),
  ('en.sahih', 19, 50, 'And We gave them of Our mercy, and we made for them a reputation of high honor.'),
  ('en.sahih', 19, 51, 'And mention in the Book, Moses. Indeed, he was chosen, and he was a messenger and a prophet.'),
  ('en.sahih', 19, 52, 'And We called him from the side of the mount at [his] right and brought him near, confiding [to him].'),
  ('en.sahih', 19, 53, 'And We gave him out of Our mercy his brother Aaron as a prophet.'),
  ('en.sahih', 19, 54, 'And mention in the Book, Ishmael. Indeed, he was true to his promise, and he was a messenger and a prophet.'),
  ('en.sahih', 19, 55, 'And he used to enjoin on his people prayer and zakah and was to his Lord pleasing.'),
  ('en.sahih', 19, 56, 'And mention in the Book, Idrees. Indeed, he was a man of truth and a prophet.'),
  ('en.sahih', 19, 57, 'And We raised him to a high station.'),
  ('en.sahih', 19, 58, 'Those were the ones upon whom Allah bestowed favor from among the prophets of the descendants of Adam and of those We carried [in the ship] with Noah, and of the descendants of Abraham and Israel, and of those whom We guided and chose. When the verses of the Most Merciful were recited to them, they fell in prostration and weeping.'),
  ('en.sahih', 19, 59, 'But there came after them successors who neglected prayer and pursued desires; so they are going to meet evil -'),
  ('en.sahih', 19, 60, 'Except those who repent, believe and do righteousness; for those will enter Paradise and will not be wronged at all.'),
  ('en.sahih', 19, 61, '[Therein are] gardens of perpetual residence which the Most Merciful has promised His servants in the unseen. Indeed, His promise has ever been coming.'),
  ('en.sahih', 19, 62, 'They will not hear therein any ill speech - only [greetings of] peace - and they will have their provision therein, morning and afternoon.'),
  ('en.sahih', 19, 63, 'That is Paradise, which We give as inheritance to those of Our servants who were fearing of Allah.'),
  ('en.sahih', 19, 64, '[Gabriel said], "And we [angels] descend not except by the order of your Lord. To Him belongs that before us and that behind us and what is in between. And never is your Lord forgetful -'),
  ('en.sahih', 19, 65, 'Lord of the heavens and the earth and whatever is between them - so worship Him and have patience for His worship. Do you know of any similarity to Him?"'),
  ('en.sahih', 19, 66, 'And the disbeliever says, "When I have died, am I going to be brought forth alive?"'),
  ('en.sahih', 19, 67, 'Does man not remember that We created him before, while he was nothing?'),
  ('en.sahih', 19, 68, 'So by your Lord, We will surely gather them and the devils; then We will bring them to be present around Hell upon their knees.'),
  ('en.sahih', 19, 69, 'Then We will surely extract from every sect those of them who were worst against the Most Merciful in insolence.'),
  ('en.sahih', 19, 70, 'Then, surely it is We who are most knowing of those most worthy of burning therein.'),
  ('en.sahih', 19, 71, 'And there is none of you except he will come to it. This is upon your Lord an inevitability decreed.'),
  ('en.sahih', 19, 72, 'Then We will save those who feared Allah and leave the wrongdoers within it, on their knees.'),
  ('en.sahih', 19, 73, 'And when Our verses are recited to them as clear evidences, those who disbelieve say to those who believe, "Which of [our] two parties is best in position and best in association?"'),
  ('en.sahih', 19, 74, 'And how many a generation have We destroyed before them who were better in possessions and [outward] appearance?'),
  ('en.sahih', 19, 75, 'Say, "Whoever is in error - let the Most Merciful extend for him an extension [in wealth and time] until, when they see that which they were promised - either punishment [in this world] or the Hour [of resurrection] - they will come to know who is worst in position and weaker in soldiers."'),
  ('en.sahih', 19, 76, 'And Allah increases those who were guided, in guidance, and the enduring good deeds are better to your Lord for reward and better for recourse.'),
  ('en.sahih', 19, 77, 'Then, have you seen he who disbelieved in Our verses and said, "I will surely be given wealth and children [in the next life]?"'),
  ('en.sahih', 19, 78, 'Has he looked into the unseen, or has he taken from the Most Merciful a promise?'),
  ('en.sahih', 19, 79, 'No! We will record what he says and extend for him from the punishment extensively.'),
  ('en.sahih', 19, 80, 'And We will inherit him [in] what he mentions, and he will come to Us alone.'),
  ('en.sahih', 19, 81, 'And they have taken besides Allah [false] deities that they would be for them [a source of] honor.'),
  ('en.sahih', 19, 82, 'No! Those "gods" will deny their worship of them and will be against them opponents [on the Day of Judgement].'),
  ('en.sahih', 19, 83, 'Do you not see that We have sent the devils upon the disbelievers, inciting them to [evil] with [constant] incitement?'),
  ('en.sahih', 19, 84, 'So be not impatient over them. We only count out to them a [limited] number.'),
  ('en.sahih', 19, 85, 'On the Day We will gather the righteous to the Most Merciful as a delegation'),
  ('en.sahih', 19, 86, 'And will drive the criminals to Hell in thirst'),
  ('en.sahih', 19, 87, 'None will have [power of] intercession except he who had taken from the Most Merciful a covenant.'),
  ('en.sahih', 19, 88, 'And they say, "The Most Merciful has taken [for Himself] a son."'),
  ('en.sahih', 19, 89, 'You have done an atrocious thing.'),
  ('en.sahih', 19, 90, 'The heavens almost rupture therefrom and the earth splits open and the mountains collapse in devastation'),
  ('en.sahih', 19, 91, 'That they attribute to the Most Merciful a son.'),
  ('en.sahih', 19, 92, 'And it is not appropriate for the Most Merciful that He should take a son.'),
  ('en.sahih', 19, 93, 'There is no one in the heavens and earth but that he comes to the Most Merciful as a servant.'),
  ('en.sahih', 19, 94, 'He has enumerated them and counted them a [full] counting.'),
  ('en.sahih', 19, 95, 'And all of them are coming to Him on the Day of Resurrection alone.'),
  ('en.sahih', 19, 96, 'Indeed, those who have believed and done righteous deeds - the Most Merciful will appoint for them affection.'),
  ('en.sahih', 19, 97, 'So, [O Muhammad], We have only made Qur\'an easy in the Arabic language that you may give good tidings thereby to the righteous and warn thereby a hostile people.'),
  ('en.sahih', 19, 98, 'And how many have We destroyed before them of generations? Do you perceive of them anyone or hear from them a sound?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 19, 1, 'কাফ-হা-ইয়া-আইন-সাদ'),
  ('bn.bengali', 19, 2, 'এটা আপনার পালনকর্তার অনুগ্রহের বিবরণ তাঁর বান্দা যাকারিয়ার প্রতি।'),
  ('bn.bengali', 19, 3, 'যখন সে তাঁর পালনকর্তাকে আহবান করেছিল নিভৃতে।'),
  ('bn.bengali', 19, 4, 'সে বললঃ হে আমার পালনকর্তা আমার অস্থি বয়স-ভারাবনত হয়েছে; বার্ধক্যে মস্তক সুশুভ্র হয়েছে; হে আমার পালনকর্তা! আপনাকে ডেকে আমি কখনও বিফলমনোরথ হইনি।'),
  ('bn.bengali', 19, 5, 'আমি ভয় করি আমার পর আমার স্বগোত্রকে এবং আমার স্ত্রী বন্ধ্যা; কাজেই আপনি নিজের পক্ষ থেকে আমাকে এক জন কর্তব্য পালনকারী দান করুন।'),
  ('bn.bengali', 19, 6, 'সে আমার স্থলাভিষিক্ত হবে ইয়াকুব বংশের এবং হে আমার পালনকর্তা, তাকে করুন সন্তোষজনক।'),
  ('bn.bengali', 19, 7, 'হে যাকারিয়া, আমি তোমাকে এক পুত্রের সুসংবাদ দিচ্ছি, তার নাম হবে ইয়াহইয়া। ইতিপূর্বে এই নামে আমি কারও নাম করণ করিনি।'),
  ('bn.bengali', 19, 8, 'সে বললঃ হে আমার পালনকর্তা কেমন করে আমার পুত্র হবে অথচ আমার স্ত্রী যে বন্ধ্যা, আর আমিও যে বার্ধক্যের শেষ প্রান্তে উপনীত।'),
  ('bn.bengali', 19, 9, 'তিনি বললেনঃ এমনিতেই হবে। তোমার পালনকর্তা বলে দিয়েছেনঃ এটা আমার পক্ষে সহজ। আমি তো পুর্বে তোমাকে সৃষ্টি করেছি এবং তুমি কিছুই ছিলে না।'),
  ('bn.bengali', 19, 10, 'সে বললঃ হে আমার পালনকর্তা, আমাকে একটি নির্দশন দিন। তিনি বললেন তোমার নিদর্শন এই যে, তুমি সুস্থ অবস্থায় তিন দিন মানুষের সাথে কথাবার্তা বলবে না।'),
  ('bn.bengali', 19, 11, 'অতঃপর সে কক্ষ থেকে বের হয়ে তার সম্প্রদায়ের কাছে এল এবং ইঙ্গিতে তাদেরকে সকাল সন্ধ্যায় আল্লাহকে স্মরণ করতে বললঃ'),
  ('bn.bengali', 19, 12, 'হে ইয়াহইয়া দৃঢ়তার সাথে এই গ্রন্থ ধারণ কর। আমি তাকে শৈশবেই বিচারবুদ্ধি দান করেছিলাম।'),
  ('bn.bengali', 19, 13, 'এবং নিজের পক্ষ থেকে আগ্রহ ও পবিত্রতা দিয়েছি। সে ছিল পরহেযগার।'),
  ('bn.bengali', 19, 14, 'পিতা-মাতার অনুগত এবং সে উদ্ধত, নাফরমান ছিল না।'),
  ('bn.bengali', 19, 15, 'তার প্রতি শান্তি-যেদিন সে জন্মগ্রহণ করে এবং যেদিন মৃত্যুবরণ করবে এবং যেদিন জীবিতাবস্থায় পুনরুত্থিত হবে।'),
  ('bn.bengali', 19, 16, 'এই কিতাবে মারইয়ামের কথা বর্ণনা করুন, যখন সে তার পরিবারের লোকজন থেকে পৃথক হয়ে পূর্বদিকে এক স্থানে আশ্রয় নিল।'),
  ('bn.bengali', 19, 17, 'অতঃপর তাদের থেকে নিজেকে আড়াল করার জন্যে সে পর্দা করলো। অতঃপর আমি তার কাছে আমার রূহ প্রেরণ করলাম, সে তার নিকট পুর্ণ মানবাকৃতিতে আত্নপ্রকাশ করল।'),
  ('bn.bengali', 19, 18, 'মারইয়াম বললঃ আমি তোমা থেকে দয়াময়ের আশ্রয় প্রার্থনা করি যদি তুমি আল্লাহভীরু হও।'),
  ('bn.bengali', 19, 19, 'সে বললঃ আমি তো শুধু তোমার পালনকর্তা প্রেরিত, যাতে তোমাকে এক পবিত্র পুত্র দান করে যাব।'),
  ('bn.bengali', 19, 20, 'মরিইয়াম বললঃ কিরূপে আমার পুত্র হবে, যখন কোন মানব আমাকে স্পর্শ করেনি এবং আমি ব্যভিচারিণীও কখনও ছিলাম না ?'),
  ('bn.bengali', 19, 21, 'সে বললঃ এমনিতেই হবে। তোমার পালনকর্তা বলেছেন, এটা আমার জন্যে সহজ সাধ্য এবং আমি তাকে মানুষের জন্যে একটি নিদর্শন ও আমার পক্ষ থেকে অনুগ্রহ স্বরূপ করতে চাই। এটা তো এক স্থিরীকৃত ব্যাপার।'),
  ('bn.bengali', 19, 22, 'অতঃপর তিনি গর্ভে সন্তান ধারণ করলেন এবং তৎসহ এক দূরবর্তী স্থানে চলে গেলেন।'),
  ('bn.bengali', 19, 23, 'প্রসব বেদনা তাঁকে এক খেজুর বৃক্ষ-মূলে আশ্রয় নিতে বাধ্য করল। তিনি বললেনঃ হায়, আমি যদি কোনরূপে এর পূর্বে মরে যেতাম এবং মানুষের স্মৃতি থেকে বিলুপ্ত হয়ে, যেতাম!'),
  ('bn.bengali', 19, 24, 'অতঃপর ফেরেশতা তাকে নিম্নদিক থেকে আওয়ায দিলেন যে, তুমি দুঃখ করো না। তোমার পালনকর্তা তোমার পায়ের তলায় একটি নহর জারি করেছেন।'),
  ('bn.bengali', 19, 25, 'আর তুমি নিজের দিকে খেজুর গাছের কান্ডে নাড়া দাও, তা থেকে তোমার উপর সুপক্ক খেজুর পতিত হবে।'),
  ('bn.bengali', 19, 26, 'যখন আহার কর, পান কর এবং চক্ষু শীতল কর। যদি মানুষের মধ্যে কাউকে তুমি দেখ, তবে বলে দিওঃ আমি আল্লাহর উদ্দেশে রোযা মানত করছি। সুতরাং আজ আমি কিছুতেই কোন মানুষের সাথে কথা বলব না।'),
  ('bn.bengali', 19, 27, 'অতঃপর তিনি সন্তানকে নিয়ে তার সম্প্রদায়ের কাছে উপস্থিত হলেন। তারা বললঃ হে মারইয়াম, তুমি একটি অঘটন ঘটিয়ে বসেছ।'),
  ('bn.bengali', 19, 28, 'হে হারূণ-ভাগিনী, তোমার পিতা অসৎ ব্যক্তি ছিলেন না এবং তোমার মাতাও ছিল না ব্যভিচারিনী।'),
  ('bn.bengali', 19, 29, 'অতঃপর তিনি হাতে সন্তানের দিকে ইঙ্গিত করলেন। তারা বললঃ যে কোলের শিশু তার সাথে আমরা কেমন করে কথা বলব?'),
  ('bn.bengali', 19, 30, 'সন্তান বললঃ আমি তো আল্লাহর দাস। তিনি আমাকে কিতাব দিয়েছেন এবং আমাকে নবী করেছেন।'),
  ('bn.bengali', 19, 31, 'আমি যেখানেই থাকি, তিনি আমাকে বরকতময় করেছেন। তিনি আমাকে নির্দেশ দিয়েছেন, যতদিন জীবিত থাকি, ততদিন নামায ও যাকাত আদায় করতে।'),
  ('bn.bengali', 19, 32, 'এবং জননীর অনুগত থাকতে এবং আমাকে তিনি উদ্ধত ও হতভাগ্য করেননি।'),
  ('bn.bengali', 19, 33, 'আমার প্রতি সালাম যেদিন আমি জন্মগ্রহণ করেছি, যেদিন মৃত্যুবরণ করব এবং যেদিন পুনরুজ্জীবিত হয়ে উত্থিত হব।'),
  ('bn.bengali', 19, 34, 'এই মারইয়ামের পুত্র ঈসা। সত্যকথা, যে সম্পর্কে লোকেরা বিতর্ক করে।'),
  ('bn.bengali', 19, 35, 'আল্লাহ এমন নন যে, সন্তান গ্রহণ করবেন, তিনি পবিত্র ও মহিমাময় সত্তা, তিনি যখন কোন কাজ করা সিদ্ধান্ত করেন, তখন একথাই বলেনঃ হও এবং তা হয়ে যায়।'),
  ('bn.bengali', 19, 36, 'তিনি আরও বললেনঃ নিশ্চয় আল্লাহ আমার পালনকর্তা ও তোমাদের পালনকর্তা। অতএব, তোমরা তার এবাদত কর। এটা সরল পথ।'),
  ('bn.bengali', 19, 37, 'অতঃপর তাদের মধ্যে দলগুলো পৃথক পৃথক পথ অবলম্বন করল। সুতরাং মহাদিবস আগমনকালে কাফেরদের জন্যে ধবংস।'),
  ('bn.bengali', 19, 38, 'সেদিন তারা কি চমৎকার শুনবে এবং দেখবে, যেদিন তারা আমার কাছে আগমন করবে। কিন্তু আজ জালেমরা প্রকাশ্য বিভ্রান্তিতে রয়েছে।'),
  ('bn.bengali', 19, 39, 'আপনি তাদেরকে পরিতাপের দিবস সম্পর্কে হুশিয়ার করে দিন যখন সব ব্যাপারের মীমাংসা হয়ে যাবে। এখন তারা অনবধানতায় আছে এবং তারা বিশ্বাস স্থাপন করছে না।'),
  ('bn.bengali', 19, 40, 'আমিই চুড়ান্ত মালিকানার অধিকারী হব পৃথিবীর এবং তার উপর যারা আছে তাদের এবং আমারই কাছে তারা প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 19, 41, 'আপনি এই কিতাবে ইব্রাহীমের কথা বর্ণনা করুন। নিশ্চয় তিনি ছিলেন সত্যবাদী, নবী।'),
  ('bn.bengali', 19, 42, 'যখন তিনি তার পিতাকে বললেনঃ হে আমার পিতা, যে শোনে না, দেখে না এবং তোমার কোন উপকারে আসে না, তার এবাদত কেন কর?'),
  ('bn.bengali', 19, 43, 'হে আমার পিতা, আমার কাছে এমন জ্ঞান এসেছে; যা তোমার কাছে আসেনি, সুতরাং আমার অনুসরণ কর, আমি তোমাকে সরল পথ দেখাব।'),
  ('bn.bengali', 19, 44, 'হে আমার পিতা, শয়তানের এবাদত করো না। নিশ্চয় শয়তান দয়াময়ের অবাধ্য।'),
  ('bn.bengali', 19, 45, 'হে আমার পিতা, আমি আশঙ্কা করি, দয়াময়ের একটি আযাব তোমাকে স্পর্শ করবে, অতঃপর তুমি শয়তানের সঙ্গী হয়ে যাবে।'),
  ('bn.bengali', 19, 46, 'পিতা বললঃ যে ইব্রাহীম, তুমি কি আমার উপাস্যদের থেকে মুখ ফিরিয়ে নিচ্ছ? যদি তুমি বিরত না হও, আমি অবশ্যই প্রস্তরাঘাতে তোমার প্রাণনাশ করব। তুমি চিরতরে আমার কাছ থেকে দূর হয়ে যাও।'),
  ('bn.bengali', 19, 47, 'ইব্রাহীম বললেনঃ তোমার উপর শান্তি হোক, আমি আমার পালনকর্তার কাছে তোমার জন্যে ক্ষমা প্রার্থনা করব। নিশ্চয় তিনি আমার প্রতি মেহেরবান।'),
  ('bn.bengali', 19, 48, 'আমি পরিত্যাগ করছি তোমাদেরকে এবং তোমরা আল্লাহ ব্যতীত যাদের এবাদত কর তাদেরকে; আমি আমার পালনকর্তার এবাদত করব। আশা করি, আমার পালনকর্তার এবাদত করে আমি বঞ্চিত হব না।'),
  ('bn.bengali', 19, 49, 'অতঃপর তিনি যখন তাদেরকে এবং তার আল্লাহ ব্যতীত যাদের এবাদত করত, তাদের সবাইকে পরিত্যাগ করলেন, তখন আমি তাকে দান করলাম ইসহাক ও ইয়াকুব এবং প্রত্যেককে নবী করলাম।'),
  ('bn.bengali', 19, 50, 'আমি তাদেরকে দান করলাম আমার অনুগ্রহ এবং তাদেরকে দিলাম সমুচ্চ সুখ্যাতি।'),
  ('bn.bengali', 19, 51, 'এই কিতাবে মূসার কথা বর্ণনা করুন, তিনি ছিলেন মনোনীত এবং তিনি ছিলেন রাসূল, নবী।'),
  ('bn.bengali', 19, 52, 'আমি তাকে আহবান করলাম তূর পাহাড়ের ডান দিক থেকে এবং গুঢ়তত্ত্ব আলোচনার উদ্দেশে তাকে নিকটবর্তী করলাম।'),
  ('bn.bengali', 19, 53, 'আমি নিজ অনুগ্রহে তাঁকে দান করলাম তাঁর ভাই হারুনকে নবীরূপে।'),
  ('bn.bengali', 19, 54, 'এই কিতাবে ইসমাঈলের কথা বর্ণনা করুন, তিনি প্রতিশ্রুতি পালনে সত্যাশ্রয়ী এবং তিনি ছিলেন রসূল, নবী।'),
  ('bn.bengali', 19, 55, 'তিনি তাঁর পরিবারবর্গকে নামায ও যাকাত আদায়ের নির্দেশ দিতেন এবং তিনি তাঁর পালনকর্তার কাছে পছন্দনীয় ছিলেন।'),
  ('bn.bengali', 19, 56, 'এই কিতাবে ইদ্রীসের কথা আলোচনা করুন, তিনি ছিলেন সত্যবাদী নবী।'),
  ('bn.bengali', 19, 57, 'আমি তাকে উচ্চে উন্নীত করেছিলাম।'),
  ('bn.bengali', 19, 58, 'এরাই তারা-নবীগণের মধ্য থেকে যাদেরকে আল্লাহ তা’আলা নেয়ামত দান করেছেন। এরা আদমের বংশধর এবং যাদেরকে আমি নূহের সাথে নৌকায় আরোহন করিয়েছিলাম, তাদের বংশধর, এবং ইব্রাহীম ও ইসরাঈলের বংশধর এবং যাদেরকে আমি পথ প্রদর্শন করেছি ও মনোনীত করেছি, তাদের বংশোদ্ভূত। তাদের কাছে যখন দয়াময় আল্লাহর আয়াতসমূহ পাঠ করা হত, তখন তারা সেজদায় লুটিয়ে পড়ত এবং ক্রন্দন করত।'),
  ('bn.bengali', 19, 59, 'অতঃপর তাদের পরে এল অপদার্থ পরবর্তীরা। তারা নামায নষ্ট করল এবং কুপ্রবৃত্তির অনুবর্তী হল। সুতরাং তারা অচিরেই পথভ্রষ্টতা প্রত্যক্ষ করবে।'),
  ('bn.bengali', 19, 60, 'কিন্তু তারা ব্যতীত, যারা তওবা করেছে, বিশ্বাস স্থাপন করেছে। সুতরাং তারা জান্নাতে প্রবেশ করবে এবং তাদের উপর কোন জুলুম করা হবে না।'),
  ('bn.bengali', 19, 61, 'তাদের স্থায়ী বসবাস হবে যার ওয়াদা দয়াময় আল্লাহ তাঁর বান্দাদেরকে অদৃশ্যভাবে দিয়েছেন। অবশ্যই তাঁর ওয়াদার তারা পৌঁছাবে।'),
  ('bn.bengali', 19, 62, 'তারা সেখানে সালাম ব্যতীত কোন অসার কথাবার্তা শুনবে না এবং সেখানে সকাল-সন্ধ্যা তাদের জন্যে রুযী থাকবে।'),
  ('bn.bengali', 19, 63, 'এটা ঐ জান্নাত যার অধিকারী করব আমার বান্দাদের মধ্যে পরহেযগারদেরকে।'),
  ('bn.bengali', 19, 64, '(জিব্রাইল বললঃ) আমি আপনার পালনকর্তার আদেশ ব্যতীত অবতরণ করি না, যা আমাদের সামনে আছে, যা আমাদের পশ্চাতে আছে এবং যা এ দুই-এর মধ্যস্থলে আছে, সবই তাঁর এবং আপনার পালনকর্তা বিস্মৃত হওয়ার নন।'),
  ('bn.bengali', 19, 65, 'তিনি নভোমন্ডল, ভূমন্ডলে এতদুভয়ের মধ্যবর্তী সবার পালনকর্তা। সুতরাং তাঁরই বন্দেগী করুন এবং তাতে দৃঢ় থাকুন আপনি কি তাঁর সমনাম কাউকে জানেন?'),
  ('bn.bengali', 19, 66, 'মানুষ বলেঃ আমার মৃত্যু হলে পর আমি কি জীবিত অবস্থায় পুনরুত্থিত হব?'),
  ('bn.bengali', 19, 67, 'মানুষ কি স্মরণ করে না যে, আমি তাকে ইতি পূর্বে সৃষ্টি করেছি এবং সে তখন কিছুই ছিল না।'),
  ('bn.bengali', 19, 68, 'সুতরাং আপনার পালনকর্তার কসম, আমি অবশ্যই তাদেরকে এবং শয়তানদেরকে একত্রে সমবেত করব, অতঃপর অবশ্যই তাদেরকে নতজানু অবস্থায় জাহান্নামের চারপাশে উপস্থিত করব।'),
  ('bn.bengali', 19, 69, 'অতঃপর প্রত্যেক সম্প্রদায়ের মধ্যে যে দয়াময় আল্লাহর সর্বাধিক অবাধ্য আমি অবশ্যই তাকে পৃথক করে নেব।'),
  ('bn.bengali', 19, 70, 'অতঃপর তাদের মধ্যে যারা জাহান্নামে প্রবেশের অধিক যোগ্য, আমি তাদের বিষয়ে ভালোভাবে জ্ঞাত আছি।'),
  ('bn.bengali', 19, 71, 'তোমাদের মধ্যে এমন কেউ নেই যে তথায় পৌছবে না। এটা আপনার পালনকর্তার অনিবার্য ফায়সালা।'),
  ('bn.bengali', 19, 72, 'অতঃপর আমি পরহেযগারদেরকে উদ্ধার করব এবং জালেমদেরকে সেখানে নতজানু অবস্থায় ছেড়ে দেব।'),
  ('bn.bengali', 19, 73, 'যখন তাদের কাছে আমার সুস্পষ্ট আয়াতসমূহ তেলাওয়াত করা হয়, তখন কাফেররা মুমিনদেরকে বলেঃ দুই দলের মধ্যে কোনটি মর্তবায় শ্রেষ্ঠ এবং কার মজলিস উত্তম?'),
  ('bn.bengali', 19, 74, 'তাদের পূর্বে কত মানব গোষ্ঠীকে আমি বিনাশ করেছি, তারা তাদের চাইতে সম্পদে ও জাঁক-জমকে শ্রেষ্ঠ ছিল।'),
  ('bn.bengali', 19, 75, 'বলুন, যারা পথভ্রষ্টতায় আছে, দয়াময় আল্লাহ তাদেরকে যথেষ্ট অবকাশ দেবেন; এমনকি অবশেষে তারা প্রত্যক্ষ করবে যে বিষয়ে তাদেরকে ওয়াদা দেয়া হচ্ছে, তা আযাব হোক অথবা কেয়ামতই হোক। সুতরাং তখন তারা জানতে পারবে কে মর্তবায় নিকৃষ্ট ও দলবলে দূর্বল।'),
  ('bn.bengali', 19, 76, 'যারা সৎপথে চলে আল্লাহ তাদের পথপ্রাপ্তি বৃদ্ধি করেন এবং স্থায়ী সৎকর্মসমূহ তোমার পালনকর্তার কাছে সওয়াবের দিক দিয়ে শ্রেষ্ঠ এবং প্রতিদান হিসেবেও শ্রেষ্ট।'),
  ('bn.bengali', 19, 77, 'আপনি কি তাকে লক্ষ্য করেছেন যে, আমার নিদর্শনাবলীতে বিশ্বাস করে না এবং বলেঃ আমাকে অর্থ-সম্পদ ও সন্তান-সন্ততি অবশ্যই দেয়া হবে।'),
  ('bn.bengali', 19, 78, 'সে কি অদৃশ্য বিষয় জেনে ফেলেছে, অথবা দয়াময় আল্লাহর নিকট থেকে কোন প্রতিশ্রুতি প্রাপ্ত হয়েছে?'),
  ('bn.bengali', 19, 79, 'না, এটা ঠিক নয়। সে যা বলে আমি তা লিখে রাখব এবং তার শাস্তি দীর্ঘায়িত করতে থাকব।'),
  ('bn.bengali', 19, 80, 'সে যা বলে, মৃত্যুর পর আমি তা নিয়ে নেব এবং সে আমার কাছে আসবে একাকী।'),
  ('bn.bengali', 19, 81, 'তারা আল্লাহ ব্যতীত অন্যান্য ইলাহ গ্রহণ করেছে, যাতে তারা তাদের জন্যে সাহায্যকারী হয়।'),
  ('bn.bengali', 19, 82, 'কখনই নয়, তারা তাদের এবাদত অস্বীকার করবে এবং তাদের বিপক্ষে চলে যাবে।'),
  ('bn.bengali', 19, 83, 'আপনি কি লক্ষ্য করেননি যে, আমি কাফেরদের উপর শয়তানদেরকে ছেড়ে দিয়েছি। তারা তাদেরকে বিশেষভাবে (মন্দকর্মে) উৎসাহিত করে।'),
  ('bn.bengali', 19, 84, 'সুতরাং তাদের ব্যাপারে আপনি তাড়াহুড়া করবেন না। আমি তো তাদের গণনা পূর্ণ করছি মাত্র।'),
  ('bn.bengali', 19, 85, 'সেদিন দয়াময়ের কাছে পরহেযগারদেরকে অতিথিরূপে সমবেত করব,'),
  ('bn.bengali', 19, 86, 'এবং অপরাধীদেরকে পিপাসার্ত অবস্থায় জাহান্নামের দিকে হাঁকিয়ে নিয়ে যাব।'),
  ('bn.bengali', 19, 87, 'যে দয়াময় আল্লাহর কাছ থেকে প্রতিশ্রুতি গ্রহণ করেছে, সে ব্যতীত আর কেউ সুপারিশ করার অধিকারী হবে না।'),
  ('bn.bengali', 19, 88, 'তারা বলেঃ দয়াময় আল্লাহ সন্তান গ্রহণ করেছেন।'),
  ('bn.bengali', 19, 89, 'নিশ্চয় তোমরা তো এক অদ্ভুত কান্ড করেছ।'),
  ('bn.bengali', 19, 90, 'হয় তো এর কারণেই এখনই নভোমন্ডল ফেটে পড়বে, পৃথিবী খন্ড-বিখন্ড হবে এবং পর্বতমালা চূর্ণ-বিচুর্ণ হবে।'),
  ('bn.bengali', 19, 91, 'এ কারণে যে, তারা দয়াময় আল্লাহর জন্যে সন্তান আহবান করে।'),
  ('bn.bengali', 19, 92, 'অথচ সন্তান গ্রহণ করা দয়াময়ের জন্য শোভনীয় নয়।'),
  ('bn.bengali', 19, 93, 'নভোমন্ডল ও ভূ-মন্ডলে কেউ নেই যে, দয়াময় আল্লাহর কাছে দাস হয়ে উপস্থিত হবে না।'),
  ('bn.bengali', 19, 94, 'তাঁর কাছে তাদের পরিসংখ্যান রয়েছে এবং তিনি তাদেরকে গণনা করে রেখেছেন।'),
  ('bn.bengali', 19, 95, 'কেয়ামতের দিন তাদের সবাই তাঁর কাছে একাকী অবস্থায় আসবে।'),
  ('bn.bengali', 19, 96, 'যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে, তাদেরকে দয়াময় আল্লাহ ভালবাসা দেবেন।'),
  ('bn.bengali', 19, 97, 'আমি কোরআনকে আপনার ভাষায় সহজ করে দিয়েছি, যাতে আপনি এর দ্বারা পরহেযগারদেরকে সুসংবাদ দেন এবং কলহকারী সম্প্রদায়কে সতর্ক করেন।'),
  ('bn.bengali', 19, 98, 'তাদের পূর্বে আমি কত মানবগোষ্ঠীকে ধ্বংস করেছি। আপনি কি তাদের কাহারও সাড়া পান, অথবা তাদের ক্ষীনতম আওয়ায ও শুনতে পান?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 19, 1, 'Kaf. Ha. Ya. A\'in. Sad.'),
  ('en.pickthall', 19, 2, 'A mention of the mercy of thy Lord unto His servant Zachariah.'),
  ('en.pickthall', 19, 3, 'When he cried unto his Lord a cry in secret,'),
  ('en.pickthall', 19, 4, 'Saying: My Lord! Lo! the bones of me wax feeble and my head is shining with grey hair, and I have never been unblest in prayer to Thee, my Lord.'),
  ('en.pickthall', 19, 5, 'Lo! I fear my kinsfolk after me, since my wife is barren. Oh, give me from Thy presence a successor'),
  ('en.pickthall', 19, 6, 'Who shall inherit of me and inherit (also) of the house of Jacob. And make him, my Lord, acceptable (unto Thee).'),
  ('en.pickthall', 19, 7, '(It was said unto him): O Zachariah! Lo! We bring thee tidings of a son whose name is John; we have given the same name to none before (him).'),
  ('en.pickthall', 19, 8, 'He said: My Lord! How can I have a son when my wife is barren and I have reached infirm old age?'),
  ('en.pickthall', 19, 9, 'He said: So (it will be). Thy Lord saith: It is easy for Me, even as I created thee before, when thou wast naught.'),
  ('en.pickthall', 19, 10, 'He said: My Lord! Appoint for me some token. He said: Thy token is that thou, with no bodily defect, shalt not speak unto mankind three nights.'),
  ('en.pickthall', 19, 11, 'Then he came forth unto his people from the sanctuary, and signified to them: Glorify your Lord at break of day and fall of night.'),
  ('en.pickthall', 19, 12, '(And it was said unto his son): O John! Hold fast the Scripture. And we gave him wisdom when a child,'),
  ('en.pickthall', 19, 13, 'And compassion from Our presence, and purity; and he was devout,'),
  ('en.pickthall', 19, 14, 'And dutiful toward his parents. And he was not arrogant, rebellious.'),
  ('en.pickthall', 19, 15, 'Peace on him the day he was born, and the day he dieth and the day he shall be raised alive!'),
  ('en.pickthall', 19, 16, 'And make mention of Mary in the Scripture, when she had withdrawn from her people to a chamber looking East,'),
  ('en.pickthall', 19, 17, 'And had chosen seclusion from them. Then We sent unto her Our Spirit and it assumed for her the likeness of a perfect man.'),
  ('en.pickthall', 19, 18, 'She said: Lo! I seek refuge in the Beneficent One from thee, if thou art Allah-fearing.'),
  ('en.pickthall', 19, 19, 'He said: I am only a messenger of thy Lord, that I may bestow on thee a faultless son.'),
  ('en.pickthall', 19, 20, 'She said: How can I have a son when no mortal hath touched me, neither have I been unchaste?'),
  ('en.pickthall', 19, 21, 'He said: So (it will be). Thy Lord saith: It is easy for Me. And (it will be) that We may make of him a revelation for mankind and a mercy from Us, and it is a thing ordained.'),
  ('en.pickthall', 19, 22, 'And she conceived him, and she withdrew with him to a far place.'),
  ('en.pickthall', 19, 23, 'And the pangs of childbirth drove her unto the trunk of the palm-tree. She said: Oh, would that I had died ere this and had become a thing of naught, forgotten!'),
  ('en.pickthall', 19, 24, 'Then (one) cried unto her from below her, saying: Grieve not! Thy Lord hath placed a rivulet beneath thee,'),
  ('en.pickthall', 19, 25, 'And shake the trunk of the palm-tree toward thee, thou wilt cause ripe dates to fall upon thee.'),
  ('en.pickthall', 19, 26, 'So eat and drink and be consoled. And if thou meetest any mortal, say: Lo! I have vowed a fast unto the Beneficent, and may not speak this day to any mortal.'),
  ('en.pickthall', 19, 27, 'Then she brought him to her own folk, carrying him. They said: O Mary! Thou hast come with an amazing thing.'),
  ('en.pickthall', 19, 28, 'O sister of Aaron! Thy father was not a wicked man nor was thy mother a harlot.'),
  ('en.pickthall', 19, 29, 'Then she pointed to him. They said: How can we talk to one who is in the cradle, a young boy?'),
  ('en.pickthall', 19, 30, 'He spake: Lo! I am the slave of Allah. He hath given me the Scripture and hath appointed me a Prophet,'),
  ('en.pickthall', 19, 31, 'And hath made me blessed wheresoever I may be, and hath enjoined upon me prayer and almsgiving so long as I remain alive,'),
  ('en.pickthall', 19, 32, 'And (hath made me) dutiful toward her who bore me, and hath not made me arrogant, unblest.'),
  ('en.pickthall', 19, 33, 'Peace on me the day I was born, and the day I die, and the day I shall be raised alive!'),
  ('en.pickthall', 19, 34, 'Such was Jesus, son of Mary: (this is) a statement of the truth concerning which they doubt.'),
  ('en.pickthall', 19, 35, 'It befitteth not (the Majesty of) Allah that He should take unto Himself a son. Glory be to Him! When He decreeth a thing, He saith unto it only: Be! and it is.'),
  ('en.pickthall', 19, 36, 'And lo! Allah is my Lord and your Lord. So serve Him. That is the right path.'),
  ('en.pickthall', 19, 37, 'The sects among them differ: but woe unto the disbelievers from the meeting of an awful Day.'),
  ('en.pickthall', 19, 38, 'See and hear them on the Day they come unto Us! yet the evil-doers are to-day in error manifest.'),
  ('en.pickthall', 19, 39, 'And warn them of the Day of anguish when the case hath been decided. Now they are in a state of carelessness, and they believe not.'),
  ('en.pickthall', 19, 40, 'Lo! We, only We, inherit the earth and all who are thereon, and unto Us they are returned.'),
  ('en.pickthall', 19, 41, 'And make mention (O Muhammad) in the Scripture of Abraham. Lo! he was a saint, a prophet.'),
  ('en.pickthall', 19, 42, 'When he said unto his father: O my father! Why worshippest thou that which heareth not nor seeth, nor can in aught avail thee?'),
  ('en.pickthall', 19, 43, 'O my father! Lo! there hath come unto me of knowledge that which came not unto thee. So follow me, and I will lead thee on a right path.'),
  ('en.pickthall', 19, 44, 'O my father! Serve not the devil. Lo! the devil is a rebel unto the Beneficent.'),
  ('en.pickthall', 19, 45, 'O my father! Lo! I fear lest a punishment from the Beneficent overtake thee so that thou become a comrade of the devil.'),
  ('en.pickthall', 19, 46, 'He said: Rejectest thou my gods, O Abraham? If thou cease not, I shall surely stone thee. Depart from me a long while!'),
  ('en.pickthall', 19, 47, 'He said: Peace be unto thee! I shall ask forgiveness of my Lord for thee. Lo! He was ever gracious unto me.'),
  ('en.pickthall', 19, 48, 'I shall withdraw from you and that unto which ye pray beside Allah, and I shall pray unto my Lord. It may be that, in prayer unto my Lord, I shall not be unblest.'),
  ('en.pickthall', 19, 49, 'So, when he had withdrawn from them and that which they were worshipping beside Allah, We gave him Isaac and Jacob. Each of them We made a prophet.'),
  ('en.pickthall', 19, 50, 'And we gave them of Our mercy, and assigned to them a high and true renown.'),
  ('en.pickthall', 19, 51, 'And make mention in the Scripture of Moses. Lo! he was chosen, and he was a messenger (of Allah), a prophet.'),
  ('en.pickthall', 19, 52, 'We called him from the right slope of the Mount, and brought him nigh in communion.'),
  ('en.pickthall', 19, 53, 'And We bestowed upon him of Our mercy his brother Aaron, a prophet (likewise).'),
  ('en.pickthall', 19, 54, 'And make mention in the Scripture of Ishmael. Lo! he was a keeper of his promise, and he was a messenger (of Allah), a prophet.'),
  ('en.pickthall', 19, 55, 'He enjoined upon his people worship and almsgiving, and was acceptable in the sight of his Lord.'),
  ('en.pickthall', 19, 56, 'And make mention in the Scripture of Idris. Lo! he was a saint, a prophet;'),
  ('en.pickthall', 19, 57, 'And We raised him to high station.'),
  ('en.pickthall', 19, 58, 'These are they unto whom Allah showed favour from among the prophets, of the seed of Adam and of those whom We carried (in the ship) with Noah, and of the seed of Abraham and Israel, and from among those whom We guided and chose. When the revelations of the Beneficent were recited unto them, they fell down, adoring and weeping.'),
  ('en.pickthall', 19, 59, 'Now there hath succeeded them a later generation whom have ruined worship and have followed lusts. But they will meet deception.'),
  ('en.pickthall', 19, 60, 'Save him who shall repent and believe and do right. Such will enter the Garden, and they will not be wronged in aught -'),
  ('en.pickthall', 19, 61, 'Gardens of Eden, which the Beneficent hath promised to His slaves in the unseen. Lo! His promise is ever sure of fulfilment -'),
  ('en.pickthall', 19, 62, 'They hear therein no idle talk, but only Peace; and therein they have food for morn and evening.'),
  ('en.pickthall', 19, 63, 'Such is the Garden which We cause the devout among Our bondmen to inherit.'),
  ('en.pickthall', 19, 64, 'We (angels) come not down save by commandment of thy Lord. Unto Him belongeth all that is before us and all that is behind us and all that is between those two, and thy Lord was never forgetful -'),
  ('en.pickthall', 19, 65, 'Lord of the heavens and the earth and all that is between them! Therefor, worship thou Him and be thou steadfast in His service. Knowest thou one that can be named along with Him?'),
  ('en.pickthall', 19, 66, 'And man saith: When I am dead, shall I forsooth be brought forth alive?'),
  ('en.pickthall', 19, 67, 'Doth not man remember that We created him before, when he was naught?'),
  ('en.pickthall', 19, 68, 'And, by thy Lord, verily We shall assemble them and the devils, then We shall bring them, crouching, around hell.'),
  ('en.pickthall', 19, 69, 'Then We shall pluck out from every sect whichever of them was most stubborn in rebellion to the Beneficent.'),
  ('en.pickthall', 19, 70, 'And surely We are Best Aware of those most worthy to be burned therein.'),
  ('en.pickthall', 19, 71, 'There is not one of you but shall approach it. That is a fixed ordinance of thy Lord.'),
  ('en.pickthall', 19, 72, 'Then We shall rescue those who kept from evil, and leave the evil-doers crouching there.'),
  ('en.pickthall', 19, 73, 'And when Our clear revelations are recited unto them, those who disbelieve say unto those who believe: Which of the two parties (yours or ours) is better in position, and more imposing as an army?'),
  ('en.pickthall', 19, 74, 'How many a generation have We destroyed before them, who were more imposing in respect of gear and outward seeming!'),
  ('en.pickthall', 19, 75, 'Say: As for him who is in error, the Beneficent will verily prolong his span of life until, when they behold that which they were promised, whether it be punishment (in the world), or the Hour (of doom), they will know who is worse in position and who is weaker as an army.'),
  ('en.pickthall', 19, 76, 'Allah increaseth in right guidance those who walk aright, and the good deeds which endure are better in thy Lord\'s sight for reward, and better for resort.'),
  ('en.pickthall', 19, 77, 'Hast thou seen him who disbelieveth in Our revelations and saith: Assuredly I shall be given wealth and children?'),
  ('en.pickthall', 19, 78, 'Hath he perused the Unseen, or hath he made a pact with the Beneficent?'),
  ('en.pickthall', 19, 79, 'Nay, but We shall record that which he saith and prolong for him a span of torment.'),
  ('en.pickthall', 19, 80, 'And We shall inherit from him that whereof he spake, and he will come unto Us, alone (without his wealth and children).'),
  ('en.pickthall', 19, 81, 'And they have chosen (other) gods beside Allah that they may be a power for them.'),
  ('en.pickthall', 19, 82, 'Nay, but they will deny their worship of them, and become opponents unto them.'),
  ('en.pickthall', 19, 83, 'Seest thou not that We have set the devils on the disbelievers to confound them with confusion?'),
  ('en.pickthall', 19, 84, 'So make no haste against them (O Muhammad). We do but number unto them a sum (of days).'),
  ('en.pickthall', 19, 85, 'On the day when We shall gather the righteous unto the Beneficent, a goodly company.'),
  ('en.pickthall', 19, 86, 'And drive the guilty unto hell, a weary herd,'),
  ('en.pickthall', 19, 87, 'They will have no power of intercession, save him who hath made a covenant with his Lord.'),
  ('en.pickthall', 19, 88, 'And they say: The Beneficent hath taken unto Himself a son.'),
  ('en.pickthall', 19, 89, 'Assuredly ye utter a disastrous thing'),
  ('en.pickthall', 19, 90, 'Whereby almost the heavens are torn, and the earth is split asunder and the mountains fall in ruins,'),
  ('en.pickthall', 19, 91, 'That ye ascribe unto the Beneficent a son,'),
  ('en.pickthall', 19, 92, 'When it is not meet for (the Majesty of) the Beneficent that He should choose a son.'),
  ('en.pickthall', 19, 93, 'There is none in the heavens and the earth but cometh unto the Beneficent as a slave.'),
  ('en.pickthall', 19, 94, 'Verily He knoweth them and numbereth them with (right) numbering.'),
  ('en.pickthall', 19, 95, 'And each one of them will come unto Him on the Day of Resurrection, alone.'),
  ('en.pickthall', 19, 96, 'Lo! those who believe and do good works, the Beneficent will appoint for them love.'),
  ('en.pickthall', 19, 97, 'And We make (this Scripture) easy in thy tongue, (O Muhammad) only that thou mayst bear good tidings therewith unto those who ward off (evil), and warn therewith the froward folk.'),
  ('en.pickthall', 19, 98, 'And how many a generation before them have We destroyed! Canst thou (Muhammad) see a single man of them, or hear from them the slightest sound?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 19, 1, 'Kaf. Ha. Ya. \'Ain. Sad.'),
  ('en.yusufali', 19, 2, '(This is) a recital of the Mercy of thy Lord to His servant Zakariya.'),
  ('en.yusufali', 19, 3, 'Behold! he cried to his Lord in secret,'),
  ('en.yusufali', 19, 4, 'Praying: "O my Lord! infirm indeed are my bones, and the hair of my head doth glisten with grey: but never am I unblest, O my Lord, in my prayer to Thee!'),
  ('en.yusufali', 19, 5, '"Now I fear (what) my relatives (and colleagues) (will do) after me: but my wife is barren: so give me an heir as from Thyself,-'),
  ('en.yusufali', 19, 6, '"(One that) will (truly) represent me, and represent the posterity of Jacob; and make him, O my Lord! one with whom Thou art well-pleased!"'),
  ('en.yusufali', 19, 7, '(His prayer was answered): "O Zakariya! We give thee good news of a son: His name shall be Yahya: on none by that name have We conferred distinction before."'),
  ('en.yusufali', 19, 8, 'He said: "O my Lord! How shall I have a son, when my wife is barren and I have grown quite decrepit from old age?"'),
  ('en.yusufali', 19, 9, 'He said: "So (it will be) thy Lord saith, \'that is easy for Me: I did indeed create thee before, when thou hadst been nothing!\'"'),
  ('en.yusufali', 19, 10, '(Zakariya) said: "O my Lord! give me a Sign." "Thy Sign," was the answer, "Shall be that thou shalt speak to no man for three nights, although thou art not dumb."'),
  ('en.yusufali', 19, 11, 'So Zakariya came out to his people from him chamber: He told them by signs to celebrate Allah\'s praises in the morning and in the evening.'),
  ('en.yusufali', 19, 12, '(To his son came the command): "O Yahya! take hold of the Book with might": and We gave him Wisdom even as a youth,'),
  ('en.yusufali', 19, 13, 'And piety (for all creatures) as from Us, and purity: He was devout,'),
  ('en.yusufali', 19, 14, 'And kind to his parents, and he was not overbearing or rebellious.'),
  ('en.yusufali', 19, 15, 'So Peace on him the day he was born, the day that he dies, and the day that he will be raised up to life (again)!'),
  ('en.yusufali', 19, 16, 'Relate in the Book (the story of) Mary, when she withdrew from her family to a place in the East.'),
  ('en.yusufali', 19, 17, 'She placed a screen (to screen herself) from them; then We sent her our angel, and he appeared before her as a man in all respects.'),
  ('en.yusufali', 19, 18, 'She said: "I seek refuge from thee to (Allah) Most Gracious: (come not near) if thou dost fear Allah."'),
  ('en.yusufali', 19, 19, 'He said: "Nay, I am only a messenger from thy Lord, (to announce) to thee the gift of a holy son.'),
  ('en.yusufali', 19, 20, 'She said: "How shall I have a son, seeing that no man has touched me, and I am not unchaste?"'),
  ('en.yusufali', 19, 21, 'He said: "So (it will be): Thy Lord saith, \'that is easy for Me: and (We wish) to appoint him as a Sign unto men and a Mercy from Us\': It is a matter (so) decreed."'),
  ('en.yusufali', 19, 22, 'So she conceived him, and she retired with him to a remote place.'),
  ('en.yusufali', 19, 23, 'And the pains of childbirth drove her to the trunk of a palm-tree: She cried (in her anguish): "Ah! would that I had died before this! would that I had been a thing forgotten and out of sight!"'),
  ('en.yusufali', 19, 24, 'But (a voice) cried to her from beneath the (palm-tree): "Grieve not! for thy Lord hath provided a rivulet beneath thee;'),
  ('en.yusufali', 19, 25, '"And shake towards thyself the trunk of the palm-tree: It will let fall fresh ripe dates upon thee.'),
  ('en.yusufali', 19, 26, '"So eat and drink and cool (thine) eye. And if thou dost see any man, say, \'I have vowed a fast to (Allah) Most Gracious, and this day will I enter into not talk with any human being\'"'),
  ('en.yusufali', 19, 27, 'At length she brought the (babe) to her people, carrying him (in her arms). They said: "O Mary! truly an amazing thing hast thou brought!'),
  ('en.yusufali', 19, 28, '"O sister of Aaron! Thy father was not a man of evil, nor thy mother a woman unchaste!"'),
  ('en.yusufali', 19, 29, 'But she pointed to the babe. They said: "How can we talk to one who is a child in the cradle?"'),
  ('en.yusufali', 19, 30, 'He said: "I am indeed a servant of Allah: He hath given me revelation and made me a prophet;'),
  ('en.yusufali', 19, 31, '"And He hath made me blessed wheresoever I be, and hath enjoined on me Prayer and Charity as long as I live;'),
  ('en.yusufali', 19, 32, '"(He) hath made me kind to my mother, and not overbearing or miserable;'),
  ('en.yusufali', 19, 33, '"So peace is on me the day I was born, the day that I die, and the day that I shall be raised up to life (again)"!'),
  ('en.yusufali', 19, 34, 'Such (was) Jesus the son of Mary: (it is) a statement of truth, about which they (vainly) dispute.'),
  ('en.yusufali', 19, 35, 'It is not befitting to (the majesty of) Allah that He should beget a son. Glory be to Him! when He determines a matter, He only says to it, "Be", and it is.'),
  ('en.yusufali', 19, 36, 'Verily Allah is my Lord and your Lord: Him therefore serve ye: this is a Way that is straight.'),
  ('en.yusufali', 19, 37, 'But the sects differ among themselves: and woe to the unbelievers because of the (coming) Judgment of a Momentous Day!'),
  ('en.yusufali', 19, 38, 'How plainly will they see and hear, the Day that they will appear before Us! but the unjust today are in error manifest!'),
  ('en.yusufali', 19, 39, 'But warn them of the Day of Distress, when the matter will be determined: for (behold,) they are negligent and they do not believe!'),
  ('en.yusufali', 19, 40, 'It is We Who will inherit the earth, and all beings thereon: to Us will they all be returned.'),
  ('en.yusufali', 19, 41, '(Also mention in the Book (the story of) Abraham: He was a man of Truth, a prophet.'),
  ('en.yusufali', 19, 42, 'Behold, he said to his father: "O my father! why worship that which heareth not and seeth not, and can profit thee nothing?'),
  ('en.yusufali', 19, 43, '"O my father! to me hath come knowledge which hath not reached thee: so follow me: I will guide thee to a way that is even and straight.'),
  ('en.yusufali', 19, 44, '"O my father! serve not Satan: for Satan is a rebel against (Allah) Most Gracious.'),
  ('en.yusufali', 19, 45, '"O my father! I fear lest a Penalty afflict thee from (Allah) Most Gracious, so that thou become to Satan a friend."'),
  ('en.yusufali', 19, 46, '(The father) replied: "Dost thou hate my gods, O Abraham? If thou forbear not, I will indeed stone thee: Now get away from me for a good long while!"'),
  ('en.yusufali', 19, 47, 'Abraham said: "Peace be on thee: I will pray to my Lord for thy forgiveness: for He is to me Most Gracious.'),
  ('en.yusufali', 19, 48, '"And I will turn away from you (all) and from those whom ye invoke besides Allah: I will call on my Lord: perhaps, by my prayer to my Lord, I shall be not unblest."'),
  ('en.yusufali', 19, 49, 'When he had turned away from them and from those whom they worshipped besides Allah, We bestowed on him Isaac and Jacob, and each one of them We made a prophet.'),
  ('en.yusufali', 19, 50, 'And We bestowed of Our Mercy on them, and We granted them lofty honour on the tongue of truth.'),
  ('en.yusufali', 19, 51, 'Also mention in the Book (the story of) Moses: for he was specially chosen, and he was a messenger (and) a prophet.'),
  ('en.yusufali', 19, 52, 'And we called him from the right side of Mount (Sinai), and made him draw near to Us, for mystic (converse).'),
  ('en.yusufali', 19, 53, 'And, out of Our Mercy, We gave him his brother Aaron, (also) a prophet.'),
  ('en.yusufali', 19, 54, 'Also mention in the Book (the story of) Isma\'il: He was (strictly) true to what he promised, and he was a messenger (and) a prophet.'),
  ('en.yusufali', 19, 55, 'He used to enjoin on his people Prayer and Charity, and he was most acceptable in the sight of his Lord.'),
  ('en.yusufali', 19, 56, 'Also mention in the Book the case of Idris: He was a man of truth (and sincerity), (and) a prophet:'),
  ('en.yusufali', 19, 57, 'And We raised him to a lofty station.'),
  ('en.yusufali', 19, 58, 'Those were some of the prophets on whom Allah did bestow His Grace,- of the posterity of Adam, and of those who We carried (in the Ark) with Noah, and of the posterity of Abraham and Israel of those whom We guided and chose. Whenever the Signs of (Allah) Most Gracious were rehearsed to them, they would fall down in prostrate adoration and in tears.'),
  ('en.yusufali', 19, 59, 'But after them there followed a posterity who missed prayers and followed after lusts soon, then, will they face Destruction,-'),
  ('en.yusufali', 19, 60, 'Except those who repent and believe, and work righteousness: for these will enter the Garden and will not be wronged in the least,-'),
  ('en.yusufali', 19, 61, 'Gardens of Eternity, those which (Allah) Most Gracious has promised to His servants in the Unseen: for His promise must (necessarily) come to pass.'),
  ('en.yusufali', 19, 62, 'They will not there hear any vain discourse, but only salutations of Peace: And they will have therein their sustenance, morning and evening.'),
  ('en.yusufali', 19, 63, 'Such is the Garden which We give as an inheritance to those of Our servants who guard against Evil.'),
  ('en.yusufali', 19, 64, '(The angels say:) "We descend not but by command of thy Lord: to Him belongeth what is before us and what is behind us, and what is between: and thy Lord never doth forget,-'),
  ('en.yusufali', 19, 65, '"Lord of the heavens and of the earth, and of all that is between them; so worship Him, and be constant and patient in His worship: knowest thou of any who is worthy of the same Name as He?"'),
  ('en.yusufali', 19, 66, 'Man says: "What! When I am dead, shall I then be raised up alive?"'),
  ('en.yusufali', 19, 67, 'But does not man call to mind that We created him before out of nothing?'),
  ('en.yusufali', 19, 68, 'So, by thy Lord, without doubt, We shall gather them together, and (also) the Evil Ones (with them); then shall We bring them forth on their knees round about Hell;'),
  ('en.yusufali', 19, 69, 'Then shall We certainly drag out from every sect all those who were worst in obstinate rebellion against (Allah) Most Gracious.'),
  ('en.yusufali', 19, 70, 'And certainly We know best those who are most worthy of being burned therein.'),
  ('en.yusufali', 19, 71, 'Not one of you but will pass over it: this is, with thy Lord, a Decree which must be accomplished.'),
  ('en.yusufali', 19, 72, 'But We shall save those who guarded against evil, and We shall leave the wrong-doers therein, (humbled) to their knees.'),
  ('en.yusufali', 19, 73, 'When Our Clear Signs are rehearsed to them, the Unbelievers say to those who believe, "Which of the two sides is best in point of position? Which makes the best show in council?"'),
  ('en.yusufali', 19, 74, 'But how many (countless) generations before them have we destroyed, who were even better in equipment and in glitter to the eye?'),
  ('en.yusufali', 19, 75, 'Say: "If any men go astray, (Allah) Most Gracious extends (the rope) to them, until, when they see the warning of Allah (being fulfilled) - either in punishment or in (the approach of) the Hour,- they will at length realise who is worst in position, and (who) weakest in forces!'),
  ('en.yusufali', 19, 76, '"And Allah doth advance in guidance those who seek guidance: and the things that endure, Good Deeds, are best in the sight of thy Lord, as rewards, and best in respect of (their) eventual return."'),
  ('en.yusufali', 19, 77, 'Hast thou then seen the (sort of) man who rejects Our Signs, yet says: "I shall certainly be given wealth and children?"'),
  ('en.yusufali', 19, 78, 'Has he penetrated to the Unseen, or has he taken a contract with (Allah) Most Gracious?'),
  ('en.yusufali', 19, 79, 'Nay! We shall record what he says, and We shall add and add to his punishment.'),
  ('en.yusufali', 19, 80, 'To Us shall return all that he talks of and he shall appear before Us bare and alone.'),
  ('en.yusufali', 19, 81, 'And they have taken (for worship) gods other than Allah, to give them power and glory!'),
  ('en.yusufali', 19, 82, 'Instead, they shall reject their worship, and become adversaries against them.'),
  ('en.yusufali', 19, 83, 'Seest thou not that We have set the Evil Ones on against the unbelievers, to incite them with fury?'),
  ('en.yusufali', 19, 84, 'So make no haste against them, for We but count out to them a (limited) number (of days).'),
  ('en.yusufali', 19, 85, 'The day We shall gather the righteous to (Allah) Most Gracious, like a band presented before a king for honours,'),
  ('en.yusufali', 19, 86, 'And We shall drive the sinners to Hell, like thirsty cattle driven down to water,-'),
  ('en.yusufali', 19, 87, 'None shall have the power of intercession, but such a one as has received permission (or promise) from (Allah) Most Gracious.'),
  ('en.yusufali', 19, 88, 'They say: "(Allah) Most Gracious has begotten a son!"'),
  ('en.yusufali', 19, 89, 'Indeed ye have put forth a thing most monstrous!'),
  ('en.yusufali', 19, 90, 'At it the skies are ready to burst, the earth to split asunder, and the mountains to fall down in utter ruin,'),
  ('en.yusufali', 19, 91, 'That they should invoke a son for (Allah) Most Gracious.'),
  ('en.yusufali', 19, 92, 'For it is not consonant with the majesty of (Allah) Most Gracious that He should beget a son.'),
  ('en.yusufali', 19, 93, 'Not one of the beings in the heavens and the earth but must come to (Allah) Most Gracious as a servant.'),
  ('en.yusufali', 19, 94, 'He does take an account of them (all), and hath numbered them (all) exactly.'),
  ('en.yusufali', 19, 95, 'And everyone of them will come to Him singly on the Day of Judgment.'),
  ('en.yusufali', 19, 96, 'On those who believe and work deeds of righteousness, will (Allah) Most Gracious bestow love.'),
  ('en.yusufali', 19, 97, 'So have We made the (Qur\'an) easy in thine own tongue, that with it thou mayest give Glad Tidings to the righteous, and warnings to people given to contention.'),
  ('en.yusufali', 19, 98, 'But how many (countless) generations before them have We destroyed? Canst thou find a single one of them (now) or hear (so much as) a whisper of them?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 19, 1, 'Kaaaf-Haa-Yaa-\'Ayyyn-Saaad'),
  ('en.transliteration', 19, 2, 'Zikru rahmati Rabbika \'abdahoo Zakariyya'),
  ('en.transliteration', 19, 3, 'Iz naadaa Rabbahoo nidaaa\'an khafiyyaa'),
  ('en.transliteration', 19, 4, 'Qaala Rabbi innee wahanal\'azmu minnee washta\'alar raasu shaibanw wa lam akum bidu\'aaa\'ika Rabbi shaqiyyaa'),
  ('en.transliteration', 19, 5, 'Wa innee khiftul mawaa liya minw waraaa\'ee wa kaana tim ra atee \'aairan fahab lee mil ladunka waliyyaa'),
  ('en.transliteration', 19, 6, 'Yarisunee wa yarisu min aali Ya\'qoob, waj\'alhu Rabbi radiyya'),
  ('en.transliteration', 19, 7, 'Yaa Zakariyyaaa innaa nubashshiruka bighulaami nismuhoo Yahyaa lam naj\'al lahoo min qablu samiyyaa'),
  ('en.transliteration', 19, 8, 'Qaala Rabbi annaa yakoonu lee ghulaamunw wa kaanatim ra atee aaqiranw wa qad balaghtu minal kibari \'itiyyaa'),
  ('en.transliteration', 19, 9, 'Qaala kazaalika qaala Rabbuka huwa \'alaiya haiyinunw wa qad khalaqtuka min qablu wa lam taku shai\'aa'),
  ('en.transliteration', 19, 10, 'Qaala Rabbij \'al leee Aayah; qaala Aayatuka allaa tukalliman naasa salaasa layaalin sawiyyaa'),
  ('en.transliteration', 19, 11, 'Fakharaja \'alaa qawmihee minal mihraabi fa-awhaaa ilaihim an sabbihoo bukratanw wa \'ashiyyaa'),
  ('en.transliteration', 19, 12, 'Yaa Yahyaa khuzil Kitaaba biquwwatinw wa aatainaahul hukma saiyyaa'),
  ('en.transliteration', 19, 13, 'Wa hanaanam mil ladunnaa wa zakaatanw wa kaana taqiyyaa'),
  ('en.transliteration', 19, 14, 'Wa barram biwaalidayhi wa lam yakum jabbaaran \'asiyyaa'),
  ('en.transliteration', 19, 15, 'Wa salaamun \'alaihi yawma wulida wa yawma yamootu wa yawma yub\'asu haiyaa'),
  ('en.transliteration', 19, 16, 'Wazkur fil Kitaabi Marya; izin tabazat min ahlihaa makaanan shariqyyaa'),
  ('en.transliteration', 19, 17, 'Fattakhazat min doonihim hijaaban fa arsalnaaa ilaihaa roohanaa fatamassala lahaa basharan sawiyyaa'),
  ('en.transliteration', 19, 18, 'Qaalat inneee a\'oozu bir Rahmaani minka in kunta taqiyyaa'),
  ('en.transliteration', 19, 19, 'Qaala innamaa ana rasoolu Rabbiki li ahaba laki ghulaaman zakiyyaa'),
  ('en.transliteration', 19, 20, 'Qaalat anna yakoonu lee ghulaamunw wa lam yamsasnee bashrunw wa lam aku baghiyyaa'),
  ('en.transliteration', 19, 21, 'Qaala kazaaliki qaala Rabbuki huwa \'alaiya yaiyimunw wa linaj \'alahooo Aayatal linnaasi wa rahmatam minnaa; wa kaana amram maqdiyyaa'),
  ('en.transliteration', 19, 22, 'Fahamalat hu fantabazat bihee makaanan qasiyyaa'),
  ('en.transliteration', 19, 23, 'Fa ajaaa \'ahal makhaadu ilaa jiz\'in nakhlati qaalat yaa laitanee mittu qabla haazaa wa kuntu nasyam mansiyyaa'),
  ('en.transliteration', 19, 24, 'Fanaadaahaa min tahtihaan allaa tahzanee qad ja\'ala Rabbuki tahtaki sariyyaa'),
  ('en.transliteration', 19, 25, 'Wa huzzeee ilaiki bijiz \'in nakhlati tusaaqit \'alaiki rutaban janiyyaa'),
  ('en.transliteration', 19, 26, 'Fakulee washrabee wa qarree \'ainaa; fa immaa tarayinnna minal bashari ahadan faqooleee innee nazartu lir Rahmaani sawman falan ukallimal yawma insiyyaa'),
  ('en.transliteration', 19, 27, 'Fa atat bihee qawmahaa tahmiluhoo qaaloo yaa Maryamoo laqad ji\'ti shai\'an fariyyaa'),
  ('en.transliteration', 19, 28, 'Yaaa ukkhta Haaroona maa kaana abokim ra-a saw\'inw wa maa kaanat ummuki baghiyyaa'),
  ('en.transliteration', 19, 29, 'Fa ashaarat ilaih; qaaloo kaifa nukallimu man kaana fil mahdi sabiyyaa'),
  ('en.transliteration', 19, 30, 'Qaala innee \'abdullaahi aataaniyal Kitaaba wa ja\'alanee Nabiyyaa'),
  ('en.transliteration', 19, 31, 'Wa ja\'alanee mubaarakan aina maa kuntu wa awsaanee bis Salaati waz Zakaati maa dumtu haiyaa'),
  ('en.transliteration', 19, 32, 'Wa barram biwaalidatee wa lam yaj\'alnee jabbaaran shaqiyyaa'),
  ('en.transliteration', 19, 33, 'Wassalaamu \'alaiya yawma wulittu wa yawma amootu wa yawma ub\'asu baiyaa'),
  ('en.transliteration', 19, 34, 'Zaalika \'Eesab-nu Marya; qawlal haqqil lazee feehi yamtaroon'),
  ('en.transliteration', 19, 35, 'Maa kaana lillaahi ai yattakhiza minw waladin Subhaanah; izaa qadaaa amran fa innamaa yaqoolu lahoo kun fa yakoon'),
  ('en.transliteration', 19, 36, 'Wa innal laaha Rabbee wa Rabbukum fa\'budooh; haazaa Siraatum Mustaqeem'),
  ('en.transliteration', 19, 37, 'Fakhtalafal ahzaabu mim bainihim fawailul lillazeena kafaroo mim mashhadi Yawmin \'azeem'),
  ('en.transliteration', 19, 38, 'Asmi\' bihim wa absir Yawma yaatoonanaa laakiniz zaalimoonal yawma fee dalaalim mubeen'),
  ('en.transliteration', 19, 39, 'Wa anzirhum Yawmal hasrati iz qudiyal amr; wa hum fee ghaflatinw wa hum laa yu\'minoon'),
  ('en.transliteration', 19, 40, 'Innaa NNahnu narisul arda wa man \'alaihaa wa ilainaa yurja\'oon'),
  ('en.transliteration', 19, 41, 'Wazkur fil Kitaabi Ibraaheem; innahoo kaana siddeeqan Nabiyyaa'),
  ('en.transliteration', 19, 42, 'Iz qaala li abeehi yaaa abati lima ta\'budu maa laa yasma\'u wa laa yubsiru wa laa yughnee \'anka shai\'aa'),
  ('en.transliteration', 19, 43, 'Yaaa abati innee qad jaaa\'anee minal \'ilmi maa lam yaatika fattabi\'neee ahdika siraatan Sawiyyaa'),
  ('en.transliteration', 19, 44, 'Yaaa abati laa ta\'budish Shaitaana innash Shaitaana kaana lir Rahmaani \'asiyyaa'),
  ('en.transliteration', 19, 45, 'Yaaa abati innee akhaafu ai yamssaka \'azaabum minar Rahmaani fatakoona lish Shaitaani waliyyaa'),
  ('en.transliteration', 19, 46, 'Qaala araaghibun anta \'an aalihatee yaaa Ibraaheemu la \'il lam tantahi la arjumannaka wahjumee maliyyaa'),
  ('en.transliteration', 19, 47, 'Qaala salaamun \'alaika sa astaghfiru laka Rabbeee innahoo kaana bee hafiyyaa'),
  ('en.transliteration', 19, 48, 'Wa a\'tazilukum wa maa tad\'oona min doonil laahi wa ad\'o Rabbee \'asaaa allaaa akoona bidu\'aaa\'i Rabbee shaqiyyaa'),
  ('en.transliteration', 19, 49, 'Falamma\' tazalahum wa maa ya\'budoona min doonil laahi wahabnaa lahoo is-haaqa wa ya\'qoob, wa kullan ja\'alnaa Nabiyyaa'),
  ('en.transliteration', 19, 50, 'Wa wahabnaa lahum mirrahmatinaa wa ja\'alnaa lahum lisaana sidqin \'aliyyaa'),
  ('en.transliteration', 19, 51, 'Wazkur fil Kitaabi Moosaaa; innahoo kaana mukhlasanw wa kaana Rasoolan Nabiyyaa'),
  ('en.transliteration', 19, 52, 'Wa naadainaahu min jaanibit Tooril aimani wa qarrabnaahu najiyyaa'),
  ('en.transliteration', 19, 53, 'Wa wahabnaa lahoo mir rahmatinaaa akhaahu Haaroona Nabiyyaa'),
  ('en.transliteration', 19, 54, 'Wazkur fil Kitaabi ismaa\'eel; innahoo kaana saadiqal wa\'di wa kaana Rasoolan Nabiyyaa'),
  ('en.transliteration', 19, 55, 'Wa kaana yaamuru ahlahoo bis Salaati waz zakaati wa kaana \'inda Rabbihee mardiyyaa'),
  ('en.transliteration', 19, 56, 'Wazkur fil Kitaabi Idrees; innahoo kaana siddeeqan Nabiyyaa'),
  ('en.transliteration', 19, 57, 'Wa rafa\'naahu makaanan \'aliyyaa'),
  ('en.transliteration', 19, 58, 'Ulaaa\'ikal lazeena an\'amal laahu \'alaihim minan Nabiyyeena min zurriyyati Aadama wa mimman hamalnaa ma\'a Noohinw wa min zurriyyati Ibraaheema wa Israaa\'eela wa mimman hadainaa wajta bainaaa; izaa tutlaa \'alaihim Aayaatur Rahmaani kharroo sujjadanw wa bukiyyaa'),
  ('en.transliteration', 19, 59, 'Fakhalafa mim ba\'dihim khalfun adaa\'us Salaata wattaba\'ush shahawaati fasawfa yalqawna ghaiyaa'),
  ('en.transliteration', 19, 60, 'Illaa man taaba wa aamana wa \'amila saalihan fa ulaaa\'ika yadkhuloonal jannata wa laa yuzlamoona shai\'aa'),
  ('en.transliteration', 19, 61, 'Jannaati \'adninil latee wa\'adar Rahmaanu ibaadahoo bilghaib; innahoo kaana wa\'duhoo maatiyyaa'),
  ('en.transliteration', 19, 62, 'Laa yasma\'oona feehaa laghwan illaa salaamaa; wa lahum rizquhum feehaa bukratanw wa \'ashiyyaa'),
  ('en.transliteration', 19, 63, 'Tilkal jannatul latee oorisu min \'ibaadinaa man kaana taqiyyaa'),
  ('en.transliteration', 19, 64, 'Wa maa natanazzalu illaa bi amri Rabbika lahoo maa baina aideenaa wa maa khalfanaa wa maa baina zaalik; wa maa kaana Rabbuka nasiyyaa'),
  ('en.transliteration', 19, 65, 'Rabbus samaawaati wal ardi wa maa bainahumaa fa\'bud hu wastabir li\'ibaadatih; hal ta\'lamu lahoo samiyyaa'),
  ('en.transliteration', 19, 66, 'Wa yaqoolul insaanu \'aizaa maa mittu lasawfa ukhraju haiyaa'),
  ('en.transliteration', 19, 67, 'awalaa yazkurul insaanu annaa khalaqnaahu min qablu wa lam yaku shai\'aa'),
  ('en.transliteration', 19, 68, 'Fawa Rabbika lanahshu rannahum wash shayaateena summa lanuhdirannahum hawla jahannama jisiyyaa'),
  ('en.transliteration', 19, 69, 'Summa lananzi \'anna min kulli shee\'atin aiyuhum ashaddu \'alar Rahmaani \'itiyyaa'),
  ('en.transliteration', 19, 70, 'Summa lanahnu a\'lamu billazeena hum awlaa bihaa siliyyaa'),
  ('en.transliteration', 19, 71, 'Wa im minkum illaa waa riduhaa; kaana \'alaa Rabbika hatmam maqdiyyaa'),
  ('en.transliteration', 19, 72, 'Summa nunajjil lazeenat taqaw wa nazaruz zaalimeena feehaa jisiyyaa'),
  ('en.transliteration', 19, 73, 'Wa izaa tutlaa \'alaihim Aayaatunaa baiyinaatin qaalal lazeena kafaroo lillazeena aamanooo aiyul fareeqaini khairum maqaamanw wa ahsanu nadiyyaa'),
  ('en.transliteration', 19, 74, 'Wa kam ahlaknaa qablahum min qarnin hum ahsanu asaasanw wa ri\'yaa'),
  ('en.transliteration', 19, 75, 'Qul man kaana fidda laalati falyamdud lahur Rahmaanu maddaa; hattaaa izaa ra aw maa yoo\'adoona immal \'azaaba wa immas Saa\'ata fasa ya\'lamoona man huwa sharrum makaananw wa ad\'afu jundaa'),
  ('en.transliteration', 19, 76, 'Wa yazeedul laahul lazeenah tadaw hudaa; wal baaqiyaatus saalihaatu khairun \'inda Rabbika sawaabanw wa khairum maraddaa'),
  ('en.transliteration', 19, 77, 'Afara\'aytal lazee kafara bi Aayaatinaa wa qaala la oota yanna maalanw wa waladaa'),
  ('en.transliteration', 19, 78, 'Attala\'al ghaiba amitta khaza\'indar Rahmaani \'ahdaa'),
  ('en.transliteration', 19, 79, 'Kallaa; sanaktubu maa yaqoolu wa namuddu lahoo minal \'azaabi maddaa'),
  ('en.transliteration', 19, 80, 'Wa narisuhoo maa yaqoolu wa yaateenaa fardaa'),
  ('en.transliteration', 19, 81, 'Wattakhazoo min doonil laahi aalihatal liyakoonoo lahum \'izzaa'),
  ('en.transliteration', 19, 82, 'Kallaa; sa yakfuroona bi\'ibaadatihim wa yakoonoona \'alaihim diddaa'),
  ('en.transliteration', 19, 83, 'Alam tara annaaa arsalnash Shayaateena \'alal kaafireena ta\'uzzuhum azzaa'),
  ('en.transliteration', 19, 84, 'Falaa ta\'jal alaihim innamaa na \'uddu lahum \'addaa'),
  ('en.transliteration', 19, 85, 'Yawma nahshurul muttaqeena ilar Rahmaani wafdaa'),
  ('en.transliteration', 19, 86, 'Wa nasooqul mujrimeena ilaa Jahannama wirdaa'),
  ('en.transliteration', 19, 87, 'Laa yamlikoonash shafaa\'ta illaa manittakhaza \'indar Rahmaani \'ahdaa'),
  ('en.transliteration', 19, 88, 'Wa qaalut takhazar Rahmaanu waladaa'),
  ('en.transliteration', 19, 89, 'Laqad ji\'tum shai\'an iddaa'),
  ('en.transliteration', 19, 90, 'Takaadus samaawaatu yatafattarna minhu wa tanshaq qul ardu wa takhirrul jibaalu haddaa'),
  ('en.transliteration', 19, 91, 'An da\'aw lir Rahmaani waladaa'),
  ('en.transliteration', 19, 92, 'Wa maa yambaghee lir Rahmaani ai yattakhiza waladaa'),
  ('en.transliteration', 19, 93, 'In kullu man fis samaawaati wal ardi illaaa aatir Rahmaani \'abdaa'),
  ('en.transliteration', 19, 94, 'Laqad ahsaahum wa addahum \'addaa'),
  ('en.transliteration', 19, 95, 'Wa kulluhum aateehi Yawmal Qiyaamati fardaa'),
  ('en.transliteration', 19, 96, 'Innal lazeena aamanoo wa \'amilus saalihaati sa yaj\'alu lahumur Rahmaanu wuddaa'),
  ('en.transliteration', 19, 97, 'Fa innamaa yassarnaahu bilisaanika litubashshira bihil muttaqeena wa tunzira bihee qawmal luddaa'),
  ('en.transliteration', 19, 98, 'Wa kam ahlaknaa qabla hum min qarnin hal tuhissu minhum min ahadin aw tasma\'u lahum rikzaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 19, 1, 'کھیصۤ'),
  ('ur.ahmedali', 19, 2, 'یہ تیرے رب کی مہربانی کا ذکر ہے جو اس کے بندے زکریا پر ہوئی'),
  ('ur.ahmedali', 19, 3, 'جب اس نے اپنے رب کو خفیہ آواز سے پکارا'),
  ('ur.ahmedali', 19, 4, 'کہا اے میرے رب میری ہڈیاں کمزور ہو گئی ہیں اور سر میں بڑھاپا چمکنے لگا ہے او رمیرے رب تجھ سے مانگ کر میں کبھی محروم نہیں ہوا'),
  ('ur.ahmedali', 19, 5, 'اور بے شک میں اپنے بعد اپنے رشتہ داروں سے ڈرتا ہوں اور میری بیوی بانجھ ہے پس تو اپنے ہاں سے ایک وارث عطا کر'),
  ('ur.ahmedali', 19, 6, 'جو میرا اور یعقوب کے خاندان کا بھی وارث ہو اور میرے رب اسے پسندیدہ بنا'),
  ('ur.ahmedali', 19, 7, 'اے زکریا بے شک ہم تجھے ایک لڑکے کی خوشخبری دیتے ہیں جس کا نام یحییٰ ہوگا اس سےپہلے ہم نے اس نام کا کوئی پیدا نہیں کیا'),
  ('ur.ahmedali', 19, 8, 'کہا اے میرے رب میرے لیے لڑکا کہاں سے ہوگا حالانکہ میری بیوی بانجھ ہے اور میں بڑھاپے میں انتہائی درجہ کو پہنچ گیا ہوں'),
  ('ur.ahmedali', 19, 9, 'کہا ایسا ہی ہوگا تیرے رب نے کہاہے وہ مجھ پر آسان ہے اور میں نے تجھے اس سے پہلے پیدا کیا حالانکہ تو کوئی چیز نہ تھا'),
  ('ur.ahmedali', 19, 10, 'کہا اے میرے رب میرے لئےکوئی نشانی مقرر کر کہا تیری نشانی یہ ہے کہ توتین رات تک مسلسل لوگوں سے بات نہیں کر سکے گا'),
  ('ur.ahmedali', 19, 11, 'پھر حجرہ سے نکل کر اپنی قوم کے پاس آئے اور انہیں اشارہ سے کہا کہ تم صبح و شام خدا کی تسبیح کیا کرو'),
  ('ur.ahmedali', 19, 12, 'اے یحییٰ کتاب کو مضبوطی سے پکڑ اور ہم نے اسےبچپن ہی میں حکمت عطا کی'),
  ('ur.ahmedali', 19, 13, 'اور اسے اپنے ہاں سے رحم دلی او رپاکیز گی عنایت کی اور وہ پرہیز گار تھا'),
  ('ur.ahmedali', 19, 14, 'اور اپنے ماں باپ کے ساتھ نیک سلوک کرنے والا اور سرکش نافرمان نہ تھا'),
  ('ur.ahmedali', 19, 15, 'اور اس پر سلام ہو جس دن وہ پیدا ہوا اور جس دن مرے گا اور جس دن وہ زندہ کرکے اٹھایا جائے گا'),
  ('ur.ahmedali', 19, 16, 'اور اس کتاب میں مریم کا ذکر کر جب کہ وہ اپنے لوگوں سے علیحدہ ہو کر مشرقی مقام میں جا بیٹھی'),
  ('ur.ahmedali', 19, 17, 'پھر لوگوں کے سامنے سے پردہ ڈال لیا پھر ہم نے اس کے پاس اپنے فرشتے کو بھیجا پھر وہ اس کے سامنے پورا آدمی بن کر ظاہر ہوا'),
  ('ur.ahmedali', 19, 18, 'کہا بے شک میں تجھ سے الله کی پناہ مانگتی ہوں اگر تو پرہیزگار ہے'),
  ('ur.ahmedali', 19, 19, 'کہا میں تو بس تیرے رب کا بھیجا ہوا ہوں تاکہ تجھے پاکیزہ لڑکا دوں'),
  ('ur.ahmedali', 19, 20, 'کہا میرے لیے لڑکا کہاں سے ہوگا حالانکہ مجھے کسی آدمی نے ہاتھ نہیں لگایا اور نہ میں بدکار ہوں'),
  ('ur.ahmedali', 19, 21, 'کہا ایسا ہی ہوگا تیرے رب نے کہا ہے وہ مجھ پر آسان ہے اور تاکہ ہم اسے لوگوں کے لیے نشانی اور اپنی طرف سے رحمت بنائیں اور یہ بات طے ہو چکی ہے'),
  ('ur.ahmedali', 19, 22, 'پھر اس (بچہ کے ساتھ) حاملہ ہوئی پھر اسے لے کر کسی دور جگہ میں چلی گئی'),
  ('ur.ahmedali', 19, 23, 'پھر اسے درد زہ ایک کھجور کی جڑ میں لے آیا کہا اے افسوس میں اس سے پہلے مرگئی ہوتی اور میں بھولی بھلائی ہوتی'),
  ('ur.ahmedali', 19, 24, 'پھر اسے اس کے نیچے سے پکارا کہ غم نہ کر تیرے رب نے تیرے نیچے سے ایک چشمہ پیدا کر دیا'),
  ('ur.ahmedali', 19, 25, 'اورتو کھجور کے تنہ کو پکڑ کر اپنی طرف ہلا تجھ پر پکی تازہ کھجوریں گریں گی'),
  ('ur.ahmedali', 19, 26, 'سوکھا اور پی اور آنکھ ٹھنڈی کر پھر اگر تو کوئی آدمی دیکھے تو کہہ دے کہ میں نے رحمان کے لیے روزہ کی نذر مانی ہے سو آج میں کسی انسان سے بات نہیں کروں گی'),
  ('ur.ahmedali', 19, 27, 'پھر وہ اسے قوم کے پا س اٹھا کر لائی انہوں نے کہا اے مریم البتہ تو نے عجیب بات کر دکھائی'),
  ('ur.ahmedali', 19, 28, 'اے ہارون کی بہن نہ تو تیرا باپ ہی برا آدمی تھا اور نہ ہی تیری ماں بدکار تھی'),
  ('ur.ahmedali', 19, 29, 'تب اس نے لڑکے کی طرف اشارہ کیا انہوں نے کہا ہم پنگوڑھے والے بچے سے کیسے بات کریں'),
  ('ur.ahmedali', 19, 30, 'کہا بے شک میں الله کا بندہ ہوں مجھےاس نے کتاب دی ہے اور مجھے نبی بنایا ہے'),
  ('ur.ahmedali', 19, 31, 'اور مجھے با برکت بنایاہے جہاں کہیں ہوں اور مجھے کو نماز اور زکواة کی وصیت کی ہے جب تک میں زندہ ہوں'),
  ('ur.ahmedali', 19, 32, 'اور اپنی ماں کے ساتھ نیکی کرنے والا اور مجھے سرکش بدبخت نہیں بنایا'),
  ('ur.ahmedali', 19, 33, 'اور مجھ پر سلام ہے جس دن میں پیدا ہوا اور جس دن مروں گا اور جس دن زندہ کر کے اٹھایا جاؤں گا'),
  ('ur.ahmedali', 19, 34, 'یہ عیسیٰ مریم کا بیٹا ہے سچی بات جس میں وہ جھگڑ رہے ہیں'),
  ('ur.ahmedali', 19, 35, 'الله کی شان نہیں کہ وہ کسی کو بیٹا بنائے وہ پاک ہے جب کسی کام کا فیصلہ کرتا ہے توصرف اسے کن کہتا ہے پھر وہ ہو جاتا ہے'),
  ('ur.ahmedali', 19, 36, 'اور بے شک الله تعالیٰ میرا اور تمہارا رب ہے سواسی کی عبادت کرو یہ سیدھا راستہ ہے'),
  ('ur.ahmedali', 19, 37, 'پھر جماعتیں آپس میں مختلف ہو گئیں سوکافروں کے لیے ایک بڑے دن کے آنے سے خرابی ہے'),
  ('ur.ahmedali', 19, 38, 'کیا خوب سنتے اور دیکھتے ہوں گے جس دن ہمارے پاس آئیں گے لیکن ظالم آج صریح گمراہی میں ہیں'),
  ('ur.ahmedali', 19, 39, 'اور انہیں حسرت کے دن سے ڈرا جس دن سارے معاملہ کا فیصلہ ہوگا اور وہ غفلت میں ہیں او رایمان نہیں لاتے'),
  ('ur.ahmedali', 19, 40, 'بے شک ہم ہی زمین کے وارث ہوں گے اور ان کے بھی جو اس پر ہیں اور ہماری طرف لوٹائے جائیں گے'),
  ('ur.ahmedali', 19, 41, 'اور کتاب میں ابراھیم کا ذکر بے شک وہ سچا نبی تھا'),
  ('ur.ahmedali', 19, 42, 'جب اپنے باپ سے کہا اے میرے باپ تو کیوں پوجتاہے ایسے کو جونہ سنتا ہے اور نہ دیکھتا ہے اور نہ تیرےکچھ کام آ سکے'),
  ('ur.ahmedali', 19, 43, 'اے میرے باپ بے شک مجھے وہ علم حاصل ہوا ہے جو تمہیں حاصل نہیں تو آپ میری تابعداری کریں میں آپ کو سیدھا راستہ دکھاؤں گا'),
  ('ur.ahmedali', 19, 44, 'اے میرے باپ شیطان کی عبادت نہ کر بے شک شیطان الله کا نافرمان ہے'),
  ('ur.ahmedali', 19, 45, 'اے میرے باپ بے شک مجھے خوف ہے کہ تم پر الله کا عذاب آئے پھر شیطان کے ساتھی ہوجاؤ'),
  ('ur.ahmedali', 19, 46, 'کہا اے ابراھیم کیا تو میرے معبودوں سے پھرا ہوا ہے البتہ اگر تو باز نہ آیا میں تجھے سنگسار کردوں گا اور مجھ سے ایک مدت تک دور ہو جا'),
  ('ur.ahmedali', 19, 47, 'کہا تیری سلامتی رہے اب میں اپنے رب سے تیری بخشش کی دعا کروں گا بے شک وہ مجھ پر بڑا مہربان ہے'),
  ('ur.ahmedali', 19, 48, 'اور میں تمہیں چھوڑتا ہوں اور جنہیں تم الله کے سوا پکارتے ہو اور میں اپنے رب ہی کو پکاروں گا امید ہے کہ میں اپنے رب کو پکار کر محروم نہ رہوں گا'),
  ('ur.ahmedali', 19, 49, 'پھر جب ان سے علیحدٰہ ہوا اور اس چیز سے جنہیں وہ الله کے سوا پوجتے تھے ہم نے اسے اسحاق اور یعقوب عطا کیا اور ہم نے ہر ایک کو نبی بنایا'),
  ('ur.ahmedali', 19, 50, 'اور ہم نے ان سب کو اپنی رحمت سے حصہ دیا اور ہم نے ان کا نیک نام بلند کیا'),
  ('ur.ahmedali', 19, 51, 'اور کتاب میں موسیٰ کا ذکر کر بے شک وہ خاص بندے اور بھیجے ہوئے پیغمبر تھے'),
  ('ur.ahmedali', 19, 52, 'اور ہم نے اسے کوہِ طور کے دائیں طرف سے پکارا اور اسے راز کی بات کہنے کے لیے قریب بلایا'),
  ('ur.ahmedali', 19, 53, 'اور ہم نے اسے اپنی رحمت سے ان کے بھائی ہارون کو نبی بنا کر عطا کیا'),
  ('ur.ahmedali', 19, 54, 'اور کتاب میں اسماعیل کا بھی ذکر کر بے شک وہ وعدہ کا سچا اور بھیجا ہوا پیغمبر تھا'),
  ('ur.ahmedali', 19, 55, 'اور اپنے گھر والوں کو نماز اور زکوٰةکا حکم کرتا تھا اور وہ اپنے رب کے ہاں پسندیدہ تھا'),
  ('ur.ahmedali', 19, 56, 'اور کتاب میں ادریس کا ذکر کر بے شک وہ سچا نبی تھا'),
  ('ur.ahmedali', 19, 57, 'اور ہم نے اسے بلند مرتبہ پر پہنچایا'),
  ('ur.ahmedali', 19, 58, 'یہ وہ لوگ ہیں جن پر الله نے انعام کیا پیغمبروں میں اور آدم کی اولاد میں سے اور ان میں سے جنہیں ہم نے نوح کے ساتھ سوار کیا تھا اور ابراھیم اور اسرائیل کی اولاد میں سے اور ان میں سے جنہیں ہم نے ہدایت کی اور پسند کیا جب ان پر الله کی آیتیں پڑھی جاتی ہیں تو روتے ہوئے سجدے میں گرتے ہیں'),
  ('ur.ahmedali', 19, 59, 'پھر ان کی جگہ ایسے ناخلف آئے جنہو ں نے نماز ضائع کی اور خواہشوں کے پیچھے پڑ گئے پھر عنقریب گمراہی کی سزا پائیں گے'),
  ('ur.ahmedali', 19, 60, 'مگر جس نے توبہ کی اور ایمان لایا اور نیک کام کیے سو وہ لوگ بہشت میں داخل ہوں گے اور ان کا ذرا نقصان نہ کیا جائے گا'),
  ('ur.ahmedali', 19, 61, 'ہمیشگی کے باغوں میں جن کا رحمان نے اپنے بندوں سے وعدہ کیا ہے جو ان کی آنکھوں سے پوشیدہ ہے بے شک اس کا وعدہ پورا ہونے والا ہے'),
  ('ur.ahmedali', 19, 62, 'اس میں سوائے سلام کے کوئی فضول بات نہ سنیں گے اور انہیں وہاں صبح و شام کھانا ملے گا'),
  ('ur.ahmedali', 19, 63, 'یہ وہ جنت ہے کہ ہم اپنے بندوں میں سے اس کو وارث بنائیں گے جو پرہیزگار ہوگا'),
  ('ur.ahmedali', 19, 64, 'اورہم تیرے رب کے حکم کے سوا نہیں اترتے اسی کا ہے جو کچھ ہمارے سامنے ہے اور جو کچھ ہمارے پیچھے ہے اور جو کچھ اس کے درمیان ہے او ر تیرا رب بھولنے والا نہیں'),
  ('ur.ahmedali', 19, 65, 'آسمانوں اور زمین کا رب ہے اور جو چیز ان کے درمیان ہے سو اسی کی عبادت کرو اسی کی عبادت پر قائم رہ کیا تیرے علم میں ا س جیسا کوئی اور ہے'),
  ('ur.ahmedali', 19, 66, 'اور انسان کہتا ہے جب میں مرجاؤں گا تو کیا پھر زندہ کر کے نکالا جاؤں گا'),
  ('ur.ahmedali', 19, 67, 'کیا انسان کو یاد نہیں ہے کہ اس سے پہلے ہم نے اسےبنایا تھا اور وہ کوئی چیز بھی نہ تھا'),
  ('ur.ahmedali', 19, 68, 'سو تیرے رب کی قسم ہے ہم انہیں اور ان کے شیطانوں کو ضرور جمع کریں گے پھر ہم انہیں گھٹنوں پر گرے ہوئے دوزخ کے گرد حاضر کریں گے'),
  ('ur.ahmedali', 19, 69, 'پھر ہر گروہ میں سے ان لوگوں کو الگ کر لیں گے جو الله سے بہت ہی سرکش تھے'),
  ('ur.ahmedali', 19, 70, 'پھر ہم ان لوگو ں کو خوب جانتے ہیں جو دوزخ میں جانے کے زیادہ مستحق ہیں'),
  ('ur.ahmedali', 19, 71, 'اور تم میں سے کوئی بھی ایسا نہیں جس کا اس پر گزر نہ ہو یہ تیرے رب پر لازم مقرر کیا ہوا ہے'),
  ('ur.ahmedali', 19, 72, 'پھر ہم انہیں بچا لیں گے جو ڈرتے ہیں اور ظالموں کو اس میں گھٹنوں پر گرے ہوئے چھوڑ دیں گے'),
  ('ur.ahmedali', 19, 73, 'اور جب انہیں ہماری کھلی ہوئی آیتیں سنائی جاتی ہیں تو کافر ایمان داروں سے کہتے ہیں دونوں فریقوں میں سے کس کا مرتبہ بہتر ہے اور محفل کس کی اچھی ہے'),
  ('ur.ahmedali', 19, 74, 'اور ہم ان سے پہلے کتنی جماعتیں ہلاک کرچکے ہیں وہ سامان اور نمود میں بہتر تھے'),
  ('ur.ahmedali', 19, 75, 'کہہ دو جو شخص گمراہی میں پڑا ہوا ہے سو الله بھی اسے ڈھیل دیتا ہے یہاں تک کہ جب اس چیز کو دیکھیں گے جس کا انہیں نے وعدہ دیا گیا تھا یا عذاب یا قیامت تب معلوم کر لیں گے مرتبے میں کون برا ہے اور لشکر کس کا کمزور ہے'),
  ('ur.ahmedali', 19, 76, 'اور جو لوگ ہدایت پر ہیں الله انہیں زیادہ ہدایت دیتا ہے اور باقی رہنے والی نیکیاں تیرے رب کے نزدیک ثواب اور انجام کے لحاظ سے بہت ہی بہتر ہیں'),
  ('ur.ahmedali', 19, 77, 'کیا تو نے اس شخص کو دیکھا جس نے ہماری آیتوں کا انکار کیا اور کہتا ہے کہ مجھے ضرور مال اور اولاد ملے گی'),
  ('ur.ahmedali', 19, 78, 'کیا اس نے غیب پر اطلاع پائی ہے یا اس نے الله سے اقرار لے رکھا ہے'),
  ('ur.ahmedali', 19, 79, 'ہرگز نہیں ہم لکھ لیتے ہیں جو کچھ وہ کہتا ہے اور اس کے لیے عذاب بڑھاتے جاتے ہیں'),
  ('ur.ahmedali', 19, 80, 'اور ہم اس کے وارث ہوں گے جو کچھ وہ کہتا ہے او رہمارے ہاں تنہا آئے گا'),
  ('ur.ahmedali', 19, 81, 'اور انہوں نے الله کے سوا معبود بنا لیے ہیں تاکہ وہ ان کے مددگار ہوں'),
  ('ur.ahmedali', 19, 82, 'ہرگز نہیں وہ جلد ہی ان کی عبادت کا انکار کریں گے اور ان کے مخالف ہوجائیں گے'),
  ('ur.ahmedali', 19, 83, 'کیا تو نے نہیں دیکھا ہم نے شیطانو ں کوکافروں پر چھوڑ رکھا ہے وہ انھیں ابھارتے رہتے ہیں'),
  ('ur.ahmedali', 19, 84, 'سوتو ان کے لیے عذاب کی جلدی نہ کر ہم خود ان کے دن گن رہے ہیں'),
  ('ur.ahmedali', 19, 85, 'جس دن ہم پرہیزگاروں کے رحمان کے پاس مہمان بنا کر جمع کریں گے'),
  ('ur.ahmedali', 19, 86, 'اور گناہگاروں کو دوزخ کی طرف پیاسا ہانکیں گے'),
  ('ur.ahmedali', 19, 87, 'کسی کو سفارش کا اختیار نہیں ہوگا مگر جس نے رحمان کے ہاں سے اجازت لی ہو'),
  ('ur.ahmedali', 19, 88, 'اورکہتے ہیں کہ رحمان نے بیٹا بنا لیا'),
  ('ur.ahmedali', 19, 89, 'البتہ تحقیق تم سخت بات زبان پر لائے ہو'),
  ('ur.ahmedali', 19, 90, 'کہ جس سے ابھی آسمان پھٹ جائیں اور زمین چر جائے اور پہاڑ ٹکڑے ہو کر گر پڑیں'),
  ('ur.ahmedali', 19, 91, 'اس لئے کہ انہوں نے رحمان کے لیے بیٹا تجویز کیا'),
  ('ur.ahmedali', 19, 92, 'اور رحمان کی یہ شان نہیں کہ کسی کوبیٹا بنائے'),
  ('ur.ahmedali', 19, 93, 'جو کچھ آسمانوں اور زمین میں ہے ان میں سے ایسا کوئی نہیں جو رحمان کا بندہ بن کر نہ آئے'),
  ('ur.ahmedali', 19, 94, 'البتہ تحقیق اس نے انھیں شمار کر رکھا ہے اور ان کی گنتی گن رکھی ہے'),
  ('ur.ahmedali', 19, 95, 'او رہر ایک ان میں سے اس کے ہاں اکیلا آئے گا'),
  ('ur.ahmedali', 19, 96, 'بے شک جو ایمان لائے اور نیک کام کیے عنقریب رحمان ان کے لیے محبت پیدا کرے گالاشبہ جو لوگ ایمان لائے اور انہوں نے اچھے کام کیے الله تعالیٰ ان کے لیے محبت پیدا کر ے گا'),
  ('ur.ahmedali', 19, 97, 'سو ہم نے فرمان کو تیری زبان میں اس لیےآسان کیا ہے کہ تو اس سے پرہیز گاروں کو خوشخبری سنا دے اور جھگڑنے والوں کو ڈرا دے'),
  ('ur.ahmedali', 19, 98, 'اور ہم ان سے پہلے کئی جماعتیں ہلاک کر چکے ہیں کیا تو کسی کی ان میں سے آہٹ پاتا ہے یا ان کی بھنک سنتا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 19, 1, 'Kaf, Ha, Ya, Ayn, Sad.'),
  ('tr.diyanet', 19, 2, 'Bu, Rabbinin kulu Zekeriya\'ya olan rahmetini anmadır.'),
  ('tr.diyanet', 19, 3, 'O Rabbine içinden yalvarmıştı.'),
  ('tr.diyanet', 19, 4, 'Şöyle demişti: "Rabbim! Gerçekten kemiklerim zayıfladı, saçlarım ağardı. Rabbim! Sana yalvarmakla şimdiye kadar bedbaht olup bir şeyden mahrum kalmadım."'),
  ('tr.diyanet', 19, 5, 'Doğrusu, benden sonra yerime geçecek yakınlarımın iyi hareket etmeyeceklerinden korkuyorum. Karım da kısırdır. Katından bana bir oğul bağışla ki, bana ve Yakub oğullarına mirasçı olsun. Rabbim! Onun, rızanı kazanmasını da sağla."'),
  ('tr.diyanet', 19, 6, 'Doğrusu, benden sonra yerime geçecek yakınlarımın iyi hareket etmeyeceklerinden korkuyorum. Karım da kısırdır. Katından bana bir oğul bağışla ki, bana ve Yakub oğullarına mirasçı olsun. Rabbim! Onun, rızanı kazanmasını da sağla."'),
  ('tr.diyanet', 19, 7, 'Allah: "Ey Zekeriya! Sana, Yahya isminde bir oğlanı müjdeliyoruz. Bu adı daha önce kimseye vermemiştik" buyurdu.'),
  ('tr.diyanet', 19, 8, 'Zekeriya: "Rabbim! Karım kısır, ben de son derece kocamışken nasıl oğlum olabilir?" dedi.'),
  ('tr.diyanet', 19, 9, 'Allah: "Rabbin böyle buyurdu; Çünkü bu bana kolaydır, nitekim sen yokken daha önce seni yaratmıştım" dedi.'),
  ('tr.diyanet', 19, 10, 'Zekeriya "Rabbim! Öyleyse bana bir alamet ver" dedi. Allah: "Senin alametin, sağlam ve sıhhatli olduğun halde üç gün üç gece insanlarla konuşamamandır" buyurdu.'),
  ('tr.diyanet', 19, 11, 'Zekeriya bunun üzerine mabedden çıkıp milletine: "Sabah akşam Allah\'ı tesbih edin" diye işarette bulundu.'),
  ('tr.diyanet', 19, 12, '"Ey Yahya! Kitaba kuvvetle sarıl" deyip daha çocukken ona hikmet, katımızdan kalp yumuşaklığı ve safiyet verdik. O, Allah\'tan sakınan ve anasına babasına karşı iyi davranan bir kimse idi, baş kaldıran bir zorba değildi.'),
  ('tr.diyanet', 19, 13, '"Ey Yahya! Kitaba kuvvetle sarıl" deyip daha çocukken ona hikmet, katımızdan kalp yumuşaklığı ve safiyet verdik. O, Allah\'tan sakınan ve anasına babasına karşı iyi davranan bir kimse idi, baş kaldıran bir zorba değildi.'),
  ('tr.diyanet', 19, 14, '"Ey Yahya! Kitaba kuvvetle sarıl" deyip daha çocukken ona hikmet, katımızdan kalp yumuşaklığı ve safiyet verdik. O, Allah\'tan sakınan ve anasına babasına karşı iyi davranan bir kimse idi, baş kaldıran bir zorba değildi.'),
  ('tr.diyanet', 19, 15, 'Doğduğu günde, öleceği günde ve dirileceği günde ona selam olsun.'),
  ('tr.diyanet', 19, 16, 'Kitabda Meryem\'i de an. O, ailesinden ayrılarak, doğu yönünde bir yere çekilmişti.'),
  ('tr.diyanet', 19, 17, 'Sonra, insanlardan gizlenmek için bir perde germişti. Cebrail\'i göndermiştik de ona tam bir insan olarak görünmüştü.'),
  ('tr.diyanet', 19, 18, 'Meryem: "Eğer Allah\'tan sakınan bir kimse isen, senden Rahman\'a sığınırım" dedi.'),
  ('tr.diyanet', 19, 19, 'Cebrail: "Ben temiz bir oğlan bağışlamak için Rabbinin sana gönderdiği elçiden başkası değilim" dedi.'),
  ('tr.diyanet', 19, 20, 'Meryem: "Bana bir insan temas etmemişken, ben kötü kadın da olmadığım halde nasıl oğlum olabilir?" dedi.'),
  ('tr.diyanet', 19, 21, 'Cebrail: "Bu böyledir, çünkü Rabbin, \'Bu bana kolaydır, onu insanlar için bir mucize ve katımızdan da bir rahmet kılacağız; hem bu önceden kararlaştırılmış bir iştir\' diyor" dedi.'),
  ('tr.diyanet', 19, 22, 'Meryem oğlana gebe kaldı, o haliyle uzak bir yere çekildi.'),
  ('tr.diyanet', 19, 23, 'Doğum sancısı onu bir hurma ağacının dibine gitmeğe mecbur etti. "Keşke ben bundan önce ölmüş olsaydım da unutulup gitseydim" dedi.'),
  ('tr.diyanet', 19, 24, 'Onun altından bir ses kendisine şöyle seslendi: "Sakın üzülme, Rabbin içinde bulunanı şerefli kılmıştır. Hurma ağacını kendine doğru silkele, üstüne taze hurma dökülsün.'),
  ('tr.diyanet', 19, 25, 'Onun altından bir ses kendisine şöyle seslendi: "Sakın üzülme, Rabbin içinde bulunanı şerefli kılmıştır. Hurma ağacını kendine doğru silkele, üstüne taze hurma dökülsün.'),
  ('tr.diyanet', 19, 26, 'Ye iç, gözün aydın olsun. İnsanlardan birini görecek olursan \'Ben Rahman için oruç adadım, bugün hiçbir insanla konuşmayacağım\' de."'),
  ('tr.diyanet', 19, 27, 'Çocuğu alıp kavmine getirdi, onlar: "Meryem! Utanılacak bir şey yaptın. Ey Harun\'un kızkardeşi! Baban kötü bir kimse değildi, annen de iffetsiz değildi" dediler.'),
  ('tr.diyanet', 19, 28, 'Çocuğu alıp kavmine getirdi, onlar: "Meryem! Utanılacak bir şey yaptın. Ey Harun\'un kızkardeşi! Baban kötü bir kimse değildi, annen de iffetsiz değildi" dediler.'),
  ('tr.diyanet', 19, 29, 'Meryem çocuğu gösterdi. "Biz beşikteki çocukla nasıl konuşabiliriz?" dediler.'),
  ('tr.diyanet', 19, 30, 'Çocuk: "Ben şüphesiz Allah\'ın kuluyum. Bana kitap verdi ve beni peygamber yaptı, nerede olursam olayım beni mübarek kıldı. Yaşadığım müddetçe namaz kılmamı, zekat vermemi ve anneme iyi davranmamı emretti. Beni bedbaht bir zorba kılmadı. Doğduğum günde, öleceğim günde, dirileceğim günde bana selam olsun" dedi.'),
  ('tr.diyanet', 19, 31, 'Çocuk: "Ben şüphesiz Allah\'ın kuluyum. Bana kitap verdi ve beni peygamber yaptı, nerede olursam olayım beni mübarek kıldı. Yaşadığım müddetçe namaz kılmamı, zekat vermemi ve anneme iyi davranmamı emretti. Beni bedbaht bir zorba kılmadı. Doğduğum günde, öleceğim günde, dirileceğim günde bana selam olsun" dedi.'),
  ('tr.diyanet', 19, 32, 'Çocuk: "Ben şüphesiz Allah\'ın kuluyum. Bana kitap verdi ve beni peygamber yaptı, nerede olursam olayım beni mübarek kıldı. Yaşadığım müddetçe namaz kılmamı, zekat vermemi ve anneme iyi davranmamı emretti. Beni bedbaht bir zorba kılmadı. Doğduğum günde, öleceğim günde, dirileceğim günde bana selam olsun" dedi.'),
  ('tr.diyanet', 19, 33, 'Çocuk: "Ben şüphesiz Allah\'ın kuluyum. Bana kitap verdi ve beni peygamber yaptı, nerede olursam olayım beni mübarek kıldı. Yaşadığım müddetçe namaz kılmamı, zekat vermemi ve anneme iyi davranmamı emretti. Beni bedbaht bir zorba kılmadı. Doğduğum günde, öleceğim günde, dirileceğim günde bana selam olsun" dedi.'),
  ('tr.diyanet', 19, 34, 'İşte hakkında şüpheye düştükleri Meryem oğlu İsa gerçek söze göre budur.'),
  ('tr.diyanet', 19, 35, 'Allah çocuk edinmez, O münezzehtir. Bir işin olmasına hükmederse ona ancak "Ol" der, o da olur.'),
  ('tr.diyanet', 19, 36, '"Doğrusu Allah benim de sizin de Rabbinizdir. O\'na kulluk edin, bu doğru yoldur."'),
  ('tr.diyanet', 19, 37, 'Fırkalar, kendi aralarında anlaşmazlığa düştüler. Vay o büyük günü görecek kafirlerin haline!'),
  ('tr.diyanet', 19, 38, 'Bize geldikleri gün neler görüp neler işitecekler! Ama zalimler bugün apaçık bir sapıklık içindedirler.'),
  ('tr.diyanet', 19, 39, 'Hala gaflet içinde bulunanları ve hala inanmayanları işin bitmiş olacağı o hasret günü ile uyar.'),
  ('tr.diyanet', 19, 40, 'Şüphesiz Biz bütün yeryüzüne ve üzerinde bulunanlara varis olacağız. Onlar Bize döneceklerdir.'),
  ('tr.diyanet', 19, 41, 'Kitap\'da İbrahim\'e dair anlattıklarımızı da an, o şüphesiz dosdoğru bir peygamberdi.'),
  ('tr.diyanet', 19, 42, 'Babasına şöyle demişti: "Babacığım! İşitmeyen, görmeyen ve sana bir faydası olmayan şeylere niçin tapıyorsun?"'),
  ('tr.diyanet', 19, 43, '"Babacığım! Doğrusu sana gelmeyen bir ilim bana geldi. Bana uy, seni doğru yola eriştireyim."'),
  ('tr.diyanet', 19, 44, '"Babacığım! Şeytana tapma, çünkü şeytan Rahman\'a baş kaldırmıştır"'),
  ('tr.diyanet', 19, 45, '"Babacığım! Doğrusu sana Rahman katından bir azabın gelmesinden korkuyorum ki böylece şeytanın dostu olarak kalırsın."'),
  ('tr.diyanet', 19, 46, 'Babası: "Ey İbrahim! Sen benim tanrılarımdan yüz çevirmek mi istiyorsun? Bundan vazgeçmezsen mutlaka seni taşlarım; uzun bir süre benden uzaklaş git." dedi.'),
  ('tr.diyanet', 19, 47, 'İbrahim şöyle cevap verdi: "Sana selam olsun. Senin için Rabbim\'den mağfiret dileyeceğim, çünkü O, bana karşı çok lütufkardır."'),
  ('tr.diyanet', 19, 48, '"Sizi Allah\'tan başka taptıklarınızla bırakıp çekilir, Rabbime yalvarırım. Rabbime yalvarışımda mahrum kalmayacağımı umarım."'),
  ('tr.diyanet', 19, 49, 'İbrahim onları Allah\'tan başka taptıklarıyla başbaşa bırakıp çekilince ona İshak ve Yakub\'u bahşettik ve her birini peygamber yaptık.'),
  ('tr.diyanet', 19, 50, 'Onlara rahmetimizden bağışta bulunduk. Onların her dilde üstün şekilde anılmalarını sağladık.'),
  ('tr.diyanet', 19, 51, 'Kitap\'da Musa\'ya dair anlattıklarımızı da an. O seçkin kılınmış bir insan, tarafımızdan gönderilmiş bir peygamberdi.'),
  ('tr.diyanet', 19, 52, 'Ona Tur\'un sağ yanından seslenmiş ve konuşmak için onu yaklaştırmıştık.'),
  ('tr.diyanet', 19, 53, 'Rahmetimizden, kardeşi Harun\'u bir peygamber olarak ona bağışladık.'),
  ('tr.diyanet', 19, 54, 'Kitap\'da İsmail\'e dair anlattıklarımızı da an. Çünkü o sözünde doğru bir kimse idi, tarafımızdan gönderilmiş bir peygamberdi.'),
  ('tr.diyanet', 19, 55, 'Çevresinde bulunanlara namaz kılmalarını, zekat vermelerini emrederdi. Rabbinin katında hoşnutluğa ermişti.'),
  ('tr.diyanet', 19, 56, 'Kitap\'da İdris\'i de zikret, çünkü o dosdoğru bir peygamberdi.'),
  ('tr.diyanet', 19, 57, 'Biz onu yüce bir yere yükselttik.'),
  ('tr.diyanet', 19, 58, 'İşte bunlar Allah\'ın kendilerine nimetler sunduğu peygamberler; Adem\'in soyundan, Nuh ile beraber taşıdıklarımızdan; İbrahim ve İsmail\'in neslinden ve doğru yola erdirdiğimizden, seçip beğendiklerimizdendirler. Rahman\'ın ayetleri onlara okunduğu zaman ağlayarak secdeye kapanırlardı.'),
  ('tr.diyanet', 19, 59, 'Onların ardından, namazı bırakan, şehvetlerine uyan bir nesil geldi. İşte bunlar azgınlıklarının karşılığını göreceklerdir.'),
  ('tr.diyanet', 19, 60, 'Ancak tevbe eden, inanıp yararlı iş yapanlar bunun dışındadır. Bunlar hiçbir haksızlığa uğratılmadan, Rahman\'ın kullarına gaybde vadettiği cennete, Adn cennetlerine gireceklerdir. Şüphesiz, O\'nun sözü yerini bulacaktır.'),
  ('tr.diyanet', 19, 61, 'Ancak tevbe eden, inanıp yararlı iş yapanlar bunun dışındadır. Bunlar hiçbir haksızlığa uğratılmadan, Rahman\'ın kullarına gaybde vadettiği cennete, Adn cennetlerine gireceklerdir. Şüphesiz, O\'nun sözü yerini bulacaktır.'),
  ('tr.diyanet', 19, 62, 'Orada boş sözler değil sadece esenlik veren sözler işitirler. Orada rızıklarını sabah akşam hazır bulurlar.'),
  ('tr.diyanet', 19, 63, 'Kullarımızdan Allah\'a karşı gelmekten sakınanları mirasçı kılacağımız Cennet işte budur.'),
  ('tr.diyanet', 19, 64, 'Cebrail: "Biz ancak Rabbinin buyruğu ile ineriz, geçmişimizi geleceğimizi ve ikisinin arasındakileri bilmek O\'na mahsustur. Rabbin unutkan değildir."'),
  ('tr.diyanet', 19, 65, 'O, göklerin, yerin ve ikisi arasında bulunanların Rabbidir. Öyleyse Ona ibadette sabırlı ol. Hiç O\'na benzeyen bir şey bilir misin?'),
  ('tr.diyanet', 19, 66, 'İnsan: "Ben öldüğümde mi diriltileceğim?" der.'),
  ('tr.diyanet', 19, 67, 'Bu insan kendisi önceden bir şey değilken onu yaratmış olduğumuzu hatırlamaz mi?'),
  ('tr.diyanet', 19, 68, 'Rabbine and olsun ki Biz onları mutlaka uydukları şeytanlarla beraber haşredeceğiz. Sonra cehennemin yanında diz çöktürerek hazır bulunduracağız.'),
  ('tr.diyanet', 19, 69, 'Sonra her toplumdan Rahman\'a en çok kimin baş kaldırdığını ortaya koyacağız.'),
  ('tr.diyanet', 19, 70, 'Cehenneme girmeye en layık olanları Biz biliriz.'),
  ('tr.diyanet', 19, 71, 'Sizden cehenneme uğramayacak yoktur. Bu, Rabbinin yapmayı üzerine aldığı kesinleşmiş bir hükümdür.'),
  ('tr.diyanet', 19, 72, 'Sonra Biz Allah\'a karşı gelmekten sakınmış olanları kurtarır, zalimleri de orada diz üstü çökmüş olarak bırakırız.'),
  ('tr.diyanet', 19, 73, 'Ayetlerimiz kendilerine apaçık okunduğu zaman inkar edenler inananlara: "Bu iki takımın hangisinin makamı daha iyi ve yeri daha güzeldir?" derler.'),
  ('tr.diyanet', 19, 74, 'Onlardan önce nice nesilleri yok ettik ki, onlar varlıkça ve gösterişçe bunlardan daha üstündüler.'),
  ('tr.diyanet', 19, 75, 'De ki: "Sapıklıkta olanı Rahman ne kadar ertelese bile, sonunda tehdit edildikleri azabı ya da kıyamet gününü gördükleri zaman onlar kimin yerinin daha kötü ve taraftarlarının daha güçsüz olduğunu bilecektir."'),
  ('tr.diyanet', 19, 76, 'Allah doğru yolda olanların doğruluğunu artırır. Baki kalacak yararlı işler Rabbinin katında sevap olarak da daha iyidir, sonuç olarak da daha iyidir.'),
  ('tr.diyanet', 19, 77, 'Ayetlerimizi inkar eden ve "bana elbette mal ve çocuk verilecektir" diyeni gördün mu?'),
  ('tr.diyanet', 19, 78, 'O görülmeyeni mi biliyor, yoksa Rahman katından bir söz mü almıştır?'),
  ('tr.diyanet', 19, 79, 'Hayır, söylediğini yazacağız ve onun azabını uzattıkça uzatacağız.'),
  ('tr.diyanet', 19, 80, 'Bahsettikleri şeyler Bize kalacaktır, kendisi Bize tek olarak gelecektir.'),
  ('tr.diyanet', 19, 81, 'Onlar kendilerine kuvvet ve şeref kazandırsın diye, Allah\'ı bırakarak tanrılar edindiler.'),
  ('tr.diyanet', 19, 82, 'Hayır, tanrıları kendilerinin ibadetlerini inkar edecekler ve onlara düşman olacaklardır.'),
  ('tr.diyanet', 19, 83, 'Kafirlerin üzerine onları kışkırtan şeytanlar gönderdiğimizi bilmiyor musun?'),
  ('tr.diyanet', 19, 84, 'Öyleyse onların acele yok olmalarını isteme. Biz onların günlerini saydıkça sayıyoruz.'),
  ('tr.diyanet', 19, 85, 'sakınanları o gün Rahman\'ın huzurunda O\'na gelmiş konuklar olarak toplarız, suçluları suya götürür gibi cehenneme süreriz.'),
  ('tr.diyanet', 19, 86, 'sakınanları o gün Rahman\'ın huzurunda O\'na gelmiş konuklar olarak toplarız, suçluları suya götürür gibi cehenneme süreriz.'),
  ('tr.diyanet', 19, 87, 'Rahman\'ın katında bir ahd almış olandan başkası asla şefaatte bulunamıyacaktır.'),
  ('tr.diyanet', 19, 88, 'Bazı kimseler: "Rahman çocuk edindi" dediler'),
  ('tr.diyanet', 19, 89, 'And olsun ki, ortaya pek kötü bir şey attınız.'),
  ('tr.diyanet', 19, 90, 'Rahman\'a çocuk isnat etmelerinden ötürü neredeyse gökler parçalanacak, yer yarılacak, dağlar göçecekti.'),
  ('tr.diyanet', 19, 91, 'Rahman\'a çocuk isnat etmelerinden ötürü neredeyse gökler parçalanacak, yer yarılacak, dağlar göçecekti.'),
  ('tr.diyanet', 19, 92, 'Oysa Rahman\'a çocuk edinmek yaraşmaz, çünkü göklerde ve yerde olan her şey Rahman\'a baş eğmiş kul olarak gelecektir.'),
  ('tr.diyanet', 19, 93, 'Oysa Rahman\'a çocuk edinmek yaraşmaz, çünkü göklerde ve yerde olan her şey Rahman\'a baş eğmiş kul olarak gelecektir.'),
  ('tr.diyanet', 19, 94, 'And olsun ki onların adedini bilmiş ve teker teker saymıştır.'),
  ('tr.diyanet', 19, 95, 'Kıyamet günü hepsi O\'na tek olarak gelecektir.'),
  ('tr.diyanet', 19, 96, 'İnanıp yararlı iş işleyenleri Rahman sevgili kılacaktır.'),
  ('tr.diyanet', 19, 97, 'Biz Kuran\'ı Allah\'a karşı gelmekten sakınanları müjdelemen ve inatçı milleti uyarman için senin dilinde indirerek kolaylaştırdık.'),
  ('tr.diyanet', 19, 98, 'Onlardan önce nice nesilleri yok ettik, şimdi onlardan hiçbirini duyuyor veya bir ses işitiyor musun?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 19, 1, 'Kaaf Haa Yaa \'Ain Shaad.'),
  ('id.indonesian', 19, 2, '(Yang dibacakan ini adalah) penjelasan tentang rahmat Tuhan kamu kepada hamba-Nya, Zakaria,'),
  ('id.indonesian', 19, 3, 'yaitu tatkala ia berdoa kepada Tuhannya dengan suara yang lembut.'),
  ('id.indonesian', 19, 4, 'Ia berkata "Ya Tuhanku, sesungguhnya tulangku telah lemah dan kepalaku telah ditumbuhi uban, dan aku belum pernah kecewa dalam berdoa kepada Engkau, ya Tuhanku.'),
  ('id.indonesian', 19, 5, 'Dan sesungguhnya aku khawatir terhadap mawaliku sepeninggalku, sedang isteriku adalah seorang yang mandul, maka anugerahilah aku dari sisi Engkau seorang putera,'),
  ('id.indonesian', 19, 6, 'yang akan mewarisi aku dan mewarisi sebahagian keluarga Ya\'qub; dan jadikanlah ia, ya Tuhanku, seorang yang diridhai".'),
  ('id.indonesian', 19, 7, 'Hai Zakaria, sesungguhnya Kami memberi kabar gembira kepadamu akan (beroleh) seorang anak yang namanya Yahya, yang sebelumnya Kami belum pernah menciptakan orang yang serupa dengan dia.'),
  ('id.indonesian', 19, 8, 'Zakaria berkata: "Ya Tuhanku, bagaimana akan ada anak bagiku, padahal isteriku adalah seorang yang mandul dan aku (sendiri) sesungguhnya sudah mencapai umur yang sangat tua".'),
  ('id.indonesian', 19, 9, 'Tuhan berfirman: "Demikianlah". Tuhan berfirman: "Hal itu adalah mudah bagi-Ku; dan sesunguhnya telah Aku ciptakan kamu sebelum itu, padahal kamu (di waktu itu) belum ada sama sekali".'),
  ('id.indonesian', 19, 10, 'Zakaria berkata: "Ya Tuhanku, berilah aku suatu tanda". Tuhan berfirman: "Tanda bagimu ialah bahwa kamu tidak dapat bercakap-cakap dengan manusia selama tiga malam, padahal kamu sehat".'),
  ('id.indonesian', 19, 11, 'Maka ia keluar dari mihrab menuju kaumnya, lalu ia memberi isyarat kepada mereka; hendaklah kamu bertasbih di waktu pagi dan petang.'),
  ('id.indonesian', 19, 12, 'Hai Yahya, ambillah Al Kitab (Taurat) itu dengan sungguh-sungguh. Dan kami berikan kepadanya hikmah selagi ia masih kanak-kanak,'),
  ('id.indonesian', 19, 13, 'dan rasa belas kasihan yang mendalam dari sisi Kami dan kesucian (dan dosa). Dan ia adalah seorang yang bertakwa,'),
  ('id.indonesian', 19, 14, 'dan seorang yang berbakti kepada kedua orang tuanya, dan bukanlah ia orang yang sombong lagi durhaka.'),
  ('id.indonesian', 19, 15, 'Kesejahteraan atas dirinya pada hari ia dilahirkan dan pada hari ia meninggal dan pada hari ia dibangkitkan hidup kembali.'),
  ('id.indonesian', 19, 16, 'Dan ceritakanlah (kisah) Maryam di dalam Al Quran, yaitu ketika ia menjauhkan diri dari keluarganya ke suatu tempat di sebelah timur,'),
  ('id.indonesian', 19, 17, 'maka ia mengadakan tabir (yang melindunginya) dari mereka; lalu Kami mengutus roh Kami kepadanya, maka ia menjelma di hadapannya (dalam bentuk) manusia yang sempurna.'),
  ('id.indonesian', 19, 18, 'Maryam berkata: "Sesungguhnya aku berlindung dari padamu kepada Tuhan Yang Maha pemurah, jika kamu seorang yang bertakwa".'),
  ('id.indonesian', 19, 19, 'Ia (jibril) berkata: "Sesungguhnya aku ini hanyalah seorang utusan Tuhanmu, untuk memberimu seorang anak laki-laki yang suci".'),
  ('id.indonesian', 19, 20, 'Maryam berkata: "Bagaimana akan ada bagiku seorang anak laki-laki, sedang tidak pernah seorang manusiapun menyentuhku dan aku bukan (pula) seorang pezina!"'),
  ('id.indonesian', 19, 21, 'Jibril berkata: "Demikianlah". Tuhanmu berfirman: "Hal itu adalah mudah bagi-Ku; dan agar dapat Kami menjadikannya suatu tanda bagi manusia dan sebagai rahmat dari Kami; dan hal itu adalah suatu perkara yang sudah diputuskan".'),
  ('id.indonesian', 19, 22, 'Maka Maryam mengandungnya, lalu ia menyisihkan diri dengan kandungannya itu ke tempat yang jauh.'),
  ('id.indonesian', 19, 23, 'Maka rasa sakit akan melahirkan anak memaksa ia (bersandar) pada pangkal pohon kurma, dia berkata: "Aduhai, alangkah baiknya aku mati sebelum ini, dan aku menjadi barang yang tidak berarti, lagi dilupakan".'),
  ('id.indonesian', 19, 24, 'Maka Jibril menyerunya dari tempat yang rendah: "Janganlah kamu bersedih hati, sesungguhnya Tuhanmu telah menjadikan anak sungai di bawahmu.'),
  ('id.indonesian', 19, 25, 'Dan goyanglah pangkal pohon kurma itu ke arahmu, niscaya pohon itu akan menggugurkan buah kurma yang masak kepadamu,'),
  ('id.indonesian', 19, 26, 'maka makan, minum dan bersenang hatilah kamu. Jika kamu melihat seorang manusia, maka katakanlah: "Sesungguhnya aku telah bernazar berpuasa untuk Tuhan Yang Maha Pemurah, maka aku tidak akan berbicara dengan seorang manusiapun pada hari ini".'),
  ('id.indonesian', 19, 27, 'Maka Maryam membawa anak itu kepada kaumnya dengan menggendongnya. Kaumnya berkata: "Hai Maryam, sesungguhnya kamu telah melakukan sesuatu yang amat mungkar.'),
  ('id.indonesian', 19, 28, 'Hai saudara perempuan Harun, ayahmu sekali-kali bukanlah seorang yang jahat dan ibumu sekali-kali bukanlah seorang pezina",'),
  ('id.indonesian', 19, 29, 'maka Maryam menunjuk kepada anaknya. Mereka berkata: "Bagaimana kami akan berbicara dengan anak kecil yang masih di dalam ayunan?"'),
  ('id.indonesian', 19, 30, 'Berkata Isa: "Sesungguhnya aku ini hamba Allah, Dia memberiku Al Kitab (Injil) dan Dia menjadikan aku seorang nabi,'),
  ('id.indonesian', 19, 31, 'dan Dia menjadikan aku seorang yang diberkati di mana saja aku berada, dan Dia memerintahkan kepadaku (mendirikan) shalat dan (menunaikan) zakat selama aku hidup;'),
  ('id.indonesian', 19, 32, 'dan berbakti kepada ibuku, dan Dia tidak menjadikan aku seorang yang sombong lagi celaka.'),
  ('id.indonesian', 19, 33, 'Dan kesejahteraan semoga dilimpahkan kepadaku, pada hari aku dilahirkan, pada hari aku meninggal dan pada hari aku dibangkitkan hidup kembali".'),
  ('id.indonesian', 19, 34, 'Itulah Isa putera Maryam, yang mengatakan perkataan yang benar, yang mereka berbantah-bantahan tentang kebenarannya.'),
  ('id.indonesian', 19, 35, 'Tidak layak bagi Allah mempunyai anak, Maha Suci Dia. Apabila Dia telah menetapkan sesuatu, maka Dia hanya berkata kepadanya: "Jadilah", maka jadilah ia.'),
  ('id.indonesian', 19, 36, 'Sesungguhnya Allah adalah Tuhanku dan Tuhanmu, maka sembahIah Dia oleh kamu sekalian. Ini adalah jalan yang lurus.'),
  ('id.indonesian', 19, 37, 'Maka berselisihlah golongan-golongan (yang ada) di antara mereka. Maka kecelakaanlah bagi orang-orang kafir pada waktu menyaksikan hari yang besar.'),
  ('id.indonesian', 19, 38, 'Alangkah terangnya pendengaran mereka dan alangkah tajamnya penglihatan mereka pada hari mereka datang kepada Kami. Tetapi orang-orang yang zalim pada hari ini (di dunia) berada dalam kesesatan yang nyata.'),
  ('id.indonesian', 19, 39, 'Dan berilah mereka peringatan tentang hari penyesalan, (yaitu) ketika segala perkara telah diputus. Dan mereka dalam kelalaian dan mereka tidak (pula) beriman.'),
  ('id.indonesian', 19, 40, 'Sesungguhnya Kami mewarisi bumi dan semua orang-orang yang ada di atasnya, dan hanya kepada Kamilah mereka dikembalikan.'),
  ('id.indonesian', 19, 41, 'Ceritakanlah (Hai Muhammad) kisah Ibrahim di dalam Al Kitab (Al Quran) ini. Sesungguhnya ia adalah seorang yang sangat membenarkan lagi seorang Nabi.'),
  ('id.indonesian', 19, 42, 'Ingatlah ketika ia berkata kepada bapaknya; "Wahai bapakku, mengapa kamu menyembah sesuatu yang tidak mendengar, tidak melihat dan tidak dapat menolong kamu sedikitpun?'),
  ('id.indonesian', 19, 43, 'Wahai bapakku, sesungguhnya telah datang kepadaku sebahagian ilmu pengetahuan yang tidak datang kepadamu, maka ikutilah aku, niscaya aku akan menunjukkan kepadamu jalan yang lurus.'),
  ('id.indonesian', 19, 44, 'Wahai bapakku, janganlah kamu menyembah syaitan. Sesungguhnya syaitan itu durhaka kepada Tuhan Yang Maha Pemurah.'),
  ('id.indonesian', 19, 45, 'Wahai bapakku, sesungguhnya aku khawatir bahwa kamu akan ditimpa azab dari Tuhan Yang Maha Pemurah, maka kamu menjadi kawan bagi syaitan".'),
  ('id.indonesian', 19, 46, 'Berkata bapaknya: "Bencikah kamu kepada tuhan-tuhanku, hai Ibrahim? Jika kamu tidak berhenti, maka niscaya kamu akan kurajam, dan tinggalkanlah aku buat waktu yang lama".'),
  ('id.indonesian', 19, 47, 'Berkata Ibrahim: "Semoga keselamatan dilimpahkan kepadamu, aku akan memintakan ampun bagimu kepada Tuhanku. Sesungguhnya Dia sangat baik kepadaku.'),
  ('id.indonesian', 19, 48, 'Dan aku akan menjauhkan diri darimu dan dari apa yang kamu seru selain Allah, dan aku akan berdoa kepada Tuhanku, mudah-mudahan aku tidak akan kecewa dengan berdoa kepada Tuhanku".'),
  ('id.indonesian', 19, 49, 'Maka ketika Ibrahim sudah menjauhkan diri dari mereka dan dari apa yang mereka sembah selain Allah, Kami anugerahkan kepadanya Ishak, dan Ya\'qub. Dan masing-masingnya Kami angkat menjadi nabi.'),
  ('id.indonesian', 19, 50, 'Dan Kami anugerahkan kepada mereka sebagian dari rahmat Kami dan Kami jadikan mereka buah tutur yang baik lagi tinggi.'),
  ('id.indonesian', 19, 51, 'Dan ceritakanlah (hai Muhammad kepada mereka), kisah Musa di dalam Al Kitab (Al Quran) ini. Sesungguhnya ia adalah seorang yang dipilih dan seorang rasul dan nabi.'),
  ('id.indonesian', 19, 52, 'Dan Kami telah memanggilnya dari sebelah kanan gunung Thur dan Kami telah mendekatkannya kepada Kami di waktu dia munajat (kepada Kami).'),
  ('id.indonesian', 19, 53, 'Dan Kami telah menganugerahkan kepadanya sebagian rahmat Kami, yaitu saudaranya, Harun menjadi seorang nabi.'),
  ('id.indonesian', 19, 54, 'Dan ceritakanlah (hai Muhammad kepada mereka) kisah Ismail (yang tersebut) di dalam Al Quran. Sesungguhnya ia adalah seorang yang benar janjinya, dan dia adalah seorang rasul dan nabi.'),
  ('id.indonesian', 19, 55, 'Dan ia menyuruh ahlinya untuk bersembahyang dan menunaikan zakat, dan ia adalah seorang yang diridhai di sisi Tuhannya.'),
  ('id.indonesian', 19, 56, 'Dan ceritakanlah (hai Muhammad kepada mereka, kisah) Idris (yang tersebut) di dalam Al Quran. Sesungguhnya ia adalah seorang yang sangat membenarkan dan seorang nabi.'),
  ('id.indonesian', 19, 57, 'Dan Kami telah mengangkatnya ke martabat yang tinggi.'),
  ('id.indonesian', 19, 58, 'Mereka itu adalah orang-orang yang telah diberi nikmat oleh Allah, yaitu para nabi dari keturunan Adam, dan dari orang-orang yang Kami angkat bersama Nuh, dan dari keturunan Ibrahim dan Israil, dan dari orang-orang yang telah Kami beri petunjuk dan telah Kami pilih. Apabila dibacakan ayat-ayat Allah Yang Maha Pemurah kepada mereka, maka mereka menyungkur dengan bersujud dan menangis.'),
  ('id.indonesian', 19, 59, 'Maka datanglah sesudah mereka, pengganti (yang jelek) yang menyia-nyiakan shalat dan memperturutkan hawa nafsunya, maka mereka kelak akan menemui kesesatan,'),
  ('id.indonesian', 19, 60, 'kecuali orang yang bertaubat, beriman dan beramal saleh, maka mereka itu akan masuk surga dan tidak dianiaya (dirugikan) sedikitpun,'),
  ('id.indonesian', 19, 61, 'yaitu surga \'Adn yang telah dijanjikan oleh Tuhan Yang Maha Pemurah kepada hamba-hamba-Nya, sekalipun (surga itu) tidak nampak. Sesungguhnya janji Allah itu pasti akan ditepati.'),
  ('id.indonesian', 19, 62, 'Mereka tidak mendengar perkataan yang tak berguna di dalam surga, kecuali ucapan salam. Bagi mereka rezekinya di surga itu tiap-tiap pagi dan petang.'),
  ('id.indonesian', 19, 63, 'Itulah surga yang akan Kami wariskan kepada hamba-hamba Kami yang selalu bertakwa.'),
  ('id.indonesian', 19, 64, 'Dan tidaklah kami (Jibril) turun, kecuali dengan perintah Tuhanmu. Kepunyaan-Nya-lah apa-apa yang ada di hadapan kita, apa-apa yang ada di belakang kita dan apa-apa yang ada di antara keduanya, dan tidaklah Tuhanmu lupa.'),
  ('id.indonesian', 19, 65, 'Tuhan (yang menguasai) langit dan bumi dan apa-apa yang ada di antara keduanya, maka sembahlah Dia dan berteguh hatilah dalam beribadat kepada-Nya. Apakah kamu mengetahui ada seorang yang sama dengan Dia (yang patut disembah)?'),
  ('id.indonesian', 19, 66, 'Dan berkata manusia: "Betulkah apabila aku telah mati, bahwa aku sungguh-sungguh akan dibangkitkan menjadi hidup kembali?"'),
  ('id.indonesian', 19, 67, 'Dan tidakkah manusia itu memikirkan bahwa sesungguhnya Kami telah menciptakannya dahulu, sedang ia tidak ada sama sekali?'),
  ('id.indonesian', 19, 68, 'Demi Tuhanmu, sesungguhnya akan Kami bangkitkan mereka bersama syaitan, kemudian akan Kami datangkan mereka ke sekeliling Jahannam dengan berlutut.'),
  ('id.indonesian', 19, 69, 'Kemudian pasti akan Kami tarik dari tiap-tiap golongan siapa di antara mereka yang sangat durhaka kepada Tuhan Yang Maha Pemurah.'),
  ('id.indonesian', 19, 70, 'Dan kemudian Kami sungguh lebih mengetahui orang-orang yang seharusnya dimasukkan ke dalam neraka.'),
  ('id.indonesian', 19, 71, 'Dan tidak ada seorangpun dari padamu, melainkan mendatangi neraka itu. Hal itu bagi Tuhanmu adalah suatu kemestian yang sudah ditetapkan.'),
  ('id.indonesian', 19, 72, 'Kemudian Kami akan menyelamatkan orang-orang yang bertakwa dan membiarkan orang-orang yang zalim di dalam neraka dalam keadaan berlutut.'),
  ('id.indonesian', 19, 73, 'Dan apabila dibacakan kepada mereka ayat-ayat Kami yang terang (maksudnya), niscaya orang-orang yang kafir berkata kepada orang-orang yang beriman: "Manakah di antara kedua golongan (kafir dan mukmin) yang lebih baik tempat tinggalnya dan lebih indah tempat pertemuan(nya)?"'),
  ('id.indonesian', 19, 74, 'Berapa banyak umat yang telah Kami binasakan sebelum mereka, sedang mereka adalah lebih bagus alat rumah tangganya dan lebih sedap di pandang mata.'),
  ('id.indonesian', 19, 75, 'Katakanlah: "Barang siapa yang berada di dalam kesesatan, maka biarlah Tuhan yang Maha Pemurah memperpanjang tempo baginya; sehingga apabila mereka telah melihat apa yang diancamkan kepadanya, baik siksa maupun kiamat, maka mereka akan mengetahui siapa yang lebih jelek kedudukannya dan lebih lemah penolong-penolongnya".'),
  ('id.indonesian', 19, 76, 'Dan Allah akan menambah petunjuk kepada mereka yang telah mendapat petunjuk. Dan amal-amal saleh yang kekal itu lebih baik pahalanya di sisi Tuhanmu dan lebih baik kesudahannya.'),
  ('id.indonesian', 19, 77, 'Maka apakah kamu telah melihat orang yang kafir kepada ayat-ayat Kami dan ia mengatakan: "Pasti aku akan diberi harta dan anak".'),
  ('id.indonesian', 19, 78, 'Adakah ia melihat yang ghaib atau ia telah membuat perjanjian di sisi Tuhan Yang Maha Pemurah?,'),
  ('id.indonesian', 19, 79, 'sekali-kali tidak, Kami akan menulis apa yang ia katakan, dan benar-benar Kami akan memperpanjang azab untuknya,'),
  ('id.indonesian', 19, 80, 'dan Kami akan mewarisi apa yang ia katakan itu, dan ia akan datang kepada Kami dengan seorang diri.'),
  ('id.indonesian', 19, 81, 'Dan mereka telah mengambil sembahan-sembahan selain Allah, agar sembahan-sembahan itu menjadi pelindung bagi mereka,'),
  ('id.indonesian', 19, 82, 'sekali-kali tidak. Kelak mereka (sembahan-sembahan) itu akan mengingkari penyembahan (pengikut-pengikutnya) terhadapnya, dan mereka (sembahan-sembahan) itu akan menjadi musuh bagi mereka.'),
  ('id.indonesian', 19, 83, 'Tidakkah kamu lihat, bahwasanya Kami telah mengirim syaitan-syaitan itu kepada orang-orang kafir untuk menghasung mereka berbuat maksiat dengan sungguh-sungguh?,'),
  ('id.indonesian', 19, 84, 'maka janganlah kamu tergesa-gesa memintakan siksa terhadap mereka, karena sesungguhnya Kami hanya menghitung datangnya (hari siksaan) untuk mereka dengan perhitungan yang teliti.'),
  ('id.indonesian', 19, 85, '(Ingatlah) hari (ketika) Kami mengumpulkan orang-orang yang takwa kepada Tuhan Yang Maha Pemurah sebagai perutusan yang terhormat,'),
  ('id.indonesian', 19, 86, 'dan Kami akan menghalau orang-orang yang durhaka ke neraka Jahannam dalam keadaan dahaga.'),
  ('id.indonesian', 19, 87, 'Mereka tidak berhak mendapat syafa\'at kecuali orang yang telah mengadakan perjanjian di sisi Tuhan Yang Maha Pemurah.'),
  ('id.indonesian', 19, 88, 'Dan mereka berkata: "Tuhan Yang Maha Pemurah mengambil (mempunyai) anak".'),
  ('id.indonesian', 19, 89, 'Sesungguhnya kamu telah mendatangkan sesuatu perkara yang sangat mungkar,'),
  ('id.indonesian', 19, 90, 'hampir-hampir langit pecah karena ucapan itu, dan bumi belah, dan gunung-gunung runtuh,'),
  ('id.indonesian', 19, 91, 'karena mereka mendakwakan Allah Yang Maha Pemurah mempunyai anak.'),
  ('id.indonesian', 19, 92, 'Dan tidak layak bagi Tuhan Yang Maha Pemurah mengambil (mempunyai) anak.'),
  ('id.indonesian', 19, 93, 'Tidak ada seorangpun di langit dan di bumi, kecuali akan datang kepada Tuhan Yang Maha Pemurah selaku seorang hamba.'),
  ('id.indonesian', 19, 94, 'Sesungguhnya Allah telah menentukan jumlah mereka dan menghitung mereka dengan hitungan yang teliti.'),
  ('id.indonesian', 19, 95, 'Dan tiap-tiap mereka akan datang kepada Allah pada hari kiamat dengan sendiri-sendiri.'),
  ('id.indonesian', 19, 96, 'Sesungguhnya orang-orang yang beriman dan beramal saleh, kelak Allah Yang Maha Pemurah akan menanamkan dalam (hati) mereka rasa kasih sayang.'),
  ('id.indonesian', 19, 97, 'Maka sesungguhnya telah Kami mudahkan Al Quran itu dengan bahasamu, agar kamu dapat memberi kabar gembira dengan Al Quran itu kepada orang-orang yang bertakwa, dan agar kamu memberi peringatan dengannya kepada kaum yang membangkang.'),
  ('id.indonesian', 19, 98, 'Dan berapa banyak telah Kami binasakan umat-umat sebelum mereka. Adakah kamu melihat seorangpun dari mereka atau kamu dengar suara mereka yang samar-samar?')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (18, 61, 2201, 'فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ سَرَبًۭا', 300, 15, 120, 0),
  (18, 62, 2202, 'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدْ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبًۭا', 301, 15, 120, 0),
  (18, 63, 2203, 'قَالَ أَرَءَيْتَ إِذْ أَوَيْنَآ إِلَى ٱلصَّخْرَةِ فَإِنِّى نَسِيتُ ٱلْحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيْطَٰنُ أَنْ أَذْكُرَهُۥ ۚ وَٱتَّخَذَ سَبِيلَهُۥ فِى ٱلْبَحْرِ عَجَبًۭا', 301, 15, 120, 0),
  (18, 64, 2204, 'قَالَ ذَٰلِكَ مَا كُنَّا نَبْغِ ۚ فَٱرْتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصًۭا', 301, 15, 120, 0),
  (18, 65, 2205, 'فَوَجَدَا عَبْدًۭا مِّنْ عِبَادِنَآ ءَاتَيْنَٰهُ رَحْمَةًۭ مِّنْ عِندِنَا وَعَلَّمْنَٰهُ مِن لَّدُنَّا عِلْمًۭا', 301, 15, 120, 0),
  (18, 66, 2206, 'قَالَ لَهُۥ مُوسَىٰ هَلْ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمْتَ رُشْدًۭا', 301, 15, 120, 0),
  (18, 67, 2207, 'قَالَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًۭا', 301, 15, 120, 0),
  (18, 68, 2208, 'وَكَيْفَ تَصْبِرُ عَلَىٰ مَا لَمْ تُحِطْ بِهِۦ خُبْرًۭا', 301, 15, 120, 0),
  (18, 69, 2209, 'قَالَ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ صَابِرًۭا وَلَآ أَعْصِى لَكَ أَمْرًۭا', 301, 15, 120, 0),
  (18, 70, 2210, 'قَالَ فَإِنِ ٱتَّبَعْتَنِى فَلَا تَسْـَٔلْنِى عَن شَىْءٍ حَتَّىٰٓ أُحْدِثَ لَكَ مِنْهُ ذِكْرًۭا', 301, 15, 120, 0),
  (18, 71, 2211, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِى ٱلسَّفِينَةِ خَرَقَهَا ۖ قَالَ أَخَرَقْتَهَا لِتُغْرِقَ أَهْلَهَا لَقَدْ جِئْتَ شَيْـًٔا إِمْرًۭا', 301, 15, 120, 0),
  (18, 72, 2212, 'قَالَ أَلَمْ أَقُلْ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًۭا', 301, 15, 120, 0),
  (18, 73, 2213, 'قَالَ لَا تُؤَاخِذْنِى بِمَا نَسِيتُ وَلَا تُرْهِقْنِى مِنْ أَمْرِى عُسْرًۭا', 301, 15, 120, 0),
  (18, 74, 2214, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمًۭا فَقَتَلَهُۥ قَالَ أَقَتَلْتَ نَفْسًۭا زَكِيَّةًۢ بِغَيْرِ نَفْسٍۢ لَّقَدْ جِئْتَ شَيْـًۭٔا نُّكْرًۭا', 301, 15, 120, 0),
  (18, 75, 2215, '۞ قَالَ أَلَمْ أَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِىَ صَبْرًۭا', 302, 16, 121, 0),
  (18, 76, 2216, 'قَالَ إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَٰحِبْنِى ۖ قَدْ بَلَغْتَ مِن لَّدُنِّى عُذْرًۭا', 302, 16, 121, 0),
  (18, 77, 2217, 'فَٱنطَلَقَا حَتَّىٰٓ إِذَآ أَتَيَآ أَهْلَ قَرْيَةٍ ٱسْتَطْعَمَآ أَهْلَهَا فَأَبَوْا۟ أَن يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًۭا يُرِيدُ أَن يَنقَضَّ فَأَقَامَهُۥ ۖ قَالَ لَوْ شِئْتَ لَتَّخَذْتَ عَلَيْهِ أَجْرًۭا', 302, 16, 121, 0),
  (18, 78, 2218, 'قَالَ هَٰذَا فِرَاقُ بَيْنِى وَبَيْنِكَ ۚ سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِع عَّلَيْهِ صَبْرًا', 302, 16, 121, 0),
  (18, 79, 2219, 'أَمَّا ٱلسَّفِينَةُ فَكَانَتْ لِمَسَٰكِينَ يَعْمَلُونَ فِى ٱلْبَحْرِ فَأَرَدتُّ أَنْ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٌۭ يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًۭا', 302, 16, 121, 0),
  (18, 80, 2220, 'وَأَمَّا ٱلْغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ فَخَشِينَآ أَن يُرْهِقَهُمَا طُغْيَٰنًۭا وَكُفْرًۭا', 302, 16, 121, 0),
  (18, 81, 2221, 'فَأَرَدْنَآ أَن يُبْدِلَهُمَا رَبُّهُمَا خَيْرًۭا مِّنْهُ زَكَوٰةًۭ وَأَقْرَبَ رُحْمًۭا', 302, 16, 121, 0),
  (18, 82, 2222, 'وَأَمَّا ٱلْجِدَارُ فَكَانَ لِغُلَٰمَيْنِ يَتِيمَيْنِ فِى ٱلْمَدِينَةِ وَكَانَ تَحْتَهُۥ كَنزٌۭ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحًۭا فَأَرَادَ رَبُّكَ أَن يَبْلُغَآ أَشُدَّهُمَا وَيَسْتَخْرِجَا كَنزَهُمَا رَحْمَةًۭ مِّن رَّبِّكَ ۚ وَمَا فَعَلْتُهُۥ عَنْ أَمْرِى ۚ ذَٰلِكَ تَأْوِيلُ مَا لَمْ تَسْطِع عَّلَيْهِ صَبْرًۭا', 302, 16, 121, 0),
  (18, 83, 2223, 'وَيَسْـَٔلُونَكَ عَن ذِى ٱلْقَرْنَيْنِ ۖ قُلْ سَأَتْلُوا۟ عَلَيْكُم مِّنْهُ ذِكْرًا', 302, 16, 121, 0),
  (18, 84, 2224, 'إِنَّا مَكَّنَّا لَهُۥ فِى ٱلْأَرْضِ وَءَاتَيْنَٰهُ مِن كُلِّ شَىْءٍۢ سَبَبًۭا', 303, 16, 121, 0),
  (18, 85, 2225, 'فَأَتْبَعَ سَبَبًا', 303, 16, 121, 0),
  (18, 86, 2226, 'حَتَّىٰٓ إِذَا بَلَغَ مَغْرِبَ ٱلشَّمْسِ وَجَدَهَا تَغْرُبُ فِى عَيْنٍ حَمِئَةٍۢ وَوَجَدَ عِندَهَا قَوْمًۭا ۗ قُلْنَا يَٰذَا ٱلْقَرْنَيْنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمْ حُسْنًۭا', 303, 16, 121, 0),
  (18, 87, 2227, 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ ثُمَّ يُرَدُّ إِلَىٰ رَبِّهِۦ فَيُعَذِّبُهُۥ عَذَابًۭا نُّكْرًۭا', 303, 16, 121, 0),
  (18, 88, 2228, 'وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًۭا فَلَهُۥ جَزَآءً ٱلْحُسْنَىٰ ۖ وَسَنَقُولُ لَهُۥ مِنْ أَمْرِنَا يُسْرًۭا', 303, 16, 121, 0),
  (18, 89, 2229, 'ثُمَّ أَتْبَعَ سَبَبًا', 303, 16, 121, 0),
  (18, 90, 2230, 'حَتَّىٰٓ إِذَا بَلَغَ مَطْلِعَ ٱلشَّمْسِ وَجَدَهَا تَطْلُعُ عَلَىٰ قَوْمٍۢ لَّمْ نَجْعَل لَّهُم مِّن دُونِهَا سِتْرًۭا', 303, 16, 121, 0),
  (18, 91, 2231, 'كَذَٰلِكَ وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًۭا', 303, 16, 121, 0),
  (18, 92, 2232, 'ثُمَّ أَتْبَعَ سَبَبًا', 303, 16, 121, 0),
  (18, 93, 2233, 'حَتَّىٰٓ إِذَا بَلَغَ بَيْنَ ٱلسَّدَّيْنِ وَجَدَ مِن دُونِهِمَا قَوْمًۭا لَّا يَكَادُونَ يَفْقَهُونَ قَوْلًۭا', 303, 16, 121, 0),
  (18, 94, 2234, 'قَالُوا۟ يَٰذَا ٱلْقَرْنَيْنِ إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِى ٱلْأَرْضِ فَهَلْ نَجْعَلُ لَكَ خَرْجًا عَلَىٰٓ أَن تَجْعَلَ بَيْنَنَا وَبَيْنَهُمْ سَدًّۭا', 303, 16, 121, 0),
  (18, 95, 2235, 'قَالَ مَا مَكَّنِّى فِيهِ رَبِّى خَيْرٌۭ فَأَعِينُونِى بِقُوَّةٍ أَجْعَلْ بَيْنَكُمْ وَبَيْنَهُمْ رَدْمًا', 303, 16, 121, 0),
  (18, 96, 2236, 'ءَاتُونِى زُبَرَ ٱلْحَدِيدِ ۖ حَتَّىٰٓ إِذَا سَاوَىٰ بَيْنَ ٱلصَّدَفَيْنِ قَالَ ٱنفُخُوا۟ ۖ حَتَّىٰٓ إِذَا جَعَلَهُۥ نَارًۭا قَالَ ءَاتُونِىٓ أُفْرِغْ عَلَيْهِ قِطْرًۭا', 303, 16, 121, 0),
  (18, 97, 2237, 'فَمَا ٱسْطَٰعُوٓا۟ أَن يَظْهَرُوهُ وَمَا ٱسْتَطَٰعُوا۟ لَهُۥ نَقْبًۭا', 303, 16, 121, 0),
  (18, 98, 2238, 'قَالَ هَٰذَا رَحْمَةٌۭ مِّن رَّبِّى ۖ فَإِذَا جَآءَ وَعْدُ رَبِّى جَعَلَهُۥ دَكَّآءَ ۖ وَكَانَ وَعْدُ رَبِّى حَقًّۭا', 304, 16, 121, 0),
  (18, 99, 2239, '۞ وَتَرَكْنَا بَعْضَهُمْ يَوْمَئِذٍۢ يَمُوجُ فِى بَعْضٍۢ ۖ وَنُفِخَ فِى ٱلصُّورِ فَجَمَعْنَٰهُمْ جَمْعًۭا', 304, 16, 122, 0),
  (18, 100, 2240, 'وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍۢ لِّلْكَٰفِرِينَ عَرْضًا', 304, 16, 122, 0),
  (18, 101, 2241, 'ٱلَّذِينَ كَانَتْ أَعْيُنُهُمْ فِى غِطَآءٍ عَن ذِكْرِى وَكَانُوا۟ لَا يَسْتَطِيعُونَ سَمْعًا', 304, 16, 122, 0),
  (18, 102, 2242, 'أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓا۟ أَن يَتَّخِذُوا۟ عِبَادِى مِن دُونِىٓ أَوْلِيَآءَ ۚ إِنَّآ أَعْتَدْنَا جَهَنَّمَ لِلْكَٰفِرِينَ نُزُلًۭا', 304, 16, 122, 0),
  (18, 103, 2243, 'قُلْ هَلْ نُنَبِّئُكُم بِٱلْأَخْسَرِينَ أَعْمَٰلًا', 304, 16, 122, 0),
  (18, 104, 2244, 'ٱلَّذِينَ ضَلَّ سَعْيُهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا', 304, 16, 122, 0),
  (18, 105, 2245, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ وَلِقَآئِهِۦ فَحَبِطَتْ أَعْمَٰلُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَزْنًۭا', 304, 16, 122, 0),
  (18, 106, 2246, 'ذَٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوٓا۟ ءَايَٰتِى وَرُسُلِى هُزُوًا', 304, 16, 122, 0),
  (18, 107, 2247, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَانَتْ لَهُمْ جَنَّٰتُ ٱلْفِرْدَوْسِ نُزُلًا', 304, 16, 122, 0),
  (18, 108, 2248, 'خَٰلِدِينَ فِيهَا لَا يَبْغُونَ عَنْهَا حِوَلًۭا', 304, 16, 122, 0),
  (18, 109, 2249, 'قُل لَّوْ كَانَ ٱلْبَحْرُ مِدَادًۭا لِّكَلِمَٰتِ رَبِّى لَنَفِدَ ٱلْبَحْرُ قَبْلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّى وَلَوْ جِئْنَا بِمِثْلِهِۦ مَدَدًۭا', 304, 16, 122, 0),
  (18, 110, 2250, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌۭ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَمَن كَانَ يَرْجُوا۟ لِقَآءَ رَبِّهِۦ فَلْيَعْمَلْ عَمَلًۭا صَٰلِحًۭا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِۦٓ أَحَدًۢا', 304, 16, 122, 0),
  (19, 1, 2251, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ كٓهيعٓصٓ', 305, 16, 122, 0),
  (19, 2, 2252, 'ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ', 305, 16, 122, 0),
  (19, 3, 2253, 'إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّۭا', 305, 16, 122, 0),
  (19, 4, 2254, 'قَالَ رَبِّ إِنِّى وَهَنَ ٱلْعَظْمُ مِنِّى وَٱشْتَعَلَ ٱلرَّأْسُ شَيْبًۭا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّۭا', 305, 16, 122, 0),
  (19, 5, 2255, 'وَإِنِّى خِفْتُ ٱلْمَوَٰلِىَ مِن وَرَآءِى وَكَانَتِ ٱمْرَأَتِى عَاقِرًۭا فَهَبْ لِى مِن لَّدُنكَ وَلِيًّۭا', 305, 16, 122, 0),
  (19, 6, 2256, 'يَرِثُنِى وَيَرِثُ مِنْ ءَالِ يَعْقُوبَ ۖ وَٱجْعَلْهُ رَبِّ رَضِيًّۭا', 305, 16, 122, 0),
  (19, 7, 2257, 'يَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسْمُهُۥ يَحْيَىٰ لَمْ نَجْعَل لَّهُۥ مِن قَبْلُ سَمِيًّۭا', 305, 16, 122, 0),
  (19, 8, 2258, 'قَالَ رَبِّ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَكَانَتِ ٱمْرَأَتِى عَاقِرًۭا وَقَدْ بَلَغْتُ مِنَ ٱلْكِبَرِ عِتِيًّۭا', 305, 16, 122, 0),
  (19, 9, 2259, 'قَالَ كَذَٰلِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّنٌۭ وَقَدْ خَلَقْتُكَ مِن قَبْلُ وَلَمْ تَكُ شَيْـًۭٔا', 305, 16, 122, 0),
  (19, 10, 2260, 'قَالَ رَبِّ ٱجْعَل لِّىٓ ءَايَةًۭ ۚ قَالَ ءَايَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالٍۢ سَوِيًّۭا', 305, 16, 122, 0),
  (19, 11, 2261, 'فَخَرَجَ عَلَىٰ قَوْمِهِۦ مِنَ ٱلْمِحْرَابِ فَأَوْحَىٰٓ إِلَيْهِمْ أَن سَبِّحُوا۟ بُكْرَةًۭ وَعَشِيًّۭا', 305, 16, 122, 0),
  (19, 12, 2262, 'يَٰيَحْيَىٰ خُذِ ٱلْكِتَٰبَ بِقُوَّةٍۢ ۖ وَءَاتَيْنَٰهُ ٱلْحُكْمَ صَبِيًّۭا', 306, 16, 122, 0),
  (19, 13, 2263, 'وَحَنَانًۭا مِّن لَّدُنَّا وَزَكَوٰةًۭ ۖ وَكَانَ تَقِيًّۭا', 306, 16, 122, 0),
  (19, 14, 2264, 'وَبَرًّۢا بِوَٰلِدَيْهِ وَلَمْ يَكُن جَبَّارًا عَصِيًّۭا', 306, 16, 122, 0),
  (19, 15, 2265, 'وَسَلَٰمٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّۭا', 306, 16, 122, 0),
  (19, 16, 2266, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مَرْيَمَ إِذِ ٱنتَبَذَتْ مِنْ أَهْلِهَا مَكَانًۭا شَرْقِيًّۭا', 306, 16, 122, 0),
  (19, 17, 2267, 'فَٱتَّخَذَتْ مِن دُونِهِمْ حِجَابًۭا فَأَرْسَلْنَآ إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًۭا سَوِيًّۭا', 306, 16, 122, 0),
  (19, 18, 2268, 'قَالَتْ إِنِّىٓ أَعُوذُ بِٱلرَّحْمَٰنِ مِنكَ إِن كُنتَ تَقِيًّۭا', 306, 16, 122, 0),
  (19, 19, 2269, 'قَالَ إِنَّمَآ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَٰمًۭا زَكِيًّۭا', 306, 16, 122, 0),
  (19, 20, 2270, 'قَالَتْ أَنَّىٰ يَكُونُ لِى غُلَٰمٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ وَلَمْ أَكُ بَغِيًّۭا', 306, 16, 122, 0),
  (19, 21, 2271, 'قَالَ كَذَٰلِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّنٌۭ ۖ وَلِنَجْعَلَهُۥٓ ءَايَةًۭ لِّلنَّاسِ وَرَحْمَةًۭ مِّنَّا ۚ وَكَانَ أَمْرًۭا مَّقْضِيًّۭا', 306, 16, 122, 0),
  (19, 22, 2272, '۞ فَحَمَلَتْهُ فَٱنتَبَذَتْ بِهِۦ مَكَانًۭا قَصِيًّۭا', 306, 16, 123, 0),
  (19, 23, 2273, 'فَأَجَآءَهَا ٱلْمَخَاضُ إِلَىٰ جِذْعِ ٱلنَّخْلَةِ قَالَتْ يَٰلَيْتَنِى مِتُّ قَبْلَ هَٰذَا وَكُنتُ نَسْيًۭا مَّنسِيًّۭا', 306, 16, 123, 0),
  (19, 24, 2274, 'فَنَادَىٰهَا مِن تَحْتِهَآ أَلَّا تَحْزَنِى قَدْ جَعَلَ رَبُّكِ تَحْتَكِ سَرِيًّۭا', 306, 16, 123, 0),
  (19, 25, 2275, 'وَهُزِّىٓ إِلَيْكِ بِجِذْعِ ٱلنَّخْلَةِ تُسَٰقِطْ عَلَيْكِ رُطَبًۭا جَنِيًّۭا', 306, 16, 123, 0),
  (19, 26, 2276, 'فَكُلِى وَٱشْرَبِى وَقَرِّى عَيْنًۭا ۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلْبَشَرِ أَحَدًۭا فَقُولِىٓ إِنِّى نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًۭا فَلَنْ أُكَلِّمَ ٱلْيَوْمَ إِنسِيًّۭا', 307, 16, 123, 0),
  (19, 27, 2277, 'فَأَتَتْ بِهِۦ قَوْمَهَا تَحْمِلُهُۥ ۖ قَالُوا۟ يَٰمَرْيَمُ لَقَدْ جِئْتِ شَيْـًۭٔا فَرِيًّۭا', 307, 16, 123, 0),
  (19, 28, 2278, 'يَٰٓأُخْتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمْرَأَ سَوْءٍۢ وَمَا كَانَتْ أُمُّكِ بَغِيًّۭا', 307, 16, 123, 0),
  (19, 29, 2279, 'فَأَشَارَتْ إِلَيْهِ ۖ قَالُوا۟ كَيْفَ نُكَلِّمُ مَن كَانَ فِى ٱلْمَهْدِ صَبِيًّۭا', 307, 16, 123, 0),
  (19, 30, 2280, 'قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّۭا', 307, 16, 123, 0),
  (19, 31, 2281, 'وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّۭا', 307, 16, 123, 0),
  (19, 32, 2282, 'وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًۭا شَقِيًّۭا', 307, 16, 123, 0),
  (19, 33, 2283, 'وَٱلسَّلَٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّۭا', 307, 16, 123, 0),
  (19, 34, 2284, 'ذَٰلِكَ عِيسَى ٱبْنُ مَرْيَمَ ۚ قَوْلَ ٱلْحَقِّ ٱلَّذِى فِيهِ يَمْتَرُونَ', 307, 16, 123, 0),
  (19, 35, 2285, 'مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٍۢ ۖ سُبْحَٰنَهُۥٓ ۚ إِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 307, 16, 123, 0),
  (19, 36, 2286, 'وَإِنَّ ٱللَّهَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 307, 16, 123, 0),
  (19, 37, 2287, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ ۖ فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِن مَّشْهَدِ يَوْمٍ عَظِيمٍ', 307, 16, 123, 0),
  (19, 38, 2288, 'أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا ۖ لَٰكِنِ ٱلظَّٰلِمُونَ ٱلْيَوْمَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 307, 16, 123, 0),
  (19, 39, 2289, 'وَأَنذِرْهُمْ يَوْمَ ٱلْحَسْرَةِ إِذْ قُضِىَ ٱلْأَمْرُ وَهُمْ فِى غَفْلَةٍۢ وَهُمْ لَا يُؤْمِنُونَ', 308, 16, 123, 0),
  (19, 40, 2290, 'إِنَّا نَحْنُ نَرِثُ ٱلْأَرْضَ وَمَنْ عَلَيْهَا وَإِلَيْنَا يُرْجَعُونَ', 308, 16, 123, 0),
  (19, 41, 2291, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِبْرَٰهِيمَ ۚ إِنَّهُۥ كَانَ صِدِّيقًۭا نَّبِيًّا', 308, 16, 123, 0),
  (19, 42, 2292, 'إِذْ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًۭٔا', 308, 16, 123, 0),
  (19, 43, 2293, 'يَٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًۭا سَوِيًّۭا', 308, 16, 123, 0),
  (19, 44, 2294, 'يَٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَٰنَ ۖ إِنَّ ٱلشَّيْطَٰنَ كَانَ لِلرَّحْمَٰنِ عَصِيًّۭا', 308, 16, 123, 0),
  (19, 45, 2295, 'يَٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌۭ مِّنَ ٱلرَّحْمَٰنِ فَتَكُونَ لِلشَّيْطَٰنِ وَلِيًّۭا', 308, 16, 123, 0),
  (19, 46, 2296, 'قَالَ أَرَاغِبٌ أَنتَ عَنْ ءَالِهَتِى يَٰٓإِبْرَٰهِيمُ ۖ لَئِن لَّمْ تَنتَهِ لَأَرْجُمَنَّكَ ۖ وَٱهْجُرْنِى مَلِيًّۭا', 308, 16, 123, 0),
  (19, 47, 2297, 'قَالَ سَلَٰمٌ عَلَيْكَ ۖ سَأَسْتَغْفِرُ لَكَ رَبِّىٓ ۖ إِنَّهُۥ كَانَ بِى حَفِيًّۭا', 308, 16, 123, 0),
  (19, 48, 2298, 'وَأَعْتَزِلُكُمْ وَمَا تَدْعُونَ مِن دُونِ ٱللَّهِ وَأَدْعُوا۟ رَبِّى عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّى شَقِيًّۭا', 308, 16, 123, 0),
  (19, 49, 2299, 'فَلَمَّا ٱعْتَزَلَهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ وَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ ۖ وَكُلًّۭا جَعَلْنَا نَبِيًّۭا', 308, 16, 123, 0),
  (19, 50, 2300, 'وَوَهَبْنَا لَهُم مِّن رَّحْمَتِنَا وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ عَلِيًّۭا', 308, 16, 123, 0),
  (19, 51, 2301, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ مُوسَىٰٓ ۚ إِنَّهُۥ كَانَ مُخْلَصًۭا وَكَانَ رَسُولًۭا نَّبِيًّۭا', 308, 16, 123, 0),
  (19, 52, 2302, 'وَنَٰدَيْنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلْأَيْمَنِ وَقَرَّبْنَٰهُ نَجِيًّۭا', 309, 16, 123, 0),
  (19, 53, 2303, 'وَوَهَبْنَا لَهُۥ مِن رَّحْمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيًّۭا', 309, 16, 123, 0),
  (19, 54, 2304, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ ۚ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًۭا نَّبِيًّۭا', 309, 16, 123, 0),
  (19, 55, 2305, 'وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّۭا', 309, 16, 123, 0),
  (19, 56, 2306, 'وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ ۚ إِنَّهُۥ كَانَ صِدِّيقًۭا نَّبِيًّۭا', 309, 16, 123, 0),
  (19, 57, 2307, 'وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا', 309, 16, 123, 0),
  (19, 58, 2308, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنْ حَمَلْنَا مَعَ نُوحٍۢ وَمِن ذُرِّيَّةِ إِبْرَٰهِيمَ وَإِسْرَٰٓءِيلَ وَمِمَّنْ هَدَيْنَا وَٱجْتَبَيْنَآ ۚ إِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُ ٱلرَّحْمَٰنِ خَرُّوا۟ سُجَّدًۭا وَبُكِيًّۭا ۩', 309, 16, 123, 1),
  (19, 59, 2309, '۞ فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَٰتِ ۖ فَسَوْفَ يَلْقَوْنَ غَيًّا', 309, 16, 124, 0),
  (19, 60, 2310, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًۭا فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ شَيْـًۭٔا', 309, 16, 124, 0),
  (19, 61, 2311, 'جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدَ ٱلرَّحْمَٰنُ عِبَادَهُۥ بِٱلْغَيْبِ ۚ إِنَّهُۥ كَانَ وَعْدُهُۥ مَأْتِيًّۭا', 309, 16, 124, 0),
  (19, 62, 2312, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَٰمًۭا ۖ وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةًۭ وَعَشِيًّۭا', 309, 16, 124, 0),
  (19, 63, 2313, 'تِلْكَ ٱلْجَنَّةُ ٱلَّتِى نُورِثُ مِنْ عِبَادِنَا مَن كَانَ تَقِيًّۭا', 309, 16, 124, 0),
  (19, 64, 2314, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ ۖ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا وَمَا بَيْنَ ذَٰلِكَ ۚ وَمَا كَانَ رَبُّكَ نَسِيًّۭا', 309, 16, 124, 0),
  (19, 65, 2315, 'رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَٰدَتِهِۦ ۚ هَلْ تَعْلَمُ لَهُۥ سَمِيًّۭا', 310, 16, 124, 0),
  (19, 66, 2316, 'وَيَقُولُ ٱلْإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوْفَ أُخْرَجُ حَيًّا', 310, 16, 124, 0),
  (19, 67, 2317, 'أَوَلَا يَذْكُرُ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن قَبْلُ وَلَمْ يَكُ شَيْـًۭٔا', 310, 16, 124, 0),
  (19, 68, 2318, 'فَوَرَبِّكَ لَنَحْشُرَنَّهُمْ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّۭا', 310, 16, 124, 0),
  (19, 69, 2319, 'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمْ أَشَدُّ عَلَى ٱلرَّحْمَٰنِ عِتِيًّۭا', 310, 16, 124, 0),
  (19, 70, 2320, 'ثُمَّ لَنَحْنُ أَعْلَمُ بِٱلَّذِينَ هُمْ أَوْلَىٰ بِهَا صِلِيًّۭا', 310, 16, 124, 0),
  (19, 71, 2321, 'وَإِن مِّنكُمْ إِلَّا وَارِدُهَا ۚ كَانَ عَلَىٰ رَبِّكَ حَتْمًۭا مَّقْضِيًّۭا', 310, 16, 124, 0),
  (19, 72, 2322, 'ثُمَّ نُنَجِّى ٱلَّذِينَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّٰلِمِينَ فِيهَا جِثِيًّۭا', 310, 16, 124, 0),
  (19, 73, 2323, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَىُّ ٱلْفَرِيقَيْنِ خَيْرٌۭ مَّقَامًۭا وَأَحْسَنُ نَدِيًّۭا', 310, 16, 124, 0),
  (19, 74, 2324, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَحْسَنُ أَثَٰثًۭا وَرِءْيًۭا', 310, 16, 124, 0),
  (19, 75, 2325, 'قُلْ مَن كَانَ فِى ٱلضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ ٱلرَّحْمَٰنُ مَدًّا ۚ حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ إِمَّا ٱلْعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعْلَمُونَ مَنْ هُوَ شَرٌّۭ مَّكَانًۭا وَأَضْعَفُ جُندًۭا', 310, 16, 124, 0),
  (19, 76, 2326, 'وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهْتَدَوْا۟ هُدًۭى ۗ وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًۭا وَخَيْرٌۭ مَّرَدًّا', 310, 16, 124, 0),
  (19, 77, 2327, 'أَفَرَءَيْتَ ٱلَّذِى كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالًۭا وَوَلَدًا', 311, 16, 124, 0),
  (19, 78, 2328, 'أَطَّلَعَ ٱلْغَيْبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًۭا', 311, 16, 124, 0),
  (19, 79, 2329, 'كَلَّا ۚ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلْعَذَابِ مَدًّۭا', 311, 16, 124, 0),
  (19, 80, 2330, 'وَنَرِثُهُۥ مَا يَقُولُ وَيَأْتِينَا فَرْدًۭا', 311, 16, 124, 0),
  (19, 81, 2331, 'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةًۭ لِّيَكُونُوا۟ لَهُمْ عِزًّۭا', 311, 16, 124, 0),
  (19, 82, 2332, 'كَلَّا ۚ سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا', 311, 16, 124, 0),
  (19, 83, 2333, 'أَلَمْ تَرَ أَنَّآ أَرْسَلْنَا ٱلشَّيَٰطِينَ عَلَى ٱلْكَٰفِرِينَ تَؤُزُّهُمْ أَزًّۭا', 311, 16, 124, 0),
  (19, 84, 2334, 'فَلَا تَعْجَلْ عَلَيْهِمْ ۖ إِنَّمَا نَعُدُّ لَهُمْ عَدًّۭا', 311, 16, 124, 0),
  (19, 85, 2335, 'يَوْمَ نَحْشُرُ ٱلْمُتَّقِينَ إِلَى ٱلرَّحْمَٰنِ وَفْدًۭا', 311, 16, 124, 0),
  (19, 86, 2336, 'وَنَسُوقُ ٱلْمُجْرِمِينَ إِلَىٰ جَهَنَّمَ وِرْدًۭا', 311, 16, 124, 0),
  (19, 87, 2337, 'لَّا يَمْلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحْمَٰنِ عَهْدًۭا', 311, 16, 124, 0),
  (19, 88, 2338, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًۭا', 311, 16, 124, 0),
  (19, 89, 2339, 'لَّقَدْ جِئْتُمْ شَيْـًٔا إِدًّۭا', 311, 16, 124, 0),
  (19, 90, 2340, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِنْهُ وَتَنشَقُّ ٱلْأَرْضُ وَتَخِرُّ ٱلْجِبَالُ هَدًّا', 311, 16, 124, 0),
  (19, 91, 2341, 'أَن دَعَوْا۟ لِلرَّحْمَٰنِ وَلَدًۭا', 311, 16, 124, 0),
  (19, 92, 2342, 'وَمَا يَنۢبَغِى لِلرَّحْمَٰنِ أَن يَتَّخِذَ وَلَدًا', 311, 16, 124, 0),
  (19, 93, 2343, 'إِن كُلُّ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِلَّآ ءَاتِى ٱلرَّحْمَٰنِ عَبْدًۭا', 311, 16, 124, 0),
  (19, 94, 2344, 'لَّقَدْ أَحْصَىٰهُمْ وَعَدَّهُمْ عَدًّۭا', 311, 16, 124, 0),
  (19, 95, 2345, 'وَكُلُّهُمْ ءَاتِيهِ يَوْمَ ٱلْقِيَٰمَةِ فَرْدًا', 311, 16, 124, 0),
  (19, 96, 2346, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَيَجْعَلُ لَهُمُ ٱلرَّحْمَٰنُ وُدًّۭا', 312, 16, 124, 0),
  (19, 97, 2347, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلْمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوْمًۭا لُّدًّۭا', 312, 16, 124, 0),
  (19, 98, 2348, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هَلْ تُحِسُّ مِنْهُم مِّنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًۢا', 312, 16, 124, 0),
  (20, 1, 2349, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طه', 312, 16, 125, 0),
  (20, 2, 2350, 'مَآ أَنزَلْنَا عَلَيْكَ ٱلْقُرْءَانَ لِتَشْقَىٰٓ', 312, 16, 125, 0),
  (20, 3, 2351, 'إِلَّا تَذْكِرَةًۭ لِّمَن يَخْشَىٰ', 312, 16, 125, 0),
  (20, 4, 2352, 'تَنزِيلًۭا مِّمَّنْ خَلَقَ ٱلْأَرْضَ وَٱلسَّمَٰوَٰتِ ٱلْعُلَى', 312, 16, 125, 0),
  (20, 5, 2353, 'ٱلرَّحْمَٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ', 312, 16, 125, 0),
  (20, 6, 2354, 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَمَا بَيْنَهُمَا وَمَا تَحْتَ ٱلثَّرَىٰ', 312, 16, 125, 0),
  (20, 7, 2355, 'وَإِن تَجْهَرْ بِٱلْقَوْلِ فَإِنَّهُۥ يَعْلَمُ ٱلسِّرَّ وَأَخْفَى', 312, 16, 125, 0),
  (20, 8, 2356, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ', 312, 16, 125, 0),
  (20, 9, 2357, 'وَهَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 312, 16, 125, 0),
  (20, 10, 2358, 'إِذْ رَءَا نَارًۭا فَقَالَ لِأَهْلِهِ ٱمْكُثُوٓا۟ إِنِّىٓ ءَانَسْتُ نَارًۭا لَّعَلِّىٓ ءَاتِيكُم مِّنْهَا بِقَبَسٍ أَوْ أَجِدُ عَلَى ٱلنَّارِ هُدًۭى', 312, 16, 125, 0),
  (20, 11, 2359, 'فَلَمَّآ أَتَىٰهَا نُودِىَ يَٰمُوسَىٰٓ', 312, 16, 125, 0),
  (20, 12, 2360, 'إِنِّىٓ أَنَا۠ رَبُّكَ فَٱخْلَعْ نَعْلَيْكَ ۖ إِنَّكَ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًۭى', 312, 16, 125, 0),
  (20, 13, 2361, 'وَأَنَا ٱخْتَرْتُكَ فَٱسْتَمِعْ لِمَا يُوحَىٰٓ', 313, 16, 125, 0),
  (20, 14, 2362, 'إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ', 313, 16, 125, 0),
  (20, 15, 2363, 'إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخْفِيهَا لِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا تَسْعَىٰ', 313, 16, 125, 0),
  (20, 16, 2364, 'فَلَا يَصُدَّنَّكَ عَنْهَا مَن لَّا يُؤْمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرْدَىٰ', 313, 16, 125, 0),
  (20, 17, 2365, 'وَمَا تِلْكَ بِيَمِينِكَ يَٰمُوسَىٰ', 313, 16, 125, 0),
  (20, 18, 2366, 'قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُا۟ عَلَيْهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔارِبُ أُخْرَىٰ', 313, 16, 125, 0),
  (20, 19, 2367, 'قَالَ أَلْقِهَا يَٰمُوسَىٰ', 313, 16, 125, 0),
  (20, 20, 2368, 'فَأَلْقَىٰهَا فَإِذَا هِىَ حَيَّةٌۭ تَسْعَىٰ', 313, 16, 125, 0),
  (20, 21, 2369, 'قَالَ خُذْهَا وَلَا تَخَفْ ۖ سَنُعِيدُهَا سِيرَتَهَا ٱلْأُولَىٰ', 313, 16, 125, 0),
  (20, 22, 2370, 'وَٱضْمُمْ يَدَكَ إِلَىٰ جَنَاحِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ءَايَةً أُخْرَىٰ', 313, 16, 125, 0),
  (20, 23, 2371, 'لِنُرِيَكَ مِنْ ءَايَٰتِنَا ٱلْكُبْرَى', 313, 16, 125, 0),
  (20, 24, 2372, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 313, 16, 125, 0),
  (20, 25, 2373, 'قَالَ رَبِّ ٱشْرَحْ لِى صَدْرِى', 313, 16, 125, 0),
  (20, 26, 2374, 'وَيَسِّرْ لِىٓ أَمْرِى', 313, 16, 125, 0),
  (20, 27, 2375, 'وَٱحْلُلْ عُقْدَةًۭ مِّن لِّسَانِى', 313, 16, 125, 0),
  (20, 28, 2376, 'يَفْقَهُوا۟ قَوْلِى', 313, 16, 125, 0),
  (20, 29, 2377, 'وَٱجْعَل لِّى وَزِيرًۭا مِّنْ أَهْلِى', 313, 16, 125, 0),
  (20, 30, 2378, 'هَٰرُونَ أَخِى', 313, 16, 125, 0),
  (20, 31, 2379, 'ٱشْدُدْ بِهِۦٓ أَزْرِى', 313, 16, 125, 0),
  (20, 32, 2380, 'وَأَشْرِكْهُ فِىٓ أَمْرِى', 313, 16, 125, 0),
  (20, 33, 2381, 'كَىْ نُسَبِّحَكَ كَثِيرًۭا', 313, 16, 125, 0),
  (20, 34, 2382, 'وَنَذْكُرَكَ كَثِيرًا', 313, 16, 125, 0),
  (20, 35, 2383, 'إِنَّكَ كُنتَ بِنَا بَصِيرًۭا', 313, 16, 125, 0),
  (20, 36, 2384, 'قَالَ قَدْ أُوتِيتَ سُؤْلَكَ يَٰمُوسَىٰ', 313, 16, 125, 0),
  (20, 37, 2385, 'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَىٰٓ', 313, 16, 125, 0),
  (20, 38, 2386, 'إِذْ أَوْحَيْنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ', 314, 16, 125, 0),
  (20, 39, 2387, 'أَنِ ٱقْذِفِيهِ فِى ٱلتَّابُوتِ فَٱقْذِفِيهِ فِى ٱلْيَمِّ فَلْيُلْقِهِ ٱلْيَمُّ بِٱلسَّاحِلِ يَأْخُذْهُ عَدُوٌّۭ لِّى وَعَدُوٌّۭ لَّهُۥ ۚ وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةًۭ مِّنِّى وَلِتُصْنَعَ عَلَىٰ عَيْنِىٓ', 314, 16, 125, 0),
  (20, 40, 2388, 'إِذْ تَمْشِىٓ أُخْتُكَ فَتَقُولُ هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُۥ ۖ فَرَجَعْنَٰكَ إِلَىٰٓ أُمِّكَ كَىْ تَقَرَّ عَيْنُهَا وَلَا تَحْزَنَ ۚ وَقَتَلْتَ نَفْسًۭا فَنَجَّيْنَٰكَ مِنَ ٱلْغَمِّ وَفَتَنَّٰكَ فُتُونًۭا ۚ فَلَبِثْتَ سِنِينَ فِىٓ أَهْلِ مَدْيَنَ ثُمَّ جِئْتَ عَلَىٰ قَدَرٍۢ يَٰمُوسَىٰ', 314, 16, 125, 0),
  (20, 41, 2389, 'وَٱصْطَنَعْتُكَ لِنَفْسِى', 314, 16, 125, 0),
  (20, 42, 2390, 'ٱذْهَبْ أَنتَ وَأَخُوكَ بِـَٔايَٰتِى وَلَا تَنِيَا فِى ذِكْرِى', 314, 16, 125, 0),
  (20, 43, 2391, 'ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 314, 16, 125, 0),
  (20, 44, 2392, 'فَقُولَا لَهُۥ قَوْلًۭا لَّيِّنًۭا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ', 314, 16, 125, 0),
  (20, 45, 2393, 'قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَآ أَوْ أَن يَطْغَىٰ', 314, 16, 125, 0),
  (20, 46, 2394, 'قَالَ لَا تَخَافَآ ۖ إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَىٰ', 314, 16, 125, 0),
  (20, 47, 2395, 'فَأْتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ وَلَا تُعَذِّبْهُمْ ۖ قَدْ جِئْنَٰكَ بِـَٔايَةٍۢ مِّن رَّبِّكَ ۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلْهُدَىٰٓ', 314, 16, 125, 0),
  (20, 48, 2396, 'إِنَّا قَدْ أُوحِىَ إِلَيْنَآ أَنَّ ٱلْعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ', 314, 16, 125, 0),
  (20, 49, 2397, 'قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ', 314, 16, 125, 0),
  (20, 50, 2398, 'قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ', 314, 16, 125, 0),
  (20, 51, 2399, 'قَالَ فَمَا بَالُ ٱلْقُرُونِ ٱلْأُولَىٰ', 314, 16, 125, 0),
  (20, 52, 2400, 'قَالَ عِلْمُهَا عِندَ رَبِّى فِى كِتَٰبٍۢ ۖ لَّا يَضِلُّ رَبِّى وَلَا يَنسَى', 315, 16, 125, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 20, 1, 'Ta, Ha.'),
  ('en.sahih', 20, 2, 'We have not sent down to you the Qur\'an that you be distressed'),
  ('en.sahih', 20, 3, 'But only as a reminder for those who fear [Allah] -'),
  ('en.sahih', 20, 4, 'A revelation from He who created the earth and highest heavens,'),
  ('en.sahih', 20, 5, 'The Most Merciful [who is] above the Throne established.'),
  ('en.sahih', 20, 6, 'To Him belongs what is in the heavens and what is on the earth and what is between them and what is under the soil.'),
  ('en.sahih', 20, 7, 'And if you speak aloud - then indeed, He knows the secret and what is [even] more hidden.'),
  ('en.sahih', 20, 8, 'Allah - there is no deity except Him. To Him belong the best names.'),
  ('en.sahih', 20, 9, 'And has the story of Moses reached you? -'),
  ('en.sahih', 20, 10, 'When he saw a fire and said to his family, "Stay here; indeed, I have perceived a fire; perhaps I can bring you a torch or find at the fire some guidance."'),
  ('en.sahih', 20, 11, 'And when he came to it, he was called, "O Moses,'),
  ('en.sahih', 20, 12, 'Indeed, I am your Lord, so remove your sandals. Indeed, you are in the sacred valley of Tuwa.'),
  ('en.sahih', 20, 13, 'And I have chosen you, so listen to what is revealed [to you].'),
  ('en.sahih', 20, 14, 'Indeed, I am Allah. There is no deity except Me, so worship Me and establish prayer for My remembrance.'),
  ('en.sahih', 20, 15, 'Indeed, the Hour is coming - I almost conceal it - so that every soul may be recompensed according to that for which it strives.'),
  ('en.sahih', 20, 16, 'So do not let one avert you from it who does not believe in it and follows his desire, for you [then] would perish.'),
  ('en.sahih', 20, 17, 'And what is that in your right hand, O Moses?"'),
  ('en.sahih', 20, 18, 'He said, "It is my staff; I lean upon it, and I bring down leaves for my sheep and I have therein other uses."'),
  ('en.sahih', 20, 19, '[Allah] said, "Throw it down, O Moses."'),
  ('en.sahih', 20, 20, 'So he threw it down, and thereupon it was a snake, moving swiftly.'),
  ('en.sahih', 20, 21, '[Allah] said, "Seize it and fear not; We will return it to its former condition.'),
  ('en.sahih', 20, 22, 'And draw in your hand to your side; it will come out white without disease - another sign,'),
  ('en.sahih', 20, 23, 'That We may show you [some] of Our greater signs.'),
  ('en.sahih', 20, 24, 'Go to Pharaoh. Indeed, he has transgressed."'),
  ('en.sahih', 20, 25, '[Moses] said, "My Lord, expand for me my breast [with assurance]'),
  ('en.sahih', 20, 26, 'And ease for me my task'),
  ('en.sahih', 20, 27, 'And untie the knot from my tongue'),
  ('en.sahih', 20, 28, 'That they may understand my speech.'),
  ('en.sahih', 20, 29, 'And appoint for me a minister from my family -'),
  ('en.sahih', 20, 30, 'Aaron, my brother.'),
  ('en.sahih', 20, 31, 'Increase through him my strength'),
  ('en.sahih', 20, 32, 'And let him share my task'),
  ('en.sahih', 20, 33, 'That we may exalt You much'),
  ('en.sahih', 20, 34, 'And remember You much.'),
  ('en.sahih', 20, 35, 'Indeed, You are of us ever Seeing."'),
  ('en.sahih', 20, 36, '[Allah] said, "You have been granted your request, O Moses.'),
  ('en.sahih', 20, 37, 'And We had already conferred favor upon you another time,'),
  ('en.sahih', 20, 38, 'When We inspired to your mother what We inspired,'),
  ('en.sahih', 20, 39, '[Saying], \'Cast him into the chest and cast it into the river, and the river will throw it onto the bank; there will take him an enemy to Me and an enemy to him.\' And I bestowed upon you love from Me that you would be brought up under My eye.'),
  ('en.sahih', 20, 40, '[And We favored you] when your sister went and said, \'Shall I direct you to someone who will be responsible for him?\' So We restored you to your mother that she might be content and not grieve. And you killed someone, but We saved you from retaliation and tried you with a [severe] trial. And you remained [some] years among the people of Madyan. Then you came [here] at the decreed time, O Moses.'),
  ('en.sahih', 20, 41, 'And I produced you for Myself.'),
  ('en.sahih', 20, 42, 'Go, you and your brother, with My signs and do not slacken in My remembrance.'),
  ('en.sahih', 20, 43, 'Go, both of you, to Pharaoh. Indeed, he has transgressed.'),
  ('en.sahih', 20, 44, 'And speak to him with gentle speech that perhaps he may be reminded or fear [Allah]."'),
  ('en.sahih', 20, 45, 'They said, "Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress."'),
  ('en.sahih', 20, 46, '[Allah] said, "Fear not. Indeed, I am with you both; I hear and I see.'),
  ('en.sahih', 20, 47, 'So go to him and say, \'Indeed, we are messengers of your Lord, so send with us the Children of Israel and do not torment them. We have come to you with a sign from your Lord. And peace will be upon he who follows the guidance.'),
  ('en.sahih', 20, 48, 'Indeed, it has been revealed to us that the punishment will be upon whoever denies and turns away.\' "'),
  ('en.sahih', 20, 49, '[Pharaoh] said, "So who is the Lord of you two, O Moses?"'),
  ('en.sahih', 20, 50, 'He said, "Our Lord is He who gave each thing its form and then guided [it]."'),
  ('en.sahih', 20, 51, '[Pharaoh] said, "Then what is the case of the former generations?"'),
  ('en.sahih', 20, 52, '[Moses] said, "The knowledge thereof is with my Lord in a record. My Lord neither errs nor forgets."'),
  ('en.sahih', 20, 53, '[It is He] who has made for you the earth as a bed [spread out] and inserted therein for you roadways and sent down from the sky, rain and produced thereby categories of various plants.'),
  ('en.sahih', 20, 54, 'Eat [therefrom] and pasture your livestock. Indeed, in that are signs for those of intelligence.'),
  ('en.sahih', 20, 55, 'From the earth We created you, and into it We will return you, and from it We will extract you another time.'),
  ('en.sahih', 20, 56, 'And We certainly showed Pharaoh Our signs - all of them - but he denied and refused.'),
  ('en.sahih', 20, 57, 'He said, "Have you come to us to drive us out of our land with your magic, O Moses?'),
  ('en.sahih', 20, 58, 'Then we will surely bring you magic like it, so make between us and you an appointment, which we will not fail to keep and neither will you, in a place assigned."'),
  ('en.sahih', 20, 59, '[Moses] said, "Your appointment is on the day of the festival when the people assemble at mid-morning."'),
  ('en.sahih', 20, 60, 'So Pharaoh went away, put together his plan, and then came [to Moses].'),
  ('en.sahih', 20, 61, 'Moses said to the magicians summoned by Pharaoh, "Woe to you! Do not invent a lie against Allah or He will exterminate you with a punishment; and he has failed who invents [such falsehood]."'),
  ('en.sahih', 20, 62, 'So they disputed over their affair among themselves and concealed their private conversation.'),
  ('en.sahih', 20, 63, 'They said, "Indeed, these are two magicians who want to drive you out of your land with their magic and do away with your most exemplary way.'),
  ('en.sahih', 20, 64, 'So resolve upon your plan and then come [forward] in line. And he has succeeded today who overcomes."'),
  ('en.sahih', 20, 65, 'They said, "O Moses, either you throw or we will be the first to throw."'),
  ('en.sahih', 20, 66, 'He said, "Rather, you throw." And suddenly their ropes and staffs seemed to him from their magic that they were moving [like snakes].'),
  ('en.sahih', 20, 67, 'And he sensed within himself apprehension, did Moses.'),
  ('en.sahih', 20, 68, 'Allah said, "Fear not. Indeed, it is you who are superior.'),
  ('en.sahih', 20, 69, 'And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is."'),
  ('en.sahih', 20, 70, 'So the magicians fell down in prostration. They said, "We have believed in the Lord of Aaron and Moses."'),
  ('en.sahih', 20, 71, '[Pharaoh] said, "You believed him before I gave you permission. Indeed, he is your leader who has taught you magic. So I will surely cut off your hands and your feet on opposite sides, and I will crucify you on the trunks of palm trees, and you will surely know which of us is more severe in [giving] punishment and more enduring."'),
  ('en.sahih', 20, 72, 'They said, "Never will we prefer you over what has come to us of clear proofs and [over] He who created us. So decree whatever you are to decree. You can only decree for this worldly life.'),
  ('en.sahih', 20, 73, 'Indeed, we have believed in our Lord that He may forgive us our sins and what you compelled us [to do] of magic. And Allah is better and more enduring."'),
  ('en.sahih', 20, 74, 'Indeed, whoever comes to his Lord as a criminal - indeed, for him is Hell; he will neither die therein nor live.'),
  ('en.sahih', 20, 75, 'But whoever comes to Him as a believer having done righteous deeds - for those will be the highest degrees [in position]:'),
  ('en.sahih', 20, 76, 'Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself.'),
  ('en.sahih', 20, 77, 'And We had inspired to Moses, "Travel by night with My servants and strike for them a dry path through the sea; you will not fear being overtaken [by Pharaoh] nor be afraid [of drowning]."'),
  ('en.sahih', 20, 78, 'So Pharaoh pursued them with his soldiers, and there covered them from the sea that which covered them,'),
  ('en.sahih', 20, 79, 'And Pharaoh led his people astray and did not guide [them].'),
  ('en.sahih', 20, 80, 'O Children of Israel, We delivered you from your enemy, and We made an appointment with you at the right side of the mount, and We sent down to you manna and quails,'),
  ('en.sahih', 20, 81, '[Saying], "Eat from the good things with which We have provided you and do not transgress [or oppress others] therein, lest My anger should descend upon you. And he upon whom My anger descends has certainly fallen."'),
  ('en.sahih', 20, 82, 'But indeed, I am the Perpetual Forgiver of whoever repents and believes and does righteousness and then continues in guidance.'),
  ('en.sahih', 20, 83, '[Allah] said, "And what made you hasten from your people, O Moses?"'),
  ('en.sahih', 20, 84, 'He said, "They are close upon my tracks, and I hastened to You, my Lord, that You be pleased."'),
  ('en.sahih', 20, 85, '[Allah] said, "But indeed, We have tried your people after you [departed], and the Samiri has led them astray."'),
  ('en.sahih', 20, 86, 'So Moses returned to his people, angry and grieved. He said, "O my people, did your Lord not make you a good promise? Then, was the time [of its fulfillment] too long for you, or did you wish that wrath from your Lord descend upon you, so you broke your promise [of obedience] to me?"'),
  ('en.sahih', 20, 87, 'They said, "We did not break our promise to you by our will, but we were made to carry burdens from the ornaments of the people [of Pharaoh], so we threw them [into the fire], and thus did the Samiri throw."'),
  ('en.sahih', 20, 88, 'And he extracted for them [the statue of] a calf which had a lowing sound, and they said, "This is your god and the god of Moses, but he forgot."'),
  ('en.sahih', 20, 89, 'Did they not see that it could not return to them any speech and that it did not possess for them any harm or benefit?'),
  ('en.sahih', 20, 90, 'And Aaron had already told them before [the return of Moses], "O my people, you are only being tested by it, and indeed, your Lord is the Most Merciful, so follow me and obey my order."'),
  ('en.sahih', 20, 91, 'They said, "We will never cease being devoted to the calf until Moses returns to us."'),
  ('en.sahih', 20, 92, '[Moses] said, "O Aaron, what prevented you, when you saw them going astray,'),
  ('en.sahih', 20, 93, 'From following me? Then have you disobeyed my order?"'),
  ('en.sahih', 20, 94, '[Aaron] said, "O son of my mother, do not seize [me] by my beard or by my head. Indeed, I feared that you would say, \'You caused division among the Children of Israel, and you did not observe [or await] my word.\' "'),
  ('en.sahih', 20, 95, '[Moses] said, "And what is your case, O Samiri?"'),
  ('en.sahih', 20, 96, 'He said, "I saw what they did not see, so I took a handful [of dust] from the track of the messenger and threw it, and thus did my soul entice me."'),
  ('en.sahih', 20, 97, '[Moses] said, "Then go. And indeed, it is [decreed] for you in [this] life to say, \'No contact.\' And indeed, you have an appointment [in the Hereafter] you will not fail to keep. And look at your \'god\' to which you remained devoted. We will surely burn it and blow it into the sea with a blast.'),
  ('en.sahih', 20, 98, 'Your god is only Allah, except for whom there is no deity. He has encompassed all things in knowledge."'),
  ('en.sahih', 20, 99, 'Thus, [O Muhammad], We relate to you from the news of what has preceded. And We have certainly given you from Us the Qur\'an.'),
  ('en.sahih', 20, 100, 'Whoever turns away from it - then indeed, he will bear on the Day of Resurrection a burden,'),
  ('en.sahih', 20, 101, '[Abiding] eternally therein, and evil it is for them on the Day of Resurrection as a load -'),
  ('en.sahih', 20, 102, 'The Day the Horn will be blown. And We will gather the criminals, that Day, blue-eyed.'),
  ('en.sahih', 20, 103, 'They will murmur among themselves, "You remained not but ten [days in the world]."'),
  ('en.sahih', 20, 104, 'We are most knowing of what they say when the best of them in manner will say, "You remained not but one day."'),
  ('en.sahih', 20, 105, 'And they ask you about the mountains, so say, "My Lord will blow them away with a blast.'),
  ('en.sahih', 20, 106, 'And He will leave the earth a level plain;'),
  ('en.sahih', 20, 107, 'You will not see therein a depression or an elevation."'),
  ('en.sahih', 20, 108, 'That Day, everyone will follow [the call of] the Caller [with] no deviation therefrom, and [all] voices will be stilled before the Most Merciful, so you will not hear except a whisper [of footsteps].'),
  ('en.sahih', 20, 109, 'That Day, no intercession will benefit except [that of] one to whom the Most Merciful has given permission and has accepted his word.'),
  ('en.sahih', 20, 110, 'Allah knows what is [presently] before them and what will be after them, but they do not encompass it in knowledge.'),
  ('en.sahih', 20, 111, 'And [all] faces will be humbled before the Ever-Living, the Sustainer of existence. And he will have failed who carries injustice.'),
  ('en.sahih', 20, 112, 'But he who does of righteous deeds while he is a believer - he will neither fear injustice nor deprivation.'),
  ('en.sahih', 20, 113, 'And thus We have sent it down as an Arabic Qur\'an and have diversified therein the warnings that perhaps they will avoid [sin] or it would cause them remembrance.'),
  ('en.sahih', 20, 114, 'So high [above all] is Allah, the Sovereign, the Truth. And, [O Muhammad], do not hasten with [recitation of] the Qur\'an before its revelation is completed to you, and say, "My Lord, increase me in knowledge."'),
  ('en.sahih', 20, 115, 'And We had already taken a promise from Adam before, but he forgot; and We found not in him determination.'),
  ('en.sahih', 20, 116, 'And [mention] when We said to the angels, "Prostrate to Adam," and they prostrated, except Iblees; he refused.'),
  ('en.sahih', 20, 117, 'So We said, "O Adam, indeed this is an enemy to you and to your wife. Then let him not remove you from Paradise so you would suffer.'),
  ('en.sahih', 20, 118, 'Indeed, it is [promised] for you not to be hungry therein or be unclothed.'),
  ('en.sahih', 20, 119, 'And indeed, you will not be thirsty therein or be hot from the sun."'),
  ('en.sahih', 20, 120, 'Then Satan whispered to him; he said, "O Adam, shall I direct you to the tree of eternity and possession that will not deteriorate?"'),
  ('en.sahih', 20, 121, 'And Adam and his wife ate of it, and their private parts became apparent to them, and they began to fasten over themselves from the leaves of Paradise. And Adam disobeyed his Lord and erred.'),
  ('en.sahih', 20, 122, 'Then his Lord chose him and turned to him in forgiveness and guided [him].'),
  ('en.sahih', 20, 123, '[Allah] said, "Descend from Paradise - all, [your descendants] being enemies to one another. And if there should come to you guidance from Me - then whoever follows My guidance will neither go astray [in the world] nor suffer [in the Hereafter].'),
  ('en.sahih', 20, 124, 'And whoever turns away from My remembrance - indeed, he will have a depressed life, and We will gather him on the Day of Resurrection blind."'),
  ('en.sahih', 20, 125, 'He will say, "My Lord, why have you raised me blind while I was [once] seeing?"'),
  ('en.sahih', 20, 126, '[Allah] will say, "Thus did Our signs come to you, and you forgot them; and thus will you this Day be forgotten."'),
  ('en.sahih', 20, 127, 'And thus do We recompense he who transgressed and did not believe in the signs of his Lord. And the punishment of the Hereafter is more severe and more enduring.'),
  ('en.sahih', 20, 128, 'Then, has it not become clear to them how many generations We destroyed before them as they walk among their dwellings? Indeed in that are signs for those of intelligence.'),
  ('en.sahih', 20, 129, 'And if not for a word that preceded from your Lord, punishment would have been an obligation [due immediately], and [if not for] a specified term [decreed].'),
  ('en.sahih', 20, 130, 'So be patient over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting; and during periods of the night [exalt Him] and at the ends of the day, that you may be satisfied.'),
  ('en.sahih', 20, 131, 'And do not extend your eyes toward that by which We have given enjoyment to [some] categories of them, [its being but] the splendor of worldly life by which We test them. And the provision of your Lord is better and more enduring.'),
  ('en.sahih', 20, 132, 'And enjoin prayer upon your family [and people] and be steadfast therein. We ask you not for provision; We provide for you, and the [best] outcome is for [those of] righteousness.'),
  ('en.sahih', 20, 133, 'And they say, "Why does he not bring us a sign from his Lord?" Has there not come to them evidence of what was in the former scriptures?'),
  ('en.sahih', 20, 134, 'And if We had destroyed them with a punishment before him, they would have said, "Our Lord, why did You not send to us a messenger so we could have followed Your verses before we were humiliated and disgraced?"'),
  ('en.sahih', 20, 135, 'Say, "Each [of us] is waiting; so wait. For you will know who are the companions of the sound path and who is guided."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 20, 1, 'তোয়া-হা'),
  ('bn.bengali', 20, 2, 'আপনাকে ক্লেশ দেবার জন্য আমি আপনার প্রতি কোরআন অবতীর্ণ করিনি।'),
  ('bn.bengali', 20, 3, 'কিন্তু তাদেরই উপদেশের জন্য যারা ভয় করে।'),
  ('bn.bengali', 20, 4, 'এটা তাঁর কাছ থেকে অবতীর্ণ, যিনি ভূমন্ডল ও সমুচ্চ নভোমন্ডল সৃষ্টি করেছেন।'),
  ('bn.bengali', 20, 5, 'তিনি পরম দয়াময়, আরশে সমাসীন হয়েছেন।'),
  ('bn.bengali', 20, 6, 'নভোমন্ডলে, ভুমন্ডলে, এতদুভয়ের মধ্যবর্তী স্থানে এবং সিক্ত ভূগর্ভে যা আছে, তা তাঁরই।'),
  ('bn.bengali', 20, 7, 'যদি তুমি উচ্চকন্ঠেও কথা বল, তিনি তো গুপ্ত ও তদপেক্ষাও গুপ্ত বিষয়বস্তু জানেন।'),
  ('bn.bengali', 20, 8, 'আল্লাহ তিনি ব্যতীত কোন উপাস্য ইলাহ নেই। সব সৌন্দর্যমন্ডিত নাম তাঁরই।'),
  ('bn.bengali', 20, 9, 'আপনার কাছে মূসার বৃত্তান্ত পৌঁছেছে কি।'),
  ('bn.bengali', 20, 10, 'তিনি যখন আগুন দেখলেন, তখন পরিবারবর্গকে বললেনঃ তোমরা এখানে অবস্থান কর আমি আগুন দেখেছি। সম্ভবতঃ আমি তা থেকে তোমাদের কাছে কিছু আগুন জালিয়ে আনতে পারব অথবা আগুনে পৌছে পথের সন্ধান পাব।'),
  ('bn.bengali', 20, 11, 'অতঃপর যখন তিনি আগুনের কাছে পৌছলেন, তখন আওয়াজ আসল হে মূসা,'),
  ('bn.bengali', 20, 12, 'আমিই তোমার পালনকর্তা, অতএব তুমি জুতা খুলে ফেল, তুমি পবিত্র উপত্যকা তুয়ায় রয়েছ।'),
  ('bn.bengali', 20, 13, 'এবং আমি তোমাকে মনোনীত করেছি, অতএব যা প্রত্যাদেশ করা হচ্ছে, তা শুনতে থাক।'),
  ('bn.bengali', 20, 14, 'আমিই আল্লাহ আমি ব্যতীত কোন ইলাহ নেই। অতএব আমার এবাদত কর এবং আমার স্মরণার্থে নামায কায়েম কর।'),
  ('bn.bengali', 20, 15, 'কেয়ামত অবশ্যই আসবে, আমি তা গোপন রাখতে চাই; যাতে প্রত্যেকেই তার কর্মানুযায়ী ফল লাভ করে।'),
  ('bn.bengali', 20, 16, 'সুতরাং যে ব্যক্তি কেয়ামতে বিশ্বাস রাখে না এবং নিজ খাহেশের অনুসরণ করে, সে যেন তোমাকে তা থেকে নিবৃত্ত না করে। নিবৃত্ত হলে তুমি ধবংস হয়ে যাবে।'),
  ('bn.bengali', 20, 17, 'হে মূসা, তোমার ডানহাতে ওটা কি?'),
  ('bn.bengali', 20, 18, 'তিনি বললেনঃ এটা আমার লাঠি, আমি এর উপর ভর দেই এবং এর দ্বারা আমার ছাগপালের জন্যে বৃক্ষপত্র ঝেড়ে ফেলি এবং এতে আমার অন্যান্য কাজ ও চলে।'),
  ('bn.bengali', 20, 19, 'আল্লাহ বললেনঃ হে মূসা, তুমি ওটা নিক্ষেপ কর।'),
  ('bn.bengali', 20, 20, 'অতঃপর তিনি তা নিক্ষেপ করলেন, অমনি তা সাপ হয়ে ছুটাছুটি করতে লাগল।'),
  ('bn.bengali', 20, 21, 'আল্লাহ বললেনঃ তুমি তাকে ধর এবং ভয় করো না, আমি এখনি একে পূর্বাবস্থায় ফিরিয়ে দেব।'),
  ('bn.bengali', 20, 22, 'তোমার হাত বগলে রাখ, তা বের হয়ে আসবে নির্মল উজ্জ্বল হয়ে অন্য এক নিদর্শন রূপে; কোন দোষ ছাড়াই।'),
  ('bn.bengali', 20, 23, 'এটা এজন্যে যে, আমি আমার বিরাট নিদর্শনাবলীর কিছু তোমাকে দেখাই।'),
  ('bn.bengali', 20, 24, 'ফেরাউনের নিকট যাও, সে দারুণ উদ্ধত হয়ে গেছে।'),
  ('bn.bengali', 20, 25, 'মূসা বললেনঃ হে আমার পালনকর্তা আমার বক্ষ প্রশস্ত করে দিন।'),
  ('bn.bengali', 20, 26, 'এবং আমার কাজ সহজ করে দিন।'),
  ('bn.bengali', 20, 27, 'এবং আমার জিহবা থেকে জড়তা দূর করে দিন।'),
  ('bn.bengali', 20, 28, 'যাতে তারা আমার কথা বুঝতে পারে।'),
  ('bn.bengali', 20, 29, 'এবং আমার পরিবারবর্গের মধ্য থেকে আমার একজন সাহায্যকারী করে দিন।'),
  ('bn.bengali', 20, 30, 'আমার ভাই হারুনকে।'),
  ('bn.bengali', 20, 31, 'তার মাধ্যমে আমার কোমর মজবুত করুন।'),
  ('bn.bengali', 20, 32, 'এবং তাকে আমার কাজে অংশীদার করুন।'),
  ('bn.bengali', 20, 33, 'যাতে আমরা বেশী করে আপনার পবিত্রতা ও মহিমা ঘোষনা করতে পারি।'),
  ('bn.bengali', 20, 34, 'এবং বেশী পরিমাণে আপনাকে স্মরণ করতে পারি।'),
  ('bn.bengali', 20, 35, 'আপনি তো আমাদের অবস্থা সবই দেখছেন।'),
  ('bn.bengali', 20, 36, 'আল্লাহ বললেনঃ হে মূসা, তুমি যা চেয়েছ তা তোমাকে দেয়া হল।'),
  ('bn.bengali', 20, 37, 'আমি তোমার প্রতি আরও একবার অনুগ্রহ করেছিলাম।'),
  ('bn.bengali', 20, 38, 'যখন আমি তোমার মাতাকে নির্দেশ দিয়েছিলাম যা অতঃপর বর্ণিত হচ্ছে।'),
  ('bn.bengali', 20, 39, 'যে, তুমি (মূসাকে) সিন্দুকে রাখ, অতঃপর তা দরিয়ায় ভাসিয়ে দাও, অতঃপর দরিয়া তাকে তীরে ঠেলে দেবে। তাকে আমার শক্র ও তার শক্র উঠিয়ে নেবে। আমি তোমার প্রতি মহব্বত সঞ্চারিত করেছিলাম আমার নিজের পক্ষ থেকে, যাতে তুমি আমার দৃষ্টির সামনে প্রতি পালিত হও।'),
  ('bn.bengali', 20, 40, 'যখন তোমার ভগিনী এসে বললঃ আমি কি তোমাদেরকে বলে দেব কে তাকে লালন পালন করবে। অতঃপর আমি তোমাকে তোমার মাতার কাছে ফিরিয়ে দিলাম, যাতে তার চক্ষু শীতল হয় এবং দুঃখ না পায়। তুমি এক ব্যক্তিকে হত্যা করেছিলে, অতঃপর আমি তোমাকে এই দুশ্চিন্তা থেকে মুক্তি দেই; আমি তোমাকে অনেক পরীক্ষা করেছি। অতঃপর তুমি কয়েক বছর মাদইয়ান বাসীদের মধ্যে অবস্থান করেছিলে; হে মূসা, অতঃপর তুমি নির্ধারিত সময়ে এসেছ।'),
  ('bn.bengali', 20, 41, 'এবং আমি তোমাকে আমার নিজের জন্য তৈরী করে নিয়েছি।'),
  ('bn.bengali', 20, 42, 'তুমি ও তোমার ভাই আমার নিদর্শনাবলীসহ যাও এবং আমার স্মরণে শৈথিল্য করো না।'),
  ('bn.bengali', 20, 43, 'তোমরা উভয়ে ফেরআউনের কাছে যাও সে খুব উদ্ধত হয়ে গেছে।'),
  ('bn.bengali', 20, 44, 'অতঃপর তোমরা তাকে নম্র কথা বল, হয়তো সে চিন্তা-ভাবনা করবে অথবা ভীত হবে।'),
  ('bn.bengali', 20, 45, 'তারা বললঃ হে আমাদের পালনকর্তা, আমরা আশঙ্কা করি যে, সে আমাদের প্রতি জুলুম করবে কিংবা উত্তেজিত হয়ে উঠবে।'),
  ('bn.bengali', 20, 46, 'আল্লাহ বললেনঃ তোমরা ভয় করো না, আমি তোমাদের সাথে আছি, আমি শুনি ও দেখি।'),
  ('bn.bengali', 20, 47, 'অতএব তোমরা তার কাছে যাও এবং বলঃ আমরা উভয়েই তোমার পালনকর্তার প্রেরিত রসূল, অতএব আমাদের সাথে বনী ইসরাঈলকে যেতে দাও এবং তাদেরকে নিপীড়ন করো না। আমরা তোমার পালনকর্তার কাছ থেকে নিদর্শন নিয়ে তোমার কাছে আগমন করেছি। এবং যে সৎপথ অনুসরণ করে, তার প্রতি শান্তি।'),
  ('bn.bengali', 20, 48, 'আমরা ওহী লাভ করেছি যে, যে ব্যক্তি মিথ্যারোপ করে এবং মুখ ফিরিয়ে নেয়, তার উপর আযাব পড়বে।'),
  ('bn.bengali', 20, 49, 'সে বললঃ তবে হে মূসা, তোমাদের পালনকর্তা কে?'),
  ('bn.bengali', 20, 50, 'মূসা বললেনঃ আমাদের পালনকর্তা তিনি, যিনি প্রত্যেক বস্তুকে তার যোগ্য আকৃতি দান করেছেন, অতঃপর পথপ্রদর্শন করেছেন।'),
  ('bn.bengali', 20, 51, 'ফেরাউন বললঃ তাহলে অতীত যুগের লোকদের অবস্থা কি?'),
  ('bn.bengali', 20, 52, 'মূসা বললেনঃ তাদের খবর আমার পালনকর্তার কাছে লিখিত আছে। আমার পালনকর্তা ভ্রান্ত হন না এং বিস্মৃতও হন না।'),
  ('bn.bengali', 20, 53, 'তিনি তোমাদের জন্যে পৃথিবীকে শয্যা করেছেন এবং তাতে চলার পথ করেছেন, আকাশ থেকে বৃষ্টি বর্ষণ করেছেন এবং তা দ্বারা আমি বিভিন্ন প্রকার উদ্ভিদ উৎপন্ন করেছি।'),
  ('bn.bengali', 20, 54, 'তোমরা আহার কর এবং তোমাদের চতুস্পদ জন্তু চরাও। নিশ্চয় এতে বিবেক বানদের জন্যে নিদর্শন রয়েছে।'),
  ('bn.bengali', 20, 55, 'এ মাটি থেকেই আমি তোমাদেরকে সৃজন করেছি, এতেই তোমাদেরকে ফিরিয়ে দিব এবং পুনরায় এ থেকেই আমি তোমাদেরকে উত্থিত করব।'),
  ('bn.bengali', 20, 56, 'আমি ফেরাউনকে আমার সব নিদর্শন দেখিয়ে দিয়েছি, অতঃপর সে মিথ্যা আরোপ করেছে এবং অমান্য করেছে।'),
  ('bn.bengali', 20, 57, 'সে বললঃ হে মূসা, তুমি কি যাদুর জোরে আমাদেরকে দেশ থেকে বহিষ্কার করার জন্যে আগমন করেছ?'),
  ('bn.bengali', 20, 58, 'অতএব, আমরাও তোমার মোকাবেলায় তোমার নিকট অনুরূপ যাদু উপস্থিত করব। সুতরাং আমাদের ও তোমার মধ্যে একটি ওয়াদার দিন ঠিক কর, যার খেলাফ আমরাও করব না এবং তুমিও করবে না একটি পরিষ্কার প্রান্তরে।'),
  ('bn.bengali', 20, 59, 'মূসা বললঃ তোমাদের ওয়াদার দিন উৎসবের দিন এবং পূর্বাহেߠলোকজন সমবেত হবে।'),
  ('bn.bengali', 20, 60, 'অতঃপর ফেরাউন প্রস্থান করল এবং তার সব কলাকৌশল জমা করল অতঃপর উপস্থিত হল।'),
  ('bn.bengali', 20, 61, 'মূসা (আঃ) তাদেরকে বললেনঃ দুর্ভাগ্য তোমাদের; তোমরা আল্লাহর প্রতি মিথ্যা আরোপ করো না। তাহলে তিনি তোমাদেরকে আযাব দ্বারা ধবংস করে দেবেন। যে মিথ্যা উদভাবন করে, সেই বিফল মনোরথ হয়েছে।'),
  ('bn.bengali', 20, 62, 'অতঃপর তারা তাদের কাজে নিজেদের মধ্যে বিতর্ক করল এবং গোপনে পরামর্শ করল।'),
  ('bn.bengali', 20, 63, 'তারা বললঃ এই দুইজন নিশ্চিতই যাদুকর, তারা তাদের যাদু দ্বারা তোমাদেরকে তোমাদের দেশ থেকে বহিস্কার করতে চায় এবং তোমাদের উৎকৃষ্ট জীবন ব্যবস্থা রহিত করতে চায়।'),
  ('bn.bengali', 20, 64, 'অতএব, তোমরা তোমাদের কলাকৌশল সুসংহত কর, অতঃপর সারিবদ্ধ হয়ে আস। আজ যে জয়ী হবে, সেই সফলকাম হবে।'),
  ('bn.bengali', 20, 65, 'তারা বললঃ হে মূসা, হয় তুমি নিক্ষেপ কর, না হয় আমরা প্রথমে নিক্ষেপ করি।'),
  ('bn.bengali', 20, 66, 'মূসা বললেনঃ বরং তোমরাই নিক্ষেপ কর। তাদের যাদুর প্রভাবে হঠাৎ তাঁর মনে হল, যেন তাদের রশিগুলো ও লাঠিগুলো চুটাছুটি করছে।'),
  ('bn.bengali', 20, 67, 'অতঃপর মূসা মনে মনে কিছুটা ভীতি অনুভব করলেন।'),
  ('bn.bengali', 20, 68, 'আমি বললামঃ ভয় করো না, তুমি বিজয়ী হবে।'),
  ('bn.bengali', 20, 69, 'তোমার ডান হাতে যা আছে তুমি তা নিক্ষেপ কর। এটা যা কিছু তারা করেছে তা গ্রাস করে ফেলবে। তারা যা করেছে তা তো কেবল যাদুকরের কলাকৌশল। যাদুকর যেখানেই থাকুক, সফল হবে না।'),
  ('bn.bengali', 20, 70, 'অতঃপর যাদুকররা সেজদায় পড়ে গেল। তারা বললঃ আমরা হারুন ও মূসার পালনকর্তার প্রতি বিশ্বাস স্থাপন করলাম।'),
  ('bn.bengali', 20, 71, 'ফেরাউন বললঃ আমার অনুমতি দানের পূর্বেই? তোমরা কি তার প্রতি বিশ্বাস স্থাপন করলে; দেখছি সেই তোমাদের প্রধান, সে তোমাদেরকে যাদু শিক্ষা দিয়েছে। অতএব আমি অবশ্যই তোমাদের হস্তপদ বিপরীত দিক থেকে কর্তন করব এবং আমি তোমাদেরকে খর্জুর বৃক্ষের কান্ডে শূলে চড়াব এবং তোমরা নিশ্চিত রূপেই জানতে পারবে আমাদের মধ্যে কার আযাব কঠোরতর এবং অধিক্ষণ স্থায়ী।'),
  ('bn.bengali', 20, 72, 'যাদুকররা বললঃ আমাদের কাছে যে, সুস্পষ্ট প্রমাণ এসেছে তার উপর এবং যিনি আমাদের কে সৃষ্টি করেছেন, তাঁর উপর আমরা কিছুতেই তোমাকে প্রাধান্য দেব না। অতএব, তুমি যা ইচ্ছা করতে পার। তুমি তো শুধু এই পার্থিব জীবনেই যা করার করবে।'),
  ('bn.bengali', 20, 73, 'আমরা আমাদের পালনকর্তার প্রতি বিশ্বাস স্থাপন করেছি যাতে তিনি আমাদের পাপ এবং তুমি আমাদেরকে যে যাদু করতে বাধ্য করেছ, তা মার্জনা করেন। আল্লাহ শ্রেষ্ঠ ও চিরস্থায়ী।'),
  ('bn.bengali', 20, 74, 'নিশ্চয়ই যে তার পালনকর্তার কাছে অপরাধী হয়ে আসে, তার জন্য রয়েছে জাহান্নাম। সেখানে সে মরবে না এবং বাঁচবেও না।'),
  ('bn.bengali', 20, 75, 'আর যারা তাঁর কাছে আসে এমন ঈমানদার হয়ে যায় সৎকর্ম সম্পাদন করেছে, তাদের জন্যে রয়েছে সুউচ্চ মর্তবা।'),
  ('bn.bengali', 20, 76, 'বসবাসের এমন পুষ্পোদ্যান রয়েছে যার তলদেশে দিয়ে নির্ঝরিণীসমূহ প্রবাহিত হয়। সেখানে তারা চিরকাল থাকবে এটা তাদেরই পুরস্কার, যারা পবিত্র হয়।'),
  ('bn.bengali', 20, 77, 'আমি মূসা প্রতি এই মর্মে ওহী করলাম যে, আমার বান্দাদেরকে নিয়ে রাত্রিযোগে বের হয়ে যাও এবং তাদের জন্যে সমুদ্রে শুষ্কপথ নির্মাণ কর। পেছন থেকে এসে তোমাদের ধরে ফেলার আশঙ্কা করো না এবং পানিতে ডুবে যাওয়ার ভয় করো না।'),
  ('bn.bengali', 20, 78, 'অতঃপর ফেরাউন তার সৈন্যবাহিনী নিয়ে তাদের পশ্চাদ্ধাবন করল এবং সমুদ্র তাদেরকে সম্পূর্ণরূপে নিমজ্জত করল।'),
  ('bn.bengali', 20, 79, 'ফেরআউন তার সম্প্রদায়কে বিভ্রান্ত করেছিল এবং সৎপথ দেখায়নি।'),
  ('bn.bengali', 20, 80, 'হে বনী-ইসরাঈল! আমি তোমাদেরকে তোমাদের শক্রুর কবল থেকে উদ্ধার করেছি, তুর পাহাড়ের দক্ষিণ পার্শ্বে তোমাদেরকে প্রতিশ্রুতি দান করেছি এবং তোমাদের কাছে ‘মান্না’ ও ‘সালওয়া’ নাযিল করেছি।'),
  ('bn.bengali', 20, 81, 'বলেছিঃ আমার দেয়া পবিত্র বস্তুসমূহ খাও এবং এতে সীমালংঘন করো না, তা হলে তোমাদের উপর আমার ক্রোধ নেমে আসবে এবং যার উপর আমার ক্রোধ নেমে আসে সে ধবংস হয়ে যায়।'),
  ('bn.bengali', 20, 82, 'আর যে তওবা করে, ঈমান আনে এবং সৎকর্ম করে অতঃপর সৎপথে অটল থাকে, আমি তার প্রতি অবশ্যই ক্ষমাশীল।'),
  ('bn.bengali', 20, 83, 'হে মূসা, তোমার সম্প্রদায়কে পেছনে ফেলে তুমি ত্বরা করলে কেন?'),
  ('bn.bengali', 20, 84, 'তিনি বললেনঃ এই তো তারা আমার পেছনে আসছে এবং হে আমার পালনকর্তা, আমি তাড়াতাড়ি তোমার কাছে এলাম, যাতে তুমি সন্তুষ্ট হও।'),
  ('bn.bengali', 20, 85, 'বললেনঃ আমি তোমার সম্প্রদায়কে পরীক্ষা করেছি তোমার পর এবং সামেরী তাদেরকে পথভ্রষ্ট করেছে।'),
  ('bn.bengali', 20, 86, 'অতঃপর মূসা তাঁর সম্প্রদায়ের কাছে ফিরে গেলেন ক্রদ্ধ ও অনুতপ্ত অবস্থায়। তিনি বললেনঃ হে আমার সম্প্রদায়, তোমাদের পালনকর্তা কি তোমাদেরকে একটি উত্তম প্রতিশ্রুতি দেননি? তবে কি প্রতিশ্রুতির সময়কাল তোমাদের কাছে দীর্ঘ হয়েছে, না তোমরা চেয়েছ যে, তোমাদের উপর তোমাদের পালনকর্তার ক্রোধ নেমে আসুক, যে কারণে তোমরা আমার সাথে কৃত ওয়াদা ভঙ্গ করলে?'),
  ('bn.bengali', 20, 87, 'তারা বললঃ আমরা তোমার সাথে কৃত ওয়াদা স্বেচ্ছায় ভঙ্গ করিনি; কিন্তু আমাদের উপর ফেরউনীদের অলংকারের বোঝা চাপিয়ে দেয়া হয়েছিল। অতঃপর আমরা তা নিক্ষেপ করে দিয়েছি। এমনি ভাবে সামেরীও নিক্ষেপ করেছে।'),
  ('bn.bengali', 20, 88, 'অতঃপর সে তাদের জন্য তৈরী করে বের করল একটি গো-বৎস, একটা দেহ, যার মধ্যে গরুর শব্দ ছিল। তারা বললঃ এটা তোমাদের উপাস্য এবং মূসার ও উপাস্য, অতঃপর মূসা ভুলে গেছে।'),
  ('bn.bengali', 20, 89, 'তারা কি দেখে না যে, এটা তাদের কোন কথার উত্তর দেয় না এবং তারে কোন ক্ষতি ও উপকার করার ক্ষমতাও রাখে না?'),
  ('bn.bengali', 20, 90, 'হারুন তাদেরকে পুর্বেই বলেছিলেনঃ হে আমার কওম, তোমরা তো এই গো-বৎস দ্বারা পরীক্ষায় নিপতিত হয়েছ এবং তোমাদের পালনকর্তা দয়াময়। অতএব, তোমরা আমার অনুসরণ কর এবং আমার আদেশ মেনে চল।'),
  ('bn.bengali', 20, 91, 'তারা বললঃ মূসা আমাদের কাছে ফিরে আসা পর্যন্ত আমরা সদাসর্বদা এর সাথেই সংযুক্ত হয়ে বসে থাকব।'),
  ('bn.bengali', 20, 92, 'মূসা বললেনঃ হে হারুন, তুমি যখন তাদেরকে পথ ভ্রষ্ট হতে দেখলে, তখন তোমাকে কিসে নিবৃত্ত করল ?'),
  ('bn.bengali', 20, 93, 'আমার পদাঙ্ক অনুসরণ করা থেকে? তবে তুমি কি আমার আদেশ অমান্য করেছ?'),
  ('bn.bengali', 20, 94, 'তিনি বললেনঃ হে আমার জননী-তনয়, আমার শ্মশ্রু ও মাথার চুল ধরে আকর্ষণ করো না; আমি আশঙ্কা করলাম যে, তুমি বলবেঃ তুমি বনী-ইসরাঈলের মধ্যে বিভেদ সৃষ্টি করেছ এবং আমার কথা স্মরণে রাখনি।'),
  ('bn.bengali', 20, 95, 'মূসা বললেন হে সামেরী, এখন তোমার ব্যাপার কি?'),
  ('bn.bengali', 20, 96, 'সে বললঃ আমি দেখলাম যা অন্যেরা দেখেনি। অতঃপর আমি সেই প্রেরিত ব্যক্তির পদচিহেߦ#2480; নীচ থেকে এক মুঠি মাটি নিয়ে নিলাম। অতঃপর আমি তা নিক্ষেপ করলাম। আমাকে আমার মন এই মন্ত্রণাই দিল।'),
  ('bn.bengali', 20, 97, 'মূসা বললেনঃ দূর হ, তোর জন্য সারা জীবন এ শাস্তিই রইল যে, তুই বলবি; আমাকে স্পর্শ করো না, এবং তোর জন্য একটি নির্দিষ্ট ওয়াদা আছে, যার ব্যতিক্রম হবে না। তুই তোর সেই ইলাহের প্রতি লক্ষ্য কর, যাকে তুই ঘিরে থাকতি। আমরা সেটি জালিয়ে দেবই। অতঃপর একে বিক্ষিপ্ত করে সাগরে ছড়িয়ে দেবই।'),
  ('bn.bengali', 20, 98, 'তোমাদের ইলাহ তো কেবল আল্লাহই, যিনি ব্যতীত অন্য কোন ইলাহ নেই। সব বিষয় তাঁর জ্ঞানের পরিধিভুক্ত।'),
  ('bn.bengali', 20, 99, 'এমনিভাবে আমি পূর্বে যা ঘটেছে, তার সংবাদ আপনার কাছে বর্ণনা করি। আমি আমার কাছ থেকে আপনাকে দান করেছি পড়ার গ্রন্থ।'),
  ('bn.bengali', 20, 100, 'যে এ থেকে মুখ ফিরিয়ে নেবে, সে কেয়ামতের দিন বোঝা বহন করবে।'),
  ('bn.bengali', 20, 101, 'তারা তাতে চিরকাল থাকবে এবং কেয়ামতের দিন এই বোঝা তাদের জন্যে মন্দ হবে।'),
  ('bn.bengali', 20, 102, 'যেদিন সিঙ্গায় ফূৎকার দেয়া হবে, সেদিন আমি অপরাধীদেরকে সমবেত করব নীল চক্ষু অবস্থায়।'),
  ('bn.bengali', 20, 103, 'তারা চুপিসারে পরস্পরে বলাবলি করবেঃ তোমরা মাত্র দশ দিন অবস্থান করেছিলে।'),
  ('bn.bengali', 20, 104, 'তারা কি বলে তা আমি ভালোভাবে জানি। তাদের মধ্যে যে, অপেক্ষাকৃত উত্তম পথের অনুসারী সে বলবেঃ তোমরা মাত্র একদিন অবস্থান করেছিলে।'),
  ('bn.bengali', 20, 105, 'তারা আপনাকে পাহাড় সম্পর্কে প্রশ্ন করা। অতএব, আপনি বলুনঃ আমার পালনকর্তা পহাড়সমূহকে সমূলে উৎপাটন করে বিক্ষিপ্ত করে দিবেন।'),
  ('bn.bengali', 20, 106, 'অতঃপর পৃথিবীকে মসৃণ সমতলভূমি করে ছাড়বেন।'),
  ('bn.bengali', 20, 107, 'তুমি তাতে মোড় ও টিলা দেখবে না।'),
  ('bn.bengali', 20, 108, 'সেই দিন তারা আহবানকারীর অনুসরণ করবে, যার কথা এদিক-সেদিক হবে না এবং দয়াময় আল্লাহর ভয়ে সব শব্দ ক্ষীণ হয়ে যাবে। সুতরাং মৃদু গুঞ্জন ব্যতীত তুমি কিছুই শুনবে না।'),
  ('bn.bengali', 20, 109, 'দয়াময় আল্লাহ যাকে অনুমতি দেবেন এবং যার কথায় সন্তুষ্ট হবেন সে ছাড়া কারও সুপারিশ সেদিন কোন উপকারে আসবে না।'),
  ('bn.bengali', 20, 110, 'তিনি জানেন যা কিছু তাদের সামনে ও পশ্চাতে আছে এবং তারা তাকে জ্ঞান দ্বারা আয়ত্ত করতে পারে না।'),
  ('bn.bengali', 20, 111, 'সেই চিরঞ্জীব চিরস্থায়ীর সামনে সব মুখমন্ডল অবনমিত হবে এবং সে ব্যর্থ হবে যে জুলুমের বোঝা বহন করবে।'),
  ('bn.bengali', 20, 112, 'যে ঈমানদার অবস্থায় সৎকর্ম সম্পাদন করে, সে জুলুম ও ক্ষতির আশঙ্কা করবে না।'),
  ('bn.bengali', 20, 113, 'এমনিভাবে আমি আরবী ভাষায় কোরআন নাযিল করেছি এবং এতে নানাভাবে সতর্কবাণী ব্যক্ত করেছি, যাতে তারা আল্লাহভীরু হয় অথবা তাদের অন্তরে চিন্তার খোরাক যোগায়।'),
  ('bn.bengali', 20, 114, 'সত্যিকার অধীশ্বর আল্লাহ মহান। আপনার প্রতি আল্লাহর ওহী সম্পুর্ণ হওয়ার পূর্বে আপনি কোরআন গ্রহণের ব্যপারে তাড়াহুড়া করবেন না এবং বলুনঃ হে আমার পালনকর্তা, আমার জ্ঞান বৃদ্ধি করুন।'),
  ('bn.bengali', 20, 115, 'আমি ইতিপূর্বে আদমকে নির্দেশ দিয়েছিলাম। অতঃপর সে ভুলে গিয়েছিল এবং আমি তার মধ্যে দৃঢ়তা পাইনি।'),
  ('bn.bengali', 20, 116, 'যখন আমি ফেরেশতাদেরকে বললামঃ তোমরা আদমকে সেজদা কর, তখন ইবলীস ব্যতীত সবাই সেজদা করল। সে অমান্য করল।'),
  ('bn.bengali', 20, 117, 'অতঃপর আমি বললামঃ হে আদম, এ তোমার ও তোমার স্ত্রীর শত্রু, সুতরাং সে যেন বের করে না দেয় তোমাদের জান্নাত থেকে। তাহলে তোমরা কষ্টে পতিত হবে।'),
  ('bn.bengali', 20, 118, 'তোমাকে এই দেয়া হল যে, তুমি এতে ক্ষুধার্ত হবে না এবং বস্ত্রহীণ হবে না।'),
  ('bn.bengali', 20, 119, 'এবং তোমার পিপাসাও হবে না এবং রৌদ্রেও কষ্ট পাবে না।'),
  ('bn.bengali', 20, 120, 'অতঃপর শয়তান তাকে কুমন্ত্রনা দিল, বললঃ হে আদম, আমি কি তোমাকে বলে দিব অনন্তকাল জীবিত থাকার বৃক্ষের কথা এবং অবিনশ্বর রাজত্বের কথা?'),
  ('bn.bengali', 20, 121, 'অতঃপর তারা উভয়েই এর ফল ভক্ষণ করল, তখন তাদের সামনে তাদের লজ্জাস্থান খুলে গেল এবং তারা জান্নাতের বৃক্ষ-পত্র দ্বারা নিজেদেরকে আবৃত করতে শুরু করল। আদম তার পালনকর্তার অবাধ্যতা করল, ফলে সে পথ ভ্রষ্ঠ হয়ে গেল।'),
  ('bn.bengali', 20, 122, 'এরপর তার পালনকর্তা তাকে মনোনীত করলেন, তার প্রতি মনোযোগী হলেন এবং তাকে সুপথে আনয়ন করলেন।'),
  ('bn.bengali', 20, 123, 'তিনি বললেনঃ তোমরা উভয়েই এখান থেকে এক সঙ্গে নেমে যাও। তোমরা একে অপরের শত্রু। এরপর যদি আমার পক্ষ থেকে তোমাদের কাছে হেদায়েত আসে, তখন যে আমার বর্ণিত পথ অনুসরণ করবে, সে পথভ্রষ্ঠ হবে না এবং কষ্টে পতিত হবে না।'),
  ('bn.bengali', 20, 124, 'এবং যে আমার স্মরণ থেকে মুখ ফিরিয়ে নেবে, তার জীবিকা সংকীর্ণ হবে এবং আমি তাকে কেয়ামতের দিন অন্ধ অবস্থায় উত্থিত করব।'),
  ('bn.bengali', 20, 125, 'সে বলবেঃ হে আমার পালনকর্তা আমাকে কেন অন্ধ অবস্থায় উত্থিত করলেন? আমি তো চক্ষুমান ছিলাম।'),
  ('bn.bengali', 20, 126, 'আল্লাহ বলবেনঃ এমনিভাবে তোমার কাছে আমার আয়াতসমূহ এসেছিল, অতঃপর তুমি সেগুলো ভুলে গিয়েছিলে। তেমনিভাবে আজ তোমাকে ভুলে যাব।'),
  ('bn.bengali', 20, 127, 'এমনিভাবে আমি তাকে প্রতিফল দেব, যে সীমালঙ্ঘন করে এবং পালনকর্তার কথায় বিশ্বাস স্থাপন না করে। তার পরকালের শাস্তি কঠোরতর এবং অনেক স্থায়ী।'),
  ('bn.bengali', 20, 128, 'আমি এদের পূর্বে অনেক সম্প্রদায়কে ধবংস করেছি। যাদের বাসভুমিতে এরা বিচরণ করে, এটা কি এদেরকে সৎপথ প্রদর্শন করল না? নিশ্চয় এতে বুদ্ধিমানদের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 20, 129, 'আপনার পালনকর্তার পক্ষ থেকে পূর্ব সিদ্ধান্ত এবং একটি কাল নির্দিষ্ট না থাকলে শাস্তি অবশ্যম্ভাবী হয়ে যেত।'),
  ('bn.bengali', 20, 130, 'সুতরাং এরা যা বলে সে বিষয়ে ধৈর্য্য ধারণ করুন এবং আপনার পালনকর্তার প্রশংসা পবিত্রতা ও মহিমা ঘোষনা করুন সূর্যোদয়ের পূর্বে, সূর্যাস্তের পূর্বে এবং পবিত্রতা ও মহিমা ঘোষনা করুন রাত্রির কিছু অংশ ও দিবাভাগে, সম্ভবতঃ তাতে আপনি সন্তুষ্ট হবেন।'),
  ('bn.bengali', 20, 131, 'আমি এদের বিভিন্ন প্রকার লোককে পরীক্ষা করার জন্যে পার্থিবজীবনের সৌন্দর্য স্বরূপ ভোগ-বিলাসের যে উপকরণ দিয়েছি, আপনি সেই সব বস্তুর প্রতি দৃষ্টি নিক্ষেপ করবেন না। আপনার পালনকর্তার দেয়া রিযিক উৎকৃষ্ট ও অধিক স্থায়ী।'),
  ('bn.bengali', 20, 132, 'আপনি আপনার পরিবারের লোকদেরকে নামাযের আদেশ দিন এবং নিজেও এর ওপর অবিচল থাকুন। আমি আপনার কাছে কোন রিযিক চাই না। আমি আপনাকে রিযিক দেই এবং আল্লাহ ভীরুতার পরিণাম শুভ।'),
  ('bn.bengali', 20, 133, 'এরা বলেঃ সে আমাদের কাছে তার পালনকর্তার কাছ থেকে কোন নিদর্শন আনয়ন করে না কেন? তাদের কাছে কি প্রমাণ আসেনি, যা পূর্ববর্তী গ্রন্থসমূহে আছে?'),
  ('bn.bengali', 20, 134, 'যদি আমি এদেরকে ইতিপূর্বে কোন শাস্তি দ্বারা ধ্বংস করতাম, তবে এরা বলতঃ হে আমাদের পালনকর্তা, আপনি আমাদের কাছে একজন রসূল প্রেরণ করলেন না কেন? তাহলে তো আমরা অপমানিত ও হেয় হওয়ার পূর্বেই আপনার নিদর্শন সমূহ মেনে চলতাম।'),
  ('bn.bengali', 20, 135, 'বলুন, প্রত্যেকেই পথপানে চেয়ে আছে, সুতরাং তোমরাও পথপানে চেয়ে থাক। অদূর ভবিষ্যতে তোমরা জানতে পারবে কে সরল পথের পথিক এবং কে সৎপথ প্রাপ্ত হয়েছে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 20, 1, 'Ta. Ha.'),
  ('en.pickthall', 20, 2, 'We have not revealed unto thee (Muhammad) this Qur\'an that thou shouldst be distressed,'),
  ('en.pickthall', 20, 3, 'But as a reminder unto him who feareth,'),
  ('en.pickthall', 20, 4, 'A revelation from Him Who created the earth and the high heavens,'),
  ('en.pickthall', 20, 5, 'The Beneficent One, Who is established on the Throne.'),
  ('en.pickthall', 20, 6, 'Unto Him belongeth whatsoever is in the heavens and whatsoever is in the earth, and whatsoever is between them, and whatsoever is beneath the sod.'),
  ('en.pickthall', 20, 7, 'And if thou speakest aloud, then lo! He knoweth the secret (thought) and (that which is yet) more hidden.'),
  ('en.pickthall', 20, 8, 'Allah! There is no Allah save Him. His are the most beautiful names.'),
  ('en.pickthall', 20, 9, 'Hath there come unto thee the story of Moses?'),
  ('en.pickthall', 20, 10, 'When he saw a fire and said unto his folk: Lo! Wait! I see a fire afar off. Peradventure I may bring you a brand therefrom or may find guidance at the fire.'),
  ('en.pickthall', 20, 11, 'And when he reached it, he was called by name: O Moses!'),
  ('en.pickthall', 20, 12, 'Lo! I, even I, am thy Lord, So take off thy shoes, for lo! thou art in the holy valley of Tuwa.'),
  ('en.pickthall', 20, 13, 'And I have chosen thee, so hearken unto that which is inspired.'),
  ('en.pickthall', 20, 14, 'Lo! I, even I, am Allah, There is no Allah save Me. So serve Me and establish worship for My remembrance.'),
  ('en.pickthall', 20, 15, 'Lo! the Hour is surely coming. But I will to keep it hidden, that every soul may be rewarded for that which it striveth (to achieve).'),
  ('en.pickthall', 20, 16, 'Therefor, let not him turn thee aside from (the thought of) it who believeth not therein but followeth his own desire, lest thou perish.'),
  ('en.pickthall', 20, 17, 'And what is that in thy right hand, O Moses?'),
  ('en.pickthall', 20, 18, 'He said: This is my staff whereon I lean, and wherewith I bear down branches for my sheep, and wherein I find other uses.'),
  ('en.pickthall', 20, 19, 'He said: Cast it down, O Moses!'),
  ('en.pickthall', 20, 20, 'So he cast it down, and lo! it was a serpent, gliding.'),
  ('en.pickthall', 20, 21, 'He said: Grasp it and fear not. We shall return it to its former state.'),
  ('en.pickthall', 20, 22, 'And thrust thy hand within thine armpit, it will come forth white without hurt. (That will be) another token.'),
  ('en.pickthall', 20, 23, 'That We may show thee (some) of Our greater portents,'),
  ('en.pickthall', 20, 24, 'Go thou unto Pharaoh! Lo! he hath transgressed (the bounds).'),
  ('en.pickthall', 20, 25, '(Moses) said: My Lord! relieve my mind'),
  ('en.pickthall', 20, 26, 'And ease my task for me;'),
  ('en.pickthall', 20, 27, 'And loose a knot from my tongue,'),
  ('en.pickthall', 20, 28, 'That they may understand my saying.'),
  ('en.pickthall', 20, 29, 'Appoint for me a henchman from my folk,'),
  ('en.pickthall', 20, 30, 'Aaron, my brother.'),
  ('en.pickthall', 20, 31, 'Confirm my strength with him'),
  ('en.pickthall', 20, 32, 'And let him share my task,'),
  ('en.pickthall', 20, 33, 'That we may glorify Thee much'),
  ('en.pickthall', 20, 34, 'And much remember Thee.'),
  ('en.pickthall', 20, 35, 'Lo! Thou art ever Seeing us.'),
  ('en.pickthall', 20, 36, 'He said: Thou art granted thy request, O Moses.'),
  ('en.pickthall', 20, 37, 'And indeed, another time, already We have shown thee favour,'),
  ('en.pickthall', 20, 38, 'When we inspired in thy mother that which is inspired,'),
  ('en.pickthall', 20, 39, 'Saying: Throw him into the ark, and throw it into the river, then the river shall throw it on to the bank, and there an enemy to Me and an enemy to him shall take him. And I endued thee with love from Me that thou mightest be trained according to My will,'),
  ('en.pickthall', 20, 40, 'When thy sister went and said: Shall I show you one who will nurse him? and we restored thee to thy mother that her eyes might be refreshed and might not sorrow. And thou didst kill a man and We delivered thee from great distress, and tried thee with a heavy trial. And thou didst tarry years among the folk of Midian. Then camest thou (hither) by (My) providence, O Moses,'),
  ('en.pickthall', 20, 41, 'And I have attached thee to Myself.'),
  ('en.pickthall', 20, 42, 'Go, thou and thy brother, with My tokens, and be not faint in remembrance of Me.'),
  ('en.pickthall', 20, 43, 'Go, both of you, unto Pharaoh. Lo! he hath transgressed (the bounds).'),
  ('en.pickthall', 20, 44, 'And speak unto him a gentle word, that peradventure he may heed or fear.'),
  ('en.pickthall', 20, 45, 'They said: Our Lord! Lo! we fear that he may be beforehand with us or that he may play the tyrant.'),
  ('en.pickthall', 20, 46, 'He said: Fear not. Lo! I am with you twain, Hearing and Seeing.'),
  ('en.pickthall', 20, 47, 'So go ye unto him and say: Lo! we are two messengers of thy Lord. So let the children of Israel go with us, and torment them not. We bring thee a token from thy Lord. And peace will be for him who followeth right guidance.'),
  ('en.pickthall', 20, 48, 'Lo! it hath been revealed unto us that the doom will be for him who denieth and turneth away.'),
  ('en.pickthall', 20, 49, '(Pharaoh) said: Who then is the Lord of you twain, O Moses?'),
  ('en.pickthall', 20, 50, 'He said: Our Lord is He Who gave unto everything its nature, then guided it aright.'),
  ('en.pickthall', 20, 51, 'He said: What then is the state of the generations of old?'),
  ('en.pickthall', 20, 52, 'He said: The knowledge thereof is with my Lord in a Record. My Lord neither erreth nor forgetteth,'),
  ('en.pickthall', 20, 53, 'Who hath appointed the earth as a bed and hath threaded roads for you therein and hath sent down water from the sky and thereby We have brought forth divers kinds of vegetation,'),
  ('en.pickthall', 20, 54, '(Saying): Eat ye and feed your cattle. Lo! herein verily are portents for men of thought.'),
  ('en.pickthall', 20, 55, 'Thereof We created you, and thereunto We return you, and thence We bring you forth a second time.'),
  ('en.pickthall', 20, 56, 'And We verily did show him all Our tokens, but he denied them and refused.'),
  ('en.pickthall', 20, 57, 'He said: Hast come to drive us out from our land by thy magic, O Moses?'),
  ('en.pickthall', 20, 58, 'But we surely can produce for thee magic the like thereof; so appoint a tryst between us and you, which neither we nor thou shall fail to keep, at a place convenient (to us both).'),
  ('en.pickthall', 20, 59, '(Moses) said: Your tryst shall be the day of the feast, and let the people assemble when the sun hath risen high.'),
  ('en.pickthall', 20, 60, 'Then Pharaoh went and gathered his strength, then came (to the appointed tryst).'),
  ('en.pickthall', 20, 61, 'Moses said unto them: Woe unto you! Invent not a lie against Allah, lest He extirpate you by some punishment. He who lieth faileth miserably.'),
  ('en.pickthall', 20, 62, 'Then they debated one with another what they must do, and they kept their counsel secret.'),
  ('en.pickthall', 20, 63, 'They said: Lo! these are two wizards who would drive you out from your country by their magic, and destroy your best traditions;'),
  ('en.pickthall', 20, 64, 'So arrange your plan, and come in battle line. Whoso is uppermost this day will be indeed successful.'),
  ('en.pickthall', 20, 65, 'They said: O Moses! Either throw first, or let us be the first to throw?'),
  ('en.pickthall', 20, 66, 'He said: Nay, do ye throw! Then lo! their cords and their staves, by their magic, appeared to him as though they ran.'),
  ('en.pickthall', 20, 67, 'And Moses conceived a fear in his mind.'),
  ('en.pickthall', 20, 68, 'We said: Fear not! Lo! thou art the higher.'),
  ('en.pickthall', 20, 69, 'Throw that which is in thy right hand! It will eat up that which they have made. Lo! that which they have made is but a wizard\'s artifice, and a wizard shall not be successful to whatever point (of skill) he may attain.'),
  ('en.pickthall', 20, 70, 'Then the wizards were (all) flung down prostrate, crying: We believe in the Lord of Aaron and Moses.'),
  ('en.pickthall', 20, 71, '(Pharaoh) said: Ye put faith in him before I give you leave. Lo! he is your chief who taught you magic. Now surely I shall cut off your hands and your feet alternately, and I shall crucify you on the trunks of palm trees, and ye shall know for certain which of us hath sterner and more lasting punishment.'),
  ('en.pickthall', 20, 72, 'They said: We choose thee not above the clear proofs that have come unto us, and above Him Who created us. So decree what thou wilt decree. Thou wilt end for us only this life of the world.'),
  ('en.pickthall', 20, 73, 'Lo! we believe in our Lord, that He may forgive us our sins and the magic unto which thou didst force us. Allah is better and more lasting.'),
  ('en.pickthall', 20, 74, 'Lo! whoso cometh guilty unto his Lord, verily for him is hell. There he will neither die nor live.'),
  ('en.pickthall', 20, 75, 'But whoso cometh unto Him a believer, having done good works, for such are the high stations;'),
  ('en.pickthall', 20, 76, 'Gardens of Eden underneath which rivers flow, wherein they will abide for ever. That is the reward of him who groweth.'),
  ('en.pickthall', 20, 77, 'And verily We inspired Moses, saying: Take away My slaves by night and strike for them a dry path in the sea, fearing not to be overtaken, neither being afraid (of the sea).'),
  ('en.pickthall', 20, 78, 'Then Pharaoh followed them with his hosts and there covered them that which did cover them of the sea.'),
  ('en.pickthall', 20, 79, 'And Pharaoh led his folk astray, he did not guide them.'),
  ('en.pickthall', 20, 80, 'O Children of Israel! We delivered you from your enemy, and we made a covenant with you on the holy mountain\'s side, and sent down on you the manna and the quails,'),
  ('en.pickthall', 20, 81, '(Saying): Eat of the good things wherewith We have provided you, and transgress not in respect thereof lest My wrath come upon you: and he on whom My wrath cometh, he is lost indeed.'),
  ('en.pickthall', 20, 82, 'And lo! verily I am Forgiving toward him who repenteth and believeth and doeth good, and afterward walketh aright.'),
  ('en.pickthall', 20, 83, 'And (it was said): What hath made thee hasten from thy folk, O Moses?'),
  ('en.pickthall', 20, 84, 'He said: They are close upon my track. I hastened unto Thee, my Lord, that Thou mightest be well pleased.'),
  ('en.pickthall', 20, 85, 'He said: Lo! We have tried thy folk in thine absence, and As-Samiri hath misled them.'),
  ('en.pickthall', 20, 86, 'Then Moses went back unto his folk, angry and sad. He said: O my people! Hath not your Lord promised you a fair promise? Did the time appointed then appear too long for you, or did ye wish that wrath from your Lord should come upon you, that ye broke tryst with me?'),
  ('en.pickthall', 20, 87, 'They said: We broke not tryst with thee of our own will, but we were laden with burdens of ornaments of the folk, then cast them (in the fire), for thus As-Samiri proposed.'),
  ('en.pickthall', 20, 88, 'Then he produced for them a calf, of saffron hue, which gave forth a lowing sound. And they cried: This is your god and the god of Moses, but he hath forgotten.'),
  ('en.pickthall', 20, 89, 'See they not, then, that it returneth no saying unto them and possesseth for them neither hurt nor use?'),
  ('en.pickthall', 20, 90, 'And Aaron indeed had told them beforehand: O my people! Ye are but being seduced therewith, for lo! your Lord is the Beneficent, so follow me and obey my order.'),
  ('en.pickthall', 20, 91, 'They said: We shall by no means cease to be its votaries till Moses return unto us.'),
  ('en.pickthall', 20, 92, 'He (Moses) said: O Aaron! What held thee back when thou didst see them gone astray,'),
  ('en.pickthall', 20, 93, 'That thou followedst me not? Hast thou then disobeyed my order?'),
  ('en.pickthall', 20, 94, 'He said: O son of my mother! Clutch not my beard nor my head! I feared lest thou shouldst say: Thou hast caused division among the Children of Israel, and hast not waited for my word.'),
  ('en.pickthall', 20, 95, '(Moses) said: And what hast thou to say, O Samiri?'),
  ('en.pickthall', 20, 96, 'He said: I perceived what they perceive not, so I seized a handful from the footsteps of the messenger, and then threw it in. Thus my soul commended to me.'),
  ('en.pickthall', 20, 97, '(Moses) said: Then go! and lo! in this life it is for thee to say: Touch me not! and lo! there is for thee a tryst thou canst not break. Now look upon thy god of which thou hast remained a votary. Verily we will burn it and will scatter its dust over the sea.'),
  ('en.pickthall', 20, 98, 'Your Allah is only Allah, than Whom there is no other Allah. He embraceth all things in His knowledge.'),
  ('en.pickthall', 20, 99, 'Thus relate We unto thee (Muhammad) some tidings of that which happened of old, and We have given thee from Our presence a reminder.'),
  ('en.pickthall', 20, 100, 'Whoso turneth away from it, he verily will bear a burden on the Day of Resurrection,'),
  ('en.pickthall', 20, 101, 'Abiding under it - an evil burden for them on the Day of Resurrection,'),
  ('en.pickthall', 20, 102, 'The day when the Trumpet is blown. On that day we assemble the guilty white-eyed (with terror),'),
  ('en.pickthall', 20, 103, 'Murmuring among themselves: Ye have tarried but ten (days).'),
  ('en.pickthall', 20, 104, 'We are Best Aware of what they utter when their best in conduct say: Ye have tarried but a day.'),
  ('en.pickthall', 20, 105, 'They will ask thee of the mountains (on that day). Say: My Lord will break them into scattered dust.'),
  ('en.pickthall', 20, 106, 'And leave it as an empty plain,'),
  ('en.pickthall', 20, 107, 'Wherein thou seest neither curve nor ruggedness.'),
  ('en.pickthall', 20, 108, 'On that day they follow the summoner who deceiveth not, and voices are hushed for the Beneficent, and thou hearest but a faint murmur.'),
  ('en.pickthall', 20, 109, 'On that day no intercession availeth save (that of) him unto whom the Beneficent hath given leave and whose word He accepteth.'),
  ('en.pickthall', 20, 110, 'He knoweth (all) that is before them and (all) that is behind them, while they cannot compass it in knowledge.'),
  ('en.pickthall', 20, 111, 'And faces humble themselves before the Living, the Eternal. And he who beareth (a burden of) wrongdoing is indeed a failure (on that day).'),
  ('en.pickthall', 20, 112, 'And he who hath done some good works, being a believer, he feareth not injustice nor begrudging (of his wage).'),
  ('en.pickthall', 20, 113, 'Thus we have revealed it as a Lecture in Arabic, and have displayed therein certain threats, that peradventure they may keep from evil or that it may cause them to take heed.'),
  ('en.pickthall', 20, 114, 'Then exalted be Allah, the True King! And hasten not (O Muhammad) with the Qur\'an ere its revelation hath been perfected unto thee, and say: My Lord! Increase me in knowledge.'),
  ('en.pickthall', 20, 115, 'And verily We made a covenant of old with Adam, but he forgot, and We found no constancy in him.'),
  ('en.pickthall', 20, 116, 'And when We said unto the angels: Fall prostrate before Adam, they fell prostrate (all) save Iblis; he refused.'),
  ('en.pickthall', 20, 117, 'Therefor we said: O Adam! This is an enemy unto thee and unto thy wife, so let him not drive you both out of the Garden so that thou come to toil.'),
  ('en.pickthall', 20, 118, 'It is (vouchsafed) unto thee that thou hungerest not therein nor art naked,'),
  ('en.pickthall', 20, 119, 'And that thou thirstest not therein nor art exposed to the sun\'s heat.'),
  ('en.pickthall', 20, 120, 'But the devil whispered to him, saying: O Adam! Shall I show thee the tree of immortality and power that wasteth not away?'),
  ('en.pickthall', 20, 121, 'Then they twain ate thereof, so that their shame became apparent unto them, and they began to hide by heaping on themselves some of the leaves of the Garden. And Adam disobeyed his Lord, so went astray.'),
  ('en.pickthall', 20, 122, 'Then his Lord chose him, and relented toward him, and guided him.'),
  ('en.pickthall', 20, 123, 'He said: Go down hence, both of you, one of you a foe unto the other. But when there come unto you from Me a guidance, then whoso followeth My guidance, he will not go astray nor come to grief.'),
  ('en.pickthall', 20, 124, 'But he who turneth away from remembrance of Me, his will be a narrow life, and I shall bring him blind to the assembly on the Day of Resurrection.'),
  ('en.pickthall', 20, 125, 'He will say: My Lord! Wherefor hast Thou gathered me (hither) blind, when I was wont to see?'),
  ('en.pickthall', 20, 126, 'He will say: So (it must be). Our revelations came unto thee but thou didst forget them. In like manner thou art forgotten this Day.'),
  ('en.pickthall', 20, 127, 'Thus do We reward him who is prodigal and believeth not the revelations of his Lord; and verily the doom of the Hereafter will be sterner and more lasting.'),
  ('en.pickthall', 20, 128, 'Is it not a guidance for them (to know) how many a generation We destroyed before them, amid whose dwellings they walk? Lo! therein verily are signs for men of thought.'),
  ('en.pickthall', 20, 129, 'And but for a decree that had already gone forth from thy Lord, and a term already fixed, the judgment would have been inevitable (in this world).'),
  ('en.pickthall', 20, 130, 'Therefor (O Muhammad), bear with what they say, and celebrate the praise of thy Lord ere the rising of the sun and ere the going down thereof. And glorify Him some hours of the night and at the two ends of the day, that thou mayst find acceptance.'),
  ('en.pickthall', 20, 131, 'And strain not thine eyes toward that which We cause some wedded pairs among them to enjoy, the flower of the life of the world, that We may try them thereby. The provision of thy Lord is better and more lasting.'),
  ('en.pickthall', 20, 132, 'And enjoin upon thy people worship, and be constant therein. We ask not of thee a provision: We provided for thee. And the sequel is for righteousness.'),
  ('en.pickthall', 20, 133, 'And they say: If only he would bring us a miracle from his Lord! Hath there not come unto them the proof of what is in the former scriptures?'),
  ('en.pickthall', 20, 134, 'And if we had destroyed them with some punishment before it, they would assuredly have said: Our Lord! If only Thou hadst sent unto us a messenger, so that we might have followed Thy revelations before we were (thus) humbled and disgraced!'),
  ('en.pickthall', 20, 135, 'Say: Each is awaiting; so await ye! Ye will come to know who are the owners of the path of equity, and who is right.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 20, 1, 'Ta-Ha.'),
  ('en.yusufali', 20, 2, 'We have not sent down the Qur\'an to thee to be (an occasion) for thy distress,'),
  ('en.yusufali', 20, 3, 'But only as an admonition to those who fear (Allah),-'),
  ('en.yusufali', 20, 4, 'A revelation from Him Who created the earth and the heavens on high.'),
  ('en.yusufali', 20, 5, '(Allah) Most Gracious is firmly established on the throne (of authority).'),
  ('en.yusufali', 20, 6, 'To Him belongs what is in the heavens and on earth, and all between them, and all beneath the soil.'),
  ('en.yusufali', 20, 7, 'If thou pronounce the word aloud, (it is no matter): for verily He knoweth what is secret and what is yet more hidden.'),
  ('en.yusufali', 20, 8, 'Allah! there is no god but He! To Him belong the most Beautiful Names.'),
  ('en.yusufali', 20, 9, 'Has the story of Moses reached thee?'),
  ('en.yusufali', 20, 10, 'Behold, he saw a fire: So he said to his family, "Tarry ye; I perceive a fire; perhaps I can bring you some burning brand therefrom, or find some guidance at the fire."'),
  ('en.yusufali', 20, 11, 'But when he came to the fire, a voice was heard: "O Moses!'),
  ('en.yusufali', 20, 12, '"Verily I am thy Lord! therefore (in My presence) put off thy shoes: thou art in the sacred valley Tuwa.'),
  ('en.yusufali', 20, 13, '"I have chosen thee: listen, then, to the inspiration (sent to thee).'),
  ('en.yusufali', 20, 14, '"Verily, I am Allah: There is no god but I: So serve thou Me (only), and establish regular prayer for celebrating My praise.'),
  ('en.yusufali', 20, 15, '"Verily the Hour is coming - My design is to keep it hidden - for every soul to receive its reward by the measure of its Endeavour.'),
  ('en.yusufali', 20, 16, '"Therefore let not such as believe not therein but follow their own lusts, divert thee therefrom, lest thou perish!"..'),
  ('en.yusufali', 20, 17, '"And what is that in the right hand, O Moses?"'),
  ('en.yusufali', 20, 18, 'He said, "It is my rod: on it I lean; with it I beat down fodder for my flocks; and in it I find other uses."'),
  ('en.yusufali', 20, 19, '(Allah) said, "Throw it, O Moses!"'),
  ('en.yusufali', 20, 20, 'He threw it, and behold! It was a snake, active in motion.'),
  ('en.yusufali', 20, 21, '(Allah) said, "Seize it, and fear not: We shall return it at once to its former condition"..'),
  ('en.yusufali', 20, 22, '"Now draw thy hand close to thy side: It shall come forth white (and shining), without harm (or stain),- as another Sign,-'),
  ('en.yusufali', 20, 23, '"In order that We may show thee (two) of our Greater Signs.'),
  ('en.yusufali', 20, 24, '"Go thou to Pharaoh, for he has indeed transgressed all bounds."'),
  ('en.yusufali', 20, 25, '(Moses) said: "O my Lord! expand me my breast;'),
  ('en.yusufali', 20, 26, '"Ease my task for me;'),
  ('en.yusufali', 20, 27, '"And remove the impediment from my speech,'),
  ('en.yusufali', 20, 28, '"So they may understand what I say:'),
  ('en.yusufali', 20, 29, '"And give me a Minister from my family,'),
  ('en.yusufali', 20, 30, '"Aaron, my brother;'),
  ('en.yusufali', 20, 31, '"Add to my strength through him,'),
  ('en.yusufali', 20, 32, '"And make him share my task:'),
  ('en.yusufali', 20, 33, '"That we may celebrate Thy praise without stint,'),
  ('en.yusufali', 20, 34, '"And remember Thee without stint:'),
  ('en.yusufali', 20, 35, '"For Thou art He that (ever) regardeth us."'),
  ('en.yusufali', 20, 36, '(Allah) said: "Granted is thy prayer, O Moses!"'),
  ('en.yusufali', 20, 37, '"And indeed We conferred a favour on thee another time (before).'),
  ('en.yusufali', 20, 38, '"Behold! We sent to thy mother, by inspiration, the message:'),
  ('en.yusufali', 20, 39, '"\'Throw (the child) into the chest, and throw (the chest) into the river: the river will cast him up on the bank, and he will be taken up by one who is an enemy to Me and an enemy to him\': But I cast (the garment of) love over thee from Me: and (this) in order that thou mayest be reared under Mine eye.'),
  ('en.yusufali', 20, 40, '"Behold! thy sister goeth forth and saith, \'shall I show you one who will nurse and rear the (child)?\' So We brought thee back to thy mother, that her eye might be cooled and she should not grieve. Then thou didst slay a man, but We saved thee from trouble, and We tried thee in various ways. Then didst thou tarry a number of years with the people of Midian. Then didst thou come hither as ordained, O Moses!'),
  ('en.yusufali', 20, 41, '"And I have prepared thee for Myself (for service)"..'),
  ('en.yusufali', 20, 42, '"Go, thou and thy brother, with My Signs, and slacken not, either of you, in keeping Me in remembrance.'),
  ('en.yusufali', 20, 43, '"Go, both of you, to Pharaoh, for he has indeed transgressed all bounds;'),
  ('en.yusufali', 20, 44, '"But speak to him mildly; perchance he may take warning or fear (Allah)."'),
  ('en.yusufali', 20, 45, 'They (Moses and Aaron) said: "Our Lord! We fear lest he hasten with insolence against us, or lest he transgress all bounds."'),
  ('en.yusufali', 20, 46, 'He said: "Fear not: for I am with you: I hear and see (everything).'),
  ('en.yusufali', 20, 47, '"So go ye both to him, and say, \'Verily we are messengers sent by thy Lord: Send forth, therefore, the Children of Israel with us, and afflict them not: with a Sign, indeed, have we come from thy Lord! and peace to all who follow guidance!'),
  ('en.yusufali', 20, 48, '"\'Verily it has been revealed to us that the Penalty (awaits) those who reject and turn away.\'"'),
  ('en.yusufali', 20, 49, '(When this message was delivered), (Pharaoh) said: "Who, then, O Moses, is the Lord of you two?"'),
  ('en.yusufali', 20, 50, 'He said: "Our Lord is He Who gave to each (created) thing its form and nature, and further, gave (it) guidance."'),
  ('en.yusufali', 20, 51, '(Pharaoh) said: "What then is the condition of previous generations?"'),
  ('en.yusufali', 20, 52, 'He replied: "The knowledge of that is with my Lord, duly recorded: my Lord never errs, nor forgets,-'),
  ('en.yusufali', 20, 53, '"He Who has, made for you the earth like a carpet spread out; has enabled you to go about therein by roads (and channels); and has sent down water from the sky." With it have We produced diverse pairs of plants each separate from the others.'),
  ('en.yusufali', 20, 54, 'Eat (for yourselves) and pasture your cattle: verily, in this are Signs for men endued with understanding.'),
  ('en.yusufali', 20, 55, 'From the (earth) did We create you, and into it shall We return you, and from it shall We bring you out once again.'),
  ('en.yusufali', 20, 56, 'And We showed Pharaoh all Our Signs, but he did reject and refuse.'),
  ('en.yusufali', 20, 57, 'He said: "Hast thou come to drive us out of our land with thy magic, O Moses?'),
  ('en.yusufali', 20, 58, '"But we can surely produce magic to match thine! So make a tryst between us and thee, which we shall not fail to keep - neither we nor thou - in a place where both shall have even chances."'),
  ('en.yusufali', 20, 59, 'Moses said: "Your tryst is the Day of the Festival, and let the people be assembled when the sun is well up."'),
  ('en.yusufali', 20, 60, 'So Pharaoh withdrew: He concerted his plan, and then came (back).'),
  ('en.yusufali', 20, 61, 'Moses said to him: Woe to you! Forge not ye a lie against Allah, lest He destroy you (at once) utterly by chastisement: the forger must suffer frustration!"'),
  ('en.yusufali', 20, 62, 'So they disputed, one with another, over their affair, but they kept their talk secret.'),
  ('en.yusufali', 20, 63, 'They said: "These two are certainly (expert) magicians: their object is to drive you out from your land with their magic, and to do away with your most cherished institutions.'),
  ('en.yusufali', 20, 64, '"Therefore concert your plan, and then assemble in (serried) ranks: He wins (all along) today who gains the upper hand."'),
  ('en.yusufali', 20, 65, 'They said: "O Moses! whether wilt thou that thou throw (first) or that we be the first to throw?"'),
  ('en.yusufali', 20, 66, 'He said, "Nay, throw ye first!" Then behold their ropes and their rods-so it seemed to him on account of their magic - began to be in lively motion!'),
  ('en.yusufali', 20, 67, 'So Moses conceived in his mind a (sort of) fear.'),
  ('en.yusufali', 20, 68, 'We said: "Fear not! for thou hast indeed the upper hand:'),
  ('en.yusufali', 20, 69, '"Throw that which is in thy right hand: Quickly will it swallow up that which they have faked what they have faked is but a magician\'s trick: and the magician thrives not, (no matter) where he goes."'),
  ('en.yusufali', 20, 70, 'So the magicians were thrown down to prostration: they said, "We believe in the Lord of Aaron and Moses".'),
  ('en.yusufali', 20, 71, '(Pharaoh) said: "Believe ye in Him before I give you permission? Surely this must be your leader, who has taught you magic! be sure I will cut off your hands and feet on opposite sides, and I will have you crucified on trunks of palm-trees: so shall ye know for certain, which of us can give the more severe and the more lasting punishment!"'),
  ('en.yusufali', 20, 72, 'They said: "Never shall we regard thee as more than the Clear Signs that have come to us, or than Him Who created us! so decree whatever thou desirest to decree: for thou canst only decree (touching) the life of this world.'),
  ('en.yusufali', 20, 73, '"For us, we have believed in our Lord: may He forgive us our faults, and the magic to which thou didst compel us: for Allah is Best and Most Abiding."'),
  ('en.yusufali', 20, 74, 'Verily he who comes to his Lord as a sinner (at Judgment),- for him is Hell: therein shall he neither die nor live.'),
  ('en.yusufali', 20, 75, 'But such as come to Him as Believers who have worked righteous deeds,- for them are ranks exalted,-'),
  ('en.yusufali', 20, 76, 'Gardens of Eternity, beneath which flow rivers: they will dwell therein for aye: such is the reward of those who purify themselves (from evil).'),
  ('en.yusufali', 20, 77, 'We sent an inspiration to Moses: "Travel by night with My servants, and strike a dry path for them through the sea, without fear of being overtaken (by Pharaoh) and without (any other) fear."'),
  ('en.yusufali', 20, 78, 'Then Pharaoh pursued them with his forces, but the waters completely overwhelmed them and covered them up.'),
  ('en.yusufali', 20, 79, 'Pharaoh led his people astray instead of leading them aright.'),
  ('en.yusufali', 20, 80, 'O ye Children of Israel! We delivered you from your enemy, and We made a Covenant with you on the right side of Mount (Sinai), and We sent down to you Manna and quails:'),
  ('en.yusufali', 20, 81, '(Saying): "Eat of the good things We have provided for your sustenance, but commit no excess therein, lest My Wrath should justly descend on you: and those on whom descends My Wrath do perish indeed!'),
  ('en.yusufali', 20, 82, '"But, without doubt, I am (also) He that forgives again and again, to those who repent, believe, and do right, who,- in fine, are ready to receive true guidance."'),
  ('en.yusufali', 20, 83, '(When Moses was up on the Mount, Allah said:) "What made thee hasten in advance of thy people, O Moses?"'),
  ('en.yusufali', 20, 84, 'He replied: "Behold, they are close on my footsteps: I hastened to thee, O my Lord, to please thee."'),
  ('en.yusufali', 20, 85, '(Allah) said: "We have tested thy people in thy absence: the Samiri has led them astray."'),
  ('en.yusufali', 20, 86, 'So Moses returned to his people in a state of indignation and sorrow. He said: "O my people! did not your Lord make a handsome promise to you? Did then the promise seem to you long (in coming)? Or did ye desire that Wrath should descend from your Lord on you, and so ye broke your promise to me?"'),
  ('en.yusufali', 20, 87, 'They said: "We broke not the promise to thee, as far as lay in our power: but we were made to carry the weight of the ornaments of the (whole) people, and we threw them (into the fire), and that was what the Samiri suggested.'),
  ('en.yusufali', 20, 88, '"Then he brought out (of the fire) before the (people) the image of a calf: It seemed to low: so they said: This is your god, and the god of Moses, but (Moses) has forgotten!"'),
  ('en.yusufali', 20, 89, 'Could they not see that it could not return them a word (for answer), and that it had no power either to harm them or to do them good?'),
  ('en.yusufali', 20, 90, 'Aaron had already, before this said to them: "O my people! ye are being tested in this: for verily your Lord is (Allah) Most Gracious; so follow me and obey my command."'),
  ('en.yusufali', 20, 91, 'They had said: "We will not abandon this cult, but we will devote ourselves to it until Moses returns to us."'),
  ('en.yusufali', 20, 92, '(Moses) said: "O Aaron! what kept thee back, when thou sawest them going wrong,'),
  ('en.yusufali', 20, 93, '"From following me? Didst thou then disobey my order?"'),
  ('en.yusufali', 20, 94, '(Aaron) replied: "O son of my mother! Seize (me) not by my beard nor by (the hair of) my head! Truly I feared lest thou shouldst say, \'Thou has caused a division among the children of Israel, and thou didst not respect my word!\'"'),
  ('en.yusufali', 20, 95, '(Moses) said: "What then is thy case, O Samiri?"'),
  ('en.yusufali', 20, 96, 'He replied: "I saw what they saw not: so I took a handful (of dust) from the footprint of the Messenger, and threw it (into the calf): thus did my soul suggest to me."'),
  ('en.yusufali', 20, 97, '(Moses) said: "Get thee gone! but thy (punishment) in this life will be that thou wilt say, \'touch me not\'; and moreover (for a future penalty) thou hast a promise that will not fail: Now look at thy god, of whom thou hast become a devoted worshipper: We will certainly (melt) it in a blazing fire and scatter it broadcast in the sea!"'),
  ('en.yusufali', 20, 98, 'But the god of you all is the One Allah: there is no god but He: all things He comprehends in His knowledge.'),
  ('en.yusufali', 20, 99, 'Thus do We relate to thee some stories of what happened before: for We have sent thee a Message from Our own Presence.'),
  ('en.yusufali', 20, 100, 'If any do turn away therefrom, verily they will bear a burden on the Day of judgment;'),
  ('en.yusufali', 20, 101, 'They will abide in this (state): and grievous will the burden be to them on that Day,-'),
  ('en.yusufali', 20, 102, 'The Day when the Trumpet will be sounded: that Day, We shall gather the sinful, blear-eyed (with terror).'),
  ('en.yusufali', 20, 103, 'In whispers will they consult each other: "Yet tarried not longer than ten (Days);'),
  ('en.yusufali', 20, 104, 'We know best what they will say, when their leader most eminent in conduct will say: "Ye tarried not longer than a day!"'),
  ('en.yusufali', 20, 105, 'They ask thee concerning the Mountains: say, "My Lord will uproot them and scatter them as dust;'),
  ('en.yusufali', 20, 106, '"He will leave them as plains smooth and level;'),
  ('en.yusufali', 20, 107, '"Nothing crooked or curved wilt thou see in their place."'),
  ('en.yusufali', 20, 108, 'On that Day will they follow the Caller (straight): no crookedness (can they show) him: all sounds shall humble themselves in the Presence of (Allah) Most Gracious: nothing shalt thou hear but the tramp of their feet (as they march).'),
  ('en.yusufali', 20, 109, 'On that Day shall no intercession avail except for those for whom permission has been granted by (Allah) Most Gracious and whose word is acceptable to Him.'),
  ('en.yusufali', 20, 110, 'He knows what (appears to His creatures as) before or after or behind them: but they shall not compass it with their knowledge.'),
  ('en.yusufali', 20, 111, '(All) faces shall be humbled before (Him) - the Living, the Self-Subsisting, Eternal: hopeless indeed will be the man that carries iniquity (on his back).'),
  ('en.yusufali', 20, 112, 'But he who works deeds of righteousness, and has faith, will have no fear of harm nor of any curtailment (of what is his due).'),
  ('en.yusufali', 20, 113, 'Thus have We sent this down - an arabic Qur\'an - and explained therein in detail some of the warnings, in order that they may fear Allah, or that it may cause their remembrance (of Him).'),
  ('en.yusufali', 20, 114, 'High above all is Allah, the King, the Truth! Be not in haste with the Qur\'an before its revelation to thee is completed, but say, "O my Lord! advance me in knowledge."'),
  ('en.yusufali', 20, 115, 'We had already, beforehand, taken the covenant of Adam, but he forgot: and We found on his part no firm resolve.'),
  ('en.yusufali', 20, 116, 'When We said to the angels, "Prostrate yourselves to Adam", they prostrated themselves, but not Iblis: he refused.'),
  ('en.yusufali', 20, 117, 'Then We said: "O Adam! verily, this is an enemy to thee and thy wife: so let him not get you both out of the Garden, so that thou art landed in misery.'),
  ('en.yusufali', 20, 118, '"There is therein (enough provision) for thee not to go hungry nor to go naked,'),
  ('en.yusufali', 20, 119, '"Nor to suffer from thirst, nor from the sun\'s heat."'),
  ('en.yusufali', 20, 120, 'But Satan whispered evil to him: he said, "O Adam! shall I lead thee to the Tree of Eternity and to a kingdom that never decays?"'),
  ('en.yusufali', 20, 121, 'In the result, they both ate of the tree, and so their nakedness appeared to them: they began to sew together, for their covering, leaves from the Garden: thus did Adam disobey his Lord, and allow himself to be seduced.'),
  ('en.yusufali', 20, 122, 'But his Lord chose him (for His Grace): He turned to him, and gave him Guidance.'),
  ('en.yusufali', 20, 123, 'He said: "Get ye down, both of you,- all together, from the Garden, with enmity one to another: but if, as is sure, there comes to you Guidance from Me, whosoever follows My Guidance, will not lose his way, nor fall into misery.'),
  ('en.yusufali', 20, 124, '"But whosoever turns away from My Message, verily for him is a life narrowed down, and We shall raise him up blind on the Day of Judgment."'),
  ('en.yusufali', 20, 125, 'He will say: "O my Lord! why hast Thou raised me up blind, while I had sight (before)?"'),
  ('en.yusufali', 20, 126, '(Allah) will say: "Thus didst Thou, when Our Signs came unto thee, disregard them: so wilt thou, this day, be disregarded."'),
  ('en.yusufali', 20, 127, 'And thus do We recompense him who transgresses beyond bounds and believes not in the Signs of his Lord: and the Penalty of the Hereafter is far more grievous and more enduring.'),
  ('en.yusufali', 20, 128, 'Is it not a warning to such men (to call to mind) how many generations before them We destroyed, in whose haunts they (now) move? Verily, in this are Signs for men endued with understanding.'),
  ('en.yusufali', 20, 129, 'Had it not been for a Word that went forth before from thy Lord, (their punishment) must necessarily have come; but there is a Term appointed (for respite).'),
  ('en.yusufali', 20, 130, 'Therefore be patient with what they say, and celebrate (constantly) the praises of thy Lord, before the rising of the sun, and before its setting; yea, celebrate them for part of the hours of the night, and at the sides of the day: that thou mayest have (spiritual) joy.'),
  ('en.yusufali', 20, 131, 'Nor strain thine eyes in longing for the things We have given for enjoyment to parties of them, the splendour of the life of this world, through which We test them: but the provision of thy Lord is better and more enduring.'),
  ('en.yusufali', 20, 132, 'Enjoin prayer on thy people, and be constant therein. We ask thee not to provide sustenance: We provide it for thee. But the (fruit of) the Hereafter is for righteousness.'),
  ('en.yusufali', 20, 133, 'They say: "Why does he not bring us a sign from his Lord?" Has not a Clear Sign come to them of all that was in the former Books of revelation?'),
  ('en.yusufali', 20, 134, 'And if We had inflicted on them a penalty before this, they would have said: "Our Lord! If only Thou hadst sent us a messenger, we should certainly have followed Thy Signs before we were humbled and put to shame."'),
  ('en.yusufali', 20, 135, 'Say: "Each one (of us) is waiting: wait ye, therefore, and soon shall ye know who it is that is on the straight and even way, and who it is that has received Guidance."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 20, 1, 'Taa-Haa'),
  ('en.transliteration', 20, 2, 'Maaa anzalnaa \'alaikal Qur-aana litashqaaa'),
  ('en.transliteration', 20, 3, 'Illaa tazkiratal limany yakshaa'),
  ('en.transliteration', 20, 4, 'Tanzeelam mimman khalaqal arda was samaawaatil \'ulaa'),
  ('en.transliteration', 20, 5, 'Ar-Rahmaanu \'alal \'Arshis tawaa'),
  ('en.transliteration', 20, 6, 'Lahoo maa fis samaawaati wa maa fil ardi wa maa bainahumaa wa maa tahtassaraa'),
  ('en.transliteration', 20, 7, 'Wa in tajhar bilqawli fainnahoo ya\'lamus sirra wa akhfaa'),
  ('en.transliteration', 20, 8, 'Allaahu laaa ilasha illaa Huwa lahul Asmaaa\'ul Husnaa'),
  ('en.transliteration', 20, 9, 'Wa hal ataaka hadeesu Moosa'),
  ('en.transliteration', 20, 10, 'Iz ra aa naaran faqaala li alhlihim kusooo inneee aanastu naaral la\'alleee aateekum minhaa biqabasin aw ajidu \'alan naari hudaa'),
  ('en.transliteration', 20, 11, 'Falammaaa ataahaa noodiya yaa Moosaa'),
  ('en.transliteration', 20, 12, 'Inneee Ana Rabbuka fakhla\' na\'laika innaka bilwaadil muqaddasi Tuwaa'),
  ('en.transliteration', 20, 13, 'Wa anakhtartuka fastami\' limaa yoohaa'),
  ('en.transliteration', 20, 14, 'Innaneee Anal laahu laaa ilaaha illaa Ana fa\'budnee wa aqimis-salaata lizikree'),
  ('en.transliteration', 20, 15, 'Innas Saa\'ata aatiyatun akaadu ukhfeehaa litujzaa kullu nafsim bimaa tas\'aa'),
  ('en.transliteration', 20, 16, 'Falaa yasuddannnaka \'anhaa mal laa yu\'minu bihaa wattaba\'a hawaahu fatardaa'),
  ('en.transliteration', 20, 17, 'Wa maa tilka bi yamee nika yaa Moosaa'),
  ('en.transliteration', 20, 18, 'Qaala hiya \'asaaya atawakka\'u alaihaa wa ahushshu bihaa \'alaa ghanamee wa liya feehaa ma aaribu ukhraa'),
  ('en.transliteration', 20, 19, 'Qaala alqihaa yaa Moosaa'),
  ('en.transliteration', 20, 20, 'Fa-alqaahaa fa -izaa hiya haiyatun tas\'aa'),
  ('en.transliteration', 20, 21, 'Qaala khuzhaa wa laa ta khaf sanu\'eeduhaa seeratahal oolaa'),
  ('en.transliteration', 20, 22, 'Wadmum yadaka ilaa janaahika takhruj baidaaa\'a min ghairi sooo\'in Aayatan ukhraa'),
  ('en.transliteration', 20, 23, 'Linuriyaka min Aayaatinal Kubra'),
  ('en.transliteration', 20, 24, 'Izhab ilaa Fir\'awna innahoo taghaa'),
  ('en.transliteration', 20, 25, 'Qaala Rabbish rah lee sadree'),
  ('en.transliteration', 20, 26, 'Wa yassir leee amree'),
  ('en.transliteration', 20, 27, 'Wahlul \'uqdatam milli saanee'),
  ('en.transliteration', 20, 28, 'Yafqahoo qawlee'),
  ('en.transliteration', 20, 29, 'Waj\'al lee wazeeram min ahlee'),
  ('en.transliteration', 20, 30, 'Haaroona akhee'),
  ('en.transliteration', 20, 31, 'Ushdud biheee azree'),
  ('en.transliteration', 20, 32, 'Wa ashrik hu feee amree'),
  ('en.transliteration', 20, 33, 'Kai nusabbihaka kaseeraa'),
  ('en.transliteration', 20, 34, 'Wa nazkuraka kaseeraa'),
  ('en.transliteration', 20, 35, 'Innaka kunta binaa baseeraa'),
  ('en.transliteration', 20, 36, 'Qaala qad ooteeta su\'laka yaa Moosaa'),
  ('en.transliteration', 20, 37, 'Wa laqad manannaa \'alaika marratan ukhraaa'),
  ('en.transliteration', 20, 38, 'Iz awhainaaa ilaaa ummika maa yoohaaa'),
  ('en.transliteration', 20, 39, 'Aniqzifeehi fit Taabooti faqzifeehi fil yammi fal yul qihil yammu bis saahili yaakhuzhu \'aduwwul lee wa \'aduwwul lah; wa alqaitu \'alaika mahabbatam minnee wa litusna\'a \'alaa \'ainee'),
  ('en.transliteration', 20, 40, 'Iz tamsheee ukhtuka fataqoolu hal adullukum \'alaa mai yakfuluhoo faraja \'naaka ilaaa ummika kai taqarra \'ainuhaa wa laa tahzan; wa qatalta nafsan fanajjainaaka minal ghammi wa fatannaaka futoonaa; falabista sineena feee ahli Madyana summa ji\'ta \'alaa qadariny yaa Moosa'),
  ('en.transliteration', 20, 41, 'Wastana\' tuka linafsee'),
  ('en.transliteration', 20, 42, 'Izhab anta wa akhooka bi Aayaatee wa laa taniyaa fee zikree'),
  ('en.transliteration', 20, 43, 'Izhabaaa ilaa Fir\'awna innahoo taghaa'),
  ('en.transliteration', 20, 44, 'Faqoolaa lahoo qawlal laiyinal la allahoo yatazakkkaru \'aw yakhshaa'),
  ('en.transliteration', 20, 45, 'Qaalaa Rabbanaaa innanaa nakhaafu ai yafruta \'alainaaa aw ai yatghaa'),
  ('en.transliteration', 20, 46, 'Qaala laa takhaafaaa innanee ma\'akumaa asma\'u wa araa'),
  ('en.transliteration', 20, 47, 'Faatiyaahu faqoolaaa innaa Rasoolaa Rabbika fa arsil ma\'anaa Banee Israaa\'eela wa laa tu\'azzibhum qad ji\'naaka bi Aayatim mir Rabbika wassa laamu \'alaa manit taba\'al hudaa'),
  ('en.transliteration', 20, 48, 'Innaa qad oohiya ilainaaa annnal \'azaaba \'alaa man kaz zaba wa tawalla'),
  ('en.transliteration', 20, 49, 'Qaala famar Rabbu kumaa yaa Moosa'),
  ('en.transliteration', 20, 50, 'Qaala Rabbunal lazeee a\'taa kulla shai\'in khalqahoo summa hadaa'),
  ('en.transliteration', 20, 51, 'Qaala famaa baalul quroonil oolaa'),
  ('en.transliteration', 20, 52, 'Qaala \'ilmuhaa \'inda Rabee fee kitaab, laa yadillu Rabbee wa laa yansaa'),
  ('en.transliteration', 20, 53, 'Allazee ja\'ala lakumul arda mahdanw wa salaka lakum feehaa subulanw wa anzala minas samaaa\'i maaa\'an fa akhrajnaa biheee azwaajam min nabaatin shatta'),
  ('en.transliteration', 20, 54, 'Kuloo war\'aw an\'aamakum; inna fee zaalika la Aayaatil li ulin nuhaa'),
  ('en.transliteration', 20, 55, 'Minhaa khalaqnaakum wa feehaa nu\'eedukum wa minhaa nukhrijukum taaratan ukhraa'),
  ('en.transliteration', 20, 56, 'Wa laqad arainaahu Aayaatinaa kullahaa fakaz zaba wa abaa'),
  ('en.transliteration', 20, 57, 'Qaala aji\'tanaa litukhri janaa min ardinaa bisihrika yaa Moosa'),
  ('en.transliteration', 20, 58, 'Falanaatiyannaka bisihrim mislihee faj\'al bainanaa wa bainaka maw\'idal laa nukhlifuhoo nahnu wa laaa anta makaanan suwaa'),
  ('en.transliteration', 20, 59, 'Qaala maw\'idukum yawmuz zeenati wa ai yuhsharan naasu duhaa'),
  ('en.transliteration', 20, 60, 'Fatawallaa Fir\'awnu fajjama\'a kaidahoo summa ataa'),
  ('en.transliteration', 20, 61, 'Qaala lahum Moosaa wailakum laa taftaroo \'alal laahi kaziban fa yus hitakum bi \'azaab, wa qad khaaba manif taraa'),
  ('en.transliteration', 20, 62, 'Fatanaaza\'ooo amrahum bainahum wa asarrun najwaa'),
  ('en.transliteration', 20, 63, 'Qaalooo in haaazaani lasaahiraani yureedaani ai yukhrijaakum min ardikum bisihrihimaa wa yazhabaa bitareeqatikumul muslaa'),
  ('en.transliteration', 20, 64, 'Fa ajmi\'oo kaidakum summma\'too saffaa; wa qad aflahal yawma manis ta\'laa'),
  ('en.transliteration', 20, 65, 'Qaaloo yaa Moosaaa immaaa an tulqiya wa immaaa an nakoona awala man alqaa'),
  ('en.transliteration', 20, 66, 'Qaala bal alqoo fa izaa hibaaluhum wa \'isiyyuhum yuhaiyalu ilaihi min sihrihim annahaa tas\'aa'),
  ('en.transliteration', 20, 67, 'Fa awjasa fee nafsihee kheefatam Moosa'),
  ('en.transliteration', 20, 68, 'Qulnaa laa takhaf innaka antal a\'laa'),
  ('en.transliteration', 20, 69, 'Wa alqi maa fee yamee nika talqaf maa sana\'oo; innamaa sana\'oo kaidu saahir; wa laa yuflihus saahiru haisu ataa'),
  ('en.transliteration', 20, 70, 'Fa ulqiyas saharatu sujjadan qaalooo aamannaa bi Rabbi Haaroona wa Moosa'),
  ('en.transliteration', 20, 71, 'Qaala aamantum lahoo qabla an aazana lakum; innahoo lakabeerukumul lazee \'allama kumus sihra fala uqatti\'anna aidiyakum wa arjulakum min khilaafinw wa la usallibannakum fee juzoo\'in nakhli wa lata\'lamunna aiyunaaa ashaddu \'azaabanw wa abqaa'),
  ('en.transliteration', 20, 72, 'Qaaloo lan nu\'siraka \'alaa maa jaaa\'anaa minal baiyinaati wallazee fataranaa faqdi maaa anta qaad; innamaa taqdee haazihil hayaatad dunyaa'),
  ('en.transliteration', 20, 73, 'Innaaa aamannaa bi Rabbinaa liyaghfira lanaa khataayaanaa wa maaa akrahtanaa \'alaihi minas sihr; wallaahu khairunw waabqaa'),
  ('en.transliteration', 20, 74, 'Innahoo mai yaati Rabbahoo mujriman fa inna lahoo Jahannama laa yamotu feehaa wa laa yahyaa'),
  ('en.transliteration', 20, 75, 'Wa mai yaatihee mu\'minan qad \'amilas saalihaati fa ulaaa\'ika lahumud dara jaatul \'ulaa'),
  ('en.transliteration', 20, 76, 'Jannaatu \'Adnin tajree min tahtihal anhaaru khaalideena feehaa; wa zaalika jazaaa\'ua man tazakka'),
  ('en.transliteration', 20, 77, 'Wa laqad awhainaaa ilaa Moosaaa an asri bi\'ibaadee fadrib lahum tareeqan fil bahri yabasal laa takhaafu darakanw wa laa takhshaa'),
  ('en.transliteration', 20, 78, 'Fa atba\'ahum Fir\'awnu bijunoodihee faghashiyahum minal yammmi maa ghashi yahum'),
  ('en.transliteration', 20, 79, 'wa adalla fir\'awnu qawmahoo wa maa hadaa'),
  ('en.transliteration', 20, 80, 'Yaa Baneee Israaa\'eela qad anjainaakum min \'aduw wikum wa wa\'adnaakum jaanibat Tooril aimana wa nazzalnaa \'alaikumul Manna was Salwaa'),
  ('en.transliteration', 20, 81, 'Kuloo min taiyibaati maa razaqnaakum wa laa tatghaw feehi fa yahilla \'alaikum ghadabee wa mai yahlil \'alaihi ghadabee faqad hawaa'),
  ('en.transliteration', 20, 82, 'Wa innee la Ghaffaarul liman taaba wa aamana wa \'amila saalihan summah tadaa'),
  ('en.transliteration', 20, 83, 'Wa maaa a\'jalaka \'an qawmika yaa Moosa'),
  ('en.transliteration', 20, 84, 'Qaala hum ulaaa\'i \'alaaa asaree wa \'ajiltu ilaika Rabbi litardaa'),
  ('en.transliteration', 20, 85, 'Qaala fa innaa qad fatannaa qawmaka mim ba\'dika wa adallahumus Saamiriyy'),
  ('en.transliteration', 20, 86, 'Faraja\'s Moosaaa ilaa qawmihee ghadbaana asifaa; qaala yaa qawmi alam ya\'idkum Rabbukum wa\'dan hasanaa; afataala \'alaikumul \'ahdu am arattum ai yahilla \'alaikum ghadabum mir Rabbikum fa akhlaftum maw\'idee'),
  ('en.transliteration', 20, 87, 'Qaaloo maaa akhlafnaa maw\'idaka bimalkinna wa laakinna hummilnaaa awzaaram min zeenatil qawmi faqazafnaahaa fakazaalika alqas Saamiriyy'),
  ('en.transliteration', 20, 88, 'Fa akhraja lahum \'ijlan jasadal lahoo khuwaarun faqaaloo haazaaa ilaahukum wa ilaahu Moosaa fanasee'),
  ('en.transliteration', 20, 89, 'Afalaa yarawna allaa yarji\'u ilaihim qawlanw wa laa yamliku lahum darranw wa laa naf\'aa'),
  ('en.transliteration', 20, 90, 'Wa laqad qaala lahum Haaroonu min qablu yaa qawmi innamaa futintum bihee wa inna Rabbakumur Rahmaanu fattabi\'oonee wa atee\'ooo amree'),
  ('en.transliteration', 20, 91, 'Qaaloo lan nabraha \'alaihi \'aakifeena hattaa yarji\'a ilainaa Moosaa'),
  ('en.transliteration', 20, 92, 'Qaala Yaa Haaroonu maa mana \'aka iz ra aitahum dallooo'),
  ('en.transliteration', 20, 93, 'Allaa tattabi\'ani afa\'asaita amree'),
  ('en.transliteration', 20, 94, 'Qaala yabna\'umma laa taakhuz bilihyatee wa laa biraasee innee khashetu an taqoola farraqta baina Baneee Israaa\'eela wa lam tarqub qawlee'),
  ('en.transliteration', 20, 95, 'Qaala famaa khatbuka yaa Saamiriyy'),
  ('en.transliteration', 20, 96, 'Qaala basurtu bimaa lam yabsuroo bihee faqabadtu qabdatam min asarir Rasooli fanabaztuhaa wa kazaalika sawwalat lee nafsee'),
  ('en.transliteration', 20, 97, 'Qaala fazhab fa inna laka fil hayaati an taqoola laa misaasa wa inna laka maw\'idal lan tukhlafahoo wanzur ilaaa ilaahikal lazee zalta \'alaihi \'aakifaa; lanuharriqannnahoo summa lanansifanahoo fil yammi nasfaa'),
  ('en.transliteration', 20, 98, 'Innamaaa ilaahukkumul laahul lazee laa ilaaha illaa Hoo; wasi\'a kulla shai\'in ilmaa'),
  ('en.transliteration', 20, 99, 'Kazaalika naqussu \'alaika min ambaaa\'i maa qad sabaq; wa qad aatainaaka mil ladunnaa Zikraa'),
  ('en.transliteration', 20, 100, 'Man a\'rada \'anhu, fa innahoo yahmilu Yawmal Qiyaamati wizraa'),
  ('en.transliteration', 20, 101, 'Khaalideena feehi wa saaa\'a lahum Yawmal Qiyaamati himlaa'),
  ('en.transliteration', 20, 102, 'Yawma yunfakhu fissoori wa nahshurul mujrimeena Yawma \'izin zurqaa'),
  ('en.transliteration', 20, 103, 'Yatakhaafatoona bainahum il labistum illaa \'ashraa'),
  ('en.transliteration', 20, 104, 'nahnu a\'lamu bimaa yaqooloona iz yaqoolu amsaluhum tareeqatan illabistum illaa yawmaa'),
  ('en.transliteration', 20, 105, 'Wa yas\'aloonaka \'anil jibaali faqul yansifuhaa Rabbee nasfaa'),
  ('en.transliteration', 20, 106, 'Fa yazaruhaa qaa\'an safsafaa'),
  ('en.transliteration', 20, 107, 'Laa taraa feehaa \'iwajanw wa laaa amtaa'),
  ('en.transliteration', 20, 108, 'Yawma iziny yattabi\'oonad daa\'iya laa \'iwaja lahoo wa khasha\'atil aswaatu lir Rahmaani falaa tasma\'u illaa hamsaa'),
  ('en.transliteration', 20, 109, 'Yawma \'izil laa tanfa\'ush shafaa\'atu illaa man azina lahur Rahmaanu wa radiya lahoo qawlaa'),
  ('en.transliteration', 20, 110, 'Ya\'lamu maa bainaa aideehim wa maa khalfahum wa laa yauheetoona bihee \'ilmaa'),
  ('en.transliteration', 20, 111, 'Wa \'anatil wujoohu lil Haiiyil Qaiyoomi wa qad khaaba man hamala zulmaa'),
  ('en.transliteration', 20, 112, 'Wa mai ya\'mal minas saalihaati wa huwa mu\'minun falaa yakhaafu zulmanw wa laa hadmaa'),
  ('en.transliteration', 20, 113, 'Wa kazaalika anzalnaahu Qur-aanan \'Arabiyyanw wa sarrafnaa fee hi minal wa\'eedi la\'allahum yattaqoona aw yuhdisu lahum zikraa'),
  ('en.transliteration', 20, 114, 'Fata\'aalal laahul Malikul Haqq; wa laa ta\'jal bil Quraani min qabli ai yuqdaaa ilaika wahyuhoo wa qur Rabbi zidnee \'ilmaa'),
  ('en.transliteration', 20, 115, 'Wa laqad \'ahidnaaa ilaaa Aadama min qablu fanasiya wa lam najid lahoo \'azmaa'),
  ('en.transliteration', 20, 116, 'Wa iz qulnaa lilma laaa\'ikatis judoo li Aadama fasajadooo illaaa Iblees; abaa'),
  ('en.transliteration', 20, 117, 'Faqulnaa yaaa Aadamu inna haazaa \'aduwwul laka wa lizawjika falaa yukhrijan nakumaa minal Jannati fatashqaa'),
  ('en.transliteration', 20, 118, 'Innaa laka allaa tajoo\'a feeha wa laa ta\'raa'),
  ('en.transliteration', 20, 119, 'Wa annaka laa tazma\'u feehaa wa laa tadhaa'),
  ('en.transliteration', 20, 120, 'Fa waswasa ilaihish Shaitaanu qaala yaaa Aadamu hal adulluka \'alaa shajaratil khuldi wa mulkil laa yablaa'),
  ('en.transliteration', 20, 121, 'Fa akalaa minhaa fabadat lahumaa saw aatuhumaa wa tafiqaa yakhsifaani \'alaihimaa minw waraqil jannah; wa \'asaaa Aadamu Rabbahoo faghawaa'),
  ('en.transliteration', 20, 122, 'Summaj tabbahu Rabbuhoo fataaba \'alaihi wa hadaa'),
  ('en.transliteration', 20, 123, 'Qaalah bita minhaa jamee\'am ba\'dukum liba\'din \'aduww; fa immaa yaati yannakum minnee hudan famanit taba\'a hudaaya falaa yadillu wa laa yashhqaa'),
  ('en.transliteration', 20, 124, 'Wa man a\'rada \'an Zikree fa inna lahoo ma\'eeshatan dankanw wa nahshuruhoo Yawmal Qiyaamati a\'maa'),
  ('en.transliteration', 20, 125, 'Qaala Rabbi lima hashar tanee a\'maa wa qad kuntu baseeraa'),
  ('en.transliteration', 20, 126, 'Qaala kazaalika atatka Aayaatunaa fanaseetahaa wa kazaalikal Yawma tunsaa'),
  ('en.transliteration', 20, 127, 'Wa kazaalika najzee man asrafa wa lam yu\'mim bi Aayaati Rabbih; wa la\'azaabul Aakhirati ashaddu wa abqaa'),
  ('en.transliteration', 20, 128, 'Afalam yahdi lahum kam ahlaknaa qablahum minal qurooni yamshoona fee masaakinihim; inna fee zaalika la Aayaatil li ulinnuhaa'),
  ('en.transliteration', 20, 129, 'Wa law laa Kalimatun sabaqat mir Rabbika lakaana lizaamanw wa ajalum musammaa'),
  ('en.transliteration', 20, 130, 'Fasbir \'alaa maa yaqooloona wa sabbih bihamdi Rabbika qabla tuloo\'ish shamsi wa qabla ghuroobihaa wa min aanaaa\'il laili fasbbih wa atraafan nahaari la \'allaka tardaa'),
  ('en.transliteration', 20, 131, 'Wa laa tamuddanna \'ainaika ilaa ma matta\'na biheee azwajam minhum zahratal hayaatid dunya linaftinahum feeh; wa rizqu Rabbika khairunw wa abqaa'),
  ('en.transliteration', 20, 132, 'Waamur ahlaka bis Salaati wastabir \'alaihaa la nas\'aluka rizqaa; nahnu narzuquk; wal \'aaqibatu littaqwaa'),
  ('en.transliteration', 20, 133, 'Wa qaaloo law laa yaateenaa bi Aayatim mmir Rabbih; awalam taatihim baiyinatu maa fis suhufil oolaa'),
  ('en.transliteration', 20, 134, 'Wa law annaaa ahlaknaahum bi\'azaabim min qablihee laqaaloo Rabbanaa law laaa arsalta ilainaa Rasoolan fanattabi\'s Aayaatika min qabli an nazilla wa nakhzaa'),
  ('en.transliteration', 20, 135, 'Qul kullum mutarabbisun fatarabbasoo fasta\'lamoona man Ashaabus Siraatis Sawiyyi wa manih tadaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 20, 1, 'طہۤ'),
  ('ur.ahmedali', 20, 2, 'ہم نے تم پر قرآن اس لیے نازل نہیں کیا کہ تم تکلیف اٹھاؤ'),
  ('ur.ahmedali', 20, 3, 'بلکہ اس شخص کے لیے نصیحت ہےجو ڈرتا ہے'),
  ('ur.ahmedali', 20, 4, 'اس کی طرف سے نازل ہوا ہے جس نے زمین اور بلند آسمانوں کو پیدا کیا'),
  ('ur.ahmedali', 20, 5, 'رحمان جو عرش پر جلوہ گر ہے'),
  ('ur.ahmedali', 20, 6, 'اسی کا ہے جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اور جوکچھ گیلی زمین کے نیچے ہے'),
  ('ur.ahmedali', 20, 7, 'اور اگرتو پکار کر بات کہے تو وہ پوشیدہ اور اس سے بھی زیادہ پوشیدہ کو جانتا ہے'),
  ('ur.ahmedali', 20, 8, 'الله ہے جس کے سوا کوئی معبود نہیں اس کے سب نام اچھے ہیں'),
  ('ur.ahmedali', 20, 9, 'اور کیا تجھے موسیٰ کی بات پہنچی ہے'),
  ('ur.ahmedali', 20, 10, 'جب اس نے آگ دیکھی تو اپنے گھر والوں سے کہا کہ ٹھہرو میں نے آگ دیکھی ہے شاید کہ میں اس سے تمہارے پاس کوئی چنگاری لاؤں یا وہاں کوئی رہبر پاؤں'),
  ('ur.ahmedali', 20, 11, 'پھر جب وہ اس کے پاس آئے تو آواز آئی کہ اے موسیٰ'),
  ('ur.ahmedali', 20, 12, 'میں تمہارا رب ہوں سو تم اپنی جوتیاں اتار دو بے شک تم پاک وادی طویٰ میں ہو'),
  ('ur.ahmedali', 20, 13, 'اور میں نے تجھے پسند کیا ہے جو کچھ وحی کی جارہی ہےاسے سن لو'),
  ('ur.ahmedali', 20, 14, 'بے شک میں ہی الله ہوں میرے سوا کوئی معبود نہیں پس میری ہی بندگی کر اور میری ہی یاد کے لیے نماز پڑھا کر'),
  ('ur.ahmedali', 20, 15, 'بے شک قیامت آنے والی ہے میں اسے پوشیدہ رکھنا چاہتا ہوں تاکہ ہر شخص کو اس کے کیے کا بدلہ مل جائے'),
  ('ur.ahmedali', 20, 16, 'سو تمہیں قیامت سے ایسا شخص باز نہ رکھنے پائے جو اس پر ایمان نہیں رکھتا اوراپنی خواہشوں پر چلتا ہے پھر تم تباہ ہوجاؤ'),
  ('ur.ahmedali', 20, 17, 'اور اے موسیٰ تیرے دائیں ہاتھ میں کیا ہے'),
  ('ur.ahmedali', 20, 18, 'کہا یہ میری لاٹھی ہے ا س پر ٹیک لگاتا ہوں اور اس سے اپنی بکریوں پر پتے جھاڑتا ہوں اور اس میں میرے لیے اور بھی فائدے ہیں'),
  ('ur.ahmedali', 20, 19, 'فرمایا اے موسیٰ اسے ڈال دو'),
  ('ur.ahmedali', 20, 20, 'پھر اسے ڈال دیا تو اسی وقت وہ دوڑتا ہوا سانپ ہو گیا'),
  ('ur.ahmedali', 20, 21, 'فرمایا اسے پکڑ لے اور نہ ڈر ہم ابھی اسےپہلی حالت پر پھیر دیں گے'),
  ('ur.ahmedali', 20, 22, 'اور اپنا ہاتھ اپنی بغل سے ملا دے بلا عیب سفید ہو کر نکلے گا یہ دوسری نشانی ہے'),
  ('ur.ahmedali', 20, 23, 'تاکہ ہم تجھے اپنی بڑی نشانیوں میں سے بعض دکھائیں'),
  ('ur.ahmedali', 20, 24, 'فرعون کے پاس جا بے شک وہ سرکش ہو گیا ہے'),
  ('ur.ahmedali', 20, 25, 'کہا اے میرے رب میرا سینہ کھول دے'),
  ('ur.ahmedali', 20, 26, 'اورمیرا کام آسان کر'),
  ('ur.ahmedali', 20, 27, 'اور میری زبان سے گرہ کھول دے'),
  ('ur.ahmedali', 20, 28, 'کہ میری بات سمجھ لیں'),
  ('ur.ahmedali', 20, 29, 'اور میرے لیے میرے کنبے میں سے ایک معاون بنا دے'),
  ('ur.ahmedali', 20, 30, 'ہارون کو جو میرا بھائی ہے'),
  ('ur.ahmedali', 20, 31, 'ا س سے میری کمر مضبوط کر دے'),
  ('ur.ahmedali', 20, 32, 'اور اسے میرے کام میں شریک کر دے'),
  ('ur.ahmedali', 20, 33, 'تاکہ ہم تیری پاک ذات کا بہت بیان کریں'),
  ('ur.ahmedali', 20, 34, 'اور تجھے بہت یاد کریں'),
  ('ur.ahmedali', 20, 35, 'بے شک تو ہمیں خوب دیکھتا ہے'),
  ('ur.ahmedali', 20, 36, 'فرمایا اے موسیٰ تیری درخواست منظور ہے'),
  ('ur.ahmedali', 20, 37, 'اورالبتہ تحقیق ہم نے تجھ پر ایک دفعہ اور بھی احسان کیا ہے'),
  ('ur.ahmedali', 20, 38, 'جب ہم نے تیری ماں کے دل میں بات ڈال دی تھی'),
  ('ur.ahmedali', 20, 39, 'کہ اسے صندوق میں ڈال دے پھر اسے دریا میں ڈال دے پر اسے دریا کنارے پر ڈال دے گا اسے میرا دشمن اور اس کا دشمن اٹھا لے گا اور میں نے تجھ پر اپنی طرف سے محبت ڈال دی اور تاکہ تو میرے سامنے پرورش پائے'),
  ('ur.ahmedali', 20, 40, 'جب تیری بہن کہتی جا رہی تھی کیا تمہیں ایسی عورت بتاؤں جو اسے اچھی طرح پالے پھر ہم نے تجھے تیری ماں کے پاس پہنچا دیا کہ اس کی آنکھ ٹھنڈی ہو اور غم نہ کھائے اور تو نے ایک شخص کو مار ڈالا پھر ہم نے تجھے اس غم سے نکالا اور ہم نے تجھے کئی مرتبہ آزمائش میں ڈالا پھر تو مدین والوں میں کئی برس رہا پھر تو اے موسیٰ تقدیر سے یہاں آیا'),
  ('ur.ahmedali', 20, 41, 'اور میں نے تجھے خاص اپنے واسطے بنایا'),
  ('ur.ahmedali', 20, 42, 'تو اور تیرا بھائی میری نشانیاں لے کر جاؤ اور میری یاد میں کوتاہی نہ کرو'),
  ('ur.ahmedali', 20, 43, 'فرعون کے پاس جاؤ بے شک وہ سرکش ہو گیا ہے'),
  ('ur.ahmedali', 20, 44, 'سو اس سے نرمی سے بات کرو شاید وہ نصیحت حاصل کرے یا ڈر جائے'),
  ('ur.ahmedali', 20, 45, 'کہا اے ہمارے رب ہمیں ڈر ہے کہ وہ ہم پر زیادتی کرے یا یہ کہ زیادہ سرکشی کرے'),
  ('ur.ahmedali', 20, 46, 'فرمایا ڈرو مت میں تمہارے ساتھ سنتا اور دیکھتا ہوں'),
  ('ur.ahmedali', 20, 47, 'سو تم دونوں اس کے پاس جاؤ اورکہو کہ بے شک ہم تیرے رب کی طرف سے پیغام لے کر آئے ہیں کہ بنی اسرائیل کو ہمارے ساتھ بھیج دے اور انہیں تکلیف نہ دے ہم تیرے پاس تیرے رب کی طرف سے نشانی لے کر آئے ہیں اور سلامتی اس کے لیے ہے جو سیدھی راہ پر چلے'),
  ('ur.ahmedali', 20, 48, 'بے شک ہمیں وحی سے بتایا گیا ہے کہ عذاب اسی پر ہوگا جو جھٹلائے اور منہ پھیر لے'),
  ('ur.ahmedali', 20, 49, 'کہا اے موسیٰ پھر تمہارا رب کون ہے'),
  ('ur.ahmedali', 20, 50, 'کہا ہمارا رب وہ ہے جس نے ہر چیز کو اس کی صورت عطا کی پھر راہ دکھائی'),
  ('ur.ahmedali', 20, 51, 'کہا پھر پہلی جماعتوں کا کیا حال ہے'),
  ('ur.ahmedali', 20, 52, 'کہا ان کا علم میرے رب کے ہاں کتاب میں ہے میرا رب نہ غلطی کرتا ہے اور نہ بھولتا ہے'),
  ('ur.ahmedali', 20, 53, 'جس نے تمہارے لیے زمین کو بچھونا بنایا اور تمہارے لیے اس میں راستے بنائے اور آسمان سے پانی نازل کیا پھر ہم نے اس میں طرح طرح کی مختلف سبزیاں نکالیں'),
  ('ur.ahmedali', 20, 54, 'کھاؤ اور اپنے مویشیوں کو چراؤ بے شک اس میں عقل والوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 20, 55, 'اسی زمین سے ہم نے تمہیں بنایا اور اسی میں لوٹائیں گے اور دوبارہ اسی سے نکالیں گے'),
  ('ur.ahmedali', 20, 56, 'اورہم نے فرعون کو اپنی سب نشانیاں دکھا دیں پھر اس نے جھٹلایا اورانکار کیا'),
  ('ur.ahmedali', 20, 57, 'کہا اے موسیٰ کیا تو ہمیں اپنے جادو سے ہمارے ملک سے نکالنے کے لیے آیا ہے'),
  ('ur.ahmedali', 20, 58, 'سو ہم بھی تیرے مقابلے میں ایک ایسا ہی جادو لائیں گے سوہمارے او راپنے درمیان ایک وعدہ مقرر کر دے نہ ہم اس کے خلاف کریں اورنہ تو کسی صاف میدان میں'),
  ('ur.ahmedali', 20, 59, 'کہا تمہارا وعدہ جشن کا دن ہے اور دن چڑھے لوگ اکھٹے کیے جائیں'),
  ('ur.ahmedali', 20, 60, 'پھر فرعون لوٹ گیا اور اپنے مکر کا سامان جمع کیا پھر آیا'),
  ('ur.ahmedali', 20, 61, 'موسیٰ نے کہا افسوس تم الله پر بہتان نہ باندھو ورنہ وہ کسی عذاب سے تمہیں ہلاک کر دے گا اوربے شک جس نے جھوٹ بنایا وہ غارت ہوا'),
  ('ur.ahmedali', 20, 62, 'پھر ان کا آپس میں اختلاف ہو گیا اور خفیہ گفتگو کرتے رہے'),
  ('ur.ahmedali', 20, 63, 'کہا بے شک یہ دونوں جادوگر ہیں چاہتے ہیں کہ اپنے جادو کے زور سے تمہیں تمہارے ملک سے نکال دیں اور تمہارے عمدہ طریقہ کو موقوف کر دیں'),
  ('ur.ahmedali', 20, 64, 'پھر تم اپنی تدبیر جمع کر کے صف باندھ کر آؤ اور تحقیق آج جیت گیا جو غالب رہا'),
  ('ur.ahmedali', 20, 65, 'کہا اے موسیٰ یا تو ڈال اوریا ہم پہلے ڈالنے والے ہوں'),
  ('ur.ahmedali', 20, 66, 'کہا بلکہ تم ڈالو پس اچانک ان کی رسیاں او رلاٹھیاں ان کے جادو سے اس کے خیال میں دوڑ رہی ہیں'),
  ('ur.ahmedali', 20, 67, 'پھر موسیٰ نے اپنے دل میں ڈر محسوس کیا'),
  ('ur.ahmedali', 20, 68, 'ہم نے کہا ڈرو مت بیشک تو ہی غالب ہوگا'),
  ('ur.ahmedali', 20, 69, 'او رجو تیرے دائیں ہاتھ میں ہے ڈال دے کہ نگل جائے جو کچھ انہوں نے بنایا ہےجو کچھ کہ انہوں نے بنایا ہے صرف جادوگر کا فریب ہے اورجادوگر کا بھلا نہیں ہوتا جہاں بھی ہو'),
  ('ur.ahmedali', 20, 70, 'پھر جادوگر سجدہ میں گر پڑے کہا ہم ہارون اورموسیٰ کے رب پر ایمان لائے'),
  ('ur.ahmedali', 20, 71, 'کہا تم میری اجازت سے پہلےہی اس پر ایمان لے آئے بے شک یہ تمہارا سردار ہے جس نے تمہیں جادو سکھایا سو اب میں تمہارے ہاتھ اور دوسری طرف کے پاؤں کٹواؤں گا اورتمہیں کھجور کے تنوں پر سولی دوں گا اورتمہیں معلوم ہوجائے گا ہم میں سے کس کا عذاب سخت اور دیر تک رہنے والا ہے'),
  ('ur.ahmedali', 20, 72, 'کہا ہم تجھے ہرگزترجیح نہ دیں گے ان کھلی ہوئی نشانیوں کے مقابلہ میں جو ہمارے پاس آ چکی ہیں اورنہ اس کے مقابلہ میں جس نے ہمیں پیدا کیا ہے سو تو کر گزر جو تجھے کرنا ہے تو صرف اس دنیا کی زندگی پر حکم چلا سکتا ہے'),
  ('ur.ahmedali', 20, 73, 'بے شک ہم اپنے رب پر ایمان لائے ہیں تاکہ ہمارے گناہ معاف کرے اور جو تو نے ہم سے زبردستی جادو کرایا اور الله بہتر اور سدا باقی رہنے والا ہے'),
  ('ur.ahmedali', 20, 74, 'بے شک جو شخص اپنے رب کے پا س مجرم ہو کر آئے گا سواس کے لیے دوزخ ہے جس میں نہ مرے گا اور نہ جیے گا'),
  ('ur.ahmedali', 20, 75, 'اورجو اس کے پاس مومن ہوکر آئے گا حالانکہ اس نے اچھے کام بھی کیے ہوں تو ان کے لیے بلند مرتبے ہوں گے'),
  ('ur.ahmedali', 20, 76, 'ہمیشہ رہنے کے باغ جن کے نیچے نہریں بہتی ہوں گی وہ ان میں ہمیشہ رہیں گے اور یہ اس کی جزا ہے جو گناہ سے پاک ہوا'),
  ('ur.ahmedali', 20, 77, 'او رہم نے البتہ موسیٰ کو وحی کی کہ میرے بندوں کو راتوں رات لے جا پھر ان کے لیے دریامیں خشک راستہ بنا دے پکڑے جانے سے نہ ڈر اور نہ کسی خطرہ کا خوف کھا'),
  ('ur.ahmedali', 20, 78, 'پھر فرعون نے اپنے لشکر کو لے کر ان کا پیچھا کیا پھر انہیں دریا نےڈھانپ لیا جیسا ڈھانپا'),
  ('ur.ahmedali', 20, 79, 'اور فرعون نے اپنی قوم کو بہکایا اور راہ پر نہ لایا'),
  ('ur.ahmedali', 20, 80, 'اے بنی اسرائیل ہم نے تمہیں تمہارے دشمن سے نجات دی اور تم سے طور کی دائیں طرف کا وعدہ کیا اور تم پر من و سلویٰ اتارا'),
  ('ur.ahmedali', 20, 81, 'کھاؤ جو ستھری چیزیں ہم نے تمہیں دی ہیں اور اس میں حد سے نہ گزرو پھر تم پر میرا غضب نازل ہو گا اور جس پرمیرا غضب نازل ہوا سو وہ گڑھے میں جا گرا'),
  ('ur.ahmedali', 20, 82, 'اور بے شک میں بڑا بخشنے والا ہوں اس کو جو توبہ کرے اور ایمان لائے اور اچھے کام کرے پھر ہدایت پر قائم رہے'),
  ('ur.ahmedali', 20, 83, 'اور اے موسیٰ تجھے اپنی قوم سے پہلے جلدی آنے کا کیا سبب ہوا'),
  ('ur.ahmedali', 20, 84, 'کہا وہ بھی میرے پیچھے یہ آ رہے ہیں اور اے میرے رب میں جلدی تیرے طرف آیا تاکہ تو خوش ہو'),
  ('ur.ahmedali', 20, 85, 'فرمایا تیری قوم کو تیرے بعد ہم نے آزمائش میں ڈال دیاہےاور انہیں سامری نے گمراہ کر دیا ہے'),
  ('ur.ahmedali', 20, 86, 'پھر موسیٰ اپنی قوم کی طرف غصہ میں بھرے ہوئے افسوس کرتے ہوئے لوٹے کہا اے میری قوم کیا تمہارے رب نے تم سے اچھا وعدہ نہیں کیا تھا پھر کیا تم پر بہت زمانہ گزر گیا تھا یا تم نے چاہا کہ تم پر تمہارے رب کا غصہ نازل ہو تب تم نے مجھ سے وعدہ خلافی کی'),
  ('ur.ahmedali', 20, 87, 'کہا ہم نےاپنے اختیا ر سے آپ سے وعدہ خلافی نہیں کی لیکن ہم سے اس قوم کے زیور کا بوجھ اٹھوایا گیا تھا سو ہم نے اسے ڈال دیا پھر اسی طرح سامری نے ڈال دیا'),
  ('ur.ahmedali', 20, 88, 'پھر ان کے لیے ایک بچھڑا نکال لایا ایک جسم جس میں گائے کی آواز تھی پھر کہا یہ تمہارا اور موسیٰ کا معبود ہے سو وہ بھول گیا ہے'),
  ('ur.ahmedali', 20, 89, 'کیا پس وہ نہیں دیکھتے کہ وہ انہیں کس بات کا جواب نہیں دیتا اور ان کے نقصان اور نفع کا بھی اسے اختیار نہیں'),
  ('ur.ahmedali', 20, 90, 'اور انہیں ہارون نے اس سے پہلے کہہ دیا تھا اے میری قوم اس سے تمہاری آزمائش کی گئی ہے اور بے شک تمہارا رب رحمان ہے سو میری پیروی کرو اور میرا کہا مانو'),
  ('ur.ahmedali', 20, 91, 'کہا ہم برابر اسی پر جمے بیٹھے رہیں گے یہاں تک کہ موسیٰ ہمارے پاس لوٹ کر آئے'),
  ('ur.ahmedali', 20, 92, 'کہا اے ہارون تمہیں کس چیز نے روکا جب تم نے دیکھا تھا کہ وہ گمراہ ہو گئے ہیں'),
  ('ur.ahmedali', 20, 93, 'تو میرے پیچھے نہ آیا کیا تو نے بھی میری حکم عدولی کی'),
  ('ur.ahmedali', 20, 94, 'کہا اے میری ماں کے بیٹے میری داڑھی اور اور سر نہ پکڑ بیشک میں ڈرا اس سے کہ تو کہے گا تو نے بنی اسرائیل میں پھوٹ ڈال دی اور میرے فیصلہ کا انتظار نہ کیا'),
  ('ur.ahmedali', 20, 95, 'کہا اے سامری تیرا کیا معاملہ ہے'),
  ('ur.ahmedali', 20, 96, 'کہا میں نے وہ چیز دیکھی تھی جو دوسروں نے نہ دیکھی پھر میں نے رسول کے نقشِ قدم کی ایک مٹھی مٹی میں لے کر ڈال دی اور میرے دل نے مجھے ایسی ہی بات سوجھائی'),
  ('ur.ahmedali', 20, 97, 'کہا بس چلا جا تیرے لیے زندگی میں یہ سزا ہے کہ توکہے گا ہاتھ نہ لگانا اورتیرے لیے ایک وعدہ ہے جو تجھ سے ٹلنے والا نہیں اور تو اپنے معبود کو دیکھ جس پر تو جما بیٹھا تھا ہم اسے ضرور جلا دیں گے پھر اسے دریا میں بکھیر کر بہا دیں گے'),
  ('ur.ahmedali', 20, 98, 'تمہارا معبود ہی الله ہے جس کے سوا کوئی معبود نہیں اس کے علم میں سب چیز سما گئی ہے'),
  ('ur.ahmedali', 20, 99, 'ہم اسی طرح سے تجھے گزشتہ لوگوں کی کچھ خبریں سناتے ہیں اور ہم نے تجھے اپنے ہاں سے ایک نصیحت نامہ دیا ہے'),
  ('ur.ahmedali', 20, 100, 'جس نے اس سے منہ پھیرا سو وہ قیامت کے دن بوجھ اٹھائے گا'),
  ('ur.ahmedali', 20, 101, 'اس میں ہمیشہ رہیں گے اوران کے لیے قیامت کے دن بُرا بوجھ ہوگا'),
  ('ur.ahmedali', 20, 102, 'جس دن صور میں پھونکا جائے گا اور ہم اس دن مجرموں کو نیلی آنکھوں والے کر کے جمع کر دیں گے'),
  ('ur.ahmedali', 20, 103, 'چپکے چپکے آپس میں باتیں کہتے ہوں گے کہ تم صرف دس دن ٹھیرے ہو'),
  ('ur.ahmedali', 20, 104, 'ہم خوب جان لیں گے جو کچھ وہ کہیں گے جب ان میں سے بڑا سمجھدار کہے گا کہ تم صرف ایک ہی دن ٹھہرے ہو'),
  ('ur.ahmedali', 20, 105, 'اور تجھ سے پہاڑوں کا حال پوچھتے ہیں سوکہہ دے میرا رب انہیں بالکل اڑا دے گا'),
  ('ur.ahmedali', 20, 106, 'پھر زمین کو چٹیل میدان کر کے چھوڑے گا'),
  ('ur.ahmedali', 20, 107, 'تو اس میں کجی اور ٹیلا نہیں دیکھے گا'),
  ('ur.ahmedali', 20, 108, 'اس دن پکارےنے والے کا اتباع کریں گے اس میں کوئی کجی نہیں ہوگی اور رحمان کے ڈر سے آوازیں دب جائیں گی پھر تو پاؤں کی آہٹ کے سوا کچھ نہیں سنے گا'),
  ('ur.ahmedali', 20, 109, 'اس دن سفارش کام نہیں آئے گی مگر جسے رحمان نے اجازت دی اور اس کی بات پسند کی'),
  ('ur.ahmedali', 20, 110, 'وہ جانتا ہے جو کچھ ان کے آگے اور پیچھے ہے اور ان کا علم اسے احاطہ نہیں کر سکتا'),
  ('ur.ahmedali', 20, 111, 'اور سب منہ حّی و قیوم کے سامنے جھک جائیں گے اور تحقیق نامراد ہوا جس نے ظلم کا بوجھ اٹھایا'),
  ('ur.ahmedali', 20, 112, 'اور جو نیک کام کرے گا اور وہ مومن بھی ہو تو اسے ظلم اور حق تلفی کا کوئی خوف نہیں ہو گا'),
  ('ur.ahmedali', 20, 113, 'اور اسی طرح ہم نے اسے عربی قرآن نازل کیا ہے اور ہم نے اس میں طرح طرح سے ڈرانے کی باتیں سنائیں تاکہ وہ ڈریں یا ان میں سمجھ پیدا کر دے'),
  ('ur.ahmedali', 20, 114, 'سو الله بادشاہ حقیقی بلند مرتبے والا ہے اور تو قرآن کے لینے میں جلدی نہ کر جب تک اس کا اترنا پورا نہ ہوجائےاور کہہ اے میرے رب مجھے اور زیادہ علم دے'),
  ('ur.ahmedali', 20, 115, 'اور ہم نے اس سے پہلے آدم سے بھی عہد لیا تھا پھر وہ بھول گیا اور ہم نے اس میں پختگی نہ پائی'),
  ('ur.ahmedali', 20, 116, 'اور جب ہم نے فرشتوں سے کہا کہ آدم کو سجدہ کرو تو سوائے ابلیس کے سب نے سجدہ کیا اس نے انکار کیا'),
  ('ur.ahmedali', 20, 117, 'پھر ہم نے کہا اے آدم بے شک یہ تیرا اور تیری بیوی کا دشمن ہے سو تمہیں جنت سے نہ نکلوا دے پھر تو تکلیف میں پڑ جائے'),
  ('ur.ahmedali', 20, 118, 'بے شک تو اس میں بھوکا اورننگا نہیں ہوگا'),
  ('ur.ahmedali', 20, 119, 'اور بے شک تو اس میں نہ پیاسا ہوگا اور نہ تجھے دھوپ لگے گی'),
  ('ur.ahmedali', 20, 120, 'پھر شیطان نے اس کے دل میں خیال ڈالا کہا اے آدم کیا میں تجھے ہمیشگی کا درخت بتاؤں اور ایسی بادشاہی جس میں ضعف نہ آئے'),
  ('ur.ahmedali', 20, 121, 'پھر دونوں نے اس درخت سے کھایا تب ان پر ان کی برہنگی ظاہر ہوگئی اور اپنے اوپر جنت کے پتے چپکانے لگے اور آدم نے اپنے رب کی نافرمانی کی پھر بھٹک گیا'),
  ('ur.ahmedali', 20, 122, 'پھر اس کے رب نے اسے سرفراز کیا پھر اس کی توبہ قبول کی اور راہ دکھائی'),
  ('ur.ahmedali', 20, 123, 'فرمایا تم دونوں یہاں سے نکل جاؤ تم میں سے ایک دوسرے کا دشمن ہے پھر اگرتمہیں میری طرف سے ہدایت پہنچے پھر جو میری ہدایت پر چلے گا تو گمراہ نہیں ہو گا اور نہ تکلیف اٹھائے گا'),
  ('ur.ahmedali', 20, 124, 'اور جو میرے ذکر سے منہ پھیرے گا تو اس کی زندگی بھی تنگ ہوگی اور اسے قیامت کے دن اندھا کر کے اٹھا ئيں گے'),
  ('ur.ahmedali', 20, 125, 'کہے گا اے میرے رب تو نے مجھے اندھا کر کے کیوں اٹھایا حالانکہ میں بینا تھا'),
  ('ur.ahmedali', 20, 126, 'فرمائے گا اسی طرح تیرے پاس ہماری آیتیں پہنچی تھیں پھر تو نے انھیں بھلا دیا تھا اور اسی طرح آج تو بھی بھلایا گیا ہے'),
  ('ur.ahmedali', 20, 127, 'اور اسی طرح ہم بدلہ دیں گے جو حد سے نکلا اور اپنے رب کی آیتوں پر ایمان نہیں لیا اور البتہ آخرت کا عذاب بڑا سخت اور دیرپا ہے'),
  ('ur.ahmedali', 20, 128, 'سو کیا انہیں اس بات سے بھی سمجھ نہیں آئی کہ ہم نے ان سے پہلے کئی جماعتیں ہلاک کر دی ہیں یہ لوگ ان کی جگہوں پر پھرتے ہیں بیشک اس میں عقل والوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 20, 129, 'اور اگر تیرے رب کی طرف سے ایک بات پہلے طے شدہ نہ ہوتی اور معیاد معین نہ ہوتی تو عذاب لازمی طور پر ہوتا'),
  ('ur.ahmedali', 20, 130, 'پس صبر کر اس پر جو کہتے ہیں اور سورج کے نکلنے اور ڈوبنے سے پہلے اپنے رب کی حمد کے ساتھ تسبیح بیان کر اور رات کی کچھ گھڑیوں میں اور دن کے اول اور آخر میں تسبیح کر تاکہ تجھے خوشی حاصل ہو'),
  ('ur.ahmedali', 20, 131, 'اور تو اپنی نظر ان چیزو ں کی طرف نہ دوڑا جو ہم نے مختلف قسم کے لوگوں کو دنیاوی زندگی کی رونق کے سامان دے رکھے ہیں تاکہ ہم انہیں اس میں آزمائیں او رتیرے رب کا رزق بہتر اور دیرپا ہے'),
  ('ur.ahmedali', 20, 132, 'اور اپنے گھر والو ں کو نماز کا حکم کر اور خود بھی اس پر قائم رہ ہم تجھ سے روزی نہیں مانگتے ہم تجھے روزی دیتے ہیں اور پرہیزگاری کا انجام اچھا ہے'),
  ('ur.ahmedali', 20, 133, 'اور لوگ کہتے ہیں کہ یہ ہمارے پاس اپنے رب سے کوئی نشانی کیوں نہیں لے آتا کیا ان کے پاس پہلی کتابوں کی شہادت نہیں پہنچی'),
  ('ur.ahmedali', 20, 134, 'اور اگر ہم انہیں اس سے پہلے کسی عذاب سے ہلاک کر دیتے تو کہتے اے ہمارے رب تو نے ہمارے پاس کوئی رسول کیوں نہ بھیجا تاکہ ہم ذلیل و خوار ہونے سے پہلے تیرے حکموں پر چلتے'),
  ('ur.ahmedali', 20, 135, 'کہہ دو ہر ایک انتظار کرنے والا ہے سو تم بھی انتظار کرو آئندہ تمہیں معلوم ہو جائے گا کہ سیدھی راہ پر کون ہے اور ہدایت پانے والا کون ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 20, 1, 'Ta, Ha.'),
  ('tr.diyanet', 20, 2, 'Kuran\'ı sana, sıkıntıya düşeşin diye değil, ancak Allah\'tan korkanlara bir öğüt ve yeri ve yüce gökleri yaratanın katından bir Kitap olarak indirdik.'),
  ('tr.diyanet', 20, 3, 'Kuran\'ı sana, sıkıntıya düşeşin diye değil, ancak Allah\'tan korkanlara bir öğüt ve yeri ve yüce gökleri yaratanın katından bir Kitap olarak indirdik.'),
  ('tr.diyanet', 20, 4, 'Kuran\'ı sana, sıkıntıya düşeşin diye değil, ancak Allah\'tan korkanlara bir öğüt ve yeri ve yüce gökleri yaratanın katından bir Kitap olarak indirdik.'),
  ('tr.diyanet', 20, 5, 'Rahman arşa hükmetmektedir.'),
  ('tr.diyanet', 20, 6, 'Göklerde ve yerde, her ikisi arasında ve toprağın altında bulunanlar O\'nundur.'),
  ('tr.diyanet', 20, 7, 'Sen sözü istersen açığa vur, şüphesiz O gizliyi de, gizlinin gizlisini de bilir.'),
  ('tr.diyanet', 20, 8, 'Allah\'tan başka tanrı yoktur, en güzel isimler O\'nundur.'),
  ('tr.diyanet', 20, 9, 'Musa\'nın başından geçen olay sana geldi mi?'),
  ('tr.diyanet', 20, 10, 'O, bir ateş görmüştü de, ailesine: "Durun, ben bir ateş gördüm, ya ondan size bir kor getirir, ya da ateşin yanında bir yol gösteren bulurum" demişti.'),
  ('tr.diyanet', 20, 11, 'Musa ateşin yanına gelince: "Ey Musa!" diye seslenildi:'),
  ('tr.diyanet', 20, 12, '"Ben şüphesiz senin Rabbinim; ayağındakileri çıkar; çünkü sen, kutsal bir vadi olan Tuva\'dasın."'),
  ('tr.diyanet', 20, 13, '"Ben seni seçtim; artık vahyolunanları dinle."'),
  ('tr.diyanet', 20, 14, '"Şüphesiz Ben Allah\'ım, Benden başka tanrı yoktur; Bana kulluk et; Beni anmak için namaz kıl."'),
  ('tr.diyanet', 20, 15, 'Herkes işlediğinin karşılığını görsün diye, zamanını gizli tuttuğum kıyamet mutlaka gelecektir.'),
  ('tr.diyanet', 20, 16, '"Buna inanmayan ve hevesine uyan kimse seni ondan alıkoymasın, yoksa helak olursun."'),
  ('tr.diyanet', 20, 17, '"Ey Musa! Sağ elindeki nedir?"'),
  ('tr.diyanet', 20, 18, 'Musa: "O benim değneğimdir, ona dayanırım, onunla davarıma yaprak silkerim, ondan daha birçok işlerde faydalanırım" dedi.'),
  ('tr.diyanet', 20, 19, 'Allah: "Ey Musa! Bırak onu" dedi.'),
  ('tr.diyanet', 20, 20, 'Bırakınca, değnek hemen, koşan bir yılan oluverdi.'),
  ('tr.diyanet', 20, 21, 'Allah: "Onu al, korkma; biz onu yine eski durumuna çevireceğiz. Daha büyük mucizelerimizi sana göstermemiz için elini koltuğunun altına koy da, diğer bir mucize olarak, kusursuz, bembeyaz çıksın" dedi.'),
  ('tr.diyanet', 20, 22, 'Allah: "Onu al, korkma; biz onu yine eski durumuna çevireceğiz. Daha büyük mucizelerimizi sana göstermemiz için elini koltuğunun altına koy da, diğer bir mucize olarak, kusursuz, bembeyaz çıksın" dedi.'),
  ('tr.diyanet', 20, 23, 'Allah: "Onu al, korkma; biz onu yine eski durumuna çevireceğiz. Daha büyük mucizelerimizi sana göstermemiz için elini koltuğunun altına koy da, diğer bir mucize olarak, kusursuz, bembeyaz çıksın" dedi.'),
  ('tr.diyanet', 20, 24, '"Firavun\'a git, doğrusu o azmıştır."'),
  ('tr.diyanet', 20, 25, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 26, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 27, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 28, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 29, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 30, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 31, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 32, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 33, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 34, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 35, 'Musa: "Rabbim! Göğsümü genişlet, işimi kolaylaştır, dilimin düğümünü çöz ki sözümü iyi anlasınlar. Ailemden kardeşim Harun\'u bana vezir yap, beni onunla destekle, onu görevimde ortak kıl ki Seni daha çok tesbih edelim ve çokça analım. Şüphesiz Sen bizi görmektesin" dedi.'),
  ('tr.diyanet', 20, 36, 'Allah: "Ey Musa! İstediğin sana verildi" dedi, "Zaten sana başka bir defa da iyilikte bulunmuş ve annene vahyedilmesi gerekeni vahyetmiştik: Musa\'yı bir sandığa koy da suya bırak; su onu kıyıya atar, Bana da, ona da düşman olan biri onu alır. Ey Musa! Gözümün önünde yetişesin diye seni sevimli kıldım."'),
  ('tr.diyanet', 20, 37, 'Allah: "Ey Musa! İstediğin sana verildi" dedi, "Zaten sana başka bir defa da iyilikte bulunmuş ve annene vahyedilmesi gerekeni vahyetmiştik: Musa\'yı bir sandığa koy da suya bırak; su onu kıyıya atar, Bana da, ona da düşman olan biri onu alır. Ey Musa! Gözümün önünde yetişesin diye seni sevimli kıldım."'),
  ('tr.diyanet', 20, 38, 'Allah: "Ey Musa! İstediğin sana verildi" dedi, "Zaten sana başka bir defa da iyilikte bulunmuş ve annene vahyedilmesi gerekeni vahyetmiştik: Musa\'yı bir sandığa koy da suya bırak; su onu kıyıya atar, Bana da, ona da düşman olan biri onu alır. Ey Musa! Gözümün önünde yetişesin diye seni sevimli kıldım."'),
  ('tr.diyanet', 20, 39, 'Allah: "Ey Musa! İstediğin sana verildi" dedi, "Zaten sana başka bir defa da iyilikte bulunmuş ve annene vahyedilmesi gerekeni vahyetmiştik: Musa\'yı bir sandığa koy da suya bırak; su onu kıyıya atar, Bana da, ona da düşman olan biri onu alır. Ey Musa! Gözümün önünde yetişesin diye seni sevimli kıldım."'),
  ('tr.diyanet', 20, 40, 'Kızkardeşin Firavun\'un sarayına giderek: "Ona bakacak birini size göstereyim mi?" diyordu. Böylece, annen üzülmesin, sevinsin diye, seni ona iade etmiştik. Sen bir cana kıymıştın, seni üzüntüden kurtarmış ve seni birçok musibetlerle denemiştik. Bunun için, Medyen halkı arasında yıllarca kalmıştın. Sonra, ey Musa, peygamberlik görevini yüklenecek bir yaşa gelince dönüp geldin.'),
  ('tr.diyanet', 20, 41, 'Seni kendim için ayırdım.'),
  ('tr.diyanet', 20, 42, 'Sen ve kardeşin, ayetlerimle gidin; beni anmakta gevşek davranmayın.'),
  ('tr.diyanet', 20, 43, 'Firavun\'a gidin, doğrusu o azmıştır.'),
  ('tr.diyanet', 20, 44, 'Ona yumuşak söz söyleyin, belki öğüt dinler veya korkar.'),
  ('tr.diyanet', 20, 45, 'Musa ve kardeşi: "Rabbimiz! Onun bize kötülük etmesinden veya azgınlığının artmasından korkarız" dediler.'),
  ('tr.diyanet', 20, 46, 'Allah: Korkmayın, dedi; Ben sizinle beraberim; görür ve işitirim. Ona gidin şöyle söyleyin: "Doğrusu biz senin Rabbinin elçileriyiz. İsrailoğullarını bizimle beraber gönder, onlara azabetme; Rabbinden sana bir mucize getirdik; selam, doğru yolda gidene olsun! Doğrusu bize, yalanlayıp sırt çevirene azap edileceği vahyolundu."'),
  ('tr.diyanet', 20, 47, 'Allah: Korkmayın, dedi; Ben sizinle beraberim; görür ve işitirim. Ona gidin şöyle söyleyin: "Doğrusu biz senin Rabbinin elçileriyiz. İsrailoğullarını bizimle beraber gönder, onlara azabetme; Rabbinden sana bir mucize getirdik; selam, doğru yolda gidene olsun! Doğrusu bize, yalanlayıp sırt çevirene azap edileceği vahyolundu."'),
  ('tr.diyanet', 20, 48, 'Allah: Korkmayın, dedi; Ben sizinle beraberim; görür ve işitirim. Ona gidin şöyle söyleyin: "Doğrusu biz senin Rabbinin elçileriyiz. İsrailoğullarını bizimle beraber gönder, onlara azabetme; Rabbinden sana bir mucize getirdik; selam, doğru yolda gidene olsun! Doğrusu bize, yalanlayıp sırt çevirene azap edileceği vahyolundu."'),
  ('tr.diyanet', 20, 49, 'Firavun: "Musa! Rabbiniz kimdir?" dedi.'),
  ('tr.diyanet', 20, 50, 'Musa: "Rabbimiz, her şeye ayrı bir özellik veren, sonra doğru yola eriştirendir" dedi.'),
  ('tr.diyanet', 20, 51, 'Firavun: "Öyleyse önceki nesillerin durumu ne oluyor?" dedi.'),
  ('tr.diyanet', 20, 52, 'Musa: "Onların bilgisi Rabbimin katında yazılıdır. Rabbim şaşırmaz ve unutmaz." dedi.'),
  ('tr.diyanet', 20, 53, 'Sizin için yeryüzünü döşeyen, yollar açan, gökten su indiren O\'dur. Biz o su ile türlü türlü, çift çift bitkiler yetiştirdik.'),
  ('tr.diyanet', 20, 54, 'İster yiyin, ister hayvanlarınızı otlatın, onlarda akıl sahipleri için şüphesiz dersler vardır.'),
  ('tr.diyanet', 20, 55, 'Sizi yerden yarattık, oraya döndüreceğiz, sizi tekrar oradan çıkaracağız.'),
  ('tr.diyanet', 20, 56, 'And olsun ki Firavun\'a bütün delillerimizi gösterdik de yalan sayıp kabulden çekindi ve: "Ey Musa! Sihirbazlığınla bizi yurdumuzdan çıkarmaya mı geldin? Şimdi biz de seninkinin benzeri bir sihri sana göstereceğiz. Bizimle senin aranda bir vakit tayinet ki sen de biz de düz bir yerde bulunalım da caymayalım" dedi.'),
  ('tr.diyanet', 20, 57, 'And olsun ki Firavun\'a bütün delillerimizi gösterdik de yalan sayıp kabulden çekindi ve: "Ey Musa! Sihirbazlığınla bizi yurdumuzdan çıkarmaya mı geldin? Şimdi biz de seninkinin benzeri bir sihri sana göstereceğiz. Bizimle senin aranda bir vakit tayinet ki sen de biz de düz bir yerde bulunalım da caymayalım" dedi.'),
  ('tr.diyanet', 20, 58, 'And olsun ki Firavun\'a bütün delillerimizi gösterdik de yalan sayıp kabulden çekindi ve: "Ey Musa! Sihirbazlığınla bizi yurdumuzdan çıkarmaya mı geldin? Şimdi biz de seninkinin benzeri bir sihri sana göstereceğiz. Bizimle senin aranda bir vakit tayinet ki sen de biz de düz bir yerde bulunalım da caymayalım" dedi.'),
  ('tr.diyanet', 20, 59, 'Musa: "Buluşma zamanımız sizin bayram gününüzde, insanların toplandığı kuşluk vaktidir" dedi.'),
  ('tr.diyanet', 20, 60, 'Firavun döndü, tuzaklarını toplayıp o gün geldi.'),
  ('tr.diyanet', 20, 61, 'Musa onlara: "Size yazıklar olsun! Allah\'a karşı yalan uydurmayın, yoksa sizi azabla yok eder. Allah\'a iftira eden hüsrana uğrar" dedi.'),
  ('tr.diyanet', 20, 62, 'Sihirbazlar işi aralarında tartıştılar ve konuşmalarını gizli tuttular.'),
  ('tr.diyanet', 20, 63, 'Musa ile Harun\'u göstererek: "Bu iki sihirbaz, sihirleriyle sizi yurdunuzdan çıkarmak, sizin en üstün dininizi ortadan kaldırmak istiyorlar; onun için tuzaklarınızı bir araya getirin, sonra sırayla gelin. Bugün üstün gelen başarıya erecektir" dediler.'),
  ('tr.diyanet', 20, 64, 'Musa ile Harun\'u göstererek: "Bu iki sihirbaz, sihirleriyle sizi yurdunuzdan çıkarmak, sizin en üstün dininizi ortadan kaldırmak istiyorlar; onun için tuzaklarınızı bir araya getirin, sonra sırayla gelin. Bugün üstün gelen başarıya erecektir" dediler.'),
  ('tr.diyanet', 20, 65, '"Ey Musa! Marifetini ya sen ortaya koy, ya da önce biz koyalım" dediler.'),
  ('tr.diyanet', 20, 66, 'Musa: "Siz koyun" dedi. Hemen, değnekleri ve ipleri, sihirleri yüzünden, Musa\'ya sanki yürüyorlarmış gibi geldi.'),
  ('tr.diyanet', 20, 67, 'Bu yüzden Musa içinde bir korku hissetti.'),
  ('tr.diyanet', 20, 68, '"Korkma, sen muhakkak daha üstünsün" dedik.'),
  ('tr.diyanet', 20, 69, '"Sağ elindekini at da onların yaptıklarını yutsun, yaptıkları sadece sihirbaz düzenidir. Sihirbaz nereden gelirse gelsin başarı kazanamaz."'),
  ('tr.diyanet', 20, 70, 'Sonunda sihirbazlar: "Biz Musa ve Harun\'un Rabbine inandık" deyip secdeye kapandılar.'),
  ('tr.diyanet', 20, 71, 'Firavun "Ben size izin vermeden mi O\'na inandınız? Doğrusu size sihri öğreten, büyüğünüz odur. And olsun ki, ellerinizi ve ayaklarınızı çaprazlama keseceğim, sizi hurma kütüklerine asacağım. Hangimizin azabının daha çetin ve daha devamlı olduğunu bileceksiniz" dedi.'),
  ('tr.diyanet', 20, 72, 'İman eden sihirbazlar: "Seni, gelen apaçık mucizelere ve bizi yaratana üstün tutmayacağız. Ne hüküm vereceksen ver. Sen, ancak bu dünya hayatına hükmedebilirsin. Doğrusu biz, yanılmalarımızı ve bize zorla yaptırdığın sihri bağışlaması için Rabbimize iman ettik. Allah\'ın vereceği mükafat daha iyi ve daha devamlıdır" dediler.'),
  ('tr.diyanet', 20, 73, 'İman eden sihirbazlar: "Seni, gelen apaçık mucizelere ve bizi yaratana üstün tutmayacağız. Ne hüküm vereceksen ver. Sen, ancak bu dünya hayatına hükmedebilirsin. Doğrusu biz, yanılmalarımızı ve bize zorla yaptırdığın sihri bağışlaması için Rabbimize iman ettik. Allah\'ın vereceği mükafat daha iyi ve daha devamlıdır" dediler.'),
  ('tr.diyanet', 20, 74, 'Rabbine suçlu olarak gelen bilsin ki, cehennem onun içindir. Orada ne ölür, ne yaşar.'),
  ('tr.diyanet', 20, 75, 'Rabbine inanmış ve yararlı iş yaparak gelenlere, işte onlara, en üstün dereceler, içlerinden ırmaklar akan, içinde temelli kalacakları Adn cennetleri vardır. Bu, arınanların mükafatıdır.'),
  ('tr.diyanet', 20, 76, 'Rabbine inanmış ve yararlı iş yaparak gelenlere, işte onlara, en üstün dereceler, içlerinden ırmaklar akan, içinde temelli kalacakları Adn cennetleri vardır. Bu, arınanların mükafatıdır.'),
  ('tr.diyanet', 20, 77, 'And olsun ki Musa\'ya: "Kullarımı geceleyin yürüt, denizde onlara kuru bir yol aç, batmaktan ve düşmanların yetişmesinden korkma, endişe etme" diye vahyettik.'),
  ('tr.diyanet', 20, 78, 'Firavun, ordusuyla onları takip etti, deniz de onları içine alıverdi, hem de ne alış!'),
  ('tr.diyanet', 20, 79, 'Firavun, milletini saptırdı, onlara doğru yolu göstermedi.'),
  ('tr.diyanet', 20, 80, 'Ey İsrailoğulları! Sizleri düşmanınızdan kurtardık, Tur\'un sağ yanını size vadettik ve üzerinize kudret helvasıyla bıldırcın indirdik.'),
  ('tr.diyanet', 20, 81, 'Size verdiğimiz rızıkların temizlerinden yiyin, bunda aşırı gitmeyin ki gazabımı haketmeyesiniz. Gazabımı hakeden kimse muhakkak mahvolur.'),
  ('tr.diyanet', 20, 82, 'Doğrusu Ben, tevbe edeni, inanıp yararlı iş işleyerek doğru yola gireni bağışlarım.'),
  ('tr.diyanet', 20, 83, '"Musa! Seni milletinden daha çabuk gelmeye sevkeden nedir?" dedik.'),
  ('tr.diyanet', 20, 84, 'Musa: "Onlar ardımdadır, Rabbim! Hoşnut olman için Sana acele geldim" dedi.'),
  ('tr.diyanet', 20, 85, 'Allah: "Doğrusu Biz, senden sonra milletini sınadık; Samiri onları saptırdı" dedi.'),
  ('tr.diyanet', 20, 86, 'Musa, milletine kızgın ve üzgün olarak döndü. "Ey milletim! Rabbiniz size güzel bir vaadde bulunmadı mı? Uzun bir zaman mı geçti, yoksa Rabbinizin gazabına mı uğramak istediniz de bana verdiğiniz sözden caydınız?" dedi.'),
  ('tr.diyanet', 20, 87, 'Onlar: "Sana verdiğimiz sözden kendi başımıza caymadık. O milletin ziynet eşyasından bize yükler dolusu taşıtıldı. Biz onları ateşe attık, aynı şekilde Samiri de attı" dediler.'),
  ('tr.diyanet', 20, 88, 'Bunun üzerine Samiri onlara böğüren bir buzağı heykeli ortaya koydu. O ve adamları: "Bu sizin de Musa\'nın da tanrısıdır, ama o unuttu" dediler.'),
  ('tr.diyanet', 20, 89, 'Görmüyorlar mıydı ki, o heykel onlara ne söz söyleyebilir, ne zarar ve ne de fayda verebilirdi?'),
  ('tr.diyanet', 20, 90, 'And olsun ki, Harun da onlara önceden: "Ey milletim! Siz bu buzağı ile sınanıyorsunuz. Sizin gerçek Rabbiniz Rahman\'dır. Bana uyun, emrime itaat edin" demişti.'),
  ('tr.diyanet', 20, 91, '"Musa bize dönene kadar buna sarılmaktan vazgeçmeyeceğiz" demişlerdi.'),
  ('tr.diyanet', 20, 92, 'Musa gelince: "Harun! Onların sapıttığını görünce seni benim yolumdan gitmekten alıkoyan nedir? Benim emrime karşı mı geldin?" dedi.'),
  ('tr.diyanet', 20, 93, 'Musa gelince: "Harun! Onların sapıttığını görünce seni benim yolumdan gitmekten alıkoyan nedir? Benim emrime karşı mı geldin?" dedi.'),
  ('tr.diyanet', 20, 94, 'Harun: "Ey Annemoğlu! Saçımdan sakalımdan tutma; doğrusu İsrailoğulları arasına ayrılık koydun, sözüme bakmadın demenden korktum" dedi.'),
  ('tr.diyanet', 20, 95, 'Musa: "Ey Samiri! Ya senin yaptığın nedir?" dedi.'),
  ('tr.diyanet', 20, 96, 'Samiri: "Onların görmedikleri bir şey gördüm ve o sana gelen elçinin bastığı yerden bir avuç avuçladım. Bunu ziynet eşyasının eritildiği potaya attım. Nefsim böyle yaptırdı" dedi.'),
  ('tr.diyanet', 20, 97, 'Musa: "Defol! Doğrusu artık hayatta, "Bana dokunmayın!" demenden başka yapacağın yoktur. Senin için asla kaçamayacağın bir ceza daha vardır. Durup üzerinde titrediğin tanrına bak, onu yakacağız, sonra denize dökeceğiz" dedi.'),
  ('tr.diyanet', 20, 98, 'Sizin Tanrınız, ancak, O\'ndan başka tanrı olmayan Allah\'tır. İlmi her şeyi içine almıştır.'),
  ('tr.diyanet', 20, 99, 'Geçmiş olayları sana böyle anlatırız. Katımızdan sana da bir Kitap verdik; kim ondan yüz çevirirse bilsin ki kıyamet günü bir günah yükü yüklenecektir.'),
  ('tr.diyanet', 20, 100, 'Geçmiş olayları sana böyle anlatırız. Katımızdan sana da bir Kitap verdik; kim ondan yüz çevirirse bilsin ki kıyamet günü bir günah yükü yüklenecektir.'),
  ('tr.diyanet', 20, 101, 'Devamlı bu günahın azabında kalacaklar. Kıyamet günü onlar için ne kötüdür bu yük!'),
  ('tr.diyanet', 20, 102, 'Sura üflendiği gün, işte o gün, suçluları gözleri korkudan göğermiş olarak toplarız.'),
  ('tr.diyanet', 20, 103, '"Siz dünyada sadece on gün eğleştiniz" diye, aralarında saklı saklı konuşurlar.'),
  ('tr.diyanet', 20, 104, 'Aralarında konuştuklarını Biz daha iyi biliriz. En akıllıları: "Sadece bir gün eğleştiniz" der.'),
  ('tr.diyanet', 20, 105, 'Sana dağları sorarlar; de ki: "Rabbim onları ufalayıp savuracak, yerlerini düz, kuru bir toprak haline getirecek; orada ne çukur, ne tümsek göreceksin. O gün, hiçbir tarafa sapmadan bir davetçiye uyarlar. Sesler Rahman\'ın heybetinden kısılmıştır; ancak bir fısıltı işitirsin."'),
  ('tr.diyanet', 20, 106, 'Sana dağları sorarlar; de ki: "Rabbim onları ufalayıp savuracak, yerlerini düz, kuru bir toprak haline getirecek; orada ne çukur, ne tümsek göreceksin. O gün, hiçbir tarafa sapmadan bir davetçiye uyarlar. Sesler Rahman\'ın heybetinden kısılmıştır; ancak bir fısıltı işitirsin."'),
  ('tr.diyanet', 20, 107, 'Sana dağları sorarlar; de ki: "Rabbim onları ufalayıp savuracak, yerlerini düz, kuru bir toprak haline getirecek; orada ne çukur, ne tümsek göreceksin. O gün, hiçbir tarafa sapmadan bir davetçiye uyarlar. Sesler Rahman\'ın heybetinden kısılmıştır; ancak bir fısıltı işitirsin."'),
  ('tr.diyanet', 20, 108, 'Sana dağları sorarlar; de ki: "Rabbim onları ufalayıp savuracak, yerlerini düz, kuru bir toprak haline getirecek; orada ne çukur, ne tümsek göreceksin. O gün, hiçbir tarafa sapmadan bir davetçiye uyarlar. Sesler Rahman\'ın heybetinden kısılmıştır; ancak bir fısıltı işitirsin."'),
  ('tr.diyanet', 20, 109, 'O gün Rahman\'ın izin verdiği ve sözünden hoşnut olduğu kimseden başkasının şefaati fayda vermez.'),
  ('tr.diyanet', 20, 110, 'Allah onların geçmişlerini de, geleceklerini de bilir. Onların hiçbirinin ilmi ise O\'nu kuşatamaz.'),
  ('tr.diyanet', 20, 111, 'İnsanlar, diri ve her an yaratıklarını gözetip duran Allah\'a boyun eğmiştir. Yükü zulüm olan kimse ise hüsrana uğramıştır.'),
  ('tr.diyanet', 20, 112, 'İnanmış olarak, yararlı işler işleyen kimse, haksızlıktan ve hakkının yeneceğinden korkmaz.'),
  ('tr.diyanet', 20, 113, 'İşte Kuran\'ı, Arapça okunmak üzere indirdik, onda tehditleri türlü türlü açıkladık ki belki sakınırlar yahut onlara ibret verir.'),
  ('tr.diyanet', 20, 114, 'Gerçek hükümdar olan Allah Yüce\'dir. Kuran sana vahyedilirken, vahy bitmezden önce, unutmamak için, tekrarda acele edip durma, "Rabbim! ilmimi artır" de.'),
  ('tr.diyanet', 20, 115, 'And olsun ki daha önce "Adem\'e secde edin" demiştik; İblis\'ten başka hepsi secde etmiş, o çekinmişti.'),
  ('tr.diyanet', 20, 116, '"Ey Adem! Doğrusu bu, senin ve eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın, yoksa bedbaht olursun. Doğrusu cennette ne acıkırsın, ne de çıplak kalırsın; orada ne susarsın ne de güneşin sıcağında kalırsın" dedik.'),
  ('tr.diyanet', 20, 117, '"Ey Adem! Doğrusu bu, senin ve eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın, yoksa bedbaht olursun. Doğrusu cennette ne acıkırsın, ne de çıplak kalırsın; orada ne susarsın ne de güneşin sıcağında kalırsın" dedik.'),
  ('tr.diyanet', 20, 118, '"Ey Adem! Doğrusu bu, senin ve eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın, yoksa bedbaht olursun. Doğrusu cennette ne acıkırsın, ne de çıplak kalırsın; orada ne susarsın ne de güneşin sıcağında kalırsın" dedik.'),
  ('tr.diyanet', 20, 119, '"Ey Adem! Doğrusu bu, senin ve eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın, yoksa bedbaht olursun. Doğrusu cennette ne acıkırsın, ne de çıplak kalırsın; orada ne susarsın ne de güneşin sıcağında kalırsın" dedik.'),
  ('tr.diyanet', 20, 120, 'Ama şeytan ona vesvese verip: "Ey Adem! Sana sonsuzluk ağacını ve çökmesi olmayan bir saltanatı göstereyim mi?" dedi.'),
  ('tr.diyanet', 20, 121, 'Bunun üzerine ikisi de o ağacın meyvesinden yedi, ayıp yerleri görünüverdi. Cennet yapraklarıyla örtünmeye koyuldular. Adem, Rabbine baş kaldırdı ve yolunu şaşırdı.'),
  ('tr.diyanet', 20, 122, 'Rabbi yine de onu seçip tevbesini kabul etti, ona doğru yolu gösterdi.'),
  ('tr.diyanet', 20, 123, 'Onlara şöyle dedi: "Birbirinize düşman olarak hepiniz oradan inin. Elbet size Benden bir yol gösteren gelir; Benim yoluma uyan ne sapar ve ne de bedbaht olur."'),
  ('tr.diyanet', 20, 124, 'Benim Kitap\'ımdan yüz çeviren bilsin ki onun dar bir geçimi olur ve kıyamet günü de onu kör olarak haşrederiz.'),
  ('tr.diyanet', 20, 125, 'O zaman: "Rabbim! Beni niçin kör olarak haşrettin, oysa ben gören bir kimseydim" der.'),
  ('tr.diyanet', 20, 126, 'Allah: "Böyledir, ayetlerimiz sana gelmişti de sen onları unutmuştun, bugün de öylece unutulursun" der.'),
  ('tr.diyanet', 20, 127, 'İşte haddi aşanları, Rabbinin ayetlerine inanmayanları böylece cezalandıracağız. Hem, ahiretin azabı bu dünya azabından daha şiddetli ve daha devamlıdır.'),
  ('tr.diyanet', 20, 128, 'Onları yerlerinde gezdikleri, kendilerinden önce yok etmiş olduğumuz bunca nesiller doğru yola sevketmedi mi? Doğrusu bunlarda akıl sahipleri için ibretler vardır.'),
  ('tr.diyanet', 20, 129, 'Eğer Rabbinin verilmiş bir sözü ve tayin ettiği bir süre olmasaydı, hemen azaba uğrarlardı.'),
  ('tr.diyanet', 20, 130, 'Onların dediklerine sabret; güneşin doğmasından ve batmasından önce Rabbini hamd ile tesbih et; gece saatlerinde ve gündüzleri de tesbih et ki Rabbinin rızasına eresin.'),
  ('tr.diyanet', 20, 131, 'Kendilerini sınamak için, dünya hayatının süsü olarak bol bol geçimlik verdiğimiz kimselere sakın göz dikme, Rabbinin rızkı daha iyi ve daha devamlıdır.'),
  ('tr.diyanet', 20, 132, 'Ehline namaz kılmalarını emret, kendin de onda devamlı ol. Biz senden rızık istemiyoruz, sana rızık veren Biziz. Sonuç Allah\'a karşı gelmekten sakınanındır.'),
  ('tr.diyanet', 20, 133, '"Rabbinden bize bir mucize getirseydi ya" derler. Onlara, önceki Kitablarda bulunan belgeler gelmedi mi?'),
  ('tr.diyanet', 20, 134, 'Eğer onları ondan önce bir azaba uğratarak yok etseydik: "Rabbimiz! Bize bir peygamber gönderseydin de, alçak ve rezil olmazdan önce ayetlerine uysaydık, olmaz mıydı?" diyeceklerdi.'),
  ('tr.diyanet', 20, 135, 'De ki: "Herkes gözlemektedir, siz de gözleyin. Şüphesiz düz yolun sahiplerinin kimler olduğunu ve kimlerin doğru yolda bulunduğunu bileceksiniz."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 20, 1, 'Thaahaa.'),
  ('id.indonesian', 20, 2, 'Kami tidak menurunkan Al Quran ini kepadamu agar kamu menjadi susah;'),
  ('id.indonesian', 20, 3, 'tetapi sebagai peringatan bagi orang yang takut (kepada Allah),'),
  ('id.indonesian', 20, 4, 'yaitu diturunkan dari Allah yang menciptakan bumi dan langit yang tinggi.'),
  ('id.indonesian', 20, 5, '(Yaitu) Tuhan Yang Maha Pemurah. Yang bersemayam di atas \'Arsy.'),
  ('id.indonesian', 20, 6, 'Kepunyaan-Nya-lah semua yang ada di langit, semua yang di bumi, semua yang di antara keduanya dan semua yang di bawah tanah.'),
  ('id.indonesian', 20, 7, 'Dan jika kamu mengeraskan ucapanmu, maka sesungguhnya Dia mengetahui rahasia dan yang lebih tersembunyi.'),
  ('id.indonesian', 20, 8, 'Dialah Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia. Dia mempunyai al asmaaul husna (nama-nama yang baik),'),
  ('id.indonesian', 20, 9, 'Apakah telah sampai kepadamu kisah Musa?'),
  ('id.indonesian', 20, 10, 'Ketika ia melihat api, lalu berkatalah ia kepada keluarganya: "Tinggallah kamu (di sini), sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa sedikit daripadanya kepadamu atau aku akan mendapat petunjuk di tempat api itu".'),
  ('id.indonesian', 20, 11, 'Maka ketika ia datang ke tempat api itu ia dipanggil: "Hai Musa.'),
  ('id.indonesian', 20, 12, 'Sesungguhnya Aku inilah Tuhanmu, maka tanggalkanlah kedua terompahmu; sesungguhnya kamu berada dilembah yang suci, Thuwa.'),
  ('id.indonesian', 20, 13, 'Dan Aku telah memilih kamu, maka dengarkanlah apa yang akan diwahyukan (kepadamu).'),
  ('id.indonesian', 20, 14, 'Sesungguhnya Aku ini adalah Allah, tidak ada Tuhan (yang hak) selain Aku, maka sembahlah Aku dan dirikanlah shalat untuk mengingat Aku.'),
  ('id.indonesian', 20, 15, 'Segungguhnya hari kiamat itu akan datang Aku merahasiakan (waktunya) agar supaya tiap-tiap diri itu dibalas dengan apa yang ia usahakan.'),
  ('id.indonesian', 20, 16, 'Maka sekali-kali janganlah kamu dipalingkan daripadanya oleh orang yang tidak beriman kepadanya dan oleh orang yang mengikuti hawa nafsunya, yang menyebabkan kamu jadi binasa".'),
  ('id.indonesian', 20, 17, 'Apakah itu yang di tangan kananmu, hai Musa?'),
  ('id.indonesian', 20, 18, 'Berkata Musa: "Ini adalah tongkatku, aku bertelekan padanya, dan aku pukul (daun) dengannya untuk kambingku, dan bagiku ada lagi keperluan yang lain padanya".'),
  ('id.indonesian', 20, 19, 'Allah berfirman: "Lemparkanlah ia, hai Musa!"'),
  ('id.indonesian', 20, 20, 'Lalu dilemparkannyalah tongkat itu, maka tiba-tiba ia menjadi seekor ular yang merayap dengan cepat.'),
  ('id.indonesian', 20, 21, 'Allah berfirman: "Peganglah ia dan jangan takut, Kami akan mengembalikannya kepada keadaannya semula,'),
  ('id.indonesian', 20, 22, 'dan kepitkanlah tanganmu ke ketiakmu, niscaya ia ke luar menjadi putih cemerlang tanpa cacad, sebagai mukjizat yang lain (pula),'),
  ('id.indonesian', 20, 23, 'untuk Kami perlihatkan kepadamu sebahagian dari tanda-tanda kekuasaan Kami yang sangat besar,'),
  ('id.indonesian', 20, 24, 'Pergilah kepada Fir\'aun; sesungguhnya ia telah melampaui batas".'),
  ('id.indonesian', 20, 25, 'Berkata Musa: "Ya Tuhanku, lapangkanlah untukku dadaku,'),
  ('id.indonesian', 20, 26, 'dan mudahkanlah untukku urusanku,'),
  ('id.indonesian', 20, 27, 'dan lepaskanlah kekakuan dari lidahku,'),
  ('id.indonesian', 20, 28, 'supaya mereka mengerti perkataanku,'),
  ('id.indonesian', 20, 29, 'dan jadikanlah untukku seorang pembantu dari keluargaku,'),
  ('id.indonesian', 20, 30, '(yaitu) Harun, saudaraku,'),
  ('id.indonesian', 20, 31, 'teguhkanlah dengan dia kekuatanku,'),
  ('id.indonesian', 20, 32, 'dan jadikankanlah dia sekutu dalam urusanku,'),
  ('id.indonesian', 20, 33, 'supaya kami banyak bertasbih kepada Engkau,'),
  ('id.indonesian', 20, 34, 'dan banyak mengingat Engkau.'),
  ('id.indonesian', 20, 35, 'Sesungguhnya Engkau adalah Maha Melihat (keadaan) kami".'),
  ('id.indonesian', 20, 36, 'Allah berfirman: "Sesungguhnya telah diperkenankan permintaanmu, hai Musa".'),
  ('id.indonesian', 20, 37, 'Dan sesungguhnya Kami telah memberi nikmat kepadamu pada kali yang lain,'),
  ('id.indonesian', 20, 38, 'yaitu ketika Kami mengilhamkan kepada ibumu suatu yang diilhamkan,'),
  ('id.indonesian', 20, 39, 'Yaitu: "Letakkanlah ia (Musa) didalam peti, kemudian lemparkanlah ia ke sungai (Nil), maka pasti sungai itu membawanya ke tepi, supaya diambil oleh (Fir\'aun) musuh-Ku dan musuhnya. Dan Aku telah melimpahkan kepadamu kasih sayang yang datang dari-Ku; dan supaya kamu diasuh di bawah pengawasan-Ku,'),
  ('id.indonesian', 20, 40, '(yaitu) ketika saudaramu yang perempuan berjalan, lalu ia berkata kepada (keluarga Fir\'aun): "Bolehkah saya menunjukkan kepadamu orang yang akan memeliharanya?" Maka Kami mengembalikanmu kepada ibumu, agar senang hatinya dan tidak berduka cita. Dan kamu pernah membunuh seorang manusia, lalu Kami selamatkan kamu dari kesusahan dan Kami telah mencobamu dengan beberapa cobaan; maka kamu tinggal beberapa tahun diantara penduduk Madyan, kemudian kamu datang menurut waktu yang ditetapkan hai Musa,'),
  ('id.indonesian', 20, 41, 'dan Aku telah memilihmu untuk diri-Ku.'),
  ('id.indonesian', 20, 42, 'Pergilah kamu beserta saudaramu dengan membawa ayat-ayat-Ku, dan janganlah kamu berdua lalai dalam mengingat-Ku;'),
  ('id.indonesian', 20, 43, 'Pergilah kamu berdua kepada Fir\'aun, sesungguhnya dia telah melampaui batas;'),
  ('id.indonesian', 20, 44, 'maka berbicaralah kamu berdua kepadanya dengan kata-kata yang lemah lembut, mudah-mudahan ia ingat atau takut".'),
  ('id.indonesian', 20, 45, 'Berkatalah mereka berdua: "Ya Tuhan kami, sesungguhnya kami khawatir bahwa ia segera menyiksa kami atau akan bertambah melampaui batas".'),
  ('id.indonesian', 20, 46, 'Allah berfirman: "Janganlah kamu berdua khawatir, sesungguhnya Aku beserta kamu berdua, Aku mendengar dan melihat".'),
  ('id.indonesian', 20, 47, 'Maka datanglah kamu berdua kepadanya (Fir\'aun) dan katakanlah: "Sesungguhnya kami berdua adalah utusan Tuhanmu, maka lepaskanlah Bani Israil bersama kami dan janganlah kamu menyiksa mereka. Sesungguhnya kami telah datang kepadamu dengan membawa bukti (atas kerasulan kami) dari Tuhanmu. Dan keselamatan itu dilimpahkan kepada orang yang mengikuti petunjuk.'),
  ('id.indonesian', 20, 48, 'Sesungguhnya telah diwahyukan kepada kami bahwa siksa itu (ditimpakan) atas orang-orang yang mendustakan dan berpaling.'),
  ('id.indonesian', 20, 49, 'Berkata Fir\'aun: "Maka siapakah Tuhanmu berdua, hai Musa?.'),
  ('id.indonesian', 20, 50, 'Musa berkata: "Tuhan kami ialah (Tuhan) yang telah memberikan kepada tiap-tiap sesuatu bentuk kejadiannya, kemudian memberinya petunjuk.'),
  ('id.indonesian', 20, 51, 'Berkata Fir\'aun: "Maka bagaimanakah keadaan umat-umat yang dahulu?"'),
  ('id.indonesian', 20, 52, 'Musa menjawab: "Pengetahuan tentang itu ada di sisi Tuhanku, di dalam sebuah kitab, Tuhan kami tidak akan salah dan tidak (pula) lupa;'),
  ('id.indonesian', 20, 53, 'Yang telah menjadikan bagimu bumi sebagai hamparan dan Yang telah menjadikan bagimu di bumi itu jalan-ja]an, dan menurunkan dari langit air hujan. Maka Kami tumbuhkan dengan air hujan itu berjenis-jenis dari tumbuh-tumbuhan yang bermacam-macam.'),
  ('id.indonesian', 20, 54, 'Makanlah dan gembalakanlah binatang-binatangmu. Sesungguhnya pada yang demikian itu, terdapat tanda-tanda kekuasaan Allah bagi orang-orang yang berakal.'),
  ('id.indonesian', 20, 55, 'Dari bumi (tanah) itulah Kami menjadikan kamu dan kepadanya Kami akan mengembalikan kamu dan daripadanya Kami akan mengeluarkan kamu pada kali yang lain,'),
  ('id.indonesian', 20, 56, 'Dan sesungguhnya Kami telah perlihatkan kepadanya (Fir\'aun) tanda-tanda kekuasaan Kami semuanya maka ia mendustakan dan enggan (menerima kebenaran).'),
  ('id.indonesian', 20, 57, 'Berkata Fir\'aun: "Adakah kamu datang kepada kami untuk mengusir kami dari negeri kami (ini) dengan sihirmu, hai Musa?'),
  ('id.indonesian', 20, 58, 'Dan kamipun pasti akan mendatangkan (pula) kepadamu sihir semacam itu, maka buatlah suatu waktu untuk pertemuan antara kami dan kamu, yang kami tidak akan menyalahinya dan tidak (pula) kamu di suatu tempat yang pertengahan (letaknya).'),
  ('id.indonesian', 20, 59, 'Berkata Musa: "Waktu untuk pertemuan (kami dengan) kamu itu ialah di hari raya dan hendaklah dikumpulkan manusia pada waktu matahari sepenggalahan naik".'),
  ('id.indonesian', 20, 60, 'Maka Fir\'aun meninggalkan (tempat itu), lalu mengatur tipu dayanya, kemudian dia datang.'),
  ('id.indonesian', 20, 61, 'Berkata Musa kepada mereka: "Celakalah kamu, janganlah kamu mengada-adakan kedustaan terhadap Allah, maka Dia membinasakan kamu dengan siksa". Dan sesungguhnya telah merugi orang yang mengada-adakan kedustaan.'),
  ('id.indonesian', 20, 62, 'Maka mereka berbantah-bantahan tentang urusan mereka di antara mereka dan mereka merahasiakan percakapan (mereka).'),
  ('id.indonesian', 20, 63, 'Mereka berkata: "Sesungguhnya dua orang ini adalah benar-benar ahli sihir yang hendak mengusir kamu dari negeri kamu dengan sihirnya dan hendak melenyapkan kedudukan kamu yang utama.'),
  ('id.indonesian', 20, 64, 'Maka himpunkanlah segala daya (sihir) kamu sekalian, kemudian datanglah dengan berbaris. dan sesungguhnya beruntunglah oran yang menang pada hari ini.'),
  ('id.indonesian', 20, 65, '(Setelah mereka berkumpul) mereka berkata: "Hai Musa (pilihlah), apakah kamu yang melemparkan (dahulu) atau kamikah orang yang mula-mula melemparkan?"'),
  ('id.indonesian', 20, 66, 'Berkata Musa: "Silahkan kamu sekalian melemparkan". Maka tiba-tiba tali-tali dan tongkat-tongkat mereka, terbayang kepada Musa seakan-akan ia merayap cepat, lantaran sihir mereka.'),
  ('id.indonesian', 20, 67, 'Maka Musa merasa takut dalam hatinya.'),
  ('id.indonesian', 20, 68, 'Kami berkata: "janganlah kamu takut, sesungguhnya kamulah yang paling unggul (menang).'),
  ('id.indonesian', 20, 69, 'Dan lemparkanlah apa yang ada ditangan kananmu, niscaya ia akan menelan apa yang mereka perbuat. "Sesungguhnya apa yang mereka perbuat itu adalah tipu daya tukang sihir (belaka). Dan tidak akan menang tukang sihir itu, dari mana saja ia datang".'),
  ('id.indonesian', 20, 70, 'Lalu tukang-tukang sihir itu tersungkur dengan bersujud, seraya berkata: "Kami telah percaya kepada Tuhan Harun dan Musa".'),
  ('id.indonesian', 20, 71, 'Berkata Fir\'aun: "Apakah kamu telah beriman kepadanya (Musa) sebelum aku memberi izin kepadamu sekalian. Sesungguhnya ia adalah pemimpinmu yang mengajarkan sihir kepadamu sekalian. Maka sesungguhnya aku akan memotong tangan dan kaki kamu sekalian dengan bersilang secara bertimbal balik, dan sesungguhnya aku akan menyalib kamu sekalian pada pangkal pohon kurma dan sesungguhnya kamu akan mengetahui siapa di antara kita yang lebih pedih dan lebih kekal siksanya".'),
  ('id.indonesian', 20, 72, 'Mereka berkata: "Kami sekali-kali tidak akan mengutamakan kamu daripada bukti-bukti yang nyata (mukjizat), yang telah datang kepada kami dan daripada Tuhan yang telah menciptakan kami; maka putuskanlah apa yang hendak kamu putuskan. Sesungguhnya kamu hanya akan dapat memutuskan pada kehidupan di dunia ini saja.'),
  ('id.indonesian', 20, 73, 'Sesungguhnya kami telah beriman kepada Tuhan kami, agar Dia mengampuni kesalahan-kesalahan kami dan sihir yang telah kamu paksakan kepada kami melakukannya. Dan Allah lebih baik (pahala-Nya) dan lebih kekal (azab-Nya)".'),
  ('id.indonesian', 20, 74, 'Sesungguhnya barangsiapa datang kepada Tuhannya dalam keadaan berdosa, maka sesungguhnya baginya neraka Jahannam. Ia tidak mati di dalamnya dan tidak (pula) hidup.'),
  ('id.indonesian', 20, 75, 'Dan barangsiapa datang kepada Tuhannya dalam keadaan beriman, lagi sungguh-sungguh telah beramal saleh, maka mereka itulah orang-orang yang memperoleh tempat-tempat yang tinggi (mulia),'),
  ('id.indonesian', 20, 76, '(yaitu) surga \'Adn yang mengalir sungai-sungai di bawahnya, mereka kekal di dalamnya. Dan itu adalah balasan bagi orang yang bersih (dari kekafiran dan kemaksiatan).'),
  ('id.indonesian', 20, 77, 'Dan sesungguhnya telah Kami wahyukan kepada Musa: "Pergilah kamu dengan hamba-hamba-Ku (Bani Israil) di malam hari, maka buatlah untuk mereka jalan yang kering dilaut itu, kamu tak usah khawatir akan tersusul dan tidak usah takut (akan tenggelam)".'),
  ('id.indonesian', 20, 78, 'Maka Fir\'aun dengan bala tentaranya mengejar mereka, lalu mereka ditutup oleh laut yang menenggelamkan mereka.'),
  ('id.indonesian', 20, 79, 'Dan Fir\'aun telah menyesatkan kaumnya dan tidak memberi petunjuk.'),
  ('id.indonesian', 20, 80, 'Hai Bani Israil, sesungguhnya Kami telah menyelamatkan kamu sekalian dari musuhmu, dan Kami telah mengadakan perjanjian dengan kamu sekalian (untuk munajat) di sebelah kanan gunung itu dan Kami telah menurunkan kepada kamu sekalian manna dan salwa.'),
  ('id.indonesian', 20, 81, 'Makanlah di antara rezeki yang baik yang telah Kami berikan kepadamu, dan janganlah melampaui batas padanya, yang menyebabkan kemurkaan-Ku menimpamu. Dan barangsiapa ditimpa oleh kemurkaan-Ku, maka sesungguhnya binasalah ia.'),
  ('id.indonesian', 20, 82, 'Dan sesungguhnya Aku Maha Pengampun bagi orang yang bertaubat, beriman, beramal saleh, kemudian tetap di jalan yang benar.'),
  ('id.indonesian', 20, 83, 'Mengapa kamu datang lebih cepat daripada kaummu, hai Musa?'),
  ('id.indonesian', 20, 84, 'Berkata, Musa: "Itulah mereka sedang menyusuli aku dan aku bersegera kepada-Mu. Ya Tuhanku, agar supaya Engkau ridha (kepadaku)".'),
  ('id.indonesian', 20, 85, 'Allah berfirman: "Maka sesungguhnya Kami telah menguji kaummu sesudah kamu tinggalkan, dan mereka telah disesatkan oleh Samiri.'),
  ('id.indonesian', 20, 86, 'Kemudian Musa kembali kepada kaumnya dengan marah dan bersedih hati. Berkata Musa: "Hai kaumku, bukankah Tuhanmu telah menjanjikan kepadamu suatu janji yang baik? Maka apakah terasa lama masa yang berlalu itu bagimu atau kamu menghendaki agar kemurkaan dari Tuhanmu menimpamu, dan kamu melanggar perjanjianmu dengan aku?".'),
  ('id.indonesian', 20, 87, 'Mereka berkata: "Kami sekali-kali tidak melanggar perjanjianmu dengan kemauan kami sendiri, tetapi kami disuruh membawa beban-beban dari perhiasan kaum itu, maka kami telah melemparkannya, dan demikian pula Samiri melemparkannya",'),
  ('id.indonesian', 20, 88, 'kemudian Samiri mengeluarkan untuk mereka (dari lobang itu) anak lembu yang bertubuh dan bersuara, maka mereka berkata: "Inilah Tuhanmu dan Tuhan Musa, tetapi Musa telah lupa".'),
  ('id.indonesian', 20, 89, 'Maka apakah mereka tidak memperhatikan bahwa patung anak lembu itu tidak dapat memberi jawaban kepada mereka, dan tidak dapat memberi kemudharatan kepada mereka dan tidak (pula) kemanfaatan?'),
  ('id.indonesian', 20, 90, 'Dan sesungguhnya Harun telah berkata kepada mereka sebelumnya: "Hai kaumku, sesungguhnya kamu hanya diberi cobaan dengan anak lembu. itu dan sesungguhnya Tuhanmu ialah (Tuhan) Yang Maha Pemurah, maka ikutilah aku dan taatilah perintahku".'),
  ('id.indonesian', 20, 91, 'Mereka menjawab: "Kami akan tetap menyembah patung anak lembu ini, hingga Musa kembali kepada kami".'),
  ('id.indonesian', 20, 92, 'Berkata Musa: "Hai Harun, apa yang menghalangi kamu ketika kamu melihat mereka telah sesat,'),
  ('id.indonesian', 20, 93, '(sehingga) kamu tidak mengikuti aku? Maka apakah kamu telah (sengaja) mendurhakai perintahku?"'),
  ('id.indonesian', 20, 94, 'Harun menjawab\' "Hai putera ibuku, janganlah kamu pegang janggutku dan jangan (pula) kepalaku; sesungguhnya aku khawatir bahwa kamu akan berkata (kepadaku): "Kamu telah memecah antara Bani Israil dan kamu tidak memelihara amanatku".'),
  ('id.indonesian', 20, 95, 'Berkata Musa: "Apakah yang mendorongmu (berbuat demikian) hai Samiri?"'),
  ('id.indonesian', 20, 96, 'Samiri menjawab: "Aku mengetahui sesuatu yang mereka tidak mengetahuinya, maka aku ambil segenggam dari jejak rasul lalu aku melemparkannya, dan demikianlah nafsuku membujukku".'),
  ('id.indonesian', 20, 97, 'Berkata Musa: "Pergilah kamu, maka sesungguhnya bagimu di dalam kehidupan di dunia ini (hanya dapat) mengatakan: "Janganlah menyentuh (aku)". Dan sesungguhnya bagimu hukuman (di akhirat) yang kamu sekali-kali tidak dapat menghindarinya, dan lihatlah tuhanmu itu yang kamu tetap menyembahnya. Sesungguhnya kami akan membakarnya, kemudian kami sungguh-sungguh akan menghamburkannya ke dalam laut (berupa abu yang berserakan).'),
  ('id.indonesian', 20, 98, 'Sesungguhnya Tuhanmu hanyalah Allah, yang tidak ada Tuhan selain Dia. Pengetahuan-Nya meliputi segala sesuatu".'),
  ('id.indonesian', 20, 99, 'Demikianlah kami kisahkan kepadamu (Muhammad) sebagian kisah umat yang telah lalu, dan sesungguhnya telah Kami berikan kepadamu dari sisi Kami suatu peringatan (Al Quran).'),
  ('id.indonesian', 20, 100, 'Barangsiapa berpaling dari pada Al qur\'an maka sesungguhnya ia akan memikul dosa yang besar di hari kiamat,'),
  ('id.indonesian', 20, 101, 'mereka kekal di dalam keadaan itu. Dan amat buruklah dosa itu sebagai beban bagi mereka di hari kiamat,'),
  ('id.indonesian', 20, 102, '(yaitu) di hari (yang di waktu itu) ditiup sangkakala dan Kami akan mengumpulkan pada hari itu orang-orang yang berdosa dengan muka yang biru muram;'),
  ('id.indonesian', 20, 103, 'mereka berbisik-bisik di antara mereka: "Kamu tidak berdiam (di dunia) melainkan hanyalah sepuluh (hari)"'),
  ('id.indonesian', 20, 104, 'Kami lebih mengetahui apa yang mereka katakan, ketika berkata orang yang paling lurus jalannya di antara mereka: "Kamu tidak berdiam (di dunia), melainkan hanyalah sehari saja".'),
  ('id.indonesian', 20, 105, 'Dan mereka bertanya kepadamu tentang gunung-gunung, maka katakanlah: "Tuhanku akan menghancurkannya (di hari kiamat) sehancur-hancurnya,'),
  ('id.indonesian', 20, 106, 'maka Dia akan menjadikan (bekas) gunung-gunung itu datar sama sekali,'),
  ('id.indonesian', 20, 107, 'tidak ada sedikitpun kamu lihat padanya tempat yang rendah dan yang tinggi-tinggi.'),
  ('id.indonesian', 20, 108, 'Pada hari itu manusia mengikuti (menuju kepada suara) penyeru dengan tidak berbelok-belok; dan merendahlah semua suara kepada Tuhan Yang Maha Pemurah, maka kamu tidak mendengar kecuali bisikan saja.'),
  ('id.indonesian', 20, 109, 'Pada hari itu tidak berguna syafa\'at, kecuali (syafa\'at) orang yang Allah Maha Pemurah telah memberi izin kepadanya, dan Dia telah meridhai perkataannya.'),
  ('id.indonesian', 20, 110, 'Dia mengetahui apa yang ada di hadapan mereka dan apa yang ada di belakang mereka, sedang ilmu mereka tidak dapat meliputi ilmu-Nya.'),
  ('id.indonesian', 20, 111, 'Dan tunduklah semua muka (dengan berendah diri) kepada Tuhan Yang Hidup Kekal lagi senantiasa mengurus (makhluk-Nya). Dan sesungguhnya telah merugilah orang yang melakukan kezaliman.'),
  ('id.indonesian', 20, 112, 'Dan barangsiapa mengerjakan amal-amal yang saleh dan ia dalam keadaan beriman, maka ia tidak khawatir akan perlakuan yang tidak adil (terhadapnya) dan tidak (pula) akan pengurangan haknya.'),
  ('id.indonesian', 20, 113, 'Dan demikianlah Kami menurunkan Al Quran dalam bahasa Arab, dan Kami telah menerangkan dengan berulang kali, di dalamnya sebahagian dari ancaman, agar mereka bertakwa atau (agar) Al Quran itu menimbulkan pengajaran bagi mereka.'),
  ('id.indonesian', 20, 114, 'Maka Maha Tinggi Allah Raja Yang sebenar-benarnya, dan janganlah kamu tergesa-gesa membaca Al qur\'an sebelum disempurnakan mewahyukannya kepadamu, dan katakanlah: "Ya Tuhanku, tambahkanlah kepadaku ilmu pengetahuan".'),
  ('id.indonesian', 20, 115, 'Dan sesungguhnya telah Kami perintahkan kepada Adam dahulu, maka ia lupa (akan perintah itu), dan tidak Kami dapati padanya kemauan yang kuat.'),
  ('id.indonesian', 20, 116, 'Dan (ingatlah) ketika Kami berkata kepada malaikat: "Sujudlah kamu kepada Adam", maka mereka sujud kecuali iblis. Ia membangkang.'),
  ('id.indonesian', 20, 117, 'Maka Kami berkata: "Hai Adam, sesungguhnya ini (iblis) adalah musuh bagimu dan bagi isterimu, maka sekali-kali janganlah sampai ia mengeluarkan kamu berdua dari surga, yang menyebabkan kamu menjadi celaka.'),
  ('id.indonesian', 20, 118, 'Sesungguhnya kamu tidak akan kelaparan di dalamnya dan tidak akan telanjang,'),
  ('id.indonesian', 20, 119, 'dan sesungguhnya kamu tidak akan merasa dahaga dan tidak (pula) akan ditimpa panas matahari di dalamnya".'),
  ('id.indonesian', 20, 120, 'Kemudian syaitan membisikkan pikiran jahat kepadanya, dengan berkata: "Hai Adam, maukah saya tunjukkan kepada kamu pohon khuldi dan kerajaan yang tidak akan binasa?"'),
  ('id.indonesian', 20, 121, 'Maka keduanya memakan dari buah pohon itu, lalu nampaklah bagi keduanya aurat-auratnya dan mulailah keduanya menutupinya dengan daun-daun (yang ada di) surga, dan durhakalah Adam kepada Tuhan dan sesatlah ia.'),
  ('id.indonesian', 20, 122, 'Kemudian Tuhannya memilihnya maka Dia menerima taubatnya dan memberinya petunjuk.'),
  ('id.indonesian', 20, 123, 'Allah berfirman: "Turunlah kamu berdua dari surga bersama-sama, sebagian kamu menjadi musuh bagi sebagian yang lain. Maka jika datang kepadamu petunjuk daripada-Ku, lalu barangsiapa yang mengikut petunjuk-Ku, ia tidak akan sesat dan tidak akan celaka.'),
  ('id.indonesian', 20, 124, 'Dan barangsiapa berpaling dari peringatan-Ku, maka sesungguhnya baginya penghidupan yang sempit, dan Kami akan menghimpunkannya pada hari kiamat dalam keadaan buta".'),
  ('id.indonesian', 20, 125, 'Berkatalah ia: "Ya Tuhanku, mengapa Engkau menghimpunkan aku dalam keadaan buta, padahal aku dahulunya adalah seorang yang melihat?"'),
  ('id.indonesian', 20, 126, 'Allah berfirman: "Demikianlah, telah datang kepadamu ayat-ayat Kami, maka kamu melupakannya, dan begitu (pula) pada hari ini kamupun dilupakan".'),
  ('id.indonesian', 20, 127, 'Dan demikianlah Kami membalas orang yang melampaui batas dan tidak percaya kepada ayat-ayat Tuhannya. Dan sesungguhnya azab di akhirat itu lebih berat dan lebih kekal.'),
  ('id.indonesian', 20, 128, 'Maka tidakkah menjadi petunjuk bagi mereka (kaum musyrikin) berapa banyaknya Kami membinasakan umat-umat sebelum mereka, padahal mereka berjalan (di bekas-bekas) tempat tinggal umat-umat itu? Sesungguhnya pada yang demikian itu terdapat tanda-tanda bagi orang yang berakal.'),
  ('id.indonesian', 20, 129, 'Dan sekiranya tidak ada suatu ketetapan dari Allah yang telah terdahulu atau tidak ada ajal yang telah ditentukan, pasti (azab itu) menimpa mereka.'),
  ('id.indonesian', 20, 130, 'Maka sabarlah kamu atas apa yang mereka katakan, dan bertasbihlah dengan memuji Tuhanmu, sebelum terbit matahari dan sebelum terbenamnya dan bertasbih pulalah pada waktu-waktu di malam hari dan pada waktu-waktu di siang hari, supaya kamu merasa senang,'),
  ('id.indonesian', 20, 131, 'Dan janganlah kamu tujukan kedua matamu kepada apa yang telah Kami berikan kepada golongan-golongan dari mereka, sebagai bunga kehidupan dunia untuk Kami cobai mereka dengannya. Dan karunia Tuhan kamu adalah lebih baik dan lebih kekal.'),
  ('id.indonesian', 20, 132, 'Dan perintahkanlah kepada keluargamu mendirikan shalat dan bersabarlah kamu dalam mengerjakannya. Kami tidak meminta rezeki kepadamu, Kamilah yang memberi rezeki kepadamu. Dan akibat (yang baik) itu adalah bagi orang yang bertakwa.'),
  ('id.indonesian', 20, 133, 'Dan mereka berkata: "Mengapa ia tidak membawa bukti kepada kami dari Tuhannya?" Dan apakah belum datang kepada mereka bukti yang nyata dari apa yang tersebut di dalam kitab-kitab yang dahulu?'),
  ('id.indonesian', 20, 134, 'Dan sekiranya Kami binasakan mereka dengan suatu azab sebelum Al Quran itu (diturunkan), tentulah mereka berkata: "Ya Tuhan kami, mengapa tidak Engkau utus seorang rasul kepada kami, lalu kami mengikuti ayat-ayat Engkau sebelum kami menjadi hina dan rendah?"'),
  ('id.indonesian', 20, 135, 'Katakanlah: "Masing-masing (kita) menanti, maka nantikanlah oleh kamu sekalian! Maka kamu kelak akan mengetahui, siapa yang menempuh jalan yang lurus dan siapa yang telah mendapat petunjuk".')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 21, 1, '[The time of] their account has approached for the people, while they are in heedlessness turning away.'),
  ('en.sahih', 21, 2, 'No mention comes to them anew from their Lord except that they listen to it while they are at play'),
  ('en.sahih', 21, 3, 'With their hearts distracted. And those who do wrong conceal their private conversation, [saying], "Is this [Prophet] except a human being like you? So would you approach magic while you are aware [of it]?"'),
  ('en.sahih', 21, 4, 'The Prophet said, "My Lord knows whatever is said throughout the heaven and earth, and He is the Hearing, the Knowing."'),
  ('en.sahih', 21, 5, 'But they say, "[The revelation is but] a mixture of false dreams; rather, he has invented it; rather, he is a poet. So let him bring us a sign just as the previous [messengers] were sent [with miracles]."'),
  ('en.sahih', 21, 6, 'Not a [single] city which We destroyed believed before them, so will they believe?'),
  ('en.sahih', 21, 7, 'And We sent not before you, [O Muhammad], except men to whom We revealed [the message], so ask the people of the message if you do not know.'),
  ('en.sahih', 21, 8, 'And We did not make the prophets forms not eating food, nor were they immortal [on earth].'),
  ('en.sahih', 21, 9, 'Then We fulfilled for them the promise, and We saved them and whom We willed and destroyed the transgressors.'),
  ('en.sahih', 21, 10, 'We have certainly sent down to you a Book in which is your mention. Then will you not reason?'),
  ('en.sahih', 21, 11, 'And how many a city which was unjust have We shattered and produced after it another people.'),
  ('en.sahih', 21, 12, 'And when its inhabitants perceived Our punishment, at once they fled from it.'),
  ('en.sahih', 21, 13, '[Some angels said], "Do not flee but return to where you were given luxury and to your homes - perhaps you will be questioned."'),
  ('en.sahih', 21, 14, 'They said, "O woe to us! Indeed, we were wrongdoers."'),
  ('en.sahih', 21, 15, 'And that declaration of theirs did not cease until We made them [as] a harvest [mowed down], extinguished [like a fire].'),
  ('en.sahih', 21, 16, 'And We did not create the heaven and earth and that between them in play.'),
  ('en.sahih', 21, 17, 'Had We intended to take a diversion, We could have taken it from [what is] with Us - if [indeed] We were to do so.'),
  ('en.sahih', 21, 18, 'Rather, We dash the truth upon falsehood, and it destroys it, and thereupon it departs. And for you is destruction from that which you describe.'),
  ('en.sahih', 21, 19, 'To Him belongs whoever is in the heavens and the earth. And those near Him are not prevented by arrogance from His worship, nor do they tire.'),
  ('en.sahih', 21, 20, 'They exalt [Him] night and day [and] do not slacken.'),
  ('en.sahih', 21, 21, 'Or have men taken for themselves gods from the earth who resurrect [the dead]?'),
  ('en.sahih', 21, 22, 'Had there been within the heavens and earth gods besides Allah, they both would have been ruined. So exalted is Allah, Lord of the Throne, above what they describe.'),
  ('en.sahih', 21, 23, 'He is not questioned about what He does, but they will be questioned.'),
  ('en.sahih', 21, 24, 'Or have they taken gods besides Him? Say, [O Muhammad], "Produce your proof. This [Qur\'an] is the message for those with me and the message of those before me." But most of them do not know the truth, so they are turning away.'),
  ('en.sahih', 21, 25, 'And We sent not before you any messenger except that We revealed to him that, "There is no deity except Me, so worship Me."'),
  ('en.sahih', 21, 26, 'And they say, "The Most Merciful has taken a son." Exalted is He! Rather, they are [but] honored servants.'),
  ('en.sahih', 21, 27, 'They cannot precede Him in word, and they act by His command.'),
  ('en.sahih', 21, 28, 'He knows what is [presently] before them and what will be after them, and they cannot intercede except on behalf of one whom He approves. And they, from fear of Him, are apprehensive.'),
  ('en.sahih', 21, 29, 'And whoever of them should say, "Indeed, I am a god besides Him"- that one We would recompense with Hell. Thus do We recompense the wrongdoers.'),
  ('en.sahih', 21, 30, 'Have those who disbelieved not considered that the heavens and the earth were a joined entity, and We separated them and made from water every living thing? Then will they not believe?'),
  ('en.sahih', 21, 31, 'And We placed within the earth firmly set mountains, lest it should shift with them, and We made therein [mountain] passes [as] roads that they might be guided.'),
  ('en.sahih', 21, 32, 'And We made the sky a protected ceiling, but they, from its signs, are turning away.'),
  ('en.sahih', 21, 33, 'And it is He who created the night and the day and the sun and the moon; all [heavenly bodies] in an orbit are swimming.'),
  ('en.sahih', 21, 34, 'And We did not grant to any man before you eternity [on earth]; so if you die - would they be eternal?'),
  ('en.sahih', 21, 35, 'Every soul will taste death. And We test you with evil and with good as trial; and to Us you will be returned.'),
  ('en.sahih', 21, 36, 'And when those who disbelieve see you, [O Muhammad], they take you not except in ridicule, [saying], "Is this the one who insults your gods?" And they are, at the mention of the Most Merciful, disbelievers.'),
  ('en.sahih', 21, 37, 'Man was created of haste. I will show you My signs, so do not impatiently urge Me.'),
  ('en.sahih', 21, 38, 'And they say, "When is this promise, if you should be truthful?"'),
  ('en.sahih', 21, 39, 'If those who disbelieved but knew the time when they will not avert the Fire from their faces or from their backs and they will not be aided...'),
  ('en.sahih', 21, 40, 'Rather, it will come to them unexpectedly and bewilder them, and they will not be able to repel it, nor will they be reprieved.'),
  ('en.sahih', 21, 41, 'And already were messengers ridiculed before you, but those who mocked them were enveloped by what they used to ridicule.'),
  ('en.sahih', 21, 42, 'Say, "Who can protect you at night or by day from the Most Merciful?" But they are, from the remembrance of their Lord, turning away.'),
  ('en.sahih', 21, 43, 'Or do they have gods to defend them other than Us? They are unable [even] to help themselves, nor can they be protected from Us.'),
  ('en.sahih', 21, 44, 'But, [on the contrary], We have provided good things for these [disbelievers] and their fathers until life was prolonged for them. Then do they not see that We set upon the land, reducing it from its borders? So it is they who will overcome?'),
  ('en.sahih', 21, 45, 'Say, "I only warn you by revelation." But the deaf do not hear the call when they are warned.'),
  ('en.sahih', 21, 46, 'And if [as much as] a whiff of the punishment of your Lord should touch them, they would surely say, "O woe to us! Indeed, we have been wrongdoers."'),
  ('en.sahih', 21, 47, 'And We place the scales of justice for the Day of Resurrection, so no soul will be treated unjustly at all. And if there is [even] the weight of a mustard seed, We will bring it forth. And sufficient are We as accountant.'),
  ('en.sahih', 21, 48, 'And We had already given Moses and Aaron the criterion and a light and a reminder for the righteous'),
  ('en.sahih', 21, 49, 'Who fear their Lord unseen, while they are of the Hour apprehensive.'),
  ('en.sahih', 21, 50, 'And this [Qur\'an] is a blessed message which We have sent down. Then are you with it unacquainted?'),
  ('en.sahih', 21, 51, 'And We had certainly given Abraham his sound judgement before, and We were of him well-Knowing'),
  ('en.sahih', 21, 52, 'When he said to his father and his people, "What are these statues to which you are devoted?"'),
  ('en.sahih', 21, 53, 'They said, "We found our fathers worshippers of them."'),
  ('en.sahih', 21, 54, 'He said, "You were certainly, you and your fathers, in manifest error."'),
  ('en.sahih', 21, 55, 'They said, "Have you come to us with truth, or are you of those who jest?"'),
  ('en.sahih', 21, 56, 'He said, "[No], rather, your Lord is the Lord of the heavens and the earth who created them, and I, to that, am of those who testify.'),
  ('en.sahih', 21, 57, 'And [I swear] by Allah, I will surely plan against your idols after you have turned and gone away."'),
  ('en.sahih', 21, 58, 'So he made them into fragments, except a large one among them, that they might return to it [and question].'),
  ('en.sahih', 21, 59, 'They said, "Who has done this to our gods? Indeed, he is of the wrongdoers."'),
  ('en.sahih', 21, 60, 'They said, "We heard a young man mention them who is called Abraham."'),
  ('en.sahih', 21, 61, 'They said, "Then bring him before the eyes of the people that they may testify."'),
  ('en.sahih', 21, 62, 'They said, "Have you done this to our gods, O Abraham?"'),
  ('en.sahih', 21, 63, 'He said, "Rather, this - the largest of them - did it, so ask them, if they should [be able to] speak."'),
  ('en.sahih', 21, 64, 'So they returned to [blaming] themselves and said [to each other], "Indeed, you are the wrongdoers."'),
  ('en.sahih', 21, 65, 'Then they reversed themselves, [saying], "You have already known that these do not speak!"'),
  ('en.sahih', 21, 66, 'He said, "Then do you worship instead of Allah that which does not benefit you at all or harm you?'),
  ('en.sahih', 21, 67, 'Uff to you and to what you worship instead of Allah. Then will you not use reason?"'),
  ('en.sahih', 21, 68, 'They said, "Burn him and support your gods - if you are to act."'),
  ('en.sahih', 21, 69, 'Allah said, "O fire, be coolness and safety upon Abraham."'),
  ('en.sahih', 21, 70, 'And they intended for him harm, but We made them the greatest losers.'),
  ('en.sahih', 21, 71, 'And We delivered him and Lot to the land which We had blessed for the worlds.'),
  ('en.sahih', 21, 72, 'And We gave him Isaac and Jacob in addition, and all [of them] We made righteous.'),
  ('en.sahih', 21, 73, 'And We made them leaders guiding by Our command. And We inspired to them the doing of good deeds, establishment of prayer, and giving of zakah; and they were worshippers of Us.'),
  ('en.sahih', 21, 74, 'And to Lot We gave judgement and knowledge, and We saved him from the city that was committing wicked deeds. Indeed, they were a people of evil, defiantly disobedient.'),
  ('en.sahih', 21, 75, 'And We admitted him into Our mercy. Indeed, he was of the righteous.'),
  ('en.sahih', 21, 76, 'And [mention] Noah, when he called [to Allah] before [that time], so We responded to him and saved him and his family from the great flood.'),
  ('en.sahih', 21, 77, 'And We saved him from the people who denied Our signs. Indeed, they were a people of evil, so We drowned them, all together.'),
  ('en.sahih', 21, 78, 'And [mention] David and Solomon, when they judged concerning the field - when the sheep of a people overran it [at night], and We were witness to their judgement.'),
  ('en.sahih', 21, 79, 'And We gave understanding of the case to Solomon, and to each [of them] We gave judgement and knowledge. And We subjected the mountains to exalt [Us], along with David and [also] the birds. And We were doing [that].'),
  ('en.sahih', 21, 80, 'And We taught him the fashioning of coats of armor to protect you from your [enemy in] battle. So will you then be grateful?'),
  ('en.sahih', 21, 81, 'And to Solomon [We subjected] the wind, blowing forcefully, proceeding by his command toward the land which We had blessed. And We are ever, of all things, Knowing.'),
  ('en.sahih', 21, 82, 'And of the devils were those who dived for him and did work other than that. And We were of them a guardian.'),
  ('en.sahih', 21, 83, 'And [mention] Job, when he called to his Lord, "Indeed, adversity has touched me, and you are the Most Merciful of the merciful."'),
  ('en.sahih', 21, 84, 'So We responded to him and removed what afflicted him of adversity. And We gave him [back] his family and the like thereof with them as mercy from Us and a reminder for the worshippers [of Allah].'),
  ('en.sahih', 21, 85, 'And [mention] Ishmael and Idrees and Dhul-Kifl; all were of the patient.'),
  ('en.sahih', 21, 86, 'And We admitted them into Our mercy. Indeed, they were of the righteous.'),
  ('en.sahih', 21, 87, 'And [mention] the man of the fish, when he went off in anger and thought that We would not decree [anything] upon him. And he called out within the darknesses, "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers."'),
  ('en.sahih', 21, 88, 'So We responded to him and saved him from the distress. And thus do We save the believers.'),
  ('en.sahih', 21, 89, 'And [mention] Zechariah, when he called to his Lord, "My Lord, do not leave me alone [with no heir], while you are the best of inheritors."'),
  ('en.sahih', 21, 90, 'So We responded to him, and We gave to him John, and amended for him his wife. Indeed, they used to hasten to good deeds and supplicate Us in hope and fear, and they were to Us humbly submissive.'),
  ('en.sahih', 21, 91, 'And [mention] the one who guarded her chastity, so We blew into her [garment] through Our angel [Gabriel], and We made her and her son a sign for the worlds.'),
  ('en.sahih', 21, 92, 'Indeed this, your religion, is one religion, and I am your Lord, so worship Me.'),
  ('en.sahih', 21, 93, 'And [yet] they divided their affair among themselves, [but] all to Us will return.'),
  ('en.sahih', 21, 94, 'So whoever does righteous deeds while he is a believer - no denial will there be for his effort, and indeed We, of it, are recorders.'),
  ('en.sahih', 21, 95, 'And there is prohibition upon [the people of] a city which We have destroyed that they will [ever] return'),
  ('en.sahih', 21, 96, 'Until when [the dam of] Gog and Magog has been opened and they, from every elevation, descend'),
  ('en.sahih', 21, 97, 'And [when] the true promise has approached; then suddenly the eyes of those who disbelieved will be staring [in horror, while they say], "O woe to us; we had been unmindful of this; rather, we were wrongdoers."'),
  ('en.sahih', 21, 98, 'Indeed, you [disbelievers] and what you worship other than Allah are the firewood of Hell. You will be coming to [enter] it.'),
  ('en.sahih', 21, 99, 'Had these [false deities] been [actual] gods, they would not have come to it, but all are eternal therein.'),
  ('en.sahih', 21, 100, 'For them therein is heavy sighing, and they therein will not hear.'),
  ('en.sahih', 21, 101, 'Indeed, those for whom the best [reward] has preceded from Us - they are from it far removed.'),
  ('en.sahih', 21, 102, 'They will not hear its sound, while they are, in that which their souls desire, abiding eternally.'),
  ('en.sahih', 21, 103, 'They will not be grieved by the greatest terror, and the angels will meet them, [saying], "This is your Day which you have been promised" -'),
  ('en.sahih', 21, 104, 'The Day when We will fold the heaven like the folding of a [written] sheet for the records. As We began the first creation, We will repeat it. [That is] a promise binding upon Us. Indeed, We will do it.'),
  ('en.sahih', 21, 105, 'And We have already written in the book [of Psalms] after the [previous] mention that the land [of Paradise] is inherited by My righteous servants.'),
  ('en.sahih', 21, 106, 'Indeed, in this [Qur\'an] is notification for a worshipping people.'),
  ('en.sahih', 21, 107, 'And We have not sent you, [O Muhammad], except as a mercy to the worlds.'),
  ('en.sahih', 21, 108, 'Say, "It is only revealed to me that your god is but one God; so will you be Muslims [in submission to Him]?"'),
  ('en.sahih', 21, 109, 'But if they turn away, then say, "I have announced to [all of] you equally. And I know not whether near or far is that which you are promised.'),
  ('en.sahih', 21, 110, 'Indeed, He knows what is declared of speech, and He knows what you conceal.'),
  ('en.sahih', 21, 111, 'And I know not; perhaps it is a trial for you and enjoyment for a time."'),
  ('en.sahih', 21, 112, '[The Prophet] has said, "My Lord, judge [between us] in truth. And our Lord is the Most Merciful, the one whose help is sought against that which you describe."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 21, 1, 'মানুষের হিসাব-কিতাবের সময় নিকটবর্তী; অথচ তারা বেখবর হয়ে মুখ ফিরিয়ে নিচ্ছে।'),
  ('bn.bengali', 21, 2, 'তাদের কাছে তাদের পালনকর্তার পক্ষ থেকে যখনই কোন নতুন উপদেশ আসে, তারা তা খেলার ছলে শ্রবণ করে।'),
  ('bn.bengali', 21, 3, 'তাদের অন্তর থাকে খেলায় মত্ত। জালেমরা গোপনে পরামর্শ করে, সে তো তোমাদেরই মত একজন মানুষ; এমতাবস্থায় দেখে শুনে তোমরা তার যাদুর কবলে কেন পড়?'),
  ('bn.bengali', 21, 4, 'পয়গম্বর বললেনঃ নভোমন্ডল ও ভুমন্ডলের কথাই আমার পালনকর্তা জানেন। তিনি সবকিছু শোনেন, সবকিছু জানেন।'),
  ('bn.bengali', 21, 5, 'এছাড়া তারা আরও বলেঃ অলীক স্বপ্ন; না সে মিথ্যা উদ্ভাবন করেছে, না সে একজন কবি। অতএব সে আমাদের কাছে কোন নিদর্শন আনয়ন করুক, যেমন নিদর্শন সহ আগমন করেছিলেন পূর্ববর্তীগন।'),
  ('bn.bengali', 21, 6, 'তাদের পূর্বে যেসব জনপদ আমি ধবংস করে দিয়েছি, তারা বিশ্বাস স্থাপন করেনি; এখন এরা কি বিশ্বাস স্থাপন করবে?'),
  ('bn.bengali', 21, 7, 'আপনার পূর্বে আমি মানুষই প্রেরণ করেছি, যাদের কাছে আমি ওহী পাঠাতাম। অতএব তোমরা যদি না জান তবে যারা স্মরণ রাখে তাদেরকে জিজ্ঞেস কর।'),
  ('bn.bengali', 21, 8, 'আমি তাদেরকে এমন দেহ বিশিষ্ট করিনি যে, তারা খাদ্য ভক্ষণ করত না এবং তারা চিরস্থায়ীও ছিল না।'),
  ('bn.bengali', 21, 9, 'অতঃপর আমি তাদেরকে দেয়া আমার প্রতিশ্রুতি পূর্ণ করলাম সুতরাং তাদেরকে এবং যাদেরকে ইচ্ছা বাঁচিয়ে দিলাম এবং ধবংস করে ছিলাম সীমালঙ্ঘনকারীদেরকে।'),
  ('bn.bengali', 21, 10, 'আমি তোমাদের প্রতি একটি কিতাব অবর্তীর্ণ করেছি; এতে তোমাদের জন্যে উপদেশ রয়েছে। তোমরা কি বোঝ না?'),
  ('bn.bengali', 21, 11, 'আমি কত জনপদের ধ্বংস সাধন করেছি যার অধিবাসীরা ছিল পাপী এবং তাদের পর সৃষ্টি করেছি অন্য জাতি।'),
  ('bn.bengali', 21, 12, 'অতঃপর যখন তারা আমার আযাবের কথা টের পেল, তখনই তারা সেখান থেকে পলায়ন করতে লাগল।'),
  ('bn.bengali', 21, 13, 'পলায়ন করো না এবং ফিরে এস, যেখানে তোমরা বিলাসিতায় মত্ত ছিলে ও তোমাদের আবাসগৃহে; সম্ভবত; কেউ তোমাদের জিজ্ঞেস করবে।'),
  ('bn.bengali', 21, 14, 'তারা বললঃ হায়, দুর্ভোগ আমাদের, আমরা অবশ্যই পাপী ছিলাম।'),
  ('bn.bengali', 21, 15, 'তাদের এই আর্তনাদ সব সময় ছিল, শেষ পর্যন্ত আমি তাদেরকে করে দিলাম যেন কর্তিত শস্য ও নির্বাপিত অগ্নি।'),
  ('bn.bengali', 21, 16, 'আকাশ পৃথিবী এতদুভয়ের মধ্যে যা আছে, তা আমি ক্রীড়াচ্ছলে সৃষ্টি করিনি।'),
  ('bn.bengali', 21, 17, 'আমি যদি ক্রীড়া উপকরণ সৃষ্টি করতে চাইতাম, তবে আমি আমার কাছে যা আছে তা দ্বারাই তা করতাম, যদি আমাকে করতে হত।'),
  ('bn.bengali', 21, 18, 'বরং আমি সত্যকে মিথ্যার উপর নিক্ষেপ করি, অতঃপর সত্য মিথ্যার মস্তক চুর্ণ-বিচূর্ণ করে দেয়, অতঃপর মিথ্যা তৎক্ষণাৎ নিশ্চিহ্ন হয়ে যায়। তোমরা যা বলছ, তার জন্যে তোমাদের দুর্ভোগ।'),
  ('bn.bengali', 21, 19, 'নভোমন্ডল ও ভুমন্ডলে যারা আছে, তারা তাঁরই। আর যারা তাঁর সান্নিধ্যে আছে তারা তাঁর ইবাদতে অহংকার করে না এবং অলসতাও করে না।'),
  ('bn.bengali', 21, 20, 'তারা রাত্রিদিন তাঁর পবিত্রতা ও মহিমা বর্ণনা করে এবং ক্লান্ত হয় না।'),
  ('bn.bengali', 21, 21, 'তারা কি মৃত্তিকা দ্বারা তৈরী উপাস্য গ্রহণ করেছে, যে তারা তাদেরকে জীবিত করবে?'),
  ('bn.bengali', 21, 22, 'যদি নভোমন্ডল ও ভুমন্ডলে আল্লাহ ব্যতীত অন্যান্য উপাস্য থাকত, তবে উভয়ের ধ্বংস হয়ে যেত। অতএব তারা যা বলে, তা থেকে আরশের অধিপতি আল্লাহ পবিত্র।'),
  ('bn.bengali', 21, 23, 'তিনি যা করেন, তৎসম্পর্কে তিনি জিজ্ঞাসিত হবেন না এবং তাদেরকে জিজ্ঞেস করা হবে।'),
  ('bn.bengali', 21, 24, 'তারা কি আল্লাহ ব্যতীত অন্যান্য উপাস্য গ্রহণ করেছে? বলুন, তোমরা তোমাদের প্রমাণ আন। এটাই আমার সঙ্গীদের কথা এবং এটাই আমার পুর্ববর্তীদের কথা। বরং তাদের অধিকাংশই সত্য জানে না; অতএব তারা টালবাহানা করে।'),
  ('bn.bengali', 21, 25, 'আপনার পূর্বে আমি যে রাসূলই প্রেরণ করেছি, তাকে এ আদেশই প্রেরণ করেছি যে, আমি ব্যতীত অন্য কোন উপাস্য নেই। সুতরাং আমারই এবাদত কর।'),
  ('bn.bengali', 21, 26, 'তারা বললঃ দয়াময় আল্লাহ সন্তান গ্রহণ করেছে। তাঁর জন্য কখনও ইহা যোগ্য নয়; বরং তারা তো তাঁর সম্মানিত বান্দা।'),
  ('bn.bengali', 21, 27, 'তারা আগে বেড়ে কথা বলতে পারে না এবং তারা তাঁর আদেশেই কাজ করে।'),
  ('bn.bengali', 21, 28, 'তাদের সম্মুখে ও পশ্চাতে যা আছে, তা তিনি জানেন। তারা শুধু তাদের জন্যে সুপারিশ করে, যাদের প্রতি আল্লাহ সন্তুষ্ট এবং তারা তাঁর ভয়ে ভীত।'),
  ('bn.bengali', 21, 29, 'তাদের মধ্যে যে বলে যে, তিনি ব্যতীত আমিই উপাস্য, তাকে আমি জাহান্নামের শাস্তি দেব। আমি জালেমদেরকে এভাবেই প্রতিফল দিয়ে থাকি।'),
  ('bn.bengali', 21, 30, 'কাফেররা কি ভেবে দেখে না যে, আকাশমন্ডলী ও পৃথিবীর মুখ বন্ধ ছিল, অতঃপর আমি উভয়কে খুলে দিলাম এবং প্রাণবন্ত সবকিছু আমি পানি থেকে সৃষ্টি করলাম। এরপরও কি তারা বিশ্বাস স্থাপন করবে না?'),
  ('bn.bengali', 21, 31, 'আমি পৃথিবীতে ভারী বোঝা রেখে দিয়েছি যাতে তাদেরকে নিয়ে পৃথিবী ঝুঁকে না পড়ে এবং তাতে প্রশস্ত পথ রেখেছি, যাতে তারা পথ প্রাপ্ত হয়।'),
  ('bn.bengali', 21, 32, 'আমি আকাশকে সুরক্ষিত ছাদ করেছি; অথচ তারা আমার আকাশস্থ নিদর্শনাবলী থেকে মুখ ফিরিয়ে রাখে।'),
  ('bn.bengali', 21, 33, 'তিনিই সৃষ্টি করেছেন রাত্রি ও দিন এবং সূর্য ও চন্দ্র। সবাই আপন আপন কক্ষপথে বিচরণ করে।'),
  ('bn.bengali', 21, 34, 'আপনার পূর্বেও কোন মানুষকে আমি অনন্ত জীবন দান করিনি। সুতরাং আপনার মৃত্যু হলে তারা কি চিরঞ্জীব হবে?'),
  ('bn.bengali', 21, 35, 'প্রত্যেককে মৃত্যুর স্বাদ আস্বাদন করতে হবে। আমি তোমাদেরকে মন্দ ও ভাল দ্বারা পরীক্ষা করে থাকি এবং আমারই কাছে তোমরা প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 21, 36, 'কাফেররা যখন আপনাকে দেখে তখন আপনার সাথে ঠাট্টা করা ছাড়া তাদের আর কোন কাজ থাকে না, একি সেই ব্যক্তি, যে তোমাদের দেব-দেবীদের সমালোচনা করে? এবং তারাই তো রহমান’ এর আলোচনায় অস্বীকার করে।'),
  ('bn.bengali', 21, 37, 'সৃষ্টিগত ভাবে মানুষ ত্বরাপ্রবণ, আমি সত্তরই তোমাদেরকে আমার নিদর্শনাবলী দেখাব। অতএব আমাকে শীঘ্র করতে বলো না।'),
  ('bn.bengali', 21, 38, 'এবং তারা বলেঃ যদি তোমরা সত্যবাদী হও তবে এই ওয়াদা কবে পুর্ণ হবে?'),
  ('bn.bengali', 21, 39, 'যদি কাফেররা ঐ সময়টি জানত, যখন তারা তাদের সম্মুখ ও পৃষ্ঠদেশ থেকে অগ্নি প্রতিরোধ করতে পারবে না এবং তারা সাহায্য প্রাপ্ত হবে না।'),
  ('bn.bengali', 21, 40, 'বরং তা আসবে তাদের উপর অতর্কিত ভাবে, অতঃপর তাদেরকে তা হতবুদ্ধি করে দেবে, তখন তারা তা রোধ করতেও পারবে না এবং তাদেরকে অবকাশও দেয়া হবে না।'),
  ('bn.bengali', 21, 41, 'আপনার পূর্বেও অনেক রাসূলের সাথে ঠাট্টা-বিদ্রূপ করা হয়েছে। অতঃপর যে বিষয়ে তারা ঠাট্টা করত তা উল্টো ঠাট্টাকারীদের উপরই আপতিত হয়েছে।'),
  ('bn.bengali', 21, 42, 'বলুনঃ ‘রহমান’ থেকে কে তোমাদেরকে হেফাযত করবে রাত্রে ও দিনে। বরং তারা তাদের পালনকর্তার স্মরণ থেকে মুখ ফিরিয়ে রাখে।'),
  ('bn.bengali', 21, 43, 'তবে কি আমি ব্যতীত তাদের এমন দেব-দেবী আছে যারা তাদেরকে রক্ষা করবে? তারা তো নিজেদেরই সাহায্য করতে সক্ষম নয় এবং তারা আমার মোকাবেলায় সাহায্যকারীও পাবে না।'),
  ('bn.bengali', 21, 44, 'বরং আমি তাদেরকে এবং তাদের বাপ-দাদাকে ভোগসম্বার দিয়েছিলাম, এমনকি তাদের আয়ুস্কালও দীর্ঘ হয়েছিল। তারা কি দেখে না যে, আমি তাদের দেশকে চতুর্দিক থেকে হ্রাস করে আনছি। এরপরও কি তারা বিজয়ী হবে?'),
  ('bn.bengali', 21, 45, 'বলুনঃ আমি তো কেবল ওহীর মাধ্যমেই তোমাদেরকে সতর্ক করি, কিন্তু বধিরদেরকে যখন সতর্ক করা হয়, তখন তারা সে সতর্কবাণী শোনে না।'),
  ('bn.bengali', 21, 46, 'আপনার পালনকর্তার আযাবের কিছুমাত্রও তাদেরকে স্পর্শ করলে তারা বলতে থাকবে, হায় আমাদের দুর্ভাগ্য, আমরা অবশ্যই পাপী ছিলাম।'),
  ('bn.bengali', 21, 47, 'আমি কেয়ামতের দিন ন্যায়বিচারের মানদন্ড স্থাপন করব। সুতরাং কারও প্রতি জুলুম হবে না। যদি কোন আমল সরিষার দানা পরিমাণও হয়, আমি তা উপস্থিত করব এবং হিসাব গ্রহণের জন্যে আমিই যথেষ্ট।'),
  ('bn.bengali', 21, 48, 'আমি মূসা ও হারুণকে দান করেছিলাম মীমাংসাকারী গ্রন্থ, আলো ও উপদেশ, আল্লাহ ভীরুদের জন্যে'),
  ('bn.bengali', 21, 49, 'যারা না দেখেই তাদের পালনকর্তাকে ভয় করে এবং কেয়ামতের ভয়ে শঙ্কিত।'),
  ('bn.bengali', 21, 50, 'এবং এটা একটা বরকতময় উপদেশ, যা আমি নাযিল করেছি। অতএব তোমরা কি একে অস্বীকার কর?'),
  ('bn.bengali', 21, 51, 'আর, আমি ইতিপূর্বে ইব্রাহীমকে তার সৎপন্থা দান করেছিলাম এবং আমি তার সম্পর্কে সম্যক পরিজ্ঞাত ও ছিলাম।'),
  ('bn.bengali', 21, 52, 'যখন তিনি তাঁর পিতা ও তাঁর সম্প্রদায়কে বললেনঃ এই মূর্তিগুলো কী, যাদের তোমরা পূজারী হয়ে বসে আছ।'),
  ('bn.bengali', 21, 53, 'তারা বললঃ আমরা আমাদের বাপ-দাদাকে এদের পুজা করতে দেখেছি।'),
  ('bn.bengali', 21, 54, 'তিনি বললেনঃ তোমরা প্রকাশ্য গোমরাহীতে আছ এবং তোমাদের বাপ-দাদারাও।'),
  ('bn.bengali', 21, 55, 'তারা বললঃ তুমি কি আমাদের কাছে সত্যসহ আগমন করেছ, না তুমি কৌতুক করছ?'),
  ('bn.bengali', 21, 56, 'তিনি বললেনঃ না, তিনিই তোমাদের পালনকর্তা যিনি নভোমন্ডল ও ভুমন্ডলের পালনকর্তা, যিনি এগুলো সৃষ্টি করেছেন; এবং আমি এই বিষয়েরই সাক্ষ্যদাতা।'),
  ('bn.bengali', 21, 57, 'আল্লাহর কসম, যখন তোমরা পৃষ্ঠ প্রদর্শন করে চলে যাবে, তখন আমি তোমাদের মূর্তিগুলোর ব্যাপারে একটা ব্যবস্থা অবলম্বন করব।'),
  ('bn.bengali', 21, 58, 'অতঃপর তিনি সেগুলোকে চূর্ণ-বিচুর্ণ করে দিলেন ওদের প্রধানটি ব্যতীতঃ যাতে তারা তাঁর কাছে প্রত্যাবর্তন করে।'),
  ('bn.bengali', 21, 59, 'তারা বললঃ আমাদের উপাস্যদের সাথে এরূপ ব্যবহার কে করল? সে তো নিশ্চয়ই কোন জালিম।'),
  ('bn.bengali', 21, 60, 'কতক লোকে বললঃ আমরা এক যুবককে তাদের সম্পর্কে বিরূপ আলোচনা করতে শুনেছি; তাকে ইব্রাহীম বলা হয়।'),
  ('bn.bengali', 21, 61, 'তারা বললঃ তাকে জনসমক্ষে উপস্থিত কর, যাতে তারা দেখে।'),
  ('bn.bengali', 21, 62, 'তারা বললঃ হে ইব্রাহীম তুমিই কি আমাদের উপাস্যদের সাথে এরূপ ব্যবহার করেছ?'),
  ('bn.bengali', 21, 63, 'তিনি বললেনঃ না এদের এই প্রধানই তো একাজ করেছে। অতএব তাদেরকে জিজ্ঞেস কর, যদি তারা কথা বলতে পারে।'),
  ('bn.bengali', 21, 64, 'অতঃপর মনে মনে চিন্তা করল এবং বললঃ লোক সকল; তোমরাই বে ইনসাফ।'),
  ('bn.bengali', 21, 65, 'অতঃপর তারা ঝুঁকে গেল মস্তক নত করে, তুমি তো জান যে, এরা কথা বলে না'),
  ('bn.bengali', 21, 66, 'তিনি বললেনঃ তোমরা কি আল্লাহর পরিবর্তে এমন কিছুর এবাদত কর, যা তোমাদের কোন উপকার ও করতে পারে না এবং ক্ষতিও করতে পারে না ?'),
  ('bn.bengali', 21, 67, 'ধিক তোমাদের জন্যে এবং তোমরা আল্লাহ ব্যতীত যাদেরই এবাদত কর, ওদের জন্যে। তোমরা কি বোঝ না?'),
  ('bn.bengali', 21, 68, 'তারা বললঃ একে পুড়িয়ে দাও এবং তোমাদের উপাস্যদের সাহায্য কর, যদি তোমরা কিছু করতে চাও।'),
  ('bn.bengali', 21, 69, 'আমি বললামঃ হে অগ্নি, তুমি ইব্রাহীমের উপর শীতল ও নিরাপদ হয়ে যাও।'),
  ('bn.bengali', 21, 70, 'তারা ইব্রাহীমের বিরুদ্ধে ফন্দি আঁটতে চাইল, অতঃপর আমি তাদেরকেই সর্বাধিক ক্ষতিগ্রস্থ করে দিলাম।'),
  ('bn.bengali', 21, 71, 'আমি তাঁকে ও লূতকে উদ্ধার করে সেই দেশে পৌঁছিয়ে দিলাম, যেখানে আমি বিশ্বের জন্যে কল্যাণ রেখেছি।'),
  ('bn.bengali', 21, 72, 'আমি তাকে দান করলাম ইসহাক ও পুরস্কার স্বরূপ দিলাম ইয়াকুব এবং প্রত্যেককেই সৎকর্ম পরায়ণ করলাম।'),
  ('bn.bengali', 21, 73, 'আমি তাঁদেরকে নেতা করলাম। তাঁরা আমার নির্দেশ অনুসারে পথ প্রদর্শন করতেন। আমি তাঁদের প্রতি ওহী নাযিল করলাম সৎকর্ম করার, নামায কায়েম করার এবং যাকাত দান করার। তাঁরা আমার এবাদতে ব্যাপৃত ছিল।'),
  ('bn.bengali', 21, 74, 'এবং আমি লূতকে দিয়েছিলাম প্রজ্ঞা ও জ্ঞান এবং তাঁকে ঐ জনপদ থেকে উদ্ধার করেছিলাম, যারা নোংরা কাজে লিপ্ত ছিল। তারা মন্দ ও নাফরমান সম্প্রদায় ছিল।'),
  ('bn.bengali', 21, 75, 'আমি তাকে আমার অনুগ্রহের অন্তর্ভুক্ত করেছিলাম। সে ছিল সৎকর্মশীলদের একজন।'),
  ('bn.bengali', 21, 76, 'এবং স্মরণ করুন নূহকে; যখন তিনি এর পূর্বে আহবান করেছিলেন। তখন আমি তাঁর দোয়া কবুল করেছিলাম, অতঃপর তাঁকে ও তাঁর পরিবারবর্গকে মহা সংকট থেকে উদ্ধার করেছিলাম।'),
  ('bn.bengali', 21, 77, 'এবং আমি তাঁকে ঐ সম্প্রদায়ের বিপক্ষে সাহায্য করেছিলাম, যারা আমার নিদর্শনাবলীকে অস্বীকার করেছিল। নিশ্চয়, তারা ছিল এক মন্দ সম্প্রদায়। অতঃপর আমি তাদের সবাইকে নিমজ্জত করেছিলাম।'),
  ('bn.bengali', 21, 78, 'এবং স্মরণ করুন দাউদ ও সুলায়মানকে, যখন তাঁরা শস্যক্ষেত্র সম্পর্কে বিচার করেছিলেন। তাতে রাত্রিকালে কিছু লোকের মেষ ঢুকে পড়েছিল। তাদের বিচার আমার সম্মুখে ছিল।'),
  ('bn.bengali', 21, 79, 'অতঃপর আমি সুলায়মানকে সে ফায়সালা বুঝিয়ে দিয়েছিলাম এবং আমি উভয়কে প্রজ্ঞা ও জ্ঞান দিয়েছিলাম। আমি পর্বত ও পক্ষীসমূহকে দাউদের অনুগত করে দিয়েছিলাম; তারা আমার পবিত্রতা ও মহিমা ঘোষণা করত। এই সমস্ত আমিই করেছিলাম।'),
  ('bn.bengali', 21, 80, 'আমি তাঁকে তোমাদের জন্যে বর্ম নির্মান শিক্ষা দিয়েছিলাম, যাতে তা যুদ্ধে তোমাদেরকে রক্ষা করে। অতএব তোমরা কি কৃতজ্ঞ হবে?'),
  ('bn.bengali', 21, 81, 'এবং সুলায়মানের অধীন করে দিয়েছিলাম প্রবল বায়ুকে; তা তাঁর আদেশে প্রবাহিত হত ঐ দেশের দিকে, যেখানে আমি কল্যাণ দান করেছি। আমি সব বিষয়েই সম্যক অবগত রয়েছি।'),
  ('bn.bengali', 21, 82, 'এবং অধীন করেছি শয়তানদের কতককে, যারা তার জন্যে ডুবুরীর কাজ করত এবং এ ছাড়া অন্য আরও অনেক কাজ করত। আমি তাদেরকে নিয়ন্ত্রন করে রাখতাম।'),
  ('bn.bengali', 21, 83, 'এবং স্মরণ করুন আইয়্যুবের কথা, যখন তিনি তাঁর পালনকর্তাকে আহবান করে বলেছিলেনঃ আমি দুঃখকষ্টে পতিত হয়েছি এবং আপনি দয়াবানদের চাইতেও সর্বশ্রেষ্ট দয়াবান।'),
  ('bn.bengali', 21, 84, 'অতঃপর আমি তাঁর আহবানে সাড়া দিলাম এবং তাঁর দুঃখকষ্ট দূর করে দিলাম এবং তাঁর পরিবরাবর্গ ফিরিয়ে দিলাম, আর তাদের সাথে তাদের সমপরিমাণ আরও দিলাম আমার পক্ষ থেকে কৃপাবশতঃ আর এটা এবাদত কারীদের জন্যে উপদেশ স্বরূপ।'),
  ('bn.bengali', 21, 85, 'এবং ইসমাঈল, ই’দ্রীস ও যুলকিফলের কথা স্মরণ করুন, তাঁরা প্রত্যেকেই ছিলেন সবরকারী।'),
  ('bn.bengali', 21, 86, 'আমি তাঁদেরকে আমার রহমাতপ্রাপ্তদের অন্তর্ভূক্ত করেছিলাম। তাঁরা ছিলেন সৎকর্মপরায়ণ।'),
  ('bn.bengali', 21, 87, 'এবং মাছওয়ালার কথা স্মরণ করুন তিনি ক্রুদ্ধ হয়ে চলে গিয়েছিলেন, অতঃপর মনে করেছিলেন যে, আমি তাঁকে ধৃত করতে পারব না। অতঃপর তিনি অন্ধকারের মধ্যে আহবান করলেনঃ তুমি ব্যতীত কোন উপাস্য নেই; তুমি নির্দোষ আমি গুনাহগার।'),
  ('bn.bengali', 21, 88, 'অতঃপর আমি তাঁর আহবানে সাড়া দিলাম এবং তাঁকে দুশ্চিন্তা থেকে মুক্তি দিলাম। আমি এমনি ভাবে বিশ্ববাসীদেরকে মুক্তি দিয়ে থাকি।'),
  ('bn.bengali', 21, 89, 'এবং যাকারিয়ার কথা স্মরণ করুন, যখন সে তার পালনকর্তাকে আহবান করেছিল; হে আমার পালনকর্তা আমাকে একা রেখো না। তুমি তো উত্তম ওয়ারিস।'),
  ('bn.bengali', 21, 90, 'অতঃপর আমি তার দোয়া কবুল করেছিলাম, তাকে দান করেছিলাম ইয়াহইয়া এবং তার জন্যে তার স্ত্রীকে প্রসব যোগ্য করেছিলাম। তারা সৎকর্মে ঝাঁপিয়ে পড়ত, তারা আশা ও ভীতি সহকারে আমাকে ডাকত এবং তারা ছিল আমার কাছে বিনীত।'),
  ('bn.bengali', 21, 91, 'এবং সেই নারীর কথা আলোচনা করুন, যে তার কামপ্রবৃত্তিকে বশে রেখেছিল, অতঃপর আমি তার মধ্যে আমার রূহ ফুঁকে দিয়েছিলাম এবং তাকে তার পুত্রকে বিশ্ববাসীর জন্য নিদর্শন করেছিলাম।'),
  ('bn.bengali', 21, 92, 'তারা সকলেই তোমাদের ধর্মের; একই ধর্মে তো বিশ্বাসী সবাই এবং আমিই তোমাদের পালনকর্তা, অতএব আমার বন্দেগী কর।'),
  ('bn.bengali', 21, 93, 'এবং মানুষ তাদের কার্যকলাপ দ্বারা পারস্পরিক বিষয়ে ভেদ সৃষ্টি করেছে। প্রত্যেকেই আমার কাছে প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 21, 94, 'অতঃপর যে বিশ্বাসী অবস্থায় সৎকর্ম সম্পাদন করে, তার প্রচেষ্টা অস্বীকৃত হবে না এবং আমি তা লিপিবদ্ধ করে রাখি।'),
  ('bn.bengali', 21, 95, 'যেসব জনপদকে আমি ধ্বংস করে দিয়েছি, তার অধিবাসীদের ফিরে না আসা অবধারিত।'),
  ('bn.bengali', 21, 96, 'যে পর্যন্ত না ইয়াজুজ ও মাজুজকে বন্ধন মুক্ত করে দেয়া হবে এবং তারা প্রত্যেক উচ্চভুমি থেকে দ্রুত ছুটে আসবে।'),
  ('bn.bengali', 21, 97, 'আমোঘ প্রতিশ্রুত সময় নিকটবর্তী হলে কাফেরদের চক্ষু উচ্চে স্থির হয়ে যাবে; হায় আমাদের দূর্ভাগ্য, আমরা এ বিষয়ে বেখবর ছিলাম; বরং আমরা গোনাহগরই ছিলাম।'),
  ('bn.bengali', 21, 98, 'তোমরা এবং আল্লাহর পরিবর্তে তোমরা যাদের পুজা কর, সেগুলো দোযখের ইন্ধন। তোমরাই তাতে প্রবেশ করবে।'),
  ('bn.bengali', 21, 99, 'এই মূর্তিরা যদি উপাস্য হত, তবে জাহান্নামে প্রবেশ করত না। প্রত্যেকেই তাতে চিরস্থায়ী হয়ে পড়ে থাকবে।'),
  ('bn.bengali', 21, 100, 'তারা সেখানে চীৎকার করবে এবং সেখানে তারা কিছুই শুনতে পাবে না।'),
  ('bn.bengali', 21, 101, 'যাদের জন্য প্রথম থেকেই আমার পক্ষ থেকে কল্যাণ নির্ধারিত হয়েছে তারা দোযখ থেকে দূরে থাকবে।'),
  ('bn.bengali', 21, 102, 'তারা তার ক্ষীণতম শব্দও শুনবে না এবং তারা তাদের মনের বাসনা অনুযায়ী চিরকাল বসবাস করবে।'),
  ('bn.bengali', 21, 103, 'মহা ত্রাস তাদেরকে চিন্তান্বিত করবে না এবং ফেরেশতারা তাদেরকে অভ্যর্থনা করবেঃ আজ তোমাদের দিন, যে দিনের ওয়াদা তোমাদেরকে দেয়া হয়েছিল।'),
  ('bn.bengali', 21, 104, 'সেদিন আমি আকাশকে গুটিয়ে নেব, যেমন গুটানো হয় লিখিত কাগজপত্র। যেভাবে আমি প্রথমবার সৃষ্টি করেছিলাম, সেভাবে পুনরায় সৃষ্টি করব। আমার ওয়াদা নিশ্চিত, আমাকে তা পূর্ণ করতেই হবে।'),
  ('bn.bengali', 21, 105, 'আমি উপদেশের পর যবুরে লিখে দিয়েছি যে, আমার সৎকর্মপরায়ণ বান্দাগণ অবশেষে পৃথিবীর অধিকারী হবে।'),
  ('bn.bengali', 21, 106, 'এতে এবাদতকারী সম্প্রদায়ের জন্যে পর্যাপ্ত বিষয়বস্তু আছে।'),
  ('bn.bengali', 21, 107, 'আমি আপনাকে বিশ্ববাসীর জন্যে রহমত স্বরূপই প্রেরণ করেছি।'),
  ('bn.bengali', 21, 108, 'বলুনঃ আমাকে তো এ আদেশই দেয়া হয়েছে যে, তোমাদের উপাস্য একমাত্র উপাস্য। সুতরাংতোমরা কি আজ্ঞাবহ হবে?'),
  ('bn.bengali', 21, 109, 'অতঃপর যদি তারা মুখ ফিরিয়ে নেয়, তবে বলে দিনঃ আমি তোমাদেরকে পরিস্কার ভাবে সতর্ক করেছি এবং আমি জানি না, তোমাদেরকে যে ওয়াদা দেয়া হয়েছে, তা নিকটবর্তী না দূরবর্তী।'),
  ('bn.bengali', 21, 110, 'তিনি জানেন, যে কথা সশব্দে বল এবং যে কথা তোমরা গোপন কর।'),
  ('bn.bengali', 21, 111, 'আমি জানি না সম্ভবতঃ বিলম্বের মধ্যে তোমাদের জন্যে একটি পরীক্ষা এবং এক সময় পর্যন্ত ভোগ করার সুযোগ।'),
  ('bn.bengali', 21, 112, 'পয়গাম্বর বললেনঃ হে আমার পালনকর্তা, আপনি ন্যায়ানুগ ফয়সালা করে দিন। আমাদের পালনকর্তা তো দয়াময়, তোমরা যা বলছ, সে বিষয়ে আমরা তাঁর কাছেই সাহায্য প্রার্থনা করি।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 21, 1, 'Their reckoning draweth nigh for mankind, while they turn away in heedlessness.'),
  ('en.pickthall', 21, 2, 'Never cometh there unto them a new reminder from their Lord but they listen to it while they play,'),
  ('en.pickthall', 21, 3, 'With hearts preoccupied. And they confer in secret. The wrong-doers say: Is this other than a mortal like you? Will ye then succumb to magic when ye see (it)?'),
  ('en.pickthall', 21, 4, 'He saith: My Lord knoweth what is spoken in the heaven and the earth. He is the Hearer, the Knower.'),
  ('en.pickthall', 21, 5, 'Nay, say they, (these are but) muddled dreams; nay, he hath but invented it; nay, he is but a poet. Let him bring us a portent even as those of old (who were Allah\'s messengers) were sent (with portents).'),
  ('en.pickthall', 21, 6, 'Not a township believed of those which We destroyed before them (though We sent them portents): would they then believe?'),
  ('en.pickthall', 21, 7, 'And We sent not (as Our messengers) before thee other than men, whom We inspired. Ask the followers of the Reminder if ye know not?'),
  ('en.pickthall', 21, 8, 'We gave them not bodies that would not eat food, nor were they immortals.'),
  ('en.pickthall', 21, 9, 'Then we fulfilled the promise unto them. So we delivered them and whom We would, and We destroyed the prodigals.'),
  ('en.pickthall', 21, 10, 'Now We have revealed unto you a Scripture wherein is your Reminder. Have ye then no sense?'),
  ('en.pickthall', 21, 11, 'How many a community that dealt unjustly have We shattered, and raised up after them another folk!'),
  ('en.pickthall', 21, 12, 'And, when they felt Our might, behold them fleeing from it!'),
  ('en.pickthall', 21, 13, '(But it was said unto them): Flee not, but return to that (existence) which emasculated you and to your dwellings, that ye may be questioned.'),
  ('en.pickthall', 21, 14, 'They cried: Alas for us! we were wrong-doers.'),
  ('en.pickthall', 21, 15, 'And this their crying ceased not till We made them as reaped corn, extinct.'),
  ('en.pickthall', 21, 16, 'We created not the heaven and the earth and all that is between them in play.'),
  ('en.pickthall', 21, 17, 'If We had wished to find a pastime, We could have found it in Our presence - if We ever did.'),
  ('en.pickthall', 21, 18, 'Nay, but We hurl the true against the false, and it doth break its head and lo! it vanisheth. And yours will be woe for that which ye ascribe (unto Him).'),
  ('en.pickthall', 21, 19, 'Unto Him belongeth whosoever is in the heavens and the earth. And those who dwell in His presence are not too proud to worship Him, nor do they weary;'),
  ('en.pickthall', 21, 20, 'They glorify (Him) night and day; they flag not.'),
  ('en.pickthall', 21, 21, 'Or have they chosen gods from the earth who raise the dead?'),
  ('en.pickthall', 21, 22, 'If there were therein gods beside Allah, then verily both (the heavens and the earth) had been disordered. Glorified be Allah, the Lord of the Throne, from all that they ascribe (unto Him).'),
  ('en.pickthall', 21, 23, 'He will not be questioned as to that which He doeth, but they will be questioned.'),
  ('en.pickthall', 21, 24, 'Or have they chosen other gods beside Him? say: Bring your proof (of their godhead). This is the Reminder of those with me and those before me, but most of them know not the Truth and so they are averse.'),
  ('en.pickthall', 21, 25, 'And We sent no messenger before thee but We inspired him, (saying): There is no Allah save Me (Allah), so worship Me.'),
  ('en.pickthall', 21, 26, 'And they say: The Beneficent hath taken unto Himself a son. Be He Glorified! Nay, but (those whom they call sons) are honoured slaves;'),
  ('en.pickthall', 21, 27, 'They speak not until He hath spoken, and they act by His command.'),
  ('en.pickthall', 21, 28, 'He knoweth what is before them and what is behind them, and they cannot intercede except for him whom He accepteth, and they quake for awe of Him.'),
  ('en.pickthall', 21, 29, 'And one of them who should say: Lo! I am a god beside Him, that one We should repay with hell. Thus We Repay wrong-doers.'),
  ('en.pickthall', 21, 30, 'Have not those who disbelieve known that the heavens and the earth were of one piece, then We parted them, and we made every living thing of water? Will they not then believe?'),
  ('en.pickthall', 21, 31, 'And We have placed in the earth firm hills lest it quake with them, and We have placed therein ravines as roads that haply they may find their way.'),
  ('en.pickthall', 21, 32, 'And we have made the sky a roof withheld (from them). Yet they turn away from its portents.'),
  ('en.pickthall', 21, 33, 'And He it is Who created the night and the day, and the sun and the moon. They float, each in an orbit.'),
  ('en.pickthall', 21, 34, 'We appointed immortality for no mortal before thee. What! if thou diest, can they be immortal!'),
  ('en.pickthall', 21, 35, 'Every soul must taste of death, and We try you with evil and with good, for ordeal. And unto Us ye will be returned.'),
  ('en.pickthall', 21, 36, 'And when those who disbelieve behold thee, they but choose thee out for mockery, (saying): Is this he who maketh mention of your gods? And they would deny all mention of the Beneficent.'),
  ('en.pickthall', 21, 37, 'Man is made of haste. I shall show you My portents, but ask Me not to hasten.'),
  ('en.pickthall', 21, 38, 'And they say: When will this promise (be fulfilled), if ye are truthful?'),
  ('en.pickthall', 21, 39, 'If those who disbelieved but knew the time when they will not be able to drive off the fire from their faces and from their backs, and they will not be helped!'),
  ('en.pickthall', 21, 40, 'Nay, but it will come upon them unawares so that it will stupefy them, and they will be unable to repel it, neither will they be reprieved.'),
  ('en.pickthall', 21, 41, 'Messengers before thee, indeed, were mocked, but that whereat they mocked surrounded those who scoffed at them.'),
  ('en.pickthall', 21, 42, 'Say: Who guardeth you in the night or in the day from the Beneficent? Nay, but they turn away from mention of their Lord!'),
  ('en.pickthall', 21, 43, 'Or have they gods who can shield them from Us? They cannot help themselves nor can they be defended from Us.'),
  ('en.pickthall', 21, 44, 'Nay, but We gave these and their fathers ease until life grew long for them. See they not how we aim to the land, reducing it of its outlying parts? Can they then be the victors?'),
  ('en.pickthall', 21, 45, 'Say (O Muhammad, unto mankind): I warn you only by the Inspiration. But the deaf hear not the call when they are warned.'),
  ('en.pickthall', 21, 46, 'And if a breath of thy Lord\'s punishment were to touch them, they assuredly would say: Alas for us! Lo! we were wrong-doers.'),
  ('en.pickthall', 21, 47, 'And We set a just balance for the Day of Resurrection so that no soul is wronged in aught. Though it be of the weight of a grain of mustard seed, We bring it. And We suffice for reckoners.'),
  ('en.pickthall', 21, 48, 'And We verily gave Moses and Aaron the Criterion (of right and wrong) and a light and a Reminder for those who keep from evil,'),
  ('en.pickthall', 21, 49, 'Those who fear their Lord in secret and who dread the Hour (of doom).'),
  ('en.pickthall', 21, 50, 'This is a blessed Reminder that we have revealed: Will ye then reject it?'),
  ('en.pickthall', 21, 51, 'And We verily gave Abraham of old his proper course, and We were Aware of him,'),
  ('en.pickthall', 21, 52, 'When he said unto his father and his folk: What are these images unto which ye pay devotion?'),
  ('en.pickthall', 21, 53, 'They said: We found our fathers worshippers of them.'),
  ('en.pickthall', 21, 54, 'He said: Verily ye and your fathers were in plain error.'),
  ('en.pickthall', 21, 55, 'They said: Bringest thou unto us the truth, or art thou some jester?'),
  ('en.pickthall', 21, 56, 'He said: Nay, but your Lord is the Lord of the heavens and the earth, Who created them; and I am of those who testify unto that.'),
  ('en.pickthall', 21, 57, 'And, by Allah, I shall circumvent your idols after ye have gone away and turned your backs.'),
  ('en.pickthall', 21, 58, 'Then he reduced them to fragments, all save the chief of them, that haply they might have recourse to it.'),
  ('en.pickthall', 21, 59, 'They said: Who hath done this to our gods? Surely it must be some evil-doer.'),
  ('en.pickthall', 21, 60, 'They said: We heard a youth make mention of them, who is called Abraham.'),
  ('en.pickthall', 21, 61, 'They said: Then bring him (hither) before the people\'s eyes that they may testify.'),
  ('en.pickthall', 21, 62, 'They said: Is it thou who hast done this to our gods, O Abraham?'),
  ('en.pickthall', 21, 63, 'He said: But this, their chief hath done it. So question them, if they can speak.'),
  ('en.pickthall', 21, 64, 'Then gathered they apart and said: Lo! ye yourselves are the wrong-doers.'),
  ('en.pickthall', 21, 65, 'And they were utterly confounded, and they said: Well thou knowest that these speak not.'),
  ('en.pickthall', 21, 66, 'He said: Worship ye then instead of Allah that which cannot profit you at all, nor harm you?'),
  ('en.pickthall', 21, 67, 'Fie on you and all that ye worship instead of Allah! Have ye then no sense?'),
  ('en.pickthall', 21, 68, 'They cried: Burn him and stand by your gods, if ye will be doing.'),
  ('en.pickthall', 21, 69, 'We said: O fire, be coolness and peace for Abraham,'),
  ('en.pickthall', 21, 70, 'And they wished to set a snare for him, but We made them the greater losers.'),
  ('en.pickthall', 21, 71, 'And We rescued him and Lot (and brought them) to the land which We have blessed for (all) peoples.'),
  ('en.pickthall', 21, 72, 'And We bestowed upon him Isaac, and Jacob as a grandson. Each of them We made righteous.'),
  ('en.pickthall', 21, 73, 'And We made them chiefs who guide by Our command, and We inspired in them the doing of good deeds and the right establishment of worship and the giving of alms, and they were worshippers of Us (alone).'),
  ('en.pickthall', 21, 74, 'And unto Lot we gave judgment and knowledge, and We delivered him from the community that did abominations. Lo! they were folk of evil, lewd.'),
  ('en.pickthall', 21, 75, 'And We brought him in unto Our mercy. Lo! he was of the righteous.'),
  ('en.pickthall', 21, 76, 'And Noah, when he cried of old, We heard his prayer and saved him and his household from the great affliction.'),
  ('en.pickthall', 21, 77, 'And delivered him from the people who denied Our revelations. Lo! they were folk of evil, therefor did We drown them all.'),
  ('en.pickthall', 21, 78, 'And David and Solomon, when they gave judgment concerning the field, when people\'s sheep had strayed and browsed therein by night; and We were witnesses to their judgment.'),
  ('en.pickthall', 21, 79, 'And We made Solomon to understand (the case); and unto each of them We gave judgment and knowledge. And we subdued the hills and the birds to hymn (His) praise along with David. We were the doers (thereof).'),
  ('en.pickthall', 21, 80, 'And We taught him the art of making garments (of mail) to protect you in your daring. Are ye then thankful?'),
  ('en.pickthall', 21, 81, 'And unto Solomon (We subdued) the wind in its raging. It set by his command toward the land which We had blessed. And of everything We are Aware.'),
  ('en.pickthall', 21, 82, 'And of the evil ones (subdued We unto him) some who dived (for pearls) for him and did other work, and We were warders unto them.'),
  ('en.pickthall', 21, 83, 'And Job, when he cried unto his Lord, (saying): Lo! adversity afflicteth me, and Thou art Most Merciful of all who show mercy.'),
  ('en.pickthall', 21, 84, 'Then We heard his prayer and removed that adversity from which he suffered, and We gave him his household (that he had lost) and the like thereof along with them, a mercy from Our store, and a remembrance for the worshippers;'),
  ('en.pickthall', 21, 85, 'And (mention) Ishmael, and Idris, and Dhu\'l-Kifl. All were of the steadfast.'),
  ('en.pickthall', 21, 86, 'And We brought them in unto Our mercy. Lo! they are among the righteous.'),
  ('en.pickthall', 21, 87, 'And (mention) Dhu\'n-Nun, when he went off in anger and deemed that We had no power over him, but he cried out in the darkness, saying: There is no Allah save Thee. Be Thou Glorified! Lo! I have been a wrong-doer.'),
  ('en.pickthall', 21, 88, 'Then we heard his prayer and saved him from the anguish. Thus we save believers.'),
  ('en.pickthall', 21, 89, 'And Zachariah, when he cried unto his Lord: My Lord! Leave me not childless, though Thou art the Best of inheritors.'),
  ('en.pickthall', 21, 90, 'Then We heard his prayer, and bestowed upon him John, and adjusted his wife (to bear a child) for him. Lo! they used to vie one with the other in good deeds, and they cried unto Us in longing and in fear, and were submissive unto Us.'),
  ('en.pickthall', 21, 91, 'And she who was chaste, therefor We breathed into her (something) of Our Spirit and made her and her son a token for (all) peoples.'),
  ('en.pickthall', 21, 92, 'Lo! this, your religion, is one religion, and I am your Lord, so worship Me.'),
  ('en.pickthall', 21, 93, 'And they have broken their religion (into fragments) among them, (yet) all are returning unto Us.'),
  ('en.pickthall', 21, 94, 'Then whoso doeth some good works and is a believer, there will be no rejection of his effort. Lo! We record (it) for him.'),
  ('en.pickthall', 21, 95, 'And there is a ban upon any community which We have destroyed: that they shall not return.'),
  ('en.pickthall', 21, 96, 'Until, when Gog and Magog are let loose, and they hasten out of every mound,'),
  ('en.pickthall', 21, 97, 'And the True Promise draweth nigh; then behold them, staring wide (in terror), the eyes of those who disbelieve! (They say): Alas for us! We (lived) in forgetfulness of this. Ah, but we were wrong-doers!'),
  ('en.pickthall', 21, 98, 'Lo! ye (idolaters) and that which ye worship beside Allah are fuel of hell. Thereunto ye will come.'),
  ('en.pickthall', 21, 99, 'If these had been gods they would not have come thither, but all will abide therein.'),
  ('en.pickthall', 21, 100, 'Therein wailing is their portion, and therein they hear not.'),
  ('en.pickthall', 21, 101, 'Lo! those unto whom kindness hath gone forth before from Us, they will be far removed from thence.'),
  ('en.pickthall', 21, 102, 'They will not hear the slightest sound thereof, while they abide in that which their souls desire.'),
  ('en.pickthall', 21, 103, 'The Supreme Horror will not grieve them, and the angels will welcome them, (saying): This is your Day which ye were promised;'),
  ('en.pickthall', 21, 104, 'The Day when We shall roll up the heavens as a recorder rolleth up a written scroll. As We began the first creation, We shall repeat it. (It is) a promise (binding) upon Us. Lo! We are to perform it.'),
  ('en.pickthall', 21, 105, 'And verily we have written in the Scripture, after the Reminder: My righteous slaves will inherit the earth:'),
  ('en.pickthall', 21, 106, 'Lo! there is a plain statement for folk who are devout.'),
  ('en.pickthall', 21, 107, 'We sent thee not save as a mercy for the peoples.'),
  ('en.pickthall', 21, 108, 'Say: It is only inspired in me that your Allah is One Allah. Will ye then surrender (unto Him)?'),
  ('en.pickthall', 21, 109, 'But if they are averse, then say: I have warned you all alike, although I know not whether nigh or far is that which ye are promised.'),
  ('en.pickthall', 21, 110, 'Lo! He knoweth that which is said openly, and that which ye conceal.'),
  ('en.pickthall', 21, 111, 'And I know not but that this may be a trial for you, and enjoyment for a while.'),
  ('en.pickthall', 21, 112, 'He saith: My Lord! Judge Thou with truth. Our Lord is the Beneficent, Whose help is to be implored against that which ye ascribe (unto Him).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 21, 1, 'Closer and closer to mankind comes their Reckoning: yet they heed not and they turn away.'),
  ('en.yusufali', 21, 2, 'Never comes (aught) to them of a renewed Message from their Lord, but they listen to it as in jest,-'),
  ('en.yusufali', 21, 3, 'Their hearts toying as with trifles. The wrong-doers conceal their private counsels, (saying), "Is this (one) more than a man like yourselves? Will ye go to witchcraft with your eyes open?"'),
  ('en.yusufali', 21, 4, 'Say: "My Lord knoweth (every) word (spoken) in the heavens and on earth: He is the One that heareth and knoweth (all things)."'),
  ('en.yusufali', 21, 5, '"Nay," they say, "(these are) medleys of dream! - Nay, He forged it! - Nay, He is (but) a poet! Let him then bring us a Sign like the ones that were sent to (Prophets) of old!"'),
  ('en.yusufali', 21, 6, '(As to those) before them, not one of the populations which We destroyed believed: will these believe?'),
  ('en.yusufali', 21, 7, 'Before thee, also, the messengers We sent were but men, to whom We granted inspiration: If ye realise this not, ask of those who possess the Message.'),
  ('en.yusufali', 21, 8, 'Nor did We give them bodies that ate no food, nor were they exempt from death.'),
  ('en.yusufali', 21, 9, 'In the end We fulfilled to them Our Promise, and We saved them and those whom We pleased, but We destroyed those who transgressed beyond bounds.'),
  ('en.yusufali', 21, 10, 'We have revealed for you (O men!) a book in which is a Message for you: will ye not then understand?'),
  ('en.yusufali', 21, 11, 'How many were the populations We utterly destroyed because of their iniquities, setting up in their places other peoples?'),
  ('en.yusufali', 21, 12, 'Yet, when they felt Our Punishment (coming), behold, they (tried to) flee from it.'),
  ('en.yusufali', 21, 13, 'Flee not, but return to the good things of this life which were given you, and to your homes in order that ye may be called to account.'),
  ('en.yusufali', 21, 14, 'They said: "Ah! woe to us! We were indeed wrong-doers!"'),
  ('en.yusufali', 21, 15, 'And that cry of theirs ceased not, till We made them as a field that is mown, as ashes silent and quenched.'),
  ('en.yusufali', 21, 16, 'Not for (idle) sport did We create the heavens and the earth and all that is between!'),
  ('en.yusufali', 21, 17, 'If it had been Our wish to take (just) a pastime, We should surely have taken it from the things nearest to Us, if We would do (such a thing)!'),
  ('en.yusufali', 21, 18, 'Nay, We hurl the Truth against falsehood, and it knocks out its brain, and behold, falsehood doth perish! Ah! woe be to you for the (false) things ye ascribe (to Us).'),
  ('en.yusufali', 21, 19, 'To Him belong all (creatures) in the heavens and on earth: Even those who are in His (very) Presence are not too proud to serve Him, nor are they (ever) weary (of His service):'),
  ('en.yusufali', 21, 20, 'They celebrate His praises night and day, nor do they ever flag or intermit.'),
  ('en.yusufali', 21, 21, 'Or have they taken (for worship) gods from the earth who can raise (the dead)?'),
  ('en.yusufali', 21, 22, 'If there were, in the heavens and the earth, other gods besides Allah, there would have been confusion in both! but glory to Allah, the Lord of the Throne: (High is He) above what they attribute to Him!'),
  ('en.yusufali', 21, 23, 'He cannot be questioned for His acts, but they will be questioned (for theirs).'),
  ('en.yusufali', 21, 24, 'Or have they taken for worship (other) gods besides him? Say, "Bring your convincing proof: this is the Message of those with me and the Message of those before me." But most of them know not the Truth, and so turn away.'),
  ('en.yusufali', 21, 25, 'Not a messenger did We send before thee without this inspiration sent by Us to him: that there is no god but I; therefore worship and serve Me.'),
  ('en.yusufali', 21, 26, 'And they say: "(Allah) Most Gracious has begotten offspring." Glory to Him! they are (but) servants raised to honour.'),
  ('en.yusufali', 21, 27, 'They speak not before He speaks, and they act (in all things) by His Command.'),
  ('en.yusufali', 21, 28, 'He knows what is before them, and what is behind them, and they offer no intercession except for those who are acceptable, and they stand in awe and reverence of His (Glory).'),
  ('en.yusufali', 21, 29, 'If any of them should say, "I am a god besides Him", such a one We should reward with Hell: thus do We reward those who do wrong.'),
  ('en.yusufali', 21, 30, 'Do not the Unbelievers see that the heavens and the earth were joined together (as one unit of creation), before we clove them asunder? We made from water every living thing. Will they not then believe?'),
  ('en.yusufali', 21, 31, 'And We have set on the earth mountains standing firm, lest it should shake with them, and We have made therein broad highways (between mountains) for them to pass through: that they may receive Guidance.'),
  ('en.yusufali', 21, 32, 'And We have made the heavens as a canopy well guarded: yet do they turn away from the Signs which these things (point to)!'),
  ('en.yusufali', 21, 33, 'It is He Who created the Night and the Day, and the sun and the moon: all (the celestial bodies) swim along, each in its rounded course.'),
  ('en.yusufali', 21, 34, 'We granted not to any man before thee permanent life (here): if then thou shouldst die, would they live permanently?'),
  ('en.yusufali', 21, 35, 'Every soul shall have a taste of death: and We test you by evil and by good by way of trial. to Us must ye return.'),
  ('en.yusufali', 21, 36, 'When the Unbelievers see thee, they treat thee not except with ridicule. "Is this," (they say), "the one who talks of your gods?" and they blaspheme at the mention of (Allah) Most Gracious!'),
  ('en.yusufali', 21, 37, 'Man is a creature of haste: soon (enough) will I show you My Signs; then ye will not ask Me to hasten them!'),
  ('en.yusufali', 21, 38, 'They say: "When will this promise come to pass, if ye are telling the truth?"'),
  ('en.yusufali', 21, 39, 'If only the Unbelievers knew (the time) when they will not be able to ward off the fire from their faces, nor yet from their backs, and (when) no help can reach them!'),
  ('en.yusufali', 21, 40, 'Nay, it may come to them all of a sudden and confound them: no power will they have then to avert it, nor will they (then) get respite.'),
  ('en.yusufali', 21, 41, 'Mocked were (many) messenger before thee; But their scoffers were hemmed in by the thing that they mocked.'),
  ('en.yusufali', 21, 42, 'Say: "Who can keep you safe by night and by day from (the Wrath of) (Allah) Most Gracious?" Yet they turn away from the mention of their Lord.'),
  ('en.yusufali', 21, 43, 'Or have they gods that can guard them from Us? They have no power to aid themselves, nor can they be defended from Us.'),
  ('en.yusufali', 21, 44, 'Nay, We gave the good things of this life to these men and their fathers until the period grew long for them; See they not that We gradually reduce the land (in their control) from its outlying borders? Is it then they who will win?'),
  ('en.yusufali', 21, 45, 'Say, "I do but warn you according to revelation": But the deaf will not hear the call, (even) when they are warned!'),
  ('en.yusufali', 21, 46, 'If but a breath of the Wrath of thy Lord do touch them, they will then say, "Woe to us! we did wrong indeed!"'),
  ('en.yusufali', 21, 47, 'We shall set up scales of justice for the Day of Judgment, so that not a soul will be dealt with unjustly in the least, and if there be (no more than) the weight of a mustard seed, We will bring it (to account): and enough are We to take account.'),
  ('en.yusufali', 21, 48, 'In the past We granted to Moses and Aaron the criterion (for judgment), and a Light and a Message for those who would do right,-'),
  ('en.yusufali', 21, 49, 'Those who fear their Lord in their most secret thoughts, and who hold the Hour (of Judgment) in awe.'),
  ('en.yusufali', 21, 50, 'And this is a blessed Message which We have sent down: will ye then reject it?'),
  ('en.yusufali', 21, 51, 'We bestowed aforetime on Abraham his rectitude of conduct, and well were We acquainted with him.'),
  ('en.yusufali', 21, 52, 'Behold! he said to his father and his people, "What are these images, to which ye are (so assiduously) devoted?"'),
  ('en.yusufali', 21, 53, 'They said, "We found our fathers worshipping them."'),
  ('en.yusufali', 21, 54, 'He said, "Indeed ye have been in manifest error - ye and your fathers."'),
  ('en.yusufali', 21, 55, 'They said, "Have you brought us the Truth, or are you one of those who jest?"'),
  ('en.yusufali', 21, 56, 'He said, "Nay, your Lord is the Lord of the heavens and the earth, He Who created them (from nothing): and I am a witness to this (Truth).'),
  ('en.yusufali', 21, 57, '"And by Allah, I have a plan for your idols - after ye go away and turn your backs"..'),
  ('en.yusufali', 21, 58, 'So he broke them to pieces, (all) but the biggest of them, that they might turn (and address themselves) to it.'),
  ('en.yusufali', 21, 59, 'They said, "Who has done this to our gods? He must indeed be some man of impiety!"'),
  ('en.yusufali', 21, 60, 'They said, "We heard a youth talk of them: He is called Abraham."'),
  ('en.yusufali', 21, 61, 'They said, "Then bring him before the eyes of the people, that they may bear witness."'),
  ('en.yusufali', 21, 62, 'They said, "Art thou the one that did this with our gods, O Abraham?"'),
  ('en.yusufali', 21, 63, 'He said: "Nay, this was done by - this is their biggest one! ask them, if they can speak intelligently!"'),
  ('en.yusufali', 21, 64, 'So they turned to themselves and said, "Surely ye are the ones in the wrong!"'),
  ('en.yusufali', 21, 65, 'Then were they confounded with shame: (they said), "Thou knowest full well that these (idols) do not speak!"'),
  ('en.yusufali', 21, 66, '(Abraham) said, "Do ye then worship, besides Allah, things that can neither be of any good to you nor do you harm?'),
  ('en.yusufali', 21, 67, '"Fie upon you, and upon the things that ye worship besides Allah! Have ye no sense?"..'),
  ('en.yusufali', 21, 68, 'They said, "Burn him and protect your gods, If ye do (anything at all)!"'),
  ('en.yusufali', 21, 69, 'We said, "O Fire! be thou cool, and (a means of) safety for Abraham!"'),
  ('en.yusufali', 21, 70, 'Then they sought a stratagem against him: but We made them the ones that lost most!'),
  ('en.yusufali', 21, 71, 'But We delivered him and (his nephew) Lut (and directed them) to the land which We have blessed for the nations.'),
  ('en.yusufali', 21, 72, 'And We bestowed on him Isaac and, as an additional gift, (a grandson), Jacob, and We made righteous men of every one (of them).'),
  ('en.yusufali', 21, 73, 'And We made them leaders, guiding (men) by Our Command, and We sent them inspiration to do good deeds, to establish regular prayers, and to practise regular charity; and they constantly served Us (and Us only).'),
  ('en.yusufali', 21, 74, 'And to Lut, too, We gave Judgment and Knowledge, and We saved him from the town which practised abominations: truly they were a people given to Evil, a rebellious people.'),
  ('en.yusufali', 21, 75, 'And We admitted him to Our Mercy: for he was one of the Righteous.'),
  ('en.yusufali', 21, 76, '(Remember) Noah, when he cried (to Us) aforetime: We listened to his (prayer) and delivered him and his family from great distress.'),
  ('en.yusufali', 21, 77, 'We helped him against people who rejected Our Signs: truly they were a people given to Evil: so We drowned them (in the Flood) all together.'),
  ('en.yusufali', 21, 78, 'And remember David and Solomon, when they gave judgment in the matter of the field into which the sheep of certain people had strayed by night: We did witness their judgment.'),
  ('en.yusufali', 21, 79, 'To Solomon We inspired the (right) understanding of the matter: to each (of them) We gave Judgment and Knowledge; it was Our power that made the hills and the birds celebrate Our praises, with David: it was We Who did (all these things).'),
  ('en.yusufali', 21, 80, 'It was We Who taught him the making of coats of mail for your benefit, to guard you from each other\'s violence: will ye then be grateful?'),
  ('en.yusufali', 21, 81, '(It was Our power that made) the violent (unruly) wind flow (tamely) for Solomon, to his order, to the land which We had blessed: for We do know all things.'),
  ('en.yusufali', 21, 82, 'And of the evil ones, were some who dived for him, and did other work besides; and it was We Who guarded them.'),
  ('en.yusufali', 21, 83, 'And (remember) Job, when He cried to his Lord, "Truly distress has seized me, but Thou art the Most Merciful of those that are merciful."'),
  ('en.yusufali', 21, 84, 'So We listened to him: We removed the distress that was on him, and We restored his people to him, and doubled their number,- as a Grace from Ourselves, and a thing for commemoration, for all who serve Us.'),
  ('en.yusufali', 21, 85, 'And (remember) Isma\'il, Idris, and Zul-kifl, all (men) of constancy and patience;'),
  ('en.yusufali', 21, 86, 'We admitted them to Our mercy: for they were of the righteous ones.'),
  ('en.yusufali', 21, 87, 'And remember Zun-nun, when he departed in wrath: He imagined that We had no power over him! But he cried through the deptHs of darkness, "There is no god but thou: glory to thee: I was indeed wrong!"'),
  ('en.yusufali', 21, 88, 'So We listened to him: and delivered him from distress: and thus do We deliver those who have faith.'),
  ('en.yusufali', 21, 89, 'And (remember) Zakariya, when he cried to his Lord: "O my Lord! leave me not without offspring, though thou art the best of inheritors."'),
  ('en.yusufali', 21, 90, 'So We listened to him: and We granted him Yahya: We cured his wife\'s (Barrenness) for him. These (three) were ever quick in emulation in good works; they used to call on Us with love and reverence, and humble themselves before Us.'),
  ('en.yusufali', 21, 91, 'And (remember) her who guarded her chastity: We breathed into her of Our spirit, and We made her and her son a sign for all peoples.'),
  ('en.yusufali', 21, 92, 'Verily, this brotherhood of yours is a single brotherhood, and I am your Lord and Cherisher: therefore serve Me (and no other).'),
  ('en.yusufali', 21, 93, 'But (later generations) cut off their affair (of unity), one from another: (yet) will they all return to Us.'),
  ('en.yusufali', 21, 94, 'Whoever works any act of righteousness and has faith,- His endeavour will not be rejected: We shall record it in his favour.'),
  ('en.yusufali', 21, 95, 'But there is a ban on any population which We have destroyed: that they shall not return,'),
  ('en.yusufali', 21, 96, 'Until the Gog and Magog (people) are let through (their barrier), and they swiftly swarm from every hill.'),
  ('en.yusufali', 21, 97, 'Then will the true promise draw nigh (of fulfilment): then behold! the eyes of the Unbelievers will fixedly stare in horror: "Ah! Woe to us! we were indeed heedless of this; nay, we truly did wrong!"'),
  ('en.yusufali', 21, 98, 'Verily ye, (unbelievers), and the (false) gods that ye worship besides Allah, are (but) fuel for Hell! to it will ye (surely) come!'),
  ('en.yusufali', 21, 99, 'If these had been gods, they would not have got there! but each one will abide therein.'),
  ('en.yusufali', 21, 100, 'There, sobbing will be their lot, nor will they there hear (aught else).'),
  ('en.yusufali', 21, 101, 'Those for whom the good (record) from Us has gone before, will be removed far therefrom.'),
  ('en.yusufali', 21, 102, 'Not the slightest sound will they hear of Hell: what their souls desired, in that will they dwell.'),
  ('en.yusufali', 21, 103, 'The Great Terror will bring them no grief: but the angels will meet them (with mutual greetings): "This is your Day,- (the Day) that ye were promised."'),
  ('en.yusufali', 21, 104, 'The Day that We roll up the heavens like a scroll rolled up for books (completed),- even as We produced the first creation, so shall We produce a new one: a promise We have undertaken: truly shall We fulfil it.'),
  ('en.yusufali', 21, 105, 'Before this We wrote in the Psalms, after the Message (given to Moses): My servants the righteous, shall inherit the earth."'),
  ('en.yusufali', 21, 106, 'Verily in this (Qur\'an) is a Message for people who would (truly) worship Allah.'),
  ('en.yusufali', 21, 107, 'We sent thee not, but as a Mercy for all creatures.'),
  ('en.yusufali', 21, 108, 'Say: "What has come to me by inspiration is that your Allah is One Allah: will ye therefore bow to His Will (in Islam)?"'),
  ('en.yusufali', 21, 109, 'But if they turn back, Say: "I have proclaimed the Message to you all alike and in truth; but I know not whether that which ye are promised is near or far.'),
  ('en.yusufali', 21, 110, '"It is He Who knows what is open in speech and what ye hide (in your hearts).'),
  ('en.yusufali', 21, 111, '"I know not but that it may be a trial for you, and a grant of (worldly) livelihood (to you) for a time."'),
  ('en.yusufali', 21, 112, 'Say: "O my Lord! judge Thou in truth!" "Our Lord Most Gracious is the One Whose assistance should be sought against the blasphemies ye utter!"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 21, 1, 'Iqtaraba linnaasi hisaa buhum wa hum fee ghaflatim mu\'ridoon'),
  ('en.transliteration', 21, 2, 'Maa yaateehim min zikrim mir Rabbihim muhdasin illas tama\'oohu wa hum yal\'aboon'),
  ('en.transliteration', 21, 3, 'Laahiyatan quloobuhum; wa asarrun najwal lazeena zalamoo hal haazaa illaa basharum mislukum afataa toonas sihra wa antum tubsiroon'),
  ('en.transliteration', 21, 4, 'Qaala Rabbee ya\'lamul qawla fis samaaa\'i wal ardi wa Huwas Samee\'ul Aleem'),
  ('en.transliteration', 21, 5, 'Bal qaalooo adghaasu ahlaamim balif taraahu bal huwa shaa\'irun falyaatinaa bi Aayatin kamaa ursilal awwaloon'),
  ('en.transliteration', 21, 6, 'Maaa aaamanat qablahum min qaryatin ahlaknaahaa a-fahum yu\'minoon'),
  ('en.transliteration', 21, 7, 'Wa maaa arsalnaa qablaka illaa rijaalan nooheee ilaihim fas\'aloo ahlaz zikri in kuntum laa ta\'lamoon'),
  ('en.transliteration', 21, 8, 'Wa maa ja\'alnaahum jasadal laa yaakuloonat ta\'aama wa maa kaanoo khaalideen'),
  ('en.transliteration', 21, 9, 'summa sadaqnaa humul wa\'da fa-anjainaahum wa man nashaaa\'u wa ahlaknal musrifeen'),
  ('en.transliteration', 21, 10, 'Laqad anzalnaaa ilaikum Kitaaban feehi zikrukum afalaa ta\'qiloon'),
  ('en.transliteration', 21, 11, 'Wa kam qasamnaa min qaryatin kannat zaalimatanw wa anshadnaa ba\'dahaa qawman aakhareen'),
  ('en.transliteration', 21, 12, 'Falammaaa ahassoo baasanaaa izaaa hum minhaa yarkudoon'),
  ('en.transliteration', 21, 13, 'Laa tarkudoo warji\'ooo ilaa maaa utriftum feehe wa masaakinikum la\'allakum tus\'aloon'),
  ('en.transliteration', 21, 14, 'Qaaloo yaa wailanaaa innaa kunnaa zaalimeen'),
  ('en.transliteration', 21, 15, 'Famaa zaalat tilka da\'waahum hattaa ja\'alnaahum haseedan khaamideen'),
  ('en.transliteration', 21, 16, 'Wa maa khalaqnas samaaa\'a wal arda wa maa bainahumaa laa\'ibeen'),
  ('en.transliteration', 21, 17, 'Law aradnaaa an nattakhiza lahwal lat takhaznaahu mil ladunnaaa in kunnaa faa\'ileen'),
  ('en.transliteration', 21, 18, 'Bal naqzifu bilhaqqi \'alal baatili fa yadmaghuhoo fa izaa huwa zaahiq; wa lakumul wailu mimmaa tasifoon'),
  ('en.transliteration', 21, 19, 'Wa lahoo man fis samaawaati wal ard; wa man \'indahoo laa yastakbiroona \'an \'ibaada tihee wa laa yastahsiroon'),
  ('en.transliteration', 21, 20, 'Yusabbihoona laila wannahaara laa yafturoon'),
  ('en.transliteration', 21, 21, 'Amit takhazooo aalihatam minal ardi hum yunshiroon'),
  ('en.transliteration', 21, 22, 'Law kaana feehimaaa aalihatun illal laahu lafasadataa; fa-Subhaanal laahi Rabbil \'Arshi \'ammaa yasifoon'),
  ('en.transliteration', 21, 23, 'Laa yus\'alu \'ammaa yaf\'alu wa hum yus\'aloon'),
  ('en.transliteration', 21, 24, 'Amit takhazoo min doonihee aalihatan qul haatoo burhaanakum haaza zikru mam ma\'iya wa zikru man qablee; bal aksaruhum laa ya\'lamoonal haqqa fahum mu\'ridoon'),
  ('en.transliteration', 21, 25, 'Wa maaa arsalnaa min qablika mir Rasoolin illaa nooheee ilaihi annahoo laaa ilaaha illaaa Ana fa\'budoon'),
  ('en.transliteration', 21, 26, 'Wa qaalut takhazar Rahmaanu waladan Subhaanah; bal \'ibaadum mkkramoon'),
  ('en.transliteration', 21, 27, 'Laa yasbiqoonahoo bil qawli wa hum bi amrihee ya\'maloon'),
  ('en.transliteration', 21, 28, 'Ya\'lamu maa baina aideehim wa maa khalfahum wa laa yashfa\'oona illaa limanir tadaa wa hum min khash yatihee mushfiqoon'),
  ('en.transliteration', 21, 29, 'Wa mai yaqul minhum inneee ilaahum min doonihee fazaalika najzeehi Jahannam; kazaalika najziz zaalimeen'),
  ('en.transliteration', 21, 30, 'Awalam yaral lazeena kafarooo annas samaawaati wal arda kaanataa ratqan faftaqnaahumaa wa ja\'alnaa minal maaa\'i kulla shai\'in haiyin afalaa yu\'minoon'),
  ('en.transliteration', 21, 31, 'Wa ja\'alnaa fil ardi rawaasiya an tameeda bihim wa ja\'alnaa feehaa fijaajan subulal la\'allahum yahtadoon'),
  ('en.transliteration', 21, 32, 'Wa ja\'alnas samaaa\'a saqfam mahfoozanw wa hum \'an Aayaatihaa mu\'ridoon'),
  ('en.transliteration', 21, 33, 'Wa Huwal lazee khalaqal laila wannahaara washshamsa wal qamara kullun fee falakiny yashbahoon'),
  ('en.transliteration', 21, 34, 'Wa maa ja\'alnaa libasharim min qablikal khuld; afaimmitta fahumul khaalidoon'),
  ('en.transliteration', 21, 35, 'Kullu nafsin zaaa\'iqatul mawt; wa nablookum bishsharri walkhairi fitnatanw wa ilainaa turja\'oon'),
  ('en.transliteration', 21, 36, 'Wa izaa ra aakal lazeena kafarooo iny-yattakhizoonaka illa huzuwaa; ahaazal lazee yazkuru aalihatakum wa hum bi zikrir Rahmaani hum kaafiroon'),
  ('en.transliteration', 21, 37, 'Khuliqal insaanu min \'ajal; sa ureekum Aayaatee falaa tasta\'jiloon'),
  ('en.transliteration', 21, 38, 'Wa yaqooloona mataa haazal wa\'du in kuntum saadiqeen'),
  ('en.transliteration', 21, 39, 'Law ya\'lamul lazeena kafaroo heena laa yakuffoona \'anw wujoohihimun Naara wa laa \'an zuhoorihim wa laa hum yunsaroon'),
  ('en.transliteration', 21, 40, 'Bal taateehim baghtatan fatabhatuhum falaa yastatee\'oona raddahaa wa laa hum yunzaroon'),
  ('en.transliteration', 21, 41, 'Wa laqadis tuhzi\'a bi-Rusulim min qablika fahaaqa billazeena sakhiroo minhum maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 21, 42, 'Qul mai yakla \'ukum billaili wannahaari minar Rahmaan; bal hum \'an zikri Rabbihim mu\'ridoon'),
  ('en.transliteration', 21, 43, 'Am lahum aalihatun tamna\'ulum min dooninaa; laa yastatee\'oona nasra anfusihim wa laa hum minnna yus-haboon'),
  ('en.transliteration', 21, 44, 'Bal matta\'naa haaa\'ulaaa\'i wa aabaaa\'ahum hattaa taala \'alaihimul \'umur; afalaa yarawna anna naatil arda nanqusuhaa min atraafihaa; afahumul ghaaliboon'),
  ('en.transliteration', 21, 45, 'Qul innamaaa unzirukum bilwahyi; wa laa yasma\'us summud du\'aaa\'a izaa maa yunzaroon'),
  ('en.transliteration', 21, 46, 'Wa la\'im massat hum nafhatum min \'azaabi Rabbika la yaqoolunna yaawailanaaa innnaa kunnaa zaalimeen'),
  ('en.transliteration', 21, 47, 'Wa nada\'ul mawaazeenal qista li Yawmil Qiyaamati falaa tuzlamu nafsun shai\'aa; wa in kaana misqaala habbatim min khardalin atainaa bihaa; wa kafaa binaa haasibeen'),
  ('en.transliteration', 21, 48, 'Wa laqad aatainaa Moosa wa haaroonal Furqaana wa diyaa\'anw wa zikral lilmuttaqeen'),
  ('en.transliteration', 21, 49, 'Allazeena yakhshawna Rabbahum bilghaibi wa hum minas Saa\'ati mushfiqoon'),
  ('en.transliteration', 21, 50, 'Wa haazaa Zikrum Mubaarakun anzalnaah; afa antum lahoo munkiroon'),
  ('en.transliteration', 21, 51, 'Wa laqad aatainaaa Ibraaheema rushdahoo min qablu wa kunnaa bihee \'aalimeen'),
  ('en.transliteration', 21, 52, 'Iz qaala li abeehi wa qawmihee maa haazihit tamaaseelul lateee antum lahee \'aakifoon'),
  ('en.transliteration', 21, 53, 'Qaaloo wajadnaaa aabaaa\'anaa lahaa \'aabideen'),
  ('en.transliteration', 21, 54, 'Qaala laqad kuntum antum wa aabaaa\'ukum fee dalaalim mubeen'),
  ('en.transliteration', 21, 55, 'Qaalooo aji\'tanaa bil haqqi am anta minal laa\'ibeen'),
  ('en.transliteration', 21, 56, 'Qaala bar Rabbukum Rabbus samaawaati wal ardil lazee fatarahunna wa ana \'alaa zaalikum minash shaahideen'),
  ('en.transliteration', 21, 57, 'Wa tallaahi la akeedanna asnaamakum ba\'da an tuwalloo mudbireen'),
  ('en.transliteration', 21, 58, 'Faja\'alahum juzaazan illaa kabeeral lahum la\'allahum ilaihi yarji\'oon'),
  ('en.transliteration', 21, 59, 'Qaaloo man fa\'ala haazaa bi aalihatinaaa innahoo laminaz zaalimeen'),
  ('en.transliteration', 21, 60, 'Qaaloo sami\'naa fatany yazkuruhum yuqaalu lahooo Ibraaheem'),
  ('en.transliteration', 21, 61, 'Qaaloo faatoo bihee \'alaaa a\'yunin naasi la\'allahum yash hadoon'),
  ('en.transliteration', 21, 62, 'Qaalooo \'a-anta fa\'alta haazaa bi aalihatinaa yaaa Ibraaheem'),
  ('en.transliteration', 21, 63, 'Qaala bal fa\'alahoo kabeeruhum haazaa fas\'aloohum in kaanoo yantiqoon'),
  ('en.transliteration', 21, 64, 'Faraja\'ooo ilaaa anfusihim faqaalooo innakum antumuz zaalimoon'),
  ('en.transliteration', 21, 65, 'Summa nukisoo \'alaa ru\'oosihim laqad \'alimta maa haaa\'ulaaa\'i yantiqoon'),
  ('en.transliteration', 21, 66, 'Qaala afata\'budoona min doonil laahi maa laa yanfa\'ukum shai\'anw wa laa yadurrukum'),
  ('en.transliteration', 21, 67, 'Uffil lakum wa limaa ta\'budoona min doonil laah; afalaa ta\'qiloon'),
  ('en.transliteration', 21, 68, 'Qaaloo harriqooho wansurooo aalihatakum in kuntum faa\'ileen'),
  ('en.transliteration', 21, 69, 'Qulnaa yaa naaru koonee bardanw wa salaaman \'alaaa Ibraaheem'),
  ('en.transliteration', 21, 70, 'Wa araadoo bihee kaidan faja\'alnaahumul akhsareen'),
  ('en.transliteration', 21, 71, 'Wa najjainaahu wa Lootan ilal ardil latee baaraknaa feehaa lil \'aalameen'),
  ('en.transliteration', 21, 72, 'Wa wahabnaa lahooo Ishaaq; wa Ya\'qooba naafilah; wa kullan ja\'alnaa saaliheen'),
  ('en.transliteration', 21, 73, 'Wa ja\'alnaahum a\'immatany yahdoona bi amrinaa wa awhainaaa ilaihim fi\'lal khairaati wa iqaamas Salaati wa eetaaa\'az Zakaati wa kaanoo lanaa \'aabideen'),
  ('en.transliteration', 21, 74, 'Wa Lootan aatainaahu hukmanw wa \'ilmanw wa najjainaahu minal qaryatil latee kaanat ta\'malul khabaaa\'is; innahum kaanoo qawma saw\'in faasiqeen'),
  ('en.transliteration', 21, 75, 'Wa adkhalnaahu fee rahmatinaa innahoo minas saalihee'),
  ('en.transliteration', 21, 76, 'Wa noohan iz naadaa min qablu fastajabnaa lahoo fanajjainaahu wa ahlahoo minal karbil \'azeem'),
  ('en.transliteration', 21, 77, 'Wa nasarnaahu minal qawmil lazeena kazzaboo bi Aayaatinaa; innahum kkaanoo qawma saw\'in fa-aghraq naahum ajma\'een'),
  ('en.transliteration', 21, 78, 'Wa Daawooda wa Sulaimaana iz yahkumaani fil harsi iz nafashat feehi ghanamul qawmi wa kunnaa lihukmihim shaahideen'),
  ('en.transliteration', 21, 79, 'Fafahhamnaahaa sulaimaan; wa kullan aatainaa hukmanw wa\'ilmanw wa sakh kharnaa ma\'a Daawoodal jibaala yusabbihna wattayr; wa kunnaa faa\'ileen'),
  ('en.transliteration', 21, 80, 'Wa \'allamanaahu san\'ata laboosil lakum lituhsinakum mim baasikum fahal antum shaakiroon'),
  ('en.transliteration', 21, 81, 'Wa li Sulaimaanar reeha \'aasifatan tajree bi amriheee ilal ardil latee baaraknaa feehaa; wa kunnaa bikulli shai\'in \'aalimeen'),
  ('en.transliteration', 21, 82, 'Wa minash Shayaateeni mai yaghoosoona lahoo wa ya\'maloona \'amalan doona zaalika wa kunna lahum baafizeen'),
  ('en.transliteration', 21, 83, 'Wa Ayyooba iz naadaa Rabbahooo annee massaniyad durru wa Anta arhamur raahimeen'),
  ('en.transliteration', 21, 84, 'Fastajabnaa lahoo fakashaf naa maa bihee min durrinw wa aatainaahu ahlahoo wa mislahum ma\'ahum rahmatam min \'indinaa wa zikraa lil\'aabideen'),
  ('en.transliteration', 21, 85, 'Wa Ismaa\'eela wa Idreesa wa Zal Kifli kullum minas saabireen'),
  ('en.transliteration', 21, 86, 'Wa adkhalnaahum fee rahmatinaa innahum minas saaliheen'),
  ('en.transliteration', 21, 87, 'Wa Zan Nooni iz zahaba mughaadiban fazaanna al lan naqdira \'alaihi fanaanna al lan naqdira \'alaihi fanaadaa fiz zulumaati al laaa ilaaha illaaa Anta Subhaanaka innee kuntu minaz zaalimeen'),
  ('en.transliteration', 21, 88, 'Fastajabnaa lahoo wa najjainaahu minal ghamm; wa kazaalika nunjil mu\'mineen'),
  ('en.transliteration', 21, 89, 'Wa Zakariyyaaa iz naadaa Rabbahoo Rabbi laa tazarnee fardanw wa Anta khairul waariseen'),
  ('en.transliteration', 21, 90, 'Fastajabnaa lahoo wa wahabnaa lahoo Yahyaa Wa aslahnaa lahoo zawjah; innahum kaanoo yusaari\'oona fil khairaati wa yad\'oonanaa raghabanw wa rahabaa; wa kaanoo lanaa khaashi\'een'),
  ('en.transliteration', 21, 91, 'Wallateee ahsanat farjahaa fanafakhnaa feehaa mir roohinaa wa ja\'alnaahaa wabnahaaa Aayatal lil\'aalameen'),
  ('en.transliteration', 21, 92, 'Inna haaziheee ummatukum ummatanw waahidatanw wa Ana Rabbukum fa\'budoon'),
  ('en.transliteration', 21, 93, 'Wa taqatta\'ooo amrahum bainahum kullun ilainaaa raaji\'oon'),
  ('en.transliteration', 21, 94, 'Famai ya\'mal minas saalihaati wa huwa mu\'minun falaa kufraana lisa\'yihee wa innaa lahoo kaatiboon'),
  ('en.transliteration', 21, 95, 'Wa haraamun \'alaa qaryatin ahlaknaahaaa annahum laa yarji\'oon'),
  ('en.transliteration', 21, 96, 'Hattaaa izaa futihat Yaajooju wa Maajooju wa hum min kulli hadabiny yansiloon'),
  ('en.transliteration', 21, 97, 'Waqtarabal wa\'dul haqqu fa-izaa hiya shaakhisatun absaarul lazeena kafaroo yaawailanaa qad kunna fee ghaflatim min haaza bal kunnaa zaalimeen'),
  ('en.transliteration', 21, 98, 'Innakum wa maa ta\'budoona min doonil laahi hasabu Jahannama antum lahaa waaridoon'),
  ('en.transliteration', 21, 99, 'Law kaana haaa\'ulaaa\'i aalihatam maa waradoohaa wa kullun feehaa khaalidoon'),
  ('en.transliteration', 21, 100, 'Lahum feehaa zafeerunw wa hum feehaa laa yasma\'oon'),
  ('en.transliteration', 21, 101, 'Innal lazeena sabaqat lahum minnal husnaaa ulaaa\'ika \'anhaa mub\'adoon'),
  ('en.transliteration', 21, 102, 'Laa yasma\'oona hasee sahaa wa hum fee mash tahat anfusuhum khaalidoon'),
  ('en.transliteration', 21, 103, 'Laa yahzunuhumul faza\'ul akbaru wa tatalaq qaahumul malaaa\'ikatu haazaa Yawmukumul lazee kuntum too\'adoon'),
  ('en.transliteration', 21, 104, 'Yawma natwis samaaa\'a kataiyis sijilli lilkutub; kamaa badaanaa awwala khalqin nu\'eeduh; wa\'dan \'alainaa; innaa kunna faa\'ileen'),
  ('en.transliteration', 21, 105, 'Wa laqad katabnaa fiz Zaboori mim ba\'diz zikri annal arda yarisuhaa \'ibaadi yas saalihoon'),
  ('en.transliteration', 21, 106, 'Inna fee haaza labalaa ghal liqawmin \'aabideen'),
  ('en.transliteration', 21, 107, 'Wa maaa arsalnaaka illaa rahmatal lil\'aalameen'),
  ('en.transliteration', 21, 108, 'Qul innamaa yoohaa ilaiya annamaaa ilaahukum illaahunw Waahid, fahal antum muslimoon'),
  ('en.transliteration', 21, 109, 'Fa in tawallaw faqul aazantukum \'alaa sawaaa\'; wa in adreee aqareebun am ba\'eedum maa too\'adoon'),
  ('en.transliteration', 21, 110, 'Innahoo ya\'lamul jahra minal qawli wa ya\'lamu maa taktumoon'),
  ('en.transliteration', 21, 111, 'Wa in adree la\'allahoo fitnatul lakum wa mataa\'un ilaaheen'),
  ('en.transliteration', 21, 112, 'Qaala Rabbih kum bil haqq; wa Rabbunar Rahmaa nul musta\'aanu \'alaa maa tasifoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 21, 1, 'لوگو ں کے حساب کا وقت قریب آ گیا ہے اوروہ غفلت میں پڑ کر منہ پھیرنے والے ہیں'),
  ('ur.ahmedali', 21, 2, 'ان کے رب کی طرف سمجھانے کے لیے کوئی ایسی نئی بات ان کے پاس نہیں آتی کہ جسے سن کر ہنسی میں نہ ٹال دیتے ہوں'),
  ('ur.ahmedali', 21, 3, 'ان کے دل کھیل میں لگے ہوئے ہیں اور ظالم پوشیدہ سرگوشیاں کرتے ہیں کہ یہ تمہاری طرح ایک انسان ہی تو ہے پھر کیا تم دیدہ دانستہ جادو کی باتیں سنتے جاتے ہو'),
  ('ur.ahmedali', 21, 4, 'رسول نے کہا میرا رب آسمان اور زمین کی سب باتیں جانتا ہے اور وہ سننے والا اور جاننے والا ہے'),
  ('ur.ahmedali', 21, 5, 'بلکہ کہتے ہیں کہ یہ بیہودہ خواب ہیں بلکہ اس نے جھوٹ بنایا ہے بلکہ وہ شاعر ہے پھر چاہیے کہ ہمارے پاس کوئی نشانی لائے جس طرح پہلے پیغمبر بھیجے گئے تھے'),
  ('ur.ahmedali', 21, 6, 'ان سے پہلے کوئی بستی ایمان نہیں لائی تھی جسے ہم نے ہلاک کیا کیا اب یہ ایمان لائیں گے'),
  ('ur.ahmedali', 21, 7, 'اور ہم نے تم سے پہلے بھی تو آدمیوں ہی کو رسول بنا کر بھیجا تھا ان کی طرف ہم وحی بھیجا کرتے تھے اگر تم نہیں جانتے تو علم والوں سے پوچھ لو'),
  ('ur.ahmedali', 21, 8, 'او رہم نے ان کے ایسے بدن بھی نہیں بنائے تھے کہ وہ کھانانہ کھائیں اور نہ وہ ہمیشہ رہنے والے تھے'),
  ('ur.ahmedali', 21, 9, 'پھر ہم نے ان سے وعدہ سچا کر دیا تب انہیں اور جسے ہم نے چاہا نجات دی اور ہم نے حد سے بڑھنے والوں کوہلاک کر دیا'),
  ('ur.ahmedali', 21, 10, 'البتہ تحقیق ہم نے تمہارے پاس ایک ایسی کتاب بھیجی ہے جس میں تمہاری نصیحت ہے کیا پس تم نہیں سمجھتے'),
  ('ur.ahmedali', 21, 11, 'اور ہم نے بہت سی بستیوں کو جو ظالم تھیں غارت کر دیا ہے اور ان کے بعد ہم نے اور قومیں پیدا کیں'),
  ('ur.ahmedali', 21, 12, 'پھر جب انہوں نے ہمارے عذاب کی آہٹ پائی تو وہ فوراً وہاں سے بھاگنے لگے'),
  ('ur.ahmedali', 21, 13, 'مت بھاگو اور لوٹ جاؤ جہاں تم نے عیش کیا تھا اور اپنے گھروں میں جاؤ تاکہ تم سے پوچھا جائے'),
  ('ur.ahmedali', 21, 14, 'کہنے لگے ہائے ہماری کم بختی بے شک ہم ہی ظالم تھے'),
  ('ur.ahmedali', 21, 15, 'سو ان کی یہی پکار رہی یہاں تک کہ ہم نے انہیں ایسا کر دیا جس طرح کھیتی کٹی ہوئی ہو اور وہ بجھ کر رہ گئے'),
  ('ur.ahmedali', 21, 16, 'اور ہم نے آسمان اور زمین کو اورجو کچھ ان کے بیچ میں ہے کھیلتے ہوئے نہیں بنایا'),
  ('ur.ahmedali', 21, 17, 'اور اگر ہم کھیل ہی بنانا چاہتے تو اپنے پا س کی چیزوں کو بناتے اگر ہمیں یہی کرنا ہوتا'),
  ('ur.ahmedali', 21, 18, 'بلکہ ہم حق کو باطل پر پھینک مارتے ہیں پھر وہ باطل کا سر توڑ دیتا ہے پھر وہ مٹنے والا ہوتا ہے او رتم پر افسوس ہے ان باتوں سے جو تم بناتے ہو'),
  ('ur.ahmedali', 21, 19, 'اور اسی کا ہے جو کوئي آسمانوں اور زمین میں ہے اور جو اس کے ہاں ہیں اس کی عبادت سے سرکشی نہیں کرتےاور نہ تھکتے ہیں'),
  ('ur.ahmedali', 21, 20, 'رات اور دن تسبیح کرتے ہیں سستی نہیں کرتے'),
  ('ur.ahmedali', 21, 21, 'کیاانہوں نے زمین کی چیزوں سے ایسے معبود بنا رکھے ہیں جو زندہ کریں گے'),
  ('ur.ahmedali', 21, 22, 'اگر ان دونوں میں الله کے سوا اور معبود ہوتے تو دونوں خراب ہو جاتے سو الله عرش کا مالک ان باتوں سے پاک ہے جو یہ بیان کرتے ہیں'),
  ('ur.ahmedali', 21, 23, 'جو کچھ وہ کرتاہے اس سے پوچھا نہیں جاتا اور وہ پوچھے جاتے ہیں'),
  ('ur.ahmedali', 21, 24, 'کیا انہوں نے اس کے سوا اور بھی معبود بنا رکھے ہیں کہہ دو اپنی دلیل لاؤ یہ میرے ساتھ والو ں کی کتاب اور مجھ سے پہلے لوگوں کی کتابیں موجود ہیں بلکہ اکثران میں سے حق جانتے ہی نہیں اس لیے منہ پھیرے ہوئے ہیں'),
  ('ur.ahmedali', 21, 25, 'اور ہم نے تم سے پہلے ایسا کوئی رسول نہیں بھیجا جس کی طرف یہ وحی نہ کی ہو کہ میرے سوا اور کوئی معبود نہیں سومیری ہی عبادت کرو'),
  ('ur.ahmedali', 21, 26, 'اور کہتے ہیں کہ الله نے اولاد بنا رکھی ہے وہ پاک ہے لیکن وہ معزز بندے ہیں'),
  ('ur.ahmedali', 21, 27, 'بات کرنے میں اس سے پیش قدمی نہیں کرتے اور وہ اسی کے حکم پر کام کرتے ہیں'),
  ('ur.ahmedali', 21, 28, 'وہ جانتا ہے جو ان کے آگے اور جو ان کے پیچھے ہے اور وہ شفاعت بھی نہیں کرتے مگر اسی کے لیے جس سے وہ خوش ہو اور وہ اس کی ہیبت سے ڈرتے ہیں'),
  ('ur.ahmedali', 21, 29, 'اورجو کوئی ان میں سے یہ کہے کہ بے شک میں اس کے سوا خدا ہوں تو اسی پر ہم اسے جہنم کی سزاد یں گے ہم اسی طرح ظالموں کو سزا دیا کرتے ہیں'),
  ('ur.ahmedali', 21, 30, 'کیا منکروں نے نہیں دیکھا کہ آسمان اور زمین جڑے ہوئے تھے پھر ہم نے انھیں جدا جدا کر دیا اورہم نے ہر جاندار چیز کو پانی سے بنایا کیا پھر بھی یقین نہیں کرتے'),
  ('ur.ahmedali', 21, 31, 'اورہم نے زمین میں بھاری پہاڑ رکھ دیئے تاکہ انہیں لے کر داھر اُدھر نہ جھکنے پائے اور ہم نے اس میں کشادہ راہیں بنا دی ہیں تاکہ وہ راہ پائیں'),
  ('ur.ahmedali', 21, 32, 'اور ہم نے آسمان کو ایک محفوظ چھت بنا دیا اور وہ آسمان کی نشانیوں سے منہ موڑنے واے ہیں'),
  ('ur.ahmedali', 21, 33, 'اور وہی ہے جس نے رات اور دن اور سورج اور چاند بنائے سب اپنے اپنے چکر میں پھرتے ہیں'),
  ('ur.ahmedali', 21, 34, 'اور ہم نے تجھ سے پہلے کسی آدمی کو ہمیشہ کے لیے زندہ رہنے نہیں دیا پھر کیا اگر تو مر گیا تو وہ رہ جائیں گے'),
  ('ur.ahmedali', 21, 35, 'ہر ایک جاندار موت کا مزہ چکھنے والا ہے اور ہم تمہیں برائی اوربھلائی سے آزمانے کے لیے جانچتے ہیں اورہماری طرف لوٹائے جاؤ گے'),
  ('ur.ahmedali', 21, 36, 'اور جہاں تمہیں کافر دیکھتے ہیں تو انہیں تجھ سے سوائے ٹھٹھا کرنے کے اور کوئی کام نہیں کیا یہی شخص ہے جو تمہارے معبودوں کا نام لیتا ہے اور وہ رحمان کے نام سے منکر ہیں'),
  ('ur.ahmedali', 21, 37, 'آدمی جلد باز بنایا گیا ہے میں تمہیں اپنی نشانیاں ابھی دکھاتا ہوں سو جلدی مت کرو'),
  ('ur.ahmedali', 21, 38, 'ور کہتے ہیں یہ وعدہ کب ہوگا اگر تم سچے ہو'),
  ('ur.ahmedali', 21, 39, 'کاش یہ منکر اس وقت کو جان لیں کہ اپنے مونہوں اوراپنی پیٹھوں سے آگ کو روک نہیں سکیں گے اور نہ وہ مدد کیے جائیں گے'),
  ('ur.ahmedali', 21, 40, 'بلکہ وہ ان پر ناگہان آئے گی پھر وہ ان کے ہوش کھو دے گی پھر نہ اسے ٹال سکیں گے اورنہ انہیں مہلت دی جائے گی'),
  ('ur.ahmedali', 21, 41, 'اور تجھ سے پہلے بھی رسولوں کے ساتھ ٹھٹھا کیا گیا ہے پھر جس عذاب کی بابت وہ ہنسی کیا کرتے تھے ان ٹھٹھا کرنے والوں پر وہی آ پڑا'),
  ('ur.ahmedali', 21, 42, 'کہہ دو تمہاری رات اور دن میں رحمان سے کون نگہبانی کرتا ہے بلکہ وہ اپنے رب کے ذکر سے منہ موڑنے والے ہیں'),
  ('ur.ahmedali', 21, 43, 'کیا ہم سے ان کےمعبود انہیں بچائے رکھتے ہیں وہ تو خود اپنی بھی مدد نہیں کر سکتے اورنہ ہمارے مقابلہ میں ان کا کوئی ساتھ دے گا'),
  ('ur.ahmedali', 21, 44, 'بلکہ ہم نے ان کو اور ان کے باپ دادا کو خوب سامان دیا یہاں تک کہ ان پر ایک عرصہ دراز گزر گیا کیا وہ یہ نہیں دیکھتے کہ بے شک ہم زمین کو ہر طرف سے گھٹاتے چلے جاتے ہیں سو کیا یہ لوگ غالب آنے والے ہیں'),
  ('ur.ahmedali', 21, 45, 'کہہ دو کہ میں تو صرف وحی کے ذریعہ سے تمہیں ڈراتا ہوں اور یہ بہرے جس وقت ڈرائے جاتے ہیں سنتے ہی نہیں'),
  ('ur.ahmedali', 21, 46, 'اور البتہ اگر انہیں تیرے رب کا عذاب کا ایک جھونکا بھی لگ جائے تو ضرور کہیں گے کہ ہائے ہماری کم بختی بے شک ہم ظالم تھے'),
  ('ur.ahmedali', 21, 47, 'اور قیامت کے دن ہم انصاف کی ترازو قائم کریں گے پھرکسی پر کچھ ظلم نہ کیا جائے گا اور اگر رائی کے دانہ کے برابر بھی عمل ہو گا تو اسے بھی ہم لے آئیں گے اور ہم ہی حساب لینے کے لیے کافی ہیں'),
  ('ur.ahmedali', 21, 48, 'اور البتہ تحقیق ہم نے موسیٰ اور ہارون کو فیصلہ کرنے والی اور روشنی دینے والی اور پرہیز گاروں کو نصیحت کرنے والی کتاب دی تھی'),
  ('ur.ahmedali', 21, 49, 'جو اپنے رب سے بن دیکھے ڈرتے ہیں اور قیامت کا بھی خوف رکھنے والے ہیں'),
  ('ur.ahmedali', 21, 50, 'اور یہ ایک مبارک نصیحت ہے جسے ہم نازل کیاہے پھر کیا تم اس کے بھی منکر ہو'),
  ('ur.ahmedali', 21, 51, 'اور ہم نے پہلے ہی سے ابراھیم کو اس کی صلاحیت عطا کی تھی اور ہم اس سے واقف تھے'),
  ('ur.ahmedali', 21, 52, 'جب اس نے اپنے باپ اور اپنی قوم سے کہا کہ یہ کیسی مورتیں ہیں جن پر تم مجاور بنے بیٹھے ہو'),
  ('ur.ahmedali', 21, 53, 'انہوں نے کہا ہم نے اپنے باپ دااد کو انہیں کی پوجا کرتے پایا ہے'),
  ('ur.ahmedali', 21, 54, 'کہا البتہ تحقیق تم اور تمہارے باپ دادا صریح گمراہی میں رہے ہو'),
  ('ur.ahmedali', 21, 55, 'انھوں نے کہا کیا تو ہمارے پاس سچی بات لایا ہے یا تو دل لگی کرتا ہے'),
  ('ur.ahmedali', 21, 56, 'کہا بلکہ تمہارا رب تو آسمانوں اور زمین کا رب ہے جس نے انہیں بنایا ہے اور میں اسی بات کا قائل ہوں'),
  ('ur.ahmedali', 21, 57, 'اور الله کی قسم میں تمہارے بتوں کا علاج کروں گا جب تم پیٹھ پھیر کر جا چکو گے'),
  ('ur.ahmedali', 21, 58, 'پھر ان کے بڑے کے سوا سب کو ٹکڑے ٹکڑے کر دیا تاکہ اس کی طرف رجوع کریں'),
  ('ur.ahmedali', 21, 59, 'انہوں نے کہا ہمارے معبودوں کے ساتھ کس نے یہ کیا ہے بے شک وہ ظالموں میں سے ہے'),
  ('ur.ahmedali', 21, 60, 'انہو ں نے کہا ہم نے سنا ہے کہ ایک جو ان بتوں کو کچھ کہا کرتا ہے اسے ابراھیم کہتے ہیں'),
  ('ur.ahmedali', 21, 61, 'کہنے لگے اسے لوگوں کے سامنے لے آؤ تاکہ وہ دیکھیں'),
  ('ur.ahmedali', 21, 62, 'کہنے لگے اے ابراھیم کیا تو نے ہمارے معبودوں کے ساتھ یہ کیا ہے'),
  ('ur.ahmedali', 21, 63, 'کہا بلکہ ان کے اس بڑے نے یہ کیا ہے سو ان سے پوچھ لو اگر وہ بولتے ہیں'),
  ('ur.ahmedali', 21, 64, 'پھر وہ اپنے دل میں سوچ کر کہنے لگے بے شک تم ہی بے انصاف ہو'),
  ('ur.ahmedali', 21, 65, 'پھر انہو ں نے سر نیچا کر کے کہا تو جانتا ہے کہ یہ بولا نہیں کرتے'),
  ('ur.ahmedali', 21, 66, 'کہا پھر کیا تم الله کے سوا اس چیز کی پوجا کرتے ہو جو نہ تمہیں نفع دے سکےاور نہ نقصان پہنچا سکے'),
  ('ur.ahmedali', 21, 67, 'میں تم سے اور جنہیں الله کے سوا پوجتے ہو بیزار ہوں پھر کیا تمھیں عقل نہیں ہے'),
  ('ur.ahmedali', 21, 68, 'انھوں نے کہا اگر تمہیں کچھ کرنا ہے تو اسے جلا دو اور اپنے معبودوں کی مدد کرو'),
  ('ur.ahmedali', 21, 69, 'ہم نے کہا اے آگ ابراھیم پر سرد اورراحت ہو جا'),
  ('ur.ahmedali', 21, 70, 'اور انہوں نے اس کی برائی چاہی سو ہم نے انہیں ناکام کر دیا'),
  ('ur.ahmedali', 21, 71, 'اور ہم اسے اورلوط کو بچا کراس زمین کی طرف لے آئے جس میں ہم نے جہان کے لیے برکت رکھی ہے'),
  ('ur.ahmedali', 21, 72, 'اور ہم نے اسے اسحاق بخشا اور انعام میں یعقوب دیا اور سب کونیک بخت کیا'),
  ('ur.ahmedali', 21, 73, 'اورہم نے انہیں پیشوا بنایا جو ہمارے حکم سے رہنمائی کیا کرتے تھے اور ہم نے انہیں اچھے کام کرنے اور نماز قائم کرنے اور زکوٰة دینے کا حکم دیا تھا اور وہ ہماری ہی بندگی کیا کرتے تھے'),
  ('ur.ahmedali', 21, 74, 'اور لوط کو ہم نے حکمت اور علم عطا کیا تھا اور ہم اسے اس بستی سے جو گندے کام کیا کرتی تھی بچا کر لے آئے بے شک وہ لوگ برے نافرمانی کرنے والے تھے'),
  ('ur.ahmedali', 21, 75, 'اوراسے ہم نے اپنی رحمت میں لے لیا بے شک وہ نیک بختوں میں سے تھا'),
  ('ur.ahmedali', 21, 76, 'اور نوح کو جب اس نے اس سے پہلے پکارا پھر ہم نے اس کی دعا قبول کر لی پھر ہم نے اسے اور اس کے گھر والوں کو گھبراہٹ سے بچا لیا'),
  ('ur.ahmedali', 21, 77, 'اور ہم نے اس کی مدد کی ان لوگوں پر جو ہماری آیتیں جھٹلاتے تھے بے شک وہ بُرے لوگ تھے پھر ہم نے ان سب کو غرق کر دیا'),
  ('ur.ahmedali', 21, 78, 'اور داؤد اور سلیمان کو جب وہ کھیتی کے جھگڑا میں فیصلہ کرنے لگے جب کہ اس میں کچھ لوگوں کی بکریاں رات کے وقت جا پڑیں اور ہم اس فیصلہ کو دیکھ رہے تھے'),
  ('ur.ahmedali', 21, 79, 'پھر ہم نے وہ فیصلہ سلیمان کو سمجھا دیا اور ہر ایک کو ہم نے حکمت اور علم دیا تھا اور ہم نے داؤد کے ساتھ پہاڑ او رپرندے تابع کیے جو تسبیح کیا کرتے تھے اور یہ سب کچھ ہم ہی کرنے والے تھے'),
  ('ur.ahmedali', 21, 80, 'اور ہم نےاسے تمہارے لیے زر ہیں بنانا بھی سکھایا تاکہ تمہیں لڑائی میں محفوظ رکھیں پھر کیا تم شکر کرتے ہو'),
  ('ur.ahmedali', 21, 81, 'اور زور سے چلنے والی ہوا سلیمان کے تابع کی جو اس کے حکم سے اس زمین کی طرف چلتی جہاں ہم نے برکت دی ہے اور ہم ہر چیز کو جاننے والے ہیں'),
  ('ur.ahmedali', 21, 82, 'اورتو کچھ ایسے جن تھے جو دریا میں اس کے واسطے غوطہ لگاتے تھے اور اس کے سوا اور کام بھی کرتے تھے اور ہم ان کی حفاظت کرنے والے تھے'),
  ('ur.ahmedali', 21, 83, 'اورجب کہ ایوب نے اپنے رب کو پکارا کہ مجھے روگ لگ گیا ہے حالانکہ تو سب رحم کرنے والوں سے زیادہ رحم کرنے والا ہے'),
  ('ur.ahmedali', 21, 84, 'پھر ہم نے اس کی دعا قبول کی اورجواسے تکلیف تھی ہم نے دور کر دی اور اسے اس کے گھر والے دیئے اور اتنا ہی ان کے ساتھ اپنی رحمت سے اوربھی دیا اور عبادت کرنے والوں کے لیے نصیحت ہے'),
  ('ur.ahmedali', 21, 85, 'اور اسماعیل اور ادریس اور ذوالکفل کو یہ سب صبر کرنے والے تھے'),
  ('ur.ahmedali', 21, 86, 'اور ہم نے انہیں اپنی رحمت میں داخل کر لیا بے شک وہ نیک بختوں میں سے تھے'),
  ('ur.ahmedali', 21, 87, 'اور مچھلی والے کو جب غصہ ہو کر چلا گیا پھر خیال کیا کہ ہم اسے نہیں پکڑیں گے اندھیروں میں پکارا کہ تیرے سوا کوئی معبود نہیں ہے تو بے عیب ہے بے شک میں بے انصافوں میں سے تھا'),
  ('ur.ahmedali', 21, 88, 'پھر ہم نے اس کی دعا قبول کی اور اسے غم سے نجات دی اور ہم ایمان داروں کو یونہی نجات دیا کرتے ہیں'),
  ('ur.ahmedali', 21, 89, 'اور ذکریا کو جب اس نے اپنے رب کو پکارا اے رب مجھے اکیلا نہ چھوڑ اور تو سب سے بہتر وارث ہے'),
  ('ur.ahmedali', 21, 90, 'پھر ہم نے اس کی دعا قبول کی اور اسے یحییٰ عطا کیا اور اس کے لیے اس کی بیوی کو درست کر دیا بے شک یہ لوگ نیک کاموں میں دوڑ پڑتے تھے اور ہمیں امید اور ڈر سے پکارا کرتے تھے اور ہمارے سامنے عاجزی کرنے والے تھے'),
  ('ur.ahmedali', 21, 91, 'اوروہ عورت جس نے اپنی عصمت کو محفوظ رکھا پھر ہم نے اس میں اپنی روح پھونک دی اور اسے اور اس کے بیٹے کو جہان کے لیے نشانی بنایا'),
  ('ur.ahmedali', 21, 92, 'یہ لوگ تمہارے گروہ کے ہیں جو ایک ہی گروہ ہے اور میں تمہارا رب ہوں پھر میری ہی عبادت کرو'),
  ('ur.ahmedali', 21, 93, 'اور ان لوگوں نے اپنے دین میں اختلاف پیدا کر لیا سب ہمارے پاس ہی آنے والے ہیں'),
  ('ur.ahmedali', 21, 94, 'پھر جو کوئی اچھے کام کرے گا اور وہ مومن بھی ہوگا تو اس کی کوشش رائگان نہ جائے گی اوربے شک ہم اس کے لکھنے والے ہیں'),
  ('ur.ahmedali', 21, 95, 'اورجن بستیوں کو ہم فنا کر چکے ہیں ان کے لیے ناممکن ہے کہ وہ پھر لوٹ کر آئيں'),
  ('ur.ahmedali', 21, 96, 'یہاں تک کہ جب یاجوج اور ماجوج کھول دیئے جائیں گے اور وہ ہر بلندی سے دوڑتے چلے آئيں گے'),
  ('ur.ahmedali', 21, 97, 'اور سچا وعدہ نزدیک آ پہنچے گا پھر اس وقت منکرو ں کی آنکھیں اوپر لگی رہ جائیں گی ہائے کم بختی ہماری بے شک ہم تو اس سے غفلت میں پڑے ہوئے تھے بلکہ ہم ہی ظالم تھے'),
  ('ur.ahmedali', 21, 98, 'بے شک تم اور الله کے سوا جو کچھ پوجتے ہو دوزخ کا ایندھن ہے تم سب اس میں داخل ہو گے'),
  ('ur.ahmedali', 21, 99, 'اگر یہ معبود ہوتے تو اس میں داخل نہ ہوتے اور سب اس میں ہمیشہ رہنے والے ہیں'),
  ('ur.ahmedali', 21, 100, 'ان کے لیے دوزخ میں چیخیں ہو ں گی اوروہ اس میں کچھ نہیں سنیں گے'),
  ('ur.ahmedali', 21, 101, 'بے شک جن کے لیے ہماری طرف سے بھلائی مقدر ہو چکی ہے وہ اس سے دور رکھے جائیں گے'),
  ('ur.ahmedali', 21, 102, 'اس کی آہٹ بھی نہ سنیں گے اور وہ اپنی من مانی مرادوں میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 21, 103, 'اور انہیں بڑا بھاری خوف بھی پریشان نہیں کرے گا اور ان سے فرشتے آ ملیں گے یہی وہ تمہارا دن ہے جس کا تمہیں وعدہ دیا جاتا تھا'),
  ('ur.ahmedali', 21, 104, 'جس دن ہم آسمان کو اس طرح لپیٹیں گے جیسے خطوں کا طومار لپیٹا جاتا ہے جس طرح ہم نے پہلی بار پیدا کیا تھا دوبارہ بھی پیدا کریں گے یہ ہمارے ذمہ وعدہ ہے بے شک ہم پورا کرنے والے ہیں'),
  ('ur.ahmedali', 21, 105, 'اور البتہ تحقیق ہم نصیحت کے بعد زبور میں لکھ چکے ہیں کہ بے شک زمین کے وارث ہمارے نیک بندے ہی ہوں گے'),
  ('ur.ahmedali', 21, 106, 'بےشک اس میں خدا پرستوں کے لیے ایک پیغام ہے'),
  ('ur.ahmedali', 21, 107, 'او رہم نے توتمہیں تمام جہان کے لوگوں کے حق میں رحمت بنا کر بھیجا ہے'),
  ('ur.ahmedali', 21, 108, 'کہہ دو مجھے تو یہی حکم آیا ہے کہ تمہارا معبود ایک معبود ہے پھر کیا اس کے آگے سر جھکاتے ہو'),
  ('ur.ahmedali', 21, 109, 'پھر اگر وہ منہ موڑیں تو کہہ دو کہ میں نے یکساں طور پر خبر دے دی ہے اورمجھے معلوم نہیں کہ نزدیک ہے یا دور ہے جس کا تم سے وعدہ کیا جاتا ہے'),
  ('ur.ahmedali', 21, 110, 'بے شک وہ جانتا ہے جو بات پکار کر کہو اور جانتا ہے جو تم چھپاتے ہو'),
  ('ur.ahmedali', 21, 111, 'اور میں نہیں جانتا شاید وہ تمہارے لیے امتحان ہو اور ایک وقت تک دنیا کا فائدہ پہنچانا منظور ہو'),
  ('ur.ahmedali', 21, 112, 'کہ اے رب انصاف کا فیصلہ کر دے اور ہمارا رب بڑا مہربان ہے اسی سے مدد مانگتے ہیں ان باتوں پر جو تم بیان کرتے ہو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 21, 1, 'İnsanların hesap görme zamanı yaklaştı, fakat onlar hala habersiz, hakdan yüz çeviriyorlar.'),
  ('tr.diyanet', 21, 2, 'Rablerinden kendilerine gelen her yeni ihtarı mutlaka, gönülleri gaflet içinde eğlenerek dinlerler. Zulmedenler, gizli toplantılarında: "Bu zat, sizin gibi bir insandan başka bir şey midir? Siz, göz göre göre sihre mi uyarsınız?" diye konuşurlar.'),
  ('tr.diyanet', 21, 3, 'Rablerinden kendilerine gelen her yeni ihtarı mutlaka, gönülleri gaflet içinde eğlenerek dinlerler. Zulmedenler, gizli toplantılarında: "Bu zat, sizin gibi bir insandan başka bir şey midir? Siz, göz göre göre sihre mi uyarsınız?" diye konuşurlar.'),
  ('tr.diyanet', 21, 4, 'Peygamber: "Benim Rabbim gökte ve yerde söyleneni bilir. O, işitendir, bilendir" dedi.'),
  ('tr.diyanet', 21, 5, 'Onlar: "Hayır; bunlar karışık rüyalardır", "Hayır; onu uydurmuştur", "Hayır; o şairdir", "Haydi önceki peygamberler gibi o da bize bir mucize getirsin" dediler.'),
  ('tr.diyanet', 21, 6, 'Onlardan önce yoketmiş olduğumuz kasabalar halkı inanmadılar, bunlar mı inanacaklar?'),
  ('tr.diyanet', 21, 7, 'Senden önce de, kendilerine vahyettiğimiz adamlar gönderdik. Bilmiyorsanız kitablılara sorun.'),
  ('tr.diyanet', 21, 8, 'Biz onları yemek yemez birer ceset kılmadık ve onlar ölümsüz de değillerdi.'),
  ('tr.diyanet', 21, 9, 'Sonra Biz onlara verdiğimiz sözü yerine getirdik, kendilerini ve dilediklerimizi kurtardık; aşırı gidenleri ise yok ettik.'),
  ('tr.diyanet', 21, 10, 'And olsun ki, size şerefiniz ve öğüt veren bir Kitap indirdik; akletmiyor musunuz?'),
  ('tr.diyanet', 21, 11, 'Halkı zalim olan nice kasabaları kırıp geçirdik ve onlardan sonra başka milletler varettik.'),
  ('tr.diyanet', 21, 12, 'Onlar bizim baskınımızı hissettiklerinde, oradan kaçmağa koyuluyorlardı.'),
  ('tr.diyanet', 21, 13, '"Koşup kaçmayın; size nimet verilen yere, yurdlarınıza dönün, elbette sorguya çekileceksiniz" dedik.'),
  ('tr.diyanet', 21, 14, '"Vay başımıza gelenlere! Doğrusu biz haksızlık yapmış kimseleriz" dediler.'),
  ('tr.diyanet', 21, 15, 'Biz onları biçilmiş ot ve bir yığın kül haline getirinceye kadar haykırmaları devam etti.'),
  ('tr.diyanet', 21, 16, 'Biz gökleri, yeri ve ikisinin arasındakileri oyun olsun diye yaratmadık.'),
  ('tr.diyanet', 21, 17, 'Eğlenme dileseydik, bunu yapacak olsaydık, şanımıza uygun şekilde yapardık; ama yapmayız.'),
  ('tr.diyanet', 21, 18, 'Gerçeği batılın başına çarparız ve onun beynini parçalar; böylece batıl ortadan kalkar. Allah\'a yakıştırdığınız vasıflardan ötürü yazıklar olsun size!'),
  ('tr.diyanet', 21, 19, 'Göklerde ve yerde ne varsa O\'nundur. Katında olanlar O\'na kulluk etmekten çekinmezler ve usanmazlar.'),
  ('tr.diyanet', 21, 20, 'Gece ve gündüz, bıkmadan tesbih ederler.'),
  ('tr.diyanet', 21, 21, 'Yeryüzünde edindikleri tanrılar mı, onlar mı ölüleri diriltecekler?'),
  ('tr.diyanet', 21, 22, 'Eğer yerle gökte Allah\'tan başka tanrılar olsaydı, ikisi de bozulurdu. Arşın Rabbi olan Allah, onların vasıflandırdıklarından münezzehtir.'),
  ('tr.diyanet', 21, 23, 'O, yaptığından sorumlu değildir, onlar ise sorumlu tutulacaklardır.'),
  ('tr.diyanet', 21, 24, 'O\'nu bırakıp tanrılar mı edindiler? De ki: "Kesin delilinizi getirin. İşte benim ve ümmetimin Kitap\'ı ve senden öncekilerin kitapları." Hayır; onların çoğu gerçeği bilmez de yüz çevirirler.'),
  ('tr.diyanet', 21, 25, 'Senden önce gönderdiğimiz her peygambere: "Benden başka tanrı yoktur, Bana kulluk edin" diye vahyetmişizdir.'),
  ('tr.diyanet', 21, 26, '"Rahman çocuk edindi" dediler. Haşa; hayır, melekler şerefli kılınmış kullardır.'),
  ('tr.diyanet', 21, 27, 'Allah\'tan önce söz söyleyemezler; ancak O\'nun emri üzerine iş işlerler.'),
  ('tr.diyanet', 21, 28, 'Allah, onların yaptıklarını ve yapmakta olduklarını bilir. Onlar Allah\'ın hoşnut olduğu kimseden başkasına şefaat edemezler; O\'nun korkusundan titrerler.'),
  ('tr.diyanet', 21, 29, 'Bunlar içinde kim "Ben, Allah\'tan başka bir tanrıyım" derse, işte onu cehennemle cezalandırırız. Zulmedenlerin cezasını böyle veririz.'),
  ('tr.diyanet', 21, 30, 'İnkar edenler, gökler ve yer yapışıkken onları ayırdığımızı ve bütün canlıları sudan meydana getirdiğimizi bilmezler mi? İnanmıyorlar mı?'),
  ('tr.diyanet', 21, 31, 'Yeryüzüne, insanlar sarsılmasın diye sabit dağlar yerleştirdik; rahat gidebilsinler diye aralarında geniş yollar varettik.'),
  ('tr.diyanet', 21, 32, 'Göğü karışıklıktan korunmuş bir tavan kıldık; oysa onlar bundaki delillerden yüz çeviriyorlar.'),
  ('tr.diyanet', 21, 33, 'Geceyi ve gündüzü, güneşi ve ayı yaratan O\'dur. Her biri bir yörüngede yürür.'),
  ('tr.diyanet', 21, 34, 'Senden önce de hiçbir insanı ölümsüz kılmadık, sen ölürsün de onlar baki kalır mı?'),
  ('tr.diyanet', 21, 35, 'Her can ölümü tadacaktır. Bir imtihan olarak size iyilik ve kötülük veririz. Sonunda Bize dönersiniz.'),
  ('tr.diyanet', 21, 36, 'İnkarcılar seni gördükleri zaman, şüphesiz, seni alaya almaktan başka bir şey yapmazlar. "Sizin tanrılarınızı diline dolayan bu mudur?" derler ve Rahman\'ın Kitabını işte onlar inkar ederler.'),
  ('tr.diyanet', 21, 37, 'İnsan aceleci olarak yaratılmıştır. Size ayetlerimi göstereceğim, bunu Benden acele istemeyin.'),
  ('tr.diyanet', 21, 38, '"Doğru sözlü iseniz bildirin bu tehdit ne zamandır?" derler.'),
  ('tr.diyanet', 21, 39, 'Bu kafirler, ateşi yüzlerinden ve sırtlarından menedemeyecekleri ve yardım da göremiyecekleri zamanı keşke bilseler.'),
  ('tr.diyanet', 21, 40, 'Belki aniden gelecek de onları şaşırtacaktır. Artık onu geri çeviremezler; kendileri de ertelenmez.'),
  ('tr.diyanet', 21, 41, 'And olsun ki, senden önce birçok peygamber alaya alınmıştı da, alaya alanları, eğlendikleri şey mahvetmişti.'),
  ('tr.diyanet', 21, 42, 'De ki: "Geceleyin ve gündüzün sizi Rahman\'dan kim koruyabilir?" Ama onlar Rablerinin Kitabından yüz çevirmektedirler.'),
  ('tr.diyanet', 21, 43, 'Yoksa kendilerini bize karşı savunacak tanrıları mı var? O tanrılar kendilerine bile yardım edemezler. Katımızdan da dostluk görmezler.'),
  ('tr.diyanet', 21, 44, 'Biz bunlara ve babalarına geçimlikler verdik de ömürleri uzadı; şimdi memleketlerini her yandan eksilttiğimizi görmüyorlar mı? Üstün gelen onlar mıdır?'),
  ('tr.diyanet', 21, 45, 'De ki: "Ben ancak sizi vahy ile uyarıyorum" Uyarıldıkları zaman, sağırlar çağrıyı duymazlar.'),
  ('tr.diyanet', 21, 46, 'Rabbinin azabından onlara bir esinti dokunsa: "Vah bize! Doğrusu biz haksızdık" derler.'),
  ('tr.diyanet', 21, 47, 'Kıyamet günü doğru teraziler kurarız; hiçbir kimse hiçbir haksızlığa uğratılmaz. Hardal tanesi kadar olsa bile yapılanı ortaya koyarız. Hesap gören olarak Biz yeteriz.'),
  ('tr.diyanet', 21, 48, 'And olsun ki, Musa ve Harun\'a eğriyi doğrudan ayıran Kitap\'ı sakınanlar için ışık ve öğüt olarak verdik.'),
  ('tr.diyanet', 21, 49, 'Onlar görmedikleri halde Rablerinden korkarlar; kıyamet saatinden de titrerler.'),
  ('tr.diyanet', 21, 50, 'İşte bu, indirdiğimiz kutsal bir Kitap\'dır. Siz mi onu inkar ediyorsunuz?'),
  ('tr.diyanet', 21, 51, 'And olsun ki, daha önce İbrahim\'e de akla uygun olanı göstermiştik. Biz onu biliyorduk.'),
  ('tr.diyanet', 21, 52, 'İbrahim, babasına ve milletine: "Bu tapınıp durduğunuz heykeller nedir?" demişti.'),
  ('tr.diyanet', 21, 53, '"Babalarımızı onlara tapar bulduk" demişlerdi.'),
  ('tr.diyanet', 21, 54, 'İbrahim: "And olsun ki sizler de babalarınız da apaçık bir sapıklık içindesiniz" deyince:'),
  ('tr.diyanet', 21, 55, '"Sen bize gerçeği mi getirdin yoksa şaka mı ediyorsun?" dediler.'),
  ('tr.diyanet', 21, 56, 'O şöyle dedi: "Hayır; Rabbiniz, göklerin ve yerin Rabbidir ki onları O yaratmıştır. Ben de buna şahidlik edenlerdenim."'),
  ('tr.diyanet', 21, 57, '"Allah\'a yemin ederim ki, siz ayrıldıktan sonra, putlarınıza bir tuzak kuracağım!"'),
  ('tr.diyanet', 21, 58, 'Hepsini paramparça edip, içlerinden büyüğünü ona başvursunlar diye, sağlam bıraktı.'),
  ('tr.diyanet', 21, 59, 'Milleti: "Tanrılarımıza bunu kim yaptı? Doğrusu o zalimlerden biridir" dediler.'),
  ('tr.diyanet', 21, 60, 'Bazıları: "İbrahim denen bir gencin onları diline doladığını duymuştuk" deyince, "O halde bunların şahidlik edebilmeleri için onu halkın gözü önüne getirin" dediler.'),
  ('tr.diyanet', 21, 61, 'Bazıları: "İbrahim denen bir gencin onları diline doladığını duymuştuk" deyince, "O halde bunların şahidlik edebilmeleri için onu halkın gözü önüne getirin" dediler.'),
  ('tr.diyanet', 21, 62, 'İbrahim gelince, ona: "Ey İbrahim, bunu tanrılarımıza sen mi yaptın?" dediler.'),
  ('tr.diyanet', 21, 63, 'İbrahim: "Belki onu şu büyükleri yapmıştır, konuşabiliyorlarsa onlara sorun" dedi.'),
  ('tr.diyanet', 21, 64, 'Kendi kendilerine: "Doğrusu siz haksızsınız", sonra kafalarında olan eski inançlarına dönerek: "Ey İbrahim! bunların konuşmayacağını, and olsun ki, bilirsin" dediler.'),
  ('tr.diyanet', 21, 65, 'Kendi kendilerine: "Doğrusu siz haksızsınız", sonra kafalarında olan eski inançlarına dönerek: "Ey İbrahim! bunların konuşmayacağını, and olsun ki, bilirsin" dediler.'),
  ('tr.diyanet', 21, 66, 'İbrahim: "O halde, Allah\'ı bırakıp da size hiçbir fayda ve zarar veremeyecek olan putlara ne diye taparsınız? Size de, Allah\'ı bırakıp taptıklarınıza da yazıklar olsun! Akletmiyor musunuz?" dedi.'),
  ('tr.diyanet', 21, 67, 'İbrahim: "O halde, Allah\'ı bırakıp da size hiçbir fayda ve zarar veremeyecek olan putlara ne diye taparsınız? Size de, Allah\'ı bırakıp taptıklarınıza da yazıklar olsun! Akletmiyor musunuz?" dedi.'),
  ('tr.diyanet', 21, 68, 'Onlar: "Bir şey yapacaksanız, şunu yakın da tanrılarınıza yardım edin" dediler.'),
  ('tr.diyanet', 21, 69, 'Biz: "Ey ateş! İbrahim\'e karşı serin ve zararsız ol" dedik.'),
  ('tr.diyanet', 21, 70, 'Ona düzen kurmak istediler, fakat Biz onları hüsrana uğrattık.'),
  ('tr.diyanet', 21, 71, 'Onu da, Lut\'u da, alemler için kutsal kıldığımız yere ulaştırıp kurtardık.'),
  ('tr.diyanet', 21, 72, 'İbrahim\'e, buna ilaveten İshak ve Yakub\'u da verdik, her birini iyi kimseler kıldık.'),
  ('tr.diyanet', 21, 73, 'Onları, buyruğumuz altında insanları doğru yola götüren önderler yaptık; onlara, iyi işler yapmayı, namaz kılmayı, zekat vermeyi vahyettik. Onlar, bize kulluk eden kimselerdi.'),
  ('tr.diyanet', 21, 74, 'Lut\'a da hüküm ve ilim verdik; onu, çirkin işler işleyen kasabadan kurtardık. Doğrusu onlar yoldan çıkmış kötü bir milletti.'),
  ('tr.diyanet', 21, 75, 'Lut\'u rahmetimizin içine aldık; doğrusu o iyilerdendi.'),
  ('tr.diyanet', 21, 76, 'Nuh da daha önceleri Bize yalvarmıştı, onun duasını kabul edip, kendisini ve ailesini büyük sıkıntıdan kurtardık.'),
  ('tr.diyanet', 21, 77, 'Ayetlerimizi yalanlayan millete karşı ona yardım ettik. Doğrusu onlar fena bir milletti, hepsini suda boğduk.'),
  ('tr.diyanet', 21, 78, 'Davud ve Süleyman da milletin koyunlarının yayıldığı bir ekin hakkında hüküm veriyorlarken, Biz onların hükmüne şahiddik.'),
  ('tr.diyanet', 21, 79, 'Süleyman\'a bu meselenin hükmünü bildirmiştik; her birine hüküm ve ilim verdik. Davud ile beraber tesbih etsinler diye dağları ve kuşları buyruk altına aldık. Bunları Biz yapmıştık.'),
  ('tr.diyanet', 21, 80, 'Ona, sizi savaşta korumak için zırh yapma sanatını öğrettik, artık şükreder misiniz?'),
  ('tr.diyanet', 21, 81, 'Bereketli kıldığımız yere doğru, Süleyman\'ın emriyle yürüyen şiddetli rüzgarı, onun buyruğuna verdik. Biz herşeyi biliyorduk.'),
  ('tr.diyanet', 21, 82, 'Dalgıçlık yapan ve bundan başka işler de gören şeytanlardan da onun buyruğu altına verdik. Onların hepsini gözetiyorduk.'),
  ('tr.diyanet', 21, 83, 'Eyyub da: "Başıma bir bela geldi, (Sana sığındım), Sen merhametlilerin merhametlisisin" diye Rabbine nida etmişti.'),
  ('tr.diyanet', 21, 84, 'Biz de onun duasını kabul etmiş ve başına gelenleri kaldırmıştık. Katımızdan bir rahmet ve kulluk edenlere bir hatıra olmak üzere ona tekrar ailesini ve kaybettikleriyle bir mislini daha vermiştik.'),
  ('tr.diyanet', 21, 85, 'İsmail, İdris ve Zülkifl hakkında anlattığımızı da an; onların her biri sabredenlerdendi.'),
  ('tr.diyanet', 21, 86, 'Onları rahmetimizin içine aldık; doğrusu onlar iyilerdendi.'),
  ('tr.diyanet', 21, 87, 'Zünnun (Balık Sahibi; Yunus) hakkında söylediğimizi de an. O, öfkelenerek giderken, kendisini sıkıntıya sokmayacağımızı sanmıştı; fakat sonunda karanlıklar içinde: "Senden başka tanrı yoktur, Sen münezzehsin, doğrusu ben haksızlık edenlerdenim" diye seslenmişti.'),
  ('tr.diyanet', 21, 88, 'Biz de ona cevap verip, onu üzüntüden kurtarmıştık. inananları böyle kurtarırız.'),
  ('tr.diyanet', 21, 89, 'Zekeriya da: "Rabbim! Beni tek Başıma bırakma, Sen varislerin en hayırlısısın" diye nida etmişti.'),
  ('tr.diyanet', 21, 90, 'Biz de ona icabet ederek, Yahya\'yı bahşetmiş, eşini de doğum yapacak hale getirmiştik. Doğrusu onlar iyi işlerde yarışıyorlar, korkarak ve umarak Bize yalvarıyorlardı. Bize karşı gönülden saygı duyuyorlardı.'),
  ('tr.diyanet', 21, 91, 'Mahrem yerini koruyan Meryem\'e ruhumuzdan üflemiş, onu ve oğlunu, alemler için bir mucize kılmıştık.'),
  ('tr.diyanet', 21, 92, 'Doğrusu tevhid dini olan Müslümanlık, bir tek din olarak sizin dininizdir ve Ben de Rabbinizim, artık Bana kulluk edin.'),
  ('tr.diyanet', 21, 93, 'Ama insanlar, din konusunda aralarında bölüklere ayrıldılar, hepsi Bize döneceklerdir.'),
  ('tr.diyanet', 21, 94, 'İnanmış olarak yararlı iş işleyenin ameli inkar edilmeyecektir. Biz onu yazmaktayız.'),
  ('tr.diyanet', 21, 95, 'Yok ettiğimiz kasaba halkının ahirette ceza görmek üzere Bize dönmemesi imkansızdır.'),
  ('tr.diyanet', 21, 96, 'Yecüc ve Mecüc\'ün seddi yıkıldığı zaman her dere ve tepeden boşanırlar.'),
  ('tr.diyanet', 21, 97, 'Gerçek vaad yaklaştığında, inkar edenlerin gözleri beleriverir: "Vah bize! Bundan önce gaflet içindeydik, hem de zalimdik" derler.'),
  ('tr.diyanet', 21, 98, 'Siz ve Allah\'tan başka taptıklarınız, cehennemin yakıtısınız; oraya gireceksiniz.'),
  ('tr.diyanet', 21, 99, 'Eğer bunlar tanrı olsaydı cehenneme girmezlerdi; hepsi orada temelli kalacaktır.'),
  ('tr.diyanet', 21, 100, 'Orada onlara ah etmek vardır; birşey de işitemezler.'),
  ('tr.diyanet', 21, 101, 'Yaptıklarına karşılık katımızdan kendileri için iyi şeyler yazılmış olanlar, işte onlar cehennemden uzak tutulanlardır.'),
  ('tr.diyanet', 21, 102, 'Cehennemin uğultusunu duymazlar. Canlarının istediği şeyler içinde temelli kalırlar.'),
  ('tr.diyanet', 21, 103, 'En büyük korku bile onları üzmez; kendilerini melekler: "Size söz verilen gün işte bugündür" diye karşılarlar.'),
  ('tr.diyanet', 21, 104, 'Göğü, kitap dürer gibi dürdüğümüz zaman, yaratmaya ilk başladığımız gibi katımızdan verilmiş bir söz olarak onu tekrar var edeceğiz. Doğrusu Biz yaparız.'),
  ('tr.diyanet', 21, 105, 'And olsun ki, Tevrat\'tan sonra Zebur\'da da yeryüzüne ancak iyi kullarımın mirasçı olduğunu yazmıştık.'),
  ('tr.diyanet', 21, 106, 'Doğrusu bu Kuran\'da, kulluk eden kimselere bildiri vardır.'),
  ('tr.diyanet', 21, 107, 'Biz seni ancak alemlere rahmet olarak gönderdik.'),
  ('tr.diyanet', 21, 108, 'De ki: "Doğrusu tanrınızın tek bir Tanrı olduğu bana şüphesiz vahyolundu. Artık müslüman olacak mısınız?"'),
  ('tr.diyanet', 21, 109, 'Eğer yüz çevirirlerse, de ki: "Size düpedüz açıkladım; tehdit olunduğunuz şeyin yakın mı uzak mı olduğunu bilmem."'),
  ('tr.diyanet', 21, 110, '"Doğrusu O, açığa vurulan sözü de bilir, gizlediklerinizi de bilir."'),
  ('tr.diyanet', 21, 111, '"Bilmem; belki bu gecikme sizi denemek ve bir süreye kadar geçindirmek içindir."'),
  ('tr.diyanet', 21, 112, 'Peygamber: "Rabbim! Aramızda gerçekle hükmet, anlattıklarınıza karşı ancak Rahman olan Rabbimizden yardım istenir" dedi.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 21, 1, 'Telah dekat kepada manusia hari menghisab segala amalan mereka, sedang mereka berada dalam kelalaian lagi berpaling (daripadanya).'),
  ('id.indonesian', 21, 2, 'Tidak datang kepada mereka suatu ayat Al Quran pun yang baru (di-turunkan) dari Tuhan mereka, melainkan mereka mendengarnya, sedang mereka bermain-main,'),
  ('id.indonesian', 21, 3, '(lagi) hati mereka dalam keadaan lalai. Dan mereka yang zalim itu merahasiakan pembicaraan mereka: "Orang ini tidak lain hanyalah seorang manusia (jua) seperti kamu, maka apakah kamu menerima sihir itu, padahal kamu menyaksikannya?"'),
  ('id.indonesian', 21, 4, 'Berkatalah Muhammad (kepada mereka): "Tuhanku mengetahui semua perkataan di langit dan di bumi dan Dialah Yang Maha Mendengar lagi Maha Mengetahui".'),
  ('id.indonesian', 21, 5, 'Bahkan mereka berkata (pula): "(Al Quran itu adalah) mimpi-mimpi yang kalut, malah diada-adakannya, bahkan dia sendiri seorang penyair, maka hendaknya ia mendatangkan kepada kita suatu mukjizat, sebagai-mana rasul-rasul yang telah lalu di-utus".'),
  ('id.indonesian', 21, 6, 'Tidak ada (penduduk) suatu negeripun yang beriman yang Kami telah membinasakannya sebeIum mereka; maka apakah mereka akan beriman?'),
  ('id.indonesian', 21, 7, 'Kami tiada mengutus rasul rasul sebelum kamu (Muhammad), melainkan beberapa orang-laki-laki yang Kami beri wahyu kepada mereka, maka tanyakanlah olehmu kepada orang-orang yang berilmu, jika kamu tiada mengetahui.'),
  ('id.indonesian', 21, 8, 'Dan tidaklah Kami jadikan mereka tubuh-tubuh yang tiada memakan makanan, dan tidak (pula) mereka itu orang-orang yang kekal.'),
  ('id.indonesian', 21, 9, 'Kemudian Kami tepati janji (yang telah Kami janjikan) kepada mereka. Maka Kami selamatkan mereka dan orang-orang yang Kami kehendaki dan Kami binasakan orang-orang yang melampaui batas.'),
  ('id.indonesian', 21, 10, 'Sesungguhnya telah Kami turunkan kepada kamu sebuah kitab yang di dalamnya terdapat sebab-sebab kemuliaan bagimu. Maka apakah kamu tiada memahaminya?'),
  ('id.indonesian', 21, 11, 'Dan berapa banyaknya (penduduk) negeri yang zalim yang teIah Kami binasakan, dan Kami adakan sesudah mereka itu kaum yang lain (sebagai penggantinya).'),
  ('id.indonesian', 21, 12, 'Maka tatkala mereka merasakan azab Kami, tiba-tiba mereka melarikan diri dari negerinya.'),
  ('id.indonesian', 21, 13, 'Janganlah kamu lari tergesa-gesa; kembalilah kamu kepada nikmat yang telah kamu rasakan dan kepada tempat-tempat kediamanmu (yang baik), supaya kamu ditanya.'),
  ('id.indonesian', 21, 14, 'Mereka berkata: "Aduhai, celaka kami, sesungguhnya kami adalah orang-orang yang zaIim".'),
  ('id.indonesian', 21, 15, 'Maka tetaplah demikian keluhan mereka, sehingga Kami jadikan mereka sebagai tanaman yang telah dituai, yang tidak dapat hidup lagi.'),
  ('id.indonesian', 21, 16, 'Dan tidaklah Kami ciptakan Iangit dan bumi dan segala yang ada di antara keduanya dengan bermain-main.'),
  ('id.indonesian', 21, 17, 'Sekiranya Kami hendak membuat sesuatu permainan, (isteri dan anak), tentulah Kami membuatnya dari sisi Kami. Jika Kami menghendaki berbuat demikian, (tentulah Kami telah melakukannya).'),
  ('id.indonesian', 21, 18, 'Sebenarya Kami melontarkan yang hak kepada yang batil lalu yang hak itu menghancurkannya, maka dengan serta merta yang batil itu lenyap. Dan kecelakaanlah bagimu disebabkan kamu mensifati (Allah dengan sifat-sifat yang tidak layak bagi-Nya).'),
  ('id.indonesian', 21, 19, 'Dan kepunyaan-Nya-lah segala yang di langit dan di bumi. Dan malaikat-malaikat yang di sisi-Nya, mereka tiada mempunyai rasa angkuh untuk menyembah-Nya dan tiada (pula) merasa letih.'),
  ('id.indonesian', 21, 20, 'Mereka selalu bertasbih malam dan siang tiada henti-hentinya.'),
  ('id.indonesian', 21, 21, 'Apakah mereka mengambil tuhan-tuhan dari bumi, yang dapat menghidupkan (orang-orang mati)?'),
  ('id.indonesian', 21, 22, 'Sekiranya ada di langit dan di bumi tuhan-tuhan selain Allah, tentulah keduanya itu telah rusak binasa. Maka Maha Suci Allah yang mempunyai \'Arsy daripada apa yang mereka sifatkan.'),
  ('id.indonesian', 21, 23, 'Dia tidak ditanya tentang apa yang diperbuat-Nya dan merekalah yang akan ditanyai.'),
  ('id.indonesian', 21, 24, 'Apakah mereka mengambil tuhan-tuhan selain-Nya? Katakanlah: "Unjukkanlah hujjahmu! (Al Quran) ini adalah peringatan bagi orang-orang yang bersamaku, dan peringatan bagi orang-orang yang sebelumku". Sebenarnya kebanyakan mereka tiada mengetahui yang hak, karena itu mereka berpaling.'),
  ('id.indonesian', 21, 25, 'Dan Kami tidak mengutus seorang rasulpun sebelum kamu melainkan Kami wahyukan kepadanya: "Bahwasanya tidak ada Tuhan (yang hak) melainkan Aku, maka sembahlah olehmu sekalian akan Aku".'),
  ('id.indonesian', 21, 26, 'Dan mereka berkata: "Tuhan Yang Maha Pemurah telah mengambil (mempunyai) anak", Maha Suci Allah. Sebenarnya (malaikat-malaikat itu), adalah hamba-hamba yang dimuliakan,'),
  ('id.indonesian', 21, 27, 'mereka itu tidak mendahului-Nya dengan perkataan dan mereka mengerjakan perintah-perintah-Nya.'),
  ('id.indonesian', 21, 28, 'Allah mengetahui segala sesuatu yang dihadapan mereka (malaikat) dan yang di belakang mereka, dan mereka tiada memberi syafa\'at melainkan kepada orang yang diridhai Allah, dan mereka itu selalu berhati-hati karena takut kepada-Nya.'),
  ('id.indonesian', 21, 29, 'Dan barangsiapa di antara mereka, mengatakan: "Sesungguhnya Aku adalah tuhan selain daripada Allah", maka orang itu Kami beri balasan dengan Jahannam, demikian Kami memberikan pembalasan kepada orang-orang zalim.'),
  ('id.indonesian', 21, 30, 'Dan apakah orang-orang yang kafir tidak mengetahui bahwasanya langit dan bumi itu keduanya dahulu adalah suatu yang padu, kemudian Kami pisahkan antara keduanya. Dan dari air Kami jadikan segala sesuatu yang hidup. Maka mengapakah mereka tiada juga beriman?'),
  ('id.indonesian', 21, 31, 'Dan telah Kami jadikan di bumi ini gunung-gunung yang kokoh supaya bumi itu (tidak) goncang bersama mereka dan telah Kami jadikan (pula) di bumi itu jalan-jalan yang luas, agar mereka mendapat petunjuk.'),
  ('id.indonesian', 21, 32, 'Dan Kami menjadikan langit itu sebagai atap yang terpelihara, sedang mereka berpaling dari segala tanda-tanda (kekuasaan Allah) yang terdapat padanya.'),
  ('id.indonesian', 21, 33, 'Dan Dialah yang telah menciptakan malam dan siang, matahari dan bulan. Masing-masing dari keduanya itu beredar di dalam garis edarnya.'),
  ('id.indonesian', 21, 34, 'Kami tidak menjadikan hidup abadi bagi seorang manusiapun sebelum kamu (Muhammad); maka jikalau kamu mati, apakah mereka akan kekal?'),
  ('id.indonesian', 21, 35, 'Tiap-tiap yang berjiwa akan merasakan mati. Kami akan menguji kamu dengan keburukan dan kebaikan sebagai cobaan (yang sebenar-benarnya). Dan hanya kepada Kamilah kamu dikembalikan.'),
  ('id.indonesian', 21, 36, 'Dan apahila orang-orang kafir itu melihat kamu, mereka hanya membuat kamu menjadi olok-olok. (Mereka mengatakan): "Apakah ini orang yang mencela tuhan-tuhan-mu?", padahal mereka adaIah orang-orang yang ingkar mengingat Allah Yang Maha Pemurah.'),
  ('id.indonesian', 21, 37, 'Manusia telah dijadikan (bertabiat) tergesa-gesa. Kelak akan Aku perIihatkan kepadamu tanda-tanda azab-Ku. Maka janganlah kamu minta kepada-Ku mendatangkannya dengan segera.'),
  ('id.indonesian', 21, 38, 'Mereka berkata: "Kapankah janji itu akan datang, jika kamu sekaIian adalah orang-orang yang benar?"'),
  ('id.indonesian', 21, 39, 'Andaikata orang-orang kafir itu mengetahui, waktu (di mana) mereka itu tidak mampu mengelakkan api neraka dari muka mereka dan (tidak pula) dari punggung mereka, sedang mereka (tidak pula) mendapat pertolongan, (tentulah mereka tiada meminta disegerakan).'),
  ('id.indonesian', 21, 40, 'Sebenarnya (azab) itu akan datang kepada mereka dengan sekonyong-konyong lalu membuat mereka menjadi panik, maka mereka tidak sanggup menolaknya dan tidak (pula) mereka diberi tangguh.'),
  ('id.indonesian', 21, 41, 'Dan sungguh telah diperolok-olokkan beberapa orang rasul sebelum kamu maka turunlah kepada orang yang mencemoohkan rasul-rasul itu azab yang selalu mereka perolok-olokkan.'),
  ('id.indonesian', 21, 42, 'Katakanlah: "Siapakah yang dapat memelihara kamu di waktu malam dan siang hari dari (azab Allah) Yang Maha Pemurah?" Sebenarnya mereka adalah orang-orang yang berpaling dari mengingati Tuhan mereka.'),
  ('id.indonesian', 21, 43, 'Atau adakah mereka mempunyai tuhan-tuhan yang dapat memelihara mereka dari (azab) Kami. Tuhan-tuhan itu tidak sanggup menolong diri mereka sendiri dan tidak (pula) mereka dilindungi dari (azab) Kami itu?'),
  ('id.indonesian', 21, 44, 'Sebenarnya Kami telah memberi mereka dan bapak-bapak mereka kenikmatan (hidup di dunia) hingga panjanglah umur mereka. Maka apakah mereka tidak melihat bahwasanya Kami mendatangi negeri (orang kafir), lalu Kami kurangi luasnya dari segala penjurunya. Maka apakah mereka yang menang?'),
  ('id.indonesian', 21, 45, 'Katakanlah (hai Muhammad): "Sesungguhnya aku hanya memberi peringatan kepada kamu sekalian dengan wahyu dan tiadalah orang-orang yang tuli mendengar seruan, apabila mereka diberi peringatan"'),
  ('id.indonesian', 21, 46, 'Dan sesungguhnya, jika mereka ditimpa sedikit saja dari azab Tuhan-mu, pastilah mereka berkata: "Aduhai, celakalah kami, bahwasanya kami adalah orang yang menganiaya diri sendiri".'),
  ('id.indonesian', 21, 47, 'Kami akan memasang timbangan yang tepat pada hari kiamat, maka tiadalah dirugikan seseorang barang sedikitpun. Dan jika (amalan itu) hanya seberat biji sawipun pasti Kami mendatangkan (pahala)nya. Dan cukuplah Kami sebagai pembuat perhitungan.'),
  ('id.indonesian', 21, 48, 'Dan sesungguhnya telah Kami berikan kepada Musa dan Harun Kitab Taurat dan penerangan serta pengajaran bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 21, 49, '(yaitu) orang-orang yang takut akan (azab) Tuhan mereka, sedang mereka tidak melihat-Nya, dan mereka merasa takut akan (tibanya) hari kiamat.'),
  ('id.indonesian', 21, 50, 'Dan Al Quran ini adalah suatu kitab (peringatan) yang mempunyai berkah yang telah Kami turunkan. Maka mengapakah kamu mengingkarinya?'),
  ('id.indonesian', 21, 51, 'Dan sesungguhnya telah Kami anugerahkan kepada Ibrahim hidayah kebenaran sebelum (Musa dan Harun), dan adalah Kami mengetahui (keadaan)nya.'),
  ('id.indonesian', 21, 52, '(Ingatlah), ketika Ibrahim berkata kepada bapaknya dan kaumnya: "Patung-patung apakah ini yang kamu tekun beribadat kepadanya?"'),
  ('id.indonesian', 21, 53, 'Mereka menjawab: "Kami mendapati bapak-bapak kami menyembahnya".'),
  ('id.indonesian', 21, 54, 'Ibrahim berkata: "Sesungguhnya kamu dan bapak-bapakmu berada dalam kesesatan yang nyata".'),
  ('id.indonesian', 21, 55, 'Mereka menjawab: "Apakah kamu datang kepada kami dengan sungguh-sungguh ataukah kamu termasuk orang-orang yang bermain-main?"'),
  ('id.indonesian', 21, 56, 'Ibrahim berkata: "Sebenarnya Tuhan kamu ialah Tuhan langit dan bumi yang telah menciptakannya: dan aku termasuk orang-orang yang dapat memberikan bukti atas yang demikian itu".'),
  ('id.indonesian', 21, 57, 'Demi Allah, sesungguhnya aku akan melakukan tipu daya terhadap berhala-berhalamu sesudah kamu pergi meninggalkannya.'),
  ('id.indonesian', 21, 58, 'Maka Ibrahim membuat berhala-berhala itu hancur berpotong-potong, kecuali yang terbesar (induk) dari patung-patung yang lain; agar mereka kembali (untuk bertanya) kepadanya.'),
  ('id.indonesian', 21, 59, 'Mereka berkata: "Siapakah yang melakukan perbuatan ini terhadap tuhan-tuhan kami, sesungguhnya dia termasuk orang-orang yang zalim".'),
  ('id.indonesian', 21, 60, 'Mereka berkata: "Kami dengar ada seorang pemuda yang mencela berhala-berhala ini yang bernama Ibrahim".'),
  ('id.indonesian', 21, 61, 'Mereka berkata: "(Kalau demikian) bawalah dia dengan cara yang dapat dilihat orang banyak, agar mereka menyaksikan".'),
  ('id.indonesian', 21, 62, 'Mereka bertanya: "Apakah kamu, yang melakukan perbuatan ini terhadap tuhan-tuhan kami, hai Ibrahim?"'),
  ('id.indonesian', 21, 63, 'Ibrahim menjawab: "Sebenarnya patung yang besar itulah yang melakukannya, maka tanyakanlah kepada berhala itu, jika mereka dapat berbicara".'),
  ('id.indonesian', 21, 64, 'Maka mereka telah kembali kepada kesadaran dan lalu berkata: "Sesungguhnya kamu sekalian adalah orang-orang yang menganiaya (diri sendiri)",'),
  ('id.indonesian', 21, 65, 'kemudian kepala mereka jadi tertunduk (lalu berkata): "Sesungguhnya kamu (hai Ibrahim) telah mengetahui bahwa berhala-berhala itu tidak dapat berbicara".'),
  ('id.indonesian', 21, 66, 'Ibrahim berkata: Maka mengapakah kamu menyembah selain Allah sesuatu yang tidak dapat memberi manfaat sedikitpun dan tidak (pula) memberi mudharat kepada kamu?"'),
  ('id.indonesian', 21, 67, 'Ah (celakalah) kamu dan apa yang kamu sembah selain Allah. Maka apakah kamu tidak memahami?'),
  ('id.indonesian', 21, 68, 'Mereka berkata: "Bakarlah dia dan bantulah tuhan-tuhan kamu, jika kamu benar-benar hendak bertindak".'),
  ('id.indonesian', 21, 69, 'Kami berfirman: "Hai api menjadi dinginlah, dan menjadi keselamatanlah bagi Ibrahim",'),
  ('id.indonesian', 21, 70, 'mereka hendak berbuat makar terhadap Ibrahim, maka Kami menjadikan mereka itu orang-orang yang paling merugi.'),
  ('id.indonesian', 21, 71, 'Dan Kami seIamatkan Ibrahim dan Luth ke sebuah negeri yang Kami telah memberkahinya untuk sekalian manusia.'),
  ('id.indonesian', 21, 72, 'Dan Kami telah memberikan kepada-nya (Ibrahim) lshak dan Ya\'qub, sebagai suatu anugerah (daripada Kami). Dan masing-masingnya Kami jadikan orang-orang yang saleh'),
  ('id.indonesian', 21, 73, 'Kami telah menjadikan mereka itu sebagai pemimpin-pemimpin yang memberi petunjuk dengan perintah Kami dan telah Kami wahyukan kepada, mereka mengerjakan kebajikan, mendirikan sembahyang, menunaikan zakat, dan hanya kepada Kamilah mereka selalu menyembah,'),
  ('id.indonesian', 21, 74, 'dan kepada Luth, Kami telah berikan hikmah dan ilmu, dan telah Kami selamatkan dia dari (azab yang telah menimpa penduduk) kota yang mengerjakan perbuatan keji. Sesungguhnya mereka adalah kaum yang jahat lagi fasik,'),
  ('id.indonesian', 21, 75, 'dan Kami masukkan dia ke dalam rahmat Kami; karena sesungguhnya dia termasuk orang-orang yang saleh.'),
  ('id.indonesian', 21, 76, 'Dan (ingatlah kisah) Nuh, sebelum itu ketika dia berdoa, dan Kami memperkenankan doanya, lalu Kami selamatkan dia beserta keluarganya dari bencana yang besar.'),
  ('id.indonesian', 21, 77, 'Dan Kami telah menolongnya dari kaum yang telah mendustakan ayat-ayat Kami. Sesungguhnya mereka adalah kaum yang jahat, maka Kami tenggelamkan mereka semuanya.'),
  ('id.indonesian', 21, 78, 'Dan (ingatlah kisah) Daud dan Sulaiman, di waktu keduanya memberikan keputusan mengenai tanaman, karena tanaman itu dirusak oleh kambing-kambing kepunyaan kaumnya. Dan adalah Kami menyaksikan keputusan yang diberikan oleh mereka itu,'),
  ('id.indonesian', 21, 79, 'maka Kami telah memberikan pengertian kepada Sulaiman tentang hukum (yang lebih tepat); dan kepada masing-masing mereka telah Kami berikan hikmah dan ilmu dan telah Kami tundukkan gunung-gunung dan burung-burung, semua bertasbih bersama Daud. Dan kamilah yang melakukannya.'),
  ('id.indonesian', 21, 80, 'Dan telah Kami ajarkan kepada Daud membuat baju besi untuk kamu, guna memelihara kamu dalam peperanganmu; Maka hendaklah kamu bersyukur (kepada Allah).'),
  ('id.indonesian', 21, 81, 'Dan (telah Kami tundukkan) untuk Sulaiman angin yang sangat kencang tiupannya yang berhembus dengan perintahnya ke negeri yang kami telah memberkatinya. Dan adalah Kami Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 21, 82, 'Dan Kami telah tundukkan (pula kepada Sulaiman) segolongan syaitan-syaitan yang menyelam (ke dalam laut) untuknya dan mengerjakan pekerjaan selain daripada itu, dan adalah Kami memelihara mereka itu,'),
  ('id.indonesian', 21, 83, 'dan (ingatlah kisah) Ayub, ketika ia menyeru Tuhannya: "(Ya Tuhanku), sesungguhnya aku telah ditimpa penyakit dan Engkau adalah Tuhan Yang Maha Penyayang di antara semua penyayang".'),
  ('id.indonesian', 21, 84, 'Maka Kamipun memperkenankan seruannya itu, lalu Kami lenyapkan penyakit yang ada padanya dan Kami kembalikan keluarganya kepadanya, dan Kami lipat gandakan bilangan mereka, sebagai suatu rahmat dari sisi Kami dan untuk menjadi peringatan bagi semua yang menyembah Allah.'),
  ('id.indonesian', 21, 85, 'Dan (ingatlah kisah) Ismail, Idris dan Dzulkifli. Semua mereka termasuk orang-orang yang sabar.'),
  ('id.indonesian', 21, 86, 'Kami telah memasukkan mereka kedalam rahmat Kami. Sesungguhnya mereka termasuk orang-orang yang saleh.'),
  ('id.indonesian', 21, 87, 'Dan (ingatlah kisah) Dzun Nun (Yunus), ketika ia pergi dalam keadaan marah, lalu ia menyangka bahwa Kami tidak akan mempersempitnya (menyulitkannya), maka ia menyeru dalam keadaan yang sangat gelap: "Bahwa tidak ada Tuhan selain Engkau. Maha Suci Engkau, sesungguhnya aku adalah termasuk orang-orang yang zalim".'),
  ('id.indonesian', 21, 88, 'Maka Kami telah memperkenankan doanya dan menyelamatkannya dari pada kedukaan. Dan demikianlah Kami selamatkan orang-orang yang beriman.'),
  ('id.indonesian', 21, 89, 'Dan (ingatlah kisah) Zakaria, tatkala ia menyeru Tuhannya: "Ya Tuhanku janganlah Engkau membiarkan aku hidup seorang diri dan Engkaulah Waris Yang Paling Baik.'),
  ('id.indonesian', 21, 90, 'Maka Kami memperkenankan doanya, dan Kami anugerahkan kepada nya Yahya dan Kami jadikan isterinya dapat mengandung. Sesungguhnya mereka adalah orang-orang yang selalu bersegera dalam (mengerjakan) perbuatan-perbuatan yang baik dan mereka berdoa kepada Kami dengan harap dan cemas. Dan mereka adalah orang-orang yang khusyu\' kepada Kami.'),
  ('id.indonesian', 21, 91, 'Dan (ingatlah kisah) Maryam yang telah memelihara kehormatannya, lalu Kami tiupkan ke dalam (tubuh)nya ruh dari Kami dan Kami jadikan dia dan anaknya tanda (kekuasaan Allah) yang besar bagi semesta alam.'),
  ('id.indonesian', 21, 92, 'Sesungguhnya (agama Tauhid) ini adalah agama kamu semua; agama yang satu dan Aku adalah Tuhanmu, maka sembahlah Aku.'),
  ('id.indonesian', 21, 93, 'Dan mereka telah memotong-motong urusan (agama) mereka di antara mereka. Kepada Kamilah masing-masing golongan itu akan kembali.'),
  ('id.indonesian', 21, 94, 'Maka barang siapa yang mengerjakan amal saleh, sedang ia beriman, maka tidak ada pengingkaran terhadap amalannya itu dan sesungguhnya Kami menuliskan amalannya itu untuknya.'),
  ('id.indonesian', 21, 95, 'Sungguh tidak mungkin atas (penduduk) suatu negeri yang telah Kami binasakan, bahwa mereka tidak akan kembali (kepada Kami).'),
  ('id.indonesian', 21, 96, 'Hingga apabila dibukakan (tembok) Ya\'juj dan Ma\'juj, dan mereka turun dengan cepat dari seluruh tempat yang tinggi.'),
  ('id.indonesian', 21, 97, 'Dan telah dekatlah kedatangan janji yang benar (hari berbangkit), maka tiba-tiba terbelalaklah mata orang-orang yang kafir. (Mereka berkata): "Aduhai, celakalah kami, sesungguhnya kami adalah dalam kelalaian tentang ini, bahkan kami adalah orang-orang yang zalim".'),
  ('id.indonesian', 21, 98, 'Sesungguhnya kamu dan apa yang kamu sembah selain Allah, adalah umpan Jahannam, kamu pasti masuk ke dalamnya.'),
  ('id.indonesian', 21, 99, 'Andaikata berhala-berhala itu Tuhan, tentulah mereka tidak masuk neraka. Dan semuanya akan kekal di dalamnya.'),
  ('id.indonesian', 21, 100, 'Mereka merintih di dalam api dan mereka di dalamnya tidak bisa mendengar.'),
  ('id.indonesian', 21, 101, 'Bahwasanya orang-orang yang telah ada untuk mereka ketetapan yang baik dari Kami, mereka itu dijauhkan dari neraka,'),
  ('id.indonesian', 21, 102, 'mereka tidak mendengar sedikitpun suara api neraka, dan mereka kekal dalam menikmati apa yang diingini oleh mereka.'),
  ('id.indonesian', 21, 103, 'Mereka tidak disusahkan oleh kedahsyatan yang besar (pada hari kiamat), dan mereka disambut oleh para malaikat. (Malaikat berkata): "Inilah harimu yang telah dijanjikan kepadamu".'),
  ('id.indonesian', 21, 104, '(Yaitu) pada hari Kami gulung langit sebagai menggulung lembaran-lembaran kertas. Sebagaimana Kami telah memulai panciptaan pertama begitulah Kami akan mengulanginya. Itulah suatu janji yang pasti Kami tepati; sesungguhnya Kamilah yang akan melaksanakannya.'),
  ('id.indonesian', 21, 105, 'Dan sungguh telah Kami tulis didalam Zabur sesudah (Kami tulis dalam) Lauh Mahfuzh, bahwasanya bumi ini dipusakai hamba-hamba-Ku yang saleh.'),
  ('id.indonesian', 21, 106, 'Sesungguhnya (apa yang disebutkan) dalam (surat) ini, benar-benar menjadi peringatan bagi kaum yang menyembah (Allah).'),
  ('id.indonesian', 21, 107, 'Dan tiadalah Kami mengutus kamu, melainkan untuk (menjadi) rahmat bagi semesta alam.'),
  ('id.indonesian', 21, 108, 'Katakanlah: "Sesungguhnya yang diwahyukan kepadaku adalah: "Bahwasanya Tuhanmu adalah Tuhan Yang Esa. maka hendaklah kamu berserah diri (kepada-Nya)".'),
  ('id.indonesian', 21, 109, 'Jika mereka berpaling, maka katakanlah: "Aku telah menyampaikan kepada kamu sekalian (ajaran) yang sama (antara kita) dan aku tidak mengetahui apakah yang diancamkan kepadamu itu sudah dekat atau masih jauh?".'),
  ('id.indonesian', 21, 110, 'Sesungguhnya Dia mengetahui perkataan (yang kamu ucapkan) dengan terang-terangan dan Dia mengetahui apa yang kamu rahasiakan.'),
  ('id.indonesian', 21, 111, 'Dan aku tiada mengetahui, boleh jadi hal itu cobaan bagi kamu dan kesenangan sampai kepada suatu waktu.'),
  ('id.indonesian', 21, 112, '(Muhammad) berkata: "Ya Tuhanku, berilah keputusan dengan adil. Dan Tuhan kami ialah Tuhan Yang Maha Pemurah lagi Yang dimohonkan pertolongan-Nya terhadap apa yang kamu katakan".')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (20, 53, 2401, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًۭا وَسَلَكَ لَكُمْ فِيهَا سُبُلًۭا وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَأَخْرَجْنَا بِهِۦٓ أَزْوَٰجًۭا مِّن نَّبَاتٍۢ شَتَّىٰ', 315, 16, 125, 0),
  (20, 54, 2402, 'كُلُوا۟ وَٱرْعَوْا۟ أَنْعَٰمَكُمْ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلنُّهَىٰ', 315, 16, 125, 0),
  (20, 55, 2403, '۞ مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ تَارَةً أُخْرَىٰ', 315, 16, 126, 0),
  (20, 56, 2404, 'وَلَقَدْ أَرَيْنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ', 315, 16, 126, 0),
  (20, 57, 2405, 'قَالَ أَجِئْتَنَا لِتُخْرِجَنَا مِنْ أَرْضِنَا بِسِحْرِكَ يَٰمُوسَىٰ', 315, 16, 126, 0),
  (20, 58, 2406, 'فَلَنَأْتِيَنَّكَ بِسِحْرٍۢ مِّثْلِهِۦ فَٱجْعَلْ بَيْنَنَا وَبَيْنَكَ مَوْعِدًۭا لَّا نُخْلِفُهُۥ نَحْنُ وَلَآ أَنتَ مَكَانًۭا سُوًۭى', 315, 16, 126, 0),
  (20, 59, 2407, 'قَالَ مَوْعِدُكُمْ يَوْمُ ٱلزِّينَةِ وَأَن يُحْشَرَ ٱلنَّاسُ ضُحًۭى', 315, 16, 126, 0),
  (20, 60, 2408, 'فَتَوَلَّىٰ فِرْعَوْنُ فَجَمَعَ كَيْدَهُۥ ثُمَّ أَتَىٰ', 315, 16, 126, 0),
  (20, 61, 2409, 'قَالَ لَهُم مُّوسَىٰ وَيْلَكُمْ لَا تَفْتَرُوا۟ عَلَى ٱللَّهِ كَذِبًۭا فَيُسْحِتَكُم بِعَذَابٍۢ ۖ وَقَدْ خَابَ مَنِ ٱفْتَرَىٰ', 315, 16, 126, 0),
  (20, 62, 2410, 'فَتَنَٰزَعُوٓا۟ أَمْرَهُم بَيْنَهُمْ وَأَسَرُّوا۟ ٱلنَّجْوَىٰ', 315, 16, 126, 0),
  (20, 63, 2411, 'قَالُوٓا۟ إِنْ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخْرِجَاكُم مِّنْ أَرْضِكُم بِسِحْرِهِمَا وَيَذْهَبَا بِطَرِيقَتِكُمُ ٱلْمُثْلَىٰ', 315, 16, 126, 0),
  (20, 64, 2412, 'فَأَجْمِعُوا۟ كَيْدَكُمْ ثُمَّ ٱئْتُوا۟ صَفًّۭا ۚ وَقَدْ أَفْلَحَ ٱلْيَوْمَ مَنِ ٱسْتَعْلَىٰ', 315, 16, 126, 0),
  (20, 65, 2413, 'قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَىٰ', 316, 16, 126, 0),
  (20, 66, 2414, 'قَالَ بَلْ أَلْقُوا۟ ۖ فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ', 316, 16, 126, 0),
  (20, 67, 2415, 'فَأَوْجَسَ فِى نَفْسِهِۦ خِيفَةًۭ مُّوسَىٰ', 316, 16, 126, 0),
  (20, 68, 2416, 'قُلْنَا لَا تَخَفْ إِنَّكَ أَنتَ ٱلْأَعْلَىٰ', 316, 16, 126, 0),
  (20, 69, 2417, 'وَأَلْقِ مَا فِى يَمِينِكَ تَلْقَفْ مَا صَنَعُوٓا۟ ۖ إِنَّمَا صَنَعُوا۟ كَيْدُ سَٰحِرٍۢ ۖ وَلَا يُفْلِحُ ٱلسَّاحِرُ حَيْثُ أَتَىٰ', 316, 16, 126, 0),
  (20, 70, 2418, 'فَأُلْقِىَ ٱلسَّحَرَةُ سُجَّدًۭا قَالُوٓا۟ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ', 316, 16, 126, 0),
  (20, 71, 2419, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ ۖ فَلَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍۢ وَلَأُصَلِّبَنَّكُمْ فِى جُذُوعِ ٱلنَّخْلِ وَلَتَعْلَمُنَّ أَيُّنَآ أَشَدُّ عَذَابًۭا وَأَبْقَىٰ', 316, 16, 126, 0),
  (20, 72, 2420, 'قَالُوا۟ لَن نُّؤْثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلَّذِى فَطَرَنَا ۖ فَٱقْضِ مَآ أَنتَ قَاضٍ ۖ إِنَّمَا تَقْضِى هَٰذِهِ ٱلْحَيَوٰةَ ٱلدُّنْيَآ', 316, 16, 126, 0),
  (20, 73, 2421, 'إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغْفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكْرَهْتَنَا عَلَيْهِ مِنَ ٱلسِّحْرِ ۗ وَٱللَّهُ خَيْرٌۭ وَأَبْقَىٰٓ', 316, 16, 126, 0),
  (20, 74, 2422, 'إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًۭا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 316, 16, 126, 0),
  (20, 75, 2423, 'وَمَن يَأْتِهِۦ مُؤْمِنًۭا قَدْ عَمِلَ ٱلصَّٰلِحَٰتِ فَأُو۟لَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلْعُلَىٰ', 316, 16, 126, 0),
  (20, 76, 2424, 'جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ', 316, 16, 126, 0),
  (20, 77, 2425, 'وَلَقَدْ أَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِى فَٱضْرِبْ لَهُمْ طَرِيقًۭا فِى ٱلْبَحْرِ يَبَسًۭا لَّا تَخَٰفُ دَرَكًۭا وَلَا تَخْشَىٰ', 317, 16, 126, 0),
  (20, 78, 2426, 'فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلْيَمِّ مَا غَشِيَهُمْ', 317, 16, 126, 0),
  (20, 79, 2427, 'وَأَضَلَّ فِرْعَوْنُ قَوْمَهُۥ وَمَا هَدَىٰ', 317, 16, 126, 0),
  (20, 80, 2428, 'يَٰبَنِىٓ إِسْرَٰٓءِيلَ قَدْ أَنجَيْنَٰكُم مِّنْ عَدُوِّكُمْ وَوَٰعَدْنَٰكُمْ جَانِبَ ٱلطُّورِ ٱلْأَيْمَنَ وَنَزَّلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ', 317, 16, 126, 0),
  (20, 81, 2429, 'كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَلَا تَطْغَوْا۟ فِيهِ فَيَحِلَّ عَلَيْكُمْ غَضَبِى ۖ وَمَن يَحْلِلْ عَلَيْهِ غَضَبِى فَقَدْ هَوَىٰ', 317, 16, 126, 0),
  (20, 82, 2430, 'وَإِنِّى لَغَفَّارٌۭ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحًۭا ثُمَّ ٱهْتَدَىٰ', 317, 16, 126, 0),
  (20, 83, 2431, '۞ وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوسَىٰ', 317, 16, 127, 0),
  (20, 84, 2432, 'قَالَ هُمْ أُو۟لَآءِ عَلَىٰٓ أَثَرِى وَعَجِلْتُ إِلَيْكَ رَبِّ لِتَرْضَىٰ', 317, 16, 127, 0),
  (20, 85, 2433, 'قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنۢ بَعْدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِىُّ', 317, 16, 127, 0),
  (20, 86, 2434, 'فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًۭا ۚ قَالَ يَٰقَوْمِ أَلَمْ يَعِدْكُمْ رَبُّكُمْ وَعْدًا حَسَنًا ۚ أَفَطَالَ عَلَيْكُمُ ٱلْعَهْدُ أَمْ أَرَدتُّمْ أَن يَحِلَّ عَلَيْكُمْ غَضَبٌۭ مِّن رَّبِّكُمْ فَأَخْلَفْتُم مَّوْعِدِى', 317, 16, 127, 0),
  (20, 87, 2435, 'قَالُوا۟ مَآ أَخْلَفْنَا مَوْعِدَكَ بِمَلْكِنَا وَلَٰكِنَّا حُمِّلْنَآ أَوْزَارًۭا مِّن زِينَةِ ٱلْقَوْمِ فَقَذَفْنَٰهَا فَكَذَٰلِكَ أَلْقَى ٱلسَّامِرِىُّ', 317, 16, 127, 0),
  (20, 88, 2436, 'فَأَخْرَجَ لَهُمْ عِجْلًۭا جَسَدًۭا لَّهُۥ خُوَارٌۭ فَقَالُوا۟ هَٰذَآ إِلَٰهُكُمْ وَإِلَٰهُ مُوسَىٰ فَنَسِىَ', 318, 16, 127, 0),
  (20, 89, 2437, 'أَفَلَا يَرَوْنَ أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًۭا وَلَا يَمْلِكُ لَهُمْ ضَرًّۭا وَلَا نَفْعًۭا', 318, 16, 127, 0),
  (20, 90, 2438, 'وَلَقَدْ قَالَ لَهُمْ هَٰرُونُ مِن قَبْلُ يَٰقَوْمِ إِنَّمَا فُتِنتُم بِهِۦ ۖ وَإِنَّ رَبَّكُمُ ٱلرَّحْمَٰنُ فَٱتَّبِعُونِى وَأَطِيعُوٓا۟ أَمْرِى', 318, 16, 127, 0),
  (20, 91, 2439, 'قَالُوا۟ لَن نَّبْرَحَ عَلَيْهِ عَٰكِفِينَ حَتَّىٰ يَرْجِعَ إِلَيْنَا مُوسَىٰ', 318, 16, 127, 0),
  (20, 92, 2440, 'قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوٓا۟', 318, 16, 127, 0),
  (20, 93, 2441, 'أَلَّا تَتَّبِعَنِ ۖ أَفَعَصَيْتَ أَمْرِى', 318, 16, 127, 0),
  (20, 94, 2442, 'قَالَ يَبْنَؤُمَّ لَا تَأْخُذْ بِلِحْيَتِى وَلَا بِرَأْسِىٓ ۖ إِنِّى خَشِيتُ أَن تَقُولَ فَرَّقْتَ بَيْنَ بَنِىٓ إِسْرَٰٓءِيلَ وَلَمْ تَرْقُبْ قَوْلِى', 318, 16, 127, 0),
  (20, 95, 2443, 'قَالَ فَمَا خَطْبُكَ يَٰسَٰمِرِىُّ', 318, 16, 127, 0),
  (20, 96, 2444, 'قَالَ بَصُرْتُ بِمَا لَمْ يَبْصُرُوا۟ بِهِۦ فَقَبَضْتُ قَبْضَةًۭ مِّنْ أَثَرِ ٱلرَّسُولِ فَنَبَذْتُهَا وَكَذَٰلِكَ سَوَّلَتْ لِى نَفْسِى', 318, 16, 127, 0),
  (20, 97, 2445, 'قَالَ فَٱذْهَبْ فَإِنَّ لَكَ فِى ٱلْحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَ ۖ وَإِنَّ لَكَ مَوْعِدًۭا لَّن تُخْلَفَهُۥ ۖ وَٱنظُرْ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِى ظَلْتَ عَلَيْهِ عَاكِفًۭا ۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِى ٱلْيَمِّ نَسْفًا', 318, 16, 127, 0),
  (20, 98, 2446, 'إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ۚ وَسِعَ كُلَّ شَىْءٍ عِلْمًۭا', 318, 16, 127, 0),
  (20, 99, 2447, 'كَذَٰلِكَ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآءِ مَا قَدْ سَبَقَ ۚ وَقَدْ ءَاتَيْنَٰكَ مِن لَّدُنَّا ذِكْرًۭا', 319, 16, 127, 0),
  (20, 100, 2448, 'مَّنْ أَعْرَضَ عَنْهُ فَإِنَّهُۥ يَحْمِلُ يَوْمَ ٱلْقِيَٰمَةِ وِزْرًا', 319, 16, 127, 0),
  (20, 101, 2449, 'خَٰلِدِينَ فِيهِ ۖ وَسَآءَ لَهُمْ يَوْمَ ٱلْقِيَٰمَةِ حِمْلًۭا', 319, 16, 127, 0),
  (20, 102, 2450, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ وَنَحْشُرُ ٱلْمُجْرِمِينَ يَوْمَئِذٍۢ زُرْقًۭا', 319, 16, 127, 0),
  (20, 103, 2451, 'يَتَخَٰفَتُونَ بَيْنَهُمْ إِن لَّبِثْتُمْ إِلَّا عَشْرًۭا', 319, 16, 127, 0),
  (20, 104, 2452, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ إِذْ يَقُولُ أَمْثَلُهُمْ طَرِيقَةً إِن لَّبِثْتُمْ إِلَّا يَوْمًۭا', 319, 16, 127, 0),
  (20, 105, 2453, 'وَيَسْـَٔلُونَكَ عَنِ ٱلْجِبَالِ فَقُلْ يَنسِفُهَا رَبِّى نَسْفًۭا', 319, 16, 127, 0),
  (20, 106, 2454, 'فَيَذَرُهَا قَاعًۭا صَفْصَفًۭا', 319, 16, 127, 0),
  (20, 107, 2455, 'لَّا تَرَىٰ فِيهَا عِوَجًۭا وَلَآ أَمْتًۭا', 319, 16, 127, 0),
  (20, 108, 2456, 'يَوْمَئِذٍۢ يَتَّبِعُونَ ٱلدَّاعِىَ لَا عِوَجَ لَهُۥ ۖ وَخَشَعَتِ ٱلْأَصْوَاتُ لِلرَّحْمَٰنِ فَلَا تَسْمَعُ إِلَّا هَمْسًۭا', 319, 16, 127, 0),
  (20, 109, 2457, 'يَوْمَئِذٍۢ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَرَضِىَ لَهُۥ قَوْلًۭا', 319, 16, 127, 0),
  (20, 110, 2458, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِهِۦ عِلْمًۭا', 319, 16, 127, 0),
  (20, 111, 2459, '۞ وَعَنَتِ ٱلْوُجُوهُ لِلْحَىِّ ٱلْقَيُّومِ ۖ وَقَدْ خَابَ مَنْ حَمَلَ ظُلْمًۭا', 319, 16, 128, 0),
  (20, 112, 2460, 'وَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌۭ فَلَا يَخَافُ ظُلْمًۭا وَلَا هَضْمًۭا', 319, 16, 128, 0),
  (20, 113, 2461, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ قُرْءَانًا عَرَبِيًّۭا وَصَرَّفْنَا فِيهِ مِنَ ٱلْوَعِيدِ لَعَلَّهُمْ يَتَّقُونَ أَوْ يُحْدِثُ لَهُمْ ذِكْرًۭا', 319, 16, 128, 0),
  (20, 114, 2462, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۗ وَلَا تَعْجَلْ بِٱلْقُرْءَانِ مِن قَبْلِ أَن يُقْضَىٰٓ إِلَيْكَ وَحْيُهُۥ ۖ وَقُل رَّبِّ زِدْنِى عِلْمًۭا', 320, 16, 128, 0),
  (20, 115, 2463, 'وَلَقَدْ عَهِدْنَآ إِلَىٰٓ ءَادَمَ مِن قَبْلُ فَنَسِىَ وَلَمْ نَجِدْ لَهُۥ عَزْمًۭا', 320, 16, 128, 0),
  (20, 116, 2464, 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ', 320, 16, 128, 0),
  (20, 117, 2465, 'فَقُلْنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوٌّۭ لَّكَ وَلِزَوْجِكَ فَلَا يُخْرِجَنَّكُمَا مِنَ ٱلْجَنَّةِ فَتَشْقَىٰٓ', 320, 16, 128, 0),
  (20, 118, 2466, 'إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعْرَىٰ', 320, 16, 128, 0),
  (20, 119, 2467, 'وَأَنَّكَ لَا تَظْمَؤُا۟ فِيهَا وَلَا تَضْحَىٰ', 320, 16, 128, 0),
  (20, 120, 2468, 'فَوَسْوَسَ إِلَيْهِ ٱلشَّيْطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلْ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلْخُلْدِ وَمُلْكٍۢ لَّا يَبْلَىٰ', 320, 16, 128, 0),
  (20, 121, 2469, 'فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ', 320, 16, 128, 0),
  (20, 122, 2470, 'ثُمَّ ٱجْتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ', 320, 16, 128, 0),
  (20, 123, 2471, 'قَالَ ٱهْبِطَا مِنْهَا جَمِيعًۢا ۖ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّۭ ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًۭى فَمَنِ ٱتَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشْقَىٰ', 320, 16, 128, 0),
  (20, 124, 2472, 'وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةًۭ ضَنكًۭا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ', 320, 16, 128, 0),
  (20, 125, 2473, 'قَالَ رَبِّ لِمَ حَشَرْتَنِىٓ أَعْمَىٰ وَقَدْ كُنتُ بَصِيرًۭا', 320, 16, 128, 0),
  (20, 126, 2474, 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَا ۖ وَكَذَٰلِكَ ٱلْيَوْمَ تُنسَىٰ', 321, 16, 128, 0),
  (20, 127, 2475, 'وَكَذَٰلِكَ نَجْزِى مَنْ أَسْرَفَ وَلَمْ يُؤْمِنۢ بِـَٔايَٰتِ رَبِّهِۦ ۚ وَلَعَذَابُ ٱلْءَاخِرَةِ أَشَدُّ وَأَبْقَىٰٓ', 321, 16, 128, 0),
  (20, 128, 2476, 'أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ يَمْشُونَ فِى مَسَٰكِنِهِمْ ۗ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّأُو۟لِى ٱلنُّهَىٰ', 321, 16, 128, 0),
  (20, 129, 2477, 'وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَكَانَ لِزَامًۭا وَأَجَلٌۭ مُّسَمًّۭى', 321, 16, 128, 0),
  (20, 130, 2478, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ غُرُوبِهَا ۖ وَمِنْ ءَانَآئِ ٱلَّيْلِ فَسَبِّحْ وَأَطْرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرْضَىٰ', 321, 16, 128, 0),
  (20, 131, 2479, 'وَلَا تَمُدَّنَّ عَيْنَيْكَ إِلَىٰ مَا مَتَّعْنَا بِهِۦٓ أَزْوَٰجًۭا مِّنْهُمْ زَهْرَةَ ٱلْحَيَوٰةِ ٱلدُّنْيَا لِنَفْتِنَهُمْ فِيهِ ۚ وَرِزْقُ رَبِّكَ خَيْرٌۭ وَأَبْقَىٰ', 321, 16, 128, 0),
  (20, 132, 2480, 'وَأْمُرْ أَهْلَكَ بِٱلصَّلَوٰةِ وَٱصْطَبِرْ عَلَيْهَا ۖ لَا نَسْـَٔلُكَ رِزْقًۭا ۖ نَّحْنُ نَرْزُقُكَ ۗ وَٱلْعَٰقِبَةُ لِلتَّقْوَىٰ', 321, 16, 128, 0),
  (20, 133, 2481, 'وَقَالُوا۟ لَوْلَا يَأْتِينَا بِـَٔايَةٍۢ مِّن رَّبِّهِۦٓ ۚ أَوَلَمْ تَأْتِهِم بَيِّنَةُ مَا فِى ٱلصُّحُفِ ٱلْأُولَىٰ', 321, 16, 128, 0),
  (20, 134, 2482, 'وَلَوْ أَنَّآ أَهْلَكْنَٰهُم بِعَذَابٍۢ مِّن قَبْلِهِۦ لَقَالُوا۟ رَبَّنَا لَوْلَآ أَرْسَلْتَ إِلَيْنَا رَسُولًۭا فَنَتَّبِعَ ءَايَٰتِكَ مِن قَبْلِ أَن نَّذِلَّ وَنَخْزَىٰ', 321, 16, 128, 0),
  (20, 135, 2483, 'قُلْ كُلٌّۭ مُّتَرَبِّصٌۭ فَتَرَبَّصُوا۟ ۖ فَسَتَعْلَمُونَ مَنْ أَصْحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِىِّ وَمَنِ ٱهْتَدَىٰ', 321, 16, 128, 0),
  (21, 1, 2484, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍۢ مُّعْرِضُونَ', 322, 17, 129, 0),
  (21, 2, 2485, 'مَا يَأْتِيهِم مِّن ذِكْرٍۢ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا ٱسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ', 322, 17, 129, 0),
  (21, 3, 2486, 'لَاهِيَةًۭ قُلُوبُهُمْ ۗ وَأَسَرُّوا۟ ٱلنَّجْوَى ٱلَّذِينَ ظَلَمُوا۟ هَلْ هَٰذَآ إِلَّا بَشَرٌۭ مِّثْلُكُمْ ۖ أَفَتَأْتُونَ ٱلسِّحْرَ وَأَنتُمْ تُبْصِرُونَ', 322, 17, 129, 0),
  (21, 4, 2487, 'قَالَ رَبِّى يَعْلَمُ ٱلْقَوْلَ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 322, 17, 129, 0),
  (21, 5, 2488, 'بَلْ قَالُوٓا۟ أَضْغَٰثُ أَحْلَٰمٍۭ بَلِ ٱفْتَرَىٰهُ بَلْ هُوَ شَاعِرٌۭ فَلْيَأْتِنَا بِـَٔايَةٍۢ كَمَآ أُرْسِلَ ٱلْأَوَّلُونَ', 322, 17, 129, 0),
  (21, 6, 2489, 'مَآ ءَامَنَتْ قَبْلَهُم مِّن قَرْيَةٍ أَهْلَكْنَٰهَآ ۖ أَفَهُمْ يُؤْمِنُونَ', 322, 17, 129, 0),
  (21, 7, 2490, 'وَمَآ أَرْسَلْنَا قَبْلَكَ إِلَّا رِجَالًۭا نُّوحِىٓ إِلَيْهِمْ ۖ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', 322, 17, 129, 0),
  (21, 8, 2491, 'وَمَا جَعَلْنَٰهُمْ جَسَدًۭا لَّا يَأْكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَٰلِدِينَ', 322, 17, 129, 0),
  (21, 9, 2492, 'ثُمَّ صَدَقْنَٰهُمُ ٱلْوَعْدَ فَأَنجَيْنَٰهُمْ وَمَن نَّشَآءُ وَأَهْلَكْنَا ٱلْمُسْرِفِينَ', 322, 17, 129, 0),
  (21, 10, 2493, 'لَقَدْ أَنزَلْنَآ إِلَيْكُمْ كِتَٰبًۭا فِيهِ ذِكْرُكُمْ ۖ أَفَلَا تَعْقِلُونَ', 322, 17, 129, 0),
  (21, 11, 2494, 'وَكَمْ قَصَمْنَا مِن قَرْيَةٍۢ كَانَتْ ظَالِمَةًۭ وَأَنشَأْنَا بَعْدَهَا قَوْمًا ءَاخَرِينَ', 323, 17, 129, 0),
  (21, 12, 2495, 'فَلَمَّآ أَحَسُّوا۟ بَأْسَنَآ إِذَا هُم مِّنْهَا يَرْكُضُونَ', 323, 17, 129, 0),
  (21, 13, 2496, 'لَا تَرْكُضُوا۟ وَٱرْجِعُوٓا۟ إِلَىٰ مَآ أُتْرِفْتُمْ فِيهِ وَمَسَٰكِنِكُمْ لَعَلَّكُمْ تُسْـَٔلُونَ', 323, 17, 129, 0),
  (21, 14, 2497, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 323, 17, 129, 0),
  (21, 15, 2498, 'فَمَا زَالَت تِّلْكَ دَعْوَىٰهُمْ حَتَّىٰ جَعَلْنَٰهُمْ حَصِيدًا خَٰمِدِينَ', 323, 17, 129, 0),
  (21, 16, 2499, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', 323, 17, 129, 0),
  (21, 17, 2500, 'لَوْ أَرَدْنَآ أَن نَّتَّخِذَ لَهْوًۭا لَّٱتَّخَذْنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ', 323, 17, 129, 0),
  (21, 18, 2501, 'بَلْ نَقْذِفُ بِٱلْحَقِّ عَلَى ٱلْبَٰطِلِ فَيَدْمَغُهُۥ فَإِذَا هُوَ زَاهِقٌۭ ۚ وَلَكُمُ ٱلْوَيْلُ مِمَّا تَصِفُونَ', 323, 17, 129, 0),
  (21, 19, 2502, 'وَلَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَمَنْ عِندَهُۥ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَلَا يَسْتَحْسِرُونَ', 323, 17, 129, 0),
  (21, 20, 2503, 'يُسَبِّحُونَ ٱلَّيْلَ وَٱلنَّهَارَ لَا يَفْتُرُونَ', 323, 17, 129, 0),
  (21, 21, 2504, 'أَمِ ٱتَّخَذُوٓا۟ ءَالِهَةًۭ مِّنَ ٱلْأَرْضِ هُمْ يُنشِرُونَ', 323, 17, 129, 0),
  (21, 22, 2505, 'لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا ۚ فَسُبْحَٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 323, 17, 129, 0),
  (21, 23, 2506, 'لَا يُسْـَٔلُ عَمَّا يَفْعَلُ وَهُمْ يُسْـَٔلُونَ', 323, 17, 129, 0),
  (21, 24, 2507, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةًۭ ۖ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ ۖ هَٰذَا ذِكْرُ مَن مَّعِىَ وَذِكْرُ مَن قَبْلِى ۗ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ ٱلْحَقَّ ۖ فَهُم مُّعْرِضُونَ', 323, 17, 129, 0),
  (21, 25, 2508, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍ إِلَّا نُوحِىٓ إِلَيْهِ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعْبُدُونِ', 324, 17, 129, 0),
  (21, 26, 2509, 'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحْمَٰنُ وَلَدًۭا ۗ سُبْحَٰنَهُۥ ۚ بَلْ عِبَادٌۭ مُّكْرَمُونَ', 324, 17, 129, 0),
  (21, 27, 2510, 'لَا يَسْبِقُونَهُۥ بِٱلْقَوْلِ وَهُم بِأَمْرِهِۦ يَعْمَلُونَ', 324, 17, 129, 0),
  (21, 28, 2511, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ٱرْتَضَىٰ وَهُم مِّنْ خَشْيَتِهِۦ مُشْفِقُونَ', 324, 17, 129, 0),
  (21, 29, 2512, '۞ وَمَن يَقُلْ مِنْهُمْ إِنِّىٓ إِلَٰهٌۭ مِّن دُونِهِۦ فَذَٰلِكَ نَجْزِيهِ جَهَنَّمَ ۚ كَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ', 324, 17, 130, 0),
  (21, 30, 2513, 'أَوَلَمْ يَرَ ٱلَّذِينَ كَفَرُوٓا۟ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ كَانَتَا رَتْقًۭا فَفَتَقْنَٰهُمَا ۖ وَجَعَلْنَا مِنَ ٱلْمَآءِ كُلَّ شَىْءٍ حَىٍّ ۖ أَفَلَا يُؤْمِنُونَ', 324, 17, 130, 0),
  (21, 31, 2514, 'وَجَعَلْنَا فِى ٱلْأَرْضِ رَوَٰسِىَ أَن تَمِيدَ بِهِمْ وَجَعَلْنَا فِيهَا فِجَاجًۭا سُبُلًۭا لَّعَلَّهُمْ يَهْتَدُونَ', 324, 17, 130, 0),
  (21, 32, 2515, 'وَجَعَلْنَا ٱلسَّمَآءَ سَقْفًۭا مَّحْفُوظًۭا ۖ وَهُمْ عَنْ ءَايَٰتِهَا مُعْرِضُونَ', 324, 17, 130, 0),
  (21, 33, 2516, 'وَهُوَ ٱلَّذِى خَلَقَ ٱلَّيْلَ وَٱلنَّهَارَ وَٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّۭ فِى فَلَكٍۢ يَسْبَحُونَ', 324, 17, 130, 0),
  (21, 34, 2517, 'وَمَا جَعَلْنَا لِبَشَرٍۢ مِّن قَبْلِكَ ٱلْخُلْدَ ۖ أَفَإِي۟ن مِّتَّ فَهُمُ ٱلْخَٰلِدُونَ', 324, 17, 130, 0),
  (21, 35, 2518, 'كُلُّ نَفْسٍۢ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةًۭ ۖ وَإِلَيْنَا تُرْجَعُونَ', 324, 17, 130, 0),
  (21, 36, 2519, 'وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓا۟ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى يَذْكُرُ ءَالِهَتَكُمْ وَهُم بِذِكْرِ ٱلرَّحْمَٰنِ هُمْ كَٰفِرُونَ', 325, 17, 130, 0),
  (21, 37, 2520, 'خُلِقَ ٱلْإِنسَٰنُ مِنْ عَجَلٍۢ ۚ سَأُو۟رِيكُمْ ءَايَٰتِى فَلَا تَسْتَعْجِلُونِ', 325, 17, 130, 0),
  (21, 38, 2521, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 325, 17, 130, 0),
  (21, 39, 2522, 'لَوْ يَعْلَمُ ٱلَّذِينَ كَفَرُوا۟ حِينَ لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمْ وَلَا هُمْ يُنصَرُونَ', 325, 17, 130, 0),
  (21, 40, 2523, 'بَلْ تَأْتِيهِم بَغْتَةًۭ فَتَبْهَتُهُمْ فَلَا يَسْتَطِيعُونَ رَدَّهَا وَلَا هُمْ يُنظَرُونَ', 325, 17, 130, 0),
  (21, 41, 2524, 'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍۢ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 325, 17, 130, 0),
  (21, 42, 2525, 'قُلْ مَن يَكْلَؤُكُم بِٱلَّيْلِ وَٱلنَّهَارِ مِنَ ٱلرَّحْمَٰنِ ۗ بَلْ هُمْ عَن ذِكْرِ رَبِّهِم مُّعْرِضُونَ', 325, 17, 130, 0),
  (21, 43, 2526, 'أَمْ لَهُمْ ءَالِهَةٌۭ تَمْنَعُهُم مِّن دُونِنَا ۚ لَا يَسْتَطِيعُونَ نَصْرَ أَنفُسِهِمْ وَلَا هُم مِّنَّا يُصْحَبُونَ', 325, 17, 130, 0),
  (21, 44, 2527, 'بَلْ مَتَّعْنَا هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ طَالَ عَلَيْهِمُ ٱلْعُمُرُ ۗ أَفَلَا يَرَوْنَ أَنَّا نَأْتِى ٱلْأَرْضَ نَنقُصُهَا مِنْ أَطْرَافِهَآ ۚ أَفَهُمُ ٱلْغَٰلِبُونَ', 325, 17, 130, 0),
  (21, 45, 2528, 'قُلْ إِنَّمَآ أُنذِرُكُم بِٱلْوَحْىِ ۚ وَلَا يَسْمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا مَا يُنذَرُونَ', 326, 17, 130, 0),
  (21, 46, 2529, 'وَلَئِن مَّسَّتْهُمْ نَفْحَةٌۭ مِّنْ عَذَابِ رَبِّكَ لَيَقُولُنَّ يَٰوَيْلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 326, 17, 130, 0),
  (21, 47, 2530, 'وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌۭ شَيْـًۭٔا ۖ وَإِن كَانَ مِثْقَالَ حَبَّةٍۢ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا ۗ وَكَفَىٰ بِنَا حَٰسِبِينَ', 326, 17, 130, 0),
  (21, 48, 2531, 'وَلَقَدْ ءَاتَيْنَا مُوسَىٰ وَهَٰرُونَ ٱلْفُرْقَانَ وَضِيَآءًۭ وَذِكْرًۭا لِّلْمُتَّقِينَ', 326, 17, 130, 0),
  (21, 49, 2532, 'ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشْفِقُونَ', 326, 17, 130, 0),
  (21, 50, 2533, 'وَهَٰذَا ذِكْرٌۭ مُّبَارَكٌ أَنزَلْنَٰهُ ۚ أَفَأَنتُمْ لَهُۥ مُنكِرُونَ', 326, 17, 130, 0),
  (21, 51, 2534, '۞ وَلَقَدْ ءَاتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ وَكُنَّا بِهِۦ عَٰلِمِينَ', 326, 17, 131, 0),
  (21, 52, 2535, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِىٓ أَنتُمْ لَهَا عَٰكِفُونَ', 326, 17, 131, 0),
  (21, 53, 2536, 'قَالُوا۟ وَجَدْنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ', 326, 17, 131, 0),
  (21, 54, 2537, 'قَالَ لَقَدْ كُنتُمْ أَنتُمْ وَءَابَآؤُكُمْ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 326, 17, 131, 0),
  (21, 55, 2538, 'قَالُوٓا۟ أَجِئْتَنَا بِٱلْحَقِّ أَمْ أَنتَ مِنَ ٱللَّٰعِبِينَ', 326, 17, 131, 0),
  (21, 56, 2539, 'قَالَ بَل رَّبُّكُمْ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ٱلَّذِى فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ', 326, 17, 131, 0),
  (21, 57, 2540, 'وَتَٱللَّهِ لَأَكِيدَنَّ أَصْنَٰمَكُم بَعْدَ أَن تُوَلُّوا۟ مُدْبِرِينَ', 326, 17, 131, 0),
  (21, 58, 2541, 'فَجَعَلَهُمْ جُذَٰذًا إِلَّا كَبِيرًۭا لَّهُمْ لَعَلَّهُمْ إِلَيْهِ يَرْجِعُونَ', 327, 17, 131, 0),
  (21, 59, 2542, 'قَالُوا۟ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ', 327, 17, 131, 0),
  (21, 60, 2543, 'قَالُوا۟ سَمِعْنَا فَتًۭى يَذْكُرُهُمْ يُقَالُ لَهُۥٓ إِبْرَٰهِيمُ', 327, 17, 131, 0),
  (21, 61, 2544, 'قَالُوا۟ فَأْتُوا۟ بِهِۦ عَلَىٰٓ أَعْيُنِ ٱلنَّاسِ لَعَلَّهُمْ يَشْهَدُونَ', 327, 17, 131, 0),
  (21, 62, 2545, 'قَالُوٓا۟ ءَأَنتَ فَعَلْتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبْرَٰهِيمُ', 327, 17, 131, 0),
  (21, 63, 2546, 'قَالَ بَلْ فَعَلَهُۥ كَبِيرُهُمْ هَٰذَا فَسْـَٔلُوهُمْ إِن كَانُوا۟ يَنطِقُونَ', 327, 17, 131, 0),
  (21, 64, 2547, 'فَرَجَعُوٓا۟ إِلَىٰٓ أَنفُسِهِمْ فَقَالُوٓا۟ إِنَّكُمْ أَنتُمُ ٱلظَّٰلِمُونَ', 327, 17, 131, 0),
  (21, 65, 2548, 'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمْ لَقَدْ عَلِمْتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ', 327, 17, 131, 0),
  (21, 66, 2549, 'قَالَ أَفَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمْ شَيْـًۭٔا وَلَا يَضُرُّكُمْ', 327, 17, 131, 0),
  (21, 67, 2550, 'أُفٍّۢ لَّكُمْ وَلِمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ ۖ أَفَلَا تَعْقِلُونَ', 327, 17, 131, 0),
  (21, 68, 2551, 'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوٓا۟ ءَالِهَتَكُمْ إِن كُنتُمْ فَٰعِلِينَ', 327, 17, 131, 0),
  (21, 69, 2552, 'قُلْنَا يَٰنَارُ كُونِى بَرْدًۭا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ', 327, 17, 131, 0),
  (21, 70, 2553, 'وَأَرَادُوا۟ بِهِۦ كَيْدًۭا فَجَعَلْنَٰهُمُ ٱلْأَخْسَرِينَ', 327, 17, 131, 0),
  (21, 71, 2554, 'وَنَجَّيْنَٰهُ وَلُوطًا إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا لِلْعَٰلَمِينَ', 327, 17, 131, 0),
  (21, 72, 2555, 'وَوَهَبْنَا لَهُۥٓ إِسْحَٰقَ وَيَعْقُوبَ نَافِلَةًۭ ۖ وَكُلًّۭا جَعَلْنَا صَٰلِحِينَ', 327, 17, 131, 0),
  (21, 73, 2556, 'وَجَعَلْنَٰهُمْ أَئِمَّةًۭ يَهْدُونَ بِأَمْرِنَا وَأَوْحَيْنَآ إِلَيْهِمْ فِعْلَ ٱلْخَيْرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِ ۖ وَكَانُوا۟ لَنَا عَٰبِدِينَ', 328, 17, 131, 0),
  (21, 74, 2557, 'وَلُوطًا ءَاتَيْنَٰهُ حُكْمًۭا وَعِلْمًۭا وَنَجَّيْنَٰهُ مِنَ ٱلْقَرْيَةِ ٱلَّتِى كَانَت تَّعْمَلُ ٱلْخَبَٰٓئِثَ ۗ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍۢ فَٰسِقِينَ', 328, 17, 131, 0),
  (21, 75, 2558, 'وَأَدْخَلْنَٰهُ فِى رَحْمَتِنَآ ۖ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ', 328, 17, 131, 0),
  (21, 76, 2559, 'وَنُوحًا إِذْ نَادَىٰ مِن قَبْلُ فَٱسْتَجَبْنَا لَهُۥ فَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 328, 17, 131, 0),
  (21, 77, 2560, 'وَنَصَرْنَٰهُ مِنَ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمَ سَوْءٍۢ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 328, 17, 131, 0),
  (21, 78, 2561, 'وَدَاوُۥدَ وَسُلَيْمَٰنَ إِذْ يَحْكُمَانِ فِى ٱلْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ ٱلْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَٰهِدِينَ', 328, 17, 131, 0),
  (21, 79, 2562, 'فَفَهَّمْنَٰهَا سُلَيْمَٰنَ ۚ وَكُلًّا ءَاتَيْنَا حُكْمًۭا وَعِلْمًۭا ۚ وَسَخَّرْنَا مَعَ دَاوُۥدَ ٱلْجِبَالَ يُسَبِّحْنَ وَٱلطَّيْرَ ۚ وَكُنَّا فَٰعِلِينَ', 328, 17, 131, 0),
  (21, 80, 2563, 'وَعَلَّمْنَٰهُ صَنْعَةَ لَبُوسٍۢ لَّكُمْ لِتُحْصِنَكُم مِّنۢ بَأْسِكُمْ ۖ فَهَلْ أَنتُمْ شَٰكِرُونَ', 328, 17, 131, 0),
  (21, 81, 2564, 'وَلِسُلَيْمَٰنَ ٱلرِّيحَ عَاصِفَةًۭ تَجْرِى بِأَمْرِهِۦٓ إِلَى ٱلْأَرْضِ ٱلَّتِى بَٰرَكْنَا فِيهَا ۚ وَكُنَّا بِكُلِّ شَىْءٍ عَٰلِمِينَ', 328, 17, 131, 0),
  (21, 82, 2565, 'وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعْمَلُونَ عَمَلًۭا دُونَ ذَٰلِكَ ۖ وَكُنَّا لَهُمْ حَٰفِظِينَ', 329, 17, 131, 0),
  (21, 83, 2566, '۞ وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ', 329, 17, 132, 0),
  (21, 84, 2567, 'فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّۢ ۖ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةًۭ مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ', 329, 17, 132, 0),
  (21, 85, 2568, 'وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ ۖ كُلٌّۭ مِّنَ ٱلصَّٰبِرِينَ', 329, 17, 132, 0),
  (21, 86, 2569, 'وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ ۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ', 329, 17, 132, 0),
  (21, 87, 2570, 'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًۭا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ', 329, 17, 132, 0),
  (21, 88, 2571, 'فَٱسْتَجَبْنَا لَهُۥ وَنَجَّيْنَٰهُ مِنَ ٱلْغَمِّ ۚ وَكَذَٰلِكَ نُۨجِى ٱلْمُؤْمِنِينَ', 329, 17, 132, 0),
  (21, 89, 2572, 'وَزَكَرِيَّآ إِذْ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرْنِى فَرْدًۭا وَأَنتَ خَيْرُ ٱلْوَٰرِثِينَ', 329, 17, 132, 0),
  (21, 90, 2573, 'فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ ۚ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًۭا وَرَهَبًۭا ۖ وَكَانُوا۟ لَنَا خَٰشِعِينَ', 329, 17, 132, 0),
  (21, 91, 2574, 'وَٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهَا مِن رُّوحِنَا وَجَعَلْنَٰهَا وَٱبْنَهَآ ءَايَةًۭ لِّلْعَٰلَمِينَ', 330, 17, 132, 0),
  (21, 92, 2575, 'إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ', 330, 17, 132, 0),
  (21, 93, 2576, 'وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ ۖ كُلٌّ إِلَيْنَا رَٰجِعُونَ', 330, 17, 132, 0),
  (21, 94, 2577, 'فَمَن يَعْمَلْ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤْمِنٌۭ فَلَا كُفْرَانَ لِسَعْيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ', 330, 17, 132, 0),
  (21, 95, 2578, 'وَحَرَٰمٌ عَلَىٰ قَرْيَةٍ أَهْلَكْنَٰهَآ أَنَّهُمْ لَا يَرْجِعُونَ', 330, 17, 132, 0),
  (21, 96, 2579, 'حَتَّىٰٓ إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ وَهُم مِّن كُلِّ حَدَبٍۢ يَنسِلُونَ', 330, 17, 132, 0),
  (21, 97, 2580, 'وَٱقْتَرَبَ ٱلْوَعْدُ ٱلْحَقُّ فَإِذَا هِىَ شَٰخِصَةٌ أَبْصَٰرُ ٱلَّذِينَ كَفَرُوا۟ يَٰوَيْلَنَا قَدْ كُنَّا فِى غَفْلَةٍۢ مِّنْ هَٰذَا بَلْ كُنَّا ظَٰلِمِينَ', 330, 17, 132, 0),
  (21, 98, 2581, 'إِنَّكُمْ وَمَا تَعْبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمْ لَهَا وَٰرِدُونَ', 330, 17, 132, 0),
  (21, 99, 2582, 'لَوْ كَانَ هَٰٓؤُلَآءِ ءَالِهَةًۭ مَّا وَرَدُوهَا ۖ وَكُلٌّۭ فِيهَا خَٰلِدُونَ', 330, 17, 132, 0),
  (21, 100, 2583, 'لَهُمْ فِيهَا زَفِيرٌۭ وَهُمْ فِيهَا لَا يَسْمَعُونَ', 330, 17, 132, 0),
  (21, 101, 2584, 'إِنَّ ٱلَّذِينَ سَبَقَتْ لَهُم مِّنَّا ٱلْحُسْنَىٰٓ أُو۟لَٰٓئِكَ عَنْهَا مُبْعَدُونَ', 330, 17, 132, 0),
  (21, 102, 2585, 'لَا يَسْمَعُونَ حَسِيسَهَا ۖ وَهُمْ فِى مَا ٱشْتَهَتْ أَنفُسُهُمْ خَٰلِدُونَ', 331, 17, 132, 0),
  (21, 103, 2586, 'لَا يَحْزُنُهُمُ ٱلْفَزَعُ ٱلْأَكْبَرُ وَتَتَلَقَّىٰهُمُ ٱلْمَلَٰٓئِكَةُ هَٰذَا يَوْمُكُمُ ٱلَّذِى كُنتُمْ تُوعَدُونَ', 331, 17, 132, 0),
  (21, 104, 2587, 'يَوْمَ نَطْوِى ٱلسَّمَآءَ كَطَىِّ ٱلسِّجِلِّ لِلْكُتُبِ ۚ كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍۢ نُّعِيدُهُۥ ۚ وَعْدًا عَلَيْنَآ ۚ إِنَّا كُنَّا فَٰعِلِينَ', 331, 17, 132, 0),
  (21, 105, 2588, 'وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ', 331, 17, 132, 0),
  (21, 106, 2589, 'إِنَّ فِى هَٰذَا لَبَلَٰغًۭا لِّقَوْمٍ عَٰبِدِينَ', 331, 17, 132, 0),
  (21, 107, 2590, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا رَحْمَةًۭ لِّلْعَٰلَمِينَ', 331, 17, 132, 0),
  (21, 108, 2591, 'قُلْ إِنَّمَا يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ ۖ فَهَلْ أَنتُم مُّسْلِمُونَ', 331, 17, 132, 0),
  (21, 109, 2592, 'فَإِن تَوَلَّوْا۟ فَقُلْ ءَاذَنتُكُمْ عَلَىٰ سَوَآءٍۢ ۖ وَإِنْ أَدْرِىٓ أَقَرِيبٌ أَم بَعِيدٌۭ مَّا تُوعَدُونَ', 331, 17, 132, 0),
  (21, 110, 2593, 'إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ مِنَ ٱلْقَوْلِ وَيَعْلَمُ مَا تَكْتُمُونَ', 331, 17, 132, 0),
  (21, 111, 2594, 'وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌۭ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍۢ', 331, 17, 132, 0),
  (21, 112, 2595, 'قَٰلَ رَبِّ ٱحْكُم بِٱلْحَقِّ ۗ وَرَبُّنَا ٱلرَّحْمَٰنُ ٱلْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ', 331, 17, 132, 0),
  (22, 1, 2596, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ ۚ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌۭ', 332, 17, 133, 0),
  (22, 2, 2597, 'يَوْمَ تَرَوْنَهَا تَذْهَلُ كُلُّ مُرْضِعَةٍ عَمَّآ أَرْضَعَتْ وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌۭ', 332, 17, 133, 0),
  (22, 3, 2598, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍۢ وَيَتَّبِعُ كُلَّ شَيْطَٰنٍۢ مَّرِيدٍۢ', 332, 17, 133, 0),
  (22, 4, 2599, 'كُتِبَ عَلَيْهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهْدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ', 332, 17, 133, 0),
  (22, 5, 2600, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍۢ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَٰكُم مِّن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ مِنْ عَلَقَةٍۢ ثُمَّ مِن مُّضْغَةٍۢ مُّخَلَّقَةٍۢ وَغَيْرِ مُخَلَّقَةٍۢ لِّنُبَيِّنَ لَكُمْ ۚ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ثُمَّ نُخْرِجُكُمْ طِفْلًۭا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍۢ شَيْـًۭٔا ۚ وَتَرَى ٱلْأَرْضَ هَامِدَةًۭ فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍۢ', 332, 17, 133, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 22, 1, 'O mankind, fear your Lord. Indeed, the convulsion of the [final] Hour is a terrible thing.'),
  ('en.sahih', 22, 2, 'On the Day you see it every nursing mother will be distracted from that [child] she was nursing, and every pregnant woman will abort her pregnancy, and you will see the people [appearing] intoxicated while they are not intoxicated; but the punishment of Allah is severe.'),
  ('en.sahih', 22, 3, 'And of the people is he who disputes about Allah without knowledge and follows every rebellious devil.'),
  ('en.sahih', 22, 4, 'It has been decreed for every devil that whoever turns to him - he will misguide him and will lead him to the punishment of the Blaze.'),
  ('en.sahih', 22, 5, 'O People, if you should be in doubt about the Resurrection, then [consider that] indeed, We created you from dust, then from a sperm-drop, then from a clinging clot, and then from a lump of flesh, formed and unformed - that We may show you. And We settle in the wombs whom We will for a specified term, then We bring you out as a child, and then [We develop you] that you may reach your [time of] maturity. And among you is he who is taken in [early] death, and among you is he who is returned to the most decrepit [old] age so that he knows, after [once having] knowledge, nothing. And you see the earth barren, but when We send down upon it rain, it quivers and swells and grows [something] of every beautiful kind.'),
  ('en.sahih', 22, 6, 'That is because Allah is the Truth and because He gives life to the dead and because He is over all things competent'),
  ('en.sahih', 22, 7, 'And [that they may know] that the Hour is coming - no doubt about it - and that Allah will resurrect those in the graves.'),
  ('en.sahih', 22, 8, 'And of the people is he who disputes about Allah without knowledge or guidance or an enlightening book [from Him],'),
  ('en.sahih', 22, 9, 'Twisting his neck [in arrogance] to mislead [people] from the way of Allah. For him in the world is disgrace, and We will make him taste on the Day of Resurrection the punishment of the Burning Fire [while it is said],'),
  ('en.sahih', 22, 10, '"That is for what your hands have put forth and because Allah is not ever unjust to [His] servants."'),
  ('en.sahih', 22, 11, 'And of the people is he who worships Allah on an edge. If he is touched by good, he is reassured by it; but if he is struck by trial, he turns on his face [to the other direction]. He has lost [this] world and the Hereafter. That is what is the manifest loss.'),
  ('en.sahih', 22, 12, 'He invokes instead of Allah that which neither harms him nor benefits him. That is what is the extreme error.'),
  ('en.sahih', 22, 13, 'He invokes one whose harm is closer than his benefit - how wretched the protector and how wretched the associate.'),
  ('en.sahih', 22, 14, 'Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. Indeed, Allah does what He intends.'),
  ('en.sahih', 22, 15, 'Whoever should think that Allah will not support [Prophet Muhammad] in this world and the Hereafter - let him extend a rope to the ceiling, then cut off [his breath], and let him see: will his effort remove that which enrages [him]?'),
  ('en.sahih', 22, 16, 'And thus have We sent the Qur\'an down as verses of clear evidence and because Allah guides whom He intends.'),
  ('en.sahih', 22, 17, 'Indeed, those who have believed and those who were Jews and the Sabeans and the Christians and the Magians and those who associated with Allah - Allah will judge between them on the Day of Resurrection. Indeed Allah is, over all things, Witness.'),
  ('en.sahih', 22, 18, 'Do you not see that to Allah prostrates whoever is in the heavens and whoever is on the earth and the sun, the moon, the stars, the mountains, the trees, the moving creatures and many of the people? But upon many the punishment has been justified. And he whom Allah humiliates - for him there is no bestower of honor. Indeed, Allah does what He wills.'),
  ('en.sahih', 22, 19, 'These are two adversaries who have disputed over their Lord. But those who disbelieved will have cut out for them garments of fire. Poured upon their heads will be scalding water'),
  ('en.sahih', 22, 20, 'By which is melted that within their bellies and [their] skins.'),
  ('en.sahih', 22, 21, 'And for [striking] them are maces of iron.'),
  ('en.sahih', 22, 22, 'Every time they want to get out of Hellfire from anguish, they will be returned to it, and [it will be said], "Taste the punishment of the Burning Fire!"'),
  ('en.sahih', 22, 23, 'Indeed, Allah will admit those who believe and do righteous deeds to gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and pearl, and their garments therein will be silk.'),
  ('en.sahih', 22, 24, 'And they had been guided [in worldly life] to good speech, and they were guided to the path of the Praiseworthy.'),
  ('en.sahih', 22, 25, 'Indeed, those who have disbelieved and avert [people] from the way of Allah and [from] al-Masjid al-Haram, which We made for the people - equal are the resident therein and one from outside; and [also] whoever intends [a deed] therein of deviation [in religion] or wrongdoing - We will make him taste of a painful punishment.'),
  ('en.sahih', 22, 26, 'And [mention, O Muhammad], when We designated for Abraham the site of the House, [saying], "Do not associate anything with Me and purify My House for those who perform Tawaf and those who stand [in prayer] and those who bow and prostrate.'),
  ('en.sahih', 22, 27, 'And proclaim to the people the Hajj [pilgrimage]; they will come to you on foot and on every lean camel; they will come from every distant pass -'),
  ('en.sahih', 22, 28, 'That they may witness benefits for themselves and mention the name of Allah on known days over what He has provided for them of [sacrificial] animals. So eat of them and feed the miserable and poor.'),
  ('en.sahih', 22, 29, 'Then let them end their untidiness and fulfill their vows and perform Tawaf around the ancient House."'),
  ('en.sahih', 22, 30, 'That [has been commanded], and whoever honors the sacred ordinances of Allah - it is best for him in the sight of his Lord. And permitted to you are the grazing livestock, except what is recited to you. So avoid the uncleanliness of idols and avoid false statement,'),
  ('en.sahih', 22, 31, 'Inclining [only] to Allah, not associating [anything] with Him. And he who associates with Allah - it is as though he had fallen from the sky and was snatched by the birds or the wind carried him down into a remote place.'),
  ('en.sahih', 22, 32, 'That [is so]. And whoever honors the symbols of Allah - indeed, it is from the piety of hearts.'),
  ('en.sahih', 22, 33, 'For you the animals marked for sacrifice are benefits for a specified term; then their place of sacrifice is at the ancient House.'),
  ('en.sahih', 22, 34, 'And for all religion We have appointed a rite [of sacrifice] that they may mention the name of Allah over what He has provided for them of [sacrificial] animals. For your god is one God, so to Him submit. And, [O Muhammad], give good tidings to the humble [before their Lord]'),
  ('en.sahih', 22, 35, 'Who, when Allah is mentioned, their hearts are fearful, and [to] the patient over what has afflicted them, and the establishers of prayer and those who spend from what We have provided them.'),
  ('en.sahih', 22, 36, 'And the camels and cattle We have appointed for you as among the symbols of Allah; for you therein is good. So mention the name of Allah upon them when lined up [for sacrifice]; and when they are [lifeless] on their sides, then eat from them and feed the needy and the beggar. Thus have We subjected them to you that you may be grateful.'),
  ('en.sahih', 22, 37, 'Their meat will not reach Allah, nor will their blood, but what reaches Him is piety from you. Thus have We subjected them to you that you may glorify Allah for that [to] which He has guided you; and give good tidings to the doers of good.'),
  ('en.sahih', 22, 38, 'Indeed, Allah defends those who have believed. Indeed, Allah does not like everyone treacherous and ungrateful.'),
  ('en.sahih', 22, 39, 'Permission [to fight] has been given to those who are being fought, because they were wronged. And indeed, Allah is competent to give them victory.'),
  ('en.sahih', 22, 40, '[They are] those who have been evicted from their homes without right - only because they say, "Our Lord is Allah." And were it not that Allah checks the people, some by means of others, there would have been demolished monasteries, churches, synagogues, and mosques in which the name of Allah is much mentioned. And Allah will surely support those who support Him. Indeed, Allah is Powerful and Exalted in Might.'),
  ('en.sahih', 22, 41, '[And they are] those who, if We give them authority in the land, establish prayer and give zakah and enjoin what is right and forbid what is wrong. And to Allah belongs the outcome of [all] matters.'),
  ('en.sahih', 22, 42, 'And if they deny you, [O Muhammad] - so, before them, did the people of Noah and \'Aad and Thamud deny [their prophets],'),
  ('en.sahih', 22, 43, 'And the people of Abraham and the people of Lot'),
  ('en.sahih', 22, 44, 'And the inhabitants of Madyan. And Moses was denied, so I prolonged enjoyment for the disbelievers; then I seized them, and how [terrible] was My reproach.'),
  ('en.sahih', 22, 45, 'And how many a city did We destroy while it was committing wrong - so it is [now] fallen into ruin - and [how many] an abandoned well and [how many] a lofty palace.'),
  ('en.sahih', 22, 46, 'So have they not traveled through the earth and have hearts by which to reason and ears by which to hear? For indeed, it is not eyes that are blinded, but blinded are the hearts which are within the breasts.'),
  ('en.sahih', 22, 47, 'And they urge you to hasten the punishment. But Allah will never fail in His promise. And indeed, a day with your Lord is like a thousand years of those which you count.'),
  ('en.sahih', 22, 48, 'And for how many a city did I prolong enjoyment while it was committing wrong. Then I seized it, and to Me is the [final] destination.'),
  ('en.sahih', 22, 49, 'Say, "O people, I am only to you a clear warner."'),
  ('en.sahih', 22, 50, 'And those who have believed and done righteous deeds - for them is forgiveness and noble provision.'),
  ('en.sahih', 22, 51, 'But the ones who strove against Our verses, [seeking] to cause failure - those are the companions of Hellfire.'),
  ('en.sahih', 22, 52, 'And We did not send before you any messenger or prophet except that when he spoke [or recited], Satan threw into it [some misunderstanding]. But Allah abolishes that which Satan throws in; then Allah makes precise His verses. And Allah is Knowing and Wise.'),
  ('en.sahih', 22, 53, '[That is] so He may make what Satan throws in a trial for those within whose hearts is disease and those hard of heart. And indeed, the wrongdoers are in extreme dissension.'),
  ('en.sahih', 22, 54, 'And so those who were given knowledge may know that it is the truth from your Lord and [therefore] believe in it, and their hearts humbly submit to it. And indeed is Allah the Guide of those who have believed to a straight path.'),
  ('en.sahih', 22, 55, 'But those who disbelieve will not cease to be in doubt of it until the Hour comes upon them unexpectedly or there comes to them the punishment of a barren Day.'),
  ('en.sahih', 22, 56, '[All] sovereignty that Day is for Allah; He will judge between them. So they who believed and did righteous deeds will be in the Gardens of Pleasure.'),
  ('en.sahih', 22, 57, 'And they who disbelieved and denied Our signs - for those there will be a humiliating punishment.'),
  ('en.sahih', 22, 58, 'And those who emigrated for the cause of Allah and then were killed or died - Allah will surely provide for them a good provision. And indeed, it is Allah who is the best of providers.'),
  ('en.sahih', 22, 59, 'He will surely cause them to enter an entrance with which they will be pleased, and indeed, Allah is Knowing and Forbearing.'),
  ('en.sahih', 22, 60, 'That [is so]. And whoever responds [to injustice] with the equivalent of that with which he was harmed and then is tyrannized - Allah will surely aid him. Indeed, Allah is Pardoning and Forgiving.'),
  ('en.sahih', 22, 61, 'That is because Allah causes the night to enter the day and causes the day to enter the night and because Allah is Hearing and Seeing.'),
  ('en.sahih', 22, 62, 'That is because Allah is the Truth, and that which they call upon other than Him is falsehood, and because Allah is the Most High, the Grand.'),
  ('en.sahih', 22, 63, 'Do you not see that Allah has sent down rain from the sky and the earth becomes green? Indeed, Allah is Subtle and Acquainted.'),
  ('en.sahih', 22, 64, 'To Him belongs what is in the heavens and what is on the earth. And indeed, Allah is the Free of need, the Praiseworthy.'),
  ('en.sahih', 22, 65, 'Do you not see that Allah has subjected to you whatever is on the earth and the ships which run through the sea by His command? And He restrains the sky from falling upon the earth, unless by His permission. Indeed Allah, to the people, is Kind and Merciful.'),
  ('en.sahih', 22, 66, 'And He is the one who gave you life; then He causes you to die and then will [again] give you life. Indeed, mankind is ungrateful.'),
  ('en.sahih', 22, 67, 'For every religion We have appointed rites which they perform. So, [O Muhammad], let the disbelievers not contend with you over the matter but invite them to your Lord. Indeed, you are upon straight guidance.'),
  ('en.sahih', 22, 68, 'And if they dispute with you, then say, "Allah is most knowing of what you do.'),
  ('en.sahih', 22, 69, 'Allah will judge between you on the Day of Resurrection concerning that over which you used to differ."'),
  ('en.sahih', 22, 70, 'Do you not know that Allah knows what is in the heaven and earth? Indeed, that is in a Record. Indeed that, for Allah, is easy.'),
  ('en.sahih', 22, 71, 'And they worship besides Allah that for which He has not sent down authority and that of which they have no knowledge. And there will not be for the wrongdoers any helper.'),
  ('en.sahih', 22, 72, 'And when Our verses are recited to them as clear evidences, you recognize in the faces of those who disbelieve disapproval. They are almost on the verge of assaulting those who recite to them Our verses. Say, "Then shall I inform you of [what is] worse than that? [It is] the Fire which Allah has promised those who disbelieve, and wretched is the destination."'),
  ('en.sahih', 22, 73, 'O people, an example is presented, so listen to it. Indeed, those you invoke besides Allah will never create [as much as] a fly, even if they gathered together for that purpose. And if the fly should steal away from them a [tiny] thing, they could not recover it from him. Weak are the pursuer and pursued.'),
  ('en.sahih', 22, 74, 'They have not appraised Allah with true appraisal. Indeed, Allah is Powerful and Exalted in Might.'),
  ('en.sahih', 22, 75, 'Allah chooses from the angels messengers and from the people. Indeed, Allah is Hearing and Seeing.'),
  ('en.sahih', 22, 76, 'He knows what is [presently] before them and what will be after them. And to Allah will be returned [all] matters.'),
  ('en.sahih', 22, 77, 'O you who have believed, bow and prostrate and worship your Lord and do good - that you may succeed.'),
  ('en.sahih', 22, 78, 'And strive for Allah with the striving due to Him. He has chosen you and has not placed upon you in the religion any difficulty. [It is] the religion of your father, Abraham. Allah named you "Muslims" before [in former scriptures] and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people. So establish prayer and give zakah and hold fast to Allah. He is your protector; and excellent is the protector, and excellent is the helper.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 22, 1, 'হে লোক সকল! তোমাদের পালনকর্তাকে ভয় কর। নিশ্চয় কেয়ামতের প্রকম্পন একটি ভয়ংকর ব্যাপার।'),
  ('bn.bengali', 22, 2, 'যেদিন তোমরা তা প্রত্যক্ষ করবে, সেদিন প্রত্যেক স্তন্যধাত্রী তার দুধের শিশুকে বিস্মৃত হবে এবং প্রত্যেক গর্ভবতী তার গর্ভপাত করবে এবং মানুষকে তুমি দেখবে মাতাল; অথচ তারা মাতাল নয় বস্তুতঃ আল্লাহর আযাব সুকঠিন।'),
  ('bn.bengali', 22, 3, 'কতক মানুষ অজ্ঞানতাবশতঃ আল্লাহ সম্পꦣ2503;ক বিতর্ক করে এবং প্রত্যেক অবাধ্য শয়তানের অনুসরণ করে।'),
  ('bn.bengali', 22, 4, 'শয়তান সম্পর্কে লিখে দেয়া হয়েছে যে, যে কেউ তার সাথী হবে, সে তাকে বিভ্রান্ত করবে এবং দোযখের আযাবের দিকে পরিচালিত করবে।'),
  ('bn.bengali', 22, 5, 'হে লোকসকল! যদি তোমরা পুনরুত্থানের ব্যাপারে সন্দিগ্ধ হও, তবে (ভেবে দেখ-) আমি তোমাদেরকে মৃত্তিকা থেকে সৃষ্টি করেছি। এরপর বীর্য থেকে, এরপর জমাট রক্ত থেকে, এরপর পূর্ণাকৃতিবিশিষ্ট ও অপূর্ণাকৃতিবিশিষ্ট মাংসপিন্ড থেকে, তোমাদের কাছে ব্যক্ত করার জন্যে। আর আমি এক নির্দিষ্ট কালের জন্যে মাতৃগর্ভে যা ইচ্ছা রেখে দেই, এরপর আমি তোমাদেরকে শিশু অবস্থায় বের করি; তারপর যাতে তোমরা যৌবনে পদার্পণ কর। তোমাদের মধ্যে কেউ কেউ মৃত্যুমুখে পতিত হয় এবং তোমাদের মধ্যে কাউকে নিষ্কর্মা বয়স পর্যন্ত পৌছানো হয়, যাতে সে জানার পর জ্ঞাত বিষয় সম্পর্কে সজ্ঞান থাকে না। তুমি ভূমিকে পতিত দেখতে পাও, অতঃপর আমি যখন তাতে বৃষ্টি বর্ষণ করি, তখন তা সতেজ ও স্ফীত হয়ে যায় এবং সর্বপ্রকার সুদৃশ্য উদ্ভিদ উৎপন্ন করে।'),
  ('bn.bengali', 22, 6, 'এগুলো এ কারণে যে, আল্লাহ সত্য এবং তিনি মৃতকে জীবিত করেন এবং তিনি সবকিছুর উপর ক্ষমতাবান।'),
  ('bn.bengali', 22, 7, 'এবং এ কারণে যে, কেয়ামত অবশ্যম্ভাবী, এতে সন্দেহ নেই এবং এ কারণে যে, কবরে যারা আছে, আল্লাহ তাদেরকে পুনরুত্থিত করবেন।'),
  ('bn.bengali', 22, 8, 'কতক মানুষ জ্ঞান; প্রমাণ ও উজ্জ্বল কিতাব ছাড়াই আল্লাহ সম্পর্কে বিতর্ক করে।'),
  ('bn.bengali', 22, 9, 'সে পার্শ্ব পরিবর্তন করে বিতর্ক করে, যাতে আল্লাহর পথ থেকে বিভ্রান্ত করে দেয়। তার জন্যে দুনিয়াতে লাঞ্ছনা আছে এবং কেয়ামতের দিন আমি তাকে দহন-যন্ত্রণা আস্বাদন করাব।'),
  ('bn.bengali', 22, 10, 'এটা তোমার দুই হাতের কর্মের কারণে, আল্লাহ বান্দাদের প্রতি জুলুম করেন না।'),
  ('bn.bengali', 22, 11, 'মানুষের মধ্যে কেউ কেউ দ্বিধা-দ্বন্দ্বে জড়িত হয়ে আল্লাহর এবাদত করে। যদি সে কল্যাণ প্রাপ্ত হয়, তবে এবাদতের উপর কায়েম থাকে এবং যদি কোন পরীক্ষায় পড়ে, তবে পূর্বাবস্থায় ফিরে যায়। সে ইহকালে ও পরকালে ক্ষতিগ্রস্ত। এটাই প্রকাশ্য ক্ষতি'),
  ('bn.bengali', 22, 12, 'সে আল্লাহর পরিবর্তে এমন কিছুকে ডাকে, যে তার অপকার করতে পারে না এবং উপকারও করতে পারে না। এটাই চরম পথভ্রষ্টতা।'),
  ('bn.bengali', 22, 13, 'সে এমন কিছুকে ডাকে, যার অপকার উপকারের আগে পৌছে। কত মন্দ এই বন্ধু এবং কত মন্দ এই সঙ্গী।'),
  ('bn.bengali', 22, 14, 'যারা বিশ্বাস স্থাপন করে ও সৎকর্ম সম্পাদন করে, আল্লাহ তাদেরকে জান্নাতে দাখিল করবেন, যার তলদেশ দিয়ে নির্ঝরণীসমূহ প্রবাহিত হয়। আল্লাহ যা ইচ্ছা তাই করেন।'),
  ('bn.bengali', 22, 15, 'সে ধারণা করে যে, আল্লাহ কখনই ইহকালে ও পরকালে রাসূলকে সাহায্য করবেন না, সে একটি রশি আকাশ পর্যন্ত ঝুলিয়ে নিক; এরপর কেটে দিক; অতঃপর দেখুক তার এই কৌশল তার আক্রোশ দূর করে কিনা।'),
  ('bn.bengali', 22, 16, 'এমনিভাবে আমি সুস্পষ্ট আয়াত রূপে কোরআন নাযিল করেছি এবং আল্লাহ-ই যাকে ইচ্ছা হেদায়েত করেন।'),
  ('bn.bengali', 22, 17, 'যারা মুসলমান, যারা ইহুদী, সাবেয়ী, খ্রীষ্টান, অগ্নিপুজক এবং যারা মুশরেক, কেয়ামতের দিন আল্লাহ অবশ্যই তাদের মধ্যে ফায়সালা করে দেবেন। সবকিছুই আল্লাহর দৃষ্টির সামনে।'),
  ('bn.bengali', 22, 18, 'তুমি কি দেখনি যে, আল্লাহকে সেজদা করে যা কিছু আছে নভোমন্ডলে, যা কিছু আছে ভুমন্ডলে, সূর্য, চন্দ্র, তারকারাজি পর্বতরাজি বৃক্ষলতা, জীবজন্তু এবং অনেক মানুষ। আবার অনেকের উপর অবধারিত হয়েছে শাস্তি। আল্লাহ যাকে ইচ্ছা লাঞ্ছিত করেন, তাকে কেউ সম্মান দিতে পারে না। আল্লাহ যা ইচ্ছা তাই করেন'),
  ('bn.bengali', 22, 19, 'এই দুই বাদী বিবাদী, তারা তাদের পালনকর্তা সম্পর্কে বিতর্ক করে। অতএব যারা কাফের, তাদের জন্যে আগুনের পোশাক তৈরী করা হয়েছে। তাদের মাথার উপর ফুটন্ত পানি ঢেলে দেয়া হবে।'),
  ('bn.bengali', 22, 20, 'ফলে তাদের পেটে যা আছে, তা এবং চর্ম গলে বের হয়ে যাবে।'),
  ('bn.bengali', 22, 21, 'তাদের জন্যে আছে লোহার হাতুড়ি।'),
  ('bn.bengali', 22, 22, 'তারা যখনই যন্ত্রনায় অতিষ্ঠ হয়ে জাহান্নাম থেকে বের হতে চাইবে, তখনই তাদেরকে তাতে ফিরিয়ে দেয়া হবে। বলা হবেঃ দহন শাস্তি আস্বাদন কর।'),
  ('bn.bengali', 22, 23, 'নিশ্চয় যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম করে, আল্লাহ তাদেরকে দাখিল করবেন উদ্যান সমূহে, যার তলদেশ দিয়ে নির্ঝরিণীসমূহ প্রবাহিত হবে। তাদেরকে তথায় স্বর্ণ-কংকন ও মুক্তা দ্বারা অলংকৃত করা হবে এবং তথায় তাদের পোশাক হবে রেশমী।'),
  ('bn.bengali', 22, 24, 'তারা পথপ্রদর্শিত হয়েছিল সৎবাক্যের দিকে এবং পরিচালিত হয়েছিল প্রশংসিত আল্লাহর পথপানে।'),
  ('bn.bengali', 22, 25, 'যারা কুফর করে ও আল্লাহর পথে বাধা সৃষ্টি করে এবং সেই মসজিদে হারাম থেকে বাধা দেয়, যাকে আমি প্রস্তুত করেছি স্থানীয় ও বহিরাগত সকল মানুষের জন্যে সমভাবে এবং যে মসজিদে হারামে অন্যায়ভাবে কোন ধর্মদ্রোহী কাজ করার ইচছা করে, আমি তাদেরকে যন্ত্রানাদায়ক শাস্তি আস্বাদন করাব।'),
  ('bn.bengali', 22, 26, 'যখন আমি ইব্রাহীমকে বায়তুল্লাহর স্থান ঠিক করে দিয়েছিলাম যে, আমার সাথে কাউকে শরীক করো না এবং আমার গৃহকে পবিত্র রাখ তাওয়াফকারীদের জন্যে, নামাযে দন্ডায়মানদের জন্যে এবং রকু সেজদাকারীদের জন্যে।'),
  ('bn.bengali', 22, 27, 'এবং মানুষের মধ্যে হজ্বের জন্যে ঘোষণা প্রচার কর। তারা তোমার কাছে আসবে পায়ে হেঁটে এবং সর্বপ্রকার কৃশকায় উটের পিঠে সওয়ার হয়ে দূর-দূরান্ত থেকে।'),
  ('bn.bengali', 22, 28, 'যাতে তারা তাদের কল্যাণের স্থান পর্যন্ত পৌছে এবং নির্দিষ্ট দিনগুলোতে আল্লাহর নাম স্মরণ করে তাঁর দেয়া চতুস্পদ জন্তু যবেহ করার সময়। অতঃপর তোমরা তা থেকে আহার কর এবং দুঃস্থ-অভাবগ্রস্থকে আহার করাও।'),
  ('bn.bengali', 22, 29, 'এরপর তারা যেন দৈহিক ময়লা দূর করে দেয়, তাদের মানত পূর্ণ করে এবং এই সুসংরক্ষিত গৃহের তাওয়াফ করে।'),
  ('bn.bengali', 22, 30, 'এটা শ্রবণযোগ্য। আর কেউ আল্লাহর সম্মানযোগ্য বিধানাবলীর প্রতি সম্মান প্রদর্শন করলে পালনকর্তার নিকট তা তার জন্যে উত্তম। উল্লেখিত ব্যতিক্রমগুলো ছাড়া তোমাদের জন্যে চতুস্পদ জন্তু হালাল করা হয়েছে। সুতরাং তোমরা মূর্তিদের অপবিত্রতা থেকে বেঁচে থাক এবং মিথ্যা কথন থেকে দূরে সরে থাক;'),
  ('bn.bengali', 22, 31, 'আল্লাহর দিকে একনিষ্ট হয়ে, তাঁর সাথে শরীক না করে; এবং যে কেউ আল্লাহর সাথে শরীক করল; সে যেন আকাশ থেকে ছিটকে পড়ল, অতঃপর মৃতভোজী পাখী তাকে ছোঁ মেরে নিয়ে গেল অথবা বাতাস তাকে উড়িয়ে নিয়ে কোন দূরবর্তী স্থানে নিক্ষেপ করল।'),
  ('bn.bengali', 22, 32, 'এটা শ্রবণযোগ্য কেউ আল্লাহর নামযুক্ত বস্তুসমুহের প্রতি সম্মান প্রদর্শন করলে তা তো তার হৃদয়ের আল্লাহভীতি প্রসূত।'),
  ('bn.bengali', 22, 33, 'চতুস্পদ জন্তুসমূহের মধ্যে তোমাদের জন্যে নির্দিষ্টকাল পর্যন্ত উপকার রয়েছে। অতঃপর এগুলোকে পৌছাতে হবে মুক্ত গৃহ পর্যন্ত।'),
  ('bn.bengali', 22, 34, 'আমি প্রত্যেক উম্মতের জন্যে কোরবানী নির্ধারণ করেছি, যাতে তারা আল্লাহর দেয়া চতুস্পদ জন্তু যবেহ কারার সময় আল্লাহর নাম উচ্চারণ করে। অতএব তোমাদের আল্লাহ তো একমাত্র আল্লাহ সুতরাং তাঁরই আজ্ঞাধীন থাক এবং বিনয়ীগণকে সুসংবাদ দাও;'),
  ('bn.bengali', 22, 35, 'যাদের অন্তর আল্লাহর নাম স্মরণ করা হলে ভীত হয় এবং যারা তাদের বিপদাপদে ধৈর্য্যধারণ করে এবং যারা নামায কায়েম করে ও আমি যা দিয়েছি, তা থেকে ব্যয় করে।'),
  ('bn.bengali', 22, 36, 'এবং কা’বার জন্যে উৎসর্গীকৃত উটকে আমি তোমাদের জন্যে আল্লাহর অন্যতম নিদর্শন করেছি। এতে তোমাদের জন্যে মঙ্গল রয়েছে। সুতরাং সারিবদ্ধভাবে বাঁধা অবস্থায় তাদের যবেহ করার সময় তোমরা আল্লাহর নাম উচ্চারণ কর। অতঃপর যখন তারা কাত হয়ে পড়ে যায় তখন তা থেকে তোমরা আহার কর এবং আহার করাও যে কিছু যাচ্ঞা করে না তাকে এবং যে যাচ্ঞা করে তাকে। এমনিভাবে আমি এগুলোকে তোমাদের বশীভূত করে দিয়েছি, যাতে তোমরা কৃতজ্ঞতা প্রকাশ কর।'),
  ('bn.bengali', 22, 37, 'এগুলোর গোশত ও রক্ত আল্লাহর কাছে পৌঁছে না, কিন্তু পৌঁছে তাঁর কাছে তোমাদের মনের তাকওয়া। এমনিভাবে তিনি এগুলোকে তোমাদের বশ করে দিয়েছেন, যাতে তোমরা আল্লাহর মহত্ত্ব ঘোষণা কর এ কারণে যে, তিনি তোমাদের পথ প্রদর্শন করেছেন। সুতরাং সৎকর্মশীলদের সুসংবাদ শুনিয়ে দিন।'),
  ('bn.bengali', 22, 38, 'আল্লাহ মুমিনদের থেকে শত্রুদেরকে হটিয়ে দেবেন। আল্লাহ কোন বিশ্বাসঘাতক অকৃতজ্ঞকে পছন্দ করেন না।'),
  ('bn.bengali', 22, 39, 'যুদ্ধে অনুমতি দেয়া হল তাদেরকে যাদের সাথে কাফেররা যুদ্ধ করে; কারণ তাদের প্রতি অত্যাচার করা হয়েছে। আল্লাহ তাদেরকে সাহায্য করতে অবশ্যই সক্ষম।'),
  ('bn.bengali', 22, 40, 'যাদেরকে তাদের ঘর-বাড়ী থেকে অন্যায়ভাবে বহিস্কার করা হয়েছে শুধু এই অপরাধে যে, তারা বলে আমাদের পালনকর্তা আল্লাহ। আল্লাহ যদি মানবজাতির একদলকে অপর দল দ্বারা প্রতিহত না করতেন, তবে (খ্রীষ্টানদের) নির্ঝন গির্জা, এবাদত খানা, (ইহুদীদের) উপাসনালয় এবং মসজিদসমূহ বিধ্বস্ত হয়ে যেত, যেগুলাতে আল্লাহর নাম অধিক স্মরণ করা হয়। আল্লাহ নিশ্চয়ই তাদেরকে সাহায্য করবেন, যারা আল্লাহর সাহায্য করে। নিশ্চয়ই আল্লাহ পরাক্রমশালী শক্তিধর।'),
  ('bn.bengali', 22, 41, 'তারা এমন লোক যাদেরকে আমি পৃথিবীতে শক্তি-সামর্থ?2470;ান করলে তারা নামায কায়েম করবে, যাকাত দেবে এবং সৎকাজে আদেশ ও অসৎকাজে নিষেধ করবে। প্রত্যেক কর্মের পরিণাম আল্লাহর এখতিয়ারভূক্ত।'),
  ('bn.bengali', 22, 42, 'তারা যদি আপনাকে মিথ্যাবাদী বলে, তবে তাদের পূর্বে মিথ্যাবাদী বলেছে কওমে নূহ, আদ, সামুদ,'),
  ('bn.bengali', 22, 43, 'ইব্রাহীম ও লূতের সম্প্রদায়ও।'),
  ('bn.bengali', 22, 44, 'এবং মাদইয়ানের অধিবাসীরা এবং মিথ্যাবাদী বলা হয়েছিল মূসাকেও। অতঃপর আমি কাফেরদেরকে সুযোগ দিয়েছিলাম এরপর তাদেরকে পাকড়াও করেছিলাম অতএব কি ভীষণ ছিল আমাকে অস্বীকৃতির পরিণাম।'),
  ('bn.bengali', 22, 45, 'আমি কত জনপদ ধ্বংস করেছি এমতাবস্থায় যে, তারা ছিল গোনাহগার। এই সব জনপদ এখন ধ্বংসস্তুপে পরিণত হয়েছে এবং কত কূপ পরিত্যক্ত হয়েছে ও কত সুদৃঢ় প্রাসাদ ধ্বংস হয়েছে।'),
  ('bn.bengali', 22, 46, 'তারা কি এই উদ্দেশ্যে দেশ ভ্রমণ করেনি, যাতে তারা সমঝদার হৃদয় ও শ্রবণ শক্তি সম্পন্ন কর্ণের অধিকারী হতে পারে? বস্তুতঃ চক্ষু তো অন্ধ হয় না, কিন্তু বক্ষ স্থিত অন্তরই অন্ধ হয়।'),
  ('bn.bengali', 22, 47, 'তারা আপনাকে আযাব ত্বরান্বিত করতে বলে। অথচ আল্লাহ কখনও তাঁর ওয়াদা ভঙ্গ করেন না। আপনার পালনকর্তার কাছে একদিন তোমাদের গণনার এক হাজার বছরের সমান।'),
  ('bn.bengali', 22, 48, 'এবং আমি কত জনপদকে অবকাশ দিয়েছি এমতাবস্থায় যে, তারা গোনাহগার ছিল। এরপর তাদেরকে পাকড়াও করেছি এবং আমার কাছেই প্রত্যাবর্তন করতে হবে।'),
  ('bn.bengali', 22, 49, 'বলুনঃ হে লোক সকল! আমি তো তোমাদের জন্যে স্পষ্ট ভাষায় সতর্ককারী।'),
  ('bn.bengali', 22, 50, 'সুতরাং যারা বিশ্বাস স্থাপন করেছে এবং সৎকর্ম করেছে, তাদের জন্যে আছে পাপ মার্জনা এবং সম্মানজনক রুযী।'),
  ('bn.bengali', 22, 51, 'এবং যারা আমার আয়াতসমূহকে ব্যর্থ করার জন্যে চেষ্টা করে, তারাই দোযখের অধিবাসী।'),
  ('bn.bengali', 22, 52, 'আমি আপনার পূর্বে যে সমস্ত রাসূল ও নবী প্রেরণ করেছি, তারা যখনই কিছু কল্পনা করেছে, তখনই শয়তান তাদের কল্পনায় কিছু মিশ্রণ করে দিয়েছে। অতঃপর আল্লাহ দূর করে দেন শয়তান যা মিশ্রণ করে। এরপর আল্লাহ তাঁর আয়াতসমূহকে সু-প্রতিষ্ঠিত করেন এবং আল্লাহ জ্ঞানময়, প্রজ্ঞাময়।'),
  ('bn.bengali', 22, 53, 'এ কারণে যে, শয়তান যা মিশ্রণ করে, তিনি তা পরীক্ষাস্বরূপ করে দেন, তাদের জন্যে, যাদের অন্তরে রোগ আছে এবং যারা পাষাণহৃদয়। গোনাহগাররা দূরবর্তী বিরোধিতায় লিপ্ত আছে।'),
  ('bn.bengali', 22, 54, 'এবং এ কারণেও যে, যাদেরকে জ্ঞানদান করা হয়েছে; তারা যেন জানে যে এটা আপনার পালনকর্তার পক্ষ থেকে সত্য; অতঃপর তারা যেন এতে বিশ্বাস স্তাপন করে এবং তাদের অন্তর যেন এর প্রতি বিজয়ী হয়। আল্লাহই বিশ্বাস স্থাপনকারীকে সরল পথ প্রদর্শন করেন।'),
  ('bn.bengali', 22, 55, 'কাফেররা সর্বদাই সন্দেহ পোষন করবে যে পর্যন্ত না তাদের কাছে আকস্মিকভাবে কেয়ামত এসে পড়ে অথবা এসে পড়ে তাদের কাছে এমন দিবসের শাস্তি যা থেকে রক্ষার উপায় নেই।'),
  ('bn.bengali', 22, 56, 'রাজত্ব সেদিন আল্লাহরই; তিনিই তাদের বিচার করবেন। অতএব যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে তারা নেয়ামত পূর্ণ কাননে থাকবে।'),
  ('bn.bengali', 22, 57, 'এবং যারা কুফরি করে এবং আমার আয়াত সমূহকে মিথ্যা বলে তাদের জন্যে লাঞ্ছনাকর শাস্তি রয়েছে।'),
  ('bn.bengali', 22, 58, 'যারা আল্লাহর পথে গৃহ ত্যাগ করেছে, এরপর নিহত হয়েছে অথবা মরে গেছে; আল্লাহ তাদেরকে অবশ্যই উৎকৃষ্ট জীবিকা দান করবেন এবং আল্লাহ সর্বোৎকৃষ্ট রিযিক দাতা।'),
  ('bn.bengali', 22, 59, 'তাদেরকে অবশ্যই এমন এক স্থানে পৌছাবেন, যাকে তারা পছন্দ করবে এবং আল্লাহ জ্ঞানময়, সহনশীল।'),
  ('bn.bengali', 22, 60, 'এ তো শুনলে, যে ব্যক্তি নিপীড়িত হয়ে নিপীড়ন পরিমাণে প্রতিশোধ গ্রহণ করে এবং পুনরায় সে নিপীড়িত হয়, আল্লাহ অবশ্যই তাকে সাহায্য করবেন। নিশ্চয় আল্লাহ মার্জনাকারী ক্ষমাশীল।'),
  ('bn.bengali', 22, 61, 'এটা এ জন্যে যে, আল্লাহ রাত্রিকে দিনের মধ্যে এবং দিনকে রাত্রির মধ্য দাখিল করে দেন এবং আল্লাহ সবকিছু শোনেন, দেখেন।'),
  ('bn.bengali', 22, 62, 'এটা এ কারণেও যে, আল্লাহই সত্য; আর তাঁর পরিবর্তে তারা যাকে ডাকে, তা অসত্য এবং আল্লাহই সবার উচ্চে, মহান।'),
  ('bn.bengali', 22, 63, 'তুমি কি দেখ না যে, আল্লাহ আকাশ থেকে পানি বর্ষণ করেন, অতঃপর ভূপৃষ্ট সবুজ-শ্যামল হয়ে উঠে। নিশ্চয় আল্লাহ সুক্ষদর্শী, সর্ববিষয়ে খবরদার।'),
  ('bn.bengali', 22, 64, 'নভোমন্ডল ও ভুপৃষ্ঠে যা কিছু আছে, সব তাঁরই এবং আল্লাহই অভাবমুক্ত প্রশংসার অধিকারী।'),
  ('bn.bengali', 22, 65, 'তুমি কি দেখ না যে, ভূপৃষ্টে যা আছে এবং সমুদ্রে চলমান নৌকা তৎসমুদয়কে আল্লাহ নিজ আদেশে তোমাদের অধীন করে দিয়েছেন এবং তিনি আকাশ স্থির রাখেন, যাতে তাঁর আদেশ ব্যতীত ভূপৃষ্টে পতিত না হয়। নিশ্চয় আল্লাহ মানুষের প্রতি করুণাশীল, দয়াবান।'),
  ('bn.bengali', 22, 66, 'তিনিই তোমাদেরকে জীবিত করেছেন, অতঃপর তিনিই তোমাদেরকে মৃত্যুদান করবেন ও পুনরায় জীবিত করবেন। নিশ্চয় মানুষ বড় অকৃতজ্ঞ।'),
  ('bn.bengali', 22, 67, 'আমি প্রত্যেক উম্মতের জন্যে এবাদতের একটি নিয়ম-কানুন নির্ধারণ করে দিয়েছি, যা তারা পালন করে। অতএব তারা যেন এ ব্যাপারে আপনার সাথে বিতর্ক না করে। আপনি তাদেরকে পালনকর্তার দিকে আহবান করুন। নিশ্চয় আপনি সরল পথেই আছেন।'),
  ('bn.bengali', 22, 68, 'তারা যদি আপনার সাথে বিতর্ক করে, তবে বলে দিন, তোমরা যা কর, সে সর্ম্পকে আল্লাহ অধিক জ্ঞাত।'),
  ('bn.bengali', 22, 69, 'তোমরা যে বিষয়ে মতবিরোধ করছ, আল্লাহ কিয়ামতের দিন সেই বিষয়ে তোমাদের মধ্যে ফায়সালা করবেন।'),
  ('bn.bengali', 22, 70, 'তুমি কি জান না যে, আল্লাহ জানেন যা কিছু আকাশে ও ভুমন্ডলে আছে এসব কিতাবে লিখিত আছে। এটা আল্লাহর কাছে সহজ।'),
  ('bn.bengali', 22, 71, 'তারা আল্লাহর পরিবর্তে এমন কিছুর পূজা করে, যার কোন সনদ নাযিল করা হয়নি এবং সে সম্পর্কে তাদের কোন জ্ঞান নেই। বস্তুতঃ জালেমদের কোন সাহায্যকারী নেই।'),
  ('bn.bengali', 22, 72, 'যখন তাদের কাছে আমার সুস্পষ্ট আয়াতসমূহ আবৃত্তি করা হয়, তখন তুমি কাফেরদের চোখে মুখে অসন্তোষের লক্ষণ প্রত্যক্ষ করতে পারবে। যারা তাদের কাছে আমার আয়াত সমূহ পাঠ করে, তারা তাদের প্রতি মার মুখো হয়ে উঠে। বলুন, আমি কি তোমাদেরকে তদপেক্ষা মন্দ কিছুর সংবাদ দেব? তা আগুন; আল্লাহ কাফেরদেরকে এর ওয়াদা দিয়েছেন। এটা কতই না নিকৃষ্ট প্রত্যাবর্তনস্থল।'),
  ('bn.bengali', 22, 73, 'হে লোক সকল! একটি উপমা বর্ণনা করা হলো, অতএব তোমরা তা মনোযোগ দিয়ে শোন; তোমরা আল্লাহর পরিবর্তে যাদের পূজা কর, তারা কখনও একটি মাছি সৃষ্টি করতে পারবে না, যদিও তারা সকলে একত্রিত হয়। আর মাছি যদি তাদের কাছ থেকে কোন কিছু ছিনিয়ে নেয়, তবে তারা তার কাছ থেকে তা উদ্ধার করতে পারবে না, প্রার্থনাকারী ও যার কাছে প্রার্থনা করা হয়, উভয়েই শক্তিহীন।'),
  ('bn.bengali', 22, 74, 'তারা আল্লাহর যথাযোগ্য মর্যাদা বোঝেনি। নিশ্চয় আল্লাহ শক্তিধর, মহাপরাক্রমশীল।'),
  ('bn.bengali', 22, 75, 'আল্লাহ ফেরেশতা ও মানুষের মধ্য থেকে রাসূল মনোনীত করেন। আল্লাহ সর্বশ্রোতা, সর্ব দ্রষ্টা!'),
  ('bn.bengali', 22, 76, 'তিনি জানেন যা তাদের সামনে আছে এবং যা পশ্চাতে আছে এবং সবকিছু আল্লাহর দিকে প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 22, 77, 'হে মুমিনগণ! তোমরা রুকু কর, সেজদা কর, তোমাদের পালনকর্তার এবাদত কর এবং সৎকাজ সম্পাদন কর, যাতে তোমরা সফলকাম হতে পার।'),
  ('bn.bengali', 22, 78, 'তোমরা আল্লাহর জন্যে শ্রম স্বীকার কর যেভাবে শ্রম স্বীকার করা উচিত। তিনি তোমাদেরকে পছন্দ করেছেন এবং ধর্মের ব্যাপারে তোমাদের উপর কোন সংকীর্ণতা রাখেননি। তোমরা তোমাদের পিতা ইব্রাহীমের ধর্মে কায়েম থাক। তিনিই তোমাদের নাম মুসলমান রেখেছেন পূর্বেও এবং এই কোরআনেও, যাতে রসূল তোমাদের জন্যে সাক্ষ্যদাতা এবং তোমরা সাক্ষ্যদাতা হও মানবমন্ডলির জন্যে। সুতরাং তোমরা নামায কায়েম কর, যাকাত দাও এবং আল্লাহকে শক্তভাবে ধারণ কর। তিনিই তোমাদের মালিক। অতএব তিনি কত উত্তম মালিক এবং কত উত্তম সাহায্যকারী।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 22, 1, 'O mankind! Fear your Lord. Lo! the earthquake of the Hour (of Doom) is a tremendous thing.'),
  ('en.pickthall', 22, 2, 'On the day when ye behold it, every nursing mother will forget her nursling and every pregnant one will be delivered of her burden, and thou (Muhammad) wilt see mankind as drunken, yet they will not be drunken, but the Doom of Allah will be strong (upon them).'),
  ('en.pickthall', 22, 3, 'Among mankind is he who disputeth concerning Allah without knowledge, and followeth each froward devil;'),
  ('en.pickthall', 22, 4, 'For him it is decreed that whoso taketh him for friend, he verily will mislead him and will guide him to the punishment of the Flame.'),
  ('en.pickthall', 22, 5, 'O mankind! if ye are in doubt concerning the Resurrection, then lo! We have created you from dust, then from a drop of seed, then from a clot, then from a little lump of flesh shapely and shapeless, that We may make (it) clear for you. And We cause what We will to remain in the wombs for an appointed time, and afterward We bring you forth as infants, then (give you growth) that ye attain your full strength. And among you there is he who dieth (young), and among you there is he who is brought back to the most abject time of life, so that, after knowledge, he knoweth naught. And thou (Muhammad) seest the earth barren, but when We send down water thereon, it doth thrill and swell and put forth every lovely kind (of growth).'),
  ('en.pickthall', 22, 6, 'That is because Allah, He is the Truth and because He quickeneth the dead, and because He is Able to do all things;'),
  ('en.pickthall', 22, 7, 'And because the Hour will come, there is no doubt thereof; and because Allah will raise those who are in the graves.'),
  ('en.pickthall', 22, 8, 'And among mankind is he who disputeth concerning Allah without knowledge or guidance or a scripture giving light,'),
  ('en.pickthall', 22, 9, 'Turning away in pride to beguile (men) from the way of Allah. For him in this world is ignominy, and on the Day of Resurrection We make him taste the doom of burning.'),
  ('en.pickthall', 22, 10, '(And unto him it will be said): This is for that which thy two hands have sent before, and because Allah is no oppressor of His slaves.'),
  ('en.pickthall', 22, 11, 'And among mankind is he who worshippeth Allah upon a narrow marge so that if good befalleth him he is content therewith, but if a trial befalleth him, he falleth away utterly. He loseth both the world and the Hereafter. That is the sheer loss.'),
  ('en.pickthall', 22, 12, 'He calleth, beside Allah, unto that which hurteth him not nor benefiteth him. That is the far error.'),
  ('en.pickthall', 22, 13, 'He calleth unto him whose harm is nearer than his benefit; verily an evil patron and verily an evil friend!'),
  ('en.pickthall', 22, 14, 'Lo! Allah causeth those who believe and do good works to enter Gardens underneath which rivers flow. Lo! Allah doth what He intendeth.'),
  ('en.pickthall', 22, 15, 'Whoso is wont to think (through envy) that Allah will not give him (Muhammad) victory in the world and the Hereafter (and is enraged at the thought of his victory), let him stretch a rope up to the roof (of his dwelling), and let him hang himself. Then let him see whether his strategy dispelleth that whereat he rageth!.'),
  ('en.pickthall', 22, 16, 'Thus We reveal it as plain revelations, and verily Allah guideth whom He will.'),
  ('en.pickthall', 22, 17, 'Lo! those who believe (this revelation), and those who are Jews, and the Sabaeans and the Christians and the Magians and the idolaters - Lo! Allah will decide between them on the Day of Resurrection. Lo! Allah is Witness over all things.'),
  ('en.pickthall', 22, 18, 'Hast thou not seen that unto Allah payeth adoration whosoever is in the heavens and whosoever is in the earth, and the sun, and the moon, and the stars, and the hills, and the trees, and the beasts, and many of mankind, while there are many unto whom the doom is justly due. He whom Allah scorneth, there is none to give him honour. Lo! Allah doeth what He will.'),
  ('en.pickthall', 22, 19, 'These twain (the believers and the disbelievers) are two opponents who contend concerning their Lord. But as for those who disbelieve, garments of fire will be cut out for them; boiling fluid will be poured down on their heads,'),
  ('en.pickthall', 22, 20, 'Whereby that which is in their bellies, and their skins too, will be melted;'),
  ('en.pickthall', 22, 21, 'And for them are hooked rods of iron.'),
  ('en.pickthall', 22, 22, 'Whenever, in their anguish, they would go forth from thence they are driven back therein and (it is said unto them): Taste the doom of burning.'),
  ('en.pickthall', 22, 23, 'Lo! Allah will cause those who believe and do good works to enter Gardens underneath which rivers flow, wherein they will be allowed armlets of gold, and pearls, and their raiment therein will be silk.'),
  ('en.pickthall', 22, 24, 'They are guided unto gentle speech; they are guided unto the path of the Glorious One.'),
  ('en.pickthall', 22, 25, 'Lo! those who disbelieve and bar (men) from the way of Allah and from the Inviolable Place of Worship, which We have appointed for mankind together, the dweller therein and the nomad: whosoever seeketh wrongful partiality therein, him We shall cause to taste a painful doom.'),
  ('en.pickthall', 22, 26, 'And (remember) when We prepared for Abraham the place of the (holy) House, saying: Ascribe thou no thing as partner unto Me, and purify My House for those who make the round (thereof) and those who stand and those who bow and make prostration.'),
  ('en.pickthall', 22, 27, 'And proclaim unto mankind the pilgrimage. They will come unto thee on foot and on every lean camel; they will come from every deep ravine,'),
  ('en.pickthall', 22, 28, 'That they may witness things that are of benefit to them, and mention the name of Allah on appointed days over the beast of cattle that He hath bestowed upon them. Then eat thereof and feed therewith the poor unfortunate.'),
  ('en.pickthall', 22, 29, 'Then let them make an end of their unkemptness and pay their vows and go around the ancient House.'),
  ('en.pickthall', 22, 30, 'That (is the command). And whoso magnifieth the sacred things of Allah, it will be well for him in the sight of his Lord. The cattle are lawful unto you save that which hath been told you. So shun the filth of idols, and shun lying speech,'),
  ('en.pickthall', 22, 31, 'Turning unto Allah (only), not ascribing partners unto Him; for whoso ascribeth partners unto Allah, it is as if he had fallen from the sky and the birds had snatched him or the wind had blown him to a far-off place.'),
  ('en.pickthall', 22, 32, 'That (is the command). And whoso magnifieth the offerings consecrated to Allah, it surely is from devotion of the hearts,'),
  ('en.pickthall', 22, 33, 'Therein are benefits for you for an appointed term; and afterward they are brought for sacrifice unto the ancient House.'),
  ('en.pickthall', 22, 34, 'And for every nation have We appointed a ritual, that they may mention the name of Allah over the beast of cattle that He hath given them for food; and your god is One God, therefor surrender unto Him. And give good tidings (O Muhammad) to the humble,'),
  ('en.pickthall', 22, 35, 'Whose hearts fear when Allah is mentioned, and the patient of whatever may befall them, and those who establish worship and who spend of that We have bestowed on them.'),
  ('en.pickthall', 22, 36, 'And the camels! We have appointed them among the ceremonies of Allah. Therein ye have much good. So mention the name of Allah over them when they are drawn up in lines. Then when their flanks fall (dead), eat thereof and feed the beggar and the suppliant. Thus have We made them subject unto you, that haply ye may give thanks.'),
  ('en.pickthall', 22, 37, 'Their flesh and their food reach not Allah, but the devotion from you reacheth Him. Thus have We made them subject unto you that ye may magnify Allah that He hath guided you. And give good tidings (O Muhammad) to the good.'),
  ('en.pickthall', 22, 38, 'Lo! Allah defendeth those who are true. Lo! Allah loveth not each treacherous ingrate.'),
  ('en.pickthall', 22, 39, 'Sanction is given unto those who fight because they have been wronged; and Allah is indeed Able to give them victory;'),
  ('en.pickthall', 22, 40, 'Those who have been driven from their homes unjustly only because they said: Our Lord is Allah - For had it not been for Allah\'s repelling some men by means of others, cloisters and churches and oratories and mosques, wherein the name of Allah is oft mentioned, would assuredly have been pulled down. Verily Allah helpeth one who helpeth Him. Lo! Allah is Strong, Almighty -'),
  ('en.pickthall', 22, 41, 'Those who, if We give them power in the land, establish worship and pay the poor-due and enjoin kindness and forbid iniquity. And Allah\'s is the sequel of events.'),
  ('en.pickthall', 22, 42, 'If they deny thee (Muhammad), even so the folk of Noah, and (the tribes of) A\'ad and Thamud, before thee, denied (Our messengers);'),
  ('en.pickthall', 22, 43, 'And the folk of Abraham and the folk of Lot;'),
  ('en.pickthall', 22, 44, '(And) the dwellers in Midian. And Moses was denied; but I indulged the disbelievers a long while, then I seized them, and how (terrible) was My abhorrence!'),
  ('en.pickthall', 22, 45, 'How many a township have We destroyed while it was sinful, so that it lieth (to this day) in ruins, and (how many) a deserted well and lofty tower!'),
  ('en.pickthall', 22, 46, 'Have they not travelled in the land, and have they hearts wherewith to feel and ears wherewith to hear? For indeed it is not the eyes that grow blind, but it is the hearts, which are within the bosoms, that grow blind.'),
  ('en.pickthall', 22, 47, 'And they will bid thee hasten on the Doom, and Allah faileth not His promise, but lo! a Day with Allah is as a thousand years of what ye reckon.'),
  ('en.pickthall', 22, 48, 'And how many a township did I suffer long though it was sinful! Then I grasped it. Unto Me is the return.'),
  ('en.pickthall', 22, 49, 'Say: O mankind! I am only a plain warner unto you.'),
  ('en.pickthall', 22, 50, 'Those who believe and do good works, for them is pardon and a rich provision;'),
  ('en.pickthall', 22, 51, 'While those who strive to thwart Our revelations, such are rightful owners of the Fire.'),
  ('en.pickthall', 22, 52, 'Never sent We a messenger or a prophet before thee but when He recited (the message) Satan proposed (opposition) in respect of that which he recited thereof. But Allah abolisheth that which Satan proposeth. Then Allah establisheth His revelations. Allah is Knower, Wise;'),
  ('en.pickthall', 22, 53, 'That He may make that which the devil proposeth a temptation for those in whose hearts is a disease, and those whose hearts are hardened - Lo! the evil-doers are in open schism -'),
  ('en.pickthall', 22, 54, 'And that those who have been given knowledge may know that it is the truth from thy Lord, so that they may believe therein and their hearts may submit humbly unto Him. Lo! Allah verily is guiding those who believe unto a right path.'),
  ('en.pickthall', 22, 55, 'And those who disbelieve will not cease to be in doubt thereof until the Hour come upon them unawares, or there come unto them the doom of a disastrous day.'),
  ('en.pickthall', 22, 56, 'The Sovereignty on that day will be Allah\'s, He will judge between them. Then those who believed and did good works will be in Gardens of Delight,'),
  ('en.pickthall', 22, 57, 'While those who disbelieved and denied Our revelations, for them will be a shameful doom.'),
  ('en.pickthall', 22, 58, 'Those who fled their homes for the cause of Allah and then were slain or died, Allah verily will provide for them a good provision. Lo! Allah, He verily is Best of all who make provision.'),
  ('en.pickthall', 22, 59, 'Assuredly He will cause them to enter by an entry that they will love. Lo! Allah verily is Knower, Indulgent.'),
  ('en.pickthall', 22, 60, 'That (is so). And whoso hath retaliated with the like of that which he was made to suffer and then hath (again) been wronged, Allah will succour him. Lo! Allah verily is Mild, Forgiving.'),
  ('en.pickthall', 22, 61, 'That is because Allah maketh the night to pass into the day and maketh the day to pass into the night, and because Allah is Hearer, Seer.'),
  ('en.pickthall', 22, 62, 'That is because Allah, He is the True, and that whereon they call instead of Him, it is the false, and because Allah, He is the High, the Great.'),
  ('en.pickthall', 22, 63, 'Seest thou not how Allah sendeth down water from the sky and then the earth becometh green upon the morrow? Lo! Allah is Subtile, Aware.'),
  ('en.pickthall', 22, 64, 'Unto Him belongeth all that is in the heavens and all that is in the earth. Lo! Allah, He verily is the Absolute, the Owner of Praise.'),
  ('en.pickthall', 22, 65, 'Hast thou not seen how Allah hath made all that is in the earth subservient unto you? And the ship runneth upon the sea by His command, and He holdeth back the heaven from falling on the earth unless by His leave. Lo! Allah is, for mankind, Full of Pity, Merciful.'),
  ('en.pickthall', 22, 66, 'And He it is Who gave you life, then He will cause you to die, and then will give you life (again). Lo! man is verily an ingrate.'),
  ('en.pickthall', 22, 67, 'Unto each nation have We given sacred rites which they are to perform; so let them not dispute with thee of the matter, but summon thou unto thy Lord. Lo! thou indeed followest right guidance.'),
  ('en.pickthall', 22, 68, 'And if they wrangle with thee, say: Allah is Best Aware of what ye do.'),
  ('en.pickthall', 22, 69, 'Allah will judge between you on the Day of Resurrection concerning that wherein ye used to differ.'),
  ('en.pickthall', 22, 70, 'Hast thou not known that Allah knoweth all that is in the heaven and the earth? Lo! it is in a record. Lo! that is easy for Allah.'),
  ('en.pickthall', 22, 71, 'And they worship instead of Allah that for which He hath sent down no warrant, and that whereof they have no knowledge. For evil-doers there is no helper.'),
  ('en.pickthall', 22, 72, 'And when Our revelations are recited unto them, thou knowest the denial in the faces of those who disbelieve; they all but attack those who recite Our revelations unto them. Say: Shall I proclaim unto you worse than that? The Fire! Allah hath promised it for those who disbelieve. A hapless journey\'s end!'),
  ('en.pickthall', 22, 73, 'O mankind! A similitude is coined, so pay ye heed to it: Lo! those on whom ye call beside Allah will never create a fly though they combine together for the purpose. And if the fly took something from them, they could not rescue it from it. So weak are (both) the seeker and the sought!'),
  ('en.pickthall', 22, 74, 'They measure not Allah His rightful measure. Lo! Allah is Strong, Almighty.'),
  ('en.pickthall', 22, 75, 'Allah chooseth from the angels messengers, and (also) from mankind. Lo! Allah is Hearer, Seer.'),
  ('en.pickthall', 22, 76, 'He knoweth all that is before them and all that is behind them, and unto Allah all things are returned. $$A'),
  ('en.pickthall', 22, 77, 'O ye who believe! Bow down and prostrate yourselves, and worship your Lord, and do good, that haply ye may prosper.'),
  ('en.pickthall', 22, 78, 'And strive for Allah with the endeavour which is His right. He hath chosen you and hath not laid upon you in religion any hardship; the faith of your father Abraham (is yours). He hath named you Muslims of old time and in this (Scripture), that the messenger may be a witness against you, and that ye may be witnesses against mankind. So establish worship, pay the poor-due, and hold fast to Allah. He is your Protecting friend. A blessed Patron and a blessed Helper!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 22, 1, 'O mankind! fear your Lord! for the convulsion of the Hour (of Judgment) will be a thing terrible!'),
  ('en.yusufali', 22, 2, 'The Day ye shall see it, every mother giving suck shall forget her suckling-babe, and every pregnant female shall drop her load (unformed): thou shalt see mankind as in a drunken riot, yet not drunk: but dreadful will be the Wrath of Allah.'),
  ('en.yusufali', 22, 3, 'And yet among men there are such as dispute about Allah, without knowledge, and follow every evil one obstinate in rebellion!'),
  ('en.yusufali', 22, 4, 'About the (Evil One) it is decreed that whoever turns to him for friendship, him will he lead astray, and he will guide him to the Penalty of the Fire.'),
  ('en.yusufali', 22, 5, 'O mankind! if ye have a doubt about the Resurrection, (consider) that We created you out of dust, then out of sperm, then out of a leech-like clot, then out of a morsel of flesh, partly formed and partly unformed, in order that We may manifest (our power) to you; and We cause whom We will to rest in the wombs for an appointed term, then do We bring you out as babes, then (foster you) that ye may reach your age of full strength; and some of you are called to die, and some are sent back to the feeblest old age, so that they know nothing after having known (much), and (further), thou seest the earth barren and lifeless, but when We pour down rain on it, it is stirred (to life), it swells, and it puts forth every kind of beautiful growth (in pairs).'),
  ('en.yusufali', 22, 6, 'This is so, because Allah is the Reality: it is He Who gives life to the dead, and it is He Who has power over all things.'),
  ('en.yusufali', 22, 7, 'And verily the Hour will come: there can be no doubt about it, or about (the fact) that Allah will raise up all who are in the graves.'),
  ('en.yusufali', 22, 8, 'Yet there is among men such a one as disputes about Allah, without Knowledge, without Guidance, and without a Book of Enlightenment,-'),
  ('en.yusufali', 22, 9, '(Disdainfully) bending his side, in order to lead (men) astray from the Path of Allah: for him there is disgrace in this life, and on the Day of Judgment We shall make him taste the Penalty of burning (Fire).'),
  ('en.yusufali', 22, 10, '(It will be said): "This is because of the deeds which thy hands sent forth, for verily Allah is not unjust to His servants.'),
  ('en.yusufali', 22, 11, 'There are among men some who serve Allah, as it were, on the verge: if good befalls them, they are, therewith, well content; but if a trial comes to them, they turn on their faces: they lose both this world and the Hereafter: that is loss for all to see!'),
  ('en.yusufali', 22, 12, 'They call on such deities, besides Allah, as can neither hurt nor profit them: that is straying far indeed (from the Way)!'),
  ('en.yusufali', 22, 13, '(Perhaps) they call on one whose hurt is nearer than his profit: evil, indeed, is the patron, and evil the companion (or help)!'),
  ('en.yusufali', 22, 14, 'Verily Allah will admit those who believe and work righteous deeds, to Gardens, beneath which rivers flow: for Allah carries out all that He plans.'),
  ('en.yusufali', 22, 15, 'If any think that Allah will not help him (His Messenger) in this world and the Hereafter, let him stretch out a rope to the ceiling and cut (himself) off: then let him see whether his plan will remove that which enrages (him)!'),
  ('en.yusufali', 22, 16, 'Thus have We sent down Clear Signs; and verily Allah doth guide whom He will!'),
  ('en.yusufali', 22, 17, 'Those who believe (in the Qur\'an), those who follow the Jewish (scriptures), and the Sabians, Christians, Magians, and Polytheists,- Allah will judge between them on the Day of Judgment: for Allah is witness of all things.'),
  ('en.yusufali', 22, 18, 'Seest thou not that to Allah bow down in worship all things that are in the heavens and on earth,- the sun, the moon, the stars; the hills, the trees, the animals; and a great number among mankind? But a great number are (also) such as are fit for Punishment: and such as Allah shall disgrace,- None can raise to honour: for Allah carries out all that He wills.'),
  ('en.yusufali', 22, 19, 'These two antagonists dispute with each other about their Lord: But those who deny (their Lord),- for them will be cut out a garment of Fire: over their heads will be poured out boiling water.'),
  ('en.yusufali', 22, 20, 'With it will be scalded what is within their bodies, as well as (their) skins.'),
  ('en.yusufali', 22, 21, 'In addition there will be maces of iron (to punish) them.'),
  ('en.yusufali', 22, 22, 'Every time they wish to get away therefrom, from anguish, they will be forced back therein, and (it will be said), "Taste ye the Penalty of Burning!"'),
  ('en.yusufali', 22, 23, 'Allah will admit those who believe and work righteous deeds, to Gardens beneath which rivers flow: they shall be adorned therein with bracelets of gold and pearls; and their garments there will be of silk.'),
  ('en.yusufali', 22, 24, 'For they have been guided (in this life) to the purest of speeches; they have been guided to the Path of Him Who is Worthy of (all) Praise.'),
  ('en.yusufali', 22, 25, 'As to those who have rejected (Allah), and would keep back (men) from the Way of Allah, and from the Sacred Mosque, which We have made (open) to (all) men - equal is the dweller there and the visitor from the country - and any whose purpose therein is profanity or wrong-doing - them will We cause to taste of a most Grievous Penalty.'),
  ('en.yusufali', 22, 26, 'Behold! We gave the site, to Abraham, of the (Sacred) House, (saying): "Associate not anything (in worship) with Me; and sanctify My House for those who compass it round, or stand up, or bow, or prostrate themselves (therein in prayer).'),
  ('en.yusufali', 22, 27, '"And proclaim the Pilgrimage among men: they will come to thee on foot and (mounted) on every kind of camel, lean on account of journeys through deep and distant mountain highways;'),
  ('en.yusufali', 22, 28, '"That they may witness the benefits (provided) for them, and celebrate the name of Allah, through the Days appointed, over the cattle which He has provided for them (for sacrifice): then eat ye thereof and feed the distressed ones in want.'),
  ('en.yusufali', 22, 29, '"Then let them complete the rites prescribed for them, perform their vows, and (again) circumambulate the Ancient House."'),
  ('en.yusufali', 22, 30, 'Such (is the Pilgrimage): whoever honours the sacred rites of Allah, for him it is good in the Sight of his Lord. Lawful to you (for food in Pilgrimage) are cattle, except those mentioned to you (as exception): but shun the abomination of idols, and shun the word that is false,-'),
  ('en.yusufali', 22, 31, 'Being true in faith to Allah, and never assigning partners to Him: if anyone assigns partners to Allah, is as if he had fallen from heaven and been snatched up by birds, or the wind had swooped (like a bird on its prey) and thrown him into a far-distant place.'),
  ('en.yusufali', 22, 32, 'Such (is his state): and whoever holds in honour the symbols of Allah, (in the sacrifice of animals), such (honour) should come truly from piety of heart.'),
  ('en.yusufali', 22, 33, 'In them ye have benefits for a term appointed: in the end their place of sacrifice is near the Ancient House.'),
  ('en.yusufali', 22, 34, 'To every people did We appoint rites (of sacrifice), that they might celebrate the name of Allah over the sustenance He gave them from animals (fit for food). But your god is One God: submit then your wills to Him (in Islam): and give thou the good news to those who humble themselves,-'),
  ('en.yusufali', 22, 35, 'To those whose hearts when Allah is mentioned, are filled with fear, who show patient perseverance over their afflictions, keep up regular prayer, and spend (in charity) out of what We have bestowed upon them.'),
  ('en.yusufali', 22, 36, 'The sacrificial camels we have made for you as among the symbols from Allah: in them is (much) good for you: then pronounce the name of Allah over them as they line up (for sacrifice): when they are down on their sides (after slaughter), eat ye thereof, and feed such as (beg not but) live in contentment, and such as beg with due humility: thus have We made animals subject to you, that ye may be grateful.'),
  ('en.yusufali', 22, 37, 'It is not their meat nor their blood, that reaches Allah: it is your piety that reaches Him: He has thus made them subject to you, that ye may glorify Allah for His Guidance to you and proclaim the good news to all who do right.'),
  ('en.yusufali', 22, 38, 'Verily Allah will defend (from ill) those who believe: verily, Allah loveth not any that is a traitor to faith, or show ingratitude.'),
  ('en.yusufali', 22, 39, 'To those against whom war is made, permission is given (to fight), because they are wronged;- and verily, Allah is most powerful for their aid;-'),
  ('en.yusufali', 22, 40, '(They are) those who have been expelled from their homes in defiance of right,- (for no cause) except that they say, "our Lord is Allah". Did not Allah check one set of people by means of another, there would surely have been pulled down monasteries, churches, synagogues, and mosques, in which the name of Allah is commemorated in abundant measure. Allah will certainly aid those who aid his (cause);- for verily Allah is full of Strength, Exalted in Might, (able to enforce His Will).'),
  ('en.yusufali', 22, 41, '(They are) those who, if We establish them in the land, establish regular prayer and give regular charity, enjoin the right and forbid wrong: with Allah rests the end (and decision) of (all) affairs.'),
  ('en.yusufali', 22, 42, 'If they treat thy (mission) as false, so did the peoples before them (with their prophets),- the People of Noah, and \'Ad and Thamud;'),
  ('en.yusufali', 22, 43, 'Those of Abraham and Lut;'),
  ('en.yusufali', 22, 44, 'And the Companions of the Madyan People; and Moses was rejected (in the same way). But I granted respite to the Unbelievers, and (only) after that did I punish them: but how (terrible) was my rejection (of them)!'),
  ('en.yusufali', 22, 45, 'How many populations have We destroyed, which were given to wrong-doing? They tumbled down on their roofs. And how many wells are lying idle and neglected, and castles lofty and well-built?'),
  ('en.yusufali', 22, 46, 'Do they not travel through the land, so that their hearts (and minds) may thus learn wisdom and their ears may thus learn to hear? Truly it is not their eyes that are blind, but their hearts which are in their breasts.'),
  ('en.yusufali', 22, 47, 'Yet they ask thee to hasten on the Punishment! But Allah will not fail in His Promise. Verily a Day in the sight of thy Lord is like a thousand years of your reckoning.'),
  ('en.yusufali', 22, 48, 'And to how many populations did I give respite, which were given to wrong-doing? in the end I punished them. To me is the destination (of all).'),
  ('en.yusufali', 22, 49, 'Say: "O men! I am (sent) to you only to give a Clear Warning:'),
  ('en.yusufali', 22, 50, '"Those who believe and work righteousness, for them is forgiveness and a sustenance most generous.'),
  ('en.yusufali', 22, 51, '"But those who strive against Our Signs, to frustrate them,- they will be Companions of the Fire."'),
  ('en.yusufali', 22, 52, 'Never did We send a messenger or a prophet before thee, but, when he framed a desire, Satan threw some (vanity) into his desire: but Allah will cancel anything (vain) that Satan throws in, and Allah will confirm (and establish) His Signs: for Allah is full of Knowledge and Wisdom:'),
  ('en.yusufali', 22, 53, 'That He may make the suggestions thrown in by Satan, but a trial for those in whose hearts is a disease and who are hardened of heart: verily the wrong-doers are in a schism far (from the Truth):'),
  ('en.yusufali', 22, 54, 'And that those on whom knowledge has been bestowed may learn that the (Qur\'an) is the Truth from thy Lord, and that they may believe therein, and their hearts may be made humbly (open) to it: for verily Allah is the Guide of those who believe, to the Straight Way.'),
  ('en.yusufali', 22, 55, 'Those who reject Faith will not cease to be in doubt concerning (Revelation) until the Hour (of Judgment) comes suddenly upon them, or there comes to them the Penalty of a Day of Disaster.'),
  ('en.yusufali', 22, 56, 'On that Day of Dominion will be that of Allah: He will judge between them: so those who believe and work righteous deeds will be in Gardens of Delight.'),
  ('en.yusufali', 22, 57, 'And for those who reject Faith and deny our Signs, there will be a humiliating Punishment.'),
  ('en.yusufali', 22, 58, 'Those who leave their homes in the cause of Allah, and are then slain or die,- On them will Allah bestow verily a goodly Provision: Truly Allah is He Who bestows the best provision.'),
  ('en.yusufali', 22, 59, 'Verily He will admit them to a place with which they shall be well pleased: for Allah is All-Knowing, Most Forbearing.'),
  ('en.yusufali', 22, 60, 'That (is so). And if one has retaliated to no greater extent than the injury he received, and is again set upon inordinately, Allah will help him: for Allah is One that blots out (sins) and forgives (again and again).'),
  ('en.yusufali', 22, 61, 'That is because Allah merges night into day, and He merges day into night, and verily it is Allah Who hears and sees (all things).'),
  ('en.yusufali', 22, 62, 'That is because Allah - He is the Reality; and those besides Him whom they invoke,- they are but vain Falsehood: verily Allah is He, Most High, Most Great.'),
  ('en.yusufali', 22, 63, 'Seest thou not that Allah sends down rain from the sky, and forthwith the earth becomes clothed with green? for Allah is He Who understands the finest mysteries, and is well-acquainted (with them).'),
  ('en.yusufali', 22, 64, 'To Him belongs all that is in the heavens and on earth: for verily Allah,- He is free of all wants, Worthy of all Praise.'),
  ('en.yusufali', 22, 65, 'Seest thou not that Allah has made subject to you (men) all that is on the earth, and the ships that sail through the sea by His Command? He withholds the sky (rain) from failing on the earth except by His leave: for Allah is Most Kind and Most Merciful to man.'),
  ('en.yusufali', 22, 66, 'It is He Who gave you life, will cause you to die, and will again give you life: Truly man is a most ungrateful creature!'),
  ('en.yusufali', 22, 67, 'To every People have We appointed rites and ceremonies which they must follow: let them not then dispute with thee on the matter, but do thou invite (them) to thy Lord: for thou art assuredly on the Right Way.'),
  ('en.yusufali', 22, 68, 'If they do wrangle with thee, say, "Allah knows best what it is ye are doing."'),
  ('en.yusufali', 22, 69, '"Allah will judge between you on the Day of Judgment concerning the matters in which ye differ."'),
  ('en.yusufali', 22, 70, 'Knowest thou not that Allah knows all that is in heaven and on earth? Indeed it is all in a Record, and that is easy for Allah.'),
  ('en.yusufali', 22, 71, 'Yet they worship, besides Allah, things for which no authority has been sent down to them, and of which they have (really) no knowledge: for those that do wrong there is no helper.'),
  ('en.yusufali', 22, 72, 'When Our Clear Signs are rehearsed to them, thou wilt notice a denial on the faces of the Unbelievers! they nearly attack with violence those who rehearse Our Signs to them. Say, "Shall I tell you of something (far) worse than these Signs? It is the Fire (of Hell)! Allah has promised it to the Unbelievers! and evil is that destination!"'),
  ('en.yusufali', 22, 73, 'O men! Here is a parable set forth! listen to it! Those on whom, besides Allah, ye call, cannot create (even) a fly, if they all met together for the purpose! and if the fly should snatch away anything from them, they would have no power to release it from the fly. Feeble are those who petition and those whom they petition!'),
  ('en.yusufali', 22, 74, 'No just estimate have they made of Allah: for Allah is He Who is strong and able to Carry out His Will.'),
  ('en.yusufali', 22, 75, 'Allah chooses messengers from angels and from men for Allah is He Who hears and sees (all things).'),
  ('en.yusufali', 22, 76, 'He knows what is before them and what is behind them: and to Allah go back all questions (for decision).'),
  ('en.yusufali', 22, 77, 'O ye who believe! bow down, prostrate yourselves, and adore your Lord; and do good; that ye may prosper.'),
  ('en.yusufali', 22, 78, 'And strive in His cause as ye ought to strive, (with sincerity and under discipline). He has chosen you, and has imposed no difficulties on you in religion; it is the cult of your father Abraham. It is He Who has named you Muslims, both before and in this (Revelation); that the Messenger may be a witness for you, and ye be witnesses for mankind! So establish regular Prayer, give regular Charity, and hold fast to Allah! He is your Protector - the Best to protect and the Best to help!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 22, 1, 'Yaaa ayyuhan naasuttaqoo Rabbakum; inna zalzalatas Saa\'ati shai\'un \'azeem'),
  ('en.transliteration', 22, 2, 'Yawma tarawnahaa tazhalu kullu murdi\'atin \'ammaaa arda\'at wa tada\'u kullu zaati hamlin hamlahaa wa tarannaasa sukaaraa wa maa hum bisukaaraa wa lakinaa \'azaabal laahi shadeed'),
  ('en.transliteration', 22, 3, 'Wa minan naasi mai yujaadilu fil laahi bighairi \'ilminw wa yattabi\'u kullaa shaitaanim mareed'),
  ('en.transliteration', 22, 4, 'Kutiba \'alaihi annahoo man tawallaahu fa annahoo yudil lauhoo wa yahdeehi ilaa \'azaabis sa\'eer'),
  ('en.transliteration', 22, 5, 'Yaaa ayyuhan naasu in kuntum fee raibim minal ba\'si fa innaa khalaqnaakum min turaabin summa min nutfatin summaa min \'alaqatin summa mim mud ghatim mukhal laqatinw wa ghairi mukhalla qatil linubaiyina lakum; wa nuqirru fil arhaami maa nashaaa\'u ilaaa ajalim musam man summa nukhrijukum tiflan summa litablughooo ashud dakum wa minkum mai yutawaffa wa minkum mai yuraddu ilaaa arzalil \'umuri likailaa ya\'lama mim ba\'di \'ilmin shai\'aa; wa taral arda haamidatan fa izaaa anzalnaa \'alaihal maaa\'ah tazzat wa rabat wa ambatat min kulli zawjim baheej'),
  ('en.transliteration', 22, 6, 'Zaalika bi annal laaha Huwal haqqu wa annahoo yuhyil mawtaa wa annahoo \'alaakulli shai\'in Qadeer'),
  ('en.transliteration', 22, 7, 'Wa annas Saa\'ata aatiya tul laa raiba feeha wa annal laaha yab\'asuman fil quboor'),
  ('en.transliteration', 22, 8, 'Wa minan naasi mai yujaadilu fil laahi bighairi \'ilminw wa laa hudanw wa laa Kitaabim Muneer'),
  ('en.transliteration', 22, 9, 'Saaniya \'itfihee liyudilla \'an sabeelil laahi lahoo fiddun yaa khizyunw wa nuzeequhoo Yawmal Qiyaamati \'azaabal lhareeq'),
  ('en.transliteration', 22, 10, 'Zaalika bimaa qaddamat yadaaka wa annal laaha laisa bizallaamil lil\'abeed'),
  ('en.transliteration', 22, 11, 'Wa minan naasi mai ya\'budul laaha \'alaa harfin fa in asaabahoo khairunit maanna bihee wa in asaabat hu fitnatunin qalaba \'alaa wajhihee khasirad dunyaa wal aakhirah; zaalika huwal khusraanul mubeen'),
  ('en.transliteration', 22, 12, 'Yad\'oo min doonil laahi maa laa yadurruhoo wa maa laa yanfa\'uh\' zaalika huwad dalaalul ba\'ed'),
  ('en.transliteration', 22, 13, 'Yad\'oo laman darruhooo aqrabu min naf\'ih; labi\'salmawlaa wa labi\'sal \'asheer'),
  ('en.transliteration', 22, 14, 'Innal laaha yudkhilul laeena aamanoo wa \'amilus saalihaati jannaatin tajree min tahtihal anhaar; innal laaha yaf\'alu maa yureed'),
  ('en.transliteration', 22, 15, 'Man kaana yazunnu allai yansurahul laahu fid dunyaa wal aakhirati fal yamdud bisababin ilas samaaa\'i summal yaqta\' falyanzur hal yuzhibanna kaiduhoo maa yagheez'),
  ('en.transliteration', 22, 16, 'Wa kazaalika anzalnaahu aayaatim baiyinaatinw wa annal laaha yahdee mai yureed'),
  ('en.transliteration', 22, 17, 'Innal lazeena aamanoo wallazeena haadoo was saabi\'eena wan nasaaraa wal Majoosa wallazeena ashrakooo innal laaha yafsilu bainahum yawmal qiyaamah; innal laaha \'alaa kulli shai\'in shaheed'),
  ('en.transliteration', 22, 18, 'Alam tara annal laaha yasjudu lahoo man fis samaawaati wa man fil ardi wash shamsu walqamaru wan nu joomu wal jibaalu wash shajaru wad dawaaabbu wa kaseerum minan naasi wa kaseerun haqqa \'alaihil \'azaab; wa mai yuhinil laahu famaa lahoo mim mukrim; innallaaha yaf\'alu maa yashaaa'),
  ('en.transliteration', 22, 19, 'Haazaani khasmaanikh tasamoo fee Rabbihim fal lazeena kafaroo qutti\'at lahum siyaabum min naar; yusabbu min fawqi ru\'oosihimul hameem'),
  ('en.transliteration', 22, 20, 'Yusharu bihee maa fee butoonihim waljulood'),
  ('en.transliteration', 22, 21, 'Wa lahum maqaami\'u min hadeed'),
  ('en.transliteration', 22, 22, 'Kullamaa araadooo any yakhrujoo minhaa min ghammin u\'eedoo feeha wa zooqoo \'azaabal hareeq'),
  ('en.transliteration', 22, 23, 'Innal laaha yudkhilul lazeena aamanoo wa \'amilus saalihaati jannaatin tajree min tahtihal anhaaru yuhallawna feehaa min asaawira min zahabinw wa lu\'lu\'aa; wa libaasuhum feehaa hareer'),
  ('en.transliteration', 22, 24, 'Wa hudooo ilat taiyibi minal qawli wa hudooo ilaaa siraatil hameed'),
  ('en.transliteration', 22, 25, 'Innal lazeena kafaroo wa yasuddoona \'an sabeelil laahi wal Masjidil Haraamil lazee ja\'alnaahu linnaasi sawaaa\'anil \'aakifu feehi walbaad; wa mai yurid feehi bi ilhaadim bizulmin nuziqhu min \'azaabin aleem'),
  ('en.transliteration', 22, 26, 'Wa iz bawwaanaa li Ibraaheema makaanal Baiti allaa tushrik bee shai\'anw wa tahhir Baitiya litaaa\'ifeena walqaaa\' imeena warrukka \'is sujood'),
  ('en.transliteration', 22, 27, 'Wa azzin fin naasi bil Hajji yaatooka rijaalanw wa \'alaa kulli daamiriny yaateena min kulli fajjin \'ameeq'),
  ('en.transliteration', 22, 28, 'Li yashhadoo manaafi\'a lahum wa yazkurus mal laahi feee ayyaamimma\'loomaatin \'alaa maa razaqahum mim baheematil an\'aami fakuloo minhaa wa at\'imul baaa\'isal faqeer'),
  ('en.transliteration', 22, 29, 'Summal yaqdoo tafasahum wal yoofoo nuzoorahum wal yattawwafoo bil Baitil \'Ateeq'),
  ('en.transliteration', 22, 30, 'Zaalika wa mai yu\'azzim hurumaatil laahi fahuwa khairul lahoo \'inda Rabbih; wa uhillat lakumul an\'aamu illaa maa yutlaa \'alaikum fajtanibur rijsa minal awsaani wajtaniboo qawlaz zoor'),
  ('en.transliteration', 22, 31, 'Hunafaaa\'a lillaahi ghaira mushrikeena bih; wa mai yushrik billaahi faka annamaa kharra minas samaaa\'i fatakh tafuhut tairu aw tahwee bihir reehu bee makaanin saheeq'),
  ('en.transliteration', 22, 32, 'Zaalika wa mai yu\'azzim sha\'aaa\'iral laahi fa innahaa min taqwal quloob'),
  ('en.transliteration', 22, 33, 'Lakum feehaa manaafi\'u ilaaa ajalim musamman summa mahilluhaaa ilal Baitil \'Ateeq'),
  ('en.transliteration', 22, 34, 'Wa likulli ummatin ja\'alnaa mansakal liyazkurus mal laahi \'alaa maa razaqahum mim baheematil an\'aam; failaahukum ilaahunw Waahidun falahooo aslimoo; wa bashshiril mukhbiteen'),
  ('en.transliteration', 22, 35, 'Allazeena izaa zukiral laahu wajilat quloobuhum wassaabireena \'alaa maaa asaabahum walmuqeemis Salaati wa mimmaa razaqnaahum yunfiqoon'),
  ('en.transliteration', 22, 36, 'Walbudna ja\'alnaahaa lakum min sha\'aaa\'iril laahi lakum feehaa khairun fazkurusmal laahi \'alaihaa sawaaff; fa izaa wajabat junoobuhaa fakuloo minhaa wa at\'imul qaani\'a walmu\'tarr; kazaalika sakhkharnaahaa lakum la\'allakum tashkuroon'),
  ('en.transliteration', 22, 37, 'Lany yanaalal laaha luhoo muhaa wa laa dimaaa\'uhaa wa laakiny yanaaluhut taqwaa minkum; kazaalika sakhkharhaa lakum litukabbirul laaha \'alaa ma hadaakum; wa bashshirul muhsineen'),
  ('en.transliteration', 22, 38, 'Innal laaha yudaafi\' \'anil lazeena aamanoo; innal laaha laa yuhibbu kulla khawwaanin kafoor'),
  ('en.transliteration', 22, 39, 'Uzina lillazeena yuqaataloona bi annahum zulimoo; wa innal laaha \'alaa nasrihim la Qaderr'),
  ('en.transliteration', 22, 40, 'Allazeena ukhrijoo min diyaarihim bighairi haqqin illaaa any yaqooloo rabbunallaah; wa law laa daf\'ul laahin naasa ba\'dahum biba\'dil lahuddimat sawaami\'u wa biya\'unw wa salawaatunw wa masaajidu yuzkaru feehasmul laahi kaseeraa; wa layansurannal laahu mai yansuruh; innal laaha la qawiyyun \'Azeez'),
  ('en.transliteration', 22, 41, 'Allazeena im makkan naahum fil ardi aqaamus Salaata wa aatawuz Zakaata wa amaroo bilma\'roofi wa nahaw \'anil munkar; wa lillaahi \'aaqibatul umoor'),
  ('en.transliteration', 22, 42, 'Wa iny yukazzibooka faqad kazzabat qablahum qawmu Nooinw wa Aadunw wa Samood'),
  ('en.transliteration', 22, 43, 'Wa qawmu Ibraaheema wa qawmu Loot'),
  ('en.transliteration', 22, 44, 'Wa as haabu Madyana wa kuzziba Moosaa fa amlaitu lilkaafireena summa akhaztuhum fakaifa kaana nakeer'),
  ('en.transliteration', 22, 45, 'Faka ayyim min qaryatin ahlaknaahaa wa hiya zaalimatun fahiya khaawiyatun \'alaa \'urooshihaa wa bi\'rim mu\'at talatinw wa qasrim masheed'),
  ('en.transliteration', 22, 46, 'Afalam yaseeroo fil ardi fatakoona lahum quloobuny ya\'qiloona bihaaa aw aazaanuny yasm\'oona bihaa fa innahaa laa ta\'mal absaaru wa laakin ta\'mal quloobul latee fissudoor'),
  ('en.transliteration', 22, 47, 'Wa yasta\'juloonaka bil\'azaabi wa lany yukhlifal laahu wa\'dah; wa inna yawman \'inda Rabbika ka\'alfi sanatim mimmaa ta\'uddoon'),
  ('en.transliteration', 22, 48, 'Wa ka ayyim min qaryatin amlaitu lahaa wa hiya zaalimatun summa akhaztuhaa wa ilaiyal maseer'),
  ('en.transliteration', 22, 49, 'Qul yaaa ayyuhan naasu innamaaa ana lakum nazeerum mubeen'),
  ('en.transliteration', 22, 50, 'Fallazeena aamanoo wa \'amilu saalihaati lahum maghfiratunw wa rizqun kareem'),
  ('en.transliteration', 22, 51, 'Wallazeena sa\'aw feee Aayaatinaa mu\'aajizeena ulaaa ika As-haabul jaheem'),
  ('en.transliteration', 22, 52, 'Wa maaa arsalnaa min qablika mir Rasoolinnw wa laa Nabiyyin illaaa izaaa tamannaaa alqash Shaitaanu feee umniy yatihee fa yansakhul laahu maa yulqish Shaitaanu summa yuhkimul laahu aayaatih; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 22, 53, 'Liyaj\'ala maa yulqish Shaitaanu fitnatal lillazeena fee quloobihim maradunw walqaasiyati quloobuhum; wa innaz zaalimeena lafee shiqaaqim ba\'eed'),
  ('en.transliteration', 22, 54, 'Wa liya\'lamal lazeena ootul \'ilma annahul haqqu mir Rabbika fa yu\'minoo bihee fatukhbita ahoo quloobuhum; wa innal laaha lahaadil lazeena aamanoo ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 22, 55, 'Wa laa yazaalul lazeena kafaroo fee miryatim minhu hattaa taatiyahumus Saa\'atu baghtatan aw yaatiyahum \'azaabu Yawmin \'aqeem'),
  ('en.transliteration', 22, 56, 'Almulku Yawma\'izil lillaahi yahkumu bainahum; fallazeena aamanoo wa \'amilus saalihaati fee jannaatin Na\'eem'),
  ('en.transliteration', 22, 57, 'Wallazeena kafaroo wa kazzaboo bi Aayaatinaa fa ulaaa\'ika lahum \'azaabum muheen'),
  ('en.transliteration', 22, 58, 'Wallazeena haajaroo fee sabeelil laahi summa qutilooo law maatoo la yarzuqan nahumul laahu rizqan hasanaa; wa innal laaha la Huwa khairur raaziqeen'),
  ('en.transliteration', 22, 59, 'La yudkhilan nahum mud khalany yardawnah; wa innal laaha la \'Aleemun Haleem'),
  ('en.transliteration', 22, 60, 'Zaalika wa man \'aaqaba bimisli maa \'ooqiba bihee summa bughiya \'alaihi la yansurannahul laah; innal laaha la \'Afuwwun Ghafoor'),
  ('en.transliteration', 22, 61, 'Zaalika bi annal laaha yoolijul laila fin nahaari wa yoolijun nahaara fil laili wa annal laaha Samee\'um Baseer'),
  ('en.transliteration', 22, 62, 'Zaalika bi annal laaha Huwal haqqu wa anna maa yad\'oona min doonihee huwal baatilu wa annal laaha Huwal \'Aliyyul kabeer'),
  ('en.transliteration', 22, 63, 'Alam tara annal laaha anzala minas samaaa\'i maaa\'an fatusbihul ardu mukhdarrah; innal laaha Lateefun Khabeer'),
  ('en.transliteration', 22, 64, 'Lahoo ma fis samaawaati wa ma fil ard; wa innal laaha la Huwal Ghaniyyul Hameed'),
  ('en.transliteration', 22, 65, 'Alam tara annal laaha sakhkhara lakum maa fil ardi wal fulka tajree fil bahri bi amrihee wa yumsikus samaaa\'a an taqa\'a \'alal ardi illaa biiznih; innal laaha binnaasi la Ra\'oofur Raheem'),
  ('en.transliteration', 22, 66, 'Wa Huwal lazee ahyaakum summa yumeetukum summma yuheekum; innal insaana lakafoor'),
  ('en.transliteration', 22, 67, 'Likulli ummatin ja\'alnaa mansakan hum naasikoohu falaa yunaazi \'unnaka fil amr; wad\'u ilaa Rabbika innaka la \'alaa hudam mustaqeem'),
  ('en.transliteration', 22, 68, 'Wa in jaadalooka faqulil laahu a\'lamu bimaa ta\'maloon'),
  ('en.transliteration', 22, 69, 'Allaahu yahkumu bainakum Yawmal Qiyaamati feemaa kuntum feehi takhtalifoon'),
  ('en.transliteration', 22, 70, 'Alam ta\'lam annal laaha ya\'lamu maa fis samaaa\'i wal ard; inna zaalika fee kitaab; inna zaalika \'alal laahi yaseer'),
  ('en.transliteration', 22, 71, 'Wa ya\'budoona min doonil laahi maa lam yunazzil bihee sultaananw wa maa laisa lahum bihee \'ilm; wa maa lizzaalimeena min naseer'),
  ('en.transliteration', 22, 72, 'Wa izaa tutlaa \'laihim Aayaatunaa baiyinaatin ta\'rifu fee wujoohil lazeena kafarul munkara yakaadoona yastoona bil lazeena yatloona \'alaihim Aayaatinaa; qul afa unab bi\'ukum bisharrim min zaalikum; an Naaru wa \'adahal laahul lazeena kafaroo wa bi\'sal maseer'),
  ('en.transliteration', 22, 73, 'Yaaa ayyuhan naasu duriba masalun fastami\'oo lah; innal lazeena tad\'oona min doonil laahi lai yakhluqoo zubaabanw wa lawijtama\'oo lahoo wa iny yaslub humuz zubbabu shai\'al laa yastan qizoohu minh; da\'ufat taalibu walmatloob'),
  ('en.transliteration', 22, 74, 'Maa qadrul laaha haqqa qadrih; innal laaha la Qawiyyun \'Azeez'),
  ('en.transliteration', 22, 75, 'Allahu yastafee minal malaaa\'ikati Rusulanw wa minan naas; innal laaha Samee\'um Baseer'),
  ('en.transliteration', 22, 76, 'Ya\'lamu maa baina aydeehim wa maa khalfahum; wa ilal laahi turja\'ul umoor'),
  ('en.transliteration', 22, 77, 'Yaaa ayyuhal lazeena aamanur ka\'oo wasjudoo wa\'budoo Rabbakum waf\'alul khaira la\'allakum tuflihoon'),
  ('en.transliteration', 22, 78, 'Wa jaahidoo fil laahi haqqa jihaadih; Huwaj tabaakum wa maa ja\'ala \'alaikum fid deeni min haraj; Millata abeekum Ibraaheem; Huwa sammaakumul muslimeena min qablu wa fee haaza li yakoonar Rasoolu shaheedan \'alaikum wa takoonoo shuhadaaa\'a \'alan naas; fa aqeemus salaata wa aatuz zakaata wa\'tasimoo billaahi Huwa mawlaakum fani\'mal mawlaa wa ni\'man naseer')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 22, 1, 'اے لوگو اپنے رب سے ڈرو بے شک قیامت کا زلزلہ ایک بڑی چیز ہے'),
  ('ur.ahmedali', 22, 2, 'جس دن اسے دیکھو گے ہر دودھ پلانے والی اپنے دودھ پیتے کو بھول جائے گی اور ہر حمل والی اپنا حمل ڈال دے گی اور تجھے لوگ مدہوش نظر آئیں گے اور وہ مدہوش نہ ہوں گے لیکن الله کا عذاب سخت ہوگا'),
  ('ur.ahmedali', 22, 3, 'اور بعضے لوگ وہ ہیں جو الله کے معاملے میں بے سمجھی سے جھگڑتے ہیں اور ہر شیطان سرکش کے کہنے پر چلتے ہیں'),
  ('ur.ahmedali', 22, 4, 'جس کے حق میں لکھاجا چکا ہے کہ جو اسے یار بنائے گا تو وہ اسے گمراہ کر کے رہے گا اور اسے دوزخ کے عذاب کا راستہ دکھائے گا'),
  ('ur.ahmedali', 22, 5, 'اے لوگو اگر تمہیں دوبارہ زندہ ہونے میں شک ہے تو ہم نے تمہیں مٹی سے پھر قطرہ سے پھر جمے ہوئے خون سے پھر گوشت کی بوٹی نقشہ بنی ہوئی اور بغیر نقشہ بنی ہوئی سے بنایا تاکہ ہم تمہارے سامنے ظاہر کر دیں اور ہم ر حم میں جس کو چاہتے ہیں ایک مدت معین تک ٹھیراتے ہیں پھر ہم تمہیں بچہ بنا کر باہر لاتے ہیں پھر تاکہ تم اپنی جوانی کو پہنچو اور کچھ تم میں سے مرجاتے ہیں اور کچھ تم میں سے نکمی عمر تک پہنچائے جاتے ہیں کہ سمجھ بوجھ کا درجہ پاکر ناسمجھی کی حالت میں جا پڑتا ہے اور تم زمین کوسوکھی دیکھتے ہو پھر جب ہم اس پر پانی برساتے ہیں تو تر و تازہ ہو جاتی ہے او رہر قسم کے خوش نمانباتات اُگ آتے ہیں'),
  ('ur.ahmedali', 22, 6, 'یہ اس لیے ہے کہ الله ہی برحق ہے اور مردوں کو زندہ کرے گا اور وہ ہر بات پر قادر ہے'),
  ('ur.ahmedali', 22, 7, 'اور بے شک قیامت آنے والی ہے جس میں کوئی شک نہیں اور بے شک الله قبروں والوں کو دوبارہ اٹھائے گا'),
  ('ur.ahmedali', 22, 8, 'اور بعضاً وہ شخص ہے جو الله کے معاملہ میں بے سمجھی اور دلیل اور روشن کتاب کے بغیر تکبر سے جھگڑتا ہے'),
  ('ur.ahmedali', 22, 9, 'تاکہ الله کی راہ سے بہکائے اس کے لیے دنیا میں رسوائی ہے اور قیامت کے دن بھی ہم اسے دوزخ کے عذاب کا مزہ چکھاویں گے'),
  ('ur.ahmedali', 22, 10, 'یہ تیرے ہاتھوں کے کیے ہوئے کاموں کا بدلہ ہے اور بےشک الله بندوں پر ظلم کرنے والا نہیں'),
  ('ur.ahmedali', 22, 11, 'اور بعض وہ لوگ ہیں کہ الله کی بندگی کنارے پر ہو کر کرتے ہیں پھر اگر اسے کچھ فائدہ پہنچ گیا تو اس عبادت پر قائم ہو گیا اور اگر تکلیف پہنچ گئی تو منہ کے بل پھر گیا دنیا اور آخرت گنوائی یہی وہ صریح خسارا ہے'),
  ('ur.ahmedali', 22, 12, 'الله کے سوا ایسی چیز کو پکارتا ہے جو نہ اسے ضرر دے سکے اور نہ اسے فائدہ پہنچا سکے یہی وہ پرلے درجہ کی گمراہی ہے'),
  ('ur.ahmedali', 22, 13, 'ایسے کو پکارتا ہے جس کا ضرر اس کے نفع سے نزدیک تر ہے ایسا کارساز بھی برا اور ایسا رفیق بھی برا ہے'),
  ('ur.ahmedali', 22, 14, 'بے شک الله ان لوگوں کو جو ایمان لائے اور اچھے کام کیے ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہوں گی بے شک الله جو چاہتا ہے کرتا ہے'),
  ('ur.ahmedali', 22, 15, 'جسے یہ خیال ہو کہ الله دنیا اور آخرت میں اس کی ہرگز مدد نہ کرے گااسے چاہیے کہ چھت میں ایک رسی لٹکائے پھر اسے کاٹ دے پھر دیکھے کہ اس کی تدبیر اس کے غصہ کو دور کرتی ہے'),
  ('ur.ahmedali', 22, 16, 'اور اسی طرح ہم نےاس قرآن کو واضح آیتیں بنا کر نازل کیا ہے اور بے شک الله جسے چاہتا ہے ہدایت کرتا ہے'),
  ('ur.ahmedali', 22, 17, 'بے شک الله مسلمانوں اور یہودیوں اور صابیوں اور عیسائیوں اورمجوسیوں اور مشرکوں میں قیامت کے دن فیصلہ کرے گا بےشک ہر چیز الله کے سامنے ہے'),
  ('ur.ahmedali', 22, 18, 'کیا تم نےنہیں دیکھا کہ جو کوئی آسمانوں میں ہے اور جو کوئی زمین میں ہے اور سورج اور چاند اور ستارے اور پہاڑ اور درخت اورچار پائے اور بہت سے آدمی الله ہی کو سجدہ کرتے ہیں اور بہت سے ہیں کہ جن پر عذاب مقرر ہو چکا ہے اور جسے الله ذلیل کرتا ہے پھر اسے کوئی عزت نہیں دےسکتا بے شک الله جو چاہتا ہے کرتا ہے'),
  ('ur.ahmedali', 22, 19, 'یہ دو فریق ہیں جو اپنے رب کے معاملہ میں جھگڑتے ہیں پھر جو منکر ہیں ان کے لیے آگ کے کپڑے قطع کیے گئے ہیں اور ان کےسروں پر کھولتا ہوا پانی ڈالا جائے گا'),
  ('ur.ahmedali', 22, 20, 'جس سے جو کچھ ان کے پیٹ میں ہے اور کھالیں جھلس دی جائیں گی'),
  ('ur.ahmedali', 22, 21, 'اور ان پر لوہے کے گرز پڑیں گے'),
  ('ur.ahmedali', 22, 22, 'جب گھبرا کر وہاں سے نکلنا چاہیں گے اسی میں لوٹا دیئے جائیں گے اور دوزخ کا عذاب چکھتے رہو'),
  ('ur.ahmedali', 22, 23, 'بے شک الله ان لوگوں کو جو ایمان لائے اور اچھے کام کیے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہوں گی وہاں انہیں سونے کے کنگن اور موتی پہنائیں جائیں گے اور وہاں ان کا لباس ریشمی ہوگا'),
  ('ur.ahmedali', 22, 24, 'اور انہوں نے عمدہ بات کی راہ پائی اور تعریف والے الله کی راہ پائی'),
  ('ur.ahmedali', 22, 25, 'بے شک جو منکر ہوئے اور لوگوں کو الله کے راستہ اور مسجد حرام سے روکتے ہیں جسے ہم نے سب لوگو ں کے لیے بنایا ہے وہاں اس جگہ کا رہنے والا اورباہروالادونوں برابر ہیں اور جو وہاں ظلم سے کجروی کرنا چاہے تو ہم اسے دردناک عذاب چکھائیں گے'),
  ('ur.ahmedali', 22, 26, 'اور جب ہم نے ابراھیم کے لیے کعبہ کی جگہ معین کر دی کہ میرے ساتھ کسی کو شریک نہ کراور میرے گھر کو طواف کرنے والوں اور قیام کرنے والوں اور رکوع و سجود کرنے والوں کے لیے پاک رکھ'),
  ('ur.ahmedali', 22, 27, 'اور لوگوں میں حج کا اعلان کر دے کہ تیرے پاس پا پیادہ او رپتلے دُبلے اونٹوں پر دور دراز راستوں سے آئیں'),
  ('ur.ahmedali', 22, 28, 'تاکہ اپنے فائدوں کے لیے آموجود ہوں اورتاکہ جو چار پائے الله نےانہیں دیے ہیں ان پر مقررہ دنوں میں الله کا نام یاد کریں پھر ان میں سے خود بھی کھاؤ اور محتاج فقیر کو بھی کھلاؤ'),
  ('ur.ahmedali', 22, 29, 'پھر چاہیئے کہ اپنا میل کچیل دور کریں اور اپنی نذریں پوری کریں اور قدیم گھر کا طواف کریں'),
  ('ur.ahmedali', 22, 30, 'یہی حکم ہے اور جو الله کی معزز چیزوں کی تعظیم کرے گا سو یہ اس کے لیے اس کے رب کے ہاں بہتر ہے اور تمہارے لیے مویشی حلال کر دیئے گئے ہیں مگر وہ جو تمہیں پڑھ کر سنائے جاتے ہیں پھر بتوں کی ناپاکی سے بچو اور جھوٹی بات سے بھی پرہیز کرو'),
  ('ur.ahmedali', 22, 31, 'خاص الله کے ہو کر رہو اس کے ساتھ کسی کو شریک نہ کرو اور جو الله کے ساتھ کسی کو شریک کرتا ہے تو گویا وہ آسمان سے گر پڑا پھر اسے پرندے اچک لیتے ہیں یا اسے ہوا اڑا کر کسی دور جگہ پھینک دیتی ہے'),
  ('ur.ahmedali', 22, 32, 'بات یہی ہے اور جو شخص الله کی نامزد چیزوں کی تعظیم کرتا ہے سو یہ دل کی پرہیز گاری ہے'),
  ('ur.ahmedali', 22, 33, 'تمہارے لیے ان میں ایک وقت معین تک فائدے ہیں پھر اس کے ذبح ہونے کی جگہ قدیم گھر کے قریب ہے'),
  ('ur.ahmedali', 22, 34, 'اور ہر امت کے لیے ہم نے قربانی مقرر کر دی تھی تاکہ الله نے جو چار پائے انہیں دیے ہیں ان پر الله کا نام یاد کیا کریں پھر تم سب کا معبود تو ایک الله ہی ہے پس اس کے فرمانبردار رہو اور عاجزی کرنے والوں کو خوشخبری سنا دو'),
  ('ur.ahmedali', 22, 35, 'وہ لوگ جب الله کا نام لیا جائے تو ان کے دل ڈر جاتے ہیں اور جب ان پر مصیبت آئے تو صبر کرنے والے ہیں اور نماز قائم کرنے والے ہیں اور جو کچھ ہم نے انہیں دیا ہے اس میں سے خرچ کرتے ہیں'),
  ('ur.ahmedali', 22, 36, 'اور ہم نے تمہارے لیے قربانی کے اونٹ کو الله کی نشانیوں میں سے بنایا ہے تمہارے لیے ان میں فائدے بھی ہیں پھر ان پر الله کا نام کھڑا کر کے لو پھر جب وہ کسی پہلو پر گر پڑیں تو ان میں سے خود کھاؤ اور صبر سے بیٹھنے والے اور سائل کو بھی کھلاؤ الله نے انہیں تمہارے لیے ایسا مسخر کر دیا ہے تاکہ تم شکر کرو'),
  ('ur.ahmedali', 22, 37, 'الله کو نہ ان کا گوشت اور نہ ان کا خون پہنچتا ہے البتہ تمہاری پرہیز گاری اس کے ہاں پہنچتی ہے اسی طرح انہیں تمہارے تابع کر دیا تاکہ تم الله کی بزرگی بیان کرو اس پر کہ اس نے تمہیں ہدایت کی اور نیکوں کو خوشخبری سنا دو'),
  ('ur.ahmedali', 22, 38, 'بیشک الله ایمان والوں سے دشمنوں کو ہٹا دے گا الله کسی دغا باز نا شکر گزار کو پسند نہیں کرتا'),
  ('ur.ahmedali', 22, 39, 'جن سے کافر لڑتے ہیں انہیں بھی لڑنے کی اجازت دی گئی ہے اس لیے کہ ان پر ظلم کیا گیا اور بیشک الله ان کی مدد کرنے پر قادر ہے'),
  ('ur.ahmedali', 22, 40, 'وہ لوگ جنہیں ناحق ان کے گھروں سے نکال دیا گیا ہے صرف اس کہنے پر کہ ہمارا رب الله ہے اور اگر الله لوگوں کو ایک دوسرے سے نہ ہٹاتا تو تکیئے اور مدرسے اورعبادت خانے اور مسجدیں ڈھا دی جاتیں جن میں الله کا نام کثرت سے لیا جاتا ہے اور الله ضرور اس کی مدد کر ے گا جو اللہ کی مددکرے گابیشک الله زبردست غالب ہے'),
  ('ur.ahmedali', 22, 41, 'وہ لوگ اگر ہم انہیں دنیا میں حکومت دے دیں تو نماز کی پابندی کریں اور زکوٰة دیں اور نیک کام کا حکم کریں اور برے کاموں سے روکیں اور ہر کام کا انجام تو الله کے ہی ہاتھ میں ہے'),
  ('ur.ahmedali', 22, 42, 'اور اگر تمہیں جھٹلائیں تو ان سے پہلے نوح کی قوم اور عاد اور ثمود'),
  ('ur.ahmedali', 22, 43, 'اور ابراھیم کی قوم اور لوط کی قوم'),
  ('ur.ahmedali', 22, 44, 'اور مدین والے اپنے اپنے نبی کو جھٹلا چکے ہیں اور موسیٰ کو بھی جھٹلایا گیا پھر میں نے منکروں کو مہلت دی پھر میں نے انہیں پکڑا پھر میری پکڑ کیسی تھی'),
  ('ur.ahmedali', 22, 45, 'سو کتنی بستیاں ہم نے ہلاک کر دیں اور وہ گناہ گار تھیں اب وہ اپنی چھتوں پر گری پڑی ہیں اور کتنے کنوئیں نکمے اور کتنے پکے محل اجڑے اجڑے پڑے ہیں'),
  ('ur.ahmedali', 22, 46, 'کیا انھوں نے ملک میں سیر نہیں کی پھر ان کے ایسے دل ہوجاتے جن سے سمجھتے یا ایسے کان ہو جاتے جن سے سنتے پس تحقیق بات یہ ہے کہ آنکھیں اندھی نہیں ہوتیں بلکہ دل جو سینوں میں ہیں اندھے ہو جاتے ہیں'),
  ('ur.ahmedali', 22, 47, 'اور تجھ سے عذاب جلدی مانگتے ہیں اور الله اپنے وعدہ کا ہرگز خلاف نہیں کرے گا اور ایک دن تیرے رب کے ہاں ہزار برس کے برابر ہوتا ہے جوتم گنتے ہو'),
  ('ur.ahmedali', 22, 48, 'اور کتنی بستیوں کو میں نے مہلت دی حالانکہ وہ ظالم تھیں پھر میں نے انہیں پکڑا اور میری طرف ہی پھر کر آنا ہے'),
  ('ur.ahmedali', 22, 49, 'کہہ دو اے لوگو میں تو صرف تمہیں صاف صاف ڈرانے والا ہوں'),
  ('ur.ahmedali', 22, 50, 'پھر جو لوگ ایمان لائے اوراچھے کام کیے ان کے لیے بخشش اور عزت کی روزی ہے'),
  ('ur.ahmedali', 22, 51, 'اور جنہوں نے ہماری آیتیوں کے پست کرنے میں کوشش کی وہی دوزخی ہیں'),
  ('ur.ahmedali', 22, 52, 'اور ہم نے تجھ سے پہلے کوئی بھی ایسا رسول اور نبی نہیں بھیجا کہ جس نے جب کوئی تمنا کی ہو اور شیطان نے اس کی تمنا میں کچھ آمیزش نہ کی ہو پھر الله ّ شیطان کی آمیزش کو دور کرکے اپنی آیتوں کو محفوظ کردیتا ہے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 22, 53, 'تاکہ شیطان کی آمیزش کو ان لوگوں کے لیے آزمائش بنا دے جن کے دلوں میں بیماری ہے اور جن کے دل سخت ہیں اور بے شک ظالم بڑی ضدی میں پڑے ہوئے ہیں'),
  ('ur.ahmedali', 22, 54, 'اور تاکہ علم والے اسے تیرے رب کی طرف سے حق سمجھ کر ایمان لے آئیں پھر ان کے دل اس کے لیے جھک جائیں اور بیشک الله ایمان داروں کو سیدھے راستہ کی طرف ہدایت کرنے والا ہے'),
  ('ur.ahmedali', 22, 55, 'اور منکر قرآن کی طرف سے ہمیشہ شک میں رہیں گے یہاں تک کہ قیامت یکاک ان پر آ مودجود ہو یا منحوس دن کا عذاب ان پر نازل ہو'),
  ('ur.ahmedali', 22, 56, 'اس دن الله ہی کی حکومت ہوگی وہی ان میں فیصلہ کر لے گا پھر جو ایمان لائے اور اچھے کام کیے وہ نعمت کے باغوں میں ہوں گے'),
  ('ur.ahmedali', 22, 57, 'اورجو منکر ہوئے اور ہماری آیتوں کو جھٹلایا سو انکے لیے ذلت کا عذاب ہے'),
  ('ur.ahmedali', 22, 58, 'اور جنہوں نے الله کی راہ میں ہجرت کی پھر قتل کیے گئے یا مر گئے البتہ انہیں الله اچھا رزق دے گا اور بے شک الله سب سے بہتر رزق دینے والا ہے'),
  ('ur.ahmedali', 22, 59, 'البتہ انہیں ایسی جگہ پہنچائے گا جسے پسند کریں گے اور بیشک الله جاننے والا بردبار ہے'),
  ('ur.ahmedali', 22, 60, 'بات یہ ہے اور جس نے اسی قدر بدلہ لیا جس قدر اسے تکلیف دی گئی تھی پھر اس پر زیادتی کی گئی تو الله ضرور اس کی مد کرے گا بے شک الله درگزر کرنے والا معاف کرنے والا ہے'),
  ('ur.ahmedali', 22, 61, 'وہ اس لیے کہ الله رات کو دن میں اور دن کو رات میں داخل کیا کرتا ہے اور بے شک الله سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 22, 62, 'یہ اس لیے کہ حق الله ہی کی ہستی ہے اور جنہیں اس کے سوا پکارتے ہیں باطل ہیں اور بے شک الله ہی بلند مرتبہ بڑائی والا ہے'),
  ('ur.ahmedali', 22, 63, 'کیا تو نے نہیں دیکھا کہ الله نے آسمان سے پانی نازل کیا پھر زمین سرسبز ہوجاتی ہے بے شک الله مہربان خبردار ہے'),
  ('ur.ahmedali', 22, 64, 'جوکچھ آسمانوں اور زمین میں ہے سب اسی کا ہے اور بے شک الله وہی بے نیاز قابل تعریف ہے'),
  ('ur.ahmedali', 22, 65, 'کیا تم نے نہیں دیکھا کہ الله نے زمین کی سب چیزوں اور کشتیوں کو تمہارے تابع کر دیا ہےجو دریا میں اس کے حکم سے چلتی ہیں اور آسمان کو زمین پر گرنے سے تھامے ہوئے ہے مگر اس کے حکم سے بے شک الله لوگوں پر نرمی کرنے والا نہایت رحم کرنے والا ہے'),
  ('ur.ahmedali', 22, 66, 'اور وہ وہی ہے جس نے تمہیں زندہ کیا پھر تمہیں مارے گا پھر تمہیں زندہ کرے گا بے شک انسان البتہ بڑا ہی نا شکرا ہے'),
  ('ur.ahmedali', 22, 67, 'ہم نے ہر قوم کے لیے ایک دستور مقرر کر دیا ہے جس پر وہ چلتے ہیں پھر انہیں تمہارے ساتھ اس معاملہ میں جھگڑنا نہ چاہیئے اور اپنے رب کی طرف بلا بے شک تو البتہ سیدھے راستہ پر ہے'),
  ('ur.ahmedali', 22, 68, 'اور اگر تجھ سے جھگڑا کریں تو کہہ دے الله بہتر جانتا ہے جو تم کرتے ہو'),
  ('ur.ahmedali', 22, 69, 'الله قیامت کے دن تمہارے درمیان فیصلہ کرے گا جس چیز میں تم اختلاف کرتے تھے'),
  ('ur.ahmedali', 22, 70, 'کیا تجھے معلوم نہیں کہ الله جانتا ہے جو کچھ آسمان اور زمین میں ہے یہ سب کتاب میں لکھا ہوا ہے یہ الله پر آسان ہے'),
  ('ur.ahmedali', 22, 71, 'اور الله کے سوا ایسی چیزکو پوجتے ہیں جس پر اس نے کوئی سند نہیں اتاری اور نہ انکے پاس کوئی اس کا علم ہے اور ظالموں کا کوئی مددگار نہ ہوگا'),
  ('ur.ahmedali', 22, 72, 'اور جب انہیں ہماری کھلی کھلی آیتیں پڑھ کر سنائی جائیں تو تم منکروں کے چہروں میں ناراضگی دیکھو گے قریب ہوتے ہیں کہ جو لوگ انہیں ہماری آیتیں پڑھ کر سناتے ہیں ان پر حملہ کر دیں کہہ دو کیا میں تمہیں اس سے بھی بدتر بات بتاؤں آگ ہے کہ جس کا الله نے منکروں سے وعدہ کیا ہے اور وہ بری جگہ ہے'),
  ('ur.ahmedali', 22, 73, 'اے لوگو ایک مثال بیان کی جاتی ہے اسے کان لگا کر سنو جنہیں تم الله کے سوا پکارتے ہو وہ ایک مکھی بھی نہیں بنا سکتے اگرچہ وہ سب اس کے لیے جمع ہوجائیں اور اگر ان سے مکھی کوئی چیز چھین لے تو اسے مکھی سے چھڑا نہیں سکتے عابد اور معبود دونوں ہی عاجز ہیں'),
  ('ur.ahmedali', 22, 74, 'انہوں نے الله کی کچھ بھی قدر نہ کی بے شک الله زوروالا غالب ہے'),
  ('ur.ahmedali', 22, 75, 'فرشتوں اور آدمیوں میں سے الله ہی پیغام پہنچانے کے لیے چن لیتا ہے بے شک الله سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 22, 76, 'وہ ان کے اگلے اور پچھلے حالات جانتا ہے اور سب کاموں کا مدار الله پر ہے'),
  ('ur.ahmedali', 22, 77, 'اے ایمان والو رکوع اور سجدہ کرو اور اپنے رب کی بندگی کرو اور بھلائی کرو تاکہ تمہارا بھلا ہو'),
  ('ur.ahmedali', 22, 78, 'اور الله کی راہ میں کوشش کرو جیسا کوشش کرنے کا حق ہے اس نے تمہیں پسند کیا ہے اور دین میں تم پر کسی طرح کی سختی نہیں کی تمہارے باپ ابراھیم کا دین ہے اسی نے تمہارا نام پہلے سےمسلمان رکھا تھااوراس قرآن میں بھی تاکہ رسول تم پر گواہ بنے اور تم لوگو ں پر گواہ بنو پس نماز قائم کرو اور زکوٰة دو اور الله کو مضبوط ہو کر پکڑو وہی تمہارا مولیٰ ہے پھر کیا ہی اچھامولیٰ اور کیا ہی اچھا مددگار ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 22, 1, 'Ey insanlar! Rabbinizden sakının; doğrusu kıyamet gününün sarsıntısı büyük şeydir.'),
  ('tr.diyanet', 22, 2, 'Kıyameti gören her emzikli kadın emzirdiğini unutur, her hamile kadın çocuğunu düşürür. İnsanları sarhoş gibi görürsün oysa sarhoş değildirler, fakat bu sadece Allah\'ın azabının çetin olmasındandır.'),
  ('tr.diyanet', 22, 3, 'Allah hakkında bilmeden taşıyan ve her azılı şeytana uyan insanlar vardır.'),
  ('tr.diyanet', 22, 4, 'Onun hakkında şöyle yazılmıştır: O kendisini dost edinen kimseyi saptırır ve alevli azaba götürür.'),
  ('tr.diyanet', 22, 5, 'Ey insanlar! Öldükten sonra tekrar dirilmekten şüphede iseniz bilin ki, ne olduğunuzu size açıklamak için, Biz sizi topraktan sonra nutfeden, sonra pıhtılaşmış kandan, sonra da yapısı belli belirsiz bir çiğnem etten yaratmışızdır. Dilediğimizi belli bir süreye kadar rahimlerde tutarız; sonra sizi çocuk olarak çıkartırız, böylece yetişip erginlik çağına varırsınız. Kiminiz öldürülür, kiminiz de ömrünün en fena zamanına ulaştırılır ki, bilirken birşey bilmez olur. Yeryüzünü görürsün ki kupkurudur; fakat Biz ona su indirdiğimiz zaman harekete geçer, kabarır, her güzel bitkiden çift çift yetiştirir.'),
  ('tr.diyanet', 22, 6, 'Bunlar, yalnız Allah\'ın gerçek olduğunu, ölüleri dirilttiğini, gücünün herşeye yettiğini, şüphe götürmeyen kıyamet saatinin geleceğini, Allah\'ın kabirlerde olanı dirilteceğini gösterir.'),
  ('tr.diyanet', 22, 7, 'Bunlar, yalnız Allah\'ın gerçek olduğunu, ölüleri dirilttiğini, gücünün herşeye yettiğini, şüphe götürmeyen kıyamet saatinin geleceğini, Allah\'ın kabirlerde olanı dirilteceğini gösterir.'),
  ('tr.diyanet', 22, 8, 'Bilmeden, doğruya götüren bir rehberi olmadan, aydınlatıcı bir kitabı da bulunmadan Allah yolundan saptırmak için büyüklük taslayarak Allah hakkında tartışan insan vardır. Dünyada rezillik onadır; ona kıyamet günü yakıcı azabı tattırırız.'),
  ('tr.diyanet', 22, 9, 'Bilmeden, doğruya götüren bir rehberi olmadan, aydınlatıcı bir kitabı da bulunmadan Allah yolundan saptırmak için büyüklük taslayarak Allah hakkında tartışan insan vardır. Dünyada rezillik onadır; ona kıyamet günü yakıcı azabı tattırırız.'),
  ('tr.diyanet', 22, 10, 'Ona: "Bunlar senin yaptıklarından ötürüdür" denir, yoksa Allah, kullarına karşı hiç de zalim değildir.'),
  ('tr.diyanet', 22, 11, 'İnsanlar içinde Allah\'a, bir yar kenarındaymış gibi kulluk eden vardır. Ona bir iyilik gelirse yatışır, başına bir bela gelirse yüz üstü döner. Dünyayı da ahireti de kaybeder. İşte apaçık kayıp budur.'),
  ('tr.diyanet', 22, 12, 'Allah\'ı bırakıp, kendisine fayda da zarar da veremeyen şeylere yalvarır. İşte derin sapıklık budur.'),
  ('tr.diyanet', 22, 13, 'Kendisine zararı faydasından daha yakın olana yalvarır. Yalvardığı şey ne kötü yardımcı ve ne kötü yoldaştır!'),
  ('tr.diyanet', 22, 14, 'Doğrusu Allah, inananları ve yararlı işler işleyenleri, içlerinden ırmaklar akan cennetlere koyar. Allah, şüphesiz, istediğini yapar.'),
  ('tr.diyanet', 22, 15, 'Allah\'ın peygamber\'e dünyada ve ahirette yardım etmeyeceğini sanan kimse, yukarı bağladığı bir ipe kendini asıp, boğsun; bir düşünsün bakalım, bu hilesi kendisini öfkelendiren şeye engel olabilir mi?'),
  ('tr.diyanet', 22, 16, 'İşte böylece Kuran\'ı apaçık ayetler olarak indirdik. Allah, şüphesiz, dilediğini doğru yola eriştirir.'),
  ('tr.diyanet', 22, 17, 'Doğrusu, inananlar ve yahudiler, sabiiler, hıristiyanlar, mecusiler, ortak koşanlar arasında, kıyamet günü Allah kesin hüküm verecektir. Doğrusu Allah herşeye şahiddir.'),
  ('tr.diyanet', 22, 18, 'Göklerde ve yerde olanların, güneş, ay, yıldızlar, dağlar, ağaçlar, hayvanların ve insanların birçoğunun Allah\'a secde ettiklerini görmüyor musun? İnsanların birçoğu da azabı hak etmiştir. Allah\'ın alçalttığı kimseyi yükseltebilecek yoktur. Doğrusu Allah ne dilerse yapar.'),
  ('tr.diyanet', 22, 19, 'İşte Rableri hakkında tartışmaya giren iki taraf: O\'nu inkar edenlere, ateşten elbiseler kesilmiştir, başlarına da kaynar su dökülür de bununla karınlarındakiler ve deriler eritilir. Demir topuzlar da onlar içindir.'),
  ('tr.diyanet', 22, 20, 'İşte Rableri hakkında tartışmaya giren iki taraf: O\'nu inkar edenlere, ateşten elbiseler kesilmiştir, başlarına da kaynar su dökülür de bununla karınlarındakiler ve deriler eritilir. Demir topuzlar da onlar içindir.'),
  ('tr.diyanet', 22, 21, 'İşte Rableri hakkında tartışmaya giren iki taraf: O\'nu inkar edenlere, ateşten elbiseler kesilmiştir, başlarına da kaynar su dökülür de bununla karınlarındakiler ve deriler eritilir. Demir topuzlar da onlar içindir.'),
  ('tr.diyanet', 22, 22, 'Orada, uğradıkları gamdan ne zaman çıkmak isteseler her defasında oraya geri çevrilirler: "Yakıcı azabı tadın" denir.'),
  ('tr.diyanet', 22, 23, 'Doğrusu Allah, inanıp yararlı iş işleyenleri, içlerinden ırmaklar akan cennetlere koyar. Orada altın bilezikler ve inciler takınırlar. Oradaki elbiseleri de ipektendir.'),
  ('tr.diyanet', 22, 24, 'Bu kimseler, sözün güzelini işitecek duruma ulaştırılmışlar, övülmeğe layık olan Allah\'ın yoluna eriştirilmişlerdir.'),
  ('tr.diyanet', 22, 25, 'Doğrusu inkar edenleri, Allah\'ın yolundan, yerli ve yolcu bütün insanlar için eşit kılınan Mescidi Haram\'dan alıkoyanları ve orada zulm ile yanlış yola saptırmak isteyeni, can yakıcı bir azaba uğratırız.'),
  ('tr.diyanet', 22, 26, '"Bana hiçbir şeyi ortak koşma; tavaf edenler, orada kıyama duranlar, rüku edenler ve secdeye varanlar için Evimi temiz tut" diye İbrahim\'i Kabe\'nin yerine yerleştirmiştik.'),
  ('tr.diyanet', 22, 27, 'İnsanları hacca çağır; yürüyerek veya binekler üstünde uzak yollardan sana gelsinler.'),
  ('tr.diyanet', 22, 28, 'Taki kendi menfaatlerine şahid olsunlar; Allah\'ın onlara rızık olarak verdiği hayvanları belli günlerde kurban ederken O\'nun adını ansınlar. Siz de bunlardan yiyin, çaresiz kalmış yoksulu da doyurun.'),
  ('tr.diyanet', 22, 29, 'Sonra kirlerini giderip temizlensinler. Adaklarını yerine getirsinler. Kabe\'yi tavaf etsinler.'),
  ('tr.diyanet', 22, 30, 'İşte böyle. Kim Allah\'ın yasaklarına saygı gösterirse, bu Rabbinin katında kendi iyiliğinedir. (Haram olduğu) size okunanlar dışında kalan hayvanlar, size helal kılındı. O halde pis putlardan sakının; yalan sözden kaçının.'),
  ('tr.diyanet', 22, 31, 'Allah\'a ortak koşmaksızın O\'na yönelerek pis putlardan kaçının, yalan sözden çekinin. Allah\'a ortak koşan kimse, gökten düşüp de kuşların kaptığı veya rüzgarın bir uçuruma attığı şeye benzer.'),
  ('tr.diyanet', 22, 32, 'Bu böyledir; kişinin Allah\'ın nişanelerine hürmet göstermesi, kalblerin Allah\'a karşı gelmekten sakınmasındandır.'),
  ('tr.diyanet', 22, 33, 'Bu nişanelerde sizin için belli bir süreye kadar faydalar vardır. Sonra bunlar Beyti Atik\'de, Kabe\'de son bulurlar.'),
  ('tr.diyanet', 22, 34, 'Her ümmet için, Allah\'ın kendilerine rızk olarak verdiği kurbanlık hayvanların üzerlerine O\'nun adını anarak kurban kesmeyi meşru kıldık. Sizin Tanrınız tek bir Tanrı\'dır, O\'na teslim olun. Allah anıldığı zaman kalbleri titreyen, başlarına gelene sabreden, namaz kılan, kendilerine verdiğimiz rızıktan sarfeden ve Allah\'a gönül vermiş olan kimselere müjde et.'),
  ('tr.diyanet', 22, 35, 'Her ümmet için, Allah\'ın kendilerine rızk olarak verdiği kurbanlık hayvanların üzerlerine O\'nun adını anarak kurban kesmeyi meşru kıldık. Sizin Tanrınız tek bir Tanrı\'dır, O\'na teslim olun. Allah anıldığı zaman kalbleri titreyen, başlarına gelene sabreden, namaz kılan, kendilerine verdiğimiz rızıktan sarfeden ve Allah\'a gönül vermiş olan kimselere müjde et.'),
  ('tr.diyanet', 22, 36, 'İşte kurbanlık deve ve sığırları Allah\'ın size olan nişanelerinden kıldık. Onlarda sizin için hayır vardır. Bağlı halde keserken üzerlerine Allah\'ın adını anın. Yan üstü düşüp ölünce onlardan yiyin, isteyene de istemeyene de verin. Şükredersiniz diye onları böylece sizin buyruğunuza verdik.'),
  ('tr.diyanet', 22, 37, 'Bu hayvanların ne etleri ve ne de kanları Allah\'a ulaşacaktır. Allah\'a ulaşacak olan ancak sizin O\'nun için yaptığınız gösterişten uzak amel ve ibadettir. Size doğru yolu gösterdiğinden, Allah\'ı yüceltmeniz için onları böylece sizin buyruğunuza vermiştir. İyilik yapanlara müjde et.'),
  ('tr.diyanet', 22, 38, 'Allah şüphesiz inananları savunur, çünkü hainleri ve nankörleri hiç sevmez.'),
  ('tr.diyanet', 22, 39, 'Haksızlığa uğratılarak kendilerine savaş açılan kimselerin karşı koyup savaşmasına izin verilmiştir. Allah onlara yardım etmeğe elbette Kadir\'dir.'),
  ('tr.diyanet', 22, 40, 'Onlar haksız yere ve "Rabbimiz Allah\'tır" dediler diye yurtlarından çıkarılmışlardır. Allah insanların bir kısmını diğeriyle savmasaydı, manastırlar, kiliseler, havralar ve içinde Allah\'ın adı çok anılan camiler yıkılıp giderdi. And olsun ki, Allah\'a yardım edenlere O da yardım eder. Doğrusu Allah kuvvetlidir, güçlüdür.'),
  ('tr.diyanet', 22, 41, 'Onları biz yeryüzüne yerleştirirsek namaz kılarlar, zekat verirler, uygun olanı emrederler, fenalığı yasak ederler. İşlerin sonucu Allah\'a aittir.'),
  ('tr.diyanet', 22, 42, 'Seni yalancı sayıyorlarsa bil ki, onlardan önce Nuh milleti, Ad, Semud, İbrahim milleti, Lut milleti ve Medyen halkı da peygamberlerini yalancı saymış ve Musa da yalanlanmıştı. Ama Ben, kafirlere önce mehil verdim, sonra da onları yakalayıverdim; Beni tanımamak nasılmış görsünler.'),
  ('tr.diyanet', 22, 43, 'Seni yalancı sayıyorlarsa bil ki, onlardan önce Nuh milleti, Ad, Semud, İbrahim milleti, Lut milleti ve Medyen halkı da peygamberlerini yalancı saymış ve Musa da yalanlanmıştı. Ama Ben, kafirlere önce mehil verdim, sonra da onları yakalayıverdim; Beni tanımamak nasılmış görsünler.'),
  ('tr.diyanet', 22, 44, 'Seni yalancı sayıyorlarsa bil ki, onlardan önce Nuh milleti, Ad, Semud, İbrahim milleti, Lut milleti ve Medyen halkı da peygamberlerini yalancı saymış ve Musa da yalanlanmıştı. Ama Ben, kafirlere önce mehil verdim, sonra da onları yakalayıverdim; Beni tanımamak nasılmış görsünler.'),
  ('tr.diyanet', 22, 45, 'Nice kasabaların halkını haksızlık yaparken yok ettik. Artık çatıları çökmüş, kuyuları metruk, sarayları bomboş kalmıştır.'),
  ('tr.diyanet', 22, 46, 'Yeryüzünde dolaşmıyorlar mı ki, orada olanları akledecek kalbleri, işitecek kulakları olsun. Ama yalnız gözler kör olmaz, fakat göğüslerde olan kalbler de körleşir.'),
  ('tr.diyanet', 22, 47, 'Senden, başlarına acele azap getirmeni istiyorlar. Allah sözünden asla caymayacaktır. Rabbinin katında bir gün, saydıklarınızdan bin yıl gibidir.'),
  ('tr.diyanet', 22, 48, 'Nice kasabalara, haksız oldukları halde, mehil vermiştim; sonunda onları yakalayıverdim. Dönüş ancak Bana\'dır.'),
  ('tr.diyanet', 22, 49, '"Ey insanlar! Ben sizin için ancak apaçık bir uyarıcıyım" de.'),
  ('tr.diyanet', 22, 50, 'Cömertçe verilmiş rızık ve mağfiret, inanan ve yararlı iş işleyenleredir.'),
  ('tr.diyanet', 22, 51, 'Ayetlerimizi tartışarak bozmağa uğraşanlar, işte onlar cehennemliklerdir.'),
  ('tr.diyanet', 22, 52, 'Senden önce gönderdiğimiz hiçbir resul ve nebi yoktur ki, birşeyi arzuladığı zaman, şeytan onun arzusuna vesvese karıştırmamış olsun. Fakat Allah, şeytanın attığını derhal iptal eder, sonra kendi ayetlerini sağlamlaştırır. Allah bilendir, hüküm ve hikmet sahibidir.'),
  ('tr.diyanet', 22, 53, '/. Allah şeytanın karıştırdığını, kalblerinde hastalık bulunan ve kalbleri kaskatı olan kimseleri sınamayı vesile kılar. Zalimler şüphesiz derin bir ayrılık içindedirler.'),
  ('tr.diyanet', 22, 54, 'Bu, kendilerine ilim verilenlerin Kuran\'ın, senin Rabbin\'den bir gerçek olduğunu bilip de ona inanmaları ve gönüllerini bağlamaları içindir. Allah inananları şüphesiz doğru yola eriştirir.'),
  ('tr.diyanet', 22, 55, 'İnkar edenler, ceza saati kendilerine ansızın gelene veya gecesi olmayan günün azabı çatana kadar Kuran\'dan şüphe etmekte devam ederler.'),
  ('tr.diyanet', 22, 56, 'İşte o gün hükümranlık Allah\'ındır. O aralarında hükmeder. İnanıp yararlı iş işleyenler nimet cennetlerindedirler.'),
  ('tr.diyanet', 22, 57, 'İnkar edenler, ayetlerimizi yalan sayan kimseler, işte onlar için hakir düşüren azap vardır.'),
  ('tr.diyanet', 22, 58, 'Allah yolunda hicret edenlere, sonra öldürülen veya ölenlere Allah, elbette onlara güzel bir rızık verecektir. Rızık verenlerin en hayırlısı yalnız Allah\'tır.'),
  ('tr.diyanet', 22, 59, 'And olsun ki, onları hoşnut olacakları bir yere koyar. Şüphesiz Allah bilendir, Halim\'dir.'),
  ('tr.diyanet', 22, 60, 'Bu böyledir; kim kendisine verilen kadar ceza verirse ve kendisine yine de saldırılırsa, Allah ona, and olsun ki yardım edecektir. Allah şüphesiz, affeder ve bağışlar.'),
  ('tr.diyanet', 22, 61, 'Böyledir; Allah geceyi gündüze katar, gündüzü de geceye katar ve Allah şüphesiz işitir ve görür.'),
  ('tr.diyanet', 22, 62, 'Keza Hak yalnız Allah\'tır; O\'nu bırakıp taptıkları sadece batıldır. Doğrusu Allah yücedir büyüktür.'),
  ('tr.diyanet', 22, 63, 'Allah\'ın gökten indirdiği su ile yerin yemyeşil olduğunu görmez misin? Doğrusu Allah Latif\'dir, haberdardır.'),
  ('tr.diyanet', 22, 64, 'Göklerde olanlar, yerde olanlar O\'nundur. Doğrusu Allah müstağnidir, övülmeğe layık olandır.'),
  ('tr.diyanet', 22, 65, 'Allah\'ın yerde olanları ve emriyle denizlerde yürüyen gemileri buyruğunuz altına vermiş olduğunu; buyruğu olmaksızın yere düşmemesi için göğü O\'nun tuttuğunu görmez misin? Doğrusu Allah insanlara karşı şefkatli ve merhametli olandır.'),
  ('tr.diyanet', 22, 66, 'Sizi dirilten, sonra öldürecek sonra yine diriltecek olan O\'dur. İnsan gerçekten pek nankördür.'),
  ('tr.diyanet', 22, 67, 'Her ümmete, yerine getirmeleri gerekli ibadetler koyduk. Öyleyse, bu konuda seninle çekişmelerine fırsat verme; Rabbine davet et, sen şüphesiz doğru yol üzerindesin. Seninle tartışırlarsa: "Allah yaptığınızı çok iyi bilir; ayrılığa düştüğünüz şeyler hakkında, kıyamet günü aranızda Allah hükmedecektir" de.'),
  ('tr.diyanet', 22, 68, 'Her ümmete, yerine getirmeleri gerekli ibadetler koyduk. Öyleyse, bu konuda seninle çekişmelerine fırsat verme; Rabbine davet et, sen şüphesiz doğru yol üzerindesin. Seninle tartışırlarsa: "Allah yaptığınızı çok iyi bilir; ayrılığa düştüğünüz şeyler hakkında, kıyamet günü aranızda Allah hükmedecektir" de.'),
  ('tr.diyanet', 22, 69, 'Her ümmete, yerine getirmeleri gerekli ibadetler koyduk. Öyleyse, bu konuda seninle çekişmelerine fırsat verme; Rabbine davet et, sen şüphesiz doğru yol üzerindesin. Seninle tartışırlarsa: "Allah yaptığınızı çok iyi bilir; ayrılığa düştüğünüz şeyler hakkında, kıyamet günü aranızda Allah hükmedecektir" de.'),
  ('tr.diyanet', 22, 70, 'Gökte ve yerde olanı Allah\'ın bildiğini bilmez misin? Bunlar hiç şüphesiz Kitap\'dadır ve şüphesiz bunlar Allah\'a kolaydır.'),
  ('tr.diyanet', 22, 71, 'Onlar Allah\'ı bırakıp da O\'nun, haklarında hiçbir delil indirmediği, kendilerinde de bir bilgi olmayan şeylere taparlar. Zulmedenlerin yardımcısı olmaz.'),
  ('tr.diyanet', 22, 72, 'Onlara ayetlerimiz apaçık olarak okunduğu zaman, inkar edenlerin yüzlerinden inkarlarını anlarsın. Nerdeyse, kendilerine ayetlerimizi okuyanlara saldıracaklar. De ki: "Size bundan daha fenasını haber vereyim mi? Allah\'ın inkarcılara vadettiği ateş! Ne kötü bir dönüştür!..'),
  ('tr.diyanet', 22, 73, 'Ey insanlar! Bir misal verilmektedir, şimdi onu dinleyin: Sizlerin Allah\'ı bırakıp taptıklarınız bir araya gelseler, bir sinek bile yaratamıyacaklardır. Sinek onlardan bir şey kapsa, onu kurtaramazlar; isteyen de, istenen de aciz!'),
  ('tr.diyanet', 22, 74, 'Allah\'ı gereği gibi değerlendiremediler. Doğrusu Allah kuvvetlidir, güçlüdür.'),
  ('tr.diyanet', 22, 75, 'Allah meleklerden ve insanlardan peygamberler seçer. Doğrusu Allah işitir ve görür.'),
  ('tr.diyanet', 22, 76, 'O, geçmişlerini geleceklerini bilir. Bütün işler Allah\'a döner.'),
  ('tr.diyanet', 22, 77, 'Ey inananlar! Rüku edin, secdeye varın, Rabbiniz\'e kulluk edin, iyilik yapın ki saadete erişesiniz.'),
  ('tr.diyanet', 22, 78, 'Allah uğrunda gereği gibi cihat edin. O, sizi seçmiş, babanız İbrahim\'in yolu olan dinde sizin için bir zorluk kılmamıştır. Daha önce ve Kuran\'da, peygamberin size şahit olması, sizin de insanlara şahit olmanız için size müslüman adını veren O\'dur. Artık, namaz kılın, zekat verin, Allah\'a sarılın. O sizin sahibinizdir. Ne güzel sahip ve ne güzel yardımcıdır!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 22, 1, 'Hai manusia, bertakwalah kepada Tuhanmu; sesungguhnya kegoncangan hari kiamat itu adalah suatu kejadian yang sangat besar (dahsyat).'),
  ('id.indonesian', 22, 2, '(Ingatlah) pada hari (ketika) kamu melihat kegoncangan itu, lalailah semua wanita yang menyusui anaknya dari anak yang disusuinya dan gugurlah kandungan segala wanita yang hamil, dan kamu lihat manusia dalam keadaan mabuk, padahal sebenarnya mereka tidak mabuk, akan tetapi azab Allah itu sangat kerasnya.'),
  ('id.indonesian', 22, 3, 'Di antara manusia ada orang yang membantah tentang Allah tanpa ilmu pengetahuan dan mengikuti setiap syaitan yang jahat,'),
  ('id.indonesian', 22, 4, 'yang telah ditetapkan terhadap syaitan itu, bahwa barangsiapa yang berkawan dengan dia, tentu dia akan menyesatkannya, dan membawanya ke azab neraka.'),
  ('id.indonesian', 22, 5, 'Hai manusia, jika kamu dalam keraguan tentang kebangkitan (dari kubur), maka (ketahuilah) sesungguhnya Kami telah menjadikan kamu dari tanah, kemudian dari setetes mani, kemudian dari segumpal darah, kemudian dari segumpal daging yang sempurna kejadiannya dan yang tidak sempurna, agar Kami jelaskan kepada kamu dan Kami tetapkan dalam rahim, apa yang Kami kehendaki sampai waktu yang sudah ditentukan, kemudian Kami keluarkan kamu sebagai bayi, kemudian (dengan berangsur-angsur) kamu sampailah kepada kedewasaan, dan di antara kamu ada yang diwafatkan dan (adapula) di antara kamu yang dipanjangkan umurnya sampai pikun, supaya dia tidak mengetahui lagi sesuatupun yang dahulunya telah diketahuinya. Dan kamu lihat bumi ini kering, kemudian apabila telah Kami turunkan air di atasnya, hiduplah bumi itu dan suburlah dan menumbuhkan berbagai macam tumbuh-tumbuhan yang indah.'),
  ('id.indonesian', 22, 6, 'Yang demikian itu, karena sesungguhnya Allah, Dialah yang haq dan sesungguhnya Dialah yang menghidupkan segala yang mati dan sesungguhnya Allah Maha Kuasa atas segala sesuatu,'),
  ('id.indonesian', 22, 7, 'dan sesungguhnya hari kiamat itu pastilah datang, tak ada keraguan padanya; dan bahwasanya Allah membangkitkan semua orang di dalam kubur.'),
  ('id.indonesian', 22, 8, 'Dan di antara manusia ada orang-orang yang membantah tentang Allah tanpa ilmu pengetahuan, tanpa petunjuk dan tanpa kitab (wahyu) yang bercahaya,'),
  ('id.indonesian', 22, 9, 'dengan memalingkan lambungnya untuk menyesatkan manusia dari jalan Allah. Ia mendapat kehinaan di dunia dan dihari kiamat Kami merasakan kepadanya azab neraka yang membakar.'),
  ('id.indonesian', 22, 10, '(Akan dikatakan kepadanya): "Yang demikian itu, adalah disebabkan perbuatan yang dikerjakan oleh kedua tangan kamu dahulu dan sesungguhnya Allah sekali-kali bukanlah penganiaya hamba-hamba-Nya".'),
  ('id.indonesian', 22, 11, 'Dan di antara manusia ada orang yang menyembah Allah dengan berada di tepi; maka jika ia memperoleh kebajikan, tetaplah ia dalam keadaan itu, dan jika ia ditimpa oleh suatu bencana, berbaliklah ia ke belakang. Rugilah ia di dunia dan di akhirat. Yang demikian itu adalah kerugian yang nyata.'),
  ('id.indonesian', 22, 12, 'Ia menyeru selain Allah, sesuatu yang tidak dapat memberi mudharat dan tidak (pula) memberi manfaat kepadanya. Yang demikian itu adalah kesesatan yang jauh.'),
  ('id.indonesian', 22, 13, 'Ia menyeru sesuatu yang sebenarnya mudharatnya lebih dekat dari manfaatnya. Sesungguhnya yang diserunya itu adalah sejahat-jahat kawan.'),
  ('id.indonesian', 22, 14, 'Sesungguhnya Allah memasukkan orang-orang yang beriman dan mengerjakan amal yang saleh ke dalam surga-surga yang di bawahnya mengalir sungai-sungai. Sesungguhnya Allah berbuat apa yang Dia kehendaki.'),
  ('id.indonesian', 22, 15, 'Barangsiapa yang menyangka bahwa Allah sekali-kali tiada menolongnya (Muhammad) di dunia dan akhirat, maka hendaklah ia merentangkan tali ke langit, kemudian hendaklah ia melaluinya, kemudian hendaklah ia pikirkan apakah tipu dayanya itu dapat melenyapkan apa yang menyakitkan hatinya.'),
  ('id.indonesian', 22, 16, 'Dan demikianlah Kami telah menurunkan Al Quran yang merupakan ayat-ayat yang nyata, dan bahwasanya Allah memberikan petunjuk kepada siapa yang Dia kehendaki.'),
  ('id.indonesian', 22, 17, 'Sesungguhnya orang-orang yang beriman, orang-orang Yahudi, orang-orang Shaabi-iin orang-orang Nasrani, orang-orang Majusi dan orang-orang musyrik, Allah akan memberi keputusan di antara mereka pada hari kiamat. Sesungguhnya Allah menyaksikan segala sesuatu.'),
  ('id.indonesian', 22, 18, 'Apakah kamu tiada mengetahui, bahwa kepada Allah bersujud apa yang ada di langit, di bumi, matahari, bulan, bintang, gunung, pohon-pohonan, binatang-binatang yang melata dan sebagian besar daripada manusia? Dan banyak di antara manusia yang telah ditetapkan azab atasnya. Dan barangsiapa yang dihinakan Allah maka tidak seorangpun yang memuliakannya. Sesungguhnya Allah berbuat apa yang Dia kehendaki.'),
  ('id.indonesian', 22, 19, 'Inilah dua golongan (golongan mukmin dan golongan kafir) yang bertengkar, mereka saling bertengkar mengenai Tuhan mereka. Maka orang kafir akan dibuatkan untuk mereka pakaian-pakaian dari api neraka. Disiramkan air yang sedang mendidih ke atas kepala mereka.'),
  ('id.indonesian', 22, 20, 'Dengan air itu dihancur luluhkan segala apa yang ada dalam perut mereka dan juga kulit (mereka).'),
  ('id.indonesian', 22, 21, 'Dan untuk mereka cambuk-cambuk dari besi.'),
  ('id.indonesian', 22, 22, 'Setiap kali mereka hendak ke luar dari neraka lantaran kesengsaraan mereka, niscaya mereka dikembalikan ke dalamnya. (Kepada mereka dikatakan), "Rasailah azab yang membakar ini".'),
  ('id.indonesian', 22, 23, 'Sesungguhnya Allah memasukkan orang-orang beriman dan mengerjakan amal yang saleh ke dalam surga-surga yang di bawahnya mengalir sungai-sungai. Di surga itu mereka diberi perhiasan dengan gelang-gelang dari emas dan mutiara, dan pakaian mereka adalah sutera.'),
  ('id.indonesian', 22, 24, 'Dan mereka diberi petunjuk kepada ucapan-ucapan yang baik dan ditunjuki (pula) kepada jalan (Allah) yang terpuji.'),
  ('id.indonesian', 22, 25, 'Sesungguhnya orang-orang yang kafir dan menghalangi manusia dari jalan Allah dan Masjidilharam yang telah Kami jadikan untuk semua manusia, baik yang bermukim di situ maupun di padang pasir dan siapa yang bermaksud di dalamnya melakukan kejahatan secara zalim, niscaya akan Kami rasakan kepadanya sebahagian siksa yang pedih.'),
  ('id.indonesian', 22, 26, 'Dan (ingatlah), ketika Kami memberikan tempat kepada Ibrahim di tempat Baitullah (dengan mengatakan): "Janganlah kamu memperserikatkan sesuatupun dengan Aku dan sucikanlah rumah-Ku ini bagi orang-orang yang thawaf, dan orang-orang yang beribadat dan orang-orang yang ruku\' dan sujud.'),
  ('id.indonesian', 22, 27, 'Dan berserulah kepada manusia untuk mengerjakan haji, niscaya mereka akan datang kepadamu dengan berjalan kaki, dan mengendarai unta yang kurus yang datang dari segenap penjuru yang jauh,'),
  ('id.indonesian', 22, 28, 'supaya mereka menyaksikan berbagai manfaat bagi mereka dan supaya mereka menyebut nama Allah pada hari yang telah ditentukan atas rezeki yang Allah telah berikan kepada mereka berupa binatang ternak. Maka makanlah sebahagian daripadanya dan (sebahagian lagi) berikanlah untuk dimakan orang-orang yang sengsara dan fakir.'),
  ('id.indonesian', 22, 29, 'Kemudian, hendaklah mereka menghilangkan kotoran yang ada pada badan mereka dan hendaklah mereka menyempurnakan nazar-nazar mereka dan hendaklah mereka melakukan melakukan thawaf sekeliling rumah yang tua itu (Baitullah).'),
  ('id.indonesian', 22, 30, 'Demikianlah (perintah Allah). Dan barangsiapa mengagungkan apa-apa yang terhormat di sisi Allah maka itu adalah lebih baik baginya di sisi Tuhannya. Dan telah dihalalkan bagi kamu semua binatang ternak, terkecuali yang diterangkan kepadamu keharamannya, maka jauhilah olehmu berhala-berhala yang najis itu dan jauhilah perkataan-perkataan dusta.'),
  ('id.indonesian', 22, 31, 'dengan ikhlas kepada Allah, tidak mempersekutukan sesuatu dengan Dia. Barangsiapa mempersekutukan sesuatu dengan Allah, maka adalah ia seolah-olah jatuh dari langit lalu disambar oleh burung, atau diterbangkan angin ke tempat yang jauh.'),
  ('id.indonesian', 22, 32, 'Demikianlah (perintah Allah). Dan barangsiapa mengagungkan syi\'ar-syi\'ar Allah, maka sesungguhnya itu timbul dari ketakwaan hati.'),
  ('id.indonesian', 22, 33, 'Bagi kamu pada binatang-binatang hadyu itu ada beberapa manfaat, sampai kepada waktu yang ditentukan, kemudian tempat wajib (serta akhir masa) menyembelihnya ialah setelah sampai ke Baitul Atiq (Baitullah).'),
  ('id.indonesian', 22, 34, 'Dan bagi tiap-tiap umat telah Kami syariatkan penyembelihan (kurban), supaya mereka menyebut nama Allah terhadap binatang ternak yang telah direzekikan Allah kepada mereka, maka Tuhanmu ialah Tuhan Yang Maha Esa, karena itu berserah dirilah kamu kepada-Nya. Dan berilah kabar gembira kepada orang-orang yang tunduk patuh (kepada Allah),'),
  ('id.indonesian', 22, 35, '(yaitu) orang-orang yang apabila disebut nama Allah gemetarlah hati mereka, orang-orang yang sabar terhadap apa yang menimpa mereka, orang-orang yang mendirikan sembahyang dan orang-orang yang menafkahkan sebagian dari apa yang telah Kami rezekikan kepada mereka.'),
  ('id.indonesian', 22, 36, 'Dan telah Kami jadikan untuk kamu unta-unta itu sebahagian dari syi\'ar Allah, kamu memperoleh kebaikan yang banyak padanya, maka sebutlah olehmu nama Allah ketika kamu menyembelihnya dalam keadaan berdiri (dan telah terikat). Kemudian apabila telah roboh (mati), maka makanlah sebahagiannya dan beri makanlah orang yang rela dengan apa yang ada padanya (yang tidak meminta-minta) dan orang yang meminta. Demikianlah Kami telah menundukkan untua-unta itu kepada kamu, mudah-mudahan kamu bersyukur.'),
  ('id.indonesian', 22, 37, 'Daging-daging unta dan darahnya itu sekali-kali tidak dapat mencapai (keridhaan) Allah, tetapi ketakwaan dari kamulah yang dapat mencapainya. Demikianlah Allah telah menundukkannya untuk kamu supaya kamu mengagungkan Allah terhadap hidayah-Nya kepada kamu. Dan berilah kabar gembira kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 22, 38, 'Sesungguhnya Allah membela orang-orang yang telah beriman. Sesungguhnya Allah tidak menyukai tiap-tiap orang yang berkhianat lagi mengingkari nikmat.'),
  ('id.indonesian', 22, 39, 'Telah diizinkan (berperang) bagi orang-orang yang diperangi, karena sesungguhnya mereka telah dianiaya. Dan sesungguhnya Allah, benar-benar Maha Kuasa menolong mereka itu,'),
  ('id.indonesian', 22, 40, '(yaitu) orang-orang yang telah diusir dari kampung halaman mereka tanpa alasan yang benar, kecuali karena mereka berkata: "Tuhan kami hanyalah Allah". Dan sekiranya Allah tiada menolak (keganasan) sebagian manusia dengan sebagian yang lain, tentulah telah dirobohkan biara-biara Nasrani, gereja-gereja, rumah-rumah ibadat orang Yahudi dan masjid-masjid, yang di dalamnya banyak disebut nama Allah. Sesungguhnya Allah pasti menolong orang yang menolong (agama)-Nya. Sesungguhnya Allah benar-benar Maha Kuat lagi Maha Perkasa,'),
  ('id.indonesian', 22, 41, '(yaitu) orang-orang yang jika Kami teguhkan kedudukan mereka di muka bumi niscaya mereka mendirikan sembahyang, menunaikan zakat, menyuruh berbuat ma\'ruf dan mencegah dari perbuatan yang mungkar; dan kepada Allah-lah kembali segala urusan.'),
  ('id.indonesian', 22, 42, 'Dan jika mereka (orang-orang musyrik) mendustakan kamu, maka sesungguhnya telah mendustakan juga sebelum mereka kaum Nuh, \'Aad dan Tsamud,'),
  ('id.indonesian', 22, 43, 'dan kaum Ibrahim dan kaum Luth,'),
  ('id.indonesian', 22, 44, 'dan penduduk Madyan, dan telah didustakan Musa, lalu Aku tangguhkan (azab-Ku) untuk orang-orang kafir, kemudian Aku azab mereka, maka (lihatlah) bagaimana besarnya kebencian-Ku (kepada mereka itu).'),
  ('id.indonesian', 22, 45, 'Berapalah banyaknya kota yang Kami telah membinasakannya, yang penduduknya dalam keadaan zalim, maka (tembok-tembok) kota itu roboh menutupi atap-atapnya dan (berapa banyak pula) sumur yang telah ditinggalkan dan istana yang tinggi,'),
  ('id.indonesian', 22, 46, 'maka apakah mereka tidak berjalan di muka bumi, lalu mereka mempunyai hati yang dengan itu mereka dapat memahami atau mempunyai telinga yang dengan itu mereka dapat mendengar? Karena sesungguhnya bukanlah mata itu yang buta, tetapi yang buta, ialah hati yang di dalam dada.'),
  ('id.indonesian', 22, 47, 'Dan mereka meminta kepadamu agar azab itu disegerakan, padahal Allah sekali-kali tidak akan menyalahi janji-Nya. Sesungguhnya sehari disisi Tuhanmu adalah seperti seribu tahun menurut perhitunganmu.'),
  ('id.indonesian', 22, 48, 'Dan berapalah banyaknya kota yang Aku tangguhkan (azab-Ku) kepadanya, yang penduduknya berbuat zalim, kemudian Aku azab mereka, dan hanya kepada-Kulah kembalinya (segala sesuatu).'),
  ('id.indonesian', 22, 49, 'Katakanlah: "Hai manusia, sesungguhnya aku adalah seorang pemberi peringatan yang nyata kepada kamu".'),
  ('id.indonesian', 22, 50, 'Maka orang-orang yang beriman dan beramal saleh, bagi mereka ampunan dan rezeki yang mulia.'),
  ('id.indonesian', 22, 51, 'Dan orang-orang yang berusaha dengan maksud menentang ayat-ayat Kami dengan melemahkan (kemauan untuk beriman); mereka itu adalah penghuni-penghuni neraka.'),
  ('id.indonesian', 22, 52, 'Dan Kami tidak mengutus sebelum kamu seorang rasulpun dan tidak (pula) seorang nabi, melainkan apabila ia mempunyai sesuatu keinginan, syaitanpun memasukkan godaan-godaan terhadap keinginan itu, Allah menghilangkan apa yang dimasukkan oleh syaitan itu, dan Allah menguatkan ayat-ayat-Nya. Dan Allah Maha Mengetahui lagi Maha Bijaksana,'),
  ('id.indonesian', 22, 53, 'agar Dia menjadikan apa yang dimasukkan oleh syaitan itu, sebagai cobaan bagi orang-orang yang di dalam hatinya ada penyakit dan yang kasar hatinya. Dan sesungguhnya orang-orang yang zalim itu, benar-benar dalam permusuhan yang sangat,'),
  ('id.indonesian', 22, 54, 'dan agar orang-orang yang telah diberi ilmu, meyakini bahwasanya Al Quran itulah yang hak dari Tuhan-mu lalu mereka beriman dan tunduk hati mereka kepadanya dan sesungguhnya Allah adalah Pemberi Petunjuk bagi orang-orang yang beriman kepada jalan yang lurus.'),
  ('id.indonesian', 22, 55, 'Dan senantiasalah orang-orang kafir itu berada dalam keragu-raguan terhadap Al Quran, hingga datang kepada mereka saat (kematiannya) dengan tiba-tiba atau datang kepada mereka azab hari kiamat.'),
  ('id.indonesian', 22, 56, 'Kekuasaan di hari itu ada pada Allah, Dia memberi keputusan di antara mereka. Maka orang-orang yang beriman dan beramal saleh adalah di dalam surga yang penuh kenikmatan.'),
  ('id.indonesian', 22, 57, 'Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, maka bagi mereka azab yang menghinakan.'),
  ('id.indonesian', 22, 58, 'Dan orang-orang yang berhijrah di jalan Allah, kemudian mereka di bunuh atau mati, benar-benar Allah akan memberikan kepada mereka rezeki yang baik (surga). Dan sesungguhnya Allah adalah sebaik-baik pemberi rezeki.'),
  ('id.indonesian', 22, 59, 'Sesungguhnya Allah akan memasukkan mereka ke dalam suatu tempat (surga) yang mereka menyukainya. Dan sesungguhnya Allah Maha mengetahui lagi Maha Penyantun.'),
  ('id.indonesian', 22, 60, 'Demikianlah, dan barangsiapa membalas seimbang dengan penganiayaan yang pernah ia derita kemudian ia dianiaya (lagi), pasti Allah akan menolongnya. Sesungguhnya Allah benar-benar Maha Pemaaf lagi Maha Pengampun.'),
  ('id.indonesian', 22, 61, 'Yang demikian itu, adalah karena sesungguhnya Allah (kuasa) memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam dan bahwasanya Allah Maha Mendengar lagi Maha Melihat.'),
  ('id.indonesian', 22, 62, '(Kuasa Allah) yang demikian itu, adalah karena sesungguhnya Allah, Dialah (Tuhan) Yang Haq dan sesungguhnya apa saja yang mereka seru selain dari Allah, itulah yang batil, dan sesungguhnya Allah, Dialah Yang Maha Tinggi lagi Maha Besar.'),
  ('id.indonesian', 22, 63, 'Apakah kamu tiada melihat, bahwasanya Allah menurunkan air dari langit, lalu jadilah bumi itu hijau? Sesungguhnya Allah Maha Halus lagi Maha Mengetahui.'),
  ('id.indonesian', 22, 64, 'Kepunyaan Allah-lah segala yang ada di langit dan segala yang ada di bumi. Dan sesungguhnya Allah benar-benar Maha Kaya lagi Maha Terpuji.'),
  ('id.indonesian', 22, 65, 'Apakah kamu tiada melihat bahwasanya Allah menundukkan bagimu apa yang ada di bumi dan bahtera yang berlayar di lautan dengan perintah-Nya. Dan Dia menahan (benda-benda) langit jatuh ke bumi, melainkan dengan izin-Nya? Sesungguhnya Allah benar-benar Maha Pengasih lagi Maha Penyayang kepada Manusia.'),
  ('id.indonesian', 22, 66, 'Dan Dialah Allah yang telah menghidupkan kamu, kemudian mematikan kamu, kemudian menghidupkan kamu (lagi), sesungguhnya manusia itu, benar-benar sangat mengingkari nikmat.'),
  ('id.indonesian', 22, 67, 'Bagi tiap-tiap umat telah Kami tetapkan syari\'at tertentu yang mereka lakukan, maka janganlah sekali-kali mereka membantah kamu dalam urusan (syari\'at) ini dan serulah kepada (agama) Tuhanmu. Sesungguhnya kamu benar-benar berada pada jalan yang lurus.'),
  ('id.indonesian', 22, 68, 'Dan jika mereka membantah kamu, maka katakanlah: "Allah lebih mengetahui tentang apa yang kamu kerjakan".'),
  ('id.indonesian', 22, 69, 'Allah akan mengadili di antara kamu pada hari kiamat tentang apa yang kamu dahulu selalu berselisih padanya.'),
  ('id.indonesian', 22, 70, 'Apakah kamu tidak mengetahui bahwa sesungguhnya Allah mengetahui apa saja yang ada di langit dan di bumi?; bahwasanya yang demikian itu terdapat dalam sebuah kitab (Lauh Mahfuzh). Sesungguhnya yang demikian itu amat mudah bagi Allah.'),
  ('id.indonesian', 22, 71, 'Dan mereka menyembah selain Allah, apa yang Allah tidak menurunkan keterangan tentang itu, dan apa yang mereka sendiri tiada mempunyai pengetahuan terhadapnya. Dan bagi orang-orang yang zalim sekali-kali tidak ada seorang penolongpun.'),
  ('id.indonesian', 22, 72, 'Dan apabila dibacakan di hadapan mereka ayat-ayat Kami yang terang, niscaya kamu melihat tanda-tanda keingkaran pada muka orang-orang yang kafir itu. Hampir-hampir mereka menyerang orang-orang yang membacakan ayat-ayat Kami di hadapan mereka. Katakanlah: "Apakah akan aku kabarkan kepadamu yang lebih buruk daripada itu, yaitu neraka?" Allah telah mengancamkannya kepada orang-orang yang kafir. Dan neraka itu adalah seburuk-buruknya tempat kembali.'),
  ('id.indonesian', 22, 73, 'Hai manusia, telah dibuat perumpamaan, maka dengarkanlah olehmu perumpamaan itu. Sesungguhnya segala yang kamu seru selain Allah sekali-kali tidak dapat menciptakan seekor lalatpun, walaupun mereka bersatu menciptakannya. Dan jika lalat itu merampas sesuatu dari mereka, tiadalah mereka dapat merebutnya kembali dari lalat itu. Amat lemahlah yang menyembah dan amat lemah (pulalah) yang disembah.'),
  ('id.indonesian', 22, 74, 'Mereka tidak mengenal Allah dengan sebenar-benarnya. Sesungguhnya Allah benar-benar Maha Kuat lagi Maha Perkasa.'),
  ('id.indonesian', 22, 75, 'Allah memilih utusan-utusan-(Nya) dari malaikat dan dari manusia; sesungguhnya Allah Maha Mendengar lagi Maha Melihat.'),
  ('id.indonesian', 22, 76, 'Allah mengetahui apa yang di hadapan mereka dan apa yang di belakang mereka. Dan hanya kepada Allah dikembalikan semua urusan.'),
  ('id.indonesian', 22, 77, 'Hai orang-orang yang beriman, ruku\'lah kamu, sujudlah kamu, sembahlah Tuhanmu dan perbuatlah kebajikan, supaya kamu mendapat kemenangan.'),
  ('id.indonesian', 22, 78, 'Dan berjihadlah kamu pada jalan Allah dengan jihad yang sebenar-benarnya. Dia telah memilih kamu dan Dia sekali-kali tidak menjadikan untuk kamu dalam agama suatu kesempitan. (Ikutilah) agama orang tuamu Ibrahim. Dia (Allah) telah menamai kamu sekalian orang-orang muslim dari dahulu, dan (begitu pula) dalam (Al Quran) ini, supaya Rasul itu menjadi saksi atas dirimu dan supaya kamu semua menjadi saksi atas segenap manusia, maka dirikanlah sembahyang, tunaikanlah zakat dan berpeganglah kamu pada tali Allah. Dia adalah Pelindungmu, maka Dialah sebaik-baik Pelindung dan sebaik-baik Penolong.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 23, 1, 'Certainly will the believers have succeeded:'),
  ('en.sahih', 23, 2, 'They who are during their prayer humbly submissive'),
  ('en.sahih', 23, 3, 'And they who turn away from ill speech'),
  ('en.sahih', 23, 4, 'And they who are observant of zakah'),
  ('en.sahih', 23, 5, 'And they who guard their private parts'),
  ('en.sahih', 23, 6, 'Except from their wives or those their right hands possess, for indeed, they will not be blamed -'),
  ('en.sahih', 23, 7, 'But whoever seeks beyond that, then those are the transgressors -'),
  ('en.sahih', 23, 8, 'And they who are to their trusts and their promises attentive'),
  ('en.sahih', 23, 9, 'And they who carefully maintain their prayers -'),
  ('en.sahih', 23, 10, 'Those are the inheritors'),
  ('en.sahih', 23, 11, 'Who will inherit al-Firdaus. They will abide therein eternally.'),
  ('en.sahih', 23, 12, 'And certainly did We create man from an extract of clay.'),
  ('en.sahih', 23, 13, 'Then We placed him as a sperm-drop in a firm lodging.'),
  ('en.sahih', 23, 14, 'Then We made the sperm-drop into a clinging clot, and We made the clot into a lump [of flesh], and We made [from] the lump, bones, and We covered the bones with flesh; then We developed him into another creation. So blessed is Allah, the best of creators.'),
  ('en.sahih', 23, 15, 'Then indeed, after that you are to die.'),
  ('en.sahih', 23, 16, 'Then indeed you, on the Day of Resurrection, will be resurrected.'),
  ('en.sahih', 23, 17, 'And We have created above you seven layered heavens, and never have We been of [Our] creation unaware.'),
  ('en.sahih', 23, 18, 'And We have sent down rain from the sky in a measured amount and settled it in the earth. And indeed, We are Able to take it away.'),
  ('en.sahih', 23, 19, 'And We brought forth for you thereby gardens of palm trees and grapevines in which for you are abundant fruits and from which you eat.'),
  ('en.sahih', 23, 20, 'And [We brought forth] a tree issuing from Mount Sinai which produces oil and food for those who eat.'),
  ('en.sahih', 23, 21, 'And indeed, for you in livestock is a lesson. We give you drink from that which is in their bellies, and for you in them are numerous benefits, and from them you eat.'),
  ('en.sahih', 23, 22, 'And upon them and on ships you are carried.'),
  ('en.sahih', 23, 23, 'And We had certainly sent Noah to his people, and he said, "O my people, worship Allah; you have no deity other than Him; then will you not fear Him?"'),
  ('en.sahih', 23, 24, 'But the eminent among those who disbelieved from his people said, "This is not but a man like yourselves who wishes to take precedence over you; and if Allah had willed [to send a messenger], He would have sent down angels. We have not heard of this among our forefathers.'),
  ('en.sahih', 23, 25, 'He is not but a man possessed with madness, so wait concerning him for a time."'),
  ('en.sahih', 23, 26, '[Noah] said, "My Lord, support me because they have denied me."'),
  ('en.sahih', 23, 27, 'So We inspired to him, "Construct the ship under Our observation, and Our inspiration, and when Our command comes and the oven overflows, put into the ship from each [creature] two mates and your family, except those for whom the decree [of destruction] has proceeded. And do not address Me concerning those who have wronged; indeed, they are to be drowned.'),
  ('en.sahih', 23, 28, 'And when you have boarded the ship, you and those with you, then say, \'Praise to Allah who has saved us from the wrongdoing people.\''),
  ('en.sahih', 23, 29, 'And say, \'My Lord, let me land at a blessed landing place, and You are the best to accommodate [us].\' "'),
  ('en.sahih', 23, 30, 'Indeed in that are signs, and indeed, We are ever testing [Our servants].'),
  ('en.sahih', 23, 31, 'Then We produced after them a generation of others.'),
  ('en.sahih', 23, 32, 'And We sent among them a messenger from themselves, [saying], "Worship Allah; you have no deity other than Him; then will you not fear Him?"'),
  ('en.sahih', 23, 33, 'And the eminent among his people who disbelieved and denied the meeting of the Hereafter while We had given them luxury in the worldly life said, "This is not but a man like yourselves. He eats of that from which you eat and drinks of what you drink.'),
  ('en.sahih', 23, 34, 'And if you should obey a man like yourselves, indeed, you would then be losers.'),
  ('en.sahih', 23, 35, 'Does he promise you that when you have died and become dust and bones that you will be brought forth [once more]?'),
  ('en.sahih', 23, 36, 'How far, how far, is that which you are promised.'),
  ('en.sahih', 23, 37, 'Life is not but our worldly life - we die and live, but we will not be resurrected.'),
  ('en.sahih', 23, 38, 'He is not but a man who has invented a lie about Allah, and we will not believe him."'),
  ('en.sahih', 23, 39, 'He said, "My Lord, support me because they have denied me."'),
  ('en.sahih', 23, 40, '[Allah] said, "After a little, they will surely become regretful."'),
  ('en.sahih', 23, 41, 'So the shriek seized them in truth, and We made them as [plant] stubble. Then away with the wrongdoing people.'),
  ('en.sahih', 23, 42, 'Then We produced after them other generations.'),
  ('en.sahih', 23, 43, 'No nation will precede its time [of termination], nor will they remain [thereafter].'),
  ('en.sahih', 23, 44, 'Then We sent Our messengers in succession. Every time there came to a nation its messenger, they denied him, so We made them follow one another [to destruction], and We made them narrations. So away with a people who do not believe.'),
  ('en.sahih', 23, 45, 'Then We sent Moses and his brother Aaron with Our signs and a clear authority'),
  ('en.sahih', 23, 46, 'To Pharaoh and his establishment, but they were arrogant and were a haughty people.'),
  ('en.sahih', 23, 47, 'They said, "Should we believe two men like ourselves while their people are for us in servitude?"'),
  ('en.sahih', 23, 48, 'So they denied them and were of those destroyed.'),
  ('en.sahih', 23, 49, 'And We certainly gave Moses the Scripture that perhaps they would be guided.'),
  ('en.sahih', 23, 50, 'And We made the son of Mary and his mother a sign and sheltered them within a high ground having level [areas] and flowing water.'),
  ('en.sahih', 23, 51, '[Allah said], "O messengers, eat from the good foods and work righteousness. Indeed, I, of what you do, am Knowing.'),
  ('en.sahih', 23, 52, 'And indeed this, your religion, is one religion, and I am your Lord, so fear Me."'),
  ('en.sahih', 23, 53, 'But the people divided their religion among them into sects - each faction, in what it has, rejoicing.'),
  ('en.sahih', 23, 54, 'So leave them in their confusion for a time.'),
  ('en.sahih', 23, 55, 'Do they think that what We extend to them of wealth and children'),
  ('en.sahih', 23, 56, 'Is [because] We hasten for them good things? Rather, they do not perceive.'),
  ('en.sahih', 23, 57, 'Indeed, they who are apprehensive from fear of their Lord'),
  ('en.sahih', 23, 58, 'And they who believe in the signs of their Lord'),
  ('en.sahih', 23, 59, 'And they who do not associate anything with their Lord'),
  ('en.sahih', 23, 60, 'And they who give what they give while their hearts are fearful because they will be returning to their Lord -'),
  ('en.sahih', 23, 61, 'It is those who hasten to good deeds, and they outstrip [others] therein.'),
  ('en.sahih', 23, 62, 'And We charge no soul except [with that within] its capacity, and with Us is a record which speaks with truth; and they will not be wronged.'),
  ('en.sahih', 23, 63, 'But their hearts are covered with confusion over this, and they have [evil] deeds besides disbelief which they are doing,'),
  ('en.sahih', 23, 64, 'Until when We seize their affluent ones with punishment, at once they are crying [to Allah] for help.'),
  ('en.sahih', 23, 65, 'Do not cry out today. Indeed, by Us you will not be helped.'),
  ('en.sahih', 23, 66, 'My verses had already been recited to you, but you were turning back on your heels'),
  ('en.sahih', 23, 67, 'In arrogance regarding it, conversing by night, speaking evil.'),
  ('en.sahih', 23, 68, 'Then have they not reflected over the Qur\'an, or has there come to them that which had not come to their forefathers?'),
  ('en.sahih', 23, 69, 'Or did they not know their Messenger, so they are toward him disacknowledging?'),
  ('en.sahih', 23, 70, 'Or do they say, "In him is madness?" Rather, he brought them the truth, but most of them, to the truth, are averse.'),
  ('en.sahih', 23, 71, 'But if the Truth had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away.'),
  ('en.sahih', 23, 72, 'Or do you, [O Muhammad], ask them for payment? But the reward of your Lord is best, and He is the best of providers.'),
  ('en.sahih', 23, 73, 'And indeed, you invite them to a straight path.'),
  ('en.sahih', 23, 74, 'But indeed, those who do not believe in the Hereafter are deviating from the path.'),
  ('en.sahih', 23, 75, 'And even if We gave them mercy and removed what was upon them of affliction, they would persist in their transgression, wandering blindly.'),
  ('en.sahih', 23, 76, 'And We had gripped them with suffering [as a warning], but they did not yield to their Lord, nor did they humbly supplicate, [and will continue thus]'),
  ('en.sahih', 23, 77, 'Until when We have opened before them a door of severe punishment, immediately they will be therein in despair.'),
  ('en.sahih', 23, 78, 'And it is He who produced for you hearing and vision and hearts; little are you grateful.'),
  ('en.sahih', 23, 79, 'And it is He who has multiplied you throughout the earth, and to Him you will be gathered.'),
  ('en.sahih', 23, 80, 'And it is He who gives life and causes death, and His is the alternation of the night and the day. Then will you not reason?'),
  ('en.sahih', 23, 81, 'Rather, they say like what the former peoples said.'),
  ('en.sahih', 23, 82, 'They said, "When we have died and become dust and bones, are we indeed to be resurrected?'),
  ('en.sahih', 23, 83, 'We have been promised this, we and our forefathers, before; this is not but legends of the former peoples."'),
  ('en.sahih', 23, 84, 'Say, [O Muhammad], "To whom belongs the earth and whoever is in it, if you should know?"'),
  ('en.sahih', 23, 85, 'They will say, "To Allah." Say, "Then will you not remember?"'),
  ('en.sahih', 23, 86, 'Say, "Who is Lord of the seven heavens and Lord of the Great Throne?"'),
  ('en.sahih', 23, 87, 'They will say, "[They belong] to Allah." Say, "Then will you not fear Him?"'),
  ('en.sahih', 23, 88, 'Say, "In whose hand is the realm of all things - and He protects while none can protect against Him - if you should know?"'),
  ('en.sahih', 23, 89, 'They will say, "[All belongs] to Allah." Say, "Then how are you deluded?"'),
  ('en.sahih', 23, 90, 'Rather, We have brought them the truth, and indeed they are liars.'),
  ('en.sahih', 23, 91, 'Allah has not taken any son, nor has there ever been with Him any deity. [If there had been], then each deity would have taken what it created, and some of them would have sought to overcome others. Exalted is Allah above what they describe [concerning Him].'),
  ('en.sahih', 23, 92, '[He is] Knower of the unseen and the witnessed, so high is He above what they associate [with Him].'),
  ('en.sahih', 23, 93, 'Say, [O Muhammad], "My Lord, if You should show me that which they are promised,'),
  ('en.sahih', 23, 94, 'My Lord, then do not place me among the wrongdoing people."'),
  ('en.sahih', 23, 95, 'And indeed, We are able to show you what We have promised them.'),
  ('en.sahih', 23, 96, 'Repel, by [means of] what is best, [their] evil. We are most knowing of what they describe.'),
  ('en.sahih', 23, 97, 'And say, "My Lord, I seek refuge in You from the incitements of the devils,'),
  ('en.sahih', 23, 98, 'And I seek refuge in You, my Lord, lest they be present with me."'),
  ('en.sahih', 23, 99, '[For such is the state of the disbelievers], until, when death comes to one of them, he says, "My Lord, send me back'),
  ('en.sahih', 23, 100, 'That I might do righteousness in that which I left behind." No! It is only a word he is saying; and behind them is a barrier until the Day they are resurrected.'),
  ('en.sahih', 23, 101, 'So when the Horn is blown, no relationship will there be among them that Day, nor will they ask about one another.'),
  ('en.sahih', 23, 102, 'And those whose scales are heavy [with good deeds] - it is they who are the successful.'),
  ('en.sahih', 23, 103, 'But those whose scales are light - those are the ones who have lost their souls, [being] in Hell, abiding eternally.'),
  ('en.sahih', 23, 104, 'The Fire will sear their faces, and they therein will have taut smiles.'),
  ('en.sahih', 23, 105, '[It will be said]. "Were not My verses recited to you and you used to deny them?"'),
  ('en.sahih', 23, 106, 'They will say, "Our Lord, our wretchedness overcame us, and we were a people astray.'),
  ('en.sahih', 23, 107, 'Our Lord, remove us from it, and if we were to return [to evil], we would indeed be wrongdoers."'),
  ('en.sahih', 23, 108, 'He will say, "Remain despised therein and do not speak to Me.'),
  ('en.sahih', 23, 109, 'Indeed, there was a party of My servants who said, \'Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.\''),
  ('en.sahih', 23, 110, 'But you took them in mockery to the point that they made you forget My remembrance, and you used to laugh at them.'),
  ('en.sahih', 23, 111, 'Indeed, I have rewarded them this Day for their patient endurance - that they are the attainers [of success]."'),
  ('en.sahih', 23, 112, '[Allah] will say, "How long did you remain on earth in number of years?"'),
  ('en.sahih', 23, 113, 'They will say, "We remained a day or part of a day; ask those who enumerate."'),
  ('en.sahih', 23, 114, 'He will say, "You stayed not but a little - if only you had known.'),
  ('en.sahih', 23, 115, 'Then did you think that We created you uselessly and that to Us you would not be returned?"'),
  ('en.sahih', 23, 116, 'So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne.'),
  ('en.sahih', 23, 117, 'And whoever invokes besides Allah another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed.'),
  ('en.sahih', 23, 118, 'And, [O Muhammad], say, "My Lord, forgive and have mercy, and You are the best of the merciful."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 23, 1, 'মুমিনগণ সফলকাম হয়ে গেছে,'),
  ('bn.bengali', 23, 2, 'যারা নিজেদের নামাযে বিনয়-নম্র;'),
  ('bn.bengali', 23, 3, 'যারা অনর্থক কথা-বার্তায় নির্লিপ্ত,'),
  ('bn.bengali', 23, 4, 'যারা যাকাত দান করে থাকে'),
  ('bn.bengali', 23, 5, 'এবং যারা নিজেদের যৌনাঙ্গকে সংযত রাখে।'),
  ('bn.bengali', 23, 6, 'তবে তাদের স্ত্রী ও মালিকানাভুক্ত দাসীদের ক্ষেত্রে সংযত না রাখলে তারা তিরস্কৃত হবে না।'),
  ('bn.bengali', 23, 7, 'অতঃপর কেউ এদেরকে ছাড়া অন্যকে কামনা করলে তারা সীমালংঘনকারী হবে।'),
  ('bn.bengali', 23, 8, 'এবং যারা আমানত ও অঙ্গীকার সম্পর্কে হুশিয়ার থাকে।'),
  ('bn.bengali', 23, 9, 'এবং যারা তাদের নামাযসমূহের খবর রাখে।'),
  ('bn.bengali', 23, 10, 'তারাই উত্তরাধিকার লাভ করবে।'),
  ('bn.bengali', 23, 11, 'তারা শীতল ছায়াময় উদ্যানের উত্তরাধিকার লাভ করবে। তারা তাতে চিরকাল থাকবে।'),
  ('bn.bengali', 23, 12, 'আমি মানুষকে মাটির সারাংশ থেকে সৃষ্টি করেছি।'),
  ('bn.bengali', 23, 13, 'অতঃপর আমি তাকে শুক্রবিন্দু রূপে এক সংরক্ষিত আধারে স্থাপন করেছি।'),
  ('bn.bengali', 23, 14, 'এরপর আমি শুক্রবিন্দুকে জমাট রক্তরূপে সৃষ্টি করেছি, অতঃপর জমাট রক্তকে মাংসপিন্ডে পরিণত করেছি, এরপর সেই মাংসপিন্ড থেকে অস্থি সৃষ্টি করেছি, অতঃপর অস্থিকে মাংস দ্বারা আবৃত করেছি, অবশেষে তাকে নতুন রূপে দাঁড় করিয়েছি। নিপুণতম সৃষ্টিকর্তা আল্লাহ কত কল্যাণময়।'),
  ('bn.bengali', 23, 15, 'এরপর তোমরা মৃত্যুবরণ করবে'),
  ('bn.bengali', 23, 16, 'অতঃপর কেয়ামতের দিন তোমরা পুনরুত্থিত হবে।'),
  ('bn.bengali', 23, 17, 'আমি তোমাদের উপর সুপ্তপথ সৃষ্টি করেছি এবং আমি সৃষ্টি সম্বন্ধে অনবধান নই।'),
  ('bn.bengali', 23, 18, 'আমি আকাশ থেকে পানি বর্ষণ করে থাকি পরিমাণ মত অতঃপর আমি জমিনে সংরক্ষণ করি এবং আমি তা অপসারণও করতে সক্ষম।'),
  ('bn.bengali', 23, 19, 'অতঃপর আমি তা দ্বারা তোমাদের জন্যে খেজুর ও আঙ্গুরের বাগান সৃষ্টি করেছি। তোমাদের জন্যে এতে প্রচুর ফল আছে এবং তোমরা তা থেকে আহার করে থাক।'),
  ('bn.bengali', 23, 20, 'এবং ঐ বৃক্ষ সৃষ্টি করেছি, যা সিনাই পর্বতে জন্মায় এবং আহারকারীদের জন্যে তৈল ও ব্যঞ্জন উৎপন্ন করে।'),
  ('bn.bengali', 23, 21, 'এবং তোমাদের জন্যে চতুস্পদ জন্তু সমূহের মধ্যে চিন্তা করার বিষয় রয়েছে। আমি তোমাদেরকে তাদের উদরস্থিত বস্তু থেকে পান করাই এবং তোমাদের জন্যে তাদের মধ্যে প্রচুর উপকারিতা আছে। তোমরা তাদের কতককে ভক্ষণ কর।'),
  ('bn.bengali', 23, 22, 'তাদের পিঠে ও জলযানে তোমরা আরোহণ করে চলাফেরা করে থাক।'),
  ('bn.bengali', 23, 23, 'আমি নূহকে তার সম্প্রদায়ের কাছে প্রেরণ করেছিলাম। সে বলেছিলঃ হে আমার সম্প্রদায়, তোমরা আল্লাহর বন্দেগী কর। তিনি ব্যতীত তোমাদের কোন মাবুদ নেই। তোমরা কি ভয় কর না।'),
  ('bn.bengali', 23, 24, 'তখন তার সম্প্রদায়ের কাফের-প্রধানরা বলেছিলঃ এ তো তোমাদের মতই একজন মানুষ বৈ নয়। সে তোমাদের উপর নেতৃত্ব করতে চায়। আল্লাহ ইচ্ছা করলে ফেরেশতাই নাযিল করতেন। আমরা আমাদের পূর্বপুরুষদের মধ্যে এরূপ কথা শুনিনি।'),
  ('bn.bengali', 23, 25, 'সে তো এক উম্মাদ ব্যক্তি বৈ নয়। সুতরাং কিছুকাল তার ব্যাপারে অপেক্ষা কর।'),
  ('bn.bengali', 23, 26, 'নূহ বলেছিলঃ হে আমার পালনকর্তা, আমাকে সাহায্য কর; কেননা, তারা আমাকে মিথ্যাবাদী বলছে।'),
  ('bn.bengali', 23, 27, 'অতঃপর আমি তার কাছে আদেশ প্রেরণ করলাম যে, তুমি আমার দৃষ্টির সামনে এবং আমার নির্দেশে নৌকা তৈরী কর। এরপর যখন আমার আদেশ আসে এবং চুল্লী প্লাবিত হয়, তখন নৌকায় তুলে নাও, প্রত্যেক জীবের এক এক জোড়া এবং তোমার পরিবারবর্গকে, তাদের মধ্যে যাদের বিপক্ষে পূর্বে সিদ্ধান্ত নেয়া হয়েছে তাদের ছাড়া। এবং তুমি জালেমদের সম্পর্কে আমাকে কিছু বলো না। নিশ্চয় তারা নিমজ্জত হবে।'),
  ('bn.bengali', 23, 28, 'যখন তুমি ও তোমার সঙ্গীরা নৌকায় আরোহণ করবে, তখন বলঃ আল্লাহর শোকর, যিনি আমাদেরকে জালেম সম্প্রদায়ের কবল থেকে উদ্ধার করেছেন।'),
  ('bn.bengali', 23, 29, 'আরও বলঃ পালনকর্তা, আমাকে কল্যাণকর ভাবে নামিয়ে দাও, তুমি শ্রেষ্ঠ অবতারণকারী।'),
  ('bn.bengali', 23, 30, 'এতে নিদর্শনাবলী রয়েছে এবং আমি পরীক্ষাকারী।'),
  ('bn.bengali', 23, 31, 'অতঃপর অন্য এক সম্প্রদায় আমি তার স্থলাভিষিক্ত করেছিলাম।'),
  ('bn.bengali', 23, 32, 'এবং তাদেরই একজনকে তাদের মধ্যে রসূলরূপে প্রেরণ করেছিলাম এই বলে যে, তোমরা আল্লাহর বন্দেগী কর। তিনি ব্যতীত তোমাদের অন্য কোন মাবুদ নেই। তবুও কি তোমরা ভয় করবে না?'),
  ('bn.bengali', 23, 33, 'তাঁর সম্প্রদায়ের প্রধানরা যারা কাফের ছিল, পরকালের সাক্ষাতকে মিথ্যা বলত এবং যাদেরকে আমি পার্থিব জীবনে সুখ-স্বাচ্ছন্দ্য দিয়েছিলাম, তারা বললঃ এতো আমাদের মতই একজন মানুষ বৈ নয়। তোমরা যা খাও, সেও তাই খায় এবং তোমরা যা পান কর, সেও তাই পান করে।'),
  ('bn.bengali', 23, 34, 'যদি তোমরা তোমাদের মতই একজন মানুষের আনুগত্য কর, তবে তোমরা নিশ্চিতরূপেই ক্ষতিগ্রস্ত হবে।'),
  ('bn.bengali', 23, 35, 'সে কি তোমাদেরকে এই ওয়াদা দেয় যে, তোমরা মারা গেলে এবং মৃত্তিকা ও অস্থিতে পরিণত হলে তোমাদেরকে পুনরুজ্জীবিত করা হবে?'),
  ('bn.bengali', 23, 36, 'তোমাদেরকে যে ওয়াদা দেয়া হচ্ছে, তা কোথায় হতে পারে?'),
  ('bn.bengali', 23, 37, 'আমাদের পার্থিবজীবনই একমাত্র জীবন। আমরা মরি ও বাঁচি এখানেই এবং আমারা পুনরুত্থিত হবো না।'),
  ('bn.bengali', 23, 38, 'সে তো এমন ব্যক্তি বৈ নয়, যে আল্লাহ সম্বন্ধে মিথ্যা উদ্ভাবন করেছে এবং আমরা তাকে বিশ্বাস করি না।'),
  ('bn.bengali', 23, 39, 'তিনি বললেনঃ হে আমার পালনকর্তা, আমাকে সাহায্য কর, কারণ তারা আমাকে মিথ্যাবাদী বলছে।'),
  ('bn.bengali', 23, 40, 'আল্লাহ বললেনঃ কিছু দিনের মধ্যে তারা সকাল বেলা অনুতপ্ত হবে।'),
  ('bn.bengali', 23, 41, 'অতঃপর সত্য সত্যই এক ভয়ংকর শব্দ তাদেরকে হতচকিত করল এবং আমি তাদেরকে বাত্যা-তাড়িত আবর্জনা সদৃশ করে দিলাম। অতঃপর ধ্বংস হোক পাপী সম্প্রদায়।'),
  ('bn.bengali', 23, 42, 'এরপর তাদের পরে আমি বহু সম্প্রদায় সৃষ্টি করেছি।'),
  ('bn.bengali', 23, 43, 'কোন সম্প্রদায় তার নির্দিষ্ট কালের অগ্রে যেতে পারে না। এবং পশ্চাতেও থকাতে পারে না।'),
  ('bn.bengali', 23, 44, 'এরপর আমি একাদিক্রমে আমার রসূল প্রেরণ করেছি। যখনই কোন উম্মতের কাছে তাঁর রসূল আগমন করেছেন, তখনই তারা তাঁকে মিথ্যাবাদী বলেছে। অতঃপর আমি তাদের একের পর এক ধ্বংস করেছি এবং তাদেরকে কাহিনীর বিষয়ে পরিণত করেছি। সুতরাং ধ্বংস হোক অবিশ্বাসীরা।'),
  ('bn.bengali', 23, 45, 'অতঃপর আমি মূসা ও হারুণকে প্রেরণ করেছিলাম আমার নিদর্শনাবলী ও সুস্পষ্ট সনদসহ,'),
  ('bn.bengali', 23, 46, 'ফেরআউন ও তার অমাত্যদের কাছে। অতঃপর তারা অহংকার করল এবং তারা উদ্ধত সম্প্রদায় ছিল।'),
  ('bn.bengali', 23, 47, 'তারা বললঃ আমরা কি আমাদের মতই এ দুই ব্যক্তিতে বিশ্বাস স্থাপন করব; অথচ তাদের সম্প্রদায় আমাদের দাস?'),
  ('bn.bengali', 23, 48, 'অতঃপর তারা উভয়কে মিথ্যাবাদী বলল। ফলে তারা ধ্বংস প্রাপ্ত হল।'),
  ('bn.bengali', 23, 49, 'আমি মূসাকে কিতাব দিয়েছিলাম যাতে তারা সৎপথ পায়।'),
  ('bn.bengali', 23, 50, 'এবং আমি মরিয়ম তনয় ও তাঁর মাতাকে এক নিদর্শন দান করেছিলাম। এবং তাদেরকে এক অবস্থানযোগ্য স্বচ্ছ পানি বিশিষ্ট টিলায় আশ্রয় দিয়েছিলাম।'),
  ('bn.bengali', 23, 51, 'হে রসূলগণ, পবিত্র বস্তু আহার করুন এবং সৎকাজ করুন। আপনারা যা করেন সে বিষয়ে আমি পরিজ্ঞাত।'),
  ('bn.bengali', 23, 52, 'আপনাদের এই উম্মত সব তো একই ধর্মের অনুসারী এবং আমি আপনাদের পালনকর্তা; অতএব আমাকে ভয় করুন।'),
  ('bn.bengali', 23, 53, 'অতঃপর মানুষ তাদের বিষয়কে বহুধা বিভক্ত করে দিয়েছে। প্রত্যেক সম্প্রদায় নিজ নিজ মতবাদ নিয়ে আনন্দিত হচ্ছে।'),
  ('bn.bengali', 23, 54, 'অতএব তাদের কিছু কালের জন্যে তাদের অজ্ঞানতায় নিমজ্জত থাকতে দিন।'),
  ('bn.bengali', 23, 55, 'তারা কি মনে করে যে, আমি তাদেরকে ধন-সম্পদ ও সন্তান-সন্ততি দিয়ে যাচ্ছি।'),
  ('bn.bengali', 23, 56, 'তাতে করে তাদেরকে দ্রুত মঙ্গলের দিকে নিয়ে যাচ্ছি? বরং তারা বোঝে না।'),
  ('bn.bengali', 23, 57, 'নিশ্চয় যারা তাদের পালনকর্তার ভয়ে সন্ত্রস্ত,'),
  ('bn.bengali', 23, 58, 'যারা তাদের পালনকর্তার কথায় বিশ্বাস স্থাপন করে,'),
  ('bn.bengali', 23, 59, 'যারা তাদের পালনকর্তার সাথে কাউকে শরীক করে না'),
  ('bn.bengali', 23, 60, 'এবং যারা যা দান করবার, তা ভীত, কম্পিত হৃদয়ে এ কারণে দান করে যে, তারা তাদের পালনকর্তার কাছে প্রত্যাবর্তন করবে,'),
  ('bn.bengali', 23, 61, 'তারাই কল্যাণ দ্রুত অর্জন করে এবং তারা তাতে অগ্রগামী।'),
  ('bn.bengali', 23, 62, 'আমি কাউকে তার সাধ্যাতীত দায়িত্ব অর্পন করি না। আমার এক কিতাব আছে, যা সত্য ব্যক্ত করে এবং তাদের প্রতি জুলুম করা হবে না।'),
  ('bn.bengali', 23, 63, 'না, তাদের অন্তর এ বিষয়ে অজ্ঞানতায় আচ্ছন্ন, এ ছাড়া তাদের আরও কাজ রয়েছে, যা তারা করছে।'),
  ('bn.bengali', 23, 64, 'এমনকি, যখন আমি তাদের ঐশ্বর্যশালী লোকদেরকে শাস্তি দ্বারা পাকড়াও করব, তখনই তারা চীৎকার জুড়ে দেবে।'),
  ('bn.bengali', 23, 65, 'অদ্য চীৎকার করো না। তোমরা আমার কাছ থেকে নিস্কৃতি পাবে না।'),
  ('bn.bengali', 23, 66, 'তোমাদেরকে আমার আয়াতসমূহ শোনানো হত, তখন তোমরা উল্টো পায়ে সরে পড়তে।'),
  ('bn.bengali', 23, 67, 'অহংকার করে এ বিষয়ে অর্থহীন গল্প-গুজব করে যেতে।'),
  ('bn.bengali', 23, 68, 'অতএব তারা কি এই কালাম সম্পꦣ2503;ক চিন্তা-ভাবনা করে না? না তাদের কাছে এমন কিছু এসেছে, যা তাদের পিতৃপুরুষদের কাছে আসেনি?'),
  ('bn.bengali', 23, 69, 'না তারা তাদের রসূলকে চেনে না, ফলে তারা তাঁকে অস্বীকার করে?'),
  ('bn.bengali', 23, 70, 'না তারা বলে যে, তিনি পাগল ? বরং তিনি তাদের কাছে সত্য নিয়ে আগমন করেছেন এবং তাদের অধিকাংশ সত্যকে অপছন্দ করে।'),
  ('bn.bengali', 23, 71, 'সত্য যদি তাদের কাছে কামনা-বাসনার অনুসারী হত, তবে নভোমন্ডল ও ভূমন্ডল এবং এগুলোর মধ্যবর্তꦣ2496; সবকিছুই বিশৃঙ্খল হয়ে পড়ত। বরং আমি তাদেরকে দান করেছি উপদেশ, কিন্তু তারা তাদের উপদেশ অনুধাবন করে না।'),
  ('bn.bengali', 23, 72, 'না আপনি তাদের কাছে কোন প্রতিদান চান? আপনার পালনকর্তার প্রতিদান উত্তম এবং তিনিই রিযিকদাতা।'),
  ('bn.bengali', 23, 73, 'আপনি তো তাদেরকে সোজা পথে দাওয়াত দিচ্ছেন;'),
  ('bn.bengali', 23, 74, 'আর যারা পরকালে বিশ্বাস করে না, তারা সোজা পথ থেকে বিচ্যুত হয়ে গেছে।'),
  ('bn.bengali', 23, 75, 'যদি আমি তাদের প্রতি দয়া করি এবং তাদের কষ্ট দূর করে দেই, তবুও তারা তাদের অবাধ্যতায় দিশেহারা হয়ে লেগে থাকবে।'),
  ('bn.bengali', 23, 76, 'আমি তাদেরকে শাস্তি দ্বারা পাকড়াও করেছিলাম, কিন্তু তারা তাদের পালনকর্তার সামনে নত হল না এবং কাকুতি-মিনুতিও করল না।'),
  ('bn.bengali', 23, 77, 'অবশেষে যখন আমি তাদের জন্য কঠিন শাস্তির দ্বার খুলে দেব, তখন তাতে তাদের আশা ভঙ্গ হবে।'),
  ('bn.bengali', 23, 78, 'তিনি তোমাদের কান, চোখ ও অন্তঃকরণ সৃষ্টি করেছেন; তোমরা খুবই অল্প কৃতজ্ঞতা স্বীকার করে থাক।'),
  ('bn.bengali', 23, 79, 'তিনিই তোমাদেরকে পৃথিবীতে ছড়িয়ে রেখেছেন এবং তারই দিকে তোমাদেরকে সমবেত করা হবে।'),
  ('bn.bengali', 23, 80, 'তিনিই প্রাণ দান করেন এবং মৃত্যু ঘটান এবং দিবা-রাত্রির বিবর্তন তাঁরই কাজ, তবু ও কি তোমরা বুঝবে না?'),
  ('bn.bengali', 23, 81, 'বরং তারা বলে যেমন তাদের পূর্ববর্তীরা বলত।'),
  ('bn.bengali', 23, 82, 'তারা বলেঃ যখন আমরা মরে যাব এবং মৃত্তিকা ও অস্থিতে পরিণত হব, তখনও কি আমরা পুনরুত্থিত হব ?'),
  ('bn.bengali', 23, 83, 'অতীতে আমাদেরকে এবং আমাদের পিতৃপুরুষদেরকে এই ওয়াদাই দেয়া হয়েছে। এটা তো পূর্ববতীদের কল্প-কথা বৈ কিছুই নয়।'),
  ('bn.bengali', 23, 84, 'বলুন পৃথিবী এবং পৃথিবীতে যারা আছে, তারা কার? যদি তোমরা জান, তবে বল।'),
  ('bn.bengali', 23, 85, 'এখন তারা বলবেঃ সবই আল্লাহর। বলুন, তবুও কি তোমরা চিন্তা কর না?'),
  ('bn.bengali', 23, 86, 'বলুনঃ সপ্তাকাশ ও মহা-আরশের মালিক কে?'),
  ('bn.bengali', 23, 87, 'এখন তারা বলবেঃ আল্লাহ। বলুন, তবুও কি তোমরা ভয় করবে না?'),
  ('bn.bengali', 23, 88, 'বলুনঃ তোমাদের জানা থাকলে বল, কার হাতে সব বস্তুর কতৃর্ꦣ2468;্ব, যিনি রক্ষা করেন এবং যার কবল থেকে কেউ রক্ষা করতে পারে না ?'),
  ('bn.bengali', 23, 89, 'এখন তারা বলবেঃ আল্লাহর। বলুনঃ তাহলে কোথা থেকে তোমাদেরকে জাদু করা হচ্ছে?'),
  ('bn.bengali', 23, 90, 'কিছুই নয়, আমি তাদের কাছে সত্য পৌঁছিয়েছি, আর তারা তো মিথ্যাবাদী।'),
  ('bn.bengali', 23, 91, 'আল্লাহ কোন সন্তান গ্রহণ করেননি এবং তাঁর সাথে কোন মাবুদ নেই। থাকলে প্রত্যেক মাবুদ নিজ নিজ সৃষ্টি নিয়ে চলে যেত এবং একজন অন্যজনের উপর প্রবল হয়ে যেত। তারা যা বলে, তা থেকে আল্লাহ পবিত্র।'),
  ('bn.bengali', 23, 92, 'তিনি দৃশ্য ও অদৃশ্যের জ্ঞানী। তারা শরীক করে, তিনি তা থেকে উর্ধ্বে।'),
  ('bn.bengali', 23, 93, 'বলুনঃ হে আমার পালনকর্তা! যে বিষয়ে তাদেরকে ওয়াদা দেয়া হয়েছে তা যদি আমাকে দেখান,'),
  ('bn.bengali', 23, 94, 'হে আমার পালনকর্তা! তবে আপনি আমাকে গোনাহগার সম্প্রদায়ের অন্তর্ভূক্ত করবেন না।'),
  ('bn.bengali', 23, 95, 'আমি তাদেরকে যে বিষয়ের ওয়াদা দিয়েছি, তা আপনাকে দেখাতে অবশ্যই সক্ষম।'),
  ('bn.bengali', 23, 96, 'মন্দের জওয়াবে তাই বলুন, যা উত্তম। তারা যা বলে, আমি সে বিষয়ে সবিশেষ অবগত।'),
  ('bn.bengali', 23, 97, 'বলুনঃ হে আমার পালনকর্তা! আমি শয়তানের প্ররোচনা থেকে আপনার আশ্রয় প্রার্থনা করি,'),
  ('bn.bengali', 23, 98, 'এবং হে আমার পালনকর্তা! আমার নিকট তাদের উপস্থিতি থেকে আপনার আশ্রয় প্রার্থনা করি।'),
  ('bn.bengali', 23, 99, 'যখন তাদের কারও কাছে মৃত্যু আসে, তখন সে বলেঃ হে আমার পালণকর্তা! আমাকে পুনরায় (দুনিয়াতে ) প্রেরণ করুন।'),
  ('bn.bengali', 23, 100, 'যাতে আমি সৎকর্ম করতে পারি, যা আমি করিনি। কখনই নয়, এ তো তার একটি কথার কথা মাত্র। তাদের সামনে পর্দা আছে পুনরুত্থান দিবস পর্যন্ত।'),
  ('bn.bengali', 23, 101, 'অতঃপর যখন শিংগায় ফুৎকার দেয়া হবে, সেদিন তাদের পারস্পরিক আত্নীয়তার বন্ধন থাকবে না এবং একে অপরকে জিজ্ঞাসাবাদ করবে না।'),
  ('bn.bengali', 23, 102, 'যাদের পাল্লা ভারী হবে, তারাই হবে সফলকাম,'),
  ('bn.bengali', 23, 103, 'এবং যাদের পাল্লা হাল্কা হবে তারাই নিজেদের ক্ষতিসাধন করেছে, তারা দোযখেই চিরকাল বসবাস করবে।'),
  ('bn.bengali', 23, 104, 'আগুন তাদের মুখমন্ডল দগ্ধ করবে এবং তারা তাতে বীভৎস আকার ধারন করবে।'),
  ('bn.bengali', 23, 105, 'তোমাদের সামনে কি আমার আয়াত সমূহ পঠিত হত না? তোমরা তো সেগুলোকে মিথ্যা বলতে।'),
  ('bn.bengali', 23, 106, 'তারা বলবেঃ হে আমাদের পালনকর্তা, আমরা দূর্ভাগ্যের হাতে পরাভূত ছিলাম এবং আমরা ছিলাম বিভ্রান্ত জাতি।'),
  ('bn.bengali', 23, 107, 'হে আমাদের পালনকর্তা! এ থেকে আমাদেরকে উদ্ধার কর; আমরা যদি পুনরায় তা করি, তবে আমরা গোনাহগার হব।'),
  ('bn.bengali', 23, 108, 'আল্লাহ বলবেনঃ তোমরা ধিকৃত অবস্থায় এখানেই পড়ে থাক এবং আমার সাথে কোন কথা বলো না।'),
  ('bn.bengali', 23, 109, 'আমার বান্দাদের একদলে বলতঃ হে আমাদের পালনকর্তা! আমরা বিশ্বাস স্থাপন করেছি। অতএব তুমি আমাদেরকে ক্ষমা কর ও আমাদের প্রতি রহম কর। তুমি তো দয়ালুদের মধ্যে শ্রেষ্ঠ দয়ালু।'),
  ('bn.bengali', 23, 110, 'অতঃপর তোমরা তাদেরকে ঠাট্টার পাত্ররূপে গ্রহণ করতে। এমনকি, তা তোমাদেরকে আমার স্মরণ ভুলিয়ে দিয়েছিল এবং তোমরা তাদেরকে দেখে পরিহাস করতে।'),
  ('bn.bengali', 23, 111, 'আজ আমি তাদেরকে তাদের সবরের কারণে এমন প্রতিদান দিয়েছি যে, তারাই সফলকাম।'),
  ('bn.bengali', 23, 112, 'আল্লাহ বলবেনঃ তোমরা পৃথিবীতে কতদিন অবস্থান করলে বছরের গণনায়?'),
  ('bn.bengali', 23, 113, 'তারা বলবে, আমরা একদিন অথবা দিনের কিছু অংশ অবস্থান করেছি। অতএব আপনি গণনাকারীদেরকে জিজ্ঞেস করুন।'),
  ('bn.bengali', 23, 114, 'আল্লাহ বলবেনঃ তোমরা তাতে অল্পদিনই অবস্থান করেছ, যদি তোমরা জানতে?'),
  ('bn.bengali', 23, 115, 'তোমরা কি ধারণা কর যে, আমি তোমাদেরকে অনর্থক সৃষ্টি করেছি এবং তোমরা আমার কাছে ফিরে আসবে না?'),
  ('bn.bengali', 23, 116, 'অতএব শীর্ষ মহিমায় আল্লাহ, তিনি সত্যিকার মালিক, তিনি ব্যতীত কোন মাবুদ নেই। তিনি সম্মানিত আরশের মালিক।'),
  ('bn.bengali', 23, 117, 'যে কেউ আল্লাহর সাথে অন্য উপাস্যকে ডাকে, তার কাছে যার সনদ নেই, তার হিসাব তার পালণকর্তার কাছে আছে। নিশ্চয় কাফেররা সফলকাম হবে না।'),
  ('bn.bengali', 23, 118, 'বলূনঃ হে আমার পালনকর্তা, ক্ষমা করুন ও রহম করুন। রহমকারীদের মধ্যে আপনি শ্রেষ্ট রহমকারী।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 23, 1, 'Successful indeed are the believers'),
  ('en.pickthall', 23, 2, 'Who are humble in their prayers,'),
  ('en.pickthall', 23, 3, 'And who shun vain conversation,'),
  ('en.pickthall', 23, 4, 'And who are payers of the poor-due;'),
  ('en.pickthall', 23, 5, 'And who guard their modesty -'),
  ('en.pickthall', 23, 6, 'Save from their wives or the (slaves) that their right hands possess, for then they are not blameworthy,'),
  ('en.pickthall', 23, 7, 'But whoso craveth beyond that, such are transgressors -'),
  ('en.pickthall', 23, 8, 'And who are shepherds of their pledge and their covenant,'),
  ('en.pickthall', 23, 9, 'And who pay heed to their prayers.'),
  ('en.pickthall', 23, 10, 'These are the heirs'),
  ('en.pickthall', 23, 11, 'Who will inherit paradise. There they will abide.'),
  ('en.pickthall', 23, 12, 'Verily We created man from a product of wet earth;'),
  ('en.pickthall', 23, 13, 'Then placed him as a drop (of seed) in a safe lodging;'),
  ('en.pickthall', 23, 14, 'Then fashioned We the drop a clot, then fashioned We the clot a little lump, then fashioned We the little lump bones, then clothed the bones with flesh, and then produced it as another creation. So blessed be Allah, the Best of creators!'),
  ('en.pickthall', 23, 15, 'Then lo! after that ye surely die.'),
  ('en.pickthall', 23, 16, 'Then lo! on the Day of Resurrection ye are raised (again).'),
  ('en.pickthall', 23, 17, 'And We have created above you seven paths, and We are never unmindful of creation.'),
  ('en.pickthall', 23, 18, 'And we send down from the sky water in measure, and We give it lodging in the earth, and lo! We are Able to withdraw it.'),
  ('en.pickthall', 23, 19, 'Then We produce for you therewith gardens of date-palms and grapes, wherein is much fruit for you and whereof ye eat;'),
  ('en.pickthall', 23, 20, 'And a tree that springeth forth from Mount Sinai that groweth oil and relish for the eaters.'),
  ('en.pickthall', 23, 21, 'And lo! in the cattle there is verily a lesson for you. We give you to drink of that which is in their bellies, and many uses have ye in them, and of them do ye eat;'),
  ('en.pickthall', 23, 22, 'And on them and on the ship ye are carried.'),
  ('en.pickthall', 23, 23, 'And We verily sent Noah unto his folk, and he said: O my people! Serve Allah. Ye have no other Allah save Him. Will ye not ward off (evil)?'),
  ('en.pickthall', 23, 24, 'But the chieftains of his folk, who disbelieved, said: This is only a mortal like you who would make himself superior to you. Had Allah willed, He surely could have sent down angels. We heard not of this in the case of our fathers of old.'),
  ('en.pickthall', 23, 25, 'He is only a man in whom is a madness, so watch him for a while.'),
  ('en.pickthall', 23, 26, 'He said: My Lord! Help me because they deny me.'),
  ('en.pickthall', 23, 27, 'Then We inspired in him, saying: Make the ship under Our eyes and Our inspiration. Then, when Our command cometh and the oven gusheth water, introduce therein of every (kind) two spouses, and thy household save him thereof against whom the Word hath already gone forth. And plead not with Me on behalf of those who have done wrong. Lo! they will be drowned.'),
  ('en.pickthall', 23, 28, 'And when thou art on board the ship, thou and whoso is with thee, then say: Praise be to Allah Who hath saved us from the wrongdoing folk!'),
  ('en.pickthall', 23, 29, 'And say: My Lord! Cause me to land at a blessed landing-place, for Thou art Best of all who bring to land.'),
  ('en.pickthall', 23, 30, 'Lo! herein verily are portents, for lo! We are ever putting (mankind) to the test.'),
  ('en.pickthall', 23, 31, 'Then, after them, We brought forth another generation;'),
  ('en.pickthall', 23, 32, 'And we sent among them a messenger of their own, saying: Serve Allah, Ye have no other Allah save Him. Will ye not ward off (evil)?'),
  ('en.pickthall', 23, 33, 'And the chieftains of his folk, who disbelieved and denied the meeting of the Hereafter, and whom We had made soft in the life of the world, said: This is only a mortal like you, who eateth of that whereof ye eat and drinketh of that ye drink.'),
  ('en.pickthall', 23, 34, 'If ye were to obey a mortal like yourselves, then, lo! ye surely would be losers.'),
  ('en.pickthall', 23, 35, 'Doth he promise you that you, when ye are dead and have become dust and bones, will (again) be brought forth?'),
  ('en.pickthall', 23, 36, 'Begone, begone, with that which ye are promised!'),
  ('en.pickthall', 23, 37, 'There is naught but our life of the world; we die and we live, and we shall not be raised (again).'),
  ('en.pickthall', 23, 38, 'He is only a man who hath invented a lie about Allah. We are not going to put faith in him.'),
  ('en.pickthall', 23, 39, 'He said: My Lord! Help me because they deny me.'),
  ('en.pickthall', 23, 40, 'He said: In a little while they surely will become repentant.'),
  ('en.pickthall', 23, 41, 'So the (Awful) Cry overtook them rightfully, and We made them like as wreckage (that a torrent hurleth). A far removal for wrongdoing folk!'),
  ('en.pickthall', 23, 42, 'Then after them We brought forth other generations.'),
  ('en.pickthall', 23, 43, 'No nation can outstrip its term, nor yet postpone it.'),
  ('en.pickthall', 23, 44, 'Then We sent our messengers one after another. Whenever its messenger came unto a nation they denied him; so We caused them to follow one another (to disaster) and We made them bywords. A far removal for folk who believe not!'),
  ('en.pickthall', 23, 45, 'Then We sent Moses and his brother Aaron with Our tokens and a clear warrant'),
  ('en.pickthall', 23, 46, 'Unto Pharaoh and his chiefs, but they scorned (them) and they were despotic folk.'),
  ('en.pickthall', 23, 47, 'And they said: Shall we put faith in two mortals like ourselves, and whose folk are servile unto us?'),
  ('en.pickthall', 23, 48, 'So they denied them, and became of those who were destroyed.'),
  ('en.pickthall', 23, 49, 'And We verily gave Moses the Scripture, that haply they might go aright.'),
  ('en.pickthall', 23, 50, 'And We made the son of Mary and his mother a portent, and We gave them refuge on a height, a place of flocks and watersprings.'),
  ('en.pickthall', 23, 51, 'O ye messengers! Eat of the good things, and do right. Lo! I am Aware of what ye do.'),
  ('en.pickthall', 23, 52, 'And lo! this your religion is one religion and I am your Lord, so keep your duty unto Me.'),
  ('en.pickthall', 23, 53, 'But they (mankind) have broken their religion among them into sects, each group rejoicing in its tenets.'),
  ('en.pickthall', 23, 54, 'So leave them in their error till a time.'),
  ('en.pickthall', 23, 55, 'Think they that in the wealth and sons wherewith We provide them'),
  ('en.pickthall', 23, 56, 'We hasten unto them with good things? Nay, but they perceive not.'),
  ('en.pickthall', 23, 57, 'Lo! those who go in awe for fear of their Lord.'),
  ('en.pickthall', 23, 58, 'And those who believe in the revelations of their Lord,'),
  ('en.pickthall', 23, 59, 'And those who ascribe not partners unto their Lord,'),
  ('en.pickthall', 23, 60, 'And those who give that which they give with hearts afraid because they are about to return unto their Lord,'),
  ('en.pickthall', 23, 61, 'These race for the good things, and they shall win them in the race.'),
  ('en.pickthall', 23, 62, 'And we task not any soul beyond its scope, and with Us is a Record which speaketh the truth, and they will not be wronged.'),
  ('en.pickthall', 23, 63, 'Nay, but their hearts are in ignorance of this (Qur\'an), and they have other works, besides, which they are doing;'),
  ('en.pickthall', 23, 64, 'Till when We grasp their luxurious ones with the punishment, behold! they supplicate.'),
  ('en.pickthall', 23, 65, 'Supplicate not this day! Assuredly ye will not be helped by Us.'),
  ('en.pickthall', 23, 66, 'My revelations were recited unto you, but ye used to turn back on your heels,'),
  ('en.pickthall', 23, 67, 'In scorn thereof. Nightly did ye rave together.'),
  ('en.pickthall', 23, 68, 'Have they not pondered the Word, or hath that come unto them which came not unto their fathers of old?'),
  ('en.pickthall', 23, 69, 'Or know they not their messenger, and so reject him?'),
  ('en.pickthall', 23, 70, 'Or say they: There is a madness in him? Nay, but he bringeth them the Truth; and most of them are haters of the Truth.'),
  ('en.pickthall', 23, 71, 'And if the Truth had followed their desires, verily the heavens and the earth and whosoever is therein had been corrupted. Nay, We have brought them their Reminder, but from their Reminder they now turn away.'),
  ('en.pickthall', 23, 72, 'Or dost thou ask of them (O Muhammad) any tribute? But the bounty of thy Lord is better, for He is Best of all who make provision.'),
  ('en.pickthall', 23, 73, 'And lo! thou summonest them indeed unto a straight path.'),
  ('en.pickthall', 23, 74, 'And lo! those who believe not in the Hereafter are indeed astray from the path.'),
  ('en.pickthall', 23, 75, 'Though We had mercy on them and relieved them of the harm afflicting them, they still would wander blindly on in their contumacy.'),
  ('en.pickthall', 23, 76, 'Already have We grasped them with punishment, but they humble not themselves unto their Lord, nor do they pray,'),
  ('en.pickthall', 23, 77, 'Until, when We open for them the gate of extreme punishment, behold! they are aghast thereat.'),
  ('en.pickthall', 23, 78, 'He it is Who hath created for you ears and eyes and hearts. Small thanks give ye!'),
  ('en.pickthall', 23, 79, 'And He it is Who hath sown you broadcast in the earth, and unto Him ye will be gathered.'),
  ('en.pickthall', 23, 80, 'And He it is Who giveth life and causeth death, and His is the difference of night and day. Have ye then no sense?'),
  ('en.pickthall', 23, 81, 'Nay, but they say the like of that which said the men of old;'),
  ('en.pickthall', 23, 82, 'They say: When we are dead and have become (mere) dust and bones, shall we then, forsooth, be raised again?'),
  ('en.pickthall', 23, 83, 'We were already promised this, we and our forefathers. Lo! this is naught but fables of the men of old.'),
  ('en.pickthall', 23, 84, 'Say: Unto Whom (belongeth) the earth and whosoever is therein, if ye have knowledge?'),
  ('en.pickthall', 23, 85, 'They will say: Unto Allah. Say: Will ye not then remember?'),
  ('en.pickthall', 23, 86, 'Say: Who is Lord of the seven heavens, and Lord of the Tremendous Throne?'),
  ('en.pickthall', 23, 87, 'They will say: Unto Allah (all that belongeth). Say: Will ye not then keep duty (unto Him)?'),
  ('en.pickthall', 23, 88, 'Say: In Whose hand is the dominion over all things and He protecteth, while against Him there is no protection, if ye have knowledge?'),
  ('en.pickthall', 23, 89, 'They will say: Unto Allah (all that belongeth). Say: How then are ye bewitched?'),
  ('en.pickthall', 23, 90, 'Nay, but We have brought them the Truth, and lo! they are liars.'),
  ('en.pickthall', 23, 91, 'Allah hath not chosen any son, nor is there any god along with Him; else would each god have assuredly championed that which he created, and some of them would assuredly have overcome others. Glorified be Allah above all that they allege.'),
  ('en.pickthall', 23, 92, 'Knower of the Invisible and the Visible! and Exalted be He over all that they ascribe as partners (unto Him)!'),
  ('en.pickthall', 23, 93, 'Say: My Lord! If Thou shouldst show me that which they are promised.'),
  ('en.pickthall', 23, 94, 'My Lord! then set me not among the wrongdoing folk.'),
  ('en.pickthall', 23, 95, 'And verily We are Able to show thee that which We have promised them.'),
  ('en.pickthall', 23, 96, 'Repel evil with that which is better. We are Best Aware of that which they allege.'),
  ('en.pickthall', 23, 97, 'And say: My Lord! I seek refuge in Thee from suggestions of the evil ones,'),
  ('en.pickthall', 23, 98, 'And I seek refuge in Thee, my Lord, lest they be present with me,'),
  ('en.pickthall', 23, 99, 'Until, when death cometh unto one of them, he saith: My Lord! Send me back,'),
  ('en.pickthall', 23, 100, 'That I may do right in that which I have left behind! But nay! It is but a word that he speaketh; and behind them is a barrier until the day when they are raised.'),
  ('en.pickthall', 23, 101, 'And when the trumpet is blown there will be no kinship among them that day, nor will they ask of one another.'),
  ('en.pickthall', 23, 102, 'Then those whose scales are heavy, they are the successful.'),
  ('en.pickthall', 23, 103, 'And those whose scales are light are those who lose their souls, in hell abiding.'),
  ('en.pickthall', 23, 104, 'The fire burneth their faces, and they are glum therein.'),
  ('en.pickthall', 23, 105, '(It will be said): Were not My revelations recited unto you, and then ye used to deny them?'),
  ('en.pickthall', 23, 106, 'They will say: Our Lord! Our evil fortune conquered us, and we were erring folk.'),
  ('en.pickthall', 23, 107, 'Our Lord! Oh, bring us forth from hence! If we return (to evil) then indeed we shall be wrong-doers.'),
  ('en.pickthall', 23, 108, 'He saith: Begone therein, and speak not unto Me.'),
  ('en.pickthall', 23, 109, 'Lo! there was a party of My slaves who said: Our Lord! We believe, therefor forgive us and have mercy on us for Thou art Best of all who show mercy;'),
  ('en.pickthall', 23, 110, 'But ye chose them for a laughing-stock until they caused you to forget remembrance of Me, while ye laughed at them.'),
  ('en.pickthall', 23, 111, 'Lo! I have rewarded them this day forasmuch as they were steadfast in that they, even they, are the triumphant.'),
  ('en.pickthall', 23, 112, 'He will say: How long tarried ye in the earth, counting by years?'),
  ('en.pickthall', 23, 113, 'They will say: We tarried by a day or part of a day. Ask of those who keep count!'),
  ('en.pickthall', 23, 114, 'He will say: Ye tarried but a little if ye only knew.'),
  ('en.pickthall', 23, 115, 'Deemed ye then that We had created you for naught, and that ye would not be returned unto Us?'),
  ('en.pickthall', 23, 116, 'Now Allah be Exalted, the True King! There is no Allah save Him, the Lord of the Throne of Grace.'),
  ('en.pickthall', 23, 117, 'He who crieth unto any other god along with Allah hath no proof thereof. His reckoning is only with his Lord. Lo! disbelievers will not be successful.'),
  ('en.pickthall', 23, 118, 'And (O Muhammad) say: My Lord! Forgive and have mercy, for Thou art Best of all who show mercy.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 23, 1, 'The believers must (eventually) win through,-'),
  ('en.yusufali', 23, 2, 'Those who humble themselves in their prayers;'),
  ('en.yusufali', 23, 3, 'Who avoid vain talk;'),
  ('en.yusufali', 23, 4, 'Who are active in deeds of charity;'),
  ('en.yusufali', 23, 5, 'Who abstain from sex,'),
  ('en.yusufali', 23, 6, 'Except with those joined to them in the marriage bond, or (the captives) whom their right hands possess,- for (in their case) they are free from blame,'),
  ('en.yusufali', 23, 7, 'But those whose desires exceed those limits are transgressors;-'),
  ('en.yusufali', 23, 8, 'Those who faithfully observe their trusts and their covenants;'),
  ('en.yusufali', 23, 9, 'And who (strictly) guard their prayers;-'),
  ('en.yusufali', 23, 10, 'These will be the heirs,'),
  ('en.yusufali', 23, 11, 'Who will inherit Paradise: they will dwell therein (for ever).'),
  ('en.yusufali', 23, 12, 'Man We did create from a quintessence (of clay);'),
  ('en.yusufali', 23, 13, 'Then We placed him as (a drop of) sperm in a place of rest, firmly fixed;'),
  ('en.yusufali', 23, 14, 'Then We made the sperm into a clot of congealed blood; then of that clot We made a (foetus) lump; then we made out of that lump bones and clothed the bones with flesh; then we developed out of it another creature. So blessed be Allah, the best to create!'),
  ('en.yusufali', 23, 15, 'After that, at length ye will die'),
  ('en.yusufali', 23, 16, 'Again, on the Day of Judgment, will ye be raised up.'),
  ('en.yusufali', 23, 17, 'And We have made, above you, seven tracts; and We are never unmindful of (our) Creation.'),
  ('en.yusufali', 23, 18, 'And We send down water from the sky according to (due) measure, and We cause it to soak in the soil; and We certainly are able to drain it off (with ease).'),
  ('en.yusufali', 23, 19, 'With it We grow for you gardens of date-palms and vines: in them have ye abundant fruits: and of them ye eat (and have enjoyment),-'),
  ('en.yusufali', 23, 20, 'Also a tree springing out of Mount Sinai, which produces oil, and relish for those who use it for food.'),
  ('en.yusufali', 23, 21, 'And in cattle (too) ye have an instructive example: from within their bodies We produce (milk) for you to drink; there are, in them, (besides), numerous (other) benefits for you; and of their (meat) ye eat;'),
  ('en.yusufali', 23, 22, 'And on them, as well as in ships, ye ride.'),
  ('en.yusufali', 23, 23, '(Further, We sent a long line of prophets for your instruction). We sent Noah to his people: He said, "O my people! worship Allah! Ye have no other god but Him. Will ye not fear (Him)?"'),
  ('en.yusufali', 23, 24, 'The chiefs of the Unbelievers among his people said: "He is no more than a man like yourselves: his wish is to assert his superiority over you: if Allah had wished (to send messengers), He could have sent down angels; never did we hear such a thing (as he says), among our ancestors of old."'),
  ('en.yusufali', 23, 25, '(And some said): "He is only a man possessed: wait (and have patience) with him for a time."'),
  ('en.yusufali', 23, 26, '(Noah) said: "O my Lord! help me: for that they accuse me of falsehood!"'),
  ('en.yusufali', 23, 27, 'So We inspired him (with this message): "Construct the Ark within Our sight and under Our guidance: then when comes Our Command, and the fountains of the earth gush forth, take thou on board pairs of every species, male and female, and thy family- except those of them against whom the Word has already gone forth: And address Me not in favour of the wrong-doers; for they shall be drowned (in the Flood).'),
  ('en.yusufali', 23, 28, 'And when thou hast embarked on the Ark - thou and those with thee,- say: "Praise be to Allah, Who has saved us from the people who do wrong."'),
  ('en.yusufali', 23, 29, 'And say: "O my Lord! enable me to disembark with thy blessing: for Thou art the Best to enable (us) to disembark."'),
  ('en.yusufali', 23, 30, 'Verily in this there are Signs (for men to understand); (thus) do We try (men).'),
  ('en.yusufali', 23, 31, 'Then We raised after them another generation.'),
  ('en.yusufali', 23, 32, 'And We sent to them a messenger from among themselves, (saying), "Worship Allah! ye have no other god but Him. Will ye not fear (Him)?"'),
  ('en.yusufali', 23, 33, 'And the chiefs of his people, who disbelieved and denied the Meeting in the Hereafter, and on whom We had bestowed the good things of this life, said: "He is no more than a man like yourselves: he eats of that of which ye eat, and drinks of what ye drink.'),
  ('en.yusufali', 23, 34, '"If ye obey a man like yourselves, behold, it is certain ye will be lost.'),
  ('en.yusufali', 23, 35, '"Does he promise that when ye die and become dust and bones, ye shall be brought forth (again)?'),
  ('en.yusufali', 23, 36, '"Far, very far is that which ye are promised!'),
  ('en.yusufali', 23, 37, '"There is nothing but our life in this world! We shall die and we live! But we shall never be raised up again!'),
  ('en.yusufali', 23, 38, '"He is only a man who invents a lie against Allah, but we are not the ones to believe in him!"'),
  ('en.yusufali', 23, 39, '(The prophet) said: "O my Lord! help me: for that they accuse me of falsehood."'),
  ('en.yusufali', 23, 40, '(Allah) said: "In but a little while, they are sure to be sorry!"'),
  ('en.yusufali', 23, 41, 'Then the Blast overtook them with justice, and We made them as rubbish of dead leaves (floating on the stream of Time)! So away with the people who do wrong!'),
  ('en.yusufali', 23, 42, 'Then We raised after them other generations.'),
  ('en.yusufali', 23, 43, 'No people can hasten their term, nor can they delay (it).'),
  ('en.yusufali', 23, 44, 'Then sent We our messengers in succession: every time there came to a people their messenger, they accused him of falsehood: so We made them follow each other (in punishment): We made them as a tale (that is told): So away with a people that will not believe!'),
  ('en.yusufali', 23, 45, 'Then We sent Moses and his brother Aaron, with Our Signs and authority manifest,'),
  ('en.yusufali', 23, 46, 'To Pharaoh and his Chiefs: But these behaved insolently: they were an arrogant people.'),
  ('en.yusufali', 23, 47, 'They said: "Shall we believe in two men like ourselves? And their people are subject to us!"'),
  ('en.yusufali', 23, 48, 'So they accused them of falsehood, and they became of those who were destroyed.'),
  ('en.yusufali', 23, 49, 'And We gave Moses the Book, in order that they might receive guidance.'),
  ('en.yusufali', 23, 50, 'And We made the son of Mary and his mother as a Sign: We gave them both shelter on high ground, affording rest and security and furnished with springs.'),
  ('en.yusufali', 23, 51, 'O ye messengers! enjoy (all) things good and pure, and work righteousness: for I am well-acquainted with (all) that ye do.'),
  ('en.yusufali', 23, 52, 'And verily this Brotherhood of yours is a single Brotherhood, and I am your Lord and Cherisher: therefore fear Me (and no other).'),
  ('en.yusufali', 23, 53, 'But people have cut off their affair (of unity), between them, into sects: each party rejoices in that which is with itself.'),
  ('en.yusufali', 23, 54, 'But leave them in their confused ignorance for a time.'),
  ('en.yusufali', 23, 55, 'Do they think that because We have granted them abundance of wealth and sons,'),
  ('en.yusufali', 23, 56, 'We would hasten them on in every good? Nay, they do not understand.'),
  ('en.yusufali', 23, 57, 'Verily those who live in awe for fear of their Lord;'),
  ('en.yusufali', 23, 58, 'Those who believe in the Signs of their Lord;'),
  ('en.yusufali', 23, 59, 'Those who join not (in worship) partners with their Lord;'),
  ('en.yusufali', 23, 60, 'And those who dispense their charity with their hearts full of fear, because they will return to their Lord;-'),
  ('en.yusufali', 23, 61, 'It is these who hasten in every good work, and these who are foremost in them.'),
  ('en.yusufali', 23, 62, 'On no soul do We place a burden greater than it can bear: before Us is a record which clearly shows the truth: they will never be wronged.'),
  ('en.yusufali', 23, 63, 'But their hearts are in confused ignorance of this; and there are, besides that, deeds of theirs, which they will (continue) to do,-'),
  ('en.yusufali', 23, 64, 'Until, when We seize in Punishment those of them who received the good things of this world, behold, they will groan in supplication!'),
  ('en.yusufali', 23, 65, '(It will be said): "Groan not in supplication this day: for ye shall certainly not be helped by Us.'),
  ('en.yusufali', 23, 66, '"My Signs used to be rehearsed to you, but ye used to turn back on your heels-'),
  ('en.yusufali', 23, 67, '"In arrogance: talking nonsense about the (Qur\'an), like one telling fables by night."'),
  ('en.yusufali', 23, 68, 'Do they not ponder over the Word (of Allah), or has anything (new) come to them that did not come to their fathers of old?'),
  ('en.yusufali', 23, 69, 'Or do they not recognise their Messenger, that they deny him?'),
  ('en.yusufali', 23, 70, 'Or do they say, "He is possessed"? Nay, he has brought them the Truth, but most of them hate the Truth.'),
  ('en.yusufali', 23, 71, 'If the Truth had been in accord with their desires, truly the heavens and the earth, and all beings therein would have been in confusion and corruption! Nay, We have sent them their admonition, but they turn away from their admonition.'),
  ('en.yusufali', 23, 72, 'Or is it that thou askest them for some recompense? But the recompense of thy Lord is best: He is the Best of those who give sustenance.'),
  ('en.yusufali', 23, 73, 'But verily thou callest them to the Straight Way;'),
  ('en.yusufali', 23, 74, 'And verily those who believe not in the Hereafter are deviating from that Way.'),
  ('en.yusufali', 23, 75, 'If We had mercy on them and removed the distress which is on them, they would obstinately persist in their transgression, wandering in distraction to and fro.'),
  ('en.yusufali', 23, 76, 'We inflicted Punishment on them, but they humbled not themselves to their Lord, nor do they submissively entreat (Him)!-'),
  ('en.yusufali', 23, 77, 'Until We open on them a gate leading to a severe Punishment: then Lo! they will be plunged in despair therein!'),
  ('en.yusufali', 23, 78, 'It is He Who has created for you (the faculties of) hearing, sight, feeling and understanding: little thanks it is ye give!'),
  ('en.yusufali', 23, 79, 'And He has multiplied you through the earth, and to Him shall ye be gathered back.'),
  ('en.yusufali', 23, 80, 'It is He Who gives life and death, and to Him (is due) the alternation of Night and Day: will ye not then understand?'),
  ('en.yusufali', 23, 81, 'On the contrary they say things similar to what the ancients said.'),
  ('en.yusufali', 23, 82, 'They say: "What! when we die and become dust and bones, could we really be raised up again?'),
  ('en.yusufali', 23, 83, '"Such things have been promised to us and to our fathers before! they are nothing but tales of the ancients!"'),
  ('en.yusufali', 23, 84, 'Say: "To whom belong the earth and all beings therein? (say) if ye know!"'),
  ('en.yusufali', 23, 85, 'They will say, "To Allah!" say: "Yet will ye not receive admonition?"'),
  ('en.yusufali', 23, 86, 'Say: "Who is the Lord of the seven heavens, and the Lord of the Throne (of Glory) Supreme?"'),
  ('en.yusufali', 23, 87, 'They will say, "(They belong) to Allah." Say: "Will ye not then be filled with awe?"'),
  ('en.yusufali', 23, 88, 'Say: "Who is it in whose hands is the governance of all things,- who protects (all), but is not protected (of any)? (say) if ye know."'),
  ('en.yusufali', 23, 89, 'They will say, "(It belongs) to Allah." Say: "Then how are ye deluded?"'),
  ('en.yusufali', 23, 90, 'We have sent them the Truth: but they indeed practise falsehood!'),
  ('en.yusufali', 23, 91, 'No son did Allah beget, nor is there any god along with Him: (if there were many gods), behold, each god would have taken away what he had created, and some would have lorded it over others! Glory to Allah! (He is free) from the (sort of) things they attribute to Him!'),
  ('en.yusufali', 23, 92, 'He knows what is hidden and what is open: too high is He for the partners they attribute to Him!'),
  ('en.yusufali', 23, 93, 'Say: "O my Lord! if Thou wilt show me (in my lifetime) that which they are warned against,-'),
  ('en.yusufali', 23, 94, '"Then, O my Lord! put me not amongst the people who do wrong!"'),
  ('en.yusufali', 23, 95, 'And We are certainly able to show thee (in fulfilment) that against which they are warned.'),
  ('en.yusufali', 23, 96, 'Repel evil with that which is best: We are well acquainted with the things they say.'),
  ('en.yusufali', 23, 97, 'And say "O my Lord! I seek refuge with Thee from the suggestions of the Evil Ones.'),
  ('en.yusufali', 23, 98, '"And I seek refuge with Thee O my Lord! lest they should come near me."'),
  ('en.yusufali', 23, 99, '(In Falsehood will they be) Until, when death comes to one of them, he says: "O my Lord! send me back (to life),-'),
  ('en.yusufali', 23, 100, '"In order that I may work righteousness in the things I neglected." - "By no means! It is but a word he says."- Before them is a Partition till the Day they are raised up.'),
  ('en.yusufali', 23, 101, 'Then when the Trumpet is blown, there will be no more relationships between them that Day, nor will one ask after another!'),
  ('en.yusufali', 23, 102, 'Then those whose balance (of good deeds) is heavy,- they will attain salvation:'),
  ('en.yusufali', 23, 103, 'But those whose balance is light, will be those who have lost their souls, in Hell will they abide.'),
  ('en.yusufali', 23, 104, 'The Fire will burn their faces, and they will therein grin, with their lips displaced.'),
  ('en.yusufali', 23, 105, '"Were not My Signs rehearsed to you, and ye did but treat them as falsehood?"'),
  ('en.yusufali', 23, 106, 'They will say: "our Lord! Our misfortune overwhelmed us, and we became a people astray!'),
  ('en.yusufali', 23, 107, '"Our Lord! bring us out of this: if ever we return (to Evil), then shall we be wrong-doers indeed!"'),
  ('en.yusufali', 23, 108, 'He will say: "Be ye driven into it (with ignominy)! And speak ye not to Me!'),
  ('en.yusufali', 23, 109, '"A part of My servants there was, who used to pray \'our Lord! we believe; then do Thou forgive us, and have mercy upon us: For Thou art the Best of those who show mercy!"'),
  ('en.yusufali', 23, 110, '"But ye treated them with ridicule, so much so that (ridicule of) them made you forget My Message while ye were laughing at them!'),
  ('en.yusufali', 23, 111, '"I have rewarded them this Day for their patience and constancy: they are indeed the ones that have achieved Bliss..."'),
  ('en.yusufali', 23, 112, 'He will say: "What number of years did ye stay on earth?"'),
  ('en.yusufali', 23, 113, 'They will say: "We stayed a day or part of a day: but ask those who keep account."'),
  ('en.yusufali', 23, 114, 'He will say: "Ye stayed not but a little,- if ye had only known!'),
  ('en.yusufali', 23, 115, '"Did ye then think that We had created you in jest, and that ye would not be brought back to Us (for account)?"'),
  ('en.yusufali', 23, 116, 'Therefore exalted be Allah, the King, the Reality: there is no god but He, the Lord of the Throne of Honour!'),
  ('en.yusufali', 23, 117, 'If anyone invokes, besides Allah, Any other god, he has no authority therefor; and his reckoning will be only with his Lord! and verily the Unbelievers will fail to win through!'),
  ('en.yusufali', 23, 118, 'So say: "O my Lord! grant Thou forgiveness and mercy for Thou art the Best of those who show mercy!"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 23, 1, 'Qad aflahal mu\'minoon'),
  ('en.transliteration', 23, 2, 'Allazeena hum fee Salaatihim khaashi\'oon'),
  ('en.transliteration', 23, 3, 'Wallazeena hum \'anillaghwimu\'ridoon'),
  ('en.transliteration', 23, 4, 'Wallazeena hum liz Zakaati faa\'iloon'),
  ('en.transliteration', 23, 5, 'Wallazeena hum lifuroo jihim haafizoon'),
  ('en.transliteration', 23, 6, 'Illaa \'alaaa azwaajihim aw maa malakat aimaanuhum fa innahum ghairu maloomeen'),
  ('en.transliteration', 23, 7, 'Famanib taghaa waraaa\'a zaalika fa ulaaa\'ika humul \'aadoon'),
  ('en.transliteration', 23, 8, 'Wallazeena hum li amaanaatihim wa \'ahdihim raa\'oon'),
  ('en.transliteration', 23, 9, 'Wallazeena hum \'alaa Salawaatihim yuhaafizoon'),
  ('en.transliteration', 23, 10, 'Ulaaa\'ika humul waarisoon'),
  ('en.transliteration', 23, 11, 'Allazeena yarisoonal Firdawsa hum feehaa khaalidoon'),
  ('en.transliteration', 23, 12, 'Wa laqad khalaqnal insaana min sulaalatim minteen'),
  ('en.transliteration', 23, 13, 'Summa ja\'alnaahu nutfatan fee qaraarim makeen'),
  ('en.transliteration', 23, 14, 'Summa khalaqnan nutfata \'alaqatan fakhalaqnal \'alaqata mudghatan fakhalaq nal mudghata \'izaaman fakasawnal \'izaama lahman summa anshaanaahu khalqan aakhar; fatabaarakal laahu ahsanul khaaliqeen'),
  ('en.transliteration', 23, 15, 'Summa innakum ba\'da zaalika la maaiyitoon'),
  ('en.transliteration', 23, 16, 'Summa innakum Yawmal Qiyaamati tub\'asoon'),
  ('en.transliteration', 23, 17, 'Wa laqad khalaqnaa fawqakum sab\'a taraaa\'iqa wa maa kunnaa \'anil khalqi ghaafileen'),
  ('en.transliteration', 23, 18, 'Wa anzalnaa minas samaaa\'i maaa\'am biqadarin fa-askannaahu fil ardi wa innaa \'alaa zahaabim bihee laqaa diroon'),
  ('en.transliteration', 23, 19, 'Fa anshaanaa lakum bihee Jannaatim min nakheelinw wa a\'naab; lakum feehaa fawaakihu kaseeratunw wa minhaa taakuloon'),
  ('en.transliteration', 23, 20, 'Wa shajaratan takhruju min Toori Sainaaa\'a tambutu bidduhni wa sibghil lil aakileen'),
  ('en.transliteration', 23, 21, 'Wa inna lakum fil an\'aami la\'ibrah; nusqeekum mimmaa fee butoonihaa wa lakum feehaa manaafi\'u kaseeratunw wa minhaa taakuloon'),
  ('en.transliteration', 23, 22, 'Wa \'alaihaa wa\'alal fulki tuhmaloon'),
  ('en.transliteration', 23, 23, 'Wa laqad arsalnaa Noohan ilaa qawmihee faqaala yaa qawmi\'budul laaha maa lakum min ilahin ghairuhoo afalaa tattaqoon'),
  ('en.transliteration', 23, 24, 'Faqaalal mala\'ul lazeena kafaroo min qawmihee maa haazaaa illaa basharum mislukum yureedu ai yatafaddala \'alaikum wa law shaaa\'al laahu la anzala malaaa\'ikatam maa sami\'naa bihaazaa feee aabaaa\'inal awwaleen'),
  ('en.transliteration', 23, 25, 'In huwa illaa rajulum bihee jinnatun fatarabbasoo bihee hattan heen'),
  ('en.transliteration', 23, 26, 'Qaala Rabbin surnee bimaa kazzaboon'),
  ('en.transliteration', 23, 27, 'Fa awhainaaa ilaihi anis na\'il fulka bi a\'yuninaa wa wahyinaa fa izaa jaaa\'a amrunaa wa faarat tannooru fasluk feehaa min kullin zawjainis naini wa ahlaka illaa man sabaqa \'alaihil qawlu minhum wa laa tukhaat ibnee fil lazeena zalamooo innaahum mughraqoon'),
  ('en.transliteration', 23, 28, 'Fa izas tawaita ata wa mam ma\'aka \'alal fulki faqulil hamdu lillaahil lazee najjaanaa minal qawmiz zalimeen'),
  ('en.transliteration', 23, 29, 'Wa qur Rabbi anzilnee munzalam mubaarakanw wa Anta khairul munzileen'),
  ('en.transliteration', 23, 30, 'Inna fee zaalika la Aayaatinw wa in kunnaa lamubtaleen'),
  ('en.transliteration', 23, 31, 'Summaa anshaana mim ba\'dihim qarnan aakhareen'),
  ('en.transliteration', 23, 32, 'Fa arsalnaa feehim Rasoolam minhum ani\'budul laaha maa lakum min ilaahin ghairuhoo afalaa tattaqoon'),
  ('en.transliteration', 23, 33, 'Wa qaalal mala-u min qawmihil lazeena kafaroo wa kazzaboo bi liqaaa\'il Aakhirati wa atrafnaahum fil hayaatid dunyaa maa haazaaa illaa basharum mislukum yaakulu mimmaa taakuloona minhu wa yashrabu mimmaa tashraboon'),
  ('en.transliteration', 23, 34, 'Wa la\'in at\'atum basharam mislakum innakum izal lakhaasiroon'),
  ('en.transliteration', 23, 35, 'A-Ya\'idukum annakum izaa mittum wa kuntum turaabanw wa izaaman annakum mukhrajoon'),
  ('en.transliteration', 23, 36, 'Haihaata haihaata limaa too\'adoon'),
  ('en.transliteration', 23, 37, 'In hiya illaa hayaatunad dunyaa namootu wa nahyaa wa maa nahnu bimab\'ooseen'),
  ('en.transliteration', 23, 38, 'In huwa illaa rajulunif taraa \'alal laahi kazibanw wa maa nahnuu lahoo bimu\'mineen'),
  ('en.transliteration', 23, 39, 'Qaala Rabbin surnee bimaa kazzaboon'),
  ('en.transliteration', 23, 40, 'Qaala \'ammaa qaleelil la yusbihunna naadimeen'),
  ('en.transliteration', 23, 41, 'Fa akhazat humus saihatu bilhaqqi faja\'alnaahum ghusaaa\'aa; fabu;dal lilqaw miz zaalimeen'),
  ('en.transliteration', 23, 42, 'Summa anshaanaa mim ba\'dihim quroonan aakhareen'),
  ('en.transliteration', 23, 43, 'Maa tasbiqu min ummatin ajalahaa wa maa yastaakhiroon'),
  ('en.transliteration', 23, 44, 'Summa arsalnaa Rusulanaa tatraa kulla maa jaaa\'a ummatar Rasooluhaa kazzabooh; fa atba\'naa ba\'dahum ba\'danw wa ja\'alnaahum ahaadees; fabu\'dal liqawmil laa yu\'minoon'),
  ('en.transliteration', 23, 45, 'Summa arsalnaa Moosaa wa akhaahu Haaroona bi Aayaatinaa wa sultaanim mubeen'),
  ('en.transliteration', 23, 46, 'Ilaa Fir\'awna wa mala\'ihee fastakbaroo wa kaanoo qawman \'aaleem'),
  ('en.transliteration', 23, 47, 'Faqaaloo annu\'minu libasharaini mislinaa wa qawmuhumaa lanaa \'aabidoon'),
  ('en.transliteration', 23, 48, 'Fakazzaboohumaa fakaanoo minal mmuhlakeen'),
  ('en.transliteration', 23, 49, 'Wa laqad aatainaa Moosal Kitaaba la\'allahum yahtadoon'),
  ('en.transliteration', 23, 50, 'Wa ja\'alnab na Maryama wa ummahooo aayatannw wa aawainaahumaaa ilaa rabwatin zaati qaraarinw wa ma\'een'),
  ('en.transliteration', 23, 51, 'Yaaa aiyuhar Rusulu kuloo minat taiyibaati wa\'maloo saalihan innee bimaa ta\'maloona \'Aleem'),
  ('en.transliteration', 23, 52, 'Wa inna haaziheee ummatukum ummatanw waahidatanw wa Ana Rabbukum fattaqoon'),
  ('en.transliteration', 23, 53, 'Fataqatta\'ooo amrahum bainahum zuburaa; kullu hizbim bimaa ladaihim farihoon'),
  ('en.transliteration', 23, 54, 'Fazarhum fee ghamratihim hattaa heen'),
  ('en.transliteration', 23, 55, 'A-yahsaboona annnamaa numiduhum bihee mimmaalinw wa baneen'),
  ('en.transliteration', 23, 56, 'Nusaari\'u lahum fil khairaat; bal laa yash\'uroon'),
  ('en.transliteration', 23, 57, 'Innal lazeena hum min khashyati Rabbihim mushfiqoon'),
  ('en.transliteration', 23, 58, 'Wallazeena hum bi Aayaati Rabbihim yu\'minoon'),
  ('en.transliteration', 23, 59, 'Wallazeena hum bi Rabbihim laa yushrikoon'),
  ('en.transliteration', 23, 60, 'Wallazeena yu\'toona maaa aataw wa quloobuhum wajilatun annahum ilaa Rabbihim raaji\'oon'),
  ('en.transliteration', 23, 61, 'Ulaaa\'ika yusaari\'oona fil khairaati wa hum lahaa saabiqoon'),
  ('en.transliteration', 23, 62, 'Wa laa nukallifu nafsan illaa wus\'ahaa wa ladainaa kitaabuny yantiqu bilhaqqi w ahum la yuzlamoon'),
  ('en.transliteration', 23, 63, 'Bal quloobuhum fee ghamratim min haazaa wa lahum a\'maalum min dooni zaalika hum lahaa \'aamiloon'),
  ('en.transliteration', 23, 64, 'Hattaaa izaaa akhznaa mutrafeehim bil\'azaabi izaa hum yaj\'aroon'),
  ('en.transliteration', 23, 65, 'Laa taj\'arul yawma innakum minnaa laa tunsaroon'),
  ('en.transliteration', 23, 66, 'Qad kaanat Aayaatee tutlaa \'alaikum fakuntum \'alaaa a\'qaabikum tankisoon'),
  ('en.transliteration', 23, 67, 'Mustakbireena bihee saamiran tahjuroon'),
  ('en.transliteration', 23, 68, 'Afalam yaddabbarrul qawla am jaaa\'ahum maa lam yaati aabaaa\'ahumul awwaleen'),
  ('en.transliteration', 23, 69, 'Am lam ya\'rifoo Rasoolahum fahum lahoo munkiroon'),
  ('en.transliteration', 23, 70, 'Am yaqooloona bihee jinnnah; bal jaaa\'ahum bilhaqqi wa aksaruhum lil haqqi kaarihoon'),
  ('en.transliteration', 23, 71, 'Wa lawit taba\'al haqqu ahwaaa\'ahum lafasadatis samaawaatu wal ardu wa man feehinnn; bal atainaahum bizikrihim fahum \'an zikrihim mu\'ridon'),
  ('en.transliteration', 23, 72, 'Am tas\'aluhum kharjan fakharaaju Rabbika khairunw wa Huwa khairur raaziqeen'),
  ('en.transliteration', 23, 73, 'Wa innaka latad\'oohum ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 23, 74, 'Wa innnal lazeena laa yu\'minoona bil Aakhirati \'anis siraati lanaakiboon'),
  ('en.transliteration', 23, 75, 'Wa law rahimnaahum wa kashafnaa maa bihim min durril lalajjoo fee tughyaanihim ya\'mahoon'),
  ('en.transliteration', 23, 76, 'Wa laqad akhaznaahum bil\'azaabi famastakaanoo li Rabbihim wa maa yatadarra\'oon'),
  ('en.transliteration', 23, 77, 'Hattaaa izaa fatahnaa \'alaihim baaban zaa \'azaabin shadeedin izaa hum feehi mublisoon'),
  ('en.transliteration', 23, 78, 'Wa Huwal lazeee ansha a-lakumus sam\'a wal absaara wal af\'idah; qaleelam maa tashkuroon'),
  ('en.transliteration', 23, 79, 'Wa Huwal lazee zara akum fil ardi wa ilaihi tuhsharoon'),
  ('en.transliteration', 23, 80, 'Wa Huwal lazee yuhyee wa yumeetu wa lahukh tilaaful laili wannahaar; afalaa ta\'qiloon'),
  ('en.transliteration', 23, 81, 'Bal qaaloo misla maa qaalal awwaloon'),
  ('en.transliteration', 23, 82, 'Qaalooo \'a-izaa mitnaa wa kunnaa turaabanw wa \'izaaman \'a-innaa lamab \'oosoon'),
  ('en.transliteration', 23, 83, 'Laqad wu\'idnaa nahnu wa aabaaa\'unaa haazaa min qablu in haazaaa illaaa asaateerul awwaleen'),
  ('en.transliteration', 23, 84, 'Qul limanil ardu wa man feehaaa in kuntum ta\'lamoon'),
  ('en.transliteration', 23, 85, 'Sa-yaqooloona lillaah; qul afalaa tazakkkaroon'),
  ('en.transliteration', 23, 86, 'Qul mar Rabbus samaawaatis sab\'i wa Rabbul \'Arshil \'Azeem'),
  ('en.transliteration', 23, 87, 'Sa yaqooloona lillaah; qul afalaa tattaqoon'),
  ('en.transliteration', 23, 88, 'Qul mam bi yadihee malakootu kulli shai\'inw wa Huwa yujeeru wa laa yujaaru \'alaihi in kuntum ta\'lamoon'),
  ('en.transliteration', 23, 89, 'Sa yaqooloona lillaah; qul fa annaa tus haroon'),
  ('en.transliteration', 23, 90, 'Bal atainaahum bil haqqi wa innahum lakaaziboon'),
  ('en.transliteration', 23, 91, 'Mat takhazal laahu minw waladinw wa maa kaana ma\'ahoo min ilaah; izal lazahaba kullu ilaahim bimaa khalaqa wa la\'alaa ba\'duhum \'alaa ba\'d; Subhaannal laahi \'ammaa yasifoon'),
  ('en.transliteration', 23, 92, '\'Aalimil Ghaibi wash shahhaadati fata\'aalaa \'ammaa yushrikoon'),
  ('en.transliteration', 23, 93, 'Qur Rabbi immmaa turiyannee maa yoo\'adoon'),
  ('en.transliteration', 23, 94, 'Rabbi falaa taj\'alnee fil qawmiz zaalimeen'),
  ('en.transliteration', 23, 95, 'Wa innaa \'alaaa an nuriyaka maa na\'iduhum laqaadiroon'),
  ('en.transliteration', 23, 96, 'Idfa\' billate hiya ahsanus saiyi\'ah; nahnu a\'lamu bimaa yasifoon'),
  ('en.transliteration', 23, 97, 'Wa qur Rabbi a\'oozu bika min hamazaatish Shayaateen'),
  ('en.transliteration', 23, 98, 'Wa a\'oozu bika Rabbi ai-yahduroon'),
  ('en.transliteration', 23, 99, 'Hattaaa izaa jaaa\'a ahada humul mawtu qaala Rabbir ji\'oon'),
  ('en.transliteration', 23, 100, 'La\'alleee a\'malu saalihan feemaa taraktu kallaa; innahaa kalimatun huwa qaaa\'iluhaa wa minw waraaa\'him barzakhun ilaa Yawmi yub\'asoon'),
  ('en.transliteration', 23, 101, 'Fa izaa nufikha fis Soori falaaa ansaaba bainahum yawma\'izinw wa laa yatasaaa\'aloon'),
  ('en.transliteration', 23, 102, 'Faman saqulat mawaazee nuhoo fa ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 23, 103, 'Wa man khaffat mawaa zeenuhoo fa ulaaa\'ikal lazeena khasiroon anfusahum fee Jahannnama khaalidoon'),
  ('en.transliteration', 23, 104, 'Talfahu wujoohahumun Naaru wa hum feehaa kaalihood'),
  ('en.transliteration', 23, 105, 'Alam takun Aayaatee tutlaa \'alaikum fakuntum bihaa tukazziboon'),
  ('en.transliteration', 23, 106, 'Qaaloo Rabbanaa ghalabat \'alainaa shiqwatunaa wa kunnaa qawman daaalleen'),
  ('en.transliteration', 23, 107, 'Rabbanaa akhrijnaa minhaa fa in \'udnaa fa innaa zaalimoon'),
  ('en.transliteration', 23, 108, 'Qaalakh sa\'oo feehaa wa laa tukallimoon'),
  ('en.transliteration', 23, 109, 'Innahoo kaana fareequm min \'ibaadee yaqooloona Rabbanaaa aamannaa faghfir lanaa warhamnaa wa Anta khairur raahimeen'),
  ('en.transliteration', 23, 110, 'Fattakhaztumoohum sikhriyyan hattaaa ansawkum zikree wa kuntum minhum tadhakoon'),
  ('en.transliteration', 23, 111, 'Inee jazaituhumul Yawma bimaa sabarooo annahum humul faaa\'izoon'),
  ('en.transliteration', 23, 112, 'Qaala kam labistum fil ardi \'adada sineen'),
  ('en.transliteration', 23, 113, 'Qaaloo labisnaa yawman aw ba\'da yawmin fas\'alil \'aaaddeen'),
  ('en.transliteration', 23, 114, 'Qaala il labistum illaa qaleelal law annakum kuntum ta\'lamoon'),
  ('en.transliteration', 23, 115, 'Afahsibtum annamaa khalaqnaakum \'abasanw wa annakum ilainaa laa turja\'oon'),
  ('en.transliteration', 23, 116, 'Fata\'aalal laahul Malikul Haqq; laaa ilaaha illaa Huwa Rabbul \'Arshil Kareem'),
  ('en.transliteration', 23, 117, 'Wa mai yad\'u ma\'allaahi ilaahan aakhara laa burhaana lahoo bihee fa innnamaa hisaabuhoo \'inda Rabbih; innahoo laa yuflihul kaafiroon'),
  ('en.transliteration', 23, 118, 'Wa qur Rabbigh fir warham wa Anta khairur raahimeen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 23, 1, 'ٰبے شک ایمان والے کامیاب ہو گئے'),
  ('ur.ahmedali', 23, 2, 'جو اپنی نماز میں عاجزی کرنے والے ہیں'),
  ('ur.ahmedali', 23, 3, 'اور جو بے ہودہ باتو ں سے منہ موڑنے والے ہیں'),
  ('ur.ahmedali', 23, 4, 'اور جو زکواة دینے والے ہیں'),
  ('ur.ahmedali', 23, 5, 'اور جو اپنی شرم گاہوں کی حفاظت کرنے والے ہیں'),
  ('ur.ahmedali', 23, 6, 'مگر اپنی بیویوں یا لونڈیوں پر اس لیے کہ ان میں کوئی الزام نہیں'),
  ('ur.ahmedali', 23, 7, 'پس جو شخص اس کے علاوہ طلب گار ہو تو وہی حد سے نکلنے والے ہیں'),
  ('ur.ahmedali', 23, 8, 'اور جو اپنی امانتوں اور اپنے وعدہ کا لحاظ رکھنے والے ہیں'),
  ('ur.ahmedali', 23, 9, 'اور جو اپنی نمازوں کی حفاظت کرتے ہیں'),
  ('ur.ahmedali', 23, 10, 'وہی وارث ہیں'),
  ('ur.ahmedali', 23, 11, 'جو جنت الفردوس کے وارث ہوں گے وہ اس میں ہمیشہ رہنے والے ہوں گے'),
  ('ur.ahmedali', 23, 12, 'اور البتہ ہم نے انسان کومٹی کے خلاصہ سے پیدا کیا'),
  ('ur.ahmedali', 23, 13, 'پھر ہم نے حفاظت کی جگہ میں نطفہ بنا کر رکھا'),
  ('ur.ahmedali', 23, 14, 'پھر ہم نے نطفہ کا لوتھڑا بنایا پھر ہم نے لوتھڑے سے گوشت کی بوٹی بنائی پھر ہم نے اس بوٹی سے ہڈیاں بنائیں پھر ہم نے ہڈیوں پر گوشت پہنایا پھر اسے ایک نئی صورت میں بنا دیا سو الله بڑی برکت والا سب سےبہتر بنانے والا ہے'),
  ('ur.ahmedali', 23, 15, 'پھر تم اس کے بعد مرنے والے ہو'),
  ('ur.ahmedali', 23, 16, 'پھر تم قیامت کے دن اٹھائے جاؤ گے'),
  ('ur.ahmedali', 23, 17, 'اورہم ہی نے تمہارے اوپر سات آسمان بنائے ہیں اور ہم بنانے میں بے خبر نہ تھے'),
  ('ur.ahmedali', 23, 18, 'اور ہم نے ایک اندازہ کے ساتھ آسمان سے پانی نازل کیا پھر اسے زمین میں ٹھیرایا اور ہم اس کے لے جانے پر بھی قادر ہیں'),
  ('ur.ahmedali', 23, 19, 'پھر ہم نے اس سے تمہارے لیے کھجور اور انگور کے باغ اگا دیے جن میں تمہارے بہت سے میوے ہیں اور انہی میں سے کھاتے ہو'),
  ('ur.ahmedali', 23, 20, 'اور وہ درخت جو طور سینا سے نکلتا ہے جو کھانے والوں کے لیے روغن اور سالن لے کر اگتا ہے'),
  ('ur.ahmedali', 23, 21, 'اور بے شک تمہارے لیے چارپایوں میں بھی عبرت ہے کہ ہم تمہیں ان کے پیٹ کی چیزوں میں سے پلاتے ہیں اور تمہارے لیے ان میں اوربھی بہت سے فائدے ہیں اور ان میں سے بعض کو کھاتے ہو'),
  ('ur.ahmedali', 23, 22, 'اور ان پر اور کشتیوں پر سوار بھی کیے جاتے ہو'),
  ('ur.ahmedali', 23, 23, 'اور ہم نے نوح کو اس کی قوم کے پاس بھیجا پھر اس نے کہا اے میری قوم الله کی بندگی کرو اس کے سوا تمہارا کوئی معبود نہیں پھر تم کیوں نہیں ڈرتے'),
  ('ur.ahmedali', 23, 24, 'سواس کی قوم کے کافر سرداروں نے کہا کہ یہ بس تم ہی جیسا آدمی ہے تم پر بڑائی حاصل کرنا چاہتا ہے اور اگر الله چاہتا تو فرشتے بھیج دیتا ہم نے اپنے پہلے باب دادا سے یہ بات کبھی نہیں سنی'),
  ('ur.ahmedali', 23, 25, 'یہ تو بس ایک دیوانہ آدمی ہے پس اس کا ایک وقت تک انتظار کرو'),
  ('ur.ahmedali', 23, 26, 'کہا اے میرے رب تو میری مدد کر کیوں کہ انہو ں نے مجھے جھٹلایا ہے'),
  ('ur.ahmedali', 23, 27, 'پھر ہم نے اس کی طرف وحی کی کہ ہماری آنکھوں کے سامنے اور ہمارے حکم سے کشتی بنا پھر جب ہمارا حکم آ پہنچے اور تنور ابلنے لگے پس تو کشتی میں ہر چیز کا جوڑا نر مادہ اور اپنے گھر والوں کو بٹھا لے مگر ان میں سے وہ شخص جس کے لیے پہلے فیصلہ ہو چکا ہے او رظالموں کے معاملہ میں مجھ سے بات نہ کر بے شک وہ غرق کیے جائیں گے'),
  ('ur.ahmedali', 23, 28, 'پھر جب تو اور جو تیرے ساتھ ہے کشتی پر چڑھ بیٹھو تو کہہ الله کا شکر ہے جس نے ہمیں ظالموں سے چھوڑایا'),
  ('ur.ahmedali', 23, 29, 'اور کہہ اے میرے رب مجھے برکت کے ساتھ اتار اور تو بہتر اتارنے والا ہے'),
  ('ur.ahmedali', 23, 30, 'اس واقعہ میں بہت سی نشانیاں ہیں بے شک ہم تو آزمائش کرنے والے تھے'),
  ('ur.ahmedali', 23, 31, 'پھر ہم نے انکے بعد ایک دوسرا دور پیدا کیا'),
  ('ur.ahmedali', 23, 32, 'پھر ان میں بھی انہیں میں سے ایک رسول بھیجا کہ الله کی عبادت کرو تمہارے لیے اس کے سوا اورکوئی معبود نہیں پھر تم کیوں نہیں ڈرتے'),
  ('ur.ahmedali', 23, 33, 'اوراس کی قوم کے سرداروں نے کہا جنہوں نے کفر کیا تھا اور قیامت کی آمد کو جھٹلاتے تھے اور جنہیں ہم نے دنیا کی زندگی میں آسودہ کر رکھا تھا کہ یہ بس تمہیں جیسا آدمی ہے وہی کھاتا ہے جو تم کھاتے ہو اور وہی پیتا ہے جو تم پیتے ہو'),
  ('ur.ahmedali', 23, 34, 'اوراگر تم نےاپنے جیسے آدمی کی فرمانبرداری کی توبے شک تم گھاٹے میں پڑ گئے'),
  ('ur.ahmedali', 23, 35, 'کیا تمہیں وعدہ دیتا ہے کہ جب تم مر جاؤ گے اورمٹی اور ہڈیاں ہو جاؤ گے تو تم نکالے جاؤ گے'),
  ('ur.ahmedali', 23, 36, 'بہت ہی بعید بہت ہی بعید بات ہے جو تم سے کہی جاتی ہے'),
  ('ur.ahmedali', 23, 37, 'ہماری صرف یہی دنیا کی زندگی ہے مرتے اور جیتےہیں اور ہم اٹھائے نہیں جائیں گے'),
  ('ur.ahmedali', 23, 38, 'بس یہ ایک ایسا شخص ہے جو الله پر جھوٹ باندھتا ہے اور ہم اسے ماننے والے نہیں ہیں'),
  ('ur.ahmedali', 23, 39, 'کہا اے میرے رب میری مدد کر کہ انہو ں نے مجھے جھٹلایا ہے'),
  ('ur.ahmedali', 23, 40, 'فرمایا تھوڑی دیر کے بعد یہ خود نادم ہوں گے'),
  ('ur.ahmedali', 23, 41, 'پھر انہیں ایک سخت آواز نے سچے وعدہ کا موافق آ پکڑا پھر ہم نے انہیں خس و خاشاک کر دیا پھر ظالموں پر الله کی پٹکار ہے'),
  ('ur.ahmedali', 23, 42, 'پھر ہم نے ان کے بعد اوربہت سے دور پیدا کیے'),
  ('ur.ahmedali', 23, 43, 'کوئی جماعت نہ اپنے وقت سے آگے بڑھ سکتی ہے نہ پیچھے ہٹ سکتی ہے'),
  ('ur.ahmedali', 23, 44, 'پھر ہم اپنے رسول لگاتار بھیجتے رہے جب کوئی رسول اپنی قوم کے پاس آیا وہ اسے جھٹلاتی ہی رہی پھر ہم بھی ایک کے بعد دوسری کو ہلاک کرتے گئے اور ہم نے ان کو افسانے بنا دیے پھر ان لوگوں پر پھٹکار ہے جو ایمان نہیں لاتے'),
  ('ur.ahmedali', 23, 45, 'پھر ہم نے موسیٰ اور اس کے بھائی ہارون کو اپنی نشانیاں اور کھلی سند دے کر'),
  ('ur.ahmedali', 23, 46, 'فرعون اور اس کے سرداروں کے پاس بھیجا پھر انہوں نے تکبر کیا اور وہ سرکش لوگ تھے'),
  ('ur.ahmedali', 23, 47, 'پھر کہا کیا ہم اپنے جیسے دو شخصوں پر ایمان لائیں جن کی قوم ہماری غلامی کر رہی ہو'),
  ('ur.ahmedali', 23, 48, 'پھر ان دونوں کو جھٹلایا پھر ہلاک کر دیے گئے'),
  ('ur.ahmedali', 23, 49, 'اور البتہ ہم نے موسیٰ کو کتاب دی تھی تاکہ وہ ہدایت پائیں'),
  ('ur.ahmedali', 23, 50, 'اور ہم نے مریم کے بیٹے اور اس کی ماں کو نشانی بنایا تھا اور انہیں ایک ٹیلہ پر جگہ دی جہاں ٹھیرےنے کا موقع اور پانی جاری تھا'),
  ('ur.ahmedali', 23, 51, 'ا ے رسولو! ستھری چیزیں کھاؤ اور اچھے کام کرو بے شک میں جانتا ہوں جو تم کرتے ہو'),
  ('ur.ahmedali', 23, 52, 'اور بے شک یہ تمہاری جماعت ایک ہی جماعت ہے اور میں تم سب کا رب ہوں پس مجھ سے ڈرو'),
  ('ur.ahmedali', 23, 53, 'پھر انہوں نے اپنے دین کو آپس میں ٹکڑے ٹکڑے کر لیا ہر ایک جماعت اس ٹکڑے پو جو ان کے پاس ہے خوش ہونے والے ہیں'),
  ('ur.ahmedali', 23, 54, 'پھر ایک وقت تک انہیں اپنے نشہ میں پڑا رہنے دو'),
  ('ur.ahmedali', 23, 55, 'کیا وہ یہ خیال کرتے ہیں کہ ہم انہیں مال اور اولاد میں ترقی دے رہے ہیں'),
  ('ur.ahmedali', 23, 56, 'انہیں فائدہ پہچانے میں جلدی کر رہے ہیں بلکہ یہ نہیں سمجھتے'),
  ('ur.ahmedali', 23, 57, 'بے شک جو اپنے رب کی ہیبت سے ڈرنے والے ہیں'),
  ('ur.ahmedali', 23, 58, 'اور جو اپنے رب کی آیتوں پر ایمان لاتے ہیں'),
  ('ur.ahmedali', 23, 59, 'اور جو اپنے رب کے ساتھ کسی کو شریک نہیں کرتے'),
  ('ur.ahmedali', 23, 60, 'اور جو دیتے ہیں جو کچھ دیتے ہیں اور ان کے دل اس سے ڈرتے ہیں کہ وہ اپنے رب کی طرف لوٹنے والے ہیں'),
  ('ur.ahmedali', 23, 61, 'یہی لوگ نیک کامو ں میں جلدی کرتے ہیں اور وہی نیکیوں میں آگے بڑھنے والے ہیں'),
  ('ur.ahmedali', 23, 62, 'اور ہم کسی پر اس کی طاقت سے بڑھ کر بوجھ نہیں ڈالتے اور ہمارے پاس ایک کتاب ہے جو سچ بولے گی اور ان پر ظلم نہیں کیا جائے گا'),
  ('ur.ahmedali', 23, 63, 'بلکہ ان کے دل اس سے بے ہوشی میں پڑے ہوئے ہیں اوراس کے سوا ان کے اوربھی کام ہیں کہ جنہیں وہ کیا کرتے ہیں'),
  ('ur.ahmedali', 23, 64, 'یہاں تک کہ جب ہم ان میں سے آسودہ حال لوگوں کو عذاب میں پکڑیں گے فوراً وہ چلائیں گے'),
  ('ur.ahmedali', 23, 65, 'آج کے دن مت چلاؤ بے شک تم ہم سے چھڑائے نہ جاؤ گے'),
  ('ur.ahmedali', 23, 66, 'تمہیں میری آیتیں سنائی جاتی تھیں پھر تم ایڑیوں پر الٹے بھاگتے تھے'),
  ('ur.ahmedali', 23, 67, 'غرور میں آ کر اسے کہانی سمجھ کر چلے جایا کرتے تھے'),
  ('ur.ahmedali', 23, 68, 'کیا انہوں نے اس ارشاد میں غور ہی نہیں کیا یا ان کے پاس ایسی بات آئی ہے جو ان کے پہلے باپ دادا کے پاس نہیں آئی تھی'),
  ('ur.ahmedali', 23, 69, 'یا یہ لوگ اپنے رسول کو پہچانتے نہیں تب یہ اس کے منکر ہیں'),
  ('ur.ahmedali', 23, 70, 'یا کہتے ہیں کہ اسے جنون ہے بلکہ رسول ان کے پاس حق بات لے کر آیا ہے اور ان میں سے اکثر حق کو ناپسند کرنے والے ہیں'),
  ('ur.ahmedali', 23, 71, 'اوراگر حق ان کی خواہشوں کے مطابق ہوتا تو آسمان اور زمین میں اورجو کچھ ان میں ہے درہم برہم ہو گیا ہوتا بلکہ ہم نے تو ان کی نصیحت انہیں پہنچا دی ہے سو وہ اپنی نصیحت سے منہ موڑنے والے ہیں'),
  ('ur.ahmedali', 23, 72, 'کیا تو ان سے کچھ اجرت مانگتا ہے سو تیرے رب کی اجرت بہتر ہے اور وہی سب سے بہتر روزی دینے والا ہے'),
  ('ur.ahmedali', 23, 73, 'اوربے شک تو انہیں سیدھے راستہ کی طرف بلاتا ہے'),
  ('ur.ahmedali', 23, 74, 'اور جو لوگ آخرت کو نہیں مانتے سیدھے راستہ سے ہٹنے والے ہیں'),
  ('ur.ahmedali', 23, 75, 'اور اگر ہم ا ن پر رحم کر کے ان کی تکلیف کو دور کر دیں تو بھی وہ اپنی سرکشی میں گمراہ پڑے رہیں گے'),
  ('ur.ahmedali', 23, 76, 'اور البتہ ہم نے انہیں عذاب میں مبتلا بھی کیا پھر بھی اپنے رب کے سامنے عاجزی نہ کی اورنہ گڑگڑائے'),
  ('ur.ahmedali', 23, 77, 'یہاں تک کہ جب ہم نے ان پر سخت عذاب کا دروازہ کھولا تو فوراً اس میں نا امید ہوگئے'),
  ('ur.ahmedali', 23, 78, 'اور اسی نے تمہارے کان اور آنکھیں اور دل بنائےہیں تم بہت ہی کم شکر کرتے ہو'),
  ('ur.ahmedali', 23, 79, 'اور اسی نے تمہیں زمین میں پھیلا رکھا ہے اور اسی کی طرف جمع کیے جاؤ گے'),
  ('ur.ahmedali', 23, 80, 'اور وہی زندہ کرتا ہے اورمارتا ہے اور رات اور دن کا بدلنا اسی کی اختیار میں ہے سو کیا تم نہیں سمجھتے'),
  ('ur.ahmedali', 23, 81, 'بلکہ وہی کہتے ہیں جو پہلے لوگ کہتے تھے'),
  ('ur.ahmedali', 23, 82, 'کہتے ہیں کیا جب ہم مرجائیں گے اور مٹی اور ہڈیاں ہو جائیں گے تو کیا ہم دوبارہ زندہ کیے جائیں گے'),
  ('ur.ahmedali', 23, 83, 'اس کا تو ہم سے اوراس سے پہلے اور ہمارے باپ دادا سے وعدہ ہوتا چلاآیا ہے یہ صرف اگلےلوگوں کی کہانیاں ہیں'),
  ('ur.ahmedali', 23, 84, 'ان سے پوچھو یہ زمین اور جو کچھ اس میں ہے کس کا ہے اگر تم جانتے ہو'),
  ('ur.ahmedali', 23, 85, 'وہ فوراً کہیں گے الله کاہے کہہ دو پھر تم کیوں نہیں سمجھتے'),
  ('ur.ahmedali', 23, 86, 'ان سے پوچھو کہ ساتوں آسمانوں اور عرش عظیم کا مالک کون ہے'),
  ('ur.ahmedali', 23, 87, 'وہ فوراً کہیں گے الله ہے کہہ دوکیاپھر تم الله سے نہیں ڈرتے'),
  ('ur.ahmedali', 23, 88, 'ان سے پوچھو کہ ہر چیز کی حکومت کس کے ہاتھ میں ہے اور وہ بچا لیتا ہے اور اسے کوئی نہیں بچا سکتا اگر تم جانتے ہو'),
  ('ur.ahmedali', 23, 89, 'وہ فوراً کہیں گے الله ہی کے ہاتھ میں ہے کہہ دو پھرتم کیسے دیوانے ہو رہے ہو'),
  ('ur.ahmedali', 23, 90, 'بلکہ ہم نے تو ان کے پاس حق بات پہنچا دی اور بے شک وہ البتہ جھوٹے ہیں'),
  ('ur.ahmedali', 23, 91, 'الله نے کوئی بھی بیٹا نہیں بنایا اورنہ اس کے ساتھ کوئی معبود ہی ہے اگر ہوتا تو ہر خدا اپنی بنائی ہوئی چیز کو الگ لے جاتا اور ایک دوسرے پر چڑھائی کرتا الله پاک ہے جو یہ بیان کرتے ہیں'),
  ('ur.ahmedali', 23, 92, 'غائب اور حاضر سب کا جاننے والا ہے وہ بہت بلند ہے اس سے جسے یہ شریک بناتے ہیں'),
  ('ur.ahmedali', 23, 93, 'کہہ دو اے میرے رب اگر تو مجھے دکھائے وہ چیز جس کا انہیں وعدہ دیا جارہا ہے'),
  ('ur.ahmedali', 23, 94, 'تو اے میرے رب مجھے ظالموں میں شامل نہ کر'),
  ('ur.ahmedali', 23, 95, 'اور ہم اس پر قادر ہیں کہ تجھے دکھا دیں جو ہم نے ان سے وعدہ کیا ہے'),
  ('ur.ahmedali', 23, 96, 'بری بات کے جواب میں وہ کہو جو بہتر ہے ہم خوب جانتے ہیں جو یہ بیان کرتے ہیں'),
  ('ur.ahmedali', 23, 97, 'اور کہواے میرے رب میں شیطانی خطرات سے تیری پناہ مانگتا ہوں'),
  ('ur.ahmedali', 23, 98, 'اوراےمیرے رب میں تیری پناہ چاہتا ہوں اس سے کہ شیطان میرے پاس آئيں'),
  ('ur.ahmedali', 23, 99, 'یہاں تک کہ جب ان میں سے کسی کو موت آئے گی تو کہے گا اے میرے رب مجھے پھر بھیج دے'),
  ('ur.ahmedali', 23, 100, 'تاکہ جسے میں چھوڑ آیا ہوں اس میں نیک کام کر لوں ہر گز نہیں ایک بات ہی بات ہے جسے یہ کہہ رہا ہے اور ان کے آگے قیامت تک ایک پردہ پڑا ہوا ہے'),
  ('ur.ahmedali', 23, 101, 'پھر جب صور پھونکا جائے گا تو اس دن ان میں نہ رشتہ داریاں رہیں گے اور نہ کوئی کسی کو پوچھے گا'),
  ('ur.ahmedali', 23, 102, 'پھر جن کا پلہ بھاری ہوا تو وہی فلاح پائیں گے'),
  ('ur.ahmedali', 23, 103, 'اورجن کا پلہ ہلکا ہوگا تو وہی یہ لوگ ہوں گے جنہوں نے اپنا نقصان کیا ہمیشہ جہنم میں رہنے والے ہوں گے'),
  ('ur.ahmedali', 23, 104, 'ان کے مونہوں کو آگ جھلس دے گی اور وہ اس میں بدشکل ہونے والے ہوں گے'),
  ('ur.ahmedali', 23, 105, 'کیا تمہیں ہماری آیتیں نہیں سنائی جاتی تھیں پھر تم انہیں جھٹلاتے تھے'),
  ('ur.ahmedali', 23, 106, 'کہیں گے اے ہمارے رب ہم پر ہماری بدبختی غالب آگئی تھی اور ہم لوگ گمراہ تھے'),
  ('ur.ahmedali', 23, 107, 'اے رب ہمارے ہمیں اس سے نکال دے اگر پھر کریں تو بے شک ہم ظالم ہوں گے'),
  ('ur.ahmedali', 23, 108, 'فرمائے گا اس میں پھٹکارے ہوئے پڑے رہو اور مجھ سے نہ بولو'),
  ('ur.ahmedali', 23, 109, 'میرے بندوں میں سے ایک گروہ تھا جو کہتے تھے اے ہمارے رب ہم ایمان لائے تو ہمیں بخش دے اور ہم پر رحم کرو اور تو بہت بڑا رحم کرنے والا ہے'),
  ('ur.ahmedali', 23, 110, 'سو تم نے ان کی ہنسی اڑائی یہا ں تک کہ انہوں نے تمہیں میری یاد بھی بھلادی اور تم ان سے ہنسی ہی کرتے رہے'),
  ('ur.ahmedali', 23, 111, 'آج میں نے انہیں ان کے صبر کا بدلہ دیا کہ وہی کامیاب ہوئے'),
  ('ur.ahmedali', 23, 112, 'فرمائے گا تم زمین پر گنتی کے کتنےبرس رہے'),
  ('ur.ahmedali', 23, 113, 'کہیں گے ایک دن یا اس سے بھی کم رہے ہیں پس آپ گنتی کرنے والوں سے پوچھ لیں'),
  ('ur.ahmedali', 23, 114, 'فرمائے گا تم اس میں بہت نہیں تھوڑا ہی رہے ہو کاش کہ تم سمجھ لیتے'),
  ('ur.ahmedali', 23, 115, 'سو کیا تم یہ خیال کرتے ہو کہ ہم نے تمہیں نکما پیدا کیا ہے اور یہ کہ تم ہمارے پاس لوٹ کر نہیں آؤ گے'),
  ('ur.ahmedali', 23, 116, 'سو الله بہت ہی عالیشان ہے جو حقیقی بادشاہ ہے اس کے سوا اور کوئی معبود نہیں عرش عظیم کا مالک ہے'),
  ('ur.ahmedali', 23, 117, 'اور جس نے الله کے ساتھ اور معبو کو پکارا جس کی اس کے پاس کوئی سند نہیں تو اس کا حساب اسی کے رب کے ہاں ہوگا بے شک کافر نجات نہیں پائیں گے'),
  ('ur.ahmedali', 23, 118, 'اورکہو اے میرے رب معاف کر اور رحم کر اور تو سب سے بہتر رحم کرنے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 23, 1, 'Müminler saadete ermişlerdir.'),
  ('tr.diyanet', 23, 2, 'Onlar namazda huşu içindedirler.'),
  ('tr.diyanet', 23, 3, 'Onlar boş şeylerden yüz çevirirler.'),
  ('tr.diyanet', 23, 4, 'Onlar zekatlarını verirler.'),
  ('tr.diyanet', 23, 5, 'Onlar, eşleri ve cariyeleri dışında, mahrem yerlerini herkesten korurlar. Doğrusu bunlar yerilemezler.'),
  ('tr.diyanet', 23, 6, 'Onlar, eşleri ve cariyeleri dışında, mahrem yerlerini herkesten korurlar. Doğrusu bunlar yerilemezler.'),
  ('tr.diyanet', 23, 7, 'Bu sınırları aşmak isteyenler, işte bunlar aşırı gidenlerdir.'),
  ('tr.diyanet', 23, 8, 'Onlar emanetlerini ve sözlerini yerine getirirler.'),
  ('tr.diyanet', 23, 9, 'Namazlarına riayet ederler.'),
  ('tr.diyanet', 23, 10, 'İşte onlar, temelli kalacakları Firdevs cennetine varis olanlardır.'),
  ('tr.diyanet', 23, 11, 'İşte onlar, temelli kalacakları Firdevs cennetine varis olanlardır.'),
  ('tr.diyanet', 23, 12, 'And olsun ki, insanı süzme çamurdan yarattık.'),
  ('tr.diyanet', 23, 13, 'Sonra onu nutfe halinde sağlam bir yere yerleştirdik.'),
  ('tr.diyanet', 23, 14, 'Sonra nutfeyi kan pıhtısına çevirdik, kan pıhtısını bir çiğnemlik et yaptık, bir çiğnemlik etten kemikler yarattık, kemiklere de et giydirdik. Sonra onu başka bir yaratık yaptık: Biçim verenlerin en güzeli olan Allah ne uludur!'),
  ('tr.diyanet', 23, 15, 'Sizler, bütün bunlardan sonra ölürsünüz.'),
  ('tr.diyanet', 23, 16, 'Şüphesiz kıyamet günü tekrar diriltilirsiniz.'),
  ('tr.diyanet', 23, 17, 'And olsun ki, üstünüzde yedi tabaka yarattık. Biz, yarattığımızdan habersiz değiliz.'),
  ('tr.diyanet', 23, 18, 'Gökten suyu ölçülü indirdik de, onu yerde durdurduk. Şüphesiz onu gidermeye de kadiriz.'),
  ('tr.diyanet', 23, 19, 'Onunla, içinde, yediğiniz birçok meyvalar bulunan hurmalık ve üzüm bağları, Tur-i Sina\'da yetişen, yiyenlere, yağ ve katık veren zeytin ağacını var ettik.'),
  ('tr.diyanet', 23, 20, 'Onunla, içinde, yediğiniz birçok meyvalar bulunan hurmalık ve üzüm bağları, Tur-i Sina\'da yetişen, yiyenlere, yağ ve katık veren zeytin ağacını var ettik.'),
  ('tr.diyanet', 23, 21, 'Ehli hayvanlarda size ders vardır; onlardan çıkan sütten size içiririz; onlarda daha birçok menfaatiniz vardır. Onlardan yersiniz.'),
  ('tr.diyanet', 23, 22, 'Hem onların ve hem de gemilerin üzerinde taşınırsınız.'),
  ('tr.diyanet', 23, 23, 'And olsun ki Nuh\'u milletine gönderdik; onlara: "Ey milletim! Allah\'a kulluk edin; O\'ndan başka tanrınız yoktur; sakınmaz mısınız?" dedi.'),
  ('tr.diyanet', 23, 24, 'Milletinin inkarcı ileri gelenleri: "Bu, sizin gibi bir insandan başka birşey değildir. Sizden üstün olmak istiyor. Allah dilemiş olsaydı melekler indirirdi. İlk atalarımızdan beri böyle birşey işitmedik. Bu adamda nedense biraz delilik var, bir süreye kadar onu gözetleyin" dediler.'),
  ('tr.diyanet', 23, 25, 'Milletinin inkarcı ileri gelenleri: "Bu, sizin gibi bir insandan başka birşey değildir. Sizden üstün olmak istiyor. Allah dilemiş olsaydı melekler indirirdi. İlk atalarımızdan beri böyle birşey işitmedik. Bu adamda nedense biraz delilik var, bir süreye kadar onu gözetleyin" dediler.'),
  ('tr.diyanet', 23, 26, 'Nuh: "Rabbim! Beni yalanlamalarına karşılık bana yardım et" dedi.'),
  ('tr.diyanet', 23, 27, 'Bunun üzerine ona şöyle vahyettik: "Nezaretimiz altında, sana bildirdiğimiz gibi gemiyi yap; buyruğumuz gelip tandırdan sular kaynayınca her cinsten birer çifti ve aleyhine hüküm verilmiş olanın dışında kalan çoluk çocuğunu alıp gemiye bindir. Haksızlık yapanlar için Bana baş vurma, çünkü onlar suda boğulacaklardır."'),
  ('tr.diyanet', 23, 28, 'Ey Nuh! Sen ve beraberindekiler gemiye yerleşince: "Bizi zalim milletten kurtaran Allah\'a hamdolsun" de.'),
  ('tr.diyanet', 23, 29, '"Rabbim! Beni mübarek bir yere indir. Sen indirenlerin en iyisisin" de.'),
  ('tr.diyanet', 23, 30, 'Doğrusu bunlarda dersler vardır. Biz şüphesiz insanları denemekteyiz.'),
  ('tr.diyanet', 23, 31, 'Bunların ardından başka nesiller varettik.'),
  ('tr.diyanet', 23, 32, 'Onlara aralarından: "Allah"a kulluk edin, O\'ndan başka tanrınız yoktur, sakınmaz mısınız?" diyen bir elçi gönderdik.'),
  ('tr.diyanet', 23, 33, 'Onun, inkarcı ve ahirete kavuşmayı yalanlayan milletinin ileri gelenleri ki Biz onlara bu dünya hayatında nimet vermiştik şöyle dediler: "Bu, yediğinizden yiyen, içtiğinizden içen sizin gibi bir insandan başka birşey değildir."'),
  ('tr.diyanet', 23, 34, '"Kendiniz gibi bir insana itaat ederseniz hüsrana uğrayacağınızda hiç şüphe yoktur."'),
  ('tr.diyanet', 23, 35, '"Öldüğünüz, toprak ve kemik yığını olduğunuz zaman tekrar dirilmenizle sizi tehdit mi ediyor?"'),
  ('tr.diyanet', 23, 36, '"Oysa tehdit edildiğiniz şey ne kadar, hem de ne kadar uzak!"'),
  ('tr.diyanet', 23, 37, '"Hayat ancak bu dünyadakidir. Ölürüz ve yaşarız (kimimiz ölür kimimiz doğar); tekrar diriltilmeyiz."'),
  ('tr.diyanet', 23, 38, '"Bu, sadece Allah\'a karşı yalan uyduranın biridir. Biz ona inanmayız."'),
  ('tr.diyanet', 23, 39, 'O peygamber: "Rabbim! Beni yalancı saymalarına karşılık bana yardım et" dedi.'),
  ('tr.diyanet', 23, 40, 'Allah da: "Az sonra pişman olacaklar" buyurdu.'),
  ('tr.diyanet', 23, 41, 'Gerçekten, onları bir çığlık yakaladı ve onları süprüntü yığını haline getirdik. Haksızlık eden millet, rahmetden ırak olsun!'),
  ('tr.diyanet', 23, 42, 'Ardlarından başka nesiller varettik.'),
  ('tr.diyanet', 23, 43, 'Hiçbir ümmet, kendi süresini ne çabuklaştırabilir ve ne de geciktirebilir.'),
  ('tr.diyanet', 23, 44, 'Sonra birbiri peşinden peygamberlerimizi gönderdik. Her ümmete peygamberi geldikçe onu yalancı saydılar. Onları birbiri peşinden yok edip hepsini birer efsane yaptık. İnanmayan millet, rahmetden ırak olsun!'),
  ('tr.diyanet', 23, 45, 'Sonra Musa ve kardeşi Harun\'u, Firavun ve erkanına mucizelerimiz ve apaçık delille gönderdik. Büyüklük tasladılar. Zaten mağrur bir topluluktular.'),
  ('tr.diyanet', 23, 46, 'Sonra Musa ve kardeşi Harun\'u, Firavun ve erkanına mucizelerimiz ve apaçık delille gönderdik. Büyüklük tasladılar. Zaten mağrur bir topluluktular.'),
  ('tr.diyanet', 23, 47, 'Bu yüzden: "Milletleri bize kul iken, bizim gibi iki insana mı inanacağız?" deyip onları yalancı saydılar. Bu yüzden yok edildiler.'),
  ('tr.diyanet', 23, 48, 'Bu yüzden: "Milletleri bize kul iken, bizim gibi iki insana mı inanacağız?" deyip onları yalancı saydılar. Bu yüzden yok edildiler.'),
  ('tr.diyanet', 23, 49, 'And olsun ki Musa\'ya, doğru yola girsinler diye Kitap verdik.'),
  ('tr.diyanet', 23, 50, 'Meryem oğlunu da, annesini de mucize kıldık. Her ikisini de, pınarı bulunan, oturmaya elverişli yüksek bir yere yerleştirdik.'),
  ('tr.diyanet', 23, 51, 'Ey Peygamberler! Temiz şeylerden yiyin, yararlı iş işleyin; doğrusu Ben, yaptığınızı bilirim.'),
  ('tr.diyanet', 23, 52, 'Şüphesiz bu Müslümanlık, bir tek din olarak sizin dininizdir ve Ben de Rabbinizim; öyleyse Benden sakının.'),
  ('tr.diyanet', 23, 53, 'Ama insanlar din konusunda aralarında bölük bölük oldular. Her bölük kendi tuttuğu yoldan memnundur.'),
  ('tr.diyanet', 23, 54, 'Onları bir süreye kadar sapıklıklarıyla başbaşa bırak.'),
  ('tr.diyanet', 23, 55, 'Kendilerine mal ve oğullar vermekle, iyiliklerde onlar için acele ettiğimizi mi zannederler? Hayır; farkında değiller.'),
  ('tr.diyanet', 23, 56, 'Kendilerine mal ve oğullar vermekle, iyiliklerde onlar için acele ettiğimizi mi zannederler? Hayır; farkında değiller.'),
  ('tr.diyanet', 23, 57, 'Rablerinden korkarak titreyenler, Rablerinin ayetlerine inananlar, Rablerine eş koşmayanlar, Rablerine dönecekleri için kalbleri ürpererek vermeleri gerekeni verenler, işte onlar iyi işlerde yarış ederler, o uğurda ileri geçerler.'),
  ('tr.diyanet', 23, 58, 'Rablerinden korkarak titreyenler, Rablerinin ayetlerine inananlar, Rablerine eş koşmayanlar, Rablerine dönecekleri için kalbleri ürpererek vermeleri gerekeni verenler, işte onlar iyi işlerde yarış ederler, o uğurda ileri geçerler.'),
  ('tr.diyanet', 23, 59, 'Rablerinden korkarak titreyenler, Rablerinin ayetlerine inananlar, Rablerine eş koşmayanlar, Rablerine dönecekleri için kalbleri ürpererek vermeleri gerekeni verenler, işte onlar iyi işlerde yarış ederler, o uğurda ileri geçerler.'),
  ('tr.diyanet', 23, 60, 'Rablerinden korkarak titreyenler, Rablerinin ayetlerine inananlar, Rablerine eş koşmayanlar, Rablerine dönecekleri için kalbleri ürpererek vermeleri gerekeni verenler, işte onlar iyi işlerde yarış ederler, o uğurda ileri geçerler.'),
  ('tr.diyanet', 23, 61, 'Rablerinden korkarak titreyenler, Rablerinin ayetlerine inananlar, Rablerine eş koşmayanlar, Rablerine dönecekleri için kalbleri ürpererek vermeleri gerekeni verenler, işte onlar iyi işlerde yarış ederler, o uğurda ileri geçerler.'),
  ('tr.diyanet', 23, 62, 'Biz herkese ancak gücünün yeteceği kadar yükleriz. Katımızda gerçeği söyleyen bir kitap vardır; onlar haksızlığa uğratılmazlar.'),
  ('tr.diyanet', 23, 63, 'Ama, kafirlerin kalbleri bundan habersizdir. Bundan başka da onların yapageldikleri işler de vardır.'),
  ('tr.diyanet', 23, 64, 'Sonunda şımarık varlıklılarını azabla yakaladığımız zaman feryat ederler.'),
  ('tr.diyanet', 23, 65, 'Onlara şöyle deriz: "Bugün feryat etmeyin, doğrusu katımızdan bir yardım görmezsiniz."'),
  ('tr.diyanet', 23, 66, '"Ayetlerim size okunduğunda büyüklük taslayıp, gece ağzınıza geleni söyleyerek ardınıza dönüyordunuz."'),
  ('tr.diyanet', 23, 67, '"Ayetlerim size okunduğunda büyüklük taslayıp, gece ağzınıza geleni söyleyerek ardınıza dönüyordunuz."'),
  ('tr.diyanet', 23, 68, 'Söyleneni hiç düşünmezler mi? Yoksa onlara, ilk atalarına gelmeyen bir şey mi geldi?'),
  ('tr.diyanet', 23, 69, 'Veya peygamberlerini tanımadılar da; bu yüzden mi onu inkar ediyorlar?'),
  ('tr.diyanet', 23, 70, 'Ya da: "Onda delilik var" diyorlar öyle mi? Hayır; onlara gerçeği getirmiştir, ama çoğu ondan hoşlanmamaktadır.'),
  ('tr.diyanet', 23, 71, 'Eğer gerçek onların heveslerine uysaydı, gökler, yer ve onlarda bulananlar bozulup giderdi. Onlara, kendilerine öğüt veren bir şey getirdik; onlar ise öğütlerinden yüz çevirirler.'),
  ('tr.diyanet', 23, 72, 'Yoksa sen onlardan bir ücret mi istiyorsun? Rabbinin ecri daha iyidir. O, rızık verenlerin en hayırlısıdır.'),
  ('tr.diyanet', 23, 73, 'Aslında sen onları doğru yola çağırıyorsun ama, ahirete inanmayanlar bu yoldan sapmaktadırlar.'),
  ('tr.diyanet', 23, 74, 'Aslında sen onları doğru yola çağırıyorsun ama, ahirete inanmayanlar bu yoldan sapmaktadırlar.'),
  ('tr.diyanet', 23, 75, 'Biz onlara acısak ve başlarındaki sıkıntıyı gidersek bile, azgınlıkları içinde bocalayıp kalırlar.'),
  ('tr.diyanet', 23, 76, 'And olsun ki, Biz onları azabla yakalamıştık, yine de Rablerine boyun eğmemiş ve yakarmamışlardı.'),
  ('tr.diyanet', 23, 77, 'Sonunda onlara şiddetli bir azap kapısı açtığımız zaman ümitsiz kalıverdiler.'),
  ('tr.diyanet', 23, 78, 'Oysa, sizin için kulaklar, gözler ve kalbler vareden O\'dur. Pek az şükrediyorsunuz.'),
  ('tr.diyanet', 23, 79, 'Sizi yerde yaratıp yayan O\'dur ve O\'nun huzurunda toplanacaksınız.'),
  ('tr.diyanet', 23, 80, 'Dirilten de, öldüren de O\'dur. Gece ile gündüzün birbiri ardından gitmesi de O\'nun emrine bağlıdır. Düşünmez misiniz?'),
  ('tr.diyanet', 23, 81, 'Hayır; yine de öncekilerin dediklerini derler.'),
  ('tr.diyanet', 23, 82, 'Öncekiler: "Ölüp toprak ve bir yığın kemik olduğumuzda mı diriltileceğiz? And olsun ki biz ve daha önce de babalarımız tehdit edilmişti; bu, öncekilerin masallarından başka birşey değildir" demişlerdi.'),
  ('tr.diyanet', 23, 83, 'Öncekiler: "Ölüp toprak ve bir yığın kemik olduğumuzda mı diriltileceğiz? And olsun ki biz ve daha önce de babalarımız tehdit edilmişti; bu, öncekilerin masallarından başka birşey değildir" demişlerdi.'),
  ('tr.diyanet', 23, 84, 'De ki: "Biliyorsanız söyleyin, yer ve onda bulunanlar kimindir?"'),
  ('tr.diyanet', 23, 85, '"Allah\'ındır" diyecekler, "Öyleyse ders almaz mısınız?" de.'),
  ('tr.diyanet', 23, 86, '"Yedi göğün de Rabbi, yüce arşın da Rabbi kimdir?" de.'),
  ('tr.diyanet', 23, 87, '"Allah\'tır" diyecekler! "Öyleyse O\'na karşı gelmekten sakınmaz mısınız?" de.'),
  ('tr.diyanet', 23, 88, '"Biliyorsanız söyleyin her şeyin hükümranlığı elinde olan, barındıran fakat himayeye muhtaç olmayan kimdir?"'),
  ('tr.diyanet', 23, 89, '"Allah\'tır" diyecekler; "Öyleyse nasıl aldanıyorsunuz" de.'),
  ('tr.diyanet', 23, 90, 'Hayır; Biz onlara gerçeği getirdik ama, onlar yalancıdırlar.'),
  ('tr.diyanet', 23, 91, 'Allah çocuk edinmemiştir; O\'nun yanında hiçbir tanrı yoktur, olsaydı, her tanrı kendi yarattığı ile beraber gider ve birbirinden üstün olmağa çalışırlardı. Allah onların vasıflandırdıklarından münezzehtir.'),
  ('tr.diyanet', 23, 92, 'O, görülmeyeni de, görüleni de bilir. Koştukları ortaklardan yücedir.'),
  ('tr.diyanet', 23, 93, 'De ki: "Rabbim! Onların tehdit olundukları şeyi bana mutlaka göstereceksen, o zaman beni zalim milletin içinde bulundurma Yarabbi."'),
  ('tr.diyanet', 23, 94, 'De ki: "Rabbim! Onların tehdit olundukları şeyi bana mutlaka göstereceksen, o zaman beni zalim milletin içinde bulundurma Yarabbi."'),
  ('tr.diyanet', 23, 95, 'Biz onlara vadettiğimizi sana elbette gösterebiliriz.'),
  ('tr.diyanet', 23, 96, 'Kötülüğü en iyi ile sav. Onların vasıflandırmalarını Biz daha iyi biliriz.'),
  ('tr.diyanet', 23, 97, 'De ki: "Rabbim! Şeytanların kışkırtmalarından Sana sığınırım."'),
  ('tr.diyanet', 23, 98, '"Rabbim! Yanımda bulunmalarından da Sana sığınırım."'),
  ('tr.diyanet', 23, 99, 'Onlardan birine ölüm gelince: "Rabbim! Beni geri çevir, belki, yapmadan bıraktığımı tamamlar, iyi iş işlerim" der. Hayır; bu söylediği sadece kendi lafıdır. Tekrar diriltilecekleri güne kadar arkalarında geriye dönmekten onları alıkoyan bir engel vardır.'),
  ('tr.diyanet', 23, 100, 'Onlardan birine ölüm gelince: "Rabbim! Beni geri çevir, belki, yapmadan bıraktığımı tamamlar, iyi iş işlerim" der. Hayır; bu söylediği sadece kendi lafıdır. Tekrar diriltilecekleri güne kadar arkalarında geriye dönmekten onları alıkoyan bir engel vardır.'),
  ('tr.diyanet', 23, 101, 'Sura üflendiği zaman, o gün, aralarındaki soy yakınlığı fayda vermez ve birbirlerine de birşey soramazlar.'),
  ('tr.diyanet', 23, 102, 'Tartıları ağır gelenler, işte onlar kurtuluşa ermiş olanlardır.'),
  ('tr.diyanet', 23, 103, 'Tartıları hafif gelenler, işte onlar, kendilerine yazık edendir, cehennemde temellidirler.'),
  ('tr.diyanet', 23, 104, 'Ateş onların yüzlerini yalar, dişleri sırıtıp kalır.'),
  ('tr.diyanet', 23, 105, 'Allah: "Ayetlerim size okunurken onları yalanlıyordunuz değil mi?" der.'),
  ('tr.diyanet', 23, 106, 'Şöyle derler: "Rabbimiz! Bizi bedbahtlığımız yenmişti; sapık bir millet olmuştuk."'),
  ('tr.diyanet', 23, 107, '"Rabbimiz! Bizi buradan çıkar, tekrar günaha dönersek, doğrusu zulmetmiş oluruz."'),
  ('tr.diyanet', 23, 108, 'Allah: "Sinin orada! Benimle konuşmayın. Kullarımdan bir topluluk: "Rabbimiz! inandık, artık bizi bağışla, bize acı. Sen acıyanların en iyisisin" diyordu. Siz ise, onları alaya alıyordunuz. Bu yaptıklarınız size Beni anmayı unutturuyordu. Onlara hep gülüyordunuz. Sabretmelerine karşılık bugün onları mükafatlandırdım. Doğrusu onlar kurtulanlardır" der.'),
  ('tr.diyanet', 23, 109, 'Allah: "Sinin orada! Benimle konuşmayın. Kullarımdan bir topluluk: "Rabbimiz! inandık, artık bizi bağışla, bize acı. Sen acıyanların en iyisisin" diyordu. Siz ise, onları alaya alıyordunuz. Bu yaptıklarınız size Beni anmayı unutturuyordu. Onlara hep gülüyordunuz. Sabretmelerine karşılık bugün onları mükafatlandırdım. Doğrusu onlar kurtulanlardır" der.'),
  ('tr.diyanet', 23, 110, 'Allah: "Sinin orada! Benimle konuşmayın. Kullarımdan bir topluluk: "Rabbimiz! inandık, artık bizi bağışla, bize acı. Sen acıyanların en iyisisin" diyordu. Siz ise, onları alaya alıyordunuz. Bu yaptıklarınız size Beni anmayı unutturuyordu. Onlara hep gülüyordunuz. Sabretmelerine karşılık bugün onları mükafatlandırdım. Doğrusu onlar kurtulanlardır" der.'),
  ('tr.diyanet', 23, 111, 'Allah: "Sinin orada! Benimle konuşmayın. Kullarımdan bir topluluk: "Rabbimiz! inandık, artık bizi bağışla, bize acı. Sen acıyanların en iyisisin" diyordu. Siz ise, onları alaya alıyordunuz. Bu yaptıklarınız size Beni anmayı unutturuyordu. Onlara hep gülüyordunuz. Sabretmelerine karşılık bugün onları mükafatlandırdım. Doğrusu onlar kurtulanlardır" der.'),
  ('tr.diyanet', 23, 112, 'Allah onlara yine: "Yeryüzünde kaç yıl kaldınız" der.'),
  ('tr.diyanet', 23, 113, '"Bir gün veya daha az bir süre kaldık, sayanlara sor" derler.'),
  ('tr.diyanet', 23, 114, 'Allah\' "Pek az kaldınız, keşke bilseydiniz! Sizi boşuna yarattığımızı ve Bize döndürülmeyeceğinizi mi sandınız?" der.'),
  ('tr.diyanet', 23, 115, 'Allah\' "Pek az kaldınız, keşke bilseydiniz! Sizi boşuna yarattığımızı ve Bize döndürülmeyeceğinizi mi sandınız?" der.'),
  ('tr.diyanet', 23, 116, 'Gerçek hükümdar olan Allah yücedir. O\'ndan başka tanrı yoktur. O, yüce arşın Rabbidir.'),
  ('tr.diyanet', 23, 117, 'Allah\'la beraber, varlığına hiçbir delili olmadığı halde başka tanrıya tapanın hesabını Rabbi görecektir. İnkarcılar elbette kurtulamazlar.'),
  ('tr.diyanet', 23, 118, 'De ki: "Rabbim! Bağışla, merhamet et, Sen merhamet edenlerin en hayırlısısın."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 23, 1, 'Sesungguhnya beruntunglah orang-orang yang beriman,'),
  ('id.indonesian', 23, 2, '(yaitu) orang-orang yang khusyu\' dalam sembahyangnya,'),
  ('id.indonesian', 23, 3, 'dan orang-orang yang menjauhkan diri dari (perbuatan dan perkataan) yang tiada berguna,'),
  ('id.indonesian', 23, 4, 'dan orang-orang yang menunaikan zakat,'),
  ('id.indonesian', 23, 5, 'dan orang-orang yang menjaga kemaluannya,'),
  ('id.indonesian', 23, 6, 'kecuali terhadap isteri-isteri mereka atau budak yang mereka miliki; maka sesungguhnya mereka dalam hal ini tiada tercela.'),
  ('id.indonesian', 23, 7, 'Barangsiapa mencari yang di balik itu maka mereka itulah orang-orang yang melampaui batas.'),
  ('id.indonesian', 23, 8, 'Dan orang-orang yang memelihara amanat-amanat (yang dipikulnya) dan janjinya.'),
  ('id.indonesian', 23, 9, 'dan orang-orang yang memelihara sembahyangnya.'),
  ('id.indonesian', 23, 10, 'Mereka itulah orang-orang yang akan mewarisi,'),
  ('id.indonesian', 23, 11, '(yakni) yang akan mewarisi surga Firdaus. Mereka kekal di dalamnya.'),
  ('id.indonesian', 23, 12, 'Dan sesungguhnya Kami telah menciptakan manusia dari suatu saripati (berasal) dari tanah.'),
  ('id.indonesian', 23, 13, 'Kemudian Kami jadikan saripati itu air mani (yang disimpan) dalam tempat yang kokoh (rahim).'),
  ('id.indonesian', 23, 14, 'Kemudian air mani itu Kami jadikan segumpal darah, lalu segumpal darah itu Kami jadikan segumpal daging, dan segumpal daging itu Kami jadikan tulang belulang, lalu tulang belulang itu Kami bungkus dengan daging. Kemudian Kami jadikan dia makhluk yang (berbentuk) lain. Maka Maha sucilah Allah, Pencipta Yang Paling Baik.'),
  ('id.indonesian', 23, 15, 'Kemudian, sesudah itu, sesungguhnya kamu sekalian benar-benar akan mati.'),
  ('id.indonesian', 23, 16, 'Kemudian, sesungguhnya kamu sekalian akan dibangkitkan (dari kuburmu) di hari kiamat.'),
  ('id.indonesian', 23, 17, 'Dan sesungguhnya Kami telah menciptakan di atas kamu tujuh buah jalan (tujuh buah langit); dan Kami tidaklah lengah terhadap ciptaan (Kami).'),
  ('id.indonesian', 23, 18, 'Dan Kami turunkan air dari langit menurut suatu ukuran; lalu Kami jadikan air itu menetap di bumi, dan sesungguhnya Kami benar-benar berkuasa menghilangkannya.'),
  ('id.indonesian', 23, 19, 'Lalu dengan air itu, Kami tumbuhkan untuk kamu kebun-kebun kurma dan anggur; di dalam kebun-kebun itu kamu peroleh buah-buahan yang banyak dan sebahagian dari buah-buahan itu kamu makan,'),
  ('id.indonesian', 23, 20, 'dan pohon kayu keluar dari Thursina (pohon zaitun), yang menghasilkan minyak, dan pemakan makanan bagi orang-orang yang makan.'),
  ('id.indonesian', 23, 21, 'Dan sesungguhnya pada binatang-binatang ternak, benar-benar terdapat pelajaran yang penting bagi kamu, Kami memberi minum kamu dari air susu yang ada dalam perutnya, dan (juga) pada binatang-binatang ternak itu terdapat faedah yang banyak untuk kamu, dan sebagian daripadanya kamu makan,'),
  ('id.indonesian', 23, 22, 'dan di atas punggung binatang-binatang ternak itu dan (juga) di atas perahu-perahu kamu diangkut.'),
  ('id.indonesian', 23, 23, 'Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, lalu ia berkata: "Hai kaumku, sembahlah oleh kamu Allah, (karena) sekali-kali tidak ada Tuhan bagimu selain Dia. Maka mengapa kamu tidak bertakwa (kepada-Nya)?"'),
  ('id.indonesian', 23, 24, 'Maka pemuka-pemuka orang yang kafir di antara kaumnya menjawab: "Orang ini tidak lain hanyalah manusia seperti kamu, yang bermaksud hendak menjadi seorang yang lebih tinggi dari kamu. Dan kalau Allah menghendaki, tentu Dia mengutus beberapa orang malaikat. Belum pernah kami mendengar (seruan yang seperti) ini pada masa nenek moyang kami yang dahulu.'),
  ('id.indonesian', 23, 25, 'la tidak lain hanyalah seorang laki-laki yang berpenyakit gila, maka tunggulah (sabarlah) terhadapnya sampai suatu waktu".'),
  ('id.indonesian', 23, 26, 'Nuh berdoa: "Ya Tuhanku, tolonglah aku, karena mereka mendustakan aku".'),
  ('id.indonesian', 23, 27, 'Lalu Kami wahyukan kepadanya: "Buatlah bahtera di bawah penilikan dan petunjuk Kami, maka apabila perintah Kami telah datang dan tanur telah memancarkan air, maka masukkanlah ke dalam bahtera itu sepasang dari tiap-tiap (jenis), dan (juga) keluargamu, kecuali orang yang telah lebih dahulu ditetapkan (akan ditimpa azab) di antara mereka. Dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang zalim, karena sesungguhnya mereka itu akan ditenggelamkan.'),
  ('id.indonesian', 23, 28, 'Apabila kamu dan orang-orang yang bersamamu telah berada di atas bahtera itu, maka ucapkanlah: "Segala puji bagi Allah yang telah menyelamatkan kami dari orang-orang yang zalim".'),
  ('id.indonesian', 23, 29, 'Dan berdoalah: Ya Tuhanku, tempatkanlah aku pada tempat yang diberkati, dan Engkau adalah sebaik-baik Yang memberi tempat".'),
  ('id.indonesian', 23, 30, 'Sesungguhnya pada (kejadian) itu benar-benar terdapat beberapa tanda (kebesaran Allah), dan sesungguhnya Kami menimpakan azab (kepada kaum Nuh itu).'),
  ('id.indonesian', 23, 31, 'Kemudian, Kami jadikan sesudah mereka umat yang lain.'),
  ('id.indonesian', 23, 32, 'Lalu Kami utus kepada mereka, seorang rasul dari kalangan mereka sendiri (yang berkata): "Sembahlah Allah oleh kamu sekalian, sekali-kali tidak ada Tuhan selain daripada-Nya. Maka mengapa kamu tidak bertakwa (kepada-Nya).'),
  ('id.indonesian', 23, 33, 'Dan berkatalah pemuka-pemuka yang kafir di antara kaumnya dan yang mendustakan akan menemui hari akhirat (kelak) dan yang telah Kami mewahkan mereka dalam kehidupan di dunia: "(Orang) ini tidak lain hanyalah manusia seperti kamu, dia makan dari apa yang kamu makan, dan meminum dari apa yang kamu minum.'),
  ('id.indonesian', 23, 34, 'Dan sesungguhnya jika kamu sekalian mentaati manusia yang seperti kamu, niscaya bila demikian, kamu benar-benar (menjadi) orang-orang yang merugi.'),
  ('id.indonesian', 23, 35, 'Apakah ia menjanjikan kepada kamu sekalian, bahwa bila kamu telah mati dan telah menjadi tanah dan tulang belulang, kamu sesungguhnya akan dikeluarkan (dari kuburmu)?'),
  ('id.indonesian', 23, 36, 'jauh, jauh sekali (dari kebenaran) apa yang diancamkan kepada kamu itu,'),
  ('id.indonesian', 23, 37, 'kehidupan itu tidak lain hanyalah kehidupan kita di dunia ini, kita mati dan kita hidup dan sekali-kali tidak akan dibangkitkan lagi,'),
  ('id.indonesian', 23, 38, 'Ia tidak lain hanyalah seorang yang mengada-adakan kebohongan terhadap Allah, dan kami sekali-kali tidak akan beriman kepadanya".'),
  ('id.indonesian', 23, 39, 'Rasul itu berdoa: "Ya Tuhanku, tolonglah aku karena mereka mendustakanku".'),
  ('id.indonesian', 23, 40, 'Allah berfirman: "Dalam sedikit waktu lagi pasti mereka akan menjadi orang-orang yang menyesal".'),
  ('id.indonesian', 23, 41, 'Maka dimusnahkanlah mereka oleh suara yang mengguntur dengan hak dan Kami jadikan mereka (sebagai) sampah banjir maka kebinasaanlah bagi orang-orang yang zalim itu.'),
  ('id.indonesian', 23, 42, 'Kemudian Kami ciptakan sesudah mereka umat-umat yang lain.'),
  ('id.indonesian', 23, 43, 'Tidak (dapat) sesuatu umatpun mendahului ajalnya, dan tidak (dapat pula) mereka terlambat (dari ajalnya itu).'),
  ('id.indonesian', 23, 44, 'Kemudian Kami utus (kepada umat-umat itu) rasul-rasul Kami berturut-turut. Tiap-tiap seorang rasul datang kepada umatnya, umat itu mendustakannya, maka Kami perikutkan sebagian mereka dengan sebagian yang lain. Dan Kami jadikan mereka buah tutur (manusia), maka kebinasaanlah bagi orang-orang yang tidak beriman.'),
  ('id.indonesian', 23, 45, 'Kemudian Kami utus Musa dan saudaranya Harun dengan membawa tanda-tanda (Kebesaran) Kami, dan bukti yang nyata,'),
  ('id.indonesian', 23, 46, 'kepada Fir\'aun dan pembesar-pembesar kaumnya, maka mereka ini takbur dan mereka adalah orang-orang yang sombong.'),
  ('id.indonesian', 23, 47, 'Dan mereka berkata: "Apakah (patut) kita percaya kepada dua orang manusia seperti kita (juga), padahal kaum mereka (Bani Israil) adalah orang-orang yang menghambakan diri kepada kita?"'),
  ('id.indonesian', 23, 48, 'Maka (tetaplah) mereka mendustakan keduanya, sebab itu mereka adalah termasuk orang-orang yang dibinasakan.'),
  ('id.indonesian', 23, 49, 'Dan sesungguhnya telah Kami berikan Al Kitab (Taurat) kepada Musa, agar mereka (Bani Israil) mendapat petunjuk.'),
  ('id.indonesian', 23, 50, 'Dan telah Kami jadikan (Isa) putera Maryam beserta ibunya suatu bukti yang nyata bagi (kekuasaan Kami), dan Kami melindungi mereka di suatu tanah tinggi yang datar yang banyak terdapat padang-padang rumput dan sumber-sumber air bersih yang mengalir.'),
  ('id.indonesian', 23, 51, 'Hai rasul-rasul, makanlah dari makanan yang baik-baik, dan kerjakanlah amal yang saleh. Sesungguhnya Aku Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 23, 52, 'Sesungguhnya (agama tauhid) ini, adalah agama kamu semua, agama yang satu, dan Aku adalah Tuhanmu, maka bertakwalah kepada-Ku.'),
  ('id.indonesian', 23, 53, 'Kemudian mereka (pengikut-pengikut rasul itu) menjadikan agama mereka terpecah belah menjadi beberapa pecahan. Tiap-tiap golongan merasa bangga dengan apa yang ada pada sisi mereka (masing-masing).'),
  ('id.indonesian', 23, 54, 'Maka biarkanlah mereka dalam kesesatannya sampai suatu waktu.'),
  ('id.indonesian', 23, 55, 'Apakah mereka mengira bahwa harta dan anak-anak yang Kami berikan kepada mereka itu (berarti bahwa),'),
  ('id.indonesian', 23, 56, 'Kami bersegera memberikan kebaikan-kebaikan kepada mereka? Tidak, sebenarnya mereka tidak sadar.'),
  ('id.indonesian', 23, 57, 'Sesungguhnya orang-orang yang berhati-hati karena takut akan (azab) Tuhan mereka,'),
  ('id.indonesian', 23, 58, 'Dan orang-orang yang beriman dengan ayat-ayat Tuhan mereka,'),
  ('id.indonesian', 23, 59, 'Dan orang-orang yang tidak mempersekutukan dengan Tuhan mereka (sesuatu apapun),'),
  ('id.indonesian', 23, 60, 'Dan orang-orang yang memberikan apa yang telah mereka berikan, dengan hati yang takut, (karena mereka tahu bahwa) sesungguhnya mereka akan kembali kepada Tuhan mereka,'),
  ('id.indonesian', 23, 61, 'mereka itu bersegera untuk mendapat kebaikan-kebaikan, dan merekalah orang-orang yang segera memperolehnya.'),
  ('id.indonesian', 23, 62, 'Kami tiada membebani seseorang melainkan menurut kesanggupannya, dan pada sisi Kami ada suatu kitab yang membicarakan kebenaran, dan mereka tidak dianiaya.'),
  ('id.indonesian', 23, 63, 'Tetapi hati orang-orang kafir itu dalam kesesatan dari (memahami kenyataan) ini, dan mereka banyak mengerjakan perbuatan-perbuatan (buruk) selain daripada itu, mereka tetap mengerjakannya.'),
  ('id.indonesian', 23, 64, 'Hingga apabila Kami timpakan azab, kepada orang-orang yang hidup mewah di antara mereka, dengan serta merta mereka memekik minta tolong.'),
  ('id.indonesian', 23, 65, 'Janganlah kamu memekik minta tolong pada hari ini. Sesungguhnya kamu tiada akan mendapat pertolongan dari Kami.'),
  ('id.indonesian', 23, 66, 'Sesungguhnya ayat-ayat-Ku (Al Quran) selalu dibacakan kepada kamu sekalian, maka kamu selalu berpaling ke belakang,'),
  ('id.indonesian', 23, 67, 'dengan menyombongkan diri terhadap Al Quran itu dan mengucapkan perkataan-perkataan keji terhadapnya di waktu kamu bercakap-cakap di malam hari.'),
  ('id.indonesian', 23, 68, 'Maka apakah mereka tidak memperhatikan perkataan (Kami), atau apakah telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka dahulu?'),
  ('id.indonesian', 23, 69, 'Ataukah mereka tidak mengenal rasul mereka, karena itu mereka memungkirinya?'),
  ('id.indonesian', 23, 70, 'Atau (apakah patut) mereka berkata: "Padanya (Muhammad) ada penyakit gila". Sebenarnya dia telah membawa kebenaran kepada mereka, dan kebanyakan mereka benci kepada kebenaran itu.'),
  ('id.indonesian', 23, 71, 'Andaikata kebenaran itu menuruti hawa nafsu mereka, pasti binasalah langit dan bumi ini, dan semua yang ada di dalamnya. Sebenarnya Kami telah mendatangkan kepada mereka kebanggaan (Al Quran) mereka tetapi mereka berpaling dari kebanggaan itu.'),
  ('id.indonesian', 23, 72, 'Atau kamu meminta upah kepada mereka?", maka upah dari Tuhanmu adalah lebih baik, dan Dia adalah Pemberi rezeki Yang Paling Baik.'),
  ('id.indonesian', 23, 73, 'Dan sesungguhnya kamu benar-benar menyeru mereka kepada jalan yang lurus.'),
  ('id.indonesian', 23, 74, 'Dan sesungguhnya orang-orang yang tidak beriman kepada negeri akhirat benar-benar menyimpang dari jalan (yang lurus).'),
  ('id.indonesian', 23, 75, 'Andaikata mereka Kami belas kasihani, dan Kami lenyapkan kemudharatan yang mereka alami, benar-benar mereka akan terus menerus terombang-ambing dalam keterlaluan mereka.'),
  ('id.indonesian', 23, 76, 'Dan sesungguhnya Kami telah pernah menimpakan azab kepada mereka, maka mereka tidak tunduk kepada Tuhan mereka, dan (juga) tidak memohon (kepada-Nya) dengan merendahkan diri.'),
  ('id.indonesian', 23, 77, 'Hingga apabila Kami bukakan untuk mereka suatu pintu tempat azab yang amat sangat (di waktu itulah) tiba-tiba mereka menjadi putus asa.'),
  ('id.indonesian', 23, 78, 'Dan Dialah yang telah menciptakan bagi kamu sekalian, pendengaran, penglihatan dan hati. Amat sedikitlah kamu bersyukur.'),
  ('id.indonesian', 23, 79, 'Dan Dialah yang menciptakan serta mengembang biakkan kamu di bumi ini dan kepada-Nya-lah kamu akan dihimpunkan.'),
  ('id.indonesian', 23, 80, 'Dan Dialah yang menghidupkan dan mematikan, dan Dialah yang (mengatur) pertukaran malam dan siang. Maka apakah kamu tidak memahaminya?'),
  ('id.indonesian', 23, 81, 'Sebenarnya mereka mengucapkan perkataan yang serupa dengan perkataan yang diucapkan oleh orang-orang dahulu kala.'),
  ('id.indonesian', 23, 82, 'Mereka berkata: "Apakah betul, apabila kami telah mati dan kami telah menjadi tanah dan tulang belulang, apakah sesungguhnya kami benar-benar akan dibangkitkan?'),
  ('id.indonesian', 23, 83, 'Sesungguhnya kami dan bapak-bapak kami telah diberi ancaman (dengan) ini dahulu, ini tidak lain hanyalah dongengan orang-orang dahulu kala!".'),
  ('id.indonesian', 23, 84, 'Katakanlah: "Kepunyaan siapakah bumi ini, dan semua yang ada padanya, jika kamu mengetahui?"'),
  ('id.indonesian', 23, 85, 'Mereka akan menjawab: "Kepunyaan Allah". Katakanlah: "Maka apakah kamu tidak ingat?"'),
  ('id.indonesian', 23, 86, 'Katakanlah: "Siapakah Yang Empunya langit yang tujuh dan Yang Empunya \'Arsy yang besar?"'),
  ('id.indonesian', 23, 87, 'Mereka akan menjawab: "Kepunyaan Allah". Katakanlah: "Maka apakah kamu tidak bertakwa?"'),
  ('id.indonesian', 23, 88, 'Katakanlah: "Siapakah yang di tangan-Nya berada kekuasaan atas segala sesuatu sedang Dia melindungi, tetapi tidak ada yang dapat dilindungi dari (azab)-Nya, jika kamu mengetahui?"'),
  ('id.indonesian', 23, 89, 'Mereka akan menjawab: "Kepunyaan Allah". Katakanlah: "(Kalau demikian), maka dari jalan manakah kamu ditipu?"'),
  ('id.indonesian', 23, 90, 'Sebenarnya Kami telah membawa kebenaran kepada mereka, dan sesungguhnya mereka benar-benar orang-orang yang berdusta.'),
  ('id.indonesian', 23, 91, 'Allah sekali-kali tidak mempunyai anak, dan sekali-kali tidak ada tuhan (yang lain) beserta-Nya, kalau ada tuhan beserta-Nya, masing-masing tuhan itu akan membawa makhluk yang diciptakannya, dan sebagian dari tuhan-tuhan itu akan mengalahkan sebagian yang lain. Maha Suci Allah dari apa yang mereka sifatkan itu,'),
  ('id.indonesian', 23, 92, 'Yang mengetahui semua yang ghaib dan semua yang nampak, maka Maha Tinggilah Dia dari apa yang mereka persekutukan.'),
  ('id.indonesian', 23, 93, 'Katakanlah: "Ya Tuhanku, jika Engkau sungguh-sungguh hendak memperlihatkan kepadaku azab yang diancamkan kepada mereka,'),
  ('id.indonesian', 23, 94, 'ya Tuhanku, maka janganlah Engkau jadikan aku berada di antara orang-orang yang zalim".'),
  ('id.indonesian', 23, 95, 'Dan sesungguhnya Kami benar-benar kuasa untuk memperlihatkan kepadamu apa yang Kami ancamkan kepada mereka.'),
  ('id.indonesian', 23, 96, 'Tolaklah perbuatan buruk mereka dengan yang lebih baik. Kami lebih mengetahui apa yang mereka sifatkan.'),
  ('id.indonesian', 23, 97, 'Dan katakanlah: "Ya Tuhanku aku berlindung kepada Engkau dari bisikan-bisikan syaitan.'),
  ('id.indonesian', 23, 98, 'Dan aku berlindung (pula) kepada Engkau ya Tuhanku, dari kedatangan mereka kepadaku".'),
  ('id.indonesian', 23, 99, '(Demikianlah keadaan orang-orang kafir itu), hingga apabila datang kematian kepada seseorang dari mereka, dia berkata: "Ya Tuhanku kembalikanlah aku (ke dunia),'),
  ('id.indonesian', 23, 100, 'agar aku berbuat amal yang saleh terhadap yang telah aku tinggalkan. Sekali-kali tidak. Sesungguhnya itu adalah perkataan yang diucapkannya saja. Dan di hadapan mereka ada dinding sampal hari mereka dibangkitkan.'),
  ('id.indonesian', 23, 101, 'Apabila sangkakala ditiup maka tidaklah ada lagi pertalian nasab di antara mereka pada hari itu, dan tidak ada pula mereka saling bertanya.'),
  ('id.indonesian', 23, 102, 'Barangsiapa yang berat timbangan (kebaikan)nya, maka mereka itulah orang-orang yang dapat keberuntungan.'),
  ('id.indonesian', 23, 103, 'Dan barangsiapa yang ringan timbangannya, maka mereka itulah orang-orang yang merugikan dirinya sendiri, mereka kekal di dalam neraka Jahannam.'),
  ('id.indonesian', 23, 104, 'Muka mereka dibakar api neraka, dan mereka di dalam neraka itu dalam keadaan cacat.'),
  ('id.indonesian', 23, 105, 'Bukankah ayat-ayat-Ku telah dibacakan kepadamu sekalian, tetapi kamu selalu mendustakannya?'),
  ('id.indonesian', 23, 106, 'Mereka berkata: "Ya Tuhan kami, kami telah dikuasai oleh kejahatan kami, dan adalah kami orang-orang yang sesat.'),
  ('id.indonesian', 23, 107, 'Ya Tuhan kami, keluarkanlah kami daripadanya (dan kembalikanlah kami ke dunia), maka jika kami kembali (juga kepada kekafiran), sesungguhnya kami adalah orang-orang yang zalim".'),
  ('id.indonesian', 23, 108, 'Allah berfirman: "Tinggallah dengan hina di dalamnya, dan janganlah kamu berbicara dengan Aku.'),
  ('id.indonesian', 23, 109, 'Sesungguhnya, ada segolongan dari hamba-hamba-Ku berdoa (di dunia): "Ya Tuhan kami, kami telah beriman, maka ampunilah kami dan berilah kami rahmat dan Engkau adalah Pemberi rahmat Yang Paling Baik.'),
  ('id.indonesian', 23, 110, 'Lalu kamu menjadikan mereka buah ejekan, sehingga (kesibukan) kamu mengejek mereka, menjadikan kamu lupa mengingat Aku, dan adalah kamu selalu mentertawakan mereka,'),
  ('id.indonesian', 23, 111, 'Sesungguhnya Aku memberi balasan kepada mereka di hari ini, karena kesabaran mereka; sesungguhnya mereka itulah orang-orang yang menang".'),
  ('id.indonesian', 23, 112, 'Allah bertanya: "Berapa tahunkah lamanya kamu tinggal di bumi?"'),
  ('id.indonesian', 23, 113, 'Mereka menjawab: "Kami tinggal (di bumi) sehari atau setengah hari, maka tanyakanlah kepada orang-orang yang menghitung".'),
  ('id.indonesian', 23, 114, 'Allah berfirman: "Kamu tidak tinggal (di bumi) melainkan sebentar saja, kalau kamu sesungguhnya mengetahui"'),
  ('id.indonesian', 23, 115, 'Maka apakah kamu mengira, bahwa sesungguhnya Kami menciptakan kamu secara main-main (saja), dan bahwa kamu tidak akan dikembalikan kepada Kami?'),
  ('id.indonesian', 23, 116, 'Maka Maha Tinggi Allah, Raja Yang Sebenarnya; tidak ada Tuhan selain Dia, Tuhan (Yang mempunyai) \'Arsy yang mulia.'),
  ('id.indonesian', 23, 117, 'Dan barangsiapa menyembah tuhan yang lain di samping Allah, padahal tidak ada suatu dalilpun baginya tentang itu, maka sesungguhnya perhitungannya di sisi Tuhannya. Sesungguhnya orang-orang yang kafir itu tiada beruntung.'),
  ('id.indonesian', 23, 118, 'Dan katakanlah: "Ya Tuhanku berilah ampun dan berilah rahmat, dan Engkau adalah Pemberi rahmat Yang Paling baik".')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (22, 6, 2601, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّهُۥ يُحْىِ ٱلْمَوْتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 333, 17, 133, 0),
  (22, 7, 2602, 'وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةٌۭ لَّا رَيْبَ فِيهَا وَأَنَّ ٱللَّهَ يَبْعَثُ مَن فِى ٱلْقُبُورِ', 333, 17, 133, 0),
  (22, 8, 2603, 'وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِى ٱللَّهِ بِغَيْرِ عِلْمٍۢ وَلَا هُدًۭى وَلَا كِتَٰبٍۢ مُّنِيرٍۢ', 333, 17, 133, 0),
  (22, 9, 2604, 'ثَانِىَ عِطْفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ ۖ لَهُۥ فِى ٱلدُّنْيَا خِزْىٌۭ ۖ وَنُذِيقُهُۥ يَوْمَ ٱلْقِيَٰمَةِ عَذَابَ ٱلْحَرِيقِ', 333, 17, 133, 0),
  (22, 10, 2605, 'ذَٰلِكَ بِمَا قَدَّمَتْ يَدَاكَ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 333, 17, 133, 0),
  (22, 11, 2606, 'وَمِنَ ٱلنَّاسِ مَن يَعْبُدُ ٱللَّهَ عَلَىٰ حَرْفٍۢ ۖ فَإِنْ أَصَابَهُۥ خَيْرٌ ٱطْمَأَنَّ بِهِۦ ۖ وَإِنْ أَصَابَتْهُ فِتْنَةٌ ٱنقَلَبَ عَلَىٰ وَجْهِهِۦ خَسِرَ ٱلدُّنْيَا وَٱلْءَاخِرَةَ ۚ ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 333, 17, 133, 0),
  (22, 12, 2607, 'يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥ ۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلْبَعِيدُ', 333, 17, 133, 0),
  (22, 13, 2608, 'يَدْعُوا۟ لَمَن ضَرُّهُۥٓ أَقْرَبُ مِن نَّفْعِهِۦ ۚ لَبِئْسَ ٱلْمَوْلَىٰ وَلَبِئْسَ ٱلْعَشِيرُ', 333, 17, 133, 0),
  (22, 14, 2609, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ', 333, 17, 133, 0),
  (22, 15, 2610, 'مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لْيَقْطَعْ فَلْيَنظُرْ هَلْ يُذْهِبَنَّ كَيْدُهُۥ مَا يَغِيظُ', 333, 17, 133, 0),
  (22, 16, 2611, 'وَكَذَٰلِكَ أَنزَلْنَٰهُ ءَايَٰتٍۭ بَيِّنَٰتٍۢ وَأَنَّ ٱللَّهَ يَهْدِى مَن يُرِيدُ', 334, 17, 133, 0),
  (22, 17, 2612, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلْمَجُوسَ وَٱلَّذِينَ أَشْرَكُوٓا۟ إِنَّ ٱللَّهَ يَفْصِلُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 334, 17, 133, 0),
  (22, 18, 2613, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَسْجُدُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ وَٱلشَّمْسُ وَٱلْقَمَرُ وَٱلنُّجُومُ وَٱلْجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرٌۭ مِّنَ ٱلنَّاسِ ۖ وَكَثِيرٌ حَقَّ عَلَيْهِ ٱلْعَذَابُ ۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكْرِمٍ ۚ إِنَّ ٱللَّهَ يَفْعَلُ مَا يَشَآءُ ۩', 334, 17, 133, 1),
  (22, 19, 2614, '۞ هَٰذَانِ خَصْمَانِ ٱخْتَصَمُوا۟ فِى رَبِّهِمْ ۖ فَٱلَّذِينَ كَفَرُوا۟ قُطِّعَتْ لَهُمْ ثِيَابٌۭ مِّن نَّارٍۢ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ ٱلْحَمِيمُ', 334, 17, 134, 0),
  (22, 20, 2615, 'يُصْهَرُ بِهِۦ مَا فِى بُطُونِهِمْ وَٱلْجُلُودُ', 334, 17, 134, 0),
  (22, 21, 2616, 'وَلَهُم مَّقَٰمِعُ مِنْ حَدِيدٍۢ', 334, 17, 134, 0),
  (22, 22, 2617, 'كُلَّمَآ أَرَادُوٓا۟ أَن يَخْرُجُوا۟ مِنْهَا مِنْ غَمٍّ أُعِيدُوا۟ فِيهَا وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ', 334, 17, 134, 0),
  (22, 23, 2618, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍۢ وَلُؤْلُؤًۭا ۖ وَلِبَاسُهُمْ فِيهَا حَرِيرٌۭ', 334, 17, 134, 0),
  (22, 24, 2619, 'وَهُدُوٓا۟ إِلَى ٱلطَّيِّبِ مِنَ ٱلْقَوْلِ وَهُدُوٓا۟ إِلَىٰ صِرَٰطِ ٱلْحَمِيدِ', 335, 17, 134, 0),
  (22, 25, 2620, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلْمَسْجِدِ ٱلْحَرَامِ ٱلَّذِى جَعَلْنَٰهُ لِلنَّاسِ سَوَآءً ٱلْعَٰكِفُ فِيهِ وَٱلْبَادِ ۚ وَمَن يُرِدْ فِيهِ بِإِلْحَادٍۭ بِظُلْمٍۢ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍۢ', 335, 17, 134, 0),
  (22, 26, 2621, 'وَإِذْ بَوَّأْنَا لِإِبْرَٰهِيمَ مَكَانَ ٱلْبَيْتِ أَن لَّا تُشْرِكْ بِى شَيْـًۭٔا وَطَهِّرْ بَيْتِىَ لِلطَّآئِفِينَ وَٱلْقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ', 335, 17, 134, 0),
  (22, 27, 2622, 'وَأَذِّن فِى ٱلنَّاسِ بِٱلْحَجِّ يَأْتُوكَ رِجَالًۭا وَعَلَىٰ كُلِّ ضَامِرٍۢ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍۢ', 335, 17, 134, 0),
  (22, 28, 2623, 'لِّيَشْهَدُوا۟ مَنَٰفِعَ لَهُمْ وَيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ فِىٓ أَيَّامٍۢ مَّعْلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ ۖ فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْبَآئِسَ ٱلْفَقِيرَ', 335, 17, 134, 0),
  (22, 29, 2624, 'ثُمَّ لْيَقْضُوا۟ تَفَثَهُمْ وَلْيُوفُوا۟ نُذُورَهُمْ وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ', 335, 17, 134, 0),
  (22, 30, 2625, 'ذَٰلِكَ وَمَن يُعَظِّمْ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيْرٌۭ لَّهُۥ عِندَ رَبِّهِۦ ۗ وَأُحِلَّتْ لَكُمُ ٱلْأَنْعَٰمُ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ ۖ فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ', 335, 17, 134, 0),
  (22, 31, 2626, 'حُنَفَآءَ لِلَّهِ غَيْرَ مُشْرِكِينَ بِهِۦ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخْطَفُهُ ٱلطَّيْرُ أَوْ تَهْوِى بِهِ ٱلرِّيحُ فِى مَكَانٍۢ سَحِيقٍۢ', 336, 17, 134, 0),
  (22, 32, 2627, 'ذَٰلِكَ وَمَن يُعَظِّمْ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقْوَى ٱلْقُلُوبِ', 336, 17, 134, 0),
  (22, 33, 2628, 'لَكُمْ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى ثُمَّ مَحِلُّهَآ إِلَى ٱلْبَيْتِ ٱلْعَتِيقِ', 336, 17, 134, 0),
  (22, 34, 2629, 'وَلِكُلِّ أُمَّةٍۢ جَعَلْنَا مَنسَكًۭا لِّيَذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلْأَنْعَٰمِ ۗ فَإِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ فَلَهُۥٓ أَسْلِمُوا۟ ۗ وَبَشِّرِ ٱلْمُخْبِتِينَ', 336, 17, 134, 0),
  (22, 35, 2630, 'ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمْ وَٱلْمُقِيمِى ٱلصَّلَوٰةِ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 336, 17, 134, 0),
  (22, 36, 2631, 'وَٱلْبُدْنَ جَعَلْنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمْ فِيهَا خَيْرٌۭ ۖ فَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهَا صَوَآفَّ ۖ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا۟ مِنْهَا وَأَطْعِمُوا۟ ٱلْقَانِعَ وَٱلْمُعْتَرَّ ۚ كَذَٰلِكَ سَخَّرْنَٰهَا لَكُمْ لَعَلَّكُمْ تَشْكُرُونَ', 336, 17, 134, 0),
  (22, 37, 2632, 'لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقْوَىٰ مِنكُمْ ۚ كَذَٰلِكَ سَخَّرَهَا لَكُمْ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ ۗ وَبَشِّرِ ٱلْمُحْسِنِينَ', 336, 17, 134, 0),
  (22, 38, 2633, '۞ إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓا۟ ۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍۢ كَفُورٍ', 336, 17, 135, 0),
  (22, 39, 2634, 'أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمْ ظُلِمُوا۟ ۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ', 337, 17, 135, 0),
  (22, 40, 2635, 'ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِم بِغَيْرِ حَقٍّ إِلَّآ أَن يَقُولُوا۟ رَبُّنَا ٱللَّهُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍۢ لَّهُدِّمَتْ صَوَٰمِعُ وَبِيَعٌۭ وَصَلَوَٰتٌۭ وَمَسَٰجِدُ يُذْكَرُ فِيهَا ٱسْمُ ٱللَّهِ كَثِيرًۭا ۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓ ۗ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 337, 17, 135, 0),
  (22, 41, 2636, 'ٱلَّذِينَ إِن مَّكَّنَّٰهُمْ فِى ٱلْأَرْضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلْمَعْرُوفِ وَنَهَوْا۟ عَنِ ٱلْمُنكَرِ ۗ وَلِلَّهِ عَٰقِبَةُ ٱلْأُمُورِ', 337, 17, 135, 0),
  (22, 42, 2637, 'وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَعَادٌۭ وَثَمُودُ', 337, 17, 135, 0),
  (22, 43, 2638, 'وَقَوْمُ إِبْرَٰهِيمَ وَقَوْمُ لُوطٍۢ', 337, 17, 135, 0),
  (22, 44, 2639, 'وَأَصْحَٰبُ مَدْيَنَ ۖ وَكُذِّبَ مُوسَىٰ فَأَمْلَيْتُ لِلْكَٰفِرِينَ ثُمَّ أَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ نَكِيرِ', 337, 17, 135, 0),
  (22, 45, 2640, 'فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌۭ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍۢ مُّعَطَّلَةٍۢ وَقَصْرٍۢ مَّشِيدٍ', 337, 17, 135, 0),
  (22, 46, 2641, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌۭ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌۭ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ', 337, 17, 135, 0),
  (22, 47, 2642, 'وَيَسْتَعْجِلُونَكَ بِٱلْعَذَابِ وَلَن يُخْلِفَ ٱللَّهُ وَعْدَهُۥ ۚ وَإِنَّ يَوْمًا عِندَ رَبِّكَ كَأَلْفِ سَنَةٍۢ مِّمَّا تَعُدُّونَ', 338, 17, 135, 0),
  (22, 48, 2643, 'وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِىَ ظَالِمَةٌۭ ثُمَّ أَخَذْتُهَا وَإِلَىَّ ٱلْمَصِيرُ', 338, 17, 135, 0),
  (22, 49, 2644, 'قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمْ نَذِيرٌۭ مُّبِينٌۭ', 338, 17, 135, 0),
  (22, 50, 2645, 'فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 338, 17, 135, 0),
  (22, 51, 2646, 'وَٱلَّذِينَ سَعَوْا۟ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 338, 17, 135, 0),
  (22, 52, 2647, 'وَمَآ أَرْسَلْنَا مِن قَبْلِكَ مِن رَّسُولٍۢ وَلَا نَبِىٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلْقَى ٱلشَّيْطَٰنُ فِىٓ أُمْنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلْقِى ٱلشَّيْطَٰنُ ثُمَّ يُحْكِمُ ٱللَّهُ ءَايَٰتِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 338, 17, 135, 0),
  (22, 53, 2648, 'لِّيَجْعَلَ مَا يُلْقِى ٱلشَّيْطَٰنُ فِتْنَةًۭ لِّلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ وَٱلْقَاسِيَةِ قُلُوبُهُمْ ۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِى شِقَاقٍۭ بَعِيدٍۢ', 338, 17, 135, 0),
  (22, 54, 2649, 'وَلِيَعْلَمَ ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّكَ فَيُؤْمِنُوا۟ بِهِۦ فَتُخْبِتَ لَهُۥ قُلُوبُهُمْ ۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓا۟ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 338, 17, 135, 0),
  (22, 55, 2650, 'وَلَا يَزَالُ ٱلَّذِينَ كَفَرُوا۟ فِى مِرْيَةٍۢ مِّنْهُ حَتَّىٰ تَأْتِيَهُمُ ٱلسَّاعَةُ بَغْتَةً أَوْ يَأْتِيَهُمْ عَذَابُ يَوْمٍ عَقِيمٍ', 338, 17, 135, 0),
  (22, 56, 2651, 'ٱلْمُلْكُ يَوْمَئِذٍۢ لِّلَّهِ يَحْكُمُ بَيْنَهُمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى جَنَّٰتِ ٱلنَّعِيمِ', 339, 17, 135, 0),
  (22, 57, 2652, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَا فَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌۭ مُّهِينٌۭ', 339, 17, 135, 0),
  (22, 58, 2653, 'وَٱلَّذِينَ هَاجَرُوا۟ فِى سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓا۟ أَوْ مَاتُوا۟ لَيَرْزُقَنَّهُمُ ٱللَّهُ رِزْقًا حَسَنًۭا ۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 339, 17, 135, 0),
  (22, 59, 2654, 'لَيُدْخِلَنَّهُم مُّدْخَلًۭا يَرْضَوْنَهُۥ ۗ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمٌۭ', 339, 17, 135, 0),
  (22, 60, 2655, '۞ ذَٰلِكَ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِىَ عَلَيْهِ لَيَنصُرَنَّهُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌۭ', 339, 17, 136, 0),
  (22, 61, 2656, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَأَنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌۭ', 339, 17, 136, 0),
  (22, 62, 2657, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ', 339, 17, 136, 0),
  (22, 63, 2658, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَتُصْبِحُ ٱلْأَرْضُ مُخْضَرَّةً ۗ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرٌۭ', 339, 17, 136, 0),
  (22, 64, 2659, 'لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِنَّ ٱللَّهَ لَهُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 339, 17, 136, 0),
  (22, 65, 2660, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِى ٱلْأَرْضِ وَٱلْفُلْكَ تَجْرِى فِى ٱلْبَحْرِ بِأَمْرِهِۦ وَيُمْسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِۦٓ ۗ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌۭ رَّحِيمٌۭ', 340, 17, 136, 0),
  (22, 66, 2661, 'وَهُوَ ٱلَّذِىٓ أَحْيَاكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ۗ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌۭ', 340, 17, 136, 0),
  (22, 67, 2662, 'لِّكُلِّ أُمَّةٍۢ جَعَلْنَا مَنسَكًا هُمْ نَاسِكُوهُ ۖ فَلَا يُنَٰزِعُنَّكَ فِى ٱلْأَمْرِ ۚ وَٱدْعُ إِلَىٰ رَبِّكَ ۖ إِنَّكَ لَعَلَىٰ هُدًۭى مُّسْتَقِيمٍۢ', 340, 17, 136, 0),
  (22, 68, 2663, 'وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعْلَمُ بِمَا تَعْمَلُونَ', 340, 17, 136, 0),
  (22, 69, 2664, 'ٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ', 340, 17, 136, 0),
  (22, 70, 2665, 'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ إِنَّ ذَٰلِكَ فِى كِتَٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 340, 17, 136, 0),
  (22, 71, 2666, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا وَمَا لَيْسَ لَهُم بِهِۦ عِلْمٌۭ ۗ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍۢ', 340, 17, 136, 0),
  (22, 72, 2667, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ تَعْرِفُ فِى وُجُوهِ ٱلَّذِينَ كَفَرُوا۟ ٱلْمُنكَرَ ۖ يَكَادُونَ يَسْطُونَ بِٱلَّذِينَ يَتْلُونَ عَلَيْهِمْ ءَايَٰتِنَا ۗ قُلْ أَفَأُنَبِّئُكُم بِشَرٍّۢ مِّن ذَٰلِكُمُ ۗ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ ۖ وَبِئْسَ ٱلْمَصِيرُ', 340, 17, 136, 0),
  (22, 73, 2668, 'يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌۭ فَٱسْتَمِعُوا۟ لَهُۥٓ ۚ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًۭا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ ۖ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًۭٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ۚ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ', 341, 17, 136, 0),
  (22, 74, 2669, 'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ ۗ إِنَّ ٱللَّهَ لَقَوِىٌّ عَزِيزٌ', 341, 17, 136, 0),
  (22, 75, 2670, 'ٱللَّهُ يَصْطَفِى مِنَ ٱلْمَلَٰٓئِكَةِ رُسُلًۭا وَمِنَ ٱلنَّاسِ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌۭ', 341, 17, 136, 0),
  (22, 76, 2671, 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 341, 17, 136, 0),
  (22, 77, 2672, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ وَٱفْعَلُوا۟ ٱلْخَيْرَ لَعَلَّكُمْ تُفْلِحُونَ ۩', 341, 17, 136, 1),
  (22, 78, 2673, 'وَجَٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ ۚ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍۢ ۚ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ ۚ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ ۚ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ ۖ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ', 341, 17, 136, 0),
  (23, 1, 2674, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', 342, 18, 137, 0),
  (23, 2, 2675, 'ٱلَّذِينَ هُمْ فِى صَلَاتِهِمْ خَٰشِعُونَ', 342, 18, 137, 0),
  (23, 3, 2676, 'وَٱلَّذِينَ هُمْ عَنِ ٱللَّغْوِ مُعْرِضُونَ', 342, 18, 137, 0),
  (23, 4, 2677, 'وَٱلَّذِينَ هُمْ لِلزَّكَوٰةِ فَٰعِلُونَ', 342, 18, 137, 0),
  (23, 5, 2678, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَٰفِظُونَ', 342, 18, 137, 0),
  (23, 6, 2679, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 342, 18, 137, 0),
  (23, 7, 2680, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْعَادُونَ', 342, 18, 137, 0),
  (23, 8, 2681, 'وَٱلَّذِينَ هُمْ لِأَمَٰنَٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 342, 18, 137, 0),
  (23, 9, 2682, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَوَٰتِهِمْ يُحَافِظُونَ', 342, 18, 137, 0),
  (23, 10, 2683, 'أُو۟لَٰٓئِكَ هُمُ ٱلْوَٰرِثُونَ', 342, 18, 137, 0),
  (23, 11, 2684, 'ٱلَّذِينَ يَرِثُونَ ٱلْفِرْدَوْسَ هُمْ فِيهَا خَٰلِدُونَ', 342, 18, 137, 0),
  (23, 12, 2685, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ مِن سُلَٰلَةٍۢ مِّن طِينٍۢ', 342, 18, 137, 0),
  (23, 13, 2686, 'ثُمَّ جَعَلْنَٰهُ نُطْفَةًۭ فِى قَرَارٍۢ مَّكِينٍۢ', 342, 18, 137, 0),
  (23, 14, 2687, 'ثُمَّ خَلَقْنَا ٱلنُّطْفَةَ عَلَقَةًۭ فَخَلَقْنَا ٱلْعَلَقَةَ مُضْغَةًۭ فَخَلَقْنَا ٱلْمُضْغَةَ عِظَٰمًۭا فَكَسَوْنَا ٱلْعِظَٰمَ لَحْمًۭا ثُمَّ أَنشَأْنَٰهُ خَلْقًا ءَاخَرَ ۚ فَتَبَارَكَ ٱللَّهُ أَحْسَنُ ٱلْخَٰلِقِينَ', 342, 18, 137, 0),
  (23, 15, 2688, 'ثُمَّ إِنَّكُم بَعْدَ ذَٰلِكَ لَمَيِّتُونَ', 342, 18, 137, 0),
  (23, 16, 2689, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ تُبْعَثُونَ', 342, 18, 137, 0),
  (23, 17, 2690, 'وَلَقَدْ خَلَقْنَا فَوْقَكُمْ سَبْعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلْخَلْقِ غَٰفِلِينَ', 342, 18, 137, 0),
  (23, 18, 2691, 'وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍۢ فَأَسْكَنَّٰهُ فِى ٱلْأَرْضِ ۖ وَإِنَّا عَلَىٰ ذَهَابٍۭ بِهِۦ لَقَٰدِرُونَ', 343, 18, 137, 0),
  (23, 19, 2692, 'فَأَنشَأْنَا لَكُم بِهِۦ جَنَّٰتٍۢ مِّن نَّخِيلٍۢ وَأَعْنَٰبٍۢ لَّكُمْ فِيهَا فَوَٰكِهُ كَثِيرَةٌۭ وَمِنْهَا تَأْكُلُونَ', 343, 18, 137, 0),
  (23, 20, 2693, 'وَشَجَرَةًۭ تَخْرُجُ مِن طُورِ سَيْنَآءَ تَنۢبُتُ بِٱلدُّهْنِ وَصِبْغٍۢ لِّلْءَاكِلِينَ', 343, 18, 137, 0),
  (23, 21, 2694, 'وَإِنَّ لَكُمْ فِى ٱلْأَنْعَٰمِ لَعِبْرَةًۭ ۖ نُّسْقِيكُم مِّمَّا فِى بُطُونِهَا وَلَكُمْ فِيهَا مَنَٰفِعُ كَثِيرَةٌۭ وَمِنْهَا تَأْكُلُونَ', 343, 18, 137, 0),
  (23, 22, 2695, 'وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 343, 18, 137, 0),
  (23, 23, 2696, 'وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۖ أَفَلَا تَتَّقُونَ', 343, 18, 137, 0),
  (23, 24, 2697, 'فَقَالَ ٱلْمَلَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٌۭ مِّثْلُكُمْ يُرِيدُ أَن يَتَفَضَّلَ عَلَيْكُمْ وَلَوْ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةًۭ مَّا سَمِعْنَا بِهَٰذَا فِىٓ ءَابَآئِنَا ٱلْأَوَّلِينَ', 343, 18, 137, 0),
  (23, 25, 2698, 'إِنْ هُوَ إِلَّا رَجُلٌۢ بِهِۦ جِنَّةٌۭ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِينٍۢ', 343, 18, 137, 0),
  (23, 26, 2699, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 343, 18, 137, 0),
  (23, 27, 2700, 'فَأَوْحَيْنَآ إِلَيْهِ أَنِ ٱصْنَعِ ٱلْفُلْكَ بِأَعْيُنِنَا وَوَحْيِنَا فَإِذَا جَآءَ أَمْرُنَا وَفَارَ ٱلتَّنُّورُ ۙ فَٱسْلُكْ فِيهَا مِن كُلٍّۢ زَوْجَيْنِ ٱثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ ٱلْقَوْلُ مِنْهُمْ ۖ وَلَا تُخَٰطِبْنِى فِى ٱلَّذِينَ ظَلَمُوٓا۟ ۖ إِنَّهُم مُّغْرَقُونَ', 343, 18, 137, 0),
  (23, 28, 2701, 'فَإِذَا ٱسْتَوَيْتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلْفُلْكِ فَقُلِ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى نَجَّىٰنَا مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 344, 18, 137, 0),
  (23, 29, 2702, 'وَقُل رَّبِّ أَنزِلْنِى مُنزَلًۭا مُّبَارَكًۭا وَأَنتَ خَيْرُ ٱلْمُنزِلِينَ', 344, 18, 137, 0),
  (23, 30, 2703, 'إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ وَإِن كُنَّا لَمُبْتَلِينَ', 344, 18, 137, 0),
  (23, 31, 2704, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ', 344, 18, 137, 0),
  (23, 32, 2705, 'فَأَرْسَلْنَا فِيهِمْ رَسُولًۭا مِّنْهُمْ أَنِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۖ أَفَلَا تَتَّقُونَ', 344, 18, 137, 0),
  (23, 33, 2706, 'وَقَالَ ٱلْمَلَأُ مِن قَوْمِهِ ٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَآءِ ٱلْءَاخِرَةِ وَأَتْرَفْنَٰهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا مَا هَٰذَآ إِلَّا بَشَرٌۭ مِّثْلُكُمْ يَأْكُلُ مِمَّا تَأْكُلُونَ مِنْهُ وَيَشْرَبُ مِمَّا تَشْرَبُونَ', 344, 18, 137, 0),
  (23, 34, 2707, 'وَلَئِنْ أَطَعْتُم بَشَرًۭا مِّثْلَكُمْ إِنَّكُمْ إِذًۭا لَّخَٰسِرُونَ', 344, 18, 137, 0),
  (23, 35, 2708, 'أَيَعِدُكُمْ أَنَّكُمْ إِذَا مِتُّمْ وَكُنتُمْ تُرَابًۭا وَعِظَٰمًا أَنَّكُم مُّخْرَجُونَ', 344, 18, 137, 0),
  (23, 36, 2709, '۞ هَيْهَاتَ هَيْهَاتَ لِمَا تُوعَدُونَ', 344, 18, 138, 0),
  (23, 37, 2710, 'إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ', 344, 18, 138, 0),
  (23, 38, 2711, 'إِنْ هُوَ إِلَّا رَجُلٌ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا وَمَا نَحْنُ لَهُۥ بِمُؤْمِنِينَ', 344, 18, 138, 0),
  (23, 39, 2712, 'قَالَ رَبِّ ٱنصُرْنِى بِمَا كَذَّبُونِ', 344, 18, 138, 0),
  (23, 40, 2713, 'قَالَ عَمَّا قَلِيلٍۢ لَّيُصْبِحُنَّ نَٰدِمِينَ', 344, 18, 138, 0),
  (23, 41, 2714, 'فَأَخَذَتْهُمُ ٱلصَّيْحَةُ بِٱلْحَقِّ فَجَعَلْنَٰهُمْ غُثَآءًۭ ۚ فَبُعْدًۭا لِّلْقَوْمِ ٱلظَّٰلِمِينَ', 344, 18, 138, 0),
  (23, 42, 2715, 'ثُمَّ أَنشَأْنَا مِنۢ بَعْدِهِمْ قُرُونًا ءَاخَرِينَ', 344, 18, 138, 0),
  (23, 43, 2716, 'مَا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَـْٔخِرُونَ', 345, 18, 138, 0),
  (23, 44, 2717, 'ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَا ۖ كُلَّ مَا جَآءَ أُمَّةًۭ رَّسُولُهَا كَذَّبُوهُ ۚ فَأَتْبَعْنَا بَعْضَهُم بَعْضًۭا وَجَعَلْنَٰهُمْ أَحَادِيثَ ۚ فَبُعْدًۭا لِّقَوْمٍۢ لَّا يُؤْمِنُونَ', 345, 18, 138, 0),
  (23, 45, 2718, 'ثُمَّ أَرْسَلْنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلْطَٰنٍۢ مُّبِينٍ', 345, 18, 138, 0),
  (23, 46, 2719, 'إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا عَالِينَ', 345, 18, 138, 0),
  (23, 47, 2720, 'فَقَالُوٓا۟ أَنُؤْمِنُ لِبَشَرَيْنِ مِثْلِنَا وَقَوْمُهُمَا لَنَا عَٰبِدُونَ', 345, 18, 138, 0),
  (23, 48, 2721, 'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلْمُهْلَكِينَ', 345, 18, 138, 0),
  (23, 49, 2722, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ لَعَلَّهُمْ يَهْتَدُونَ', 345, 18, 138, 0),
  (23, 50, 2723, 'وَجَعَلْنَا ٱبْنَ مَرْيَمَ وَأُمَّهُۥٓ ءَايَةًۭ وَءَاوَيْنَٰهُمَآ إِلَىٰ رَبْوَةٍۢ ذَاتِ قَرَارٍۢ وَمَعِينٍۢ', 345, 18, 138, 0),
  (23, 51, 2724, 'يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّيِّبَٰتِ وَٱعْمَلُوا۟ صَٰلِحًا ۖ إِنِّى بِمَا تَعْمَلُونَ عَلِيمٌۭ', 345, 18, 138, 0),
  (23, 52, 2725, 'وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ', 345, 18, 138, 0),
  (23, 53, 2726, 'فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًۭا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ', 345, 18, 138, 0),
  (23, 54, 2727, 'فَذَرْهُمْ فِى غَمْرَتِهِمْ حَتَّىٰ حِينٍ', 345, 18, 138, 0),
  (23, 55, 2728, 'أَيَحْسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٍۢ وَبَنِينَ', 345, 18, 138, 0),
  (23, 56, 2729, 'نُسَارِعُ لَهُمْ فِى ٱلْخَيْرَٰتِ ۚ بَل لَّا يَشْعُرُونَ', 345, 18, 138, 0),
  (23, 57, 2730, 'إِنَّ ٱلَّذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 345, 18, 138, 0),
  (23, 58, 2731, 'وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمْ يُؤْمِنُونَ', 345, 18, 138, 0),
  (23, 59, 2732, 'وَٱلَّذِينَ هُم بِرَبِّهِمْ لَا يُشْرِكُونَ', 345, 18, 138, 0),
  (23, 60, 2733, 'وَٱلَّذِينَ يُؤْتُونَ مَآ ءَاتَوا۟ وَّقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَىٰ رَبِّهِمْ رَٰجِعُونَ', 346, 18, 138, 0),
  (23, 61, 2734, 'أُو۟لَٰٓئِكَ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَهُمْ لَهَا سَٰبِقُونَ', 346, 18, 138, 0),
  (23, 62, 2735, 'وَلَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَلَدَيْنَا كِتَٰبٌۭ يَنطِقُ بِٱلْحَقِّ ۚ وَهُمْ لَا يُظْلَمُونَ', 346, 18, 138, 0),
  (23, 63, 2736, 'بَلْ قُلُوبُهُمْ فِى غَمْرَةٍۢ مِّنْ هَٰذَا وَلَهُمْ أَعْمَٰلٌۭ مِّن دُونِ ذَٰلِكَ هُمْ لَهَا عَٰمِلُونَ', 346, 18, 138, 0),
  (23, 64, 2737, 'حَتَّىٰٓ إِذَآ أَخَذْنَا مُتْرَفِيهِم بِٱلْعَذَابِ إِذَا هُمْ يَجْـَٔرُونَ', 346, 18, 138, 0),
  (23, 65, 2738, 'لَا تَجْـَٔرُوا۟ ٱلْيَوْمَ ۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ', 346, 18, 138, 0),
  (23, 66, 2739, 'قَدْ كَانَتْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ تَنكِصُونَ', 346, 18, 138, 0),
  (23, 67, 2740, 'مُسْتَكْبِرِينَ بِهِۦ سَٰمِرًۭا تَهْجُرُونَ', 346, 18, 138, 0),
  (23, 68, 2741, 'أَفَلَمْ يَدَّبَّرُوا۟ ٱلْقَوْلَ أَمْ جَآءَهُم مَّا لَمْ يَأْتِ ءَابَآءَهُمُ ٱلْأَوَّلِينَ', 346, 18, 138, 0),
  (23, 69, 2742, 'أَمْ لَمْ يَعْرِفُوا۟ رَسُولَهُمْ فَهُمْ لَهُۥ مُنكِرُونَ', 346, 18, 138, 0),
  (23, 70, 2743, 'أَمْ يَقُولُونَ بِهِۦ جِنَّةٌۢ ۚ بَلْ جَآءَهُم بِٱلْحَقِّ وَأَكْثَرُهُمْ لِلْحَقِّ كَٰرِهُونَ', 346, 18, 138, 0),
  (23, 71, 2744, 'وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ', 346, 18, 138, 0),
  (23, 72, 2745, 'أَمْ تَسْـَٔلُهُمْ خَرْجًۭا فَخَرَاجُ رَبِّكَ خَيْرٌۭ ۖ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ', 346, 18, 138, 0),
  (23, 73, 2746, 'وَإِنَّكَ لَتَدْعُوهُمْ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 346, 18, 138, 0),
  (23, 74, 2747, 'وَإِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ', 346, 18, 138, 0),
  (23, 75, 2748, '۞ وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرٍّۢ لَّلَجُّوا۟ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ', 347, 18, 139, 0),
  (23, 76, 2749, 'وَلَقَدْ أَخَذْنَٰهُم بِٱلْعَذَابِ فَمَا ٱسْتَكَانُوا۟ لِرَبِّهِمْ وَمَا يَتَضَرَّعُونَ', 347, 18, 139, 0),
  (23, 77, 2750, 'حَتَّىٰٓ إِذَا فَتَحْنَا عَلَيْهِم بَابًۭا ذَا عَذَابٍۢ شَدِيدٍ إِذَا هُمْ فِيهِ مُبْلِسُونَ', 347, 18, 139, 0),
  (23, 78, 2751, 'وَهُوَ ٱلَّذِىٓ أَنشَأَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۚ قَلِيلًۭا مَّا تَشْكُرُونَ', 347, 18, 139, 0),
  (23, 79, 2752, 'وَهُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 347, 18, 139, 0),
  (23, 80, 2753, 'وَهُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ وَلَهُ ٱخْتِلَٰفُ ٱلَّيْلِ وَٱلنَّهَارِ ۚ أَفَلَا تَعْقِلُونَ', 347, 18, 139, 0),
  (23, 81, 2754, 'بَلْ قَالُوا۟ مِثْلَ مَا قَالَ ٱلْأَوَّلُونَ', 347, 18, 139, 0),
  (23, 82, 2755, 'قَالُوٓا۟ أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 347, 18, 139, 0),
  (23, 83, 2756, 'لَقَدْ وُعِدْنَا نَحْنُ وَءَابَآؤُنَا هَٰذَا مِن قَبْلُ إِنْ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 347, 18, 139, 0),
  (23, 84, 2757, 'قُل لِّمَنِ ٱلْأَرْضُ وَمَن فِيهَآ إِن كُنتُمْ تَعْلَمُونَ', 347, 18, 139, 0),
  (23, 85, 2758, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَذَكَّرُونَ', 347, 18, 139, 0),
  (23, 86, 2759, 'قُلْ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ', 347, 18, 139, 0),
  (23, 87, 2760, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ أَفَلَا تَتَّقُونَ', 347, 18, 139, 0),
  (23, 88, 2761, 'قُلْ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍۢ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيْهِ إِن كُنتُمْ تَعْلَمُونَ', 347, 18, 139, 0),
  (23, 89, 2762, 'سَيَقُولُونَ لِلَّهِ ۚ قُلْ فَأَنَّىٰ تُسْحَرُونَ', 347, 18, 139, 0),
  (23, 90, 2763, 'بَلْ أَتَيْنَٰهُم بِٱلْحَقِّ وَإِنَّهُمْ لَكَٰذِبُونَ', 348, 18, 139, 0),
  (23, 91, 2764, 'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍۢ وَمَا كَانَ مَعَهُۥ مِنْ إِلَٰهٍ ۚ إِذًۭا لَّذَهَبَ كُلُّ إِلَٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍۢ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 348, 18, 139, 0),
  (23, 92, 2765, 'عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 348, 18, 139, 0),
  (23, 93, 2766, 'قُل رَّبِّ إِمَّا تُرِيَنِّى مَا يُوعَدُونَ', 348, 18, 139, 0),
  (23, 94, 2767, 'رَبِّ فَلَا تَجْعَلْنِى فِى ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 348, 18, 139, 0),
  (23, 95, 2768, 'وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمْ لَقَٰدِرُونَ', 348, 18, 139, 0),
  (23, 96, 2769, 'ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ ٱلسَّيِّئَةَ ۚ نَحْنُ أَعْلَمُ بِمَا يَصِفُونَ', 348, 18, 139, 0),
  (23, 97, 2770, 'وَقُل رَّبِّ أَعُوذُ بِكَ مِنْ هَمَزَٰتِ ٱلشَّيَٰطِينِ', 348, 18, 139, 0),
  (23, 98, 2771, 'وَأَعُوذُ بِكَ رَبِّ أَن يَحْضُرُونِ', 348, 18, 139, 0),
  (23, 99, 2772, 'حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ', 348, 18, 139, 0),
  (23, 100, 2773, 'لَعَلِّىٓ أَعْمَلُ صَٰلِحًۭا فِيمَا تَرَكْتُ ۚ كَلَّآ ۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا ۖ وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ', 348, 18, 139, 0),
  (23, 101, 2774, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ فَلَآ أَنسَابَ بَيْنَهُمْ يَوْمَئِذٍۢ وَلَا يَتَسَآءَلُونَ', 348, 18, 139, 0),
  (23, 102, 2775, 'فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 348, 18, 139, 0),
  (23, 103, 2776, 'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فِى جَهَنَّمَ خَٰلِدُونَ', 348, 18, 139, 0),
  (23, 104, 2777, 'تَلْفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمْ فِيهَا كَٰلِحُونَ', 348, 18, 139, 0),
  (23, 105, 2778, 'أَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَكُنتُم بِهَا تُكَذِّبُونَ', 349, 18, 139, 0),
  (23, 106, 2779, 'قَالُوا۟ رَبَّنَا غَلَبَتْ عَلَيْنَا شِقْوَتُنَا وَكُنَّا قَوْمًۭا ضَآلِّينَ', 349, 18, 139, 0),
  (23, 107, 2780, 'رَبَّنَآ أَخْرِجْنَا مِنْهَا فَإِنْ عُدْنَا فَإِنَّا ظَٰلِمُونَ', 349, 18, 139, 0),
  (23, 108, 2781, 'قَالَ ٱخْسَـُٔوا۟ فِيهَا وَلَا تُكَلِّمُونِ', 349, 18, 139, 0),
  (23, 109, 2782, 'إِنَّهُۥ كَانَ فَرِيقٌۭ مِّنْ عِبَادِى يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 349, 18, 139, 0),
  (23, 110, 2783, 'فَٱتَّخَذْتُمُوهُمْ سِخْرِيًّا حَتَّىٰٓ أَنسَوْكُمْ ذِكْرِى وَكُنتُم مِّنْهُمْ تَضْحَكُونَ', 349, 18, 139, 0),
  (23, 111, 2784, 'إِنِّى جَزَيْتُهُمُ ٱلْيَوْمَ بِمَا صَبَرُوٓا۟ أَنَّهُمْ هُمُ ٱلْفَآئِزُونَ', 349, 18, 139, 0),
  (23, 112, 2785, 'قَٰلَ كَمْ لَبِثْتُمْ فِى ٱلْأَرْضِ عَدَدَ سِنِينَ', 349, 18, 139, 0),
  (23, 113, 2786, 'قَالُوا۟ لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍۢ فَسْـَٔلِ ٱلْعَآدِّينَ', 349, 18, 139, 0),
  (23, 114, 2787, 'قَٰلَ إِن لَّبِثْتُمْ إِلَّا قَلِيلًۭا ۖ لَّوْ أَنَّكُمْ كُنتُمْ تَعْلَمُونَ', 349, 18, 139, 0),
  (23, 115, 2788, 'أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَٰكُمْ عَبَثًۭا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ', 349, 18, 139, 0),
  (23, 116, 2789, 'فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ ۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ', 349, 18, 139, 0),
  (23, 117, 2790, 'وَمَن يَدْعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرْهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓ ۚ إِنَّهُۥ لَا يُفْلِحُ ٱلْكَٰفِرُونَ', 349, 18, 139, 0),
  (23, 118, 2791, 'وَقُل رَّبِّ ٱغْفِرْ وَٱرْحَمْ وَأَنتَ خَيْرُ ٱلرَّٰحِمِينَ', 349, 18, 139, 0),
  (24, 1, 2792, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سُورَةٌ أَنزَلْنَٰهَا وَفَرَضْنَٰهَا وَأَنزَلْنَا فِيهَآ ءَايَٰتٍۭ بَيِّنَٰتٍۢ لَّعَلَّكُمْ تَذَكَّرُونَ', 350, 18, 140, 0),
  (24, 2, 2793, 'ٱلزَّانِيَةُ وَٱلزَّانِى فَٱجْلِدُوا۟ كُلَّ وَٰحِدٍۢ مِّنْهُمَا مِا۟ئَةَ جَلْدَةٍۢ ۖ وَلَا تَأْخُذْكُم بِهِمَا رَأْفَةٌۭ فِى دِينِ ٱللَّهِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ وَلْيَشْهَدْ عَذَابَهُمَا طَآئِفَةٌۭ مِّنَ ٱلْمُؤْمِنِينَ', 350, 18, 140, 0),
  (24, 3, 2794, 'ٱلزَّانِى لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةًۭ وَٱلزَّانِيَةُ لَا يَنكِحُهَآ إِلَّا زَانٍ أَوْ مُشْرِكٌۭ ۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلْمُؤْمِنِينَ', 350, 18, 140, 0),
  (24, 4, 2795, 'وَٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ثُمَّ لَمْ يَأْتُوا۟ بِأَرْبَعَةِ شُهَدَآءَ فَٱجْلِدُوهُمْ ثَمَٰنِينَ جَلْدَةًۭ وَلَا تَقْبَلُوا۟ لَهُمْ شَهَٰدَةً أَبَدًۭا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 350, 18, 140, 0),
  (24, 5, 2796, 'إِلَّا ٱلَّذِينَ تَابُوا۟ مِنۢ بَعْدِ ذَٰلِكَ وَأَصْلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 350, 18, 140, 0),
  (24, 6, 2797, 'وَٱلَّذِينَ يَرْمُونَ أَزْوَٰجَهُمْ وَلَمْ يَكُن لَّهُمْ شُهَدَآءُ إِلَّآ أَنفُسُهُمْ فَشَهَٰدَةُ أَحَدِهِمْ أَرْبَعُ شَهَٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ', 350, 18, 140, 0),
  (24, 7, 2798, 'وَٱلْخَٰمِسَةُ أَنَّ لَعْنَتَ ٱللَّهِ عَلَيْهِ إِن كَانَ مِنَ ٱلْكَٰذِبِينَ', 350, 18, 140, 0),
  (24, 8, 2799, 'وَيَدْرَؤُا۟ عَنْهَا ٱلْعَذَابَ أَن تَشْهَدَ أَرْبَعَ شَهَٰدَٰتٍۭ بِٱللَّهِ ۙ إِنَّهُۥ لَمِنَ ٱلْكَٰذِبِينَ', 350, 18, 140, 0),
  (24, 9, 2800, 'وَٱلْخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيْهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ', 350, 18, 140, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 24, 1, '[This is] a surah which We have sent down and made [that within it] obligatory and revealed therein verses of clear evidence that you might remember.'),
  ('en.sahih', 24, 2, 'The [unmarried] woman or [unmarried] man found guilty of sexual intercourse - lash each one of them with a hundred lashes, and do not be taken by pity for them in the religion of Allah, if you should believe in Allah and the Last Day. And let a group of the believers witness their punishment.'),
  ('en.sahih', 24, 3, 'The fornicator does not marry except a [female] fornicator or polytheist, and none marries her except a fornicator or a polytheist, and that has been made unlawful to the believers.'),
  ('en.sahih', 24, 4, 'And those who accuse chaste women and then do not produce four witnesses - lash them with eighty lashes and do not accept from them testimony ever after. And those are the defiantly disobedient,'),
  ('en.sahih', 24, 5, 'Except for those who repent thereafter and reform, for indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 24, 6, 'And those who accuse their wives [of adultery] and have no witnesses except themselves - then the witness of one of them [shall be] four testimonies [swearing] by Allah that indeed, he is of the truthful.'),
  ('en.sahih', 24, 7, 'And the fifth [oath will be] that the curse of Allah be upon him if he should be among the liars.'),
  ('en.sahih', 24, 8, 'But it will prevent punishment from her if she gives four testimonies [swearing] by Allah that indeed, he is of the liars.'),
  ('en.sahih', 24, 9, 'And the fifth [oath will be] that the wrath of Allah be upon her if he was of the truthful.'),
  ('en.sahih', 24, 10, 'And if not for the favor of Allah upon you and His mercy... and because Allah is Accepting of repentance and Wise.'),
  ('en.sahih', 24, 11, 'Indeed, those who came with falsehood are a group among you. Do not think it bad for you; rather it is good for you. For every person among them is what [punishment] he has earned from the sin, and he who took upon himself the greater portion thereof - for him is a great punishment.'),
  ('en.sahih', 24, 12, 'Why, when you heard it, did not the believing men and believing women think good of one another and say, "This is an obvious falsehood"?'),
  ('en.sahih', 24, 13, 'Why did they [who slandered] not produce for it four witnesses? And when they do not produce the witnesses, then it is they, in the sight of Allah, who are the liars.'),
  ('en.sahih', 24, 14, 'And if it had not been for the favor of Allah upon you and His mercy in this world and the Hereafter, you would have been touched for that [lie] in which you were involved by a great punishment'),
  ('en.sahih', 24, 15, 'When you received it with your tongues and said with your mouths that of which you had no knowledge and thought it was insignificant while it was, in the sight of Allah, tremendous.'),
  ('en.sahih', 24, 16, 'And why, when you heard it, did you not say, "It is not for us to speak of this. Exalted are You, [O Allah]; this is a great slander"?'),
  ('en.sahih', 24, 17, 'Allah warns you against returning to the likes of this [conduct], ever, if you should be believers.'),
  ('en.sahih', 24, 18, 'And Allah makes clear to you the verses, and Allah is Knowing and Wise.'),
  ('en.sahih', 24, 19, 'Indeed, those who like that immorality should be spread [or publicized] among those who have believed will have a painful punishment in this world and the Hereafter. And Allah knows and you do not know.'),
  ('en.sahih', 24, 20, 'And if it had not been for the favor of Allah upon you and His mercy... and because Allah is Kind and Merciful.'),
  ('en.sahih', 24, 21, 'O you who have believed, do not follow the footsteps of Satan. And whoever follows the footsteps of Satan - indeed, he enjoins immorality and wrongdoing. And if not for the favor of Allah upon you and His mercy, not one of you would have been pure, ever, but Allah purifies whom He wills, and Allah is Hearing and Knowing.'),
  ('en.sahih', 24, 22, 'And let not those of virtue among you and wealth swear not to give [aid] to their relatives and the needy and the emigrants for the cause of Allah, and let them pardon and overlook. Would you not like that Allah should forgive you? And Allah is Forgiving and Merciful.'),
  ('en.sahih', 24, 23, 'Indeed, those who [falsely] accuse chaste, unaware and believing women are cursed in this world and the Hereafter; and they will have a great punishment'),
  ('en.sahih', 24, 24, 'On a Day when their tongues, their hands and their feet will bear witness against them as to what they used to do.'),
  ('en.sahih', 24, 25, 'That Day, Allah will pay them in full their deserved recompense, and they will know that it is Allah who is the perfect in justice.'),
  ('en.sahih', 24, 26, 'Evil words are for evil men, and evil men are [subjected] to evil words. And good words are for good men, and good men are [an object] of good words. Those [good people] are declared innocent of what the slanderers say. For them is forgiveness and noble provision.'),
  ('en.sahih', 24, 27, 'O you who have believed, do not enter houses other than your own houses until you ascertain welcome and greet their inhabitants. That is best for you; perhaps you will be reminded.'),
  ('en.sahih', 24, 28, 'And if you do not find anyone therein, do not enter them until permission has been given you. And if it is said to you, "Go back," then go back; it is purer for you. And Allah is Knowing of what you do.'),
  ('en.sahih', 24, 29, 'There is no blame upon you for entering houses not inhabited in which there is convenience for you. And Allah knows what you reveal and what you conceal.'),
  ('en.sahih', 24, 30, 'Tell the believing men to reduce [some] of their vision and guard their private parts. That is purer for them. Indeed, Allah is Acquainted with what they do.'),
  ('en.sahih', 24, 31, 'And tell the believing women to reduce [some] of their vision and guard their private parts and not expose their adornment except that which [necessarily] appears thereof and to wrap [a portion of] their headcovers over their chests and not expose their adornment except to their husbands, their fathers, their husbands\' fathers, their sons, their husbands\' sons, their brothers, their brothers\' sons, their sisters\' sons, their women, that which their right hands possess, or those male attendants having no physical desire, or children who are not yet aware of the private aspects of women. And let them not stamp their feet to make known what they conceal of their adornment. And turn to Allah in repentance, all of you, O believers, that you might succeed.'),
  ('en.sahih', 24, 32, 'And marry the unmarried among you and the righteous among your male slaves and female slaves. If they should be poor, Allah will enrich them from His bounty, and Allah is all-Encompassing and Knowing.'),
  ('en.sahih', 24, 33, 'But let them who find not [the means for] marriage abstain [from sexual relations] until Allah enriches them from His bounty. And those who seek a contract [for eventual emancipation] from among whom your right hands possess - then make a contract with them if you know there is within them goodness and give them from the wealth of Allah which He has given you. And do not compel your slave girls to prostitution, if they desire chastity, to seek [thereby] the temporary interests of worldly life. And if someone should compel them, then indeed, Allah is [to them], after their compulsion, Forgiving and Merciful.'),
  ('en.sahih', 24, 34, 'And We have certainly sent down to you distinct verses and examples from those who passed on before you and an admonition for those who fear Allah.'),
  ('en.sahih', 24, 35, 'Allah is the Light of the heavens and the earth. The example of His light is like a niche within which is a lamp, the lamp is within glass, the glass as if it were a pearly [white] star lit from [the oil of] a blessed olive tree, neither of the east nor of the west, whose oil would almost glow even if untouched by fire. Light upon light. Allah guides to His light whom He wills. And Allah presents examples for the people, and Allah is Knowing of all things.'),
  ('en.sahih', 24, 36, '[Such niches are] in mosques which Allah has ordered to be raised and that His name be mentioned therein; exalting Him within them in the morning and the evenings'),
  ('en.sahih', 24, 37, '[Are] men whom neither commerce nor sale distracts from the remembrance of Allah and performance of prayer and giving of zakah. They fear a Day in which the hearts and eyes will [fearfully] turn about -'),
  ('en.sahih', 24, 38, 'That Allah may reward them [according to] the best of what they did and increase them from His bounty. And Allah gives provision to whom He wills without account.'),
  ('en.sahih', 24, 39, 'But those who disbelieved - their deeds are like a mirage in a lowland which a thirsty one thinks is water until, when he comes to it, he finds it is nothing but finds Allah before Him, and He will pay him in full his due; and Allah is swift in account.'),
  ('en.sahih', 24, 40, 'Or [they are] like darknesses within an unfathomable sea which is covered by waves, upon which are waves, over which are clouds - darknesses, some of them upon others. When one puts out his hand [therein], he can hardly see it. And he to whom Allah has not granted light - for him there is no light.'),
  ('en.sahih', 24, 41, 'Do you not see that Allah is exalted by whomever is within the heavens and the earth and [by] the birds with wings spread [in flight]? Each [of them] has known his [means of] prayer and exalting [Him], and Allah is Knowing of what they do.'),
  ('en.sahih', 24, 42, 'And to Allah belongs the dominion of the heavens and the earth, and to Allah is the destination.'),
  ('en.sahih', 24, 43, 'Do you not see that Allah drives clouds? Then He brings them together, then He makes them into a mass, and you see the rain emerge from within it. And He sends down from the sky, mountains [of clouds] within which is hail, and He strikes with it whom He wills and averts it from whom He wills. The flash of its lightening almost takes away the eyesight.'),
  ('en.sahih', 24, 44, 'Allah alternates the night and the day. Indeed in that is a lesson for those who have vision.'),
  ('en.sahih', 24, 45, 'Allah has created every [living] creature from water. And of them are those that move on their bellies, and of them are those that walk on two legs, and of them are those that walk on four. Allah creates what He wills. Indeed, Allah is over all things competent.'),
  ('en.sahih', 24, 46, 'We have certainly sent down distinct verses. And Allah guides whom He wills to a straight path.'),
  ('en.sahih', 24, 47, 'But the hypocrites say, "We have believed in Allah and in the Messenger, and we obey"; then a party of them turns away after that. And those are not believers.'),
  ('en.sahih', 24, 48, 'And when they are called to [the words of] Allah and His Messenger to judge between them, at once a party of them turns aside [in refusal].'),
  ('en.sahih', 24, 49, 'But if the right is theirs, they come to him in prompt obedience.'),
  ('en.sahih', 24, 50, 'Is there disease in their hearts? Or have they doubted? Or do they fear that Allah will be unjust to them, or His Messenger? Rather, it is they who are the wrongdoers.'),
  ('en.sahih', 24, 51, 'The only statement of the [true] believers when they are called to Allah and His Messenger to judge between them is that they say, "We hear and we obey." And those are the successful.'),
  ('en.sahih', 24, 52, 'And whoever obeys Allah and His Messenger and fears Allah and is conscious of Him - it is those who are the attainers.'),
  ('en.sahih', 24, 53, 'And they swear by Allah their strongest oaths that if you ordered them, they would go forth [in Allah \'s cause]. Say, "Do not swear. [Such] obedience is known. Indeed, Allah is Acquainted with that which you do."'),
  ('en.sahih', 24, 54, 'Say, "Obey Allah and obey the Messenger; but if you turn away - then upon him is only that [duty] with which he has been charged, and upon you is that with which you have been charged. And if you obey him, you will be [rightly] guided. And there is not upon the Messenger except the [responsibility for] clear notification."'),
  ('en.sahih', 24, 55, 'Allah has promised those who have believed among you and done righteous deeds that He will surely grant them succession [to authority] upon the earth just as He granted it to those before them and that He will surely establish for them [therein] their religion which He has preferred for them and that He will surely substitute for them, after their fear, security, [for] they worship Me, not associating anything with Me. But whoever disbelieves after that - then those are the defiantly disobedient.'),
  ('en.sahih', 24, 56, 'And establish prayer and give zakah and obey the Messenger - that you may receive mercy.'),
  ('en.sahih', 24, 57, 'Never think that the disbelievers are causing failure [to Allah] upon the earth. Their refuge will be the Fire - and how wretched the destination.'),
  ('en.sahih', 24, 58, 'O you who have believed, let those whom your right hands possess and those who have not [yet] reached puberty among you ask permission of you [before entering] at three times: before the dawn prayer and when you put aside your clothing [for rest] at noon and after the night prayer. [These are] three times of privacy for you. There is no blame upon you nor upon them beyond these [periods], for they continually circulate among you - some of you, among others. Thus does Allah make clear to you the verses; and Allah is Knowing and Wise.'),
  ('en.sahih', 24, 59, 'And when the children among you reach puberty, let them ask permission [at all times] as those before them have done. Thus does Allah make clear to you His verses; and Allah is Knowing and Wise.'),
  ('en.sahih', 24, 60, 'And women of post-menstrual age who have no desire for marriage - there is no blame upon them for putting aside their outer garments [but] not displaying adornment. But to modestly refrain [from that] is better for them. And Allah is Hearing and Knowing.'),
  ('en.sahih', 24, 61, 'There is not upon the blind [any] constraint nor upon the lame constraint nor upon the ill constraint nor upon yourselves when you eat from your [own] houses or the houses of your fathers or the houses of your mothers or the houses of your brothers or the houses of your sisters or the houses of your father\'s brothers or the houses of your father\'s sisters or the houses of your mother\'s brothers or the houses of your mother\'s sisters or [from houses] whose keys you possess or [from the house] of your friend. There is no blame upon you whether you eat together or separately. But when you enter houses, give greetings of peace upon each other - a greeting from Allah, blessed and good. Thus does Allah make clear to you the verses [of ordinance] that you may understand.'),
  ('en.sahih', 24, 62, 'The believers are only those who believe in Allah and His Messenger and, when they are [meeting] with him for a matter of common interest, do not depart until they have asked his permission. Indeed, those who ask your permission, [O Muhammad] - those are the ones who believe in Allah and His Messenger. So when they ask your permission for something of their affairs, then give permission to whom you will among them and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 24, 63, 'Do not make [your] calling of the Messenger among yourselves as the call of one of you to another. Already Allah knows those of you who slip away, concealed by others. So let those beware who dissent from the Prophet\'s order, lest fitnah strike them or a painful punishment.'),
  ('en.sahih', 24, 64, 'Unquestionably, to Allah belongs whatever is in the heavens and earth. Already He knows that upon which you [stand] and [knows] the Day when they will be returned to Him and He will inform them of what they have done. And Allah is Knowing of all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 24, 1, 'এটা একটা সূরা যা আমি নাযিল করেছি, এবং দায়িত্বে অপরিহার্য করেছি। এতে আমি সুস্পষ্ট আয়াতসমূহ অবতীর্ণ করেছি, যাতে তোমরা স্মরণ রাখ।'),
  ('bn.bengali', 24, 2, 'ব্যভিচারিণী নারী ব্যভিচারী পুরুষ; তাদের প্রত্যেককে একশ’ করে বেত্রাঘাত কর। আল্লাহর বিধান কার্যকর কারণে তাদের প্রতি যেন তোমাদের মনে দয়ার উদ্রেক না হয়, যদি তোমরা আল্লাহর প্রতি ও পরকালের প্রতি বিশ্বাসী হয়ে থাক। মুসলমানদের একটি দল যেন তাদের শাস্তি প্রত্যক্ষ করে।'),
  ('bn.bengali', 24, 3, 'ব্যভিচারী পুরুষ কেবল ব্যভিচারিণী নারী অথবা মুশরিকা নারীকেই বিয়ে করে এবং ব্যভিচারিণীকে কেবল ব্যভিচারী অথবা মুশরিক পুরুষই বিয়ে করে এবং এদেরকে মুমিনদের জন্যে হারাম করা হয়েছে।'),
  ('bn.bengali', 24, 4, 'যারা সতী-সাধ্বী নারীর প্রতি অপবাদ আরোপ করে অতঃপর স্বপক্ষে চার জন পুরুষ সাক্ষী উপস্থিত করে না, তাদেরকে আশিটি বেত্রাঘাত করবে এবং কখনও তাদের সাক্ষ্য কবুল করবে না। এরাই না’ফারমান।'),
  ('bn.bengali', 24, 5, 'কিন্তু যারা এরপর তওবা করে এবং সংশোধিত হয়, আল্লাহ ক্ষমাশীল, পরম মেহেরবান।'),
  ('bn.bengali', 24, 6, 'এবং যারা তাদের স্ত্রীদের প্রতি অপবাদ আরোপ করে এবং তারা নিজেরা ছাড়া তাদের কোন সাক্ষী নেই, এরূপ ব্যক্তির সাক্ষ্য এভাবে হবে যে, সে আল্লাহর কসম খেয়ে চারবার সাক্ষ্য দেবে যে, সে অবশ্যই সত্যবাদী।'),
  ('bn.bengali', 24, 7, 'এবং পঞ্চমবার বলবে যে, যদি সে মিথ্যাবাদী হয় তবে তার উপর আল্লাহর লানত।'),
  ('bn.bengali', 24, 8, 'এবং স্ত্রীর শাস্তি রহিত হয়ে যাবে যদি সে আল্লাহর কসম খেয়ে চার বার সাক্ষ্য দেয় যে, তার স্বামী অবশ্যই মিথ্যাবাদী;'),
  ('bn.bengali', 24, 9, 'এবং পঞ্চমবার বলে যে, যদি তার স্বামী সত্যবাদী হয় তবে তার ওপর আল্লাহর গযব নেমে আসবে।'),
  ('bn.bengali', 24, 10, 'তোমাদের প্রতি আল্লাহর অনুগ্রহ ও দয়া না থাকলে এবং আল্লাহ তওবা কবুল কারী, প্রজ্ঞাময় না হলে কত কিছুই যে হয়ে যেত।'),
  ('bn.bengali', 24, 11, 'যারা মিথ্যা অপবাদ রটনা করেছে, তারা তোমাদেরই একটি দল। তোমরা একে নিজেদের জন্যে খারাপ মনে করো না; বরং এটা তোমাদের জন্যে মঙ্গলজনক। তাদের প্রত্যেকের জন্যে ততটুকু আছে যতটুকু সে গোনাহ করেছে এবং তাদের মধ্যে যে এ ব্যাপারে অগ্রণী ভূমিকা নিয়েছে, তার জন্যে রয়েছে বিরাট শাস্তি।'),
  ('bn.bengali', 24, 12, 'তোমরা যখন একথা শুনলে, তখন ঈমানদার পুরুষ ও নারীগণ কেন নিজেদের লোক সম্পর্কে উত্তম ধারণা করনি এবং বলনি যে, এটা তো নির্জলা অপবাদ?'),
  ('bn.bengali', 24, 13, 'তারা কেন এ ব্যাপারে চার জন সাক্ষী উপস্থিত করেনি; অতঃপর যখন তারা সাক্ষী উপস্থিত করেনি, তখন তারাই আল্লাহর কাছে মিথ্যাবাদী।'),
  ('bn.bengali', 24, 14, 'যদি ইহকালে ও পরকালে তোমাদের প্রতি আল্লাহর অনুগ্রহ ও দয়া না থাকত, তবে তোমরা যা চর্চা করছিলে, তজ্জন্যে তোমাদেরকে গুরুতর আযাব স্পর্শ করত।'),
  ('bn.bengali', 24, 15, 'যখন তোমরা একে মুখে মুখে ছড়াচ্ছিলে এবং মুখে এমন বিষয় উচ্চারণ করছিলে, যার কোন জ্ঞান তোমাদের ছিল না। তোমরা একে তুচ্ছ মনে করছিলে, অথচ এটা আল্লাহর কাছে গুরুতর ব্যাপার ছিল।'),
  ('bn.bengali', 24, 16, 'তোমরা যখন এ কথা শুনলে তখন কেন বললে না যে, এ বিষয়ে কথা বলা আমাদের উচিত নয়। আল্লাহ তো পবিত্র, মহান। এটা তো এক গুরুতর অপবাদ।'),
  ('bn.bengali', 24, 17, 'আল্লাহ তোমাদেরকে উপদেশ দিচ্ছেন, তোমরা যদি ঈমানদার হও, তবে তখনও পুনরায় এ ধরণের আচরণের পুনরাবৃত্তি করো না।'),
  ('bn.bengali', 24, 18, 'আল্লাহ তোমাদের জন্যে কাজের কথা স্পষ্ট করে বর্ণনা করেন। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 24, 19, 'যারা পছন্দ করে যে, ঈমানদারদের মধ্যে ব্যভিচার প্রসার লাভ করুক, তাদের জন্যে ইহাকাল ও পরকালে যন্ত্রণাদায়ক শাস্তি রয়েছে। আল্লাহ জানেন, তোমরা জান না।'),
  ('bn.bengali', 24, 20, 'যদি তোমাদের প্রতি আল্লাহর অনুগ্রহ ও দয়া না থাকত এবং আল্লাহ দয়ালু, মেহেরবান না হতেন, তবে কত কিছুই হয়ে যেত।'),
  ('bn.bengali', 24, 21, 'হে ঈমানদারগণ, তোমরা শয়তানের পদাঙ্ক অনুসরণ করো না। যে কেউ শয়তানের পদাঙ্ক অনুসরণ করবে, তখন তো শয়তান নির্লজ্জতা ও মন্দ কাজেরই আদেশ করবে। যদি আল্লাহর অনুগ্রহ ও দয়া তোমাদের প্রতি না থাকত, তবে তোমাদের কেউ কখনও পবিত্র হতে পারতে না। কিন্তু আল্লাহ যাকে ইচ্ছা পবিত্র করেন। আল্লাহ সবকিছু শোনেন, জানেন।'),
  ('bn.bengali', 24, 22, 'তোমাদের মধ্যে যারা উচ্চমর্যাদা ও আর্থিক প্রাচুর্যের অধিকারী, তারা যেন কসম না খায় যে, তারা আত্নীয়-স্বজনকে, অভাবগ্রস্তকে এবং আল্লাহর পথে হিজরতকারীদেরকে কিছুই দেবে না। তাদের ক্ষমা করা উচিত এবং দোষক্রটি উপেক্ষা করা উচিত। তোমরা কি কামনা কর না যে, আল্লাহ তোমাদেরকে ক্ষমা করেন? আল্লাহ ক্ষমাশীল, পরম করুণাময়।'),
  ('bn.bengali', 24, 23, 'যারা সতী-সাধ্বী, নিরীহ ঈমানদার নারীদের প্রতি অপবাদ আরোপ করে, তারা ইহকালে ও পরকালে ধিকৃত এবং তাদের জন্যে রয়েছে গুরুতর শাস্তি।'),
  ('bn.bengali', 24, 24, 'যেদিন প্রকাশ করে দেবে তাদের জিহবা, তাদের হাত ও তাদের পা, যা কিছু তারা করত;'),
  ('bn.bengali', 24, 25, 'সেদিন আল্লাহ তাদের সমুচিত শাস্তি পুরোপুরি দেবেন এবং তারা জানতে পারবে যে, অল্লাহই সত্য, স্পষ্ট ব্যক্তকারী।'),
  ('bn.bengali', 24, 26, 'দুশ্চরিত্রা নারীকূল দুশ্চরিত্র পুরুষকুলের জন্যে এবং দুশ্চরিত্র পুরুষকুল দুশ্চরিত্রা নারীকুলের জন্যে। সচ্চরিত্রা নারীকুল সচ্চরিত্র পুরুষকুলের জন্যে এবং সচ্চরিত্র পুরুষকুল সচ্চরিত্রা নারীকুলের জন্যে। তাদের সম্পর্কে লোকে যা বলে, তার সাথে তারা সম্পর্কহীন। তাদের জন্যে আছে ক্ষমা ও সম্মানজনক জীবিকা।'),
  ('bn.bengali', 24, 27, 'হে মুমিনগণ, তোমরা নিজেদের গৃহ ব্যতীত অন্য গৃহে প্রবেশ করো না, যে পর্যন্ত আলাপ-পরিচয় না কর এবং গৃহবাসীদেরকে সালাম না কর। এটাই তোমাদের জন্যে উত্তম, যাতে তোমরা স্মরণ রাখ।'),
  ('bn.bengali', 24, 28, 'যদি তোমরা গৃহে কাউকে না পাও, তবে অনুমতি গ্রহণ না করা পর্যন্ত সেখানে প্রবেশ করো না। যদি তোমাদেরকে বলা হয় ফিরে যাও, তবে ফিরে যাবে। এতে তোমাদের জন্যে অনেক পবিত্রতা আছে এবং তোমরা যা কর, আল্লাহ তা ভালোভাবে জানেন।'),
  ('bn.bengali', 24, 29, 'যে গৃহে কেউ বাস করে না, যাতে তোমাদের সামগ্রী আছে এমন গৃহে প্রবেশ করাতে তোমাদের কোন পাপ নেই এবং আল্লাহ জানেন তোমরা যা প্রকাশ কর এবং যা গোপন কর।'),
  ('bn.bengali', 24, 30, 'মুমিনদেরকে বলুন, তারা যেন তাদের দৃষ্টি নত রাখে এবং তাদের যৌনাঙ্গর হেফাযত করে। এতে তাদের জন্য খুব পবিত্রতা আছে। নিশ্চয় তারা যা করে আল্লাহ তা অবহিত আছেন।'),
  ('bn.bengali', 24, 31, 'ঈমানদার নারীদেরকে বলুন, তারা যেন তাদের দৃষ্টিকে নত রাখে এবং তাদের যৌন অঙ্গের হেফাযত করে। তারা যেন যা সাধারণতঃ প্রকাশমান, তা ছাড়া তাদের সৌন্দর্য প্রদর্শন না করে এবং তারা যেন তাদের মাথার ওড়না বক্ষ দেশে ফেলে রাখে এবং তারা যেন তাদের স্বামী, পিতা, শ্বশুর, পুত্র, স্বামীর পুত্র, ভ্রাতা, ভ্রাতুস্পুত্র, ভগ্নিপুত্র, স্ত্রীলোক অধিকারভুক্ত বাঁদী, যৌনকামনামুক্ত পুরুষ, ও বালক, যারা নারীদের গোপন অঙ্গ সম্পর্কে অজ্ঞ, তাদের ব্যতীত কারো আছে তাদের সৌন্দর্য প্রকাশ না করে, তারা যেন তাদের গোপন সাজ-সজ্জা প্রকাশ করার জন্য জোরে পদচারণা না করে। মুমিনগণ, তোমরা সবাই আল্লাহর সামনে তওবা কর, যাতে তোমরা সফলকাম হও।'),
  ('bn.bengali', 24, 32, 'তোমাদের মধ্যে যারা বিবাহহীন, তাদের বিবাহ সম্পাদন করে দাও এবং তোমাদের দাস ও দাসীদের মধ্যে যারা সৎকর্মপরায়ন, তাদেরও। তারা যদি নিঃস্ব হয়, তবে আল্লাহ নিজ অনুগ্রহে তাদেরকে সচ্ছল করে দেবেন। আল্লাহ প্রাচুর্যময়, সর্বজ্ঞ।'),
  ('bn.bengali', 24, 33, 'যারা বিবাহে সামর্থ নয়, তারা যেন সংযম অবলম্বন করে যে পর্যন্ত না আল্লাহ নিজ অনুগ্রহে তাদেরকে অভাবমুক্ত করে দেন। তোমাদের অধিকারভুক্তদের মধ্যে যারা মুক্তির জন্য লিখিত চুক্তি করতে চায়, তাদের সাথে তোমরা লিখিত চুক্তি কর যদি জান যে, তাদের মধ্যে কল্যাণ আছে। আল্লাহ তোমাদেরকে যে, অর্থ-কড়ি দিয়েছেন, তা থেকে তাদেরকে দান কর। তোমাদের দাসীরা নিজেদের পবিত্রতা রক্ষা করতে চাইলে তোমরা পার্থিব জীবনের সম্পদের লালসায় তাদেরকে ব্যভিচারে বাধ্য কারো না। যদি কেহ তাদের উপর জোর-জবরদস্তি করে, তবে তাদের উপর জোর-জবরদস্তির পর আল্লাহ তাদের প্রতি ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 24, 34, 'আমি তোমাদের প্রতি অবতীর্ণ করেছি সুস্পষ্ট আয়াতসমূহ, তোমাদের পূর্ববর্তীদের কিছু দৃষ্টান্ত এবং আল্লাহ ভীরুদের জন্যে দিয়েছি উপদেশ।'),
  ('bn.bengali', 24, 35, 'আল্লাহ নভোমন্ডল ও ভূমন্ডলের জ্যোতি, তাঁর জ্যোতির উদাহরণ যেন একটি কুলঙ্গি, যাতে আছে একটি প্রদীপ, প্রদীপটি একটি কাঁচপাত্রে স্থাপিত, কাঁচপাত্রটি উজ্জ্বল নক্ষত্র সদৃশ্য। তাতে পুতঃপবিত্র যয়তুন বৃক্ষের তৈল প্রজ্বলিত হয়, যা পূর্বমুখী নয় এবং পশ্চিমমুখীও নয়। অগ্নি স্পর্শ না করলেও তার তৈল যেন আলোকিত হওয়ার নিকটবর্তী। জ্যোতির উপর জ্যোতি। আল্লাহ যাকে ইচ্ছা পথ দেখান তাঁর জ্যোতির দিকে। আল্লাহ মানুষের জন্যে দৃষ্টান্তসমূহ বর্ণনা করেন এবং আল্লাহ সব বিষয়ে জ্ঞাত।'),
  ('bn.bengali', 24, 36, 'আল্লাহ যেসব গৃহকে মর্যাদায় উন্নীত করার এবং সেগুলোতে তাঁর নাম উচ্চারণ করার আদেশ দিয়েছেন, সেখানে সকাল ও সন্ধ্যায় তাঁর পবিত্রতা ও মহিমা ঘোষণা করে;'),
  ('bn.bengali', 24, 37, 'এমন লোকেরা, যাদেরকে ব্যবসা-বাণিজ্য ও ক্রয়-বিক্রয় আল্লাহর স্মরণ থেকে, নামায কায়েম করা থেকে এবং যাকাত প্রদান করা থেকে বিরত রাখে না। তারা ভয় করে সেই দিনকে, যেদিন অন্তর ও দৃষ্টিসমূহ উল্টে যাবে।'),
  ('bn.bengali', 24, 38, '(তারা আল্লাহর পবিত্রতা ঘোষণা করে) যাতে আল্লাহ তাদের উৎকৃষ্টতর কাজের প্রতিদান দেন এবং নিজ অনুগ্রহে আরও অধিক দেন। আল্লাহ যাকে ইচ্ছা অপরিমিত রুযী দান করেন।'),
  ('bn.bengali', 24, 39, 'যারা কাফের, তাদের কর্ম মরুভুমির মরীচিকা সদৃশ, যাকে পিপাসার্ত ব্যক্তি পানি মনে করে। এমনকি, সে যখন তার কাছে যায়, তখন কিছুই পায় না এবং পায় সেখানে আল্লাহকে, অতঃপর আল্লাহ তার হিসাব চুকিয়ে দেন। আল্লাহ দ্রুত হিসাব গ্রহণকারী।'),
  ('bn.bengali', 24, 40, 'অথবা (তাদের কর্ম) প্রমত্ত সমুদ্রের বুকে গভীর অন্ধকারের ন্যায়, যাকে উদ্বেলিত করে তরঙ্গের উপর তরঙ্গ, যার উপরে ঘন কালো মেঘ আছে। একের উপর এক অন্ধকার। যখন সে তার হাত বের করে, তখন তাকে একেবারেই দেখতে পায় না। আল্লাহ যাকে জ্যোতি দেন না, তার কোন জ্যোতিই নেই।'),
  ('bn.bengali', 24, 41, 'তুমি কি দেখ না যে, নভোমন্ডল ও ভূমন্ডলে যারা আছে, তারা এবং উড়ন্ত পক্ষীকুল তাদের পাখা বিস্তার করতঃ আল্লাহর পবিত্রতা ও মহিমা ঘোষণা করে? প্রত্যেকেই তার যোগ্য এবাদত এবং পবিত্রতা ও মহিমা ঘোষণার পদ্ধতি জানে। তারা যা করে, আল্লাহ সে বিষয়ে সম্যক জ্ঞাত।'),
  ('bn.bengali', 24, 42, 'নভোমন্ডল ও ভূমন্ডলের সার্বভৌমত্ব আল্লাহরই এবং তাঁরই দিকে প্রত্যাবর্তন করতে হবে।'),
  ('bn.bengali', 24, 43, 'তুমি কি দেখ না যে, আল্লাহ মেঘমালাকে সঞ্চালিত করেন, অতঃপর তাকে পুঞ্জীভূত করেন, অতঃপর তাকে স্তরে স্তরে রাখেন; অতঃপর তুমি দেখ যে, তার মধ্য থেকে বারিধারা নির্গত হয়। তিনি আকাশস্থিত শিলাস্তুপ থেকে শিলাবর্ষণ করেন এবং তা দ্বারা যাকে ইচ্ছা আঘাত করেন এবং যার কাছ থেকে ইচ্ছা, তা অন্যদিকে ফিরিয়ে দেন। তার বিদ্যুৎঝলক দৃষ্টিশক্তি যেন বিলীন করে দিতে চায়।'),
  ('bn.bengali', 24, 44, 'আল্লাহ দিন ও রাত্রির পরিবর্তন ঘটান। এতে অর্ন্তদৃষ্টি-সম্পন্নগণের জন্যে চিন্তার উপকরণ রয়েছে।'),
  ('bn.bengali', 24, 45, 'আল্লাহ প্রত্যেক চলন্ত জীবকে পানি দ্বারা সৃষ্টি করেছেন। তাদের কতক বুকে ভয় দিয়ে চলে, কতক দুই পায়ে ভর দিয়ে চলে এবং কতক চার পায়ে ভর দিয়ে চলে; আল্লাহ যা ইচ্ছা সৃষ্টি করেন। নিশ্চয়ই আল্লাহ সবকিছু করতে সক্ষম।'),
  ('bn.bengali', 24, 46, 'আমি তো সুস্পষ্ট আয়াত সমূহ অবর্তীর্ণ করেছি। আল্লাহ যাকে ইচ্ছা সরল পথে পরিচালনা করেন।'),
  ('bn.bengali', 24, 47, 'তারা বলেঃ আমরা আল্লাহ ও রসূলের প্রতি বিশ্বাস স্থাপন করেছি এবং আনুগত্য করি; কিন্তু অতঃপর তাদের একদল মুখ ফিরিয়ে নেয় এবং তারা বিশ্বাসী নয়।'),
  ('bn.bengali', 24, 48, 'তাদের মধ্যে ফয়সালা করার জন্য যখন তাদেরকে আল্লাহ ও রসূলের দিকে আহবান করা হয তখন তাদের একদল মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 24, 49, 'সত্য তাদের স্বপক্ষে হলে তারা বিনীতভাবে রসূলের কাছে ছুটে আসে।'),
  ('bn.bengali', 24, 50, 'তাদের অন্তরে কি রোগ আছে, না তারা ধোঁকায় পড়ে আছে; না তারা ভয় করে যে, আল্লাহ ও তাঁর রাসূল তাদের প্রতি অবিচার করবেন? বরং তারাই তো অবিচারকারী ?'),
  ('bn.bengali', 24, 51, 'মুমিনদের বক্তব্য কেবল এ কথাই যখন তাদের মধ্যে ফয়সালা করার জন্যে আল্লাহ ও তাঁর রসূলের দিকে তাদেরকে আহবান করা হয়, তখন তারা বলেঃ আমরা শুনলাম ও আদেশ মান্য করলাম। তারাই সফলকাম।'),
  ('bn.bengali', 24, 52, 'যারা আল্লাহ ও তাঁর রসূলের আনুগত্য করে আল্লাহকে ভয় করে ও তাঁর শাস্তি থেকে বেঁচে থাকে তারাই কৃতকার্য।'),
  ('bn.bengali', 24, 53, 'তারা দৃঢ়ভাবে আল্লাহর কসম খেয়ে বলে যে, আপনি তাদেরকে আদেশ করলে তারা সবকিছু ছেড়ে বের হবেই। বলুনঃ তোমরা কসম খেয়ো না। নিয়মানুযায়ী তোমাদের আনুগত্য, তোমরা যা কিছু কর নিশ্চয় আল্লাহ সে বিষয়ে জ্ঞাত।'),
  ('bn.bengali', 24, 54, 'বলুনঃ আল্লাহর আনুগত্য কর এবং রসূলের আনুগত্য কর। অতঃপর যদি তোমরা মুখ ফিরিয়ে নাও, তবে তার উপর ন্যস্ত দায়িত্বের জন্যে সে দায়ী এবং তোমাদের উপর ন্যস্ত দায়িত্বের জন্যে তোমরা দায়ী। তোমরা যদি তাঁর আনুগত্য কর, তবে সৎ পথ পাবে। রসূলের দায়িত্ব তো কেবল সুস্পষ্টরূপে পৌছে দেয়া।'),
  ('bn.bengali', 24, 55, 'তোমাদের মধ্যে যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে, আল্লাহ তাদেরকে ওয়াদা দিয়েছেন যে, তাদেরকে অবশ্যই পৃথিবীতে শাসনকর্তৃত্ব দান করবেন। যেমন তিনি শাসনকতৃꦣ2468;্ব দান করেছেন তাদের পূর্ববতীদেরকে এবং তিনি অবশ্যই সুদৃঢ় করবেন তাদের ধর্মকে, যা তিনি তাদের জন্যে পছন্দ করেছেন এবং তাদের ভয়-ভীতির পরিবর্তে অবশ্যই তাদেরকে শান্তি দান করবেন। তারা আমার এবাদত করবে এবং আমার সাথে কাউকে শরীক করবে না। এরপর যারা অকৃতজ্ঞ হবে, তারাই অবাধ্য।'),
  ('bn.bengali', 24, 56, 'নামায কায়েম কর, যাকাত প্রদান কর এবং রসূলের আনুগত্য কর যাতে তোমরা অনুগ্রহ প্রাপ্ত হও।'),
  ('bn.bengali', 24, 57, 'তোমরা কাফেরদেরকে পৃথিবীতে পরাক্রমশালী মনে করো না। তাদের ঠিকানা অগ্নি। কতই না নিকৃষ্ট এই প্রত্যাবর্তনস্থল।'),
  ('bn.bengali', 24, 58, 'হে মুমিনগণ! তোমাদের দাসদাসীরা এবং তোমাদের মধ্যে যারা প্রাপ্ত বয়স্ক হয়নি তারা যেন তিন সময়ে তোমাদের কাছে অনুমতি গ্রহণ করে, ফজরের নামাযের পূর্বে, দুপুরে যখন তোমরা বস্ত্র খুলে রাখ এবং এশার নামাযের পর। এই তিন সময় তোমাদের দেহ খোলার সময়। এ সময়ের পর তোমাদের ও তাদের জন্যে কোন দোষ নেই। তোমাদের একে অপরের কাছে তো যাতায়াত করতেই হয়, এমনি ভাবে আল্লাহ তোমাদের কাছে সুস্পষ্ট আয়াতসমূহ বিবৃত করেন। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 24, 59, 'তোমাদের সন্তান-সন্ততিরা যখন বায়োপ্রাপ্ত হয়, তারাও যেন তাদের পূর্ববর্তীদের ন্যায় অনুমতি চায়। এমনিভাবে আল্লাহ তাঁর আয়াতসমূহ তোমাদের কাছে বর্ণনা করেন। আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 24, 60, 'বৃদ্ধা নারী, যারা বিবাহের আশা রাখে না, যদি তারা তাদের সৌন্দর্য?2474;্রকাশ না করে তাদের বস্ত্র খুলে রাখে। তাদের জন্যে দোষ নেই, তবে এ থেকে বিরত থাকাই তাদের জন্যে উত্তম। আল্লাহ সর্বশ্রোতা, সর্বজ্ঞ।'),
  ('bn.bengali', 24, 61, 'অন্ধের জন্যে দোষ নেই, খঞ্জের জন্যে দোষ নেই, রোগীর জন্যে দোষ নেই, এবং তোমাদের নিজেদের জন্যেও দোষ নেই যে, তোমরা আহার করবে তোমাদের গৃহে অথবা তোমাদের পিতাদের গৃহে অথবা তোমাদের মাতাদের গৃহে অথবা তোমাদের ভ্রাতাদের গৃহে অথবা তোমাদের ভগিণীদের গৃহে অথবা তোমাদের পিতৃব্যদের গৃহে অথবা তোমাদের ফুফুদের গৃহে অথবা তোমাদের মামাদের গৃহে অথবা তোমাদের খালাদের গৃহে অথবা সেই গৃহে, যার চাবি আছে তোমাদের হাতে অথবা তোমাদের বন্ধুদের গৃহে। তোমরা একত্রে আহার কর অথবা পৃথকভবে আহার কর, তাতে তোমাদের কোন দোষ নেই। অতঃপর যখন তোমরা গৃহে প্রবেশ কর, তখন তোমাদের স্বজনদের প্রতি সালাম বলবে। এটা আল্লাহর কাছ থেকে কল্যাণময় ও পবিত্র দোয়া। এমনিভাবে আল্লাহ তোমাদের জন্যে আয়াতসমূহ বিশদভাবে বর্ননা করেন, যাতে তোমরা বুঝে নাও।'),
  ('bn.bengali', 24, 62, 'মুমিন তো তারাই; যারা আল্লাহর ও রসূলের প্রতি বিশ্বাস স্থাপন করে এবং রসূলের সাথে কোন সমষ্টিগত কাজে শরীক হলে তাঁর কাছ থেকে অনুমতি গ্রহণ ব্যতীত চলে যায় না। যারা আপনার কাছে অনুমতি প্রার্থনা করে, তারাই আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন করে। অতএব তারা আপনার কাছে তাদের কোন কাজের জন্যে অনুমতি চাইলে আপনি তাদের মধ্যে যাকে ইচ্ছা অনুমতি দিন এবং তাদের জন্যে আল্লাহর কাছে ক্ষমা প্রার্থনা করুন। আল্লাহ ক্ষমাশীল, মেহেরবান।'),
  ('bn.bengali', 24, 63, 'রসূলের আহবানকে তোমরা তোমাদের একে অপরকে আহ্বানের মত গণ্য করো না। আল্লাহ তাদেরকে জানেন, যারা তোমাদের মধ্যে চুপিসারে সরে পড়ে। অতএব যারা তাঁর আদেশের বিরুদ্ধাচরণ করে, তারা এ বিষয়ে সতর্ক হোক যে, বিপর্যয় তাদেরকে স্পর্শ করবে অথবা যন্ত্রণাদায়ক শাস্তি তাদেরকে গ্রাস করবে।'),
  ('bn.bengali', 24, 64, 'মনে রেখো নভোমন্ডল ও ভূমন্ডলে যা আছে, তা আল্লাহরই। তোমরা যে অবস্থায় আছ তা তিনি জানেন। যেদিন তারা তাঁর কাছে প্রত্যাবর্তিত হবে, সেদিন তিনি বলে দেবেন তারা যা করেছে। আল্লাহ প্রত্যেক বিষয়ই জানেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 24, 1, '(Here is) a surah which We have revealed and enjoined, and wherein We have revealed plain tokens, that haply ye may take heed.'),
  ('en.pickthall', 24, 2, 'The adulterer and the adulteress, scourge ye each one of them (with) a hundred stripes. And let not pity for the twain withhold you from obedience to Allah, if ye believe in Allah and the Last Day. And let a party of believers witness their punishment.'),
  ('en.pickthall', 24, 3, 'The adulterer shall not marry save an adulteress or an idolatress, and the adulteress none shall marry save an adulterer or an idolater. All that is forbidden unto believers.'),
  ('en.pickthall', 24, 4, 'And those who accuse honourable women but bring not four witnesses, scourge them (with) eighty stripes and never (afterward) accept their testimony - They indeed are evil-doers -'),
  ('en.pickthall', 24, 5, 'Save those who afterward repent and make amends. (For such) lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 24, 6, 'As for those who accuse their wives but have no witnesses except themselves; let the testimony of one of them be four testimonies, (swearing) by Allah that he is of those who speak the truth;'),
  ('en.pickthall', 24, 7, 'And yet a fifth, invoking the curse of Allah on him if he is of those who lie.'),
  ('en.pickthall', 24, 8, 'And it shall avert the punishment from her if she bear witness before Allah four times that the thing he saith is indeed false,'),
  ('en.pickthall', 24, 9, 'And a fifth (time) that the wrath of Allah be upon her if he speaketh truth.'),
  ('en.pickthall', 24, 10, 'And had it not been for the grace of Allah and His mercy unto you, and that Allah is Clement, Wise, (ye had been undone).'),
  ('en.pickthall', 24, 11, 'Lo! they who spread the slander are a gang among you. Deem it not a bad thing for you; nay, it is good for you. Unto every man of them (will be paid) that which he hath earned of the sin; and as for him among them who had the greater share therein, his will be an awful doom.'),
  ('en.pickthall', 24, 12, 'Why did not the believers, men and women, when ye heard it, think good of their own own folk, and say: It is a manifest untruth?'),
  ('en.pickthall', 24, 13, 'Why did they not produce four witnesses? Since they produce not witnesses, they verily are liars in the sight of Allah.'),
  ('en.pickthall', 24, 14, 'Had it not been for the grace of Allah and His mercy unto you in the world and the Hereafter an awful doom had overtaken you for that whereof ye murmured.'),
  ('en.pickthall', 24, 15, 'When ye welcomed it with your tongues, and uttered with your mouths that whereof ye had no knowledge, ye counted it a trifle. In the sight of Allah it is very great.'),
  ('en.pickthall', 24, 16, 'Wherefor, when ye heard it, said ye not: It is not for us to speak of this. Glory be to Thee (O Allah)! This is awful calumny.'),
  ('en.pickthall', 24, 17, 'Allah admonisheth you that ye repeat not the like thereof ever, if ye are (in truth) believers.'),
  ('en.pickthall', 24, 18, 'And He expoundeth unto you the revelations. Allah is Knower, Wise.'),
  ('en.pickthall', 24, 19, 'Lo! those who love that slander should be spread concerning those who believe, theirs will be a painful punishment in the world and the Hereafter. Allah knoweth. Ye know not.'),
  ('en.pickthall', 24, 20, 'Had it not been for the grace of Allah and His mercy unto you, and that Allah is Clement, Merciful, (ye had been undone).'),
  ('en.pickthall', 24, 21, 'O ye who believe! Follow not the footsteps of the devil. Unto whomsoever followeth the footsteps of the devil, lo! he commandeth filthiness and wrong. Had it not been for the grace of Allah and His mercy unto you, not one of you would ever have grown pure. But Allah causeth whom He will to grow. And Allah is Hearer, Knower.'),
  ('en.pickthall', 24, 22, 'And let not those who possess dignity and ease among you swear not to give to the near of kin and to the needy, and to fugitives for the cause of Allah. Let them forgive and show indulgence. Yearn ye not that Allah may forgive you? Allah is Forgiving, Merciful.'),
  ('en.pickthall', 24, 23, 'Lo! as for those who traduce virtuous, believing women (who are) careless, cursed are they in the world and the Hereafter. Theirs will be an awful doom'),
  ('en.pickthall', 24, 24, 'On the day when their tongues and their hands and their feet testify against them as to what they used to do,'),
  ('en.pickthall', 24, 25, 'On that day Allah will pay them their just due, and they will know that Allah, He is the Manifest Truth.'),
  ('en.pickthall', 24, 26, 'Vile women are for vile men, and vile men for vile women. Good women are for good men, and good men for good women; such are innocent of that which people say: For them is pardon and a bountiful provision.'),
  ('en.pickthall', 24, 27, 'O ye who believe! Enter not houses other than your own without first announcing your presence and invoking peace upon the folk thereof. That is better for you, that ye may be heedful.'),
  ('en.pickthall', 24, 28, 'And if ye find no-one therein, still enter not until permission hath been given. And if it be said unto you: Go away again, then go away, for it is purer for you. Allah knoweth what ye do.'),
  ('en.pickthall', 24, 29, '(It is) no sin for you to enter uninhabited houses wherein is comfort for you. Allah knoweth what ye proclaim and what ye hide.'),
  ('en.pickthall', 24, 30, 'Tell the believing men to lower their gaze and be modest. That is purer for them. Lo! Allah is aware of what they do.'),
  ('en.pickthall', 24, 31, 'And tell the believing women to lower their gaze and be modest, and to display of their adornment only that which is apparent, and to draw their veils over their bosoms, and not to reveal their adornment save to their own husbands or fathers or husbands\' fathers, or their sons or their husbands\' sons, or their brothers or their brothers\' sons or sisters\' sons, or their women, or their slaves, or male attendants who lack vigour, or children who know naught of women\'s nakedness. And let them not stamp their feet so as to reveal what they hide of their adornment. And turn unto Allah together, O believers, in order that ye may succeed.'),
  ('en.pickthall', 24, 32, 'And marry such of you as are solitary and the pious of your slaves and maid-servants. If they be poor, Allah will enrich them of His bounty. Allah is of ample means, Aware.'),
  ('en.pickthall', 24, 33, 'And let those who cannot find a match keep chaste till Allah give them independence by His grace. And such of your slaves as seek a writing (of emancipation), write it for them if ye are aware of aught of good in them, and bestow upon them of the wealth of Allah which He hath bestowed upon you. Force not your slave-girls to whoredom that ye may seek enjoyment of the life of the world, if they would preserve their chastity. And if one force them, then (unto them), after their compulsion, lo! Allah will be Forgiving, Merciful.'),
  ('en.pickthall', 24, 34, 'And verily We have sent down for you revelations that make plain, and the example of those who passed away before you. An admonition unto those who ward off (evil).'),
  ('en.pickthall', 24, 35, 'Allah is the Light of the heavens and the earth. The similitude of His light is as a niche wherein is a lamp. The lamp is in a glass. The glass is as it were a shining star. (This lamp is) kindled from a blessed tree, an olive neither of the East nor of the West, whose oil would almost glow forth (of itself) though no fire touched it. Light upon light. Allah guideth unto His light whom He will. And Allah speaketh to mankind in allegories, for Allah is Knower of all things.'),
  ('en.pickthall', 24, 36, '(This lamp is found) in houses which Allah hath allowed to be exalted and that His name shall be remembered therein. Therein do offer praise to Him at morn and evening.'),
  ('en.pickthall', 24, 37, 'Men whom neither merchandise nor sale beguileth from remembrance of Allah and constancy in prayer and paying to the poor their due; who fear a day when hearts and eyeballs will be overturned;'),
  ('en.pickthall', 24, 38, 'That Allah may reward them with the best of what they did, and increase reward for them of His bounty. Allah giveth blessings without stint to whom He will.'),
  ('en.pickthall', 24, 39, 'As for those who disbelieve, their deeds are as a mirage in a desert. The thirsty one supposeth it to be water till he cometh unto it and findeth it naught, and findeth, in the place thereof, Allah Who payeth him his due; and Allah is swift at reckoning.'),
  ('en.pickthall', 24, 40, 'Or as darkness on a vast, abysmal sea. There covereth him a wave, above which is a wave, above which is a cloud. Layer upon layer of darkness. When he holdeth out his hand he scarce can see it. And he for whom Allah hath not appointed light, for him there is no light.'),
  ('en.pickthall', 24, 41, 'Hast thou not seen that Allah, He it is Whom all who are in the heavens and the earth praise, and the birds in their flight? Of each He knoweth verily the worship and the praise; and Allah is Aware of what they do.'),
  ('en.pickthall', 24, 42, 'And unto Allah belongeth the Sovereignty of the heavens and the earth, and unto Allah is the journeying.'),
  ('en.pickthall', 24, 43, 'Hast thou not seen how Allah wafteth the clouds, then gathereth them, then maketh them layers, and thou seest the rain come forth from between them; He sendeth down from the heaven mountains wherein is hail, and smiteth therewith whom He will, and averteth it from whom He will. The flashing of His lightning all but snatcheth away the sight.'),
  ('en.pickthall', 24, 44, 'Allah causeth the revolution of the day and the night. Lo! herein is indeed a lesson for those who see.'),
  ('en.pickthall', 24, 45, 'Allah hath created every animal of water. Of them is (a kind) that goeth upon its belly and (a kind) that goeth upon two legs and (a kind) that goeth upon four. Allah createth what He will. Lo! Allah is Able to do all things.'),
  ('en.pickthall', 24, 46, 'Verily We have sent down revelations and explained them. Allah guideth whom He will unto a straight path.'),
  ('en.pickthall', 24, 47, 'And they say: We believe in Allah and the messenger, and we obey; then after that a faction of them turn away. Such are not believers.'),
  ('en.pickthall', 24, 48, 'And when they appeal unto Allah and His messenger to judge between them, lo! a faction of them are averse;'),
  ('en.pickthall', 24, 49, 'But if right had been with them they would have come unto him willingly.'),
  ('en.pickthall', 24, 50, 'Is there in their hearts a disease, or have they doubts, or fear they lest Allah and His messenger should wrong them in judgment? Nay, but such are evil-doers.'),
  ('en.pickthall', 24, 51, 'The saying of (all true) believers when they appeal unto Allah and His messenger to judge between them is only that they say: We hear and we obey. And such are the successful.'),
  ('en.pickthall', 24, 52, 'He who obeyeth Allah and His messenger, and feareth Allah, and keepeth duty (unto Him): such indeed are the victorious.'),
  ('en.pickthall', 24, 53, 'They swear by Allah solemnly that, if thou order them, they will go forth. Say: Swear not; known obedience (is better). Lo! Allah is Informed of what ye do.'),
  ('en.pickthall', 24, 54, 'Say: Obey Allah and obey the messenger. But if ye turn away, then (it is) for him (to do) only that wherewith he hath been charged, and for you (to do) only that wherewith ye have been charged. If ye obey him, ye will go aright. But the messenger hath no other charge than to convey (the message) plainly.'),
  ('en.pickthall', 24, 55, 'Allah hath promised such of you as believe and do good work that He will surely make them to succeed (the present rulers) in the earth even as He caused those who were before them to succeed (others); and that He will surely establish for them their religion which He hath approved for them, and will give them in exchange safety after their fear. They serve Me. They ascribe no thing as partner unto Me. Those who disbelieve henceforth, they are the miscreants.'),
  ('en.pickthall', 24, 56, 'Establish worship and pay the poor-due and obey the messenger, that haply ye may find mercy.'),
  ('en.pickthall', 24, 57, 'Think not that the disbelievers can escape in the land. Fire will be their home - a hapless journey\'s end!'),
  ('en.pickthall', 24, 58, 'O ye who believe! Let your slaves, and those of you who have not come to puberty, ask leave of you at three times (before they come into your presence): Before the prayer of dawn, and when ye lay aside your raiment for the heat of noon, and after the prayer of night. Three times of privacy for you. It is no sin for them or for you at other times, when some of you go round attendant upon others (if they come into your presence without leave). Thus Allah maketh clear the revelations for you. Allah is Knower, Wise.'),
  ('en.pickthall', 24, 59, 'And when the children among you come to puberty then let them ask leave even as those before them used to ask it. Thus Allah maketh clear His revelations for you. Allah is Knower, Wise.'),
  ('en.pickthall', 24, 60, 'As for women past child-bearing, who have no hope of marriage, it is no sin for them if they discard their (outer) clothing in such a way as not to show adornment. But to refrain is better for them. Allah is Hearer, Knower.'),
  ('en.pickthall', 24, 61, 'No blame is there upon the blind nor any blame upon the lame nor any blame upon the sick nor on yourselves if ye eat from your houses, or the houses of your fathers, or the houses of your mothers, or the houses of your brothers, or the houses of your sisters, or the houses of your fathers\' brothers, or the houses of your fathers\' sisters, or the houses of your mothers\' brothers, or the houses of your mothers\' sisters, or (from that) whereof ye hold the keys, or (from the house) of a friend. No sin shall it be for you whether ye eat together or apart. But when ye enter houses, salute one another with a greeting from Allah, blessed and sweet. Thus Allah maketh clear His revelations for you, that haply ye may understand.'),
  ('en.pickthall', 24, 62, 'They only are the true believers who believe in Allah and His messenger and, when they are with him on some common errand, go not away until they have asked leave of him. Lo! those who ask leave of thee, those are they who believe in Allah and His messenger. So, if they ask thy leave for some affair of theirs, give leave to whom thou wilt of them, and ask for them forgiveness of Allah. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 24, 63, 'Make not the calling of the messenger among you as your calling one of another. Allah knoweth those of you who steal away, hiding themselves. And let those who conspire to evade orders beware lest grief or painful punishment befall them.'),
  ('en.pickthall', 24, 64, 'Lo! verily unto Allah belongeth whatsoever is in the heavens and the earth. He knoweth your condition. And (He knoweth) the Day when they are returned unto Him so that He may inform them of what they did. Allah is Knower of all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 24, 1, 'A sura which We have sent down and which We have ordained in it have We sent down Clear Signs, in order that ye may receive admonition.'),
  ('en.yusufali', 24, 2, 'The woman and the man guilty of adultery or fornication,- flog each of them with a hundred stripes: Let not compassion move you in their case, in a matter prescribed by Allah, if ye believe in Allah and the Last Day: and let a party of the Believers witness their punishment.'),
  ('en.yusufali', 24, 3, 'Let no man guilty of adultery or fornication marry and but a woman similarly guilty, or an Unbeliever: nor let any but such a man or an Unbeliever marry such a woman: to the Believers such a thing is forbidden.'),
  ('en.yusufali', 24, 4, 'And those who launch a charge against chaste women, and produce not four witnesses (to support their allegations),- flog them with eighty stripes; and reject their evidence ever after: for such men are wicked transgressors;-'),
  ('en.yusufali', 24, 5, 'Unless they repent thereafter and mend (their conduct); for Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 24, 6, 'And for those who launch a charge against their spouses, and have (in support) no evidence but their own,- their solitary evidence (can be received) if they bear witness four times (with an oath) by Allah that they are solemnly telling the truth;'),
  ('en.yusufali', 24, 7, 'And the fifth (oath) (should be) that they solemnly invoke the curse of Allah on themselves if they tell a lie.'),
  ('en.yusufali', 24, 8, 'But it would avert the punishment from the wife, if she bears witness four times (with an oath) By Allah, that (her husband) is telling a lie;'),
  ('en.yusufali', 24, 9, 'And the fifth (oath) should be that she solemnly invokes the wrath of Allah on herself if (her accuser) is telling the truth.'),
  ('en.yusufali', 24, 10, 'If it were not for Allah\'s grace and mercy on you, and that Allah is Oft-Returning, full of Wisdom,- (Ye would be ruined indeed).'),
  ('en.yusufali', 24, 11, 'Those who brought forward the lie are a body among yourselves: think it not to be an evil to you; On the contrary it is good for you: to every man among them (will come the punishment) of the sin that he earned, and to him who took on himself the lead among them, will be a penalty grievous.'),
  ('en.yusufali', 24, 12, 'Why did not the believers - men and women - when ye heard of the affair,- put the best construction on it in their own minds and say, "This (charge) is an obvious lie"?'),
  ('en.yusufali', 24, 13, 'Why did they not bring four witnesses to prove it? When they have not brought the witnesses, such men, in the sight of Allah, (stand forth) themselves as liars!'),
  ('en.yusufali', 24, 14, 'Were it not for the grace and mercy of Allah on you, in this world and the Hereafter, a grievous penalty would have seized you in that ye rushed glibly into this affair.'),
  ('en.yusufali', 24, 15, 'Behold, ye received it on your tongues, and said out of your mouths things of which ye had no knowledge; and ye thought it to be a light matter, while it was most serious in the sight of Allah.'),
  ('en.yusufali', 24, 16, 'And why did ye not, when ye heard it, say? - "It is not right of us to speak of this: Glory to Allah! this is a most serious slander!"'),
  ('en.yusufali', 24, 17, 'Allah doth admonish you, that ye may never repeat such (conduct), if ye are (true) Believers.'),
  ('en.yusufali', 24, 18, 'And Allah makes the Signs plain to you: for Allah is full of knowledge and wisdom.'),
  ('en.yusufali', 24, 19, 'Those who love (to see) scandal published broadcast among the Believers, will have a grievous Penalty in this life and in the Hereafter: Allah knows, and ye know not.'),
  ('en.yusufali', 24, 20, 'Were it not for the grace and mercy of Allah on you, and that Allah is full of kindness and mercy, (ye would be ruined indeed).'),
  ('en.yusufali', 24, 21, 'O ye who believe! follow not Satan\'s footsteps: if any will follow the footsteps of Satan, he will (but) command what is shameful and wrong: and were it not for the grace and mercy of Allah on you, not one of you would ever have been pure: but Allah doth purify whom He pleases: and Allah is One Who hears and knows (all things).'),
  ('en.yusufali', 24, 22, 'Let not those among you who are endued with grace and amplitude of means resolve by oath against helping their kinsmen, those in want, and those who have left their homes in Allah\'s cause: let them forgive and overlook, do you not wish that Allah should forgive you? For Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 24, 23, 'Those who slander chaste women, indiscreet but believing, are cursed in this life and in the Hereafter: for them is a grievous Penalty,-'),
  ('en.yusufali', 24, 24, 'On the Day when their tongues, their hands, and their feet will bear witness against them as to their actions.'),
  ('en.yusufali', 24, 25, 'On that Day Allah will pay them back (all) their just dues, and they will realise that Allah is the (very) Truth, that makes all things manifest.'),
  ('en.yusufali', 24, 26, 'Women impure are for men impure, and men impure for women impure and women of purity are for men of purity, and men of purity are for women of purity: these are not affected by what people say: for them there is forgiveness, and a provision honourable.'),
  ('en.yusufali', 24, 27, 'O ye who believe! enter not houses other than your own, until ye have asked permission and saluted those in them: that is best for you, in order that ye may heed (what is seemly).'),
  ('en.yusufali', 24, 28, 'If ye find no one in the house, enter not until permission is given to you: if ye are asked to go back, go back: that makes for greater purity for yourselves: and Allah knows well all that ye do.'),
  ('en.yusufali', 24, 29, 'It is no fault on your part to enter houses not used for living in, which serve some (other) use for you: And Allah has knowledge of what ye reveal and what ye conceal.'),
  ('en.yusufali', 24, 30, 'Say to the believing men that they should lower their gaze and guard their modesty: that will make for greater purity for them: And Allah is well acquainted with all that they do.'),
  ('en.yusufali', 24, 31, 'And say to the believing women that they should lower their gaze and guard their modesty; that they should not display their beauty and ornaments except what (must ordinarily) appear thereof; that they should draw their veils over their bosoms and not display their beauty except to their husbands, their fathers, their husband\'s fathers, their sons, their husbands\' sons, their brothers or their brothers\' sons, or their sisters\' sons, or their women, or the slaves whom their right hands possess, or male servants free of physical needs, or small children who have no sense of the shame of sex; and that they should not strike their feet in order to draw attention to their hidden ornaments. And O ye Believers! turn ye all together towards Allah, that ye may attain Bliss.'),
  ('en.yusufali', 24, 32, 'Marry those among you who are single, or the virtuous ones among yourselves, male or female: if they are in poverty, Allah will give them means out of His grace: for Allah encompasseth all, and he knoweth all things.'),
  ('en.yusufali', 24, 33, 'Let those who find not the wherewithal for marriage keep themselves chaste, until Allah gives them means out of His grace. And if any of your slaves ask for a deed in writing (to enable them to earn their freedom for a certain sum), give them such a deed if ye know any good in them: yea, give them something yourselves out of the means which Allah has given to you. But force not your maids to prostitution when they desire chastity, in order that ye may make a gain in the goods of this life. But if anyone compels them, yet, after such compulsion, is Allah, Oft-Forgiving, Most Merciful (to them),'),
  ('en.yusufali', 24, 34, 'We have already sent down to you verses making things clear, an illustration from (the story of) people who passed away before you, and an admonition for those who fear (Allah).'),
  ('en.yusufali', 24, 35, 'Allah is the Light of the heavens and the earth. The Parable of His Light is as if there were a Niche and within it a Lamp: the Lamp enclosed in Glass: the glass as it were a brilliant star: Lit from a blessed Tree, an Olive, neither of the east nor of the west, whose oil is well-nigh luminous, though fire scarce touched it: Light upon Light! Allah doth guide whom He will to His Light: Allah doth set forth Parables for men: and Allah doth know all things.'),
  ('en.yusufali', 24, 36, '(Lit is such a Light) in houses, which Allah hath permitted to be raised to honour; for the celebration, in them, of His name: In them is He glorified in the mornings and in the evenings, (again and again),-'),
  ('en.yusufali', 24, 37, 'By men whom neither traffic nor merchandise can divert from the Remembrance of Allah, nor from regular Prayer, nor from the practice of regular Charity: Their (only) fear is for the Day when hearts and eyes will be transformed (in a world wholly new),-'),
  ('en.yusufali', 24, 38, 'That Allah may reward them according to the best of their deeds, and add even more for them out of His Grace: for Allah doth provide for those whom He will, without measure.'),
  ('en.yusufali', 24, 39, 'But the Unbelievers,- their deeds are like a mirage in sandy deserts, which the man parched with thirst mistakes for water; until when he comes up to it, he finds it to be nothing: But he finds Allah (ever) with him, and Allah will pay him his account: and Allah is swift in taking account.'),
  ('en.yusufali', 24, 40, 'Or (the Unbelievers\' state) is like the depths of darkness in a vast deep ocean, overwhelmed with billow topped by billow, topped by (dark) clouds: depths of darkness, one above another: if a man stretches out his hands, he can hardly see it! for any to whom Allah giveth not light, there is no light!'),
  ('en.yusufali', 24, 41, 'Seest thou not that it is Allah Whose praises all beings in the heavens and on earth do celebrate, and the birds (of the air) with wings outspread? Each one knows its own (mode of) prayer and praise. And Allah knows well all that they do.'),
  ('en.yusufali', 24, 42, 'Yea, to Allah belongs the dominion of the heavens and the earth; and to Allah is the final goal (of all).'),
  ('en.yusufali', 24, 43, 'Seest thou not that Allah makes the clouds move gently, then joins them together, then makes them into a heap? - then wilt thou see rain issue forth from their midst. And He sends down from the sky mountain masses (of clouds) wherein is hail: He strikes therewith whom He pleases and He turns it away from whom He pleases, the vivid flash of His lightning well-nigh blinds the sight.'),
  ('en.yusufali', 24, 44, 'It is Allah Who alternates the Night and the Day: verily in these things is an instructive example for those who have vision!'),
  ('en.yusufali', 24, 45, 'And Allah has created every animal from water: of them there are some that creep on their bellies; some that walk on two legs; and some that walk on four. Allah creates what He wills for verily Allah has power over all things.'),
  ('en.yusufali', 24, 46, 'We have indeed sent down signs that make things manifest: and Allah guides whom He wills to a way that is straight.'),
  ('en.yusufali', 24, 47, 'They say, "We believe in Allah and in the messenger, and we obey": but even after that, some of them turn away: they are not (really) Believers.'),
  ('en.yusufali', 24, 48, 'When they are summoned to Allah and His messenger, in order that He may judge between them, behold some of them decline (to come).'),
  ('en.yusufali', 24, 49, 'But if the right is on their side, they come to him with all submission.'),
  ('en.yusufali', 24, 50, 'Is it that there is a disease in their hearts? or do they doubt, or are they in fear, that Allah and His Messenger will deal unjustly with them? Nay, it is they themselves who do wrong.'),
  ('en.yusufali', 24, 51, 'The answer of the Believers, when summoned to Allah and His Messenger, in order that He may judge between them, is no other than this: they say, "We hear and we obey": it is such as these that will attain felicity.'),
  ('en.yusufali', 24, 52, 'It is such as obey Allah and His Messenger, and fear Allah and do right, that will win (in the end),'),
  ('en.yusufali', 24, 53, 'They swear their strongest oaths by Allah that, if only thou wouldst command them, they would leave (their homes). Say: "Swear ye not; Obedience is (more) reasonable; verily, Allah is well acquainted with all that ye do."'),
  ('en.yusufali', 24, 54, 'Say: "Obey Allah, and obey the Messenger: but if ye turn away, he is only responsible for the duty placed on him and ye for that placed on you. If ye obey him, ye shall be on right guidance. The Messenger\'s duty is only to preach the clear (Message).'),
  ('en.yusufali', 24, 55, 'Allah has promised, to those among you who believe and work righteous deeds, that He will, of a surety, grant them in the land, inheritance (of power), as He granted it to those before them; that He will establish in authority their religion - the one which He has chosen for them; and that He will change (their state), after the fear in which they (lived), to one of security and peace: \'They will worship Me (alone) and not associate aught with Me. \'If any do reject Faith after this, they are rebellious and wicked.'),
  ('en.yusufali', 24, 56, 'So establish regular Prayer and give regular Charity; and obey the Messenger; that ye may receive mercy.'),
  ('en.yusufali', 24, 57, 'Never think thou that the Unbelievers are going to frustrate (Allah\'s Plan) on earth: their abode is the Fire,- and it is indeed an evil refuge!'),
  ('en.yusufali', 24, 58, 'O ye who believe! let those whom your right hands possess, and the (children) among you who have not come of age ask your permission (before they come to your presence), on three occasions: before morning prayer; the while ye doff your clothes for the noonday heat; and after the late-night prayer: these are your three times of undress: outside those times it is not wrong for you or for them to move about attending to each other: Thus does Allah make clear the Signs to you: for Allah is full of knowledge and wisdom.'),
  ('en.yusufali', 24, 59, 'But when the children among you come of age, let them (also) ask for permission, as do those senior to them (in age): Thus does Allah make clear His Signs to you: for Allah is full of knowledge and wisdom.'),
  ('en.yusufali', 24, 60, 'Such elderly women as are past the prospect of marriage,- there is no blame on them if they lay aside their (outer) garments, provided they make not a wanton display of their beauty: but it is best for them to be modest: and Allah is One Who sees and knows all things.'),
  ('en.yusufali', 24, 61, 'It is no fault in the blind nor in one born lame, nor in one afflicted with illness, nor in yourselves, that ye should eat in your own houses, or those of your fathers, or your mothers, or your brothers, or your sisters, or your father\'s brothers or your father\'s sisters, or your mother\'s brothers, or your mother\'s sisters, or in houses of which the keys are in your possession, or in the house of a sincere friend of yours: there is no blame on you, whether ye eat in company or separately. But if ye enter houses, salute each other - a greeting of blessing and purity as from Allah. Thus does Allah make clear the signs to you: that ye may understand.'),
  ('en.yusufali', 24, 62, 'Only those are believers, who believe in Allah and His Messenger: when they are with him on a matter requiring collective action, they do not depart until they have asked for his leave; those who ask for thy leave are those who believe in Allah and His Messenger; so when they ask for thy leave, for some business of theirs, give leave to those of them whom thou wilt, and ask Allah for their forgiveness: for Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 24, 63, 'Deem not the summons of the Messenger among yourselves like the summons of one of you to another: Allah doth know those of you who slip away under shelter of some excuse: then let those beware who withstand the Messenger\'s order, lest some trial befall them, or a grievous penalty be inflicted on them.'),
  ('en.yusufali', 24, 64, 'Be quite sure that to Allah doth belong whatever is in the heavens and on earth. Well doth He know what ye are intent upon: and one day they will be brought back to Him, and He will tell them the truth of what they did: for Allah doth know all things.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 24, 1, 'Sooratun anzalnaahaa wa faradnaahaa wa anzalnaa feehaaa Aayaatim baiyinaatil la\'allakum tazakkaroon'),
  ('en.transliteration', 24, 2, 'Azzaaniyatu wazzaanee fajlidoo kulla waahidim minhumaa mi\'ata jaldatinw wa laa taakhuzkum bihimaa raafatun fee deenil laahi in kuntum tu\'minoona billaahi wal Yawmil Aakhiri wal yashhad \'azaabahumaa taaa\'ifatum minal mu\'mineen'),
  ('en.transliteration', 24, 3, 'Azzaanee laa yankihu illaa zaaniyatan aw mushrikatanw wazzaaniyatu laa yankihuhaaa illaa zaanin aw mushrik; wa hurrima zaalika \'alal mu\'mineen'),
  ('en.transliteration', 24, 4, 'Wallazeena yarmoonal muhsanaati summa lam yaatoo bi-arba\'ati shuhadaaa\'a fajlidoohum samaaneena jaldatanw wa laa taqbaloo lahum shahaadatan abadaa; wa ulaaa\'ika humul faasiqoon'),
  ('en.transliteration', 24, 5, 'Illal lazeena taaboo mim ba\'di zaalika wa aslahoo fa innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 24, 6, 'Wallazeena yarmoona azwaajahum wa lam yakul lahum shuhadaaa\'u illaaa anfusuhum fashahaadatu ahadihim arb\'u shahaadaatim billaahi innahoo laminas saadiqeen'),
  ('en.transliteration', 24, 7, 'Wal khaamisatu anna la\'natal laahi \'alaihi in kaana minal kaazibeen'),
  ('en.transliteration', 24, 8, 'Wa yadra\'u anhal \'azaaba an tashhada arba\'a shahaa daatim billaahi innahoo laminal kaazibeen'),
  ('en.transliteration', 24, 9, 'Wal khaamisata anna ghadabal laahi \'alaihaaa in kaana minas saadiqeen'),
  ('en.transliteration', 24, 10, 'Wa law laa fadlul laahi \'alaikum wa rahmatuhoo wa annal laaha Tawwaabun Hakeem'),
  ('en.transliteration', 24, 11, 'Innal lazeena jaaa\'oo bilifki \'usbatum minkum; laa tahsaboohu sharral lakum bal huwa khairul lakum; likul limri\'im minhum mak tasaba minal-ism; wallazee tawallaa kibrahoo minhum lahoo \'azaabun \'azeem'),
  ('en.transliteration', 24, 12, 'Law laaa iz sami\'tumoohu zannal mu\'minoona walmu\'minaatu bi anfusihim khairanw wa qaaloo haazaaa ifkum mmubeen'),
  ('en.transliteration', 24, 13, 'Law laa jaaa\'oo \'alaihi bi-arba\'ati shuhadaaa\'; fa iz lam yaatoo bishshuhadaaa\'i fa ulaaa \'ika \'indal laahi humul kaaziboon'),
  ('en.transliteration', 24, 14, 'Wa law laa fadlul laahi \'alaikum wa rahmatuhoo fiddunyaa wal aakhirati lamassakum fee maaa afadtum feehi \'azaabun \'azeem'),
  ('en.transliteration', 24, 15, 'iz talaqqawnahoo bi alsinatikum wa taqooloona bi afwaahikum maa laisa lakum bihee \'ilmunw wa tahsaboo nahoo haiyinanw wa huwa \'indl laahi \'azeem'),
  ('en.transliteration', 24, 16, 'Wa law laaa iz sami\'tu moohu qultum maa yakoonu lanaaa an natakallama bihaazaa Subhaanaka haaza buhtaanun \'azeem'),
  ('en.transliteration', 24, 17, 'Ya\'izukumul laahu an ta\'oodoo limisliheee abadan in kuntum mu\'mineen'),
  ('en.transliteration', 24, 18, 'Wa yubaiyinul laahu lakumul Aayaat; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 24, 19, 'Innal lazeena yuhibboona an tashee\'al faahishatu fil lazeena aamanoo lahum \'azaabun aleemun fid dunyaa wal Aakhirah; wallaahu ya\'lamu wa antum laa ta\'lamoon'),
  ('en.transliteration', 24, 20, 'Wa law laa fadlul laahi \'alaikum wa rahmatuhoo wa annal laaha Ra\'oofur Raheem'),
  ('en.transliteration', 24, 21, 'Yaaa aiyuhal lazeena aamanoo laa tattabi\'oo khutuwaatish Shaitaan; wa many-yattabi\' khutuwaatish Shaitaani fa innahoo yaamuru bilfahshaaa\'i walmunkar; wa law laa fadlul laahi \'alaikum wa rahmatuhoo maa zakaa minkum min ahadin abadanw wa laakinnal laaha yuzakkee many-yashaaa\'; wallaahu Samee\'un \'Aleem'),
  ('en.transliteration', 24, 22, 'Wa laa yaatali ulul fadli minkum wassa\'ati ai yu\'tooo ulil qurbaa walmasaakeena walmuhaajireena fee sabeelillaahi walya\'foo walyasfahoo; alaa tuhibboona ai yaghfiral laahu lakum; wal laahu Ghafoorur Raheem'),
  ('en.transliteration', 24, 23, 'Innal lazeena yarmoonal muhsanaatil ghaafilaatil mu\'minaati lu\'inoo fid dunyaa wal Aakhirati wa lahum \'azaabun \'azeem'),
  ('en.transliteration', 24, 24, 'Yawma tashhhadu \'alaihim alsinatuhum wa aideehim wa arjuluhum bimaa kaanoo ya\'maloon'),
  ('en.transliteration', 24, 25, 'Yawma\'iziny yuwaf feehimul laahu deenahumul haqqa wa ya\'lamoona annal laaha Huwal Haqqul Mubeen'),
  ('en.transliteration', 24, 26, 'Alkhabeesaatu lilkha beeseena walkhabeesoona lilkhabeesaati wattaiyibaatu littaiyibeena wattaiyiboona littaiyibaat; ulaaa\'ika mubar ra\'oona maimma yaqooloona lahum maghfiratunw wa rizqun kareem'),
  ('en.transliteration', 24, 27, 'Yaaa aiyuhal lazeena aamanoo laa tadkhuloo buyootan ghaira buyootikum hatta tastaanisoo wa tusallimoo \'allaa ahlihaa; zaalikum khairul lakum la\'allakum tazakkaroon'),
  ('en.transliteration', 24, 28, 'Fa il lam tajidoo feehaaa ahadan falaa tadkhuloohaa hattaa yu\'zana lakum wa in qeela lakumurji\'oo farji\'oo huwa azkaa lakum; wallaahu bimaa ta\'maloona \'Aleem'),
  ('en.transliteration', 24, 29, 'Laisa \'alaikum junaahun ann tadkhuloo buyootan ghaira maskoonatin feeha mataa\'ul lakum; wallaahu ya\'lamu maa tubdoona wa maa taktumoon'),
  ('en.transliteration', 24, 30, 'Qul lilmu\' mineena yaghuuddoo min absaarihim wa yahfazoo furoojahum; zaalika azkaa lahum; innallaaha khabeerum bimaa yasna\'oon'),
  ('en.transliteration', 24, 31, 'Wa qul lilmu\'minaati yaghdudna min absaarihinna wa yahfazna furoojahunna wa laa yubdeena zeenatahunna illaa maa zahara minhaa walyadribna bikhumurihinna \'alaa juyoobihinna wa laa yubdeena zeenatahunna illaa libu\'oolatihinna aw aabaaa\'i hinna aw aabaaa\'i bu\'oolati hinna aw abnaaa\'ihinaa aw abnaaa\'i bu\'oolatihinnna aw ikhwaanihinnna aw baneee ikhwaanihinna aw banee akhawaatihinna aw nisaaa\'i hinna aw maa malakat aimaanuhunna awit taabi\'eena ghairi ilil irbati minar rijaali awit tiflillazeena lam yazharoo \'alaa \'awraatin nisaaa\'i wala yadribnna bi arjulihinna min zeenatihinn; wa toobooo ilallaahi jammee\'an aiyuhal mu\'minoona la\'allakum tuflihoon'),
  ('en.transliteration', 24, 32, 'Wa ankihul ayaamaa minkum was saaliheena min \'ibaadikum wa imaa\'kum; iny-yakoonoo fuqaraaa\'a yughni himul laahu min fadlih; wal laahu Waasi\'un \'Aleem'),
  ('en.transliteration', 24, 33, 'Wal yasta\'fifil lazeena laa yajidoona nikaahan hata yughniyahumul laahu mi fadlih; wallazeena yabtaghoonal kitaaba mimmaa malakat aimaanukum fakaatiboohum in \'alimtum feehim khairanw wa aatoohum mimmaalil laahil lazeee aataakum; wa laa tukrihoo fatayaatikum \'alal bighaaa\'i in aradna tahassunal litabtaghoo \'aradal hayaatid dunyaa; wa mai yukrihhunna fa innal laaha mim ba\'di ikraahihinna Ghafoor Raheem'),
  ('en.transliteration', 24, 34, 'Wa laqad anzalnaaa ilaikum Aayaatim mubaiyinaatinw wa masalam minnal lazeena khalaw min qablikum wa maw\'izatal lilmuttaqeen'),
  ('en.transliteration', 24, 35, 'Allaahu noorus samaawaati wal ard; masalu noorihee kamishkaatin feehaa misbaah; almisbaahu fee zujaajatin azzujaajatu ka annahaa kawkabun durriyyuny yooqadu min shajaratim mubaarakatin zaitoonatil laa shariqiyyatinw wa laa gharbiyyatiny yakaadu zaituhaa yudeee\'u wa law alm tamsashu naar; noorun \'alaa noor; yahdil laahu linoorihee mai yashaaa\'; wa yadribul laahul amsaala linnaas; wallaahu bikulli shai\'in Aleem'),
  ('en.transliteration', 24, 36, 'Fee buyootin azinal laahu an turfa\'a wa yuzkara feehasmuhoo yusabbihu lahoo feehaa bilghuduwwi wal aasaal'),
  ('en.transliteration', 24, 37, 'Rinjaalul laa tulheehim tijaaratunw wa laa bai\'un \'an zikril laahi wa iqaamis Salaati wa eetaaa\'iz Zakaati yakkhaafoona Yawman tataqallabu feehil quloobu wal absaar'),
  ('en.transliteration', 24, 38, 'Liyajziyahumul laahu ahsana maa \'amiloo wa yazeedahum min fadlih; wal laahu yarzuqu mai yashaaa\'u bighairi hisaab'),
  ('en.transliteration', 24, 39, 'Wallazeena kafarooo a\'maaluhum kasaraabim biqee\'atiny yahsabuhuz zamaanu maaa\'an hattaaa izaa jaaa\'ahoo lam yajid hu shai\'anw wa wajadal laaha \'indahoo fa waffaahu hisaabah; wallaahu saree\'ul hisaab'),
  ('en.transliteration', 24, 40, 'Aw kazulumaatin fee bahril lujjiyyiny yaghshaahu mawjum min fawqihee mawjum min fawqihee mawjum min fawqihee sahaab; zulumatum ba\'duhaa fawqa ba\'din izaaa akhraja yadahoo lam yakad yaraahaa wa mal lam yaj\'alil laahu lahoo noora famaa lahoo min noor'),
  ('en.transliteration', 24, 41, 'Alam tara annal laaha yusabbihu lahoo man fissamaawaati wal ardi wat tairu saaaffaatim kullun qad \'alima Salaatahoo wa tasbeehah; wallaahu \'aleemum bimaa yaf\'aloon'),
  ('en.transliteration', 24, 42, 'Wa lillaahi mulkus samaawaati wal ardi wa ilal laahil maseer'),
  ('en.transliteration', 24, 43, 'Alam tara annal laaha yuzjee sahaaban summa yu\'allifu bainahoo summa yaj\'aluhoo rukaaman fataral wadqa yakhruju min khilaalihee wa yunazzilu minas samaaa\'i min jibaalin feehaa mim barain fa yuseebu bihee mai yashaaa\'u wa yasrifuhoo \'am mai yashaaa\'u yakkaadu sanaa barqihee yazhabu bil absaar'),
  ('en.transliteration', 24, 44, 'Yuqallibul laahul laila wannahaar; inna fee zaalika la\'ibratal li ulil absaar'),
  ('en.transliteration', 24, 45, 'Wallaahu khalaqa kulla daaabbatim mim maaa\'in faminhum mai yamshee \'alaa batnihee wa minhum mai yamshee \'alaa rijlaine wa minhum mai yamshee \'alaaa arba\'; yakhluqul laahu maa yashaaa\'; innal laaha \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 24, 46, 'Laqad anzalnaaa Aayaatim mubaiyinaat; wallaahu yahdee mai yashaaa\'u ilaa Siraatim Mustaqeem'),
  ('en.transliteration', 24, 47, 'Wa yaqooloona aamannaa billaahi wa bir Rasooli wa ata\'naa summa yatawallaa fareequm minhum mim ba\'di zaalik; wa maaa ulaaa\'ika bilmu\'mineen'),
  ('en.transliteration', 24, 48, 'Wa izaa du\'ooo ilal laahi wa Rasoolihee li yahkuma bainahum izaa fareequm minhum mu\'ridoon'),
  ('en.transliteration', 24, 49, 'Wa iny-yakul lahumul haqqu yaatooo ilaihi muz\'ineen'),
  ('en.transliteration', 24, 50, 'Afee quloobihim ma radun amirtaabooo am yakhaafoona ani yaheefallaahu \'alaihim wa Rasooluh; bal ulaaa\'ika humuz zaalimoon'),
  ('en.transliteration', 24, 51, 'Innamaa kaana qawlal mu\'mineena izaa du\'ooo ilal laahi wa Rasoolihee li yahkuma bainahum ai yaqooloo sami\'naa wa ata\'naa; wa ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 24, 52, 'Wa mai yuti\'il laaha wa Rasoolahoo wa yakhshal laaha wa yattaqhi fa ulaaa\'ika humul faaa\'izoon'),
  ('en.transliteration', 24, 53, 'Wa aqsamoo billaahi jahda aimaanihim la\'in amartahum la yakhrujunna qul laa tuqsimoo taa\'atum ma\'roofah innal laaha khabeerum bimaa ta\'maloon'),
  ('en.transliteration', 24, 54, 'Qul atee\'ul laaha wa atee\'ur Rasoola fa in tawallaw fa innamaa \'alaihi maa hummila wa \'alaikum maa hummiltum wa in tutee\'oohu tahtadoo; wa maa\'alar Rasooli illal balaaghul mubeen'),
  ('en.transliteration', 24, 55, 'Wa\'adal laahul lazeena aamanoo minkum wa \'amilus saalihaati la yastakhlifan nahum fil ardi kamastakh lafal lazeena min qablihim wa la yumakkinanna lahum deenahumul lazir tadaa lahum wa la yubaddilannahum mim ba\'di khawfihim amnaa; ya\'budoonanee laayushrikoona bee shai\'aa; wa man kafara ba\'da zaalika fa ulaaa\'ika humul faasiqoon'),
  ('en.transliteration', 24, 56, 'Wa aqeemus Salaata wa aatuz Zakaata wa atee\'ur Rasoola la\'allakum turhamoon'),
  ('en.transliteration', 24, 57, 'Laa tahsabannal lazeena kafaroo mu\'jizeena fil ard; wa maawaahumun Naaru wa labi\'sal maseer'),
  ('en.transliteration', 24, 58, 'Yaaa aiyuhal lazeena aamanoo li yastaazinkumul lazeena malakat aimaanukum wallazeena lam yablughul huluma minkum salaasa marraat; min qabli Salaatil Fajri wa heena tada\'oona siyaa bakum minaz zaheerati wa mim ba\'di Salaatil Ishaaa\'; salaasu \'awraatil lakum; laisa \'alaikum wa laa \'alaihim junaahum ba\'dahunn; tawwaafoona \'alaikum ba\'dukum \'alaa ba\'d; kazaalika yubaiyinul laahu lakumul aayaat wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 24, 59, 'Wa izaa balaghal atfaalu minkumul huluma fal yastaazinoo kamas taazanal lazeena min qablihim; kazaalika yubaiyinul laahu lakum Aayaatih; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 24, 60, 'Walqawaa\'idu minan nisaaa\'il laatee laa yarjoona nikaahan falisa \'alaihinna junaahun ai yada\'na siyaabahunna ghaira mutabar rijaatim bizeenah; wa ai yasta\'fifna khairul lahunn; wallaahu Samee\'un \'Aleem'),
  ('en.transliteration', 24, 61, 'Laisa \'alal a\'maa barajunw wa laa \'alal a\'raji barajunw wa laa \'alal mareedi barajun wa laa \'alaa anfusikum an taakuloo mim buyootikum aw buyooti aabaaa\'ikum aw buyooti ummahaatikum aw buyooti ikhwaanikum aw buyooti akhawaatikum aw buyooti a\'maamikum aw buyooti \'ammaatikum aw buyooti akhwaalikum aw buyooti khaalaatikum aw maa malaktum mafaatihahooo aw sadeeqikum; laisa \'alaikum junaahun an taakuloo jamee\'an aw ashtaata; fa izaa dakhaltum buyootan fasallimoo \'alaaa anfusikum tahiyyatam min \'indil laahi mubaarakatan taiyibah; kazaalika yubai yinul laahu lakumul Aayaati la\'allakum ta\'qiloon'),
  ('en.transliteration', 24, 62, 'Innamal mu\'minoonal lazeena aamanoo billaahi wa Rasoolihee wa izaa kaanoo ma\'ahoo \'alaaa amrin jaami\'il lam yazhaboo hataa yastaazinooh; innal lazeena yastaa zinookana ulaaa\'ikal lazeena yu\'minoona billaahi wa Rasoolih; fa izas taazanooka liba\'di shaanihim faazal liman shi\'ta minhum wastaghfir lahumul laah; innal laaha Gahfoor Raheem'),
  ('en.transliteration', 24, 63, 'La taj\'aloo du\'aaa\'ar Rasooli bainakum kadu\'aaa\'i badikum ba\'daa; qad ya\'lamul laahul lazeena yatasallaloona minkum liwaazaa; fal yahzaril lazeena yukhaalifoona \'an amriheee an tuseebahum fitnatun aw yuseebahum \'azaabun aleem'),
  ('en.transliteration', 24, 64, 'Alaaa inna lillaahi maa fis samaawaati wal ardi qad ya\'lamu maaa antum \'alaihi wa Yawma yurja\'oona ilaihi fa yunaabi \'uhum bimaa \'amiloo; wallaahu bikulli shai\'in \'Aleem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 24, 1, 'یہ ایک سورت ہے جسے ہم نے نازل کیا ہے اور اس کے احکام ہم نے ہی فرض کئے ہیں اور ہم نے اس میں صاف صاف آیتیں نازل کی ہیں تاکہ تم سمجھو'),
  ('ur.ahmedali', 24, 2, 'بدکار عورت اور بدکار مرد سو دونوں میں سے ہر ایک کو سو سو دُرّے مارو اور تمہیں الله کے معاملہ میں ان پر ذرا رحم نہ آنا چاہیئے اگر تم الله پر اور قیامت کے دن پر ایمان رکھتے ہو اور ان کی سزا کے وقت مسلمانوں کی ایک جماعت کو حاضر رہنا چاہیئے'),
  ('ur.ahmedali', 24, 3, 'بدکار مرد سوائے بدکار عورت یا مشرکہ کے نکاح نہیں کرے گا اور بدکار عورت سے سوائے بد کار مرد یا مشرک کے اور کوئی نکاح نہیں کرے گا اور ایمان والوں پر یہ حرام کیا گیا ہے'),
  ('ur.ahmedali', 24, 4, 'اور جو لوگ پاک دامن عورتوں پر تہمت لگاتے ہیں اور پھر چار گواہ نہیں لاتے تو انہیں اسّی درے مارو اور کبھی ان کی گواہی قبول نہ کرو اور وہی لوگ نافرمان ہیں'),
  ('ur.ahmedali', 24, 5, 'مگر جنہوں نے اس کے بعد توبہ کر لی اور درست ہو گئے تو بے شک الله ہی بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 24, 6, 'او رجو لوگ اپنی بیویوں پر تہمت لگاتے ہیں اور ان کے لیے سوائے اپنے اورکوئی گواہ نہیں تو ایسے شخص کی گواہی کی یہ صورت ہے کہ چار مرتبہ الله کی قسم کھا کر گواہی دے کہ بے شک وہ سچا ہے'),
  ('ur.ahmedali', 24, 7, 'او رپانچویں مرتبہ یہ کہے کہ اس پر اللہ کی لعنت ہواگر وہ جھوٹا ہے'),
  ('ur.ahmedali', 24, 8, 'او رعورت کی سزا کو یہ بات دور کر دے گی کہ الله کو گواہ کر کے چار مرتبہ یہ کہے کہ بے شک اس پر الله کا غضب پڑے اگر وہ سچا ہے'),
  ('ur.ahmedali', 24, 9, 'اور پانچویں مرتبہ کہے کہ بے شک اس پر الله کا غضب پڑے اگر وہ سچا ہے'),
  ('ur.ahmedali', 24, 10, 'اور اگر تم پر الله کا فضل اور اس کی رحمت نہ ہوتی اور یہ کہ الله توبہ قبول کرنے والا حکمت والا ہے (تو کیا کچھ نہ ہوتا)'),
  ('ur.ahmedali', 24, 11, 'بے شک جو لوگ یہ طوفان لائے ہیں تم ہی میں سے ایک گروہ ہے تم سے اپنے حق میں برا نہ سمجھو بلکہ وہ تمہارے لیے بہتر ہے ان میں سے ہر ایک کے لیے بقدرِ عمل گناہ ہے اور جس نے ان میں سے سب سے زیادہ حصہ لیا اس کے لیے بڑا عذاب ہے'),
  ('ur.ahmedali', 24, 12, 'جب تم نے یہ بات سنی تھی تو مسلمان مردوں اور مسلمان عورتوں نے اپنے لوگوں کے ساتھ نیک گمان کیوں نہ کیا او رکیو ں نہ کہا کہ یہ صریح بہتان ہے'),
  ('ur.ahmedali', 24, 13, 'یہ لوگ اس پرچار گواہ کیو ں نہ لائے پھر جب وہ گواہ نہ لائے تو الله کے نزدیک وہی جھوٹے ہیں'),
  ('ur.ahmedali', 24, 14, 'اور اگر تم پر الله کا فضل اور دنیا اور آخرت میں اس کی رحمت نہ ہوتی تو اس چرچا کرنے میں تم پر کوئی بڑی آفت پڑتی'),
  ('ur.ahmedali', 24, 15, 'جب تم اسے اپنی زبانوں سے نکالنے لگے اور اپنے مونہوں سے وہ بات کہنی شروع کر دی جس کا تمہیں علم بھی نہ تھا اور تم نے اسے ہلکی بات سمجھ لیا تھا حالانکہ وہ الله کے نزدیک بڑی بات ہے'),
  ('ur.ahmedali', 24, 16, 'اور جب تم نے اسے سنا تھا تو کیوں نہ کہہ دیا کہ ہمیں تو اس کا منہ سے نکالنا بھی لائق نہیں سبحان الله یہ بڑا بہتان ہے'),
  ('ur.ahmedali', 24, 17, 'الله تمہیں نصیحت کرتا ہے کہ پھر کبھی ایسا نہ کرنا اگر تم ایمان دار ہو'),
  ('ur.ahmedali', 24, 18, 'اور الله تمہارے لیے آیتیں بیان کرتا ہے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 24, 19, 'بے شک جو لوگ چاہتے ہیں کہ ایمانداروں میں بدکاری کا چرچا ہو ان کے لیے دنیا اور آخرت میں دردناک عذاب ہے اور الله جانتا ہے اور تم نہیں جانتے'),
  ('ur.ahmedali', 24, 20, 'اور اگرتم پر الله کا فضل اوراس کی رحمت نہ ہوتی اوریہ کہ الله نرمی کرنے والا مہربان ہے (تو کیا کچھ نہ ہوتا)'),
  ('ur.ahmedali', 24, 21, 'اے ایمان والو شیطان کے قدموں پر نہ چلو اورجو کوئی شیطان کے قدموں پرچلے گا سو وہ تو اسے بے حیائی اور بری باتیں ہی بتائے گا اوراگر تم پر الله کا فضل اوراس کی رحمت نہ ہوتی تو تم میں سے کوئی کبھی بھی پاک صاف نہ ہوتا اورلیکن الله جسے چاہتا ہے پاک کر دیتا ہے اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 24, 22, 'اور تم میں سے بزرگی اور کشائش والے اس بات پر قسم نہ کھائیں کہ رشتہ داروں اور مسکینوں اور الله کی راہ میں ہجرت کرنے والوں کو نہ دیا کریں گے اور انہیں معاف کرنا اور درگذر کرنا چاہیے کیا تم نہیں چاہتے کہ الله تمہیں معاف کر دے اور الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 24, 23, 'جو لوگ پاک دامنوں بے خبر ایمان والیوں پر تہمت لگاتے ہیں ان پر دنیا اور آخرت میں لعنت ہے اوران کے لیےبڑا عذاب ہے'),
  ('ur.ahmedali', 24, 24, 'جس دن ان پر ان کی زبانیں اور ان کے ہاتھ پاؤں گواہی دیں گے جو کچھ وہ کیا کرتے تھے'),
  ('ur.ahmedali', 24, 25, 'اس دن الله انہیں انصاف سے پوری جزا دے گا اور جان لیں گے بے شک الله ہی حق بیان کرنے والا ہے'),
  ('ur.ahmedali', 24, 26, 'ناپاک عورتیں ناپاک مردوں کے لیے ہیں اور ناپاک مرد ناپاک عورتو ں کے لیے ہیں او رپاک عورتیں پاک مردوں کے لیے ہیں اور پاک مرد پاک عورتوں کے لیے ہیں وہ لوگ اس سے پاک ہیں جو یہ کہتے ہیں ا ن کے لیے بخشش اورعزت کی روزی ہے'),
  ('ur.ahmedali', 24, 27, 'اے ایمان والو اپنے گھروں کے سوا اور کسی کے گھروں میں نہ جایا کرو جب تک اجازت نہ لے لو او رگھر والوں پر سلام نہ کر لو یہ تہارے لیے بہتر ہے تاکہ تم نصیحت حاصل کرو'),
  ('ur.ahmedali', 24, 28, 'پھر اگر وہاں کسی کو نہ پاؤ تو اندر نہ جاؤ جب تک کہ تمہیں اجازت نہ دی جائے اور اگر تمہیں کہا جائے کہ لوٹ جاؤ تو اپس چلے جاؤ یہ تمہارے حق میں بہتر ہے اور جو کچھ تم کرتے ہو الله جانتا ہے'),
  ('ur.ahmedali', 24, 29, 'تم پراس میں کوئی گناہ نہیں کہ ان گھروں میں جاؤ جہاں کوئی نہیں بستا ان میں تمہارا سامان ہے اور الله جانتا ہے جو تم ظاہر کرتے ہو اور جو تم چھپاتے ہو'),
  ('ur.ahmedali', 24, 30, 'ایمان والوں سے کہہ دو کہ وہ اپنی نگاہ نیچی رکھا کریں اور اپنی شرم گاہوں کو بھی محفوظ رکھیں یہ ان کے لیے بہت پاکیزہ ہے بے شک الله جانتا ہے جو وہ کرتے ہیں'),
  ('ur.ahmedali', 24, 31, 'اور ایمان والیوں سے کہہ دو کہ اپنی نگاہ نیچی رکھیں اور اپنی عصمت کی حفاظت کریں اور اپنی زینت کو ظاہر نہ کریں مگر جو جگہ اس میں سے کھلی رہتی ہے اوراپنے دوپٹے اپنے سینوں پر ڈالے رکھیں اوراپنی زینت ظاہر نہ کریں مگر اپنے خاوندوں پر یا اپنے باپ یا خاوند کے باپ یا اپنے بھائیوں یا بھتیجوں یا بھانجوں پر یا اپنی عورتوں پر یا اپنے غلاموں پر یا ان خدمت گاروں پر جنہیں عورت کی حاجت نہیں یا ان لڑکوں پر جو عورتوں کی پردہ کی چیزوں سے واقف نہیں اور اپنے پاؤں زمین پر زور سے نہ ماریں کہ ان کا مخفی زیور معلوم ہوجائے اوراے مسلمانو تم سب الله کے سامنے توبہ کرو تاکہ تم نجات پاؤ'),
  ('ur.ahmedali', 24, 32, 'اور جو تم میں مجرّد ہوں اور جو تمہارے غلام اور لونڈیاں نیک ہوں سب کے نکاح کرادو اگر وہ مفلس ہو ں گے تو الله اپنے فضل سے انہیں غنی کر دے گا اور الله کشائش والا سب کچھ جاننے والا ہے'),
  ('ur.ahmedali', 24, 33, 'اور چاہیے کہ پاک دامن رہیں وہ جو نکاح کی توفیق نہیں رکھتے یہاں تک کہ الله انہیں اپنے فضل سے غنی کر دے اور تمہارے غلاموں میں سے جو لوگ مال دے کر آزادی کی تحریر چاہیں تو انہیں لکھ دو بشرطیکہ ان میں بہتری کے آثار پاؤ اور انہیں الله کے مال میں سے دو جو اس نے تمہیں دیا ہے اور تمہاری لونڈیاں جو پاک دامن رہنا چاہتی ہیں انہیں دنیا کی زندگی کے فائدہ کی غرض سے زنا پر مجبور نہ کرو اور جو انہیں مجبور کرے گا تو الله ان کے مجبور ہونے کے بعد بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 24, 34, 'اور البتہ ہم نے تمہارے پاس روشن آیتیں بھیج دی ہیں اور جن میں تم سے پہلوں کے حالات ہیں او رجو پرہیز گاروں کے لیے نصیحت ہیں'),
  ('ur.ahmedali', 24, 35, 'الله آسمانوں اور زمین کا نور ہے اس کے نور کی مثال ایسی ہے جیسے طاق میں چراغ ہو چراغ شیشے کی قندیل میں ہے قندیل گویا کہ موتی کی طرح چمکتا ہوا ستارا ہے زیتون کے مبارک درخت سے روشن کیا جاتا ہے نہ مشرق کی طرف ہے اور نہ مغرب کی طرف اس کا تیل قریب ہے کہ روشن ہوجائے اگرچہ اسے آگ نے نہ چھوا ہو روشنی ہے الله جسے چاہتا ہے اپنی روشنی کی راہ دکھاتا ہے اور الله کے لیے مثالیں بیان فرماتا ہے اور الله ہر چیز کا جاننے والا ہے'),
  ('ur.ahmedali', 24, 36, 'ان گھروں میں جن کی تعظیم کرنے اور ان میں اس کا نام یاد کرنے کا الله نے حکم دیا ان میں صبح اور شام الله کی تسبیح پڑھتے ہیں'),
  ('ur.ahmedali', 24, 37, 'ایسے آدمی جنہیں سوداگری اور خرید و فروخت الله کے ذکر اور نماز کے پڑھنے اور زکوٰة کے دینے سے غافل نہیں کرتی اس دن سے ڈرتے ہیں جس میں دل اور آنکھیں الٹ جائیں گی'),
  ('ur.ahmedali', 24, 38, 'تاکہ الله انہیں ان کے عمل کا اچھا بدلہ دے اور انہیں اپنے فضل سے اور بھی دے اور الله جسے چاہتا ہے بے حساب روزی دیتا ہے'),
  ('ur.ahmedali', 24, 39, 'اور جو کافر ہیں ان کے اعمال ایسے ہیں جیسے جنگل میں چمکتی ہوئی ریت ہو جسے پیاسا پانی سمجھتا ہے یہاں تک کہ جب اس کے پاس آتا ہے اسے کچھ بھی نہیں پاتا اور الله ہی کو اپنے پاس پاتا ہے پھر الله نے اس کا حساب پورا کر دیا اور الله جلد حساب لینے والا ہے'),
  ('ur.ahmedali', 24, 40, 'یا جیسے گہرے دریا میں اندھیرے ہوں اس پر ایک لہر چڑھ آتی ہے اس پرایک او رلہر ہے اس کے اوپر بادل ہے اوپر تلے بہت سے اندھیرے ہیں جب اپنا ہاتھ نکالے تو اسے کچھ بھی دیکھ نہ سکے اور جسے الله ہی نے نور نہ دیا ہو اس کے لیے کہیں نور نہیں ہے'),
  ('ur.ahmedali', 24, 41, 'کیا تم نے نہیں دیکھا کہ آسمانوں اور زمین کے رہنے والے اور پرند جو پر پھیلائے اڑتے ہیں سب الله ہی کی تسبیح کرتے ہیں ہر ایک نے اپنی نماز اور تسبیح سمجھ رکھی ہے اور الله جانتا ہے جو کچھ وہ کرتے ہیں'),
  ('ur.ahmedali', 24, 42, 'اور آسمانوں اور زمین کی بادشاہی الله ہی کی ہے اور الله ہی کی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 24, 43, 'کیا تو نے نہیں دیکھا الله ہی بادل کو چلاتا ہے پھر اسے ملاتا ہے پھر اسے تہہ بر تہہ کرتا ہے پھر تو بارش کو دیکھتا ہے کہ اس کے بیچ میں سے نکلتی ہے اور آسمان سے جو ان میں اولوں کے پہاڑ ہیں ان میں سے اولے برساتا ہے پھر انہیں جس پر چاہتا ہے گراتا ہے اور جس سے چاہتا ہے روک لیتا ہے قریب ہے کہ اس کی بجلی کی چمک آنکھوں کو لے جائے'),
  ('ur.ahmedali', 24, 44, 'الله ہی رات اور دن کو بدلتا ہے بے شک اس میں آنکھوں والوں کے لیے عبرت ہے'),
  ('ur.ahmedali', 24, 45, 'اور الله نے ہر جاندار کو پانی سے بنایا ہے سو بعض ان میں سے اپنےپیٹ کے بل چلتے ہیں اور بعض ان میں سے دو پاؤں پر چلتے ہیں اور اور بعض ان میں سے چار پاؤں پر چلتے ہیں الله جو چاہتا ہے پیدا کرتا ہے بے شک الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 24, 46, 'البتہ ہم نے کھلی کھلی آیتیں نازل کر دی ہیں اور الله جسے چاہے سیدھے راستہ پر چلاتا ہے'),
  ('ur.ahmedali', 24, 47, 'اور کہتے ہیں ہم الله اور رسول پرایمان لائے اور ہم فرمانبردار ہو گئے پھر ایک گروہ ان میں سے اس کے بعد پھر جاتا ہے اور وہ لوگ مومن نہیں ہیں'),
  ('ur.ahmedali', 24, 48, 'اورجب انہیں الله اور اس کے رسول کی طرف بلایا جائے تاکہ ان میں فیصلہ کرے تب ہی ایک گروہ ان میں سے منہ موڑنے والے ہیں'),
  ('ur.ahmedali', 24, 49, 'اور اگر انہیں حق پہنچتا ہو تو اس کی طرف گردن جھکائے آتے ہیں'),
  ('ur.ahmedali', 24, 50, 'کیا ان کے دلوں میں بیماری ہے یا شک میں پڑے ہیں یا ڈرتے ہیں اس سے کہ ان پر الله اور اس کا رسول ظلم کرے گا بلکہ وہی ظالم ہیں'),
  ('ur.ahmedali', 24, 51, 'مومنوں کی بات تو یہی ہوتی ہے جب انہیں الله اور اس کے رسول کی طرف بلایا جاتا ہے تاکہ وہ ان کے درمیان فیصلہ کرے وہ کہتے ہیں کہ ہم نے سنا اور مان لیا اور وہی لوگ نجات پانے والے ہیں'),
  ('ur.ahmedali', 24, 52, 'اور جو شخص الله اور اس کے رسول کی اطاعت کرتا ہے اور الله سے ڈرتا ہے اور اس کی نافرمانی سے بچتا ہے بس وہی کامیاب ہونے والے ہیں'),
  ('ur.ahmedali', 24, 53, 'اور الله کی پکی قسمیں کھا کر کہتے ہیں کہ اگر آپ انہیں حکم دیں تو سب کچھ چھوڑ کر نکل جائیں کہہ دو قسمیں نہ کھاؤ دستور کے موافق فرمانبرداری چاہیئے بے شک الله جانتا ہے جو تم کرتے ہو'),
  ('ur.ahmedali', 24, 54, 'کہہ دو الله اور اس کے رسول کی فرمانبرداری کرو پھر اگر منہ پھیرو گے تو پیغمبر تو وہی ہے جس کا وہ ذمہ دار ہے اورتم پر وہ ہے جو تمہارے ذمہ لازم کیا گیا ہے اور اگر اس کی فرمانبرداری کرو گے تو ہدایت پاؤ گے اور رسول کے ذمہ صرف صاف طور پر پہنچا دینا ہے'),
  ('ur.ahmedali', 24, 55, 'الله نے ان لوگوں سے وعدہ کیا ہے جو تم میں سے ایمان لائے اور نیک عمل کیے کہ انہیں ضرور ملک کی حکومت عطا کرے گا جیسا کہ ان سے پہلوں کو عطا کی تھی اور ان کے لیے جس دین کو پسند کیا ہے اسے ضرور مستحکم کر دے گا اور البتہ ان کے خوف کو امن سے بدل دے گا بشرطیکہ میری عبادت کرتے رہیں اور میرے ساتھ کسی کو شریک نہ کریں اور جواس کے بعد ناشکری کرے وہی فاسق ہوں گے'),
  ('ur.ahmedali', 24, 56, 'اور نماز پڑھا کرو اور زکوٰة دیا کرو اور رسول کی فرمانبرداری کرو تاکہ تم پر رحم کیا جائے'),
  ('ur.ahmedali', 24, 57, 'کافروں کی نسبت یہ خیال نہ کر کہ ملک میں عاجز کر دیں گے اور ان کا ٹھکانہ دوزخ ہے اور بہت ہی برا ٹھکانہ ہے'),
  ('ur.ahmedali', 24, 58, 'اے ایمان والو تمہارے غلام اور تمہارےوہ لڑکے جو ابھی بالغ نہیں ہوئے تم سے ان تین وقتوں میں اجازت لے کر آیا کریں صبح کی نماز سے پہلے اور دوپہر کے وقت جب کہ تم اپنے کپڑے اتار دیتے ہو اور عشا کی نماز کے بعد یہ تین وقت تمہارے پردوں کے ہیں ان کے بعد تم پر اور نہ ان پر کوئی الزام ہے تم آپس میں ایک دوسرے کے پاس آنے جانے والے ہو اسی طرح الله تمہارے لیے آیتیں کھول کر بیان کرتا ہے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 24, 59, 'اورجب تمہارے لڑکے بلوغ کو پہنچ جائیں انہیں بھی اجازت لے کر آنا چاہیے جس طرح کہ ان سے پہلے لوگ اجازت لے کر آتے ہیں الله اس طرح تمہارے لیے کھول کر احکام بیان کرتا ہے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 24, 60, 'اوروہ بڑی بوڑھی عورتیں جو نکاح کی رغبت نہیں رکھتیں ان پر اس بات میں کوئی گناہ نہیں کہ اپنے کپڑے اتار رکھیں بشرطیکہ زینت کا اظہار نہ کریں اور اس سے بھی بچیں توان کے لیے بہتر ہے اور الله سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 24, 61, 'اندھے پر اور لنگڑ ے پر اور بیمار پر اور خود تم پر اس بات میں کوئی گناہ نہیں کہ تم اپنے گھروں سے کھانا کھاؤ یا اپنے باپ کے گھروں سے یا اپنی ماؤں کے گھروں سے یا اپنے بھائیوں کے گھروں سے یا اپنی بہنوں کے گھروں سے یا اپنے چچاؤں کے گھروں سے یا اپنی پھوپھیوں کے گھروں سے یا اپنے ماموؤں کے گھروں سے یا اپنی خالاؤں کےگھروں سے یا ان گھروں سے جنکی کنجیاں تمہارے اختیار میں ہیں یا اپنے دوستوں کے گھروں سے تم پر کوئی گناہ نہیں کہ مل کر کھاؤ یا الگ الگ کھاؤ پھر جب گھروں میں داخل ہونا چاہو تو اپنے لوگوں سے سلام کیا کرو جو الله کی طرف سے مبارک اور عمدہ دعا ہے اسی طرح الله تمہارے لیے احکام بیان فرماتا ہے تاکہ تم سمجھو'),
  ('ur.ahmedali', 24, 62, 'مومن تو وہی ہیں جو الله اور اس کے رسول پر ایمان لائے ہیں اور جب وہ اس کے ساتھ کسی جمع ہونے کے کام میں ہوتے ہیں تو چلے نہیں جاتے جب تک اس سے اجازت نہ لیں جو لوگ تجھ سے اجازت لیتے ہیں وہی ہیں جوالله اور اس کے رسول پرایمان لائے ہیں پھر جب تجھ سے اپنے کسی کام کے لیے اجازت مانگیں تو ان میں سے جسے تو چاہے عزت دے اور ان کے لیے الله سے بخشش کی دعا کر الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 24, 63, 'رسول کے بلانے کو آپس میں ایک دوسرے کے بلانے جیسا نہ سمجھو الله انہیں جانتا ہے جو تم میں سے چھپ کر کھسک جاتے ہیں سو جو لوگ الله کے حکم کی مخالفت کرتے ہیں انہیں اس سے ڈرنا چاہیئے کہ ان پر کوئی آفت آئے یا ان پر کوئی دردناک عذاب نازل ہوجائے'),
  ('ur.ahmedali', 24, 64, 'خبردار الله ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے اسے معلوم ہے جس حال پر تم ہو اور جس دن اس کی طرف پھیر لائے جائیں گے تو انہیں بتائے گا جو کچھ وہ کرتے تھے اور الله ہر چیز کو جاننے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 24, 1, 'Bu, indirip, hükümlerini kesinleştirdiğimiz suredir. Öğüt alasınız diye onda apaçık ayetler indirdik.'),
  ('tr.diyanet', 24, 2, 'Zina eden kadın ve erkeğin her birine yüzer değnek vurun. Allah\'a ve ahiret gününe inanıyorsanız, Allah\'ın dini konusunda o ikisine acımayın. Onların ceza görmesine, inananlardan bir topluluk da şahit olsun.'),
  ('tr.diyanet', 24, 3, 'Zina eden erkek, ancak zina eden veya putperest bir kadınla evlenebilir. Zina eden kadınla da, ancak zina eden veya putperest olan bir erkek evlenebilir. Bu, müminlere yasak edilmiştir.'),
  ('tr.diyanet', 24, 4, 'İffetli kadınlara zina isnat edip de, sonra dört şahit getiremeyenlere seksen değnek vurun; ebediyen onların şahidliğini kabul etmeyin. İşte onlar yoldan çıkmış kimselerdir.'),
  ('tr.diyanet', 24, 5, 'Ama bundan sonra, tevbe edip düzelenler bunun dışındadır. Şüphesiz Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 24, 6, 'Karılarına zina isnat edip de kendilerinden başka şahidleri olmayanların şahidliği, kendisinin doğru sözlülerden olduğuna Allah\'ı dört defa şahit tutmasıyla olur. Beşincisinde, eğer yalancılardan ise Allah\'ın lanetinin kendisine olmasını diler.'),
  ('tr.diyanet', 24, 7, 'Karılarına zina isnat edip de kendilerinden başka şahidleri olmayanların şahidliği, kendisinin doğru sözlülerden olduğuna Allah\'ı dört defa şahit tutmasıyla olur. Beşincisinde, eğer yalancılardan ise Allah\'ın lanetinin kendisine olmasını diler.'),
  ('tr.diyanet', 24, 8, 'Kocasının yalancılardan olduğuna Allah\'ı dört defa şahit tutması, cezayı kadından savar. Beşincisinde, kocası doğrulardan ise kendisinin Allah\'ın gazabına uğramasını diler.'),
  ('tr.diyanet', 24, 9, 'Kocasının yalancılardan olduğuna Allah\'ı dört defa şahit tutması, cezayı kadından savar. Beşincisinde, kocası doğrulardan ise kendisinin Allah\'ın gazabına uğramasını diler.'),
  ('tr.diyanet', 24, 10, 'Allah\'ın size nimet ve rahmeti bulunmasa ve Allah tevbeleri kabul eden ve Hakim olmasaydı suçlunun hemen cezasını verirdi.'),
  ('tr.diyanet', 24, 11, '(Peygamber\'in eşi hakkında) o yalanı uyduranlar içinizden bir güruhtur. Bunu kendiniz için kötü sanmayın, o sizin için hayırlı olmuştur. O kimselerden her birine kazandığı günah karşılığı ceza vardır; içlerinden elebaşılık yapana ise büyük azap vardır.'),
  ('tr.diyanet', 24, 12, 'Onu işittiğiniz zaman, erkek kadın müminlerin, kendiliklerinden hüsnü zanda bulunup da: "Bu apaçık bir iftiradır" demeleri gerekmez miydi?'),
  ('tr.diyanet', 24, 13, 'Dört şahit getirmeleri gerekmez miydi? İşte bunlar, şahit getirmedikçe Allah katında yalancı olanlardır.'),
  ('tr.diyanet', 24, 14, 'Allah\'ın dünya ve ahirette size lütuf ve merhameti olmasaydı, o kötü sözü yaymanızdan ötürü büyük bir azaba uğrardınız.'),
  ('tr.diyanet', 24, 15, 'Onu dilinize dolamıştınız. Bilmediğiniz şeyleri ağzınıza alıyordunuz. Onu önemsiz bir şey sanıyordunuz, oysa Allah katında önemi büyüktü.'),
  ('tr.diyanet', 24, 16, 'O\'nu işittiğinizde: "Bu konuda konuşmamız yakışık almaz; haşa, bu büyük bir iftiradır" demeniz gerekmez miydi?'),
  ('tr.diyanet', 24, 17, 'Eğer mümin kişilerdenseniz, Allah buna benzer bir şeye bir daha dönmemenizi tavsiye eder.'),
  ('tr.diyanet', 24, 18, 'Allah size ayetleri açıkça bildirir. Allah bilendir, Hakim\'dir.'),
  ('tr.diyanet', 24, 19, 'Müminler arasından hayasızlığın yayılmasını arzu edenlere, işte onlara, dünya ve ahirette can yakıcı azap vardır. Allah bilir, siz ise bilmezsiniz.'),
  ('tr.diyanet', 24, 20, 'Allah\'ın size lütuf ve merhameti bulunmasaydı, Allah şefkatli ve merhametli olmasaydı hemen cezanızı verirdi.'),
  ('tr.diyanet', 24, 21, 'Ey İnananlar! Şeytana ayak uydurmayın. Kim şeytanın ardına takılırsa, bilsin ki, o, hayasızlığı ve fenalığı emreder. Allah\'ın size lütuf ve merhameti bulunmasaydı, hiçbiriniz ebediyen temize çıkamazdı. Fakat Allah dilediğini temize çıkarır. Allah işitir ve bilir.'),
  ('tr.diyanet', 24, 22, 'İçinizde lütuf ve servet sahibi olanlar, yakınlarına, düşkünlere ve Allah yolunda hicret edenlere, vermemek için yemin etmesinler, affetsinler, geçsinler. Allah\'ın sizi bağışlamasından hoşlanmaz mısınız? Allah bağışlayandır, merhametli olandır.'),
  ('tr.diyanet', 24, 23, 'İffetli, habersiz, mümin kadınlara zina isnat edenler dünya ve ahirette lanetlenmişlerdir. Kendi dilleri, elleri ve ayakları, yapmış olduklarına şahidlik ettikleri gün onlar büyük azaba uğrayacaklardır.'),
  ('tr.diyanet', 24, 24, 'İffetli, habersiz, mümin kadınlara zina isnat edenler dünya ve ahirette lanetlenmişlerdir. Kendi dilleri, elleri ve ayakları, yapmış olduklarına şahidlik ettikleri gün onlar büyük azaba uğrayacaklardır.'),
  ('tr.diyanet', 24, 25, 'O gün, Allah onlara kesinleşmiş cezalarını verecektir. Allah\'ın apaçık hak olduğunu bileceklerdir.'),
  ('tr.diyanet', 24, 26, 'Kötü kadınlar kötü erkeklere, kötü erkekler kötü kadınlara yakışırlar. İyi kadınlar iyi erkeklere, iyi erkekler de iyi kadınlara yakışırlar. Bunlar, onların söylediklerinden uzaktırlar. İşte bunlara mağfiret ve cömertçe verilmiş rızık vardır.'),
  ('tr.diyanet', 24, 27, 'Ey inananlar! Evlerinizden başka evlere, izin almadan, seslenip sahiplerine selam vermeden girmeyiniz. Eğer düşünürseniz bu sizin için daha iyidir.'),
  ('tr.diyanet', 24, 28, 'Eğer evde kimseyi bulamazsanız, yine de size izin verilmedikçe içeriye girmeyiniz. Size "Dönün" denirse dönün. Bu, sizi daha çok temize çıkarır. Allah yaptıklarınızı bilir.'),
  ('tr.diyanet', 24, 29, 'İçinde malınız bulunan boş evlere girmenizde bir sorumluluk yoktur. Allah, açığa vurduğunuzu da, gizlediğinizi de bilir.'),
  ('tr.diyanet', 24, 30, 'Mümin erkeklere söyle: Gözlerini bakılması yasak olandan çevirsinler, mahrem yerlerini, korusunlar. Bu, onların arınmasını daha iyi sağlar. Allah yaptıklarından şüphesiz haberdardır.'),
  ('tr.diyanet', 24, 31, 'Mümin kadınlara da söyle: Gözlerini bakılması yasak olandan çevirsinler, iffetlerini korusunlar. Süslerini, kendiliğinden görünen kısmı müstesna, açmasınlar. Baş örtülerini yakalarının üzerine salsınlar. Süslerini kocaları veya babaları ve kayınpederleri veya oğulları veya kocalarının oğulları veya kardeşleri veya erkek kardeşlerinin oğulları veya kızkardeşlerinin oğulları veya müslüman kadınları veya cariyeleri veya erkekliği kalmamış hizmetçiler, ya da kadınların mahrem yerlerini henüz anlamayan çocuklardan başkasına göstermesinler. Gizledikleri süslerin bilinmesi için ayaklarını yere vurmasınlar. Ey inananlar! Saadete ermeniz için hepiniz tevbe ederek Allah\'ın hükmüne dönün.'),
  ('tr.diyanet', 24, 32, 'İçinizdeki bekarları, kölelerinizden ve cariyelerinizden iyi olanları evlendirin. Eğer yoksul iseler, Allah onları lütfü ile zenginleştirir. Allah lütfü bol olandır, bilendir.'),
  ('tr.diyanet', 24, 33, 'Evlenemeyenler, Allah kendilerini lütfü ile zenginleştirene kadar iffetli davransınlar. Kölelerinizden hür olmak için bedel vermek isteyenlerin, onlarda bir iyilik görürseniz, bedel vermelerini kabul edin. Onlara Allah\'ın size verdiği maldan verin. Dünya hayatının geçici menfaatini elde etmek için, iffetli olmak isteyen cariyelerinizi fuhşa zorlamayın. Kim onları buna zorlarsa bilsin ki Allah hiç şüphesiz onu değil zorlanan kadınları bağışlar ve merhamet eder.'),
  ('tr.diyanet', 24, 34, 'And olsun ki, size apaçık ayetler, sizden önce geçenlerden misal ve sakınanlara öğüt indirdik.'),
  ('tr.diyanet', 24, 35, 'Allah göklerin ve yerin Nur\'udur. O\'nun nuru, içinde ışık bulunan bir kandil yuvasına benzer. O ışık bir cam içindedir, cam ise, sanki inci gibi parlayan bir yıldızdır; bu ne yalnız doğuda ve ne de yalnız batıda bulunan bereketli zeytin ağacından yakılır. Ateş değmese bile, nerdeyse yağın kendisi aydınlatacak! Nur üstüne nurdur. Allah dilediğini nuruna kavuşturur. Allah insanlara misaller verir. O, herşeyi bilir.'),
  ('tr.diyanet', 24, 36, 'Allah\'ın yüksek tutulmasına ve içlerinde adının anılmasına izin verdiği evlerde, insanlar sabah akşam O\'nu tesbih ederler.'),
  ('tr.diyanet', 24, 37, 'Bunları ne ticaret ve ne de alışveriş Allah\'ı anmaktan, namaz kılmaktan, zekat vermekten alıkoyar. Bunlar, gönüllerin ve gözlerin döneceği günden korkarlar.'),
  ('tr.diyanet', 24, 38, 'Allah, onları işlediklerinin en güzeliyle mükafatlandırır ve lütfundan onlara fazlasıyla verir. Allah dilediğini hesapsız şekilde rızıklandırır.'),
  ('tr.diyanet', 24, 39, 'İnkar edenlerin işleri engin çöllerdeki serap gibidir. Susayan kimse onu su zanneder, fakat oraya geldiğinde hiçbir şey bulamaz. Orada Allah\'ı bulur ve O da hesabını görür. Allah hesabı çabuk görendir.'),
  ('tr.diyanet', 24, 40, 'Veya derin denizin karanlıklarına benzer. Onu üstüste dalgalar ve dalgaların üstünde de bulutlar örter; karanlıklar üstünde karanlıklar; insan elini uzattığı zaman, nerdeyse onu bile göremez. Allah\'ın nur vermediği kimsenin nuru olmaz.'),
  ('tr.diyanet', 24, 41, 'Göklerde ve yerde olan kimselerin, sıra sıra uçan kuşların Allah\'ı tesbih ettiğini görmez misin? Her biri kendi niyaz ve tesbihini bilir. Allah, onların yaptıklarını bilendir.'),
  ('tr.diyanet', 24, 42, 'Göklerin ve yerin hükümranlığı Allah\'ındır. Dönüş Allah\'adır.'),
  ('tr.diyanet', 24, 43, 'Bilmez misiniz ki, Allah bulutları sürer, sonra onları bir araya getirir; üstüste yığar, sen de onların arasından yağmur yağdığını görürsün. Gökten içinde dolu bulunan dağlar gibi bulutlar indirir, dilediğini ona uğratır, dilediğinden de uzak tutar. Bu bulutların şimşeğinin parıltısı nerdeyse gözleri alır!'),
  ('tr.diyanet', 24, 44, 'Allah geceyi gündüze, gündüzü geceye çevirir. Doğrusu, görebilenler için bunda ibretler vardır.'),
  ('tr.diyanet', 24, 45, 'Allah bütün canlıları sudan yaratmıştır. Kimi karnı üzerinde sürünür, kimi iki ayakla yürür, kimi dört ayakla yürür. Allah dilediğini yaratır, Allah şüphesiz herşeye Kadir\'dir.'),
  ('tr.diyanet', 24, 46, 'And olsun ki, açıklayıcı ayetler indirmişizdir. Allah dilediğini doğru yola eriştirir.'),
  ('tr.diyanet', 24, 47, 'Münafıklar: "Allah\'a ve Peygamber\'e inandık, itaat ettik" derler; sonra da bir takımı yüz çevirirler. İşte bunlar inanmış değillerdir.'),
  ('tr.diyanet', 24, 48, 'Aralarında hüküm vermek üzere Allah\'a ve Peygamberine çağırıldıkları zaman, bir takımı hemen yüz çevirirler. İşte bunlar inanmış değillerdir.'),
  ('tr.diyanet', 24, 49, 'Ama hak kendilerinden tarafa ise, itaatle koşa koşa gelirler.'),
  ('tr.diyanet', 24, 50, 'Kalplerinde hastalık mı var, yoksa şüphelenmişler midir, yahut Allah\'ın ve Peygamberinin onlara haksızlık yapacağından mı korkmaktadırlar? Hayır; onlar sadece zalimdirler.'),
  ('tr.diyanet', 24, 51, 'Aralarında hüküm verilmek üzere Allah\'a ve Peygambere çağırıldıkları vakit: "İşittik, itaat ettik" demek, ancak müminlerin sözüdür, işte saadete erenler onlardır.'),
  ('tr.diyanet', 24, 52, 'Allah\'a ve Peygambere itaat eden, Allah\'tan korkan ve O\'ndan sakınan kimseler, işte onlar kurtulanlardır.'),
  ('tr.diyanet', 24, 53, 'Eğer kendilerine emredersen, o iki yüzlüler, savaşa çıkacaklarına bütün güçleriyle yemin ederler. De ki: "Yemin etmeyin; itaatiniz malumdur. Allah yaptıklarınızdan şüphesiz haberdardır."'),
  ('tr.diyanet', 24, 54, 'De ki: "Allah\'a itaat edin; Peygambere itaat edin." Eğer yüz çevirirseniz, bilin ki o Peygamber, kendisine yükletilenden ve siz de kendinize yükletilenden sorumlusunuz. Eğer O\'na itaat ederseniz doğru yolu bulursunuz, Peygambere düşen sadece, apaçık tebliğdir.'),
  ('tr.diyanet', 24, 55, 'Allah, içinizden inanıp yararlı iş işleyenlere, onlardan öncekileri halef kıldığı gibi, onları da yeryüzüne halef kılacağına, onlar için beğendiği dini temelli yerleştireceğine, korkularını güvene çevireceğine dair söz vermiştir. Çünkü onlar Bana kulluk eder, hiçbir şeyi Bana ortak koşmazlar. Bundan sonra inkar eden kimseler, işte onlar artık yoldan çıkmış olanlardır.'),
  ('tr.diyanet', 24, 56, 'Namaz kılın, zekat verin, Peygambere itaat edin ki size merhamet edilsin.'),
  ('tr.diyanet', 24, 57, 'İnkar edenlerin, Bizi yeryüzünde aciz bırakacaklarını sanmayasın. Varacakları yer ateştir. Ne kötü dönüştür!'),
  ('tr.diyanet', 24, 58, 'Ey inananlar! Ellerinizin altında olan köle ve cariyeler ve sizden henüz erginliğe ermemiş olanlar, sabah namazından önce, öğle sıcağında soyunduğunuzda ve yatsı namazından sonra yanınıza gireceklerinde üç defa izin istesinler. Bunlar, sizin açık bulunabileceğiniz üç vakittir. Bu vakitlerin dışında birbirinizin yanına girip çıkmakta size de, onlara da bir sorumluluk yoktur. Allah size ayetlerini böylece açıklar. Allah bilendir, Hakim\'dir.'),
  ('tr.diyanet', 24, 59, 'Çocuklarınız erginlik çağına gelince, büyüklerinin izin istediği gibi, onlar da her defasında izin istesinler. Allah size ayetlerini böylece açıklar. Allah bilendir, Hakim\'dir.'),
  ('tr.diyanet', 24, 60, 'Evlenme ümidi kalmayan, ihtiyarlayıp oturmuş kadınlara, süslerini açığa vurmamak şartiyle, dış esvaplarını çıkarmaktan ötürü sorumluluk yoktur; ama sakınmaları kendileri için daha iyi olur. Allah işitir ve bilir.'),
  ('tr.diyanet', 24, 61, 'Kör için bir sorumluluk yoktur. Topal için bir sorumluluk yoktur. Hastaya da bir sorumluluk yoktur. Evlerinizde veya babalarınızın evlerinde veya annelerinizin evlerinde veya erkek kardeşlerinizin evlerinde veya kız kardeşlerinizin evlerinde veya amcalarınızın evlerinde veya halalarınızın evlerinde veya dayılarınızın evlerinde veya teyzelerinizin evlerinde veya kahyası olup anahtarları elinde olan evlerde, ya da dostlarınızın evlerinde izinsiz yemek yemenizde bir sorumluluk yoktur. Bir arada veya ayrı ayrı yemenizde de bir sorumluluk yoktur. Evlere girdiğiniz zaman, kendinize ehlinize Allah katından bereket, esenlik ve güzellik dileyerek selam verin. Allah size ayetleri, düşünesiniz diye böylece açıklar.'),
  ('tr.diyanet', 24, 62, 'Doğrusu Allah\'a ve Peygamberine inanan Müminler, Peygamberle beraber bir işe karar vermek için toplandıklarında, ondan izin almaksızın gitmezler. Senden izin isteyenler, işte onlar, Allah\'a ve Peygamberine inananlardır. Bazı işleri için senden izin isterlerse, içlerinden dilediğine izin ver, Allah\'tan, onların bağışlanmalarını dile. Allah şüphesiz bağışlar, merhamet eder.'),
  ('tr.diyanet', 24, 63, 'Peygamberin çağrısını, kendi aranızda birbirinizi çağırmanız gibi tutmayın. Allah, içinizden sıvışıp gidenleri şüphesiz bilir. O\'nun buyruğuna aykırı hareket edenler, başlarına bir belanın gelmesinden veya can yakıcı bir azaba uğramaktan sakınsınlar.'),
  ('tr.diyanet', 24, 64, 'Dikkat edin; göklerde ve yerde olanlar Allah\'ındır. O, içinde bulunduğunuz durumu da, kendisine döndürüleceğiniz günü de gerçekten bilir. Onlara işlediklerini haber verir. Allah herşeyi bilir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 24, 1, '(Ini adalah) satu surat yang Kami turunkan dan Kami wajibkan (menjalankan hukum-hukum yang ada di dalam)nya, dan Kami turunkan di dalamnya ayat ayat yang jelas, agar kamu selalu mengingatinya.'),
  ('id.indonesian', 24, 2, 'Perempuan yang berzina dan laki-laki yang berzina, maka deralah tiap-tiap seorang dari keduanya seratus dali dera, dan janganlah belas kasihan kepada keduanya mencegah kamu untuk (menjalankan) agama Allah, jika kamu beriman kepada Allah, dan hari akhirat, dan hendaklah (pelaksanaan) hukuman mereka disaksikan oleh sekumpulan orang-orang yang beriman.'),
  ('id.indonesian', 24, 3, 'Laki-laki yang berzina tidak mengawini melainkan perempuan yang berzina, atau perempuan yang musyrik; dan perempuan yang berzina tidak dikawini melainkan oleh laki-laki yang berzina atau laki-laki musyrik, dan yang demikian itu diharamkan atas oran-orang yang mukmin.'),
  ('id.indonesian', 24, 4, 'Dan orang-orang yang menuduh wanita-wanita yang baik-baik (berbuat zina) dan mereka tidak mendatangkan empat orang saksi, maka deralah mereka (yang menuduh itu) delapan puluh kali dera, dan janganlah kamu terima kesaksian mereka buat selama-lamanya. Dan mereka itulah orang-orang yang fasik.'),
  ('id.indonesian', 24, 5, 'kecuali orang-orang yang bertaubat sesudah itu dan memperbaiki (dirinya), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 24, 6, 'Dan orang-orang yang menuduh isterinya (berzina), padahal mereka tidak ada mempunyai saksi-saksi selain diri mereka sendiri, maka persaksian orang itu ialah empat kali bersumpah dengan nama Allah, sesungguhnya dia adalah termasuk orang-orang yang benar.'),
  ('id.indonesian', 24, 7, 'Dan (sumpah) yang kelima: bahwa laknat Allah atasnya, jika dia termasuk orang-orang yang berdusta.'),
  ('id.indonesian', 24, 8, 'Istrinya itu dihindarkan dari hukuman oleh sumpahnya empat kali atas nama Allah sesungguhnya suaminya itu benar-benar termasuk orang-orang yang dusta.'),
  ('id.indonesian', 24, 9, 'dan (sumpah) yang kelima: bahwa laknat Allah atasnya jika suaminya itu termasuk orang-orang yang benar.'),
  ('id.indonesian', 24, 10, 'Dan andaikata tidak ada kurnia Allah dan rahmat-Nya atas dirimu dan (andaikata) Allah bukan Penerima Taubat lagi Maha Bijaksana, (niscaya kamu akan mengalami kesulitan-kesulitan).'),
  ('id.indonesian', 24, 11, 'Sesungguhnya orang-orang yang membawa berita bohong itu adalah dari golongan kamu juga. Janganlah kamu kira bahwa berita bohong itu buruk bagi kamu bahkan ia adalah baik bagi kamu. Tiap-tiap seseorang dari mereka mendapat balasan dari dosa yang dikerjakannya. Dan siapa di antara mereka yang mengambil bahagian yang terbesar dalam penyiaran berita bohong itu baginya azab yang besar.'),
  ('id.indonesian', 24, 12, 'Mengapa di waktu kamu mendengar berita bohon itu orang-orang mukminin dan mukminat tidak bersangka baik terhadap diri mereka sendiri, dan (mengapa tidak) berkata: "Ini adalah suatu berita bohong yang nyata".'),
  ('id.indonesian', 24, 13, 'Mengapa mereka (yang menuduh itu) tidak mendatangkan empat orang saksi atas berita bohong itu? Olah karena mereka tidak mendatangkan saksi-saksi maka mereka itulah pada sisi Allah orang-orang yang dusta.'),
  ('id.indonesian', 24, 14, 'Sekiranya tidak ada kurnia Allah dan rahmat-Nya kepada kamu semua di dunia dan di akhirat, niscaya kamu ditimpa azab yang besar, karena pembicaraan kamu tentang berita bohong itu.'),
  ('id.indonesian', 24, 15, '(Ingatlah) di waktu kamu menerima berita bohong itu dari mulut ke mulut dan kamu katakan dengan mulutmu apa yang tidak kamu ketahui sedikit juga, dan kamu menganggapnya suatu yang ringan saja. Padahal dia pada sisi Allah adalah besar.'),
  ('id.indonesian', 24, 16, 'Dan mengapa kamu tidak berkata, diwaktu mendengar berita bohong itu: "Sekali-kali tidaklah pantas bagi kita memperkatakan ini, Maha Suci Engkau (Ya Tuhan kami), ini adalah dusta yang besar".'),
  ('id.indonesian', 24, 17, 'Allah memperingatkan kamu agar (jangan) kembali memperbuat yang seperti itu selama-lamanya, jika kamu orang-orang yang beriman.'),
  ('id.indonesian', 24, 18, 'dan Allah menerangkan ayat-ayat-Nya kepada kamu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 24, 19, 'Sesungguhnya orang-orang yang ingin agar (berita) perbuatan yang amat keji itu tersiar di kalangan orang-orang yang beriman, bagi mereka azab yang pedih di dunia dan di akhirat. Dan Allah mengetahui, sedang, kamu tidak mengetahui.'),
  ('id.indonesian', 24, 20, 'Dan sekiranya tidaklah karena kurnia Allah dan rahmat-Nya kepada kamu semua, dan Allah Maha Penyantun dan Maha Penyayang, (niscaya kamu akan ditimpa azab yang besar).'),
  ('id.indonesian', 24, 21, 'Hai orang-orang yang beriman, janganlah kamu mengikuti langkah-langkah syaitan. Barangsiapa yang mengikuti langkah-langkah syaitan, maka sesungguhnya syaitan itu menyuruh mengerjakan perbuatan yang keji dan yang mungkar. Sekiranya tidaklah karena kurnia Allah dan rahmat-Nya kepada kamu sekalian, niscaya tidak seorangpun dari kamu bersih (dari perbuatan-perbuatan keji dan mungkar itu) selama-lamanya, tetapi Allah membersihkan siapa yang dikehendaki-Nya. Dan Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 24, 22, 'Dan janganlah orang-orang yang mempunyai kelebihan dan kelapangan di antara kamu bersumpah bahwa mereka (tidak) akan memberi (bantuan) kepada kaum kerabat(nya), orang-orang yang miskin dan orang-orang yang berhijrah pada jalan Allah, dan hendaklah mereka memaafkan dan berlapang dada. Apakah kamu tidak ingin bahwa Allah mengampunimu? Dan Allah adalah Maha Pengampun lagi Maha Penyayang,'),
  ('id.indonesian', 24, 23, 'Sesungguhnya orang-orang yang menuduh wanita yang baik-baik, yang lengah lagi beriman (berbuat zina), mereka kena laknat di dunia dan akhirat, dan bagi mereka azab yang besar,'),
  ('id.indonesian', 24, 24, 'pada hari (ketika), lidah, tangan dan kaki mereka menjadi saksi atas mereka terhadap apa yang dahulu mereka kerjakan.'),
  ('id.indonesian', 24, 25, 'Di hari itu, Allah akan memberi mereka balasan yag setimpal menurut semestinya, dan tahulah mereka bahwa Allah-lah yang Benar, lagi Yang menjelaskan (segala sesutatu menurut hakikat yang sebenarnya).'),
  ('id.indonesian', 24, 26, 'Wanita-wanita yang keji adalah untuk laki-laki yang keji, dan laki-laki yang keji adalah buat wanita-wanita yang keji (pula), dan wanita-wanita yang baik adalah untuk laki-laki yang baik dan laki-laki yang baik adalah untuk wanita-wanita yang baik (pula). Mereka (yang dituduh) itu bersih dari apa yang dituduhkan oleh mereka (yang menuduh itu). Bagi mereka ampunan dan rezeki yang mulia (surga).'),
  ('id.indonesian', 24, 27, 'Hai orang-orang yang beriman, janganlah kamu memasuki rumah yang bukan rumahmu sebelum meminta izin dan memberi salam kepada penghuninya. Yang demikian itu lebih baik bagimu, agar kamu (selalu) ingat.'),
  ('id.indonesian', 24, 28, 'Jika kamu tidak menemui seorangpun didalamnya, maka janganlah kamu masuk sebelum kamu mendapat izin. Dan jika dikatakan kepadamu: "Kembali (saja)lah, maka hendaklah kamu kembali. Itu bersih bagimu dan Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 24, 29, 'Tidak ada dosa atasmu memasuki rumah yang tidak disediakan untuk didiami, yang di dalamnya ada keperluanmu, dan Allah mengetahui apa yang kamu nyatakan dan apa yang kamu sembunyikan.'),
  ('id.indonesian', 24, 30, 'Katakanlah kepada orang laki-laki yang beriman: "Hendaklah mereka menahan pandanganya, dan memelihara kemaluannya; yang demikian itu adalah lebih suci bagi mereka, sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat".'),
  ('id.indonesian', 24, 31, 'Katakanlah kepada wanita yang beriman: "Hendaklah mereka menahan pandangannya, dan kemaluannya, dan janganlah mereka menampakkan perhiasannya, kecuali yang (biasa) nampak dari padanya. Dan hendaklah mereka menutupkan kain kudung kedadanya, dan janganlah menampakkan perhiasannya kecuali kepada suami mereka, atau ayah mereka, atau ayah suami mereka, atau putera-putera mereka, atau putera-putera suami mereka, atau saudara-saudara laki-laki mereka, atau putera-putera saudara lelaki mereka, atau putera-putera saudara perempuan mereka, atau wanita-wanita islam, atau budak-budak yang mereka miliki, atau pelayan-pelayan laki-laki yang tidak mempunyai keinginan (terhadap wanita) atau anak-anak yang belum mengerti tentang aurat wanita. Dan janganlah mereka memukulkan kakinyua agar diketahui perhiasan yang mereka sembunyikan. Dan bertaubatlah kamu sekalian kepada Allah, hai orang-orang yang beriman supaya kamu beruntung.'),
  ('id.indonesian', 24, 32, 'Dan kawinkanlah orang-orang yang sedirian diantara kamu, dan orang-orang yang layak (berkawin) dari hamba-hamba sahayamu yang lelaki dan hamba-hamba sahayamu yang perempuan. Jika mereka miskin Allah akan memampukan mereka dengan kurnia-Nya. Dan Allah Maha luas (pemberian-Nya) lagi Maha Mengetahui.'),
  ('id.indonesian', 24, 33, 'Dan orang-orang yang tidak mampu kawin hendaklah menjaga kesucian (diri)nya, sehingga Allah memampukan mereka dengan karunia-Nya. Dan budak-budak yang kamu miliki yang memginginkan perjanjian, hendaklah kamu buat perjanjian dengan mereka, jika kamu mengetahui ada kebaikan pada mereka, dan berikanlah kepada mereka sebahagian dari harta Allah yang dikaruniakan-Nya kepadamu. Dan janganlah kamu paksa budak-budak wanitamu untuk melakukan pelacuran, sedang mereka sendiri mengingini kesucian, karena kamu hendak mencari keuntungan duniawi. Dan barangsiapa yang memaksa mereka, maka sesungguhnya Allah adalah Maha Pengampun lagi Maha Penyayang (kepada mereka) sesudah mereka dipaksa itu.'),
  ('id.indonesian', 24, 34, 'Dan sesungguhnya Kami telah menurunkan kepada kamu ayat-ayat yang memberi penerangan, dan contoh-contoh dari orang-orang yang terdahulu sebelum kamu dan pelajaran bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 24, 35, 'Allah (Pemberi) cahaya (kepada) langit dan bumi. Perumpamaan cahaya Allah, adalah seperti sebuah lubang yang tak tembus, yang di dalamnya ada pelita besar. Pelita itu di dalam kaca (dan) kaca itu seakan-akan bintang (yang bercahaya) seperti mutiara, yang dinyalakan dengan minyak dari pohon yang berkahnya, (yaitu) pohon zaitun yang tumbuh tidak di sebelah timur (sesuatu) dan tidak pula di sebelah barat(nya), yang minyaknya (saja) hampir-hampir menerangi, walaupun tidak disentuh api. Cahaya di atas cahaya (berlapis-lapis), Allah membimbing kepada cahaya-Nya siapa yang dia kehendaki, dan Allah memperbuat perumpamaan-perumpamaan bagi manusia, dan Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 24, 36, 'Bertasbih kepada Allah di masjid-masjid yang telah diperintahkan untuk dimuliakan dan disebut nama-Nya di dalamnya, pada waktu pagi dan waktu petang,'),
  ('id.indonesian', 24, 37, 'laki-laki yang tidak dilalaikan oleh perniagaan dan tidak (pula) oleh jual beli dari mengingati Allah, dan (dari) mendirikan sembahyang, dan (dari) membayarkan zakat. Mereka takut kepada suatu hari yang (di hari itu) hati dan penglihatan menjadi goncang.'),
  ('id.indonesian', 24, 38, '(Meraka mengerjakan yang demikian itu) supaya Allah memberikan balasan kepada mereka (dengan balasan) yang lebih baik dari apa yang telah mereka kerjakan, dan supaya Allah menambah karunia-Nya kepada mereka. Dan Allah memberi rezeki kepada siapa yang dikehendaki-Nya tanpa batas.'),
  ('id.indonesian', 24, 39, 'Dan orang-orang kafir amal-amal mereka adalah laksana fatamorgana di tanah yang datar, yang disangka air oleh orang-orang yang dahaga, tetapi bila didatanginya air itu dia tidak mendapatinya sesuatu apapun. Dan didapatinya (ketetapan) Allah disisinya, lalu Allah memberikan kepadanya perhitungan amal-amal dengan cukup dan Allah adalah sangat cepat perhitungan-Nya.'),
  ('id.indonesian', 24, 40, 'Atau seperti gelap gulita di lautan yang dalam, yang diliputi oleh ombak, yang di atasnya ombak (pula), di atasnya (lagi) awan; gelap gulita yang tindih-bertindih, apabila dia mengeluarkan tangannya, tiadalah dia dapat melihatnya, (dan) barangsiapa yang tiada diberi cahaya (petunjuk) oleh Allah tiadalah dia mempunyai cahaya sedikitpun.'),
  ('id.indonesian', 24, 41, 'Tidaklah kamu tahu bahwasanya Allah: kepada-Nya bertasbih apa yang di langit dan di bumi dan (juga) burung dengan mengembangkan sayapnya. Masing-masing telah mengetahui (cara) sembahyang dan tasbihnya, dan Allah Maha Mengetahui apa yang mereka kerjakan.'),
  ('id.indonesian', 24, 42, 'Dan kepunyaan Allah-lah kerajaan langit dan bumi dan kepada Allah-lah kembali (semua makhluk).'),
  ('id.indonesian', 24, 43, 'Tidaklah kamu melihat bahwa Allah mengarak awan, kemudian mengumpulkan antara (bagian-bagian)nya, kemudian menjadikannya bertindih-tindih, maka kelihatanlah olehmu hujan keluar dari celah-celahnya dan Allah (juga) menurunkan (butiran-butiran) es dari langit, (yaitu) dari (gumpalan-gumpalan awan seperti) gunung-gunung, maka ditimpakan-Nya (butiran-butiran) es itu kepada siapa yang dikehendaki-Nya dan dipalingkan-Nya dari siapa yang dikehendaki-Nya. Kilauan kilat awan itu hampir-hampir menghilangkan penglihatan.'),
  ('id.indonesian', 24, 44, 'Allah mempergantikan malam dan siang. Sesungguhnya pada yang demikian itu terdapat pelajaran yang besar bagi orang-orang yang mempunyai penglihatan.'),
  ('id.indonesian', 24, 45, 'Dan Allah telah menciptakan semua jenis hewan dari air, maka sebagian dari hewan itu ada yang berjalan di atas perutnya dan sebagian berjalan dengan dua kaki sedang sebagian (yang lain) berjalan dengan empat kaki. Allah menciptakan apa yang dikehendaki-Nya, sesungguhnya Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 24, 46, 'Sesungguhnya Kami telah menurunkan ayat-ayat yang menjelaskan. Dan Allah memimpin siapa yang dikehendaki-Nya kepada jalan yang lurus.'),
  ('id.indonesian', 24, 47, 'Dan mereka berkata: "Kami telah beriman kepada Allah dan rasul, dan kami mentaati (keduanya)". Kemudian sebagian dari mereka berpaling sesudah itu, sekali-kali mereka itu bukanlah orang-orang yang beriman.'),
  ('id.indonesian', 24, 48, 'Dan apabila mereka dipanggil kepada Allah dan rasul-Nya, agar rasul menghukum (mengadili) di antara mereka, tiba-tiba sebagian dari mereka menolak untuk datang.'),
  ('id.indonesian', 24, 49, 'Tetapi jika keputusan itu untuk (kemaslahatan) mereka, mereka datang kepada rasul dengan patuh.'),
  ('id.indonesian', 24, 50, 'Apakah (ketidak datangan mereka itu karena) dalam hati mereka ada penyakit, atau (karena) mereka ragu-ragu ataukah (karena) takut kalau-kalau Allah dan rasul-Nya berlaku zalim kepada mereka? Sebenarnya, mereka itulah orang-orang yang zalim.'),
  ('id.indonesian', 24, 51, 'Sesungguhnya jawaban oran-orang mukmin, bila mereka dipanggil kepada Allah dan rasul-Nya agar rasul menghukum (mengadili) di antara mereka ialah ucapan. "Kami mendengar, dan kami patuh". Dan mereka itulah orang-orang yang beruntung.'),
  ('id.indonesian', 24, 52, 'Dan barang siapa yang taat kepada Allah dan rasul-Nya dan takut kepada Allah dan bertakwa kepada-Nya, maka mereka adalah orang-orang yang mendapat kemenangan.'),
  ('id.indonesian', 24, 53, 'Dan mereka bersumpah dengan nama Allah sekuat-kuat sumpah, jika kamu suruh mereka berperang, pastilah mereka akan pergi. Katakanlah: "Janganlah kamu bersumpah, (karena ketaatan yang diminta ialah) ketaatan yang sudah dikenal. Sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 24, 54, 'Katakanlah: "Taat kepada Allah dan taatlah kepada rasul; dan jika kamu berpaling maka sesungguhnya kewajiban rasul itu adalah apa yang dibebankan kepadanya, dan kewajiban kamu sekalian adalah semata-mata apa yang dibebankan kepadamu. Dan jika kamu taat kepadanya, niscaya kamu mendapat petunjuk. Dan tidak lain kewajiban rasul itu melainkan menyampaikan (amanat Allah) dengan terang".'),
  ('id.indonesian', 24, 55, 'Dan Allah telah berjanji kepada orang-orang yang beriman di antara kamu dan mengerjakan amal-amal yang saleh bahwa Dia sungguh-sungguh akan menjadikan mereka berkuasa dimuka bumi, sebagaimana Dia telah menjadikan orang-orang sebelum mereka berkuasa, dan sungguh Dia akan meneguhkan bagi mereka agama yang telah diridhai-Nya untuk mereka, dan Dia benar-benar akan menukar (keadaan) mereka, sesudah mereka dalam ketakutan menjadi aman sentausa. Mereka tetap menyembahku-Ku dengan tiada mempersekutukan sesuatu apapun dengan Aku. Dan barangsiapa yang (tetap) kafir sesudah (janji) itu, maka mereka itulah orang-orang yang fasik.'),
  ('id.indonesian', 24, 56, 'Dan dirikanlah sembahyang, tunaikanlah zakat, dan taatlah kepada rasul, supaya kamu diberi rahmat.'),
  ('id.indonesian', 24, 57, 'Janganlah kamu kira bahwa orang-orang yang kafir itu dapat melemahkan (Allah dari mengazab mereka) di bumi ini, sedang tempat tinggal mereka (di akhirat) adalah neraka. Dan sungguh amat jeleklah tempat kembali itu.'),
  ('id.indonesian', 24, 58, 'Hai orang-orang yang beriman, hendaklah budak-budak (lelaki dan wanita) yang kamu miliki, dan orang-orang yang belum balig di antara kamu, meminta izin kepada kamu tiga kali (dalam satu hari) yaitu: sebelum sembahyang subuh, ketika kamu menanggalkan pakaian (luar)mu di tengah hari dan sesudah sembahyang Isya\'. (Itulah) tiga aurat bagi kamu. Tidak ada dosa atasmu dan tidak (pula) atas mereka selain dari (tiga waktu) itu. Mereka melayani kamu, sebahagian kamu (ada keperluan) kepada sebahagian (yang lain). Demikianlah Allah menjelaskan ayat-ayat bagi kamu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 24, 59, 'Dan apabila anak-anakmu telah sampai umur balig, maka hendaklah mereka meminta izin, seperti orang-orang yang sebelum mereka meminta izin. Demikianlah Allah menjelaskan ayat-ayat-Nya. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 24, 60, 'Dan perempuan-perempuan tua yang telah terhenti (dari haid dan mengandung) yang tiada ingin kawin (lagi), tiadalah atas mereka dosa menanggalkan pakaian mereka dengan tidak (bermaksud) menampakkan perhiasan, dan berlaku sopan adalah lebih baik bagi mereka. Dan Allah Maha Mendengar lagi Maha Bijaksana.'),
  ('id.indonesian', 24, 61, 'Tidak ada halangan bagi orang buta, tidak (pula) bagi orang pincang, tidak (pula) bagi orang sakit, dan tidak (pula) bagi dirimu sendiri, makan (bersama-sama mereka) dirumah kamu sendiri atau dirumah bapak-bapakmu, dirumah ibu-ibumu, dirumah saudara-saudaramu yang laki-laki, di rumah saudaramu yang perempuan, dirumah saudara bapakmu yang laki-laki, dirumah saudara bapakmu yang perempuan, dirumah saudara ibumu yang laki-laki, dirumah saudara ibumu yang perempuan, dirumah yang kamu miliki kuncinya atau dirumah kawan-kawanmu. Tidak ada halangan bagi kamu makan bersama-sama mereka atau sendirian. Maka apabila kamu memasuki (suatu rumah dari) rumah-rumah (ini) hendaklah kamu memberi salam kepada (penghuninya yang berarti memberi salam) kepada dirimu sendiri, salam yang ditetapkan dari sisi Allah, yang diberi berkat lagi baik. Demikianlah Allah menjelaskan ayat-ayatnya(Nya) bagimu, agar kamu memahaminya.'),
  ('id.indonesian', 24, 62, 'Sesungguhnya yang sebenar-benar orang mukmin ialah orang-orang yang beriman kepada Allah dan Rasul-Nya, dan apabila mereka berada bersama-sama Rasulullah dalam sesuatu urusan yang memerlukan pertemuan, mereka tidak meninggalkan (Rasulullah) sebelum meminta izin kepadanya. Sesungguhnya orang-orang yang meminta izin kepadamu (Muhammad) mereka itulah orang-orang yang beriman kepada Allah dan rasul-Nya, maka apabila mereka meminta izin kepadamu karena sesuatu keperluan, berilah izin kepada siapa yang kamu kehendaki di antara mereka, dan mohonkanlah ampunan untuk mereka kepada Allah. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 24, 63, 'Janganlah kamu jadikan panggilan Rasul diantara kamu seperti panggilan sebahagian kamu kepada sebahagian (yang lain). Sesungguhnya Allah telah mengetahui orang-orang yang berangsur-angsur pergi di antara kamu dengan berlindung (kepada kawannya), maka hendaklah orang-orang yang menyalahi perintah Rasul takut akan ditimpa cobaan atau ditimpa azab yang pedih.'),
  ('id.indonesian', 24, 64, 'Ketahuilah sesungguhnya kepunyaan Allahlah apa yang di langit dan di bumi. Sesungguhnya Dia mengetahui keadaan yang kamu berada di dalamnya (sekarang). Dan (mengetahui pula) hati (manusia) dikembalikan kepada-Nya, lalu diterangkan-Nya kepada mereka apa yang telah mereka kerjakan. Dan Allah Maha mengehui segala sesuatu.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 25, 1, 'Blessed is He who sent down the Criterion upon His Servant that he may be to the worlds a warner -'),
  ('en.sahih', 25, 2, 'He to whom belongs the dominion of the heavens and the earth and who has not taken a son and has not had a partner in dominion and has created each thing and determined it with [precise] determination.'),
  ('en.sahih', 25, 3, 'But they have taken besides Him gods which create nothing, while they are created, and possess not for themselves any harm or benefit and possess not [power to cause] death or life or resurrection.'),
  ('en.sahih', 25, 4, 'And those who disbelieve say, "This [Qur\'an] is not except a falsehood he invented, and another people assisted him in it." But they have committed an injustice and a lie.'),
  ('en.sahih', 25, 5, 'And they say, "Legends of the former peoples which he has written down, and they are dictated to him morning and afternoon."'),
  ('en.sahih', 25, 6, 'Say, [O Muhammad], "It has been revealed by He who knows [every] secret within the heavens and the earth. Indeed, He is ever Forgiving and Merciful."'),
  ('en.sahih', 25, 7, 'And they say, "What is this messenger that eats food and walks in the markets? Why was there not sent down to him an angel so he would be with him a warner?'),
  ('en.sahih', 25, 8, 'Or [why is not] a treasure presented to him [from heaven], or does he [not] have a garden from which he eats?" And the wrongdoers say, "You follow not but a man affected by magic."'),
  ('en.sahih', 25, 9, 'Look how they strike for you comparisons; but they have strayed, so they cannot [find] a way.'),
  ('en.sahih', 25, 10, 'Blessed is He who, if He willed, could have made for you [something] better than that - gardens beneath which rivers flow - and could make for you palaces.'),
  ('en.sahih', 25, 11, 'But they have denied the Hour, and We have prepared for those who deny the Hour a Blaze.'),
  ('en.sahih', 25, 12, 'When the Hellfire sees them from a distant place, they will hear its fury and roaring.'),
  ('en.sahih', 25, 13, 'And when they are thrown into a narrow place therein bound in chains, they will cry out thereupon for destruction.'),
  ('en.sahih', 25, 14, '[They will be told], "Do not cry this Day for one destruction but cry for much destruction."'),
  ('en.sahih', 25, 15, 'Say, "Is that better or the Garden of Eternity which is promised to the righteous? It will be for them a reward and destination.'),
  ('en.sahih', 25, 16, 'For them therein is whatever they wish, [while] abiding eternally. It is ever upon your Lord a promise [worthy to be] requested.'),
  ('en.sahih', 25, 17, 'And [mention] the Day He will gather them and that which they worship besides Allah and will say, "Did you mislead these, My servants, or did they [themselves] stray from the way?"'),
  ('en.sahih', 25, 18, 'They will say, "Exalted are You! It was not for us to take besides You any allies. But You provided comforts for them and their fathers until they forgot the message and became a people ruined."'),
  ('en.sahih', 25, 19, 'So they will deny you, [disbelievers], in what you say, and you cannot avert [punishment] or [find] help. And whoever commits injustice among you - We will make him taste a great punishment.'),
  ('en.sahih', 25, 20, 'And We did not send before you, [O Muhammad], any of the messengers except that they ate food and walked in the markets. And We have made some of you [people] as trial for others - will you have patience? And ever is your Lord, Seeing.'),
  ('en.sahih', 25, 21, 'And those who do not expect the meeting with Us say, "Why were not angels sent down to us, or [why] do we [not] see our Lord?" They have certainly become arrogant within themselves and [become] insolent with great insolence.'),
  ('en.sahih', 25, 22, 'The day they see the angels - no good tidings will there be that day for the criminals, and [the angels] will say, "Prevented and inaccessible."'),
  ('en.sahih', 25, 23, 'And We will regard what they have done of deeds and make them as dust dispersed.'),
  ('en.sahih', 25, 24, 'The companions of Paradise, that Day, are [in] a better settlement and better resting place.'),
  ('en.sahih', 25, 25, 'And [mention] the Day when the heaven will split open with [emerging] clouds, and the angels will be sent down in successive descent.'),
  ('en.sahih', 25, 26, 'True sovereignty, that Day, is for the Most Merciful. And it will be upon the disbelievers a difficult Day.'),
  ('en.sahih', 25, 27, 'And the Day the wrongdoer will bite on his hands [in regret] he will say, "Oh, I wish I had taken with the Messenger a way.'),
  ('en.sahih', 25, 28, 'Oh, woe to me! I wish I had not taken that one as a friend.'),
  ('en.sahih', 25, 29, 'He led me away from the remembrance after it had come to me. And ever is Satan, to man, a deserter."'),
  ('en.sahih', 25, 30, 'And the Messenger has said, "O my Lord, indeed my people have taken this Qur\'an as [a thing] abandoned."'),
  ('en.sahih', 25, 31, 'And thus have We made for every prophet an enemy from among the criminals. But sufficient is your Lord as a guide and a helper.'),
  ('en.sahih', 25, 32, 'And those who disbelieve say, "Why was the Qur\'an not revealed to him all at once?" Thus [it is] that We may strengthen thereby your heart. And We have spaced it distinctly.'),
  ('en.sahih', 25, 33, 'And they do not come to you with an argument except that We bring you the truth and the best explanation.'),
  ('en.sahih', 25, 34, 'The ones who are gathered on their faces to Hell - those are the worst in position and farthest astray in [their] way.'),
  ('en.sahih', 25, 35, 'And We had certainly given Moses the Scripture and appointed with him his brother Aaron as an assistant.'),
  ('en.sahih', 25, 36, 'And We said, "Go both of you to the people who have denied Our signs." Then We destroyed them with [complete] destruction.'),
  ('en.sahih', 25, 37, 'And the people of Noah - when they denied the messengers, We drowned them, and We made them for mankind a sign. And We have prepared for the wrongdoers a painful punishment.'),
  ('en.sahih', 25, 38, 'And [We destroyed] \'Aad and Thamud and the companions of the well and many generations between them.'),
  ('en.sahih', 25, 39, 'And for each We presented examples [as warnings], and each We destroyed with [total] destruction.'),
  ('en.sahih', 25, 40, 'And they have already come upon the town which was showered with a rain of evil. So have they not seen it? But they are not expecting resurrection.'),
  ('en.sahih', 25, 41, 'And when they see you, [O Muhammad], they take you not except in ridicule, [saying], "Is this the one whom Allah has sent as a messenger?'),
  ('en.sahih', 25, 42, 'He almost would have misled us from our gods had we not been steadfast in [worship of] them." But they are going to know, when they see the punishment, who is farthest astray in [his] way.'),
  ('en.sahih', 25, 43, 'Have you seen the one who takes as his god his own desire? Then would you be responsible for him?'),
  ('en.sahih', 25, 44, 'Or do you think that most of them hear or reason? They are not except like livestock. Rather, they are [even] more astray in [their] way.'),
  ('en.sahih', 25, 45, 'Have you not considered your Lord - how He extends the shadow, and if He willed, He could have made it stationary? Then We made the sun for it an indication.'),
  ('en.sahih', 25, 46, 'Then We hold it in hand for a brief grasp.'),
  ('en.sahih', 25, 47, 'And it is He who has made the night for you as clothing and sleep [a means for] rest and has made the day a resurrection.'),
  ('en.sahih', 25, 48, 'And it is He who sends the winds as good tidings before His mercy, and We send down from the sky pure water'),
  ('en.sahih', 25, 49, 'That We may bring to life thereby a dead land and give it as drink to those We created of numerous livestock and men.'),
  ('en.sahih', 25, 50, 'And We have certainly distributed it among them that they might be reminded, but most of the people refuse except disbelief.'),
  ('en.sahih', 25, 51, 'And if We had willed, We could have sent into every city a warner.'),
  ('en.sahih', 25, 52, 'So do not obey the disbelievers, and strive against them with the Qur\'an a great striving.'),
  ('en.sahih', 25, 53, 'And it is He who has released [simultaneously] the two seas, one fresh and sweet and one salty and bitter, and He placed between them a barrier and prohibiting partition.'),
  ('en.sahih', 25, 54, 'And it is He who has created from water a human being and made him [a relative by] lineage and marriage. And ever is your Lord competent [concerning creation].'),
  ('en.sahih', 25, 55, 'But they worship rather than Allah that which does not benefit them or harm them, and the disbeliever is ever, against his Lord, an assistant [to Satan].'),
  ('en.sahih', 25, 56, 'And We have not sent you, [O Muhammad], except as a bringer of good tidings and a warner.'),
  ('en.sahih', 25, 57, 'Say, "I do not ask of you for it any payment - only that whoever wills might take to his Lord a way."'),
  ('en.sahih', 25, 58, 'And rely upon the Ever-Living who does not die, and exalt [Allah] with His praise. And sufficient is He to be, with the sins of His servants, Acquainted -'),
  ('en.sahih', 25, 59, 'He who created the heavens and the earth and what is between them in six days and then established Himself above the Throne - the Most Merciful, so ask about Him one well informed.'),
  ('en.sahih', 25, 60, 'And when it is said to them, "Prostrate to the Most Merciful," they say, "And what is the Most Merciful? Should we prostrate to that which you order us?" And it increases them in aversion.'),
  ('en.sahih', 25, 61, 'Blessed is He who has placed in the sky great stars and placed therein a [burning] lamp and luminous moon.'),
  ('en.sahih', 25, 62, 'And it is He who has made the night and the day in succession for whoever desires to remember or desires gratitude.'),
  ('en.sahih', 25, 63, 'And the servants of the Most Merciful are those who walk upon the earth easily, and when the ignorant address them [harshly], they say [words of] peace,'),
  ('en.sahih', 25, 64, 'And those who spend [part of] the night to their Lord prostrating and standing [in prayer]'),
  ('en.sahih', 25, 65, 'And those who say, "Our Lord, avert from us the punishment of Hell. Indeed, its punishment is ever adhering;'),
  ('en.sahih', 25, 66, 'Indeed, it is evil as a settlement and residence."'),
  ('en.sahih', 25, 67, 'And [they are] those who, when they spend, do so not excessively or sparingly but are ever, between that, [justly] moderate'),
  ('en.sahih', 25, 68, 'And those who do not invoke with Allah another deity or kill the soul which Allah has forbidden [to be killed], except by right, and do not commit unlawful sexual intercourse. And whoever should do that will meet a penalty.'),
  ('en.sahih', 25, 69, 'Multiplied for him is the punishment on the Day of Resurrection, and he will abide therein humiliated -'),
  ('en.sahih', 25, 70, 'Except for those who repent, believe and do righteous work. For them Allah will replace their evil deeds with good. And ever is Allah Forgiving and Merciful.'),
  ('en.sahih', 25, 71, 'And he who repents and does righteousness does indeed turn to Allah with [accepted] repentance.'),
  ('en.sahih', 25, 72, 'And [they are] those who do not testify to falsehood, and when they pass near ill speech, they pass by with dignity.'),
  ('en.sahih', 25, 73, 'And those who, when reminded of the verses of their Lord, do not fall upon them deaf and blind.'),
  ('en.sahih', 25, 74, 'And those who say, "Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous."'),
  ('en.sahih', 25, 75, 'Those will be awarded the Chamber for what they patiently endured, and they will be received therein with greetings and [words of] peace.'),
  ('en.sahih', 25, 76, 'Abiding eternally therein. Good is the settlement and residence.'),
  ('en.sahih', 25, 77, 'Say, "What would my Lord care for you if not for your supplication?" For you [disbelievers] have denied, so your denial is going to be adherent.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 25, 1, 'পরম কল্যাণময় তিনি যিনি তাঁর বান্দার প্রতি ফয়সালার গ্রন্থ অবর্তীণ করেছেন, যাতে সে বিশ্বজগতের জন্যে সতর্ককারী হয়,।'),
  ('bn.bengali', 25, 2, 'তিনি হলেন যাঁর রয়েছে নভোমন্ডল ও ভূমন্ডলের রাজত্ব। তিনি কোন সন্তান গ্রহণ করেননি। রাজত্বে তাঁর কোন অংশীদার নেই। তিনি প্রত্যেক বস্তু সৃষ্টি করেছেন, অতঃপর তাকে শোধিত করেছেন পরিমিতভাবে।'),
  ('bn.bengali', 25, 3, 'তারা তাঁর পরিবর্তে কত উপাস্য গ্রহণ করেছে, যারা কিছুই সৃষ্টি করে না এবং তারা নিজেরাই সৃষ্ট এবং নিজেদের ভালও করতে পারে না, মন্দও করতে পারে না এবং জীবন, মরণ ও পুনরুজ্জীবনের ও তারা মালিক নয়।'),
  ('bn.bengali', 25, 4, 'কাফেররা বলে, এটা মিথ্যা বৈ নয়, যা তিনি উদ্ভাবন করেছেন এবং অন্য লোকেরা তাঁকে সাহায্য করেছে। অবশ্যই তারা অবিচার ও মিথ্যার আশ্রয় নিয়েছে।'),
  ('bn.bengali', 25, 5, 'তারা বলে, এগুলো তো পুরাকালের রূপকথা, যা তিনি লিখে রেখেছেন। এগুলো সকাল-সন্ধ্যায় তাঁর কাছে শেখানো হয়।'),
  ('bn.bengali', 25, 6, 'বলুন, একে তিনিই অবতীর্ণ করেছেন, যিনি নভোমন্ডল ও ভূমন্ডলের গোপন রহস্য অবগত আছেন। তিনি ক্ষমাশীল, মেহেরবান।'),
  ('bn.bengali', 25, 7, 'তারা বলে, এ কেমন রসূল যে, খাদ্য আহার করে এবং হাটে-বাজারে চলাফেরা করে? তাঁর কাছে কেন কোন ফেরেশতা নাযিল করা হল না যে, তাঁর সাথে সতর্ককারী হয়ে থাকত?'),
  ('bn.bengali', 25, 8, 'অথবা তিনি ধন-ভান্ডার প্রাপ্ত হলেন না কেন, অথবা তাঁর একটি বাগান হল না কেন, যা থেকে তিনি আহার করতেন? জালেমরা বলে, তোমরা তো একজন জাদুগ্রস্ত ব্যক্তিরই অনুসরণ করছ।'),
  ('bn.bengali', 25, 9, 'দেখুন, তারা আপনার কেমন দৃষ্টান্ত বর্ণনা করে! অতএব তারা পথভ্রষ্ট হয়েছে, এখন তারা পথ পেতে পারে না।'),
  ('bn.bengali', 25, 10, 'কল্যানময় তিনি, যিনি ইচ্ছা করলে আপনাকে তদপেক্ষা উত্তম বস্তু দিতে পারেন-বাগ-বাগিচা, যার তলদেশে নহর প্রবাহিত হয় এবং দিতে পারেন আপনাকে প্রাসাদসমূহ।'),
  ('bn.bengali', 25, 11, 'বরং তারা কেয়ামতকে অস্বীকার করে এবং যে কেয়ামতকে অস্বীকার করে, আমি তার জন্যে অগ্নি প্রস্তুত করেছি।'),
  ('bn.bengali', 25, 12, 'অগ্নি যখন দূর থেকে তাদেরকে দেখবে, তখন তারা শুনতে পাবে তার গর্জন ও হুঙ্কার।'),
  ('bn.bengali', 25, 13, 'যখন এক শিকলে কয়েকজন বাঁধা অবস্থায় জাহান্নামের কোন সংকীর্ণ স্থানে নিক্ষেপ করা হবে, তখন সেখানে তারা মৃত্যুকে ডাকবে।'),
  ('bn.bengali', 25, 14, 'বলা হবে, আজ তোমরা এক মৃত্যুকে ডেকো না অনেক মৃত্যুকে ডাক।'),
  ('bn.bengali', 25, 15, 'বলুন এটা উত্তম, না চিরকাল বসবাসের জান্নাত, যার সুসংবাদ দেয়া হয়েছে মুত্তাকীদেরকে? সেটা হবে তাদের প্রতিদান ও প্রত্যাবর্তন স্থান।'),
  ('bn.bengali', 25, 16, 'তারা চিরকাল বসবাসরত অবস্থায় সেখানে যা চাইবে, তাই পাবে। এই প্রার্থিত ওয়াদা পূরণ আপনার পালনকর্তার দায়িত্ব।'),
  ('bn.bengali', 25, 17, 'সেদিন আল্লাহ একত্রিত করবেন তাদেরকে এবং তারা আল্লাহর পরিবর্তে যাদের এবাদত করত তাদেরকে, সেদিন তিনি উপাস্যদেরকে বলবেন, তোমরাই কি আমার এই বান্দাদেরকে পথভ্রান্ত করেছিলে, না তারা নিজেরাই পথভ্রান্ত হয়েছিল?'),
  ('bn.bengali', 25, 18, 'তারা বলবে-আপনি পবিত্র, আমরা আপনার পরিবর্তে অন্যকে মুরুব্বীরূপে গ্রহণ করতে পারতাম না; কিন্তু আপনিই তো তাদেরকে এবং তাদের পিতৃপুরুষদেরকে ভোগসম্ভার দিয়েছিলেন, ফলে তারা আপনার স্মৃতি বিস্মৃত হয়েছিল এবং তারা ছিল ধ্বংসপ্রাপ্ত জাতি।'),
  ('bn.bengali', 25, 19, 'আল্লাহ মুশরিকদেরকে বলবেন, তোমাদের কথা তো তারা মিথ্যা সাব্যস্ত করল, এখন তোমরা শাস্তি প্রতিরোধ করতে পারবে না এবং সাহায্যও করতে পারবে না। তোমাদের মধ্যে যে গোনাহগার আমি তাকে গুরুতর শাস্তি আস্বাদন করাব।'),
  ('bn.bengali', 25, 20, 'আপনার পূর্বে যত রসূল প্রেরণ করেছি, তারা সবাই খাদ্য গ্রহণ করত এবং হাটে-বাজারে চলাফেরা করত। আমি তোমাদের এককে অপরের জন্যে পরীক্ষাস্বরূপ করেছি। দেখি, তোমরা সবর কর কিনা। আপনার পালনকর্তা সব কিছু দেখেন।'),
  ('bn.bengali', 25, 21, 'যারা আমার সাক্ষাৎ আশা করে না, তারা বলে, আমাদের কাছে ফেরেশতা অবতীর্ণ করা হল না কেন? অথবা আমরা আমাদের পালনকর্তাকে দেখি না কেন? তারা নিজেদের অন্তরে অহংকার পোষণ করে এবং গুরুতর অবাধ্যতায় মেতে উঠেছে।'),
  ('bn.bengali', 25, 22, 'যেদিন তারা ফেরেশতাদেরকে দেখবে, সেদিন অপরাধীদের জন্যে কোন সুসংবাদ থাকবে না এবং তারা বলবে, কোন বাধা যদি তা আটকে রাখত।'),
  ('bn.bengali', 25, 23, 'আমি তাদের কৃতকর্মের প্রতি মনোনিবেশ করব, অতঃপর সেগুলোকে বিক্ষিপ্ত ধুলিকণারূপে করে দেব।'),
  ('bn.bengali', 25, 24, 'সেদিন জান্নাতীদের বাসস্থান হবে উত্তম এবং বিশ্রামস্থল হবে মনোরম।'),
  ('bn.bengali', 25, 25, 'সেদিন আকাশ মেঘমালাসহ বিদীর্ণ হবে এবং সেদিন ফেরেশতাদের নামিয়ে দেয়া হবে,'),
  ('bn.bengali', 25, 26, 'সেদিন সত্যিকার রাজত্ব হবে দয়াময় আল্লাহর এবং কাফেরদের পক্ষে দিনটি হবে কঠিন।'),
  ('bn.bengali', 25, 27, 'জালেম সেদিন আপন হস্তদ্বয় দংশন করতে করতে বলবে, হায় আফসোস! আমি যদি রসূলের সাথে পথ অবলম্বন করতাম।'),
  ('bn.bengali', 25, 28, 'হায় আমার দূর্ভাগ্য, আমি যদি অমুককে বন্ধুরূপে গ্রহণ না করতাম।'),
  ('bn.bengali', 25, 29, 'আমার কাছে উপদেশ আসার পর সে আমাকে তা থেকে বিভ্রান্ত করেছিল। শয়তান মানুষকে বিপদকালে ধোঁকা দেয়।'),
  ('bn.bengali', 25, 30, 'রসূল বললেনঃ হে আমার পালনকর্তা, আমার সম্প্রদায় এই কোরআনকে প্রলাপ সাব্যস্ত করেছে।'),
  ('bn.bengali', 25, 31, 'এমনিভাবে প্রত্যেক নবীর জন্যে আমি অপরাধীদের মধ্য থেকে শত্রু করেছি। আপনার জন্যে আপনার পালনকর্তা পথপ্রদর্শক ও সাহায্যকারীরূপে যথেষ্ট।'),
  ('bn.bengali', 25, 32, 'সত্য প্রত্যাখানকারীরা বলে, তাঁর প্রতি সমগ্র কোরআন একদফায় অবতীর্ণ হল না কেন? আমি এমনিভাবে অবতীর্ণ করেছি এবং ক্রমে ক্রমে আবৃত্তি করেছি আপনার অন্তকরণকে মজবুত করার জন্যে।'),
  ('bn.bengali', 25, 33, 'তারা আপনার কাছে কোন সমস্যা উপস্থাপিত করলেই আমি আপনাকে তার সঠিক জওয়াব ও সুন্দর ব্যাখ্যা দান করি।'),
  ('bn.bengali', 25, 34, 'যাদেরকে মুখ থুবড়ে পড়ে থাকা অবস্থায় জাহান্নামের দিকে একত্রিত করা হবে, তাদেরই স্থান হবে নিকৃষ্ট এবং তারাই পথভ্রষ্ট।'),
  ('bn.bengali', 25, 35, 'আমি তো মূসাকে কিতাব দিয়েছি এবং তাঁর সাথে তাঁর ভ্রাতা হারুনকে সাহায্যকারী করেছি।'),
  ('bn.bengali', 25, 36, 'অতঃপর আমি বলেছি, তোমরা সেই সম্প্রদায়ের কাছে যাও, যারা আমার আয়াতসমূহকে মিথ্যা অভিহিত করেছে। অতঃপর আমি তাদেরকে সমূলে ধ্বংস করে দিয়েছি।'),
  ('bn.bengali', 25, 37, 'নূহের সম্প্রদায় যখন রসূলগণের প্রতি মিথ্যারোপ করল, তখন আমি তাদেরকে নিমজ্জত করলাম এবং তাদেরকে মানবমন্ডলীর জন্যে নিদর্শন করে দিলাম। জালেমদের জন্যে আমি যন্ত্রণাদায়ক শাস্তি প্রস্তুত করে রেখেছি।'),
  ('bn.bengali', 25, 38, 'আমি ধ্বংস করেছি আদ, সামুদ, কপবাসী এবং তাদের মধ্যবর্তী অনেক সম্প্রদায়কে।'),
  ('bn.bengali', 25, 39, 'আমি প্রত্যেকের জন্যেই দৃষ্টান্ত বর্ণনা করেছি এবং প্রত্যেককেই সম্পুর্ণরূপে ধ্বংস করেছি।'),
  ('bn.bengali', 25, 40, 'তারা তো সেই জনপদের উপর দিয়েই যাতায়াত করে, যার ওপর বর্ষিত হয়েছে মন্দ বৃষ্টি। তবে কি তারা তা প্রত্যক্ষ করে না? বরং তারা পুনরুজ্জীবনের আশঙ্কা করে না।'),
  ('bn.bengali', 25, 41, 'তারা যখন আপনাকে দেখে, তখন আপনাকে কেবল বিদ্রুপের পাত্ররূপে গ্রহণ করে, বলে, এ-ই কি সে যাকে আল্লাহ ‘রসূল’ করে প্রেরণ করেছেন?'),
  ('bn.bengali', 25, 42, 'সে তো আমাদেরকে আমাদের উপাস্যগণের কাছ থেকে সরিয়েই দিত, যদি আমরা তাদেরকে আঁকড়ে ধরে না থাকতাম। তারা যখন শাস্তি প্রত্যক্ষ করবে, তখন জানতে পারবে কে অধিক পথভ্রষ্ট।'),
  ('bn.bengali', 25, 43, 'আপনি কি তাকে দেখেন না, যে তারা প্রবৃত্তিকে উপাস্যরূপে গ্রহণ করে? তবুও কি আপনি তার যিম্মাদার হবেন?'),
  ('bn.bengali', 25, 44, 'আপনি কি মনে করেন যে, তাদের অধিকাংশ শোনে অথবা বোঝে ? তারা তো চতুস্পদ জন্তুর মত; বরং আরও পথভ্রান্ত'),
  ('bn.bengali', 25, 45, 'তুমি কি তোমার পালনকর্তাকে দেখ না, তিনি কিভাবে ছায়াকে বিলম্বিত করেন? তিনি ইচ্ছা করলে একে স্থির রাখতে পারতেন। এরপর আমি সূর্যকে করেছি এর নির্দেশক।'),
  ('bn.bengali', 25, 46, 'অতঃপর আমি একে নিজের দিকে ধীরে ধীরে গুটিয়ে আনি।'),
  ('bn.bengali', 25, 47, 'তিনিই তো তোমাদের জন্যে রাত্রিকে করেছেন আবরণ, নিদ্রাকে বিশ্রাম এবং দিনকে করেছেন বাইরে গমনের জন্যে।'),
  ('bn.bengali', 25, 48, 'তিনিই স্বীয় রহমতের প্রাক্কালে বাতাসকে সুসংবাদবাহীরূপে প্রেরণ করেন। এবং আমি আকাশ থেকে পবিত্রতা অর্জনের জন্যে পানি বর্ষণ করি।'),
  ('bn.bengali', 25, 49, 'তদ্দ্বারা মৃত ভূভাগকে সঞ্জীবিত করার জন্যে এবং আমার সৃষ্ট জীবজন্তু ও অনেক মানুষের তৃষ্ণা নিবারণের জন্যে।'),
  ('bn.bengali', 25, 50, 'এবং আমি তা তাদের মধ্যে বিভিন্নভাবে বিতরণ করি, যাতে তারা স্মরণ করে। কিন্তু অধিকাংশ লোক অকৃতজ্ঞতা ছাড়া কিছুই করে না।'),
  ('bn.bengali', 25, 51, 'আমি ইচ্ছা করলে প্রত্যেক জনপদে একজন ভয় প্রদর্শনকারী প্রেরণ করতে পারতাম।'),
  ('bn.bengali', 25, 52, 'অতএব আপনি কাফেরদের আনুগত্য করবেন না এবং তাদের সাথে এর সাহায্যে কঠোর সংগ্রাম করুন।'),
  ('bn.bengali', 25, 53, 'তিনিই সমান্তরালে দুই সমুদ্র প্রবাহিত করেছেন, এটি মিষ্ট, তৃষ্ণা নিবারক ও এটি লোনা, বিস্বাদ; উভয়ের মাঝখানে রেখেছেন একটি অন্তরায়, একটি দুর্ভেদ্য আড়াল।'),
  ('bn.bengali', 25, 54, 'তিনিই পানি থেকে সৃষ্টি করেছেন মানবকে, অতঃপর তাকে রক্তগত, বংশ ও বৈবাহিক সম্পর্কশীল করেছেন। তোমার পালনকর্তা সবকিছু করতে সক্ষম।'),
  ('bn.bengali', 25, 55, 'তারা এবাদত করে আল্লাহর পরিবর্তে এমন কিছুর, যা তাদের উপকার করতে পারে না এবং ক্ষতিও করতে পারে না। কাফের তো তার পালনকর্তার প্রতি পৃষ্ঠপ্রদর্শনকারী।'),
  ('bn.bengali', 25, 56, 'আমি আপনাকে সুসংবাদ ও সতর্ককারীরূপেই প্রেরণ করেছি।'),
  ('bn.bengali', 25, 57, 'বলুন, আমি তোমাদের কাছে এর কোন বিনিময় চাই না, কিন্তু যে ইচ্ছা করে, সে তার পালনকর্তার পথ অবলম্বন করুক।'),
  ('bn.bengali', 25, 58, 'আপনি সেই চিরঞ্জীবের উপর ভরসা করুন, যার মৃত্যু নেই এবং তাঁর প্রশংসাসহ পবিত্রতা ঘোষণা করুন। তিনি বান্দার গোনাহ সম্পর্কে যথেষ্ট খবরদার।'),
  ('bn.bengali', 25, 59, 'তিনি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের অন্তর্বর্তী সবকিছু ছয়দিনে সৃস্টি করেছেন, অতঃপর আরশে সমাসীন হয়েছেন। তিনি পরম দয়াময়। তাঁর সম্পর্কে যিনি অবগত, তাকে জিজ্ঞেস কর।'),
  ('bn.bengali', 25, 60, 'তাদেরকে যখন বলা হয়, দয়াময়কে সেজদা কর, তখন তারা বলে, দয়াময় আবার কে? তুমি কাউকে সেজদা করার আদেশ করলেই কি আমরা সেজদা করব? এতে তাদের পলায়নপরতাই বৃদ্ধি পায়।'),
  ('bn.bengali', 25, 61, 'কল্যাণময় তিনি, যিনি নভোমন্ডলে রাশিচক্র সৃষ্টি করেছেন এবং তাতে রেখেছেন সূর্য ও দীপ্তিময় চন্দ্র।'),
  ('bn.bengali', 25, 62, 'যারা অনুসন্ধানপ্রিয় অথবা যারা কৃতজ্ঞতাপ্রিয় তাদের জন্যে তিনি রাত্রি ও দিবস সৃষ্টি করেছেন পরিবর্তনশীলরূপে।'),
  ('bn.bengali', 25, 63, 'রহমান-এর বান্দা তারাই, যারা পৃথিবীতে নম্রভাবে চলাফেরা করে এবং তাদের সাথে যখন মুর্খরা কথা বলতে থাকে, তখন তারা বলে, সালাম।'),
  ('bn.bengali', 25, 64, 'এবং যারা রাত্রি যাপন করে পালনকর্তার উদ্দেশ্যে সেজদাবনত হয়ে ও দন্ডায়মান হয়ে;'),
  ('bn.bengali', 25, 65, 'এবং যারা বলে, হে আমার পালনকর্তা, আমাদের কাছথেকে জাহান্নামের শাস্তি হটিয়ে দাও। নিশ্চয় এর শাস্তি নিশ্চিত বিনাশ;'),
  ('bn.bengali', 25, 66, 'বসবাস ও অবস্থানস্থল হিসেবে তা কত নিকৃষ্ট জায়গা।'),
  ('bn.bengali', 25, 67, 'এবং তারা যখন ব্যয় করে, তখন অযথা ব্যয় করে না কৃপণতাও করে না এবং তাদের পন্থা হয় এতদুভয়ের মধ্যবর্তী।'),
  ('bn.bengali', 25, 68, 'এবং যারা আল্লাহর সাথে অন্য উপাস্যের এবাদত করে না, আল্লাহ যার হত্যা অবৈধ করেছেন, সঙ্গত কারণ ব্যতীত তাকে হত্যা করে না এবং ব্যভিচার করে না। যারা একাজ করে, তারা শাস্তির সম্মুখীন হবে।'),
  ('bn.bengali', 25, 69, 'কেয়ামতের দিন তাদের শাস্তি দ্বিগুন হবে এবং তথায় লাঞ্ছিত অবস্থায় চিরকাল বসবাস করবে।'),
  ('bn.bengali', 25, 70, 'কিন্তু যারা তওবা করে বিশ্বাস স্থাপন করে এবং সৎকর্ম করে, আল্লাহ তাদের গোনাহকে পুন্য দ্বারা পরিবর্তত করে এবং দেবেন। আল্লাহ ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 25, 71, 'যে তওবা করে ও সৎকর্ম করে, সে ফিরে আসার স্থান আল্লাহর দিকে ফিরে আসে।'),
  ('bn.bengali', 25, 72, 'এবং যারা মিথ্যা কাজে যোগদান করে না এবং যখন অসার ক্রিয়াকর্মের সম্মুখীন হয়, তখন মান রক্ষার্থে ভদ্রভাবে চলে যায়।'),
  ('bn.bengali', 25, 73, 'এবং যাদেরকে তাদের পালনকর্তার আয়াতসমূহ বোঝানো হলে তাতে অন্ধ ও বধির সদৃশ আচরণ করে না।'),
  ('bn.bengali', 25, 74, 'এবং যারা বলে, হে আমাদের পালনকর্তা, আমাদের স্ত্রীদের পক্ষ থেকে এবং আমাদের সন্তানের পক্ষ থেকে আমাদের জন্যে চোখের শীতলতা দান কর এবং আমাদেরকে মুত্তাকীদের জন্যে আদর্শস্বরূপ কর।'),
  ('bn.bengali', 25, 75, 'তাদেরকে তাদের সবরের প্রতিদানে জান্নাতে কক্ষ দেয়া হবে এবং তাদেরকে তথায় দোয়া ও সালাম সহকারে অভ্যর্থনা করা হবে।'),
  ('bn.bengali', 25, 76, 'তথায় তারা চিরকাল বসবাস করবে। অবস্থানস্থল ও বাসস্থান হিসেবে তা কত উত্তম।'),
  ('bn.bengali', 25, 77, 'বলুন, আমার পালনকর্তা পরওয়া করেন না যদি তোমরা তাঁকে না ডাক। তোমরা মিথ্যা বলেছ। অতএব সত্বর নেমে আসবে অনিবার্য শাস্তি।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 25, 1, 'Blessed is He Who hath revealed unto His slave the Criterion (of right and wrong), that he may be a warner to the peoples.'),
  ('en.pickthall', 25, 2, 'He unto Whom belongeth the Sovereignty of the heavens and the earth, He hath chosen no son nor hath He any partner in the Sovereignty. He hath created everything and hath meted out for it a measure.'),
  ('en.pickthall', 25, 3, 'Yet they choose beside Him other gods who create naught but are themselves created, and possess not hurt nor profit for themselves, and possess not death nor life, nor power to raise the dead.'),
  ('en.pickthall', 25, 4, 'Those who disbelieve say: This is naught but a lie that he hath invented, and other folk have helped him with it, so that they have produced a slander and a lie.'),
  ('en.pickthall', 25, 5, 'And they say: Fables of the men of old which he hath had written down so that they are dictated to him morn and evening.'),
  ('en.pickthall', 25, 6, 'Say (unto them, O Muhammad): He who knoweth the secret of the heavens and the earth hath revealed it. Lo! He ever is Forgiving, Merciful.'),
  ('en.pickthall', 25, 7, 'And they say: What aileth this messenger (of Allah) that he eateth food and walketh in the markets? Why is not an angel sent down unto him, to be a warner with him.'),
  ('en.pickthall', 25, 8, 'Or (why is not) treasure thrown down unto him, or why hath he not a paradise from whence to eat? And the evil-doers say: Ye are but following a man bewitched.'),
  ('en.pickthall', 25, 9, 'See how they coin similitudes for thee, so that they are all astray and cannot find a road!'),
  ('en.pickthall', 25, 10, 'Blessed is He Who, if He will, will assign thee better than (all) that - Gardens underneath which rivers flow - and will assign thee mansions.'),
  ('en.pickthall', 25, 11, 'Nay, but they deny (the coming of) the Hour, and for those who deny (the coming of) the Hour We have prepared a flame.'),
  ('en.pickthall', 25, 12, 'When it seeth them from afar, they hear the crackling and the roar thereof.'),
  ('en.pickthall', 25, 13, 'And when they are flung into a narrow place thereof, chained together, they pray for destruction there.'),
  ('en.pickthall', 25, 14, 'Pray not that day for one destruction, but pray for many destructions!'),
  ('en.pickthall', 25, 15, 'Say: Is that (doom) better or the Garden of Immortality which is promised unto those who ward off (evil)? It will be their reward and journey\'s end.'),
  ('en.pickthall', 25, 16, 'Therein abiding, they have all that they desire. It is for thy Lord a promise that must be fulfilled.'),
  ('en.pickthall', 25, 17, 'And on the day when He will assemble them and that which they worship instead of Allah and will say: Was it ye who misled these my slaves or did they (themselves) wander from the way?'),
  ('en.pickthall', 25, 18, 'They will say: Be Thou Glorified! it was not for us to choose any protecting friends beside thee; but Thou didst give them and their fathers ease till they forgot the warning and became lost folk.'),
  ('en.pickthall', 25, 19, 'Thus they will give you the lie regarding what ye say, then ye can neither avert (the doom) nor obtain help. And whoso among you doeth wrong, We shall make him taste great torment.'),
  ('en.pickthall', 25, 20, 'We never sent before thee any messengers but lo! they verily ate food and walked in the markets. And We have appointed some of you a test for others: Will ye be steadfast? And thy Lord is ever Seer.'),
  ('en.pickthall', 25, 21, 'And those who look not for a meeting with Us say: Why are angels not sent down unto us and (Why) do we not see our Lord! Assuredly they think too highly of themselves and are scornful with great pride.'),
  ('en.pickthall', 25, 22, 'On the day when they behold the angels, on that day there will be no good tidings for the guilty; and they will cry: A forbidding ban!'),
  ('en.pickthall', 25, 23, 'And We shall turn unto the work they did and make it scattered motes.'),
  ('en.pickthall', 25, 24, 'Those who have earned the Garden on that day will be better in their home and happier in their place of noonday rest;'),
  ('en.pickthall', 25, 25, 'A day when the heaven with the clouds will be rent asunder and the angels will be sent down, a grand descent.'),
  ('en.pickthall', 25, 26, 'The Sovereignty on that day will be the True (Sovereignty) belonging to the Beneficent One, and it will be a hard day for disbelievers.'),
  ('en.pickthall', 25, 27, 'On the day when the wrong-doer gnaweth his hands, he will say: Ah, would that I had chosen a way together with the messenger (of Allah)!'),
  ('en.pickthall', 25, 28, 'Alas for me! Ah, would that I had never taken such an one for friend!'),
  ('en.pickthall', 25, 29, 'He verily led me astray from the Reminder after it had reached me. Satan was ever man\'s deserter in the hour of need.'),
  ('en.pickthall', 25, 30, 'And the messenger saith: O my Lord! Lo! mine own folk make this Qur\'an of no account.'),
  ('en.pickthall', 25, 31, 'Even so have We appointed unto every prophet an opponent from among the guilty; but Allah sufficeth for a Guide and Helper.'),
  ('en.pickthall', 25, 32, 'And those who disbelieve say: Why is the Qur\'an not revealed unto him all at once? (It is revealed) thus that We may strengthen thy heart therewith; and We have arranged it in right order.'),
  ('en.pickthall', 25, 33, 'And they bring thee no similitude but We bring thee the Truth (as against it), and better (than their similitude) as argument.'),
  ('en.pickthall', 25, 34, 'Those who will be gathered on their faces unto hell: such are worse in plight and further from the right road.'),
  ('en.pickthall', 25, 35, 'We verily gave Moses the Scripture and placed with him his brother Aaron as henchman.'),
  ('en.pickthall', 25, 36, 'Then We said: Go together unto the folk who have denied Our revelations. Then We destroyed them, a complete destruction.'),
  ('en.pickthall', 25, 37, 'And Noah\'s folk, when they denied the messengers, We drowned them and made of them a portent for mankind. We have prepared a painful doom for evil-doers.'),
  ('en.pickthall', 25, 38, 'And (the tribes of) A\'ad and Thamud, and the dwellers in Ar-Rass, and many generations in between.'),
  ('en.pickthall', 25, 39, 'Each (of them) We warned by examples, and each (of them) We brought to utter ruin.'),
  ('en.pickthall', 25, 40, 'And indeed they have passed by the township whereon was rained the fatal rain. Can it be that they have not seen it? Nay, but they hope for no resurrection.'),
  ('en.pickthall', 25, 41, 'And when they see thee (O Muhammad) they treat thee only as a jest (saying): Is this he whom Allah sendeth as a messenger?'),
  ('en.pickthall', 25, 42, 'He would have led us far away from our gods if we had not been staunch to them. They will know, when they behold the doom, who is more astray as to the road.'),
  ('en.pickthall', 25, 43, 'Hast thou seen him who chooseth for his god his own lust? Wouldst thou then be guardian over him?'),
  ('en.pickthall', 25, 44, 'Or deemest thou that most of them hear or understand? They are but as the cattle - nay, but they are farther astray?'),
  ('en.pickthall', 25, 45, 'Hast thou not seen how thy Lord hath spread the shade - And if He willed He could have made it still - then We have made the sun its pilot;'),
  ('en.pickthall', 25, 46, 'Then We withdraw it unto Us, a gradual withdrawal?'),
  ('en.pickthall', 25, 47, 'And He it is Who maketh night a covering for you, and sleep repose, and maketh day a resurrection.'),
  ('en.pickthall', 25, 48, 'And He it is Who sendeth the winds, glad tidings heralding His mercy, and We send down purifying water from the sky,'),
  ('en.pickthall', 25, 49, 'That We may give life thereby to a dead land, and We give many beasts and men that We have created to drink thereof.'),
  ('en.pickthall', 25, 50, 'And verily We have repeated it among them that they may remember, but most of mankind begrudge aught save ingratitude.'),
  ('en.pickthall', 25, 51, 'If We willed, We could raise up a warner in every village.'),
  ('en.pickthall', 25, 52, 'So obey not the disbelievers, but strive against them herewith with a great endeavour.'),
  ('en.pickthall', 25, 53, 'And He it is Who hath given independence to the two seas (though they meet); one palatable, sweet, and the other saltish, bitter; and hath set a bar and a forbidding ban between them.'),
  ('en.pickthall', 25, 54, 'And He it is Who hath created man from water, and hath appointed for him kindred by blood and kindred by marriage; for thy Lord is ever Powerful.'),
  ('en.pickthall', 25, 55, 'Yet they worship instead of Allah that which can neither benefit them nor hurt them. The disbeliever was ever a partisan against his Lord.'),
  ('en.pickthall', 25, 56, 'And We have sent thee (O Muhammad) only as a bearer of good tidings and a warner.'),
  ('en.pickthall', 25, 57, 'Say: I ask of you no reward for this, save that whoso will may choose a way unto his Lord.'),
  ('en.pickthall', 25, 58, 'And trust thou in the Living One Who dieth not, and hymn His praise. He sufficeth as the Knower of His bondmen\'s sins,'),
  ('en.pickthall', 25, 59, 'Who created the heavens and the earth and all that is between them in six Days, then He mounted the Throne. The Beneficent! Ask anyone informed concerning Him!'),
  ('en.pickthall', 25, 60, 'And when it is said unto them: Prostrate to the Beneficent! they say: And what is the Beneficent? Are we to prostrate to whatever thou (Muhammad) biddest us? And it increaseth aversion in them.'),
  ('en.pickthall', 25, 61, 'Blessed be He Who hath placed in the heaven mansions of the stars, and hath placed therein a great lamp and a moon giving light!'),
  ('en.pickthall', 25, 62, 'And He it is Who hath appointed night and day in succession, for him who desireth to remember, or desireth thankfulness.'),
  ('en.pickthall', 25, 63, 'The (faithful) slaves of the Beneficent are they who walk upon the earth modestly, and when the foolish ones address them answer: Peace;'),
  ('en.pickthall', 25, 64, 'And who spend the night before their Lord, prostrate and standing,'),
  ('en.pickthall', 25, 65, 'And who say: Our Lord! Avert from us the doom of hell; lo! the doom thereof is anguish;'),
  ('en.pickthall', 25, 66, 'Lo! it is wretched as abode and station;'),
  ('en.pickthall', 25, 67, 'And those who, when they spend, are neither prodigal nor grudging; and there is ever a firm station between the two;'),
  ('en.pickthall', 25, 68, 'And those who cry not unto any other god along with Allah, nor take the life which Allah hath forbidden save in (course of) justice, nor commit adultery - and whoso doeth this shall pay the penalty;'),
  ('en.pickthall', 25, 69, 'The doom will be doubled for him on the Day of Resurrection, and he will abide therein disdained for ever;'),
  ('en.pickthall', 25, 70, 'Save him who repenteth and believeth and doth righteous work; as for such, Allah will change their evil deeds to good deeds. Allah is ever Forgiving, Merciful.'),
  ('en.pickthall', 25, 71, 'And whosoever repenteth and doeth good, he verily repenteth toward Allah with true repentance -'),
  ('en.pickthall', 25, 72, 'And those who will not witness vanity, but when they pass near senseless play, pass by with dignity.'),
  ('en.pickthall', 25, 73, 'And those who, when they are reminded of the revelations of their Lord, fall not deaf and blind thereat.'),
  ('en.pickthall', 25, 74, 'And who say: Our Lord! Vouchsafe us comfort of our wives and of our offspring, and make us patterns for (all) those who ward off (evil).'),
  ('en.pickthall', 25, 75, 'They will be awarded the high place forasmuch as they were steadfast, and they will meet therein with welcome and the ward of peace,'),
  ('en.pickthall', 25, 76, 'Abiding there for ever. Happy is it as abode and station!'),
  ('en.pickthall', 25, 77, 'Say (O Muhammad, unto the disbelievers): My Lord would not concern Himself with you but for your prayer. But now ye have denied (the Truth), therefor there will be judgment.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 25, 1, 'Blessed is He who sent down the criterion to His servant, that it may be an admonition to all creatures;-'),
  ('en.yusufali', 25, 2, 'He to whom belongs the dominion of the heavens and the earth: no son has He begotten, nor has He a partner in His dominion: it is He who created all things, and ordered them in due proportions.'),
  ('en.yusufali', 25, 3, 'Yet have they taken, besides him, gods that can create nothing but are themselves created; that have no control of hurt or good to themselves; nor can they control death nor life nor resurrection.'),
  ('en.yusufali', 25, 4, 'But the misbelievers say: "Naught is this but a lie which he has forged, and others have helped him at it." In truth it is they who have put forward an iniquity and a falsehood.'),
  ('en.yusufali', 25, 5, 'And they say: "Tales of the ancients, which he has caused to be written: and they are dictated before him morning and evening."'),
  ('en.yusufali', 25, 6, 'Say: "The (Qur\'an) was sent down by Him who knows the mystery (that is) in the heavens and the earth: verily He is Oft-Forgiving, Most Merciful."'),
  ('en.yusufali', 25, 7, 'And they say: "What sort of a messenger is this, who eats food, and walks through the streets? Why has not an angel been sent down to him to give admonition with him?'),
  ('en.yusufali', 25, 8, '"Or (Why) has not a treasure been bestowed on him, or why has he (not) a garden for enjoyment?" The wicked say: "Ye follow none other than a man bewitched."'),
  ('en.yusufali', 25, 9, 'See what kinds of comparisons they make for thee! But they have gone astray, and never a way will they be able to find!'),
  ('en.yusufali', 25, 10, 'Blessed is He who, if that were His will, could give thee better (things) than those,- Gardens beneath which rivers flow; and He could give thee palaces (secure to dwell in).'),
  ('en.yusufali', 25, 11, 'Nay they deny the hour (of the judgment to come): but We have prepared a blazing fire for such as deny the hour:'),
  ('en.yusufali', 25, 12, 'When it sees them from a place far off, they will hear its fury and its ranging sigh.'),
  ('en.yusufali', 25, 13, 'And when they are cast, bound together into a constricted place therein, they will plead for destruction there and then!'),
  ('en.yusufali', 25, 14, '"This day plead not for a single destruction: plead for destruction oft-repeated!"'),
  ('en.yusufali', 25, 15, 'Say: "Is that best, or the eternal garden, promised to the righteous? for them, that is a reward as well as a goal (of attainment).'),
  ('en.yusufali', 25, 16, '"For them there will be therein all that they wish for: they will dwell (there) for aye: A promise to be prayed for from thy Lord."'),
  ('en.yusufali', 25, 17, 'The day He will gather them together as well as those whom they worship besides Allah, He will ask: "Was it ye who let these My servants astray, or did they stray from the Path themselves?"'),
  ('en.yusufali', 25, 18, 'They will say: "Glory to Thee! not meet was it for us that we should take for protectors others besides Thee: But Thou didst bestow, on them and their fathers, good things (in life), until they forgot the Message: for they were a people (worthless and) lost."'),
  ('en.yusufali', 25, 19, '(Allah will say): "Now have they proved you liars in what ye say: so ye cannot avert (your penalty) nor (get) help." And whoever among you does wrong, him shall We cause to taste of a grievous Penalty.'),
  ('en.yusufali', 25, 20, 'And the messengers whom We sent before thee were all (men) who ate food and walked through the streets: We have made some of you as a trial for others: will ye have patience? for Allah is One Who sees (all things).'),
  ('en.yusufali', 25, 21, 'Such as fear not the meeting with Us (for Judgment) say: "Why are not the angels sent down to us, or (why) do we not see our Lord?" Indeed they have an arrogant conceit of themselves, and mighty is the insolence of their impiety!'),
  ('en.yusufali', 25, 22, 'The Day they see the angels,- no joy will there be to the sinners that Day: The (angels) will say: "There is a barrier forbidden (to you) altogether!"'),
  ('en.yusufali', 25, 23, 'And We shall turn to whatever deeds they did (in this life), and We shall make such deeds as floating dust scattered about.'),
  ('en.yusufali', 25, 24, 'The Companions of the Garden will be well, that Day, in their abode, and have the fairest of places for repose.'),
  ('en.yusufali', 25, 25, 'The Day the heaven shall be rent asunder with clouds, and angels shall be sent down, descending (in ranks),-'),
  ('en.yusufali', 25, 26, 'That Day, the dominion as of right and truth, shall be (wholly) for (Allah) Most Merciful: it will be a Day of dire difficulty for the misbelievers.'),
  ('en.yusufali', 25, 27, 'The Day that the wrong-doer will bite at his hands, he will say, "Oh! would that I had taken a (straight) path with the Messenger!'),
  ('en.yusufali', 25, 28, '"Ah! woe is me! Would that I had never taken such a one for a friend!'),
  ('en.yusufali', 25, 29, '"He did lead me astray from the Message (of Allah) after it had come to me! Ah! the Evil One is but a traitor to man!"'),
  ('en.yusufali', 25, 30, 'Then the Messenger will say: "O my Lord! Truly my people took this Qur\'an for just foolish nonsense."'),
  ('en.yusufali', 25, 31, 'Thus have We made for every prophet an enemy among the sinners: but enough is thy Lord to guide and to help.'),
  ('en.yusufali', 25, 32, 'Those who reject Faith say: "Why is not the Qur\'an revealed to him all at once? Thus (is it revealed), that We may strengthen thy heart thereby, and We have rehearsed it to thee in slow, well-arranged stages, gradually.'),
  ('en.yusufali', 25, 33, 'And no question do they bring to thee but We reveal to thee the truth and the best explanation (thereof).'),
  ('en.yusufali', 25, 34, 'Those who will be gathered to Hell (prone) on their faces,- they will be in an evil plight, and, as to Path, most astray.'),
  ('en.yusufali', 25, 35, '(Before this,) We sent Moses The Book, and appointed his brother Aaron with him as minister;'),
  ('en.yusufali', 25, 36, 'And We command: "Go ye both, to the people who have rejected our Signs:" And those (people) We destroyed with utter destruction.'),
  ('en.yusufali', 25, 37, 'And the people of Noah,- when they rejected the messengers, We drowned them, and We made them as a Sign for mankind; and We have prepared for (all) wrong-doers a grievous Penalty;-'),
  ('en.yusufali', 25, 38, 'As also \'Ad and Thamud, and the Companions of the Rass, and many a generation between them.'),
  ('en.yusufali', 25, 39, 'To each one We set forth Parables and examples; and each one We broke to utter annihilation (for their sins).'),
  ('en.yusufali', 25, 40, 'And the (Unbelievers) must indeed have passed by the town on which was rained a shower of evil: did they not then see it (with their own eyes)? But they fear not the Resurrection.'),
  ('en.yusufali', 25, 41, 'When they see thee, they treat thee no otherwise than in mockery: "Is this the one whom Allah has sent as a messenger?"'),
  ('en.yusufali', 25, 42, '"He indeed would well-nigh have misled us from our gods, had it not been that we were constant to them!" - Soon will they know, when they see the Penalty, who it is that is most misled in Path!'),
  ('en.yusufali', 25, 43, 'Seest thou such a one as taketh for his god his own passion (or impulse)? Couldst thou be a disposer of affairs for him?'),
  ('en.yusufali', 25, 44, 'Or thinkest thou that most of them listen or understand? They are only like cattle;- nay, they are worse astray in Path.'),
  ('en.yusufali', 25, 45, 'Hast thou not turned thy vision to thy Lord?- How He doth prolong the shadow! If He willed, He could make it stationary! then do We make the sun its guide;'),
  ('en.yusufali', 25, 46, 'Then We draw it in towards Ourselves,- a contraction by easy stages.'),
  ('en.yusufali', 25, 47, 'And He it is Who makes the Night as a Robe for you, and Sleep as Repose, and makes the Day (as it were) a Resurrection.'),
  ('en.yusufali', 25, 48, 'And He it is Who sends the winds as heralds of glad tidings, going before His mercy, and We send down pure water from the sky,-'),
  ('en.yusufali', 25, 49, 'That with it We may give life to a dead land, and slake the thirst of things We have created,- cattle and men in great numbers.'),
  ('en.yusufali', 25, 50, 'And We have distributed the (water) amongst them, in order that they may celebrate (our) praises, but most men are averse (to aught) but (rank) ingratitude.'),
  ('en.yusufali', 25, 51, 'Had it been Our Will, We could have sent a warner to every centre of population.'),
  ('en.yusufali', 25, 52, 'Therefore listen not to the Unbelievers, but strive against them with the utmost strenuousness, with the (Qur\'an).'),
  ('en.yusufali', 25, 53, 'It is He Who has let free the two bodies of flowing water: One palatable and sweet, and the other salt and bitter; yet has He made a barrier between them, a partition that is forbidden to be passed.'),
  ('en.yusufali', 25, 54, 'It is He Who has created man from water: then has He established relationships of lineage and marriage: for thy Lord has power (over all things).'),
  ('en.yusufali', 25, 55, 'Yet do they worship, besides Allah, things that can neither profit them nor harm them: and the Misbeliever is a helper (of Evil), against his own Lord!'),
  ('en.yusufali', 25, 56, 'But thee We only sent to give glad tidings and admonition.'),
  ('en.yusufali', 25, 57, 'Say: "No reward do I ask of you for it but this: that each one who will may take a (straight) Path to his Lord."'),
  ('en.yusufali', 25, 58, 'And put thy trust in Him Who lives and dies not; and celebrate his praise; and enough is He to be acquainted with the faults of His servants;-'),
  ('en.yusufali', 25, 59, 'He Who created the heavens and the earth and all that is between, in six days, and is firmly established on the Throne (of Authority): Allah Most Gracious: ask thou, then, about Him of any acquainted (with such things).'),
  ('en.yusufali', 25, 60, 'When it is said to them, "Prostrate to (Allah) Most Gracious!", they say, "And what is (Allah) Most Gracious? Shall we prostrate to that which thou commandest us?" And it increases their flight (from the Truth).'),
  ('en.yusufali', 25, 61, 'Blessed is He Who made constellations in the skies, and placed therein a Lamp and a Moon giving light;'),
  ('en.yusufali', 25, 62, 'And it is He Who made the Night and the Day to follow each other: for such as have the will to celebrate His praises or to show their gratitude.'),
  ('en.yusufali', 25, 63, 'And the servants of (Allah) Most Gracious are those who walk on the earth in humility, and when the ignorant address them, they say, "Peace!";'),
  ('en.yusufali', 25, 64, 'Those who spend the night in adoration of their Lord prostrate and standing;'),
  ('en.yusufali', 25, 65, 'Those who say, "Our Lord! avert from us the Wrath of Hell, for its Wrath is indeed an affliction grievous,-'),
  ('en.yusufali', 25, 66, '"Evil indeed is it as an abode, and as a place to rest in";'),
  ('en.yusufali', 25, 67, 'Those who, when they spend, are not extravagant and not niggardly, but hold a just (balance) between those (extremes);'),
  ('en.yusufali', 25, 68, 'Those who invoke not, with Allah, any other god, nor slay such life as Allah has made sacred except for just cause, nor commit fornication; - and any that does this (not only) meets punishment.'),
  ('en.yusufali', 25, 69, '(But) the Penalty on the Day of Judgment will be doubled to him, and he will dwell therein in ignominy,-'),
  ('en.yusufali', 25, 70, 'Unless he repents, believes, and works righteous deeds, for Allah will change the evil of such persons into good, and Allah is Oft-Forgiving, Most Merciful,'),
  ('en.yusufali', 25, 71, 'And whoever repents and does good has truly turned to Allah with an (acceptable) conversion;-'),
  ('en.yusufali', 25, 72, 'Those who witness no falsehood, and, if they pass by futility, they pass by it with honourable (avoidance);'),
  ('en.yusufali', 25, 73, 'Those who, when they are admonished with the Signs of their Lord, droop not down at them as if they were deaf or blind;'),
  ('en.yusufali', 25, 74, 'And those who pray, "Our Lord! Grant unto us wives and offspring who will be the comfort of our eyes, and give us (the grace) to lead the righteous."'),
  ('en.yusufali', 25, 75, 'Those are the ones who will be rewarded with the highest place in heaven, because of their patient constancy: therein shall they be met with salutations and peace,'),
  ('en.yusufali', 25, 76, 'Dwelling therein;- how beautiful an abode and place of rest!'),
  ('en.yusufali', 25, 77, 'Say (to the Rejecters): "My Lord is not uneasy because of you if ye call not on Him: But ye have indeed rejected (Him), and soon will come the inevitable (punishment)!"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 25, 1, 'Tabaarakal lazee nazzalal Furqaana \'alaa \'abdihee li yakoona lil\'aalameena nazeera'),
  ('en.transliteration', 25, 2, 'Allazee lahoo mulkus samaawaati wal ardi wa lam yattakhiz waladanw wa lam yakul lahoo shareekun filmulki wa khalaqa kulla shai\'in faqaddarahoo taqdeeraa'),
  ('en.transliteration', 25, 3, 'Wattakhazoo min dooniheee aahihatal laa yakhluqoona shai\'anw wa hum yukhlaqoona wa laa yamlikoona li anfusihim darranw wa laa naf\'anw wa laa yamlikoona mawtanw wa laa hayaatanw wa laa nushooraa'),
  ('en.transliteration', 25, 4, 'Wa qaalal lazeena kafarooo in haazaaa illaaa ifkunif taraahu wa a\'aanahoo \'alaihi qawmun aakharoona faqad jaaa\'oo zulmanw wa zooraa'),
  ('en.transliteration', 25, 5, 'Wa qaalooo asaateerul awwaleenak tatabahaa fahiya tumlaa \'alaihi bukratanw wa aseelaa'),
  ('en.transliteration', 25, 6, 'Qul anzalhul lazee ya\'lamus sirra fis samaawaati wal-ard; innahoo kaana Ghafoorar Raheemaa'),
  ('en.transliteration', 25, 7, 'Wa qaaloo maa li haazar Rasooli yaakulut ta\'aama wa yamshee fil aswaaq; law laaa unzila ilaihi malakun fa yakoona ma\'ahoo nazeeraa'),
  ('en.transliteration', 25, 8, 'Aw yulqaaa ilaihi kanzun aw takoonu lahoo jannatuny yaakulu minhaa; wa qaalaz zaalimoona in tattabi\'oona illaa rajulam mas hooraa'),
  ('en.transliteration', 25, 9, 'Unzur kaifa daraboo lakal amsaala fadalloo falaa yastatee\'oona sabeelaa'),
  ('en.transliteration', 25, 10, 'Tabaarakal lazeee in shaaa\'a ja\'ala laka khairam min zaalika jannaatin tajree min tahtihal anhaaru wa yaj\'al laka qusooraa'),
  ('en.transliteration', 25, 11, 'Bal kazzaboo bis Saa\'ati wa a\'tadnaa liman kazzaba bis Saa\'ati sa\'eeraa'),
  ('en.transliteration', 25, 12, 'Izaa ra\'at hum mim ma kaanim ba\'eedin sami\'oo lahaa taghaiyuzanw wa zafeeraa'),
  ('en.transliteration', 25, 13, 'Wa izaaa ulqoo minhaa makaanan daiyiqam muqar raneena da\'aw hunaalika subooraa'),
  ('en.transliteration', 25, 14, 'Laa tad\'ul yawma subooranw waahidanw wad\'oo subooran kaseeraa'),
  ('en.transliteration', 25, 15, 'Qul azaalika khairun am Jannatul khuldil latee wu\'idal muttaqoon; kaanat lahum jazaaa\'anw wa maseeraa'),
  ('en.transliteration', 25, 16, 'Lahum feehaa maa yashaaa\'oona khaalideen; kaana \'alaa Rabbika wa\'dam mas\'oolaa'),
  ('en.transliteration', 25, 17, 'Wa Yawma yahshuruhum wa maa ya\'budoona min doonil lahi fa yaqoolu \'a-antum adlaltum \'ibaadee haaa\'ulaaa\'i am hum dallus sabeel'),
  ('en.transliteration', 25, 18, 'Qaaloo Subhaanaka maa kaana yambaghee lanaaa an nattakhiza min doonika min awliyaaa\'a wa laakim matta\'tahum wa aabaaa\'ahum hattaa nasuz zikra wa kaanoo qawmam booraa'),
  ('en.transliteration', 25, 19, 'Faqad kazzabookum bimaa taqooloona famaa tastatee\'oona sarfanw wa laa nasraa; wa mai yazlim minkum nuziqhu \'azaaban kabeeraa'),
  ('en.transliteration', 25, 20, 'Wa maaa arsalnaa qablaka minal mursaleena illaaa innahum la yaakuloonat ta\'aama wa yamshoona fil aswaaq; wa ja\'alnaa ba\'dakum liba\'din fitnatan atasbiroon; wa kaana Rabbuka Baseera'),
  ('en.transliteration', 25, 21, 'Wa qaalal lazeena laa yarjoona liqaaa\'anaa law laaa unzila \'alainal malaaa\'ikatu awnaraa Rabbanaa; laqadistakbaroo feee anfusihim wa \'ataw \'utuwwan kabeeraa'),
  ('en.transliteration', 25, 22, 'Yawma yarawnal malaaa \'ikata laa bushraa Yawma\'izil lilmujrimeena wa yaqooloona hijram mahjooraa'),
  ('en.transliteration', 25, 23, 'Wa qadimnaaa ilaa maa \'amiloo min \'amalin faja\'alnaahu habaaa\'am mansooraa'),
  ('en.transliteration', 25, 24, 'As haabul jannati yawma\'izin khairum mustaqar ranw wa ahsanu maqeela'),
  ('en.transliteration', 25, 25, 'Wa Yawma tashaqqaqus samaaa\'u bilghamaami wa nuzzilal malaaa\'ikatu tanzeela'),
  ('en.transliteration', 25, 26, 'Almulku Yawma\'izinil haqqu lir Rahmaan; wa kaana Yawman\'alal kaafireena \'aseeraa'),
  ('en.transliteration', 25, 27, 'Wa Yawma ya\'adduz zaalimu \'alaa yadaihi yaqoolu yaa laitanit takhaztu ma\'ar Rasooli sabeelaa'),
  ('en.transliteration', 25, 28, 'Yaa wailataa laitanee lam attakhiz fulaanan khaleelaa'),
  ('en.transliteration', 25, 29, 'Laqad adallanee \'aniz zikri ba\'da iz jaaa\'anee; wa kaanash Shaitaanu lil insaani khazoolaa'),
  ('en.transliteration', 25, 30, 'Wa qaalar Rasoolu yaa Rabbi inna qawmit takhazoo haazal Qur-aana mahjooraa'),
  ('en.transliteration', 25, 31, 'Wa kazaalika ja\'alnaa likulli Nabiyyin \'aduwwam minal mujrimeen; wa kafaa bi Rabbika haadiyanw wa naseeraa'),
  ('en.transliteration', 25, 32, 'Wa qaalal lazeena kafaroo law laa nuzzila \'alaihil Quraanu jumlatanw waahidah; kazaalika linusabbita bihee fu\'aadaka wa rattalnaahu tarteelaa'),
  ('en.transliteration', 25, 33, 'Wa laa yaatoonaka bimasainn illaa ji\'naaka bilhaqqi wa ahsana tafseeraa'),
  ('en.transliteration', 25, 34, 'Allazeena yuhsharoona \'alaa wujoohim ilaa jahannama ulaaa\'ika sharrum makaananw wa adallu sabeelaa )section 3)'),
  ('en.transliteration', 25, 35, 'Wa laqad aatainaa Moosal Kitaaba wa ja\'alnaa ma\'ahooo akhaahu Haaroona wazeeraa'),
  ('en.transliteration', 25, 36, 'Faqulnaz habaaa ilal qawmil lazeena kazzaboo bi Aayaatinaa fadammarnaahum tadmeeraa'),
  ('en.transliteration', 25, 37, 'Wa qawma Noohil lammaa kazzabur Rusula aghraqnaahum wa ja\'alnaahum linnaasi Aayatanw wa a\'tadnaa lizzaalimeena \'azaaban aleemaa'),
  ('en.transliteration', 25, 38, 'Wa \'Aadanw Samooda wa As haabar Rassi wa quroonam baina zaalika kaseeraa'),
  ('en.transliteration', 25, 39, 'Wa kullandarabnaa lahul amsaala wa kullan tabbarnaa tatbeera'),
  ('en.transliteration', 25, 40, 'Wa laqad ataw \'alal qaryatil lateee umtirat mataras saw\'; afalam yakoonoo yarawnahaa; bal kaanoo laa yarjoona nushooraa'),
  ('en.transliteration', 25, 41, 'Wa izaa ra awka iny yattakhizoonaka illaa huzuwan ahaazal lazee ba\'asal laahu Rasoolaa'),
  ('en.transliteration', 25, 42, 'In kaada la yudillunaa \'an aalihatinaa law laaa an sabarnaa \'alaihaa; wa sawfa ya\'lamoona heena yarawnal \'azaaba man adallu sabeela'),
  ('en.transliteration', 25, 43, 'Ara\'aita manit takhaza ilaahahoo hawaahu afa anta takoonu \'alaihi wakeelaa'),
  ('en.transliteration', 25, 44, 'Am tahsabu annna aksarahum yasma\'oona aw ya\'\'qiloon; in hum illaa kal an\'aami bal hum adallu sabeelan'),
  ('en.transliteration', 25, 45, 'Alam tara ilaa Rabbika kaifa maddaz zilla wa law shaaa\'a laja\'alahoo saakinan summa ja\'alnash shamsa \'alaihe daleelaa'),
  ('en.transliteration', 25, 46, 'Summa qabadnaahu ilainaa qabdany yaseeraa'),
  ('en.transliteration', 25, 47, 'Wa Huwal lazee ja\'ala lakumul laila libaasanw wannawma subaatanw wa ja\'alan nahaara nushooraa'),
  ('en.transliteration', 25, 48, 'Wa Huwal lazeee arsalar riyaaha bushram baina yadai rahmatih; wa anzalnaa minas samaaa\'i maaa\'an tahooraa'),
  ('en.transliteration', 25, 49, 'Linuhyiya bihee balda tam maitanw wa nusqiyahoo mimmaa khalaqnaaa an\'aa manw wa anaasiyya kaseeraa'),
  ('en.transliteration', 25, 50, 'Wa laqad sarrafnaahu bainahum li yazzakkaroo fa abaaa aksarun naasi illaa kufooraa'),
  ('en.transliteration', 25, 51, 'Wa law shi\'naa laba\'asnaa fee kulli qar yatin nazeeraa'),
  ('en.transliteration', 25, 52, 'Falaa tuti\'il kaafireena wa jaahidhum bihee jihaadan kabeeraa'),
  ('en.transliteration', 25, 53, 'Wa Huwal lazee marajal bahraini haazaa \'azbun furaatunw wa haazaa milhun ujaaj; wa ja\'ala bainahumaa barzakhanw wa hijram mahjooraa'),
  ('en.transliteration', 25, 54, 'Wa Huwal lazee khalaqa minal maaa\'i basharran fa ja\'alahoo nasaban wa sihraa; wa kaana Rabbuka Qadeeraa'),
  ('en.transliteration', 25, 55, 'Wa ya\'budoona min doonil laahi maa laa yanfa\'uhum wa laa yadurruhum; wa kaanal kaafiru \'alaa Rabbihee zaheeraa'),
  ('en.transliteration', 25, 56, 'Wa maa arsalnaaka illaa mubashshiranw wa nazeeraa'),
  ('en.transliteration', 25, 57, 'Qul maaa as\'alukum \'alaihi min ajrin illaa man shaaa\'a ai yattakhiza ilaa Rabbihee sabeelaa'),
  ('en.transliteration', 25, 58, 'Wa tawakkal \'alal Haiyil lazee laa yamootu wa sabbih bihamdih; wa kafaa bihee bizunoobi \'ibaadihee khabeeraa'),
  ('en.transliteration', 25, 59, 'Allazee khalaqas samaawaati wal arda wa maa bainahumaa fee sittati aiyaamin summmmastawaa \'alal \'Arsh; ar Rahmaanu fas\'al bihee khabeeraa'),
  ('en.transliteration', 25, 60, 'Wa izaa qeela lahumus judoo lir Rahmaani qaaloo wa mar Rahmaanu anasjudu limaa taamurunaa wa zaadahum nufooraa'),
  ('en.transliteration', 25, 61, 'Tabaarakal lazee ja\'ala fis samaaa\'i buroojanw wa ja\'ala feehaa siraajanw wa qamaram muneeraa'),
  ('en.transliteration', 25, 62, 'Wa huwal lazee ja\'alal laila wannahaara khilfatal liman araada ai yazzakkara aw araadaa shookooraa'),
  ('en.transliteration', 25, 63, 'Wa \'ibaadur Rahmaanil lazeena yamshoona \'alal ardi hawnanw wa izaa khaata bahumul jaahiloona qaaloo salaamaa'),
  ('en.transliteration', 25, 64, 'Wallazeena yabeetoona li Rabbihim sujjadanw wa qiyaamaa'),
  ('en.transliteration', 25, 65, 'Wallazeena yaqooloona Rabbanas rif \'annnaa \'azaaba Jahannama inn \'azaabahaa kaana gharaamaa'),
  ('en.transliteration', 25, 66, 'Innahaa saaa\'at mustaqarranw wa muqaamaa'),
  ('en.transliteration', 25, 67, 'Wallazeena izaaa anfaqoo lam yusrifoo wa lam yaqturoo wa kaana baina zaalika qawaamaa'),
  ('en.transliteration', 25, 68, 'Wallazeena laa yad\'oona ma\'al laahi ilaahan aakhara wa laa yaqtuloonan nafsal latee harramal laahu illaa bilhaqqi wa laa yaznoon; wa mai yaf\'al zaalika yalqa asaamaa'),
  ('en.transliteration', 25, 69, 'Yudaa\'af lahul \'azaabu Yawmal Qiyaamati wa yakhlud feehee muhaanaa'),
  ('en.transliteration', 25, 70, 'Illaa man taaba wa \'aamana wa \'amila \'amalan saalihan fa ulaaa\'ika yubad dilul laahu saiyi aatihim hasanaat; wa kaanal laahu Ghafoorar Raheemaa'),
  ('en.transliteration', 25, 71, 'Wa man taaba wa \'amila saalihan fa innnahoo yatoobu ilal laahi mataabaa'),
  ('en.transliteration', 25, 72, 'Wallazeena laa yash hadoonaz zoora wa izaa marroo billaghwi marroo kiraamaa'),
  ('en.transliteration', 25, 73, 'Wallazeena izaa zukkiroo bi Aayaati Rabbihim lam yakhirroo \'alaihaa summanw wa\'umyaanaa'),
  ('en.transliteration', 25, 74, 'Wallazeena yaqooloona Rabbanaa hab lanaa min azwaajinaa wa zurriyaatinaa qurrata a\'yuninw waj \'alnaa lilmuttaqeena Imaamaa'),
  ('en.transliteration', 25, 75, 'Ulaaa\'ika yujzawnal ghurfata bimaa sabaroo wa yulaqqawna feehaa tahiyyatanw wa salaamaa'),
  ('en.transliteration', 25, 76, 'Khaalideena feehaa; hasunat mustaqarranw wa muqaamaa'),
  ('en.transliteration', 25, 77, 'Qul maa ya\'ba\'u bikum Rabbee law laa du\'aaa\'ukum faqad kazzabtum fasawfa yakoonu lizaamaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 25, 1, 'وہ بڑی برکت والا ہے جس نے اپنے بندے پر قرآن نازل کیا تاکہ تمام جہان کے لیےڈرانے والا ہو'),
  ('ur.ahmedali', 25, 2, 'وہ جس کی آسمانوں اور زمین میں سلطنت ہے اور اس نے نہ کسی کو بیٹا بنایا ہے اور نہ کوئی سلطنت میں اس کا شریک ہے اور اس نے ہر چیز کو پیدا کر کے اندازہ پر قائم کر دیا'),
  ('ur.ahmedali', 25, 3, 'اور انہوں نے الله کے سوا ایسے معبود بنا رکھے ہیں جو کچھ بھی پیدا نہیں کر سکتے حالانکہ وہ خود پیدا کیے گئے ہیں اور وہ اپنی ذات کے لیے نقصان اور نفع کے مالک نہیں اور موت اور زندگی اور دوبارہ اٹھنے کے بھی مالک نہیں'),
  ('ur.ahmedali', 25, 4, 'اور کافر کہتے ہیں کہ یہ تو محض جھوٹ ہے جسے اس نے بنا لیا ہے اور دوسرے لوگوں نے اس میں ا س کی مدد کی ہے پس وہ بڑے ظلم اور جھوٹ پر اتر آئے ہیں'),
  ('ur.ahmedali', 25, 5, 'اور کہتے ہیں کہ پہلوں کی کہانیاں ہیں کہ جنہیں اس نے لکھ رکھا ہے پس وہی اس پر صبح اور شام پڑھی جاتی ہیں'),
  ('ur.ahmedali', 25, 6, 'کہہ دو کہ اسے تو اس نے نازل کیا ہے جو آسمانوں اور زمین کی پوشیدہ باتیں جانتا ہے بے شک وہ بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 25, 7, 'اور کہتے ہیں اس رسول کو کیا ہوگیا کہ کھاناکھاتا اور بازاروں میں پھرتا ہے اس کے پاس کوئی فرشتہ کیوں نہیں بھیجا گیا کہ اس کے ساتھ وہ بھی ڈرانے والا ہوتا'),
  ('ur.ahmedali', 25, 8, 'یا اس کے پاس کوئی خزانہ آجاتا یا اس کے لیے باغ ہوتا جس میں سےکھاتا اور بے انصافوں نے کہا کہ تم تو بس ایک ایسے شخص کے تابع ہوگئے جس پر جادو کیا گیا ہے'),
  ('ur.ahmedali', 25, 9, 'دیکھو تو تمہارے لیے کیسی مثالیں بیان کرتے ہیں پس وہ ایسے گمراہ ہو ئے کہ راستہ بھی نہیں پا سکتے'),
  ('ur.ahmedali', 25, 10, 'بڑی برکت ہے اس کی جو چاہے تو تیرے لیے اس سے بہتر باغ بنا دے جن کے نیچے نہریں بہتی ہوں اور تیرے لیے محل بنا دے'),
  ('ur.ahmedali', 25, 11, 'بلکہ انہوں نے تو قیامت کو جھوٹ سمجھ لیا ہے اور ہم نے اس کے لیے آگ تیار کی ہے جو قیامت کو جھٹلاتا ہے'),
  ('ur.ahmedali', 25, 12, 'جب وہ انہیں دور سے دیکھے گی تو اس کے جوش و خروش کی آواز سنیں گے'),
  ('ur.ahmedali', 25, 13, 'اور جب وہ اس کے کسی تنگ مکان میں جکڑکر ڈال دیے جائیں گے تو وہاں موت کو پکاریں گے'),
  ('ur.ahmedali', 25, 14, 'آج ایک موت کو نہ پکارو اور بہت سی موتوں کو پکارو'),
  ('ur.ahmedali', 25, 15, 'کہہ دو کیا بہتر ہے یا وہ بہشت جس کا پرہیز گارو ں کے لیے وعدہ کیا گیا ہے جو ان کا بدلہ اور ٹھکانہ ہوگی'),
  ('ur.ahmedali', 25, 16, 'وہاں انہیں جو چاہیں گے ملے گا وہ اس میں ہمیشہ رہیں گے یہ وعدہ تیرے رب کے ذمہ ہے جو قابل درخواست ہے'),
  ('ur.ahmedali', 25, 17, 'اورجس دن انہیں اور ان کے معبودوں کو جمع کرے گا جنھیں وہ الله کے سوا پوجتے تھے تو فرمائے گا کیا تم ہی نے میرے ان بندوں کو گمراہ کیا تھا یا وہ خود راستہ بھول گئے تھے'),
  ('ur.ahmedali', 25, 18, 'کہیں گے تو پاک ہے ہمیں یہ کب لایق تھا کہ تیرے سوا کسی اور کو کارساز بناتے لیکن تو نے انہیں اور ان کے باپ دادا کو یہاں تک آسودگی دی تھی کہ وہ یاد کرنا بھول گئے اور یہ لوگ تباہ ہونے والے تھے'),
  ('ur.ahmedali', 25, 19, 'سو تمہارے معبودوں نے تمہاری باتو ں میں تمہیں جھٹلا دیا سو تم نہ تو ٹال سکتے ہو اور نہ مدد دے سکتے ہو اور جو تم میں سے ظلم کرے گا ہم اسے بڑا عذاب چکھائیں گے'),
  ('ur.ahmedali', 25, 20, 'اور ہم نے تجھ سے پہلے جتنے پیغمبر بھیجے وہ کھانا بھی کھاتے تھے اور بازاروں میں بھی چلتے پھرتے تھے اورہم نے تمہیں ایک دوسرے کے لیے آزمائش بنایا کیا تم ثابت قدم رہتے ہو اور تیرا رب سب کچھ دیکھنے والا ہے'),
  ('ur.ahmedali', 25, 21, 'اور ان لوگوں نے کہا جو ہم سے ملنے کی امید نہیں رکھتے کہ ہمارے پاس فرشتے کیوں نہ بھیجے گئے یا ہم اپنے رب کو دیکھ لیتے البتہ انہوں نے اپنے آپ کو بہت بڑاسمجھ لیا ہے اور بہت بڑی سرکشی کی ہے'),
  ('ur.ahmedali', 25, 22, 'جس دن فرشتوں کو دیکھیں گے اس دن مجرموں کے لیے کوئی خوشی نہیں ہو گی اورکہیں گے آڑ کر دی جائے'),
  ('ur.ahmedali', 25, 23, 'اور جو عمل انہوں نے کیے تھے ہم ان کی طرف متوجہ ہوں گے پھر انہیں اڑتی ہوئی خاک کر دیں گے'),
  ('ur.ahmedali', 25, 24, 'اس دن بہشتیوں کا ٹھکانا بہتر ہوگا اور دوپہر کی آرام گاہ بھی عمدہ ہو گی'),
  ('ur.ahmedali', 25, 25, 'اور جس دن آسمان بادل سے پھٹ جائے گا اور فرشتے بکثرت اتارے جائیں گے'),
  ('ur.ahmedali', 25, 26, 'اس دن حقیقی حکومت رحمنٰ ہی کی ہوگی اور وہ دن کافروں پر بڑا سخت ہوگا'),
  ('ur.ahmedali', 25, 27, 'اور اس دن ظالم اپنے ہاتھ کاٹ کاٹ کھائے گا کہے گا اے کاش میں بھی رسول کے ساتھ راہ چلتا'),
  ('ur.ahmedali', 25, 28, 'ہائے میری شامت کاش میں نے فلاں کو دوست نہ بنایا ہوتا'),
  ('ur.ahmedali', 25, 29, 'اسی نے تو نصیحت کے آنے کےبعد مجھے بہکا دیا اور شیطان تو انسان کو رسوا کرنے والا ہی ہے'),
  ('ur.ahmedali', 25, 30, 'اور رسول کہے گا اے میرے رب بےشک میری قوم نے اس قرآن کو نظر انداز کر رکھا تھا'),
  ('ur.ahmedali', 25, 31, 'اور ہم اسی مجرموں کو ہر ایک نبی کا دشمن بناتے رہے ہیں اور ہدایت کرنے اور مدد کرنے کے لیے تیرا رب کافی ہے'),
  ('ur.ahmedali', 25, 32, 'اور کافر کہتے ہیں کہ اس پر یکبارگی قرآن کیوں نازل نہیں کیا گیا اسی طرح اتارا گیا تاکہ ہم اس سے تیرے دل کو اطمینان دیں اور ہم نے اسے ٹھہر ٹھہر کر پڑھ سنایا'),
  ('ur.ahmedali', 25, 33, 'اور جو انوکھی بات تیرے سامنے لائیں گے ہم بھی تمہیں اس کا بہت ٹھیک جواب اوربہت عمدہ حل بتائیں'),
  ('ur.ahmedali', 25, 34, 'جو لوگ مونہوں کے بل گھسیٹ کر جہنم میں ڈالیں جائیں گے یہی برے درجے والے ہیں اور بہت ہی بڑے گمراہ ہیں'),
  ('ur.ahmedali', 25, 35, 'اور البتہ تحقیق ہم نے موسیٰ کو کتاب دی اور ہم نے اس کے ساتھ اس کے بھائی ہارون کو وزیر بنایا'),
  ('ur.ahmedali', 25, 36, 'پھر ہم نے کہا تم دونو ان لوگوں کی طرف جاؤ جنہو ں نے ہماری آیتیں جھٹلائی ہیں پھر ہم نے انہیں جڑ سے اکھاڑ کر پھینک دیا'),
  ('ur.ahmedali', 25, 37, 'اور نوح کی قوم کوبھی جب انہو ں نے رسولوں کو جھٹلایا تو ہم نے انہیں غرق کر دیا اور ہم نے انہیں لوگوں کے لیے نشانی بنا دیا اور ہم نے ظالموں کے لیے دردناک عذاب تیار کیا ہے'),
  ('ur.ahmedali', 25, 38, 'اور عاد اور ثمود اورکنوئیں والوں کو بھی اوربہت سے دور جو ان کے درمیان تھے'),
  ('ur.ahmedali', 25, 39, 'اور ہم نے ہر ایک کو مثالیں دے کر سمجھایا تھا اور سب کو ہم نے ہلاک کر دیا'),
  ('ur.ahmedali', 25, 40, 'اور یہ اس بستی پر بھی گزرے ہیں جس پر بری طرح پتھر برسائے گئے سو کیا یہ لوگ اسے دیکھتے نہیں رہتے بلکہ یہ لوگ مر کر زندہ ہونے کی امید ہی نہیں رکھتے'),
  ('ur.ahmedali', 25, 41, 'اور جب یہ لوگ تمہیں دیکھتے ہیں تو بس تم سے مذاق کرنے لگتے ہیں کیا یہی ہے جسےالله نے رسول بنا کر بھیجا'),
  ('ur.ahmedali', 25, 42, 'اس نے تو ہمیں ہمارے معبودوں سے ہٹا ہی دیا ہوتا اگر ہم ان پر قائم نہ رہتے اور انہیں جلدی معلوم ہوجائے گا جب عذاب دیکھیں گے کہ کون شخص گمراہ تھا'),
  ('ur.ahmedali', 25, 43, 'کیا تم نے اس شخص کو دیکھا جس نے اپنا خدا اپنی خوہشات نفسانی کو بنا رکھا ہے پھر کیا تو اس کا ذمہ دار ہو سکتا ہے'),
  ('ur.ahmedali', 25, 44, 'یا تو خیال کرتا ہے کہ اکثر ان میں سے سنتے یا سمجھتے ہیں یہ تو محض چوپایوں کی طرح ہیں بلکہ ان سے بھی زیادہ گمراہ ہیں'),
  ('ur.ahmedali', 25, 45, 'کیا تو نے اپنے رب کی طرف نہیں دیکھا کہ اس نے سایہ کو کیسے پھیلایا ہے اور اگر چاہتا تو اسے ٹھہرا رکھتا پھر ہم نے سورج کو اس کا سبب بنا دیا ہے'),
  ('ur.ahmedali', 25, 46, 'پھر ہم اسے آہستہ آہستہ اپنی طرف سمیٹتے ہیں'),
  ('ur.ahmedali', 25, 47, 'اور وہی ہے جس نے تمہارے لیے رات کو اوڑھنا اور نیند کو راحت بنا دیا اور دن چلنے پھرنے کے لیے بنایا'),
  ('ur.ahmedali', 25, 48, 'اوروہی تو ہے جو اپنی رحمت سے پہلے خوشخبری لانے والی ہوائیں چلاتا ہے اور ہم نے آسمان سے پاک پانی نازل فرمایا'),
  ('ur.ahmedali', 25, 49, 'تاکہ ہم اس سے مرے ہوئے شہر کو زندہ کریں اور اسے اپنی پیدا کی ہوئی چیزوں، چارپایوں اوربہت سے آدمیوں کوپلائیں'),
  ('ur.ahmedali', 25, 50, 'اور ہم نے اسے لوگوں میں بانٹ دیا ہے تاکہ نصیحت حاصل کریں پس بہت سے آدمی ناشکری کیے بغیر نہ رہے'),
  ('ur.ahmedali', 25, 51, 'اور اگر ہم چاہتے تو ہر گاؤں میں ایک ڈرانے والا بھیج دیتے'),
  ('ur.ahmedali', 25, 52, 'پس کافروں کا کہا نہ مان اس کے ساتھ بڑے زور سے ان کا مقابلہ کر'),
  ('ur.ahmedali', 25, 53, 'اور وہی ہے جس نے دو دریاؤں کو آپس میں ملا دیا یہ میٹھا خوشگوار ہے او ریہ کھاری کڑوا ہے اوران دونوں میں ایک پردہ اور مستحکم آڑ بنا دی'),
  ('ur.ahmedali', 25, 54, 'اوروہی ہے جس نے انسان کو پانی سے پیدا کیا پھر ا س کے لیے رشتہ نسب اور دامادی قائم کیا اور تیرا رب ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 25, 55, 'اور وہ الله کے سوا ایسے کو پوجتے ہیں جو انہیں نہ نفع دے سکتے ہیں نہ نقصان پہنچا سکتے ہیں اور کافر اپنے رب کی طرف پیٹھ پھیرنے والا ہے'),
  ('ur.ahmedali', 25, 56, 'اور ہم نےتمہیں محض خوشخبری دینے والا اور ڈرانے والا بنا کر بھیجا ہے'),
  ('ur.ahmedali', 25, 57, 'کہہ دو میں اس پر تم سے کوئی مزدوری نہیں مانگتا مگر جو شخص اپنے رب کی طرف راستہ معلوم کرنا چاہے'),
  ('ur.ahmedali', 25, 58, 'اورتم اس زندہ خدا پر بھروسہ رکھو جو کبھی نہ مرے گا اور اس کی تسبیح اورحمد کرتے رہو اور وہ اپنے بندوں کے گناہوں سے کافی خبردار ہے'),
  ('ur.ahmedali', 25, 59, 'جس نے آسمان اور زمین اور جو کچھ ان میں ہے چھ دن میں بنایا پھر عرش پر قائم ہوا وہ رحمنٰ ہے پس ا س کی شان کسی خبردار سے پوچھو'),
  ('ur.ahmedali', 25, 60, 'اورجب ان سے کہا جاتا ہے کہ رحمنٰ کو سجدہ کرو توکہتے ہیں رحمنٰ کیا ہے کیا ہم اسے سجدہ کریں جس کے لیے تو کہہ دے اور اس سے انہیں اور زیادہ نفرت ہوتی ہے'),
  ('ur.ahmedali', 25, 61, 'بڑا برکت والا ہے وہ جس نے آسمان میں ستارے بنائے اور اس میں چراغ اور چمکتا ہوا چاند بھی بنایا'),
  ('ur.ahmedali', 25, 62, 'اور وہی ہے جس نے رات اور دن یکے بعد دیگرے آنے والے بنائے یہ اس کے لیے ہے جو سمجھنا چاہے یا شکر کرنا چاہے'),
  ('ur.ahmedali', 25, 63, 'اور رحمنٰ کے بندے وہ ہیں جو زمین پردبے پاؤں چلتے ہیں اورجب ان سے بے سمجھ لوگ بات کریں تو کہتے ہیں سلام ہے'),
  ('ur.ahmedali', 25, 64, 'اور وہ لوگ جو اپنے رب کے سامنے سجدہ میں اور کھڑے ہوکر رات گزارتے ہیں'),
  ('ur.ahmedali', 25, 65, 'اور وہ لوگ جو کہتے ہیں اے ہمارے رب ہم سے دوزخ کا عذاب دور کر دے بے شک اس کا عذاب پوری تباہی ہے'),
  ('ur.ahmedali', 25, 66, 'بے شک وہ برا ٹھکانا اوربڑی قیام گاہ ہے'),
  ('ur.ahmedali', 25, 67, 'اوروہ لوگ جب خرچ کرتے ہیں تو فضول خرچی نہیں کرتے اور نہ تنگی کرتے ہیں اور ان کا خرچ ان دونوں کے درمیان اعتدال پر ہوتا ہے'),
  ('ur.ahmedali', 25, 68, 'اوروہ جو الله کے سوا کسی اور معبود کونہیں پکارتے اور اس شخص کوناحق قتل نہیں کرتے جسے الله نے حرام کر دیا ہے اور زنا نہیں کرتے اور جس شخص نے یہ کیا وہ گناہ میں جا پڑا'),
  ('ur.ahmedali', 25, 69, 'قیامت کے دن اسے دگنا عذاب ہو گا اس میں ذلیل ہو کر پڑا رہے گا'),
  ('ur.ahmedali', 25, 70, 'مگر جس نے توبہ کی اور ایمان لایا اور نیک کام کیے سو انہیں الله برائیوں کی جگہ بھلائیاں بدل دے گا اور الله بخشنے والا مہربان ہے'),
  ('ur.ahmedali', 25, 71, 'اور جس نے توبہ کی اور نیک کام کیے تو وہ الله کی طرف رجوع کرتا ہے'),
  ('ur.ahmedali', 25, 72, 'اور جو بے ہودہ باتوں میں شامل نہیں ہوتے اور جب بیہودہ باتوں کے پاس سے گزریں تو شریفانہ طور سے گزرتے ہیں'),
  ('ur.ahmedali', 25, 73, 'اور وہ لوگ جب انہیں ان کے رب کی آیتوں سے سمجھایا جاتا ہے تو ان پر بہرے اندھے ہو کر نہیں گرتے'),
  ('ur.ahmedali', 25, 74, 'اور وہ جو کہتے ہیں کہ ہمارے رب ہمیں ہماری بیویوں اور اولاد کی طرف سے آنکھوں کی ٹھنڈک عطا فرما اور ہمیں پرہیزگاروں کا پیشوا بنا دے'),
  ('ur.ahmedali', 25, 75, 'یہی لوگ ہیں جنہیں ان کے صبر کے بدلہ میں جنت کے بالا خانے دیے جائیں گے اور ان کا وہاں دعا اور سلام سے استقبال کیا جائے گا'),
  ('ur.ahmedali', 25, 76, 'اس میں ہمیشہ رہنے والے ہوں گے ٹھیرنے اور رہنے کی خوب جگہ ہے'),
  ('ur.ahmedali', 25, 77, 'کہہ دو میرا رب تمہاری پروا نہیں کرتا اگرتم اسے نہ پکارو سو تم جھٹلا توچکے ہو پھر اب تو اس کا وبال پڑ کر رہے گا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 25, 1, 'Göklerin ve yerin hükümranlığı kendisinin olan, çocuk edinmeyen, hükümranlıkta ortağı bulunmayan, herşeyi yaratıp bir ölçüye göre düzenleyen ve dünyaları uyarmak üzere kuluna hakkı batıldan ayırdeden Kuran\'ı indiren Allah yücelerin yücesidir.'),
  ('tr.diyanet', 25, 2, 'Göklerin ve yerin hükümranlığı kendisinin olan, çocuk edinmeyen, hükümranlıkta ortağı bulunmayan, herşeyi yaratıp bir ölçüye göre düzenleyen ve dünyaları uyarmak üzere kuluna hakkı batıldan ayırdeden Kuran\'ı indiren Allah yücelerin yücesidir.'),
  ('tr.diyanet', 25, 3, 'Kafirler, O\'nu bırakıp, birşey yaratamayan, bilakis kendileri yaratılmış olan, kendilerine ne zarar ve ne de fayda verebilen; öldürmeye, diriltmeye ve ölümden sonra tekrar canlandırmaya güçleri yetmeyen tanrılar edindiler.'),
  ('tr.diyanet', 25, 4, 'İnkar edenler: "Bu Kuran uydurmadır, ona başka bir topluluk yardım etmiştir" diyerek haksız ve asılsız bir söz uydurdular.'),
  ('tr.diyanet', 25, 5, '"Kuran öncekilerin masallarıdır; başkalarına yazdırıp sabah akşam kendisine okunmaktadır" dediler.'),
  ('tr.diyanet', 25, 6, 'De ki: "Onu, göklerin ve yerin sırrını bilen indirmiştir. Şüphesiz O, bağışlayandır, merhamet edendir."'),
  ('tr.diyanet', 25, 7, 'Şöyle dediler: "Bu ne biçim peygamber ki yemek yer, sokaklarda gezer? Ona, beraberinde bulunup uyaran bir melek indirilseydi ya! Yahut, kendisine bir hazine verilseydi, veya besleneceği bir bahçe olsaydı ya!" Bu zalimler, inananlara: "Siz sadece büyülenmiş bir adama uyuyorsunuz" dediler.'),
  ('tr.diyanet', 25, 8, 'Şöyle dediler: "Bu ne biçim peygamber ki yemek yer, sokaklarda gezer? Ona, beraberinde bulunup uyaran bir melek indirilseydi ya! Yahut, kendisine bir hazine verilseydi, veya besleneceği bir bahçe olsaydı ya!" Bu zalimler, inananlara: "Siz sadece büyülenmiş bir adama uyuyorsunuz" dediler.'),
  ('tr.diyanet', 25, 9, 'Sana nasıl misaller getirdiklerine bir bak! Onlar sapmışlardır, yol bulamazlar.'),
  ('tr.diyanet', 25, 10, 'Dilerse sana, bunlardan daha iyi olan, içlerinden ırmaklar akan cennetler verebilen ve köşkler kurabilen Allah yücelerin yücesidir.'),
  ('tr.diyanet', 25, 11, 'Zaten onlar, kıyamet saatini de yalanladılar. O saatin geleceğini yalanlayanlara çılgın alevli bir ateş hazırlamışızdır.'),
  ('tr.diyanet', 25, 12, 'Bu ateş, onlara uzak bir yerden gözükünce, onun kaynamasını ve uğultusunu işitirler.'),
  ('tr.diyanet', 25, 13, 'Elleri boyunlarına bağlanarak, dar bir yerden atıldıkları zaman, orada, yok olup gitmeyi isterler.'),
  ('tr.diyanet', 25, 14, '"Bir kere yok olmayı değil, birçok defa yok olmayı isteyin" denir.'),
  ('tr.diyanet', 25, 15, 'De ki: "Bu mu iyidir, yoksa Allah\'a karşı gelmekten sakınanlara mükafat ve gidilecek yer olarak söz verilen ebedi cennet mi daha iyidir?"'),
  ('tr.diyanet', 25, 16, 'Temelli kalacakları cennette diledikleri şeyleri bulurlar. Bu, Rabbinin yerine getirilmesi istenen bir vaadidir.'),
  ('tr.diyanet', 25, 17, 'O gün Rabbin onları ve Allah\'ı bırakıp da taptıkları şeyleri toplar ve: "Bu kullarımı siz mi saptırdınız, yoksa kendi kendilerine mi yoldan saptılar?" der.'),
  ('tr.diyanet', 25, 18, 'Onlar: "Haşa; Seni bırakıp başka dostlar edinmek bize yaraşmaz; fakat Sen onlara ve babalarına nimetler verdin de sonunda Seni anmayı unuttular ve helaki hak eden bir millet oldular" derler.'),
  ('tr.diyanet', 25, 19, '"Söylediklerinizde sizi yalancı çıkardılar, artık kendinizden azabı çeviremez, yardım da göremezsiniz. Zulmedenlerinize büyük bir azap tattıracağız" denir.'),
  ('tr.diyanet', 25, 20, 'Senden önce gönderdiğimiz bütün peygamberler de, şüphesiz, yemek yerler, sokaklarda gezerlerdi. Ey insanlar! Sabreder misiniz diye sizi birbirinizle sınarız. Rabbin her şeyi görür.'),
  ('tr.diyanet', 25, 21, 'Bizimle karşılaşmayı ummayanlar: "Bize ya melekler indirilmeli, ya da Rabbimiz\'i görmeliyiz" derler. And olsun ki kendi kendilerine büyüklenmişler, azgınlıkta pek ileri gitmişlerdir.'),
  ('tr.diyanet', 25, 22, 'Melekleri gördükleri gün, işte o gün, suçlulara iyi haber yoktur. Melekler: "İyi haber size yasaktır, yasak!" derler.'),
  ('tr.diyanet', 25, 23, 'Yaptıkları her işi ele alır, onu toz duman ederiz.'),
  ('tr.diyanet', 25, 24, 'O gün, cennetliklerin kalacağı yer çok iyi, dinlenecekleri yer çok güzeldir.'),
  ('tr.diyanet', 25, 25, 'O gün, gök beyaz bulutlar halinde parçalanacak ve melekler bölük bölük indirilecektir.'),
  ('tr.diyanet', 25, 26, 'O gün gerçek hükümdarlık Rahman\'ındır. İnkarcılar için yaman bir gündür.'),
  ('tr.diyanet', 25, 27, 'O gün, zalim kimse ellerini ısırıp: "Keşke Peygamberle beraber bir yol tutsaydım, vay başıma gelene; keşke falancayı dost edinmeseydim. And olsun ki beni, bana gelen Kuran\'dan o saptırdı. Şeytan insanı yalnız ve yardımcısız bırakıyor" der.'),
  ('tr.diyanet', 25, 28, 'O gün, zalim kimse ellerini ısırıp: "Keşke Peygamberle beraber bir yol tutsaydım, vay başıma gelene; keşke falancayı dost edinmeseydim. And olsun ki beni, bana gelen Kuran\'dan o saptırdı. Şeytan insanı yalnız ve yardımcısız bırakıyor" der.'),
  ('tr.diyanet', 25, 29, 'O gün, zalim kimse ellerini ısırıp: "Keşke Peygamberle beraber bir yol tutsaydım, vay başıma gelene; keşke falancayı dost edinmeseydim. And olsun ki beni, bana gelen Kuran\'dan o saptırdı. Şeytan insanı yalnız ve yardımcısız bırakıyor" der.'),
  ('tr.diyanet', 25, 30, 'Peygamber: "Ey Rabbim! Doğrusu milletim bu Kuran\'ı terketmişti" der.'),
  ('tr.diyanet', 25, 31, 'Her peygamber için, böylece suçlulardan bir düşman ortaya koyarız. Doğruyu gösterici ve yardımcı olarak, Rabbin yeter.'),
  ('tr.diyanet', 25, 32, 'İnkar edenler: "Kuran ona bir defada indirilmeliydi" derler. Oysa Biz onu böylece senin kalbine yerleştirmek için azar azar indirir ve onu ağır ağır okuruz.'),
  ('tr.diyanet', 25, 33, 'Sana bir misal vermezler ki, Biz onun gerçeğini ve en iyi anlaşılanını sana vermemiş olalım.'),
  ('tr.diyanet', 25, 34, 'Cehennemde yüzü koyun toplanacak olanlar, işte onların yerleri en kötü ve yolları da en sapıktır.'),
  ('tr.diyanet', 25, 35, 'And olsun ki Musa\'ya Kitap verdik, kardeşi Harun\'u da kendisine vezir yaptık.'),
  ('tr.diyanet', 25, 36, '"Ayetlerimizi yalanlayan millete gidin" dedik. Sonunda o milleti yerle bir ettik.'),
  ('tr.diyanet', 25, 37, 'Nuh milletini de, peygamberleri yalanladıkları zaman suda boğduk ve kendilerini insanlar için bir ibret kıldık. Zalimlere can yakıcı azap hazırlamışızdır.'),
  ('tr.diyanet', 25, 38, 'Ad, Semud milletleri ile Ress\'lileri ve bunların arasında birçok nesilleri de yerle bir ettik.'),
  ('tr.diyanet', 25, 39, 'Her birine misaller vermiştik ama, dinlemedikleri için hepsini kırdık geçirdik.'),
  ('tr.diyanet', 25, 40, 'Bu putperestler and olsun ki, bela yağmuruna tutulmuş olan kasabaya uğramışlardı. Onu görmediler mi? Hayır; tekrar dirilmeyi ummuyorlardı.'),
  ('tr.diyanet', 25, 41, 'Seni gördükleri zaman, "Allah\'ın gönderdiği elçi bu mudur?" diye alaya almaktan başka birşey yapmazlar.'),
  ('tr.diyanet', 25, 42, '"Tanrılarımız üzerinde direnmeseydik, doğrusu neredeyse bizi onlardan uzaklaştıracaktı" derler. Azabı gördükleri zaman, kimin yolunun sapık olduğunu bileceklerdir.'),
  ('tr.diyanet', 25, 43, 'Hevesini kendine tanrı edineni gördün mü? Ona sen mi vekil olacaksın?'),
  ('tr.diyanet', 25, 44, 'Yoksa çoklarının söz dinlediklerini veya aklettiklerini mi sanırsın? Onlar şüphesiz davarlar gibidir, belki daha da sapık yolludurlar.'),
  ('tr.diyanet', 25, 45, 'Rabbinin gölgeyi nasıl uzattığını görmez misin? İsteseydi onu durdururdu. Sonra Biz güneşi, ona delil kılıp yavaş yavaş kendimize çekmişizdir.'),
  ('tr.diyanet', 25, 46, 'Rabbinin gölgeyi nasıl uzattığını görmez misin? İsteseydi onu durdururdu. Sonra Biz güneşi, ona delil kılıp yavaş yavaş kendimize çekmişizdir.'),
  ('tr.diyanet', 25, 47, 'Size geceyi örtü, uykuyu rahatlık kılan, gündüzü çalışma zamanı yapan Allah\'tır.'),
  ('tr.diyanet', 25, 48, 'Rüzgarları rahmetinin önünde müjdeci gönderen O\'dur. Ölü bir yeri diriltmek ve yarattığımız nice hayvan ve insanları sulamak için gökten tertemiz su indirmişizdir.'),
  ('tr.diyanet', 25, 49, 'Rüzgarları rahmetinin önünde müjdeci gönderen O\'dur. Ölü bir yeri diriltmek ve yarattığımız nice hayvan ve insanları sulamak için gökten tertemiz su indirmişizdir.'),
  ('tr.diyanet', 25, 50, 'And olsun ki öğüt almaları için ülkeler arasında yer yer türlü türlü yağmur yağdırmışızdır. Buna rağmen insanların çoğu nankörlükte direnmiştir.'),
  ('tr.diyanet', 25, 51, 'Dileseydik, her kente bir uyarıcı gönderirdik.'),
  ('tr.diyanet', 25, 52, 'Sen, inkarcılara uyma, onlara karşı olanca gücünle mücadele et.'),
  ('tr.diyanet', 25, 53, 'Birinin suyu tatlı ve kolay içimli, diğerininki tuzlu ve acı olan iki denizi salıverip aralarına da, karışmalarına engel olan bir sınır koyan Allah\'tır.'),
  ('tr.diyanet', 25, 54, 'İnsanı sudan yaratarak, ona soy sop veren O\'dur. Rabbin herşeye Kadir\'dir.'),
  ('tr.diyanet', 25, 55, 'Allah\'ı bırakıp, kendilerine fayda da zarar da veremeyen şeylere kulluk ederler. İnkar eden, Rabbine karşı gelenin (şeytanın) yardımcısıdır.'),
  ('tr.diyanet', 25, 56, 'Biz seni sadece müjdeci ve uyarıcı olarak gönderdik.'),
  ('tr.diyanet', 25, 57, 'De ki: "Ben buna karşı sizden bir ücret değil, ancak, Rabbine doğru bir yol tutmak dileyen kimseler olmanızı istiyorum."'),
  ('tr.diyanet', 25, 58, 'Ölümsüz, diri olan Allah\'a güven, O\'nu överek tesbih et. Kullarının günahlarından haberdar olarak kendisi yeter.'),
  ('tr.diyanet', 25, 59, 'Gökleri, yeri ve ikisinin arasındakileri altı günde yaratan sonra da arşa hükmeden Rahman\'dır. Bunu bir bilene sor.'),
  ('tr.diyanet', 25, 60, 'Onlara: "Rahman\'a secdeye varın" dendiği zaman "Rahman da nedir? Emrettiğine mi secdeye varacağız?" derler. Bu, onların nefretini artırır.'),
  ('tr.diyanet', 25, 61, 'Gökte burçlar vareden, orada ışık saçan güneş ve aydınlatan ayı yaratan Allah, yücelerin yücesidir.'),
  ('tr.diyanet', 25, 62, 'İbret almak veya şükretmek dileyen kimseler için gece ile gündüzü birbiri ardınca getiren O\'dur.'),
  ('tr.diyanet', 25, 63, 'Rahman\'ın kulları yeryüzünde mütevazı yürürler. Bilgisizler kendilerine takıldıkları zaman onlara güzel ve yumuşak söz söylerler.'),
  ('tr.diyanet', 25, 64, 'Onlar, gecelerini Rableri için kıyama durarak ve secdeye vararak geçirirler.'),
  ('tr.diyanet', 25, 65, 'Onlar, "Rabbimiz! Bizden cehennem azabını uzaklaştır; doğrusu onun azabı sürekli ve acıdır. Orası şüphesiz kötü bir yer ve kötü bir duraktır" derler.'),
  ('tr.diyanet', 25, 66, 'Onlar, "Rabbimiz! Bizden cehennem azabını uzaklaştır; doğrusu onun azabı sürekli ve acıdır. Orası şüphesiz kötü bir yer ve kötü bir duraktır" derler.'),
  ('tr.diyanet', 25, 67, 'Onlar, sarfettikleri zaman ne israf ederler ne de cimrilik, ikisi arasında orta bir yol tutarlar.'),
  ('tr.diyanet', 25, 68, 'Onlar, Allah\'ın yanında başka tanrı tutup ona yalvarmazlar. Allah\'ın haram kıldığı cana haksız yere kıymazlar. Zina etmezler. Bunları yapan günaha girmiş olur.'),
  ('tr.diyanet', 25, 69, 'Kıyamet günü azabı kat kat olur, orada, alçaltılarak temelli kalır.'),
  ('tr.diyanet', 25, 70, 'Ancak tevbe eden, inanıp yararlı iş işleyenlerin, işte Allah onların kötülüklerini iyiliklere çevirir. Allah bağışlar ve merhamet eder.'),
  ('tr.diyanet', 25, 71, 'Kim tevbe edip yararlı iş işlerse, şüphesiz o, Allah\'a gereği gibi yönelmiş olur.'),
  ('tr.diyanet', 25, 72, 'Onlar yalan yere şehadet etmezler; faydasız birşeye rastladıkları zaman yüz çevirip vakarla geçerler.'),
  ('tr.diyanet', 25, 73, 'Kendilerine Rablerinin ayetleri hatırlatıldığı zaman, onlara karşı kör ve sağır davranmazlar.'),
  ('tr.diyanet', 25, 74, 'Onlar: "Rabbimiz! Bize eşlerimizden ve çocuklarımızdan gözümüzün aydınlığı olacak insanlar ihsan et ve bizi, Allah\'a karşı gelmekten sakınanlara önder yap" derler.'),
  ('tr.diyanet', 25, 75, 'İşte onlar, sabrettiklerinden ötürü cennetin en yüksek dereceleriyle mükafatlandırılırlar. Orada esenlik ve dirlik dilekleriyle karşılanırlar.'),
  ('tr.diyanet', 25, 76, 'Orada temellidirler. Orası ne güzel bir yer ve ne güzel duraktır!'),
  ('tr.diyanet', 25, 77, 'De ki: "İbadetiniz (duanız) olmasa Rabbim size ne diye değer versin?" Ey inkarcılar! Yalanladığınız için, azap yakanızı bırakmayacaktır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 25, 1, 'Maha suci Allah yang telah menurunkan Al Furqaan (Al Quran) kepada hamba-Nya, agar dia menjadi pemberi peringatan kepada seluruh alam,'),
  ('id.indonesian', 25, 2, 'yang kepunyaan-Nya-lah kerajaan langit dan bumi, dan Dia tidak mempunyai anak, dan tidak ada sekutu bagi-Nya dalam kekuasaan(Nya), dan dia telah menciptakan segala sesuatu, dan Dia menetapkan ukuran-ukurannya dengan serapi-rapinya.'),
  ('id.indonesian', 25, 3, 'Kemudian mereka mengambil tuhan-tuhan selain daripada-Nya (untuk disembah), yang tuhan-tuhan itu tidak menciptakan apapun, bahkan mereka sendiri diciptakan dan tidak kuasa untuk (menolak) sesuatu kemudharatan dari dirinya dan tidak (pula untuk mengambil) suatu kemanfaatanpun dan (juga) tidak kuasa mematikan, menghidupkan dan tidak (pula) membangkitkan.'),
  ('id.indonesian', 25, 4, 'Dan orang-orang kafir berkata: "Al Quran ini tidak lain hanyalah kebohongan yang diada-adakan oleh Muhammad dan dia dibantu oleh kaum yang lain"; maka sesungguhnya mereka telah berbuat suatu kezaliman dan dusta yang besar.'),
  ('id.indonesian', 25, 5, 'Dan mereka berkata: "Dongengan-dongengan orang-orang dahulu, dimintanya supaya dituliskan, maka dibacakanlah dongengan itu kepadanya setiap pagi dan petang".'),
  ('id.indonesian', 25, 6, 'Katakanlah: "Al Quran itu diturunkan oleh (Allah) yang mengetahui rahasia di langit dan di bumi. Sesungguhnya Dia adalah Maha Pengampun lagi Maha Penyayang".'),
  ('id.indonesian', 25, 7, 'Dan mereka berkata: "Mengapa rasul itu memakan makanan dan berjalan di pasar-pasar? Mengapa tidak diturunkan kepadanya seorang malaikat agar malaikat itu memberikan peringatan bersama-sama dengan dia?,'),
  ('id.indonesian', 25, 8, 'atau (mengapa tidak) diturunkan kepadanya perbendaharaan, atau (mengapa tidak) ada kebun baginya, yang dia dapat makan dari (hasil)nya?" Dan orang-orang yang zalim itu berkata: "Kamu sekalian tidak lain hanyalah mengikuti seorang lelaki yang kena sihir".'),
  ('id.indonesian', 25, 9, 'Perhatikanlah, bagaimana mereka membuat perbandingan-perbandingan tentang kamu, lalu sesatlah mereka, mereka tidak sanggup (mendapatkan) jalan (untuk menentang kerasulanmu).'),
  ('id.indonesian', 25, 10, 'Maha Suci (Allah) yang jika Dia menghendaki, niscaya dijadikan-Nya bagimu yang lebih baik dari yang demikian, (yaitu) surga-surga yang mengalir sungai-sungai di bawahnya, dan dijadikan-Nya (pula) untukmu istana-istana.'),
  ('id.indonesian', 25, 11, 'Bahkan mereka mendustakan hari kiamat. Dan kami menyediakan neraka yang menyala-nyala bagi siapa yang mendustakan hari kiamat.'),
  ('id.indonesian', 25, 12, 'Apabila neraka itu melihat mereka dari tempat yang jauh, mereka mendengar kegeramannya dan suara nyalanya.'),
  ('id.indonesian', 25, 13, 'Dan apabila mereka dilemparkan ke tempat yang sempit di neraka itu dengan dibelenggu, mereka di sana mengharapkan kebinasaan.'),
  ('id.indonesian', 25, 14, '(Akan dikatakan kepada mereka): "Jangan kamu sekalian mengharapkan satu kebinasaan, melainkan harapkanlah kebinasaan yang banyak".'),
  ('id.indonesian', 25, 15, 'Katakanlah: "Apa (azab) yang demikian itukah yang baik, atau surga yang kekal yang telah dijanjikan kepada orang-orang yang bertakwa?" Dia menjadi balasan dan tempat kembali bagi mereka?".'),
  ('id.indonesian', 25, 16, 'Bagi mereka di dalam surga itu apa yang mereka kehendaki, sedang mereka kekal (di dalamnya). (Hal itu) adalah janji dari Tuhanmu yang patut dimohonkan (kepada-Nya).'),
  ('id.indonesian', 25, 17, 'Dan (ingatlah) suatu hari (ketika) Allah menghimpunkan mereka beserta apa yang mereka sembah selain Allah, lalu Allah berkata (kepada yang disembah); "Apakah kamu yang menyesatkan hamba-hamba-Ku itu, atau mereka sendirikah yang sesat dari jalan (yang benar)?".'),
  ('id.indonesian', 25, 18, 'Mereka (yang disembah itu) menjawab: "Maha Suci Engkau, tidaklah patut bagi kami mengambil selain engkau (untuk jadi) pelindung, akan tetapi Engkau telah memberi mereka dan bapak-bapak mereka kenikmatan hidup, sampai mereka lupa mengingati (Engkau); dan mereka adalah kaum yang binasa".'),
  ('id.indonesian', 25, 19, 'maka sesungguhnya mereka (yang disembah itu) telah mendustakan kamu tentang apa yang kamu katakan maka kamu tidak akan dapat menolak (azab) dan tidak (pula) menolong (dirimu), dan barang siapa di antara kamu yang berbuat zalim, niscaya Kami rasakan kepadanya azab yang besar.'),
  ('id.indonesian', 25, 20, 'Dan Kami tidak mengutus rasul-rasul sebelummu, melainkan mereka sungguh memakan makanan dan berjalan di pasar-pasar. Dan kami jadikan sebahagian kamu cobaan bagi sebahagian yang lain. Maukah kamu bersabar?; dan adalah Tuhanmu maha Melihat.'),
  ('id.indonesian', 25, 21, 'Berkatalah orang-orang yang tidak menanti-nanti pertemuan(nya) dengan Kami: "Mengapakah tidak diturunkan kepada kita malaikat atau (mengapa) kita (tidak) melihat Tuhan kita?" Sesungguhnya mereka memandang besar tentang diri mereka dan mereka benar-benar telah melampaui batas(dalam melakukan) kezaliman".'),
  ('id.indonesian', 25, 22, 'Pada hari mereka melihat malaikat dihari itu tidak ada kabar gembira bagi orang-orang yang berdosa mereka berkata: "Hijraan mahjuuraa.'),
  ('id.indonesian', 25, 23, 'Dan kami hadapi segala amal yang mereka kerjakan, lalu kami jadikan amal itu (bagaikan) debu yang berterbangan.'),
  ('id.indonesian', 25, 24, 'Penghuni-penghuni surga pada hari itu palig baik tempat tinggalnya dan paling indah tempat istirahatnya.'),
  ('id.indonesian', 25, 25, 'Dan (ingatlah) hari (ketika) langit pecah belah mengeluarkan kabut putih dan diturunkanlah malaikat bergelombang-gelombang.'),
  ('id.indonesian', 25, 26, 'Kerajaan yang hak pada hari itu adalah kepunyaan Tuhan Yang Maha Pemurah. Dan adalah (hari itu), satu hari penuh kesukaran bagi orang-orang kafir.'),
  ('id.indonesian', 25, 27, 'Dan (ingatlah) hari (ketika itu) orang yang zalim menggigit dua tangannya, seraya berkata: "Aduhai kiranya (dulu) aku mengambil jalan bersama-sama Rasul".'),
  ('id.indonesian', 25, 28, 'Kecelakaan besarlah bagiku; kiranya aku (dulu) tidak menjadikan sifulan itu teman akrab(ku).'),
  ('id.indonesian', 25, 29, 'Sesungguhnya dia telah menyesatkan aku dari Al Quran ketika Al Quran itu telah datang kepadaku. Dan adalah syaitan itu tidak mau menolong manusia.'),
  ('id.indonesian', 25, 30, 'Berkatalah Rasul: "Ya Tuhanku, sesungguhnya kaumku menjadikan Al Quran itu sesuatu yang tidak diacuhkan".'),
  ('id.indonesian', 25, 31, 'Dan seperti itulah, telah Kami adakan bagi tiap-tiap nabi, musuh dari orang-orang yang berdosa. Dan cukuplah Tuhanmu menjadi Pemberi petunjuk dan Penolong.'),
  ('id.indonesian', 25, 32, 'Berkatalah orang-orang yang kafir: "Mengapa Al Quran itu tidak diturunkan kepadanya sekali turun saja?"; demikianlah supaya Kami perkuat hatimu dengannya dan Kami membacanya secara tartil (teratur dan benar).'),
  ('id.indonesian', 25, 33, 'Tidaklah orang-orang kafir itu datang kepadamu (membawa) sesuatu yang ganjil, melainkan Kami datangkan kepadamu suatu yang benar dan yang paling baik penjelasannya.'),
  ('id.indonesian', 25, 34, 'Orang-orang yang dihimpunkan ke neraka Jahannam dengan diseret atas muka-muka mereka, mereka itulah orang yang paling buruk tempatnya dan paling sesat jalannya.'),
  ('id.indonesian', 25, 35, 'Dan sesungguhnya kami telah memberikan Al Kitab (Taurat) kepada Musa dan Kami telah menjadikan Harun saudaranya, menyertai dia sebagai wazir (pembantu).'),
  ('id.indonesian', 25, 36, 'Kemudian Kami berfirman kepada keduanya: "Pergilah kamu berdua kepada kaum yang mendustakan ayat-ayat Kami". Maka Kami membinasakan mereka sehancur-hancurnya.'),
  ('id.indonesian', 25, 37, 'Dan (telah Kami binasakan) kaum Nuh tatkala mereka mendustakan rasul-rasul. Kami tenggelamkan mereka dan kami jadikan (cerita) mereka itu pelajaran bagi manusia. Dan Kami telah menyediakan bagi orang-orang zalim azab yang pedih;'),
  ('id.indonesian', 25, 38, 'dan (Kami binasakan) kaum \'Aad dan Tsamud dan penduduk Rass dan banyak (lagi) generasi-generasi di antara kaum-kaum tersebut.'),
  ('id.indonesian', 25, 39, 'Dan Kami jadikan bagi masing-masing mereka perumpamaan dan masing-masing mereka itu benar benar telah Kami binasakan dengan sehancur-hancurnya.'),
  ('id.indonesian', 25, 40, 'Dan sesungguhnya mereka (kaum musyrik Mekah) telah melalui sebuah negeri (Sadum) yang (dulu) dihujani dengan hujan yang sejelek-jeleknya (hujan batu). Maka apakah mereka tidak menyaksikan runtuhan itu; bahkan adalah mereka itu tidak mengharapkan akan kebangkitan.'),
  ('id.indonesian', 25, 41, 'Dan apabila mereka melihat kamu (Muhammad), mereka hanyalah menjadikan kamu sebagai ejekan (dengan mengatakan): "Inikah orangnya yang di utus Allah sebagai Rasul?.'),
  ('id.indonesian', 25, 42, 'Sesungguhnya hampirlah ia menyesatkan kita dari sembahan-sembahan kita, seandainya kita tidak sabar(menyembah)nya" dan mereka kelak akan mengetahui di saat mereka melihat azab, siapa yang paling sesat jalannya.'),
  ('id.indonesian', 25, 43, 'Terangkanlah kepadaku tentang orang yang menjadikan hawa nafsunya sebagai tuhannya. Maka apakah kamu dapat menjadi pemelihara atasnya?,'),
  ('id.indonesian', 25, 44, 'atau apakah kamu mengira bahwa kebanyakan mereka itu mendengar atau memahami. Mereka itu tidak lain, hanyalah seperti binatang ternak, bahkan mereka lebih sesat jalannya (dari binatang ternak itu).'),
  ('id.indonesian', 25, 45, 'Apakah kamu tidak memperhatikan (penciptaan) Tuhanmu, bagaimana Dia memanjangkan (dan memendekkan) bayang-bayang dan kalau Dia menghendaki niscaya Dia menjadikan tetap bayang-bayang itu, kemudian Kami jadikan matahari sebagai petunjuk atas bayang-bayang itu,'),
  ('id.indonesian', 25, 46, 'kemudian Kami menarik bayang-bayang itu kepada kami dengan tarikan yang perlahan-lahan.'),
  ('id.indonesian', 25, 47, 'Dialah yang menjadikan untukmu malam (sebagai) pakaian, dan tidur untuk istirahat, dan Dia menjadikan siang untuk bangun berusaha.'),
  ('id.indonesian', 25, 48, 'Dialah yang meniupkan angin (sebagai) pembawa kabar gembira dekat sebelum kedatangan rahmat-nya (hujan); dan Kami turunkan dari langit air yang amat bersih,'),
  ('id.indonesian', 25, 49, 'agar Kami menghidupkan dengan air itu negeri (tanah) yang mati, dan agar Kami memberi minum dengan air itu sebagian besar dari makhluk Kami, binatang-binatang ternak dan manusia yang banyak.'),
  ('id.indonesian', 25, 50, 'Dan sesungguhnya Kami telah mempergilirkan hujan itu diantara manusia supaya mereka mengambil pelajaran (dari padanya); maka kebanyakan manusia itu tidak mau kecuali mengingkari (nikmat).'),
  ('id.indonesian', 25, 51, 'Dan andaikata Kami menghendaki benar-benarlah Kami utus pada tiap-tiap negeri seorang yang memberi peringatan (rasul).'),
  ('id.indonesian', 25, 52, 'Maka janganlah kamu mengikuti orang-orang kafir, dan berjihadlah terhadap mereka dengan Al Quran dengan jihad yang besar.'),
  ('id.indonesian', 25, 53, 'Dan Dialah yang membiarkan dua laut yang mengalir (berdampingan); yang ini tawar lagi segar dan yang lain asin lagi pahit; dan Dia jadikan antara keduanya dinding dan batas yang menghalangi.'),
  ('id.indonesian', 25, 54, 'Dan Dia (pula) yang menciptakan manusia dari air lalu dia jadikan manusia itu (punya) keturunan dan mushaharah dan adalah Tuhanmu Maha Kuasa.'),
  ('id.indonesian', 25, 55, 'Dan mereka menyembah selain Allah apa yang tidak memberi manfaat kepada mereka dan tidak (pula) memberi mudharat kepada mereka. Adalah orang-orang kafir itu penolong (syaitan untuk berbuat durhaka) terhadap Tuhannya.'),
  ('id.indonesian', 25, 56, 'Dan tidaklah Kami mengutus kamu melainkan hanya sebagai pembawa kabar gembira dan pemberi peringatan.'),
  ('id.indonesian', 25, 57, 'Katakanlah: "Aku tidak meminta upah sedikitpun kepada kamu dalam menyampaikan risalah itu, melainkan (mengharapkan kepatuhan) orang-orang yang mau mengambil jalan kepada Tuhan nya.'),
  ('id.indonesian', 25, 58, 'Dan bertawakkallah kepada Allah yang hidup (kekal) Yang tidak mati, dan bertasbihlah dengan memuji-Nya. Dan cukuplah Dia Maha Mengetahui dosa-dosa hamba-hamba-Nya.'),
  ('id.indonesian', 25, 59, 'Yang menciptakan langit dan bumi dan apa yang ada antara keduanya dalam enam masa, kemudian dia bersemayam di atas \'Arsy, (Dialah) Yang Maha Pemurah, maka tanyakanlah (tentang Allah) kepada yang lebih mengetahui (Muhammad) tentang Dia.'),
  ('id.indonesian', 25, 60, 'Dan apabila dikatakan kepada mereka: "Sujudlah kamu sekalian kepada yang Maha Penyayang", mereka menjawab: "Siapakah yang Maha Penyayang itu? Apakah kami akan sujud kepada Tuhan Yang kamu perintahkan kami(bersujud kepada-Nya)?", dan (perintah sujud itu) menambah mereka jauh (dari iman).'),
  ('id.indonesian', 25, 61, 'Maha Suci Allah yang menjadikan di langit gugusan-gugusan bintang dan Dia menjadikan juga padanya matahari dan bulan yang bercahaya.'),
  ('id.indonesian', 25, 62, 'Dan Dia (pula) yang menjadikan malam dan siang silih berganti bagi orang yang ingin mengambil pelajaran atau orang yang ingin bersyukur.'),
  ('id.indonesian', 25, 63, 'Dan hamba-hamba Tuhan yang Maha Penyayang itu (ialah) orang-orang yang berjalan di atas bumi dengan rendah hati dan apabila orang-orang jahil menyapa mereka, mereka mengucapkan kata-kata (yang mengandung) keselamatan.'),
  ('id.indonesian', 25, 64, 'Dan orang yang melalui malam hari dengan bersujud dan berdiri untuk Tuhan mereka.'),
  ('id.indonesian', 25, 65, 'Dan orang-orang yang berkata: "Ya Tuhan kami, jauhkan azab jahannam dari kami, sesungguhnya azabnya itu adalah kebinasaan yang kekal".'),
  ('id.indonesian', 25, 66, 'Sesungguhnya jahannam itu seburuk-buruk tempat menetap dan tempat kediaman.'),
  ('id.indonesian', 25, 67, 'Dan orang-orang yang apabila membelanjakan (harta), mereka tidak berlebihan, dan tidak (pula) kikir, dan adalah (pembelanjaan itu) di tengah-tengah antara yang demikian.'),
  ('id.indonesian', 25, 68, 'Dan orang-orang yang tidak menyembah tuhan yang lain beserta Allah dan tidak membunuh jiwa yang diharamkan Allah (membunuhnya) kecuali dengan (alasan) yang benar, dan tidak berzina, barang siapa yang melakukan yang demikian itu, niscaya dia mendapat (pembalasan) dosa(nya),'),
  ('id.indonesian', 25, 69, '(yakni) akan dilipat gandakan azab untuknya pada hari kiamat dan dia akan kekal dalam azab itu, dalam keadaan terhina,'),
  ('id.indonesian', 25, 70, 'kecuali orang-orang yang bertaubat, beriman dan mengerjakan amal saleh; maka itu kejahatan mereka diganti Allah dengan kebajikan. Dan adalah Allah maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 25, 71, 'Dan orang-orang yang bertaubat dan mengerjakan amal saleh, maka sesungguhnya dia bertaubat kepada Allah dengan taubat yang sebenar-benarnya.'),
  ('id.indonesian', 25, 72, 'Dan orang-orang yang tidak memberikan persaksian palsu, dan apabila mereka bertemu dengan (orang-orang) yang mengerjakan perbuatan-perbuatan yang tidak berfaedah, mereka lalui (saja) dengan menjaga kehormatan dirinya.'),
  ('id.indonesian', 25, 73, 'Dan orang-orang yang apabila diberi peringatan dengan ayat-ayat Tuhan mereka, mereka tidaklah menghadapinya sebagai orang-orang yang tuli dan buta.'),
  ('id.indonesian', 25, 74, 'Dan orang orang yang berkata: "Ya Tuhan kami, anugrahkanlah kepada kami isteri-isteri kami dan keturunan kami sebagai penyenang hati (kami), dan jadikanlah kami imam bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 25, 75, 'Mereka itulah orang yang dibalasi dengan martabat yang tinggi (dalam surga) karena kesabaran mereka dan mereka disambut dengan penghormatan dan ucapan selamat di dalamnya,'),
  ('id.indonesian', 25, 76, 'mereka kekal di dalamnya. Surga itu sebaik-baik tempat menetap dan tempat kediaman.'),
  ('id.indonesian', 25, 77, 'Katakanlah (kepada orang-orang musyrik): "Tuhanku tidak mengindahkan kamu, melainkan kalau ada ibadatmu. (Tetapi bagaimana kamu beribadat kepada-Nya), padahal kamu sungguh telah mendustakan-Nya? karena itu kelak (azab) pasti (menimpamu)".')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (24, 10, 2801, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ', 350, 18, 140, 0),
  (24, 11, 2802, 'إِنَّ ٱلَّذِينَ جَآءُو بِٱلْإِفْكِ عُصْبَةٌۭ مِّنكُمْ ۚ لَا تَحْسَبُوهُ شَرًّۭا لَّكُم ۖ بَلْ هُوَ خَيْرٌۭ لَّكُمْ ۚ لِكُلِّ ٱمْرِئٍۢ مِّنْهُم مَّا ٱكْتَسَبَ مِنَ ٱلْإِثْمِ ۚ وَٱلَّذِى تَوَلَّىٰ كِبْرَهُۥ مِنْهُمْ لَهُۥ عَذَابٌ عَظِيمٌۭ', 351, 18, 140, 0),
  (24, 12, 2803, 'لَّوْلَآ إِذْ سَمِعْتُمُوهُ ظَنَّ ٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَٰتُ بِأَنفُسِهِمْ خَيْرًۭا وَقَالُوا۟ هَٰذَآ إِفْكٌۭ مُّبِينٌۭ', 351, 18, 140, 0),
  (24, 13, 2804, 'لَّوْلَا جَآءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَآءَ ۚ فَإِذْ لَمْ يَأْتُوا۟ بِٱلشُّهَدَآءِ فَأُو۟لَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلْكَٰذِبُونَ', 351, 18, 140, 0),
  (24, 14, 2805, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ لَمَسَّكُمْ فِى مَآ أَفَضْتُمْ فِيهِ عَذَابٌ عَظِيمٌ', 351, 18, 140, 0),
  (24, 15, 2806, 'إِذْ تَلَقَّوْنَهُۥ بِأَلْسِنَتِكُمْ وَتَقُولُونَ بِأَفْوَاهِكُم مَّا لَيْسَ لَكُم بِهِۦ عِلْمٌۭ وَتَحْسَبُونَهُۥ هَيِّنًۭا وَهُوَ عِندَ ٱللَّهِ عَظِيمٌۭ', 351, 18, 140, 0),
  (24, 16, 2807, 'وَلَوْلَآ إِذْ سَمِعْتُمُوهُ قُلْتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبْحَٰنَكَ هَٰذَا بُهْتَٰنٌ عَظِيمٌۭ', 351, 18, 140, 0),
  (24, 17, 2808, 'يَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثْلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤْمِنِينَ', 351, 18, 140, 0),
  (24, 18, 2809, 'وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 351, 18, 140, 0),
  (24, 19, 2810, 'إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلْفَٰحِشَةُ فِى ٱلَّذِينَ ءَامَنُوا۟ لَهُمْ عَذَابٌ أَلِيمٌۭ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ ۚ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ', 351, 18, 140, 0),
  (24, 20, 2811, 'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفٌۭ رَّحِيمٌۭ', 351, 18, 140, 0),
  (24, 21, 2812, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ ۚ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًۭا وَلَٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 352, 18, 141, 0),
  (24, 22, 2813, 'وَلَا يَأْتَلِ أُو۟لُوا۟ ٱلْفَضْلِ مِنكُمْ وَٱلسَّعَةِ أَن يُؤْتُوٓا۟ أُو۟لِى ٱلْقُرْبَىٰ وَٱلْمَسَٰكِينَ وَٱلْمُهَٰجِرِينَ فِى سَبِيلِ ٱللَّهِ ۖ وَلْيَعْفُوا۟ وَلْيَصْفَحُوٓا۟ ۗ أَلَا تُحِبُّونَ أَن يَغْفِرَ ٱللَّهُ لَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌ', 352, 18, 141, 0),
  (24, 23, 2814, 'إِنَّ ٱلَّذِينَ يَرْمُونَ ٱلْمُحْصَنَٰتِ ٱلْغَٰفِلَٰتِ ٱلْمُؤْمِنَٰتِ لُعِنُوا۟ فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَلَهُمْ عَذَابٌ عَظِيمٌۭ', 352, 18, 141, 0),
  (24, 24, 2815, 'يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 352, 18, 141, 0),
  (24, 25, 2816, 'يَوْمَئِذٍۢ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلْحَقَّ وَيَعْلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ ٱلْمُبِينُ', 352, 18, 141, 0),
  (24, 26, 2817, 'ٱلْخَبِيثَٰتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَٰتِ ۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِ ۚ أُو۟لَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَ ۖ لَهُم مَّغْفِرَةٌۭ وَرِزْقٌۭ كَرِيمٌۭ', 352, 18, 141, 0),
  (24, 27, 2818, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتًا غَيْرَ بُيُوتِكُمْ حَتَّىٰ تَسْتَأْنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰٓ أَهْلِهَا ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ لَعَلَّكُمْ تَذَكَّرُونَ', 352, 18, 141, 0),
  (24, 28, 2819, 'فَإِن لَّمْ تَجِدُوا۟ فِيهَآ أَحَدًۭا فَلَا تَدْخُلُوهَا حَتَّىٰ يُؤْذَنَ لَكُمْ ۖ وَإِن قِيلَ لَكُمُ ٱرْجِعُوا۟ فَٱرْجِعُوا۟ ۖ هُوَ أَزْكَىٰ لَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌۭ', 353, 18, 141, 0),
  (24, 29, 2820, 'لَّيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَدْخُلُوا۟ بُيُوتًا غَيْرَ مَسْكُونَةٍۢ فِيهَا مَتَٰعٌۭ لَّكُمْ ۚ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ', 353, 18, 141, 0),
  (24, 30, 2821, 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا۟ مِنْ أَبْصَٰرِهِمْ وَيَحْفَظُوا۟ فُرُوجَهُمْ ۚ ذَٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا يَصْنَعُونَ', 353, 18, 141, 0),
  (24, 31, 2822, 'وَقُل لِّلْمُؤْمِنَٰتِ يَغْضُضْنَ مِنْ أَبْصَٰرِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا ۖ وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ ۖ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ ءَابَآئِهِنَّ أَوْ ءَابَآءِ بُعُولَتِهِنَّ أَوْ أَبْنَآئِهِنَّ أَوْ أَبْنَآءِ بُعُولَتِهِنَّ أَوْ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ إِخْوَٰنِهِنَّ أَوْ بَنِىٓ أَخَوَٰتِهِنَّ أَوْ نِسَآئِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيْرِ أُو۟لِى ٱلْإِرْبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفْلِ ٱلَّذِينَ لَمْ يَظْهَرُوا۟ عَلَىٰ عَوْرَٰتِ ٱلنِّسَآءِ ۖ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ ۚ وَتُوبُوٓا۟ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ', 353, 18, 141, 0),
  (24, 32, 2823, 'وَأَنكِحُوا۟ ٱلْأَيَٰمَىٰ مِنكُمْ وَٱلصَّٰلِحِينَ مِنْ عِبَادِكُمْ وَإِمَآئِكُمْ ۚ إِن يَكُونُوا۟ فُقَرَآءَ يُغْنِهِمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٌۭ', 354, 18, 141, 0),
  (24, 33, 2824, 'وَلْيَسْتَعْفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغْنِيَهُمُ ٱللَّهُ مِن فَضْلِهِۦ ۗ وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَٰبَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًۭا ۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِىٓ ءَاتَىٰكُمْ ۚ وَلَا تُكْرِهُوا۟ فَتَيَٰتِكُمْ عَلَى ٱلْبِغَآءِ إِنْ أَرَدْنَ تَحَصُّنًۭا لِّتَبْتَغُوا۟ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَمَن يُكْرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعْدِ إِكْرَٰهِهِنَّ غَفُورٌۭ رَّحِيمٌۭ', 354, 18, 141, 0),
  (24, 34, 2825, 'وَلَقَدْ أَنزَلْنَآ إِلَيْكُمْ ءَايَٰتٍۢ مُّبَيِّنَٰتٍۢ وَمَثَلًۭا مِّنَ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُمْ وَمَوْعِظَةًۭ لِّلْمُتَّقِينَ', 354, 18, 141, 0),
  (24, 35, 2826, '۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ مَثَلُ نُورِهِۦ كَمِشْكَوٰةٍۢ فِيهَا مِصْبَاحٌ ۖ ٱلْمِصْبَاحُ فِى زُجَاجَةٍ ۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌۭ دُرِّىٌّۭ يُوقَدُ مِن شَجَرَةٍۢ مُّبَٰرَكَةٍۢ زَيْتُونَةٍۢ لَّا شَرْقِيَّةٍۢ وَلَا غَرْبِيَّةٍۢ يَكَادُ زَيْتُهَا يُضِىٓءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌۭ ۚ نُّورٌ عَلَىٰ نُورٍۢ ۗ يَهْدِى ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُ ۚ وَيَضْرِبُ ٱللَّهُ ٱلْأَمْثَٰلَ لِلنَّاسِ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 354, 18, 142, 0),
  (24, 36, 2827, 'فِى بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا ٱسْمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلْغُدُوِّ وَٱلْءَاصَالِ', 354, 18, 142, 0),
  (24, 37, 2828, 'رِجَالٌۭ لَّا تُلْهِيهِمْ تِجَٰرَةٌۭ وَلَا بَيْعٌ عَن ذِكْرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِيتَآءِ ٱلزَّكَوٰةِ ۙ يَخَافُونَ يَوْمًۭا تَتَقَلَّبُ فِيهِ ٱلْقُلُوبُ وَٱلْأَبْصَٰرُ', 355, 18, 142, 0),
  (24, 38, 2829, 'لِيَجْزِيَهُمُ ٱللَّهُ أَحْسَنَ مَا عَمِلُوا۟ وَيَزِيدَهُم مِّن فَضْلِهِۦ ۗ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍۢ', 355, 18, 142, 0),
  (24, 39, 2830, 'وَٱلَّذِينَ كَفَرُوٓا۟ أَعْمَٰلُهُمْ كَسَرَابٍۭ بِقِيعَةٍۢ يَحْسَبُهُ ٱلظَّمْـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمْ يَجِدْهُ شَيْـًۭٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥ ۗ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ', 355, 18, 142, 0),
  (24, 40, 2831, 'أَوْ كَظُلُمَٰتٍۢ فِى بَحْرٍۢ لُّجِّىٍّۢ يَغْشَىٰهُ مَوْجٌۭ مِّن فَوْقِهِۦ مَوْجٌۭ مِّن فَوْقِهِۦ سَحَابٌۭ ۚ ظُلُمَٰتٌۢ بَعْضُهَا فَوْقَ بَعْضٍ إِذَآ أَخْرَجَ يَدَهُۥ لَمْ يَكَدْ يَرَىٰهَا ۗ وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُۥ نُورًۭا فَمَا لَهُۥ مِن نُّورٍ', 355, 18, 142, 0),
  (24, 41, 2832, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلطَّيْرُ صَٰٓفَّٰتٍۢ ۖ كُلٌّۭ قَدْ عَلِمَ صَلَاتَهُۥ وَتَسْبِيحَهُۥ ۗ وَٱللَّهُ عَلِيمٌۢ بِمَا يَفْعَلُونَ', 355, 18, 142, 0),
  (24, 42, 2833, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ', 355, 18, 142, 0),
  (24, 43, 2834, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يُزْجِى سَحَابًۭا ثُمَّ يُؤَلِّفُ بَيْنَهُۥ ثُمَّ يَجْعَلُهُۥ رُكَامًۭا فَتَرَى ٱلْوَدْقَ يَخْرُجُ مِنْ خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالٍۢ فِيهَا مِنۢ بَرَدٍۢ فَيُصِيبُ بِهِۦ مَن يَشَآءُ وَيَصْرِفُهُۥ عَن مَّن يَشَآءُ ۖ يَكَادُ سَنَا بَرْقِهِۦ يَذْهَبُ بِٱلْأَبْصَٰرِ', 355, 18, 142, 0),
  (24, 44, 2835, 'يُقَلِّبُ ٱللَّهُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّأُو۟لِى ٱلْأَبْصَٰرِ', 356, 18, 142, 0),
  (24, 45, 2836, 'وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةٍۢ مِّن مَّآءٍۢ ۖ فَمِنْهُم مَّن يَمْشِى عَلَىٰ بَطْنِهِۦ وَمِنْهُم مَّن يَمْشِى عَلَىٰ رِجْلَيْنِ وَمِنْهُم مَّن يَمْشِى عَلَىٰٓ أَرْبَعٍۢ ۚ يَخْلُقُ ٱللَّهُ مَا يَشَآءُ ۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 356, 18, 142, 0),
  (24, 46, 2837, 'لَّقَدْ أَنزَلْنَآ ءَايَٰتٍۢ مُّبَيِّنَٰتٍۢ ۚ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 356, 18, 142, 0),
  (24, 47, 2838, 'وَيَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعْنَا ثُمَّ يَتَوَلَّىٰ فَرِيقٌۭ مِّنْهُم مِّنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَٰٓئِكَ بِٱلْمُؤْمِنِينَ', 356, 18, 142, 0),
  (24, 48, 2839, 'وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌۭ مِّنْهُم مُّعْرِضُونَ', 356, 18, 142, 0),
  (24, 49, 2840, 'وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ', 356, 18, 142, 0),
  (24, 50, 2841, 'أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ ۚ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 356, 18, 142, 0),
  (24, 51, 2842, 'إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 356, 18, 142, 0),
  (24, 52, 2843, 'وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ', 356, 18, 142, 0),
  (24, 53, 2844, '۞ وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنْ أَمَرْتَهُمْ لَيَخْرُجُنَّ ۖ قُل لَّا تُقْسِمُوا۟ ۖ طَاعَةٌۭ مَّعْرُوفَةٌ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 356, 18, 143, 0),
  (24, 54, 2845, 'قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ ۖ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ ۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ', 357, 18, 143, 0),
  (24, 55, 2846, 'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ ٱلَّذِى ٱرْتَضَىٰ لَهُمْ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعْدِ خَوْفِهِمْ أَمْنًۭا ۚ يَعْبُدُونَنِى لَا يُشْرِكُونَ بِى شَيْـًۭٔا ۚ وَمَن كَفَرَ بَعْدَ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 357, 18, 143, 0),
  (24, 56, 2847, 'وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱلرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ', 357, 18, 143, 0),
  (24, 57, 2848, 'لَا تَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ مُعْجِزِينَ فِى ٱلْأَرْضِ ۚ وَمَأْوَىٰهُمُ ٱلنَّارُ ۖ وَلَبِئْسَ ٱلْمَصِيرُ', 357, 18, 143, 0),
  (24, 58, 2849, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِيَسْتَـْٔذِنكُمُ ٱلَّذِينَ مَلَكَتْ أَيْمَٰنُكُمْ وَٱلَّذِينَ لَمْ يَبْلُغُوا۟ ٱلْحُلُمَ مِنكُمْ ثَلَٰثَ مَرَّٰتٍۢ ۚ مِّن قَبْلِ صَلَوٰةِ ٱلْفَجْرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ ٱلظَّهِيرَةِ وَمِنۢ بَعْدِ صَلَوٰةِ ٱلْعِشَآءِ ۚ ثَلَٰثُ عَوْرَٰتٍۢ لَّكُمْ ۚ لَيْسَ عَلَيْكُمْ وَلَا عَلَيْهِمْ جُنَاحٌۢ بَعْدَهُنَّ ۚ طَوَّٰفُونَ عَلَيْكُم بَعْضُكُمْ عَلَىٰ بَعْضٍۢ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 357, 18, 143, 0),
  (24, 59, 2850, 'وَإِذَا بَلَغَ ٱلْأَطْفَٰلُ مِنكُمُ ٱلْحُلُمَ فَلْيَسْتَـْٔذِنُوا۟ كَمَا ٱسْتَـْٔذَنَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 358, 18, 143, 0),
  (24, 60, 2851, 'وَٱلْقَوَٰعِدُ مِنَ ٱلنِّسَآءِ ٱلَّٰتِى لَا يَرْجُونَ نِكَاحًۭا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَن يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَٰتٍۭ بِزِينَةٍۢ ۖ وَأَن يَسْتَعْفِفْنَ خَيْرٌۭ لَّهُنَّ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ', 358, 18, 143, 0),
  (24, 61, 2852, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌۭ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌۭ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌۭ وَلَا عَلَىٰٓ أَنفُسِكُمْ أَن تَأْكُلُوا۟ مِنۢ بُيُوتِكُمْ أَوْ بُيُوتِ ءَابَآئِكُمْ أَوْ بُيُوتِ أُمَّهَٰتِكُمْ أَوْ بُيُوتِ إِخْوَٰنِكُمْ أَوْ بُيُوتِ أَخَوَٰتِكُمْ أَوْ بُيُوتِ أَعْمَٰمِكُمْ أَوْ بُيُوتِ عَمَّٰتِكُمْ أَوْ بُيُوتِ أَخْوَٰلِكُمْ أَوْ بُيُوتِ خَٰلَٰتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُۥٓ أَوْ صَدِيقِكُمْ ۚ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا۟ جَمِيعًا أَوْ أَشْتَاتًۭا ۚ فَإِذَا دَخَلْتُم بُيُوتًۭا فَسَلِّمُوا۟ عَلَىٰٓ أَنفُسِكُمْ تَحِيَّةًۭ مِّنْ عِندِ ٱللَّهِ مُبَٰرَكَةًۭ طَيِّبَةًۭ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 358, 18, 143, 0),
  (24, 62, 2853, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰٓ أَمْرٍۢ جَامِعٍۢ لَّمْ يَذْهَبُوا۟ حَتَّىٰ يَسْتَـْٔذِنُوهُ ۚ إِنَّ ٱلَّذِينَ يَسْتَـْٔذِنُونَكَ أُو۟لَٰٓئِكَ ٱلَّذِينَ يُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ ۚ فَإِذَا ٱسْتَـْٔذَنُوكَ لِبَعْضِ شَأْنِهِمْ فَأْذَن لِّمَن شِئْتَ مِنْهُمْ وَٱسْتَغْفِرْ لَهُمُ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 359, 18, 143, 0),
  (24, 63, 2854, 'لَّا تَجْعَلُوا۟ دُعَآءَ ٱلرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم بَعْضًۭا ۚ قَدْ يَعْلَمُ ٱللَّهُ ٱلَّذِينَ يَتَسَلَّلُونَ مِنكُمْ لِوَاذًۭا ۚ فَلْيَحْذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِۦٓ أَن تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ', 359, 18, 143, 0),
  (24, 64, 2855, 'أَلَآ إِنَّ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ قَدْ يَعْلَمُ مَآ أَنتُمْ عَلَيْهِ وَيَوْمَ يُرْجَعُونَ إِلَيْهِ فَيُنَبِّئُهُم بِمَا عَمِلُوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ', 359, 18, 143, 0),
  (25, 1, 2856, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَارَكَ ٱلَّذِى نَزَّلَ ٱلْفُرْقَانَ عَلَىٰ عَبْدِهِۦ لِيَكُونَ لِلْعَٰلَمِينَ نَذِيرًا', 359, 18, 144, 0),
  (25, 2, 2857, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَمْ يَتَّخِذْ وَلَدًۭا وَلَمْ يَكُن لَّهُۥ شَرِيكٌۭ فِى ٱلْمُلْكِ وَخَلَقَ كُلَّ شَىْءٍۢ فَقَدَّرَهُۥ تَقْدِيرًۭا', 359, 18, 144, 0),
  (25, 3, 2858, 'وَٱتَّخَذُوا۟ مِن دُونِهِۦٓ ءَالِهَةًۭ لَّا يَخْلُقُونَ شَيْـًۭٔا وَهُمْ يُخْلَقُونَ وَلَا يَمْلِكُونَ لِأَنفُسِهِمْ ضَرًّۭا وَلَا نَفْعًۭا وَلَا يَمْلِكُونَ مَوْتًۭا وَلَا حَيَوٰةًۭ وَلَا نُشُورًۭا', 360, 18, 144, 0),
  (25, 4, 2859, 'وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَٰذَآ إِلَّآ إِفْكٌ ٱفْتَرَىٰهُ وَأَعَانَهُۥ عَلَيْهِ قَوْمٌ ءَاخَرُونَ ۖ فَقَدْ جَآءُو ظُلْمًۭا وَزُورًۭا', 360, 18, 144, 0),
  (25, 5, 2860, 'وَقَالُوٓا۟ أَسَٰطِيرُ ٱلْأَوَّلِينَ ٱكْتَتَبَهَا فَهِىَ تُمْلَىٰ عَلَيْهِ بُكْرَةًۭ وَأَصِيلًۭا', 360, 18, 144, 0),
  (25, 6, 2861, 'قُلْ أَنزَلَهُ ٱلَّذِى يَعْلَمُ ٱلسِّرَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ إِنَّهُۥ كَانَ غَفُورًۭا رَّحِيمًۭا', 360, 18, 144, 0),
  (25, 7, 2862, 'وَقَالُوا۟ مَالِ هَٰذَا ٱلرَّسُولِ يَأْكُلُ ٱلطَّعَامَ وَيَمْشِى فِى ٱلْأَسْوَاقِ ۙ لَوْلَآ أُنزِلَ إِلَيْهِ مَلَكٌۭ فَيَكُونَ مَعَهُۥ نَذِيرًا', 360, 18, 144, 0),
  (25, 8, 2863, 'أَوْ يُلْقَىٰٓ إِلَيْهِ كَنزٌ أَوْ تَكُونُ لَهُۥ جَنَّةٌۭ يَأْكُلُ مِنْهَا ۚ وَقَالَ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلًۭا مَّسْحُورًا', 360, 18, 144, 0),
  (25, 9, 2864, 'ٱنظُرْ كَيْفَ ضَرَبُوا۟ لَكَ ٱلْأَمْثَٰلَ فَضَلُّوا۟ فَلَا يَسْتَطِيعُونَ سَبِيلًۭا', 360, 18, 144, 0),
  (25, 10, 2865, 'تَبَارَكَ ٱلَّذِىٓ إِن شَآءَ جَعَلَ لَكَ خَيْرًۭا مِّن ذَٰلِكَ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَيَجْعَل لَّكَ قُصُورًۢا', 360, 18, 144, 0),
  (25, 11, 2866, 'بَلْ كَذَّبُوا۟ بِٱلسَّاعَةِ ۖ وَأَعْتَدْنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا', 360, 18, 144, 0),
  (25, 12, 2867, 'إِذَا رَأَتْهُم مِّن مَّكَانٍۭ بَعِيدٍۢ سَمِعُوا۟ لَهَا تَغَيُّظًۭا وَزَفِيرًۭا', 361, 18, 144, 0),
  (25, 13, 2868, 'وَإِذَآ أُلْقُوا۟ مِنْهَا مَكَانًۭا ضَيِّقًۭا مُّقَرَّنِينَ دَعَوْا۟ هُنَالِكَ ثُبُورًۭا', 361, 18, 144, 0),
  (25, 14, 2869, 'لَّا تَدْعُوا۟ ٱلْيَوْمَ ثُبُورًۭا وَٰحِدًۭا وَٱدْعُوا۟ ثُبُورًۭا كَثِيرًۭا', 361, 18, 144, 0),
  (25, 15, 2870, 'قُلْ أَذَٰلِكَ خَيْرٌ أَمْ جَنَّةُ ٱلْخُلْدِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۚ كَانَتْ لَهُمْ جَزَآءًۭ وَمَصِيرًۭا', 361, 18, 144, 0),
  (25, 16, 2871, 'لَّهُمْ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَ ۚ كَانَ عَلَىٰ رَبِّكَ وَعْدًۭا مَّسْـُٔولًۭا', 361, 18, 144, 0),
  (25, 17, 2872, 'وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمْ أَضْلَلْتُمْ عِبَادِى هَٰٓؤُلَآءِ أَمْ هُمْ ضَلُّوا۟ ٱلسَّبِيلَ', 361, 18, 144, 0),
  (25, 18, 2873, 'قَالُوا۟ سُبْحَٰنَكَ مَا كَانَ يَنۢبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ وَلَٰكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ حَتَّىٰ نَسُوا۟ ٱلذِّكْرَ وَكَانُوا۟ قَوْمًۢا بُورًۭا', 361, 18, 144, 0),
  (25, 19, 2874, 'فَقَدْ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسْتَطِيعُونَ صَرْفًۭا وَلَا نَصْرًۭا ۚ وَمَن يَظْلِم مِّنكُمْ نُذِقْهُ عَذَابًۭا كَبِيرًۭا', 361, 18, 144, 0),
  (25, 20, 2875, 'وَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ ٱلْمُرْسَلِينَ إِلَّآ إِنَّهُمْ لَيَأْكُلُونَ ٱلطَّعَامَ وَيَمْشُونَ فِى ٱلْأَسْوَاقِ ۗ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍۢ فِتْنَةً أَتَصْبِرُونَ ۗ وَكَانَ رَبُّكَ بَصِيرًۭا', 361, 18, 144, 0),
  (25, 21, 2876, '۞ وَقَالَ ٱلَّذِينَ لَا يَرْجُونَ لِقَآءَنَا لَوْلَآ أُنزِلَ عَلَيْنَا ٱلْمَلَٰٓئِكَةُ أَوْ نَرَىٰ رَبَّنَا ۗ لَقَدِ ٱسْتَكْبَرُوا۟ فِىٓ أَنفُسِهِمْ وَعَتَوْ عُتُوًّۭا كَبِيرًۭا', 362, 19, 145, 0),
  (25, 22, 2877, 'يَوْمَ يَرَوْنَ ٱلْمَلَٰٓئِكَةَ لَا بُشْرَىٰ يَوْمَئِذٍۢ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْرًۭا مَّحْجُورًۭا', 362, 19, 145, 0),
  (25, 23, 2878, 'وَقَدِمْنَآ إِلَىٰ مَا عَمِلُوا۟ مِنْ عَمَلٍۢ فَجَعَلْنَٰهُ هَبَآءًۭ مَّنثُورًا', 362, 19, 145, 0),
  (25, 24, 2879, 'أَصْحَٰبُ ٱلْجَنَّةِ يَوْمَئِذٍ خَيْرٌۭ مُّسْتَقَرًّۭا وَأَحْسَنُ مَقِيلًۭا', 362, 19, 145, 0),
  (25, 25, 2880, 'وَيَوْمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلْغَمَٰمِ وَنُزِّلَ ٱلْمَلَٰٓئِكَةُ تَنزِيلًا', 362, 19, 145, 0),
  (25, 26, 2881, 'ٱلْمُلْكُ يَوْمَئِذٍ ٱلْحَقُّ لِلرَّحْمَٰنِ ۚ وَكَانَ يَوْمًا عَلَى ٱلْكَٰفِرِينَ عَسِيرًۭا', 362, 19, 145, 0),
  (25, 27, 2882, 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَٰلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًۭا', 362, 19, 145, 0),
  (25, 28, 2883, 'يَٰوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًۭا', 362, 19, 145, 0),
  (25, 29, 2884, 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى ۗ وَكَانَ ٱلشَّيْطَٰنُ لِلْإِنسَٰنِ خَذُولًۭا', 362, 19, 145, 0),
  (25, 30, 2885, 'وَقَالَ ٱلرَّسُولُ يَٰرَبِّ إِنَّ قَوْمِى ٱتَّخَذُوا۟ هَٰذَا ٱلْقُرْءَانَ مَهْجُورًۭا', 362, 19, 145, 0),
  (25, 31, 2886, 'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّۭا مِّنَ ٱلْمُجْرِمِينَ ۗ وَكَفَىٰ بِرَبِّكَ هَادِيًۭا وَنَصِيرًۭا', 362, 19, 145, 0),
  (25, 32, 2887, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ٱلْقُرْءَانُ جُمْلَةًۭ وَٰحِدَةًۭ ۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَ ۖ وَرَتَّلْنَٰهُ تَرْتِيلًۭا', 362, 19, 145, 0),
  (25, 33, 2888, 'وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَٰكَ بِٱلْحَقِّ وَأَحْسَنَ تَفْسِيرًا', 363, 19, 145, 0),
  (25, 34, 2889, 'ٱلَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُو۟لَٰٓئِكَ شَرٌّۭ مَّكَانًۭا وَأَضَلُّ سَبِيلًۭا', 363, 19, 145, 0),
  (25, 35, 2890, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرًۭا', 363, 19, 145, 0),
  (25, 36, 2891, 'فَقُلْنَا ٱذْهَبَآ إِلَى ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَدَمَّرْنَٰهُمْ تَدْمِيرًۭا', 363, 19, 145, 0),
  (25, 37, 2892, 'وَقَوْمَ نُوحٍۢ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغْرَقْنَٰهُمْ وَجَعَلْنَٰهُمْ لِلنَّاسِ ءَايَةًۭ ۖ وَأَعْتَدْنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمًۭا', 363, 19, 145, 0),
  (25, 38, 2893, 'وَعَادًۭا وَثَمُودَا۟ وَأَصْحَٰبَ ٱلرَّسِّ وَقُرُونًۢا بَيْنَ ذَٰلِكَ كَثِيرًۭا', 363, 19, 145, 0),
  (25, 39, 2894, 'وَكُلًّۭا ضَرَبْنَا لَهُ ٱلْأَمْثَٰلَ ۖ وَكُلًّۭا تَبَّرْنَا تَتْبِيرًۭا', 363, 19, 145, 0),
  (25, 40, 2895, 'وَلَقَدْ أَتَوْا۟ عَلَى ٱلْقَرْيَةِ ٱلَّتِىٓ أُمْطِرَتْ مَطَرَ ٱلسَّوْءِ ۚ أَفَلَمْ يَكُونُوا۟ يَرَوْنَهَا ۚ بَلْ كَانُوا۟ لَا يَرْجُونَ نُشُورًۭا', 363, 19, 145, 0),
  (25, 41, 2896, 'وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِى بَعَثَ ٱللَّهُ رَسُولًا', 363, 19, 145, 0),
  (25, 42, 2897, 'إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلَآ أَن صَبَرْنَا عَلَيْهَا ۚ وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ ٱلْعَذَابَ مَنْ أَضَلُّ سَبِيلًا', 363, 19, 145, 0),
  (25, 43, 2898, 'أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', 363, 19, 145, 0),
  (25, 44, 2899, 'أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ ۚ إِنْ هُمْ إِلَّا كَٱلْأَنْعَٰمِ ۖ بَلْ هُمْ أَضَلُّ سَبِيلًا', 364, 19, 145, 0),
  (25, 45, 2900, 'أَلَمْ تَرَ إِلَىٰ رَبِّكَ كَيْفَ مَدَّ ٱلظِّلَّ وَلَوْ شَآءَ لَجَعَلَهُۥ سَاكِنًۭا ثُمَّ جَعَلْنَا ٱلشَّمْسَ عَلَيْهِ دَلِيلًۭا', 364, 19, 145, 0),
  (25, 46, 2901, 'ثُمَّ قَبَضْنَٰهُ إِلَيْنَا قَبْضًۭا يَسِيرًۭا', 364, 19, 145, 0),
  (25, 47, 2902, 'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِبَاسًۭا وَٱلنَّوْمَ سُبَاتًۭا وَجَعَلَ ٱلنَّهَارَ نُشُورًۭا', 364, 19, 145, 0),
  (25, 48, 2903, 'وَهُوَ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۚ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ طَهُورًۭا', 364, 19, 145, 0),
  (25, 49, 2904, 'لِّنُحْۦِىَ بِهِۦ بَلْدَةًۭ مَّيْتًۭا وَنُسْقِيَهُۥ مِمَّا خَلَقْنَآ أَنْعَٰمًۭا وَأَنَاسِىَّ كَثِيرًۭا', 364, 19, 145, 0),
  (25, 50, 2905, 'وَلَقَدْ صَرَّفْنَٰهُ بَيْنَهُمْ لِيَذَّكَّرُوا۟ فَأَبَىٰٓ أَكْثَرُ ٱلنَّاسِ إِلَّا كُفُورًۭا', 364, 19, 145, 0),
  (25, 51, 2906, 'وَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍۢ نَّذِيرًۭا', 364, 19, 145, 0),
  (25, 52, 2907, 'فَلَا تُطِعِ ٱلْكَٰفِرِينَ وَجَٰهِدْهُم بِهِۦ جِهَادًۭا كَبِيرًۭا', 364, 19, 145, 0),
  (25, 53, 2908, '۞ وَهُوَ ٱلَّذِى مَرَجَ ٱلْبَحْرَيْنِ هَٰذَا عَذْبٌۭ فُرَاتٌۭ وَهَٰذَا مِلْحٌ أُجَاجٌۭ وَجَعَلَ بَيْنَهُمَا بَرْزَخًۭا وَحِجْرًۭا مَّحْجُورًۭا', 364, 19, 146, 0),
  (25, 54, 2909, 'وَهُوَ ٱلَّذِى خَلَقَ مِنَ ٱلْمَآءِ بَشَرًۭا فَجَعَلَهُۥ نَسَبًۭا وَصِهْرًۭا ۗ وَكَانَ رَبُّكَ قَدِيرًۭا', 364, 19, 146, 0),
  (25, 55, 2910, 'وَيَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُهُمْ وَلَا يَضُرُّهُمْ ۗ وَكَانَ ٱلْكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرًۭا', 364, 19, 146, 0),
  (25, 56, 2911, 'وَمَآ أَرْسَلْنَٰكَ إِلَّا مُبَشِّرًۭا وَنَذِيرًۭا', 365, 19, 146, 0),
  (25, 57, 2912, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلًۭا', 365, 19, 146, 0),
  (25, 58, 2913, 'وَتَوَكَّلْ عَلَى ٱلْحَىِّ ٱلَّذِى لَا يَمُوتُ وَسَبِّحْ بِحَمْدِهِۦ ۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِيرًا', 365, 19, 146, 0),
  (25, 59, 2914, 'ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ ٱلرَّحْمَٰنُ فَسْـَٔلْ بِهِۦ خَبِيرًۭا', 365, 19, 146, 0),
  (25, 60, 2915, 'وَإِذَا قِيلَ لَهُمُ ٱسْجُدُوا۟ لِلرَّحْمَٰنِ قَالُوا۟ وَمَا ٱلرَّحْمَٰنُ أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًۭا ۩', 365, 19, 146, 1),
  (25, 61, 2916, 'تَبَارَكَ ٱلَّذِى جَعَلَ فِى ٱلسَّمَآءِ بُرُوجًۭا وَجَعَلَ فِيهَا سِرَٰجًۭا وَقَمَرًۭا مُّنِيرًۭا', 365, 19, 146, 0),
  (25, 62, 2917, 'وَهُوَ ٱلَّذِى جَعَلَ ٱلَّيْلَ وَٱلنَّهَارَ خِلْفَةًۭ لِّمَنْ أَرَادَ أَن يَذَّكَّرَ أَوْ أَرَادَ شُكُورًۭا', 365, 19, 146, 0),
  (25, 63, 2918, 'وَعِبَادُ ٱلرَّحْمَٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًۭا وَإِذَا خَاطَبَهُمُ ٱلْجَٰهِلُونَ قَالُوا۟ سَلَٰمًۭا', 365, 19, 146, 0),
  (25, 64, 2919, 'وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًۭا وَقِيَٰمًۭا', 365, 19, 146, 0),
  (25, 65, 2920, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 365, 19, 146, 0),
  (25, 66, 2921, 'إِنَّهَا سَآءَتْ مُسْتَقَرًّۭا وَمُقَامًۭا', 365, 19, 146, 0),
  (25, 67, 2922, 'وَٱلَّذِينَ إِذَآ أَنفَقُوا۟ لَمْ يُسْرِفُوا۟ وَلَمْ يَقْتُرُوا۟ وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًۭا', 365, 19, 146, 0),
  (25, 68, 2923, 'وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ وَلَا يَزْنُونَ ۚ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًۭا', 366, 19, 146, 0),
  (25, 69, 2924, 'يُضَٰعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَٰمَةِ وَيَخْلُدْ فِيهِۦ مُهَانًا', 366, 19, 146, 0),
  (25, 70, 2925, 'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًۭا صَٰلِحًۭا فَأُو۟لَٰٓئِكَ يُبَدِّلُ ٱللَّهُ سَيِّـَٔاتِهِمْ حَسَنَٰتٍۢ ۗ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 366, 19, 146, 0),
  (25, 71, 2926, 'وَمَن تَابَ وَعَمِلَ صَٰلِحًۭا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابًۭا', 366, 19, 146, 0),
  (25, 72, 2927, 'وَٱلَّذِينَ لَا يَشْهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغْوِ مَرُّوا۟ كِرَامًۭا', 366, 19, 146, 0),
  (25, 73, 2928, 'وَٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَمْ يَخِرُّوا۟ عَلَيْهَا صُمًّۭا وَعُمْيَانًۭا', 366, 19, 146, 0),
  (25, 74, 2929, 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعْيُنٍۢ وَٱجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 366, 19, 146, 0),
  (25, 75, 2930, 'أُو۟لَٰٓئِكَ يُجْزَوْنَ ٱلْغُرْفَةَ بِمَا صَبَرُوا۟ وَيُلَقَّوْنَ فِيهَا تَحِيَّةًۭ وَسَلَٰمًا', 366, 19, 146, 0),
  (25, 76, 2931, 'خَٰلِدِينَ فِيهَا ۚ حَسُنَتْ مُسْتَقَرًّۭا وَمُقَامًۭا', 366, 19, 146, 0),
  (25, 77, 2932, 'قُلْ مَا يَعْبَؤُا۟ بِكُمْ رَبِّى لَوْلَا دُعَآؤُكُمْ ۖ فَقَدْ كَذَّبْتُمْ فَسَوْفَ يَكُونُ لِزَامًۢا', 366, 19, 146, 0),
  (26, 1, 2933, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ طسٓمٓ', 367, 19, 147, 0),
  (26, 2, 2934, 'تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ', 367, 19, 147, 0),
  (26, 3, 2935, 'لَعَلَّكَ بَٰخِعٌۭ نَّفْسَكَ أَلَّا يَكُونُوا۟ مُؤْمِنِينَ', 367, 19, 147, 0),
  (26, 4, 2936, 'إِن نَّشَأْ نُنَزِّلْ عَلَيْهِم مِّنَ ٱلسَّمَآءِ ءَايَةًۭ فَظَلَّتْ أَعْنَٰقُهُمْ لَهَا خَٰضِعِينَ', 367, 19, 147, 0),
  (26, 5, 2937, 'وَمَا يَأْتِيهِم مِّن ذِكْرٍۢ مِّنَ ٱلرَّحْمَٰنِ مُحْدَثٍ إِلَّا كَانُوا۟ عَنْهُ مُعْرِضِينَ', 367, 19, 147, 0),
  (26, 6, 2938, 'فَقَدْ كَذَّبُوا۟ فَسَيَأْتِيهِمْ أَنۢبَٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 367, 19, 147, 0),
  (26, 7, 2939, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلْأَرْضِ كَمْ أَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۢ كَرِيمٍ', 367, 19, 147, 0),
  (26, 8, 2940, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 367, 19, 147, 0),
  (26, 9, 2941, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 367, 19, 147, 0),
  (26, 10, 2942, 'وَإِذْ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئْتِ ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 367, 19, 147, 0),
  (26, 11, 2943, 'قَوْمَ فِرْعَوْنَ ۚ أَلَا يَتَّقُونَ', 367, 19, 147, 0),
  (26, 12, 2944, 'قَالَ رَبِّ إِنِّىٓ أَخَافُ أَن يُكَذِّبُونِ', 367, 19, 147, 0),
  (26, 13, 2945, 'وَيَضِيقُ صَدْرِى وَلَا يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَىٰ هَٰرُونَ', 367, 19, 147, 0),
  (26, 14, 2946, 'وَلَهُمْ عَلَىَّ ذَنۢبٌۭ فَأَخَافُ أَن يَقْتُلُونِ', 367, 19, 147, 0),
  (26, 15, 2947, 'قَالَ كَلَّا ۖ فَٱذْهَبَا بِـَٔايَٰتِنَآ ۖ إِنَّا مَعَكُم مُّسْتَمِعُونَ', 367, 19, 147, 0),
  (26, 16, 2948, 'فَأْتِيَا فِرْعَوْنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', 367, 19, 147, 0),
  (26, 17, 2949, 'أَنْ أَرْسِلْ مَعَنَا بَنِىٓ إِسْرَٰٓءِيلَ', 367, 19, 147, 0),
  (26, 18, 2950, 'قَالَ أَلَمْ نُرَبِّكَ فِينَا وَلِيدًۭا وَلَبِثْتَ فِينَا مِنْ عُمُرِكَ سِنِينَ', 367, 19, 147, 0),
  (26, 19, 2951, 'وَفَعَلْتَ فَعْلَتَكَ ٱلَّتِى فَعَلْتَ وَأَنتَ مِنَ ٱلْكَٰفِرِينَ', 367, 19, 147, 0),
  (26, 20, 2952, 'قَالَ فَعَلْتُهَآ إِذًۭا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ', 368, 19, 147, 0),
  (26, 21, 2953, 'فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْمًۭا وَجَعَلَنِى مِنَ ٱلْمُرْسَلِينَ', 368, 19, 147, 0),
  (26, 22, 2954, 'وَتِلْكَ نِعْمَةٌۭ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِىٓ إِسْرَٰٓءِيلَ', 368, 19, 147, 0),
  (26, 23, 2955, 'قَالَ فِرْعَوْنُ وَمَا رَبُّ ٱلْعَٰلَمِينَ', 368, 19, 147, 0),
  (26, 24, 2956, 'قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ', 368, 19, 147, 0),
  (26, 25, 2957, 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَ', 368, 19, 147, 0),
  (26, 26, 2958, 'قَالَ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 368, 19, 147, 0),
  (26, 27, 2959, 'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِىٓ أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌۭ', 368, 19, 147, 0),
  (26, 28, 2960, 'قَالَ رَبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُمْ تَعْقِلُونَ', 368, 19, 147, 0),
  (26, 29, 2961, 'قَالَ لَئِنِ ٱتَّخَذْتَ إِلَٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ ٱلْمَسْجُونِينَ', 368, 19, 147, 0),
  (26, 30, 2962, 'قَالَ أَوَلَوْ جِئْتُكَ بِشَىْءٍۢ مُّبِينٍۢ', 368, 19, 147, 0),
  (26, 31, 2963, 'قَالَ فَأْتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 368, 19, 147, 0),
  (26, 32, 2964, 'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌۭ مُّبِينٌۭ', 368, 19, 147, 0),
  (26, 33, 2965, 'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ', 368, 19, 147, 0),
  (26, 34, 2966, 'قَالَ لِلْمَلَإِ حَوْلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌۭ', 368, 19, 147, 0),
  (26, 35, 2967, 'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُم بِسِحْرِهِۦ فَمَاذَا تَأْمُرُونَ', 368, 19, 147, 0),
  (26, 36, 2968, 'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَٱبْعَثْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 368, 19, 147, 0),
  (26, 37, 2969, 'يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍۢ', 368, 19, 147, 0),
  (26, 38, 2970, 'فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوْمٍۢ مَّعْلُومٍۢ', 368, 19, 147, 0),
  (26, 39, 2971, 'وَقِيلَ لِلنَّاسِ هَلْ أَنتُم مُّجْتَمِعُونَ', 368, 19, 147, 0),
  (26, 40, 2972, 'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 369, 19, 147, 0),
  (26, 41, 2973, 'فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ', 369, 19, 147, 0),
  (26, 42, 2974, 'قَالَ نَعَمْ وَإِنَّكُمْ إِذًۭا لَّمِنَ ٱلْمُقَرَّبِينَ', 369, 19, 147, 0),
  (26, 43, 2975, 'قَالَ لَهُم مُّوسَىٰٓ أَلْقُوا۟ مَآ أَنتُم مُّلْقُونَ', 369, 19, 147, 0),
  (26, 44, 2976, 'فَأَلْقَوْا۟ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُوا۟ بِعِزَّةِ فِرْعَوْنَ إِنَّا لَنَحْنُ ٱلْغَٰلِبُونَ', 369, 19, 147, 0),
  (26, 45, 2977, 'فَأَلْقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ', 369, 19, 147, 0),
  (26, 46, 2978, 'فَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ', 369, 19, 147, 0),
  (26, 47, 2979, 'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ', 369, 19, 147, 0),
  (26, 48, 2980, 'رَبِّ مُوسَىٰ وَهَٰرُونَ', 369, 19, 147, 0),
  (26, 49, 2981, 'قَالَ ءَامَنتُمْ لَهُۥ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِى عَلَّمَكُمُ ٱلسِّحْرَ فَلَسَوْفَ تَعْلَمُونَ ۚ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍۢ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ', 369, 19, 147, 0),
  (26, 50, 2982, 'قَالُوا۟ لَا ضَيْرَ ۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ', 369, 19, 147, 0),
  (26, 51, 2983, 'إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلْمُؤْمِنِينَ', 369, 19, 147, 0),
  (26, 52, 2984, '۞ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَسْرِ بِعِبَادِىٓ إِنَّكُم مُّتَّبَعُونَ', 369, 19, 148, 0),
  (26, 53, 2985, 'فَأَرْسَلَ فِرْعَوْنُ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ', 369, 19, 148, 0),
  (26, 54, 2986, 'إِنَّ هَٰٓؤُلَآءِ لَشِرْذِمَةٌۭ قَلِيلُونَ', 369, 19, 148, 0),
  (26, 55, 2987, 'وَإِنَّهُمْ لَنَا لَغَآئِظُونَ', 369, 19, 148, 0),
  (26, 56, 2988, 'وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ', 369, 19, 148, 0),
  (26, 57, 2989, 'فَأَخْرَجْنَٰهُم مِّن جَنَّٰتٍۢ وَعُيُونٍۢ', 369, 19, 148, 0),
  (26, 58, 2990, 'وَكُنُوزٍۢ وَمَقَامٍۢ كَرِيمٍۢ', 369, 19, 148, 0),
  (26, 59, 2991, 'كَذَٰلِكَ وَأَوْرَثْنَٰهَا بَنِىٓ إِسْرَٰٓءِيلَ', 369, 19, 148, 0),
  (26, 60, 2992, 'فَأَتْبَعُوهُم مُّشْرِقِينَ', 369, 19, 148, 0),
  (26, 61, 2993, 'فَلَمَّا تَرَٰٓءَا ٱلْجَمْعَانِ قَالَ أَصْحَٰبُ مُوسَىٰٓ إِنَّا لَمُدْرَكُونَ', 370, 19, 148, 0),
  (26, 62, 2994, 'قَالَ كَلَّآ ۖ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ', 370, 19, 148, 0),
  (26, 63, 2995, 'فَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْبَحْرَ ۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرْقٍۢ كَٱلطَّوْدِ ٱلْعَظِيمِ', 370, 19, 148, 0),
  (26, 64, 2996, 'وَأَزْلَفْنَا ثَمَّ ٱلْءَاخَرِينَ', 370, 19, 148, 0),
  (26, 65, 2997, 'وَأَنجَيْنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجْمَعِينَ', 370, 19, 148, 0),
  (26, 66, 2998, 'ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ', 370, 19, 148, 0),
  (26, 67, 2999, 'إِنَّ فِى ذَٰلِكَ لَءَايَةًۭ ۖ وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ', 370, 19, 148, 0),
  (26, 68, 3000, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 370, 19, 148, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 26, 1, 'Ta, Seen, Meem.'),
  ('en.sahih', 26, 2, 'These are the verses of the clear Book.'),
  ('en.sahih', 26, 3, 'Perhaps, [O Muhammad], you would kill yourself with grief that they will not be believers.'),
  ('en.sahih', 26, 4, 'If We willed, We could send down to them from the sky a sign for which their necks would remain humbled.'),
  ('en.sahih', 26, 5, 'And no revelation comes to them anew from the Most Merciful except that they turn away from it.'),
  ('en.sahih', 26, 6, 'For they have already denied, but there will come to them the news of that which they used to ridicule.'),
  ('en.sahih', 26, 7, 'Did they not look at the earth - how much We have produced therein from every noble kind?'),
  ('en.sahih', 26, 8, 'Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 9, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 10, 'And [mention] when your Lord called Moses, [saying], "Go to the wrongdoing people -'),
  ('en.sahih', 26, 11, 'The people of Pharaoh. Will they not fear Allah?"'),
  ('en.sahih', 26, 12, 'He said, "My Lord, indeed I fear that they will deny me'),
  ('en.sahih', 26, 13, 'And that my breast will tighten and my tongue will not be fluent, so send for Aaron.'),
  ('en.sahih', 26, 14, 'And they have upon me a [claim due to] sin, so I fear that they will kill me."'),
  ('en.sahih', 26, 15, '[Allah] said, "No. Go both of you with Our signs; indeed, We are with you, listening.'),
  ('en.sahih', 26, 16, 'Go to Pharaoh and say, \'We are the messengers of the Lord of the worlds,'),
  ('en.sahih', 26, 17, '[Commanded to say], "Send with us the Children of Israel."\'"'),
  ('en.sahih', 26, 18, '[Pharaoh] said, "Did we not raise you among us as a child, and you remained among us for years of your life?'),
  ('en.sahih', 26, 19, 'And [then] you did your deed which you did, and you were of the ungrateful."'),
  ('en.sahih', 26, 20, '[Moses] said, "I did it, then, while I was of those astray.'),
  ('en.sahih', 26, 21, 'So I fled from you when I feared you. Then my Lord granted me wisdom and prophethood and appointed me [as one] of the messengers.'),
  ('en.sahih', 26, 22, 'And is this a favor of which you remind me - that you have enslaved the Children of Israel?"'),
  ('en.sahih', 26, 23, 'Said Pharaoh, "And what is the Lord of the worlds?"'),
  ('en.sahih', 26, 24, '[Moses] said, "The Lord of the heavens and earth and that between them, if you should be convinced."'),
  ('en.sahih', 26, 25, '[Pharaoh] said to those around him, "Do you not hear?"'),
  ('en.sahih', 26, 26, '[Moses] said, "Your Lord and the Lord of your first forefathers."'),
  ('en.sahih', 26, 27, '[Pharaoh] said, "Indeed, your \'messenger\' who has been sent to you is mad."'),
  ('en.sahih', 26, 28, '[Moses] said, "Lord of the east and the west and that between them, if you were to reason."'),
  ('en.sahih', 26, 29, '[Pharaoh] said, "If you take a god other than me, I will surely place you among those imprisoned."'),
  ('en.sahih', 26, 30, '[Moses] said, "Even if I brought you proof manifest?"'),
  ('en.sahih', 26, 31, '[Pharaoh] said, "Then bring it, if you should be of the truthful."'),
  ('en.sahih', 26, 32, 'So [Moses] threw his staff, and suddenly it was a serpent manifest.'),
  ('en.sahih', 26, 33, 'And he drew out his hand; thereupon it was white for the observers.'),
  ('en.sahih', 26, 34, '[Pharaoh] said to the eminent ones around him, "Indeed, this is a learned magician.'),
  ('en.sahih', 26, 35, 'He wants to drive you out of your land by his magic, so what do you advise?"'),
  ('en.sahih', 26, 36, 'They said, "Postpone [the matter of] him and his brother and send among the cities gatherers'),
  ('en.sahih', 26, 37, 'Who will bring you every learned, skilled magician."'),
  ('en.sahih', 26, 38, 'So the magicians were assembled for the appointment of a well-known day.'),
  ('en.sahih', 26, 39, 'And it was said to the people, "Will you congregate'),
  ('en.sahih', 26, 40, 'That we might follow the magicians if they are the predominant?"'),
  ('en.sahih', 26, 41, 'And when the magicians arrived, they said to Pharaoh, "Is there indeed for us a reward if we are the predominant?"'),
  ('en.sahih', 26, 42, 'He said, "Yes, and indeed, you will then be of those near [to me]."'),
  ('en.sahih', 26, 43, 'Moses said to them, "Throw whatever you will throw."'),
  ('en.sahih', 26, 44, 'So they threw their ropes and their staffs and said, "By the might of Pharaoh, indeed it is we who are predominant."'),
  ('en.sahih', 26, 45, 'Then Moses threw his staff, and at once it devoured what they falsified.'),
  ('en.sahih', 26, 46, 'So the magicians fell down in prostration [to Allah].'),
  ('en.sahih', 26, 47, 'They said, "We have believed in the Lord of the worlds,'),
  ('en.sahih', 26, 48, 'The Lord of Moses and Aaron."'),
  ('en.sahih', 26, 49, '[Pharaoh] said, "You believed Moses before I gave you permission. Indeed, he is your leader who has taught you magic, but you are going to know. I will surely cut off your hands and your feet on opposite sides, and I will surely crucify you all."'),
  ('en.sahih', 26, 50, 'They said, "No harm. Indeed, to our Lord we will return.'),
  ('en.sahih', 26, 51, 'Indeed, we aspire that our Lord will forgive us our sins because we were the first of the believers."'),
  ('en.sahih', 26, 52, 'And We inspired to Moses, "Travel by night with My servants; indeed, you will be pursued."'),
  ('en.sahih', 26, 53, 'Then Pharaoh sent among the cities gatherers'),
  ('en.sahih', 26, 54, '[And said], "Indeed, those are but a small band,'),
  ('en.sahih', 26, 55, 'And indeed, they are enraging us,'),
  ('en.sahih', 26, 56, 'And indeed, we are a cautious society... "'),
  ('en.sahih', 26, 57, 'So We removed them from gardens and springs'),
  ('en.sahih', 26, 58, 'And treasures and honorable station -'),
  ('en.sahih', 26, 59, 'Thus. And We caused to inherit it the Children of Israel.'),
  ('en.sahih', 26, 60, 'So they pursued them at sunrise.'),
  ('en.sahih', 26, 61, 'And when the two companies saw one another, the companions of Moses said, "Indeed, we are to be overtaken!"'),
  ('en.sahih', 26, 62, '[Moses] said, "No! Indeed, with me is my Lord; He will guide me."'),
  ('en.sahih', 26, 63, 'Then We inspired to Moses, "Strike with your staff the sea," and it parted, and each portion was like a great towering mountain.'),
  ('en.sahih', 26, 64, 'And We advanced thereto the pursuers.'),
  ('en.sahih', 26, 65, 'And We saved Moses and those with him, all together.'),
  ('en.sahih', 26, 66, 'Then We drowned the others.'),
  ('en.sahih', 26, 67, 'Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 68, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 69, 'And recite to them the news of Abraham,'),
  ('en.sahih', 26, 70, 'When he said to his father and his people, "What do you worship?"'),
  ('en.sahih', 26, 71, 'They said, "We worship idols and remain to them devoted."'),
  ('en.sahih', 26, 72, 'He said, "Do they hear you when you supplicate?'),
  ('en.sahih', 26, 73, 'Or do they benefit you, or do they harm?"'),
  ('en.sahih', 26, 74, 'They said, "But we found our fathers doing thus."'),
  ('en.sahih', 26, 75, 'He said, "Then do you see what you have been worshipping,'),
  ('en.sahih', 26, 76, 'You and your ancient forefathers?'),
  ('en.sahih', 26, 77, 'Indeed, they are enemies to me, except the Lord of the worlds,'),
  ('en.sahih', 26, 78, 'Who created me, and He [it is who] guides me.'),
  ('en.sahih', 26, 79, 'And it is He who feeds me and gives me drink.'),
  ('en.sahih', 26, 80, 'And when I am ill, it is He who cures me'),
  ('en.sahih', 26, 81, 'And who will cause me to die and then bring me to life'),
  ('en.sahih', 26, 82, 'And who I aspire that He will forgive me my sin on the Day of Recompense."'),
  ('en.sahih', 26, 83, '[And he said], "My Lord, grant me authority and join me with the righteous.'),
  ('en.sahih', 26, 84, 'And grant me a reputation of honor among later generations.'),
  ('en.sahih', 26, 85, 'And place me among the inheritors of the Garden of Pleasure.'),
  ('en.sahih', 26, 86, 'And forgive my father. Indeed, he has been of those astray.'),
  ('en.sahih', 26, 87, 'And do not disgrace me on the Day they are [all] resurrected -'),
  ('en.sahih', 26, 88, 'The Day when there will not benefit [anyone] wealth or children'),
  ('en.sahih', 26, 89, 'But only one who comes to Allah with a sound heart."'),
  ('en.sahih', 26, 90, 'And Paradise will be brought near [that Day] to the righteous.'),
  ('en.sahih', 26, 91, 'And Hellfire will be brought forth for the deviators,'),
  ('en.sahih', 26, 92, 'And it will be said to them, "Where are those you used to worship'),
  ('en.sahih', 26, 93, 'Other than Allah? Can they help you or help themselves?"'),
  ('en.sahih', 26, 94, 'So they will be overturned into Hellfire, they and the deviators'),
  ('en.sahih', 26, 95, 'And the soldiers of Iblees, all together.'),
  ('en.sahih', 26, 96, 'They will say while they dispute therein,'),
  ('en.sahih', 26, 97, '"By Allah, we were indeed in manifest error'),
  ('en.sahih', 26, 98, 'When we equated you with the Lord of the worlds.'),
  ('en.sahih', 26, 99, 'And no one misguided us except the criminals.'),
  ('en.sahih', 26, 100, 'So now we have no intercessors'),
  ('en.sahih', 26, 101, 'And not a devoted friend.'),
  ('en.sahih', 26, 102, 'Then if we only had a return [to the world] and could be of the believers... "'),
  ('en.sahih', 26, 103, 'Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 104, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 105, 'The people of Noah denied the messengers'),
  ('en.sahih', 26, 106, 'When their brother Noah said to them, "Will you not fear Allah?'),
  ('en.sahih', 26, 107, 'Indeed, I am to you a trustworthy messenger.'),
  ('en.sahih', 26, 108, 'So fear Allah and obey me.'),
  ('en.sahih', 26, 109, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.'),
  ('en.sahih', 26, 110, 'So fear Allah and obey me."'),
  ('en.sahih', 26, 111, 'They said, "Should we believe you while you are followed by the lowest [class of people]?"'),
  ('en.sahih', 26, 112, 'He said, "And what is my knowledge of what they used to do?'),
  ('en.sahih', 26, 113, 'Their account is only upon my Lord, if you [could] perceive.'),
  ('en.sahih', 26, 114, 'And I am not one to drive away the believers.'),
  ('en.sahih', 26, 115, 'I am only a clear warner."'),
  ('en.sahih', 26, 116, 'They said, "If you do not desist, O Noah, you will surely be of those who are stoned."'),
  ('en.sahih', 26, 117, 'He said, "My Lord, indeed my people have denied me.'),
  ('en.sahih', 26, 118, 'Then judge between me and them with decisive judgement and save me and those with me of the believers."'),
  ('en.sahih', 26, 119, 'So We saved him and those with him in the laden ship.'),
  ('en.sahih', 26, 120, 'Then We drowned thereafter the remaining ones.'),
  ('en.sahih', 26, 121, 'Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 122, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 123, '\'Aad denied the messengers'),
  ('en.sahih', 26, 124, 'When their brother Hud said to them, "Will you not fear Allah?'),
  ('en.sahih', 26, 125, 'Indeed, I am to you a trustworthy messenger.'),
  ('en.sahih', 26, 126, 'So fear Allah and obey me.'),
  ('en.sahih', 26, 127, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.'),
  ('en.sahih', 26, 128, 'Do you construct on every elevation a sign, amusing yourselves,'),
  ('en.sahih', 26, 129, 'And take for yourselves palaces and fortresses that you might abide eternally?'),
  ('en.sahih', 26, 130, 'And when you strike, you strike as tyrants.'),
  ('en.sahih', 26, 131, 'So fear Allah and obey me.'),
  ('en.sahih', 26, 132, 'And fear He who provided you with that which you know,'),
  ('en.sahih', 26, 133, 'Provided you with grazing livestock and children'),
  ('en.sahih', 26, 134, 'And gardens and springs.'),
  ('en.sahih', 26, 135, 'Indeed, I fear for you the punishment of a terrible day."'),
  ('en.sahih', 26, 136, 'They said, "It is all the same to us whether you advise or are not of the advisors.'),
  ('en.sahih', 26, 137, 'This is not but the custom of the former peoples,'),
  ('en.sahih', 26, 138, 'And we are not to be punished."'),
  ('en.sahih', 26, 139, 'And they denied him, so We destroyed them. Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 140, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 141, 'Thamud denied the messengers'),
  ('en.sahih', 26, 142, 'When their brother Salih said to them, "Will you not fear Allah?'),
  ('en.sahih', 26, 143, 'Indeed, I am to you a trustworthy messenger.'),
  ('en.sahih', 26, 144, 'So fear Allah and obey me.'),
  ('en.sahih', 26, 145, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.'),
  ('en.sahih', 26, 146, 'Will you be left in what is here, secure [from death],'),
  ('en.sahih', 26, 147, 'Within gardens and springs'),
  ('en.sahih', 26, 148, 'And fields of crops and palm trees with softened fruit?'),
  ('en.sahih', 26, 149, 'And you carve out of the mountains, homes, with skill.'),
  ('en.sahih', 26, 150, 'So fear Allah and obey me.'),
  ('en.sahih', 26, 151, 'And do not obey the order of the transgressors,'),
  ('en.sahih', 26, 152, 'Who cause corruption in the land and do not amend."'),
  ('en.sahih', 26, 153, 'They said, "You are only of those affected by magic.'),
  ('en.sahih', 26, 154, 'You are but a man like ourselves, so bring a sign, if you should be of the truthful."'),
  ('en.sahih', 26, 155, 'He said, "This is a she-camel. For her is a [time of] drink, and for you is a [time of] drink, [each] on a known day.'),
  ('en.sahih', 26, 156, 'And do not touch her with harm, lest you be seized by the punishment of a terrible day."'),
  ('en.sahih', 26, 157, 'But they hamstrung her and so became regretful.'),
  ('en.sahih', 26, 158, 'And the punishment seized them. Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 159, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 160, 'The people of Lot denied the messengers'),
  ('en.sahih', 26, 161, 'When their brother Lot said to them, "Will you not fear Allah?'),
  ('en.sahih', 26, 162, 'Indeed, I am to you a trustworthy messenger.'),
  ('en.sahih', 26, 163, 'So fear Allah and obey me.'),
  ('en.sahih', 26, 164, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.'),
  ('en.sahih', 26, 165, 'Do you approach males among the worlds'),
  ('en.sahih', 26, 166, 'And leave what your Lord has created for you as mates? But you are a people transgressing."'),
  ('en.sahih', 26, 167, 'They said, "If you do not desist, O Lot, you will surely be of those evicted."'),
  ('en.sahih', 26, 168, 'He said, "Indeed, I am, toward your deed, of those who detest [it].'),
  ('en.sahih', 26, 169, 'My Lord, save me and my family from [the consequence of] what they do."'),
  ('en.sahih', 26, 170, 'So We saved him and his family, all,'),
  ('en.sahih', 26, 171, 'Except an old woman among those who remained behind.'),
  ('en.sahih', 26, 172, 'Then We destroyed the others.'),
  ('en.sahih', 26, 173, 'And We rained upon them a rain [of stones], and evil was the rain of those who were warned.'),
  ('en.sahih', 26, 174, 'Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 175, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 176, 'The companions of the thicket denied the messengers'),
  ('en.sahih', 26, 177, 'When Shu\'ayb said to them, "Will you not fear Allah?'),
  ('en.sahih', 26, 178, 'Indeed, I am to you a trustworthy messenger.'),
  ('en.sahih', 26, 179, 'So fear Allah and obey me.'),
  ('en.sahih', 26, 180, 'And I do not ask you for it any payment. My payment is only from the Lord of the worlds.'),
  ('en.sahih', 26, 181, 'Give full measure and do not be of those who cause loss.'),
  ('en.sahih', 26, 182, 'And weigh with an even balance.'),
  ('en.sahih', 26, 183, 'And do not deprive people of their due and do not commit abuse on earth, spreading corruption.'),
  ('en.sahih', 26, 184, 'And fear He who created you and the former creation."'),
  ('en.sahih', 26, 185, 'They said, "You are only of those affected by magic.'),
  ('en.sahih', 26, 186, 'You are but a man like ourselves, and indeed, we think you are among the liars.'),
  ('en.sahih', 26, 187, 'So cause to fall upon us fragments of the sky, if you should be of the truthful."'),
  ('en.sahih', 26, 188, 'He said, "My Lord is most knowing of what you do."'),
  ('en.sahih', 26, 189, 'And they denied him, so the punishment of the day of the black cloud seized them. Indeed, it was the punishment of a terrible day.'),
  ('en.sahih', 26, 190, 'Indeed in that is a sign, but most of them were not to be believers.'),
  ('en.sahih', 26, 191, 'And indeed, your Lord - He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 26, 192, 'And indeed, the Qur\'an is the revelation of the Lord of the worlds.'),
  ('en.sahih', 26, 193, 'The Trustworthy Spirit has brought it down'),
  ('en.sahih', 26, 194, 'Upon your heart, [O Muhammad] - that you may be of the warners -'),
  ('en.sahih', 26, 195, 'In a clear Arabic language.'),
  ('en.sahih', 26, 196, 'And indeed, it is [mentioned] in the scriptures of former peoples.'),
  ('en.sahih', 26, 197, 'And has it not been a sign to them that it is recognized by the scholars of the Children of Israel?'),
  ('en.sahih', 26, 198, 'And even if We had revealed it to one among the foreigners'),
  ('en.sahih', 26, 199, 'And he had recited it to them [perfectly], they would [still] not have been believers in it.'),
  ('en.sahih', 26, 200, 'Thus have We inserted disbelief into the hearts of the criminals.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 26, 201, 'They will not believe in it until they see the painful punishment.'),
  ('en.sahih', 26, 202, 'And it will come to them suddenly while they perceive [it] not.'),
  ('en.sahih', 26, 203, 'And they will say, "May we be reprieved?"'),
  ('en.sahih', 26, 204, 'So for Our punishment are they impatient?'),
  ('en.sahih', 26, 205, 'Then have you considered if We gave them enjoyment for years'),
  ('en.sahih', 26, 206, 'And then there came to them that which they were promised?'),
  ('en.sahih', 26, 207, 'They would not be availed by the enjoyment with which they were provided.'),
  ('en.sahih', 26, 208, 'And We did not destroy any city except that it had warners'),
  ('en.sahih', 26, 209, 'As a reminder; and never have We been unjust.'),
  ('en.sahih', 26, 210, 'And the devils have not brought the revelation down.'),
  ('en.sahih', 26, 211, 'It is not allowable for them, nor would they be able.'),
  ('en.sahih', 26, 212, 'Indeed they, from [its] hearing, are removed.'),
  ('en.sahih', 26, 213, 'So do not invoke with Allah another deity and [thus] be among the punished.'),
  ('en.sahih', 26, 214, 'And warn, [O Muhammad], your closest kindred.'),
  ('en.sahih', 26, 215, 'And lower your wing to those who follow you of the believers.'),
  ('en.sahih', 26, 216, 'And if they disobey you, then say, "Indeed, I am disassociated from what you are doing."'),
  ('en.sahih', 26, 217, 'And rely upon the Exalted in Might, the Merciful,'),
  ('en.sahih', 26, 218, 'Who sees you when you arise'),
  ('en.sahih', 26, 219, 'And your movement among those who prostrate.'),
  ('en.sahih', 26, 220, 'Indeed, He is the Hearing, the Knowing.'),
  ('en.sahih', 26, 221, 'Shall I inform you upon whom the devils descend?'),
  ('en.sahih', 26, 222, 'They descend upon every sinful liar.'),
  ('en.sahih', 26, 223, 'They pass on what is heard, and most of them are liars.'),
  ('en.sahih', 26, 224, 'And the poets - [only] the deviators follow them;'),
  ('en.sahih', 26, 225, 'Do you not see that in every valley they roam'),
  ('en.sahih', 26, 226, 'And that they say what they do not do? -'),
  ('en.sahih', 26, 227, 'Except those [poets] who believe and do righteous deeds and remember Allah often and defend [the Muslims] after they were wronged. And those who have wronged are going to know to what [kind of] return they will be returned.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 26, 1, 'ত্বা, সীন, মীম।'),
  ('bn.bengali', 26, 2, 'এগুলো সুস্পষ্ট কিতাবের আয়াত।'),
  ('bn.bengali', 26, 3, 'তারা বিশ্বাস করে না বলে আপনি হয়তো মর্মব্যথায় আত্নঘাতী হবেন।'),
  ('bn.bengali', 26, 4, 'আমি যদি ইচ্ছা করি, তবে আকাশ থেকে তাদের কাছে কোন নিদর্শন নাযিল করতে পারি। অতঃপর তারা এর সামনে নত হয়ে যাবে।'),
  ('bn.bengali', 26, 5, 'যখনই তাদের কাছে রহমান এর কোন নতুন উপদেশ আসে, তখনই তারা তা থেকে মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 26, 6, 'অতএব তারা তো মিথ্যারোপ করেছেই; সুতরাং যে বিষয় নিয়ে তারা ঠাট্টা-বিদ্রুপ করত, তার যথার্থ স্বরূপ শীঘ্রই তাদের কাছে পৌছবে।'),
  ('bn.bengali', 26, 7, 'তারা কি ভুপৃষ্ঠের প্রতি দৃষ্টিপাত করে না? আমি তাতে সর্বপ্রকার বিশেষ-বস্তু কত উদগত করেছি।'),
  ('bn.bengali', 26, 8, 'নিশ্চয় এতে নিদর্শন আছে, কিন্তু তাদের অধিকাংশই বিশ্বাসী নয়।'),
  ('bn.bengali', 26, 9, 'আপনার পালনকর্তা তো পরাক্রমশালী পরম দয়ালু।'),
  ('bn.bengali', 26, 10, 'যখন আপনার পালনকর্তা মূসাকে ডেকে বললেনঃ তুমি পাপিষ্ঠ সম্প্রদায়ের নিকট যাও;'),
  ('bn.bengali', 26, 11, 'ফেরাউনের সম্প্রদায়ের নিকট; তারা কি ভয় করে না?'),
  ('bn.bengali', 26, 12, 'সে বলল, হে আমার পালনকর্তা, আমার আশংকা হচ্ছে যে, তারা আমাকে মিথ্যাবাদী বলে দেবে।'),
  ('bn.bengali', 26, 13, 'এবং আমার মন হতবল হয়ে পড়ে এবং আমার জিহবা অচল হয়ে যায়। সুতরাং হারুনের কাছে বার্তা প্রেরণ করুন।'),
  ('bn.bengali', 26, 14, 'আমার বিরুদ্ধে তাদের অভিযোগ আছে। অতএব আমি আশংকা করি যে, তারা আমাকে হত্যা করবে।'),
  ('bn.bengali', 26, 15, 'আল্লাহ বলেন, কখনই নয় তোমরা উভয়ে যাও আমার নিদর্শনাবলী নিয়ে। আমি তোমাদের সাথে থেকে শোনব।'),
  ('bn.bengali', 26, 16, 'অতএব তোমরা ফেরআউনের কাছে যাও এবং বল, আমরা বিশ্বজগতের পালনকর্তার রসূল।'),
  ('bn.bengali', 26, 17, 'যাতে তুমি বনী-ইসরাঈলকে আমাদের সাথে যেতে দাও।'),
  ('bn.bengali', 26, 18, 'ফেরাউন বলল, আমরা কি তোমাকে শিশু অবস্থায় আমাদের মধ্যে লালন-পালন করিনি? এবং তুমি আমাদের মধ্যে জীবনের বহু বছর কাটিয়েছ।'),
  ('bn.bengali', 26, 19, 'তুমি সেই-তোমরা অপরাধ যা করবার করেছ। তুমি হলে কৃতঘ্ন।'),
  ('bn.bengali', 26, 20, 'মূসা বলল, আমি সে অপরাধ তখন করেছি, যখন আমি ভ্রান্ত ছিলাম।'),
  ('bn.bengali', 26, 21, 'অতঃপর আমি ভীত হয়ে তোমাদের কাছ থেকে পলায়ন করলাম। এরপর আমার পালনকর্তা আমাকে প্রজ্ঞা দান করেছেন এবং আমাকে পয়গম্বর করেছেন।'),
  ('bn.bengali', 26, 22, 'আমার প্রতি তোমার যে অনুগ্রহের কথা বলছ, তা এই যে, তুমি বনী-ইসলাঈলকে গোলাম বানিয়ে রেখেছ।'),
  ('bn.bengali', 26, 23, 'ফেরাউন বলল, বিশ্বজগতের পালনকর্তা আবার কি?'),
  ('bn.bengali', 26, 24, 'মূসা বলল, তিনি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের মধ্যবর্তী সবকিছুর পালনকর্তা যদি তোমরা বিশ্বাসী হও।'),
  ('bn.bengali', 26, 25, 'ফেরাউন তার পরিষদবর্গকে বলল, তোমরা কি শুনছ না?'),
  ('bn.bengali', 26, 26, 'মূসা বলল, তিনি তোমাদের পালনকর্তা এবং তোমাদের পূর্ববর্তীদেরও পালনকর্তা।'),
  ('bn.bengali', 26, 27, 'ফেরাউন বলল, তোমাদের প্রতি প্রেরিত তোমাদের রসূলটি নিশ্চয়ই বদ্ধ পাগল।'),
  ('bn.bengali', 26, 28, 'মূসা বলল, তিনি পূর্ব, পশ্চিম ও এতদুভয়ের মধ্যবর্তী সব কিছুর পালনকর্তা, যদি তোমরা বোঝ।'),
  ('bn.bengali', 26, 29, 'ফেরাউন বলল, তুমি যদি আমার পরিবর্তে অন্যকে উপাস্যরূপে গ্রহণ কর তবে আমি অবশ্যই তোমাকে কারাগারে নিক্ষেপ করব।'),
  ('bn.bengali', 26, 30, 'মূসা বলল, আমি তোমার কাছে কোন স্পষ্ট বিষয় নিয়ে আগমন করলেও কি?'),
  ('bn.bengali', 26, 31, 'ফেরাউন বলল, তুমি সত্যবাদী হলে তা উপস্থিত কর।'),
  ('bn.bengali', 26, 32, 'অতঃপর তিনি লাঠি নিক্ষেপ করলে মুহূর্তের মধ্যে তা সুস্পষ্ট অজগর হয়ে গেল।'),
  ('bn.bengali', 26, 33, 'আর তিনি তার হাত বের করলেন, তৎক্ষণাৎ তা দর্শকদের কাছে সুশুভ্র প্রতিভাত হলো।'),
  ('bn.bengali', 26, 34, 'ফেরাউন তার পরিষদবর্গকে বলল, নিশ্চয় এ একজন সুদক্ষ জাদুকর।'),
  ('bn.bengali', 26, 35, 'সে তার জাদু বলে তোমাদেরকে তোমাদের দেশ থেকে বহিস্কার করতে চায়। অতএব তোমাদের মত কি?'),
  ('bn.bengali', 26, 36, 'তারা বলল, তাকে ও তার ভাইকে কিছু অবকাশ দিন এবং শহরে শহরে ঘোষক প্রেরণ করুন।'),
  ('bn.bengali', 26, 37, 'তারা যেন আপনার কাছে প্রত্যেকটি দক্ষ জাদুকর কে উপস্থিত করে।'),
  ('bn.bengali', 26, 38, 'অতঃপর এক নির্দিষ্ট দিনে জাদুকরদেরকে একত্রিত করা হল।'),
  ('bn.bengali', 26, 39, 'এবং জনগণের মধ্যে ঘোষণা করা হল, তোমরাও সমবেত হও।'),
  ('bn.bengali', 26, 40, 'যাতে আমরা জাদুকরদের অনুসরণ করতে পারি-যদি তারাই বিজয়ী হয়।'),
  ('bn.bengali', 26, 41, 'যখন যাদুকররা আগমণ করল, তখন ফেরআউনকে বলল, যদি আমরা বিজয়ী হই, তবে আমরা পুরস্কার পাব তো?'),
  ('bn.bengali', 26, 42, 'ফেরাউন বলল, হঁ্যা এবং তখন তোমরা আমার নৈকট্যশীলদের অন্তর্ভুক্ত হবে।'),
  ('bn.bengali', 26, 43, 'মূসা (আঃ) তাদেরকে বললেন, নিক্ষেপ কর তোমরা যা নিক্ষেপ করবে।'),
  ('bn.bengali', 26, 44, 'অতঃপর তারা তাদের রশি ও লাঠি নিক্ষেপ করল এবং বলল, ফেরাউনের ইযযতের কসম, আমরাই বিজয়ী হব।'),
  ('bn.bengali', 26, 45, 'অতঃপর মূসা তাঁর লাঠি নিক্ষেপ করল, হঠাৎ তা তাদের অলীক কীর্তিগুলোকে গ্রাস করতে লাগল।'),
  ('bn.bengali', 26, 46, 'তখন জাদুকররা সেজদায় নত হয়ে গেল।'),
  ('bn.bengali', 26, 47, 'তারা বলল, আমরা রাব্বুল আলামীনের প্রতি বিশ্বাস স্থাপন করলাম।'),
  ('bn.bengali', 26, 48, 'যিনি মূসা ও হারুনের রব।'),
  ('bn.bengali', 26, 49, 'ফেরাউন বলল, আমার অনুমতি দানের পূর্বেই তোমরা কি তাকে মেনে নিলে? নিশ্চয় সে তোমাদের প্রধান, যে তোমাদেরকে জাদু শিক্ষা দিয়েছে। শীঘ্রই তোমরা পরিণাম জানতে পারবে। আমি অবশ্যই তোমাদের হাত ও পা বিপরীত দিক থেকে কর্তন করব। এবং তোমাদের সবাইকে শূলে চড়াব।'),
  ('bn.bengali', 26, 50, 'তারা বলল, কোন ক্ষতি নেই। আমরা আমাদের পালনকর্তার কাছে প্রত্যাবর্তন করব।'),
  ('bn.bengali', 26, 51, 'আমরা আশা করি, আমাদের পালনকর্তা আমাদের ক্রটি-বিচ্যুতি মার্জনা করবেন। কারণ, আমরা বিশ্বাস স্থাপনকারীদের মধ্যে অগ্রণী।'),
  ('bn.bengali', 26, 52, 'আমি মূসাকে আদেশ করলাম যে, আমার বান্দাদেরকে নিয়ে রাত্রিযোগে বের হয়ে যাও, নিশ্চয় তোমাদের পশ্চাদ্ধাবন করা হবে।'),
  ('bn.bengali', 26, 53, 'অতঃপর ফেরাউন শহরে শহরে সংগ্রাহকদেরকে প্রেরণ করল,'),
  ('bn.bengali', 26, 54, 'নিশ্চয় এরা (বনী-ইসরাঈলরা) ক্ষুদ্র একটি দল।'),
  ('bn.bengali', 26, 55, 'এবং তারা আমাদের ক্রোধের উদ্রেক করেছে।'),
  ('bn.bengali', 26, 56, 'এবং আমরা সবাই সদা শংকিত।'),
  ('bn.bengali', 26, 57, 'অতঃপর আমি ফেরআউনের দলকে তাদের বাগ-বাগিচা ও ঝর্ণাসমূহ থেকে বহিষ্কার করলাম।'),
  ('bn.bengali', 26, 58, 'এবং ধন-ভান্ডার ও মনোরম স্থানসমূহ থেকে।'),
  ('bn.bengali', 26, 59, 'এরূপই হয়েছিল এবং বনী-ইসলাঈলকে করে দিলাম এসবের মালিক।'),
  ('bn.bengali', 26, 60, 'অতঃপর সুর্যোদয়ের সময় তারা তাদের পশ্চাদ্ধাবন করল।'),
  ('bn.bengali', 26, 61, 'যখন উভয় দল পরস্পরকে দেখল, তখন মূসার সঙ্গীরা বলল, আমরা যে ধরা পড়ে গেলাম।'),
  ('bn.bengali', 26, 62, 'মূসা বলল, কখনই নয়, আমার সাথে আছেন আমার পালনকর্তা। তিনি আমাকে পথ বলে দেবেন।'),
  ('bn.bengali', 26, 63, 'অতঃপর আমি মূসাকে আদেশ করলাম, তোমার লাঠি দ্বারা সমূদ্রকে আঘাত কর। ফলে, তা বিদীর্ণ হয়ে গেল এবং প্রত্যেক ভাগ বিশাল পর্বতসদৃশ হয়ে গেল।'),
  ('bn.bengali', 26, 64, 'আমি সেথায় অপর দলকে পৌঁছিয়ে দিলাম।'),
  ('bn.bengali', 26, 65, 'এবং মূসা ও তাঁর সংগীদের সবাইকে বাঁচিয়ে দিলাম।'),
  ('bn.bengali', 26, 66, 'অতঃপর অপর দলটিকে নিমজ্জত কললাম।'),
  ('bn.bengali', 26, 67, 'নিশ্চয় এতে একটি নিদর্শন আছে এবং তাদের অধিকাংশই বিশ্বাসী ছিল না।'),
  ('bn.bengali', 26, 68, 'আপনার পালনকর্তা অবশ্যই পরাক্রমশালী, পরম দয়ালু।'),
  ('bn.bengali', 26, 69, 'আর তাদেরকে ইব্রাহীমের বৃত্তান্ত শুনিয়ে দিন।'),
  ('bn.bengali', 26, 70, 'যখন তাঁর পিতাকে এবং তাঁর সম্প্রদায়কে বললেন, তোমরা কিসের এবাদত কর?'),
  ('bn.bengali', 26, 71, 'তারা বলল, আমরা প্রতিমার পূজা করি এবং সারাদিন এদেরকেই নিষ্ঠার সাথে আঁকড়ে থাকি।'),
  ('bn.bengali', 26, 72, 'ইব্রাহীম (আঃ) বললেন, তোমরা যখন আহবান কর, তখন তারা শোনে কি?'),
  ('bn.bengali', 26, 73, 'অথবা তারা কি তোমাদের উপকার কিংবা ক্ষতি করতে পারে?'),
  ('bn.bengali', 26, 74, 'তারা বললঃ না, তবে আমরা আমাদের পিতৃপুরুষদেরকে পেয়েছি, তারা এরূপই করত।'),
  ('bn.bengali', 26, 75, 'ইব্রাহীম বললেন, তোমরা কি তাদের সম্পর্কে ভেবে দেখেছ, যাদের পূজা করে আসছ।'),
  ('bn.bengali', 26, 76, 'তোমরা এবং তোমাদের পূর্ববর্তী পিতৃপুরুষেরা ?'),
  ('bn.bengali', 26, 77, 'বিশ্বপালনকর্তা ব্যতীত তারা সবাই আমার শত্রু।'),
  ('bn.bengali', 26, 78, 'যিনি আমাকে সৃষ্টি করেছেন, অতঃপর তিনিই আমাকে পথপ্রদর্শন করেন,'),
  ('bn.bengali', 26, 79, 'যিনি আমাকে আহার এবং পানীয় দান করেন,'),
  ('bn.bengali', 26, 80, 'যখন আমি রোগাক্রান্ত হই, তখন তিনিই আরোগ্য দান করেন।'),
  ('bn.bengali', 26, 81, 'যিনি আমার মৃত্যু ঘটাবেন, অতঃপর পুনর্জীবন দান করবেন।'),
  ('bn.bengali', 26, 82, 'আমি আশা করি তিনিই বিচারের দিনে আমার ক্রটি-বিচ্যুতি মাফ করবেন।'),
  ('bn.bengali', 26, 83, 'হে আমার পালনকর্তা, আমাকে প্রজ্ঞা দান কর এবং আমাকে সৎকর্মশীলদের অন্তর্ভুক্ত কর'),
  ('bn.bengali', 26, 84, 'এবং আমাকে পরবর্তীদের মধ্যে সত্যভাষী কর।'),
  ('bn.bengali', 26, 85, 'এবং আমাকে নেয়ামত উদ্যানের অধিকারীদের অন্তর্ভূক্ত কর।'),
  ('bn.bengali', 26, 86, 'এবং আমার পিতাকে ক্ষমা কর। সে তো পথভ্রষ্টদের অন্যতম।'),
  ('bn.bengali', 26, 87, 'এবং পূনরুত্থান দিবসে আমাকে লাঞ্ছিত করো না,'),
  ('bn.bengali', 26, 88, 'যে দিবসে ধন-সম্পদ ও সন্তান সন্ততি কোন উপকারে আসবে না;'),
  ('bn.bengali', 26, 89, 'কিন্তু যে সুস্থ অন্তর নিয়ে আল্লাহর কাছে আসবে।'),
  ('bn.bengali', 26, 90, 'জান্নাত আল্লাহভীরুদের নিকটবর্তী করা হবে।'),
  ('bn.bengali', 26, 91, 'এবং বিপথগামীদের সামনে উম্মোচিত করা হবে জাহান্নাম।'),
  ('bn.bengali', 26, 92, 'তাদেরকে বলা হবেঃ তারা কোথায়, তোমরা যাদের পূজা করতে।'),
  ('bn.bengali', 26, 93, 'আল্লাহর পরিবর্তে? তারা কি তোমাদের সাহায্য করতে পারে, অথবা তারা প্রতিশোধ নিতে পারে?'),
  ('bn.bengali', 26, 94, 'অতঃপর তাদেরকে এবং পথভ্রষ্টদেরকে আধোমুখি করে নিক্ষেপ করা হবে জাহান্নামে।'),
  ('bn.bengali', 26, 95, 'এবং ইবলীস বাহিনীর সকলকে।'),
  ('bn.bengali', 26, 96, 'তারা তথায় কথা কাটাকাটিতে লিপ্ত হয়ে বলবেঃ'),
  ('bn.bengali', 26, 97, 'আল্লাহর কসম, আমরা প্রকাশ্য বিভ্রান্তিতে লিপ্ত ছিলাম।'),
  ('bn.bengali', 26, 98, 'যখন আমরা তোমাদেরকে বিশ্ব-পালনকর্তার সমতুল্য গন্য করতাম।'),
  ('bn.bengali', 26, 99, 'আমাদেরকে দুষ্টকর্মীরাই গোমরাহ করেছিল।'),
  ('bn.bengali', 26, 100, 'অতএব আমাদের কোন সুপারিশকারী নেই।'),
  ('bn.bengali', 26, 101, 'এবং কোন সহৃদয় বন্ধু ও নেই।'),
  ('bn.bengali', 26, 102, 'হায়, যদি কোনরুপে আমরা পৃথিবীতে প্রত্যাবর্তনের সুযোগ পেতাম, তবে আমরা বিশ্বাস স্থাপনকারী হয়ে যেতাম।'),
  ('bn.bengali', 26, 103, 'নিশ্চয়, এতে নিদর্শন আছে এবং তাদের অধিকাংশই বিশ্বাসী নয়।'),
  ('bn.bengali', 26, 104, 'আপনার পালনকর্তা প্রবল পরাক্রমশালী, পরম দয়ালু।'),
  ('bn.bengali', 26, 105, 'নূহের সম্প্রদায় পয়গম্বরগণকে মিথ্যারোপ করেছে।'),
  ('bn.bengali', 26, 106, 'যখন তাদের ভ্রাতা নূহ তাদেরকে বললেন, তোমাদের কি ভয় নেই?'),
  ('bn.bengali', 26, 107, 'আমি তোমাদের জন্য বিশ্বস্ত বার্তাবাহক।'),
  ('bn.bengali', 26, 108, 'অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।'),
  ('bn.bengali', 26, 109, 'আমি তোমাদের কাছে এর জন্য কোন প্রতিদান চাই না, আমার প্রতিদান তো বিশ্ব-পালনকর্তাই দেবেন।'),
  ('bn.bengali', 26, 110, 'অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।'),
  ('bn.bengali', 26, 111, 'তারা বলল, আমরা কি তোমাকে মেনে নেব যখন তোমার অনুসরণ করছে ইতরজনেরা?'),
  ('bn.bengali', 26, 112, 'নূহ বললেন, তারা কি কাজ করছে, তা জানা আমার কি দরকার?'),
  ('bn.bengali', 26, 113, 'তাদের হিসাব নেয়া আমার পালনকর্তারই কাজ; যদি তোমরা বুঝতে!'),
  ('bn.bengali', 26, 114, 'আমি মুমিনগণকে তাড়িয়ে দেয়ার লোক নই।'),
  ('bn.bengali', 26, 115, 'আমি তো শুধু একজন সুস্পষ্ট সতর্ককারী।'),
  ('bn.bengali', 26, 116, 'তারা বলল, হে নূহ যদি তুমি বিরত না হও, তবে তুমি নিশ্চিতই প্রস্তরাঘাতে নিহত হবে।'),
  ('bn.bengali', 26, 117, 'নূহ বললেন, হে আমার পালনকর্তা, আমার সম্প্রদায় তো আমাকে মিথ্যাবাদী বলছে।'),
  ('bn.bengali', 26, 118, 'অতএব, আমার ও তাদের মধ্যে কোন ফয়সালা করে দিন এবং আমাকে ও আমার সংগী মুমিনগণকে রক্ষা করুন।'),
  ('bn.bengali', 26, 119, 'অতঃপর আমি তাঁকে ও তাঁর সঙ্গিগণকে বোঝাই করা নৌকায় রক্ষা করলাম।'),
  ('bn.bengali', 26, 120, 'এরপর অবশিষ্ট সবাইকে নিমজ্জত করলাম।'),
  ('bn.bengali', 26, 121, 'নিশ্চয় এতে নিদর্শন আছে এবং তাদের অধিকাংশই বিশ্বাসী নয়।'),
  ('bn.bengali', 26, 122, 'নিশ্চয় আপনার পালনকর্তা প্রবল পরাক্রমশালী, পরম দয়ালু।'),
  ('bn.bengali', 26, 123, 'আদ সম্প্রদায় পয়গম্বরগণকে মিথ্যাবাদী বলেছে।'),
  ('bn.bengali', 26, 124, 'তখন তাদের ভাই হুদ তাদেরকে বললেনঃ তোমাদের কি ভয় নেই?'),
  ('bn.bengali', 26, 125, 'আমি তোমাদের বিশ্বস্ত রসূল।'),
  ('bn.bengali', 26, 126, 'অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।'),
  ('bn.bengali', 26, 127, 'আমি তোমাদের কাছে এর জন্যে প্রতিদান চাই না। আমার প্রতিদান তো পালনকর্তা দেবেন।'),
  ('bn.bengali', 26, 128, 'তোমরা কি প্রতিটি উচ্চস্থানে অযথা নিদর্শন নির্মান করছ?'),
  ('bn.bengali', 26, 129, 'এবং বড় বড় প্রাসাদ নির্মাণ করছ, যেন তোমরা চিরকাল থাকবে?'),
  ('bn.bengali', 26, 130, 'যখন তোমরা আঘাত হান, তখন জালেম ও নিষ্ঠুরের মত আঘাত হান।'),
  ('bn.bengali', 26, 131, 'অতএব, আল্লাহকে ভয় কর এবং আমার অনুগত্য কর।'),
  ('bn.bengali', 26, 132, 'ভয় কর তাঁকে, যিনি তোমাদেরকে সেসব বস্তু দিয়েছেন, যা তোমরা জান।'),
  ('bn.bengali', 26, 133, 'তোমাদেরকে দিয়েছেন চতুষ্পদ জন্তু ও পুত্র-সন্তান,'),
  ('bn.bengali', 26, 134, 'এবং উদ্যান ও ঝরণা।'),
  ('bn.bengali', 26, 135, 'আমি তোমাদের জন্যে মহাদিবসের শাস্তি আশংকা করি।'),
  ('bn.bengali', 26, 136, 'তারা বলল, তুমি উপদেশ দাও অথবা উপদেশ নাই দাও, উভয়ই আমাদের জন্যে সমান।'),
  ('bn.bengali', 26, 137, 'এসব কথাবার্তা পূর্ববর্তী লোকদের অভ্যাস বৈ নয়।'),
  ('bn.bengali', 26, 138, 'আমরা শাস্তিপ্রাপ্ত হব না।'),
  ('bn.bengali', 26, 139, 'অতএব, তারা তাঁকে মিথ্যাবাদী বলতে লাগল এবং আমি তাদেরকে নিপাত করে দিলাম। এতে অবশ্যই নিদর্শন আছে; কিন্তু তাদের অধিকাংশই বিশ্বাসী নয়।'),
  ('bn.bengali', 26, 140, 'এবং আপনার পালনকর্তা, তিনি তো প্রবল পরাক্রমশালী, পরম দয়ালু।'),
  ('bn.bengali', 26, 141, 'সামুদ সম্প্রদায় পয়গম্বরগণকে মিথ্যাবাদী বলেছে।'),
  ('bn.bengali', 26, 142, 'যখন তাদের ভাই সালেহ, তাদেরকে বললেন, তোমরা কি ভয় কর না?'),
  ('bn.bengali', 26, 143, 'আমি তোমাদের বিশ্বস্ত পয়গম্বর।'),
  ('bn.bengali', 26, 144, 'অতএব, আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।'),
  ('bn.bengali', 26, 145, 'আমি এর জন্যে তোমাদের কাছে কোন প্রতিদান চাই না। আমার প্রতিদান তো বিশ্ব-পালনকর্তাই দেবেন।'),
  ('bn.bengali', 26, 146, 'তোমাদেরকে কি এ জগতের ভোগ-বিলাসের মধ্যে নিরাপদে রেখে দেয়া হবে?'),
  ('bn.bengali', 26, 147, 'উদ্যানসমূহের মধ্যে এবং ঝরণাসমূহের মধ্যে ?'),
  ('bn.bengali', 26, 148, 'শস্যক্ষেত্রের মধ্যে এবং মঞ্জুরিত খেজুর বাগানের মধ্যে ?'),
  ('bn.bengali', 26, 149, 'তোমরা পাহাড় কেটে জাঁক জমকের গৃহ নির্মাণ করছ।'),
  ('bn.bengali', 26, 150, 'সুতরাং তোমরা আল্লাহকে ভয় কর এবং আমার অনুগত্য কর।'),
  ('bn.bengali', 26, 151, 'এবং সীমালংঘনকারীদের আদেশ মান্য কর না;'),
  ('bn.bengali', 26, 152, 'যারা পৃথিবীতে অনর্থ সৃষ্টি করে এবং শান্তি স্থাপন করে না;'),
  ('bn.bengali', 26, 153, 'তারা বলল, তুমি তো জাদুগ্রস্থুরেদ একজন।'),
  ('bn.bengali', 26, 154, 'তুমি তো আমাদের মতই একজন মানুষ বৈ নও। সুতরাং যদি তুমি সত্যবাদী হও, তবে কোন নিদর্শন উপস্থিত কর।'),
  ('bn.bengali', 26, 155, 'সালেহ বললেন এই উষ্ট্রী, এর জন্যে আছে পানি পানের পালা এবং তোমাদের জন্যে আছে পানি পানের পালা নির্দিষ্ট এক-এক দিনের।'),
  ('bn.bengali', 26, 156, 'তোমরা একে কোন কষ্ট দিও না। তাহলে তোমাদেরকে মহাদিবসের আযাব পাকড়াও করবে।'),
  ('bn.bengali', 26, 157, 'তারা তাকে বধ করল ফলে, তারা অনুতপ্ত হয়ে গেল।'),
  ('bn.bengali', 26, 158, 'এরপর আযাব তাদেরকে পাকড়াও করল। নিশ্চয় এতে নিদর্শন আছে। কিন্তু তাদের অধিকাংশই বিশ্বাসী নয়।'),
  ('bn.bengali', 26, 159, 'আপনার পালনকর্তা প্রবল পরাক্রমশালী, পরম দয়ালু।'),
  ('bn.bengali', 26, 160, 'লূতের সম্প্রদায় পয়গম্বরগণকে মিথ্যাবাদী বলেছে।'),
  ('bn.bengali', 26, 161, 'যখন তাদের ভাই লূত তাদেরকে বললেন, তোমরা কি ভয় কর না ?'),
  ('bn.bengali', 26, 162, 'আমি তোমাদের বিশ্বস্ত পয়গম্বর।'),
  ('bn.bengali', 26, 163, 'অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।'),
  ('bn.bengali', 26, 164, 'আমি এর জন্যে তোমাদের কাছে কোন প্রতিদান চাই না। আমার প্রতিদান তো বিশ্ব-পালনকর্তা দেবেন।'),
  ('bn.bengali', 26, 165, 'সারা জাহানের মানুষের মধ্যে তোমরাই কি পুরূষদের সাথে কুকর্ম কর?'),
  ('bn.bengali', 26, 166, 'এবং তোমাদের পালনকর্তা তোমাদের জন্যে যে স্ত্রীগনকে সৃষ্টি করেছেন, তাদেরকে বর্জন কর? বরং তোমরা সীমালঙ্ঘনকারী সম্প্রদায়।'),
  ('bn.bengali', 26, 167, 'তারা বলল, হে লূত, তুমি যদি বিরত না হও, তবে অবশ্যই তোমাকে বহিস্কৃত করা হবে।'),
  ('bn.bengali', 26, 168, 'লূত বললেন, আমি তোমাদের এই কাজকে ঘৃণা করি।'),
  ('bn.bengali', 26, 169, 'হে আমার পালনকর্তা, আমাকে এবং আমার পরিবারবর্গকে তারা যা করে, তা থেকে রক্ষা কর।'),
  ('bn.bengali', 26, 170, 'অতঃপর আমি তাঁকে ও তাঁর পরিবারবর্গকে রক্ষা করলাম।'),
  ('bn.bengali', 26, 171, 'এক বৃদ্ধা ব্যতীত, সে ছিল ধ্বংস প্রাপ্তদের অন্তর্ভুক্ত।'),
  ('bn.bengali', 26, 172, 'এরপর অন্যদেরকে নিপাত করলাম।'),
  ('bn.bengali', 26, 173, 'তাদের উপর এক বিশেষ বৃষ্টি বর্ষণ করলাম। ভীতি-প্রদর্শিত দের জন্যে এই বৃষ্টি ছিল কত নিকৃষ্ট।'),
  ('bn.bengali', 26, 174, 'নিশ্চয়ই এতে নিদর্শন রয়েছে; কিন্তু তাদের অধিকাংশই বিশ্বাসী নয়।'),
  ('bn.bengali', 26, 175, 'নিশ্চয়ই আপনার পালনকর্তা প্রবল পরাক্রমশালী, পরম দয়ালু।'),
  ('bn.bengali', 26, 176, 'বনের অধিবাসীরা পয়গম্বরগণকে মিথ্যাবাদী বলেছে।'),
  ('bn.bengali', 26, 177, 'যখন শো’আয়ব তাদের কে বললেন, তোমরা কি ভয় কর না?'),
  ('bn.bengali', 26, 178, 'আমি তোমাদের বিশ্বস্ত পয়গম্বর।'),
  ('bn.bengali', 26, 179, 'অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার আনুগত্য কর।'),
  ('bn.bengali', 26, 180, 'আমি তোমাদের কাছে এর জন্য কোন প্রতিদান চাই না। আমার প্রতিদান তো বিশ্ব-পালনকর্তাই দেবেন।'),
  ('bn.bengali', 26, 181, 'মাপ পূর্ণ কর এবং যারা পরিমাপে কম দেয়, তাদের অন্তর্ভুক্ত হয়ো না।'),
  ('bn.bengali', 26, 182, 'সোজা দাঁড়ি-পাল্লায় ওজন কর।'),
  ('bn.bengali', 26, 183, 'মানুষকে তাদের বস্তু কম দিও না এবং পৃথিবীতে অনর্থ সৃষ্টি করে ফিরো না।'),
  ('bn.bengali', 26, 184, 'ভয় কর তাঁকে, যিনি তোমাদেরকে এবং তোমাদের পূর্ববর্তী লোক-সম্প্রদায়কে সৃষ্টি করেছেন।'),
  ('bn.bengali', 26, 185, 'তারা বলল, তুমি তো জাদুগ্রস্তদের অন্যতম।'),
  ('bn.bengali', 26, 186, 'তুমি আমাদের মত মানুষ বৈ তো নও। আমাদের ধারণা-তুমি মিথ্যাবাদীদের অন্তর্ভুক্ত।'),
  ('bn.bengali', 26, 187, 'অতএব, যদি সত্যবাদী হও, তবে আকাশের কোন টুকরো আমাদের উপর ফেলে দাও।'),
  ('bn.bengali', 26, 188, 'শো’আয়ব বললেন, তোমরা যা কর, সে সম্পর্কে আমার পালনকর্তা ভালরূপে অবহিত।'),
  ('bn.bengali', 26, 189, 'অতঃপর তারা তাঁকে মিথ্যাবাদী বলে দিল। ফলে তাদেরকে মেঘাচ্ছন্ন দিবসের আযাব পাকড়াও করল। নিশ্চয় সেটা ছিল এক মহাদিবসের আযাব।'),
  ('bn.bengali', 26, 190, 'নিশ্চয় এতে নিদর্শন রয়েছে; কিন্তু তাদের অধিকাংশই বিশ্বাস করে না।'),
  ('bn.bengali', 26, 191, 'নিশ্চয় আপনার পালনকর্তা প্রবল পরাক্রমশালী, পরম দয়ালু।'),
  ('bn.bengali', 26, 192, 'এই কোরআন তো বিশ্ব-জাহানের পালনকর্তার নিকট থেকে অবতীর্ণ।'),
  ('bn.bengali', 26, 193, 'বিশ্বস্ত ফেরেশতা একে নিয়ে অবতরণ করেছে।'),
  ('bn.bengali', 26, 194, 'আপনার অন্তরে, যাতে আপনি ভীতি প্রদর্শণকারীদের অন্তর্ভুক্ত হন,'),
  ('bn.bengali', 26, 195, 'সুস্পষ্ট আরবী ভাষায়।'),
  ('bn.bengali', 26, 196, 'নিশ্চয় এর উল্লেখ আছে পূর্ববর্তী কিতাবসমূহে।'),
  ('bn.bengali', 26, 197, 'তাদের জন্যে এটা কি নিদর্শন নয় যে, বনী-ইসরাঈলের আলেমগণ এটা অবগত আছে?'),
  ('bn.bengali', 26, 198, 'যদি আমি একে কোন ভিন্নভাষীর প্রতি অবতীর্ণ করতাম,'),
  ('bn.bengali', 26, 199, 'অতঃপর তিনি তা তাদের কাছে পাঠ করতেন, তবে তারা তাতে বিশ্বাস স্থাপন করত না।'),
  ('bn.bengali', 26, 200, 'এমনিভাবে আমি গোনাহগারদের অন্তরে অবিশ্বাস সঞ্চার করেছি।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 26, 201, 'তারা এর প্রতি বিশ্বাস স্থাপন করবে না, যে পর্যন্ত প্রত্যক্ষ না করে মর্মন্তুদ আযাব।'),
  ('bn.bengali', 26, 202, 'অতঃপর তা আকস্মিকভাবে তাদের কাছে এসে পড়বে, তারা তা বুঝতে ও পারবে না।'),
  ('bn.bengali', 26, 203, 'তখন তারা বলবে, আমরা কি অবকাশ পাব না?'),
  ('bn.bengali', 26, 204, 'তারা কি আমার শাস্তি দ্রুত কামনা করে?'),
  ('bn.bengali', 26, 205, 'আপনি ভেবে দেখুন তো, যদি আমি তাদেরকে বছরের পর বছর ভোগ-বিলাস করতে দেই,'),
  ('bn.bengali', 26, 206, 'অতঃপর যে বিষয়ে তাদেরকে ওয়াদা দেয়া হত, তা তাদের কাছে এসে পড়ে।'),
  ('bn.bengali', 26, 207, 'তখন তাদের ভোগ বিলাস তা তাদের কি কোন উপকারে আসবে?'),
  ('bn.bengali', 26, 208, 'আমি কোন জনপদ ধ্বংস করিনি; কিন্তু এমতাবস্থায় যে, তারা সতর্ককারী ছিল।'),
  ('bn.bengali', 26, 209, 'স্মরণ করানোর জন্যে, এবং আমার কাজ অন্যায়াচরণ নয়।'),
  ('bn.bengali', 26, 210, 'এই কোরআন শয়তানরা অবতীর্ণ করেনি।'),
  ('bn.bengali', 26, 211, 'তারা এ কাজের উপযুক্ত নয় এবং তারা এর সামর্থ?451; রাখে না।'),
  ('bn.bengali', 26, 212, 'তাদেরকে তো শ্রবণের জায়গা থেকে দূরে রাখা রয়েছে।'),
  ('bn.bengali', 26, 213, 'অতএব, আপনি আল্লাহর সাথে অন্য উপাস্যকে আহবান করবেন না। করলে শাস্তিতে পতিত হবেন।'),
  ('bn.bengali', 26, 214, 'আপনি নিকটতম আত্মীয়দেরকে সতর্ক করে দিন।'),
  ('bn.bengali', 26, 215, 'এবং আপনার অনুসারী মুমিনদের প্রতি সদয় হোন।'),
  ('bn.bengali', 26, 216, 'যদি তারা আপনার অবাধ্য করে, তবে বলে দিন, তোমরা যা কর, তা থেকে আমি মুক্ত।'),
  ('bn.bengali', 26, 217, 'আপনি ভরসা করুন পরাক্রমশালী, পরম দয়ালুর উপর,'),
  ('bn.bengali', 26, 218, 'যিনি আপনাকে দেখেন যখন আপনি নামাযে দন্ডায়মান হন,'),
  ('bn.bengali', 26, 219, 'এবং নামাযীদের সাথে উঠাবসা করেন।'),
  ('bn.bengali', 26, 220, 'নিশ্চয় তিনি সর্বশ্রোতা, সর্বজ্ঞানী।'),
  ('bn.bengali', 26, 221, 'আমি আপনাকে বলব কি কার নিকট শয়তানরা অবতরণ করে?'),
  ('bn.bengali', 26, 222, 'তারা অবতীর্ণ হয় প্রত্যেক মিথ্যাবাদী, গোনাহগারের উপর।'),
  ('bn.bengali', 26, 223, 'তারা শ্রুত কথা এনে দেয় এবং তাদের অধিকাংশই মিথ্যাবাদী।'),
  ('bn.bengali', 26, 224, 'বিভ্রান্ত লোকেরাই কবিদের অনুসরণ করে।'),
  ('bn.bengali', 26, 225, 'তুমি কি দেখ না যে, তারা প্রতি ময়দানেই উদভ্রান্ত হয়ে ফিরে?'),
  ('bn.bengali', 26, 226, 'এবং এমন কথা বলে, যা তারা করে না।'),
  ('bn.bengali', 26, 227, 'তবে তাদের কথা ভিন্ন, যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে এবং আল্লাহ কে খুব স্মরণ করে এবং নিপীড়িত হওয়ার পর প্রতিশোধ গ্রহণ করে। নিপীড়নকারীরা শীঘ্রই জানতে পারবে তাদের গন্তব্যস্থল কিরূপ।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 26, 1, 'Ta. Sin. Mim.'),
  ('en.pickthall', 26, 2, 'These are revelations of the Scripture that maketh plain.'),
  ('en.pickthall', 26, 3, 'It may be that thou tormentest thyself (O Muhammad) because they believe not.'),
  ('en.pickthall', 26, 4, 'If We will, We can send down on them from the sky a portent so that their necks would remain bowed before it.'),
  ('en.pickthall', 26, 5, 'Never cometh there unto them a fresh reminder from the Beneficent One, but they turn away from it.'),
  ('en.pickthall', 26, 6, 'Now they have denied (the Truth); but there will come unto them tidings of that whereat they used to scoff.'),
  ('en.pickthall', 26, 7, 'Have they not seen the earth, how much of every fruitful kind We make to grow therein?'),
  ('en.pickthall', 26, 8, 'Lo! herein is indeed a portent; yet most of them are not believers.'),
  ('en.pickthall', 26, 9, 'And lo! thy Lord! He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 10, 'And when thy Lord called Moses, saying: Go unto the wrongdoing folk,'),
  ('en.pickthall', 26, 11, 'The folk of Pharaoh. Will they not ward off (evil)?'),
  ('en.pickthall', 26, 12, 'He said: My Lord! Lo! I fear that they will deny me,'),
  ('en.pickthall', 26, 13, 'And I shall be embarrassed, and my tongue will not speak plainly, therefor send for Aaron (to help me).'),
  ('en.pickthall', 26, 14, 'And they have a crime against me, so I fear that they will kill me.'),
  ('en.pickthall', 26, 15, 'He said: Nay, verily. So go ye twain with Our tokens. Lo! We shall be with you, Hearing.'),
  ('en.pickthall', 26, 16, 'And come together unto Pharaoh and say: Lo! we bear a message of the Lord of the Worlds,'),
  ('en.pickthall', 26, 17, '(Saying): Let the Children of Israel go with us.'),
  ('en.pickthall', 26, 18, '(Pharaoh) said (unto Moses): Did we not rear thee among us as a child? And thou didst dwell many years of thy life among us,'),
  ('en.pickthall', 26, 19, 'And thou didst that thy deed which thou didst, and thou wast one of the ingrates.'),
  ('en.pickthall', 26, 20, 'He said: I did it then, when I was of those who are astray.'),
  ('en.pickthall', 26, 21, 'Then I fled from you when I feared you, and my Lord vouchsafed me a command and appointed me (of the number) of those sent (by Him).'),
  ('en.pickthall', 26, 22, 'And this is the past favour wherewith thou reproachest me: that thou hast enslaved the Children of Israel.'),
  ('en.pickthall', 26, 23, 'Pharaoh said: And what is the Lord of the Worlds?'),
  ('en.pickthall', 26, 24, '(Moses) said: Lord of the heavens and the earth and all that is between them, if ye had but sure belief.'),
  ('en.pickthall', 26, 25, '(Pharaoh) said unto those around him: Hear ye not?'),
  ('en.pickthall', 26, 26, 'He said: Your Lord and the Lord of your fathers.'),
  ('en.pickthall', 26, 27, '(Pharaoh) said: Lo! your messenger who hath been sent unto you is indeed a madman!'),
  ('en.pickthall', 26, 28, 'He said: Lord of the East and the West and all that is between them, if ye did but understand.'),
  ('en.pickthall', 26, 29, '(Pharaoh) said: If thou choosest a god other than me, I assuredly shall place thee among the prisoners.'),
  ('en.pickthall', 26, 30, 'He said: Even though I show thee something plain?'),
  ('en.pickthall', 26, 31, '(Pharaoh) said: Produce it then, if thou art of the truthful!'),
  ('en.pickthall', 26, 32, 'Then he flung down his staff and it became a serpent manifest,'),
  ('en.pickthall', 26, 33, 'And he drew forth his hand and lo! it was white to the beholders.'),
  ('en.pickthall', 26, 34, '(Pharaoh) said unto the chiefs about him: Lo! this is verily a knowing wizard,'),
  ('en.pickthall', 26, 35, 'Who would drive you out of your land by his magic. Now what counsel ye?'),
  ('en.pickthall', 26, 36, 'They said: Put him off, (him) and his brother, and send into the cities summoners'),
  ('en.pickthall', 26, 37, 'Who shall bring unto thee every knowing wizard.'),
  ('en.pickthall', 26, 38, 'So the wizards were gathered together at a set time on a day appointed.'),
  ('en.pickthall', 26, 39, 'And it was said unto the people: Are ye (also) gathering?'),
  ('en.pickthall', 26, 40, '(They said): Aye, so that we may follow the wizards if they are the winners.'),
  ('en.pickthall', 26, 41, 'And when the wizards came they said unto Pharaoh: Will there surely be a reward for us if we are the winners?'),
  ('en.pickthall', 26, 42, 'He said: Aye, and ye will then surely be of those brought near (to me).'),
  ('en.pickthall', 26, 43, 'Moses said unto them: Throw what ye are going to throw!'),
  ('en.pickthall', 26, 44, 'Then they threw down their cords and their staves and said: By Pharaoh\'s might, lo! we verily are the winners.'),
  ('en.pickthall', 26, 45, 'Then Moses threw his staff and lo! it swallowed that which they did falsely show.'),
  ('en.pickthall', 26, 46, 'And the wizards were flung prostrate,'),
  ('en.pickthall', 26, 47, 'Crying: We believe in the Lord of the Worlds,'),
  ('en.pickthall', 26, 48, 'The Lord of Moses and Aaron.'),
  ('en.pickthall', 26, 49, '(Pharaoh) said: Ye put your faith in him before I give you leave. Lo! he doubtless is your chief who taught you magic! But verily ye shall come to know. Verily I will cut off your hands and your feet alternately, and verily I will crucify you every one.'),
  ('en.pickthall', 26, 50, 'They said: It is no hurt, for lo! unto our Lord we shall return.'),
  ('en.pickthall', 26, 51, 'Lo! we ardently hope that our Lord will forgive us our sins because we are the first of the believers.'),
  ('en.pickthall', 26, 52, 'And We inspired Moses, saying: Take away My slaves by night, for ye will be pursued.'),
  ('en.pickthall', 26, 53, 'Then Pharaoh sent into the cities summoners,'),
  ('en.pickthall', 26, 54, '(Who said): Lo! these indeed are but a little troop,'),
  ('en.pickthall', 26, 55, 'And lo! they are offenders against us.'),
  ('en.pickthall', 26, 56, 'And lo! we are a ready host.'),
  ('en.pickthall', 26, 57, 'Thus did We take them away from gardens and watersprings,'),
  ('en.pickthall', 26, 58, 'And treasures and a fair estate.'),
  ('en.pickthall', 26, 59, 'Thus (were those things taken from them) and We caused the Children of Israel to inherit them.'),
  ('en.pickthall', 26, 60, 'And they overtook them at sunrise.'),
  ('en.pickthall', 26, 61, 'And when the two hosts saw each other, those with Moses said: Lo! we are indeed caught.'),
  ('en.pickthall', 26, 62, 'He said: Nay, verily! for lo! my Lord is with me. He will guide me.'),
  ('en.pickthall', 26, 63, 'Then We inspired Moses, saying: Smite the sea with thy staff. And it parted, and each part was as a mountain vast.'),
  ('en.pickthall', 26, 64, 'Then brought We near the others to that place.'),
  ('en.pickthall', 26, 65, 'And We saved Moses and those with him, every one;'),
  ('en.pickthall', 26, 66, 'And We drowned the others.'),
  ('en.pickthall', 26, 67, 'Lo! herein is indeed a portent, yet most of them are not believers.'),
  ('en.pickthall', 26, 68, 'And lo, thy Lord! He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 69, 'Recite unto them the story of Abraham:'),
  ('en.pickthall', 26, 70, 'When he said unto his father and his folk: What worship ye?'),
  ('en.pickthall', 26, 71, 'They said: We worship idols, and are ever devoted unto them.'),
  ('en.pickthall', 26, 72, 'He said: Do they hear you when ye cry?'),
  ('en.pickthall', 26, 73, 'Or do they benefit or harm you?'),
  ('en.pickthall', 26, 74, 'They said: Nay, but we found our fathers acting on this wise.'),
  ('en.pickthall', 26, 75, 'He said: See now that which ye worship,'),
  ('en.pickthall', 26, 76, 'Ye and your forefathers!'),
  ('en.pickthall', 26, 77, 'Lo! they are (all) an enemy unto me, save the Lord of the Worlds,'),
  ('en.pickthall', 26, 78, 'Who created me, and He doth guide me,'),
  ('en.pickthall', 26, 79, 'And Who feedeth me and watereth me.'),
  ('en.pickthall', 26, 80, 'And when I sicken, then He healeth me,'),
  ('en.pickthall', 26, 81, 'And Who causeth me to die, then giveth me life (again),'),
  ('en.pickthall', 26, 82, 'And Who, I ardently hope, will forgive me my sin on the Day of Judgment.'),
  ('en.pickthall', 26, 83, 'My Lord! Vouchsafe me wisdom and unite me to the righteous.'),
  ('en.pickthall', 26, 84, 'And give unto me a good report in later generations.'),
  ('en.pickthall', 26, 85, 'And place me among the inheritors of the Garden of Delight,'),
  ('en.pickthall', 26, 86, 'And forgive my father. Lo! he is of those who err.'),
  ('en.pickthall', 26, 87, 'And abase me not on the day when they are raised,'),
  ('en.pickthall', 26, 88, 'The day when wealth and sons avail not (any man)'),
  ('en.pickthall', 26, 89, 'Save him who bringeth unto Allah a whole heart.'),
  ('en.pickthall', 26, 90, 'And the Garden will be brought nigh for those who ward off (evil).'),
  ('en.pickthall', 26, 91, 'And hell will appear plainly to the erring.'),
  ('en.pickthall', 26, 92, 'And it will be said unto them: Where is (all) that ye used to worship'),
  ('en.pickthall', 26, 93, 'Instead of Allah? Can they help you or help themselves?'),
  ('en.pickthall', 26, 94, 'Then will they be hurled therein, they and the seducers'),
  ('en.pickthall', 26, 95, 'And the hosts of Iblis, together.'),
  ('en.pickthall', 26, 96, 'And they will say, when they are quarrelling therein:'),
  ('en.pickthall', 26, 97, 'By Allah, of a truth we were in error manifest'),
  ('en.pickthall', 26, 98, 'When we made you equal with the Lord of the Worlds.'),
  ('en.pickthall', 26, 99, 'It was but the guilty who misled us.'),
  ('en.pickthall', 26, 100, 'Now we have no intercessors'),
  ('en.pickthall', 26, 101, 'Nor any loving friend.'),
  ('en.pickthall', 26, 102, 'Oh, that we had another turn (on earth), that we might be of the believers!'),
  ('en.pickthall', 26, 103, 'Lo! herein is indeed a portent, yet most of them are not believers!'),
  ('en.pickthall', 26, 104, 'And lo, thy Lord! He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 105, 'Noah\'s folk denied the messengers (of Allah),'),
  ('en.pickthall', 26, 106, 'When their brother Noah said unto them: Will ye not ward off (evil)?'),
  ('en.pickthall', 26, 107, 'Lo! I am a faithful messenger unto you,'),
  ('en.pickthall', 26, 108, 'So keep your duty to Allah, and obey me.'),
  ('en.pickthall', 26, 109, 'And I ask of you no wage therefor; my wage is the concern only of the Lord of the Worlds.'),
  ('en.pickthall', 26, 110, 'So keep your duty to Allah, and obey me.'),
  ('en.pickthall', 26, 111, 'They said: Shall we put faith in thee, when the lowest (of the people) follow thee?'),
  ('en.pickthall', 26, 112, 'He said: And what knowledge have I of what they may have been doing (in the past)?'),
  ('en.pickthall', 26, 113, 'Lo! their reckoning is my Lord\'s concern, if ye but knew;'),
  ('en.pickthall', 26, 114, 'And I am not (here) to repulse believers.'),
  ('en.pickthall', 26, 115, 'I am only a plain warner.'),
  ('en.pickthall', 26, 116, 'They said: If thou cease not, O Noah, thou wilt surely be among those stoned (to death).'),
  ('en.pickthall', 26, 117, 'He said: My Lord! Lo! my own folk deny me.'),
  ('en.pickthall', 26, 118, 'Therefor judge Thou between us, a (conclusive) judgment, and save me and those believers who are with me.'),
  ('en.pickthall', 26, 119, 'And We saved him and those with him in the laden ship.'),
  ('en.pickthall', 26, 120, 'Then afterward We drowned the others.'),
  ('en.pickthall', 26, 121, 'Lo! herein is indeed a portent, yet most of them are not believers.'),
  ('en.pickthall', 26, 122, 'And lo, thy Lord, He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 123, '(The tribe of) A\'ad denied the messengers (of Allah).'),
  ('en.pickthall', 26, 124, 'When their brother Hud said unto them: Will ye not ward off (evil)?'),
  ('en.pickthall', 26, 125, 'Lo! I am a faithful messenger unto you,'),
  ('en.pickthall', 26, 126, 'So keep your duty to Allah and obey me.'),
  ('en.pickthall', 26, 127, 'And I ask of you no wage therefor; my wage is the concern only of the Lord of the Worlds.'),
  ('en.pickthall', 26, 128, 'Build ye on every high place a monument for vain delight?'),
  ('en.pickthall', 26, 129, 'And seek ye out strongholds, that haply ye may last for ever?'),
  ('en.pickthall', 26, 130, 'And if ye seize by force, seize ye as tyrants?'),
  ('en.pickthall', 26, 131, 'Rather keep your duty to Allah, and obey me.'),
  ('en.pickthall', 26, 132, 'Keep your duty toward Him Who hath aided you with (the good things) that ye know,'),
  ('en.pickthall', 26, 133, 'Hath aided you with cattle and sons.'),
  ('en.pickthall', 26, 134, 'And gardens and watersprings.'),
  ('en.pickthall', 26, 135, 'Lo! I fear for you the retribution of an awful day.'),
  ('en.pickthall', 26, 136, 'They said: It is all one to us whether thou preachest or art not of those who preach;'),
  ('en.pickthall', 26, 137, 'This is but a fable of the men of old,'),
  ('en.pickthall', 26, 138, 'And we shall not be doomed.'),
  ('en.pickthall', 26, 139, 'And they denied him; therefor We destroyed them. Lo! herein is indeed a portent, yet most of them are not believers.'),
  ('en.pickthall', 26, 140, 'And lo! thy Lord, He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 141, '(The tribe of) Thamud denied the messengers (of Allah)'),
  ('en.pickthall', 26, 142, 'When their brother Salih said unto them: Will ye not ward off (evil)?'),
  ('en.pickthall', 26, 143, 'Lo! I am a faithful messenger unto you,'),
  ('en.pickthall', 26, 144, 'So keep your duty to Allah and obey me.'),
  ('en.pickthall', 26, 145, 'And I ask of you no wage therefor; my wage is the concern only of the Lord of the Worlds.'),
  ('en.pickthall', 26, 146, 'Will ye be left secure in that which is here before us,'),
  ('en.pickthall', 26, 147, 'In gardens and watersprings.'),
  ('en.pickthall', 26, 148, 'And tilled fields and heavy-sheathed palm-trees,'),
  ('en.pickthall', 26, 149, 'Though ye hew out dwellings in the mountain, being skilful?'),
  ('en.pickthall', 26, 150, 'Therefor keep your duty to Allah and obey me,'),
  ('en.pickthall', 26, 151, 'And obey not the command of the prodigal,'),
  ('en.pickthall', 26, 152, 'Who spread corruption in the earth, and reform not.'),
  ('en.pickthall', 26, 153, 'They said: Thou art but one of the bewitched;'),
  ('en.pickthall', 26, 154, 'Thou art but a mortal like us. So bring some token if thou art of the truthful.'),
  ('en.pickthall', 26, 155, 'He said: (Behold) this she-camel. She hath the right to drink (at the well), and ye have the right to drink, (each) on an appointed day.'),
  ('en.pickthall', 26, 156, 'And touch her not with ill lest there come on you the retribution of an awful day.'),
  ('en.pickthall', 26, 157, 'But they hamstrung her, and then were penitent.'),
  ('en.pickthall', 26, 158, 'So the retribution came on them. Lo! herein is indeed a portent, yet most of them are not believers.'),
  ('en.pickthall', 26, 159, 'And lo! thy Lord! He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 160, 'The folk of Lot denied the messengers (of Allah),'),
  ('en.pickthall', 26, 161, 'When their brother Lot said unto them: Will ye not ward off (evil)?'),
  ('en.pickthall', 26, 162, 'Lo! I am a faithful messenger unto you,'),
  ('en.pickthall', 26, 163, 'So keep your duty to Allah and obey me.'),
  ('en.pickthall', 26, 164, 'And I ask of you no wage therefor; my wage is the concern only of the Lord of the Worlds.'),
  ('en.pickthall', 26, 165, 'What! Of all creatures do ye come unto the males,'),
  ('en.pickthall', 26, 166, 'And leave the wives your Lord created for you? Nay, but ye are froward folk.'),
  ('en.pickthall', 26, 167, 'They said: If thou cease not, O Lot, thou wilt soon be of the outcast.'),
  ('en.pickthall', 26, 168, 'He said: I am in truth of those who hate your conduct.'),
  ('en.pickthall', 26, 169, 'My Lord! Save me and my household from what they do.'),
  ('en.pickthall', 26, 170, 'So We saved him and his household, every one,'),
  ('en.pickthall', 26, 171, 'Save an old woman among those who stayed behind.'),
  ('en.pickthall', 26, 172, 'Then afterward We destroyed the others.'),
  ('en.pickthall', 26, 173, 'And We rained on them a rain. And dreadful is the rain of those who have been warned.'),
  ('en.pickthall', 26, 174, 'Lo! herein is indeed a portent, yet most of them are not believers.'),
  ('en.pickthall', 26, 175, 'And lo! thy Lord, He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 176, 'The dwellers in the wood (of Midian) denied the messengers (of Allah),'),
  ('en.pickthall', 26, 177, 'When Shu\'eyb said unto them: Will ye not ward off (evil)?'),
  ('en.pickthall', 26, 178, 'Lo! I am a faithful messenger unto you,'),
  ('en.pickthall', 26, 179, 'So keep your duty to Allah and obey me.'),
  ('en.pickthall', 26, 180, 'And I ask of you no wage for it; my wage is the concern only of the Lord of the Worlds.'),
  ('en.pickthall', 26, 181, 'Give full measure, and be not of those who give less (than the due).'),
  ('en.pickthall', 26, 182, 'And weigh with the true balance.'),
  ('en.pickthall', 26, 183, 'Wrong not mankind in their goods, and do not evil, making mischief, in the earth.'),
  ('en.pickthall', 26, 184, 'And keep your duty unto Him Who created you and the generations of the men of old.'),
  ('en.pickthall', 26, 185, 'They said: Thou art but one of the bewitched;'),
  ('en.pickthall', 26, 186, 'Thou art but a mortal like us, and lo! we deem thee of the liars.'),
  ('en.pickthall', 26, 187, 'Then make fragments of the heaven fall upon us, if thou art of the truthful.'),
  ('en.pickthall', 26, 188, 'He said: My Lord is Best Aware of what ye do.'),
  ('en.pickthall', 26, 189, 'But they denied him, so there came on them the retribution of the day of gloom. Lo! it was the retribution of an awful day.'),
  ('en.pickthall', 26, 190, 'Lo! herein is indeed a portent; yet most of them are not believers.'),
  ('en.pickthall', 26, 191, 'And lo! thy Lord! He is indeed the Mighty, the Merciful.'),
  ('en.pickthall', 26, 192, 'And lo! it is a revelation of the Lord of the Worlds,'),
  ('en.pickthall', 26, 193, 'Which the True Spirit hath brought down'),
  ('en.pickthall', 26, 194, 'Upon thy heart, that thou mayst be (one) of the warners,'),
  ('en.pickthall', 26, 195, 'In plain Arabic speech.'),
  ('en.pickthall', 26, 196, 'And lo! it is in the Scriptures of the men of old.'),
  ('en.pickthall', 26, 197, 'Is it not a token for them that the doctors of the Children of Israel know it?'),
  ('en.pickthall', 26, 198, 'And if We had revealed it unto one of any other nation than the Arabs,'),
  ('en.pickthall', 26, 199, 'And he had read it unto them, they would not have believed in it.'),
  ('en.pickthall', 26, 200, 'Thus do We make it traverse the hearts of the guilty.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 26, 201, 'They will not believe in it till they behold the painful doom,'),
  ('en.pickthall', 26, 202, 'So that it will come upon them suddenly, when they perceive not.'),
  ('en.pickthall', 26, 203, 'Then they will say: Are we to be reprieved?'),
  ('en.pickthall', 26, 204, 'Would they (now) hasten on Our doom?'),
  ('en.pickthall', 26, 205, 'Hast thou then seen, if We content them for (long) years,'),
  ('en.pickthall', 26, 206, 'And then cometh that which they were promised,'),
  ('en.pickthall', 26, 207, '(How) that wherewith they were contented naught availeth them?'),
  ('en.pickthall', 26, 208, 'And We destroyed no township but it had its warners'),
  ('en.pickthall', 26, 209, 'For reminder, for We never were oppressors.'),
  ('en.pickthall', 26, 210, 'The devils did not bring it down.'),
  ('en.pickthall', 26, 211, 'It is not meet for them, nor is it in their power,'),
  ('en.pickthall', 26, 212, 'Lo! verily they are banished from the hearing.'),
  ('en.pickthall', 26, 213, 'Therefor invoke not with Allah another god, lest thou be one of the doomed.'),
  ('en.pickthall', 26, 214, 'And warn thy tribe of near kindred,'),
  ('en.pickthall', 26, 215, 'And lower thy wing (in kindness) unto those believers who follow thee.'),
  ('en.pickthall', 26, 216, 'And if they (thy kinsfolk) disobey thee, say: Lo! I am innocent of what they do.'),
  ('en.pickthall', 26, 217, 'And put thy trust in the Mighty, the Merciful.'),
  ('en.pickthall', 26, 218, 'Who seeth thee when thou standest up (to pray)'),
  ('en.pickthall', 26, 219, 'And (seeth) thine abasement among those who fall prostrate (in worship).'),
  ('en.pickthall', 26, 220, 'Lo! He, only He, is the Hearer, the Knower.'),
  ('en.pickthall', 26, 221, 'Shall I inform you upon whom the devils descend?'),
  ('en.pickthall', 26, 222, 'They descend on every sinful, false one.'),
  ('en.pickthall', 26, 223, 'They listen eagerly, but most of them are liars.'),
  ('en.pickthall', 26, 224, 'As for poets, the erring follow them.'),
  ('en.pickthall', 26, 225, 'Hast thou not seen how they stray in every valley,'),
  ('en.pickthall', 26, 226, 'And how they say that which they do not?'),
  ('en.pickthall', 26, 227, 'Save those who believe and do good works, and remember Allah much, and vindicate themselves after they have been wronged. Those who do wrong will come to know by what a (great) reverse they will be overturned!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 26, 1, 'Ta. Sin. Mim.'),
  ('en.yusufali', 26, 2, 'These are verses of the Book that makes (things) clear.'),
  ('en.yusufali', 26, 3, 'It may be thou frettest thy soul with grief, that they do not become Believers.'),
  ('en.yusufali', 26, 4, 'If (such) were Our Will, We could send down to them from the sky a Sign, to which they would bend their necks in humility.'),
  ('en.yusufali', 26, 5, 'But there comes not to them a newly-revealed Message from (Allah) Most Gracious, but they turn away therefrom.'),
  ('en.yusufali', 26, 6, 'They have indeed rejected (the Message): so they will know soon (enough) the truth of what they mocked at!'),
  ('en.yusufali', 26, 7, 'Do they not look at the earth,- how many noble things of all kinds We have produced therein?'),
  ('en.yusufali', 26, 8, 'Verily, in this is a Sign: but most of them do not believe.'),
  ('en.yusufali', 26, 9, 'And verily, thy Lord is He, the Exalted in Might, Most Merciful.'),
  ('en.yusufali', 26, 10, 'Behold, thy Lord called Moses: "Go to the people of iniquity,-'),
  ('en.yusufali', 26, 11, '"The people of the Pharaoh: will they not fear Allah?"'),
  ('en.yusufali', 26, 12, 'He said: "O my Lord! I do fear that they will charge me with falsehood:'),
  ('en.yusufali', 26, 13, '"My breast will be straitened. And my speech may not go (smoothly): so send unto Aaron.'),
  ('en.yusufali', 26, 14, '"And (further), they have a charge of crime against me; and I fear they may slay me."'),
  ('en.yusufali', 26, 15, 'Allah said: "By no means! proceed then, both of you, with Our Signs; We are with you, and will listen (to your call).'),
  ('en.yusufali', 26, 16, '"So go forth, both of you, to Pharaoh, and say: \'We have been sent by the Lord and Cherisher of the worlds;'),
  ('en.yusufali', 26, 17, '"\'Send thou with us the Children of Israel.\'"'),
  ('en.yusufali', 26, 18, '(Pharaoh) said: "Did we not cherish thee as a child among us, and didst thou not stay in our midst many years of thy life?'),
  ('en.yusufali', 26, 19, '"And thou didst a deed of thine which (thou knowest) thou didst, and thou art an ungrateful (wretch)!"'),
  ('en.yusufali', 26, 20, 'Moses said: "I did it then, when I was in error.'),
  ('en.yusufali', 26, 21, '"So I fled from you (all) when I feared you; but my Lord has (since) invested me with judgment (and wisdom) and appointed me as one of the messengers.'),
  ('en.yusufali', 26, 22, '"And this is the favour with which thou dost reproach me,- that thou hast enslaved the Children of Israel!"'),
  ('en.yusufali', 26, 23, 'Pharaoh said: "And what is the \'Lord and Cherisher of the worlds\'?"'),
  ('en.yusufali', 26, 24, '(Moses) said: "The Lord and Cherisher of the heavens and the earth, and all between,- if ye want to be quite sure."'),
  ('en.yusufali', 26, 25, '(Pharaoh) said to those around: "Did ye not listen (to what he says)?"'),
  ('en.yusufali', 26, 26, '(Moses) said: "Your Lord and the Lord of your fathers from the beginning!"'),
  ('en.yusufali', 26, 27, '(Pharaoh) said: "Truly your messenger who has been sent to you is a veritable madman!"'),
  ('en.yusufali', 26, 28, '(Moses) said: "Lord of the East and the West, and all between! if ye only had sense!"'),
  ('en.yusufali', 26, 29, '(Pharaoh) said: "If thou dost put forward any god other than me, I will certainly put thee in prison!"'),
  ('en.yusufali', 26, 30, '(Moses) said: "Even if I showed you something clear (and) convincing?"'),
  ('en.yusufali', 26, 31, '(Pharaoh) said: "Show it then, if thou tellest the truth!"'),
  ('en.yusufali', 26, 32, 'So (Moses) threw his rod, and behold, it was a serpent, plain (for all to see)!'),
  ('en.yusufali', 26, 33, 'And he drew out his hand, and behold, it was white to all beholders!'),
  ('en.yusufali', 26, 34, '(Pharaoh) said to the Chiefs around him: "This is indeed a sorcerer well-versed:'),
  ('en.yusufali', 26, 35, '"His plan is to get you out of your land by his sorcery; then what is it ye counsel?"'),
  ('en.yusufali', 26, 36, 'They said: "Keep him and his brother in suspense (for a while), and dispatch to the Cities heralds to collect-'),
  ('en.yusufali', 26, 37, '"And bring up to thee all (our) sorcerers well-versed."'),
  ('en.yusufali', 26, 38, 'So the sorcerers were got together for the appointment of a day well-known,'),
  ('en.yusufali', 26, 39, 'And the people were told: "Are ye (now) assembled?-'),
  ('en.yusufali', 26, 40, '"That we may follow the sorcerers (in religion) if they win?"'),
  ('en.yusufali', 26, 41, 'So when the sorcerers arrived, they said to Pharaoh: "Of course - shall we have a (suitable) reward if we win?'),
  ('en.yusufali', 26, 42, 'He said: "Yea, (and more),- for ye shall in that case be (raised to posts) nearest (to my person)."'),
  ('en.yusufali', 26, 43, 'Moses said to them: "Throw ye - that which ye are about to throw!"'),
  ('en.yusufali', 26, 44, 'So they threw their ropes and their rods, and said: "By the might of Pharaoh, it is we who will certainly win!"'),
  ('en.yusufali', 26, 45, 'Then Moses threw his rod, when, behold, it straightway swallows up all the falsehoods which they fake!'),
  ('en.yusufali', 26, 46, 'Then did the sorcerers fall down, prostrate in adoration,'),
  ('en.yusufali', 26, 47, 'Saying: "We believe in the Lord of the Worlds,'),
  ('en.yusufali', 26, 48, '"The Lord of Moses and Aaron."'),
  ('en.yusufali', 26, 49, 'Said (Pharaoh): "Believe ye in Him before I give you permission? surely he is your leader, who has taught you sorcery! but soon shall ye know! Be sure I will cut off your hands and your feet on opposite sides, and I will cause you all to die on the cross!"'),
  ('en.yusufali', 26, 50, 'They said: "No matter! for us, we shall but return to our Lord!'),
  ('en.yusufali', 26, 51, '"Only, our desire is that our Lord will forgive us our faults, that we may become foremost among the believers!"'),
  ('en.yusufali', 26, 52, 'By inspiration we told Moses: "Travel by night with my servants; for surely ye shall be pursued."'),
  ('en.yusufali', 26, 53, 'Then Pharaoh sent heralds to (all) the Cities,'),
  ('en.yusufali', 26, 54, '(Saying): "These (Israelites) are but a small band,'),
  ('en.yusufali', 26, 55, '"And they are raging furiously against us;'),
  ('en.yusufali', 26, 56, '"But we are a multitude amply fore-warned."'),
  ('en.yusufali', 26, 57, 'So We expelled them from gardens, springs,'),
  ('en.yusufali', 26, 58, 'Treasures, and every kind of honourable position;'),
  ('en.yusufali', 26, 59, 'Thus it was, but We made the Children of Israel inheritors of such things.'),
  ('en.yusufali', 26, 60, 'So they pursued them at sunrise.'),
  ('en.yusufali', 26, 61, 'And when the two bodies saw each other, the people of Moses said: "We are sure to be overtaken."'),
  ('en.yusufali', 26, 62, '(Moses) said: "By no means! my Lord is with me! Soon will He guide me!"'),
  ('en.yusufali', 26, 63, 'Then We told Moses by inspiration: "Strike the sea with thy rod." So it divided, and each separate part became like the huge, firm mass of a mountain.'),
  ('en.yusufali', 26, 64, 'And We made the other party approach thither.'),
  ('en.yusufali', 26, 65, 'We delivered Moses and all who were with him;'),
  ('en.yusufali', 26, 66, 'But We drowned the others.'),
  ('en.yusufali', 26, 67, 'Verily in this is a Sign: but most of them do not believe.'),
  ('en.yusufali', 26, 68, 'And verily thy Lord is He, the Exalted in Might, Most Merciful.'),
  ('en.yusufali', 26, 69, 'And rehearse to them (something of) Abraham\'s story.'),
  ('en.yusufali', 26, 70, 'Behold, he said to his father and his people: "What worship ye?"'),
  ('en.yusufali', 26, 71, 'They said: "We worship idols, and we remain constantly in attendance on them."'),
  ('en.yusufali', 26, 72, 'He said: "Do they listen to you when ye call (on them)?"'),
  ('en.yusufali', 26, 73, '"Or do you good or harm?"'),
  ('en.yusufali', 26, 74, 'They said: "Nay, but we found our fathers doing thus (what we do)."'),
  ('en.yusufali', 26, 75, 'He said: "Do ye then see whom ye have been worshipping,-'),
  ('en.yusufali', 26, 76, '"Ye and your fathers before you?-'),
  ('en.yusufali', 26, 77, '"For they are enemies to me; not so the Lord and Cherisher of the Worlds;'),
  ('en.yusufali', 26, 78, '"Who created me, and it is He Who guides me;'),
  ('en.yusufali', 26, 79, '"Who gives me food and drink,'),
  ('en.yusufali', 26, 80, '"And when I am ill, it is He Who cures me;'),
  ('en.yusufali', 26, 81, '"Who will cause me to die, and then to life (again);'),
  ('en.yusufali', 26, 82, '"And who, I hope, will forgive me my faults on the day of Judgment.'),
  ('en.yusufali', 26, 83, '"O my Lord! bestow wisdom on me, and join me with the righteous;'),
  ('en.yusufali', 26, 84, '"Grant me honourable mention on the tongue of truth among the latest (generations);'),
  ('en.yusufali', 26, 85, '"Make me one of the inheritors of the Garden of Bliss;'),
  ('en.yusufali', 26, 86, '"Forgive my father, for that he is among those astray;'),
  ('en.yusufali', 26, 87, '"And let me not be in disgrace on the Day when (men) will be raised up;-'),
  ('en.yusufali', 26, 88, '"The Day whereon neither wealth nor sons will avail,'),
  ('en.yusufali', 26, 89, '"But only he (will prosper) that brings to Allah a sound heart;'),
  ('en.yusufali', 26, 90, '"To the righteous, the Garden will be brought near,'),
  ('en.yusufali', 26, 91, '"And to those straying in Evil, the Fire will be placed in full view;'),
  ('en.yusufali', 26, 92, '"And it shall be said to them: \'Where are the (gods) ye worshipped-'),
  ('en.yusufali', 26, 93, '"\'Besides Allah? Can they help you or help themselves?\''),
  ('en.yusufali', 26, 94, '"Then they will be thrown headlong into the (Fire),- they and those straying in Evil,'),
  ('en.yusufali', 26, 95, '"And the whole hosts of Iblis together.'),
  ('en.yusufali', 26, 96, '"They will say there in their mutual bickerings:'),
  ('en.yusufali', 26, 97, '"\'By Allah, we were truly in an error manifest,'),
  ('en.yusufali', 26, 98, '"\'When we held you as equals with the Lord of the Worlds;'),
  ('en.yusufali', 26, 99, '"\'And our seducers were only those who were steeped in guilt.'),
  ('en.yusufali', 26, 100, '"\'Now, then, we have none to intercede (for us),'),
  ('en.yusufali', 26, 101, '"\'Nor a single friend to feel (for us).'),
  ('en.yusufali', 26, 102, '"\'Now if we only had a chance of return we shall truly be of those who believe!\'"'),
  ('en.yusufali', 26, 103, 'Verily in this is a Sign but most of them do not believe.'),
  ('en.yusufali', 26, 104, 'And verily thy Lord is He, the Exalted in Might, Most Merciful.'),
  ('en.yusufali', 26, 105, 'The people of Noah rejected the messengers.'),
  ('en.yusufali', 26, 106, 'Behold, their brother Noah said to them: "Will ye not fear (Allah)?'),
  ('en.yusufali', 26, 107, '"I am to you a messenger worthy of all trust:'),
  ('en.yusufali', 26, 108, '"So fear Allah, and obey me.'),
  ('en.yusufali', 26, 109, '"No reward do I ask of you for it: my reward is only from the Lord of the Worlds:'),
  ('en.yusufali', 26, 110, '"So fear Allah, and obey me."'),
  ('en.yusufali', 26, 111, 'They said: "Shall we believe in thee when it is the meanest that follow thee?"'),
  ('en.yusufali', 26, 112, 'He said: "And what do I know as to what they do?'),
  ('en.yusufali', 26, 113, '"Their account is only with my Lord, if ye could (but) understand.'),
  ('en.yusufali', 26, 114, '"I am not one to drive away those who believe.'),
  ('en.yusufali', 26, 115, '"I am sent only to warn plainly in public."'),
  ('en.yusufali', 26, 116, 'They said: "If thou desist not, O Noah! thou shalt be stoned (to death)."'),
  ('en.yusufali', 26, 117, 'He said: "O my Lord! truly my people have rejected me.'),
  ('en.yusufali', 26, 118, '"Judge Thou, then, between me and them openly, and deliver me and those of the Believers who are with me."'),
  ('en.yusufali', 26, 119, 'So We delivered him and those with him, in the Ark filled (with all creatures).'),
  ('en.yusufali', 26, 120, 'Thereafter We drowned those who remained behind.'),
  ('en.yusufali', 26, 121, 'Verily in this is a Sign: but most of them do not believe.'),
  ('en.yusufali', 26, 122, 'And verily thy Lord is He, the Exalted in Might, Most Merciful.'),
  ('en.yusufali', 26, 123, 'The \'Ad (people) rejected the messengers.'),
  ('en.yusufali', 26, 124, 'Behold, their brother Hud said to them: "Will ye not fear (Allah)?'),
  ('en.yusufali', 26, 125, '"I am to you a messenger worthy of all trust:'),
  ('en.yusufali', 26, 126, '"So fear Allah and obey me.'),
  ('en.yusufali', 26, 127, '"No reward do I ask of you for it: my reward is only from the Lord of the Worlds.'),
  ('en.yusufali', 26, 128, '"Do ye build a landmark on every high place to amuse yourselves?'),
  ('en.yusufali', 26, 129, '"And do ye get for yourselves fine buildings in the hope of living therein (for ever)?'),
  ('en.yusufali', 26, 130, '"And when ye exert your strong hand, do ye do it like men of absolute power?'),
  ('en.yusufali', 26, 131, '"Now fear Allah, and obey me.'),
  ('en.yusufali', 26, 132, '"Yea, fear Him Who has bestowed on you freely all that ye know.'),
  ('en.yusufali', 26, 133, '"Freely has He bestowed on you cattle and sons,-'),
  ('en.yusufali', 26, 134, '"And Gardens and Springs.'),
  ('en.yusufali', 26, 135, '"Truly I fear for you the Penalty of a Great Day."'),
  ('en.yusufali', 26, 136, 'They said: "It is the same to us whether thou admonish us or be not among (our) admonishers!'),
  ('en.yusufali', 26, 137, '"This is no other than a customary device of the ancients,'),
  ('en.yusufali', 26, 138, '"And we are not the ones to receive Pains and Penalties!"'),
  ('en.yusufali', 26, 139, 'So they rejected him, and We destroyed them. Verily in this is a Sign: but most of them do not believe.'),
  ('en.yusufali', 26, 140, 'And verily thy Lord is He, the Exalted in Might, Most Merciful.'),
  ('en.yusufali', 26, 141, 'The Thamud (people) rejected the messengers.'),
  ('en.yusufali', 26, 142, 'Behold, their brother Salih said to them: "Will you not fear (Allah)?'),
  ('en.yusufali', 26, 143, '"I am to you a messenger worthy of all trust.'),
  ('en.yusufali', 26, 144, '"So fear Allah, and obey me.'),
  ('en.yusufali', 26, 145, '"No reward do I ask of you for it: my reward is only from the Lord of the Worlds.'),
  ('en.yusufali', 26, 146, '"Will ye be left secure, in (the enjoyment of) all that ye have here?-'),
  ('en.yusufali', 26, 147, '"Gardens and Springs,'),
  ('en.yusufali', 26, 148, '"And corn-fields and date-palms with spathes near breaking (with the weight of fruit)?'),
  ('en.yusufali', 26, 149, '"And ye carve houses out of (rocky) mountains with great skill.'),
  ('en.yusufali', 26, 150, '"But fear Allah and obey me;'),
  ('en.yusufali', 26, 151, '"And follow not the bidding of those who are extravagant,-'),
  ('en.yusufali', 26, 152, '"Who make mischief in the land, and mend not (their ways)."'),
  ('en.yusufali', 26, 153, 'They said: "Thou art only one of those bewitched!'),
  ('en.yusufali', 26, 154, '"Thou art no more than a mortal like us: then bring us a Sign, if thou tellest the truth!"'),
  ('en.yusufali', 26, 155, 'He said: "Here is a she-camel: she has a right of watering, and ye have a right of watering, (severally) on a day appointed.'),
  ('en.yusufali', 26, 156, '"Touch her not with harm, lest the Penalty of a Great Day seize you."'),
  ('en.yusufali', 26, 157, 'But they ham-strung her: then did they become full of regrets.'),
  ('en.yusufali', 26, 158, 'But the Penalty seized them. Verily in this is a Sign: but most of them do not believe.'),
  ('en.yusufali', 26, 159, 'And verily thy Lord is He, the Exalted in Might, Most Merciful.'),
  ('en.yusufali', 26, 160, 'The people of Lut rejected the messengers.'),
  ('en.yusufali', 26, 161, 'Behold, their brother Lut said to them: "Will ye not fear (Allah)?'),
  ('en.yusufali', 26, 162, '"I am to you a messenger worthy of all trust.'),
  ('en.yusufali', 26, 163, '"So fear Allah and obey me.'),
  ('en.yusufali', 26, 164, '"No reward do I ask of you for it: my reward is only from the lord of the Worlds.'),
  ('en.yusufali', 26, 165, '"Of all the creatures in the world, will ye approach males,'),
  ('en.yusufali', 26, 166, '"And leave those whom Allah has created for you to be your mates? Nay, ye are a people transgressing (all limits)!"'),
  ('en.yusufali', 26, 167, 'They said: "If thou desist not, O Lut! thou wilt assuredly be cast out!"'),
  ('en.yusufali', 26, 168, 'He said: "I do detest your doings."'),
  ('en.yusufali', 26, 169, '"O my Lord! deliver me and my family from such things as they do!"'),
  ('en.yusufali', 26, 170, 'So We delivered him and his family,- all'),
  ('en.yusufali', 26, 171, 'Except an old woman who lingered behind.'),
  ('en.yusufali', 26, 172, 'But the rest We destroyed utterly.'),
  ('en.yusufali', 26, 173, 'We rained down on them a shower (of brimstone): and evil was the shower on those who were admonished (but heeded not)!'),
  ('en.yusufali', 26, 174, 'Verily in this is a Sign: but most of them do not believe.'),
  ('en.yusufali', 26, 175, 'And verily thy Lord is He, the Exalted in Might Most Merciful.'),
  ('en.yusufali', 26, 176, 'The Companions of the Wood rejected the messengers.'),
  ('en.yusufali', 26, 177, 'Behold, Shu\'aib said to them: "Will ye not fear (Allah)?'),
  ('en.yusufali', 26, 178, '"I am to you a messenger worthy of all trust.'),
  ('en.yusufali', 26, 179, '"So fear Allah and obey me.'),
  ('en.yusufali', 26, 180, '"No reward do I ask of you for it: my reward is only from the Lord of the Worlds.'),
  ('en.yusufali', 26, 181, '"Give just measure, and cause no loss (to others by fraud).'),
  ('en.yusufali', 26, 182, '"And weigh with scales true and upright.'),
  ('en.yusufali', 26, 183, '"And withhold not things justly due to men, nor do evil in the land, working mischief.'),
  ('en.yusufali', 26, 184, '"And fear Him Who created you and (who created) the generations before (you)"'),
  ('en.yusufali', 26, 185, 'They said: "Thou art only one of those bewitched!'),
  ('en.yusufali', 26, 186, '"Thou art no more than a mortal like us, and indeed we think thou art a liar!'),
  ('en.yusufali', 26, 187, '"Now cause a piece of the sky to fall on us, if thou art truthful!"'),
  ('en.yusufali', 26, 188, 'He said: "My Lord knows best what ye do."'),
  ('en.yusufali', 26, 189, 'But they rejected him. Then the punishment of a day of overshadowing gloom seized them, and that was the Penalty of a Great Day.'),
  ('en.yusufali', 26, 190, 'Verily in that is a Sign: but most of them do not believe.'),
  ('en.yusufali', 26, 191, 'And verily thy Lord is He, the Exalted in Might, Most Merciful.'),
  ('en.yusufali', 26, 192, 'Verily this is a Revelation from the Lord of the Worlds:'),
  ('en.yusufali', 26, 193, 'With it came down the spirit of Faith and Truth-'),
  ('en.yusufali', 26, 194, 'To thy heart and mind, that thou mayest admonish.'),
  ('en.yusufali', 26, 195, 'In the perspicuous Arabic tongue.'),
  ('en.yusufali', 26, 196, 'Without doubt it is (announced) in the mystic Books of former peoples.'),
  ('en.yusufali', 26, 197, 'Is it not a Sign to them that the Learned of the Children of Israel knew it (as true)?'),
  ('en.yusufali', 26, 198, 'Had We revealed it to any of the non-Arabs,'),
  ('en.yusufali', 26, 199, 'And had he recited it to them, they would not have believed in it.'),
  ('en.yusufali', 26, 200, 'Thus have We caused it to enter the hearts of the sinners.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 26, 201, 'They will not believe in it until they see the grievous Penalty;'),
  ('en.yusufali', 26, 202, 'But the (Penalty) will come to them of a sudden, while they perceive it not;'),
  ('en.yusufali', 26, 203, 'Then they will say: "Shall we be respited?"'),
  ('en.yusufali', 26, 204, 'Do they then ask for Our Penalty to be hastened on?'),
  ('en.yusufali', 26, 205, 'Seest thou? If We do let them enjoy (this life) for a few years,'),
  ('en.yusufali', 26, 206, 'Yet there comes to them at length the (Punishment) which they were promised!'),
  ('en.yusufali', 26, 207, 'It will profit them not that they enjoyed (this life)!'),
  ('en.yusufali', 26, 208, 'Never did We destroy a population, but had its warners -'),
  ('en.yusufali', 26, 209, 'By way of reminder; and We never are unjust.'),
  ('en.yusufali', 26, 210, 'No evil ones have brought down this (Revelation):'),
  ('en.yusufali', 26, 211, 'It would neither suit them nor would they be able (to produce it).'),
  ('en.yusufali', 26, 212, 'Indeed they have been removed far from even (a chance of) hearing it.'),
  ('en.yusufali', 26, 213, 'So call not on any other god with Allah, or thou wilt be among those under the Penalty.'),
  ('en.yusufali', 26, 214, 'And admonish thy nearest kinsmen,'),
  ('en.yusufali', 26, 215, 'And lower thy wing to the Believers who follow thee.'),
  ('en.yusufali', 26, 216, 'Then if they disobey thee, say: "I am free (of responsibility) for what ye do!"'),
  ('en.yusufali', 26, 217, 'And put thy trust on the Exalted in Might, the Merciful,-'),
  ('en.yusufali', 26, 218, 'Who seeth thee standing forth (in prayer),'),
  ('en.yusufali', 26, 219, 'And thy movements among those who prostrate themselves,'),
  ('en.yusufali', 26, 220, 'For it is He Who heareth and knoweth all things.'),
  ('en.yusufali', 26, 221, 'Shall I inform you, (O people!), on whom it is that the evil ones descend?'),
  ('en.yusufali', 26, 222, 'They descend on every lying, wicked person,'),
  ('en.yusufali', 26, 223, '(Into whose ears) they pour hearsay vanities, and most of them are liars.'),
  ('en.yusufali', 26, 224, 'And the Poets,- It is those straying in Evil, who follow them:'),
  ('en.yusufali', 26, 225, 'Seest thou not that they wander distracted in every valley?-'),
  ('en.yusufali', 26, 226, 'And that they say what they practise not?-'),
  ('en.yusufali', 26, 227, 'Except those who believe, work righteousness, engage much in the remembrance of Allah, and defend themselves only after they are unjustly attacked. And soon will the unjust assailants know what vicissitudes their affairs will take!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 26, 1, 'Taa-Seeen-Meeem'),
  ('en.transliteration', 26, 2, 'Tilka Aayaatul Kitaabil Mubeen'),
  ('en.transliteration', 26, 3, 'La\'allaka baakhi\'un nafsaka allaa yakoonoo mu\'mineen'),
  ('en.transliteration', 26, 4, 'In nashaa nunazzil \'alaihim minas samaaa\'i Aayatan fazallat a\'naaquhum lahaa khaadi\'een'),
  ('en.transliteration', 26, 5, 'Wa maa yaateehim min zikrim minar Rahmaani muhdasin illaa kaanoo \'anhu mu\'rideen'),
  ('en.transliteration', 26, 6, 'Faqad kazzaboo fasa yaateehim ambaaa\'u maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 26, 7, 'Awa lam yaraw ilal ardi kam ambatnaa feehaa min kulli zawjin kareem'),
  ('en.transliteration', 26, 8, 'Inn fee zaalika la Aayah; wa maa kaana aksaruhum mu\'mineen'),
  ('en.transliteration', 26, 9, 'Wa inna Rabbaka la Huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 10, 'Wa iz naadaa Rabbuka Moosaaa ani\'-til qawmaz zaalimeen'),
  ('en.transliteration', 26, 11, 'Qawma Fir\'awn; alaa yattaqoon'),
  ('en.transliteration', 26, 12, 'Qaala Rabbi inneee akhaafu ai yukazziboon'),
  ('en.transliteration', 26, 13, 'Wa yadeequ sadree wa laa yantaliqu lisaanee fa arsil ilaa Haaroon'),
  ('en.transliteration', 26, 14, 'Wa lahum \'alaiya zambun fa akhaafu ai yaqtuloon'),
  ('en.transliteration', 26, 15, 'Qaala kallaa fazhabaa bi Aayaatinaaa innaa ma\'akum mustami\'oon'),
  ('en.transliteration', 26, 16, 'Faatiyaa Fir\'awna faqoolaaa innaa Rasoolu Rabbil \'aalameen'),
  ('en.transliteration', 26, 17, 'An arsil ma\'anaa Baneee Israaa\'eel'),
  ('en.transliteration', 26, 18, 'Qaala alam nurabbika feenaa waleedanw wa labista feenaa min \'umurika sineen'),
  ('en.transliteration', 26, 19, 'Wa fa\'alta fa\'latakal latee fa\'alta wa anta minal kaafireen'),
  ('en.transliteration', 26, 20, 'Qaala fa\'altuhaaa izanw wa ana minad daaaleen'),
  ('en.transliteration', 26, 21, 'Fafarartu minkum lam maa khiftukum fawahaba lee Rabbee hukmanw wa ja\'alanee minal mursaleen'),
  ('en.transliteration', 26, 22, 'Wa tilka ni\'matun tamun nuhaa \'alaiya an \'abbatta Baneee Israaa\'eel'),
  ('en.transliteration', 26, 23, 'Qaala Fir\'awnu wa maa Rabbul \'aalameen'),
  ('en.transliteration', 26, 24, 'Qaala Rabbus samaawaati wal ardi wa maa bainahumaa in kuntum mooqineen'),
  ('en.transliteration', 26, 25, 'Qaala liman hawlahooo alaa tastami\'oon'),
  ('en.transliteration', 26, 26, 'Qaala Rabbukum wa Rabbu aabaaa\'ikumul awwaleen'),
  ('en.transliteration', 26, 27, 'Qaala inna Rasoolakumul lazee ursila ilaikum lamajnoon'),
  ('en.transliteration', 26, 28, 'Qaala Rabbul mashriqi wal maghribi wa maa baina humaa in kuntum ta\'qiloon'),
  ('en.transliteration', 26, 29, 'Qaala la\'init takhazta ilaahan ghairee la aj\'alannaka minal masjooneen'),
  ('en.transliteration', 26, 30, 'Qaala awalw ji\'tuka bishai\'im mubeen'),
  ('en.transliteration', 26, 31, 'Qaala faati biheee in kunta minas saadiqeen'),
  ('en.transliteration', 26, 32, 'Fa alqaa \'asaahu fa izaaa hiya su\'baanum mubeen'),
  ('en.transliteration', 26, 33, 'Wa naza\'a yadahoo faizaa hiya baidaaa\'u linnaa zireen'),
  ('en.transliteration', 26, 34, 'Qaala lilmala-i hawlahooo inna haazaa lasaahirun \'aleem'),
  ('en.transliteration', 26, 35, 'Yureedu ai yukhrijakum min ardikum bisihrihee famaazaa taamuroon'),
  ('en.transliteration', 26, 36, 'Qaalooo arjih wa akhaahu wab\'as filmadaaa\'ini haashireen'),
  ('en.transliteration', 26, 37, 'Yaatooka bikulli sah haarin \'aleem'),
  ('en.transliteration', 26, 38, 'Fa jumi\'as saharatu limeeqaati Yawmim ma\'loom'),
  ('en.transliteration', 26, 39, 'Wa qeela linnaasi hal antum mujtami\'oon'),
  ('en.transliteration', 26, 40, 'La\'allanaa nattabi\'us saharata in kaanoo humul ghaalibeen'),
  ('en.transliteration', 26, 41, 'Falammaa jaaa\'as saharatu qaaloo li Fir\'awna a\'inna lanaa la ajjran in kunnaa nahnul ghaalibeen'),
  ('en.transliteration', 26, 42, 'Qaala na\'am wa innakum izal laminal muqarrabeen'),
  ('en.transliteration', 26, 43, 'Qaala lahum Moosaaa alqoo maaa antum mulqoon'),
  ('en.transliteration', 26, 44, 'Fa alqaw hibaalahum wa \'isiyyahum wa qaaloo bi\'izzati Fir\'awna innaa lanahnul ghaaliboon'),
  ('en.transliteration', 26, 45, 'Fa alqaa Moosaa \'asaahu fa izaa hiya talqafu maa yaafikoon'),
  ('en.transliteration', 26, 46, 'Fa ulqiyas saharatu saajideen'),
  ('en.transliteration', 26, 47, 'Qaalooo aamannaa bi Rabbil \'aalameen'),
  ('en.transliteration', 26, 48, 'Rabbi Moosaa wa Haaroon'),
  ('en.transliteration', 26, 49, 'Qaala aamantum lahoo qabla an aazana lakum innahoo lakabeerukumul lazee \'alla makumus sihra falasawfa ta\'lamoon; la uqatti\'anna aidiyakum wa arjulakum min khilaafinw wa la usallibanna kum ajma\'een'),
  ('en.transliteration', 26, 50, 'Qaaloo la daira innaaa ilaa Rabbinaa munqalliboon'),
  ('en.transliteration', 26, 51, 'Innaa natma\'u ai yaghfira lanaa Rabbunna khataa yaanaaa an kunnaaa awwalal mu\'mineen'),
  ('en.transliteration', 26, 52, 'Wa awhainaaa ilaa Moosaaa an asri bi\'ibaadeee innakum muttaba\'oon'),
  ('en.transliteration', 26, 53, 'Fa arsala Fir\'awnu filmadaaa\'ini haashireen'),
  ('en.transliteration', 26, 54, 'Inna haaa\'ulaaa\'i lashir zimatun qaleeloon'),
  ('en.transliteration', 26, 55, 'Wa innahum lanaa laghaaa\'izoon'),
  ('en.transliteration', 26, 56, 'Wa innaa lajamee\'un haaziroon'),
  ('en.transliteration', 26, 57, 'Fa akhrajnaahum min Jannaatinw wa \'uyoon'),
  ('en.transliteration', 26, 58, 'Wa kunoozinw wa ma qaamin kareem'),
  ('en.transliteration', 26, 59, 'Kazaalika wa awrasnaahaa Baneee Israaa\'eel'),
  ('en.transliteration', 26, 60, 'Fa atba\'oohum mushriqeen'),
  ('en.transliteration', 26, 61, 'Falammaa taraaa\'al jam\'aani qaala as haabu Moosaaa innaa lamudrakoon'),
  ('en.transliteration', 26, 62, 'Qaala kallaaa inna ma\'iya Rabbee sa yahdeen'),
  ('en.transliteration', 26, 63, 'Fa awhainaaa ilaa Moosaaa anidrib bi\'asaakal bahra fanfalaqa fakaana kullu firqin kattawdil \'azeem'),
  ('en.transliteration', 26, 64, 'Wa azlafnaa sammal aakhareen'),
  ('en.transliteration', 26, 65, 'Wa anjainaa Moosaa wa mam ma\'ahooo ajma\'een'),
  ('en.transliteration', 26, 66, 'Summa aghraqnal aakhareen'),
  ('en.transliteration', 26, 67, 'Inna fee zaalika la Aayaah; wa maa kaana aksaru hu mu\'mineen'),
  ('en.transliteration', 26, 68, 'Wa inna Rabbaka la Huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 69, 'Watlu \'alaihim naba-a Ibraaheem'),
  ('en.transliteration', 26, 70, 'Iz qaala li abeehi wa qawmihee maa ta\'budoon'),
  ('en.transliteration', 26, 71, 'Qaaloo na\'budu asnaaman fanazallu lahaa \'aakifeen'),
  ('en.transliteration', 26, 72, 'Qaala hal yasma\'oona kum iz tad\'oon'),
  ('en.transliteration', 26, 73, 'Aw yanfa\'oonakum aw yadurroon'),
  ('en.transliteration', 26, 74, 'Qaaloo bal wajadnaaa aabaaa \'anaa kazaalika yaf\'aloon'),
  ('en.transliteration', 26, 75, 'Qaala afara \'aitum maa kuntum ta\'budoon'),
  ('en.transliteration', 26, 76, 'Antum wa aabaaa\'ukumul aqdamoon'),
  ('en.transliteration', 26, 77, 'Fa innahum \'aduwwwul leee illaa Rabbal \'aalameen'),
  ('en.transliteration', 26, 78, 'Allazee khalaqanee fa Huwa yahdeen'),
  ('en.transliteration', 26, 79, 'Wallazee Huwa yut\'imunee wa yasqeen'),
  ('en.transliteration', 26, 80, 'Wa izaa mardtu fahuwa yashfeen'),
  ('en.transliteration', 26, 81, 'Wallazee yumeetunee summa yuhyeen'),
  ('en.transliteration', 26, 82, 'Wallazeee atma\'u ai yaghfira lee khateee\' atee Yawmad Deen'),
  ('en.transliteration', 26, 83, 'Rabbi hab lee hukmanw wa alhiqnee bis saaliheen'),
  ('en.transliteration', 26, 84, 'Waj\'al lee lisaana sidqin fil aakhireen'),
  ('en.transliteration', 26, 85, 'Waj\'alnee minw warasati Jannnatin Na\'eem'),
  ('en.transliteration', 26, 86, 'Waghfir li abeee innahoo kaana mind daalleen'),
  ('en.transliteration', 26, 87, 'Wa laa tukhzinee Yawma yub\'asoon'),
  ('en.transliteration', 26, 88, 'Yawma laa yanfa\'u maalunw wa laa banoon'),
  ('en.transliteration', 26, 89, 'Illaa man atal laaha biqalbin saleem'),
  ('en.transliteration', 26, 90, 'Wa uzlifatil Jannatu lilmuttaqeen'),
  ('en.transliteration', 26, 91, 'Wa burrizatil Jaheemu lilghaaween'),
  ('en.transliteration', 26, 92, 'Wa qeela lahum aina maa kuntum ta\'budoon'),
  ('en.transliteration', 26, 93, 'Min doonil laahi hal yansuroonakum aw yantasiroon'),
  ('en.transliteration', 26, 94, 'Fakubkiboo feehaa hum walghaawoon'),
  ('en.transliteration', 26, 95, 'Wa junoodu Ibleesa ajma\'oon'),
  ('en.transliteration', 26, 96, 'Qaaloo wa hum feehaa yakkhtasimoon'),
  ('en.transliteration', 26, 97, 'Tallaahi in kunnaa lafee dalaalim mubeen'),
  ('en.transliteration', 26, 98, 'Iz nusawweekum bi Rabbil \'aalameen'),
  ('en.transliteration', 26, 99, 'Wa maaa adallanaaa illal mujrimoon'),
  ('en.transliteration', 26, 100, 'Famaa lanaa min shaa fi\'een'),
  ('en.transliteration', 26, 101, 'Wa laa sadeeqin hameem'),
  ('en.transliteration', 26, 102, 'Falaw anna lanaa karratan fanakoona minal mu\'mineen'),
  ('en.transliteration', 26, 103, 'Inna fee zaalika la Aayatanw wa maa kaana aksaruhum mu\'mineen'),
  ('en.transliteration', 26, 104, 'Wa inna Rabbaka la Huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 105, 'Kazzabat qawmu Noohinil Mursaleen'),
  ('en.transliteration', 26, 106, 'Iz qaala lahum akhoohum Noohun alaa tattaqoon'),
  ('en.transliteration', 26, 107, 'Innee lakum Rasoolun ameen'),
  ('en.transliteration', 26, 108, 'Fattaqullaaha wa atee\'oon'),
  ('en.transliteration', 26, 109, 'Wa maaa as\'alukum \'alaihi min ajrin in ajriya illaa \'alaa Rabbil \'aalameen'),
  ('en.transliteration', 26, 110, 'Fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 26, 111, 'Qaalooo anu\'minu laka wattaba \'akal arzaloon'),
  ('en.transliteration', 26, 112, 'Qaala wa maa \'ilmee bimaa kaanoo ya\'maloon'),
  ('en.transliteration', 26, 113, 'In hisaabuhum illaa \'alaa Rabbee law tash\'uroon'),
  ('en.transliteration', 26, 114, 'Wa maaa ana bitaaridil mu\'mineen'),
  ('en.transliteration', 26, 115, 'In ana illaa nazeerum mubeen'),
  ('en.transliteration', 26, 116, 'Qaaloo la\'il lam tantahi yaa Noohu latakoonanna minal marjoomeen'),
  ('en.transliteration', 26, 117, 'Qaala Rabbi inna qawmee kazzaboon'),
  ('en.transliteration', 26, 118, 'Faftab bainee wa bai nahum fat hanw wa najjinee wa mam ma\'iya minal mu\'mineen'),
  ('en.transliteration', 26, 119, 'Fa anjainaahu wa mamma\'ahoo fil fulkil mashhoon'),
  ('en.transliteration', 26, 120, 'Summa aghraqnaa ba\'dul baaqeen'),
  ('en.transliteration', 26, 121, 'Inna fee zaalika la Aayaah; wa maa kaana aksaruhum mu\'mineen'),
  ('en.transliteration', 26, 122, 'Wa inna Rabbaka la huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 123, 'Kazzabat \'Aadunil mursaleen'),
  ('en.transliteration', 26, 124, 'Iz qaala lahum akhoohum Hoodun alaa tattaqoon'),
  ('en.transliteration', 26, 125, 'Innee lakum Rasoolun ameen'),
  ('en.transliteration', 26, 126, 'Fattaqullaaha wa atee\'oon'),
  ('en.transliteration', 26, 127, 'Wa maa as\'alukum \'alaihi min ajrin in ajriya illaa \'alaa Rabbil \'aalameen'),
  ('en.transliteration', 26, 128, 'Atabnoona bikulli ree\'in aayatan ta\'basoon'),
  ('en.transliteration', 26, 129, 'Wa tattakhizoona masaani\'a la\'allakum takhludoon'),
  ('en.transliteration', 26, 130, 'Wa izaa batashtum batashtum jabbaareen'),
  ('en.transliteration', 26, 131, 'Fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 26, 132, 'Wattaqul lazeee amad dakum bimaa ta\'lamoon'),
  ('en.transliteration', 26, 133, 'Amaddakum bi an\'aa minw wa baneen'),
  ('en.transliteration', 26, 134, 'Wa jannaatinw wa \'uyoon'),
  ('en.transliteration', 26, 135, 'Innee akhaafu \'alaikum \'azaaba Yawmin \'azeem'),
  ('en.transliteration', 26, 136, 'Qaaloo sawaaa\'un \'alainaaa awa \'azta am lam takum minal waa\'izeen'),
  ('en.transliteration', 26, 137, 'In haazaaa illaa khuluqul awwaleen'),
  ('en.transliteration', 26, 138, 'Wa maa nahnu bimu \'azzabeen'),
  ('en.transliteration', 26, 139, 'Fakazzaboohu fa ahlaknaahum; inna fee zaalika la aayah; wa maa kaana aksaruhum mu\'mineen'),
  ('en.transliteration', 26, 140, 'Wa inna Rabbaka la huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 141, 'Kazzabat Samoodul mursaleen'),
  ('en.transliteration', 26, 142, 'Iz qaala lahum akhoohum Saalihun alaa tattaqoon'),
  ('en.transliteration', 26, 143, 'Innee lakum Rasoolun ameen'),
  ('en.transliteration', 26, 144, 'Fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 26, 145, 'Wa maaa as\'alukum \'alaihi min ajrin in ajriya illaa \'alaa Rabbil \'aalameen'),
  ('en.transliteration', 26, 146, 'Atutrakoona fee maa haahunnaaa aamineen'),
  ('en.transliteration', 26, 147, 'Fee jannaatinw wa \'uyoon'),
  ('en.transliteration', 26, 148, 'Wa zuroo inw wa nakhlin tal \'uhaa hadeem'),
  ('en.transliteration', 26, 149, 'Wa tanhitoona minal jibaali buyootan faariheen'),
  ('en.transliteration', 26, 150, 'Fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 26, 151, 'Wa laa tutee\'ooo amral musrifeen'),
  ('en.transliteration', 26, 152, 'Allazeena yufsidoona fil ardi wa laa yuslihoon'),
  ('en.transliteration', 26, 153, 'Qaalooo innamaa anta minal musahhareen'),
  ('en.transliteration', 26, 154, 'Maaa anta illaa basharum mislunaa faati bi Aayatin in kunta minas saadiqeen'),
  ('en.transliteration', 26, 155, 'Qaala haazihee naaqatul lahaa shirbunw w alakum shirbu yawmim ma\'loom'),
  ('en.transliteration', 26, 156, 'Wa laa tamassoohaa bisooo\'in fa yaakhuzakum \'azaabu Yawmin \'Azeem'),
  ('en.transliteration', 26, 157, 'Fa\'aqaroohaa fa asbahoo naadimeen'),
  ('en.transliteration', 26, 158, 'Fa akhazahumul \'azaab; inna fee zaalika la Aayah; wa maa kaana aksaruhum m\'mineen'),
  ('en.transliteration', 26, 159, 'Wa inna Rabbaka la Huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 160, 'kazzabat qawmu Lootinil mursaleen'),
  ('en.transliteration', 26, 161, 'Iz qaala lahum akhoohum Lootun alaa tattaqoon'),
  ('en.transliteration', 26, 162, 'Innee lakum rasoolun ameen'),
  ('en.transliteration', 26, 163, 'Fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 26, 164, 'Wa maaa as\'alukum \'alaihi min ajrin in ajriya illaa \'alaa Rabbil \'aalameen'),
  ('en.transliteration', 26, 165, 'Ataatoonaz zukraana minal \'aalameen'),
  ('en.transliteration', 26, 166, 'Wa tazaroona maa khalaqa lakum Rabbukum min azwaajikum; bal antum qawmun \'aadoon'),
  ('en.transliteration', 26, 167, 'Qaloo la\'il lam tantahi yaa Lootu latakoonanna minal mukhrajeen'),
  ('en.transliteration', 26, 168, 'Qaala innee li\'amalikum minal qaaleen'),
  ('en.transliteration', 26, 169, 'Rabbi najjjinee wa ahlee mimmmaa ya\'maloon'),
  ('en.transliteration', 26, 170, 'Fanajjainaahu wa ahlahooo ajma\'een'),
  ('en.transliteration', 26, 171, 'Illaa \'ajoozan filghaabireen'),
  ('en.transliteration', 26, 172, 'Summa dammarnal aa khareen'),
  ('en.transliteration', 26, 173, 'Wa amtarnaa \'alaihim mataran fasaaa\'a matarul munzareen'),
  ('en.transliteration', 26, 174, 'Inna fee zaalika la Aayah; wa maa kaana aksaruhum mu\'mineen'),
  ('en.transliteration', 26, 175, 'Wa inna Rabbaka la Huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 176, 'Kazzaba As haabul Aykatil mursaleen'),
  ('en.transliteration', 26, 177, 'Iz qaala lahum Shu\'aybun alaa tattaqoon'),
  ('en.transliteration', 26, 178, 'Innee lakum Rasoolun ameen'),
  ('en.transliteration', 26, 179, 'Fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 26, 180, 'Wa maaa as\'alukum \'alaihi min ajrin in ajriya illaa \'alaa Rabbil \'aalameen'),
  ('en.transliteration', 26, 181, 'Awful kaila wa laa takoonoo minal mukhsireen'),
  ('en.transliteration', 26, 182, 'Wa zinoo bilqistaasil mustaqeem'),
  ('en.transliteration', 26, 183, 'Wa laa tabkhasun naasa ashyaaa \'ahum wa laa ta\'saw fil ardi mufsideen'),
  ('en.transliteration', 26, 184, 'Wattaqul lazee khalaqakum waljibillatal awwaleen'),
  ('en.transliteration', 26, 185, 'Qaalooo innamaa anta minal musahhareen'),
  ('en.transliteration', 26, 186, 'Wa maaa anta illaa basharum mislunaa wa innazunnuka laminal kaazibeen'),
  ('en.transliteration', 26, 187, 'Fa asqit \'alainaa kisafam minas samaaa\'i in kunta minas saadiqeen'),
  ('en.transliteration', 26, 188, 'Qaala Rabbeee a\'lamu bimaa ta\'maloon'),
  ('en.transliteration', 26, 189, 'Fakazzaboohu fa akhazahum \'azaabu Yawmiz zullah; innahoo kaana \'azaaba Yawmin \'Azeem'),
  ('en.transliteration', 26, 190, 'Inna fee zaalika la Aayah; wa maa kaana aksaruhum mu\'mineen'),
  ('en.transliteration', 26, 191, 'Wa inna Rabbaka la huwal \'Azeezur Raheem'),
  ('en.transliteration', 26, 192, 'Wa innahoo latanzeelu Rabbil \'aalameen'),
  ('en.transliteration', 26, 193, 'Nazala bihir Roohul Ameen'),
  ('en.transliteration', 26, 194, '\'Alaa qalbika litakoona minal munzireen'),
  ('en.transliteration', 26, 195, 'Bilisaanin \'Arabiyyim mubeen'),
  ('en.transliteration', 26, 196, 'Wa innahoo lafee Zuburil awwaleen'),
  ('en.transliteration', 26, 197, 'Awalam yakul lahum Aayatan ai ya\'lamahoo \'ulamaaa\'u Baneee Israaa\'eel'),
  ('en.transliteration', 26, 198, 'Wa law nazzalnaahu \'alaa ba\'dil a\'jameen'),
  ('en.transliteration', 26, 199, 'Faqara ahoo \'alaihim maa kaanoo bihee mu\'mineen'),
  ('en.transliteration', 26, 200, 'Kazaalika salaknaahu fee quloobil mujrimeen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 26, 201, 'Laa yu\'minoona bihee hattaa yarawul \'azaabal aleem'),
  ('en.transliteration', 26, 202, 'Fayaatiyahum baghtatanw wa hum laa yash\'uroon'),
  ('en.transliteration', 26, 203, 'Fa yaqooloo hal nahnu munzaroon'),
  ('en.transliteration', 26, 204, 'Aafabi \'azaabinaa yasta\'jiloon'),
  ('en.transliteration', 26, 205, 'Aara\'aita im matta\'naahum sineen'),
  ('en.transliteration', 26, 206, 'Summa jaaa\'ahum maa kaanoo yoo\'adoon'),
  ('en.transliteration', 26, 207, 'Maaa aghnaaa \'anhum maa kaanoo yumaatoo\'oon'),
  ('en.transliteration', 26, 208, 'Wa maaa ahlaknaa min qaryatin illaa lahaa munziroon'),
  ('en.transliteration', 26, 209, 'Zikraa wa maa kunnaa zaalimeen'),
  ('en.transliteration', 26, 210, 'Wa maa tanazzalat bihish Shayaateen'),
  ('en.transliteration', 26, 211, 'Wa maa yambaghee lahum wa maa yastatee\'oon'),
  ('en.transliteration', 26, 212, 'Innahum \'anis sam\'i lama\'zooloon'),
  ('en.transliteration', 26, 213, 'Falaa tad\'u ma\'al laahi ilaahan aakhara fatakoona minal mu\'azzabeen'),
  ('en.transliteration', 26, 214, 'Wa anzir \'asheeratakal aqrabeen'),
  ('en.transliteration', 26, 215, 'Wakhfid janaahaka limanit taba \'aka minal mu\'mineen'),
  ('en.transliteration', 26, 216, 'Fa in asawka faqul innee bareee\'um mimmmaa ta\'maloon'),
  ('en.transliteration', 26, 217, 'Wa tawakkal alal \'Azeezir Raheem'),
  ('en.transliteration', 26, 218, 'Allazee yaraaka heena taqoom'),
  ('en.transliteration', 26, 219, 'Wa taqallubaka fis saajideen'),
  ('en.transliteration', 26, 220, 'Innahoo Huwas Samee\'ul \'Aleem'),
  ('en.transliteration', 26, 221, 'Hal unabbi\'ukum \'alaa man tanazzalush Shayaateen'),
  ('en.transliteration', 26, 222, 'Tanazzalu \'alaa kulli affaakin aseem'),
  ('en.transliteration', 26, 223, 'Yulqoonas sam\'a wa aksaruhum aaziboon'),
  ('en.transliteration', 26, 224, 'Washshu \'araaa\'u yattabi \'uhumul ghaawoon'),
  ('en.transliteration', 26, 225, 'Alam tara annahum fee kulli waadiny yaheemoon'),
  ('en.transliteration', 26, 226, 'Wa annahum yaqooloona ma laa yaf\'aloon'),
  ('en.transliteration', 26, 227, 'Illal lazeena aamanoo w a\'amilus saalihaati wa zakarul laaha kaseeranw wantasaroo mim ba\'di maa zulimoo; wa saya\'lamul lazeena zalamooo aiya munqalbiny yanqaliboon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 26, 1, 'طسمۤ'),
  ('ur.ahmedali', 26, 2, 'یہ روشن کتاب کی آیتیں ہیں'),
  ('ur.ahmedali', 26, 3, 'شاید تو اپنی جان ہلاک کرنے والا ہے اس لیے کہ وہ ایمان نہیں لاتے'),
  ('ur.ahmedali', 26, 4, 'اگر ہم چاہیں تو ان پر آسمان سے ایسی نشانی نازل کریں کہ اس کے آگے ان کی گردنیں جھک جائیں'),
  ('ur.ahmedali', 26, 5, 'اور ان کے پاس رحمنٰ کی طرف سے کوئی نئی بات نصیحت کی ایسی نہیں آئی کہ وہ اس سے منہ نہ موڑ لیتے ہوں'),
  ('ur.ahmedali', 26, 6, 'سو یہ جھٹلاتو چکے اب ان کے پاس اس چیز کی حقیقت آئے گی جس پر ٹھٹھا کیا کرتے تھے'),
  ('ur.ahmedali', 26, 7, 'کیا وہ زمین کو نہیں دیکھتے ہم نے اس میں ہر ایک قسم کی کتنی عمدہ چیزیں اُگائی ہیں'),
  ('ur.ahmedali', 26, 8, 'البتہ اس میں بڑی نشانی ہے اور ان میں سے اکثر ایمان لانے والے نہیں'),
  ('ur.ahmedali', 26, 9, 'اور بے شک تیرا رب زبردست رحم کرنے والا ہے'),
  ('ur.ahmedali', 26, 10, 'اور جب تیرے رب نے موسیٰ کو پکارا کہ اس ظالم قوم کے پاس جا'),
  ('ur.ahmedali', 26, 11, 'فرعون کی قوم کے پاس کیا وہ ڈرتے نہیں'),
  ('ur.ahmedali', 26, 12, 'عرض کی اے میرے رب میں ڈرتا ہوں کہ مجھے جھٹلا دیں'),
  ('ur.ahmedali', 26, 13, 'اور میرا سینہ تنگ ہوجائے اور میری زبان نہ چلے پس ہارون کو پیغام دے'),
  ('ur.ahmedali', 26, 14, 'اور میرے ذمہ ان کا ایک گناہ بھی ہے سو میں ڈرتا ہوں کہ مجھے مار نہ ڈالیں'),
  ('ur.ahmedali', 26, 15, 'فرمایا ہر گز نہیں تم دونوں ہماری نشانیاں لے کر جاؤ ہم تمہارے ساتھ سننے والے ہیں'),
  ('ur.ahmedali', 26, 16, 'سو فرعون کے پاس جاؤ اور کہو کہ ہم پروردگار عالم کا پیغام لے کر آئے ہیں'),
  ('ur.ahmedali', 26, 17, 'یہ کہ ہمارے ساتھ بنی اسرائیل کو بھیج دے'),
  ('ur.ahmedali', 26, 18, 'کہا کیا ہم نےتمہیں بچپن میں پرورش نہیں کیا اورتو نے ہم میں اپنی عمر کے کئی سال گزارے'),
  ('ur.ahmedali', 26, 19, 'اور تو اپنا وہ کرتوت کر گیا جوکر گیا اور تو ناشکروں میں سے ہے'),
  ('ur.ahmedali', 26, 20, 'کہا جب میں نے وہ کام کیا تھاتو میں بےخبر تھا'),
  ('ur.ahmedali', 26, 21, 'پھر میں تم سے تمہارے ڈر کے مارے بھاگ گیا تب مجھے میرے رب نے دانائی عطا کی اور مجھے رسول بنایا'),
  ('ur.ahmedali', 26, 22, 'اور یہ احسان جو تو مجھ پر رکھتا ہے اسی لیے تو نے بنی اسرائیل کو غلام بنا رکھا ہے'),
  ('ur.ahmedali', 26, 23, 'فرعون نے کہا رب العالمین کیا چیز ہے'),
  ('ur.ahmedali', 26, 24, 'فرمایا آسمانوں اور زمین اور جو کچھ ان کے درمیان ہے سب کا پروردگار ہے اگر تمہیں یقین آئے'),
  ('ur.ahmedali', 26, 25, 'اپنے گرد والوں سے کہا کیا تم سنتے نہیں ہو'),
  ('ur.ahmedali', 26, 26, 'فرمایا تمہارا ور تمہارے پہلے باپ دادا کا رب ہے'),
  ('ur.ahmedali', 26, 27, 'کہا بے شک تمہارا رسول جو تمہارے پاس بھیجا گیا ہے ضرور دیوانہ ہے'),
  ('ur.ahmedali', 26, 28, 'فرمایا مشر ق مغرب اور جو ان کے درمیان ہے سب کا پروردگار ہے اگر تم عقل رکھتے ہو'),
  ('ur.ahmedali', 26, 29, 'کہا اگر تو نے میرے سوا اور کوئی معبود بنایا تو تمہیں قید میں ڈال دوں گا'),
  ('ur.ahmedali', 26, 30, 'فرمایا اگرچہ میں تیرے پاس ایک روشن چیز لے آؤں'),
  ('ur.ahmedali', 26, 31, 'کہا اگر تو سچا ہے تو وہ چیز لا'),
  ('ur.ahmedali', 26, 32, 'پھر اس نےاپناعصا ڈال دیا سو اسی وقت وہ صریح اژدھا ہو گیا'),
  ('ur.ahmedali', 26, 33, 'اوراپنا ہاتھ نکالا سو اسی وقت وہ دیکھنے والوں کو چمکتا ہوا دکھائی دیا'),
  ('ur.ahmedali', 26, 34, 'اپنے گرد کے سرداروں سے کہا کہ بے شک یہ بڑا ماہر جادوگر ہے'),
  ('ur.ahmedali', 26, 35, 'چاہتا ہے کہ تمہیں تمہارے دیس سے اپنے جادو کے زور سےنکال دےپھر تم کیا رائے دیتے ہو'),
  ('ur.ahmedali', 26, 36, 'کہا اسےاور اس کے بھائی کو مہلت دو اور شہروں میں چپڑاسیوں کو بھیج دیجیئے'),
  ('ur.ahmedali', 26, 37, 'کہ تیرے پاس بڑے ماہر جادوگروں کو لے آئیں'),
  ('ur.ahmedali', 26, 38, 'پھر سب جادوگر ایک مقرر دن پر جمع کیے گئے'),
  ('ur.ahmedali', 26, 39, 'اور لوگوں سے کہا گیا کیا تم بھی اکھٹے ہوتے ہو'),
  ('ur.ahmedali', 26, 40, 'تاکہ اگر جادوگر غالب آجائیں تو ہم انہی کی راہ پر رہیں'),
  ('ur.ahmedali', 26, 41, 'پھر جب جادوگر آئے تو فرعون سے کہا اگر ہم غالب آگئے تو کیا ہمیں کوئی بڑا انعام ملے گا'),
  ('ur.ahmedali', 26, 42, 'کہا ہاں اور بیشک تم اس وقت مقربوں میں داخل ہو جاؤ گے'),
  ('ur.ahmedali', 26, 43, 'موسیٰ نے ان سے کہا ڈالو جو تم ڈالتے ہو'),
  ('ur.ahmedali', 26, 44, 'پھر انہوں نے اپنی رسیاں اور لاٹھیاں ڈال دیں اور کہا فرعون کے اقبال سے ہماری فتح ہے'),
  ('ur.ahmedali', 26, 45, 'پھر موسیٰ نے اپنا عصا ڈالا پھر وہ فوراً ہی نگلنے لگا جو انہوں نے جھوٹ بنایا تھا'),
  ('ur.ahmedali', 26, 46, 'پھر جادوگر سجدے میں گر پڑے'),
  ('ur.ahmedali', 26, 47, 'کہا ہم رب العالمین پر ایمان لائے'),
  ('ur.ahmedali', 26, 48, 'جو موسیٰ اور ہارون کا رب ہے'),
  ('ur.ahmedali', 26, 49, 'کہا کیا تم میری اجازت سے پہلے ہی ایمان لے آئے بے شک وہ تمہارا استاد ہے جس نے تمہیں جادو سکھایا ہے سو تمہیں ابھی معلوم ہو جائے گا البتہ میں تمہارا ایک طرف کا ہاتھ اور دوسری طرف کا پاؤں کاٹ دوں گا اور تم سب کو سولی پر چڑھا دوں گا'),
  ('ur.ahmedali', 26, 50, 'کہا کچھ حرج نہیں بے شک ہم اپنے رب کے پاس پہنچنے والا ہوں گے'),
  ('ur.ahmedali', 26, 51, 'ہمیں امید ہے کہ ہمارا رب ہمارے گناہوں کو معاف کر دے گا اس لیے کہ ہم سب سے پہلے ایمان لانے والے ہیں'),
  ('ur.ahmedali', 26, 52, 'اور ہم نے موسی ٰکو حکم بھیجا کہ میرے بندوں کو رات کو لے نکل البتہ تمہارا پیچھا کیا جائے گا'),
  ('ur.ahmedali', 26, 53, 'پھر فرعون نے شہروں میں چپڑاسی بھیجے'),
  ('ur.ahmedali', 26, 54, 'کہ یہ ایک تھوڑی سی جماعت ہے'),
  ('ur.ahmedali', 26, 55, 'اور انہوں نے ہمیں بہت غصہ دلایا ہے'),
  ('ur.ahmedali', 26, 56, 'اور بے شک ہم سب ہتھیار بند ہیں'),
  ('ur.ahmedali', 26, 57, 'پھر ہم نے انہیں باغوں اور چشموں سے نکال باہر کیا'),
  ('ur.ahmedali', 26, 58, 'اور خزانوں اور عمدہ مکانو ں سے'),
  ('ur.ahmedali', 26, 59, 'اسی طرح ہوا اور ہم نے ان چیزوں کا بنی اسرائیل کو وارث بنایا'),
  ('ur.ahmedali', 26, 60, 'پھر سورج نکلنے کے وقت ان کے پیچھے پڑے'),
  ('ur.ahmedali', 26, 61, 'پھر جب دونوں جماعتوں نےایک دوسرے کو دیکھا تو موسیٰ کے ساتھیوں نے کہا ہم تو پکڑے گئے'),
  ('ur.ahmedali', 26, 62, 'کہا ہرگز نہیں میرا رب میرے ساتھ ہے وہ مجھے راہ بتائے گا'),
  ('ur.ahmedali', 26, 63, 'پھر ہم نےموسیٰ کو حکم بھیجا کہ اپنی لاٹھی کو دریا پر مار پھر پھٹ گیا پھر ہر ٹکڑا بڑے ٹیلے کی طرح ہو گیا'),
  ('ur.ahmedali', 26, 64, 'اور ہم نے اس جگہ دوسروں کو پہنچا دیا'),
  ('ur.ahmedali', 26, 65, 'اورہم نے موسیٰ کی اور جو اس کے ساتھ تھے سب کو نجات دی'),
  ('ur.ahmedali', 26, 66, 'پھر ہم نے دوسروں کو غرق کر دیا'),
  ('ur.ahmedali', 26, 67, 'البتہ اس میں بڑی نشانی ہے اور ان میں سے اکثر ایمان لانے والے نہیں'),
  ('ur.ahmedali', 26, 68, 'اور بے شک تیرا رب زبردست رحم کرنے والا ہے'),
  ('ur.ahmedali', 26, 69, 'اور انہیں ابراھیم کی خبر سنا دے'),
  ('ur.ahmedali', 26, 70, 'جب اپنے باپ اور اپنی قوم سے کہا تم کس کو پوجتے ہو'),
  ('ur.ahmedali', 26, 71, 'کہنے لگے ہم بتوں کو پوجتے ہیں پھر انہی کے گرد رہا کرتے ہیں'),
  ('ur.ahmedali', 26, 72, 'کہا کیا وہ تمہاری بات سنتے ہیں جب تم پکارتے ہو'),
  ('ur.ahmedali', 26, 73, 'یا تمہیں کچھ نفع یا نقصان پہنچا سکتے ہیں'),
  ('ur.ahmedali', 26, 74, 'کہنے لگے بلکہ ہم نے اپنے باپ دادا کو ایسا کرتے پایا ہے'),
  ('ur.ahmedali', 26, 75, 'کہا کیا تمہیں خبر ہے جنہیں تم پوجتے ہو'),
  ('ur.ahmedali', 26, 76, 'تم او رتمہارے پہلے باپ دادا جنہیں پوجتے تھے'),
  ('ur.ahmedali', 26, 77, 'سو وہ سوائے رب العالمین کے میرے دشمن ہیں'),
  ('ur.ahmedali', 26, 78, 'جس نے مجھے پیدا کیا پھر وہی مجھے راہ دکھاتا ہے'),
  ('ur.ahmedali', 26, 79, 'اور وہ جو مجھے کھلاتا اور پلاتا ہے'),
  ('ur.ahmedali', 26, 80, 'اور جب میں بیمار ہوتا ہوں تو وہی مجھے شفا دیتا ہے'),
