INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 26, 201, 'وہ دردناک عذاب دیکھے بغیر اس پر ایمان نہیں لائیں گے'),
  ('ur.ahmedali', 26, 202, 'پھر وہ ان پر اچاناک آئے گا اور انہیں خبر بھی نہ ہوگی'),
  ('ur.ahmedali', 26, 203, 'پھر کہیں گے کیا ہمیں مہلت مل سکتی ہے'),
  ('ur.ahmedali', 26, 204, 'کیا ہمارے عذاب کو جلد چاہتے ہیں'),
  ('ur.ahmedali', 26, 205, 'بھلا دیکھ اگر ہم انہیں چند سال فائدہ اٹھانے دیں'),
  ('ur.ahmedali', 26, 206, 'پھر ان کے پاس وہ عذاب آئے جس کا وعدہ دیے جاتے ہیں'),
  ('ur.ahmedali', 26, 207, 'تو جو انہوں نے فائدہ اٹھایا ہے کیا ان کے کچھ کام بھی آئے گا'),
  ('ur.ahmedali', 26, 208, 'اور ہم نے ایسی کوئی بستی ہلاک نہیں کی جس کے لیے ڈرانے والے نہ آئے ہوں'),
