INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 37, 1, 'Sıra Sıra duran ve önlerindekini sürdükçe süren ve Allah\'ı andıkça anan meleklere and olsun ki, sizin Tanrınız birdir; göklerin, yerin ve ikisi arasında bulunanların -doğuların da- Rabbidir.'),
  ('tr.diyanet', 37, 2, 'Sıra Sıra duran ve önlerindekini sürdükçe süren ve Allah\'ı andıkça anan meleklere and olsun ki, sizin Tanrınız birdir; göklerin, yerin ve ikisi arasında bulunanların -doğuların da- Rabbidir.'),
  ('tr.diyanet', 37, 3, 'Sıra Sıra duran ve önlerindekini sürdükçe süren ve Allah\'ı andıkça anan meleklere and olsun ki, sizin Tanrınız birdir; göklerin, yerin ve ikisi arasında bulunanların -doğuların da- Rabbidir.'),
  ('tr.diyanet', 37, 4, 'Sıra Sıra duran ve önlerindekini sürdükçe süren ve Allah\'ı andıkça anan meleklere and olsun ki, sizin Tanrınız birdir; göklerin, yerin ve ikisi arasında bulunanların -doğuların da- Rabbidir.'),
  ('tr.diyanet', 37, 5, 'Sıra Sıra duran ve önlerindekini sürdükçe süren ve Allah\'ı andıkça anan meleklere and olsun ki, sizin Tanrınız birdir; göklerin, yerin ve ikisi arasında bulunanların -doğuların da- Rabbidir.'),
  ('tr.diyanet', 37, 6, 'Şüphesiz Biz, yakın göğü bir süsle, yıldızlarla süsledik.'),
  ('tr.diyanet', 37, 7, 'Onu, inatçı her türlü şeytandan koruduk.'),
  ('tr.diyanet', 37, 8, 'Onlar yüce alemi asla dinleyemezler. Her yönden kovularak atılırlar. Onlara sürekli bir azap vardır.'),
  ('tr.diyanet', 37, 9, 'Onlar yüce alemi asla dinleyemezler. Her yönden kovularak atılırlar. Onlara sürekli bir azap vardır.'),
  ('tr.diyanet', 37, 10, 'Hele bir tek söz kapan olsun; delici bir alev onun peşine düşüverir.'),
  ('tr.diyanet', 37, 11, 'Allah\'a eş koşanlara sor: Kendilerini yaratmak mı daha zordur, yoksa Bizim yarattığımız gökleri yaratmak mı? Aslında Biz kendilerini özlü ve yapışkan çamurdan yaratmışızdır.'),
  ('tr.diyanet', 37, 12, 'Evet; sen onlara şaşıyorsun, onlar da seni alaya alıyorlar.'),
  ('tr.diyanet', 37, 13, 'Onlara öğüt verildiğinde öğüt dinlemezler.'),
  ('tr.diyanet', 37, 14, 'Bir mucize gördüklerinde onu eğlenceye alırlar.'),
  ('tr.diyanet', 37, 15, '"Bu apaçık bir sihirdir; öldüğümüz, toprak ve kemik olduğumuz zaman, önceki babalarımız yahut biz mi dirileceğiz?" derler.'),
  ('tr.diyanet', 37, 16, '"Bu apaçık bir sihirdir; öldüğümüz, toprak ve kemik olduğumuz zaman, önceki babalarımız yahut biz mi dirileceğiz?" derler.'),
  ('tr.diyanet', 37, 17, '"Bu apaçık bir sihirdir; öldüğümüz, toprak ve kemik olduğumuz zaman, önceki babalarımız yahut biz mi dirileceğiz?" derler.'),
  ('tr.diyanet', 37, 18, 'De ki: "Evet hem de zelil ve hakir olarak."'),
  ('tr.diyanet', 37, 19, 'Tek bir çığlık. Hemen bakıp kalırlar.'),
  ('tr.diyanet', 37, 20, 'Şöyle derler: "Vay bize! İşte bu ceza günüdür."'),
  ('tr.diyanet', 37, 21, 'Onlara: "İşte bu, yalanladığınız hüküm günüdür" denir.'),
  ('tr.diyanet', 37, 22, 'İlgililere şöyle emredilir: "Zulmedenleri, onlarla işbirliği edenleri ve Allah\'ı bırakıp da taptıklarını derleyin. Onları cehennem yoluna koyun."'),
  ('tr.diyanet', 37, 23, 'İlgililere şöyle emredilir: "Zulmedenleri, onlarla işbirliği edenleri ve Allah\'ı bırakıp da taptıklarını derleyin. Onları cehennem yoluna koyun."'),
  ('tr.diyanet', 37, 24, '"Onları durdurun; çünkü kendilerinden daha da sorulacaktır."'),
  ('tr.diyanet', 37, 25, 'Şöyle sorulur: "Size ne oldu ki birbirinizle yardımlaşmıyorsunuz?"'),
  ('tr.diyanet', 37, 26, 'Hayır; bugün onların hepsi teslim olmuşlardır.'),
  ('tr.diyanet', 37, 27, 'Birbirlerine dönüp soruşurlar.'),
  ('tr.diyanet', 37, 28, 'İleri gelenlerine: "Doğrusu siz bize sureti hakdan görünürdünüz" derler.'),
  ('tr.diyanet', 37, 29, 'Onlar da şöyle derler: "Hayır; siz inanmış kimseler değildiniz."'),
  ('tr.diyanet', 37, 30, '"Bizim sizin üstünüzde bir nüfuzumuz yoktu. Bilakis, azmış bir millettiniz."'),
  ('tr.diyanet', 37, 31, '"Bu sebeple, Rabbimizin sözü aleyhimizde gerçekleşti. şüphesiz azabı tadacağız."'),
  ('tr.diyanet', 37, 32, '"Sizi biz azdırmıştık, çünkü kendimiz azgındık".'),
  ('tr.diyanet', 37, 33, 'O gün hepsi azabda birleşirler.'),
  ('tr.diyanet', 37, 34, 'Doğrusu suçlulara böyle yaparız.'),
  ('tr.diyanet', 37, 35, 'Onlara: "Allah\'tan başka tanrı yoktur" denildiği zaman şüphesiz büyüklenirler.'),
  ('tr.diyanet', 37, 36, '"Deli bir şair yüzünden tanrılarımızı mı bırakalım?" derlerdi.'),
  ('tr.diyanet', 37, 37, 'Hayır; o, gerçeği getirmiş ve peygamberleri doğrulamıştı.'),
  ('tr.diyanet', 37, 38, 'Şüphesiz siz can yakıcı azabı tadacaksınız.'),
  ('tr.diyanet', 37, 39, 'Yaptığınızdan başka birşeyle cezalanmayacaksınız.'),
  ('tr.diyanet', 37, 40, 'Ancak Allah\'a içten bağlı kullar bunun dışındadır.'),
  ('tr.diyanet', 37, 41, 'İşte bildirilen rızık ve meyveler onlaradır. Nimet cennetlerinde, karşılıklı tahtlar üzerinde kendilerine ikram olunur.'),
  ('tr.diyanet', 37, 42, 'İşte bildirilen rızık ve meyveler onlaradır. Nimet cennetlerinde, karşılıklı tahtlar üzerinde kendilerine ikram olunur.'),
  ('tr.diyanet', 37, 43, 'İşte bildirilen rızık ve meyveler onlaradır. Nimet cennetlerinde, karşılıklı tahtlar üzerinde kendilerine ikram olunur.'),
  ('tr.diyanet', 37, 44, 'İşte bildirilen rızık ve meyveler onlaradır. Nimet cennetlerinde, karşılıklı tahtlar üzerinde kendilerine ikram olunur.'),
  ('tr.diyanet', 37, 45, 'Baş ağrısı vermeyen, sarhoş etmeyen, içenlere zevk bahşeden bembeyaz bir kaynaktan doldurulmuş kadehler sunulur.'),
  ('tr.diyanet', 37, 46, 'Baş ağrısı vermeyen, sarhoş etmeyen, içenlere zevk bahşeden bembeyaz bir kaynaktan doldurulmuş kadehler sunulur.'),
  ('tr.diyanet', 37, 47, 'Baş ağrısı vermeyen, sarhoş etmeyen, içenlere zevk bahşeden bembeyaz bir kaynaktan doldurulmuş kadehler sunulur.'),
  ('tr.diyanet', 37, 48, 'Yanlarında, örtülü yumurta gibi (bembeyaz), bakışlarını da yalnız eşlerine çevirmiş güzel gözlüler vardır.'),
  ('tr.diyanet', 37, 49, 'Yanlarında, örtülü yumurta gibi (bembeyaz), bakışlarını da yalnız eşlerine çevirmiş güzel gözlüler vardır.'),
  ('tr.diyanet', 37, 50, 'Birbirlerine dönüp sorarlar:'),
  ('tr.diyanet', 37, 51, 'İçlerinden biri şöyle der: "Benim bir dostum vardı, bana: \'Sen de mi, ölüp toprak ve kemik olduğumuz zaman dirilerek ceza göreceğimizi tasdik edenlerdensin?\' derdi."'),
  ('tr.diyanet', 37, 52, 'İçlerinden biri şöyle der: "Benim bir dostum vardı, bana: \'Sen de mi, ölüp toprak ve kemik olduğumuz zaman dirilerek ceza göreceğimizi tasdik edenlerdensin?\' derdi."'),
  ('tr.diyanet', 37, 53, 'İçlerinden biri şöyle der: "Benim bir dostum vardı, bana: \'Sen de mi, ölüp toprak ve kemik olduğumuz zaman dirilerek ceza göreceğimizi tasdik edenlerdensin?\' derdi."'),
  ('tr.diyanet', 37, 54, 'Yanındakilere: "Siz onu bilir misiniz?" der.'),
  ('tr.diyanet', 37, 55, 'Bir bakar onu cehennemin ortasında görür.'),
  ('tr.diyanet', 37, 56, 'Ona der ki: "Allah\'a and olsun ki, az kalsın beni de mahvedecektin."'),
  ('tr.diyanet', 37, 57, '"Eğer Rabbimin lütfu olmasaydı ben de oraya götürülenlerden olurdum."'),
  ('tr.diyanet', 37, 58, '"Birinci ölümden sonra bir daha ölmeyeceğiz değil mi? Azap da görmeyeceğiz ha?"'),
  ('tr.diyanet', 37, 59, '"Birinci ölümden sonra bir daha ölmeyeceğiz değil mi? Azap da görmeyeceğiz ha?"'),
  ('tr.diyanet', 37, 60, 'İşte büyük kurtuluş şüphesiz budur.'),
  ('tr.diyanet', 37, 61, 'Çalışanlar bunun için çalışsın.'),
  ('tr.diyanet', 37, 62, 'Konukluk olarak bu mu iyidir, yoksa zakkum ağacı mı?'),
  ('tr.diyanet', 37, 63, 'Biz o ağacı, zalimler için bir dert yaptık.'),
  ('tr.diyanet', 37, 64, 'O, cehennemin dibinde çıkan bir ağaçtır.'),
  ('tr.diyanet', 37, 65, 'Tomurcukları şeytan başı gibidir.'),
  ('tr.diyanet', 37, 66, 'İşte cehennemlikler bundan yerler, karınlarını onunla doldururlar.'),
  ('tr.diyanet', 37, 67, 'Sonra, üzerine kaynar su katılmış içki şüphesiz onlar içindir.'),
  ('tr.diyanet', 37, 68, 'Doğrusu sonra dönecekleri yer yine cehennemdir.'),
  ('tr.diyanet', 37, 69, 'Onlar babalarını şüphesiz sapık kimseler olarak bulmuşlardı.'),
  ('tr.diyanet', 37, 70, 'Öyleyken yine de onların izlerinden kovalanırcasına koşturuyorlardı.'),
  ('tr.diyanet', 37, 71, 'Onlardan önce, evvelki ümmetlerin çoğu, and olsun ki sapıtmıştı.'),
  ('tr.diyanet', 37, 72, 'And olsun ki, içlerine uyarıcılar göndermiştik.'),
  ('tr.diyanet', 37, 73, 'Uyarıldığı halde yola gelmeyenlerin sonunun nasıl olduğuna bir bak!'),
  ('tr.diyanet', 37, 74, 'Allah\'ın, O\'na içten bağlanan kulları bunun dışındadır.'),
  ('tr.diyanet', 37, 75, 'And olsun ki, Nuh Bize seslenmişti de duasına ne güzel icabet etmiştik.'),
  ('tr.diyanet', 37, 76, 'Onu ve ailesini büyük sıkıntıdan kurtarmıştık.'),
  ('tr.diyanet', 37, 77, 'Ancak onun soyunu sürekli kıldık.'),
  ('tr.diyanet', 37, 78, 'Sonra gelenler içinde "Alemlerde, Nuh\'a selam olsun" diye ona iyi bir ün bıraktık.'),
  ('tr.diyanet', 37, 79, 'Sonra gelenler içinde "Alemlerde, Nuh\'a selam olsun" diye ona iyi bir ün bıraktık.'),
  ('tr.diyanet', 37, 80, 'İşte Biz iyi davrananları böyle mükafatlandırırız.'),
  ('tr.diyanet', 37, 81, 'Doğrusu o, bizim inanmış kullarımızdandı.'),
  ('tr.diyanet', 37, 82, 'Sonra, diğerlerini suda boğduk.'),
  ('tr.diyanet', 37, 83, 'İbrahim de şüphesiz O\'nun yolunda olanlardandı.'),
  ('tr.diyanet', 37, 84, 'Nitekim Rabbine temiz bir kalple geldi.'),
  ('tr.diyanet', 37, 85, 'İbrahim babasına ve milletine şöyle demişti: "Nelere kulluk ediyorsunuz?"'),
  ('tr.diyanet', 37, 86, '"Allah\'ı bırakıp uydurma tanrılar mı istiyorsunuz?"'),
  ('tr.diyanet', 37, 87, '"Alemlerin Rabbi hakkındaki sanınız nedir?"'),
  ('tr.diyanet', 37, 88, 'İbrahim yıldızlara bir göz attı ve "Ben rahatsızım" dedi.'),
  ('tr.diyanet', 37, 89, 'İbrahim yıldızlara bir göz attı ve "Ben rahatsızım" dedi.'),
  ('tr.diyanet', 37, 90, 'Onu bırakıp gittiler.'),
  ('tr.diyanet', 37, 91, 'O da onların tanrılarına gizlice yönelip: "Sundukları yiyecekleri yemiyor musunuz? Ne o, konuşmuyor musunuz?" dedi.'),
  ('tr.diyanet', 37, 92, 'O da onların tanrılarına gizlice yönelip: "Sundukları yiyecekleri yemiyor musunuz? Ne o, konuşmuyor musunuz?" dedi.'),
  ('tr.diyanet', 37, 93, 'Sonunda, üzerlerine yürüyüp kuvvetle vurdu.'),
  ('tr.diyanet', 37, 94, 'Bunun üzerine putperestler koşarak ona geldiler.'),
  ('tr.diyanet', 37, 95, 'İbrahim onlara şöyle söyledi: "Yonttuğunuz şeylere mi tapıyorsunuz? Oysa sizi de, yonttuklarınızı da Allah yaratmıştır."'),
  ('tr.diyanet', 37, 96, 'İbrahim onlara şöyle söyledi: "Yonttuğunuz şeylere mi tapıyorsunuz? Oysa sizi de, yonttuklarınızı da Allah yaratmıştır."'),
  ('tr.diyanet', 37, 97, 'Putperestler: "Onun için bir yapı yapın da onu oradan ateşin içine atın" dediler.'),
  ('tr.diyanet', 37, 98, 'Ona düzen kurmak istediler, ama Biz onları altettik.'),
  ('tr.diyanet', 37, 99, 'İbrahim: "Doğrusu ben Rabbim uğrunda sizi bırakıp gidiyorum; O beni doğru yola eriştirir" dedi.'),
  ('tr.diyanet', 37, 100, '"Rabbim! Bana iyilerden olacak bir çocuk ver" diye yalvardı.'),
  ('tr.diyanet', 37, 101, 'Biz de ona yumuşak huylu bir oğlan müjdeledik.'),
  ('tr.diyanet', 37, 102, 'Çocuk kendisinin yanısıra yürümeye başlayınca: "Ey oğulcuğum! Doğrusu ben uykuda iken seni boğazladığımı görüyorum, bir düşün, ne dersin?" dedi. "Ey babacığım! Ne ile emrolundunsa yap, Allah dilerse, sabredenlerden olduğumu göreceksin" dedi.'),
  ('tr.diyanet', 37, 103, 'Böylece ikisi de Allah\' a teslimiyet gösterip, babası oğlunu alnı üzerine yatırınca Biz: "Ey İbrahim! Rüyayı gerçek yaptın; işte biz iyi davrananları böylece mükafatlandırırız" diye seslendik.'),
  ('tr.diyanet', 37, 104, 'Böylece ikisi de Allah\' a teslimiyet gösterip, babası oğlunu alnı üzerine yatırınca Biz: "Ey İbrahim! Rüyayı gerçek yaptın; işte biz iyi davrananları böylece mükafatlandırırız" diye seslendik.'),
  ('tr.diyanet', 37, 105, 'Böylece ikisi de Allah\' a teslimiyet gösterip, babası oğlunu alnı üzerine yatırınca Biz: "Ey İbrahim! Rüyayı gerçek yaptın; işte biz iyi davrananları böylece mükafatlandırırız" diye seslendik.'),
  ('tr.diyanet', 37, 106, 'Doğrusu bu apaçık bir deneme idi.'),
  ('tr.diyanet', 37, 107, 'Ona fidye olarak büyük bir kurbanlık verdik.'),
  ('tr.diyanet', 37, 108, 'Sonra gelenler içinde "İbrahim\'e selam olsun" diye ona iyi bir ün bıraktık.'),
  ('tr.diyanet', 37, 109, 'Sonra gelenler içinde "İbrahim\'e selam olsun" diye ona iyi bir ün bıraktık.'),
  ('tr.diyanet', 37, 110, 'İşte iyileri böylece mükafatlandırırız.'),
  ('tr.diyanet', 37, 111, 'Doğrusu o, inanmış kullarımızdandı.'),
  ('tr.diyanet', 37, 112, 'Ona, iyilerden olan İshak\'ı peygamber olarak müjdeledik.'),
  ('tr.diyanet', 37, 113, 'Kendisini ve İshak\'ı mübarek kıldık; ikisinin soyundan iyi olan da vardır, açıktan açığa kendisine yazık eden de vardır.'),
  ('tr.diyanet', 37, 114, 'And olsun ki Musa ve Harun\'a da iyilikte bulunmuştuk.'),
  ('tr.diyanet', 37, 115, 'İkisini ve milletlerini büyük bir sıkıntıdan kurtarmıştık.'),
  ('tr.diyanet', 37, 116, 'Onlara yardım etmiştik de üstün gelmişlerdi.'),
  ('tr.diyanet', 37, 117, 'Her ikisine de, apaçık anlaşılan bir Kitap vermiştik.'),
  ('tr.diyanet', 37, 118, 'Her ikisini de doğru yola eriştirmiştik.'),
  ('tr.diyanet', 37, 119, 'Sonra gelenler içinde "Musa ve Harun\'a selam olsun" diye iyi birer ün bıraktık.'),
  ('tr.diyanet', 37, 120, 'Sonra gelenler içinde "Musa ve Harun\'a selam olsun" diye iyi birer ün bıraktık.'),
  ('tr.diyanet', 37, 121, 'Doğrusu Biz, iyileri böylece mükafatlandırırız.'),
  ('tr.diyanet', 37, 122, 'İkisi de şüphesiz inanmış kullarımızdandı.'),
  ('tr.diyanet', 37, 123, 'Doğrusu İlyas da peygamberlerdendir.'),
  ('tr.diyanet', 37, 124, 'Milletine: "Allah\'a karşı gelmekten sakınmaz mısınız? Biçim verenlerin en iyisi olan, sizin de Rabbiniz, önceki babalarınızın da Rabbi bulunan Allah\'ı bırakıp da Baal putuna mı taparsınız?" demişti.'),
  ('tr.diyanet', 37, 125, 'Milletine: "Allah\'a karşı gelmekten sakınmaz mısınız? Biçim verenlerin en iyisi olan, sizin de Rabbiniz, önceki babalarınızın da Rabbi bulunan Allah\'ı bırakıp da Baal putuna mı taparsınız?" demişti.'),
  ('tr.diyanet', 37, 126, 'Milletine: "Allah\'a karşı gelmekten sakınmaz mısınız? Biçim verenlerin en iyisi olan, sizin de Rabbiniz, önceki babalarınızın da Rabbi bulunan Allah\'ı bırakıp da Baal putuna mı taparsınız?" demişti.'),
  ('tr.diyanet', 37, 127, 'Bunun üzerine onu yalanlamışlardı. Allah\'ın O\'na içten bağlı kulları bir yana, bunların hepsi cehenneme götürüleceklerdi.'),
  ('tr.diyanet', 37, 128, 'Bunun üzerine onu yalanlamışlardı. Allah\'ın O\'na içten bağlı kulları bir yana, bunların hepsi cehenneme götürüleceklerdi.'),
  ('tr.diyanet', 37, 129, 'Sonra gelenler içinde, "İlyas\'a selam olsun" diye bir ün bıraktık.'),
  ('tr.diyanet', 37, 130, 'Sonra gelenler içinde, "İlyas\'a selam olsun" diye bir ün bıraktık.'),
  ('tr.diyanet', 37, 131, 'Doğrusu Biz iyileri böylece mükafatlandırırız.'),
  ('tr.diyanet', 37, 132, 'O, inanmış kullarımızdandı.'),
  ('tr.diyanet', 37, 133, 'Şüphesiz Lut da peygamberlerdendir.'),
  ('tr.diyanet', 37, 134, 'Geridekiler arasında kalan yaşlı bir kadın dışında, Lut\'u ve ailesinin hepsini kurtarmıştık.'),
  ('tr.diyanet', 37, 135, 'Geridekiler arasında kalan yaşlı bir kadın dışında, Lut\'u ve ailesinin hepsini kurtarmıştık.'),
  ('tr.diyanet', 37, 136, 'Sonra diğerlerini yok etmiştik.'),
  ('tr.diyanet', 37, 137, 'Sabah akşam, onların yerleri üzerinden geçersiniz. Akletmez misiniz?'),
  ('tr.diyanet', 37, 138, 'Sabah akşam, onların yerleri üzerinden geçersiniz. Akletmez misiniz?'),
  ('tr.diyanet', 37, 139, 'Doğrusu Yunus da peygamberlerdendir.'),
  ('tr.diyanet', 37, 140, 'Dolu bir gemiye kaçmıştı.'),
  ('tr.diyanet', 37, 141, 'Gemide olanlarla karşılıklı kura çekmişti de yenilenlerden olmuştu, bu sebeple denize atılmıştı.'),
  ('tr.diyanet', 37, 142, 'Kendini kınarken onu bir balık yutmuştu.'),
  ('tr.diyanet', 37, 143, 'Eğer Allah\'ı tesbih edenlerden olmasaydı, tekrar diriltilecek güne kadar balığın karnında kalacaktı.'),
  ('tr.diyanet', 37, 144, 'Eğer Allah\'ı tesbih edenlerden olmasaydı, tekrar diriltilecek güne kadar balığın karnında kalacaktı.'),
  ('tr.diyanet', 37, 145, 'Halsiz bir halde iken kendisini sahile çıkardık.'),
  ('tr.diyanet', 37, 146, 'Onun için, geniş yapraklı bir bitki yetiştirdik.'),
  ('tr.diyanet', 37, 147, 'Onu, yüzbin veya daha çok kişiye peygamber olarak gönderdik.'),
  ('tr.diyanet', 37, 148, 'Sonunda ona inandılar, bunun üzerine Biz de onları bir süreye kadar geçindirdik.'),
  ('tr.diyanet', 37, 149, 'Putperestlere sor, kızlar senin Rabbinin de erkekler onların mı?'),
  ('tr.diyanet', 37, 150, 'Yoksa melekleri kız olarak yarattığımızda onlar hazır mı idiler?'),
  ('tr.diyanet', 37, 151, 'Dikkat edin; doğrusu onlar yalan uydurup söylüyorlar, "Allah doğurdu" diyorlar. Onlar şüphesiz yalancıdırlar.'),
  ('tr.diyanet', 37, 152, 'Dikkat edin; doğrusu onlar yalan uydurup söylüyorlar, "Allah doğurdu" diyorlar. Onlar şüphesiz yalancıdırlar.'),
  ('tr.diyanet', 37, 153, 'Allah kızları, oğullara tercih mi etmiş?'),
  ('tr.diyanet', 37, 154, 'Ne oluyorsunuz? Ne biçim hükmediyorsunuz?'),
  ('tr.diyanet', 37, 155, 'Hiç düşünmez misiniz?'),
  ('tr.diyanet', 37, 156, 'Yoksa apaçık bir deliliniz mi var?'),
  ('tr.diyanet', 37, 157, 'Doğru sözlülerden iseniz, kitabınızı getirin bakalım.'),
  ('tr.diyanet', 37, 158, 'Allah\'la cinler (melekler) arasında da bir soy bağı icadettiler. And olsun ki, cinler de, kendilerinin (bunu söyleyenlerin) hesap yerine götürüleceklerini bilirler.'),
  ('tr.diyanet', 37, 159, 'Allah onların vasıflandırmalarından münezzehtir.'),
  ('tr.diyanet', 37, 160, 'Allah\'ın içten bağlı kulları bunların dışındadır.'),
  ('tr.diyanet', 37, 161, 'Sizler ve taptığınız şeyler, cehenneme girecek kimseden başkasını Allah\'a karşı azdırıcı değilsiniz.'),
  ('tr.diyanet', 37, 162, 'Sizler ve taptığınız şeyler, cehenneme girecek kimseden başkasını Allah\'a karşı azdırıcı değilsiniz.'),
  ('tr.diyanet', 37, 163, 'Sizler ve taptığınız şeyler, cehenneme girecek kimseden başkasını Allah\'a karşı azdırıcı değilsiniz.'),
  ('tr.diyanet', 37, 164, 'Melekler şöyle derler: "Bizim her birimizin bilinen bir makamı vardır. Şüphesiz biz sıra sıra duranlarız, şüphesiz biz Allah\'ı tesbih edenleriz."'),
  ('tr.diyanet', 37, 165, 'Melekler şöyle derler: "Bizim her birimizin bilinen bir makamı vardır. Şüphesiz biz sıra sıra duranlarız, şüphesiz biz Allah\'ı tesbih edenleriz."'),
  ('tr.diyanet', 37, 166, 'Melekler şöyle derler: "Bizim her birimizin bilinen bir makamı vardır. Şüphesiz biz sıra sıra duranlarız, şüphesiz biz Allah\'ı tesbih edenleriz."'),
  ('tr.diyanet', 37, 167, 'Putperestler: "Öncekilerde olduğu gibi bizde de bir kitap olsaydı, Allah\'ın O\'na içten bağlanan kulları olurduk" derlerdi.'),
  ('tr.diyanet', 37, 168, 'Putperestler: "Öncekilerde olduğu gibi bizde de bir kitap olsaydı, Allah\'ın O\'na içten bağlanan kulları olurduk" derlerdi.'),
  ('tr.diyanet', 37, 169, 'Putperestler: "Öncekilerde olduğu gibi bizde de bir kitap olsaydı, Allah\'ın O\'na içten bağlanan kulları olurduk" derlerdi.'),
  ('tr.diyanet', 37, 170, 'Böyleyken O\'nu inkar ettiler. Ama bileceklerdir.'),
  ('tr.diyanet', 37, 171, 'And olsun ki, peygamber kullarımıza söz vermişizdir.'),
  ('tr.diyanet', 37, 172, 'Onlar şüphesiz yardım göreceklerdir.'),
  ('tr.diyanet', 37, 173, 'Bizim ordumuz şüphesiz üstün gelecektir.'),
  ('tr.diyanet', 37, 174, 'Bir süreye kadar onlara aldırış etme.'),
  ('tr.diyanet', 37, 175, 'Onlara inecek azabı gözetle, onlar da göreceklerdir.'),
  ('tr.diyanet', 37, 176, 'Azabımıza uğramakta acele mi ediyorlar?'),
  ('tr.diyanet', 37, 177, 'O azap, yurtlarına indiğinde, uyarılan fakat yola gelmeyenlerin sabahı ne kötü olur!'),
  ('tr.diyanet', 37, 178, 'Bir süreye kadar onlardan yüz çevir.'),
  ('tr.diyanet', 37, 179, 'İnecek azabı gözetle, onlar da göreceklerdir.'),
  ('tr.diyanet', 37, 180, 'Senin güçlü olan Rabbin, onların vasıflandırmalarından münezzehtir.'),
  ('tr.diyanet', 37, 181, 'Ve selam, peygamberleredir.'),
  ('tr.diyanet', 37, 182, 'Hamd de Alemlerin Rabbi Allah\'adır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 37, 1, 'Demi (rombongan) yang ber shaf-shaf dengan sebenar-benarnya],'),
  ('id.indonesian', 37, 2, 'dan demi (rombongan) yang melarang dengan sebenar-benarnya (dari perbuatan-perbuatan maksiat),'),
  ('id.indonesian', 37, 3, 'dan demi (rombongan) yang membacakan pelajaran,'),
  ('id.indonesian', 37, 4, 'Sesungguhnya Tuhanmu benar-benar Esa.'),
  ('id.indonesian', 37, 5, 'Tuhan langit dan bumi dan apa yang berada di antara keduanya dan Tuhan tempat-tempat terbit matahari.'),
  ('id.indonesian', 37, 6, 'Sesungguhnya Kami telah menghias langit yang terdekat dengan hiasan, yaitu bintang-bintang,'),
  ('id.indonesian', 37, 7, 'dan telah memeliharanya (sebenar-benarnya) dari setiap syaitan yang sangat durhaka,'),
  ('id.indonesian', 37, 8, 'syaitan syaitan itu tidak dapat mendengar-dengarkan (pembicaraan) para malaikat dan mereka dilempari dari segala penjuru.'),
  ('id.indonesian', 37, 9, 'Untuk mengusir mereka dan bagi mereka siksaan yang kekal,'),
  ('id.indonesian', 37, 10, 'akan tetapi barangsiapa (di antara mereka) yang mencuri-curi (pembicaraan); maka ia dikejar oleh suluh api yang cemerlang.'),
  ('id.indonesian', 37, 11, 'Maka tanyakanlah kepada mereka (musyrik Mekah): "Apakah mereka yang lebih kukuh kejadiannya ataukah apa yang telah Kami ciptakan itu?" Sesungguhnya Kami telah menciptakan mereka dari tanah liat.'),
  ('id.indonesian', 37, 12, 'Bahkan kamu menjadi heran (terhadap keingkaran mereka) dan mereka menghinakan kamu.'),
  ('id.indonesian', 37, 13, 'Dan apabila mereka diberi pelajaran mereka tiada mengingatnya.'),
  ('id.indonesian', 37, 14, 'Dan apabila mereka melihat sesuatu tanda kebesaran Allah, mereka sangat menghinakan.'),
  ('id.indonesian', 37, 15, 'Dan mereka berkata "Ini tiada lain hanyalah sihir yang nyata.'),
  ('id.indonesian', 37, 16, 'Apakah apabila kami telah mati dan telah menjadi tanah serta menjadi tulang belulang, apakah benar-benar kami akan dibangkitkan (kembali)?'),
  ('id.indonesian', 37, 17, 'Dan apakah bapak-bapak kami yang telah terdahulu (akan dibangkitkan pula)"?'),
  ('id.indonesian', 37, 18, 'Katakanlah: "Ya, dan kamu akan terhina"'),
  ('id.indonesian', 37, 19, 'Maka sesungguhnya kebangkitan itu hanya dengan satu teriakan saja; maka tiba-tiba mereka meIihatnya.'),
  ('id.indonesian', 37, 20, 'Dan mereka berkata: "Aduhai celakalah kita!" Inilah hari pembalasan.'),
  ('id.indonesian', 37, 21, 'Inilah hari keputusan yang kamu selalu mendustakannya.'),
  ('id.indonesian', 37, 22, '(kepada malaikat diperintahkan): "Kumpulkanlah orang-orang yang zalim beserta teman sejawat mereka dan sembahan-sembahan yang selalu mereka sembah,'),
  ('id.indonesian', 37, 23, 'selain Allah; maka tunjukkanlah kepada mereka jalan ke neraka.'),
  ('id.indonesian', 37, 24, 'Dan tahanlah mereka (di tempat perhentian) karena sesungguhnya mereka akan ditanya:'),
  ('id.indonesian', 37, 25, '"Kenapa kamu tidak tolong menolong?"'),
  ('id.indonesian', 37, 26, 'Bahkan mereka pada hari itu menyerah diri.'),
  ('id.indonesian', 37, 27, 'Sebahagian dan mereka menghadap kepada sebahagian yang lain berbantah-bantahan.'),
  ('id.indonesian', 37, 28, 'Pengikut-pengikut mereka berkata (kepada pemimpin-pemimpin mereka): "Sesungguhnya kamulah yang datang kepada kami dan kanan.'),
  ('id.indonesian', 37, 29, 'Pemimpin-pemimpin mereka menjawab: "Sebenarnya kamulah yang tidak beriman".'),
  ('id.indonesian', 37, 30, 'Dan sekali-kali kami tidak berkuasa terhadapmu, bahkan kamulah kaum yang melampaui batas.'),
  ('id.indonesian', 37, 31, 'Maka pastilah putusan (azab) Tuhan kita menimpa atas kita; sesungguhnya kita akan merasakan (azab itu).'),
  ('id.indonesian', 37, 32, 'Maka kami telah menyesatkan kamu, sesungguhnya kami adalah orang-orang yang sesat.'),
  ('id.indonesian', 37, 33, 'Maka sesungguhnya mereka pada hari itu bersama-sama dalam azab.'),
  ('id.indonesian', 37, 34, 'Sesungguhnya demikianlah Kami berbuat terhadap orang-orang yang berbuat jahat.'),
  ('id.indonesian', 37, 35, 'Sesungguhnya mereka dahulu apabila dikatakan kepada mereka: "Laa ilaaha illallah" (Tiada Tuhan yang berhak disembah melainkan Allah) mereka menyombongkan diri,'),
  ('id.indonesian', 37, 36, 'dan mereka berkata: "Apakah sesungguhnya kami harus meninggalkan sembahan-sembahan kami karena seorang penyair gila?"'),
  ('id.indonesian', 37, 37, 'Sebenarnya dia (Muhammad) telah datang membawa kebenaran dan membenarkan rasul-rasul (sebelumnya).'),
  ('id.indonesian', 37, 38, 'Sesungguhnya kamu pasti akan merasakan azab yang pedih.'),
  ('id.indonesian', 37, 39, 'Dan kamu tidak diberi pembalasan melainkan terhadap kejahatan yang telah kamu kerjakan,'),
  ('id.indonesian', 37, 40, 'tetapi hamba-hamba Allah yang dibersihkan (dari dosa).'),
  ('id.indonesian', 37, 41, 'Mereka itu memperoleh rezeki yang tertentu,'),
  ('id.indonesian', 37, 42, 'yaitu buah-buahan. Dan mereka adalah orang-orang yang dimuliakan,'),
  ('id.indonesian', 37, 43, 'di dalam surga-surga yang penuh nikmat.'),
  ('id.indonesian', 37, 44, 'di atas takhta-takhta kebesaran berhadap-hadapan.'),
  ('id.indonesian', 37, 45, 'Diedarkan kepada mereka gelas yang berisi khamar dari sungai yang mengalir.'),
  ('id.indonesian', 37, 46, '(Warnanya) putih bersih, sedap rasanya bagi orang-orang yang minum.'),
  ('id.indonesian', 37, 47, 'Tidak ada dalam khamar itu alkohol dan mereka tiada mabuk karenanya.'),
  ('id.indonesian', 37, 48, 'Di sisi mereka ada bidadari-bidadari yang tidak liar pandangannya dan jelita matanya,'),
  ('id.indonesian', 37, 49, 'seakan-akan mereka adalah telur (burung unta) yang tersimpan dengan baik.'),
  ('id.indonesian', 37, 50, 'Lalu sebahagian mereka menghadap kepada sebahagian yang lain sambil bercakap-cakap.'),
  ('id.indonesian', 37, 51, 'Berkatalah salah seorang di antara mereka: "Sesungguhnya aku dahulu (di dunia) mempunyai seorang teman,'),
  ('id.indonesian', 37, 52, 'yang berkata: "Apakah kamu sungguh-sungguh termasuk orang-orang yang membenarkan (hari berbangkit)?'),
  ('id.indonesian', 37, 53, 'Apakah bila kita telah mati dan kita telah menjadi tanah dan tulang belulang, apakah sesungguhnya kita benar-benar (akan dibangkitkan) untuk diberi pembalasan?"'),
  ('id.indonesian', 37, 54, 'Berkata pulalah ia: "Maukah kamu meninjau (temanku itu)?"'),
  ('id.indonesian', 37, 55, 'Maka ia meninjaunya, lalu dia melihat temannya itu di tengah-tengah neraka menyala-nyala.'),
  ('id.indonesian', 37, 56, 'Ia berkata (pula): "Demi Allah, sesungguhnya kamu benar-benar hampir mencelakakanku,'),
  ('id.indonesian', 37, 57, 'jikalau tidaklah karena nikmat Tuhanku pastilah aku termasuk orang-orang yang diseret (ke neraka).'),
  ('id.indonesian', 37, 58, 'Maka apakah kita tidak akan mati?,'),
  ('id.indonesian', 37, 59, 'melainkan hanya kematian kita yang pertama saja (di dunia), dan kita tidak akan disiksa (di akhirat ini)?'),
  ('id.indonesian', 37, 60, 'Sesungguhnya ini benar-benar kemenangan yang besar.'),
  ('id.indonesian', 37, 61, 'Untuk kemenangan serupa ini hendaklah berusaha orang-orang yang bekerja"'),
  ('id.indonesian', 37, 62, '(Makanan surga) itukah hidangan yang lebih baik ataukah pohon zaqqum.'),
  ('id.indonesian', 37, 63, 'Sesungguhnya Kami menjadikan pohon zaqqum itu sebagai siksaan bagi orang-orang yang zalim.'),
  ('id.indonesian', 37, 64, 'Sesungguhnya dia adalah sebatang pohon yang ke luar dan dasar neraka yang menyala.'),
  ('id.indonesian', 37, 65, 'mayangnya seperti kepala syaitan-syaitan.'),
  ('id.indonesian', 37, 66, 'Maka sesungguhnya mereka benar-benar memakan sebagian dari buah pohon itu, maka mereka memenuhi perutnya dengan buah zaqqum itu.'),
  ('id.indonesian', 37, 67, 'Kemudian sesudah makan buah pohon zaqqum itu pasti mereka mendapat minuman yang bercampur dengan air yang sangat panas.'),
  ('id.indonesian', 37, 68, 'Kemudian sesungguhnya tempat kembali mereka benar-benar ke neraka Jahim.'),
  ('id.indonesian', 37, 69, 'Karena sesungguhnya mereka mendapati bapak-bapak mereka dalam Keadaaan sesat.'),
  ('id.indonesian', 37, 70, 'Lalu mereka sangat tergesa-gesa mengikuti jejak orang-orang tua mereka itu.'),
  ('id.indonesian', 37, 71, 'Dan sesungguhnya telah sesat sebelum mereka (Quraisy) sebagian besar dari orang-orang yang dahulu,'),
  ('id.indonesian', 37, 72, 'dan sesungguhnya telah Kami utus pemberi-pemberi peringatan (rasul-rasul) di kalangan mereka.'),
  ('id.indonesian', 37, 73, 'Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu.'),
  ('id.indonesian', 37, 74, 'Tetapi hamba-hamba Allah yang bersihkan (dari dosa tidak akan diazab).'),
  ('id.indonesian', 37, 75, 'Sesungguhnya Nuh telah menyeru Kami: maka sesungguhnya sebaik-baik yang memperkenankan (adalah Kami).'),
  ('id.indonesian', 37, 76, 'Dan Kami telah menyelamatkannya dan pengikutnya dari bencana yang besar.'),
  ('id.indonesian', 37, 77, 'Dan Kami jadikan anak cucunya orang-orang yang melanjutkan keturunan.'),
  ('id.indonesian', 37, 78, 'Dan Kami abadikan untuk Nuh itu (pujian yang baik) di kalangan orang-orang yang datang kemudian;'),
  ('id.indonesian', 37, 79, '"Kesejahteraan dilimpahkan atas Nuh di seluruh alam".'),
  ('id.indonesian', 37, 80, 'Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 37, 81, 'Sesungguhnya dia termasuk di antara hamba-hamba Kami yang beriman.'),
  ('id.indonesian', 37, 82, 'Kemudian Kami tenggelamkan orang-orang yang lain.'),
  ('id.indonesian', 37, 83, 'Dan sesungguhnya Ibrahim benar-benar termasuk golongannya (Nuh).'),
  ('id.indonesian', 37, 84, '(lngatlah) ketika ia datang kepada Tuhannya dengan hati yang suci:'),
  ('id.indonesian', 37, 85, '(Ingatlah) ketika ia berkata kepada bapaknya dan kaumnya: "Apakah yang kamu sembah itu?'),
  ('id.indonesian', 37, 86, 'Apakah kamu menghendaki sembahan-sembahan selain Allah dengan jalan berbohong?'),
  ('id.indonesian', 37, 87, 'Maka apakah anggapanmu terhadap Tuhan semesta alam?"'),
  ('id.indonesian', 37, 88, 'Lalu ia memandang sekali pandang ke bintang-bintang.'),
  ('id.indonesian', 37, 89, 'Kemudian ia berkata: "Sesungguhnya aku sakit".'),
  ('id.indonesian', 37, 90, 'Lalu mereka berpaling daripadanya dengan membelakang.'),
  ('id.indonesian', 37, 91, 'Kemudian ia pergi dengan diam-diam kepada berhala-berhala mereka; lalu ia berkata: "Apakah kamu tidak makan?'),
  ('id.indonesian', 37, 92, 'Kenapa kamu tidak menjawab?"'),
  ('id.indonesian', 37, 93, 'Lalu dihadapinya berhala-berhala itu sambil memukulnya dengan tangan kanannya (dengan kuat).'),
  ('id.indonesian', 37, 94, 'Kemudian kaumnya datang kepadanya dengan bergegas.'),
  ('id.indonesian', 37, 95, 'Ibrahim berkata: "Apakah kamu menyembah patung-patung yang kamu pahat itu?'),
  ('id.indonesian', 37, 96, 'Padahal Allah-lah yang menciptakan kamu dan apa yang kamu perbuat itu".'),
  ('id.indonesian', 37, 97, 'Mereka berkata: "Dirikanlah suatu bangunan untuk (membakar) Ibrahim; lalu lemparkanlah dia ke dalam api yang menyala-nyala itu".'),
  ('id.indonesian', 37, 98, 'Mereka hendak melakukan tipu muslihat kepadanya, maka Kami jadikan mereka orang-orang yang hina.'),
  ('id.indonesian', 37, 99, 'Dan Ibrahim berkata: "Sesungguhnya aku pergi menghadap kepada Tuhanku, dan Dia akan memberi petunjuk kepadaku.'),
  ('id.indonesian', 37, 100, 'Ya Tuhanku, anugrahkanlah kepadaku (seorang anak) yang termasuk orang-orang yang saleh.'),
  ('id.indonesian', 37, 101, 'Maka Kami beri dia khabar gembira dengan seorang anak yang amat sabar.'),
  ('id.indonesian', 37, 102, 'Maka tatkala anak itu sampai (pada umur sanggup) berusaha bersama-sama Ibrahim, Ibrahim berkata: "Hai anakku sesungguhnya aku melihat dalam mimpi bahwa aku menyembelihmu. Maka fikirkanlah apa pendapatmu!" Ia menjawab: "Hai bapakku, kerjakanlah apa yang diperintahkan kepadamu; insya Allah kamu akan mendapatiku termasuk orang-orang yang sabar".'),
  ('id.indonesian', 37, 103, 'Tatkala keduanya telah berserah diri dan Ibrahim membaringkan anaknya atas pelipis(nya), (nyatalah kesabaran keduanya).'),
  ('id.indonesian', 37, 104, 'Dan Kami panggillah dia: "Hai Ibrahim,'),
  ('id.indonesian', 37, 105, 'sesungguhnya kamu telah membenarkan mimpi itu sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 37, 106, 'Sesungguhnya ini benar-benar suatu ujian yang nyata.'),
  ('id.indonesian', 37, 107, 'Dan Kami tebus anak itu dengan seekor sembelihan yang besar.'),
  ('id.indonesian', 37, 108, 'Kami abadikan untuk Ibrahim itu (pujian yang baik) di kalangan orang-orang yang datang kemudian,'),
  ('id.indonesian', 37, 109, '(yaitu)"Kesejahteraan dilimpahkan atas Ibrahim".'),
  ('id.indonesian', 37, 110, 'Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 37, 111, 'Sesungguhnya ia termasuk hamba-hamba Kami yang beriman.'),
  ('id.indonesian', 37, 112, 'Dan Kami beri dia kabar gembira dengan (kelahiran) Ishaq seorang nabi yang termasuk orang-orang yang saleh.'),
  ('id.indonesian', 37, 113, 'Kami limpahkan keberkatan atasnya dan atas Ishaq. Dan diantara anak cucunya ada yang berbuat baik dan ada (pula) yang Zalim terhadap dirinya sendiri dengan nyata.'),
  ('id.indonesian', 37, 114, 'Dan sesungguhnya Kami telah melimpahkan nikmat atas Musa dan Harun.'),
  ('id.indonesian', 37, 115, 'Dan Kami selamatkan keduanya dan kaumnya dari bencana yang besar.'),
  ('id.indonesian', 37, 116, 'Dan Kami tolong mereka, maka jadilah mereka orang-orang yang menang.'),
  ('id.indonesian', 37, 117, 'Dan Kami berikan kepada keduanya kitab yang sangat jelas.'),
  ('id.indonesian', 37, 118, 'Dan Kami tunjuki keduanya ke jalan yang lurus.'),
  ('id.indonesian', 37, 119, 'Dan Kami abadikan untuk keduanya (pujian yang baik) dikalangan orang-orang yang datang kemudian;'),
  ('id.indonesian', 37, 120, '(yaitu): "Kesejahteraan dilimpahkan atas Musa dan Harun".'),
  ('id.indonesian', 37, 121, 'Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 37, 122, 'Sesungguhnya keduanya termasuk hamba-hamba Kami yang beriman.'),
  ('id.indonesian', 37, 123, 'Dan sesungguhnya Ilyas benar-benar termasuk salah seorang rasul-rasul.'),
  ('id.indonesian', 37, 124, '(ingatlah) ketika ia berkata kepada kaumnya: "Mengapa kamu tidak bertakwa?'),
  ('id.indonesian', 37, 125, 'Patutkah kamu menyembah Ba\'l dan kamu tinggalkan sebaik-baik Pencipta,'),
  ('id.indonesian', 37, 126, '(yaitu) Allah Tuhanmu dan Tuhan bapak-bapakmu yang terdahulu?"'),
  ('id.indonesian', 37, 127, 'Maka mereka mendustakannya, karena itu mereka akan diseret (ke neraka),'),
  ('id.indonesian', 37, 128, 'kecuali hamba-hamba Allah yang dibersihkan (dari dosa).'),
  ('id.indonesian', 37, 129, 'Dan Kami abadikan untuk Ilyas (pujian yang baik) di kalangan orang-orang yang datang kemudian.'),
  ('id.indonesian', 37, 130, '(yaitu): "Kesejahteraan dilimpahkan atas Ilyas?"'),
  ('id.indonesian', 37, 131, 'Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 37, 132, 'Sesungguhnya dia termasuk hamba-hamba Kami yang beriman.'),
  ('id.indonesian', 37, 133, 'Sesungguhnya Luth benar-benar salah seorang rasul.'),
  ('id.indonesian', 37, 134, '(Ingatlah) ketika Kami selamatkan dia dan keluarganya (pengikut-pengikutnya) semua,'),
  ('id.indonesian', 37, 135, 'kecuali seorang perempuan tua (isterinya yang berada) bersama-sama orang yang tinggal.'),
  ('id.indonesian', 37, 136, 'Kemudian Kami binasakan orang-orang yang lain.'),
  ('id.indonesian', 37, 137, 'Dan sesungguhnya kamu (hai penduduk Mekah) benar-benar akan melalui (bekas-bekas) mereka di waktu pagi,'),
  ('id.indonesian', 37, 138, 'dan di waktu malam. Maka apakah kamu tidak memikirkan?'),
  ('id.indonesian', 37, 139, 'Sesungguhnya Yunus benar-benar salah seorang rasul,'),
  ('id.indonesian', 37, 140, '(ingatlah) ketika ia lari, ke kapal yang penuh muatan,'),
  ('id.indonesian', 37, 141, 'kemudian ia ikut berundi lalu dia termasuk orang-orang yang kalah dalam undian.'),
  ('id.indonesian', 37, 142, 'Maka ia ditelan oleh ikan besar dalam keadaan tercela.'),
  ('id.indonesian', 37, 143, 'Maka kalau sekiranya dia tidak termasuk orang-orang yang banyak mengingat Allah,'),
  ('id.indonesian', 37, 144, 'niscaya ia akan tetap tinggal di perut ikan itu sampai hari berbangkit.'),
  ('id.indonesian', 37, 145, 'Kemudian Kami lemparkan dia ke daerah yang tandus, sedang ia dalam keadaan sakit.'),
  ('id.indonesian', 37, 146, 'Dan Kami tumbuhkan untuk dia sebatang pohon dari jenis labu.'),
  ('id.indonesian', 37, 147, 'Dan Kami utus dia kepada seratus ribu orang atau lebih.'),
  ('id.indonesian', 37, 148, 'Lalu mereka beriman, karena itu Kami anugerahkan kenikmatan hidup kepada mereka hingga waktu yang tertentu.'),
  ('id.indonesian', 37, 149, 'Tanyakanlah (ya Muhammad) kepada mereka (orang-orang kafir Mekah): "Apakah untuk Tuhanmu anak-anak perempuan dan untuk mereka anak laki-laki,'),
  ('id.indonesian', 37, 150, 'atau apakah Kami menciptakan malaikat-malaikat berupa perempuan dan mereka menyaksikan(nya)?'),
  ('id.indonesian', 37, 151, 'Ketahuilah bahwa sesungguhnya mereka dengan kebohongannya benar-benar mengatakan:'),
  ('id.indonesian', 37, 152, '"Allah beranak". Dan sesungguhnya mereka benar-benar orang yang berdusta.'),
  ('id.indonesian', 37, 153, 'Apakah Tuhan memilih (mengutamakan) anak-anak perempuan daripada anak laki-laki?'),
  ('id.indonesian', 37, 154, 'Apakah yang terjadi padamu? Bagaimana (caranya) kamu menetapkan?'),
  ('id.indonesian', 37, 155, 'Maka apakah kamu tidak memikirkan?'),
  ('id.indonesian', 37, 156, 'Atau apakah kamu mempunyai bukti yang nyata?'),
  ('id.indonesian', 37, 157, 'Maka bawalah kitabmu jika kamu memang orang-orang yang benar.'),
  ('id.indonesian', 37, 158, 'Dan mereka adakan (hubungan) nasab antara Allah dan antara jin. Dan sesungguhnya jin mengetahui bahwa mereka benar-benar akan diseret (ke neraka),'),
  ('id.indonesian', 37, 159, 'Maha Suci Allah dari apa yang mereka sifatkan,'),
  ('id.indonesian', 37, 160, 'Kecuali hamba-hamba Allah yang dibersihkan dari (dosa).'),
  ('id.indonesian', 37, 161, 'Maka sesungguhnya kamu dan apa-apa yang kamu sembah itu,'),
  ('id.indonesian', 37, 162, 'Sekali-kali tidak dapat menyesatkan (seseorang) terhadap Allah,'),
  ('id.indonesian', 37, 163, 'kecuali orang-orang yang akan masuk neraka yang menyala.'),
  ('id.indonesian', 37, 164, 'Tiada seorangpun di antara kami (malaikat) melainkan mempunyai kedudukan yang tertentu,'),
  ('id.indonesian', 37, 165, 'dan sesungguhnya kami benar-benar bershaf-shaf (dalam menunaikan perintah Allah).'),
  ('id.indonesian', 37, 166, 'Dan sesungguhnya kami benar-benar bertasbih (kepada Allah).'),
  ('id.indonesian', 37, 167, 'Sesungguhnya mereka benar-benar akan berkata:'),
  ('id.indonesian', 37, 168, '"Kalau sekiranya di sksi kami ada sebuah kitab dari (kitab-kitab yang diturunkan) kepada orang-orang dahulu,'),
  ('id.indonesian', 37, 169, 'benar-benar kami akan jadi hamba Allah yang dibersihkan (dari dosa)".'),
  ('id.indonesian', 37, 170, 'Tetapi mereka mengingkarinya (Al Quran); maka kelak mereka akan mengetahui (akibat keingkarannya itu).'),
  ('id.indonesian', 37, 171, 'Dan sesungguhnya telah tetap janji Kami kepada hamba-hamba Kami yang menjadi rasul,'),
  ('id.indonesian', 37, 172, '(yaitu) sesungguhnya mereka itulah yang pasti mendapat pertolongan.'),
  ('id.indonesian', 37, 173, 'Dan sesungguhnya tentara Kami itulah yang pasti menang,'),
  ('id.indonesian', 37, 174, 'Maka berpalinglah kamu (Muhammad) dari mereka sampai suatu ketika.'),
  ('id.indonesian', 37, 175, 'Dan lihatlah mereka, maka kelak mereka akan melihat (azab itu).'),
  ('id.indonesian', 37, 176, 'Maka apakah mereka meminta supaya siksa Kami disegerakan?'),
  ('id.indonesian', 37, 177, 'Maka apabila siksaan itu turun dihalaman mereka, maka amat buruklah pagi hari yang dialami oleh orang-orang yang diperingatkan itu.'),
  ('id.indonesian', 37, 178, 'Dan berpalinglah kamu dari mereka hingga suatu ketika.'),
  ('id.indonesian', 37, 179, 'Dan lihatlah, maka kelak mereka juga akan melihat.'),
  ('id.indonesian', 37, 180, 'Maha Suci Tuhanmu Yang mempunyai keperkasaan dari apa yang mereka katakan.'),
  ('id.indonesian', 37, 181, 'Dan kesejahteraan dilimpahkan atas para rasul.'),
  ('id.indonesian', 37, 182, 'Dan segala puji bagi Allah Tuhan seru sekalian alam.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (37, 13, 3801, 'وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ', 446, 23, 178, 0),
  (37, 14, 3802, 'وَإِذَا رَأَوْا۟ ءَايَةًۭ يَسْتَسْخِرُونَ', 446, 23, 178, 0),
  (37, 15, 3803, 'وَقَالُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌ', 446, 23, 178, 0),
  (37, 16, 3804, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 446, 23, 178, 0),
  (37, 17, 3805, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 446, 23, 178, 0),
  (37, 18, 3806, 'قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ', 446, 23, 178, 0),
  (37, 19, 3807, 'فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ فَإِذَا هُمْ يَنظُرُونَ', 446, 23, 178, 0),
  (37, 20, 3808, 'وَقَالُوا۟ يَٰوَيْلَنَا هَٰذَا يَوْمُ ٱلدِّينِ', 446, 23, 178, 0),
  (37, 21, 3809, 'هَٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 446, 23, 178, 0),
  (37, 22, 3810, '۞ ٱحْشُرُوا۟ ٱلَّذِينَ ظَلَمُوا۟ وَأَزْوَٰجَهُمْ وَمَا كَانُوا۟ يَعْبُدُونَ', 446, 23, 179, 0),
  (37, 23, 3811, 'مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ', 446, 23, 179, 0),
  (37, 24, 3812, 'وَقِفُوهُمْ ۖ إِنَّهُم مَّسْـُٔولُونَ', 446, 23, 179, 0),
  (37, 25, 3813, 'مَا لَكُمْ لَا تَنَاصَرُونَ', 447, 23, 179, 0),
  (37, 26, 3814, 'بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ', 447, 23, 179, 0),
  (37, 27, 3815, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ', 447, 23, 179, 0),
  (37, 28, 3816, 'قَالُوٓا۟ إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ ٱلْيَمِينِ', 447, 23, 179, 0),
  (37, 29, 3817, 'قَالُوا۟ بَل لَّمْ تَكُونُوا۟ مُؤْمِنِينَ', 447, 23, 179, 0),
  (37, 30, 3818, 'وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنٍۭ ۖ بَلْ كُنتُمْ قَوْمًۭا طَٰغِينَ', 447, 23, 179, 0),
  (37, 31, 3819, 'فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ ۖ إِنَّا لَذَآئِقُونَ', 447, 23, 179, 0),
  (37, 32, 3820, 'فَأَغْوَيْنَٰكُمْ إِنَّا كُنَّا غَٰوِينَ', 447, 23, 179, 0),
  (37, 33, 3821, 'فَإِنَّهُمْ يَوْمَئِذٍۢ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 447, 23, 179, 0),
  (37, 34, 3822, 'إِنَّا كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 447, 23, 179, 0),
  (37, 35, 3823, 'إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ', 447, 23, 179, 0),
  (37, 36, 3824, 'وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا۟ ءَالِهَتِنَا لِشَاعِرٍۢ مَّجْنُونٍۭ', 447, 23, 179, 0),
  (37, 37, 3825, 'بَلْ جَآءَ بِٱلْحَقِّ وَصَدَّقَ ٱلْمُرْسَلِينَ', 447, 23, 179, 0),
  (37, 38, 3826, 'إِنَّكُمْ لَذَآئِقُوا۟ ٱلْعَذَابِ ٱلْأَلِيمِ', 447, 23, 179, 0),
  (37, 39, 3827, 'وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ', 447, 23, 179, 0),
  (37, 40, 3828, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 447, 23, 179, 0),
  (37, 41, 3829, 'أُو۟لَٰٓئِكَ لَهُمْ رِزْقٌۭ مَّعْلُومٌۭ', 447, 23, 179, 0),
  (37, 42, 3830, 'فَوَٰكِهُ ۖ وَهُم مُّكْرَمُونَ', 447, 23, 179, 0),
  (37, 43, 3831, 'فِى جَنَّٰتِ ٱلنَّعِيمِ', 447, 23, 179, 0),
  (37, 44, 3832, 'عَلَىٰ سُرُرٍۢ مُّتَقَٰبِلِينَ', 447, 23, 179, 0),
  (37, 45, 3833, 'يُطَافُ عَلَيْهِم بِكَأْسٍۢ مِّن مَّعِينٍۭ', 447, 23, 179, 0),
  (37, 46, 3834, 'بَيْضَآءَ لَذَّةٍۢ لِّلشَّٰرِبِينَ', 447, 23, 179, 0),
  (37, 47, 3835, 'لَا فِيهَا غَوْلٌۭ وَلَا هُمْ عَنْهَا يُنزَفُونَ', 447, 23, 179, 0),
  (37, 48, 3836, 'وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ عِينٌۭ', 447, 23, 179, 0),
  (37, 49, 3837, 'كَأَنَّهُنَّ بَيْضٌۭ مَّكْنُونٌۭ', 447, 23, 179, 0),
  (37, 50, 3838, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ', 447, 23, 179, 0),
  (37, 51, 3839, 'قَالَ قَآئِلٌۭ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌۭ', 447, 23, 179, 0),
  (37, 52, 3840, 'يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ', 448, 23, 179, 0),
  (37, 53, 3841, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ', 448, 23, 179, 0),
  (37, 54, 3842, 'قَالَ هَلْ أَنتُم مُّطَّلِعُونَ', 448, 23, 179, 0),
  (37, 55, 3843, 'فَٱطَّلَعَ فَرَءَاهُ فِى سَوَآءِ ٱلْجَحِيمِ', 448, 23, 179, 0),
  (37, 56, 3844, 'قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرْدِينِ', 448, 23, 179, 0),
  (37, 57, 3845, 'وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ', 448, 23, 179, 0),
  (37, 58, 3846, 'أَفَمَا نَحْنُ بِمَيِّتِينَ', 448, 23, 179, 0),
  (37, 59, 3847, 'إِلَّا مَوْتَتَنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ', 448, 23, 179, 0),
  (37, 60, 3848, 'إِنَّ هَٰذَا لَهُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 448, 23, 179, 0),
  (37, 61, 3849, 'لِمِثْلِ هَٰذَا فَلْيَعْمَلِ ٱلْعَٰمِلُونَ', 448, 23, 179, 0),
  (37, 62, 3850, 'أَذَٰلِكَ خَيْرٌۭ نُّزُلًا أَمْ شَجَرَةُ ٱلزَّقُّومِ', 448, 23, 179, 0),
  (37, 63, 3851, 'إِنَّا جَعَلْنَٰهَا فِتْنَةًۭ لِّلظَّٰلِمِينَ', 448, 23, 179, 0),
  (37, 64, 3852, 'إِنَّهَا شَجَرَةٌۭ تَخْرُجُ فِىٓ أَصْلِ ٱلْجَحِيمِ', 448, 23, 179, 0),
  (37, 65, 3853, 'طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ', 448, 23, 179, 0),
  (37, 66, 3854, 'فَإِنَّهُمْ لَءَاكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 448, 23, 179, 0),
  (37, 67, 3855, 'ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًۭا مِّنْ حَمِيمٍۢ', 448, 23, 179, 0),
  (37, 68, 3856, 'ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ٱلْجَحِيمِ', 448, 23, 179, 0),
  (37, 69, 3857, 'إِنَّهُمْ أَلْفَوْا۟ ءَابَآءَهُمْ ضَآلِّينَ', 448, 23, 179, 0),
  (37, 70, 3858, 'فَهُمْ عَلَىٰٓ ءَاثَٰرِهِمْ يُهْرَعُونَ', 448, 23, 179, 0),
  (37, 71, 3859, 'وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ ٱلْأَوَّلِينَ', 448, 23, 179, 0),
  (37, 72, 3860, 'وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ', 448, 23, 179, 0),
  (37, 73, 3861, 'فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ', 448, 23, 179, 0),
  (37, 74, 3862, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 448, 23, 179, 0),
  (37, 75, 3863, 'وَلَقَدْ نَادَىٰنَا نُوحٌۭ فَلَنِعْمَ ٱلْمُجِيبُونَ', 448, 23, 179, 0),
  (37, 76, 3864, 'وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 448, 23, 179, 0),
  (37, 77, 3865, 'وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ٱلْبَاقِينَ', 449, 23, 179, 0),
  (37, 78, 3866, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 449, 23, 179, 0),
  (37, 79, 3867, 'سَلَٰمٌ عَلَىٰ نُوحٍۢ فِى ٱلْعَٰلَمِينَ', 449, 23, 179, 0),
  (37, 80, 3868, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 449, 23, 179, 0),
  (37, 81, 3869, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 449, 23, 179, 0),
  (37, 82, 3870, 'ثُمَّ أَغْرَقْنَا ٱلْءَاخَرِينَ', 449, 23, 179, 0),
  (37, 83, 3871, '۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ', 449, 23, 180, 0),
  (37, 84, 3872, 'إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍۢ سَلِيمٍ', 449, 23, 180, 0),
  (37, 85, 3873, 'إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ', 449, 23, 180, 0),
  (37, 86, 3874, 'أَئِفْكًا ءَالِهَةًۭ دُونَ ٱللَّهِ تُرِيدُونَ', 449, 23, 180, 0),
  (37, 87, 3875, 'فَمَا ظَنُّكُم بِرَبِّ ٱلْعَٰلَمِينَ', 449, 23, 180, 0),
  (37, 88, 3876, 'فَنَظَرَ نَظْرَةًۭ فِى ٱلنُّجُومِ', 449, 23, 180, 0),
  (37, 89, 3877, 'فَقَالَ إِنِّى سَقِيمٌۭ', 449, 23, 180, 0),
  (37, 90, 3878, 'فَتَوَلَّوْا۟ عَنْهُ مُدْبِرِينَ', 449, 23, 180, 0),
  (37, 91, 3879, 'فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ', 449, 23, 180, 0),
  (37, 92, 3880, 'مَا لَكُمْ لَا تَنطِقُونَ', 449, 23, 180, 0),
  (37, 93, 3881, 'فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ', 449, 23, 180, 0),
  (37, 94, 3882, 'فَأَقْبَلُوٓا۟ إِلَيْهِ يَزِفُّونَ', 449, 23, 180, 0),
  (37, 95, 3883, 'قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ', 449, 23, 180, 0),
  (37, 96, 3884, 'وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ', 449, 23, 180, 0),
  (37, 97, 3885, 'قَالُوا۟ ٱبْنُوا۟ لَهُۥ بُنْيَٰنًۭا فَأَلْقُوهُ فِى ٱلْجَحِيمِ', 449, 23, 180, 0),
  (37, 98, 3886, 'فَأَرَادُوا۟ بِهِۦ كَيْدًۭا فَجَعَلْنَٰهُمُ ٱلْأَسْفَلِينَ', 449, 23, 180, 0),
  (37, 99, 3887, 'وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ', 449, 23, 180, 0),
  (37, 100, 3888, 'رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ', 449, 23, 180, 0),
  (37, 101, 3889, 'فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمٍۢ', 449, 23, 180, 0),
  (37, 102, 3890, 'فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ ۚ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ ۖ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ', 449, 23, 180, 0),
  (37, 103, 3891, 'فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ', 450, 23, 180, 0),
  (37, 104, 3892, 'وَنَٰدَيْنَٰهُ أَن يَٰٓإِبْرَٰهِيمُ', 450, 23, 180, 0),
  (37, 105, 3893, 'قَدْ صَدَّقْتَ ٱلرُّءْيَآ ۚ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 450, 23, 180, 0),
  (37, 106, 3894, 'إِنَّ هَٰذَا لَهُوَ ٱلْبَلَٰٓؤُا۟ ٱلْمُبِينُ', 450, 23, 180, 0),
  (37, 107, 3895, 'وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍۢ', 450, 23, 180, 0),
  (37, 108, 3896, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 450, 23, 180, 0),
  (37, 109, 3897, 'سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ', 450, 23, 180, 0),
  (37, 110, 3898, 'كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 450, 23, 180, 0),
  (37, 111, 3899, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 450, 23, 180, 0),
  (37, 112, 3900, 'وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ', 450, 23, 180, 0),
  (37, 113, 3901, 'وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ ۚ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌۭ وَظَالِمٌۭ لِّنَفْسِهِۦ مُبِينٌۭ', 450, 23, 180, 0),
  (37, 114, 3902, 'وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 450, 23, 180, 0),
  (37, 115, 3903, 'وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ', 450, 23, 180, 0),
  (37, 116, 3904, 'وَنَصَرْنَٰهُمْ فَكَانُوا۟ هُمُ ٱلْغَٰلِبِينَ', 450, 23, 180, 0),
  (37, 117, 3905, 'وَءَاتَيْنَٰهُمَا ٱلْكِتَٰبَ ٱلْمُسْتَبِينَ', 450, 23, 180, 0),
  (37, 118, 3906, 'وَهَدَيْنَٰهُمَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ', 450, 23, 180, 0),
  (37, 119, 3907, 'وَتَرَكْنَا عَلَيْهِمَا فِى ٱلْءَاخِرِينَ', 450, 23, 180, 0),
  (37, 120, 3908, 'سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ', 450, 23, 180, 0),
  (37, 121, 3909, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 450, 23, 180, 0),
  (37, 122, 3910, 'إِنَّهُمَا مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 450, 23, 180, 0),
  (37, 123, 3911, 'وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ', 450, 23, 180, 0),
  (37, 124, 3912, 'إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ', 450, 23, 180, 0),
  (37, 125, 3913, 'أَتَدْعُونَ بَعْلًۭا وَتَذَرُونَ أَحْسَنَ ٱلْخَٰلِقِينَ', 450, 23, 180, 0),
  (37, 126, 3914, 'ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 450, 23, 180, 0),
  (37, 127, 3915, 'فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ', 451, 23, 180, 0),
  (37, 128, 3916, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 451, 23, 180, 0),
  (37, 129, 3917, 'وَتَرَكْنَا عَلَيْهِ فِى ٱلْءَاخِرِينَ', 451, 23, 180, 0),
  (37, 130, 3918, 'سَلَٰمٌ عَلَىٰٓ إِلْ يَاسِينَ', 451, 23, 180, 0),
  (37, 131, 3919, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 451, 23, 180, 0),
  (37, 132, 3920, 'إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ', 451, 23, 180, 0),
  (37, 133, 3921, 'وَإِنَّ لُوطًۭا لَّمِنَ ٱلْمُرْسَلِينَ', 451, 23, 180, 0),
  (37, 134, 3922, 'إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ', 451, 23, 180, 0),
  (37, 135, 3923, 'إِلَّا عَجُوزًۭا فِى ٱلْغَٰبِرِينَ', 451, 23, 180, 0),
  (37, 136, 3924, 'ثُمَّ دَمَّرْنَا ٱلْءَاخَرِينَ', 451, 23, 180, 0),
  (37, 137, 3925, 'وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ', 451, 23, 180, 0),
  (37, 138, 3926, 'وَبِٱلَّيْلِ ۗ أَفَلَا تَعْقِلُونَ', 451, 23, 180, 0),
  (37, 139, 3927, 'وَإِنَّ يُونُسَ لَمِنَ ٱلْمُرْسَلِينَ', 451, 23, 180, 0),
  (37, 140, 3928, 'إِذْ أَبَقَ إِلَى ٱلْفُلْكِ ٱلْمَشْحُونِ', 451, 23, 180, 0),
  (37, 141, 3929, 'فَسَاهَمَ فَكَانَ مِنَ ٱلْمُدْحَضِينَ', 451, 23, 180, 0),
  (37, 142, 3930, 'فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌۭ', 451, 23, 180, 0),
  (37, 143, 3931, 'فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ', 451, 23, 180, 0),
  (37, 144, 3932, 'لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 451, 23, 180, 0),
  (37, 145, 3933, '۞ فَنَبَذْنَٰهُ بِٱلْعَرَآءِ وَهُوَ سَقِيمٌۭ', 451, 23, 181, 0),
  (37, 146, 3934, 'وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةًۭ مِّن يَقْطِينٍۢ', 451, 23, 181, 0),
  (37, 147, 3935, 'وَأَرْسَلْنَٰهُ إِلَىٰ مِا۟ئَةِ أَلْفٍ أَوْ يَزِيدُونَ', 451, 23, 181, 0),
  (37, 148, 3936, 'فَـَٔامَنُوا۟ فَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍۢ', 451, 23, 181, 0),
  (37, 149, 3937, 'فَٱسْتَفْتِهِمْ أَلِرَبِّكَ ٱلْبَنَاتُ وَلَهُمُ ٱلْبَنُونَ', 451, 23, 181, 0),
  (37, 150, 3938, 'أَمْ خَلَقْنَا ٱلْمَلَٰٓئِكَةَ إِنَٰثًۭا وَهُمْ شَٰهِدُونَ', 451, 23, 181, 0),
  (37, 151, 3939, 'أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ', 451, 23, 181, 0),
  (37, 152, 3940, 'وَلَدَ ٱللَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ', 451, 23, 181, 0),
  (37, 153, 3941, 'أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ', 451, 23, 181, 0),
  (37, 154, 3942, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 452, 23, 181, 0),
  (37, 155, 3943, 'أَفَلَا تَذَكَّرُونَ', 452, 23, 181, 0),
  (37, 156, 3944, 'أَمْ لَكُمْ سُلْطَٰنٌۭ مُّبِينٌۭ', 452, 23, 181, 0),
  (37, 157, 3945, 'فَأْتُوا۟ بِكِتَٰبِكُمْ إِن كُنتُمْ صَٰدِقِينَ', 452, 23, 181, 0),
  (37, 158, 3946, 'وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًۭا ۚ وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ', 452, 23, 181, 0),
  (37, 159, 3947, 'سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ', 452, 23, 181, 0),
  (37, 160, 3948, 'إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 452, 23, 181, 0),
  (37, 161, 3949, 'فَإِنَّكُمْ وَمَا تَعْبُدُونَ', 452, 23, 181, 0),
  (37, 162, 3950, 'مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ', 452, 23, 181, 0),
  (37, 163, 3951, 'إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ', 452, 23, 181, 0),
  (37, 164, 3952, 'وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌۭ مَّعْلُومٌۭ', 452, 23, 181, 0),
  (37, 165, 3953, 'وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ', 452, 23, 181, 0),
  (37, 166, 3954, 'وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ', 452, 23, 181, 0),
  (37, 167, 3955, 'وَإِن كَانُوا۟ لَيَقُولُونَ', 452, 23, 181, 0),
  (37, 168, 3956, 'لَوْ أَنَّ عِندَنَا ذِكْرًۭا مِّنَ ٱلْأَوَّلِينَ', 452, 23, 181, 0),
  (37, 169, 3957, 'لَكُنَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ', 452, 23, 181, 0),
  (37, 170, 3958, 'فَكَفَرُوا۟ بِهِۦ ۖ فَسَوْفَ يَعْلَمُونَ', 452, 23, 181, 0),
  (37, 171, 3959, 'وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ٱلْمُرْسَلِينَ', 452, 23, 181, 0),
  (37, 172, 3960, 'إِنَّهُمْ لَهُمُ ٱلْمَنصُورُونَ', 452, 23, 181, 0),
  (37, 173, 3961, 'وَإِنَّ جُندَنَا لَهُمُ ٱلْغَٰلِبُونَ', 452, 23, 181, 0),
  (37, 174, 3962, 'فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍۢ', 452, 23, 181, 0),
  (37, 175, 3963, 'وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ', 452, 23, 181, 0),
  (37, 176, 3964, 'أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ', 452, 23, 181, 0),
  (37, 177, 3965, 'فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ٱلْمُنذَرِينَ', 452, 23, 181, 0),
  (37, 178, 3966, 'وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍۢ', 452, 23, 181, 0),
  (37, 179, 3967, 'وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ', 452, 23, 181, 0),
  (37, 180, 3968, 'سُبْحَٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ', 452, 23, 181, 0),
  (37, 181, 3969, 'وَسَلَٰمٌ عَلَى ٱلْمُرْسَلِينَ', 452, 23, 181, 0),
  (37, 182, 3970, 'وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 452, 23, 181, 0),
  (38, 1, 3971, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ صٓ ۚ وَٱلْقُرْءَانِ ذِى ٱلذِّكْرِ', 453, 23, 181, 0),
  (38, 2, 3972, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى عِزَّةٍۢ وَشِقَاقٍۢ', 453, 23, 181, 0),
  (38, 3, 3973, 'كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍۢ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍۢ', 453, 23, 181, 0),
  (38, 4, 3974, 'وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌۭ مِّنْهُمْ ۖ وَقَالَ ٱلْكَٰفِرُونَ هَٰذَا سَٰحِرٌۭ كَذَّابٌ', 453, 23, 181, 0),
  (38, 5, 3975, 'أَجَعَلَ ٱلْءَالِهَةَ إِلَٰهًۭا وَٰحِدًا ۖ إِنَّ هَٰذَا لَشَىْءٌ عُجَابٌۭ', 453, 23, 181, 0),
  (38, 6, 3976, 'وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ ۖ إِنَّ هَٰذَا لَشَىْءٌۭ يُرَادُ', 453, 23, 181, 0),
  (38, 7, 3977, 'مَا سَمِعْنَا بِهَٰذَا فِى ٱلْمِلَّةِ ٱلْءَاخِرَةِ إِنْ هَٰذَآ إِلَّا ٱخْتِلَٰقٌ', 453, 23, 181, 0),
  (38, 8, 3978, 'أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا ۚ بَلْ هُمْ فِى شَكٍّۢ مِّن ذِكْرِى ۖ بَل لَّمَّا يَذُوقُوا۟ عَذَابِ', 453, 23, 181, 0),
  (38, 9, 3979, 'أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ', 453, 23, 181, 0),
  (38, 10, 3980, 'أَمْ لَهُم مُّلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَٰبِ', 453, 23, 181, 0),
  (38, 11, 3981, 'جُندٌۭ مَّا هُنَالِكَ مَهْزُومٌۭ مِّنَ ٱلْأَحْزَابِ', 453, 23, 181, 0),
  (38, 12, 3982, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَعَادٌۭ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ', 453, 23, 181, 0),
  (38, 13, 3983, 'وَثَمُودُ وَقَوْمُ لُوطٍۢ وَأَصْحَٰبُ لْـَٔيْكَةِ ۚ أُو۟لَٰٓئِكَ ٱلْأَحْزَابُ', 453, 23, 181, 0),
  (38, 14, 3984, 'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ', 453, 23, 181, 0),
  (38, 15, 3985, 'وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيْحَةًۭ وَٰحِدَةًۭ مَّا لَهَا مِن فَوَاقٍۢ', 453, 23, 181, 0),
  (38, 16, 3986, 'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ', 453, 23, 181, 0),
  (38, 17, 3987, 'ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ ۖ إِنَّهُۥٓ أَوَّابٌ', 454, 23, 181, 0),
  (38, 18, 3988, 'إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ', 454, 23, 181, 0),
  (38, 19, 3989, 'وَٱلطَّيْرَ مَحْشُورَةًۭ ۖ كُلٌّۭ لَّهُۥٓ أَوَّابٌۭ', 454, 23, 181, 0),
  (38, 20, 3990, 'وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ', 454, 23, 181, 0),
  (38, 21, 3991, '۞ وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ', 454, 23, 182, 0),
  (38, 22, 3992, 'إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ ۖ قَالُوا۟ لَا تَخَفْ ۖ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍۢ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ', 454, 23, 182, 0),
  (38, 23, 3993, 'إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌۭ وَتِسْعُونَ نَعْجَةًۭ وَلِىَ نَعْجَةٌۭ وَٰحِدَةٌۭ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ', 454, 23, 182, 0),
  (38, 24, 3994, 'قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ ۖ وَإِنَّ كَثِيرًۭا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَقَلِيلٌۭ مَّا هُمْ ۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًۭا وَأَنَابَ ۩', 454, 23, 182, 1),
  (38, 25, 3995, 'فَغَفَرْنَا لَهُۥ ذَٰلِكَ ۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍۢ', 454, 23, 182, 0),
  (38, 26, 3996, 'يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةًۭ فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', 454, 23, 182, 0),
  (38, 27, 3997, 'وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًۭا ۚ ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ ۚ فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ', 455, 23, 182, 0),
  (38, 28, 3998, 'أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ', 455, 23, 182, 0),
  (38, 29, 3999, 'كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌۭ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 455, 23, 182, 0),
  (38, 30, 4000, 'وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ ۚ نِعْمَ ٱلْعَبْدُ ۖ إِنَّهُۥٓ أَوَّابٌ', 455, 23, 182, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 38, 1, 'Sad. By the Qur\'an containing reminder...'),
  ('en.sahih', 38, 2, 'But those who disbelieve are in pride and dissension.'),
  ('en.sahih', 38, 3, 'How many a generation have We destroyed before them, and they [then] called out; but it was not a time for escape.'),
  ('en.sahih', 38, 4, 'And they wonder that there has come to them a warner from among themselves. And the disbelievers say, "This is a magician and a liar.'),
  ('en.sahih', 38, 5, 'Has he made the gods [only] one God? Indeed, this is a curious thing."'),
  ('en.sahih', 38, 6, 'And the eminent among them went forth, [saying], "Continue, and be patient over [the defense of] your gods. Indeed, this is a thing intended.'),
  ('en.sahih', 38, 7, 'We have not heard of this in the latest religion. This is not but a fabrication.'),
  ('en.sahih', 38, 8, 'Has the message been revealed to him out of [all of] us?" Rather, they are in doubt about My message. Rather, they have not yet tasted My punishment.'),
  ('en.sahih', 38, 9, 'Or do they have the depositories of the mercy of your Lord, the Exalted in Might, the Bestower?'),
  ('en.sahih', 38, 10, 'Or is theirs the dominion of the heavens and the earth and what is between them? Then let them ascend through [any] ways of access.'),
  ('en.sahih', 38, 11, '[They are but] soldiers [who will be] defeated there among the companies [of disbelievers].'),
  ('en.sahih', 38, 12, 'The people of Noah denied before them, and [the tribe of] \'Aad and Pharaoh, the owner of stakes,'),
  ('en.sahih', 38, 13, 'And [the tribe of] Thamud and the people of Lot and the companions of the thicket. Those are the companies.'),
  ('en.sahih', 38, 14, 'Each of them denied the messengers, so My penalty was justified.'),
  ('en.sahih', 38, 15, 'And these [disbelievers] await not but one blast [of the Horn]; for it there will be no delay.'),
  ('en.sahih', 38, 16, 'And they say, "Our Lord, hasten for us our share [of the punishment] before the Day of Account"'),
  ('en.sahih', 38, 17, 'Be patient over what they say and remember Our servant, David, the possessor of strength; indeed, he was one who repeatedly turned back [to Allah].'),
  ('en.sahih', 38, 18, 'Indeed, We subjected the mountains [to praise] with him, exalting [Allah] in the [late] afternoon and [after] sunrise.'),
  ('en.sahih', 38, 19, 'And the birds were assembled, all with him repeating [praises].'),
  ('en.sahih', 38, 20, 'And We strengthened his kingdom and gave him wisdom and discernment in speech.'),
  ('en.sahih', 38, 21, 'And has there come to you the news of the adversaries, when they climbed over the wall of [his] prayer chamber -'),
  ('en.sahih', 38, 22, 'When they entered upon David and he was alarmed by them? They said, "Fear not. [We are] two adversaries, one of whom has wronged the other, so judge between us with truth and do not exceed [it] and guide us to the sound path.'),
  ('en.sahih', 38, 23, 'Indeed this, my brother, has ninety-nine ewes, and I have one ewe; so he said, \'Entrust her to me,\' and he overpowered me in speech."'),
  ('en.sahih', 38, 24, '[David] said, "He has certainly wronged you in demanding your ewe [in addition] to his ewes. And indeed, many associates oppress one another, except for those who believe and do righteous deeds - and few are they." And David became certain that We had tried him, and he asked forgiveness of his Lord and fell down bowing [in prostration] and turned in repentance [to Allah].'),
  ('en.sahih', 38, 25, 'So We forgave him that; and indeed, for him is nearness to Us and a good place of return.'),
  ('en.sahih', 38, 26, '[We said], "O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allah." Indeed, those who go astray from the way of Allah will have a severe punishment for having forgotten the Day of Account.'),
  ('en.sahih', 38, 27, 'And We did not create the heaven and the earth and that between them aimlessly. That is the assumption of those who disbelieve, so woe to those who disbelieve from the Fire.'),
  ('en.sahih', 38, 28, 'Or should we treat those who believe and do righteous deeds like corrupters in the land? Or should We treat those who fear Allah like the wicked?'),
  ('en.sahih', 38, 29, '[This is] a blessed Book which We have revealed to you, [O Muhammad], that they might reflect upon its verses and that those of understanding would be reminded.'),
  ('en.sahih', 38, 30, 'And to David We gave Solomon. An excellent servant, indeed he was one repeatedly turning back [to Allah].'),
  ('en.sahih', 38, 31, '[Mention] when there were exhibited before him in the afternoon the poised [standing] racehorses.'),
  ('en.sahih', 38, 32, 'And he said, "Indeed, I gave preference to the love of good [things] over the remembrance of my Lord until the sun disappeared into the curtain [of darkness]."'),
  ('en.sahih', 38, 33, '[He said], "Return them to me," and set about striking [their] legs and necks.'),
  ('en.sahih', 38, 34, 'And We certainly tried Solomon and placed on his throne a body; then he returned.'),
  ('en.sahih', 38, 35, 'He said, "My Lord, forgive me and grant me a kingdom such as will not belong to anyone after me. Indeed, You are the Bestower."'),
  ('en.sahih', 38, 36, 'So We subjected to him the wind blowing by his command, gently, wherever he directed,'),
  ('en.sahih', 38, 37, 'And [also] the devils [of jinn] - every builder and diver'),
  ('en.sahih', 38, 38, 'And others bound together in shackles.'),
  ('en.sahih', 38, 39, '[We said], "This is Our gift, so grant or withhold without account."'),
  ('en.sahih', 38, 40, 'And indeed, for him is nearness to Us and a good place of return.'),
  ('en.sahih', 38, 41, 'And remember Our servant Job, when he called to his Lord, "Indeed, Satan has touched me with hardship and torment."'),
  ('en.sahih', 38, 42, '[So he was told], "Strike [the ground] with your foot; this is a [spring for] a cool bath and drink."'),
  ('en.sahih', 38, 43, 'And We granted him his family and a like [number] with them as mercy from Us and a reminder for those of understanding.'),
  ('en.sahih', 38, 44, '[We said], "And take in your hand a bunch [of grass] and strike with it and do not break your oath." Indeed, We found him patient, an excellent servant. Indeed, he was one repeatedly turning back [to Allah].'),
  ('en.sahih', 38, 45, 'And remember Our servants, Abraham, Isaac and Jacob - those of strength and [religious] vision.'),
  ('en.sahih', 38, 46, 'Indeed, We chose them for an exclusive quality: remembrance of the home [of the Hereafter].'),
  ('en.sahih', 38, 47, 'And indeed they are, to Us, among the chosen and outstanding.'),
  ('en.sahih', 38, 48, 'And remember Ishmael, Elisha and Dhul-Kifl, and all are among the outstanding.'),
  ('en.sahih', 38, 49, 'This is a reminder. And indeed, for the righteous is a good place of return'),
  ('en.sahih', 38, 50, 'Gardens of perpetual residence, whose doors will be opened to them.'),
  ('en.sahih', 38, 51, 'Reclining within them, they will call therein for abundant fruit and drink.'),
  ('en.sahih', 38, 52, 'And with them will be women limiting [their] glances and of equal age.'),
  ('en.sahih', 38, 53, 'This is what you, [the righteous], are promised for the Day of Account.'),
  ('en.sahih', 38, 54, 'Indeed, this is Our provision; for it there is no depletion.'),
  ('en.sahih', 38, 55, 'This [is so]. But indeed, for the transgressors is an evil place of return -'),
  ('en.sahih', 38, 56, 'Hell, which they will [enter to] burn, and wretched is the resting place.'),
  ('en.sahih', 38, 57, 'This - so let them taste it - is scalding water and [foul] purulence.'),
  ('en.sahih', 38, 58, 'And other [punishments] of its type [in various] kinds.'),
  ('en.sahih', 38, 59, '[Its inhabitants will say], "This is a company bursting in with you. No welcome for them. Indeed, they will burn in the Fire."'),
  ('en.sahih', 38, 60, 'They will say, "Nor you! No welcome for you. You, [our leaders], brought this upon us, and wretched is the settlement."'),
  ('en.sahih', 38, 61, 'They will say, "Our Lord, whoever brought this upon us - increase for him double punishment in the Fire."'),
  ('en.sahih', 38, 62, 'And they will say, "Why do we not see men whom we used to count among the worst?'),
  ('en.sahih', 38, 63, 'Is it [because] we took them in ridicule, or has [our] vision turned away from them?"'),
  ('en.sahih', 38, 64, 'Indeed, that is truth - the quarreling of the people of the Fire.'),
  ('en.sahih', 38, 65, 'Say, [O Muhammad], "I am only a warner, and there is not any deity except Allah, the One, the Prevailing.'),
  ('en.sahih', 38, 66, 'Lord of the heavens and the earth and whatever is between them, the Exalted in Might, the Perpetual Forgiver."'),
  ('en.sahih', 38, 67, 'Say, "It is great news'),
  ('en.sahih', 38, 68, 'From which you turn away.'),
  ('en.sahih', 38, 69, 'I had no knowledge of the exalted assembly [of angels] when they were disputing [the creation of Adam].'),
  ('en.sahih', 38, 70, 'It has not been revealed to me except that I am a clear warner."'),
  ('en.sahih', 38, 71, '[So mention] when your Lord said to the angels, "Indeed, I am going to create a human being from clay.'),
  ('en.sahih', 38, 72, 'So when I have proportioned him and breathed into him of My [created] soul, then fall down to him in prostration."'),
  ('en.sahih', 38, 73, 'So the angels prostrated - all of them entirely.'),
  ('en.sahih', 38, 74, 'Except Iblees; he was arrogant and became among the disbelievers.'),
  ('en.sahih', 38, 75, '[Allah] said, "O Iblees, what prevented you from prostrating to that which I created with My hands? Were you arrogant [then], or were you [already] among the haughty?"'),
  ('en.sahih', 38, 76, 'He said, "I am better than him. You created me from fire and created him from clay."'),
  ('en.sahih', 38, 77, '[Allah] said, "Then get out of Paradise, for indeed, you are expelled.'),
  ('en.sahih', 38, 78, 'And indeed, upon you is My curse until the Day of Recompense."'),
  ('en.sahih', 38, 79, 'He said, "My Lord, then reprieve me until the Day they are resurrected."'),
  ('en.sahih', 38, 80, '[Allah] said, "So indeed, you are of those reprieved'),
  ('en.sahih', 38, 81, 'Until the Day of the time well-known."'),
  ('en.sahih', 38, 82, '[Iblees] said, "By your might, I will surely mislead them all'),
  ('en.sahih', 38, 83, 'Except, among them, Your chosen servants."'),
  ('en.sahih', 38, 84, '[Allah] said, "The truth [is My oath], and the truth I say -'),
  ('en.sahih', 38, 85, '[That] I will surely fill Hell with you and those of them that follow you all together."'),
  ('en.sahih', 38, 86, 'Say, [O Muhammad], "I do not ask you for the Qur\'an any payment, and I am not of the pretentious'),
  ('en.sahih', 38, 87, 'It is but a reminder to the worlds.'),
  ('en.sahih', 38, 88, 'And you will surely know [the truth of] its information after a time."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 38, 1, 'ছোয়াদ। শপথ উপদেশপূর্ণ কোরআনের,'),
  ('bn.bengali', 38, 2, 'বরং যারা কাফের, তারা অহংকার ও বিরোধিতায় লিপ্ত।'),
  ('bn.bengali', 38, 3, 'তাদের আগে আমি কত জনগোষ্ঠীকে ধ্বংস করেছি, অতঃপর তারা আর্তনাদ করতে শুরু করেছে কিন্তু তাদের নিষ্কৃতি লাভের সময় ছিল না।'),
  ('bn.bengali', 38, 4, 'তারা বিস্ময়বোধ করে যে, তাদেরই কাছে তাদের মধ্যে থেকে একজন সতর্ককারী আগমন করেছেন। আর কাফেররা বলে এ-তো এক মিথ্যাচারী যাদুকর।'),
  ('bn.bengali', 38, 5, 'সে কি বহু উপাস্যের পরিবর্তে এক উপাস্যের উপাসনা সাব্যস্ত করে দিয়েছে। নিশ্চয় এটা এক বিস্ময়কর ব্যাপার।'),
  ('bn.bengali', 38, 6, 'তাদের কতিপয় বিশিষ্ট ব্যক্তি একথা বলে প্রস্থান করে যে, তোমরা চলে যাও এবং তোমাদের উপাস্যদের পূজায় দৃঢ় থাক। নিশ্চয়ই এ বক্তব্য কোন বিশেষ উদ্দেশ্যে প্রণোদিত।'),
  ('bn.bengali', 38, 7, 'আমরা সাবেক ধর্মে এ ধরনের কথা শুনিনি। এটা মনগড়া ব্যাপার বৈ নয়।'),
  ('bn.bengali', 38, 8, 'আমাদের মধ্য থেকে শুধু কি তারই প্রতি উপদেশ বানী অবতীর্ণ হল? বস্তুতঃ ওরা আমার উপদেশ সম্পর্কে সন্দিহান; বরং ওরা এখনও আমার মার আস্বাদন করেনি।'),
  ('bn.bengali', 38, 9, 'না কি তাদের কাছে আপনার পরাক্রান্ত দয়াবান পালনকর্তার রহমতের কোন ভান্ডার রয়েছে?'),
  ('bn.bengali', 38, 10, 'নাকি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের মধ্যবর্তী সবকিছুর উপর তাদের সাম্রাজ্য রয়েছে? থাকলে তাদের আকাশে আরোহণ করা উচিত রশি ঝুলিয়ে।'),
  ('bn.bengali', 38, 11, 'এক্ষেত্রে বহু বাহিনীর মধ্যে ওদেরও এক বাহিনী আছে, যা পরাজিত হবে।'),
  ('bn.bengali', 38, 12, 'তাদের পূর্বেও মিথ্যারোপ করেছিল নূহের সম্প্রদায়, আদ, কীলক বিশিষ্ট ফেরাউন,'),
  ('bn.bengali', 38, 13, 'সামুদ, লূতের সম্প্রদায় ও আইকার লোকেরা। এরাই ছিল বহু বাহিনী।'),
  ('bn.bengali', 38, 14, 'এদের প্রত্যেকেই পয়গম্বরগণের প্রতি মিথ্যারোপ করেছে। ফলে আমার আযাব প্রতিষ্ঠিত হয়েছে।'),
  ('bn.bengali', 38, 15, 'কেবল একটি মহানাদের অপেক্ষা করছে, যাতে দম ফেলার অবকাশ থাকবে না।'),
  ('bn.bengali', 38, 16, 'তারা বলে, হে আমাদের পরওয়ারদেগার, আমাদের প্রাপ্য অংশ হিসাব দিবসের আগেই দিয়ে দাও।'),
  ('bn.bengali', 38, 17, 'তারা যা বলে তাতে আপনি সবর করুন এবং আমার শক্তিশালী বান্দা দাউদকে স্মরণ করুন। সে ছিল আমার প্রতি প্রত্যাবর্তনশীল।'),
  ('bn.bengali', 38, 18, 'আমি পর্বতমালাকে তার অনুগামী করে দিয়েছিলাম, তারা সকাল-সন্ধ্যায় তার সাথে পবিত্রতা ঘোষণা করত;'),
  ('bn.bengali', 38, 19, 'আর পক্ষীকুলকেও, যারা তার কাছে সমবেত হত। সবাই ছিল তাঁর প্রতি প্রত্যাবর্তনশীল।'),
  ('bn.bengali', 38, 20, 'আমি তাঁর সাম্রাজ্যকে সুদৃঢ় করেছিলাম এবং তাঁকে দিয়েছিলাম প্রজ্ঞা ও ফয়সালাকারী বাগ্নীতা।'),
  ('bn.bengali', 38, 21, 'আপনার কাছে দাবীদারদের বৃত্তান্ত পৌছেছে, যখন তারা প্রাচীর ডিঙ্গীয়ে এবাদত খানায় প্রবেশ করেছিল।'),
  ('bn.bengali', 38, 22, 'যখন তারা দাউদের কাছে অনুপ্রবেশ করল, তখন সে সন্ত্রস্ত হয়ে পড়ল। তারা বললঃ ভয় করবেন না; আমরা বিবদমান দুটি পক্ষ, একে অপরের প্রতি বাড়াবাড়ি করেছি। অতএব, আমাদের মধ্যে ন্যায়বিচার করুন, অবিচার করবেন না। আমাদেরকে সরল পথ প্রদর্শন করুন।'),
  ('bn.bengali', 38, 23, 'সে আমার ভাই, সে নিরানব্বই দুম্বার মালিক আর আমি মালিক একটি মাদী দুম্বার। এরপরও সে বলেঃ এটিও আমাকে দিয়ে দাও। সে কথাবার্তায় আমার উপর বল প্রয়োগ করে।'),
  ('bn.bengali', 38, 24, 'দাউদ বললঃ সে তোমার দুম্বাটিকে নিজের দুম্বাগুলোর সাথে সংযুক্ত করার দাবী করে তোমার প্রতি অবিচার করেছে। শরীকদের অনেকেই একে অপরের প্রতি জুলুম করে থাকে। তবে তারা করে না, যারা আল্লাহর প্রতি বিশ্বাসী ও সৎকর্ম সম্পাদনকারী। অবশ্য এমন লোকের সংখ্যা অল্প। দাউদের খেয়াল হল যে, আমি তাকে পরীক্ষা করছি। অতঃপর সে তার পালনকর্তার কাছে ক্ষমা প্রার্থনা করল, সেজদায় লুটিয়ে পড়ল এবং তাঁর দিকে প্রত্যাবর্তন করল।'),
  ('bn.bengali', 38, 25, 'আমি তার সে অপরাধ ক্ষমা করলাম। নিশ্চয় আমার কাছে তার জন্যে রয়েছে উচ্চ মর্তবা ও সুন্দর আবাসস্থল।'),
  ('bn.bengali', 38, 26, 'হে দাউদ! আমি তোমাকে পৃথিবীতে প্রতিনিধি করেছি, অতএব, তুমি মানুষের মাঝে ন্যায়সঙ্গতভাবে রাজত্ব কর এবং খেয়াল-খুশীর অনুসরণ করো না। তা তোমাকে আল্লাহর পথ থেকে বিচ্যুত করে দেবে। নিশ্চয় যারা আল্লাহর পথ থেকে বিচ্যুত হয়, তাদের জন্যে রয়েছে কঠোর শাস্তি, এ কারণে যে, তারা হিসাবদিবসকে ভূলে যায়।'),
  ('bn.bengali', 38, 27, 'আমি আসমান-যমীন ও এতদুভয়ের মধ্যবর্তী কোন কিছু অযথা সৃষ্টি করিনি। এটা কাফেরদের ধারণা। অতএব, কাফেরদের জন্যে রয়েছে দূর্ভোগ অর্থাৎ জাহান্নাম।'),
  ('bn.bengali', 38, 28, 'আমি কি বিশ্বাসী ও সৎকর্মীদেরকে পৃথিবীতে বিপর্যয় সৃষ্টিকারী কাফেরদের সমতুল্য করে দেব? না খোদাভীরুদেরকে পাপাচারীদের সম্মান করে দেব।'),
  ('bn.bengali', 38, 29, 'এটি একটি বরকতময় কিতাব, যা আমি আপনার প্রতি বরকত হিসেবে অবতীর্ণ করেছি, যাতে মানুষ এর আয়াতসূহ লক্ষ্য করে এবং বুদ্ধিমানগণ যেন তা অনুধাবন করে।'),
  ('bn.bengali', 38, 30, 'আমি দাউদকে সোলায়মান দান করেছি। সে একজন উত্তম বান্দা। সে ছিল প্রত্যাবর্তনশীল।'),
  ('bn.bengali', 38, 31, 'যখন তার সামনে অপরাহ্নে উৎকৃষ্ট অশ্বরাজি পেশ করা হল,'),
  ('bn.bengali', 38, 32, 'তখন সে বললঃ আমি তো আমার পরওয়ারদেগারের স্মরণে বিস্মৃত হয়ে সম্পদের মহব্বতে মুগ্ধ হয়ে পড়েছি-এমনকি সূর্য ডুবে গেছে।'),
  ('bn.bengali', 38, 33, 'এগুলোকে আমার কাছে ফিরিয়ে আন। অতঃপর সে তাদের পা ও গলদেশ ছেদন করতে শুরু করল।'),
  ('bn.bengali', 38, 34, 'আমি সোলায়মানকে পরীক্ষা করলাম এবং রেখে দিলাম তার সিংহাসনের উপর একটি নিস্প্রাণ দেহ। অতঃপর সে রুজু হল।'),
  ('bn.bengali', 38, 35, 'সোলায়মান বললঃ হে আমার পালনকর্তা, আমাকে মাফ করুন এবং আমাকে এমন সাম্রাজ্য দান করুন যা আমার পরে আর কেউ পেতে পারবে না। নিশ্চয় আপনি মহাদাতা।'),
  ('bn.bengali', 38, 36, 'তখন আমি বাতাসকে তার অনুগত করে দিলাম, যা তার হুকুমে অবাধে প্রবাহিত হত যেখানে সে পৌছাতে চাইত।'),
  ('bn.bengali', 38, 37, 'আর সকল শয়তানকে তার অধীন করে দিলাম অর্থৎ, যারা ছিল প্রাসাদ নির্মাণকারী ও ডুবুরী।'),
  ('bn.bengali', 38, 38, 'এবং অন্য আরও অনেককে অধীন করে দিলাম, যারা আবদ্ধ থাকত শৃঙ্খলে।'),
  ('bn.bengali', 38, 39, 'এগুলো আমার অনুগ্রহ, অতএব, এগুলো কাউকে দাও অথবা নিজে রেখে দাও-এর কোন হিসেব দিতে হবে না।'),
  ('bn.bengali', 38, 40, 'নিশ্চয় তার জন্যে আমার কাছে রয়েছে মর্যাদা ও শুভ পরিণতি।'),
  ('bn.bengali', 38, 41, 'স্মরণ করুণ, আমার বান্দা আইয়্যুবের কথা, যখন সে তার পালনকর্তাকে আহবান করে বললঃ শয়তান আমাকে যন্ত্রণা ও কষ্ট পৌছিয়েছে।'),
  ('bn.bengali', 38, 42, 'তুমি তোমার পা দিয়ে ভূমিতে আঘাত কর। ঝরণা নির্গত হল গোসল করার জন্যে শীতল ও পান করার জন্যে।'),
  ('bn.bengali', 38, 43, 'আমি তাকে দিলাম তার পরিজনবর্গ ও তাদের মত আরও অনেক আমার পক্ষ থেকে রহমতস্বরূপ এবং বুদ্ধিমানদের জন্যে উপদেশস্বরূপ।'),
  ('bn.bengali', 38, 44, 'তুমি তোমার হাতে এক মুঠো তৃণশলা নাও, তদ্বারা আঘাত কর এবং শপথ ভঙ্গ করো না। আমি তাকে পেলাম সবরকারী। চমৎকার বান্দা সে। নিশ্চয় সে ছিল প্রত্যাবর্তনশীল।'),
  ('bn.bengali', 38, 45, 'স্মরণ করুন, হাত ও চোখের অধিকারী আমার বান্দা ইব্রাহীম, ইসহাক ও ইয়াকুবের কথা।'),
  ('bn.bengali', 38, 46, 'আমি তাদের এক বিশেষ গুণ তথা পরকালের স্মরণ দ্বারা স্বাতন্ত্র্য দান করেছিলাম।'),
  ('bn.bengali', 38, 47, 'আর তারা আমার কাছে মনোনীত ও সৎলোকদের অন্তর্ভুক্ত।'),
  ('bn.bengali', 38, 48, 'স্মরণ করুণ, ইসমাঈল, আল ইয়াসা ও যুলকিফলের কথা। তারা প্রত্যেকেই গুনীজন।'),
  ('bn.bengali', 38, 49, 'এ এক মহৎ আলোচনা। খোদাভীরুদের জন্যে রয়েছে উত্তম ঠিকানা-'),
  ('bn.bengali', 38, 50, 'তথা স্থায়ী বসবাসের জান্নাত; তাদের জন্যে তার দ্বার উম্মুক্ত রয়েছে।'),
  ('bn.bengali', 38, 51, 'সেখানে তারা হেলান দিয়ে বসবে। তারা সেখানে চাইবে অনেক ফল-মূল ও পানীয়।'),
  ('bn.bengali', 38, 52, 'তাদের কাছে থাকবে আনতনয়না সমবয়স্কা রমণীগণ।'),
  ('bn.bengali', 38, 53, 'তোমাদেরকে এরই প্রতিশ্রুতি দেয়া হচ্ছে বিচার দিবসের জন্যে।'),
  ('bn.bengali', 38, 54, 'এটা আমার দেয়া রিযিক যা শেষ হবে না।'),
  ('bn.bengali', 38, 55, 'এটাতো শুনলে, এখন দুষ্টদের জন্যে রয়েছে নিকৃষ্ট ঠিকানা'),
  ('bn.bengali', 38, 56, 'তথা জাহান্নাম। তারা সেখানে প্রবেশ করবে। অতএব, কত নিকৃষ্ট সেই আবাস স্থল।'),
  ('bn.bengali', 38, 57, 'এটা উত্তপ্ত পানি ও পঁূজ; অতএব তারা একে আস্বাদন করুক।'),
  ('bn.bengali', 38, 58, 'এ ধরনের আরও কিছু শাস্তি আছে।'),
  ('bn.bengali', 38, 59, 'এই তো একদল তোমাদের সাথে প্রবেশ করছে। তাদের জন্যে অভিনন্দন নেই তারা তো জাহান্নামে প্রবেশ করবে।'),
  ('bn.bengali', 38, 60, 'তারা বলবে, তোমাদের জন্যে ও তো অভিনন্দন নেই। তোমরাই আমাদেরকে এ বিপদের সম্মুখীন করেছ। অতএব, এটি কতই না ঘৃণ্য আবাসস্থল।'),
  ('bn.bengali', 38, 61, 'তারা বলবে, হে আমাদের পালনকর্তা, যে আমাদেরকে এর সম্মুখীন করেছে, আপনি জাহান্নামে তার শাস্তি দ্বিগুণ করে দিন।'),
  ('bn.bengali', 38, 62, 'তারা আরও বলবে, আমাদের কি হল যে, আমরা যাদেরকে মন্দ লোক বলে গণ্য করতাম, তাদেরকে এখানে দেখছি না।'),
  ('bn.bengali', 38, 63, 'আমরা কি অহেতুক তাদেরকে ঠাট্টার পাত্র করে নিয়েছিলাম, না আমাদের দৃষ্টি ভুল করছে?'),
  ('bn.bengali', 38, 64, 'এটা অর্থাৎ জাহান্নামীদের পারস্পরিক বাক-বিতন্ডা অবশ্যম্ভাবী।'),
  ('bn.bengali', 38, 65, 'বলুন, আমি তো একজন সতর্ককারী মাত্র এবং এক পরাক্রমশালী আল্লাহ ব্যতীত কোন উপাস্য নেই।'),
  ('bn.bengali', 38, 66, 'তিনি আসমান-যমীন ও এতদুভয়ের মধ্যবর্তী সব কিছুর পালনকর্তা, পরাক্রমশালী, মার্জনাকারী।'),
  ('bn.bengali', 38, 67, 'বলুন, এটি এক মহাসংবাদ,'),
  ('bn.bengali', 38, 68, 'যা থেকে তোমরা মুখ ফিরিয়ে নিয়েছ।'),
  ('bn.bengali', 38, 69, 'ঊর্ধ্ব জগৎ সম্পর্কে আমার কোন জ্ঞান ছিল না যখন ফেরেশতারা কথাবার্তা বলছিল।'),
  ('bn.bengali', 38, 70, 'আমার কাছে এ ওহীই আসে যে, আমি একজন স্পষ্ট সতর্ককারী।'),
  ('bn.bengali', 38, 71, 'যখন আপনার পালনকর্তা ফেরেশতাগণকে বললেন, আমি মাটির মানুষ সৃষ্টি করব।'),
  ('bn.bengali', 38, 72, 'যখন আমি তাকে সুষম করব এবং তাতে আমার রূহ ফুঁকে দেব, তখন তোমরা তার সম্মুখে সেজদায় নত হয়ে যেয়ো।'),
  ('bn.bengali', 38, 73, 'অতঃপর সমস্ত ফেরেশতাই একযোগে সেজদায় নত হল,'),
  ('bn.bengali', 38, 74, 'কিন্তু ইবলীস; সে অহংকার করল এবং অস্বীকারকারীদের অন্তর্ভুক্ত হয়ে গেল।'),
  ('bn.bengali', 38, 75, 'আল্লাহ বললেন, হে ইবলীস, আমি স্বহস্তে যাকে সৃষ্টি করেছি, তার সম্মুখে সেজদা করতে তোমাকে কিসে বাধা দিল? তুমি অহংকার করলে, না তুমি তার চেয়ে উচ্চ মর্যাদা সম্পন্ন?'),
  ('bn.bengali', 38, 76, 'সে বললঃ আমি তার চেয়ে উত্তম আপনি আমাকে আগুনের দ্বারা সৃষ্টি করেছেন, আর তাকে সৃষ্টি করেছেন মাটির দ্বারা।'),
  ('bn.bengali', 38, 77, 'আল্লাহ বললেনঃ বের হয়ে যা, এখান থেকে। কারণ, তুই অভিশপ্ত।'),
  ('bn.bengali', 38, 78, 'তোর প্রতি আমার এ অভিশাপ বিচার দিবস পর্যন্ত স্থায়ী হবে।'),
  ('bn.bengali', 38, 79, 'সে বললঃ হে আমার পালনকর্তা, আপনি আমাকে পুনরুত্থান দিবস পর্যন্ত অবকাশ দিন।'),
  ('bn.bengali', 38, 80, 'আল্লঅহ বললেনঃ তোকে অবকাশ দেয়া হল।'),
  ('bn.bengali', 38, 81, 'সে সময়ের দিন পর্যন্ত যা জানা।'),
  ('bn.bengali', 38, 82, 'সে বলল, আপনার ইযযতের কসম, আমি অবশ্যই তাদের সবাইকে বিপথগামী করে দেব।'),
  ('bn.bengali', 38, 83, 'তবে তাদের মধ্যে যারা আপনার খাঁটি বান্দা, তাদেরকে ছাড়া।'),
  ('bn.bengali', 38, 84, 'আল্লাহ বললেনঃ তাই ঠিক, আর আমি সত্য বলছি-'),
  ('bn.bengali', 38, 85, 'তোর দ্বারা আর তাদের মধ্যে যারা তোর অনুসরণ করবে তাদের দ্বারা আমি জাহান্নাম পূর্ণ করব।'),
  ('bn.bengali', 38, 86, 'বলুন, আমি তোমাদের কাছে কোন প্রতিদান চাই না আর আমি লৌকিকতাকারীও নই।'),
  ('bn.bengali', 38, 87, 'এটা তো বিশ্ববাসীর জন্যে এক উপদেশ মাত্র।'),
  ('bn.bengali', 38, 88, 'তোমরা কিছু কাল পরে এর সংবাদ অবশ্যই জানতে পারবে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 38, 1, 'Sad. By the renowned Qur\'an,'),
  ('en.pickthall', 38, 2, 'Nay, but those who disbelieve are in false pride and schism.'),
  ('en.pickthall', 38, 3, 'How many a generation We destroyed before them, and they cried out when it was no longer the time for escape!'),
  ('en.pickthall', 38, 4, 'And they marvel that a warner from among themselves hath come unto them, and the disbelievers say: This is a wizard, a charlatan.'),
  ('en.pickthall', 38, 5, 'Maketh he the gods One Allah? Lo! that is an astounding thing.'),
  ('en.pickthall', 38, 6, 'The chiefs among them go about, exhorting: Go and be staunch to your gods! Lo! this is a thing designed.'),
  ('en.pickthall', 38, 7, 'We have not heard of this in later religion. This is naught but an invention.'),
  ('en.pickthall', 38, 8, 'Hath the reminder been unto him (alone) among us? Nay, but they are in doubt concerning My reminder; nay but they have not yet tasted My doom.'),
  ('en.pickthall', 38, 9, 'Or are theirs the treasures of the mercy of thy Lord, the Mighty, the Bestower?'),
  ('en.pickthall', 38, 10, 'Or is the kingdom of the heavens and the earth and all that is between them theirs? Then let them ascend by ropes!'),
  ('en.pickthall', 38, 11, 'A defeated host are (all) the factions that are there.'),
  ('en.pickthall', 38, 12, 'The folk of Noah before them denied (their messenger) and (so did the tribe of) A\'ad, and Pharaoh firmly planted,'),
  ('en.pickthall', 38, 13, 'And (the tribe of) Thamud, and the folk of Lot, and the dwellers in the wood: these were the factions.'),
  ('en.pickthall', 38, 14, 'Not one of them but did deny the messengers, therefor My doom was justified,'),
  ('en.pickthall', 38, 15, 'These wait for but one Shout, there will be no second thereto.'),
  ('en.pickthall', 38, 16, 'They say: Our Lord! Hasten on for us our fate before the Day of Reckoning.'),
  ('en.pickthall', 38, 17, 'Bear with what they say, and remember Our bondman David, lord of might, Lo! he was ever turning in repentance (toward Allah).'),
  ('en.pickthall', 38, 18, 'Lo! We subdued the hills to hymn the praises (of their Lord) with him at nightfall and sunrise,'),
  ('en.pickthall', 38, 19, 'And the birds assembled; all were turning unto Him.'),
  ('en.pickthall', 38, 20, 'We made his kingdom strong and gave him wisdom and decisive speech.'),
  ('en.pickthall', 38, 21, 'And hath the story of the litigants come unto thee? How they climbed the wall into the royal chamber;'),
  ('en.pickthall', 38, 22, 'How they burst in upon David, and he was afraid of them. They said: Be not afraid! (We are) two litigants, one of whom hath wronged the other, therefor judge aright between us; be not unjust; and show us the fair way.'),
  ('en.pickthall', 38, 23, 'Lo! this my brother hath ninety and nine ewes while I had one ewe; and he said: Entrust it to me, and he conquered me in speech.'),
  ('en.pickthall', 38, 24, '(David) said: He hath wronged thee in demanding thine ewe in addition to his ewes, and lo! many partners oppress one another, save such as believe and do good works, and they are few. And David guessed that We had tried him, and he sought forgiveness of his Lord, and he bowed himself and fell down prostrate and repented.'),
  ('en.pickthall', 38, 25, 'So We forgave him that; and lo! he had access to Our presence and a happy journey\'s end.'),
  ('en.pickthall', 38, 26, '(And it was said unto him): O David! Lo! We have set thee as a viceroy in the earth; therefor judge aright between mankind, and follow not desire that it beguile thee from the way of Allah. Lo! those who wander from the way of Allah have an awful doom, forasmuch as they forgot the Day of Reckoning.'),
  ('en.pickthall', 38, 27, 'And We created not the heaven and the earth and all that is between them in vain. That is the opinion of those who disbelieve. And woe unto those who disbelieve, from the Fire!'),
  ('en.pickthall', 38, 28, 'Shall We treat those who believe and do good works as those who spread corruption in the earth; or shall We treat the pious as the wicked?'),
  ('en.pickthall', 38, 29, '(This is) a Scripture that We have revealed unto thee, full of blessing, that they may ponder its revelations, and that men of understanding may reflect.'),
  ('en.pickthall', 38, 30, 'And We bestowed on David, Solomon. How excellent a slave! Lo! he was ever turning in repentance (toward Allah).'),
  ('en.pickthall', 38, 31, 'When there were shown to him at eventide lightfooted coursers'),
  ('en.pickthall', 38, 32, 'And he said: Lo! I have preferred the good things (of the world) to the remembrance of my Lord; till they were taken out of sight behind the curtain.'),
  ('en.pickthall', 38, 33, '(Then he said): Bring them back to me, and fell to slashing (with his sword their) legs and necks.'),
  ('en.pickthall', 38, 34, 'And verily We tried Solomon, and set upon his throne a (mere) body. Then did he repent.'),
  ('en.pickthall', 38, 35, 'He said: My Lord! Forgive me and bestow on me sovereignty such as shall not belong to any after me. Lo! Thou art the Bestower.'),
  ('en.pickthall', 38, 36, 'So We made the wind subservient unto him, setting fair by his command whithersoever he intended.'),
  ('en.pickthall', 38, 37, 'And the unruly, every builder and diver (made We subservient),'),
  ('en.pickthall', 38, 38, 'And others linked together in chains,'),
  ('en.pickthall', 38, 39, '(Saying): This is Our gift, so bestow thou, or withhold, without reckoning.'),
  ('en.pickthall', 38, 40, 'And lo! he hath favour with Us, and a happy journey\'s end.'),
  ('en.pickthall', 38, 41, 'And make mention (O Muhammad) of Our bondman Job, when he cried unto his Lord (saying): Lo! the devil doth afflict me with distress and torment.'),
  ('en.pickthall', 38, 42, '(And it was said unto him): Strike the ground with thy foot. This (spring) is a cool bath and a refreshing drink.'),
  ('en.pickthall', 38, 43, 'And We bestowed on him (again) his household and therewith the like thereof, a mercy from Us, and a memorial for men of understanding.'),
  ('en.pickthall', 38, 44, 'And (it was said unto him): Take in thine hand a branch and smite therewith, and break not thine oath. Lo! We found him steadfast, how excellent a slave! Lo! he was ever turning in repentance (to his Lord).'),
  ('en.pickthall', 38, 45, 'And make mention of Our bondmen, Abraham, Isaac and Jacob, men of parts and vision.'),
  ('en.pickthall', 38, 46, 'Lo! We purified them with a pure thought, remembrance of the Home (of the Hereafter).'),
  ('en.pickthall', 38, 47, 'Lo! in Our sight they are verily of the elect, the excellent.'),
  ('en.pickthall', 38, 48, 'And make mention of Ishmael and Elisha and Dhu\'l-Kifl. All are of the chosen.'),
  ('en.pickthall', 38, 49, 'This is a reminder. And lo! for those who ward off (evil) is a happy journey\'s end,'),
  ('en.pickthall', 38, 50, 'Gardens of Eden, whereof the gates are opened for them,'),
  ('en.pickthall', 38, 51, 'Wherein, reclining, they call for plenteous fruit and cool drink (that is) therein.'),
  ('en.pickthall', 38, 52, 'And with them are those of modest gaze, companions.'),
  ('en.pickthall', 38, 53, 'This it is that ye are promised for the Day of Reckoning.'),
  ('en.pickthall', 38, 54, 'Lo! this in truth is Our provision, which will never waste away.'),
  ('en.pickthall', 38, 55, 'This (is for the righteous). And lo! for the transgressors there with be an evil journey\'s end,'),
  ('en.pickthall', 38, 56, 'Hell, where they will burn, an evil resting-place.'),
  ('en.pickthall', 38, 57, 'Here is a boiling and an ice-cold draught, so let them taste it,'),
  ('en.pickthall', 38, 58, 'And other (torment) of the kind in pairs (the two extremes)!'),
  ('en.pickthall', 38, 59, 'Here is an army rushing blindly with you. (Those who are already in the Fire say): No word of welcome for them. Lo! they will roast at the Fire.'),
  ('en.pickthall', 38, 60, 'They say: Nay, but you (misleaders), for you there is no word of welcome. Ye prepared this for us (by your misleading). Now hapless is the plight.'),
  ('en.pickthall', 38, 61, 'They say: Our Lord! Whoever did prepare this for us, oh, give him double portion of the Fire!'),
  ('en.pickthall', 38, 62, 'And they say: What aileth us that we behold not men whom we were wont to count among the wicked?'),
  ('en.pickthall', 38, 63, 'Did we take them (wrongly) for a laughing-stock, or have our eyes missed them?'),
  ('en.pickthall', 38, 64, 'Lo! that is very truth: the wrangling of the dwellers in the Fire.'),
  ('en.pickthall', 38, 65, 'Say (unto them, O Muhammad): I am only a warner, and there is no Allah save Allah, the One, the Absolute,'),
  ('en.pickthall', 38, 66, 'Lord of the heavens and the earth and all that is between them, the Mighty, the Pardoning.'),
  ('en.pickthall', 38, 67, 'Say: It is tremendous tidings'),
  ('en.pickthall', 38, 68, 'Whence ye turn away!'),
  ('en.pickthall', 38, 69, 'I had no knowledge of the Highest Chiefs when they disputed;'),
  ('en.pickthall', 38, 70, 'It is revealed unto me only that I may be a plain warner.'),
  ('en.pickthall', 38, 71, 'When thy Lord said unto the angels: Lo! I am about to create a mortal out of mire,'),
  ('en.pickthall', 38, 72, 'And when I have fashioned him and breathed into him of My Spirit, then fall down before him prostrate,'),
  ('en.pickthall', 38, 73, 'The angels fell down prostrate, every one,'),
  ('en.pickthall', 38, 74, 'Saving Iblis; he was scornful and became one of the disbelievers.'),
  ('en.pickthall', 38, 75, 'He said: O Iblis! What hindereth thee from falling prostrate before that which I have created with both My hands? Art thou too proud or art thou of the high exalted?'),
  ('en.pickthall', 38, 76, 'He said: I am better than him. Thou createdst me of fire, whilst him Thou didst create of clay.'),
  ('en.pickthall', 38, 77, 'He said: Go forth from hence, for lo! thou art outcast,'),
  ('en.pickthall', 38, 78, 'And lo! My curse is on thee till the Day of Judgment.'),
  ('en.pickthall', 38, 79, 'He said: My Lord! Reprieve me till the day when they are raised.'),
  ('en.pickthall', 38, 80, 'He said: Lo! thou art of those reprieved'),
  ('en.pickthall', 38, 81, 'Until the day of the time appointed.'),
  ('en.pickthall', 38, 82, 'He said: Then, by Thy might, I surely will beguile them every one,'),
  ('en.pickthall', 38, 83, 'Save Thy single-minded slaves among them.'),
  ('en.pickthall', 38, 84, 'He said: The Truth is, and the Truth I speak,'),
  ('en.pickthall', 38, 85, 'That I shall fill hell with thee and with such of them as follow thee, together.'),
  ('en.pickthall', 38, 86, 'Say (O Muhammad, unto mankind): I ask of you no fee for this, and I am no simulating.'),
  ('en.pickthall', 38, 87, 'Lo! it is naught else than a reminder for all peoples'),
  ('en.pickthall', 38, 88, 'And ye will come in time to know the truth thereof.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 38, 1, 'Sad: By the Qur\'an, Full of Admonition: (This is the Truth).'),
  ('en.yusufali', 38, 2, 'But the Unbelievers (are steeped) in self-glory and Separatism.'),
  ('en.yusufali', 38, 3, 'How many generations before them did We destroy? In the end they cried (for mercy)- when there was no longer time for being saved!'),
  ('en.yusufali', 38, 4, 'So they wonder that a Warner has come to them from among themselves! and the Unbelievers say, "This is a sorcerer telling lies!'),
  ('en.yusufali', 38, 5, '"Has he made the gods (all) into one Allah? Truly this is a wonderful thing!"'),
  ('en.yusufali', 38, 6, 'And the leader among them go away (impatiently), (saying), "Walk ye away, and remain constant to your gods! For this is truly a thing designed (against you)!'),
  ('en.yusufali', 38, 7, '"We never heard (the like) of this among the people of these latter days: this is nothing but a made-up tale!"'),
  ('en.yusufali', 38, 8, '"What! has the Message been sent to him - (Of all persons) among us?"... but they are in doubt concerning My (Own) Message! Nay, they have not yet tasted My Punishment!'),
  ('en.yusufali', 38, 9, 'Or have they the treasures of the mercy of thy Lord,- the Exalted in Power, the Grantor of Bounties without measure?'),
  ('en.yusufali', 38, 10, 'Or have they the dominion of the heavens and the earth and all between? If so, let them mount up with the ropes and means (to reach that end)!'),
  ('en.yusufali', 38, 11, 'But there - will be put to flight even a host of confederates.'),
  ('en.yusufali', 38, 12, 'Before them (were many who) rejected messengers,- the people of Noah, and \'Ad, and Pharaoh, the Lord of Stakes,'),
  ('en.yusufali', 38, 13, 'And Thamud, and the people of Lut, and the Companions of the Wood; - such were the Confederates.'),
  ('en.yusufali', 38, 14, 'Not one (of them) but rejected the messengers, but My punishment came justly and inevitably (on them).'),
  ('en.yusufali', 38, 15, 'These (today) only wait for a single mighty Blast, which (when it comes) will brook no delay.'),
  ('en.yusufali', 38, 16, 'They say: "Our Lord! hasten to us our sentence (even) before the Day of Account!"'),
  ('en.yusufali', 38, 17, 'Have patience at what they say, and remember our servant David, the man of strength: for he ever turned (to Allah).'),
  ('en.yusufali', 38, 18, 'It was We that made the hills declare, in unison with him, Our Praises, at eventide and at break of day,'),
  ('en.yusufali', 38, 19, 'And the birds gathered (in assemblies): all with him did turn (to Allah).'),
  ('en.yusufali', 38, 20, 'We strengthened his kingdom, and gave him wisdom and sound judgment in speech and decision.'),
  ('en.yusufali', 38, 21, 'Has the Story of the Disputants reached thee? Behold, they climbed over the wall of the private chamber;'),
  ('en.yusufali', 38, 22, 'When they entered the presence of David, and he was terrified of them, they said: "Fear not: we are two disputants, one of whom has wronged the other: Decide now between us with truth, and treat us not with injustice, but guide us to the even Path..'),
  ('en.yusufali', 38, 23, '"This man is my brother: He has nine and ninety ewes, and I have (but) one: Yet he says, \'commit her to my care,\' and is (moreover) harsh to me in speech."'),
  ('en.yusufali', 38, 24, '(David) said: "He has undoubtedly wronged thee in demanding thy (single) ewe to be added to his (flock of) ewes: truly many are the partners (in business) who wrong each other: Not so do those who believe and work deeds of righteousness, and how few are they?"... and David gathered that We had tried him: he asked forgiveness of his Lord, fell down, bowing (in prostration), and turned (to Allah in repentance).'),
  ('en.yusufali', 38, 25, 'So We forgave him this (lapse): he enjoyed, indeed, a Near Approach to Us, and a beautiful place of (Final) Return.'),
  ('en.yusufali', 38, 26, 'O David! We did indeed make thee a vicegerent on earth: so judge thou between men in truth (and justice): Nor follow thou the lusts (of thy heart), for they will mislead thee from the Path of Allah: for those who wander astray from the Path of Allah, is a Penalty Grievous, for that they forget the Day of Account.'),
  ('en.yusufali', 38, 27, 'Not without purpose did We create heaven and earth and all between! that were the thought of Unbelievers! but woe to the Unbelievers because of the Fire (of Hell)!'),
  ('en.yusufali', 38, 28, 'Shall We treat those who believe and work deeds of righteousness, the same as those who do mischief on earth? Shall We treat those who guard against evil, the same as those who turn aside from the right?'),
  ('en.yusufali', 38, 29, '(Here is) a Book which We have sent down unto thee, full of blessings, that they may mediate on its Signs, and that men of understanding may receive admonition.'),
  ('en.yusufali', 38, 30, 'To David We gave Solomon (for a son),- How excellent in Our service! Ever did he turn (to Us)!'),
  ('en.yusufali', 38, 31, 'Behold, there were brought before him, at eventide coursers of the highest breeding, and swift of foot;'),
  ('en.yusufali', 38, 32, 'And he said, "Truly do I love the love of good, with a view to the glory of my Lord,"- until (the sun) was hidden in the veil (of night):'),
  ('en.yusufali', 38, 33, '"Bring them back to me." then began he to pass his hand over (their) legs and their necks.'),
  ('en.yusufali', 38, 34, 'And We did try Solomon: We placed on his throne a body (without life); but he did turn (to Us in true devotion):'),
  ('en.yusufali', 38, 35, 'He said, "O my Lord! Forgive me, and grant me a kingdom which, (it may be), suits not another after me: for Thou art the Grantor of Bounties (without measure).'),
  ('en.yusufali', 38, 36, 'Then We subjected the wind to his power, to flow gently to his order, Whithersoever he willed,-'),
  ('en.yusufali', 38, 37, 'As also the evil ones, (including) every kind of builder and diver,-'),
  ('en.yusufali', 38, 38, 'As also others bound together in fetters.'),
  ('en.yusufali', 38, 39, '"Such are Our Bounties: whether thou bestow them (on others) or withhold them, no account will be asked."'),
  ('en.yusufali', 38, 40, 'And he enjoyed, indeed, a Near Approach to Us, and a beautiful Place of (Final) Return.'),
  ('en.yusufali', 38, 41, 'Commemorate Our Servant Job. Behold he cried to his Lord: "The Evil One has afflicted me with distress and suffering!"'),
  ('en.yusufali', 38, 42, '(The command was given:) "Strike with thy foot: here is (water) wherein to wash, cool and refreshing, and (water) to drink."'),
  ('en.yusufali', 38, 43, 'And We gave him (back) his people, and doubled their number,- as a Grace from Ourselves, and a thing for commemoration, for all who have Understanding.'),
  ('en.yusufali', 38, 44, '"And take in thy hand a little grass, and strike therewith: and break not (thy oath)." Truly We found him full of patience and constancy. How excellent in Our service! ever did he turn (to Us)!'),
  ('en.yusufali', 38, 45, 'And commemorate Our Servants Abraham, Isaac, and Jacob, possessors of Power and Vision.'),
  ('en.yusufali', 38, 46, 'Verily We did choose them for a special (purpose)- proclaiming the Message of the Hereafter.'),
  ('en.yusufali', 38, 47, 'They were, in Our sight, truly, of the company of the Elect and the Good.'),
  ('en.yusufali', 38, 48, 'And commemorate Isma\'il, Elisha, and Zul-Kifl: Each of them was of the Company of the Good.'),
  ('en.yusufali', 38, 49, 'This is a Message (of admonition): and verily, for the righteous, is a beautiful Place of (Final) Return,-'),
  ('en.yusufali', 38, 50, 'Gardens of Eternity, whose doors will (ever) be open to them;'),
  ('en.yusufali', 38, 51, 'Therein will they recline (at ease): Therein can they call (at pleasure) for fruit in abundance, and (delicious) drink;'),
  ('en.yusufali', 38, 52, 'And beside them will be chaste women restraining their glances, (companions) of equal age.'),
  ('en.yusufali', 38, 53, 'Such is the Promise made, to you for the Day of Account!'),
  ('en.yusufali', 38, 54, 'Truly such will be Our Bounty (to you); it will never fail;-'),
  ('en.yusufali', 38, 55, 'Yea, such! but - for the wrong-doers will be an evil place of (Final) Return!-'),
  ('en.yusufali', 38, 56, 'Hell!- they will burn therein, - an evil bed (indeed, to lie on)!-'),
  ('en.yusufali', 38, 57, 'Yea, such! - then shall they taste it,- a boiling fluid, and a fluid dark, murky, intensely cold!-'),
  ('en.yusufali', 38, 58, 'And other Penalties of a similar kind, to match them!'),
  ('en.yusufali', 38, 59, 'Here is a troop rushing headlong with you! No welcome for them! truly, they shall burn in the Fire!'),
  ('en.yusufali', 38, 60, '(The followers shall cry to the misleaders:) "Nay, ye (too)! No welcome for you! It is ye who have brought this upon us! Now evil is (this) place to stay in!"'),
  ('en.yusufali', 38, 61, 'They will say: "Our Lord! whoever brought this upon us,- Add to him a double Penalty in the Fire!"'),
  ('en.yusufali', 38, 62, 'And they will say: "What has happened to us that we see not men whom we used to number among the bad ones?'),
  ('en.yusufali', 38, 63, '"Did we treat them (as such) in ridicule, or have (our) eyes failed to perceive them?"'),
  ('en.yusufali', 38, 64, 'Truly that is just and fitting,- the mutual recriminations of the People of the Fire!'),
  ('en.yusufali', 38, 65, 'Say: "Truly am I a Warner: no god is there but the one Allah, Supreme and Irresistible,-'),
  ('en.yusufali', 38, 66, '"The Lord of the heavens and the earth, and all between,- Exalted in Might, able to enforce His Will, forgiving again and again."'),
  ('en.yusufali', 38, 67, 'Say: "That is a Message Supreme (above all),-'),
  ('en.yusufali', 38, 68, '"From which ye do turn away!'),
  ('en.yusufali', 38, 69, '"No knowledge have I of the Chiefs on high, when they discuss (matters) among themselves.'),
  ('en.yusufali', 38, 70, '\'Only this has been revealed to me: that I am to give warning plainly and publicly."'),
  ('en.yusufali', 38, 71, 'Behold, thy Lord said to the angels: "I am about to create man from clay:'),
  ('en.yusufali', 38, 72, '"When I have fashioned him (in due proportion) and breathed into him of My spirit, fall ye down in obeisance unto him."'),
  ('en.yusufali', 38, 73, 'So the angels prostrated themselves, all of them together:'),
  ('en.yusufali', 38, 74, 'Not so Iblis: he was haughty, and became one of those who reject Faith.'),
  ('en.yusufali', 38, 75, '(Allah) said: "O Iblis! What prevents thee from prostrating thyself to one whom I have created with my hands? Art thou haughty? Or art thou one of the high (and mighty) ones?"'),
  ('en.yusufali', 38, 76, '(Iblis) said: "I am better than he: thou createdst me from fire, and him thou createdst from clay."'),
  ('en.yusufali', 38, 77, '(Allah) said: "Then get thee out from here: for thou art rejected, accursed.'),
  ('en.yusufali', 38, 78, '"And My curse shall be on thee till the Day of Judgment."'),
  ('en.yusufali', 38, 79, '(Iblis) said: "O my Lord! Give me then respite till the Day the (dead) are raised."'),
  ('en.yusufali', 38, 80, '(Allah) said: "Respite then is granted thee-'),
  ('en.yusufali', 38, 81, '"Till the Day of the Time Appointed."'),
  ('en.yusufali', 38, 82, '(Iblis) said: "Then, by Thy power, I will put them all in the wrong,-'),
  ('en.yusufali', 38, 83, '"Except Thy Servants amongst them, sincere and purified (by Thy Grace)."'),
  ('en.yusufali', 38, 84, '(Allah) said: "Then it is just and fitting- and I say what is just and fitting-'),
  ('en.yusufali', 38, 85, '"That I will certainly fill Hell with thee and those that follow thee,- every one."'),
  ('en.yusufali', 38, 86, 'Say: "No reward do I ask of you for this (Qur\'an), nor am I a pretender.'),
  ('en.yusufali', 38, 87, '"This is no less than a Message to (all) the Worlds.'),
  ('en.yusufali', 38, 88, '"And ye shall certainly know the truth of it (all) after a while."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 38, 1, 'Saaad; wal-Qur-aani ziz zikr'),
  ('en.transliteration', 38, 2, 'Balil lazeena kafaroo fee \'izzatilnw wa shiqaaq'),
  ('en.transliteration', 38, 3, 'Kam ahlaknaa min qablihim min qarnin fanaadaw wa laata heena manaas'),
  ('en.transliteration', 38, 4, 'Wa \'ajibooo an jaaa\'a hum munzirum minhum wa qaalal kaafiroona haazaa saahirun kazzaab'),
  ('en.transliteration', 38, 5, 'Aja\'alal aalihata Ilaahanw Waahidan inna haazaa lashai\'un \'ujaab'),
  ('en.transliteration', 38, 6, 'Wantalaqal mala-u minhum anim shoo wasbiroo \'alaaa aalihatikum innna haazaa lashai \'uny yuraad'),
  ('en.transliteration', 38, 7, 'Maa sami\'naa bihaazaa fil millatil aakhirati in haazaaa illakh tilaaq'),
  ('en.transliteration', 38, 8, '\'A-unzila \'alaihiz zikru mim baininaa; bal hum fee shakkim min Zikree bal lammaa yazooqoo \'azaab'),
  ('en.transliteration', 38, 9, 'Am\'indahum khazaaa \'inu rahmati Rabbikal \'Azeezil Wahhab'),
  ('en.transliteration', 38, 10, 'Am lahum mulkus samaawaati wal ardi wa maa bainahumaa falyartaqoo fil asbaab'),
  ('en.transliteration', 38, 11, 'Jundum maa hunaalika mahzoomum minal Ahzaab'),
  ('en.transliteration', 38, 12, 'Kazzabat qablahum qawmu Lootinw-wa \'Aadunw wa Fir\'awnu zul awtaad'),
  ('en.transliteration', 38, 13, 'Wa Samoodu wa qawmu Lootinw wa Ashaabul \'Aykah; ulaaa\'ikal Ahzaab'),
  ('en.transliteration', 38, 14, 'In kullun illaa kazzabar Rusula fahaqqa \'iqaab'),
  ('en.transliteration', 38, 15, 'Wa maa yanzuru haaa ulaaa\'i illaa saihatanw waahidatam maa lahaa min fawaaq'),
  ('en.transliteration', 38, 16, 'Wa qaaloo Rabbanaa \'ajjil lanaa qittanaa qabla Yawmil Hisaab'),
  ('en.transliteration', 38, 17, 'Isbir \'alaa maa yaqooloona wazkur \'abdanaa Daawooda zal aidi aidi innahooo awwaab'),
  ('en.transliteration', 38, 18, 'Innaa sakhkharnal jibaala ma\'ahoo yusabbihna bil\'ashaiyi wal ishraaq'),
  ('en.transliteration', 38, 19, 'Wattayra mahshoorah; kullul lahooo awwaab'),
  ('en.transliteration', 38, 20, 'Wa shadadnaa mulkahoo wa aatainaahul Hikmata wa faslal khitaab'),
  ('en.transliteration', 38, 21, 'Wa hal ataaka naba\'ul khasm; iz tasawwarul mihraab'),
  ('en.transliteration', 38, 22, 'Iz dakhaloo \'alaa Daawooda fafazi\'a minhum qaaloo la takhaf khasmaani baghaa ba\'dunaa \'alaa ba\'din fahkum bainanaaa bilhaqqi wa laa tushtit wahdinaaa ilaa Sawaaa\'is Siraat'),
  ('en.transliteration', 38, 23, 'Inna haazaaa akhee lahoo tis\'unw wa tis\'oona na\'jatanw wa liya na\'jatunw waahidah; faqaala akfilneeha wa \'azzanee filkhitaab'),
  ('en.transliteration', 38, 24, 'Qaala laqad zalamaka bisu \'aali na\'jatika ilaa ni\'aajihee wa inna kaseeram minal khulataaa\'i la-yabghee ba\'duhum \'alaa ba\'din illal lazeena aamanoo wa \'amilus saalihaati wa qaleehum maa hum; wa zanna Daawoodu annamaa fatannaahu fastaghrara Rabbahoo wa kharra raaki\'anw wa anaab'),
  ('en.transliteration', 38, 25, 'Faghafarnaa lahoo zaalik; wa inna lahoo \'indanaa lazulfaa wa husna ma aab'),
  ('en.transliteration', 38, 26, 'Yaa Daawoodu innaa ja\'alnaaka khaleefatan fil ardi fahkum bainan naasi bilhaqqi wa laa tattabi\'il hawaa fayudillaka \'an sabeelil laah; innal lazeena yadilloona \'an sabeelil laah; lahum \'azaabun shadeedum bimaa nasoo Yawmal Hisaab'),
  ('en.transliteration', 38, 27, 'Wa ma khalaqnas samaaa\'a wal arda wa maa bainahumaa baatilaa; zaalika zannul lazeena kafaroo; fawi lul lillazeena kafaroo minan Naar'),
  ('en.transliteration', 38, 28, 'Am naj\'alul lazeena aamanoo wa \'amilus saalihaati kalmufisdeena fil ardi am naj\'alul muttaqeena kalfujjaar'),
  ('en.transliteration', 38, 29, 'Kitaabun anzalnaahu ilaika mubaarakul liyaddabbarooo Aayaatihee wa liyatazakkara ulul albaab'),
  ('en.transliteration', 38, 30, 'Wa wahabnaa li Daawooda Sulaimaan; ni\'mal \'abd; innahoo awwaab'),
  ('en.transliteration', 38, 31, 'Iz \'urida \'alaihi bil\'ashiy yis saafinaatul jiyaad'),
  ('en.transliteration', 38, 32, 'Faqaala inneee ahbabtu hubbal khairi \'an zikri Rabbee hattaa tawaarat bilhijaab'),
  ('en.transliteration', 38, 33, 'Ruddoohaa \'alaiya fatafiqa masham bissooqi wal a\'naaq'),
  ('en.transliteration', 38, 34, 'Wa laqad fatannaa Sulaimaana wa alqainaa \'alaa kursiyyihee jasadan summa anaab'),
  ('en.transliteration', 38, 35, 'Qaala Rabbigh fir lee wa hab lee mulkal laa yambaghee li ahadim mim ba\'de inaka Antal Wahhab'),
  ('en.transliteration', 38, 36, 'Fasakhkharnaa lahur reeha tajree bi amrihee rukhaaa\'an haisu asaab'),
  ('en.transliteration', 38, 37, 'Wash Shayaateena kulla bannaaa\'inw wa ghawwaas'),
  ('en.transliteration', 38, 38, 'Wa aakhareena muqarraneena fil asfaad'),
  ('en.transliteration', 38, 39, 'Haazaa \'ataaa\'unaa famnun aw amsik bighairi hisaab'),
  ('en.transliteration', 38, 40, 'Wa inna lahoo \'indanaa lazulfaa wa husna ma-aab'),
  ('en.transliteration', 38, 41, 'Wazkur \'abdanaaa Ayyoob; iz naada Rabbahooo annee massaniyash Shaitaanu binus binw wa \'azaab'),
  ('en.transliteration', 38, 42, 'Urkud birijlika haaza mughtasalum baaridunw wa sharaab'),
  ('en.transliteration', 38, 43, 'Wa wahabnaa lahoo ahlahoo wa mislahum ma\'ahum rahmatam minna wa zikraa li ulil albaab'),
  ('en.transliteration', 38, 44, 'Wa khuz biyadika dighsan fadrib bihee wa laa tahnas, innaa wajadnaahu saabiraa; ni\'mal \'abd; innahooo awwaab'),
  ('en.transliteration', 38, 45, 'Wazkur \'ibaadanaaa Ibraaheema wa Is-haaqa wa Ya\'qooba ulil-aydee walabsaar'),
  ('en.transliteration', 38, 46, 'Innaaa akhlasnaahum bi khaalisatin zikrad daar'),
  ('en.transliteration', 38, 47, 'Wa innahum \'indanaa laminal mustafainal akhyaar'),
  ('en.transliteration', 38, 48, 'Wazkur Ismaa\'eela wal Yasa\'a wa Zal-Kifli wa kullum minal akhyaar'),
  ('en.transliteration', 38, 49, 'Haazaa zikr; wa inna lilmuttaqeena lahusna ma aab'),
  ('en.transliteration', 38, 50, 'Jannaati \'adnim mufat tahatal lahumul abwaab'),
  ('en.transliteration', 38, 51, 'Muttaki\'eena feehaa yad\'oona feehaa bifaakihatin kaseeratinw wa sharaab'),
  ('en.transliteration', 38, 52, 'Wa \'indahum qaasiraatut tarfi atraab'),
  ('en.transliteration', 38, 53, 'Haaza maa too\'odoona li Yawmil Hisaab'),
  ('en.transliteration', 38, 54, 'Inna haazaa larizqunaa maa lahoo min nafaad'),
  ('en.transliteration', 38, 55, 'Haazaa; wa inna littaagheena lasharra ma-aab'),
  ('en.transliteration', 38, 56, 'Jahannama yaslawnahaa fai\'sal mihaad'),
  ('en.transliteration', 38, 57, 'Haazaa falyazooqoohu hameemunw wa ghassaaq'),
  ('en.transliteration', 38, 58, 'Wa aakharu min shak liheee azwaaj'),
  ('en.transliteration', 38, 59, 'Haazaa fawjum muqtahimum ma\'akum laa marhabam bihim; innahum saalun Naar'),
  ('en.transliteration', 38, 60, 'Qaaloo bal antum laa marhabam bikum; antum qaddamtumoohu lanaa fabi\'sal qaraar'),
  ('en.transliteration', 38, 61, 'Qaaloo Rabbanaa man qaddama lanaa haaza fazidhu \'azaaban di\'fan fin Naar'),
  ('en.transliteration', 38, 62, 'Wa qaaloo ma lanaa laa naraa rijaalan kunnaa na\'udduhum minal ashraar'),
  ('en.transliteration', 38, 63, 'Attakhaznaahum sikh riyyan am zaaghat \'anhumul absaar'),
  ('en.transliteration', 38, 64, 'Inna zaalika lahaqqun takhaasumu Ahlin Naar'),
  ('en.transliteration', 38, 65, 'Qul innamaaa ana munzirunw wa maa min ilaahim illal laahul Waahidul Qahhaar'),
  ('en.transliteration', 38, 66, 'Rabbus samaawaati wal ardi wa maa bainahumal \'Azeezul Ghaffaar'),
  ('en.transliteration', 38, 67, 'Qul huwa naba\'un \'azeem'),
  ('en.transliteration', 38, 68, 'Antum \'anhu mu\'ridoon'),
  ('en.transliteration', 38, 69, 'Maa kaana liya min \'ilmim bilmala il a\'laaa iz yakhtasimoon'),
  ('en.transliteration', 38, 70, 'Iny-yoohaaa ilaiya illaaa annnamaaa ana nazeerum mubeen'),
  ('en.transliteration', 38, 71, 'Iz qaala Rabbuka lilmalaaa\'ikati innee khaaliqum basharam min teen'),
  ('en.transliteration', 38, 72, 'Fa-iza sawwaituhoo wa nafakhtu feehi mir roohee faqa\'oo lahoo saajideen'),
  ('en.transliteration', 38, 73, 'Fasajadal malaaa\'ikatu kulluhum ajma\'oon'),
  ('en.transliteration', 38, 74, 'Illaaa Iblees; istakbara wa kaana minal kaafireen'),
  ('en.transliteration', 38, 75, 'Qaala yaaa Ibleesu maa man\'aka an tasjuda limaa khalaqtu biyadai; astakbarta am kunta min \'aaleen'),
  ('en.transliteration', 38, 76, 'Qaala ana khairum minah; khalaqtanee min naarinw wa khalaqtahoo min teen'),
  ('en.transliteration', 38, 77, 'Qaala fakhruj minhaa fainnaka rajeem'),
  ('en.transliteration', 38, 78, 'Wa inna \'alaika la\'nateee ilaa Yawmid Deen'),
  ('en.transliteration', 38, 79, 'Qaala Rabbi fa anzirneee ilaa Yawmi yub\'asoon'),
  ('en.transliteration', 38, 80, 'Qaala fa innaka minal munzareen'),
  ('en.transliteration', 38, 81, 'Ilaa Yawmil waqtil ma\'loom'),
  ('en.transliteration', 38, 82, 'Qaala fabi\'izzatika la ughwiyannahum ajma\'een'),
  ('en.transliteration', 38, 83, 'Illaa \'ibaadaka minhumul mukhlaseen'),
  ('en.transliteration', 38, 84, 'Qaala falhaqq, walhaqqa aqool'),
  ('en.transliteration', 38, 85, 'La amla\'annna Jahannama minka wa mimman tabi\'aka minhum ajma\'een'),
  ('en.transliteration', 38, 86, 'Qul maaa as\'alukum \'alaihi min ajrinw wa maaa ana minal mutakallifeen'),
  ('en.transliteration', 38, 87, 'In huwa illaa zikrul lil\'aalameen'),
  ('en.transliteration', 38, 88, 'Wa lata\'lamunna naba ahoo ba\'da heen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 38, 1, 'قرآن کی قسم ہے جو سراسر نصیحت ہے'),
  ('ur.ahmedali', 38, 2, 'بلکہ جو لوگ منکر ہیں وہ محض تکبر اور مخالفت میں پڑے ہیں'),
  ('ur.ahmedali', 38, 3, 'ہم نے ان سے پہلے کتنی قومیں ہلاک کر دی ہیں سو انہوں نے بڑی ہائے پکار کی اور وہ وقت خلاصی کا نہ تھا'),
  ('ur.ahmedali', 38, 4, 'اور انہوں نے تعجب کیا کہ ان کے پاس انہیں میں سے ڈرانے والا آیا اور منکروں نے کہا کہ یہ تو ایک بڑا جھوٹا جادوگر ہے'),
  ('ur.ahmedali', 38, 5, 'کیا اس نے کئی معبودوں کو صرف ایک معبود بنایا ہے بے شک یہ بڑی عجیب بات ہے'),
  ('ur.ahmedali', 38, 6, 'اور ان میں سے سردار یہ کہتے ہوئے چل پڑے کہ چلو اور اپنے معبودوں پر جمے رہو بے شک اس میں کچھ غرض ہے'),
  ('ur.ahmedali', 38, 7, 'ہم نے یہ بات اپنے پچھلے دین میں نہیں سنی یہ تو ایک بنائی ہوئی بات ہے'),
  ('ur.ahmedali', 38, 8, 'کیا ہم میں سے اسی پر نصیحت اتاری گئی بلکہ انہیں تو میری نصیحت میں بھی شک ہے بلکہ انہوں نے میرا ابھی عذاب بھی نہیں چکھا'),
  ('ur.ahmedali', 38, 9, 'کیا ان کے پاس تیرے خدائے غالب فیاض کی رحمت کے خزانے ہیں'),
  ('ur.ahmedali', 38, 10, 'یا انہیں آسمانوں اور زمین کی حکومت اور جو کچھ ان کے درمیان ہے حاصل ہے تو سیڑھیاں لگا کر چڑھ جائیں'),
  ('ur.ahmedali', 38, 11, 'وہاں ان کے لشکر شکست پائیں گے'),
  ('ur.ahmedali', 38, 12, 'ان سے پہلے قوم نوح اور عاد اور میخوں والا فرعون'),
  ('ur.ahmedali', 38, 13, 'اور ثمود اور لوط کی قوم اور بن والے بھی جھٹلا چکے ہیں یہی وہ لشکر ہیں'),
  ('ur.ahmedali', 38, 14, 'ان سب نے رسولوں کو جھٹلایا تھا پس میرا عذاب آ موجود ہوا'),
  ('ur.ahmedali', 38, 15, 'اور یہ ایک ہی چیخ کے منتظر ہیں جسے کچھ دیر نہیں لگے گی'),
  ('ur.ahmedali', 38, 16, 'اور کہتے ہیں اے رب ہمارے! ہمارا حصہ ہمیں حساب کے دن سے پہلے ہی دے دے'),
  ('ur.ahmedali', 38, 17, 'ان کی اِن باتوں پر صبر کر اور ہمارے بندے داؤد کو یاد کر جو بڑا طاقتور تھا بے شک وہ رجوع کرنے والا تھا'),
  ('ur.ahmedali', 38, 18, 'بے شک ہم نے پہاڑوں کو اس کے تابع کر دیا تھا کہ وہ شام اور صبح کو تسبیح کرتے تھے'),
  ('ur.ahmedali', 38, 19, 'اور پرندوں کو بھی جو جمع ہوجاتے تھے ہر ایک اس کے تابع تھا'),
  ('ur.ahmedali', 38, 20, 'اورہم نے اس کی سلطنت کو مضبوھ کر دیا تھا اور ہم نے اسے نبوت دی تھی اور مقدمات کے فیصلے کرنے کا سلیقہ (دیا تھا)'),
  ('ur.ahmedali', 38, 21, 'اور کیا آپ کو دو جھگڑنے والوں کی خبر بھی پہنچی جب وہ عبادت خانہ کی دیوار پھاند کر آئے'),
  ('ur.ahmedali', 38, 22, 'جب وہ داؤد کے پاس آئے تو وہ ان سے گھبرایا کہا ڈر نہیں دو جھگڑنے والے ہیں ایک نے دوسرے پر زیادتی کی ہے پس آپ ہمارے درمیا ن انصاف کا فیصلہ کیجیئے اور بات کو دور نہ ڈالیئے اور ہمیں سیدھی راہ پر چلائیے'),
  ('ur.ahmedali', 38, 23, 'بے شک یہ میرا بھائی ہے اس کے پاس ننانوے دنبیاں ہیں اور میرے پاس صرف ایک دنبی ہے پس اس نے کہا مجھے وہ بھی دے دے اور اس نے مجھے گفتگو میں دبا لیا ہے'),
  ('ur.ahmedali', 38, 24, 'کہا البتہ اس نے تجھ پر ظلم کیا جو تیری دنبی کو اپنی دنبیوں میں ملانے کا سوال کیا گور اکثر شریک ایک دوسرے پر زیادتی کیا کرتے ہیں مگر جو ایماندار ہیں اور انہوں نے نیک کام بھی کیے اور وہ بہت ہی کم ہیں اور داؤد سمجھ گیا کہ ہم نے اسے آزمایا ہے پھر اس نے اپنے رب سے معافی مانگی اور سجدہ میں گر پڑا اور توبہ کی'),
  ('ur.ahmedali', 38, 25, 'پھر ہم نے اس کی یہ غلطی معاف کر دی اور اس کے لیے ہمارے ہاں مرتبہ اور اچھا ٹھکانہ ہے'),
  ('ur.ahmedali', 38, 26, 'اے داؤد! ہم نے تجھے زمین میں بادشاہ بنایا ہے پس تم لوگو ں میں انصاف سے فیصلہ کیا کرو اور نفس کی خواہش کی پیروی نہ کرو کہ وہ تمہیں الله کی راہ سے ہٹا دے گی بے شک جو الله کی راہ سے گمراہ ہوتے ہیں ان کے لیے سخت عذاب ہے اس لیے کہ وہ حساب کے دن کوبھول گئے'),
  ('ur.ahmedali', 38, 27, 'اور ہم نے آسمان اور زمین کو اور جو کچھ ان کے بیچ میں ہے بیکار تو پیدا نہیں کیا یہ تو ان کا خیال ہے جو کافر ہیں پھرکافروں کے لیے ہلاکت ہے جو آگ ہے'),
  ('ur.ahmedali', 38, 28, 'کیا ہم کردیں گے ان کو جو ایمان لائے اور نیک کام کیے ان کی طرح جو زمین میں فساد کرتے ہیں یا ہم پرہیز گاروں کو بدکاروں کی طرح کر دیں گے'),
  ('ur.ahmedali', 38, 29, 'ایک کتاب ہے جو ہم نے آپ کی طرف نازل کی بڑی برکت والی تاکہ وہ اس کی آیتوں میں غور کریں اور تاکہ عقلمند نصحیت حاصل کریں'),
  ('ur.ahmedali', 38, 30, 'اور ہم نے داؤد کو سلیمان عطا کیا کیسا اچھا بندہ تھا بےشک وہ رجوع کرنے والا تھا'),
  ('ur.ahmedali', 38, 31, 'جب اس کے سامنے شام کے وقت تیز رو گھوڑے حاضر کیے گئے'),
  ('ur.ahmedali', 38, 32, 'تو کہا میں نے مال کی محبت کو یاد الہیٰ سے عزیز سمجھا یہاں تک کہ آفتاب غروب ہو گیا'),
  ('ur.ahmedali', 38, 33, 'ان کو میرے پاس لوٹا لاؤ پس پنڈلیوں اور گردنوں پر (تلوار) پھیرنے لگا'),
  ('ur.ahmedali', 38, 34, 'اور ہم نے سلیمان کو آزمایا تھا اور اس کی کرسی پر ایک دھڑ ڈال دیا تھا پھر وہ رجوع ہوا'),
  ('ur.ahmedali', 38, 35, 'کہا اے میرے رب! مجھے معاف کر اور مجھے ایسی حکومت عنایت فرما کہ کسی کو میرے بعد شایاں نہ ہو بے شک تو بہت بڑا عنایت کرنے والا ہے'),
  ('ur.ahmedali', 38, 36, 'پھر ہم نے ہوا کو اس کے تابع کر دیا کہ وہ اس کے حکم سے بڑی نرمی سے چلتی تھی جہاں اسے پہنچنا ہوتا تھا'),
  ('ur.ahmedali', 38, 37, 'اور شیطان کو جو سب معمار اور غوطہ زن تھے'),
  ('ur.ahmedali', 38, 38, 'اور دوسروں کو جو زنجیروں میں جکڑے ہوئے تھے'),
  ('ur.ahmedali', 38, 39, 'یہ ہماری بخشش ہے پس احسان کر یا اپنے پاس رکھ کوئی حساب نہیں'),
  ('ur.ahmedali', 38, 40, 'اور البتہ (سلیمان) کے لیے ہمارے پاس مرتبہ اورعمدہ مقام ہے'),
  ('ur.ahmedali', 38, 41, 'اور ہمارے بندے ایوب کو یاد کر جب اس نے اپنے رب کو پکارا کہ مجھے شیطان نے تکلیف اور عذاب پہنچایا ہے'),
  ('ur.ahmedali', 38, 42, 'اپنا پاؤں (زمین پر مار) یہ ٹھنڈا چشمہ نہانے اور پینے کو ہے'),
  ('ur.ahmedali', 38, 43, 'اور ہم نے ان کو ان کے اہل و عیال اور کتنے ہی اور بھی اپنی مہربانی سے عنایت فرمائے اور عقلمندوں کے لیے نصیحت ہے'),
  ('ur.ahmedali', 38, 44, 'اور اپنے ہاتھ میں جھاڑو کا مٹھا لے کر مارے اور قسم نہ توڑ بے شک ہم نے ایوب کو صابر پایا وہ بڑے اچھے بندے الله کی طرف رجوع کرنے والے تھے'),
  ('ur.ahmedali', 38, 45, 'اور ہمارے بندوں ابراھیم اور اسحاق اور یعقوب کو یاد کر جو ہاتھو ں اور آنکھوں والے تھے'),
  ('ur.ahmedali', 38, 46, 'بے شک ہم نے انہیں ایک خاص فضیلت دی یعنی ذکر آخرت کے لیے چن لیا تھا'),
  ('ur.ahmedali', 38, 47, 'اور بے شک وہ ہمارے نزدیک برگزیدہ بندوں میں سے تھے'),
  ('ur.ahmedali', 38, 48, 'اور اسماعیل اور الیسع اور ذوالکفل کو بھی یاد کر اور یہ سب نیک لوگو ں میں سے تھے'),
  ('ur.ahmedali', 38, 49, 'یہ نصیحت ہے اور بے شک پرہیز گاروں کے لئے اچھا ٹھکانا ہے'),
  ('ur.ahmedali', 38, 50, 'ہمیشہ رہنے کے باغ ہیں ان کے لئے ان کے دروازے کھولے جائیں گے'),
  ('ur.ahmedali', 38, 51, 'وہاں تکیہ لگا کر بیٹھیں گے وہاں بہت سے میوے اور شراب طلب کریں گے'),
  ('ur.ahmedali', 38, 52, 'اور ان کے پاس نیچی نگاہ والی ہم عمر عورتیں ہوں گی'),
  ('ur.ahmedali', 38, 53, 'یہی ہے جس کا تم سے حساب کے دن کے لیے وعدہ کیا جاتا ہے'),
  ('ur.ahmedali', 38, 54, 'بے شک یہ ہمارا رزق ہے جو کبھی ختم نہیں ہوگا'),
  ('ur.ahmedali', 38, 55, 'یہی بات ہے اور بے شک سرکشوں کے لیے برا ٹھکانا ہے'),
  ('ur.ahmedali', 38, 56, 'یعنی دوزخ جس میں وہ گریں گے پس وہ کیسی بری جگہ ہے'),
  ('ur.ahmedali', 38, 57, 'یہ ہے پھر وہ اس کو چکھیں جو کھولتا ہوا پانی اور پیپ ہے'),
  ('ur.ahmedali', 38, 58, 'اور اس کی شکل اور بھی کئی طرح کی چیزیں ہوں گی'),
  ('ur.ahmedali', 38, 59, 'یہ ایک جماعت ہے جو تمہارے ساتھ دوزخ میں داخل ہونے والی ہے (متبوع کہیں گے) ان پر خدا کی مار یہ بھی دوزخ ہی میں آ رہے ہیں'),
  ('ur.ahmedali', 38, 60, '(تابع ہونے والے) کہیں گے بلکہ تم پر خدا کی مار تم ہی تو اس بلا کو ہمارے سامنے لائے جو بہت ہی برا ٹھکانا ہے'),
  ('ur.ahmedali', 38, 61, 'تابع کہیں گے اے ہمارے رب! جو اس بلا کو آگے لایا اسے آگ میں دگنا عذاب دے'),
  ('ur.ahmedali', 38, 62, 'اور کہیں گے کہ جن لوگوں کو ہم دنیا میں برا سمجھتے تھے ہمیں دکھائی کیوں نہیں دیتے'),
  ('ur.ahmedali', 38, 63, 'کیا ہم ان سے (ناحق) تمسخر کرتے تھے یا ان سے ہماری نگاہیں پھر گئی ہیں'),
  ('ur.ahmedali', 38, 64, 'بے شک یہ دوزخیوں کا آپس میں جھگڑنا بالکل سچی بات ہے'),
  ('ur.ahmedali', 38, 65, 'کہہ دو میں تو ایک ڈرانے والا ہوں اور الله کے سوا کوئی اور معبود نہیں ہے ایک ہے بڑا غالب'),
  ('ur.ahmedali', 38, 66, 'آسمانوں اور زمین کا پرودگار اورجو کچھ ان کے درمیان ہے غالب بڑا معاف کرنے والا ہے'),
  ('ur.ahmedali', 38, 67, 'کہہ دو یہ ایک بڑی خبر ہے'),
  ('ur.ahmedali', 38, 68, 'تم اس سے منہ پھیرنے والے ہو'),
  ('ur.ahmedali', 38, 69, 'مجھے فرشتو ں کے متعلق کوئی علم نہیں تھا جب کہ وہ جھگڑ رہے تھے'),
  ('ur.ahmedali', 38, 70, 'مجھے تو یہی وحی کیا گیا ہے کہ میں تمہیں صاف صاف ڈراؤں'),
  ('ur.ahmedali', 38, 71, 'جب تیرے رب نے فرشتوں سے کہا کہ میں ایک انسان مٹی سے بنانے والا ہوں'),
  ('ur.ahmedali', 38, 72, 'پھرجب میں اسے پورے طور پر بنا لوں اور اس میں اپنی رو ح پھونک دوں تو اس کے لیے سجدہ میں گر پڑنا'),
  ('ur.ahmedali', 38, 73, 'پھر سب کے سب فرشتوں نے سجدہ کیا'),
  ('ur.ahmedali', 38, 74, 'مگر ابلیس نے نہ کیا تکبر کیا اور کافروں میں سے ہو گیا'),
  ('ur.ahmedali', 38, 75, 'فرمایا اے ابلیس! تمہیں اس کےے سجدہ کرنے سے کس نے منع کیا جسے میں نے اپنے ہاتھوں سے بنایا کیا تو نے تکبر کیا یا تو بڑوں میں سے تھا'),
  ('ur.ahmedali', 38, 76, 'اس نے عرض کی میں اس سے بہتر ہوں مجھے تو نے آگ سے بنایااور اسے مٹی سے بنایا'),
  ('ur.ahmedali', 38, 77, 'فرمایا پھر تو یہاں سے نکل جاکیوں نکہ تو راندہ گیا ہے'),
  ('ur.ahmedali', 38, 78, 'اور تجھ پر قیامت تک میری لعنت ہے'),
  ('ur.ahmedali', 38, 79, 'عرض کی اے میرے رب! پھر مجھے مردوں کے زندہ ہونے تک مہلت دے'),
  ('ur.ahmedali', 38, 80, 'فرمایا پس تمہیں مہلت ہے'),
  ('ur.ahmedali', 38, 81, 'وقت معین کے دن تک'),
  ('ur.ahmedali', 38, 82, 'عرض کی تیری عز ت کی قسم! میں ان سب کو گمراہ کر دوں گا'),
  ('ur.ahmedali', 38, 83, 'مگر ان میں جو تیرے خالص بندے ہوں گے'),
  ('ur.ahmedali', 38, 84, 'فرمایا حق بات یہ ہے اور میں حق ہی کہا کرتا ہوں'),
  ('ur.ahmedali', 38, 85, 'میں تجھ سے اوران میں سے جو تیرے تابع ہوں گے سب سے جہنم بھر دوں گا'),
  ('ur.ahmedali', 38, 86, 'کہہ دو میں اس پر تم سے کوئی مزدوری نہیں مانگتا اور نہ میں تکلف کرنے والوں میں ہوں'),
  ('ur.ahmedali', 38, 87, 'یہ قرآن تو تمام جہان کے لیے نصیحت ہے'),
  ('ur.ahmedali', 38, 88, 'اور تم کچھ مدت کے بعد اس کا حال ضرور جان لوگے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 38, 1, 'Sad. Öğüt veren Kuran\'a and olsun ki, inkar edenler gurur ve ayrılık içindedirler.'),
  ('tr.diyanet', 38, 2, 'Sad. Öğüt veren Kuran\'a and olsun ki, inkar edenler gurur ve ayrılık içindedirler.'),
  ('tr.diyanet', 38, 3, 'Onlardan önce nice nesilleri yok ettik. Feryat ediyorlardı; oysa artık kurtulma zamanı değildi.'),
  ('tr.diyanet', 38, 4, 'Aralarından bir uyarıcının gelmesine şaşmışlardı. İnkarcılar: "Bu, pek yalancı bir sihirbazdır; tanrıları tek bir tanrı mı yaptı? Doğrusu bu tuhaf bir şeydir" demişlerdi.'),
  ('tr.diyanet', 38, 5, 'Aralarından bir uyarıcının gelmesine şaşmışlardı. İnkarcılar: "Bu, pek yalancı bir sihirbazdır; tanrıları tek bir tanrı mı yaptı? Doğrusu bu tuhaf bir şeydir" demişlerdi.'),
  ('tr.diyanet', 38, 6, 'Onlardan ileri gelenler: "Yürüyün, tanrılarınıza bağlılıkta direnin, sizden istenen şüphesiz budur. Başka dinde de bunu işitmedik; bu ancak bir uydurmadır. Kuran, aramızda ona mı indirilmeliydi?" dediler. Hayır, bunlar Kuran\'ımızdan şüphededirler. Hayır, azabımızı henüz tatmamışlardır.'),
  ('tr.diyanet', 38, 7, 'Onlardan ileri gelenler: "Yürüyün, tanrılarınıza bağlılıkta direnin, sizden istenen şüphesiz budur. Başka dinde de bunu işitmedik; bu ancak bir uydurmadır. Kuran, aramızda ona mı indirilmeliydi?" dediler. Hayır, bunlar Kuran\'ımızdan şüphededirler. Hayır, azabımızı henüz tatmamışlardır.'),
  ('tr.diyanet', 38, 8, 'Onlardan ileri gelenler: "Yürüyün, tanrılarınıza bağlılıkta direnin, sizden istenen şüphesiz budur. Başka dinde de bunu işitmedik; bu ancak bir uydurmadır. Kuran, aramızda ona mı indirilmeliydi?" dediler. Hayır, bunlar Kuran\'ımızdan şüphededirler. Hayır, azabımızı henüz tatmamışlardır.'),
  ('tr.diyanet', 38, 9, 'Yoksa, güçlü ve çok ihsan sahibi olan Rabbinin rahmet hazineleri onların yanında mıdır?'),
  ('tr.diyanet', 38, 10, 'Yahut, göklerin, yerin ve ikisi arasında bulunanların hükümranlığı onların elinde midir? Öyle ise sebeplere tevessül edip göğe yükselsinler!'),
  ('tr.diyanet', 38, 11, 'Onlar burada takım takım bozguna uğramış perişan bir ordudur.'),
  ('tr.diyanet', 38, 12, 'Onlardan önce Nuh milleti, Ad, sarsılmaz bir saltanatın sahibi Firavun, Semud, Lut milleti, Eykeliler de peygamberleri yalanlamıştı. İşte bunlar da peygamberlerine karşı birleşen topluluklardır.'),
  ('tr.diyanet', 38, 13, 'Onlardan önce Nuh milleti, Ad, sarsılmaz bir saltanatın sahibi Firavun, Semud, Lut milleti, Eykeliler de peygamberleri yalanlamıştı. İşte bunlar da peygamberlerine karşı birleşen topluluklardır.'),
  ('tr.diyanet', 38, 14, 'Hepsi peygamberleri yalanladı da azabımı hakettiler.'),
  ('tr.diyanet', 38, 15, 'Bunlar da ancak, bir an gecikmesi olmayan tek bir çığlık beklemektedirler.'),
  ('tr.diyanet', 38, 16, 'Onlar ise "Rabbimiz! Bizim payımızı hesap gününden önce ver" derler.'),
  ('tr.diyanet', 38, 17, 'Onların söylediklerine sabret; güçlü kulumuz Davud\'u an; o, daima Allah\'a yönelirdi.'),
  ('tr.diyanet', 38, 18, 'Doğrusu Biz, akşam sabah onunla beraber tesbih eden dağları, kuşları da toplu halde onun buyruğu altına vermiştik. Her biri ona yönelmekteydi.'),
  ('tr.diyanet', 38, 19, 'Doğrusu Biz, akşam sabah onunla beraber tesbih eden dağları, kuşları da toplu halde onun buyruğu altına vermiştik. Her biri ona yönelmekteydi.'),
  ('tr.diyanet', 38, 20, 'Onun hükümranlığını kuvvetlendirmiştik. Ona hikmet ve kesin hüküm selahiyeti vermiştik.'),
  ('tr.diyanet', 38, 21, 'Sana davacıların haberi ulaştı mı? Mabedin duvarına tırmanıp Davud\'un yanına girmişlerdi de, o onlardan ürkmüştü. Şöyle demişlerdi: "Korkma, birbirinin hakkına tecavüz etmiş iki davacıyız; aramızda adaletle hükmet, ondan ayrılma, bizi doğru yola çıkar."'),
  ('tr.diyanet', 38, 22, 'Sana davacıların haberi ulaştı mı? Mabedin duvarına tırmanıp Davud\'un yanına girmişlerdi de, o onlardan ürkmüştü. Şöyle demişlerdi: "Korkma, birbirinin hakkına tecavüz etmiş iki davacıyız; aramızda adaletle hükmet, ondan ayrılma, bizi doğru yola çıkar."'),
  ('tr.diyanet', 38, 23, '"Bu kardeşimin doksan dokuz dişi koyunu, benim de bir tek dişi koyunum vardır; O\'nu da bana ver dedi ve tartışmada beni yendi."'),
  ('tr.diyanet', 38, 24, 'Davud: "And olsun ki, senin dişi koyununu kendi dişi koyunlarına katmak istemekle sana haksızlıkta bulunmuştur. Doğrusu ortakçıların çoğu birbirlerinin haklarına tecavüz ederler. İnanıp yararlı iş işleyenler bunun dışındadır ki sayıları da ne kadar azdır!" demişti. Davud, Kendisini denediğimizi sanmıştı da, Rabbinden mağfiret dileyerek eğilip secdeye kapanmış, tevbe etmiş, Allah\'a yönelmişti.'),
  ('tr.diyanet', 38, 25, 'Böylece onu bağışlamıştık. Katımızda onun yakınlığı ve güzel bir geleceği vardır.'),
  ('tr.diyanet', 38, 26, 'Ey Davud! Seni şüphesiz yeryüzünde hükümran kıldık, o halde insanlar arasında adaletle hükmet, hevese uyma yoksa seni Allah\'ın yolundan saptırır. Doğrusu, Allah\'ın yolundan sapanlara, onlara, hesap gününü unutmalarına karşılık çetin azap vardır.'),
  ('tr.diyanet', 38, 27, 'Göğü, yeri ve ikisinin arasında bulunanları boşuna yaratmadık. Bunun boşuna olduğu, inkar edenlerin sanısıdır. Vay ateşe uğrayacak inkarcıların haline!'),
  ('tr.diyanet', 38, 28, 'Yoksa, inanıp yararlı iş işleyenleri, yeryüzünde, bozguncular gibi mi tutarız? Yoksa, Allah\'a karşı gelmekten sakınanları yoldan çıkanlar gibi mi tutarız?'),
  ('tr.diyanet', 38, 29, 'Sana indirdiğimiz bu Kitap mübarektir; ayetlerini düşünsünler, aklı olanlar da öğüt alsınlar.'),
  ('tr.diyanet', 38, 30, 'Davud\'a Süleyman\'ı bahşettik; o ne güzel bir kuldu! Doğrusu o daima Allah\'a yönelirdi.'),
  ('tr.diyanet', 38, 31, 'Ona bir akşam üstü, çalımlı, cins koşu atları sunulmuştu.'),
  ('tr.diyanet', 38, 32, 'Süleyman: "Doğrusu ben bu iyi malları, Rabbimi anmayı sağladıkları için severim" demişti. Koşup, toz perdesi arkasında kayboldukları zaman: "onları bana getirin" dedi. Bacaklarını ve boyunlarını sıvazlamaya başlamıştı.'),
  ('tr.diyanet', 38, 33, 'Süleyman: "Doğrusu ben bu iyi malları, Rabbimi anmayı sağladıkları için severim" demişti. Koşup, toz perdesi arkasında kayboldukları zaman: "onları bana getirin" dedi. Bacaklarını ve boyunlarını sıvazlamaya başlamıştı.'),
  ('tr.diyanet', 38, 34, 'And olsun ki Süleyman\'ı denedik, hükümranlığını zayıf düşürdük; sonra eski haline döndü.'),
  ('tr.diyanet', 38, 35, 'Süleyman: "Rabbim! Beni bağışla, bana benden sonra kimsenin ulaşamayacağı bir hükümranlık ver; Sen şüphesiz, daima bağışta bulunansın" dedi.'),
  ('tr.diyanet', 38, 36, 'Bunun üzerine Biz de, istediği yere onun buyruğu ile kolayca giden rüzgarı, bina kuran ve dalgıçlık yapan şeytanları, demir halkalarla bağlı diğerlerini onun buyruğu altına verdik.'),
  ('tr.diyanet', 38, 37, 'Bunun üzerine Biz de, istediği yere onun buyruğu ile kolayca giden rüzgarı, bina kuran ve dalgıçlık yapan şeytanları, demir halkalarla bağlı diğerlerini onun buyruğu altına verdik.'),
  ('tr.diyanet', 38, 38, 'Bunun üzerine Biz de, istediği yere onun buyruğu ile kolayca giden rüzgarı, bina kuran ve dalgıçlık yapan şeytanları, demir halkalarla bağlı diğerlerini onun buyruğu altına verdik.'),
  ('tr.diyanet', 38, 39, '"İşte Bizim bağışımız budur; ister ver, ister tut, hesapsızdır." dedik.'),
  ('tr.diyanet', 38, 40, 'Doğrusu onun katımızda yakınlığı ve güzel bir istikbali vardır.'),
  ('tr.diyanet', 38, 41, 'Kulumuz Eyyub\'u da an; Rabbine: "Doğrusu şeytan bana yorgunluk ve azap verdi" diye seslenmişti.'),
  ('tr.diyanet', 38, 42, '"Ayağını yere vur! İşte yıkanacak ve içilecek soğuk bir su" dedik.'),
  ('tr.diyanet', 38, 43, 'Katımızdan bir rahmet ve akıl sahiplerine bir öğüt olmak üzere, ona tekrar ailesini ve geçmiş olanlarla bir mislini daha vermiştik.'),
  ('tr.diyanet', 38, 44, '"Ey Eyyub! Eline bir demet sap alıp onunla vur, yeminini bozma" demiştik. Doğrusu Biz onu sabırlı bulmuştuk. Ne iyi kuldu, daima Allah\'a yönelirdi.'),
  ('tr.diyanet', 38, 45, 'Güçlü ve anlayışlı olan kullarımız İbrahim, İshak ve Yakub\'u da an.'),
  ('tr.diyanet', 38, 46, 'Biz onları ahiret yurdunu düşünen, içten bağlı kimseler kıldık.'),
  ('tr.diyanet', 38, 47, 'Doğrusu onlar katımızda seçkin, iyi kimselerdendirler.'),
  ('tr.diyanet', 38, 48, 'İsmail\'i, Elyesa\'ı, Zülkifl\'i de an. Hepsi iyilerdendir.'),
  ('tr.diyanet', 38, 49, 'İşte bu güzel bir anmadır. Doğrusu Allah\'a karşı gelmekten sakınanlara güzel bir gelecek vardır.'),
  ('tr.diyanet', 38, 50, 'Kapıları onlara açılmış Adn cennetleri vardır.'),
  ('tr.diyanet', 38, 51, 'Orada tahtlara yaslanmış olarak türlü meyveler ve içecekler isterler.'),
  ('tr.diyanet', 38, 52, 'Yanlarında, gözlerini eşlerine dikmiş yaşıt güzeller vardır.'),
  ('tr.diyanet', 38, 53, 'İşte bu hesap günü için, size söz verilenlerdir.'),
  ('tr.diyanet', 38, 54, 'Doğrusu, verdiğimiz bu rızıklar tükenecek değildir.'),
  ('tr.diyanet', 38, 55, 'Bu böyle; ama azgınlara kötü bir gelecek vardır.'),
  ('tr.diyanet', 38, 56, 'Cehenneme girerler; ne kötü bir konaktır!'),
  ('tr.diyanet', 38, 57, 'İşte bu kaynar su ve irindir, artık onu tatsınlar.'),
  ('tr.diyanet', 38, 58, 'Bunlara benzer daha başkaları da vardır...'),
  ('tr.diyanet', 38, 59, '(İnkarcıların ileri gelenlerine denir ki;) "İşte şunlar sizinle beraber girecek olanlardır." (Derler ki;) "Onlar rahat yüzü görmesin. Behemehal ateşe gireceklerdir"'),
  ('tr.diyanet', 38, 60, '(Onlara uyanlar;) "Hayır, asıl siz rahat yüzü görmeyin; bunu başımıza getiren sizsiniz; ne kötü bir duraktır!" derler.'),
  ('tr.diyanet', 38, 61, '"Rabbimiz! Bunu kim başımıza getirdiyse, ateşte onun azabını kat kat artır" derler.'),
  ('tr.diyanet', 38, 62, 'Şöyle derler: "Kendilerini dünyada iken kötü saydığımız kimseleri burada niçin görmüyoruz?"'),
  ('tr.diyanet', 38, 63, '"Onları alaya alırdık; yoksa şimdi gözlere görünmezler mi?"'),
  ('tr.diyanet', 38, 64, 'İşte cehennemliklerin bu şekilde tartışması gerçektir.'),
  ('tr.diyanet', 38, 65, 'De ki: "Ben sadece bir uyarıcıyım. Gücü her şeye yeten tek Allah\'tan başka tanrı yoktur."'),
  ('tr.diyanet', 38, 66, '"Göklerin, yerin ve ikisi arasında bulunanların Rabbi, güçlüdür, çok bağışlayandır."'),
  ('tr.diyanet', 38, 67, 'De ki: "Bu Kuran büyük bir haberdir, ama siz ondan yüz çeviriyorsunuz."'),
  ('tr.diyanet', 38, 68, 'De ki: "Bu Kuran büyük bir haberdir, ama siz ondan yüz çeviriyorsunuz."'),
  ('tr.diyanet', 38, 69, '"Onlar tartışırlarken Melei Ala\'daki bu olanlar hakkında bir bilgim yoktu."'),
  ('tr.diyanet', 38, 70, '"Bana sadece vahyolunuyor; doğrusu ben ancak apaçık bir uyarıcıyım."'),
  ('tr.diyanet', 38, 71, 'Rabbin meleklere şöyle demişti: "Ben çamurdan bir insan yaratacağım. Onu yapıp ruhumdan ona üflediğim zaman ona secdeye kapanın."'),
  ('tr.diyanet', 38, 72, 'Rabbin meleklere şöyle demişti: "Ben çamurdan bir insan yaratacağım. Onu yapıp ruhumdan ona üflediğim zaman ona secdeye kapanın."'),
  ('tr.diyanet', 38, 73, 'Bütün melekler secde etmişlerdi, fakat İblis; o, büyüklük taslamış ve inkarcılardan olmuştu.'),
  ('tr.diyanet', 38, 74, 'Bütün melekler secde etmişlerdi, fakat İblis; o, büyüklük taslamış ve inkarcılardan olmuştu.'),
  ('tr.diyanet', 38, 75, 'Allah: "Ey İblis, ellerimle (kudretimle) yarattığıma secde etmekten seni alıkoyan nedir? Böbürlendin mi? Yoksa gururlananlardan mısın?" dedi.'),
  ('tr.diyanet', 38, 76, 'İblis: "Ben ondan daha üstünüm. Beni ateşten yarattın, onu çamurdan yarattın" dedi.'),
  ('tr.diyanet', 38, 77, 'Allah: "Defol oradan, sen artık kovulmuş birisin. Din (kıyamet/ceza) gününe kadar lanetim senin üzerinedir" dedi.'),
  ('tr.diyanet', 38, 78, 'Allah: "Defol oradan, sen artık kovulmuş birisin. Din (kıyamet/ceza) gününe kadar lanetim senin üzerinedir" dedi.'),
  ('tr.diyanet', 38, 79, '"Rabbim! Dirilecekleri güne kadar beni (canımı almayı) ertele" dedi.'),
  ('tr.diyanet', 38, 80, 'Allah: "Sen bilinen güne kadar erteye bırakılanlardansın" dedi.'),
  ('tr.diyanet', 38, 81, 'Allah: "Sen bilinen güne kadar erteye bırakılanlardansın" dedi.'),
  ('tr.diyanet', 38, 82, 'İblis: "Senin kudretine and olsun ki, onlardan, sana içten bağlı olan kulların bir yana, hepsini azdıracağım" dedi.'),
  ('tr.diyanet', 38, 83, 'İblis: "Senin kudretine and olsun ki, onlardan, sana içten bağlı olan kulların bir yana, hepsini azdıracağım" dedi.'),
  ('tr.diyanet', 38, 84, 'Allah: "Doğrudur; işte Ben hakikati söylüyorum, sen ve sana uyanların hepsiyle cehennemi dolduracağım" dedi.'),
  ('tr.diyanet', 38, 85, 'Allah: "Doğrudur; işte Ben hakikati söylüyorum, sen ve sana uyanların hepsiyle cehennemi dolduracağım" dedi.'),
  ('tr.diyanet', 38, 86, 'De ki: "Buna karşılık sizden bir ücret istemiyorum. Kendiliğimden bir şey iddia eden kimselerden de değilim."'),
  ('tr.diyanet', 38, 87, '"Bu Kuran, ancak dünyalar için bir öğüttür."'),
  ('tr.diyanet', 38, 88, '"Onun verdiği haberin doğruluğunu bir zaman sonra öğreneceksiniz."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 38, 1, 'Shaad, demi Al Quran yang mempunyai keagungan.'),
  ('id.indonesian', 38, 2, 'Sebenarnya orang-orang kafir itu (berada) dalam kesombongan dan permusuhan yang sengit.'),
  ('id.indonesian', 38, 3, 'Betapa banyaknya umat sebelum mereka yang telah Kami binasakan, lalu mereka meminta tolong padahal (waktu itu) bukanlah saat untuk lari melepaskan diri.'),
  ('id.indonesian', 38, 4, 'Dan mereka heran karena mereka kedatangan seorang pemberi peringatan (rasul) dari kalangan mereka; dan orang-orang kafir berkata: "Ini adalah seorang ahli sihir yang banyak berdusta".'),
  ('id.indonesian', 38, 5, 'Mengapa ia menjadikan tuhan-tuhan itu Tuhan Yang Satu saja? Sesungguhnya ini benar-benar suatu hal yang sangat mengherankan.'),
  ('id.indonesian', 38, 6, 'Dan pergilah pemimpin-pemimpin mereka (seraya berkata): "Pergilah kamu dan tetaplah (menyembah) tuhan-tuhanmu, sesungguhnya ini benar-benar suatu hal yang dikehendaki.'),
  ('id.indonesian', 38, 7, 'Kami tidak pernah mendengar hal ini dalam agama yang terakhir; ini (mengesakan Allah), tidak lain hanyalah (dusta) yang diada-adakan,'),
  ('id.indonesian', 38, 8, 'mengapa Al Quran itu diturunkan kepadanya di antara kita?" Sebenarnya mereka ragu-ragu terhadap Al Quran-Ku, dan sebenarnya mereka belum merasakan azab-Ku.'),
  ('id.indonesian', 38, 9, 'Atau apakah mereka itu mempunyai perbendaharaan rahmat Tuhanmu Yang Maha Perkasa lagi Maha Pemberi?'),
  ('id.indonesian', 38, 10, 'Atau apakah bagi mereka kerajaan langit dan bumi dan yang ada di antara keduanya? (Jika ada), maka hendaklah mereka menaiki tangga-tangga (ke langit).'),
  ('id.indonesian', 38, 11, 'Suatu tentara yang besar yang berada disana dari golongan-golongan yang berserikat, pasti akan dikalahkan.'),
  ('id.indonesian', 38, 12, 'Telah mendustakan (rasul-rasul pula) sebelum mereka itu kaum Nuh, \'Aad, Fir\'aun yang mempunyai tentara yang banyak,'),
  ('id.indonesian', 38, 13, 'dan Tsamud, kaum Luth dan penduduk Aikah. Mereka itulah golongan-golongan yang bersekutu (menentang rasul-rasul).'),
  ('id.indonesian', 38, 14, 'Semua mereka itu tidak lain hanyalah mendustakan rasul-rasul, maka pastilah (bagi mereka) azab-Ku.'),
  ('id.indonesian', 38, 15, 'Tidaklah yang mereka tunggu melainkan hanya satu teriakan saja yang tidak ada baginya saat berselang.'),
  ('id.indonesian', 38, 16, 'Dan mereka berkata: "Ya Tuhan kami cepatkanlah untuk kami azab yang diperuntukkan bagi kami sebelum hari berhisab".'),
  ('id.indonesian', 38, 17, 'Bersabarlah atas segala apa yang mereka katakan; dan ingatlah hamba Kami Daud yang mempunyai kekuatan; sesungguhnya dia amat taat (kepada Tuhan).'),
  ('id.indonesian', 38, 18, 'Sesungguhnya Kami menundukkan gunung-gunung untuk bertasbih bersama dia (Daud) di waktu petang dan pagi,'),
  ('id.indonesian', 38, 19, 'dan (Kami tundukkan pula) burung-burung dalam keadaan terkumpul. Masing-masingnya amat taat kepada Allah.'),
  ('id.indonesian', 38, 20, 'Dan Kami kuatkan kerajaannya dan Kami berikan kepadanya hikmahdan kebijaksanaan dalam menyelesaikan perselisihan.'),
  ('id.indonesian', 38, 21, 'Dan adakah sampai kepadamu berita orang-orang yang berperkara ketika mereka memanjat pagar?'),
  ('id.indonesian', 38, 22, 'Ketika mereka masuk (menemui) Daud lalu ia terkejut karena kedatangan) mereka. Mereka berkata: "Janganlah kamu merasa takut; (kami) adalah dua orang yang berperkara yang salah seorang dari kami berbuat zalim kepada yang lain; maka berilah keputusan antara kami dengan adil dan janganlah kamu menyimpang dari kebenaran dan tunjukilah kami ke jalan yang lurus.'),
  ('id.indonesian', 38, 23, 'Sesungguhnya saudaraku ini mempunyai sembilan puluh sembilan ekor kambing betina dan aku mempunyai seekor saja. Maka dia berkata: "Serahkanlah kambingmu itu kepadaku dan dia mengalahkan aku dalam perdebatan".'),
  ('id.indonesian', 38, 24, 'Daud berkata: "Sesungguhnya dia telah berbuat zalim kepadamu dengan meminta kambingmu itu untuk ditambahkan kepada kambingnya. Dan sesungguhnya kebanyakan dari orang-orang yang berserikat itu sebahagian mereka berbuat zalim kepada sebahagian yang lain, kecuali orang-orang yang beriman dan mengerjakan amal yang saleh; dan amat sedikitlah mereka ini". Dan Daud mengetahui bahwa Kami mengujinya; maka ia meminta ampun kepada Tuhannya lalu menyungkur sujud dan bertaubat.'),
  ('id.indonesian', 38, 25, 'Maka Kami ampuni baginya kesalahannya itu. Dan sesungguhnya dia mempunyai kedudukan dekat pada sisi Kami dan tempat kembali yang baik.'),
  ('id.indonesian', 38, 26, 'Hai Daud, sesungguhnya Kami menjadikan kamu khalifah (penguasa) di muka bumi, maka berilah keputusan (perkara) di antara manusia dengan adil dan janganlah kamu mengikuti hawa nafsu, karena ia akan menyesatkan kamu dari jalan Allah. Sesungguhnya orang-orang yang sesat darin jalan Allah akan mendapat azab yang berat, karena mereka melupakan hari perhitungan.'),
  ('id.indonesian', 38, 27, 'Dan Kami tidak menciptakan langit dan bumi dan apa yang ada antara keduanya tanpa hikmah. Yang demikian itu adalah anggapan orang-orang kafir, maka celakalah orang-orang kafir itu karena mereka akan masuk neraka.'),
  ('id.indonesian', 38, 28, 'Patutkah Kami menganggap orang-orang yang beriman dan mengerjakan amal yang saleh sama dengan orang-orang yang berbuat kerusakan di muka bumi? Patutkah (pula) Kami menganggap orang-orang yang bertakwa sama dengan orang-orang yang berbuat maksiat?'),
  ('id.indonesian', 38, 29, 'Ini adalah sebuah kitab yang Kami turunkan kepadamu penuh dengan berkah supaya mereka memperhatikan ayat-ayatnya dan supaya mendapat pelajaran orang-orang yang mempunyai fikiran.'),
  ('id.indonesian', 38, 30, 'Dan Kami karuniakan kepada Daud, Sulaiman, dia adalah sebaik-baik hamba. Sesungguhnya dia amat taat (kepada Tuhannya),'),
  ('id.indonesian', 38, 31, '(ingatlah) ketika dipertunjukkan kepadanya kuda-kuda yang tenang di waktu berhenti dan cepat waktu berlari pada waktu sore,'),
  ('id.indonesian', 38, 32, 'maka ia berkata: "Sesungguhnya aku menyukai kesenangan terhadap barang yang baik (kuda) sehingga aku lalai mengingat Tuhanku sampai kuda itu hilang dari pandangan".'),
  ('id.indonesian', 38, 33, '"Bawalah kuda-kuda itu kembali kepadaku". Lalu ia potong kaki dan leher kuda itu.'),
  ('id.indonesian', 38, 34, 'Dan sesungguhnya Kami telah menguji Sulaiman dan Kami jadikan (dia) tergeletak di atas kursinya sebagai tubuh (yang lemah karena sakit), kemudian ia bertaubat.'),
  ('id.indonesian', 38, 35, 'Ia berkata: "Ya Tuhanku, ampunilah aku dan anugerahkanlah kepadaku kerajaan yang tidak dimiliki oleh seorang juapun sesudahku, sesungguhnya Engkaulah Yang Maha Pemberi".'),
  ('id.indonesian', 38, 36, 'Kemudian Kami tundukkan kepadanya angin yang berhembus dengan baik menurut ke mana saja yang dikehendakinya,'),
  ('id.indonesian', 38, 37, 'dan (Kami tundukkan pula kepadanya) syaitan-syaitan semuanya ahli bangunan dan penyelam,'),
  ('id.indonesian', 38, 38, 'dan syaitan yang lain yang terikat dalam belenggu.'),
  ('id.indonesian', 38, 39, 'Inilah anugerah Kami; maka berikanlah (kepada orang lain) atau tahanlah (untuk dirimu sendiri) dengan tiada pertanggungan jawab.'),
  ('id.indonesian', 38, 40, 'Dan sesungguhnya dia mempunyai kedudukan yang dekat pada sisi Kami dan tempat kembali yang baik.'),
  ('id.indonesian', 38, 41, 'Dan ingatlah akan hamba Kami Ayyub ketika ia menyeru Tuhan-nya: "Sesungguhnya aku diganggu syaitan dengan kepayahan dan siksaan".'),
  ('id.indonesian', 38, 42, '(Allah berfirman): "Hantamkanlah kakimu; inilah air yang sejuk untuk mandi dan untuk minum".'),
  ('id.indonesian', 38, 43, 'Dan Kami anugerahi dia (dengan mengumpulkan kembali) keluarganya dan (Kami tambahkan) kepada mereka sebanyak mereka pula sebagai rahmat dari Kami dan pelajaran bagi orang-orang yang mempunyai fikiran.'),
  ('id.indonesian', 38, 44, 'Dan ambillah dengan tanganmu seikat (rumput), maka pukullah dengan itu dan janganlah kamu melanggar sumpah. Sesungguhnya Kami dapati dia (Ayyub) seorang yang sabar. Dialah sebaik-baik hamba. Sesungguhnya dia amat taat (kepada Tuhan-nya).'),
  ('id.indonesian', 38, 45, 'Dan ingatlah hamba-hamba Kami: Ibrahim, Ishaq dan Ya\'qub yang mempunyai perbuatan-perbuatan yang besar dan ilmu-ilmu yang tinggi.'),
  ('id.indonesian', 38, 46, 'Sesungguhnya Kami telah mensucikan mereka dengan (menganugerahkan kepada mereka) akhlak yang tinggi yaitu selalu mengingatkan (manusia) kepada negeri akhirat.'),
  ('id.indonesian', 38, 47, 'Dan sesungguhnya mereka pada sisi Kami benar-benar termasuk orang-orang pilihan yang paling baik.'),
  ('id.indonesian', 38, 48, 'Dan ingatlah akan Ismail, Ilyasa\' dan Zulkifli. Semuanya termasuk orang-orang yang paling baik.'),
  ('id.indonesian', 38, 49, 'Ini adalah kehormatan (bagi mereka). Dan sesungguhnya bagi orang-orang yang bertakwa benar-benar (disediakan) tempat kembali yang baik,'),
  ('id.indonesian', 38, 50, '(yaitu) surga \'Adn yang pintu-pintunya terbuka bagi mereka,'),
  ('id.indonesian', 38, 51, 'di dalamnya mereka bertelekan (diatas dipan-dipan) sambil meminta buah-buahan yang banyak dan minuman di surga itu.'),
  ('id.indonesian', 38, 52, 'Dan pada sisi mereka (ada bidadari-bidadari) yang tidak liar pandangannya dan sebaya umurnya.'),
  ('id.indonesian', 38, 53, 'Inilah apa yang dijanjikan kepadamu pada hari berhisab.'),
  ('id.indonesian', 38, 54, 'Sesungguhnya ini adalah benar-benar rezeki dari Kami yang tiada habis-habisnya.'),
  ('id.indonesian', 38, 55, 'Beginilah (keadaan mereka). Dan sesungguhnya bagi orang-orang yang durhaka benar-benar (disediakan) tempat kembali yang buruk,'),
  ('id.indonesian', 38, 56, '(yaitu) neraka Jahannam, yang mereka masuk ke dalamnya; maka amat buruklah Jahannam itu sebagai tempat tinggal.'),
  ('id.indonesian', 38, 57, 'Inilah (azab neraka), biarlah mereka merasakannya, (minuman mereka) air yang sangat panas dan air yang sangat dingin.'),
  ('id.indonesian', 38, 58, 'Dan azab yang lain yang serupa itu berbagai macam.'),
  ('id.indonesian', 38, 59, '(Dikatakan kepada mereka): "Ini adalah suatu rombongan (pengikut-pengikutmu) yang masuk berdesak-desak bersama kamu (ke neraka)". (Berkata pemimpin-pemimpin mereka yang durhaka): "Tiadalah ucapan selamat datang kepada mereka karena sesungguhnya mereka akan masuk neraka".'),
  ('id.indonesian', 38, 60, 'Pengikut-pengikut mereka menjawab: "Sebenarnya kamulah. Tiada ucapan selamat datang bagimu, karena kamulah yang menjerumuskan kami ke dalam azab, maka amat buruklah Jahannam itu sebagai tempat menetap".'),
  ('id.indonesian', 38, 61, 'Mereka berkata (lagi): "Ya Tuhan kami; barang siapa yang menjerumuskan kami ke dalam azab ini maka tambahkanlah azab kepadanya dengan berlipat ganda di dalam neraka".'),
  ('id.indonesian', 38, 62, 'Dan (orang-orang durhaka) berkata: "Mengapa kami tidak melihat orang-orang yang dahulu (di dunia) kami anggap sebagai orang-orang yang jahat (hina).'),
  ('id.indonesian', 38, 63, 'Apakah kami dahulu menjadikan mereka olok-olokan, ataukah karena mata kami tidak melihat mereka?"'),
  ('id.indonesian', 38, 64, 'Sesungguhnya yang demikian itu pasti terjadi, (yaitu) pertengkaran penghuni neraka.'),
  ('id.indonesian', 38, 65, 'Katakanlah (ya Muhammad): "Sesungguhnya aku hanya seorang pemberi peringatan, dan sekali-kali tidak ada Tuhan selain Allah Yang Maha Esa dan Maha Mengalahkan.'),
  ('id.indonesian', 38, 66, 'Tuhan langit dan bumi dan apa yang ada di antara keduanya Yang Maha Perkasa lagi Maha Pengampun.'),
  ('id.indonesian', 38, 67, 'Katakanlah: "Berita itu adalah berita yang besar,'),
  ('id.indonesian', 38, 68, 'yang kamu berpaling daripadanya.'),
  ('id.indonesian', 38, 69, 'Aku tiada mempunyai pengetahuan sedikitpun tentang al mala\'ul a\'la (malaikat) itu ketika mereka berbantah-bantahan.'),
  ('id.indonesian', 38, 70, 'Tidak diwahyukan kepadaku, melainkan bahwa sesungguhnya aku hanyalah seorang pemberi peringatan yang nyata".'),
  ('id.indonesian', 38, 71, '(Ingatlah) ketika Tuhanmu berfirman kepada malaikat: "Sesungguhnya Aku akan menciptakan manusia dari tanah".'),
  ('id.indonesian', 38, 72, 'Maka apabila telah Kusempurnakan kejadiannya dan Kutiupkan kepadanya roh (ciptaan)Ku; maka hendaklah kamu tersungkur dengan bersujud kepadanya".'),
  ('id.indonesian', 38, 73, 'Lalu seluruh malaikat-malaikat itu bersujud semuanya,'),
  ('id.indonesian', 38, 74, 'kecuali iblis; dia menyombongkan diri dan adalah dia termasuk orang-orang yang kafir.'),
  ('id.indonesian', 38, 75, 'Allah berfirman: "Hai iblis, apakah yang menghalangi kamu sujud kepada yang telah Ku-ciptakan dengan kedua tangan-Ku. Apakah kamu menyombongkan diri ataukah kamu (merasa) termasuk orang-orang yang (lebih) tinggi?".'),
  ('id.indonesian', 38, 76, 'Iblis berkata: "Aku lebih baik daripadanya, karena Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah".'),
  ('id.indonesian', 38, 77, 'Allah berfirman: "Maka keluarlah kamu dari surga; sesungguhnya kamu adalah orang yang terkutuk,'),
  ('id.indonesian', 38, 78, 'Sesungguhnya kutukan-Ku tetap atasmu sampai hari pembalasan".'),
  ('id.indonesian', 38, 79, 'Iblis berkata: "Ya Tuhanku, beri tangguhlah aku sampai hari mereka dibangkitkan".'),
  ('id.indonesian', 38, 80, 'Allah berfirman: "Sesungguhnya kamu termasuk orang-orang yang diberi tangguh,'),
  ('id.indonesian', 38, 81, 'sampai kepada hari yang telah ditentukan waktunya (hari Kiamat)".'),
  ('id.indonesian', 38, 82, 'Iblis menjawab: "Demi kekuasaan Engkau aku akan menyesatkan mereka semuanya,'),
  ('id.indonesian', 38, 83, 'kecuali hamba-hamba-Mu yang mukhlis di antara mereka.'),
  ('id.indonesian', 38, 84, 'Allah berfirman: "Maka yang benar (adalah sumpah-Ku) dan hanya kebenaran itulah yang Ku-katakan".'),
  ('id.indonesian', 38, 85, 'Sesungguhnya Aku pasti akan memenuhi neraka Jahannam dengan jenis kamu dan dengan orang-orang yang mengikuti kamu di antara mereka kesemuanya.'),
  ('id.indonesian', 38, 86, 'Katakanlah (hai Muhammad): "Aku tidak meminta upah sedikitpun padamu atas dakwahku dan bukanlah aku termasuk orang-orang yang mengada-adakan.'),
  ('id.indonesian', 38, 87, 'Al Quran ini tidak lain hanyalah peringatan bagi semesta alam.'),
  ('id.indonesian', 38, 88, 'Dan sesungguhnya kamu akan mengetahui (kebenaran) berita Al Quran setelah beberapa waktu lagi.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 39, 1, 'The revelation of the Qur\'an is from Allah, the Exalted in Might, the Wise.'),
  ('en.sahih', 39, 2, 'Indeed, We have sent down to you the Book, [O Muhammad], in truth. So worship Allah, [being] sincere to Him in religion.'),
  ('en.sahih', 39, 3, 'Unquestionably, for Allah is the pure religion. And those who take protectors besides Him [say], "We only worship them that they may bring us nearer to Allah in position." Indeed, Allah will judge between them concerning that over which they differ. Indeed, Allah does not guide he who is a liar and [confirmed] disbeliever.'),
  ('en.sahih', 39, 4, 'If Allah had intended to take a son, He could have chosen from what He creates whatever He willed. Exalted is He; He is Allah, the One, the Prevailing.'),
  ('en.sahih', 39, 5, 'He created the heavens and earth in truth. He wraps the night over the day and wraps the day over the night and has subjected the sun and the moon, each running [its course] for a specified term. Unquestionably, He is the Exalted in Might, the Perpetual Forgiver.'),
  ('en.sahih', 39, 6, 'He created you from one soul. Then He made from it its mate, and He produced for you from the grazing livestock eight mates. He creates you in the wombs of your mothers, creation after creation, within three darknesses. That is Allah, your Lord; to Him belongs dominion. There is no deity except Him, so how are you averted?'),
  ('en.sahih', 39, 7, 'If you disbelieve - indeed, Allah is Free from need of you. And He does not approve for His servants disbelief. And if you are grateful, He approves it for you; and no bearer of burdens will bear the burden of another. Then to your Lord is your return, and He will inform you about what you used to do. Indeed, He is Knowing of that within the breasts.'),
  ('en.sahih', 39, 8, 'And when adversity touches man, he calls upon his Lord, turning to Him [alone]; then when He bestows on him a favor from Himself, he forgets Him whom he called upon before, and he attributes to Allah equals to mislead [people] from His way. Say, "Enjoy your disbelief for a little; indeed, you are of the companions of the Fire."'),
  ('en.sahih', 39, 9, 'Is one who is devoutly obedient during periods of the night, prostrating and standing [in prayer], fearing the Hereafter and hoping for the mercy of his Lord, [like one who does not]? Say, "Are those who know equal to those who do not know?" Only they will remember [who are] people of understanding.'),
  ('en.sahih', 39, 10, 'Say, "O My servants who have believed, fear your Lord. For those who do good in this world is good, and the earth of Allah is spacious. Indeed, the patient will be given their reward without account."'),
  ('en.sahih', 39, 11, 'Say, [O Muhammad], "Indeed, I have been commanded to worship Allah, [being] sincere to Him in religion.'),
  ('en.sahih', 39, 12, 'And I have been commanded to be the first [among you] of the Muslims."'),
  ('en.sahih', 39, 13, 'Say, "Indeed I fear, if I should disobey my Lord, the punishment of a tremendous Day."'),
  ('en.sahih', 39, 14, 'Say, "Allah [alone] do I worship, sincere to Him in my religion,'),
  ('en.sahih', 39, 15, 'So worship what you will besides Him." Say, "Indeed, the losers are the ones who will lose themselves and their families on the Day of Resurrection. Unquestionably, that is the manifest loss."'),
  ('en.sahih', 39, 16, 'They will have canopies of fire above them and below them, canopies. By that Allah threatens His servants. O My servants, then fear Me.'),
  ('en.sahih', 39, 17, 'But those who have avoided Taghut, lest they worship it, and turned back to Allah - for them are good tidings. So give good tidings to My servants'),
  ('en.sahih', 39, 18, 'Who listen to speech and follow the best of it. Those are the ones Allah has guided, and those are people of understanding.'),
  ('en.sahih', 39, 19, 'Then, is one who has deserved the decree of punishment [to be guided]? Then, can you save one who is in the Fire?'),
  ('en.sahih', 39, 20, 'But those who have feared their Lord - for them are chambers, above them chambers built high, beneath which rivers flow. [This is] the promise of Allah. Allah does not fail in [His] promise.'),
  ('en.sahih', 39, 21, 'Do you not see that Allah sends down rain from the sky and makes it flow as springs [and rivers] in the earth; then He produces thereby crops of varying colors; then they dry and you see them turned yellow; then He makes them [scattered] debris. Indeed in that is a reminder for those of understanding.'),
  ('en.sahih', 39, 22, 'So is one whose breast Allah has expanded to [accept] Islam and he is upon a light from his Lord [like one whose heart rejects it]? Then woe to those whose hearts are hardened against the remembrance of Allah. Those are in manifest error.'),
  ('en.sahih', 39, 23, 'Allah has sent down the best statement: a consistent Book wherein is reiteration. The skins shiver therefrom of those who fear their Lord; then their skins and their hearts relax at the remembrance of Allah. That is the guidance of Allah by which He guides whom He wills. And one whom Allah leaves astray - for him there is no guide.'),
  ('en.sahih', 39, 24, 'Then is he who will shield with his face the worst of the punishment on the Day of Resurrection [like one secure from it]? And it will be said to the wrongdoers, "Taste what you used to earn."'),
  ('en.sahih', 39, 25, 'Those before them denied, and punishment came upon them from where they did not perceive.'),
  ('en.sahih', 39, 26, 'So Allah made them taste disgrace in worldly life. But the punishment of the Hereafter is greater, if they only knew.'),
  ('en.sahih', 39, 27, 'And We have certainly presented for the people in this Qur\'an from every [kind of] example - that they might remember.'),
  ('en.sahih', 39, 28, '[It is] an Arabic Qur\'an, without any deviance that they might become righteous.'),
  ('en.sahih', 39, 29, 'Allah presents an example: a slave owned by quarreling partners and another belonging exclusively to one man - are they equal in comparison? Praise be to Allah! But most of them do not know.'),
  ('en.sahih', 39, 30, 'Indeed, you are to die, and indeed, they are to die.'),
  ('en.sahih', 39, 31, 'Then indeed you, on the Day of Resurrection, before your Lord, will dispute.'),
  ('en.sahih', 39, 32, 'So who is more unjust than one who lies about Allah and denies the truth when it has come to him? Is there not in Hell a residence for the disbelievers?'),
  ('en.sahih', 39, 33, 'And the one who has brought the truth and [they who] believed in it - those are the righteous.'),
  ('en.sahih', 39, 34, 'They will have whatever they desire with their Lord. That is the reward of the doers of good -'),
  ('en.sahih', 39, 35, 'That Allah may remove from them the worst of what they did and reward them their due for the best of what they used to do.'),
  ('en.sahih', 39, 36, 'Is not Allah sufficient for His Servant [Prophet Muhammad]? And [yet], they threaten you with those [they worship] other than Him. And whoever Allah leaves astray - for him there is no guide.'),
  ('en.sahih', 39, 37, 'And whoever Allah guides - for him there is no misleader. Is not Allah Exalted in Might and Owner of Retribution?'),
  ('en.sahih', 39, 38, 'And if you asked them, "Who created the heavens and the earth?" they would surely say, "Allah." Say, "Then have you considered what you invoke besides Allah? If Allah intended me harm, are they removers of His harm; or if He intended me mercy, are they withholders of His mercy?" Say, "Sufficient for me is Allah; upon Him [alone] rely the [wise] reliers."'),
  ('en.sahih', 39, 39, 'Say, "O my people, work according to your position, [for] indeed, I am working; and you are going to know'),
  ('en.sahih', 39, 40, 'To whom will come a torment disgracing him and on whom will descend an enduring punishment."'),
  ('en.sahih', 39, 41, 'Indeed, We sent down to you the Book for the people in truth. So whoever is guided - it is for [the benefit of] his soul; and whoever goes astray only goes astray to its detriment. And you are not a manager over them.'),
  ('en.sahih', 39, 42, 'Allah takes the souls at the time of their death, and those that do not die [He takes] during their sleep. Then He keeps those for which He has decreed death and releases the others for a specified term. Indeed in that are signs for a people who give thought.'),
  ('en.sahih', 39, 43, 'Or have they taken other than Allah as intercessors? Say, "Even though they do not possess [power over] anything, nor do they reason?"'),
  ('en.sahih', 39, 44, 'Say, "To Allah belongs [the right to allow] intercession entirely. To Him belongs the dominion of the heavens and the earth. Then to Him you will be returned."'),
  ('en.sahih', 39, 45, 'And when Allah is mentioned alone, the hearts of those who do not believe in the Hereafter shrink with aversion, but when those [worshipped] other than Him are mentioned, immediately they rejoice.'),
  ('en.sahih', 39, 46, 'Say, "O Allah, Creator of the heavens and the earth, Knower of the unseen and the witnessed, You will judge between your servants concerning that over which they used to differ."'),
  ('en.sahih', 39, 47, 'And if those who did wrong had all that is in the earth entirely and the like of it with it, they would [attempt to] ransom themselves thereby from the worst of the punishment on the Day of Resurrection. And there will appear to them from Allah that which they had not taken into account.'),
  ('en.sahih', 39, 48, 'And there will appear to them the evils they had earned, and they will be enveloped by what they used to ridicule.'),
  ('en.sahih', 39, 49, 'And when adversity touches man, he calls upon Us; then when We bestow on him a favor from Us, he says, "I have only been given it because of [my] knowledge." Rather, it is a trial, but most of them do not know.'),
  ('en.sahih', 39, 50, 'Those before them had already said it, but they were not availed by what they used to earn.'),
  ('en.sahih', 39, 51, 'And the evil consequences of what they earned struck them. And those who have wronged of these [people] will be afflicted by the evil consequences of what they earned; and they will not cause failure.'),
  ('en.sahih', 39, 52, 'Do they not know that Allah extends provision for whom He wills and restricts [it]? Indeed in that are signs for a people who believe.'),
  ('en.sahih', 39, 53, 'Say, "O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful."'),
  ('en.sahih', 39, 54, 'And return [in repentance] to your Lord and submit to Him before the punishment comes upon you; then you will not be helped.'),
  ('en.sahih', 39, 55, 'And follow the best of what was revealed to you from your Lord before the punishment comes upon you suddenly while you do not perceive,'),
  ('en.sahih', 39, 56, 'Lest a soul should say, "Oh [how great is] my regret over what I neglected in regard to Allah and that I was among the mockers."'),
  ('en.sahih', 39, 57, 'Or [lest] it say, "If only Allah had guided me, I would have been among the righteous."'),
  ('en.sahih', 39, 58, 'Or [lest] it say when it sees the punishment, "If only I had another turn so I could be among the doers of good."'),
  ('en.sahih', 39, 59, 'But yes, there had come to you My verses, but you denied them and were arrogant, and you were among the disbelievers.'),
  ('en.sahih', 39, 60, 'And on the Day of Resurrection you will see those who lied about Allah [with] their faces blackened. Is there not in Hell a residence for the arrogant?'),
  ('en.sahih', 39, 61, 'And Allah will save those who feared Him by their attainment; no evil will touch them, nor will they grieve.'),
  ('en.sahih', 39, 62, 'Allah is the Creator of all things, and He is, over all things, Disposer of affairs.'),
  ('en.sahih', 39, 63, 'To Him belong the keys of the heavens and the earth. And they who disbelieve in the verses of Allah - it is those who are the losers.'),
  ('en.sahih', 39, 64, 'Say, [O Muhammad], "Is it other than Allah that you order me to worship, O ignorant ones?"'),
  ('en.sahih', 39, 65, 'And it was already revealed to you and to those before you that if you should associate [anything] with Allah, your work would surely become worthless, and you would surely be among the losers."'),
  ('en.sahih', 39, 66, 'Rather, worship [only] Allah and be among the grateful.'),
  ('en.sahih', 39, 67, 'They have not appraised Allah with true appraisal, while the earth entirely will be [within] His grip on the Day of Resurrection, and the heavens will be folded in His right hand. Exalted is He and high above what they associate with Him.'),
  ('en.sahih', 39, 68, 'And the Horn will be blown, and whoever is in the heavens and whoever is on the earth will fall dead except whom Allah wills. Then it will be blown again, and at once they will be standing, looking on.'),
  ('en.sahih', 39, 69, 'And the earth will shine with the light of its Lord, and the record [of deeds] will be placed, and the prophets and the witnesses will be brought, and it will be judged between them in truth, and they will not be wronged.'),
  ('en.sahih', 39, 70, 'And every soul will be fully compensated [for] what it did; and He is most knowing of what they do.'),
  ('en.sahih', 39, 71, 'And those who disbelieved will be driven to Hell in groups until, when they reach it, its gates are opened and its keepers will say, "Did there not come to you messengers from yourselves, reciting to you the verses of your Lord and warning you of the meeting of this Day of yours?" They will say, "Yes, but the word of punishment has come into effect upon the disbelievers.'),
  ('en.sahih', 39, 72, '[To them] it will be said, "Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."'),
  ('en.sahih', 39, 73, 'But those who feared their Lord will be driven to Paradise in groups until, when they reach it while its gates have been opened and its keepers say, "Peace be upon you; you have become pure; so enter it to abide eternally therein," [they will enter].'),
  ('en.sahih', 39, 74, 'And they will say, "Praise to Allah, who has fulfilled for us His promise and made us inherit the earth [so] we may settle in Paradise wherever we will. And excellent is the reward of [righteous] workers."'),
  ('en.sahih', 39, 75, 'And you will see the angels surrounding the Throne, exalting [Allah] with praise of their Lord. And it will be judged between them in truth, and it will be said, "[All] praise to Allah, Lord of the worlds."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 39, 1, 'কিতাব অবতীর্ণ হয়েছে পরাক্রমশালী, প্রজ্ঞাময় আল্লাহর পক্ষ থেকে।'),
  ('bn.bengali', 39, 2, 'আমি আপনার প্রতি এ কিতাব যথার্থরূপে নাযিল করেছি। অতএব, আপনি নিষ্ঠার সাথে আল্লাহর এবাদত করুন।'),
  ('bn.bengali', 39, 3, 'জেনে রাখুন, নিষ্ঠাপূর্ণ এবাদত আল্লাহরই নিমিত্ত। যারা আল্লাহ ব্যতীত অপরকে উপাস্যরূপে গ্রহণ করে রেখেছে এবং বলে যে, আমরা তাদের এবাদত এ জন্যেই করি, যেন তারা আমাদেরকে আল্লাহর নিকটবর্তী করে দেয়। নিশ্চয় আল্লাহ তাদের মধ্যে তাদের পারস্পরিক বিরোধপূর্ণ বিষয়ের ফয়সালা করে দেবেন। আল্লাহ মিথ্যাবাদী কাফেরকে সৎপথে পরিচালিত করেন না।'),
  ('bn.bengali', 39, 4, 'আল্লাহ যদি সন্তান গ্রহণ করার ইচ্ছা করতেন, তবে তাঁর সৃষ্টির মধ্য থেকে যা কিছু ইচ্ছা মনোনীত করতেন, তিনি পবিত্র। তিনি আল্লাহ, এক পরাক্রমশালী।'),
  ('bn.bengali', 39, 5, 'তিনি আসমান ও যমীন সৃষ্টি করেছেন যথাযথভাবে। তিনি রাত্রিকে দিবস দ্বারা আচ্ছাদিত করেন এবং দিবসকে রাত্রি দ্বারা আচ্ছাদিত করেন এবং তিনি সুর্য ও চন্দ্রকে কাজে নিযুক্ত করেছেন প্রত্যেকেই বিচরণ করে নির্দিষ্ট সময়কাল পর্যন্ত। জেনে রাখুন, তিনি পরাক্রমশালী, ক্ষমাশীল।'),
  ('bn.bengali', 39, 6, 'তিনি সৃষ্টি করেছেন তোমাদেরকে একই ব্যক্তি থেকে। অতঃপর তা থেকে তার যুগল সৃষ্টি করেছেন এবং তিনি তোমাদের জন্যে আট প্রকার চতুষ্পদ জন্তু অবতীর্ণ করেছেন। তিনি তোমাদেরকে সৃষ্টি করেছেন তোমাদের মাতৃগর্ভে পর্যায়ক্রমে একের পর এক ত্রিবিধ অন্ধকারে। তিনি আল্লাহ তোমাদের পালনকর্তা, সাম্রাজ্য তাঁরই। তিনি ব্যতীত কোন উপাস্য নেই। অতএব, তোমরা কোথায় বিভ্রান্ত হচ্ছ?'),
  ('bn.bengali', 39, 7, 'যদি তোমরা অস্বীকার কর, তবে আল্লাহ তোমাদের থেকে বেপরওয়া। তিনি তাঁর বান্দাদের কাফের হয়ে পড়া পছন্দ করেন না। পক্ষান্তরে যদি তোমরা কৃতজ্ঞ হও, তবে তিনি তোমাদের জন্যে তা পছন্দ করেন। একের পাপ ভার অন্যে বহন করবে না। অতঃপর তোমরা তোমাদের পালনকর্তার কাছে ফিরে যাবে। তিনি তোমাদেরকে তোমাদের কর্ম সম্বন্ধে অবহিত করবেন। নিশ্চয় তিনি অন্তরের বিষয় সম্পর্কেও অবগত।'),
  ('bn.bengali', 39, 8, 'যখন মানুষকে দুঃখ-কষ্ট স্পর্শ করে, তখন সে একাগ্রচিত্তে তার পালনকর্তাকে ডাকে, অতঃপর তিনি যখন তাকে নেয়ামত দান করেন, তখন সে কষ্টের কথা বিস্মৃত হয়ে যায়, যার জন্যে পূর্বে ডেকেছিল এবং আল্লাহর সমকক্ষ স্থির করে; যাতে করে অপরকে আল্লাহর পথ থেকে বিভ্রান্ত করে। বলুন, তুমি তোমার কুফর সহকারে কিছুকাল জীবনোপভোগ করে নাও। নিশ্চয় তুমি জাহান্নামীদের অন্তর্ভূক্ত।'),
  ('bn.bengali', 39, 9, 'যে ব্যক্তি রাত্রিকালে সেজদার মাধ্যমে অথবা দাঁড়িয়ে এবাদত করে, পরকালের আশংকা রাখে এবং তার পালনকর্তার রহমত প্রত্যাশা করে, সে কি তার সমান, যে এরূপ করে না; বলুন, যারা জানে এবং যারা জানে না; তারা কি সমান হতে পারে? চিন্তা-ভাবনা কেবল তারাই করে, যারা বুদ্ধিমান।'),
  ('bn.bengali', 39, 10, 'বলুন, হে আমার বিশ্বাসী বান্দাগণ! তোমরা তোমাদের পালনকর্তাকে ভয় কর। যারা এ দুনিয়াতে সৎকাজ করে, তাদের জন্যে রয়েছে পুণ্য। আল্লাহর পৃথিবী প্রশস্ত। যারা সবরকারী, তারাই তাদের পুরস্কার পায় অগণিত।'),
  ('bn.bengali', 39, 11, 'বলুন, আমি নিষ্ঠার সাথে আল্লাহর এবাদত করতে আদিষ্ট হয়েছি।'),
  ('bn.bengali', 39, 12, 'আরও আদিষ্ট হয়েছি, সর্ব প্রথম নির্দেশ পালনকারী হওয়ার জন্যে।'),
  ('bn.bengali', 39, 13, 'বলুন, আমি আমার পালনকর্তার অবাধ্য হলে এক মহাদিবসের শাস্তির ভয় করি।'),
  ('bn.bengali', 39, 14, 'বলুন, আমি নিষ্ঠার সাথে আল্লাহ তা’আলারই এবাদত করি।'),
  ('bn.bengali', 39, 15, 'অতএব, তোমরা আল্লাহর পরিবর্তে যার ইচ্ছা তার এবাদত কর। বলুন, কেয়ামতের দিন তারাই বেশী ক্ষতিগ্রস্ত হবে, যারা নিজেদের ও পরিবারবর্গের তরফ থেকে ক্ষতিগ্রস্ত হবে। জেনে রাখ, এটাই সুস্পষ্ট ক্ষতি।'),
  ('bn.bengali', 39, 16, 'তাদের জন্যে উপর দিক থেকে এবং নীচের দিক থেকে আগুনের মেঘমালা থাকবে। এ শাস্তি দ্বারা আল্লাহ তাঁর বান্দাদেরকে সতর্ক করেন যে, হে আমার বান্দাগণ, আমাকে ভয় কর।'),
  ('bn.bengali', 39, 17, 'যারা শয়তানী শক্তির পূজা-অর্চনা থেকে দূরে থাকে এবং আল্লাহ অভিমুখী হয়, তাদের জন্যে রয়েছে সুসংবাদ। অতএব, সুসংবাদ দিন আমার বান্দাদেরকে।'),
  ('bn.bengali', 39, 18, 'যারা মনোনিবেশ সহকারে কথা শুনে, অতঃপর যা উত্তম, তার অনুসরণ করে। তাদেরকেই আল্লাহ সৎপথ প্রদর্শন করেন এবং তারাই বুদ্ধিমান।'),
  ('bn.bengali', 39, 19, 'যার জন্যে শাস্তির হুকুম অবধারিত হয়ে গেছে আপনি কি সে জাহান্নামীকে মুক্ত করতে পারবেন?'),
  ('bn.bengali', 39, 20, 'কিন্তু যারা তাদের পালনকর্তাকে ভয় করে, তাদের জন্যে নির্মিত রয়েছে প্রাসাদের উপর প্রাসাদ। এগুলোর তলদেশে নদী প্রবাহিত। আল্লাহ প্রতিশ্রুতি দিয়েছেন। আল্লাহ প্রতিশ্রুতির খেলাফ করেন না।'),
  ('bn.bengali', 39, 21, 'তুমি কি দেখনি যে, আল্লাহ আকাশ থেকে পানি বর্ষণ করেছেন, অতঃপর সে পানি যমীনের ঝর্ণাসমূহে প্রবাহিত করেছেন, এরপর তদ্দ্বারা বিভিন্ন রঙের ফসল উৎপন্ন করেন, অতঃপর তা শুকিয়ে যায়, ফলে তোমরা তা পীতবর্ণ দেখতে পাও। এরপর আল্লাহ তাকে খড়-কুটায় পরিণত করে দেন। নিশ্চয় এতে বুদ্ধিমানদের জন্যে উপদেশ রয়েছে।'),
  ('bn.bengali', 39, 22, 'আল্লাহ যার বক্ষ ইসলামের জন্যে উম্মুক্ত করে দিয়েছেন, অতঃপর সে তার পালনকর্তার পক্ষ থেকে আগত আলোর মাঝে রয়েছে। (সে কি তার সমান, যে এরূপ নয়) যাদের অন্তর আল্লাহ স্মরণের ব্যাপারে কঠোর, তাদের জন্যে দূর্ভোগ। তারা সুস্পষ্ঠ গোমরাহীতে রয়েছে।'),
  ('bn.bengali', 39, 23, 'আল্লাহ উত্তম বাণী তথা কিতাব নাযিল করেছেন, যা সামঞ্জস্যপূর্ণ, পূনঃ পূনঃ পঠিত। এতে তাদের লোম কাঁটা দিয়ে উঠে চামড়ার উপর, যারা তাদের পালনকর্তাকে ভয় করে, এরপর তাদের চামড়া ও অন্তর আল্লাহর স্মরণে বিনম্র হয়। এটাই আল্লাহর পথ নির্দেশ, এর মাধ্যমে আল্লাহ যাকে ইচ্ছা পথ প্রদর্শন করেন। আর আল্লাহ যাকে গোমরাহ করেন, তার কোন পথপ্রদর্শক নেই।'),
  ('bn.bengali', 39, 24, 'যে ব্যক্তি কেয়ামতের দিন তার মুখ দ্বারা অশুভ আযাব ঠেকাবে এবং এরূপ জালেমদেরকে বলা হবে, তোমরা যা করতে তার স্বাদ আস্বাদন কর,-সে কি তার সমান, যে এরূপ নয়?'),
  ('bn.bengali', 39, 25, 'তাদের পূর্ববর্তীরাও মিথ্যারোপ করেছিল, ফলে তাদের কাছে আযাব এমনভাবে আসল, যা তারা কল্পনাও করত না।'),
  ('bn.bengali', 39, 26, 'অতঃপর আল্লাহ তাদেরকে পার্থিব জীবনে লাঞ্ছনার স্বাদ আস্বাদন করালেন, আর পরকালের আযাব হবে আরও গুরুতর, যদি তারা জানত!'),
  ('bn.bengali', 39, 27, 'আমি এ কোরআনে মানুষের জন্যে সব দৃষ্টান্তই বর্ণনা করেছি, যাতে তারা অনুধাবন করে;'),
  ('bn.bengali', 39, 28, 'আরবী ভাষায় এ কোরআন বক্রতামুক্ত, যাতে তারা সাবধান হয়ে চলে।'),
  ('bn.bengali', 39, 29, 'আল্লাহ এক দৃষ্টান্ত বর্ণনা করেছেনঃ একটি লোকের উপর পরস্পর বিরোধী কয়জন মালিক রয়েছে, আরেক ব্যক্তির প্রভু মাত্র একজন-তাদের উভয়ের অবস্থা কি সমান? সমস্ত প্রশংসা আল্লাহর। কিন্তু তাদের অধিকাংশই জানে না।'),
  ('bn.bengali', 39, 30, 'নিশ্চয় তোমারও মৃত্যু হবে এবং তাদেরও মৃত্যু হবে।'),
  ('bn.bengali', 39, 31, 'অতঃপর কেয়ামতের দিন তোমরা সবাই তোমাদের পালনকর্তার সামনে কথা কাটাকাটি করবে।'),
  ('bn.bengali', 39, 32, 'যে ব্যক্তি আল্লাহর বিরুদ্ধে মিথ্যা বলে এবং তার কাছে সত্য আগমন করার পর তাকে মিথ্যা সাব্যস্ত করে, তার চেয়ে অধিক যালেম আর কে হবে? কাফেরদের বাসস্থান জাহান্নামে নয় কি?'),
  ('bn.bengali', 39, 33, 'যারা সত্য নিয়ে আগমন করছে এবং সত্যকে সত্য মেনে নিয়েছে; তারাই তো খোদাভীরু।'),
  ('bn.bengali', 39, 34, 'তাদের জন্যে পালনকর্তার কাছে তাই রয়েছে, যা তারা চাইবে। এটা সৎকর্মীদের পুরস্কার।'),
  ('bn.bengali', 39, 35, 'যাতে আল্লাহ তাদের মন্দ কর্মসমূহ মার্জনা করেন এবং তাদের উত্তম কর্মের পুরস্কার তাদেরকে দান করেন।'),
  ('bn.bengali', 39, 36, 'আল্লাহ কি তাঁর বান্দার পক্ষে যথেষ্ট নন? অথচ তারা আপনাকে আল্লাহর পরিবর্তে অন্যান্য উপাস্যদের ভয় দেখায়। আল্লাহ যাকে গোমরাহ করেন, তার কোন পথপ্রদর্শক নেই।'),
  ('bn.bengali', 39, 37, 'আর আল্লাহ যাকে পথপ্রদর্শন করেন, তাকে পথভ্রষ্টকারী কেউ নেই। আল্লাহ কি পরাক্রমশালী, প্রতিশোধ গ্রহণকারী নন?'),
  ('bn.bengali', 39, 38, 'যদি আপনি তাদেরকে জিজ্ঞেস করেন, আসমান ও যমীন কে সৃষ্টি করেছে? তারা অবশ্যই বলবে-আল্লাহ। বলুন, তোমরা ভেবে দেখেছ কি, যদি আল্লাহ আমার অনিষ্ট করার ইচ্ছা করেন, তবে তোমরা আল্লাহ ব্যতীত যাদেরকে ডাক, তারা কি সে অনিষ্ট দূর করতে পারবে? অথবা তিনি আমার প্রতি রহমত করার ইচ্ছা করলে তারা কি সে রহমত রোধ করতে পারবে? বলুন, আমার পক্ষে আল্লাহই যথেষ্ট। নির্ভরকারীরা তাঁরই উপর নির্ভর করে।'),
  ('bn.bengali', 39, 39, 'বলুন, হে আমার কওম, তোমরা তোমাদের জায়গায় কাজ কর, আমিও কাজ করছি। সত্ত্বরই জানতে পারবে।'),
  ('bn.bengali', 39, 40, 'কার কাছে অবমাননাকর আযাব এবং চিরস্থায়ী শাস্তি নেমে আসে।'),
  ('bn.bengali', 39, 41, 'আমি আপনার প্রতি সত্য ধর্মসহ কিতাব নাযিল করেছি মানুষের কল্যাণকল্পে। অতঃপর যে সৎপথে আসে, সে নিজের কল্যাণের জন্যেই আসে, আর যে পথভ্রষ্ট হয়, সে নিজেরই অনিষ্টের জন্যে পথভ্রষ্ট হয়। আপনি তাদের জন্যে দায়ী নন।'),
  ('bn.bengali', 39, 42, 'আল্লাহ মানুষের প্রাণ হরণ করেন তার মৃত্যুর সময়, আর যে মরে না, তার নিদ্রাকালে। অতঃপর যার মৃত্যু অবধারিত করেন, তার প্রাণ ছাড়েন না এবং অন্যান্যদের ছেড়ে দেন এক নির্দিষ্ট সময়ের জন্যে। নিশ্চয় এতে চিন্তাশীল লোকদের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 39, 43, 'তারা কি আল্লাহ ব্যতীত সুপারিশকারী গ্রহণ করেছে? বলুন, তাদের কোন এখতিয়ার না থাকলেও এবং তারা না বুঝলেও?'),
  ('bn.bengali', 39, 44, 'বলুন, সমস্ত সুপারিশ আল্লাহরই ক্ষমতাধীন, আসমান ও যমীনে তাঁরই সাম্রাজ্য। অতঃপর তাঁরই কাছে তোমরা প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 39, 45, 'যখন খাঁটিভাবে আল্লাহর নাম উচ্চারণ করা হয়, তখন যারা পরকালে বিশ্বাস করে না, তাদের অন্তর সংকুচিত হয়ে যায়, আর যখন আল্লাহ ব্যতীত অন্য উপাস্যদের নাম উচ্চারণ করা হয়, তখন তারা আনন্দে উল্লসিত হয়ে উঠে।'),
  ('bn.bengali', 39, 46, 'বলুন, হে আল্লাহ আসমান ও যমীনের স্রষ্টা, দৃশ্য ও অদৃশ্যের জ্ঞানী, আপনিই আপনার বান্দাদের মধ্যে ফয়সালা করবেন, যে বিষয়ে তারা মত বিরোধ করত।'),
  ('bn.bengali', 39, 47, 'যদি গোনাহগারদের কাছে পৃথিবীর সবকিছু থাকে এবং তার সাথে সমপরিমাণ আরও থাকে, তবে অবশ্যই তারা কেয়ামতের দিন সে সবকিছুই নিস্কৃতি পাওয়ার জন্যে মুক্তিপন হিসেবে দিয়ে দেবে। অথচ তারা দেখতে পাবে, আল্লাহর পক্ষ থেকে এমন শাস্তি, যা তারা কল্পনাও করত না।'),
  ('bn.bengali', 39, 48, 'আর দেখবে, তাদের দুস্কর্মসমূহ এবং যে বিষয়ে তারা ঠাট্টা-বিদ্রুপ করত, তা তাদেরকে ঘিরে নেবে।'),
  ('bn.bengali', 39, 49, 'মানুষকে যখন দুঃখ-কষ্ট স্পর্শ করে, তখন সে আমাকে ডাকতে শুরু করে, এরপর আমি যখন তাকে আমার পক্ষ থেকে নেয়ামত দান করি, তখন সে বলে, এটা তো আমি পূর্বের জানা মতেই প্রাপ্ত হয়েছি। অথচ এটা এক পরীক্ষা, কিন্তু তাদের অধিকাংশই বোঝে না।'),
  ('bn.bengali', 39, 50, 'তাদের পূর্ববর্তীরাও তাই বলত, অতঃপর তাদের কৃতকর্ম তাদের কোন উপকারে আসেনি।'),
  ('bn.bengali', 39, 51, 'তাদের দুস্কর্ম তাদেরকে বিপদে ফেলেছে, এদের মধ্যেও যারা পাপী, তাদেরকেও অতি সত্ত্বর তাদের দুস্কর্ম বিপদে ফেলবে। তারা তা প্রতিহত করতে সক্ষম হবে না।'),
  ('bn.bengali', 39, 52, 'তারা কি জানেনি যে, আল্লাহ যার জন্যে ইচ্ছা রিযিক বৃদ্ধি করেন এবং পরিমিত দেন। নিশ্চয় এতে বিশ্বাসী সম্প্রদায়ের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 39, 53, 'বলুন, হে আমার বান্দাগণ যারা নিজেদের উপর যুলুম করেছ তোমরা আল্লাহর রহমত থেকে নিরাশ হয়ো না। নিশ্চয় আল্লাহ সমস্ত গোনাহ মাফ করেন। তিনি ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 39, 54, 'তোমরা তোমাদের পালনকর্তার অভিমূখী হও এবং তাঁর আজ্ঞাবহ হও তোমাদের কাছে আযাব আসার পূর্বে। এরপর তোমরা সাহায্যপ্রাপ্ত হবে না;'),
  ('bn.bengali', 39, 55, 'তোমাদের প্রতি অবতীর্ণ উত্তম বিষয়ের অনুসরণ কর তোমাদের কাছে অতর্কিতে ও অজ্ঞাতসারে আযাব আসার পূর্বে,'),
  ('bn.bengali', 39, 56, 'যাতে কেউ না বলে, হায়, হায়, আল্লাহ সকাশে আমি কর্তব্যে অবহেলা করেছি এবং আমি ঠাট্টা-বিদ্রুপকারীদের অন্তর্ভূক্ত ছিলাম।'),
  ('bn.bengali', 39, 57, 'অথবা না বলে, আল্লাহ যদি আমাকে পথপ্রদর্শন করতেন, তবে অবশ্যই আমি পরহেযগারদের একজন হতাম।'),
  ('bn.bengali', 39, 58, 'অথবা আযাব প্রত্যক্ষ করার সময় না বলে, যদি কোনরূপে একবার ফিরে যেতে পারি, তবে আমি সৎকর্মপরায়ণ হয়ে যাব।'),
  ('bn.bengali', 39, 59, 'হাঁ, তোমার কাছে আমার নির্দেশ এসেছিল; অতঃপর তুমি তাকে মিথ্যা বলেছিলে, অহংকার করেছিলে এবং কাফেরদের অন্তর্ভূক্ত হয়ে গিয়েছিলে।'),
  ('bn.bengali', 39, 60, 'যারা আল্লাহর প্রতি মিথ্যা আরোপ করে, কেয়ামতের দিন আপনি তাদের মুখ কাল দেখবেন। অহংকারীদের আবাসস্থল জাহান্নামে নয় কি?'),
  ('bn.bengali', 39, 61, 'আর যারা শিরক থেকে বেঁচে থাকত, আল্লাহ তাদেরকে সাফল্যের সাথে মুক্তি দেবেন, তাদেরকে অনিষ্ট স্পর্শ করবে না এবং তারা চিন্তিতও হবে না।'),
  ('bn.bengali', 39, 62, 'আল্লাহ সর্বকিছুর স্রষ্টা এবং তিনি সবকিছুর দায়িত্ব গ্রহণ করেন।'),
  ('bn.bengali', 39, 63, 'আসমান ও যমীনের চাবি তাঁরই নিকট। যারা আল্লাহর আয়াতসমূহকে অস্বীকার করে, তারাই ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 39, 64, 'বলুন, হে মুর্খরা, তোমরা কি আমাকে আল্লাহ ব্যতীত অন্যের এবাদত করতে আদেশ করছ?'),
  ('bn.bengali', 39, 65, 'আপনার প্রতি এবং আপনার পূর্ববর্তীদের পতি প্রত্যাদেশ হয়েছে, যদি আল্লাহর শরীক স্থির করেন, তবে আপনার কর্ম নিষ্ফল হবে এবং আপনি ক্ষতিগ্রস্তদের একজন হবেন।'),
  ('bn.bengali', 39, 66, 'বরং আল্লাহরই এবাদত করুন এবং কৃতজ্ঞদের অন্তর্ভুক্ত থাকুন।'),
  ('bn.bengali', 39, 67, 'তারা আল্লাহকে যথার্থরূপে বোঝেনি। কেয়ামতের দিন গোটা পৃথিবী থাকবে তাঁর হাতের মুঠোতে এবং আসমান সমূহ ভাঁজ করা অবস্থায় থাকবে তাঁর ডান হাতে। তিনি পবিত্র। আর এরা যাকে শরীক করে, তা থেকে তিনি অনেক উর্ধ্বে।'),
  ('bn.bengali', 39, 68, 'শিংগায় ফুঁক দেয়া হবে, ফলে আসমান ও যমীনে যারা আছে সবাই বেহুঁশ হয়ে যাবে, তবে আল্লাহ যাকে ইচ্ছা করেন। অতঃপর আবার শিংগায় ফুঁক দেয়া হবে, তৎক্ষণাৎ তারা দন্ডায়মান হয়ে দেখতে থাকবে।'),
  ('bn.bengali', 39, 69, 'পৃথিবী তার পালনকর্তার নূরে উদ্ভাসিত হবে, আমলনামা স্থাপন করা হবে, পয়গম্বরগণ ও সাক্ষীগণকে আনা হবে এবং সকলের মধ্যে ন্যায় বিচার করা হবে-তাদের প্রতি জুলুম করা হবে না।'),
  ('bn.bengali', 39, 70, 'প্রত্যেকে যা করেছে, তার পূর্ণ প্রতিফল দেয়া হবে। তারা যা কিছু করে, সে সম্পর্কে আল্লাহ সম্যক অবগত।'),
  ('bn.bengali', 39, 71, 'কাফেরদেরকে জাহান্নামের দিকে দলে দলে হাঁকিয়ে নেয়া হবে। তারা যখন সেখানে পৌছাবে, তখন তার দরজাসমূহ খুলে দেয়া হবে এবং জাহান্নামের রক্ষীরা তাদেরকে বলবে, তোমাদের কাছে কি তোমাদের মধ্য থেকে পয়গম্বর আসেনি, যারা তোমাদের কাছে তোমাদের পালনকর্তার আয়াতসমূহ আবৃত্তি করত এবং সতর্ক করত এ দিনের সাক্ষাতের ব্যাপারে? তারা বলবে, হঁ্যা, কিন্তু কাফেরদের প্রতি শাস্তির হুকুমই বাস্তবায়িত হয়েছে।'),
  ('bn.bengali', 39, 72, 'বলা হবে, তোমরা জাহান্নামের দরজা দিয়ে প্রবেশ কর, সেখানে চিরকাল অবস্থানের জন্যে। কত নিকৃষ্ট অহংকারীদের আবাসস্থল।'),
  ('bn.bengali', 39, 73, 'যারা তাদের পালনকর্তাকে ভয় করত তাদেরকে দলে দলে জান্নাতের দিকে নিয়ে যাওয়া হবে। যখন তারা উম্মুক্ত দরজা দিয়ে জান্নাতে পৌছাবে এবং জান্নাতের রক্ষীরা তাদেরকে বলবে, তোমাদের প্রতি সালাম, তোমরা সুখে থাক, অতঃপর সদাসর্বদা বসবাসের জন্যে তোমরা জান্নাতে প্রবেশ কর।'),
  ('bn.bengali', 39, 74, 'তারা বলবে, সমস্ত প্রশংসা আল্লাহর, যিনি আমাদের প্রতি তাঁর ওয়াদা পূর্ণ করেছেন এবং আমাদেরকে এ ভূমির উত্তরাধিকারী করেছেন। আমরা জান্নাতের যেখানে ইচ্ছা বসবাস করব। মেহনতকারীদের পুরস্কার কতই চমৎকার।'),
  ('bn.bengali', 39, 75, 'আপনি ফেরেশতাগণকে দেখবেন, তারা আরশের চার পাশ ঘিরে তাদের পালনকর্তার পবিত্রতা ঘোষনা করছে। তাদের সবার মাঝে ন্যায় বিচার করা হবে। বলা হবে, সমস্ত প্রশংসা বিশ্বপালক আল্লাহর।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 39, 1, 'The revelation of the Scripture is from Allah, the Mighty, the Wise.'),
  ('en.pickthall', 39, 2, 'Lo! We have revealed the Scripture unto thee (Muhammad) with truth; so worship Allah, making religion pure for Him (only).'),
  ('en.pickthall', 39, 3, 'Surely pure religion is for Allah only. And those who choose protecting friends beside Him (say): We worship them only that they may bring us near unto Allah. Lo! Allah will judge between them concerning that wherein they differ. Lo! Allah guideth not him who is a liar, an ingrate.'),
  ('en.pickthall', 39, 4, 'If Allah had willed to choose a son, He could have chosen what He would of that which He hath created. Be He Glorified! He is Allah, the One, the Absolute.'),
  ('en.pickthall', 39, 5, 'He hath created the heavens and the earth with truth. He maketh night to succeed day, and He maketh day to succeed night, and He constraineth the sun and the moon to give service, each running on for an appointed term. Is not He the Mighty, the Forgiver?'),
  ('en.pickthall', 39, 6, 'He created you from one being, then from that (being) He made its mate; and He hath provided for you of cattle eight kinds. He created you in the wombs of your mothers, creation after creation, in a threefold gloom. Such is Allah, your Lord. His is the Sovereignty. There is no Allah save Him. How then are ye turned away?'),
  ('en.pickthall', 39, 7, 'If ye are thankless, yet Allah is Independent of you, though He is not pleased with thanklessness for His bondmen; and if ye are thankful He is pleased therewith for you. No laden soul will bear another\'s load. Then unto your Lord is your return; and He will tell you what ye used to do. Lo! He knoweth what is in the breasts (of men).'),
  ('en.pickthall', 39, 8, 'And when some hurt toucheth man, he crieth unto his Lord, turning unto Him (repentant). Then, when He granteth him a boon from Him he forgetteth that for which he cried unto Him before, and setteth up rivals to Allah that he may beguile (men) from his way. Say (O Muhammad, unto such an one): Take pleasure in thy disbelief a while. Lo! thou art of the owners of the Fire.'),
  ('en.pickthall', 39, 9, 'Is he who payeth adoration in the watches of the night, prostrate and standing, bewaring of the Hereafter and hoping for the mercy of his Lord, (to be accounted equal with a disbeliever)? Say (unto them, O Muhammad): Are those who know equal with those who know not? But only men of understanding will pay heed.'),
  ('en.pickthall', 39, 10, 'Say: O My bondmen who believe! Observe your duty to your Lord. For those who do good in this world there is good, and Allah\'s earth is spacious. Verily the steadfast will be paid their wages without stint.'),
  ('en.pickthall', 39, 11, 'Say (O Muhammad): Lo! I am commanded to worship Allah, making religion pure for Him (only).'),
  ('en.pickthall', 39, 12, 'And I am commanded to be the first of those who are muslims (surrender unto Him).'),
  ('en.pickthall', 39, 13, 'Say: Lo! if I should disobey my Lord, I fear the doom of a tremendous Day.'),
  ('en.pickthall', 39, 14, 'Say: Allah I worship, making my religion pure for Him (only).'),
  ('en.pickthall', 39, 15, 'Then worship what ye will beside Him. Say: The losers will be those who lose themselves and their housefolk on the Day of Resurrection. Ah, that will be the manifest loss!'),
  ('en.pickthall', 39, 16, 'They have an awning of fire above them and beneath them a dais (of fire). With this doth Allah appal His bondmen. O My bondmen, therefor fear Me!'),
  ('en.pickthall', 39, 17, 'And those who put away false gods lest they should worship them and turn to Allah in repentance, for them there are glad tidings. Therefor give good tidings (O Muhammad) to My bondmen'),
  ('en.pickthall', 39, 18, 'Who hear advice and follow the best thereof. Such are those whom Allah guideth, and such are men of understanding.'),
  ('en.pickthall', 39, 19, 'Is he on whom the word of doom is fulfilled (to be helped), and canst thou (O Muhammad) rescue him who is in the Fire?'),
  ('en.pickthall', 39, 20, 'But those who keep their duty to their Lord, for them are lofty halls with lofty halls above them, built (for them), beneath which rivers flow. (It is) a promise of Allah. Allah faileth not His promise.'),
  ('en.pickthall', 39, 21, 'Hast thou not seen how Allah hath sent down water from the sky and hath caused it to penetrate the earth as watersprings, and afterward thereby produceth crops of divers hues; and afterward they wither and thou seest them turn yellow; then He maketh them chaff. Lo! herein verily is a reminder for men of understanding.'),
  ('en.pickthall', 39, 22, 'Is he whose bosom Allah hath expanded for Al-Islam, so that he followeth a light from his Lord, (as he who disbelieveth)? Then woe unto those whose hearts are hardened against remembrance of Allah. Such are in plain error.'),
  ('en.pickthall', 39, 23, 'Allah hath (now) revealed the fairest of statements, a Scripture consistent, (wherein promises of reward are) paired (with threats of punishment), whereat doth creep the flesh of those who fear their Lord, so that their flesh and their hearts soften to Allah\'s reminder. Such is Allah\'s guidance, wherewith He guideth whom He will. And him whom Allah sendeth astray, for him there is no guide.'),
  ('en.pickthall', 39, 24, 'Is he then, who will strike his face against the awful doom upon the Day of Resurrection (as he who doeth right)? And it will be said unto the wrong-doers: Taste what ye used to earn.'),
  ('en.pickthall', 39, 25, 'Those before them denied, and so the doom came on them whence they knew not.'),
  ('en.pickthall', 39, 26, 'Thus Allah made them taste humiliation in the life of the world, and verily the doom of the Hereafter will be greater if they did but know.'),
  ('en.pickthall', 39, 27, 'And verily We have coined for mankind in this Qur\'an all kinds of similitudes, that haply they may reflect;'),
  ('en.pickthall', 39, 28, 'A Lecture in Arabic, containing no crookedness, that haply they may ward off (evil).'),
  ('en.pickthall', 39, 29, 'Allah coineth a similitude: A man in relation to whom are several part-owners, quarrelling, and a man belonging wholly to one man. Are the two equal in similitude? Praise be to Allah! But most of them know not.'),
  ('en.pickthall', 39, 30, 'Lo! thou wilt die, and lo! they will die;'),
  ('en.pickthall', 39, 31, 'Then lo! on the Day of Resurrection, before your Lord ye will dispute.'),
  ('en.pickthall', 39, 32, 'And who doth greater wrong than he who telleth a lie against Allah, and denieth the truth when it reacheth him? Will not the home of disbelievers be in hell?'),
  ('en.pickthall', 39, 33, 'And whoso bringeth the truth and believeth therein - Such are the dutiful.'),
  ('en.pickthall', 39, 34, 'They shall have what they will of their Lord\'s bounty. That is the reward of the good:'),
  ('en.pickthall', 39, 35, 'That Allah will remit from them the worst of what they did, and will pay them for reward the best they used to do.'),
  ('en.pickthall', 39, 36, 'Will not Allah defend His slave? Yet they would frighten thee with those beside Him. He whom Allah sendeth astray, for him there is no guide.'),
  ('en.pickthall', 39, 37, 'And he whom Allah guideth, for him there can be no misleader. Is not Allah Mighty, Able to Requite (the wrong)?'),
  ('en.pickthall', 39, 38, 'And verily, if thou shouldst ask them: Who created the heavens and the earth? they will say: Allah. Say: Bethink you then of those ye worship beside Allah, if Allah willed some hurt for me, could they remove from me His hurt; or if He willed some mercy for me, could they restrain His mercy? Say: Allah is my all. In Him do (all) the trusting put their trust.'),
  ('en.pickthall', 39, 39, 'Say: O my people! Act in your manner. Lo! I (too) am acting. Thus ye will come to know'),
  ('en.pickthall', 39, 40, 'Who it is unto whom cometh a doom that will abase him, and on whom there falleth everlasting doom.'),
  ('en.pickthall', 39, 41, 'Lo! We have revealed unto thee (Muhammad) the Scripture for mankind with truth. Then whosoever goeth right it is for his soul, and whosoever strayeth, strayeth only to its hurt. And thou art not a warder over them.'),
  ('en.pickthall', 39, 42, 'Allah receiveth (men\'s) souls at the time of their death, and that (soul) which dieth not (yet) in its sleep. He keepeth that (soul) for which He hath ordained death and dismisseth the rest till an appointed term. Lo! herein verily are portents for people who take thought.'),
  ('en.pickthall', 39, 43, 'Or choose they intercessors other than Allah? Say: What! Even though they have power over nothing and have no intelligence?'),
  ('en.pickthall', 39, 44, 'Say: Unto Allah belongeth all intercession. His is the Sovereignty of the heavens and the earth. And afterward unto Him ye will be brought back.'),
  ('en.pickthall', 39, 45, 'And when Allah alone is mentioned, the hearts of those who believe not in the Hereafter are repelled, and when those (whom they worship) beside Him are mentioned, behold! they are glad.'),
  ('en.pickthall', 39, 46, 'Say: O Allah! Creator of the heavens and the earth! Knower of the Invisible and the Visible! Thou wilt judge between Thy slaves concerning that wherein they used to differ.'),
  ('en.pickthall', 39, 47, 'And though those who do wrong possess all that is in the earth, and therewith as much again, they verily will seek to ransom themselves therewith on the Day of Resurrection from the awful doom; and there will appear unto them, from their Lord, that wherewith they never reckoned.'),
  ('en.pickthall', 39, 48, 'And the evils that they earned will appear unto them, and that whereat they used to scoff will surround them.'),
  ('en.pickthall', 39, 49, 'Now when hurt toucheth a man he crieth unto Us, and afterward when We have granted him a boon from Us, he saith: Only by force of knowledge I obtained it. Nay, but it is a test. But most of them know not.'),
  ('en.pickthall', 39, 50, 'Those before them said it, yet (all) that they had earned availed them not;'),
  ('en.pickthall', 39, 51, 'But the evils that they earned smote them; and such of these as do wrong, the evils that they earn will smite them; they cannot escape.'),
  ('en.pickthall', 39, 52, 'Know they not that Allah enlargeth providence for whom He will, and straiteneth it (for whom He will). Lo! herein verily are portents for people who believe.'),
  ('en.pickthall', 39, 53, 'Say: O My slaves who have been prodigal to their own hurt! Despair not of the mercy of Allah, Who forgiveth all sins. Lo! He is the Forgiving, the Merciful.'),
  ('en.pickthall', 39, 54, 'Turn unto your Lord repentant, and surrender unto Him, before there come unto you the doom, when ye cannot be helped.'),
  ('en.pickthall', 39, 55, 'And follow the better (guidance) of that which is revealed unto you from your Lord, before the doom cometh on you suddenly when ye know not,'),
  ('en.pickthall', 39, 56, 'Lest any soul should say: Alas, my grief that I was unmindful of Allah, and I was indeed among the scoffers!'),
  ('en.pickthall', 39, 57, 'Or should say: If Allah had but guided me I should have been among the dutiful!'),
  ('en.pickthall', 39, 58, 'Or should say, when it seeth the doom: Oh, that I had but a second chance that I might be among the righteous!'),
  ('en.pickthall', 39, 59, '(But now the answer will be): Nay, for My revelations came unto thee, but thou didst deny them and wast scornful and wast among the disbelievers.'),
  ('en.pickthall', 39, 60, 'And on the Day of Resurrection thou (Muhammad) seest those who lied concerning Allah with their faces blackened. Is not the home of the scorners in hell?'),
  ('en.pickthall', 39, 61, 'And Allah delivereth those who ward off (evil) because of their deserts. Evil toucheth them not, nor do they grieve.'),
  ('en.pickthall', 39, 62, 'Allah is Creator of all things, and He is Guardian over all things.'),
  ('en.pickthall', 39, 63, 'His are the keys of the heavens and the earth, and they who disbelieve the revelations of Allah - such are they who are the losers.'),
  ('en.pickthall', 39, 64, 'Say (O Muhammad, to the disbelievers): Do ye bid me serve other than Allah? O ye fools!'),
  ('en.pickthall', 39, 65, 'And verily it hath been revealed unto thee as unto those before thee (saying): If thou ascribe a partner to Allah thy work will fail and thou indeed wilt be among the losers.'),
  ('en.pickthall', 39, 66, 'Nay, but Allah must thou serve, and be among the thankful!'),
  ('en.pickthall', 39, 67, 'And they esteem not Allah as He hath the right to be esteemed, when the whole earth is His handful on the Day of Resurrection, and the heavens are rolled in His right hand. Glorified is He and High Exalted from all that they ascribe as partner (unto Him).'),
  ('en.pickthall', 39, 68, 'And the trumpet is blown, and all who are in the heavens and all who are in the earth swoon away, save him whom Allah willeth. Then it is blown a second time, and behold them standing waiting!'),
  ('en.pickthall', 39, 69, 'And the earth shineth with the light of her Lord, and the Book is set up, and the prophets and the witnesses are brought, and it is judged between them with truth, and they are not wronged.'),
  ('en.pickthall', 39, 70, 'And each soul is paid in full for what it did. And He is Best Aware of what they do.'),
  ('en.pickthall', 39, 71, 'And those who disbelieve are driven unto hell in troops till, when they reach it and the gates thereof are opened, and the warders thereof say unto them: Came there not unto you messengers of your own, reciting unto you the revelations of your Lord and warning you of the meeting of this your Day? they say: Yea, verily. But the word of doom of disbelievers is fulfilled.'),
  ('en.pickthall', 39, 72, 'It is said (unto them): Enter ye the gates of hell to dwell therein. Thus hapless is the journey\'s end of the scorners.'),
  ('en.pickthall', 39, 73, 'And those who keep their duty to their Lord are driven unto the Garden in troops till, when they reach it, and the gates thereof are opened, and the warders thereof say unto them: Peace be unto you! Ye are good, so enter ye (the Garden of delight), to dwell therein;'),
  ('en.pickthall', 39, 74, 'They say: Praise be to Allah, Who hath fulfilled His promise unto us and hath made us inherit the land, sojourning in the Garden where we will! So bounteous is the wage of workers.'),
  ('en.pickthall', 39, 75, 'And thou (O Muhammad) seest the angels thronging round the Throne, hymning the praises of their Lord. And they are judged aright. And it is said: Praise be to Allah, the Lord of the Worlds!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 39, 1, 'The revelation of this Book is from Allah, the Exalted in Power, full of Wisdom.'),
  ('en.yusufali', 39, 2, 'Verily it is We Who have revealed the Book to thee in Truth: so serve Allah, offering Him sincere devotion.'),
  ('en.yusufali', 39, 3, 'Is it not to Allah that sincere devotion is due? But those who take for protectors other than Allah (say): "We only serve them in order that they may bring us nearer to Allah." Truly Allah will judge between them in that wherein they differ. But Allah guides not such as are false and ungrateful.'),
  ('en.yusufali', 39, 4, 'Had Allah wished to take to Himself a son, He could have chosen whom He pleased out of those whom He doth create: but Glory be to Him! (He is above such things.) He is Allah, the One, the Irresistible.'),
  ('en.yusufali', 39, 5, 'He created the heavens and the earth in true (proportions): He makes the Night overlap the Day, and the Day overlap the Night: He has subjected the sun and the moon (to His law): Each one follows a course for a time appointed. Is not He the Exalted in Power - He Who forgives again and again?'),
  ('en.yusufali', 39, 6, 'He created you (all) from a single person: then created, of like nature, his mate; and he sent down for you eight head of cattle in pairs: He makes you, in the wombs of your mothers, in stages, one after another, in three veils of darkness. such is Allah, your Lord and Cherisher: to Him belongs (all) dominion. There is no god but He: then how are ye turned away (from your true Centre)?'),
  ('en.yusufali', 39, 7, 'If ye reject (Allah), Truly Allah hath no need of you; but He liketh not ingratitude from His servants: if ye are grateful, He is pleased with you. No bearer of burdens can bear the burden of another. In the end, to your Lord is your Return, when He will tell you the truth of all that ye did (in this life). for He knoweth well all that is in (men\'s) hearts.'),
  ('en.yusufali', 39, 8, 'When some trouble toucheth man, he crieth unto his Lord, turning to Him in repentance: but when He bestoweth a favour upon him as from Himself, (man) doth forget what he cried and prayed for before, and he doth set up rivals unto Allah, thus misleading others from Allah\'s Path. Say, "Enjoy thy blasphemy for a little while: verily thou art (one) of the Companions of the Fire!"'),
  ('en.yusufali', 39, 9, 'Is one who worships devoutly during the hour of the night prostrating himself or standing (in adoration), who takes heed of the Hereafter, and who places his hope in the Mercy of his Lord - (like one who does not)? Say: "Are those equal, those who know and those who do not know? It is those who are endued with understanding that receive admonition.'),
  ('en.yusufali', 39, 10, 'Say: "O ye my servants who believe! Fear your Lord, good is (the reward) for those who do good in this world. Spacious is Allah\'s earth! those who patiently persevere will truly receive a reward without measure!"'),
  ('en.yusufali', 39, 11, 'Say: "Verily, I am commanded to serve Allah with sincere devotion;'),
  ('en.yusufali', 39, 12, '"And I am commanded to be the first of those who bow to Allah in Islam."'),
  ('en.yusufali', 39, 13, 'Say: "I would, if I disobeyed my Lord, indeed have fear of the Penalty of a Mighty Day."'),
  ('en.yusufali', 39, 14, 'Say: "It is Allah I serve, with my sincere (and exclusive) devotion:'),
  ('en.yusufali', 39, 15, '"Serve ye what ye will besides him." Say: "Truly, those in loss are those who lose their own souls and their People on the Day of Judgment: Ah! that is indeed the (real and) evident Loss!'),
  ('en.yusufali', 39, 16, 'They shall have Layers of Fire above them, and Layers (of Fire) below them: with this doth Allah warn off his servants: "O My Servants! then fear ye Me!"'),
  ('en.yusufali', 39, 17, 'Those who eschew Evil,- and fall not into its worship,- and turn to Allah (in repentance),- for them is Good News: so announce the Good News to My Servants,-'),
  ('en.yusufali', 39, 18, 'Those who listen to the Word, and follow the best (meaning) in it: those are the ones whom Allah has guided, and those are the ones endued with understanding.'),
  ('en.yusufali', 39, 19, 'Is, then, one against whom the decree of Punishment is justly due (equal to one who eschews Evil)? Wouldst thou, then, deliver one (who is) in the Fire?'),
  ('en.yusufali', 39, 20, 'But it is for those who fear their Lord. That lofty mansions, one above another, have been built: beneath them flow rivers (of delight): (such is) the Promise of Allah: never doth Allah fail in (His) promise.'),
  ('en.yusufali', 39, 21, 'Seest thou not that Allah sends down rain from the sky, and leads it through springs in the earth? Then He causes to grow, therewith, produce of various colours: then it withers; thou wilt see it grow yellow; then He makes it dry up and crumble away. Truly, in this, is a Message of remembrance to men of understanding.'),
  ('en.yusufali', 39, 22, 'Is one whose heart Allah has opened to Islam, so that he has received Enlightenment from Allah, (no better than one hard-hearted)? Woe to those whose hearts are hardened against celebrating the praises of Allah! they are manifestly wandering (in error)!'),
  ('en.yusufali', 39, 23, 'Allah has revealed (from time to time) the most beautiful Message in the form of a Book, consistent with itself, (yet) repeating (its teaching in various aspects): the skins of those who fear their Lord tremble thereat; then their skins and their hearts do soften to the celebration of Allah\'s praises. Such is the guidance of Allah: He guides therewith whom He pleases, but such as Allah leaves to stray, can have none to guide.'),
  ('en.yusufali', 39, 24, 'Is, then, one who has to fear the brunt of the Penalty on the Day of Judgment (and receive it) on his face, (like one guarded therefrom)? It will be said to the wrong-doers: "Taste ye (the fruits of) what ye earned!"'),
  ('en.yusufali', 39, 25, 'Those before them (also) rejected (revelation), and so the Punishment came to them from directions they did not perceive.'),
  ('en.yusufali', 39, 26, 'So Allah gave them a taste of humiliation in the present life, but greater is the punishment of the Hereafter, if they only knew!'),
  ('en.yusufali', 39, 27, 'We have put forth for men, in this Qur\'an every kind of Parable, in order that they may receive admonition.'),
  ('en.yusufali', 39, 28, '(It is) a Qur\'an in Arabic, without any crookedness (therein): in order that they may guard against Evil.'),
  ('en.yusufali', 39, 29, 'Allah puts forth a Parable a man belonging to many partners at variance with each other, and a man belonging entirely to one master: are those two equal in comparison? Praise be to Allah! but most of them have no knowledge.'),
  ('en.yusufali', 39, 30, 'Truly thou wilt die (one day), and truly they (too) will die (one day).'),
  ('en.yusufali', 39, 31, 'In the end will ye (all), on the Day of Judgment, settle your disputes in the presence of your Lord.'),
  ('en.yusufali', 39, 32, 'Who, then, doth more wrong than one who utters a lie concerning Allah, and rejects the Truth when it comes to him; is there not in Hell an abode for blasphemers?'),
  ('en.yusufali', 39, 33, 'And he who brings the Truth and he who confirms (and supports) it - such are the men who do right.'),
  ('en.yusufali', 39, 34, 'They shall have all that they wish for, in the presence of their Lord: such is the reward of those who do good:'),
  ('en.yusufali', 39, 35, 'So that Allah will turn off from them (even) the worst in their deeds and give them their reward according to the best of what they have done.'),
  ('en.yusufali', 39, 36, 'Is not Allah enough for his Servant? But they try to frighten thee with other (gods) besides Him! for such as Allah leaves to stray, there can be no guide.'),
  ('en.yusufali', 39, 37, 'And such as Allah doth guide there can be none to lead astray. Is not Allah Exalted in Power, (Able to enforce His Will), Lord of Retribution?'),
  ('en.yusufali', 39, 38, 'If indeed thou ask them who it is that created the heavens and the earth, they would be sure to say, "Allah". Say: "See ye then? the things that ye invoke besides Allah,- can they, if Allah wills some Penalty for me, remove His Penalty?- Or if He wills some Grace for me, can they keep back his Grace?" Say: "Sufficient is Allah for me! In Him trust those who put their trust."'),
  ('en.yusufali', 39, 39, 'Say: "O my People! Do whatever ye can: I will do (my part): but soon will ye know-'),
  ('en.yusufali', 39, 40, '"Who it is to whom comes a Penalty of ignominy, and on whom descends a Penalty that abides."'),
  ('en.yusufali', 39, 41, 'Verily We have revealed the Book to thee in Truth, for (instructing) mankind. He, then, that receives guidance benefits his own soul: but he that strays injures his own soul. Nor art thou set over them to dispose of their affairs.'),
  ('en.yusufali', 39, 42, 'It is Allah that takes the souls (of men) at death; and those that die not (He takes) during their sleep: those on whom He has passed the decree of death, He keeps back (from returning to life), but the rest He sends (to their bodies) for a term appointed verily in this are Signs for those who reflect.'),
  ('en.yusufali', 39, 43, 'What! Do they take for intercessors others besides Allah? Say: "Even if they have no power whatever and no intelligence?"'),
  ('en.yusufali', 39, 44, 'Say: "To Allah belongs exclusively (the right to grant) intercession: to Him belongs the dominion of the heavens and the earth: In the End, it is to Him that ye shall be brought back."'),
  ('en.yusufali', 39, 45, 'When Allah, the One and Only, is mentioned, the hearts of those who believe not in the Hereafter are filled with disgust and horror; but when (gods) other than He are mentioned, behold, they are filled with joy!'),
  ('en.yusufali', 39, 46, 'Say: "O Allah! Creator of the heavens and the earth! Knower of all that is hidden and open! it is Thou that wilt judge between Thy Servants in those matters about which they have differed."'),
  ('en.yusufali', 39, 47, 'Even if the wrong-doers had all that there is on earth, and as much more, (in vain) would they offer it for ransom from the pain of the Penalty on the Day of Judgment: but something will confront them from Allah, which they could never have counted upon!'),
  ('en.yusufali', 39, 48, 'For the evils of their Deeds will confront them, and they will be (completely) encircled by that which they used to mock at!'),
  ('en.yusufali', 39, 49, 'Now, when trouble touches man, he cries to Us: But when We bestow a favour upon him as from Ourselves, he says, "This has been given to me because of a certain knowledge (I have)!" Nay, but this is but a trial, but most of them understand not!'),
  ('en.yusufali', 39, 50, 'Thus did the (generations) before them say! But all that they did was of no profit to them.'),
  ('en.yusufali', 39, 51, 'Nay, the evil results of their Deeds overtook them. And the wrong-doers of this (generation)- the evil results of their Deeds will soon overtake them (too), and they will never be able to frustrate (Our Plan)!'),
  ('en.yusufali', 39, 52, 'Know they not that Allah enlarges the provision or restricts it, for any He pleases? Verily, in this are Signs for those who believe!'),
  ('en.yusufali', 39, 53, 'Say: "O my Servants who have transgressed against their souls! Despair not of the Mercy of Allah: for Allah forgives all sins: for He is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 39, 54, '"Turn ye to our Lord (in repentance) and bow to His (Will), before the Penalty comes on you: after that ye shall not be helped.'),
  ('en.yusufali', 39, 55, '"And follow the best of (the courses) revealed to you from your Lord, before the Penalty comes on you - of a sudden while ye perceive not!-'),
  ('en.yusufali', 39, 56, '"Lest the soul should (then) say: \'Ah! Woe is me!- In that I neglected (my duty) towards Allah, and was but among those who mocked!\'-'),
  ('en.yusufali', 39, 57, '"Or (lest) it should say: \'If only Allah had guided me, I should certainly have been among the righteous!\'-'),
  ('en.yusufali', 39, 58, '"Or (lest) it should say when it (actually) sees the penalty: \'If only I had another chance, I should certainly be among those who do good!\''),
  ('en.yusufali', 39, 59, '"(The reply will be:) \'Nay, but there came to thee my Signs, and thou didst reject them: thou wast Haughty, and became one of those who reject faith!\'"'),
  ('en.yusufali', 39, 60, 'On the Day of Judgment wilt thou see those who told lies against Allah;- their faces will be turned black; Is there not in Hell an abode for the Haughty?'),
  ('en.yusufali', 39, 61, 'But Allah will deliver the righteous to their place of salvation: no evil shall touch them, nor shall they grieve.'),
  ('en.yusufali', 39, 62, 'Allah is the Creator of all things, and He is the Guardian and Disposer of all affairs.'),
  ('en.yusufali', 39, 63, 'To Him belong the keys of the heavens and the earth: and those who reject the Signs of Allah,- it is they who will be in loss.'),
  ('en.yusufali', 39, 64, 'Say: "Is it some one other than Allah that ye order me to worship, O ye ignorant ones?"'),
  ('en.yusufali', 39, 65, 'But it has already been revealed to thee,- as it was to those before thee,- "If thou wert to join (gods with Allah), truly fruitless will be thy work (in life), and thou wilt surely be in the ranks of those who lose (all spiritual good)".'),
  ('en.yusufali', 39, 66, 'Nay, but worship Allah, and be of those who give thanks.'),
  ('en.yusufali', 39, 67, 'No just estimate have they made of Allah, such as is due to Him: On the Day of Judgment the whole of the earth will be but His handful, and the heavens will be rolled up in His right hand: Glory to Him! High is He above the Partners they attribute to Him!'),
  ('en.yusufali', 39, 68, 'The Trumpet will (just) be sounded, when all that are in the heavens and on earth will swoon, except such as it will please Allah (to exempt). Then will a second one be sounded, when, behold, they will be standing and looking on!'),
  ('en.yusufali', 39, 69, 'And the Earth will shine with the Glory of its Lord: the Record (of Deeds) will be placed (open); the prophets and the witnesses will be brought forward and a just decision pronounced between them; and they will not be wronged (in the least).'),
  ('en.yusufali', 39, 70, 'And to every soul will be paid in full (the fruit) of its Deeds; and (Allah) knoweth best all that they do.'),
  ('en.yusufali', 39, 71, 'The Unbelievers will be led to Hell in crowd: until, when they arrive, there, its gates will be opened. And its keepers will say, "Did not messengers come to you from among yourselves, rehearsing to you the Signs of your Lord, and warning you of the Meeting of This Day of yours?" The answer will be: "True: but the Decree of Punishment has been proved true against the Unbelievers!"'),
  ('en.yusufali', 39, 72, '(To them) will be said: "Enter ye the gates of Hell, to dwell therein: and evil is (this) Abode of the Arrogant!"'),
  ('en.yusufali', 39, 73, 'And those who feared their Lord will be led to the Garden in crowds: until behold, they arrive there; its gates will be opened; and its keepers will say: "Peace be upon you! well have ye done! enter ye here, to dwell therein."'),
  ('en.yusufali', 39, 74, 'They will say: "Praise be to Allah, Who has truly fulfilled His Promise to us, and has given us (this) land in heritage: We can dwell in the Garden as we will: how excellent a reward for those who work (righteousness)!"'),
  ('en.yusufali', 39, 75, 'And thou wilt see the angels surrounding the Throne (Divine) on all sides, singing Glory and Praise to their Lord. The Decision between them (at Judgment) will be in (perfect) justice, and the cry (on all sides) will be, "Praise be to Allah, the Lord of the Worlds!"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 39, 1, 'Tanzeelul Kitaabi minal laahil \'Azeezil Hakeem'),
  ('en.transliteration', 39, 2, 'Innaaa anzalnaaa ilaikal Kitaaba bilhaqqi fa\'budil laaha mukhlisal lahud deen'),
  ('en.transliteration', 39, 3, 'Alaa lillaahid deenul khaalis; wallazeenat takhazoo min dooniheee awliyaaa\'a maa na\'buduhum illaa liyuqar riboonaaa ilal laahi zulfaa; innal laaha yahkumu baina hum fee maa hum feehi yakhtalifoon; innal laaha laa yahdee man huwa kaazibun kaffaar'),
  ('en.transliteration', 39, 4, 'Law araadal laahu aiyattakhiza waladal lastafaa mimmaa yakhluqu maa yashaaa\'; Subhaanahoo Huwal laahul Waahidul Qahhaar'),
  ('en.transliteration', 39, 5, 'Khalaqas samaawaati wal arda bilhaqq; yukawwirul laila \'alan nahaari wa yukawwirun nahaara \'alaal laili wa sakhkharash shamsa walqamara kulluny yajree li ajalim musammaa; alaa Huwal \'Azeezul Ghaffaar'),
  ('en.transliteration', 39, 6, 'Khalaqakum min nafsinw waahidatin summa ja\'ala minhaa zawjahaa wa anzala lakum minal-an\'aami samaani yata azwaaj; yakhuluqukum fee butooni ummahaatikum khalqam mim ba\'di khalqin fee zulumaatin salaas; zaalikumul laahu Rabbukum lahul mulk; laaa ilaaha illaa Huwa fa annaa tusrafoon'),
  ('en.transliteration', 39, 7, 'In takfuroo fa innal laaha ghaniyyun \'ankum; wa laa yardaa li\'ibaadihil kufra wa in tashkuroo yardahu lakum; wa laa taziru waaziratunw wizra ukhraa; summa ilaa Rabikum marji\'ukum fa-yunabbi\'ukum bimaa kuntum ta\'maloon; innahoo \'aleemum bizaatissudoor'),
  ('en.transliteration', 39, 8, 'Wa izaa massal insaana durrun da\'aa Rabbahoo muneeban ilaihi summa izaa khawwalahoo ni\'matam minhu nasiya maa kaana yad\'ooo ilaihi min qablu wa ja\'ala lillaahi andaadal liyudilla \'ansabeelih; qul tamatta\' bikufrika qaleelan innaka min Ashaabin Naar;'),
  ('en.transliteration', 39, 9, 'Amman huwa qaanitun aanaaa\'al laili saajidanw wa qaaa\'imai yahzarul Aakhirata wa yarjoo rahmata Rabbih; qul hal yastawil lazeena ya\'lamoona wallazeena laa ya\'lamoon; innamaa yatazakkaru ulul albaab'),
  ('en.transliteration', 39, 10, 'Qul yaa \'ibaadil lazeena aamanut taqoo Rabbakum; lillazeena ahsanoo fee haazihid dunyaa hasanah; wa ardul laahi waasi\'ah; innamaa yuwaffas saabiroona ajrahum bighayri hisab'),
  ('en.transliteration', 39, 11, 'Qul inneee umirtu an a\'budal laaha mukhlisal lahud deen'),
  ('en.transliteration', 39, 12, 'Wa umirtu li an akoona awwalal muslimeen'),
  ('en.transliteration', 39, 13, 'Qul inneee akhaafu in \'asaitu Rabbee \'azaaba Yawmin \'azeem'),
  ('en.transliteration', 39, 14, 'Qulil laaha a\'budu mukhlisal lahoo deenee'),
  ('en.transliteration', 39, 15, 'Fa\'budoo maa shi\'tum min doonih; qul innal khaasireenal lazeena khasirooo anfusahum wa ahleehim yawmal qiyaamah; alaa zaalika huwal khusraanul mubeen'),
  ('en.transliteration', 39, 16, 'Lahum min fawqihim zulalum minan Naari wa min tahtihim zulal; zaalika yukhaw wiful laahu bihee \'ibaadah; yaa \'ibaadi fattaqoon'),
  ('en.transliteration', 39, 17, 'Wallazeenaj tanabut Taaghoota ai ya\'budoohaa wa anaabooo ilal laahi lahumul bushraa; fabashshir \'ibaad'),
  ('en.transliteration', 39, 18, 'Allazeena yastami\'oonal qawla fayattabi\'oona ahsanah; ulaaa\'ikal lazeena hadaahumul laahu wa ulaaa\'ika hum ulul albaab'),
  ('en.transliteration', 39, 19, 'Afaman haqqa \'alaihi kalimatul \'azaab; afa anta tunqizu man fin Naar'),
  ('en.transliteration', 39, 20, 'Laakinil lazeenat taqaw Rabbahum lahum ghurafum min fawqihaa ghurafum mabniyyatun tajree min tahtihal anhaar; wa\'dal laah; laa yukhliful laahul mee\'aad'),
  ('en.transliteration', 39, 21, 'Alam tara annal laaha anzala minas samaaa\'i maaa\'an fasalakahoo yanaabee\'a fil ardi summa yukhriju bihee zar\'am mukhtalifan alwaanuhoo summa yaheeju fatarahu musfarran summa yaj\'aluhoo hutaamaa; inna fee zaalika lazikraa li ulil albaab'),
  ('en.transliteration', 39, 22, 'Afaman sharahal laahu sadrahoo lil Islaami fahuwa \'alaa noorim mir Rabbih; fa wailul lilqaasiyati quloobuhum min zikril laah; ulaaa\'ika fee dalaalim mubeen'),
  ('en.transliteration', 39, 23, 'Allahu nazzala ahsanal hadeesi Kitaabam mutashaa biham masaaniy taqsha\'irru minhu juloodul lazeena yakhshawna Rabbahum summa taleenu julooduhum wa quloo buhum ilaa zikril laah; zaalika hudal laahi yahdee bihee mai yashaaa\'; wa mai yudlilil laahu famaa lahoo min haad'),
  ('en.transliteration', 39, 24, 'Afamai yattaqee biwaj hihee sooo\'al \'azaabi Yawmal Qiyaamah; wa qeela lizzaali meena zooqoo maa kuntum taksiboon'),
  ('en.transliteration', 39, 25, 'Kazzabal lazeena min qablihim fa ataahumul \'azaabu min haisu laa yash\'uroon'),
  ('en.transliteration', 39, 26, 'Fa azaaqahumul laahul khizya fil hayaatid dunyaa wa la\'azaabul Aakirati akbar; law kaanoo ya\'lamoon'),
  ('en.transliteration', 39, 27, 'Wa laqad darabnaa linnaasi fee haazal Qur-aani min kulli masalil la\'allahum yatazakkaroon'),
  ('en.transliteration', 39, 28, 'Qur-aanan \'Arabiyyan ghaira zee \'iwajil la\'allahum yattaqoon'),
  ('en.transliteration', 39, 29, 'Darabal laahu masalar rajulan feehi shurakaaa\'u mutashaakisoona wa rajulan salamal lirajulin hal tastawi yaani masalaa; alhamdu lillaah; bal aksaruhum laa ya\'lamoon'),
  ('en.transliteration', 39, 30, 'Innaka maiyitunw wa inna hum maiyitunw wa inna hum maiyitoon'),
  ('en.transliteration', 39, 31, 'Summa innakum Yawmal Qiyaamati \'inda Rabbikum takhtasimoon'),
  ('en.transliteration', 39, 32, 'Faman azlamu mimman kazaba \'alal laahi wa kazzaba bissidqi iz jaaa\'ah; alaisa fee Jahannama maswal lilkaafir'),
  ('en.transliteration', 39, 33, 'Wallazee jaaa\'a bissidqi wa saddaqa biheee ulaaa\'ika humul muttaqoon'),
  ('en.transliteration', 39, 34, 'Lahum maa yashaaa\'oona \'inda Rabbihim; zaalika jazaaa\'ul muhsineen'),
  ('en.transliteration', 39, 35, 'Liyukaffiral laahu \'anhum aswa allazee \'amiloo wa yajziyahum ajrahum bi ahsanil lazee kaano ya\'maloon'),
  ('en.transliteration', 39, 36, 'Alaisal laahu bikaafin \'abdahoo wa yukhawwi foonaka billazeena min doonih; wa mai yudlilil laahu famaa lahoo min haad'),
  ('en.transliteration', 39, 37, 'Wa mai yahdil laahu famalahoo mim mudlil; alai sal laahu bi\'azeezin zin tiqaam'),
  ('en.transliteration', 39, 38, 'Wa la\'in sa altahum man khalaqas samaawaati wal arda la yaqoolunal laah; qul afara\'aitum maa tad\'oona min doonil laahi in araadaniyal laahu bidurrin hal hunna kaashi faatu durriheee aw araadanee birahmatin hal hunna mumsikaatu rahmatih; qul hasbiyal laahu \'alaihi tatawakkalul mutawakkiloon'),
  ('en.transliteration', 39, 39, 'Qul yaa qawmi\'maloo \'alaa makaanatikum innee \'aamilun fasawfa ta\'lamoon'),
  ('en.transliteration', 39, 40, 'Mai yaateehi \'azaabuny yukhzeehi wa yahillu \'alaihi \'azaabum muqeem'),
  ('en.transliteration', 39, 41, 'Innaa anzalnaa \'alaikal Kitaaba linnaasi bilhaqq; famanih tadaa falinafsihee wa man dalla fa innamaa yadillu \'alaihaa wa maaa anta \'alaihim biwakeel'),
  ('en.transliteration', 39, 42, 'Allaahu yatawaffal anfusa heena mawtihaa wallatee lam tamut fee manaamihaa fa yumsikul latee qadaa \'alaihal mawta wa yursilul ukhraaa ilaaa ajalim musammaa; inna fee zaalika la Aayaatil liqawmai yatafakkarron'),
  ('en.transliteration', 39, 43, 'Amit takhazoo min doonillaahi shufa\'aaa\'; qul awalaw kaanoo laa yamlikoona shai\'aw wa laa ya\'qiloon'),
  ('en.transliteration', 39, 44, 'Qul lillaahish shafaa\'atu jamee\'aa; lahoo mulkus samaawaati wal ardi summa ilaihi turj\'oon'),
  ('en.transliteration', 39, 45, 'Wa izaa zukiral laahu wahdahush ma azzat quloobul lazeena laa yu\'minoona bil Aakhirati wa izaa zukiral lazeena min dooniheee izaa hum yastabshiroon'),
  ('en.transliteration', 39, 46, 'Qulil laahumma faatiras samaawaati wal ardi \'Aalimal Ghaibi washshahaadati Anta tahkumu baina \'ibaadika fee maa kaanoo fee yakhtalifoon'),
  ('en.transliteration', 39, 47, 'Wa law anna lillazeena zalamoo maa fil ardi jamee\'anw wa mislahoo ma\'ahoo laftadaw bihee min sooo\'il azaabi Yawmal Qiyaamah; wa badaa lahum minal laahi maa lam yakkoonoo yahtasiboon'),
  ('en.transliteration', 39, 48, 'Wa badaa lahum saiyiaatu maa kasaboo wa haaqa bihim maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 39, 49, 'Fa izaa massal insaana durrun da\'aanaa summa izaa khawwalnaahu ni\'matam minna qaala innamaaa ootee tuhoo \'alaa \'ilm; bal hiya fitna tunw wa laakinna aksarahum laa ya\'lamoon'),
  ('en.transliteration', 39, 50, 'Qad qaalahul lazeena min qablihim famaaa aghnaa \'anhum maa kaanoo yaksiboon'),
  ('en.transliteration', 39, 51, 'Fa asaabahum saiyi aatu maa kasaboo; wallazeena zalamoo min haaa\'ulaaa\'i sa yuzeebuhum saiyi aatu maa kasaboo wa maa hum bimu\'jizeen'),
  ('en.transliteration', 39, 52, 'Awalam ya\'lamooo annal laaha yabsutur rizqa limai yashaaa\'u wa yaqdir; inna fee zaalika la Aayaatil liqamai yu\'minoon'),
  ('en.transliteration', 39, 53, 'Qul yaa\'ibaadiyal lazeena asrafoo \'alaaa anfusihim laa taqnatoo mirrahmatil laah; innal laaha yaghfiruz zunooba jamee\'aa; innahoo Huwal Ghafoorur Raheem'),
  ('en.transliteration', 39, 54, 'Wa aneebooo ilaa Rabbikum wa aslimoo lahoo min qabli ai yaatiyakumul \'azaabu summ laa tunsaroon'),
  ('en.transliteration', 39, 55, 'Wattabi\'ooo ahsana maaa unzila ilaikum mir Rabbikum min qabli aiyaatiyakumal \'azaabu baghtatanw wa antum laa tash\'uroon'),
  ('en.transliteration', 39, 56, 'An taqoola nafsuny yaahasrataa \'alaa maa farrattu fee jambil laahi wa in kuntu laminas saakhireen'),
  ('en.transliteration', 39, 57, 'Aw taqoola law annal laaha hadaanee lakuntu minal muttaqeen'),
  ('en.transliteration', 39, 58, 'Aw taqoola heena taral \'azaaba law anna lee karratan fa akoona minal muhsineen'),
  ('en.transliteration', 39, 59, 'Balaa qad jaaa\'atka Asyaatee fakazzabta bihaa wastak barta wa kunta minal kaafireen'),
  ('en.transliteration', 39, 60, 'Wa Yawmal Qiyaamati taral lazeena kazaboo \'alallaahi wujoohuhum muswaddah; alaisa fee Hahannama maswal lilmutakabbireen'),
  ('en.transliteration', 39, 61, 'Wa yunajjil laahul lazee nat taqaw bimafaazatihim laa yamassuhumus sooo\'u wa laa hum uahzanoon'),
  ('en.transliteration', 39, 62, 'Allaahu khaaliqu kulli shai\'inw wa Huwa \'alaa kulli shai\'inw Wakeel'),
  ('en.transliteration', 39, 63, 'Lahoo maqaaleedus sa maawaati wal ard; wallazeena kafaroo bi ayaatil laahi ulaaa\'ika humul khaasiroon'),
  ('en.transliteration', 39, 64, 'Qul afaghairal laahi taamurooonneee a\'budu ayyuhal jaahiloon'),
  ('en.transliteration', 39, 65, 'Wa laqad oohiya ilaika wa ilal lazeena min qablika la in ashrakta la yahbatanna \'amalu ka wa latakoonanna minal khaasireen'),
  ('en.transliteration', 39, 66, 'Balil laahha fa\'bud wa kum minash shaakireen'),
  ('en.transliteration', 39, 67, 'Wa maa qadarul laaha haqqa qadrihee wal ardu jamee \'an qabdatuhoo Yawmal Qiyaamit wassamaawaatu matwiyyaatum biyameenih; Subhaanahoo wa Ta\'aalaa \'amma yushrikoon'),
  ('en.transliteration', 39, 68, 'Wa nufikha fis Soori fas\'iqa man fis samaawaati wa man fil ardi illaa man shaa\'al lahu summa nufikha feehi ukhraa fa izaa hum qiyaamuny yanzuroon'),
  ('en.transliteration', 39, 69, 'Wa ashraqatil ardu binoori Rabbihaa wa wudi\'al Kitaabu wa jeee\'a bin nabiyyeena wash shuhadaaa\'i wa qudiya bainahum bilhaqqi wa hum laa yuzlamoon'),
  ('en.transliteration', 39, 70, 'Wa wuffiyat kullu nafsim maa \'amilat wa Huwa a\'lamubimaa yaf\'aloon'),
  ('en.transliteration', 39, 71, 'Wa seeqal lazeena kafaroon ilaa jahannama zumaran battaaa izaa jaaa\'oohaa futihat abwaabuhaa wa qaala lahum khazanatuhaaa alam yaatikum Rusulum minkum yatloona \'alaikum Aayaati Rabbikum wa yunziroonakum liqaaa\'a Yawmikum haazaa; qaaloo balaa wa laakin haqqat kalimatul \'azaabi \'alal kaafireen'),
  ('en.transliteration', 39, 72, 'Qeelad khuloo abwaaba jahannama khaalideena feeha fabi\'sa maswal mutakabbireen'),
  ('en.transliteration', 39, 73, 'Wa seeqal lazeenat taqaw Rabbahum ilal Jannati zumaran hattaaa izaa jaaa\'oohaa wa futihat abwaabuhaa wa qaala lahum khazanatuhaa salaamun \'alaikum tibtum fadkhuloohaa khaalideen'),
  ('en.transliteration', 39, 74, 'Wa waalull hamdulillaahil lazee sadaqanaa wa\'dahoo wa awrasanal arda natabaw wa-u minal jannati haisu nashaaa\'u fani\'ma ajrul \'aamileen'),
  ('en.transliteration', 39, 75, 'Wa taral malaaa\'ikata haaaffeena min hawlil \'Arshi yusabbihoona bihamdi Rabbihim wa qudiya bainahum bilhaqqi wa qeelal hamdu lillaahi Rabbil \'aalameen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 39, 1, 'یہ کتاب الله کی طرف سے نازل کی گئی ہے جو غالب حکمت والا ہے'),
  ('ur.ahmedali', 39, 2, 'بے شک ہم نے یہ کتاب ٹھیک طور پر آپ کی طرف نازل کی ہے پس تو خالص الله ہی کی فرمانبرداری مدِ نظر رکھ کر اسی کی عبادت کر'),
  ('ur.ahmedali', 39, 3, 'خبردار! خالص فرمانبرداری الله ہی کے لیے ہے جنہوں نے اس کے سوا اور کارساز بنا لیے ہیں ہم ان کی عبادت نہیں کرتے مگر اس لیے کہ وہ ہمیں الله سے قریب کر دیں بے شک الله ان کے درمیان ان باتوں میں فیصلہ کرے گا جن میں وہ اختلاف کرتےتھے بے شک الله اسے ہدایت نہیں کرتا جو جھوٹا ناشکرگزار ہو'),
  ('ur.ahmedali', 39, 4, 'اگر الله چاہتا کہ کسی کو فرزند بنائے تواپنی مخلوقات میں سے جسے چاہتا چن لیتا وہ پاک ہے وہ الله ایک بڑا غالب ہے'),
  ('ur.ahmedali', 39, 5, 'اس نے آسمانوں اور زمین کو حکمت سے پیدا کیا وہ رات کو دن پر لپیٹ دیتا ہے اور دن کو رات پر لپیٹ دیتا ہے اور اس نے سورج اور چاند کو تابع کر دیا ہے ہر ایک وقت مقرر تک چل رہا ہے خبرادار! وہی غالب بخشنے والا ہے'),
  ('ur.ahmedali', 39, 6, 'اس نے تمہیں ایک جان سے پیدا کیا پھر اس نے اس سے اس کی بیوی بنائی اور تمہارے لیے آٹھ نر اور مادہ چارپایوں کے پیدا کیے وہ تمہیں تمہاری ماؤں کے پیٹوں میں ایک کیفیت کے بعد دوسری کیفیت پر تین اندھیروں میں بناتا ہے یہی الله تمہارا رب ہے اسی کی بادشاہی ہے اس کے سوا کوئی معبود نہیں پس تم کہاں پھرے جا رہے ہو'),
  ('ur.ahmedali', 39, 7, 'اگر تم انکار کرو تو بے شک الله تم سے بے نیاز ہے اور وہ اپنے بندوں کے لیے کفر کو پسند نہیں کرتا اور اگر تم شکر کرو تو وہ اسے تمہارے لیے پسند کرتا ہے اور کوئی بوجھ اٹھانے والا دوسرے کا بوجھ نہیں اٹھائے گا پھر اپنے رب ہی کی طرف تمہیں لوٹ کر جانا ہے سو وہ تمہیں بتا دے گا جو کچھ تم کرتے رہے ہو بے شک وہ سینوں کے بھید جاننے والا ہے'),
  ('ur.ahmedali', 39, 8, 'اور جب انسان کو تکلیف پہنچتی ہے تو اپنے رب کواس کی طرف رجوع کر کے پکارتا ہے پھر جب وہ اسے کوئی نعمت اپنی طرف سے عطا کرتا ہے تو جس کے لیے پہلے پکارتا تھا اسے بھول جاتا ہے اور اس کے لیے شریک بناتا ہے تاکہ اس کی راہ سے گمراہ کرے کہہ دو اپنے کفر میں تھوڑی مدت فائد ہ اٹھا لے بے شک تو دوزخیوں میں سے ہے'),
  ('ur.ahmedali', 39, 9, '(کیا کافر بہتر ہے) یا وہ جو رات کے اوقات میں سجدہ اور قیام کی حالت میں عبادت کر رہا ہو آخرت سے ڈر رہا ہو اور اپنے رب کی رحمت کی امید کر رہا ہو کہہ دو کیا علم والے اور بے علم برابر ہو سکتے ہیں سمجھتے وہی ہیں جو عقل والے ہیں'),
  ('ur.ahmedali', 39, 10, 'کہہ دو اے میرے بندو جو ایمان لائےہو اپنے رب سے ڈرو ان کے لیے جنھوں نے اس دنیا میں نیکی کی ہے اچھا بدلہ ہے اور الله کی زمین کشادہ ہے بے شک صبر کرنے والوں کو ان کا اجر بے حساب دیا جائے گا'),
  ('ur.ahmedali', 39, 11, 'کہہ دو مجھے حکم ہوا ہے کہ میں الله کی اس طرح عبادت کروں کہ عبادت کو اس کے لیے خاص رکھوں'),
  ('ur.ahmedali', 39, 12, 'اور مجھے یہ بھی حکم ہوا ہے کہ میں سب سے پہلا فرمانبردار بنوں'),
  ('ur.ahmedali', 39, 13, 'کہہ دو میں بڑے دن کے عذاب سے ڈرتا ہوں اگر اپنے رب کی نافرمانی کروں'),
  ('ur.ahmedali', 39, 14, 'کہہ دو میں خالص الله ہی کی اطاعت کرتے ہوئے اس کی عبادت کر تا ہوں'),
  ('ur.ahmedali', 39, 15, 'پھر تم اس کے سوا جس کی چاہو عبادت کرو کہہ دو خسارہ اٹھانے والے وہ ہیں جنہوں نے اپنے جان اور اپنے گھر والوں کو قیامت کے روز خسارہ میں ڈال دیا یاد رکھو! یہ صریح خسارہ ہے'),
  ('ur.ahmedali', 39, 16, 'ان کے اوپر بھی آگ کے سائبان ہوں گے اور ان کے نیچے بھی سائبان ہوں گے یہی بات ہے جس کا ا لله اپنے بندوں کو خوف دلاتا ہے کہ اے میرے بندو! مجھ سے ڈرتے رہو'),
  ('ur.ahmedali', 39, 17, 'اور جو لوگ شیطانوں کو پوجنے سے بچتے رہے اور الله کی طرف رجوع ہوئے ان کے لیے خوشخبری ہے پس میرےبندوں کو خوشخبری دے دو'),
  ('ur.ahmedali', 39, 18, 'جو توجہ سے بات کو سنتے ہیں پھر اچھی بات کی پیروی کرتے ہیں یہی ہیں جنہیں الله نے ہدایت کی ہے اور یہی عقل والے ہیں'),
  ('ur.ahmedali', 39, 19, 'پس کیا جسے عذاب کا حکم ہو چکا ہے (نجات والے کے برابر ہے) کیا آپ اسے چھوڑ سکتے ہیں جو آگ میں ہے'),
  ('ur.ahmedali', 39, 20, 'لیکن جو لوگ اپنےرب سے ڈرتے رہے ان کے لیے بالا خانے ہیں جن کے اوپر اوربالا خانے بنے ہوئے ہیں ان کے نیچے نہریں چلتی ہوں گی یہ الله کا وعدہ ہے اور الله اپنے وعدے کے خلاف نہیں کرتا'),
  ('ur.ahmedali', 39, 21, 'کیا آپ نے نہیں دیکھا کہ الله ہی آسمان سے پانی اتارتا ہے پھر اسے چشمے بنا کر زمین میں چلا دیتا ہے پھر اس کے ذریعے سے کھیتی مختلف رنگوں کی اگاتا ہے پھر خوب ابھرتی ہے پھر آپ اسے زردشدہ دیکھتے ہیں پھر اسے ریزہ ریزہ کر دیتا ہے بے شک اس میں عقل مندوں کے لیے عبرت ہے'),
  ('ur.ahmedali', 39, 22, 'بھلا جس کا سینہ الله نے دین اسلام کے لئے کھول دیا ہے سو وہ اپنے رب کی طرف سے روشنی میں ہے سوجن لوگوں کے دل الله کے ذکر سے متاثر نہیں ہوتے ان کے لیے بڑی خرابی ہے یہ لوگ کھلی گمراہی میں ہیں'),
  ('ur.ahmedali', 39, 23, 'الله ہی نے بہترین کلام نال کیا ہے یعنی کتاب باہم ملتی جلتی ہے (اس کی آیات) دہرائی جاتی ہیں جس سے خدا ترس لوگوں کے رونگٹے کھڑے ہو جاتے ہیں پھر ان کی کھالیں نرم ہوجاتی ہیں اور دل یاد الہیٰ کی طرف راغب ہوتے ہیں یہی الله کی ہدایت ہے اس کے ذریعے سے جسے چاہے راہ پر لے آتا ہے اور جسے الله گمراہ کر دے اسے راہ پر لانے والا کوئی نہیں'),
  ('ur.ahmedali', 39, 24, 'بھلا جو شخص اپنے منہ کو قیامت کے دن برے عذاب کی سپر بنائے گا اور ایسے ظالموں کو حکم ہوگا جو کچھ تم کیا کرتے تھے اس کا مزہ چکھو'),
  ('ur.ahmedali', 39, 25, 'ان سے پہلے لوگوں نے بھی جھٹلایا تھاپھر ان پر اس طرح عذاب آیا کہ ان کو خبر بھی نہ ہوئی'),
  ('ur.ahmedali', 39, 26, 'پھر الله نے ان کو دنیا ہی کی زندگی میں رسوائی کا مزہ چکھایا اور آخرت کا عذاب تو اور بھی زیادہ ہے کاش وہ جانتے'),
  ('ur.ahmedali', 39, 27, 'اورہم نے لوگو ں کے لیے اس قرآن میں ہر قسم کی مثال بیان کر دی ہے تاکہ وہ نصیحت پکڑیں'),
  ('ur.ahmedali', 39, 28, 'وہ عربی زبان کا بے عیب قرآن ہے تاکہ یہ لوگ ڈریں'),
  ('ur.ahmedali', 39, 29, 'الله نے ایک مثال بیان کی ہے ایک غلام ہے جس میں کئی ضدی شریک ہیں اور ایک غلام سالم ایک ہی شخص کا ہے کیا دونوں کی حالت برابر ہے سب تعریف الله ہی کے لیے ہے مگر ان میں سے اکثر نہیں سمجھتے'),
  ('ur.ahmedali', 39, 30, 'بے شک آپ کو بھی مرنا ہے اور ان کو بھی مرنا ہے'),
  ('ur.ahmedali', 39, 31, 'پھر بے شک تم قیامت کے دن اپنے رب کے ہاں آپس میں جھگڑو گے'),
  ('ur.ahmedali', 39, 32, 'پھر اس سے کون زیادہ ظالم ہے جس نے الله پرجھوٹ بولا اور سچی بات کو جھٹلایا جب اس کے پاس آئی کیا دوزخ میں کافروں کا ٹھکانا نہیں ہے'),
  ('ur.ahmedali', 39, 33, 'اور جو سچی بات لایا اور جس نے اس کی تصدیق کی وہی پرہیزگار ہیں'),
  ('ur.ahmedali', 39, 34, 'ان کے لیے جو کچھ وہ چاہیں گے ان کے رب کے پاس موجود ہوگا نیکو کارو ں کا یہی بدلہ ہے'),
  ('ur.ahmedali', 39, 35, 'تاکہ الله ان سے وہ برائیاں دور کر دے جو انہوں نے کی تھیں اور الله ان کو ان کا اجر دے ان نیک کاموں کے بدلہ میں جو وہ کیا کرتے تھے'),
  ('ur.ahmedali', 39, 36, 'کیا الله اپنے بندے کو کافی نہیں اور وہ آپ کو ان لوگوں سے ڈراتے ہیں جو اس کے سوا ہیں اور جسے الله گمراہ کر دے تو اسے راہ پر لانے والا کوئی نہیں'),
  ('ur.ahmedali', 39, 37, 'اور جسے الله راہ پر لے آئے تو اسے کوئی گمراہ کرنے والا نہیں کیا الله غالب بدلہ لینے والا نہیں ہے'),
  ('ur.ahmedali', 39, 38, 'او راگر آپ ان سے پوچھیں آسمانوں اور زمین کو کس نے پیدا کیا ہے تو وہ ضرور کہیں گے الله نے کہہ دو بھلا دیکھو تو سہی جنہیں تم الله کے سوا پکارتے ہو اگر الله مجھے تکلیف دینا چاہے تو کیا وہ اس کی تکلیف کو دور کر سکتے ہیں یا وہ مجھ پر مہربانی کرنا چاہے تو کیا وہ اس مہربانی کو روک سکتے ہیں کہہ دو مجھے الله کافی ہے توکل کرنے والے اسی پر توکل کیا کرتے ہیں'),
  ('ur.ahmedali', 39, 39, 'کہہ دو اے میری قوم تم اپنی جگہ پر کام کیے جاؤ میں بھی کر رہا ہوں پھر تمہیں معلوم ہو جائے گا'),
  ('ur.ahmedali', 39, 40, 'کہ کس پر عذاب آتا ہےجو اسے رسوا کردے اورکس پردائمی عذاب اترتا ہے'),
  ('ur.ahmedali', 39, 41, 'بے شک ہم نے آپ پر یہ کتاب سچی لوگو ں کے لیے اتاری ہے پھر جو راہ پر آیا سو اپنے لیے اور جو گمراہ ہوا سو وہ گمراہ ہوتا ہے اپنے برے کو اور آپ ان کے ذمہ دار نہیں ہیں'),
  ('ur.ahmedali', 39, 42, 'اللہ ہی جانوں کو ان کی موت کے وقت قبض کرتا ہے اور ان جانوں کو بھی جن کی موت ان کے سونے کے وقت نہیں آئی پھر ان جانوں کو روک لیتا ہے جن پر موت کا حکم فرما چکا ہے اور باقی جانوں کو ایک میعاد معین تک بھیج دیتا ہے بے شک اس میں ان لوگوں کے لیے نشانیاں ہیں جو غور کرتے ہیں'),
  ('ur.ahmedali', 39, 43, 'کیا انہوں نے الله کےسوا اور حمایتی بنا رکھے ہیں کہہ دوکیا اگرچہ وہ کچھ بھی اختیار نہ رکھتے ہوں اور نہ عقل رکھتے ہوں'),
  ('ur.ahmedali', 39, 44, 'کہہ دو ہر طرح کی حمایت الله ہی کے اختیار میں ہے آسمانوں اور زمین میں اسی کی حکومت ہے پھر اسی کی طرف تم لوٹائے جاؤ گے'),
  ('ur.ahmedali', 39, 45, 'اور جب ایک الله کا ذکر کیا جاتا ہے تو لوگ آخرت پر یقین نہیں رکھتے ان کے دل نفرت کرتے ہیں اور جب اس کے سوا اوروں کا ذکر کیا جاتا ہے تو فوراً خوش ہو جاتے ہیں'),
  ('ur.ahmedali', 39, 46, 'کہہ دو اے الله آسمانوں اور زمین کے پیدا کرنے والے ہر چھپی او رکھلی بات کے جاننے والے تو ہی اپنے بندوں میں فیصلہ کرے گا اس بات میں جس میں وہ اختلاف کر رہے ہیں'),
  ('ur.ahmedali', 39, 47, 'اور اگر ظالموں کے پاس جو کچھ زمین میں ہے سب ہو اور اسی قدر اس کے ساتھ اور بھی ہو تو قیامت کے بڑے عذاب کے معاوضہ میں دے کر چھوٹنا چاہیں گے اور اللہ کی طرف سے انہیں وہ پیش آئے گا کہ جس کا انہیں گمان بھی نہ تھا'),
  ('ur.ahmedali', 39, 48, 'اور برے کاموں کی برائی ان پر ظاہر ہو جائے گی اوران کو وہ عذاب کہ جس پر ہنسی کیا کرتے تھے پکڑ لے گا'),
  ('ur.ahmedali', 39, 49, 'پھر جب آدمی پر کوئی مصیبت آتی ہے تو ہمیں پکارتا ہے پھر جب ہم اسے اپنی نعمت عطا کرتے ہیں تو کہتا ہے یہ تومجھے میری عقل سے ملی ہے بلکہ یہ نعمت آزمائش ہے ولیکن ان میں سے اکثر نہیں جانتے'),
  ('ur.ahmedali', 39, 50, 'بے شک یہی بات وہ لوگ کہہ چکے ہیں جو ان سے پہلے تھے پس ان کے نہ کام آیا جو کچھ وہ کماتے رہے'),
  ('ur.ahmedali', 39, 51, 'پھر ان پر ان کے اعمال کی برائی آ پڑی اور ان میں سے جو لوگ ظلم کر رہے ہیں عنقریب ان کو بھی برے نتائج ان برے عملوں کے پہنچیں گے اور وہ عاجز کرنے والے نہیں ہیں'),
  ('ur.ahmedali', 39, 52, 'اور کیا انہیں معلوم نہیں کہ الله ہی روزی کشادہ کر تا ہے جس کی چاہے اور تنگ کرتا ہے بے شک اس میں ان لوگو ں کے لیے نشانیاں ہیں جو ایمان رکھتے ہیں'),
  ('ur.ahmedali', 39, 53, 'کہہ دو اے میرے بندو جنہوں نے اپنی جانوں پر ظلم کیا ہے الله کی رحمت سے مایوس نہ ہو بے شک الله سب گناہ بخش دے گا بے شک وہ بخشنے والا رحم والا ہے'),
  ('ur.ahmedali', 39, 54, 'اور اپنے رب کی طرف رجوع کرو اور اس کا حکم مانو اس سے پہلے کہ تم پر عذاب آئے پھر تمہیں مدد بھی نہ مل سکے گی'),
  ('ur.ahmedali', 39, 55, 'اور ان اچھی باتوں کی پیروی کرو جو تمہارے رب کی طرف سے نازل کی گئی ہیں اس سے پہلے کہ تم پر ناگہاں عذاب آ جائے اور تمہیں خبر بھی نہ ہو'),
  ('ur.ahmedali', 39, 56, 'کہیں کوئی نفس کہنے لگے ہائے افسوس اس پر جو میں نے الله کے حق میں کوتاہی کی اور میں تو ہنسی ہی کرتا رہ گیا'),
  ('ur.ahmedali', 39, 57, 'یا کہنے لگے اگر الله مجھے ہدایت کرتا تو میں پرہیزگاروں میں ہوتا'),
  ('ur.ahmedali', 39, 58, 'یا کہنے لگے جس وقت عذاب کو دیکھے گا کہ کاش مجھے میسر ہو واپس لوٹنا تو میں نیکو کاروں میں سے ہوجاؤں'),
  ('ur.ahmedali', 39, 59, 'ہاں تیرے پاس میری آیتیں آ چکی تھیں سو تو نے انہیں جھٹلایا اور تو نے تکبر کیا اور تو منکروں میں سے تھا'),
  ('ur.ahmedali', 39, 60, 'اور قیامت کے دن آپ ان لوگوں کو دیکھیں گے جو الله پر جھوٹے الزام لگاتے ہیں کہ ان کے منہ سیاہ ہوں گے کیا دوزخ میں تکبر کرنے والوں کا ٹھکانہ نہیں ہے'),
  ('ur.ahmedali', 39, 61, 'اور الله ان لوگوں کو کامیابی کے ساتھ نجات دے گا جو (شرک و کفر سے) بچتےتھے انہیں تکلیف نہیں پہنچے گی اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 39, 62, 'الله ہی ہر چیز کا پیدا کرنے والا ہے اور وہی ہر چیز کا نگہبان ہے'),
  ('ur.ahmedali', 39, 63, 'آسمانوں اور زمین کی کنجیاں اسی کے ہاتھ میں ہیں اور جو الله کی آیتوں کے منکر ہوئے وہی نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 39, 64, 'کہہ دو اے جاہلو کیا مجھے الله کے سوا اور کی عبادت کرنے کا حکم دیتے ہو'),
  ('ur.ahmedali', 39, 65, 'اور بے شک آپ کی طرف اور ان کی طرف وحی کیا جا چکا ہے جو آپ سے پہلے ہو گزرے ہیں کہ اگرتم نے شرک کیا تو ضرور تمہارے عمل برباد ہو جائیں گے اور تم نقصان اٹھانے والوں میں سے ہو گے'),
  ('ur.ahmedali', 39, 66, 'بلکہ الله ہی کی عبادت کرو اور جس کے شکر گزار رہو'),
  ('ur.ahmedali', 39, 67, 'اور انھوں نے الله کی قدر نہیں کی جیسا کہ اس کی قدر کرنے کا حق ہے اور یہ زمین قیامت کے دن سب اسی کی مٹھی میں ہو گی اور آسمان اس کے داہنے ہاتھ میں لپٹے ہوئےہوں گے وہ پاک اور برتر ہے اس سے جو وہ شریک ٹھیراتے ہیں'),
  ('ur.ahmedali', 39, 68, 'اور صور پھونکا جائے گا تو بے ہوش ہو جاے گا جو کوئی آسمانوں اورجو کوئی زمین میں ہے مگر جسے الله چاہے پھر وہ دوسری دفعہ صور پھونکا جائے گا تو یکایک وہ کھڑے دیکھ رہے ہوں گے'),
  ('ur.ahmedali', 39, 69, 'اور زمین اپنے رب کے نور سے چمک اٹھے گی اور کتاب رکھ دی جاوے گی اور نبی اور گواہ لائے جاویں گے اور ان میں انصاف سے فیصلہ کیا جاوے گا اور ان پر ظلم نہ کیا جائے گا'),
  ('ur.ahmedali', 39, 70, 'اورہر شخص کو جو کچھ اس نے کیا تھا پورا پورا بدلہ دیا جائے گا اور وہ خوب جانتا ہے جو کچھ وہ کر رہے ہیں'),
  ('ur.ahmedali', 39, 71, 'اور جو کافر ہیں دوزخ کی طرف گروہ گروہ ہانکے جائیں گے یہاں تک کہ جب اسکے پاس آئیں گے تو اس کے دروازے کھول دیے جائیں گے اور ان سے اس کے داروغہ کہیں گے کیا تمہارے پاس تم ہی میں سے رسول نہیں آئےتھے جو تمہیں تمہارے رب کی آیتیں پڑھ کر سناتے تھے اور آج کے دن کےپیش آنے سے تمہیں ڈراتے تھے کہیں گے ہاں لیکن عذاب کا حکم (علم ازلی میں) منکرو ں پر ہو چکا تھا'),
  ('ur.ahmedali', 39, 72, 'کہا جائے گا دوزخ کے دروازوں میں داخل ہو جاؤ اس میں سدا رہو گے پس وہ تکبر کرنے والوں کے لیے کیسا برا ٹھکانہ ہے'),
  ('ur.ahmedali', 39, 73, 'اور وہ لوگ جو اپنے رب سے ڈرتے رہے جنت کی طرف گرو ہ گروہ لے جانے جائیں گے یہاں تک کہ جب وہ اس کے پا پہنچ جائیں گے اور اس کے دروازے کھلے ہوئے ہوں گے اور ان سے اس کے داروغہ کہیں گے تم پر سلام ہو تم اچھے لوگ ہو اس میں ہمیشہ کے لیے داخل ہو جاؤ'),
  ('ur.ahmedali', 39, 74, 'اوروہ کہیں گے الله کا شکر ہے جس نے ہم سے اپنا وعدہ سچا کیا اور ہمیں اس زمین کا وارث کر دیا کہ ہم جنت میں جہاں چاہیں رہیں پھر کیا خوب بدلہ ہے عمل کرنے والوں کا'),
  ('ur.ahmedali', 39, 75, 'اور آپ فرشتوں کو حلقہ باندھے ہوئے عرش کے گرد دیکھیں گے اپنے رب کی حمد کے ساتھ تسبیح پڑھ رہے ہیں اور درمیان انصاف سے فیصلہ کیا جائے گا اور سب کہیں گے سب تعریف الله ہی کے لیے ہے جو سارے جہانوں کا رب ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 39, 1, 'Kitap\'ın indirilmesi, güçlü ve Hakim olan Allah katındandır.'),
  ('tr.diyanet', 39, 2, 'Biz sana Kitap\'ı gerçekle indirdik. Öyle ise dini Allah için halis kılarak O\'na kulluk et.'),
  ('tr.diyanet', 39, 3, 'Dikkat edin, halis din Allah\'ındır; O\'nu bırakıp da putlardan dostlar edinenler: "Onlara, bizi Allah\'a yaklaştırsınlar diye kulluk ediyoruz" derler. Doğrusu Allah ayrılığa düştükleri şeylerde aralarında hüküm verecektir. Allah şüphesiz yalancı ve inkarcı kimseyi doğru yola eriştirmez.'),
  ('tr.diyanet', 39, 4, 'Allah çocuk edinmek isteseydi, yaratıklarından dilediğini seçerdi. O münezzehtir, O; gücü her şeye yeten tek Allah\'tır.'),
  ('tr.diyanet', 39, 5, 'Gökleri ve yeri gerçekten yaratan O\'dur. Geceyi gündüze dolar, gündüzü geceye dolar. Her biri belirli bir süreye kadar yörüngelerinde yürüyen güneş ve ayı buyruk altında tutar. Dikkat edin, güçlü olan, çok bağışlayan O\'dur.'),
  ('tr.diyanet', 39, 6, 'Sizi bir tek nefisten yaratmış, sonra ondan eşini varetmiştir; sizin için hayvanlardan sekiz çift meydana getirmiştir; sizi annelerinizin karınlarında üç türlü karanlık içinde, yaratılıştan yaratılışa geçirerek yaratmıştır; işte bu Rabbiniz olan Allah\'tır. Hükümranlık O\'nundur, O\'ndan başka tanrı yoktur. Öyleyken nasıl olur da O\'nu bırakıp başkasına yönelirsiniz?'),
  ('tr.diyanet', 39, 7, 'Eğer inkar ederseniz bilin ki Allah sizden müstağnidir. Kullarının inkarından hoşnut olmaz. Eğer şükrederseniz sizden hoşnut olur. Hiçbir günahkar diğerinin günahını yüklenmez. Sonunda dönüşünüz Rabbinizedir; yaptıklarınızı o zaman size haber verir; çünkü O, kalblerde olanı bilir.'),
  ('tr.diyanet', 39, 8, 'İnsanın başına bir sıkıntı gelince Rabbine yönelerek O\'na yalvarır. Sonra Allah, katından bir nimet verince önceden kime yalvarmış olduğunu unutuverir; Allah\'ın yolundan saptırmak için O\'na eşler koşar. De ki: "İnkarınla az bir müddet zevklen, şüphesiz sen cehennemliksin."'),
  ('tr.diyanet', 39, 9, 'Geceleyin secde ederek ve ayakta durarak boyun büken, ahiretten çekinen, Rabbinin rahmetini dileyen kimse inkar eden kimse gibi olur mu? De ki: "Bilenlerle bilmeyenler bir olur mu? Doğrusu ancak akıl sahipleri öğüt alırlar."'),
  ('tr.diyanet', 39, 10, 'Şöyle de: "Ey inanan kullarım! Rabbinize karşı gelmekten sakının; bu dünyada iyilik yapanlara iyilik vardır. Allah\'ın yarattığı yeryüzü geniştir. Yalnız sabredenlere, ecirleri sonsuz olarak ödenecektir."'),
  ('tr.diyanet', 39, 11, 'De ki: "Dini Allah\'a halis kılarak O\'na kulluk etmekle emrolundum."'),
  ('tr.diyanet', 39, 12, '"Ve Müslümanların ilki olmakla emrolundum."'),
  ('tr.diyanet', 39, 13, 'De ki: "Rabbime karşı gelirsem, doğrusu büyük günün azabından korkarım."'),
  ('tr.diyanet', 39, 14, 'De ki: "Ben, dinimi Allah\'a halis kılarak O\'na kulluk ederim;'),
  ('tr.diyanet', 39, 15, 'Ey Allah\'a eş koşanlar! Siz de O\'ndan başka dilediğinize kulluk edin." De ki: Hüsrana uğrayanlar kıyamet günü kendilerini ve ailelerini hüsrana sokanlardır. Dikkat edin, işte apaçık hüsran budur.'),
  ('tr.diyanet', 39, 16, 'Onlara üstlerinden kat kat ateş vardır. Allah kullarını bununla korkutur. Ey kullarım, Benden sakının.'),
  ('tr.diyanet', 39, 17, 'Şeytana ve putlara kulluk etmekten kaçınıp, Allah\'a yönelenlere, onlara, müjde vardır. Dinleyip de, en güzel söze uyan kullarımı müjdele. İşte Allah\'ın doğru yola eriştirdiği onlardır. İşte onlar akıl sahipleridir.'),
  ('tr.diyanet', 39, 18, 'Şeytana ve putlara kulluk etmekten kaçınıp, Allah\'a yönelenlere, onlara, müjde vardır. Dinleyip de, en güzel söze uyan kullarımı müjdele. İşte Allah\'ın doğru yola eriştirdiği onlardır. İşte onlar akıl sahipleridir.'),
  ('tr.diyanet', 39, 19, 'Hakkında azap sözü gerçekleşmiş kimseyi, ateşte olanı sen mi kurtaracaksın?'),
  ('tr.diyanet', 39, 20, 'Fakat, Rablerinden sakınanlara, üst üste bina edilmiş köşkler vardır; altlarından ırmaklar akar. Bu, Allah\'ın verdiği sözdür, Allah verdiği sözden caymaz.'),
  ('tr.diyanet', 39, 21, 'Allah\'ın gökten bir su indirip, onu yerdeki kaynaklara yerleştiren, sonra onunla çeşitli renklerde ekinler yetiştiren olduğunu görmez misin? Sonra onları kurutur ki sen de onları sapsarı görürsün, sonra da çer çöpe çevirir. Şüphesiz bunlarda, akıl sahipleri için öğüt vardır.'),
  ('tr.diyanet', 39, 22, 'Allah kimin gönlünü İslam\'a açmışsa, o, Rabbi katından bir nur üzere olmaz mı? Kalbleri Allah\'ı anmak hususunda katılaşmış olanlara yazıklar olsun; işte bunlar apaçık sapıklıktadırlar.'),
  ('tr.diyanet', 39, 23, 'Allah, ayetleri birbirine benzeyen ve yer yer tekrar eden Kitap\'ı sözlerin en güzeli olarak indirmiştir. Rablerinden korkanların, bu Kitap\'tan tüyleri ürperir, sonra hem derileri ve hem de kalbleri Allah\'ın zikrine yumuşar ve yatışır. İşte bu Kitap, Allah\'ın doğruluk rehberidir, onunla istediğini doğru yola eriştirir. Allah kimi de saptırırsa artık ona yol gösteren bulunmaz.'),
  ('tr.diyanet', 39, 24, 'Kıyamet günü kötü azaptan yüzünü korumaya çalışan kimse, güven içinde olan kimse gibi midir? Zalimlere: "Kazandıklarınızın karşılığını tadın" denir.'),
  ('tr.diyanet', 39, 25, 'Onlardan öncekiler de peygamberleri yalanlamışlardı da farkına varmadıkları yerden onlara bir azap çatmıştı.'),
  ('tr.diyanet', 39, 26, 'Allah onlara, dünya hayatında rezilliği tattırdı; ahiret azabı daha büyüktür. Keşke bilseler!'),
  ('tr.diyanet', 39, 27, 'Biz bu Kuran\'da insanlara her türlü misali, belki öğüt alırlar diye, and olsun ki verdik.'),
  ('tr.diyanet', 39, 28, 'O, eğriliği olmayan, Arapça bir Kuran\'dır. Belki sakınırlar.'),
  ('tr.diyanet', 39, 29, 'Allah, geçimsiz efendileri olan bir adamla, yalnız bir kişiye bağlı olan bir adamı misal olarak verir. Bu ikisi eşit midir? Övülmek Allah içindir, fakat çoğu bilmezler.'),
  ('tr.diyanet', 39, 30, 'Şüphesiz sen de öleceksin, onlar da ölecekler.'),
  ('tr.diyanet', 39, 31, 'Ey insanlar! Sonra siz, kıyamet günü Rabbinizin huzurunda duruşmaya çıkacaksınız.'),
  ('tr.diyanet', 39, 32, 'Allah\'a karşı yalan uydurandan, kendisine gelmiş gerçeği yalan sayandan daha zalim olan kimdir? İnkarcılar için cehennemde dur durak olmaz olur mu?'),
  ('tr.diyanet', 39, 33, 'Gerçeği getiren ve onu doğrulayanlar, işte onlar, Allah\'a karşı gelmekten sakınmış olanlardır.'),
  ('tr.diyanet', 39, 34, 'Onlara, Rablerinin katında diledikleri şeyler vardır, bu, iyilerin mükafatıdır.'),
  ('tr.diyanet', 39, 35, 'Zira Allah, onların yaptıkları kötülükleri örter, onlara, işledikleri şeylerin en güzel karşılıklarını verir.'),
  ('tr.diyanet', 39, 36, 'Allah, kuluna yetmez mi? Seni O\'ndan başka şeylerle korkutuyorlar. Allah\'ın, saptırdığını doğru yola koyacak yoktur.'),
  ('tr.diyanet', 39, 37, 'Allah\'ın doğru yola eriştirdiğini de saptıracak yoktur. Allah, güçlü olan, öç alabilen değil midir?'),
  ('tr.diyanet', 39, 38, 'And olsun ki, onlara, "Gökleri ve yeri yaratan kimdir?" diye sorsan: "Allah\'tır" derler. De ki: "Öyleyse bana bildirin, Allah bana bir zarar vermek isterse, Allah\'ı bırakıp da taptıklarınız, O\'nun verdiği zararı giderebilir mi? Yahut bana bir rahmetdilerse, O\'nun rahmetini önleyebilir mi?" De ki: "Allah bana yeter; güvenenler O\'na güvenir."'),
  ('tr.diyanet', 39, 39, 'De ki: "Ey milletim! Durumunuzun gerektirdiğini yapın; doğrusu ben de yapacağım. Kendisini rezil edecek azap kime gelecek, kime sürekli azap inecek bileceksiniz."'),
  ('tr.diyanet', 39, 40, 'De ki: "Ey milletim! Durumunuzun gerektirdiğini yapın; doğrusu ben de yapacağım. Kendisini rezil edecek azap kime gelecek, kime sürekli azap inecek bileceksiniz."'),
  ('tr.diyanet', 39, 41, 'Doğrusu Biz, insanlar için Kitap\'ı gerçekle sana indirdik; kim doğru yolda ise bu kendi lehinedir; sapıtan da kendi aleyhine sapıtmış olur. Sen onlara vekil değilsin.'),
  ('tr.diyanet', 39, 42, 'Allah, öleceklerin ölümleri anında, ölmeyeceklerin de uykuları esnasında ruhlarını alır. Ölmelerine hükmettiği kimselerinkini tutar, diğerlerini bir süreye kadar salıverir. Doğrusu bunda düşünen kimseler için dersler vardır.'),
  ('tr.diyanet', 39, 43, 'Yoksa Allah\'tan başka şefaatçiler mi edindiler? De ki: "Onlar bir şeye sahip olmadıkları, akıl da edemedikleri halde mi şefaat edecekler?"'),
  ('tr.diyanet', 39, 44, 'De ki: "Bütün şefaat Allah\'ın iznine bağlıdır. Göklerin ve yerin hükümranlığı O\'nundur. Sonra O\'na döneceksiniz."'),
  ('tr.diyanet', 39, 45, 'Allah tek olarak anıldığı zaman, ahirete inanmayanların kalbleri nefretle çarpar, ama Allah\'tan başka putlar anıldığı zaman hemen yüzleri güler.'),
  ('tr.diyanet', 39, 46, 'De ki: "Ey göklerin, yerin yaratanı, görülmeyeni ve görüleni bilen Allah\'ım! Kullarının ayrılığa düştükleri şeyler hakkında aralarında Sen hükmedeceksin."'),
  ('tr.diyanet', 39, 47, 'Yeryüzünde olanların hepsi ve bir misli daha zalimlerin olmuş olsa, kıyamet günündeki kötü azap için fidye verseler kabul edilmez. Allah katından onlara, hiç hesaplamadıkları şeyler beliriverir.'),
  ('tr.diyanet', 39, 48, 'Onlara, işledikleri kötü şeyler belli olur; alaya aldıkları şeyler de kendilerini çepeçevre sarar.'),
  ('tr.diyanet', 39, 49, 'İnsanın başına bir sıkıntı gelince Bize yalvarır. Sonra katımızdan ona bir nimet verdiğimiz zaman: "Bu bana bilgimden dolayı verilmiştir" der. Hayır; o bir imtihandır, fakat çokları bilmezler.'),
  ('tr.diyanet', 39, 50, 'Bunu onlardan öncekiler de söylemişti, ama kazandıkları şeyler onlara fayda vermedi.'),
  ('tr.diyanet', 39, 51, 'Bunun için, işledikleri kötülükler başlarına geldi. Bunlar içinde zulmedenlerin de kazandıkları kötülükler başlarına gelecektir. Bu hususta Allah\'ı aciz bırakamazlar.'),
  ('tr.diyanet', 39, 52, 'Allah\'ın rızkı dilediğine yaydığını ve kısıp bir ölçüye göre verdiğini bilmezler mi? Doğrusu bunda, inanan kimseler için dersler vardır.'),
  ('tr.diyanet', 39, 53, 'De ki: "Ey kendilerine kötülük edip aşırı giden kullarım! Allah\'ın rahmetinden umudunuzu kesmeyin. Doğrusu Allah günahların hepsini bağışlar. Çünkü O, bağışlayandır, merhametlidir."'),
  ('tr.diyanet', 39, 54, '"Rabbinize yönelin. Azap size gelmeden önce O\'na teslim olun; sonra yardım görmezsiniz."'),
  ('tr.diyanet', 39, 55, '"Size ansızın, farkına varmadan azap gelmeden önce Rabbinizden size indirilen en güzel söze, Kuran\'a uyun."'),
  ('tr.diyanet', 39, 56, 'Kişinin: "Allah\'a karşı aşırı gitmemden ötürü bana yazıklar olsun. Gerçekten ben alaya alanlardandım" diyeceği günden sakının.'),
  ('tr.diyanet', 39, 57, 'Veya, "Allah beni doğru yola eriştirseydi sakınanlardan olurdum" diyeceği, yahut, azabı gördüğünde: "Keşke benim için dönüş imkanı bulunsa da iyilerden olsam" diyeceği günden sakının.'),
  ('tr.diyanet', 39, 58, 'Veya, "Allah beni doğru yola eriştirseydi sakınanlardan olurdum" diyeceği, yahut, azabı gördüğünde: "Keşke benim için dönüş imkanı bulunsa da iyilerden olsam" diyeceği günden sakının.'),
  ('tr.diyanet', 39, 59, 'Ey insanoğlu! Evet; ayetlerim sana gelmişti de onları yalanlamış, büyüklük taslamış ve inkarcılardan olmuştun.'),
  ('tr.diyanet', 39, 60, 'Allah\'a karşı yalan uyduranların, kıyamet günü, yüzlerinin simsiyah olduğunu görürsün. Böbürlenenler için cehennemde bir durak olmaz olur mu?'),
  ('tr.diyanet', 39, 61, 'Allah, sakınanları başarılarından ötürü kurtarır. Onlara hiçbir kötülük gelmez; onlar üzülmezler.'),
  ('tr.diyanet', 39, 62, 'Allah her şeyin yaratanıdır. O her şeye Vekil\'dir.'),
  ('tr.diyanet', 39, 63, 'Göklerin ve yerin kilitleri O\'nundur. Allah\'ın ayetlerini inkar edenler, işte onlar hüsrandadırlar.'),
  ('tr.diyanet', 39, 64, 'De ki: "Ey cahiller! Bana, Allah\'tan başkasına kulluk etmemi mi emredersiniz?"'),
  ('tr.diyanet', 39, 65, 'And olsun ki sana da, senden önceki peygamberlere de vahyolunmuştur: "And olsun, eğer Allah\'a ortak koşarsan işlerin şüphesiz boşa gider ve hüsranda kalanlardan olursun."'),
  ('tr.diyanet', 39, 66, '"Hayır; yalnız Allah\'a kulluk et ve şukredenlerden ol."'),
  ('tr.diyanet', 39, 67, 'Onlar Allah\'ı gereği gibi değerlendiremediler. Bütün yeryüzü, kıyamet günü O\'nun avucundadır; gökler O\'nun kudretiyle dürülmüş olacaktır. O, putperestlerin ortak koşmalarından yüce ve münezzehtir.'),
  ('tr.diyanet', 39, 68, 'Sura üflenince, Allah\'ın dilediği bir yana, göklerde olanlar, yerde olanlar hepsi düşüp ölür. Sonra Sura bir daha üflenince hemen ayağa kalkıp bakışır dururlar.'),
  ('tr.diyanet', 39, 69, 'Yeryüzü Rabbinin nuruyla aydınlanır, kitap açılır, peygamberler ve şahidler getirilir ve onlara haksızlık yapılmadan, aralarında adaletle hüküm verilir.'),
  ('tr.diyanet', 39, 70, 'Her kişiye işlediği ödenir. Esasen Allah onların yaptıklarını en iyi bilendir.'),
  ('tr.diyanet', 39, 71, 'İnkar edenler, bölük bölük cehenneme sürülür. Oraya vardıklarında kapıları açılır; bekçileri onlara: "Size içinizden Rabbinizin ayetlerini okuyan ve bugüne kavuşacağınızı ihtar eden peygamberler gelmedi mi" derler. "Evet geldi" derler. Lakin azap sözü inkarcıların aleyhine gerçekleşir.'),
  ('tr.diyanet', 39, 72, 'Onlara: "Temelli kalacağınız cehennemin kapılarından girin; böbürlenenlerin durağı ne kötüdür!" denir.'),
  ('tr.diyanet', 39, 73, 'Rablerine karşı gelmekten sakınanlar, bölük bölük cennete götürülürler. Oraya varıp da kapıları açıldığında, bekçileri onlara: "Selam size, hoş geldiniz! Temelli olarak buraya girin" derler.'),
  ('tr.diyanet', 39, 74, 'Onlar: "Bize verdiği sözde duran ve bizi bu yere varis kılan Allah\'a hamdolsun. Cennette istediğimiz yerde oturabiliriz. Yararlı iş işleyenlerin ecri ne güzelmiş!" derler.'),
  ('tr.diyanet', 39, 75, 'Melekleri, arşın etrafını çevirmiş oldukları halde, Rablerini hamd ile överken görürsün. Artık insanların aralarında adaletle hüküm olunmuştur. "Övgü, Alemlerin Rabbi olan Allah içindir" denir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 39, 1, 'Kitab (Al Quran ini) diturunkan oleh Allah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 39, 2, 'Sesunguhnya Kami menurunkan kepadamu Kitab (Al Quran) dengan (membawa) kebenaran. Maka sembahlah Allah dengan memurnikan ketaatan kepada-Nya.'),
  ('id.indonesian', 39, 3, 'Ingatlah, hanya kepunyaan Allah-lah agama yang bersih (dari syirik). Dan orang-orang yang mengambil pelindung selain Allah (berkata): "Kami tidak menyembah mereka melainkan supaya mereka mendekatkan kami kepada Allah dengan sedekat-dekatnya". Sesungguhnya Allah akan memutuskan di antara mereka tentang apa yang mereka berselisih padanya. Sesungguhnya Allah tidak menunjuki orang-orang yang pendusta dan sangat ingkar.'),
  ('id.indonesian', 39, 4, 'Kalau sekiranya Allah hendak mengambil anak, tentu Dia akan memilih apa yang dikehendaki-Nya di antara ciptaan-ciptaan yang telah diciptakan-Nya. Maha Suci Allah. Dialah Allah Yang Maha Esa lagi Maha Mengalahkan.'),
  ('id.indonesian', 39, 5, 'Dia menciptakan langit dan bumi dengan (tujuan) yang benar; Dia menutupkan malam atas siang dan menutupkan siang atas malam dan menundukkan matahari dan bulan, masing-masing berjalan menurut waktu yang ditentukan. Ingatlah Dialah Yang Maha Perkasa lagi Maha Pengampun.'),
  ('id.indonesian', 39, 6, 'Dia menciptakan kamu dari seorang diri kemudian Dia jadikan daripadanya isterinya dan Dia menurunkan untuk kamu delapan ekor yang berpasangan dari binatang ternak. Dia menjadikan kamu dalam perut ibumu kejadian demi kejadian dalam tiga kegelapan. Yang (berbuat) demikian itu adalah Allah, Tuhan kamu, Tuhan Yang mempunyai kerajaan. Tidak ada Tuhan selain Dia; maka bagaimana kamu dapat dipalingkan?'),
  ('id.indonesian', 39, 7, 'Jika kamu kafir maka sesungguhnya Allah tidak memerlukan (iman)mu dan Dia tidak meridhai kekafiran bagi hamba-Nya; dan jika kamu bersyukur, niscaya Dia meridhai bagimu kesyukuranmu itu; dan seorang yang berdosa tidak akan memikul dosa orang lain. Kemudian kepada Tuhanmulah kembalimu lalu Dia memberitakan kepadamu apa yang telah kamu kerjakan. Sesungguhnya Dia Maha Mengetahui apa yang tersimpan dalam (dada)mu.'),
  ('id.indonesian', 39, 8, 'Dan apabila manusia itu ditimpa kemudharatan, dia memohon (pertolongan) kepada Tuhannya dengan kembali kepada-Nya; kemudian apabila Tuhan memberikan nikmat-Nya kepadanya lupalah dia akan kemudharatan yang pernah dia berdoa (kepada Allah) untuk (menghilangkannya) sebelum itu, dan dia mengada-adakan sekutu-sekutu bagi Allah untuk menyesatkan (manusia) dari jalan-Nya. Katakanlah: "Bersenang-senanglah dengan kekafiranmu itu sementara waktu; sesungguhnya kamu termasuk penghuni neraka".'),
  ('id.indonesian', 39, 9, '(Apakah kamu hai orang musyrik yang lebih beruntung) ataukah orang yang beribadat di waktu-waktu malam dengan sujud dan berdiri, sedang ia takut kepada (azab) akhirat dan mengharapkan rahmat Tuhannya? Katakanlah: "Adakah sama orang-orang yang mengetahui dengan orang-orang yang tidak mengetahui?" Sesungguhnya orang yang berakallah yang dapat menerima pelajaran.'),
  ('id.indonesian', 39, 10, 'Katakanlah: "Hai hamba-hamba-Ku yang beriman. bertakwalah kepada Tuhanmu". Orang-orang yang berbuat baik di dunia ini memperoleh kebaikan. Dan bumi Allah itu adalah luas. Sesungguhnya hanya orang-orang yang bersabarlah Yang dicukupkan pahala mereka tanpa batas.'),
  ('id.indonesian', 39, 11, 'Katakanlah: "Sesungguhnya aku diperintahkan supaya menyembah Allah dengan memurnikan ketaatan kepada-Nya dalam (menjalankan) agama.'),
  ('id.indonesian', 39, 12, 'Dan aku diperintahkan supaya menjadi orang yang pertama-tama berserah diri".'),
  ('id.indonesian', 39, 13, 'Katakanlah: "Sesungguhnya aku takut akan siksaan hari yang besar jika aku durhaka kepada Tuhanku".'),
  ('id.indonesian', 39, 14, 'Katakanlah: "Hanya Allah saja Yang aku sembah dengan memurnikan ketaatan kepada-Nya dalam (menjalankan) agamaku".'),
  ('id.indonesian', 39, 15, 'Maka sembahlah olehmu (hai orang-orang musyrik) apa yang kamu kehendaki selain Dia. Katakanlah: "Sesungguhnya orang-orang yang rugi ialah orang-orang yang merugikan diri mereka sendiri dan keluarganya pada hari kiamat". Ingatlah yang demikian itu adalah kerugian yang nyata.'),
  ('id.indonesian', 39, 16, 'Bagi mereka lapisan-lapisan dari api di atas mereka dan di bawah merekapun lapisan-lapisan (dari api). Demikianlah Allah mempertakuti hamba-hamba-Nya dengan azab itu. Maka bertakwalah kepada-Ku hai hamba-hamba-Ku.'),
  ('id.indonesian', 39, 17, 'Dan orang-orang yang menjauhi thaghut (yaitu) tidak menyembahnya dan kembali kepada Allah, bagi mereka berita gembira; sebab itu sampaikanlah berita itu kepada hamba-hamba-Ku,'),
  ('id.indonesian', 39, 18, 'yang mendengarkan perkataan lalu mengikuti apa yang paling baik di antaranya. Mereka itulah orang-orang yang telah diberi Allah petunjuk dan mereka itulah orang-orang yang mempunyai akal.'),
  ('id.indonesian', 39, 19, 'Apakah (kamu hendak merubah nasib) orang-orang yang telah pasti ketentuan azab atasnya? Apakah kamu akan menyelamatkan orang yang berada dalam api neraka?'),
  ('id.indonesian', 39, 20, 'Tetapi orang-orang yang bertakwa kepada Tuhannya mereka mendapat tempat-tempat yang tinggi, di atasnya dibangun pula tempat-tempat yang tinggi yang di bawahnya mengalir sungai-sungai. Allah telah berjanji dengan sebenar-benarnya. Allah tidak akan memungkiri janji-Nya.'),
  ('id.indonesian', 39, 21, 'Apakah kamu tidak memperhatikan, bahwa sesungguhnya Allah menurunkan air dari langit, maka diaturnya menjadi sumber-sumber air di bumi kemudian ditumbuhkan-Nya dengan air itu tanam-tanaman yang bermacam-macam warnanya, lalu menjadi kering lalu kamu melihatnya kekuning-kuningan, kemudian dijadikan-Nya hancur berderai-derai. Sesungguhnya pada yang demikian itu benar-benar terdapat pelajaran bagi orang-orang yang mempunyai akal.'),
  ('id.indonesian', 39, 22, 'Maka apakah orang-orang yang dibukakan Allah hatinya untuk (menerima) agama Islam lalu ia mendapat cahaya dari Tuhannya (sama dengan orang yang membatu hatinya)? Maka kecelakaan yang besarlah bagi mereka yang telah membatu hatinya untuk mengingat Allah. Mereka itu dalam kesesatan yang nyata.'),
  ('id.indonesian', 39, 23, 'Allah telah menurunkan perkataan yang paling baik (yaitu) Al Quran yang serupa (mutu ayat-ayatnya) lagi berulang-ulang, gemetar karenanya kulit orang-orang yang takut kepada Tuhannya, kemudian menjadi tenang kulit dan hati mereka di waktu mengingat Allah. Itulah petunjuk Allah, dengan kitab itu Dia menunjuki siapa yang dikehendaki-Nya. Dan barangsiapa yang disesatkan Allah, niscaya tak ada baginya seorang pemimpinpun.'),
  ('id.indonesian', 39, 24, 'Maka apakah orang-orang yang menoleh dengan mukanya menghindari azab yang buruk pada hari kiamat (sama dengan orang mukmin yang tidak kena azab)? Dan dikatakan kepada orang-orang yang zalim: "Rasakanlah olehmu balasan apa yang telah kamu kerjakan".'),
  ('id.indonesian', 39, 25, 'Orang-orang yang sebelum mereka telah mendustakan (rasul-rasul), maka datanglah kepada mereka azab dari arah yang tidak mereka sangka.'),
  ('id.indonesian', 39, 26, 'Maka Allah merasakan kepada mereka kehinaan pada kehidupan dunia. Dan sesungguhnya azab pada hari akhirat lebih besar kalau mereka mengetahui.'),
  ('id.indonesian', 39, 27, 'Sesungguhnya telah Kami buatkan bagi manusia dalam Al Quran ini setiap macam perumpamaan supaya mereka dapat pelajaran.'),
  ('id.indonesian', 39, 28, '(Ialah) Al Quran dalam bahasa Arab yang tidak ada kebengkokan (di dalamnya) supaya mereka bertakwa.'),
  ('id.indonesian', 39, 29, 'Allah membuat perumpamaan (yaitu) seorang laki-laki (budak) yang dimiliki oleh beberapa orang yang berserikat yang dalam perselisihan dan seorang budak yang menjadi milik penuh dari seorang laki-laki (saja); Adakah kedua budak itu sama halnya? Segala puji bagi Allah tetapi kebanyakan mereka tidak mengetahui.'),
  ('id.indonesian', 39, 30, 'Sesungguhnya kamu akan mati dan sesungguhnya mereka akan mati (pula).'),
  ('id.indonesian', 39, 31, 'Kemudian sesungguhnya kamu pada hari kiamat akan berbantah-bantah di hadapan Tuhanmu.'),
  ('id.indonesian', 39, 32, 'Maka siapakah yang lebih zalim daripada orang yang membuat-buat dusta terhadap Allah dan mendustakan kebenaran ketika datang kepadanya? Bukankah di neraka Jahannam tersedia tempat tinggal bagi orang-orang yang kafir?'),
  ('id.indonesian', 39, 33, 'Dan orang yang membawa kebenaran (Muhammad) dan membenarkannya, mereka itulah orang-orang yang bertakwa.'),
  ('id.indonesian', 39, 34, 'Mereka memperoleh apa yang mereka kehendaki pada sisi Tuhan mereka. Demikianlah balasan orang-orang yang berbuat baik,'),
  ('id.indonesian', 39, 35, 'agar Allah akan menutupi (mengampuni) bagi mereka perbuatan yang paling buruk yang mereka kerjakan dan membalas mereka dengan upah yang lebih baik dari apa yang telah mereka kerjakan.'),
  ('id.indonesian', 39, 36, 'Bukankah Allah cukup untuk melindungi hamba-hamba-Nya. Dan mereka mempertakuti kamu dengan (sembahan-sembahan) yang selain Allah? Dan siapa yang disesatkan Allah maka tidak seorangpun pemberi petunjuk baginya.'),
  ('id.indonesian', 39, 37, 'Dan barangsiapa yang diberi petunjuk oleh Allah, maka tidak seorangpun yang dapat menyesatkannya. Bukankah Allah Maha Perkasa lagi mempunyai (kekuasaan untuk) mengazab?'),
  ('id.indonesian', 39, 38, 'Dan sungguh jika kamu bertanya kepada mereka: "Siapakah yang menciptakan langit dan bumi?", niscaya mereka menjawab: "Allah". Katakanlah: "Maka terangkanlah kepadaku tentang apa yang kamu seru selain Allah, jika Allah hendak mendatangkan kemudharatan kepadaku, apakah berhala-berhalamu itu dapat menghilangkan kemudharatan itu, atau jika Allah hendak memberi rahmat kepadaku, apakah mereka dapat menahan rahmat-Nya?. Katakanlah: "Cukuplah Allah bagiku". Kepada-Nya-lah bertawakkal orang-orang yang berserah diri.'),
  ('id.indonesian', 39, 39, 'Katakanlah: "Hai kaumku, bekerjalah sesuai dengan keadaanmu, sesungguhnya aku akan bekerja (pula), maka kelak kamu akan mengetahui,'),
  ('id.indonesian', 39, 40, 'siapa yang akan mendapat siksa yang menghinakannya dan lagi ditimpa oleh azab yang kekal".'),
  ('id.indonesian', 39, 41, 'Sesungguhnya Kami menurunkan kepadamu Al Kitab (Al Quran) untuk manusia dengan membawa kebenaran; siapa yang mendapat petunjuk maka (petunjuk itu) untuk dirinya sendiri, dan siapa yang sesat maka sesungguhnya dia semata-mata sesat buat (kerugian) dirinya sendiri, dan kamu sekali-kali bukanlah orang yang bertanggung jawab terhadap mereka.'),
  ('id.indonesian', 39, 42, 'Allah memegang jiwa (orang) ketika matinya dan (memegang) jiwa (orang) yang belum mati di waktu tidurnya; maka Dia tahanlah jiwa (orang) yang telah Dia tetapkan kematiannya dan Dia melepaskan jiwa yang lain sampai waktu yang ditetapkan. Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan Allah bagi kaum yang berfikir.'),
  ('id.indonesian', 39, 43, 'Bahkan mereka mengambil pemberi syafa\'at selain Allah. Katakanlah: "Dan apakah (kamu mengambilnya juga) meskipun mereka tidak memiliki sesuatupun dan tidak berakal?"'),
  ('id.indonesian', 39, 44, 'Katakanlah: "Hanya kepunyaan Allah syafa\'at itu semuanya. Kepunyaan-Nya kerajaan langit dan bumi. Kemudian kepada-Nya-lah kamu dikembalikan"'),
  ('id.indonesian', 39, 45, 'Dan apabila hanya nama Allah saja disebut, kesallah hati orang-orang yang tidak beriman kepada kehidupan akhirat; dan apabila nama sembahan-sembahan selain Allah yang disebut, tiba-tiba mereka bergirang hati.'),
  ('id.indonesian', 39, 46, 'Katakanlah: "Wahai Allah, Pencipta langit dan bumi, Yang mengetahui barang ghaib dan yang nyata, Engkaulah Yang memutuskan antara hamba-hamba-Mu tentang apa yang selalu mereka memperselisihkannya".'),
  ('id.indonesian', 39, 47, 'Dan sekiranya orang-orang yang zalim mempunyai apa yang ada di bumi semuanya dan (ada pula) sebanyak itu besertanya, niscaya mereka akan menebus dirinya dengan itu dari siksa yang buruk pada hari kiamat. Dan jelaslah bagi mereka azab dari Allah yang belum pernah mereka perkirakan.'),
  ('id.indonesian', 39, 48, 'Dan (jelaslah) bagi mereka akibat buruk dari apa yang telah mereka perbuat dan mereka diliputi oleh pembalasan yang mereka dahulu selalu memperolok-olokkannya.'),
  ('id.indonesian', 39, 49, 'Maka apabila manusia ditimpa bahaya ia menyeru Kami, kemudian apabila Kami berikan kepadanya nikmat dari Kami ia berkata: "Sesungguhnya aku diberi nikmat itu hanyalah karena kepintaranku". Sebenarnya itu adalah ujian, tetapi kebanyakan mereka itu tidak mengetahui.'),
  ('id.indonesian', 39, 50, 'Sungguh orang-orang yang sebelum mereka (juga) telah mengatakan itu pula, maka tiadalah berguna bagi mereka apa yang dahulu mereka usahakan.'),
  ('id.indonesian', 39, 51, 'Maka mereka ditimpa oleh akibat buruk dari apa yang mereka usahakan. Dan orang-orang yang zalim di antara mereka akan ditimpa akibat buruk dari usahanya dan mereka tidak dapat melepaskan diri.'),
  ('id.indonesian', 39, 52, 'Dan tidakkah mereka mengetahui bahwa Allah melapangkan rezeki dan menyempitkannya bagi siapa yang dikehendaki-Nya? Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan Allah bagi kaum yang beriman.'),
  ('id.indonesian', 39, 53, 'Katakanlah: "Hai hamba-hamba-Ku yang malampaui batas terhadap diri mereka sendiri, janganlah kamu berputus asa dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa semuanya. Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 39, 54, 'Dan kembalilah kamu kepada Tuhanmu, dan berserah dirilah kepada-Nya sebelum datang azab kepadamu kemudian kamu tidak dapat ditolong (lagi).'),
  ('id.indonesian', 39, 55, 'Dan ikutilah sebaik-baik apa yang telah diturunkan kepadamu dari Tuhanmu sebelum datang azab kepadamu dengan tiba-tiba, sedang kamu tidak menyadarinya,'),
  ('id.indonesian', 39, 56, 'supaya jangan ada orang yang mengatakan: "Amat besar penyesalanku atas kelalaianku dalam (menunaikan kewajiban) terhadap Allah, sedang aku sesungguhnya termasuk orang-orang yang memperolok-olokkan (agama Allah),'),
  ('id.indonesian', 39, 57, 'atau supaya jangan ada yang berkata: \'Kalau sekiranya Allah memberi petunjuk kepadaku tentulah aku termasuk orang-orang yang bertakwa\'.'),
  ('id.indonesian', 39, 58, 'Atau supaya jangan ada yang berkata ketika ia melihat azab \'Kalau sekiranya aku dapat kemnbali (ke dunia), niscaya aku akan termasuk orang-orang berbuat baik\'.'),
  ('id.indonesian', 39, 59, '(Bukan demikian) sebenarya telah datang keterangan-keterangan-Ku kepadamu lalu kamu mendustakannya dan kamu menyombongkan diri dan adalah kamu termasuk orang-orang yang kafir".'),
  ('id.indonesian', 39, 60, 'Dan pada hari kiamat kamu akan melihat orang-orang yang berbuat dusta terhadap Allah, mukanya menjadi hitam. Bukankah dalam neraka Jahannam itu ada tempat bagi orang-orang yang menyombongkan diri?'),
  ('id.indonesian', 39, 61, 'Dan Allah menyelamatkan orang-orang yang bertakwa karena kemenangan mereka, mereka tiada disentuh oleh azab (neraka dan tidak pula) mereka berduka cita.'),
  ('id.indonesian', 39, 62, 'Allah menciptakan segala sesuatu dan Dia memelihara segala sesuatu.'),
  ('id.indonesian', 39, 63, 'Kepunyaan-Nya-lah kunci-kunci (perbendaharaan) langit dan bumi. Dan orang-orang yang kafir terhadap ayat-ayat Allah, mereka itulah orang-orang yang merugi.'),
  ('id.indonesian', 39, 64, 'Katakanlah: "Maka apakah kamu menyuruh aku menyembah selain Allah, hai orang-orang yang tidak berpengetahuan?"'),
  ('id.indonesian', 39, 65, 'Dan sesungguhnya telah diwahyukan kepadamu dan kepada (nabi-nabi) yang sebelummu. "Jika kamu mempersekutukan (Tuhan), niscaya akan hapuslah amalmu dan tentulah kamu termasuk orang-orang yang merugi.'),
  ('id.indonesian', 39, 66, 'Karena itu, maka hendaklah Allah saja kamu sembah dan hendaklah kamu termasuk orang-orang yang bersyukur".'),
  ('id.indonesian', 39, 67, 'Dan mereka tidak mengagungkan Allah dengan pengagungan yang semestinya padahal bumi seluruhnya dalam genggaman-Nya pada hari kiamat dan langit digulung dengan tangan kanan-Nya. Maha Suci Tuhan dan Maha Tinggi Dia dari apa yang mereka persekutukan.'),
  ('id.indonesian', 39, 68, 'Dan ditiuplah sangkakala, maka matilah siapa yang di langit dan di bumi kecuali siapa yang dikehendaki Allah. Kemudian ditiup sangkakala itu sekali lagi maka tiba-tiba mereka berdiri menunggu (putusannya masing-masing).'),
  ('id.indonesian', 39, 69, 'Dan terang benderanglah bumi (padang mahsyar) dengan cahaya (keadilan) Tuhannya; dan diberikanlah buku (perhitungan perbuatan masing-masing) dan didatangkanlah para nabi dan saksi-saksi dan diberi keputusan di antara mereka dengan adil, sedang mereka tidak dirugikan.'),
  ('id.indonesian', 39, 70, 'Dan disempurnakan bagi tiap-tiap jiwa (balasan) apa yang telah dikerjakannya dan Dia lebih mengetahui apa yang mereka kerjakan.'),
  ('id.indonesian', 39, 71, 'Orang-orang kafir dibawa ke neraka Jahannam berombong-rombongan. Sehingga apabila mereka sampai ke neraka itu dibukakanlah pintu-pintunya dan berkatalah kepada mereka penjaga-penjaganya: "Apakah belum pernah datang kepadamu rasul-rasul di antaramu yang membacakan kepadamu ayat-ayat Tuhanmu dan memperingatkan kepadamu akan pertemuan dengan hari ini?" Mereka menjawab: "Benar (telah datang)". Tetapi telah pasti berlaku ketetapan azab terhadap orang-orang yang kafir.'),
  ('id.indonesian', 39, 72, 'Dikatakan (kepada mereka): "Masukilah pintu-pintu neraka Jahannam itu, sedang kamu kekal di dalamnya" Maka neraka Jahannam itulah seburuk-buruk tempat bagi orang-orang yang menyombongkan diri.'),
  ('id.indonesian', 39, 73, 'Dan orang-orang yang bertakwa kepada Tuhan dibawa ke dalam surga berombong-rombongan (pula). Sehingga apabila mereka sampai ke surga itu sedang pintu-pintunya telah terbuka dan berkatalah kepada mereka penjaga-penjaganya: "Kesejahteraan (dilimpahkan) atasmu. Berbahagialah kamu! maka masukilah surga ini, sedang kamu kekal di dalamnya".'),
  ('id.indonesian', 39, 74, 'Dan mereka mengucapkan: "Segala puji bagi Allah yang telah memenuhi janji-Nya kepada kami dan telah (memberi) kepada kami tempat ini sedang kami (diperkenankan) menempati tempat dalam surga di mana saja yang kami kehendaki; maka surga itulah sebaik-baik balasan bagi orang-orang yang beramal".'),
  ('id.indonesian', 39, 75, 'Dan kamu (Muhammad) akan melihat malaikat-mmlaikat berlingkar di sekeliling \'Arsy bertasbih sambil memuji Tuhannya; dan diberi putusan di antara hamba-hamba Allah dengan adil dan diucapkan: "Segala puji bagi Allah, Tuhan semesta alam".')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (38, 31, 4001, 'إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ', 455, 23, 182, 0),
  (38, 32, 4002, 'فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ', 455, 23, 182, 0),
  (38, 33, 4003, 'رُدُّوهَا عَلَىَّ ۖ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ', 455, 23, 182, 0),
  (38, 34, 4004, 'وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًۭا ثُمَّ أَنَابَ', 455, 23, 182, 0),
  (38, 35, 4005, 'قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًۭا لَّا يَنۢبَغِى لِأَحَدٍۢ مِّنۢ بَعْدِىٓ ۖ إِنَّكَ أَنتَ ٱلْوَهَّابُ', 455, 23, 182, 0),
  (38, 36, 4006, 'فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ', 455, 23, 182, 0),
  (38, 37, 4007, 'وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٍۢ وَغَوَّاصٍۢ', 455, 23, 182, 0),
  (38, 38, 4008, 'وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ', 455, 23, 182, 0),
  (38, 39, 4009, 'هَٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍۢ', 455, 23, 182, 0),
  (38, 40, 4010, 'وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍۢ', 455, 23, 182, 0),
  (38, 41, 4011, 'وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍۢ وَعَذَابٍ', 455, 23, 182, 0),
  (38, 42, 4012, 'ٱرْكُضْ بِرِجْلِكَ ۖ هَٰذَا مُغْتَسَلٌۢ بَارِدٌۭ وَشَرَابٌۭ', 455, 23, 182, 0),
  (38, 43, 4013, 'وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةًۭ مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 456, 23, 182, 0),
  (38, 44, 4014, 'وَخُذْ بِيَدِكَ ضِغْثًۭا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ ۗ إِنَّا وَجَدْنَٰهُ صَابِرًۭا ۚ نِّعْمَ ٱلْعَبْدُ ۖ إِنَّهُۥٓ أَوَّابٌۭ', 456, 23, 182, 0),
  (38, 45, 4015, 'وَٱذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَٰرِ', 456, 23, 182, 0),
  (38, 46, 4016, 'إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍۢ ذِكْرَى ٱلدَّارِ', 456, 23, 182, 0),
  (38, 47, 4017, 'وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ', 456, 23, 182, 0),
  (38, 48, 4018, 'وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ ۖ وَكُلٌّۭ مِّنَ ٱلْأَخْيَارِ', 456, 23, 182, 0),
  (38, 49, 4019, 'هَٰذَا ذِكْرٌۭ ۚ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍۢ', 456, 23, 182, 0),
  (38, 50, 4020, 'جَنَّٰتِ عَدْنٍۢ مُّفَتَّحَةًۭ لَّهُمُ ٱلْأَبْوَٰبُ', 456, 23, 182, 0),
  (38, 51, 4021, 'مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍۢ كَثِيرَةٍۢ وَشَرَابٍۢ', 456, 23, 182, 0),
  (38, 52, 4022, '۞ وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ', 456, 23, 183, 0),
  (38, 53, 4023, 'هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ', 456, 23, 183, 0),
  (38, 54, 4024, 'إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ', 456, 23, 183, 0),
  (38, 55, 4025, 'هَٰذَا ۚ وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٍۢ', 456, 23, 183, 0),
  (38, 56, 4026, 'جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ', 456, 23, 183, 0),
  (38, 57, 4027, 'هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌۭ وَغَسَّاقٌۭ', 456, 23, 183, 0),
  (38, 58, 4028, 'وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ', 456, 23, 183, 0),
  (38, 59, 4029, 'هَٰذَا فَوْجٌۭ مُّقْتَحِمٌۭ مَّعَكُمْ ۖ لَا مَرْحَبًۢا بِهِمْ ۚ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ', 456, 23, 183, 0),
  (38, 60, 4030, 'قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ ۖ أَنتُمْ قَدَّمْتُمُوهُ لَنَا ۖ فَبِئْسَ ٱلْقَرَارُ', 456, 23, 183, 0),
  (38, 61, 4031, 'قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًۭا ضِعْفًۭا فِى ٱلنَّارِ', 456, 23, 183, 0),
  (38, 62, 4032, 'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًۭا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ', 457, 23, 183, 0),
  (38, 63, 4033, 'أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَٰرُ', 457, 23, 183, 0),
  (38, 64, 4034, 'إِنَّ ذَٰلِكَ لَحَقٌّۭ تَخَاصُمُ أَهْلِ ٱلنَّارِ', 457, 23, 183, 0),
  (38, 65, 4035, 'قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌۭ ۖ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 457, 23, 183, 0),
  (38, 66, 4036, 'رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 457, 23, 183, 0),
  (38, 67, 4037, 'قُلْ هُوَ نَبَؤٌا۟ عَظِيمٌ', 457, 23, 183, 0),
  (38, 68, 4038, 'أَنتُمْ عَنْهُ مُعْرِضُونَ', 457, 23, 183, 0),
  (38, 69, 4039, 'مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ', 457, 23, 183, 0),
  (38, 70, 4040, 'إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌ', 457, 23, 183, 0),
  (38, 71, 4041, 'إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًۭا مِّن طِينٍۢ', 457, 23, 183, 0),
  (38, 72, 4042, 'فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ', 457, 23, 183, 0),
  (38, 73, 4043, 'فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ', 457, 23, 183, 0),
  (38, 74, 4044, 'إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ', 457, 23, 183, 0),
  (38, 75, 4045, 'قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ ۖ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ', 457, 23, 183, 0),
  (38, 76, 4046, 'قَالَ أَنَا۠ خَيْرٌۭ مِّنْهُ ۖ خَلَقْتَنِى مِن نَّارٍۢ وَخَلَقْتَهُۥ مِن طِينٍۢ', 457, 23, 183, 0),
  (38, 77, 4047, 'قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌۭ', 457, 23, 183, 0),
  (38, 78, 4048, 'وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ', 457, 23, 183, 0),
  (38, 79, 4049, 'قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ', 457, 23, 183, 0),
  (38, 80, 4050, 'قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ', 457, 23, 183, 0),
  (38, 81, 4051, 'إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ', 457, 23, 183, 0),
  (38, 82, 4052, 'قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ', 457, 23, 183, 0),
  (38, 83, 4053, 'إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ', 457, 23, 183, 0),
  (38, 84, 4054, 'قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ', 458, 23, 183, 0),
  (38, 85, 4055, 'لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ', 458, 23, 183, 0),
  (38, 86, 4056, 'قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍۢ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ', 458, 23, 183, 0),
  (38, 87, 4057, 'إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 458, 23, 183, 0),
  (38, 88, 4058, 'وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ', 458, 23, 183, 0),
  (39, 1, 4059, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 458, 23, 183, 0),
  (39, 2, 4060, 'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًۭا لَّهُ ٱلدِّينَ', 458, 23, 183, 0),
  (39, 3, 4061, 'أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ ۚ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌۭ كَفَّارٌۭ', 458, 23, 183, 0),
  (39, 4, 4062, 'لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًۭا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ ۚ سُبْحَٰنَهُۥ ۖ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ', 458, 23, 183, 0),
  (39, 5, 4063, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ ۖ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ ۖ كُلٌّۭ يَجْرِى لِأَجَلٍۢ مُّسَمًّى ۗ أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّٰرُ', 458, 23, 183, 0),
  (39, 6, 4064, 'خَلَقَكُم مِّن نَّفْسٍۢ وَٰحِدَةٍۢ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجٍۢ ۚ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَٰتِكُمْ خَلْقًۭا مِّنۢ بَعْدِ خَلْقٍۢ فِى ظُلُمَٰتٍۢ ثَلَٰثٍۢ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُصْرَفُونَ', 459, 23, 183, 0),
  (39, 7, 4065, 'إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ ۖ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ ۖ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ ۗ وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۗ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 459, 23, 183, 0),
  (39, 8, 4066, '۞ وَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّۭ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةًۭ مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًۭا لِّيُضِلَّ عَن سَبِيلِهِۦ ۚ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا ۖ إِنَّكَ مِنْ أَصْحَٰبِ ٱلنَّارِ', 459, 23, 184, 0),
  (39, 9, 4067, 'أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًۭا وَقَآئِمًۭا يَحْذَرُ ٱلْءَاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ ۗ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ ۗ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 459, 23, 184, 0),
  (39, 10, 4068, 'قُلْ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ ۚ لِلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌۭ ۗ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ ۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍۢ', 459, 23, 184, 0),
  (39, 11, 4069, 'قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًۭا لَّهُ ٱلدِّينَ', 460, 23, 184, 0),
  (39, 12, 4070, 'وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ', 460, 23, 184, 0),
  (39, 13, 4071, 'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍۢ', 460, 23, 184, 0),
  (39, 14, 4072, 'قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًۭا لَّهُۥ دِينِى', 460, 23, 184, 0),
  (39, 15, 4073, 'فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ ۗ قُلْ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ', 460, 23, 184, 0),
  (39, 16, 4074, 'لَهُم مِّن فَوْقِهِمْ ظُلَلٌۭ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌۭ ۚ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ ۚ يَٰعِبَادِ فَٱتَّقُونِ', 460, 23, 184, 0),
  (39, 17, 4075, 'وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ ۚ فَبَشِّرْ عِبَادِ', 460, 23, 184, 0),
  (39, 18, 4076, 'ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ ۖ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ', 460, 23, 184, 0),
  (39, 19, 4077, 'أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ', 460, 23, 184, 0),
  (39, 20, 4078, 'لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌۭ مِّن فَوْقِهَا غُرَفٌۭ مَّبْنِيَّةٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ وَعْدَ ٱللَّهِ ۖ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ', 460, 23, 184, 0),
  (39, 21, 4079, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءًۭ فَسَلَكَهُۥ يَنَٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًۭا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّۭا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا ۚ إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 460, 23, 184, 0),
  (39, 22, 4080, 'أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍۢ مِّن رَّبِّهِۦ ۚ فَوَيْلٌۭ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ ۚ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۢ مُّبِينٍ', 461, 23, 184, 0),
  (39, 23, 4081, 'ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًۭا مُّتَشَٰبِهًۭا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ۚ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ', 461, 23, 184, 0),
  (39, 24, 4082, 'أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ ۚ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ', 461, 23, 184, 0),
  (39, 25, 4083, 'كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ', 461, 23, 184, 0),
  (39, 26, 4084, 'فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 461, 23, 184, 0),
  (39, 27, 4085, 'وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍۢ لَّعَلَّهُمْ يَتَذَكَّرُونَ', 461, 23, 184, 0),
  (39, 28, 4086, 'قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍۢ لَّعَلَّهُمْ يَتَّقُونَ', 461, 23, 184, 0),
  (39, 29, 4087, 'ضَرَبَ ٱللَّهُ مَثَلًۭا رَّجُلًۭا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًۭا سَلَمًۭا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ۚ ٱلْحَمْدُ لِلَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ', 461, 23, 184, 0),
  (39, 30, 4088, 'إِنَّكَ مَيِّتٌۭ وَإِنَّهُم مَّيِّتُونَ', 461, 23, 184, 0),
  (39, 31, 4089, 'ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ', 461, 23, 184, 0),
  (39, 32, 4090, '۞ فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًۭى لِّلْكَٰفِرِينَ', 462, 24, 185, 0),
  (39, 33, 4091, 'وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ ۙ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ', 462, 24, 185, 0),
  (39, 34, 4092, 'لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ۚ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ', 462, 24, 185, 0),
  (39, 35, 4093, 'لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 462, 24, 185, 0),
  (39, 36, 4094, 'أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ ۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍۢ', 462, 24, 185, 0),
  (39, 37, 4095, 'وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ ۗ أَلَيْسَ ٱللَّهُ بِعَزِيزٍۢ ذِى ٱنتِقَامٍۢ', 462, 24, 185, 0),
  (39, 38, 4096, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ ۚ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ ۚ قُلْ حَسْبِىَ ٱللَّهُ ۖ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ', 462, 24, 185, 0),
  (39, 39, 4097, 'قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌۭ ۖ فَسَوْفَ تَعْلَمُونَ', 462, 24, 185, 0),
  (39, 40, 4098, 'مَن يَأْتِيهِ عَذَابٌۭ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌۭ مُّقِيمٌ', 462, 24, 185, 0),
  (39, 41, 4099, 'إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ لِلنَّاسِ بِٱلْحَقِّ ۖ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ', 463, 24, 185, 0),
  (39, 42, 4100, 'ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا ۖ فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍۢ مُّسَمًّى ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 463, 24, 185, 0),
  (39, 43, 4101, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ ۚ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًۭٔا وَلَا يَعْقِلُونَ', 463, 24, 185, 0),
  (39, 44, 4102, 'قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعًۭا ۖ لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ ثُمَّ إِلَيْهِ تُرْجَعُونَ', 463, 24, 185, 0),
  (39, 45, 4103, 'وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ ۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ', 463, 24, 185, 0),
  (39, 46, 4104, 'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ عَٰلِمَ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 463, 24, 185, 0),
  (39, 47, 4105, 'وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًۭا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ ۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ', 463, 24, 185, 0),
  (39, 48, 4106, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 464, 24, 185, 0),
  (39, 49, 4107, 'فَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّۭ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةًۭ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ ۚ بَلْ هِىَ فِتْنَةٌۭ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 464, 24, 185, 0),
  (39, 50, 4108, 'قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 464, 24, 185, 0),
  (39, 51, 4109, 'فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ ۚ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ', 464, 24, 185, 0),
  (39, 52, 4110, 'أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يُؤْمِنُونَ', 464, 24, 185, 0),
  (39, 53, 4111, '۞ قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 464, 24, 186, 0),
  (39, 54, 4112, 'وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ', 464, 24, 186, 0),
  (39, 55, 4113, 'وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةًۭ وَأَنتُمْ لَا تَشْعُرُونَ', 464, 24, 186, 0),
  (39, 56, 4114, 'أَن تَقُولَ نَفْسٌۭ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ', 464, 24, 186, 0),
  (39, 57, 4115, 'أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ', 465, 24, 186, 0),
  (39, 58, 4116, 'أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةًۭ فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ', 465, 24, 186, 0),
  (39, 59, 4117, 'بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَٰفِرِينَ', 465, 24, 186, 0),
  (39, 60, 4118, 'وَيَوْمَ ٱلْقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ ۚ أَلَيْسَ فِى جَهَنَّمَ مَثْوًۭى لِّلْمُتَكَبِّرِينَ', 465, 24, 186, 0),
  (39, 61, 4119, 'وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ', 465, 24, 186, 0),
  (39, 62, 4120, 'ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍۢ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ وَكِيلٌۭ', 465, 24, 186, 0),
  (39, 63, 4121, 'لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۗ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 465, 24, 186, 0),
  (39, 64, 4122, 'قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَٰهِلُونَ', 465, 24, 186, 0),
  (39, 65, 4123, 'وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ', 465, 24, 186, 0),
  (39, 66, 4124, 'بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّٰكِرِينَ', 465, 24, 186, 0),
  (39, 67, 4125, 'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًۭا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ', 465, 24, 186, 0),
  (39, 68, 4126, 'وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ۖ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌۭ يَنظُرُونَ', 466, 24, 186, 0),
  (39, 69, 4127, 'وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّۦنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ', 466, 24, 186, 0),
  (39, 70, 4128, 'وَوُفِّيَتْ كُلُّ نَفْسٍۢ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ', 466, 24, 186, 0),
  (39, 71, 4129, 'وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا ۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌۭ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا ۚ قَالُوا۟ بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَٰفِرِينَ', 466, 24, 186, 0),
  (39, 72, 4130, 'قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۖ فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 466, 24, 186, 0),
  (39, 73, 4131, 'وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا ۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ', 466, 24, 186, 0),
  (39, 74, 4132, 'وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ ۖ فَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ', 466, 24, 186, 0),
  (39, 75, 4133, 'وَتَرَى ٱلْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ ۖ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 467, 24, 186, 0),
  (40, 1, 4134, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 467, 24, 187, 0),
  (40, 2, 4135, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ', 467, 24, 187, 0),
  (40, 3, 4136, 'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ ۖ لَآ إِلَٰهَ إِلَّا هُوَ ۖ إِلَيْهِ ٱلْمَصِيرُ', 467, 24, 187, 0),
  (40, 4, 4137, 'مَا يُجَٰدِلُ فِىٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَٰدِ', 467, 24, 187, 0),
  (40, 5, 4138, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ ۖ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ ۖ وَجَٰدَلُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ ۖ فَكَيْفَ كَانَ عِقَابِ', 467, 24, 187, 0),
  (40, 6, 4139, 'وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَٰبُ ٱلنَّارِ', 467, 24, 187, 0),
  (40, 7, 4140, 'ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍۢ رَّحْمَةًۭ وَعِلْمًۭا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ', 467, 24, 187, 0),
  (40, 8, 4141, 'رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ ۚ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 468, 24, 187, 0),
  (40, 9, 4142, 'وَقِهِمُ ٱلسَّيِّـَٔاتِ ۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍۢ فَقَدْ رَحِمْتَهُۥ ۚ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 468, 24, 187, 0),
  (40, 10, 4143, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَٰنِ فَتَكْفُرُونَ', 468, 24, 187, 0),
  (40, 11, 4144, 'قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍۢ مِّن سَبِيلٍۢ', 468, 24, 187, 0),
  (40, 12, 4145, 'ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ ۖ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ ۚ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ', 468, 24, 187, 0),
  (40, 13, 4146, 'هُوَ ٱلَّذِى يُرِيكُمْ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًۭا ۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ', 468, 24, 187, 0),
  (40, 14, 4147, 'فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 468, 24, 187, 0),
  (40, 15, 4148, 'رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ', 468, 24, 187, 0),
  (40, 16, 4149, 'يَوْمَ هُم بَٰرِزُونَ ۖ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌۭ ۚ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ ۖ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ', 468, 24, 187, 0),
  (40, 17, 4150, 'ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ ۚ لَا ظُلْمَ ٱلْيَوْمَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ', 469, 24, 187, 0),
  (40, 18, 4151, 'وَأَنذِرْهُمْ يَوْمَ ٱلْءَازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَٰظِمِينَ ۚ مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍۢ وَلَا شَفِيعٍۢ يُطَاعُ', 469, 24, 187, 0),
  (40, 19, 4152, 'يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ', 469, 24, 187, 0),
  (40, 20, 4153, 'وَٱللَّهُ يَقْضِى بِٱلْحَقِّ ۖ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ ۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 469, 24, 187, 0),
  (40, 21, 4154, '۞ أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ ۚ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةًۭ وَءَاثَارًۭا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍۢ', 469, 24, 188, 0),
  (40, 22, 4155, 'ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ ۚ إِنَّهُۥ قَوِىٌّۭ شَدِيدُ ٱلْعِقَابِ', 469, 24, 188, 0),
  (40, 23, 4156, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍۢ مُّبِينٍ', 469, 24, 188, 0),
  (40, 24, 4157, 'إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا۟ سَٰحِرٌۭ كَذَّابٌۭ', 469, 24, 188, 0),
  (40, 25, 4158, 'فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ ۚ وَمَا كَيْدُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍۢ', 469, 24, 188, 0),
  (40, 26, 4159, 'وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ ۖ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ', 470, 24, 188, 0),
  (40, 27, 4160, 'وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍۢ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ', 470, 24, 188, 0),
  (40, 28, 4161, 'وَقَالَ رَجُلٌۭ مُّؤْمِنٌۭ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ ۖ وَإِن يَكُ كَٰذِبًۭا فَعَلَيْهِ كَذِبُهُۥ ۖ وَإِن يَكُ صَادِقًۭا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌۭ كَذَّابٌۭ', 470, 24, 188, 0),
  (40, 29, 4162, 'يَٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا ۚ قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ', 470, 24, 188, 0),
  (40, 30, 4163, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ', 470, 24, 188, 0),
  (40, 31, 4164, 'مِثْلَ دَأْبِ قَوْمِ نُوحٍۢ وَعَادٍۢ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ ۚ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًۭا لِّلْعِبَادِ', 470, 24, 188, 0),
  (40, 32, 4165, 'وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ', 470, 24, 188, 0),
  (40, 33, 4166, 'يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍۢ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍۢ', 470, 24, 188, 0),
  (40, 34, 4167, 'وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّۢ مِّمَّا جَآءَكُم بِهِۦ ۖ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًۭا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌۭ مُّرْتَابٌ', 471, 24, 188, 0),
  (40, 35, 4168, 'ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ ۖ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍۢ جَبَّارٍۢ', 471, 24, 188, 0),
  (40, 36, 4169, 'وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ٱبْنِ لِى صَرْحًۭا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَٰبَ', 471, 24, 188, 0),
  (40, 37, 4170, 'أَسْبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًۭا ۚ وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ ۚ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍۢ', 471, 24, 188, 0),
  (40, 38, 4171, 'وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ', 471, 24, 188, 0),
  (40, 39, 4172, 'يَٰقَوْمِ إِنَّمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَٰعٌۭ وَإِنَّ ٱلْءَاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ', 471, 24, 188, 0),
  (40, 40, 4173, 'مَنْ عَمِلَ سَيِّئَةًۭ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا ۖ وَمَنْ عَمِلَ صَٰلِحًۭا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌۭ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍۢ', 471, 24, 188, 0),
  (40, 41, 4174, '۞ وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ', 472, 24, 189, 0),
  (40, 42, 4175, 'تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌۭ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّٰرِ', 472, 24, 189, 0),
  (40, 43, 4176, 'لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌۭ فِى ٱلدُّنْيَا وَلَا فِى ٱلْءَاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَٰبُ ٱلنَّارِ', 472, 24, 189, 0),
  (40, 44, 4177, 'فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ ۚ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ', 472, 24, 189, 0),
  (40, 45, 4178, 'فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ ۖ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ', 472, 24, 189, 0),
  (40, 46, 4179, 'ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّۭا وَعَشِيًّۭا ۖ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ', 472, 24, 189, 0),
  (40, 47, 4180, 'وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًۭا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًۭا مِّنَ ٱلنَّارِ', 472, 24, 189, 0),
  (40, 48, 4181, 'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّۭ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ', 472, 24, 189, 0),
  (40, 49, 4182, 'وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًۭا مِّنَ ٱلْعَذَابِ', 472, 24, 189, 0),
  (40, 50, 4183, 'قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ ۖ قَالُوا۟ بَلَىٰ ۚ قَالُوا۟ فَٱدْعُوا۟ ۗ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ', 473, 24, 189, 0),
  (40, 51, 4184, 'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ', 473, 24, 189, 0),
  (40, 52, 4185, 'يَوْمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعْذِرَتُهُمْ ۖ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ', 473, 24, 189, 0),
  (40, 53, 4186, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ', 473, 24, 189, 0),
  (40, 54, 4187, 'هُدًۭى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ', 473, 24, 189, 0),
  (40, 55, 4188, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ', 473, 24, 189, 0),
  (40, 56, 4189, 'إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ ۙ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌۭ مَّا هُم بِبَٰلِغِيهِ ۚ فَٱسْتَعِذْ بِٱللَّهِ ۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 473, 24, 189, 0),
  (40, 57, 4190, 'لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 473, 24, 189, 0),
  (40, 58, 4191, 'وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ ۚ قَلِيلًۭا مَّا تَتَذَكَّرُونَ', 473, 24, 189, 0),
  (40, 59, 4192, 'إِنَّ ٱلسَّاعَةَ لَءَاتِيَةٌۭ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ', 474, 24, 189, 0),
  (40, 60, 4193, 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ ۚ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ', 474, 24, 189, 0),
  (40, 61, 4194, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ', 474, 24, 189, 0),
  (40, 62, 4195, 'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍۢ لَّآ إِلَٰهَ إِلَّا هُوَ ۖ فَأَنَّىٰ تُؤْفَكُونَ', 474, 24, 189, 0),
  (40, 63, 4196, 'كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ', 474, 24, 189, 0),
  (40, 64, 4197, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًۭا وَٱلسَّمَآءَ بِنَآءًۭ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 474, 24, 189, 0),
  (40, 65, 4198, 'هُوَ ٱلْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۗ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ', 474, 24, 189, 0),
  (40, 66, 4199, '۞ قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ', 474, 24, 190, 0),
  (40, 67, 4200, 'هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍۢ ثُمَّ مِن نُّطْفَةٍۢ ثُمَّ مِنْ عَلَقَةٍۢ ثُمَّ يُخْرِجُكُمْ طِفْلًۭا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًۭا ۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ ۖ وَلِتَبْلُغُوٓا۟ أَجَلًۭا مُّسَمًّۭى وَلَعَلَّكُمْ تَعْقِلُونَ', 475, 24, 190, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 40, 1, 'Ha, Meem.'),
  ('en.sahih', 40, 2, 'The revelation of the Book is from Allah, the Exalted in Might, the Knowing.'),
  ('en.sahih', 40, 3, 'The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination.'),
  ('en.sahih', 40, 4, 'No one disputes concerning the signs of Allah except those who disbelieve, so be not deceived by their [uninhibited] movement throughout the land.'),
  ('en.sahih', 40, 5, 'The people of Noah denied before them and the [disbelieving] factions after them, and every nation intended [a plot] for their messenger to seize him, and they disputed by [using] falsehood to [attempt to] invalidate thereby the truth. So I seized them, and how [terrible] was My penalty.'),
  ('en.sahih', 40, 6, 'And thus has the word of your Lord come into effect upon those who disbelieved that they are companions of the Fire.'),
  ('en.sahih', 40, 7, 'Those [angels] who carry the Throne and those around it exalt [Allah] with praise of their Lord and believe in Him and ask forgiveness for those who have believed, [saying], "Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.'),
  ('en.sahih', 40, 8, 'Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.'),
  ('en.sahih', 40, 9, 'And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."'),
  ('en.sahih', 40, 10, 'Indeed, those who disbelieve will be addressed, "The hatred of Allah for you was [even] greater than your hatred of yourselves [this Day in Hell] when you were invited to faith, but you refused."'),
  ('en.sahih', 40, 11, 'They will say, "Our Lord, You made us lifeless twice and gave us life twice, and we have confessed our sins. So is there to an exit any way?"'),
  ('en.sahih', 40, 12, '[They will be told], "That is because, when Allah was called upon alone, you disbelieved; but if others were associated with Him, you believed. So the judgement is with Allah, the Most High, the Grand."'),
  ('en.sahih', 40, 13, 'It is He who shows you His signs and sends down to you from the sky, provision. But none will remember except he who turns back [in repentance].'),
  ('en.sahih', 40, 14, 'So invoke Allah, [being] sincere to Him in religion, although the disbelievers dislike it.'),
  ('en.sahih', 40, 15, '[He is] the Exalted above [all] degrees, Owner of the Throne; He places the inspiration of His command upon whom He wills of His servants to warn of the Day of Meeting.'),
  ('en.sahih', 40, 16, 'The Day they come forth nothing concerning them will be concealed from Allah. To whom belongs [all] sovereignty this Day? To Allah, the One, the Prevailing.'),
  ('en.sahih', 40, 17, 'This Day every soul will be recompensed for what it earned. No injustice today! Indeed, Allah is swift in account.'),
  ('en.sahih', 40, 18, 'And warn them, [O Muhammad], of the Approaching Day, when hearts are at the throats, filled [with distress]. For the wrongdoers there will be no devoted friend and no intercessor [who is] obeyed.'),
  ('en.sahih', 40, 19, 'He knows that which deceives the eyes and what the breasts conceal.'),
  ('en.sahih', 40, 20, 'And Allah judges with truth, while those they invoke besides Him judge not with anything. Indeed, Allah - He is the Hearing, the Seeing.'),
  ('en.sahih', 40, 21, 'Have they not traveled through the land and observed how was the end of those who were before them? They were greater than them in strength and in impression on the land, but Allah seized them for their sins. And they had not from Allah any protector.'),
  ('en.sahih', 40, 22, 'That was because their messengers were coming to them with clear proofs, but they disbelieved, so Allah seized them. Indeed, He is Powerful and severe in punishment.'),
  ('en.sahih', 40, 23, 'And We did certainly send Moses with Our signs and a clear authority'),
  ('en.sahih', 40, 24, 'To Pharaoh, Haman and Qarun; but they said, "[He is] a magician and a liar."'),
  ('en.sahih', 40, 25, 'And when he brought them the truth from Us, they said, "Kill the sons of those who have believed with him and keep their women alive." But the plan of the disbelievers is not except in error.'),
  ('en.sahih', 40, 26, 'And Pharaoh said, "Let me kill Moses and let him call upon his Lord. Indeed, I fear that he will change your religion or that he will cause corruption in the land."'),
  ('en.sahih', 40, 27, 'But Moses said, "Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account."'),
  ('en.sahih', 40, 28, 'And a believing man from the family of Pharaoh who concealed his faith said, "Do you kill a man [merely] because he says, \'My Lord is Allah\' while he has brought you clear proofs from your Lord? And if he should be lying, then upon him is [the consequence of] his lie; but if he should be truthful, there will strike you some of what he promises you. Indeed, Allah does not guide one who is a transgressor and a liar.'),
  ('en.sahih', 40, 29, 'O my people, sovereignty is yours today, [your being] dominant in the land. But who would protect us from the punishment of Allah if it came to us?" Pharaoh said, "I do not show you except what I see, and I do not guide you except to the way of right conduct."'),
  ('en.sahih', 40, 30, 'And he who believed said, "O my people, indeed I fear for you [a fate] like the day of the companies -'),
  ('en.sahih', 40, 31, 'Like the custom of the people of Noah and of \'Aad and Thamud and those after them. And Allah wants no injustice for [His] servants.'),
  ('en.sahih', 40, 32, 'And O my people, indeed I fear for you the Day of Calling -'),
  ('en.sahih', 40, 33, 'The Day you will turn your backs fleeing; there is not for you from Allah any protector. And whoever Allah leaves astray - there is not for him any guide.'),
  ('en.sahih', 40, 34, 'And Joseph had already come to you before with clear proofs, but you remained in doubt of that which he brought to you, until when he died, you said, \'Never will Allah send a messenger after him.\' Thus does Allah leave astray he who is a transgressor and skeptic."'),
  ('en.sahih', 40, 35, 'Those who dispute concerning the signs of Allah without an authority having come to them - great is hatred [of them] in the sight of Allah and in the sight of those who have believed. Thus does Allah seal over every heart [belonging to] an arrogant tyrant.'),
  ('en.sahih', 40, 36, 'And Pharaoh said, "O Haman, construct for me a tower that I might reach the ways -'),
  ('en.sahih', 40, 37, 'The ways into the heavens - so that I may look at the deity of Moses; but indeed, I think he is a liar." And thus was made attractive to Pharaoh the evil of his deed, and he was averted from the [right] way. And the plan of Pharaoh was not except in ruin.'),
  ('en.sahih', 40, 38, 'And he who believed said, "O my people, follow me, I will guide you to the way of right conduct.'),
  ('en.sahih', 40, 39, 'O my people, this worldly life is only [temporary] enjoyment, and indeed, the Hereafter - that is the home of [permanent] settlement.'),
  ('en.sahih', 40, 40, 'Whoever does an evil deed will not be recompensed except by the like thereof; but whoever does righteousness, whether male or female, while he is a believer - those will enter Paradise, being given provision therein without account.'),
  ('en.sahih', 40, 41, 'And O my people, how is it that I invite you to salvation while you invite me to the Fire?'),
  ('en.sahih', 40, 42, 'You invite me to disbelieve in Allah and associate with Him that of which I have no knowledge, and I invite you to the Exalted in Might, the Perpetual Forgiver.'),
  ('en.sahih', 40, 43, 'Assuredly, that to which you invite me has no [response to a] supplication in this world or in the Hereafter; and indeed, our return is to Allah, and indeed, the transgressors will be companions of the Fire.'),
  ('en.sahih', 40, 44, 'And you will remember what I [now] say to you, and I entrust my affair to Allah. Indeed, Allah is Seeing of [His] servants."'),
  ('en.sahih', 40, 45, 'So Allah protected him from the evils they plotted, and the people of Pharaoh were enveloped by the worst of punishment -'),
  ('en.sahih', 40, 46, 'The Fire, they are exposed to it morning and evening. And the Day the Hour appears [it will be said], "Make the people of Pharaoh enter the severest punishment."'),
  ('en.sahih', 40, 47, 'And [mention] when they will argue within the Fire, and the weak will say to those who had been arrogant, "Indeed, we were [only] your followers, so will you relieve us of a share of the Fire?"'),
  ('en.sahih', 40, 48, 'Those who had been arrogant will say, "Indeed, all [of us] are in it. Indeed, Allah has judged between the servants."'),
  ('en.sahih', 40, 49, 'And those in the Fire will say to the keepers of Hell, "Supplicate your Lord to lighten for us a day from the punishment."'),
  ('en.sahih', 40, 50, 'They will say, "Did there not come to you your messengers with clear proofs?" They will say, "Yes." They will reply, "Then supplicate [yourselves], but the supplication of the disbelievers is not except in error."'),
  ('en.sahih', 40, 51, 'Indeed, We will support Our messengers and those who believe during the life of this world and on the Day when the witnesses will stand -'),
  ('en.sahih', 40, 52, 'The Day their excuse will not benefit the wrongdoers, and they will have the curse, and they will have the worst home.'),
  ('en.sahih', 40, 53, 'And We had certainly given Moses guidance, and We caused the Children of Israel to inherit the Scripture'),
  ('en.sahih', 40, 54, 'As guidance and a reminder for those of understanding.'),
  ('en.sahih', 40, 55, 'So be patient, [O Muhammad]. Indeed, the promise of Allah is truth. And ask forgiveness for your sin and exalt [Allah] with praise of your Lord in the evening and the morning.'),
  ('en.sahih', 40, 56, 'Indeed, those who dispute concerning the signs of Allah without [any] authority having come to them - there is not within their breasts except pride, [the extent of] which they cannot reach. So seek refuge in Allah. Indeed, it is He who is the Hearing, the Seeing.'),
  ('en.sahih', 40, 57, 'The creation of the heavens and earth is greater than the creation of mankind, but most of the people do not know.'),
  ('en.sahih', 40, 58, 'And not equal are the blind and the seeing, nor are those who believe and do righteous deeds and the evildoer. Little do you remember.'),
  ('en.sahih', 40, 59, 'Indeed, the Hour is coming - no doubt about it - but most of the people do not believe.'),
  ('en.sahih', 40, 60, 'And your Lord says, "Call upon Me; I will respond to you." Indeed, those who disdain My worship will enter Hell [rendered] contemptible.'),
  ('en.sahih', 40, 61, 'It is Allah who made for you the night that you may rest therein and the day giving sight. Indeed, Allah is full of bounty to the people, but most of the people are not grateful.'),
  ('en.sahih', 40, 62, 'That is Allah, your Lord, Creator of all things; there is no deity except Him, so how are you deluded?'),
  ('en.sahih', 40, 63, 'Thus were those [before you] deluded who were rejecting the signs of Allah.'),
  ('en.sahih', 40, 64, 'It is Allah who made for you the earth a place of settlement and the sky a ceiling and formed you and perfected your forms and provided you with good things. That is Allah, your Lord; then blessed is Allah, Lord of the worlds.'),
  ('en.sahih', 40, 65, 'He is the Ever-Living; there is no deity except Him, so call upon Him, [being] sincere to Him in religion. [All] praise is [due] to Allah, Lord of the worlds.'),
  ('en.sahih', 40, 66, 'Say, [O Muhammad], "Indeed, I have been forbidden to worship those you call upon besides Allah once the clear proofs have come to me from my Lord, and I have been commanded to submit to the Lord of the worlds."'),
  ('en.sahih', 40, 67, 'It is He who created you from dust, then from a sperm-drop, then from a clinging clot; then He brings you out as a child; then [He develops you] that you reach your [time of] maturity, then [further] that you become elders. And among you is he who is taken in death before [that], so that you reach a specified term; and perhaps you will use reason.'),
  ('en.sahih', 40, 68, 'He it is who gives life and causes death; and when He decrees a matter, He but says to it, "Be," and it is.'),
  ('en.sahih', 40, 69, 'Do you not consider those who dispute concerning the signs of Allah - how are they averted?'),
  ('en.sahih', 40, 70, 'Those who deny the Book and that with which We sent Our messengers - they are going to know,'),
  ('en.sahih', 40, 71, 'When the shackles are around their necks and the chains; they will be dragged'),
  ('en.sahih', 40, 72, 'In boiling water; then in the Fire they will be filled [with flame].'),
  ('en.sahih', 40, 73, 'Then it will be said to them, "Where is that which you used to associate [with Him in worship]'),
  ('en.sahih', 40, 74, 'Other than Allah?" They will say, "They have departed from us; rather, we did not used to invoke previously anything." Thus does Allah put astray the disbelievers.'),
  ('en.sahih', 40, 75, '[The angels will say], "That was because you used to exult upon the earth without right and you used to behave insolently.'),
  ('en.sahih', 40, 76, 'Enter the gates of Hell to abide eternally therein, and wretched is the residence of the arrogant."'),
  ('en.sahih', 40, 77, 'So be patient, [O Muhammad]; indeed, the promise of Allah is truth. And whether We show you some of what We have promised them or We take you in death, it is to Us they will be returned.'),
  ('en.sahih', 40, 78, 'And We have already sent messengers before you. Among them are those [whose stories] We have related to you, and among them are those [whose stories] We have not related to you. And it was not for any messenger to bring a sign [or verse] except by permission of Allah. So when the command of Allah comes, it will be concluded in truth, and the falsifiers will thereupon lose [all].'),
  ('en.sahih', 40, 79, 'It is Allah who made for you the grazing animals upon which you ride, and some of them you eat.'),
  ('en.sahih', 40, 80, 'And for you therein are [other] benefits and that you may realize upon them a need which is in your breasts; and upon them and upon ships you are carried.'),
  ('en.sahih', 40, 81, 'And He shows you His signs. So which of the signs of Allah do you deny?'),
  ('en.sahih', 40, 82, 'Have they not traveled through the land and observed how was the end of those before them? They were more numerous than themselves and greater in strength and in impression on the land, but they were not availed by what they used to earn.'),
  ('en.sahih', 40, 83, 'And when their messengers came to them with clear proofs, they [merely] rejoiced in what they had of knowledge, but they were enveloped by what they used to ridicule.'),
  ('en.sahih', 40, 84, 'And when they saw Our punishment, they said," We believe in Allah alone and disbelieve in that which we used to associate with Him."'),
  ('en.sahih', 40, 85, 'But never did their faith benefit them once they saw Our punishment. [It is] the established way of Allah which has preceded among His servants. And the disbelievers thereupon lost [all].')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 40, 1, 'হা-মীম।'),
  ('bn.bengali', 40, 2, 'কিতাব অবতীর্ণ হয়েছে আল্লাহর পক্ষ থেকে, যিনি পরাক্রমশালী, সর্বজ্ঞ।'),
  ('bn.bengali', 40, 3, 'পাপ ক্ষমাকারী, তওবা কবুলকারী, কঠোর শাস্তিদাতা ও সামর্থ?476;ান। তিনি ব্যতীত কোন উপাস্য নেই। তাঁরই দিকে হবে প্রত্যাবর্তন।'),
  ('bn.bengali', 40, 4, 'কাফেররাই কেবল আল্লাহর আয়াত সম্পর্কে বিতর্ক করে। কাজেই নগরীসমূহে তাদের বিচরণ যেন আপনাকে বিভ্রান্তিতে না ফেলে।'),
  ('bn.bengali', 40, 5, 'তাদের পূর্বে নূহের সম্প্রদায় মিথ্যারোপ করেছিল, আর তাদের পরে অন্য অনেক দল ও প্রত্যেক সম্প্রদায় নিজ নিজ পয়গম্বরকে আক্রমণ করার ইচ্ছা করেছিল এবং তারা মিথ্যা বিতর্কে প্রবৃত্ত হয়েছিল, যেন সত্যধর্মকে ব্যর্থ করে দিতে পারে। অতঃপর আমি তাদেরকে পাকড়াও করলাম। কেমন ছিল আমার শাস্তি।'),
  ('bn.bengali', 40, 6, 'এভাবে কাফেরদের বেলায় আপনার পালনকর্তার এ বাক্য সত্য হল যে, তারা জাহান্নামী।'),
  ('bn.bengali', 40, 7, 'যারা আরশ বহন করে এবং যারা তার চারপাশে আছে, তারা তাদের পালনকর্তার সপ্রশংস পবিত্রতা বর্ণনা করে, তার প্রতি বিশ্বাস স্থাপন করে এবং মুমিনদের জন্যে ক্ষমা প্রার্থনা করে বলে, হে আমাদের পালনকর্তা, আপনার রহমত ও জ্ঞান সবকিছুতে পরিব্যাপ্ত। অতএব, যারা তওবা করে এবং আপনার পথে চলে, তাদেরকে ক্ষমা করুন এবং জাহান্নামের আযাব থেকে রক্ষা করুন।'),
  ('bn.bengali', 40, 8, 'হে আমাদের পালনকর্তা, আর তাদেরকে দাখিল করুন চিরকাল বসবাসের জান্নাতে, যার ওয়াদা আপনি তাদেরকে দিয়েছেন এবং তাদের বাপ-দাদা, পতি-পত্নী ও সন্তানদের মধ্যে যারা সৎকর্ম করে তাদেরকে। নিশ্চয় আপনি পরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 40, 9, 'এবং আপনি তাদেরকে অমঙ্গল থেকে রক্ষা করুন। আপনি যাকে সেদিন অমঙ্গল থেকে রক্ষা করবেন, তার প্রতি অনুগ্রহই করবেন। এটাই মহাসাফল্য।'),
  ('bn.bengali', 40, 10, 'যারা কাফের তাদেরকে উচ্চঃস্বরে বলা হবে, তোমাদের নিজেদের প্রতি তোমাদের আজকের এ ক্ষোভ অপেক্ষা আল্লার ক্ষোভ অধিক ছিল, যখন তোমাদেরকে ঈমান আনতে বলা হয়েছিল, অতঃপর তোমরা কুফরী করছিল।'),
  ('bn.bengali', 40, 11, 'তারা বলবে হে আমাদের পালনকর্তা! আপনি আমাদেরকে দু’বার মৃত্যু দিয়েছেন এবং দু’ বার জীবন দিয়েছেন। এখন আমাদের অপরাধ স্বীকার করছি। অতঃপর এখন ও নিস্কৃতির কোন উপায় আছে কি?'),
  ('bn.bengali', 40, 12, 'তোমাদের এ বিপদ এ কারণে যে, যখন এক আল্লাহকে ডাকা হত, তখন তোমরা কাফের হয়ে যেতে যখন তার সাথে শরীককে ডাকা হত তখন তোমরা বিশ্বাস স্থাপন করতে। এখন আদেশ তাই, যা আল্লাহ করবেন, যিনি সর্বোচ্চ, মহান।'),
  ('bn.bengali', 40, 13, 'তিনিই তোমাদেরকে তাঁর নিদর্শনাবলী দেখান এবং তোমাদের জন্যে আকাশ থেকে নাযিল করেন রুযী। চিন্তা-ভাবনা তারাই করে, যারা আল্লাহর দিকে রুজু থাকে।'),
  ('bn.bengali', 40, 14, 'অতএব, তোমরা আল্লাহকে খাঁটি বিশ্বাস সহকারে ডাক, যদিও কাফেররা তা অপছন্দ করে।'),
  ('bn.bengali', 40, 15, 'তিনিই সুউচ্চ মর্যাদার অধিকারী, আরশের মালিক, তাঁর বান্দাদের মধ্যে যার প্রতি ইচ্ছা তত্ত্বপূর্ণ বিষয়াদি নাযিল করেন, যাতে সে সাক্ষাতের দিন সম্পর্কে সকলকে সতর্ক করে।'),
  ('bn.bengali', 40, 16, 'যেদিন তারা বের হয়ে পড়বে, আল্লাহর কাছে তাদের কিছুই গোপন থাকবে না। আজ রাজত্ব কার? এক প্রবল পরাক্রান্ত আল্লাহর।'),
  ('bn.bengali', 40, 17, 'আজ প্রত্যেকেই তার কৃতকর্মের প্রতিদান পাবে। আজ যুলুম নেই। নিশ্চয় আল্লাহ দ্রুত হিসাব গ্রহণকারী।'),
  ('bn.bengali', 40, 18, 'আপনি তাদেরকে আসন্ন দিন সম্পর্কে সতর্ক করুন, যখন প্রাণ কন্ঠাগত হবে, দম বন্ধ হওয়ার উপক্রম হবে। পাপিষ্ঠদের জন্যে কোন বন্ধু নেই এবং সুপারিশকারীও নেই; যার সুপারিশ গ্রাহ্য হবে।'),
  ('bn.bengali', 40, 19, 'চোখের চুরি এবং অন্তরের গোপন বিষয় তিনি জানেন।'),
  ('bn.bengali', 40, 20, 'আল্লাহ ফয়সালা করেন সঠিকভাবে, আল্লাহর পরিবর্তে তারা যাদেরকে ডাকে, তারা কিছুই ফয়সালা করে না। নিশ্চয় আল্লাহ সবকিছু শুনেন, সবকিছু দেখেন।'),
  ('bn.bengali', 40, 21, 'তারা কি দেশ-বিদেশ ভ্রমণ করে না, যাতে দেখত তাদের পূর্বসুরিদের কি পরিণাম হয়েছে? তাদের শক্তি ও কীর্তি পৃথিবীতে এদের অপেক্ষা অধিকতর ছিল। অতঃপর আল্লাহ তাদেরকে তাদের গোনাহের কারণে ধৃত করেছিলেন এবং আল্লাহ থেকে তাদেরকে রক্ষাকারী কেউ হয়নি।'),
  ('bn.bengali', 40, 22, 'এর কারণ এই যে, তাদের কাছে তাদের রসূলগণ সুস্পষ্ট নিদর্শনাবলী নিয়ে আগমন করত, অতঃপর তারা কাফের হয়ে যায়, তখন আল্লাহ তাদের ধৃত করেন। নিশ্চয় তিনি শক্তিধর, কঠোর শাস্তিদাতা।'),
  ('bn.bengali', 40, 23, 'আমি আমার নিদর্শনাবলী ও স্পষ্ট প্রমাণসহ মূসাকে প্রেরণ করেছি।'),
  ('bn.bengali', 40, 24, 'ফেরাউন, হামান ও কারুণের কাছে, অতঃপর তারা বলল, সে তো জাদুকর, মিথ্যাবাদী।'),
  ('bn.bengali', 40, 25, 'অতঃপর মূসা যখন আমার কাছ থেকে সত্যসহ তাদের কাছে পৌঁছাল; তখন তারা বলল, যারা তার সঙ্গী হয়ে বিশ্বাস স্থাপন করেছে, তাদের পুত্র সন্তানদেরকে হত্যা কর, আর তাদের নারীদেরকে জীবিত রাখ। কাফেরদের চক্রান্ত ব্যর্থই হয়েছে।'),
  ('bn.bengali', 40, 26, 'ফেরাউন বলল; তোমরা আমাকে ছাড়, মূসাকে হত্যা করতে দাও, ডাকুক সে তার পালনকর্তাকে! আমি আশংকা করি যে, সে তোমাদের ধর্ম পরিবর্তন করে দেবে অথবা সে দেশময় বিপর্যয় সৃষ্টি করবে।'),
  ('bn.bengali', 40, 27, 'মূসা বলল, যারা হিসাব দিবসে বিশ্বাস করে না এমন প্রত্যেক অহংকারী থেকে আমি আমার ও তোমাদের পালনকর্তার আশ্রয় নিয়ে নিয়েছি।'),
  ('bn.bengali', 40, 28, 'ফেরাউন গোত্রের এক মুমিন ব্যক্তি, যে তার ঈমান গোপন রাখত, সে বলল, তোমরা কি একজনকে এজন্যে হত্যা করবে যে, সে বলে, আমার পালনকর্তা আল্লাহ, অথচ সে তোমাদের পালনকর্তার নিকট থেকে স্পষ্ট প্রমাণসহ তোমাদের নিকট আগমন করেছে? যদি সে মিথ্যাবাদী হয়, তবে তার মিথ্যাবাদিতা তার উপরই চাপবে, আর যদি সে সত্যবাদী হয়, তবে সে যে শাস্তির কথা বলছে, তার কিছু না কিছু তোমাদের উপর পড়বেই। নিশ্চয় আল্লাহ সীমালংঘনকারী, মিথ্যাবাদীকে পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 40, 29, 'হে আমার কওম, আজ এদেশে তোমাদেরই রাজত্ব, দেশময় তোমরাই বিচরণ করছ; কিন্তু আমাদের আল্লাহর শাস্তি এসে গেলে কে আমাদেরকে সাহায্য করবে? ফেরাউন বলল, আমি যা বুঝি, তোমাদেরকে তাই বোঝাই, আর আমি তোমাদেরকে মঙ্গলের পথই দেখাই।'),
  ('bn.bengali', 40, 30, 'সে মুমিন ব্যক্তি বললঃ হে আমার কওম, আমি তোমাদের জন্যে পূর্ববর্তী সম্প্রদায়সমূহের মতই বিপদসঙ্কুল দিনের আশংকা করি।'),
  ('bn.bengali', 40, 31, 'যেমন, কওমে নূহ, আদ, সামুদ ও তাদের পরবর্তীদের অবস্থা হয়েছিল। আল্লাহ বান্দাদের প্রতি কোন যুলুম করার ইচ্ছা করেন না।'),
  ('bn.bengali', 40, 32, 'হে আমার কওম, আমি তোমাদের জন্যে প্রচন্ড হাঁক-ডাকের দিনের আশংকা করি।'),
  ('bn.bengali', 40, 33, 'যেদিন তোমরা পেছনে ফিরে পলায়ন করবে; কিন্তু আল্লাহ থেকে তোমাদেরকে রক্ষাকারী কেউ থাকবে না। আল্লাহ যাকে পথভ্রষ্ট করেন, তার কোন পথপ্রদর্শক নেই।'),
  ('bn.bengali', 40, 34, 'ইতিপূর্বে তোমাদের কাছে ইউসুফ সুস্পষ্ট প্রামাণাদিসহ আগমন করেছিল, অতঃপর তোমরা তার আনীত বিষয়ে সন্দেহই পোষণ করতে। অবশেষে যখন সে মারা গেল, তখন তোমরা বলতে শুরু করলে, আল্লাহ ইউসুফের পরে আর কাউকে রসূলরূপে পাঠাবেন না। এমনিভাবে আল্লাহ সীমালংঘনকারী, সংশয়ী ব্যক্তিকে পথভ্রষ্ট করেন।'),
  ('bn.bengali', 40, 35, 'যারা নিজেদের কাছে আগত কোন দলীল ছাড়াই আল্লাহর আয়াত সম্পর্কে বিতর্ক করে, তাদের একজন আল্লাহ ও মুমিনদের কাছে খুবই অসন্তোষজনক। এমনিভাবে আল্লাহ প্রত্যেক অহংকারী-স্বৈরাচারী ব্যক্তির অন্তরে মোহর এঁটে দেন।'),
  ('bn.bengali', 40, 36, 'ফেরাউন বলল, হে হামান, তুমি আমার জন্যে একটি সুউচ্চ প্রাসাদ নির্মাণ কর, হয়তো আমি পৌঁছে যেতে পারব।'),
  ('bn.bengali', 40, 37, 'আকাশের পথে, অতঃপর উঁকি মেরে দেখব মূসার আল্লাহকে। বস্তুতঃ আমি তো তাকে মিথ্যাবাদীই মনে করি। এভাবেই ফেরাউনের কাছে সুশোভিত করা হয়েছিল তার মন্দ কর্মকে এবং সোজা পথ থেকে তাকে বিরত রাখা হয়েছিল। ফেরাউনের চক্রান্ত ব্যর্থ হওয়ারই ছিল।'),
  ('bn.bengali', 40, 38, 'মুমিন লোকটি বললঃ হে আমার কওম, তোমরা আমার অনুসরণ কর। আমি তোমাদেরকে সৎপথ প্রদর্শন করব।'),
  ('bn.bengali', 40, 39, 'হে আমার কওম, পার্থিব এ জীবন তো কেবল উপভোগের বস্তু, আর পরকাল হচ্ছে স্থায়ী বসবাসের গৃহ।'),
  ('bn.bengali', 40, 40, 'যে মন্দ কর্ম করে, সে কেবল তার অনুরূপ প্রতিফল পাবে, আর যে, পুরুষ অথবা নারী মুমিন অবস্থায় সৎকর্ম করে তারাই জান্নাতে প্রবেশ করবে। তথায় তাদেরকে বে-হিসাব রিযিক দেয়া হবে।'),
  ('bn.bengali', 40, 41, 'হে আমার কওম, ব্যাপার কি, আমি তোমাদেরকে দাওয়াত দেই মুক্তির দিকে, আর তোমরা আমাকে দাওয়াত দাও জাহান্নামের দিকে।'),
  ('bn.bengali', 40, 42, 'তোমরা আমাকে দাওয়াত দাও, যাতে আমি আল্লাহকে অস্বীকার করি এবং তাঁর সাথে শরীক করি এমন বস্তুকে, যার কোন প্রমাণ আমার কাছে নেই। আমি তোমাদেরকে দাওয়াত দেই পরাক্রমশালী, ক্ষমাশীল আল্লাহর দিকে।'),
  ('bn.bengali', 40, 43, 'এতে সন্দেহ নেই যে, তোমরা আমাকে যার দিকে দাওয়াত দাও, হইকালে ও পরকালে তার কোন দাওয়াত নেই! আমাদের প্রত্যাবর্তন আল্লাহর দিকে এবং সীমা লংঘকারীরাই জাহান্নামী।'),
  ('bn.bengali', 40, 44, 'আমি তোমাদেরকে যা বলছি, তোমরা একদিন তা স্মরণ করবে। আমি আমার ব্যাপার আল্লাহর কাছে সমর্পণ করছি। নিশ্চয় বান্দারা আল্লাহর দৃষ্টিতে রয়েছে।'),
  ('bn.bengali', 40, 45, 'অতঃপর আল্লাহ তাকে তাদের চক্রান্তের অনিষ্ট থেকে রক্ষা করলেন এবং ফেরাউন গোত্রকে শোচনীয় আযাব গ্রাস করল।'),
  ('bn.bengali', 40, 46, 'সকালে ও সন্ধ্যায় তাদেরকে আগুনের সামনে পেশ করা হয় এবং যেদিন কেয়ামত সংঘটিত হবে, সেদিন আদেশ করা হবে, ফেরাউন গোত্রকে কঠিনতর আযাবে দাখিল কর।'),
  ('bn.bengali', 40, 47, 'যখন তারা জাহান্নামে পরস্পর বিতর্ক করবে, অতঃপর দূর্বলরা অহংকারীদেরকে বলবে, আমরা তোমাদের অনুসারী ছিলাম। তোমরা এখন জাহান্নামের আগুনের কিছু অংশ আমাদের থেকে নিবৃত করবে কি?'),
  ('bn.bengali', 40, 48, 'অহংকারীরা বলবে, আমরা সবাই তো জাহান্নামে আছি। আল্লাহ তাঁর বান্দাদের ফয়সালা করে দিয়েছেন।'),
  ('bn.bengali', 40, 49, 'যারা জাহান্নামে আছে, তারা জাহান্নামের রক্ষীদেরকে বলবে, তোমরা তোমাদের পালনকর্তাকে বল, তিনি যেন আমাদের থেকে একদিনের আযাব লাঘব করে দেন।'),
  ('bn.bengali', 40, 50, 'রক্ষীরা বলবে, তোমাদের কাছে কি সুস্পষ্ট প্রমাণাদিসহ তোমাদের রসূল আসেননি? তারা বলবে হঁ্যা। রক্ষীরা বলবে, তবে তোমরাই দোয়া কর। বস্তুতঃ কাফেরদের দোয়া নিস্ফলই হয়।'),
  ('bn.bengali', 40, 51, 'আমি সাহায্য করব রসূলগণকে ও মুমিনগণকে পার্থিব জীবনে ও সাক্ষীদের দন্ডায়মান হওয়ার দিবসে।'),
  ('bn.bengali', 40, 52, 'সে দিন যালেমদের ওযর-আপত্তি কোন উপকারে আসবে না, তাদের জন্যে থাকবে অভিশাপ এবং তাদের জন্যে থাকবে মন্দ গৃহ।'),
  ('bn.bengali', 40, 53, 'নিশ্চয় আমি মূসাকে হেদায়েত দান করেছিলাম এবং বনী ইসরাঈলকে কিতাবের উত্তরাধিকারী করেছিলাম।'),
  ('bn.bengali', 40, 54, 'বুদ্ধিমানদের জন্যে উপদেশ ও হেদায়েত স্বরূপ।'),
  ('bn.bengali', 40, 55, 'অতএব, আপনি সবর করুন নিশ্চয় আল্লাহর ওয়াদা সত্য। আপনি আপনার গোনাহের জন্যে ক্ষমা প্রর্থনা করুন এবং সকাল-সন্ধ্যায় আপনার পালনকর্তার প্রশংসাসহ পবিত্রতা বর্ণনা করুন।'),
  ('bn.bengali', 40, 56, 'নিশ্চয় যারা আল্লাহর আয়াত সম্পর্কে বিতর্ক করে তাদের কাছে আগত কোন দলীল ব্যতিরেকে, তাদের অন্তরে আছে কেবল আত্নম্ভরিতা, যা অর্জনে তারা সফল হবে না। অতএব, আপনি আল্লাহর আশ্রয় প্রার্থনা করুন। নিশ্চয় তিনি সবকিছু শুনেন, সবকিছু দেখেন।'),
  ('bn.bengali', 40, 57, 'মানুষের সৃষ্টি অপেক্ষা নভোমন্ডল ও ভূ-মন্ডলের সৃষ্টি কঠিনতর। কিন্তু অধিকাংশ মানুষ বোঝে না।'),
  ('bn.bengali', 40, 58, 'অন্ধ ও চক্ষুষ্মান সমান নয়, আর যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে এবং কুকর্মী। তোমরা অল্পই অনুধাবন করে থাক।'),
  ('bn.bengali', 40, 59, 'কেয়ামত অবশ্যই আসবে, এতে সন্দেহ নেই; কিন্ত অধিকাংশ লোক বিশ্বাস স্থাপন করে না।'),
  ('bn.bengali', 40, 60, 'তোমাদের পালনকর্তা বলেন, তোমরা আমাকে ডাক, আমি সাড়া দেব। যারা আমার এবাদতে অহংকার করে তারা সত্বরই জাহান্নামে দাখিল হবে লাঞ্ছিত হয়ে।'),
  ('bn.bengali', 40, 61, 'তিনিই আল্লাহ যিনি রাত্র সৃষ্টি করেছেন তোমাদের বিশ্রামের জন্যে এবং দিবসকে করেছেন দেখার জন্যে। নিশ্চয় আল্লাহ মানুষের প্রতি অনুগ্রহশীল, কিন্তু অধিকাংশ মানুষ কৃতজ্ঞতা স্বীকার করে না।'),
  ('bn.bengali', 40, 62, 'তিনি আল্লাহ, তোমাদের পালনকর্তা, সব কিছুর স্রষ্টা। তিনি ব্যতীত কোন উপাস্য নেই। অতএব তোমরা কোথায় বিভ্রান্ত হচ্ছ?'),
  ('bn.bengali', 40, 63, 'এমনিভাবে তাদেরকে বিভ্রান্ত করা হয়, যারা আল্লাহর আয়াতসমূহকে অস্বীকার করে।'),
  ('bn.bengali', 40, 64, 'আল্লাহ, পৃথিবীকে করেছেন তোমাদের জন্যে বাসস্থান, আকাশকে করেছেন ছাদ এবং তিনি তোমাদেরকে আকৃতি দান করেছেন, অতঃপর তোমাদের আকৃতি সুন্দর করেছেন এবং তিনি তোমাদেরকে দান করেছেন পরিচ্ছন্ন রিযিক। তিনি আল্লাহ, তোমাদের পালনকর্তা। বিশ্বজগতের পালনকর্তা, আল্লাহ বরকতময়।'),
  ('bn.bengali', 40, 65, 'তিনি চিরঞ্জীব, তিনি ব্যতীত কোন উপাস্য নেই। অতএব, তাঁকে ডাক তাঁর খাঁটি এবাদতের মাধ্যমে। সমস্ত প্রশংসা বিশ্বজগতের পালনকর্তা আল্লাহর।'),
  ('bn.bengali', 40, 66, 'বলুন, যখন আমার কাছে আমার পালনকর্তার পক্ষ থেকে স্পষ্ট প্রমাণাদি এসে গেছে, তখন আল্লাহ ব্যতীত তোমরা যার পূজা কর, তার এবাদত করতে আমাকে নিষেধ করা হয়েছে। আমাকে আদেশ করা হয়েছে বিশ্ব পালনকর্তার অনুগত থাকতে।'),
  ('bn.bengali', 40, 67, 'তিনি তো তোমাদের সৃষ্টি করেছেন মাটির দ্বারা, অতঃপর শুক্রবিন্দু দ্বারা, অতঃপর জমাট রক্ত দ্বারা, অতঃপর তোমাদেরকে বের করেন শিশুরূপে, অতঃপর তোমরা যৌবনে পদর্পণ কর, অতঃপর বার্ধক্যে উপনীত হও। তোমাদের কারও কারও এর পূর্বেই মৃত্যু ঘটে এবং তোমরা নির্ধারিত কালে পৌঁছ এবং তোমরা যাতে অনুধাবন কর।'),
  ('bn.bengali', 40, 68, 'তিনিই জীবিত করেন এবং মৃত্যু দেন। যখন তিনি কোন কাজের আদেশ করেন, তখন একথাই বলেন, হয়ে যা’-তা হয়ে যায়।'),
  ('bn.bengali', 40, 69, 'আপনি কি তাদেরকে দেখেননি, যারা আল্লাহর আয়াত সম্পর্কে বিতর্ক করে, তারা কোথায় ফিরছে?'),
  ('bn.bengali', 40, 70, 'যারা কিতাবের প্রতি এবং যে বিষয় দিয়ে আমি পয়গম্বরগণকে প্রেরণ করেছি, সে বিষয়ের প্রতি মিথ্যারোপ করে। অতএব, সত্বরই তারা জানতে পারবে।'),
  ('bn.bengali', 40, 71, 'যখন বেড়িও শৃঙ্খল তাদের গলদেশে পড়বে। তাদেরকে টেনে নিয়ে যাওয়া হবে।'),
  ('bn.bengali', 40, 72, 'ফুটন্ত পানিতে, অতঃপর তাদেরকে আগুনে জ্বালানো হবে।'),
  ('bn.bengali', 40, 73, 'অতঃপর তাদেরকে বলা হবে, কোথায় গেল যাদেরকে তোমরা শরীক করতে।'),
  ('bn.bengali', 40, 74, 'আল্লাহ ব্যতীত? তারা বলবে, তারা আমাদের কাছ থেকে উধাও হয়ে গেছে; বরং আমরা তো ইতিপূর্বে কোন কিছুর পূজাই করতাম না। এমনি ভাবে আল্লাহ কাফেরদেরকে বিভ্রান্ত করেন।'),
  ('bn.bengali', 40, 75, 'এটা একারণে যে, তোমরা দুনিয়াতে অন্যায়ভাবে আনন্দ-উল্লাস করতে এবং এ কারণে যে, তোমরা ঔদ্ধত্য করতে।'),
  ('bn.bengali', 40, 76, 'প্রবেশ কর তোমরা জাহান্নামের দরজা দিয়ে সেখানে চিরকাল বসবাসের জন্যে। কত নিকৃষ্ট দাম্ভিকদের আবাসস্থল।'),
  ('bn.bengali', 40, 77, 'অতএব আপনি সবর করুন। নিশ্চয় আল্লাহর ওয়াদা সত্য। অতঃপর আমি কাফেরদেরকে যে শাস্তির ওয়াদা দেই, তার কিয়দংশ যদি আপনাকে দেখিয়ে দেই অথবা আপনার প্রাণ হরণ করে নেই, সর্বাবস্থায় তারা তো আমারই কাছে ফিরে আসবে।'),
  ('bn.bengali', 40, 78, 'আমি আপনার পূর্বে অনেক রসূল প্রেরণ করেছি, তাদের কারও কারও ঘটনা আপনার কাছে বিবৃত করেছি এবং কারও কারও ঘটনা আপনার কাছে বিবৃত করিনি। আল্লাহর অনুমতি ব্যতীত কোন নিদর্শন নিয়ে আসা কোন রসূলের কাজ নয়। যখন আল্লাহর আদেশ আসবে, তখন ন্যায় সঙ্গত ফয়সালা হয়ে যাবে। সেক্ষেত্রে মিথ্যাপন্থীরা ক্ষতিগ্রস্ত হবে।'),
  ('bn.bengali', 40, 79, 'আল্লাহ তোমাদের জন্যে চতুস্পদ জন্তু সৃষ্টি করেছেন, যাতে কোন কোনটিই বাহন হিসাবে ব্যবহার কর এবং কোন কোনটিকে ভক্ষণ কর।'),
  ('bn.bengali', 40, 80, 'তাতে তোমাদের জন্যে অনেক উপকারিতা রয়েছে আর এজন্যে সৃষ্টি করেছেন; যাতে সেগুলোতে আরোহণ করে তোমরা তোমাদের অভীষ্ট প্রয়োজন পূর্ণ করতে পার। এগুলোর উপর এবং নৌকার উপর তোমরা বাহিত হও।'),
  ('bn.bengali', 40, 81, 'তিনি তোমাদেরকে তাঁর নিদর্শনাবলী দেখান। অতএব, তোমরা আল্লাহর কোন কোন নিদর্শনকে অস্বীকার করবে?'),
  ('bn.bengali', 40, 82, 'তারা কি পৃথিবীতে ভ্রমণ করেনি? করলে দেখত, তাদের পূর্ববর্তীদের কি পরিণাম হয়েছে। তারা তাদের চেয়ে সংখ্যায় বেশী এবং শক্তি ও কীর্তিতে অধিক প্রবল ছিল, অতঃপর তাদের কর্ম তাদেরকে কোন উপকার দেয়নি।'),
  ('bn.bengali', 40, 83, 'তাদের কাছে যখন তাদের রসূলগণ স্পষ্ট প্রমাণাদিসহ আগমন করেছিল, তখন তারা নিজেদের জ্ঞান-গরিমার দম্ভ প্রকাশ করেছিল। তারা যে বিষয় নিয়ে ঠাট্টাবিদ্রুপ করেছিল, তাই তাদেরকে গ্রাস করে নিয়েছিল।'),
  ('bn.bengali', 40, 84, 'তারা যখন আমার শাস্তি প্রত্যক্ষ করল, তখন বলল, আমরা এক আল্লাহর প্রতি বিশ্বাস করলাম এবং যাদেরকে শরীক করতাম, তাদেরকে পরিহার করলাম।'),
  ('bn.bengali', 40, 85, 'অতঃপর তাদের এ ঈমান তাদের কোন উপকারে আসল না যখন তারা শাস্তি প্রত্যক্ষ করল। আল্লাহর এ নিয়মই পূর্ব থেকে তাঁর বান্দাদের মধ্যে প্রচলিত হয়েছে। সেক্ষেত্রে কাফেররা ক্ষতিগ্রস্ত হয়।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 40, 1, 'Ha. Mim.'),
  ('en.pickthall', 40, 2, 'The revelation of the Scripture is from Allah, the Mighty, the Knower,'),
  ('en.pickthall', 40, 3, 'The Forgiver of sin, the Accepter of repentance, the Stern in punishment, the Bountiful. There is no Allah save Him. Unto Him is the journeying.'),
  ('en.pickthall', 40, 4, 'None argue concerning the revelations of Allah save those who disbelieve, so let not their turn of fortune in the land deceive thee (O Muhammad).'),
  ('en.pickthall', 40, 5, 'The folk of Noah and the factions after them denied (their messengers) before these, and every nation purposed to seize their messenger and argued falsely, (thinking) thereby to refute the Truth. Then I seized them, and how (awful) was My punishment.'),
  ('en.pickthall', 40, 6, 'Thus was the word of thy Lord concerning those who disbelieve fulfilled: That they are owners of the Fire.'),
  ('en.pickthall', 40, 7, 'Those who bear the Throne, and all who are round about it, hymn the praises of their Lord and believe in Him and ask forgiveness for those who believe (saying): Our Lord! Thou comprehendest all things in mercy and knowledge, therefor forgive those who repent and follow Thy way. Ward off from them the punishment of hell.'),
  ('en.pickthall', 40, 8, 'Our Lord! And make them enter the Gardens of Eden which thou hast promised them, with such of their fathers and their wives and their descendants as do right. Lo! Thou, only Thou, art the Mighty, the Wise.'),
  ('en.pickthall', 40, 9, 'And ward off from them ill-deeds; and he from whom Thou wardest off ill-deeds that day, him verily hast Thou taken into mercy. That is the supreme triumph.'),
  ('en.pickthall', 40, 10, 'Lo! (on that day) those who disbelieve are informed by proclamation: Verily Allah\'s abhorrence is more terrible than your abhorrence one of another, when ye were called unto the faith but did refuse.'),
  ('en.pickthall', 40, 11, 'They say: Our Lord! Twice hast Thou made us die, and twice hast Thou made us live. Now we confess our sins. Is there any way to go out?'),
  ('en.pickthall', 40, 12, '(It is said unto them): This is (your plight) because, when Allah only was invoked, ye disbelieved, but when some partner was ascribed to Him ye were believing. But the command belongeth only to Allah, the Sublime, the Majestic.'),
  ('en.pickthall', 40, 13, 'He it is Who showeth you His portents, and sendeth down for you provision from the sky. None payeth heed save him who turneth (unto Him) repentant.'),
  ('en.pickthall', 40, 14, 'Therefor (O believers) pray unto Allah, making religion pure for Him (only), however much the disbelievers be averse -'),
  ('en.pickthall', 40, 15, 'The Exalter of Ranks, the Lord of the Throne. He causeth the Spirit of His command upon whom He will of His slaves, that He may warn of the Day of Meeting,'),
  ('en.pickthall', 40, 16, 'The day when they come forth, nothing of them being hidden from Allah. Whose is the Sovereignty this day? It is Allah\'s, the One, the Almighty.'),
  ('en.pickthall', 40, 17, 'This day is each soul requited that which it hath earned; no wrong (is done) this day. Lo! Allah is swift at reckoning.'),
  ('en.pickthall', 40, 18, 'Warn them (O Muhammad) of the Day of the approaching (doom), when the hearts will be choking the throats, (when) there will be no friend for the wrong-doers, nor any intercessor who will be heard.'),
  ('en.pickthall', 40, 19, 'He knoweth the traitor of the eyes, and that which the bosoms hide.'),
  ('en.pickthall', 40, 20, 'Allah judgeth with truth, while those to whom they cry instead of Him judge not at all. Lo! Allah, He is the Hearer, the Seer.'),
  ('en.pickthall', 40, 21, 'Have they not travelled in the land to see the nature of the consequence for those who disbelieved before them? They were mightier than these in power and (in the) traces (which they left behind them) in the earth. Yet Allah seized them for their sins, and they had no protector from Allah.'),
  ('en.pickthall', 40, 22, 'That was because their messengers kept bringing them clear proofs (of Allah\'s Sovereignty) but they disbelieved; so Allah seized them. Lo! He is Strong, severe in punishment.'),
  ('en.pickthall', 40, 23, 'And verily We sent Moses with Our revelations and a clear warrant'),
  ('en.pickthall', 40, 24, 'Unto Pharaoh and Haman and Korah, but they said: A lying sorcerer!'),
  ('en.pickthall', 40, 25, 'And when he brought them the Truth from Our presence, they said: Slay the sons of those who believe with him, and spare their women. But the plot of disbelievers is in naught but error.'),
  ('en.pickthall', 40, 26, 'And Pharaoh said: Suffer me to kill Moses, and let him cry unto his Lord. Lo! I fear that he will alter your religion or that he will cause confusion in the land.'),
  ('en.pickthall', 40, 27, 'Moses said: Lo! I seek refuge in my Lord and your Lord from every scorner who believeth not in a Day of Reckoning.'),
  ('en.pickthall', 40, 28, 'And a believing man of Pharaoh\'s family, who hid his faith, said: Would ye kill a man because he saith: My Lord is Allah, and hath brought you clear proofs from your Lord? If he is lying, then his lie is upon him; and if he is truthful, then some of that wherewith he threateneth you will strike you. Lo! Allah guideth not one who is a prodigal, a liar.'),
  ('en.pickthall', 40, 29, 'O my people! Yours is the kingdom to-day, ye being uppermost in the land. But who would save us from the wrath of Allah should it reach us? Pharaoh said: I do but show you what I think, and I do but guide you to wise policy.'),
  ('en.pickthall', 40, 30, 'And he who believed said: O my people! Lo! I fear for you a fate like that of the factions (of old);'),
  ('en.pickthall', 40, 31, 'A plight like that of Noah\'s folk, and A\'ad and Thamud, and those after them, and Allah willeth no injustice for (His) slaves.'),
  ('en.pickthall', 40, 32, 'And, O my people! Lo! I fear for you a Day of Summoning,'),
  ('en.pickthall', 40, 33, 'A day when ye will turn to flee, having no preserver from Allah: and he whom Allah sendeth astray, for him there is no guide.'),
  ('en.pickthall', 40, 34, 'And verily Joseph brought you of old clear proofs, yet ye ceased not to be in doubt concerning what he brought you till, when he died, ye said: Allah will not send any messenger after him. Thus Allah deceiveth him who is a prodigal, a doubter.'),
  ('en.pickthall', 40, 35, 'Those who wrangle concerning the revelations of Allah without any warrant that hath come unto them, it is greatly hateful in the sight of Allah and in the sight of those who believe. Thus doth Allah print on every arrogant, disdainful heart.'),
  ('en.pickthall', 40, 36, 'And Pharaoh said: O Haman! Build for me a tower that haply I may reach the roads,'),
  ('en.pickthall', 40, 37, 'The roads of the heavens, and may look upon the god of Moses, though verily I think him a liar. Thus was the evil that he did made fairseeming unto Pharaoh, and he was debarred from the (right) way. The plot of Pharaoh ended but in ruin.'),
  ('en.pickthall', 40, 38, 'And he who believed said: O my people! Follow me. I will show you the way of right conduct.'),
  ('en.pickthall', 40, 39, 'O my people! Lo! this life of the world is but a passing comfort, and lo! the Hereafter, that is the enduring home.'),
  ('en.pickthall', 40, 40, 'Whoso doeth an ill-deed, he will be repaid the like thereof, while whoso doeth right, whether male or female, and is a believer, (all) such will enter the Garden, where they will be nourished without stint.'),
  ('en.pickthall', 40, 41, 'And, O my people! What aileth me that I call you unto deliverance when ye call me unto the Fire?'),
  ('en.pickthall', 40, 42, 'Ye call me to disbelieve in Allah and ascribe unto Him as partners that whereof I have no knowledge, while I call you unto the Mighty, the Forgiver.'),
  ('en.pickthall', 40, 43, 'Assuredly that whereunto ye call me hath no claim in the world or in the Hereafter, and our return will be unto Allah, and the prodigals will be owners of the Fire.'),
  ('en.pickthall', 40, 44, 'And ye will remember what I say unto you. I confide my cause unto Allah. Lo! Allah is Seer of (His) slaves.'),
  ('en.pickthall', 40, 45, 'So Allah warded off from him the evils which they plotted, while a dreadful doom encompassed Pharaoh\'s folk,'),
  ('en.pickthall', 40, 46, 'The Fire; they are exposed to it morning and evening; and on the day when the Hour upriseth (it is said): Cause Pharaoh\'s folk to enter the most awful doom.'),
  ('en.pickthall', 40, 47, 'And when they wrangle in the Fire, the weak say unto those who were proud: Lo! we were a following unto you; will ye therefor rid us of a portion of the Fire?'),
  ('en.pickthall', 40, 48, 'Those who were proud say: Lo! we are all (together) herein. Lo! Allah hath judged between (His) slaves.'),
  ('en.pickthall', 40, 49, 'And those in the Fire say unto the guards of hell: Entreat your Lord that He relieve us of a day of the torment.'),
  ('en.pickthall', 40, 50, 'They say: Came not your messengers unto you with clear proofs? They say: Yea, verily. They say: Then do ye pray, although the prayer of disbelievers is in vain.'),
  ('en.pickthall', 40, 51, 'Lo! We verily do help Our messengers, and those who believe, in the life of the world and on the day when the witnesses arise,'),
  ('en.pickthall', 40, 52, 'The day when their excuse availeth not the evil-doers, and theirs is the curse, and theirs the ill abode.'),
  ('en.pickthall', 40, 53, 'And We verily gave Moses the guidance, and We caused the Children of Israel to inherit the Scripture,'),
  ('en.pickthall', 40, 54, 'A guide and a reminder for men of understanding.'),
  ('en.pickthall', 40, 55, 'Then have patience (O Muhammad). Lo! the promise of Allah is true. And ask forgiveness of thy sin, and hymn the praise of thy Lord at fall of night and in the early hours.'),
  ('en.pickthall', 40, 56, 'Lo! those who wrangle concerning the revelations of Allah without a warrant having come unto them, there is naught else in their breasts save pride which they will never attain. So take thou refuge in Allah. Lo! He, only He, is the Hearer, the Seer.'),
  ('en.pickthall', 40, 57, 'Assuredly the creation of the heavens and the earth is greater than the creation of mankind; but most of mankind know not.'),
  ('en.pickthall', 40, 58, 'And the blind man and the seer are not equal, neither are those who believe and do good works (equal with) the evil-doer. Little do ye reflect!'),
  ('en.pickthall', 40, 59, 'Lo! the Hour is surely coming, there is no doubt thereof; yet most of mankind believe not.'),
  ('en.pickthall', 40, 60, 'And your Lord hath said: Pray unto Me and I will hear your prayer. Lo! those who scorn My service, they will enter hell, disgraced.'),
  ('en.pickthall', 40, 61, 'Allah it is Who hath appointed for you night that ye may rest therein, and day for seeing. Lo! Allah is a Lord of bounty for mankind, yet most of mankind give not thanks.'),
  ('en.pickthall', 40, 62, 'Such is Allah, your Lord, the Creator of all things, There is no Allah save Him. How then are ye perverted?'),
  ('en.pickthall', 40, 63, 'Thus are they perverted who deny the revelations of Allah.'),
  ('en.pickthall', 40, 64, 'Allah it is Who appointed for you the earth for a dwelling-place and the sky for a canopy, and fashioned you and perfected your shapes, and hath provided you with good things. Such is Allah, your Lord. Then blessed be Allah, the Lord of the Worlds!'),
  ('en.pickthall', 40, 65, 'He is the Living One. There is no Allah save Him. So pray unto Him, making religion pure for Him (only). Praise be to Allah, the Lord of the Worlds!'),
  ('en.pickthall', 40, 66, 'Say (O Muhammad): I am forbidden to worship those unto whom ye cry beside Allah since there have come unto me clear proofs from my Lord, and I am commanded to surrender to the Lord of the Worlds.'),
  ('en.pickthall', 40, 67, 'He it is Who created you from dust, then from a drop (of seed) then from a clot, then bringeth you forth as a child, then (ordaineth) that ye attain full strength and afterward that ye become old men - though some among you die before - and that ye reach an appointed term, that haply ye may understand.'),
  ('en.pickthall', 40, 68, 'He it is Who quickeneth and giveth death. When He ordaineth a thing, He saith unto it only: Be! and it is.'),
  ('en.pickthall', 40, 69, 'Hast thou not seen those who wrangle concerning the revelations of Allah, how they are turned away? -'),
  ('en.pickthall', 40, 70, 'Those who deny the Scripture and that wherewith We send Our messengers. But they will come to know,'),
  ('en.pickthall', 40, 71, 'When carcans are about their necks and chains. They are dragged'),
  ('en.pickthall', 40, 72, 'Through boiling waters; then they are thrust into the Fire.'),
  ('en.pickthall', 40, 73, 'Then it is said unto them: Where are (all) that ye used to make partners (in the Sovereignty)'),
  ('en.pickthall', 40, 74, 'Beside Allah? They say: They have failed us; but we used not to pray to anything before. Thus doth Allah send astray the disbelievers (in His guidance).'),
  ('en.pickthall', 40, 75, '(And it is said unto them): This is because ye exulted in the earth without right, and because ye were petulant.'),
  ('en.pickthall', 40, 76, 'Enter ye the gates of hell, to dwell therein. Evil is the habitation of the scornful.'),
  ('en.pickthall', 40, 77, 'Then have patience (O Muhammad). Lo! the promise of Allah is true. And whether we let thee see a part of that which We promise them, or (whether) We cause thee to die, still unto Us they will be brought back.'),
  ('en.pickthall', 40, 78, 'Verily We sent messengers before thee, among them those of whom We have told thee, and some of whom We have not told thee; and it was not given to any messenger that he should bring a portent save by Allah\'s leave, but when Allah\'s commandment cometh (the cause) is judged aright, and the followers of vanity will then be lost.'),
  ('en.pickthall', 40, 79, 'Allah it is Who hath appointed for you cattle, that ye may ride on some of them, and eat of some -'),
  ('en.pickthall', 40, 80, '(Many) benefits ye have from them - and that ye may satisfy by their means a need that is in your breasts, and may be borne upon them as upon the ship.'),
  ('en.pickthall', 40, 81, 'And He showeth you His tokens. Which, then, of the tokens of Allah do ye deny?'),
  ('en.pickthall', 40, 82, 'Have they not travelled in the land to see the nature of the consequence for those before them? They were more numerous than these, and mightier in power and (in the) traces (which they left behind them) in the earth. But all that they used to earn availed them not.'),
  ('en.pickthall', 40, 83, 'And when their messengers brought them clear proofs (of Allah\'s Sovereignty) they exulted in the knowledge they (themselves) possessed. And that which they were wont to mock befell them.'),
  ('en.pickthall', 40, 84, 'Then, when they saw Our doom, they said: We believe in Allah only and reject (all) that we used to associate (with Him).'),
  ('en.pickthall', 40, 85, 'But their faith could not avail them when they saw Our doom. This is Allah\'s law which hath ever taken course for His bondmen. And then the disbelievers will be ruined.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 40, 1, 'Ha Mim'),
  ('en.yusufali', 40, 2, 'The revelation of this Book is from Allah, Exalted in Power, Full of Knowledge,-'),
  ('en.yusufali', 40, 3, 'Who forgiveth sin, accepteth repentance, is strict in punishment, and hath a long reach (in all things). there is no god but He: to Him is the final goal.'),
  ('en.yusufali', 40, 4, 'None can dispute about the Signs of Allah but the Unbelievers. Let not, then, their strutting about through the land deceive thee!'),
  ('en.yusufali', 40, 5, 'But (there were people) before them, who denied (the Signs),- the People of Noah, and the Confederates (of Evil) after them; and every People plotted against their prophet, to seize him, and disputed by means of vanities, therewith to condemn the Truth; but it was I that seized them! and how (terrible) was My Requital!'),
  ('en.yusufali', 40, 6, 'Thus was the Decree of thy Lord proved true against the Unbelievers; that truly they are Companions of the Fire!'),
  ('en.yusufali', 40, 7, 'Those who sustain the Throne (of Allah) and those around it Sing Glory and Praise to their Lord; believe in Him; and implore Forgiveness for those who believe: "Our Lord! Thy Reach is over all things, in Mercy and Knowledge. Forgive, then, those who turn in Repentance, and follow Thy Path; and preserve them from the Penalty of the Blazing Fire!'),
  ('en.yusufali', 40, 8, '"And grant, our Lord! that they enter the Gardens of Eternity, which Thou hast promised to them, and to the righteous among their fathers, their wives, and their posterity! For Thou art (He), the Exalted in Might, Full of Wisdom.'),
  ('en.yusufali', 40, 9, '"And preserve them from (all) ills; and any whom Thou dost preserve from ills that Day,- on them wilt Thou have bestowed Mercy indeed: and that will be truly (for them) the highest Achievement".'),
  ('en.yusufali', 40, 10, 'The Unbelievers will be addressed: "Greater was the aversion of Allah to you than (is) your aversion to yourselves, seeing that ye were called to the Faith and ye used to refuse."'),
  ('en.yusufali', 40, 11, 'They will say: "Our Lord! twice hast Thou made us without life, and twice hast Thou given us Life! Now have we recognised our sins: Is there any way out (of this)?"'),
  ('en.yusufali', 40, 12, '(The answer will be:) "This is because, when Allah was invoked as the Only (object of worship), ye did reject Faith, but when partners were joined to Him, ye believed! the Command is with Allah, Most High, Most Great!"'),
  ('en.yusufali', 40, 13, 'He it is Who showeth you his Signs, and sendeth down sustenance for you from the sky: but only those receive admonition who turn (to Allah).'),
  ('en.yusufali', 40, 14, 'Call ye, then, upon Allah with sincere devotion to Him, even though the Unbelievers may detest it.'),
  ('en.yusufali', 40, 15, 'Raised high above ranks (or degrees), (He is) the Lord of the Throne (of Authority): by His Command doth He send the Spirit (of inspiration) to any of His servants he pleases, that it may warn (men) of the Day of Mutual Meeting,-'),
  ('en.yusufali', 40, 16, 'The Day whereon they will (all) come forth: not a single thing concerning them is hidden from Allah. Whose will be the dominion that Day?" That of Allah, the One the Irresistible!'),
  ('en.yusufali', 40, 17, 'That Day will every soul be requited for what it earned; no injustice will there be that Day, for Allah is Swift in taking account.'),
  ('en.yusufali', 40, 18, 'Warn them of the Day that is (ever) drawing near, when the hearts will (come) right up to the throats to choke (them); No intimate friend nor intercessor will the wrong-doers have, who could be listened to.'),
  ('en.yusufali', 40, 19, '(Allah) knows of (the tricks) that deceive with the eyes, and all that the hearts (of men) conceal.'),
  ('en.yusufali', 40, 20, 'And Allah will judge with (justice and) Truth: but those whom (men) invoke besides Him, will not (be in a position) to judge at all. Verily it is Allah (alone) Who hears and sees (all things).'),
  ('en.yusufali', 40, 21, 'Do they not travel through the earth and see what was the End of those before them? They were even superior to them in strength, and in the traces (they have left) in the land: but Allah did call them to account for their sins, and none had they to defend them against Allah.'),
  ('en.yusufali', 40, 22, 'That was because there came to them their messengers with Clear (Signs), but they rejected them: So Allah called them to account: for He is Full of Strength, Strict in Punishment.'),
  ('en.yusufali', 40, 23, 'Of old We sent Moses, with Our Signs and an authority manifest,'),
  ('en.yusufali', 40, 24, 'To Pharaoh, Haman, and Qarun; but they called (him)" a sorcerer telling lies!"...'),
  ('en.yusufali', 40, 25, 'Now, when he came to them in Truth, from Us, they said, "Slay the sons of those who believe with him, and keep alive their females," but the plots of Unbelievers (end) in nothing but errors (and delusions)!...'),
  ('en.yusufali', 40, 26, 'Said Pharaoh: "Leave me to slay Moses; and let him call on his Lord! What I fear is lest he should change your religion, or lest he should cause mischief to appear in the land!"'),
  ('en.yusufali', 40, 27, 'Moses said: "I have indeed called upon my Lord and your Lord (for protection) from every arrogant one who believes not in the Day of Account!"'),
  ('en.yusufali', 40, 28, 'A believer, a man from among the people of Pharaoh, who had concealed his faith, said: "Will ye slay a man because he says, \'My Lord is Allah\'?- when he has indeed come to you with Clear (Signs) from your Lord? and if he be a liar, on him is (the sin of) his lie: but, if he is telling the Truth, then will fall on you something of the (calamity) of which he warns you: Truly Allah guides not one who transgresses and lies!'),
  ('en.yusufali', 40, 29, '"O my People! Yours is the dominion this day: Ye have the upper hand in the land: but who will help us from the Punishment of Allah, should it befall us?" Pharaoh said: "I but point out to you that which I see (myself); Nor do I guide you but to the Path of Right!"'),
  ('en.yusufali', 40, 30, 'Then said the man who believed: "O my people! Truly I do fear for you something like the Day (of disaster) of the Confederates (in sin)!-'),
  ('en.yusufali', 40, 31, '"Something like the fate of the People of Noah, the \'Ad, and the Thamud, and those who came after them: but Allah never wishes injustice to his Servants.'),
  ('en.yusufali', 40, 32, '"And O my people! I fear for you a Day when there will be Mutual calling (and wailing),-'),
  ('en.yusufali', 40, 33, '"A Day when ye shall turn your backs and flee: No defender shall ye have from Allah: Any whom Allah leaves to stray, there is none to guide...'),
  ('en.yusufali', 40, 34, '"And to you there came Joseph in times gone by, with Clear Signs, but ye ceased not to doubt of the (Mission) for which he had come: At length, when he died, ye said: \'No messenger will Allah send after him.\' thus doth Allah leave to stray such as transgress and live in doubt,-'),
  ('en.yusufali', 40, 35, '"(Such) as dispute about the Signs of Allah, without any authority that hath reached them, grievous and odious (is such conduct) in the sight of Allah and of the Believers. Thus doth Allah, seal up every heart - of arrogant and obstinate Transgressors."'),
  ('en.yusufali', 40, 36, 'Pharaoh said: "O Haman! Build me a lofty palace, that I may attain the ways and means-'),
  ('en.yusufali', 40, 37, '"The ways and means of (reaching) the heavens, and that I may mount up to the god of Moses: But as far as I am concerned, I think (Moses) is a liar!" Thus was made alluring, in Pharaoh\'s eyes, the evil of his deeds, and he was hindered from the Path; and the plot of Pharaoh led to nothing but perdition (for him).'),
  ('en.yusufali', 40, 38, 'The man who believed said further: "O my people! Follow me: I will lead you to the Path of Right.'),
  ('en.yusufali', 40, 39, '"O my people! This life of the present is nothing but (temporary) convenience: It is the Hereafter that is the Home that will last.'),
  ('en.yusufali', 40, 40, '"He that works evil will not be requited but by the like thereof: and he that works a righteous deed - whether man or woman - and is a Believer- such will enter the Garden (of Bliss): Therein will they have abundance without measure.'),
  ('en.yusufali', 40, 41, '"And O my people! How (strange) it is for me to call you to Salvation while ye call me to the Fire!'),
  ('en.yusufali', 40, 42, '"Ye do call upon me to blaspheme against Allah, and to join with Him partners of whom I have no knowledge; and I call you to the Exalted in Power, Who forgives again and again!"'),
  ('en.yusufali', 40, 43, '"Without doubt ye do call me to one who is not fit to be called to, whether in this world, or in the Hereafter; our return will be to Allah; and the Transgressors will be Companions of the Fire!'),
  ('en.yusufali', 40, 44, '"Soon will ye remember what I say to you (now), My (own) affair I commit to Allah: for Allah (ever) watches over His Servants."'),
  ('en.yusufali', 40, 45, 'Then Allah saved him from (every) ill that they plotted (against him), but the burnt of the Penalty encompassed on all sides the People of Pharaoh.'),
  ('en.yusufali', 40, 46, 'In front of the Fire will they be brought, morning and evening: And (the sentence will be) on the Day that Judgment will be established: "Cast ye the People of Pharaoh into the severest Penalty!"'),
  ('en.yusufali', 40, 47, 'Behold, they will dispute with each other in the Fire! The weak ones (who followed) will say to those who had been arrogant, "We but followed you: Can ye then take (on yourselves) from us some share of the Fire?'),
  ('en.yusufali', 40, 48, 'Those who had been arrogant will say: "We are all in this (Fire)! Truly, Allah has judged between (his) Servants!"'),
  ('en.yusufali', 40, 49, 'Those in the Fire will say to the Keepers of Hell: "Pray to your Lord to lighten us the Penalty for a day (at least)!"'),
  ('en.yusufali', 40, 50, 'They will say: "Did there not come to you your messengers with Clear Signs?" They will say, "Yes". They will reply, "Then pray (as ye like)! But the prayer of those without Faith is nothing but (futile wandering) in (mazes of) error!"'),
  ('en.yusufali', 40, 51, 'We will, without doubt, help our messengers and those who believe, (both) in this world\'s life and on the Day when the Witnesses will stand forth,-'),
  ('en.yusufali', 40, 52, 'The Day when no profit will it be to Wrong-doers to present their excuses, but they will (only) have the Curse and the Home of Misery.'),
  ('en.yusufali', 40, 53, 'We did aforetime give Moses the (Book of) Guidance, and We gave the book in inheritance to the Children of Israel,-'),
  ('en.yusufali', 40, 54, 'A Guide and a Message to men of Understanding.'),
  ('en.yusufali', 40, 55, 'Patiently, then, persevere: for the Promise of Allah is true: and ask forgiveness for thy fault, and celebrate the Praises of thy Lord in the evening and in the morning.'),
  ('en.yusufali', 40, 56, 'Those who dispute about the signs of Allah without any authority bestowed on them,- there is nothing in their breasts but (the quest of) greatness, which they shall never attain to: seek refuge, then, in Allah: It is He Who hears and sees (all things).'),
  ('en.yusufali', 40, 57, 'Assuredly the creation of the heavens and the earth is a greater (matter) than the creation of men: Yet most men understand not.'),
  ('en.yusufali', 40, 58, 'Not equal are the blind and those who (clearly) see: Nor are (equal) those who believe and work deeds of righteousness, and those who do evil. Little do ye learn by admonition!'),
  ('en.yusufali', 40, 59, 'The Hour will certainly come: Therein is no doubt: Yet most men believe not.'),
  ('en.yusufali', 40, 60, 'And your Lord says: "Call on Me; I will answer your (Prayer): but those who are too arrogant to serve Me will surely find themselves in Hell - in humiliation!"'),
  ('en.yusufali', 40, 61, 'It is Allah Who has made the Night for you, that ye may rest therein, and the days as that which helps (you) to see. Verily Allah is full of Grace and Bounty to men: yet most men give no thanks.'),
  ('en.yusufali', 40, 62, 'Such is Allah, your Lord, the Creator of all things, there is no god but He: Then how ye are deluded away from the Truth!'),
  ('en.yusufali', 40, 63, 'Thus are deluded those who are wont to reject the Signs of Allah.'),
  ('en.yusufali', 40, 64, 'It is Allah Who has made for you the earth as a resting place, and the sky as a canopy, and has given you shape- and made your shapes beautiful,- and has provided for you Sustenance, of things pure and good;- such is Allah your Lord. So Glory to Allah, the Lord of the Worlds!'),
  ('en.yusufali', 40, 65, 'He is the Living (One): There is no god but He: Call upon Him, giving Him sincere devotion. Praise be to Allah, Lord of the Worlds!'),
  ('en.yusufali', 40, 66, 'Say: "I have been forbidden to invoke those whom ye invoke besides Allah,- seeing that the Clear Signs have come to me from my Lord; and I have been commanded to bow (in Islam) to the Lord of the Worlds."'),
  ('en.yusufali', 40, 67, 'It is He Who has created you from dust then from a sperm-drop, then from a leech-like clot; then does he get you out (into the light) as a child: then lets you (grow and) reach your age of full strength; then lets you become old,- though of you there are some who die before;- and lets you reach a Term appointed; in order that ye may learn wisdom.'),
  ('en.yusufali', 40, 68, 'It is He Who gives Life and Death; and when He decides upon an affair, He says to it, "Be", and it is.'),
  ('en.yusufali', 40, 69, 'Seest thou not those that dispute concerning the Signs of Allah? How are they turned away (from Reality)?-'),
  ('en.yusufali', 40, 70, 'Those who reject the Book and the (revelations) with which We sent our messengers: but soon shall they know,-'),
  ('en.yusufali', 40, 71, 'When the yokes (shall be) round their necks, and the chains; they shall be dragged along-'),
  ('en.yusufali', 40, 72, 'In the boiling fetid fluid: then in the Fire shall they be burned;'),
  ('en.yusufali', 40, 73, 'Then shall it be said to them: "Where are the (deities) to which ye gave part-worship-'),
  ('en.yusufali', 40, 74, '"In derogation of Allah?" They will reply: "They have left us in the lurch: Nay, we invoked not, of old, anything (that had real existence)." Thus does Allah leave the Unbelievers to stray.'),
  ('en.yusufali', 40, 75, '"That was because ye were wont to rejoice on the earth in things other than the Truth, and that ye were wont to be insolent.'),
  ('en.yusufali', 40, 76, '"Enter ye the gates of Hell, to dwell therein: and evil is (this) abode of the arrogant!"'),
  ('en.yusufali', 40, 77, 'So persevere in patience; for the Promise of Allah is true: and whether We show thee (in this life) some part of what We promise them,- or We take thy soul (to Our Mercy) (before that),-(in any case) it is to Us that they shall (all) return.'),
  ('en.yusufali', 40, 78, 'We did aforetime send messengers before thee: of them there are some whose story We have related to thee, and some whose story We have not related to thee. It was not (possible) for any messenger to bring a sign except by the leave of Allah: but when the Command of Allah issued, the matter was decided in truth and justice, and there perished, there and then those who stood on Falsehoods.'),
  ('en.yusufali', 40, 79, 'It is Allah Who made cattle for you, that ye may use some for riding and some for food;'),
  ('en.yusufali', 40, 80, 'And there are (other) advantages in them for you (besides); that ye may through them attain to any need (there may be) in your hearts; and on them and on ships ye are carried.'),
  ('en.yusufali', 40, 81, 'And He shows you (always) His Signs: then which of the Signs of Allah will ye deny?'),
  ('en.yusufali', 40, 82, 'Do they not travel through the earth and see what was the End of those before them? They were more numerous than these and superior in strength and in the traces (they have left) in the land: Yet all that they accomplished was of no profit to them.'),
  ('en.yusufali', 40, 83, 'For when their messengers came to them with Clear Signs, they exulted in such knowledge (and skill) as they had; but that very (Wrath) at which they were wont to scoff hemmed them in.'),
  ('en.yusufali', 40, 84, 'But when they saw Our Punishment, they said: "We believe in Allah,- the one Allah - and we reject the partners we used to join with Him."'),
  ('en.yusufali', 40, 85, 'But their professing the Faith when they (actually) saw Our Punishment was not going to profit them. (Such has been) Allah\'s Way of dealing with His Servants (from the most ancient times). And even thus did the Rejecters of Allah perish (utterly)!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 40, 1, 'Haa-Meeem'),
  ('en.transliteration', 40, 2, 'Tanzeelul Kitaabi minal laahil Azeezil \'Aleem'),
  ('en.transliteration', 40, 3, 'Ghaafiriz zambi wa qaabilit tawbi shadeedil \'iqaabi zit tawli laaa ilaaha illaa Huwa ilaihil maseer'),
  ('en.transliteration', 40, 4, 'Maa yujaadilu feee Aayaatil laahi illal lazeena kafaroo falaa yaghrurka taqallubuhum fil bilaad'),
  ('en.transliteration', 40, 5, 'Kazzabat qablahum qawmu Noohinw wal Ahzaabu mim ba\'dihim wa hammat kullu ummatim bi Rasoolihim liyaa khuzoobhu wa jaadaloo bilbaatili liyudhidoo bihil haqqa fa akhaztuhum fakifa kaana \'iqaab'),
  ('en.transliteration', 40, 6, 'Wa kazaalika haqqat Kalimatu Rabbika \'alal lazeena kafarooo annahum Ashaabun Naar'),
  ('en.transliteration', 40, 7, 'Allazeena yahmiloonal \'Arsha wa man hawlahoo yusabbihoona bihamdi Rabbihim wa yu\'minoona bihee wa yastaghfiroona lillazeena aamanoo Rabbanaa wasi\'ta kulla shai\'ir rahmantanw wa \'ilman faghfir lillazeena taaboo wattaba\'oo sabeelaka wa qihim \'azaabal Jaheem'),
  ('en.transliteration', 40, 8, 'Rabbannaa wa adkhilhum Jannaati \'adninil latee wa\'attahum wa man salaha min aabaaa\'ihim wa azwaajihim wa zurriyyaatihim; innaka Antal \'Azeezul Hakeem'),
  ('en.transliteration', 40, 9, 'Wa qihimus saiyi-aat; wa man taqis saiyi-aati Yawma\'izin faqad rahimtah; wa zaalika huwal fawzul \'azeem'),
  ('en.transliteration', 40, 10, 'Innal lazeena kafaroo yunaadawna lamaqtul laahi akbaru mim maqtikum anfusakum iz tud\'awna ilal eemaani fatakfuroon'),
  ('en.transliteration', 40, 11, 'Qaaloo Rabbanaaa amat tanasnataini wa ahyaitanas nataini fa\'tarafnaa bizunoo binaa fahal ilaa khuroojim min sabeel'),
  ('en.transliteration', 40, 12, 'Zaalikum bi annahooo izaa du\'iyal laahu wahdahoo kafartum wa iny yushrak bihee tu\'minoo; falhukmu lillaahil \'Aliyyil Kabeer'),
  ('en.transliteration', 40, 13, 'Huwal lazee yureekum Aayaatihee wa yunazzilu lakum minas samaaa\'i rizqaa; wa maa tatazakkaru illaa mai yuneeb'),
  ('en.transliteration', 40, 14, 'Fad\'ul laaha mukhliseena lahud deena wa law karihal kaafiroon'),
  ('en.transliteration', 40, 15, 'Rafee\'ud darajaati zul \'Arshi yulqir rooha min amrihee \'alaa mai yashaaa\'u min \'ibaadihee liyunzira yawmat talaaq'),
  ('en.transliteration', 40, 16, 'Yawma hum baarizoona laa yakhfaa \'alal laahi minhum shai; limanil mulkul Yawma lillaahil Waahidil Qahaar'),
  ('en.transliteration', 40, 17, 'Al-Yawma tujzaa kullu nafsim bimaa kasabat; laa zulmal Yawm; innal laaha saree\'ul hisaab'),
  ('en.transliteration', 40, 18, 'Wa anzirhum yawmal aazifati izil quloobu ladal hanaajiri kaazimeen; maa lizzaalimeena min hameeminw wa laa shafee\'iny-yutaa\''),
  ('en.transliteration', 40, 19, 'Ya\'lamu khaaa\'inatal a\'yuni wa maa tukhfis sudoor'),
  ('en.transliteration', 40, 20, 'Wallaahu yaqdee bilhaqq, wallazeena yad\'oona min doonihee laa yaqdoona bishai\'; innal laaha Huwas Samee\'ul Baseer'),
  ('en.transliteration', 40, 21, 'Awalam yaseeroo fil ardi fa yanzuroo kaifa kaana \'aaqibatul lazeena kaanoo min qablihim; kaanoo hum ashadda minhum quwwatanw wa aasaaran fil ardi fa akhazahumul laahu bizunoobihim wa maa kaana lahum minal laahi minw waaq'),
  ('en.transliteration', 40, 22, 'Zaalika bi annahum kaanat taateehim Rusuluhum bilbaiyinaati fakafaroo fa akhazahumul laah; innahoo qawiyyun shadeedul \'iqaab'),
  ('en.transliteration', 40, 23, 'Wa laqad arsalnaa Moosaa bi Aayaatinaa wa sultaanim mubeen'),
  ('en.transliteration', 40, 24, 'Ilaa Fir\'awna wa Haamaana qa Qaaroona faqaaloo saahirun kazzaab'),
  ('en.transliteration', 40, 25, 'Falamuna jaaa\'ahum bil haqqi min \'indinaa qaaluq tulooo abnaaa\'al lazeena aamanoo ma\'ahoo wastahyoo nisaaa\'ahum; wa maa kaidul kaafireena illaa fee dalaal'),
  ('en.transliteration', 40, 26, 'Wa qaala Fir\'awnu zarooneee aqtul Moosaa walyad\'u Rabbahoo inneee akhaafu ai yubaddila deenakum aw ai yuzhira fil ardil fasaad'),
  ('en.transliteration', 40, 27, 'Wa qaala Moosaaaa innee \'uztu bi Rabbee wa Rabbikum min kulli mutakabbiril laayu\'minu bi Yawmil Hisaab'),
  ('en.transliteration', 40, 28, 'Wa qaala rajulum mu\'minummin Aali Fir\'awna yaktumu eemaanahooo ataqtuloona rajulan ai yaqoola Rabbi yal laahu wa qad jaaa\'akum bil haiyinaati mir Rabbikum wa iny yaku kaaziban fa\'alaihi kazi buhoo wa iny yaku saadiqany yasibkum ba\'dul lazee ya\'idukum innal laaha laa yahdee man huwa musrifun kaazaab'),
  ('en.transliteration', 40, 29, 'Yaa qawmi lakumul mulkul yawma zaahireena fil ardi famai yansurunaa mim baasil laahi in jaaa\'anaa; qaala Fir\'awnu maaa ureekum illaa maaa araa wa maaa ahdeekum illaa sabeelar Rashaad'),
  ('en.transliteration', 40, 30, 'Wa qaalal lazee aamana yaa qawmi inneee akhaafu \'alaikum misla yawmil Ahzaab'),
  ('en.transliteration', 40, 31, 'Misla daabi qawmi Noohinw wa \'aadinw wa Samooda wallazeena mim ba\'dihim; wa mal laahu yureedu zulmal lil\'ibaad'),
  ('en.transliteration', 40, 32, 'Wa yaa qawmi inneee akhaafu \'alaikum yawmat tanaad'),
  ('en.transliteration', 40, 33, 'Yawma tuwalloona mud bireena maa lakum minal laahi min \'aasim; wa mai yudlilil laahu famaa lahoo min haad'),
  ('en.transliteration', 40, 34, 'Wa laqad jaaa\'akum Yoosufu min qablu bil baiyinaati famaa ziltum fee shakkim mimaa jaaa\'akum bihee hattaaa izaa halaka qultum lai yab asal laahu mim ba\'dihee Rasoolaa; kazaalika yudillul laahu man huwa Musrifum murtaab'),
  ('en.transliteration', 40, 35, 'Allazeena yujaadiloona feee Aaayaatil laahi bighairi sultaanin ataahum kabura maqtan \'indal laahi wa \'indal lazeena aamanoo; kazaalika yatha\'ul laahu \'alaa kulli qalbi mutakabbirin jabbaar'),
  ('en.transliteration', 40, 36, 'Wa qaala Fir\'awnu yaa Haamaanub-ni lee sarhal la\'alleee ablughul asbaab'),
  ('en.transliteration', 40, 37, 'Asbaabas samaawaati faattali\'a ilaaa ilaahi Moosaa wa innee la azunnuhoo kaazibaa; wa kazaalika zuyyina li-Fir\'awna sooo\'u \'amalihee wa sudda \'anis sabeel; wa maa kaidu Fir\'awna illaa fee tabaab'),
  ('en.transliteration', 40, 38, 'Wa qaalal lazeee aamana yaa qawmit tabi\'ooni ahdikum sabeelar rashaad'),
  ('en.transliteration', 40, 39, 'Yaa qawmi innamaa haazihil hayaatud dunyaa mataa\'unw wa innal Aakhirata hiya daarul qaraar'),
  ('en.transliteration', 40, 40, 'Man \'amila saiyi\'atan falaa yujzaaa illaa mislahaa wa man \'amila saaliham min zakarin aw unsaa wa huwa mu\'minun fa ulaaa\'ika yadkhuloonal Jannata yurzaqoona feehaa bighairi hisaab'),
  ('en.transliteration', 40, 41, 'Wa yaa qawmi maa leee ad\'ookum ilan najaati wa tad\'oonaneee ilan Naar'),
  ('en.transliteration', 40, 42, 'Tad\'oonanee li-akfura billaahi wa ushrika bihee maa laisa lee bihee \'ilmunw wa ana ad\'ookum ilal\'Azeezil Ghaffaar'),
  ('en.transliteration', 40, 43, 'Laa jarama annamaa tad\'oonanee ilaihi laisa lahoo da\'watun fid dunyaa wa laa fil Aakhirati wa anna maraddanaaa ilal laahi wa annal musrifeenahum Ashaabun Naar'),
  ('en.transliteration', 40, 44, 'Fasatazkuroona maaa aqoolu lakum; wa ufawwidu amreee ilal laah; innallaaha baseerum bil\'ibaad'),
  ('en.transliteration', 40, 45, 'Fa waqaahul laahu saiyiaati maa makaroo wa haaqa bi Aali-Fir\'awna sooo\'ul \'azaab'),
  ('en.transliteration', 40, 46, 'An Naaru yu\'radoona \'alaihaa ghuduwwanw wa \'ashiyyanw wa Yawma taqoomus Saa\'aatu adkhilooo Aala Fir\'awna ashaddal \'azaab'),
  ('en.transliteration', 40, 47, 'Wa iz yatahaaajjoona fin Naari fa-yaqoolud du\'afaaa\'u lillazeenas takbarooo innaa kunnaa lakum taba\'an fahal antum mughnoona annaa naseebam minan Naar'),
  ('en.transliteration', 40, 48, 'Qaalal lazeenas takbarooo innaa kullun feehaaa innal laaha qad hakama baynal\'ibaad'),
  ('en.transliteration', 40, 49, 'Wa qaalal lazena fin Naari likhazanati Jahannamad-\'oo Rabbakum yukhaffif \'annaa yawmam minal \'azaab'),
  ('en.transliteration', 40, 50, 'Qaalooo awalam taku taateekum Rusulukum bilbaiyinaati qaaloo balaa\' qaaloo fad\'oo; wa maa du\'aaa\'ul kaafireena illaa fee dalaal'),
  ('en.transliteration', 40, 51, 'Innaa lanansuru Rusulanaa wallazeena aamanoo fil hayaatid dunyaa wa Yawma yaqoomul ashhaad'),
  ('en.transliteration', 40, 52, 'Yawma laa yanfa\'uz zaalimeena ma\'ziratuhum wa lahumul la\'natu wa lahum soooud daar'),
  ('en.transliteration', 40, 53, 'Wa laqad aatainaa Moosal hudaa wa awrasnaa Baneee Israaa \'eelal Kitaab'),
  ('en.transliteration', 40, 54, 'Hudanw wa zikraa li ulil albaab'),
  ('en.transliteration', 40, 55, 'Fasbir inna wa\'dal laahi haqqunw wastaghfir lizambika wa sabbih bihamdi Rabbika bil\'ashiyyi wal ibkaar'),
  ('en.transliteration', 40, 56, 'Innal lazeena yujaadi loona feee Aayaatil laahi bighairi sultaanin ataahum in fee sudoorihim illaa kibrum maa hum bibaaligheeh; fasta\'iz billaahi innahoo Huwas Samee\'ul Baseer'),
  ('en.transliteration', 40, 57, 'Lakhalqus samaawaati wal ardi akbaru min khalqin naasi wa laakinna aksaran naasi laa ya\'lamoon'),
  ('en.transliteration', 40, 58, 'Wa maa yastawil a\'maa walbaseeru wallazeena aamanoo wa \'amilus saalihaati wa lal museee\'; qaleelam maa tatazakkaroon'),
  ('en.transliteration', 40, 59, 'Innas Saa\'ata la aatiyatul laa raiba feehaa wa laakinna aksaran naasi laa yu\'minoon'),
  ('en.transliteration', 40, 60, 'Wa qaala Rabbukumud \'ooneee astajib lakum; innal lazeena yastakbiroona an \'ibaadatee sa yadkhuloona jahannama daakhireen'),
  ('en.transliteration', 40, 61, 'Allaahul lazee ja\'ala lakumul laila litqaskunoo feehi wannahaara mubsiraa; innal laaha lazoo fadlin \'alan naasi wa laakinna aksaran naasi laa yashkuroon'),
  ('en.transliteration', 40, 62, 'Zaalikumul laahu Rabbukum khaaliqu kulli shai\'; laaa ilaaha illaa Huwa fa annaa tu\'fakoon'),
  ('en.transliteration', 40, 63, 'Kazaalika yu\'fakul loazeena kaanoo bi Aayaatil laahi yajhadoon'),
  ('en.transliteration', 40, 64, 'Allaahul lazee ja\'ala lakumul arda qaraaranw wassa maaa\'a binaaa\'anw wa sawwarakum fa ahsana suwarakum wa razaqakum minat taiyibaat; zaalikumul laahu Rabbukum fatabaarakal laahu Rabbul \'aalameen'),
  ('en.transliteration', 40, 65, 'Huwal Hayyu laaa ilaaha illaa Huwa fad\'oohu mukh liseena lahudeen; alhamdu lillaahi Rabbil \'aalameen'),
  ('en.transliteration', 40, 66, 'Qul innee nuheetu an a\'budal lazeena tad\'oona min doonil laahi lammaa jaaa\'a niyal biyinaatu mir Rabbee wa umirtu an uslima li Rabbil \'aalameen'),
  ('en.transliteration', 40, 67, 'Huwal lazee khalaqakum min turaabin summa min nutfatin summa min \'alaqatin summa yukhrijukum tiflan summa litablughooo ashuddakum summa litakoonoo shuyookhaa; wa minkum mai yutawaffaa min qablu wa litablughooo ajalam musam manw-wa la\'allakum ta\'qiloon'),
  ('en.transliteration', 40, 68, 'Huwal lazee yuhyee wa yumeetu fa izaa qadaaa amran fa innamaa yaqoolu lahoo kun fa yakon'),
  ('en.transliteration', 40, 69, 'Alam tara ilal lazeena yujaadiloona feee Aayaatil laahi annaa yusrafoon'),
  ('en.transliteration', 40, 70, 'Allazeena kazzaboo bil Kitaabi wa bimaa arsalnaa bihee Rusulanaa fasawfa ya\'lamoon'),
  ('en.transliteration', 40, 71, 'Izil aghlaalu feee a\'naaqi-him wassalaasilu yashaboon'),
  ('en.transliteration', 40, 72, 'Fil hameemi summa fin Naari Yasjaroon'),
  ('en.transliteration', 40, 73, 'Summaa qeela lahum ayna maa kuntum tushrikoon'),
  ('en.transliteration', 40, 74, 'Min doonil laahi qaaloo dalloo \'annaa bal lam nakun nad\'oo min qablu shai\'aa; kazaalika yudillul laahul kaafireen'),
  ('en.transliteration', 40, 75, 'Zaalikum bimaa kuntum tafrahoona fil ardi bighairil haqqi wa bimaa kuntum tamrahoon'),
  ('en.transliteration', 40, 76, 'Udkhulooo abwaaba Jahannama khaalideena feehaa fabi\'sa maswal mutakabbireen'),
  ('en.transliteration', 40, 77, 'Fasbir inna wa\'dal laahi haqq; fa immaa nuriyannak ba\'dal lazee na\'i duhum aw natawaffayannaka fa ilainaa yurja\'oon'),
  ('en.transliteration', 40, 78, 'Wa laqad arsalnaa Rusulam min qablika minhum man qasasnaa \'alaika wa minhum mal lam naqsus \'alaik; wa maa kaana li Rasoolin any yaatiya bi Aayatin illaa bi iznil laah; fa izaa jaaa\'a amrul laahi qudiya bilhaqqi wa khasira hunaalikal mubtiloon'),
  ('en.transliteration', 40, 79, 'Allaahul lazee ja\'ala lakumul an\'aama litarkaboo minhaa wa minhaa taakuloon'),
  ('en.transliteration', 40, 80, 'Wa lakum feehaa manaafi\'u wa litablughoo \'alaihaa haajatan fee sudoorikum wa \'alaihaa wa \'alal fulki tuhmaloon'),
  ('en.transliteration', 40, 81, 'Wa yureekum Aayaatihee fa ayya Aayaatil laahi tunkiroon'),
  ('en.transliteration', 40, 82, 'Afalam yaseeroo fil ardi fa yanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; kaanoo aksara minhum wa ashadda quwwatanw wa aasaaran fil ardi famaaa aghnaa \'anhum maa kaanoo yaksiboon'),
  ('en.transliteration', 40, 83, 'Falammaa jaaa\'at hum Rusuluhum bilbaiyinaati farihoo bimaa \'indahum minal \'ilmi wa haaqa bihim maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 40, 84, 'Falammaa ra aw baasanaa qaalooo aamannaa billaahi wahdahoo wa kafarnaa bimaa kunnaa bihee mushrikeen'),
  ('en.transliteration', 40, 85, 'Falam yaku tanfa \'uhum eemaanuhum lammaa ra-aw baasana sunnatal laahil latee qad khalat fee \'ibaadihee wa khasira hunaalikal kaafiroon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 40, 1, 'حمۤ'),
  ('ur.ahmedali', 40, 2, 'یہ کتاب الله کی طرف سے نازل ہوئی ہے جو غالب ہر چیز کا جاننے والا ہے'),
  ('ur.ahmedali', 40, 3, 'گناہ بخشنے والا اور توبہ قبول کرنے والا سخت عذاب دینے والا قدرت والا ہے اس کے سوا کوئی معبود نہیں اسی کی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 40, 4, 'الله کی آیتوں میں نہیں جھگڑتے مگر وہ لوگ جو کافر ہیں پس ان کا شہرو ں میں چلنا پھرنا آپ کو دھوکا نہ دے'),
  ('ur.ahmedali', 40, 5, 'ان سے پہلے قوم نوح اور ان کے بعد اور فرقے بھی جھٹلا چکے ہیں اور ہر ایک امت نے اپنے رسول کو پکڑنے کا ارادہ کیا اور غلط باتوں کے ساتھ بحث کرتے رہے تاکہ اس سے دین حق کو مٹا دیں پھر ہم نے انھیں پکڑ لیا پھر کیسی سزا ہوئی'),
  ('ur.ahmedali', 40, 6, 'اور اسی طرح منکروں پر الله کا کلام پورا ہوا کہ وہ دوزخی ہیں'),
  ('ur.ahmedali', 40, 7, 'جو (فرشتے) عرش کو اٹھائے ہوئے ہیں اور جو اس کے گرد ہیں وہ اپنے رب کی حمد کے ساتھ تسبیح کرتے رہتے ہیں اور اس پر ایمان لاتے ہیں اور ایمانداروں کے لیے بخشش مانگتے ہیں کہ اے ہمارے رب تیری رحمت اور تیرا علم سب پر حاوی ہے پھر جن لوگو ں نے توبہ کی ہے اور تیرے راستے پر چلتے ہیں انہیں بخش دے اور انہیں دوزخ کے عذاب سے بچا لے'),
  ('ur.ahmedali', 40, 8, 'اے ہمارے رب اور انہیں بہشتوں میں داخل کر جو ہمیشہ رہیں گی جن کا تو نے ان سے وعدہ کیا ہے اور ان کو جو ان کے باپ دادوں اوران کی بیویوں اوران کی اولاد میں سے نیک ہیں بے شک تو غالب حکمت والا ہے'),
  ('ur.ahmedali', 40, 9, 'اور انہیں برائیوں سے بچا اور جس کو تو اس دن برائیوں سے بچائے گا سو اس پر تو نے رحم کر دیا اور یہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 40, 10, 'بے شک جو لوگ کافر ہیں انہیں پکار کر کہا جائے گا جیسی تمہیں (اس وقت) اپنے سے نفرت ہے اس سے بڑھ کر الله کو (تم سے) نفرت تھی جبکہ تم ایمان کی طرف بلائے جاتے تھے پھر نہیں مانا کرتے تھے'),
  ('ur.ahmedali', 40, 11, 'وہ کہیں گے اے ہمارے رب تو نے ہمیں دو بار موت دی اورتو نے ہمیں دوبارہ زندہ کیا پس ہم نے اپنے گناہوں کا اقرار کر لیا پس کیا نکلنے کی بھی کوئی راہ ہے'),
  ('ur.ahmedali', 40, 12, 'یہ عذاب اس لیے ہے کہ جب تم اکیلے الله کی طرف بلایا جاتا تھا تو انکار کرتے تھے اورجب اس کے ساتھ شریک کیا جاتا تھا تو مان لیتے تھے سو یہ فیصلہ الله کا ہے جو عالیشان بڑے رتبے والا ہے'),
  ('ur.ahmedali', 40, 13, 'وہی ہے جو تمہیں اپنی نشانیاں دکھاتا ہے اور تمہارے لیے آسمان سے رزق نازل کرتا ہے اور سمجھتا وہی ہے جو (الله کی طرف) رجوع کرتا ہے'),
  ('ur.ahmedali', 40, 14, 'پس الله کو پکارو اس کے لیے عبادت کو خالص کرتے ہوئے اگرچہ کافر برا منائیں'),
  ('ur.ahmedali', 40, 15, 'وہ اونچے درجوں والا عرش کا مالک ہے اپنے حکم سے اپنےبندوں میں سے جس کے پاس چاہتا ہے وحی بھیجتا ہے تاکہ وہ ملاقات (قیامت) کے دن سے ڈرائے'),
  ('ur.ahmedali', 40, 16, 'جس دن وہ سب نکل کھڑے ہوں گے الله پر ان کی کوئی بات چھپی نہ رہے گی آج کس کی حکومت ہے الله ہی کی جو ایک ہے بڑا غالب'),
  ('ur.ahmedali', 40, 17, 'آج کے دن ہر شخص اپنے کیے کا بدلہ پائے گا آج کچھ ظلم نہ ہوگا بے شک الله جلد حساب لینے والا ہے'),
  ('ur.ahmedali', 40, 18, 'اور انہیں قریب آنے والی (مصیبت) کے دن سے ڈرا جب کہ غم کے مارے کلیجے منہ کو آ رہے ہوں گے ظالموں کا کوئی حمایتی نہیں ہوگا اور نہ کوئی سفارشی جس کی بات مانی جائے'),
  ('ur.ahmedali', 40, 19, 'وہ آنکھوں کی خیانت اور دل کے بھید جانتا ہے'),
  ('ur.ahmedali', 40, 20, 'اور الله ہی انصاف کے ساتھ فیصلہ کرے گا اور جنہیں وہ اس کے سوا پکارتے ہیں وہ کچھ بھی فیصلہ نہیں کر سکتے بیشک الله ہی سب کچھ سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 40, 21, 'کیا انہوں نے زمین میں سیر نہیں کی کہ وہ دیکھتے ان لوگو ں کا انجام کیسا تھا جو ان سے پہلے ہو گزرے ہیں وہ قوت میں ان سے بڑھ کر تھے اور زمین میں آثار کے اعتبار سے بھی پھر الله نے انہیں ان کے گناہوں کے سبب سے پکڑ لیا اوران کے لیے الله سے کوئی بچانے والا نہ تھا'),
  ('ur.ahmedali', 40, 22, 'یہ اس لیے کہ ان کے پاس ان کے رسول روشن دلیلیں لے کر آتے تھے تو وہ انکار کرتے تھے پس انہیں الله نے پکڑ لیا بے شک وہ بڑا قوت والا سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 40, 23, 'اور ہم نے موسیٰ کو اپنے معجزات اور واضح دلیل دے کر بھیجا تھا'),
  ('ur.ahmedali', 40, 24, 'فرعون اور ہامان اور قارون کی طرف تو وہ کہنے لگے بڑا جھوٹا جادوگر ہے'),
  ('ur.ahmedali', 40, 25, 'پس جب وہ ان کے پاس ہماری طرف سے سچا دین لائے تو کہنے لگے ان لوگوں کے بیٹوں کو قتل کر دو جو موسیٰ پر ایمان لائے ہیں اور ان کی عورتوں کو زندہ رہنے دو اور کافروں کے داؤ تو محض غلط ہوا کرتے ہیں'),
  ('ur.ahmedali', 40, 26, 'اور فرعون نے کہا مجھے چھوڑ دو میں موسیٰ کو قتل کر دوں اور وہ اپنے رب کو پکارے میں ڈرتا ہوں کہ وہ تمہارے دین کو بدل ڈالے گا یا یہ کہ زمین میں فساد پھیلائے گا'),
  ('ur.ahmedali', 40, 27, 'اور موسیٰ نے کہا میں تو اپنی اور تمہارے رب کی پناہ لے چکا ہوں ہر ایک متکبّر سے جو حساب کے دن پر یقین نہیں رکھتا'),
  ('ur.ahmedali', 40, 28, 'اور فرعون کی قوم میں سے ایک ایمان دار آدمی نے کہا جو اپنا ایمان چھپاتا تھا کیاتم ایسے آدمی کو قتل کرتے ہو جو یہ کہتا ہے کہ میرا رب الله ہے اوروہ تمہارے پاس وہ روشن دلیلیں تمہارے رب کی طرف سے لایا ہے اور اگر وہ جھوٹا ہے تو اسی پر ا س کے جھوٹ کا وبال ہے اور اگر وہ سچا ہے تو تمہیں کچھ نہ کچھ وہ (عذاب) جس کا وہ تم سے وعدہ کرتا ہے پہنچے گا اور الله اس کو راہ پر نہیں لاتا جو حد سے بڑھنے والا بڑا جھوٹا ہے'),
  ('ur.ahmedali', 40, 29, 'اے میری قوم آج تو تمہاری حکومت ہے تم ملک میں غالب ہو ہماری کون مدد کرے گا اگر ہم پر الله کا عذاب آگیا فرعون نے کہا میں تو تمہیں وہی سوجھاتا ہوں جو مجھے سوجھی ہے اور میں تمہیں سیدھا ہی راستہ بتاتا ہوں'),
  ('ur.ahmedali', 40, 30, 'اور اس شخص نے کہا جو ایمان لایا تھا کہ اےمیری قوم مجھے تو تمہاری نسبت (پہلی) امتوں جیسے دن کا اندیشہ ہو رہا ہے'),
  ('ur.ahmedali', 40, 31, 'جیسا کہ قوم نوح اور عاد اور ثمود اور ان سے پچھلوں کا حال ہوا اور الله تو بندوں پر کچھ بھی ظلم نہیں کرنا چاہتا'),
  ('ur.ahmedali', 40, 32, 'اور اے میری قوم مجھے تم پر چیخ و پکار (قیامت) کے دن کا اندیشہ ہے'),
  ('ur.ahmedali', 40, 33, 'جس دن تم پیٹھ پھیر کر بھاگو گے الله سے تمہیں کوئی بچانے والا نہیں ہوگا اور جسے الله گمراہ کر دے پھر اسے کوئی راہ بتانے والا نہیں'),
  ('ur.ahmedali', 40, 34, 'اور تمہارے پاس یوسف بھی اس سے پہلے واضح دلیلیں لے کر آ چکا پس تم ہمیشہ اس سے شک میں رہے جو وہ تمہارے پاس لایا یہاں تک کہ جب وہ فوت ہو گیا تو تم نےکہا کہ الله اس کے بعد کوئی رسول ہر گز نہیں بھیجے گا اسی طرح الله گمراہ کرتا ہے اس کو جو حد سے بڑھنے والا شک کرنے والا ہے'),
  ('ur.ahmedali', 40, 35, 'جو لوگ الله کی آیتوں میں کسی دلیل کے سوا جو ان کے پاس پہنچی ہو جھگڑتے ہیں الله اور ایمان والوں کے نزدیک (یہ) بڑی نازیبا بات ہے الله ہر ایک متکبّر سرکش کے دل پر اسی طرح مہر کر دیا کرتا ہے'),
  ('ur.ahmedali', 40, 36, 'اور فرعون نے کہا اے ہامان میرے لیے ایک محل بنا تاکہ میں راستوں پر پہنچوں'),
  ('ur.ahmedali', 40, 37, 'یعنی آسمان کے راستوں پر پھر موسیٰ کے خدا کی طرف جھانک کر دیکھوں اور میں تو اسے جھوٹا خیال کرتا ہوں اور اسی طرح فرعون کو اس کا برا عمل اچھا معلوم ہوا اور وہ راستہ سے روکا گیا تھا اور فرعون کی ہر تدبیر غارت ہی گئی'),
  ('ur.ahmedali', 40, 38, 'اوراس شخص نے کہا جو ایمان لایا تھا اے میری قوم تم میری پیروی کرو میں تمہیں نیکی کی راہ بتاؤں گا'),
  ('ur.ahmedali', 40, 39, 'اے میری قوم دنیا کی زندگی بس (چند روزہ) فائدے ہیں اور آخرت کا گھر ہی ٹھہرنے کی جگہ ہے'),
  ('ur.ahmedali', 40, 40, 'جس نے برا کام کیا تو اتنی ہی سزا پائے گا اور جس نے نیک کام کیا خواہ وہ مرد ہو یا عورت اور وہ ایمانداربھی ہو سو وہ جنت میں داخل ہوں گے جہاں انہیں بے حساب روزی ملے گی'),
  ('ur.ahmedali', 40, 41, 'اور اے میری قوم کیا بات ہے میں تو تمہیں نجات کی طرف بلاتا ہوں اور تم مجھے دوزخ کی طرف بلاتے ہو'),
  ('ur.ahmedali', 40, 42, 'تم مجھے اس بات کی طرف بلاتے ہو کہ میں الله کا منکر ہو جاؤں اور اس کے ساتھ اسے شریک کروں جسے میں جانتا بھی نہیں اور میں تمہیں غالب بخشنے والے کی طرف بلاتاہوں'),
  ('ur.ahmedali', 40, 43, 'بے شک تم مجھے جس کی طرف بلاتے ہو وہ نہ دنیا میں بلانے کے قابل ہے اور نہ آخرت میں اور بےشک ہمیں الله کی طرف لوٹ کر جانا ہے اور بے شک حد سے بڑھنے والے ہی دوزخی ہیں'),
  ('ur.ahmedali', 40, 44, 'پھر تم میری بات کو یاد کرو گے اور میں اپنا معاملہ الله کے سپرد کرتا ہوں بے شک الله بندوں کو دیکھ رہا ہے'),
  ('ur.ahmedali', 40, 45, 'پھر الله نے اسے تو ان کے فریبوں کی برائی سے بچایا اور خود فرعونیوں پر سخت عذاب آ پڑا'),
  ('ur.ahmedali', 40, 46, 'وہ صبح او رشام آگ کے سامنے لائے جاتے ہیں اور جس دن قیامت قائم ہو گی (حکم ہوگا) فرعونیوں کو سخت عذاب میں لے جاؤ'),
  ('ur.ahmedali', 40, 47, 'اور جب دوزخی آپس میں جھگڑیں گےپھر کمزور سرکشوں سے کہیں گے کہ ہم تمہارے پیرو تھے پھر کیا تم ہم سے کچھ بھی آگ دور کر سکتے ہو'),
  ('ur.ahmedali', 40, 48, 'سرکش کہیں گے ہم تم سبھی اس میں پڑے ہوئے ہیں بے شک الله اپنے بندوں میں فیصلہ کر چکا ہے'),
  ('ur.ahmedali', 40, 49, 'اور دوزخی جہنم کے داروغہ سے کہیں گے کہ تم اپنے رب سے عرض کرو کہ وہ ہم سے کسی روز تو عذاب ہلکا کر دیا کرے'),
  ('ur.ahmedali', 40, 50, 'وہ کہیں گے کیا تمہارے پاس تمہارے رسول نشانیاں لے کر نہ آئے تھے کہیں گے ہاں (آئے تھے) کہیں گے پس پکارو اور کافروں کا پکارنا محض بے سود ہو گا'),
  ('ur.ahmedali', 40, 51, 'ہم اپنے رسولوں اور ایمانداروں کے دنیا کی زندگی میں بھی مددگار ہیں اور اس دن جب کہ گواہ کھڑے ہوں گے'),
  ('ur.ahmedali', 40, 52, 'جس دن ظالموں کو ان کا عذر کرنا کچھ بھی نفع نہ دے گا اور ان پر پھٹکار پڑے گی اور ان کے لیے برا گھر ہوگا'),
  ('ur.ahmedali', 40, 53, 'اور ہم نے موسیٰ کو ہدایت دی تھی اور ہم نے بنی اسرائیل کو کتاب کا وارث کر دیا تھا'),
  ('ur.ahmedali', 40, 54, 'جو عقلمندوں کے لیے ہدایت اور نصیحت تھی'),
  ('ur.ahmedali', 40, 55, 'پس صبر کر بے شک الله کا وعدہ سچا ہے اور اپنے گناہ کی معافی مانگ اور شام اور صبح اپنے رب کی حمد کے ساتھ پاکی بیان کر'),
  ('ur.ahmedali', 40, 56, 'بے شک جو لوگ الله کی آیتوں میں بغیر اس کے کہ ان کے پاس کوئی دلیل آئی ہو جھگڑتے ہیں اور کچھ نہیں بس ان کے دل میں بڑائی ہے کہ وہ اس تک کبھی پہنچنے والے نہیں سو الله سے پناہ مانگو کیوں کہ وہ سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 40, 57, 'البتہ آسمانوں اور زمین کا پیدا کرنا آدمیوں کے پیدا کرنے کی نسبت بڑا کام ہے لیکن اکثر لوگ نہیں جانتے'),
  ('ur.ahmedali', 40, 58, 'اور اندھا اور دیکھنے والا برابر نہیں اور جو لوگ ایمان لائے اور نیک کام کئے وہ اور بدکار برابر نہیں تم بہت ہی کم سمجھتے ہو'),
  ('ur.ahmedali', 40, 59, 'بے شک قیامت آنے والی ہے اس میں کوئی شک نہیں لیکن اکثر لوگ یقین نہیں کرتے'),
  ('ur.ahmedali', 40, 60, 'اور تمہارے رب نے فرمایا ہے مجھے پکارو میں تمہاری دعا قبول کروں گا بے شک جو لوگ میری عبادت سے سرکشی کرتے ہیں عنقریب وہ ذلیل ہو کر دوزخ میں داخل ہوں گے'),
  ('ur.ahmedali', 40, 61, 'الله ہی ہے جس نے تمہارے لیے رات بنائی تاکہ اس میں آرام کرو اور دن کو ہر چیز دکھانے والا بنایا بے شک الله لوگوں پر بڑے فضل والا ہے لیکن اکثر لوگ شکر نہیں کرتے'),
  ('ur.ahmedali', 40, 62, 'یہی الله تمہارا رب ہے ہر چیز کا پیدا کرنے والا اس کے سوا کوئی معبود نہیں پھر کہاں الٹے جا رہے ہو'),
  ('ur.ahmedali', 40, 63, 'اسی طرح وہ لوگ بھی الٹے چلا کرتے تھے جو الله کی نشانیوں کا انکار کیا کرتے تھے'),
  ('ur.ahmedali', 40, 64, 'الله ہی ہے جس نے تمہارے لیے زمین کو آرام گاہ بنایا اور آسمان کو چھت اور تمہاری صورتیں بنائیں اور پاکیزہ چیزوں سے تمہیں رزق دیا وہی الله تمہارا پالنے والا ہے پس سارے جہان کا پالنے والا الله با برکت ہے'),
  ('ur.ahmedali', 40, 65, 'وہی ہمیشہ زندہ ہے اس کے سوا کوئی معبود نہیں پس اسی کو پکارو خاص اسی کی بندگی کرتے ہوئے سب تعریف الله کے لیے ہے جو سارے جہان کا پالنے والا ہے'),
  ('ur.ahmedali', 40, 66, 'کہہ دو مجھے تو ان چیزوں کی عبادت سے منع کیا گیا ہے جن کو تم الله کے سوا پکارتے ہو جب کہ میرے رب کی طرف سے میرے پاس کھلی کھلی نشانیاں آچکی ہیں اور مجھے یہ حکم دیا گیا ہے کہ میں رب العالمین کے سامنے سر جھکاؤں'),
  ('ur.ahmedali', 40, 67, 'وہی ہے جس نے تمہیں مٹی سے پھر نطفے سے پھر خون بستہ سے پیدا کیا پھر وہ تمہیں بچہ بنا کر نکالتا ہے پھر باقی رکھتا ہے تاکہ تم اپنی جوانی کو پہنچو پھر یہاں تک کہ تم بوڑھے ہو جاتے ہو کچھ تم میں اس سے پہلے مر جاتے ہیں (بعض کو زندہ رکھتا ہےاور تاکہ تم وقت مقررہ تک پہنچو اور تاکہ تم سمجھو'),
  ('ur.ahmedali', 40, 68, 'وہی ہے جو زندہ کرتا ہے اور مارتا ہے پس جب وہ کسی امر کیا فیصلہ کرلیتا ہے تو صرف اس سے یہی کہتا ہے کو ہو جا تو وہ ہو جاتا ہے'),
  ('ur.ahmedali', 40, 69, 'کیا آپ نے ان لوگوں کو نہیں دیکھا جو الله کی آیتوں میں جھگڑتے ہیں وہ کہاں پھرے چلے جا رہے ہیں'),
  ('ur.ahmedali', 40, 70, 'وہ لوگ جنہوں نے کتاب کو اور جو کچھ ہم نے رسولوں کو دے کر بھیجا تھا سب کو جھٹلا دیا پس انہیں معلوم ہو جائے گا'),
  ('ur.ahmedali', 40, 71, 'جب کہ طوق اور زنجیریں ان کے گلے میں ڈال کر گھسیٹے جائيں گے'),
  ('ur.ahmedali', 40, 72, 'کھولتے پانی میں پھر آگ میں جھونکے جائیں گے'),
  ('ur.ahmedali', 40, 73, 'پھر ان سے کہا جائے گا کہاں ہیں جنھیں تم شریک بتاتے تھے'),
  ('ur.ahmedali', 40, 74, 'الله کے سوا وہ کہیں گے ہم سے وہ کھوئے گئے بلکہ ہم تو اس سے پہلے کسی چیز کو بھی نہیں پکارتے تھے اسی طرح الله کافروں کو گمراہ کرتا ہے'),
  ('ur.ahmedali', 40, 75, 'یہ عذاب تمہیں اس لیے ہوا کہ تم ملک میں ناحق خوشیاں مناتے تھے اور اس لیے بھی کہ تم اترایا کرتے تھے'),
  ('ur.ahmedali', 40, 76, 'جہنم کے دروازوں میں ہمیشہ رہنے کے لیے داخل ہو جاؤ پھر تکبر کرنے والوں کا کیا ہی برا ٹھکانہ ہے'),
  ('ur.ahmedali', 40, 77, 'پھر صبر کر بے شک الله کا وعدہ سچا ہے پھر جس (عذاب) کا ہم ان سے وعدہ کر رہے ہیں کچھ تھوڑا سا اگر ہم آپ کو دکھا دیں یا ہم آپ کو وفات دے د یں تو ہماری طرف ہی سب لوٹائے جائیں گے'),
  ('ur.ahmedali', 40, 78, 'اورہم نے آپ سے پہلے کئی رسول بھیجے تھے بعض ان میں سے وہ ہیں جن کا حال ہم نے آپ پر بیان کر دیا اور بعض وہ ہیں کہ ہم نے آپ پر انکا حال بیان نہیں کیا اور کسی رسول سے یہ نہ ہو سکا کہ کوئی معجزہ اذنِ الہیٰ کے سوا ظاہر کر سکے پھر جس وقت الله کا حکم آئے گا ٹھیک فیصلہ ہو جائے گا اوراس وقت باطل پرست نقصان اٹھائیں گے'),
  ('ur.ahmedali', 40, 79, 'الله ہی ہے جس نے تمہارے لیے چوپائے بنائے تاکہ تم ان میں سے بعض پر سوار ہو اور بعض کو تم کھاتے ہو'),
  ('ur.ahmedali', 40, 80, 'اور تمہارے لیے ان میں بہت سے فوائد ہیں اور تاکہ تم ان پر سوار ہو کر اپنی حاجت کو پہنچو جو تمہارے سینوں میں ہے اور ان پر اور نیز کشتیوں پر تم سوارکیے جاتے ہو'),
  ('ur.ahmedali', 40, 81, 'اور وہ تمہیں اپنی نشانیاں دکھاتا ہے پس تم الله کی کون کون سی نشانیوں کا انکار کرو گے'),
  ('ur.ahmedali', 40, 82, 'پس کیا انہوں نے ملک میں چل پھر کر نہیں دیکھا کہ جو لوگ ان سے پہلے ہو گزرے ہیں ان کا کیا انجام ہوا وہ لوگ ان سے زیادہ تھے اور قوت اور نشانوں میں (بھی) جو کہ زمین پر چھوڑگئے ہیں بڑھے ہوئے تھے پس ان کے نہ کام آیا جو کچھ وہ کماتے تھے'),
  ('ur.ahmedali', 40, 83, 'پس جب ان کے رسول ان کے پا س کھلی دلیلیں لائے تووہ اپنے علم و دانش پر اترانے لگے اور جس پر وہ ہنسی کرتےتھے وہ ان پر الٹ پڑا'),
  ('ur.ahmedali', 40, 84, 'پھر جب انہوں نے ہمارا عذاب آتے دیکھا تو کہنے لگے کہ ہم الله پر ایمان لائےجو ایک ہے اور ہم نے ان چیزوں کا انکار کیا جنہیں ہم اس کا شریک ٹھیراتے تھے'),
  ('ur.ahmedali', 40, 85, 'پس انہیں ان کے ایمان نے نفع نہ دیا جب انہوں نے ہمارا عذاب دیکھ لیا یہ سنت الہیٰ ہے جو اس کے بندو ں میں گزر چکی ہے اور اس وقت کافر خسارہ میں رہ گئے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 40, 1, 'Ha, Mim.'),
  ('tr.diyanet', 40, 2, 'Kitap\'ın indirilmesi, güçlü ve bilgin olan Allah katındandır.'),
  ('tr.diyanet', 40, 3, 'O, günahı bağışlayan, tevbeyi kabul eden, cezası şiddetli, lütfu bol olandır. O\'ndan başka tanrı yoktur, dönüş O\'nadır.'),
  ('tr.diyanet', 40, 4, 'Allah\'ın ayetleri üzerinde, inkar edenlerden başkası tartışmaya girişmez. İnkarcıların memlekette gezip dolaşması seni aldatmasın.'),
  ('tr.diyanet', 40, 5, 'Onlardan önce, Nuh milleti, ardından, peygamberlere karşı gelen topluluklar da peygamberlerini yalanlamış; her ümmet, peygamberini cezalandırmaya azmetmişti. Hakkı batılla gidermek için mücadele etmişlerdi. Bunun üzerine Ben onları yakaladım. Cezalandırmam nasılmış?'),
  ('tr.diyanet', 40, 6, 'İnkar edenlerin cehennemlik olduklarına dair Rabbinin sözü böylece gerçekleşti.'),
  ('tr.diyanet', 40, 7, 'Arşı yüklenen ve çevresinde bulunanlar, Rablerini överek tesbih ederler; O\'na inanırlar. Müminler için: "Rabbimiz! İlmin ve rahmetin herşeyi içine almıştır. Tevbe edip Senin yoluna uyanları bağışla; onları cehennemin azabından koru" diye bağışlanma dilerler.'),
  ('tr.diyanet', 40, 8, '"Rabbimiz! Müminleri ve babalarından, eşlerinden, soylarından iyi olanları, kendilerine söz verdiğin Adn cennetlerine koy; şüphesiz güçlü olan, Hakim olan ancak Sensin"'),
  ('tr.diyanet', 40, 9, '"Onları kötülüklerden koru! O gün kötülüklerden kimi korursan, ona şüphesiz rahmet etmiş olursun. Bu büyük kurtuluştur."'),
  ('tr.diyanet', 40, 10, 'Ama inkar edenlere, "Allah\'ın gazabı, sizin birbirinize olan öfkenizden daha büyüktür; imana çağrıldığınızda inkar ederdiniz" diye seslenilir.'),
  ('tr.diyanet', 40, 11, 'Onlar: "Rabbimiz! Bizi iki defa öldürdün, iki defa dirilttin. Biz de suçlarımızı itiraf ettik, bir daha çıkmağa yol var mıdır?" derler.'),
  ('tr.diyanet', 40, 12, 'Onlara: "Yalnız Allah çağrıldığı zaman inkar ederdiniz de, O\'na eş koşulunca inanırdınız. Bugün hüküm, yüce Allah\'ındır" denir.'),
  ('tr.diyanet', 40, 13, 'Size mucizelerini gösteren, size gökten rızık indiren O\'dur. Allah\'a yönelenden başkası ibret almaz.'),
  ('tr.diyanet', 40, 14, 'Ey inananlar! İnkarcılar istemese de, dini yalnız Allah\'a has kılarak O\'na yalvarın.'),
  ('tr.diyanet', 40, 15, 'Arş sahibi, varlıkların en yücesi olan Allah, kavuşma gününü ihtar etmek için kullarından dilediğine emriyle vahyi indirir.'),
  ('tr.diyanet', 40, 16, 'O gün onlar meydana çıkarlar; onların hiçbir şeyi Allah\'a gizli kalmaz. "Bugün hükümranlık kimindir?" denir; hepsi: "Gücü herşeye yeten tek Allah\'ındır" derler.'),
  ('tr.diyanet', 40, 17, 'Bugün herkese, kazandığının karşılığı verilir. Bugün haksızlık yoktur. Doğrusu Allah, hesabı çabuk görendir.'),
  ('tr.diyanet', 40, 18, 'Onları, yüreklerin ağıza geleceği, tasadan yutkunacakları, yaklaşan kıyamet günü ile uyar. Zalimlerin ne dostu ne de sözü dinlenecek şefaatçisi olur.'),
  ('tr.diyanet', 40, 19, 'Allah gözlerin hainliğini ve gönüllerin gizlediğini bilir.'),
  ('tr.diyanet', 40, 20, 'Allah, gerçekle hükmeder. O\'nu bırakıp da yalvardıkları putlar bir şeye hüküm veremez. Şüphesiz Allah işitir ve görür.'),
  ('tr.diyanet', 40, 21, 'Yeryüzünde dolaşıp, kendilerinden önce ve kendilerinden daha kuvvetli olan ve yeryüzünde daha çok eser bırakan kimselerin sonuçlarının nasıl olduğunu görmezler mi? Allah onları suçlarıyla yakalamıştır. Allah\'a karşı onları koruyan yoktur.'),
  ('tr.diyanet', 40, 22, 'Bu, kendilerine açık belgelerle gelen peygamberlerini inkar etmelerinden ötürüdür. Allah da onları bunun için yakalamıştır. Doğrusu O, kuvvetlidir, cezalandırması da şiddetlidir.'),
  ('tr.diyanet', 40, 23, 'And olsun ki Musa\'yı, mucizelerimiz ve apaçık delillerle Firavun, Haman ve Karun\'a göndermişizdir. Onlar: "Bu, yalancı sihirbazın biridir" demişlerdi.'),
  ('tr.diyanet', 40, 24, 'And olsun ki Musa\'yı, mucizelerimiz ve apaçık delillerle Firavun, Haman ve Karun\'a göndermişizdir. Onlar: "Bu, yalancı sihirbazın biridir" demişlerdi.'),
  ('tr.diyanet', 40, 25, 'Musa katımızdan onlara gerçeği getirince: "Onunla beraber iman etmiş kimselerin oğullarını öldürün, kadınlarını sağ bırakın" dediler. Ama inkarcıların hilesi elbette boşa gider.'),
  ('tr.diyanet', 40, 26, 'Firavun: "Beni bırakın da Musa\'yı öldüreyim, o, Rabbine yalvaradursun. Onun, sizin dininizi değiştireceğinden veya yeryüzünde bozgun çıkaracağından korkuyorum" dedi.'),
  ('tr.diyanet', 40, 27, 'Musa: "Doğrusu ben, hesap görülecek güne inanmayan böbürlenenlerin hepsinden, benim de Rabbim sizin de Rabbiniz olan Allah\'a sığınırım" dedi.'),
  ('tr.diyanet', 40, 28, 'Firavun ailesinden olup da, inandığını gizleyen bir adam dedi ki: "Rabbim Allah\'tır diyen bir adamı mı öldüreceksiniz? Oysa size Rabbinizden belgelerle gelmiştir. Eğer yalancıysa, yalanı kendisinedir; eğer doğru sözlü ise, sizi tehdit ettiklerinin bir kısmı başınıza gelebilir. Doğrusu Allah, aşırı yalancıyı doğru yola eriştirmez."'),
  ('tr.diyanet', 40, 29, '"Ey milletim; Bugün memlekette hükümranlık sizindir, galip olanlar sizsiniz. Ama Allah\'ın baskını bize çatınca, O\'na karşı bize kim yardım eder?" Firavun: "Ben size kendi görüşümden başkasını söylemiyorum. Ben size ancak doğru yolu gösteriyorum" dedi.'),
  ('tr.diyanet', 40, 30, 'İnanmış olan adam dedi ki: "Ey milletim! Doğrusu ben sizin için, Nuh milletinin, Ad, Semud ve onlardan sonra gelenlerin durumu gibi, peygamberleri yalanlayan toplulukların uğradıkları bir günün benzerinden korkuyorum. Allah kullara zulüm dilemez."'),
  ('tr.diyanet', 40, 31, 'İnanmış olan adam dedi ki: "Ey milletim! Doğrusu ben sizin için, Nuh milletinin, Ad, Semud ve onlardan sonra gelenlerin durumu gibi, peygamberleri yalanlayan toplulukların uğradıkları bir günün benzerinden korkuyorum. Allah kullara zulüm dilemez."'),
  ('tr.diyanet', 40, 32, '"Ey milletim! Ahu figan gününden sizin hesabınıza korkuyorum."'),
  ('tr.diyanet', 40, 33, '"Arkanıza dönüp kaçacağınız gün Allah\'a karşı sizi koruyan bulunmaz. Allah\'ın saptırdığını doğru yola getirecek yoktur."'),
  ('tr.diyanet', 40, 34, '"And olsun ki, Yusuf da, daha önce, size belgelerle gelmişti. Size getirdiği şeylerden şüphelenip durmuştunuz. Sonunda Yusuf ölünce, Allah onun ardından hiçbir peygamber göndermeyecek demiştiniz. Allah, aşırı şüpheciyi işte böylece saptırır."'),
  ('tr.diyanet', 40, 35, '"Bunlar, Allah\'ın ayetleri üzerinde kendilerine gelmiş bir delil bulunmadan tartışırlar. Bu, Allah katında da, inananların yanında da öfkeyi arttırır. Allah, büyüklük taslayan her zorbanın kalbini bundan dolayı mühürler."'),
  ('tr.diyanet', 40, 36, 'Firavun: "Ey Haman! Bana bir kule yap; belki yollara, göklerin yollarına erişirim de Musa\'nın Tanrısını görürüm. Doğrusu ben, onu yalancı sanıyorum" dedi. Firavun\'a, kötü işi böylece güzel gösterildi ve doğru yoldan alıkondu. Firavun\'un hilesi elbette boşa gidecekti.'),
  ('tr.diyanet', 40, 37, 'Firavun: "Ey Haman! Bana bir kule yap; belki yollara, göklerin yollarına erişirim de Musa\'nın Tanrısını görürüm. Doğrusu ben, onu yalancı sanıyorum" dedi. Firavun\'a, kötü işi böylece güzel gösterildi ve doğru yoldan alıkondu. Firavun\'un hilesi elbette boşa gidecekti.'),
  ('tr.diyanet', 40, 38, 'O inanan kimse dedi ki: "Ey milletim! Bana uyun, sizi doğru yola eriştireyim."'),
  ('tr.diyanet', 40, 39, '"Ey milletim! Şüphesiz bu dünya hayatı geçicidir, ama ahiret, doğrusu işte o, kalınacak yurttur."'),
  ('tr.diyanet', 40, 40, '"Kim bir kötülük işlerse ancak onun kadar ceza görür. Kadın veya erkek, kim, inanarak yararlı iş işlerse, işte onlar cennete girerler; orada hesapsız şekilde rızıklanırlar."'),
  ('tr.diyanet', 40, 41, '"Ey milletim! Nedir başıma gelen? Ben sizi kurtuluşa çağırıyorum, siz beni ateşe çağırıyorsunuz."'),
  ('tr.diyanet', 40, 42, '"Siz beni Allah\'ı inkar etmeye, bilmediğim bir şeyi O\'na ortak koşmaya çağırıyorsunuz; ben ise sizi, güçlü olan, çok bağışlayan Allah\'a çağırıyorum."'),
  ('tr.diyanet', 40, 43, '"Beni kendisine çağırdığınızın, bu dünyada da ahirette de çağırabilecek kabiliyette olmadığında, hepimizin Allah\'a döneceğinde, aşırı gidenlerin ateşlikler olduklarında şüphe yoktur."'),
  ('tr.diyanet', 40, 44, '"Size söylediğimi hatırlayacaksınız. Ben işimi Allah\'a bırakıyorum. Doğrusu Allah, kulları görür."'),
  ('tr.diyanet', 40, 45, 'Allah o adamı, kurmak istedikleri tuzaktan korudu. Kötü azap Firavun\'un adamlarını sardı.'),
  ('tr.diyanet', 40, 46, 'Onlar, sabah akşam ateşe sunulurlar. Kıyamet çattığı gün, "Firavun\'un adamlarını azabın en ağırına sokun"denir.'),
  ('tr.diyanet', 40, 47, 'Ateşin içinde birbirleriyle tartışırlarken, güçsüzler, büyüklük taslayanlara: "Doğrusu biz size uymuştuk, şimdi ateşin bir parçasını olsun bizden savabilir misiniz?" derler.'),
  ('tr.diyanet', 40, 48, 'Büyüklük taslayanlar: "Doğrusu hepimiz onun içindeyiz. Allah kullar arasında şüphesiz hüküm vermiştir" derler.'),
  ('tr.diyanet', 40, 49, 'Ateşte olanlar, cehennemin bekçilerine: "Rabbinize yalvarın da hiç değilse bir gün, azabımızı hafifletsin" derler.'),
  ('tr.diyanet', 40, 50, 'Bekçiler: "Size, belgelerle peygamberleriniz gelmiş miydi?" derler. Onlar da: "Evet, gelmişti" derler. Bekçiler: "O halde kendiniz yalvarın" derler. İnkarcıların yalvarışı şüphesiz boşunadır.'),
  ('tr.diyanet', 40, 51, 'Doğrusu Biz, peygamberlerimize ve inananlara dünya hayatında ve şahidlerin şahidlik edecekleri günde yardım ederiz.'),
  ('tr.diyanet', 40, 52, 'O gün zalimlere, özür beyan etmeleri fayda vermez. Lanet onlaradır. Yurdun kötüsü de onlaradır.'),
  ('tr.diyanet', 40, 53, 'And olsun ki Biz Musa\'ya doğruluk rehberi verdik. İsrailoğullarını da, akıl sahipleri için bir öğüt ve doğruluk rehberi olan Kitap\'a, Tevrat\'a varis kıldık.'),
  ('tr.diyanet', 40, 54, 'And olsun ki Biz Musa\'ya doğruluk rehberi verdik. İsrailoğullarını da, akıl sahipleri için bir öğüt ve doğruluk rehberi olan Kitap\'a, Tevrat\'a varis kıldık.'),
  ('tr.diyanet', 40, 55, 'Sabret, Allah\'ın verdiği söz şüphesiz gerçektir. Suçunun bağışlanmasını dile; Rabbini akşam, sabah, överek tesbih et.'),
  ('tr.diyanet', 40, 56, 'Allah\'ın ayetleri üzerinde kendilerine gelen bir delil olmadan tartışanların gönüllerinde, ulaşamayacakları bir büyüklenme vardır. Sen Allah\'a sığın. O şüphesiz işitendir, görendir.'),
  ('tr.diyanet', 40, 57, 'Göklerin ve yerin yaratılması, insanların yaratılmasından daha büyük bir şeydir. Fakat insanların çoğu bilmezler.'),
  ('tr.diyanet', 40, 58, 'Körle gören, inanıp yararlı iş işleyenlerle kötülük yapan bir değildir. Ne kadar az düşünüyorsunuz?'),
  ('tr.diyanet', 40, 59, 'Kıyamet günü mutlaka gelecektir. Bunda şüphe yoktur, fakat, insanların çoğu inanmıyor.'),
  ('tr.diyanet', 40, 60, 'Rabbiniz: "Bana dua edin ki duanıza icabet edeyim. Bana kulluk etmeyi büyüklüklerine yediremeyenler alçalmış olarak cehenneme gireceklerdir" buyurmuştur.'),
  ('tr.diyanet', 40, 61, 'Size, geceyi dinlenesiniz diye karanlık ve gündüzü aydınlık olarak yaratan Allah\'tır. Doğrusu Allah insanlara karşı lütufkardır, ama insanların çoğu şükretmezler.'),
  ('tr.diyanet', 40, 62, 'İşte herşeyin yaratıcısı olan Rabbiniz Allah budur. O\'ndan başka tanrı yoktur. Nasıl aldatılıp döndürülürsünüz?'),
  ('tr.diyanet', 40, 63, 'Allah\'ın ayetlerini bile bile inkar edenler böylece döndürülüyorlardı.'),
  ('tr.diyanet', 40, 64, 'Sizin için yeri durak, göğü bina eden, size şekil verip de, şeklinizi güzel yapan, sizi temiz şeylerle rızıklandıran Allah\'tır. İşte Rabbiniz olan Allah budur. Alemlerin Rabbi Allah ne yücedir!'),
  ('tr.diyanet', 40, 65, 'O diridir, O\'ndan başka tanrı yoktur. Dini yalnız O\'na has kılarak O\'na yalvarın. Övgü, Alemlerin Rabbi Allah içindir.'),
  ('tr.diyanet', 40, 66, 'De ki: "Sizin, Allah\'ı bırakıp da kulluk ettiklerinize kulluk etmek bana yasak kılınmıştır. Zira bana Rabbimden belgeler gelmiştir. Ben, kendimi Alemlerin Rabbine vermekle emrolundum."'),
  ('tr.diyanet', 40, 67, 'Sizi topraktan, sonra nutfeden, sonra kan pıhtısından yaratan; sonra erginlik çağına ulaşmanız, sonra da yaşlanmanız için sizi bebek olarak dünyaya çıkaran O\'dur. Kiminiz daha önce öldürülür, kiminiz de, belirtilmiş bir süreye ulaşırsınız. Belki artık düşünürsünüz.'),
  ('tr.diyanet', 40, 68, 'Dirilten, öldüren O\'dur. Bir şeye karar verirse "Ol" der, o da oluverir.'),
  ('tr.diyanet', 40, 69, 'Allah\'ın ayetleri üzerinde tartışanları görmez misin? Nasıl da döndürülüyorlar?'),
  ('tr.diyanet', 40, 70, 'Kitap\'ı ve peygamberlerimize gönderdiklerimizi yalanlayanlar elbette bileceklerdir.'),
  ('tr.diyanet', 40, 71, 'Boyunlarında halkalar ve zincirler olarak kaynar suya sürülür, sonra ateşte yakılırlar.'),
  ('tr.diyanet', 40, 72, 'Boyunlarında halkalar ve zincirler olarak kaynar suya sürülür, sonra ateşte yakılırlar.'),
  ('tr.diyanet', 40, 73, 'Sonra onlara: "Allah\'ı bırakıp da koştuğunuz ortaklar nerededir?" denir. "Bizden uzaklaştılar; hayır, biz zaten önceleri hiçbir şeye kulluk etmiyorduk" derler. İşte Allah inkarcıları böyle saptırır.'),
  ('tr.diyanet', 40, 74, 'Sonra onlara: "Allah\'ı bırakıp da koştuğunuz ortaklar nerededir?" denir. "Bizden uzaklaştılar; hayır, biz zaten önceleri hiçbir şeye kulluk etmiyorduk" derler. İşte Allah inkarcıları böyle saptırır.'),
  ('tr.diyanet', 40, 75, 'Onlara: "İşte bu, yeryüzünde haksız yere şımarmanız ve böbürlenmenizden ötürüdür. Temelli kalacağınız cehennem kapılarından girin" denir. Büyüklenenlerin durağı ne kötüdür!'),
  ('tr.diyanet', 40, 76, 'Onlara: "İşte bu, yeryüzünde haksız yere şımarmanız ve böbürlenmenizden ötürüdür. Temelli kalacağınız cehennem kapılarından girin" denir. Büyüklenenlerin durağı ne kötüdür!'),
  ('tr.diyanet', 40, 77, 'Sabret; şüphesiz Allah\'ın verdiği söz gerçektir. Onlara söz verdiğimiz azabın bir kısmını sana gösteririz veya seni öldürürüz, nasıl olsa onların dönüşü Bizedir.'),
  ('tr.diyanet', 40, 78, 'And olsun ki, senden önce birçok peygamberler gönderdik; sana onların kimini anlattık, kimini anlatmadık; hiçbir peygamber, Allah\'ın izni olmadan bir mucize getiremez. Allah\'ın buyruğu gelince iş gerçekten biter. İşte o zaman, boşa uğraşanlar hüsranda kalırlar.'),
  ('tr.diyanet', 40, 79, 'Binek olarak kullanmanız ve yemeniz için hayvanları sizin için yaratan Allah\'tır.'),
  ('tr.diyanet', 40, 80, 'Onlarda sizin için daha nice faydalar vardır; gönüllerinizdeki arzulara, onlara binerek ulaşırsınız. Onlarla ve gemilerle taşınırsınız.'),
  ('tr.diyanet', 40, 81, 'Allah size delillerini gösteriyor. Allah\'ın delillerinden hangisini inkar edersiniz?'),
  ('tr.diyanet', 40, 82, 'Yeryüzünde dolaşıp, kendilerinden daha çok, daha kuvvetli, yeryüzünde bıraktıkları eserler daha sağlam olan öncekilerin sonuçlarının nasıl olduğunu görmezler mi? Kazandıkları onlara bir fayda vermemiştir.'),
  ('tr.diyanet', 40, 83, 'Peygamberleri onlara belgelerle gelince, kendilerinde olan bilgiden gururlandılar da, alaya aldıkları şey kendilerini sarıverdi.'),
  ('tr.diyanet', 40, 84, 'Şiddetli azabımızı gördüklerinde: "Yalnız Allah\'a inandık; O\'na koştuğumuz eşleri inkar ettik" dediler.'),
  ('tr.diyanet', 40, 85, 'Ama, Bizim şiddetli azabımızı görüp de öyle inanmaları kendilerine fayda vermedi. Bu, Allah\'ın kulları hakkında, öteden beri yürürlükte olan yasasıdır. İşte inkarcılar o zaman hüsranda kaldılar.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 40, 1, 'Haa Miim.'),
  ('id.indonesian', 40, 2, 'Diturunkan Kitab ini (Al Quran) dari Allah Yang Maha Perkasa lagi Maha Mengetahui,'),
  ('id.indonesian', 40, 3, 'Yang Mengampuni dosa dan Menerima taubat lagi keras hukuman-Nya. Yang mempunyai karunia. Tiada Tuhan (yang berhak disembah) selain Dia. Hanya kepada-Nya-lah kembali (semua makhluk).'),
  ('id.indonesian', 40, 4, 'Tidak ada yang memperdebatkan tentang ayat-ayat Allah, kecuali orang-orang yang kafir. Karena itu janganlah pulang balik mereka dengan bebas dari suatu kota ke kota yang lain memperdayakan kamu.'),
  ('id.indonesian', 40, 5, 'Sebelum mereka, kaum Nuh dan golongan-golongan yang bersekutu sesudah mereka telah mendustakan (rasul) dan tiap-tiap umat telah merencanakan makar terhadap rasul mereka untuk menawannya dan mereka membantah dengan (alasan) yang batil untuk melenyapkan kebenaran dengan yang batil itu; karena itu Aku azab mereka. Maka betapa (pedihnya) azab-Ku?'),
  ('id.indonesian', 40, 6, 'Dan demikianlah telah pasti berlaku ketetapan azab Tuhanmu terhadap orang-orang kafir, karena sesungguhnya mereka adalah penghuni neraka.'),
  ('id.indonesian', 40, 7, '(Malaikat-malaikat) yang memikul \'Arsy dan malaikat yang berada di sekelilingnya bertasbih memuji Tuhannya dan mereka beriman kepada-Nya serta memintakan ampun bagi orang-orang yang beriman (seraya mengucapkan): "Ya Tuhan kami, rahmat dan ilmu Engkau meliputi segala sesuatu, maka berilah ampunan kepada orang-orang yang bertaubat dan mengikuti jalan Engkau dan peliharalah mereka dari siksaan neraka yang menyala-nyala,'),
  ('id.indonesian', 40, 8, 'ya Tuhan kami, dan masukkanlah mereka ke dalam surga \'Adn yang telah Engkau janjikan kepada mereka dan orang-orang yang saleh di antara bapak-bapak mereka, dan isteri-isteri mereka, dan keturunan mereka semua. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana,'),
  ('id.indonesian', 40, 9, 'dan peliharalah mereka dari (balasan) kejahatan. Dan orang-orang yang Engkau pelihara dari (pembalasan) kejahatan pada hari itu maka sesungguhnya telah Engkau anugerahkan rahmat kepadanya dan itulah kemenangan yang besar".'),
  ('id.indonesian', 40, 10, 'Sesungguhnya orang-orang yang kafir diserukan kepada mereka (pada hari kiamat): "Sesungguhnya kebencian Allah (kepadamu) lebih besar daripada kebencianmu kepada dirimu sendiri karena kamu diseru untuk beriman lalu kamu kafir".'),
  ('id.indonesian', 40, 11, 'Mereka menjawab: "Ya Tuhan kami Engkau telah mematikan kami dua kali dan telah menghidupkan kami dua kali (pula), lalu kami mengakui dosa-dosa kami. Maka adakah sesuatu jalan (bagi kami) untuk keluar (dari neraka)?"'),
  ('id.indonesian', 40, 12, 'Yang demikian itu adalah karena kamu kafir apabila Allah saja disembah. Dan kamu percaya apabila Allah dipersekutukan. Maka putusan (sekarang ini) adalah pada Allah Yang Maha Tinggi lagi Maha Besar.'),
  ('id.indonesian', 40, 13, 'Dialah yang memperlihatkan kepadamu tanda-tanda (kekuasaan)-Nya dan menurunkan untukmu rezeki dari langit. Dan tiadalah mendapat pelajaran kecuali orang-orang yang kembali (kepada Allah).'),
  ('id.indonesian', 40, 14, 'Maka sembahlah Allah dengan memurnikan ibadat kepada-Nya, meskipun orang-orang kafir tidak menyukai(nya).'),
  ('id.indonesian', 40, 15, '(Dialah) Yang Maha Tinggi derajat-Nya, Yang mempunyai \'Arsy, Yang mengutus Jibril dengan (membawa) perintah-Nya kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya, supaya dia memperingatkan (manusia) tentang hari pertemuan (hari kiamat).'),
  ('id.indonesian', 40, 16, '(Yaitu) hari (ketika) mereka keluar (dari kubur); tiada suatupun dari keadaan mereka yang tersembunyi bagi Allah. (Lalu Allah berfirman): "Kepunyaan siapakah kerajaan pada hari ini?" Kepunyaan Allah Yang Maha Esa lagi Maha Mengalahkan.'),
  ('id.indonesian', 40, 17, 'Pada hari ini tiap-tiap jiwa diberi balasan dengan apa yang diusahakannya. Tidak ada yang dirugikan pada hari ini. Sesungguhnya Allah amat cepat hisabnya.'),
  ('id.indonesian', 40, 18, 'Berilah mereka peringatan dengan hari yang dekat (hari kiamat yaitu) ketika hati (menyesak) sampai di kerongkongan dengan menahan kesedihan. Orang-orang yang zalim tidak mempunyai teman setia seorangpun dan tidak (pula) mempunyai seorang pemberi syafa\'at yang diterima syafa\'atnya.'),
  ('id.indonesian', 40, 19, 'Dia mengetahui (pandangan) mata yang khianat dan apa yang disembunyikan oleh hati.'),
  ('id.indonesian', 40, 20, 'Dan Allah menghukum dengan keadilan. Dan sembahan-sembahan yang mereka sembah selain Allah tiada dapat menghukum dengan sesuatu apapun. Sesungguhnya Allah Dialah Yang Maha Mendengar lagi Maha Melihat.'),
  ('id.indonesian', 40, 21, 'Dan apakah mereka tidak mengadakan perjalanan di muka bumi, lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Mereka itu adalah lebih hebat kekuatannya daripada mereka dan (lebih banyak) bekas-bekas mereka di muka bumi, maka Allah mengazab mereka disebabkan dosa-dosa mereka. Dan mereka tidak mempunyai seorang pelindung dari azab Allah.'),
  ('id.indonesian', 40, 22, 'Yang demiklan itu adalah karena telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti yang nyata lalu mereka kafir; maka Allah mengazab mereka. Sesungguhnya Dia Maha Kuat lagi Maha Keras hukuman-Nya.'),
  ('id.indonesian', 40, 23, 'Dan sesungguhnya telah Kami utus Musa dengan membawa ayat-ayat Kami dan keterangan yang nyata,'),
  ('id.indonesian', 40, 24, 'kepada Fir\'aun, Haman dan Qarun; maka mereka berkata: "(Ia) adalah seorang ahli sihir yang pendusta".'),
  ('id.indonesian', 40, 25, 'Maka tatkala Musa datang kepada mereka membawa kebenaran dari sisi Kami mereka berkata: "Bunuhlah anak-anak orang-orang yang beriman bersama dengan dia dan biarkanlah hidup wanita-wanita mereka". Dan tipu daya orang-orang kafir itu tak lain hanyalah sia-sia (belaka).'),
  ('id.indonesian', 40, 26, 'Dan berkata Fir\'aun (kepada pembesar-pembesarnya): "Biarkanlah aku membunuh Musa dan hendaklah ia memohon kepada Tuhannya, karena sesungguhnya aku khawatir dia akan menukar agamamu atau menimbulkan kerusakan di muka bumi".'),
  ('id.indonesian', 40, 27, 'Dan Musa berkata: "Sesungguhnya aku berlindung kepada Tuhanku dan Tuhanmu dari setiap orang yang menyombongkan diri yang tidak beriman kepada hari berhisab".'),
  ('id.indonesian', 40, 28, 'Dan seorang laki-laki yang beriman di antara pengikut-pengikut Fir\'aun yang menyembunyikan imannya berkata: "Apakah kamu akan membunuh seorang laki-laki karena dia menyatakan: "Tuhanku ialah Allah padahal dia telah datang kepadamu dengan membawa keterangan-keterangan dari Tuhanmu. Dan jika ia seorang pendusta maka dialah yang menanggung (dosa) dustanya itu; dan jika ia seorang yang benar niscaya sebagian (bencana) yang diancamkannya kepadamu akan menimpamu". Sesungguhnya Allah tidak menunjuki orang-orang yang melampaui batas lagi pendusta.'),
  ('id.indonesian', 40, 29, '(Musa berkata): "Hai kaumku, untukmulah kerajaan pada hari ini dengan berkuasa di muka bumi. Siapakah yang akan menolong kita dari azab Allah jika azab itu menimpa kita!" Fir\'aun berkata: "Aku tidak mengemukakan kepadamu, melainkan apa yang aku pandang baik; dan aku tiada menunjukkan kepadamu selain jalan yang benar".'),
  ('id.indonesian', 40, 30, 'Dan orang yang beriman itu berkata: "Hai kaumku, sesungguhnya aku khawatir kamu akan ditimpa (bencana) seperti peristiwa kehancuran golongan yang bersekutu.'),
  ('id.indonesian', 40, 31, '(Yakni) seperti keadaan kaum Nuh, \'Aad, Tsamud dan orang-orang yang datang sesudah mereka. Dan Allah tidak menghendaki berbuat kezaliman terhadap hamba-hamba-Nya.'),
  ('id.indonesian', 40, 32, 'Hai kaumku, sesungguhnya aku khawatir terhadapmu akan siksaan hari panggil-memanggil.'),
  ('id.indonesian', 40, 33, '(yaitu) hari (ketika) kamu (lari) berpaling ke belakang, tidak ada bagimu seorangpun yang menyelamatkan kamu dari (azab) Allah, dan siapa yang disesatkan Allah, niscaya tidak ada baginya seorangpun yang akan memberi petunjuk.'),
  ('id.indonesian', 40, 34, 'Dan sesungguhnya telah datang Yusuf kepadamu dengan membawa keterangan-keterangan, tetapi kamu senantiasa dalam keraguan tentang apa yang dibawanya kepadamu, hingga ketika dia meninggal, kamu berkata: "Allah tidak akan mengirim seorang (rasulpun) sesudahnya. Demikianlah Allah menyesatkan orang-orang yang melampaui batas dan ragu-ragu.'),
  ('id.indonesian', 40, 35, '(Yaitu) orang-orang yang memperdebatkan ayat-ayat Allah tanpa alasan yang sampai kepada mereka. Amat besar kemurkaan (bagi mereka) di sisi Allah dan di sisi orang-orang yang beriman. Demikianlah Allah mengunci mati hati orang yang sombong dan sewenang-wenang.'),
  ('id.indonesian', 40, 36, 'Dan berkatalah Fir\'aun: "Hai Haman, buatkanlah bagiku sebuah bangunan yang tinggi supaya aku sampai ke pintu-pintu,'),
  ('id.indonesian', 40, 37, '(yaitu) pintu-pintu langit, supaya aku dapat melihat Tuhan Musa dan sesungguhnya aku memandangnya seorang pendusta". Demikianlah dijadikan Fir\'aun memandang baik perbuatan yang buruk itu, dan dia dihalangi dari jalan (yang benar); dan tipu daya Fir\'aun itu tidak lain hanyalah membawa kerugian.'),
  ('id.indonesian', 40, 38, 'Orang yang beriman itu berkata: "Hai kaumku, ikutilah aku, aku akan menunjukkan kepadamu jalan yang benar.'),
  ('id.indonesian', 40, 39, 'Hai kaumku, sesungguhnya kehidupan dunia ini hanyalah kesenangan (sementara) dan sesungguhnya akhirat itulah negeri yang kekal.'),
  ('id.indonesian', 40, 40, 'Barangsiapa mengerjakan perbuatan jahat, maka dia tidak akan dibalasi melainkan sebanding dengan kejahatan itu. Dan barangsiapa mengerjakan amal yang saleh baik laki-laki maupun perempuan sedang ia dalam keadaan beriman, maka mereka akan masuk surga, mereka diberi rezeki di dalamnya tanpa hisab.'),
  ('id.indonesian', 40, 41, 'Hai kaumku, bagaimanakah kamu, aku menyeru kamu kepada keselamatan, tetapi kamu menyeru aku ke neraka?'),
  ('id.indonesian', 40, 42, '(Kenapa) kamu menyeruku supaya kafir kepada Allah dan mempersekutukan-Nya dengan apa yang tidak kuketahui padahal aku menyeru kamu (beriman) kepada Yang Maha Perkasa lagi Maha Pengampun?'),
  ('id.indonesian', 40, 43, 'Sudah pasti bahwa apa yang kamu seru supaya aku (beriman) kepadanya tidak dapat memperkenankan seruan apapun baik di dunia maupun di akhirat. Dan sesungguhnya kita kembali kepada Allah dan sesungguhnya orang-orang yang melampaui batas, mereka itulah penghuni neraka.'),
  ('id.indonesian', 40, 44, 'Kelak kamu akan ingat kepada apa yang kukatakan kepada kamu. Dan aku menyerahkan urusanku kepada Allah. Sesungguhnya Allah Maha Melihat akan hamba-hamba-Nya".'),
  ('id.indonesian', 40, 45, 'Maka Allah memeliharanya dari kejahatan tipu daya mereka, dan Fir\'aun beserta kaumnya dikepung oleh azab yang amat buruk.'),
  ('id.indonesian', 40, 46, 'Kepada mereka dinampakkan neraka pada pagi dan petang, dan pada hari terjadinya Kiamat. (Dikatakan kepada malaikat): "Masukkanlah Fir\'aun dan kaumnya ke dalam azab yang sangat keras".'),
  ('id.indonesian', 40, 47, 'Dan (ingatlah), ketika mereka berbantah-bantah dalam neraka, maka orang-orang yang lemah berkata kepada orang-orang yang menyombongkan diri: "Sesungguhnya kami adalah pengikut-pengikutmu, maka dapatkah kamu menghindarkan dari kami sebahagian azab api neraka?"'),
  ('id.indonesian', 40, 48, 'Orang-orang yang menyombongkan diri menjawab: "Sesungguhnya kita semua sama-sama dalam neraka karena sesungguhnya Allah telah menetapkan keputusan antara hamba-hamba-(Nya)".'),
  ('id.indonesian', 40, 49, 'Dan orang-orang yang berada dalam neraka berkata kepada penjaga-penjaga neraka Jahannam: "Mohonkanlah kepada Tuhanmu supaya Dia meringankan azab dari kami barang sehari".'),
  ('id.indonesian', 40, 50, 'Penjaga Jahannam berkata: "Dan apakah belum datang kepada kamu rasul-rasulmu dengan membawa keterangan-keterangan?" Mereka menjawab: "Benar, sudah datang". Penjaga-penjaga Jahannam berkata: "Berdoalah kamu". Dan doa orang-orang kafir itu hanyalah sia-sia belaka.'),
  ('id.indonesian', 40, 51, 'Sesungguhnya Kami menolong rasul-rasul Kami dan orang-orang yang beriman dalam kehidupan dunia dan pada hari berdirinya saksi-saksi (hari kiamat),'),
  ('id.indonesian', 40, 52, '(yaitu) hari yang tidak berguna bagi orang-orang zalim permintaan maafnya dan bagi merekalah laknat dan bagi merekalah tempat tinggal yang buruk.'),
  ('id.indonesian', 40, 53, 'Dan sesungguhnya telah Kami berikan petunjuk kepada Musa; dan Kami wariskan Taurat kepada Bani Israil,'),
  ('id.indonesian', 40, 54, 'untuk menjadi petunjuk dan peringatan bagi orang-orang yang berfikir.'),
  ('id.indonesian', 40, 55, 'Maka bersabarlah kamu, karena sesungguhnya janji Allah itu benar, dan mohonlah ampunan untuk dosamu dan bertasbihlah seraya memuji Tuhanmu pada waktu petang dan pagi.'),
  ('id.indonesian', 40, 56, 'Sesungguhhnya orang-orang yang memperdebatkan tentang ayat-ayat Allah tanpa alasan yang sampai kepada mereka tidak ada dalam dada mereka melainkan hanyalah (keinginan akan) kebesaran yang mereka sekali-kali tiada akan mencapainya, maka mintalah perlindungan kepada Allah. Sesungguhnya Dia Maha Mendengar lagi Maha Melihat.'),
  ('id.indonesian', 40, 57, 'Sesungguhnya penciptaan langit dan bumi lebih besar daripada penciptaan manusia akan tetapi kebanyakan manusia tidak mengetahui.'),
  ('id.indonesian', 40, 58, 'Dan tidaklah sama orang yang buta dengan orang yang melihat, dan tidaklah (pula sama) orang-orang yang beriman serta mengerjakan amal saleh dengan orang-orang yang durhaka. Sedikit sekali kamu mengambil pelajaran.'),
  ('id.indonesian', 40, 59, 'Sesungguhnya hari kiamat pasti akan datang, tidak ada keraguan tentangnya, akan tetapi kebanyakan manusia tiada beriman.'),
  ('id.indonesian', 40, 60, 'Dan Tuhanmu berfirman: "Berdoalah kepada-Ku, niscaya akan Kuperkenankan bagimu. Sesungguhnya orang-orang yang menyombongkan diri dari menyembah-Ku akan masuk neraka Jahannam dalam keadaan hina dina".'),
  ('id.indonesian', 40, 61, 'Allah-lah yang menjadikan malam untuk kamu supaya kamu beristirahat padanya; dan menjadikan siang terang benderang. Sesungguhnya Allah benar-benar mempunyal karunia yang dilimpahkan atas manusia, akan tetapi kebanyakan manusia tidak bersyukur.'),
  ('id.indonesian', 40, 62, 'Yang demikian itu adalah Allah, Tuhanmu, Pencipta segala sesuatu, tiada Tuhan (yang berhak disembah) melainkan Dia; maka bagaimanakah kamu dapat dipalingkan?'),
  ('id.indonesian', 40, 63, 'Seperti demikianlah dipalingkan orang-orang yang selalu mengingkari ayat-ayat Allah.'),
  ('id.indonesian', 40, 64, 'Allah-lah yang menjadikan bumi bagi kamu tempat menetap dan langit sebagai atap, dan membentuk kamu lalu membaguskan rupamu serta memberi kamu rezeki dengan sebahagian yang baik-baik. Yang demikian itu adalah Allah Tuhanmu, Maha Agung Allah, Tuhan semesta alam.'),
  ('id.indonesian', 40, 65, 'Dialah Yang hidup kekal, tiada Tuhan (yang berhak disembah) melainkan Dia; maka sembahlah Dia dengan memurnikan ibadat kepada-Nya. Segala puji bagi Allah Tuhan semesta alam.'),
  ('id.indonesian', 40, 66, 'Katakanlah (ya Muhammad): "Sesungguhnya aku dilarang menyembah sembahan yang kamu sembah selain Allah setelah datang kepadaku keterangan-keterangan dari Tuhanku; dan aku diperintahkan supaya tunduk patuh kepada Tuhan semesta alam.'),
  ('id.indonesian', 40, 67, 'Dialah yang menciptakan kamu dari tanah kemudian dari setetes mani, sesudah itu dari segumpal darah, kemudian dilahirkannya kamu sebagai seorang anak, kemudian (kamu dibiarkan hidup) supaya kamu sampai kepada masa (dewasa), kemudian (dibiarkan kamu hidup lagi) sampai tua, di antara kamu ada yang diwafatkan sebelum itu. (Kami perbuat demikian) supaya kamu sampai kepada ajal yang ditentukan dan supaya kamu memahami(nya).'),
  ('id.indonesian', 40, 68, 'Dialah yang menghidupkan dan mematikan, maka apabila Dia menetapkan sesuatu urusan, Dia hanya bekata kepadanya: "Jadilah", maka jadilah ia.'),
  ('id.indonesian', 40, 69, 'Apakah kamu tidak melihat kepada orang-orang yang membantah ayat-ayat Allah? Bagaimanakah mereka dapat dipalingkan?'),
  ('id.indonesian', 40, 70, '(Yaitu) orang-orang yang mendustakan Al Kitab (Al Quran) dan wahyu yang dibawa oleh rasul-rasul Kami yang telah Kami utus. Kelak mereka akan mengetahui,'),
  ('id.indonesian', 40, 71, 'ketika belenggu dan rantai dipasang di leher mereka, seraya mereka diseret,'),
  ('id.indonesian', 40, 72, 'ke dalam air yang sangat panas, kemudian mereka dibakar dalam api,'),
  ('id.indonesian', 40, 73, 'kemudian dikatakan kepada mereka: "Manakah berhala-berhala yang selalu kamu persekutukan,'),
  ('id.indonesian', 40, 74, '(yang kamu sembah) selain Allah?" Mereka menjawab: "Mereka telah hilang lenyap dari kami, bahkan kami dahulu tiada pernah menyembah sesuatu". Seperti demikianlah Allah menyesatkan orang-orang kafir.'),
  ('id.indonesian', 40, 75, 'Yang demikian itu disebabkan karena kamu bersuka ria di muka bumi dengan tidak benar dan karena kamu selalu bersuka ria (dalam kemaksiatan).'),
  ('id.indonesian', 40, 76, '(Dikatakan kepada mereka): "Masuklah kamu ke pintu-pintu neraka Jahannam, sedang kamu kekal di dalamnya. Maka itulah seburuk-buruk tempat bagi orang-orang yang sombong".'),
  ('id.indonesian', 40, 77, 'Maka bersabarlah kamu, sesungguhnya janji Allah adalah benar; maka meskipun Kami perlihatkan kepadamu sebagian siksa yang Kami ancamkan kepada mereka ataupun Kami wafatkan kamu (sebelum ajal menimpa mereka), namun kepada Kami sajalah mereka dikembalikan.'),
  ('id.indonesian', 40, 78, 'Dan sesungguhnya telah Kami utus beberapa orang rasul sebelum kamu, di antara mereka ada yang Kami ceritakan kepadamu dan di antara mereka ada (pula) yang tidak Kami ceritakan kepadamu. Tidak dapat bagi seorang rasul membawa suatu mukjizat, melainkan dengan seizin Allah; maka apabila telah datang perintah Allah, diputuskan (semua perkara) dengan adil. Dan ketika itu rugilah orang-orang yang berpegang kepada yang batil.'),
  ('id.indonesian', 40, 79, 'Allahlah yang menjadikan binatang ternak untuk kamu, sebagiannya untuk kamu kendarai dan sebagiannya untuk kamu makan.'),
  ('id.indonesian', 40, 80, 'Dan (ada lagi) manfaat-manfaat yang lain pada binatang ternak itu untuk kamu dan supaya kamu mencapai suatu keperluan yang tersimpan dalam hati dengan mengendarainya. Dan kamu dapat diangkut dengan mengendarai binatang-binatang itu dan dengan mengendarai bahtera.'),
  ('id.indonesian', 40, 81, 'Dan Dia memperlihatkan kepada kamu tanda-tanda (kekuasaan-Nya); maka tanda-tanda (kekuasaan) Allah yang manakah yang kamu ingkari?'),
  ('id.indonesian', 40, 82, 'Maka apakah mereka tiada mengadakan perjalanan di muka bumi lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Adalah orang-orang yang sebelum mereka itu lebih hebat kekuatannya dan (lebih banyak) bekas-bekas mereka di muka bumi, maka apa yang mereka usahakan itu tidak dapat menolong mereka.'),
  ('id.indonesian', 40, 83, 'Maka tatkala datang kepada mereka rasul-rasul (yang diutus kepada) mereka dengan membawa ketarangan-keterangan, mereka merasa senang dengan pengetahuan yang ada pada mereka dan mereka dikepung oleh azab Allah yang selalu mereka perolok-olokkan itu.'),
  ('id.indonesian', 40, 84, 'Maka tatkala mereka melihat azab Kami, mereka berkata: "Kami beriman hanya kepada Allah saja, dan kami kafir kepada sembahan-sembahan yang telah kami persekutukan dengan Allah".'),
  ('id.indonesian', 40, 85, 'Maka iman mereka tiada berguna bagi mereka tatkala mereka telah melihat siksa Kami. Itulah sunnah Allah yang telah berlaku terhadap hamba-hamba-Nya. Dan di waktu itu binasalah orang-orang kafir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 41, 1, 'Ha, Meem.'),
  ('en.sahih', 41, 2, '[This is] a revelation from the Entirely Merciful, the Especially Merciful -'),
  ('en.sahih', 41, 3, 'A Book whose verses have been detailed, an Arabic Qur\'an for a people who know,'),
  ('en.sahih', 41, 4, 'As a giver of good tidings and a warner; but most of them turn away, so they do not hear.'),
  ('en.sahih', 41, 5, 'And they say, "Our hearts are within coverings from that to which you invite us, and in our ears is deafness, and between us and you is a partition, so work; indeed, we are working."'),
  ('en.sahih', 41, 6, 'Say, O [Muhammad], "I am only a man like you to whom it has been revealed that your god is but one God; so take a straight course to Him and seek His forgiveness." And woe to those who associate others with Allah -'),
  ('en.sahih', 41, 7, 'Those who do not give zakah, and in the Hereafter they are disbelievers.'),
  ('en.sahih', 41, 8, 'Indeed, those who believe and do righteous deeds - for them is a reward uninterrupted.'),
  ('en.sahih', 41, 9, 'Say, "Do you indeed disbelieve in He who created the earth in two days and attribute to Him equals? That is the Lord of the worlds."'),
  ('en.sahih', 41, 10, 'And He placed on the earth firmly set mountains over its surface, and He blessed it and determined therein its [creatures\'] sustenance in four days without distinction - for [the information] of those who ask.'),
  ('en.sahih', 41, 11, 'Then He directed Himself to the heaven while it was smoke and said to it and to the earth, "Come [into being], willingly or by compulsion." They said, "We have come willingly."'),
  ('en.sahih', 41, 12, 'And He completed them as seven heavens within two days and inspired in each heaven its command. And We adorned the nearest heaven with lamps and as protection. That is the determination of the Exalted in Might, the Knowing.'),
  ('en.sahih', 41, 13, 'But if they turn away, then say, "I have warned you of a thunderbolt like the thunderbolt [that struck] \'Aad and Thamud.'),
  ('en.sahih', 41, 14, '[That occurred] when the messengers had come to them before them and after them, [saying], "Worship not except Allah." They said, "If our Lord had willed, He would have sent down the angels, so indeed we, in that with which you have been sent, are disbelievers."'),
  ('en.sahih', 41, 15, 'As for \'Aad, they were arrogant upon the earth without right and said, "Who is greater than us in strength?" Did they not consider that Allah who created them was greater than them in strength? But they were rejecting Our signs.'),
  ('en.sahih', 41, 16, 'So We sent upon them a screaming wind during days of misfortune to make them taste the punishment of disgrace in the worldly life; but the punishment of the Hereafter is more disgracing, and they will not be helped.'),
  ('en.sahih', 41, 17, 'And as for Thamud, We guided them, but they preferred blindness over guidance, so the thunderbolt of humiliating punishment seized them for what they used to earn.'),
  ('en.sahih', 41, 18, 'And We saved those who believed and used to fear Allah.'),
  ('en.sahih', 41, 19, 'And [mention, O Muhammad], the Day when the enemies of Allah will be gathered to the Fire while they are [driven] assembled in rows,'),
  ('en.sahih', 41, 20, 'Until, when they reach it, their hearing and their eyes and their skins will testify against them of what they used to do.'),
  ('en.sahih', 41, 21, 'And they will say to their skins, "Why have you testified against us?" They will say, "We were made to speak by Allah, who has made everything speak; and He created you the first time, and to Him you are returned.'),
  ('en.sahih', 41, 22, 'And you were not covering yourselves, lest your hearing testify against you or your sight or your skins, but you assumed that Allah does not know much of what you do.'),
  ('en.sahih', 41, 23, 'And that was your assumption which you assumed about your Lord. It has brought you to ruin, and you have become among the losers."'),
  ('en.sahih', 41, 24, 'So [even] if they are patient, the Fire is a residence for them; and if they ask to appease [Allah], they will not be of those who are allowed to appease.'),
  ('en.sahih', 41, 25, 'And We appointed for them companions who made attractive to them what was before them and what was behind them [of sin], and the word has come into effect upon them among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.'),
  ('en.sahih', 41, 26, 'And those who disbelieve say, "Do not listen to this Qur\'an and speak noisily during [the recitation of] it that perhaps you will overcome."'),
  ('en.sahih', 41, 27, 'But We will surely cause those who disbelieve to taste a severe punishment, and We will surely recompense them for the worst of what they had been doing.'),
  ('en.sahih', 41, 28, 'That is the recompense of the enemies of Allah - the Fire. For them therein is the home of eternity as recompense for what they, of Our verses, were rejecting.'),
  ('en.sahih', 41, 29, 'And those who disbelieved will [then] say, "Our Lord, show us those who misled us of the jinn and men [so] we may put them under our feet that they will be among the lowest."'),
  ('en.sahih', 41, 30, 'Indeed, those who have said, "Our Lord is Allah " and then remained on a right course - the angels will descend upon them, [saying], "Do not fear and do not grieve but receive good tidings of Paradise, which you were promised.'),
  ('en.sahih', 41, 31, 'We [angels] were your allies in worldly life and [are so] in the Hereafter. And you will have therein whatever your souls desire, and you will have therein whatever you request [or wish]'),
  ('en.sahih', 41, 32, 'As accommodation from a [Lord who is] Forgiving and Merciful."'),
  ('en.sahih', 41, 33, 'And who is better in speech than one who invites to Allah and does righteousness and says, "Indeed, I am of the Muslims."'),
  ('en.sahih', 41, 34, 'And not equal are the good deed and the bad. Repel [evil] by that [deed] which is better; and thereupon the one whom between you and him is enmity [will become] as though he was a devoted friend.'),
  ('en.sahih', 41, 35, 'But none is granted it except those who are patient, and none is granted it except one having a great portion [of good].'),
  ('en.sahih', 41, 36, 'And if there comes to you from Satan an evil suggestion, then seek refuge in Allah. Indeed, He is the Hearing, the Knowing.'),
  ('en.sahih', 41, 37, 'And of His signs are the night and day and the sun and moon. Do not prostrate to the sun or to the moon, but prostate to Allah, who created them, if it should be Him that you worship.'),
  ('en.sahih', 41, 38, 'But if they are arrogant - then those who are near your Lord exalt Him by night and by day, and they do not become weary.'),
  ('en.sahih', 41, 39, 'And of His signs is that you see the earth stilled, but when We send down upon it rain, it quivers and grows. Indeed, He who has given it life is the Giver of Life to the dead. Indeed, He is over all things competent.'),
  ('en.sahih', 41, 40, 'Indeed, those who inject deviation into Our verses are not concealed from Us. So, is he who is cast into the Fire better or he who comes secure on the Day of Resurrection? Do whatever you will; indeed, He is Seeing of what you do.'),
  ('en.sahih', 41, 41, 'Indeed, those who disbelieve in the message after it has come to them... And indeed, it is a mighty Book.'),
  ('en.sahih', 41, 42, 'Falsehood cannot approach it from before it or from behind it; [it is] a revelation from a [Lord who is] Wise and Praiseworthy.'),
  ('en.sahih', 41, 43, 'Nothing is said to you, [O Muhammad], except what was already said to the messengers before you. Indeed, your Lord is a possessor of forgiveness and a possessor of painful penalty.'),
  ('en.sahih', 41, 44, 'And if We had made it a non-Arabic Qur\'an, they would have said, "Why are its verses not explained in detail [in our language]? Is it a foreign [recitation] and an Arab [messenger]?" Say, "It is, for those who believe, a guidance and cure." And those who do not believe - in their ears is deafness, and it is upon them blindness. Those are being called from a distant place.'),
  ('en.sahih', 41, 45, 'And We had already given Moses the Scripture, but it came under disagreement. And if not for a word that preceded from your Lord, it would have been concluded between them. And indeed they are, concerning the Qur\'an, in disquieting doubt.'),
  ('en.sahih', 41, 46, 'Whoever does righteousness - it is for his [own] soul; and whoever does evil [does so] against it. And your Lord is not ever unjust to [His] servants.'),
  ('en.sahih', 41, 47, 'To him [alone] is attributed knowledge of the Hour. And fruits emerge not from their coverings nor does a female conceive or give birth except with His knowledge. And the Day He will call to them, "Where are My \'partners\'?" they will say, "We announce to You that there is [no longer] among us any witness [to that]."'),
  ('en.sahih', 41, 48, 'And lost from them will be those they were invoking before, and they will be certain that they have no place of escape.'),
  ('en.sahih', 41, 49, 'Man is not weary of supplication for good [things], but if evil touches him, he is hopeless and despairing.'),
  ('en.sahih', 41, 50, 'And if We let him taste mercy from Us after an adversity which has touched him, he will surely say, "This is [due] to me, and I do not think the Hour will occur; and [even] if I should be returned to my Lord, indeed, for me there will be with Him the best." But We will surely inform those who disbelieved about what they did, and We will surely make them taste a massive punishment.'),
  ('en.sahih', 41, 51, 'And when We bestow favor upon man, he turns away and distances himself; but when evil touches him, then he is full of extensive supplication.'),
  ('en.sahih', 41, 52, 'Say, "Have you considered: if the Qur\'an is from Allah and you disbelieved in it, who would be more astray than one who is in extreme dissension?"'),
  ('en.sahih', 41, 53, 'We will show them Our signs in the horizons and within themselves until it becomes clear to them that it is the truth. But is it not sufficient concerning your Lord that He is, over all things, a Witness?'),
  ('en.sahih', 41, 54, 'Unquestionably, they are in doubt about the meeting with their Lord. Unquestionably He is, of all things, encompassing.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 41, 1, 'হা-মীম।'),
  ('bn.bengali', 41, 2, 'এটা অবতীর্ণ পরম করুণাময়, দয়ালুর পক্ষ থেকে।'),
  ('bn.bengali', 41, 3, 'এটা কিতাব, এর আয়াতসমূহ বিশদভাবে বিবৃত আরবী কোরআনরূপে জ্ঞানী লোকদের জন্য।'),
  ('bn.bengali', 41, 4, 'সুসংবাদদাতা ও সতর্ককারীরূপে, অতঃপর তাদের অধিকাংশই মুখ ফিরিয়ে নিয়েছে, তারা শুনে না।'),
  ('bn.bengali', 41, 5, 'তারা বলে আপনি যে বিষয়ের দিকে আমাদের কে দাওয়াত দেন, সে বিষয়ে আমাদের অন্তর আবরণে আবৃত, আমাদের কর্ণে আছে বোঝা এবং আমাদের ও আপনার মাঝখানে আছে অন্তরাল। অতএব, আপনি আপনার কাজ করুন এবং আমরা আমাদের কাজ করি।'),
  ('bn.bengali', 41, 6, 'বলুন, আমিও তোমাদের মতই মানুষ, আমার প্রতি ওহী আসে যে, তোমাদের মাবুদ একমাত্র মাবুদ, অতএব তাঁর দিকেই সোজা হয়ে থাক এবং তাঁর কাছে ক্ষমা প্রার্থনা কর। আর মুশরিকদের জন্যে রয়েছে দুর্ভোগ,'),
  ('bn.bengali', 41, 7, 'যারা যাকাত দেয় না এবং পরকালকে অস্বীকার করে।'),
  ('bn.bengali', 41, 8, 'নিশ্চয় যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে, তাদের জন্যে রয়েছে অফুরন্ত পুরস্কার।'),
  ('bn.bengali', 41, 9, 'বলুন, তোমরা কি সে সত্তাকে অস্বীকার কর যিনি পৃথিবী সৃষ্টি করেছেন দু’দিনে এবং তোমরা কি তাঁর সমকক্ষ স্থীর কর? তিনি তো সমগ্র বিশ্বের পালনকর্তা।'),
  ('bn.bengali', 41, 10, 'তিনি পৃথিবীতে উপরিভাগে অটল পর্বতমালা স্থাপন করেছেন, তাতে কল্যাণ নিহিত রেখেছেন এবং চার দিনের মধ্যে তাতে তার খাদ্যের ব্যবস্থা করেছেন-পূর্ণ হল জিজ্ঞাসুদের জন্যে।'),
  ('bn.bengali', 41, 11, 'অতঃপর তিনি আকাশের দিকে মনোযোগ দিলেন যা ছিল ধুম্রকুঞ্জ, অতঃপর তিনি তাকে ও পৃথিবীকে বললেন, তোমরা উভয়ে আস ইচ্ছায় অথবা অনিচ্ছায়। তারা বলল, আমরা স্বেচ্ছায় আসলাম।'),
  ('bn.bengali', 41, 12, 'অতঃপর তিনি আকাশমন্ডলীকে দু’দিনে সপ্ত আকাশ করে দিলেন এবং প্রত্যেক আকাশে তার আদেশ প্রেরণ করলেন। আমি নিকটবর্তী আকাশকে প্রদীপমালা দ্বারা সুশোভিত ও সংরক্ষিত করেছি। এটা পরাক্রমশালী সর্বজ্ঞ আল্লাহর ব্যবস্থাপনা।'),
  ('bn.bengali', 41, 13, 'অতঃপর যদি তারা মুখ ফিরিয়ে নেয়, তবে বলুন, আমি তোমাদেরকে সতর্ক করলাম এক কঠোর আযাব সম্পর্কে আদ ও সামুদের আযাবের মত।'),
  ('bn.bengali', 41, 14, 'যখন তাদের কাছে রসূলগণ এসেছিলেন সম্মুখ দিক থেকে এবং পিছন দিক থেকে এ কথা বলতে যে, তোমরা আল্লাহ ব্যতীত কারও পূজা করো না। তারা বলেছিল, আমাদের পালনকর্তা ইচ্ছা করলে অবশ্যই ফেরেশতা প্রেরণ করতেন, অতএব, আমরা তোমাদের আনীত বিষয় অমান্য করলাম।'),
  ('bn.bengali', 41, 15, 'যারা ছিল আদ, তারা পৃথিবীতে অযথা অহংকার করল এবং বলল, আমাদের অপেক্ষা অধিক শক্তিধর কে? তারা কি লক্ষ্য করেনি যে, যে আল্লাহ তাদেরকে সৃষ্টি করেছেন, তিনি তাদের অপেক্ষা অধিক শক্তিধর ? বস্তুতঃ তারা আমার নিদর্শনাবলী অস্বীকার করত।'),
  ('bn.bengali', 41, 16, 'অতঃপর আমি তাদেরকে পার্থিব জীবনে লাঞ্ছনার আযাব আস্বাদন করানোর জন্যে তাদের উপর প্রেরণ করলাম ঝঞ্ঝাবায়ু বেশ কতিপয় অশুভ দিনে। আর পরকালের আযাব তো আরও লাঞ্ছনাকর এমতাবস্থায় যে, তারা সাহায্যপ্রাপ্ত হবে না।'),
  ('bn.bengali', 41, 17, 'আর যারা সামূদ, আমি তাদেরকে প্রদর্শন করেছিলাম, অতঃপর তারা সৎপথের পরিবর্তে অন্ধ থাকাই পছন্দ করল। অতঃপর তাদের কৃতকর্মের কারণে তাদেরকে অবমাননাকর আযাবের বিপদ এসে ধৃত করল।'),
  ('bn.bengali', 41, 18, 'যারা বিশ্বাস স্থাপন করেছিল ও সাবধানে চলত, আমি তাদেরকে উদ্ধার করলাম।'),
  ('bn.bengali', 41, 19, 'যেদিন আল্লাহর শত্রুদেরকে অগ্নিকুন্ডের দিকে ঠেলে নেওয়া হবে। এবং ওদের বিন্যস্ত করা হবে বিভিন্ন দলে।'),
  ('bn.bengali', 41, 20, 'তারা যখন জাহান্নামের কাছে পৌঁছাবে, তখন তাদের কান, চক্ষু ও ত্বক তাদের কর্ম সম্পর্কে সাক্ষ্য দেবে।'),
  ('bn.bengali', 41, 21, 'তারা তাদের ত্বককে বলবে, তোমরা আমাদের বিপক্ষে সাক্ষ্য দিলে কেন? তারা বলবে, যে আল্লাহ সব কিছুকে বাকশক্তি দিয়েছেন, তিনি আমাদেরকেও বাকশক্তি দিয়েছেন। তিনিই তোমাদেরকে প্রথমবার সৃষ্টি করেছেন এবং তোমরা তাঁরই দিকে প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 41, 22, 'তোমাদের কান, তোমাদের চক্ষু এবং তোমাদের ত্বক তোমাদের বিপক্ষে সাক্ষ্য দেবে না ধারণার বশবর্তী হয়ে তোমরা তাদের কাছে কিছু গোপন করতে না। তবে তোমাদের ধারণা ছিল যে, তোমরা যা কর তার অনেক কিছুই আল্লাহ জানেন না।'),
  ('bn.bengali', 41, 23, 'তোমাদের পালনকর্তা সম্বন্ধে তোমাদের এ ধারণাই তোমাদেরকে ধ্বংস করেছে। ফলে তোমরা ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হয়ে গেছ।'),
  ('bn.bengali', 41, 24, 'অতঃপর যদি তারা সবর করে, তবুও জাহান্নামই তাদের আবাসস্থল। আর যদি তারা ওযরখাহী করে, তবে তাদের ওযর কবুল করা হবে না।'),
  ('bn.bengali', 41, 25, 'আমি তাদের পেছনে সঙ্গী লাগিয়ে দিয়েছিলাম, অতঃপর সঙ্গীরা তাদের অগ্র-পশ্চাতের আমল তাদের দৃষ্টিতে শোভনীয় করে দিয়েছিল। তাদের ব্যাপারেও শাস্তির আদেশ বাস্তবায়িত হল, যা বাস্তবায়িত হয়েছিল তাদের পূর্ববতী জিন ও মানুষের ব্যাপারে। নিশ্চয় তারা ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 41, 26, 'আর কাফেররা বলে, তোমরা এ কোরআন শ্রবণ করো না এবং এর আবৃত্তিতে হঞ্জগোল সৃষ্টি কর, যাতে তোমরা জয়ী হও।'),
  ('bn.bengali', 41, 27, 'আমি অবশ্যই কাফেরদেরকে কঠিন আযাব আস্বাদন করাব এবং আমি অবশ্যই তাদেরকে তাদের মন্দ ও হীন কাজের প্রতিফল দেব।'),
  ('bn.bengali', 41, 28, 'এটা আল্লাহর শত্রুদের শাস্তি-জাহান্নাম। তাতে তাদের জন্যে রয়েছে স্থায়ী আবাস, আমার আয়াতসমূহ অস্বীকার করার প্রতিফলস্বরূপ।'),
  ('bn.bengali', 41, 29, 'কাফেররা বলবে, হে আমাদের পালনকর্তা! যেসব জিন ও মানুষ আমাদেরকে পথভ্রষ্ট করেছিল, তাদেরকে দেখিয়ে দাও, আমরা তাদেরকে পদদলিত করব, যাতে তারা যথেষ্ট অপমানিত হয়।'),
  ('bn.bengali', 41, 30, 'নিশ্চয় যারা বলে, আমাদের পালনকর্তা আল্লাহ, অতঃপর তাতেই অবিচল থাকে, তাদের কাছে ফেরেশতা অবতীর্ণ হয় এবং বলে, তোমরা ভয় করো না, চিন্তা করো না এবং তোমাদের প্রতিশ্রুত জান্নাতের সুসংবাদ শোন।'),
  ('bn.bengali', 41, 31, 'ইহকালে ও পরকালে আমরা তোমাদের বন্ধু। সেখানে তোমাদের জন্য আছে যা তোমাদের মন চায় এবং সেখানে তোমাদের জন্যে আছে তোমরা দাবী কর।'),
  ('bn.bengali', 41, 32, 'এটা ক্ষমাশীল করুনাময়ের পক্ষ থেকে সাদর আপ্যায়ন।'),
  ('bn.bengali', 41, 33, 'যে আল্লাহর দিকে দাওয়াত দেয়, সৎকর্ম করে এবং বলে, আমি একজন আজ্ঞাবহ, তার কথা অপেক্ষা উত্তম কথা আর কার?'),
  ('bn.bengali', 41, 34, 'সমান নয় ভাল ও মন্দ। জওয়াবে তাই বলুন যা উৎকৃষ্ট। তখন দেখবেন আপনার সাথে যে ব্যক্তির শুত্রুতা রয়েছে, সে যেন অন্তরঙ্গ বন্ধু।'),
  ('bn.bengali', 41, 35, 'এ চরিত্র তারাই লাভ করে, যারা সবর করে এবং এ চরিত্রের অধিকারী তারাই হয়, যারা অত্যন্ত ভাগ্যবান।'),
  ('bn.bengali', 41, 36, 'যদি শয়তানের পক্ষ থেকে আপনি কিছু কুমন্ত্রণা অনুভব করেন, তবে আল্লাহর শরণাপন্ন হোন। নিশ্চয় তিনি সর্বশ্রোতা, সর্বজ্ঞ।'),
  ('bn.bengali', 41, 37, 'তাঁর নিদর্শনসমূহের মধ্যে রয়েছে দিবস, রজনী, সূর্য ও চন্দ্র। তোমরা সূর্যকে সেজদা করো না, চন্দ্রকেও না; আল্লাহকে সেজদা কর, যিনি এগুলো সৃষ্টি করেছেন, যদি তোমরা নিষ্ঠার সাথে শুধুমাত্র তাঁরই এবাদত কর।'),
  ('bn.bengali', 41, 38, 'অতঃপর তারা যদি অহংকার করে, তবে যারা আপনার পালনকর্তার কাছে আছে, তারা দিবারাত্রি তাঁর পবিত্রতা ঘোষণা করে এবং তারা ক্লান্ত হয় না।'),
  ('bn.bengali', 41, 39, 'তাঁর এক নিদর্শন এই যে, তুমি ভূমিকে দেখবে অনুর্বর পড়ে আছে। অতঃপর আমি যখন তার উপর বৃষ্টি বর্ষণ করি, তখন সে শস্যশ্যামল ও স্ফীত হয়। নিশ্চয় যিনি একে জীবিত করেন, তিনি জীবিত করবেন মৃতদেরকেও। নিশ্চয় তিনি সবকিছু করতে সক্ষম।'),
  ('bn.bengali', 41, 40, 'নিশ্চয় যারা আমার আয়াতসমূহের ব্যাপারে বক্রতা অবলম্বন করে, তারা আমার কাছে গোপন নয়। যে ব্যক্তি জাহান্নামে নিক্ষিপ্ত হবে সে শ্রেষ্ঠ, না যে কেয়ামতের দিন নিরাপদে আসবে? তোমরা যা ইচ্ছা কর, নিশ্চয় তিনি দেখেন যা তোমরা কর।'),
  ('bn.bengali', 41, 41, 'নিশ্চয় যারা কোরআন আসার পর তা অস্বীকার করে, তাদের মধ্যে চিন্তা-ভাবনার অভাব রয়েছে। এটা অবশ্যই এক সম্মানিত গ্রন্থ।'),
  ('bn.bengali', 41, 42, 'এতে মিথ্যার প্রভাব নেই, সামনের দিক থেকেও নেই এবং পেছন দিক থেকেও নেই। এটা প্রজ্ঞাময়, প্রশংসিত আল্লাহর পক্ষ থেকে অবতীর্ণ।'),
  ('bn.bengali', 41, 43, 'আপনাকে তো তাই বলা হয়, যা বলা হত পূর্ববর্তী রসূলগনকে। নিশ্চয় আপনার পালনকর্তার কাছে রয়েছে ক্ষমা এবং রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 41, 44, 'আমি যদি একে অনারব ভাষায় কোরআন করতাম, তবে অবশ্যই তারা বলত, এর আয়াতসমূহ পরিস্কার ভাষায় বিবৃত হয়নি কেন? কি আশ্চর্য যে, কিতাব অনারব ভাষায় আর রসূল আরবী ভাষী! বলুন, এটা বিশ্বাসীদের জন্য হেদায়েত ও রোগের প্রতিকার। যারা মুমিন নয়, তাদের কানে আছে ছিপি, আর কোরআন তাদের জন্যে অন্ধত্ব। তাদেরকে যেন দূরবর্তী স্থান থেকে আহবান করা হয়।'),
  ('bn.bengali', 41, 45, 'আমি মূসাকে কিতাব দিয়েছিলাম, অতঃপর তাতে মতভেদ সৃষ্টি হয়। আপনার পালনকর্তার পক্ষ থেকে পূর্ব সিদ্ধান্ত না থাকলে তাদের মধ্যে ফয়সালা হয়ে যেত। তারা কোরআন সমন্ধে এক অস্বস্তিকর সন্দেহে লিপ্ত।'),
  ('bn.bengali', 41, 46, 'যে সৎকর্ম করে, সে নিজের উপকারের জন্যেই করে, আর যে অসৎকর্ম করে, তা তার উপরই বর্তাবে। আপনার পালনকর্তা বান্দাদের প্রতি মোটেই যুলুম করেন না।'),
  ('bn.bengali', 41, 47, 'কেয়ামতের জ্ঞান একমাত্র তাঁরই জানা। তাঁর জ্ঞানের বাইরে কোন ফল আবরণমুক্ত হয় না। এবং কোন নারী গর্ভধারণ ও সন্তান প্রসব করে না। যেদিন আল্লাহ তাদেরকে ডেকে বলবেন, আমার শরীকরা কোথায়? সেদিন তারা বলবে, আমরা আপনাকে বলে দিয়েছি যে, আমাদের কেউ এটা স্বীকার করে না।'),
  ('bn.bengali', 41, 48, 'পূর্বে তারা যাদের পূজা করত, তারা উধাও হয়ে যাবে এবং তারা বুঝে নেবে যে, তাদের কোন নিস্কৃতি নেই।'),
  ('bn.bengali', 41, 49, 'মানুষ উন্নতি কামনায় ক্লান্ত হয় না; যদি তাকে অমঙ্গল স্পর্শ করে, তবে সে সম্পূর্ণ রূপে নিরাশ হয়ে পড়ে।'),
  ('bn.bengali', 41, 50, 'বিপদাপদ স্পর্শ করার পর আমি যদি তাকে আমার অনুগ্রহ আস্বাদন করাই, তখন সে বলতে থাকে, এটা যে আমার যোগ্য প্রাপ্য; আমি মনে করি না যে, কেয়ামত সংঘটিত হবে। আমি যদি আমার পালনকর্তার কাছে ফিরে যাই, তবে অবশ্যই তার কাছে আমার জন্য কল্যাণ রয়েছে। অতএব, আমি কাফেরদেরকে তাদের কর্ম সম্পর্কে অবশ্যই অবহিত করব এবং তাদেরকে অবশ্যই আস্বাদন করাব কঠিন শাস্তি।'),
  ('bn.bengali', 41, 51, 'আমি যখন মানুষের প্রতি অনুগ্রহ করি তখন সে মুখ ফিরিয়ে নেয় এবং পার্শ্ব পরিবর্তন করে। আর যখন তাকে অনিষ্ট স্পর্শ করে, তখন সুদীর্ঘ দোয়া করতে থাকে।'),
  ('bn.bengali', 41, 52, 'বলুন, তোমরা ভেবে দেখেছ কি, যদি এটা আল্লাহর পক্ষ থেকে হয়, অতঃপর তোমরা একে অমান্য কর, তবে যে ব্যক্তি ঘোর বিরোধিতায় লিপ্ত, তার চাইতে অধিক পথভ্রষ্ট আর কে?'),
  ('bn.bengali', 41, 53, 'এখন আমি তাদেরকে আমার নিদর্শনাবলী প্রদর্শন করাব পৃথিবীর দিগন্তে এবং তাদের নিজেদের মধ্যে; ফলে তাদের কাছে ফুটে উঠবে যে, এ কোরআন সত্য। আপনার পালনকর্তা সর্ববিষয়ে সাক্ষ্যদাতা, এটা কি যথেষ্ট নয়?'),
  ('bn.bengali', 41, 54, 'শুনে রাখ, তারা তাদের পালনকর্তার সাথে সাক্ষাতের ব্যাপারে সন্দেহে পতিত রয়েছে। শুনে রাখ, তিনি সবকিছুকে পরিবেষ্টন করে রয়েছেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 41, 1, 'Ha. Mim.'),
  ('en.pickthall', 41, 2, 'A revelation from the Beneficent, the Merciful,'),
  ('en.pickthall', 41, 3, 'A Scripture whereof the verses are expounded, a Lecture in Arabic for people who have knowledge,'),
  ('en.pickthall', 41, 4, 'Good tidings and a warning. But most of them turn away so that they hear not.'),
  ('en.pickthall', 41, 5, 'And they say: Our hearts are protected from that unto which thou (O Muhammad) callest us, and in our ears there is a deafness, and between us and thee there is a veil. Act, then. Lo! we also shall be acting.'),
  ('en.pickthall', 41, 6, 'Say (unto them O Muhammad): I am only a mortal like you. It is inspired in me that your Allah is One Allah, therefor take the straight path unto Him and seek forgiveness of Him. And woe unto the idolaters,'),
  ('en.pickthall', 41, 7, 'Who give not the poor-due, and who are disbelievers in the Hereafter.'),
  ('en.pickthall', 41, 8, 'Lo! as for those who believe and do good works, for them is a reward enduring.'),
  ('en.pickthall', 41, 9, 'Say (O Muhammad, unto the idolaters): Disbelieve ye verily in Him Who created the earth in two Days, and ascribe ye unto Him rivals? He (and none else) is the Lord of the Worlds.'),
  ('en.pickthall', 41, 10, 'He placed therein firm hills rising above it, and blessed it and measured therein its sustenance in four Days, alike for (all) who ask;'),
  ('en.pickthall', 41, 11, 'Then turned He to the heaven when it was smoke, and said unto it and unto the earth: Come both of you, willingly or loth. They said: We come, obedient.'),
  ('en.pickthall', 41, 12, 'Then He ordained them seven heavens in two Days and inspired in each heaven its mandate; and We decked the nether heaven with lamps, and rendered it inviolable. That is the measuring of the Mighty, the Knower.'),
  ('en.pickthall', 41, 13, 'But if they turn away, then say: I warn you of a thunderbolt like the thunderbolt (which fell of old upon the tribes) of A\'ad and Thamud;'),
  ('en.pickthall', 41, 14, 'When their messengers came unto them from before them and behind them, saying: Worship none but Allah! they said: If our Lord had willed, He surely would have sent down angels (unto us), so lo! we are disbelievers in that wherewith ye have been sent.'),
  ('en.pickthall', 41, 15, 'As for A\'ad, they were arrogant in the land without right, and they said: Who is mightier than us in power? Could they not see that Allah Who created them, He was mightier than them in power? And they denied Our revelations.'),
  ('en.pickthall', 41, 16, 'Therefor We let loose on them a raging wind in evil days, that We might make them taste the torment of disgrace in the life of the world. And verily the doom of the Hereafter will be more shameful, and they will not be helped.'),
  ('en.pickthall', 41, 17, 'And as for Thamud, We gave them guidance, but they preferred blindness to the guidance, so the bolt of the doom of humiliation overtook them because of what they used to earn.'),
  ('en.pickthall', 41, 18, 'And We delivered those who believed and used to keep their duty to Allah.'),
  ('en.pickthall', 41, 19, 'And (make mention of) the day when the enemies of Allah are gathered unto the Fire, they are driven on'),
  ('en.pickthall', 41, 20, 'Till, when they reach it, their ears and their eyes and their skins testify against them as to what they used to do.'),
  ('en.pickthall', 41, 21, 'And they say unto their skins: Why testify ye against us? They say: Allah hath given us speech Who giveth speech to all things, and Who created you at the first, and unto Whom ye are returned.'),
  ('en.pickthall', 41, 22, 'Ye did not hide yourselves lest your ears and your eyes and your skins should testify against you, but ye deemed that Allah knew not much of what ye did.'),
  ('en.pickthall', 41, 23, 'That, your thought which ye did think about your Lord, hath ruined you; and ye find yourselves (this day) among the lost.'),
  ('en.pickthall', 41, 24, 'And though they are resigned, yet the Fire is still their home; and if they ask for favour, yet they are not of those unto whom favour can be shown.'),
  ('en.pickthall', 41, 25, 'And We assigned them comrades (in the world), who made their present and their past fairseeming unto them. And the Word concerning nations of the jinn and humankind who passed away before them hath effect for them. Lo! they were ever losers.'),
  ('en.pickthall', 41, 26, 'Those who disbelieve say: Heed not this Qur\'an, and drown the hearing of it; haply ye may conquer.'),
  ('en.pickthall', 41, 27, 'But verily We shall cause those who disbelieve to taste an awful doom, and verily We shall requite them the worst of what they used to do.'),
  ('en.pickthall', 41, 28, 'That is the reward of Allah\'s enemies: the Fire. Therein is their immortal home, payment forasmuch as they denied Our revelations.'),
  ('en.pickthall', 41, 29, 'And those who disbelieve will say: Our Lord! Show us those who beguiled us of the jinn and humankind. We will place them underneath our feet that they may be among the nethermost.'),
  ('en.pickthall', 41, 30, 'Lo! those who say: Our Lord is Allah, and afterward are upright, the angels descend upon them, saying: Fear not nor grieve, but hear good tidings of the paradise which ye are promised.'),
  ('en.pickthall', 41, 31, 'We are your protecting friends in the life of the world and in the Hereafter. There ye will have (all) that your souls desire, and there ye will have (all) for which ye pray.'),
  ('en.pickthall', 41, 32, 'A gift of welcome from One Forgiving, Merciful.'),
  ('en.pickthall', 41, 33, 'And who is better in speech than him who prayeth unto his Lord and doeth right, and saith: Lo! I am of those who are muslims (surrender unto Him).'),
  ('en.pickthall', 41, 34, 'The good deed and the evil deed are not alike. Repel the evil deed with one which is better, then lo! he, between whom and thee there was enmity (will become) as though he was a bosom friend.'),
  ('en.pickthall', 41, 35, 'But none is granted it save those who are steadfast, and none is granted it save the owner of great happiness.'),
  ('en.pickthall', 41, 36, 'And if a whisper from the devil reach thee (O Muhammad) then seek refuge in Allah. Lo! He is the Hearer, the Knower.'),
  ('en.pickthall', 41, 37, 'And of His portents are the night and the day and the sun and the moon. Do not prostrate to the sun or the moon; but prostrate to Allah Who created them, if it is in truth Him Whom ye worship.'),
  ('en.pickthall', 41, 38, 'But if they are too proud - still those who are with thy Lord glorify Him night and day, and tire not.'),
  ('en.pickthall', 41, 39, 'And of His portents (is this): that thou seest the earth lowly, but when We send down water thereon it thrilleth and groweth. Lo! He Who quickeneth it is verily the Quickener of the Dead. Lo! He is Able to do all things.'),
  ('en.pickthall', 41, 40, 'Lo! those who distort Our revelations are not hid from Us. Is he who is hurled into the Fire better, or he who cometh secure on the Day of Resurrection? Do what ye will. Lo! He is Seer of what ye do.'),
  ('en.pickthall', 41, 41, 'Lo! those who disbelieve in the Reminder when it cometh unto them (are guilty), for lo! it is an unassailable Scripture.'),
  ('en.pickthall', 41, 42, 'Falsehood cannot come at it from before it or from behind it. (It is) a revelation from the Wise, the Owner of Praise.'),
  ('en.pickthall', 41, 43, 'Naught is said unto thee (Muhammad) save what was said unto the messengers before thee. Lo! thy Lord is owner of forgiveness, and owner (also) of dire punishment.'),
  ('en.pickthall', 41, 44, 'And if We had appointed it a Lecture in a foreign tongue they would assuredly have said: If only its verses were expounded (so that we might understand)? What! A foreign tongue and an Arab? - Say unto them (O Muhammad): For those who believe it is a guidance and a healing; and as for those who disbelieve, there is a deafness in their ears, and it is blindness for them. Such are called to from afar.'),
  ('en.pickthall', 41, 45, 'And We verily gave Moses the Scripture, but there hath been dispute concerning it; and but for a Word that had already gone forth from thy Lord, it would ere now have been judged between them; but lo! they are in hopeless doubt concerning it.'),
  ('en.pickthall', 41, 46, 'Whoso doeth right it is for his soul, and whoso doeth wrong it is against it. And thy Lord is not at all a tyrant to His slaves.'),
  ('en.pickthall', 41, 47, 'Unto Him is referred (all) knowledge of the Hour. And no fruits burst forth from their sheaths, and no female carrieth or bringeth forth but with His knowledge. And on the day when He calleth unto them: Where are now My partners? they will say: We confess unto Thee, not one of us is a witness (for them).'),
  ('en.pickthall', 41, 48, 'And those to whom they used to cry of old have failed them, and they perceive they have no place of refuge.'),
  ('en.pickthall', 41, 49, 'Man tireth not of praying for good, and if ill toucheth him, then he is disheartened, desperate.'),
  ('en.pickthall', 41, 50, 'And verily, if We cause him to taste mercy after some hurt that hath touched him, he will say: This is my own; and I deem not that the Hour will ever rise, and if I am brought back to my Lord, I surely shall be better off with Him - But We verily shall tell those who disbelieve (all) that they did, and We verily shall make them taste hard punishment.'),
  ('en.pickthall', 41, 51, 'When We show favour unto man, he withdraweth and turneth aside, but when ill toucheth him then he aboundeth in prayer.'),
  ('en.pickthall', 41, 52, 'Bethink you: If it is from Allah and ye reject it - Who is further astray than one who is at open feud (with Allah)?'),
  ('en.pickthall', 41, 53, 'We shall show them Our portents on the horizons and within themselves until it will be manifest unto them that it is the Truth. Doth not thy Lord suffice, since He is Witness over all things?'),
  ('en.pickthall', 41, 54, 'How! Are they still in doubt about the meeting with their Lord? Lo! Is not He surrounding all things?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 41, 1, 'Ha Mim:'),
  ('en.yusufali', 41, 2, 'A Revelation from (Allah), Most Gracious, Most Merciful;-'),
  ('en.yusufali', 41, 3, 'A Book, whereof the verses are explained in detail;- a Qur\'an in Arabic, for people who understand;-'),
  ('en.yusufali', 41, 4, 'Giving good news and admonition: yet most of them turn away, and so they hear not.'),
  ('en.yusufali', 41, 5, 'They say: "Our hearts are under veils, (concealed) from that to which thou dost invite us, and in our ears in a deafness, and between us and thee is a screen: so do thou (what thou wilt); for us, we shall do (what we will!)"'),
  ('en.yusufali', 41, 6, 'Say thou: "I am but a man like you: It is revealed to me by Inspiration, that your Allah is one Allah: so stand true to Him, and ask for His Forgiveness." And woe to those who join gods with Allah,-'),
  ('en.yusufali', 41, 7, 'Those who practise not regular Charity, and who even deny the Hereafter.'),
  ('en.yusufali', 41, 8, 'For those who believe and work deeds of righteousness is a reward that will never fail.'),
  ('en.yusufali', 41, 9, 'Say: Is it that ye deny Him Who created the earth in two Days? And do ye join equals with Him? He is the Lord of (all) the Worlds.'),
  ('en.yusufali', 41, 10, 'He set on the (earth), mountains standing firm, high above it, and bestowed blessings on the earth, and measure therein all things to give them nourishment in due proportion, in four Days, in accordance with (the needs of) those who seek (Sustenance).'),
  ('en.yusufali', 41, 11, 'Moreover He comprehended in His design the sky, and it had been (as) smoke: He said to it and to the earth: "Come ye together, willingly or unwillingly." They said: "We do come (together), in willing obedience."'),
  ('en.yusufali', 41, 12, 'So He completed them as seven firmaments in two Days, and He assigned to each heaven its duty and command. And We adorned the lower heaven with lights, and (provided it) with guard. Such is the Decree of (Him) the Exalted in Might, Full of Knowledge.'),
  ('en.yusufali', 41, 13, 'But if they turn away, say thou: "I have warned you of a stunning Punishment (as of thunder and lightning) like that which (overtook) the \'Ad and the Thamud!"'),
  ('en.yusufali', 41, 14, 'Behold, the messengers came to them, from before them and behind them, (preaching): "Serve none but Allah." They said, "If our Lord had so pleased, He would certainly have sent down angels (to preach). Now we reject your mission (altogether)."'),
  ('en.yusufali', 41, 15, 'Now the \'Ad behaved arrogantly through the land, against (all) truth and reason, and said: "Who is superior to us in strength?" What! did they not see that Allah, Who created them, was superior to them in strength? But they continued to reject Our Signs!'),
  ('en.yusufali', 41, 16, 'So We sent against them a furious Wind through days of disaster, that We might give them a taste of a Penalty of humiliation in this life; but the Penalty of a Hereafter will be more humiliating still: and they will find no help.'),
  ('en.yusufali', 41, 17, 'As to the Thamud, We gave them Guidance, but they preferred blindness (of heart) to Guidance: so the stunning Punishment of humiliation seized them, because of what they had earned.'),
  ('en.yusufali', 41, 18, 'But We delivered those who believed and practised righteousness.'),
  ('en.yusufali', 41, 19, 'On the Day that the enemies of Allah will be gathered together to the Fire, they will be marched in ranks.'),
  ('en.yusufali', 41, 20, 'At length, when they reach the (Fire), their hearing, their sight, and their skins will bear witness against them, as to (all) their deeds.'),
  ('en.yusufali', 41, 21, 'They will say to their skins: "Why bear ye witness against us?" They will say: "Allah hath given us speech,- (He) Who giveth speech to everything: He created you for the first time, and unto Him were ye to return.'),
  ('en.yusufali', 41, 22, '"Ye did not seek to hide yourselves, lest your hearing, your sight, and your skins should bear witness against you! But ye did think that Allah knew not many of the things that ye used to do!'),
  ('en.yusufali', 41, 23, '"But this thought of yours which ye did entertain concerning your Lord, hath brought you to destruction, and (now) have ye become of those utterly lost!"'),
  ('en.yusufali', 41, 24, 'If, then, they have patience, the Fire will be a home for them! and if they beg to be received into favour, into favour will they not (then) be received.'),
  ('en.yusufali', 41, 25, 'And We have destined for them intimate companions (of like nature), who made alluring to them what was before them and behind them; and the sentence among the previous generations of Jinns and men, who have passed away, is proved against them; for they are utterly lost.'),
  ('en.yusufali', 41, 26, 'The Unbelievers say: "Listen not to this Qur\'an, but talk at random in the midst of its (reading), that ye may gain the upper hand!"'),
  ('en.yusufali', 41, 27, 'But We will certainly give the Unbelievers a taste of a severe Penalty, and We will requite them for the worst of their deeds.'),
  ('en.yusufali', 41, 28, 'Such is the requital of the enemies of Allah,- the Fire: therein will be for them the Eternal Home: a (fit) requital, for that they were wont to reject Our Signs.'),
  ('en.yusufali', 41, 29, 'And the Unbelievers will say: "Our Lord! Show us those, among Jinns and men, who misled us: We shall crush them beneath our feet, so that they become the vilest (before all)."'),
  ('en.yusufali', 41, 30, 'In the case of those who say, "Our Lord is Allah", and, further, stand straight and steadfast, the angels descend on them (from time to time): "Fear ye not!" (they suggest), "Nor grieve! but receive the Glad Tidings of the Garden (of Bliss), the which ye were promised!'),
  ('en.yusufali', 41, 31, '"We are your protectors in this life and in the Hereafter: therein shall ye have all that your souls shall desire; therein shall ye have all that ye ask for!-'),
  ('en.yusufali', 41, 32, '"A hospitable gift from one Oft-Forgiving, Most Merciful!"'),
  ('en.yusufali', 41, 33, 'Who is better in speech than one who calls (men) to Allah, works righteousness, and says, "I am of those who bow in Islam"?'),
  ('en.yusufali', 41, 34, 'Nor can goodness and Evil be equal. Repel (Evil) with what is better: Then will he between whom and thee was hatred become as it were thy friend and intimate!'),
  ('en.yusufali', 41, 35, 'And no one will be granted such goodness except those who exercise patience and self-restraint,- none but persons of the greatest good fortune.'),
  ('en.yusufali', 41, 36, 'And if (at any time) an incitement to discord is made to thee by the Evil One, seek refuge in Allah. He is the One Who hears and knows all things.'),
  ('en.yusufali', 41, 37, 'Among His Signs are the Night and the Day, and the Sun and the Moon. Do not prostrate to the sun and the moon, but prostrate to Allah, Who created them, if it is Him ye wish to serve.'),
  ('en.yusufali', 41, 38, 'But is the (Unbelievers) are arrogant, (no matter): for in the presence of thy Lord are those who celebrate His praises by night and by day. And they never flag (nor feel themselves above it).'),
  ('en.yusufali', 41, 39, 'And among His Signs in this: thou seest the earth barren and desolate; but when We send down rain to it, it is stirred to life and yields increase. Truly, He Who gives life to the (dead) earth can surely give life to (men) who are dead. For He has power over all things.'),
  ('en.yusufali', 41, 40, 'Those who pervert the Truth in Our Signs are not hidden from Us. Which is better?- he that is cast into the Fire, or he that comes safe through, on the Day of Judgment? Do what ye will: verily He seeth (clearly) all that ye do.'),
  ('en.yusufali', 41, 41, 'Those who reject the Message when it comes to them (are not hidden from Us). And indeed it is a Book of exalted power.'),
  ('en.yusufali', 41, 42, 'No falsehood can approach it from before or behind it: It is sent down by One Full of Wisdom, Worthy of all Praise.'),
  ('en.yusufali', 41, 43, 'Nothing is said to thee that was not said to the messengers before thee: that thy lord has at his Command (all) forgiveness as well as a most Grievous Penalty.'),
  ('en.yusufali', 41, 44, 'Had We sent this as a Qur\'an (in the language) other than Arabic, they would have said: "Why are not its verses explained in detail? What! (a Book) not in Arabic and (a Messenger an Arab?" Say: "It is a Guide and a Healing to those who believe; and for those who believe not, there is a deafness in their ears, and it is blindness in their (eyes): They are (as it were) being called from a place far distant!"'),
  ('en.yusufali', 41, 45, 'We certainly gave Moses the Book aforetime: but disputes arose therein. Had it not been for a Word that went forth before from thy Lord, (their differences) would have been settled between them: but they remained in suspicious disquieting doubt thereon.'),
  ('en.yusufali', 41, 46, 'Whoever works righteousness benefits his own soul; whoever works evil, it is against his own soul: nor is thy Lord ever unjust (in the least) to His Servants.'),
  ('en.yusufali', 41, 47, 'To Him is referred the Knowledge of the Hour (of Judgment: He knows all): No date-fruit comes out of its sheath, nor does a female conceive (within her womb) nor bring forth the Day that (Allah) will propound to them the (question), "Where are the partners (ye attributed to Me?" They will say, "We do assure thee not one of us can bear witness!"'),
  ('en.yusufali', 41, 48, 'The (deities) they used to invoke aforetime will leave them in the lurch, and they will perceive that they have no way of escape.'),
  ('en.yusufali', 41, 49, 'Man does not weary of asking for good (things), but if ill touches him, he gives up all hope (and) is lost in despair.'),
  ('en.yusufali', 41, 50, 'When we give him a taste of some Mercy from Ourselves, after some adversity has touched him, he is sure to say, "This is due to my (merit): I think not that the Hour (of Judgment) will (ever) be established; but if I am brought back to my Lord, I have (much) good (stored) in His sight!" But We will show the Unbelievers the truth of all that they did, and We shall give them the taste of a severe Penalty.'),
  ('en.yusufali', 41, 51, 'When We bestow favours on man, he turns away, and gets himself remote on his side (instead of coming to Us); and when evil seizes him, (he comes) full of prolonged prayer!'),
  ('en.yusufali', 41, 52, 'Say: "See ye if the (Revelation) is (really) from Allah, and yet do ye reject it? Who is more astray than one who is in a schism far (from any purpose)?"'),
  ('en.yusufali', 41, 53, 'Soon will We show them our Signs in the (furthest) regions (of the earth), and in their own souls, until it becomes manifest to them that this is the Truth. Is it not enough that thy Lord doth witness all things?'),
  ('en.yusufali', 41, 54, 'Ah indeed! Are they in doubt concerning the Meeting with their Lord? Ah indeed! It is He that doth encompass all things!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 41, 1, 'Haa Meeem'),
  ('en.transliteration', 41, 2, 'Tanzeelum Minar-Rahmaanir-Raheem'),
  ('en.transliteration', 41, 3, 'Kitaabun fussilat Aayaatuhoo Qur-aanan \'Arabiyyal liqawminy ya\'lamoon'),
  ('en.transliteration', 41, 4, 'Basheeranw wa nazeeran fa-a\'rada aksaruhum fahum laa yasma\'oon'),
  ('en.transliteration', 41, 5, 'Wa qaaloo quloobunaa feee akinnatim mimmaa tad\'oonaaa ilaihi wa feee aazaaninaa waqrunw wa mim baininaa wa bainika bijaabun fa\'mal innanaa \'aamiloon'),
  ('en.transliteration', 41, 6, 'Qul innamaaa ana basharum mislukum yoohaaa ilaiya annamaaa ilaahukum Ilaahunw Waahidun fastaqeemooo ilaihi wastagfirooh; wa wailul lil mushrikeen'),
  ('en.transliteration', 41, 7, 'Allazeena laa yu\'toonaz Zakaata wa hum bil-Aakhiratihum kaafiroon'),
  ('en.transliteration', 41, 8, 'Innal lazeena aamanoo wa \'amilus saalihaati lahum ajrun ghairu mamnoon'),
  ('en.transliteration', 41, 9, 'Qul a\'innakum latakfuroona billazee khalaqal arda fee yawmaini wa taj\'aloona lahooo andaadaa; zaalika Rabbul \'aalameen'),
  ('en.transliteration', 41, 10, 'Wa ja\'ala feehaa rawaa siya min fawqihaa wa baaraka feehaa wa qaddara feehaaaa aqwaatahaa feee arba\'ati ayyaamin sawaaa\'al lissaaa\'ileen'),
  ('en.transliteration', 41, 11, 'Summas tawaaa ilas-samaaa\'i wa hiya dukhaanun faqaala lahaa wa lil ardi\'tiyaaa taw\'an aw karhan qaalataaa atainaa taaa\'i\'een'),
  ('en.transliteration', 41, 12, 'Faqadaahunna sab\'a samaawaatin fee yawmaini wa awhaa fee kulli samaaa\'in amarahaa; wa zaiyannassa maaa\'ad dunyaa bimasaabeeha wa hifzaa; zaalika taqdeerul \'Azeezil \'Aleem'),
  ('en.transliteration', 41, 13, 'Fa-in a\'radoo faqul anzartukum saa\'iqatam misla saa\'iqati \'Aadinw wa Samood'),
  ('en.transliteration', 41, 14, 'Iz jaaa\'at humur Rusulu mim baini aydeehim wa min khalfihim allaa ta\'budooo illal laaha qaaloo law shaaa\'a Rabunaa la anzala malaaa \'ikatan fa innaa bimaaa ursiltum bihee kaafiroon'),
  ('en.transliteration', 41, 15, 'Fa ammaa \'Aadun fastak baroo fil ardi bighairul haqqi wa qaaloo man ashaddu minnaa quwwatan awalam yaraw annal laahal lazee khalaqahum Huwa ashaddu minhum quwwatanw wa kaanoo bi Aayaatinaa yajhadoon'),
  ('en.transliteration', 41, 16, 'Fa arsalnaa \'alaihim reehan sarsaran feee ayyaamin nahisaatil linuzeeqahum \'azaabal khizyi fil hayaatid dunyaa wa la\'azaabul Aakhirati akhzaa wa hum laa yunsaroon'),
  ('en.transliteration', 41, 17, 'Wa ammaa Samoodu fahadinaahum fastahabbul \'ama \'alal huda fa akhazathum saa\'iqatul \'azaabil hooni bimaa kaanoo yaksiboon'),
  ('en.transliteration', 41, 18, 'Wa najjainal lazeena aamanoo wa kaanoo yattaqoon'),
  ('en.transliteration', 41, 19, 'Wa yawma yuhsharu a\'daaa\'ul laahi ilan Naari fahum yooza\'oon'),
  ('en.transliteration', 41, 20, 'Hattaaa izaa maa jaaa\'oohaa shahida \'alaihim samu\'uhum wa absaaruhum wa julooduhum bimaa kaanoo ya\'maloon'),
  ('en.transliteration', 41, 21, 'Wa qaaloo lijuloodihim lima shahittum \'alainaa qaaloo antaqanal laahul lazeee antaqa kulla shai\'inw wa Huwa khalaqakum awwala marratinw wa ilaihi turja\'oon'),
  ('en.transliteration', 41, 22, 'Wa maa kuntum tastatiroona ai-yashhada \'alaikum sam\'ukum wa laaa absaarukum wa laa juloodukum wa laakin zanantum annal laaha laa ya\'lamu kaseeram mimmaa ta\'maloon'),
  ('en.transliteration', 41, 23, 'Wa zaalikum zannukumul lazee zanantum bi-Rabbikum ardaakum fa asbahtum minal khaasireen'),
  ('en.transliteration', 41, 24, 'Fa-iny yasbiroo fan Naaru maswal lahum wa iny-yasta\'tiboo famaa hum minal mu\'tabeen'),
  ('en.transliteration', 41, 25, 'Wa qaiyadnaa lahum quranaaa\'a fazaiyanoo lahum maa baina aideehim wa maa khalfahum wa haqqa \'alaihimul qawlu feee umamin qad khalat min qablihim minal jinni wal insi innahum kaanoo khaasireen'),
  ('en.transliteration', 41, 26, 'Wa qaalal lazeena kafaroo laa tasma\'oo lihaazal Quraani walghaw feehi la\'allakum taghlihoon'),
  ('en.transliteration', 41, 27, 'Falanuzeeqannal lazeena kafaroo \'azaaban shadeedanw wa lanajziyannahum aswallazee kaanoo ya\'maloon'),
  ('en.transliteration', 41, 28, 'Zaalika jazaaa\'u a\'daaa\'il laahin Naaru lahum feehaa daarul khuld, jazaaa\'am bimaa kaanoo bi aayaatinaa yajhdoon'),
  ('en.transliteration', 41, 29, 'Wa qaalal lazeena kafaroo Rabbanaaa arinal lazaini adal laanaa minal jinni wal insi naj\'alhumaa tahta aqdaaminaa liyakoonaa minal asfaleen'),
  ('en.transliteration', 41, 30, 'Innal lazeena qaaloo Rabbunal laahu summas taqaamoo tatanazzalu \'alaihimul malaaa \'ikatu allaa takhaafoo wa laa tahzanoo wa abshiroo bil Jannnatil latee kuntum too\'adoon'),
  ('en.transliteration', 41, 31, 'Nahnu awliyaaa\'ukum fil hayaatid dunyaa wa fil Aakhirati wa lakum feehaa maa tashtaheee anfusukum wa lakum feehaa ma tadda\'oon'),
  ('en.transliteration', 41, 32, 'Nuzulam min Ghafoorir Raheem'),
  ('en.transliteration', 41, 33, 'Wa man ahsanu qawlam mimman da\'aaa ilal laahi wa \'amila saalihanw wa qaala innanee minal muslimeen'),
  ('en.transliteration', 41, 34, 'Wa laa tastawil hasanatu wa las saiyi\'ah; idfa\' billatee hiya ahsanu fa\'izal lazee bainaka wa bainahoo \'adaawatun ka\'annahoo waliyun hameem'),
  ('en.transliteration', 41, 35, 'Wa maa yulaqqaahaaa illal lazeena sabaroo wa maa yulaqqaahaaa illaa zoo hazzin \'azeem'),
  ('en.transliteration', 41, 36, 'Wa immaa yanzaghannaka minash Shaitaani nazghun fasta\'iz billaahi innahoo Huwas Samee\'ul \'Aleem'),
  ('en.transliteration', 41, 37, 'Wa min Aayaatihil lailu wannahaaru washshamsu walqamar; laa tasjudoo lishshamsi wa laa lilqamari wasjudoo lillaahil lazee khala qahunna in kuntum iyyaahu ta\'budoon'),
  ('en.transliteration', 41, 38, 'Fa inis-takbaroo fallazee na \'inda Rabbika yusabbihoona lahoo billaili wannnahaari wa hum laa yas\'amoon'),
  ('en.transliteration', 41, 39, 'Wa min Aayaatiheee annaka taral arda khaashi\'atan fa izaaa anzalna \'alaihal maaa\'ah tazzat wa rabat; innal lazeee ahyaahaa lamuhiyil mawtaa; innahoo \'alaa kulli shai-in Qadeer'),
  ('en.transliteration', 41, 40, 'Innal lazeena yulhidoona feee Aayaatina laa yakhfawna \'alainaa\' afamai yulqaa fin Naari khayrun am mai yaateee aaminai Yawmal Qiyaamah; i\'maloo ma shi\'tum innahoo bimaa ta\'maloona Baseer'),
  ('en.transliteration', 41, 41, 'Inna Lazeena kafaroo biz Zikri lammaa jaa\'ahum wa innahoo la Kitaabun \'Azeez'),
  ('en.transliteration', 41, 42, 'Laa yaateehil baatilu mim baini yadaihi wa laa min khalfihee tanzeelum min Hakeemin Hameed'),
  ('en.transliteration', 41, 43, 'Maa yuqaalu laka illaa maa qad qeela lir Rusuli min qablik; inna Rabbaka lazoo maghfiratinw wa zoo \'iqaabin aleem'),
  ('en.transliteration', 41, 44, 'Wa law ja\'alnaahu Qur-aanan A\'jamiyyal laqaaloo law laa fussilat Aayaatuhoo \'a A\'jamiyyunw wa \'Arabiyy; qul huwa lillazeena aamanoo hudanw wa shifaaa\'unw wallazeena la yu\'minoona feee aazaanihim waqrunw wa huwa \'alaihim \'amaa; ulaaa\'ika yunaadawna mim maakaanim ba\'eed'),
  ('en.transliteration', 41, 45, 'Wa laqad aatainaa Moosal Kitaaba fakhtulifa fee; wa lawlaa Kalimatun sabaqat mir Rabbika laqudiya bainahum; wa innahum lafee shakkim minhu mureeb'),
  ('en.transliteration', 41, 46, 'Man \'amila salihan falinafshihee wa man asaaa\'a fa\'alaihaa; wamaa rabbuka bizallaamil lil \'abeed'),
  ('en.transliteration', 41, 47, 'Ilaihi yuraddu \'ilmus Saaa\'ah; wa maa takhruju min samaraatim min akmaamihaa wa maa tahmilu min unsaa wa laa tada\'u illaa bi\'ilmih; wa Yawma yunaadeehim aina shurakaaa\'ee qaalooo aazannaaka maa minnaa min shaheed'),
  ('en.transliteration', 41, 48, 'Wa dalla \'anhum maa kaanoo yad\'oona min qablu wa zannoo maa lahum mim mahees'),
  ('en.transliteration', 41, 49, 'Laa yas\'amul insaanu min du\'aaa\'il khairi wa im massa hush sharru fa ya\'oosun qanoot'),
  ('en.transliteration', 41, 50, 'Wa la in azaqnaahu rahmatam minnaa mim ba\'di dar raaa\'a massat hu la yaqoolanna haazaa lee wa maaa azunnus Saa\'ata qaaa\'imatanw wa la\'in ruji\'tu ilaa Rabbeee inna lee \'indahoo lalhusnaa; falanu nabbi\'annal lazeena kafaroo bimaa \'amiloo wa lanuzeeqan nahum min \'azaabin ghaleez'),
  ('en.transliteration', 41, 51, 'Wa izaaa an\'amnaa \'alal insaani a\'rada wa na-aa bijaani bihee wa izaa massahush sharru fazoo du\'aaa\'in \'areed'),
  ('en.transliteration', 41, 52, 'Qul araiaitum in kaana min \'indil laahi summa kafar tum bihee man adallu mimman huwa fee shiqaqim ba\'eed'),
  ('en.transliteration', 41, 53, 'Sanureehim Aayaatinaa fil aafaaqi wa feee anfusihim hattaa yatabaiyana lahum annahul haqq; awa lam yakfi bi Rabbika annahoo \'alaa kulli shai-in Shaheed'),
  ('en.transliteration', 41, 54, 'Alaaa innahum fee miryatim mil liqaaa\'i Rabbihim; alaaa innahoo bikulli shai\'im muheet')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 41, 1, 'حمۤ'),
  ('ur.ahmedali', 41, 2, '(یہ کتاب) بڑے مہربان نہایت رحم والے کی طرف سے نازل ہوئی ہے'),
  ('ur.ahmedali', 41, 3, 'کہ جس کی آیتیں عربی زبان میں علم والوں کے لیے واضح ہیں'),
  ('ur.ahmedali', 41, 4, 'خوشخبری دینے والی ڈرانے والی ہےپھر ان میں سے اکثر نے تو منہ ہی پھیر لیا پھر وہ سنتے بھی نہیں'),
  ('ur.ahmedali', 41, 5, 'اور کہتے ہیں ہمارے دل اس بات سے کہ جس کی طرف تو ہمیں بلاتا ہے پردوں میں ہیں اور ہمارے کانوں میں بوجھ ہے اور ہمارے اور آپ کے درمیان پردہ پڑا ہوا ہے پھر آپ اپنا کام کیے جائیں ہم بھی اپنا کام کر رہے ہیں'),
  ('ur.ahmedali', 41, 6, 'آپ ان سے کہہ دیں کہ میں بھی تم جیسا ایک آدمی ہوں میری طرف یہی حکم آتا ہے کہ تمہارا معبود ایک ہی ہے پھراس کی طرف سیدھے چلے جاؤ اور اس سے معافی مانگو اور مشرکوں کے لیے ہلاکت ہے'),
  ('ur.ahmedali', 41, 7, 'جو زکواة نہیں دیتے اور وہ آخرت کے بھی منکر ہیں'),
  ('ur.ahmedali', 41, 8, 'بے شک جو لوگ ایمان لائے اور انہوں نے نیک کام بھی کیے ان کے لیے بے انتہا اجر ہے'),
  ('ur.ahmedali', 41, 9, 'کہہ دو کیا تم اس کا انکار کرتے ہو جس نے دو دن میں زمین بنائی اور تم اس کے لیے شریک ٹھیراتے ہو وہی سب جہانوں کا پروردگار ہے'),
  ('ur.ahmedali', 41, 10, 'اور اس نے زمین میں اوپر سے پہاڑ رکھے اور اس میں برکت دی اور چار دن میں اس کی غذاؤں کا اندازہ کیا (یہ جواب) پوچھنے والوں کے لیے پورا ہے'),
  ('ur.ahmedali', 41, 11, 'پھر وہ آسمان کی طرف متوجہ ہوا اور وہ دھؤاں تھا پس اس کو اور زمین کو فرمایا کہ خوشی سے آؤ یا جبر سے دونوں نے کہا ہم خوشی سے آئے ہیں'),
  ('ur.ahmedali', 41, 12, 'پھر انہیں دو دن میں سات آسمان بنا دیا اور اس نے ہر ایک آسمان میں اس کا کام القا کیا اور ہم نے پہلے آسمان کو چراغوں سے زینت دی اور حفاظت کے لیے بھی یہ زبردست ہر چیز کے جاننے والے کا اندازہ ہے'),
  ('ur.ahmedali', 41, 13, 'پس اگر وہ نہ مانیں تو کہہ دو میں تمہیں کڑک سے ڈراتا ہوں جیسا کہ قوم عاد اور ثمود پر کڑک آئی تھی'),
  ('ur.ahmedali', 41, 14, 'جب ان کے پاس رسول آئے ان کے سامنے سے اور ان کے پیچھے سے کہ سوائے الله کے کسی کی عبادت نہ کرو تو کہنے لگےکہ اگر ہمارا رب چاہتا تو فرشتے نازل کر دیتا پس ہم تو اس چیز سے جو تم دے کر بھیجے گئے ہو منکر ہیں'),
  ('ur.ahmedali', 41, 15, 'پس قوم عاد نے زمین میں ناحق تکبر کیا اورکہا ہم سے طاقت میں کون زیادہ ہے کیا انہوں نے دیکھا نہیں کہ الله جس نے انہیں پیدا کیا ہے وہ ان سے طاقت میں کہیں بڑھ کر ہے وہ ہماری آیتوں کا انکار کرتے رہے'),
  ('ur.ahmedali', 41, 16, 'پس ہم نے ان پر منحوس دنوں میں تیز آندھی بھیجی تاکہ ہم انہیں ذلت کے عذاب کا مزہ دنیا کی زندگی میں چکھا دیں اور آخرت کا عذاب تواور بھی ذلت کا ہے اور ان کی مدد نہ کی جائے گی'),
  ('ur.ahmedali', 41, 17, 'اور وہ جو قوم ثمود تھی ہم نے انہیں ہدایت کی سو انہوں نے گمراہی کو بمقابلہ ہدایت کے پسند کیا پھر انہیں کڑاکے کے ذلیل کرنے والے عذاب نے آ لیا ان کے اعمال کے سبب سے'),
  ('ur.ahmedali', 41, 18, 'اورجو لوگ ایمان لائے اور ڈرتے رہتے تھے ہم نے انہیں بچا لیا'),
  ('ur.ahmedali', 41, 19, 'اور جس دن الله کے دشمن دوزخ کی طرف ہانکیں جائیں گے تو وہ روک لیے جائیں گے'),
  ('ur.ahmedali', 41, 20, 'یہاں تک کہ جب وہ اس کے پاس آ پہنچیں گے تو ان پر ان کے کان اور ان کی آنکھیں اور ان کی کھالیں گواہی دیں گی جو کچھ وہ کیا کرتے تھے'),
  ('ur.ahmedali', 41, 21, 'وہ اپنی کھالوں سے کہیں گے کہ تم نے ہمارے خلاف کیوں گواہی دی وہ کہیں گے کہ ہمیں الله نے گویائی دی جس نے ہر چیز کو گویائی بخشی ہے اور اسی نے پہلی مرتبہ تمہیں پیدا کیا اور اسی کی طرف تم لوٹائے جاؤ گے'),
  ('ur.ahmedali', 41, 22, 'اور تم اپنے کانوں اور آنکھوں اور چمڑو ں کی اپنے اوپر گواہی دینے سے پردہ نہ کرتے تھے لیکن تم نے یہ گمان کیا تھا جو کچھ تم کرتے ہو اس میں سے بہت سی چیزوں کو الله نہیں جانتا'),
  ('ur.ahmedali', 41, 23, 'او رتمہارے اسی خیال نے جو تم نے اپنے رب کے حق میں کیا تھا تمہیں برباد کیا پھر تم نقصان اٹھانے والو ں میں سے ہوگئے'),
  ('ur.ahmedali', 41, 24, 'پس اگر وہ صبر کریں تو بھی ان کا ٹھکانہ آگ ہی ہے اور اگر وہ معافی چاہیں گے تو انہیں معافی نہیں دی جائے گی'),
  ('ur.ahmedali', 41, 25, 'اورہم نے ان کے لیے کچھ ہمنشین مقرر کر دیئے پس انہوں نے ان کو وہ (برے کام) اچھے کر دکھائے جو پہلے کر چکے تھے اورجو پیچھے کریں گے اور ان پر حکم الہیٰ ثابت ہو چکا تھاپہلی امتوں کے ضمن میں جو ان سے پہلے جنوں اور انسانوں میں سے گزر چکی تھیں بے شک وہ نقصان اٹھانے والے تھے'),
  ('ur.ahmedali', 41, 26, 'اور کافروں نے کہا کہ تم اس قرآن کو نہ سنو اور اس میں غل مچاؤ تاکہ تم غالب ہو جاؤ'),
  ('ur.ahmedali', 41, 27, 'پس ہم ضرور کافرو ں کو سخت عذاب کا مزہ چکھائیں گے اور ہم ان کے بدترین اعمال کا بدلہ دیں گے جو وہ کیا کرتے تھے'),
  ('ur.ahmedali', 41, 28, 'الله کے دشمنوں کی یہی سزا آگ ہی ہے ان کے لیے اس میں ہمیشہ رہنے کا گھر ہے اس کا بدلہ جو ہماری آیتوں کاانکار کیا کرتے تھے'),
  ('ur.ahmedali', 41, 29, 'اور کافر کہیں گے اے ہمارے رب ہمیں وہ لوگ دکھا جنہوں نے ہمیں گمراہ کیا تھا جنّوں اور انسانوں میں سے ہم انہیں اپنے قدموں کے نیچے ڈال دیں تاکہ وہ بہت ذلیل ہوں'),
  ('ur.ahmedali', 41, 30, 'بے شک جنہوں نے کہا تھا کہ ہمارا رب الله ہے پھر اس پر قائم رہے ان پر فرشتے اتریں گے کہ تم خوف نہ کرو اور نہ غم کرو اور جنت میں خوش رہو جس کا تم سے وعدہ کیا جاتا تھا'),
  ('ur.ahmedali', 41, 31, 'ہم تمہارے دنیا میں بھی دوست تھے اور آخرت میں بھی اور بہشت میں تمہارے لیے ہر چیز موجود ہے جس کو تمہارا دل چاہے اور تم جو وہاں مانگو گے ملے گا'),
  ('ur.ahmedali', 41, 32, 'بخشنے والے نہایت رحم والے کی طرف سے مہمانی ہے'),
  ('ur.ahmedali', 41, 33, 'اور اس سے بہتر کس کی بات ہے جس نے لوگوں کو الله کی طرف بلایا اور خود بھی اچھے کام کیے اور کہا بے شک میں بھی فرمانبرداروں میں سے ہوں'),
  ('ur.ahmedali', 41, 34, 'اور نیکی اور بدی برابر نہیں ہو تی (برائی کا) دفعیہ اس بات سے کیجیئے جو اچھی ہو پھر ناگہاں وہ شخص جو تیرے اور اس کے درمیان دشمنی تھی ایسا ہوگا گویاکہ وہ مخلص دوست ہے'),
  ('ur.ahmedali', 41, 35, 'اور یہ بات نہیں دی جاتی مگر انہیں جو صابر ہوتے ہیں اور یہ بات نہیں دی جاتی مگر اس کو جو بڑا بخت والا ہے'),
  ('ur.ahmedali', 41, 36, 'اور اگر آپ کو شیطان سے کوئی وسوسہ آنے لگے تو الله کی پناہ مانگیئے بے شک وہی سب کچھ سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 41, 37, 'اور اس کی نشانیوں میں سے رات اور دن اور سورج اور چاند ہیں سورج کو سجدہ نہ کرو اور نہ چاند کو اور اس الله کو سجدہ کرو جس نے انہیں پیدا کیا ہے اگر تم اسی کی عبادت کرتے ہو'),
  ('ur.ahmedali', 41, 38, 'پھر اگر وہ تکبر کریں تو وہ لوگ جو آپ کے رب کے پاس ہیں رات دن اس کی تسبیح کرتے ہیں اور تھکتے نہیں'),
  ('ur.ahmedali', 41, 39, 'اور اس کی نشانیوں میں سے یہ ہے کہ تو زمین کو دبی ہوئی دیکھتا ہے پھر جب ہم اس پر پانی برساتے ہیں تو ابھرتی ہے اور پھولتی ہے بے شک جس نے اسےزندہ کیا وہی مردوں کو زندہ کرے گا بے شک وہی ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 41, 40, 'بے شک جو لوگ ہماری آیتوں میں کجروی کرتے ہیں وہ ہم سے چھپے نہیں رہتے کیا وہ شخص جو آگ میں ڈالا جائے گا بہتر ہے یا وہ جو قیامت کے دن امن سے آئے گا جو چاہو کرو جو کچھ تم کرتے ہو وہ دیکھ رہا ہے'),
  ('ur.ahmedali', 41, 41, 'بے شک وہ لوگ جنہوں نے نصیحت سے انکار کیا جب کہ وہ ان کے پاس آئی اور تحقیق وہ البتہ عزت والی کتاب ہے'),
  ('ur.ahmedali', 41, 42, 'جس میں نہ آگے اور نہ پیچھے سے غلطی کا دخل ہے حکمت والے تعریف کیے ہوئے کی طرف سے نازل کی گئی ہے'),
  ('ur.ahmedali', 41, 43, 'آپ سے وہی بات کہی جاتی ہے جو آپ سے پہلے رسولوں سے کہی گئی تھی بے شک آپ کا رب بخشنے والا اور دردناک عذاب دینے والا بھی ہے'),
  ('ur.ahmedali', 41, 44, 'اور اگر ہم اسے عجمی زبان کا قرآن بنا دیتے توکہتے کہ اس کی آیتیں صاف صاف بیان کیوں نہیں کی گئیں کیا عجمی کتاب اور عربی رسول کہہ دو یہ ایمان داروں کے لیے ہدایت اور شفا ہے او رجو لوگ ایمان نہیں لاتے ان کے کان بہرے ہیں اور وہ قرآن ان کے حق میں نابینائی ہے وہ لوگ (گو یاکہ) دور جگہ سے پکارے جا رہے ہیں'),
  ('ur.ahmedali', 41, 45, 'اورہم نے موسیٰ کو کتاب دی تھی پھر اس میں اختلاف کیا گیا اور اگر آپ کے رب کی طرف سے ایک بات صادر نہ ہو چکی ہوتی تو ان کا فیصلہ ہی ہو چکا ہوتا اورانہیں تو قرآن میں قوی شک ہے'),
  ('ur.ahmedali', 41, 46, 'جو کوئی نیک کام کرتاہے تو اپنے لیے اور برائی کرتا ہے تو اپنے سر پر اور آپ کا رب تو بندوں پر کچھ بھی ظلم نہیں کرتا'),
  ('ur.ahmedali', 41, 47, 'قیامت کی خبرکا اسی کی طرف حوالہ دیا جاتا ہے اور کوئی پھل اپنے غلافوں سے نہیں نکلتا اور نہ کوئی مادہ حاملہ ہوتی ہے اور نہ وضح حمل کرتی ہے مگر اس کے علم سے اور جس دن انہیں پکارے گا کہ میرے شریک کہاں ہیں کہیں گے ہم نے آپ سے عرض کر دیا کہ ہم میں سے کسی کو بھی خبر نہیں'),
  ('ur.ahmedali', 41, 48, 'اور ان سے وہ کھوئے جائیں گے جنہیں اس سے پہلے پکارتے تھے اوریقین کر لیں گے کہ انہیں کسی طرح بھی چھٹکارا نہیں'),
  ('ur.ahmedali', 41, 49, 'انسان بھلائی مانگنے سے نہیں تھکتا اور اگر اسے کوئی تکلیف پہنچ جائے تو مایوس اور نا امید ہو جاتا ہے'),
  ('ur.ahmedali', 41, 50, 'اور اگر ہم اسے اس مصیبت کے بعدجو اس پر آئی تھی اپنی رحمت کا مزہ چکھاتے ہیں تو کہتا ہے یہ میرا حق تھا اور میں نہیں خیال کرتا کہ قیامت قائم ہو گی اور اگر میں اپنے رب کے پاس گیا بھی تو بے شک میرے لیے اس کے ہاں بھلائی ہی ہو گی ہم کافروں کو ضرور بتائیں گے جو کچھ وہ کرتے رہے اور ہم ضرور انہیں سخت عذاب چکھائیں گے'),
  ('ur.ahmedali', 41, 51, 'اور جب ہم نے انسان پر انعام کیا تو اس نے منہ پھیر لیا اور کنارہ کش ہو گیا اور جب اس کو تکلیف پہنچی تو لمبی چوڑی دعا کرنے لگا'),
  ('ur.ahmedali', 41, 52, 'کہہ دو بھلا دیکھوتو سہی اگر یہ قرآن الله کی طرف سے ہو پھر تم اس کا انکار کر بیٹھے تو ایسے پرلے درجہ کے ضدی سے کون زیادہ گمراہ ہو گا'),
  ('ur.ahmedali', 41, 53, 'عنقریب ہم اپنی نشانیاں انہیں دنیا میں دکھائیں گے اور خود ان کے نفس میں یہاں تک کہ ان پر واضح ہو جائے گا کہ وہی حق ہے کیا ان کے رب کی یہ بات کافی نہیں کہ وہ ہر چیز کو دیکھ رہا ہے'),
  ('ur.ahmedali', 41, 54, 'خبردار انہیں اپنے رب کے پاس حاضر ہونے میں شک ہے خبردار بے شک وہ ہر چیز کوگھیرے ہوئے ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 41, 1, 'Ha, Mim.'),
  ('tr.diyanet', 41, 2, 'Bu Kitap, merhametli olan Allah katından indirilmedir; bilen bir millet için müjdeci ve uyarıcı olmak üzere Arapça okunarak, ayetleri uzun uzun açıklanmıştır. Ama insanların çoğu yüz çevirmiştir, onlar işitmezler de: "Bizi çağırdığın şeye karşı kalblerimiz kapalıdır, kulaklarımızda ağırlık, bizimle senin aranda anlaşmamıza engel vardır; istediğini yap, biz de yapacağız" derler.'),
  ('tr.diyanet', 41, 3, 'Bu Kitap, merhametli olan Allah katından indirilmedir; bilen bir millet için müjdeci ve uyarıcı olmak üzere Arapça okunarak, ayetleri uzun uzun açıklanmıştır. Ama insanların çoğu yüz çevirmiştir, onlar işitmezler de: "Bizi çağırdığın şeye karşı kalblerimiz kapalıdır, kulaklarımızda ağırlık, bizimle senin aranda anlaşmamıza engel vardır; istediğini yap, biz de yapacağız" derler.'),
  ('tr.diyanet', 41, 4, 'Bu Kitap, merhametli olan Allah katından indirilmedir; bilen bir millet için müjdeci ve uyarıcı olmak üzere Arapça okunarak, ayetleri uzun uzun açıklanmıştır. Ama insanların çoğu yüz çevirmiştir, onlar işitmezler de: "Bizi çağırdığın şeye karşı kalblerimiz kapalıdır, kulaklarımızda ağırlık, bizimle senin aranda anlaşmamıza engel vardır; istediğini yap, biz de yapacağız" derler.'),
  ('tr.diyanet', 41, 5, 'Bu Kitap, merhametli olan Allah katından indirilmedir; bilen bir millet için müjdeci ve uyarıcı olmak üzere Arapça okunarak, ayetleri uzun uzun açıklanmıştır. Ama insanların çoğu yüz çevirmiştir, onlar işitmezler de: "Bizi çağırdığın şeye karşı kalblerimiz kapalıdır, kulaklarımızda ağırlık, bizimle senin aranda anlaşmamıza engel vardır; istediğini yap, biz de yapacağız" derler.'),
  ('tr.diyanet', 41, 6, 'Onlara söyle: "Ben de ancak sizin gibi bir insanım. Bana, tanrınızın tek bir Tanrı olduğu vahyolunuyor. Artık O\'na yönelin, O\'ndan bağışlanma dileyin; vay ortak koşanlara!"'),
  ('tr.diyanet', 41, 7, 'Onlar zekat vermezler; ahireti inkar edenler de yalnız onlardır.'),
  ('tr.diyanet', 41, 8, 'Doğrusu inanıp yararlı iş işleyenlere, onlara kesintisiz bir ecir vardır.'),
  ('tr.diyanet', 41, 9, '"Siz yeri iki günde yaratanı mı inkar ediyor ve O\'na eşler koşuyorsunuz! O, alemlerin Rabbidir" de.'),
  ('tr.diyanet', 41, 10, 'Yeryüzüne üstünden ağır baskılar (dağlar) yerleştirdi, onu bereketli kıldı; arayıp soranlar için gıdalarını tam (toplam) dört gün içinde yetiştirmesi kanununu koydu (takdir etti).'),
  ('tr.diyanet', 41, 11, 'Sonra, duman halinde bulunan göğe yöneldi, ona ve yeryüzüne: "İsteyerek veya istemeyerek buyruğuma gelin" dedi. İkisi de: "İsteyerek geldik" dediler.'),
  ('tr.diyanet', 41, 12, 'Böylece onları, iki gün içinde yedi göğe tamamladı ve her göğün işini kendisine bildirdi. Yakın göğü ışıklarla donattık ve bozulmaktan koruduk. İşte bu, bilen, güçlü olan Allah\'ın kanunudur.'),
  ('tr.diyanet', 41, 13, 'Eğer yüz çevirirlerse onlara de ki: "İşte sizi, Ad ve Semud\'un başına gelen yıldırıma benzer bir azap ile uyardım."'),
  ('tr.diyanet', 41, 14, 'Onlara, önlerinden, artlarından, her yönden: "Allah\'tan başkasına kulluk etmeyin" diyen peygamberler gelmişti: "Eğer Rabbimiz böyle bir şey dileseydi melekler indirirdi. Doğrusu sizinle gönderileni inkar ederiz" demişlerdi.'),
  ('tr.diyanet', 41, 15, 'Ad milleti, yeryüzünde haksız yere büyüklük taslamış, "Bizden daha kuvvetli kim vardır?" demişti. Onlar, kendilerini yaratan Allah\'ın onlardan daha kuvvetli olduğunu görmüyorlardı değil mi? Ayetlerimizi bile bile inkar ediyorlardı.'),
  ('tr.diyanet', 41, 16, 'Rezillik azabını onlara dünya hayatında tattırmak için uğursuz günlerde üzerlerine dondurucu bir kasırga gönderdik. Ahiret azabı ise daha çok alçaltıcıdır ve onlar yardım da görmezler.'),
  ('tr.diyanet', 41, 17, 'Semud milletine, doğru yolu göstermiştik, ama onlar körlüğü, doğru yolda gitmeye tercih ettiler. Kazandıklarının karşılığı olarak onları alçaltıcı azabın yıldırımı çarptı.'),
  ('tr.diyanet', 41, 18, 'İnananları ve Allah\'a karşı gelmekten sakınmış olanları kurtardık.'),
  ('tr.diyanet', 41, 19, 'Allah\'ın düşmanları o gün cehenneme sürülürler. Hepsi bir aradadırlar.'),
  ('tr.diyanet', 41, 20, 'Sonunda oraya varınca, kulakları, gözleri ve derileri, yaptıkları hakkında onların aleyhinde şahidlik ederler.'),
  ('tr.diyanet', 41, 21, 'Derilerine: "Aleyhimize niçin şahidlik ettiniz?" derler. "Bizi, her şeyi konuşturan Allah konuşturdu. Sizi önce yaratan O\'dur ve O\'na döndürülüyorsunuz" cevabını verirler.'),
  ('tr.diyanet', 41, 22, 'Siz, gözleriniz, kulaklarınız ve derilerinizin aleyhinize şahidlik edeceğinden korkarak kötü iş işlemekten çekinmiyordunuz. Hayır; Allah\'ın, yaptıklarınızın çoğunu bilmediğini sanıyordunuz.'),
  ('tr.diyanet', 41, 23, 'İşte Rabbinizi böyle sanmanız sizi mahvetti de hüsrana uğrayanlardan oldunuz.'),
  ('tr.diyanet', 41, 24, 'İster sabretsinler ister etmesinler, onların durağı ateştir. Hoş tutulmalarını isteseler de artık hoş tutulmazlar.'),
  ('tr.diyanet', 41, 25, 'Onların yanına bir takım yardakçılar koyarız da geçmişlerini geleceklerini onlara güzel gösterirler. Verilen söz, gerek cinlerden ve gerekse insanlardan, gelip geçmiş ümmetler içinde, onların aleyhine gerçekleşmiştir. Doğrusu onlar hüsranda idiler.'),
  ('tr.diyanet', 41, 26, 'İnkar edenler: "Bu Kuran\'ı dinlemeyin, okunurken gürültü yapın, belki bastırırsınız" dediler.'),
  ('tr.diyanet', 41, 27, 'İnkar edenlere çetin bir azap tattıracağız. İşledikleri en kötü işlere karşılık onların cezasını vereceğiz.'),
  ('tr.diyanet', 41, 28, 'İşte böyle; Allah\'ın düşmanlarının cezası ateştir. Ayetlerimizi bile bile inkar etmeleri karşılığı orası onların temelli kalacakları yerdir.'),
  ('tr.diyanet', 41, 29, 'İnkar edenler: "Rabbimiz! Cinlerden ve insanlardan, bizi saptıranları göster, onları ayaklarımızın altına alalım da en altta kalanlardan olsunlar" derler.'),
  ('tr.diyanet', 41, 30, '"Rabbimiz Allah\'tır" deyip sonra da doğrulukta devam edenler, onları, melekler, ölümleri anında: "Korkmayınız, üzülmeyiniz, size söz verilen cennetle sevinin, biz dünya hayatında da, ahirette de size dostuz. Burada, canlarınızın çektiği, umduğunuz şeyler, bağışlayan ve acıyan Allah katından bir ziyafet olarak size sunulur" diyerek inerler.'),
  ('tr.diyanet', 41, 31, '"Rabbimiz Allah\'tır" deyip sonra da doğrulukta devam edenler, onları, melekler, ölümleri anında: "Korkmayınız, üzülmeyiniz, size söz verilen cennetle sevinin, biz dünya hayatında da, ahirette de size dostuz. Burada, canlarınızın çektiği, umduğunuz şeyler, bağışlayan ve acıyan Allah katından bir ziyafet olarak size sunulur" diyerek inerler.'),
  ('tr.diyanet', 41, 32, '"Rabbimiz Allah\'tır" deyip sonra da doğrulukta devam edenler, onları, melekler, ölümleri anında: "Korkmayınız, üzülmeyiniz, size söz verilen cennetle sevinin, biz dünya hayatında da, ahirette de size dostuz. Burada, canlarınızın çektiği, umduğunuz şeyler, bağışlayan ve acıyan Allah katından bir ziyafet olarak size sunulur" diyerek inerler.'),
  ('tr.diyanet', 41, 33, '"Doğrusu ben, kendini Allah\'a verenlerdenim" diyen, yararlı iş işleyen ve Allah\'a çağıran kimseden daha güzel sözlü kim vardır?'),
  ('tr.diyanet', 41, 34, 'İyilik ve fenalık bir değildir. Ey inanan kişi: Sen, fenalığı en güzel şekilde sav; o zaman, seninle arasında düşmanlık bulunan kişinin yakın bir dost gibi olduğunu görürsün.'),
  ('tr.diyanet', 41, 35, 'Bu, ancak sabredenlere vergidir; bu ancak o büyük hazzı tadanlara vergidir.'),
  ('tr.diyanet', 41, 36, 'Şeytan seni dürtecek olursa Allah\'a sığın; doğrusu O, işitendir, bilendir.'),
  ('tr.diyanet', 41, 37, 'Gece ile gündüz, güneş ile ay Allah\'ın varlığının belgelerindendir. Güneşe ve aya secde etmeyin; eğer Allah\'a kulluk etmek istiyorsanız, bunları yaratana secde edin.'),
  ('tr.diyanet', 41, 38, 'Eğer büyüklük taslarlarsa kendi aleyhlerinedir. Rabbinin katında bulunanlar hiç usanmadan, O\'nu gece gündüz tesbih ederler.'),
  ('tr.diyanet', 41, 39, 'Kupkuru gördüğün yeryüzünün, Biz ona su indirdiğimiz zaman harekete geçmesi, kabarması, Allah\'ın varlığının belgelerindendir. Ona can veren Allah şüphesiz ölüleri de diriltir. Doğrusu O her şeye kadir\'dir.'),
  ('tr.diyanet', 41, 40, 'Ayetlerimizi inkar edenler Bize gizli değillerdir. Kıyamet gününde ateşe atılan mı, yoksa güven içinde gelen kimse mi daha iyidir? Dilediğinizi işleyin, doğrusu O, yaptıklarınızı gören\'dir.'),
  ('tr.diyanet', 41, 41, 'Kitap kendilerine gelince, onlar, onu inkar etmişlerdir; oysa o, değerli bir Kitap\'dır. Geçmişte ve gelecekte onu batıl kılacak yoktur. Hakim ve övülmeğe layık olan Allah katından indirilmedir.'),
  ('tr.diyanet', 41, 42, 'Kitap kendilerine gelince, onlar, onu inkar etmişlerdir; oysa o, değerli bir Kitap\'dır. Geçmişte ve gelecekte onu batıl kılacak yoktur. Hakim ve övülmeğe layık olan Allah katından indirilmedir.'),
  ('tr.diyanet', 41, 43, 'Senin için söylenenler, senden önceki peygamberler için de söylenmişti. Doğrusu Rabbin hem bağışlayan ve hem de can yakıcı azap verendir.'),
  ('tr.diyanet', 41, 44, 'Biz bu Kuran\'ı yabancı bir dil ile ortaya koysaydık: "Ayetleri uzun açıklanmalı değil miydi? Araba yabancı bir dille söylenir mi?" derlerdi. De ki: "Bu, inananlara doğruluk rehberi ve gönüllerine şifadır." İnanmayanların kulaklarında ağırlık vardır ve onlara kapalıdır; sanki bunlara uzak bir mesafeden sesleniliyor da anlamıyorlar.'),
  ('tr.diyanet', 41, 45, 'And olsun ki Musa\'ya Kitap vermiştik de onda ayrılığa düşmüşlerdi. Rabbinin verilmiş bir sözü olmasaydı, aralarında hükmedilmiş olurdu. Doğrusu onlar, onun hakkında şüphe ve endişe içindedirler.'),
  ('tr.diyanet', 41, 46, 'Kim yararlı iş işlerse kendi lehinedir; kim de kötülük işlerse kendi aleyhinedir. Rabbin, kullara karşı zalim değildir.'),
  ('tr.diyanet', 41, 47, 'Kıyametin ne zaman kopacağı bilgisi ona aittir. O\'nun bilgisi dışında hiçbir ürün kabuğundan çıkmaz, hiçbir dişi gebe kalmaz ve doğurmaz. Onlara: "Bana koştuğunuz ortaklar nerede?" diye seslendiği gün: "Sana, buna dair bizden hiçbir şahit olmadığınıarzederiz" derler.'),
  ('tr.diyanet', 41, 48, 'Önceden yalvarıp durdukları şeyler onlardan uzaklaşmıştır. Kendilerinin kaçacak yerleri olmadığını anlamışlardır.'),
  ('tr.diyanet', 41, 49, 'İnsan, iyilik istemekten usanmaz da, kendisine bir kötülük gelince umutsuzluğa düşer, meyus olur.'),
  ('tr.diyanet', 41, 50, 'Başına gelen sıkıntıdan sonra, kendisine katımızdan bir rahmet tattırsak: "Bu benim hakkımdır; kıyametin kopacağını sanmıyorum. Rabbime döndürülürsem, O\'nun katında and olsun ki, benim için daha güzel şeyler vardır" der. İnkar edenlere, işlediklerini, and olsun ki bildireceğiz. Onlara and olsun ki çetin bir azap tattıracağız.'),
  ('tr.diyanet', 41, 51, 'İnsana nimet verdiğimiz zaman yüz çevirerek yan çizer; başına bir kötülük gelince uzun uzun yalvarır.'),
  ('tr.diyanet', 41, 52, 'De ki: "Kuran Allah katından gelmiş olup da siz de onu inkar etmişseniz, söyleyin bana, derin bir çıkmazda bulunan kimseden daha sapık kim vardır?"'),
  ('tr.diyanet', 41, 53, 'Onun hak olduğu meydana çıkıncaya kadar varlığımızın belgelerini onlara hem dış dünyada ve hem de kendi içlerinde göstereceğiz. Rabbinin her şeye şahit olması yetmez mi?'),
  ('tr.diyanet', 41, 54, 'Dikkat edin; onlar Rablerine kavuşmaktan şüphededirler; dikkat edin; Allah şüphesiz her şeyi bilgisiyle kuşatandır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 41, 1, 'Haa Miim.'),
  ('id.indonesian', 41, 2, 'Diturunkan dari Tuhan Yang Maha Pemurah lagi Maha Penyayang.'),
  ('id.indonesian', 41, 3, 'Kitab yang dijelaskan ayat-ayatnya, yakni bacaan dalam bahasa Arab, untuk kaum yang mengetahui,'),
  ('id.indonesian', 41, 4, 'yang membawa berita gembira dan yang membawa peringatan, tetapi kebanyakan mereka berpaling, tidak mau mendengarkan.'),
  ('id.indonesian', 41, 5, 'Mereka berkata: "Hati kami berada dalam tutupan (yang menutupi) apa yang kamu seru kami kepadanya dan telinga kami ada sumbatan dan antara kami dan kamu ada dinding, maka bekerjalah kamu; sesungguhnya kami bekerja (pula)".'),
  ('id.indonesian', 41, 6, 'Katakanlah: "Bahwasanya aku hanyalah seorang manusia seperti kamu, diwahyukan kepadaku bahwasanya Tuhan kamu adalah Tuhan yang Maha Esa, maka tetaplah pada jalan yang lurus menuju kepada-Nya dan mohonlah ampun kepada-Nya. Dan kecelakaan besarlah bagi orang-orang yang mempersekutukan-Nya,'),
  ('id.indonesian', 41, 7, '(yaitu) orang-orang yang tidak menunaikan zakat dan mereka kafir akan adanya (kehidupan) akhirat.'),
  ('id.indonesian', 41, 8, 'Sesungguhnya orang-orang yang beriman dan beramal saleh, mereka mendapat pahala yang tiada putus-putusnya".'),
  ('id.indonesian', 41, 9, 'Katakanlah: "Sesungguhnya patutkah kamu kafir kepada Yang menciptakan bumi dalam dua masa dan kamu adakan sekutu-sekutu bagi-Nya? (Yang bersifat) demikian itu adalah Rabb semesta alam".'),
  ('id.indonesian', 41, 10, 'Dan dia menciptakan di bumi itu gunung-gunung yang kokoh di atasnya. Dia memberkahinya dan Dia menentukan padanya kadar makanan-makanan (penghuni)nya dalam empat masa. (Penjelasan itu sebagai jawaban) bagi orang-orang yang bertanya.'),
  ('id.indonesian', 41, 11, 'Kemudian Dia menuju kepada penciptaan langit dan langit itu masih merupakan asap, lalu Dia berkata kepadanya dan kepada bumi: "Datanglah kamu keduanya menurut perintah-Ku dengan suka hati atau terpaksa". Keduanya menjawab: "Kami datang dengan suka hati".'),
  ('id.indonesian', 41, 12, 'Maka Dia menjadikannya tujuh langit dalam dua masa. Dia mewahyukan pada tiap-tiap langit urusannya. Dan Kami hiasi langit yang dekat dengan bintang-bintang yang cemerlang dan Kami memeliharanya dengan sebaik-baiknya. Demikianlah ketentuan Yang Maha Perkasa lagi Maha Mengetahui.'),
  ('id.indonesian', 41, 13, 'Jika mereka berpaling maka katakanlah: "Aku telah memperingatkan kamu dengan petir, seperti petir yang menimpa kaum \'Aad dan Tsamud".'),
  ('id.indonesian', 41, 14, 'Ketika para rasul datang kepada mereka dari depan dan belakang mereka (dengan menyerukan): "Janganlah kamu menyembah selain Allah". Mereka menjawab: "Kalau Tuhan kami menghendaki tentu Dia akan menurunkan malaikat-malaikat-Nya, maka sesungguhnya kami kafir kepada wahyu yang kamu diutus membawanya".'),
  ('id.indonesian', 41, 15, 'Adapun kaum \'Aad maka mereka menyombongkan diri di muka bumi tanpa alasan yang benar dan berkata: "Siapakah yang lebih besar kekuatannya dari kami?" Dan apakah mereka itu tidak memperhatikan bahwa Allah Yang menciptakan mereka adalah lebih besar kekuatan-Nya daripada mereka? Dan adalah mereka mengingkari tanda-tanda (kekuatan) Kami.'),
  ('id.indonesian', 41, 16, 'Maka Kami meniupkan angin yang amat gemuruh kepada mereka dalam beberapa hari yang sial, karena Kami hendak merasakan kepada mereka itu siksaan yang menghinakan dalam kehidupan dunia. Dan Sesungguhnya siksa akhirat lebih menghinakan sedang mereka tidak diberi pertolongan.'),
  ('id.indonesian', 41, 17, 'Dan adapun kaum Tsamud, maka mereka telah Kami beri petunjuk tetapi mereka lebih menyukai buta (kesesatan) daripada petunjuk, maka mereka disambar petir azab yang menghinakan disebabkan apa yang telah mereka kerjakan.'),
  ('id.indonesian', 41, 18, 'Dan Kami selamatkan orang-orang yang beriman dan mereka adalah orang-orang yang bertakwa.'),
  ('id.indonesian', 41, 19, 'Dan (ingatlah) hari (ketika) musuh-musuh Allah di giring ke dalam neraka, lalu mereka dikumpulkan semuanya.'),
  ('id.indonesian', 41, 20, 'Sehingga apabila mereka sampai ke neraka, pendengaran, penglihatan dan kulit mereka menjadi saksi terhadap mereka tentang apa yang telah mereka kerjakan.'),
  ('id.indonesian', 41, 21, 'Dan mereka berkata kepada kulit mereka: "Mengapa kamu menjadi saksi terhadap kami?" Kulit mereka menjawab: "Allah yang menjadikan segala sesuatu pandai berkata telah menjadikan kami pandai (pula) berkata, dan Dialah yang menciptakan kamu pada kali pertama dan hanya kepada-Nya lah kamu dikembalikan".'),
  ('id.indonesian', 41, 22, 'Kamu sekali-sekali tidak dapat bersembunyi dari kesaksian pendengaran, penglihatan dan kulitmu kepadamu bahkan kamu mengira bahwa Allah tidak mengetahui kebanyakan dari apa yang kamu kerjakan.'),
  ('id.indonesian', 41, 23, 'Dan yang demikian itu adalah prasangkamu yang telah kamu sangka kepada Tuhanmu, Dia telah membinasakan kamu, maka jadilah kamu termasuk orang-orang yang merugi.'),
  ('id.indonesian', 41, 24, 'Jika mereka bersabar (menderita azab) maka nerakalah tempat diam mereka dan jika mereka mengemukakan alasan-alasan, maka tidaklah mereka termasuk orang-orang yang diterima alasannya.'),
  ('id.indonesian', 41, 25, 'Dan Kami tetapkan bagi mereka teman-teman yang menjadikan mereka memandang bagus apa yang ada di hadapan dan di belakang mereka dan tetaplah atas mereka keputusan azab pada umat-umat yang terdahulu sebelum mereka dari jinn dan manusia, sesungguhnya mereka adalah orang-orang yang merugi.'),
  ('id.indonesian', 41, 26, 'Dan orang-orang yang kafir berkata: "Janganlah kamu mendengar dengan sungguh-sungguh akan Al Quran ini dan buatlah hiruk-pikuk terhadapnya, supaya kamu dapat mengalahkan mereka".'),
  ('id.indonesian', 41, 27, 'Maka sesungguhnya Kami akan merasakan azab yang keras kepada orang-orang kafir dan Kami akan memberi balasan kepada mereka dengan seburuk-buruk pembalasan bagi apa yang telah mereka kerjakan.'),
  ('id.indonesian', 41, 28, 'Demikianlah balasan terhadap musuh-musuh Allah, (yaitu) neraka; mereka mendapat tempat tinggal yang kekal di dalamnya sebagai balasan atas keingkaran mereka terhadap ayat-ayat Kami.'),
  ('id.indonesian', 41, 29, 'Dan orang-orang kafir berkata: "Ya Rabb kami perlihatkanlah kepada kami dua jenis orang yang telah menyesatkan kami (yaitu) sebagian dari jinn dan manusia agar kami letakkan keduanya di bawah telapak kaki kami supaya kedua jenis itu menjadi orang-orang yang hina".'),
  ('id.indonesian', 41, 30, 'Sesungguhnya orang-orang yang mengatakan: "Tuhan kami ialah Allah" kemudian mereka meneguhkan pendirian mereka, maka malaikat akan turun kepada mereka dengan mengatakan: "Janganlah kamu takut dan janganlah merasa sedih; dan gembirakanlah mereka dengan jannah yang telah dijanjikan Allah kepadamu".'),
  ('id.indonesian', 41, 31, 'Kamilah pelindung-pelindungmu dalam kehidupan dunia dan akhirat; di dalamnya kamu memperoleh apa yang kamu inginkan dan memperoleh (pula) di dalamnya apa yang kamu minta.'),
  ('id.indonesian', 41, 32, 'Sebagai hidangan (bagimu) dari Tuhan Yang Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 41, 33, 'Siapakah yang lebih baik perkataannya daripada orang yang menyeru kepada Allah, mengerjakan amal yang saleh, dan berkata: "Sesungguhnya aku termasuk orang-orang yang menyerah diri?"'),
  ('id.indonesian', 41, 34, 'Dan tidaklah sama kebaikan dan kejahatan. Tolaklah (kejahatan itu) dengan cara yang lebih baik, maka tiba-tiba orang yang antaramu dan antara dia ada permusuhan seolah-olah telah menjadi teman yang sangat setia.'),
  ('id.indonesian', 41, 35, 'Sifat-sifat yang baik itu tidak dianugerahkan melainkan kepada orang-orang yang sabar dan tidak dianugerahkan melainkan kepada orang-orang yang mempunyai keuntungan yang besar.'),
  ('id.indonesian', 41, 36, 'Dan jika syetan mengganggumu dengan suatu gangguan, maka mohonlah perlindungan kepada Allah. Sesungguhnya Dialah yang Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 41, 37, 'Dan di antara tanda-tanda kekuasaan-Nya ialah malam, siang, matahari dan bulan. Janganlah sembah matahari maupun bulan, tapi sembahlah Allah Yang menciptakannya, Jika Ialah yang kamu hendak sembah.'),
  ('id.indonesian', 41, 38, 'Jika mereka menyombongkan diri, maka mereka (malaikat) yang di sisi Tuhanmu bertasbih kepada-Nya di malam dan siang hari, sedang mereka tidak jemu-jemu.'),
  ('id.indonesian', 41, 39, 'Dan di antara tanda-tanda-Nya (Ialah) bahwa kau lihat bumi kering dan gersang, maka apabila Kami turunkan air di atasnya, niscaya ia bergerak dan subur. Sesungguhnya Tuhan Yang menghidupkannya, Pastilah dapat menghidupkan yang mati. Sesungguhnya Dia Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 41, 40, 'Sesungguhnya orang-orang yang mengingkari ayat-ayat Kami, mereka tidak tersembunyi dari Kami. Maka apakah orang-orang yang dilemparkan ke dalam neraka lebih baik, ataukah orang-orang yang datang dengan aman sentosa pada hari Kiamat? Perbuatlah apa yang kamu kehendaki; Sesungguhnya Dia Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 41, 41, 'Sesungguhnya orang-orang yang mengingkari Al Quran ketika Al Quran itu datang kepada mereka, (mereka itu pasti akan celaka), dan sesungguhnya Al Quran itu adalah kitab yang mulia.'),
  ('id.indonesian', 41, 42, 'Yang tidak datang kepadanya (Al Quran) kebatilan baik dari depan maupun dari belakangnya, yang diturunkan dari Rabb Yang Maha Bijaksana lagi Maha Terpuji.'),
  ('id.indonesian', 41, 43, 'Tidaklah ada yang dikatakan (oleh orang-orang kafir) kepadamu itu selain apa yang sesungguhnya telah dikatakan kepada rasul-rasul sebelum kamu. Sesungguhnya Rabb-mu benar-benar mempunyai ampunan dan hukuman yang pedih.'),
  ('id.indonesian', 41, 44, 'Dan jikalau Kami jadikan Al Quran itu suatu bacaan dalam bahasa selain Arab, tentulah mereka mengatakan: "Mengapa tidak dijelaskan ayat-ayatnya?" Apakah (patut Al Quran) dalam bahasa asing sedang (rasul adalah orang) Arab? Katakanlah: "Al Quran itu adalah petunjuk dan penawar bagi orang-orang mukmin. Dan orang-orang yang tidak beriman pada telinga mereka ada sumbatan, sedang Al Quran itu suatu kegelapan bagi mereka. Mereka itu adalah (seperti) yang dipanggil dari tempat yang jauh".'),
  ('id.indonesian', 41, 45, 'Dan sesungguhnya telah Kami berikan kepada Musa Taurat lalu diperselisihkan tentang Taurat itu. Kalau tidak ada keputusan yang telah terdahulu dari Rabb-mu, tentulah orang-orang kafir itu sudah dibinasakan. Dan Sesungguhnya mereka terhadap Al Quran benar-benar dalam keragu-raguan yang membingungkan.'),
  ('id.indonesian', 41, 46, 'Barangsiapa yang mengerjakan amal yang saleh maka (pahalanya) untuk dirinya sendiri dan barangsiapa mengerjakan perbuatan jahat, maka (dosanya) untuk dirinya sendiri; dan sekali-kali tidaklah Rabb-mu menganiaya hamba-hamba-Nya.'),
  ('id.indonesian', 41, 47, 'Kepada-Nya-lah dikembalikan pengetahuan tentang hari Kiamat. Dan tidak ada buah-buahan keluar dari kelopaknya dan tidak seorang perempuanpun mengandung dan tidak (pula) melahirkan, melainkan dengan sepengetahuan-Nya. Pada hari Tuhan memanggil mereka: "Dimanakah sekutu-sekutu-Ku itu?", mereka menjawab: "Kami nyatakan kepada Engkau bahwa tidak ada seorangpun di antara kami yang memberi kesaksian (bahwa Engkau punya sekutu)".'),
  ('id.indonesian', 41, 48, 'Dan hilang lenyaplah dari mereka apa yang selalu mereka sembah dahulu, dan mereka yakin bahwa tidak ada bagi mereka satu jalan keluarpun.'),
  ('id.indonesian', 41, 49, 'Manusia tidak jemu memohon kebaikan, dan jika mereka ditimpa malapetaka dia menjadi putus asa lagi putus harapan.'),
  ('id.indonesian', 41, 50, 'Dan jika Kami merasakan kepadanya sesuatu rahmat dari Kami sesudah dia ditimpa kesusahan, pastilah dia berkata: "Ini adalah hakku, dan aku tidak yakin bahwa hari Kiamat itu akan datang. Dan jika aku dikembalikan kepada Tuhanku maka sesungguhnya aku akan memperoleh kebaikan pada sisi-Nya". Maka Kami benar-benar akan memberitakan kepada orang-orang kafir apa yang telah mereka kerjakan dan akan Kami rasakan kepada mereka azab yang keras.'),
  ('id.indonesian', 41, 51, 'Dan apabila Kami memberikan nikmat kepada manusia, ia berpaling dan menjauhkan diri; tetapi apabila ia ditimpa malapetaka, maka ia banyak berdoa.'),
  ('id.indonesian', 41, 52, 'Katakanlah: "Bagaimana pendapatmu jika (Al Quran) itu datang dari sisi Allah, kemudian kamu mengingkarinya. Siapakah yang lebih sesat daripada orang yang selalu berada dalam penyimpangan yang jauh?"'),
  ('id.indonesian', 41, 53, 'Kami akan memperlihatkan kepada mereka tanda-tanda (kekuasaan) Kami di segala wilayah bumi dan pada diri mereka sendiri, hingga jelas bagi mereka bahwa Al Quran itu adalah benar. Tiadakah cukup bahwa sesungguhnya Tuhanmu menjadi saksi atas segala sesuatu?'),
  ('id.indonesian', 41, 54, 'Ingatlah bahwa sesungguhnya mereka adalah dalam keraguan tentang pertemuan dengan Tuhan mereka. Ingatlah bahwa sesungguhnya Dia Maha Meliputi segala sesuatu.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 42, 1, 'Ha, Meem.'),
  ('en.sahih', 42, 2, '\'Ayn, Seen, Qaf.'),
  ('en.sahih', 42, 3, 'Thus has He revealed to you, [O Muhammad], and to those before you - Allah, the Exalted in Might, the Wise.'),
  ('en.sahih', 42, 4, 'To Him belongs whatever is in the heavens and whatever is in the earth, and He is the Most High, the Most Great.'),
  ('en.sahih', 42, 5, 'The heavens almost break from above them, and the angels exalt [Allah] with praise of their Lord and ask forgiveness for those on earth. Unquestionably, it is Allah who is the Forgiving, the Merciful.'),
  ('en.sahih', 42, 6, 'And those who take as allies other than Him - Allah is [yet] Guardian over them; and you, [O Muhammad], are not over them a manager.'),
  ('en.sahih', 42, 7, 'And thus We have revealed to you an Arabic Qur\'an that you may warn the Mother of Cities [Makkah] and those around it and warn of the Day of Assembly, about which there is no doubt. A party will be in Paradise and a party in the Blaze.'),
  ('en.sahih', 42, 8, 'And if Allah willed, He could have made them [of] one religion, but He admits whom He wills into His mercy. And the wrongdoers have not any protector or helper.'),
  ('en.sahih', 42, 9, 'Or have they taken protectors [or allies] besides him? But Allah - He is the Protector, and He gives life to the dead, and He is over all things competent.'),
  ('en.sahih', 42, 10, 'And in anything over which you disagree - its ruling is [to be referred] to Allah. [Say], "That is Allah, my Lord; upon Him I have relied, and to Him I turn back."'),
  ('en.sahih', 42, 11, '[He is] Creator of the heavens and the earth. He has made for you from yourselves, mates, and among the cattle, mates; He multiplies you thereby. There is nothing like unto Him, and He is the Hearing, the Seeing.'),
  ('en.sahih', 42, 12, 'To Him belong the keys of the heavens and the earth. He extends provision for whom He wills and restricts [it]. Indeed He is, of all things, Knowing.'),
  ('en.sahih', 42, 13, 'He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muhammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allah is that to which you invite them. Allah chooses for Himself whom He wills and guides to Himself whoever turns back [to Him].'),
  ('en.sahih', 42, 14, 'And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt.'),
  ('en.sahih', 42, 15, 'So to that [religion of Allah] invite, [O Muhammad], and remain on a right course as you are commanded and do not follow their inclinations but say, "I have believed in what Allah has revealed of the Qur\'an, and I have been commanded to do justice among you. Allah is our Lord and your Lord. For us are our deeds, and for you your deeds. There is no [need for] argument between us and you. Allah will bring us together, and to Him is the [final] destination."'),
  ('en.sahih', 42, 16, 'And those who argue concerning Allah after He has been responded to - their argument is invalid with their Lord, and upon them is [His] wrath, and for them is a severe punishment.'),
  ('en.sahih', 42, 17, 'It is Allah who has sent down the Book in truth and [also] the balance. And what will make you perceive? Perhaps the Hour is near.'),
  ('en.sahih', 42, 18, 'Those who do not believe in it are impatient for it, but those who believe are fearful of it and know that it is the truth. Unquestionably, those who dispute concerning the Hour are in extreme error.'),
  ('en.sahih', 42, 19, 'Allah is Subtle with His servants; He gives provisions to whom He wills. And He is the Powerful, the Exalted in Might.'),
  ('en.sahih', 42, 20, 'Whoever desires the harvest of the Hereafter - We increase for him in his harvest. And whoever desires the harvest of this world - We give him thereof, but there is not for him in the Hereafter any share.'),
  ('en.sahih', 42, 21, 'Or have they other deities who have ordained for them a religion to which Allah has not consented? But if not for the decisive word, it would have been concluded between them. And indeed, the wrongdoers will have a painful punishment.'),
  ('en.sahih', 42, 22, 'You will see the wrongdoers fearful of what they have earned, and it will [certainly] befall them. And those who have believed and done righteous deeds will be in lush regions of the gardens [in Paradise] having whatever they will in the presence of their Lord. That is what is the great bounty.'),
  ('en.sahih', 42, 23, 'It is that of which Allah gives good tidings to His servants who believe and do righteous deeds. Say, [O Muhammad], "I do not ask you for this message any payment [but] only good will through kinship." And whoever commits a good deed - We will increase for him good therein. Indeed, Allah is Forgiving and Appreciative.'),
  ('en.sahih', 42, 24, 'Or do they say, "He has invented about Allah a lie"? But if Allah willed, He could seal over your heart. And Allah eliminates falsehood and establishes the truth by His words. Indeed, He is Knowing of that within the breasts.'),
  ('en.sahih', 42, 25, 'And it is He who accepts repentance from his servants and pardons misdeeds, and He knows what you do.'),
  ('en.sahih', 42, 26, 'And He answers [the supplication of] those who have believed and done righteous deeds and increases [for] them from His bounty. But the disbelievers will have a severe punishment.'),
  ('en.sahih', 42, 27, 'And if Allah had extended [excessively] provision for His servants, they would have committed tyranny throughout the earth. But He sends [it] down in an amount which He wills. Indeed He is, of His servants, Acquainted and Seeing.'),
  ('en.sahih', 42, 28, 'And it is He who sends down the rain after they had despaired and spreads His mercy. And He is the Protector, the Praiseworthy.'),
  ('en.sahih', 42, 29, 'And of his signs is the creation of the heavens and earth and what He has dispersed throughout them of creatures. And He, for gathering them when He wills, is competent.'),
  ('en.sahih', 42, 30, 'And whatever strikes you of disaster - it is for what your hands have earned; but He pardons much.'),
  ('en.sahih', 42, 31, 'And you will not cause failure [to Allah] upon the earth. And you have not besides Allah any protector or helper.'),
  ('en.sahih', 42, 32, 'And of His signs are the ships in the sea, like mountains.'),
  ('en.sahih', 42, 33, 'If He willed, He could still the wind, and they would remain motionless on its surface. Indeed in that are signs for everyone patient and grateful.'),
  ('en.sahih', 42, 34, 'Or He could destroy them for what they earned; but He pardons much.'),
  ('en.sahih', 42, 35, 'And [that is so] those who dispute concerning Our signs may know that for them there is no place of escape.'),
  ('en.sahih', 42, 36, 'So whatever thing you have been given - it is but [for] enjoyment of the worldly life. But what is with Allah is better and more lasting for those who have believed and upon their Lord rely'),
  ('en.sahih', 42, 37, 'And those who avoid the major sins and immoralities, and when they are angry, they forgive,'),
  ('en.sahih', 42, 38, 'And those who have responded to their lord and established prayer and whose affair is [determined by] consultation among themselves, and from what We have provided them, they spend.'),
  ('en.sahih', 42, 39, 'And those who, when tyranny strikes them, they defend themselves,'),
  ('en.sahih', 42, 40, 'And the retribution for an evil act is an evil one like it, but whoever pardons and makes reconciliation - his reward is [due] from Allah. Indeed, He does not like wrongdoers.'),
  ('en.sahih', 42, 41, 'And whoever avenges himself after having been wronged - those have not upon them any cause [for blame].'),
  ('en.sahih', 42, 42, 'The cause is only against the ones who wrong the people and tyrannize upon the earth without right. Those will have a painful punishment.'),
  ('en.sahih', 42, 43, 'And whoever is patient and forgives - indeed, that is of the matters [requiring] determination.'),
  ('en.sahih', 42, 44, 'And he whom Allah sends astray - for him there is no protector beyond Him. And you will see the wrongdoers, when they see the punishment, saying, "Is there for return [to the former world] any way?"'),
  ('en.sahih', 42, 45, 'And you will see them being exposed to the Fire, humbled from humiliation, looking from [behind] a covert glance. And those who had believed will say, "Indeed, the [true] losers are the ones who lost themselves and their families on the Day of Resurrection. Unquestionably, the wrongdoers are in an enduring punishment."'),
  ('en.sahih', 42, 46, 'And there will not be for them any allies to aid them other than Allah. And whoever Allah sends astray - for him there is no way.'),
  ('en.sahih', 42, 47, 'Respond to your Lord before a Day comes from Allah of which there is no repelling. No refuge will you have that day, nor for you will there be any denial.'),
  ('en.sahih', 42, 48, 'But if they turn away - then We have not sent you, [O Muhammad], over them as a guardian; upon you is only [the duty of] notification. And indeed, when We let man taste mercy from us, he rejoices in it; but if evil afflicts him for what his hands have put forth, then indeed, man is ungrateful.'),
  ('en.sahih', 42, 49, 'To Allah belongs the dominion of the heavens and the earth; He creates what he wills. He gives to whom He wills female [children], and He gives to whom He wills males.'),
  ('en.sahih', 42, 50, 'Or He makes them [both] males and females, and He renders whom He wills barren. Indeed, He is Knowing and Competent.'),
  ('en.sahih', 42, 51, 'And it is not for any human being that Allah should speak to him except by revelation or from behind a partition or that He sends a messenger to reveal, by His permission, what He wills. Indeed, He is Most High and Wise.'),
  ('en.sahih', 42, 52, 'And thus We have revealed to you an inspiration of Our command. You did not know what is the Book or [what is] faith, but We have made it a light by which We guide whom We will of Our servants. And indeed, [O Muhammad], you guide to a straight path -'),
  ('en.sahih', 42, 53, 'The path of Allah, to whom belongs whatever is in the heavens and whatever is on the earth. Unquestionably, to Allah do [all] matters evolve.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 42, 1, 'হা-মীম।'),
  ('bn.bengali', 42, 2, 'আইন, সীন ক্বা-ফ।'),
  ('bn.bengali', 42, 3, 'এমনিভাবে পরাক্রমশালী, প্রজ্ঞাময় আল্লাহ আপনার প্রতি ও আপনার পূর্ববর্তীদের প্রতি ওহী প্রেরণ করেন।'),
  ('bn.bengali', 42, 4, 'নভোমন্ডলে যা কিছু আছে এবং ভূমন্ডলে যা কিছু আছে, সমস্তই তাঁর। তিনি সমুন্নত, মহান।'),
  ('bn.bengali', 42, 5, 'আকাশ উপর থেকে ফেটে পড়ার উপক্রম হয় আর তখন ফেরেশতাগণ তাদের পালনকর্তার প্রশংসাসহ পবিত্রতা বর্ণনা করে এবং পৃথিবীবাসীদের জন্যে ক্ষমা প্রার্থনা করে। শুনে রাখ, আল্লাহই ক্ষমাশীল, পরম করুনাময়।'),
  ('bn.bengali', 42, 6, 'যারা আল্লাহ ব্যতীত অপরকে অভিভাবক হিসাবে গ্রহণ করে, আল্লাহ তাদের প্রতি লক্ষ্য রাখেন। আপনার উপর নয় তাদের দায়-দায়িত্ব।'),
  ('bn.bengali', 42, 7, 'এমনি ভাবে আমি আপনার প্রতি আরবী ভাষায় কোরআন নাযিল করেছি, যাতে আপনি মক্কা ও তার আশ-পাশের লোকদের সতর্ক করেন এবং সতর্ক করেন সমাবেশের দিন সম্পর্কে, যাতে কোন সন্দেহ নেই। একদল জান্নাতে এবং একদল জাহান্নামে প্রবেশ করবে।'),
  ('bn.bengali', 42, 8, 'আল্লাহ ইচ্ছা করলে সমস্ত লোককে এক দলে পরিণত করতে পারেন। কিন্তু তিনি যাকে ইচ্ছা স্বীয় রহমতে দাখিল করেন। আর যালেমদের কোন অভিভাবক ও সাহায্যকারী নেই।'),
  ('bn.bengali', 42, 9, 'তারা কি আল্লাহ ব্যতীত অপরকে অভিভাবক স্থির করেছে? পরন্তু আল্লাহই তো একমাত্র অভিভাবক। তিনি মৃতদেরকে জীবিত করেন। তিনি সর্ববিষয়ে ক্ষমতাবান।'),
  ('bn.bengali', 42, 10, 'তোমরা যে বিষয়েই মতভেদ কর, তার ফয়সালা আল্লাহর কাছে সোপর্দ। ইনিই আল্লাহ আমার পালনকর্তা আমি তাঁরই উপর নির্ভর করি এবং তাঁরই অভিমুখী হই।'),
  ('bn.bengali', 42, 11, 'তিনি নভোমন্ডল ও ভূমন্ডলের স্রষ্টা। তিনি তোমাদের মধ্য থেকে তোমাদের জন্যে যুগল সৃষ্টি করেছেন এবং চতুস্পদ জন্তুদের মধ্য থেকে জোড়া সৃষ্টি করেছেন। এভাবে তিনি তোমাদের বংশ বিস্তার করেন। কোন কিছুই তাঁর অনুরূপ নয়। তিনি সব শুনেন, সব দেখেন।'),
  ('bn.bengali', 42, 12, 'আকাশ ও পৃথিবীর চাবি তাঁর কাছে। তিনি যার জন্যে ইচ্ছা রিযিক বৃদ্ধি করেন এবং পরিমিত করেন। তিনি সর্ব বিষয়ে জ্ঞানী।'),
  ('bn.bengali', 42, 13, 'তিনি তোমাদের জন্যে দ্বীনের ক্ষেত্রে সে পথই নিধারিত করেছেন, যার আদেশ দিয়েছিলেন নূহকে, যা আমি প্রত্যাদেশ করেছি আপনার প্রতি এবং যার আদেশ দিয়েছিলাম ইব্রাহীম, মূসা ও ঈসাকে এই মর্মে যে, তোমরা দ্বীনকে প্রতিষ্ঠিত কর এবং তাতে অনৈক্য সৃষ্টি করো না। আপনি মূশরেকদেরকে যে বিষয়ের প্রতি আমন্ত্রণ জানান, তা তাদের কাছে দুঃসাধ্য বলে মনে হয়। আল্লাহ যাকে ইচ্ছা মনোনীত করেন এবং যে তাঁর অভিমুখী হয়, তাকে পথ প্রদর্শন করেন।'),
  ('bn.bengali', 42, 14, 'তাদের কাছে জ্ঞান আসার পরই তারা পারস্পরিক বিভেদের কারণে মতভেদ করেছে। যদি আপনার পালনকর্তার পক্ষ থেকে নির্দিষ্ট সময় পর্যন্ত অবকাশের পূর্ব সিদ্ধান্ত না থাকত, তবে তাদের ফয়সালা হয়ে যেত। তাদের পর যারা কিতাব প্রাপ্ত হয়েছে, তারা অস্বস্তিকর সন্দেহে পতিত রয়েছে।'),
  ('bn.bengali', 42, 15, 'সুতরাং আপনি এর প্রতিই দাওয়াত দিন এবং হুকুম অনুযায়ী অবিচল থাকুন; আপনি তাদের খেয়ালখুশীর অনুসরণ করবেন না। বলুন, আল্লাহ যে কিতাব নাযিল করেছেন, আমি তাতে বিশ্বাস স্থাপন করেছি। আমি তোমাদের মধ্যে ন্যায় বিচার করতে আদিষ্ট হয়েছি। আল্লাহ আমাদের পালনকর্তা ও তোমাদের পালনকর্তা। আমাদের জন্যে আমাদের কর্ম এবং তোমাদের জন্যে তোমাদের কর্ম। আমাদের মধ্যে ও তোমাদের মধ্যে বিবাদ নেই। আল্লাহ আমাদেরকে সমবেত করবেন এবং তাঁরই দিকে প্রত্যাবর্তণ হবে।'),
  ('bn.bengali', 42, 16, 'আল্লাহর দ্বীন মেনে নেয়ার পর যারা সে সম্পর্কে বিতর্কে প্রবৃত্ত হয়, তাদের বিতর্ক তাদের পালনকর্তার কাছে বাতিল, তাদের প্রতি আল্লাহর গযব এবং তাদের জন্যে রয়েছে কঠোর আযাব।'),
  ('bn.bengali', 42, 17, 'আল্লাহই সত্যসহ কিতাব ও ইনসাফের মানদন্ড নাযিল করেছেন। আপনি কি জানেন, সম্ভবতঃ কেয়ামত নিকটবর্তী।'),
  ('bn.bengali', 42, 18, 'যারা তাতে বিশ্বাস করে না তারা তাকে তড়িৎ কামনা করে। আর যারা বিশ্বাস করে, তারা তাকে ভয় করে এবং জানে যে, তা সত্য। জেনে রাখ, যারা কেয়ামত সম্পর্কে বিতর্ক করে, তারা দূরবর্তী পথ ভ্রষ্টতায় লিপ্ত রয়েছে।'),
  ('bn.bengali', 42, 19, 'আল্লাহ তাঁর বান্দাদের প্রতি দয়ালু। তিনি যাকে ইচ্ছা, রিযিক দান করেন। তিনি প্রবল, পরাক্রমশালী।'),
  ('bn.bengali', 42, 20, 'যে কেউ পরকালের ফসল কামনা করে, আমি তার জন্যে সেই ফসল বাড়িয়ে দেই। আর যে ইহকালের ফসল কামনা করে, আমি তাকে তার কিছু দিয়ে দেই এবং পরকালে তার কোন অংশ থাকবে না।'),
  ('bn.bengali', 42, 21, 'তাদের কি এমন শরীক দেবতা আছে, যারা তাদের জন্যে সে ধর্ম সিদ্ধ করেছে, যার অনুমতি আল্লাহ দেননি ? যদি চুড়ান্ত সিন্ধান্ত না থাকত, তবে তাদের ব্যাপারে ফয়সালা হয়ে যেত। নিশ্চয় যালেমদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 42, 22, 'আপনি কাফেরদেরকে তাদের কৃতকর্মের জন্যে ভীতসন্ত্রস্ত দেখবেন। তাদের কর্মের শাস্তি অবশ্যই তাদের উপর পতিত হবে। আর যারা মুমিন ও সৎকর্মী, তারা জান্নাতের উদ্যানে থাকবে। তারা যা চাইবে, তাই তাদের জন্যে তাদের পালনকর্তার কাছে রয়েছে। এটাই বড় পুরস্কার।'),
  ('bn.bengali', 42, 23, 'এরই সুসংবাদ দেন আল্লাহ তার সেসব বান্দাকে, যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে। বলুন, আমি আমার দাওয়াতের জন্যে তোমাদের কাছে কেবল আত্নীয়তাজনিত সৌহার্দ চাই। যে কেউ উত্তম কাজ করে, আমি তার জন্যে তাতে পুণ্য বাড়িয়ে দেই। নিশ্চয় আল্লাহ ক্ষমাকারী, গুণগ্রাহী।'),
  ('bn.bengali', 42, 24, 'নাকি তারা একথা বলে যে, তিনি আল্লাহর বিরুদ্ধে মিথ্যা রটনা করেছেন? আল্লাহ ইচ্ছা করলে আপনার অন্তরে মোহর এঁটে দিতেন। বস্তুতঃ তিনি মিথ্যাকে মিটিয়ে দেন এবং নিজ বাক্য দ্বারা সত্যকে প্রতিষ্ঠিত করেন। নিশ্চয় তিনি অন্তর্নিহিত বিষয় সম্পর্কে সর্বিশেষ জ্ঞাত।'),
  ('bn.bengali', 42, 25, 'তিনি তাঁর বান্দাদের তওবা কবুল করেন পাপসমূহ মার্জনা করেন এবং তোমাদের কৃত বিষয় সম্পর্কে অবগত রয়েছেন।'),
  ('bn.bengali', 42, 26, 'তিনি মুমিন ও সৎকর্মীদের দোয়া শোনেন এবং তাদের প্রতি স্বীয় অনুগ্রহ বাড়িয়ে দেন। আর কাফেরদের জন্যে রয়েছে কঠোর শাস্তি।'),
  ('bn.bengali', 42, 27, 'যদি আল্লাহ তাঁর সকল বান্দাকে প্রচুর রিযিক দিতেন, তবে তারা পৃথিবীতে বিপর্যয় সৃষ্টি করত। কিন্তু তিনি যে পরিমাণ ইচ্ছা সে পরিমাণ নাযিল করেন। নিশ্চয় তিনি তাঁর বান্দাদের খবর রাখেন ও সবকিছু দেখেন।'),
  ('bn.bengali', 42, 28, 'মানুষ নিরাশ হয়ে যাওয়ার পরে তিনি বৃষ্টি বর্ষণ করেন এবং স্বীয় রহমত ছড়িয়ে দেন। তিনিই কার্যনির্বাহী, প্রশংসিত।'),
  ('bn.bengali', 42, 29, 'তাঁর এক নিদর্শন নভোমন্ডল ও ভূমন্ডলের সৃষ্টি এবং এতদুভয়ের মধ্যে তিনি যেসব জীব-জন্তু ছড়িয়ে দিয়েছেন। তিনি যখন ইচ্ছা এগুলোকে একত্রিত করতে সক্ষম।'),
  ('bn.bengali', 42, 30, 'তোমাদের উপর যেসব বিপদ-আপদ পতিত হয়, তা তোমাদের কর্মেরই ফল এবং তিনি তোমাদের অনেক গোনাহ ক্ষমা করে দেন।'),
  ('bn.bengali', 42, 31, 'তোমরা পৃথিবীতে পলায়ন করে আল্লাহকে অক্ষম করতে পার না এবং আল্লাহ ব্যতীত তোমাদের কোন কার্যনির্বাহী নেই, সাহায্যকারীও নেই।'),
  ('bn.bengali', 42, 32, 'সমুদ্রে ভাসমান পর্বতসম জাহাজসমূহ তাঁর অন্যতম নিদর্শন।'),
  ('bn.bengali', 42, 33, 'তিনি ইচ্ছা করলে বাতাসকে থামিয়ে দেন। তখন জাহাজসমূহ সমুদ্রপৃষ্ঠে নিশ্চল হয়ে পড়ে যেন পাহাড়। নিশ্চয় এতে প্রত্যেক সবরকারী, কৃতজ্ঞের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 42, 34, 'অথবা তাদের কৃতকর্মের জন্যে সেগুলোকে ধ্বংস করে দেন এবং অনেককে ক্ষমাও করে দেন।'),
  ('bn.bengali', 42, 35, 'এবং যারা আমার ক্ষমতা সম্পর্কে বিতর্ক করে, তারা যেন জানে যে, তাদের কোন পলায়নের জায়গা নেই।'),
  ('bn.bengali', 42, 36, 'অতএব, তোমাদেরকে যা দেয়া হয়েছে তা পার্থিব জীবনের ভোগ মাত্র। আর আল্লাহর কাছে যা রয়েছে, তা উৎকৃষ্ট ও স্থায়ী তাদের জন্যে যারা বিশ্বাস স্থাপন করে ও তাদের পালনকর্তার উপর ভরসা করে।'),
  ('bn.bengali', 42, 37, 'যারা বড় গোনাহ ও অশ্লীল কার্য থেকে বেঁচে থাকে এবং ক্রোধাম্বিত হয়েও ক্ষমা করে,'),
  ('bn.bengali', 42, 38, 'যারা তাদের পালনকর্তার আদেশ মান্য করে, নামায কায়েম করে; পারস্পরিক পরামর্শক্রমে কাজ করে এবং আমি তাদেরকে যে রিযিক দিয়েছি, তা থেকে ব্যয় করে,'),
  ('bn.bengali', 42, 39, 'যারা আক্রান্ত হলে প্রতিশোধ গ্রহণ করে।'),
  ('bn.bengali', 42, 40, 'আর মন্দের প্রতিফল তো অনুরূপ মন্দই। যে ক্ষমা করে ও আপোষ করে তার পুরস্কার আল্লাহর কাছে রয়েছে; নিশ্চয় তিনি অত্যাচারীদেরকে পছন্দ করেন নাই।'),
  ('bn.bengali', 42, 41, 'নিশ্চয় যে অত্যাচারিত হওয়ার পর প্রতিশোধ গ্রহণ করে, তাদের বিরুদ্ধেও কোন অভিযোগ নেই।'),
  ('bn.bengali', 42, 42, 'অভিযোগ কেবল তাদের বিরুদ্ধে, যারা মানুষের উপর অত্যাচার চালায় এবং পৃথিবীতে অন্যায়ভাবে বিদ্রোহ করে বেড়ায়। তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 42, 43, 'অবশ্যই যে সবর করে ও ক্ষমা করে নিশ্চয় এটা সাহসিকতার কাজ।'),
  ('bn.bengali', 42, 44, 'আল্লাহ যাকে পথ ভ্রষ্ট করেন, তার জন্যে তিনি ব্যতীত কোন কার্যনির্বাহী নেই। পাপাচারীরা যখন আযাব প্রত্যক্ষ করবে, তখন আপনি তাদেরকে দেখবেন যে, তারা বলছে আমাদের ফিরে যাওয়ার কোন উপায় আছে কি?'),
  ('bn.bengali', 42, 45, 'জাহান্নামের সামনে উপস্থিত করার সময় আপনি তাদেরকে দেখবেন, অপমানে অবনত এবং অর্ধ নিমীলিত দৃষ্টিতে তাকায়। মুমিনরা বলবে, কেয়ামতের দিন ক্ষতিগ্রস্ত তারাই, যারা নিজেদের ও তাদের পরিবার-পরিজনের ক্ষতি সাধন করেছে। শুনে রাখ, পাপাচারীরা স্থায়ী আযাবে থাকবে।'),
  ('bn.bengali', 42, 46, 'আল্লাহ তা’আলা ব্যতীত তাদের কোন সাহায্যকারী থাকবে না, যে তাদেরকে সাহায্য করবে। আল্লাহ তা’আলা যাকে পথভ্রষ্ট করেন, তার কোন গতি নেই।'),
  ('bn.bengali', 42, 47, 'আল্লাহ তা’আলার পক্ষ থেকে অবশ্যম্ভাবী দিবস আসার পূর্বে তোমরা তোমাদের পালনকর্তার আদেশ মান্য কর। সেদিন তোমাদের কোন আশ্রয়স্থল থাকবে না এবং তা নিরোধকারী কেউ থাকবে না।'),
  ('bn.bengali', 42, 48, 'যদি তারা মুখ ফিরিয়ে নেয়, তবে আপনাকে আমি তাদের রক্ষক করে পাঠাইনি। আপনার কর্তব্য কেবল প্রচার করা। আমি তাদের রক্ষক করে পাঠাইনি। আপনার কর্তব্য কেবল প্রচার করা। আমি যখন মানুষকে আমার রহমত আস্বাদন করাই, তখন সে উল্লসিত, আর যখন তাদের কৃতকর্মের কারণে তাদের কোন অনিষ্ট ঘটে, তখন মানুষ খুব অকৃতজ্ঞ হয়ে যায়।'),
  ('bn.bengali', 42, 49, 'নভোমন্ডল ও ভূমন্ডলের রাজত্ব আল্লাহ তা’আলারই। তিনি যা ইচ্ছা, সৃষ্টি করেন, যাকে ইচ্ছা কন্যা-সন্তান এবং যাকে ইচ্ছা পুত্র সন্তান দান করেন।'),
  ('bn.bengali', 42, 50, 'অথবা তাদেরকে দান করেন পুত্র ও কন্যা উভয়ই এবং যাকে ইচ্ছা বন্ধ্যা করে দেন। নিশ্চয় তিনি সর্বজ্ঞ, ক্ষমতাশীল।'),
  ('bn.bengali', 42, 51, 'কোন মানুষের জন্য এমন হওয়ার নয় যে, আল্লাহ তার সাথে কথা বলবেন। কিন্তু ওহীর মাধ্যমে অথবা পর্দার অন্তরাল থেকে অথবা তিনি কোন দূত প্রেরণ করবেন, অতঃপর আল্লাহ যা চান, সে তা তাঁর অনুমতিক্রমে পৌঁছে দেবে। নিশ্চয় তিনি সর্বোচ্চ প্রজ্ঞাময়।'),
  ('bn.bengali', 42, 52, 'এমনিভাবে আমি আপনার কাছে এক ফেরেশতা প্রেরণ করেছি আমার আদেশক্রমে। আপনি জানতেন না, কিতাব কি এবং ঈমান কি? কিন্তু আমি একে করেছি নূর, যাদ্দ্বারা আমি আমার বান্দাদের মধ্য থেকে যাকে ইচ্ছা পথ প্রদর্শন করি। নিশ্চয় আপনি সরল পথ প্রদর্শন করেন-'),
  ('bn.bengali', 42, 53, 'আল্লাহর পথ। নভোমন্ডল ও ভূমন্ডল যা কিছু আছে, সব তাঁরই। শুনে রাখ, আল্লাহ তা’আলার কাছেই সব বিষয়ে পৌঁছে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 42, 1, 'Ha. Mim.'),
  ('en.pickthall', 42, 2, 'A\'in. Sin. Qaf.'),
  ('en.pickthall', 42, 3, 'Thus Allah the Mighty, the Knower inspireth thee (Muhammad) as (He inspired) those before thee.'),
  ('en.pickthall', 42, 4, 'Unto Him belongeth all that is in the heavens and all that is in the earth, and He is the Sublime, the Tremendous.'),
  ('en.pickthall', 42, 5, 'Almost might the heavens above be rent asunder while the angels hymn the praise of their Lord and ask forgiveness for those on the earth. Lo! Allah, He is the Forgiver, the Merciful.'),
  ('en.pickthall', 42, 6, 'And as for those who choose protecting friends beside Him, Allah is Warden over them, and thou art in no wise a guardian over them.'),
  ('en.pickthall', 42, 7, 'And thus We have inspired in thee a Lecture in Arabic, that thou mayst warn the mother-town and those around it, and mayst warn of a day of assembling whereof there is no doubt. A host will be in the Garden, and a host of them in the Flame.'),
  ('en.pickthall', 42, 8, 'Had Allah willed, He could have made them one community, but Allah bringeth whom He will into His mercy. And the wrong-doers have no friend nor helper.'),
  ('en.pickthall', 42, 9, 'Or have they chosen protecting friends besides Him? But Allah, He (alone) is the Protecting Friend. He quickeneth the dead, and He is Able to do all things.'),
  ('en.pickthall', 42, 10, 'And in whatsoever ye differ, the verdict therein belongeth to Allah. Such is my Lord, in Whom I put my trust, and unto Whom I turn.'),
  ('en.pickthall', 42, 11, 'The Creator of the heavens and the earth. He hath made for you pairs of yourselves, and of the cattle also pairs, whereby He multiplieth you. Naught is as His likeness; and He is the Hearer, the Seer.'),
  ('en.pickthall', 42, 12, 'His are the keys of the heavens and the earth. He enlargeth providence for whom He will and straiteneth (it for whom He will). Lo! He is Knower of all things.'),
  ('en.pickthall', 42, 13, 'He hath ordained for you that religion which He commended unto Noah, and that which We inspire in thee (Muhammad), and that which We commended unto Abraham and Moses and Jesus, saying: Establish the religion, and be not divided therein. Dreadful for the idolaters is that unto which thou callest them. Allah chooseth for Himself whom He will, and guideth unto Himself him who turneth (toward Him).'),
  ('en.pickthall', 42, 14, 'And they were not divided until after the knowledge came unto them, through rivalry among themselves; and had it not been for a Word that had already gone forth from thy Lord for an appointed term, it surely had been judged between them. And those who were made to inherit the Scripture after them are verily in hopeless doubt concerning it.'),
  ('en.pickthall', 42, 15, 'Unto this, then, summon (O Muhammad). And be thou upright as thou art commanded, and follow not their lusts, but say: I believe in whatever scripture Allah hath sent down, and I am commanded to be just among you. Allah is our Lord and your Lord. Unto us our works and unto you your works; no argument between us and you. Allah will bring us together, and unto Him is the journeying.'),
  ('en.pickthall', 42, 16, 'And those who argue concerning Allah after He hath been acknowledged, their argument hath no weight with their Lord, and wrath is upon them and theirs will be an awful doom.'),
  ('en.pickthall', 42, 17, 'Allah it is Who hath revealed the Scripture with truth, and the Balance. How canst thou know? It may be that the Hour is nigh.'),
  ('en.pickthall', 42, 18, 'Those who believe not therein seek to hasten it, while those who believe are fearful of it and know that it is the Truth. Are not they who dispute, in doubt concerning the Hour, far astray?'),
  ('en.pickthall', 42, 19, 'Allah is gracious unto His slaves. He provideth for whom He will. And He is the Strong, the Mighty.'),
  ('en.pickthall', 42, 20, 'Whoso desireth the harvest of the Hereafter, We give him increase in its harvest. And whoso desireth the harvest of the world, We give him thereof, and he hath no portion in the Hereafter.'),
  ('en.pickthall', 42, 21, 'Or have they partners (of Allah) who have made lawful for them in religion that which Allah allowed not? And but for a decisive word (gone forth already), it would have been judged between them. Lo! for wrong-doers is a painful doom.'),
  ('en.pickthall', 42, 22, 'Thou seest the wrong-doers fearful of that which they have earned, and it will surely befall them, while those who believe and do good works (will be) in flowering meadows of the Gardens, having what they wish from their Lord. This is the great preferment.'),
  ('en.pickthall', 42, 23, 'This it is which Allah announceth unto His bondmen who believe and do good works. Say (O Muhammad, unto mankind): I ask of you no fee therefor, save lovingkindness among kinsfolk. And whoso scoreth a good deed We add unto its good for him. Lo! Allah is Forgiving, Responsive.'),
  ('en.pickthall', 42, 24, 'Or say they: He hath invented a lie concerning Allah? If Allah willed, He could have sealed thy heart (against them). And Allah will wipe out the lie and will vindicate the truth by His words. Lo! He is Aware of what is hidden in the breasts (of men).'),
  ('en.pickthall', 42, 25, 'And He it is Who accepteth repentance from His bondmen, and pardoneth the evil deeds, and knoweth what ye do,'),
  ('en.pickthall', 42, 26, 'And accepteth those who do good works, and giveth increase unto them of His bounty. And as for disbelievers, theirs will be an awful doom.'),
  ('en.pickthall', 42, 27, 'And if Allah were to enlarge the provision for His slaves they would surely rebel in the earth, but He sendeth down by measure as He willeth. Lo! He is Informed, a Seer of His bondmen.'),
  ('en.pickthall', 42, 28, 'And He it is Who sendeth down the saving rain after they have despaired, and spreadeth out His mercy. He is the Protecting Friend, the Praiseworthy.'),
  ('en.pickthall', 42, 29, 'And of His portents is the creation of the heaven and the earth, and of whatever beasts He hath dispersed therein. And He is Able to gather them when He will.'),
  ('en.pickthall', 42, 30, 'Whatever of misfortune striketh you, it is what your right hands have earned. And He forgiveth much.'),
  ('en.pickthall', 42, 31, 'Ye cannot escape in the earth, for beside Allah ye have no protecting friend nor any helper.'),
  ('en.pickthall', 42, 32, 'And of His portents are the ships, like banners on the sea;'),
  ('en.pickthall', 42, 33, 'If He will He calmeth the wind so that they keep still upon its surface - Lo! herein verily are signs for every steadfast grateful (heart). -'),
  ('en.pickthall', 42, 34, 'Or He causeth them to perish on account of that which they have earned - And He forgiveth much -'),
  ('en.pickthall', 42, 35, 'And that those who argue concerning Our revelations may know they have no refuge.'),
  ('en.pickthall', 42, 36, 'Now whatever ye have been given is but a passing comfort for the life of the world, and that which Allah hath is better and more lasting for those who believe and put their trust in their Lord,'),
  ('en.pickthall', 42, 37, 'And those who shun the worst of sins and indecencies and, when they are wroth, forgive,'),
  ('en.pickthall', 42, 38, 'And those who answer the call of their Lord and establish worship, and whose affairs are a matter of counsel, and who spend of what We have bestowed on them,'),
  ('en.pickthall', 42, 39, 'And those who, when great wrong is done to them, defend themselves,'),
  ('en.pickthall', 42, 40, 'The guerdon of an ill-deed is an ill the like thereof. But whosoever pardoneth and amendeth, his wage is the affair of Allah. Lo! He loveth not wrong-doers.'),
  ('en.pickthall', 42, 41, 'And whoso defendeth himself after he hath suffered wrong - for such, there is no way (of blame) against them.'),
  ('en.pickthall', 42, 42, 'The way (of blame) is only against those who oppress mankind, and wrongfully rebel in the earth. For such there is a painful doom.'),
  ('en.pickthall', 42, 43, 'And verily whoso is patient and forgiveth - lo! that, verily, is (of) the steadfast heart of things.'),
  ('en.pickthall', 42, 44, 'He whom Allah sendeth astray, for him there is no protecting friend after Him. And thou (Muhammad) wilt see the evil-doers when they see the doom, (how) they say: Is there any way of return?'),
  ('en.pickthall', 42, 45, 'And thou wilt see them exposed to (the Fire), made humble by disgrace, and looking with veiled eyes. And those who believe will say: Lo! the (eternal) losers are they who lose themselves and their housefolk on the Day of Resurrection. Lo! are not the wrong-doers in perpetual torment?'),
  ('en.pickthall', 42, 46, 'And they will have no protecting friends to help them instead of Allah. He whom Allah sendeth astray, for him there is no road.'),
  ('en.pickthall', 42, 47, 'Answer the call of your Lord before there cometh unto you from Allah a Day which there is no averting. Ye have no refuge on that Day, nor have a ye any (power of) refusal.'),
  ('en.pickthall', 42, 48, 'But if they are averse, We have not sent thee as a warder over them. Thine is only to convey (the message). And lo! when We cause man to taste of mercy from Us he exulteth therefor. And if some evil striketh them because of that which their own hands have sent before, then lo! man is an ingrate.'),
  ('en.pickthall', 42, 49, 'Unto Allah belongeth the Sovereignty of the heavens and the earth. He createth what He will. He bestoweth female (offspring) upon whom He will, and bestoweth male (offspring) upon whom He will;'),
  ('en.pickthall', 42, 50, 'Or He mingleth them, males and females, and He maketh barren whom He will. Lo! He is Knower, Powerful.'),
  ('en.pickthall', 42, 51, 'And it was not (vouchsafed) to any mortal that Allah should speak to him unless (it be) by revelation or from behind a veil, or (that) He sendeth a messenger to reveal what He will by His leave. Lo! He is Exalted, Wise.'),
  ('en.pickthall', 42, 52, 'And thus have We inspired in thee (Muhammad) a Spirit of Our command. Thou knewest not what the Scripture was, nor what the Faith. But We have made it a light whereby We guide whom We will of Our bondmen. And lo! thou verily dost guide unto a right path,'),
  ('en.pickthall', 42, 53, 'The path of Allah, unto Whom belongeth whatsoever is in the heavens and whatsoever is in the earth. Do not all things reach Allah at last?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 42, 1, 'Ha-Mim'),
  ('en.yusufali', 42, 2, '\'Ain. Sin. Qaf.'),
  ('en.yusufali', 42, 3, 'Thus doth (He) send inspiration to thee as (He did) to those before thee,- Allah, Exalted in Power, Full of Wisdom.'),
  ('en.yusufali', 42, 4, 'To Him belongs all that is in the heavens and on earth: and He is Most High, Most Great.'),
  ('en.yusufali', 42, 5, 'The heavens are almost rent asunder from above them (by Him Glory): and the angels celebrate the Praises of their Lord, and pray for forgiveness for (all) beings on earth: Behold! Verily Allah is He, the Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 42, 6, 'And those who take as protectors others besides Him,- Allah doth watch over them; and thou art not the disposer of their affairs.'),
  ('en.yusufali', 42, 7, 'Thus have We sent by inspiration to thee an Arabic Qur\'an: that thou mayest warn the Mother of Cities and all around her,- and warn (them) of the Day of Assembly, of which there is no doubt: (when) some will be in the Garden, and some in the Blazing Fire.'),
  ('en.yusufali', 42, 8, 'If Allah had so willed, He could have made them a single people; but He admits whom He will to His Mercy; and the Wrong-doers will have no protector nor helper.'),
  ('en.yusufali', 42, 9, 'What! Have they taken (for worship) protectors besides Him? But it is Allah,- He is the Protector, and it is He Who gives life to the dead: It is He Who has power over all things,'),
  ('en.yusufali', 42, 10, 'Whatever it be wherein ye differ, the decision thereof is with Allah: such is Allah my Lord: In Him I trust, and to Him I turn.'),
  ('en.yusufali', 42, 11, '(He is) the Creator of the heavens and the earth: He has made for you pairs from among yourselves, and pairs among cattle: by this means does He multiply you: there is nothing whatever like unto Him, and He is the One that hears and sees (all things).'),
  ('en.yusufali', 42, 12, 'To Him belong the keys of the heavens and the earth: He enlarges and restricts. The Sustenance to whom He will: for He knows full well all things.'),
  ('en.yusufali', 42, 13, 'The same religion has He established for you as that which He enjoined on Noah - the which We have sent by inspiration to thee - and that which We enjoined on Abraham, Moses, and Jesus: Namely, that ye should remain steadfast in religion, and make no divisions therein: to those who worship other things than Allah, hard is the (way) to which thou callest them. Allah chooses to Himself those whom He pleases, and guides to Himself those who turn (to Him).'),
  ('en.yusufali', 42, 14, 'And they became divided only after Knowledge reached them,- through selfish envy as between themselves. Had it not been for a Word that went forth before from thy Lord, (tending) to a Term appointed, the matter would have been settled between them: But truly those who have inherited the Book after them are in suspicious (disquieting) doubt concerning it.'),
  ('en.yusufali', 42, 15, 'Now then, for that (reason), call (them to the Faith), and stand steadfast as thou art commanded, nor follow thou their vain desires; but say: "I believe in the Book which Allah has sent down; and I am commanded to judge justly between you. Allah is our Lord and your Lord: for us (is the responsibility for) our deeds, and for you for your deeds. There is no contention between us and you. Allah will bring us together, and to Him is (our) Final Goal.'),
  ('en.yusufali', 42, 16, 'But those who dispute concerning Allah after He has been accepted,- futile is their dispute in the Sight of their Lord: on them will be a Penalty terrible.'),
  ('en.yusufali', 42, 17, 'It is Allah Who has sent down the Book in Truth, and the Balance (by which to weigh conduct). And what will make thee realise that perhaps the Hour is close at hand?'),
  ('en.yusufali', 42, 18, 'Only those wish to hasten it who believe not in it: those who believe hold it in awe, and know that it is the Truth. Behold, verily those that dispute concerning the Hour are far astray.'),
  ('en.yusufali', 42, 19, 'Gracious is Allah to His servants: He gives Sustenance to whom He pleases: and He has power and can carry out His Will.'),
  ('en.yusufali', 42, 20, 'To any that desires the tilth of the Hereafter, We give increase in his tilth, and to any that desires the tilth of this world, We grant somewhat thereof, but he has no share or lot in the Hereafter.'),
  ('en.yusufali', 42, 21, 'What! have they partners (in godhead), who have established for them some religion without the permission of Allah? Had it not been for the Decree of Judgment, the matter would have been decided between them (at once). But verily the Wrong-doers will have a grievous Penalty.'),
  ('en.yusufali', 42, 22, 'Thou wilt see the Wrong-doers in fear on account of what they have earned, and (the burden of) that must (necessarily) fall on them. But those who believe and work righteous deeds will be in the luxuriant meads of the Gardens: they shall have, before their Lord, all that they wish for. That will indeed be the magnificent Bounty (of Allah).'),
  ('en.yusufali', 42, 23, 'That is (the Bounty) whereof Allah gives Glad Tidings to His Servants who believe and do righteous deeds. Say: "No reward do I ask of you for this except the love of those near of kin." And if any one earns any good, We shall give him an increase of good in respect thereof: for Allah is Oft-Forgiving, Most Ready to appreciate (service).'),
  ('en.yusufali', 42, 24, 'What! Do they say, "He has forged a falsehood against Allah"? But if Allah willed, He could seal up thy heart. And Allah blots out Vanity, and proves the Truth by His Words. For He knows well the secrets of all hearts.'),
  ('en.yusufali', 42, 25, 'He is the One that accepts repentance from His Servants and forgives sins: and He knows all that ye do.'),
  ('en.yusufali', 42, 26, 'And He listens to those who believe and do deeds of righteousness, and gives them increase of His Bounty: but for the Unbelievers their is a terrible Penalty.'),
  ('en.yusufali', 42, 27, 'If Allah were to enlarge the provision for His Servants, they would indeed transgress beyond all bounds through the earth; but he sends (it) down in due measure as He pleases. For He is with His Servants Well-acquainted, Watchful.'),
  ('en.yusufali', 42, 28, 'He is the One that sends down rain (even) after (men) have given up all hope, and scatters His Mercy (far and wide). And He is the Protector, Worthy of all Praise.'),
  ('en.yusufali', 42, 29, 'And among His Signs is the creation of the heavens and the earth, and the living creatures that He has scattered through them: and He has power to gather them together when He wills.'),
  ('en.yusufali', 42, 30, 'Whatever misfortune happens to you, is because on the things your hands have wrought, and for many (of them) He grants forgiveness.'),
  ('en.yusufali', 42, 31, 'Nor can ye frustrate (aught), (fleeing) through the earth; nor have ye, besides Allah, any one to protect or to help.'),
  ('en.yusufali', 42, 32, 'And among His Signs are the ships, smooth-running through the ocean, (tall) as mountains.'),
  ('en.yusufali', 42, 33, 'If it be His Will He can still the Wind: then would they become motionless on the back of the (ocean). Verily in this are Signs for everyone who patiently perseveres and is grateful.'),
  ('en.yusufali', 42, 34, 'Or He can cause them to perish because of the (evil) which (the men) have earned; but much doth He forgive.'),
  ('en.yusufali', 42, 35, 'But let those know, who dispute about Our Signs, that there is for them no way of escape.'),
  ('en.yusufali', 42, 36, 'Whatever ye are given (here) is (but) a convenience of this life: but that which is with Allah is better and more lasting: (it is) for those who believe and put their trust in their Lord:'),
  ('en.yusufali', 42, 37, 'Those who avoid the greater crimes and shameful deeds, and, when they are angry even then forgive;'),
  ('en.yusufali', 42, 38, 'Those who hearken to their Lord, and establish regular Prayer; who (conduct) their affairs by mutual Consultation; who spend out of what We bestow on them for Sustenance;'),
  ('en.yusufali', 42, 39, 'And those who, when an oppressive wrong is inflicted on them, (are not cowed but) help and defend themselves.'),
  ('en.yusufali', 42, 40, 'The recompense for an injury is an injury equal thereto (in degree): but if a person forgives and makes reconciliation, his reward is due from Allah: for (Allah) loveth not those who do wrong.'),
  ('en.yusufali', 42, 41, 'But indeed if any do help and defend themselves after a wrong (done) to them, against such there is no cause of blame.'),
  ('en.yusufali', 42, 42, 'The blame is only against those who oppress men and wrong-doing and insolently transgress beyond bounds through the land, defying right and justice: for such there will be a penalty grievous.'),
  ('en.yusufali', 42, 43, 'But indeed if any show patience and forgive, that would truly be an exercise of courageous will and resolution in the conduct of affairs.'),
  ('en.yusufali', 42, 44, 'For any whom Allah leaves astray, there is no protector thereafter. And thou wilt see the Wrong-doers, when in sight of the Penalty, Say: "Is there any way (to effect) a return?"'),
  ('en.yusufali', 42, 45, 'And thou wilt see them brought forward to the (Penalty), in a humble frame of mind because of (their) disgrace, (and) looking with a stealthy glance. And the Believers will say: "Those are indeed in loss, who have given to perdition their own selves and those belonging to them on the Day of Judgment. Behold! Truly the Wrong-doers are in a lasting Penalty!"'),
  ('en.yusufali', 42, 46, 'And no protectors have they to help them, other than Allah. And for any whom Allah leaves to stray, there is no way (to the Goal).'),
  ('en.yusufali', 42, 47, 'Hearken ye to your Lord, before there come a Day which there will be no putting back, because of (the Ordainment of) Allah! that Day there will be for you no place of refuge nor will there be for you any room for denial (of your sins)!'),
  ('en.yusufali', 42, 48, 'If then they run away, We have not sent thee as a guard over them. Thy duty is but to convey (the Message). And truly, when We give man a taste of a Mercy from Ourselves, he doth exult thereat, but when some ill happens to him, on account of the deeds which his hands have sent forth, truly then is man ungrateful!'),
  ('en.yusufali', 42, 49, 'To Allah belongs the dominion of the heavens and the earth. He creates what He wills (and plans). He bestows (children) male or female according to His Will (and Plan),'),
  ('en.yusufali', 42, 50, 'Or He bestows both males and females, and He leaves barren whom He will: for He is full of Knowledge and Power.'),
  ('en.yusufali', 42, 51, 'It is not fitting for a man that Allah should speak to him except by inspiration, or from behind a veil, or by the sending of a messenger to reveal, with Allah\'s permission, what Allah wills: for He is Most High, Most Wise.'),
  ('en.yusufali', 42, 52, 'And thus have We, by Our Command, sent inspiration to thee: thou knewest not (before) what was Revelation, and what was Faith; but We have made the (Qur\'an) a Light, wherewith We guide such of Our servants as We will; and verily thou dost guide (men) to the Straight Way,-'),
  ('en.yusufali', 42, 53, 'The Way of Allah, to Whom belongs whatever is in the heavens and whatever is on earth. Behold (how) all affairs tend towards Allah!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 42, 1, 'Haa Meeem'),
  ('en.transliteration', 42, 2, '\'Ayyyn Seeen Qaaaf'),
  ('en.transliteration', 42, 3, 'Kazaalika yooheee ilaika wa ilal lazeena min qablikal laahul \'Azeezul Hakeem'),
  ('en.transliteration', 42, 4, 'Lahoo maa fis samaa waati wa maa fil ardi wa Huwal \'Aliyul \'Azeem'),
  ('en.transliteration', 42, 5, 'Takaadus samaawaatu yatafattarna min fawqihinn; walmalaaa\'ikatu yusabbihoona bihamdi Rabbihim wa yastaghfiroona liman fil ard; alaaa innal laaha huwal Ghafoorur Raheem'),
  ('en.transliteration', 42, 6, 'Wallazeenat takhazoo min dooniheee awliyaaa\'al laahu hafeezun \'alaihim wa maaa anta \'alaihim biwakeel'),
  ('en.transliteration', 42, 7, 'Wa kazaalika awhainaaa llaika Qur-aanan \'Arabiyyal litunzir aUmmal Quraa wa man hawlahaa wa tunzira Yawmal Jam\'ilaa raiba feeh; fareequn fil jannati wa fareequn fissa\'eer'),
  ('en.transliteration', 42, 8, 'Wa law shaaa\'al laahu laja\'alahum ummatanw waahi datanw walaakiny yudkhilumany yashaaa\'u fee rahmatih; waz zaalimoona maa lahum minw waliyyinw wa laa naseer'),
  ('en.transliteration', 42, 9, 'Amit takhazoo min dooniheee awliyaaa\'a fallaahu Huwal Waliyyu wa Huwa yuhyil mawtaa wa Huwa \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 42, 10, 'Wa makh-talaftum feehi min shai\'in fahukmuhooo ilallaah; zaalikumul laahu Rabbee \'alaihi tawakkaltu wa ilaihi uneeb'),
  ('en.transliteration', 42, 11, 'Faatirus samaawaati wal ard; ja\'ala lakum min anfusikum azwaajanw wa minal an\'aami azwaajany yazra\'ukum feeh; laisa kamislihee shai\'unw wa Huwas Samee\'ul Baseer'),
  ('en.transliteration', 42, 12, 'Lahoo maqaaleedus samaawaati wal ardi yabsutur rizqa limany yashaaa\'u wa yaqdir; innahoo bikulli shai\'unw wa Huwas Samee\'ul Baseer'),
  ('en.transliteration', 42, 13, 'Shara\'a lakum minad deeni maa wassaa bihee Noohanw wallazeee awhainaaa ilaika wa maa wassainaa biheee Ibraaheema wa Moosa wa \'Eesaaa an aqeemud adeena wa laa tatafarraqoo feeh; kabura \'alal mushrikeena maa tad\'oohum ilaih; Allaahu yajtabee ilaihi many yashaaa\'u wa yahdeee ilaihi mai yuneeb'),
  ('en.transliteration', 42, 14, 'Wa maa tafarraqooo illaa mim ba\'di maa jaaa\'ahumul \'ilmu baghyam bainahum; wa law laa Kalimatun sabaqat mir Rabbika ilaaa ajalim musammal laqudiya bainahum; wa innal lazeena oorisul Kitaaba mim ba\'dihim lafee shakkim minhu mureeb'),
  ('en.transliteration', 42, 15, 'Falizaalika fad\'u wastaqim kamaaa umirta wa laa tattabi\' ahwaaa\'ahum wa qul aamantu bimaaa anzalal laahu min Kitaab, wa umirtu li a\'dila bainakum Allaahu Rabbunaa wa Rabbukum lanaaa a\'maa lunaa wa lakum a\'maalukim laa hujjata bainanaa wa baina kumul laahu yajma\'u bainanaa wa ilaihil maseer'),
  ('en.transliteration', 42, 16, 'Wallazeena yuhaaajjoona fil laahi mim ba\'di mastujeeba lahoo hujjatuhum daahidatun \'inda Rabbihim wa \'alaihim ghadabunw wa lahum \'azaabun shadeed'),
  ('en.transliteration', 42, 17, 'Allahul lazeee anzalal Kitaaba bilhaqqi wal Meezaan; wa ma yudreeka la\'allas Saa\'ata qareeb'),
  ('en.transliteration', 42, 18, 'Yasta\'jilu bihal lazeena laa yu\'minoona bihaa wallazeena aamanoo mushfiqoona minhaa wa ya\'lamoona annahal haqq; alaaa innal lazeena yumaaroona fis Saa\'ati lafee dalaalim ba\'eed'),
  ('en.transliteration', 42, 19, 'Allahu lateefum bi\'ibaadihee yarzuqu mai yashaaa\'u wa Huwal Qawiyyul \'Azeez'),
  ('en.transliteration', 42, 20, 'Man kaana yureedu harsal Aakhirati nazid lahoo fee harsihee wa man kaana yureedu harsad dunyaa nu\'tihee mnhaa wa maa lahoo fil Aakhirati min naseeb'),
  ('en.transliteration', 42, 21, 'Am lahum shurakaaa\'u shara\'oo lahum minad deeni maa lam yaazam bihil laah; wa law laa kalimatul fasli laqudiya bainahum; wa innaz zaalimeena lahum \'azaabun aleem'),
  ('en.transliteration', 42, 22, 'Taraz zaalimeena mushfiqeena mimmaa kasaboo wa huwa waaqi\'um bihim; wallazeena aamanoo wa \'amilus saalihaati fee rawdaatil jannaati lahum maa yashaaa\'oona \'inda Rabbihim; zaalika huwal fadlul kabeer'),
  ('en.transliteration', 42, 23, 'Zaalikal lazee yubash shirul laahu \'ibaadahul lazeena aamanoo wa \'amilus saalihaat; qul laaa as\'alukum \'alaihi ajran illal mawaddata fil qurbaa; wa mai yaqtarif hasanatan nazid lahoo feehaa husnaa; innal laaha Ghafoorun Shakoor'),
  ('en.transliteration', 42, 24, 'Am yaqooloonaf tara \'alal laahi kaziban fa-iny yasha il laahu yakhtim \'alaa qalbik; wa yamhul laahul baatila wa yuhiqqul haqqa bi Kalimaatih; innahoo \'Aleemum bizaatis sudoor'),
  ('en.transliteration', 42, 25, 'Wa Huwal lazee yaqbalut tawbata \'an \'ibaadihee wa ya\'foo \'anis saiyiaati wa ya\'lamu maa taf\'aloon'),
  ('en.transliteration', 42, 26, 'Wa yastajeebul lazeena aamanoo wa \'amilu saalihaati wa yazeeduhum min fadlih; wal kaafiroona lahum \'azaabun shadeed'),
  ('en.transliteration', 42, 27, 'Wa law basatal laahur rizqa li\'ibaadihee labaghaw fil ardi wa laakiny yunazzilu biqadarim maa yashaaa\'; innahoo bi\'ibaadihee Khabeerum Baseer'),
  ('en.transliteration', 42, 28, 'Wa Huwal lazee yunazzilul ghaisa mim ba\'di maa qanatoo wa yanshuru rahmatah; wa Huwal Waliyyul Hameed'),
  ('en.transliteration', 42, 29, 'Wa min Aayaatihee khalqus samaawaati wal ardi wa maa bassa feehimaa min daaabbah; wa Huwa \'alaa jam\'ihim izaa yashaaa\'u Qadeer'),
  ('en.transliteration', 42, 30, 'Wa maaa asaabakum mim museebatin fabimaa kasabat aydeekum wa ya\'foo \'an kaseer'),
  ('en.transliteration', 42, 31, 'Wa maaa antum bimu\'jizeena fil ardi wa maa lakum min doonil laahi minw wa liyyinw wa laa naseer'),
  ('en.transliteration', 42, 32, 'Wa min Aayaatihil ja waarifil bahri kal a\'lam'),
  ('en.transliteration', 42, 33, 'Iny yashaaa yuskinir reeha fa yazlalna rawaakida \'alaa zahirh; inna fee zaalika la Aayaatil likulli sabbaarin shakoor'),
  ('en.transliteration', 42, 34, 'Aw yoobiqhunna bimaa kasaboo wa ya\'fu \'an kaseer'),
  ('en.transliteration', 42, 35, 'Wa ya\'lamal lazeena yujaadiloona feee Aayaatinaa maa lahum mim mahees'),
  ('en.transliteration', 42, 36, 'Famaa ooteetum min shai\'in famataa\'ul hayaatid dunyaa wa maa \'indal laahi khairunw wa abqaa lillazeena aamanoo wa \'alaa Rabbihim yatawakkaloon'),
  ('en.transliteration', 42, 37, 'Wallazeena yajtaniboona kabaaa\'iral ismi wal fawaa hisha wa izaa maa ghadiboo hum yaghfiroon'),
  ('en.transliteration', 42, 38, 'Wallazeenas tajaaboo li Rabbhim wa aqaamus Salaata wa amruhum shooraa bainahum wa mimmaa razaqnaahum yunfiqoon'),
  ('en.transliteration', 42, 39, 'Wallazeena izaa asaabahumul baghyu hum yantasiroon'),
  ('en.transliteration', 42, 40, 'Wa jazaaa\'u saiyi\'atin saiyi\'tum misluha faman \'afaa wa aslaha fa ajruhoo \'alal laah; innahoo laa yuhibbuz zaalimeen'),
  ('en.transliteration', 42, 41, 'Wa lamanin tasara ba\'da zulmihee fa ulaaa\'ika maa \'alaihim min sabeel'),
  ('en.transliteration', 42, 42, 'Innamas sabeelu \'alal lazeena yazlimoonan naasa wa yabghoona fil ardi bighairil haqq; ulaaa\'ika lahum \'azaabun aleem'),
  ('en.transliteration', 42, 43, 'Wa laman sabara wa ghafara inna zaalika lamin \'azmil umoor'),
  ('en.transliteration', 42, 44, 'Wa mai yudlilil laahu famaa lahoo minw waliyyim mim ba\'dih; wa taraz zaalimeena lammaa ra awul \'azaaba yaqooloona hal ilaa maraddim min sabeel'),
  ('en.transliteration', 42, 45, 'Wa taraahum yu\'radoona \'alaihaa khaashi\'eena minazzulli yanzuroona min tarfin khaifiyy; wa qaalal lazeena aamanooo innal khaasireenal lazeena khasiroon anfusahum wa ahleehim Yawmal Qiyaamah; alaaa innaz zaalimeena fee\'azaabim muqeem'),
  ('en.transliteration', 42, 46, 'Wa maa kaana lahum min awliyaaa\'a yansuroonahum min doonil laah; wa mai yudlilil laahu famaa lahoo min sabeel'),
  ('en.transliteration', 42, 47, 'Istajeeboo li Rabbikum min qabli any yaatiya Yawmul laa maradda lahoo minal laah; maa lakum mim malja iny yawma\'izinw wa maa lakum min nakeer'),
  ('en.transliteration', 42, 48, 'Fa-in a\'radoo famaaa arsalnaaka \'alaihim hafeezan in \'alaika illal balaagh; wa innaaa izaaa azaqnal insaana minnaa rahmatan fariha bihaa wa in tusibhum saiyi\'atum bimaa qaddamat aydeehim fa innal insaana kafoor'),
  ('en.transliteration', 42, 49, 'Lillaahi mulkus samaawaati wal ard; yakhluqu maa yashaaa\'; yahabu limai yashaaa\'u inaasanw wa yahabu limai yashaaa\'uz zukoor'),
  ('en.transliteration', 42, 50, 'Aw yuzawwijuhum zukraananw wa inaasanw wa yaj\'alu mai yashaaa\'u \'aqeemaa; innahoo \'Aleemun Qadeer'),
  ('en.transliteration', 42, 51, 'Wa maa kaana libasharin any yukallimahul laahu illaa wahyan aw minw waraaa\'i hijaabin aw yursila Rasoolan fa yoohiya bi iznuhee maa yashaaa\'; innahoo \'Aliyyun Hakeem'),
  ('en.transliteration', 42, 52, 'Wa kazaalika awhainaaa ilaika rooham min amrinaa; maa kunta tadree mal Kitaabu wa lal eemaanu wa laakin ja\'alnaahu nooran nahdee bihee man nashaaa\'u min \'ibaadinaa; wa innaka latahdeee ilaaa Siraatim Mustaqeem'),
  ('en.transliteration', 42, 53, 'Siraatil laahil lazee lahoo maa fis samaawaati wa maa fil ard; alaaa ilal laahi taseerul umoor')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 42, 1, 'حمۤ'),
  ('ur.ahmedali', 42, 2, 'عۤسۤقۤ'),
  ('ur.ahmedali', 42, 3, 'اسی طرح سے الله زبردست حکمت والا آپ کی طرف وحی کرتا ہے اور ان کی طرف بھی (کرتا تھا) جو آپ سے پہلے تھے'),
  ('ur.ahmedali', 42, 4, 'اسی کا ہے جو کچھ آسمانوں اور زمین میں ہے اور وہ بلند مرتبہ بزرگی والا ہے'),
  ('ur.ahmedali', 42, 5, 'قریب ہے کہ آسمان اوپر سے پھٹ جائیں اور سب فرشتے اپنے رب کی حمد کے ساتھ تسبیح کرتے ہیں اور ان کے لیے جو زمین میں ہیں مغفرت مانگتے ہیں خبردار بے شک الله ہی بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 42, 6, 'اور وہ لوگ جنہوں نے اس کے سوا اور کارساز بنا رکھے ہیں الله ان کا حال دیکھ رہا ہے اور آپ ان کے ذمہ دار نہیں ہیں'),
  ('ur.ahmedali', 42, 7, 'اور اسی طرح ہم نے آپ پر عربی زبان میں قرآن نازل کیا تاکہ آپ مکہ والوں اور اس کے آس پاس والوں کو ڈرائیں اور قیامت کے دن سے بھی ڈرائیں جس میں کوئی شبہ نہیں (اس روز) ایک جماعت جنت میں اور ایک جماعت جہنم میں ہو گی'),
  ('ur.ahmedali', 42, 8, 'اور اگر الله چاہتا تو ان سب کو ایک ہی جماعت کر دیتا لیکن الله جسے چاہتا ہے اپنی رحمت میں داخل کرتا ہے اور ظالموں کا نہ کوئی دوست ہے اور نہ کوئی مددگار'),
  ('ur.ahmedali', 42, 9, 'کیا انہوں نے اس کے سوا اوربھی مددگار بنا رکھے ہیں پھر الله ہی مددگار ہے اور وہی مردووں کو زندہ کرے گا اور وہ ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 42, 10, 'اور جس بات میں بھی تم اختلاف کرتے ہو سو اس کا فیصلہ الله کے سپرد ہے وہی الله میرا رب ہے اسی پر میرا بھروسہ ہے اور اس کی طرف میں رجوع کرتا ہوں'),
  ('ur.ahmedali', 42, 11, 'وہ آسمانوں اور زمین کا پیدا کرنے والا ہے اسی نے تمہاری جنس سے تمہارے جوڑے بنائے اور چارپایوں کےبھی جوڑے بنائے تمہیں زمین میں پھیلاتا ہے کوئی چیز اس کی مثل نہیں اور وہ سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 42, 12, 'اس کے ہاتھ میں آسمانوں اور زمین کی کنجیاں ہیں روزی کشادہ کرتا ہے جس کی چاہے اور تنگ کر دیتا ہے بے شک وہ ہر چیز کو جاننے والا ہے'),
  ('ur.ahmedali', 42, 13, 'تمہارے لیے وہی دین مقرر کیا جس کا نوح کو حکم دیا تھا اور اسی راستہ کی ہم نے آپ کی طرف وحی کی ہے اور اسی کا ہم نے ابراھیم اور موسیٰ اور عیسیٰ کو حکم دیا تھا کہ اسی دین پر قائم رہو اور اس میں پھوٹ نہ ڈالنا جس چیز کی طرف آپ مشرکوں کو بلاتے ہیں وہ ان پر گراں گزرتی ہے الله جسے چاہے اپنی طرف کھینچ لیتا ہے اور جو اس کی طرف رجوع کرتا ہے اسے راہ دکھاتا ہے'),
  ('ur.ahmedali', 42, 14, 'اور اہلِ کتاب جوجدا جدا فرقے ہوئے تو علم آنے کے بعد اپنی باہمی ضد سے ہوئے اور اگر تیرے رب کی طرف سے ایک وقت مقرر (قیامت) تک کا وعدہ نہ ہوتا تو ان میں فیصلہ ہوگیا ہوتا اور جو ان کے بعد کتاب کے وارث بنائے گئے ہیں (زمانہِ نبوی کے اہل کتاب) وہ اس (دین) کی نسبت حیرت انگیز شک میں ہیں'),
  ('ur.ahmedali', 42, 15, 'تو آپ اسی دین کی طرف بلائیے اور قائم رہیئے جیسا آپ کو حکم دیا گیا ہے اور ان کی خواہشوں پر نہ چلیئے اور کہہ دو کہ میں اس پر یقن لایا ہوں جو اللهنےکتاب نازل کی ہے اور مجھے حکم دیا گیا ہے کہ میں تمہارے درمیان انصاف کروں اللہ ہی ہمارا اور تمہارا پروردگار ہے ہمارے لیے ہمارےاعمال ہیں اور تمہارے لیے تمہارے اعمال اور تمہارے درمیان کوئی جھگڑا نہیں الله ہم سب کو جمع کر لے گا اور اسی کی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 42, 16, 'اور جو لوگ الله (کے دین) کے بارے میں جھگڑتے ہیں بعد اس کے کہ وہ مان لیا گیا ان لوگوں کی حجّت ان کے رب کے ہاں باطل ہے اور ان پر غضب ہے اور ان کے لیے سخت عذاب ہے'),
  ('ur.ahmedali', 42, 17, 'الله ہی ہے جس نے سچی کتاب اور ترازو نازل کی اور آپ کو کیا معلوم شاید قیامت قریب ہو'),
  ('ur.ahmedali', 42, 18, 'اس کی جلدی تووہی کرتے ہیں جو اس پر ایمان نہیں رکھتے اور جو ایمان رکھتے ہیں وہ اس سے ڈر رہے ہیں اور جانتے ہیں کہ وہ برحق ہے خبردار بے شک جو لوگ قیامت کے بارہ میں جھگڑا کرتے ہیں وہ پرلے درجے کی گمراہی میں ہیں'),
  ('ur.ahmedali', 42, 19, 'الله اپنے بندوں پر بڑا مہربان ہے جسے (جس قدر) چاہے روزی دیتا ہے اوروہ بڑا طاقتور زبردست ہے'),
  ('ur.ahmedali', 42, 20, 'جو کوئی آخرت کی کھیتی کا طالب ہو ہم اس کے لیے اس کھیتی میں برکت دیں گے اور جو دنیا کی کھیتی کا طالب ہو اسے (بقدر مناسب) دنیا میں دیں گے اور آخرت میں اس کا کچھ حصہ نہیں ہوگا'),
  ('ur.ahmedali', 42, 21, 'کیا ان کے اور شریک ہیں جنہوں نے ان کے لیے دین کا وہ طریقہ نکالا ہے جس کی الله نے اجازت نہیں دی اور اگر فیصلہ کا وعدہ نہ ہوا ہوتا تو ان کا دنیا ہی میں فیصلہ ہو گیا ہو تا اور بے شک ظالموں کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 42, 22, 'آپ ظالموں کو (قیامت کے دن) دیکھیں گے کہ اپنے اعمال (کے وبال) سے ڈر رہے ہوں گے اور ان پر پڑنے والا اور جو لوگ ایمان لائے اور نیک کام کیے وہ بہشت کے باغوں میں ہوں گے انہیں جو چاہیں گے اپنے رب کے ہاں سے ملے گا یہی وہ بڑا فضل ہے'),
  ('ur.ahmedali', 42, 23, 'یہی وہ (فضل) جس کی الله اپنے بندوں کو خوشخبری دے دیتا ہے جو ایمان لائے اور نیک کام کیے کہہ دو میں تم سے اس پر کوئی اجرات نہیں مانگتا بجز رشتہ داری کی محبت کے اور جو نیکی کمائے گا تو ہم اس میں اس کے لیے بھلائی زیادہ کردیں گے بے شک الله بخشنے والا قدردان ہے'),
  ('ur.ahmedali', 42, 24, 'کیا وہ کہتے ہیں کہ آپ نے الله پر جھوٹ باندھا ہے پس اگر الله چاہے تو آپ کے دل پر مُہر کر دے اور الله باطل کو مٹا دیتا ہے اور سچ کو اپنی کلام سے ثابت کر دیتا ہے بے شک وہ سینوں کے بھید خوب جانتا ہے'),
  ('ur.ahmedali', 42, 25, 'اور وہی ہے جو اپنے بندوں کی توبہ قبول کرتا ہے اور ان کے گناہ معاف کر دیتا ہے اور جانتا ہے جو تم کرتے ہو'),
  ('ur.ahmedali', 42, 26, 'اور ان کی دعا قبول کرتا ہے جو ایمان لائے اور نیک کام کیے اور انہیں اپنے فضل سے زیادہ دیتا ہے او رکافروں کے لیے سخت عذاب ہے'),
  ('ur.ahmedali', 42, 27, 'اور اگر الله اپنے بندوں کی روزی کشادہ کر دے تو زمین پر سرکشی کرنے لگیں لیکن وہ ایک اندازے سے اتارتا ہے جتنی چاہتا ہے بے شک وہ اپنے بندوں سے خوب خبردار دیکھنے والا ہے'),
  ('ur.ahmedali', 42, 28, 'اور وہی ہے جو ناامید ہو جانے کے بعد مینہ برساتا ہے اور اپنی رحمت کو پھیلاتا ہے اور وہی کارساز احمد کے لائق ہے'),
  ('ur.ahmedali', 42, 29, 'اور اس کی نشانیوں میں سے ایک یہ بھی ہے کہ آسمانوں اور زمین کو بنایا اور اس پر ہر قسم کے چلنے والے جانور پھیلائے اوروہ جب چاہے گا ان کے جمع کرنے پر قادر ہے'),
  ('ur.ahmedali', 42, 30, 'اور تم پر جو مصیبت آتی ہے تو وہ تمہارے ہی ہاتھوں کے کیے ہوئے کاموں سے آتی ہے اور وہ بہت سے گناہ معاف کر دیتا ہے'),
  ('ur.ahmedali', 42, 31, 'اور تم زمین میں عاجز کرنے والے نہیں اور سوائے الله کے نہ کوئی تمہارا کارساز ہے اور نہ کوئی مددگار'),
  ('ur.ahmedali', 42, 32, 'اور اس کی نشانیوں میں سے سمندر میں پہاڑوں جیسے جہاز ہیں'),
  ('ur.ahmedali', 42, 33, 'اگر وہ چاہے تو ہوا کو ٹھیرا دے پس وہ اس کی سطح پر کھڑ ے رہ جائیں بے شک اس میں ہر صبر کرنے والے شکر گزار کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 42, 34, 'یا ان کے برے اعمال کے سبب سے انہیں تباہ کر دے اور بہتوں کو معاف بھی کر دیتا ہے'),
  ('ur.ahmedali', 42, 35, 'اور جان لیں وہ جو ہماری آیتوں میں جھگڑتے ہیں کہ ان کے لیے پناہ کی کوئی جگہ نہیں'),
  ('ur.ahmedali', 42, 36, 'پھر جو کچھ تمہیں دیا گیا ہے وہ دنیا کی زندگی کا سامان ہے اور جو کچھ الله کے پاس ہے وہ بہتر اور سدا رہنے والا ہے یہ ان کے لیے ہے جو ایمان لائے اور اپنے رب پر توکل کرتے ہیں'),
  ('ur.ahmedali', 42, 37, 'اوروہ جو بڑے بڑے گناہوں اور بے حیائی سے بچتے ہیں اور جب غضہ ہوتے ہیں تو معاف کر دیتے ہیں'),
  ('ur.ahmedali', 42, 38, 'اور وہ جو اپنے رب کا حکم مانتے ہیں اور نماز ادا کرتے ہیں اور ان کا کام باہمی مشورے سے ہوتا ہے اور ہمارے دیے ہوئے میں سے کچھ دیا بھی کرتے ہیں'),
  ('ur.ahmedali', 42, 39, 'اور وہ لوگ جب ان پر ظلم ہوتا ہے تو بدلہ لیتے ہیں'),
  ('ur.ahmedali', 42, 40, 'اوربرائی کا بدلہ ویسی ہی برائی ہے پس جس نے معاف کر دیا اور صلح کر لی تو اس کا اجر الله کے ذمہ ہے بے شک وہ ظالموں کو پسند نہیں کرتا'),
  ('ur.ahmedali', 42, 41, 'اور جو کوئی ظلم اٹھانے کے بعد بدلہ لے تو ان پر کوئی الزام نہیں'),
  ('ur.ahmedali', 42, 42, 'الزام تو ان پر ہے جو لوگوں پر ظلم کرتے ہیں اور ملک میں ناحق سرکشی کرتے ہیں یہی ہیں جن کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 42, 43, 'اور البتہ جس نے صبر کیا اور معاف کر دیا بے شکے یہ بڑی ہمت کا کام ہے'),
  ('ur.ahmedali', 42, 44, 'اور جسے الله گمراہ کر دے سو اس کے بعد اس کا کوئی کارساز نہیں اور ظالموں کو دیکھیں گے جب وہ عذاب دیکھیں گے تو کہیں گے کیا واپس جانے کا بھی کوئی راستہ ہے'),
  ('ur.ahmedali', 42, 45, 'اور آپ انہیں دیکھیں گے کہ وہ دوزخ کے سامنے لائے جائيں گے ایسے حال میں ذلت کے مارے جھکے ہوئے ہوں گے چھپی نگاہ سے دیکھ رہے ہوں گے اور وہ لوگ کہیں گے جو ایمان لائے تھے بے شک خسارہ اٹھانے والے وہی لوگ ہیں جنہوں نے اپنے آپ کو اوراپنے گھر والوں کو قیامت کے دن خسارہ میں رکھا خبردار بے شک ظالم ہی ہمیشہ عذاب میں ہوں گے'),
  ('ur.ahmedali', 42, 46, 'اور ان کا الله کے سوا کوئی بھی حمایتی نہ ہوگا کہ ان کو بچائے اورجسے الله گمراہ کرے اس کے لیے کوئی بھی راستہ نہیں'),
  ('ur.ahmedali', 42, 47, 'اس سے پہلے اپنے رب کا حکم مان لو کہ وہ دن آجائے جو الله کی طرف سے ٹلنے والا نہیں اس دن تمہارے لیے کوئی جائے پناہ نہیں ہو گی اور نہ تم انکارکر سکو گے'),
  ('ur.ahmedali', 42, 48, 'پھر بھی اگر نہ مانیں تو ہم نے آپ کو ان پر محافظ بنا کرنہیں بھیجا ہے آپ پر تو صرف پہنچا دینا ہے اور جب ہم انسان کو اپنی کوئی رحمت چکھاتے ہیں تو اس سے خوش ہوجاتا ہے اور اگر اس پر اس کے اعمال سے اس سے کوئی مصیبت پڑ جاتی ہے تو انسان بڑا ہی ناشکرا ہے'),
  ('ur.ahmedali', 42, 49, 'آسمانوں اور زمین میں الله ہی کی بادشاہی ہے جو چاہتا ہے پیدا کر تا ہے جسے چاہتا ہے لڑکیاں عطا کرتا ہے اور جسے چاہتا ہے لڑکے بخشتا ہے'),
  ('ur.ahmedali', 42, 50, 'یا لڑکے اور لڑکیاں ملا کر دیتا ہے اور جسے چاہتا ہے بانجھ کر دیتا ہے بے شک وہ خبردار قدرت والا ہے'),
  ('ur.ahmedali', 42, 51, 'اور کسی انسان کا حق نہیں کہ اس سے الله کلام کر لے مگر بذریعہ وحی یا پردے کے پیچھے سے یا کوئی فرشتہ بھیج دے کہ وہ اس کے حکم سے القا کر لے جو چاہے بے شک وہ بڑاعالیشان حکمت والا ہے'),
  ('ur.ahmedali', 42, 52, 'اور اسی طرح ہم نے آپ کی طرف اپنا حکم سے قرآن نازل کیا آپ نہیں جانتے تھے کہ کتاب کیا ہے او رایمان کیا ہے او رلیکن ہم نے قرآن کو ایسا نور بنایا ہے کہ ہم اس کے ذریعہ سے ہم اپنے بندوں سے جسے چاہتے ہیں ہدایت کرتے ہیں اور بے شک آپ سیدھا راستہ بتاتے ہیں'),
  ('ur.ahmedali', 42, 53, 'اس الله کا راستہ جس کے قبضہ میں آسمانوں اور زمین کی سب چیزیں ہیں خبردار الله ہی کی طرف سب کام رجوع کرتے ہیں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 42, 1, 'Ha, Mim.'),
  ('tr.diyanet', 42, 2, 'Ayn, Sin, Kaf,'),
  ('tr.diyanet', 42, 3, 'Güçlü olan, Hakim olan Allah, sana da, senden öncekilere de böyle vahyeder.'),
  ('tr.diyanet', 42, 4, 'Göklerde olanlar da, yerde olanlar da O\'nundur. O, çok yücedir ve büyüktür.'),
  ('tr.diyanet', 42, 5, 'Gökler neredeyse üstlerinden çatlayacak. Melekler Rablerini överek tesbih eder ve yeryüzünde bulunanlar için O\'ndan bağışlanma dilerler. İyi bilin ki Allah Şüphesiz bağışlayandır, merhametli olandır.'),
  ('tr.diyanet', 42, 6, 'Allah\'ı bırakıp da dostlar edinenlerin işlediklerini Allah gözetlemektedir. Sen, onlara vekil olmağa memur değilsin.'),
  ('tr.diyanet', 42, 7, 'Böylece şehirlerin anası olan Mekke\'de ve çevresinde bulunanları uyarman, şüphe götürmeyen toplanma günü ile uyarman için sana Arapça okunan bir Kitap vahyettik. İnsanların bir takımı cennete, bir takımı da çılgın alevli cehenneme girer.'),
  ('tr.diyanet', 42, 8, 'Eğer dilemiş olsaydı hepsini bir tek ümmet yapardı. Ama, O, rahmetine dilediğini kavuşturur. Zalimlerin ise bir dost ve yardımcısı olmaz.'),
  ('tr.diyanet', 42, 9, 'Demek onlar Allah\'tan başka dostlar edindiler? Oysa dost, ancak Allah\'tır. O, ölüleri diriltir. Her şeye Kadir\'dir.'),
  ('tr.diyanet', 42, 10, 'Ayrılığa düştüğünüz herhangi bir şeyde hüküm vermek, Allah\'a aittir; "İşte bu Allah, benim Rabbimdir. O\'na güvenirim ve O\'na yönelirim." (demek gerekir)'),
  ('tr.diyanet', 42, 11, 'Göklerin ve yerin yaratanı, size içinizden eşler, çift çift hayvanlar var etmiştir. Bu suretle, çoğalmanızı sağlamıştır. O\'nun benzeri hiçbir şey yoktur. O, işitendir, görendir.'),
  ('tr.diyanet', 42, 12, 'Göklerin ve yerin kilitleri O\'nundur. Dilediğine rızkı yayar ve isterse kısar, bir ölçüye göre verir. Doğrusu O herşeyi bilendir.'),
  ('tr.diyanet', 42, 13, 'Allah Nuh\'a buyurduğu şeyleri size de din olarak buyurmuştur. Sana vahyettik; İbrahim\'e, Musa\'ya ve İsa\'ya da buyurduk ki: "Dine bağlı kalın, onda ayrılığa düşmeyin." Ortak koşanları çağırdığın şey onların gözünde büyümektedir. Allah dilediğini kendine seçer, kendisine yöneleni de doğru yola eriştirir.'),
  ('tr.diyanet', 42, 14, 'Kendilerine ilim geldikten sonra ayrılığa düşmeleri, ancak, birbirini çekememekten oldu. Eğer belirli bir süre için Rabbinin verilmiş bir sözü olmasaydı, aralarında hemen hükmedilirdi. Arkalarından Kitaba varis kılınanlar da ondan şüphe ve endişe içindedirler.'),
  ('tr.diyanet', 42, 15, 'Bundan ötürü sen birliğe çağır ve emrolunduğun gibi doğru ol; onların heveslerine uyma ve şöyle söyle: "Allah\'ın indirdiği Kitap\'a inandım; aranızda adaletle hükmetmek ile emrolundum; Allah bizim de Rabbimiz, sizin de Rabbinizdir; bizim işlediklerimiz bize, sizin işledikleriniz kendinizedir. Bizimle sizin aranızda tartışılacak bir şey yoktur. Allah hepimizi bir araya toplar; dönüş O\'nadır."'),
  ('tr.diyanet', 42, 16, 'Allah\'ın çağrısına icabet eden bulunduktan sonra, O\'nun hakkında tartışmağa girişenlerin delilleri Rableri katında hükümsüzdür. Onlara bir gazap vardır, çetin bir azap da onlar içindir.'),
  ('tr.diyanet', 42, 17, 'Gerçekten Kitap\'ı ve ölçüyü indiren Allah\'tır. Ne bilirsin, belki de kıyamet saati yakındır.'),
  ('tr.diyanet', 42, 18, 'O\'na inanmayanlar, acele olmasını beklerler; inananlar ise korku ile titrerler ve onun gerçek olduğunu bilirler. İyi bilin ki kıyamet günü hakkında tartışanlar derin bir sapıklık içindedirler.'),
  ('tr.diyanet', 42, 19, 'Allah, kullarına lütufta bulunandır. Dilediğini rızıklandırır. Kuvvetli olan da güçlü olan da O\'dur.'),
  ('tr.diyanet', 42, 20, 'Ahiret kazancını isteyenin kazancını artırırız; dünya kazancını isteyene de ondan veririz; ama ahirette bir payı bulunmaz.'),
  ('tr.diyanet', 42, 21, 'Yoksa, Allah\'ın dinde izin vermediği bir şeyi onlara meşru kılacak ortakları mı vardır? Eğer kesin yargı bulunmayacak olsaydı aralarında hemen hükmedilirdi. Doğrusu, zalimlere can yakıcı azap vardır.'),
  ('tr.diyanet', 42, 22, 'Yaptıkları şeyler başlarına gelirken, zalimlerin korkudan titrediklerini görürsün. İnanıp yararlı işler işleyenler cennet bahçelerindedirler. Rablerinin katında, onlara diledikleri verilir. İşte büyük lütuf budur.'),
  ('tr.diyanet', 42, 23, 'Allah, inanıp yararlı işler işleyen kullarını bununla müjdeler. De ki: "Ben sizden buna karşı yakınlara sevgiden (veya Allah\'a yaklaşmaktan) başka bir ücret istemem." Kim güzel bir iş işlerse onun güzelliğini arttırırız. Doğrusu Allah bağışlayandır, şükrün karşılığını verendir.'),
  ('tr.diyanet', 42, 24, 'Yoksa senin için "Allah\'a karşı yalan yere iftira etti" mi derler? Allah dilerse senin kalbini mühürler, batılı da yok eder, hakkı sözleriyle gerçekleştirir. Doğrusu O, kalplerde olanı bilendir.'),
  ('tr.diyanet', 42, 25, 'Kullarının tevbesini kabul eden, kötülükleri affeden, yaptıklarınızı bilen, inanıp yararlı işler işleyenlerin duasını kabul eden, lütfuyla onların ecrini arttıran O\'dur. Ama, inkarcılar için çetin azap vardır.'),
  ('tr.diyanet', 42, 26, 'Kullarının tevbesini kabul eden, kötülükleri affeden, yaptıklarınızı bilen, inanıp yararlı işler işleyenlerin duasını kabul eden, lütfuyla onların ecrini arttıran O\'dur. Ama, inkarcılar için çetin azap vardır.'),
  ('tr.diyanet', 42, 27, 'Eğer Allah rızkı kullarının hepsine bol bol verseydi, yeryüzünde azgınlık ederlerdi. Ama O, dilediğini bir ölçüye göre indirir. Doğrusu O, kullarından haberdardır, onları görendir.'),
  ('tr.diyanet', 42, 28, 'Umutsuzluğa düşmelerinin ardından yağmuru indiren, rahmetini yayan O\'dur. O, övülmeğe layık olan dosttur.'),
  ('tr.diyanet', 42, 29, 'Gökleri, yeri ve ikisinde yaydığı canlıları yaratması varlığının delillerindendir.'),
  ('tr.diyanet', 42, 30, 'Başınıza gelen herhangi bir musibet ellerinizle işlediklerinizden ötürüdür. O, yine de çoğunu affeder.'),
  ('tr.diyanet', 42, 31, 'Yeryüzünde O\'nu aciz bırakamazsınız. Allah\'tan başka bir dostunuz da yardımcınız da yoktur.'),
  ('tr.diyanet', 42, 32, 'Denizde yüce dağlar gibi gemilerin yürümesi O\'nun varlığının delillerindendir.'),
  ('tr.diyanet', 42, 33, 'O, dilerse rüzgarı durdurur, yelkenle giden gemiler o zaman denizin yüzünde durakalır. Bunlarda, sabırlı olan ve çok şükreden kimseler için deliller vardır.'),
  ('tr.diyanet', 42, 34, 'Yahut yaptıklarına karşılık onları ortadan kaldırır, bir çoğunu da bağışlar.'),
  ('tr.diyanet', 42, 35, 'Ayetlerimiz üzerinde tartışanlar, kendilerine kaçacak yer olmadığını bilsinler.'),
  ('tr.diyanet', 42, 36, 'Size verilen herhangi bir şey, sadece dünya hayatının bir geçimliğidir. Allah katında olan; inanıp Rablerine güvenen, büyük günahlardan ve hayasızlıklardan çekinen, öfkelendiklerinde bile bağışlayanlar, Rablerinin çağrısına cevap verenler ve namaz kılanlar için daha iyi ve daha süreklidir. Onların işleri aralarında danışma iledir. Kendilerine verdiğimiz rızıktan da sarfederler.'),
  ('tr.diyanet', 42, 37, 'Size verilen herhangi bir şey, sadece dünya hayatının bir geçimliğidir. Allah katında olan; inanıp Rablerine güvenen, büyük günahlardan ve hayasızlıklardan çekinen, öfkelendiklerinde bile bağışlayanlar, Rablerinin çağrısına cevap verenler ve namaz kılanlar için daha iyi ve daha süreklidir. Onların işleri aralarında danışma iledir. Kendilerine verdiğimiz rızıktan da sarfederler.'),
  ('tr.diyanet', 42, 38, 'Size verilen herhangi bir şey, sadece dünya hayatının bir geçimliğidir. Allah katında olan; inanıp Rablerine güvenen, büyük günahlardan ve hayasızlıklardan çekinen, öfkelendiklerinde bile bağışlayanlar, Rablerinin çağrısına cevap verenler ve namaz kılanlar için daha iyi ve daha süreklidir. Onların işleri aralarında danışma iledir. Kendilerine verdiğimiz rızıktan da sarfederler.'),
  ('tr.diyanet', 42, 39, 'Bir haksızlığa uğradıklarında, üstün gelmek için aralarında yardımlaşırlar.'),
  ('tr.diyanet', 42, 40, 'Bir kötülüğün karşılığı, aynı şekilde bir kötülüktür. Ama kim affeder ve barışırsa, onun ecri Allah\'a aittir. Doğrusu O, zulmedenleri sevmez.'),
  ('tr.diyanet', 42, 41, 'Zulüm gördükten sonra hakkını alan kimselere, işte onların aleyhine bir yol yoktur.'),
  ('tr.diyanet', 42, 42, 'İnsanlara zulmedenlere, yeryüzünde haksız yere taşkınlık edenlere karşı durulmalıdır. İşte, can yakıcı azap bunlaradır.'),
  ('tr.diyanet', 42, 43, 'Ama sabredip bağışlayanın işi, işte bu, azmedilmeye değer işlerdendir.'),
  ('tr.diyanet', 42, 44, 'Allah kimi saptırırsa, artık onun bundan sonra bir dostu olmaz. Azabı gördüklerinde, zalimlerin: "Dönecek bir yol yok mudur?" dediklerini görürsün.'),
  ('tr.diyanet', 42, 45, 'Aşağılıktan başları öne eğilmiş, göz ucuyla gizli gizli etrafa bakarken, ateşe sunulduklarını görürsün. İnananlar: "Hüsranda olanlar, kıyamet günü kendilerini de, ailelerini de hüsranda bırakanlardır" derler. İyi bilin ki, zalimler sürekli bir azap içindedirler.'),
  ('tr.diyanet', 42, 46, 'Onların, Allah\'tan başka kendilerine yardım edecek dostları da yoktur. Allah\'ın saptırdığı kimsenin çıkar yolu olmaz.'),
  ('tr.diyanet', 42, 47, 'Allah katından, geri çevrilemeyecek günün gelmesinden önce Rabbinizin çağrısına cevap verin. O gün hiçbirinize sığınacak yer bulunmaz, inkar de edemezsiniz.'),
  ('tr.diyanet', 42, 48, 'Eğer yüz çevirirlerse bilsinler ki, Biz seni onlara bekçi göndermedik; sana düşen sadece tebliğdir. Doğrusu Biz insana katımızdan bir rahmet tattırırsak ona sevinir; ama elleriyle yaptıkları yüzünden başlarına bir kötülük gelirse işte o zaman görürsün ki insan gerçekten pek nankördür.'),
  ('tr.diyanet', 42, 49, 'Göklerin ve yerin hükümranlığı Allah\'ındır. Dilediğini yaratır, dilediğine kız çocuk, dilediğine de erkek çocuk verir.'),
  ('tr.diyanet', 42, 50, 'Yahut hem kız hem erkek çocuk verir, dilediğini de kısır kılar. O, bilendir, her şeye Kadir\'dir.'),
  ('tr.diyanet', 42, 51, 'Allah bir insanla ancak vahiy suretiyle veya perde arkasından konuşur, yahut bir elçi gönderir; izniyle, dilediğini vahyeder. Doğrusu O yücedir, Hakim\'dir.'),
  ('tr.diyanet', 42, 52, 'İşte sana da buyruğumuzla Cebrail\'i gönderdik; sen Kitap nedir, iman nedir önceleri bilmezdin, fakat Biz onu, kullarımızdan dilediğimizi onunla doğru yola eriştirdiğimiz bir nur kıldık. Şüphesiz sen de insanlara, göklerde ve yerde ne varsa kendisininolan Allah\'ın yolunu, doğru yolu göstermektesin. İyi bilin ki işler sonunda Allah\'a döner.'),
  ('tr.diyanet', 42, 53, 'İşte sana da buyruğumuzla Cebrail\'i gönderdik; sen Kitap nedir, iman nedir önceleri bilmezdin, fakat Biz onu, kullarımızdan dilediğimizi onunla doğru yola eriştirdiğimiz bir nur kıldık. Şüphesiz sen de insanlara, göklerde ve yerde ne varsa kendisininolan Allah\'ın yolunu, doğru yolu göstermektesin. İyi bilin ki işler sonunda Allah\'a döner.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 42, 1, 'Haa Miim.'),
  ('id.indonesian', 42, 2, '\'Ain Siin Qaaf.'),
  ('id.indonesian', 42, 3, 'Demikianlah Allah Yang Maha Perkasa lagi Maha Bijaksana, mewahyukan kepada kamu dan kepada orang-orang sebelum kamu.'),
  ('id.indonesian', 42, 4, 'Kepunyaan-Nya-lah apa yang ada di langit dan apa yang ada di bumi. Dan Dialah yang Maha Tinggi lagi Maha Besar.'),
  ('id.indonesian', 42, 5, 'Hampir saja langit itu pecah dari sebelah atas (karena kebesaran Tuhan) dan malaikat-malaikat bertasbih serta memuji Tuhan-nya dan memohonkan ampun bagi orang-orang yang ada di bumi. Ingatlah, bahwa sesungguhnya Allah Dialah Yang Maha Pengampun lagi Penyayang.'),
  ('id.indonesian', 42, 6, 'Dan orang-orang yang mengambil pelindung-pelindung selain Allah, Allah mengawasi (perbuatan) mereka; dan kamu (ya Muhammad) bukanlah orang yang diserahi mengawasi mereka.'),
  ('id.indonesian', 42, 7, 'Demikianlah Kami wahyukan kepadamu Al Quran dalam bahasa Arab, supaya kamu memberi peringatan kepada ummul Qura (penduduk Mekah) dan penduduk (negeri-negeri) sekelilingnya serta memberi peringatan (pula) tentang hari berkumpul (kiamat) yang tidak ada keraguan padanya. Segolongan masuk surga, dan segolongan masuk Jahannam.'),
  ('id.indonesian', 42, 8, 'Dan kalau Allah menghendaki niscaya Allah menjadikan mereka satu umat (saja), tetapi Dia memasukkan orang-orang yang dikehendaki-Nya ke dalam rahmat-Nya. Dan orang-orang yang zalim tidak ada bagi mereka seorang pelindungpun dan tidak pula seorang penolong.'),
  ('id.indonesian', 42, 9, 'Atau patutkah mereka mengambil pelindung-pelindung selain Allah? Maka Allah, Dialah pelindung (yang sebenarnya) dan Dia menghidupkan orang-orang yang mati, dan Dia adalah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 42, 10, 'Tentang sesuatu apapun kamu berselisih, maka putusannya (terserah) kepada Allah. (Yang mempunyai sifat-sifat demikian) itulah Allah Tuhanku. Kepada-Nya lah aku bertawakkal dan kepada-Nya-lah aku kembali.'),
  ('id.indonesian', 42, 11, '(Dia) Pencipta langit dan bumi. Dia menjadikan bagi kamu dari jenis kamu sendiri pasangan-pasangan dan dari jenis binatang ternak pasangan-pasangan (pula), dijadikan-Nya kamu berkembang biak dengan jalan itu. Tidak ada sesuatupun yang serupa dengan Dia, dan Dialah yang Maha Mendengar dan Melihat.'),
  ('id.indonesian', 42, 12, 'Kepunyaan-Nya-lah perbendaharaan langit dan bumi; Dia melapangkan rezeki bagi siapa yang dikehendaki-Nya dan menyempitkan(nya). Sesungguhnya Dia Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 42, 13, 'Dia telah mensyari\'atkan bagi kamu tentang agama apa yang telah diwasiatkan-Nya kepada Nuh dan apa yang telah Kami wahyukan kepadamu dan apa yang telah Kami wasiatkan kepada Ibrahim, Musa dan Isa yaitu: Tegakkanlah agama dan janganlah kamu berpecah belah tentangnya. Amat berat bagi orang-orang musyrik agama yang kamu seru mereka kepadanya. Allah menarik kepada agama itu orang yang dikehendaki-Nya dan memberi petunjuk kepada (agama)-Nya orang yang kembali (kepada-Nya).'),
  ('id.indonesian', 42, 14, 'Dan mereka (ahli kitab) tidak berpecah belah, kecuali setelah datang pada mereka ilmu pengetahuan, karena kedengkian di antara mereka. Kalau tidaklah karena sesuatu ketetapan yang telah ada dari Tuhanmu dahulunya (untuk menangguhkan azab) sampai kepada waktu yang ditentukan, pastilah mereka telah dibinasakan. Dan sesungguhnya orang-orang yang diwariskan kepada mereka Al-Kitab (Taurat dan Injil) sesudah mereka, benar-benar berada dalam keraguan yang menggoncangkan tentang kitab itu.'),
  ('id.indonesian', 42, 15, 'Maka karena itu serulah (mereka kepada agama ini) dan tetaplah sebagai mana diperintahkan kepadamu dan janganlah mengikuti hawa nafsu mereka dan katakanlah: "Aku beriman kepada semua Kitab yang diturunkan Allah dan aku diperintahkan supaya berlaku adil diantara kamu. Allah-lah Tuhan kami dan Tuhan kamu. Bagi kami amal-amal kami dan bagi kamu amal-amal kamu. Tidak ada pertengkaran antara kami dan kamu, Allah mengumpulkan antara kita dan kepada-Nya-lah kembali (kita)".'),
  ('id.indonesian', 42, 16, 'Dan orang-orang yang membantah (agama) Allah sesudah agama itu diterima maka bantahan mereka itu sia-sia saja, di sisi Tuhan mereka. Mereka mendapat kemurkaan (Allah) dan bagi mereka azab yang sangat keras.'),
  ('id.indonesian', 42, 17, 'Allah-lah yang menurunkan kitab dengan (membawa) kebenaran dan (menurunkan) neraca (keadilan). Dan tahukah kamu, boleh jadi hari kiamat itu (sudah) dekat?'),
  ('id.indonesian', 42, 18, 'Orang-orang yang tidak beriman kepada hari kiamat meminta supaya hari itu segera didatangkan dan orang-orang yang beriman merasa takut kepadanya dan mereka yakin bahwa kiamat itu adalah benar (akan terjadi). Ketahuilah bahwa sesungguhnya orang-orang yang membantah tentang terjadinya kiamat itu benar-benar dalam kesesatan yang jauh.'),
  ('id.indonesian', 42, 19, 'Allah Maha lembut terhadap hamba-hamba-Nya; Dia memberi rezeki kepada yang di kehendaki-Nya dan Dialah Yang Maha Kuat lagi Maha Perkasa.'),
  ('id.indonesian', 42, 20, 'Barang siapa yang menghendaki keuntungan di akhirat akan Kami tambah keuntungan itu baginya dan barang siapa yang menghendaki keuntungan di dunia Kami berikan kepadanya sebagian dari keuntungan dunia dan tidak ada baginya suatu bahagianpun di akhirat.'),
  ('id.indonesian', 42, 21, 'Apakah mereka mempunyai sembahan-sembahan selain Allah yang mensyariatkan untuk mereka agama yang tidak diizinkan Allah? Sekiranya tak ada ketetapan yang menentukan (dari Allah) tentulah mereka telah dibinasakan. Dan sesungguhnya orang-orang yang zalim itu akan memperoleh azab yang amat pedih.'),
  ('id.indonesian', 42, 22, 'Kamu lihat orang-orang yang zalim sangat ketakutan karena kejahatan-kejahatan yang telah mereka kerjakan, sedang siksaan menimpa mereka. Dan orang-orang yang beriman serta mengerjakan amal saleh (berada) di dalam taman-taman surga, mereka memperoleh apa yang mereka kehendaki di sisi Tuhan mereka. Yang demikian itu adalah karunia yang besar.'),
  ('id.indonesian', 42, 23, 'Itulah (karunia) yang (dengan itu) Allah menggembirakan hamba-hamba-Nya yang beriman dan mengerjakan amal yang saleh. Katakanlah: "Aku tidak meminta kepadamu sesuatu upahpun atas seruanku kecuali kasih sayang dalam kekeluargaan". Dan siapa yang mengerjakan kebaikan akan Kami tambahkan baginya kebaikan pada kebaikannya itu. Sesungguhnya Allah Maha Pengampun lagi Maha Mensyukuri.'),
  ('id.indonesian', 42, 24, 'Bahkan mereka mengatakan: "Dia (Muhammad) telah mengada-adakan dusta terhadap Allah". Maka jika Allah menghendaki niscaya Dia mengunci mati hatimu; dan Allah menghapuskan yang batil dan membenarkan yang hak dengan kalimat-kalimat-Nya (Al Quran). Sesungguhnya Dia Maha Mengetahui segala isi hati.'),
  ('id.indonesian', 42, 25, 'Dan Dialah yang menerima taubat dari hamba-hamba-Nya dan memaafkan kesalahan-kesalahan dan mengetahui apa yang kamu kerjakan,'),
  ('id.indonesian', 42, 26, 'dan Dia memperkenankan (doa) orang-orang yang beriman serta mengerjakan amal yang saleh dan menambah (pahala) kepada mereka dari karunia-Nya. Dan orang-orang yang kafir bagi mereka azab yang sangat keras.'),
  ('id.indonesian', 42, 27, 'Dan jikalau Allah melapangkan rezeki kepada hamba-hamba-Nya tentulah mereka akan melampaui batas di muka bumi, tetapi Allah menurunkan apa yang dikehendaki-Nya dengan ukuran. Sesungguhnya Dia Maha Mengetahui (keadaan) hamba-hamba-Nya lagi Maha Melihat.'),
  ('id.indonesian', 42, 28, 'Dan Dialah Yang menurunkan hujan sesudah mereka berputus asa dan menyebarkan rahmat-Nya. Dan Dialah Yang Maha Pelindung lagi Maha Terpuji.'),
  ('id.indonesian', 42, 29, 'Di antara (ayat-ayat) tanda-tanda-Nya ialah menciptakan langit dan bumi dan makhluk-makhluk yang melata Yang Dia sebarkan pada keduanya. Dan Dia Maha Kuasa mengumpulkan semuanya apabila dikehendaki-Nya.'),
  ('id.indonesian', 42, 30, 'Dan apa saja musibah yang menimpa kamu maka adalah disebabkan oleh perbuatan tanganmu sendiri, dan Allah memaafkan sebagian besar (dari kesalahan-kesalahanmu).'),
  ('id.indonesian', 42, 31, 'Dan kamu tidak dapat melepaskan diri (dari azab Allah) di muka bumi, dan kamu tidak memperoleh seorang pelindung dan tidak pula penolong selain Allah.'),
  ('id.indonesian', 42, 32, 'Dan di antara tanda-tanda kekuasaan-Nya ialah kapal-kapal di tengah (yang berlayar) di laut seperti gunung-gunung.'),
  ('id.indonesian', 42, 33, 'Jika Dia menghendaki, Dia akan menenangkan angin, maka jadilah kapal-kapal itu terhenti di permukaan laut. Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaannya) bagi setiap orang yang banyak bersabar dan banyak bersyukur,'),
  ('id.indonesian', 42, 34, 'atau kapal-kapal itu dibinasakan-Nya karena perbuatan mereka atau Dia memberi maaf sebagian besar (dari mereka).'),
  ('id.indonesian', 42, 35, 'Dan supaya orang-orang yang membantah ayat-ayat (kekuasaan) Kami mengetahui bahwa mereka sekali-kali tidak akan memperoleh jalan ke luar (dari siksaan).'),
  ('id.indonesian', 42, 36, 'Maka sesuatu yang diberikan kepadamu, itu adalah kenikmatan hidup di dunia; dan yang ada pada sisi Allah lebih baik dan lebih kekal bagi orang-orang yang beriman, dan hanya kepada Tuhan mereka, mereka bertawakkal.'),
  ('id.indonesian', 42, 37, 'Dan (bagi) orang-orang yang menjauhi dosa-dosa besar dan perbuatan-perbuatan keji, dan apabila mereka marah mereka memberi maaf.'),
  ('id.indonesian', 42, 38, 'Dan (bagi) orang-orang yang menerima (mematuhi) seruan Tuhannya dan mendirikan shalat, sedang urusan mereka (diputuskan) dengan musyawarat antara mereka; dan mereka menafkahkan sebagian dari rezeki yang Kami berikan kepada mereka.'),
  ('id.indonesian', 42, 39, 'Dan ( bagi) orang-orang yang apabila mereka diperlakukan dengan zalim mereka membela diri.'),
  ('id.indonesian', 42, 40, 'Dan balasan suatu kejahatan adalah kejahatan yang serupa, maka barang siapa memaafkan dan berbuat baik maka pahalanya atas (tanggungan) Allah. Sesungguhnya Dia tidak menyukai orang-orang yang zalim.'),
  ('id.indonesian', 42, 41, 'Dan sesungguhnya orang-orang yang membela diri sesudah teraniaya, tidak ada satu dosapun terhadap mereka.'),
  ('id.indonesian', 42, 42, 'Sesungguhnya dosa itu atas orang-orang yang berbuat zalim kepada manusia dan melampaui batas di muka bumi tanpa hak. Mereka itu mendapat azab yang pedih.'),
  ('id.indonesian', 42, 43, 'Tetapi orang yang bersabar dan memaafkan, sesungguhnya (perbuatan) yang demikian itu termasuk hal-hal yang diutamakan.'),
  ('id.indonesian', 42, 44, 'Dan siapa yang disesatkan Allah maka tidak ada baginya seorang pemimpinpun sesudah itu. Dan kamu akan melihat orang-orang yang zalim ketika mereka melihat azab berkata: "Adakah kiranya jalan untuk kembali (ke dunia)?"'),
  ('id.indonesian', 42, 45, 'Dan kamu akan melihat mereka dihadapkan ke neraka dalam keadaan tunduk karena (merasa) hina, mereka melihat dengan pandangan yang lesu. Dan orang-orang yang beriman berkata: "Sesungguhnya orang-orang yang merugi ialah orang-orang yang kehilangan diri mereka sendiri dan (kehilangan) keluarga mereka pada hari kiamat. Ingatlah, sesungguhnya orang-orang yang zalim itu berada dalam azab yang kekal.'),
  ('id.indonesian', 42, 46, 'Dan mereka sekali-kali tidak mempunyai pelindung-pelindung yang dapat menolong mereka selain Allah. Dan siapa yang disesatkan Allah maka tidaklah ada baginya satu jalanpun (untuk mendapat petunjuk).'),
  ('id.indonesian', 42, 47, 'Patuhilah seruan Tuhanmu sebelum datang dari Allah suatu hari yang tidak dapat ditolak kedatangannya. Kamu tidak memperoleh tempat berlindung pada hari itu dan tidak (pula) dapat mengingkari (dosa-dosamu).'),
  ('id.indonesian', 42, 48, 'Jika mereka berpaling maka Kami tidak mengutus kamu sebagai pengawas bagi mereka. Kewajibanmu tidak lain hanyalah menyampaikan (risalah). Sesungguhnya apabila Kami merasakan kepada manusia sesuatu rahmat dari Kami dia bergembira ria karena rahmat itu. Dan jika mereka ditimpa kesusahan disebabkan perbuatan tangan mereka sendiri (niscaya mereka ingkar) karena sesungguhnya manusia itu amat ingkar (kepada nikmat).'),
  ('id.indonesian', 42, 49, 'Kepunyaan Allah-lah kerajaan langit dan bumi, Dia menciptakan apa yang Dia kehendaki. Dia memberikan anak-anak perempuan kepada siapa yang Dia kehendaki dan memberikan anak-anak lelaki kepada siapa yang Dia kehendaki,'),
  ('id.indonesian', 42, 50, 'atau Dia menganugerahkan kedua jenis laki-laki dan perempuan (kepada siapa) yang dikehendaki-Nya, dan Dia menjadikan mandul siapa yang Dia kehendaki. Sesungguhnya Dia Maha Mengetahui lagi Maha Kuasa.'),
  ('id.indonesian', 42, 51, 'Dan tidak mungkin bagi seorang manusiapun bahwa Allah berkata-kata dengan dia kecuali dengan perantaraan wahyu atau dibelakang tabir atau dengan mengutus seorang utusan (malaikat) lalu diwahyukan kepadanya dengan seizin-Nya apa yang Dia kehendaki. Sesungguhnya Dia Maha Tinggi lagi Maha Bijaksana.'),
  ('id.indonesian', 42, 52, 'Dan demikianlah Kami wahyukan kepadamu wahyu (Al Quran) dengan perintah Kami. Sebelumnya kamu tidaklah mengetahui apakah Al Kitab (Al Quran) dan tidak pula mengetahui apakah iman itu, tetapi Kami menjadikan Al Quran itu cahaya, yang Kami tunjuki dengan dia siapa yang kami kehendaki di antara hamba-hamba Kami. Dan sesungguhnya kamu benar-benar memberi petunjuk kepada jalan yang lurus.'),
  ('id.indonesian', 42, 53, '(Yaitu) jalan Allah yang kepunyaan-Nya segala apa yang ada di langit dan apa yang ada di bumi. Ingatlah, bahwa kepada Allah-lah kembali semua urusan.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (40, 68, 4201, 'هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ ۖ فَإِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ', 475, 24, 190, 0),
  (40, 69, 4202, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ', 475, 24, 190, 0),
  (40, 70, 4203, 'ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا ۖ فَسَوْفَ يَعْلَمُونَ', 475, 24, 190, 0),
  (40, 71, 4204, 'إِذِ ٱلْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَٱلسَّلَٰسِلُ يُسْحَبُونَ', 475, 24, 190, 0),
  (40, 72, 4205, 'فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ', 475, 24, 190, 0),
  (40, 73, 4206, 'ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ', 475, 24, 190, 0),
  (40, 74, 4207, 'مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًۭٔا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَٰفِرِينَ', 475, 24, 190, 0),
  (40, 75, 4208, 'ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ', 475, 24, 190, 0),
  (40, 76, 4209, 'ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا ۖ فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ', 475, 24, 190, 0),
  (40, 77, 4210, 'فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ ۚ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ', 475, 24, 190, 0),
  (40, 78, 4211, 'وَلَقَدْ أَرْسَلْنَا رُسُلًۭا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ ۗ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۚ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ', 476, 24, 190, 0),
  (40, 79, 4212, 'ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ', 476, 24, 190, 0),
  (40, 80, 4213, 'وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةًۭ فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ', 476, 24, 190, 0),
  (40, 81, 4214, 'وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ', 476, 24, 190, 0),
  (40, 82, 4215, 'أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةًۭ وَءَاثَارًۭا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ', 476, 24, 190, 0),
  (40, 83, 4216, 'فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 476, 24, 190, 0),
  (40, 84, 4217, 'فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ', 476, 24, 190, 0),
  (40, 85, 4218, 'فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا ۖ سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ ۖ وَخَسِرَ هُنَالِكَ ٱلْكَٰفِرُونَ', 476, 24, 190, 0),
  (41, 1, 4219, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 477, 24, 190, 0),
  (41, 2, 4220, 'تَنزِيلٌۭ مِّنَ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ', 477, 24, 190, 0),
  (41, 3, 4221, 'كِتَٰبٌۭ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّۭا لِّقَوْمٍۢ يَعْلَمُونَ', 477, 24, 190, 0),
  (41, 4, 4222, 'بَشِيرًۭا وَنَذِيرًۭا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ', 477, 24, 190, 0),
  (41, 5, 4223, 'وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍۢ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌۭ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌۭ فَٱعْمَلْ إِنَّنَا عَٰمِلُونَ', 477, 24, 190, 0),
  (41, 6, 4224, 'قُلْ إِنَّمَآ أَنَا۠ بَشَرٌۭ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌۭ وَٰحِدٌۭ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ ۗ وَوَيْلٌۭ لِّلْمُشْرِكِينَ', 477, 24, 190, 0),
  (41, 7, 4225, 'ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْءَاخِرَةِ هُمْ كَٰفِرُونَ', 477, 24, 190, 0),
  (41, 8, 4226, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۢ', 477, 24, 190, 0),
  (41, 9, 4227, '۞ قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًۭا ۚ ذَٰلِكَ رَبُّ ٱلْعَٰلَمِينَ', 477, 24, 191, 0),
  (41, 10, 4228, 'وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍۢ سَوَآءًۭ لِّلسَّآئِلِينَ', 477, 24, 191, 0),
  (41, 11, 4229, 'ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌۭ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًۭا قَالَتَآ أَتَيْنَا طَآئِعِينَ', 477, 24, 191, 0),
  (41, 12, 4230, 'فَقَضَىٰهُنَّ سَبْعَ سَمَٰوَاتٍۢ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا ۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَحِفْظًۭا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ', 478, 24, 191, 0),
  (41, 13, 4231, 'فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَٰعِقَةًۭ مِّثْلَ صَٰعِقَةِ عَادٍۢ وَثَمُودَ', 478, 24, 191, 0),
  (41, 14, 4232, 'إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ ۖ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةًۭ فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 478, 24, 191, 0),
  (41, 15, 4233, 'فَأَمَّا عَادٌۭ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً ۖ أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةًۭ ۖ وَكَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 478, 24, 191, 0),
  (41, 16, 4234, 'فَأَرْسَلْنَا عَلَيْهِمْ رِيحًۭا صَرْصَرًۭا فِىٓ أَيَّامٍۢ نَّحِسَاتٍۢ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَخْزَىٰ ۖ وَهُمْ لَا يُنصَرُونَ', 478, 24, 191, 0),
  (41, 17, 4235, 'وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ', 478, 24, 191, 0),
  (41, 18, 4236, 'وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ', 478, 24, 191, 0),
  (41, 19, 4237, 'وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ', 478, 24, 191, 0),
  (41, 20, 4238, 'حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ', 478, 24, 191, 0),
  (41, 21, 4239, 'وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا ۖ قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍۢ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍۢ وَإِلَيْهِ تُرْجَعُونَ', 479, 24, 191, 0),
  (41, 22, 4240, 'وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًۭا مِّمَّا تَعْمَلُونَ', 479, 24, 191, 0),
  (41, 23, 4241, 'وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ', 479, 24, 191, 0),
  (41, 24, 4242, 'فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًۭى لَّهُمْ ۖ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ', 479, 24, 191, 0),
  (41, 25, 4243, '۞ وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍۢ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 479, 24, 192, 0),
  (41, 26, 4244, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ', 479, 24, 192, 0),
  (41, 27, 4245, 'فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًۭا شَدِيدًۭا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ', 479, 24, 192, 0),
  (41, 28, 4246, 'ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ ۖ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ ۖ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ', 479, 24, 192, 0),
  (41, 29, 4247, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ', 479, 24, 192, 0),
  (41, 30, 4248, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ', 480, 24, 192, 0),
  (41, 31, 4249, 'نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْءَاخِرَةِ ۖ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ', 480, 24, 192, 0),
  (41, 32, 4250, 'نُزُلًۭا مِّنْ غَفُورٍۢ رَّحِيمٍۢ', 480, 24, 192, 0),
  (41, 33, 4251, 'وَمَنْ أَحْسَنُ قَوْلًۭا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًۭا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ', 480, 24, 192, 0),
  (41, 34, 4252, 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌۭ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌۭ', 480, 24, 192, 0),
  (41, 35, 4253, 'وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍۢ', 480, 24, 192, 0),
  (41, 36, 4254, 'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌۭ فَٱسْتَعِذْ بِٱللَّهِ ۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 480, 24, 192, 0),
  (41, 37, 4255, 'وَمِنْ ءَايَٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ ۚ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ', 480, 24, 192, 0),
  (41, 38, 4256, 'فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ ۩', 480, 24, 192, 1),
  (41, 39, 4257, 'وَمِنْ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَٰشِعَةًۭ فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ ۚ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ ۚ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 481, 24, 192, 0),
  (41, 40, 4258, 'إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ ۗ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًۭا يَوْمَ ٱلْقِيَٰمَةِ ۚ ٱعْمَلُوا۟ مَا شِئْتُمْ ۖ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ', 481, 24, 192, 0),
  (41, 41, 4259, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ ۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌۭ', 481, 24, 192, 0),
  (41, 42, 4260, 'لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ ۖ تَنزِيلٌۭ مِّنْ حَكِيمٍ حَمِيدٍۢ', 481, 24, 192, 0),
  (41, 43, 4261, 'مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ ۚ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍۢ وَذُو عِقَابٍ أَلِيمٍۢ', 481, 24, 192, 0),
  (41, 44, 4262, 'وَلَوْ جَعَلْنَٰهُ قُرْءَانًا أَعْجَمِيًّۭا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَٰتُهُۥٓ ۖ ءَا۬عْجَمِىٌّۭ وَعَرَبِىٌّۭ ۗ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًۭى وَشِفَآءٌۭ ۖ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌۭ وَهُوَ عَلَيْهِمْ عَمًى ۚ أُو۟لَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍۢ', 481, 24, 192, 0),
  (41, 45, 4263, 'وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ ۗ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ ۚ وَإِنَّهُمْ لَفِى شَكٍّۢ مِّنْهُ مُرِيبٍۢ', 481, 24, 192, 0),
  (41, 46, 4264, 'مَّنْ عَمِلَ صَٰلِحًۭا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۗ وَمَا رَبُّكَ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 481, 24, 192, 0),
  (41, 47, 4265, '۞ إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ ۚ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍۢ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ ۚ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٍۢ', 482, 25, 193, 0),
  (41, 48, 4266, 'وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ ۖ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍۢ', 482, 25, 193, 0),
  (41, 49, 4267, 'لَّا يَسْـَٔمُ ٱلْإِنسَٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌۭ قَنُوطٌۭ', 482, 25, 193, 0),
  (41, 50, 4268, 'وَلَئِنْ أَذَقْنَٰهُ رَحْمَةًۭ مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةًۭ وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ ۚ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍۢ', 482, 25, 193, 0),
  (41, 51, 4269, 'وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍۢ', 482, 25, 193, 0),
  (41, 52, 4270, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍۢ', 482, 25, 193, 0),
  (41, 53, 4271, 'سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْءَافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 482, 25, 193, 0),
  (41, 54, 4272, 'أَلَآ إِنَّهُمْ فِى مِرْيَةٍۢ مِّن لِّقَآءِ رَبِّهِمْ ۗ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍۢ مُّحِيطٌۢ', 482, 25, 193, 0),
  (42, 1, 4273, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 483, 25, 193, 0),
  (42, 2, 4274, 'عٓسٓقٓ', 483, 25, 193, 0),
  (42, 3, 4275, 'كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ', 483, 25, 193, 0),
  (42, 4, 4276, 'لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 483, 25, 193, 0),
  (42, 5, 4277, 'تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ ۚ وَٱلْمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ ۗ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 483, 25, 193, 0),
  (42, 6, 4278, 'وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍۢ', 483, 25, 193, 0),
  (42, 7, 4279, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّۭا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ ۚ فَرِيقٌۭ فِى ٱلْجَنَّةِ وَفَرِيقٌۭ فِى ٱلسَّعِيرِ', 483, 25, 193, 0),
  (42, 8, 4280, 'وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةًۭ وَٰحِدَةًۭ وَلَٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِىٍّۢ وَلَا نَصِيرٍ', 483, 25, 193, 0),
  (42, 9, 4281, 'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۖ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 483, 25, 193, 0),
  (42, 10, 4282, 'وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍۢ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ', 483, 25, 193, 0),
  (42, 11, 4283, 'فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًۭا ۖ يَذْرَؤُكُمْ فِيهِ ۚ لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ', 484, 25, 193, 0),
  (42, 12, 4284, 'لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 484, 25, 193, 0),
  (42, 13, 4285, '۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًۭا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ ۖ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ ۚ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ۚ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ', 484, 25, 194, 0),
  (42, 14, 4286, 'وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى لَّقُضِىَ بَيْنَهُمْ ۚ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّۢ مِّنْهُ مُرِيبٍۢ', 484, 25, 194, 0),
  (42, 15, 4287, 'فَلِذَٰلِكَ فَٱدْعُ ۖ وَٱسْتَقِمْ كَمَآ أُمِرْتَ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ ۖ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٍۢ ۖ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ ۖ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ ۖ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ۖ ٱللَّهُ يَجْمَعُ بَيْنَنَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 484, 25, 194, 0),
  (42, 16, 4288, 'وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌۭ وَلَهُمْ عَذَابٌۭ شَدِيدٌ', 485, 25, 194, 0),
  (42, 17, 4289, 'ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ ۗ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌۭ', 485, 25, 194, 0),
  (42, 18, 4290, 'يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا ۖ وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ ۗ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَٰلٍۭ بَعِيدٍ', 485, 25, 194, 0),
  (42, 19, 4291, 'ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ ۖ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ', 485, 25, 194, 0),
  (42, 20, 4292, 'مَن كَانَ يُرِيدُ حَرْثَ ٱلْءَاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ ۖ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْءَاخِرَةِ مِن نَّصِيبٍ', 485, 25, 194, 0),
  (42, 21, 4293, 'أَمْ لَهُمْ شُرَكَٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ ۚ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ ۗ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌۭ', 485, 25, 194, 0),
  (42, 22, 4294, 'تَرَى ٱلظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ ۗ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ ۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ۚ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ', 485, 25, 194, 0),
  (42, 23, 4295, 'ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ ۗ وَمَن يَقْتَرِفْ حَسَنَةًۭ نَّزِدْ لَهُۥ فِيهَا حُسْنًا ۚ إِنَّ ٱللَّهَ غَفُورٌۭ شَكُورٌ', 486, 25, 194, 0),
  (42, 24, 4296, 'أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًۭا ۖ فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ ۗ وَيَمْحُ ٱللَّهُ ٱلْبَٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَٰتِهِۦٓ ۚ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 486, 25, 194, 0),
  (42, 25, 4297, 'وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ', 486, 25, 194, 0),
  (42, 26, 4298, 'وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۚ وَٱلْكَٰفِرُونَ لَهُمْ عَذَابٌۭ شَدِيدٌۭ', 486, 25, 194, 0),
  (42, 27, 4299, '۞ وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍۢ مَّا يَشَآءُ ۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌۭ', 486, 25, 195, 0),
  (42, 28, 4300, 'وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ ۚ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ', 486, 25, 195, 0),
  (42, 29, 4301, 'وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍۢ ۚ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌۭ', 486, 25, 195, 0),
  (42, 30, 4302, 'وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍۢ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍۢ', 486, 25, 195, 0),
  (42, 31, 4303, 'وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ ۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍۢ', 486, 25, 195, 0),
  (42, 32, 4304, 'وَمِنْ ءَايَٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 487, 25, 195, 0),
  (42, 33, 4305, 'إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّكُلِّ صَبَّارٍۢ شَكُورٍ', 487, 25, 195, 0),
  (42, 34, 4306, 'أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍۢ', 487, 25, 195, 0),
  (42, 35, 4307, 'وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍۢ', 487, 25, 195, 0),
  (42, 36, 4308, 'فَمَآ أُوتِيتُم مِّن شَىْءٍۢ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَمَا عِندَ ٱللَّهِ خَيْرٌۭ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ', 487, 25, 195, 0),
  (42, 37, 4309, 'وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ', 487, 25, 195, 0),
  (42, 38, 4310, 'وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ', 487, 25, 195, 0),
  (42, 39, 4311, 'وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ', 487, 25, 195, 0),
  (42, 40, 4312, 'وَجَزَٰٓؤُا۟ سَيِّئَةٍۢ سَيِّئَةٌۭ مِّثْلُهَا ۖ فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ', 487, 25, 195, 0),
  (42, 41, 4313, 'وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ', 487, 25, 195, 0),
  (42, 42, 4314, 'إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ ۚ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌۭ', 487, 25, 195, 0),
  (42, 43, 4315, 'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ', 487, 25, 195, 0),
  (42, 44, 4316, 'وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّۢ مِّنۢ بَعْدِهِۦ ۗ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّۢ مِّن سَبِيلٍۢ', 487, 25, 195, 0),
  (42, 45, 4317, 'وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّۢ ۗ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ ۗ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِى عَذَابٍۢ مُّقِيمٍۢ', 488, 25, 195, 0),
  (42, 46, 4318, 'وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ ۗ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ', 488, 25, 195, 0),
  (42, 47, 4319, 'ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ ۚ مَا لَكُم مِّن مَّلْجَإٍۢ يَوْمَئِذٍۢ وَمَا لَكُم مِّن نَّكِيرٍۢ', 488, 25, 195, 0),
  (42, 48, 4320, 'فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا ۖ إِنْ عَلَيْكَ إِلَّا ٱلْبَلَٰغُ ۗ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةًۭ فَرِحَ بِهَا ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَٰنَ كَفُورٌۭ', 488, 25, 195, 0),
  (42, 49, 4321, 'لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ يَخْلُقُ مَا يَشَآءُ ۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثًۭا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ', 488, 25, 195, 0),
  (42, 50, 4322, 'أَوْ يُزَوِّجُهُمْ ذُكْرَانًۭا وَإِنَٰثًۭا ۖ وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا ۚ إِنَّهُۥ عَلِيمٌۭ قَدِيرٌۭ', 488, 25, 195, 0),
  (42, 51, 4323, '۞ وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًۭا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ ۚ إِنَّهُۥ عَلِىٌّ حَكِيمٌۭ', 488, 25, 196, 0),
  (42, 52, 4324, 'وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًۭا مِّنْ أَمْرِنَا ۚ مَا كُنتَ تَدْرِى مَا ٱلْكِتَٰبُ وَلَا ٱلْإِيمَٰنُ وَلَٰكِن جَعَلْنَٰهُ نُورًۭا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا ۚ وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 489, 25, 196, 0),
  (42, 53, 4325, 'صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ', 489, 25, 196, 0),
  (43, 1, 4326, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 489, 25, 196, 0),
  (43, 2, 4327, 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', 489, 25, 196, 0),
  (43, 3, 4328, 'إِنَّا جَعَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّۭا لَّعَلَّكُمْ تَعْقِلُونَ', 489, 25, 196, 0),
  (43, 4, 4329, 'وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ', 489, 25, 196, 0),
  (43, 5, 4330, 'أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًۭا مُّسْرِفِينَ', 489, 25, 196, 0),
  (43, 6, 4331, 'وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّۢ فِى ٱلْأَوَّلِينَ', 489, 25, 196, 0),
  (43, 7, 4332, 'وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 489, 25, 196, 0),
  (43, 8, 4333, 'فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًۭا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ', 489, 25, 196, 0),
  (43, 9, 4334, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ', 489, 25, 196, 0),
  (43, 10, 4335, 'ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًۭا وَجَعَلَ لَكُمْ فِيهَا سُبُلًۭا لَّعَلَّكُمْ تَهْتَدُونَ', 489, 25, 196, 0),
  (43, 11, 4336, 'وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍۢ فَأَنشَرْنَا بِهِۦ بَلْدَةًۭ مَّيْتًۭا ۚ كَذَٰلِكَ تُخْرَجُونَ', 490, 25, 196, 0),
  (43, 12, 4337, 'وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَٰمِ مَا تَرْكَبُونَ', 490, 25, 196, 0),
  (43, 13, 4338, 'لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', 490, 25, 196, 0),
  (43, 14, 4339, 'وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ', 490, 25, 196, 0),
  (43, 15, 4340, 'وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا ۚ إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌۭ مُّبِينٌ', 490, 25, 196, 0),
  (43, 16, 4341, 'أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍۢ وَأَصْفَىٰكُم بِٱلْبَنِينَ', 490, 25, 196, 0),
  (43, 17, 4342, 'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَٰنِ مَثَلًۭا ظَلَّ وَجْهُهُۥ مُسْوَدًّۭا وَهُوَ كَظِيمٌ', 490, 25, 196, 0),
  (43, 18, 4343, 'أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍۢ', 490, 25, 196, 0),
  (43, 19, 4344, 'وَجَعَلُوا۟ ٱلْمَلَٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَٰدُ ٱلرَّحْمَٰنِ إِنَٰثًا ۚ أَشَهِدُوا۟ خَلْقَهُمْ ۚ سَتُكْتَبُ شَهَٰدَتُهُمْ وَيُسْـَٔلُونَ', 490, 25, 196, 0),
  (43, 20, 4345, 'وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَٰنُ مَا عَبَدْنَٰهُم ۗ مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَخْرُصُونَ', 490, 25, 196, 0),
  (43, 21, 4346, 'أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًۭا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ', 490, 25, 196, 0),
  (43, 22, 4347, 'بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ', 490, 25, 196, 0),
  (43, 23, 4348, 'وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍۢ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ', 491, 25, 196, 0),
  (43, 24, 4349, '۞ قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ ۖ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ', 491, 25, 197, 0),
  (43, 25, 4350, 'فَٱنتَقَمْنَا مِنْهُمْ ۖ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ', 491, 25, 197, 0),
  (43, 26, 4351, 'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌۭ مِّمَّا تَعْبُدُونَ', 491, 25, 197, 0),
  (43, 27, 4352, 'إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ', 491, 25, 197, 0),
  (43, 28, 4353, 'وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةًۭ فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ', 491, 25, 197, 0),
  (43, 29, 4354, 'بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌۭ مُّبِينٌۭ', 491, 25, 197, 0),
  (43, 30, 4355, 'وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَٰذَا سِحْرٌۭ وَإِنَّا بِهِۦ كَٰفِرُونَ', 491, 25, 197, 0),
  (43, 31, 4356, 'وَقَالُوا۟ لَوْلَا نُزِّلَ هَٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍۢ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ', 491, 25, 197, 0),
  (43, 32, 4357, 'أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ ۚ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍۢ دَرَجَٰتٍۢ لِّيَتَّخِذَ بَعْضُهُم بَعْضًۭا سُخْرِيًّۭا ۗ وَرَحْمَتُ رَبِّكَ خَيْرٌۭ مِّمَّا يَجْمَعُونَ', 491, 25, 197, 0),
  (43, 33, 4358, 'وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةًۭ وَٰحِدَةًۭ لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًۭا مِّن فِضَّةٍۢ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ', 491, 25, 197, 0),
  (43, 34, 4359, 'وَلِبُيُوتِهِمْ أَبْوَٰبًۭا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ', 492, 25, 197, 0),
  (43, 35, 4360, 'وَزُخْرُفًۭا ۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَٱلْءَاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ', 492, 25, 197, 0),
  (43, 36, 4361, 'وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًۭا فَهُوَ لَهُۥ قَرِينٌۭ', 492, 25, 197, 0),
  (43, 37, 4362, 'وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ', 492, 25, 197, 0),
  (43, 38, 4363, 'حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ', 492, 25, 197, 0),
  (43, 39, 4364, 'وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ', 492, 25, 197, 0),
  (43, 40, 4365, 'أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 492, 25, 197, 0),
  (43, 41, 4366, 'فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ', 492, 25, 197, 0),
  (43, 42, 4367, 'أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ', 492, 25, 197, 0),
  (43, 43, 4368, 'فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ ۖ إِنَّكَ عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 492, 25, 197, 0),
  (43, 44, 4369, 'وَإِنَّهُۥ لَذِكْرٌۭ لَّكَ وَلِقَوْمِكَ ۖ وَسَوْفَ تُسْـَٔلُونَ', 492, 25, 197, 0),
  (43, 45, 4370, 'وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةًۭ يُعْبَدُونَ', 492, 25, 197, 0),
  (43, 46, 4371, 'وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ', 492, 25, 197, 0),
  (43, 47, 4372, 'فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ', 492, 25, 197, 0),
  (43, 48, 4373, 'وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا ۖ وَأَخَذْنَٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ', 493, 25, 197, 0),
  (43, 49, 4374, 'وَقَالُوا۟ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ', 493, 25, 197, 0),
  (43, 50, 4375, 'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ', 493, 25, 197, 0),
  (43, 51, 4376, 'وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَٰذِهِ ٱلْأَنْهَٰرُ تَجْرِى مِن تَحْتِىٓ ۖ أَفَلَا تُبْصِرُونَ', 493, 25, 197, 0),
  (43, 52, 4377, 'أَمْ أَنَا۠ خَيْرٌۭ مِّنْ هَٰذَا ٱلَّذِى هُوَ مَهِينٌۭ وَلَا يَكَادُ يُبِينُ', 493, 25, 197, 0),
  (43, 53, 4378, 'فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌۭ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَٰٓئِكَةُ مُقْتَرِنِينَ', 493, 25, 197, 0),
  (43, 54, 4379, 'فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ', 493, 25, 197, 0),
  (43, 55, 4380, 'فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ', 493, 25, 197, 0),
  (43, 56, 4381, 'فَجَعَلْنَٰهُمْ سَلَفًۭا وَمَثَلًۭا لِّلْءَاخِرِينَ', 493, 25, 197, 0),
  (43, 57, 4382, '۞ وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ', 493, 25, 198, 0),
  (43, 58, 4383, 'وَقَالُوٓا۟ ءَأَٰلِهَتُنَا خَيْرٌ أَمْ هُوَ ۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا ۚ بَلْ هُمْ قَوْمٌ خَصِمُونَ', 493, 25, 198, 0),
  (43, 59, 4384, 'إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلًۭا لِّبَنِىٓ إِسْرَٰٓءِيلَ', 493, 25, 198, 0),
  (43, 60, 4385, 'وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةًۭ فِى ٱلْأَرْضِ يَخْلُفُونَ', 493, 25, 198, 0),
  (43, 61, 4386, 'وَإِنَّهُۥ لَعِلْمٌۭ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 494, 25, 198, 0),
  (43, 62, 4387, 'وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَٰنُ ۖ إِنَّهُۥ لَكُمْ عَدُوٌّۭ مُّبِينٌۭ', 494, 25, 198, 0),
  (43, 63, 4388, 'وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ', 494, 25, 198, 0),
  (43, 64, 4389, 'إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ ۚ هَٰذَا صِرَٰطٌۭ مُّسْتَقِيمٌۭ', 494, 25, 198, 0),
  (43, 65, 4390, 'فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ ۖ فَوَيْلٌۭ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ', 494, 25, 198, 0),
  (43, 66, 4391, 'هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ', 494, 25, 198, 0),
  (43, 67, 4392, 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', 494, 25, 198, 0),
  (43, 68, 4393, 'يَٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ', 494, 25, 198, 0),
  (43, 69, 4394, 'ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ مُسْلِمِينَ', 494, 25, 198, 0),
  (43, 70, 4395, 'ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ', 494, 25, 198, 0),
  (43, 71, 4396, 'يُطَافُ عَلَيْهِم بِصِحَافٍۢ مِّن ذَهَبٍۢ وَأَكْوَابٍۢ ۖ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ ۖ وَأَنتُمْ فِيهَا خَٰلِدُونَ', 494, 25, 198, 0),
  (43, 72, 4397, 'وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ', 494, 25, 198, 0),
  (43, 73, 4398, 'لَكُمْ فِيهَا فَٰكِهَةٌۭ كَثِيرَةٌۭ مِّنْهَا تَأْكُلُونَ', 494, 25, 198, 0),
  (43, 74, 4399, 'إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَٰلِدُونَ', 495, 25, 198, 0),
  (43, 75, 4400, 'لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ', 495, 25, 198, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 43, 1, 'Ha, Meem.'),
  ('en.sahih', 43, 2, 'By the clear Book,'),
  ('en.sahih', 43, 3, 'Indeed, We have made it an Arabic Qur\'an that you might understand.'),
  ('en.sahih', 43, 4, 'And indeed it is, in the Mother of the Book with Us, exalted and full of wisdom.'),
  ('en.sahih', 43, 5, 'Then should We turn the message away, disregarding you, because you are a transgressing people?'),
  ('en.sahih', 43, 6, 'And how many a prophet We sent among the former peoples,'),
  ('en.sahih', 43, 7, 'But there would not come to them a prophet except that they used to ridicule him.'),
  ('en.sahih', 43, 8, 'And We destroyed greater than them in [striking] power, and the example of the former peoples has preceded.'),
  ('en.sahih', 43, 9, 'And if you should ask them, "Who has created the heavens and the earth?" they would surely say, "They were created by the Exalted in Might, the Knowing."'),
  ('en.sahih', 43, 10, '[The one] who has made for you the earth a bed and made for you upon it roads that you might be guided'),
  ('en.sahih', 43, 11, 'And who sends down rain from the sky in measured amounts, and We revive thereby a dead land - thus will you be brought forth -'),
  ('en.sahih', 43, 12, 'And who created the species, all of them, and has made for you of ships and animals those which you mount.'),
  ('en.sahih', 43, 13, 'That you may settle yourselves upon their backs and then remember the favor of your Lord when you have settled upon them and say. "Exalted is He who has subjected this to us, and we could not have [otherwise] subdued it.'),
  ('en.sahih', 43, 14, 'And indeed we, to our Lord, will [surely] return."'),
  ('en.sahih', 43, 15, 'But they have attributed to Him from His servants a portion. Indeed, man is clearly ungrateful.'),
  ('en.sahih', 43, 16, 'Or has He taken, out of what He has created, daughters and chosen you for [having] sons?'),
  ('en.sahih', 43, 17, 'And when one of them is given good tidings of that which he attributes to the Most Merciful in comparison, his face becomes dark, and he suppresses grief.'),
  ('en.sahih', 43, 18, 'So is one brought up in ornaments while being during conflict unevident [attributed to Allah]?'),
  ('en.sahih', 43, 19, 'And they have made the angels, who are servants of the Most Merciful, females. Did they witness their creation? Their testimony will be recorded, and they will be questioned.'),
  ('en.sahih', 43, 20, 'And they said, "If the Most Merciful had willed, we would not have worshipped them." They have of that no knowledge. They are not but falsifying.'),
  ('en.sahih', 43, 21, 'Or have We given them a book before the Qur\'an to which they are adhering?'),
  ('en.sahih', 43, 22, 'Rather, they say, "Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided."'),
  ('en.sahih', 43, 23, 'And similarly, We did not send before you any warner into a city except that its affluent said, "Indeed, we found our fathers upon a religion, and we are, in their footsteps, following."'),
  ('en.sahih', 43, 24, '[Each warner] said, "Even if I brought you better guidance than that [religion] upon which you found your fathers?" They said, "Indeed we, in that with which you were sent, are disbelievers."'),
  ('en.sahih', 43, 25, 'So we took retribution from them; then see how was the end of the deniers.'),
  ('en.sahih', 43, 26, 'And [mention, O Muhammad], when Abraham said to his father and his people, "Indeed, I am disassociated from that which you worship'),
  ('en.sahih', 43, 27, 'Except for He who created me; and indeed, He will guide me."'),
  ('en.sahih', 43, 28, 'And he made it a word remaining among his descendants that they might return [to it].'),
  ('en.sahih', 43, 29, 'However, I gave enjoyment to these [people of Makkah] and their fathers until there came to them the truth and a clear Messenger.'),
  ('en.sahih', 43, 30, 'But when the truth came to them, they said, "This is magic, and indeed we are, concerning it, disbelievers."'),
  ('en.sahih', 43, 31, 'And they said, "Why was this Qur\'an not sent down upon a great man from [one of] the two cities?"'),
  ('en.sahih', 43, 32, 'Do they distribute the mercy of your Lord? It is We who have apportioned among them their livelihood in the life of this world and have raised some of them above others in degrees [of rank] that they may make use of one another for service. But the mercy of your Lord is better than whatever they accumulate.'),
  ('en.sahih', 43, 33, 'And if it were not that the people would become one community [of disbelievers], We would have made for those who disbelieve in the Most Merciful - for their houses - ceilings and stairways of silver upon which to mount'),
  ('en.sahih', 43, 34, 'And for their houses - doors and couches [of silver] upon which to recline'),
  ('en.sahih', 43, 35, 'And gold ornament. But all that is not but the enjoyment of worldly life. And the Hereafter with your Lord is for the righteous.'),
  ('en.sahih', 43, 36, 'And whoever is blinded from remembrance of the Most Merciful - We appoint for him a devil, and he is to him a companion.'),
  ('en.sahih', 43, 37, 'And indeed, the devils avert them from the way [of guidance] while they think that they are [rightly] guided'),
  ('en.sahih', 43, 38, 'Until, when he comes to Us [at Judgement], he says [to his companion], "Oh, I wish there was between me and you the distance between the east and west - how wretched a companion."'),
  ('en.sahih', 43, 39, 'And never will it benefit you that Day, when you have wronged, that you are [all] sharing in the punishment.'),
  ('en.sahih', 43, 40, 'Then will you make the deaf hear, [O Muhammad], or guide the blind or he who is in clear error?'),
  ('en.sahih', 43, 41, 'And whether [or not] We take you away [in death], indeed, We will take retribution upon them.'),
  ('en.sahih', 43, 42, 'Or whether [or not] We show you that which We have promised them, indeed, We are Perfect in Ability.'),
  ('en.sahih', 43, 43, 'So adhere to that which is revealed to you. Indeed, you are on a straight path.'),
  ('en.sahih', 43, 44, 'And indeed, it is a remembrance for you and your people, and you [all] are going to be questioned.'),
  ('en.sahih', 43, 45, 'And ask those We sent before you of Our messengers; have We made besides the Most Merciful deities to be worshipped?'),
  ('en.sahih', 43, 46, 'And certainly did We send Moses with Our signs to Pharaoh and his establishment, and he said, "Indeed, I am the messenger of the Lord of the worlds."'),
  ('en.sahih', 43, 47, 'But when he brought them Our signs, at once they laughed at them.'),
  ('en.sahih', 43, 48, 'And We showed them not a sign except that it was greater than its sister, and We seized them with affliction that perhaps they might return [to faith].'),
  ('en.sahih', 43, 49, 'And they said [to Moses], "O magician, invoke for us your Lord by what He has promised you. Indeed, we will be guided."'),
  ('en.sahih', 43, 50, 'But when We removed from them the affliction, at once they broke their word.'),
  ('en.sahih', 43, 51, 'And Pharaoh called out among his people; he said, "O my people, does not the kingdom of Egypt belong to me, and these rivers flowing beneath me; then do you not see?'),
  ('en.sahih', 43, 52, 'Or am I [not] better than this one who is insignificant and hardly makes himself clear?'),
  ('en.sahih', 43, 53, 'Then why have there not been placed upon him bracelets of gold or come with him the angels in conjunction?"'),
  ('en.sahih', 43, 54, 'So he bluffed his people, and they obeyed him. Indeed, they were [themselves] a people defiantly disobedient [of Allah].'),
  ('en.sahih', 43, 55, 'And when they angered Us, We took retribution from them and drowned them all.'),
  ('en.sahih', 43, 56, 'And We made them a precedent and an example for the later peoples.'),
  ('en.sahih', 43, 57, 'And when the son of Mary was presented as an example, immediately your people laughed aloud.'),
  ('en.sahih', 43, 58, 'And they said, "Are your gods better, or is he?" They did not present the comparison except for [mere] argument. But, [in fact], they are a people prone to dispute.'),
  ('en.sahih', 43, 59, 'Jesus was not but a servant upon whom We bestowed favor, and We made him an example for the Children of Israel.'),
  ('en.sahih', 43, 60, 'And if We willed, We could have made [instead] of you angels succeeding [one another] on the earth.'),
  ('en.sahih', 43, 61, 'And indeed, Jesus will be [a sign for] knowledge of the Hour, so be not in doubt of it, and follow Me. This is a straight path.'),
  ('en.sahih', 43, 62, 'And never let Satan avert you. Indeed, he is to you a clear enemy.'),
  ('en.sahih', 43, 63, 'And when Jesus brought clear proofs, he said, "I have come to you with wisdom and to make clear to you some of that over which you differ, so fear Allah and obey me.'),
  ('en.sahih', 43, 64, 'Indeed, Allah is my Lord and your Lord, so worship Him. This is a straight path."'),
  ('en.sahih', 43, 65, 'But the denominations from among them differed [and separated], so woe to those who have wronged from the punishment of a painful Day.'),
  ('en.sahih', 43, 66, 'Are they waiting except for the Hour to come upon them suddenly while they perceive not?'),
  ('en.sahih', 43, 67, 'Close friends, that Day, will be enemies to each other, except for the righteous'),
  ('en.sahih', 43, 68, '[To whom Allah will say], "O My servants, no fear will there be concerning you this Day, nor will you grieve,'),
  ('en.sahih', 43, 69, '[You] who believed in Our verses and were Muslims.'),
  ('en.sahih', 43, 70, 'Enter Paradise, you and your kinds, delighted."'),
  ('en.sahih', 43, 71, 'Circulated among them will be plates and vessels of gold. And therein is whatever the souls desire and [what] delights the eyes, and you will abide therein eternally.'),
  ('en.sahih', 43, 72, 'And that is Paradise which you are made to inherit for what you used to do.'),
  ('en.sahih', 43, 73, 'For you therein is much fruit from which you will eat.'),
  ('en.sahih', 43, 74, 'Indeed, the criminals will be in the punishment of Hell, abiding eternally.'),
  ('en.sahih', 43, 75, 'It will not be allowed to subside for them, and they, therein, are in despair.'),
  ('en.sahih', 43, 76, 'And We did not wrong them, but it was they who were the wrongdoers.'),
  ('en.sahih', 43, 77, 'And they will call, "O Malik, let your Lord put an end to us!" He will say, "Indeed, you will remain."'),
  ('en.sahih', 43, 78, 'We had certainly brought you the truth, but most of you, to the truth, were averse.'),
  ('en.sahih', 43, 79, 'Or have they devised [some] affair? But indeed, We are devising [a plan].'),
  ('en.sahih', 43, 80, 'Or do they think that We hear not their secrets and their private conversations? Yes, [We do], and Our messengers are with them recording.'),
  ('en.sahih', 43, 81, 'Say, [O Muhammad], "If the Most Merciful had a son, then I would be the first of [his] worshippers."'),
  ('en.sahih', 43, 82, 'Exalted is the Lord of the heavens and the earth, Lord of the Throne, above what they describe.'),
  ('en.sahih', 43, 83, 'So leave them to converse vainly and amuse themselves until they meet their Day which they are promised.'),
  ('en.sahih', 43, 84, 'And it is Allah who is [the only] deity in the heaven, and on the earth [the only] deity. And He is the Wise, the Knowing.'),
  ('en.sahih', 43, 85, 'And blessed is He to whom belongs the dominion of the heavens and the earth and whatever is between them and with whom is knowledge of the Hour and to whom you will be returned.'),
  ('en.sahih', 43, 86, 'And those they invoke besides Him do not possess [power of] intercession; but only those who testify to the truth [can benefit], and they know.'),
  ('en.sahih', 43, 87, 'And if you asked them who created them, they would surely say, "Allah." So how are they deluded?'),
  ('en.sahih', 43, 88, 'And [Allah acknowledges] his saying, "O my Lord, indeed these are a people who do not believe."'),
  ('en.sahih', 43, 89, 'So turn aside from them and say, "Peace." But they are going to know.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 43, 1, 'হা-মীম।'),
  ('bn.bengali', 43, 2, 'শপথ সুস্পষ্ট কিতাবের,'),
  ('bn.bengali', 43, 3, 'আমি একে করেছি কোরআন, আরবী ভাষায়, যাতে তোমরা বুঝ।'),
  ('bn.bengali', 43, 4, 'নিশ্চয় এ কোরআন আমার কাছে সমুন্নত অটল রয়েছে লওহে মাহফুযে।'),
  ('bn.bengali', 43, 5, 'তোমরা সীমাতিক্রমকারী সম্প্রদায়-এ কারণে কি আমি তোমাদের কাছ থেকে কোরআন প্রত্যাহার করে নেব?'),
  ('bn.bengali', 43, 6, 'পূর্ববর্তী লোকদের কাছে আমি অনেক রসূলই প্রেরণ করেছি।'),
  ('bn.bengali', 43, 7, 'যখনই তাদের কাছে কোন রসূল আগমন করেছেন, তখনই তারা তাঁর সাথে ঠাট্টা-বিদ্রুপ করেছে।'),
  ('bn.bengali', 43, 8, 'সুতরাং আমি তাদের চেয়ে অধিক শক্তি সম্পন্নদেরকে ধ্বংস করে দিয়েছি। পূর্ববর্তীদের এ ঘটনা অতীত হয়ে গেছে।'),
  ('bn.bengali', 43, 9, 'আপনি যদি তাদেরকে জিজ্ঞাসা করেন কে নভোমন্ডল ও ভূ-মন্ডল সৃষ্টি করেছে? তারা অবশ্যই বলবে, এগুলো সৃষ্টি করেছেন পরাক্রমশালী সর্বজ্ঞ আল্লাহ।'),
  ('bn.bengali', 43, 10, 'যিনি তোমাদের জন্যে পৃথিবীকে করেছেন বিছানা এবং তাতে তোমাদের জন্যে করেছেন পথ, যাতে তোমরা গন্তব্যস্থলে পৌঁছতে পার।'),
  ('bn.bengali', 43, 11, 'এবং যিনি আকাশ থেকে পানি বর্ষণ করেছেন পরিমিত। আতঃপর তদ্দ্বারা আমি মৃত ভূ-ভাগকে পুনরুজ্জীবিত করেছি। তোমরা এমনিভাবে উত্থিত হবে।'),
  ('bn.bengali', 43, 12, 'এবং যিনি সবকিছুর যুগল সৃষ্টি করেছেন এবং নৌকা ও চতুস্পদ জন্তুকে তোমাদের জন্যে যানবাহনে পরিণত করেছেন,'),
  ('bn.bengali', 43, 13, 'যাতে তোমরা তাদের পিঠের উপর আরোহণ কর। অতঃপর তোমাদের পালনকর্তার নেয়ামত স্মরণ কর এবং বল পবিত্র তিনি, যিনি এদেরকে আমাদের বশীভূত করে দিয়েছেন এবং আমরা এদেরকে বশীভূত করতে সক্ষম ছিলাম না।'),
  ('bn.bengali', 43, 14, 'আমরা অবশ্যই আমাদের পালনকর্তার দিকে ফিরে যাব।'),
  ('bn.bengali', 43, 15, 'তারা আল্লাহর বান্দাদের মধ্য থেকে আল্লাহর অংশ স্থির করেছে। বাস্তবিক মানুষ স্পষ্ট অকৃতজ্ঞ।'),
  ('bn.bengali', 43, 16, 'তিনি কি তাঁর সৃষ্টি থেকে কন্যা সন্তান গ্রহণ করেছেন এবং তোমাদের জন্য মনোনীত করেছেন পুত্র সন্তান?'),
  ('bn.bengali', 43, 17, 'তারা রহমান আল্লাহর জন্যে যে, কন্যা-সন্তান বর্ণনা করে, যখন তাদের কাউকে তার সংবাদ দেয়া হয়, তখন তার মুখমন্ডল কালো হয়ে যায় এবং ভীষণ মনস্তাপ ভোগ করে।'),
  ('bn.bengali', 43, 18, 'তারা কি এমন ব্যক্তিকে আল্লাহর জন্যে বর্ণনা করে, যে অলংকারে লালিত-পালিত হয় এবং বিতর্কে কথা বলতে অক্ষম।'),
  ('bn.bengali', 43, 19, 'তারা নারী স্থির করে ফেরেশতাগণকে, যারা আল্লাহর বান্দা। তারা কি তাদের সৃষ্টি প্রত্যক্ষ করেছে? এখন তাদের দাবী লিপিবদ্ধ করা হবে এবং তাদের জিজ্ঞাসা করা হবে।'),
  ('bn.bengali', 43, 20, 'তারা বলে, রহমান আল্লাহ ইচছা না করলে আমরা ওদের পূজা করতাম না। এ বিষয়ে তারা কিছুই জানে না। তারা কেবল অনুমানে কথা বলে।'),
  ('bn.bengali', 43, 21, 'আমি কি তাদেরকে কোরআনের পূর্বে কোন কিতাব দিয়েছি, অতঃপর তারা তাকে আঁকড়ে রেখেছে?'),
  ('bn.bengali', 43, 22, 'বরং তারা বলে, আমরা আমাদের পূর্বপুরুষদেরকে পেয়েছি এক পথের পথিক এবং আমরা তাদেরই পদাংক অনুসরণ করে পথপ্রাপ্ত।'),
  ('bn.bengali', 43, 23, 'এমনিভাবে আপনার পূর্বে আমি যখন কোন জনপদে কোন সতর্ককারী প্রেরণ করেছি, তখনই তাদের বিত্তশালীরা বলেছে, আমরা আমাদের পূর্বপুরুষদেরকে পেয়েছি এক পথের পথিক এবং আমরা তাদেরই পদাংক অনুসরণ করে চলছি।'),
  ('bn.bengali', 43, 24, 'সে বলত, তোমরা তোমাদের পূর্বপুরুষদেরকে যে বিষয়ের উপর পেয়েছ, আমি যদি তদপেক্ষা উত্তম বিষয় নিয়ে তোমাদের কাছে এসে থাকি, তবুও কি তোমরা তাই বলবে? তারা বলত তোমরা যে বিষয়সহ প্রেরিত হয়েছ, তা আমরা মানব না।'),
  ('bn.bengali', 43, 25, 'অতঃপর আমি তাদের কাছ থেকে প্রতিশোধ নিয়েছি। অতএব দেখুন, মিথ্যারোপকারীদের পরিণাম কিরূপ হয়েছে।'),
  ('bn.bengali', 43, 26, 'যখন ইব্রাহীম তার পিতা ও সম্প্রদায়কে বলল, তোমরা যাদের পূজা কর, তাদের সাথে আমার কোন সম্পর্ক নেই।'),
  ('bn.bengali', 43, 27, 'তবে আমার সম্পর্ক তাঁর সাথে যিনি আমাকে সৃষ্টি করেছেন। অতএব, তিনিই আমাকে সৎপথ প্রদর্শন করবেন।'),
  ('bn.bengali', 43, 28, 'এ কথাটিকে সে অক্ষয় বাণীরূপে তার সন্তানদের মধ্যে রেখে গেছে, যাতে তারা আল্লাহর দিকেই আকৃষ্ট থাকে।'),
  ('bn.bengali', 43, 29, 'পরন্ত আমিই এদেরকে ও এদের পূর্বপুরুষদেরকে জীবনোপভোগ করতে দিয়েছি, অবশেষে তাদের কাছে সত্য ও স্পষ্ট বর্ণনাকারী রসূল আগমন করেছে।'),
  ('bn.bengali', 43, 30, 'যখন সত্য তাদের কাছে আগমন করল, তখন তারা বলল, এটা যাদু, আমরা একে মানি না।'),
  ('bn.bengali', 43, 31, 'তারা বলে, কোরআন কেন দুই জনপদের কোন প্রধান ব্যক্তির উপর অবতীর্ণ হল না?'),
  ('bn.bengali', 43, 32, 'তারা কি আপনার পালনকর্তার রহমত বন্টন করে? আমি তাদের মধ্যে তাদের জীবিকা বন্টন করেছি পার্থিব জীবনে এবং একের মর্যাদাকে অপরের উপর উন্নীত করেছি, যাতে একে অপরকে সেবক রূপে গ্রহণ করে। তারা যা সঞ্চয় করে, আপনার পালনকর্তার রহমত তদপেক্ষা উত্তম।'),
  ('bn.bengali', 43, 33, 'যদি সব মানুষের এক মতাবলম্বী হয়ে যাওয়ার আশংকা না থাকত, তবে যারা দয়াময় আল্লাহকে অস্বীকার করে আমি তাদেরকে দিতাম তাদের গৃহের জন্যে রৌপ্য নির্মিত ছাদ ও সিঁড়ি, যার উপর তারা চড়ত।'),
  ('bn.bengali', 43, 34, 'এবং তাদের গৃহের জন্যে দরজা দিতাম এবং পালংক দিতাম যাতে তারা হেলান দিয়ে বসত।'),
  ('bn.bengali', 43, 35, 'এবং স্বর্ণনির্মিতও দিতাম। এগুলো সবই তো পার্থিব জীবনের ভোগ সামগ্রী মাত্র। আর পরকাল আপনার পালনকর্তার কাছে তাঁদের জন্যেই যারা ভয় করে।'),
  ('bn.bengali', 43, 36, 'যে ব্যক্তি দয়াময় আল্লাহর স্মরণ থেকে চোখ ফিরিয়ে নেয়, আমি তার জন্যে এক শয়তান নিয়োজিত করে দেই, অতঃপর সে-ই হয় তার সঙ্গী।'),
  ('bn.bengali', 43, 37, 'শয়তানরাই মানুষকে সৎপথে বাধা দান করে, আর মানুষ মনে করে যে, তারা সৎপথে রয়েছে।'),
  ('bn.bengali', 43, 38, 'অবশেষে যখন সে আমার কাছে আসবে, তখন সে শয়তানকে বলবে, হায়, আমার ও তোমার মধ্যে যদি পূর্ব-পশ্চিমের দূরত্ব থাকত। কত হীন সঙ্গী সে।'),
  ('bn.bengali', 43, 39, 'তোমরা যখন কুফর করছিলে, তখন তোমাদের আজকের আযাবে শরীক হওয়া কোন কাজে আসবে না।'),
  ('bn.bengali', 43, 40, 'আপনি কি বধিরকে শোনাতে পারবেন? অথবা যে অন্ধ ও যে স্পষ্ট পথ ভ্রষ্টতায় লিপ্ত, তাকে পথ প্রদর্শণ করতে পারবেন?'),
  ('bn.bengali', 43, 41, 'অতঃপর আমি যদি আপনাকে নিয়ে যাই, তবু আমি তাদের কাছে থেকে প্রতিশোধ নেব।'),
  ('bn.bengali', 43, 42, 'অথবা যদি আমি তাদেরকে যে আযাবের ওয়াদা দিয়েছি, তা আপনাকে দেখিয়ে দেই, তবু তাদের উপর আমার পূর্ণ ক্ষমতা রয়েছে।'),
  ('bn.bengali', 43, 43, 'অতএব, আপনার প্রতি যে ওহী নাযিল করা হয়, তা দৃঢ়ভাবে অবলম্বন করুন। নিঃসন্দেহে আপনি সরল পথে রয়েছেন।'),
  ('bn.bengali', 43, 44, 'এটা আপনার ও আপনার সম্প্রদায়ের জন্যে উল্লেখিত থাকবে এবং শীঘ্রই আপনারা জিজ্ঞাসিত হবেন।'),
  ('bn.bengali', 43, 45, 'আপনার পূর্বে আমি যেসব রসূল প্রেরণ করেছি, তাদেরকে জিজ্ঞেস করুন, দয়াময় আল্লাহ ব্যতীত আমি কি কোন উপাস্য স্থির করেছিলাম এবাদতের জন্যে?'),
  ('bn.bengali', 43, 46, 'আমি মূসাকে আমার নিদর্শনাবলী দিয়ে ফেরাউন ও তার পরিষদবর্গের কাছে প্রেরণ করেছিলাম, অতঃপর সে বলেছিল, আমি বিশ্ব পালনকর্তার রসূল।'),
  ('bn.bengali', 43, 47, 'অতঃপর সে যখন তাদের কাছে আমার নিদর্শনাবলী উপস্থাপন করল, তখন তারা হাস্যবিদ্রুপ করতে লাগল।'),
  ('bn.bengali', 43, 48, 'আমি তাদেরকে যে নিদর্শনই দেখাতাম, তাই হত পূর্ববর্তী নিদর্শন অপেক্ষা বৃহৎ এবং আমি তাদেরকে শাস্তি দ্বারা পাকড়াও করলাম, যাতে তারা ফিরে আসে।'),
  ('bn.bengali', 43, 49, 'তারা বলল, হে যাদুকর, তুমি আমাদের জন্যে তোমার পালনকর্তার কাছে সে বিষয় প্রার্থনা কর, যার ওয়াদা তিনি তোমাকে দিয়েছেন; আমরা অবশ্যই সৎপথ অবলম্বন করব।'),
  ('bn.bengali', 43, 50, 'অতঃপর যখন আমি তাদের থেকে আযাব প্রত্যাহার করে নিলাম, তখনই তারা অঙ্গীকার ভঙ্গ করতে লাগলো।'),
  ('bn.bengali', 43, 51, 'ফেরাউন তার সম্প্রদায়কে ডেকে বলল, হে আমার কওম, আমি কি মিসরের অধিপতি নই? এই নদী গুলো আমার নিম্নদেশে প্রবাহিত হয়, তোমরা কি দেখ না?'),
  ('bn.bengali', 43, 52, 'আমি যে শ্রেষ্ট এ ব্যক্তি থেকে, যে নীচ এবং কথা বলতেও সক্ষম নয়।'),
  ('bn.bengali', 43, 53, 'তাকে কেন স্বর্ণবলয় পরিধান করানো হল না, অথবা কেন আসল না তার সঙ্গে ফেরেশতাগণ দল বেঁধে?'),
  ('bn.bengali', 43, 54, 'অতঃপর সে তার সম্প্রদায়কে বোকা বানিয়ে দিল, ফলে তারা তার কথা মেনে নিল। নিশ্চয় তারা ছিল পাপাচারী সম্প্রদায়।'),
  ('bn.bengali', 43, 55, 'অতঃপর যখন আমাকে রাগাম্বিত করল তখন আমি তাদের কাছ থেকে প্রতিশোধ নিলাম এবং নিমজ্জত করলাম। তাদের সবাইকে।'),
  ('bn.bengali', 43, 56, 'অতঃপর আমি তাদেরকে করে দিলাম অতীত লোক ও দৃষ্টান্ত পরবর্তীদের জন্যে।'),
  ('bn.bengali', 43, 57, 'যখনই মরিয়ম তনয়ের দৃষ্টান্ত বর্ণনা করা হল, তখনই আপনার সম্প্রদায় হঞ্জগোল শুরু করে দিল'),
  ('bn.bengali', 43, 58, 'এবং বলল, আমাদের উপাস্যরা শ্রেষ্ঠ, না সে? তারা আপনার সামনে যে উদাহরণ উপস্থাপন করে তা কেবল বিতর্কের জন্যেই করে। বস্তুতঃ তারা হল এক বিতর্ককারী সম্প্রদায়।'),
  ('bn.bengali', 43, 59, 'সে তো এক বান্দাই বটে আমি তার প্রতি অনুগ্রহ করেছি এবং তাকে করেছি বণী-ইসরাঈলের জন্যে আদর্শ।'),
  ('bn.bengali', 43, 60, 'আমি ইচ্ছা করলে তোমাদের থেকে ফেরেশতা সৃষ্টি করতাম, যারা পৃথিবীতে একের পর এক বসবাস করত।'),
  ('bn.bengali', 43, 61, 'সুতরাং তা হল কেয়ামতের নিদর্শন। কাজেই তোমরা কেয়ামতে সন্দেহ করো না এবং আমার কথা মান। এটা এক সরল পথ।'),
  ('bn.bengali', 43, 62, 'শয়তান যেন তোমাদেরকে নিবৃত্ত না করে। সে তোমাদের প্রকাশ্য শুত্রু।'),
  ('bn.bengali', 43, 63, 'ঈসা যখন স্পষ্ট নিদর্শনসহ আগমন করল, তখন বলল, আমি তোমাদের কাছে প্রজ্ঞা নিয়ে এসেছি এবং তোমরা যে, কোন কোন বিষয়ে মতভেদ করছ তা ব্যক্ত করার জন্যে এসেছি, অতএব, তোমরা আল্লাহকে ভয় কর এবং আমার কথা মান।'),
  ('bn.bengali', 43, 64, 'নিশ্চয় আল্লাহই আমার পালনকর্তা ও তোমাদের পালনকর্তা। অতএব, তাঁর এবাদত কর। এটা হল সরল পথ।'),
  ('bn.bengali', 43, 65, 'অতঃপর তাদের মধ্যে থেকে বিভিন্ন দল মতভেদ সৃষ্টি করল। সুতরাং যালেমদের জন্যে রয়েছে যন্ত্রণাদায়ক দিবসের আযাবের দুর্ভোগ।'),
  ('bn.bengali', 43, 66, 'তারা কেবল কেয়ামতেরই অপেক্ষা করছে যে, আকস্মিকভাবে তাদের কাছে এসে যাবে এবং তারা খবর ও রাখবে না।'),
  ('bn.bengali', 43, 67, 'বন্ধুবর্গ সেদিন একে অপরের শত্রু হবে, তবে খোদাভীরুরা নয়।'),
  ('bn.bengali', 43, 68, 'হে আমার বান্দাগণ, তোমাদের আজ কোন ভয় নেই এবং তোমরা দুঃখিতও হবে না।'),
  ('bn.bengali', 43, 69, 'তোমরা আমার আয়াতসমূহে বিশ্বাস স্থাপন করেছিলে এবং তোমরা আজ্ঞাবহ ছিলে।'),
  ('bn.bengali', 43, 70, 'জান্নাতের প্রবেশ কর তোমরা এবং তোমাদের বিবিগণ সানন্দে।'),
  ('bn.bengali', 43, 71, 'তাদের কাছে পরিবেশন করা হবে স্বর্ণের থালা ও পানপাত্র এবং তথায় রয়েছে মনে যা চায় এবং নয়ন যাতে তৃপ্ত হয়। তোমরা তথায় চিরকাল অবস্থান করবে।'),
  ('bn.bengali', 43, 72, 'এই যে, জান্নাতের উত্তরাধিকারী তোমরা হয়েছ, এটা তোমাদের কর্মের ফল।'),
  ('bn.bengali', 43, 73, 'তথায় তোমাদের জন্যে আছে প্রচুর ফল-মূল, তা থেকে তোমরা আহার করবে।'),
  ('bn.bengali', 43, 74, 'নিশ্চয় অপরাধীরা জাহান্নামের আযাবে চিরকাল থাকবে।'),
  ('bn.bengali', 43, 75, 'তাদের থেকে আযাব লাঘব করা হবে না এবং তারা তাতেই থাকবে হতাশ হয়ে।'),
  ('bn.bengali', 43, 76, 'আমি তাদের প্রতি জুলুম করিনি; কিন্তু তারাই ছিল জালেম।'),
  ('bn.bengali', 43, 77, 'তারা ডেকে বলবে, হে মালেক, পালনকর্তা আমাদের কিসসাই শেষ করে দিন। সে বলবে, নিশ্চয় তোমরা চিরকাল থাকবে।'),
  ('bn.bengali', 43, 78, 'আমি তোমাদের কাছে সত্যধর্ম পৌঁছিয়েছি; কিন্তু তোমাদের অধিকাংশই সত্যধর্মে নিস্পৃহ!'),
  ('bn.bengali', 43, 79, 'তারা কি কোন ব্যবস্থা চুড়ান্ত করেছে? তাহলে আমিও এক ব্যবস্থা চুড়ান্ত করেছি।'),
  ('bn.bengali', 43, 80, 'তারা কি মনে করে যে, আমি তাদের গোপন বিষয় ও গোপন পরামর্শ শুনি না? হঁ্যা, শুনি। আমার ফেরেশতাগণ তাদের নিকটে থেকে লিপিবদ্ধ করে।'),
  ('bn.bengali', 43, 81, 'বলুন, দয়াময় আল্লাহর কোন সন্তান থাকলে আমি সর্ব প্রথম তার এবাদত করব।'),
  ('bn.bengali', 43, 82, 'তারা যা বর্ণনা করে, তা থেকে নভোমন্ডল ও ভূমন্ডলের পালনকর্তা, আরশের পালনকর্তা পবিত্র।'),
  ('bn.bengali', 43, 83, 'অতএব, তাদেরকে বাকচাতুরী ও ক্রীড়া-কৌতুক করতে দিন সেই দিবসের সাক্ষাত পর্যন্ত, যার ওয়াদা তাদেরকে দেয়া হয়।'),
  ('bn.bengali', 43, 84, 'তিনিই উপাস্য নভোমন্ডলে এবং তিনিই উপাস্য ভুমন্ডলে। তিনি প্রজ্ঞাময়, সর্বজ্ঞ,'),
  ('bn.bengali', 43, 85, 'বরকতময় তিনিই, নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের মধ্যবর্তী সবকিছু যার। তাঁরই কাছে আছে কেয়ামতের জ্ঞান এবং তাঁরই দিকে তোমরা প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 43, 86, 'তিনি ব্যতীত তারা যাদের পুজা করে, তারা সুপারিশের অধিকারী হবে না, তবে যারা সত্য স্বীকার করত ও বিশ্বাস করত।'),
  ('bn.bengali', 43, 87, 'যদি আপনি তাদেরকে জিজ্ঞাসা করেন, কে তাদেরকে সৃষ্টি করেছেন, তবে অবশ্যই তারা বলবে, আল্লাহ, অতঃপর তারা কোথায় ফিরে যাচ্ছে ?'),
  ('bn.bengali', 43, 88, 'রসূলের এই উক্তির কসম, হে আমার পালনকর্তা, এ সম্প্রদায় তো বিশ্বাস স্থাপন করে না।'),
  ('bn.bengali', 43, 89, 'অতএব, আপনি তাদের থেকে মুখ ফিরিয়ে নিন এবং বলুন, ‘সালাম’। তারা শীঘ্রই জানতে পারবে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 43, 1, 'Ha. Mim.'),
  ('en.pickthall', 43, 2, 'By the Scripture which maketh plain,'),
  ('en.pickthall', 43, 3, 'Lo! We have appointed it a Lecture, in Arabic that haply ye may understand.'),
  ('en.pickthall', 43, 4, 'And Lo! in the Source of Decrees, which We possess, it is indeed sublime, decisive.'),
  ('en.pickthall', 43, 5, 'Shall We utterly ignore you because ye are a wanton folk?'),
  ('en.pickthall', 43, 6, 'How many a prophet did We send among the men of old!'),
  ('en.pickthall', 43, 7, 'And never came there unto them a prophet but they used to mock him.'),
  ('en.pickthall', 43, 8, 'Then We destroyed men mightier than these in prowess; and the example of the men of old hath gone (before them).'),
  ('en.pickthall', 43, 9, 'And if thou (Muhammad) ask them: Who created the heavens and the earth, they will surely answer: The Mighty, the Knower created them;'),
  ('en.pickthall', 43, 10, 'Who made the earth a resting-place for you, and placed roads for you therein, that haply ye may find your way;'),
  ('en.pickthall', 43, 11, 'And Who sendeth down water from the sky in (due) measure, and We revive a dead land therewith. Even so will ye be brought forth;'),
  ('en.pickthall', 43, 12, 'He Who created all the pairs, and appointed for you ships and cattle whereupon ye ride.'),
  ('en.pickthall', 43, 13, 'That ye may mount upon their backs, and may remember your Lord\'s favour when ye mount thereon, and may say: Glorified be He Who hath subdued these unto us, and we were not capable (of subduing them);'),
  ('en.pickthall', 43, 14, 'And lo! unto our Lord we surely are returning.'),
  ('en.pickthall', 43, 15, 'And they allot to Him a portion of His bondmen! Lo! man is verily a mere ingrate.'),
  ('en.pickthall', 43, 16, 'Or chooseth He daughters of all that He hath created, and honoureth He you with sons?'),
  ('en.pickthall', 43, 17, 'And if one of them hath tidings of that which he likeneth to the Beneficent One, his countenance becometh black and he is full of inward rage.'),
  ('en.pickthall', 43, 18, '(Liken they then to Allah) that which is bred up in outward show, and in dispute cannot make itself plain?'),
  ('en.pickthall', 43, 19, 'And they make the angels, who are the slaves of the Beneficent, females. Did they witness their creation? Their testimony will be recorded and they will be questioned.'),
  ('en.pickthall', 43, 20, 'And they say: If the Beneficent One had (so) willed, we should not have worshipped them. They have no knowledge whatsoever of that. They do but guess.'),
  ('en.pickthall', 43, 21, 'Or have We given them any scripture before (this Qur\'an) so that they are holding fast thereto?'),
  ('en.pickthall', 43, 22, 'Nay, for they say only: Lo! we found our fathers following a religion, and we are guided by their footprints.'),
  ('en.pickthall', 43, 23, 'And even so We sent not a warner before thee (Muhammad) into any township but its luxurious ones said: Lo! we found our fathers following a religion, and we are following their footprints.'),
  ('en.pickthall', 43, 24, '(And the warner) said: What! Even though I bring you better guidance than that ye found your fathers following? They answered: Lo! in what ye bring we are disbelievers.'),
  ('en.pickthall', 43, 25, 'So We requited them. Then see the nature of the consequence for the rejecters!'),
  ('en.pickthall', 43, 26, 'And when Abraham said unto his father and his folk: Lo! I am innocent of what ye worship'),
  ('en.pickthall', 43, 27, 'Save Him Who did create me, for He will surely guide me.'),
  ('en.pickthall', 43, 28, 'And he made it a word enduring among his seed, that haply they might return.'),
  ('en.pickthall', 43, 29, 'Nay, but I let these and their fathers enjoy life (only) till there should come unto them the Truth and a messenger making plain.'),
  ('en.pickthall', 43, 30, 'And now that the Truth hath come unto them they say: This is mere magic, and lo! we are disbelievers therein.'),
  ('en.pickthall', 43, 31, 'And they say: If only this Qur\'an had been revealed to some great man of the two towns?'),
  ('en.pickthall', 43, 32, 'Is it they who apportion thy Lord\'s mercy? We have apportioned among them their livelihood in the life of the world, and raised some of them above others in rank that some of them may take labour from others; and the mercy of thy Lord is better than (the wealth) that they amass.'),
  ('en.pickthall', 43, 33, 'And were it not that mankind would have become one community, We might well have appointed, for those who disbelieve in the Beneficent, roofs of silver for their houses and stairs (of silver) whereby to mount,'),
  ('en.pickthall', 43, 34, 'And for their houses doors (of silver) and couches of silver whereon to recline,'),
  ('en.pickthall', 43, 35, 'And ornaments of gold. Yet all that would have been but a provision of the life of the world. And the Hereafter with your Lord would have been for those who keep from evil.'),
  ('en.pickthall', 43, 36, 'And he whose sight is dim to the remembrance of the Beneficent, We assign unto him a devil who becometh his comrade;'),
  ('en.pickthall', 43, 37, 'And lo! they surely turn them from the way of Allah, and yet they deem that they are rightly guided;'),
  ('en.pickthall', 43, 38, 'Till, when he cometh unto Us, he saith (unto his comrade): Ah, would that between me and thee there were the distance of the two horizons - an evil comrade!'),
  ('en.pickthall', 43, 39, 'And it profiteth you not this day, because ye did wrong, that ye will be sharers in the doom.'),
  ('en.pickthall', 43, 40, 'Canst thou (Muhammad) make the deaf to hear, or canst thou guide the blind or him who is in error manifest?'),
  ('en.pickthall', 43, 41, 'And if We take thee away, We surely shall take vengeance on them,'),
  ('en.pickthall', 43, 42, 'Or (if) We show thee that wherewith We threaten them; for lo! We have complete command of them.'),
  ('en.pickthall', 43, 43, 'So hold thou fast to that which is inspired in thee. Lo! thou art on a right path.'),
  ('en.pickthall', 43, 44, 'And lo! it is in truth a Reminder for thee and for thy folk; and ye will be questioned.'),
  ('en.pickthall', 43, 45, 'And ask those of Our messengers whom We sent before thee: Did We ever appoint gods to be worshipped beside the Beneficent?'),
  ('en.pickthall', 43, 46, 'And verily We sent Moses with Our revelations unto Pharaoh and his chiefs, and he said: I am a messenger of the Lord of the Worlds.'),
  ('en.pickthall', 43, 47, 'But when he brought them Our tokens, behold! they laughed at them.'),
  ('en.pickthall', 43, 48, 'And every token that We showed them was greater than its sister (token), and We grasped them with the torment, that haply they might turn again.'),
  ('en.pickthall', 43, 49, 'And they said: O wizard! Entreat thy Lord for us by the pact that He hath made with thee. Lo! we verily will walk aright.'),
  ('en.pickthall', 43, 50, 'But when We eased them of the torment, behold! they broke their word.'),
  ('en.pickthall', 43, 51, 'And Pharaoh caused a proclamation to be made among his people saying: O my people! Is not mine the sovereignty of Egypt and these rivers flowing under me? Can ye not then discern?'),
  ('en.pickthall', 43, 52, 'I am surely better than this fellow, who is despicable and can hardly make (his meaning) plain!'),
  ('en.pickthall', 43, 53, 'Why, then, have armlets of gold not been set upon him, or angels sent along with him?'),
  ('en.pickthall', 43, 54, 'Thus he persuaded his people to make light (of Moses), and they obeyed him. Lo! they were a wanton folk.'),
  ('en.pickthall', 43, 55, 'So, when they angered Us, We punished them and drowned them every one.'),
  ('en.pickthall', 43, 56, 'And We made them a thing past, and an example for those after (them).'),
  ('en.pickthall', 43, 57, 'And when the son of Mary is quoted as an example, behold! the folk laugh out,'),
  ('en.pickthall', 43, 58, 'And say: Are our gods better, or is he? They raise not the objection save for argument. Nay! but they are a contentious folk.'),
  ('en.pickthall', 43, 59, 'He is nothing but a slave on whom We bestowed favour, and We made him a pattern for the Children of Israel.'),
  ('en.pickthall', 43, 60, 'And had We willed We could have set among you angels to be viceroys in the earth.'),
  ('en.pickthall', 43, 61, 'And lo! verily there is knowledge of the Hour. So doubt ye not concerning it, but follow Me. This is the right path.'),
  ('en.pickthall', 43, 62, 'And let not Satan turn you aside. Lo! he is an open enemy for you.'),
  ('en.pickthall', 43, 63, 'When Jesus came with clear proofs (of Allah\'s Sovereignty), he said: I have come unto you with wisdom, and to make plain some of that concerning which ye differ. So keep your duty to Allah, and obey me.'),
  ('en.pickthall', 43, 64, 'Lo! Allah, He is my Lord and your Lord. So worship Him. This is a right path.'),
  ('en.pickthall', 43, 65, 'But the factions among them differed. Then woe unto those who do wrong from the doom of a painful day.'),
  ('en.pickthall', 43, 66, 'Await they aught save the Hour, that it shall come upon them suddenly, when they know not?'),
  ('en.pickthall', 43, 67, 'Friends on that day will be foes one to another, save those who kept their duty (to Allah).'),
  ('en.pickthall', 43, 68, 'O My slaves! For you there is no fear this day, nor is it ye who grieve;'),
  ('en.pickthall', 43, 69, '(Ye) who believed Our revelations and were self-surrendered,'),
  ('en.pickthall', 43, 70, 'Enter the Garden, ye and your wives, to be made glad.'),
  ('en.pickthall', 43, 71, 'Therein are brought round for them trays of gold and goblets, and therein is all that souls desire and eyes find sweet. And ye are immortal therein.'),
  ('en.pickthall', 43, 72, 'This is the Garden which ye are made to inherit because of what ye used to do.'),
  ('en.pickthall', 43, 73, 'Therein for you is fruit in plenty whence to eat.'),
  ('en.pickthall', 43, 74, 'Lo! the guilty are immortal in hell\'s torment.'),
  ('en.pickthall', 43, 75, 'It is not relaxed for them, and they despair therein.'),
  ('en.pickthall', 43, 76, 'We wronged them not, but they it was who did the wrong.'),
  ('en.pickthall', 43, 77, 'And they cry: O master! Let thy Lord make an end of us. He saith: Lo! here ye must remain.'),
  ('en.pickthall', 43, 78, 'We verily brought the Truth unto you, but ye were, most of you, averse to the Truth.'),
  ('en.pickthall', 43, 79, 'Or do they determine any thing (against the Prophet)? Lo! We (also) are determining.'),
  ('en.pickthall', 43, 80, 'Or deem they that We cannot hear their secret thoughts and private confidences? Nay, but Our envoys, present with them, do record.'),
  ('en.pickthall', 43, 81, 'Say (O Muhammad): If the Beneficent One hath a son, then, I shall be first among the worshippers. (But there is no son).'),
  ('en.pickthall', 43, 82, 'Glorified be the Lord of the heavens and the earth, the Lord of the Throne, from that which they ascribe (unto Him)!'),
  ('en.pickthall', 43, 83, 'So let them flounder (in their talk) and play until they meet the Day which they are promised.'),
  ('en.pickthall', 43, 84, 'And He it is Who in the heaven is Allah, and in the earth Allah. He is the Wise, the Knower.'),
  ('en.pickthall', 43, 85, 'And blessed be He unto Whom belongeth the Sovereignty of the heavens and the earth and all that is between them, and with Whom is knowledge of the Hour, and unto Whom ye will be returned.'),
  ('en.pickthall', 43, 86, 'And those unto whom they cry instead of Him possess no power of intercession, saving him who beareth witness unto the Truth knowingly.'),
  ('en.pickthall', 43, 87, 'And if thou ask them who created them, they will surely say: Allah. How then are they turned away?'),
  ('en.pickthall', 43, 88, 'And he saith: O my Lord! Lo! these are a folk who believe not.'),
  ('en.pickthall', 43, 89, 'Then bear with them (O Muhammad) and say: Peace. But they will come to know.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 43, 1, 'Ha-Mim'),
  ('en.yusufali', 43, 2, 'By the Book that makes things clear,-'),
  ('en.yusufali', 43, 3, 'We have made it a Qur\'an in Arabic, that ye may be able to understand (and learn wisdom).'),
  ('en.yusufali', 43, 4, 'And verily, it is in the Mother of the Book, in Our Presence, high (in dignity), full of wisdom.'),
  ('en.yusufali', 43, 5, 'Shall We then take away the Message from you and repel (you), for that ye are a people transgressing beyond bounds?'),
  ('en.yusufali', 43, 6, 'But how many were the prophets We sent amongst the peoples of old?'),
  ('en.yusufali', 43, 7, 'And never came there a prophet to them but they mocked him.'),
  ('en.yusufali', 43, 8, 'So We destroyed (them)- stronger in power than these;- and (thus) has passed on the Parable of the peoples of old.'),
  ('en.yusufali', 43, 9, 'If thou wert to question them, \'Who created the heavens and the earth?\' They would be sure to reply, \'they were created by (Him), the Exalted in Power, Full of Knowledge\';-'),
  ('en.yusufali', 43, 10, '(Yea, the same that) has made for you the earth (like a carpet) spread out, and has made for you roads (and channels) therein, in order that ye may find guidance (on the way);'),
  ('en.yusufali', 43, 11, 'That sends down (from time to time) rain from the sky in due measure;- and We raise to life therewith a land that is dead; even so will ye be raised (from the dead);-'),
  ('en.yusufali', 43, 12, 'That has created pairs in all things, and has made for you ships and cattle on which ye ride,'),
  ('en.yusufali', 43, 13, 'In order that ye may sit firm and square on their backs, and when so seated, ye may celebrate the (kind) favour of your Lord, and say, "Glory to Him Who has subjected these to our (use), for we could never have accomplished this (by ourselves),'),
  ('en.yusufali', 43, 14, '"And to our Lord, surely, must we turn back!"'),
  ('en.yusufali', 43, 15, 'Yet they attribute to some of His servants a share with Him (in his godhead)! truly is man a blasphemous ingrate avowed!'),
  ('en.yusufali', 43, 16, 'What! has He taken daughters out of what He himself creates, and granted to you sons for choice?'),
  ('en.yusufali', 43, 17, 'When news is brought to one of them of (the birth of) what he sets up as a likeness to (Allah) Most Gracious, his face darkens, and he is filled with inward grief!'),
  ('en.yusufali', 43, 18, 'Is then one brought up among trinkets, and unable to give a clear account in a dispute (to be associated with Allah)?'),
  ('en.yusufali', 43, 19, 'And they make into females angels who themselves serve Allah. Did they witness their creation? Their evidence will be recorded, and they will be called to account!'),
  ('en.yusufali', 43, 20, '("Ah!") they say, "If it had been the will of (Allah) Most Gracious, we should not have worshipped such (deities)!" Of that they have no knowledge! they do nothing but lie!'),
  ('en.yusufali', 43, 21, 'What! have We given them a Book before this, to which they are holding fast?'),
  ('en.yusufali', 43, 22, 'Nay! they say: "We found our fathers following a certain religion, and we do guide ourselves by their footsteps."'),
  ('en.yusufali', 43, 23, 'Just in the same way, whenever We sent a Warner before thee to any people, the wealthy ones among them said: "We found our fathers following a certain religion, and we will certainly follow in their footsteps."'),
  ('en.yusufali', 43, 24, 'He said: "What! Even if I brought you better guidance than that which ye found your fathers following?" They said: "For us, we deny that ye (prophets) are sent (on a mission at all)."'),
  ('en.yusufali', 43, 25, 'So We exacted retribution from them: now see what was the end of those who rejected (Truth)!'),
  ('en.yusufali', 43, 26, 'Behold! Abraham said to his father and his people: "I do indeed clear myself of what ye worship:'),
  ('en.yusufali', 43, 27, '"(I worship) only Him Who made me, and He will certainly guide me."'),
  ('en.yusufali', 43, 28, 'And he left it as a Word to endure among those who came after him, that they may turn back (to Allah).'),
  ('en.yusufali', 43, 29, 'Yea, I have given the good things of this life to these (men) and their fathers, until the Truth has come to them, and a messenger making things clear.'),
  ('en.yusufali', 43, 30, 'But when the Truth came to them, they said: "This is sorcery, and we do reject it."'),
  ('en.yusufali', 43, 31, 'Also, they say: "Why is not this Qur\'an sent down to some leading man in either of the two (chief) cities?"'),
  ('en.yusufali', 43, 32, 'Is it they who would portion out the Mercy of thy Lord? It is We Who portion out between them their livelihood in the life of this world: and We raise some of them above others in ranks, so that some may command work from others. But the Mercy of thy Lord is better than the (wealth) which they amass.'),
  ('en.yusufali', 43, 33, 'And were it not that (all) men might become of one (evil) way of life, We would provide, for everyone that blasphemes against (Allah) Most Gracious, silver roofs for their houses and (silver) stair-ways on which to go up,'),
  ('en.yusufali', 43, 34, 'And (silver) doors to their houses, and thrones (of silver) on which they could recline,'),
  ('en.yusufali', 43, 35, 'And also adornments of gold. But all this were nothing but conveniences of the present life: The Hereafter, in the sight of thy Lord is for the Righteous.'),
  ('en.yusufali', 43, 36, 'If anyone withdraws himself from remembrance of (Allah) Most Gracious, We appoint for him an evil one, to be an intimate companion to him.'),
  ('en.yusufali', 43, 37, 'Such (evil ones) really hinder them from the Path, but they think that they are being guided aright!'),
  ('en.yusufali', 43, 38, 'At length, when (such a one) comes to Us, he says (to his evil companion): "Would that between me and thee were the distance of East and West!" Ah! evil is the companion (indeed)!'),
  ('en.yusufali', 43, 39, 'When ye have done wrong, it will avail you nothing, that Day, that ye shall be partners in Punishment!'),
  ('en.yusufali', 43, 40, 'Canst thou then make the deaf to hear, or give direction to the blind or to such as (wander) in manifest error?'),
  ('en.yusufali', 43, 41, 'Even if We take thee away, We shall be sure to exact retribution from them,'),
  ('en.yusufali', 43, 42, 'Or We shall show thee that (accomplished) which We have promised them: for verily We shall prevail over them.'),
  ('en.yusufali', 43, 43, 'So hold thou fast to the Revelation sent down to thee; verily thou art on a Straight Way.'),
  ('en.yusufali', 43, 44, 'The (Qur\'an) is indeed the message, for thee and for thy people; and soon shall ye (all) be brought to account.'),
  ('en.yusufali', 43, 45, 'And question thou our messengers whom We sent before thee; did We appoint any deities other than (Allah) Most Gracious, to be worshipped?'),
  ('en.yusufali', 43, 46, 'We did send Moses aforetime, with Our Signs, to Pharaoh and his Chiefs: He said, "I am a messenger of the Lord of the Worlds."'),
  ('en.yusufali', 43, 47, 'But when he came to them with Our Signs, behold they ridiculed them.'),
  ('en.yusufali', 43, 48, 'We showed them Sign after Sign, each greater than its fellow, and We seized them with Punishment, in order that they might turn (to Us).'),
  ('en.yusufali', 43, 49, 'And they said, "O thou sorcerer! Invoke thy Lord for us according to His covenant with thee; for we shall truly accept guidance."'),
  ('en.yusufali', 43, 50, 'But when We removed the Penalty from them, behold, they broke their word.'),
  ('en.yusufali', 43, 51, 'And Pharaoh proclaimed among his people, saying: "O my people! Does not the dominion of Egypt belong to me, (witness) these streams flowing underneath my (palace)? What! see ye not then?'),
  ('en.yusufali', 43, 52, '"Am I not better than this (Moses), who is a contemptible wretch and can scarcely express himself clearly?'),
  ('en.yusufali', 43, 53, '"Then why are not gold bracelets bestowed on him, or (why) come (not) with him angels accompanying him in procession?"'),
  ('en.yusufali', 43, 54, 'Thus did he make fools of his people, and they obeyed him: truly were they a people rebellious (against Allah).'),
  ('en.yusufali', 43, 55, 'When at length they provoked Us, We exacted retribution from them, and We drowned them all.'),
  ('en.yusufali', 43, 56, 'And We made them (a people) of the Past and an Example to later ages.'),
  ('en.yusufali', 43, 57, 'When (Jesus) the son of Mary is held up as an example, behold, thy people raise a clamour thereat (in ridicule)!'),
  ('en.yusufali', 43, 58, 'And they say, "Are our gods best, or he?" This they set forth to thee, only by way of disputation: yea, they are a contentious people.'),
  ('en.yusufali', 43, 59, 'He was no more than a servant: We granted Our favour to him, and We made him an example to the Children of Israel.'),
  ('en.yusufali', 43, 60, 'And if it were Our Will, We could make angels from amongst you, succeeding each other on the earth.'),
  ('en.yusufali', 43, 61, 'And (Jesus) shall be a Sign (for the coming of) the Hour (of Judgment): therefore have no doubt about the (Hour), but follow ye Me: this is a Straight Way.'),
  ('en.yusufali', 43, 62, 'Let not the Evil One hinder you: for he is to you an enemy avowed.'),
  ('en.yusufali', 43, 63, 'When Jesus came with Clear Signs, he said: "Now have I come to you with Wisdom, and in order to make clear to you some of the (points) on which ye dispute: therefore fear Allah and obey me.'),
  ('en.yusufali', 43, 64, '"For Allah, He is my Lord and your Lord: so worship ye Him: this is a Straight Way."'),
  ('en.yusufali', 43, 65, 'But sects from among themselves fell into disagreement: then woe to the wrong-doers, from the Penalty of a Grievous Day!'),
  ('en.yusufali', 43, 66, 'Do they only wait for the Hour - that it should come on them all of a sudden, while they perceive not?'),
  ('en.yusufali', 43, 67, 'Friends on that day will be foes, one to another,- except the Righteous.'),
  ('en.yusufali', 43, 68, 'My devotees! no fear shall be on you that Day, nor shall ye grieve,-'),
  ('en.yusufali', 43, 69, '(Being) those who have believed in Our Signs and bowed (their wills to Ours) in Islam.'),
  ('en.yusufali', 43, 70, 'Enter ye the Garden, ye and your wives, in (beauty and) rejoicing.'),
  ('en.yusufali', 43, 71, 'To them will be passed round, dishes and goblets of gold: there will be there all that the souls could desire, all that their eyes could delight in: and ye shall abide therein (for eye).'),
  ('en.yusufali', 43, 72, 'Such will be the Garden of which ye are made heirs for your (good) deeds (in life).'),
  ('en.yusufali', 43, 73, 'Ye shall have therein abundance of fruit, from which ye shall have satisfaction.'),
  ('en.yusufali', 43, 74, 'The sinners will be in the Punishment of Hell, to dwell therein (for aye):'),
  ('en.yusufali', 43, 75, 'Nowise will the (Punishment) be lightened for them, and in despair will they be there overwhelmed.'),
  ('en.yusufali', 43, 76, 'Nowise shall We be unjust to them: but it is they who have been unjust themselves.'),
  ('en.yusufali', 43, 77, 'They will cry: "O Malik! would that thy Lord put an end to us!" He will say, "Nay, but ye shall abide!"'),
  ('en.yusufali', 43, 78, 'Verily We have brought the Truth to you: but most of you have a hatred for Truth.'),
  ('en.yusufali', 43, 79, 'What! have they settled some plan (among themselves)? But it is We Who settle things.'),
  ('en.yusufali', 43, 80, 'Or do they think that We hear not their secrets and their private counsels? Indeed (We do), and Our messengers are by them, to record.'),
  ('en.yusufali', 43, 81, 'Say: "If (Allah) Most Gracious had a son, I would be the first to worship."'),
  ('en.yusufali', 43, 82, 'Glory to the Lord of the heavens and the earth, the Lord of the Throne (of Authority)! (He is free) from the things they attribute (to him)!'),
  ('en.yusufali', 43, 83, 'So leave them to babble and play (with vanities) until they meet that Day of theirs, which they have been promised.'),
  ('en.yusufali', 43, 84, 'It is He Who is Allah in heaven and Allah on earth; and He is full of Wisdom and Knowledge.'),
  ('en.yusufali', 43, 85, 'And blessed is He to Whom belongs the dominion of the heavens and the earth, and all between them: with Him is the Knowledge of the Hour (of Judgment): and to Him shall ye be brought back.'),
  ('en.yusufali', 43, 86, 'And those whom they invoke besides Allah have no power of intercession;- only he who bears witness to the Truth, and they know (him).'),
  ('en.yusufali', 43, 87, 'If thou ask them, who created them, they will certainly say, Allah: How then are they deluded away (from the Truth)?'),
  ('en.yusufali', 43, 88, '(Allah has knowledge) of the (Prophet\'s) cry, "O my Lord! Truly these are people who will not believe!"'),
  ('en.yusufali', 43, 89, 'But turn away from them, and say "Peace!" But soon shall they know!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 43, 1, 'Haa-Meeem'),
  ('en.transliteration', 43, 2, 'Wal Kitaabil Mubeen'),
  ('en.transliteration', 43, 3, 'Innaa ja\'alnaahu Quraanan \'Arabiyyal la\'allakum ta\'qiloon'),
  ('en.transliteration', 43, 4, 'Wa innahoo feee Ummil Kitaabi Ladainaa la\'aliyyun hakeem'),
  ('en.transliteration', 43, 5, 'Afanadribu \'ankumuz Zikra safhan an kuntum qawmam musrifeen'),
  ('en.transliteration', 43, 6, 'Wa kam arsalnaa min Nabiyyin fil awwaleen'),
  ('en.transliteration', 43, 7, 'Wa maa yaateehim min Nabiyyin illaa kaanoo bihee yasahzi\'oon'),
  ('en.transliteration', 43, 8, 'Fa ahlaknaaa ashadda minhum batshanw wa madaa masalul lawwaleen'),
  ('en.transliteration', 43, 9, 'Wa la\'in sa altahum man khalaqas samaawaati wal arda la yaqoolunna khalaqa hunnal \'Azeezul \'Aleem'),
  ('en.transliteration', 43, 10, 'Allazee ja\'ala lakumul arda mahdanw wa ja\'ala lakum feehaa subulal la\'allakum tahtadoon'),
  ('en.transliteration', 43, 11, 'Wallazee nazzala minas samaaa\'i maaa\'am biqadarin fa anshamaa bihee baldatam maitaa\' kazaalika tukhrajoon'),
  ('en.transliteration', 43, 12, 'Wallazee khalaqal azwaaja kullahaa wa ja\'ala lakum minal fulki wal-an\'aami maa tarkaboon'),
  ('en.transliteration', 43, 13, 'Litastawoo \'alaa zuhoorihee summa tazkuroo ni\'mata Rabbikum izastawaitum \'alaihi wa taqooloo Subhaanal lazee sakhkhara lana haaza wa maa kunnaa lahoo muqrineen'),
  ('en.transliteration', 43, 14, 'Wa innaaa ilaa Rabbinaa lamunqaliboon'),
  ('en.transliteration', 43, 15, 'Wa ja\'aloo lahoo min \'ibaadihee juz\'aa; innal insaana lakafoorum mubeen'),
  ('en.transliteration', 43, 16, 'Amit takhaza mimmaa yakhluqu banaatinw wa asfaakum bilbaneen'),
  ('en.transliteration', 43, 17, 'Wa izaa bushshira ahaduhum bimaa daraba lir Rahmaani masalan zalla wajhuhoo muswaddanw wa hua kazeem'),
  ('en.transliteration', 43, 18, 'Awa mai yunashsha\'u fil hilyati wa huwa fil khisaami ghairu mubeen'),
  ('en.transliteration', 43, 19, 'Wa ja\'alul malaaa\'ikatal lazeena hum \'ibaadur Rahmaani inaasaa; a shahidoo khalaqhum; satuktabu shahaa datuhum wa yus\'aloon'),
  ('en.transliteration', 43, 20, 'Wa qaaloo law shaaa\'ar Rahmaanu maa \'abadnaahum; maa lahum bizaalika min \'ilmin in hum illaa yakhrusoon'),
  ('en.transliteration', 43, 21, 'Am aatainaahum Kitaabam min qablihee fahum bihee mustamsikoon'),
  ('en.transliteration', 43, 22, 'Bal qaalooo innaa wajadnaaa aabaaa\'anaa \'alaaa ummatinw wa innaa \'alaaa aasaarihim muhtadoon'),
  ('en.transliteration', 43, 23, 'Wa kazaalika maaa arsalnaa min qablika fee qaryatim min nazeerin illaa qaala mutrafoohaaa innaa wajadnaaa aabaaa\'anaa \'alaaa ummatinw wa innaa \'alaaa aasaarihim muqtadoon'),
  ('en.transliteration', 43, 24, 'Qaala awa law ji\'tukum bi ahdaa mimmaa wajattum \'alaihi aabaaa\'akum qaalooo innaa bimaaa ursiltum bihee kaafiroon'),
  ('en.transliteration', 43, 25, 'Fantaqamnaa minhum fanzur kaifa kaana \'aaqibatul mukazzibeen'),
  ('en.transliteration', 43, 26, 'Wa iz qaala Ibraaheemu liabeehi wa qawmiheee innane baraaa\'um mimmaa ta\'budo'),
  ('en.transliteration', 43, 27, 'Illal lazee fataranee innahoo sa yahdeen'),
  ('en.transliteration', 43, 28, 'Wa ja\'alahaa Kalimatam baaqiyatan fee \'aqibihee la\'al lahum yarji\'oon'),
  ('en.transliteration', 43, 29, 'Bal matta\'tu haaa\'ulaaa\'i wa aabaaa\'ahum hattaa jaaa\'a humul haqqu wa Rasoolum mubeen'),
  ('en.transliteration', 43, 30, 'Wa lammaa jaaa\'ahumul haqqu qaaloo haazaa sihrunw wa innaa bihee kaafiroon'),
  ('en.transliteration', 43, 31, 'Wa qaaloo law laa nuzzila haazal Quraanu \'alaa rajulim minal qaryataini \'azeem'),
  ('en.transliteration', 43, 32, 'Ahum yaqsimoona rahmata Rabbik; Nahnu qasamnaa bainahum ma\'eeshatahum fil hayaatid dunyaa wa rafa\'naa ba\'dahum fawqa ba\'din darajaatil liyattakhiza ba\'duhum ba\'dan sukhriyyaa; wa rahmatu Rabbika khairum mimmaa yajma\'oon'),
  ('en.transliteration', 43, 33, 'Wa law laaa any yakoonan naasu ummatanw waahidatal laja\'alnaa limany yakfuru bir Rahmaani libu yootihim suqufam min fiddatinw wa ma\'aarija \'alaihaa yazharoon'),
  ('en.transliteration', 43, 34, 'Wa libu yootihim abwaabanw wa sururan \'alaihaa yattaki\'oon'),
  ('en.transliteration', 43, 35, 'Wa zukhrufaa; wa in kullu zaalika lammaa mataa\'ul hayaatid dunyaa; wal aakhiratu \'inda Rabbika lilmuttaqeen'),
  ('en.transliteration', 43, 36, 'Wa mai ya\'shu \'an zikrir Rahmaani nuqaiyid lahoo Shaitaanan fahuwa lahoo qareen'),
  ('en.transliteration', 43, 37, 'Wa innahum la yasuddoo nahum \'anis sabeeli wa yahsaboona annahum muhtadoon'),
  ('en.transliteration', 43, 38, 'Hattaaa izaa jaaa\'anaa qaala yaa laita bainee wa bainaka bu\'dal mashriqaini fabi\'sal qareen'),
  ('en.transliteration', 43, 39, 'Wa lai yanfa\'akumul Yawma iz zalamtum annakum fil \'azaabi mushtarikoon'),
  ('en.transliteration', 43, 40, 'Afa anta tusmi\'us summa aw tahdil \'umya wa man kaana fee dalaalim mubeen'),
  ('en.transliteration', 43, 41, 'Fa immaa nazhabanna bika fa innaa minhum muntaqimoon'),
  ('en.transliteration', 43, 42, 'Aw nuriyannakal lazee wa\'adnaahum fa innaa \'alaihim muqtadiroon'),
  ('en.transliteration', 43, 43, 'Fastamsik billazeee oohi ya ilaika innaka \'alaa Siraatim Mustaqeem'),
  ('en.transliteration', 43, 44, 'Wa innahoo lazikrul laka wa liqawmika wa sawfa tus\'aloon'),
  ('en.transliteration', 43, 45, 'Was\'al man arsalnaa min qablika mir Rusulinaaa aja\'alnaa min doonir Rahmaani aalihatany yu badoon'),
  ('en.transliteration', 43, 46, 'Wa laqad arsalnaa Moosaa bi aayaatinaaa ilaa Fir\'awna wa mala\'ihee faqaala innee Rasoolu Rabbil \'aalameen'),
  ('en.transliteration', 43, 47, 'Falammma jaaa\'ahum bi aayaatinaaa izaa hum minhaa yadhakoon'),
  ('en.transliteration', 43, 48, 'Wa maa nureehim min aayatin illaa hiya akbaru min ukhtihaa wa akhaznaahum bil\'azaabi la\'allahum yarji\'oon'),
  ('en.transliteration', 43, 49, 'Wa qaaloo yaaa ayyuhas saahirud\'u lanaa Rabbaka bimaa \'ahida \'indaka innanaa lamuhtadoon'),
  ('en.transliteration', 43, 50, 'Falammaa kashafnaa \'anhumul \'azaaba izaa hum yankusoon'),
  ('en.transliteration', 43, 51, 'Wa naadaa Fir\'awnu fee qawmihee qaala yaa qawmi alaisa lee mulku Misra wa haazihil anhaaru tajree min tahtee afalaa tubsiroon'),
  ('en.transliteration', 43, 52, 'Am ana khairum min haazal lazee huwa maheenunw wa laa yuakaadu yubeen'),
  ('en.transliteration', 43, 53, 'Falaw laa ulqiya \'alaihi aswiratum min zahabin awjaaa\'a ma\'ahul malaaa\'ikatu muqtarineen'),
  ('en.transliteration', 43, 54, 'Fastakhaffa qawmahoo fa ataa\'ooh; innahum kaanoo qawman faasiqeen'),
  ('en.transliteration', 43, 55, 'Falammaaa aasafoonan taqamnaa minhum fa aghraqnaahum ajma\'een'),
  ('en.transliteration', 43, 56, 'Faja\'alnaahum salafanw wa masalal lil aakhireen'),
  ('en.transliteration', 43, 57, 'Wa lammaa duribab nu Maryama masalan izaa qawmu ka minhu yasidoon'),
  ('en.transliteration', 43, 58, 'Wa qaalooo \'a-aalihatunaa khairun am hoo; maa daraboohu laka illaa jadalaa; balhum qawmun khasimoon'),
  ('en.transliteration', 43, 59, 'In huwa illaa \'abdun an\'amnaa \'alaihi wa ja\'alnaahu masalal li Baneee Israaa\'eel'),
  ('en.transliteration', 43, 60, 'Wa law nashaaa\'u laja\'alnaa minkum malaaa\'ikatan fil ardi yakhlufoon'),
  ('en.transliteration', 43, 61, 'Wa innahoo la\'ilmul lis Saa\'ati fala tamtarunna bihaa wattabi\'oon; haazaa Siraatum Mustaqeem'),
  ('en.transliteration', 43, 62, 'Wa laa yasuddan nakumush Shaitaanu innahoo lakum \'aduwwum mubeen'),
  ('en.transliteration', 43, 63, 'Wa lammaa jaaa\'a \'Eesaa bilbaiyinaati qaala qad ji\'tukum bil Hikmati wa li-ubaiyina lakum ba\'dal lazee takhtalifoona feehi fattaqul laaha wa atee\'oon'),
  ('en.transliteration', 43, 64, 'Innal laaha Huwa Rabbee wa Rabbukum fa\'budooh; haaza Siraatum Mustaqeem'),
  ('en.transliteration', 43, 65, 'Fakhtalafal ahzaabu mim bainihim fawailul lillazeena zalamoo min \'azaabi Yawmin aleem'),
  ('en.transliteration', 43, 66, 'Hal yanzuroona illas Saa\'ata an taatiyahum baghtatanw wa hum laa yash\'uroon'),
  ('en.transliteration', 43, 67, 'Al akhillaaa\'u Yawma\'izim ba\'duhum liba\'din \'aduwwun illal muttaqeen'),
  ('en.transliteration', 43, 68, 'Yaa \'ibaadi laa khawfun \'alaikumul Yawma wa laaa antum tahzanoon'),
  ('en.transliteration', 43, 69, 'Allazeena aamanoo bi Aayaatinaa wa kaanoo muslimeen'),
  ('en.transliteration', 43, 70, 'Udkhulul Jannata antum wa azwaajukum tuhbaroon'),
  ('en.transliteration', 43, 71, 'Yutaafu \'alaihim bishaa fim min zahabinw wa akwaab, wa feehaa maatashtaheehil anfusu wa talazzul a\'yunu wa antum feehaa khaalidoon'),
  ('en.transliteration', 43, 72, 'Wa tilkal jannatul lateee ooristumoohaa bimaa kuntum ta\'maloon'),
  ('en.transliteration', 43, 73, 'Lakum feehaa faakihatun kaseeratum minhaa taakuloon'),
  ('en.transliteration', 43, 74, 'Innal mujrimeena fee \'azaabi jahannama khaalidoon'),
  ('en.transliteration', 43, 75, 'Laa yufattaru \'anhum wa hum feehi mublisoon'),
  ('en.transliteration', 43, 76, 'Wa maa zalamnaahum wa laakin kaanoo humuz zaalimeen'),
  ('en.transliteration', 43, 77, 'Wa naadaw yaa Maaliku liyaqdi \'alainaa Rabbuka qaala innakum maakisson'),
  ('en.transliteration', 43, 78, 'Laqad ji\'naakum bilhaqqi wa laakinna aksarakum lilhaqqi kaarihoon'),
  ('en.transliteration', 43, 79, 'Am abramooo amran fainnaa mubrimoon'),
  ('en.transliteration', 43, 80, 'Am yahsaboona annaa laa nasma\'u sirrahum wa najwaahum; balaa wa Rusulunaa ladaihim yaktuboon'),
  ('en.transliteration', 43, 81, 'Qul in kaana lir Rahmaani walad; fa-ana awwalul \'aabideen'),
  ('en.transliteration', 43, 82, 'Subhaana Rabbis samaawaati wal ardi Rabbil Arshi \'ammaa yasifoon'),
  ('en.transliteration', 43, 83, 'Fazarhum yakhoodoo wa yal\'aboo hattaa yulaaqoo Yawmahumul lazee yoo\'adoon'),
  ('en.transliteration', 43, 84, 'Wa Huwal lazee fissamaaa\'i Ilaahunw wa fil ardi Ilaah; wa Huwal Hakeemul\'Aleem'),
  ('en.transliteration', 43, 85, 'Wa tabaarakal lazee lahoo mulkus samaawaati wal ardi wa maa bainahumaa wa \'indahoo \'ilmus Saa\'ati wa ilaihi turja\'oon'),
  ('en.transliteration', 43, 86, 'Wa laa yamlikul lazeena yad\'oona min doonihish shafaa\'ata illaa man shahida bilhaqqi wa hum ya\'lamoon'),
  ('en.transliteration', 43, 87, 'Wa la\'in sa altahum man khalaqahum la yaqoolun nallaahu fa annaa yu\'fakoon'),
  ('en.transliteration', 43, 88, 'Wa qeelihee yaa Rabbi inna haa\'ulaaa\'i qawmul laa yu\'minoon'),
  ('en.transliteration', 43, 89, 'Fasfah \'anhum wa qul salaam; fasawfa ya\'lamoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 43, 1, 'حمۤ'),
  ('ur.ahmedali', 43, 2, 'روشن کتاب کی قسم ہے'),
  ('ur.ahmedali', 43, 3, 'ہم نے اسے عربی زبان میں قرآن بنایا ہے تاکہ تم سمجھو'),
  ('ur.ahmedali', 43, 4, 'اور یہ کتاب لوح محفوظ میں ہمارے نزدیک بلند مرتبہ حکمت والی ہے'),
  ('ur.ahmedali', 43, 5, 'کیا تمہارے سمجھانے سے ہم اس لیے منہ پھیر لیں گے کہ تم بیہودہ لوگ ہو'),
  ('ur.ahmedali', 43, 6, 'اور پہلے لوگوں میں بھی ہم نے بہت سے نبی بھیجے ہیں'),
  ('ur.ahmedali', 43, 7, 'اور ان کے پاس ایسا کوئی نبی نہ آتا تھا کہ جس سے وہ ٹھٹھا نہ کرتے تھے'),
  ('ur.ahmedali', 43, 8, 'پھر ہم نے ان میں بڑے زور والوں کو ہلاک کر دیا او رپہلوں کی مثال گزرچکی ہے'),
  ('ur.ahmedali', 43, 9, 'اور اگر آپ ان سے پوچھیں کہ آسمانوں اور زمین کو کس نے پیدا کیا ہے تو ضرور کہیں گے کہ انہیں اس بڑے زبردست جاننے والے نے پیدا کیا ہے'),
  ('ur.ahmedali', 43, 10, 'وہ جس نے زمین کو تمہارا بچھونا بنایا اور تمہارے لیے اس میں راستے بنائے تاکہ تم راہ پاؤ'),
  ('ur.ahmedali', 43, 11, 'اور وہ جس نے آسمان سے اندازے کے ساتھ پانی اتارا پھر ہم نے اس سے مردہ بستی کو زندہ کیا تم بھی اس طرح (قبروں سے) نکالے جاؤ گے'),
  ('ur.ahmedali', 43, 12, 'اوروہ جس نے ہر قسم کے جوڑے بنائے اور تمہارے لیے وہ کشتیاں اور چار پائے بنائے جن پر تم سوار ہوتے ہو'),
  ('ur.ahmedali', 43, 13, 'تاکہ ان کی پیٹھ پر چڑھ کر اپنے رب کا احسان یاد کرو جب کہ تم ان پر خوب بیٹھ جاؤ اورکہو وہ ذات پاک ہے جس نے ہمارے لیے اسے مطیع کر دیا اور ہم اسے قابو میں لانے والے نہ تھے'),
  ('ur.ahmedali', 43, 14, 'اور بےشک ہم اپنے رب کی طرف لوٹنے والے ہیں'),
  ('ur.ahmedali', 43, 15, 'اورلوگوں نے اس کے بندوں کو اس کی اولاد بنا دیا بے شک انسان صریح ناشکرا ہے'),
  ('ur.ahmedali', 43, 16, 'کیا اس نے اپنی مخلوقات میں سے بیٹیاں لے لیں اور تمہیں بیٹے چن کر دیئے'),
  ('ur.ahmedali', 43, 17, 'اور جب ان میں سے کسی کو اس چیز کی خوشخبری دی جائے جسے رحمان کے لیے ٹھیراتا ہے تو اس کا منہ سیاہ ہو جاتا ہے اور و ہ دل میں کڑھتا رہتا ہے'),
  ('ur.ahmedali', 43, 18, 'کیا اس کے لیے وہ ہے جو زیور میں پلتی ہے اور وہ جھگڑتے میں بات نہیں کر سکتی'),
  ('ur.ahmedali', 43, 19, 'اورفرشتوں کو جو رحمان کے بندے ہیں عورتیں فرض کر لیا کیا انھوں نے پیدا ہوتے دیکھا ہے ان کی گواہی لکھی جائے گی اور ان سے پوچھا ئے گا'),
  ('ur.ahmedali', 43, 20, 'اور کہتے ہیں اگر رحمان چاہتا تو ہم انہیں نہ پوجتے انہیں اس کی کچھ خبر نہیں وہ محض اٹکل دوڑاتے ہیں'),
  ('ur.ahmedali', 43, 21, 'کیا ہم نے انہیں اس سے پہلے کوئی کتاب دی ہے کہ یہ اس پر قائم ہیں'),
  ('ur.ahmedali', 43, 22, 'بلکہ وہ کہتے ہیں کہ ہم نے اپنے باپ دادا کو ایک طریقہ پر پایا ہے اور انہیں کے ہم پیرو ہیں'),
  ('ur.ahmedali', 43, 23, 'اور اسی طرح ہم نے آپ سے پہلے کسی گاؤں میں بھی کوئی ڈرانے والا بھیجا تو وہاں کے دولت مندوں نے (یہی) کہا کہ ہم نے اپنے باپ دادا کو ایک طریقہ پر پایا اور ہم انہیں کے پیرو ہیں'),
  ('ur.ahmedali', 43, 24, 'رسول نے کہا اگرچہ میں تمہارے پاس اس سے بھی بہتر طریقہ لاؤں جس پر تم نے اپنے باپ دادا کو پایا انہوں نے کہا جو کچھ تو لایا ہے ہم اس کے منکر ہیں'),
  ('ur.ahmedali', 43, 25, 'پھر ہم نے ان سے بدلہ لیا پھر دیکھ جھٹلانے والوں کا انجام کیا ہوا'),
  ('ur.ahmedali', 43, 26, 'اور جب ابراھیم نے اپنے باپ اور اپنی قوم سے کہا کہ بے شک میں ان سے بیزار ہوں جن کی تم عبادت کرتے ہو'),
  ('ur.ahmedali', 43, 27, 'سوائے اس ذات کے جس نے تجھے پیدا کیا سو بے شک وہی تجھے راہ دکھائے گا'),
  ('ur.ahmedali', 43, 28, 'اور یہی بات اپنی اولاد میں پیچھے چھوڑ گیا تاکہ وہ رجوع کریں'),
  ('ur.ahmedali', 43, 29, 'بلکہ میں نے ان کو اوران کے باپ دادا کو خوب سامان دیا یہاں تک کہ ان کے پاس سچا قرآن اور صاف صاف بتانے والا رسول آیا'),
  ('ur.ahmedali', 43, 30, 'اورجب ان کے پاس سچا قرآن پہنچا تو کہا کہ یہ توجادو ہے اور ہم اسے نہیں مانتے'),
  ('ur.ahmedali', 43, 31, 'اور کہا کیوں یہ قرآن ان دو بستیوں کےکسی سردار پر نازل نہیں کیا گیا'),
  ('ur.ahmedali', 43, 32, 'کیا وہ آپ کے رب کی رحمت تقسیم کرتے ہیں ان کی روزی تو ہم نے ان کے درمیان دنیا کی زندگی میں تقسیم کی ہے اور ہم نے بعض کے بعض پر درجے بلند کیے تاکہ ایک دوسرے کو محکوم بنا کررکھے اور آپ کے رب کی رحمت اس سے کہیں بہتر ہے جو وہ جمع کرتے ہیں'),
  ('ur.ahmedali', 43, 33, 'اوراگر یہ نہ ہوتا کہ سب لوگ ایک طریقہ کے ہوجائیں گے (کافر) تو جو الله کے منکر ہیں انکے گھروں کی چھت اور ان پر چڑھنے کی سیڑھیاں چاندی کی کر دیتے'),
  ('ur.ahmedali', 43, 34, 'اوران کے گھروں کے دروازے اور تخت بھی چاندی کے کر دیتے جن پر وہ تکیہ لگا کر بیٹھتے ہیں'),
  ('ur.ahmedali', 43, 35, 'اور سونے کے بھی اور یہ سب کچھ دنیا کی زندگی کا سامان ہے اور آخرت آپ کے رب کے ہاں پرہیزگاروں کے لیے ہے'),
  ('ur.ahmedali', 43, 36, 'اورجو الله کی یاد سے غافل ہوتا ہے تو ہم اس پر ایک شیطان متعین کر تے ہیں پھر وہ اس کا ساتھی رہتا ہے'),
  ('ur.ahmedali', 43, 37, 'اور شیاطین آدمیوں کو راستے سے روکتے ہیں اور وہ سمجھتے ہیں کہ ہم راہِ راست پر ہیں'),
  ('ur.ahmedali', 43, 38, 'یہاں تک کہ جب وہ ہمارے پاس آئے گا تو کہے گا اے کاش میرے اور تیرے درمیان مشرق اور مغرب کی دوری ہوتی پس کیسا برا ساتھی ہے'),
  ('ur.ahmedali', 43, 39, 'اورآج تمہیں یہ بات ہر گز نفع نہ دے گی چونکہ تم نے ظلہم کیا تھا بے شک تم عذاب میں شریک ہو'),
  ('ur.ahmedali', 43, 40, 'پس کیا آپ بہروں کو سنا سکتے ہیں یااندھوں کو راہ دکھا سکتے ہیں اور انہیں جو صریح گمراہی میں ہیں'),
  ('ur.ahmedali', 43, 41, 'پس اگر ہم آپ کو (دنیا سے) اٹھالیں تو بھی ہم ان سے بدلہ لیں گے'),
  ('ur.ahmedali', 43, 42, 'یا اگر ہم آپ کووہ دکھا بھی دیں جس کا ہم نے ان سے وعدہ کیا ہے تو ہم ان پر قادر ہیں'),
  ('ur.ahmedali', 43, 43, 'پھر آپ مضبوطی سے پکڑیں اسے جو آپ کی طرف وحی کیا گیا ہے بے شک آپ سیدھے راستہ پر ہیں'),
  ('ur.ahmedali', 43, 44, 'اور بے شک وہ (قرآن) آپ کے لیے اور آپ کی قوم کے لیے ایک نصیحت ہے اور تم سب سے ا سکی باز پرس ہو گی'),
  ('ur.ahmedali', 43, 45, 'اور آپ ان سب پیغمبروں سے جنہیں ہم نے آپ سے پہلے بھیجا ہے پوچھ لیجیئے کیا ہم نے رحمان کے سوا دوسرے معبود ٹھیرا لئے تھے کہ انکی عبادت کی جائے'),
  ('ur.ahmedali', 43, 46, 'اور ہم نے موسیٰ کو اپنی نشانیاں دے کر فرعون اور اس کے امرائے دربار کی طرف بھیجا تھا سو اس نے کہا کہ میں پروردگار عالم کا رسول ہوں'),
  ('ur.ahmedali', 43, 47, 'پس جب وہ ان کے پاس ہماری نشانیاں لایا تو وہ اس کی ہنسی اڑانے لگے'),
  ('ur.ahmedali', 43, 48, 'اور ہم ان کو جو کوئی نشانی دکھاتے تھے تو ایک دوسرے سے بڑھ کر ہوتی تھی اور ہم نے انہیں عذاب میں پکڑا تاکہ وہ باز آ جائیں'),
  ('ur.ahmedali', 43, 49, 'اور انہوں نے کہا اے جادوگر اپنے رب سے ہمارے لیے اس عہد سے جو تجھ سے اس نے کیا ہے دعا کر ہم ضرور راہ پر آجائیں گے'),
  ('ur.ahmedali', 43, 50, 'پھر جب ہم ان سے عذاب ہٹا لیتے تو اسی وقت عہد کو توڑ دیتے'),
  ('ur.ahmedali', 43, 51, 'اور فرعون نے اپنی قوم میں منادی کر کے کہہ دیا اے میری قوم کیا میرےلیے مصر کی بادشاہت نہیں اور کیا یہ نہریں میرے (محل کے) نیچے سے نہیں بہہ رہی ہیں پھر کیا تم نہیں دیکھتے'),
  ('ur.ahmedali', 43, 52, 'کیا میں اس سے بہتر نہیں ہوں جو ذلیل ہے اور صاف صاف بات بھی نہیں کر سکتا'),
  ('ur.ahmedali', 43, 53, 'پھر اس کے لیے سونےکے کنگن کیوں نہیں اتارے گئے یا اس کے ہمراہ فرشتے پرے باندھے ہوئے آئے ہوتے'),
  ('ur.ahmedali', 43, 54, 'پس اس نے اپنی قوم کو احمق بنا دیا پھر ا س کے کہنے میں آ گئے کیو ں کہ وہ بدکار لوگ تھے'),
  ('ur.ahmedali', 43, 55, 'پس جب انہوں نے ہمیں غصہ دلا دیا تو ہم نے ان سے بدلہ لیا ہم نے ان سب کو غرق کر دیا'),
  ('ur.ahmedali', 43, 56, 'پھر ہم نے انہیں گئے گزرے اور پیچھے آنے والوں کے لیے کہاوت بنا دیا'),
  ('ur.ahmedali', 43, 57, 'اورجب ابن مریم کی مثال بیان کی گئی تو اسی وقت آپ کی قوم کے لوگ اس سے کھلکھلا کر ہنسنے لگے'),
  ('ur.ahmedali', 43, 58, 'اورکہا کیا ہمارے معبود بہتر ہیں یا وہ یہ ذکر صرف آپ سے جھگڑنے کے لیے کرتے ہیں بلکہ وہ تو جھگڑالو ہی ہیں'),
  ('ur.ahmedali', 43, 59, 'وہ تو ہمارا ایک بندہ ہے جس پر ہم نے انعام کیا اور اسے بنی اسرائیل کے لیے نمونہ بنا دیا تھا'),
  ('ur.ahmedali', 43, 60, 'اور اگر ہم چاہیں تم میں سے فرشتے پیدا کریں جو زمین میں تمہاری جگہ رہیں'),
  ('ur.ahmedali', 43, 61, 'اور البتہ عیسیٰ قیامت کی ایک نشانی ہے پس تم اس میں شبہ نہ کرو اور میری تابعداری کرو یہی سیدھا راستہ ہے'),
  ('ur.ahmedali', 43, 62, 'اور تمہیں شیطان نہ روکنے پائیں کیوں کہ وہ تمہارا صریح دشمن ہے'),
  ('ur.ahmedali', 43, 63, 'اور جب عیسیٰ واضح دلیلیں لے کر آیا تھا تو اس نے کہا تھا کہ میں تمہارے پاس دانائی کی باتیں لایا ہوں اورتاکہ تم پر بعض وہ باتیں واضح کر دوں جن میں تم اختلاف کرتے تھے پس الله سے ڈرو اور میرا حکم مانو'),
  ('ur.ahmedali', 43, 64, 'بے شک الله ہی میرا اور تمہارا پروردگار ہے پس اسی کی عبادت کرو وہی سیدھا راستہ ہے'),
  ('ur.ahmedali', 43, 65, 'پھر لوگ ایک دوسرے سے مختلف ہو گئے پس جنہوں نے ظلم کیا ان کے لیے دردناک دن کے عذاب سے تباہی ہے'),
  ('ur.ahmedali', 43, 66, 'کیا وہ قیامت کے ہی منتظر ہیں کہ ان پر یکایک آجائے اور ان کو خبر بھی نہ ہو'),
  ('ur.ahmedali', 43, 67, 'اس دن دوست بھی آپس میں دشمن ہو جائیں گے مگر پرہیز گار لوگ'),
  ('ur.ahmedali', 43, 68, '(کہا جائے گا) اے میرے بندو تم پر آج نہ کوئی خوف ہے اور نہ تم غمگین ہو گے'),
  ('ur.ahmedali', 43, 69, 'جو لوگ ہماری آیتوں پر ایمان لائے اور فرمانبردار تھے'),
  ('ur.ahmedali', 43, 70, 'تم اور تمہاری بیویاں خوشیاں کرتے ہوئے جنت میں داخل ہوجاؤ'),
  ('ur.ahmedali', 43, 71, 'ان کے سامنے سونے کے پیالے پیش کیے جائیں گے اور آبخورے بھی اور وہاں جس چیز کو دل چاہے گا اوبر جس سے آنکھیں خوش ہوں گی موجود ہو گی اور تم اس میں ہمیشہ رہو گے'),
  ('ur.ahmedali', 43, 72, 'اور یہی وہ جنت ہے جس کے تم وارث بنائے گئے ہو ان اعمال کے بدلے میں جو تم کرتے تھے'),
  ('ur.ahmedali', 43, 73, 'تمہارے لیے وہاں بہت سے میوے ہیں جن میں سے کھایا کرو گے'),
  ('ur.ahmedali', 43, 74, 'بے شک گناہگار عذاب دوزخ ہی میں ہمیشہ رہیں گے'),
  ('ur.ahmedali', 43, 75, 'ان سے ہلکا نہ کیا جائے گا اور وہ اسی میں مایوس پڑے رہیں گے'),
  ('ur.ahmedali', 43, 76, 'اور ہم نے تو ان پر ظلم نہیں کیا لیکن وہ خود ہی ظالم تھے'),
  ('ur.ahmedali', 43, 77, 'اور وہ پکاریں گے اے مالک تیرا پروردگار ہمارا کام تمام کر دے وہ کہے گا بے شک تمہیں تو ہمیشہ رہنا ہے'),
  ('ur.ahmedali', 43, 78, 'ہم تو تمہارے پاس سچا دین لا چکےاورلیکن تم میں سے اکثر دین حق سے نفرت کرتے ہیں'),
  ('ur.ahmedali', 43, 79, 'کیا انہوں نے کوئی بات طے کرلی ہے تو ہم بھی طے کرنے والے ہیں'),
  ('ur.ahmedali', 43, 80, 'کیا وہ خیال کرتے ہیں کہ ہم ان کا بھید اور مشورہ نہیں سنتے کیوں نہیں اور ہمارے بھیجے ہوئے فرشتے ان کے پاس لکھ رہے ہیں'),
  ('ur.ahmedali', 43, 81, 'کہہ دو اگر الله کا بیٹا ہوتا تو سب سے پہلے میں عبادت کرتا'),
  ('ur.ahmedali', 43, 82, 'آسمانوں اور زمین اور عرش کا رب پاک ہے ان باتوں سے جو وہ بناتے ہیں'),
  ('ur.ahmedali', 43, 83, 'پھر انہیں چھوڑ دو بک بک اور کھیل کود میں لگے رہیں یہاں تک کہ وہ دن دیکھ لیں جس کا ان سے وعدہ کیا جاتا ہے'),
  ('ur.ahmedali', 43, 84, 'او روہی ہے جو آسمان میں بھی معبود ہے اور زمین میں بھی معبود ہے اور وہی حکمت والا جاننے والا ہے'),
  ('ur.ahmedali', 43, 85, 'اور وہ بڑا بابرکت ہے جس کی حکومت آسمانوں اور زمین میں ہے اور جو ان دونوں کے درمیان موجود ہے اور اسی کے پاس قیامت کا علم ہے اور اسی کی طرف تم سب لوٹائے جاؤ گے'),
  ('ur.ahmedali', 43, 86, 'اورجنہیں وہ اس کے سوا پکارتے ہیں انہیں تو شفاعت کا بھی اختیا رنہیں ہاں جن لوگوں نے حق بات کا اقرار کیا تھا اور وہ تصدیق بھی کرتے تھے'),
  ('ur.ahmedali', 43, 87, 'اور اگر آپ ان سے پوچھیں کہ انہیں کس نے پیدا کیا ہے تو ضرور کہیں گے الله نے پھر کہا ں بہکے جا رہے ہیں'),
  ('ur.ahmedali', 43, 88, 'اور قسم ہے رسول کے یا رب پکارنے کی بے شک یہ ایسے لوگ ہیں کہ ایمان نہ لائیں گے'),
  ('ur.ahmedali', 43, 89, 'پس آپ بھی ان سے منہ پھیر لیں اور سلام کہہ دیں پس انہیں خو دمعلوم ہو جائے گا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 43, 1, 'Ha, Mim,'),
  ('tr.diyanet', 43, 2, 'Apaçık Kitap\'a and olsun ki, akledesiniz diye Kuran\'ı Arapça okunan bir Kitap kılmışızdır.'),
  ('tr.diyanet', 43, 3, 'Apaçık Kitap\'a and olsun ki, akledesiniz diye Kuran\'ı Arapça okunan bir Kitap kılmışızdır.'),
  ('tr.diyanet', 43, 4, 'Şüphesiz o, Bizim katımızda Ana Kitap\'ta mevcut, yüce ve hikmet dolu bir Kitap\'dır.'),
  ('tr.diyanet', 43, 5, 'Ey inkarcılar! Aşırı giden kimselersiniz diye sizi Kuran\'la uyarmaktan vaz mı geçelim?'),
  ('tr.diyanet', 43, 6, 'Öncekilere nice peygamberler göndermişizdir.'),
  ('tr.diyanet', 43, 7, 'Kendilerine gelen her peygamberi onlar mutlaka alaya alırlardı.'),
  ('tr.diyanet', 43, 8, 'Bunun için Biz de, bunlardan daha kuvvetli olanları yok etmişizdir. Öncekilere dair nice misaller geçmiştir.'),
  ('tr.diyanet', 43, 9, 'And olsun ki onlara: "Gökleri ve yeri kim yarattı?" diye sorsan, "Onları güçlü olan, her şeyi bilen yaratmıştır" derler.'),
  ('tr.diyanet', 43, 10, 'O, size yeri beşik kılmış ve orada, doğru gidesiniz diye yollar var etmiştir.'),
  ('tr.diyanet', 43, 11, 'O, suyu gökten bir ölçüye göre indirir. Biz onunla ölü memleketi diriltiriz. İşte siz de böyle diriltileceksiniz.'),
  ('tr.diyanet', 43, 12, 'Her sınıf varlığı yaratan O\'dur. Gemiler ve hayvanlardan binesiniz diye size binekler var etmiştir. Bütün bunlar; üzerlerine oturunca Rabbinizin nimetini anarak: "Bunları buyruğumuza veren ne yücedir; zaten bizim takatimiz bunlara yetmezdi; şüphesiz Rabbimize döneceğiz" demeniz içindir.'),
  ('tr.diyanet', 43, 13, 'Her sınıf varlığı yaratan O\'dur. Gemiler ve hayvanlardan binesiniz diye size binekler var etmiştir. Bütün bunlar; üzerlerine oturunca Rabbinizin nimetini anarak: "Bunları buyruğumuza veren ne yücedir; zaten bizim takatimiz bunlara yetmezdi; şüphesiz Rabbimize döneceğiz" demeniz içindir.'),
  ('tr.diyanet', 43, 14, 'Her sınıf varlığı yaratan O\'dur. Gemiler ve hayvanlardan binesiniz diye size binekler var etmiştir. Bütün bunlar; üzerlerine oturunca Rabbinizin nimetini anarak: "Bunları buyruğumuza veren ne yücedir; zaten bizim takatimiz bunlara yetmezdi; şüphesiz Rabbimize döneceğiz" demeniz içindir.'),
  ('tr.diyanet', 43, 15, 'Ama inkarcılar O\'na çocuk isnat ettiler. İnsan gerçekten apaçık nankördür.'),
  ('tr.diyanet', 43, 16, 'Demek O yarattıkları arasından kızları kendisine alıp da oğulları size verdi öyle mi?'),
  ('tr.diyanet', 43, 17, 'Ama Rahman olan Allah\'a isnat ettiği kız evlat kendilerinden birine müjdelenince, o kimsenin içi gayzla dolarak yüzü simsiyah kesilir.'),
  ('tr.diyanet', 43, 18, 'Demek, süs içinde yetiştirilecek de çekişmeyi beceremeyecek olanı Allah\'a değil mi?'),
  ('tr.diyanet', 43, 19, 'Onlar, Rahman olan Allah\'ın kulları melekleri de dişi saydılar. Yaratılışlarını mı görmüşler? Onların bu şahidlikleri yazılacak ve sorguya çekileceklerdir.'),
  ('tr.diyanet', 43, 20, '"Eğer Rahman dilemiş olsaydı, biz bunlara kulluk etmezdik" derler. Buna dair bir bilgileri yoktur; onlar sadece vehimde bulunuyorlar.'),
  ('tr.diyanet', 43, 21, 'Yoksa onlara daha önce bir kitap verdik de ona mı bağlanıyorlar?'),
  ('tr.diyanet', 43, 22, 'Hayır; "Doğrusu Biz babalarımızı bir din üzerinde bulduk, biz de onların izlerinden gitmekteyiz" derler.'),
  ('tr.diyanet', 43, 23, 'Senden önce, herhangi bir şehre gönderdiğimiz uyarıcıya, şımarık varlıklıları sadece: "Doğrusu babalarımızı bir din üzerinde bulduk, biz de onların izlerini izlemekteyiz" dediler.'),
  ('tr.diyanet', 43, 24, 'Gönderilen uyarıcı: "Eğer size, babalarınızı üzerinde bulduğunuz dinden daha doğrusunu getirmiş isem de mi bana uymazsınız?" dedi. Onlar: "Doğrusu sizinle gönderilen şeyi inkar ediyoruz" dediler.'),
  ('tr.diyanet', 43, 25, 'Bunun üzerine Biz de onlardan öç aldık. Yalancıların sonunun nasıl olduğuna bir bak!'),
  ('tr.diyanet', 43, 26, 'İbrahim, babasına ve milletine demişti ki: "Beni yaratan hariç, sizin taptığınız şeylerden uzağım. Beni doğru yola eriştirecek olan şüphesiz O\'dur."'),
  ('tr.diyanet', 43, 27, 'İbrahim, babasına ve milletine demişti ki: "Beni yaratan hariç, sizin taptığınız şeylerden uzağım. Beni doğru yola eriştirecek olan şüphesiz O\'dur."'),
  ('tr.diyanet', 43, 28, 'İbrahim ardından geleceklere bu sözü, devamlı kalacak bir miras olarak bıraktı. Artık belki doğru yola dönerler.'),
  ('tr.diyanet', 43, 29, 'Hayır; Ben bunları ve babalarını gerçek ve onu açıklayan bir peygamber gelene kadar geçindirdim.'),
  ('tr.diyanet', 43, 30, 'Gerçek kendilerine geldiği zaman: "Bu bir büyüdür. Doğrusu biz onu inkar ediyoruz" dediler.'),
  ('tr.diyanet', 43, 31, '"Bu Kuran, iki şehrin birinden bir büyük adama indirilmeli değil miydi?" dediler.'),
  ('tr.diyanet', 43, 32, 'Rabbinin rahmetini onlar mı taksim edip paylaştırıyorlar? Dünya hayatında onların geçimliklerini aralarında Biz taksim ettik; birbirlerine iş gördürmeleri için kimini kimine derecelerle üstün kıldık; Rabbinin rahmeti, onların biriktirdikleri şeylerden daha iyidir.'),
  ('tr.diyanet', 43, 33, 'Eğer bütün insanlar tek ümmet olma durumuna gelmeyecek olsaydı, Rahman olan Allah\'ı inkar edenlerin evlerinin tavanlarını, üzerinde yükseldikleri merdivenleri, evlerinin kapılarını, üzerine yaslanacakları kerevetleri gümüşten yapar ve altın bezeklerle işlerdik. Bunların hepsi ancak dünya hayatının geçimliğidir. Ahiret, Rabbinin katında O\'na karşı gelmekten sakınanlaradır.'),
  ('tr.diyanet', 43, 34, 'Eğer bütün insanlar tek ümmet olma durumuna gelmeyecek olsaydı, Rahman olan Allah\'ı inkar edenlerin evlerinin tavanlarını, üzerinde yükseldikleri merdivenleri, evlerinin kapılarını, üzerine yaslanacakları kerevetleri gümüşten yapar ve altın bezeklerle işlerdik. Bunların hepsi ancak dünya hayatının geçimliğidir. Ahiret, Rabbinin katında O\'na karşı gelmekten sakınanlaradır.'),
  ('tr.diyanet', 43, 35, 'Eğer bütün insanlar tek ümmet olma durumuna gelmeyecek olsaydı, Rahman olan Allah\'ı inkar edenlerin evlerinin tavanlarını, üzerinde yükseldikleri merdivenleri, evlerinin kapılarını, üzerine yaslanacakları kerevetleri gümüşten yapar ve altın bezeklerle işlerdik. Bunların hepsi ancak dünya hayatının geçimliğidir. Ahiret, Rabbinin katında O\'na karşı gelmekten sakınanlaradır.'),
  ('tr.diyanet', 43, 36, 'Rahman olan Allah\'ı anmayı görmezlikten gelene, yanından ayrılmayacak bir şeytanı arkadaş veririz.'),
  ('tr.diyanet', 43, 37, 'Şüphesiz onlar bunları yoldan alıkorlar, bunlar da doğru yola eriştiklerini sanırlar.'),
  ('tr.diyanet', 43, 38, 'Sonunda Bize gelince arkadaşına: "Keşke benimle senin aranda doğu ile batı arasındaki kadar uzaklık olsaydı, sen ne kötü arkadaş imişsin!" der. Nedametin bugün size hiç faydası dokunmaz; zira haksızlık etmiştiniz, şimdi azabda ortaksınız.'),
  ('tr.diyanet', 43, 39, 'Sonunda Bize gelince arkadaşına: "Keşke benimle senin aranda doğu ile batı arasındaki kadar uzaklık olsaydı, sen ne kötü arkadaş imişsin!" der. Nedametin bugün size hiç faydası dokunmaz; zira haksızlık etmiştiniz, şimdi azabda ortaksınız.'),
  ('tr.diyanet', 43, 40, 'Sağırlara sen mi duyuracaksın? Yoksa körleri ve apaçık sapıklıkta olanları doğru yola sen mi eriştireceksin?'),
  ('tr.diyanet', 43, 41, 'Seni onlardan uzaklaştırsak bile doğrusu Biz kendilerinden öç alırız; yahut onlara vadettiğimizi sana gösteririz. Çünkü onlara karşı gücü yetenleriz.'),
  ('tr.diyanet', 43, 42, 'Seni onlardan uzaklaştırsak bile doğrusu Biz kendilerinden öç alırız; yahut onlara vadettiğimizi sana gösteririz. Çünkü onlara karşı gücü yetenleriz.'),
  ('tr.diyanet', 43, 43, 'Sana vahyolunana sarıl, sen, şüphesiz doğru yol üzerindesin.'),
  ('tr.diyanet', 43, 44, 'Doğrusu bu Kuran sana ve ümmetine bir öğüttür, ondan sorumlu tutulacaksınız.'),
  ('tr.diyanet', 43, 45, 'Senden önce gönderdiğimiz elçilerimizden sor; Biz, Rahman olan Allah\'tan başka, kulluk edilecek tanrılar meşru kılmış mıyız?'),
  ('tr.diyanet', 43, 46, 'And olsun ki Biz Musa\'yı mucizelerimizle Firavun\'a ve erkanına göndermiştik, "Şüphesiz ben, Alemlerin Rabbinin elçisiyim" demişti.'),
  ('tr.diyanet', 43, 47, 'Onlara mucizelerimizi getirdiği zaman, bunlara gülüvermişlerdi.'),
  ('tr.diyanet', 43, 48, 'Onlara gösterdiğimiz her mucize diğerinden daha büyüktü; doğru yola dönmeleri için onları azaba uğrattık.'),
  ('tr.diyanet', 43, 49, '"Ey Sihirbaz! Sana verdiği ahde göre Rabbine bizim için yalvar da doğru yola erişelim" dediler.'),
  ('tr.diyanet', 43, 50, 'Ama, azabı üzerlerinden kaldırdığımızda hemen sözlerinden döndüler.'),
  ('tr.diyanet', 43, 51, 'Firavun, milletine şöyle seslendi: "Ey milletim! Mısır hükümdarlığı ve memleketimde akan bu ırmaklar benim değil mi? Görmüyor musunuz?"'),
  ('tr.diyanet', 43, 52, '"Yahut, ben zavallı ve nerdeyse konuşamayan bu kimseden daha üstün değil miyim?"'),
  ('tr.diyanet', 43, 53, '"Ona altın bilezikler verilmeli veya yanında ona yardım edecek melekler gelmeli değil mi?"'),
  ('tr.diyanet', 43, 54, 'Firavun, milletini küçümsedi ama, onlar kendisine yine de itaat ettiler. Doğrusu onlar yoldan çıkmış bir milletti.'),
  ('tr.diyanet', 43, 55, 'Böylece Bizi öfkelendirince onlardan öç aldık, hepsini suda boğduk.'),
  ('tr.diyanet', 43, 56, 'Onları, sonradan gelecek inkarcılara ibret alınacak bir geçmiş kıldık.'),
  ('tr.diyanet', 43, 57, 'Meryem oğlu misal verilince, senin milletin buna gülüp geçiverdi.'),
  ('tr.diyanet', 43, 58, '"Bizim tanrımız mı yoksa o mu daha iyidir?" dediler. Sana böyle söylemeleri, sadece, tartışmaya girişmek içindir. Onlar şüphesiz kavgacı bir millettir.'),
  ('tr.diyanet', 43, 59, 'Meryemoğlu, ancak kendisine nimet verdiğimiz ve İsrailoğullarına örnek kıldığımız bir kuldur.'),
  ('tr.diyanet', 43, 60, 'Eğer dileseydik, size bedel yeryüzünde sizin yerinizi tutacak melekler var ederdik.'),
  ('tr.diyanet', 43, 61, 'O kıyametin kopacağını bildirir; o saatin geleceğinden şüphe etmeyin, Bana uyun, bu doğru yoldur.'),
  ('tr.diyanet', 43, 62, 'Sakın şeytan sizi bu yoldan alıkoymasın; şüphesiz o size apaçık bir düşmandır.'),
  ('tr.diyanet', 43, 63, 'İsa, belgeleri getirdiği zaman demişti ki: "Size hikmetle ve ayrılığa düştüğünüz şeylerin bir kısmını açıklamak üzere geldim. Allah\'a karşı gelmekten sakının, bana itaat edin."'),
  ('tr.diyanet', 43, 64, '"Doğrusu Allah benim de Rabbimdir, sizin de Rabbinizdir, artık O\'na kulluk edin, bu, doğru yoldur."'),
  ('tr.diyanet', 43, 65, 'Ama, aralarında guruplaştılar, ayrılığa düştüler. Kıyamet gününün can yakıcı azabına uğrayacak zalimlerin vay haline!'),
  ('tr.diyanet', 43, 66, 'Onlar farkında değillerken kıyamet gününün kendilerine ansızın gelmesini mi bekliyorlar?'),
  ('tr.diyanet', 43, 67, 'O gün Allah\'a karşı gelmekten sakınanlar dışında, dost olanlar birbirine düşman olurlar.'),
  ('tr.diyanet', 43, 68, 'Allah: "Ey kullarım! Bugün size korku yoktur, siz üzülmeyeceksiniz" der.'),
  ('tr.diyanet', 43, 69, 'Bunlar, ayetlerimize inanmış ve kendilerini Bize vermişlerdir.'),
  ('tr.diyanet', 43, 70, 'Şöyle denir: "Siz ve eşleriniz, ağırlanmış olarak cennete giriniz."'),
  ('tr.diyanet', 43, 71, 'Onlar için altın kadeh ve tepsiler dolaştırılır, canlarının istediği ve gözlerinin hoşlandığı her şey oradadır. Siz orada ebedi kalacaksınız.'),
  ('tr.diyanet', 43, 72, 'İşlediklerinize karşılık, size miras verilen işte bu cennettir.'),
  ('tr.diyanet', 43, 73, 'Orada sizin için bol yemiş vardır, onlardan yersiniz.'),
  ('tr.diyanet', 43, 74, 'Doğrusu suçlular, temelli kalacakları cehennemin azabı içindedirler.'),
  ('tr.diyanet', 43, 75, 'Azaba hiç ara verilmez, onlar orada tamamen umutsuzdurlar.'),
  ('tr.diyanet', 43, 76, 'Biz onlara zulmetmedik, ama onlar zalim kimselerdi.'),
  ('tr.diyanet', 43, 77, 'Cehennemde şöyle seslenilir: "Ey Nöbetçi! Rabbin hiç değilse canımızı alsın." Nöbetçi: "Siz böyle kalacaksınız" der.'),
  ('tr.diyanet', 43, 78, 'And olsun ki, size gerçeği getirdik; fakat çoğunuz gerçeği sevmiyorsunuz.'),
  ('tr.diyanet', 43, 79, 'Yoksa bir işe mi karar verdiler? Doğrusu Biz de kararlıyız.'),
  ('tr.diyanet', 43, 80, 'Yoksa, kendilerinin gizli veya açık konuşmalarını duymayız mı sanırlar? Hayır; öyle değil; yanlarındaki elçilerimiz yazmaktadır.'),
  ('tr.diyanet', 43, 81, 'De ki: "Eğer Rahman olan Allah\'ın çocuğu olsa, kulluk edenlerin ilki ben olurdum."'),
  ('tr.diyanet', 43, 82, 'Göklerin ve yerin Rabbi, Arşın Rabbi onların vasıflandırmalarından münezzehtir.'),
  ('tr.diyanet', 43, 83, 'Bırak onları, kendilerine söz verilen güne kavuşana kadar, dalsınlar, oynasınlar.'),
  ('tr.diyanet', 43, 84, 'Gökte de Tanrı, yerde de Tanrı O\'dur. Hakim olan, her şeyi bilen O\'dur.'),
  ('tr.diyanet', 43, 85, 'Göklerin, yerin ve ikisi arasında bulunanların hükümranlığı kendisinin olan Allah ne yücedir! Kıyamet saatini bilmek O\'na aittir. O\'na döneceksiniz.'),
  ('tr.diyanet', 43, 86, 'Allah\'ı bırakıp yalvardıkları şeyler, şefaat edemezler. Ancak hakkı bilip ona şahidlik edenler bunun dışındadır.'),
  ('tr.diyanet', 43, 87, 'And olsun ki, onlara kendilerini kimin yarattığını sorsan: "Allah" derler. Öyleyken nasıl da aldatılıp döndürülüyorlar?'),
  ('tr.diyanet', 43, 88, 'Onlar hakkında: "Ey Rabbim! Bunlar inanmayan bir millettir" demesi üzerine Allah: "Onlardan geç, esenlik dile; yakında bileceklerdir" buyurdu.'),
  ('tr.diyanet', 43, 89, 'Onlar hakkında: "Ey Rabbim! Bunlar inanmayan bir millettir" demesi üzerine Allah: "Onlardan geç, esenlik dile; yakında bileceklerdir" buyurdu.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 43, 1, 'Haa Miim.'),
  ('id.indonesian', 43, 2, 'Demi Kitab (Al Quran) yang menerangkan.'),
  ('id.indonesian', 43, 3, 'Sesungguhnya Kami menjadikan Al Quran dalam bahasa Arab supaya kamu memahami(nya).'),
  ('id.indonesian', 43, 4, 'Dan sesungguhnya Al Quran itu dalam induk Al Kitab (Lauh Mahfuzh) di sisi Kami, adalah benar-benar tinggi (nilainya) dan amat banyak mengandung hikmah.'),
  ('id.indonesian', 43, 5, 'Maka apakah Kami akan berhenti menurunkan Al Quran kepadamu, karena kamu adalah kaum yang melampaui batas?'),
  ('id.indonesian', 43, 6, 'Berapa banyaknya nabi-nabi yang telah Kami utus kepada umat-umat yang terdahulu.'),
  ('id.indonesian', 43, 7, 'Dan tiada seorang nabipun datang kepada mereka melainkan mereka selalu memperolok-olokkannya.'),
  ('id.indonesian', 43, 8, 'Maka telah Kami binasakan orang-orang yang lebih besar kekuatannya dari mereka itu (musyrikin Mekah) dan telah terdahulu (tersebut dalam Al Quran) perumpamaan umat-umat masa dahulu.'),
  ('id.indonesian', 43, 9, 'Dan sungguh jika kamu tanyakan kepada mereka: "Siapakah yang menciptakan langit dan bumi?", niscaya mereka akan menjawab: "Semuanya diciptakan oleh Yang Maha Perkasa lagi Maha Mengetahui".'),
  ('id.indonesian', 43, 10, 'Yang menjadikan bumi untuk kamu sebagai tempat menetap dan Dia membuat jalan-jalan di atas bumi untuk kamu supaya kamu mendapat petunjuk.'),
  ('id.indonesian', 43, 11, 'Dan Yang menurunkan air dari langit menurut kadar (yang diperlukan) lalu Kami hidupkan dengan air itu negeri yang mati, seperti itulah kamu akan dikeluarkan (dari dalam kubur).'),
  ('id.indonesian', 43, 12, 'Dan Yang menciptakan semua yang berpasang-pasangan dan menjadikan untukmu kapal dan binatang ternak yang kamu tunggangi.'),
  ('id.indonesian', 43, 13, 'Supaya kamu duduk di atas punggungnya kemudian kamu ingat nikmat Tuhanmu apabila kamu telah duduk di atasnya; dan supaya kamu mengucapkan: "Maha Suci Tuhan yang telah menundukkan semua ini bagi kami padahal kami sebelumnya tidak mampu menguasainya,'),
  ('id.indonesian', 43, 14, 'dan sesungguhnya kami akan kembali kepada Tuhan kami".'),
  ('id.indonesian', 43, 15, 'Dan mereka menjadikan sebahagian dari hamba-hamba-Nya sebagai bahagian daripada-Nya. Sesungguhnya manusia itu benar-benar pengingkar yang nyata (terhadap rahmat Allah).'),
  ('id.indonesian', 43, 16, 'Patutkah Dia mengambil anak perempuan dari yang diciptakan-Nya dan Dia mengkhususkan buat kamu anak laki-laki.'),
  ('id.indonesian', 43, 17, 'Padahal apabila salah seorang di antara mereka diberi kabar gembira dengan apa yang dijadikan sebagai misal bagi Allah Yang Maha Pemurah; jadilah mukanya hitam pekat sedang dia amat menahan sedih.'),
  ('id.indonesian', 43, 18, 'Dan apakah patut (menjadi anak Allah) orang yang dibesarkan dalam keadaan berperhiasan sedang dia tidak dapat memberi alasan yang terang dalam pertengkaran.'),
  ('id.indonesian', 43, 19, 'Dan mereka menjadikan malaikat-malaikat yang mereka itu adalah hamba-hamba Allah Yang Maha Pemurah sebagai orang-orang perempuan. Apakah mereka menyaksikan penciptaan malaika-malaikat itu? Kelak akan dituliskan persaksian mereka dan mereka akan dimintai pertanggung-jawaban.'),
  ('id.indonesian', 43, 20, 'Dan mereka berkata: "Jikalau Allah Yang Maha Pemurah menghendaki tentulah kami tidak menyembah mereka (malaikat)". Mereka tidak mempunyai pengetahuan sedikitpun tentang itu, mereka tidak lain hanyalah menduga-duga belaka.'),
  ('id.indonesian', 43, 21, 'Atau adakah Kami memberikan sebuah kitab kepada mereka sebelum Al Quran, lalu mereka berpegang dengan kitab itu?'),
  ('id.indonesian', 43, 22, 'Bahkan mereka berkata: "Sesungguhnya kami mendapati bapak-bapak kami menganut suatu agama, dan sesungguhnya kami orang-orang yang mendapat petunjuk dengan (mengikuti) jejak mereka".'),
  ('id.indonesian', 43, 23, 'Dan demikianlah, Kami tidak mengutus sebelum kamu seorang pemberi peringatanpun dalam suatu negeri, melainkan orang-orang yang hidup mewah di negeri itu berkata: "Sesungguhnya kami mendapati bapak-bapak kami menganut suatu agama dan sesungguhnya kami adalah pengikut jejak-jejak mereka".'),
  ('id.indonesian', 43, 24, '(Rasul itu) berkata: "Apakah (kamu akan mengikutinya juga) sekalipun aku membawa untukmu (agama) yang lebih (nyata) memberi petunjuk daripada apa yang kamu dapati bapak-bapakmu menganutnya?" Mereka menjawab: "Sesungguhnya kami mengingkari agama yang kamu diutus untuk menyampaikannya".'),
  ('id.indonesian', 43, 25, 'Maka Kami binasakan mereka maka perhatikanlah bagaimana kesudahan orang-orang yang mendustakan itu.'),
  ('id.indonesian', 43, 26, 'Dan ingatlah ketika Ibrahim berkata kepada bapaknya dan kaumnya: "Sesungguhnya aku tidak bertanggung jawab terhadap apa yang kamu sembah,'),
  ('id.indonesian', 43, 27, 'tetapi (aku menyembah) Tuhan Yang menjadikanku; karena sesungguhnya Dia akan memberi hidayah kepadaku".'),
  ('id.indonesian', 43, 28, 'Dan (lbrahim a. s.) menjadikan kalimat tauhid itu kalimat yang kekal pada keturunannya supaya mereka kembali kepada kalimat tauhid itu.'),
  ('id.indonesian', 43, 29, 'Tetapi Aku telah memberikan kenikmatan hidup kepada mereka dan bapak-bapak mereka sehingga datanglah kepada mereka kebenaran (Al Quran) dan seorang rasul yang memberi penjelasan.'),
  ('id.indonesian', 43, 30, 'Dan tatkala kebenaran (Al Quran) itu datang kepada mereka, mereka berkata: "Ini adalah sihir dan sesungguhnya kami adalah orang-orang yang mengingkarinya".'),
  ('id.indonesian', 43, 31, 'Dan mereka berkata: "Mengapa Al Quran ini tidak diturunkan kepada seorang besar dari salah satu dua negeri (Mekah dan Thaif) ini?"'),
  ('id.indonesian', 43, 32, 'Apakah mereka yang membagi-bagi rahmat Tuhanmu? Kami telah menentukan antara mereka penghidupan mereka dalam kehidupan dunia, dan kami telah meninggikan sebahagian mereka atas sebagian yang lain beberapa derajat, agar sebagian mereka dapat mempergunakan sebagian yang lain. Dan rahmat Tuhanmu lebih baik dari apa yang mereka kumpulkan.'),
  ('id.indonesian', 43, 33, 'Dan sekiranya bukan karena hendak menghindari manusia menjadi umat yang satu (dalam kekafiran), tentulah kami buatkan bagi orang-orang yang kafir kepada Tuhan Yang Maha Pemurah loteng-loteng perak bagi rumah mereka dan (juga) tangga-tangga (perak) yang mereka menaikinya.'),
  ('id.indonesian', 43, 34, 'Dan (Kami buatkan pula) pintu-pintu (perak) bagi rumah-rumah mereka dan (begitu pula) dipan-dipan yang mereka bertelekan atasnya.'),
  ('id.indonesian', 43, 35, 'Dan (Kami buatkan pula) perhiasan-perhiasan (dari emas untuk mereka). Dan semuanya itu tidak lain hanyalah kesenangan kehidupan dunia, dan kehidupan akhirat itu di sisi Tuhanmu adalah bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 43, 36, 'Barangsiapa yang berpaling dari pengajaran Tuhan Yang Maha Pemurah (Al Quran), kami adakan baginya syaitan (yang menyesatkan) maka syaitan itulah yang menjadi teman yang selalu menyertainya.'),
  ('id.indonesian', 43, 37, 'Dan sesungguhnya syaitan-syaitan itu benar-benar menghalangi mereka dari jalan yang benar dan mereka menyangka bahwa mereka mendapat petunjuk.'),
  ('id.indonesian', 43, 38, 'Sehingga apabila orang-orang yang berpaling itu datang kepada kami (di hari kiamat) dia berkata: "Aduhai, semoga (jarak) antaraku dan kamu seperti jarak antara masyrik dan maghrib, maka syaitan itu adalah sejahat-jahat teman (yang menyertai manusia)".'),
  ('id.indonesian', 43, 39, '(Harapanmu itu) sekali-kali tidak akan memberi manfaat kepadamu di hari itu karena kamu telah menganiaya (dirimu sendiri). Sesungguhnya kamu bersekutu dalam azab itu.'),
  ('id.indonesian', 43, 40, 'Maka apakah kamu dapat menjadikan orang yang pekak bisa mendengar atau (dapatkah) kamu memberi petunjuk kepada orang yang buta (hatinya) dan kepada orang yang tetap dalam kesesatan yang nyata?'),
  ('id.indonesian', 43, 41, 'Sungguh, jika Kami mewafatkan kamu (sebelum kamu mencapai kemenangan) maka sesungguhnya Kami akan menyiksa mereka (di akhirat).'),
  ('id.indonesian', 43, 42, 'Atau Kami memperlihatkan kepadamu (azab) yang telah Kami ancamkan kepada mereka. Maka sesungguhnya Kami berkuasa atas mereka.'),
  ('id.indonesian', 43, 43, 'Maka berpegang teguhlah kamu kepada agama yang telah diwahyukan kepadamu. Sesungguhnya kamu berada di atas jalan yang lurus.'),
  ('id.indonesian', 43, 44, 'Dan sesungguhnya Al Quran itu benar-benar adalah suatu kemuliaan besar bagimu dan bagi kaummu dan kelak kamu akan diminta pertanggungan jawab.'),
  ('id.indonesian', 43, 45, 'Dan tanyakanlah kepada rasul-rasul Kami yang telah Kami utus sebelum kamu: "Adakah Kami menentukan tuhan-tuhan untuk disembah selain Allah Yang Maha Pemurah?"'),
  ('id.indonesian', 43, 46, 'Dan sesunguhnya Kami telah mengutus Musa dengan membawa mukjizat-mukjizat Kami kepada Fir\'aun dan pemuka-pemuka kaumnya. Maka Musa berkata: "Sesungguhnya aku adalah utusan dari Tuhan seru sekalian alam".'),
  ('id.indonesian', 43, 47, 'Maka tatkala dia datang kepada mereka dengan membawa mukjizat-mukjizat Kami dengan serta merta mereka mentertawakannya.'),
  ('id.indonesian', 43, 48, 'Dan tidaklah Kami perlihatkan kepada mereka sesuatu mukjizat kecuali mukjizat itu lebih besar dari mukjizat-mukjizat yang sebelumnya. Dan Kami timpakan kepada mereka azab supaya mereka kembali (ke jalan yang benar).'),
  ('id.indonesian', 43, 49, 'Dan mereka berkata: "Hai ahli sihir, berdoalah kepada Tuhanmu untuk (melepaskan) kami sesuai dengan apa yang telah dijanjikan-Nya kepadamu; sesungguhnya kami (jika doamu dikabulkan) benar-benar akan menjadi orang yang mendapat petunjuk.'),
  ('id.indonesian', 43, 50, 'Maka tatkala Kami hilangkan azab itu dari mereka, dengan serta merta mereka memungkiri (janjinya).'),
  ('id.indonesian', 43, 51, 'Dan Fir\'aun berseru kepada kaumnya (seraya) berkata: "Hai kaumku, bukankah kerajaan Mesir ini kepunyaanku dan (bukankah) sungai-sungai ini mengalir di bawahku; maka apakah kamu tidak melihat(nya)?'),
  ('id.indonesian', 43, 52, 'Bukankah aku lebih baik dari orang yang hina ini dan yang hampir tidak dapat menjelaskan (perkataannya)?'),
  ('id.indonesian', 43, 53, 'Mengapa tidak dipakaikan kepadanya gelang dari emas atau malaikat datang bersama-sama dia untuk mengiringkannya?"'),
  ('id.indonesian', 43, 54, 'Maka Fir\'aun mempengaruhi kaumnya (dengan perkataan itu) lalu mereka patuh kepadanya. Karena sesungguhnya mereka adalah kaum yang fasik.'),
  ('id.indonesian', 43, 55, 'Maka tatkala mereka membuat Kami murka, Kami menghukum mereka lalu kami tenggelamkan mereka semuanya (di laut),'),
  ('id.indonesian', 43, 56, 'dan Kami jadikan mereka sebagai pelajaran dan contoh bagi orang-orang yang kemudian.'),
  ('id.indonesian', 43, 57, 'Dan tatkala putra Maryam (Isa) dijadikan perumpamnaan tiba-tiba kaummu (Quraisy) bersorak karenanya.'),
  ('id.indonesian', 43, 58, 'Dan mereka berkata: "Manakah yang lebih baik tuhan-tuhan kami atau dia (Isa)?" Mereka tidak memberikan perumpamaan itu kepadamu melainkan dengan maksud membantah saja, sebenarnya mereka adalah kaum yang suka bertengkar.'),
  ('id.indonesian', 43, 59, 'Isa tidak lain hanyalah seorang hamba yang Kami berikan kepadanya nikmat (kenabian) dan Kami jadikan dia sebagai tanda bukti (kekuasaan Allah) untuk Bani lsrail'),
  ('id.indonesian', 43, 60, 'Dan kalau Kami kehendaki benar-benar Kami jadikan sebagai gantimu di muka bumi malaikat-malaikat yang turun temurun.'),
  ('id.indonesian', 43, 61, 'Dan sesungguhnya Isa itu benar-benar memberikan pengetahuan tentang hari kiamat. Karena itu janganlah kamu ragu-ragu tentang kiamat itu dan ikutilah Aku. Inilah jalan yang lurus.'),
  ('id.indonesian', 43, 62, 'Dan janganlah kamu sekali-kali dipalingkan oleh syaitan; sesungguhnya syaitan itu musuh yang nyata bagimu.'),
  ('id.indonesian', 43, 63, 'Dan tatkala Isa datang membawa keterangan dia berkata: "Sesungguhnya aku datang kepadamu dengan membawa hikmat dan untuk menjelaskan kepadamu sebagian dari apa yang kamu berselisih tentangnya, maka bertakwalah kepada Allah dan taatlah (kepada)ku".'),
  ('id.indonesian', 43, 64, 'Sesungguhnya Allah Dialah Tuhanku dan Tuhan kamu maka sembahlah Dia, ini adalah jalan yang lurus.'),
  ('id.indonesian', 43, 65, 'Maka berselisihlah golongan-golongan (yang terdapat) di antara mereka, lalu kecelakaan yang besarlah bagi orang-orang yang zalim yakni siksaan hari yang pedih (kiamat).'),
  ('id.indonesian', 43, 66, 'Mereka tidak menunggu kecuali kedatangan hari kiamat kepada mereka dengan tiba-tiba sedang mereka tidak menyadarinya.'),
  ('id.indonesian', 43, 67, 'Teman-teman akrab pada hari itu sebagiannya menjadi musuh bagi sebagian yang lain kecuali orang-orang yang bertakwa.'),
  ('id.indonesian', 43, 68, '"Hai hamba-hamba-Ku, tiada kekhawatiran terhadapmu pada hari ini dan tidak pula kamu bersedih hati.'),
  ('id.indonesian', 43, 69, '(Yaitu) orang-orang yang beriman kepada ayat-ayat Kami dan adalah mereka dahulu orang-orang yang berserah diri.'),
  ('id.indonesian', 43, 70, 'Masuklah kamu ke dalam surga, kamu dan isteri-isteri kamu digembirakan".'),
  ('id.indonesian', 43, 71, 'Diedarkan kepada mereka piring-piring dari emas, dan piala-piala dan di dalam surga itu terdapat segala apa yang diingini oleh hati dan sedap (dipandang) mata dan kamu kekal di dalamnya".'),
  ('id.indonesian', 43, 72, 'Dan itulah surga yang diwariskan kepada kamu disebabkan amal-amal yang dahulu kamu kerjakan.'),
  ('id.indonesian', 43, 73, 'Di dalam surga itu ada buah-buahan yang banyak untukmu yang sebahagiannya kamu makan.'),
  ('id.indonesian', 43, 74, 'Sesungguhnya orang-orang yang berdosa kekal di dalam azab neraka Jahannam.'),
  ('id.indonesian', 43, 75, 'Tidak diringankan azab itu dari mereka dan mereka di dalamnya berputus asa.'),
  ('id.indonesian', 43, 76, 'Dan tidaklah Kami menganiaya mereka tetapi merekalah yang menganiaya diri mereka sendiri.'),
  ('id.indonesian', 43, 77, 'Mereka berseru: "Hai Malik biarlah Tuhanmu membunuh kami saja". Dia menjawab: "Kamu akan tetap tinggal (di neraka ini)".'),
  ('id.indonesian', 43, 78, 'Sesungguhnya Kami benar-benar telah memhawa kebenaran kepada kamu tetapi kebanyakan di antara kamu benci pada kebenaran itu.'),
  ('id.indonesian', 43, 79, 'Bahkan mereka telah menetapkan satu tipu daya (jahat), maka sesungguhnya Kami menetapkan pula.'),
  ('id.indonesian', 43, 80, 'Apakah mereka mengira, bahwa Kami tidak mendengar rahasia dan bisikan-bisikan mereka? Sebenarnya (Kami mendengar), dan utusan-utusan (malaikat-malaikat) Kami selalu mencatat di sisi mereka.'),
  ('id.indonesian', 43, 81, 'Katakanlah, jika benar Tuhan Yang Maha Pemurah mempunyai anak, maka akulah (Muhammad) orang yang mula-mula memuliakan (anak itu).'),
  ('id.indonesian', 43, 82, 'Maha Suci Tuhan Yang empunya langit dan bumi, Tuhan Yang empunya \'Arsy, dari apa yang mereka sifatkan itu.'),
  ('id.indonesian', 43, 83, 'Maka biarlah mereka tenggelam (dalam kesesatan) dan bermain-main sampai mereka menemui hari yang dijanjikan kepada mereka.'),
  ('id.indonesian', 43, 84, 'Dan Dialah Tuhan (Yang disembah) di langit dan Tuhan (Yang disembah) di bumi dan Dialah Yang Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 43, 85, 'Dan Maha Suci Tuhan Yang mempunyai kerajaan langit dan bumi; dan apa yang ada di antara keduanya; dan di sisi-Nya-lah pengetahuan tentang hari kiamat dan hanya kepada-Nya-lah kamu dikembalikan.'),
  ('id.indonesian', 43, 86, 'Dan sembahan-sembahan yang mereka sembah selain Allah tidak dapat memberi syafa\'at; akan tetapi (orang yang dapat memberi syafa\'at ialah) orang yang mengakui yang hak (tauhid) dan mereka meyakini(nya).'),
  ('id.indonesian', 43, 87, 'Dan sungguh jika kamu bertanya kepada mereka: "Siapakah yang menciptakan mereka, niscaya mereka menjawab: "Allah", maka bagaimanakah mereka dapat dipalingkan (dari menyembah Allah)?,'),
  ('id.indonesian', 43, 88, 'dan (Allah mengetabui) ucapan Muhammad: "Ya Tuhanku, sesungguhnya mereka itu adalah kaum yang tidak beriman".'),
  ('id.indonesian', 43, 89, 'Maka berpalinglah (hai Muhammad) dari mereka dan katakanlah: "Salam (selamat tinggal)". Kelak mereka akan mengetahui (nasib mereka yang buruk).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 44, 1, 'Ha, Meem.'),
  ('en.sahih', 44, 2, 'By the clear Book,'),
  ('en.sahih', 44, 3, 'Indeed, We sent it down during a blessed night. Indeed, We were to warn [mankind].'),
  ('en.sahih', 44, 4, 'On that night is made distinct every precise matter -'),
  ('en.sahih', 44, 5, '[Every] matter [proceeding] from Us. Indeed, We were to send [a messenger]'),
  ('en.sahih', 44, 6, 'As mercy from your Lord. Indeed, He is the Hearing, the Knowing.'),
  ('en.sahih', 44, 7, 'Lord of the heavens and the earth and that between them, if you would be certain.'),
  ('en.sahih', 44, 8, 'There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers.'),
  ('en.sahih', 44, 9, 'But they are in doubt, amusing themselves.'),
  ('en.sahih', 44, 10, 'Then watch for the Day when the sky will bring a visible smoke.'),
  ('en.sahih', 44, 11, 'Covering the people; this is a painful torment.'),
  ('en.sahih', 44, 12, '[They will say], "Our Lord, remove from us the torment; indeed, we are believers."'),
  ('en.sahih', 44, 13, 'How will there be for them a reminder [at that time]? And there had come to them a clear Messenger.'),
  ('en.sahih', 44, 14, 'Then they turned away from him and said, "[He was] taught [and is] a madman."'),
  ('en.sahih', 44, 15, 'Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief].'),
  ('en.sahih', 44, 16, 'The Day We will strike with the greatest assault, indeed, We will take retribution.'),
  ('en.sahih', 44, 17, 'And We had already tried before them the people of Pharaoh, and there came to them a noble messenger,'),
  ('en.sahih', 44, 18, '[Saying], "Render to me the servants of Allah. Indeed, I am to you a trustworthy messenger,"'),
  ('en.sahih', 44, 19, 'And [saying], "Be not haughty with Allah. Indeed, I have come to you with clear authority.'),
  ('en.sahih', 44, 20, 'And indeed, I have sought refuge in my Lord and your Lord, lest you stone me.'),
  ('en.sahih', 44, 21, 'But if you do not believe me, then leave me alone."'),
  ('en.sahih', 44, 22, 'And [finally] he called to his Lord that these were a criminal people.'),
  ('en.sahih', 44, 23, '[Allah said], "Then set out with My servants by night. Indeed, you are to be pursued.'),
  ('en.sahih', 44, 24, 'And leave the sea in stillness. Indeed, they are an army to be drowned."'),
  ('en.sahih', 44, 25, 'How much they left behind of gardens and springs'),
  ('en.sahih', 44, 26, 'And crops and noble sites'),
  ('en.sahih', 44, 27, 'And comfort wherein they were amused.'),
  ('en.sahih', 44, 28, 'Thus. And We caused to inherit it another people.'),
  ('en.sahih', 44, 29, 'And the heaven and earth wept not for them, nor were they reprieved.'),
  ('en.sahih', 44, 30, 'And We certainly saved the Children of Israel from the humiliating torment -'),
  ('en.sahih', 44, 31, 'From Pharaoh. Indeed, he was a haughty one among the transgressors.'),
  ('en.sahih', 44, 32, 'And We certainly chose them by knowledge over [all] the worlds.'),
  ('en.sahih', 44, 33, 'And We gave them of signs that in which there was a clear trial.'),
  ('en.sahih', 44, 34, 'Indeed, these [disbelievers] are saying,'),
  ('en.sahih', 44, 35, '"There is not but our first death, and we will not be resurrected.'),
  ('en.sahih', 44, 36, 'Then bring [back] our forefathers, if you should be truthful."'),
  ('en.sahih', 44, 37, 'Are they better or the people of Tubba\' and those before them? We destroyed them, [for] indeed, they were criminals.'),
  ('en.sahih', 44, 38, 'And We did not create the heavens and earth and that between them in play.'),
  ('en.sahih', 44, 39, 'We did not create them except in truth, but most of them do not know.'),
  ('en.sahih', 44, 40, 'Indeed, the Day of Judgement is the appointed time for them all -'),
  ('en.sahih', 44, 41, 'The Day when no relation will avail a relation at all, nor will they be helped -'),
  ('en.sahih', 44, 42, 'Except those [believers] on whom Allah has mercy. Indeed, He is the Exalted in Might, the Merciful.'),
  ('en.sahih', 44, 43, 'Indeed, the tree of zaqqum'),
  ('en.sahih', 44, 44, 'Is food for the sinful.'),
  ('en.sahih', 44, 45, 'Like murky oil, it boils within bellies'),
  ('en.sahih', 44, 46, 'Like the boiling of scalding water.'),
  ('en.sahih', 44, 47, '[It will be commanded], "Seize him and drag him into the midst of the Hellfire,'),
  ('en.sahih', 44, 48, 'Then pour over his head from the torment of scalding water."'),
  ('en.sahih', 44, 49, '[It will be said], "Taste! Indeed, you are the honored, the noble!'),
  ('en.sahih', 44, 50, 'Indeed, this is what you used to dispute."'),
  ('en.sahih', 44, 51, 'Indeed, the righteous will be in a secure place;'),
  ('en.sahih', 44, 52, 'Within gardens and springs,'),
  ('en.sahih', 44, 53, 'Wearing [garments of] fine silk and brocade, facing each other.'),
  ('en.sahih', 44, 54, 'Thus. And We will marry them to fair women with large, [beautiful] eyes.'),
  ('en.sahih', 44, 55, 'They will call therein for every [kind of] fruit - safe and secure.'),
  ('en.sahih', 44, 56, 'They will not taste death therein except the first death, and He will have protected them from the punishment of Hellfire'),
  ('en.sahih', 44, 57, 'As bounty from your Lord. That is what is the great attainment.'),
  ('en.sahih', 44, 58, 'And indeed, We have eased the Qur\'an in your tongue that they might be reminded.'),
  ('en.sahih', 44, 59, 'So watch, [O Muhammad]; indeed, they are watching [for your end].')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 44, 1, 'হা-মীম।'),
  ('bn.bengali', 44, 2, 'শপথ সুস্পষ্ট কিতাবের।'),
  ('bn.bengali', 44, 3, 'আমি একে নাযিল করেছি। এক বরকতময় রাতে, নিশ্চয় আমি সতর্ককারী।'),
  ('bn.bengali', 44, 4, 'এ রাতে প্রত্যেক প্রজ্ঞাপূর্ণ বিষয় স্থিরীকৃত হয়।'),
  ('bn.bengali', 44, 5, 'আমার পক্ষ থেকে আদেশক্রমে, আমিই প্রেরণকারী।'),
  ('bn.bengali', 44, 6, 'আপনার পালনকর্তার পক্ষ থেকে রহমতস্বরূপ। তিনি সর্বশ্রোতা, সর্বজ্ঞ।'),
  ('bn.bengali', 44, 7, 'যদি তোমাদের বিশ্বাস থাকে দেখতে পাবে। তিনি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের মধ্যেবর্তী সবকিছুর পালনকর্তা।'),
  ('bn.bengali', 44, 8, 'তিনি ব্যতীত কোন উপাস্য নেই। তিনি জীবন দান করেন ও মৃত্যু দেন। তিনি তোমাদের পালনকর্তা এবং তোমাদের পূর্ববর্তী পিতৃ-পুরুষদেরও পালনকর্তা।'),
  ('bn.bengali', 44, 9, 'এতদসত্ত্বেও এরা সন্দেহে পতিত হয়ে ক্রীড়া-কৌতুক করছে।'),
  ('bn.bengali', 44, 10, 'অতএব আপনি সেই দিনের অপেক্ষা করুন, যখন আকাশ ধূয়ায় ছেয়ে যাবে।'),
  ('bn.bengali', 44, 11, 'যা মানুষকে ঘিরে ফেলবে। এটা যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 44, 12, 'হে আমাদের পালনকর্তা আমাদের উপর থেকে শাস্তি প্রত্যাহার করুন, আমরা বিশ্বাস স্থাপন করছি।'),
  ('bn.bengali', 44, 13, 'তারা কি করে বুঝবে, অথচ তাদের কাছে এসেছিলেন স্পষ্ট বর্ণনাকারী রসূল।'),
  ('bn.bengali', 44, 14, 'অতঃপর তারা তাকে পৃষ্ঠপ্রদর্শন করে এবং বলে, সে তো উম্মাদ-শিখানো কথা বলে।'),
  ('bn.bengali', 44, 15, 'আমি তোমাদের উপর থেকে আযাব কিছুটা প্রত্যাহার করব, কিন্তু তোমরা পুনরায় পুনর্বস্থায় ফিরে যাবে।'),
  ('bn.bengali', 44, 16, 'যেদিন আমি প্রবলভাবে ধৃত করব, সেদিন পুরোপুরি প্রতিশোধ গ্রহণ করবই।'),
  ('bn.bengali', 44, 17, 'তাদের পূর্বে আমি ফেরাউনের সম্প্রদায়কে পরীক্ষা করেছি এবং তাদের কাছে আগমন করেছেন একজন সম্মানিত রসূল,'),
  ('bn.bengali', 44, 18, 'এই মর্মে যে, আল্লাহর বান্দাদেরকে আমার কাছে অর্পণ কর। আমি তোমাদের জন্য প্রেরীত বিশ্বস্ত রসূল।'),
  ('bn.bengali', 44, 19, 'আর তোমরা আল্লাহর বিরুদ্ধে ঔদ্ধত্য প্রকাশ করো না। আমি তোমাদের কাছে প্রকাশ্য প্রমাণ উপস্থিত করছি।'),
  ('bn.bengali', 44, 20, 'তোমরা যাতে আমাকে প্রস্তরবর্ষণে হত্যা না কর, তজ্জন্যে আমি আমার পালনকর্তা ও তোমাদের পালনকর্তার শরনাপন্ন হয়েছি।'),
  ('bn.bengali', 44, 21, 'তোমরা যদি আমার প্রতি বিশ্বাস স্থাপন না কর, তবে আমার কাছ থেকে দূরে থাক।'),
  ('bn.bengali', 44, 22, 'অতঃপর সে তার পালনকর্তার কাছে দোয়া করল যে, এরা অপরাধী সম্প্রদায়।'),
  ('bn.bengali', 44, 23, 'তাহলে তুমি আমার বান্দাদেরকে নিয়ে রাত্রিবেলায় বের হয়ে পড়। নিশ্চয় তোমাদের পশ্চাদ্ধবন করা হবে।'),
  ('bn.bengali', 44, 24, 'এবং সমুদ্রকে অচল থাকতে দাও। নিশ্চয় ওরা নিমজ্জত বাহিনী।'),
  ('bn.bengali', 44, 25, 'তারা ছেড়ে গিয়েছিল কত উদ্যান ও প্রস্রবন,'),
  ('bn.bengali', 44, 26, 'কত শস্যক্ষেত্র ও সূরম্য স্থান।'),
  ('bn.bengali', 44, 27, 'কত সুখের উপকরণ, যাতে তারা খোশগল্প করত।'),
  ('bn.bengali', 44, 28, 'এমনিই হয়েছিল এবং আমি ওগুলোর মালিক করেছিলাম ভিন্ন সম্প্রদায়কে।'),
  ('bn.bengali', 44, 29, 'তাদের জন্যে ক্রন্দন করেনি আকাশ ও পৃথিবী এবং তারা অবকাশও পায়নি।'),
  ('bn.bengali', 44, 30, 'আমি বনী-ইসরাঈলকে অপমানজনক শাস্তি থেকে উদ্ধার করছি।'),
  ('bn.bengali', 44, 31, 'ফেরাউন সে ছিল সীমালংঘনকারীদের মধ্যে শীর্ষস্থানীয়।'),
  ('bn.bengali', 44, 32, 'আমি জেনেশুনে তাদেরকে বিশ্ববাসীদের উপর শ্রেষ্ঠত্ব দিয়েছিলাম।'),
  ('bn.bengali', 44, 33, 'এবং আমি তাদেরকে এমন নিদর্শনাবলী দিয়েছিলাম যাতে ছিল স্পষ্ট সাহায্য।'),
  ('bn.bengali', 44, 34, 'কাফেররা বলেই থাকে,'),
  ('bn.bengali', 44, 35, 'প্রথম মৃত্যুর মাধ্যমেই আমাদের সবকিছুর অবসান হবে এবং আমরা পুনরুত্থিত হব না।'),
  ('bn.bengali', 44, 36, 'তোমরা যদি সত্যবাদী হও, তবে আমাদের পূর্বপুরুষদেরকে নিয়ে এস।'),
  ('bn.bengali', 44, 37, 'ওরা শ্রেষ্ঠ, না তুব্বার সম্প্রদায় ও তাদের পূর্ববর্তীরা? আমি ওদেরকে ধ্বংস করে দিয়েছি। ওরা ছিল অপরাধী।'),
  ('bn.bengali', 44, 38, 'আমি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের মধ্যবর্তী সবকিছু ক্রীড়াচ্ছলে সৃষ্টি করিনি।'),
  ('bn.bengali', 44, 39, 'আমি এগুলো যথাযথ উদ্দেশ্যে সৃষ্টি করেছি; কিন্তু তাদের অধিকাংশই বোঝে না।'),
  ('bn.bengali', 44, 40, 'নিশ্চয় ফয়সালার দিন তাদের সবারই নির্ধারিত সময়।'),
  ('bn.bengali', 44, 41, 'যেদিন কোন বন্ধুই কোন বন্ধুর উপকারে আসবে না এবং তারা সাহায্যপ্রাপ্তও হবে না।'),
  ('bn.bengali', 44, 42, 'তবে আল্লাহ যার প্রতি দয়া করেন, তার কথা ভিন্ন। নিশ্চয় তিনি পরাক্রমশালী দয়াময়।'),
  ('bn.bengali', 44, 43, 'নিশ্চয় যাক্কুম বৃক্ষ'),
  ('bn.bengali', 44, 44, 'পাপীর খাদ্য হবে;'),
  ('bn.bengali', 44, 45, 'গলিত তাম্রের মত পেটে ফুটতে থাকবে।'),
  ('bn.bengali', 44, 46, 'যেমন ফুটে পানি।'),
  ('bn.bengali', 44, 47, 'একে ধর এবং টেনে নিয়ে যাও জাহান্নামের মধ্যস্থলে,'),
  ('bn.bengali', 44, 48, 'অতঃপর তার মাথার উপর ফুটন্ত পানির আযাব ঢেলে দাও,'),
  ('bn.bengali', 44, 49, 'স্বাদ গ্রহণ কর, তুমি তো সম্মানিত, সম্ভ্রান্ত।'),
  ('bn.bengali', 44, 50, 'এ সম্পর্কে তোমরা সন্দেহে পতিত ছিলে।'),
  ('bn.bengali', 44, 51, 'নিশ্চয় খোদাভীরুরা নিরাপদ স্থানে থাকবে-'),
  ('bn.bengali', 44, 52, 'উদ্যানরাজি ও নির্ঝরিণীসমূহে।'),
  ('bn.bengali', 44, 53, 'তারা পরিধান করবে চিকন ও পুরু রেশমীবস্ত্র, মুখোমুখি হয়ে বসবে।'),
  ('bn.bengali', 44, 54, 'এরূপই হবে এবং আমি তাদেরকে আনতলোচনা স্ত্রী দেব।'),
  ('bn.bengali', 44, 55, 'তারা সেখানে শান্ত মনে বিভিন্ন ফল-মূল আনতে বলবে।'),
  ('bn.bengali', 44, 56, 'তারা সেখানে মৃত্যু আস্বাদন করবে না, প্রথম মৃত্যু ব্যতীত এবং আপনার পালনকর্তা তাদেরকে জাহান্নামের আযাব থেকে রক্ষা করবেন।'),
  ('bn.bengali', 44, 57, 'আপনার পালনকর্তার কৃপায় এটাই মহা সাফল্য।'),
  ('bn.bengali', 44, 58, 'আমি আপনার ভাষায় কোরআনকে সহজ করে দিয়েছি, যাতে তারা স্মরণ রাখে।'),
  ('bn.bengali', 44, 59, 'অতএব, আপনি অপেক্ষা করুন, তারাও অপেক্ষা করছে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 44, 1, 'Ha. Mim.'),
  ('en.pickthall', 44, 2, 'By the Scripture that maketh plain'),
  ('en.pickthall', 44, 3, 'Lo! We revealed it on a blessed night - Lo! We are ever warning -'),
  ('en.pickthall', 44, 4, 'Whereon every wise command is made clear'),
  ('en.pickthall', 44, 5, 'As a command from Our presence - Lo! We are ever sending -'),
  ('en.pickthall', 44, 6, 'A mercy from thy Lord. Lo! He, even He is the Hearer, the Knower,'),
  ('en.pickthall', 44, 7, 'Lord of the heavens and the earth and all that is between them, if ye would be sure.'),
  ('en.pickthall', 44, 8, 'There is no Allah save Him. He quickeneth and giveth death; your Lord and Lord of your forefathers.'),
  ('en.pickthall', 44, 9, 'Nay, but they play in doubt.'),
  ('en.pickthall', 44, 10, 'But watch thou (O Muhammad) for the day when the sky will produce visible smoke'),
  ('en.pickthall', 44, 11, 'That will envelop the people. This will be a painful torment.'),
  ('en.pickthall', 44, 12, '(Then they will say): Our Lord relieve us of the torment. Lo! we are believers.'),
  ('en.pickthall', 44, 13, 'How can there be remembrance for them, when a messenger making plain (the Truth) had already come unto them,'),
  ('en.pickthall', 44, 14, 'And they had turned away from him and said: One taught (by others), a madman?'),
  ('en.pickthall', 44, 15, 'Lo! We withdraw the torment a little. Lo! ye return (to disbelief).'),
  ('en.pickthall', 44, 16, 'On the day when We shall seize them with the greater seizure, (then) in truth We shall punish.'),
  ('en.pickthall', 44, 17, 'And verily We tried before them Pharaoh\'s folk, when there came unto them a noble messenger,'),
  ('en.pickthall', 44, 18, 'Saying: Give up to me the slaves of Allah. Lo! I am a faithful messenger unto you.'),
  ('en.pickthall', 44, 19, 'And saying: Be not proud against Allah. Lo! I bring you a clear warrant.'),
  ('en.pickthall', 44, 20, 'And lo! I have sought refuge in my Lord and your Lord lest ye stone me to death.'),
  ('en.pickthall', 44, 21, 'And if ye put no faith in me, then let me go.'),
  ('en.pickthall', 44, 22, 'And he cried unto his Lord, (saying): These are guilty folk.'),
  ('en.pickthall', 44, 23, 'Then (his Lord commanded): Take away My slaves by night. Lo! ye will be followed,'),
  ('en.pickthall', 44, 24, 'And leave the sea behind at rest, for lo! they are a drowned host.'),
  ('en.pickthall', 44, 25, 'How many were the gardens and the watersprings that they left behind,'),
  ('en.pickthall', 44, 26, 'And the cornlands and the goodly sites'),
  ('en.pickthall', 44, 27, 'And pleasant things wherein they took delight!'),
  ('en.pickthall', 44, 28, 'Even so (it was), and We made it an inheritance for other folk;'),
  ('en.pickthall', 44, 29, 'And the heaven and the earth wept not for them, nor were they reprieved.'),
  ('en.pickthall', 44, 30, 'And We delivered the Children of Israel from the shameful doom;'),
  ('en.pickthall', 44, 31, '(We delivered them) from Pharaoh. Lo! he was a tyrant of the wanton ones.'),
  ('en.pickthall', 44, 32, 'And We chose them, purposely, above (all) creatures.'),
  ('en.pickthall', 44, 33, 'And We gave them portents wherein was a clear trial.'),
  ('en.pickthall', 44, 34, 'Lo! these, forsooth, are saying:'),
  ('en.pickthall', 44, 35, 'There is naught but our first death, and we shall not be raised again.'),
  ('en.pickthall', 44, 36, 'Bring back our fathers, if ye speak the truth!'),
  ('en.pickthall', 44, 37, 'Are they better, or the folk of Tubb\'a and those before them? We destroyed them, for surely they were guilty.'),
  ('en.pickthall', 44, 38, 'And We created not the heavens and the earth, and all that is between them, in play.'),
  ('en.pickthall', 44, 39, 'We created them not save with truth; but most of them know not.'),
  ('en.pickthall', 44, 40, 'Assuredly the Day of Decision is the term for all of them,'),
  ('en.pickthall', 44, 41, 'A day when friend can in naught avail friend, nor can they be helped,'),
  ('en.pickthall', 44, 42, 'Save him on whom Allah hath mercy. Lo! He is the Mighty, the Merciful.'),
  ('en.pickthall', 44, 43, 'Lo! the tree of Zaqqum,'),
  ('en.pickthall', 44, 44, 'The food of the sinner!'),
  ('en.pickthall', 44, 45, 'Like molten brass, it seetheth in their bellies'),
  ('en.pickthall', 44, 46, 'As the seething of boiling water.'),
  ('en.pickthall', 44, 47, '(And it will be said): Take him and drag him to the midst of hell,'),
  ('en.pickthall', 44, 48, 'Then pour upon his head the torment of boiling water.'),
  ('en.pickthall', 44, 49, '(Saying): Taste! Lo! thou wast forsooth the mighty, the noble!'),
  ('en.pickthall', 44, 50, 'Lo! this is that whereof ye used to doubt.'),
  ('en.pickthall', 44, 51, 'Lo! those who kept their duty will be in a place secured.'),
  ('en.pickthall', 44, 52, 'Amid gardens and watersprings,'),
  ('en.pickthall', 44, 53, 'Attired in silk and silk embroidery, facing one another.'),
  ('en.pickthall', 44, 54, 'Even so (it will be). And We shall wed them unto fair ones with wide, lovely eyes.'),
  ('en.pickthall', 44, 55, 'They call therein for every fruit in safety.'),
  ('en.pickthall', 44, 56, 'They taste not death therein, save the first death. And He hath saved them from the doom of hell,'),
  ('en.pickthall', 44, 57, 'A bounty from thy Lord. That is the supreme triumph.'),
  ('en.pickthall', 44, 58, 'And We have made (this Scripture) easy in thy language only that they may heed.'),
  ('en.pickthall', 44, 59, 'Wait then (O Muhammad). Lo! they (too) are waiting.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 44, 1, 'Ha-Mim.'),
  ('en.yusufali', 44, 2, 'By the Book that makes things clear;-'),
  ('en.yusufali', 44, 3, 'We sent it down during a Blessed Night: for We (ever) wish to warn (against Evil).'),
  ('en.yusufali', 44, 4, 'In the (Night) is made distinct every affair of wisdom,'),
  ('en.yusufali', 44, 5, 'By command, from Our Presence. For We (ever) send (revelations),'),
  ('en.yusufali', 44, 6, 'As Mercy from thy Lord: for He hears and knows (all things);'),
  ('en.yusufali', 44, 7, 'The Lord of the heavens and the earth and all between them, if ye (but) have an assured faith.'),
  ('en.yusufali', 44, 8, 'There is no god but He: It is He Who gives life and gives death,- The Lord and Cherisher to you and your earliest ancestors.'),
  ('en.yusufali', 44, 9, 'Yet they play about in doubt.'),
  ('en.yusufali', 44, 10, 'Then watch thou for the Day that the sky will bring forth a kind of smoke (or mist) plainly visible,'),
  ('en.yusufali', 44, 11, 'Enveloping the people: this will be a Penalty Grievous.'),
  ('en.yusufali', 44, 12, '(They will say:) "Our Lord! remove the Penalty from us, for we do really believe!"'),
  ('en.yusufali', 44, 13, 'How shall the message be (effectual) for them, seeing that an Messenger explaining things clearly has (already) come to them,-'),
  ('en.yusufali', 44, 14, 'Yet they turn away from him and say: "Tutored (by others), a man possessed!"'),
  ('en.yusufali', 44, 15, 'We shall indeed remove the Penalty for a while, (but) truly ye will revert (to your ways).'),
  ('en.yusufali', 44, 16, 'One day We shall seize you with a mighty onslaught: We will indeed (then) exact Retribution!'),
  ('en.yusufali', 44, 17, 'We did, before them, try the people of Pharaoh: there came to them a messenger most honourable,'),
  ('en.yusufali', 44, 18, 'Saying: "Restore to me the Servants of Allah: I am to you an messenger worthy of all trust;'),
  ('en.yusufali', 44, 19, '"And be not arrogant as against Allah: for I come to you with authority manifest.'),
  ('en.yusufali', 44, 20, '"For me, I have sought safety with my Lord and your Lord, against your injuring me.'),
  ('en.yusufali', 44, 21, '"If ye believe me not, at least keep yourselves away from me."'),
  ('en.yusufali', 44, 22, '(But they were aggressive:) then he cried to his Lord: "These are indeed a people given to sin."'),
  ('en.yusufali', 44, 23, '(The reply came:) "March forth with My Servants by night: for ye are sure to be pursued.'),
  ('en.yusufali', 44, 24, '"And leave the sea as a furrow (divided): for they are a host (destined) to be drowned."'),
  ('en.yusufali', 44, 25, 'How many were the gardens and springs they left behind,'),
  ('en.yusufali', 44, 26, 'And corn-fields and noble buildings,'),
  ('en.yusufali', 44, 27, 'And wealth (and conveniences of life), wherein they had taken such delight!'),
  ('en.yusufali', 44, 28, 'Thus (was their end)! And We made other people inherit (those things)!'),
  ('en.yusufali', 44, 29, 'And neither heaven nor earth shed a tear over them: nor were they given a respite (again).'),
  ('en.yusufali', 44, 30, 'We did deliver aforetime the Children of Israel from humiliating Punishment,'),
  ('en.yusufali', 44, 31, 'Inflicted by Pharaoh, for he was arrogant (even) among inordinate transgressors.'),
  ('en.yusufali', 44, 32, 'And We chose them aforetime above the nations, knowingly,'),
  ('en.yusufali', 44, 33, 'And granted them Signs in which there was a manifest trial'),
  ('en.yusufali', 44, 34, 'As to these (Quraish), they say forsooth:'),
  ('en.yusufali', 44, 35, '"There is nothing beyond our first death, and we shall not be raised again.'),
  ('en.yusufali', 44, 36, '"Then bring (back) our forefathers, if what ye say is true!"'),
  ('en.yusufali', 44, 37, 'What! Are they better than the people of Tubba and those who were before them? We destroyed them because they were guilty of sin.'),
  ('en.yusufali', 44, 38, 'We created not the heavens, the earth, and all between them, merely in (idle) sport:'),
  ('en.yusufali', 44, 39, 'We created them not except for just ends: but most of them do not understand.'),
  ('en.yusufali', 44, 40, 'Verily the Day of sorting out is the time appointed for all of them,-'),
  ('en.yusufali', 44, 41, 'The Day when no protector can avail his client in aught, and no help can they receive,'),
  ('en.yusufali', 44, 42, 'Except such as receive Allah\'s Mercy: for He is Exalted in Might, Most Merciful.'),
  ('en.yusufali', 44, 43, 'Verily the tree of Zaqqum'),
  ('en.yusufali', 44, 44, 'Will be the food of the Sinful,-'),
  ('en.yusufali', 44, 45, 'Like molten brass; it will boil in their insides.'),
  ('en.yusufali', 44, 46, 'Like the boiling of scalding water.'),
  ('en.yusufali', 44, 47, '(A voice will cry: "Seize ye him and drag him into the midst of the Blazing Fire!'),
  ('en.yusufali', 44, 48, '"Then pour over his head the Penalty of Boiling Water,'),
  ('en.yusufali', 44, 49, '"Taste thou (this)! Truly wast thou mighty, full of honour!'),
  ('en.yusufali', 44, 50, '"Truly this is what ye used to doubt!"'),
  ('en.yusufali', 44, 51, 'As to the Righteous (they will be) in a position of Security,'),
  ('en.yusufali', 44, 52, 'Among Gardens and Springs;'),
  ('en.yusufali', 44, 53, 'Dressed in fine silk and in rich brocade, they will face each other;'),
  ('en.yusufali', 44, 54, 'So; and We shall join them to fair women with beautiful, big, and lustrous eyes.'),
  ('en.yusufali', 44, 55, 'There can they call for every kind of fruit in peace and security;'),
  ('en.yusufali', 44, 56, 'Nor will they there taste Death, except the first death; and He will preserve them from the Penalty of the Blazing Fire,-'),
  ('en.yusufali', 44, 57, 'As a Bounty from thy Lord! that will be the supreme achievement!'),
  ('en.yusufali', 44, 58, 'Verily, We have made this (Qur\'an) easy, in thy tongue, in order that they may give heed.'),
  ('en.yusufali', 44, 59, 'So wait thou and watch; for they (too) are waiting.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 44, 1, 'Haa Meeem'),
  ('en.transliteration', 44, 2, 'Wal Kitaabil Mubeen'),
  ('en.transliteration', 44, 3, 'Innaaa anzalnaahu fee lailatim mubaarakah; innaa kunnaa munzireen'),
  ('en.transliteration', 44, 4, 'Feehaa yufraqu kullu amrin hakeem'),
  ('en.transliteration', 44, 5, 'Amram min \'indinaaa; innaa kunnaa mursileen'),
  ('en.transliteration', 44, 6, 'Rahmatam mir rabbik; innahoo Huwas Samee\'ul \'Aleem'),
  ('en.transliteration', 44, 7, 'Rabbis samaawaati wal ardi wa maa bainahumaa; in kuntum mooqineen'),
  ('en.transliteration', 44, 8, 'Laaa ilaaha illaa Huwa yuhyee wa yumeetu Rabbukum wa Rabbu aabaaa\'ikumul awwaleen'),
  ('en.transliteration', 44, 9, 'Bal hum fee shakkiny yal\'aboon'),
  ('en.transliteration', 44, 10, 'Fartaqib Yawma taatis samaaa\'u bidukhaanim mubeen'),
  ('en.transliteration', 44, 11, 'Yaghshan naasa haazaa \'azaabun aleem'),
  ('en.transliteration', 44, 12, 'Rabbanak shif \'annal \'azaaba innaa mu\'minoon'),
  ('en.transliteration', 44, 13, 'Annaa lahumuz zikraa wa qad jaaa\'ahum Rasoolum mubeen'),
  ('en.transliteration', 44, 14, 'Summaa tawallaw \'anhu wa qaaloo mu\'allamum majnoon'),
  ('en.transliteration', 44, 15, 'Innaa kaashiful \'azaabi qaleelaa; innakum \'aaa\'indoon'),
  ('en.transliteration', 44, 16, 'Yawma nabtishul batsha tal kubraa innaa muntaqimoon'),
  ('en.transliteration', 44, 17, 'Wa laqad fatannaa qablahum qawma Fir\'awna wa jaaa\'ahum Rasoolun kareem'),
  ('en.transliteration', 44, 18, 'An addooo ilaiya \'ibaadal laahi innee lakum Rasoolun ameen'),
  ('en.transliteration', 44, 19, 'Wa al laa ta\'loo \'alal laahi innee aateekum bisultaanim mubeen'),
  ('en.transliteration', 44, 20, 'Wa innee \'uztu bi Rabbee wa rabbikum an tarjumoon'),
  ('en.transliteration', 44, 21, 'Wa il lam tu\'minoo lee fa\'taziloon'),
  ('en.transliteration', 44, 22, 'Fada\'aa rabbahooo anna haaa\'ulaaa\'i qawmum mujrimoon'),
  ('en.transliteration', 44, 23, 'Fa asri bi\'ibaadee lailan innakum muttaba\'oon'),
  ('en.transliteration', 44, 24, 'Watrukil bahra rahwan innahum jundum mughraqoon'),
  ('en.transliteration', 44, 25, 'Kam tarakoo min jannaatinw wa \'uyoon'),
  ('en.transliteration', 44, 26, 'Wa zuroo\'inw wa maqaa min kareem'),
  ('en.transliteration', 44, 27, 'Wa na\'matin kaanoo feehaa faakiheen'),
  ('en.transliteration', 44, 28, 'Kazaalika wa awrasnaahaa qawman aakhareen'),
  ('en.transliteration', 44, 29, 'Famaa bakat \'alaihimus samaaa\'u wal ardu wa maa kaanoo munzareen'),
  ('en.transliteration', 44, 30, 'Wa laqad najjainaa Baneee Israaa\'eela minal\'azaabil muheen'),
  ('en.transliteration', 44, 31, 'Min Fir\'awn; innahoo kaana \'aaliyam minal musrifeen'),
  ('en.transliteration', 44, 32, 'Wa laqadikh tarnaahum \'alaa \'ilmin \'alal \'aalameen'),
  ('en.transliteration', 44, 33, 'Wa aatainaahum minal aayaati maa feehi balaaa\'um mubeen'),
  ('en.transliteration', 44, 34, 'Inna haaa\'ulaaa\'i la yaqooloon'),
  ('en.transliteration', 44, 35, 'In hiya illaa mawtatunal oolaa wa maa nahnu bimun shareen'),
  ('en.transliteration', 44, 36, 'Faatoo bi aabaaa\'inaaa inkuntum saadiqeen'),
  ('en.transliteration', 44, 37, 'Ahum khayrun am qawmu Tubba\'inw wallazeena min qablihim; ahlaknaahum innahum kaanoo mujrimeen'),
  ('en.transliteration', 44, 38, 'Wa maa khalaqnas samaawaati wal arda wa maa baina humaa laa\'ibeen'),
  ('en.transliteration', 44, 39, 'Maa khalaqnaahumaaa illaa bilhaqqi wa laakinna aksarahum laa ya\'lamoon'),
  ('en.transliteration', 44, 40, 'Inna yawmal fasli meeqaatuhum ajma\'een'),
  ('en.transliteration', 44, 41, 'Yawma laa yughnee mawlan \'am mawlan shai\'anw wa laa hum yunsaroon'),
  ('en.transliteration', 44, 42, 'Illaa mar rahimal laah\' innahoo huwal \'azeezur raheem'),
  ('en.transliteration', 44, 43, 'Inna shajarataz zaqqoom'),
  ('en.transliteration', 44, 44, 'Ta\'aamul aseem'),
  ('en.transliteration', 44, 45, 'Kalmuhli yaghlee filbutoon'),
  ('en.transliteration', 44, 46, 'Kaghalyil hameem'),
  ('en.transliteration', 44, 47, 'Khuzoohu fa\'tiloohu ilaa sawaaa\'il Jaheem'),
  ('en.transliteration', 44, 48, 'Summa subboo fawqa raasihee min \'azaabil hameem'),
  ('en.transliteration', 44, 49, 'Zuq innaka antal \'azeezul kareem'),
  ('en.transliteration', 44, 50, 'Inna haazaa maa kuntum bihee tamtaroon'),
  ('en.transliteration', 44, 51, 'Innal muttaqeena fee maqaamin ameen'),
  ('en.transliteration', 44, 52, 'Fee jannaatinw wa \'uyoon'),
  ('en.transliteration', 44, 53, 'Yalbasoona min sundusinw wa istbraqim mutaqaabileen'),
  ('en.transliteration', 44, 54, 'Kazaalika wa zawwajnaahum bihoorin \'een'),
  ('en.transliteration', 44, 55, 'Yad\'oona feehaa bikulli faakihatin aamineen'),
  ('en.transliteration', 44, 56, 'Laa yazooqoona feehal mawtaa illal mawtatal oolaa wa qaqaahum \'azaabal jaheem'),
  ('en.transliteration', 44, 57, 'Fadlam mir rabbik; zaalika huwal fawzul \'azeem'),
  ('en.transliteration', 44, 58, 'Fa innamaa yassarnaahu bilisaanika la\'allahum yatazakkaroon'),
  ('en.transliteration', 44, 59, 'Fartaqib innahum murta qiboon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 44, 1, 'حمۤ'),
  ('ur.ahmedali', 44, 2, 'روشن کتاب کی قسم ہے'),
  ('ur.ahmedali', 44, 3, 'ہم نے اسے مبارک رات میں نازل کیا ہے بے شک ہمیں ڈرانا مقصود تھا'),
  ('ur.ahmedali', 44, 4, 'سارے کام جو حکمت پر مبنی ہیں اسی رات تصفیہ پاتے ہیں'),
  ('ur.ahmedali', 44, 5, 'ہمارے خاص حکم سے کیوں کہ ہمیں رسول بھیجنا منظور تھا'),
  ('ur.ahmedali', 44, 6, 'آپ کے پروردگار کی رحمت ہے بے شک وہی سب کچھ سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 44, 7, 'آسمانوں اور زمین کا رب ہے اور جو کچھ ان کے درمیان ہے اگر تم یقین کر نے والے ہو'),
  ('ur.ahmedali', 44, 8, 'اس کے سوا اورکوئی معبود نہیں زندہ کرتا ہے اور مارتا ہے تمہارا بھی رب ہے او رتمہارے پہلے باپ دادا کا بھی'),
  ('ur.ahmedali', 44, 9, 'بلکہ وہ تو شک میں کھیل رہے ہیں'),
  ('ur.ahmedali', 44, 10, 'سو اس دن کا انتظار کیجیئے کہ آسمان دھواں ظاہر لائے'),
  ('ur.ahmedali', 44, 11, 'جو لوگوں کو ڈھانپ لے یہی دردناک عذاب ہے'),
  ('ur.ahmedali', 44, 12, 'اے ہمارے رب ہم سے یہ عذاب دور کر دے بے شک ہم ایمان لانے والے ہیں'),
  ('ur.ahmedali', 44, 13, 'وہ کہاں سمجھتے ہیں حالانکہ ان کے پاس کھول کر سنانے والا رسول بھی آ چکا ہے'),
  ('ur.ahmedali', 44, 14, 'پھر اس سے بھی پھر گئے اور کہا کہ سکھایا ہوا دیوانہ ہے'),
  ('ur.ahmedali', 44, 15, 'ہم اس عذاب کو تھوڑی دیر کے لیےہٹا دیں گے تم پھر وہی کرنے والے ہو'),
  ('ur.ahmedali', 44, 16, 'جس دن ہم بڑی سخت پکڑ پکڑیں گے بے شک ہم بدلہ لینے والے ہیں'),
  ('ur.ahmedali', 44, 17, 'اور ان سے پہلے ہم فرعون کی قوم کو آزما چکے ہیں اور ان کے پاس ایک عزت والا رسول بھی آیا تھا'),
  ('ur.ahmedali', 44, 18, 'کہ الله کے بندوں کو میرے حوالہ کر دو بے شک میں تمہارے لیے ایک امانت دار رسول ہوں'),
  ('ur.ahmedali', 44, 19, 'اور یہ کہ الله کے خلاف سرکشی نہ کرو میں تمہارے پاس کھلی دلیل لایا ہوں'),
  ('ur.ahmedali', 44, 20, 'اور بے شک میں نے اپنے اور تمہارے رب کی پناہ لی ہے اس واسطے کہ تم مجھے سنگسار کرو'),
  ('ur.ahmedali', 44, 21, 'اور اگرتم میری بات پر ایمان نہیں لاتے تو مجھ سے الگ ہو جاؤ'),
  ('ur.ahmedali', 44, 22, 'پس اس نے اپنے رب کو پکارا کہ یہ تو مجرم لوگ ہیں'),
  ('ur.ahmedali', 44, 23, 'حکم ہوا پس میرے بندوں کو رات کے وقت لے چل کیوں کہ تمہارا پیچھا کیا جائے گا'),
  ('ur.ahmedali', 44, 24, 'اور سمندر کو ٹھہرا ہوا چھوڑ دے بے شک وہ لشکر ڈوبنے والے ہیں'),
  ('ur.ahmedali', 44, 25, 'کتنے انہوں نے باغات اور چشمے چھوڑے ہیں'),
  ('ur.ahmedali', 44, 26, 'اور کھیتیاں اور مقام عمدہ'),
  ('ur.ahmedali', 44, 27, 'اورنعمت کے سازو سامان جس میں وہ مزے کیا کرتے تھے'),
  ('ur.ahmedali', 44, 28, 'اسی طرح ہوا اورہم نے ان کا ایک دوسری قوم کو وارث کر دیا'),
  ('ur.ahmedali', 44, 29, 'پس ان پر نہ آسمان روویا اور نہ زمین اور نہ ان کو مہلت دی گئی'),
  ('ur.ahmedali', 44, 30, 'اورہم نے بنی اسرائیل کو اس ذلت کےعذاب سے نجات دی'),
  ('ur.ahmedali', 44, 31, '(یعنی) فرعون سے بے شک وہ ایک سرکش حد سے بڑھنے والا تھا'),
  ('ur.ahmedali', 44, 32, 'اور ہم نے اپنے علم سے ان کو جہان والوں پر چن لیا تھا'),
  ('ur.ahmedali', 44, 33, 'اور ہم نے ان کو نشانیاں دی تھیں جن میں صریح آزمائش تھی'),
  ('ur.ahmedali', 44, 34, 'بے شک یہ لوگ کہتے ہیں'),
  ('ur.ahmedali', 44, 35, 'کہ او رمرنا نہیں ہے مگر یہی ہمارا پہلی بار کا مرنا اور ہم دوبارہ اٹھائے جانے والے نہیں'),
  ('ur.ahmedali', 44, 36, 'پس ہمارے باپ دادا کو لے آؤ اگر تم سچے ہو'),
  ('ur.ahmedali', 44, 37, 'کیا وہ بہتر ہیں یا تبع کی قوم اوروہ لوگ جو ان سے پہلے ہوئے ہم نے انہیں ہلاک کر دیا کیوں کہ وہ مجرم تھے'),
  ('ur.ahmedali', 44, 38, 'اور ہم نے آسمانوں اور زمین کو اورجو کچھ اس کے درمیان میں ہے کھیل کے لیے نہیں بنایا'),
  ('ur.ahmedali', 44, 39, 'ہم نے انہیں بہت ہی مصلحت سے بنایا ہے لیکن اکثر ان میں سے نہیں جانتے'),
  ('ur.ahmedali', 44, 40, 'بے شک فیصلہ کا دن ان سب کے لیے مقرر ہو چکا ہے'),
  ('ur.ahmedali', 44, 41, 'جس دن کوئی دوست کسی دوست کے کچھ بھی کام نہیں آئے گا اورنہ انہیں مدد ملے گی'),
  ('ur.ahmedali', 44, 42, 'مگر جس پر الله نے رحم کیابے شک وہ زبردست رحم والا ہے'),
  ('ur.ahmedali', 44, 43, 'بے شک تھوہر کا درخت'),
  ('ur.ahmedali', 44, 44, 'گناہگارو ں کا کھانا ہے'),
  ('ur.ahmedali', 44, 45, 'پگھلے ہوئے تانبے کی طرح پیٹو ں میں کھولے گا'),
  ('ur.ahmedali', 44, 46, 'جیسے پکتا ہوا پانی کھولتا ہے'),
  ('ur.ahmedali', 44, 47, 'اسے پکڑ لو پس اسے دوزخ کے درمیان دھکیل کر لے جاؤ'),
  ('ur.ahmedali', 44, 48, 'پھر اس کے سر پر عذاب کا کھولتا ہوا پانی ڈالو'),
  ('ur.ahmedali', 44, 49, 'چکھ بے شک تو تو بڑا عزت والا بزرگی والا ہے'),
  ('ur.ahmedali', 44, 50, 'بے شک یہی ہے جس کی نسبت تم شک کیا کرتے تھے'),
  ('ur.ahmedali', 44, 51, 'بے شک پرہیزگار ہی امن کی جگہ میں ہوں گے'),
  ('ur.ahmedali', 44, 52, 'باغوں اور چشموں میں'),
  ('ur.ahmedali', 44, 53, 'باریک ریشم اورگاڑھا پہن کر آمنے سامنے بیٹھے ہوں گے'),
  ('ur.ahmedali', 44, 54, 'یونہی ہوگا اور ہم ان کا نکاح بڑی آنکھوں والی حوروں سے کر دیں گے'),
  ('ur.ahmedali', 44, 55, 'وہ اس میں ہر قسم کا میوہ امن و اطمینان سے طلب کریں گے'),
  ('ur.ahmedali', 44, 56, 'وہا ں پہلی موت کے سوا اور موت کا مرہ نہ چکھیں گے اورانہیں الله دوزح کے عذاب سے بچا لے گا'),
  ('ur.ahmedali', 44, 57, 'یہ آپکے رب کا فضل ہوگا یہی وہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 44, 58, 'اس قرآن کو ہم نے آپ کی زبان میں آسان کر دیا تاکہ وہ سمجھیں'),
  ('ur.ahmedali', 44, 59, 'پس آپ انتظار کیجیئے بے شک وہ بھی انتظار کر ہے ہیں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 44, 1, 'Ha, Mim.'),
  ('tr.diyanet', 44, 2, 'Apaçık olan Kitap\'a and olsun ki, Biz onu, kutlu bir gecede indirdik. Doğrusu Biz, insanları uyarmaktayız.'),
  ('tr.diyanet', 44, 3, 'Apaçık olan Kitap\'a and olsun ki, Biz onu, kutlu bir gecede indirdik. Doğrusu Biz, insanları uyarmaktayız.'),
  ('tr.diyanet', 44, 4, 'Katımızdan bir buyrukla, her hikmetli işe o gecede hükmedilir. Doğrusu Biz öteden beri peygamberler göndermekteyiz. Eğer kesin olarak inanırsanız bilin ki, bu senin Rabbinden, göklerin, yerin ve ikisi arasında bulunanların Rabbinden bir rahmettir. O, işitendir, bilendir.'),
  ('tr.diyanet', 44, 5, 'Katımızdan bir buyrukla, her hikmetli işe o gecede hükmedilir. Doğrusu Biz öteden beri peygamberler göndermekteyiz. Eğer kesin olarak inanırsanız bilin ki, bu senin Rabbinden, göklerin, yerin ve ikisi arasında bulunanların Rabbinden bir rahmettir. O, işitendir, bilendir.'),
  ('tr.diyanet', 44, 6, 'Katımızdan bir buyrukla, her hikmetli işe o gecede hükmedilir. Doğrusu Biz öteden beri peygamberler göndermekteyiz. Eğer kesin olarak inanırsanız bilin ki, bu senin Rabbinden, göklerin, yerin ve ikisi arasında bulunanların Rabbinden bir rahmettir. O, işitendir, bilendir.'),
  ('tr.diyanet', 44, 7, 'Katımızdan bir buyrukla, her hikmetli işe o gecede hükmedilir. Doğrusu Biz öteden beri peygamberler göndermekteyiz. Eğer kesin olarak inanırsanız bilin ki, bu senin Rabbinden, göklerin, yerin ve ikisi arasında bulunanların Rabbinden bir rahmettir. O, işitendir, bilendir.'),
  ('tr.diyanet', 44, 8, 'O\'ndan başka tanrı yoktur; diriltir ve öldürür. Sizin de Rabbiniz önceki atalarınızın da Rabbidir.'),
  ('tr.diyanet', 44, 9, 'Ama inkarcılar, dirilmekten şüphededirler, bunu eğlenceye alırlar.'),
  ('tr.diyanet', 44, 10, 'Göğün, insanları bürüyecek ve gözle görülecek bir duman çıkaracağı günü bekle; bu, can yakan bir azabdır.'),
  ('tr.diyanet', 44, 11, 'Göğün, insanları bürüyecek ve gözle görülecek bir duman çıkaracağı günü bekle; bu, can yakan bir azabdır.'),
  ('tr.diyanet', 44, 12, 'İnsanlar: "Rabbimiz! Bu azabı bizden kaldır; doğrusu artık biz inananlarız" derler.'),
  ('tr.diyanet', 44, 13, 'Nerde onlarda öğüt almak? Kendilerine gerçeği açıklayan bir peygamber gelmişti ve ondan yüz çevirmişler, "Belletilmiş bir deli" demişlerdi.'),
  ('tr.diyanet', 44, 14, 'Nerde onlarda öğüt almak? Kendilerine gerçeği açıklayan bir peygamber gelmişti ve ondan yüz çevirmişler, "Belletilmiş bir deli" demişlerdi.'),
  ('tr.diyanet', 44, 15, 'Biz sizden azabı az bir süre için kaldıracağız, siz yine de eski inkarcılığınıza döneceksiniz.'),
  ('tr.diyanet', 44, 16, 'Onları çarptıkça çarpacağımız gün öcümüzü şüphesiz alırız.'),
  ('tr.diyanet', 44, 17, 'And olsun ki, onlardan önce, Firavun milletini denemiştik. Onlara gelen değerli bir peygamber demişti ki:'),
  ('tr.diyanet', 44, 18, '"Ey Allah\'ın kulları! Bana gelin, doğrusu ben size gönderilmiş güvenilir bir elçiyim."'),
  ('tr.diyanet', 44, 19, '"Allah\'a karşı üstün gelmeye kalkışmayın; doğrusu ben size apaçık bir delil getirdim."'),
  ('tr.diyanet', 44, 20, '"Beni taşlamanızdan ötürü, benim de Rabbim, sizin de Rabbiniz olan Allah\'a sığındım."'),
  ('tr.diyanet', 44, 21, '"Bana inanmazsanız, başımdan çekilin."'),
  ('tr.diyanet', 44, 22, 'Bunlar, suçlu bir millet olduğu için, Rabbine yardım etmesi için yalvardı.'),
  ('tr.diyanet', 44, 23, 'Allah da şöyle buyurdu: "Kullarımı geceleyin yola çıkar; şüphesiz takip olunacaksınız."'),
  ('tr.diyanet', 44, 24, '"Denizi sakin iken geride bırak, doğrusu onlar suda boğulacak bir ordudur."'),
  ('tr.diyanet', 44, 25, 'Orada nice bahçeler, pınarlar, ekinler, güzel konaklar, eğlenip durdukları nimetler bırakmışlardı.'),
  ('tr.diyanet', 44, 26, 'Orada nice bahçeler, pınarlar, ekinler, güzel konaklar, eğlenip durdukları nimetler bırakmışlardı.'),
  ('tr.diyanet', 44, 27, 'Orada nice bahçeler, pınarlar, ekinler, güzel konaklar, eğlenip durdukları nimetler bırakmışlardı.'),
  ('tr.diyanet', 44, 28, 'Bu böyledir; onları başka bir millete miras bıraktık.'),
  ('tr.diyanet', 44, 29, 'Gök ve yer, onlar için gözyaşı dökmedi, onlar erteye bırakılmamışlardı.'),
  ('tr.diyanet', 44, 30, 'And olsun ki, İsrailoğullarını, azgın bir zorba olan Firavun\'un alçaltıcı azabından kurtardık.'),
  ('tr.diyanet', 44, 31, 'And olsun ki, İsrailoğullarını, azgın bir zorba olan Firavun\'un alçaltıcı azabından kurtardık.'),
  ('tr.diyanet', 44, 32, 'And olsun ki, onların durumunu bilerek dünyaların üzerinde seçkin kıldık.'),
  ('tr.diyanet', 44, 33, 'Onlara, her birinde açıkça bir imtihan bulunan, mucizeler verdik.'),
  ('tr.diyanet', 44, 34, 'Doğrusu inkarcılar, "Ölum bir defadır, tekrar diriltilmeyeceğiz. Eğer doğru sözlü iseniz bize babalarımızı getirsenize" derler.'),
  ('tr.diyanet', 44, 35, 'Doğrusu inkarcılar, "Ölum bir defadır, tekrar diriltilmeyeceğiz. Eğer doğru sözlü iseniz bize babalarımızı getirsenize" derler.'),
  ('tr.diyanet', 44, 36, 'Doğrusu inkarcılar, "Ölum bir defadır, tekrar diriltilmeyeceğiz. Eğer doğru sözlü iseniz bize babalarımızı getirsenize" derler.'),
  ('tr.diyanet', 44, 37, 'Bunlar mı daha üstün yoksa Tubba milleti ve onlardan öncekiler mi? Onları yok etmişizdir, çünkü onlar suçlu idiler.'),
  ('tr.diyanet', 44, 38, 'Biz gökleri, yeri ve ikisinin arasında bulunanları oyun olsun diye yaratmadık.'),
  ('tr.diyanet', 44, 39, 'Biz onları, ancak ve ancak gerektiği gibi yarattık, ama insanların çoğu bilmezler.'),
  ('tr.diyanet', 44, 40, 'Doğrusu hüküm günü hepsinin bir arada bulunacağı gündür.'),
  ('tr.diyanet', 44, 41, 'O gün, dostun dosta hiçbir faydası olmaz, yardım da görmezler.'),
  ('tr.diyanet', 44, 42, 'Yalnız, Allah\'ın merhamet ettiği kimseler bunların dışındadır. O, şüphesiz güçlüdür, merhametlidir.'),
  ('tr.diyanet', 44, 43, 'Doğrusu günahkarların yiyeceği zakkum ağacıdır; karınlarda suyun kaynaması gibi kaynayan, erimiş maden gibidir.'),
  ('tr.diyanet', 44, 44, 'Doğrusu günahkarların yiyeceği zakkum ağacıdır; karınlarda suyun kaynaması gibi kaynayan, erimiş maden gibidir.'),
  ('tr.diyanet', 44, 45, 'Doğrusu günahkarların yiyeceği zakkum ağacıdır; karınlarda suyun kaynaması gibi kaynayan, erimiş maden gibidir.'),
  ('tr.diyanet', 44, 46, 'Doğrusu günahkarların yiyeceği zakkum ağacıdır; karınlarda suyun kaynaması gibi kaynayan, erimiş maden gibidir.'),
  ('tr.diyanet', 44, 47, '"Suçluyu yakalayın, cehennemin ortasına sürükleyin, sonra başına azap olarak kaynar su dökün" denir, sonra ona: "Tad bakalım, hani şerefli olan, değerli olan yalnız sendin. İşte bu, şüphelenip durduğunuz şeydir" denir.'),
  ('tr.diyanet', 44, 48, '"Suçluyu yakalayın, cehennemin ortasına sürükleyin, sonra başına azap olarak kaynar su dökün" denir, sonra ona: "Tad bakalım, hani şerefli olan, değerli olan yalnız sendin. İşte bu, şüphelenip durduğunuz şeydir" denir.'),
  ('tr.diyanet', 44, 49, '"Suçluyu yakalayın, cehennemin ortasına sürükleyin, sonra başına azap olarak kaynar su dökün" denir, sonra ona: "Tad bakalım, hani şerefli olan, değerli olan yalnız sendin. İşte bu, şüphelenip durduğunuz şeydir" denir.'),
  ('tr.diyanet', 44, 50, '"Suçluyu yakalayın, cehennemin ortasına sürükleyin, sonra başına azap olarak kaynar su dökün" denir, sonra ona: "Tad bakalım, hani şerefli olan, değerli olan yalnız sendin. İşte bu, şüphelenip durduğunuz şeydir" denir.'),
  ('tr.diyanet', 44, 51, 'Allah\'a karşı gelmekten sakınmış olanlar ise, güvenli bir yerde, bahçelerde ve pınar başlarındadırlar.'),
  ('tr.diyanet', 44, 52, 'Allah\'a karşı gelmekten sakınmış olanlar ise, güvenli bir yerde, bahçelerde ve pınar başlarındadırlar.'),
  ('tr.diyanet', 44, 53, 'İnce ipekten ve parlak atlastan giyinerek karşılıklı otururlar.'),
  ('tr.diyanet', 44, 54, 'Bu böyledir; onları iri siyah gözlü hurilerle eşlendiririz.'),
  ('tr.diyanet', 44, 55, 'Orada, güven içinde olarak her yemişi isteyebilirler.'),
  ('tr.diyanet', 44, 56, 'Orada, ilk ölümden başka bir ölüm tatmazlar. Rabbin lütfuyla onları cehennem azabından korumuştur. İşte büyük kurtuluş budur.'),
  ('tr.diyanet', 44, 57, 'Orada, ilk ölümden başka bir ölüm tatmazlar. Rabbin lütfuyla onları cehennem azabından korumuştur. İşte büyük kurtuluş budur.'),
  ('tr.diyanet', 44, 58, 'Biz, öğüt alırlar diye, Kuran\'ı senin dilinde indirerek kolayca anlaşılmasını sağladık. Sen bekle, onlar da beklemektedirler.'),
  ('tr.diyanet', 44, 59, 'Biz, öğüt alırlar diye, Kuran\'ı senin dilinde indirerek kolayca anlaşılmasını sağladık. Sen bekle, onlar da beklemektedirler.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 44, 1, 'Haa miim.'),
  ('id.indonesian', 44, 2, 'Demi Kitab (Al Quran) yang menjelaskan,'),
  ('id.indonesian', 44, 3, 'sesungguhnya Kami menurunkannya pada suatu malam yang diberkahi dan sesungguhnya Kami-lah yang memberi peringatan.'),
  ('id.indonesian', 44, 4, 'Pada malam itu dijelaskan segala urusan yang penuh hikmah,'),
  ('id.indonesian', 44, 5, '(yaitu) urusan yang besar dari sisi Kami. Sesungguhnya Kami adalah Yang mengutus rasul-rasul,'),
  ('id.indonesian', 44, 6, 'sebagai rahmat dari Tuhanmu. Sesungguhnya Dialah Yang Maha Mendengar lagi Maha Mengetahui,'),
  ('id.indonesian', 44, 7, 'Tuhan Yang memelihara langit dan bumi dan apa yang ada di antara keduanya, jika kamu adalah orang yang meyakini.'),
  ('id.indonesian', 44, 8, 'Tidak ada Tuhan (yang berhak disembah) melainkan Dia, Yang menghidupkan dan Yang mematikan (Dialah) Tuhanmu dan Tuhan bapak-bapakmu yang terdahulu.'),
  ('id.indonesian', 44, 9, 'Tetapi mereka bermain-main dalam keragu-raguan.'),
  ('id.indonesian', 44, 10, 'Maka tunggulah hari ketika langit membawa kabut yang nyata,'),
  ('id.indonesian', 44, 11, 'yang meliputi manusia. Inilah azab yang pedih.'),
  ('id.indonesian', 44, 12, '(Mereka berdoa): "Ya Tuhan kami, lenyapkanlah dari kami azab itu. Sesungguhnya kami akan beriman".'),
  ('id.indonesian', 44, 13, 'Bagaimanakah mereka dapat menerima peringatan, padahal telah datang kepada mereka seorang rasul yang memberi penjelasan,'),
  ('id.indonesian', 44, 14, 'kemudian mereka berpaling daripadanya dan berkata: "Dia adalah seorang yang menerima ajaran (dari orang lain) lagi pula seorang yang gila".'),
  ('id.indonesian', 44, 15, 'Sesungguhnya (kalau) Kami akan melenyapkan siksaan itu agak sedikit sesungguhnya kamu akan kembali (ingkar).'),
  ('id.indonesian', 44, 16, '(Ingatlah) hari (ketika) Kami menghantam mereka dengan hantaman yang keras. Sesungguhnya Kami adalah Pemberi balasan.'),
  ('id.indonesian', 44, 17, 'Sesungguhnya sebelum mereka telah Kami uji kaum Fir\'aun dan telah datang kepada mereka seorang rasul yang mulia,'),
  ('id.indonesian', 44, 18, '(dengan berkata): "Serahkanlah kepadaku hamba-hamba Allah (Bani Israil yang kamu perbudak). Sesungguhnya aku adalah utusan (Allah) yang dipercaya kepadamu,'),
  ('id.indonesian', 44, 19, 'dan janganlah kamu menyombongkan diri terhadap Allah. Sesungguhnya aku datang kepadamu dengan membawa bukti yang nyata.'),
  ('id.indonesian', 44, 20, 'Dan sesungguhnya aku berlindung kepada Tuhanku dan Tuhanmu, dari keinginanmu merajamku,'),
  ('id.indonesian', 44, 21, 'dan jika kamu tidak beriman kepadaku maka biarkanlah aku (memimpin Bani Israil)".'),
  ('id.indonesian', 44, 22, 'Kemudian Musa berdoa kepada Tuhannya: "Sesungguhnya mereka ini adalah kaum yang berdosa (segerakanlah azab kepada mereka)".'),
  ('id.indonesian', 44, 23, '(Allah berfirman): "Maka berjalanlah kamu dengan membawa hamba-hamba-Ku pada malam hari, sesungguhnya kamu akan dikejar,'),
  ('id.indonesian', 44, 24, 'dan biarkanlah laut itu tetap terbelah. Sesungguhnya mereka adalah tentara yang akan ditenggelamkan".'),
  ('id.indonesian', 44, 25, 'Alangkah banyaknya taman dan mata air yang mereka tinggalkan,'),
  ('id.indonesian', 44, 26, 'dan kebun-kebun serta tempat-tempat yang indah-indah,'),
  ('id.indonesian', 44, 27, 'dan kesenangan-kesenangan yang mereka menikmatinya,'),
  ('id.indonesian', 44, 28, 'demikianlah. Dan Kami wariskan semua itu kepada kaum yang lain.'),
  ('id.indonesian', 44, 29, 'Maka langit dan bumi tidak menangisi mereka dan merekapun tidak diberi tangguh.'),
  ('id.indonesian', 44, 30, 'Dan sesungguhnya telah Kami selamatkan Bani Israil dari siksa yang menghinakan,'),
  ('id.indonesian', 44, 31, 'dari (azab) Fir\'aun. Sesungguhnya dia adalah orang yang sombong, salah seorang dari orang-orang yang melampaui batas.'),
  ('id.indonesian', 44, 32, 'Dan sesungguhnya telah Kami pilih mereka dengan pengetahuan (Kami) atas bangsa-bangsa.'),
  ('id.indonesian', 44, 33, 'Dan Kami telah memberikan kepada mereka di antara tanda-tanda kekuasaan (Kami) sesuatu yang di dalamnya terdapat nikmat yang nyata.'),
  ('id.indonesian', 44, 34, 'Sesungguhnya mereka (kaum musyrik) itu benar-benar berkata,'),
  ('id.indonesian', 44, 35, '"tidak ada kematian selain kematian di dunia ini. Dan kami sekali-kali tidak akan dibangkitkan,'),
  ('id.indonesian', 44, 36, 'maka datangkanlah (kembali) bapak-bapak kami jika kamu memang orang-orang yang benar".'),
  ('id.indonesian', 44, 37, 'Apakah mereka (kaum musyrikin) yang lebih baik ataukah kaum Tubba\' dan orang-orang yang sebelum mereka. Kami telah membinasakan mereka karena sesungguhnya mereka adalah orang-orang yang berdosa.'),
  ('id.indonesian', 44, 38, 'Dan Kami tidak menciptakan langit dan bumi dan apa yang ada antara keduanya dengan bermain-main.'),
  ('id.indonesian', 44, 39, 'Kami tidak menciptakan keduanya melainkan dengan haq, tetapi kebanyakan mereka tidak mengetahui.'),
  ('id.indonesian', 44, 40, 'Sesungguhnya hari keputusan (hari kiamat) itu adalah waktu yang dijanjikan bagi mereka semuanya,'),
  ('id.indonesian', 44, 41, 'yaitu hari yang seorang karib tidak dapat memberi manfaat kepada karibnya sedikitpun, dan mereka tidak akan mendapat pertolongan,'),
  ('id.indonesian', 44, 42, 'kecuali orang yang diberi rahmat oleh Allah. Sesungguhnya Dialah Yang Maha Perkasa lagi Maha Penyayang.'),
  ('id.indonesian', 44, 43, 'Sesungguhnya pohon zaqqum itu,'),
  ('id.indonesian', 44, 44, 'makanan orang yang banyak berdosa.'),
  ('id.indonesian', 44, 45, '(Ia) sebagai kotoran minyak yang mendidih di dalam perut,'),
  ('id.indonesian', 44, 46, 'seperti mendidihnya air yang amat panas.'),
  ('id.indonesian', 44, 47, 'Peganglah dia kemudian seretlah dia ke tengah-tengah neraka.'),
  ('id.indonesian', 44, 48, 'Kemudian tuangkanlah di atas kepalanya siksaan (dari) air yang amat panas.'),
  ('id.indonesian', 44, 49, 'Rasakanlah, sesungguhnya kamu orang yang perkasa lagi mulia.'),
  ('id.indonesian', 44, 50, 'Sesungguhnya ini adalah azab yang dahulu selalu kamu meragu-ragukannya.'),
  ('id.indonesian', 44, 51, 'Sesungguhnya orang-orang yang bertakwa berada dalam tempat yang aman,'),
  ('id.indonesian', 44, 52, '(yaitu) di dalam taman-taman dan mata-air-mata-air;'),
  ('id.indonesian', 44, 53, 'mereka memakai sutera yang halus dan sutera yang tebal, (duduk) berhadap-hadapan,'),
  ('id.indonesian', 44, 54, 'demikianlah. Dan Kami berikan kepada mereka bidadari.'),
  ('id.indonesian', 44, 55, 'Di dalamnya mereka meminta segala macam buah-buahan dengan aman (dari segala kekhawatiran),'),
  ('id.indonesian', 44, 56, 'mereka tidak akan merasakan mati di dalamnya kecuali mati di dunia. Dan Allah memelihara mereka dari azab neraka,'),
  ('id.indonesian', 44, 57, 'sebagai karunia dari Tuhanmu. Yang demikian itu adalah keberuntungan yang besar.'),
  ('id.indonesian', 44, 58, 'Sesungguhnya Kami mudahkan Al Quran itu dengan bahasamu supaya mereka mendapat pelajaran.'),
  ('id.indonesian', 44, 59, 'Maka tunggulah; sesungguhnya mereka itu menunggu (pula).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 45, 1, 'Ha, Meem.'),
  ('en.sahih', 45, 2, 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.'),
  ('en.sahih', 45, 3, 'Indeed, within the heavens and earth are signs for the believers.'),
  ('en.sahih', 45, 4, 'And in the creation of yourselves and what He disperses of moving creatures are signs for people who are certain [in faith].'),
  ('en.sahih', 45, 5, 'And [in] the alternation of night and day and [in] what Allah sends down from the sky of provision and gives life thereby to the earth after its lifelessness and [in His] directing of the winds are signs for a people who reason.'),
  ('en.sahih', 45, 6, 'These are the verses of Allah which We recite to you in truth. Then in what statement after Allah and His verses will they believe?'),
  ('en.sahih', 45, 7, 'Woe to every sinful liar'),
  ('en.sahih', 45, 8, 'Who hears the verses of Allah recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment.'),
  ('en.sahih', 45, 9, 'And when he knows anything of Our verses, he takes them in ridicule. Those will have a humiliating punishment.'),
  ('en.sahih', 45, 10, 'Before them is Hell, and what they had earned will not avail them at all nor what they had taken besides Allah as allies. And they will have a great punishment.'),
  ('en.sahih', 45, 11, 'This [Qur\'an] is guidance. And those who have disbelieved in the verses of their Lord will have a painful punishment of foul nature.'),
  ('en.sahih', 45, 12, 'It is Allah who subjected to you the sea so that ships may sail upon it by His command and that you may seek of His bounty; and perhaps you will be grateful.'),
  ('en.sahih', 45, 13, 'And He has subjected to you whatever is in the heavens and whatever is on the earth - all from Him. Indeed in that are signs for a people who give thought.'),
  ('en.sahih', 45, 14, 'Say, [O Muhammad], to those who have believed that they [should] forgive those who expect not the days of Allah so that He may recompense a people for what they used to earn.'),
  ('en.sahih', 45, 15, 'Whoever does a good deed - it is for himself; and whoever does evil - it is against the self. Then to your Lord you will be returned.'),
  ('en.sahih', 45, 16, 'And We did certainly give the Children of Israel the Scripture and judgement and prophethood, and We provided them with good things and preferred them over the worlds.'),
  ('en.sahih', 45, 17, 'And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ.'),
  ('en.sahih', 45, 18, 'Then We put you, [O Muhammad], on an ordained way concerning the matter [of religion]; so follow it and do not follow the inclinations of those who do not know.'),
  ('en.sahih', 45, 19, 'Indeed, they will never avail you against Allah at all. And indeed, the wrongdoers are allies of one another; but Allah is the protector of the righteous.'),
  ('en.sahih', 45, 20, 'This [Qur\'an] is enlightenment for mankind and guidance and mercy for a people who are certain [in faith].'),
  ('en.sahih', 45, 21, 'Or do those who commit evils think We will make them like those who have believed and done righteous deeds - [make them] equal in their life and their death? Evil is that which they judge.'),
  ('en.sahih', 45, 22, 'And Allah created the heavens and earth in truth and so that every soul may be recompensed for what it has earned, and they will not be wronged.'),
  ('en.sahih', 45, 23, 'Have you seen he who has taken as his god his [own] desire, and Allah has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allah? Then will you not be reminded?'),
  ('en.sahih', 45, 24, 'And they say, "There is not but our worldly life; we die and live, and nothing destroys us except time." And they have of that no knowledge; they are only assuming.'),
  ('en.sahih', 45, 25, 'And when Our verses are recited to them as clear evidences, their argument is only that they say, "Bring [back] our forefathers, if you should be truthful."'),
  ('en.sahih', 45, 26, 'Say, "Allah causes you to live, then causes you to die; then He will assemble you for the Day of Resurrection, about which there is no doubt, but most of the people do not know."'),
  ('en.sahih', 45, 27, 'And to Allah belongs the dominion of the heavens and the earth. And the Day the Hour appears - that Day the falsifiers will lose.'),
  ('en.sahih', 45, 28, 'And you will see every nation kneeling [from fear]. Every nation will be called to its record [and told], "Today you will be recompensed for what you used to do.'),
  ('en.sahih', 45, 29, 'This, Our record, speaks about you in truth. Indeed, We were having transcribed whatever you used to do."'),
  ('en.sahih', 45, 30, 'So as for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is what is the clear attainment.'),
  ('en.sahih', 45, 31, 'But as for those who disbelieved, [it will be said], "Were not Our verses recited to you, but you were arrogant and became a people of criminals?'),
  ('en.sahih', 45, 32, 'And when it was said, \'Indeed, the promise of Allah is truth and the Hour [is coming] - no doubt about it,\' you said, \'We know not what is the Hour. We assume only assumption, and we are not convinced.\' "'),
  ('en.sahih', 45, 33, 'And the evil consequences of what they did will appear to them, and they will be enveloped by what they used to ridicule.'),
  ('en.sahih', 45, 34, 'And it will be said, "Today We will forget you as you forgot the meeting of this Day of yours, and your refuge is the Fire, and for you there are no helpers.'),
  ('en.sahih', 45, 35, 'That is because you took the verses of Allah in ridicule, and worldly life deluded you." So that Day they will not be removed from it, nor will they be asked to appease [Allah].'),
  ('en.sahih', 45, 36, 'Then, to Allah belongs [all] praise - Lord of the heavens and Lord of the earth, Lord of the worlds.'),
  ('en.sahih', 45, 37, 'And to Him belongs [all] grandeur within the heavens and the earth, and He is the Exalted in Might, the Wise.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 45, 1, 'হা-মীম।'),
  ('bn.bengali', 45, 2, 'পরাক্রান্ত, প্রজ্ঞাময় আল্লাহর পক্ষ থেকে অবতীর্ণ এ কিতাব।'),
  ('bn.bengali', 45, 3, 'নিশ্চয় নভোমন্ডল ও ভূ-মন্ডলে মুমিনদের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 45, 4, 'আর তোমাদের সৃষ্টিতে এবং চারদিকে ছড়িয়ে রাখা জীব জন্তুর সৃজনের মধ্যেও নিদর্শনাবলী রয়েছে বিশ্বাসীদের জন্য।'),
  ('bn.bengali', 45, 5, 'দিবারাত্রির পরিবর্তনে, আল্লাহ আকাশ থেকে যে রিযিক (বৃষ্টি) বর্ষণ করেন অতঃপর পৃথিবীকে তার মৃত্যুর পর পুনরুজ্জীবিত করেন, তাতে এবং বায়ুর পরিবর্তনে বুদ্ধিমানদের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 45, 6, 'এগুলো আল্লাহর আয়াত, যা আমি আপনার কাছে আবৃত্তি করি যথাযথরূপে। অতএব, আল্লাহ ও তাঁর আয়াতের পর তারা কোন কথায় বিশ্বাস স্থাপন করবে।'),
  ('bn.bengali', 45, 7, 'প্রত্যেক মিথ্যাবাদী পাপাচারীর দুর্ভোগ।'),
  ('bn.bengali', 45, 8, 'সে আল্লাহর আয়াতসমূহ শুনে, অতঃপর অহংকারী হয়ে জেদ ধরে, যেন সে আয়াত শুনেনি। অতএব, তাকে যন্ত্রণাদায়ক শাস্তির সুসংবাদ দিন।'),
  ('bn.bengali', 45, 9, 'যখন সে আমার কোন আয়াত অবগত হয়, তখন তাকে ঠাট্টারূপে গ্রহণ করে। এদের জন্যই রয়েছে লাঞ্ছনাদায়ক শাস্তি।'),
  ('bn.bengali', 45, 10, 'তাদের সামনে রয়েছে জাহান্নাম। তারা যা উপার্জন করেছে, তা তাদের কোন কাজে আসবে না, তারা আল্লাহর পরিবর্তে যাদেরকে বন্ধুরূপে গ্রহণ করেছে তারাও নয়। তাদের জন্যে রয়েছে মহাশাস্তি।'),
  ('bn.bengali', 45, 11, 'এটা সৎপথ প্রদর্শন, আর যারা তাদের পালনকর্তার আয়াতসমূহ অস্বীকার করে, তাদের জন্যে রয়েছে কঠোর যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 45, 12, 'তিনি আল্লাহ যিনি সমুদ্রকে তোমাদের উপকারার্থে আয়ত্বাধীন করে দিয়েছেন, যাতে তাঁর আদেশক্রমে তাতে জাহাজ চলাচল করে এবং যাতে তোমরা তাঁর অনুগ্রহ তালাশ কর ও তাঁর প্রতি কৃতজ্ঞ হও।'),
  ('bn.bengali', 45, 13, 'এবং আয়ত্ত্বাধীন করে দিয়েছেন তোমাদের, যা আছে নভোমন্ডলে ও যা আছে ভূমন্ডলে; তাঁর পক্ষ থেকে। নিশ্চয় এতে চিন্তাশীল সম্প্রদায়ের জন্যে নিদর্শনাবলী রয়েছে।'),
  ('bn.bengali', 45, 14, 'মুমিনদেরকে বলুন, তারা যেন তাদেরকে ক্ষমা করে, যারা আল্লাহর সে দিনগুলো সম্পর্কে বিশ্বাস রাখে না যাতে তিনি কোন সম্প্রদায়কে কৃতকর্মের প্রতিফল দেন।'),
  ('bn.bengali', 45, 15, 'যে সৎকাজ করছে, সে নিজের কল্যাণার্থেই তা করছে, আর যে অসৎকাজ করছে, তা তার উপরই বর্তাবে। অতঃপর তোমরা তোমাদের পালনকর্তার দিকে প্রত্যাবর্তিত হবে।'),
  ('bn.bengali', 45, 16, 'আমি বনী ইসরাঈলকে কিতাব, রাজত্ব ও নবুওয়ত দান করেছিলাম এবং তাদেরকে পরিচ্ছন্ন রিযিক দিয়েছিলাম এবং বিশ্ববাসীর উপর শ্রেষ্ঠত্ব দিয়েছিলাম।'),
  ('bn.bengali', 45, 17, 'আরও দিয়েছিলাম তাদেরকে ধর্মের সুস্পষ্ট প্রমাণাদি। অতঃপর তারা জ্ঞান লাভ করার পর শুধু পারস্পরিক জেদের বশবর্তী হয়ে মতভেদ সৃষ্টি করেছে। তারা যে বিষয়ে মতভেদ করত, আপনার পালনকর্তা কেয়ামতের দিন তার ফয়সালা করে দেবেন।'),
  ('bn.bengali', 45, 18, 'এরপর আমি আপনাকে রেখেছি ধর্মের এক বিশেষ শরীয়তের উপর। অতএব, আপনি এর অনুসরণ করুন এবং অজ্ঞানদের খেয়াল-খুশীর অনুসরণ করবেন না।'),
  ('bn.bengali', 45, 19, 'আল্লাহর সামনে তারা আপনার কোন উপকারে আসবে না। যালেমরা একে অপরের বন্ধু। আর আল্লাহ পরহেযগারদের বন্ধু।'),
  ('bn.bengali', 45, 20, 'এটা মানুষের জন্যে জ্ঞানের কথা এবং বিশ্বাসী সম্প্রদায়ের জন্য হেদায়েত ও রহমত।'),
  ('bn.bengali', 45, 21, 'যারা দুস্কর্ম উপার্জন করেছে তারা কি মনে করে যে, আমি তাদেরকে সে লোকদের মত করে দেব, যারা ঈমান আনে ও সৎকর্ম করে এবং তাদের জীবন ও মুত্যু কি সমান হবে? তাদের দাবী কত মন্দ।'),
  ('bn.bengali', 45, 22, 'আল্লাহ নভোমন্ডল ও ভূ-মন্ডল যথাযথভাবে সৃষ্টি করেছেন, যাতে প্রত্যেক ব্যক্তি তার উপার্জনের ফল পায়। তাদের প্রতি যুলুম করা হবে না।'),
  ('bn.bengali', 45, 23, 'আপনি কি তার প্রতি লক্ষ্য করেছেন, যে তার খেয়াল-খুশীকে স্বীয় উপাস্য স্থির করেছে? আল্লাহ জেনে শুনে তাকে পথভ্রষ্ট করেছেন, তার কান ও অন্তরে মহর এঁটে দিয়েছেন এবং তার চোখের উপর রেখেছেন পর্দা। অতএব, আল্লাহর পর কে তাকে পথ প্রদর্শন করবে? তোমরা কি চিন্তাভাবনা কর না?'),
  ('bn.bengali', 45, 24, 'তারা বলে, আমাদের পার্থিব জীবনই তো শেষ; আমরা মরি ও বাঁচি মহাকালই আমাদেরকে ধ্বংস করে। তাদের কাছে এ ব্যাপারে কোন জ্ঞান নেই। তারা কেবল অনুমান করে কথা বলে।'),
  ('bn.bengali', 45, 25, 'তাদের কাছে যখন আমার সুস্পষ্ট আয়াতসমূহ পাঠ করা হয়, তখন একথা বলা ছাড়া তাদের কোন মুক্তিই থাকে না যে, তোমরা সত্যবাদী হলে আমাদের পূর্বপুরুষদেরকে নিয়ে আস।'),
  ('bn.bengali', 45, 26, 'আপনি বলুন, আল্লাহই তোমাদেরকে জীবন দান করেন, অতঃপর মৃত্যু দেন, অতঃপর তোমাদেরকে কেয়ামতের দিন একত্রিত করবেন, যাতে কোন সন্দেহ নেই। কিন্তু অধিকাংশ মানুষ বোঝে না।'),
  ('bn.bengali', 45, 27, 'নভোমন্ডল ও ভূ-মন্ডলের রাজত্ব আল্লাহরই। যেদিন কেয়ামত সংঘটিত হবে, সেদিন মিথ্যাপন্থীরা ক্ষতিগ্রস্ত হবে।'),
  ('bn.bengali', 45, 28, 'আপনি প্রত্যেক উম্মতকে দেখবেন নতজানু অবস্থায়। প্রত্যেক উম্মতকে তাদের আমলনামা দেখতে বলা হবে। তোমরা যা করতে, অদ্য তোমারদেরকে তার প্রতিফল দেয়া হবে।'),
  ('bn.bengali', 45, 29, 'আমার কাছে রক্ষিত এই আমলনামা তোমাদের সম্পর্কে সত্য কথা বলবে। তোমরা যা করতে আমি তা লিপিবদ্ধ করতাম।'),
  ('bn.bengali', 45, 30, 'যারা বিশ্বাস স্থাপন করেছে ও সৎকর্ম করেছে, তাদেরকে তাদের পালনকর্তা স্বীয় রহমতে দাখিল করবেন। এটাই প্রকাশ্য সাফল্য।'),
  ('bn.bengali', 45, 31, 'আর যারা কুফর করেছে, তাদেরকে জিজ্ঞাসা করা হবে, তোমাদের কাছে কি আয়াতসমূহ পঠিত হত না? কিন্তু তোমরা অহংকার করছিলে এবং তোমরা ছিলে এক অপরাধী সম্প্রদায়।'),
  ('bn.bengali', 45, 32, 'যখন বলা হত, আল্লাহর ওয়াদা সত্য এবং কেয়ামতে কোন সন্দেহ নেই, তখন তোমরা বলতে আমরা জানি না কেয়ামত কি ? আমরা কেবল ধারণাই করি এবং এ বিষয়ে আমরা নিশ্চিত নই।'),
  ('bn.bengali', 45, 33, 'তাদের মন্দ কর্ম গুলো তাদের সামনে প্রকাশ হয়ে পড়বে এবং যে আযাব নিয়ে তারা ঠাট্টা-বিদ্রুপ করত, তা তাদেরকে গ্রাস করবে।'),
  ('bn.bengali', 45, 34, 'বলা হবে, আজ আমি তোমাদেরকে ভুলে যাব, যেমন তোমরা এ দিনের সাক্ষাৎকে ভুলে গিয়েছিলে। তোমাদের আবাসস্থল জাহান্নাম এবং তোমাদের সাহায্যকারী নেই।'),
  ('bn.bengali', 45, 35, 'এটা এজন্যে যে, তোমরা আল্লাহর আয়াতসমূহকে ঠাট্টারূপে গ্রহণ করেছিলে এবং পার্থিব জীবন তোমাদেরকে প্রতারিত করেছিল। সুতরাং আজ তাদেরকে জাহান্নাম থেকে বের করা হবে না এবং তাদের কাছে তওবা চাওয়া হবে না।'),
  ('bn.bengali', 45, 36, 'অতএব, বিশ্বজগতের পালনকর্তা, ভূ-মন্ডলের পালনকর্তা ও নভোমন্ডলের পালনকর্তা আল্লাহর-ই প্রশংসা।'),
  ('bn.bengali', 45, 37, 'নভোমন্ডলে ও ভূ-মন্ডলে তাঁরই গৌরব। তিনি পরাক্রমশালী, প্রজ্ঞাময়।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 45, 1, 'Ha. Mim.'),
  ('en.pickthall', 45, 2, 'The revelation of the Scripture is from Allah, the Mighty, the Wise.'),
  ('en.pickthall', 45, 3, 'Lo! in the heavens and the earth are portents for believers.'),
  ('en.pickthall', 45, 4, 'And in your creation, and all the beasts that He scattereth in the earth, are portents for a folk whose faith is sure.'),
  ('en.pickthall', 45, 5, 'And the difference of night and day and the provision that Allah sendeth down from the sky and thereby quickeneth the earth after her death, and the ordering of the winds, are portents for a people who have sense.'),
  ('en.pickthall', 45, 6, 'These are the portents of Allah which We recite unto thee (Muhammad) with truth. Then in what fact, after Allah and His portents, will they believe?'),
  ('en.pickthall', 45, 7, 'Woe unto each sinful liar,'),
  ('en.pickthall', 45, 8, 'Who heareth the revelations of Allah recited unto him, and then continueth in pride as though he heard them not. Give him tidings of a painful doom.'),
  ('en.pickthall', 45, 9, 'And when he knoweth aught of Our revelations he maketh it a jest. For such there is a shameful doom.'),
  ('en.pickthall', 45, 10, 'Beyond them there is hell, and that which they have earned will naught avail them, nor those whom they have chosen for protecting friends beside Allah. Theirs will be an awful doom.'),
  ('en.pickthall', 45, 11, 'This is guidance. And those who disbelieve the revelations of their Lord, for them there is a painful doom of wrath.'),
  ('en.pickthall', 45, 12, 'Allah it is Who hath made the sea of service unto you that the ships may run thereon by His command, and that ye may seek of His bounty, and that haply ye may be thankful;'),
  ('en.pickthall', 45, 13, 'And hath made of service unto you whatsoever is in the heavens and whatsoever is in the earth; it is all from Him. Lo! herein verily are portents for a people who reflect.'),
  ('en.pickthall', 45, 14, 'Tell those who believe to forgive those who hope not for the days of Allah; in order that He may requite folk what they used to earn.'),
  ('en.pickthall', 45, 15, 'Whoso doeth right, it is for his soul, and whoso doeth wrong, it is against it. And afterward unto your Lord ye will be brought back.'),
  ('en.pickthall', 45, 16, 'And verily we gave the Children of Israel the Scripture and the Command and the Prophethood, and provided them with good things and favoured them above (all) peoples;'),
  ('en.pickthall', 45, 17, 'And gave them plain commandments. And they differed not until after the knowledge came unto them, through rivalry among themselves. Lo! thy Lord will judge between them on the Day of Resurrection concerning that wherein they used to differ.'),
  ('en.pickthall', 45, 18, 'And now have We set thee (O Muhammad) on a clear road of (Our) commandment; so follow it, and follow not the whims of those who know not.'),
  ('en.pickthall', 45, 19, 'Lo! they can avail thee naught against Allah. And lo! as for the wrong-doers, some of them are friends of others; and Allah is the Friend of those who ward off (evil).'),
  ('en.pickthall', 45, 20, 'This is clear indication for mankind, and a guidance and a mercy for a folk whose faith is sure.'),
  ('en.pickthall', 45, 21, 'Or do those who commit ill-deeds suppose that We shall make them as those who believe and do good works, the same in life and death? Bad is their judgment!'),
  ('en.pickthall', 45, 22, 'And Allah hath created the heavens and the earth with truth, and that every soul may be repaid what it hath earned. And they will not be wronged.'),
  ('en.pickthall', 45, 23, 'Hast thou seen him who maketh his desire his god, and Allah sendeth him astray purposely, and sealeth up his hearing and his heart, and setteth on his sight a covering? Then who will lead him after Allah (hath condemned him)? Will ye not then heed?'),
  ('en.pickthall', 45, 24, 'And they say: There is naught but our life of the world; we die and we live, and naught destroyeth us save time; when they have no knowledge whatsoever of (all) that; they do but guess.'),
  ('en.pickthall', 45, 25, 'And when Our clear revelations are recited unto them their only argument is that they say: Bring (back) our fathers. then, if ye are truthful.'),
  ('en.pickthall', 45, 26, 'Say (unto them, O Muhammad): Allah giveth life to you, then causeth you to die, then gathereth you unto the Day of Resurrection whereof there is no doubt. But most of mankind know not.'),
  ('en.pickthall', 45, 27, 'And unto Allah belongeth the Sovereignty of the heavens and the earth; and on the day when the Hour riseth, on that day those who follow falsehood will be lost.'),
  ('en.pickthall', 45, 28, 'And thou wilt see each nation crouching, each nation summoned to its record. (And it will be said unto them): This day ye are requited what ye used to do.'),
  ('en.pickthall', 45, 29, 'This Our Book pronounceth against you with truth. Lo! We have caused (all) that ye did to be recorded.'),
  ('en.pickthall', 45, 30, 'Then, as for those who believed and did good works, their Lord will bring them in unto His mercy. That is the evident triumph.'),
  ('en.pickthall', 45, 31, 'And as for those who disbelieved (it will be said unto them): Were not Our revelations recited unto you? But ye were scornful and became a guilty folk.'),
  ('en.pickthall', 45, 32, 'And when it was said: Lo! Allah\'s promise is the truth, and there is no doubt of the Hour\'s coming, ye said: We know not what the Hour is. We deem it naught but a conjecture, and we are by no means convinced.'),
  ('en.pickthall', 45, 33, 'And the evils of what they did will appear unto them, and that which they used to deride will befall them.'),
  ('en.pickthall', 45, 34, 'And it will be said: This day We forget you, even as ye forgot the meeting of this your day; and your habitation is the Fire, and there is none to help you.'),
  ('en.pickthall', 45, 35, 'This, forasmuch as ye made the revelations of Allah a jest, and the life of the world beguiled you. Therefor this day they come not forth from thence, nor can they make amends.'),
  ('en.pickthall', 45, 36, 'Then praise be to Allah, Lord of the heavens and Lord of the earth, the Lord of the Worlds.'),
  ('en.pickthall', 45, 37, 'And unto Him (alone) belongeth Majesty in the heavens and the earth, and He is the Mighty, the Wise.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 45, 1, 'Ha-Mim.'),
  ('en.yusufali', 45, 2, 'The revelation of the Book is from Allah the Exalted in Power, Full of Wisdom.'),
  ('en.yusufali', 45, 3, 'Verily in the heavens and the earth, are Signs for those who believe.'),
  ('en.yusufali', 45, 4, 'And in the creation of yourselves and the fact that animals are scattered (through the earth), are Signs for those of assured Faith.'),
  ('en.yusufali', 45, 5, 'And in the alternation of Night and Day, and the fact that Allah sends down Sustenance from the sky, and revives therewith the earth after its death, and in the change of the winds,- are Signs for those that are wise.'),
  ('en.yusufali', 45, 6, 'Such are the Signs of Allah, which We rehearse to thee in Truth; then in what exposition will they believe after (rejecting) Allah and His Signs?'),
  ('en.yusufali', 45, 7, 'Woe to each sinful dealer in Falsehoods:'),
  ('en.yusufali', 45, 8, 'He hears the Signs of Allah rehearsed to him, yet is obstinate and lofty, as if he had not heard them: then announce to him a Penalty Grievous!'),
  ('en.yusufali', 45, 9, 'And when he learns something of Our Signs, he takes them in jest: for such there will be a humiliating Penalty.'),
  ('en.yusufali', 45, 10, 'In front of them is Hell: and of no profit to them is anything they may have earned, nor any protectors they may have taken to themselves besides Allah: for them is a tremendous Penalty.'),
  ('en.yusufali', 45, 11, 'This is (true) Guidance and for those who reject the Signs of their Lord, is a grievous Penalty of abomination.'),
  ('en.yusufali', 45, 12, 'It is Allah Who has subjected the sea to you, that ships may sail through it by His command, that ye may seek of his Bounty, and that ye may be grateful.'),
  ('en.yusufali', 45, 13, 'And He has subjected to you, as from Him, all that is in the heavens and on earth: Behold, in that are Signs indeed for those who reflect.'),
  ('en.yusufali', 45, 14, 'Tell those who believe, to forgive those who do not look forward to the Days of Allah: It is for Him to recompense (for good or ill) each People according to what they have earned.'),
  ('en.yusufali', 45, 15, 'If any one does a righteous deed, it ensures to the benefit of his own soul; if he does evil, it works against (his own soul). In the end will ye (all) be brought back to your Lord.'),
  ('en.yusufali', 45, 16, 'We did aforetime grant to the Children of Israel the Book the Power of Command, and Prophethood; We gave them, for Sustenance, things good and pure; and We favoured them above the nations.'),
  ('en.yusufali', 45, 17, 'And We granted them Clear Signs in affairs (of Religion): it was only after knowledge had been granted to them that they fell into schisms, through insolent envy among themselves. Verily thy Lord will judge between them on the Day of Judgment as to those matters in which they set up differences.'),
  ('en.yusufali', 45, 18, 'Then We put thee on the (right) Way of Religion: so follow thou that (Way), and follow not the desires of those who know not.'),
  ('en.yusufali', 45, 19, 'They will be of no use to thee in the sight of Allah: it is only Wrong-doers (that stand as) protectors, one to another: but Allah is the Protector of the Righteous.'),
  ('en.yusufali', 45, 20, 'These are clear evidences to men and a Guidance and Mercy to those of assured Faith.'),
  ('en.yusufali', 45, 21, 'What! Do those who seek after evil ways think that We shall hold them equal with those who believe and do righteous deeds,- that equal will be their life and their death? Ill is the judgment that they make.'),
  ('en.yusufali', 45, 22, 'Allah created the heavens and the earth for just ends, and in order that each soul may find the recompense of what it has earned, and none of them be wronged.'),
  ('en.yusufali', 45, 23, 'Then seest thou such a one as takes as his god his own vain desire? Allah has, knowing (him as such), left him astray, and sealed his hearing and his heart (and understanding), and put a cover on his sight. Who, then, will guide him after Allah (has withdrawn Guidance)? Will ye not then receive admonition?'),
  ('en.yusufali', 45, 24, 'And they say: "What is there but our life in this world? We shall die and we live, and nothing but time can destroy us." But of that they have no knowledge: they merely conjecture:'),
  ('en.yusufali', 45, 25, 'And when Our Clear Signs are rehearsed to them their argument is nothing but this: They say, "Bring (back) our forefathers, if what ye say is true!"'),
  ('en.yusufali', 45, 26, 'Say: "It is Allah Who gives you life, then gives you death; then He will gather you together for the Day of Judgment about which there is no doubt": But most men do not understand.'),
  ('en.yusufali', 45, 27, 'To Allah belongs the dominion of the heavens and the earth, and the Day that the Hour of Judgment is established,- that Day will the dealers in Falsehood perish!'),
  ('en.yusufali', 45, 28, 'And thou wilt see every sect bowing the knee: Every sect will be called to its Record: "This Day shall ye be recompensed for all that ye did!'),
  ('en.yusufali', 45, 29, '"This Our Record speaks about you with truth: For We were wont to put on Record all that ye did."'),
  ('en.yusufali', 45, 30, 'Then, as to those who believed and did righteous deeds, their Lord will admit them to His Mercy that will be the achievement for all to see.'),
  ('en.yusufali', 45, 31, 'But as to those who rejected Allah, (to them will be said): "Were not Our Signs rehearsed to you? But ye were arrogant, and were a people given to sin!'),
  ('en.yusufali', 45, 32, '"And when it was said that the promise of Allah was true, and that the Hour- there was no doubt about its (coming), ye used to say, \'We know not what is the hour: we only think it is an idea, and we have no firm assurance.\'"'),
  ('en.yusufali', 45, 33, 'Then will appear to them the evil (fruits) of what they did, and they will be completely encircled by that which they used to mock at!'),
  ('en.yusufali', 45, 34, 'It will also be said: "This Day We will forget you as ye forgot the meeting of this Day of yours! and your abode is the Fire, and no helpers have ye!'),
  ('en.yusufali', 45, 35, '"This, because ye used to take the Signs of Allah in jest, and the life of the world deceived you:" (From) that Day, therefore, they shall not be taken out thence, nor shall they be received into Grace.'),
  ('en.yusufali', 45, 36, 'Then Praise be to Allah, Lord of the heavens and Lord of the earth,- Lord and Cherisher of all the Worlds!'),
  ('en.yusufali', 45, 37, 'To Him be glory throughout the heavens and the earth: and He is Exalted in Power, Full of Wisdom!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 45, 1, 'Haa-Meeem'),
  ('en.transliteration', 45, 2, 'Tanzeelul Kitaabi minal laahil \'Azeezil Hakeem'),
  ('en.transliteration', 45, 3, 'Innaa fis samaawaati wal ardi la Aayaatil lilmu\'mineen'),
  ('en.transliteration', 45, 4, 'Wa fee khalaqikum wa maa yabussu min daaabbatin Aayaatul liqawminy-yooqinoon'),
  ('en.transliteration', 45, 5, 'Wakhtilaafil laili wannahaari wa maaa anzalal laahu minas samaaa\'i mir rizqin fa ahyaa bihil arda ba\'da mawtihaa wa tasreefir riyaahi Aayaatul liqawminy ya\'qiloon'),
  ('en.transliteration', 45, 6, 'Tilka Aayatul laahi natloohaa \'alika bilhaqq, fabiayyi hadeesim ba\'dal laahi wa Aayaatihee yu\'minoon'),
  ('en.transliteration', 45, 7, 'Wailul likulli affaakin aseem'),
  ('en.transliteration', 45, 8, 'Yasma\'u Aayaatil laahi tutlaa \'alaihi summa yusirru mustakbiran ka-al lam yasma\'haa fabashshirhu bi\'azaabin aleem'),
  ('en.transliteration', 45, 9, 'Wa izaa \'alima min Aayaatinaa shai\'anit takhazahaa huzuwaa; ulaaa\'ika lahum \'azaabum muheen'),
  ('en.transliteration', 45, 10, 'Minw waraaa\'ihim Jahannamu wa laa yughnee \'anhum maa kasaboo shai\'anw wa laa mat takhazoo min doonil laahi awliyaaa\'a wa lahum \'azaabun \'azeem'),
  ('en.transliteration', 45, 11, 'Haazaa hudanw wal lazeena kafaroo bi aayaati Rabbihim lahum \'azaabum mir rijzin aleem'),
  ('en.transliteration', 45, 12, 'Allaahul lazee sahkhara lakumul bahra litajriyal fulku feehi bi amrihee wa litabtaghoo min fadlihee wa la\'allakum tashkuroon'),
  ('en.transliteration', 45, 13, 'Wa sakhkhara lakum maa fis samaawaati wa maa fil ardi jamee\'am minh; inna feezaalika la Aayaatil liqawminy yatafakkaroon'),
  ('en.transliteration', 45, 14, 'Qul lillazeena aamanoo yaghfiroo lillazeena laa yarjoona ayyaamal laahi liyajziya qawmam bimaa kaanoo yaksiboon'),
  ('en.transliteration', 45, 15, 'Maa \'amila saalihan falinafsihee wa man asaaa\'a fa\'alaihaa summa ilaa Rabbikum turja\'oon'),
  ('en.transliteration', 45, 16, 'Wa laqad aatainaa Baneee Israaa\'eelal Kitaaba walhukma wan Nubuwwata wa razaqnaahum minat taiyibaati wa faddalnaahum;alal \'aalameen'),
  ('en.transliteration', 45, 17, 'Wa aatainaahum baiyinaatim minal amri famakh talafooo illaa mim ba\'di maa jaaa\'ahumul \'ilmu baghyam bainahum; inna Rabbaka yaqdee bainahum Yawmal Qiyaamati feemaa kaanoo feehi yakhtalifoon'),
  ('en.transliteration', 45, 18, 'Summa ja\'alnaaka \'alaa sharee\'atim minal amri fattabi\'haa wa laa tattabi\'ahwaaa\'al-lazeena laa ya\'lamoon'),
  ('en.transliteration', 45, 19, 'Innahum lany yughnoo \'anka minal laahi shai\'aa; wa innaz zaalimeena ba\'duhum awliyaaa\'u ba\'dinw wallaahu waliyyul muttaqeen'),
  ('en.transliteration', 45, 20, 'Haazaa basaaa\'iru linnaasi wa hudanw wa rahmatul liqawminy yooqinoon'),
  ('en.transliteration', 45, 21, 'Am hasibal lazeenaj tarahus saiyiaati an naj\'alahum kallazeena aamanoo wa \'amilu saalihaati sawaaa\'am mahyaahum wa mamaatuhum; saaa\'a maa yahkumoon'),
  ('en.transliteration', 45, 22, 'Wa khalaqal laahus samaawaati wal arda bilhaqqi wa litujzaa kullu nafsim bimaa kasabat wa hum laa yuzlamoon'),
  ('en.transliteration', 45, 23, 'Afara\'ayta manit takhaza ilaahahoo hawaahu wa adal lahul laahu \'alaa \'ilminw wa khatama \'alaa sam\'ihee wa qalbihee wa ja\'ala \'alaa basarihee ghishaawatan famany yahdeehi mim ba\'dil laah; afalaa tazakkaroon'),
  ('en.transliteration', 45, 24, 'Wa qaaloo maa hiya illaa hayaatunad dunyaa namootu wa nahyaa wa maa yuhlikunaaa illad dahr; wa maa lahum bizaalika min \'ilmin in hum illaayazunnoon'),
  ('en.transliteration', 45, 25, 'Wa izaa tutlaa \'alaihim aayaatuna baiyinaatim maa kaana hujjatahum illaaa an qaalu\'too bi aabaaa\'inaaa in kuntum saadiqeen'),
  ('en.transliteration', 45, 26, 'Qulil laahu yuhyeekum summa yumeetukum summa yajma\'ukum ilaa Yawmil Qiyaamati laa raiba feehi wa laakinna aksaran naasi laa ya\'lamoon'),
  ('en.transliteration', 45, 27, 'Wa lillaahi mulkus samaawaati wal ard; wa Yawma taqoomus Saa\'atu Yawma \'iziny yakhsarul mubtiloon'),
  ('en.transliteration', 45, 28, 'Wa taraa kulla ummatin jaasiyah; kullu ummatin tud\'aaa ilaa kitaabihaa al Yawma tujzawna maa kuntum ta\'maloon'),
  ('en.transliteration', 45, 29, 'Haazaa kitaabunaa yantiqu \'alaikum bilhaqq; innaa kunnaa nastansikhu maa kuntum ta\'maloon'),
  ('en.transliteration', 45, 30, 'Fa ammal lazeena aamaanoo wa \'amilus saalihaati fayudkhiluhum Rabbuhum fee rahmatih; zaalika huwal fawzul mubeen'),
  ('en.transliteration', 45, 31, 'Wa ammal lazeena kafarooo afalam takun Aayaatee tutlaa \'alaikum fastakbartum wa kuntum qawmam mujrimeen'),
  ('en.transliteration', 45, 32, 'Wa izaa qeela inna wa\'dallaahi haqqunw was Saa\'atu laa raiba feehaa qultum maa nadree mas Saa\'atu in nazunnu illaa zannanw wa maa nahnu bimustaiqineen'),
  ('en.transliteration', 45, 33, 'Wa badaa lahum saiyiaatu maa \'amiloo wa haaqa bihim maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 45, 34, 'Wa qeelal yawma nansaakum kamaa naseetum liqaaa\'a yawmikum haazaa wa maawaakumun Naaru wa maa lakum min naasireen'),
  ('en.transliteration', 45, 35, 'Zaalikum bi annakumut takhaztum aayaatil laahi huzuwanw wa gharratkumul hayaatud dunyaa; fal yawma laa yukhrajoona minhaa wa laahum yusta\'taboon'),
  ('en.transliteration', 45, 36, 'Falillaahil hamdu Rabbis samaawaati wa Rabbil ardi Rabbil-\'aalameen'),
  ('en.transliteration', 45, 37, 'Wa lahul kibriyaaa\'u fissamaawaati wal ardi wa Huwal \'Azeezul Hakeem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 45, 1, 'حمۤ'),
  ('ur.ahmedali', 45, 2, 'یہ کتاب الله زبردست حکمت والے کی طرف سے نازل ہوئی ہے'),
  ('ur.ahmedali', 45, 3, 'بے شک آسمانوں اور زمین میں ایمانداروں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 45, 4, 'اور (نیز) تمہارے پیدا کرنے میں اور جانوروں کے پھیلانے میں یقین والوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 45, 5, 'اور (نیز) رات اور دن کے بدل کر آنے میں اور اس میں جو الله نے آسمان سے رزق (پانی) نازل کیا پھر اس کے ذریعے سے زمین کو اس کے مر جانے کے بعد زندہ کیا اور ہواؤں کے بدل کر لانے میں عقل مندوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 45, 6, 'یہ الله کی آیات ہیں جو ہم آپ کو بالکل سچی پڑھ کر سناتے ہیں پس الله اور اس کی آیات کے بعد وہ کس بات پر ایمان لائیں گے'),
  ('ur.ahmedali', 45, 7, 'ہر سخت جھوٹے گناہگار کے لیے تباہی ہے'),
  ('ur.ahmedali', 45, 8, 'جو آیات الہیٰ سنتا ہے جو اس پر پڑھی جاتی ہیں پھر نا حق تکبر کی وجہ سے اصرار کرتا ہے گویاکہ اس نے سنا ہی نہیں پس اسے دردناک عذاب کی خوشخبری دے دو'),
  ('ur.ahmedali', 45, 9, 'اورجب ہماری آیتوں میں سے کسی کو سن لیتاہے تو اس کی ہنسی اڑاتا ہے ایسوں کے لیے ذلت کا عذاب ہے'),
  ('ur.ahmedali', 45, 10, 'ان کے سامنے جہنم ہے اور جو کچھ انہوں نے کمایا تھا ان کے کچھ بھی کام نہ آئے گا اور نہ وہ معبود کام آئيں گے جنہیں الله کے سوا حمایتی بنا رکھا تھا اور ان کے لیے بڑاعذاب ہے'),
  ('ur.ahmedali', 45, 11, 'یہ (قرآن) تو ہدایت ہے اور جو اپنے رب کی آیتوں کے منکر ہیں ان کے لیے سخت دردناک عذاب ہے'),
  ('ur.ahmedali', 45, 12, 'الله ہی ہے جس نے تمہارے لیے سمندر کو تابع کر دیا تاکہ ا س میں اس کے حکم سے جہاز چلیں اورتاکہ تم اس کا فضل تلاش کرو اور تاکہ تم اس کا شکر کرو'),
  ('ur.ahmedali', 45, 13, 'اور اس نے آسمانوں اور زمین کی سب چیزوں کو اپنے فضل سے تمہارے کام پر لگا دیا ہے بے شک اس میں فکر کرنے والوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 45, 14, 'ان سے کہہ دو جو ایمان لائے کہ انہیں معاف کر دیں ایام الہیٰ (عذاب) کی امید نہیں رکھتے تاکہ وہ ایک قوم کو بدلہ دے اس کا جو وہ کرتے رہے'),
  ('ur.ahmedali', 45, 15, 'جو کوئی نیک کام کرتا ہے وہ اپنے ہی لیے کرتا ہے اورجو کوئی برائی کرتا ہے تو اپنے سر پر وبال لیتا ہے پھر تم اپنے رب کی طرف لوٹائے جاؤ گے'),
  ('ur.ahmedali', 45, 16, 'اور بے شک ہم نے بنی اسرائیل کو کتاب اورحکومت اور نبوت دی تھی اور ہم نے پاکیزہ چیزوں سے روزی دی اور ہم نے انہیں جہان والوں پر بزرگی دی'),
  ('ur.ahmedali', 45, 17, 'اور انہیں دین کے کھلے کھلے احکام بھی دیے پھر انہوں نے اختلاف کیا تو علم آنے کے بعد صرف آپس کی ضد سے بے شک آپ کا رب قیامت کے دن ان میں فیصلہ کرے گا جس چیز میں وہ باہم اختلاف کیا کرتے تھے'),
  ('ur.ahmedali', 45, 18, 'پھر ہم نے آپ کو دین کے ایک طریقہ پر مقرر کر دیا پس آپ اسی کی پیروی کیجیئے اور ان کی خواہشوں کی پیروی نہ کیجیئے جو علم نہیں رکھتے'),
  ('ur.ahmedali', 45, 19, 'کیوں کہ وہ الله کے سامنے آپ کے کچھ بھی کام نہ آئیں گے اور بے شک ظالم ایک دوسرے کے دوست ہیں اور الله ہی پرہیز گاروں کا دوست ہے'),
  ('ur.ahmedali', 45, 20, 'یہ قرآن لوگوں کے لیے بصیرت اورہدایت ہے اور یقین کرنے والو ں کے لیے رحمت ہے'),
  ('ur.ahmedali', 45, 21, 'کیا گناہ کرنے والوں نے یہ سمجھ لیا ہے کہ ہم ان کو ایمانداروں نیک کام کرنے والوں کے برابر کر دیں گے ان کا جینا اور مرنا برابر ہے وہ بہت ہی برا فیصلہ کرتے ہیں'),
  ('ur.ahmedali', 45, 22, 'اور الله نے آسمانوں اور زمین کو جسے چاہئیں بنایا ہے اور تاکہ ہر نفس کو اس کا بدلہ دیا جائے جو اس نے کمایا ہے اور ان پر کوئی ظلم نہ ہوگا'),
  ('ur.ahmedali', 45, 23, 'بھلا آپ نے اس کو بھی دیکھا جو اپنی خواہش کا بندہ بن گیا اور الله نے باوجود سمجھ کے اسے گمراہ کر دیا اور اس کے کان اور دل پر مہر کر دی اور اس کی آنکھوں پر پردہ ڈال دیا پھر الله کے بعد اسے کون ہدایت کر سکتا ہے پھر تم کیوں نہیں سمجھتے'),
  ('ur.ahmedali', 45, 24, 'اور کہتے ہیں ہمارا یہی دنیا کا جینا ہے ہم مرتے ہیں اور جیتے ہیں اور زمانہ ہی ہمیں ہلاک کرتا ہے حالانکہ انہیں اس کی کچھ بھی حقیقت معلوم نہیں محض اٹکلیں دوڑاتے ہیں'),
  ('ur.ahmedali', 45, 25, 'اور جب انہیں ہماری واضح آیتیں پڑھ کر سنائی جاتی ہیں تو سوائے اس کے ان کی اور کوئی دلیل نہیں ہوتی کہتے ہیں ہمارے باپ دادا کو لے آؤ اگر تم سچے ہو'),
  ('ur.ahmedali', 45, 26, 'کہہ دو الله ہی تمہیں زندہ کرتا ہے پھر تمہیں مارتا ہے پھر وہی تم سب کو قیامت میں جمع کرے گا جس میں کوئی شک نہیں لیکن اکثر آدمی نہیں جانتے'),
  ('ur.ahmedali', 45, 27, 'اور آسمانوں اور زمین کی بادشاہی الله ہی کی ہے اور جس دن قیامت قائم ہو گی اس دن جھٹلانے والے نقصان اٹھائیں گے'),
  ('ur.ahmedali', 45, 28, 'اور آپ ہر ایک جماعت کو گھٹنے ٹیکے ہوئے دیکھیں گے ہر ایک جماعت اپنے نامہٴ اعمال کی طرف بلائی جائے گی (کہا جائے گا) آج تمہیں تمہارے اعمال کا بدلہ دیا جائے گا'),
  ('ur.ahmedali', 45, 29, 'یہ ہمارا دفتر تم پر سچ سچ بول رہا ہے کیونکہ جو کچھ تم کیا کرتے تھے اسے ہم لکھ لیا کرتے تھے'),
  ('ur.ahmedali', 45, 30, 'پس جو لوگ ایمان لائے اورانہوں نے نیک کام کیے انہیں ان کا پروردگار اپنی رحمت میں داخل کرے گا یہ صریح کامیابی ہے'),
  ('ur.ahmedali', 45, 31, 'اور جنہوں نے کفر کیا (انہیں کہا جائے گا) کیا تمہیں ہماری آیتیں نہیں سنائی جاتی تھیں پھر تم نے غرور کیا اور تم نافرمان لوگ تھے'),
  ('ur.ahmedali', 45, 32, 'اور جب کہا جاتا تھا کہ الله کا وعدہ سچا ہے اور قیامت میں کوئی شک نہیں تو تم کہتے تھے ہم نہیں جانتے قیامت کیا چیز ہے ہم تو اس کو محض خیالی بات جانتے ہیں اور ہمیں یقین نہیں'),
  ('ur.ahmedali', 45, 33, 'اور ان پر ان کےاعمال کی برائی ظاہر ہو جائے گی اور ان پر وہ آفت آ پڑے گی جس سے وہ ٹھٹھا کرتے تھے'),
  ('ur.ahmedali', 45, 34, 'اور کہا جائے گا آج ہم تمہیں فراموش کر دیں گے جیسا تم نے اپنے اس دن کے ملنے کو فراموش کر دیا تھا اور تمہارا ٹھکانہ دوزخ ہے اور تمہارا کوئی مددگارنہیں'),
  ('ur.ahmedali', 45, 35, 'یہ اس لیے کہ تم الله کی آیتوں کی ہنسی اڑایا کرتے تھے اور تمہیں دنیا کی زندگی نے دھوکے میں ڈال دیا تھا پس آج وہ اس سے نہ نکالے جائیں گے اور نہ ان سے توبہ طلب کی جائے گی'),
  ('ur.ahmedali', 45, 36, 'پس سب تعریف الله ہی کے لیے ہے جو آسمانوں کا رب اور زمین کا رب سارے جہانوں کا رب ہے'),
  ('ur.ahmedali', 45, 37, 'اور آسمانوں اور زمین میں اسی کی عزت ہے اور وہی زبردست حکمت والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 45, 1, 'Ha, Mim.'),
  ('tr.diyanet', 45, 2, 'Kitap\'ın indirilmesi, güçlü ve Hakim olan Allah katındandır.'),
  ('tr.diyanet', 45, 3, 'Göklerde ve yerde inananlara nice dersler vardır.'),
  ('tr.diyanet', 45, 4, 'Ey insanlar! Sizin yaratılmanızda ve canlıların yeryüzünde yayılmasında, kesin olarak inanan kimseler için ibretler vardır.'),
  ('tr.diyanet', 45, 5, 'Gece ile gündüzün birbiri ardından gelmesinde, gökten, Allah\'ın rızık vermek için yağmur indirip, yeri onunla, ölümünden sonra diriltmesinde, rüzgarları yönetmesinde, akleden kimseler için dersler vardır.'),
  ('tr.diyanet', 45, 6, 'İşte sana gerçek olarak anlattığımız bunlar, Allah\'ın varlığının delilleridir. Artık Allah\'tan ve O\'nun delillerinden sonra hangi söze inanırlar?'),
  ('tr.diyanet', 45, 7, 'Kendine okunan Allah\'ın ayetlerini dinleyip, sonra, onları hiç duymamış gibi büyüklük taslamakta direnen, yalancı ve günahkar kişinin vay haline! Ona can yakıcı bir azap müjdele.'),
  ('tr.diyanet', 45, 8, 'Kendine okunan Allah\'ın ayetlerini dinleyip, sonra, onları hiç duymamış gibi büyüklük taslamakta direnen, yalancı ve günahkar kişinin vay haline! Ona can yakıcı bir azap müjdele.'),
  ('tr.diyanet', 45, 9, 'Ayetlerimizden bir şey öğrendiğinde onu alaya alır. İşte bunlara alçaltıcı bir azap ve ardından da cehennem vardır. Kazandıkları şeyler de, Allah\'ı bırakıp edindikleri dostlar da onlara bir fayda vermez. Büyük azap onlaradır.'),
  ('tr.diyanet', 45, 10, 'Ayetlerimizden bir şey öğrendiğinde onu alaya alır. İşte bunlara alçaltıcı bir azap ve ardından da cehennem vardır. Kazandıkları şeyler de, Allah\'ı bırakıp edindikleri dostlar da onlara bir fayda vermez. Büyük azap onlaradır.'),
  ('tr.diyanet', 45, 11, 'İşte bu Kuran doğruluk rehberidir. Rablerinin ayetlerini inkar edenlere, onlara, tiksindiren, can yakan bir azap vardır.'),
  ('tr.diyanet', 45, 12, 'Emri gereğince denizde yüzmek üzere gemileri, lütfedip verdiği rızkı aramanız için denizi buyruğunuz altına veren Allah\'tır, belki artık şükredersiniz.'),
  ('tr.diyanet', 45, 13, 'Göklerde olanları, yerde olanları, hepsini sizin buyruğunuz altına vermiştir. Doğrusu bunlarda, düşünen kimseler için dersler vardır.'),
  ('tr.diyanet', 45, 14, 'İnanmışlara de ki: Allah\'ın bir milleti yaptıklarına karşılık cezalandıracağı günlerin geleceğini ummayanları şimdilik bağışlasınlar.'),
  ('tr.diyanet', 45, 15, 'Kim yararlı iş işlerse kendinedir; kim kötülük yaparsa kendi aleyhinedir. Sonra Rabbinize döndürülürsünüz.'),
  ('tr.diyanet', 45, 16, 'And olsun ki Biz, İsrailoğullarına Kitap, hüküm ve peygamberlik verdik; onları temiz şeylerle rızıklandırdık; onları dünyalara üstün kıldık.'),
  ('tr.diyanet', 45, 17, 'Din konusunda, onlara belgeler verdik; ancak, kendilerine ilim geldikten sonra birbirini çekememezlikten ayrılığa düştüler. Rabbin kıyamet günü, ayrılığa düştükleri şeyler hakkında şüphesiz aralarında hükmedecektir.'),
  ('tr.diyanet', 45, 18, 'Sonra seni de din konusunda bir şeriat sahibi kıldık, ona uy; bilmeyenlerin heveslerine uyma.'),
  ('tr.diyanet', 45, 19, 'Şüphesiz onlar, seni Allah\'tan müstağni kılamazlar. Doğrusu zalimler birbirlerinin dostudurlar. Sakınanların dostu ise Allah\'tır.'),
  ('tr.diyanet', 45, 20, 'Bu Kuran, insanlar için açık belgeler; kesin olarak inanan millet için doğruluk rehberi ve rahmettir.'),
  ('tr.diyanet', 45, 21, 'Yoksa, kötülük işleyen kimseler, ölümlerinde ve diriliklerinde kendilerini, inanıp yararlı iş işleyen kimseler ile bir mi tutacağımızı sandılar? Ne kötü hüküm veriyorlar!'),
  ('tr.diyanet', 45, 22, 'Allah gökleri ve yeri gerçekle yaratmıştır; her cana, kazandığının karşılığı verilir, onlara zulmedilmez.'),
  ('tr.diyanet', 45, 23, 'Heva ve hevesini tanrı edinen, bilgisi olduğu halde Allah\'ın şaşırttığı, kulağını ve kalbini mühürlediği, gözünü perdelediği kimseyi gördün mü? Onu Allah\'tan başka kim doğru yola eriştirebilir? Ey insanlar! Anlamaz mısınız?'),
  ('tr.diyanet', 45, 24, '"Hayat, ancak bu dünyadaki hayatımızdır. Ölürüz ve yaşarız; bizi ancak zamanın geçişi yokluğa sürükler" derler. Onların bu hususta bir bilgisi yoktur, sadece böyle sanırlar.'),
  ('tr.diyanet', 45, 25, 'Ayetlerimiz onlara açıkça okunduğu zaman, delilleri yalnızca: "Doğru sözlü iseniz babalarımızı getirin bakalım" demek olur.'),
  ('tr.diyanet', 45, 26, 'De ki: "Sizi Allah diriltir, sonra öldürür, sonra sizi şüphe götürmeyen kıyamet gününde toplar. Ama insanların çoğu bilmezler."'),
  ('tr.diyanet', 45, 27, 'Göklerin ve yerin hükümranlığı Allah\'ındır. Kıyamet kopacağı gün, işte o gün, batıl sözlere uymuş olanlar hüsranda kalırlar.'),
  ('tr.diyanet', 45, 28, 'Her ümmeti diz üstü çökmüş olarak görürsün. Her ümmet kitabına çağrılır. Onlara denir ki: "Bugün, size işlediğinizin karşılığı verilecektir."'),
  ('tr.diyanet', 45, 29, '"Bu kitabımız gerçekten sizin aleyhinize konuşur. Biz yaptıklarınızı şüphesiz bir bir kaydediyorduk."'),
  ('tr.diyanet', 45, 30, 'İnanıp, yararlı iş işleyenlere gelince, Rableri onları rahmetine garkeder. İşte bu, apaçık kurtuluştur.'),
  ('tr.diyanet', 45, 31, 'Ama, inkar eden kimselere denir ki: "Ayetlerim size okunmuş, siz de büyüklenip suçlu bir millet olmuştunuz değil mi?"'),
  ('tr.diyanet', 45, 32, '"Doğrusu Allah\'ın verdiği söz gerçektir, kıyamet saati şüphe götürmez" dendiği zaman: "Kıyametin ne olduğunu bilmiyoruz, yalnız yoktur sanıyoruz, buna dair kesin bir bilgi elde etmiş değiliz" derdiniz.'),
  ('tr.diyanet', 45, 33, 'İşledikleri kötülükler kendilerine belli oldu ve onları, alaya aldıkları şeyler kuşatıp mahvetti.'),
  ('tr.diyanet', 45, 34, 'Onlara denir ki: "Bugüne kavuşacağınızı unuttuğunuz gibi Biz de sizi unuttuk; varacağınız yer ateştir, yardımcılarınız da yoktur."'),
  ('tr.diyanet', 45, 35, '"Bu, Allah\'ın ayetlerini alaya almanızdan ve dünya hayatının sizi aldatmış olmasından ötürüdür." O gün, ne oradan çıkarılırlar ve ne de özürleri dinlenir.'),
  ('tr.diyanet', 45, 36, 'Övülmek, göklerin Rabbi, yerin Rabbi ve alemlerin Rabbi olan Allah içindir.'),
  ('tr.diyanet', 45, 37, 'Göklerde ve yerde azamet O\'nundur, O, güçlüdür, Hakim\'dir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 45, 1, 'Haa Miim'),
  ('id.indonesian', 45, 2, 'Kitab (ini) diturunkan dari Allah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 45, 3, 'Sesungguhnya pada langit dan bumi benar-benar terdapat tanda-tanda (kekuasaan Allah) untuk orang-orang yang beriman.'),
  ('id.indonesian', 45, 4, 'Dan pada penciptakan kamu dan pada binatang-binatang yang melata yang bertebaran (di muka bumi) terdapat tanda-tanda (kekuasaan Allah) untuk kaum yang meyakini,'),
  ('id.indonesian', 45, 5, 'dan pada pergantian malam dan siang dan hujan yang diturunkan Allah dari langit lalu dihidupkan-Nya dengan air hujan itu bumi sesudah matinya; dan pada perkisaran angin terdapat tanda-tanda (kekuasaan Allah) bagi kaum yang berakal.'),
  ('id.indonesian', 45, 6, 'Itulah ayat-ayat Allah yang Kami membacakannya kepadamu dengan sebenarnya; maka dengan perkataan manakah lagi mereka akan beriman sesudah (kalam) Allah dan keterangan-keterangan-Nya.'),
  ('id.indonesian', 45, 7, 'Kecelakaan besarlah bagi tiap-tiap orang yang banyak berdusta lagi banyak berdosa,'),
  ('id.indonesian', 45, 8, 'dia mendengar ayat-ayat Allah dibacakan kepadanya kemudian dia tetap menyombongkan diri seakan-akan dia tidak mendengarnya. Maka beri khabar gembiralah dia dengan azab yang pedih.'),
  ('id.indonesian', 45, 9, 'Dan apabila dia mengetahui barang sedikit tentang ayat-ayat Kami, maka ayat-ayat itu dijadikan olok-olok. Merekalah yang memperoleh azab yang menghinakan.'),
  ('id.indonesian', 45, 10, 'Di hadapan mereka neraka Jahannam dan tidak akan berguna bagi mereka sedikitpun apa yang telah mereka kerjakan, dan tidak pula berguna apa yang mereka jadikan sebagai sembahan-sembahan (mereka) dari selain Allah. Dan bagi mereka azab yang besar.'),
  ('id.indonesian', 45, 11, 'Ini (Al Quran) adalah petunjuk. Dan orang-orang yang kafir kepada ayat-ayat Tuhannya bagi mereka azab yaitu siksaan yang sangat pedih.'),
  ('id.indonesian', 45, 12, 'Allah-lah yang menundukkan lautan untukmu supaya kapal-kapal dapat berlayar padanya dengan seizin-Nya dan supaya kamu dapat mencari karunia -Nya dan mudah-mudahan kamu bersyukur.'),
  ('id.indonesian', 45, 13, 'Dan Dia telah menundukkan untukmu apa yang di langit dan apa yang di bumi semuanya, (sebagai rahmat) daripada-Nya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi kaum yang berfikir.'),
  ('id.indonesian', 45, 14, 'Katakanlah kepada orang-orang yang beriman hendaklah mereka memaafkan orang-orang yang tiada takut hari-hari Allah karena Dia akan membalas sesuatu kaum terhadap apa yang telah mereka kerjakan.'),
  ('id.indonesian', 45, 15, 'Barangsiapa yang mengerjakan amal saleh, maka itu adalah untuk dirinya sendiri, dan barangsiapa yang mengerjakan kejahatan, maka itu akan menimpa dirinya sendiri, kemudian kepada Tuhanmulah kamu dikembalikan.'),
  ('id.indonesian', 45, 16, 'Dan sesungguhnya telah Kami berikan kepada Bani Israil Al Kitab (Taurat), kekuasaan dan kenabian dan Kami berikan kepada mereka rezeki-rezeki yang baik dan Kami lebihkan mereka atas bangsa-bangsa (pada masanya).'),
  ('id.indonesian', 45, 17, 'Dan Kami berikan kepada mereka keterangan-keterangan yang nyata tentang urusan (agama); maka mereka tidak berselisih melainkan sesudah datang kepada mereka pengetahuan karena kedengkian yang ada di antara mereka. Sesungguhnya Tuhanmu akan memutuskan antara mereka pada hari kiamat terhadap apa yang mereka selalu berselisih padanya.'),
  ('id.indonesian', 45, 18, 'Kemudian Kami jadikan kamu berada di atas suatu syariat (peraturan) dari urusan (agama itu), maka ikutilah syariat itu dan janganlah kamu ikuti hawa nafsu orang-orang yang tidak mengetahui.'),
  ('id.indonesian', 45, 19, 'Sesungguhnya mereka sekali-kali tidak akan dapat menolak dari kamu sedikitpun dari siksaan Allah. Dan Sesungguhnya orang-orang yang zalim itu sebagian mereka menjadi penolong bagi sebagian yang lain, dan Allah adalah pelindung orang-orang yang bertakwa.'),
  ('id.indonesian', 45, 20, 'Al Quran ini adalah pedoman bagi manusia, petunjuk dan rahmat bagi kaum yang meyakini.'),
  ('id.indonesian', 45, 21, 'Apakah orang-orang yang membuat kejahatan itu menyangka bahwa Kami akan menjadikan mereka seperti orang-orang yang beriman dan mengerjakan amal saleh, yaitu sama antara kehidupan dan kematian mereka? Amat buruklah apa yang mereka sangka itu.'),
  ('id.indonesian', 45, 22, 'Dan Allah menciptakan langit dan bumi dengan tujuan yang benar dan agar dibalasi tiap-tiap diri terhadap apa yang dikerjakannya, dan mereka tidak akan dirugikan.'),
  ('id.indonesian', 45, 23, 'Maka pernahkah kamu melihat orang yang menjadikan hawa nafsunya sebagai tuhannya dan Allah membiarkannya berdasarkan ilmu-Nya dan Allah telah mengunci mati pendengaran dan hatinya dan meletakkan tutupan atas penglihatannya? Maka siapakah yang akan memberinya petunjuk sesudah Allah (membiarkannya sesat). Maka mengapa kamu tidak mengambil pelajaran?'),
  ('id.indonesian', 45, 24, 'Dan mereka berkata: "Kehidupan ini tidak lain hanyalah kehidupan di dunia saja, kita mati dan kita hidup dan tidak ada yang akan membinasakan kita selain masa", dan mereka sekali-kali tidak mempunyai pengetahuan tentang itu, mereka tidak lain hanyalah menduga-duga saja.'),
  ('id.indonesian', 45, 25, 'Dan apabila dibacakan kepada mereka ayat-ayat Kami yang jelas, tidak ada bantahan mereka selain dari mengatakan: "Datangkanlah nenek moyang kami jika kamu adalah orang-orang yang benar".'),
  ('id.indonesian', 45, 26, 'Katakanlah: "Allah-lah yang menghidupkan kamu kemudian mematikan kamu, setelah itu mengumpulkan kamu pada hari kiamat yang tidak ada keraguan padanya; akan tetapi kebanyakan manusia tidak mengetahui.'),
  ('id.indonesian', 45, 27, 'Dan hanya kepunyaan Allah kerajaan langit dan bumi. Dan pada hari terjadinya kebangkitan, akan rugilah pada hari itu orang-orang yang mengerjakan kebathilan.'),
  ('id.indonesian', 45, 28, 'Dan (pada hari itu) kamu lihat tiap-tiap umat berlutut. Tiap-tiap umat dipanggil untuk (melihat) buku catatan amalnya. Pada hari itu kamu diberi balasan terhadap apa yang telah kamu kerjakan.'),
  ('id.indonesian', 45, 29, '(Allah berfirman): "Inilah kitab (catatan) Kami yang menuturkan terhadapmu dengan benar. Sesungguhnya Kami telah menyuruh mencatat apa yang telah kamu kerjakan".'),
  ('id.indonesian', 45, 30, 'Adapun orang-orang yang beriman dan mengerjakan amal saleh maka Tuhan mereka memasukkan mereka ke dalam rahmat-Nya (surga). Itulah keberuntungan yang nyata.'),
  ('id.indonesian', 45, 31, 'Dan adapun orang-orang yang kafir (kepada mereka dikatakan): "Maka apakah belum ada ayat-ayat-Ku yang dibacakan kepadamu lalu kamu menyombongkan diri dan kamu jadi kaum yang berbuat dosa?"'),
  ('id.indonesian', 45, 32, 'Dan apabila dikatakan (kepadamu): "Sesungguhnya janji Allah itu adalah benar dan hari berbangkit itu tidak ada keraguan padanya", niscaya kamu menjawab: "Kami tidak tahu apakah hari kiamat itu, kami sekali-kali tidak lain hanyalah menduga-duga saja dan kami sekali-kali tidak meyakini(nya)".'),
  ('id.indonesian', 45, 33, 'Dan nyatalah bagi mereka keburukan-keburukan dari apa yang mereka kerjakan dan mereka diliputi oleh (azab) yang mereka selalu memperolok-olokkannya.'),
  ('id.indonesian', 45, 34, 'Dan dikatakan (kepada mereka): "Pada hari ini Kami melupakan kamu sebagaimana kamu telah melupakan pertemuan (dengan) harimu ini dan tempat kembalimu ialah neraka dan kamu sekali-kali tidak memperoleh penolong".'),
  ('id.indonesian', 45, 35, 'Yang demikian itu, karena sesungguhnya kamu menjadikan ayat-ayat Allah sebagai olok-olokan dan kamu telah ditipu oleh kehidupan dunia, maka pada hari ini mereka tidak dikeluarkan dari neraka dan tidak pula mereka diberi kesempatan untuk bertaubat.'),
  ('id.indonesian', 45, 36, 'Maka bagi Allah-lah segala puji, Tuhan langit dan Tuhan bumi, Tuhan semesta alam.'),
  ('id.indonesian', 45, 37, 'Dan bagi-Nya-lah keagungan di langit dan bumi, Dialah Yang Maha Perkasa lagi Maha Bijaksana.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 46, 1, 'Ha, Meem.'),
  ('en.sahih', 46, 2, 'The revelation of the Book is from Allah, the Exalted in Might, the Wise.'),
  ('en.sahih', 46, 3, 'We did not create the heavens and earth and what is between them except in truth and [for] a specified term. But those who disbelieve, from that of which they are warned, are turning away.'),
  ('en.sahih', 46, 4, 'Say, [O Muhammad], "Have you considered that which you invoke besides Allah? Show me what they have created of the earth; or did they have partnership in [creation of] the heavens? Bring me a scripture [revealed] before this or a [remaining] trace of knowledge, if you should be truthful."'),
  ('en.sahih', 46, 5, 'And who is more astray than he who invokes besides Allah those who will not respond to him until the Day of Resurrection, and they, of their invocation, are unaware.'),
  ('en.sahih', 46, 6, 'And when the people are gathered [that Day], they [who were invoked] will be enemies to them, and they will be deniers of their worship.'),
  ('en.sahih', 46, 7, 'And when Our verses are recited to them as clear evidences, those who disbelieve say of the truth when it has come to them, "This is obvious magic."'),
  ('en.sahih', 46, 8, 'Or do they say, "He has invented it?" Say, "If I have invented it, you will not possess for me [the power of protection] from Allah at all. He is most knowing of that in which you are involved. Sufficient is He as Witness between me and you, and He is the Forgiving the Merciful."'),
  ('en.sahih', 46, 9, 'Say, "I am not something original among the messengers, nor do I know what will be done with me or with you. I only follow that which is revealed to me, and I am not but a clear warner."'),
  ('en.sahih', 46, 10, 'Say, "Have you considered: if the Qur\'an was from Allah, and you disbelieved in it while a witness from the Children of Israel has testified to something similar and believed while you were arrogant...?" Indeed, Allah does not guide the wrongdoing people.'),
  ('en.sahih', 46, 11, 'And those who disbelieve say of those who believe, "If it had [truly] been good, they would not have preceded us to it." And when they are not guided by it, they will say, "This is an ancient falsehood."'),
  ('en.sahih', 46, 12, 'And before it was the scripture of Moses to lead and as a mercy. And this is a confirming Book in an Arabic tongue to warn those who have wronged and as good tidings to the doers of good.'),
  ('en.sahih', 46, 13, 'Indeed, those who have said, "Our Lord is Allah," and then remained on a right course - there will be no fear concerning them, nor will they grieve.'),
  ('en.sahih', 46, 14, 'Those are the companions of Paradise, abiding eternally therein as reward for what they used to do.'),
  ('en.sahih', 46, 15, 'And We have enjoined upon man, to his parents, good treatment. His mother carried him with hardship and gave birth to him with hardship, and his gestation and weaning [period] is thirty months. [He grows] until, when he reaches maturity and reaches [the age of] forty years, he says, "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims."'),
  ('en.sahih', 46, 16, 'Those are the ones from whom We will accept the best of what they did and overlook their misdeeds, [their being] among the companions of Paradise. [That is] the promise of truth which they had been promised.'),
  ('en.sahih', 46, 17, 'But one who says to his parents, "Uff to you; do you promise me that I will be brought forth [from the earth] when generations before me have already passed on [into oblivion]?" while they call to Allah for help [and to their son], "Woe to you! Believe! Indeed, the promise of Allah is truth." But he says, "This is not but legends of the former people" -'),
  ('en.sahih', 46, 18, 'Those are the ones upon whom the word has come into effect, [who will be] among nations which had passed on before them of jinn and men. Indeed, they [all] were losers.'),
  ('en.sahih', 46, 19, 'And for all there are degrees [of reward and punishment] for what they have done, and [it is] so that He may fully compensate them for their deeds, and they will not be wronged.'),
  ('en.sahih', 46, 20, 'And the Day those who disbelieved are exposed to the Fire [it will be said], "You exhausted your pleasures during your worldly life and enjoyed them, so this Day you will be awarded the punishment of [extreme] humiliation because you were arrogant upon the earth without right and because you were defiantly disobedient."'),
  ('en.sahih', 46, 21, 'And mention, [O Muhammad], the brother of \'Aad, when he warned his people in the [region of] al-Ahqaf - and warners had already passed on before him and after him - [saying], "Do not worship except Allah. Indeed, I fear for you the punishment of a terrible day."'),
  ('en.sahih', 46, 22, 'They said, "Have you come to delude us away from our gods? Then bring us what you promise us, if you should be of the truthful."'),
  ('en.sahih', 46, 23, 'He said, "Knowledge [of its time] is only with Allah, and I convey to you that with which I was sent; but I see you [to be] a people behaving ignorantly."'),
  ('en.sahih', 46, 24, 'And when they saw it as a cloud approaching their valleys, they said, "This is a cloud bringing us rain!" Rather, it is that for which you were impatient: a wind, within it a painful punishment,'),
  ('en.sahih', 46, 25, 'Destroying everything by command of its Lord. And they became so that nothing was seen [of them] except their dwellings. Thus do We recompense the criminal people.'),
  ('en.sahih', 46, 26, 'And We had certainly established them in such as We have not established you, and We made for them hearing and vision and hearts. But their hearing and vision and hearts availed them not from anything [of the punishment] when they were [continually] rejecting the signs of Allah; and they were enveloped by what they used to ridicule.'),
  ('en.sahih', 46, 27, 'And We have already destroyed what surrounds you of [those] cities, and We have diversified the signs [or verses] that perhaps they might return [from disbelief].'),
  ('en.sahih', 46, 28, 'Then why did those they took besides Allah as deities by which to approach [Him] not aid them? But they had strayed from them. And that was their falsehood and what they were inventing.'),
  ('en.sahih', 46, 29, 'And [mention, O Muhammad], when We directed to you a few of the jinn, listening to the Qur\'an. And when they attended it, they said, "Listen quietly." And when it was concluded, they went back to their people as warners.'),
  ('en.sahih', 46, 30, 'They said, "O our people, indeed we have heard a [recited] Book revealed after Moses confirming what was before it which guides to the truth and to a straight path.'),
  ('en.sahih', 46, 31, 'O our people, respond to the Messenger of Allah and believe in him; Allah will forgive for you your sins and protect you from a painful punishment.'),
  ('en.sahih', 46, 32, 'But he who does not respond to the Caller of Allah will not cause failure [to Him] upon earth, and he will not have besides Him any protectors. Those are in manifest error."'),
  ('en.sahih', 46, 33, 'Do they not see that Allah, who created the heavens and earth and did not fail in their creation, is able to give life to the dead? Yes. Indeed, He is over all things competent.'),
  ('en.sahih', 46, 34, 'And the Day those who disbelieved are exposed to the Fire [it will be said], "Is this not the truth?" They will say, "Yes, by our Lord." He will say, "Then taste the punishment because you used to disbelieve."'),
  ('en.sahih', 46, 35, 'So be patient, [O Muhammad], as were those of determination among the messengers and do not be impatient for them. It will be - on the Day they see that which they are promised - as though they had not remained [in the world] except an hour of a day. [This is] notification. And will [any] be destroyed except the defiantly disobedient people?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 46, 1, 'হা-মীম।'),
  ('bn.bengali', 46, 2, 'এই কিতাব পরাক্রমশালী, প্রজ্ঞাময় আল্লাহর পক্ষ থেকে অবতীর্ণ।'),
  ('bn.bengali', 46, 3, 'নভোমন্ডল, ভূ-মন্ডল ও এতদুভয়ের মধ্যবর্তী সবকিছু আমি যথাযথভাবেই এবং নির্দিষ্ট সময়ের জন্যেই সৃষ্টি করেছি। আর কাফেররা যে বিষয়ে তাদেরকে সতর্ক করা হয়েছে, তা থেকে মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 46, 4, 'বলুন, তোমরা আল্লাহ ব্যতীত যাদের পূজা কর, তাদের বিষয়ে ভেবে দেখেছ কি? দেখাও আমাকে তারা পৃথিবীতে কি সৃষ্টি করেছে? অথবা নভোমন্ডল সৃজনে তাদের কি কোন অংশ আছে? এর পূর্ববর্তী কোন কিতাব অথবা পরস্পরাগত কোন জ্ঞান আমার কাছে উপস্থিত কর, যদি তোমরা সত্যবাদী হও।'),
  ('bn.bengali', 46, 5, 'যে ব্যক্তি আল্লাহর পরিবর্তে এমন বস্তুর পূজা করে, যে কেয়ামত পর্যন্তও তার ডাকে সাড়া দেবে না, তার চেয়ে অধিক পথভ্রষ্ট আর কে? তারা তো তাদের পুজা সম্পর্কেও বেখবর।'),
  ('bn.bengali', 46, 6, 'যখন মানুষকে হাশরে একত্রিত করা হবে, তখন তারা তাদের শত্রু হবে এবং তাদের এবাদত অস্বীকার করবে।'),
  ('bn.bengali', 46, 7, 'যখন তাদেরকে আমার সুস্পষ্ট আয়াতসমূহ পাঠ করে শুনানো হয়, তখন সত্য আগমন করার পর কাফেররা বলে, এ তো প্রকাশ্য জাদু।'),
  ('bn.bengali', 46, 8, 'তারা কি বলে যে, রসূল একে রচনা করেছে? বলুন, যদি আমি রচনা করে থাকি, তবে তোমরা আল্লাহর শাস্তি থেকে আমাকে রক্ষা করার অধিকারী নও। তোমরা এ সম্পর্কে যা আলোচনা কর, সে বিষয়ে আল্লাহ সম্যক অবগত। আমার ও তোমাদের মধ্যে তিনি সাক্ষী হিসাবে যথেষ্ট। তিনি ক্ষমাশীল, দয়াময়।'),
  ('bn.bengali', 46, 9, 'বলুন, আমি তো কোন নতুন রসূল নই। আমি জানি না, আমার ও তোমাদের সাথে কি ব্যবহার করা হবে। আমি কেবল তারই অনুসরণ করি, যা আমার প্রতি ওহী করা হয়। আমি স্পষ্ট সতর্ক কারী বৈ নই।'),
  ('bn.bengali', 46, 10, 'বলুন, তোমরা ভেবে দেখেছ কি, যদি এটা আল্লাহর পক্ষ থেকে হয় এবং তোমরা একে অমান্য কর এবং বনী ইসরাঈলের একজন সাক্ষী এর পক্ষে সাক্ষ্য দিয়ে এতে বিশ্বাস স্থাপন করে; আর তোমরা অহংকার কর, তবে তোমাদের চেয়ে অবিবেচক আর কে হবে? নিশ্চয় আল্লাহ অবিবেচকদেরকে পথ দেখান না।'),
  ('bn.bengali', 46, 11, 'আর কাফেররা মুমিনদের বলতে লাগল যে, যদি এ দ্বীন ভাল হত তবে এরা আমাদেরকে পেছনে ফেলে এগিয়ে যেতে পারত না। তারা যখন এর মাধ্যমে সুপথ পায়নি, তখন শীঘ্রই বলবে, এ তো এক পুরাতন মিথ্যা।'),
  ('bn.bengali', 46, 12, 'এর আগে মূসার কিতাব ছিল পথপ্রদর্শক ও রহমতস্বরূপ। আর এই কিতাব তার সমর্থক আরবী ভাষায়, যাতে যালেমদেরকে সতর্ক করে এবং সৎকর্মপরায়ণদেরকে সুসংবাদ দেয়।'),
  ('bn.bengali', 46, 13, 'নিশ্চয় যারা বলে, আমাদের পালনকর্তা আল্লাহ অতঃপর অবিচল থাকে, তাদের কোন ভয় নেই এবং তারা চিন্তিত হবে না।'),
  ('bn.bengali', 46, 14, 'তারাই জান্নাতের অধিকারী! তারা তথায় চিরকাল থাকবে। তারা যে কর্ম করত, এটা তারই প্রতিফল।'),
  ('bn.bengali', 46, 15, 'আমি মানুষকে তার পিতা-মাতার সাথে সদ্ব্যবহারের আদেশ দিয়েছি। তার জননী তাকে কষ্টসহকারে গর্ভে ধারণ করেছে এবং কষ্টসহকারে প্রসব করেছে। তাকে গর্ভে ধারণ করতে ও তার স্তন্য ছাড়তে লেগেছে ত্রিশ মাস। অবশেষে সে যখন শক্তি-সামর্থে?480; বয়সে ও চল্লিশ বছরে পৌছেছে, তখন বলতে লাগল, হে আমার পালনকর্তা, আমাকে এরূপ ভাগ্য দান কর, যাতে আমি তোমার নেয়ামতের শোকর করি, যা তুমি দান করেছ আমাকে ও আমার পিতা-মাতাকে এবং যাতে আমি তোমার পছন্দনীয় সৎকাজ করি। আমার সন্তানদেরকে সৎকর্মপরায়ণ কর, আমি তোমার প্রতি তওবা করলাম এবং আমি আজ্ঞাবহদের অন্যতম।'),
  ('bn.bengali', 46, 16, 'আমি এমন লোকদের সুকর্মগুলো কবুল করি এবং মন্দকর্মগুলো মার্জনা করি। তারা জান্নাতীদের তালিকাভুক্ত সেই সত্য ওয়াদার কারণে যা তাদেরকে দেওয়া হত।'),
  ('bn.bengali', 46, 17, 'আর যে ব্যক্তি তার পিতা-মাতাকে বলে, ধিক তোমাদেরকে, তোমরা কি আমাকে খবর দাও যে, আমি পুনরুত্থিত হব, অথচ আমার পূর্বে বহু লোক গত হয়ে গেছে? আর পিতা-মাতা আল্লাহর কাছে ফরিযাদ করে বলে, দুর্ভোগ তোমার তুমি বিশ্বাস স্থাপন কর। নিশ্চয় আল্লাহর ওয়াদা সত্য। তখন সে বলে, এটা তো পূর্ববর্তীদের উপকথা বৈ নয়।'),
  ('bn.bengali', 46, 18, 'তাদের পূর্বে যে সব জ্বিন ও মানুষ গত হয়েছে, তাদের মধ্যে এ ধরনের লোকদের প্রতিও শাস্তিবানী অবধারিত হয়ে গেছে। নিশ্চয় তারা ছিল ক্ষতিগ্রস্থ।'),
  ('bn.bengali', 46, 19, 'প্রত্যেকের জন্যে তাদের কৃতকর্ম অনুযায়ী বিভিন্ন স্তর রয়েছে, যাতে আল্লাহ তাদের কর্মের পূর্ণ প্রতিফল দেন। বস্তুতঃ তাদের প্রতি যুলুম করা হবে না।'),
  ('bn.bengali', 46, 20, 'যেদিন কাফেরদেরকে জাহান্নামের কাছে উপস্থিত করা হবে সেদিন বলা হবে, তোমরা তোমাদের সুখ পার্থিব জীবনেই নিঃশেষ করেছ এবং সেগুলো ভোগ করেছ সুতরাং আজ তোমাদেরকে অপমানকর আযাবের শাস্তি দেয়া হবে; কারণ, তোমরা পৃথিবীতে অন্যায় ভাবে অহংকার করতে এবং তোমরা পাপাচার করতে।'),
  ('bn.bengali', 46, 21, 'আ’দ সম্প্রদায়ের ভাইয়ের কথা স্মরণ করুন, তার পূর্বে ও পরে অনেক সতর্ককারী গত হয়েছিল সে তার সম্প্রদায়কে বালুকাময় উচ্চ উপত্যকায় এ মর্মে সতর্ক করেছিল যে, তোমরা আল্লাহ ব্যতীত কারও এবাদত করো না। আমি তোমাদের জন্যে এক মহাদিবসের শাস্তির আশংকা করি।'),
  ('bn.bengali', 46, 22, 'তারা বলল, তুমি কি আমাদেরকে আমাদের উপাস্য দেব-দেবী থেকে নিবৃত্ত করতে আগমন করেছ? তুমি সত্যবাদী হলে আমাদেরকে যে বিষয়ের ওয়াদা দাও, তা নিয়ে আস।'),
  ('bn.bengali', 46, 23, 'সে বলল, এ জ্ঞান তো আল্লাহর কাছেই রয়েছে। আমি যে বিষয়সহ প্রেরিত হয়েছি, তা তোমাদের কাছে পৌঁছাই। কিন্তু আমি দেখছি তোমরা এক মুর্খ সম্প্রদায়।'),
  ('bn.bengali', 46, 24, '(অতঃপর) তারা যখন শাস্তিকে মেঘরূপে তাদের উপত্যকা অভিমুখী দেখল, তখন বলল, এ তো মেঘ, আমাদেরকে বৃষ্টি দেবে। বরং এটা সেই বস্তু, যা তোমরা তাড়াতাড়ি চেয়েছিলে। এটা বায়ু এতে রয়েছে মর্মন্তুদ শাস্তি।'),
  ('bn.bengali', 46, 25, 'তার পালনকর্তার আদেশে সে সব কিছুকে ধ্বংস করে দেবে। অতঃপর তারা ভোর বেলায় এমন হয়ে গেল যে, তাদের বসতিগুলো ছাড়া কিছুই দৃষ্টিগোচর হল না। আমি অপরাধী সম্প্রদায়কে এমনিভাবে শাস্তি দিয়ে থাকি।'),
  ('bn.bengali', 46, 26, 'আমি তাদেরকে এমন বিষয়ে ক্ষমতা দিয়েছিলাম, যে বিষয়ে তোমাদেরকে ক্ষমতা দেইনি। আমি তাদের দিয়েছিলাম, কর্ণ, চক্ষু ও হৃদয়, কিন্তু তাদের কর্ণ, চক্ষু ও হৃদয় তাদের কোন কাজে আসল না, যখন তারা আল্লাহর আয়াতসমূহকে অস্বীকার করল এবং তাদেরকে সেই শাস্তি গ্রাস করে নিল, যা নিয়ে তারা ঠাট্টা বিদ্রুপ করত।'),
  ('bn.bengali', 46, 27, 'আমি তোমাদের আশপাশের জনপদ সমূহ ধ্বংস করে দিয়েছি এবং বার বার আয়াতসমূহ শুনিয়েছি, যাতে তারা ফিরে আসে।'),
  ('bn.bengali', 46, 28, 'অতঃপর আল্লাহর পরিবর্তে তারা যাদেরকে সান্নিধ্য লাভের জন্যে উপাস্যরূপে গ্রহণ করেছিল, তারা তাদেরকে সাহায্য করল না কেন? বরং তারা তাদের কাছ থেকে উধাও হয়ে গেল। এটা ছিল তাদের মিথ্যা ও মনগড়া বিষয়।'),
  ('bn.bengali', 46, 29, 'যখন আমি একদল জিনকে আপনার প্রতি আকৃষ্ট করেছিলাম, তারা কোরআন পাঠ শুনছিল,। তারা যখন কোরআন পাঠের জায়গায় উপস্থিত হল, তখন পরস্পর বলল, চুপ থাক। অতঃপর যখন পাঠ সমাপ্ত হল, তখন তারা তাদের সম্প্রদায়ের কাছে সতর্ককারীরূপে ফিরে গেল।'),
  ('bn.bengali', 46, 30, 'তারা বলল, হে আমাদের সম্প্রদায়, আমরা এমন এক কিতাব শুনেছি, যা মূসার পর অবর্তীণ হয়েছে। এ কিতাব পূর্ববর্তী সব কিতাবের প্রত্যায়ন করে, সত্যধর্ম ও সরলপথের দিকে পরিচালিত করে।'),
  ('bn.bengali', 46, 31, 'হে আমাদের সম্প্রদায়, তোমরা আল্লাহর দিকে আহবানকারীর কথা মান্য কর এবং তাঁর প্রতি বিশ্বাস স্থাপন কর। তিনি তোমাদের গোনাহ মার্জনা করবেন।'),
  ('bn.bengali', 46, 32, 'আর যে ব্যক্তি আল্লাহর দিকে আহবানকারীর কথা মানবে না, সে পৃথিবীতে আল্লাহকে অপারক করতে পারবে না এবং আল্লাহ ব্যতীত তার কোন সাহায্যকারী থাকবে না। এ ধরনের লোকই প্রকাশ্য পথভ্রষ্টতায় লিপ্ত।'),
  ('bn.bengali', 46, 33, 'তারা কি জানে না যে, আল্লাহ যিনি নভোমন্ডল ও ভূমন্ডল সৃষ্টি করেছেন এবং এগুলোর সৃষ্টিতে কোন ক্লান্তিবোধ করেননি, তিনি মৃতকে জীবিত করতে সক্ষম? কেন নয়, নিশ্চয় তিনি সর্ব বিষয়ে সর্বশক্তিমান।'),
  ('bn.bengali', 46, 34, 'যেদিন কাফেরদেরকে জাহান্নামের সামনে পেশ করা হবে, সেদিন বলা হবে, এটা কি সত্য নয়? তারা বলবে, হঁ্যা আমাদের পালনকর্তার শপথ। আল্লাহ বলবেন, আযাব আস্বাদন কর। কারণ, তোমরা কুফরী করতে।'),
  ('bn.bengali', 46, 35, 'অতএব, আপনি সবর করুন, যেমন উচ্চ সাহসী পয়গম্বরগণ সবর করেছেন এবং ওদের বিষয়ে তড়িঘড়ি করবেন না। ওদেরকে যে বিষয়ে ওয়াদা দেয়া হত, তা যেদিন তারা প্রত্যক্ষ করবে, সেদিন তাদের মনে হবে যেন তারা দিনের এক মুহুর্তের বেশী পৃথিবীতে অবস্থান করেনি। এটা সুস্পষ্ট অবগতি। এখন তারাই ধ্বংসপ্রাপ্ত হবে, যারা পাপাচারী সম্প্রদায়।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 46, 1, 'Ha. Mim.'),
  ('en.pickthall', 46, 2, 'The revelation of the Scripture is from Allah the Mighty, the Wise.'),
  ('en.pickthall', 46, 3, 'We created not the heavens and the earth and all that is between them save with truth, and for a term appointed. But those who disbelieve turn away from that whereof they are warned.'),
  ('en.pickthall', 46, 4, 'Say (unto them, O Muhammad): Have ye thought on all that ye invoke beside Allah? Show me what they have created of the earth. Or have they any portion in the heavens? Bring me a scripture before this (Scripture), or some vestige of knowledge (in support of what ye say), if ye are truthful.'),
  ('en.pickthall', 46, 5, 'And who is further astray than those who, instead of Allah, pray unto such as hear not their prayer until the Day of Resurrection, and are unconscious of their prayer,'),
  ('en.pickthall', 46, 6, 'And when mankind are gathered (to the Judgment) will become enemies for them, and will become deniers of having been worshipped.'),
  ('en.pickthall', 46, 7, 'And when Our clear revelations are recited unto them, those who disbelieve say of the Truth when it reacheth them: This is mere magic.'),
  ('en.pickthall', 46, 8, 'Or say they: He hath invented it? Say (O Muhammad): If I have invented it, still ye have no power to support me against Allah. He is Best Aware of what ye say among yourselves concerning it. He sufficeth for a witness between me and you. And He is the Forgiving, the Merciful.'),
  ('en.pickthall', 46, 9, 'Say: I am no new thing among the messengers (of Allah), nor know I what will be done with me or with you. I do but follow that which is inspired in me, and I am but a plain warner.'),
  ('en.pickthall', 46, 10, 'Bethink you: If it is from Allah and ye disbelieve therein, and a witness of the Children of Israel hath already testified to the like thereof and hath believed, and ye are too proud (what plight is yours)? Lo! Allah guideth not wrong-doing folk.'),
  ('en.pickthall', 46, 11, 'And those who disbelieve say of those who believe: If it had been (any) good, they would not have been before us in attaining it. And since they will not be guided by it, they say: This is an ancient lie;'),
  ('en.pickthall', 46, 12, 'When before it there was the Scripture of Moses, an example and a mercy; and this is a confirming Scripture in the Arabic language, that it may warn those who do wrong and bring good tidings for the righteous.'),
  ('en.pickthall', 46, 13, 'Lo! those who say: Our Lord is Allah, and thereafter walk aright, there shall no fear come upon them neither shall they grieve.'),
  ('en.pickthall', 46, 14, 'Such are rightful owners of the Garden, immortal therein, as a reward for what they used to do.'),
  ('en.pickthall', 46, 15, 'And We have commended unto man kindness toward parents. His mother beareth him with reluctance, and bringeth him forth with reluctance, and the bearing of him and the weaning of him is thirty months, till, when he attaineth full strength and reacheth forty years, he saith: My Lord! Arouse me that I may give thanks for the favour wherewith Thou hast favoured me and my parents, and that I may do right acceptable unto Thee. And be gracious unto me in the matter of my seed. Lo! I have turned unto Thee repentant, and lo! I am of those who surrender (unto Thee).'),
  ('en.pickthall', 46, 16, 'Those are they from whom We accept the best of what they do, and overlook their evil deeds. (They are) among the owners of the Garden. This is the true promise which they were promised (in the world).'),
  ('en.pickthall', 46, 17, 'And whoso saith unto his parents: Fie upon you both! Do ye threaten me that I shall be brought forth (again) when generations before me have passed away? And they twain cry unto Allah for help (and say): Woe unto thee! Believe! Lo! the promise of Allah is true. But he saith: This is naught save fables of the men of old:'),
  ('en.pickthall', 46, 18, 'Such are those on whom the Word concerning nations of the jinn and mankind which have passed away before them hath effect. Lo! they are the losers.'),
  ('en.pickthall', 46, 19, 'And for all there will be ranks from what they do, that He may pay them for their deeds; and they will not be wronged.'),
  ('en.pickthall', 46, 20, 'And on the day when those who disbelieve are exposed to the Fire (it will be said): Ye squandered your good things in the life of the world and sought comfort therein. Now this day ye are rewarded with the doom of ignominy because ye were disdainful in the land without a right, and because ye used to transgress.'),
  ('en.pickthall', 46, 21, 'And make mention (O Muhammad) of the brother of A\'ad when he warned his folk among the wind-curved sandhills - and verily warners came and went before and after him - saying: Serve none but Allah. Lo! I fear for you the doom of a tremendous Day.'),
  ('en.pickthall', 46, 22, 'They said: Hast come to turn us away from our gods? Then bring upon us that wherewith thou threatenest us, if thou art of the truthful.'),
  ('en.pickthall', 46, 23, 'He said: The knowledge is with Allah only. I convey unto you that wherewith I have been sent, but I see you are a folk that know not.'),
  ('en.pickthall', 46, 24, 'Then, when they beheld it as a dense cloud coming toward their valleys, they said: Here is a cloud bringing us rain. Nay, but it is that which ye did seek to hasten, a wind wherein is painful torment,'),
  ('en.pickthall', 46, 25, 'Destroying all things by commandment of its Lord. And morning found them so that naught could be seen save their dwellings. Thus do We reward the guilty folk.'),
  ('en.pickthall', 46, 26, 'And verily We had empowered them with that wherewith We have not empowered you, and had assigned them ears and eyes and hearts; but their ears and eyes and hearts availed them naught since they denied the revelations of Allah; and what they used to mock befell them.'),
  ('en.pickthall', 46, 27, 'And verily We have destroyed townships round about you, and displayed (for them) Our revelation, that haply they might return.'),
  ('en.pickthall', 46, 28, 'Then why did those whom they had chosen for gods as a way of approach (unto Allah) not help them? Nay, but they did fail them utterly. And (all) that was their lie, and what they used to invent.'),
  ('en.pickthall', 46, 29, 'And when We inclined toward thee (Muhammad) certain of the jinn, who wished to hear the Qur\'an and, when they were in its presence, said: Give ear! and, when it was finished, turned back to their people, warning.'),
  ('en.pickthall', 46, 30, 'They said: O our people! Lo! we have heard a scripture which hath been revealed after Moses, confirming that which was before it, guiding unto the truth and a right road.'),
  ('en.pickthall', 46, 31, 'O our people! respond to Allah\'s summoner and believe in Him. He will forgive you some of your sins and guard you from a painful doom.'),
  ('en.pickthall', 46, 32, 'And whoso respondeth not to Allah\'s summoner he can nowise escape in the earth, and he hath no protecting friends instead of Him. Such are in error manifest.'),
  ('en.pickthall', 46, 33, 'Have they not seen that Allah, Who created the heavens and the earth and was not wearied by their creation, is Able to give life to the dead? Aye, He verily is Able to do all things.'),
  ('en.pickthall', 46, 34, 'And on the day when those who disbelieve are exposed to the Fire (they will be asked): Is not this real? They will say: Yea, by our Lord. He will say: Then taste the doom for that ye disbelieved.'),
  ('en.pickthall', 46, 35, 'Then have patience (O Muhammad) even as the stout of heart among the messengers (of old) had patience, and seek not to hasten on (the doom) for them. On the day when they see that which they are promised (it will seem to them) as though they had tarried but an hour of daylight. A clear message. Shall any be destroyed save evil-living folk?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 46, 1, 'Ha-Mim.'),
  ('en.yusufali', 46, 2, 'The Revelation of the Book is from Allah the Exalted in Power, Full of Wisdom.'),
  ('en.yusufali', 46, 3, 'We created not the heavens and the earth and all between them but for just ends, and for a Term Appointed: But those who reject Faith turn away from that whereof they are warned.'),
  ('en.yusufali', 46, 4, 'Say: "Do ye see what it is ye invoke besides Allah? Show me what it is they have created on earth, or have they a share in the heavens bring me a book (revealed) before this, or any remnant of knowledge (ye may have), if ye are telling the truth!'),
  ('en.yusufali', 46, 5, 'And who is more astray than one who invokes besides Allah, such as will not answer him to the Day of Judgment, and who (in fact) are unconscious of their call (to them)?'),
  ('en.yusufali', 46, 6, 'And when mankind are gathered together (at the Resurrection), they will be hostile to them and reject their worship (altogether)!'),
  ('en.yusufali', 46, 7, 'When Our Clear Signs are rehearsed to them, the Unbelievers say, of the Truth when it comes to them: "This is evident sorcery!"'),
  ('en.yusufali', 46, 8, 'Or do they say, "He has forged it"? Say: "Had I forged it, then can ye obtain no single (blessing) for me from Allah. He knows best of that whereof ye talk (so glibly)! Enough is He for a witness between me and you! And he is Oft-Forgiving, Most Merciful."'),
  ('en.yusufali', 46, 9, 'Say: "I am no bringer of new-fangled doctrine among the messengers, nor do I know what will be done with me or with you. I follow but that which is revealed to me by inspiration; I am but a Warner open and clear."'),
  ('en.yusufali', 46, 10, 'Say: "See ye? If (this teaching) be from Allah, and ye reject it, and a witness from among the Children of Israel testifies to its similarity (with earlier scripture), and has believed while ye are arrogant, (how unjust ye are!) truly, Allah guides not a people unjust."'),
  ('en.yusufali', 46, 11, 'The Unbelievers say of those who believe: "If (this Message) were a good thing, (such men) would not have gone to it first, before us!" And seeing that they guide not themselves thereby, they will say, "this is an (old,) falsehood!"'),
  ('en.yusufali', 46, 12, 'And before this, was the Book of Moses as a guide and a mercy: And this Book confirms (it) in the Arabic tongue; to admonish the unjust, and as Glad Tidings to those who do right.'),
  ('en.yusufali', 46, 13, 'Verily those who say, "Our Lord is Allah," and remain firm (on that Path),- on them shall be no fear, nor shall they grieve.'),
  ('en.yusufali', 46, 14, 'Such shall be Companions of the Gardens, dwelling therein (for aye): a recompense for their (good) deeds.'),
  ('en.yusufali', 46, 15, 'We have enjoined on man kindness to his parents: In pain did his mother bear him, and in pain did she give him birth. The carrying of the (child) to his weaning is (a period of) thirty months. At length, when he reaches the age of full strength and attains forty years, he says, "O my Lord! Grant me that I may be grateful for Thy favour which Thou has bestowed upon me, and upon both my parents, and that I may work righteousness such as Thou mayest approve; and be gracious to me in my issue. Truly have I turned to Thee and truly do I bow (to Thee) in Islam."'),
  ('en.yusufali', 46, 16, 'Such are they from whom We shall accept the best of their deeds and pass by their ill deeds: (They shall be) among the Companions of the Garden: a promise! of truth, which was made to them (in this life).'),
  ('en.yusufali', 46, 17, 'But (there is one) who says to his parents, "Fie on you! Do ye hold out the promise to me that I shall be raised up, even though generations have passed before me (without rising again)?" And they two seek Allah\'s aid, (and rebuke the son): "Woe to thee! Have faith! for the promise of Allah is true." But he says, "This is nothing but tales of the ancients!"'),
  ('en.yusufali', 46, 18, 'Such are they against whom is proved the sentence among the previous generations of Jinns and men, that have passed away; for they will be (utterly) lost.'),
  ('en.yusufali', 46, 19, 'And to all are (assigned) degrees according to the deeds which they (have done), and in order that (Allah) may recompense their deeds, and no injustice be done to them.'),
  ('en.yusufali', 46, 20, 'And on the Day that the Unbelievers will be placed before the Fire, (It will be said to them): "Ye received your good things in the life of the world, and ye took your pleasure out of them: but today shall ye be recompensed with a Penalty of humiliation: for that ye were arrogant on earth without just cause, and that ye (ever) transgressed."'),
  ('en.yusufali', 46, 21, 'Mention (Hud) one of \'Ad\'s (own) brethren: Behold, he warned his people about the winding Sand-tracts: but there have been warners before him and after him: "Worship ye none other than Allah: Truly I fear for you the Penalty of a Mighty Day."'),
  ('en.yusufali', 46, 22, 'They said: "Hast thou come in order to turn us aside from our gods? Then bring upon us the (calamity) with which thou dost threaten us, if thou art telling the truth?"'),
  ('en.yusufali', 46, 23, 'He said: "The Knowledge (of when it will come) is only with Allah: I proclaim to you the mission on which I have been sent: But I see that ye are a people in ignorance!"..'),
  ('en.yusufali', 46, 24, 'Then, when they saw the (Penalty in the shape of) a cloud traversing the sky, coming to meet their valleys, they said, "This cloud will give us rain!" "Nay, it is the (Calamity) ye were asking to be hastened!- A wind wherein is a Grievous Penalty!'),
  ('en.yusufali', 46, 25, '"Everything will it destroy by the command of its Lord!" Then by the morning they - nothing was to be seen but (the ruins of) their houses! thus do We recompense those given to sin!'),
  ('en.yusufali', 46, 26, 'And We had firmly established them in a (prosperity and) power which We have not given to you (ye Quraish!) and We had endowed them with (faculties of) hearing, seeing, heart and intellect: but of no profit to them were their (faculties of) hearing, sight, and heart and intellect, when they went on rejecting the Signs of Allah; and they were (completely) encircled by that which they used to mock at!'),
  ('en.yusufali', 46, 27, 'We destroyed aforetime populations round about you; and We have shown the Signs in various ways, that they may turn (to Us).'),
  ('en.yusufali', 46, 28, 'Why then was no help forthcoming to them from those whom they worshipped as gods, besides Allah, as a means of access (to Allah)? Nay, they left them in the lurch: but that was their falsehood and their invention.'),
  ('en.yusufali', 46, 29, 'Behold, We turned towards thee a company of Jinns (quietly) listening to the Qur\'an: when they stood in the presence thereof, they said, "Listen in silence!" When the (reading) was finished, they returned to their people, to warn (them of their sins).'),
  ('en.yusufali', 46, 30, 'They said, "O our people! We have heard a Book revealed after Moses, confirming what came before it: it guides (men) to the Truth and to a Straight Path.'),
  ('en.yusufali', 46, 31, '"O our people, hearken to the one who invites (you) to Allah, and believe in him: He will forgive you your faults, and deliver you from a Penalty Grievous.'),
  ('en.yusufali', 46, 32, '"If any does not hearken to the one who invites (us) to Allah, he cannot frustrate (Allah\'s Plan) on earth, and no protectors can he have besides Allah: such men (wander) in manifest error."'),
  ('en.yusufali', 46, 33, 'See they not that Allah, Who created the heavens and the earth, and never wearied with their creation, is able to give life to the dead? Yea, verily He has power over all things.'),
  ('en.yusufali', 46, 34, 'And on the Day that the Unbelievers will be placed before the Fire, (they will be asked,) "Is this not the Truth?" they will say, "Yea, by our Lord!" (One will say:) "Then taste ye the Penalty, for that ye were wont to deny (Truth)!"'),
  ('en.yusufali', 46, 35, 'Therefore patiently persevere, as did (all) messengers of inflexible purpose; and be in no haste about the (Unbelievers). On the Day that they see the (Punishment) promised them, (it will be) as if they had not tarried more than an hour in a single day. (Thine but) to proclaim the Message: but shall any be destroyed except those who transgress?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 46, 1, 'Haa-Meeeem'),
  ('en.transliteration', 46, 2, 'Tanzeelul Kitaabi minal laahil-\'Azeezil Hakeem'),
  ('en.transliteration', 46, 3, 'Maa khalaqnas samaawaati wal arda wa maa bainahumaaa illaa bilhaqqi wa ajalim musammaa; wallazeena kafaroo \'ammaaa unziroo mu\'ridoon'),
  ('en.transliteration', 46, 4, 'Qul ara\'aytum maa tad\'oona min doonil laahi aroonee maazaa khalaqoo minal ardi am lahum shirkun fis samaawaati eetoonee bi kitaabim min qabli haazaaa aw asaaratim min \'ilmin in kuntum saadiqeen'),
  ('en.transliteration', 46, 5, 'Wa man adallu mimmany yad\'oo min doonil laahi mallaa yastajeebu lahooo ilaa Yawmil Qiyaamati wa hum\'an du\'aaa\'ihim ghaafiloon'),
  ('en.transliteration', 46, 6, 'Wa izaa hushiran naasu kaanoo lahum a\'daaa\'anw wa kaanoo bi\'ibaadatihim kaafireen'),
  ('en.transliteration', 46, 7, 'Wa izaa tutlaa \'alaihim Aayaatunaa baiyinaatin qaalal lazeena kafaroo lilhaqqi lammaa jaaa\'ahum haazaa sihrum mubeen'),
  ('en.transliteration', 46, 8, 'Am yaqooloonaf taraahu qul inif taraituhoo falaa tamlikoona lee minal laahi shai\'an Huwa a\'lamu bimaa tufeedoona feehi kafaa bihee shaheedam bainee wa bainakum wa Huwal Ghafoorur Raheem'),
  ('en.transliteration', 46, 9, 'Qul maa kuntu bid\'am minal Rusuli wa maaa adreee ma yuf\'alu bee wa laa bikum in attabi\'u illaa maa yoohaaa ilaiya ya maaa ana illaa nazeerum mubeen'),
  ('en.transliteration', 46, 10, 'Qul ara\'aytum in kaana min \'indil laahi wa kafartum bihee wa shahida shaahidum mim Banee Israaa\'eela \'alaa mislihee fa aamana wastak bartum innal laaha laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 46, 11, 'Wa qaalal lazeena kafaroo lillazeena aamanoo law kaana khairam maa sabaqoonaaa ilyh; wa iz lam yahtadoo bihee fasa yaqooloona haazaaa ifkun qadeem'),
  ('en.transliteration', 46, 12, 'Wa min qablihee kitaabu Moosaaa imaamanw-wa rahmah; wa haazaa Kitaabum musad diqul lisaanan \'Arabiyyal liyunziral lazeena zalamoo wa bushraa lilmuhsineen'),
  ('en.transliteration', 46, 13, 'Innal lazeena qaaloo Rabbunal laahu summas taqaamoo falaa khawfun \'alaihim wa laahum yahzanoon'),
  ('en.transliteration', 46, 14, 'Ulaaa\'ika Ashabul Jannati khaalideena feehaa jazaaa\'am bimaa kaano ya\'maloon'),
  ('en.transliteration', 46, 15, 'Wa wassainal insaana biwaalidaihi ihsaanan hamalathu ummuhoo kurhanw-wa wada\'athu kurhanw wa hamluhoo wa fisaaluhoo salaasoona shahraa; hattaaa izaa balagha ashuddahoo wa balagho arba\'eena sanatan qaala Rabbi aqzi\'neee an ashkura ni\'matakal lateee an\'amta \'alaiya wa \'alaa waalidaiya wa an a\'mala saalihan tardaahu wa aslih lee fee zurriyyatee innee tubtu ilaika wa innee minal muslimeen'),
  ('en.transliteration', 46, 16, 'Ulaaa\'ikal lazeena nata qabbalu \'anhum ahsana maa \'amiloo wa natajaawazu \'an saiyiaatihim feee Ashaabil jannati Wa\'das sidqil lazee kaanoo yoo\'adoon'),
  ('en.transliteration', 46, 17, 'Wallazee qaala liwaali daihi uffil lakumaaa ata\'idanineee an ukhraja wa qad khalatil quroonu min qablee wa humaa yastagheesaanil laaha wailaka aamin inna wa\'dal laahi haqq, fa yaqoolu maa haazaaa illaaa asaateerul awwaleen'),
  ('en.transliteration', 46, 18, 'Ulaaa\'ikal lazeena haqqa \'alaihimul qawlu feee umamin qad khalat min qablihim minal jinni wal insi innahum kaanoo khaasireen'),
  ('en.transliteration', 46, 19, 'Wa likullin darajaatum mimmaa \'amiloo wa liyuwaf fiyahum a\'maalahum wa hum laa yuzlamoon'),
  ('en.transliteration', 46, 20, 'Wa Yawma yu\'radul lazeena kafaroo \'alan Naai azhabtum taiyibaatikum fee hayaatikumud dunyaa wastam ta\'tum bihaa fal Yawma tujzawna \'azaabal hooni bimaa kuntum tastakbiroona fil ardi bighairil haqqi wa bimaa kuntum tafsuqoon'),
  ('en.transliteration', 46, 21, 'Wazkur akhaa \'Aad, iz anzara qawmahoo bil Ahqaafi wa qad khalatin nuzuru mim baini yadaihi wa min khalfiheee allaa ta\'budooo illal laaha inneee akhaafu \'alaikum \'azaaba Yawmin \'azeem'),
  ('en.transliteration', 46, 22, 'Qaaloo aji\'tanaa litaa fikanaa \'an aalihatinaa faatinaa bimaa ta\'idunaaa in kunta minas saadiqeen'),
  ('en.transliteration', 46, 23, 'Qaala innamal \'ilmu indal laahi wa uballighukum maaa uriltu bihee wa laakinneee araakum qawman tajhaloon'),
  ('en.transliteration', 46, 24, 'Falammaa ra awhu \'aaridam mustaqbila awdiyatihim qaaloo haazaa \'aaridum mumtirunaa; bal huwa masta\'jaltum bihee reehun feehaa \'azaabun aleem'),
  ('en.transliteration', 46, 25, 'Tudammiru kulla shai\'im bi-amri Rabbihaa fa asbahoo laa yuraaa illaa masaakinuhum; kazaalika najzil qawmal mujrimeen'),
  ('en.transliteration', 46, 26, 'Wa laqad makkannaahum feemaaa im makkannaakum feehi waj\'alnaa lahum sam\'anw wa absaaranw wa af\'idatan famaaa aghnaa \'anhum samu\'uhum wa laaa absaaruhum wa laaa af\'idatuhum min shai\'in iz kaanoo yajhadoona bi Aayaatil laahi wa haaqa bihim maa kaanoo bihee yastahzi\'oon'),
  ('en.transliteration', 46, 27, 'Wa laqad ahlaknaa ma hawlakum minal quraa wa sarrafnal Aayaati la\'allahum yarji\'oon'),
  ('en.transliteration', 46, 28, 'Falaw laa nasarahumul lazeenat takhazoo min doonil laahi qurbaanan aalihatam bal dalloo \'anhum\' wa zaalika ifkuhum wa maa kaanoo yaftaroon'),
  ('en.transliteration', 46, 29, 'Wa iz sarafinaaa ilaika nafaram minal jinni yastami\'oonal Quraana falammaa hadaroohu qaalooo ansitoo falammaa qudiya wallaw ilaa qawmihim munzireen'),
  ('en.transliteration', 46, 30, 'Qaaloo yaa qawmanaaa innaa sami\'naa Kitaaban unzila mim ba\'di Moosa musaddiqal limaa baina yadihi yahdeee ilal haqqi wa ilaa Tareeqim Mustaqeem'),
  ('en.transliteration', 46, 31, 'Yaa qawmanaaa ajeeboo daa\'iyal laahi wa aaminoo bihee yaghfir lakum min zunoobikum wa yujirkum min \'azaabin aleem'),
  ('en.transliteration', 46, 32, 'Wa mal laa yujib daa\'iyal laahi falaisa bimu\'jizin fil ardi wa laisa lahoo min dooniheee awliyaaa\'; ulaaa ika fee dalaalim mubeen'),
  ('en.transliteration', 46, 33, 'Awalam yaraw annal laahal lazee khalaqas samaawaati wal larda wa lam ya\'ya bikhal qihinna biqaadirin \'alaaa anyyuhiyal mawtaa; balaaa innahoo \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 46, 34, 'Wa Yawma yu\'radul lazeena kafaroo \'alan naari alaisa haaza bil haqq; qaaloo balaa wa Rabbinaa; qaala fazooqul \'azaaba bimaa kuntum takfuroon'),
  ('en.transliteration', 46, 35, 'Fasbir kamaa sabara ulul \'azmi minar Rusuli wa laa tasta\'jil lahum; ka annahum Yawma yarawna maa yoo\'adoona lam yalbasooo illaa saa\'atam min nahaar; balaagh; fahal yuhlaku illal qawmul faasiqoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 46, 1, 'حمۤ'),
  ('ur.ahmedali', 46, 2, 'یہ کتاب الله کی طرف سے اتاری گئی ہے جو غالب حکمت والا ہے'),
  ('ur.ahmedali', 46, 3, 'ہم نے آسمانوں اور زمین کو اور جو ان کے درمیان ہے کسی مصلحت ہی سے اور ایک خاص وقت تک کے لیے پیدا کیا ہے اورکافروں کو جس چیز سے ڈرایا جاتا ہے اس سے منہ پھیر لیتے ہیں'),
  ('ur.ahmedali', 46, 4, 'کہہ دو بھلا بتاؤ تو سہی جنہیں تم الله کے سوا پکارتے ہو مجھے دکھاؤ کہ انہوں نے زمین میں کون سی چیز پیدا کی ہے یا آسمانوں میں ان کا کوئی حصہ ہے میرے پاس اس سے پہلے کی کوئی کتاب لاؤ یا کوئی علم چلا آتا ہو وہ لاؤ اگر تم سچے ہو'),
  ('ur.ahmedali', 46, 5, 'اور اس سے بڑھ کر کون گمراہ ہے جو الله کےسوا اسےپکارتا ہے جو قیامت تک اس کے پکارنے کا جواب نہ دے سکے اور انہیں ان کے پکارنے کی خبر بھی نہ ہو'),
  ('ur.ahmedali', 46, 6, 'او ر جب لوگ جمع کئےجائیں گے تو وہ ان کے دشمن ہو جائیں گے اور ان کی عبادت کے منکر ہوں گے'),
  ('ur.ahmedali', 46, 7, 'اور جب ان پر ہماری واضح آیتیں پڑھی جاتی ہیں تو کافر حق کو کہتے ہیں جب وہ ان کے پاس آچکا کہ یہ تو کھلم کھلاجادوہے'),
  ('ur.ahmedali', 46, 8, 'کیا وہ کہتے ہیں آپ نے اسے خود بنا لیا ہے کہہ دو اگر میں نے اسے خود بنا لیا ہے تو تم مجھے الله سے بچانے کی کچھ بھی طاقت نہیں رکھتے وہی بہتر جانتا ہے جو باتیں تم اس میں بناتے ہو میرے اور تمہارے درمیان وہی گواہ کافی ہے اور وہ بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 46, 9, 'کہہ دو میں کوئی انوکھا رسول نہیں ہوں اور میں نہیں جانتا کہ میرے ساتھ کیا کیا جائے گا اور نہ تمہارے ساتھ میں نہیں پیروی کرتا مگر اس کی جو میری طرف وحی کیا جاتا ہے سوائے اس کے نہیں کہ میں کھلم کھلا ڈرانے والا ہوں'),
  ('ur.ahmedali', 46, 10, 'کہہ دو بتاؤ تو سہی اگر یہ کتاب الله کی طرف سے ہو اور تم اس کے منکر ہو اور بنی اسرائیل کا ایک گواہ ایک ایسی کتاب پر گواہی دے کر ایمان بھی لے آیا اور تم اکڑے ہی رہے بے شک الله ظالموں کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 46, 11, 'اور کافروں نے ایمانداروں سے کہا اگر یہ دین بہتر ہوتا تو یہ اس پر ہم سے پہلے نہ دوڑ کر جاتے اورجب انہوں نے اس کے ذریعے سے ہدایت نہیں پائی تو کہیں گے یہ تو پرانا جھوٹ ہے'),
  ('ur.ahmedali', 46, 12, 'اور اس سے پہلے موسیٰ کی کتاب ہے جو رہنما اور رحمت تھی او ریہ کتاب ہے جو اسے سچا کرتی ہے عربی زبان میں ظالموں کو ڈرانے کے لیے اور نیکوں کو خوشخبری دینے کے لیے'),
  ('ur.ahmedali', 46, 13, 'بے شک جنہوں نے کہا کہ ہمارا رب الله ہے پھر اسی پر جمے رہے پس ان پر کوئی خوف نہیں اور نہ وہ غمگین ہوں گے'),
  ('ur.ahmedali', 46, 14, 'یہی بہشتی ہیں اس میں ہمیشہ رہیں گے بدلےان کاموں کے جو وہ کیا کرتے تھے'),
  ('ur.ahmedali', 46, 15, 'اور ہم نے انسان کو اپنے والدین کے ساتھ نیکی کرنے کی تاکید کی کہ اسے اس کی ماں نے تکلیف سے اٹھائے رکھا اور اسے تکلیف سے جنا اوراس کا حمل اور دودھ کا چھڑانا تیس مہینے ہیں یہاں تک کہ جب وہ اپنی جوانی کو پہنچا اور چالیں سال کی عمر کو پہنچا تو اس نے کہا اے میرے رب مجھے توفیق دے کہ میں تیری نعمت کا شکر ادا کروں جو تو نے مجھ پر انعام کی اور میرے والدین پر اور میں نیک عمل کروں جسے تو پسند کرے اور میرے لیے میری اولاد میں اصلاح کر بے شک میں تیری طرف رجوع کرتا ہوں اور بے شک میں فرمانبردار میں ہوں'),
  ('ur.ahmedali', 46, 16, 'یہی وہ لوگ ہیں جن سے ہم وہ نیک عمل قبول کرتے ہیں جو انہوں نے کیے اور بہشتیوں میں شامل کر کے ان کے گناہوں سے درگزر کرتے ہیں یہ اس سچے وعدے کے مطابق ہے جو ان سے کیا گیا تھا'),
  ('ur.ahmedali', 46, 17, 'اور جس نے اپنے ماں باپ سے کہا کہ تم پر تف ہے کیاتم مجھے یہ وعدہ دیتے ہو کہ میں قبر سے نکالا جاؤں گا حالانکہ مجھ سے پہلے بہت سی امتیں گزر گئیں اور وہ دونوں الله سے فریاد کر رہے ہیں کہ ارے تیرا ناس ہو ایمان لا بے شک الله کاوعدہ سچا ہے پھر وہ کہتا ہے یہ ہے کیا مگر پہلوں کے افسانے'),
  ('ur.ahmedali', 46, 18, 'یہ وہ لوگ ہیں کہ ان کے حق میں بھی ان لوگوں کے ساتھ الله کا قول پورا ہو کر رہا جو ان سے پہلے جن اور انسان ہوگزرے ہیں بے شک وہی خسارہ اٹھانے والے ہیں'),
  ('ur.ahmedali', 46, 19, 'اور ہر ایک کے لیے اپنے اپنے اعمال کے مطابق درجے ہیں تاکہ الله ان کے اعمال کا انہیں پورا عوض دے اور ان پر کچھ بھی ظلم نہ ہوگا'),
  ('ur.ahmedali', 46, 20, 'اور جس دن کافر آگ کے روبرو لائے جائیں گے ان سے (کہا جائے گا) تم (اپنا حصہ) پاک چیزو ں میں سے اپنی دنیا کی زندگی میں لے چکے اور تم ان سے فائدہ اٹھا چکے پس آج تمہیں ذلت کا عذاب دیا جائے گا بدلے اس کے جو تم زمین میں ناحق اکڑا کرتے تھے اوربدلے اس کے جو تم نافرمانی کیاکرتے تھے'),
  ('ur.ahmedali', 46, 21, 'اور قوم عاد کے بھائی کا ذکر کر جب اس نے اپنی قوم کو (وادی) احقاف میں ڈرایا اور اس سے پہلے اورپیچھے کئی ڈرانے والے گزرے کہ سوائے الله کے کسی کی عبادت نہ کرو بے شک میں تم پر ایک بڑے دن کے عذاب سے ڈرتا ہوں'),
  ('ur.ahmedali', 46, 22, 'انہوں نے کہا کیا تو ہمارے پاس اس لیے آیا ہے کہ تو ہمیں ہمارے معبودوں سے بہکا دے پس ہم پردہ (عذاب) لے آ جس کا تو ہم سے وعدہ کرتا ہے اگر تو سچا ہے'),
  ('ur.ahmedali', 46, 23, 'اس نے کہا اس کا علم تو الله کے پاس ہے اورمیں تمہیں وہ (پیغام) پہنچاتا ہوں جو میں دے کر بھیجا گیا ہوں لیکن میں تمہیں دیکھ رہا ہوں تم ایک جاہل قوم ہو'),
  ('ur.ahmedali', 46, 24, 'پھر جب انہوں نے اسے دیکھا کہ وہ ایک ابر ہے جو ان کے میدانوں کی طرف بڑھا چلا آ رہا ہے کہنے لگے کہ یہ تو ابر ہے جو ہم پر برسے گا (نہیں) بلکہ یہ وہی ہے جسے تم جلدی چاہتے تھے یعنی آندھی جس میں دردناک عذاب ہے'),
  ('ur.ahmedali', 46, 25, 'وہ اپنے رب کے حکم سے ہر ایک چیز کو برباد کر دے گی پس وہ صبح کو ایسے ہو گئے کہ سوائے ان کے گھروں کے کچھ نظر نہ آتا تھا ہم اسی طرح مجرم لوگوں کو سزا دیا کرتے ہیں'),
  ('ur.ahmedali', 46, 26, 'اور ہم نے ان لوگوں کو ان باتوں میں قدرت دی تھی کہ تمہیں ان باتوں میں قدرت نہیں دی اور ہم نے انہیں کان اور آنکھیں اور دل دیئے تھے پھر نہ تو ان کے کان ہی کام آئے اور نہ ان کی آنکھیں ہی کام آئیں او رنہ ان کے دل ہی کچھ کام آئے کیوں کہ وہ الله کی آیتوں کو انکار ہی کرتے رہے اور جس عذاب کا وہ ٹھٹھا اڑیا کرتے تھے ان پر آن پڑا'),
  ('ur.ahmedali', 46, 27, 'اور ہم ہلاک کر چکے ہیں جو تمہارے آس پاس بستیاں ہیں اور طرح طرح کے اپنے نشان قدرت بھی دکھائے تاکہ وہ باز آجائيں'),
  ('ur.ahmedali', 46, 28, 'پھر ان معبودوں نے کیوں نہ مدد کی جن کو انہوں نے الله کے سوا مرتبہ حاصل کرنے کے لیے معبود بنا رکھا تھا بلکہ وہ تو ان سے کھو ئےگئے تھے اور یہ ان کا جھوٹ تھا اور جو کچھ وہ ڈھکوسلے بنایا کرتےتھے'),
  ('ur.ahmedali', 46, 29, 'اورجب ہم نے آپ کی طرف چند ایک جنوں کو پھیر دیا جو قرآن سن رہے تھے پس جب وہ آپ کے پاس حاصر ہوئے تو کہنے لگے چپ رہو پھر جب ختم ہوا تو اپنی قوم کی طرف واپس لوٹے ایسے حال میں کہ وہ ڈرانے والے تھے'),
  ('ur.ahmedali', 46, 30, 'کہنے لگے اےہماری قوم بیشک ہم نے ایک کتاب سنی ہے جو موسیٰ کے بعد نازل ہوئی ہے ان کی تصدیق کرنے والی ہے جو اس سے پہلے ہو چکیں حق کی طرف ا ور سیدھے راستہ کی طرف رہنمائی کرتی ہے'),
  ('ur.ahmedali', 46, 31, 'اے ہماری قوم الله کی طرف بلانے والے کو مان لو اور اس پر ایمان لے آؤ وہ تمہارے لیے تمہارے گناہ بخش دے گا اور تمہیں دردناک عذاب سے بچا لے گا'),
  ('ur.ahmedali', 46, 32, 'اور جو الله کی طرف بلانے والے کو نہ مانے گا تو وہ زمین میں اسے عاجر نہیں کر سکے گا اور الله کے سوا اس کا کوئی مددگار نہ ہوگا یہی لوگ صریح گمراہی میں ہیں'),
  ('ur.ahmedali', 46, 33, 'کیا انہوں نے نہیں دیکھا جس الله نے آسمانوں اور زمین کو پیدا کرنے میں نہیں تھکا اس پر قاد رہے کہ مردوں کو زندہ کردے کیوں نہیں وہ تو ہر ایک چیز پر قادر ہے'),
  ('ur.ahmedali', 46, 34, 'اور جس دن کافر آگ کے سامنے لائے جائیں گے (ان سے کہا جائے گا) کیا یہ امر واقعی نہیں ہے کہیں گے ہمیں اپنے رب کی قسم ضرور امر واقعی ہے ارشاد ہو گا تواپنے کفر کے بدلہ میں اس کا عذاب چکھو'),
  ('ur.ahmedali', 46, 35, 'پھر صبرکر جیسا کہ عالی ہمت رسولوں نے کیا ہے اور ان کے لیے جلدی نہ کر گویا کہ وہ جس دن عذاب دیکھیں گے جس کا ان سے وعدہ کیا جاتا ہے (تو انہیں ایسا معلوم ہو گا) کہ ایک دن میں سے ایک گھڑی بھر رہے تھے آپ کا کام پہنچا دینا تھا سو کیا نافرمان لوگوں کے سوا اور کوئی ہلاک ہوگا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 46, 1, 'Ha, Mim.'),
  ('tr.diyanet', 46, 2, 'Bu Kitap\'ın indirilmesi güçlü olan, Hakim olan Allah katındandır.'),
  ('tr.diyanet', 46, 3, 'Biz, gökleri, yeri ve ikisinin arasında bulunanları, ancak gerçek üzere ve belirli bir süre için yarattık; inkar edenler, uyarıldıkları şeylerden yüz çevirmektedirler.'),
  ('tr.diyanet', 46, 4, 'De ki: "Allah\'ı bırakıp taptığınız şeyleri görüyor musunuz? Yeryüzünde ne yaratmışlar bana göstersenize! Yoksa Allah\'la ortaklıkları göklerde midir? Eğer doğru sözlü iseniz, size indirilmiş bir kitap veya intikal etmiş bir bilgi kalıntısı varsa bana getirin."'),
  ('tr.diyanet', 46, 5, 'Allah\'ı bırakıp da, kıyamet gününe kadar cevap veremeyecek şeylere yalvarandan daha sapık kimdir? Çünkü, yalvardıkları şeyler yalvarışlarından habersizdirler.'),
  ('tr.diyanet', 46, 6, 'Ama, insanlar kıyamet günü toplatılınca, putları onlara düşman olurlar ve tapınmalarını inkar ederler.'),
  ('tr.diyanet', 46, 7, 'Ayetlerimiz onlara açıkça okunduğu zaman inkar edenler, kendilerine gelen gerçek için: "Bu, apaçık bir büyüdür" derler.'),
  ('tr.diyanet', 46, 8, 'Veya, "onu uydurdu" derler. De ki: "Eğer onu uydurdumsa, beni Allah\'a karşı hiçbir şekilde savunamazsınız; O, Kuran için yaptığınız taşkınlıkları daha iyi bilir. Benimle sizin aranızda şahit olarak O yeter. O, bağışlayandır, merhamet edendir."'),
  ('tr.diyanet', 46, 9, 'De ki: "Ben peygamberlerin ilki değilim; benim ve sizin başınıza gelecekleri bilmem; ben ancak bana vahyolunana uymaktayım; ben sadece apaçık bir uyarıcıyım."'),
  ('tr.diyanet', 46, 10, 'De ki: "Eğer bu Kitap Allah katından ise ve siz de onu inkar etmişseniz; İsrailoğullarından bir şahit de bunun böyle olduğuna şehadet edip de inanmışken, siz yine de büyüklük taslarsınız, bana söyleyin kendinize yazık etmiş olmaz mısınız?" Doğrusu Allah zalim milleti doğru yola eriştirmez.'),
  ('tr.diyanet', 46, 11, 'İnkar edenler, inananlar için: "Eğer İslamiyet\'te bir hayır olsaydı, bu hususta bizden öne geçemezlerdi" derler. Bununla doğru yola girmedikleri için de, "Bu, eski bir uydurmadır" derler.'),
  ('tr.diyanet', 46, 12, 'Kuran\'dan önce, Musa\'nın kitabı (Tevrat), bir rahmet ve rehberdi. Bu Kuran da, zulmedenleri uyarmak ve iyi davrananlara müjde olmak üzere Arap diliyle indirilmiş, kendinden öncekileri doğrulayan bir Kitap\'dır.'),
  ('tr.diyanet', 46, 13, 'Doğrusu, "Rabbimiz Allah\'tır" deyip, sonra da dosdoğru gidenlere korku yoktur, onlar üzülmeyeceklerdir.'),
  ('tr.diyanet', 46, 14, 'İşte onlar, cennetliklerdir; işlediklerine karşılık olarak, içinde temelli kalacaklardır.'),
  ('tr.diyanet', 46, 15, 'Biz insana, anne ve babasına karşı iyi davranmasını tavsiye etmişizdir; zira annesi, onu, karnında, zorluğa uğrayarak taşımış; onu güçlükle doğurmuştur. Taşınması ve sütten kesilmesi otuz ay sürer. Sonunda erginlik çağına erince ve kırk yaşına varınca: "Rabbim! Bana ve anne babama verdiğin nimete şükretmemi ve benim hoşnut olacağın yararlı bir işi yapmamı sağla; bana verdiğin gibi soyuma da salah ver; doğrusu Sana yöneldim, ben, kendini Sana verenlerdenim" demesi gerekir.'),
  ('tr.diyanet', 46, 16, 'İşte, işlediklerini en güzel şekilde kabul ettiğimiz ve kötülüklerini geçtiğimiz bu kimseler, cennetlikler içindedirler. Bu, verilen doğru bir sözdür.'),
  ('tr.diyanet', 46, 17, 'Annesine babasına: "Of ikinizden; benden önce nice nesiller gelip geçmişken beni tekrar diriltilmemle mi tehdit ediyorsunuz?" diyen kimseye, anne babası Allah\'a sığınarak: "Sana yazıklar olsun! İnan; doğrusu Allah\'ın sözü gerçektir" dedikleri halde: "Bu, Kuran öncekilerin masallarından başka bir şey değildir" diye cevap verenler işte onlar kendilerinden önce cinlerden ve insanlardan gelip geçmiş ümmetler içinde, Allah\'ın azap vadinin aleyhlerinde gerçekleştiği kimselerdir. Doğrusu onlar hüsranda olanlardır.'),
  ('tr.diyanet', 46, 18, 'Annesine babasına: "Of ikinizden; benden önce nice nesiller gelip geçmişken beni tekrar diriltilmemle mi tehdit ediyorsunuz?" diyen kimseye, anne babası Allah\'a sığınarak: "Sana yazıklar olsun! İnan; doğrusu Allah\'ın sözü gerçektir" dedikleri halde: "Bu, Kuran öncekilerin masallarından başka bir şey değildir" diye cevap verenler işte onlar kendilerinden önce cinlerden ve insanlardan gelip geçmiş ümmetler içinde, Allah\'ın azap vadinin aleyhlerinde gerçekleştiği kimselerdir. Doğrusu onlar hüsranda olanlardır.'),
  ('tr.diyanet', 46, 19, 'İşlediklerinden ötürü herkesin bir derecesi vardır. Herkese işlediklerinin karşılığı ödenir. Kendilerine haksızlık yapılmaz.'),
  ('tr.diyanet', 46, 20, 'İnkar edenler, ateşe sunuldukları gün, onlara: "Dünyadaki hayatınızda sizin için güzel olan her şeyi harcadınız, onların zevkini sürdünüz; ama bugün, yeryüzünde haksız yere büyüklük taslamanızın ve yoldan çıkmanızın karşılığında alçaltıcı bir azap göreceksiniz"'),
  ('tr.diyanet', 46, 21, 'Ad milletinin kardeşi Hud\'u an; ondan önce ve sonra, "Allah\'tan başkasına kulluk etmeyin" diyen nice uyarıcılar gelip geçmişken, Ahkaf bölgesindeki milletini uyarmış "Doğrusu sizin için, büyük günün azabından korkuyorum" demişti.'),
  ('tr.diyanet', 46, 22, '"Bize, bizi tanrılarımızdan alıkoymak için mi geldin? Doğru sözlülerden isen, bizi tehdit ettiğin şeyi başımıza getir" dediler.'),
  ('tr.diyanet', 46, 23, '"Doğrusu bunun ne zaman geleceğini Allah bilir; ben size benimle gönderileni tebliğ ediyorum; fakat sizin cahil bir millet olduğunuzu görüyorum." dedi.'),
  ('tr.diyanet', 46, 24, 'O azabın, yayılarak vadilerine doğru yöneldiğini gördüklerinde: "Bu yaygın bulut bize yağmur yağdıracaktır" dediler. Hud: "Hayır, o, acele beklediğiniz şeydir; can yakıcı azap veren bir rüzgardır; Rabbinin buyruğu ile her şeyi yok eder" dedi. Bunun üzerine evlerinin harabelerinden başka bir şey görünmez oldu. Biz, suçlu milleti işte böyle cezalandırırız.'),
  ('tr.diyanet', 46, 25, 'O azabın, yayılarak vadilerine doğru yöneldiğini gördüklerinde: "Bu yaygın bulut bize yağmur yağdıracaktır" dediler. Hud: "Hayır, o, acele beklediğiniz şeydir; can yakıcı azap veren bir rüzgardır; Rabbinin buyruğu ile her şeyi yok eder" dedi. Bunun üzerine evlerinin harabelerinden başka bir şey görünmez oldu. Biz, suçlu milleti işte böyle cezalandırırız.'),
  ('tr.diyanet', 46, 26, 'And olsun ki onlara, size vermediğimiz servet ve imkanı vermiştik. Onlara kulaklar, gözler ve kalbler vermiştik; ama kulakları, gözleri ve kalbleri onlara bir fayda sağlamadı, zira, Allah\'ın ayetlerini bile bile inkar ediyorlardı, alaya aldıkları şeyler onları kuşatıp yokediverdi.'),
  ('tr.diyanet', 46, 27, 'And olsun ki, çevrenizde bulunan birçok kentleri yok etmişizdir. Belki doğru yola dönerler diye ayetleri türlü türlü anlatmışızdır.'),
  ('tr.diyanet', 46, 28, 'O zamanlar, Allah\'ı bırakıp da O\'na yakınlık peyda etmek için edindikleri tanrılar kendilerine yardım etmeli değil miydi? Ama tanrıları onlardan uzaklaştılar. Bu, onların yalanı ve uydurup durdukları şeydir.'),
  ('tr.diyanet', 46, 29, 'Kuran\'ı dinleyecek cinlerden bir takımını sana yöneltmiştik. Onlar Kuran\'ı dinlemeğe hazır olunca birbirlerine: "Susun" dediler. Kuran\'ın okunması bitince, her biri birer uyarıcı olarak milletlerine döndüler.'),
  ('tr.diyanet', 46, 30, 'Şöyle dediler: "Ey milletimiz! Doğrusu biz, Musa\'dan sonra indirilen, kendinden öncekileri doğrulayan, gerçeği ve doğru yolu gösteren bir kitap dinledik."'),
  ('tr.diyanet', 46, 31, '"Ey milletimiz! Allah\'a çağırana (Muhammed\'e) uyun ve O\'na inanın da Allah da sizin günahlarınızı bağışlasın ve sizi can yakıcı azabdan korusun."'),
  ('tr.diyanet', 46, 32, 'Allah\'a çağırana uymayan kimse bilsin ki, Allah\'ı yeryüzünde aciz bırakamaz; onların O\'ndan başka dostları da bulunmaz; işte onlar apaçık sapıklıktadırlar.'),
  ('tr.diyanet', 46, 33, 'Gökleri, yeri yaratan ve onları yaratmaktan yorulmayan Allah\'ın, ölüleri diriltmeye de kadir olduğunu görmezler mi? Evet; O her şeye Kadir\'dir.'),
  ('tr.diyanet', 46, 34, 'İnkar edenler, ateşe sunuldukları gün onlara: "Bu, gerçek değil miydi?" denir, onlar: "Rabbimize and olsun ki evet gerçekti" derler. Allah: "İnkar etmenizden ötürü azabı tadın" der.'),
  ('tr.diyanet', 46, 35, 'Peygamberlerden azim sahibi olanların sabrettiği gibi sen de sabret; inkarcılar için acele etme; onlar, kendilerine söz verileni gördükleri gün dünyada sadece gündüzün bir müddeti eğlendiklerini sanırlar. Bu bir bildiridir; yoldan çıkmış olanlardan başkası mı yok edilir?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 46, 1, 'Haa Miim.'),
  ('id.indonesian', 46, 2, 'Diturunkan Kitab ini dari Allah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 46, 3, 'Kami tiada menciptakan langit dan bumi dan apa yang ada antara keduanya melainkan dengan (tujuan) yang benar dan dalam waktu yang ditentukan. Dan orang-orang yang kafir berpaling dari apa yang diperingatkan kepada mereka.'),
  ('id.indonesian', 46, 4, 'Katakanlah: "Terangkanlah kepadaku tentang apa yang kamu sembah selain Allah; perlihatkan kepada-Ku apakah yang telah mereka ciptakan dari bumi ini atau adakah mereka berserikat (dengan Allah) dalam (penciptaan) langit? Bawalah kepada-Ku Kitab yang sebelum (Al Quran) ini atau peninggalan dari pengetahuan (orang-orang dahulu), jika kamu adalah orang-orang yang benar"'),
  ('id.indonesian', 46, 5, 'Dan siapakah yang lebih sesat daripada orang yang menyembah sembahan-sembahan selain Allah yang tiada dapat memperkenankan (doa)nya sampai hari kiamat dan mereka lalai dari (memperhatikan) doa mereka?'),
  ('id.indonesian', 46, 6, 'Dan apabila manusia dikumpulkan (pada hari kiamat) niscaya sembahan-sembahan itu menjadi musuh mereka dan mengingkari pemujaan-pemujaan mereka.'),
  ('id.indonesian', 46, 7, 'Dan apabila dibacakan kepada mereka ayat-ayat Kami yang menjelaskan, berkatalah orang-orang yang mengingkari kebenaran ketika kebenaran itu datang kepada mereka: "Ini adalah sihir yang nyata".'),
  ('id.indonesian', 46, 8, 'Bahkan mereka mengatakan: "Dia (Muhammad) telah mengada-adakannya (Al Quran)". Katakanlah: "Jika aku mengada-adakannya, maka kamu tiada mempunyai kuasa sedikitpun mempertahankan aku dari (azab) Allah itu. Dia lebih mengetahui apa-apa yang kamu percakapkan tentang Al Quran itu. Cukuplah Dia menjadi saksi antaraku dan antaramu dan Dialah Yang Maha Pengampun lagi Maha Penyayang".'),
  ('id.indonesian', 46, 9, 'Katakanlah: "Aku bukanlah rasul yang pertama di antara rasul-rasul dan aku tidak mengetahui apa yang akan diperbuat terhadapku dan tidak (pula) terhadapmu. Aku tidak lain hanyalah mengikuti apa yang diwahyukan kepadaku dan aku tidak lain hanyalah seorang pemberi peringatan yang menjelaskan".'),
  ('id.indonesian', 46, 10, 'Katakanlah: "Terangkanlah kepadaku, bagaimanakah pendapatmu jika Al Quran itu datang dari sisi Allah, padahal kamu mengingkarinya dan seorang saksi dari Bani Israil mengakui (kebenaran) yang serupa dengan (yang tersebut dalam) Al Quran lalu dia beriman, sedang kamu menyombongkan diri. Sesungguhnya Allah tiada memberi petunjuk kepada orang-orang yang zalim".'),
  ('id.indonesian', 46, 11, 'Dan orang-orang kafir berkata kepada orang-orang yang beriman: "Kalau sekiranya di (Al Quran) adalah suatu yang baik, tentulah mereka tiada mendahului kami (beriman) kepadanya. Dan karena mereka tidak mendapat petunjuk dengannya maka mereka akan berkata: "Ini adalah dusta yang lama".'),
  ('id.indonesian', 46, 12, 'Dan sebelum Al Quran itu telah ada kitab Musa sebagai petunjuk dan rahmat. Dan ini (Al Quran) adalah kitab yang membenarkannya dalam bahasa Arab untuk memberi peringatan kepada orang-orang yang zalim dan memberi kabar gembira kepada orang-orang yang berbuat baik.'),
  ('id.indonesian', 46, 13, 'Sesungguhnya orang-orang yang mengatakan: "Tuhan kami ialah Allah", kemudian mereka tetap istiqamah maka tidak ada kekhawatiran terhadap mereka dan mereka tiada (pula) berduka cita.'),
  ('id.indonesian', 46, 14, 'Mereka itulah penghuni-penghuni surga, mereka kekal di dalamnya; sebagai balasan atas apa yang telah mereka kerjakan.'),
  ('id.indonesian', 46, 15, 'Kami perintahkan kepada manusia supaya berbuat baik kepada dua orang ibu bapaknya, ibunya mengandungnya dengan susah payah, dan melahirkannya dengan susah payah (pula). Mengandungnya sampai menyapihnya adalah tiga puluh bulan, sehingga apabila dia telah dewasa dan umurnya sampai empat puluh tahun ia berdoa: "Ya Tuhanku, tunjukilah aku untuk mensyukuri nikmat Engkau yang telah Engkau berikan kepadaku dan kepada ibu bapakku dan supaya aku dapat berbuat amal yang saleh yang Engkau ridhai; berilah kebaikan kepadaku dengan (memberi kebaikan) kepada anak cucuku. Sesungguhnya aku bertaubat kepada Engkau dan sesungguhnya aku termasuk orang-orang yang berserah diri".'),
  ('id.indonesian', 46, 16, 'Mereka itulah orang-orang yang Kami terima dari mereka amal yang baik yang telah mereka kerjakan dan Kami ampuni kesalahan-kesalahan mereka, bersama penghuni-penghuni surga, sebagai janji yang benar yang telah dijanjikan kepada mereka.'),
  ('id.indonesian', 46, 17, 'Dan orang yang berkata kepada dua orang ibu bapaknya: "Cis bagi kamu keduanya, apakah kamu keduanya memperingatkan kepadaku bahwa aku akan dibangkitkan, padahal sungguh telah berlalu beberapa umat sebelumku? lalu kedua ibu bapaknya itu memohon pertolongan kepada Allah seraya mengatakan: "Celaka kamu, berimanlah! Sesungguhnya janji Allah adalah benar". Lalu dia berkata: "Ini tidak lain hanyalah dongengan orang-orang dahulu belaka".'),
  ('id.indonesian', 46, 18, 'Mereka itulah orang-orang yang telah pasti ketetapan (azab) atas mereka bersama umat-umat yang telah berlalu sebelum mereka dari jin dan manusia. Sesungguhnya mereka adalah orang-orang yang merugi.'),
  ('id.indonesian', 46, 19, 'Dan bagi masing-masing mereka derajat menurut apa yang telah mereka kerjakan dan agar Allah mencukupkan bagi mereka (balasan) pekerjaan-pekerjaan mereka sedang mereka tiada dirugikan.'),
  ('id.indonesian', 46, 20, 'Dan (ingatlah) hari (ketika) orang-orang kafir dihadapkan ke neraka (kepada mereka dikatakan): "Kamu telah menghabiskan rezekimu yang baik dalam kehidupan duniawimu (saja) dan kamu telah bersenang-senang dengannya; maka pada hari ini kamu dibalasi dengan azab yang menghinakan karena kamu telah menyombongkan diri di muka bumi tanpa hak dan karena kamu telah fasik".'),
  ('id.indonesian', 46, 21, 'Dan ingatlah (Hud) saudara kaum \'Aad yaitu ketika dia memberi peringatan kepada kaumnya di Al Ahqaaf dan sesungguhnya telah terdahulu beberapa orang pemberi peringatan sebelumnya dan sesudahnya (dengan mengatakan): "Janganlah kamu menyembah selain Allah, sesungguhnya aku khawatir kamu akan ditimpa azab hari yang besar".'),
  ('id.indonesian', 46, 22, 'Mereka menjawab: "Apakah kamu datang kepada kami untuk memalingkan kami dari (menyembah) tuhan-tuhan kami? Maka datangkanlah kepada kami azab yang telah kamu ancamkan kepada kami jika kamu termasuk orang-orang yang benar".'),
  ('id.indonesian', 46, 23, 'Ia berkata: "Sesungguhnya pengetahuan (tentang itu) hanya pada sisi Allah dan aku (hanya) menyampaikan kepadamu apa yang aku diutus dengan membawanya tetapi aku lihat kamu adalah kaum yang bodoh".'),
  ('id.indonesian', 46, 24, 'Maka tatkala mereka melihat azab itu berupa awan yang menuju ke lembah-lembah mereka, berkatalah mereka: "Inilah awan yang akan menurunkan hujan kepada kami". (Bukan!) bahkan itulah azab yang kamu minta supaya datang dengan segera (yaitu) angin yang mengandung azab yang pedih,'),
  ('id.indonesian', 46, 25, 'yang menghancurkan segala sesuatu dengan perintah Tuhannya, maka jadilah mereka tidak ada yang kelihatan lagi kecuali (bekas-bekas) tempat tinggal mereka. Demikianlah Kami memberi balasan kepada kaum yang berdosa.'),
  ('id.indonesian', 46, 26, 'Dan sesungguhnya Kami telah meneguhkan kedudukan mereka dalam hal-hal yang Kami belum pernah meneguhkan kedudukanmu dalam hal itu dan Kami telah memberikan kepada mereka pendengaran, penglihatan dan hati; tetapi pendengaran, penglihatan dan hati mereka itu tidak berguna sedikit juapun bagi mereka, karena mereka selalu mengingkari ayat-ayat Allah dan mereka telah diliputi oleh siksa yang dahulu selalu mereka memperolok-olokkannya.'),
  ('id.indonesian', 46, 27, 'Dan sesungguhnya Kami telah membinasakan negeri-negeri di sekitarmu dan Kami telah mendatangkan tanda-tanda kebesaran Kami berulang-ulang supaya mereka kembali (bertaubat).'),
  ('id.indonesian', 46, 28, 'Maka mengapa yang mereka sembah selain Allah sebagai Tuhan untuk mendekatkan diri (kepada Allah) tidak dapat menolong mereka. Bahkan tuhan-tuhan itu telah lenyap dari mereka? Itulah akibat kebohongan mereka dan apa yang dahulu mereka ada-adakan.'),
  ('id.indonesian', 46, 29, 'Dan (ingatlah) ketika Kami hadapkan serombongan jin kepadamu yang mendengarkan Al Quran, maka tatkala mereka menghadiri pembacaan(nya) lalu mereka berkata: "Diamlah kamu (untuk mendengarkannya)". Ketika pembacaan telah selesai mereka kembali kepada kaumnya (untuk) memberi peringatan.'),
  ('id.indonesian', 46, 30, 'Mereka berkata: "Hai kaum kami, sesungguhnya kami telah mendengarkan kitab (Al Quran) yang telah diturunkan sesudah Musa yang membenarkan kitab-kitab yang sebelumnya lagi memimpin kepada kebenaran dan kepada jalan yang lurus.'),
  ('id.indonesian', 46, 31, 'Hai kaum kami, terimalah (seruan) orang yang menyeru kepada Allah dan berimanlah kepada-Nya, niscaya Allah akan mengampuni dosa-dosa kamu dan melepaskan kamu dari azab yang pedih.'),
  ('id.indonesian', 46, 32, 'Dan orang yang tidak menerima (seruan) orang yang menyeru kepada Allah maka dia tidak akan melepaskan diri dari azab Allah di muka bumi dan tidak ada baginya pelindung selain Allah. Mereka itu dalam kesesatan yang nyata".'),
  ('id.indonesian', 46, 33, 'Dan apakah mereka tidak memperhatikan bahwa sesungguhnya Allah yang menciptakan langit dan bumi dan Dia tidak merasa payah karena menciptakannya, kuasa menghidupkan orang-orang mati? Ya (bahkan) sesungguhnya Dia Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 46, 34, 'Dan (ingatlah) hari (ketika) orang-orang kafir dihadapkan kepada neraka, (dikatakan kepada mereka): "Bukankah (azab) ini benar?" Mereka menjawab: "Ya benar, demi Tuhan kami". Allah berfirman "Maka rasakanlah azab ini disebabkan kamu selalu ingkar".'),
  ('id.indonesian', 46, 35, 'Maka bersabarlah kamu seperti orang-orang yang mempunyai keteguhan hati dari rasul-rasul telah bersabar dan janganlah kamu meminta disegerakan (azab) bagi mereka. Pada hari mereka melihat azab yang diancamkan kepada mereka (merasa) seolah-olah tidak tinggal (di dunia) melainkan sesaat pada siang hari. (Inilah) suatu pelajaran yang cukup, maka tidak dibinasakan melainkan kaum yang fasik.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 47, 1, 'Those who disbelieve and avert [people] from the way of Allah - He will waste their deeds.'),
  ('en.sahih', 47, 2, 'And those who believe and do righteous deeds and believe in what has been sent down upon Muhammad - and it is the truth from their Lord - He will remove from them their misdeeds and amend their condition.'),
  ('en.sahih', 47, 3, 'That is because those who disbelieve follow falsehood, and those who believe follow the truth from their Lord. Thus does Allah present to the people their comparisons.'),
  ('en.sahih', 47, 4, 'So when you meet those who disbelieve [in battle], strike [their] necks until, when you have inflicted slaughter upon them, then secure their bonds, and either [confer] favor afterwards or ransom [them] until the war lays down its burdens. That [is the command]. And if Allah had willed, He could have taken vengeance upon them [Himself], but [He ordered armed struggle] to test some of you by means of others. And those who are killed in the cause of Allah - never will He waste their deeds.'),
  ('en.sahih', 47, 5, 'He will guide them and amend their condition'),
  ('en.sahih', 47, 6, 'And admit them to Paradise, which He has made known to them.'),
  ('en.sahih', 47, 7, 'O you who have believed, if you support Allah, He will support you and plant firmly your feet.'),
  ('en.sahih', 47, 8, 'But those who disbelieve - for them is misery, and He will waste their deeds.'),
  ('en.sahih', 47, 9, 'That is because they disliked what Allah revealed, so He rendered worthless their deeds.'),
  ('en.sahih', 47, 10, 'Have they not traveled through the land and seen how was the end of those before them? Allah destroyed [everything] over them, and for the disbelievers is something comparable.'),
  ('en.sahih', 47, 11, 'That is because Allah is the protector of those who have believed and because the disbelievers have no protector.'),
  ('en.sahih', 47, 12, 'Indeed, Allah will admit those who have believed and done righteous deeds to gardens beneath which rivers flow, but those who disbelieve enjoy themselves and eat as grazing livestock eat, and the Fire will be a residence for them.'),
  ('en.sahih', 47, 13, 'And how many a city was stronger than your city [Makkah] which drove you out? We destroyed them; and there was no helper for them.'),
  ('en.sahih', 47, 14, 'So is he who is on clear evidence from his Lord like him to whom the evil of his work has been made attractive and they follow their [own] desires?'),
  ('en.sahih', 47, 15, 'Is the description of Paradise, which the righteous are promised, wherein are rivers of water unaltered, rivers of milk the taste of which never changes, rivers of wine delicious to those who drink, and rivers of purified honey, in which they will have from all [kinds of] fruits and forgiveness from their Lord, like [that of] those who abide eternally in the Fire and are given to drink scalding water that will sever their intestines?'),
  ('en.sahih', 47, 16, 'And among them, [O Muhammad], are those who listen to you, until when they depart from you, they say to those who were given knowledge, "What has he said just now?" Those are the ones of whom Allah has sealed over their hearts and who have followed their [own] desires.'),
  ('en.sahih', 47, 17, 'And those who are guided - He increases them in guidance and gives them their righteousness.'),
  ('en.sahih', 47, 18, 'Then do they await except that the Hour should come upon them unexpectedly? But already there have come [some of] its indications. Then what good to them, when it has come, will be their remembrance?'),
  ('en.sahih', 47, 19, 'So know, [O Muhammad], that there is no deity except Allah and ask forgiveness for your sin and for the believing men and believing women. And Allah knows of your movement and your resting place.'),
  ('en.sahih', 47, 20, 'Those who believe say, "Why has a surah not been sent down? But when a precise surah is revealed and fighting is mentioned therein, you see those in whose hearts is hypocrisy looking at you with a look of one overcome by death. And more appropriate for them [would have been]'),
  ('en.sahih', 47, 21, 'Obedience and good words. And when the matter [of fighting] was determined, if they had been true to Allah, it would have been better for them.'),
  ('en.sahih', 47, 22, 'So would you perhaps, if you turned away, cause corruption on earth and sever your [ties of] relationship?'),
  ('en.sahih', 47, 23, 'Those [who do so] are the ones that Allah has cursed, so He deafened them and blinded their vision.'),
  ('en.sahih', 47, 24, 'Then do they not reflect upon the Qur\'an, or are there locks upon [their] hearts?'),
  ('en.sahih', 47, 25, 'Indeed, those who reverted back [to disbelief] after guidance had become clear to them - Satan enticed them and prolonged hope for them.'),
  ('en.sahih', 47, 26, 'That is because they said to those who disliked what Allah sent down, "We will obey you in part of the matter." And Allah knows what they conceal.'),
  ('en.sahih', 47, 27, 'Then how [will it be] when the angels take them in death, striking their faces and their backs?'),
  ('en.sahih', 47, 28, 'That is because they followed what angered Allah and disliked [what earns] His pleasure, so He rendered worthless their deeds.'),
  ('en.sahih', 47, 29, 'Or do those in whose hearts is disease think that Allah would never expose their [feelings of] hatred?'),
  ('en.sahih', 47, 30, 'And if We willed, We could show them to you, and you would know them by their mark; but you will surely know them by the tone of [their] speech. And Allah knows your deeds.'),
  ('en.sahih', 47, 31, 'And We will surely test you until We make evident those who strive among you [for the cause of Allah] and the patient, and We will test your affairs.'),
  ('en.sahih', 47, 32, 'Indeed, those who disbelieved and averted [people] from the path of Allah and opposed the Messenger after guidance had become clear to them - never will they harm Allah at all, and He will render worthless their deeds.'),
  ('en.sahih', 47, 33, 'O you who have believed, obey Allah and obey the Messenger and do not invalidate your deeds.'),
  ('en.sahih', 47, 34, 'Indeed, those who disbelieved and averted [people] from the path of Allah and then died while they were disbelievers - never will Allah forgive them.'),
  ('en.sahih', 47, 35, 'So do not weaken and call for peace while you are superior; and Allah is with you and will never deprive you of [the reward of] your deeds.'),
  ('en.sahih', 47, 36, '[This] worldly life is only amusement and diversion. And if you believe and fear Allah, He will give you your rewards and not ask you for your properties.'),
  ('en.sahih', 47, 37, 'If He should ask you for them and press you, you would withhold, and He would expose your unwillingness.'),
  ('en.sahih', 47, 38, 'Here you are - those invited to spend in the cause of Allah - but among you are those who withhold [out of greed]. And whoever withholds only withholds [benefit] from himself; and Allah is the Free of need, while you are the needy. And if you turn away, He will replace you with another people; then they will not be the likes of you.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 47, 1, 'যারা কুফরী করে এবং আল্লাহর পথে বাধা সৃষ্টি করে, আল্লাহ তাদের সকল কর্ম ব্যর্থ করে দেন।'),
  ('bn.bengali', 47, 2, 'আর যারা বিশ্বাস স্থাপন করে, সৎকর্ম সম্পাদন করে এবং তাদের পালনকর্তার পক্ষ থেকে মুহাম্মদের প্রতি অবতীর্ণ সত্যে বিশ্বাস করে, আল্লাহ তাদের মন্দ কর্মসমূহ মার্জনা করেন এবং তাদের অবস্থা ভাল করে দেন।'),
  ('bn.bengali', 47, 3, 'এটা এ কারণে যে, যারা কাফের, তারা বাতিলের অনুসরণ করে এবং যারা বিশ্বাসী, তারা তাদের পালনকর্তার নিকট থেকে আগত সত্যের অনুসরণ করে। এমনিভাবে আল্লাহ মানুষের জন্যে তাদের দৃষ্টান্তসমূহ বর্ণনা করেন।'),
  ('bn.bengali', 47, 4, 'অতঃপর যখন তোমরা কাফেরদের সাথে যুদ্ধে অবতীর্ণ হও, তখন তাদের গর্দার মার, অবশেষে যখন তা˦#2503;দরকে পূর্ণরূপে পরাভূত কর তখন তাদেরকে শক্ত করে বেধে ফেল। অতঃপর হয় তাদের প্রতি অনুগ্রহ কর, না হয় তাদের নিকট হতে মুক্তিপণ লও। তোমরা যুদ্ধ চালিয়ে যাবে যে পর্যন্ত না শত্রুপক্ষ অস্ত্র সমর্পণ করবে! একথা শুনলে। আল্লাহ ইচ্ছা করলে তাদের কাছ থেকে প্রতিশোধ নিতে পারতেন। কিন্তু তিনি তোমাদের কতককে কতকের দ্বারা পরীক্ষা করতে চান। যারা আল্লাহর পথে শহীদ হয়, আল্লাহ কখনই তাদের কর্ম বিনষ্ট করবেন না।'),
  ('bn.bengali', 47, 5, 'তিনি তাদেরকে পথ প্রদর্শন করবেন এবং তাদের অবস্থা ভাল করবেন।'),
  ('bn.bengali', 47, 6, 'অতঃপর তিনি তাদেরকে জান্নাতে দাখিল করবেন, যা তাদেরকে জানিয়ে দিয়েছেন।'),
  ('bn.bengali', 47, 7, 'হে বিশ্বাসীগণ! যদি তোমরা আল্লাহকে সাহায্য কর, আল্লাহ তোমাদেরকে সাহায্য করবেন এবং তোমাদের পা দৃঢ়প্রতিষ্ঠ করবেন।'),
  ('bn.bengali', 47, 8, 'আর যারা কাফের, তাদের জন্যে আছে দুর্গতি এবং তিনি তাদের কর্ম বিনষ্ট করে দিবেন।'),
  ('bn.bengali', 47, 9, 'এটা এজন্যে যে, আল্লাহ যা নাযিল করেছেন, তারা তা পছন্দ করে না। অতএব, আল্লাহ তাদের কর্ম ব্যর্থ করে দিবেন।'),
  ('bn.bengali', 47, 10, 'তারা কি পৃথিবীতে ভ্রমণ করেনি অতঃপর দেখেনি যে, তাদের পূর্ববর্তীদের পরিণাম কি হয়েছে? আল্লাহ তাদেরকে ধ্বংস করে দিয়েছেন এবং কাফেরদের অবস্থা এরূপই হবে।'),
  ('bn.bengali', 47, 11, 'এটা এজন্যে যে, আল্লাহ মুমিনদের হিতৈষী বন্ধু এবং কাফেরদের কোন হিতৈষী বন্ধু নাই।'),
  ('bn.bengali', 47, 12, 'যারা বিশ্বাস করে ও সৎকর্ম করে, আল্লাহ তাদেরকে জান্নাতে দাখিল করবেন, যার নিম্নদেশে নির্ঝরিণীসমূহ প্রবাহিত হয়। আর যারা কাফের, তারা ভোগ-বিলাসে মত্ত থাকে এবং চতুস্পদ জন্তুর মত আহার করে। তাদের বাসস্থান জাহান্নাম।'),
  ('bn.bengali', 47, 13, 'যে জনপদ আপনাকে বহিস্কার করেছে, তদপেক্ষা কত শক্তিশালী জনপদকে আমি ধ্বংস করেছি, অতঃপর তাদেরকে সাহায্য করার কেউ ছিল না।'),
  ('bn.bengali', 47, 14, 'যে ব্যক্তি তার পালনকর্তার পক্ষ থেকে আগত নিদর্শন অনুসরণ করে, সে কি তার সমান, যার কাছে তার মন্দ কর্ম শোভনীয় করা হয়েছে এবং যে তার খেয়াল-খুশীর অনুসরণ করে।'),
  ('bn.bengali', 47, 15, 'পরহেযগারদেরকে যে জান্নাতের ওয়াদা দেয়া হয়েছে, তার অবস্থা নিম্নরূপঃ তাতে আছে পানির নহর, নির্মল দুধের নহর যারা স্বাদ অপরিবর্তনীয়, পানকারীদের জন্যে সুস্বাদু শরাবের নহর এবং পরিশোধিত মধুর নহর। তথায় তাদের জন্যে আছে রকমারি ফল-মূল ও তাদের পালনকর্তার ক্ষমা। পরহেযগাররা কি তাদের সমান, যারা জাহান্নামে অনন্তকাল থাকবে এবং যাদেরকে পান করতে দেয়া হবে ফুটন্ত পানি অতঃপর তা তাদের নাড়িভূঁড়ি ছিন্ন বিচ্ছিন্ন করে দেবে?'),
  ('bn.bengali', 47, 16, 'তাদের মধ্যে কতক আপনার দিকে কান পাতে, অতঃপর যখন আপনার কাছ থেকে বাইরে যায়, তখন যারা শিক্ষিত, তাদেরকে বলেঃ এইমাত্র তিনি কি বললেন ? এদের অন্তরে আল্লাহ মোহর মেরে দিয়েছেন এবং তারা নিজেদের খেয়াল-খুশীর অনুসরণ করে।'),
  ('bn.bengali', 47, 17, 'যারা সৎপথপ্রাপ্ত হয়েছে, তাদের সৎপথপ্রাপ্তি আরও বেড়ে যায় এবং আল্লাহ তাদেরকে তাকওয়া দান করেন।'),
  ('bn.bengali', 47, 18, 'তারা শুধু এই অপেক্ষাই করছে যে, কেয়ামত অকস্মাৎ তাদের কাছে এসে পড়ুক। বস্তুতঃ কেয়ামতের লক্ষণসমূহ তো এসেই পড়েছে। সুতরাং কেয়ামত এসে পড়লে তারা উপদেশ গ্রহণ করবে কেমন করে ?'),
  ('bn.bengali', 47, 19, 'জেনে রাখুন, আল্লাহ ব্যতীত কোন উপাস্য নেই। ক্ষমাপ্রার্থনা করুন, আপনার ক্রটির জন্যে এবং মুমিন পুরুষ ও নারীদের জন্যে। আল্লাহ, তোমাদের গতিবিধি ও অবস্থান সম্পর্কে জ্ঞাত।'),
  ('bn.bengali', 47, 20, 'যারা মুমিন, তারা বলেঃ একটি সূরা নাযিল হয় না কেন? অতঃপর যখন কোন দ্ব্যর্থহীন সূরা নাযিল হয় এবং তাতে জেহাদের উল্লেখ করা হয়, তখন যাদের অন্তরে রোগ আছে, আপনি তাদেরকে মৃত্যুভয়ে মূর্ছাপ্রাপ্ত মানুষের মত আপনার দিকে তাকিয়ে থাকতে দেখবেন। সুতরাং ধ্বংস তাদের জন্যে।'),
  ('bn.bengali', 47, 21, 'তাদের আনুগত্য ও মিষ্ট বাক্য জানা আছে। অতএব, জেহাদের সিন্ধান্ত হলে যদি তারা আল্লাহর প্রতি পদত্ত অংগীকার পূর্ণ করে, তবে তাদের জন্যে তা মঙ্গলজনক হবে।'),
  ('bn.bengali', 47, 22, 'ক্ষমতা লাভ করলে, সম্ভবতঃ তোমরা পৃথিবীতে অনর্থ সৃষ্টি করবে এবং আত্নীয়তা বন্ধন ছিন্ন করবে।'),
  ('bn.bengali', 47, 23, 'এদের প্রতিই আল্লাহ অভিসম্পাত করেন, অতঃপর তাদেরকে বধির ও দৃষ্টিশক্তিহীন করেন।'),
  ('bn.bengali', 47, 24, 'তারা কি কোরআন সম্পর্কে গভীর চিন্তা করে না? না তাদের অন্তর তালাবদ্ধ?'),
  ('bn.bengali', 47, 25, 'নিশ্চয় যারা সোজা পথ ব্যক্ত হওয়ার পর তৎপ্রতি পৃষ্ঠপ্রদর্শন করে, শয়তান তাদের জন্যে তাদের কাজকে সুন্দর করে দেখায় এবং তাদেরকে মিথ্যা আশা দেয়।'),
  ('bn.bengali', 47, 26, 'এটা এজন্য যে, তারা তাদেরকে বলে, যারা আল্লাহর অবতীর্ণ কিতাব অপছন্দ করেঃ আমরা কোন কোন ব্যাপারে তোমাদের কথা মান্য করব। আল্লাহ তাদের গোপন পরামর্শ অবগত আছেন।'),
  ('bn.bengali', 47, 27, 'ফেরেশতা যখন তাদের মুখমন্ডল ও পৃষ্ঠদেশে আঘাত করতে করতে প্রাণ হরণ করবে, তখন তাদের অবস্থা কেমন হবে?'),
  ('bn.bengali', 47, 28, 'এটা এজন্যে যে, তারা সেই বিষয়ের অনুসরণ করে, যা আল্লাহর অসন্তোষ সৃষ্টি করে এবং আল্লাহর সন্তুষ্টিকে অপছন্দ করে। ফলে তিনি তাদের কর্মসমূহ ব্যর্থ করে দেন।'),
  ('bn.bengali', 47, 29, 'যাদের অন্তরে রোগ আছে, তারা কি মনে করে যে, আল্লাহ তাদের অন্তরের বিদ্বেষ প্রকাশ করে দেবেন না?'),
  ('bn.bengali', 47, 30, 'আমি ইচ্ছা করলে আপনাকে তাদের সাথে পরিচিত করে দিতাম। তখন আপনি তাদের চেহারা দেখে তাদেরকে চিনতে পারতেন এবং আপনি অবশ্যই কথার ভঙ্গিতে তাদেরকে চিনতে পারবেন। আল্লাহ তোমাদের কর্মসমূহের খবর রাখেন।'),
  ('bn.bengali', 47, 31, 'আমি অবশ্যই তোমাদেরকে পরীক্ষা করব যে পর্যন্ত না ফুটিয়ে তুলি তোমাদের জেহাদকারীদেরকে এবং সবরকারীদেরকে এবং যতক্ষণ না আমি তোমাদের অবস্থান সমূহ যাচাই করি।'),
  ('bn.bengali', 47, 32, 'নিশ্চয় যারা কাফের এবং আল্লাহর পথ থেকে মানুষকে ফিরিয়ে রাখে এবং নিজেদের জন্যে সৎপথ ব্যক্ত হওয়ার পর রসূলের (সঃ) বিরোধিতা করে, তারা আল্লাহর কোনই ক্ষতি করতে পারবে না এবং তিনি ব্যর্থ করে দিবেন তাদের কর্মসমূহকে।'),
  ('bn.bengali', 47, 33, 'হে মুমিনগণ! তোমরা আল্লাহর আনুগত্য কর, রসূলের (সাঃ) আনুগত্য কর এবং নিজেদের কর্ম বিনষ্ট করো না।'),
  ('bn.bengali', 47, 34, 'নিশ্চয় যারা কাফের এবং আল্লাহর পথ থেকে মানুষকে ফিরিয়ে রাখে, অতঃপর কাফের অবস্থায় মারা যায়, আল্লাহ কখনই তাদেরকে ক্ষমা করবেন না।'),
  ('bn.bengali', 47, 35, 'অতএব, তোমরা হীনবল হয়ো না এবং সন্ধির আহবান জানিও না, তোমরাই হবে প্রবল। আল্লাহই তোমাদের সাথে আছেন। তিনি কখনও তোমাদের কর্ম হ্রাস করবেন না।'),
  ('bn.bengali', 47, 36, 'পার্থিব জীবন তো কেবল খেলাধুলা, যদি তোমরা বিশ্বাসী হও এবং সংযম অবলম্বন কর, আল্লাহ তোমাদেরকে তোমাদের প্রতিদান দেবেন এবং তিনি তোমাদের ধন-সম্পদ চাইবেন না।'),
  ('bn.bengali', 47, 37, 'তিনি তোমাদের কাছে ধন-সম্পদ চাইলে অতঃপর তোমাদেরকে অতিষ্ঠ করলে তোমরা কার্পণ্য করবে এবং তিনি তোমাদের মনের সংকীর্ণতা প্রকাশ করে দেবেন।'),
  ('bn.bengali', 47, 38, 'শুন, তোমরাই তো তারা, যাদেরকে আল্লাহর পথে ব্যয় করার আহবান জানানো হচ্ছে, অতঃপর তোমাদের কেউ কেউ কৃপণতা করছে। যারা কৃপণতা করছে, তারা নিজেদের প্রতিই কৃপণতা করছে। আল্লাহ অভাবমুক্ত এবং তোমরা অভাবগ্রস্থ। যদি তোমরা মুখ ফিরিয়ে নাও, তবে তিনি তোমাদের পরিবর্তে অন্য জাতিকে প্রতিষ্ঠিত করবেন, এরপর তারা তোমাদের মত হবে না।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 47, 1, 'Those who disbelieve and turn (men) from the way of Allah, He rendereth their actions vain.'),
  ('en.pickthall', 47, 2, 'And those who believe and do good works and believe in that which is revealed unto Muhammad - and it is the truth from their Lord - He riddeth them of their ill-deeds and improveth their state.'),
  ('en.pickthall', 47, 3, 'That is because those who disbelieve follow falsehood and because those who believe follow the truth from their Lord. Thus Allah coineth their similitudes for mankind.'),
  ('en.pickthall', 47, 4, 'Now when ye meet in battle those who disbelieve, then it is smiting of the necks until, when ye have routed them, then making fast of bonds; and afterward either grace or ransom till the war lay down its burdens. That (is the ordinance). And if Allah willed He could have punished them (without you) but (thus it is ordained) that He may try some of you by means of others. And those who are slain in the way of Allah, He rendereth not their actions vain.'),
  ('en.pickthall', 47, 5, 'He will guide them and improve their state,'),
  ('en.pickthall', 47, 6, 'And bring them in unto the Garden which He hath made known to them.'),
  ('en.pickthall', 47, 7, 'O ye who believe! If ye help Allah, He will help you and will make your foothold firm.'),
  ('en.pickthall', 47, 8, 'And those who disbelieve, perdition is for them, and He will make their actions vain.'),
  ('en.pickthall', 47, 9, 'That is because they are averse to that which Allah hath revealed, therefor maketh He their actions fruitless.'),
  ('en.pickthall', 47, 10, 'Have they not travelled in the land to see the nature of the consequence for those who were before them? Allah wiped them out. And for the disbelievers there will be the like thereof.'),
  ('en.pickthall', 47, 11, 'That is because Allah is patron of those who believe, and because the disbelievers have no patron.'),
  ('en.pickthall', 47, 12, 'Lo! Allah will cause those who believe and do good works to enter Gardens underneath which rivers flow; while those who disbelieve take their comfort in this life and eat even as the cattle eat, and the Fire is their habitation.'),
  ('en.pickthall', 47, 13, 'And how many a township stronger than thy township (O Muhammad) which hath cast thee out, have We destroyed, and they had no helper!'),
  ('en.pickthall', 47, 14, 'Is he who relieth on a clear proof from his Lord like those for whom the evil that they do is beautified while they follow their own lusts?'),
  ('en.pickthall', 47, 15, 'A similitude of the Garden which those who keep their duty (to Allah) are promised: Therein are rivers of water unpolluted, and rivers of milk whereof the flavour changeth not, and rivers of wine delicious to the drinkers, and rivers of clear-run honey; therein for them is every kind of fruit, with pardon from their Lord. (Are those who enjoy all this) like those who are immortal in the Fire and are given boiling water to drink so that it teareth their bowels?'),
  ('en.pickthall', 47, 16, 'Among them are some who give ear unto thee (Muhammad) till, when they go forth from thy presence they say unto those who have been given knowledge: What was that he said just now? Those are they whose hearts Allah hath sealed, and they follow their own lusts.'),
  ('en.pickthall', 47, 17, 'While as for those who walk aright, He addeth to their guidance, and giveth them their protection (against evil).'),
  ('en.pickthall', 47, 18, 'Await they aught save the Hour, that it should come upon them unawares? And the beginnings thereof have already come. But how, when it hath come upon them, can they take their warning?'),
  ('en.pickthall', 47, 19, 'So know (O Muhammad) that there is no Allah save Allah, and ask forgiveness for thy sin and for believing men and believing women. Allah knoweth (both) your place of turmoil and your place of rest.'),
  ('en.pickthall', 47, 20, 'And those who believe say: If only a surah were revealed! But when a decisive surah is revealed and war is mentioned therein, thou seest those in whose hearts is a disease looking at thee with the look of men fainting unto death. Therefor woe unto them!'),
  ('en.pickthall', 47, 21, 'Obedience and a civil word. Then, when the matter is determined, if they are loyal to Allah it will be well for them.'),
  ('en.pickthall', 47, 22, 'Would ye then, if ye were given the command, work corruption in the land and sever your ties of kinship?'),
  ('en.pickthall', 47, 23, 'Such are they whom Allah curseth so that He deafeneth them and maketh blind their eyes.'),
  ('en.pickthall', 47, 24, 'Will they then not meditate on the Qur\'an, or are there locks on the hearts?'),
  ('en.pickthall', 47, 25, 'Lo! those who turn back after the guidance hath been manifested unto them, Satan hath seduced them, and He giveth them the rein.'),
  ('en.pickthall', 47, 26, 'That is because they say unto those who hate what Allah hath revealed: We will obey you in some matters; and Allah knoweth their secret talk.'),
  ('en.pickthall', 47, 27, 'Then how (will it be with them) when the angels gather them, smiting their faces and their backs!'),
  ('en.pickthall', 47, 28, 'That will be because they followed that which angereth Allah, and hated that which pleaseth Him. Therefor He hath made their actions vain.'),
  ('en.pickthall', 47, 29, 'Or do those in whose hearts is a disease deem that Allah will not bring to light their (secret) hates?'),
  ('en.pickthall', 47, 30, 'And if We would, We could show them unto thee (Muhammad) so that thou shouldst know them surely by their marks. And thou shalt know them by the burden of their talk. And Allah knoweth your deeds.'),
  ('en.pickthall', 47, 31, 'And verily We shall try you till We know those of you who strive hard (for the cause of Allah) and the steadfast, and till We test your record.'),
  ('en.pickthall', 47, 32, 'Lo! those who disbelieve and turn from the way of Allah and oppose the messenger after the guidance hath been manifested unto them, they hurt Allah not a jot, and He will make their actions fruitless.'),
  ('en.pickthall', 47, 33, 'O ye who believe! Obey Allah and obey the messenger, and render not your actions vain.'),
  ('en.pickthall', 47, 34, 'Lo! those who disbelieve and turn from the way of Allah and then die disbelievers, Allah surely will not pardon them.'),
  ('en.pickthall', 47, 35, 'So do not falter and cry out for peace when ye (will be) the uppermost, and Allah is with you, and He will not grudge (the reward of) your actions.'),
  ('en.pickthall', 47, 36, 'The life of the world is but a sport and a pastime. And if ye believe and ward off (evil). He will give you your wages, and will not ask of you your wordly wealth.'),
  ('en.pickthall', 47, 37, 'If He should ask it of you and importune you, ye would hoard it, and He would bring to light your (secret) hates.'),
  ('en.pickthall', 47, 38, 'Lo! ye are those who are called to spend in the way of Allah, yet among you there are some who hoard. And as for him who hoardeth, he hoardeth only from his soul. And Allah is the Rich, and ye are the poor. And if ye turn away He will exchange you for some other folk, and they will not be the likes of you.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 47, 1, 'Those who reject Allah and hinder (men) from the Path of Allah,- their deeds will Allah render astray (from their mark).'),
  ('en.yusufali', 47, 2, 'But those who believe and work deeds of righteousness, and believe in the (Revelation) sent down to Muhammad - for it is the Truth from their Lord,- He will remove from them their ills and improve their condition.'),
  ('en.yusufali', 47, 3, 'This because those who reject Allah follow vanities, while those who believe follow the Truth from their Lord: Thus does Allah set forth for men their lessons by similitudes.'),
  ('en.yusufali', 47, 4, 'Therefore, when ye meet the Unbelievers (in fight), smite at their necks; At length, when ye have thoroughly subdued them, bind a bond firmly (on them): thereafter (is the time for) either generosity or ransom: Until the war lays down its burdens. Thus (are ye commanded): but if it had been Allah\'s Will, He could certainly have exacted retribution from them (Himself); but (He lets you fight) in order to test you, some with others. But those who are slain in the Way of Allah,- He will never let their deeds be lost.'),
  ('en.yusufali', 47, 5, 'Soon will He guide them and improve their condition,'),
  ('en.yusufali', 47, 6, 'And admit them to the Garden which He has announced for them.'),
  ('en.yusufali', 47, 7, 'O ye who believe! If ye will aid (the cause of) Allah, He will aid you, and plant your feet firmly.'),
  ('en.yusufali', 47, 8, 'But those who reject (Allah),- for them is destruction, and (Allah) will render their deeds astray (from their mark).'),
  ('en.yusufali', 47, 9, 'That is because they hate the Revelation of Allah; so He has made their deeds fruitless.'),
  ('en.yusufali', 47, 10, 'Do they not travel through the earth, and see what was the End of those before them (who did evil)? Allah brought utter destruction on them, and similar (fates await) those who reject Allah.'),
  ('en.yusufali', 47, 11, 'That is because Allah is the Protector of those who believe, but those who reject Allah have no protector.'),
  ('en.yusufali', 47, 12, 'Verily Allah will admit those who believe and do righteous deeds, to Gardens beneath which rivers flow; while those who reject Allah will enjoy (this world) and eat as cattle eat; and the Fire will be their abode.'),
  ('en.yusufali', 47, 13, 'And how many cities, with more power than thy city which has driven thee out, have We destroyed (for their sins)? and there was none to aid them.'),
  ('en.yusufali', 47, 14, 'Is then one who is on a clear (Path) from his Lord, no better than one to whom the evil of his conduct seems pleasing, and such as follow their own lusts?'),
  ('en.yusufali', 47, 15, '(Here is) a Parable of the Garden which the righteous are promised: in it are rivers of water incorruptible; rivers of milk of which the taste never changes; rivers of wine, a joy to those who drink; and rivers of honey pure and clear. In it there are for them all kinds of fruits; and Grace from their Lord. (Can those in such Bliss) be compared to such as shall dwell for ever in the Fire, and be given, to drink, boiling water, so that it cuts up their bowels (to pieces)?'),
  ('en.yusufali', 47, 16, 'And among them are men who listen to thee, but in the end, when they go out from thee, they say to those who have received Knowledge, "What is it he said just then?" Such are men whose hearts Allah has sealed, and who follow their own lusts.'),
  ('en.yusufali', 47, 17, 'But to those who receive Guidance, He increases the (light of) Guidance, and bestows on them their Piety and Restraint (from evil).'),
  ('en.yusufali', 47, 18, 'Do they then only wait for the Hour,- that it should come on them of a sudden? But already have come some tokens thereof, and when it (actually) is on them, how can they benefit then by their admonition?'),
  ('en.yusufali', 47, 19, 'Know, therefore, that there is no god but Allah, and ask forgiveness for thy fault, and for the men and women who believe: for Allah knows how ye move about and how ye dwell in your homes.'),
  ('en.yusufali', 47, 20, 'Those who believe say, "Why is not a sura sent down (for us)?" But when a sura of basic or categorical meaning is revealed, and fighting is mentioned therein, thou wilt see those in whose hearts is a disease looking at thee with a look of one in swoon at the approach of death. But more fitting for them-'),
  ('en.yusufali', 47, 21, 'Were it to obey and say what is just, and when a matter is resolved on, it were best for them if they were true to Allah.'),
  ('en.yusufali', 47, 22, 'Then, is it to be expected of you, if ye were put in authority, that ye will do mischief in the land, and break your ties of kith and kin?'),
  ('en.yusufali', 47, 23, 'Such are the men whom Allah has cursed for He has made them deaf and blinded their sight.'),
  ('en.yusufali', 47, 24, 'Do they not then earnestly seek to understand the Qur\'an, or are their hearts locked up by them?'),
  ('en.yusufali', 47, 25, 'Those who turn back as apostates after Guidance was clearly shown to them,- the Evil One has instigated them and busied them up with false hopes.'),
  ('en.yusufali', 47, 26, 'This, because they said to those who hate what Allah has revealed, "We will obey you in part of (this) matter"; but Allah knows their (inner) secrets.'),
  ('en.yusufali', 47, 27, 'But how (will it be) when the angels take their souls at death, and smite their faces and their backs?'),
  ('en.yusufali', 47, 28, 'This because they followed that which called forth the Wrath of Allah, and they hated Allah\'s good pleasure; so He made their deeds of no effect.'),
  ('en.yusufali', 47, 29, 'Or do those in whose hearts is a disease, think that Allah will not bring to light all their rancour?'),
  ('en.yusufali', 47, 30, 'Had We so wiled, We could have shown them up to thee, and thou shouldst have known them by their marks: but surely thou wilt know them by the tone of their speech! And Allah knows all that ye do.'),
  ('en.yusufali', 47, 31, 'And We shall try you until We test those among you who strive their utmost and persevere in patience; and We shall try your reported (mettle).'),
  ('en.yusufali', 47, 32, 'Those who reject Allah, hinder (men) from the Path of Allah, and resist the Messenger, after Guidance has been clearly shown to them, will not injure Allah in the least, but He will make their deeds of no effect.'),
  ('en.yusufali', 47, 33, 'O ye who believe! Obey Allah, and obey the messenger, and make not vain your deeds!'),
  ('en.yusufali', 47, 34, 'Those who reject Allah, and hinder (men) from the Path of Allah, then die rejecting Allah,- Allah will not forgive them.'),
  ('en.yusufali', 47, 35, 'Be not weary and faint-hearted, crying for peace, when ye should be uppermost: for Allah is with you, and will never put you in loss for your (good) deeds.'),
  ('en.yusufali', 47, 36, 'The life of this world is but play and amusement: and if ye believe and guard against Evil, He will grant you your recompense, and will not ask you (to give up) your possessions.'),
  ('en.yusufali', 47, 37, 'If He were to ask you for all of them, and press you, ye would covetously withhold, and He would bring out all your ill-feeling.'),
  ('en.yusufali', 47, 38, 'Behold, ye are those invited to spend (of your substance) in the Way of Allah: But among you are some that are niggardly. But any who are niggardly are so at the expense of their own souls. But Allah is free of all wants, and it is ye that are needy. If ye turn back (from the Path), He will substitute in your stead another people; then they would not be like you!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 47, 1, 'Allazeena kafaroo wa saddoo\'an sabeelil laahi adalla a\'maalahum'),
  ('en.transliteration', 47, 2, 'Wallazeena aamanoo wa \'amilus saalihaati wa aamanoo bimaa nuzzila \'alaa Muhammadinw-wa huwal haqqu mir Rabbihim kaffara \'anhum saiyiaatihim wa aslaha baalahum'),
  ('en.transliteration', 47, 3, 'Zaalika bi annal lazeena kafarut taba\'ul baatila wa annal lazeena aamanut taba\'ul haqqa mir Rabbihim; kazaalika yadribul laahu linnaasi amsaalahum'),
  ('en.transliteration', 47, 4, 'Fa-izaa laqeetumul lazeena kafaroo fadarbar riqaab, hattaaa izaa askhan tumoohum fashuddul wasaaq, fa immaa mannnam ba\'du wa immaa fidaaa\'an hattaa tada\'al harbu awzaarahaa; zaalika wa law yashaaa\'ul laahu lantasara minhum wa laakil laiyabluwa ba\'dakum biba\'d; wallazeena qutiloo fee sabeelil laahi falany yudilla a\'maalahum'),
  ('en.transliteration', 47, 5, 'Sa-yahdeehim wa yusihu baalahum'),
  ('en.transliteration', 47, 6, 'Wa yudkhiluhumul jannata \'arrafahaa lahum'),
  ('en.transliteration', 47, 7, 'Yaaa ayyuhal lazeena aamanooo in tansurul laaha yansurkum wa yusabbit aqdaamakum'),
  ('en.transliteration', 47, 8, 'Wallazeena kafaroo fata\'s al lahum wa adalla a\'maalahum'),
  ('en.transliteration', 47, 9, 'Zaalika bi annahum karihoo maaa anzalal laahu faahbata a\'maalahum'),
  ('en.transliteration', 47, 10, 'Afalam yaseeroo fil ardi fayanzuroo kaifa kaana \'aaqibatul lazeena min qablihim; dammaral laahu \'alaihim wa lilkaafireena amsaaluhaa'),
  ('en.transliteration', 47, 11, 'Zaalika bi annal laaha mawlal lazeena aamanoo wa annal kaafireena laa mawlaa lahum'),
  ('en.transliteration', 47, 12, 'Innal-laaha yudkhilul lazeena aamanoo wa \'amilus saalihaati Jannaatin tajree min tahtihal anhaaru wallazeena kafaroo yatamatta\'oona wa yaakuloona kamaa taakuluian\'aamu wan Naaru maswallahum'),
  ('en.transliteration', 47, 13, 'Wa ka ayyim min qaryatin hiya ashaddu quwwatam min qaryatikal lateee akhrajatka ahlaknaahum falaa naasira lahum'),
  ('en.transliteration', 47, 14, 'Afaman kaana \'alaa baiyinatim mir Rabbihee kaman zuyyina lahoo sooo\'u \'amalihee wattaba\'ooo ahwaaa\'ahum'),
  ('en.transliteration', 47, 15, 'Masalul jannatil latee wu\'idal muttaqoona feehaaa anhaarum mim maaa\'in ghayri aasininw wa anhaarum mil labanil lam yataghaiyar ta\'muhoo wa anhaarum min khamril lazzatil lishshaaribeena wa anhaarum min \'asalim musaffanw wa lahum feeha min kullis samaraati wa maghfiratum mir Rabbihim kaman huwa khaalidun fin naari wa suqoo maaa\'an hameeman faqatta\'a am\'aaa\'ahum'),
  ('en.transliteration', 47, 16, 'Wa minhum mai yastami\' ilaika hattaaa izaa kharajoo min \'indika qaaloo lillazeena ootul \'ilma maazaa qaala aanifaa; ulaaa\'ikal lazeena taba\'al laahu \'alaa quloobihim wattaba\'ooo ahwaaa\'ahum'),
  ('en.transliteration', 47, 17, 'Wallazeenah tadaw zaadahum hudanw wa aataahum taqwaahum'),
  ('en.transliteration', 47, 18, 'Fahal yanzuroona illas Saa\'ata an taatiyahum baghtatan faqad jaaa\'a ashraatuhaa; fa-annnaa lahum izaa jaaa\'at hum zikraahum'),
  ('en.transliteration', 47, 19, 'Fa\'lam annahoo laaa ilaaha illal laahu wastaghfir lizambika wa lilmu\'mineena walmu\'minaat; wallaahu ya\'lamu mutaqallabakum wa maswaakum'),
  ('en.transliteration', 47, 20, 'Wa yaqoolul lazeena aamanoo law laa nuzzilat Sooratun fa izaaa unzilat Sooratum Muhkamatunw wa zukira feehal qitaalu ra aytal lazeena fee quloobihim maraduny yanzuroona ilaika nazaral maghshiyyi \'alaihi minal mawti fa\'awlaa lahum'),
  ('en.transliteration', 47, 21, 'Taa\'atunw wa qawlum ma\'roof; fa izaa \'azamal amru falaw sadaqul laaha lakaana khairal lahum'),
  ('en.transliteration', 47, 22, 'Fahal \'asaitum in tawallaitum an tufsidoo fil ardi wa tuqatti\'ooo arhaamakum'),
  ('en.transliteration', 47, 23, 'Ulaaa\'ikal lazeena la\'anahumul laahu fa asammahum wa a\'maaa absaarahum'),
  ('en.transliteration', 47, 24, 'Afalaa yatadabbaroonal Qur-aana am \'alaa quloobin aqfaaluhaa'),
  ('en.transliteration', 47, 25, 'Innal lazeenar taddoo \'alaaa adbaarihim mim ba\'di maa tabaiyana lahumul hudash Shaitaanu sawwala lahum wa amlaa lahum'),
  ('en.transliteration', 47, 26, 'Zaalika bi annahum qaaloo lillazeena karihoo maa nazzalal laahu sanutee\'ukum fee ba\'dil amri wallaahu ya\'lamu israarahum'),
  ('en.transliteration', 47, 27, 'Fakaifa izaa tawaffat humul malaaa\'ikatu yadriboona wujoohahum wa adbaa rahum'),
  ('en.transliteration', 47, 28, 'Zaalika bi annahumut taba\'oo maaa askhatal laaha wa karihoo ridwaanahoo fa ahbata a\'maalahum'),
  ('en.transliteration', 47, 29, 'Am hasibal lazeena fee quloobihim maradun al lan yukhrijal laahu adghaanahum'),
  ('en.transliteration', 47, 30, 'Wa law nashaaa\'u la-arainaakahum fala \'araftahum bi seemaahum; wa lata\'rifan nahum fee lahnil qawl; wallaahu ya\'lamu a\'maalakum'),
  ('en.transliteration', 47, 31, 'Wa lanabluwannakum hattaa na\'lamal mujaahideena minkum wassaabireena wa nabluwa akhbaarakum'),
  ('en.transliteration', 47, 32, 'Innnal lazeena kafaroo wa saddoo \'an sabeelil laahi wa shaaaqqur Rasoola mim ba\'di maa tabaiyana lahumul hudaa lany yadurrul laaha shai\'anw wa sa yuhbitu a\'maalahum'),
  ('en.transliteration', 47, 33, 'Yaaa ayyuhal lazeena aamanoo atee\'ul laaha wa atee\'ur Rasoola wa laa tubtilooo a\'maalakum'),
  ('en.transliteration', 47, 34, 'Innal lazeena kafaroo wa saddoo \'an sabeelil laahi summa maatoo wa hum kuffaarun falany yaghfirallaahu lahum'),
  ('en.transliteration', 47, 35, 'Falaa tahinoo wa tad\'ooo ilas salmi wa antumul a\'lawna wallaahu ma\'akum wa lany yatirakum a\'maalakum'),
  ('en.transliteration', 47, 36, 'Innamal hayaatud dunyaa la\'ibunw wa lahw; wa in to\'minoo wa tattaqoo yu\'tikum ujoorakum wa laa yas\'alkum amwaalakum'),
  ('en.transliteration', 47, 37, 'Iny yas\'alkumoohaa fa yuhfikum tabkhaloo wa yukhrij adghaanakum'),
  ('en.transliteration', 47, 38, 'haaa antum haaa\'ulaaa\'i tud\'awna litunfiqoo fee sabeelillaahi faminkum many yabkhalu wa many yabkhal fa innamaa yabkhalu \'an nafsih; wallaahu Ghaniyyu wa antumul fuqaraaa\'; wa in tatwal law yastabdil qawman ghairakum summa laa yakoonooo amsaalakum')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 47, 1, 'وہ لوگ جو منکر ہوئے اورانہوں نے لوگوں کو بھی الله کے راستہ سے روکا تو الله نے ان کے اعمال برباد کر دیئے'),
  ('ur.ahmedali', 47, 2, 'اوروہ جو ایمان لائے اور انہوں نے اچھے کام کیے اورجو کچھ محمد پر نازل کیا گیا اسپر بھی ایمان لائے اور انہوں نے اچھے کام بھی کیے اور جو کچھ محمد پر نازل کیا گیا اس پر بھی ایمان لائے حالانکہ وہ ان کے رب کی طرف سے برحق بھی ہے تو الله ان کی برائیوں کو مٹا دے گا اور ان کا حال درست کرے گا'),
  ('ur.ahmedali', 47, 3, 'یہ اس لیے کہ جولوگ منکر ہیں انہوں نے جھوٹ کی پیروی کی اور جو لوگ ایمان لائے انہوں نے اپنے رب کی طرف سے حق کی پیروی کی اسی طرح اللہ لوگوں کے لیے ان کی مثالیں بیان کرتا ہے'),
  ('ur.ahmedali', 47, 4, 'پس جب تم ان کے مقابل ہو جو کافر ہیں تو ان کی گردنیں مارو یہاں تک کہ جب تم ان کو خوب مغلوب کر لو تو ان کی مشکیں کس لو پھر یا تو اس کے بعد احسان کرو یا تاوان لے لو یہاں تک کہ لڑائی اپنے ہتھیار ڈال دے یہی (حکم) ہے اور اگر الله چاہتا تو ان سے خود ہی بدلہ لے لیتا لیکن وہ تمہارا ایک دوسرے کے ساتھ امتحان کرنا چاہتا ہے اور جو الله کی راہ میں مارے گئے ہیں الله ان کے اعمال برباد نہیں کرے گا'),
  ('ur.ahmedali', 47, 5, 'جلدی انہیں راہ دکھائے گا اور ان کاحال درست کر دے گا'),
  ('ur.ahmedali', 47, 6, 'اور انہیں بہشت میں داخل کرے گا جس کی حقیقت انہیں بتا دی ہے'),
  ('ur.ahmedali', 47, 7, 'اے ایمان والو اگر تم الله کی مدد کرو گے وہ تمہاری مدد کرے گا اور تمہارے قدم جمائے رکھے گا'),
  ('ur.ahmedali', 47, 8, 'اور جو منکر ہیں سو ان کے لیے تباہی ہے اور وہ ان کے اعمال اکارت کر دے گا'),
  ('ur.ahmedali', 47, 9, 'یہ اس لیے کہ انہیں نے ناپسند کیا جو الله نے اتارا ہے سو اس نے ان کے اعمال ضائع کر دیے'),
  ('ur.ahmedali', 47, 10, 'کیا انہوں نے زمین میں سیر نہیں کی وہ دیکھتے ان کا انجام کیسا ہوا جو ان سے پہلے تھے الله نے انہیں ہلاک کر دیا اور منکروں کے لیے ایسی ہی (سزائیں) ہیں'),
  ('ur.ahmedali', 47, 11, 'یہ اس لیے کہ اللهان کا حامی ہے جو ایمان لائے اور کفار کا کوئی بھی حامی نہیں'),
  ('ur.ahmedali', 47, 12, 'بے شک الله انہیں داخل کرے گا جو ایمان لائے اور نیک کام کیے بہشتوں میں جن کے نبیچے نہریں بہتی ہو ں گی اور جو کافر ہیں وہ عیش کر رہے ہیں اور اس طرح کھاتے ہیں جس طرح چار پائے کھاتے ہیں اور دوزخ ان کا ٹھکانہ ہے'),
  ('ur.ahmedali', 47, 13, 'اور کتنی ہی بستیاں تھی جو آپ کی اس بستی سے طاقت میں بڑھ کر تھیں جس کے رہنے والوں نے آپ کو نکال دیا ہے ہم نے انہیں ہلاک کر دیا تو ان کا کوئی بھی مددگار نہ ہوا'),
  ('ur.ahmedali', 47, 14, 'پس کیا وہ شخص جو اپنے رب کی طرف سے واضح دلیل پر ہو وہ اس جیسا ہو سکتا ہے جسے اس کے برے عمل اچھے کر کے دکھائے گئے ہوں اور انہوں نے اپنی ہی خواہشوں کی پیروی کی ہو'),
  ('ur.ahmedali', 47, 15, 'اس جنت کی کیفیت جس کا پرہیزگاروں سے وعدہ کیا جاتا ہے (یہ ہے) کہ اس میں ایسے پانی کی نہریں ہو گی جو بگڑنے والا نہیں اور کچھ دودھ کی نہریں جن کا مزہ کبھی نہیں بدلے گا اور کچھ نہریں ایسے شراب کی جو پینے والوں کے لیے خوش ذائقہ ہو گا اور کچھ نہریں صاف شہد کی اور ان کے لیے وہاں ہر قسم کے میوے ہوں اوراپنے رب کی بخشش (کیا وہ) ان جیسے ہو سکتے ہیں جو ہمیشہ دوزخ میں رہیں گے اور انہیں کھولتا ہوا پانی پلایا جائے گا سو وہ ان کی آنتوں کے ٹکڑے ٹکڑے کر ڈالے گا'),
  ('ur.ahmedali', 47, 16, 'اور ان میں سے بعض وہ ہیں جو آپ کی بات سنتے ہیں یہاں تک کہ جب آپ کے ہاں سے نکل جاتے ہیں تو ان سے کہتے ہیں جنہیں علم دیا گیا ہے اس نے ابھی ابھی کیا کہا یہی لوگ ہیں کہ الله نے ان کے دلوں پر مہر کر دی ہے اور انہوں نے اپنی خواہشوں کی پیروی کی ہے'),
  ('ur.ahmedali', 47, 17, 'اور جو راستہ پر آگئے ہیں الله انہیں اور زیادہ ہدایت دیتا اور انہیں پرہیزگاری عطا کرتا ہے'),
  ('ur.ahmedali', 47, 18, 'پھر کیا وہ اس گھڑی کا انتظار کرتے ہیں کہ ان پر ناگہان آئے پس تحقیق اس کی علامتیں تو ظاہر ہو چکیں ہیں پھر جب وہ آگئی تو ان کا سمجھنا کیا فائدہ دے گا'),
  ('ur.ahmedali', 47, 19, 'پس جان لو کہ سوائے الله کے کوئی معبود نہیں اور اپنے اور مسلمان مردوں اور مسلمان عورتوں کے گناہوں کی معافی مانگیئے اور الله ہی تمہارے لوٹنے اور آرام کرنے کی جگہ کو جانتا ہے'),
  ('ur.ahmedali', 47, 20, 'اور کہتے ہیں وہ لوگ جو ایمان لائے کوئی سورت کیوں نہیں نازل ہوئی سو جس وقت کوئی صاف (مضمون) کی سورت نازل ہوتی ہے اور اس میں جہاد کا بھی ذکر ہوتا ہے تو جن لوگو ں کے دلوں میں بیماری (نفاق) ہے آپ ان لوگو ں کو دیکھتے ہیں کہ وہ آپ کی طرف اس طرح دیکھتے ہیں جیسے کسی پر موت کی بیہوشی طاری ہو پس ایسے لوگوں کے لیے تباہی ہے'),
  ('ur.ahmedali', 47, 21, 'حکم ماننا اور نیک بات کہنا (لازم ہے) پس جب بات قرار پا جائے تو اگر وہ الله کے سچے رہے تو ان کے لیے بہتر ہے'),
  ('ur.ahmedali', 47, 22, 'پھر تم سے یہ بھی توقع ہے اگرتم ملک کے حاکم ہو جاؤ تو ملک میں فساد مچانے اور قطع رحمی کرنے لگو'),
  ('ur.ahmedali', 47, 23, 'یہی وہ لوگ ہیں جن پر الله نے لعنت کی ہے پھرانہیں بہرا اوراندھا بھی کر دیا ہے'),
  ('ur.ahmedali', 47, 24, 'پھر کیوں قرآن پر غور نہیں کرتے کیا ان کے دلوں پر قفل پڑے ہوئے ہیں'),
  ('ur.ahmedali', 47, 25, 'بے شک جو لوگ پیچھے کی طرف الٹے پھر گئے بعد اس کے کہ ان پر سیدھا راستہ ظاہر ہو چکا شیطان نے ان کے سامنے برے کامو ں کو بھلا کر دکھایا اور انہیں آرزو دلائی'),
  ('ur.ahmedali', 47, 26, 'یہ اس لیے کہ وہ ان لوگوں سے کہنے لگے جنہوں نے اسے ناپسند کیا اس کو جو الله نے نازل کیا ہے کہ بعض باتوں میں ہم تمہاراکہا مانیں گے اور الله ان کی رازداری کو جانتا ہے'),
  ('ur.ahmedali', 47, 27, 'پھر کیا حال ہوگا جب ان کی روحیں فرشتے قبض کریں گے ان کے مونہوں اور پیٹھوں پر مار رہے ہوں گے'),
  ('ur.ahmedali', 47, 28, 'یہ اس لیے کہ یہ اس پر چلے جس پر الله ناراض ہے اور انہوں نے الله کی رضا مندی کو برا جانا پھر اس نے بھی ان کے اعمال اکارت کر دیئے'),
  ('ur.ahmedali', 47, 29, 'کیا وہ لوگ کہ جن کے دلوں میں مرض (نفاق) ہے یہ سمجھے ہوئے ہیں کہ الله ان کی دبی دشمنی ظاہر نہ کرے گا'),
  ('ur.ahmedali', 47, 30, 'اور اگر ہم چاہتے تو آپ کو وہ لوگ دکھا دیتے پس آپ اچھی طرح سے انہیں ان کے نشان سےپہچان لیتے اور آپ انہیں طرز کلام سے پہچان لیں گے اور الله تمہارے اعمال کو جانتا ہے'),
  ('ur.ahmedali', 47, 31, 'اور ہم تمہیں آزمائیں گے یہاں تک کہ ہم تم میں سے جہاد کرنے والوں کو اور صبر کرنے والوں کو معلوم کر لیں اور تمہارے حالات کو جانچ لیں'),
  ('ur.ahmedali', 47, 32, 'بے شک جنہوں نے انکار کر دیا اور الله کی راہ سے روکا اور رسول کی مخالفت کی بعد اس کے کہ ان پر سیدھا راستہ صاضح ہو چکا وہ الله کا کچھ بھی نہیں بگاڑ سکیں گے اور ان کے اعمال کو اکارت کر دے گا'),
  ('ur.ahmedali', 47, 33, 'اے ایمان والو الله کا حکم مانو اوراس کے رسول کا حکم مانو اور اپنے اعمال کو ضائع نہ کرو'),
  ('ur.ahmedali', 47, 34, 'بےشک جنہوں نے انکار کیا اور الله کی راہ سے روکا پھر مر گئے درآنحالیکہ وہ کافر تھے سو الله ان کو ہرگز نہیں بخشے گا'),
  ('ur.ahmedali', 47, 35, 'پس تم سست نہ ہو اور نہ صلح کی طرف بلاؤ اور تم ہی غالب رہو گے اور الله تمہارے ساتھ ہے اور وہ ہر گز تمہارےاعمال میں نقصان نہیں دیگا'),
  ('ur.ahmedali', 47, 36, 'بلاشبہ دنیا کی زندگی تو کھیل اور تماشا ہے اور اگر تم ایمان لاؤ اور پرہیزگاری اختیار کرو تو تمہیں تمہارے اجر دے گا اور تم سے تمہارے مال نہیں مانگے گا'),
  ('ur.ahmedali', 47, 37, 'اور اگر تم سے وہ (مال) مانگے پھر تمہیں تنگ کرے تو تم بخل کرنے لگو اور تمہارے دلی کینے ظاہر کر دے'),
  ('ur.ahmedali', 47, 38, 'خبردار تم وہ لوگ ہو کہ الله کی راہ میں خرچ کرنے کو بلائے جاتے ہو تو کوئی تم میں سے وہ ہے جو بخل کرتا ہے اورجو بخل کرتا ہے سو وہ اپنی ہی ذات سے بخل کرتا ہے اور الله بے پرواہ ہے اور تم ہی محتاج ہو اور اگر تم نہ مانو گے تو وہ اور قوم سوائے تمہارے بدل دے گا پھر وہ تمہاری طرح نہ ہوں گے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 47, 1, 'Allah, inkar edenlerin ve kendi yolundan alıkoyanların işlerini boşa çıkarır.'),
  ('tr.diyanet', 47, 2, 'İnanıp yararlı iş işleyenlerin ve Muhammed\'e, Rablerinden bir gerçek olarak indirilene inananların kötülüklerini Allah örter ve durumlarını düzeltir.'),
  ('tr.diyanet', 47, 3, 'Bu, inkar edenlerin batıla uymaları ve inananların Rablerinden gelen gerçeğe uymalarından ötürü böyledir. Allah böylece insanlara kendilerinin misallerini anlatır.'),
  ('tr.diyanet', 47, 4, 'Savaşta inkar edenlerle karşılaştığınızda boyunlarını vurun; sonunda onlara üstün geldiğinizde onları esir alın; savaş sona erince onları ya karşılıksız, ya da fidye ile salıverin; Allah dilemiş olsaydı, onlardan başka türlü öç alabilirdi, bunun böyle olması, kiminizi kiminizle denemek içindir. Allah, kendi yolunda öldürülenlerin işlerini boşa çıkarmaz.'),
  ('tr.diyanet', 47, 5, 'Onları doğru yola eriştirir, durumlarını düzeltir.'),
  ('tr.diyanet', 47, 6, 'Onları, kendilerine anlattığı cennete koyar.'),
  ('tr.diyanet', 47, 7, 'Ey inananlar! Siz Allah\'ın dinine yardım ederseniz, O da size yardım eder, ayaklarınızı savaşta sabit kılar.'),
  ('tr.diyanet', 47, 8, 'İnkar edenlere ise, yıkım ve yokluk olsun! Allah onların işlerini boşa çıkarır.'),
  ('tr.diyanet', 47, 9, 'Bu, Allah\'ın indirdiğini beğenmediklerinden ötürüdür. İşlerini Allah bunun için boşa çıkarmıştır.'),
  ('tr.diyanet', 47, 10, 'Yeryüzünde dolaşıp kendilerinden öncekilerin sonlarının nasıl olduğuna bakmazlar mı? Allah onları yere geçirmiştir; inkarcılara da onların başına gelenin benzerleri vardır.'),
  ('tr.diyanet', 47, 11, 'Çünkü Allah inananların sahibidir. Kafirlerin ise sahibi yoktur.'),
  ('tr.diyanet', 47, 12, 'Doğrusu Allah, inanıp yararlı işler işleyenleri içlerinden ırmaklar akan cennetlere koyar. Durakları ateş olduğu halde kafirler, zevklenirler ve hayvanlar gibi yerler.'),
  ('tr.diyanet', 47, 13, 'Seni sürüp çıkaran şehirden daha kuvvetli olan nice şehirler yok ettik. Yardım edenleri bulunmadı.'),
  ('tr.diyanet', 47, 14, 'Rabbinin katından bir belgesi olan kimse, kötü işi kendisine güzel gösterilen kimseye benzer mi? Bunlar heveslerine uymuşlardır.'),
  ('tr.diyanet', 47, 15, 'Allah\'a karşı gelmekten sakınanlara söz verilen cennet şöyledir: Orada temiz su ırmakları, tadı bozulmayan süt ırmakları, içenlere zevk veren şarap ırmakları, süzme bal ırmakları vardır. Onlara orada her türlü ürün ve Rablerinden mağfiret vardır. Bunların durumu, ateşte temelli kalan ve bağırsaklarını parça parça edecek kaynar su içirilen kimselerin durumu gibi olur mu?'),
  ('tr.diyanet', 47, 16, 'Onların içinde seni dinleyenler vardır; sonra senin yanından çıkınca, bilgili kimselere "Az önce ne demişti?" diye sorarlar. İşte bunlar, Allah\'ın kalblerini mühürlemiş olduğu, kendi heveslerine uyan kimselerdir.'),
  ('tr.diyanet', 47, 17, 'Doğru yolu bulanların ise Allah doğruluklarını artırır, onların karşı gelmekten sakınmalarını sağlar.'),
  ('tr.diyanet', 47, 18, 'Onlar kıyamet gününün kendilerine ansızın gelmesini mi bekliyorlar. Şüphesiz onun alametleri belirmiştir. Kendilerine gelip çatınca ibret almaları neye yarar?'),
  ('tr.diyanet', 47, 19, 'Bil ki, Allah\'tan başka tanrı yoktur; kendinin, inanmış erkek ve kadınların günahlarının bağışlanmasını dile. Allah, gezip dolaştığınız ve duracağınız yerleri bilir.'),
  ('tr.diyanet', 47, 20, 'İnananlar: "Keşke bir süre indirilse de cihada çıksak" derlerdi. Fakat hükmü açık bir süre inip, orada savaş zikredilince, kalblerinde hastalık olanların, ölüm korkusuyla bayılmış kimselerin bakışları gibi, sana baktıklarını gördün. Oysa onlara itaat etmek ve uygun olanı söylemek yaraşırdı. İş ciddileşince Allah\'a verdikleri yeminde doğruluk gösterselerdi, onların iyiliğine olurdu.'),
  ('tr.diyanet', 47, 21, 'İnananlar: "Keşke bir süre indirilse de cihada çıksak" derlerdi. Fakat hükmü açık bir süre inip, orada savaş zikredilince, kalblerinde hastalık olanların, ölüm korkusuyla bayılmış kimselerin bakışları gibi, sana baktıklarını gördün. Oysa onlara itaat etmek ve uygun olanı söylemek yaraşırdı. İş ciddileşince Allah\'a verdikleri yeminde doğruluk gösterselerdi, onların iyiliğine olurdu.'),
  ('tr.diyanet', 47, 22, 'Geri dönerseniz yeryüzünde bozgunculuk yapmanız ve akrabalık bağlarını kesmeniz beklenmez mi sizden?'),
  ('tr.diyanet', 47, 23, 'İşte, Allah\'ın lanetlediği, sağır kıldığı ve gözlerini kör ettiği bunlardır.'),
  ('tr.diyanet', 47, 24, 'Bunlar Kuran\'ı düşünmezler mi? Yoksa kalbleri kilitli midir?'),
  ('tr.diyanet', 47, 25, 'Kendileri için doğru yol belli olduktan sonra ardlarına dönenleri, bu işi yapmaya şeytan sürüklemiş, onlara ümit vermiştir.'),
  ('tr.diyanet', 47, 26, 'Bu, Allah\'ın indirdiğini beğenmeyen kimselerin: "Biz bazı işlerde size itaat edeceğiz" demelerindendir. Allah onların gizlediklerini bilir.'),
  ('tr.diyanet', 47, 27, 'Melekler, onların yüzlerine ve sırtlarına vurarak canlarını alırken durumları nice olur?'),
  ('tr.diyanet', 47, 28, 'Bu, Allah\'ı gazablandıran şeye uymaları ve O\'nun rızasından hoşnut olmamalarından ötürüdür. Allah da onların işlerini boşa çıkarmıştır.'),
  ('tr.diyanet', 47, 29, 'Yoksa, kalblerinde hastalık olanlar, Allah\'ın onların kinlerini dışarı vurmayacağını mı sandılar?'),
  ('tr.diyanet', 47, 30, 'Eğer dileseydik, Biz onları sana gösterirdik; sen de onları yüzlerinden tanırdın. And olsun ki sen, onları konuşmalarından da tanırsın; Allah işlediklerinizi bilir.'),
  ('tr.diyanet', 47, 31, 'And olsun ki sizi, içinizden cihada çıkanları ve sabredenleri meydana çıkarana ve haberlerinizi açıklayana kadar deneyeceğiz.'),
  ('tr.diyanet', 47, 32, 'Şüphesiz, inkar edenler, Allah yolundan alıkoyanlar ve kendilerine doğru yol belli olduktan sonra Peygambere karşı gelenler Allah\'a hiçbir zarar veremezler. O, onların işlerini boşa çıkaracaktır.'),
  ('tr.diyanet', 47, 33, 'Ey inananlar! Allah\'a itaat edin, Peygambere itaat edin; işlerinizi boşa çıkarmayın.'),
  ('tr.diyanet', 47, 34, 'İnkar edip Allah yolundan alıkoyanları, sonra da inkarcı olarak ölenleri Allah şüphesiz ki bağışlamayacaktır.'),
  ('tr.diyanet', 47, 35, 'Ey inananlar! Sizler daha üstün olduğunuz halde düşman karşısında gevşemeyin ki barış istemek zorunda kalmayasınız; Allah sizinle beraberdir; sizin işlerinizi eksiltmeyecektir.'),
  ('tr.diyanet', 47, 36, 'Doğrusu dünya hayatı oyun ve oyalanmadır. Eğer inanır ve Allah\'a karşı gelmekten sakınırsanız, O, size ecirlerinizi verir; O, sizin mallarınızı tamamen sarfetmenizi istemez.'),
  ('tr.diyanet', 47, 37, 'Eğer sizden onları isteyip de sizi zorlarsa, cimrilik edecektiniz, O da kinlerinizi ortaya çıkaracaktı.'),
  ('tr.diyanet', 47, 38, 'İşte sizler, Allah yolunda sarfetmeye çağırılan kimselersiniz. Kiminiz cimrilik yapıyor ama, cimrilik yapan bilsin ki, ancak kendine karşı cimrilik etmiş olur. Allah zengindir, siz ise fakirsiniz. Eğer O\'ndan yüz çevirirseniz sizi ortadan kaldırır, sizin gibi olmayacak bir milleti yerinize getirir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 47, 1, 'Orang-orang yang kafir dan menghalangi (manusia) dari jalan Allah, Allah menyesatkan perbuatan-perbuatan mereka.'),
  ('id.indonesian', 47, 2, 'Dan orang-orang mukmin dan beramal soleh serta beriman kepada apa yang diturunkan kepada Muhammad dan itulah yang haq dari Tuhan mereka, Allah menghapuskan kesalahan-kesalahan mereka dan memperbaiki keadaan mereka.'),
  ('id.indonesian', 47, 3, 'Yang demikian adalah karena sesungguhnya orang-orang kafir mengikuti yang bathil dan sesungguhnya orang-orang mukmin mengikuti yang haq dari Tuhan mereka. Demikianlah Allah membuat untuk manusia perbandingan-perbandingan bagi mereka.'),
  ('id.indonesian', 47, 4, 'Apabila kamu bertemu dengan orang-orang kafir (di medan perang) maka pancunglah batang leher mereka. Sehingga apabila kamu telah mengalahkan mereka maka tawanlah mereka dan sesudah itu kamu boleh membebaskan mereka atau menerima tebusan sampai perang berakhir. Demikianlah apabila Allah menghendaki niscaya Allah akan membinasakan mereka tetapi Allah hendak menguji sebahagian kamu dengan sebahagian yang lain. Dan orang-orang yang syahid pada jalan Allah, Allah tidak akan menyia-nyiakan amal mereka.'),
  ('id.indonesian', 47, 5, 'Allah akan memberi pimpinan kepada mereka dan memperbaiki keadaan mereka,'),
  ('id.indonesian', 47, 6, 'dan memasukkan mereka ke dalam jannah yang telah diperkenankan-Nya kepada mereka.'),
  ('id.indonesian', 47, 7, 'Hai orang-orang mukmin, jika kamu menolong (agama) Allah, niscaya Dia akan menolongmu dan meneguhkan kedudukanmu.'),
  ('id.indonesian', 47, 8, 'Dan orang-orang yang kafir, maka kecelakaanlah bagi mereka dan Allah menyesatkan amal-amal mereka.'),
  ('id.indonesian', 47, 9, 'Yang demikian itu adalah karena Sesungguhnya mereka benci kepada apa yang diturunkan Allah (Al Quran) lalu Allah menghapuskan (pahala-pahala) amal-amal mereka.'),
  ('id.indonesian', 47, 10, 'Maka apakah mereka tidak mengadakan perjalanan di muka bumi sehingga mereka dapat memperhatikan bagaimana kesudahan orang-orang sebelum mereka; Allah telah menimpakan kebinasaan atas mereka dan orang-orang kafir akan menerima (akibat-akibat) seperti itu.'),
  ('id.indonesian', 47, 11, 'Yang demikian itu karena sesungguhnya Allah adalah pelindung orang-orang yang beriman dan karena sesungguhnya orang-orang kafir itu tidak mempunyai pelindung.'),
  ('id.indonesian', 47, 12, 'Sesungguhnya Allah memasukkan orang-orang mukmin dan beramal saleh ke dalam jannah yang mengalir di bawahnya sungai-sungai. Dan orang-orang kafir bersenang-senang (di dunia) dan mereka makan seperti makannya binatang. Dan jahannam adalah tempat tinggal mereka.'),
  ('id.indonesian', 47, 13, 'Dan betapa banyaknya negeri yang (penduduknya) lebih kuat dari pada (penduduk) negerimu (Muhammad) yang telah mengusirmu itu. Kami telah membinasakan mereka, maka tidak ada seorang penolongpun bagi mereka.'),
  ('id.indonesian', 47, 14, 'Maka apakah orang yang berpegang pada keterangan yang datang dari Rabbnya sama dengan orang yang (shaitan) menjadikan dia memandang baik perbuatannya yang buruk itu dan mengikuti hawa nafsunya?'),
  ('id.indonesian', 47, 15, '(Apakah) perumpamaan (penghuni) jannah yang dijanjikan kepada orang-orang yang bertakwa yang di dalamnya ada sungai-sungai dari air yang tiada berubah rasa dan baunya, sungai-sungai dari air susu yang tidak berubah rasanya, sungai-sungai dari khamar yang lezat rasanya bagi peminumnya dan sungai-sungai dari madu yang disaring; dan mereka memperoleh di dalamnya segala macam buah-buahan dan ampunan dari Rabb mereka, sama dengan orang yang kekal dalam jahannam dan diberi minuman dengan air yang mendidih sehingga memotong ususnya?'),
  ('id.indonesian', 47, 16, 'Dan di antara mereka ada orang yang mendengarkan perkataanmu sehingga apabila mereka keluar dari sisimu orang-orang berkata kepada orang yang telah diberi ilmu pengetahuan (sahabat-sahabat Nabi): "Apakah yang dikatakannya tadi?" Mereka itulah orang-orang yang dikunci mati hati mereka oleh Allah dan mengikuti hawa nafsu mereka.'),
  ('id.indonesian', 47, 17, 'Dan orang-orang yang mau menerima petunjuk, Allah menambah petunjuk kepada mereka dan memberikan balasan ketakwaannya.'),
  ('id.indonesian', 47, 18, 'Maka tidaklah yang mereka tunggu-tunggu melainkan hari kiamat (yaitu) kedatangannya kepada mereka dengan tiba-tiba, karena sesungguhnya telah datang tanda-tandanya. Maka apakah faedahnya bagi mereka kesadaran mereka itu apabila Kiamat sudah datang?'),
  ('id.indonesian', 47, 19, 'Maka ketahuilah, bahwa sesungguhnya tidak ada Ilah (sesembahan, tuhan) selain Allah dan mohonlah ampunan bagi dosamu dan bagi (dosa) orang-orang mukmin, laki-laki dan perempuan. Dan Allah mengetahui tempat kamu berusaha dan tempat kamu tinggal.'),
  ('id.indonesian', 47, 20, 'Dan orang-orang yang beriman berkata: "Mengapa tiada diturunkan suatu surat?" Maka apabila diturunkan suatu surat yang jelas maksudnya dan disebutkan di dalamnya (perintah) perang, kamu lihat orang-orang yang ada penyakit di dalam hatinya memandang kepadamu seperti pandangan orang yang pingsan karena takut mati, dan kecelakaanlah bagi mereka.'),
  ('id.indonesian', 47, 21, 'Taat dan mengucapkan perkataan yang baik (adalah lebih baik bagi mereka). Apabila telah tetap perintah perang (mereka tidak menyukainya). Tetapi jikalau mereka benar (imannya) terhadap Allah, niscaya yang demikian itu lebih baik bagi mereka.'),
  ('id.indonesian', 47, 22, 'Maka apakah kiranya jika kamu berkuasa kamu akan membuat kerusakan di muka bumi dan memutuskan hubungan kekeluargaan?'),
  ('id.indonesian', 47, 23, 'Mereka itulah orang-orang yang dilaknati Allah dan ditulikan-Nya telinga mereka dan dibutakan-Nya penglihatan mereka.'),
  ('id.indonesian', 47, 24, 'Maka apakah mereka tidak memperhatikan Al Quran ataukah hati mereka terkunci?'),
  ('id.indonesian', 47, 25, 'Sesungguhnya orang-orang yang kembali ke belakang (kepada kekafiran) sesudah petunjuk itu jelas bagi mereka, syaitan telah menjadikan mereka mudah (berbuat dosa) dan memanjangkan angan-angan mereka.'),
  ('id.indonesian', 47, 26, 'Yang demikian itu karena sesungguhnya mereka (orang-orang munafik) itu berkata kepada orang-orang yang benci kepada apa yang diturunkan Allah (orang-orang Yahudi): "Kami akan mematuhi kamu dalam beberapa urusan", sedang Allah mengetahui rahasia mereka.'),
  ('id.indonesian', 47, 27, 'Bagaimanakah (keadaan mereka) apabila malaikat mencabut nyawa mereka seraya memukul-mukul muka mereka dan punggung mereka?'),
  ('id.indonesian', 47, 28, 'Yang demikian itu adalah karena sesungguhnya mereka mengikuti apa yang menimbulkan kemurkaan Allah dan karena mereka membenci keridhaan-Nya, sebab itu Allah menghapus (pahala) amal-amal mereka.'),
  ('id.indonesian', 47, 29, 'Atau apakah orang-orang yang ada penyakit dalam hatinya mengira bahwa Allah tidak akan menampakkan kedengkian mereka?'),
  ('id.indonesian', 47, 30, 'Dan kalau Kami kehendaki, niscaya Kami tunjukkan mereka kepadamu sehingga kamu benar-benar dapat mengenal mereka dengan tanda-tandanya. Dan kamu benar-benar akan mengenal mereka dari kiasan-kiasan perkataan mereka dan Allah mengetahui perbuatan-perbuatan kamu.'),
  ('id.indonesian', 47, 31, 'Dan sesungguhnya Kami benar-benar akan menguji kamu agar Kami mengetahui orang-orang yang berjihad dan bersabar di antara kamu, dan agar Kami menyatakan (baik buruknya) hal ihwalmu.'),
  ('id.indonesian', 47, 32, 'Sesungguhnya orang-orang kafir dan (yang) menghalangi manusia dari jalan Allah serta memusuhi Rasul setelah petunjuk itu jelas bagi mereka, mereka tidak dapat memberi mudharat kepada Allah sedikitpun. Dan Allah akan menghapuskan (pahala) amal-amal mereka.'),
  ('id.indonesian', 47, 33, 'Hai orang-orang yang beriman, taatilah Allah dan taatilah Rasul dan janganlah kamu merusakkan (pahala) amal-amalmu.'),
  ('id.indonesian', 47, 34, 'Sesungguhnya orang-orang kafir dan (yang) menghalangi manusia dari jalan Allah kemudian mereka mati dalam keadaan kafir, maka sekali-kali Allah tidak akan memberi ampun kepada mereka.'),
  ('id.indonesian', 47, 35, 'Janganlah kamu lemah dan minta damai padahal kamulah yang di atas dan Allah pun bersamamu dan Dia sekali-kali tidak akan mengurangi pahala amal-amalmu.'),
  ('id.indonesian', 47, 36, 'Sesungguhnya kehidupan dunia hanyalah permainan dan senda gurau. Dan jika kamu beriman dan bertakwa, Allah akan memberikan pahala kepadamu dan Dia tidak akan meminta harta-hartamu.'),
  ('id.indonesian', 47, 37, 'Jika Dia meminta harta kepadamu lalu mendesak kamu (supaya memberikan semuanya) niscaya kamu akan kikir dan Dia akan menampakkan kedengkianmu.'),
  ('id.indonesian', 47, 38, 'Ingatlah, kamu ini orang-orang yang diajak untuk menafkahkan (hartamu) pada jalan Allah. Maka di antara kamu ada yang kikir, dan siapa yang kikir sesungguhnya dia hanyalah kikir terhadap dirinya sendiri. Dan Allah-lah yang Maha Kaya sedangkan kamulah orang-orang yang berkehendak (kepada-Nya); dan jika kamu berpaling niscaya Dia akan mengganti (kamu) dengan kaum yang lain; dan mereka tidak akan seperti kamu ini.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (43, 76, 4401, 'وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ', 495, 25, 198, 0),
  (43, 77, 4402, 'وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ ۖ قَالَ إِنَّكُم مَّٰكِثُونَ', 495, 25, 198, 0),
  (43, 78, 4403, 'لَقَدْ جِئْنَٰكُم بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ', 495, 25, 198, 0),
  (43, 79, 4404, 'أَمْ أَبْرَمُوٓا۟ أَمْرًۭا فَإِنَّا مُبْرِمُونَ', 495, 25, 198, 0),
  (43, 80, 4405, 'أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم ۚ بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ', 495, 25, 198, 0),
  (43, 81, 4406, 'قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌۭ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ', 495, 25, 198, 0),
  (43, 82, 4407, 'سُبْحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ', 495, 25, 198, 0),
  (43, 83, 4408, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 495, 25, 198, 0),
  (43, 84, 4409, 'وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَٰهٌۭ وَفِى ٱلْأَرْضِ إِلَٰهٌۭ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 495, 25, 198, 0),
  (43, 85, 4410, 'وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ', 495, 25, 198, 0),
  (43, 86, 4411, 'وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ', 495, 25, 198, 0),
  (43, 87, 4412, 'وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ ۖ فَأَنَّىٰ يُؤْفَكُونَ', 495, 25, 198, 0),
  (43, 88, 4413, 'وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوْمٌۭ لَّا يُؤْمِنُونَ', 495, 25, 198, 0),
  (43, 89, 4414, 'فَٱصْفَحْ عَنْهُمْ وَقُلْ سَلَٰمٌۭ ۚ فَسَوْفَ يَعْلَمُونَ', 495, 25, 198, 0),
  (44, 1, 4415, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 496, 25, 198, 0),
  (44, 2, 4416, 'وَٱلْكِتَٰبِ ٱلْمُبِينِ', 496, 25, 198, 0),
  (44, 3, 4417, 'إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةٍۢ مُّبَٰرَكَةٍ ۚ إِنَّا كُنَّا مُنذِرِينَ', 496, 25, 198, 0),
  (44, 4, 4418, 'فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ', 496, 25, 198, 0),
  (44, 5, 4419, 'أَمْرًۭا مِّنْ عِندِنَآ ۚ إِنَّا كُنَّا مُرْسِلِينَ', 496, 25, 198, 0),
  (44, 6, 4420, 'رَحْمَةًۭ مِّن رَّبِّكَ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 496, 25, 198, 0),
  (44, 7, 4421, 'رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ ۖ إِن كُنتُم مُّوقِنِينَ', 496, 25, 198, 0),
  (44, 8, 4422, 'لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ', 496, 25, 198, 0),
  (44, 9, 4423, 'بَلْ هُمْ فِى شَكٍّۢ يَلْعَبُونَ', 496, 25, 198, 0),
  (44, 10, 4424, 'فَٱرْتَقِبْ يَوْمَ تَأْتِى ٱلسَّمَآءُ بِدُخَانٍۢ مُّبِينٍۢ', 496, 25, 198, 0),
  (44, 11, 4425, 'يَغْشَى ٱلنَّاسَ ۖ هَٰذَا عَذَابٌ أَلِيمٌۭ', 496, 25, 198, 0),
  (44, 12, 4426, 'رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ', 496, 25, 198, 0),
  (44, 13, 4427, 'أَنَّىٰ لَهُمُ ٱلذِّكْرَىٰ وَقَدْ جَآءَهُمْ رَسُولٌۭ مُّبِينٌۭ', 496, 25, 198, 0),
  (44, 14, 4428, 'ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌۭ مَّجْنُونٌ', 496, 25, 198, 0),
  (44, 15, 4429, 'إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا ۚ إِنَّكُمْ عَآئِدُونَ', 496, 25, 198, 0),
  (44, 16, 4430, 'يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ', 496, 25, 198, 0),
  (44, 17, 4431, '۞ وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌۭ كَرِيمٌ', 496, 25, 199, 0),
  (44, 18, 4432, 'أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ ۖ إِنِّى لَكُمْ رَسُولٌ أَمِينٌۭ', 496, 25, 199, 0),
  (44, 19, 4433, 'وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ ۖ إِنِّىٓ ءَاتِيكُم بِسُلْطَٰنٍۢ مُّبِينٍۢ', 497, 25, 199, 0),
  (44, 20, 4434, 'وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ', 497, 25, 199, 0),
  (44, 21, 4435, 'وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ', 497, 25, 199, 0),
  (44, 22, 4436, 'فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوْمٌۭ مُّجْرِمُونَ', 497, 25, 199, 0),
  (44, 23, 4437, 'فَأَسْرِ بِعِبَادِى لَيْلًا إِنَّكُم مُّتَّبَعُونَ', 497, 25, 199, 0),
  (44, 24, 4438, 'وَٱتْرُكِ ٱلْبَحْرَ رَهْوًا ۖ إِنَّهُمْ جُندٌۭ مُّغْرَقُونَ', 497, 25, 199, 0),
  (44, 25, 4439, 'كَمْ تَرَكُوا۟ مِن جَنَّٰتٍۢ وَعُيُونٍۢ', 497, 25, 199, 0),
  (44, 26, 4440, 'وَزُرُوعٍۢ وَمَقَامٍۢ كَرِيمٍۢ', 497, 25, 199, 0),
  (44, 27, 4441, 'وَنَعْمَةٍۢ كَانُوا۟ فِيهَا فَٰكِهِينَ', 497, 25, 199, 0),
  (44, 28, 4442, 'كَذَٰلِكَ ۖ وَأَوْرَثْنَٰهَا قَوْمًا ءَاخَرِينَ', 497, 25, 199, 0),
  (44, 29, 4443, 'فَمَا بَكَتْ عَلَيْهِمُ ٱلسَّمَآءُ وَٱلْأَرْضُ وَمَا كَانُوا۟ مُنظَرِينَ', 497, 25, 199, 0),
  (44, 30, 4444, 'وَلَقَدْ نَجَّيْنَا بَنِىٓ إِسْرَٰٓءِيلَ مِنَ ٱلْعَذَابِ ٱلْمُهِينِ', 497, 25, 199, 0),
  (44, 31, 4445, 'مِن فِرْعَوْنَ ۚ إِنَّهُۥ كَانَ عَالِيًۭا مِّنَ ٱلْمُسْرِفِينَ', 497, 25, 199, 0),
  (44, 32, 4446, 'وَلَقَدِ ٱخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَٰلَمِينَ', 497, 25, 199, 0),
  (44, 33, 4447, 'وَءَاتَيْنَٰهُم مِّنَ ٱلْءَايَٰتِ مَا فِيهِ بَلَٰٓؤٌۭا۟ مُّبِينٌ', 497, 25, 199, 0),
  (44, 34, 4448, 'إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ', 497, 25, 199, 0),
  (44, 35, 4449, 'إِنْ هِىَ إِلَّا مَوْتَتُنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُنشَرِينَ', 497, 25, 199, 0),
  (44, 36, 4450, 'فَأْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 497, 25, 199, 0),
  (44, 37, 4451, 'أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍۢ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ أَهْلَكْنَٰهُمْ ۖ إِنَّهُمْ كَانُوا۟ مُجْرِمِينَ', 497, 25, 199, 0),
  (44, 38, 4452, 'وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ', 497, 25, 199, 0),
  (44, 39, 4453, 'مَا خَلَقْنَٰهُمَآ إِلَّا بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 497, 25, 199, 0),
  (44, 40, 4454, 'إِنَّ يَوْمَ ٱلْفَصْلِ مِيقَٰتُهُمْ أَجْمَعِينَ', 498, 25, 199, 0),
  (44, 41, 4455, 'يَوْمَ لَا يُغْنِى مَوْلًى عَن مَّوْلًۭى شَيْـًۭٔا وَلَا هُمْ يُنصَرُونَ', 498, 25, 199, 0),
  (44, 42, 4456, 'إِلَّا مَن رَّحِمَ ٱللَّهُ ۚ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ', 498, 25, 199, 0),
  (44, 43, 4457, 'إِنَّ شَجَرَتَ ٱلزَّقُّومِ', 498, 25, 199, 0),
  (44, 44, 4458, 'طَعَامُ ٱلْأَثِيمِ', 498, 25, 199, 0),
  (44, 45, 4459, 'كَٱلْمُهْلِ يَغْلِى فِى ٱلْبُطُونِ', 498, 25, 199, 0),
  (44, 46, 4460, 'كَغَلْىِ ٱلْحَمِيمِ', 498, 25, 199, 0),
  (44, 47, 4461, 'خُذُوهُ فَٱعْتِلُوهُ إِلَىٰ سَوَآءِ ٱلْجَحِيمِ', 498, 25, 199, 0),
  (44, 48, 4462, 'ثُمَّ صُبُّوا۟ فَوْقَ رَأْسِهِۦ مِنْ عَذَابِ ٱلْحَمِيمِ', 498, 25, 199, 0),
  (44, 49, 4463, 'ذُقْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْكَرِيمُ', 498, 25, 199, 0),
  (44, 50, 4464, 'إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمْتَرُونَ', 498, 25, 199, 0),
  (44, 51, 4465, 'إِنَّ ٱلْمُتَّقِينَ فِى مَقَامٍ أَمِينٍۢ', 498, 25, 199, 0),
  (44, 52, 4466, 'فِى جَنَّٰتٍۢ وَعُيُونٍۢ', 498, 25, 199, 0),
  (44, 53, 4467, 'يَلْبَسُونَ مِن سُندُسٍۢ وَإِسْتَبْرَقٍۢ مُّتَقَٰبِلِينَ', 498, 25, 199, 0),
  (44, 54, 4468, 'كَذَٰلِكَ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍۢ', 498, 25, 199, 0),
  (44, 55, 4469, 'يَدْعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ', 498, 25, 199, 0),
  (44, 56, 4470, 'لَا يَذُوقُونَ فِيهَا ٱلْمَوْتَ إِلَّا ٱلْمَوْتَةَ ٱلْأُولَىٰ ۖ وَوَقَىٰهُمْ عَذَابَ ٱلْجَحِيمِ', 498, 25, 199, 0),
  (44, 57, 4471, 'فَضْلًۭا مِّن رَّبِّكَ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 498, 25, 199, 0),
  (44, 58, 4472, 'فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ', 498, 25, 199, 0),
  (44, 59, 4473, 'فَٱرْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ', 498, 25, 199, 0),
  (45, 1, 4474, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 499, 25, 199, 0),
  (45, 2, 4475, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 499, 25, 199, 0),
  (45, 3, 4476, 'إِنَّ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَءَايَٰتٍۢ لِّلْمُؤْمِنِينَ', 499, 25, 199, 0),
  (45, 4, 4477, 'وَفِى خَلْقِكُمْ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٌۭ لِّقَوْمٍۢ يُوقِنُونَ', 499, 25, 199, 0),
  (45, 5, 4478, 'وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزْقٍۢ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَتَصْرِيفِ ٱلرِّيَٰحِ ءَايَٰتٌۭ لِّقَوْمٍۢ يَعْقِلُونَ', 499, 25, 199, 0),
  (45, 6, 4479, 'تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤْمِنُونَ', 499, 25, 199, 0),
  (45, 7, 4480, 'وَيْلٌۭ لِّكُلِّ أَفَّاكٍ أَثِيمٍۢ', 499, 25, 199, 0),
  (45, 8, 4481, 'يَسْمَعُ ءَايَٰتِ ٱللَّهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًۭا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍۢ', 499, 25, 199, 0),
  (45, 9, 4482, 'وَإِذَا عَلِمَ مِنْ ءَايَٰتِنَا شَيْـًٔا ٱتَّخَذَهَا هُزُوًا ۚ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌۭ مُّهِينٌۭ', 499, 25, 199, 0),
  (45, 10, 4483, 'مِّن وَرَآئِهِمْ جَهَنَّمُ ۖ وَلَا يُغْنِى عَنْهُم مَّا كَسَبُوا۟ شَيْـًۭٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوْلِيَآءَ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ', 499, 25, 199, 0),
  (45, 11, 4484, 'هَٰذَا هُدًۭى ۖ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ رَبِّهِمْ لَهُمْ عَذَابٌۭ مِّن رِّجْزٍ أَلِيمٌ', 499, 25, 199, 0),
  (45, 12, 4485, '۞ ٱللَّهُ ٱلَّذِى سَخَّرَ لَكُمُ ٱلْبَحْرَ لِتَجْرِىَ ٱلْفُلْكُ فِيهِ بِأَمْرِهِۦ وَلِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ', 499, 25, 200, 0),
  (45, 13, 4486, 'وَسَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ جَمِيعًۭا مِّنْهُ ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ', 499, 25, 200, 0),
  (45, 14, 4487, 'قُل لِّلَّذِينَ ءَامَنُوا۟ يَغْفِرُوا۟ لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ ٱللَّهِ لِيَجْزِىَ قَوْمًۢا بِمَا كَانُوا۟ يَكْسِبُونَ', 500, 25, 200, 0),
  (45, 15, 4488, 'مَنْ عَمِلَ صَٰلِحًۭا فَلِنَفْسِهِۦ ۖ وَمَنْ أَسَآءَ فَعَلَيْهَا ۖ ثُمَّ إِلَىٰ رَبِّكُمْ تُرْجَعُونَ', 500, 25, 200, 0),
  (45, 16, 4489, 'وَلَقَدْ ءَاتَيْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ وَرَزَقْنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلْنَٰهُمْ عَلَى ٱلْعَٰلَمِينَ', 500, 25, 200, 0),
  (45, 17, 4490, 'وَءَاتَيْنَٰهُم بَيِّنَٰتٍۢ مِّنَ ٱلْأَمْرِ ۖ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ', 500, 25, 200, 0),
  (45, 18, 4491, 'ثُمَّ جَعَلْنَٰكَ عَلَىٰ شَرِيعَةٍۢ مِّنَ ٱلْأَمْرِ فَٱتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ لَا يَعْلَمُونَ', 500, 25, 200, 0),
  (45, 19, 4492, 'إِنَّهُمْ لَن يُغْنُوا۟ عَنكَ مِنَ ٱللَّهِ شَيْـًۭٔا ۚ وَإِنَّ ٱلظَّٰلِمِينَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍۢ ۖ وَٱللَّهُ وَلِىُّ ٱلْمُتَّقِينَ', 500, 25, 200, 0),
  (45, 20, 4493, 'هَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدًۭى وَرَحْمَةٌۭ لِّقَوْمٍۢ يُوقِنُونَ', 500, 25, 200, 0),
  (45, 21, 4494, 'أَمْ حَسِبَ ٱلَّذِينَ ٱجْتَرَحُوا۟ ٱلسَّيِّـَٔاتِ أَن نَّجْعَلَهُمْ كَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ سَوَآءًۭ مَّحْيَاهُمْ وَمَمَاتُهُمْ ۚ سَآءَ مَا يَحْكُمُونَ', 500, 25, 200, 0),
  (45, 22, 4495, 'وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَلِتُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ', 500, 25, 200, 0),
  (45, 23, 4496, 'أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍۢ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةًۭ فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ ۚ أَفَلَا تَذَكَّرُونَ', 501, 25, 200, 0),
  (45, 24, 4497, 'وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ ۚ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَظُنُّونَ', 501, 25, 200, 0),
  (45, 25, 4498, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ', 501, 25, 200, 0),
  (45, 26, 4499, 'قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ لَا رَيْبَ فِيهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ', 501, 25, 200, 0),
  (45, 27, 4500, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَيَوْمَ تَقُومُ ٱلسَّاعَةُ يَوْمَئِذٍۢ يَخْسَرُ ٱلْمُبْطِلُونَ', 501, 25, 200, 0),
  (45, 28, 4501, 'وَتَرَىٰ كُلَّ أُمَّةٍۢ جَاثِيَةًۭ ۚ كُلُّ أُمَّةٍۢ تُدْعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلْيَوْمَ تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 501, 25, 200, 0),
  (45, 29, 4502, 'هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيْكُم بِٱلْحَقِّ ۚ إِنَّا كُنَّا نَسْتَنسِخُ مَا كُنتُمْ تَعْمَلُونَ', 501, 25, 200, 0),
  (45, 30, 4503, 'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَيُدْخِلُهُمْ رَبُّهُمْ فِى رَحْمَتِهِۦ ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْمُبِينُ', 501, 25, 200, 0),
  (45, 31, 4504, 'وَأَمَّا ٱلَّذِينَ كَفَرُوٓا۟ أَفَلَمْ تَكُنْ ءَايَٰتِى تُتْلَىٰ عَلَيْكُمْ فَٱسْتَكْبَرْتُمْ وَكُنتُمْ قَوْمًۭا مُّجْرِمِينَ', 501, 25, 200, 0),
  (45, 32, 4505, 'وَإِذَا قِيلَ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ وَٱلسَّاعَةُ لَا رَيْبَ فِيهَا قُلْتُم مَّا نَدْرِى مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنًّۭا وَمَا نَحْنُ بِمُسْتَيْقِنِينَ', 501, 25, 200, 0),
  (45, 33, 4506, 'وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 502, 25, 200, 0),
  (45, 34, 4507, 'وَقِيلَ ٱلْيَوْمَ نَنسَىٰكُمْ كَمَا نَسِيتُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا وَمَأْوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّٰصِرِينَ', 502, 25, 200, 0),
  (45, 35, 4508, 'ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذْتُمْ ءَايَٰتِ ٱللَّهِ هُزُوًۭا وَغَرَّتْكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ لَا يُخْرَجُونَ مِنْهَا وَلَا هُمْ يُسْتَعْتَبُونَ', 502, 25, 200, 0),
  (45, 36, 4509, 'فَلِلَّهِ ٱلْحَمْدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلْأَرْضِ رَبِّ ٱلْعَٰلَمِينَ', 502, 25, 200, 0),
  (45, 37, 4510, 'وَلَهُ ٱلْكِبْرِيَآءُ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 502, 25, 200, 0),
  (46, 1, 4511, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ حمٓ', 502, 26, 201, 0),
  (46, 2, 4512, 'تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 502, 26, 201, 0),
  (46, 3, 4513, 'مَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَآ إِلَّا بِٱلْحَقِّ وَأَجَلٍۢ مُّسَمًّۭى ۚ وَٱلَّذِينَ كَفَرُوا۟ عَمَّآ أُنذِرُوا۟ مُعْرِضُونَ', 502, 26, 201, 0),
  (46, 4, 4514, 'قُلْ أَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌۭ فِى ٱلسَّمَٰوَٰتِ ۖ ٱئْتُونِى بِكِتَٰبٍۢ مِّن قَبْلِ هَٰذَآ أَوْ أَثَٰرَةٍۢ مِّنْ عِلْمٍ إِن كُنتُمْ صَٰدِقِينَ', 502, 26, 201, 0),
  (46, 5, 4515, 'وَمَنْ أَضَلُّ مِمَّن يَدْعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا يَسْتَجِيبُ لَهُۥٓ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ وَهُمْ عَن دُعَآئِهِمْ غَٰفِلُونَ', 502, 26, 201, 0),
  (46, 6, 4516, 'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمْ أَعْدَآءًۭ وَكَانُوا۟ بِعِبَادَتِهِمْ كَٰفِرِينَ', 503, 26, 201, 0),
  (46, 7, 4517, 'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ هَٰذَا سِحْرٌۭ مُّبِينٌ', 503, 26, 201, 0),
  (46, 8, 4518, 'أَمْ يَقُولُونَ ٱفْتَرَىٰهُ ۖ قُلْ إِنِ ٱفْتَرَيْتُهُۥ فَلَا تَمْلِكُونَ لِى مِنَ ٱللَّهِ شَيْـًٔا ۖ هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ ۖ كَفَىٰ بِهِۦ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ ۖ وَهُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 503, 26, 201, 0),
  (46, 9, 4519, 'قُلْ مَا كُنتُ بِدْعًۭا مِّنَ ٱلرُّسُلِ وَمَآ أَدْرِى مَا يُفْعَلُ بِى وَلَا بِكُمْ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٌۭ مُّبِينٌۭ', 503, 26, 201, 0),
  (46, 10, 4520, 'قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌۭ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ ۖ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 503, 26, 201, 0),
  (46, 11, 4521, 'وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوا۟ لَوْ كَانَ خَيْرًۭا مَّا سَبَقُونَآ إِلَيْهِ ۚ وَإِذْ لَمْ يَهْتَدُوا۟ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفْكٌۭ قَدِيمٌۭ', 503, 26, 201, 0),
  (46, 12, 4522, 'وَمِن قَبْلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامًۭا وَرَحْمَةًۭ ۚ وَهَٰذَا كِتَٰبٌۭ مُّصَدِّقٌۭ لِّسَانًا عَرَبِيًّۭا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُوا۟ وَبُشْرَىٰ لِلْمُحْسِنِينَ', 503, 26, 201, 0),
  (46, 13, 4523, 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 503, 26, 201, 0),
  (46, 14, 4524, 'أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 503, 26, 201, 0),
  (46, 15, 4525, 'وَوَصَّيْنَا ٱلْإِنسَٰنَ بِوَٰلِدَيْهِ إِحْسَٰنًا ۖ حَمَلَتْهُ أُمُّهُۥ كُرْهًۭا وَوَضَعَتْهُ كُرْهًۭا ۖ وَحَمْلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهْرًا ۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرْبَعِينَ سَنَةًۭ قَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَٰلِحًۭا تَرْضَىٰهُ وَأَصْلِحْ لِى فِى ذُرِّيَّتِىٓ ۖ إِنِّى تُبْتُ إِلَيْكَ وَإِنِّى مِنَ ٱلْمُسْلِمِينَ', 504, 26, 201, 0),
  (46, 16, 4526, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ فِىٓ أَصْحَٰبِ ٱلْجَنَّةِ ۖ وَعْدَ ٱلصِّدْقِ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 504, 26, 201, 0),
  (46, 17, 4527, 'وَٱلَّذِى قَالَ لِوَٰلِدَيْهِ أُفٍّۢ لَّكُمَآ أَتَعِدَانِنِىٓ أَنْ أُخْرَجَ وَقَدْ خَلَتِ ٱلْقُرُونُ مِن قَبْلِى وَهُمَا يَسْتَغِيثَانِ ٱللَّهَ وَيْلَكَ ءَامِنْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّۭ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 504, 26, 201, 0),
  (46, 18, 4528, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍۢ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ', 504, 26, 201, 0),
  (46, 19, 4529, 'وَلِكُلٍّۢ دَرَجَٰتٌۭ مِّمَّا عَمِلُوا۟ ۖ وَلِيُوَفِّيَهُمْ أَعْمَٰلَهُمْ وَهُمْ لَا يُظْلَمُونَ', 504, 26, 201, 0),
  (46, 20, 4530, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذْهَبْتُمْ طَيِّبَٰتِكُمْ فِى حَيَاتِكُمُ ٱلدُّنْيَا وَٱسْتَمْتَعْتُم بِهَا فَٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ', 504, 26, 201, 0),
  (46, 21, 4531, '۞ وَٱذْكُرْ أَخَا عَادٍ إِذْ أَنذَرَ قَوْمَهُۥ بِٱلْأَحْقَافِ وَقَدْ خَلَتِ ٱلنُّذُرُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦٓ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍۢ', 505, 26, 202, 0),
  (46, 22, 4532, 'قَالُوٓا۟ أَجِئْتَنَا لِتَأْفِكَنَا عَنْ ءَالِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ', 505, 26, 202, 0),
  (46, 23, 4533, 'قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًۭا تَجْهَلُونَ', 505, 26, 202, 0),
  (46, 24, 4534, 'فَلَمَّا رَأَوْهُ عَارِضًۭا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا۟ هَٰذَا عَارِضٌۭ مُّمْطِرُنَا ۚ بَلْ هُوَ مَا ٱسْتَعْجَلْتُم بِهِۦ ۖ رِيحٌۭ فِيهَا عَذَابٌ أَلِيمٌۭ', 505, 26, 202, 0),
  (46, 25, 4535, 'تُدَمِّرُ كُلَّ شَىْءٍۭ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا۟ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمْ ۚ كَذَٰلِكَ نَجْزِى ٱلْقَوْمَ ٱلْمُجْرِمِينَ', 505, 26, 202, 0),
  (46, 26, 4536, 'وَلَقَدْ مَكَّنَّٰهُمْ فِيمَآ إِن مَّكَّنَّٰكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًۭا وَأَبْصَٰرًۭا وَأَفْـِٔدَةًۭ فَمَآ أَغْنَىٰ عَنْهُمْ سَمْعُهُمْ وَلَآ أَبْصَٰرُهُمْ وَلَآ أَفْـِٔدَتُهُم مِّن شَىْءٍ إِذْ كَانُوا۟ يَجْحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ', 505, 26, 202, 0),
  (46, 27, 4537, 'وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُم مِّنَ ٱلْقُرَىٰ وَصَرَّفْنَا ٱلْءَايَٰتِ لَعَلَّهُمْ يَرْجِعُونَ', 505, 26, 202, 0),
  (46, 28, 4538, 'فَلَوْلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرْبَانًا ءَالِهَةًۢ ۖ بَلْ ضَلُّوا۟ عَنْهُمْ ۚ وَذَٰلِكَ إِفْكُهُمْ وَمَا كَانُوا۟ يَفْتَرُونَ', 505, 26, 202, 0),
  (46, 29, 4539, 'وَإِذْ صَرَفْنَآ إِلَيْكَ نَفَرًۭا مِّنَ ٱلْجِنِّ يَسْتَمِعُونَ ٱلْقُرْءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓا۟ أَنصِتُوا۟ ۖ فَلَمَّا قُضِىَ وَلَّوْا۟ إِلَىٰ قَوْمِهِم مُّنذِرِينَ', 506, 26, 202, 0),
  (46, 30, 4540, 'قَالُوا۟ يَٰقَوْمَنَآ إِنَّا سَمِعْنَا كِتَٰبًا أُنزِلَ مِنۢ بَعْدِ مُوسَىٰ مُصَدِّقًۭا لِّمَا بَيْنَ يَدَيْهِ يَهْدِىٓ إِلَى ٱلْحَقِّ وَإِلَىٰ طَرِيقٍۢ مُّسْتَقِيمٍۢ', 506, 26, 202, 0),
  (46, 31, 4541, 'يَٰقَوْمَنَآ أَجِيبُوا۟ دَاعِىَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍۢ', 506, 26, 202, 0),
  (46, 32, 4542, 'وَمَن لَّا يُجِبْ دَاعِىَ ٱللَّهِ فَلَيْسَ بِمُعْجِزٍۢ فِى ٱلْأَرْضِ وَلَيْسَ لَهُۥ مِن دُونِهِۦٓ أَوْلِيَآءُ ۚ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍۢ مُّبِينٍ', 506, 26, 202, 0),
  (46, 33, 4543, 'أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَمْ يَعْىَ بِخَلْقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحْۦِىَ ٱلْمَوْتَىٰ ۚ بَلَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 506, 26, 202, 0),
  (46, 34, 4544, 'وَيَوْمَ يُعْرَضُ ٱلَّذِينَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَيْسَ هَٰذَا بِٱلْحَقِّ ۖ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ', 506, 26, 202, 0),
  (46, 35, 4545, 'فَٱصْبِرْ كَمَا صَبَرَ أُو۟لُوا۟ ٱلْعَزْمِ مِنَ ٱلرُّسُلِ وَلَا تَسْتَعْجِل لَّهُمْ ۚ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوٓا۟ إِلَّا سَاعَةًۭ مِّن نَّهَارٍۭ ۚ بَلَٰغٌۭ ۚ فَهَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلْفَٰسِقُونَ', 506, 26, 202, 0),
  (47, 1, 4546, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعْمَٰلَهُمْ', 507, 26, 202, 0),
  (47, 2, 4547, 'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٍۢ وَهُوَ ٱلْحَقُّ مِن رَّبِّهِمْ ۙ كَفَّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ وَأَصْلَحَ بَالَهُمْ', 507, 26, 202, 0),
  (47, 3, 4548, 'ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلْبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلْحَقَّ مِن رَّبِّهِمْ ۚ كَذَٰلِكَ يَضْرِبُ ٱللَّهُ لِلنَّاسِ أَمْثَٰلَهُمْ', 507, 26, 202, 0),
  (47, 4, 4549, 'فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ فَضَرْبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثْخَنتُمُوهُمْ فَشُدُّوا۟ ٱلْوَثَاقَ فَإِمَّا مَنًّۢا بَعْدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلْحَرْبُ أَوْزَارَهَا ۚ ذَٰلِكَ وَلَوْ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنْهُمْ وَلَٰكِن لِّيَبْلُوَا۟ بَعْضَكُم بِبَعْضٍۢ ۗ وَٱلَّذِينَ قُتِلُوا۟ فِى سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعْمَٰلَهُمْ', 507, 26, 202, 0),
  (47, 5, 4550, 'سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ', 507, 26, 202, 0),
  (47, 6, 4551, 'وَيُدْخِلُهُمُ ٱلْجَنَّةَ عَرَّفَهَا لَهُمْ', 507, 26, 202, 0),
  (47, 7, 4552, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', 507, 26, 202, 0),
  (47, 8, 4553, 'وَٱلَّذِينَ كَفَرُوا۟ فَتَعْسًۭا لَّهُمْ وَأَضَلَّ أَعْمَٰلَهُمْ', 507, 26, 202, 0),
  (47, 9, 4554, 'ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا۟ مَآ أَنزَلَ ٱللَّهُ فَأَحْبَطَ أَعْمَٰلَهُمْ', 507, 26, 202, 0),
  (47, 10, 4555, '۞ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ دَمَّرَ ٱللَّهُ عَلَيْهِمْ ۖ وَلِلْكَٰفِرِينَ أَمْثَٰلُهَا', 507, 26, 203, 0),
  (47, 11, 4556, 'ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوْلَى ٱلَّذِينَ ءَامَنُوا۟ وَأَنَّ ٱلْكَٰفِرِينَ لَا مَوْلَىٰ لَهُمْ', 507, 26, 203, 0),
  (47, 12, 4557, 'إِنَّ ٱللَّهَ يُدْخِلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ وَٱلَّذِينَ كَفَرُوا۟ يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ ٱلْأَنْعَٰمُ وَٱلنَّارُ مَثْوًۭى لَّهُمْ', 508, 26, 203, 0),
  (47, 13, 4558, 'وَكَأَيِّن مِّن قَرْيَةٍ هِىَ أَشَدُّ قُوَّةًۭ مِّن قَرْيَتِكَ ٱلَّتِىٓ أَخْرَجَتْكَ أَهْلَكْنَٰهُمْ فَلَا نَاصِرَ لَهُمْ', 508, 26, 203, 0),
  (47, 14, 4559, 'أَفَمَن كَانَ عَلَىٰ بَيِّنَةٍۢ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُم', 508, 26, 203, 0),
  (47, 15, 4560, 'مَّثَلُ ٱلْجَنَّةِ ٱلَّتِى وُعِدَ ٱلْمُتَّقُونَ ۖ فِيهَآ أَنْهَٰرٌۭ مِّن مَّآءٍ غَيْرِ ءَاسِنٍۢ وَأَنْهَٰرٌۭ مِّن لَّبَنٍۢ لَّمْ يَتَغَيَّرْ طَعْمُهُۥ وَأَنْهَٰرٌۭ مِّنْ خَمْرٍۢ لَّذَّةٍۢ لِّلشَّٰرِبِينَ وَأَنْهَٰرٌۭ مِّنْ عَسَلٍۢ مُّصَفًّۭى ۖ وَلَهُمْ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغْفِرَةٌۭ مِّن رَّبِّهِمْ ۖ كَمَنْ هُوَ خَٰلِدٌۭ فِى ٱلنَّارِ وَسُقُوا۟ مَآءً حَمِيمًۭا فَقَطَّعَ أَمْعَآءَهُمْ', 508, 26, 203, 0),
  (47, 16, 4561, 'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ حَتَّىٰٓ إِذَا خَرَجُوا۟ مِنْ عِندِكَ قَالُوا۟ لِلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ مَاذَا قَالَ ءَانِفًا ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ', 508, 26, 203, 0),
  (47, 17, 4562, 'وَٱلَّذِينَ ٱهْتَدَوْا۟ زَادَهُمْ هُدًۭى وَءَاتَىٰهُمْ تَقْوَىٰهُمْ', 508, 26, 203, 0),
  (47, 18, 4563, 'فَهَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةًۭ ۖ فَقَدْ جَآءَ أَشْرَاطُهَا ۚ فَأَنَّىٰ لَهُمْ إِذَا جَآءَتْهُمْ ذِكْرَىٰهُمْ', 508, 26, 203, 0),
  (47, 19, 4564, 'فَٱعْلَمْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ', 508, 26, 203, 0),
  (47, 20, 4565, 'وَيَقُولُ ٱلَّذِينَ ءَامَنُوا۟ لَوْلَا نُزِّلَتْ سُورَةٌۭ ۖ فَإِذَآ أُنزِلَتْ سُورَةٌۭ مُّحْكَمَةٌۭ وَذُكِرَ فِيهَا ٱلْقِتَالُ ۙ رَأَيْتَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌۭ يَنظُرُونَ إِلَيْكَ نَظَرَ ٱلْمَغْشِىِّ عَلَيْهِ مِنَ ٱلْمَوْتِ ۖ فَأَوْلَىٰ لَهُمْ', 509, 26, 203, 0),
  (47, 21, 4566, 'طَاعَةٌۭ وَقَوْلٌۭ مَّعْرُوفٌۭ ۚ فَإِذَا عَزَمَ ٱلْأَمْرُ فَلَوْ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَيْرًۭا لَّهُمْ', 509, 26, 203, 0),
  (47, 22, 4567, 'فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا۟ فِى ٱلْأَرْضِ وَتُقَطِّعُوٓا۟ أَرْحَامَكُمْ', 509, 26, 203, 0),
  (47, 23, 4568, 'أُو۟لَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمْ وَأَعْمَىٰٓ أَبْصَٰرَهُمْ', 509, 26, 203, 0),
  (47, 24, 4569, 'أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ أَمْ عَلَىٰ قُلُوبٍ أَقْفَالُهَآ', 509, 26, 203, 0),
  (47, 25, 4570, 'إِنَّ ٱلَّذِينَ ٱرْتَدُّوا۟ عَلَىٰٓ أَدْبَٰرِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَى ۙ ٱلشَّيْطَٰنُ سَوَّلَ لَهُمْ وَأَمْلَىٰ لَهُمْ', 509, 26, 203, 0),
  (47, 26, 4571, 'ذَٰلِكَ بِأَنَّهُمْ قَالُوا۟ لِلَّذِينَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمْ فِى بَعْضِ ٱلْأَمْرِ ۖ وَٱللَّهُ يَعْلَمُ إِسْرَارَهُمْ', 509, 26, 203, 0),
  (47, 27, 4572, 'فَكَيْفَ إِذَا تَوَفَّتْهُمُ ٱلْمَلَٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَٰرَهُمْ', 509, 26, 203, 0),
  (47, 28, 4573, 'ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَآ أَسْخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضْوَٰنَهُۥ فَأَحْبَطَ أَعْمَٰلَهُمْ', 509, 26, 203, 0),
  (47, 29, 4574, 'أَمْ حَسِبَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ أَن لَّن يُخْرِجَ ٱللَّهُ أَضْغَٰنَهُمْ', 509, 26, 203, 0),
  (47, 30, 4575, 'وَلَوْ نَشَآءُ لَأَرَيْنَٰكَهُمْ فَلَعَرَفْتَهُم بِسِيمَٰهُمْ ۚ وَلَتَعْرِفَنَّهُمْ فِى لَحْنِ ٱلْقَوْلِ ۚ وَٱللَّهُ يَعْلَمُ أَعْمَٰلَكُمْ', 510, 26, 203, 0),
  (47, 31, 4576, 'وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ مِنكُمْ وَٱلصَّٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ', 510, 26, 203, 0),
  (47, 32, 4577, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ وَشَآقُّوا۟ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْهُدَىٰ لَن يَضُرُّوا۟ ٱللَّهَ شَيْـًۭٔا وَسَيُحْبِطُ أَعْمَٰلَهُمْ', 510, 26, 203, 0),
  (47, 33, 4578, '۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَلَا تُبْطِلُوٓا۟ أَعْمَٰلَكُمْ', 510, 26, 204, 0),
  (47, 34, 4579, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمْ كُفَّارٌۭ فَلَن يَغْفِرَ ٱللَّهُ لَهُمْ', 510, 26, 204, 0),
  (47, 35, 4580, 'فَلَا تَهِنُوا۟ وَتَدْعُوٓا۟ إِلَى ٱلسَّلْمِ وَأَنتُمُ ٱلْأَعْلَوْنَ وَٱللَّهُ مَعَكُمْ وَلَن يَتِرَكُمْ أَعْمَٰلَكُمْ', 510, 26, 204, 0),
  (47, 36, 4581, 'إِنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌۭ وَلَهْوٌۭ ۚ وَإِن تُؤْمِنُوا۟ وَتَتَّقُوا۟ يُؤْتِكُمْ أُجُورَكُمْ وَلَا يَسْـَٔلْكُمْ أَمْوَٰلَكُمْ', 510, 26, 204, 0),
  (47, 37, 4582, 'إِن يَسْـَٔلْكُمُوهَا فَيُحْفِكُمْ تَبْخَلُوا۟ وَيُخْرِجْ أَضْغَٰنَكُمْ', 510, 26, 204, 0),
  (47, 38, 4583, 'هَٰٓأَنتُمْ هَٰٓؤُلَآءِ تُدْعَوْنَ لِتُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبْخَلُ ۖ وَمَن يَبْخَلْ فَإِنَّمَا يَبْخَلُ عَن نَّفْسِهِۦ ۚ وَٱللَّهُ ٱلْغَنِىُّ وَأَنتُمُ ٱلْفُقَرَآءُ ۚ وَإِن تَتَوَلَّوْا۟ يَسْتَبْدِلْ قَوْمًا غَيْرَكُمْ ثُمَّ لَا يَكُونُوٓا۟ أَمْثَٰلَكُم', 510, 26, 204, 0),
  (48, 1, 4584, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّا فَتَحْنَا لَكَ فَتْحًۭا مُّبِينًۭا', 511, 26, 204, 0),
  (48, 2, 4585, 'لِّيَغْفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُۥ عَلَيْكَ وَيَهْدِيَكَ صِرَٰطًۭا مُّسْتَقِيمًۭا', 511, 26, 204, 0),
  (48, 3, 4586, 'وَيَنصُرَكَ ٱللَّهُ نَصْرًا عَزِيزًا', 511, 26, 204, 0),
  (48, 4, 4587, 'هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَٰنًۭا مَّعَ إِيمَٰنِهِمْ ۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًۭا', 511, 26, 204, 0),
  (48, 5, 4588, 'لِّيُدْخِلَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّـَٔاتِهِمْ ۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوْزًا عَظِيمًۭا', 511, 26, 204, 0),
  (48, 6, 4589, 'وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوْءِ ۚ عَلَيْهِمْ دَآئِرَةُ ٱلسَّوْءِ ۖ وَغَضِبَ ٱللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًۭا', 511, 26, 204, 0),
  (48, 7, 4590, 'وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا', 511, 26, 204, 0),
  (48, 8, 4591, 'إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًۭا وَمُبَشِّرًۭا وَنَذِيرًۭا', 511, 26, 204, 0),
  (48, 9, 4592, 'لِّتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكْرَةًۭ وَأَصِيلًا', 511, 26, 204, 0),
  (48, 10, 4593, 'إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوْقَ أَيْدِيهِمْ ۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفْسِهِۦ ۖ وَمَنْ أَوْفَىٰ بِمَا عَٰهَدَ عَلَيْهُ ٱللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًۭا', 512, 26, 204, 0),
  (48, 11, 4594, 'سَيَقُولُ لَكَ ٱلْمُخَلَّفُونَ مِنَ ٱلْأَعْرَابِ شَغَلَتْنَآ أَمْوَٰلُنَا وَأَهْلُونَا فَٱسْتَغْفِرْ لَنَا ۚ يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِى قُلُوبِهِمْ ۚ قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًۢا ۚ بَلْ كَانَ ٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرًۢا', 512, 26, 204, 0),
  (48, 12, 4595, 'بَلْ ظَنَنتُمْ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلْمُؤْمِنُونَ إِلَىٰٓ أَهْلِيهِمْ أَبَدًۭا وَزُيِّنَ ذَٰلِكَ فِى قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ ٱلسَّوْءِ وَكُنتُمْ قَوْمًۢا بُورًۭا', 512, 26, 204, 0),
  (48, 13, 4596, 'وَمَن لَّمْ يُؤْمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعْتَدْنَا لِلْكَٰفِرِينَ سَعِيرًۭا', 512, 26, 204, 0),
  (48, 14, 4597, 'وَلِلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَكَانَ ٱللَّهُ غَفُورًۭا رَّحِيمًۭا', 512, 26, 204, 0),
  (48, 15, 4598, 'سَيَقُولُ ٱلْمُخَلَّفُونَ إِذَا ٱنطَلَقْتُمْ إِلَىٰ مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ ۖ يُرِيدُونَ أَن يُبَدِّلُوا۟ كَلَٰمَ ٱللَّهِ ۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمْ قَالَ ٱللَّهُ مِن قَبْلُ ۖ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنَا ۚ بَلْ كَانُوا۟ لَا يَفْقَهُونَ إِلَّا قَلِيلًۭا', 512, 26, 204, 0),
  (48, 16, 4599, 'قُل لِّلْمُخَلَّفِينَ مِنَ ٱلْأَعْرَابِ سَتُدْعَوْنَ إِلَىٰ قَوْمٍ أُو۟لِى بَأْسٍۢ شَدِيدٍۢ تُقَٰتِلُونَهُمْ أَوْ يُسْلِمُونَ ۖ فَإِن تُطِيعُوا۟ يُؤْتِكُمُ ٱللَّهُ أَجْرًا حَسَنًۭا ۖ وَإِن تَتَوَلَّوْا۟ كَمَا تَوَلَّيْتُم مِّن قَبْلُ يُعَذِّبْكُمْ عَذَابًا أَلِيمًۭا', 513, 26, 204, 0),
  (48, 17, 4600, 'لَّيْسَ عَلَى ٱلْأَعْمَىٰ حَرَجٌۭ وَلَا عَلَى ٱلْأَعْرَجِ حَرَجٌۭ وَلَا عَلَى ٱلْمَرِيضِ حَرَجٌۭ ۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۖ وَمَن يَتَوَلَّ يُعَذِّبْهُ عَذَابًا أَلِيمًۭا', 513, 26, 204, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 48, 1, 'Indeed, We have given you, [O Muhammad], a clear conquest'),
  ('en.sahih', 48, 2, 'That Allah may forgive for you what preceded of your sin and what will follow and complete His favor upon you and guide you to a straight path'),
  ('en.sahih', 48, 3, 'And [that] Allah may aid you with a mighty victory.'),
  ('en.sahih', 48, 4, 'It is He who sent down tranquillity into the hearts of the believers that they would increase in faith along with their [present] faith. And to Allah belong the soldiers of the heavens and the earth, and ever is Allah Knowing and Wise.'),
  ('en.sahih', 48, 5, '[And] that He may admit the believing men and the believing women to gardens beneath which rivers flow to abide therein eternally and remove from them their misdeeds - and ever is that, in the sight of Allah, a great attainment -'),
  ('en.sahih', 48, 6, 'And [that] He may punish the hypocrite men and hypocrite women, and the polytheist men and polytheist women - those who assume about Allah an assumption of evil nature. Upon them is a misfortune of evil nature; and Allah has become angry with them and has cursed them and prepared for them Hell, and evil it is as a destination.'),
  ('en.sahih', 48, 7, 'And to Allah belong the soldiers of the heavens and the earth. And ever is Allah Exalted in Might and Wise.'),
  ('en.sahih', 48, 8, 'Indeed, We have sent you as a witness and a bringer of good tidings and a warner'),
  ('en.sahih', 48, 9, 'That you [people] may believe in Allah and His Messenger and honor him and respect the Prophet and exalt Allah morning and afternoon.'),
  ('en.sahih', 48, 10, 'Indeed, those who pledge allegiance to you, [O Muhammad] - they are actually pledging allegiance to Allah. The hand of Allah is over their hands. So he who breaks his word only breaks it to the detriment of himself. And he who fulfills that which he has promised Allah - He will give him a great reward.'),
  ('en.sahih', 48, 11, 'Those who remained behind of the bedouins will say to you, "Our properties and our families occupied us, so ask forgiveness for us." They say with their tongues what is not within their hearts. Say, "Then who could prevent Allah at all if He intended for you harm or intended for you benefit? Rather, ever is Allah, with what you do, Acquainted.'),
  ('en.sahih', 48, 12, 'But you thought that the Messenger and the believers would never return to their families, ever, and that was made pleasing in your hearts. And you assumed an assumption of evil and became a people ruined."'),
  ('en.sahih', 48, 13, 'And whoever has not believed in Allah and His Messenger - then indeed, We have prepared for the disbelievers a Blaze.'),
  ('en.sahih', 48, 14, 'And to Allah belongs the dominion of the heavens and the earth. He forgives whom He wills and punishes whom He wills. And ever is Allah Forgiving and Merciful.'),
  ('en.sahih', 48, 15, 'Those who remained behind will say when you set out toward the war booty to take it, "Let us follow you." They wish to change the words of Allah. Say, "Never will you follow us. Thus did Allah say before." So they will say, "Rather, you envy us." But [in fact] they were not understanding except a little.'),
  ('en.sahih', 48, 16, 'Say to those who remained behind of the bedouins, "You will be called to [face] a people of great military might; you may fight them, or they will submit. So if you obey, Allah will give you a good reward; but if you turn away as you turned away before, He will punish you with a painful punishment."'),
  ('en.sahih', 48, 17, 'There is not upon the blind any guilt or upon the lame any guilt or upon the ill any guilt [for remaining behind]. And whoever obeys Allah and His Messenger - He will admit him to gardens beneath which rivers flow; but whoever turns away - He will punish him with a painful punishment.'),
  ('en.sahih', 48, 18, 'Certainly was Allah pleased with the believers when they pledged allegiance to you, [O Muhammad], under the tree, and He knew what was in their hearts, so He sent down tranquillity upon them and rewarded them with an imminent conquest'),
  ('en.sahih', 48, 19, 'And much war booty which they will take. And ever is Allah Exalted in Might and Wise.'),
  ('en.sahih', 48, 20, 'Allah has promised you much booty that you will take [in the future] and has hastened for you this [victory] and withheld the hands of people from you - that it may be a sign for the believers and [that] He may guide you to a straight path.'),
  ('en.sahih', 48, 21, 'And [He promises] other [victories] that you were [so far] unable to [realize] which Allah has already encompassed. And ever is Allah, over all things, competent.'),
  ('en.sahih', 48, 22, 'And if those [Makkans] who disbelieve had fought you, they would have turned their backs [in flight]. Then they would not find a protector or a helper.'),
  ('en.sahih', 48, 23, '[This is] the established way of Allah which has occurred before. And never will you find in the way of Allah any change.'),
  ('en.sahih', 48, 24, 'And it is He who withheld their hands from you and your hands from them within [the area of] Makkah after He caused you to overcome them. And ever is Allah of what you do, Seeing.'),
  ('en.sahih', 48, 25, 'They are the ones who disbelieved and obstructed you from al-Masjid al-Haram while the offering was prevented from reaching its place of sacrifice. And if not for believing men and believing women whom you did not know - that you might trample them and there would befall you because of them dishonor without [your] knowledge - [you would have been permitted to enter Makkah]. [This was so] that Allah might admit to His mercy whom He willed. If they had been apart [from them], We would have punished those who disbelieved among them with painful punishment'),
  ('en.sahih', 48, 26, 'When those who disbelieved had put into their hearts chauvinism - the chauvinism of the time of ignorance. But Allah sent down His tranquillity upon His Messenger and upon the believers and imposed upon them the word of righteousness, and they were more deserving of it and worthy of it. And ever is Allah, of all things, Knowing.'),
  ('en.sahih', 48, 27, 'Certainly has Allah showed to His Messenger the vision in truth. You will surely enter al-Masjid al-Haram, if Allah wills, in safety, with your heads shaved and [hair] shortened, not fearing [anyone]. He knew what you did not know and has arranged before that a conquest near [at hand].'),
  ('en.sahih', 48, 28, 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion. And sufficient is Allah as Witness.'),
  ('en.sahih', 48, 29, 'Muhammad is the Messenger of Allah; and those with him are forceful against the disbelievers, merciful among themselves. You see them bowing and prostrating [in prayer], seeking bounty from Allah and [His] pleasure. Their mark is on their faces from the trace of prostration. That is their description in the Torah. And their description in the Gospel is as a plant which produces its offshoots and strengthens them so they grow firm and stand upon their stalks, delighting the sowers - so that Allah may enrage by them the disbelievers. Allah has promised those who believe and do righteous deeds among them forgiveness and a great reward.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 48, 1, 'নিশ্চয় আমি আপনার জন্যে এমন একটা ফয়সালা করে দিয়েছি, যা সুস্পষ্ট।'),
  ('bn.bengali', 48, 2, 'যাতে আল্লাহ আপনার অতীত ও ভবিষ্যত ত্রুটিসমূহ মার্জনা করে দেন এবং আপনার প্রতি তাঁর নেয়ামত পূর্ণ করেন ও আপনাকে সরল পথে পরিচালিত করেন।'),
  ('bn.bengali', 48, 3, 'এবং আপনাকে দান করেন বলিষ্ঠ সাহায্য।'),
  ('bn.bengali', 48, 4, 'তিনি মুমিনদের অন্তরে প্রশান্তি নাযিল করেন, যাতে তাদের ঈমানের সাথে আরও ঈমান বেড়ে যায়। নভোমন্ডল ও ভূমন্ডলের বাহিনীসমূহ আল্লাহরই এবং আল্লাহ সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 48, 5, 'ঈমান এজন্যে বেড়ে যায়, যাতে তিনি ঈমানদার পুরুষ ও ঈমানদার নারীদেরকে জান্নাতে প্রবেশ করান, যার তলদেশে নদী প্রবাহিত। সেথায় তারা চিরকাল বসবাস করবে এবং যাতে তিনি তাদের পাপ মোচন করেন। এটাই আল্লাহর কাছে মহাসাফল্য।'),
  ('bn.bengali', 48, 6, 'এবং যাতে তিনি কপট বিশ্বাসী পুরুষ ও কপট বিশ্বাসিনী নারী এবং অংশীবাদী পুরুষ ও অংশীবাদিনী নারীদেরকে শাস্তি দেন, যারা আল্লাহ সম্পর্কে মন্দ ধারণা পোষন করে। তাদের জন্য মন্দ পরিনাম। আল্লাহ তাদের প্রতি ক্রুদ্ধ হয়েছেন, তাদেরকে অভিশপ্ত করেছেন। এবং তাহাদের জন্যে জাহান্নাম প্রস্তুত রেখেছেন। তাদের প্রত্যাবর্তন স্থল অত্যন্ত মন্দ।'),
  ('bn.bengali', 48, 7, 'নভোমন্ডল ও ভূমন্ডলের বাহিনীসমূহ আল্লাহরই। আল্লাহ পরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 48, 8, 'আমি আপনাকে প্রেরণ করেছি অবস্থা ব্যক্তকারীরূপে, সুসংবাদদাতা ও ভয় প্রদর্শনকারীরূপে।'),
  ('bn.bengali', 48, 9, 'যাতে তোমরা আল্লাহ ও রসূলের প্রতি বিশ্বাস স্থাপন কর এবং তাঁকে সাহায্য ও সম্মান কর এবং সকাল-সন্ধ্যায় আল্লাহর পবিত্রতা ঘোষণা কর।'),
  ('bn.bengali', 48, 10, 'যারা আপনার কাছে আনুগত্যের শপথ করে, তারা তো আল্লাহর কাছে আনুগত্যের শপথ করে। আল্লাহর হাত তাদের হাতের উপর রয়েছে। অতএব, যে শপথ ভঙ্গ করে; অতি অবশ্যই সে তা নিজের ক্ষতির জন্যেই করে এবং যে আল্লাহর সাথে কৃত অঙ্গীকার পূর্ণ করে; আল্লাহ সত্ত্বরই তাকে মহাপুরস্কার দান করবেন।'),
  ('bn.bengali', 48, 11, 'মরুবাসীদের মধ্যে যারা গৃহে বসে রয়েছে, তারা আপনাকে বলবেঃ আমরা আমাদের ধন-সম্পদ ও পরিবার-পরিজনের কাজে ব্যস্ত ছিলাম। অতএব, আমাদের পাপ মার্জনা করান। তারা মুখে এমন কথা বলবে, যা তাদের অন্তরে নেই। বলুনঃ আল্লাহ তোমাদের ক্ষতি অথবা উপকার সাধনের ইচ্ছা করলে কে তাকে বিরত রাখতে পারে? বরং তোমরা যা কর, আল্লাহ সে বিষয় পরিপূর্ণ জ্ঞাত।'),
  ('bn.bengali', 48, 12, 'বরং তোমরা ধারণ করেছিলে যে, রসূল ও মুমিনগণ তাদের বাড়ী-ঘরে কিছুতেই ফিরে আসতে পারবে না এবং এই ধারণা তোমাদের জন্যে খুবই সুখকর ছিল। তোমরা মন্দ ধারণার বশবর্তী হয়েছিলে। তোমরা ছিলে ধ্বংসমুখী এক সম্প্রদায়।'),
  ('bn.bengali', 48, 13, 'যারা আল্লাহ ও তাঁর রসূলে বিশ্বাস করে না, আমি সেসব কাফেরের জন্যে জ্বলন্ত অগ্নি প্রস্তুত রেখেছি।'),
  ('bn.bengali', 48, 14, 'নভোমন্ডল ও ভূমন্ডলের রাজত্ব আল্লাহরই। তিনি যাকে ইচ্ছা ক্ষমা করেন এবং যাকে ইচ্ছা শাস্তি দেন। তিনি ক্ষমাশীল, পরম মেহেরবান।'),
  ('bn.bengali', 48, 15, 'তোমরা যখন যুদ্ধলব্ধ ধন-সম্পদ সংগ্রহের জন্য যাবে, তখন যারা পশ্চাতে থেকে গিয়েছিল, তারা বলবেঃ আমাদেরকেও তোমাদের সঙ্গে যেতে দাও। তারা আল্লাহর কালাম পরিবর্তন করতে চায়। বলুনঃ তোমরা কখনও আমাদের সঙ্গে যেতে পারবে না। আল্লাহ পূর্ব থেকেই এরূপ বলে দিয়েছেন। তারা বলবেঃ বরং তোমরা আমাদের প্রতি বিদ্বেষ পোষণ করছ। পরন্তু তারা সামান্যই বোঝে।'),
  ('bn.bengali', 48, 16, 'গৃহে অবস্থানকারী মরুবাসীদেরকে বলে দিনঃ আগামীতে তোমরা এক প্রবল পরাক্রান্ত জাতির সাথে যুদ্ধ করতে আহুত হবে। তোমরা তাদের সাথে যুদ্ধ করবে, যতক্ষণ না তারা মুসলমান হয়ে যায়। তখন যদি তোমরা নির্দেশ পালন কর, তবে আল্লাহ তোমাদেরকে উত্তম পুরস্কার দিবেন। আর যদি পৃষ্ঠপ্রদর্শন কর যেমন ইতিপূর্বে পৃষ্ঠপ্রদর্শন করেছ, তবে তিনি তোমাদেরকে যন্ত্রনাদায়ক শাস্তি দিবেন।'),
  ('bn.bengali', 48, 17, 'অন্ধের জন্যে, খঞ্জের জন্যে ও রুগ্নের জন্যে কোন অপরাধ নাই এবং যে কেউ আল্লাহ ও তাঁর রসূলের অনুগত্য করবে তাকে তিনি জান্নাতে দাখিল করবেন, যার তলদেশে নদী প্রবাহিত হয়। পক্ষান্তরে যে, ব্যক্তি পৃষ্ঠপ্রদর্শন করবে, তাকে যন্ত্রণাদায়ক শাস্তি দিবেন।'),
  ('bn.bengali', 48, 18, 'আল্লাহ মুমিনদের প্রতি সন্তুষ্ট হলেন, যখন তারা বৃক্ষের নীচে আপনার কাছে শপথ করল। আল্লাহ অবগত ছিলেন যা তাদের অন্তরে ছিল। অতঃপর তিনি তাদের প্রতি প্রশান্তি নাযিল করলেন এবং তাদেরকে আসন্ন বিজয় পুরস্কার দিলেন।'),
  ('bn.bengali', 48, 19, 'এবং বিপুল পরিমাণে যুদ্ধলব্ধ সম্পদ, যা তারা লাভ করবে। আল্লাহ পরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 48, 20, 'আল্লাহ তোমাদেরকে বিপুল পরিমাণ যুদ্ধলব্ধ সম্পদের ওয়াদা দিয়েছেন, যা তোমরা লাভ করবে। তিনি তা তোমাদের জন্যে ত্বরান্বিত করবেন। তিনি তোমাদের থেকে শত্রুদের স্তব্দ করে দিয়েছেন-যাতে এটা মুমিনদের জন্যে এক নিদর্শন হয় এবং তোমাদেরকে সরল পথে পরিচালিত করেন।'),
  ('bn.bengali', 48, 21, 'আর ও একটি বিজয় রয়েছে যা এখনও তোমাদের অধিকারে আসেনি, আল্লাহ তা বেষ্টন করে আছেন। আল্লাহ সর্ববিষয়ে ক্ষমতাবান।'),
  ('bn.bengali', 48, 22, 'যদি কাফেররা তোমাদের মোকাবেলা করত, তবে অবশ্যই তারা পৃষ্ঠপ্রদর্শন করত। তখন তারা কোন অভিভাবক ও সাহায্যকারী পেত না।'),
  ('bn.bengali', 48, 23, 'এটাই আল্লাহর রীতি, যা পূর্ব থেকে চালু আছে। তুমি আল্লাহর রীতিতে কোন পরিবর্তন পাবে না।'),
  ('bn.bengali', 48, 24, 'তিনি মক্কা শহরে তাদের হাত তোমাদের থেকে এবং তোমাদের হাত তাদের থেকে নিবারিত করেছেন তাদের উপর তোমাদেরকে বিজয়ী করার পর। তোমরা যা কিছু কর, আল্লাহ তা দেখেন।'),
  ('bn.bengali', 48, 25, 'তারাই তো কুফরী করেছে এবং বাধা দিয়েছে তোমাদেরকে মসজিদে হারাম থেকে এবং অবস্থানরত কোরবানীর জন্তুদেরকে যথাস্থানে পৌছতে। যদি মক্কায় কিছুসংখ্যক ঈমানদার পুরুষ ও ঈমানদার নারী না থাকত, যাদেরকে তোমরা জানতে না। অর্থাৎ তাদের পিষ্ট হয়ে যাওয়ার আশংকা না থাকত, অতঃপর তাদের কারণে তোমরা অজ্ঞাতসারে ক্ষতিগ্রস্ত হতে, তবে সব কিছু চুকিয়ে দেয়া হত; কিন্তু এ কারণে চুকানো হয়নি, যাতে আল্লাহ তা’আলা যাকে ইচ্ছা স্বীয় রহমতে দাখিল করে নেন। যদি তারা সরে যেত, তবে আমি অবশ্যই তাদের মধ্যে যারা কাফের তাদেরকে যন্ত্রনাদায়ক শস্তি দিতাম।'),
  ('bn.bengali', 48, 26, 'কেননা, কাফেররা তাদের অন্তরে মূর্খতাযুগের জেদ পোষণ করত। অতঃপর আল্লাহ তাঁর রসূল ও মুমিনদের উপর স্বীয় প্রশান্তি নাযিল করলেন এবং তাদের জন্যে সংযমের দায়িত্ব অপরিহার্য করে দিলেন। বস্তুতঃ তারাই ছিল এর অধিকতর যোগ্য ও উপযুক্ত। আল্লাহ সর্ববিষয়ে সম্যক জ্ঞাত।'),
  ('bn.bengali', 48, 27, 'আল্লাহ তাঁর রসূলকে সত্য স্বপ্ন দেখিয়েছেন। আল্লাহ চাহেন তো তোমরা অবশ্যই মসজিদে হারামে প্রবেশ করবে নিরাপদে মস্তকমুন্ডিত অবস্থায় এবং কেশ কর্তিত অবস্থায়। তোমরা কাউকে ভয় করবে না। অতঃপর তিনি জানেন যা তোমরা জান না। এছাড়াও তিনি দিয়েছেন তোমাদেরকে একটি আসন্ন বিজয়।'),
  ('bn.bengali', 48, 28, 'তিনিই তাঁর রসূলকে হেদায়েত ও সত্য ধর্মসহ প্রেরণ করেছেন, যাতে একে অন্য সমস্ত ধর্মের উপর জয়যুক্ত করেন। সত্য প্রতিষ্ঠাতারূপে আল্লাহ যথেষ্ট।'),
  ('bn.bengali', 48, 29, 'মুহাম্মদ আল্লাহর রসূল এবং তাঁর সহচরগণ কাফেরদের প্রতি কঠোর, নিজেদের মধ্যে পরস্পর সহানুভূতিশীল। আল্লাহর অনুগ্রহ ও সন্তুষ্টি কামনায় আপনি তাদেরকে রুকু ও সেজদারত দেখবেন। তাদের মুখমন্ডলে রয়েছে সেজদার চিহ্ন । তওরাতে তাদের অবস্থা এরূপ এবং ইঞ্জিলে তাদের অবস্থা যেমন একটি চারা গাছ যা থেকে নির্গত হয় কিশলয়, অতঃপর তা শক্ত ও মজবুত হয় এবং কান্ডের উপর দাঁড়ায় দৃঢ়ভাবে-চাষীকে আনন্দে অভিভুত করে-যাতে আল্লাহ তাদের দ্বারা কাফেরদের অন্তর্জালা সৃষ্টি করেন। তাদের মধ্যে যারা বিশ্বাস স্থাপন করে এবং সৎকর্ম করে, আল্লাহ তাদেরকে ক্ষমা ও মহাপুরস্কারের ওয়াদা দিয়েছেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 48, 1, 'Lo! We have given thee (O Muhammad) a signal victory,'),
  ('en.pickthall', 48, 2, 'That Allah may forgive thee of thy sin that which is past and that which is to come, and may perfect His favour unto thee, and may guide thee on a right path,'),
  ('en.pickthall', 48, 3, 'And that Allah may help thee with strong help -'),
  ('en.pickthall', 48, 4, 'He it is Who sent down peace of reassurance into the hearts of the believers that they might add faith unto their faith. Allah\'s are the hosts of the heavens and the earth, and Allah is ever Knower, Wise -'),
  ('en.pickthall', 48, 5, 'That He may bring the believing men and the believing women into Gardens underneath which rivers flow, wherein they will abide, and may remit from them their evil deeds - That, in the sight of Allah, is the supreme triumph -'),
  ('en.pickthall', 48, 6, 'And may punish the hypocritical men and the hypocritical women, and the idolatrous men and the idolatrous women, who think an evil thought concerning Allah. For them is the evil turn of fortune, and Allah is wroth against them and hath cursed them, and hath made ready for them hell, a hapless journey\'s end.'),
  ('en.pickthall', 48, 7, 'Allah\'s are the hosts of the heavens and the earth, and Allah is ever Mighty, Wise.'),
  ('en.pickthall', 48, 8, 'Lo! We have sent thee (O Muhammad) as a witness and a bearer of good tidings and a warner,'),
  ('en.pickthall', 48, 9, 'That ye (mankind) may believe in Allah and His messenger, and may honour Him, and may revere Him, and may glorify Him at early dawn and at the close of day.'),
  ('en.pickthall', 48, 10, 'Lo! those who swear allegiance unto thee (Muhammad), swear allegiance only unto Allah. The Hand of Allah is above their hands. So whosoever breaketh his oath, breaketh it only to his soul\'s hurt; while whosoever keepeth his covenant with Allah, on him will He bestow immense reward.'),
  ('en.pickthall', 48, 11, 'Those of the wandering Arabs who were left behind will tell thee: Our possessions and our households occupied us, so ask forgiveness for us! They speak with their tongues that which is not in their hearts. Say: Who can avail you aught against Allah, if He intend you hurt or intend you profit? Nay, but Allah is ever Aware of what ye do.'),
  ('en.pickthall', 48, 12, 'Nay, but ye deemed that the messenger and the believers would never return to their own folk, and that was made fairseeming in your hearts, and ye did think an evil thought, and ye were worthless folk.'),
  ('en.pickthall', 48, 13, 'And so for him who believeth not in Allah and His messenger - Lo! We have prepared a flame for disbelievers.'),
  ('en.pickthall', 48, 14, 'And Allah\'s is the Sovereignty of the heavens and the earth. He forgiveth whom He will, and punisheth whom He will. And Allah is ever Forgiving, Merciful.'),
  ('en.pickthall', 48, 15, 'Those who were left behind will say, when ye set forth to capture booty: Let us go with you. They fain would change the verdict of Allah. Say (unto them, O Muhammad): Ye shall not go with us. Thus hath Allah said beforehand. Then they will say: Ye are envious of us. Nay, but they understand not, save a little.'),
  ('en.pickthall', 48, 16, 'Say unto those of the wandering Arabs who were left behind: Ye will be called against a folk of mighty prowess, to fight them until they surrender; and if ye obey, Allah will give you a fair reward; but if ye turn away as ye did turn away before, He will punish you with a painful doom.'),
  ('en.pickthall', 48, 17, 'There is no blame for the blind, nor is there blame for the lame, nor is there blame for the sick (that they go not forth to war). And whoso obeyeth Allah and His messenger, He will make him enter Gardens underneath which rivers flow; and whoso turneth back, him will He punish with a painful doom.'),
  ('en.pickthall', 48, 18, 'Allah was well pleased with the believers when they swore allegiance unto thee beneath the tree, and He knew what was in their hearts, and He sent down peace of reassurance on them, and hath rewarded them with a near victory;'),
  ('en.pickthall', 48, 19, 'And much booty that they will capture. Allah is ever Mighty, Wise.'),
  ('en.pickthall', 48, 20, 'Allah promiseth you much booty that ye will capture, and hath given you this in advance, and hath withheld men\'s hands from you, that it may be a token for the believers, and that He may guide you on a right path.'),
  ('en.pickthall', 48, 21, 'And other (gain), which ye have not been able to achieve, Allah will compass it, Allah is Able to do all things.'),
  ('en.pickthall', 48, 22, 'And if those who disbelieve join battle with you they will take to flight, and afterward they will find no protecting friend nor helper.'),
  ('en.pickthall', 48, 23, 'It is the law of Allah which hath taken course aforetime. Thou wilt not find for the law of Allah aught of power to change.'),
  ('en.pickthall', 48, 24, 'And He it is Who hath withheld men\'s hands from you, and hath withheld your hands from them, in the valley of Mecca, after He had made you victors over them. Allah is Seer of what ye do.'),
  ('en.pickthall', 48, 25, 'These it was who disbelieved and debarred you from the Inviolable Place of Worship, and debarred the offering from reaching its goal. And if it had not been for believing men and believing women, whom ye know not - lest ye should tread them under foot and thus incur guilt for them unknowingly; that Allah might bring into His mercy whom He will - If (the believers and the disbelievers) had been clearly separated We verily had punished those of them who disbelieved with painful punishment.'),
  ('en.pickthall', 48, 26, 'When those who disbelieve had set up in their hearts zealotry, the zealotry of the Age of Ignorance, then Allah sent down His peace of reassurance upon His messenger and upon the believers and imposed on them the word of self-restraint, for they were worthy of it and meet for it. And Allah is Aware of all things.'),
  ('en.pickthall', 48, 27, 'Allah hath fulfilled the vision for His messenger in very truth. Ye shall indeed enter the Inviolable Place of Worship, if Allah will, secure, (having your hair) shaven and cut, not fearing. But He knoweth that which ye know not, and hath given you a near victory beforehand.'),
  ('en.pickthall', 48, 28, 'He it is Who hath sent His messenger with the guidance and the religion of truth, that He may cause it to prevail over all religion. And Allah sufficeth as a Witness.'),
  ('en.pickthall', 48, 29, 'Muhammad is the messenger of Allah. And those with him are hard against the disbelievers and merciful among themselves. Thou (O Muhammad) seest them bowing and falling prostrate (in worship), seeking bounty from Allah and (His) acceptance. The mark of them is on their foreheads from the traces of prostration. Such is their likeness in the Torah and their likeness in the Gospel - like as sown corn that sendeth forth its shoot and strengtheneth it and riseth firm upon its stalk, delighting the sowers - that He may enrage the disbelievers with (the sight of) them. Allah hath promised, unto such of them as believe and do good works, forgiveness and immense reward.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 48, 1, 'Verily We have granted thee a manifest Victory:'),
  ('en.yusufali', 48, 2, 'That Allah may forgive thee thy faults of the past and those to follow; fulfil His favour to thee; and guide thee on the Straight Way;'),
  ('en.yusufali', 48, 3, 'And that Allah may help thee with powerful help.'),
  ('en.yusufali', 48, 4, 'It is He Who sent down tranquillity into the hearts of the Believers, that they may add faith to their faith;- for to Allah belong the Forces of the heavens and the earth; and Allah is Full of Knowledge and Wisdom;-'),
  ('en.yusufali', 48, 5, 'That He may admit the men and women who believe, to Gardens beneath which rivers flow, to dwell therein for aye, and remove their ills from them;- and that is, in the sight of Allah, the highest achievement (for man),-'),
  ('en.yusufali', 48, 6, 'And that He may punish the Hypocrites, men and women, and the Polytheists men and women, who imagine an evil opinion of Allah. On them is a round of Evil: the Wrath of Allah is on them: He has cursed them and got Hell ready for them: and evil is it for a destination.'),
  ('en.yusufali', 48, 7, 'For to Allah belong the Forces of the heavens and the earth; and Allah is Exalted in Power, Full of Wisdom.'),
  ('en.yusufali', 48, 8, 'We have truly sent thee as a witness, as a bringer of Glad Tidings, and as a Warner:'),
  ('en.yusufali', 48, 9, 'In order that ye (O men) may believe in Allah and His Messenger, that ye may assist and honour Him, and celebrate His praise morning and evening.'),
  ('en.yusufali', 48, 10, 'Verily those who plight their fealty to thee do no less than plight their fealty to Allah: the Hand of Allah is over their hands: then any one who violates his oath, does so to the harm of his own soul, and any one who fulfils what he has covenanted with Allah,- Allah will soon grant him a great Reward.'),
  ('en.yusufali', 48, 11, 'The desert Arabs who lagged behind will say to thee: "We were engaged in (looking after) our flocks and herds, and our families: do thou then ask forgiveness for us." They say with their tongues what is not in their hearts. Say: "Who then has any power at all (to intervene) on your behalf with Allah, if His Will is to give you some loss or to give you some profit? But Allah is well acquainted with all that ye do.'),
  ('en.yusufali', 48, 12, '"Nay, ye thought that the Messenger and the Believers would never return to their families; this seemed pleasing in your hearts, and ye conceived an evil thought, for ye are a people lost (in wickedness)."'),
  ('en.yusufali', 48, 13, 'And if any believe not in Allah and His Messenger, We have prepared, for those who reject Allah, a Blazing Fire!'),
  ('en.yusufali', 48, 14, 'To Allah belongs the dominion of the heavens and the earth: He forgives whom He wills, and He punishes whom He wills: but Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 48, 15, 'Those who lagged behind (will say), when ye (are free to) march and take booty (in war): "Permit us to follow you." They wish to change Allah\'s decree: Say: "Not thus will ye follow us: Allah has already declared (this) beforehand": then they will say, "But ye are jealous of us." Nay, but little do they understand (such things).'),
  ('en.yusufali', 48, 16, 'Say to the desert Arabs who lagged behind: "Ye shall be summoned (to fight) against a people given to vehement war: then shall ye fight, or they shall submit. Then if ye show obedience, Allah will grant you a goodly reward, but if ye turn back as ye did before, He will punish you with a grievous Penalty."'),
  ('en.yusufali', 48, 17, 'No blame is there on the blind, nor is there blame on the lame, nor on one ill (if he joins not the war): But he that obeys Allah and his Messenger,- (Allah) will admit him to Gardens beneath which rivers flow; and he who turns back, (Allah) will punish him with a grievous Penalty.'),
  ('en.yusufali', 48, 18, 'Allah\'s Good Pleasure was on the Believers when they swore Fealty to thee under the Tree: He knew what was in their hearts, and He sent down Tranquillity to them; and He rewarded them with a speedy Victory;'),
  ('en.yusufali', 48, 19, 'And many gains will they acquire (besides): and Allah is Exalted in Power, Full of Wisdom.'),
  ('en.yusufali', 48, 20, 'Allah has promised you many gains that ye shall acquire, and He has given you these beforehand; and He has restrained the hands of men from you; that it may be a Sign for the Believers, and that He may guide you to a Straight Path;'),
  ('en.yusufali', 48, 21, 'And other gains (there are), which are not within your power, but which Allah has compassed: and Allah has power over all things.'),
  ('en.yusufali', 48, 22, 'If the Unbelievers should fight you, they would certainly turn their backs; then would they find neither protector nor helper.'),
  ('en.yusufali', 48, 23, '(Such has been) the practice (approved) of Allah already in the past: no change wilt thou find in the practice (approved) of Allah.'),
  ('en.yusufali', 48, 24, 'And it is He Who has restrained their hands from you and your hands from them in the midst of Makka, after that He gave you the victory over them. And Allah sees well all that ye do.'),
  ('en.yusufali', 48, 25, 'They are the ones who denied Revelation and hindered you from the Sacred Mosque and the sacrificial animals, detained from reaching their place of sacrifice. Had there not been believing men and believing women whom ye did not know that ye were trampling down and on whose account a crime would have accrued to you without (your) knowledge, (Allah would have allowed you to force your way, but He held back your hands) that He may admit to His Mercy whom He will. If they had been apart, We should certainly have punished the Unbelievers among them with a grievous Punishment.'),
  ('en.yusufali', 48, 26, 'While the Unbelievers got up in their hearts heat and cant - the heat and cant of ignorance,- Allah sent down His Tranquillity to his Messenger and to the Believers, and made them stick close to the command of self-restraint; and well were they entitled to it and worthy of it. And Allah has full knowledge of all things.'),
  ('en.yusufali', 48, 27, 'Truly did Allah fulfil the vision for His Messenger: ye shall enter the Sacred Mosque, if Allah wills, with minds secure, heads shaved, hair cut short, and without fear. For He knew what ye knew not, and He granted, besides this, a speedy victory.'),
  ('en.yusufali', 48, 28, 'It is He Who has sent His Messenger with Guidance and the Religion of Truth, to proclaim it over all religion: and enough is Allah for a Witness.'),
  ('en.yusufali', 48, 29, 'Muhammad is the messenger of Allah; and those who are with him are strong against Unbelievers, (but) compassionate amongst each other. Thou wilt see them bow and prostrate themselves (in prayer), seeking Grace from Allah and (His) Good Pleasure. On their faces are their marks, (being) the traces of their prostration. This is their similitude in the Taurat; and their similitude in the Gospel is: like a seed which sends forth its blade, then makes it strong; it then becomes thick, and it stands on its own stem, (filling) the sowers with wonder and delight. As a result, it fills the Unbelievers with rage at them. Allah has promised those among them who believe and do righteous deeds forgiveness, and a great Reward.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 48, 1, 'Innaa fatahnaa laka Fatham Mubeenaa'),
  ('en.transliteration', 48, 2, 'Liyaghfira lakal laahu maa taqaddama min zambika wa maa ta akhkhara wa yutimma ni\'matahoo \'alaika wa yahdiyaka siraatam mustaqeema'),
  ('en.transliteration', 48, 3, 'Wa yansurakal laahu nasran \'azeezaa'),
  ('en.transliteration', 48, 4, 'Huwal lazeee anzalas sakeenata fee quloobil mu\'mineena liyazdaadooo eemaanamma\'a eemaanihim; wa lillaahi junoodus samawaati wal ard; wa kaanal laahu \'Aleeman Hakeemaa'),
  ('en.transliteration', 48, 5, 'Liyudkhilal mu\'mineena walmu\'minaati jannaatin tajree min tahtihal anhaaru khaalideena feehaa wa yukaffira \'anhum saiyi aatihim; wa kaana zaalika \'indal laahi fawzan \'azeemaa'),
  ('en.transliteration', 48, 6, 'Wa yu\'azzibal munaafiqeena walmunaafiqaati wal mushrikeena walmushrikaatiz zaaanneena billaahi zannas saw\'; \'alaihim daaa\'iratus saw\'i wa ghadibal laahu \'alaihim wa la\'anahum wa a\'adda lahum jahannama wa saaa\' at maseeraa'),
  ('en.transliteration', 48, 7, 'Wa lillaahi junoodus samaawaati wal ard; wa kaanal laahu \'azeezan hakeema'),
  ('en.transliteration', 48, 8, 'Innaaa arsalnaaka shaahi danw wa mubashshiranw wa nazeera'),
  ('en.transliteration', 48, 9, 'Litu minoo billaahi wa Rasoolihee wa tu\'azziroohu watuwaqqiroohu watusabbi hoohu bukratanw wa aseelaa'),
  ('en.transliteration', 48, 10, 'Innal lazeena yubaayi\'oonaka innamaa yubaayi\'oonal laaha yadul laahi fawqa aydehim; faman nakasa fainnamaa yuankusu \'alaa nafsihee wa man awfaa bimaa \'aahada \'alihul laaha fasa yu\'teehi ajran \'azeemaa'),
  ('en.transliteration', 48, 11, 'Sa yaqoolu lakal mukhal lafoona minal-A\'raabi shaighalatnaaa amwaalunaa wa ahloonaa fastaghfir lanaa; yaqooloona bi alsinatihim maa laisa fee quloobihim; qul famany yamliku lakum minal laahi shai\'an in araada bikum darran aw araada bikum naf\'aa; bal kaanal laahu bimaa ta\'maloona Khabeeraa'),
  ('en.transliteration', 48, 12, 'Bal zanantum al lany yanqalibar Rasoolu walmu\'minoona ilaaa ahleehim abadanw wa zuyyina zaalika fee quloobikum wa zanantum zannnas saw\'i wa kuntum qawmam booraa'),
  ('en.transliteration', 48, 13, 'Wa mal lam yu\'mim billaahi wa Rasoolihee fainnaaa a\'tadnaa lilkaafireena sa\'eeraa'),
  ('en.transliteration', 48, 14, 'Wa lillaahii mulkus samaawaati wal ard; yaghfiru limany yashaaa\'u wa yu\'azzibu many yashaaa\'; wa kaanal laahu Ghafoorar Raheemaa'),
  ('en.transliteration', 48, 15, 'Sa yaqoolul mukhalla foona izan talaqtum ilaa maghaanima litaakhuzoohaa zaroonaa nattabi\'kum yureedoona any yubaddiloo Kalaamallaah; qul lan tattabi\'oonaa kazaalikum qaalal laahu min qablu fasa yaqooloona bal tahsudoonanna; bal kaanoo laa yafqahoona illaa qaleela'),
  ('en.transliteration', 48, 16, 'Qul lilmukhallafeena minal A\'raabi satud\'awna ilaa qawmin ulee baasin shadeedin tuqaati loonahum aw yuslimoona fa in tutee\'oo yu\'tikumul laahu ajran hasananw wa in tatawallaw kamaa tawallaitum min qablu yu\'azzibkum \'azaaban aleemaa'),
  ('en.transliteration', 48, 17, 'Laisa \'alal a\'maa harajunw wa laa \'alal a\'raji harajunw wa laa \'alal mareedi haraj\' wa many yutil\'il laaha wa Rasoolahoo yudkhilhu jannaatin tajree min tahtihal anhaaru wa many yatawalla yu\'azzibhu \'azaaban aleemaa'),
  ('en.transliteration', 48, 18, 'Laqad radiyal laahu \'anil mu\'mineena iz yubaayi \'oonaka tahtash shajarati fa\'alima maa fee quloobihim fa anzalas sakeenata \'alaihim wa asaa bahum fat han qareebaa'),
  ('en.transliteration', 48, 19, 'Wa maghaanima kaseera tany yaakhuzoonahaa; wa kaanal laahu \'Azeezan Hakeemaa'),
  ('en.transliteration', 48, 20, 'Wa\'adakumul laahu ma ghaanima kaseeratan taakhuzoo nahaa fa\'ajjala lakum haazihee wa kaffa aydiyan naasi \'ankum wa litakoona aayatal lilmu\'mineena wa yahdiyakum siraatam mustaqeema'),
  ('en.transliteration', 48, 21, 'Wa ukhraa lam taqdiroo \'alaihaa qad ahaatal laahu bihaa; wa kaanal laahu \'alaa kulli shai\'in qadeera'),
  ('en.transliteration', 48, 22, 'Wa law qaatalakumul lazeena kafaroo la wallawul adbaara summa laa yajidoona waliyanw-wa laa naseeraa'),
  ('en.transliteration', 48, 23, 'Sunnatal laahil latee qad khalat min qablu wa lan tajida lisunnatil laahi tabdeelaa'),
  ('en.transliteration', 48, 24, 'Wa Huwal lazee kaffa aydiyahum \'ankum wa aydiyakum \'anhum bibatni Makkata mim ba\'di an azfarakum \'alaihim; wa kaanal laahu bimaa ta\'maloona Baseera'),
  ('en.transliteration', 48, 25, 'Humul lazeena kafaroo wa saddookum \'anil-Masjidil-Haraami walhadya ma\'koofan any yablugha mahillah; wa law laa rijaalum mu\'minoona wa nisaaa\'um mu\'minaatul lam ta\'lamoohum an tata\'oohum fatuseebakum minhum ma\'arratum bighairi \'ilmin liyud khilal laahu fee rahmatihee many yashaaa\'; law tazayyaloo la\'azzabnal lazeena kafaroo minhum \'azaaban aleema'),
  ('en.transliteration', 48, 26, 'Iz ja\'alal lazeena kafaroo fee quloobihimul hamiyyata hamiyyatal jaahiliyyati fa anzalal laahu sakeenatahoo \'alaa Rasoolihee wa \'alal mu mineena wa alzamahum kalimatat taqwaa wa kaanooo ahaqqa bihaa wa ahlahaa; wa kaanal laahu bikulli shai\'in Aleema'),
  ('en.transliteration', 48, 27, 'Laqad sadaqal laahu Rasoolahur ru\'yaa bilhaqq, latadkhulunnal Masjidal-Haraama in shaaa\'al laahu aamineena muhalliqeena ru\'oosakum wa muqassireena laa takhaafoona fa\'alima maa lam ta\'lamoo faja\'ala min dooni zaalika fathan qareebaa'),
  ('en.transliteration', 48, 28, 'Huwal lazeee arsala Rasoolahoo bilhudaa wa deenil haqqi liyuzhirahoo \'alad deeni kullih; wa kafaa billaahi Shaheeda'),
  ('en.transliteration', 48, 29, 'Muhammadur Rasoolul laah; wallazeena ma\'ahooo ashiddaaa\'u \'alal kuffaaari ruhamaaa\'u bainahum taraahum rukka\'an sujjadany yabtaghoona fadlam minal laahi wa ridwaanan seemaahum fee wujoohihim min asaris sujood; zaalika masaluhum fit tawraah; wa masaluhum fil Injeeli kazar\'in akhraja shat \'ahoo fa \'aazarahoo fastaghlaza fastawaa \'alaa sooqihee yu\'jibuz zurraa\'a liyagheeza bihimul kuffaar; wa\'adal laahul lazeena aamanoo wa \'amilus saalihaati minhum maghfiratanw wa ajran \'azeemaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 48, 1, 'بے شک ہم نے آپ کو کھلم کھلا فتح دی'),
  ('ur.ahmedali', 48, 2, 'تاکہ آپ کے اگلے اور پچھلے گناہ معاف کر دے اور اپنی نعمت آپ پر تمام کر دے اور تاکہ آپ کو سیدھے راستہ پر چلائے'),
  ('ur.ahmedali', 48, 3, 'اور تاکہ الله آپ کی زبردست مدد کرے'),
  ('ur.ahmedali', 48, 4, 'وہی تو ہے جس نے ایمانداروں کے دلو ں میں اطمینان اتارا تاکہ ان کا ایمان اور زیادہ ہو جائے اور آسمانوں اور زمین کے لشکر سب الله ہی کے ہیں اور الله خبردار حکمت والا ہے'),
  ('ur.ahmedali', 48, 5, 'تاکہ ایمان والے مردوں اور عورتوں کو بہشتوں میں داخل کرے جن کے نیچے نہریں بہہ رہی ہوں گی ان میں ہمیشہ رہیں گے اور ان پر سے ان کے گناہ دور کر دے گا اور الله کے ہاں یہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 48, 6, 'اور تاکہ منافق مردوں اور عورتوں کواور مشرک مردوں اور عورتوں کو عذاب دے جو الله کے بارے میں براگمان رکھتے ہیں انہیں پر بری گردش ہے اور الله نے ان پر غضب نازل کیا اور ان پر لعنت کی اوران کے لیے دوزخ تیار کر رکھا ہےاور وہ برا ٹھکانہ ہے'),
  ('ur.ahmedali', 48, 7, 'اور الله ہی کے سب لشکر آسمانوں اور زمین میں ہیں اور الله بڑا غالب حکمت والا ہے'),
  ('ur.ahmedali', 48, 8, 'بے شک ہم نے آپ کو گواہ بناکر بھیجا اور خوشخبری دینے والا اور ڈرانے والا'),
  ('ur.ahmedali', 48, 9, 'تاکہ تم الله پر اور اس کے رسول پر ایمان لاؤ اور اس کی مدد کرو اور اس کی عزت کرو اور صبح اور شام اس کی پاکی بیان کرو'),
  ('ur.ahmedali', 48, 10, 'بے شک جو لوگ آپ سے بیعت کر رہے ہیں وہ الله ہی سے بیعت کر رہے ہیں ان کے ہاتھوں پر الله کا ہاتھ ہے پس جو اس عہد کو) تو ڑ دے گا سو توڑنے کا وبال خود اسی پر ہو گا اور جو وہ عہد پورا کرے گا جو اس نے الله سے کیا ہے سو عقریب وہ اسے بہت بڑا اجر دے گا'),
  ('ur.ahmedali', 48, 11, 'عنقریب آ پ سے وہ لوگ کہیں گے جو بدویوں میں سے پیچھے رہ گئے تھے کہ ہمیں ہمارے اور اہل و عیال نے مشغول رکھا ہے آپ ہمارے لیے مغفرت مانگیئے وہ اپنی زبانوں سے وہ بات کہتے ہیں جو ان کے دلوں میں نہیں ہے کہدو وہ کون ہے جو الله کے سامنے تمہارے لیے کسی چیز کا (کچھ بھی) اختیار رکھتا ہوگا اگر الله تمہیں کوئی نقصان یا کوئی نفع پہنچانا چاہے بلکہ الله تمہارے سب اعمال پر خبردار ہے'),
  ('ur.ahmedali', 48, 12, 'بلکہ تم نے خیال کیا تھا کہ رسول الله اور مسلمان اپنے گھر والوں کی طرف کبھی بھی واپس نہ لوٹیں گے اور تمہارے دلوں میں یہ بات اچھی معلوم ہوئی اور تم نے بہت برا گمان کیا اور تم ہلاک ہونے والے لوگ تھے'),
  ('ur.ahmedali', 48, 13, 'اورجو لوگ الله اور اس کے رسول پر ایمان نہیں لائے سو ہم نے ایسے کافروں کے لیے بھڑکتی ہوئی آگ تیار کر رکھی ہے'),
  ('ur.ahmedali', 48, 14, 'اور آسمانوں اور زمین کی حکومت الله ہی کے لیے ہے وہ جسے چاہے بخشے اورجسے چاہے عذاب دے اور الله بخشنے والا بڑا مہربان ہے'),
  ('ur.ahmedali', 48, 15, 'عنقریب کہیں گے وہ لوگ جو پیچھے رہ گئے تھے جب تم غنیمتوں کی طرف ان کے لینے کے لیے جانے لگو گے کہ ہمیں چھوڑو ہم تمہارے ساتھ چلیں وہ چاہتے ہیں کہ الله کا حکم بدل دیں کہہ دو کہ تم ہرگز ہمارے ساتھ نہ چلو گے الله نے اس سے پہلے ہی ایسا فرما دیا ہے پس وہ کہیں گے کہ (نہیں) بلکہ تم ہم سے حسد کرتے ہو بلکہ وہ لوگ بات ہی کم سمجھتے ہیں'),
  ('ur.ahmedali', 48, 16, 'ان پیچھے رہ جکانے والے بدوؤں سے کہہ دو کہ بہت جلد تمہیں ایک سخت جنگجو قوم سے لڑنے کے لیے بلایا جائے گا تم ان سے لڑو گے یا وہ اطاعت قبول کر لے گی پھر اگر تم نے حکم مان لیا تو الله تمہیں بہت ہی اچھا انعام دے گا اور اگر تم پھر گئے جیسا کہ پہلے پھر گئے تھے تو تمہیں سخت عذاب دے گا'),
  ('ur.ahmedali', 48, 17, 'نہ اندھے پر کچھ گناہ ہے اور نہ لنگڑے ہی پرکچھ گناہ ہے اور نہ بیمار ی پرکچھ گناہے ہے اور جوکوئی الله اور اس کے رسول کی اطاعت کرے گا تو اسے ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہوں گی اور جو نافرمانی کرے گا اسے سخت سزا دے گا'),
  ('ur.ahmedali', 48, 18, 'بے شک الله مسلمانوں سے راضی ہوا جب وہ آپ سے درخت کے نیچے بیعت کر رہے تھے پھر اس نے جان لیا جو کچھ ان کے دلو ں میں تھا پس اس نے ان پر اطمینان نازل کر دیا اور انہیں جلد ہی فتح دے دی'),
  ('ur.ahmedali', 48, 19, 'اوربہت سی غنیمتیں بھی دے گا جنہیں وہ لیں گے اور الله زبردست حکمت والا ہے'),
  ('ur.ahmedali', 48, 20, 'الله نے تم سے بہت سی غنیمتوں کا وعدہ کیا ہے جنہیں تم حاصل کرو گے پھر تمہیں اس نے یہ جلدی دےدی اوراس نےتم سے لوگوں کے ہاتھ روک دیئے اور تاکہ ایمان لانے والوں کے لیے یہ ایک نشان ہو اور تاکہ تم سیدھے راستہ پر چلائے'),
  ('ur.ahmedali', 48, 21, 'اور بھی فتوحات ہیں کہ جو (اب تک) تمہارے بس میں نہیں آئیں البتہ الله کے بس میں ہیں اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 48, 22, 'اور اگر کافر تم سے لڑتے تو پیٹھ پھیر کر بھاگ پڑتے پھر نہ کوئی حمایتی پاتے نہ کوئی مددگار'),
  ('ur.ahmedali', 48, 23, 'الله کا قدیم دستور پہلے سے یونہی چلا آتا ہے اور تو اس کے دستور کو بدلا ہوا نہ پائے گا'),
  ('ur.ahmedali', 48, 24, 'اوروہی ہے جس نے وادی مکہ میں ان کے ہاتھ تم سے اور تمہارے ہاتھ ان سے روک دیے اس کے بعد اس نے تمہیں ان پر غالب کر دیا تھا اور الله ان سب باتوں کو جو تم کر رہے تھے دیکھ رہا تھا'),
  ('ur.ahmedali', 48, 25, 'وہ تو وہی ہیں جنہوں نے انکار کیا اور تمہیں مسجد حرام سے روکا اور قربانی کے جانوروں کو روکے رکھا اس سے کہ وہ اپنی قربان گاہ تک پہنچیں اور اگر کچھ مرد ایمان والے اور عورتیں ایمان والی نہ ہوتیں جنہیں تم نہیں جانتے تھے کہ تم انہیں پامال کر دیتے پھر ان کی طرف سے تم پر نادانستگی سے الزام آتا (تو تمہیں لڑنے سے نہ روکا جاتا) تاکہ الله اپنی رحمت میں جسے چاہے داخل کرے اگر وہ ٹل گئے ہوتے تو ہم ان میں سے جو کافر ہیں انہیں دردناک عذاب دیتے'),
  ('ur.ahmedali', 48, 26, 'جب کہ کافروں نے اپنے دل میں سخت جوش پیدا کیا تھا جہالت کا جوش تھا پھر الله نے بھی اپنی تسکین اپنے رسول اور ایمان والوں پر نازل کر دی اور ان کو پرہیزگاری کی بات پر قائم رکھا اور وہ اسی کے لائق اور قابل بھی تھے اور الله ہر چیز کو جانتا ہے'),
  ('ur.ahmedali', 48, 27, 'بے شک الله نے اپنے رسول کا خواب سچا کر دکھایا کہ اگر الله نے چاہا تو تم امن کے ساتھ مسجد حرام میں ضرور داخل ہو گے اپنے سر منڈاتے ہوئے اور بال کتراتے ہوئے بے خوف و خطر ہوں گے پس جس بات کو تم نہ جانتے تھے اس نے اسے جان لیا تھا پھر اس نے اس سے پہلےہی ایک فتح بہت جلدی کر دی'),
  ('ur.ahmedali', 48, 28, 'وہی تو ہے جس نے اپنے رسول کو ہدایت اور سچا دین دے کر بھیجا تاکہ اسے ہر ایک دین پر غالب کرے اور الله کی شہادت کافی ہے'),
  ('ur.ahmedali', 48, 29, 'محمد الله کے رسول ہیں اور جو لوگ آپ کے ساتھ ہیں کفار پر سخت ہیں آپس میں رحم دل ہیں تو انہیں دیکھے گا کہ رکوع و سجود کر رہے ہیں الله کا فضل اوراس کی خوشنودی تلاش کرتے ہیں ان کی شناخت ان کے چہرو ں میں سجدہ کا نشان ہے یہی وصف ان کا تو رات میں ہے اور انجیل میں ان کا وصف ہے مثل اس کھیتی کے جس نے اپنی سوئی نکالی پھر اسے قوی کر دیا پھر موٹی ہوگئی پھر اپنے تنہ پر کھڑی ہوگئی کسانوں کو خوش کرنے لگی تاکہ الله ان کی وجہ سے کفار کو غصہ دلائے الله ان میں سے ایمان داروں اورنیک کام کرنے والوں کے لیے بخشش اور اجر عظیم کا وعدہ کیا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 48, 1, 'Doğrusu Biz sana apaçık bir zafer sağlamışızdır.'),
  ('tr.diyanet', 48, 2, 'Allah böylece, senin geçmiş ve gelecek günahlarını bağışlar, sana olan nimetini tamamlar, seni doğru yola eriştirir.'),
  ('tr.diyanet', 48, 3, 'Böylece sana, kimsenin güç yetiremeyeceği bir şekilde yardım eder.'),
  ('tr.diyanet', 48, 4, 'İnananların, imanlarını kat kat artırmaları için, kalblerine güven indiren O\'dur. Göklerdeki ve yerdeki ordular Allah\'ındır. Allah bilendir, Hakim olandır.'),
  ('tr.diyanet', 48, 5, 'İnanan erkek ve kadınları, içinde temelli kalacakları, içlerinden ırmaklar akan cennetlere koyar, onların kötülüklerini örter. Allah katında büyük kurtuluş işte budur.'),
  ('tr.diyanet', 48, 6, 'İnananlara yardım etmez diye Allah\'a kötü sanıda bulunan ikiyüzlü erkek ve kadınlara, puta tapan erek ve kadınlara Allah azabetsin; kötü sanıları kendi baslarına gelsin! Allah onlara gazabetmiş, onları lanetlemiş ve cehennemi kendilerine hazırlamıştır. Ne kötü dönüş yeridir!'),
  ('tr.diyanet', 48, 7, 'Göklerdeki ve yerdeki ordular Allah\'ındır. Allah güçlü olandır. Hakim olandır.'),
  ('tr.diyanet', 48, 8, 'Doğrusu seni şahit, müjdeci ve uyarıcı olarak gönderdik. Ey insanlar, siz de Allah\'a ve Peygamberine inanasınız, ona yardım edesiniz, O\'na saygı gösteresiniz ve O\'nu sabah akşam tesbih edesiniz.'),
  ('tr.diyanet', 48, 9, 'Doğrusu seni şahit, müjdeci ve uyarıcı olarak gönderdik. Ey insanlar, siz de Allah\'a ve Peygamberine inanasınız, ona yardım edesiniz, O\'na saygı gösteresiniz ve O\'nu sabah akşam tesbih edesiniz.'),
  ('tr.diyanet', 48, 10, 'Şüphesiz sana baş eğerek ellerini verenler (biat edenler), Allah\'a baş eğip el vermiş sayılırlar. Allah\'ın eli onların ellerinin üstündedir. Verdiği bu sözden dönen, ancak kendi aleyhine dönmüş olur. Allah\'a verdiği sözü yerine getirene, Allah büyük ecir verecektir.'),
  ('tr.diyanet', 48, 11, 'Bedevilerin savaştan geri kalmış olanları, sana: "Bizi mallarımız ve ailelerimiz alıkoydu. Allah\'tan bizim bağışlanmamızı dile" diyecekler. Dilleriyle, gönüllerinde bulunmayanı söylerler; de ki: "Allah size bir zarar gelmesini dilerse, yahut bir fayda elde etmenizi dilerse, O\'na karşı kimin gücü bir şeye yeter? Kaldı ki, Allah yaptıklarınızdan haberdardır."'),
  ('tr.diyanet', 48, 12, 'Aslında siz, Peygamberin ve inananların, ailelerine bir daha dönmeyeceklerini sanmıştınız. Bu, gönüllerinize güzel görünmüştü de kötü sanıda bulunmuştunuz. Hayırsız bir topluluk oldunuz.'),
  ('tr.diyanet', 48, 13, 'Allah\'a ve Peygamberine kim inanmamışsa bilsin ki, şüphesiz Biz, inkarcılar için çılgın alevli cehennemi hazırlamışızdır.'),
  ('tr.diyanet', 48, 14, 'Göklerin ve yerin hükümranlığı Allah\'ındır. O, dilediğini bağışlar, dilediğine azabeder. Allah bağışlayandır, merhamet edendir.'),
  ('tr.diyanet', 48, 15, 'Savaştan geri kalmış olanlar, siz ganimetleri almaya giderken: "Bırakın, biz de sizinle gelelim" diyeceklerdir. Onlar Allah\'ın sözünü değiştirmek isterler. De ki: "Bize uymayacaksınız; Allah sizin için önceden böyle buyurmuştur." Size: "Hayır, bizi çekemiyorsunuz" diyecekler. Aksine, kendileri ancak pek az söz anlayan kimselerdir.'),
  ('tr.diyanet', 48, 16, 'Bedevilerden geri kalmış olanlara de ki: "güçlü kuvvetli bir millete karşı, onlar müslüman olana kadar savaşmaya çağrılacaksanız; eğer itaat ederseniz Allah size güzel ecir verir, ama daha önce döndüğünüz gibi yine dönecek olursanız sizi can yakan bir azaba uğratır."'),
  ('tr.diyanet', 48, 17, 'Ama, gözleri görmeyen kimse savaşa gelmezse ona bir sorumluluk yoktur; topala ve hastaya da sorumluluk yoktur. Kim Allah\'a ve peygamberine itaat ederse, Allah onu, içlerinden ırmaklar akan cennetlere koyar. Kim yüz çevirirse, onu can yakıcı azaba uğratır.'),
  ('tr.diyanet', 48, 18, 'Allah inananlardan, ağaç altında sana baş eğerek el verirlerken, and olsun ki hoşnut olmuştur. Gönüllerinde olanı da bilmiş, onlara güvenlik vermiş, onlara yakın bir zafer ve ele geçirecekleri bol ganimetler bahşetmiştir. Allah, güçlü olandır, Hakim olandır.'),
  ('tr.diyanet', 48, 19, 'Allah inananlardan, ağaç altında sana baş eğerek el verirlerken, and olsun ki hoşnut olmuştur. Gönüllerinde olanı da bilmiş, onlara güvenlik vermiş, onlara yakın bir zafer ve ele geçirecekleri bol ganimetler bahşetmiştir. Allah, güçlü olandır, Hakim olandır.'),
  ('tr.diyanet', 48, 20, 'Allah size, ele geçireceğiniz bol bol ganimetler vadetmiştir. İnananlar için bir belge olması, sizi doğru yola eriştirmesi için bunları size hemen vermiş ve insanların size uzanan ellerini önlemiştir.'),
  ('tr.diyanet', 48, 21, 'Bundan başka, sizin gücünüzün yetmediği fakat Allah\'ın sizin için sakladığı ganimetler de vardır. Allah her şeye Kadir olandır.'),
  ('tr.diyanet', 48, 22, 'İnkar edenler sizinle savaşsalardı yüzgeri döneceklerdi. Sonra bir dost ve yardımcı da bulamayacaklardı.'),
  ('tr.diyanet', 48, 23, 'Allah\'ın önceden gelip geçmişlere uyguladığı yasası budur. Allah\'ın yasasında değişme bulamazsın.'),
  ('tr.diyanet', 48, 24, 'Sizi onlara üstün kıldıktan sonra, Mekke bölgesinde, onların ellerini sizden, sizin ellerinizi onlardan geri tutan, savaşı önleyen O\'dur. Allah yaptıklarınızı görendir.'),
  ('tr.diyanet', 48, 25, 'Onlar inkar edenlerdir, sizi Mescidi Haram\'ı ziyaretten ve bağlı kurbanları yerlerine gitmekten alıkoyanlardır. Eğer, oradaki henüz tanımadığınız inanmış erkeklerle inanmış kadınları bilmeyerek ezmek suretiyle üzüntüye kapılmanız ihtimali olmasaydı Allah savaşı önlemezdi. Allah, dilediklerine rahmet etmek için böyle yapmıştır. Eğer inananlarla inkarcılar birbirinden ayrılmış olsalardı, inkar edenleri can yakıcı bir azaba uğratırdık.'),
  ('tr.diyanet', 48, 26, 'İnkar edenler, gönüllerindeki cahiliyye çağının asabiyet ateşini ateşlendirdiklerinde, Allah, Peygamberine ve inananlara huzur indirdi; onların takva sözünü tutmalarını sağladı. Onlar, bu söze layık ve ehil kimselerdi. Allah her şeyi bilmektedir.'),
  ('tr.diyanet', 48, 27, 'And olsun ki Allah, Peygamberinin rüyasının gerçek olduğunu tasdik eder. Ey inananlar! Siz, Allah dilerse, güven içinde, başlarınızı tıraş etmiş veya saçlarınızı kısaltmış olarak, korkmadan Mescidi Haram\'a gireceksiniz. Allah, sizin bilmediğinizi bilir. Size, bundan başka, yakın zamanda bir zafer verecektir.'),
  ('tr.diyanet', 48, 28, 'Bütün dinlerden üstün kılmak üzere, Peygamberini, doğruluk rehberi Kuran ve hak din ile gönderen O\'dur. Şahit olarak Allah yeter.'),
  ('tr.diyanet', 48, 29, 'Muhammed Allah\'ın elçisidir. Onun beraberinde bulunanlar, inkarcılara karşı sert, birbirlerine merhametlidirler. Onları rükua varırken, secde ederken, Allah\'tan lütuf ve hoşnudluk dilerken görürsün. Onlar, yüzlerindeki secde izi ile tanınırlar. İşte bu, onların Tevrat\'ta anlatılan vasıflarıdır. İncil\'de de şöyle vasıflandırılmışlardı: Filizini çıkarmış, onu kuvvetlendirmiş, kalınlaşmış, gövdesi üzerine dikilmiş, ekincilerin hoşuna giden ekin gibidirler. Allah böylece bunları çoğaltıp kuvvetlendirmekle inkarcıları öfkelendirir. Allah, inanıp yararlı işler işleyenlere, bağışlama ve büyük ecir vadetmiştir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 48, 1, 'Sesungguhnya Kami telah memberikan kepadamu kemenangan yang nyata,'),
  ('id.indonesian', 48, 2, 'supaya Allah memberi ampunan kepadamu terhadap dosamu yang telah lalu dan yang akan datang serta menyempurnakan nikmat-Nya atasmu dan memimpin kamu kepada jalan yang lurus,'),
  ('id.indonesian', 48, 3, 'dan supaya Allah menolongmu dengan pertolongan yang kuat (banyak).'),
  ('id.indonesian', 48, 4, 'Dialah yang telah menurunkan ketenangan ke dalam hati orang-orang mukmin supaya keimanan mereka bertambah di samping keimanan mereka (yang telah ada). Dan kepunyaan Allah-lah tentara langit dan bumi dan adalah Allah Maha Mengetahui lagi Maha Bijaksana,'),
  ('id.indonesian', 48, 5, 'supaya Dia memasukkan orang-orang mukmin laki-laki dan perempuan ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya dan supaya Dia menutupi kesalahan-kesalahan mereka. Dan yang demikian itu adalah keberuntungan yang besar di sisi Allah,'),
  ('id.indonesian', 48, 6, 'dan supaya Dia mengazab orang-orang munafik laki-laki dan perempuan dan orang-orang musyrik laki-laki dan perempuan yang mereka itu berprasangka buruk terhadap Allah. Mereka akan mendapat giliran (kebinasaan) yang amat buruk dan Allah memurkai dan mengutuk mereka serta menyediakan bagi mereka neraka Jahannam. Dan (neraka Jahannam) itulah sejahat-jahat tempat kembali.'),
  ('id.indonesian', 48, 7, 'Dan kepunyaan Allah-lah tentara langit dan bumi. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 48, 8, 'Sesungguhnya Kami mengutus kamu sebagai saksi, pembawa berita gembira dan pemberi peringatan,'),
  ('id.indonesian', 48, 9, 'supaya kamu sekalian beriman kepada Allah dan Rasul-Nya, menguatkan (agama)Nya, membesarkan-Nya. Dan bertasbih kepada-Nya di waktu pagi dan petang.'),
  ('id.indonesian', 48, 10, 'Bahwasanya orang-orang yang berjanji setia kepada kamu sesungguhnya mereka berjanji setia kepada Allah. Tangan Allah di atas tangan mereka, maka barangsiapa yang melanggar janjinya niscaya akibat ia melanggar janji itu akan menimpa dirinya sendiri dan barangsiapa menepati janjinya kepada Allah maka Allah akan memberinya pahala yang besar.'),
  ('id.indonesian', 48, 11, 'Orang-orang Badwi yang tertinggal (tidak turut ke Hudaibiyah) akan mengatakan: "Harta dan keluarga kami telah merintangi kami, maka mohonkanlah ampunan untuk kami"; mereka mengucapkan dengan lidahnya apa yang tidak ada dalam hatinya. Katakanlah: "Maka siapakah (gerangan) yang dapat menghalang-halangi kehendak Allah jika Dia menghendaki kemudharatan bagimu atau jika Dia menghendaki manfaat bagimu. Sebenarnya Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 48, 12, 'Tetapi kamu menyangka bahwa Rasul dan orang-orang mukmin tidak sekali-kali akan kembali kepada keluarga mereka selama-lamanya dan syaitan telah menjadikan kamu memandang baik dalam hatimu persangkaan itu, dan kamu telah menyangka dengan sangkaan yang buruk dan kamu menjadi kaum yang binasa.'),
  ('id.indonesian', 48, 13, 'Dan barangsiapa yang tidak beriman kepada Allah dan Rasul-Nya maka sesungguhnya Kami menyediakan untuk orang-orang yang kafir neraka yang bernyala-nyala.'),
  ('id.indonesian', 48, 14, 'Dan hanya kepunyaan Allah-lah kerajaan langit dan bumi. Dia memberikan ampun kepada siapa yang dikehendaki-Nya dan mengazab siapa yang dikehendaki-Nya. Dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 48, 15, 'Orang-orang Badwi yang tertinggal itu akan berkata apabila kamu berangkat untuk mengambil barang rampasan: "Biarkanlah kami, niscaya kami mengikuti kamu"; mereka hendak merubah janji Allah. Katakanlah: "Kamu sekali-kali tidak (boleh) mengikuti kami; demikian Allah telah menetapkan sebelumnya"; mereka akan mengatakan: "Sebenarnya kamu dengki kepada kami". Bahkan mereka tidak mengerti melainkan sedikit sekali.'),
  ('id.indonesian', 48, 16, 'Katakanlah kepada orang-orang Badwi yang tertinggal: "Kamu akan diajak untuk (memerangi) kaum yang mempunyai kekuatan yang besar, kamu akan memerangi mereka atau mereka menyerah (masuk Islam). Maka jika kamu patuhi (ajakan itu) niscaya Allah akan memberikan kepadamu pahala yang baik dan jika kamu berpaling sebagaimana kamu telah berpaling sebelumnya, niscaya Dia akan mengazab kamu dengan azab yang pedih".'),
  ('id.indonesian', 48, 17, 'Tiada dosa atas orang-orang yang buta dan atas orang yang pincang dan atas orang yang sakit (apabila tidak ikut berperang). Dan barangsiapa yang taat kepada Allah dan Rasul-Nya; niscaya Allah akan memasukkannya ke dalam surga yang mengalir di bawahnya sungai-sungai dan barang siapa yang berpaling niscaya akan diazab-Nya dengan azab yang pedih.'),
  ('id.indonesian', 48, 18, 'Sesungguhnya Allah telah ridha terhadap orang-orang mukmin ketika mereka berjanji setia kepadamu di bawah pohon, maka Allah mengetahui apa yang ada dalam hati mereka lalu menurunkan ketenangan atas mereka dan memberi balasan kepada mereka dengan kemenangan yang dekat (waktunya).'),
  ('id.indonesian', 48, 19, 'Serta harta rampasan yang banyak yang dapat mereka ambil. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 48, 20, 'Allah menjanjikan kepada kamu harta rampasan yang banyak yang dapat kamu ambil, maka disegerakan-Nya harta rampasan ini untukmu dan Dia menahan tangan manusia dari (membinasakan)mu (agar kamu mensyukuri-Nya) dan agar hal itu menjadi bukti bagi orang-orang mukmin dan agar Dia menunjuki kamu kepada jalan yang lurus.'),
  ('id.indonesian', 48, 21, 'Dan (telah menjanjikan pula kemenangan-kemenangan) yang lain (atas negeri-negeri) yang kamu belum dapat menguasainya yang sungguh Allah telah menentukan-Nya. Dan adalah Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 48, 22, 'Dan sekiranya orang-orang kafir itu memerangi kamu pastilah mereka berbalik melarikan diri ke belakang (kalah) kemudian mereka tiada memperoleh pelindung dan tidak (pula) penolong.'),
  ('id.indonesian', 48, 23, 'Sebagai suatu sunnatullah yang telah berlaku sejak dahulu, kamu sekali-kali tiada akan menemukan perubahan bagi sunnatullah itu.'),
  ('id.indonesian', 48, 24, 'Dan Dialah yang menahan tangan mereka dari (membinasakan) kamu dan (menahan) tangan kamu dari (membinasakan) mereka di tengah kota Mekah sesudah Allah memenangkan kamu atas mereka, dan adalah Allah Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 48, 25, 'Merekalah orang-orang yang kafir yang menghalangi kamu dari (masuk) Masjidil Haram dan menghalangi hewan korban sampai ke tempat (penyembelihan)nya. Dan kalau tidaklah karena laki-laki yang mukmin dan perempuan-perempuan yang mukmin yang tiada kamu ketahui, bahwa kamu akan membunuh mereka yang menyebabkan kamu ditimpa kesusahan tanpa pengetahuanmu (tentulah Allah tidak akan menahan tanganmu dari membinasakan mereka). Supaya Allah memasukkan siapa yang dikehendaki-Nya ke dalam rahmat-Nya. Sekiranya mereka tidak bercampur-baur, tentulah Kami akan mengazab orang-orang yag kafir di antara mereka dengan azab yang pedih.'),
  ('id.indonesian', 48, 26, 'Ketika orang-orang kafir menanamkan dalam hati mereka kesombongan (yaitu) kesombongan jahiliyah lalu Allah menurunkan ketenangan kepada Rasul-Nya, dan kepada orang-orang mukmin dan Allah mewajibkan kepada mereka kalimat-takwa dan adalah mereka berhak dengan kalimat takwa itu dan patut memilikinya. Dan adalah Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 48, 27, 'Sesungguhnya Allah akan membuktikan kepada Rasul-Nya, tentang kebenaran mimpinya dengan sebenarnya (yaitu) bahwa sesungguhnya kamu pasti akan memasuki Masjidil Haram, insya Allah dalam keadaan aman, dengan mencukur rambut kepala dan mengguntingnya, sedang kamu tidak merasa takut. Maka Allah mengetahui apa yang tiada kamu ketahui dan Dia memberikan sebelum itu kemenangan yang dekat.'),
  ('id.indonesian', 48, 28, 'Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang hak agar dimenangkan-Nya terhadap semua agama. Dan cukuplah Allah sebagai saksi.'),
  ('id.indonesian', 48, 29, 'Muhammad itu adalah utusan Allah dan orang-orang yang bersama dengan dia adalah keras terhadap orang-orang kafir, tetapi berkasih sayang sesama mereka. Kamu lihat mereka ruku\' dan sujud mencari karunia Allah dan keridhaan-Nya, tanda-tanda mereka tampak pada muka mereka dari bekas sujud. Demikianlah sifat-sifat mereka dalam Taurat dan sifat-sifat mereka dalam Injil, yaitu seperti tanaman yang mengeluarkan tunasnya maka tunas itu menjadikan tanaman itu kuat lalu menjadi besarlah dia dan tegak lurus di atas pokoknya; tanaman itu menyenangkan hati penanam-penanamnya karena Allah hendak menjengkelkan hati orang-orang kafir (dengan kekuatan orang-orang mukmin). Allah menjanjikan kepada orang-orang yang beriman dan mengerjakan amal yang saleh di antara mereka ampunan dan pahala yang besar.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 49, 1, 'O you who have believed, do not put [yourselves] before Allah and His Messenger but fear Allah. Indeed, Allah is Hearing and Knowing.'),
  ('en.sahih', 49, 2, 'O you who have believed, do not raise your voices above the voice of the Prophet or be loud to him in speech like the loudness of some of you to others, lest your deeds become worthless while you perceive not.'),
  ('en.sahih', 49, 3, 'Indeed, those who lower their voices before the Messenger of Allah - they are the ones whose hearts Allah has tested for righteousness. For them is forgiveness and great reward.'),
  ('en.sahih', 49, 4, 'Indeed, those who call you, [O Muhammad], from behind the chambers - most of them do not use reason.'),
  ('en.sahih', 49, 5, 'And if they had been patient until you [could] come out to them, it would have been better for them. But Allah is Forgiving and Merciful.'),
  ('en.sahih', 49, 6, 'O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful.'),
  ('en.sahih', 49, 7, 'And know that among you is the Messenger of Allah. If he were to obey you in much of the matter, you would be in difficulty, but Allah has endeared to you the faith and has made it pleasing in your hearts and has made hateful to you disbelief, defiance and disobedience. Those are the [rightly] guided.'),
  ('en.sahih', 49, 8, '[It is] as bounty from Allah and favor. And Allah is Knowing and Wise.'),
  ('en.sahih', 49, 9, 'And if two factions among the believers should fight, then make settlement between the two. But if one of them oppresses the other, then fight against the one that oppresses until it returns to the ordinance of Allah. And if it returns, then make settlement between them in justice and act justly. Indeed, Allah loves those who act justly.'),
  ('en.sahih', 49, 10, 'The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy.'),
  ('en.sahih', 49, 11, 'O you who have believed, let not a people ridicule [another] people; perhaps they may be better than them; nor let women ridicule [other] women; perhaps they may be better than them. And do not insult one another and do not call each other by [offensive] nicknames. Wretched is the name of disobedience after [one\'s] faith. And whoever does not repent - then it is those who are the wrongdoers.'),
  ('en.sahih', 49, 12, 'O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allah; indeed, Allah is Accepting of repentance and Merciful.'),
  ('en.sahih', 49, 13, 'O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most noble of you in the sight of Allah is the most righteous of you. Indeed, Allah is Knowing and Acquainted.'),
  ('en.sahih', 49, 14, 'The bedouins say, "We have believed." Say, "You have not [yet] believed; but say [instead], \'We have submitted,\' for faith has not yet entered your hearts. And if you obey Allah and His Messenger, He will not deprive you from your deeds of anything. Indeed, Allah is Forgiving and Merciful."'),
  ('en.sahih', 49, 15, 'The believers are only the ones who have believed in Allah and His Messenger and then doubt not but strive with their properties and their lives in the cause of Allah. It is those who are the truthful.'),
  ('en.sahih', 49, 16, 'Say, "Would you acquaint Allah with your religion while Allah knows whatever is in the heavens and whatever is on the earth, and Allah is Knowing of all things?"'),
  ('en.sahih', 49, 17, 'They consider it a favor to you that they have accepted Islam. Say, "Do not consider your Islam a favor to me. Rather, Allah has conferred favor upon you that He has guided you to the faith, if you should be truthful."'),
  ('en.sahih', 49, 18, 'Indeed, Allah knows the unseen [aspects] of the heavens and the earth. And Allah is Seeing of what you do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 49, 1, 'মুমিনগণ! তোমরা আল্লাহ ও রসূলের সামনে অগ্রণী হয়ো না এবং আল্লাহকে ভয় কর। নিশ্চয় আল্লাহ সবকিছু শুনেন ও জানেন।'),
  ('bn.bengali', 49, 2, 'মুমিনগণ! তোমরা নবীর কন্ঠস্বরের উপর তোমাদের কন্ঠস্বর উঁচু করো না এবং তোমরা একে অপরের সাথে যেরূপ উঁচুস্বরে কথা বল, তাঁর সাথে সেরূপ উঁচুস্বরে কথা বলো না। এতে তোমাদের কর্ম নিস্ফল হয়ে যাবে এবং তোমরা টেরও পাবে না।'),
  ('bn.bengali', 49, 3, 'যারা আল্লাহর রসূলের সামনে নিজেদের কন্ঠস্বর নীচু করে, আল্লাহ তাদের অন্তরকে শিষ্টাচারের জন্যে শোধিত করেছেন। তাদের জন্যে রয়েছে ক্ষমা ও মহাপুরস্কার।'),
  ('bn.bengali', 49, 4, 'যারা প্রাচীরের আড়াল থেকে আপনাকে উচুস্বরে ডাকে, তাদের অধিকাংশই অবুঝ।'),
  ('bn.bengali', 49, 5, 'যদি তারা আপনার বের হয়ে তাদের কাছে আসা পর্যন্ত সবর করত, তবে তা-ই তাদের জন্যে মঙ্গলজনক হত। আল্লাহ ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 49, 6, 'মুমিনগণ! যদি কোন পাপাচারী ব্যক্তি তোমাদের কাছে কোন সংবাদ আনয়ন করে, তবে তোমরা পরীক্ষা করে দেখবে, যাতে অজ্ঞতাবশতঃ তোমরা কোন সম্প্রদায়ের ক্ষতিসাধনে প্রবৃত্ত না হও এবং পরে নিজেদের কৃতকর্মের জন্যে অনুতপ্ত না হও।'),
  ('bn.bengali', 49, 7, 'তোমরা জেনে রাখ তোমাদের মধ্যে আল্লাহর রসূল রয়েছেন। তিনি যদি অনেক বিষয়ে তোমাদের আবদার মেনে নেন, তবে তোমরাই কষ্ট পাবে। কিন্তু আল্লাহ তোমাদের অন্তরে ঈমানের মহব্বত সৃষ্টি করে দিয়েছেন এবং তা হৃদয়গ্রাহী করে দিয়েছেন। পক্ষান্তরে কুফর, পাপাচার ও নাফরমানীর প্রতি ঘৃণা সৃষ্টি করে দিয়েছেন। তারাই সৎপথ অবলম্বনকারী।'),
  ('bn.bengali', 49, 8, 'এটা আল্লাহর কৃপা ও নিয়ামতঃ আল্লাহ সর্বজ্ঞ প্রজ্ঞাময়।'),
  ('bn.bengali', 49, 9, 'যদি মুমিনদের দুই দল যুদ্ধে লিপ্ত হয়ে পড়ে, তবে তোমরা তাদের মধ্যে মীমাংসা করে দিবে। অতঃপর যদি তাদের একদল অপর দলের উপর চড়াও হয়, তবে তোমরা আক্রমণকারী দলের বিরুদ্ধে যুদ্ধ করবে; যে পর্যন্ত না তারা আল্লাহর নির্দেশের দিকে ফিরে আসে। যদি ফিরে আসে, তবে তোমরা তাদের মধ্যে ন্যায়ানুগ পন্থায় মীমাংসা করে দিবে এবং ইনছাফ করবে। নিশ্চয় আল্লাহ ইনছাফকারীদেরকে পছন্দ করেন।'),
  ('bn.bengali', 49, 10, 'মুমিনরা তো পরস্পর ভাই-ভাই। অতএব, তোমরা তোমাদের দুই ভাইয়ের মধ্যে মীমাংসা করবে এবং আল্লাহকে ভয় করবে-যাতে তোমরা অনুগ্রহপ্রাপ্ত হও।'),
  ('bn.bengali', 49, 11, 'মুমিনগণ, কেউ যেন অপর কাউকে উপহাস না করে। কেননা, সে উপহাসকারী অপেক্ষা উত্তম হতে পারে এবং কোন নারী অপর নারীকেও যেন উপহাস না করে। কেননা, সে উপহাসকারিণী অপেক্ষা শ্রেষ্ঠ হতে পারে। তোমরা একে অপরের প্রতি দোষারোপ করো না এবং একে অপরকে মন্দ নামে ডেকো না। কেউ বিশ্বাস স্থাপন করলে তাদের মন্দ নামে ডাকা গোনাহ। যারা এহেন কাজ থেকে তওবা না করে তারাই যালেম।'),
  ('bn.bengali', 49, 12, 'মুমিনগণ, তোমরা অনেক ধারণা থেকে বেঁচে থাক। নিশ্চয় কতক ধারণা গোনাহ। এবং গোপনীয় বিষয় সন্ধান করো না। তোমাদের কেউ যেন কারও পশ্চাতে নিন্দা না করে। তোমাদের কেউ কি তারা মৃত ভ্রাতার মাংস ভক্ষণ করা পছন্দ করবে? বস্তুতঃ তোমরা তো একে ঘৃণাই কর। আল্লাহকে ভয় কর। নিশ্চয় আল্লাহ তওবা কবুলকারী, পরম দয়ালু।'),
  ('bn.bengali', 49, 13, 'হে মানব, আমি তোমাদেরকে এক পুরুষ ও এক নারী থেকে সৃষ্টি করেছি এবং তোমাদেরকে বিভিন্ন জাতি ও গোত্রে বিভক্ত করেছি, যাতে তোমরা পরস্পরে পরিচিতি হও। নিশ্চয় আল্লাহর কাছে সে-ই সর্বাধিক সম্ভ্রান্ত যে সর্বাধিক পরহেযগার। নিশ্চয় আল্লাহ সর্বজ্ঞ, সবকিছুর খবর রাখেন।'),
  ('bn.bengali', 49, 14, 'মরুবাসীরা বলেঃ আমরা বিশ্বাস স্থাপন করেছি। বলুনঃ তোমরা বিশ্বাস স্থাপন করনি; বরং বল, আমরা বশ্যতা স্বীকার করেছি। এখনও তোমাদের অন্তরে বিশ্বাস জন্মেনি। যদি তোমরা আল্লাহ ও তাঁর রসূলের আনুগত্য কর, তবে তোমাদের কর্ম বিন্দুমাত্রও নিস্ফল করা হবে না। নিশ্চয়, আল্লাহ ক্ষমাশীল, পরম মেহেরবান।'),
  ('bn.bengali', 49, 15, 'তারাই মুমিন, যারা আল্লাহ ও তাঁর রসূলের প্রতি ঈমান আনার পর সন্দেহ পোষণ করে না এবং আল্লাহর পথে প্রাণ ও ধন-সম্পদ দ্বারা জেহাদ করে। তারাই সত্যনিষ্ঠ।'),
  ('bn.bengali', 49, 16, 'বলুনঃ তোমরা কি তোমাদের ধর্ম পরায়ণতা সম্পর্কে আল্লাহকে অবহিত করছ? অথচ আল্লাহ জানেন যা কিছু আছে ভূমন্ডলে এবং যা কিছু আছে নভোমন্ডলে। আল্লাহ সর্ববিষয়ে সম্যক জ্ঞাত।'),
  ('bn.bengali', 49, 17, 'তারা মুসলমান হয়ে আপনাকে ধন্য করেছে মনে করে। বলুন, তোমরা মুসলমান হয়ে আমাকে ধন্য করেছ মনে করো না। বরং আল্লাহ ঈমানের পথে পরিচালিত করে তোমাদেরকে ধন্য করেছেন, যদি তোমরা সত্যনিষ্ঠ হয়ে থাক।'),
  ('bn.bengali', 49, 18, 'আল্লাহ নভোমন্ডল ও ভূমন্ডলের অদৃশ্য বিষয় জানেন, তোমরা যা কর আল্লাহ তা দেখেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 49, 1, 'O ye who believe! Be not forward in the presence of Allah and His messenger, and keep your duty to Allah. Lo! Allah is Hearer, Knower.'),
  ('en.pickthall', 49, 2, 'O ye who believe! Lift not up your voices above the voice of the Prophet, nor shout when speaking to him as ye shout one to another, lest your works be rendered vain while ye perceive not.'),
  ('en.pickthall', 49, 3, 'Lo! they who subdue their voices in the presence of the messenger of Allah, those are they whose hearts Allah hath proven unto righteousness. Theirs will be forgiveness and immense reward.'),
  ('en.pickthall', 49, 4, 'Lo! those who call thee from behind the private apartments, most of them have no sense.'),
  ('en.pickthall', 49, 5, 'And if they had had patience till thou camest forth unto them, it had been better for them. And Allah is Forgiving, Merciful.'),
  ('en.pickthall', 49, 6, 'O ye who believe! If an evil-liver bring you tidings, verify it, lest ye smite some folk in ignorance and afterward repent of what ye did.'),
  ('en.pickthall', 49, 7, 'And know that the messenger of Allah is among you. If he were to obey you in much of the government, ye would surely be in trouble; but Allah hath endeared the faith to you and hath beautified it in your hearts, and hath made disbelief and lewdness and rebellion hateful unto you. Such are they who are the rightly guided.'),
  ('en.pickthall', 49, 8, '(It is) a bounty and a grace from Allah; and Allah is Knower, Wise.'),
  ('en.pickthall', 49, 9, 'And if two parties of believers fall to fighting, then make peace between them. And if one party of them doeth wrong to the other, fight ye that which doeth wrong till it return unto the ordinance of Allah; then, if it return, make peace between them justly, and act equitably. Lo! Allah loveth the equitable.'),
  ('en.pickthall', 49, 10, 'The believers are naught else than brothers. Therefore make peace between your brethren and observe your duty to Allah that haply ye may obtain mercy.'),
  ('en.pickthall', 49, 11, 'O ye who believe! Let not a folk deride a folk who may be better than they (are), not let women (deride) women who may be better than they are; neither defame one another, nor insult one another by nicknames. Bad is the name of lewdness after faith. And whoso turneth not in repentance, such are evil-doers.'),
  ('en.pickthall', 49, 12, 'O ye who believe! Shun much suspicion; for lo! some suspicion is a crime. And spy not, neither backbite one another. Would one of you love to eat the flesh of his dead brother? Ye abhor that (so abhor the other)! And keep your duty (to Allah). Lo! Allah is Relenting, Merciful.'),
  ('en.pickthall', 49, 13, 'O mankind! Lo! We have created you male and female, and have made you nations and tribes that ye may know one another. Lo! the noblest of you, in the sight of Allah, is the best in conduct. Lo! Allah is Knower, Aware.'),
  ('en.pickthall', 49, 14, 'The wandering Arabs say: We believe. Say (unto them, O Muhammad): Ye believe not, but rather say "We submit," for the faith hath not yet entered into your hearts. Yet, if ye obey Allah and His messenger, He will not withhold from you aught of (the reward of) your deeds. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 49, 15, 'The (true) believers are those only who believe in Allah and His messenger and afterward doubt not, but strive with their wealth and their lives for the cause of Allah. Such are the sincere.'),
  ('en.pickthall', 49, 16, 'Say (unto them, O Muhammad): Would ye teach Allah your religion, when Allah knoweth all that is in the heavens and all that is in the earth, and Allah is Aware of all things?'),
  ('en.pickthall', 49, 17, 'They make it a favour unto thee (Muhammad) that they have surrendered (unto Him). Say: Deem not your Surrender a favour unto me; but Allah doth confer a favour on you, inasmuch as He hath led you to the Faith, if ye are earnest.'),
  ('en.pickthall', 49, 18, 'Lo! Allah knoweth the Unseen of the heavens and the earth. And Allah is Seer of what ye do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 49, 1, 'O Ye who believe! Put not yourselves forward before Allah and His Messenger; but fear Allah: for Allah is He Who hears and knows all things.'),
  ('en.yusufali', 49, 2, 'O ye who believe! Raise not your voices above the voice of the Prophet, nor speak aloud to him in talk, as ye may speak aloud to one another, lest your deeds become vain and ye perceive not.'),
  ('en.yusufali', 49, 3, 'Those that lower their voices in the presence of Allah\'s Messenger,- their hearts has Allah tested for piety: for them is Forgiveness and a great Reward.'),
  ('en.yusufali', 49, 4, 'Those who shout out to thee from without the inner apartments - most of them lack understanding.'),
  ('en.yusufali', 49, 5, 'If only they had patience until thou couldst come out to them, it would be best for them: but Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 49, 6, 'O ye who believe! If a wicked person comes to you with any news, ascertain the truth, lest ye harm people unwittingly, and afterwards become full of repentance for what ye have done.'),
  ('en.yusufali', 49, 7, 'And know that among you is Allah\'s Messenger: were he, in many matters, to follow your (wishes), ye would certainly fall into misfortune: But Allah has endeared the Faith to you, and has made it beautiful in your hearts, and He has made hateful to you Unbelief, wickedness, and rebellion: such indeed are those who walk in righteousness;-'),
  ('en.yusufali', 49, 8, 'A Grace and Favour from Allah; and Allah is full of Knowledge and Wisdom.'),
  ('en.yusufali', 49, 9, 'If two parties among the Believers fall into a quarrel, make ye peace between them: but if one of them transgresses beyond bounds against the other, then fight ye (all) against the one that transgresses until it complies with the command of Allah; but if it complies, then make peace between them with justice, and be fair: for Allah loves those who are fair (and just).'),
  ('en.yusufali', 49, 10, 'The Believers are but a single Brotherhood: So make peace and reconciliation between your two (contending) brothers; and fear Allah, that ye may receive Mercy.'),
  ('en.yusufali', 49, 11, 'O ye who believe! Let not some men among you laugh at others: It may be that the (latter) are better than the (former): Nor let some women laugh at others: It may be that the (latter are better than the (former): Nor defame nor be sarcastic to each other, nor call each other by (offensive) nicknames: Ill-seeming is a name connoting wickedness, (to be used of one) after he has believed: And those who do not desist are (indeed) doing wrong.'),
  ('en.yusufali', 49, 12, 'O ye who believe! Avoid suspicion as much (as possible): for suspicion in some cases is a sin: And spy not on each other behind their backs. Would any of you like to eat the flesh of his dead brother? Nay, ye would abhor it... But fear Allah: For Allah is Oft-Returning, Most Merciful.'),
  ('en.yusufali', 49, 13, 'O mankind! We created you from a single (pair) of a male and a female, and made you into nations and tribes, that ye may know each other (not that ye may despise (each other). Verily the most honoured of you in the sight of Allah is (he who is) the most righteous of you. And Allah has full knowledge and is well acquainted (with all things).'),
  ('en.yusufali', 49, 14, 'The desert Arabs say, "We believe." Say, "Ye have no faith; but ye (only) say, \'We have submitted our wills to Allah,\' For not yet has Faith entered your hearts. But if ye obey Allah and His Messenger, He will not belittle aught of your deeds: for Allah is Oft-Forgiving, Most Merciful."'),
  ('en.yusufali', 49, 15, 'Only those are Believers who have believed in Allah and His Messenger, and have never since doubted, but have striven with their belongings and their persons in the Cause of Allah: Such are the sincere ones.'),
  ('en.yusufali', 49, 16, 'Say: "What! Will ye instruct Allah about your religion? But Allah knows all that is in the heavens and on earth: He has full knowledge of all things.'),
  ('en.yusufali', 49, 17, 'They impress on thee as a favour that they have embraced Islam. Say, "Count not your Islam as a favour upon me: Nay, Allah has conferred a favour upon you that He has guided you to the faith, if ye be true and sincere.'),
  ('en.yusufali', 49, 18, '"Verily Allah knows the secrets of the heavens and the earth: and Allah Sees well all that ye do."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 49, 1, 'Yaa ayyuhal lazeena aamanoo la tuqaddimoo baina yada yil laahi wa Rasoolihee wattaqul laah; innal laaha samee\'un \'Aleem'),
  ('en.transliteration', 49, 2, 'Yaa ayyuhal lazeena aamanoo laa tarfa\'ooo aswaatakum fawqa sawtin Nabiyi wa laa tajharoo lahoo bilqawli kajahri ba\'dikum liba \'din an tahbata a \'maalukum wa antum laa tash\'uroon'),
  ('en.transliteration', 49, 3, 'Innal lazeena yaghud doona aswaatahum \'inda Rasoolil laahi ulaaa\'ikal lazeenam tah anal laahu quloobahum littaqwaa; lahum maghfiratunw waajrun \'azeem'),
  ('en.transliteration', 49, 4, 'Innal lazeena yunaadoo naka minw waraaa\'il hujuraati aksaruhum laa ya\'qiloon'),
  ('en.transliteration', 49, 5, 'Wa law annahum sabaroo hatta takhruja ilaihim lakaana khairal lahum; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 49, 6, 'Yaaa ayyuhal lazeena aamanoo in jaaa\'akum faasqum binaba in fatabaiyanooo an tuseeboo qawmam bijahalatin fatusbihoo \'alaa maa fa\'altum naadimeen'),
  ('en.transliteration', 49, 7, 'Wa\'lamooo anna feekum Rasoolal laah; law yutee\'ukum fee kaseerim minal amrila\'anittum wa laakinnal laaha habbaba ilaikumul eemaana wa zaiyanahoo fee quloobikum wa karraha ilaikumul kufra walfusooqa wal\'isyaan; ulaaaika humur raashidoon'),
  ('en.transliteration', 49, 8, 'Fadlam minal laahi wa ni\'mah; wallaahu \'Aleemun Hakeem'),
  ('en.transliteration', 49, 9, 'Wa in taaa\'ifataani minal mu\'mineenaq tataloo faaslihoo bainahumaa fa-im baghat ih daahumaa \'alal ukhraa faqaatilul latee tabhee hattaa tafeee\'a ilaaa amril laah; fa-in faaa\'t fa aslihoo bainahumaa bil\'adli wa aqsitoo innal laaha yuhibbul muqsiteen'),
  ('en.transliteration', 49, 10, 'Innamal mu\'minoona ikhwatun fa aslihoo baina akhawaykum wattaqul laaha la\'allakum tuhamoon'),
  ('en.transliteration', 49, 11, 'Yaaa ayyuhal lazeena aamanoo laa yaskhar qawmum min qawmin \'asaaa anyyakoonoo khairam minhum wa laa nisaaa\'um min nisaaa\'in \'Asaaa ay yakunna khairam minhunna wa laa talmizooo bil alqaab; bi\'sal ismul fusooqu ba\'dal eemaan; wa mal-lam yatub fa-ulaaa\'ika humuz zaalimoon'),
  ('en.transliteration', 49, 12, 'Yaaa ayyuhal lazeena aamanuj taniboo kaseeram minaz zanni inna ba\'daz zanniismunw wa laa tajassasoo wa la yaghtab ba\'dukum ba\'daa; a yuhibbu ahadukum any yaakula lahma akheehi maitan fakarih tumooh; wattaqul laa; innal laaha tawwaabur Raheem'),
  ('en.transliteration', 49, 13, 'Yaaa ayyuhan naasu innaa khalaqnaakum min zakarinw wa unsaa wa ja\'alnaakum shu\'oobanw wa qabaaa\'ila lita\'aarafoo inna akramakum \'indal laahi atqaakum innal laaha \'Aleemun khabeer'),
  ('en.transliteration', 49, 14, 'Qaalatil-A \'raabu aamannaa qul lam tu\'minoo wa laakin qoolooo aslamnaa wa lamma yadkhulil eemaanu fee quloobikum wa in tutee\'ul laaha wa Rasoolahoo laa yalitkum min a\'maalikum shai\'aa; innal laaha Ghafoorur Raheem'),
  ('en.transliteration', 49, 15, 'Innamal muu\'minoonal lazeena aamanoo billaahi wa Rasoolihee summa lam yartaaboo wa jaahadoo biamwaalihim wa anfusihim fee sabeelil laah; ulaaaika humus saadiqoon'),
  ('en.transliteration', 49, 16, 'Qul atu\'allimoonal laaha bideenikum wallaahu ya\'lamu maa fis samaawaati wa maa fil ard; wallaahu bikulli shai\'in \'Aleem'),
  ('en.transliteration', 49, 17, 'Yamunnoona \'alaika an aslamoo qul laa tamunnoo \'alaiya Islaamakum balillaahu yamunnu \'alaikum an hadaakum lil eemaani in kuntum saadiqeen'),
  ('en.transliteration', 49, 18, 'Innal laaha ya\'lamu ghaibas samaawaati wal ard; wallaahu baseerum bimaa ta\'maloon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 49, 1, 'اے ایمان والو الله اور اس کے رسول کے سامنے پہل نہ کرو الله سے ڈرتے رہو بے شک الله سب کچھ سننے والا جاننے والا ہے'),
  ('ur.ahmedali', 49, 2, 'اے ایمان والو اپنی آوازیں نبی کی آواز سے بلند نہ کیا کرو اور نہ بلندآواز سے رسول سے بات کیا کرو جیسا کہ تم ایک دوسرے سے کیا کرتے ہو کہیں تمہارے اعمال برباد نہ ہوجائیں اور تمہیں خبر بھی نہ ہو'),
  ('ur.ahmedali', 49, 3, 'بے شک جو لوگ اپنی آوازیں رسول الله کے حضور دھیمی کر لیتے ہیں یہی لوگ ہیں کہ الله نے ان کے دلوں کو پرہیزگاری کے لیے جانچ لیا ہےان کے لیے بخشش اور بڑا اجر ہے'),
  ('ur.ahmedali', 49, 4, 'بے شک جو لوگ آپ کو حجروں کے باہر سے پکارتے ہیں اکثر ان میں سے عقل نہیں رکھتے'),
  ('ur.ahmedali', 49, 5, 'اور اگر وہ صبر کرتے یہاں تک کہ آپ ان کے پاس سے نکل کر آتے تو ان کے لیے بہتر ہوتا اور الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 49, 6, 'اے ایمان والو اگر کوئی فاسق تمہاے پاس کوئی سی خبر لائے تو اس کی تحقیق کیا کرو کہیں کسی قوم پر بے خبری سے نہ جا پڑو پھر اپنے کیے پر پشیمان ہونے لگو'),
  ('ur.ahmedali', 49, 7, 'اور جان لو کہ تم میں الله کا رسول موجود ہے اگر وہ بہت سی باتوں میں تمہارا کہا مانے تو تم پر مشکل پڑ جائے لیکن الله نے تمہارے دلوں میں ایمان کی محبت ڈال دی ہے اوراس کو تمہارے دلوں میں اچھاکردکھایا ہے اور تمہارے دل میں کفر اور گناہ اور نافرمانی کی نفرت ڈال دی ہے یہی لوگ ہدایت یافتہ ہیں'),
  ('ur.ahmedali', 49, 8, 'الله کے فضل اور احسان سے اور الله جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 49, 9, 'اور اگر مسلمانوں کے دو گروہ آپس میں لڑ پڑیں تو ان کے درمیان صلح کرا دو پس اگر ایک ان میں دوسرے پر ظلم کرے تو اس سے لڑو جو زیادتی کرتا ہے یہاں تک کہ وہ الله کے حکم کی طرف رجوع کرے پھر اگر وہ رجوع کرے تو ان دونوں میں انصاف سے صلح کرادو اورانصاف کرو بے شک الله انصاف کرنے والوں کو دوست رکھتا ہے'),
  ('ur.ahmedali', 49, 10, 'بے شک مسلمان آپس میں بھائی بھائی ہیں سواپنے بھائیوں میں صلح کرادو اور الله سے ڈرو تاکہ تم پر رحم کیا جائے'),
  ('ur.ahmedali', 49, 11, 'اے ایمان والو ایک قوم دوسری قوم سے ٹھٹھا نہ کرے عجب نہیں کہ وہ ان سے بہتر ہوں اور نہ عورتیں دوسری عورتوں سے ٹھٹھا کریں کچھ بعید نہیں کہ وہ ان سے بہتر ہوں اور ایک دوسرے کو طعنے نہ دو اور نہ ایک دوسرے کے نام دھرو فسق کے نام لینے ایمان لانے کے بعد بہت برے ہیں اور جو باز نہ آئیں سووہی ظالم ہیں'),
  ('ur.ahmedali', 49, 12, 'اے ایمان والو بہت سی بدگمانیوں سے بچتے رہو کیوں کہ بعض گمان تو گناہ ہیں اور ٹٹول بھی نہ کیا کرو اور نہ کوئی کسی سے غیبت کیا کرے کیا تم میں سے کوئی پسند کرتا ہے کہ اپنے مردہ بھائی کا گوشت کھائے سواس کو توتم ناپسند کرتے ہو اور الله سے ڈرو بے شک الله بڑا توبہ قبول کرنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 49, 13, 'ا ے لوگو ہم نے تمہیں ایک ہی مرد اور عورت سے پیدا کیا ہے اور تمہارے خاندان اور قومیں جو بنائی ہیں تاکہ تمہیں آپس میں پہچان ہو بے شک زیادہ عزت والا تم میں سے الله کے نزدیک وہ ہے جو تم میں سے زیادہ پرہیزگار ہے بے شک الله سب کچھ جاننے والا خبردار ہے'),
  ('ur.ahmedali', 49, 14, 'بدویوں نے کہا ہم ایمان لے آئے ہیں کہہ دو تم ایمان نہیں لائے لیکن تم کہو کہ ہم مسلمان ہو گئے ہیں اورابھی تک ایمان تمہارے دلوں میں داخل نہیں ہوا اور اگر تم الله اور اس کے رسول کا حکم مانو تو تمہارے اعمال میں سے کچھ بھی کم نہیں کرے گا بے شک الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 49, 15, 'بے شک سچے مسلمان تو وہی ہیں جو الله اور اس کے رسول پر ایمان لائے پھر انہوں نے شک نہ کیا اور اپنے مالوں اور اپنی جانوں سے الله کی راہ میں جہاد کیا وہی سچے (مسلمان) ہیں'),
  ('ur.ahmedali', 49, 16, 'کہہ دوکیا تم الله کو اپنی دین داری جتاتے ہو اور الله جانتا ہے جو کچھ آسمانوں میں اور زمین میں ہے اور الله ہر چیز کو جاننے والا ہے'),
  ('ur.ahmedali', 49, 17, 'آپ پر اپنے اسلام لانے کا احسان جتاتے ہیں کہہ دو مجھ پراپنے اسلام لانے کا احسان نہ جتلاؤ بلکہ الله تم پر احسان رکھتا ہے کہ اس نے ایمان کی طرف تمہاری رہنمائی کی اگر تم سچے ہو'),
  ('ur.ahmedali', 49, 18, 'بے شک الله آسمانوں اور زمین کی سب مخفی چیزیں جانتا ہےاوردیکھ رہاہےجوتم کررہےہو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 49, 1, 'Ey inananlar! Allah\'tan ve Peygamberinden öne geçmeyin; Allah\'tan sakının, doğrusu Allah işitir ve bilir.'),
  ('tr.diyanet', 49, 2, 'Ey inananlar! Seslerinizi, Peygamberin sesini bastıracak şekilde yükseltmeyin. Farkına varmadan, işlediklerinizin boşa gitmemesi için, Peygambere birbirinize bağırdığınız gibi yüksek sesle bağırmayın.'),
  ('tr.diyanet', 49, 3, 'Seslerini Peygamberin yanında kısan kimseler, Allah\'ın gönüllerini takva ile sınadığı kimselerdir. Onlara mağfiret ve büyük ecir vardır.'),
  ('tr.diyanet', 49, 4, 'Sana odaların ötesinden seslenenlerin çoğu akletmeyen kimselerdir.'),
  ('tr.diyanet', 49, 5, 'Eğer onlar, sen yanlarına çıkıncaya kadar sabretselerdi şüphesiz onlar için daha iyi olurdu. Allah bağışlayandır, merhamet edendir.'),
  ('tr.diyanet', 49, 6, 'Ey inananlar! Eğer yoldan çıkmışın biri size bir haber getirirse, onun iç yüzünü araştırın, yoksa bilmeden bir millete fenalık edersiniz de sonra ettiğinize pişman olursunuz.'),
  ('tr.diyanet', 49, 7, 'Bilin ki, içinizde Allah\'ın Peygamberi bulunmaktadır. Eğer o, bir çok işlerde size uymuş olsaydı şüphesiz kötü duruma düşerdiniz; ama Allah size imanı sevdirmiş, onu gönüllerinize güzel göstermiş; inkarcılığı, yoldan çıkmayı ve baş kaldırmayı size iğrenç göstermiştir. İşte böyle olanlar, Allah katından bir lütuf ve nimet sayesinde doğru yolda bulunanlardır. Allah bilendir, Hakim\'dir.'),
  ('tr.diyanet', 49, 8, 'Bilin ki, içinizde Allah\'ın Peygamberi bulunmaktadır. Eğer o, bir çok işlerde size uymuş olsaydı şüphesiz kötü duruma düşerdiniz; ama Allah size imanı sevdirmiş, onu gönüllerinize güzel göstermiş; inkarcılığı, yoldan çıkmayı ve baş kaldırmayı size iğrenç göstermiştir. İşte böyle olanlar, Allah katından bir lütuf ve nimet sayesinde doğru yolda bulunanlardır. Allah bilendir, Hakim\'dir.'),
  ('tr.diyanet', 49, 9, 'Eğer müminlerden iki topluluk birbirleriyle savaşırlarsa aralarını düzeltiniz; eğer biri diğeri üzerine saldırırsa, saldıranlarla Allah\'ın buyruğuna dönmelerine kadar savaşınız; eğer dönerlerse aralarını adaletle bulunuz, adil davranınız, şüphesiz Allah adil davrananları sever.'),
  ('tr.diyanet', 49, 10, 'Şüphesiz müminler birbiri ile kardeştirler; öyle ise dargın olan kardeşlerinizin arasını düzeltin; Allah\'tan sakının ki size acısın.'),
  ('tr.diyanet', 49, 11, 'Ey inananlar! Bir topluluk bir diğerini alaya almasın, belki de onlar kendilerinden daha iyidirler. Kadınlar da başka kadınları alaya almasınlar, belki onlar kendilerinden daha iyidirler. Kendi kendinizi ayıplamayın; birbirinizi kötü lakaplarla çağırmayın; inandıktan sonra yoldan çıkmış olmak ne kötü bir addır. Tevbe etmeyenler, işte onlar zalimlerdir.'),
  ('tr.diyanet', 49, 12, 'Ey inananlar! Zannın çoğundan sakının, zira zannın bir kısmı günahtır. Birbirinizin suçunu araştırmayın; kimse kimseyi çekiştirmesin; hangi biriniz ölü kardeşinin etini yemekten hoşlanır? Ondan tiksinirsiniz; Allah\'tan sakının, şüphesiz Allah tevbeleri daima kabul edendir, acıyandır.'),
  ('tr.diyanet', 49, 13, 'Ey insanlar! Doğrusu Biz sizleri bir erkekle bir dişiden yarattık. Sizi milletler ve kabileler haline koyduk ki birbirinizi kolayca tanıyasınız. Şüphesiz, Allah katında en değerliniz, O\'na karşı gelmekten en çok sakınanızdır. Allah bilendir, haberdardır.'),
  ('tr.diyanet', 49, 14, 'Bedeviler: "İnandık" dediler, de ki: "İnanmadınız ama İslam olduk deyin; inanç henüz gönüllerinize yerleşmedi; eğer Allah\'a ve Peygamberine itaat ederseniz, işlediklerinizden bir şey eksilmez; doğrusu Allah, bağışlar, merhamet eder."'),
  ('tr.diyanet', 49, 15, '"İnananlar, ancak Allah\'a ve peygamberine inanmış, sonra şüpheye düşmemiş; Allah uğrunda mallarıyla, canlarıyla cihat etmiş olanlardır. İşte onlar doğru olanlardır."'),
  ('tr.diyanet', 49, 16, 'De ki: "Dininizi Allah\'a mı öğretiyorsunuz? Oysa Allah göklerde olanları da yerde olanları da bilir, Allah her şeyi bilendir."'),
  ('tr.diyanet', 49, 17, 'Müslüman oldular diye seni minnet altında bırakmak isterler; de ki: "Müslüman olmanızla beni minnet altında tutmayın, hayır; eğer doğru kimselerseniz, sizi imana eriştirmekle Allah sizi minnet altında bırakır."'),
  ('tr.diyanet', 49, 18, 'Doğrusu Allah, göklerin ve yerin gaybını bilir. Allah, yaptıklarınızı görendir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 49, 1, 'Hai orang-orang yang beriman, janganlah kamu mendahului Allah dan Rasulnya dan bertakwalah kepada Allah. Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.'),
  ('id.indonesian', 49, 2, 'Hai orang-orang yang beriman, janganlah kamu meninggikan suaramu melebihi suara Nabi, dan janganlah kamu berkata kepadanya dengan suara yang keras, sebagaimana kerasnya suara sebagian kamu terhadap sebagian yang lain, supaya tidak hapus (pahala) amalanmu, sedangkan kamu tidak menyadari.'),
  ('id.indonesian', 49, 3, 'Sesungguhnya orang yang merendahkan suaranya di sisi Rasulullah mereka itulah orang-orang yang telah diuji hati mereka oleh Allah untuk bertakwa. Bagi mereka ampunan dan pahala yang besar.'),
  ('id.indonesian', 49, 4, 'Sesungguhnya orang-orang yang memanggil kamu dari luar kamar(mu) kebanyakan mereka tidak mengerti.'),
  ('id.indonesian', 49, 5, 'Dan kalau sekiranya mereka bersabar sampai kamu keluar menemui mereka sesungguhnya itu lebih baik bagi mereka, dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 49, 6, 'Hai orang-orang yang beriman, jika datang kepadamu orang fasik membawa suatu berita, maka periksalah dengan teliti agar kamu tidak menimpakan suatu musibah kepada suatu kaum tanpa mengetahui keadaannya yang menyebabkan kamu menyesal atas perbuatanmu itu.'),
  ('id.indonesian', 49, 7, 'Dan ketahuilah olehmu bahwa di kalanganmu ada Rasulullah. Kalau ia menuruti kemauanmu dalam beberapa urusan benar-benarlah kamu mendapat kesusahan, tetapi Allah menjadikan kamu "cinta" kepada keimanan dan menjadikan keimanan itu indah di dalam hatimu serta menjadikan kamu benci kepada kekafiran, kefasikan, dan kedurhakaan. Mereka itulah orang-orang yang mengikuti jalan yang lurus,'),
  ('id.indonesian', 49, 8, 'sebagai karunia dan nikmat dari Allah. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 49, 9, 'Dan kalau ada dua golongan dari mereka yang beriman itu berperang hendaklah kamu damaikan antara keduanya! Tapi kalau yang satu melanggar perjanjian terhadap yang lain, hendaklah yang melanggar perjanjian itu kamu perangi sampai surut kembali pada perintah Allah. Kalau dia telah surut, damaikanlah antara keduanya menurut keadilan, dan hendaklah kamu berlaku adil; sesungguhnya Allah mencintai orang-orang yang berlaku adil.'),
  ('id.indonesian', 49, 10, 'Orang-orang beriman itu sesungguhnya bersaudara. Sebab itu damaikanlah (perbaikilah hubungan) antara kedua saudaramu itu dan takutlah terhadap Allah, supaya kamu mendapat rahmat.'),
  ('id.indonesian', 49, 11, 'Hai orang-orang yang beriman, janganlah sekumpulan orang laki-laki merendahkan kumpulan yang lain, boleh jadi yang ditertawakan itu lebih baik dari mereka. Dan jangan pula sekumpulan perempuan merendahkan kumpulan lainnya, boleh jadi yang direndahkan itu lebih baik. Dan janganlah suka mencela dirimu sendiri dan jangan memanggil dengan gelaran yang mengandung ejekan. Seburuk-buruk panggilan adalah (panggilan) yang buruk sesudah iman dan barangsiapa yang tidak bertobat, maka mereka itulah orang-orang yang zalim.'),
  ('id.indonesian', 49, 12, 'Hai orang-orang yang beriman, jauhilah kebanyakan purba-sangka (kecurigaan), karena sebagian dari purba-sangka itu dosa. Dan janganlah mencari-cari keburukan orang dan janganlah menggunjingkan satu sama lain. Adakah seorang diantara kamu yang suka memakan daging saudaranya yang sudah mati? Maka tentulah kamu merasa jijik kepadanya. Dan bertakwalah kepada Allah. Sesungguhnya Allah Maha Penerima Taubat lagi Maha Penyayang.'),
  ('id.indonesian', 49, 13, 'Hai manusia, sesungguhnya Kami menciptakan kamu dari seorang laki-laki dan seorang perempuan dan menjadikan kamu berbangsa-bangsa dan bersuku-suku supaya kamu saling kenal-mengenal. Sesungguhnya orang yang paling mulia diantara kamu disisi Allah ialah orang yang paling takwa diantara kamu. Sesungguhnya Allah Maha Mengetahui lagi Maha Mengenal.'),
  ('id.indonesian', 49, 14, 'Orang-orang Arab Badui itu berkata: "Kami telah beriman". Katakanlah: "Kamu belum beriman, tapi katakanlah \'kami telah tunduk\', karena iman itu belum masuk ke dalam hatimu; dan jika kamu taat kepada Allah dan Rasul-Nya, Dia tidak akan mengurangi sedikitpun pahala amalanmu; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang".'),
  ('id.indonesian', 49, 15, 'Sesungguhnya orang-orang yang beriman itu hanyalah orang-orang yang percaya (beriman) kepada Allah dan Rasul-Nya, kemudian mereka tidak ragu-ragu dan mereka berjuang (berjihad) dengan harta dan jiwa mereka pada jalan Allah. Mereka itulah orang-orang yang benar.'),
  ('id.indonesian', 49, 16, 'Katakanlah: "Apakah kamu akan memberitahukan kepada Allah tentang agamamu, padahal Allah mengetahui apa yang di langit dan apa yang di bumi dan Allah Maha Mengetahui segala sesuatu?"'),
  ('id.indonesian', 49, 17, 'Mereka merasa telah memberi nikmat kepadamu dengan keislaman mereka. Katakanlah: "Janganlah kamu merasa telah memberi nikmat kepadaku dengan keislamanmu, sebenarnya Allah, Dialah yang melimpahkan nikmat kepadamu dengan menunjuki kamu kepada keimanan jika kamu adalah orang-orang yang benar".'),
  ('id.indonesian', 49, 18, 'Sesungguhnya Allah mengetahui apa yang ghaib di langit dan bumi. Dan Allah Maha Melihat apa yang kamu kerjakan.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 50, 1, 'Qaf. By the honored Qur\'an...'),
  ('en.sahih', 50, 2, 'But they wonder that there has come to them a warner from among themselves, and the disbelievers say, "This is an amazing thing.'),
  ('en.sahih', 50, 3, 'When we have died and have become dust, [we will return to life]? That is a distant return."'),
  ('en.sahih', 50, 4, 'We know what the earth diminishes of them, and with Us is a retaining record.'),
  ('en.sahih', 50, 5, 'But they denied the truth when it came to them, so they are in a confused condition.'),
  ('en.sahih', 50, 6, 'Have they not looked at the heaven above them - how We structured it and adorned it and [how] it has no rifts?'),
  ('en.sahih', 50, 7, 'And the earth - We spread it out and cast therein firmly set mountains and made grow therein [something] of every beautiful kind,'),
  ('en.sahih', 50, 8, 'Giving insight and a reminder for every servant who turns [to Allah].'),
  ('en.sahih', 50, 9, 'And We have sent down blessed rain from the sky and made grow thereby gardens and grain from the harvest'),
  ('en.sahih', 50, 10, 'And lofty palm trees having fruit arranged in layers -'),
  ('en.sahih', 50, 11, 'As provision for the servants, and We have given life thereby to a dead land. Thus is the resurrection.'),
  ('en.sahih', 50, 12, 'The people of Noah denied before them, and the companions of the well and Thamud'),
  ('en.sahih', 50, 13, 'And \'Aad and Pharaoh and the brothers of Lot'),
  ('en.sahih', 50, 14, 'And the companions of the thicket and the people of Tubba\'. All denied the messengers, so My threat was justly fulfilled.'),
  ('en.sahih', 50, 15, 'Did We fail in the first creation? But they are in confusion over a new creation.'),
  ('en.sahih', 50, 16, 'And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein'),
  ('en.sahih', 50, 17, 'When the two receivers receive, seated on the right and on the left.'),
  ('en.sahih', 50, 18, 'Man does not utter any word except that with him is an observer prepared [to record].'),
  ('en.sahih', 50, 19, 'And the intoxication of death will bring the truth; that is what you were trying to avoid.'),
  ('en.sahih', 50, 20, 'And the Horn will be blown. That is the Day of [carrying out] the threat.'),
  ('en.sahih', 50, 21, 'And every soul will come, with it a driver and a witness.'),
  ('en.sahih', 50, 22, '[It will be said], "You were certainly in unmindfulness of this, and We have removed from you your cover, so your sight, this Day, is sharp."'),
  ('en.sahih', 50, 23, 'And his companion, [the angel], will say, "This [record] is what is with me, prepared."'),
  ('en.sahih', 50, 24, '[Allah will say], "Throw into Hell every obstinate disbeliever,'),
  ('en.sahih', 50, 25, 'Preventer of good, aggressor, and doubter,'),
  ('en.sahih', 50, 26, 'Who made [as equal] with Allah another deity; then throw him into the severe punishment."'),
  ('en.sahih', 50, 27, 'His [devil] companion will say, "Our Lord, I did not make him transgress, but he [himself] was in extreme error."'),
  ('en.sahih', 50, 28, '[Allah] will say, "Do not dispute before Me, while I had already presented to you the warning.'),
  ('en.sahih', 50, 29, 'The word will not be changed with Me, and never will I be unjust to the servants."'),
  ('en.sahih', 50, 30, 'On the Day We will say to Hell, "Have you been filled?" and it will say, "Are there some more,"'),
  ('en.sahih', 50, 31, 'And Paradise will be brought near to the righteous, not far,'),
  ('en.sahih', 50, 32, '[It will be said], "This is what you were promised - for every returner [to Allah] and keeper [of His covenant]'),
  ('en.sahih', 50, 33, 'Who feared the Most Merciful unseen and came with a heart returning [in repentance].'),
  ('en.sahih', 50, 34, 'Enter it in peace. This is the Day of Eternity."'),
  ('en.sahih', 50, 35, 'They will have whatever they wish therein, and with Us is more.'),
  ('en.sahih', 50, 36, 'And how many a generation before them did We destroy who were greater than them in [striking] power and had explored throughout the lands. Is there any place of escape?'),
  ('en.sahih', 50, 37, 'Indeed in that is a reminder for whoever has a heart or who listens while he is present [in mind].'),
  ('en.sahih', 50, 38, 'And We did certainly create the heavens and earth and what is between them in six days, and there touched Us no weariness.'),
  ('en.sahih', 50, 39, 'So be patient, [O Muhammad], over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting,'),
  ('en.sahih', 50, 40, 'And [in part] of the night exalt Him and after prostration.'),
  ('en.sahih', 50, 41, 'And listen on the Day when the Caller will call out from a place that is near -'),
  ('en.sahih', 50, 42, 'The Day they will hear the blast [of the Horn] in truth. That is the Day of Emergence [from the graves].'),
  ('en.sahih', 50, 43, 'Indeed, it is We who give life and cause death, and to Us is the destination'),
  ('en.sahih', 50, 44, 'On the Day the earth breaks away from them [and they emerge] rapidly; that is a gathering easy for Us.'),
  ('en.sahih', 50, 45, 'We are most knowing of what they say, and you are not over them a tyrant. But remind by the Qur\'an whoever fears My threat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 50, 1, 'ক্বাফ! সম্মানিত কোরআনের শপথ;'),
  ('bn.bengali', 50, 2, 'বরং তারা তাদের মধ্য থেকেই একজন ভয় প্রদর্শনকারী আগমন করেছে দেখে বিস্ময় বোধ করে। অতঃপর কাফেররা বলেঃ এটা আশ্চর্যের ব্যাপার।'),
  ('bn.bengali', 50, 3, 'আমরা মরে গেলে এবং মৃত্তিকায় পরিণত হয়ে গেলেও কি পুনরুত্থিত হব? এ প্রত্যাবর্তন সুদূরপরাহত।'),
  ('bn.bengali', 50, 4, 'মৃত্তিকা তাদের কতটুকু গ্রাস করবে, তা আমার জানা আছে এবং আমার কাছে আছে সংরক্ষিত কিতাব।'),
  ('bn.bengali', 50, 5, 'বরং তাদের কাছে সত্য আগমন করার পর তারা তাকে মিথ্যা বলছে। ফলে তারা সংশয়ে পতিত রয়েছে।'),
  ('bn.bengali', 50, 6, 'তারা কি তাদের উপরস্থিত আকাশের পানে দৃষ্টিপাত করে না আমি কিভাবে তা নির্মাণ করেছি এবং সুশোভিত করেছি? তাতে কোন ছিদ্রও নেই।'),
  ('bn.bengali', 50, 7, 'আমি ভূমিকে বিস্তৃত করেছি, তাতে পর্বতমালার ভার স্থাপন করেছি এবং তাতে সর্বপ্রকার নয়নাভিরাম উদ্ভিদ উদগত করেছি।'),
  ('bn.bengali', 50, 8, 'এটা জ্ঞান আহরণ ও স্মরণ করার মত ব্যাপার প্রত্যেক অনুরাগী বান্দার জন্যে।'),
  ('bn.bengali', 50, 9, 'আমি আকাশ থেকে কল্যাণময় বৃষ্টি বর্ষণ করি এবং তদ্বারা বাগান ও শস্য উদগত করি, যেগুলোর ফসল আহরণ করা হয়।'),
  ('bn.bengali', 50, 10, 'এবং লম্বমান খর্জুর বৃক্ষ, যাতে আছে গুচ্ছ গুচ্ছ খর্জুর,'),
  ('bn.bengali', 50, 11, 'বান্দাদের জীবিকাস্বরূপ এবং বৃষ্টি দ্বারা আমি মৃত জনপদকে সঞ্জীবিত করি। এমনিভাবে পুনরুত্থান ঘটবে।'),
  ('bn.bengali', 50, 12, 'তাদের পূর্বে মিথ্যাবাদী বলেছে নূহের সম্প্রদায়, কুপবাসীরা এবং সামুদ সম্প্রদায়।'),
  ('bn.bengali', 50, 13, 'আদ, ফেরাউন, ও লূতের সম্প্রদায়,'),
  ('bn.bengali', 50, 14, 'বনবাসীরা এবং তোব্বা সম্প্রদায়। প্রত্যেকেই রসূলগণকে মিথ্যা বলেছে, অতঃপর আমার শাস্তির যোগ্য হয়েছে।'),
  ('bn.bengali', 50, 15, 'আমি কি প্রথমবার সৃষ্টি করেই ক্লান্ত হয়ে পড়েছি? বরং তারা নতুন সৃষ্টির ব্যাপারে সন্দেহ পোষন করেছে।'),
  ('bn.bengali', 50, 16, 'আমি মানুষ সৃষ্টি করেছি এবং তার মন নিভৃতে যে কুচিন্তা করে, সে সম্বন্ধেও আমি অবগত আছি। আমি তার গ্রীবাস্থিত ধমনী থেকেও অধিক নিকটবর্তী।'),
  ('bn.bengali', 50, 17, 'যখন দুই ফেরেশতা ডানে ও বামে বসে তার আমল গ্রহণ করে।'),
  ('bn.bengali', 50, 18, 'সে যে কথাই উচ্চারণ করে, তাই গ্রহণ করার জন্যে তার কাছে সদা প্রস্তুত প্রহরী রয়েছে।'),
  ('bn.bengali', 50, 19, 'মৃত্যুযন্ত্রণা নিশ্চিতই আসবে। এ থেকেই তুমি টালবাহানা করতে।'),
  ('bn.bengali', 50, 20, 'এবং শিঙ্গায় ফুঁৎকার দেয়া হবে এটা হবে ভয় প্রদর্শনের দিন।'),
  ('bn.bengali', 50, 21, 'প্রত্যেক ব্যক্তি আগমন করবে। তার সাথে থাকবে চালক ও কর্মের সাক্ষী।'),
  ('bn.bengali', 50, 22, 'তুমি তো এই দিন সম্পর্কে উদাসীন ছিলে। এখন তোমার কাছ থেকে যবনিকা সরিয়ে দিয়েছি। ফলে আজ তোমার দৃষ্টি সুতীক্ষ্ন।'),
  ('bn.bengali', 50, 23, 'তার সঙ্গী ফেরেশতা বলবেঃ আমার কাছে যে, আমলনামা ছিল, তা এই।'),
  ('bn.bengali', 50, 24, 'তোমরা উভয়েই নিক্ষেপ কর জাহান্নামে প্রত্যেক অকৃতজ্ঞ বিরুদ্ধবাদীকে,'),
  ('bn.bengali', 50, 25, 'যে বাধা দিত মঙ্গলজনক কাজে, সীমালঙ্ঘনকারী, সন্দেহ পোষণকারীকে।'),
  ('bn.bengali', 50, 26, 'যে ব্যক্তি আল্লাহর সাথে অন্য উপাস্য গ্রহণ করত, তাকে তোমরা কঠিন শাস্তিতে নিক্ষেপ কর।'),
  ('bn.bengali', 50, 27, 'তার সঙ্গী শয়তান বলবেঃ হে আমাদের পালনকর্তা, আমি তাকে অবাধ্যতায় লিপ্ত করিনি। বস্তুতঃ সে নিজেই ছিল সুদূর পথভ্রান্তিতে লিপ্ত।'),
  ('bn.bengali', 50, 28, 'আল্লাহ বলবেনঃ আমার সামনে বাকবিতন্ডা করো না আমি তো পূর্বেই তোমাদেরকে আযাব দ্বারা ভয় প্রদর্শন করেছিলাম।'),
  ('bn.bengali', 50, 29, 'আমার কাছে কথা রদবদল হয় না এবং আমি বান্দাদের প্রতি জুলুমকারী নই।'),
  ('bn.bengali', 50, 30, 'যেদিন আমি জাহান্নামকে জিজ্ঞাসা করব; তুমি কি পূর্ণ হয়ে গেছ? সে বলবেঃ আরও আছে কি?'),
  ('bn.bengali', 50, 31, 'জান্নাতকে উপস্থিত করা হবে খোদাভীরুদের অদূরে।'),
  ('bn.bengali', 50, 32, 'তোমাদের প্রত্যেক অনুরাগী ও স্মরণকারীকে এরই প্রতিশ্রুতি দেয়া হয়েছিল।'),
  ('bn.bengali', 50, 33, 'যে না দেখে দয়াময় আল্লাহ তা’আলাকে ভয় করত এবং বিনীত অন্তরে উপস্থিত হত।'),
  ('bn.bengali', 50, 34, 'তোমরা এতে শান্তিতে প্রবেশ কর। এটাই অনন্তকাল বসবাসের জন্য প্রবেশ করার দিন।'),
  ('bn.bengali', 50, 35, 'তারা তথায় যা চাইবে, তাই পাবে এবং আমার কাছে রয়েছে আরও অধিক।'),
  ('bn.bengali', 50, 36, 'আমি তাদের পূর্বে বহু সম্প্রদায়কে ধ্বংস করেছি, তারা এদের অপেক্ষা অধিক শক্তিশালী ছিল এবং দেশে-বিদেশে বিচরণ করে ফিরত। তাদের কোন পলায়ন স্থান ছিল না।'),
  ('bn.bengali', 50, 37, 'এতে উপদেশ রয়েছে তার জন্যে, যার অনুধাবন করার মত অন্তর রয়েছে। অথবা সে নিবিষ্ট মনে শ্রবণ করে।'),
  ('bn.bengali', 50, 38, 'আমি নভোমন্ডল, ভূমন্ডল ও এতদুভয়ের মধ্যবর্তী সবকিছু ছয়দিনে সৃষ্টি করেছি এবং আমাকে কোনরূপ ক্লান্তি স্পর্শ করেনি।'),
  ('bn.bengali', 50, 39, 'অতএব, তারা যা কিছু বলে, তজ্জন্যে আপনি ছবর করুন এবং, সূর্যোদয় ও সূর্যাস্তের পূর্বে আপনার পালনকর্তার সপ্রশংস পবিত্রতা ঘোষণা করুন।'),
  ('bn.bengali', 50, 40, 'রাত্রির কিছু অংশে তাঁর পবিত্রতা ঘোষণা করুন এবং নামাযের পশ্চাতেও।'),
  ('bn.bengali', 50, 41, 'শুন, যে দিন এক আহবানকারী নিকটবর্তী স্থান থেকে আহবান করবে।'),
  ('bn.bengali', 50, 42, 'যেদিন মানুষ নিশ্চিত সেই ভয়াবহ আওয়াজ শুনতে পাবে, সেদিনই পুনরত্থান দিবস।'),
  ('bn.bengali', 50, 43, 'আমি জীবন দান করি, মৃত্যু ঘটাই এবং আমারই দিকে সকলের প্রত্যাবর্তন।'),
  ('bn.bengali', 50, 44, 'যেদিন ভূমন্ডল বিদীর্ণ হয়ে মানুষ ছুটাছুটি করে বের হয়ে আসবে। এটা এমন সমবেত করা, যা আমার জন্যে অতি সহজ।'),
  ('bn.bengali', 50, 45, 'তারা যা বলে, তা আমি সম্যক অবগত আছি। আপনি তাদের উপর জোরজবরকারী নন। অতএব, যে আমার শাস্তিকে ভয় করে, তাকে কোরআনের মাধ্যমে উপদেশ দান করুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 50, 1, 'Qaf. By the Glorious Qur\'an,'),
  ('en.pickthall', 50, 2, 'Nay, but they marvel that a warner of their own hath come unto them; and the disbelievers say: This is a strange thing:'),
  ('en.pickthall', 50, 3, 'When we are dead and have become dust (shall we be brought back again)? That would be a far return!'),
  ('en.pickthall', 50, 4, 'We know that which the earth taketh of them, and with Us is a recording Book.'),
  ('en.pickthall', 50, 5, 'Nay, but they have denied the truth when it came unto them, therefor they are now in troubled case.'),
  ('en.pickthall', 50, 6, 'Have they not then observed the sky above them, how We have constructed it and beautified it, and how there are no rifts therein?'),
  ('en.pickthall', 50, 7, 'And the earth have We spread out, and have flung firm hills therein, and have caused of every lovely kind to grow thereon,'),
  ('en.pickthall', 50, 8, 'A vision and a reminder for every penitent slave.'),
  ('en.pickthall', 50, 9, 'And We send down from the sky blessed water whereby We give growth unto gardens and the grain of crops,'),
  ('en.pickthall', 50, 10, 'And lofty date-palms with ranged clusters,'),
  ('en.pickthall', 50, 11, 'Provision (made) for men; and therewith We quicken a dead land. Even so will be the resurrection of the dead.'),
  ('en.pickthall', 50, 12, 'The folk of Noah denied (the truth) before them, and (so did) the dwellers at Ar-Rass and (the tribe of) Thamud,'),
  ('en.pickthall', 50, 13, 'And (the tribe of) A\'ad, and Pharaoh, and the brethren of Lot,'),
  ('en.pickthall', 50, 14, 'And the dwellers in the wood, and the folk of Tubb\'a: every one denied their messengers, therefor My threat took effect.'),
  ('en.pickthall', 50, 15, 'Were We then worn out by the first creation? Yet they are in doubt about a new creation.'),
  ('en.pickthall', 50, 16, 'We verily created man and We know what his soul whispereth to him, and We are nearer to him than his jugular vein.'),
  ('en.pickthall', 50, 17, 'When the two Receivers receive (him), seated on the right hand and on the left,'),
  ('en.pickthall', 50, 18, 'He uttereth no word but there is with him an observer ready.'),
  ('en.pickthall', 50, 19, 'And the agony of death cometh in truth. (And it is said unto him): This is that which thou wast wont to shun.'),
  ('en.pickthall', 50, 20, 'And the trumpet is blown. This is the threatened Day.'),
  ('en.pickthall', 50, 21, 'And every soul cometh, along with it a driver and a witness.'),
  ('en.pickthall', 50, 22, '(And unto the evil-doer it is said): Thou wast in heedlessness of this. Now We have removed from thee thy covering, and piercing is thy sight this day.'),
  ('en.pickthall', 50, 23, 'And (unto the evil-doer) his comrade saith: This is that which I have ready (as testimony).'),
  ('en.pickthall', 50, 24, '(And it is said): Do ye twain hurl to hell each rebel ingrate,'),
  ('en.pickthall', 50, 25, 'Hinderer of good, transgressor, doubter,'),
  ('en.pickthall', 50, 26, 'Who setteth up another god along with Allah. Do ye twain hurl him to the dreadful doom.'),
  ('en.pickthall', 50, 27, 'His comrade saith: Our Lord! I did not cause him to rebel, but he was (himself) far gone in error.'),
  ('en.pickthall', 50, 28, 'He saith: Contend not in My presence, when I had already proffered unto you the warning.'),
  ('en.pickthall', 50, 29, 'The sentence that cometh from Me cannot be changed, and I am in no wise a tyrant unto the slaves.'),
  ('en.pickthall', 50, 30, 'On the day when We say unto hell: Art thou filled? and it saith: Can there be more to come?'),
  ('en.pickthall', 50, 31, 'And the Garden is brought nigh for those who kept from evil, no longer distant.'),
  ('en.pickthall', 50, 32, '(And it is said): This is that which ye were promised. (It is) for every penitent and heedful one,'),
  ('en.pickthall', 50, 33, 'Who feareth the Beneficent in secret and cometh with a contrite heart.'),
  ('en.pickthall', 50, 34, 'Enter it in peace. This is the day of immortality.'),
  ('en.pickthall', 50, 35, 'There they have all that they desire, and there is more with Us.'),
  ('en.pickthall', 50, 36, 'And how many a generation We destroyed before them, who were mightier than these in prowess so that they overran the lands! Had they any place of refuge (when the judgment came)?'),
  ('en.pickthall', 50, 37, 'Lo! therein verily is a reminder for him who hath a heart, or giveth ear with full intelligence.'),
  ('en.pickthall', 50, 38, 'And verily We created the heavens and the earth, and all that is between them, in six Days, and naught of weariness touched Us.'),
  ('en.pickthall', 50, 39, 'Therefor (O Muhammad) bear with what they say, and hymn the praise of thy Lord before the rising and before the setting of the sun;'),
  ('en.pickthall', 50, 40, 'And in the night-time hymn His praise, and after the (prescribed) prostrations.'),
  ('en.pickthall', 50, 41, 'And listen on the day when the crier crieth from a near place,'),
  ('en.pickthall', 50, 42, 'The day when they will hear the (Awful) Cry in truth. That is the day of coming forth (from the graves).'),
  ('en.pickthall', 50, 43, 'Lo! We it is Who quicken and give death, and unto Us is the journeying.'),
  ('en.pickthall', 50, 44, 'On the day when the earth splitteth asunder from them, hastening forth (they come). That is a gathering easy for Us (to make).'),
  ('en.pickthall', 50, 45, 'We are Best Aware of what they say, and thou (O Muhammad) art in no wise a compeller over them. But warn by the Qur\'an him who feareth My threat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 50, 1, 'Qaf: By the Glorious Qur\'an (Thou art Allah\'s Messenger).'),
  ('en.yusufali', 50, 2, 'But they wonder that there has come to them a Warner from among themselves. So the Unbelievers say: "This is a wonderful thing!'),
  ('en.yusufali', 50, 3, '"What! When we die and become dust, (shall we live again?) That is a (sort of) return far (from our understanding)."'),
  ('en.yusufali', 50, 4, 'We already know how much of them the earth takes away: With Us is a record guarding (the full account).'),
  ('en.yusufali', 50, 5, 'But they deny the Truth when it comes to them: so they are in a confused state.'),
  ('en.yusufali', 50, 6, 'Do they not look at the sky above them?- How We have made it and adorned it, and there are no flaws in it?'),
  ('en.yusufali', 50, 7, 'And the earth- We have spread it out, and set thereon mountains standing firm, and produced therein every kind of beautiful growth (in pairs)-'),
  ('en.yusufali', 50, 8, 'To be observed and commemorated by every devotee turning (to Allah).'),
  ('en.yusufali', 50, 9, 'And We send down from the sky rain charted with blessing, and We produce therewith gardens and Grain for harvests;'),
  ('en.yusufali', 50, 10, 'And tall (and stately) palm-trees, with shoots of fruit-stalks, piled one over another;-'),
  ('en.yusufali', 50, 11, 'As sustenance for (Allah\'s) Servants;- and We give (new) life therewith to land that is dead: Thus will be the Resurrection.'),
  ('en.yusufali', 50, 12, 'Before them was denied (the Hereafter) by the People of Noah, the Companions of the Rass, the Thamud,'),
  ('en.yusufali', 50, 13, 'The \'Ad, Pharaoh, the brethren of Lut,'),
  ('en.yusufali', 50, 14, 'The Companions of the Wood, and the People of Tubba\'; each one (of them) rejected the messengers, and My warning was duly fulfilled (in them).'),
  ('en.yusufali', 50, 15, 'Were We then weary with the first Creation, that they should be in confused doubt about a new Creation?'),
  ('en.yusufali', 50, 16, 'It was We Who created man, and We know what dark suggestions his soul makes to him: for We are nearer to him than (his) jugular vein.'),
  ('en.yusufali', 50, 17, 'Behold, two (guardian angels) appointed to learn (his doings) learn (and noted them), one sitting on the right and one on the left.'),
  ('en.yusufali', 50, 18, 'Not a word does he utter but there is a sentinel by him, ready (to note it).'),
  ('en.yusufali', 50, 19, 'And the stupor of death will bring Truth (before his eyes): "This was the thing which thou wast trying to escape!"'),
  ('en.yusufali', 50, 20, 'And the Trumpet shall be blown: that will be the Day whereof Warning (had been given).'),
  ('en.yusufali', 50, 21, 'And there will come forth every soul: with each will be an (angel) to drive, and an (angel) to bear witness.'),
  ('en.yusufali', 50, 22, '(It will be said:) "Thou wast heedless of this; now have We removed thy veil, and sharp is thy sight this Day!"'),
  ('en.yusufali', 50, 23, 'And his Companion will say: "Here is (his Record) ready with me!"'),
  ('en.yusufali', 50, 24, '(The sentence will be:) "Throw, throw into Hell every contumacious Rejecter (of Allah)!-'),
  ('en.yusufali', 50, 25, '"Who forbade what was good, transgressed all bounds, cast doubts and suspicions;'),
  ('en.yusufali', 50, 26, '"Who set up another god beside Allah: Throw him into a severe penalty."'),
  ('en.yusufali', 50, 27, 'His Companion will say: "Our Lord! I did not make him transgress, but he was (himself) far astray."'),
  ('en.yusufali', 50, 28, 'He will say: "Dispute not with each other in My Presence: I had already in advance sent you Warning.'),
  ('en.yusufali', 50, 29, '"The Word changes not before Me, and I do not the least injustice to My Servants."'),
  ('en.yusufali', 50, 30, 'One Day We will ask Hell, "Art thou filled to the full?" It will say, "Are there any more (to come)?"'),
  ('en.yusufali', 50, 31, 'And the Garden will be brought nigh to the Righteous,- no more a thing distant.'),
  ('en.yusufali', 50, 32, '(A voice will say:) "This is what was promised for you,- for every one who turned (to Allah) in sincere repentance, who kept (His Law),'),
  ('en.yusufali', 50, 33, '"Who feared (Allah) Most Gracious Unseen, and brought a heart turned in devotion (to Him):'),
  ('en.yusufali', 50, 34, '"Enter ye therein in Peace and Security; this is a Day of Eternal Life!"'),
  ('en.yusufali', 50, 35, 'There will be for them therein all that they wish,- and more besides in Our Presence.'),
  ('en.yusufali', 50, 36, 'But how many generations before them did We destroy (for their sins),- stronger in power than they? Then did they wander through the land: was there any place of escape (for them)?'),
  ('en.yusufali', 50, 37, 'Verily in this is a Message for any that has a heart and understanding or who gives ear and earnestly witnesses (the truth).'),
  ('en.yusufali', 50, 38, 'We created the heavens and the earth and all between them in Six Days, nor did any sense of weariness touch Us.'),
  ('en.yusufali', 50, 39, 'Bear, then, with patience, all that they say, and celebrate the praises of thy Lord, before the rising of the sun and before (its) setting.'),
  ('en.yusufali', 50, 40, 'And during part of the night, (also,) celebrate His praises, and (so likewise) after the postures of adoration.'),
  ('en.yusufali', 50, 41, 'And listen for the Day when the Caller will call out from a place quiet near,-'),
  ('en.yusufali', 50, 42, 'The Day when they will hear a (mighty) Blast in (very) truth: that will be the Day of Resurrection.'),
  ('en.yusufali', 50, 43, 'Verily it is We Who give Life and Death; and to Us is the Final Goal-'),
  ('en.yusufali', 50, 44, 'The Day when the Earth will be rent asunder, from (men) hurrying out: that will be a gathering together,- quite easy for Us.'),
  ('en.yusufali', 50, 45, 'We know best what they say; and thou art not one to overawe them by force. So admonish with the Qur\'an such as fear My Warning!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 50, 1, 'Qaaaf; wal Qur aanil Majeed'),
  ('en.transliteration', 50, 2, 'Bal \'ajibooo an jaa\'ahum munzirum minhum faqaalal kaafiroona haazaa shai\'un \'ajeeb'),
  ('en.transliteration', 50, 3, '\'A-izaa mitnaa wa kunnaa turaaban zaalika raj\'um ba\'eed'),
  ('en.transliteration', 50, 4, 'Qad \'alimnaa maa tanqu-sul-ardu minhum wa \'indanaa Kitaabun Hafeez'),
  ('en.transliteration', 50, 5, 'Bal kazzaboo bilhaqqi lammaa jaaa\'ahum fahum feee amrim mareej'),
  ('en.transliteration', 50, 6, 'Afalam yanzurooo ilas samaaa\'i fawqahum kaifa banainaahaa wa zaiyannaahaa wa maa lahaa min furooj'),
  ('en.transliteration', 50, 7, 'Wal arda madadnaahaa wa alqainaa feehaa rawaasiya wa ambatnaa feehaa min kulli zawjim baheej'),
  ('en.transliteration', 50, 8, 'Tabsiratanw wa zikraa likulli \'abdim muneeb'),
  ('en.transliteration', 50, 9, 'Wa nazzalnaa minas samaaa\'i maaa\'am mubaarakan fa ambatnaa bihee jannaatinw wa habbal haseed'),
  ('en.transliteration', 50, 10, 'Wannakhla baasiqaatil laha tal\'un nadeed'),
  ('en.transliteration', 50, 11, 'Rizqal lil\'ibaad, wa ahyainaa bihee baldatam maitaa; kazaalikal khurooj'),
  ('en.transliteration', 50, 12, 'Kazzabat qablahum qawmu Noohinw wa Ashaabur Rassi wa Samood'),
  ('en.transliteration', 50, 13, 'Wa \'Aadunw wa Fir\'awnu wikhwaanu loot'),
  ('en.transliteration', 50, 14, 'Wa Ashaabul Aykati wa qawmu Tubba\'; kullun kazzabar Rusula fahaqqa wa\'eed'),
  ('en.transliteration', 50, 15, 'Afa\'a yeenaa bilkhalqil awwal; bal hum fee labsim min khalqin jadeed'),
  ('en.transliteration', 50, 16, 'Wa laqad khalaqnal insaana wa na\'lamu maa tuwaswisu bihee nafsuhoo wa Nahnu aqrabu ilaihi min hablil wareed'),
  ('en.transliteration', 50, 17, '\'Iz yatalaqqal mutalaqqi yaani \'anil yameeni wa \'anish shimaali qa\'eed'),
  ('en.transliteration', 50, 18, 'Maa yalfizu min qawlin illaa ladaihi raqeebun \'ateed'),
  ('en.transliteration', 50, 19, 'Wa jaaa\'at kullu nafsim ma\'ahaa saaa\'iqunw wa shaheed'),
  ('en.transliteration', 50, 20, 'Wa nufikha fis Soor; zaalika yawmul wa\'eed'),
  ('en.transliteration', 50, 21, 'Wa jaaa\'at kullu nafsim ma\'ahaa saaa\'iqunw wa shaheed'),
  ('en.transliteration', 50, 22, 'Laqad kunta fee ghaf latim min haazaa fakashafnaa \'anka ghitaaa\'aka fabasarukal yawma hadeed'),
  ('en.transliteration', 50, 23, 'Wa qaala qareenuhoo haazaa maa ladaiya \'ateed'),
  ('en.transliteration', 50, 24, 'Alqiyaa fee Jahannama kulla kaffaarin \'aneed'),
  ('en.transliteration', 50, 25, 'Mannaa\'il lilkhayri mu\'tadim mureeb'),
  ('en.transliteration', 50, 26, 'Allazee ja\'ala ma\'al laahi ilaahan aakhara fa alqiyaahu fil\'azaabish shadeed'),
  ('en.transliteration', 50, 27, 'Qaala qareenuhoo Rabbanaa maaa atghaituhoo wa laakin kaana fee dalaahim ba\'eed'),
  ('en.transliteration', 50, 28, 'Qaala laa takhtasimoo ladaayya wa qad qaddamtu ilaikum bilwa\'eed'),
  ('en.transliteration', 50, 29, 'Maa yubaddalul qawlu ladaiya wa maaa ana bizal laamil lil\'abeed'),
  ('en.transliteration', 50, 30, 'Yawma naqoolu li\'jahannama halim talaati wa taqoolu hal mim mazeed'),
  ('en.transliteration', 50, 31, 'Wa uzlifatil jannatu lil muttaqeena ghaira ba\'eed'),
  ('en.transliteration', 50, 32, 'Haaza maa too\'adoona likulli awwaabin hafeez'),
  ('en.transliteration', 50, 33, 'Man khashiyar Rahmaana bilghaibi wa jaaa\'a biqalbim muneeb'),
  ('en.transliteration', 50, 34, 'Udkhuloohaa bisalaamin zaalika yawmul khulood'),
  ('en.transliteration', 50, 35, 'Lahum maa yashaaa\'oona feehaa wa ladainaa mazeed'),
  ('en.transliteration', 50, 36, 'Wa kam ahlaknaa qablahum min qarnin hum ashaddu minhum batshan fanaqqaboo fil bilaad, hal mim mahees'),
  ('en.transliteration', 50, 37, 'Inna fee zaalika lazikraa liman kaana lahoo qalbun aw alqas sam\'a wa huwa shaheed'),
  ('en.transliteration', 50, 38, 'Wa laqad khalaqnas samaawaati wal arda wa maa bainahumaa fee sittati ayyaamin wa maa massanaa mil lughoob'),
  ('en.transliteration', 50, 39, 'Fasbir \'alaa maa yaqooloona wa sabbih bihamdi Rabbika qabla tuloo\'ish shamsi wa qablal ghuroob'),
  ('en.transliteration', 50, 40, 'Wa minal laili fasabbih hu wa adbaaras sujood'),
  ('en.transliteration', 50, 41, 'Wastami\' yawma yunaa dil munaadi mim makaanin qareeb'),
  ('en.transliteration', 50, 42, 'Yawma yasmaoonas sai hata bilhaqq zaalika yawmul khurooj'),
  ('en.transliteration', 50, 43, 'Innaa Nahnu nuhyee wa numeetu wa ilainal maseer'),
  ('en.transliteration', 50, 44, 'Yawma tashaqqaqul ardu \'anhum siraa\'aa; zaalika hashrun \'alainaa yaseer'),
  ('en.transliteration', 50, 45, 'Nahnu a\'lamu bimaa yaqooloona wa maaa anta \'alihim bijabbaarin fazakkir bil quraani many yakhaafu wa\'eed')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 50, 1, 'قۤ۔ اس قرآن کی قسم جو بڑا شان والا ہے'),
  ('ur.ahmedali', 50, 2, 'بلکہ وہ تعجب کرتے ہیں کہ ان کے پاس انہیں میں سے ایک ڈرانے والا آیا پس کافرو ں نے کہا کہ یہ تو ایک عجیب بات ہے'),
  ('ur.ahmedali', 50, 3, 'کیا جب ہم مرجائیں گے اورمٹی ہو جائیں گے یہ دوبارہ زندگی بعید از قیاس ہے'),
  ('ur.ahmedali', 50, 4, 'ہمیں معلوم ہے جو زمین ان میں سے کم کرتی ہے اور ہمارے پاس ایک کتاب ہے جس میں سب کھچ محفوظ ہے'),
  ('ur.ahmedali', 50, 5, 'بلکہ انہوں نے حق کو جھٹلایا جب کہ وہ ان کے پاس آیا پس وہ ایک الجھی ہوئی بات میں پڑے ہوئے ہیں'),
  ('ur.ahmedali', 50, 6, 'پس کیا انہوں نے غور سے اپنے اوپر آسمان کو نہیں دیکھا کہ ہم نے کس طرح اسے بنایا اور آراستہ کیا ہے اور اس میں کوئی بھی شگاف نہیں'),
  ('ur.ahmedali', 50, 7, 'اور ہم نے زمین کو بچھا دیا اوراس میں مضبوط ڈال دیے اور اس میں ہر قسم کی خوشنما چیزیں اگائیں'),
  ('ur.ahmedali', 50, 8, 'ہر رجوع کرے والے بندے کے لیے بصیرت اور نصیحت ہے'),
  ('ur.ahmedali', 50, 9, 'اور ہم نے آسمان سے برکت والا پانی اتارا پھر ہم پھر ہم نے اس کے ذریعے سے باغ اگائے اور اناج جن کے کھیت کاٹے جاتے ہیں'),
  ('ur.ahmedali', 50, 10, 'او رلمبی لمبی کھجوریں جن کے خوشے تہہ بہ تہہ ہیں'),
  ('ur.ahmedali', 50, 11, 'بندوں کے لیے روزی اورہم نے اس سے ایک مردہ بستی کو زندہ کیا دوبارہ نکلنا اس طرح ہے'),
  ('ur.ahmedali', 50, 12, 'ان سے پہلے قوم نوح اور کنوئیں والوں نے اور قوم ثمود نے جھٹلایا'),
  ('ur.ahmedali', 50, 13, 'اور قوم عاد اور فرعون اور قوم لوط نے'),
  ('ur.ahmedali', 50, 14, 'اور بن والو ں اور قوم تبعّ نے ہر ایک نےرسولوں کو جھٹلایا تو ہمارا وعدہ عذاب ثابت ہوا'),
  ('ur.ahmedali', 50, 15, 'کی ہم پہلی بار پیدا کرنے میں تھک گئے ہیں (نہیں) بلکہ وہ از سرِ نو پیدا کرنے کے متعلق شک میں ہیں'),
  ('ur.ahmedali', 50, 16, 'اور بے شک ہم نے انسان کو پیدا کیا اور ہم جانتے ہیں جو وسوسہ اس کے دل میں گزرتا ہے اور ہم اس سے اس کی رگ گلو سے بھی زیادہ قریب ہیں'),
  ('ur.ahmedali', 50, 17, 'جب کہ ضبط کرنے والے دایں اوربائیں بیٹھیں ہوئے ضبط کرتے جاتے ہیں'),
  ('ur.ahmedali', 50, 18, 'وہ منہ سے کوئی بات نہیں نکالتا مگراس کے پاس ایک ہوشیار محافظ ہوتا ہے'),
  ('ur.ahmedali', 50, 19, 'اور موت کی بے ہوشی تو ضرور آ کر رہے گی یہی ہے وہ جس سے تو گریز کرتا تھا'),
  ('ur.ahmedali', 50, 20, 'اور صور میں پھونکا جائے گا وعدہ عذاب کا دن یہی ہے'),
  ('ur.ahmedali', 50, 21, 'اور ہر ایک شخص آئے گا اس کے ساتھ ایک ہانکنے والا اورایک گواہی دینے والا ہوگا'),
  ('ur.ahmedali', 50, 22, 'بے شک تو تو اس دن سے غفلت میں رہا پس ہم نے تجھ سے تیرا پردہ دور کر دیا پس تیری نگاہ آج بڑی تیز ہے'),
  ('ur.ahmedali', 50, 23, 'اور اس کا ساتھی کہے گا یہ ہے جو میرے پاس تیار ہے (حکم ہوگ)'),
  ('ur.ahmedali', 50, 24, 'تم دونوں ہر کافر سرکش کو دوزخ میں ڈال دو'),
  ('ur.ahmedali', 50, 25, 'جو نیکی سےروکنے والا حد سےبڑھنے والا شک کرنے والا ہے'),
  ('ur.ahmedali', 50, 26, 'جس نے الله کے ساتھ کوئی دوسرا معبود ٹھیرایا پس اسے سخت عذاب میں ڈال دو'),
  ('ur.ahmedali', 50, 27, 'اس کا ہم نشین کہے گا اے ہمارے رب میں نے اسے گمراہ نہیں کیا تھا بلکہ وہ خود ہی بڑی گمراہی میں پڑا ہوا تھا'),
  ('ur.ahmedali', 50, 28, 'فرمائے گا تم میرے پاس مت جھگڑو اور میں تو پہلے تمہاری طرف اپنے عذاب کا وعدہ بھیج چکا تھا'),
  ('ur.ahmedali', 50, 29, 'میرے ہاں کی بات بدلی نہیں جاتی اور نہ ہی بندو ں کے لیے ظالم ہوں'),
  ('ur.ahmedali', 50, 30, 'جس دن ہم جہنم سے کہیں گے کیا تو بھر چکی اوروہ کہے گی کیا کچھ اوربھی ہے'),
  ('ur.ahmedali', 50, 31, 'اوربہشت پرہیزگاروں کے لیے قریب لائی جائے گی کہ کچھ فاصلہ نہ ہوگا'),
  ('ur.ahmedali', 50, 32, 'یہی ہے جس کا تم سے وعدہ کیا جاتا تھا ہر رجوع کرنے والے اور حفاظت کرنے والے کے لیے'),
  ('ur.ahmedali', 50, 33, 'جو کوئی الله سے بن دیکھے ڈرا اور رجوع کرنے والا دل لے کر آیا'),
  ('ur.ahmedali', 50, 34, 'اس میں سلامتی سے داخل ہو جاؤ ہمیشہ رہنے کا دن یہی ہے'),
  ('ur.ahmedali', 50, 35, 'انہیں جو کچھ وہ چاہیں گے وہاں ملے گا اور ہمارے پاس اوربھی زیادہ ہے'),
  ('ur.ahmedali', 50, 36, 'اور ہم نے ان سے پہلے کتنی قومیں ہلاک کر دیں جو قوت میں ان سے بڑھ کر تھیں پھر (عذاب کے وقت) شہرو ں میں دوڑتے پھرنے لگے کہ کوئی پناہ کی جگہ بھی ہے'),
  ('ur.ahmedali', 50, 37, 'بے شک اس میں شخص کے لیے بڑی عبرت ہے جس کے پاس (فہیم) دل ہو یا وہ متوجہ ہو کر (بات کی طرف) کان ہی لگا دیتا ہو'),
  ('ur.ahmedali', 50, 38, 'اور بے شک ہم نےآسمانوں اور زمین کو پیدا کیا اورجو کچھ ان کے درمیان میں ہے چھ دن میں اور ہمیں کچھ بھی تکان نہ ہوئی'),
  ('ur.ahmedali', 50, 39, 'پس ان باتوں پر صبر کر جو وہ کہتے ہیں اور اپنے رب کی پاکیزگی بیان کر تعریف کے ساتھ دن نکلنے سے پہلے اور دن چھپنے سے پہلے'),
  ('ur.ahmedali', 50, 40, 'اورکچھ رات میں بھی اس کی تسبیح کر اور نماز کے بعد بھی'),
  ('ur.ahmedali', 50, 41, 'اور توجہ سے سنیئے جس دن پکارنے والا پاس سے پکارے گا'),
  ('ur.ahmedali', 50, 42, 'جس دن وہ ایک چیخ کو بخوبی سنیں گے یہ دن قبروں سے نکلنے کا ہوگا'),
  ('ur.ahmedali', 50, 43, 'بے شک ہم ہی زندہ کرتے اورمارتے ہیں اورہماری طرف ہی لوٹ کر آنا ہے'),
  ('ur.ahmedali', 50, 44, 'جس دن ان پر سے زمین پھٹ جائے گی لوگ دوڑتے ہوئے نکل آئيں گے یہ لوگو ں کا جمع کرنا ہمیں بہت آسان ہے'),
  ('ur.ahmedali', 50, 45, 'ہم جانتے ہیں جو کچھ وہ کہتے ہیں اور آپ ا ن پر کچھ زبردستی کرنے والے نہیں پھر آپ قرآن سے اس کو نصیحت کیجیئے جو میرے عذاب سے ڈرتا ہو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 50, 1, 'Kaf. Şanlı Kuran\'a and olsun.'),
  ('tr.diyanet', 50, 2, 'Kafirler, Aralarından bir uyarıcının gelmesine şaştılar da: "Bu şaşılacak bir şey; öldüğümüz ve toprak olduğumuz zaman dirilecek miyiz? Bu, ihtimali olmayan bir dönüştür" dediler.'),
  ('tr.diyanet', 50, 3, 'Kafirler, Aralarından bir uyarıcının gelmesine şaştılar da: "Bu şaşılacak bir şey; öldüğümüz ve toprak olduğumuz zaman dirilecek miyiz? Bu, ihtimali olmayan bir dönüştür" dediler.'),
  ('tr.diyanet', 50, 4, 'Onlardan kimlerin ölüp toprağa karıştığını biliyoruz. Katımızda her şeyi unutulmaktan koruyan bir kitap vardır.'),
  ('tr.diyanet', 50, 5, 'Hayır; onlar, gerçek kendilerine gelince onu yalanladılar; kararsızlık içindedirler.'),
  ('tr.diyanet', 50, 6, 'Onlar, üstlerindeki göğü nasıl yapmışız, süslemişizdir bir bakmazlar mı? Onda hiçbir çatlak da yoktur.'),
  ('tr.diyanet', 50, 7, 'Allah\'a yönelen her kula öğüt ve bir belge olarak yeryüzünü yaydık, oraya sabit dağlar yerleştirdik, orada her güzel türden yetiştirdik.'),
  ('tr.diyanet', 50, 8, 'Allah\'a yönelen her kula öğüt ve bir belge olarak yeryüzünü yaydık, oraya sabit dağlar yerleştirdik, orada her güzel türden yetiştirdik.'),
  ('tr.diyanet', 50, 9, 'Gökten bereketli bir su indirdik, kullara rızık olmak üzere onunla bahçeler, biçilecek taneli ekinler, küme küme tomurcukları olan boylu hurma ağaçları yetiştirdik. O su ile ölü yeri dirilttik. İşte insanların diriltilmesi de böyledir.'),
  ('tr.diyanet', 50, 10, 'Gökten bereketli bir su indirdik, kullara rızık olmak üzere onunla bahçeler, biçilecek taneli ekinler, küme küme tomurcukları olan boylu hurma ağaçları yetiştirdik. O su ile ölü yeri dirilttik. İşte insanların diriltilmesi de böyledir.'),
  ('tr.diyanet', 50, 11, 'Gökten bereketli bir su indirdik, kullara rızık olmak üzere onunla bahçeler, biçilecek taneli ekinler, küme küme tomurcukları olan boylu hurma ağaçları yetiştirdik. O su ile ölü yeri dirilttik. İşte insanların diriltilmesi de böyledir.'),
  ('tr.diyanet', 50, 12, 'Onlardan önce Nuh milleti, Ressliler, Semud, Ad, Firavun milletleri, Lut\'un kardeşleri, Eykeliler, Tubba milleti de yalanlamışlardı; evet bunların hepsi peygamberleri yalanlamışlardı da tehdidim gerçekleşmişti.'),
  ('tr.diyanet', 50, 13, 'Onlardan önce Nuh milleti, Ressliler, Semud, Ad, Firavun milletleri, Lut\'un kardeşleri, Eykeliler, Tubba milleti de yalanlamışlardı; evet bunların hepsi peygamberleri yalanlamışlardı da tehdidim gerçekleşmişti.'),
  ('tr.diyanet', 50, 14, 'Onlardan önce Nuh milleti, Ressliler, Semud, Ad, Firavun milletleri, Lut\'un kardeşleri, Eykeliler, Tubba milleti de yalanlamışlardı; evet bunların hepsi peygamberleri yalanlamışlardı da tehdidim gerçekleşmişti.'),
  ('tr.diyanet', 50, 15, 'Biz ilk yaratışta yorulduk mu? Hayır; onlar yeniden yaratılmaktan şüphe etmektedirler.'),
  ('tr.diyanet', 50, 16, 'And olsun ki insanı Biz yarattık; nefsinin kendisine fısıldadıklarını biliriz; Biz ona şah damarından daha yakınız.'),
  ('tr.diyanet', 50, 17, 'Sağında ve solunda, onunla beraber oturan iki alıcı melek, yanında hazır birer gözcü olarak söylediği her sözü zaptederler.'),
  ('tr.diyanet', 50, 18, 'Sağında ve solunda, onunla beraber oturan iki alıcı melek, yanında hazır birer gözcü olarak söylediği her sözü zaptederler.'),
  ('tr.diyanet', 50, 19, 'Ölüm sarhoşluğu gerçekten gelir, ey insan, işte bu senin öteden beri korkup kaçtığın şeydir.'),
  ('tr.diyanet', 50, 20, 'Sura üfürülür. İşte bu geleceği söz verilen gündür.'),
  ('tr.diyanet', 50, 21, 'Her can, kendisiyle beraber bir sürücü ve şahit bulunduğu halde gelir.'),
  ('tr.diyanet', 50, 22, 'Ona: "And olsun ki, sen, bundan gafildin; işte senden gaflet perdesini kaldırdık, bugün artık görüşün keskindir" denir.'),
  ('tr.diyanet', 50, 23, 'Yanındaki melek: "İşte bu yanımdaki hazırdır" der.'),
  ('tr.diyanet', 50, 24, 'Allah: "Ey sürücü ve şahit! Her inatçı inkarcıyı, iyiliklere boyuna engel olan, mütecaviz, şüpheye düşüren, Allah\'ın yanında başka tanrı benimseyen kişiyi cehenneme atın, onu çetin bir azaba sokun" buyurur.'),
  ('tr.diyanet', 50, 25, 'Allah: "Ey sürücü ve şahit! Her inatçı inkarcıyı, iyiliklere boyuna engel olan, mütecaviz, şüpheye düşüren, Allah\'ın yanında başka tanrı benimseyen kişiyi cehenneme atın, onu çetin bir azaba sokun" buyurur.'),
  ('tr.diyanet', 50, 26, 'Allah: "Ey sürücü ve şahit! Her inatçı inkarcıyı, iyiliklere boyuna engel olan, mütecaviz, şüpheye düşüren, Allah\'ın yanında başka tanrı benimseyen kişiyi cehenneme atın, onu çetin bir azaba sokun" buyurur.'),
  ('tr.diyanet', 50, 27, 'Yanındaki şeytan: "Rabbimiz! Ben onu azdırmadım, fakat kendisi derin bir sapıklıktaydı" der.'),
  ('tr.diyanet', 50, 28, 'Allah: "Benim katımda çekişmeyin; size bunu önceden bildirmiştim. Benim katımda söz değişmez; Ben kullara asla zulmetmem" der.'),
  ('tr.diyanet', 50, 29, 'Allah: "Benim katımda çekişmeyin; size bunu önceden bildirmiştim. Benim katımda söz değişmez; Ben kullara asla zulmetmem" der.'),
  ('tr.diyanet', 50, 30, 'O gün cehenneme: "Doldun mu?" deriz, o: "Daha var mı?" der.'),
  ('tr.diyanet', 50, 31, 'Cennet, Allah\'a karşı gelmekten sakınanlara yaklaştırılır, zaten uzakta değildir.'),
  ('tr.diyanet', 50, 32, 'Onlara: "İşte bu cennet, Allah\'a yönelen, O\'nun buyruklarına riayet eden; görmediği Rahman\'dan korkan, Allah\'a yönelmiş bir kalble gelen sizlere, hepinize söz verilen yerdir. Oraya esenlikle girin; işte sonsuzluk günü budur" denir.'),
  ('tr.diyanet', 50, 33, 'Onlara: "İşte bu cennet, Allah\'a yönelen, O\'nun buyruklarına riayet eden; görmediği Rahman\'dan korkan, Allah\'a yönelmiş bir kalble gelen sizlere, hepinize söz verilen yerdir. Oraya esenlikle girin; işte sonsuzluk günü budur" denir.'),
  ('tr.diyanet', 50, 34, 'Onlara: "İşte bu cennet, Allah\'a yönelen, O\'nun buyruklarına riayet eden; görmediği Rahman\'dan korkan, Allah\'a yönelmiş bir kalble gelen sizlere, hepinize söz verilen yerdir. Oraya esenlikle girin; işte sonsuzluk günü budur" denir.'),
  ('tr.diyanet', 50, 35, 'Orada dilediklerini bulurlar. Katımızda fazlası da vardır.'),
  ('tr.diyanet', 50, 36, 'Bu inkarcılardan önce, kendilerinden daha kuvvetli olan, diyar diyar dolaşan nice nesilleri yok etmişizdir. Kurtuluşu var mı?'),
  ('tr.diyanet', 50, 37, 'Doğrusu bunda, kalbi olana veya hazır bulunup kulak verene ders vardır.'),
  ('tr.diyanet', 50, 38, 'And olsun ki, gökleri, yeri ve ikisinin arasında bulunanları altı günde yarattık ve Biz bir yorgunluk da duymadık.'),
  ('tr.diyanet', 50, 39, 'Söylediklerine sabret; Rabbini, güneşin doğmasından önce ve batışından önce överek tesbih et.'),
  ('tr.diyanet', 50, 40, 'Geceleyin ve secdelerin ardından O\'nu tesbih et.'),
  ('tr.diyanet', 50, 41, 'Bir çağırıcının yakın bir yerden çağıracağı güne kulak ver.'),
  ('tr.diyanet', 50, 42, 'O gün çığlığı gerçekten duyarlar; işte o, kabirden çıkış günüdür.'),
  ('tr.diyanet', 50, 43, 'Doğrusu Biz diriltiriz, Biz öldürürüz, dönüş Bize\'dir.'),
  ('tr.diyanet', 50, 44, 'O gün, yer yarılır, onlar çabucak ayrılır; bu, Bize göre kolay bir toplamadır.'),
  ('tr.diyanet', 50, 45, 'Onların dediklerini Biz biliriz. Sen onların üzerinde bir zorba değilsin; söz verdiğim günden korkanlara Kuran\'la öğüt ver.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 50, 1, 'Qaaf Demi Al Quran yang sangat mulia.'),
  ('id.indonesian', 50, 2, '(Mereka tidak menerimanya) bahkan mereka tercengang karena telah datang kepada mereka seorang pemberi peringatan dari (kalangan) mereka sendiri, maka berkatalah orang-orang kafir: "Ini adalah suatu yang amat ajaib".'),
  ('id.indonesian', 50, 3, 'Apakah kami setelah mati dan setelah menjadi tanah (kami akan kembali lagi)?, itu adalah suatu pengembalian yang tidak mungkin.'),
  ('id.indonesian', 50, 4, 'Sesungguhnya Kami telah mengetahui apa yang dihancurkan oleh bumi dari (tubuh-tubuh) mereka, dan pada sisi Kamipun ada kitab yang memelihara (mencatat).'),
  ('id.indonesian', 50, 5, 'Sebenarnya, mereka telah mendustakan kebenaran tatkala kebenaran itu datang kepada mereka, maka mereka berada dalam keadaan kacau balau.'),
  ('id.indonesian', 50, 6, 'Maka apakah mereka tidak melihat akan langit yang ada di atas mereka, bagaimana Kami meninggikannya dan menghiasinya dan langit itu tidak mempunyai retak-retak sedikitpun?'),
  ('id.indonesian', 50, 7, 'Dan Kami hamparkan bumi itu dan Kami letakkan padanya gunung-gunung yang kokoh dan Kami tumbuhkan padanya segala macam tanaman yang indah dipandang mata,'),
  ('id.indonesian', 50, 8, 'untuk menjadi pelajaran dan peringatan bagi tiap-tiap hamba yang kembali (mengingat Allah).'),
  ('id.indonesian', 50, 9, 'Dan Kami turunkan dari langit air yang banyak manfaatnya lalu Kami tumbuhkan dengan air itu pohon-pohon dan biji-biji tanaman yang diketam,'),
  ('id.indonesian', 50, 10, 'dan pohon kurma yang tinggi-tinggi yang mempunyai mayang yang bersusun-susun,'),
  ('id.indonesian', 50, 11, 'untuk menjadi rezeki bagi hamba-hamba (Kami), dan Kami hidupkan dengan air itu tanah yang mati (kering). Seperti itulah terjadinya kebangkitan.'),
  ('id.indonesian', 50, 12, 'Sebelum mereka telah mendustakan (pula) kaum Nuh dan penduduk Rass dan Tsamud,'),
  ('id.indonesian', 50, 13, 'dan kaum Aad, kaum Fir\'aun dan kaum Luth,'),
  ('id.indonesian', 50, 14, 'dan penduduk Aikah serta kaum Tubba\' semuanya telah mendustakan rasul-rasul maka sudah semestinyalah mereka mendapat hukuman yang sudah diancamkan.'),
  ('id.indonesian', 50, 15, 'Maka apakah Kami letih dengan penciptaan yang pertama? Sebenarnya mereka dalam keadaan ragu-ragu tentang penciptaan yang baru.'),
  ('id.indonesian', 50, 16, 'Dan sesungguhnya Kami telah menciptakan manusia dan mengetahui apa yang dibisikkan oleh hatinya, dan Kami lebih dekat kepadanya daripada urat lehernya,'),
  ('id.indonesian', 50, 17, '(yaitu) ketika dua orang malaikat mencatat amal perbuatannya, seorang duduk di sebelah kanan dan yang lain duduk di sebelah kiri.'),
  ('id.indonesian', 50, 18, 'Tiada suatu ucapanpun yang diucapkannya melainkan ada di dekatnya malaikat pengawas yang selalu hadir.'),
  ('id.indonesian', 50, 19, 'Dan datanglah sakaratul maut dengan sebenar-benarnya. Itulah yang kamu selalu lari daripadanya.'),
  ('id.indonesian', 50, 20, 'Dan ditiuplah sangkakala. Itulah hari terlaksananya ancaman.'),
  ('id.indonesian', 50, 21, 'Dan datanglah tiap-tiap diri, bersama dengan dia seorang malaikat penggiring dan seorang malaikat penyaksi.'),
  ('id.indonesian', 50, 22, 'Sesungguhnya kamu berada dalam keadaan lalai dari (hal) ini, maka Kami singkapkan daripadamu tutup (yang menutupi) matamu, maka penglihatanmu pada hari itu amat tajam.'),
  ('id.indonesian', 50, 23, 'Dan yang menyertai dia berkata: "Inilah (catatan amalnya) yang tersedia pada sisiku".'),
  ('id.indonesian', 50, 24, 'Allah berfirman: "Lemparkanlah olehmu berdua ke dalam neraka semua orang yang sangat ingkar dan keras kepala,'),
  ('id.indonesian', 50, 25, 'yang sangat menghalangi kebajikan, melanggar batas lagi ragu-ragu,'),
  ('id.indonesian', 50, 26, 'yang menyembah sembahan yang lain beserta Allah maka lemparkanlah dia ke dalam siksaan yang sangat".'),
  ('id.indonesian', 50, 27, 'Yang menyertai dia berkata (pula): "Ya Tuhan kami, aku tidak menyesatkannya tetapi dialah yang berada dalam kesesatan yang jauh".'),
  ('id.indonesian', 50, 28, 'Allah berfirman: "Janganlah kamu bertengkar di hadapan-Ku, padahal sesungguhnya Aku dahulu telah memberikan ancaman kepadamu".'),
  ('id.indonesian', 50, 29, 'Keputusan di sisi-Ku tidak dapat diubah dan Aku sekali-kali tidak menganiaya hamba-hamba-Ku'),
  ('id.indonesian', 50, 30, '(Dan ingatlah akan) hari (yang pada hari itu) Kami bertanya kepada jahannam: "Apakah kamu sudah penuh?" Dia menjawab: "Masih ada tambahan?"'),
  ('id.indonesian', 50, 31, 'Dan didekatkanlah surga itu kepada orang-orang yang bertakwa pada tempat yang tiada jauh (dari mereka).'),
  ('id.indonesian', 50, 32, 'Inilah yang dijanjikan kepadamu, (yaitu) kepada setiap hamba yang selalu kembali (kepada Allah) lagi memelihara (semua peraturan-peraturan-Nya)'),
  ('id.indonesian', 50, 33, '(Yaitu) orang yang takut kepada Tuhan Yang Maha Pemurah sedang Dia tidak kelihatan (olehnya) dan dia datang dengan hati yang bertaubat,'),
  ('id.indonesian', 50, 34, 'masukilah surga itu dengan aman, itulah hari kekekalan.'),
  ('id.indonesian', 50, 35, 'Mereka di dalamnya memperoleh apa yang mereka kehendaki; dan pada sisi Kami ada tambahannya.'),
  ('id.indonesian', 50, 36, 'Dan berapa banyaknya umat-umat yang telah Kami binasakan sebelum mereka yang mereka itu lebih besar kekuatannya daripada mereka ini, maka mereka (yang telah dibinasakan itu) telah pernah menjelajah di beberapa negeri. Adakah (mereka) mendapat tempat lari (dari kebinasaan)?'),
  ('id.indonesian', 50, 37, 'Sesungguhnya pada yang demikian itu benar-benar terdapat peringatan bagi orang-orang yang mempunyai akal atau yang menggunakan pendengarannya, sedang dia menyaksikannya.'),
  ('id.indonesian', 50, 38, 'Dan sesungguhnya telah Kami ciptakan langit dan bumi dan apa yang ada antara keduanya dalam enam masa, dan Kami sedikitpun tidak ditimpa keletihan.'),
  ('id.indonesian', 50, 39, 'Maka bersabarlah kamu terhadap apa yang mereka katakan dan bertasbihlah sambil memuji Tuhanmu sebelum terbit matahari dan sebelum terbenam(nya).'),
  ('id.indonesian', 50, 40, 'Dan bertasbihlah kamu kepada-Nya di malam hari dan setiap selesai sembahyang.'),
  ('id.indonesian', 50, 41, 'Dan dengarkanlah (seruan) pada hari penyeru (malaikat) menyeru dari tempat yang dekat.'),
  ('id.indonesian', 50, 42, '(Yaitu) pada hari mereka mendengar teriakan dengan sebenar-benarnya itulah hari ke luar (dari kubur).'),
  ('id.indonesian', 50, 43, 'Sesungguhnya Kami menghidupkan dan mematikan dan hanya kepada Kami-lah tempat kembali (semua makhluk).'),
  ('id.indonesian', 50, 44, '(Yaitu) pada hari bumi terbelah-belah menampakkan mereka (lalu mereka ke luar) dengan cepat. Yang demikian itu adalah pengumpulan yang mudah bagi Kami.'),
  ('id.indonesian', 50, 45, 'Kami lebih mengetahui tentang apa yang mereka katakan, dan kamu sekali-kali bukanlah seorang pemaksa terhadap mereka. Maka beri peringatanlah dengan Al Quran orang yang takut dengan ancaman-Ku.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 51, 1, 'By those [winds] scattering [dust] dispersing'),
  ('en.sahih', 51, 2, 'And those [clouds] carrying a load [of water]'),
  ('en.sahih', 51, 3, 'And those [ships] sailing with ease'),
  ('en.sahih', 51, 4, 'And those [angels] apportioning [each] matter,'),
  ('en.sahih', 51, 5, 'Indeed, what you are promised is true.'),
  ('en.sahih', 51, 6, 'And indeed, the recompense is to occur.'),
  ('en.sahih', 51, 7, 'By the heaven containing pathways,'),
  ('en.sahih', 51, 8, 'Indeed, you are in differing speech.'),
  ('en.sahih', 51, 9, 'Deluded away from the Qur\'an is he who is deluded.'),
  ('en.sahih', 51, 10, 'Destroyed are the falsifiers'),
  ('en.sahih', 51, 11, 'Who are within a flood [of confusion] and heedless.'),
  ('en.sahih', 51, 12, 'They ask, "When is the Day of Recompense?"'),
  ('en.sahih', 51, 13, '[It is] the Day they will be tormented over the Fire'),
  ('en.sahih', 51, 14, '[And will be told], "Taste your torment. This is that for which you were impatient."'),
  ('en.sahih', 51, 15, 'Indeed, the righteous will be among gardens and springs,'),
  ('en.sahih', 51, 16, 'Accepting what their Lord has given them. Indeed, they were before that doers of good.'),
  ('en.sahih', 51, 17, 'They used to sleep but little of the night,'),
  ('en.sahih', 51, 18, 'And in the hours before dawn they would ask forgiveness,'),
  ('en.sahih', 51, 19, 'And from their properties was [given] the right of the [needy] petitioner and the deprived.'),
  ('en.sahih', 51, 20, 'And on the earth are signs for the certain [in faith]'),
  ('en.sahih', 51, 21, 'And in yourselves. Then will you not see?'),
  ('en.sahih', 51, 22, 'And in the heaven is your provision and whatever you are promised.'),
  ('en.sahih', 51, 23, 'Then by the Lord of the heaven and earth, indeed, it is truth - just as [sure as] it is that you are speaking.'),
  ('en.sahih', 51, 24, 'Has there reached you the story of the honored guests of Abraham? -'),
  ('en.sahih', 51, 25, 'When they entered upon him and said, "[We greet you with] peace." He answered, "[And upon you] peace, [you are] a people unknown.'),
  ('en.sahih', 51, 26, 'Then he went to his family and came with a fat [roasted] calf'),
  ('en.sahih', 51, 27, 'And placed it near them; he said, "Will you not eat?"'),
  ('en.sahih', 51, 28, 'And he felt from them apprehension. They said, "Fear not," and gave him good tidings of a learned boy.'),
  ('en.sahih', 51, 29, 'And his wife approached with a cry [of alarm] and struck her face and said, "[I am] a barren old woman!"'),
  ('en.sahih', 51, 30, 'They said, "Thus has said your Lord; indeed, He is the Wise, the Knowing."'),
  ('en.sahih', 51, 31, '[Abraham] said, "Then what is your business [here], O messengers?"'),
  ('en.sahih', 51, 32, 'They said, "Indeed, we have been sent to a people of criminals'),
  ('en.sahih', 51, 33, 'To send down upon them stones of clay,'),
  ('en.sahih', 51, 34, 'Marked in the presence of your Lord for the transgressors."'),
  ('en.sahih', 51, 35, 'So We brought out whoever was in the cities of the believers.'),
  ('en.sahih', 51, 36, 'And We found not within them other than a [single] house of Muslims.'),
  ('en.sahih', 51, 37, 'And We left therein a sign for those who fear the painful punishment.'),
  ('en.sahih', 51, 38, 'And in Moses [was a sign], when We sent him to Pharaoh with clear authority.'),
  ('en.sahih', 51, 39, 'But he turned away with his supporters and said," A magician or a madman."'),
  ('en.sahih', 51, 40, 'So We took him and his soldiers and cast them into the sea, and he was blameworthy.'),
  ('en.sahih', 51, 41, 'And in \'Aad [was a sign], when We sent against them the barren wind.'),
  ('en.sahih', 51, 42, 'It left nothing of what it came upon but that it made it like disintegrated ruins.'),
  ('en.sahih', 51, 43, 'And in Thamud, when it was said to them, "Enjoy yourselves for a time."'),
  ('en.sahih', 51, 44, 'But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on.'),
  ('en.sahih', 51, 45, 'And they were unable to arise, nor could they defend themselves.'),
  ('en.sahih', 51, 46, 'And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient.'),
  ('en.sahih', 51, 47, 'And the heaven We constructed with strength, and indeed, We are [its] expander.'),
  ('en.sahih', 51, 48, 'And the earth We have spread out, and excellent is the preparer.'),
  ('en.sahih', 51, 49, 'And of all things We created two mates; perhaps you will remember.'),
  ('en.sahih', 51, 50, 'So flee to Allah. Indeed, I am to you from Him a clear warner.'),
  ('en.sahih', 51, 51, 'And do not make [as equal] with Allah another deity. Indeed, I am to you from Him a clear warner.'),
  ('en.sahih', 51, 52, 'Similarly, there came not to those before them any messenger except that they said, "A magician or a madman."'),
  ('en.sahih', 51, 53, 'Did they suggest it to them? Rather, they [themselves] are a transgressing people.'),
  ('en.sahih', 51, 54, 'So leave them, [O Muhammad], for you are not to be blamed.'),
  ('en.sahih', 51, 55, 'And remind, for indeed, the reminder benefits the believers.'),
  ('en.sahih', 51, 56, 'And I did not create the jinn and mankind except to worship Me.'),
  ('en.sahih', 51, 57, 'I do not want from them any provision, nor do I want them to feed Me.'),
  ('en.sahih', 51, 58, 'Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength.'),
  ('en.sahih', 51, 59, 'And indeed, for those who have wronged is a portion [of punishment] like the portion of their predecessors, so let them not impatiently urge Me.'),
  ('en.sahih', 51, 60, 'And woe to those who have disbelieved from their Day which they are promised.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 51, 1, 'কসম ঝঞ্ঝাবায়ুর।'),
  ('bn.bengali', 51, 2, 'অতঃপর বোঝা বহনকারী মেঘের।'),
  ('bn.bengali', 51, 3, 'অতঃপর মৃদু চলমান জলযানের,'),
  ('bn.bengali', 51, 4, 'অতঃপর কর্ম বন্টনকারী ফেরেশতাগণের,'),
  ('bn.bengali', 51, 5, 'তোমাদের প্রদত্ত ওয়াদা অবশ্যই সত্য।'),
  ('bn.bengali', 51, 6, 'ইনসাফ অবশ্যম্ভাবী।'),
  ('bn.bengali', 51, 7, 'পথবিশিষ্ট আকাশের কসম,'),
  ('bn.bengali', 51, 8, 'তোমরা তো বিরোধপূর্ণ কথা বলছ।'),
  ('bn.bengali', 51, 9, 'যে ভ্রষ্ট, সেই এ থেকে মুখ ফিরায়,'),
  ('bn.bengali', 51, 10, 'অনুমানকারীরা ধ্বংস হোক,'),
  ('bn.bengali', 51, 11, 'যারা উদাসীন, ভ্রান্ত।'),
  ('bn.bengali', 51, 12, 'তারা জিজ্ঞাসা করে, কেয়ামত কবে হবে?'),
  ('bn.bengali', 51, 13, 'যেদিন তারা অগ্নিতে পতিত হবে,'),
  ('bn.bengali', 51, 14, 'তোমরা তোমাদের শাস্তি আস্বাদন কর। তোমরা একেই ত্বরান্বিত করতে চেয়েছিল।'),
  ('bn.bengali', 51, 15, 'খোদাভীরুরা জান্নাতে ও প্রস্রবণে থাকবে।'),
  ('bn.bengali', 51, 16, 'এমতাবস্থায় যে, তারা গ্রহণ করবে যা তাদের পালনকর্তা তাদেরকে দেবেন। নিশ্চয় ইতিপূর্বে তারা ছিল সৎকর্মপরায়ণ,'),
  ('bn.bengali', 51, 17, 'তারা রাত্রির সামান্য অংশেই নিদ্রা যেত,'),
  ('bn.bengali', 51, 18, 'রাতের শেষ প্রহরে তারা ক্ষমাপ্রার্থনা করত,'),
  ('bn.bengali', 51, 19, 'এবং তাদের ধন-সম্পদে প্রার্থী ও বঞ্চিতের হক ছিল।'),
  ('bn.bengali', 51, 20, 'বিশ্বাসকারীদের জন্যে পৃথিবীতে নিদর্শনাবলী রয়েছে,'),
  ('bn.bengali', 51, 21, 'এবং তোমাদের নিজেদের মধ্যেও, তোমরা কি অনুধাবন করবে না?'),
  ('bn.bengali', 51, 22, 'আকাশে রয়েছে তোমাদের রিযিক ও প্রতিশ্রুত সবকিছু।'),
  ('bn.bengali', 51, 23, 'নভোমন্ডল ও ভূমন্ডলের পালনকর্তার কসম, তোমাদের কথাবার্তার মতই এটা সত্য।'),
  ('bn.bengali', 51, 24, 'আপনার কাছে ইব্রাহীমের সম্মানিত মেহমানদের বৃত্তান্ত এসেছে কি?'),
  ('bn.bengali', 51, 25, 'যখন তারা তাঁর কাছে উপস্থিত হয়ে বললঃ সালাম, তখন সে বললঃ সালাম। এরা তো অপরিচিত লোক।'),
  ('bn.bengali', 51, 26, 'অতঃপর সে গ্রহে গেল এবং একটি ঘৃতেপক্ক মোটা গোবৎস নিয়ে হাযির হল।'),
  ('bn.bengali', 51, 27, 'সে গোবৎসটি তাদের সামনে রেখে বললঃ তোমরা আহার করছ না কেন?'),
  ('bn.bengali', 51, 28, 'অতঃপর তাদের সম্পর্কে সে মনে মনে ভীত হলঃ তারা বললঃ ভীত হবেন না। তারা তাঁকে একট জ্ঞানীগুণী পুত্র সন্তানের সুসংবাদ দিল।'),
  ('bn.bengali', 51, 29, 'অতঃপর তাঁর স্ত্রী চীৎকার করতে করতে সামনে এল এবং মুখ চাপড়িয়ে বললঃ আমি তো বৃদ্ধা, বন্ধ্যা।'),
  ('bn.bengali', 51, 30, 'তারা বললঃ তোমার পালনকর্তা এরূপই বলেছেন। নিশ্চয় তিনি প্রজ্ঞাময়, সর্বজ্ঞ।'),
  ('bn.bengali', 51, 31, 'ইব্রাহীম বললঃ হে প্রেরিত ফেরেশতাগণ, তোমাদের উদ্দেশ্য কি?'),
  ('bn.bengali', 51, 32, 'তারা বললঃ আমরা এক অপরাধী সম্প্রদায়ের প্রতি প্রেরিত হয়েছি,'),
  ('bn.bengali', 51, 33, 'যাতে তাদের উপর মাটির ঢিলা নিক্ষেপ করি।'),
  ('bn.bengali', 51, 34, 'যা সীমাতিক্রমকারীদের জন্যে আপনার পালনকর্তার কাছে চিহিߦ#2468; আছে।'),
  ('bn.bengali', 51, 35, 'অতঃপর সেখানে যারা ঈমানদার ছিল, আমি তাদেরকে উদ্ধার করলাম।'),
  ('bn.bengali', 51, 36, 'এবং সেখানে একটি গৃহ ব্যতীত কোন মুসলমান আমি পাইনি।'),
  ('bn.bengali', 51, 37, 'যারা যন্ত্রণাদায়ক শাস্তিকে ভয় করে, আমি তাদের জন্যে সেখানে একটি নিদর্শন রেখেছি।'),
  ('bn.bengali', 51, 38, 'এবং নিদর্শন রয়েছে মূসার বৃত্তান্তে; যখন আমি তাকে সুস্পষ্ট প্রমাণসহ ফেরাউনের কাছে প্রেরণ করেছিলাম।'),
  ('bn.bengali', 51, 39, 'অতঃপর সে শক্তিবলে মুখ ফিরিয়ে নিল এবং বললঃ সে হয় যাদুকর, না হয় পাগল।'),
  ('bn.bengali', 51, 40, 'অতঃপর আমি তাকে ও তার সেনাবাহিনীকে পাকড়াও করলাম এবং তাদেরকে সমুদ্রে নিক্ষেপ করলাম। সে ছিল অভিযুক্ত।'),
  ('bn.bengali', 51, 41, 'এবং নিদর্শন রয়েছে তাদের কাহিনীতে; যখন আমি তাদের উপর প্রেরণ করেছিলাম অশুভ বায়ু।'),
  ('bn.bengali', 51, 42, 'এই বায়ু যার উপর দিয়ে প্রবাহিত হয়েছিলঃ তাকেই চুর্ণ-বিচুর্ণ করে দিয়েছিল।'),
  ('bn.bengali', 51, 43, 'আরও নিদর্শন রয়েছে সামূদের ঘটনায়; যখন তাদেরকে বলা হয়েছিল, কিছুকাল মজা লুটে নাও।'),
  ('bn.bengali', 51, 44, 'অতঃপর তারা তাদের পালনকর্তার আদেশ অমান্য করল এবং তাদের প্রতি বজ্রঘাত হল এমতাবস্থায় যে, তারা তা দেখেছিল।'),
  ('bn.bengali', 51, 45, 'অতঃপর তারা দাঁড়াতে সক্ষম হল না এবং কোন প্রতিকারও করতে পারল না।'),
  ('bn.bengali', 51, 46, 'আমি ইতিপূর্বে নূহের সম্প্রদায়কে ধ্বংস করেছি। নিশ্চিতই তারা ছিল পাপাচারী সম্প্রদায়।'),
  ('bn.bengali', 51, 47, 'আমি স্বীয় ক্ষমতাবলে আকাশ নির্মাণ করেছি এবং আমি অবশ্যই ব্যাপক ক্ষমতাশালী।'),
  ('bn.bengali', 51, 48, 'আমি ভূমিকে বিছিয়েছি। আমি কত সুন্দরভাবেই না বিছাতে সক্ষম।'),
  ('bn.bengali', 51, 49, 'আমি প্রত্যেক বস্তু জোড়ায় জোড়ায় সৃষ্টি করেছি, যাতে তোমরা হৃদয়ঙ্গম কর।'),
  ('bn.bengali', 51, 50, 'অতএব, আল্লাহর দিকে ধাবিত হও। আমি তাঁর তরফ থেকে তোমাদের জন্যে সুস্পষ্ট সতর্ককারী।'),
  ('bn.bengali', 51, 51, 'তোমরা আল্লাহর সাথে কোন উপাস্য সাব্যস্ত করো না। আমি তাঁর পক্ষ থেকে তোমাদের জন্য সুস্পষ্ট সতর্ককারী।'),
  ('bn.bengali', 51, 52, 'এমনিভাবে, তাদের পূর্ববর্তীদের কাছে যখনই কোন রসূল আগমন করেছে, তারা বলছেঃ যাদুকর, না হয় উম্মাদ।'),
  ('bn.bengali', 51, 53, 'তারা কি একে অপরকে এই উপদেশই দিয়ে গেছে? বস্তুতঃ ওরা দুষ্ট সম্প্রদায়।'),
  ('bn.bengali', 51, 54, 'অতএব, আপনি ওদের থেকে মুখ ফিরিয়ে নিন। এতে আপনি অপরাধী হবেন না।'),
  ('bn.bengali', 51, 55, 'এবং বোঝাতে থাকুন; কেননা, বোঝানো মুমিনদের উপকারে আসবে।'),
  ('bn.bengali', 51, 56, 'আমার এবাদত করার জন্যই আমি মানব ও জিন জাতি সৃষ্টি করেছি।'),
  ('bn.bengali', 51, 57, 'আমি তাদের কাছে জীবিকা চাই না এবং এটাও চাই না যে, তারা আমাকে আহার্য যোগাবে।'),
  ('bn.bengali', 51, 58, 'আল্লাহ তা’আলাই তো জীবিকাদাতা শক্তির আধার, পরাক্রান্ত।'),
  ('bn.bengali', 51, 59, 'অতএব, এই যালেমদের প্রাপ্য তাই, যা ওদের অতীত সহচরদের প্রাপ্য ছিল। কাজেই ওরা যেন আমার কাছে তা তাড়াতাড়ি না চায়।'),
  ('bn.bengali', 51, 60, 'অতএব, কাফেরদের জন্যে দুর্ভোগ সেই দিনের, যেদিনের প্রতিশ্রুতি ওদেরকে দেয়া হয়েছে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 51, 1, 'By those that winnow with a winnowing'),
  ('en.pickthall', 51, 2, 'And those that bear the burden (of the rain)'),
  ('en.pickthall', 51, 3, 'And those that glide with ease (upon the sea)'),
  ('en.pickthall', 51, 4, 'And those who distribute (blessings) by command,'),
  ('en.pickthall', 51, 5, 'Lo! that wherewith ye are threatened is indeed true,'),
  ('en.pickthall', 51, 6, 'And lo! the judgment will indeed befall.'),
  ('en.pickthall', 51, 7, 'By the heaven full of paths,'),
  ('en.pickthall', 51, 8, 'Lo! ye, forsooth, are of various opinion (concerning the truth).'),
  ('en.pickthall', 51, 9, 'He is made to turn away from it who is (himself) averse.'),
  ('en.pickthall', 51, 10, 'Accursed be the conjecturers'),
  ('en.pickthall', 51, 11, 'Who are careless in an abyss!'),
  ('en.pickthall', 51, 12, 'They ask: When is the Day of Judgment?'),
  ('en.pickthall', 51, 13, '(It is) the day when they will be tormented at the Fire,'),
  ('en.pickthall', 51, 14, '(And it will be said unto them): Taste your torment (which ye inflicted). This is what ye sought to hasten.'),
  ('en.pickthall', 51, 15, 'Lo! those who keep from evil will dwell amid gardens and watersprings,'),
  ('en.pickthall', 51, 16, 'Taking that which their Lord giveth them; for lo! aforetime they were doers of good;'),
  ('en.pickthall', 51, 17, 'They used to sleep but little of the night,'),
  ('en.pickthall', 51, 18, 'And ere the dawning of each day would seek forgiveness,'),
  ('en.pickthall', 51, 19, 'And in their wealth the beggar and the outcast had due share.'),
  ('en.pickthall', 51, 20, 'And in the earth are portents for those whose faith is sure.'),
  ('en.pickthall', 51, 21, 'And (also) in yourselves. Can ye then not see?'),
  ('en.pickthall', 51, 22, 'And in the heaven is your providence and that which ye are promised;'),
  ('en.pickthall', 51, 23, 'And by the Lord of the heavens and the earth, it is the truth, even as (it is true) that ye speak.'),
  ('en.pickthall', 51, 24, 'Hath the story of Abraham\'s honoured guests reached thee (O Muhammad)?'),
  ('en.pickthall', 51, 25, 'When they came in unto him and said: Peace! he answered, Peace! (and thought): Folk unknown (to me).'),
  ('en.pickthall', 51, 26, 'Then he went apart unto his housefolk so that they brought a fatted calf;'),
  ('en.pickthall', 51, 27, 'And he set it before them, saying: Will ye not eat?'),
  ('en.pickthall', 51, 28, 'Then he conceived a fear of them. They said: Fear not! and gave him tidings of (the birth of) a wise son.'),
  ('en.pickthall', 51, 29, 'Then his wife came forward, making moan, and smote her face, and cried: A barren old woman!'),
  ('en.pickthall', 51, 30, 'They said: Even so saith thy Lord. Lo! He is the Wise, the Knower.'),
  ('en.pickthall', 51, 31, '(Abraham) said: And (afterward) what is your errand, O ye sent (from Allah)?'),
  ('en.pickthall', 51, 32, 'They said: Lo! we are sent unto a guilty folk,'),
  ('en.pickthall', 51, 33, 'That we may send upon them stones of clay,'),
  ('en.pickthall', 51, 34, 'Marked by thy Lord for (the destruction of) the wanton.'),
  ('en.pickthall', 51, 35, 'Then we brought forth such believers as were there.'),
  ('en.pickthall', 51, 36, 'But We found there but one house of those surrendered (to Allah).'),
  ('en.pickthall', 51, 37, 'And We left behind therein a portent for those who fear a painful doom.'),
  ('en.pickthall', 51, 38, 'And in Moses (too, there is a portent) when We sent him unto Pharaoh with clear warrant,'),
  ('en.pickthall', 51, 39, 'But he withdrew (confiding) in his might, and said: A wizard or a madman.'),
  ('en.pickthall', 51, 40, 'So We seized him and his hosts and flung them in the sea, for he was reprobate.'),
  ('en.pickthall', 51, 41, 'And in (the tribe of) A\'ad (there is a portent) when we sent the fatal wind against them.'),
  ('en.pickthall', 51, 42, 'It spared naught that it reached, but made it (all) as dust.'),
  ('en.pickthall', 51, 43, 'And in (the tribe of) Thamud (there is a portent) when it was told them: Take your ease awhile.'),
  ('en.pickthall', 51, 44, 'But they rebelled against their Lord\'s decree, and so the thunderbolt overtook them even while they gazed;'),
  ('en.pickthall', 51, 45, 'And they were unable to rise up, nor could they help themselves.'),
  ('en.pickthall', 51, 46, 'And the folk of Noah aforetime. Lo! they were licentious folk.'),
  ('en.pickthall', 51, 47, 'We have built the heaven with might, and We it is Who make the vast extent (thereof).'),
  ('en.pickthall', 51, 48, 'And the earth have We laid out, how gracious is the Spreader (thereof)!'),
  ('en.pickthall', 51, 49, 'And all things We have created by pairs, that haply ye may reflect.'),
  ('en.pickthall', 51, 50, 'Therefor flee unto Allah; lo! I am a plain warner unto you from him.'),
  ('en.pickthall', 51, 51, 'And set not any other god along with Allah; lo! I am a plain warner unto you from Him.'),
  ('en.pickthall', 51, 52, 'Even so there came no messenger unto those before them but they said: A wizard or a madman!'),
  ('en.pickthall', 51, 53, 'Have they handed down (the saying) as an heirloom one unto another? Nay, but they are froward folk.'),
  ('en.pickthall', 51, 54, 'So withdraw from them (O Muhammad), for thou art in no wise blameworthy,'),
  ('en.pickthall', 51, 55, 'And warn, for warning profiteth believers.'),
  ('en.pickthall', 51, 56, 'I created the jinn and humankind only that they might worship Me.'),
  ('en.pickthall', 51, 57, 'I seek no livelihood from them, nor do I ask that they should feed Me.'),
  ('en.pickthall', 51, 58, 'Lo! Allah! He it is that giveth livelihood, the Lord of unbreakable might.'),
  ('en.pickthall', 51, 59, 'And lo! for those who (now) do wrong there is an evil day like unto the evil day (which came for) their likes (of old); so let them not ask Me to hasten on (that day).'),
  ('en.pickthall', 51, 60, 'And woe unto those who disbelieve, from (that) their day which they are promised.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 51, 1, 'By the (Winds) that scatter broadcast;'),
  ('en.yusufali', 51, 2, 'And those that lift and bear away heavy weights;'),
  ('en.yusufali', 51, 3, 'And those that flow with ease and gentleness;'),
  ('en.yusufali', 51, 4, 'And those that distribute and apportion by Command;-'),
  ('en.yusufali', 51, 5, 'Verily that which ye are promised is true;'),
  ('en.yusufali', 51, 6, 'And verily Judgment and Justice must indeed come to pass.'),
  ('en.yusufali', 51, 7, 'By the Sky with (its) numerous Paths,'),
  ('en.yusufali', 51, 8, 'Truly ye are in a doctrine discordant,'),
  ('en.yusufali', 51, 9, 'Through which are deluded (away from the Truth) such as would be deluded.'),
  ('en.yusufali', 51, 10, 'Woe to the falsehood-mongers,-'),
  ('en.yusufali', 51, 11, 'Those who (flounder) heedless in a flood of confusion:'),
  ('en.yusufali', 51, 12, 'They ask, "When will be the Day of Judgment and Justice?"'),
  ('en.yusufali', 51, 13, '(It will be) a Day when they will be tried (and tested) over the Fire!'),
  ('en.yusufali', 51, 14, '"Taste ye your trial! This is what ye used to ask to be hastened!"'),
  ('en.yusufali', 51, 15, 'As to the Righteous, they will be in the midst of Gardens and Springs,'),
  ('en.yusufali', 51, 16, 'Taking joy in the things which their Lord gives them, because, before then, they lived a good life.'),
  ('en.yusufali', 51, 17, 'They were in the habit of sleeping but little by night,'),
  ('en.yusufali', 51, 18, 'And in the hour of early dawn, they (were found) praying for Forgiveness;'),
  ('en.yusufali', 51, 19, 'And in their wealth and possessions (was remembered) the right of the (needy,) him who asked, and him who (for some reason) was prevented (from asking).'),
  ('en.yusufali', 51, 20, 'On the earth are signs for those of assured Faith,'),
  ('en.yusufali', 51, 21, 'As also in your own selves: Will ye not then see?'),
  ('en.yusufali', 51, 22, 'And in heaven is your Sustenance, as (also) that which ye are promised.'),
  ('en.yusufali', 51, 23, 'Then, by the Lord of heaven and earth, this is the very Truth, as much as the fact that ye can speak intelligently to each other.'),
  ('en.yusufali', 51, 24, 'Has the story reached thee, of the honoured guests of Abraham?'),
  ('en.yusufali', 51, 25, 'Behold, they entered his presence, and said: "Peace!" He said, "Peace!" (and thought, "These seem) unusual people."'),
  ('en.yusufali', 51, 26, 'Then he turned quickly to his household, brought out a fatted calf,'),
  ('en.yusufali', 51, 27, 'And placed it before them.. he said, "Will ye not eat?"'),
  ('en.yusufali', 51, 28, '(When they did not eat), He conceived a fear of them. They said, "Fear not," and they gave him glad tidings of a son endowed with knowledge.'),
  ('en.yusufali', 51, 29, 'But his wife came forward (laughing) aloud: she smote her forehead and said: "A barren old woman!"'),
  ('en.yusufali', 51, 30, 'They said, "Even so has thy Lord spoken: and He is full of Wisdom and Knowledge."'),
  ('en.yusufali', 51, 31, '(Abraham) said: "And what, O ye Messengers, is your errand (now)?"'),
  ('en.yusufali', 51, 32, 'They said, "We have been sent to a people (deep) in sin;-'),
  ('en.yusufali', 51, 33, '"To bring on, on them, (a shower of) stones of clay (brimstone),'),
  ('en.yusufali', 51, 34, '"Marked as from thy Lord for those who trespass beyond bounds."'),
  ('en.yusufali', 51, 35, 'Then We evacuated those of the Believers who were there,'),
  ('en.yusufali', 51, 36, 'But We found not there any just (Muslim) persons except in one house:'),
  ('en.yusufali', 51, 37, 'And We left there a Sign for such as fear the Grievous Penalty.'),
  ('en.yusufali', 51, 38, 'And in Moses (was another Sign): Behold, We sent him to Pharaoh, with authority manifest.'),
  ('en.yusufali', 51, 39, 'But (Pharaoh) turned back with his Chiefs, and said, "A sorcerer, or one possessed!"'),
  ('en.yusufali', 51, 40, 'So We took him and his forces, and threw them into the sea; and his was the blame.'),
  ('en.yusufali', 51, 41, 'And in the \'Ad (people) (was another Sign): Behold, We sent against them the devastating Wind:'),
  ('en.yusufali', 51, 42, 'It left nothing whatever that it came up against, but reduced it to ruin and rottenness.'),
  ('en.yusufali', 51, 43, 'And in the Thamud (was another Sign): Behold, they were told, "Enjoy (your brief day) for a little while!"'),
  ('en.yusufali', 51, 44, 'But they insolently defied the Command of their Lord: So the stunning noise (of an earthquake) seized them, even while they were looking on.'),
  ('en.yusufali', 51, 45, 'Then they could not even stand (on their feet), nor could they help themselves.'),
  ('en.yusufali', 51, 46, 'So were the People of Noah before them for they wickedly transgressed.'),
  ('en.yusufali', 51, 47, 'With power and skill did We construct the Firmament: for it is We Who create the vastness of pace.'),
  ('en.yusufali', 51, 48, 'And We have spread out the (spacious) earth: How excellently We do spread out!'),
  ('en.yusufali', 51, 49, 'And of every thing We have created pairs: That ye may receive instruction.'),
  ('en.yusufali', 51, 50, 'Hasten ye then (at once) to Allah: I am from Him a Warner to you, clear and open!'),
  ('en.yusufali', 51, 51, 'And make not another an object of worship with Allah: I am from Him a Warner to you, clear and open!'),
  ('en.yusufali', 51, 52, 'Similarly, no messenger came to the Peoples before them, but they said (of him) in like manner, "A sorcerer, or one possessed"!'),
  ('en.yusufali', 51, 53, 'Is this the legacy they have transmitted, one to another? Nay, they are themselves a people transgressing beyond bounds!'),
  ('en.yusufali', 51, 54, 'So turn away from them: not thine is the blame.'),
  ('en.yusufali', 51, 55, 'But teach (thy Message) for teaching benefits the Believers.'),
  ('en.yusufali', 51, 56, 'I have only created Jinns and men, that they may serve Me.'),
  ('en.yusufali', 51, 57, 'No Sustenance do I require of them, nor do I require that they should feed Me.'),
  ('en.yusufali', 51, 58, 'For Allah is He Who gives (all) Sustenance,- Lord of Power,- Steadfast (for ever).'),
  ('en.yusufali', 51, 59, 'For the Wrong-doers, their portion is like unto the portion of their fellows (of earlier generations): then let them not ask Me to hasten (that portion)!'),
  ('en.yusufali', 51, 60, 'Woe, then, to the Unbelievers, on account of that Day of theirs which they have been promised!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 51, 1, 'Waz-zaariyaati zarwaa'),
  ('en.transliteration', 51, 2, 'Falhaamilaati wiqraa'),
  ('en.transliteration', 51, 3, 'Faljaariyaati yusraa'),
  ('en.transliteration', 51, 4, 'Falmuqassimaati amraa'),
  ('en.transliteration', 51, 5, 'Innamaa too\'adoona la-saadiq'),
  ('en.transliteration', 51, 6, 'Wa innad deena la waaqi\''),
  ('en.transliteration', 51, 7, 'Wassamaaa\'i zaatil hubuk'),
  ('en.transliteration', 51, 8, 'Innakum lafee qawlim mukhtalif'),
  ('en.transliteration', 51, 9, 'Yu\'faku \'anhu man ufik'),
  ('en.transliteration', 51, 10, 'Qutilal kharraasoon'),
  ('en.transliteration', 51, 11, 'Allazeena hum fee ghamratin saahoon'),
  ('en.transliteration', 51, 12, 'Yas\'aloona ayyaana yawmud Deen'),
  ('en.transliteration', 51, 13, 'Yawma hum \'alan naari yuftanoon'),
  ('en.transliteration', 51, 14, 'Zooqoo fitnatakum haa zal lazee kuntum bihee tas ta\'jiloon'),
  ('en.transliteration', 51, 15, 'Innal muttaqeena fee jannaatinw wa \'uyoon'),
  ('en.transliteration', 51, 16, 'Aakhizeena maaa aataahum Rabbuhum; innahum kaanoo qabla zaalika muhsineen'),
  ('en.transliteration', 51, 17, 'kaanoo qaleelam minal laili maa yahja\'oon'),
  ('en.transliteration', 51, 18, 'Wa bilashaari hum yastaghfiroon'),
  ('en.transliteration', 51, 19, 'Wa feee amwaalihim haqqul lissaaa\'ili walmahroom'),
  ('en.transliteration', 51, 20, 'Wa fil ardi aayaatul lilmooqineen'),
  ('en.transliteration', 51, 21, 'Wa feee anfusikum; afalaa tubsiroon'),
  ('en.transliteration', 51, 22, 'Wa fissamaaa\'i rizqukum wa maa too\'adoon'),
  ('en.transliteration', 51, 23, 'Fawa Rabbis samaaa\'i wal ardi innahoo lahaqqum misla maa annakum tantiqoon'),
  ('en.transliteration', 51, 24, 'Hal ataaka hadeesu daifi Ibraaheemal mukrameen'),
  ('en.transliteration', 51, 25, 'Iz dakhaloo \'alaihi faqaaloo salaaman qaala salaamun qawmum munkaroon'),
  ('en.transliteration', 51, 26, 'Faraagha ilaaa ahlihee fajaaa\'a bi\'ijlin sameen'),
  ('en.transliteration', 51, 27, 'Faqarrabahooo ilaihim qaala alaa taakuloon'),
  ('en.transliteration', 51, 28, 'Fa awjasa minhm khee fatan qaaloo laa takhaf wa bashsharoohu bighulaamin \'aleem'),
  ('en.transliteration', 51, 29, 'Fa aqbalatim ra-atuhoo fee sarratin fasakkat wajhahaa wa qaalat \'ajoozun \'aqeem'),
  ('en.transliteration', 51, 30, 'Qaaloo kazaaliki qaala Rabbuki innahoo huwal hakeemul \'aleem'),
  ('en.transliteration', 51, 31, 'Qaala famaa khatbukum ayyuhal mursaloon'),
  ('en.transliteration', 51, 32, 'Qaalooo innaaa ursilnaaa ilaa qawmim mujrimeen'),
  ('en.transliteration', 51, 33, 'Linursila \'alaihim hijaa ratam min teen'),
  ('en.transliteration', 51, 34, 'Musawwamatan \'inda rabbika lilmusrifeen'),
  ('en.transliteration', 51, 35, 'Fa akhrajnaa man kaana feehaa minal mu\'mineen'),
  ('en.transliteration', 51, 36, 'Famaa wajadnaa feehaa ghaira baitim minal muslimeen'),
  ('en.transliteration', 51, 37, 'Wa taraknaa feehaaa aayatal lillazeena yakhaafoonal \'azaabal aleem'),
  ('en.transliteration', 51, 38, 'Wa fee Moosaaa iz arsalnaahu ilaa Fir\'wna bisultaa nim mubeen'),
  ('en.transliteration', 51, 39, 'Fatawalla biruknihee wa qaala saahirun aw majnoon'),
  ('en.transliteration', 51, 40, 'Fa akhaznaahu wa junoo dahoo fanabaznaahum fil yammi wa huwa muleem'),
  ('en.transliteration', 51, 41, 'Wa fee \'Aadin iz arsalnaa \'alaihimur reehal\'aqeem'),
  ('en.transliteration', 51, 42, 'Maa tazaru min shai\'in atat \'alaihi illaa ja\'alat hu karrameem'),
  ('en.transliteration', 51, 43, 'Wa fee Samooda iz qeela lahum tamatta\'\'oo hattaa heen'),
  ('en.transliteration', 51, 44, 'Fa\'ataw \'an amri Rabbihim fa akhazal humus saa\'iqatu wa hum yanzuroon'),
  ('en.transliteration', 51, 45, 'Famas tataa\'oo min qiyaaminw wa maa kaanoo muntasireen'),
  ('en.transliteration', 51, 46, 'Wa qawma Noohim min qablu innahum kaano qawman faasiqeen'),
  ('en.transliteration', 51, 47, 'Wassamaaa\'a banainaa haa bi aydinw wa innaa lamoosi\'oon'),
  ('en.transliteration', 51, 48, 'Wal arda farashnaahaa fani\'mal maahidoon'),
  ('en.transliteration', 51, 49, 'Wa min kulli shai\'in khalaqnaa zawjaini la\'allakum tazakkaroon'),
  ('en.transliteration', 51, 50, 'Fafirrooo ilal laahi innee lakum minhu nazeerum mubeen'),
  ('en.transliteration', 51, 51, 'Wa laa taj\'aloo ma\'al laahi ilaahan aakhara innee lakum minhu nazeerum mubeen'),
  ('en.transliteration', 51, 52, 'Kazaalika maaa atal lazeena min qablihim mir Rasoolin illaa qaaloo saahirun aw majnoon'),
  ('en.transliteration', 51, 53, 'Atawaasaw bih; bal hum qawmun taaghoon'),
  ('en.transliteration', 51, 54, 'Fatawalla \'anhum famaaa anta bimaloom'),
  ('en.transliteration', 51, 55, 'Wa zakkir fa innaz zikraa tanfa\'ul mu\'mineen'),
  ('en.transliteration', 51, 56, 'Wa maa khalaqtul jinna wal insa illaa liya\'budoon'),
  ('en.transliteration', 51, 57, 'Maaa ureedu minhum mir rizqinw wa maaa ureedu anyyut\'imoon'),
  ('en.transliteration', 51, 58, 'Innal laaha Huwar Razzaaqu Zul Quwwatil Mateen'),
  ('en.transliteration', 51, 59, 'Fa inna lillazeena zalamoo zanoobam misla zanoobi ashaabihim falaa yasta\'jiloon'),
  ('en.transliteration', 51, 60, 'Fawailul lillazeena kafaroo miny yawmihimul lazee yoo\'adoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 51, 1, 'قسم ہے ان ہواؤں کی جو (غبار وغیرہ) اڑانے والی ہیں'),
  ('ur.ahmedali', 51, 2, 'پھر ا ن بادلوں کی جو بوجھ (بارش کا) اٹھانے والے ہیں'),
  ('ur.ahmedali', 51, 3, 'پھر ان کشتیوں کی جو نرمی سے چلنے والی ہیں'),
  ('ur.ahmedali', 51, 4, 'پھر ان فرشتوں کی جو حکم کے موافق چیزیں تقسیم کرنے واے ہیں'),
  ('ur.ahmedali', 51, 5, 'بے شک جس قیامت کا تم سے وعدہ کیا جاتا ہےوہ سچ ہے'),
  ('ur.ahmedali', 51, 6, 'اور بے شک اعمال کی جزا ضرور ہونے والی ہے'),
  ('ur.ahmedali', 51, 7, 'آسمان جالی دار کی قسم ہے'),
  ('ur.ahmedali', 51, 8, 'البتہ تم پیچیدہ بات میں پڑے ہوئے ہو'),
  ('ur.ahmedali', 51, 9, 'قرآن سے وہی روکا جاتا ہےجوازل سے گمراہ ہے'),
  ('ur.ahmedali', 51, 10, 'اٹکل پچو باتیں بنانے والے غارت ہوں'),
  ('ur.ahmedali', 51, 11, 'وہ جو غفلت میں بھولے ہوئے ہیں'),
  ('ur.ahmedali', 51, 12, 'پوچھتے ہیں فیصلے کا دن کب ہوگا'),
  ('ur.ahmedali', 51, 13, 'جس دن وہ آگ پر عذاب دیے جائیں گے'),
  ('ur.ahmedali', 51, 14, 'اپنی شرارت کا مزہ چکہو یہی ہے وہ (عذاب) جس کی تم جلدی کرتے تھے'),
  ('ur.ahmedali', 51, 15, 'بے شک پرہیزگار باغات اور چشموں میں ہوں گے'),
  ('ur.ahmedali', 51, 16, 'لے رہے ہوں گے جو کچھ انہیں ان کا رب عطا کرے گا بے شک وہ اس سے پہلے نیکو کار تھے'),
  ('ur.ahmedali', 51, 17, 'وہ رات کے وقت تھوڑا عرصہ سویا کرتے تھے'),
  ('ur.ahmedali', 51, 18, 'اور آخر رات میں مغفرت مانگا کرتے تھے'),
  ('ur.ahmedali', 51, 19, 'اور ان کے مالوں میں سوال کرنے والے اور محتاج کا حق ہوتا تھا'),
  ('ur.ahmedali', 51, 20, 'اور زمین میں یقین کرنے والوں کے لیے نشانیاں ہیں'),
  ('ur.ahmedali', 51, 21, 'اور خود تمہاری نفسوں میں بھی پس کیا تم غور سے نہیں دیکھتے'),
  ('ur.ahmedali', 51, 22, 'اور تمہاری روزی آسمان میں ہے اور جو تم سے وعدہ کیا جاتا ہے'),
  ('ur.ahmedali', 51, 23, 'پس آسمان اور زمین کے مالک کی قسم ہے بے شک یہ (قرآن) برحق ہے جیسا تم باتیں کرتے ہو'),
  ('ur.ahmedali', 51, 24, 'کیا آپ کو ابراھیم کے معزز مہمانوں کی بات پہنچی ہے'),
  ('ur.ahmedali', 51, 25, 'جب کہ وہ اس پر داخل ہوئے پھر انہوں نے سلام کیا ابراھیم نے سوال کا جواب دیا (خیال کیا) کچھ اجنبی سے لوگ ہیں'),
  ('ur.ahmedali', 51, 26, 'پس چپکے سے اپنے گھر والوں کے پاس گیا اور ایک موٹا بچھڑا (تلا ہوا) لایا'),
  ('ur.ahmedali', 51, 27, 'پھر ان کے سامنے لا رکھا فرمایا کیا تم کھاتے نہیں'),
  ('ur.ahmedali', 51, 28, 'پھر ان سے خوف محسوس کیا انہوں نے کہا تم ڈرو نہیں اور انہوں نے اسے ایک دانشمند لڑکے کی خوشخبری دی'),
  ('ur.ahmedali', 51, 29, 'پھر ان کی بیوی شور مچاتی ہوئی آگے بڑھی اور اپنا ماتھا پیٹ کر کہنے لگی کیا بڑھیا بانجھ جنے گی'),
  ('ur.ahmedali', 51, 30, 'انہوں نے کہا تیرے رب نے یونہی فرمایا ہے بے شک وہ حکمت والا دانا ہے'),
  ('ur.ahmedali', 51, 31, 'فرمایا اے رسولو! تمہارا کیا مطلب ہے'),
  ('ur.ahmedali', 51, 32, 'انہوں نے کہا ہم ایک مجرم قوم کی طرف بھیجے گئے ہیں'),
  ('ur.ahmedali', 51, 33, 'تاکہ ہم ان پر مٹی کے پتھر برسائیں'),
  ('ur.ahmedali', 51, 34, 'وہ آپ کے رب کی طرف حدسے بڑھنے والوں کے لیے مقرر ہو چکے ہیں'),
  ('ur.ahmedali', 51, 35, 'پھر ہم نے نکال لیا جو بھی وہا ں ایمان دار تھا'),
  ('ur.ahmedali', 51, 36, 'پھر ہم نے وہاں سوائے مسلمانوں کے ایک گھر کے نہ پایا'),
  ('ur.ahmedali', 51, 37, 'اورہم نے اس واقعہ میں ایسے لوگو ں کے لیے ایک عبرت رہنے دی جو دردناک عذاب سے ڈرتے ہیں'),
  ('ur.ahmedali', 51, 38, 'اور موسیٰ کے قصہ میں بھی عبرت ہے جب کہ ہم نے فرعون کے پا س ایک کھلی دلیل دے کر بھیجا'),
  ('ur.ahmedali', 51, 39, 'سو اس نے مع اپنے ارکانِ سلطنت کے سرتابی کی اور کہا یہ جادوگر یا دیوانہ ہے'),
  ('ur.ahmedali', 51, 40, 'پھر ہم نے اسے اور اس کے لشکروں کو پکڑ لیا پھر ہم نے انہیں سمند رمیں پھینک دیا اور اس نے کام ہی ملامت کا کیا تھا'),
  ('ur.ahmedali', 51, 41, 'اور قوم عاد میں بھی (عبرت ہے) جب ہم نے ان پر سخت آندھی بھیجی'),
  ('ur.ahmedali', 51, 42, 'جو کسی چیز کو نہ چھوڑتی جس پر سے وہ گزرتی مگر اسے بوسیدہ ہڈیوں کی طرح کر دیتی'),
  ('ur.ahmedali', 51, 43, 'اور قوم ثمود میں بھی (عبرت ہے) جب ہ ان سے کہا گیا ایک وقت معین تک کا فائدہ اٹھاؤ'),
  ('ur.ahmedali', 51, 44, 'پھر انہوں نے اپنے رب کے حکم سے سرتابی کی تو ان کو بجلی نے آ پکڑا اوروہ دیکھ رہے تھے'),
  ('ur.ahmedali', 51, 45, 'پھر نہ تو وہ اٹھ ہی سکے اور نہ وہ بدلہ ہی لے سکے'),
  ('ur.ahmedali', 51, 46, 'اور قوم نوح کو اس سے پہلے (ہلاک کر دیا) بے شک وہ نافرمان لوگ تھے'),
  ('ur.ahmedali', 51, 47, 'اور ہم نے آسمان کو قدرت سے بنایا اور ہم وسیع قدرت رہنے والے ہیں'),
  ('ur.ahmedali', 51, 48, 'اورہم نے ہی زمین کو بچھایا پھر ہم کیا خوب بچھانے والے ہیں'),
  ('ur.ahmedali', 51, 49, 'اور ہم نے ہی ہر چیز کا جوڑا پیدا کیا تاکہ تم غور کرو'),
  ('ur.ahmedali', 51, 50, 'پھر الله کی طرف دوڑو بے شک میں تمہارے لیے الله کی طرف سے کھلم کھلا ڈرانے والا ہوں'),
  ('ur.ahmedali', 51, 51, 'اور اللہ کے ساتھ کوئی دوسرا معبود نہ ٹھراؤ بےشک میں تمہارے لئے اس کی طرف سے کھلم کھلا ڈرانے والا ہوں'),
  ('ur.ahmedali', 51, 52, 'اسی طرح ان سے پہلوں کے پا س بھی جب کوئی رسول آیا تو انہوں نے یہی کہا کہ یہ جادوگر یا دیوانہ ہے'),
  ('ur.ahmedali', 51, 53, 'کیا ایک دوسرے سے یہی کہ مرے تھے نہیں بلکہ وہ خود ہی سرکش ہیں'),
  ('ur.ahmedali', 51, 54, 'پس آپ ان کی پرواہ نہ کیجیئے آپ پر کوئی الزام نہیں'),
  ('ur.ahmedali', 51, 55, 'اور نصیحت کرتے رہیئے بے شک ایمان والوں کو نصیحت نفع دیتی ہے'),
  ('ur.ahmedali', 51, 56, 'اور میں نے جن اور انسان کو بنایا ہے تو صرف اپنی بندگی کے لیے'),
  ('ur.ahmedali', 51, 57, 'میں ان سے کوئی روزی نہیں چاہتا ہوں اور نہ ہی چاہتا ہوں کہ وہ مجھے کھلائیں'),
  ('ur.ahmedali', 51, 58, 'بے شک الله ہی بڑا روزی دینے والا زبردست طاقت والا ہے'),
  ('ur.ahmedali', 51, 59, 'پس بے شک ان کے لیے جو ظالم ہیں حصہ ہے جیسا کہ ان کے ساتھیوں کا حصہ تھا تو وہ مجھ سے جلدی کا مطالبہ نہ کریں'),
  ('ur.ahmedali', 51, 60, 'پس ہلاکت ہے ان کے لیے جو کافر ہیں اس دن جس کا ان سے وعدہ کیا جاتا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 51, 1, 'Esip savuran rüzgarlara, yağmur yüklü bulutlara, kolayca süzülen gemiler ve işleri yöneten meleklere and olsun ki, size söz verilen kıyametin kopması şüphesiz gerçektir. Ödeşme günü gelecektir.'),
  ('tr.diyanet', 51, 2, 'Esip savuran rüzgarlara, yağmur yüklü bulutlara, kolayca süzülen gemiler ve işleri yöneten meleklere and olsun ki, size söz verilen kıyametin kopması şüphesiz gerçektir. Ödeşme günü gelecektir.'),
  ('tr.diyanet', 51, 3, 'Esip savuran rüzgarlara, yağmur yüklü bulutlara, kolayca süzülen gemiler ve işleri yöneten meleklere and olsun ki, size söz verilen kıyametin kopması şüphesiz gerçektir. Ödeşme günü gelecektir.'),
  ('tr.diyanet', 51, 4, 'Esip savuran rüzgarlara, yağmur yüklü bulutlara, kolayca süzülen gemiler ve işleri yöneten meleklere and olsun ki, size söz verilen kıyametin kopması şüphesiz gerçektir. Ödeşme günü gelecektir.'),
  ('tr.diyanet', 51, 5, 'Esip savuran rüzgarlara, yağmur yüklü bulutlara, kolayca süzülen gemiler ve işleri yöneten meleklere and olsun ki, size söz verilen kıyametin kopması şüphesiz gerçektir. Ödeşme günü gelecektir.'),
  ('tr.diyanet', 51, 6, 'Esip savuran rüzgarlara, yağmur yüklü bulutlara, kolayca süzülen gemiler ve işleri yöneten meleklere and olsun ki, size söz verilen kıyametin kopması şüphesiz gerçektir. Ödeşme günü gelecektir.'),
  ('tr.diyanet', 51, 7, 'İçinde yörüngeler bulunan göğe and olsun ki, ey inkarcılar, siz, şüphesiz aykırı görüştesiniz.'),
  ('tr.diyanet', 51, 8, 'İçinde yörüngeler bulunan göğe and olsun ki, ey inkarcılar, siz, şüphesiz aykırı görüştesiniz.'),
  ('tr.diyanet', 51, 9, 'Bundan, dönebilecek kimseler döndürülür.'),
  ('tr.diyanet', 51, 10, 'Yalancılığı itiyat edinenlerin, bilgisizliğe saplanıp kalanların canları çıksın!'),
  ('tr.diyanet', 51, 11, 'Yalancılığı itiyat edinenlerin, bilgisizliğe saplanıp kalanların canları çıksın!'),
  ('tr.diyanet', 51, 12, 'İşlerin karşılık göreceği günün zamanını sorarlar.'),
  ('tr.diyanet', 51, 13, 'O, kendilerinin ateşte azap görecekleri gündür.'),
  ('tr.diyanet', 51, 14, 'Onlara: "Azabınızı tadın; işte acele beklediğiniz bu idi" denir.'),
  ('tr.diyanet', 51, 15, 'Doğrusu, Allah\'a karşı gelmekten sakınanlar, Rablerinin kendilerine verdiğini almış olarak bahçelerde ve pınar başlarındadırlar. Çünkü onlar, bundan önce iyi davrananlardı.'),
  ('tr.diyanet', 51, 16, 'Doğrusu, Allah\'a karşı gelmekten sakınanlar, Rablerinin kendilerine verdiğini almış olarak bahçelerde ve pınar başlarındadırlar. Çünkü onlar, bundan önce iyi davrananlardı.'),
  ('tr.diyanet', 51, 17, 'Onlar, geceleri az uyuyanlardı.'),
  ('tr.diyanet', 51, 18, 'Seher vakitlerinde bağışlanma dilerlerdi.'),
  ('tr.diyanet', 51, 19, 'Onların mallarında muhtaç ve yoksullar için bir hak vardı, onu verirlerdi.'),
  ('tr.diyanet', 51, 20, 'Kesin olarak inananlara, yeryüzünde ve kendi içinizde Allah\'ın varlığına nice deliller vardır; görmez misiniz?'),
  ('tr.diyanet', 51, 21, 'Kesin olarak inananlara, yeryüzünde ve kendi içinizde Allah\'ın varlığına nice deliller vardır; görmez misiniz?'),
  ('tr.diyanet', 51, 22, 'Rızkınız da, size söz verilen azap da yukarıdan gelir.'),
  ('tr.diyanet', 51, 23, 'Göğün ve yerin Rabbine and olsun ki bu, sizin konuşmanız kadar kesin ve gerçektir.'),
  ('tr.diyanet', 51, 24, 'İbrahim\'in ikram edilmiş konuklarının haberi sana geldi mi?'),
  ('tr.diyanet', 51, 25, 'Onlar, İbrahim\'in yanına girip: "Selam sana" demişlerdi, İbrahim de: "Selam size" demişti; içinden de, onların "tanınmamış bir topluluk" olduğunu geçirmişti.'),
  ('tr.diyanet', 51, 26, 'Hemen ailesine giderek semiz bir buzağı getirmiş, onların önüne sürüp: "Yemez misiniz?" demişti.'),
  ('tr.diyanet', 51, 27, 'Hemen ailesine giderek semiz bir buzağı getirmiş, onların önüne sürüp: "Yemez misiniz?" demişti.'),
  ('tr.diyanet', 51, 28, '(Yemediklerini görünce) onlardan endişeye düştü; "Korkma" dediler ve ona bilgin bir oğul sahibi olacağını müjdelediler.'),
  ('tr.diyanet', 51, 29, 'Bunun üzerine karısı hayretle seslenerek geldi, elleriyle yüzünü kapayarak: "kısır bir kocakarı!" dedi.'),
  ('tr.diyanet', 51, 30, 'Melekler: "Bu böyledir, Rabbin söylemiştir; doğrusu O, Hakim olandır, bilendir" dediler.'),
  ('tr.diyanet', 51, 31, 'İbrahim: "Ey Elçiler! Göreviniz nedir?" dedi.'),
  ('tr.diyanet', 51, 32, 'Elçiler: "Suçlu bir milletin üzerine, Rabbinin katından işaretli olarak, aşırı gidenlere mahsus sert taşlar göndermekle görevlendirildik" dediler.'),
  ('tr.diyanet', 51, 33, 'Elçiler: "Suçlu bir milletin üzerine, Rabbinin katından işaretli olarak, aşırı gidenlere mahsus sert taşlar göndermekle görevlendirildik" dediler.'),
  ('tr.diyanet', 51, 34, 'Elçiler: "Suçlu bir milletin üzerine, Rabbinin katından işaretli olarak, aşırı gidenlere mahsus sert taşlar göndermekle görevlendirildik" dediler.'),
  ('tr.diyanet', 51, 35, 'Bunun üzerine, suçlu milletin arasında bulunan müminleri çıkardık.'),
  ('tr.diyanet', 51, 36, 'Zaten orada, kendini Allah\'a vermiş sadece bir tek ev halkı bulduk.'),
  ('tr.diyanet', 51, 37, 'Can yakıcı azabdan korkanlar için, o beldede bir işaret, bir kalıntı bıraktık.'),
  ('tr.diyanet', 51, 38, 'Musa\'nın başından geçenlerde de ibret vardır: Onu apaçık delille Firavun\'a gönderdik.'),
  ('tr.diyanet', 51, 39, 'Firavun, erkaniyle birlikte hakdan yüz çevirdi; "sihirbazdır veya delidir" dedi.'),
  ('tr.diyanet', 51, 40, 'Sonunda onu ve ordularını yakalayıp denize attık. O, kınanmayı haketmişti.'),
  ('tr.diyanet', 51, 41, 'Ad milletinin başından geçende de ibret vardır: Onların üzerine, uğradığı her şeyi bırakmayıp toza çeviren kuru bir rüzgar gönderdik.'),
  ('tr.diyanet', 51, 42, 'Ad milletinin başından geçende de ibret vardır: Onların üzerine, uğradığı her şeyi bırakmayıp toza çeviren kuru bir rüzgar gönderdik.'),
  ('tr.diyanet', 51, 43, 'Semud milletinin başına gelende de ibret vardır: Onlara, "Bir süreye kadar zevklenin" denmişti.'),
  ('tr.diyanet', 51, 44, 'Onlar Rablerinin buyruğundan çıkmışlardı; bunun üzerine kendilerini gözleri göre göre yıldırım çarptı.'),
  ('tr.diyanet', 51, 45, 'Ayağa kalkacak güçleri kalmadı, yardım da görmediler.'),
  ('tr.diyanet', 51, 46, 'Daha önce de Nuh milletini cezalandırmıştık. Çünkü onlar da yoldan çıkmış bir milletti.'),
  ('tr.diyanet', 51, 47, 'Göğü, gücümüzle Biz kurduk; şüphesiz biz onu genişleticiyiz.'),
  ('tr.diyanet', 51, 48, 'Yeryüzünü biz yayıp döşedik: Ne güzel döşeyiciyiz!'),
  ('tr.diyanet', 51, 49, 'İbret alasınız diye her şeyi çift çift yaratmışızdır.'),
  ('tr.diyanet', 51, 50, 'De ki: "Öyleyse Allah\'a koşusun; doğrusu ben sizi O\'nun azabı ile açıkça uyaranım."'),
  ('tr.diyanet', 51, 51, '"Allah\'ın yanında başkasını tanrı kılmayın; doğrusu ben sizi O\'nun azabı ile açıkça uyaranım."'),
  ('tr.diyanet', 51, 52, 'Onlardan öncekilere, herhangi bir peygamber gelince: "sihirbazdır" veya "Delidir" derlerdi.'),
  ('tr.diyanet', 51, 53, 'Öncekiler sonrakilere böyle mi vasiyet ettiler? Hayır; bunlar azgın bir millettir.'),
  ('tr.diyanet', 51, 54, 'Onlardan yüz çevir; sen kınanacak değilsin.'),
  ('tr.diyanet', 51, 55, 'Öğüt ver; doğrusu öğüt inananlara fayda verir.'),
  ('tr.diyanet', 51, 56, 'Cinleri ve insanları ancak Bana kulluk etmeleri için yaratmışımdır.'),
  ('tr.diyanet', 51, 57, 'Onlardan bir rızık istemem; Beni doyurmalarını da istemem.'),
  ('tr.diyanet', 51, 58, 'Şüphesiz rızıklandıran da, güç ve kuvvet sahibi olan da Allah\'tır.'),
  ('tr.diyanet', 51, 59, 'Zulmedenlerin, geçmiş arkadaşlarının suçlarına benzer suçları vardır; cezalarını Benden acele istemesinler.'),
  ('tr.diyanet', 51, 60, 'Söz verilen günün azabından vay o inkar edenlere!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 51, 1, 'Demi (angin) yang menerbangkan debu dengan kuat.'),
  ('id.indonesian', 51, 2, 'dan awan yang mengandung hujan,'),
  ('id.indonesian', 51, 3, 'dan kapal-kapal yang berlayar dengan mudah.'),
  ('id.indonesian', 51, 4, 'dan (malaikat-malaikat) yang membagi-bagi urusan,'),
  ('id.indonesian', 51, 5, 'sesungguhnya apa yang dijanjikan kepadamu pasti benar.'),
  ('id.indonesian', 51, 6, 'dan sesungguhnya (hari) pembalasan pasti terjadi.'),
  ('id.indonesian', 51, 7, 'Demi langit yang mempunyai jalan-jalan,'),
  ('id.indonesian', 51, 8, 'sesungguhnya kamu benar-benar dalam keadaan berbeda pendapat,'),
  ('id.indonesian', 51, 9, 'dipalingkan daripadanya (Rasul dan Al-Quran) orang yang dipalingkan.'),
  ('id.indonesian', 51, 10, 'Terkutuklah orang-orang yang banyak berdusta,'),
  ('id.indonesian', 51, 11, '(yaitu) orang-orang yang terbenam dalam kebodohan yang lalai,'),
  ('id.indonesian', 51, 12, 'mereka bertanya: "Bilakah hari pembalasan itu?"'),
  ('id.indonesian', 51, 13, '(Hari pembalasan itu) ialah pada hari ketika mereka diazab di atas api neraka.'),
  ('id.indonesian', 51, 14, '(Dikatakan kepada mereka): "Rasakanlah azabmu itu. Inilah azab yang dulu kamu minta untuk disegerakan".'),
  ('id.indonesian', 51, 15, 'Sesungguhnya orang-orang yang bertakwa itu berada dalam taman-taman (surga) dan mata air-mata air,'),
  ('id.indonesian', 51, 16, 'sambil menerima segala pemberian Rabb mereka. Sesungguhnya mereka sebelum itu di dunia adalah orang-orang yang berbuat kebaikan.'),
  ('id.indonesian', 51, 17, 'Di dunia mereka sedikit sekali tidur diwaktu malam.'),
  ('id.indonesian', 51, 18, 'Dan selalu memohonkan ampunan diwaktu pagi sebelum fajar.'),
  ('id.indonesian', 51, 19, 'Dan pada harta-harta mereka ada hak untuk orang miskin yang meminta dan orang miskin yang tidak mendapat bagian.'),
  ('id.indonesian', 51, 20, 'Dan di bumi itu terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang yakin.'),
  ('id.indonesian', 51, 21, 'dan (juga) pada dirimu sendiri. Maka apakah kamu tidak memperhatikan?'),
  ('id.indonesian', 51, 22, 'Dan di langit terdapat (sebab-sebab) rezekimu dan terdapat (pula) apa yang dijanjikan kepadamu.'),
  ('id.indonesian', 51, 23, 'Maka demi Tuhan langit dan bumi, sesungguhnya yang dijanjikan itu adalah benar-benar (akan terjadi) seperti perkataan yang kamu ucapkan.'),
  ('id.indonesian', 51, 24, 'Sudahkah sampai kepadamu (Muhammad) cerita tentang tamu Ibrahim (yaitu malaikat-malaikat) yang dimuliakan?'),
  ('id.indonesian', 51, 25, '(Ingatlah) ketika mereka masuk ke tempatnya lalu mengucapkan: "Salaamun". Ibrahim menjawab: "Salaamun (kamu) adalah orang-orang yang tidak dikenal".'),
  ('id.indonesian', 51, 26, 'Maka dia pergi dengan diam-diam menemui keluarganya, kemudian dibawanya daging anak sapi gemuk.'),
  ('id.indonesian', 51, 27, 'Lalu dihidangkannya kepada mereka. Ibrahim lalu berkata: "Silahkan anda makan".'),
  ('id.indonesian', 51, 28, '(Tetapi mereka tidak mau makan), karena itu Ibrahim merasa takut terhadap mereka. Mereka berkata: "Janganlah kamu takut", dan mereka memberi kabar gembira kepadanya dengan (kelahiran) seorang anak yang alim (Ishak).'),
  ('id.indonesian', 51, 29, 'Kemudian isterinya datang memekik lalu menepuk mukanya sendiri seraya berkata: "(Aku adalah) seorang perempuan tua yang mandul".'),
  ('id.indonesian', 51, 30, 'Mereka berkata: "Demikianlah Tuhanmu memfirmankan" Sesungguhnya Dialah yang Maha Bijaksana lagi Maha Mengetahui.'),
  ('id.indonesian', 51, 31, 'Ibrahim bertanya: "Apakah urusanmu hai para utusan?"'),
  ('id.indonesian', 51, 32, 'Mereka menjawab: "Sesungguhnya kami diutus kepada kaum yang berdosa (kaum Luth),'),
  ('id.indonesian', 51, 33, 'agar kami timpakan kepada mereka batu-batu dari tanah,'),
  ('id.indonesian', 51, 34, 'yang ditandai di sisi Tuhanmu untuk membinasakan orang-orang yang melampaui batas".'),
  ('id.indonesian', 51, 35, 'Lalu Kami keluarkan orang-orang yang beriman yang berada di negeri kaum Luth itu.'),
  ('id.indonesian', 51, 36, 'Dan Kami tidak mendapati negeri itu, kecuali sebuah rumah dari orang yang berserah diri.'),
  ('id.indonesian', 51, 37, 'Dan Kami tinggalkan pada negeri itu suatu tanda bagi orang-orang yang takut kepada siksa yang pedih.'),
  ('id.indonesian', 51, 38, 'Dan juga pada Musa (terdapat tanda-tanda kekuasaan Allah) ketika Kami mengutusnya kepada Fir\'aun dengan membawa mukjizat yang nyata.'),
  ('id.indonesian', 51, 39, 'Maka dia (Fir\'aun) berpaling (dari iman) bersama tentaranya dan berkata: "Dia adalah seorang tukang sihir atau seorang gila".'),
  ('id.indonesian', 51, 40, 'Maka Kami siksa dia dan tentaranya lalu Kami lemparkan mereka ke dalam laut, sedang dia melakukan pekerjaan yang tercela.'),
  ('id.indonesian', 51, 41, 'Dan juga pada (kisah) Aad ketika Kami kirimkan kepada mereka angin yang membinasakan,'),
  ('id.indonesian', 51, 42, 'angin itu tidak membiarkan satupun yang dilaluinya, melainkan dijadikannya seperti serbuk.'),
  ('id.indonesian', 51, 43, 'Dan pada (kisah) kaum Tsamud ketika dikatakan kepada mereka: "Bersenang-senanglah kalian sampai suatu waktu".'),
  ('id.indonesian', 51, 44, 'Maka mereka berlaku angkuh terhadap perintah Tuhannya, lalu mereka disambar petir dan mereka melihatnya.'),
  ('id.indonesian', 51, 45, 'Maka mereka sekali-kali tidak dapat bangun dan tidak pula mendapat pertolongan,'),
  ('id.indonesian', 51, 46, 'dan (Kami membinasakan) kaum Nuh sebelum itu. Sesungguhnya mereka adalah kaum yang fasik.'),
  ('id.indonesian', 51, 47, 'Dan langit itu Kami bangun dengan kekuasaan (Kami) dan sesungguhnya Kami benar-benar berkuasa'),
  ('id.indonesian', 51, 48, 'Dan bumi itu Kami hamparkan, maka sebaik-baik yang menghamparkan (adalah Kami).'),
  ('id.indonesian', 51, 49, 'Dan segala sesuatu Kami ciptakan berpasang-pasangan supaya kamu mengingat kebesaran Allah.'),
  ('id.indonesian', 51, 50, 'Maka segeralah kembali kepada (mentaati) Allah. Sesungguhnya aku seorang pemberi peringatan yang nyata dari Allah untukmu.'),
  ('id.indonesian', 51, 51, 'Dan janganlah kamu mengadakan tuhan yang lain disamping Allah. Sesungguhnya aku seorang pemberi peringatan yang nyata dari Allah untukmu.'),
  ('id.indonesian', 51, 52, 'Demikianlah tidak seorang rasulpun yang datang kepada orang-orang yang sebelum mereka, melainkan mereka mengatakan: "Dia adalah seorang tukang sihir atau seorang gila".'),
  ('id.indonesian', 51, 53, 'Apakah mereka saling berpesan tentang apa yang dikatakan itu. Sebenarnya mereka adalah kaum yang melampaui batas.'),
  ('id.indonesian', 51, 54, 'Maka berpalinglah kamu dari mereka dan kamu sekali-kali tidak tercela.'),
  ('id.indonesian', 51, 55, 'Dan tetaplah memberi peringatan, karena sesungguhnya peringatan itu bermanfaat bagi orang-orang yang beriman.'),
  ('id.indonesian', 51, 56, 'Dan aku tidak menciptakan jin dan manusia melainkan supaya mereka mengabdi kepada-Ku.'),
  ('id.indonesian', 51, 57, 'Aku tidak menghendaki rezeki sedikitpun dari mereka dan Aku tidak menghendaki supaya mereka memberi-Ku makan.'),
  ('id.indonesian', 51, 58, 'Sesungguhnya Allah Dialah Maha Pemberi rezeki Yang mempunyai Kekuatan lagi Sangat Kokoh.'),
  ('id.indonesian', 51, 59, 'Maka sesungguhnya untuk orang-orang zalim ada bagian (siksa) seperti bahagian teman mereka (dahulu); maka janganlah mereka meminta kepada-Ku untuk menyegerakannya.'),
  ('id.indonesian', 51, 60, 'Maka kecelakaanlah bagi orang-orang yang kafir pada hari yang diancamkan kepada mereka.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 52, 1, 'By the mount'),
  ('en.sahih', 52, 2, 'And [by] a Book inscribed'),
  ('en.sahih', 52, 3, 'In parchment spread open'),
  ('en.sahih', 52, 4, 'And [by] the frequented House'),
  ('en.sahih', 52, 5, 'And [by] the heaven raised high'),
  ('en.sahih', 52, 6, 'And [by] the sea filled [with fire],'),
  ('en.sahih', 52, 7, 'Indeed, the punishment of your Lord will occur.'),
  ('en.sahih', 52, 8, 'Of it there is no preventer.'),
  ('en.sahih', 52, 9, 'On the Day the heaven will sway with circular motion'),
  ('en.sahih', 52, 10, 'And the mountains will pass on, departing -'),
  ('en.sahih', 52, 11, 'Then woe, that Day, to the deniers,'),
  ('en.sahih', 52, 12, 'Who are in [empty] discourse amusing themselves.'),
  ('en.sahih', 52, 13, 'The Day they are thrust toward the fire of Hell with a [violent] thrust, [its angels will say],'),
  ('en.sahih', 52, 14, '"This is the Fire which you used to deny.'),
  ('en.sahih', 52, 15, 'Then is this magic, or do you not see?'),
  ('en.sahih', 52, 16, '[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do."'),
  ('en.sahih', 52, 17, 'Indeed, the righteous will be in gardens and pleasure,'),
  ('en.sahih', 52, 18, 'Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire.'),
  ('en.sahih', 52, 19, '[They will be told], "Eat and drink in satisfaction for what you used to do."'),
  ('en.sahih', 52, 20, 'They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes.'),
  ('en.sahih', 52, 21, 'And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained.'),
  ('en.sahih', 52, 22, 'And We will provide them with fruit and meat from whatever they desire.'),
  ('en.sahih', 52, 23, 'They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin.'),
  ('en.sahih', 52, 24, 'There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected.'),
  ('en.sahih', 52, 25, 'And they will approach one another, inquiring of each other.'),
  ('en.sahih', 52, 26, 'They will say, "Indeed, we were previously among our people fearful [of displeasing Allah].'),
  ('en.sahih', 52, 27, 'So Allah conferred favor upon us and protected us from the punishment of the Scorching Fire.'),
  ('en.sahih', 52, 28, 'Indeed, we used to supplicate Him before. Indeed, it is He who is the Beneficent, the Merciful."'),
  ('en.sahih', 52, 29, 'So remind [O Muhammad], for you are not, by the favor of your Lord, a soothsayer or a madman.'),
  ('en.sahih', 52, 30, 'Or do they say [of you], "A poet for whom we await a misfortune of time?"'),
  ('en.sahih', 52, 31, 'Say, "Wait, for indeed I am, with you, among the waiters."'),
  ('en.sahih', 52, 32, 'Or do their minds command them to [say] this, or are they a transgressing people?'),
  ('en.sahih', 52, 33, 'Or do they say, "He has made it up"? Rather, they do not believe.'),
  ('en.sahih', 52, 34, 'Then let them produce a statement like it, if they should be truthful.'),
  ('en.sahih', 52, 35, 'Or were they created by nothing, or were they the creators [of themselves]?'),
  ('en.sahih', 52, 36, 'Or did they create the heavens and the earth? Rather, they are not certain.'),
  ('en.sahih', 52, 37, 'Or have they the depositories [containing the provision] of your Lord? Or are they the controllers [of them]?'),
  ('en.sahih', 52, 38, 'Or have they a stairway [into the heaven] upon which they listen? Then let their listener produce a clear authority.'),
  ('en.sahih', 52, 39, 'Or has He daughters while you have sons?'),
  ('en.sahih', 52, 40, 'Or do you, [O Muhammad], ask of them a payment, so they are by debt burdened down?'),
  ('en.sahih', 52, 41, 'Or have they [knowledge of] the unseen, so they write [it] down?'),
  ('en.sahih', 52, 42, 'Or do they intend a plan? But those who disbelieve - they are the object of a plan.'),
  ('en.sahih', 52, 43, 'Or have they a deity other than Allah? Exalted is Allah above whatever they associate with Him.'),
  ('en.sahih', 52, 44, 'And if they were to see a fragment from the sky falling, they would say, "[It is merely] clouds heaped up."'),
  ('en.sahih', 52, 45, 'So leave them until they meet their Day in which they will be struck insensible -'),
  ('en.sahih', 52, 46, 'The Day their plan will not avail them at all, nor will they be helped.'),
  ('en.sahih', 52, 47, 'And indeed, for those who have wronged is a punishment before that, but most of them do not know.'),
  ('en.sahih', 52, 48, 'And be patient, [O Muhammad], for the decision of your Lord, for indeed, you are in Our eyes. And exalt [Allah] with praise of your Lord when you arise.'),
  ('en.sahih', 52, 49, 'And in a part of the night exalt Him and after [the setting of] the stars.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 52, 1, 'কসম তূরপর্বতের,'),
  ('bn.bengali', 52, 2, 'এবং লিখিত কিতাবের,'),
  ('bn.bengali', 52, 3, 'প্রশস্ত পত্রে,'),
  ('bn.bengali', 52, 4, 'কসম বায়তুল-মামুর তথা আবাদ গৃহের,'),
  ('bn.bengali', 52, 5, 'এবং সমুন্নত ছাদের,'),
  ('bn.bengali', 52, 6, 'এবং উত্তাল সমুদ্রের,'),
  ('bn.bengali', 52, 7, 'আপনার পালনকর্তার শাস্তি অবশ্যম্ভাবী,'),
  ('bn.bengali', 52, 8, 'তা কেউ প্রতিরোধ করতে পারবে না।'),
  ('bn.bengali', 52, 9, 'সেদিন আকাশ প্রকম্পিত হবে প্রবলভাবে।'),
  ('bn.bengali', 52, 10, 'এবং পর্বতমালা হবে চলমান,'),
  ('bn.bengali', 52, 11, 'সেদিন মিথ্যারোপকারীদের দুর্ভোগ হবে,'),
  ('bn.bengali', 52, 12, 'যারা ক্রীড়াচ্ছলে মিছেমিছি কথা বানায়।'),
  ('bn.bengali', 52, 13, 'সেদিন তোমাদেরকে জাহান্নামের অগ্নির দিকে ধাক্কা মেরে মেরে নিয়ে যাওয়া হবে।'),
  ('bn.bengali', 52, 14, 'এবং বলা হবেঃ এই সেই অগ্নি, যাকে তোমরা মিথ্যা বলতে,'),
  ('bn.bengali', 52, 15, 'এটা কি জাদু, না তোমরা চোখে দেখছ না?'),
  ('bn.bengali', 52, 16, 'এতে প্রবেশ কর অতঃপর তোমরা সবর কর অথবা না কর, উভয়ই তোমাদের জন্য সমান। তোমরা যা করতে তোমাদেরকে কেবল তারই প্রতিফল দেয়া হবে।'),
  ('bn.bengali', 52, 17, 'নিশ্চয় খোদাভীরুরা থাকবে জান্নাতে ও নেয়ামতে।'),
  ('bn.bengali', 52, 18, 'তারা উপভোগ করবে যা তাদের পালনকর্তা তাদের দেবেন এবং তিনি জাহান্নামের আযাব থেকে তাদেরকে রক্ষা করবেন।'),
  ('bn.bengali', 52, 19, 'তাদেরকে বলা হবেঃ তোমরা যা করতে তার প্রতিফলস্বরূপ তোমরা তৃপ্ত হয়ে পানাহার কর।'),
  ('bn.bengali', 52, 20, 'তারা শ্রেণীবদ্ধ সিংহাসনে হেলান দিয়ে বসবে। আমি তাদেরকে আয়তলোচনা হুরদের সাথে বিবাহবন্ধনে আবদ্ধ করে দেব।'),
  ('bn.bengali', 52, 21, 'যারা ঈমানদার এবং যাদের সন্তানরা ঈমানে তাদের অনুগামী, আমি তাদেরকে তাদের পিতৃপুরুষদের সাথে মিলিত করে দেব এবং তাদের আমল বিন্দুমাত্রও হ্রাস করব না। প্রত্যেক ব্যক্তি নিজ কৃত কর্মের জন্য দায়ী।'),
  ('bn.bengali', 52, 22, 'আমি তাদেরকে দেব ফল-মূল এবং মাংস যা তারা চাইবে।'),
  ('bn.bengali', 52, 23, 'সেখানে তারা একে অপরকে পানপাত্র দেবে; যাতে অসার বকাবকি নেই এবং পাপকর্মও নেই।'),
  ('bn.bengali', 52, 24, 'সুরক্ষিত মোতিসদৃশ কিশোররা তাদের সেবায় ঘুরাফেরা করবে।'),
  ('bn.bengali', 52, 25, 'তারা একে অপরের দিকে মুখ করে জিজ্ঞাসাবাদ করবে।'),
  ('bn.bengali', 52, 26, 'তারা বলবেঃ আমরা ইতিপূর্বে নিজেদের বাসগৃহে ভীত-কম্পিত ছিলাম।'),
  ('bn.bengali', 52, 27, 'অতঃপর আল্লাহ আমাদের প্রতি অনুগ্রহ করেছেন এবং আমাদেরকে আগুনের শাস্তি থেকে রক্ষা করেছেন।'),
  ('bn.bengali', 52, 28, 'আমরা পূর্বেও আল্লাহকে ডাকতাম। তিনি সৌজন্যশীল, পরম দয়ালু।'),
  ('bn.bengali', 52, 29, 'অতএব, আপনি উপদেশ দান করুন। আপনার পালনকর্তার কৃপায় আপনি অতীন্দ্রিয়বাদী নন এবং উম্মাদও নন।'),
  ('bn.bengali', 52, 30, 'তারা কি বলতে চায়ঃ সে একজন কবি আমরা তার মৃত্যু-দুর্ঘটনার প্রতীক্ষা করছি।'),
  ('bn.bengali', 52, 31, 'বলুনঃ তোমরা প্রতীক্ষা কর, আমিও তোমাদের সাথে প্রতীক্ষারত আছি।'),
  ('bn.bengali', 52, 32, 'তাদের বুদ্ধি কি এ বিষয়ে তাদেরকে আদেশ করে, না তারা সীমালংঘনকারী সম্প্রদায়?'),
  ('bn.bengali', 52, 33, 'না তারা বলেঃ এই কোরআন সে নিজে রচনা করেছে? বরং তারা অবিশ্বাসী।'),
  ('bn.bengali', 52, 34, 'যদি তারা সত্যবাদী হয়ে থাকে, তবেএর অনুরূপ কোন রচনা উপস্থিত করুক।'),
  ('bn.bengali', 52, 35, 'তারা কি আপনা-আপনিই সৃজিত হয়ে গেছে, না তারা নিজেরাই স্রষ্টা?'),
  ('bn.bengali', 52, 36, 'না তারা নভোমন্ডল ও ভূমন্ডল সৃষ্টি করেছে? বরং তারা বিশ্বাস করে না।'),
  ('bn.bengali', 52, 37, 'তাদের কাছে কি আপনার পালনকর্তার ভান্ডার রয়েছে, না তারাই সবকিছুর তত্ত্বাবধায়ক?'),
  ('bn.bengali', 52, 38, 'না তাদের কোন সিঁড়ি আছে, যাতে আরোহণ করে তারা শ্রবণ করে? থাকলে তাদের শ্রোতা সুস্পষ্ট প্রমাণ উপস্থিত করুক।'),
  ('bn.bengali', 52, 39, 'না তার কন্যা-সন্তান আছে আর তোমাদের আছে পুত্রসন্তান?'),
  ('bn.bengali', 52, 40, 'না আপনি তাদের কাছে পারিশ্রমিক চান যে, তাদের উপর জরিমানার বোঝা চেপে বসে?'),
  ('bn.bengali', 52, 41, 'না তাদের কাছে অদৃশ্য বিষয়ের জ্ঞান আছে যে, তারাই তা লিপিবদ্ধ করে?'),
  ('bn.bengali', 52, 42, 'না তারা চক্রান্ত করতে চায়? অতএব যারা কাফের, তারই চক্রান্তের শিকার হবে।'),
  ('bn.bengali', 52, 43, 'না তাদের আল্লাহ তা’আলা ব্যতীত কোন উপাস্য আছে? তারা যাকে শরীক করে, আল্লাহ তা’আলা তা থেকে পবিত্র।'),
  ('bn.bengali', 52, 44, 'তারা যদি আকাশের কোন খন্ডকে পতিত হতে দেখে, তবে বলে এটা তো পুঞ্জীভুত মেঘ।'),
  ('bn.bengali', 52, 45, 'তাদেরকে ছেড়ে দিন সেদিন পর্যন্ত, যেদিন তাদের উপর বজ্রাঘাত পতিত হবে।'),
  ('bn.bengali', 52, 46, 'সেদিন তাদের চক্রান্ত তাদের কোন উপকারে আসবে না এবং তারা সাহায্যপ্রাপ্তও হবে না।'),
  ('bn.bengali', 52, 47, 'গোনাহগারদের জন্যে এছাড়া আরও শাস্তি রয়েছে, কিন্তু তাদের অধিকাংশই তা জানে না।'),
  ('bn.bengali', 52, 48, 'আপনি আপনার পালনকর্তার নির্দেশের অপেক্ষায় সবর করুন। আপনি আমার দৃষ্টির সামনে আছেন এবং আপনি আপনার পালনকর্তꦣ2494;র সপ্রশংস পবিত্রতা ঘোষণা করুন যখন আপনি গাত্রোত্থান করেন।'),
  ('bn.bengali', 52, 49, 'এবং রাত্রির কিছু অংশে এবং তারকা অস্তমিত হওয়ার সময় তাঁর পবিত্রতা ঘোষণা করুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 52, 1, 'By the Mount,'),
  ('en.pickthall', 52, 2, 'And a Scripture inscribed'),
  ('en.pickthall', 52, 3, 'On fine parchment unrolled,'),
  ('en.pickthall', 52, 4, 'And the House frequented,'),
  ('en.pickthall', 52, 5, 'And the roof exalted,'),
  ('en.pickthall', 52, 6, 'And the sea kept filled,'),
  ('en.pickthall', 52, 7, 'Lo! the doom of thy Lord will surely come to pass;'),
  ('en.pickthall', 52, 8, 'There is none that can ward it off.'),
  ('en.pickthall', 52, 9, 'On the day when the heaven will heave with (awful) heaving,'),
  ('en.pickthall', 52, 10, 'And the mountains move away with (awful) movement,'),
  ('en.pickthall', 52, 11, 'Then woe that day unto the deniers'),
  ('en.pickthall', 52, 12, 'Who play in talk of grave matters;'),
  ('en.pickthall', 52, 13, 'The day when they are thrust with a (disdainful) thrust, into the fire of hell'),
  ('en.pickthall', 52, 14, '(And it is said unto them): This is the Fire which ye were wont to deny.'),
  ('en.pickthall', 52, 15, 'Is this magic, or do ye not see?'),
  ('en.pickthall', 52, 16, 'Endure the heat thereof, and whether ye are patient of it or impatient of it is all one for you. Ye are only being paid for what ye used to do.'),
  ('en.pickthall', 52, 17, 'Lo! those who kept their duty dwell in gardens and delight,'),
  ('en.pickthall', 52, 18, 'Happy because of what their Lord hath given them, and (because) their Lord hath warded off from them the torment of hell-fire.'),
  ('en.pickthall', 52, 19, '(And it is said unto them): Eat and drink in health (as a reward) for what ye used to do,'),
  ('en.pickthall', 52, 20, 'Reclining on ranged couches. And we wed them unto fair ones with wide, lovely eyes.'),
  ('en.pickthall', 52, 21, 'And they who believe and whose seed follow them in faith, We cause their seed to join them (there), and We deprive them of nought of their (life\'s) work. Every man is a pledge for that which he hath earned.'),
  ('en.pickthall', 52, 22, 'And We provide them with fruit and meat such as they desire.'),
  ('en.pickthall', 52, 23, 'There they pass from hand to hand a cup wherein is neither vanity nor cause of sin.'),
  ('en.pickthall', 52, 24, 'And there go round, waiting on them menservants of their own, as they were hidden pearls.'),
  ('en.pickthall', 52, 25, 'And some of them draw near unto others, questioning,'),
  ('en.pickthall', 52, 26, 'Saying: Lo! of old, when we were with our families, we were ever anxious;'),
  ('en.pickthall', 52, 27, 'But Allah hath been gracious unto us and hath preserved us from the torment of the breath of Fire.'),
  ('en.pickthall', 52, 28, 'Lo! we used to pray unto Him of old. Lo! He is the Benign, the Merciful.'),
  ('en.pickthall', 52, 29, 'Therefor warn (men, O Muhammad). By the grace of Allah thou art neither soothsayer nor madman.'),
  ('en.pickthall', 52, 30, 'Or say they: (he is) a poet, (one) for whom we may expect the accident of time?'),
  ('en.pickthall', 52, 31, 'Say (unto them): Except (your fill)! Lo! I am with you among the expectant.'),
  ('en.pickthall', 52, 32, 'Do their minds command them to do this, or are they an outrageous folk?'),
  ('en.pickthall', 52, 33, 'Or say they: He hath invented it? Nay, but they will not believe!'),
  ('en.pickthall', 52, 34, 'Then let them produce speech the like thereof, if they are truthful.'),
  ('en.pickthall', 52, 35, 'Or were they created out of naught? Or are they the creators?'),
  ('en.pickthall', 52, 36, 'Or did they create the heavens and the earth? Nay, but they are sure of nothing!'),
  ('en.pickthall', 52, 37, 'Or do they own the treasures of thy Lord? Or have they been given charge (thereof)?'),
  ('en.pickthall', 52, 38, 'Or have they any stairway (unto heaven) by means of which they overhear (decrees). Then let their listener produce some warrant manifest!'),
  ('en.pickthall', 52, 39, 'Or hath He daughters whereas ye have sons?'),
  ('en.pickthall', 52, 40, 'Or askest thou (Muhammad) a fee from them so that they are plunged in debt?'),
  ('en.pickthall', 52, 41, 'Or possess they the Unseen so that they can write (it) down?'),
  ('en.pickthall', 52, 42, 'Or seek they to ensnare (the messenger)? But those who disbelieve, they are the ensnared!'),
  ('en.pickthall', 52, 43, 'Or have they any god beside Allah? Glorified be Allah from all that they ascribe as partner (unto Him)!'),
  ('en.pickthall', 52, 44, 'And if they were to see a fragment of the heaven falling, they would say: A heap of clouds.'),
  ('en.pickthall', 52, 45, 'Then let them be (O Muhammad), till they meet their day, in which they will be thunder-stricken,'),
  ('en.pickthall', 52, 46, 'A day in which their guile will naught avail them, nor will they be helped.'),
  ('en.pickthall', 52, 47, 'And verily, for those who do wrong, there is a punishment beyond that. But most of them know not.'),
  ('en.pickthall', 52, 48, 'So wait patiently (O Muhammad) for thy Lord\'s decree, for surely thou art in Our sight; and hymn the praise of thy Lord when thou uprisest,'),
  ('en.pickthall', 52, 49, 'And in the night-time also hymn His praise, and at the setting of the stars.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 52, 1, 'By the Mount (of Revelation);'),
  ('en.yusufali', 52, 2, 'By a Decree inscribed'),
  ('en.yusufali', 52, 3, 'In a Scroll unfolded;'),
  ('en.yusufali', 52, 4, 'By the much-frequented Fane;'),
  ('en.yusufali', 52, 5, 'By the Canopy Raised High;'),
  ('en.yusufali', 52, 6, 'And by the Ocean filled with Swell;-'),
  ('en.yusufali', 52, 7, 'Verily, the Doom of thy Lord will indeed come to pass;-'),
  ('en.yusufali', 52, 8, 'There is none can avert it;-'),
  ('en.yusufali', 52, 9, 'On the Day when the firmament will be in dreadful commotion.'),
  ('en.yusufali', 52, 10, 'And the mountains will fly hither and thither.'),
  ('en.yusufali', 52, 11, 'Then woe that Day to those that treat (Truth) as Falsehood;-'),
  ('en.yusufali', 52, 12, 'That play (and paddle) in shallow trifles.'),
  ('en.yusufali', 52, 13, 'That Day shall they be thrust down to the Fire of Hell, irresistibly.'),
  ('en.yusufali', 52, 14, '"This:, it will be said, "Is the Fire,- which ye were wont to deny!'),
  ('en.yusufali', 52, 15, '"Is this then a fake, or is it ye that do not see?'),
  ('en.yusufali', 52, 16, '"Burn ye therein: the same is it to you whether ye bear it with patience, or not: Ye but receive the recompense of your (own) deeds."'),
  ('en.yusufali', 52, 17, 'As to the Righteous, they will be in Gardens, and in Happiness,-'),
  ('en.yusufali', 52, 18, 'Enjoying the (Bliss) which their Lord hath bestowed on them, and their Lord shall deliver them from the Penalty of the Fire.'),
  ('en.yusufali', 52, 19, '(To them will be said:) "Eat and drink ye, with profit and health, because of your (good) deeds."'),
  ('en.yusufali', 52, 20, 'They will recline (with ease) on Thrones (of dignity) arranged in ranks; and We shall join them to Companions, with beautiful big and lustrous eyes.'),
  ('en.yusufali', 52, 21, 'And those who believe and whose families follow them in Faith,- to them shall We join their families: Nor shall We deprive them (of the fruit) of aught of their works: (Yet) is each individual in pledge for his deeds.'),
  ('en.yusufali', 52, 22, 'And We shall bestow on them, of fruit and meat, anything they shall desire.'),
  ('en.yusufali', 52, 23, 'They shall there exchange, one with another, a (loving) cup free of frivolity, free of all taint of ill.'),
  ('en.yusufali', 52, 24, 'Round about them will serve, (devoted) to them, young male servants (handsome) as Pearls well-guarded.'),
  ('en.yusufali', 52, 25, 'They will advance to each other, engaging in mutual enquiry.'),
  ('en.yusufali', 52, 26, 'They will say: "Aforetime, we were not without fear for the sake of our people.'),
  ('en.yusufali', 52, 27, '"But Allah has been good to us, and has delivered us from the Penalty of the Scorching Wind.'),
  ('en.yusufali', 52, 28, '"Truly, we did call unto Him from of old: truly it is He, the Beneficent, the Merciful!"'),
  ('en.yusufali', 52, 29, 'Therefore proclaim thou the praises (of thy Lord): for by the Grace of thy Lord, thou art no (vulgar) soothsayer, nor art thou one possessed.'),
  ('en.yusufali', 52, 30, 'Or do they say:- "A Poet! we await for him some calamity (hatched) by Time!"'),
  ('en.yusufali', 52, 31, 'Say thou: "Await ye!- I too will wait along with you!"'),
  ('en.yusufali', 52, 32, 'Is it that their faculties of understanding urge them to this, or are they but a people transgressing beyond bounds?'),
  ('en.yusufali', 52, 33, 'Or do they say, "He fabricated the (Message)"? Nay, they have no faith!'),
  ('en.yusufali', 52, 34, 'Let them then produce a recital like unto it,- If (it be) they speak the truth!'),
  ('en.yusufali', 52, 35, 'Were they created of nothing, or were they themselves the creators?'),
  ('en.yusufali', 52, 36, 'Or did they create the heavens and the earth? Nay, they have no firm belief.'),
  ('en.yusufali', 52, 37, 'Or are the Treasures of thy Lord with them, or are they the managers (of affairs)?'),
  ('en.yusufali', 52, 38, 'Or have they a ladder, by which they can (climb up to heaven and) listen (to its secrets)? Then let (such a) listener of theirs produce a manifest proof.'),
  ('en.yusufali', 52, 39, 'Or has He only daughters and ye have sons?'),
  ('en.yusufali', 52, 40, 'Or is it that thou dost ask for a reward, so that they are burdened with a load of debt?-'),
  ('en.yusufali', 52, 41, 'Or that the Unseen in it their hands, and they write it down?'),
  ('en.yusufali', 52, 42, 'Or do they intend a plot (against thee)? But those who defy Allah are themselves involved in a Plot!'),
  ('en.yusufali', 52, 43, 'Or have they a god other than Allah? Exalted is Allah far above the things they associate with Him!'),
  ('en.yusufali', 52, 44, 'Were they to see a piece of the sky falling (on them), they would (only) say: "Clouds gathered in heaps!"'),
  ('en.yusufali', 52, 45, 'So leave them alone until they encounter that Day of theirs, wherein they shall (perforce) swoon (with terror),-'),
  ('en.yusufali', 52, 46, 'The Day when their plotting will avail them nothing and no help shall be given them.'),
  ('en.yusufali', 52, 47, 'And verily, for those who do wrong, there is another punishment besides this: But most of them understand not.'),
  ('en.yusufali', 52, 48, 'Now await in patience the command of thy Lord: for verily thou art in Our eyes: and celebrate the praises of thy Lord the while thou standest forth,'),
  ('en.yusufali', 52, 49, 'And for part of the night also praise thou Him,- and at the retreat of the stars!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 52, 1, 'Wat-Toor'),
  ('en.transliteration', 52, 2, 'Wa kitaabim mastoor'),
  ('en.transliteration', 52, 3, 'Fee raqqim manshoor'),
  ('en.transliteration', 52, 4, 'Wal baitil ma\'moor'),
  ('en.transliteration', 52, 5, 'Wassaqfil marfoo\''),
  ('en.transliteration', 52, 6, 'Wal bahril masjoor'),
  ('en.transliteration', 52, 7, 'Inna \'azaaba Rabbika lawaaqi\''),
  ('en.transliteration', 52, 8, 'Maa lahoo min daafi\''),
  ('en.transliteration', 52, 9, 'Yawma tamoorus samaaa\'u mawraa'),
  ('en.transliteration', 52, 10, 'Wa taseerul jibaalu sairaa'),
  ('en.transliteration', 52, 11, 'Fawailuny yawma \'izil lil mukaazzibeen'),
  ('en.transliteration', 52, 12, 'Allazeena hum fee khawdiny yal\'aboon'),
  ('en.transliteration', 52, 13, 'Yawma yuda\'-\'oona ilaa naari jahannama da\'-\'aa'),
  ('en.transliteration', 52, 14, 'Haazihin naarul latee kuntum bihaa tukazziboon'),
  ('en.transliteration', 52, 15, 'Afasihrun haazaaaa am antum laa tubsiroon'),
  ('en.transliteration', 52, 16, 'Islawhaa fasbirooo aw laa tasbiroo sawaaa\'un \'alaikum innamaa tujzawna maa kuntum ta\'maloon'),
  ('en.transliteration', 52, 17, 'Innal muttaqeena fee jannaatinw wa na\'eem'),
  ('en.transliteration', 52, 18, 'Faakiheena bimaaa aataahum rabbuhum wa waqaahum rabbuhum \'azaabal jaheem'),
  ('en.transliteration', 52, 19, 'Kuloo washraboo haneee \'am bimaa kuntum ta\'maloon'),
  ('en.transliteration', 52, 20, 'Muttaki\'eena \'alaa sururim masfoofatinw wa zawwaj naahum bihoorin \'een'),
  ('en.transliteration', 52, 21, 'Wallazeena aamanoo wattaba\'at hum zurriyyatuhum bieemaanin alhaqnaa bihim zurriyyatahum wa maaa alatnaahum min \'amalihim min shai\'; kullum ri\'im bimaa kasaba raheen'),
  ('en.transliteration', 52, 22, 'Wa amdadnaahum bifaa kihatinw wa lahmim mimmaa yashtahoon'),
  ('en.transliteration', 52, 23, 'Yatanaaza\'oona feehaa kaasal laa laghwun feehaa wa laa taaseem'),
  ('en.transliteration', 52, 24, 'Wa yatoofu \'alaihim ghilmaanul lahum ka annahum lu\'lu\'um maknoon'),
  ('en.transliteration', 52, 25, 'Wa aqbala ba\'duhum \'alaa ba\'diny yatasaaa\'aloon'),
  ('en.transliteration', 52, 26, 'Qaalooo innaa kunnaa qablu feee ahlinaa mushfiqeen'),
  ('en.transliteration', 52, 27, 'Famannnal laahu \'alainaa wa waqaanaa \'azaabas samoom'),
  ('en.transliteration', 52, 28, 'Innaa kunnaa min qablu nad\'oohu innahoo huwal barrur raheem'),
  ('en.transliteration', 52, 29, 'Fazakkir famaaa anta bini\'mati rabbika bikaahininw wa laa majnoon'),
  ('en.transliteration', 52, 30, 'Am yaqooloona shaa\'irun natarabbasu bihee raibal manoon'),
  ('en.transliteration', 52, 31, 'Qul tarabbasoo fa innee ma\'akum minal mutarabbiseen'),
  ('en.transliteration', 52, 32, 'Am taamuruhum ahlaamuhum bihaazaaa am hum qawmun taaghoon'),
  ('en.transliteration', 52, 33, 'Am yaqooloona taqawwalah; bal laa yu\'minoon'),
  ('en.transliteration', 52, 34, 'Falyaatoo bihadeesim misliheee in kaanoo saadiqeen'),
  ('en.transliteration', 52, 35, 'Am khuliqoo min ghairi shai\'in am humul khaaliqoon'),
  ('en.transliteration', 52, 36, 'Am khalaqus samaawaati wal ard; bal laa yooqinoon'),
  ('en.transliteration', 52, 37, 'Am\'indahum khazaaa\'inu rabbika am humul musaitiroon'),
  ('en.transliteration', 52, 38, 'Am lahum sullamuny yastami\'oona feehi falyaati mustami\'uhum bisultaanim mubeen'),
  ('en.transliteration', 52, 39, 'Am lahul banaatu wa lakumul banoon'),
  ('en.transliteration', 52, 40, 'Am tas\'aluhum ajran fahum mim maghramim musqaloon'),
  ('en.transliteration', 52, 41, 'Am \'indahumul ghaibu fahum yaktuboon'),
  ('en.transliteration', 52, 42, 'Am yureedoona kaidan fallazeena kafaroo humul makeedoon'),
  ('en.transliteration', 52, 43, 'Am lahum ilaahun ghairul laa; subhaanal laahi \'ammaa yushrikoon'),
  ('en.transliteration', 52, 44, 'Wa iny yaraw kisfam minas samaaa\'i saaqitany yaqooloo sahaabum markoom'),
  ('en.transliteration', 52, 45, 'Fazarhum hatta yulaaqoo yawmahumul lazee feehi yus\'aqoon'),
  ('en.transliteration', 52, 46, 'Yawma laa yughnee \'anhum kaidumhum shai\'anw wa laa hum yunsaroon'),
  ('en.transliteration', 52, 47, 'Wa inna lillazeena zalamoo \'azaaban doona zalika wa laakinna aksarahum laa ya\'lamoon'),
  ('en.transliteration', 52, 48, 'Wasbir lihukmi rabbika fa innaka bi-a\'yuninaa wa sabbih bihamdi rabbika heena taqoom'),
  ('en.transliteration', 52, 49, 'Wa minal laili fasabbihhu wa idbaaran nujoom')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 52, 1, 'قسم ہے طور کی'),
  ('ur.ahmedali', 52, 2, 'اور اس کتاب کی جو لکھی گئی ہے'),
  ('ur.ahmedali', 52, 3, 'کشادہ ورقوں میں'),
  ('ur.ahmedali', 52, 4, 'اور آباد گھر کی قسم ہے'),
  ('ur.ahmedali', 52, 5, 'اور اونچی چھت کی'),
  ('ur.ahmedali', 52, 6, 'اور جوش مارتے ہوئے سمندر کی'),
  ('ur.ahmedali', 52, 7, 'بے شک آپ کے رب کا عذاب واقع ہوکر رہے گا'),
  ('ur.ahmedali', 52, 8, 'اسے کوئی ٹالنے والا نہیں ہے'),
  ('ur.ahmedali', 52, 9, 'جس دن آسمان تھرتھرا کر لرزنے لگے گا'),
  ('ur.ahmedali', 52, 10, 'اور پہاڑ تیزی سے چلنے لگیں گے'),
  ('ur.ahmedali', 52, 11, 'پس اس دن جھٹلانے والوں کے لیے ہلاکت ہے'),
  ('ur.ahmedali', 52, 12, 'جو جھوٹی باتوں میں لگے ہوئے کھیل رہے ہیں'),
  ('ur.ahmedali', 52, 13, 'جس دن وہ دوزخ کی آگ کی طرف بری طرح سے دھکیلے جائیں گے'),
  ('ur.ahmedali', 52, 14, 'یہی وہ آگ ہے جسے تم دنیا میں جھٹلاتے تھے'),
  ('ur.ahmedali', 52, 15, 'پس کیایہ جادو ہے یا تم دیکھتے نہیں'),
  ('ur.ahmedali', 52, 16, 'اس میں داخل ہو جاؤ پس تم صبر کرو یا نہ کرو تم پر برابر ہے تمہیں تو ویسا ہی بدلہ دیا جائے گا جیسا تم کرتے تھے'),
  ('ur.ahmedali', 52, 17, 'بے شک پرہیز گار باغوں اور نعمتوں میں ہوں گے'),
  ('ur.ahmedali', 52, 18, 'محظوظ ہو رہے ہوں گے اس سے جو انہیں ان کے رب نے عطا کی ہے اور ان کو ان کے رب نے عذاب دوزخ سے بچا دیا ہے'),
  ('ur.ahmedali', 52, 19, 'مزے سے کھاؤ اور پیو بدلے ان (اعمال) کے جو تم کیا کرتے تھے'),
  ('ur.ahmedali', 52, 20, 'تختوں پر تکیہ لگائے ہوئے جو قطاروں میں بچھے ہوئے ہیں اور ہم ان کا نکاح بڑی بڑی آنکھوں والی حوروں سے کر دیں گے'),
  ('ur.ahmedali', 52, 21, 'اور جو لوگ ایمان لائے اور ان کی اولاد نے ایمان میں ان کی پیروی کی ہم ان کے ساتھ ان کی اولاد کو بھی (جنت) میں ملا دیں گے اور ان کے عمل میں سے کچھ بھی کم نہ کریں گے ہر شخص اپنے عمل کے ساتھ وابستہ ہے'),
  ('ur.ahmedali', 52, 22, 'اور ہم انہیں اور زیادہ میوے دیں گے اور گوشت جو وہ چاہیں گے'),
  ('ur.ahmedali', 52, 23, 'وہاں ایک دوسرے سے شراب کا پیالہ لیں گے جس میں نہ بکواس ہو گی نہ گناہ کا کام'),
  ('ur.ahmedali', 52, 24, 'اور ان کے پاس لڑکے ان کی خدمت کے لیے پھر رہے ہوں گے گویا وہ غلافوں میں رکھے ہوئے موتی ہیں'),
  ('ur.ahmedali', 52, 25, 'اورایک دوسرے کی طرف متوجہ ہو کر آپس میں پوچھیں گے'),
  ('ur.ahmedali', 52, 26, 'کہیں گے ہم تو اس سے پہلے اپنے گھروں میں ڈرا کرتے تھے'),
  ('ur.ahmedali', 52, 27, 'پس الله نے ہم پر احسان کیا اور ہمیں لُو کے عذاب سے بچا لیا'),
  ('ur.ahmedali', 52, 28, 'بے شک ہم اس سے پہلے اسے پکارا کرتے تھے بے شک وہ بڑا ہی احسان کرنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 52, 29, 'پس نصیحت کرتے رہئے آپ اپنے رب کے فضل سے نہ کاہن ہیں نہ دیوانہ ہیں'),
  ('ur.ahmedali', 52, 30, 'کیا وہ کہتے ہیں کہ وہ شاعر ہے ہم اس پر گردشِ زمانہ کا انتظار کر رہے ہیں'),
  ('ur.ahmedali', 52, 31, 'کہہ دو تم انتظار کرتے رہو بے شک میں بھی تمہارے ساتھ منتظر ہوں'),
  ('ur.ahmedali', 52, 32, 'کیا ان کی عقلیں انہیں اس بات کا حکم دیتی ہیں یا وہ خود ہی سرکش ہیں'),
  ('ur.ahmedali', 52, 33, 'یا وہ کہتے ہیں کہ اس نے اسے خود بنا لیا ہے بلکہ وہ ایمان ہی نہیں لاتے'),
  ('ur.ahmedali', 52, 34, 'پس کوئی کلام اس جیسا لے آئيں اگر وہ سچے ہیں'),
  ('ur.ahmedali', 52, 35, 'کیا وہ بغیر کسی خالق کے پیدا ہو گئے ہیں یا وہ خود خالق ہیں'),
  ('ur.ahmedali', 52, 36, 'یا انہوں نے آسمانوں اور زمین کوبنایا ہے نہیں بلکہ وہ یقین ہی نہیں کرتے'),
  ('ur.ahmedali', 52, 37, 'کیا ان کے پاس آپ کے رب کے خزانے ہیں یا وہ داروغہ ہیں'),
  ('ur.ahmedali', 52, 38, 'کیا ان کے پاس کوئی سیڑھی ہے کہ وہ اس پر چڑھ کر سن آتے ہیں تو لے آئے ان میں سے سننے والا کوئی دلیل واضح'),
  ('ur.ahmedali', 52, 39, 'کیا اس کے لیے توبیٹیاں ہیں اور تمہارے لیے بیٹے'),
  ('ur.ahmedali', 52, 40, 'کیا آپ ان سے کوئی صلہ مانگتے ہیں کہ وہ تاوان سے دبے جا رہے ہیں'),
  ('ur.ahmedali', 52, 41, 'یا ان کے پاس علم غیب ہے کہ وہ اسے لکھتے رہتے ہیں'),
  ('ur.ahmedali', 52, 42, 'کیا وہ کوئی داؤ کرنا چاہتے ہیں پس جو منکر ہیں وہی داؤ میں آئے ہوئے ہیں'),
  ('ur.ahmedali', 52, 43, 'کیا سوائے الله کے ان کا کوئی اور معبود ہے الله اس سےپاک ہے جو وہ شریک ٹھہراتے ہیں'),
  ('ur.ahmedali', 52, 44, 'اگر وہ ایک ٹکڑا آسمان سے گرتا ہوا دیکھ لیں تو کہہ دیں کہ تہ بہ تہ جما ہوا بادل ہے'),
  ('ur.ahmedali', 52, 45, 'پس آپ انہیں چھوڑ دیجیئے یہاں تک کہ وہ اپنا وہ دن دیکھ لیں جس میں وہ بے ہوش ہو کر گر پڑیں گے'),
  ('ur.ahmedali', 52, 46, 'جس دن ان کا داؤ ان کے کچھ بھی کام نہ آئے گا اور نہ انہیں مدد دی جائے گی'),
  ('ur.ahmedali', 52, 47, 'اوربے شک ان ظالموں کو علاوہ اس کے ایک عذاب (دنیا میں) ہوگا لیکن اکثر ان میں سے نہیں جانتے'),
  ('ur.ahmedali', 52, 48, 'اور اپنے رب کا حکم آنے تک صبر کر کیوں کہ بےشک آپ ہماری آنکھوں کے سامنے ہیں اور اپنے رب کی حمد کے ساتھ تسبیح کیجیئے جب آپ اٹھا کریں'),
  ('ur.ahmedali', 52, 49, 'اور (کچھ حصہ رات میں بھی) اس کی تسبیح کیا کیجیئے اور ستاروں کے غروب ہونے کے بعد بھی')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 52, 1, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 2, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 3, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 4, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 5, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 6, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 7, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 8, 'Tura, yayılmış ince deri üzerine satır satır dizilmiş Kitap\'a, mamur bir ev olan Kabe\'ye, yükseltilmiş tavan gibi göğe, kaynayacak denize and olsun ki, Rabbinin azabı hiç şüphesiz gelecektir. Onu savacak yoktur.'),
  ('tr.diyanet', 52, 9, 'Göğün sarsıldıkça sarsılacağı, dağların yürüdükçe yürüyeceği gün; işte o gün, daldıkları yerde eğlenip oyalanarak kıyameti yalanlayanlara yazık olacak!'),
  ('tr.diyanet', 52, 10, 'Göğün sarsıldıkça sarsılacağı, dağların yürüdükçe yürüyeceği gün; işte o gün, daldıkları yerde eğlenip oyalanarak kıyameti yalanlayanlara yazık olacak!'),
  ('tr.diyanet', 52, 11, 'Göğün sarsıldıkça sarsılacağı, dağların yürüdükçe yürüyeceği gün; işte o gün, daldıkları yerde eğlenip oyalanarak kıyameti yalanlayanlara yazık olacak!'),
  ('tr.diyanet', 52, 12, 'Göğün sarsıldıkça sarsılacağı, dağların yürüdükçe yürüyeceği gün; işte o gün, daldıkları yerde eğlenip oyalanarak kıyameti yalanlayanlara yazık olacak!'),
  ('tr.diyanet', 52, 13, 'Cehennem ateşine itildikçe itildikleri gün, onlara: "İşte yalanlayıp durduğunuz ateş budur;'),
  ('tr.diyanet', 52, 14, 'Cehennem ateşine itildikçe itildikleri gün, onlara: "İşte yalanlayıp durduğunuz ateş budur;'),
  ('tr.diyanet', 52, 15, 'Bu bir büyü müdür, yoksa hala görmez misiniz? Girin oraya, sabretseniz de sabretmeseniz de artık birdir; ancak işlediklerinizin karşılığını görüyorsunuz" denir.'),
  ('tr.diyanet', 52, 16, 'Bu bir büyü müdür, yoksa hala görmez misiniz? Girin oraya, sabretseniz de sabretmeseniz de artık birdir; ancak işlediklerinizin karşılığını görüyorsunuz" denir.'),
  ('tr.diyanet', 52, 17, 'Allah\'a karşı gelmekten sakınanlar, şüphesiz, cennetlerde ve Rablerinin kendilerine verdikleriyle zevk duyarak nimetler içindedirler. Rableri onları cehennem azabından korumuştur.'),
  ('tr.diyanet', 52, 18, 'Allah\'a karşı gelmekten sakınanlar, şüphesiz, cennetlerde ve Rablerinin kendilerine verdikleriyle zevk duyarak nimetler içindedirler. Rableri onları cehennem azabından korumuştur.'),
  ('tr.diyanet', 52, 19, 'Onlara şöyle denir: "İşlediklerinizden ötürü, dizi dizi tahtlara yaslanarak afiyetle yiyin için." Onlara, ceylan gözlü eşler veririz.'),
  ('tr.diyanet', 52, 20, 'Onlara şöyle denir: "İşlediklerinizden ötürü, dizi dizi tahtlara yaslanarak afiyetle yiyin için." Onlara, ceylan gözlü eşler veririz.'),
  ('tr.diyanet', 52, 21, 'İnanan, soyları da inançta kendilerine uyan kimselere soylarını da katarız. Onların işlediklerinden hiçbir şey eksiltmeyiz. Herkes kazancına bağlıdır.'),
  ('tr.diyanet', 52, 22, 'Cennette olanlara diledikleri meyve ve etten bol bol veririz.'),
  ('tr.diyanet', 52, 23, 'Orada kadeh tokuştururlar; fakat bunda ne bir saçmalama, ne de bir günaha girme vardır.'),
  ('tr.diyanet', 52, 24, 'Sedefteki inciler gibi olan gençler yanlarında dolaşırlar.'),
  ('tr.diyanet', 52, 25, 'Birbirlerine dönüp soruşurlar:'),
  ('tr.diyanet', 52, 26, '"Doğrusu bundan önce ailemizin yanında bile korku içindeydik; Allah lütfedip bizi kavurucu azabdan korudu; doğrusu bundan önce de O\'na yalvarıyorduk; şüphesiz O, iyilik yapandır, acıyandır" derler.'),
  ('tr.diyanet', 52, 27, '"Doğrusu bundan önce ailemizin yanında bile korku içindeydik; Allah lütfedip bizi kavurucu azabdan korudu; doğrusu bundan önce de O\'na yalvarıyorduk; şüphesiz O, iyilik yapandır, acıyandır" derler.'),
  ('tr.diyanet', 52, 28, '"Doğrusu bundan önce ailemizin yanında bile korku içindeydik; Allah lütfedip bizi kavurucu azabdan korudu; doğrusu bundan önce de O\'na yalvarıyorduk; şüphesiz O, iyilik yapandır, acıyandır" derler.'),
  ('tr.diyanet', 52, 29, 'Öğüt ver; Rabbinin nimetiyle sen, ne kahinsin ne de delisin.'),
  ('tr.diyanet', 52, 30, 'Yoksa senin için şöyle mi derler: "Şairdir, zamanın onun aleyhine dönmesini gözlüyoruz."'),
  ('tr.diyanet', 52, 31, 'De ki: "Gözleyin, doğrusu ben de sizinle beraber gözlemekteyim."'),
  ('tr.diyanet', 52, 32, 'Bunu onlara akılları mı buyuruyor? Yoksa onlar azgın bir millet midirler?'),
  ('tr.diyanet', 52, 33, 'Yahut: "Onu kendi uydurdu" diyorlar öyle mi? Hayır, inanmıyorlar.'),
  ('tr.diyanet', 52, 34, 'Eğer iddialarında samimi iseler Kuran\'ın benzeri bir söz meydana getirsinler.'),
  ('tr.diyanet', 52, 35, 'Onlar, yaratan olmaksızın mı yaratıldılar yoksa yaratanlar kendileri midir?'),
  ('tr.diyanet', 52, 36, 'Yoksa gökleri ve yeri kendileri mi yarattılar? Hayır, Allah\'a kesin olarak inanmıyorlar.'),
  ('tr.diyanet', 52, 37, 'Yoksa Rabbinin hazineleri onların yanında mıdır? Yoksa onlar mı işe hakimdirler?'),
  ('tr.diyanet', 52, 38, 'Yoksa, üzerine çıkıp vahiy dinledikleri bir merdivenleri mi var? Öyleyse, dinleyenleri açık bir delil getirsin.'),
  ('tr.diyanet', 52, 39, 'Demek kızlar Allah\'ın, oğullar sizin öyle mi?'),
  ('tr.diyanet', 52, 40, 'Yahut sen onlardan bir ücret istiyorsun da onlar ağır bir borç altında mı kalıyorlar?'),
  ('tr.diyanet', 52, 41, 'Veya, görülmeyeni bilmek kendilerine aittir de, onlar mı yazıyorlar?'),
  ('tr.diyanet', 52, 42, 'Yoksa bir tuzak mı kurmak istiyorlar? Ama o tuzağa yakalanacak olanlar inkar edenlerdir.'),
  ('tr.diyanet', 52, 43, 'Yoksa Allah\'tan başka bir tanrıları mı vardır? Allah, onların ortak koşmalarından münezzehtir.'),
  ('tr.diyanet', 52, 44, 'Gökten azap olarak düşen bir parça görseler: "Bulut kümesidir" derler.'),
  ('tr.diyanet', 52, 45, 'Çarpılacakları güne erişmelerine kadar onları bırak.'),
  ('tr.diyanet', 52, 46, 'O gün, düzenleri kendilerine bir fayda vermez; yardım da görmezler.'),
  ('tr.diyanet', 52, 47, 'Zulmedenlere, şüphesiz, bundan başka da azap vardır; fakat onların çoğu bilmezler.'),
  ('tr.diyanet', 52, 48, 'Rabbinin hükmü yerine gelinceye kadar sabret; doğrusu sen, Bizim nezaretimiz altındasın; kalkarken Rabbini överek tesbih et;'),
  ('tr.diyanet', 52, 49, 'Geceleyin ve yıldızlar kaybolurken de O\'nu tesbih et.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 52, 1, 'Demi bukit,'),
  ('id.indonesian', 52, 2, 'dan Kitab yang ditulis,'),
  ('id.indonesian', 52, 3, 'pada lembaran yang terbuka,'),
  ('id.indonesian', 52, 4, 'dan demi Baitul Ma\'mur,'),
  ('id.indonesian', 52, 5, 'dan atap yang ditinggikan (langit),'),
  ('id.indonesian', 52, 6, 'dan laut yang di dalam tanahnya ada api,'),
  ('id.indonesian', 52, 7, 'sesungguhnya azab Tuhanmu pasti terjadi,'),
  ('id.indonesian', 52, 8, 'tidak seorangpun yang dapat menolaknya,'),
  ('id.indonesian', 52, 9, 'pada hari ketika langit benar-benar bergoncang,'),
  ('id.indonesian', 52, 10, 'dan gunung benar-benar berjalan.'),
  ('id.indonesian', 52, 11, 'Maka kecelakaan yang besarlah di hari itu bagi orang-orang yang mendustakan,'),
  ('id.indonesian', 52, 12, '(yaitu) orang-orang yang bermain-main dalam kebathilan,'),
  ('id.indonesian', 52, 13, 'pada hari mereka didorong ke neraka Jahannam dengan sekuat-kuatnya.'),
  ('id.indonesian', 52, 14, '(Dikatakan kepada mereka): "Inilah neraka yang dahulu kamu selalu mendustakannya".'),
  ('id.indonesian', 52, 15, 'Maka apakah ini sihir? Ataukah kamu tidak melihat?'),
  ('id.indonesian', 52, 16, 'Masukklah kamu ke dalamnya (rasakanlah panas apinya); maka baik kamu bersabar atau tidak, sama saja bagimu; kamu diberi balasan terhadap apa yang telah kamu kerjakan.'),
  ('id.indonesian', 52, 17, 'Sesungguhnya orang-orang yang bertakwa berada dalam surga dan kenikmatan,'),
  ('id.indonesian', 52, 18, 'mereka bersuka ria dengan apa yang diberikan kepada mereka oleh Tuhan mereka; dan Tuhan mereka memelihara mereka dari azab neraka.'),
  ('id.indonesian', 52, 19, '(Dikatakan kepada mereka): "Makan dan minumlah dengan enak sebagai balasan dari apa yang telah kamu kerjakan",'),
  ('id.indonesian', 52, 20, 'mereka bertelekan di atas dipan-dipan berderetan dan Kami kawinkan mereka dengan bidadari-bidadari yang cantik bermata jeli.'),
  ('id.indonesian', 52, 21, 'Dan orang-oranng yang beriman, dan yang anak cucu mereka mengikuti mereka dalam keimanan, Kami hubungkan anak cucu mereka dengan mereka, dan Kami tiada mengurangi sedikitpun dari pahala amal mereka. Tiap-tiap manusia terikat dengan apa yang dikerjakannya.'),
  ('id.indonesian', 52, 22, 'Dan Kami beri mereka tambahan dengan buah-buahan dan daging dari segala jenis yang mereka ingini.'),
  ('id.indonesian', 52, 23, 'Di dalam surga mereka saling memperebutkan piala (gelas) yang isinya tidak (menimbulkan) kata-kata yang tidak berfaedah dan tiada pula perbuatan dosa.'),
  ('id.indonesian', 52, 24, 'Dan berkeliling di sekitar mereka anak-anak muda untuk (melayani) mereka, seakan-akan mereka itu mutiara yang tersimpan.'),
  ('id.indonesian', 52, 25, 'Dan sebahagian mereka menghadap kepada sebahagian yang lain saling tanya-menanya.'),
  ('id.indonesian', 52, 26, 'Mereka berkata: "Sesungguhnya kami dahulu, sewaktu berada di tengah-tengah keluarga kami merasa takut (akan diazab)".'),
  ('id.indonesian', 52, 27, 'Maka Allah memberikan karunia kepada kami dan memelihara kami dari azab neraka.'),
  ('id.indonesian', 52, 28, 'Sesungguhnya kami dahulu menyembah-Nya. Sesungguhnya Dialah yang melimpahkan kebaikan lagi Maha Penyayang.'),
  ('id.indonesian', 52, 29, 'Maka tetaplah memberi peringatan, dan kamu disebabkan nikmat Tuhanmu bukanlah seorang tukang tenung dan bukan pula seorang gila.'),
  ('id.indonesian', 52, 30, 'Bahkan mereka mengatakan: "Dia adalah seorang penyair yang kami tunggu-tunggu kecelakaan menimpanya".'),
  ('id.indonesian', 52, 31, 'Katakanlah: "Tunggulah, maka sesungguhnya akupun termasuk orang yang menunggu (pula) bersama kamu".'),
  ('id.indonesian', 52, 32, 'Apakah mereka diperintah oleh fikiran-fikiran mereka untuk mengucapkan tuduhan-tuduhan ini ataukah mereka kaum yang melampaui batas?'),
  ('id.indonesian', 52, 33, 'Ataukah mereka mengatakan: "Dia (Muhammad) membuat-buatnya". Sebenarnya mereka tidak beriman.'),
  ('id.indonesian', 52, 34, 'Maka hendaklah mereka mendatangkan kalimat yang semisal Al Quran itu jika mereka orang-orang yang benar.'),
  ('id.indonesian', 52, 35, 'Apakah mereka diciptakan tanpa sesuatupun ataukah mereka yang menciptakan (diri mereka sendiri)?'),
  ('id.indonesian', 52, 36, 'Ataukah mereka telah menciptakan langit dan bumi itu?; sebenarnya mereka tidak meyakini (apa yang mereka katakan).'),
  ('id.indonesian', 52, 37, 'Ataukah di sisi mereka ada perbendaharaan Tuhanmu atau merekakah yang berkuasa?'),
  ('id.indonesian', 52, 38, 'Ataukah mereka mempunyai tangga (ke langit) untuk mendengarkan pada tangga itu (hal-hal yang gaib)? Maka hendaklah orang yang mendengarkan di antara mereka mendatangkan suatu keterangan yang nyata.'),
  ('id.indonesian', 52, 39, 'Ataukah untuk Allah anak-anak perempuan dan untuk kamu anak-anak laki-laki?'),
  ('id.indonesian', 52, 40, 'Ataukah kamu meminta upah kepada mereka sehingga mereka dibebani dengan hutang?'),
  ('id.indonesian', 52, 41, 'Apakah ada pada sisi mereka pengetahuan tentang yang gaib lalu mereka menuliskannya?'),
  ('id.indonesian', 52, 42, 'Ataukah mereka hendak melakukan tipu daya? Maka orang-orang yang kafir itu merekalah yang kena tipu daya.'),
  ('id.indonesian', 52, 43, 'Ataukah mereka mempunyai tuhan selain Allah. Maha Suci Allah dari apa yang mereka persekutukan.'),
  ('id.indonesian', 52, 44, 'Jika mereka melihat sebagian dari langit gugur, mereka akan mengatakan: "Itu adalah awan yang bertindih-tindih".'),
  ('id.indonesian', 52, 45, 'Maka biarkanlah mereka hingga mereka menemui hari (yang dijanjikan kepada) mereka yang pada hari itu mereka dibinasakan,'),
  ('id.indonesian', 52, 46, '(yaitu) hari ketika tidak berguna bagi mereka sedikitpun tipu daya mereka dan mereka tidak ditolong.'),
  ('id.indonesian', 52, 47, 'Dan sesungguhnya untuk orang-orang yang zalim ada azab selain daripada itu. Tetapi kebanyakan mereka tidak mengetahui.'),
  ('id.indonesian', 52, 48, 'Dan bersabarlah dalam menunggu ketetapan Tuhanmu, maka sesungguhnya kamu berada dalam penglihatan Kami, dan bertasbihlah dengan memuji Tuhanmu ketika kamu bangun berdiri,'),
  ('id.indonesian', 52, 49, 'dan bertasbihlah kepada-Nya pada beberapa saat di malam hari dan di waktu terbenam bintang-bintang (di waktu fajar).')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (48, 18, 4601, '۞ لَّقَدْ رَضِىَ ٱللَّهُ عَنِ ٱلْمُؤْمِنِينَ إِذْ يُبَايِعُونَكَ تَحْتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمْ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيْهِمْ وَأَثَٰبَهُمْ فَتْحًۭا قَرِيبًۭا', 513, 26, 205, 0),
  (48, 19, 4602, 'وَمَغَانِمَ كَثِيرَةًۭ يَأْخُذُونَهَا ۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًۭا', 513, 26, 205, 0),
  (48, 20, 4603, 'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةًۭ تَأْخُذُونَهَا فَعَجَّلَ لَكُمْ هَٰذِهِۦ وَكَفَّ أَيْدِىَ ٱلنَّاسِ عَنكُمْ وَلِتَكُونَ ءَايَةًۭ لِّلْمُؤْمِنِينَ وَيَهْدِيَكُمْ صِرَٰطًۭا مُّسْتَقِيمًۭا', 513, 26, 205, 0),
  (48, 21, 4604, 'وَأُخْرَىٰ لَمْ تَقْدِرُوا۟ عَلَيْهَا قَدْ أَحَاطَ ٱللَّهُ بِهَا ۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرًۭا', 513, 26, 205, 0),
  (48, 22, 4605, 'وَلَوْ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلْأَدْبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيًّۭا وَلَا نَصِيرًۭا', 513, 26, 205, 0),
  (48, 23, 4606, 'سُنَّةَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ مِن قَبْلُ ۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًۭا', 513, 26, 205, 0),
  (48, 24, 4607, 'وَهُوَ ٱلَّذِى كَفَّ أَيْدِيَهُمْ عَنكُمْ وَأَيْدِيَكُمْ عَنْهُم بِبَطْنِ مَكَّةَ مِنۢ بَعْدِ أَنْ أَظْفَرَكُمْ عَلَيْهِمْ ۚ وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا', 514, 26, 205, 0),
  (48, 25, 4608, 'هُمُ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱلْهَدْىَ مَعْكُوفًا أَن يَبْلُغَ مَحِلَّهُۥ ۚ وَلَوْلَا رِجَالٌۭ مُّؤْمِنُونَ وَنِسَآءٌۭ مُّؤْمِنَٰتٌۭ لَّمْ تَعْلَمُوهُمْ أَن تَطَـُٔوهُمْ فَتُصِيبَكُم مِّنْهُم مَّعَرَّةٌۢ بِغَيْرِ عِلْمٍۢ ۖ لِّيُدْخِلَ ٱللَّهُ فِى رَحْمَتِهِۦ مَن يَشَآءُ ۚ لَوْ تَزَيَّلُوا۟ لَعَذَّبْنَا ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابًا أَلِيمًا', 514, 26, 205, 0),
  (48, 26, 4609, 'إِذْ جَعَلَ ٱلَّذِينَ كَفَرُوا۟ فِى قُلُوبِهِمُ ٱلْحَمِيَّةَ حَمِيَّةَ ٱلْجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلْمُؤْمِنِينَ وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ وَكَانُوٓا۟ أَحَقَّ بِهَا وَأَهْلَهَا ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًۭا', 514, 26, 205, 0),
  (48, 27, 4610, 'لَّقَدْ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءْيَا بِٱلْحَقِّ ۖ لَتَدْخُلُنَّ ٱلْمَسْجِدَ ٱلْحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمْ وَمُقَصِّرِينَ لَا تَخَافُونَ ۖ فَعَلِمَ مَا لَمْ تَعْلَمُوا۟ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتْحًۭا قَرِيبًا', 514, 26, 205, 0),
  (48, 28, 4611, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًۭا', 514, 26, 205, 0),
  (48, 29, 4612, 'مُّحَمَّدٌۭ رَّسُولُ ٱللَّهِ ۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلْكُفَّارِ رُحَمَآءُ بَيْنَهُمْ ۖ تَرَىٰهُمْ رُكَّعًۭا سُجَّدًۭا يَبْتَغُونَ فَضْلًۭا مِّنَ ٱللَّهِ وَرِضْوَٰنًۭا ۖ سِيمَاهُمْ فِى وُجُوهِهِم مِّنْ أَثَرِ ٱلسُّجُودِ ۚ ذَٰلِكَ مَثَلُهُمْ فِى ٱلتَّوْرَىٰةِ ۚ وَمَثَلُهُمْ فِى ٱلْإِنجِيلِ كَزَرْعٍ أَخْرَجَ شَطْـَٔهُۥ فَـَٔازَرَهُۥ فَٱسْتَغْلَظَ فَٱسْتَوَىٰ عَلَىٰ سُوقِهِۦ يُعْجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلْكُفَّارَ ۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنْهُم مَّغْفِرَةًۭ وَأَجْرًا عَظِيمًۢا', 515, 26, 205, 0),
  (49, 1, 4613, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَيْنَ يَدَىِ ٱللَّهِ وَرَسُولِهِۦ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ', 515, 26, 206, 0),
  (49, 2, 4614, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَرْفَعُوٓا۟ أَصْوَٰتَكُمْ فَوْقَ صَوْتِ ٱلنَّبِىِّ وَلَا تَجْهَرُوا۟ لَهُۥ بِٱلْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَٰلُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ', 515, 26, 206, 0),
  (49, 3, 4615, 'إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصْوَٰتَهُمْ عِندَ رَسُولِ ٱللَّهِ أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱمْتَحَنَ ٱللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ ۚ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌ عَظِيمٌ', 515, 26, 206, 0),
  (49, 4, 4616, 'إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلْحُجُرَٰتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ', 515, 26, 206, 0),
  (49, 5, 4617, 'وَلَوْ أَنَّهُمْ صَبَرُوا۟ حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًۭا لَّهُمْ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 516, 26, 206, 0),
  (49, 6, 4618, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍۢ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَٰلَةٍۢ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ', 516, 26, 206, 0),
  (49, 7, 4619, 'وَٱعْلَمُوٓا۟ أَنَّ فِيكُمْ رَسُولَ ٱللَّهِ ۚ لَوْ يُطِيعُكُمْ فِى كَثِيرٍۢ مِّنَ ٱلْأَمْرِ لَعَنِتُّمْ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيْكُمُ ٱلْإِيمَٰنَ وَزَيَّنَهُۥ فِى قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ ٱلْكُفْرَ وَٱلْفُسُوقَ وَٱلْعِصْيَانَ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلرَّٰشِدُونَ', 516, 26, 206, 0),
  (49, 8, 4620, 'فَضْلًۭا مِّنَ ٱللَّهِ وَنِعْمَةًۭ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 516, 26, 206, 0),
  (49, 9, 4621, 'وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا ۖ فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ ۚ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ ۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 516, 26, 206, 0),
  (49, 10, 4622, 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌۭ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ', 516, 26, 206, 0),
  (49, 11, 4623, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌۭ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًۭا مِّنْهُمْ وَلَا نِسَآءٌۭ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًۭا مِّنْهُنَّ ۖ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَٰبِ ۖ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَٰنِ ۚ وَمَن لَّمْ يَتُبْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 516, 26, 206, 0),
  (49, 12, 4624, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًۭا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌۭ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌۭ رَّحِيمٌۭ', 517, 26, 206, 0),
  (49, 13, 4625, 'يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَٰكُم مِّن ذَكَرٍۢ وَأُنثَىٰ وَجَعَلْنَٰكُمْ شُعُوبًۭا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ ۚ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌۭ', 517, 26, 206, 0),
  (49, 14, 4626, '۞ قَالَتِ ٱلْأَعْرَابُ ءَامَنَّا ۖ قُل لَّمْ تُؤْمِنُوا۟ وَلَٰكِن قُولُوٓا۟ أَسْلَمْنَا وَلَمَّا يَدْخُلِ ٱلْإِيمَٰنُ فِى قُلُوبِكُمْ ۖ وَإِن تُطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتْكُم مِّنْ أَعْمَٰلِكُمْ شَيْـًٔا ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 517, 26, 207, 0),
  (49, 15, 4627, 'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمْ يَرْتَابُوا۟ وَجَٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 517, 26, 207, 0),
  (49, 16, 4628, 'قُلْ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمْ وَٱللَّهُ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 517, 26, 207, 0),
  (49, 17, 4629, 'يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا۟ ۖ قُل لَّا تَمُنُّوا۟ عَلَىَّ إِسْلَٰمَكُم ۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَىٰكُمْ لِلْإِيمَٰنِ إِن كُنتُمْ صَٰدِقِينَ', 517, 26, 207, 0),
  (49, 18, 4630, 'إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ', 517, 26, 207, 0),
  (50, 1, 4631, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قٓ ۚ وَٱلْقُرْءَانِ ٱلْمَجِيدِ', 518, 26, 207, 0),
  (50, 2, 4632, 'بَلْ عَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌۭ مِّنْهُمْ فَقَالَ ٱلْكَٰفِرُونَ هَٰذَا شَىْءٌ عَجِيبٌ', 518, 26, 207, 0),
  (50, 3, 4633, 'أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا ۖ ذَٰلِكَ رَجْعٌۢ بَعِيدٌۭ', 518, 26, 207, 0),
  (50, 4, 4634, 'قَدْ عَلِمْنَا مَا تَنقُصُ ٱلْأَرْضُ مِنْهُمْ ۖ وَعِندَنَا كِتَٰبٌ حَفِيظٌۢ', 518, 26, 207, 0),
  (50, 5, 4635, 'بَلْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ فَهُمْ فِىٓ أَمْرٍۢ مَّرِيجٍ', 518, 26, 207, 0),
  (50, 6, 4636, 'أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَٰهَا وَزَيَّنَّٰهَا وَمَا لَهَا مِن فُرُوجٍۢ', 518, 26, 207, 0),
  (50, 7, 4637, 'وَٱلْأَرْضَ مَدَدْنَٰهَا وَأَلْقَيْنَا فِيهَا رَوَٰسِىَ وَأَنۢبَتْنَا فِيهَا مِن كُلِّ زَوْجٍۭ بَهِيجٍۢ', 518, 26, 207, 0),
  (50, 8, 4638, 'تَبْصِرَةًۭ وَذِكْرَىٰ لِكُلِّ عَبْدٍۢ مُّنِيبٍۢ', 518, 26, 207, 0),
  (50, 9, 4639, 'وَنَزَّلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ مُّبَٰرَكًۭا فَأَنۢبَتْنَا بِهِۦ جَنَّٰتٍۢ وَحَبَّ ٱلْحَصِيدِ', 518, 26, 207, 0),
  (50, 10, 4640, 'وَٱلنَّخْلَ بَاسِقَٰتٍۢ لَّهَا طَلْعٌۭ نَّضِيدٌۭ', 518, 26, 207, 0),
  (50, 11, 4641, 'رِّزْقًۭا لِّلْعِبَادِ ۖ وَأَحْيَيْنَا بِهِۦ بَلْدَةًۭ مَّيْتًۭا ۚ كَذَٰلِكَ ٱلْخُرُوجُ', 518, 26, 207, 0),
  (50, 12, 4642, 'كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ وَأَصْحَٰبُ ٱلرَّسِّ وَثَمُودُ', 518, 26, 207, 0),
  (50, 13, 4643, 'وَعَادٌۭ وَفِرْعَوْنُ وَإِخْوَٰنُ لُوطٍۢ', 518, 26, 207, 0),
  (50, 14, 4644, 'وَأَصْحَٰبُ ٱلْأَيْكَةِ وَقَوْمُ تُبَّعٍۢ ۚ كُلٌّۭ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ', 518, 26, 207, 0),
  (50, 15, 4645, 'أَفَعَيِينَا بِٱلْخَلْقِ ٱلْأَوَّلِ ۚ بَلْ هُمْ فِى لَبْسٍۢ مِّنْ خَلْقٍۢ جَدِيدٍۢ', 518, 26, 207, 0),
  (50, 16, 4646, 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ وَنَعْلَمُ مَا تُوَسْوِسُ بِهِۦ نَفْسُهُۥ ۖ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', 519, 26, 207, 0),
  (50, 17, 4647, 'إِذْ يَتَلَقَّى ٱلْمُتَلَقِّيَانِ عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٌۭ', 519, 26, 207, 0),
  (50, 18, 4648, 'مَّا يَلْفِظُ مِن قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌۭ', 519, 26, 207, 0),
  (50, 19, 4649, 'وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ۖ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ', 519, 26, 207, 0),
  (50, 20, 4650, 'وَنُفِخَ فِى ٱلصُّورِ ۚ ذَٰلِكَ يَوْمُ ٱلْوَعِيدِ', 519, 26, 207, 0),
  (50, 21, 4651, 'وَجَآءَتْ كُلُّ نَفْسٍۢ مَّعَهَا سَآئِقٌۭ وَشَهِيدٌۭ', 519, 26, 207, 0),
  (50, 22, 4652, 'لَّقَدْ كُنتَ فِى غَفْلَةٍۢ مِّنْ هَٰذَا فَكَشَفْنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلْيَوْمَ حَدِيدٌۭ', 519, 26, 207, 0),
  (50, 23, 4653, 'وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَىَّ عَتِيدٌ', 519, 26, 207, 0),
  (50, 24, 4654, 'أَلْقِيَا فِى جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٍۢ', 519, 26, 207, 0),
  (50, 25, 4655, 'مَّنَّاعٍۢ لِّلْخَيْرِ مُعْتَدٍۢ مُّرِيبٍ', 519, 26, 207, 0),
  (50, 26, 4656, 'ٱلَّذِى جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلْقِيَاهُ فِى ٱلْعَذَابِ ٱلشَّدِيدِ', 519, 26, 207, 0),
  (50, 27, 4657, '۞ قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ وَلَٰكِن كَانَ فِى ضَلَٰلٍۭ بَعِيدٍۢ', 519, 26, 208, 0),
  (50, 28, 4658, 'قَالَ لَا تَخْتَصِمُوا۟ لَدَىَّ وَقَدْ قَدَّمْتُ إِلَيْكُم بِٱلْوَعِيدِ', 519, 26, 208, 0),
  (50, 29, 4659, 'مَا يُبَدَّلُ ٱلْقَوْلُ لَدَىَّ وَمَآ أَنَا۠ بِظَلَّٰمٍۢ لِّلْعَبِيدِ', 519, 26, 208, 0),
  (50, 30, 4660, 'يَوْمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمْتَلَأْتِ وَتَقُولُ هَلْ مِن مَّزِيدٍۢ', 519, 26, 208, 0),
  (50, 31, 4661, 'وَأُزْلِفَتِ ٱلْجَنَّةُ لِلْمُتَّقِينَ غَيْرَ بَعِيدٍ', 519, 26, 208, 0),
  (50, 32, 4662, 'هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٍۢ', 519, 26, 208, 0),
  (50, 33, 4663, 'مَّنْ خَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ وَجَآءَ بِقَلْبٍۢ مُّنِيبٍ', 519, 26, 208, 0),
  (50, 34, 4664, 'ٱدْخُلُوهَا بِسَلَٰمٍۢ ۖ ذَٰلِكَ يَوْمُ ٱلْخُلُودِ', 519, 26, 208, 0),
  (50, 35, 4665, 'لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيْنَا مَزِيدٌۭ', 519, 26, 208, 0),
  (50, 36, 4666, 'وَكَمْ أَهْلَكْنَا قَبْلَهُم مِّن قَرْنٍ هُمْ أَشَدُّ مِنْهُم بَطْشًۭا فَنَقَّبُوا۟ فِى ٱلْبِلَٰدِ هَلْ مِن مَّحِيصٍ', 520, 26, 208, 0),
  (50, 37, 4667, 'إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْبٌ أَوْ أَلْقَى ٱلسَّمْعَ وَهُوَ شَهِيدٌۭ', 520, 26, 208, 0),
  (50, 38, 4668, 'وَلَقَدْ خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا فِى سِتَّةِ أَيَّامٍۢ وَمَا مَسَّنَا مِن لُّغُوبٍۢ', 520, 26, 208, 0),
  (50, 39, 4669, 'فَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ ٱلشَّمْسِ وَقَبْلَ ٱلْغُرُوبِ', 520, 26, 208, 0),
  (50, 40, 4670, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَأَدْبَٰرَ ٱلسُّجُودِ', 520, 26, 208, 0),
  (50, 41, 4671, 'وَٱسْتَمِعْ يَوْمَ يُنَادِ ٱلْمُنَادِ مِن مَّكَانٍۢ قَرِيبٍۢ', 520, 26, 208, 0),
  (50, 42, 4672, 'يَوْمَ يَسْمَعُونَ ٱلصَّيْحَةَ بِٱلْحَقِّ ۚ ذَٰلِكَ يَوْمُ ٱلْخُرُوجِ', 520, 26, 208, 0),
  (50, 43, 4673, 'إِنَّا نَحْنُ نُحْىِۦ وَنُمِيتُ وَإِلَيْنَا ٱلْمَصِيرُ', 520, 26, 208, 0),
  (50, 44, 4674, 'يَوْمَ تَشَقَّقُ ٱلْأَرْضُ عَنْهُمْ سِرَاعًۭا ۚ ذَٰلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌۭ', 520, 26, 208, 0),
  (50, 45, 4675, 'نَّحْنُ أَعْلَمُ بِمَا يَقُولُونَ ۖ وَمَآ أَنتَ عَلَيْهِم بِجَبَّارٍۢ ۖ فَذَكِّرْ بِٱلْقُرْءَانِ مَن يَخَافُ وَعِيدِ', 520, 26, 208, 0),
  (51, 1, 4676, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلذَّٰرِيَٰتِ ذَرْوًۭا', 520, 26, 208, 0),
  (51, 2, 4677, 'فَٱلْحَٰمِلَٰتِ وِقْرًۭا', 520, 26, 208, 0),
  (51, 3, 4678, 'فَٱلْجَٰرِيَٰتِ يُسْرًۭا', 520, 26, 208, 0),
  (51, 4, 4679, 'فَٱلْمُقَسِّمَٰتِ أَمْرًا', 520, 26, 208, 0),
  (51, 5, 4680, 'إِنَّمَا تُوعَدُونَ لَصَادِقٌۭ', 520, 26, 208, 0),
  (51, 6, 4681, 'وَإِنَّ ٱلدِّينَ لَوَٰقِعٌۭ', 520, 26, 208, 0),
  (51, 7, 4682, 'وَٱلسَّمَآءِ ذَاتِ ٱلْحُبُكِ', 521, 26, 208, 0),
  (51, 8, 4683, 'إِنَّكُمْ لَفِى قَوْلٍۢ مُّخْتَلِفٍۢ', 521, 26, 208, 0),
  (51, 9, 4684, 'يُؤْفَكُ عَنْهُ مَنْ أُفِكَ', 521, 26, 208, 0),
  (51, 10, 4685, 'قُتِلَ ٱلْخَرَّٰصُونَ', 521, 26, 208, 0),
  (51, 11, 4686, 'ٱلَّذِينَ هُمْ فِى غَمْرَةٍۢ سَاهُونَ', 521, 26, 208, 0),
  (51, 12, 4687, 'يَسْـَٔلُونَ أَيَّانَ يَوْمُ ٱلدِّينِ', 521, 26, 208, 0),
  (51, 13, 4688, 'يَوْمَ هُمْ عَلَى ٱلنَّارِ يُفْتَنُونَ', 521, 26, 208, 0),
  (51, 14, 4689, 'ذُوقُوا۟ فِتْنَتَكُمْ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَسْتَعْجِلُونَ', 521, 26, 208, 0),
  (51, 15, 4690, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَعُيُونٍ', 521, 26, 208, 0),
  (51, 16, 4691, 'ءَاخِذِينَ مَآ ءَاتَىٰهُمْ رَبُّهُمْ ۚ إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُحْسِنِينَ', 521, 26, 208, 0),
  (51, 17, 4692, 'كَانُوا۟ قَلِيلًۭا مِّنَ ٱلَّيْلِ مَا يَهْجَعُونَ', 521, 26, 208, 0),
  (51, 18, 4693, 'وَبِٱلْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ', 521, 26, 208, 0),
  (51, 19, 4694, 'وَفِىٓ أَمْوَٰلِهِمْ حَقٌّۭ لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 521, 26, 208, 0),
  (51, 20, 4695, 'وَفِى ٱلْأَرْضِ ءَايَٰتٌۭ لِّلْمُوقِنِينَ', 521, 26, 208, 0),
  (51, 21, 4696, 'وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ', 521, 26, 208, 0),
  (51, 22, 4697, 'وَفِى ٱلسَّمَآءِ رِزْقُكُمْ وَمَا تُوعَدُونَ', 521, 26, 208, 0),
  (51, 23, 4698, 'فَوَرَبِّ ٱلسَّمَآءِ وَٱلْأَرْضِ إِنَّهُۥ لَحَقٌّۭ مِّثْلَ مَآ أَنَّكُمْ تَنطِقُونَ', 521, 26, 208, 0),
  (51, 24, 4699, 'هَلْ أَتَىٰكَ حَدِيثُ ضَيْفِ إِبْرَٰهِيمَ ٱلْمُكْرَمِينَ', 521, 26, 208, 0),
  (51, 25, 4700, 'إِذْ دَخَلُوا۟ عَلَيْهِ فَقَالُوا۟ سَلَٰمًۭا ۖ قَالَ سَلَٰمٌۭ قَوْمٌۭ مُّنكَرُونَ', 521, 26, 208, 0),
  (51, 26, 4701, 'فَرَاغَ إِلَىٰٓ أَهْلِهِۦ فَجَآءَ بِعِجْلٍۢ سَمِينٍۢ', 521, 26, 208, 0),
  (51, 27, 4702, 'فَقَرَّبَهُۥٓ إِلَيْهِمْ قَالَ أَلَا تَأْكُلُونَ', 521, 26, 208, 0),
  (51, 28, 4703, 'فَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۖ قَالُوا۟ لَا تَخَفْ ۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٍۢ', 521, 26, 208, 0),
  (51, 29, 4704, 'فَأَقْبَلَتِ ٱمْرَأَتُهُۥ فِى صَرَّةٍۢ فَصَكَّتْ وَجْهَهَا وَقَالَتْ عَجُوزٌ عَقِيمٌۭ', 521, 26, 208, 0),
  (51, 30, 4705, 'قَالُوا۟ كَذَٰلِكِ قَالَ رَبُّكِ ۖ إِنَّهُۥ هُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ', 521, 26, 208, 0),
  (51, 31, 4706, '۞ قَالَ فَمَا خَطْبُكُمْ أَيُّهَا ٱلْمُرْسَلُونَ', 522, 27, 209, 0),
  (51, 32, 4707, 'قَالُوٓا۟ إِنَّآ أُرْسِلْنَآ إِلَىٰ قَوْمٍۢ مُّجْرِمِينَ', 522, 27, 209, 0),
  (51, 33, 4708, 'لِنُرْسِلَ عَلَيْهِمْ حِجَارَةًۭ مِّن طِينٍۢ', 522, 27, 209, 0),
  (51, 34, 4709, 'مُّسَوَّمَةً عِندَ رَبِّكَ لِلْمُسْرِفِينَ', 522, 27, 209, 0),
  (51, 35, 4710, 'فَأَخْرَجْنَا مَن كَانَ فِيهَا مِنَ ٱلْمُؤْمِنِينَ', 522, 27, 209, 0),
  (51, 36, 4711, 'فَمَا وَجَدْنَا فِيهَا غَيْرَ بَيْتٍۢ مِّنَ ٱلْمُسْلِمِينَ', 522, 27, 209, 0),
  (51, 37, 4712, 'وَتَرَكْنَا فِيهَآ ءَايَةًۭ لِّلَّذِينَ يَخَافُونَ ٱلْعَذَابَ ٱلْأَلِيمَ', 522, 27, 209, 0),
  (51, 38, 4713, 'وَفِى مُوسَىٰٓ إِذْ أَرْسَلْنَٰهُ إِلَىٰ فِرْعَوْنَ بِسُلْطَٰنٍۢ مُّبِينٍۢ', 522, 27, 209, 0),
  (51, 39, 4714, 'فَتَوَلَّىٰ بِرُكْنِهِۦ وَقَالَ سَٰحِرٌ أَوْ مَجْنُونٌۭ', 522, 27, 209, 0),
  (51, 40, 4715, 'فَأَخَذْنَٰهُ وَجُنُودَهُۥ فَنَبَذْنَٰهُمْ فِى ٱلْيَمِّ وَهُوَ مُلِيمٌۭ', 522, 27, 209, 0),
  (51, 41, 4716, 'وَفِى عَادٍ إِذْ أَرْسَلْنَا عَلَيْهِمُ ٱلرِّيحَ ٱلْعَقِيمَ', 522, 27, 209, 0),
  (51, 42, 4717, 'مَا تَذَرُ مِن شَىْءٍ أَتَتْ عَلَيْهِ إِلَّا جَعَلَتْهُ كَٱلرَّمِيمِ', 522, 27, 209, 0),
  (51, 43, 4718, 'وَفِى ثَمُودَ إِذْ قِيلَ لَهُمْ تَمَتَّعُوا۟ حَتَّىٰ حِينٍۢ', 522, 27, 209, 0),
  (51, 44, 4719, 'فَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ فَأَخَذَتْهُمُ ٱلصَّٰعِقَةُ وَهُمْ يَنظُرُونَ', 522, 27, 209, 0),
  (51, 45, 4720, 'فَمَا ٱسْتَطَٰعُوا۟ مِن قِيَامٍۢ وَمَا كَانُوا۟ مُنتَصِرِينَ', 522, 27, 209, 0),
  (51, 46, 4721, 'وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ قَوْمًۭا فَٰسِقِينَ', 522, 27, 209, 0),
  (51, 47, 4722, 'وَٱلسَّمَآءَ بَنَيْنَٰهَا بِأَيْي۟دٍۢ وَإِنَّا لَمُوسِعُونَ', 522, 27, 209, 0),
  (51, 48, 4723, 'وَٱلْأَرْضَ فَرَشْنَٰهَا فَنِعْمَ ٱلْمَٰهِدُونَ', 522, 27, 209, 0),
  (51, 49, 4724, 'وَمِن كُلِّ شَىْءٍ خَلَقْنَا زَوْجَيْنِ لَعَلَّكُمْ تَذَكَّرُونَ', 522, 27, 209, 0),
  (51, 50, 4725, 'فَفِرُّوٓا۟ إِلَى ٱللَّهِ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ', 522, 27, 209, 0),
  (51, 51, 4726, 'وَلَا تَجْعَلُوا۟ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ۖ إِنِّى لَكُم مِّنْهُ نَذِيرٌۭ مُّبِينٌۭ', 522, 27, 209, 0),
  (51, 52, 4727, 'كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوْ مَجْنُونٌ', 523, 27, 209, 0),
  (51, 53, 4728, 'أَتَوَاصَوْا۟ بِهِۦ ۚ بَلْ هُمْ قَوْمٌۭ طَاغُونَ', 523, 27, 209, 0),
  (51, 54, 4729, 'فَتَوَلَّ عَنْهُمْ فَمَآ أَنتَ بِمَلُومٍۢ', 523, 27, 209, 0),
  (51, 55, 4730, 'وَذَكِّرْ فَإِنَّ ٱلذِّكْرَىٰ تَنفَعُ ٱلْمُؤْمِنِينَ', 523, 27, 209, 0),
  (51, 56, 4731, 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', 523, 27, 209, 0),
  (51, 57, 4732, 'مَآ أُرِيدُ مِنْهُم مِّن رِّزْقٍۢ وَمَآ أُرِيدُ أَن يُطْعِمُونِ', 523, 27, 209, 0),
  (51, 58, 4733, 'إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلْقُوَّةِ ٱلْمَتِينُ', 523, 27, 209, 0),
  (51, 59, 4734, 'فَإِنَّ لِلَّذِينَ ظَلَمُوا۟ ذَنُوبًۭا مِّثْلَ ذَنُوبِ أَصْحَٰبِهِمْ فَلَا يَسْتَعْجِلُونِ', 523, 27, 209, 0),
  (51, 60, 4735, 'فَوَيْلٌۭ لِّلَّذِينَ كَفَرُوا۟ مِن يَوْمِهِمُ ٱلَّذِى يُوعَدُونَ', 523, 27, 209, 0),
  (52, 1, 4736, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلطُّورِ', 523, 27, 209, 0),
  (52, 2, 4737, 'وَكِتَٰبٍۢ مَّسْطُورٍۢ', 523, 27, 209, 0),
  (52, 3, 4738, 'فِى رَقٍّۢ مَّنشُورٍۢ', 523, 27, 209, 0),
  (52, 4, 4739, 'وَٱلْبَيْتِ ٱلْمَعْمُورِ', 523, 27, 209, 0),
  (52, 5, 4740, 'وَٱلسَّقْفِ ٱلْمَرْفُوعِ', 523, 27, 209, 0),
  (52, 6, 4741, 'وَٱلْبَحْرِ ٱلْمَسْجُورِ', 523, 27, 209, 0),
  (52, 7, 4742, 'إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٌۭ', 523, 27, 209, 0),
  (52, 8, 4743, 'مَّا لَهُۥ مِن دَافِعٍۢ', 523, 27, 209, 0),
  (52, 9, 4744, 'يَوْمَ تَمُورُ ٱلسَّمَآءُ مَوْرًۭا', 523, 27, 209, 0),
  (52, 10, 4745, 'وَتَسِيرُ ٱلْجِبَالُ سَيْرًۭا', 523, 27, 209, 0),
  (52, 11, 4746, 'فَوَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ', 523, 27, 209, 0),
  (52, 12, 4747, 'ٱلَّذِينَ هُمْ فِى خَوْضٍۢ يَلْعَبُونَ', 523, 27, 209, 0),
  (52, 13, 4748, 'يَوْمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا', 523, 27, 209, 0),
  (52, 14, 4749, 'هَٰذِهِ ٱلنَّارُ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ', 523, 27, 209, 0),
  (52, 15, 4750, 'أَفَسِحْرٌ هَٰذَآ أَمْ أَنتُمْ لَا تُبْصِرُونَ', 524, 27, 209, 0),
  (52, 16, 4751, 'ٱصْلَوْهَا فَٱصْبِرُوٓا۟ أَوْ لَا تَصْبِرُوا۟ سَوَآءٌ عَلَيْكُمْ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 524, 27, 209, 0),
  (52, 17, 4752, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَنَعِيمٍۢ', 524, 27, 209, 0),
  (52, 18, 4753, 'فَٰكِهِينَ بِمَآ ءَاتَىٰهُمْ رَبُّهُمْ وَوَقَىٰهُمْ رَبُّهُمْ عَذَابَ ٱلْجَحِيمِ', 524, 27, 209, 0),
  (52, 19, 4754, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 524, 27, 209, 0),
  (52, 20, 4755, 'مُتَّكِـِٔينَ عَلَىٰ سُرُرٍۢ مَّصْفُوفَةٍۢ ۖ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍۢ', 524, 27, 209, 0),
  (52, 21, 4756, 'وَٱلَّذِينَ ءَامَنُوا۟ وَٱتَّبَعَتْهُمْ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ وَمَآ أَلَتْنَٰهُم مِّنْ عَمَلِهِم مِّن شَىْءٍۢ ۚ كُلُّ ٱمْرِئٍۭ بِمَا كَسَبَ رَهِينٌۭ', 524, 27, 209, 0),
  (52, 22, 4757, 'وَأَمْدَدْنَٰهُم بِفَٰكِهَةٍۢ وَلَحْمٍۢ مِّمَّا يَشْتَهُونَ', 524, 27, 209, 0),
  (52, 23, 4758, 'يَتَنَٰزَعُونَ فِيهَا كَأْسًۭا لَّا لَغْوٌۭ فِيهَا وَلَا تَأْثِيمٌۭ', 524, 27, 209, 0),
  (52, 24, 4759, '۞ وَيَطُوفُ عَلَيْهِمْ غِلْمَانٌۭ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤٌۭ مَّكْنُونٌۭ', 524, 27, 210, 0),
  (52, 25, 4760, 'وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ', 524, 27, 210, 0),
  (52, 26, 4761, 'قَالُوٓا۟ إِنَّا كُنَّا قَبْلُ فِىٓ أَهْلِنَا مُشْفِقِينَ', 524, 27, 210, 0),
  (52, 27, 4762, 'فَمَنَّ ٱللَّهُ عَلَيْنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ', 524, 27, 210, 0),
  (52, 28, 4763, 'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ ۖ إِنَّهُۥ هُوَ ٱلْبَرُّ ٱلرَّحِيمُ', 524, 27, 210, 0),
  (52, 29, 4764, 'فَذَكِّرْ فَمَآ أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍۢ وَلَا مَجْنُونٍ', 524, 27, 210, 0),
  (52, 30, 4765, 'أَمْ يَقُولُونَ شَاعِرٌۭ نَّتَرَبَّصُ بِهِۦ رَيْبَ ٱلْمَنُونِ', 524, 27, 210, 0),
  (52, 31, 4766, 'قُلْ تَرَبَّصُوا۟ فَإِنِّى مَعَكُم مِّنَ ٱلْمُتَرَبِّصِينَ', 524, 27, 210, 0),
  (52, 32, 4767, 'أَمْ تَأْمُرُهُمْ أَحْلَٰمُهُم بِهَٰذَآ ۚ أَمْ هُمْ قَوْمٌۭ طَاغُونَ', 525, 27, 210, 0),
  (52, 33, 4768, 'أَمْ يَقُولُونَ تَقَوَّلَهُۥ ۚ بَل لَّا يُؤْمِنُونَ', 525, 27, 210, 0),
  (52, 34, 4769, 'فَلْيَأْتُوا۟ بِحَدِيثٍۢ مِّثْلِهِۦٓ إِن كَانُوا۟ صَٰدِقِينَ', 525, 27, 210, 0),
  (52, 35, 4770, 'أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَٰلِقُونَ', 525, 27, 210, 0),
  (52, 36, 4771, 'أَمْ خَلَقُوا۟ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ', 525, 27, 210, 0),
  (52, 37, 4772, 'أَمْ عِندَهُمْ خَزَآئِنُ رَبِّكَ أَمْ هُمُ ٱلْمُصَۣيْطِرُونَ', 525, 27, 210, 0),
  (52, 38, 4773, 'أَمْ لَهُمْ سُلَّمٌۭ يَسْتَمِعُونَ فِيهِ ۖ فَلْيَأْتِ مُسْتَمِعُهُم بِسُلْطَٰنٍۢ مُّبِينٍ', 525, 27, 210, 0),
  (52, 39, 4774, 'أَمْ لَهُ ٱلْبَنَٰتُ وَلَكُمُ ٱلْبَنُونَ', 525, 27, 210, 0),
  (52, 40, 4775, 'أَمْ تَسْـَٔلُهُمْ أَجْرًۭا فَهُم مِّن مَّغْرَمٍۢ مُّثْقَلُونَ', 525, 27, 210, 0),
  (52, 41, 4776, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 525, 27, 210, 0),
  (52, 42, 4777, 'أَمْ يُرِيدُونَ كَيْدًۭا ۖ فَٱلَّذِينَ كَفَرُوا۟ هُمُ ٱلْمَكِيدُونَ', 525, 27, 210, 0),
  (52, 43, 4778, 'أَمْ لَهُمْ إِلَٰهٌ غَيْرُ ٱللَّهِ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 525, 27, 210, 0),
  (52, 44, 4779, 'وَإِن يَرَوْا۟ كِسْفًۭا مِّنَ ٱلسَّمَآءِ سَاقِطًۭا يَقُولُوا۟ سَحَابٌۭ مَّرْكُومٌۭ', 525, 27, 210, 0),
  (52, 45, 4780, 'فَذَرْهُمْ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى فِيهِ يُصْعَقُونَ', 525, 27, 210, 0),
  (52, 46, 4781, 'يَوْمَ لَا يُغْنِى عَنْهُمْ كَيْدُهُمْ شَيْـًۭٔا وَلَا هُمْ يُنصَرُونَ', 525, 27, 210, 0),
  (52, 47, 4782, 'وَإِنَّ لِلَّذِينَ ظَلَمُوا۟ عَذَابًۭا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ', 525, 27, 210, 0),
  (52, 48, 4783, 'وَٱصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا ۖ وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ', 525, 27, 210, 0),
  (52, 49, 4784, 'وَمِنَ ٱلَّيْلِ فَسَبِّحْهُ وَإِدْبَٰرَ ٱلنُّجُومِ', 525, 27, 210, 0),
  (53, 1, 4785, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلنَّجْمِ إِذَا هَوَىٰ', 526, 27, 210, 0),
  (53, 2, 4786, 'مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ', 526, 27, 210, 0),
  (53, 3, 4787, 'وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ', 526, 27, 210, 0),
  (53, 4, 4788, 'إِنْ هُوَ إِلَّا وَحْىٌۭ يُوحَىٰ', 526, 27, 210, 0),
  (53, 5, 4789, 'عَلَّمَهُۥ شَدِيدُ ٱلْقُوَىٰ', 526, 27, 210, 0),
  (53, 6, 4790, 'ذُو مِرَّةٍۢ فَٱسْتَوَىٰ', 526, 27, 210, 0),
  (53, 7, 4791, 'وَهُوَ بِٱلْأُفُقِ ٱلْأَعْلَىٰ', 526, 27, 210, 0),
  (53, 8, 4792, 'ثُمَّ دَنَا فَتَدَلَّىٰ', 526, 27, 210, 0),
  (53, 9, 4793, 'فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَىٰ', 526, 27, 210, 0),
  (53, 10, 4794, 'فَأَوْحَىٰٓ إِلَىٰ عَبْدِهِۦ مَآ أَوْحَىٰ', 526, 27, 210, 0),
  (53, 11, 4795, 'مَا كَذَبَ ٱلْفُؤَادُ مَا رَأَىٰٓ', 526, 27, 210, 0),
  (53, 12, 4796, 'أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ', 526, 27, 210, 0),
  (53, 13, 4797, 'وَلَقَدْ رَءَاهُ نَزْلَةً أُخْرَىٰ', 526, 27, 210, 0),
  (53, 14, 4798, 'عِندَ سِدْرَةِ ٱلْمُنتَهَىٰ', 526, 27, 210, 0),
  (53, 15, 4799, 'عِندَهَا جَنَّةُ ٱلْمَأْوَىٰٓ', 526, 27, 210, 0),
  (53, 16, 4800, 'إِذْ يَغْشَى ٱلسِّدْرَةَ مَا يَغْشَىٰ', 526, 27, 210, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 53, 1, 'By the star when it descends,'),
  ('en.sahih', 53, 2, 'Your companion [Muhammad] has not strayed, nor has he erred,'),
  ('en.sahih', 53, 3, 'Nor does he speak from [his own] inclination.'),
  ('en.sahih', 53, 4, 'It is not but a revelation revealed,'),
  ('en.sahih', 53, 5, 'Taught to him by one intense in strength -'),
  ('en.sahih', 53, 6, 'One of soundness. And he rose to [his] true form'),
  ('en.sahih', 53, 7, 'While he was in the higher [part of the] horizon.'),
  ('en.sahih', 53, 8, 'Then he approached and descended'),
  ('en.sahih', 53, 9, 'And was at a distance of two bow lengths or nearer.'),
  ('en.sahih', 53, 10, 'And he revealed to His Servant what he revealed.'),
  ('en.sahih', 53, 11, 'The heart did not lie [about] what it saw.'),
  ('en.sahih', 53, 12, 'So will you dispute with him over what he saw?'),
  ('en.sahih', 53, 13, 'And he certainly saw him in another descent'),
  ('en.sahih', 53, 14, 'At the Lote Tree of the Utmost Boundary -'),
  ('en.sahih', 53, 15, 'Near it is the Garden of Refuge -'),
  ('en.sahih', 53, 16, 'When there covered the Lote Tree that which covered [it].'),
  ('en.sahih', 53, 17, 'The sight [of the Prophet] did not swerve, nor did it transgress [its limit].'),
  ('en.sahih', 53, 18, 'He certainly saw of the greatest signs of his Lord.'),
  ('en.sahih', 53, 19, 'So have you considered al-Lat and al-\'Uzza?'),
  ('en.sahih', 53, 20, 'And Manat, the third - the other one?'),
  ('en.sahih', 53, 21, 'Is the male for you and for Him the female?'),
  ('en.sahih', 53, 22, 'That, then, is an unjust division.'),
  ('en.sahih', 53, 23, 'They are not but [mere] names you have named them - you and your forefathers - for which Allah has sent down no authority. They follow not except assumption and what [their] souls desire, and there has already come to them from their Lord guidance.'),
  ('en.sahih', 53, 24, 'Or is there for man whatever he wishes?'),
  ('en.sahih', 53, 25, 'Rather, to Allah belongs the Hereafter and the first [life].'),
  ('en.sahih', 53, 26, 'And how many angels there are in the heavens whose intercession will not avail at all except [only] after Allah has permitted [it] to whom He wills and approves.'),
  ('en.sahih', 53, 27, 'Indeed, those who do not believe in the Hereafter name the angels female names,'),
  ('en.sahih', 53, 28, 'And they have thereof no knowledge. They follow not except assumption, and indeed, assumption avails not against the truth at all.'),
  ('en.sahih', 53, 29, 'So turn away from whoever turns his back on Our message and desires not except the worldly life.'),
  ('en.sahih', 53, 30, 'That is their sum of knowledge. Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of who is guided.'),
  ('en.sahih', 53, 31, 'And to Allah belongs whatever is in the heavens and whatever is in the earth - that He may recompense those who do evil with [the penalty of] what they have done and recompense those who do good with the best [reward] -'),
  ('en.sahih', 53, 32, 'Those who avoid the major sins and immoralities, only [committing] slight ones. Indeed, your Lord is vast in forgiveness. He was most knowing of you when He produced you from the earth and when you were fetuses in the wombs of your mothers. So do not claim yourselves to be pure; He is most knowing of who fears Him.'),
  ('en.sahih', 53, 33, 'Have you seen the one who turned away'),
  ('en.sahih', 53, 34, 'And gave a little and [then] refrained?'),
  ('en.sahih', 53, 35, 'Does he have knowledge of the unseen, so he sees?'),
  ('en.sahih', 53, 36, 'Or has he not been informed of what was in the scriptures of Moses'),
  ('en.sahih', 53, 37, 'And [of] Abraham, who fulfilled [his obligations] -'),
  ('en.sahih', 53, 38, 'That no bearer of burdens will bear the burden of another'),
  ('en.sahih', 53, 39, 'And that there is not for man except that [good] for which he strives'),
  ('en.sahih', 53, 40, 'And that his effort is going to be seen -'),
  ('en.sahih', 53, 41, 'Then he will be recompensed for it with the fullest recompense'),
  ('en.sahih', 53, 42, 'And that to your Lord is the finality'),
  ('en.sahih', 53, 43, 'And that it is He who makes [one] laugh and weep'),
  ('en.sahih', 53, 44, 'And that it is He who causes death and gives life'),
  ('en.sahih', 53, 45, 'And that He creates the two mates - the male and female -'),
  ('en.sahih', 53, 46, 'From a sperm-drop when it is emitted'),
  ('en.sahih', 53, 47, 'And that [incumbent] upon Him is the next creation'),
  ('en.sahih', 53, 48, 'And that it is He who enriches and suffices'),
  ('en.sahih', 53, 49, 'And that it is He who is the Lord of Sirius'),
  ('en.sahih', 53, 50, 'And that He destroyed the first [people of] \'Aad'),
  ('en.sahih', 53, 51, 'And Thamud - and He did not spare [them] -'),
  ('en.sahih', 53, 52, 'And the people of Noah before. Indeed, it was they who were [even] more unjust and oppressing.'),
  ('en.sahih', 53, 53, 'And the overturned towns He hurled down'),
  ('en.sahih', 53, 54, 'And covered them by that which He covered.'),
  ('en.sahih', 53, 55, 'Then which of the favors of your Lord do you doubt?'),
  ('en.sahih', 53, 56, 'This [Prophet] is a warner like the former warners.'),
  ('en.sahih', 53, 57, 'The Approaching Day has approached.'),
  ('en.sahih', 53, 58, 'Of it, [from those] besides Allah, there is no remover.'),
  ('en.sahih', 53, 59, 'Then at this statement do you wonder?'),
  ('en.sahih', 53, 60, 'And you laugh and do not weep'),
  ('en.sahih', 53, 61, 'While you are proudly sporting?'),
  ('en.sahih', 53, 62, 'So prostrate to Allah and worship [Him].')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 53, 1, 'নক্ষত্রের কসম, যখন অস্তমিত হয়।'),
  ('bn.bengali', 53, 2, 'তোমাদের সংগী পথভ্রষ্ট হননি এবং বিপথগামীও হননি।'),
  ('bn.bengali', 53, 3, 'এবং প্রবৃত্তির তাড়নায় কথা বলেন না।'),
  ('bn.bengali', 53, 4, 'কোরআন ওহী, যা প্রত্যাদেশ হয়।'),
  ('bn.bengali', 53, 5, 'তাঁকে শিক্ষা দান করে এক শক্তিশালী ফেরেশতা,'),
  ('bn.bengali', 53, 6, 'সহজাত শক্তিসম্পন্ন, সে নিজ আকৃতিতে প্রকাশ পেল।'),
  ('bn.bengali', 53, 7, 'উর্ধ্ব দিগন্তে,'),
  ('bn.bengali', 53, 8, 'অতঃপর নিকটবর্তী হল ও ঝুলে গেল।'),
  ('bn.bengali', 53, 9, 'তখন দুই ধনুকের ব্যবধান ছিল অথবা আরও কম।'),
  ('bn.bengali', 53, 10, 'তখন আল্লাহ তাঁর দাসের প্রতি যা প্রত্যাদেশ করবার, তা প্রত্যাদেশ করলেন।'),
  ('bn.bengali', 53, 11, 'রসূলের অন্তর মিথ্যা বলেনি যা সে দেখেছে।'),
  ('bn.bengali', 53, 12, 'তোমরা কি বিষয়ে বিতর্ক করবে যা সে দেখেছে?'),
  ('bn.bengali', 53, 13, 'নিশ্চয় সে তাকে আরেকবার দেখেছিল,'),
  ('bn.bengali', 53, 14, 'সিদরাতুলমুন্তাহার নিকটে,'),
  ('bn.bengali', 53, 15, 'যার কাছে অবস্থিত বসবাসের জান্নাত।'),
  ('bn.bengali', 53, 16, 'যখন বৃক্ষটি দ্বারা আচ্ছন্ন হওয়ার, তদ্দ্বারা আচ্ছন্ন ছিল।'),
  ('bn.bengali', 53, 17, 'তাঁর দৃষ্টিবিভ্রম হয় নি এবং সীমালংঘনও করেনি।'),
  ('bn.bengali', 53, 18, 'নিশ্চয় সে তার পালনকর্তার মহান নিদর্শনাবলী অবলোকন করেছে।'),
  ('bn.bengali', 53, 19, 'তোমরা কি ভেবে দেখেছ লাত ও ওযযা সম্পর্কে।'),
  ('bn.bengali', 53, 20, 'এবং তৃতীয় আরেকটি মানাত সম্পর্কে?'),
  ('bn.bengali', 53, 21, 'পুত্র-সন্তান কি তোমাদের জন্যে এবং কন্যা-সন্তান আল্লাহর জন্য?'),
  ('bn.bengali', 53, 22, 'এমতাবস্থায় এটা তো হবে খুবই অসংগত বন্টন।'),
  ('bn.bengali', 53, 23, 'এগুলো কতগুলো নাম বৈ নয়, যা তোমরা এবং তোমাদের পূর্ব-পুরুষদের রেখেছ। এর সমর্থনে আল্লাহ কোন দলীল নাযিল করেননি। তারা অনুমান এবং প্রবৃত্তিরই অনুসরণ করে। অথচ তাদের কাছে তাদের পালনকর্তার পক্ষ থেকে পথ নির্দেশ এসেছে।'),
  ('bn.bengali', 53, 24, 'মানুষ যা চায়, তাই কি পায়?'),
  ('bn.bengali', 53, 25, 'অতএব, পরবর্তী ও পূর্ববর্তী সব মঙ্গলই আল্লাহর হাতে।'),
  ('bn.bengali', 53, 26, 'আকাশে অনেক ফেরেশতা রয়েছে। তাদের কোন সুপারিশ ফলপ্রসূ হয় না যতক্ষণ আল্লাহ যার জন্যে ইচ্ছা ও যাকে পছন্দ করেন, অনুমতি না দেন।'),
  ('bn.bengali', 53, 27, 'যারা পরকালে বিশ্বাস করে না, তারাই ফেরেশতাকে নারীবাচক নাম দিয়ে থাকে।'),
  ('bn.bengali', 53, 28, 'অথচ এ বিষয়ে তাদের কোন জ্ঞান নেই। তারা কেবল অনুমানের উপর চলে। অথচ সত্যের ব্যাপারে অনুমান মোটেই ফলপ্রসূ নয়।'),
  ('bn.bengali', 53, 29, 'অতএব যে আমার স্মরণে বিমুখ এবং কেবল পার্থিব জীবনই কামনা করে তার তরফ থেকে আপনি মুখ ফিরিয়ে নিন।'),
  ('bn.bengali', 53, 30, 'তাদের জ্ঞানের পরিধি এ পর্যন্তই। নিশ্চয় আপনার পালনকর্তা ভাল জানেন, কে তাঁর পথ থেকে বিচ্যুত হয়েছে এবং তিনিই ভাল জানেন কে সুপথপ্রাপ্ত হয়েছে।'),
  ('bn.bengali', 53, 31, 'নভোমন্ডল ও ভূমন্ডলে যা কিছু আছে, সবই আল্লাহর, যাতে তিনি মন্দকর্মীদেরকে তাদের কর্মের প্রতিফল দেন এবং সৎকর্মীদেরকে দেন ভাল ফল।'),
  ('bn.bengali', 53, 32, 'যারা বড় বড় গোনাহ ও অশ্লীলকার্য থেকে বেঁচে থাকে ছোটখাট অপরাধ করলেও নিশ্চয় আপনার পালনকর্তার ক্ষমা সুদূর বিস্তৃত। তিনি তোমাদের সম্পর্কে ভাল জানেন, যখন তিনি তোমাদেরকে সৃষ্টি করেছেন মৃত্তিকা থেকে এবং যখন তোমরা মাতৃগর্ভে কচি শিশু ছিলে। অতএব তোমরা আত্নপ্রশংসা করো না। তিনি ভাল জানেন কে সংযমী।'),
  ('bn.bengali', 53, 33, 'আপনি কি তাকে দেখেছেন, যে মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 53, 34, 'এবং দেয় সামান্যই ও পাষাণ হয়ে যায়।'),
  ('bn.bengali', 53, 35, 'তার কাছে কি অদৃশ্যের জ্ঞান আছে যে, সে দেখে?'),
  ('bn.bengali', 53, 36, 'তাকে কি জানানো হয়নি যা আছে মূসার কিতাবে,'),
  ('bn.bengali', 53, 37, 'এবং ইব্রাহীমের কিতাবে, যে তার দায়িত্ব পালন করেছিল?'),
  ('bn.bengali', 53, 38, 'কিতাবে এই আছে যে, কোন ব্যক্তি কারও গোনাহ নিজে বহন করবে না।'),
  ('bn.bengali', 53, 39, 'এবং মানুষ তাই পায়, যা সে করে,'),
  ('bn.bengali', 53, 40, 'তার কর্ম শীঘ্রই দেখা হবে।'),
  ('bn.bengali', 53, 41, 'অতঃপর তাকে পূর্ণ প্রতিদান দেয়া হবে।'),
  ('bn.bengali', 53, 42, 'তোমার পালনকর্তার কাছে সবকিছুর সমাপ্তি,'),
  ('bn.bengali', 53, 43, 'এবং তিনিই হাসান ও কাঁদান'),
  ('bn.bengali', 53, 44, 'এবং তিনিই মারেন ও বাঁচান,'),
  ('bn.bengali', 53, 45, 'এবং তিনিই সৃষ্টি করেন যুগল-পুরুষ ও নারী।'),
  ('bn.bengali', 53, 46, 'একবিন্দু বীর্য থেকে যখন স্খলিত করা হয়।'),
  ('bn.bengali', 53, 47, 'পুনরুত্থানের দায়িত্ব তাঁরই,'),
  ('bn.bengali', 53, 48, 'এবং তিনিই ধনবান করেন ও সম্পদ দান করেন।'),
  ('bn.bengali', 53, 49, 'তিনি শিরা নক্ষত্রের মালিক।'),
  ('bn.bengali', 53, 50, 'তিনিই প্রথম আদ সম্প্রদায়কে ধ্বংস করেছেন,'),
  ('bn.bengali', 53, 51, 'এবং সামুদকেও; অতঃপর কাউকে অব্যহতি দেননি।'),
  ('bn.bengali', 53, 52, 'এবং তাদের পূর্বে নূহের সম্প্রদায়কে, তারা ছিল আরও জালেম ও অবাধ্য।'),
  ('bn.bengali', 53, 53, 'তিনিই জনপদকে শুন্যে উত্তোলন করে নিক্ষেপ করেছেন।'),
  ('bn.bengali', 53, 54, 'অতঃপর তাকে আচ্ছন্ন করে নেয় যা আচ্ছন্ন করার।'),
  ('bn.bengali', 53, 55, 'অতঃপর তুমি তোমার পালনকর্তার কোন অনুগ্রহকে মিথ্যা বলবে?'),
  ('bn.bengali', 53, 56, 'অতীতের সতর্ককারীদের মধ্যে সে-ও একজন সতর্ককারী।'),
  ('bn.bengali', 53, 57, 'কেয়ামত নিকটে এসে গেছে।'),
  ('bn.bengali', 53, 58, 'আল্লাহ ব্যতীত কেউ একে প্রকাশ করতে সক্ষম নয়।'),
  ('bn.bengali', 53, 59, 'তোমরা কি এই বিষয়ে আশ্চর্যবোধ করছ?'),
  ('bn.bengali', 53, 60, 'এবং হাসছ-ক্রন্দন করছ না?'),
  ('bn.bengali', 53, 61, 'তোমরা ক্রীড়া-কৌতুক করছ,'),
  ('bn.bengali', 53, 62, 'অতএব আল্লাহকে সেজদা কর এবং তাঁর এবাদত কর।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 53, 1, 'By the Star when it setteth,'),
  ('en.pickthall', 53, 2, 'Your comrade erreth not, nor is deceived;'),
  ('en.pickthall', 53, 3, 'Nor doth he speak of (his own) desire.'),
  ('en.pickthall', 53, 4, 'It is naught save an inspiration that is inspired,'),
  ('en.pickthall', 53, 5, 'Which one of mighty powers hath taught him,'),
  ('en.pickthall', 53, 6, 'One vigorous; and he grew clear to view'),
  ('en.pickthall', 53, 7, 'When he was on the uppermost horizon.'),
  ('en.pickthall', 53, 8, 'Then he drew nigh and came down'),
  ('en.pickthall', 53, 9, 'Till he was (distant) two bows\' length or even nearer,'),
  ('en.pickthall', 53, 10, 'And He revealed unto His slave that which He revealed.'),
  ('en.pickthall', 53, 11, 'The heart lied not (in seeing) what it saw.'),
  ('en.pickthall', 53, 12, 'Will ye then dispute with him concerning what he seeth?'),
  ('en.pickthall', 53, 13, 'And verily he saw him yet another time'),
  ('en.pickthall', 53, 14, 'By the lote-tree of the utmost boundary,'),
  ('en.pickthall', 53, 15, 'Nigh unto which is the Garden of Abode.'),
  ('en.pickthall', 53, 16, 'When that which shroudeth did enshroud the lote-tree,'),
  ('en.pickthall', 53, 17, 'The eye turned not aside nor yet was overbold.'),
  ('en.pickthall', 53, 18, 'Verily he saw one of the greater revelations of his Lord.'),
  ('en.pickthall', 53, 19, 'Have ye thought upon Al-Lat and Al-\'Uzza'),
  ('en.pickthall', 53, 20, 'And Manat, the third, the other?'),
  ('en.pickthall', 53, 21, 'Are yours the males and His the females?'),
  ('en.pickthall', 53, 22, 'That indeed were an unfair division!'),
  ('en.pickthall', 53, 23, 'They are but names which ye have named, ye and your fathers, for which Allah hath revealed no warrant. They follow but a guess and that which (they) themselves desire. And now the guidance from their Lord hath come unto them.'),
  ('en.pickthall', 53, 24, 'Or shall man have what he coveteth?'),
  ('en.pickthall', 53, 25, 'But unto Allah belongeth the after (life), and the former.'),
  ('en.pickthall', 53, 26, 'And how many angels are in the heavens whose intercession availeth naught save after Allah giveth leave to whom He chooseth and accepteth.'),
  ('en.pickthall', 53, 27, 'Lo! it is those who disbelieve in the Hereafter who name the angels with the names of females.'),
  ('en.pickthall', 53, 28, 'And they have no knowledge thereof. They follow but a guess, and lo! a guess can never take the place of the truth.'),
  ('en.pickthall', 53, 29, 'Then withdraw (O Muhammad) from him who fleeth from Our remembrance and desireth but the life of the world.'),
  ('en.pickthall', 53, 30, 'Such is their sum of knowledge. Lo! thy Lord is Best Aware of him who strayeth, and He is Best Aware of him whom goeth right.'),
  ('en.pickthall', 53, 31, 'And unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth, that He may reward those who do evil with that which they have done, and reward those who do good with goodness.'),
  ('en.pickthall', 53, 32, 'Those who avoid enormities of sin and abominations, save the unwilled offences - (for them) lo! thy Lord is of vast mercy. He is Best Aware of you (from the time) when He created you from the earth, and when ye were hidden in the bellies of your mothers. Therefor ascribe not purity unto yourselves. He is Best Aware of him who wardeth off (evil).'),
  ('en.pickthall', 53, 33, 'Didst thou (O Muhammad) observe him who turned away,'),
  ('en.pickthall', 53, 34, 'And gave a little, then was grudging?'),
  ('en.pickthall', 53, 35, 'Hath he knowledge of the Unseen so that he seeth?'),
  ('en.pickthall', 53, 36, 'Or hath he not had news of what is in the books of Moses'),
  ('en.pickthall', 53, 37, 'And Abraham who paid his debt:'),
  ('en.pickthall', 53, 38, 'That no laden one shall bear another\'s load,'),
  ('en.pickthall', 53, 39, 'And that man hath only that for which he maketh effort,'),
  ('en.pickthall', 53, 40, 'And that his effort will be seen.'),
  ('en.pickthall', 53, 41, 'And afterward he will be repaid for it with fullest payment;'),
  ('en.pickthall', 53, 42, 'And that thy Lord, He is the goal;'),
  ('en.pickthall', 53, 43, 'And that He it is who maketh laugh, and maketh weep,'),
  ('en.pickthall', 53, 44, 'And that He it is Who giveth death and giveth life;'),
  ('en.pickthall', 53, 45, 'And that He createth the two spouses, the male and the female,'),
  ('en.pickthall', 53, 46, 'From a drop (of seed) when it is poured forth;'),
  ('en.pickthall', 53, 47, 'And that He hath ordained the second bringing forth;'),
  ('en.pickthall', 53, 48, 'And that He it is Who enricheth and contenteth;'),
  ('en.pickthall', 53, 49, 'And that He it is Who is the Lord of Sirius;'),
  ('en.pickthall', 53, 50, 'And that He destroyed the former (tribe of) A\'ad,'),
  ('en.pickthall', 53, 51, 'And (the tribe of) Thamud He spared not;'),
  ('en.pickthall', 53, 52, 'And the folk of Noah aforetime, Lo! they were more unjust and more rebellious;'),
  ('en.pickthall', 53, 53, 'And Al-Mu\'tafikah He destroyed'),
  ('en.pickthall', 53, 54, 'So that there covered them that which did cover.'),
  ('en.pickthall', 53, 55, 'Concerning which then, of the bounties of thy Lord, canst thou dispute?'),
  ('en.pickthall', 53, 56, 'This is a warner of the warners of old.'),
  ('en.pickthall', 53, 57, 'The threatened Hour is nigh.'),
  ('en.pickthall', 53, 58, 'None beside Allah can disclose it.'),
  ('en.pickthall', 53, 59, 'Marvel ye then at this statement,'),
  ('en.pickthall', 53, 60, 'And laugh and not weep,'),
  ('en.pickthall', 53, 61, 'While ye amuse yourselves?'),
  ('en.pickthall', 53, 62, 'Rather prostrate yourselves before Allah and serve Him.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 53, 1, 'By the Star when it goes down,-'),
  ('en.yusufali', 53, 2, 'Your Companion is neither astray nor being misled.'),
  ('en.yusufali', 53, 3, 'Nor does he say (aught) of (his own) Desire.'),
  ('en.yusufali', 53, 4, 'It is no less than inspiration sent down to him:'),
  ('en.yusufali', 53, 5, 'He was taught by one Mighty in Power,'),
  ('en.yusufali', 53, 6, 'Endued with Wisdom: for he appeared (in stately form);'),
  ('en.yusufali', 53, 7, 'While he was in the highest part of the horizon:'),
  ('en.yusufali', 53, 8, 'Then he approached and came closer,'),
  ('en.yusufali', 53, 9, 'And was at a distance of but two bow-lengths or (even) nearer;'),
  ('en.yusufali', 53, 10, 'So did (Allah) convey the inspiration to His Servant- (conveyed) what He (meant) to convey.'),
  ('en.yusufali', 53, 11, 'The (Prophet\'s) (mind and) heart in no way falsified that which he saw.'),
  ('en.yusufali', 53, 12, 'Will ye then dispute with him concerning what he saw?'),
  ('en.yusufali', 53, 13, 'For indeed he saw him at a second descent,'),
  ('en.yusufali', 53, 14, 'Near the Lote-tree beyond which none may pass:'),
  ('en.yusufali', 53, 15, 'Near it is the Garden of Abode.'),
  ('en.yusufali', 53, 16, 'Behold, the Lote-tree was shrouded (in mystery unspeakable!)'),
  ('en.yusufali', 53, 17, '(His) sight never swerved, nor did it go wrong!'),
  ('en.yusufali', 53, 18, 'For truly did he see, of the Signs of his Lord, the Greatest!'),
  ('en.yusufali', 53, 19, 'Have ye seen Lat. and \'Uzza,'),
  ('en.yusufali', 53, 20, 'And another, the third (goddess), Manat?'),
  ('en.yusufali', 53, 21, 'What! for you the male sex, and for Him, the female?'),
  ('en.yusufali', 53, 22, 'Behold, such would be indeed a division most unfair!'),
  ('en.yusufali', 53, 23, 'These are nothing but names which ye have devised,- ye and your fathers,- for which Allah has sent down no authority (whatever). They follow nothing but conjecture and what their own souls desire!- Even though there has already come to them Guidance from their Lord!'),
  ('en.yusufali', 53, 24, 'Nay, shall man have (just) anything he hankers after?'),
  ('en.yusufali', 53, 25, 'But it is to Allah that the End and the Beginning (of all things) belong.'),
  ('en.yusufali', 53, 26, 'How many-so-ever be the angels in the heavens, their intercession will avail nothing except after Allah has given leave for whom He pleases and that he is acceptable to Him.'),
  ('en.yusufali', 53, 27, 'Those who believe not in the Hereafter, name the angels with female names.'),
  ('en.yusufali', 53, 28, 'But they have no knowledge therein. They follow nothing but conjecture; and conjecture avails nothing against Truth.'),
  ('en.yusufali', 53, 29, 'Therefore shun those who turn away from Our Message and desire nothing but the life of this world.'),
  ('en.yusufali', 53, 30, 'That is as far as knowledge will reach them. Verily thy Lord knoweth best those who stray from His Path, and He knoweth best those who receive guidance.'),
  ('en.yusufali', 53, 31, 'Yea, to Allah belongs all that is in the heavens and on earth: so that He rewards those who do evil, according to their deeds, and He rewards those who do good, with what is best.'),
  ('en.yusufali', 53, 32, 'Those who avoid great sins and shameful deeds, only (falling into) small faults,- verily thy Lord is ample in forgiveness. He knows you well when He brings you out of the earth, And when ye are hidden in your mothers\' wombs. Therefore justify not yourselves: He knows best who it is that guards against evil.'),
  ('en.yusufali', 53, 33, 'Seest thou one who turns back,'),
  ('en.yusufali', 53, 34, 'Gives a little, then hardens (his heart)?'),
  ('en.yusufali', 53, 35, 'What! Has he knowledge of the Unseen so that he can see?'),
  ('en.yusufali', 53, 36, 'Nay, is he not acquainted with what is in the Books of Moses-'),
  ('en.yusufali', 53, 37, 'And of Abraham who fulfilled his engagements?-'),
  ('en.yusufali', 53, 38, 'Namely, that no bearer of burdens can bear the burden of another;'),
  ('en.yusufali', 53, 39, 'That man can have nothing but what he strives for;'),
  ('en.yusufali', 53, 40, 'That (the fruit of) his striving will soon come in sight:'),
  ('en.yusufali', 53, 41, 'Then will he be rewarded with a reward complete;'),
  ('en.yusufali', 53, 42, 'That to thy Lord is the final Goal;'),
  ('en.yusufali', 53, 43, 'That it is He Who granteth Laughter and Tears;'),
  ('en.yusufali', 53, 44, 'That it is He Who granteth Death and Life;'),
  ('en.yusufali', 53, 45, 'That He did create in pairs,- male and female,'),
  ('en.yusufali', 53, 46, 'From a seed when lodged (in its place);'),
  ('en.yusufali', 53, 47, 'That He hath promised a Second Creation (Raising of the Dead);'),
  ('en.yusufali', 53, 48, 'That it is He Who giveth wealth and satisfaction;'),
  ('en.yusufali', 53, 49, 'That He is the Lord of Sirius (the Mighty Star);'),
  ('en.yusufali', 53, 50, 'And that it is He Who destroyed the (powerful) ancient \'Ad (people),'),
  ('en.yusufali', 53, 51, 'And the Thamud nor gave them a lease of perpetual life.'),
  ('en.yusufali', 53, 52, 'And before them, the people of Noah, for that they were (all) most unjust and most insolent transgressors,'),
  ('en.yusufali', 53, 53, 'And He destroyed the Overthrown Cities (of Sodom and Gomorrah).'),
  ('en.yusufali', 53, 54, 'So that (ruins unknown) have covered them up.'),
  ('en.yusufali', 53, 55, 'Then which of the gifts of thy Lord, (O man,) wilt thou dispute about?'),
  ('en.yusufali', 53, 56, 'This is a Warner, of the (series of) Warners of old!'),
  ('en.yusufali', 53, 57, 'The (Judgment) ever approaching draws nigh:'),
  ('en.yusufali', 53, 58, 'No (soul) but Allah can lay it bare.'),
  ('en.yusufali', 53, 59, 'Do ye then wonder at this recital?'),
  ('en.yusufali', 53, 60, 'And will ye laugh and not weep,-'),
  ('en.yusufali', 53, 61, 'Wasting your time in vanities?'),
  ('en.yusufali', 53, 62, 'But fall ye down in prostration to Allah, and adore (Him)!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 53, 1, 'Wannajmi izaa hawaa'),
  ('en.transliteration', 53, 2, 'Maa dalla saahibukum wa maa ghawaa'),
  ('en.transliteration', 53, 3, 'Wa maa yyantiqu \'anilhawaaa'),
  ('en.transliteration', 53, 4, 'In huwa illaa Wahyuny yoohaa'),
  ('en.transliteration', 53, 5, '\'Allamahoo shadeedul quwaa'),
  ('en.transliteration', 53, 6, 'Zoo mirratin fastawaa'),
  ('en.transliteration', 53, 7, 'Wa huwa bil ufuqil a\'laa'),
  ('en.transliteration', 53, 8, 'Summa danaa fatadalla'),
  ('en.transliteration', 53, 9, 'Fakaana qaaba qawsaini aw adnaa'),
  ('en.transliteration', 53, 10, 'Fa awhaaa ilaa \'abdihee maaa awhaa'),
  ('en.transliteration', 53, 11, 'Maa kazabal fu\'aadu maa ra aa'),
  ('en.transliteration', 53, 12, 'Afatumaaroonahoo \'alaa maayaraa'),
  ('en.transliteration', 53, 13, 'Wa laqad ra aahu nazlatan ukhraa'),
  ('en.transliteration', 53, 14, '\'Inda sidratil muntaha'),
  ('en.transliteration', 53, 15, '\'Indahaa jannatul maawaa'),
  ('en.transliteration', 53, 16, 'Iz yaghshas sidrata maa yaghshaa'),
  ('en.transliteration', 53, 17, 'Maa zaaghal basaru wa maa taghaa'),
  ('en.transliteration', 53, 18, 'Laqad ra aa min aayaati Rabbihil kubraaa'),
  ('en.transliteration', 53, 19, 'Afara\'aytumul laata wal \'uzzaa'),
  ('en.transliteration', 53, 20, 'Wa manaatas saalisatal ukhraa'),
  ('en.transliteration', 53, 21, 'A-lakumuz zakaru wa lahul unsaa'),
  ('en.transliteration', 53, 22, 'Tilka izan qismatun deezaa'),
  ('en.transliteration', 53, 23, 'In hiya illaaa asmaaa\'un sammaitumoohaaa antum wa aabaaa\'ukum maaa anzalal laahu bihaa min sultaan; inyyattabi\'oona illaz zanna wa maa tahwal anfusu wa laqad jaaa\'ahum mir Rabbihimul hudaa'),
  ('en.transliteration', 53, 24, 'Am lil insaani maa taman naa'),
  ('en.transliteration', 53, 25, 'Falillaahil aakhiratu wal oolaa'),
  ('en.transliteration', 53, 26, 'Wa kam mim malakin fissamaawaati laa tughnee shafaa\'atuhum shai\'an illaa mim ba\'di anyyaazanal laahu limany yashaaa\'u wa yardaa'),
  ('en.transliteration', 53, 27, 'innal lazeena laa yu\'minoona bil aakhirati la yusammoonal malaaa\'ikata tasmiyatal unsaa'),
  ('en.transliteration', 53, 28, 'Wa maa lahum bihee min \'ilmin iny yattabi\'oona illaz zanna wa innaz zanna laa yughnee minal haqqi shai\'aa'),
  ('en.transliteration', 53, 29, 'Fa a\'rid \'am man tawallaa \'an zikrinaa wa lam yurid illal hayaatad dunyaa'),
  ('en.transliteration', 53, 30, 'Zalika mablaghuhum minal \'ilm; inna rabbaka huwa a\'lamu biman dalla \'an sabee lihee wa huwa a\'lamu bimanih tadaa'),
  ('en.transliteration', 53, 31, 'Wa lillaahi maa fis samaawaati wa maa fil ardi liyajziyal lazeena asaaa\'oo bimaa \'amiloo wa yajziyal lazeena ahsanoo bilhusnaa'),
  ('en.transliteration', 53, 32, 'Allazeena yajtaniboona kabaaa\'iral ismi walfawaa hisha illal lamam; inna rabbaka waasi\'ul maghfirah; huwa a\'lamu bikum iz ansha akum minal ardi wa iz antum ajinnatun fee butooni umma haatikum falaa tuzakkooo anfusakum huwa a\'lamu bimanit taqaa'),
  ('en.transliteration', 53, 33, 'Afara\'ayatal lazee tawallaa'),
  ('en.transliteration', 53, 34, 'Wa a\'taa qaleelanw wa akdaa'),
  ('en.transliteration', 53, 35, 'A\'indahoo \'ilmul ghaibi fahuwa yaraa'),
  ('en.transliteration', 53, 36, 'Am lam yunabbaa bimaa fee suhuhfi Moosa'),
  ('en.transliteration', 53, 37, 'Wa Ibraaheemal lazee waffaaa'),
  ('en.transliteration', 53, 38, 'Allaa taziru waaziratunw wizra ukhraa'),
  ('en.transliteration', 53, 39, 'Wa al laisa lil insaani illaa maa sa\'aa'),
  ('en.transliteration', 53, 40, 'Wa anna sa\'yahoo sawfa yuraa'),
  ('en.transliteration', 53, 41, 'Summa yujzaahul jazaaa \'al awfaa'),
  ('en.transliteration', 53, 42, 'Wa anna ilaa rabbikal muntahaa'),
  ('en.transliteration', 53, 43, 'Wa annahoo huwa adhaka wa abkaa'),
  ('en.transliteration', 53, 44, 'Wa annahoo huwa amaata wa ahyaa'),
  ('en.transliteration', 53, 45, 'Wa annahoo khalaqaz zawjainiz zakara wal unsaa'),
  ('en.transliteration', 53, 46, 'Min nutfatin izaa tumnaa'),
  ('en.transliteration', 53, 47, 'Wa anna \'alaihin nash atal ukhraa'),
  ('en.transliteration', 53, 48, 'Wa annahoo huwa aghnaa wa aqnaa'),
  ('en.transliteration', 53, 49, 'Wa annahoo huwa rabbush shi\'raa'),
  ('en.transliteration', 53, 50, 'Wa annahooo ahlak a \'Aadanil oolaa'),
  ('en.transliteration', 53, 51, 'Wa samooda famaaa abqaa'),
  ('en.transliteration', 53, 52, 'Wa qawma Noohim min qablu innahum kaanoo hum azlama wa atghaa'),
  ('en.transliteration', 53, 53, 'Wal mu\'tafikata ahwaa'),
  ('en.transliteration', 53, 54, 'Faghashshaahaa maa ghashshaa'),
  ('en.transliteration', 53, 55, 'Fabi ayyi aalaaa\'i Rabbika tatamaaraa'),
  ('en.transliteration', 53, 56, 'Haazaa nazeerum minan nuzuril oolaa'),
  ('en.transliteration', 53, 57, 'Azifatil laazifah'),
  ('en.transliteration', 53, 58, 'Laisa lahaa min doonil laahi kaashifah'),
  ('en.transliteration', 53, 59, 'Afamin hazal hadeesi ta\'jaboon'),
  ('en.transliteration', 53, 60, 'Wa tadhakoona wa laa tabkoon'),
  ('en.transliteration', 53, 61, 'Wa antum saamidoon'),
  ('en.transliteration', 53, 62, 'Fasjudoo lillaahi wa\'budoo')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 53, 1, 'ستارے کی قسم ہے جب وہ ڈوبنے لگے'),
  ('ur.ahmedali', 53, 2, 'تمہارا رفیق نہ گمراہ ہوا ہے اورنہ بہکا ہے'),
  ('ur.ahmedali', 53, 3, 'اور نہ وہ اپنی خواہش سے کچھ کہتا ہے'),
  ('ur.ahmedali', 53, 4, 'یہ تو وحی ہے جو اس پر آتی ہے'),
  ('ur.ahmedali', 53, 5, 'بڑے طاقتور (جبرائیل) نے اسے سکھایا ہے'),
  ('ur.ahmedali', 53, 6, 'جو بڑا زور آور ہے پس وہ قائم ہوا (اصلی صورت میں)'),
  ('ur.ahmedali', 53, 7, 'اور وہ (آسمان کے) اونچے کنارے پر تھا'),
  ('ur.ahmedali', 53, 8, 'پھر نزدیک ہوا پھر اور بھی قریب ہوا'),
  ('ur.ahmedali', 53, 9, 'پھر فاصلہ دو کمان کے برابر تھا یا اس سے بھی کم'),
  ('ur.ahmedali', 53, 10, 'پھر اس نے الله کےبندے کے دل میں القا کیا جو کچھ القا کیا دل نے'),
  ('ur.ahmedali', 53, 11, 'جھوٹ نہیں کہا تھا جو دیکھا تھا'),
  ('ur.ahmedali', 53, 12, 'پھر جو کچھ اس نے دیکھا تم اس میں جھگڑتے ہو'),
  ('ur.ahmedali', 53, 13, 'اور اس نے اس کو ایک بار اور بھی دیکھا ہے'),
  ('ur.ahmedali', 53, 14, 'سدرة المنتہیٰ کے پاس'),
  ('ur.ahmedali', 53, 15, 'جس کے پاس جنت الماویٰ ہے'),
  ('ur.ahmedali', 53, 16, 'جب کہ اس سدرة پر چھا رہا تھا جو چھا رہا تھا (یعنی نور)'),
  ('ur.ahmedali', 53, 17, 'نہ تو نظر بہکی نہ حد سے بڑھی'),
  ('ur.ahmedali', 53, 18, 'بے شک اس نے اپنے رب کی بڑی بڑی نشانیاں دیکھیں'),
  ('ur.ahmedali', 53, 19, 'پھر کیا تم نے لات اور عزیٰ کو بھی دیکھاہے'),
  ('ur.ahmedali', 53, 20, 'اور تیسرے منات گھٹیا کو (دیکھا ہے)'),
  ('ur.ahmedali', 53, 21, 'کیا تمہارے لیے بیٹے اور اس کے لیے بیٹیاں ہیں'),
  ('ur.ahmedali', 53, 22, 'تب تو یہ بہت ہی بری تقسیم ہے'),
  ('ur.ahmedali', 53, 23, 'یہ تو صرف نام ہی نام ہیں جو تم نے اور تمہارے باپ دادا نے گھڑ لیے ہیں جن پر خدا نے کوئی سندبھی نہیں اتاری وہ محض وہم اور اپنی خواہش کی پیروی کرتے ہیں حالانکہ ان کے پاس ان کے رب کے ہاں سے ہدایت آ چکی ہے'),
  ('ur.ahmedali', 53, 24, 'پھر کیا انسان کو وہی مل جاتا ہے جس کی تمنا کرتا ہے'),
  ('ur.ahmedali', 53, 25, 'پس آخرت اور دنیا الله ہی کے اختیار میں ہے'),
  ('ur.ahmedali', 53, 26, 'اور بہت سے فرشتے آسمان میں ہیں کہ جن کی شفاعت کسی کے کچھ بھی کام نہیں آتی مگر اس کے بعدکہ الله جس کے لیے چاہے اجازت دے اور پسند کرے'),
  ('ur.ahmedali', 53, 27, 'بے شک جو لوگ آخرت پر ایمان نہیں لاتے وہ فرشتوں کے عورتوں کے سے نام رکھتے ہیں'),
  ('ur.ahmedali', 53, 28, 'اور اس بات کو کچھ بھی نہیں جانتے محص وہم پر چلتے ہیں اوروہم حق بات کی جگہ کچھ بھی کام نہیں آتا'),
  ('ur.ahmedali', 53, 29, 'پھر تم اس کی پرواہ نہ کرو جس نے ہماری یاد سے منہ پھیر لیا ہے اور صرف دنیا ہی کی زندگی چاہتا ہے'),
  ('ur.ahmedali', 53, 30, 'ان کی سمجھ کی یہیں تک رسائی ہے بے شک آپ کا رب اس کو خوب جانتا ہے جو اس کے راستہ سے بہکا اور اس کو بھی خوب جانتا ہے جو راہ پر آیا'),
  ('ur.ahmedali', 53, 31, 'اور الله ہی کا ہے جو کچھ آسمانوں اور زمین میں ہے تاکہ براکرنے والوں کو ان کے بدلہ دے اور نیکی کرنے والوں کو نیک بدلہ دے'),
  ('ur.ahmedali', 53, 32, 'وہ جو بڑے گناہوں اور بے حیائی کی باتوں سے بچتے ہیں مگر صغیرہ گناہوں سے بے شک آپ کا رب بڑی وسیع بخشش والا ہے وہ تمہیں خوب جانتا ہے جب کہ تمہیں زمین سے پیدا کیا تھا اور جب کہ تم اپنی ماں کے پیٹ میں بچے تھے پس اپنے آپ کو پاک نہ سمجھو وہ پرہیزگار کو خوب جانتا ہے'),
  ('ur.ahmedali', 53, 33, 'بھلا آپ نے اس شخص کو دیکھا جس نے منہ پھیر لیا'),
  ('ur.ahmedali', 53, 34, 'اور تھوڑا سا دیا اور سخت دل ہو گیا'),
  ('ur.ahmedali', 53, 35, 'کیا اس کے پاس غیب کا علم ہے کہ وہ دیکھ رہا ہے'),
  ('ur.ahmedali', 53, 36, 'کیا اسے ان باتوں کی خبر نہیں پہنچی جو موسیٰ کے صحیفوں میں ہیں'),
  ('ur.ahmedali', 53, 37, 'اورابراھیم کے جس نے (اپنا عہد) پورا کیا'),
  ('ur.ahmedali', 53, 38, 'وہ یہ کہ کوئی کسی کا بوجھ نہیں اٹھائے گا'),
  ('ur.ahmedali', 53, 39, 'اور یہ کہ انسان کو وہی ملتا ہے جو کرتا ہے'),
  ('ur.ahmedali', 53, 40, 'اور یہ کہ اس کی کوشش جلد دیکھی جائے گی'),
  ('ur.ahmedali', 53, 41, 'پھر اسے پورا بدلہ دیا جائے گا'),
  ('ur.ahmedali', 53, 42, 'اوریہ کہ سب کو آپ کے رب ہی کی طرف پہنچتا ہے'),
  ('ur.ahmedali', 53, 43, 'اور یہ کہ وہی ہنساتا ہے اوررلاتا ہے'),
  ('ur.ahmedali', 53, 44, 'اور یہ کہ وہی مارتا ہے اور زندہ کرتا ہے'),
  ('ur.ahmedali', 53, 45, 'اور یہ کہ اسی نے جوڑا نر اور مادہ کا پیدا کیا ہے'),
  ('ur.ahmedali', 53, 46, 'ایک بوند سے جب کہ وہ ٹپکائی جائے'),
  ('ur.ahmedali', 53, 47, 'اور یہ کہ دوسری بارزندہ کر کے اٹھانا اسی کے ذمہ ہے'),
  ('ur.ahmedali', 53, 48, 'اور یہ کہ وہی غنی اور سرمایہ دار کرتا ہے'),
  ('ur.ahmedali', 53, 49, 'اور یہ کہ وہی شعریٰ کا رب ہے'),
  ('ur.ahmedali', 53, 50, 'اور یہ کہ اسی نے عاد اولیٰ کو ہلاک کیا تھا'),
  ('ur.ahmedali', 53, 51, 'اور ثمود کو پس اسے باقی نہ چھوڑا'),
  ('ur.ahmedali', 53, 52, 'اور اس سے پہلے نوح کی قوم کو بے شک وہ زیادہ ظالم اور زيادہ سرکش تھے'),
  ('ur.ahmedali', 53, 53, 'اور الٹی بستی کو اس نے دے ٹپکا'),
  ('ur.ahmedali', 53, 54, 'پس اس پر وہ (تباہی) چھا گئی جوچھا گئی'),
  ('ur.ahmedali', 53, 55, 'پس اپنے رب کی کون کون سی نعمت میں تو شک کرے گا'),
  ('ur.ahmedali', 53, 56, 'یہ بھی ایک ڈرانے والا ہے پہلے ڈرانے والوں میں سے'),
  ('ur.ahmedali', 53, 57, 'آنے والی قریب آ پہنچی'),
  ('ur.ahmedali', 53, 58, 'سوائے الله کے اسے کوئی ہٹانے والا نہیں'),
  ('ur.ahmedali', 53, 59, 'پس کیا اس بات سے تم تعجب کرتے ہو'),
  ('ur.ahmedali', 53, 60, 'اور ہنستے ہو اور روتے نہیں'),
  ('ur.ahmedali', 53, 61, 'اور تم کھیل رہے ہو'),
  ('ur.ahmedali', 53, 62, 'پس الله کے آگے سجدہ کرو اور اس کی عبادت کرو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 53, 1, 'Batmakta olan yıldıza and olsun ki,'),
  ('tr.diyanet', 53, 2, 'Arkadaşınız (Muhammed) sapmamış ve azmamıştır.'),
  ('tr.diyanet', 53, 3, 'O, kendiliğinden konuşmamaktadır.'),
  ('tr.diyanet', 53, 4, 'Onun konuşması ancak, bildirilen bir vahy iledir.'),
  ('tr.diyanet', 53, 5, 'Ona, çetin kuvvetlere sahip ve güçlü olan Cebrail öğretmiştir; en yüksek ufukta iken doğruluvermiş.'),
  ('tr.diyanet', 53, 6, 'Ona, çetin kuvvetlere sahip ve güçlü olan Cebrail öğretmiştir; en yüksek ufukta iken doğruluvermiş.'),
  ('tr.diyanet', 53, 7, 'Ona, çetin kuvvetlere sahip ve güçlü olan Cebrail öğretmiştir; en yüksek ufukta iken doğruluvermiş.'),
  ('tr.diyanet', 53, 8, 'Sonra yaklaşmış ve inmiştir.'),
  ('tr.diyanet', 53, 9, 'Araları iki yay aralığı kadar veya daha da yakın oldu.'),
  ('tr.diyanet', 53, 10, 'Allah o anda kuluna vahyedeceğini etti.'),
  ('tr.diyanet', 53, 11, 'Gözünün gördüğünü gönlü yalanlamadı.'),
  ('tr.diyanet', 53, 12, 'Ey inkarcılar! Onun gördüğü şey hakkında kendisi ile tartışır mısınız?'),
  ('tr.diyanet', 53, 13, 'And olsun ki o, Cebrail\'i sınırın sonunda başka bir inişinde de görmüştür.'),
  ('tr.diyanet', 53, 14, 'And olsun ki o, Cebrail\'i sınırın sonunda başka bir inişinde de görmüştür.'),
  ('tr.diyanet', 53, 15, 'Orada Me\'va cenneti vardır.'),
  ('tr.diyanet', 53, 16, 'Sidre\'yi bürüyen bürüyordu.'),
  ('tr.diyanet', 53, 17, 'Gözü oradan ne kaydı ve ne de onu aştı.'),
  ('tr.diyanet', 53, 18, 'And olsun ki Rabbinin varlığının büyük delillerini gördü.'),
  ('tr.diyanet', 53, 19, 'Ey inkarcılar! Şimdi Lat, Uzza ve bundan başka üçüncüleri olan Menat\'ın ne olduğunu söyler misiniz?'),
  ('tr.diyanet', 53, 20, 'Ey inkarcılar! Şimdi Lat, Uzza ve bundan başka üçüncüleri olan Menat\'ın ne olduğunu söyler misiniz?'),
  ('tr.diyanet', 53, 21, 'Demek erkekler sizin, dişiler Allah\'ın mı?'),
  ('tr.diyanet', 53, 22, 'Öyleyse bu haksız bir paylaşma;'),
  ('tr.diyanet', 53, 23, 'Bunlar sizin ve babalarınızın taktığı adlardan başka bir şey değildir. Allah onları destekleyen bir delil indirmemiştir. Onlar sadece sanıya ve canlarının istediğine uymaktadırlar. Oysa onlara Rablerinden and olsun ki doğruluk rehberi gelmiştir.'),
  ('tr.diyanet', 53, 24, 'Yoksa, her umduğu şey insanın mıdır?'),
  ('tr.diyanet', 53, 25, 'Hayatın ilki de sonu da Allah\'ındır.'),
  ('tr.diyanet', 53, 26, 'Allah, dilediğine ve hoşnut olduğuna izin vermedikçe, göklerde bulunan nice meleklerin şefaati bir şeye yaramaz.'),
  ('tr.diyanet', 53, 27, 'Doğrusu ahirete inanmayanlar, meleklere "dişi" adını takarlar.'),
  ('tr.diyanet', 53, 28, 'Oysa onların bu hususta bir bilgileri yoktur, sadece sanıya uyarlar. Sanı ise şüphesiz gerçeği ifade etmez.'),
  ('tr.diyanet', 53, 29, 'Bizi anmaktan yüz çevirenlere ve dünya hayatından başka bir şey istemeyenlere aldırma.'),
  ('tr.diyanet', 53, 30, 'Bu onların ulaştıkları bilginin seviyesini gösterir. Doğrusu Rabbin yolundan sapmış olanı pek iyi bilir, doğru yolda olanı da çok iyi bilir.'),
  ('tr.diyanet', 53, 31, 'Göklerde olanlar ve yerde olanlar Allah\'ındır ki O, kötülük yapanlara işlerinin karşılığını verir; iyi davrananlara, ufak tefek kabahatleri bir yana büyük günahlardan ve hayasızlıklardan kaçınanlara işlediklerinden daha iyisiyle karşılığını verir. Doğrusu Rabbinin bağışı boldur. Sizi yerden var ederken ve siz annelerinizin karınlarında cenin halinde iken sizleri çok iyi bilen O\'dur. Kendinizi temize çıkarmayın. O, sakınanı çok iyi bilir.'),
  ('tr.diyanet', 53, 32, 'Göklerde olanlar ve yerde olanlar Allah\'ındır ki O, kötülük yapanlara işlerinin karşılığını verir; iyi davrananlara, ufak tefek kabahatleri bir yana büyük günahlardan ve hayasızlıklardan kaçınanlara işlediklerinden daha iyisiyle karşılığını verir. Doğrusu Rabbinin bağışı boldur. Sizi yerden var ederken ve siz annelerinizin karınlarında cenin halinde iken sizleri çok iyi bilen O\'dur. Kendinizi temize çıkarmayın. O, sakınanı çok iyi bilir.'),
  ('tr.diyanet', 53, 33, 'Yüz çevireni ve malından biraz verip sonra vermemekte direneni gördün mü?"'),
  ('tr.diyanet', 53, 34, 'Yüz çevireni ve malından biraz verip sonra vermemekte direneni gördün mü?"'),
  ('tr.diyanet', 53, 35, 'Görülmeyenin ilmi yanında da o mu görüyor?'),
  ('tr.diyanet', 53, 36, 'Yoksa Musa\'nın ve sözünü yerine getiren İbrahim\'in kitablarında olanlar kendisine bildirilmedi mi ki?'),
  ('tr.diyanet', 53, 37, 'Yoksa Musa\'nın ve sözünü yerine getiren İbrahim\'in kitablarında olanlar kendisine bildirilmedi mi ki?'),
  ('tr.diyanet', 53, 38, 'Hiç bir günahkar başkasının günah yükünü yüklenmez;'),
  ('tr.diyanet', 53, 39, 'İnsan ancak çalıştığına erişir.'),
  ('tr.diyanet', 53, 40, 'Onun çalışması şüphesiz görülecektir.'),
  ('tr.diyanet', 53, 41, 'Sonra ona karşılığı eksiksiz verilecektir.'),
  ('tr.diyanet', 53, 42, 'Doğrusu son varış Rabbinedir.'),
  ('tr.diyanet', 53, 43, 'Doğrusu, güldüren de ağlatan da O\'dur.'),
  ('tr.diyanet', 53, 44, 'Doğrusu dirilten de öldüren de O\'dur.'),
  ('tr.diyanet', 53, 45, 'Doğrusu, atıldığında meniden erkek ve dişiyi, iki çifti yaratan O\'dur.'),
  ('tr.diyanet', 53, 46, 'Doğrusu, atıldığında meniden erkek ve dişiyi, iki çifti yaratan O\'dur.'),
  ('tr.diyanet', 53, 47, 'Doğrusu ölümden sonra tekrar dirilten de O\'dur.'),
  ('tr.diyanet', 53, 48, 'Doğrusu zengin eden de varlıklı kılan da O\'dur.'),
  ('tr.diyanet', 53, 49, 'Doğrusu Şira yıldızının Rabbi O\'dur.'),
  ('tr.diyanet', 53, 50, 'İlk Ad milletini, Semud milletini yok edip geri bırakmayan O\'dur.'),
  ('tr.diyanet', 53, 51, 'İlk Ad milletini, Semud milletini yok edip geri bırakmayan O\'dur.'),
  ('tr.diyanet', 53, 52, 'Daha önce de Nuh milletini yok eden O\'dur; çünkü onlar çok zalim ve pek taşkın kimselerdi.'),
  ('tr.diyanet', 53, 53, 'Lut milletinin kasabalarını yere batıran, onları gömdükçe gömen O\'dur.'),
  ('tr.diyanet', 53, 54, 'Lut milletinin kasabalarını yere batıran, onları gömdükçe gömen O\'dur.'),
  ('tr.diyanet', 53, 55, 'Ey kişi! Rabbinin hangi nimetinden şüpheye düşersin?'),
  ('tr.diyanet', 53, 56, 'İşte ilk uyaranlar gibi bu da bir uyarandır.'),
  ('tr.diyanet', 53, 57, 'Kıyamet yaklaştıkça yaklaşmıştır.'),
  ('tr.diyanet', 53, 58, 'Onu Allah\'tan başka ortaya koyacak yoktur.'),
  ('tr.diyanet', 53, 59, 'Bu söze mi şaşıyorsunuz?'),
  ('tr.diyanet', 53, 60, 'Gülüyorsunuz... Ağlamıyorsunuz.'),
  ('tr.diyanet', 53, 61, 'Habersiz oyalanmaktasınız.'),
  ('tr.diyanet', 53, 62, 'Artık secdeye varın, Allah\'a kulluk edin.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 53, 1, 'Demi bintang ketika terbenam.'),
  ('id.indonesian', 53, 2, 'kawanmu (Muhammad) tidak sesat dan tidak pula keliru.'),
  ('id.indonesian', 53, 3, 'dan tiadalah yang diucapkannya itu (Al-Quran) menurut kemauan hawa nafsunya.'),
  ('id.indonesian', 53, 4, 'Ucapannya itu tiada lain hanyalah wahyu yang diwahyukan (kepadanya).'),
  ('id.indonesian', 53, 5, 'yang diajarkan kepadanya oleh (Jibril) yang sangat kuat.'),
  ('id.indonesian', 53, 6, 'yang mempunyai akal yang cerdas; dan (Jibril itu) menampakkan diri dengan rupa yang asli.'),
  ('id.indonesian', 53, 7, 'sedang dia berada di ufuk yang tinggi.'),
  ('id.indonesian', 53, 8, 'Kemudian dia mendekat, lalu bertambah dekat lagi.'),
  ('id.indonesian', 53, 9, 'maka jadilah dia dekat (pada Muhammad sejarak) dua ujung busur panah atau lebih dekat (lagi).'),
  ('id.indonesian', 53, 10, 'Lalu dia menyampaikan kepada hamba-Nya (Muhammad) apa yang telah Allah wahyukan.'),
  ('id.indonesian', 53, 11, 'Hatinya tidak mendustakan apa yang telah dilihatnya.'),
  ('id.indonesian', 53, 12, 'Maka apakah kaum (musyrik Mekah) hendak membantahnya tentang apa yang telah dilihatnya?'),
  ('id.indonesian', 53, 13, 'Dan sesungguhnya Muhammad telah melihat Jibril itu (dalam rupanya yang asli) pada waktu yang lain,'),
  ('id.indonesian', 53, 14, '(yaitu) di Sidratil Muntaha.'),
  ('id.indonesian', 53, 15, 'Di dekatnya ada surga tempat tinggal,'),
  ('id.indonesian', 53, 16, '(Muhammad melihat Jibril) ketika Sidratil Muntaha diliputi oleh sesuatu yang meliputinya.'),
  ('id.indonesian', 53, 17, 'Penglihatannya (muhammad) tidak berpaling dari yang dilihatnya itu dan tidak (pula) melampauinya.'),
  ('id.indonesian', 53, 18, 'Sesungguhnya dia telah melihat sebahagian tanda-tanda (kekuasaan) Tuhannya yang paling besar.'),
  ('id.indonesian', 53, 19, 'Maka apakah patut kamu (hai orang-orang musyrik) menganggap al Lata dan al Uzza,'),
  ('id.indonesian', 53, 20, 'dan Manah yang ketiga, yang paling terkemudian (sebagai anak perempuan Allah)?'),
  ('id.indonesian', 53, 21, 'Apakah (patut) untuk kamu (anak) laki-laki dan untuk Allah (anak) perempuan?'),
  ('id.indonesian', 53, 22, 'Yang demikian itu tentulah suatu pembagian yang tidak adil.'),
  ('id.indonesian', 53, 23, 'Itu tidak lain hanyalah nama-nama yang kamu dan bapak-bapak kamu mengadakannya; Allah tidak menurunkan suatu keteranganpun untuk (menyembah)nya. Mereka tidak lain hanyalah mengikuti sangkaan-sangkaan, dan apa yang diingini oleh hawa nafsu mereka dan sesungguhnya telah datang petunjuk kepada mereka dari Tuhan mereka.'),
  ('id.indonesian', 53, 24, 'Atau apakah manusia akan mendapat segala yang dicita-citakannya?'),
  ('id.indonesian', 53, 25, '(Tidak), maka hanya bagi Allah kehidupan akhirat dan kehidupan dunia.'),
  ('id.indonesian', 53, 26, 'Dan berapa banyaknya malaikat di langit, syafa\'at mereka sedikitpun tidak berguna, kecuali sesudah Allah mengijinkan bagi orang yang dikehendaki dan diridhai (Nya).'),
  ('id.indonesian', 53, 27, 'Sesungguhnya orang-orang yang tiada beriman kepada kehidupan akhirat, mereka benar-benar menamakan malaikat itu dengan nama perempuan.'),
  ('id.indonesian', 53, 28, 'Dan mereka tidak mempunyai sesuatu pengetahuanpun tentang itu. Mereka tidak lain hanyalah mengikuti persangkaan sedang sesungguhnya persangkaan itu tiada berfaedah sedikitpun terhadap kebenaran.'),
  ('id.indonesian', 53, 29, 'Maka berpalinglah (hai Muhammad) dari orang yang berpaling dari peringatan Kami, dan tidak mengingini kecuali kehidupan duniawi.'),
  ('id.indonesian', 53, 30, 'Itulah sejauh-jauh pengetahuan mereka. Sesungguhnya Tuhanmu, Dialah yang paling mengetahui siapa yang tersesat dari jalan-Nya dan Dia pulalah yang paling mengetahui siapa yang mendapat petunjuk.'),
  ('id.indonesian', 53, 31, 'Dan hanya kepunyaan Allah-lah apa yang ada di langit dan apa yang ada di bumi supaya Dia memberi balasan kepada orang-orang yang berbuat jahat terhadap apa yang telah mereka kerjakan dan memberi balasan kepada orang-orang yang berbuat baik dengan pahala yang lebih baik (surga).'),
  ('id.indonesian', 53, 32, '(Yaitu) orang-orang yang menjauhi dosa-dosa besar dan perbuatan keji yang selain dari kesalahan-kesalahan kecil. Sesungguhnya Tuhanmu maha luas ampunan-Nya. Dan Dia lebih mengetahui (tentang keadaan)mu ketika Dia menjadikan kamu dari tanah dan ketika kamu masih janin dalam perut ibumu; maka janganlah kamu mengatakan dirimu suci. Dialah yang paling mengetahui tentang orang yang bertakwa.'),
  ('id.indonesian', 53, 33, 'Maka apakah kamu melihat orang yang berpaling (dari Al-Quran)?'),
  ('id.indonesian', 53, 34, 'serta memberi sedikit dan tidak mau memberi lagi?'),
  ('id.indonesian', 53, 35, 'Apakah dia mempunyai pengetahuan tentang yang ghaib, sehingga dia mengetahui (apa yang dikatakan)?'),
  ('id.indonesian', 53, 36, 'Ataukah belum diberitakan kepadanya apa yang ada dalam lembaran-lembaran Musa?'),
  ('id.indonesian', 53, 37, 'dan lembaran-lembaran Ibrahim yang selalu menyempurnakan janji?'),
  ('id.indonesian', 53, 38, '(yaitu) bahwasanya seorang yang berdosa tidak akan memikul dosa orang lain,'),
  ('id.indonesian', 53, 39, 'dan bahwasanya seorang manusia tiada memperoleh selain apa yang telah diusahakannya,'),
  ('id.indonesian', 53, 40, 'dan bahwasanya usaha itu kelak akan diperlihatkan (kepadanya).'),
  ('id.indonesian', 53, 41, 'Kemudian akan diberi balasan kepadanya dengan balasan yang paling sempurna,'),
  ('id.indonesian', 53, 42, 'dan bahwasanya kepada Tuhanmulah kesudahan (segala sesuatu),'),
  ('id.indonesian', 53, 43, 'dan bahwasanya Dialah yang menjadikan orang tertawa dan menangis,'),
  ('id.indonesian', 53, 44, 'dan bahwasanya Dialah yang mematikan dan menghidupkan,'),
  ('id.indonesian', 53, 45, 'dan bahwasanya Dialah yang menciptakan berpasang-pasangan pria dan wanita.'),
  ('id.indonesian', 53, 46, 'dari air mani, apabila dipancarkan.'),
  ('id.indonesian', 53, 47, 'Dan bahwasanya Dialah yang menetapkan kejadian yang lain (kebangkitan sesudah mati),'),
  ('id.indonesian', 53, 48, 'dan bahwasanya Dia yang memberikan kekayaan dan memberikan kecukupan,'),
  ('id.indonesian', 53, 49, 'dan bahwasanya Dialah yang Tuhan (yang memiliki) bintang syi\'ra,'),
  ('id.indonesian', 53, 50, 'dan bahwasanya Dia telah membinasakan kaum \'Aad yang pertama,'),
  ('id.indonesian', 53, 51, 'dan kaum Tsamud. Maka tidak seorangpun yang ditinggalkan-Nya (hidup).'),
  ('id.indonesian', 53, 52, 'Dan kaum Nuh sebelum itu. Sesungguhnya mereka adalah orang-orang yang paling zalim dan paling durhaka,'),
  ('id.indonesian', 53, 53, 'dan negeri-negeri kaum Luth yang telah dihancurkan Allah.'),
  ('id.indonesian', 53, 54, 'lalu Allah menimpakan atas negeri itu azab besar yang menimpanya.'),
  ('id.indonesian', 53, 55, 'Maka terhadap nikmat Tuhanmu yang manakah kamu ragu-ragu?'),
  ('id.indonesian', 53, 56, 'Ini (Muhammad) adalah seorang pemberi peringatan di antara pemberi-pemberi peringatan yang terdahulu.'),
  ('id.indonesian', 53, 57, 'Telah dekat terjadinya hari kiamat.'),
  ('id.indonesian', 53, 58, 'Tidak ada yang akan menyatakan terjadinya hari itu selain Allah.'),
  ('id.indonesian', 53, 59, 'Maka apakah kamu merasa heran terhadap pemberitaan ini?'),
  ('id.indonesian', 53, 60, 'Dan kamu mentertawakan dan tidak menangis?'),
  ('id.indonesian', 53, 61, 'Sedang kamu melengahkan(nya)?'),
  ('id.indonesian', 53, 62, 'Maka bersujudlah kepada Allah dan sembahlah (Dia).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 54, 1, 'The Hour has come near, and the moon has split [in two].'),
  ('en.sahih', 54, 2, 'And if they see a miracle, they turn away and say, "Passing magic."'),
  ('en.sahih', 54, 3, 'And they denied and followed their inclinations. But for every matter is a [time of] settlement.'),
  ('en.sahih', 54, 4, 'And there has already come to them of information that in which there is deterrence -'),
  ('en.sahih', 54, 5, 'Extensive wisdom - but warning does not avail [them].'),
  ('en.sahih', 54, 6, 'So leave them, [O Muhammad]. The Day the Caller calls to something forbidding,'),
  ('en.sahih', 54, 7, 'Their eyes humbled, they will emerge from the graves as if they were locusts spreading,'),
  ('en.sahih', 54, 8, 'Racing ahead toward the Caller. The disbelievers will say, "This is a difficult Day."'),
  ('en.sahih', 54, 9, 'The people of Noah denied before them, and they denied Our servant and said, "A madman," and he was repelled.'),
  ('en.sahih', 54, 10, 'So he invoked his Lord, "Indeed, I am overpowered, so help."'),
  ('en.sahih', 54, 11, 'Then We opened the gates of the heaven with rain pouring down'),
  ('en.sahih', 54, 12, 'And caused the earth to burst with springs, and the waters met for a matter already predestined.'),
  ('en.sahih', 54, 13, 'And We carried him on a [construction of] planks and nails,'),
  ('en.sahih', 54, 14, 'Sailing under Our observation as reward for he who had been denied.'),
  ('en.sahih', 54, 15, 'And We left it as a sign, so is there any who will remember?'),
  ('en.sahih', 54, 16, 'And how [severe] were My punishment and warning.'),
  ('en.sahih', 54, 17, 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?'),
  ('en.sahih', 54, 18, '\'Aad denied; and how [severe] were My punishment and warning.'),
  ('en.sahih', 54, 19, 'Indeed, We sent upon them a screaming wind on a day of continuous misfortune,'),
  ('en.sahih', 54, 20, 'Extracting the people as if they were trunks of palm trees uprooted.'),
  ('en.sahih', 54, 21, 'And how [severe] were My punishment and warning.'),
  ('en.sahih', 54, 22, 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?'),
  ('en.sahih', 54, 23, 'Thamud denied the warning'),
  ('en.sahih', 54, 24, 'And said, "Is it one human being among us that we should follow? Indeed, we would then be in error and madness.'),
  ('en.sahih', 54, 25, 'Has the message been sent down upon him from among us? Rather, he is an insolent liar."'),
  ('en.sahih', 54, 26, 'They will know tomorrow who is the insolent liar.'),
  ('en.sahih', 54, 27, 'Indeed, We are sending the she-camel as trial for them, so watch them and be patient.'),
  ('en.sahih', 54, 28, 'And inform them that the water is shared between them, each [day of] drink attended [by turn].'),
  ('en.sahih', 54, 29, 'But they called their companion, and he dared and hamstrung [her].'),
  ('en.sahih', 54, 30, 'And how [severe] were My punishment and warning.'),
  ('en.sahih', 54, 31, 'Indeed, We sent upon them one blast from the sky, and they became like the dry twig fragments of an [animal] pen.'),
  ('en.sahih', 54, 32, 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?'),
  ('en.sahih', 54, 33, 'The people of Lot denied the warning.'),
  ('en.sahih', 54, 34, 'Indeed, We sent upon them a storm of stones, except the family of Lot - We saved them before dawn'),
  ('en.sahih', 54, 35, 'As favor from us. Thus do We reward he who is grateful.'),
  ('en.sahih', 54, 36, 'And he had already warned them of Our assault, but they disputed the warning.'),
  ('en.sahih', 54, 37, 'And they had demanded from him his guests, but We obliterated their eyes, [saying], "Taste My punishment and warning."'),
  ('en.sahih', 54, 38, 'And there came upon them by morning an abiding punishment.'),
  ('en.sahih', 54, 39, 'So taste My punishment and warning.'),
  ('en.sahih', 54, 40, 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?'),
  ('en.sahih', 54, 41, 'And there certainly came to the people of Pharaoh warning.'),
  ('en.sahih', 54, 42, 'They denied Our signs, all of them, so We seized them with a seizure of one Exalted in Might and Perfect in Ability.'),
  ('en.sahih', 54, 43, 'Are your disbelievers better than those [former ones], or have you immunity in the scripture?'),
  ('en.sahih', 54, 44, 'Or do they say, "We are an assembly supporting [each other]"?'),
  ('en.sahih', 54, 45, '[Their] assembly will be defeated, and they will turn their backs [in retreat].'),
  ('en.sahih', 54, 46, 'But the Hour is their appointment [for due punishment], and the Hour is more disastrous and more bitter.'),
  ('en.sahih', 54, 47, 'Indeed, the criminals are in error and madness.'),
  ('en.sahih', 54, 48, 'The Day they are dragged into the Fire on their faces [it will be said], "Taste the touch of Saqar."'),
  ('en.sahih', 54, 49, 'Indeed, all things We created with predestination.'),
  ('en.sahih', 54, 50, 'And Our command is but one, like a glance of the eye.'),
  ('en.sahih', 54, 51, 'And We have already destroyed your kinds, so is there any who will remember?'),
  ('en.sahih', 54, 52, 'And everything they did is in written records.'),
  ('en.sahih', 54, 53, 'And every small and great [thing] is inscribed.'),
  ('en.sahih', 54, 54, 'Indeed, the righteous will be among gardens and rivers,'),
  ('en.sahih', 54, 55, 'In a seat of honor near a Sovereign, Perfect in Ability.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 54, 1, 'কেয়ামত আসন্ন, চন্দ্র বিদীর্ণ হয়েছে।'),
  ('bn.bengali', 54, 2, 'তারা যদি কোন নিদর্শন দেখে তবে মুখ ফিরিয়ে নেয় এবং বলে, এটা তো চিরাগত জাদু।'),
  ('bn.bengali', 54, 3, 'তারা মিথ্যারোপ করছে এবং নিজেদের খেয়াল-খুশীর অনুসরণ করছে। প্রত্যেক কাজ যথাসময়ে স্থিরীকৃত হয়।'),
  ('bn.bengali', 54, 4, 'তাদের কাছে এমন সংবাদ এসে গেছে, যাতে সাবধানবাণী রয়েছে।'),
  ('bn.bengali', 54, 5, 'এটা পরিপূর্ণ জ্ঞান, তবে সতর্ককারীগণ তাদের কোন উপকারে আসে না।'),
  ('bn.bengali', 54, 6, 'অতএব, আপনি তাদের থেকে মুখ ফিরিয়ে নিন। যেদিন আহবানকারী আহবান করবে এক অপ্রিয় পরিণামের দিকে,'),
  ('bn.bengali', 54, 7, 'তারা তখন অবনমিত নেত্রে কবর থেকে বের হবে বিক্ষিপ্ত পংগপাল সদৃশ।'),
  ('bn.bengali', 54, 8, 'তারা আহবানকারীর দিকে দৌড়াতে থাকবে। কাফেরা বলবেঃ এটা কঠিন দিন।'),
  ('bn.bengali', 54, 9, 'তাদের পূর্বে নূহের সম্প্রদায়ও মিথ্যারোপ করেছিল। তারা মিথ্যারোপ করেছিল আমার বান্দা নূহের প্রতি এবং বলেছিলঃ এ তো উম্মাদ। তাঁরা তাকে হুমকি প্রদর্শন করেছিল।'),
  ('bn.bengali', 54, 10, 'অতঃপর সে তার পালনকর্তাকে ডেকে বললঃ আমি অক্ষম, অতএব, তুমি প্রতিবিধান কর।'),
  ('bn.bengali', 54, 11, 'তখন আমি খুলে দিলাম আকাশের দ্বার প্রবল বারিবর্ষণের মাধ্যমে।'),
  ('bn.bengali', 54, 12, 'এবং ভুমি থেকে প্রবাহিত করলাম প্রস্রবণ। অতঃপর সব পানি মিলিত হল এক পরিকম্পিত কাজে।'),
  ('bn.bengali', 54, 13, 'আমি নূহকে আরোহণ করালাম এক কাষ্ঠ ও পেরেক নির্মিত জলযানে।'),
  ('bn.bengali', 54, 14, 'যা চলত আমার দৃষ্টি সামনে। এটা তার পক্ষ থেকে প্রতিশোধ ছিল, যাকে প্রত্যখ্যান করা হয়েছিল।'),
  ('bn.bengali', 54, 15, 'আমি একে এক নিদর্শনরূপে রেখে দিয়েছি। অতএব, কোন চিন্তাশীল আছে কি?'),
  ('bn.bengali', 54, 16, 'কেমন কঠোর ছিল আমার শাস্তি ও সতর্কবাণী।'),
  ('bn.bengali', 54, 17, 'আমি কোরআনকে সহজ করে দিয়েছি বোঝার জন্যে। অতএব, কোন চিন্তাশীল আছে কি?'),
  ('bn.bengali', 54, 18, 'আদ সম্প্রদায় মিথ্যারোপ করেছিল, অতঃপর কেমন কঠোর হয়েছিল আমার শাস্তি ও সতর্কবাণী।'),
  ('bn.bengali', 54, 19, 'আমি তাদের উপর প্রেরণ করেছিলাম ঝঞ্জাবায়ু এক চিরাচরিত অশুভ দিনে।'),
  ('bn.bengali', 54, 20, 'তা মানুষকে উৎখাত করছিল, যেন তারা উৎপাটিত খর্জুর বৃক্ষের কান্ড।'),
  ('bn.bengali', 54, 21, 'অতঃপর কেমন কঠোর ছিল আমার শাস্তি ও সতর্কবাণী।'),
  ('bn.bengali', 54, 22, 'আমি কোরআনকে বোঝার জন্যে সহজ করে দিয়েছি। অতএব, কোন চিন্তাশীল আছে কি?'),
  ('bn.bengali', 54, 23, 'সামুদ সম্প্রদায় সতর্ককারীদের প্রতি মিথ্যারোপ করেছিল।'),
  ('bn.bengali', 54, 24, 'তারা বলেছিলঃ আমরা কি আমাদেরই একজনের অনুসরণ করব? তবে তো আমরা বিপথগামী ও বিকার গ্রস্থরূপে গণ্য হব।'),
  ('bn.bengali', 54, 25, 'আমাদের মধ্যে কি তারই প্রতি উপদেশ নাযিল করা হয়েছে? বরং সে একজন মিথ্যাবাদী, দাম্ভিক।'),
  ('bn.bengali', 54, 26, 'এখন আগামীকল্যই তারা জানতে পারবে কে মিথ্যাবাদী, দাম্ভিক।'),
  ('bn.bengali', 54, 27, 'আমি তাদের পরীক্ষার জন্য এক উষ্ট্রী প্রেরণ করব, অতএব, তাদের প্রতি লক্ষ্য রাখ এবং সবর কর।'),
  ('bn.bengali', 54, 28, 'এবং তাদেরকে জানিয়ে দাও যে, তাদের মধ্যে পানির পালা নির্ধারিত হয়েছে এবং পালাক্রমে উপস্থিত হতে হবে।'),
  ('bn.bengali', 54, 29, 'অতঃপর তারা তাদের সঙ্গীকে ডাকল। সে তাকে ধরল এবং বধ করল।'),
  ('bn.bengali', 54, 30, 'অতঃপর কেমন কঠোর ছিল আমার শাস্তি ও সতর্কবাণী।'),
  ('bn.bengali', 54, 31, 'আমি তাদের প্রতি একটিমাত্র নিনাদ প্রেরণ করেছিলাম। এতেই তারা হয়ে গেল শুষ্ক শাখাপল্লব নির্মিত দলিত খোয়াড়ের ন্যায়।'),
  ('bn.bengali', 54, 32, 'আমি কোরআনকে বোঝার জন্যে সহজ করে দিয়েছি। অতএব, কোন চিন্তাশীল আছে কি?'),
  ('bn.bengali', 54, 33, 'লূত-সম্প্রদায় সতর্ককারীদের প্রতি মিথ্যারোপ করেছিল।'),
  ('bn.bengali', 54, 34, 'আমি তাদের প্রতি প্রেরণ করেছিলাম প্রস্তর বর্ষণকারী প্রচন্ড ঘূর্ণিবায়ু; কিন্তু লূত পরিবারের উপর নয়। আমি তাদেরকে রাতের শেষপ্রহরে উদ্ধার করেছিলাম।'),
  ('bn.bengali', 54, 35, 'আমার পক্ষ থেকে অনুগ্রহ স্বরূপ। যারা কৃতজ্ঞতা স্বীকার করে, আমি তাদেরকে এভাবে পুরস্কৃত করে থকি।'),
  ('bn.bengali', 54, 36, 'লূত (আঃ) তাদেরকে আমার প্রচন্ড পাকড়াও সম্পর্কে সতর্ক করেছিল। অতঃপর তারা সতর্কবাণী সম্পর্কে বাকবিতন্ডা করেছিল।'),
  ('bn.bengali', 54, 37, 'তারা লূতের (আঃ) কাছে তার মেহমানদেরকে দাবী করেছিল। তখন আমি তাদের চক্ষু লোপ করে দিলাম। অতএব, আস্বাদন কর আমার শাস্তি ও সতর্কবাণী।'),
  ('bn.bengali', 54, 38, 'তাদেরকে প্রত্যুষে নির্ধারিত শাস্তি আঘাত হেনেছিল।'),
  ('bn.bengali', 54, 39, 'অতএব, আমার শাস্তি ও সতর্কবাণী আস্বাদন কর।'),
  ('bn.bengali', 54, 40, 'আমি কোরআনকে বোঝবার জন্যে সহজ করে দিয়েছি। অতএব, কোন চিন্তাশীল আছে কি?'),
  ('bn.bengali', 54, 41, 'ফেরাউন সম্প্রদায়ের কাছেও সতর্ককারীগণ আগমন করেছিল।'),
  ('bn.bengali', 54, 42, 'তারা আমার সকল নিদর্শনের প্রতি মিথ্যারোপ করেছিল। অতঃপর আমি পরাভূতকারী, পরাক্রমশালীর ন্যায় তাদেরকে পাকড়াও করলাম।'),
  ('bn.bengali', 54, 43, 'তোমাদের মধ্যকার কাফেররা কি তাদের চাইতে শ্রেষ্ঠ ? না তোমাদের মুক্তির সনদপত্র রয়েছে কিতাবসমূহে?'),
  ('bn.bengali', 54, 44, 'না তারা বলে যে, আমারা এক অপরাজেয় দল?'),
  ('bn.bengali', 54, 45, 'এ দল তো সত্ত্বরই পরাজিত হবে এবং পৃষ্ঠপ্রদর্শন করবে।'),
  ('bn.bengali', 54, 46, 'বরং কেয়ামত তাদের প্রতিশ্রুত সময় এবং কেয়ামত ঘোরতর বিপদ ও তিক্ততর।'),
  ('bn.bengali', 54, 47, 'নিশ্চয় অপরাধীরা পথভ্রষ্ট ও বিকারগ্রস্ত।'),
  ('bn.bengali', 54, 48, 'যেদিন তাদেরকে মুখ হিঁচড়ে টেনে নেয়া হবে জাহান্নামে, বলা হবেঃ অগ্নির খাদ্য আস্বাদন কর।'),
  ('bn.bengali', 54, 49, 'আমি প্রত্যেক বস্তুকে পরিমিতরূপে সৃষ্টি করেছি।'),
  ('bn.bengali', 54, 50, 'আমার কাজ তো এক মুহূর্তে চোখের পলকের মত।'),
  ('bn.bengali', 54, 51, 'আমি তোমাদের সমমনা লোকদেরকে ধ্বংস করেছি, অতএব, কোন চিন্তাশীল আছে কি?'),
  ('bn.bengali', 54, 52, 'তারা যা কিছু করেছে, সবই আমলনামায় লিপিবদ্ধ আছে।'),
  ('bn.bengali', 54, 53, 'ছোট ও বড় সবই লিপিবদ্ধ।'),
  ('bn.bengali', 54, 54, 'খোদাভীরুরা থাকবে জান্নাতে ও নির্ঝরিণীতে।'),
  ('bn.bengali', 54, 55, 'যোগ্য আসনে, সর্বাধিপতি সম্রাটের সান্নিধ্যে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 54, 1, 'The hour drew nigh and the moon was rent in twain.'),
  ('en.pickthall', 54, 2, 'And if they behold a portent they turn away and say: Prolonged illusion.'),
  ('en.pickthall', 54, 3, 'They denied (the Truth) and followed their own lusts. Yet everything will come to a decision'),
  ('en.pickthall', 54, 4, 'And surely there hath come unto them news whereof the purport should deter,'),
  ('en.pickthall', 54, 5, 'Effective wisdom; but warnings avail not.'),
  ('en.pickthall', 54, 6, 'So withdraw from them (O Muhammad) on the day when the Summoner summoneth unto a painful thing.'),
  ('en.pickthall', 54, 7, 'With downcast eyes, they come forth from the graves as they were locusts spread abroad,'),
  ('en.pickthall', 54, 8, 'Hastening toward the summoner; the disbelievers say: This is a hard day.'),
  ('en.pickthall', 54, 9, 'The folk of Noah denied before them, yea, they denied Our slave and said: A madman; and he was repulsed.'),
  ('en.pickthall', 54, 10, 'So he cried unto his Lord, saying: I am vanquished, so give help.'),
  ('en.pickthall', 54, 11, 'Then opened We the gates of heaven with pouring water'),
  ('en.pickthall', 54, 12, 'And caused the earth to gush forth springs, so that the waters met for a predestined purpose.'),
  ('en.pickthall', 54, 13, 'And We carried him upon a thing of planks and nails,'),
  ('en.pickthall', 54, 14, 'That ran (upon the waters) in Our sight, as a reward for him who was rejected.'),
  ('en.pickthall', 54, 15, 'And verily We left it as a token; but is there any that remembereth?'),
  ('en.pickthall', 54, 16, 'Then see how (dreadful) was My punishment after My warnings!'),
  ('en.pickthall', 54, 17, 'And in truth We have made the Qur\'an easy to remember; but is there any that remembereth?'),
  ('en.pickthall', 54, 18, '(The tribe of) A\'ad rejected warnings. Then how (dreadful) was My punishment after My warnings.'),
  ('en.pickthall', 54, 19, 'Lo! We let loose on them a raging wind on a day of constant calamity,'),
  ('en.pickthall', 54, 20, 'Sweeping men away as though they were uprooted trunks of palm-trees.'),
  ('en.pickthall', 54, 21, 'Then see how (dreadful) was My punishment after My warnings!'),
  ('en.pickthall', 54, 22, 'And in truth We have made the Qur\'an easy to remember; but is there any that remembereth?'),
  ('en.pickthall', 54, 23, '(The tribe of) Thamud rejected warnings'),
  ('en.pickthall', 54, 24, 'For they said; Is it a mortal man, alone among us, that we are to follow? Then indeed we should fall into error and madness.'),
  ('en.pickthall', 54, 25, 'Hath the remembrance been given unto him alone among us? Nay, but he is a rash liar.'),
  ('en.pickthall', 54, 26, '(Unto their warner it was said): To-morrow they will know who is the rash liar.'),
  ('en.pickthall', 54, 27, 'Lo! We are sending the she-camel as a test for them; so watch them and have patience;'),
  ('en.pickthall', 54, 28, 'And inform them that the water is to be shared between (her and) them. Every drinking will be witnessed.'),
  ('en.pickthall', 54, 29, 'But they call their comrade and he took and hamstrung (her).'),
  ('en.pickthall', 54, 30, 'Then see how (dreadful) was My punishment after My warnings!'),
  ('en.pickthall', 54, 31, 'Lo! We sent upon them one Shout, and they became as the dry twigs (rejected by) the builder of a cattle-fold.'),
  ('en.pickthall', 54, 32, 'And in truth We have made the Qur\'an easy to remember; but is there any that remembereth?'),
  ('en.pickthall', 54, 33, 'The folk of Lot rejected warnings.'),
  ('en.pickthall', 54, 34, 'Lo! We sent a storm of stones upon them (all) save the family of Lot, whom We rescued in the last watch of the night,'),
  ('en.pickthall', 54, 35, 'As grace from Us. Thus We reward him who giveth thanks.'),
  ('en.pickthall', 54, 36, 'And he indeed had warned them of Our blow, but they did doubt the warnings.'),
  ('en.pickthall', 54, 37, 'They even asked of him his guests for an ill purpose. Then We blinded their eyes (and said): Taste now My punishment after My warnings!'),
  ('en.pickthall', 54, 38, 'And in truth the punishment decreed befell them early in the morning.'),
  ('en.pickthall', 54, 39, 'Now taste My punishment after My warnings!'),
  ('en.pickthall', 54, 40, 'And in truth We have made the Qur\'an easy to remember; but is there any that remembereth?'),
  ('en.pickthall', 54, 41, 'And warnings came in truth unto the house of Pharaoh'),
  ('en.pickthall', 54, 42, 'Who denied Our revelations, every one. Therefore We grasped them with the grasp of the Mighty, the Powerful.'),
  ('en.pickthall', 54, 43, 'Are your disbelievers better than those, or have ye some immunity in the scriptures?'),
  ('en.pickthall', 54, 44, 'Or say they: We are a host victorious?'),
  ('en.pickthall', 54, 45, 'The hosts will all be routed and will turn and flee.'),
  ('en.pickthall', 54, 46, 'Nay, but the Hour (of doom) is their appointed tryst, and the Hour will be more wretched and more bitter (than their earthly failure).'),
  ('en.pickthall', 54, 47, 'Lo! the guilty are in error and madness.'),
  ('en.pickthall', 54, 48, 'On the day when they are dragged into the Fire upon their faces (it is said unto them): Feel the touch of hell.'),
  ('en.pickthall', 54, 49, 'Lo! We have created every thing by measure.'),
  ('en.pickthall', 54, 50, 'And Our commandment is but one (commandment), as the twinkling of an eye.'),
  ('en.pickthall', 54, 51, 'And verily We have destroyed your fellows; but is there any that remembereth?'),
  ('en.pickthall', 54, 52, 'And every thing they did is in the scriptures,'),
  ('en.pickthall', 54, 53, 'And every small and great thing is recorded.'),
  ('en.pickthall', 54, 54, 'Lo! the righteous will dwell among gardens and rivers,'),
  ('en.pickthall', 54, 55, 'Firmly established in the favour of a Mighty King.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 54, 1, 'The Hour (of Judgment) is nigh, and the moon is cleft asunder.'),
  ('en.yusufali', 54, 2, 'But if they see a Sign, they turn away, and say, "This is (but) transient magic."'),
  ('en.yusufali', 54, 3, 'They reject (the warning) and follow their (own) lusts but every matter has its appointed time.'),
  ('en.yusufali', 54, 4, 'There have already come to them Recitals wherein there is (enough) to check (them),'),
  ('en.yusufali', 54, 5, 'Mature wisdom;- but (the preaching of) Warners profits them not.'),
  ('en.yusufali', 54, 6, 'Therefore, (O Prophet,) turn away from them. The Day that the Caller will call (them) to a terrible affair,'),
  ('en.yusufali', 54, 7, 'They will come forth,- their eyes humbled - from (their) graves, (torpid) like locusts scattered abroad,'),
  ('en.yusufali', 54, 8, 'Hastening, with eyes transfixed, towards the Caller!- "Hard is this Day!", the Unbelievers will say.'),
  ('en.yusufali', 54, 9, 'Before them the People of Noah rejected (their messenger): they rejected Our servant, and said, "Here is one possessed!", and he was driven out.'),
  ('en.yusufali', 54, 10, 'Then he called on his Lord: "I am one overcome: do Thou then help (me)!"'),
  ('en.yusufali', 54, 11, 'So We opened the gates of heaven, with water pouring forth.'),
  ('en.yusufali', 54, 12, 'And We caused the earth to gush forth with springs, so the waters met (and rose) to the extent decreed.'),
  ('en.yusufali', 54, 13, 'But We bore him on an (Ark) made of broad planks and caulked with palm-fibre:'),
  ('en.yusufali', 54, 14, 'She floats under our eyes (and care): a recompense to one who had been rejected (with scorn)!'),
  ('en.yusufali', 54, 15, 'And We have left this as a Sign (for all time): then is there any that will receive admonition?'),
  ('en.yusufali', 54, 16, 'But how (terrible) was My Penalty and My Warning?'),
  ('en.yusufali', 54, 17, 'And We have indeed made the Qur\'an easy to understand and remember: then is there any that will receive admonition?'),
  ('en.yusufali', 54, 18, 'The \'Ad (people) (too) rejected (Truth): then how terrible was My Penalty and My Warning?'),
  ('en.yusufali', 54, 19, 'For We sent against them a furious wind, on a Day of violent Disaster,'),
  ('en.yusufali', 54, 20, 'Plucking out men as if they were roots of palm-trees torn up (from the ground).'),
  ('en.yusufali', 54, 21, 'Yea, how (terrible) was My Penalty and My Warning!'),
  ('en.yusufali', 54, 22, 'But We have indeed made the Qur\'an easy to understand and remember: then is there any that will receive admonition?'),
  ('en.yusufali', 54, 23, 'The Thamud (also) rejected (their) Warners.'),
  ('en.yusufali', 54, 24, 'For they said: "What! a man! a Solitary one from among ourselves! shall we follow such a one? Truly should we then be straying in mind, and mad!'),
  ('en.yusufali', 54, 25, '"Is it that the Message is sent to him, of all people amongst us? Nay, he is a liar, an insolent one!"'),
  ('en.yusufali', 54, 26, 'Ah! they will know on the morrow, which is the liar, the insolent one!'),
  ('en.yusufali', 54, 27, 'For We will send the she-camel by way of trial for them. So watch them, (O Salih), and possess thyself in patience!'),
  ('en.yusufali', 54, 28, 'And tell them that the water is to be divided between them: Each one\'s right to drink being brought forward (by suitable turns).'),
  ('en.yusufali', 54, 29, 'But they called to their companion, and he took a sword in hand, and hamstrung (her).'),
  ('en.yusufali', 54, 30, 'Ah! how (terrible) was My Penalty and My Warning!'),
  ('en.yusufali', 54, 31, 'For We sent against them a single Mighty Blast, and they became like the dry stubble used by one who pens cattle.'),
  ('en.yusufali', 54, 32, 'And We have indeed made the Qur\'an easy to understand and remember: then is there any that will receive admonition?'),
  ('en.yusufali', 54, 33, 'The people of Lut rejected (his) warning.'),
  ('en.yusufali', 54, 34, 'We sent against them a violent Tornado with showers of stones, (which destroyed them), except Lut\'s household: them We delivered by early Dawn,-'),
  ('en.yusufali', 54, 35, 'As a Grace from Us: thus do We reward those who give thanks.'),
  ('en.yusufali', 54, 36, 'And (Lut) did warn them of Our Punishment, but they disputed about the Warning.'),
  ('en.yusufali', 54, 37, 'And they even sought to snatch away his guests from him, but We blinded their eyes. (They heard:) "Now taste ye My Wrath and My Warning."'),
  ('en.yusufali', 54, 38, 'Early on the morrow an abiding Punishment seized them:'),
  ('en.yusufali', 54, 39, '"So taste ye My Wrath and My Warning."'),
  ('en.yusufali', 54, 40, 'And We have indeed made the Qur\'an easy to understand and remember: then is there any that will receive admonition?'),
  ('en.yusufali', 54, 41, 'To the People of Pharaoh, too, aforetime, came Warners (from Allah).'),
  ('en.yusufali', 54, 42, 'The (people) rejected all Our Signs; but We seized them with such Penalty (as comes) from One Exalted in Power, able to carry out His Will.'),
  ('en.yusufali', 54, 43, 'Are your Unbelievers, (O Quraish), better than they? Or have ye an immunity in the Sacred Books?'),
  ('en.yusufali', 54, 44, 'Or do they say: "We acting together can defend ourselves"?'),
  ('en.yusufali', 54, 45, 'Soon will their multitude be put to flight, and they will show their backs.'),
  ('en.yusufali', 54, 46, 'Nay, the Hour (of Judgment) is the time promised them (for their full recompense): And that Hour will be most grievous and most bitter.'),
  ('en.yusufali', 54, 47, 'Truly those in sin are the ones straying in mind, and mad.'),
  ('en.yusufali', 54, 48, 'The Day they will be dragged through the Fire on their faces, (they will hear:) "Taste ye the touch of Hell!"'),
  ('en.yusufali', 54, 49, 'Verily, all things have We created in proportion and measure.'),
  ('en.yusufali', 54, 50, 'And Our Command is but a single (Act),- like the twinkling of an eye.'),
  ('en.yusufali', 54, 51, 'And (oft) in the past, have We destroyed gangs like unto you: then is there any that will receive admonition?'),
  ('en.yusufali', 54, 52, 'All that they do is noted in (their) Books (of Deeds):'),
  ('en.yusufali', 54, 53, 'Every matter, small and great, is on record.'),
  ('en.yusufali', 54, 54, 'As to the Righteous, they will be in the midst of Gardens and Rivers,'),
  ('en.yusufali', 54, 55, 'In an Assembly of Truth, in the Presence of a Sovereign Omnipotent.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 54, 1, 'Iqtarabatis Saa\'atu wsan shaqqal qamar'),
  ('en.transliteration', 54, 2, 'Wa iny yaraw aayatany yu\'ridoo wa yaqooloo sihrum mustamirr'),
  ('en.transliteration', 54, 3, 'Wa kazzaboo wattaba\'ooo ahwaaa\'ahum; wa kullu amrim mustaqirr'),
  ('en.transliteration', 54, 4, 'Wa laqad jaaa\'ahum minal ambaaa\'i maa feehi muzdajar'),
  ('en.transliteration', 54, 5, 'Hikmatum baalighatun famaa tughnin nuzur'),
  ('en.transliteration', 54, 6, 'Fatawalla \'anhum; yawma yad\'ud daa\'i ilaa shai \'in nukur'),
  ('en.transliteration', 54, 7, 'khushsha\'an absaaruhum yakrujoona minal ajdaasi ka annahum jaraadum muntashir'),
  ('en.transliteration', 54, 8, 'Muhti\'eena ilad daa\'i yaqoolul kafiroona haazaa yawmun \'asir'),
  ('en.transliteration', 54, 9, 'Kazzabat qablahum qawmu Noohin fakazzaboo \'abdanaa wa qaaloo majnoo nunw wazdujir'),
  ('en.transliteration', 54, 10, 'Fada\'aa Rabbahooo annee maghloobun fantasir'),
  ('en.transliteration', 54, 11, 'Fafatahnaaa abwaabas sa maaa\'i bimaa\'im munhamir'),
  ('en.transliteration', 54, 12, 'Wa fajjamal arda \'uyoonan faltaqal maaa\'u \'alaaa amrin qad qudir'),
  ('en.transliteration', 54, 13, 'Wa hamalnaahu \'alaa zaati alwaahinw wa dusur'),
  ('en.transliteration', 54, 14, 'Tajree bi a\'yuninaa jazaaa \'al liman kaana kufir'),
  ('en.transliteration', 54, 15, 'Wa laqat taraknaahaad aayatan fahal mim muddakir'),
  ('en.transliteration', 54, 16, 'Fakaifa kaana \'azaabee wa nuzur'),
  ('en.transliteration', 54, 17, 'Wa laqad yassamal Quraana liz zikri fahal mimmuddakir'),
  ('en.transliteration', 54, 18, 'Kazzabat \'Aadun fakaifa kaana \'azaabee wa nuzur'),
  ('en.transliteration', 54, 19, 'Innaa arsalnaa \'alaihim reehan sarsaran fee Yawmi nahsim mustamirr'),
  ('en.transliteration', 54, 20, 'Tanzi;un naasa ka anna huma\'jaazu nakhlim munqa\'ir'),
  ('en.transliteration', 54, 21, '\'Fakaifa kaana \'azaabee wa nuzur'),
  ('en.transliteration', 54, 22, 'Wa laqad yassamal Quraana liz zikri fahal mim muddakir'),
  ('en.transliteration', 54, 23, 'Kazzabat Samoodu binnuzur'),
  ('en.transliteration', 54, 24, 'Faqaalooo a-basharam minnaa waahidan nattabi\'uhooo innaa izal lafee dalaalinw wa su\'ur'),
  ('en.transliteration', 54, 25, '\'A-ulqiyaz zikru \'alaihi mim baininaa bal huwa kazzaabun ashir'),
  ('en.transliteration', 54, 26, 'Sa-ya\'lamoona ghadam manil kazzaabul ashir'),
  ('en.transliteration', 54, 27, 'Innaa mursilun naaqati fitnatal lahum fartaqibhum wastabir'),
  ('en.transliteration', 54, 28, 'Wa nabbi\'hum annal maaa\'a qismatum bainahum kullu shirbim muhtadar'),
  ('en.transliteration', 54, 29, 'Fanaadaw saahibahum fata\'aataa fa\'aqar'),
  ('en.transliteration', 54, 30, 'Fakaifa kaana \'azaabee wa nuzur'),
  ('en.transliteration', 54, 31, 'Innaaa arsalnaa \'alaihim saihatanw waahidatan fakaano kahasheemil muhtazir'),
  ('en.transliteration', 54, 32, 'Wa laqad yassarnal quraana liz zikri fahal mim muddakir'),
  ('en.transliteration', 54, 33, 'Kazzabat qawmu lootim binnuzur'),
  ('en.transliteration', 54, 34, 'Innaa arsalnaa \'alaihim haasiban illaaa aala Loot najjainaahum bisahar'),
  ('en.transliteration', 54, 35, 'Ni\'matam min \'indinaa; kazaalika najzee man shakar'),
  ('en.transliteration', 54, 36, 'Wa laqad anzarahum batshatanaa fatamaaraw binnuzur'),
  ('en.transliteration', 54, 37, 'Wa laqad raawadoohu \'andaifee fatamasnaaa a\'yunahum fazooqoo \'azaabee wa nuzur'),
  ('en.transliteration', 54, 38, 'Wa laqad sabbahahum bukratan \'azaabum mustaqirr'),
  ('en.transliteration', 54, 39, 'Fazooqoo \'azaabee wa nuzur'),
  ('en.transliteration', 54, 40, 'Wa laqad yassarnal Quraana liz zikri fahal mim muddakir'),
  ('en.transliteration', 54, 41, 'Wa laqad jaaa\'a Aala Fir\'awnan nuzur'),
  ('en.transliteration', 54, 42, 'Kazzaboo bi Aayaatinaa kullihaa fa akhaznaahum akhza \'azeezim muqtadir'),
  ('en.transliteration', 54, 43, 'Akuffaarukum khairum min ulaaa\'ikum am lakum baraaa\'atun fiz Zubur'),
  ('en.transliteration', 54, 44, 'Am yaqooloona nahnu jamee\'um muntasir'),
  ('en.transliteration', 54, 45, 'Sa yuhzamul jam\'u wa yuwalloonad dubur'),
  ('en.transliteration', 54, 46, 'Balis Saa\'atu maw\'iduhum was Saa\'atu adhaa wa amarr'),
  ('en.transliteration', 54, 47, 'Innal mujrimeena fee dalaalinw wa su\'ur'),
  ('en.transliteration', 54, 48, 'Yawma yushaboona fin Naari\'alaa wujoohimim zooqoo massa saqar'),
  ('en.transliteration', 54, 49, 'Innaa kulla shai\'in khalaqnaahu biqadar'),
  ('en.transliteration', 54, 50, 'Wa maaa amrunaaa illaa waahidatun kalamhim bilbasar'),
  ('en.transliteration', 54, 51, 'Wa laqad ahlaknaaa ashyaa\'akum fahal mim muddakir'),
  ('en.transliteration', 54, 52, 'Wa kullu shai\'in fa\'aloohu fiz Zubur'),
  ('en.transliteration', 54, 53, 'Wa kullu sagheerinw wa kabeerim mustatar'),
  ('en.transliteration', 54, 54, 'Innal muttaqeena fee jannaatinw wa nahar'),
  ('en.transliteration', 54, 55, 'Fee maq\'adi sidqin \'inda Maleekim Muqtadir')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 54, 1, 'قیامت قریب آ گئی اور چاند پھٹ گیا'),
  ('ur.ahmedali', 54, 2, 'اور اگر وہ کوئی معجزہ دیکھ لیں تو اس سے منہ موڑ لیں اور کہیں یہ تو ہمیشہ سے چلا آتا جادو ہے'),
  ('ur.ahmedali', 54, 3, 'اور انہوں نے جھٹلایا اور اپنی خواہشوں کی پیروی کی اور ہر بات کے لیے ایک وقت مقرر ہے'),
  ('ur.ahmedali', 54, 4, 'اور ان کے پاس وہ خبریں آ چکی ہیں جن میں کافی تنبیہ ہے'),
  ('ur.ahmedali', 54, 5, 'اورپوری دانائی بھی ہے پر ان کو ڈرانے والوں سے فائدہ نہیں پہنچا'),
  ('ur.ahmedali', 54, 6, 'پس ان سے منہ موڑ لے جس دن پکارنے والا ایک نا پسند چیز کے لیے پکارے گا'),
  ('ur.ahmedali', 54, 7, 'اپنی آنکھیں نیچے کیے ہوئے قبروں سے نکل پڑیں گے جیسے ٹڈیاں پھیل پڑی ہوں'),
  ('ur.ahmedali', 54, 8, 'بلانے والے کی طرف بھاگے جا رہے ہوں گے یہ کافر کہہ رہے ہوں گے یہ تو بڑا ہی سخت دن ہے'),
  ('ur.ahmedali', 54, 9, 'ان سے پہلے قوم نوح نے بھی جھٹلایا تھا پس انہوں نے ہمارے بندے کو جھٹلایا اور کہا دیوانہ ہے اور اسے جھڑک دیا گیا'),
  ('ur.ahmedali', 54, 10, 'پھر نوح نے اپنے رب کو پکارا کہ میں تو مغلوب ہو گیا تو میری مدد کر'),
  ('ur.ahmedali', 54, 11, 'پھر ہم نے موسلا دھار پانی سے آسمان کے دروازے کھول دیے'),
  ('ur.ahmedali', 54, 12, 'اور ہم نے زمین سے چشمے جاری کر دیے پھر جہاں تک پانی کا چڑھاؤ چڑھنا ٹھہر چکا تھاچڑھ آیا'),
  ('ur.ahmedali', 54, 13, 'اور ہم نے نوح کو تختوں اور کیلوں والی کشتی پر سوار کیا'),
  ('ur.ahmedali', 54, 14, 'جو ہماری عنایت سے چلتی تھی یہ اس کا بدلہ تھا جس کا انکار کیا گیا تھا'),
  ('ur.ahmedali', 54, 15, 'اور ہم نے اس کو ایک نشان بنا کر چھوڑ دیا پس کیا کوئی نصیحت پکڑنے والا ہے'),
  ('ur.ahmedali', 54, 16, 'پھر (دیکھا) ہمارا عذاب اور ڈرانا کیسا تھا'),
  ('ur.ahmedali', 54, 17, 'اور البتہ ہم نے تو سمجھنے کے لیے قرآن کو آسان کر دیا پھر کوئی ہے کہ سمجھے'),
  ('ur.ahmedali', 54, 18, 'قوم عاد نے بھی جھٹلایا تھا پھر (دیکھا) ہمارا عذاب اور ڈرانا کیسا تھا'),
  ('ur.ahmedali', 54, 19, 'بے شک ہم نے ایک دن سخت آندھی بھیجی تھی جس کی نحوست دائمی تھی'),
  ('ur.ahmedali', 54, 20, 'جو لوگوں کو ایسا پھینک رہی تھی کہ گویا وہ کھجور کے جڑ سے اکھڑے ہوئے پیڑ ہیں'),
  ('ur.ahmedali', 54, 21, 'پھر (دیکھا) ہمارا عذاب اور ڈرانا کیسا تھا'),
  ('ur.ahmedali', 54, 22, 'اور البتہ ہم نے قرآن کو سمجھنے کے لیے آسان کر دیا ہے پھر ہے کوئی کہ سمجھے'),
  ('ur.ahmedali', 54, 23, 'قوم ثمود نے بھی ڈرانے والوں کو جھٹلایا تھا'),
  ('ur.ahmedali', 54, 24, 'پس کہا کیا ہم اپنے میں سے ایک آدمی کے کہنے پر چلیں گے تب تو ہم ضرور گمراہی اور دیوانگی میں جا پڑیں گے'),
  ('ur.ahmedali', 54, 25, 'کیا ہم میں سے اسی پر وحی بھیجی گئی بلکہ وہ بڑا جھوٹا (اور) شیخی خورہ ہے'),
  ('ur.ahmedali', 54, 26, 'عنقریب انہیں معلوم ہو جائے گا کون بڑا جھوٹا (اور) شیخی خورہ ہے'),
  ('ur.ahmedali', 54, 27, 'بے شک ہم ان کی آزمائش کے لیے اونٹنی بھیجنے والے ہیں پس (اے صالح) ان کا انتظار کر اور صبر کر'),
  ('ur.ahmedali', 54, 28, 'اور ان سے کہہ دو کہ پانی ان میں بٹ گیا ہے ہر ایک اپنی باری سے پانی پلایا کرے'),
  ('ur.ahmedali', 54, 29, 'پھر انہوں نے اپنے رفیق کو بلایا تب اس نے ہاتھ بڑھایا اور (اس کی) کانچیں کاٹ ڈالیں'),
  ('ur.ahmedali', 54, 30, 'پھر (دیکھا) ہمارا عذاب اور ڈرانا کیسا تھا'),
  ('ur.ahmedali', 54, 31, 'بے شک ہم نے ان پر ایک زور کی چیخ کا عذاب بھیجا پھر وہ ایسے ہو گئے جیسا کانٹو ں کی باڑ کا چورا'),
  ('ur.ahmedali', 54, 32, 'اور البتہ ہم نے قرآن کو سمجھنے کے لیے آسان کر دیا ہے پھر ہے کوئی سمجھنے والا'),
  ('ur.ahmedali', 54, 33, 'قوم لوط نے بھی ڈرانے والوں کو جھٹلایا تھا'),
  ('ur.ahmedali', 54, 34, 'بے شک ہم نے ان پر پتھر برسائے سوائے لوط کے گھر والوں کے ہم نے انہیں پچھلی رات نجات دی'),
  ('ur.ahmedali', 54, 35, 'یہ ہماری طرف سے فضل ہے جو شکر کرتا ہے ہم اسے ایسا ہی بدلہ دیا کرتے ہیں'),
  ('ur.ahmedali', 54, 36, 'اور وہ انہیں ہماری پکڑ سے ڈرا چکا تھا پس وہ ڈرانے میں شک کرنے لگے'),
  ('ur.ahmedali', 54, 37, 'اور البتہ اس سے اس کے مہمانوں کا مطالبہ کرنے لگے تو ہم نے ان کی آنکھیں مٹا دیں پس (کہا) میرے عذاب اور میرے ڈرانے کا مزہ چکھو'),
  ('ur.ahmedali', 54, 38, 'اور بے شک صبح کو ان پر ایک عذاب نہ ٹلنے والا آ پڑا'),
  ('ur.ahmedali', 54, 39, 'پس میرے عذاب اور میرے ڈرانے کا مزہ چکھو'),
  ('ur.ahmedali', 54, 40, 'اور البتہ ہم نے سمجھنے کے لیے قرآن کو آسان کر دیا ہے پھر ہے کوئی سمجھنے والا'),
  ('ur.ahmedali', 54, 41, 'اور البتہ فرعون کے خاندان کے پاس بھی ڈرانے والے آئے تھے'),
  ('ur.ahmedali', 54, 42, 'انہوں نے ہماری سب نشانیوں کو جھٹلایا پھر ہم نے انہیں بڑی زبردست پکڑ سے پکڑا'),
  ('ur.ahmedali', 54, 43, 'کیا تمہارے منکر ان لوگوں سے اچھے ہیں یا تمہارے لیے کتابوں میں نجات لکھی ہے'),
  ('ur.ahmedali', 54, 44, 'کیا وہ یہ کہتے ہیں کہ ہم زبردست جماعت ہیں'),
  ('ur.ahmedali', 54, 45, 'عنقریب یہ جماعت بھی شکست کھائے گی اور پیٹھ پھیر کر بھاگیں گے'),
  ('ur.ahmedali', 54, 46, 'بلکہ قیامت ان کے وعدے کا وقت ہے اور قیامت زیادہ دہشت ناک اور تلخ تر ہے'),
  ('ur.ahmedali', 54, 47, 'بے شک مجرم گمراہی اور جنون میں ہیں'),
  ('ur.ahmedali', 54, 48, 'جس دن اپنے منہ کے بل دوزخ میں گھسیٹے جائیں گے (کہا جائے گا) آگ لگنے کا مزہ چکھو'),
  ('ur.ahmedali', 54, 49, 'بے شک ہم نے ہر چیز اندازے سے بنائی ہے'),
  ('ur.ahmedali', 54, 50, 'اور ہمارا حکم تو ایک ہی بات ہوتی ہے جیسا کہ پلک جھپکنا'),
  ('ur.ahmedali', 54, 51, 'اور البتہ ہم تمہارے جیسوں کو غارت کر چکے ہیں پھر کیا کوئی سمجھنے والا ہے'),
  ('ur.ahmedali', 54, 52, 'اور پھر جو کچھ بھی انہوں نے کیا ہے وہ اعمال ناموں میں موجود ہے'),
  ('ur.ahmedali', 54, 53, 'اور ہر چھوٹا اور بڑا کام لکھا ہوا ہے'),
  ('ur.ahmedali', 54, 54, 'بے شک پرہیزگار باغوں اور نہروں میں ہوں گے'),
  ('ur.ahmedali', 54, 55, 'عزت کے مقام میں قادر مطلق بادشاہ کے حضور میں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 54, 1, 'Kıyamet saati yaklaşır, ay yarılır; onlar bir delil görünce hala yüz çevirirler ve: "Süregelen bir sihir" derler.'),
  ('tr.diyanet', 54, 2, 'Kıyamet saati yaklaşır, ay yarılır; onlar bir delil görünce hala yüz çevirirler ve: "Süregelen bir sihir" derler.'),
  ('tr.diyanet', 54, 3, 'Yalanlarlar da kendi heveslerine uyarlar. Ama her işin karar kılacağı bir sonucu vardır.'),
  ('tr.diyanet', 54, 4, 'And olsun ki, onları bu hallerinden vazgeçirecek nice haberler gelmiştir.'),
  ('tr.diyanet', 54, 5, 'Bu haberlerin her birinde üstün hikmet vardır; ama uyarmalar fayda vermiyor.'),
  ('tr.diyanet', 54, 6, 'Öyleyse onlardan yüz çevir; çağıran, görülmemiş ve tanınmamış bir şeye çağırdığı gün;'),
  ('tr.diyanet', 54, 7, 'Gözleri dalgın dalgın, çekirgeler gibi yayılmış, o çağırana koşarak kabirlerden çıkarlar. İnkarcılar: "Bu, zorlu bir gündür" derler.'),
  ('tr.diyanet', 54, 8, 'Gözleri dalgın dalgın, çekirgeler gibi yayılmış, o çağırana koşarak kabirlerden çıkarlar. İnkarcılar: "Bu, zorlu bir gündür" derler.'),
  ('tr.diyanet', 54, 9, 'Bu ortak koşanlardan önce Nuh milleti de yalanlamış, kulumuzu yalanlayarak: "Delidir" demişlerdi, yolu kesilmişti.'),
  ('tr.diyanet', 54, 10, 'O da: "Ben yenildim, bana yardım et" diye Rabbine yalvarmıştı.'),
  ('tr.diyanet', 54, 11, 'Biz de bunun üzerine gök kapılarını boşanan sularla açtık.'),
  ('tr.diyanet', 54, 12, 'Yeryüzünde kaynaklar fışkırttık; her iki su, takdir edilen bir ölçüye göre birleşti.'),
  ('tr.diyanet', 54, 13, 'Onu, tahtadan yapılmış, mıhla çakılmış bir gemiye bindirdik; inkar edilmiş olan Nuh\'a mükafat olarak verdiğimiz gemi nezaretimiz altında yüzüyordu.'),
  ('tr.diyanet', 54, 14, 'Onu, tahtadan yapılmış, mıhla çakılmış bir gemiye bindirdik; inkar edilmiş olan Nuh\'a mükafat olarak verdiğimiz gemi nezaretimiz altında yüzüyordu.'),
  ('tr.diyanet', 54, 15, 'And olsun ki Biz, o gemiyi bir ibret olarak bıraktık; öğüt alan yok mudur?'),
  ('tr.diyanet', 54, 16, 'Benim azabım ve uyarmam nasılmış?'),
  ('tr.diyanet', 54, 17, 'And olsun ki Kuran\'ı, öğüt olsun diye kolaylaştırdık; öğüt alan yok mudur?'),
  ('tr.diyanet', 54, 18, 'Ad milleti peygamberini yalanlamıştı; Benim azabım ve uyarmam nasılmış?'),
  ('tr.diyanet', 54, 19, 'Nitekim üzerlerine, insanları, sökülmüş hurma kütüğü gibi kopararak yere seren, dondurucu bir rüzgarı uğursuzluğu devam eden bir günde gönderdik.'),
  ('tr.diyanet', 54, 20, 'Nitekim üzerlerine, insanları, sökülmüş hurma kütüğü gibi kopararak yere seren, dondurucu bir rüzgarı uğursuzluğu devam eden bir günde gönderdik.'),
  ('tr.diyanet', 54, 21, 'Benim azabım ve uyarmam nasılmış?'),
  ('tr.diyanet', 54, 22, 'And olsun ki, Kuran\'ı öğüt olsun diye kolaylaştırdık; öğüt alan yok mudur?'),
  ('tr.diyanet', 54, 23, 'Semud milleti uyaran peygamberleri yalanladı.'),
  ('tr.diyanet', 54, 24, '"İçimizden bir insana mı uyacağız? O zaman biz sapıklık ve delilik etmiş oluruz. Kitap, aramızda, ona mı verilmiş? Hayır, o pek yalancı ve şımarığın biridir" dediler.'),
  ('tr.diyanet', 54, 25, '"İçimizden bir insana mı uyacağız? O zaman biz sapıklık ve delilik etmiş oluruz. Kitap, aramızda, ona mı verilmiş? Hayır, o pek yalancı ve şımarığın biridir" dediler.'),
  ('tr.diyanet', 54, 26, 'Yarın, kimin pek yalancı ve şımarık olduğunu bileceklerdir.'),
  ('tr.diyanet', 54, 27, 'Doğrusu, onları denemek üzere dişi deveyi gönderen Biziz. Salih\'e şöyle demiştik: "Onları gözetle ve sabret;'),
  ('tr.diyanet', 54, 28, 'Onlara, sıralarına göre suyun kendileriyle o deve aralarında pay edilmiş olunduğunu söyle."'),
  ('tr.diyanet', 54, 29, 'Ama bir arkadaşlarını çağırdılar, o da kılıcını alarak deveyi kesti.'),
  ('tr.diyanet', 54, 30, 'Benim azabım ve uyarmam nasılmış?'),
  ('tr.diyanet', 54, 31, 'Nitekim üzerlerine bir çığlık gönderdik de, ağılcıların kullandığı kurumuş ot gibi oldular.'),
  ('tr.diyanet', 54, 32, 'And olsun ki, Kuran\'ı öğüt olsun diye kolaylaştırdık; öğüt alan yok mudur?'),
  ('tr.diyanet', 54, 33, 'Lut milleti uyaran peygamberleri yalanladı.'),
  ('tr.diyanet', 54, 34, 'Biz de üzerlerine taş yağdıran bir rüzgar gönderdik. Ancak, Lut\'un taraftarlarını, katımızdan bir nimet olarak seher vakti kurtardık. Şükredene işte böyle mükafat veririz.'),
  ('tr.diyanet', 54, 35, 'Biz de üzerlerine taş yağdıran bir rüzgar gönderdik. Ancak, Lut\'un taraftarlarını, katımızdan bir nimet olarak seher vakti kurtardık. Şükredene işte böyle mükafat veririz.'),
  ('tr.diyanet', 54, 36, 'Lut, and olsun ki, onları Bizim yakalamamızla uyarmıştı, ama onlar uyarmaları şüphe ile karşılayarak dinlemediler.'),
  ('tr.diyanet', 54, 37, 'And olsun ki, onlar Lut\'un konukları olan melekleri elde etmeye kalkıştılar, bunun üzerine gözlerini kör ettik. "Azabımı ve uyarmalarımı dinlememenin sonucunu tadın" dedik.'),
  ('tr.diyanet', 54, 38, 'And olsun ki, sabah erken, önü alınmaz bir azap başlarına geldi.'),
  ('tr.diyanet', 54, 39, '"Azabımı ve uyarmalarımı dinlememenin sonucunu tadın" dedik.'),
  ('tr.diyanet', 54, 40, 'And olsun ki, Kuran\'ı öğüt olsun diye kolaylaştırdık; öğüt alan yok mudur?'),
  ('tr.diyanet', 54, 41, 'And olsun ki, Firavun erkanına uyaranlar geldi.'),
  ('tr.diyanet', 54, 42, 'Mucizelerimizin hepsini yalanladılar. Bunun üzerine onları güç ve kuvvet sahibi olana yakışır bir şekilde yakaladık.'),
  ('tr.diyanet', 54, 43, 'Sizin inkarcılarınız bunlardan daha mı üstündür? Yoksa Kitablarda size bir kurtuluş belgesi mi var?'),
  ('tr.diyanet', 54, 44, 'Yoksa: "Biz öç alabilecek bir topluluğuz" mu diyorlar?'),
  ('tr.diyanet', 54, 45, 'Toplulukları dağıtılacak, yüzgeri edileceklerdir.'),
  ('tr.diyanet', 54, 46, 'Kıyamet onların azap ile vadedildikleri gündür. O ne korkunç, ne acı bir gündür!'),
  ('tr.diyanet', 54, 47, 'Doğrusu suçlular sapıklık ve çılgınlık içindedirler.'),
  ('tr.diyanet', 54, 48, 'Ateşe yüzüstü sürüldükleri gün, onlara: "Cehennemin dokunan azabını tadın" denir.'),
  ('tr.diyanet', 54, 49, 'Şüphesiz Biz her şeyi bir ölçüye göre yaratmışızdır.'),
  ('tr.diyanet', 54, 50, 'Bizim buyruğumuz bir göz kırpması gibi anidir.'),
  ('tr.diyanet', 54, 51, 'And olsun ki, benzerlerinizi yok etti, öğüt alan yok mudur?'),
  ('tr.diyanet', 54, 52, 'İnsanların yaptıkları her şey kitablarda kayıtlıdır.'),
  ('tr.diyanet', 54, 53, 'Küçük ve büyük, hepsi satır satırdır.'),
  ('tr.diyanet', 54, 54, 'Allah\'a karşı gelmekten sakınanlar, güçlü hükümdarın katında, yüksek bir derecede, cennetlerde ferahlık ve aydınlık içindedirler.'),
  ('tr.diyanet', 54, 55, 'Allah\'a karşı gelmekten sakınanlar, güçlü hükümdarın katında, yüksek bir derecede, cennetlerde ferahlık ve aydınlık içindedirler.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 54, 1, 'Telah dekat datangnya saat itu dan telah terbelah bulan.'),
  ('id.indonesian', 54, 2, 'Dan jika mereka (orang-orang musyrikin) melihat suatu tanda (mukjizat), mereka berpaling dan berkata: "(Ini adalah) sihir yang terus menerus".'),
  ('id.indonesian', 54, 3, 'Dan mereka mendutakan (Nabi) dan mengikuti hawa nafsu mereka, sedang tiap-tiap urusan telah ada ketetapannya'),
  ('id.indonesian', 54, 4, 'Dan sesungguhnya telah datang kepada mereka beberapa kisah yang di dalamnya terdapat cegahan (dari kekafiran).'),
  ('id.indonesian', 54, 5, 'Itulah suatu hikmah yang sempurna maka peringatan-peringatan itu tidak berguna (bagi mereka).'),
  ('id.indonesian', 54, 6, 'Maka berpalinglah kamu dari mereka. (Ingatlah) hari (ketika) seorang penyeru (malaikat) menyeru kepada sesuatu yang tidak menyenangkan (hari pembalasan),'),
  ('id.indonesian', 54, 7, 'sambil menundukkan pandangan-pandangan mereka keluar dari kuburan seakan-akan mereka belalang yang beterbangan'),
  ('id.indonesian', 54, 8, 'mereka datang dengan cepat kepada penyeru itu. Orang-orang kafir berkata: "Ini adalah hari yang berat".'),
  ('id.indonesian', 54, 9, 'Sebelum mereka, telah mendustakan (pula) kamu Nuh, maka mereka mendustakan hamba Kami (Nuh) dan mengatakan: "Dia seorang gila dan dia sudah pernah diberi ancaman).'),
  ('id.indonesian', 54, 10, 'Maka dia mengadu kepada Tuhannya: "bahwasanya aku ini adalah orang yang dikalahkan, oleh sebab itu menangkanlah (aku)".'),
  ('id.indonesian', 54, 11, 'Maka Kami bukakan pintu-pintu langit dengan (menurunkan) air yang tercurah.'),
  ('id.indonesian', 54, 12, 'Dan Kami jadikan bumi memancarkan mata air-mata air, maka bertemulah air-air itu untuk suatu urusan yang sungguh telah ditetapkan.'),
  ('id.indonesian', 54, 13, 'Dan Kami angkut Nuh ke atas (bahtera) yang terbuat dari papan dan paku,'),
  ('id.indonesian', 54, 14, 'Yang berlayar dengan pemeliharaan Kami sebagai belasan bagi orang-orang yang diingkari (Nuh).'),
  ('id.indonesian', 54, 15, 'Dan sesungguhnya telah Kami jadikan kapal itu sebagai pelajaran, maka adakah orang yang mau mengambil pelajaran?'),
  ('id.indonesian', 54, 16, 'Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.'),
  ('id.indonesian', 54, 17, 'Dan sesungguhnya telah Kami mudahkan Al-Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?'),
  ('id.indonesian', 54, 18, 'Kaum \'Aad pun mendustakan (pula). Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.'),
  ('id.indonesian', 54, 19, 'Sesungguhnya Kami telah menghembuskan kepada mereka angin yang sangat kencang pada hari nahas yang terus menerus,'),
  ('id.indonesian', 54, 20, 'yang menggelimpangkan manusia seakan-akan mereka pokok korma yang tumbang.'),
  ('id.indonesian', 54, 21, 'Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.'),
  ('id.indonesian', 54, 22, 'Dan sesungguhnya telah Kami mudahkan Al Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?'),
  ('id.indonesian', 54, 23, 'Kaum Tsamudpun telah mendustakan ancaman-ancaman (itu).'),
  ('id.indonesian', 54, 24, 'Maka mereka berkata: "Bagaimana kita akan mengikuti seorang manusia (biasa) di antara kita?" Sesungguhnya kalau kita begitu benar-benar berada dalam keadaan sesat dan gila".'),
  ('id.indonesian', 54, 25, 'Apakah wahyu itu diturunkan kepadanya di antara kita? Sebenarnya dia adalah seorang yang amat pendusta lagi sombong.'),
  ('id.indonesian', 54, 26, 'Kelak mereka akan mengetahui siapakah yang sebenarnya amat pendusta lagi sombong.'),
  ('id.indonesian', 54, 27, 'Sesungguhnya Kami akan mengirimkan unta betina sebagai cobaan bagi mereka, maka tunggulah (tindakan) mereka dan bersabarlah.'),
  ('id.indonesian', 54, 28, 'Dan beritakanlah kepada mereka bahwa sesungguhnya air itu terbagi antara mereka (dengan unta betina itu); tiap-tiap giliran minum dihadiri (oleh yang punya giliran)'),
  ('id.indonesian', 54, 29, 'Maka mereka memanggil kawannya, lalu kawannya menangkap (unta itu) dan membunuhnya.'),
  ('id.indonesian', 54, 30, 'Alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.'),
  ('id.indonesian', 54, 31, 'Sesungguhnya Kami menimpakan atas mereka satu suara yang keras mengguntur, maka jadilah mereka seperti rumput kering (yang dikumpulkan oleh) yang punya kandang binatang.'),
  ('id.indonesian', 54, 32, 'Dan sesungguhnya telah Kami mudahkan Al Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?'),
  ('id.indonesian', 54, 33, 'Kaum Luth-pun telah mendustakan ancaman-ancaman (nabinya).'),
  ('id.indonesian', 54, 34, 'Sesungguhnya Kami telah menghembuskan kepada mereka angin yang membawa batu-batu (yang menimpa mereka), kecuali keluarga Luth. Mereka Kami selamatkan sebelum fajar menyingsing,'),
  ('id.indonesian', 54, 35, 'sebagai nikmat dari Kami. Demikianlah Kami memberi balasan kepada orang-orang yang bersyukur,'),
  ('id.indonesian', 54, 36, 'Dan sesungguhnya dia (Luth) telah memperingatkan mereka akan azab-azab Kami, maka mereka mendustakan ancaman-ancaman itu.'),
  ('id.indonesian', 54, 37, 'Dan sesungguhnya mereka telah membujuknya (agar menyerahkan) tamunya (kepada mereka), lalu Kami butakan mata mereka, maka rasakanlah azab-Ku dan ancaman-ancaman-Ku.'),
  ('id.indonesian', 54, 38, 'Dan sesungguhnya pada esok harinya mereka ditimpa azab yang kekal.'),
  ('id.indonesian', 54, 39, 'Maka rasakanlah azab-Ku dan ancaman-ancaman-Ku.'),
  ('id.indonesian', 54, 40, 'Dan sesungguhnya telah Kami mudahkan Al Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?'),
  ('id.indonesian', 54, 41, 'Dan sesungguhnya telah datang kepada kaum Fir\'aun ancaman-ancaman.'),
  ('id.indonesian', 54, 42, 'Mereka mendustakan mukjizat Kami semuanya, lalu Kami azab mereka sebagai azab dari Yang Maha Perkasa lagi Maha Kuasa'),
  ('id.indonesian', 54, 43, 'Apakah orang-orang kafirmu (hai kaum musyrikin) lebih baik dari mereka itu, atau apakah kamu telah mempunyai jaminan kebebasan (dari azab) dalam Kitab-kitab yang dahulu'),
  ('id.indonesian', 54, 44, 'Atau apakah mereka mengatakan: "Kami adalah satu golongan yang bersatu yang pasti menang".'),
  ('id.indonesian', 54, 45, 'Golongan itu pasti akan dikalahkan dan mereka akan mundur ke belakang.'),
  ('id.indonesian', 54, 46, 'Sebenarnya hari kiamat itulah hari yang dijanjikan kepada mereka dan kiamat itu lebih dahsyat dan lebih pahit.'),
  ('id.indonesian', 54, 47, 'Sesungguhnya orang-orang yang berdosa berada dalam kesesatan (di dunia) dan dalam neraka.'),
  ('id.indonesian', 54, 48, '(Ingatlah) pada hari mereka diseret ke neraka atas muka mereka. (Dikatakan kepada mereka): "Rasakanlah sentuhan api neraka!"'),
  ('id.indonesian', 54, 49, 'Sesungguhnya Kami menciptakan segala sesuatu menurut ukuran.'),
  ('id.indonesian', 54, 50, 'Dan perintah Kami hanyalah satu perkataan seperti kejapan mata.'),
  ('id.indonesian', 54, 51, 'Dan sesungguhnya telah Kami binasakan orang yang serupa dengan kamu. Maka adakah orang yang mau mengambil pelajaran?'),
  ('id.indonesian', 54, 52, 'Dan segala sesuatu yang telah mereka perbuat tercatat dalam buku-buku catatan'),
  ('id.indonesian', 54, 53, 'Dan segala (urusan) yang kecil maupun yang besar adalah tertulis.'),
  ('id.indonesian', 54, 54, 'Sesungguhnya orang-orang yang bertakwa itu di dalam taman-taman dan sungai-sungai,'),
  ('id.indonesian', 54, 55, 'di tempat yang disenangi di sisi Tuhan Yang Berkuasa.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 55, 1, 'The Most Merciful'),
  ('en.sahih', 55, 2, 'Taught the Qur\'an,'),
  ('en.sahih', 55, 3, 'Created man,'),
  ('en.sahih', 55, 4, '[And] taught him eloquence.'),
  ('en.sahih', 55, 5, 'The sun and the moon [move] by precise calculation,'),
  ('en.sahih', 55, 6, 'And the stars and trees prostrate.'),
  ('en.sahih', 55, 7, 'And the heaven He raised and imposed the balance'),
  ('en.sahih', 55, 8, 'That you not transgress within the balance.'),
  ('en.sahih', 55, 9, 'And establish weight in justice and do not make deficient the balance.'),
  ('en.sahih', 55, 10, 'And the earth He laid [out] for the creatures.'),
  ('en.sahih', 55, 11, 'Therein is fruit and palm trees having sheaths [of dates]'),
  ('en.sahih', 55, 12, 'And grain having husks and scented plants.'),
  ('en.sahih', 55, 13, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 14, 'He created man from clay like [that of] pottery.'),
  ('en.sahih', 55, 15, 'And He created the jinn from a smokeless flame of fire.'),
  ('en.sahih', 55, 16, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 17, '[He is] Lord of the two sunrises and Lord of the two sunsets.'),
  ('en.sahih', 55, 18, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 19, 'He released the two seas, meeting [side by side];'),
  ('en.sahih', 55, 20, 'Between them is a barrier [so] neither of them transgresses.'),
  ('en.sahih', 55, 21, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 22, 'From both of them emerge pearl and coral.'),
  ('en.sahih', 55, 23, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 24, 'And to Him belong the ships [with sails] elevated in the sea like mountains.'),
  ('en.sahih', 55, 25, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 26, 'Everyone upon the earth will perish,'),
  ('en.sahih', 55, 27, 'And there will remain the Face of your Lord, Owner of Majesty and Honor.'),
  ('en.sahih', 55, 28, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 29, 'Whoever is within the heavens and earth asks Him; every day He is bringing about a matter.'),
  ('en.sahih', 55, 30, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 31, 'We will attend to you, O prominent beings.'),
  ('en.sahih', 55, 32, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 33, 'O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah].'),
  ('en.sahih', 55, 34, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 35, 'There will be sent upon you a flame of fire and smoke, and you will not defend yourselves.'),
  ('en.sahih', 55, 36, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 37, 'And when the heaven is split open and becomes rose-colored like oil -'),
  ('en.sahih', 55, 38, 'So which of the favors of your Lord would you deny? -'),
  ('en.sahih', 55, 39, 'Then on that Day none will be asked about his sin among men or jinn.'),
  ('en.sahih', 55, 40, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 41, 'The criminals will be known by their marks, and they will be seized by the forelocks and the feet.'),
  ('en.sahih', 55, 42, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 43, 'This is Hell, which the criminals deny.'),
  ('en.sahih', 55, 44, 'They will go around between it and scalding water, heated [to the utmost degree].'),
  ('en.sahih', 55, 45, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 46, 'But for he who has feared the position of his Lord are two gardens -'),
  ('en.sahih', 55, 47, 'So which of the favors of your Lord would you deny? -'),
  ('en.sahih', 55, 48, 'Having [spreading] branches.'),
  ('en.sahih', 55, 49, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 50, 'In both of them are two springs, flowing.'),
  ('en.sahih', 55, 51, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 52, 'In both of them are of every fruit, two kinds.'),
  ('en.sahih', 55, 53, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 54, '[They are] reclining on beds whose linings are of silk brocade, and the fruit of the two gardens is hanging low.'),
  ('en.sahih', 55, 55, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 56, 'In them are women limiting [their] glances, untouched before them by man or jinni -'),
  ('en.sahih', 55, 57, 'So which of the favors of your Lord would you deny? -'),
  ('en.sahih', 55, 58, 'As if they were rubies and coral.'),
  ('en.sahih', 55, 59, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 60, 'Is the reward for good [anything] but good?'),
  ('en.sahih', 55, 61, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 62, 'And below them both [in excellence] are two [other] gardens -'),
  ('en.sahih', 55, 63, 'So which of the favors of your Lord would you deny? -'),
  ('en.sahih', 55, 64, 'Dark green [in color].'),
  ('en.sahih', 55, 65, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 66, 'In both of them are two springs, spouting.'),
  ('en.sahih', 55, 67, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 68, 'In both of them are fruit and palm trees and pomegranates.'),
  ('en.sahih', 55, 69, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 70, 'In them are good and beautiful women -'),
  ('en.sahih', 55, 71, 'So which of the favors of your Lord would you deny? -'),
  ('en.sahih', 55, 72, 'Fair ones reserved in pavilions -'),
  ('en.sahih', 55, 73, 'So which of the favors of your Lord would you deny? -'),
  ('en.sahih', 55, 74, 'Untouched before them by man or jinni -'),
  ('en.sahih', 55, 75, 'So which of the favors of your Lord would you deny? -'),
  ('en.sahih', 55, 76, 'Reclining on green cushions and beautiful fine carpets.'),
  ('en.sahih', 55, 77, 'So which of the favors of your Lord would you deny?'),
  ('en.sahih', 55, 78, 'Blessed is the name of your Lord, Owner of Majesty and Honor.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 55, 1, 'করুনাময় আল্লাহ।'),
  ('bn.bengali', 55, 2, 'শিক্ষা দিয়েছেন কোরআন,'),
  ('bn.bengali', 55, 3, 'সৃষ্টি করেছেন মানুষ,'),
  ('bn.bengali', 55, 4, 'তাকে শিখিয়েছেন বর্ণনা।'),
  ('bn.bengali', 55, 5, 'সূর্য ও চন্দ্র হিসাবমত চলে।'),
  ('bn.bengali', 55, 6, 'এবং তৃণলতা ও বৃক্ষাদি সেজদারত আছে।'),
  ('bn.bengali', 55, 7, 'তিনি আকাশকে করেছেন সমুন্নত এবং স্থাপন করেছেন তুলাদন্ড।'),
  ('bn.bengali', 55, 8, 'যাতে তোমরা সীমালংঘন না কর তুলাদন্ডে।'),
  ('bn.bengali', 55, 9, 'তোমরা ন্যায্য ওজন কায়েম কর এবং ওজনে কম দিয়ো না।'),
  ('bn.bengali', 55, 10, 'তিনি পৃথিবীকে স্থাপন করেছেন সৃষ্টজীবের জন্যে।'),
  ('bn.bengali', 55, 11, 'এতে আছে ফলমূল এবং বহিরাবরণবিশিষ্ট খর্জুর বৃক্ষ।'),
  ('bn.bengali', 55, 12, 'আর আছে খোসাবিশিষ্ট শস্য ও সুগন্ধি ফুল।'),
  ('bn.bengali', 55, 13, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অনুগ্রহকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 14, 'তিনি মানুষকে সৃষ্টি করেছেন পোড়া মাটির ন্যায় শুষ্ক মৃত্তিকা থেকে।'),
  ('bn.bengali', 55, 15, 'এবং জিনকে সৃষ্টি করেছেন অগ্নিশিখা থেকে।'),
  ('bn.bengali', 55, 16, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অনুগ্রহ অস্বীকার করবে?'),
  ('bn.bengali', 55, 17, 'তিনি দুই উদয়াচল ও দুই অস্তাচলের মালিক।'),
  ('bn.bengali', 55, 18, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 19, 'তিনি পাশাপাশি দুই দরিয়া প্রবাহিত করেছেন।'),
  ('bn.bengali', 55, 20, 'উভয়ের মাঝখানে রয়েছে এক অন্তরাল, যা তারা অতিক্রম করে না।'),
  ('bn.bengali', 55, 21, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 22, 'উভয় দরিয়া থেকে উৎপন্ন হয় মোতি ও প্রবাল।'),
  ('bn.bengali', 55, 23, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 24, 'দরিয়ায় বিচরণশীল পর্বতদৃশ্য জাহাজসমূহ তাঁরই (নিয়ন্ত্রনাধীন)'),
  ('bn.bengali', 55, 25, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 26, 'ভূপৃষ্টের সবকিছুই ধ্বংসশীল।'),
  ('bn.bengali', 55, 27, 'একমাত্র আপনার মহিমায় ও মহানুভব পালনকর্তার সত্তা ছাড়া।'),
  ('bn.bengali', 55, 28, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 29, 'নভোমন্ডল ও ভূমন্ডলের সবাই তাঁর কাছে প্রার্থী। তিনি সর্বদাই কোন না কোন কাজে রত আছেন।'),
  ('bn.bengali', 55, 30, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 31, 'হে জিন ও মানব! আমি শীঘ্রই তোমাদের জন্যে কর্মমুক্ত হয়ে যাব।'),
  ('bn.bengali', 55, 32, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 33, 'হে জিন ও মানবকূল, নভোমন্ডল ও ভূমন্ডলের প্রান্ত অতিক্রম করা যদি তোমাদের সাধ্যে কুলায়, তবে অতিক্রম কর। কিন্তু ছাড়পত্র ব্যতীত তোমরা তা অতিক্রম করতে পারবে না।'),
  ('bn.bengali', 55, 34, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 35, 'ছাড়া হবে তোমাদের প্রতি অগ্নিস্ফুলিঙ্গ ও ধুম্রকুঞ্জ তখন তোমরা সেসব প্রতিহত করতে পারবে না।'),
  ('bn.bengali', 55, 36, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 37, 'যেদিন আকাশ বিদীর্ণ হবে তখন সেটি রক্তবর্ণে রঞ্জিত চামড়ার মত হয়ে যাবে।'),
  ('bn.bengali', 55, 38, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 39, 'সেদিন মানুষ না তার অপরাধ সম্পর্কে জিজ্ঞাসিত হবে, না জিন।'),
  ('bn.bengali', 55, 40, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 41, 'অপরাধীদের পরিচয় পাওয়া যাবে তাদের চেহারা থেকে; অতঃপর তাদের কপালের চুল ও পা ধরে টেনে নেয়া হবে।'),
  ('bn.bengali', 55, 42, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 43, 'এটাই জাহান্নাম, যাকে অপরাধীরা মিথ্যা বলত।'),
  ('bn.bengali', 55, 44, 'তারা জাহান্নামের অগ্নি ও ফুটন্ত পানির মাঝখানে প্রদক্ষিণ করবে।'),
  ('bn.bengali', 55, 45, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 46, 'যে ব্যক্তি তার পালনকর্তার সামনে পেশ হওয়ার ভয় রাখে, তার জন্যে রয়েছে দু’টি উদ্যান।'),
  ('bn.bengali', 55, 47, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 48, 'উভয় উদ্যানই ঘন শাখা-পল্লববিশিষ্ট।'),
  ('bn.bengali', 55, 49, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 50, 'উভয় উদ্যানে আছে বহমান দুই প্রস্রবন।'),
  ('bn.bengali', 55, 51, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 52, 'উভয়ের মধ্যে প্রত্যেক ফল বিভিন্ন রকমের হবে।'),
  ('bn.bengali', 55, 53, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 54, 'তারা তথায় রেশমের আস্তরবিশিষ্ট বিছানায় হেলান দিয়ে বসবে। উভয় উদ্যানের ফল তাদের নিকট ঝুলবে।'),
  ('bn.bengali', 55, 55, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 56, 'তথায় থাকবে আনতনয়ন রমনীগন, কোন জিন ও মানব পূর্বে যাদের ব্যবহার করেনি।'),
  ('bn.bengali', 55, 57, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 58, 'প্রবাল ও পদ্মরাগ সদৃশ রমণীগণ।'),
  ('bn.bengali', 55, 59, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 60, 'সৎকাজের প্রতিদান উত্তম পুরস্কার ব্যতীত কি হতে পারে?'),
  ('bn.bengali', 55, 61, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 62, 'এই দু’টি ছাড়া আরও দু’টি উদ্যান রয়েছে।'),
  ('bn.bengali', 55, 63, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 64, 'কালোমত ঘন সবুজ।'),
  ('bn.bengali', 55, 65, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 66, 'তথায় আছে উদ্বেলিত দুই প্রস্রবণ।'),
  ('bn.bengali', 55, 67, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 68, 'তথায় আছে ফল-মূল, খর্জুর ও আনার।'),
  ('bn.bengali', 55, 69, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 70, 'সেখানে থাকবে সচ্চরিত্রা সুন্দরী রমণীগণ।'),
  ('bn.bengali', 55, 71, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 72, 'তাঁবুতে অবস্থানকারিণী হুরগণ।'),
  ('bn.bengali', 55, 73, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 74, 'কোন জিন ও মানব পূর্বে তাদেরকে স্পর্শ করেনি।'),
  ('bn.bengali', 55, 75, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 76, 'তারা সবুজ মসনদে এবং উৎকৃষ্ট মূল্যবান বিছানায় হেলান দিয়ে বসবে।'),
  ('bn.bengali', 55, 77, 'অতএব, তোমরা উভয়ে তোমাদের পালনকর্তার কোন কোন অবদানকে অস্বীকার করবে?'),
  ('bn.bengali', 55, 78, 'কত পূণ্যময় আপনার পালনকর্তার নাম, যিনি মহিমাময় ও মহানুভব।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 55, 1, 'The Beneficent'),
  ('en.pickthall', 55, 2, 'Hath made known the Qur\'an.'),
  ('en.pickthall', 55, 3, 'He hath created man.'),
  ('en.pickthall', 55, 4, 'He hath taught him utterance.'),
  ('en.pickthall', 55, 5, 'The sun and the moon are made punctual.'),
  ('en.pickthall', 55, 6, 'The stars and the trees prostrate.'),
  ('en.pickthall', 55, 7, 'And the sky He hath uplifted; and He hath set the measure,'),
  ('en.pickthall', 55, 8, 'That ye exceed not the measure,'),
  ('en.pickthall', 55, 9, 'But observe the measure strictly, nor fall short thereof.'),
  ('en.pickthall', 55, 10, 'And the earth hath He appointed for (His) creatures,'),
  ('en.pickthall', 55, 11, 'Wherein are fruit and sheathed palm-trees,'),
  ('en.pickthall', 55, 12, 'Husked grain and scented herb.'),
  ('en.pickthall', 55, 13, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 14, 'He created man of clay like the potter\'s,'),
  ('en.pickthall', 55, 15, 'And the jinn did He create of smokeless fire.'),
  ('en.pickthall', 55, 16, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 17, 'Lord of the two Easts, and Lord of the two Wests!'),
  ('en.pickthall', 55, 18, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 19, 'He hath loosed the two seas. They meet.'),
  ('en.pickthall', 55, 20, 'There is a barrier between them. They encroach not (one upon the other).'),
  ('en.pickthall', 55, 21, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 22, 'There cometh forth from both of them the pearl and coral-stone.'),
  ('en.pickthall', 55, 23, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 24, 'His are the ships displayed upon the sea, like banners.'),
  ('en.pickthall', 55, 25, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 26, 'Everyone that is thereon will pass away;'),
  ('en.pickthall', 55, 27, 'There remaineth but the Countenance of thy Lord of Might and Glory.'),
  ('en.pickthall', 55, 28, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 29, 'All that are in the heavens and the earth entreat Him. Every day He exerciseth (universal) power.'),
  ('en.pickthall', 55, 30, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 31, 'We shall dispose of you, O ye two dependents (man and jinn).'),
  ('en.pickthall', 55, 32, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 33, 'O company of jinn and men, if ye have power to penetrate (all) regions of the heavens and the earth, then penetrate (them)! Ye will never penetrate them save with (Our) sanction.'),
  ('en.pickthall', 55, 34, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 35, 'There will be sent, against you both, heat of fire and flash of brass, and ye will not escape.'),
  ('en.pickthall', 55, 36, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 37, 'And when the heaven splitteth asunder and becometh rosy like red hide -'),
  ('en.pickthall', 55, 38, 'Which is it, of the favours of your Lord, that ye deny? -'),
  ('en.pickthall', 55, 39, 'On that day neither man nor jinni will be questioned of his sin.'),
  ('en.pickthall', 55, 40, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 41, 'The guilty will be known by their marks, and will be taken by the forelocks and the feet.'),
  ('en.pickthall', 55, 42, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 43, 'This is hell which the guilty deny.'),
  ('en.pickthall', 55, 44, 'They go circling round between it and fierce, boiling water.'),
  ('en.pickthall', 55, 45, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 46, 'But for him who feareth the standing before his Lord there are two gardens.'),
  ('en.pickthall', 55, 47, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 48, 'Of spreading branches.'),
  ('en.pickthall', 55, 49, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 50, 'Wherein are two fountains flowing.'),
  ('en.pickthall', 55, 51, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 52, 'Wherein is every kind of fruit in pairs.'),
  ('en.pickthall', 55, 53, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 54, 'Reclining upon couches lined with silk brocade, the fruit of both the gardens near to hand.'),
  ('en.pickthall', 55, 55, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 56, 'Therein are those of modest gaze, whom neither man nor jinni will have touched before them.'),
  ('en.pickthall', 55, 57, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 58, '(In beauty) like the jacynth and the coral-stone.'),
  ('en.pickthall', 55, 59, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 60, 'Is the reward of goodness aught save goodness?'),
  ('en.pickthall', 55, 61, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 62, 'And beside them are two other gardens,'),
  ('en.pickthall', 55, 63, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 64, 'Dark green with foliage.'),
  ('en.pickthall', 55, 65, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 66, 'Wherein are two abundant springs.'),
  ('en.pickthall', 55, 67, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 68, 'Wherein is fruit, the date-palm and pomegranate.'),
  ('en.pickthall', 55, 69, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 70, 'Wherein (are found) the good and beautiful -'),
  ('en.pickthall', 55, 71, 'Which is it, of the favours of your Lord, that ye deny? -'),
  ('en.pickthall', 55, 72, 'Fair ones, close-guarded in pavilions -'),
  ('en.pickthall', 55, 73, 'Which is it, of the favours of your Lord, that ye deny? -'),
  ('en.pickthall', 55, 74, 'Whom neither man nor jinni will have touched before them -'),
  ('en.pickthall', 55, 75, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 76, 'Reclining on green cushions and fair carpets.'),
  ('en.pickthall', 55, 77, 'Which is it, of the favours of your Lord, that ye deny?'),
  ('en.pickthall', 55, 78, 'Blessed be the name of thy Lord, Mighty and glorious!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 55, 1, '(Allah) Most Gracious!'),
  ('en.yusufali', 55, 2, 'It is He Who has taught the Qur\'an.'),
  ('en.yusufali', 55, 3, 'He has created man:'),
  ('en.yusufali', 55, 4, 'He has taught him speech (and intelligence).'),
  ('en.yusufali', 55, 5, 'The sun and the moon follow courses (exactly) computed;'),
  ('en.yusufali', 55, 6, 'And the herbs and the trees - both (alike) prostrate in adoration.'),
  ('en.yusufali', 55, 7, 'And the Firmament has He raised high, and He has set up the Balance (of Justice),'),
  ('en.yusufali', 55, 8, 'In order that ye may not transgress (due) balance.'),
  ('en.yusufali', 55, 9, 'So establish weight with justice and fall not short in the balance.'),
  ('en.yusufali', 55, 10, 'It is He Who has spread out the earth for (His) creatures:'),
  ('en.yusufali', 55, 11, 'Therein is fruit and date-palms, producing spathes (enclosing dates);'),
  ('en.yusufali', 55, 12, 'Also corn, with (its) leaves and stalk for fodder, and sweet-smelling plants.'),
  ('en.yusufali', 55, 13, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 14, 'He created man from sounding clay like unto pottery,'),
  ('en.yusufali', 55, 15, 'And He created Jinns from fire free of smoke:'),
  ('en.yusufali', 55, 16, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 17, '(He is) Lord of the two Easts and Lord of the two Wests:'),
  ('en.yusufali', 55, 18, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 19, 'He has let free the two bodies of flowing water, meeting together:'),
  ('en.yusufali', 55, 20, 'Between them is a Barrier which they do not transgress:'),
  ('en.yusufali', 55, 21, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 22, 'Out of them come Pearls and Coral:'),
  ('en.yusufali', 55, 23, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 24, 'And His are the Ships sailing smoothly through the seas, lofty as mountains:'),
  ('en.yusufali', 55, 25, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 26, 'All that is on earth will perish:'),
  ('en.yusufali', 55, 27, 'But will abide (for ever) the Face of thy Lord,- full of Majesty, Bounty and Honour.'),
  ('en.yusufali', 55, 28, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 29, 'Of Him seeks (its need) every creature in the heavens and on earth: every day in (new) Splendour doth He (shine)!'),
  ('en.yusufali', 55, 30, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 31, 'Soon shall We settle your affairs, O both ye worlds!'),
  ('en.yusufali', 55, 32, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 33, 'O ye assembly of Jinns and men! If it be ye can pass beyond the zones of the heavens and the earth, pass ye! not without authority shall ye be able to pass!'),
  ('en.yusufali', 55, 34, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 35, 'On you will be sent (O ye evil ones twain!) a flame of fire (to burn) and a smoke (to choke): no defence will ye have:'),
  ('en.yusufali', 55, 36, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 37, 'When the sky is rent asunder, and it becomes red like ointment:'),
  ('en.yusufali', 55, 38, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 39, 'On that Day no question will be asked of man or Jinn as to his sin.'),
  ('en.yusufali', 55, 40, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 41, '(For) the sinners will be known by their marks: and they will be seized by their forelocks and their feet.'),
  ('en.yusufali', 55, 42, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 43, 'This is the Hell which the Sinners deny:'),
  ('en.yusufali', 55, 44, 'In its midst and in the midst of boiling hot water will they wander round!'),
  ('en.yusufali', 55, 45, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 46, 'But for such as fear the time when they will stand before (the Judgment Seat of) their Lord, there will be two Gardens-'),
  ('en.yusufali', 55, 47, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 48, 'Containing all kinds (of trees and delights);-'),
  ('en.yusufali', 55, 49, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 50, 'In them (each) will be two Springs flowing (free);'),
  ('en.yusufali', 55, 51, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 52, 'In them will be Fruits of every kind, two and two.'),
  ('en.yusufali', 55, 53, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 54, 'They will recline on Carpets, whose inner linings will be of rich brocade: the Fruit of the Gardens will be near (and easy of reach).'),
  ('en.yusufali', 55, 55, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 56, 'In them will be (Maidens), chaste, restraining their glances, whom no man or Jinn before them has touched;-'),
  ('en.yusufali', 55, 57, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 58, 'Like unto Rubies and coral.'),
  ('en.yusufali', 55, 59, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 60, 'Is there any Reward for Good - other than Good?'),
  ('en.yusufali', 55, 61, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 62, 'And besides these two, there are two other Gardens,-'),
  ('en.yusufali', 55, 63, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 64, 'Dark-green in colour (from plentiful watering).'),
  ('en.yusufali', 55, 65, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 66, 'In them (each) will be two Springs pouring forth water in continuous abundance:'),
  ('en.yusufali', 55, 67, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 68, 'In them will be Fruits, and dates and pomegranates:'),
  ('en.yusufali', 55, 69, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 70, 'In them will be fair (Companions), good, beautiful;-'),
  ('en.yusufali', 55, 71, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 72, 'Companions restrained (as to their glances), in (goodly) pavilions;-'),
  ('en.yusufali', 55, 73, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 74, 'Whom no man or Jinn before them has touched;-'),
  ('en.yusufali', 55, 75, 'Then which of the favours of your Lord will ye deny?-'),
  ('en.yusufali', 55, 76, 'Reclining on green Cushions and rich Carpets of beauty.'),
  ('en.yusufali', 55, 77, 'Then which of the favours of your Lord will ye deny?'),
  ('en.yusufali', 55, 78, 'Blessed be the name of thy Lord, full of Majesty, Bounty and Honour.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 55, 1, 'Ar Rahmaan'),
  ('en.transliteration', 55, 2, '\'Allamal Quran'),
  ('en.transliteration', 55, 3, 'Khalaqal insaan'),
  ('en.transliteration', 55, 4, '\'Allamalhul bayaan'),
  ('en.transliteration', 55, 5, 'Ashshamsu walqamaru bihusbaan'),
  ('en.transliteration', 55, 6, 'Wannajmu washshajaru yasjudan'),
  ('en.transliteration', 55, 7, 'Wassamaaa\'a rafa\'ahaa wa wada\'al Meezan'),
  ('en.transliteration', 55, 8, 'Allaa tatghaw fil meezaan'),
  ('en.transliteration', 55, 9, 'Wa aqeemul wazna bilqisti wa laa tukhsirul meezaan'),
  ('en.transliteration', 55, 10, 'Wal arda wada\'ahaa lilanaame'),
  ('en.transliteration', 55, 11, 'Feehaa faakihatunw wan nakhlu zaatul akmaam'),
  ('en.transliteration', 55, 12, 'Walhabbu zul \'asfi war Raihaanu'),
  ('en.transliteration', 55, 13, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan'),
  ('en.transliteration', 55, 14, 'Khalaqal insaana min salsaalin kalfakhkhaari'),
  ('en.transliteration', 55, 15, 'Wa khalaqal jaaan mim maarijim min naar'),
  ('en.transliteration', 55, 16, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan'),
  ('en.transliteration', 55, 17, 'Rabbul mashriqayni wa Rabbul maghribayni'),
  ('en.transliteration', 55, 18, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan'),
  ('en.transliteration', 55, 19, 'Marajal bahrayni yalta qiyaani'),
  ('en.transliteration', 55, 20, 'Bainahumaa barzakhul laa yabghiyaan'),
  ('en.transliteration', 55, 21, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan'),
  ('en.transliteration', 55, 22, 'Yakhruju minhumal lu \'lu u wal marjaanu'),
  ('en.transliteration', 55, 23, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan'),
  ('en.transliteration', 55, 24, 'Wa lahul jawaaril mun sha\'aatu fil bahri kal a\'laam'),
  ('en.transliteration', 55, 25, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 26, 'Kullu man \'alaihaa faan'),
  ('en.transliteration', 55, 27, 'Wa yabqaa wajhu rabbika zul jalaali wal ikraam'),
  ('en.transliteration', 55, 28, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 29, 'Yas\'aluhoo man fissamaawaati walard; kulla ywmin huwa fee shaan'),
  ('en.transliteration', 55, 30, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 31, 'Sanafrughu lakum ayyuhas saqalaan'),
  ('en.transliteration', 55, 32, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 33, 'Yaa ma\'sharal jinni wal insi inis tata\'tum an tanfuzoo min aqtaaris samaawaati wal ardi fanfuzoo; laa tanfuzoona illaa bisultaan'),
  ('en.transliteration', 55, 34, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 35, 'Yursalu \'alaikumaa shuwaazum min naarifiw-wa nuhaasun falaa tantasiraan'),
  ('en.transliteration', 55, 36, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 37, 'Fa-izan shaqqatis samaaa\'u fakaanat wardatan kaddihaan'),
  ('en.transliteration', 55, 38, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 39, 'Fa-yawma\'izil laa yus\'alu \'an zambiheee insunw wa laa jaann'),
  ('en.transliteration', 55, 40, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 41, 'Yu\'raful mujrimoona biseemaahum fa\'yu\'khazu binna waasi wal aqdaam'),
  ('en.transliteration', 55, 42, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 43, 'Haazihee jahannamul latee yukazzibu bihal mujrimoon'),
  ('en.transliteration', 55, 44, 'Yatoofoona bainahaa wa baina hameemim aan'),
  ('en.transliteration', 55, 45, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 46, 'Wa liman khaafa maqaama rabbihee jannataan'),
  ('en.transliteration', 55, 47, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 48, 'Zawaataaa afnaan'),
  ('en.transliteration', 55, 49, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 50, 'Feehimaa \'aynaani tajriyaan'),
  ('en.transliteration', 55, 51, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 52, 'Feehimaa min kulli faakihatin zawjaan'),
  ('en.transliteration', 55, 53, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 54, 'Muttaki\'eena \'alaa furushim bataaa\'inuhaa min istabraq; wajanal jannataini daan'),
  ('en.transliteration', 55, 55, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 56, 'Feehinna qaasiratut tarfi lam yatmishunna insun qablahum wa laa jaaann'),
  ('en.transliteration', 55, 57, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 58, 'ka annahunnal yaaqootu wal marjaan'),
  ('en.transliteration', 55, 59, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 60, 'Hal jazaaa\'ul ihsaani illal ihsaan'),
  ('en.transliteration', 55, 61, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 62, 'Wa min doonihimaa jannataan'),
  ('en.transliteration', 55, 63, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 64, 'Mudhaaammataan'),
  ('en.transliteration', 55, 65, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 66, 'Feehimaa \'aynaani nad daakhataan'),
  ('en.transliteration', 55, 67, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 68, 'Feehimaa faakihatunw wa nakhlunw wa rummaan'),
  ('en.transliteration', 55, 69, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 70, 'Feehinna khairaatun hisaan'),
  ('en.transliteration', 55, 71, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 72, 'Hoorum maqsooraatun fil khiyaam'),
  ('en.transliteration', 55, 73, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 74, 'Lam yatmis hunna insun qablahum wa laa jaaann'),
  ('en.transliteration', 55, 75, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 76, 'Muttaki\'eena \'alaa rafratin khudrinw wa \'abqariyyin hisaan'),
  ('en.transliteration', 55, 77, 'Fabi ayyi aalaaa\'i Rabbikumaa tukazzibaan.'),
  ('en.transliteration', 55, 78, 'Tabaarakasmu Rabbika Zil-Jalaali wal-Ikraam')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 55, 1, 'رحمنٰ ہی نے'),
  ('ur.ahmedali', 55, 2, 'قرآن سکھایا'),
  ('ur.ahmedali', 55, 3, 'اس نے انسان کو پیدا کیا'),
  ('ur.ahmedali', 55, 4, 'اسے بولنا سکھایا'),
  ('ur.ahmedali', 55, 5, 'سورج اور چاند ایک حساب سے چل رہے ہیں'),
  ('ur.ahmedali', 55, 6, 'اوربیلیں اور درخت سجدہ کر رہے ہیں'),
  ('ur.ahmedali', 55, 7, 'اور آسمان کو اسی نے بلند کر دیا اور ترازو قائم کی'),
  ('ur.ahmedali', 55, 8, 'تاکہ تم تولنے میں زیادتی نہ کرو'),
  ('ur.ahmedali', 55, 9, 'اور انصاف سے تولو اور تول نہ گھٹاؤ'),
  ('ur.ahmedali', 55, 10, 'اور اس نے خلقت کے لیے زمین کو بچھا دیا'),
  ('ur.ahmedali', 55, 11, 'اس میں میوے اور غلافوں والی کھجوریں ہیں'),
  ('ur.ahmedali', 55, 12, 'اور بھوسے دار اناج اور پھول خوشبو دار ہیں'),
  ('ur.ahmedali', 55, 13, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 14, 'اس نے انسان کو ٹھیکری کی طرح بجتی ہوئی مٹی سے پیدا کیا'),
  ('ur.ahmedali', 55, 15, 'اور اس نے جنوں کو آگ کے شعلے سے پیدا کیا'),
  ('ur.ahmedali', 55, 16, 'پھر تم (اے جن و انس) اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 17, 'وہ دونوں مشرقوں اور مغربوں کا مالک ہے'),
  ('ur.ahmedali', 55, 18, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 19, 'اس نے دو سمندر ملا دیئے جو باہم ملتے ہیں'),
  ('ur.ahmedali', 55, 20, 'ان دونوں میں پردہ ہے کہ وہ حد سے تجاوز نہیں کرسکتے'),
  ('ur.ahmedali', 55, 21, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 22, 'ان دونوں میں سے موتی اور مونگا نکلتا ہے'),
  ('ur.ahmedali', 55, 23, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 24, 'اور سمند ر میں پہا ڑوں جیسے کھڑے ہوئے جہاز اسی کے ہیں'),
  ('ur.ahmedali', 55, 25, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 26, 'جو کوئی زمین پر ہے فنا ہوجانے والا ہے'),
  ('ur.ahmedali', 55, 27, 'اور آپ کے پروردگار کی ذات باقی رہے گی جو بڑی شان اور عظمت والا ہے'),
  ('ur.ahmedali', 55, 28, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 29, 'اس سے مانگتے ہیں جو آسمانوں اور زمین میں ہیں ہر روز وہ ایک کام میں ہے'),
  ('ur.ahmedali', 55, 30, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 31, 'اے جن و انس ہم تمہارے لیے جلد ہی فارغ ہو جائیں گے'),
  ('ur.ahmedali', 55, 32, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 33, 'اے جنوں اور انسانوں کے گروہ اگر تم آسمانوں اور زمین کی حدود سے باہر نکل سکتے ہو تو نکل جاؤ تم بغیر زور کے نہ نکل سکو گے (اور وہ ہے نہیں)'),
  ('ur.ahmedali', 55, 34, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 35, 'تم پر آگے کے شعلے اور دھواں چھوڑا جائے گا پھر تم بچ نہ سکو گے'),
  ('ur.ahmedali', 55, 36, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 37, 'پھر جب آسمان پھٹ جائے گا اور پھٹ کر گلابی تیل کی طرح سرخ ہو جائے گا'),
  ('ur.ahmedali', 55, 38, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 39, 'پس اس دن اپنے گناہ کی بات نہ کوئی انسان اور نہ کوئی جن پوچھا جائے گا'),
  ('ur.ahmedali', 55, 40, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 41, 'مجرم اپنے چہرے کے نشان سے پہچانے جائیں گے پس پیشانی کے بالوں اور پاؤں سے پکڑے جائیں گے'),
  ('ur.ahmedali', 55, 42, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 43, 'یہی وہ دوزخ ہے جسے مجرم جھٹلاتے تھے'),
  ('ur.ahmedali', 55, 44, 'گناہ گار جہنم میں اور کھولتے ہوئے پانی میں تڑپتے پھریں گے'),
  ('ur.ahmedali', 55, 45, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 46, 'اوراس کے لیے جو اپنے رب کے سامنے کھڑا ہونے سے ڈرتا ہے دو باغ ہوں گے'),
  ('ur.ahmedali', 55, 47, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 48, 'جن میں بہت سی شاخیں ہوں گی'),
  ('ur.ahmedali', 55, 49, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 50, 'ان دونوں میں دو چشمے جاری ہوں گے'),
  ('ur.ahmedali', 55, 51, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 52, 'ان دونوں میں ہر میوہ کی دو قسمیں ہوں گی'),
  ('ur.ahmedali', 55, 53, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 54, 'ایسے فرشتو ں پر تکیہ لگائے بیٹھے ہوں گے کہ جن کا استر مخملی ہوگا اور دونوں باغوں کا میوہ جھک رہا ہوگا'),
  ('ur.ahmedali', 55, 55, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 56, 'ان میں نیچی نگاہوں والی عورتیں ہوں گی نہ تو انہیں ان سے پہلے کسی انسان نے اور نہ کسی جن نے چھوا ہوگا'),
  ('ur.ahmedali', 55, 57, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 58, 'گویا کہ وہ یاقوت اور مونگا ہیں'),
  ('ur.ahmedali', 55, 59, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 60, 'نیکی کا بدلہ نیکی کے سوا اور کیا ہے'),
  ('ur.ahmedali', 55, 61, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 62, 'اور ان دو کے علاوہ اور دو باغ ہوں گے'),
  ('ur.ahmedali', 55, 63, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 64, 'وہ دونوں بہت ہی سبز ہوں گے'),
  ('ur.ahmedali', 55, 65, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 66, 'ان دونوں میں دو چشمے ابلتےہوئے ہوں گے'),
  ('ur.ahmedali', 55, 67, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 68, 'ان دونوں میں میوے اور کھجوریں اور انار ہوں گے'),
  ('ur.ahmedali', 55, 69, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 70, 'ان میں نیک خوبصورت عورتیں ہوں گی'),
  ('ur.ahmedali', 55, 71, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 72, 'وہ حوریں جو خیموں میں بند ہوں گی'),
  ('ur.ahmedali', 55, 73, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 74, 'نہ انہیں ان سےپہلے کسی انسان نے اور نہ کسی جن نے چھوا ہوگا'),
  ('ur.ahmedali', 55, 75, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 76, 'قالینوں پر تکیہ لگائے ہوئے ہوں گے جو سبز اور نہایت قیمتی نفیس ہوں گے'),
  ('ur.ahmedali', 55, 77, 'پھر تم اپنے رب کی کس کس نعمت کو جھٹلاؤ گے'),
  ('ur.ahmedali', 55, 78, 'آپ کے رب کا نام با برکت ہے جو بڑی شان اور عظمت والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 55, 1, 'Rahman olan Allah Kuran\'ı öğretti;'),
  ('tr.diyanet', 55, 2, 'Rahman olan Allah Kuran\'ı öğretti;'),
  ('tr.diyanet', 55, 3, 'İnsanı yarattı, ona konuşmayı öğretti.'),
  ('tr.diyanet', 55, 4, 'İnsanı yarattı, ona konuşmayı öğretti.'),
  ('tr.diyanet', 55, 5, 'Güneş ve ayın hareketleri bir hesaba göredir.'),
  ('tr.diyanet', 55, 6, 'Bitkiler ve ağaçlar O\'nun buyruğuna boyun eğerler.'),
  ('tr.diyanet', 55, 7, 'O, göğü yükseltmiştir; tartıyı koymuştur.'),
  ('tr.diyanet', 55, 8, 'Artık tartıda tecavüz etmeyin.'),
  ('tr.diyanet', 55, 9, 'Tartmayı doğru yapın, tartıyı eksik tutmayın.'),
  ('tr.diyanet', 55, 10, 'Allah, yeri yaratıkları için meydana getirmiştir.'),
  ('tr.diyanet', 55, 11, 'Orada meyveler, salkımlı hurma ağaçları, kabuklu taneler, güzel kokulu otlar vardır.'),
  ('tr.diyanet', 55, 12, 'Orada meyveler, salkımlı hurma ağaçları, kabuklu taneler, güzel kokulu otlar vardır.'),
  ('tr.diyanet', 55, 13, 'Ey insanlar ve cinler! Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 14, 'O, insanı pişmiş çamur gibi kuru balçıktan yaratmıştır.'),
  ('tr.diyanet', 55, 15, 'Cinleri de yalın bir alevden yaratmıştır.'),
  ('tr.diyanet', 55, 16, 'Öyleyken; Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 17, 'O, iki doğunun Rabbidir, iki batının Rabbidir.'),
  ('tr.diyanet', 55, 18, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 19, 'Acı ve tatlı sulu iki denizi birbirine kavuşmamak üzere salıvermiştir.'),
  ('tr.diyanet', 55, 20, 'Aralarında bir engel vardır; birbirinin sınırını aşamazlar.'),
  ('tr.diyanet', 55, 21, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 22, 'Bu iki denizden de inci ve mercan çıkar.'),
  ('tr.diyanet', 55, 23, 'Öyleyken Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 24, 'Denizde yürüyen dağlar gibi gemiler O\'nundur.'),
  ('tr.diyanet', 55, 25, 'Öyleyken Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 26, 'Yeryüzünde bulunan her şey fanidir.'),
  ('tr.diyanet', 55, 27, 'Ancak, yüce ve cömert olan Rabbinin varlığı bakidir.'),
  ('tr.diyanet', 55, 28, 'Öyleyken Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 29, 'Göklerde ve yerde olan kimseler her şeyi O\'ndan isterler; O her an kainata tasarruf etmektedir.'),
  ('tr.diyanet', 55, 30, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 31, 'Ey insan ve cin toplulukları! Sizin de hesabınızı ele alacağız.'),
  ('tr.diyanet', 55, 32, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 33, 'Ey cin ve insan toplulukları! Göklerin ve yerin çevresini aşıp geçmeye gücünüz yetiyorsa geçin! Ama Allah\'ın verdiği bir güç olmaksızın geçemezsiniz ki!'),
  ('tr.diyanet', 55, 34, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 35, 'Ey insanlar ve cinler! Üzerinize dumansız bir alev ve ateşsiz bir duman gönderilir de kurtulamazsınız.'),
  ('tr.diyanet', 55, 36, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 37, 'Gök yarılıp da, gül gibi kızardığı, yağ gibi eridiği zaman haliniz nice olur?'),
  ('tr.diyanet', 55, 38, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 39, 'O gün ne insana ve ne cine suçu sorulur.'),
  ('tr.diyanet', 55, 40, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 41, 'Suçlular simalarından tanınırlar da, alın saçlarından ve ayaklarından yakalanırlar.'),
  ('tr.diyanet', 55, 42, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 43, 'İşte suçluların yalanladıkları cehennem budur.'),
  ('tr.diyanet', 55, 44, 'Onlar, cehennem ateşiyle kaynar su arasında dolaşır dururlar.'),
  ('tr.diyanet', 55, 45, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 46, 'Rabbine karşı durmaktan korkan kimseye iki cennet vardır.'),
  ('tr.diyanet', 55, 47, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 48, 'Bu iki cennet türlü ağaçlarla doludur.'),
  ('tr.diyanet', 55, 49, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 50, 'Bu cennetlerden akan iki kaynak vardır.'),
  ('tr.diyanet', 55, 51, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 52, 'Bu cennetlerde türlü meyveden çift çift vardır.'),
  ('tr.diyanet', 55, 53, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 54, 'Orada, örtüleri parlak atlastan yataklara yaslanırlar; iki cennetin meyvelerini de kolayca toplarlar.'),
  ('tr.diyanet', 55, 55, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 56, 'Orada, bakışlarını yalnız eşlerine çevirmiş, daha önce ne insan ve ne de cinlerin dokunmuş olduğu eşler vardır.'),
  ('tr.diyanet', 55, 57, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 58, 'Onlar yakut ve mercan gibidirler.'),
  ('tr.diyanet', 55, 59, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 60, 'İyiliğin karşılığı ancak iyilik değil midir?'),
  ('tr.diyanet', 55, 61, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 62, 'Bu iki cennetten başka iki cennet daha vardır.'),
  ('tr.diyanet', 55, 63, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 64, 'Renkleri koyu yeşildir.'),
  ('tr.diyanet', 55, 65, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 66, 'İkisinde de durmadan fışkıran iki kaynak vardır.'),
  ('tr.diyanet', 55, 67, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 68, 'İkisinde de türlü türlü meyveler, hurmalıklar ve nar ağaçları vardır.'),
  ('tr.diyanet', 55, 69, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 70, 'Oralarda iyi huylu güzel kadınlar vardır.'),
  ('tr.diyanet', 55, 71, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 72, 'Çadırlar içinde ceylan gözlüler vardır.'),
  ('tr.diyanet', 55, 73, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 74, 'Onlara daha önce insan da, cin de dokunmamıştır.'),
  ('tr.diyanet', 55, 75, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 76, 'Cennetlikler orada yeşil yastıklara ve harikulade işlemeli döşeklere yaslanırlar.'),
  ('tr.diyanet', 55, 77, 'Öyleyken, Rabbinizin nimetlerinden hangisini yalanlarsınız?'),
  ('tr.diyanet', 55, 78, 'Büyük ve pek cömert olan Rabbinin adı ne yücedir!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 55, 1, '(Tuhan) Yang Maha Pemurah,'),
  ('id.indonesian', 55, 2, 'Yang telah mengajarkan al Quran.'),
  ('id.indonesian', 55, 3, 'Dia menciptakan manusia.'),
  ('id.indonesian', 55, 4, 'Mengajarnya pandai berbicara.'),
  ('id.indonesian', 55, 5, 'Matahari dan bulan (beredar) menurut perhitungan.'),
  ('id.indonesian', 55, 6, 'Dan tumbuh-tumbuhan dan pohon-pohonan kedua-duanya tunduk kepada-Nya.'),
  ('id.indonesian', 55, 7, 'Dan Allah telah meninggikan langit dan Dia meletakkan neraca (keadilan).'),
  ('id.indonesian', 55, 8, 'Supaya kamu jangan melampaui batas tentang neraca itu.'),
  ('id.indonesian', 55, 9, 'Dan tegakkanlah timbangan itu dengan adil dan janganlah kamu mengurangi neraca itu.'),
  ('id.indonesian', 55, 10, 'Dan Allah telah meratakan bumi untuk makhluk(Nya).'),
  ('id.indonesian', 55, 11, 'Di bumi itu ada buah-buahan dan pohon kurma yang mempunyai kelopak mayang.'),
  ('id.indonesian', 55, 12, 'Dan biji-bijian yang berkulit dan bunga-bunga yang harum baunya.'),
  ('id.indonesian', 55, 13, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 14, 'Dia menciptakan manusia dari tanah kering seperti tembikar,'),
  ('id.indonesian', 55, 15, 'dan Dia menciptakan jin dari nyala api.'),
  ('id.indonesian', 55, 16, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 17, 'Tuhan yang memelihara kedua tempat terbit matahari dan Tuhan yang memelihara kedua tempat terbenamnya'),
  ('id.indonesian', 55, 18, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 19, 'Dia membiarkan dua lautan mengalir yang keduanya kemudian bertemu,'),
  ('id.indonesian', 55, 20, 'antara keduanya ada batas yang tidak dilampaui masing-masing.'),
  ('id.indonesian', 55, 21, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 22, 'Dari keduanya keluar mutiara dan marjan.'),
  ('id.indonesian', 55, 23, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 24, 'Dan kepunyaan-Nya lah bahtera-bahtera yang tinggi layarnya di lautan laksana gunung-gunung.'),
  ('id.indonesian', 55, 25, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 26, 'Semua yang ada di bumi itu akan binasa.'),
  ('id.indonesian', 55, 27, 'Dan tetap kekal Dzat Tuhanmu yang mempunyai kebesaran dan kemuliaan.'),
  ('id.indonesian', 55, 28, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 29, 'Semua yang ada di langit dan bumi selalu meminta kepada-Nya. Setiap waktu Dia dalam kesibukan.'),
  ('id.indonesian', 55, 30, 'Maka nikmat Rabb-mu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 31, 'Kami akan memperhatikan sepenuhnya kepadamu hai manusia dan jin.'),
  ('id.indonesian', 55, 32, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 33, 'Hai jama\'ah jin dan manusia, jika kamu sanggup menembus (melintasi) penjuru langit dan bumi, maka lintasilah, kamu tidak dapat menembusnya kecuali dengan kekuatan.'),
  ('id.indonesian', 55, 34, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 35, 'Kepada kamu, (jin dan manusia) dilepaskan nyala api dan cairan tembaga maka kamu tidak dapat menyelamatkan diri (dari padanya).'),
  ('id.indonesian', 55, 36, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 37, 'Maka apabila langit telah terbelah dan menjadi merah mawar seperti (kilapan) minyak.'),
  ('id.indonesian', 55, 38, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 39, 'Pada waktu itu manusia dan jin tidak ditanya tentang dosanya.'),
  ('id.indonesian', 55, 40, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 41, 'Orang-orang yang berdosa dikenal dengan tanda-tandannya, lalu dipegang ubun-ubun dan kaki mereka.'),
  ('id.indonesian', 55, 42, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 43, 'Inilah neraka Jahannam yang didustakan oleh orang-orang berdosa.'),
  ('id.indonesian', 55, 44, 'Mereka berkeliling di antaranya dan di antara air mendidih yang memuncak panasnya.'),
  ('id.indonesian', 55, 45, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 46, 'Dan bagi orang yang takut akan saat menghadap Tuhannya ada dua surga.'),
  ('id.indonesian', 55, 47, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?,'),
  ('id.indonesian', 55, 48, 'kedua surga itu mempunyai pohon-pohonan dan buah-buahan.'),
  ('id.indonesian', 55, 49, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 50, 'Di dalam kedua surga itu ada dua buah mata air yang mengalir'),
  ('id.indonesian', 55, 51, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 52, 'Di dalam kedua surga itu terdapat segala macam buah-buahan yang berpasangan.'),
  ('id.indonesian', 55, 53, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 54, 'Mereka bertelekan di atas permadani yang sebelah dalamnya dari sutera. Dan buah-buahan di kedua surga itu dapat (dipetik) dari dekat.'),
  ('id.indonesian', 55, 55, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 56, 'Di dalam surga itu ada bidadari-bidadari yang sopan menundukkan pandangannya, tidak pernah disentuh oleh manusia sebelum mereka (penghuni-penghuni surga yang menjadi suami mereka), dan tidak pula oleh jin.'),
  ('id.indonesian', 55, 57, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 58, 'Seakan-akan bidadari itu permata yakut dan marjan.'),
  ('id.indonesian', 55, 59, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 60, 'Tidak ada balasan kebaikan kecuali kebaikan (pula).'),
  ('id.indonesian', 55, 61, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 62, 'Dan selain dari dua surga itu ada dua surga lagi'),
  ('id.indonesian', 55, 63, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 64, 'Kedua surga itu (kelihatan) hijau tua warnanya.'),
  ('id.indonesian', 55, 65, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 66, 'Di dalam kedua surga itu ada dua buah mata air yang memancar.'),
  ('id.indonesian', 55, 67, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 68, 'Di dalam keduanya (ada macam-macam) buah-buahan dan kurma serta delima.'),
  ('id.indonesian', 55, 69, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 70, 'Di dalam surga itu ada bidadari-bidadari yang baik-baik lagi cantik-cantik.'),
  ('id.indonesian', 55, 71, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 72, '(Bidadari-bidadari) yang jelita, putih bersih, dipingit dalam rumah.'),
  ('id.indonesian', 55, 73, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 74, 'Mereka tidak pernah disentuh oleh manusia sebelum mereka (penghuni-penghuni surga yang menjadi suami mereka), dan tidak pula oleh jin.'),
  ('id.indonesian', 55, 75, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 76, 'Mereka bertelekan pada bantal-bantal yang hijau dan permadani-permadani yang indah.'),
  ('id.indonesian', 55, 77, 'Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?'),
  ('id.indonesian', 55, 78, 'Maha Agung nama Tuhanmu Yang Mempunyai Kebesaran dan Karunia.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (53, 17, 4801, 'مَا زَاغَ ٱلْبَصَرُ وَمَا طَغَىٰ', 526, 27, 210, 0),
  (53, 18, 4802, 'لَقَدْ رَأَىٰ مِنْ ءَايَٰتِ رَبِّهِ ٱلْكُبْرَىٰٓ', 526, 27, 210, 0),
  (53, 19, 4803, 'أَفَرَءَيْتُمُ ٱللَّٰتَ وَٱلْعُزَّىٰ', 526, 27, 210, 0),
  (53, 20, 4804, 'وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلْأُخْرَىٰٓ', 526, 27, 210, 0),
  (53, 21, 4805, 'أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلْأُنثَىٰ', 526, 27, 210, 0),
  (53, 22, 4806, 'تِلْكَ إِذًۭا قِسْمَةٌۭ ضِيزَىٰٓ', 526, 27, 210, 0),
  (53, 23, 4807, 'إِنْ هِىَ إِلَّآ أَسْمَآءٌۭ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهْوَى ٱلْأَنفُسُ ۖ وَلَقَدْ جَآءَهُم مِّن رَّبِّهِمُ ٱلْهُدَىٰٓ', 526, 27, 210, 0),
  (53, 24, 4808, 'أَمْ لِلْإِنسَٰنِ مَا تَمَنَّىٰ', 526, 27, 210, 0),
  (53, 25, 4809, 'فَلِلَّهِ ٱلْءَاخِرَةُ وَٱلْأُولَىٰ', 526, 27, 210, 0),
  (53, 26, 4810, '۞ وَكَم مِّن مَّلَكٍۢ فِى ٱلسَّمَٰوَٰتِ لَا تُغْنِى شَفَٰعَتُهُمْ شَيْـًٔا إِلَّا مِنۢ بَعْدِ أَن يَأْذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرْضَىٰٓ', 526, 27, 211, 0),
  (53, 27, 4811, 'إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْءَاخِرَةِ لَيُسَمُّونَ ٱلْمَلَٰٓئِكَةَ تَسْمِيَةَ ٱلْأُنثَىٰ', 527, 27, 211, 0),
  (53, 28, 4812, 'وَمَا لَهُم بِهِۦ مِنْ عِلْمٍ ۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ ۖ وَإِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًۭٔا', 527, 27, 211, 0),
  (53, 29, 4813, 'فَأَعْرِضْ عَن مَّن تَوَلَّىٰ عَن ذِكْرِنَا وَلَمْ يُرِدْ إِلَّا ٱلْحَيَوٰةَ ٱلدُّنْيَا', 527, 27, 211, 0),
  (53, 30, 4814, 'ذَٰلِكَ مَبْلَغُهُم مِّنَ ٱلْعِلْمِ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِمَنِ ٱهْتَدَىٰ', 527, 27, 211, 0),
  (53, 31, 4815, 'وَلِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ لِيَجْزِىَ ٱلَّذِينَ أَسَٰٓـُٔوا۟ بِمَا عَمِلُوا۟ وَيَجْزِىَ ٱلَّذِينَ أَحْسَنُوا۟ بِٱلْحُسْنَى', 527, 27, 211, 0),
  (53, 32, 4816, 'ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ ۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ ۚ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌۭ فِى بُطُونِ أُمَّهَٰتِكُمْ ۖ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ', 527, 27, 211, 0),
  (53, 33, 4817, 'أَفَرَءَيْتَ ٱلَّذِى تَوَلَّىٰ', 527, 27, 211, 0),
  (53, 34, 4818, 'وَأَعْطَىٰ قَلِيلًۭا وَأَكْدَىٰٓ', 527, 27, 211, 0),
  (53, 35, 4819, 'أَعِندَهُۥ عِلْمُ ٱلْغَيْبِ فَهُوَ يَرَىٰٓ', 527, 27, 211, 0),
  (53, 36, 4820, 'أَمْ لَمْ يُنَبَّأْ بِمَا فِى صُحُفِ مُوسَىٰ', 527, 27, 211, 0),
  (53, 37, 4821, 'وَإِبْرَٰهِيمَ ٱلَّذِى وَفَّىٰٓ', 527, 27, 211, 0),
  (53, 38, 4822, 'أَلَّا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ', 527, 27, 211, 0),
  (53, 39, 4823, 'وَأَن لَّيْسَ لِلْإِنسَٰنِ إِلَّا مَا سَعَىٰ', 527, 27, 211, 0),
  (53, 40, 4824, 'وَأَنَّ سَعْيَهُۥ سَوْفَ يُرَىٰ', 527, 27, 211, 0),
  (53, 41, 4825, 'ثُمَّ يُجْزَىٰهُ ٱلْجَزَآءَ ٱلْأَوْفَىٰ', 527, 27, 211, 0),
  (53, 42, 4826, 'وَأَنَّ إِلَىٰ رَبِّكَ ٱلْمُنتَهَىٰ', 527, 27, 211, 0),
  (53, 43, 4827, 'وَأَنَّهُۥ هُوَ أَضْحَكَ وَأَبْكَىٰ', 527, 27, 211, 0),
  (53, 44, 4828, 'وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحْيَا', 527, 27, 211, 0),
  (53, 45, 4829, 'وَأَنَّهُۥ خَلَقَ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰ', 528, 27, 211, 0),
  (53, 46, 4830, 'مِن نُّطْفَةٍ إِذَا تُمْنَىٰ', 528, 27, 211, 0),
  (53, 47, 4831, 'وَأَنَّ عَلَيْهِ ٱلنَّشْأَةَ ٱلْأُخْرَىٰ', 528, 27, 211, 0),
  (53, 48, 4832, 'وَأَنَّهُۥ هُوَ أَغْنَىٰ وَأَقْنَىٰ', 528, 27, 211, 0),
  (53, 49, 4833, 'وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعْرَىٰ', 528, 27, 211, 0),
  (53, 50, 4834, 'وَأَنَّهُۥٓ أَهْلَكَ عَادًا ٱلْأُولَىٰ', 528, 27, 211, 0),
  (53, 51, 4835, 'وَثَمُودَا۟ فَمَآ أَبْقَىٰ', 528, 27, 211, 0),
  (53, 52, 4836, 'وَقَوْمَ نُوحٍۢ مِّن قَبْلُ ۖ إِنَّهُمْ كَانُوا۟ هُمْ أَظْلَمَ وَأَطْغَىٰ', 528, 27, 211, 0),
  (53, 53, 4837, 'وَٱلْمُؤْتَفِكَةَ أَهْوَىٰ', 528, 27, 211, 0),
  (53, 54, 4838, 'فَغَشَّىٰهَا مَا غَشَّىٰ', 528, 27, 211, 0),
  (53, 55, 4839, 'فَبِأَىِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ', 528, 27, 211, 0),
  (53, 56, 4840, 'هَٰذَا نَذِيرٌۭ مِّنَ ٱلنُّذُرِ ٱلْأُولَىٰٓ', 528, 27, 211, 0),
  (53, 57, 4841, 'أَزِفَتِ ٱلْءَازِفَةُ', 528, 27, 211, 0),
  (53, 58, 4842, 'لَيْسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ', 528, 27, 211, 0),
  (53, 59, 4843, 'أَفَمِنْ هَٰذَا ٱلْحَدِيثِ تَعْجَبُونَ', 528, 27, 211, 0),
  (53, 60, 4844, 'وَتَضْحَكُونَ وَلَا تَبْكُونَ', 528, 27, 211, 0),
  (53, 61, 4845, 'وَأَنتُمْ سَٰمِدُونَ', 528, 27, 211, 0),
  (53, 62, 4846, 'فَٱسْجُدُوا۟ لِلَّهِ وَٱعْبُدُوا۟ ۩', 528, 27, 211, 1),
  (54, 1, 4847, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ', 528, 27, 211, 0),
  (54, 2, 4848, 'وَإِن يَرَوْا۟ ءَايَةًۭ يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌۭ مُّسْتَمِرٌّۭ', 528, 27, 211, 0),
  (54, 3, 4849, 'وَكَذَّبُوا۟ وَٱتَّبَعُوٓا۟ أَهْوَآءَهُمْ ۚ وَكُلُّ أَمْرٍۢ مُّسْتَقِرٌّۭ', 528, 27, 211, 0),
  (54, 4, 4850, 'وَلَقَدْ جَآءَهُم مِّنَ ٱلْأَنۢبَآءِ مَا فِيهِ مُزْدَجَرٌ', 528, 27, 211, 0),
  (54, 5, 4851, 'حِكْمَةٌۢ بَٰلِغَةٌۭ ۖ فَمَا تُغْنِ ٱلنُّذُرُ', 528, 27, 211, 0),
  (54, 6, 4852, 'فَتَوَلَّ عَنْهُمْ ۘ يَوْمَ يَدْعُ ٱلدَّاعِ إِلَىٰ شَىْءٍۢ نُّكُرٍ', 528, 27, 211, 0),
  (54, 7, 4853, 'خُشَّعًا أَبْصَٰرُهُمْ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌۭ مُّنتَشِرٌۭ', 529, 27, 211, 0),
  (54, 8, 4854, 'مُّهْطِعِينَ إِلَى ٱلدَّاعِ ۖ يَقُولُ ٱلْكَٰفِرُونَ هَٰذَا يَوْمٌ عَسِرٌۭ', 529, 27, 211, 0),
  (54, 9, 4855, '۞ كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍۢ فَكَذَّبُوا۟ عَبْدَنَا وَقَالُوا۟ مَجْنُونٌۭ وَٱزْدُجِرَ', 529, 27, 212, 0),
  (54, 10, 4856, 'فَدَعَا رَبَّهُۥٓ أَنِّى مَغْلُوبٌۭ فَٱنتَصِرْ', 529, 27, 212, 0),
  (54, 11, 4857, 'فَفَتَحْنَآ أَبْوَٰبَ ٱلسَّمَآءِ بِمَآءٍۢ مُّنْهَمِرٍۢ', 529, 27, 212, 0),
  (54, 12, 4858, 'وَفَجَّرْنَا ٱلْأَرْضَ عُيُونًۭا فَٱلْتَقَى ٱلْمَآءُ عَلَىٰٓ أَمْرٍۢ قَدْ قُدِرَ', 529, 27, 212, 0),
  (54, 13, 4859, 'وَحَمَلْنَٰهُ عَلَىٰ ذَاتِ أَلْوَٰحٍۢ وَدُسُرٍۢ', 529, 27, 212, 0),
  (54, 14, 4860, 'تَجْرِى بِأَعْيُنِنَا جَزَآءًۭ لِّمَن كَانَ كُفِرَ', 529, 27, 212, 0),
  (54, 15, 4861, 'وَلَقَد تَّرَكْنَٰهَآ ءَايَةًۭ فَهَلْ مِن مُّدَّكِرٍۢ', 529, 27, 212, 0),
  (54, 16, 4862, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 529, 27, 212, 0),
  (54, 17, 4863, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 529, 27, 212, 0),
  (54, 18, 4864, 'كَذَّبَتْ عَادٌۭ فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 529, 27, 212, 0),
  (54, 19, 4865, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ رِيحًۭا صَرْصَرًۭا فِى يَوْمِ نَحْسٍۢ مُّسْتَمِرٍّۢ', 529, 27, 212, 0),
  (54, 20, 4866, 'تَنزِعُ ٱلنَّاسَ كَأَنَّهُمْ أَعْجَازُ نَخْلٍۢ مُّنقَعِرٍۢ', 529, 27, 212, 0),
  (54, 21, 4867, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 529, 27, 212, 0),
  (54, 22, 4868, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 529, 27, 212, 0),
  (54, 23, 4869, 'كَذَّبَتْ ثَمُودُ بِٱلنُّذُرِ', 529, 27, 212, 0),
  (54, 24, 4870, 'فَقَالُوٓا۟ أَبَشَرًۭا مِّنَّا وَٰحِدًۭا نَّتَّبِعُهُۥٓ إِنَّآ إِذًۭا لَّفِى ضَلَٰلٍۢ وَسُعُرٍ', 529, 27, 212, 0),
  (54, 25, 4871, 'أَءُلْقِىَ ٱلذِّكْرُ عَلَيْهِ مِنۢ بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌۭ', 529, 27, 212, 0),
  (54, 26, 4872, 'سَيَعْلَمُونَ غَدًۭا مَّنِ ٱلْكَذَّابُ ٱلْأَشِرُ', 529, 27, 212, 0),
  (54, 27, 4873, 'إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةًۭ لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ', 529, 27, 212, 0),
  (54, 28, 4874, 'وَنَبِّئْهُمْ أَنَّ ٱلْمَآءَ قِسْمَةٌۢ بَيْنَهُمْ ۖ كُلُّ شِرْبٍۢ مُّحْتَضَرٌۭ', 530, 27, 212, 0),
  (54, 29, 4875, 'فَنَادَوْا۟ صَاحِبَهُمْ فَتَعَاطَىٰ فَعَقَرَ', 530, 27, 212, 0),
  (54, 30, 4876, 'فَكَيْفَ كَانَ عَذَابِى وَنُذُرِ', 530, 27, 212, 0),
  (54, 31, 4877, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ صَيْحَةًۭ وَٰحِدَةًۭ فَكَانُوا۟ كَهَشِيمِ ٱلْمُحْتَظِرِ', 530, 27, 212, 0),
  (54, 32, 4878, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 530, 27, 212, 0),
  (54, 33, 4879, 'كَذَّبَتْ قَوْمُ لُوطٍۭ بِٱلنُّذُرِ', 530, 27, 212, 0),
  (54, 34, 4880, 'إِنَّآ أَرْسَلْنَا عَلَيْهِمْ حَاصِبًا إِلَّآ ءَالَ لُوطٍۢ ۖ نَّجَّيْنَٰهُم بِسَحَرٍۢ', 530, 27, 212, 0),
  (54, 35, 4881, 'نِّعْمَةًۭ مِّنْ عِندِنَا ۚ كَذَٰلِكَ نَجْزِى مَن شَكَرَ', 530, 27, 212, 0),
  (54, 36, 4882, 'وَلَقَدْ أَنذَرَهُم بَطْشَتَنَا فَتَمَارَوْا۟ بِٱلنُّذُرِ', 530, 27, 212, 0),
  (54, 37, 4883, 'وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 530, 27, 212, 0),
  (54, 38, 4884, 'وَلَقَدْ صَبَّحَهُم بُكْرَةً عَذَابٌۭ مُّسْتَقِرٌّۭ', 530, 27, 212, 0),
  (54, 39, 4885, 'فَذُوقُوا۟ عَذَابِى وَنُذُرِ', 530, 27, 212, 0),
  (54, 40, 4886, 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', 530, 27, 212, 0),
  (54, 41, 4887, 'وَلَقَدْ جَآءَ ءَالَ فِرْعَوْنَ ٱلنُّذُرُ', 530, 27, 212, 0),
  (54, 42, 4888, 'كَذَّبُوا۟ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذْنَٰهُمْ أَخْذَ عَزِيزٍۢ مُّقْتَدِرٍ', 530, 27, 212, 0),
  (54, 43, 4889, 'أَكُفَّارُكُمْ خَيْرٌۭ مِّنْ أُو۟لَٰٓئِكُمْ أَمْ لَكُم بَرَآءَةٌۭ فِى ٱلزُّبُرِ', 530, 27, 212, 0),
  (54, 44, 4890, 'أَمْ يَقُولُونَ نَحْنُ جَمِيعٌۭ مُّنتَصِرٌۭ', 530, 27, 212, 0),
  (54, 45, 4891, 'سَيُهْزَمُ ٱلْجَمْعُ وَيُوَلُّونَ ٱلدُّبُرَ', 530, 27, 212, 0),
  (54, 46, 4892, 'بَلِ ٱلسَّاعَةُ مَوْعِدُهُمْ وَٱلسَّاعَةُ أَدْهَىٰ وَأَمَرُّ', 530, 27, 212, 0),
  (54, 47, 4893, 'إِنَّ ٱلْمُجْرِمِينَ فِى ضَلَٰلٍۢ وَسُعُرٍۢ', 530, 27, 212, 0),
  (54, 48, 4894, 'يَوْمَ يُسْحَبُونَ فِى ٱلنَّارِ عَلَىٰ وُجُوهِهِمْ ذُوقُوا۟ مَسَّ سَقَرَ', 530, 27, 212, 0),
  (54, 49, 4895, 'إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍۢ', 530, 27, 212, 0),
  (54, 50, 4896, 'وَمَآ أَمْرُنَآ إِلَّا وَٰحِدَةٌۭ كَلَمْحٍۭ بِٱلْبَصَرِ', 531, 27, 212, 0),
  (54, 51, 4897, 'وَلَقَدْ أَهْلَكْنَآ أَشْيَاعَكُمْ فَهَلْ مِن مُّدَّكِرٍۢ', 531, 27, 212, 0),
  (54, 52, 4898, 'وَكُلُّ شَىْءٍۢ فَعَلُوهُ فِى ٱلزُّبُرِ', 531, 27, 212, 0),
  (54, 53, 4899, 'وَكُلُّ صَغِيرٍۢ وَكَبِيرٍۢ مُّسْتَطَرٌ', 531, 27, 212, 0),
  (54, 54, 4900, 'إِنَّ ٱلْمُتَّقِينَ فِى جَنَّٰتٍۢ وَنَهَرٍۢ', 531, 27, 212, 0),
  (54, 55, 4901, 'فِى مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍۢ مُّقْتَدِرٍۭ', 531, 27, 212, 0),
  (55, 1, 4902, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلرَّحْمَٰنُ', 531, 27, 213, 0),
  (55, 2, 4903, 'عَلَّمَ ٱلْقُرْءَانَ', 531, 27, 213, 0),
