  (55, 12, 4913, 'وَٱلْحَبُّ ذُو ٱلْعَصْفِ وَٱلرَّيْحَانُ', 531, 27, 213, 0),
  (55, 13, 4914, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 531, 27, 213, 0),
  (55, 14, 4915, 'خَلَقَ ٱلْإِنسَٰنَ مِن صَلْصَٰلٍۢ كَٱلْفَخَّارِ', 531, 27, 213, 0),
  (55, 15, 4916, 'وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍۢ مِّن نَّارٍۢ', 531, 27, 213, 0),
  (55, 16, 4917, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 531, 27, 213, 0),
  (55, 17, 4918, 'رَبُّ ٱلْمَشْرِقَيْنِ وَرَبُّ ٱلْمَغْرِبَيْنِ', 532, 27, 213, 0),
  (55, 18, 4919, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 19, 4920, 'مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ', 532, 27, 213, 0),
  (55, 20, 4921, 'بَيْنَهُمَا بَرْزَخٌۭ لَّا يَبْغِيَانِ', 532, 27, 213, 0),
  (55, 21, 4922, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 22, 4923, 'يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ', 532, 27, 213, 0),
  (55, 23, 4924, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 24, 4925, 'وَلَهُ ٱلْجَوَارِ ٱلْمُنشَـَٔاتُ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ', 532, 27, 213, 0),
  (55, 25, 4926, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 26, 4927, 'كُلُّ مَنْ عَلَيْهَا فَانٍۢ', 532, 27, 213, 0),
  (55, 27, 4928, 'وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو ٱلْجَلَٰلِ وَٱلْإِكْرَامِ', 532, 27, 213, 0),
  (55, 28, 4929, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 29, 4930, 'يَسْـَٔلُهُۥ مَن فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ', 532, 27, 213, 0),
  (55, 30, 4931, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 31, 4932, 'سَنَفْرُغُ لَكُمْ أَيُّهَ ٱلثَّقَلَانِ', 532, 27, 213, 0),
  (55, 32, 4933, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 33, 4934, 'يَٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ إِنِ ٱسْتَطَعْتُمْ أَن تَنفُذُوا۟ مِنْ أَقْطَارِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ فَٱنفُذُوا۟ ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَٰنٍۢ', 532, 27, 213, 0),
  (55, 34, 4935, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 35, 4936, 'يُرْسَلُ عَلَيْكُمَا شُوَاظٌۭ مِّن نَّارٍۢ وَنُحَاسٌۭ فَلَا تَنتَصِرَانِ', 532, 27, 213, 0),
  (55, 36, 4937, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 532, 27, 213, 0),
  (55, 37, 4938, 'فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتْ وَرْدَةًۭ كَٱلدِّهَانِ', 532, 27, 213, 0),
