  (55, 68, 4969, 'فِيهِمَا فَٰكِهَةٌۭ وَنَخْلٌۭ وَرُمَّانٌۭ', 534, 27, 213, 0),
  (55, 69, 4970, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 534, 27, 213, 0),
  (55, 70, 4971, 'فِيهِنَّ خَيْرَٰتٌ حِسَانٌۭ', 534, 27, 213, 0),
  (55, 71, 4972, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 534, 27, 213, 0),
  (55, 72, 4973, 'حُورٌۭ مَّقْصُورَٰتٌۭ فِى ٱلْخِيَامِ', 534, 27, 213, 0),
  (55, 73, 4974, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 534, 27, 213, 0),
  (55, 74, 4975, 'لَمْ يَطْمِثْهُنَّ إِنسٌۭ قَبْلَهُمْ وَلَا جَآنٌّۭ', 534, 27, 213, 0),
  (55, 75, 4976, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 534, 27, 213, 0),
  (55, 76, 4977, 'مُتَّكِـِٔينَ عَلَىٰ رَفْرَفٍ خُضْرٍۢ وَعَبْقَرِىٍّ حِسَانٍۢ', 534, 27, 213, 0),
  (55, 77, 4978, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 534, 27, 213, 0),
  (55, 78, 4979, 'تَبَٰرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَٰلِ وَٱلْإِكْرَامِ', 534, 27, 213, 0),
  (56, 1, 4980, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا وَقَعَتِ ٱلْوَاقِعَةُ', 534, 27, 214, 0),
  (56, 2, 4981, 'لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ', 534, 27, 214, 0),
  (56, 3, 4982, 'خَافِضَةٌۭ رَّافِعَةٌ', 534, 27, 214, 0),
  (56, 4, 4983, 'إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّۭا', 534, 27, 214, 0),
  (56, 5, 4984, 'وَبُسَّتِ ٱلْجِبَالُ بَسًّۭا', 534, 27, 214, 0),
  (56, 6, 4985, 'فَكَانَتْ هَبَآءًۭ مُّنۢبَثًّۭا', 534, 27, 214, 0),
  (56, 7, 4986, 'وَكُنتُمْ أَزْوَٰجًۭا ثَلَٰثَةًۭ', 534, 27, 214, 0),
  (56, 8, 4987, 'فَأَصْحَٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَٰبُ ٱلْمَيْمَنَةِ', 534, 27, 214, 0),
  (56, 9, 4988, 'وَأَصْحَٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ', 534, 27, 214, 0),
  (56, 10, 4989, 'وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ', 534, 27, 214, 0),
  (56, 11, 4990, 'أُو۟لَٰٓئِكَ ٱلْمُقَرَّبُونَ', 534, 27, 214, 0),
  (56, 12, 4991, 'فِى جَنَّٰتِ ٱلنَّعِيمِ', 534, 27, 214, 0),
  (56, 13, 4992, 'ثُلَّةٌۭ مِّنَ ٱلْأَوَّلِينَ', 534, 27, 214, 0),
  (56, 14, 4993, 'وَقَلِيلٌۭ مِّنَ ٱلْءَاخِرِينَ', 534, 27, 214, 0),
  (56, 15, 4994, 'عَلَىٰ سُرُرٍۢ مَّوْضُونَةٍۢ', 534, 27, 214, 0),
  (56, 16, 4995, 'مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَٰبِلِينَ', 534, 27, 214, 0),
  (56, 17, 4996, 'يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌۭ مُّخَلَّدُونَ', 535, 27, 214, 0),
  (56, 18, 4997, 'بِأَكْوَابٍۢ وَأَبَارِيقَ وَكَأْسٍۢ مِّن مَّعِينٍۢ', 535, 27, 214, 0),
  (56, 19, 4998, 'لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ', 535, 27, 214, 0),
  (56, 20, 4999, 'وَفَٰكِهَةٍۢ مِّمَّا يَتَخَيَّرُونَ', 535, 27, 214, 0),
  (56, 21, 5000, 'وَلَحْمِ طَيْرٍۢ مِّمَّا يَشْتَهُونَ', 535, 27, 214, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 56, 1, 'When the Occurrence occurs,'),
  ('en.sahih', 56, 2, 'There is, at its occurrence, no denial.'),
  ('en.sahih', 56, 3, 'It will bring down [some] and raise up [others].'),
  ('en.sahih', 56, 4, 'When the earth is shaken with convulsion'),
  ('en.sahih', 56, 5, 'And the mountains are broken down, crumbling'),
  ('en.sahih', 56, 6, 'And become dust dispersing.'),
  ('en.sahih', 56, 7, 'And you become [of] three kinds:'),
  ('en.sahih', 56, 8, 'Then the companions of the right - what are the companions of the right?'),
  ('en.sahih', 56, 9, 'And the companions of the left - what are the companions of the left?'),
  ('en.sahih', 56, 10, 'And the forerunners, the forerunners -'),
  ('en.sahih', 56, 11, 'Those are the ones brought near [to Allah]'),
  ('en.sahih', 56, 12, 'In the Gardens of Pleasure,'),
  ('en.sahih', 56, 13, 'A [large] company of the former peoples'),
  ('en.sahih', 56, 14, 'And a few of the later peoples,'),
  ('en.sahih', 56, 15, 'On thrones woven [with ornament],'),
  ('en.sahih', 56, 16, 'Reclining on them, facing each other.'),
  ('en.sahih', 56, 17, 'There will circulate among them young boys made eternal'),
  ('en.sahih', 56, 18, 'With vessels, pitchers and a cup [of wine] from a flowing spring -'),
  ('en.sahih', 56, 19, 'No headache will they have therefrom, nor will they be intoxicated -'),
  ('en.sahih', 56, 20, 'And fruit of what they select'),
  ('en.sahih', 56, 21, 'And the meat of fowl, from whatever they desire.'),
  ('en.sahih', 56, 22, 'And [for them are] fair women with large, [beautiful] eyes,'),
  ('en.sahih', 56, 23, 'The likenesses of pearls well-protected,'),
  ('en.sahih', 56, 24, 'As reward for what they used to do.'),
  ('en.sahih', 56, 25, 'They will not hear therein ill speech or commission of sin -'),
  ('en.sahih', 56, 26, 'Only a saying: "Peace, peace."'),
  ('en.sahih', 56, 27, 'The companions of the right - what are the companions of the right?'),
  ('en.sahih', 56, 28, '[They will be] among lote trees with thorns removed'),
  ('en.sahih', 56, 29, 'And [banana] trees layered [with fruit]'),
  ('en.sahih', 56, 30, 'And shade extended'),
  ('en.sahih', 56, 31, 'And water poured out'),
  ('en.sahih', 56, 32, 'And fruit, abundant [and varied],'),
  ('en.sahih', 56, 33, 'Neither limited [to season] nor forbidden,'),
  ('en.sahih', 56, 34, 'And [upon] beds raised high.'),
  ('en.sahih', 56, 35, 'Indeed, We have produced the women of Paradise in a [new] creation'),
  ('en.sahih', 56, 36, 'And made them virgins,'),
  ('en.sahih', 56, 37, 'Devoted [to their husbands] and of equal age,'),
  ('en.sahih', 56, 38, 'For the companions of the right [who are]'),
  ('en.sahih', 56, 39, 'A company of the former peoples'),
  ('en.sahih', 56, 40, 'And a company of the later peoples.'),
  ('en.sahih', 56, 41, 'And the companions of the left - what are the companions of the left?'),
  ('en.sahih', 56, 42, '[They will be] in scorching fire and scalding water'),
  ('en.sahih', 56, 43, 'And a shade of black smoke,'),
  ('en.sahih', 56, 44, 'Neither cool nor beneficial.'),
  ('en.sahih', 56, 45, 'Indeed they were, before that, indulging in affluence,'),
  ('en.sahih', 56, 46, 'And they used to persist in the great violation,'),
  ('en.sahih', 56, 47, 'And they used to say, "When we die and become dust and bones, are we indeed to be resurrected?'),
  ('en.sahih', 56, 48, 'And our forefathers [as well]?"'),
  ('en.sahih', 56, 49, 'Say, [O Muhammad], "Indeed, the former and the later peoples'),
  ('en.sahih', 56, 50, 'Are to be gathered together for the appointment of a known Day."'),
  ('en.sahih', 56, 51, 'Then indeed you, O those astray [who are] deniers,'),
  ('en.sahih', 56, 52, 'Will be eating from trees of zaqqum'),
  ('en.sahih', 56, 53, 'And filling with it your bellies'),
  ('en.sahih', 56, 54, 'And drinking on top of it from scalding water'),
  ('en.sahih', 56, 55, 'And will drink as the drinking of thirsty camels.'),
  ('en.sahih', 56, 56, 'That is their accommodation on the Day of Recompense.'),
  ('en.sahih', 56, 57, 'We have created you, so why do you not believe?'),
  ('en.sahih', 56, 58, 'Have you seen that which you emit?'),
  ('en.sahih', 56, 59, 'Is it you who creates it, or are We the Creator?'),
  ('en.sahih', 56, 60, 'We have decreed death among you, and We are not to be outdone'),
  ('en.sahih', 56, 61, 'In that We will change your likenesses and produce you in that [form] which you do not know.'),
  ('en.sahih', 56, 62, 'And you have already known the first creation, so will you not remember?'),
  ('en.sahih', 56, 63, 'And have you seen that [seed] which you sow?'),
  ('en.sahih', 56, 64, 'Is it you who makes it grow, or are We the grower?'),
  ('en.sahih', 56, 65, 'If We willed, We could make it [dry] debris, and you would remain in wonder,'),
  ('en.sahih', 56, 66, '[Saying], "Indeed, we are [now] in debt;'),
  ('en.sahih', 56, 67, 'Rather, we have been deprived."'),
  ('en.sahih', 56, 68, 'And have you seen the water that you drink?'),
  ('en.sahih', 56, 69, 'Is it you who brought it down from the clouds, or is it We who bring it down?'),
  ('en.sahih', 56, 70, 'If We willed, We could make it bitter, so why are you not grateful?'),
  ('en.sahih', 56, 71, 'And have you seen the fire that you ignite?'),
  ('en.sahih', 56, 72, 'Is it you who produced its tree, or are We the producer?'),
  ('en.sahih', 56, 73, 'We have made it a reminder and provision for the travelers,'),
  ('en.sahih', 56, 74, 'So exalt the name of your Lord, the Most Great.'),
  ('en.sahih', 56, 75, 'Then I swear by the setting of the stars,'),
  ('en.sahih', 56, 76, 'And indeed, it is an oath - if you could know - [most] great.'),
  ('en.sahih', 56, 77, 'Indeed, it is a noble Qur\'an'),
  ('en.sahih', 56, 78, 'In a Register well-protected;'),
  ('en.sahih', 56, 79, 'None touch it except the purified.'),
  ('en.sahih', 56, 80, '[It is] a revelation from the Lord of the worlds.'),
  ('en.sahih', 56, 81, 'Then is it to this statement that you are indifferent'),
  ('en.sahih', 56, 82, 'And make [the thanks for] your provision that you deny [the Provider]?'),
  ('en.sahih', 56, 83, 'Then why, when the soul at death reaches the throat'),
  ('en.sahih', 56, 84, 'And you are at that time looking on -'),
  ('en.sahih', 56, 85, 'And Our angels are nearer to him than you, but you do not see -'),
  ('en.sahih', 56, 86, 'Then why do you not, if you are not to be recompensed,'),
  ('en.sahih', 56, 87, 'Bring it back, if you should be truthful?'),
  ('en.sahih', 56, 88, 'And if the deceased was of those brought near to Allah,'),
  ('en.sahih', 56, 89, 'Then [for him is] rest and bounty and a garden of pleasure.'),
  ('en.sahih', 56, 90, 'And if he was of the companions of the right,'),
  ('en.sahih', 56, 91, 'Then [the angels will say], "Peace for you; [you are] from the companions of the right."'),
  ('en.sahih', 56, 92, 'But if he was of the deniers [who were] astray,'),
  ('en.sahih', 56, 93, 'Then [for him is] accommodation of scalding water'),
  ('en.sahih', 56, 94, 'And burning in Hellfire'),
  ('en.sahih', 56, 95, 'Indeed, this is the true certainty,'),
  ('en.sahih', 56, 96, 'So exalt the name of your Lord, the Most Great.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 56, 1, 'যখন কিয়ামতের ঘটনা ঘটবে,'),
  ('bn.bengali', 56, 2, 'যার বাস্তবতায় কোন সংশয় নেই।'),
  ('bn.bengali', 56, 3, 'এটা নীচু করে দেবে, সমুন্নত করে দেবে।'),
  ('bn.bengali', 56, 4, 'যখন প্রবলভাবে প্রকম্পিত হবে পৃথিবী।'),
  ('bn.bengali', 56, 5, 'এবং পর্বতমালা ভেঙ্গে চুরমার হয়ে যাবে।'),
  ('bn.bengali', 56, 6, 'অতঃপর তা হয়ে যাবে উৎক্ষিপ্ত ধূলিকণা।'),
  ('bn.bengali', 56, 7, 'এবং তোমরা তিনভাবে বিভক্ত হয়ে পড়বে।'),
  ('bn.bengali', 56, 8, 'যারা ডান দিকে, কত ভাগ্যবান তারা।'),
  ('bn.bengali', 56, 9, 'এবং যারা বামদিকে, কত হতভাগা তারা।'),
  ('bn.bengali', 56, 10, 'অগ্রবর্তীগণ তো অগ্রবর্তীই।'),
  ('bn.bengali', 56, 11, 'তারাই নৈকট্যশীল,'),
  ('bn.bengali', 56, 12, 'অবদানের উদ্যানসমূহে,'),
  ('bn.bengali', 56, 13, 'তারা একদল পূর্ববর্তীদের মধ্য থেকে।'),
  ('bn.bengali', 56, 14, 'এবং অল্পসংখ্যক পরবর্তীদের মধ্যে থেকে।'),
  ('bn.bengali', 56, 15, 'স্বর্ণ খচিত সিংহাসন।'),
  ('bn.bengali', 56, 16, 'তারা তাতে হেলান দিয়ে বসবে পরস্পর মুখোমুখি হয়ে।'),
  ('bn.bengali', 56, 17, 'তাদের কাছে ঘোরাফেরা করবে চির কিশোরেরা।'),
  ('bn.bengali', 56, 18, 'পানপাত্র কুঁজা ও খাঁটি সূরাপূর্ণ পেয়ালা হাতে নিয়ে,'),
  ('bn.bengali', 56, 19, 'যা পান করলে তাদের শিরঃপীড়া হবে না এবং বিকারগ্রস্ত ও হবে না।'),
  ('bn.bengali', 56, 20, 'আর তাদের পছন্দমত ফল-মুল নিয়ে,'),
  ('bn.bengali', 56, 21, 'এবং রুচিমত পাখীর মাংস নিয়ে।'),
  ('bn.bengali', 56, 22, 'তথায় থাকবে আনতনয়না হুরগণ,'),
  ('bn.bengali', 56, 23, 'আবরণে রক্ষিত মোতির ন্যায়,'),
  ('bn.bengali', 56, 24, 'তারা যা কিছু করত, তার পুরস্কারস্বরূপ।'),
  ('bn.bengali', 56, 25, 'তারা তথায় অবান্তর ও কোন খারাপ কথা শুনবে না।'),
  ('bn.bengali', 56, 26, 'কিন্তু শুনবে সালাম আর সালাম।'),
  ('bn.bengali', 56, 27, 'যারা ডান দিকে থাকবে, তারা কত ভাগ্যবান।'),
  ('bn.bengali', 56, 28, 'তারা থাকবে কাঁটাবিহীন বদরিকা বৃক্ষে।'),
  ('bn.bengali', 56, 29, 'এবং কাঁদি কাঁদি কলায়,'),
  ('bn.bengali', 56, 30, 'এবং দীর্ঘ ছায়ায়।'),
  ('bn.bengali', 56, 31, 'এবং প্রবাহিত পানিতে,'),
  ('bn.bengali', 56, 32, 'ও প্রচুর ফল-মূলে,'),
  ('bn.bengali', 56, 33, 'যা শেষ হবার নয় এবং নিষিদ্ধ ও নয়,'),
  ('bn.bengali', 56, 34, 'আর থাকবে সমুন্নত শয্যায়।'),
  ('bn.bengali', 56, 35, 'আমি জান্নাতী রমণীগণকে বিশেষরূপে সৃষ্টি করেছি।'),
  ('bn.bengali', 56, 36, 'অতঃপর তাদেরকে করেছি চিরকুমারী।'),
  ('bn.bengali', 56, 37, 'কামিনী, সমবয়স্কা।'),
  ('bn.bengali', 56, 38, 'ডান দিকের লোকদের জন্যে।'),
  ('bn.bengali', 56, 39, 'তাদের একদল হবে পূর্ববর্তীদের মধ্য থেকে।'),
  ('bn.bengali', 56, 40, 'এবং একদল পরবর্তীদের মধ্য থেকে।'),
  ('bn.bengali', 56, 41, 'বামপার্শ্বস্থ লোক, কত না হতভাগা তারা।'),
  ('bn.bengali', 56, 42, 'তারা থাকবে প্রখর বাষ্পে এবং উত্তপ্ত পানিতে,'),
  ('bn.bengali', 56, 43, 'এবং ধুম্রকুঞ্জের ছায়ায়।'),
  ('bn.bengali', 56, 44, 'যা শীতল নয় এবং আরামদায়কও নয়।'),
  ('bn.bengali', 56, 45, 'তারা ইতিপূর্বে স্বাচ্ছন্দ্যশীল ছিল।'),
  ('bn.bengali', 56, 46, 'তারা সদাসর্বদা ঘোরতর পাপকর্মে ডুবে থাকত।'),
  ('bn.bengali', 56, 47, 'তারা বলতঃ আমরা যখন মরে অস্থি ও মৃত্তিকায় পরিণত হয়ে যাব, তখনও কি পুনরুত্থিত হব?'),
  ('bn.bengali', 56, 48, 'এবং আমাদের পূর্বপুরুষগণও!'),
  ('bn.bengali', 56, 49, 'বলুনঃ পূর্ববর্তী ও পরবর্তীগণ,'),
  ('bn.bengali', 56, 50, 'সবাই একত্রিত হবে এক নির্দিষ্ট দিনের নির্দিষ্ট সময়ে।'),
  ('bn.bengali', 56, 51, 'অতঃপর হে পথভ্রষ্ট, মিথ্যারোপকারীগণ।'),
  ('bn.bengali', 56, 52, 'তোমরা অবশ্যই ভক্ষণ করবে যাক্কুম বৃক্ষ থেকে,'),
  ('bn.bengali', 56, 53, 'অতঃপর তা দ্বারা উদর পূর্ণ করবে,'),
  ('bn.bengali', 56, 54, 'অতঃপর তার উপর পান করবে উত্তপ্ত পানি।'),
  ('bn.bengali', 56, 55, 'পান করবে পিপাসিত উটের ন্যায়।'),
  ('bn.bengali', 56, 56, 'কেয়ামতের দিন এটাই হবে তাদের আপ্যায়ন।'),
  ('bn.bengali', 56, 57, 'আমি সৃষ্টি করেছি তোমাদেরকে। অতঃপর কেন তোমরা তা সত্য বলে বিশ্বাস কর না।'),
  ('bn.bengali', 56, 58, 'তোমরা কি ভেবে দেখেছ, তোমাদের বীর্যপাত সম্পর্কে।'),
  ('bn.bengali', 56, 59, 'তোমরা তাকে সৃষ্টি কর, না আমি সৃষ্টি করি?'),
  ('bn.bengali', 56, 60, 'আমি তোমাদের মৃত্যুকাল নির্ধারিত করেছি এবং আমি অক্ষম নই।'),
  ('bn.bengali', 56, 61, 'এ ব্যাপারে যে, তোমাদের পরিবর্তে তোমাদের মত লোককে নিয়ে আসি এবং তোমাদেরকে এমন করে দেই, যা তোমরা জান না।'),
  ('bn.bengali', 56, 62, 'তোমরা অবগত হয়েছ প্রথম সৃষ্টি সম্পর্কে, তবে তোমরা অনুধাবন কর না কেন?'),
  ('bn.bengali', 56, 63, 'তোমরা যে বীজ বপন কর, সে সম্পর্কে ভেবে দেখেছ কি?'),
  ('bn.bengali', 56, 64, 'তোমরা তাকে উৎপন্ন কর, না আমি উৎপন্নকারী ?'),
  ('bn.bengali', 56, 65, 'আমি ইচ্ছা করলে তাকে খড়কুটা করে দিতে পারি, অতঃপর হয়ে যাবে তোমরা বিস্ময়াবিষ্ট।'),
  ('bn.bengali', 56, 66, 'বলবেঃ আমরা তো ঋণের চাপে পড়ে গেলাম;'),
  ('bn.bengali', 56, 67, 'বরং আমরা হূত সর্বস্ব হয়ে পড়লাম।'),
  ('bn.bengali', 56, 68, 'তোমরা যে পানি পান কর, সে সম্পর্কে ভেবে দেখেছ কি?'),
  ('bn.bengali', 56, 69, 'তোমরা তা মেঘ থেকে নামিয়ে আন, না আমি বর্ষন করি?'),
  ('bn.bengali', 56, 70, 'আমি ইচ্ছা করলে তাকে লোনা করে দিতে পারি, অতঃপর তোমরা কেন কৃতজ্ঞতা প্রকাশ কর না?'),
  ('bn.bengali', 56, 71, 'তোমরা যে অগ্নি প্রজ্জ্বলিত কর, সে সম্পর্কে ভেবে দেখেছ কি?'),
  ('bn.bengali', 56, 72, 'তোমরা কি এর বৃক্ষ সৃষ্টি করেছ, না আমি সৃষ্টি করেছি ?'),
  ('bn.bengali', 56, 73, 'আমি সেই বৃক্ষকে করেছি স্মরণিকা এবং মরুবাসীদের জন্য সামগ্রী।'),
  ('bn.bengali', 56, 74, 'অতএব, আপনি আপনার মহান পালনকর্তার নামে পবিত্রতা ঘোষণা করুন।'),
  ('bn.bengali', 56, 75, 'অতএব, আমি তারকারাজির অস্তাচলের শপথ করছি,'),
  ('bn.bengali', 56, 76, 'নিশ্চয় এটা এক মহা শপথ-যদি তোমরা জানতে।'),
  ('bn.bengali', 56, 77, 'নিশ্চয় এটা সম্মানিত কোরআন,'),
  ('bn.bengali', 56, 78, 'যা আছে এক গোপন কিতাবে,'),
  ('bn.bengali', 56, 79, 'যারা পাক-পবিত্র, তারা ব্যতীত অন্য কেউ একে স্পর্শ করবে না।'),
  ('bn.bengali', 56, 80, 'এটা বিশ্ব-পালনকর্তার পক্ষ থেকে অবতীর্ণ।'),
  ('bn.bengali', 56, 81, 'তবুও কি তোমরা এই বাণীর প্রতি শৈথিল্য পদর্শন করবে?'),
  ('bn.bengali', 56, 82, 'এবং একে মিথ্যা বলাকেই তোমরা তোমাদের ভূমিকায় পরিণত করবে?'),
  ('bn.bengali', 56, 83, 'অতঃপর যখন কারও প্রাণ কন্ঠাগত হয়।'),
  ('bn.bengali', 56, 84, 'এবং তোমরা তাকিয়ে থাক,'),
  ('bn.bengali', 56, 85, 'তখন আমি তোমাদের অপেক্ষা তার অধিক নিকটে থাকি; কিন্তু তোমরা দেখ না।'),
  ('bn.bengali', 56, 86, 'যদি তোমাদের হিসাব-কিতাব না হওয়াই ঠিক হয়,'),
  ('bn.bengali', 56, 87, 'তবে তোমরা এই আত্মাকে ফিরাও না কেন, যদি তোমরা সত্যবাদী হও ?'),
  ('bn.bengali', 56, 88, 'যদি সে নৈকট্যশীলদের একজন হয়;'),
  ('bn.bengali', 56, 89, 'তবে তার জন্যে আছে সুখ, উত্তম রিযিক এবং নেয়ামতে ভরা উদ্যান।'),
  ('bn.bengali', 56, 90, 'আর যদি সে ডান পার্শ্বস্থদের একজন হয়,'),
  ('bn.bengali', 56, 91, 'তবে তাকে বলা হবেঃ তোমার জন্যে ডানপার্শ্বসস্থদের পক্ষ থেকে সালাম।'),
  ('bn.bengali', 56, 92, 'আর যদি সে পথভ্রষ্ট মিথ্যারোপকারীদের একজন হয়,'),
  ('bn.bengali', 56, 93, 'তবে তার আপ্যায়ন হবে উত্তপ্ত পানি দ্বারা।'),
  ('bn.bengali', 56, 94, 'এবং সে নিক্ষিপ্ত হবে অগ্নিতে।'),
  ('bn.bengali', 56, 95, 'এটা ধ্রুব সত্য।'),
  ('bn.bengali', 56, 96, 'অতএব, আপনি আপনার মহান পালনকর্তার নামে পবিত্রতা ঘোষণা করুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 56, 1, 'When the event befalleth -'),
  ('en.pickthall', 56, 2, 'There is no denying that it will befall -'),
  ('en.pickthall', 56, 3, 'Abasing (some), exalting (others);'),
  ('en.pickthall', 56, 4, 'When the earth is shaken with a shock'),
  ('en.pickthall', 56, 5, 'And the hills are ground to powder'),
  ('en.pickthall', 56, 6, 'So that they become a scattered dust,'),
  ('en.pickthall', 56, 7, 'And ye will be three kinds:'),
  ('en.pickthall', 56, 8, '(First) those on the right hand; what of those on the right hand?'),
  ('en.pickthall', 56, 9, 'And (then) those on the left hand; what of those on the left hand?'),
  ('en.pickthall', 56, 10, 'And the foremost in the race, the foremost in the race:'),
  ('en.pickthall', 56, 11, 'Those are they who will be brought nigh'),
  ('en.pickthall', 56, 12, 'In gardens of delight;'),
  ('en.pickthall', 56, 13, 'A multitude of those of old'),
  ('en.pickthall', 56, 14, 'And a few of those of later time.'),
  ('en.pickthall', 56, 15, 'On lined couches,'),
  ('en.pickthall', 56, 16, 'Reclining therein face to face.'),
  ('en.pickthall', 56, 17, 'There wait on them immortal youths'),
  ('en.pickthall', 56, 18, 'With bowls and ewers and a cup from a pure spring'),
  ('en.pickthall', 56, 19, 'Wherefrom they get no aching of the head nor any madness,'),
  ('en.pickthall', 56, 20, 'And fruit that they prefer'),
  ('en.pickthall', 56, 21, 'And flesh of fowls that they desire.'),
  ('en.pickthall', 56, 22, 'And (there are) fair ones with wide, lovely eyes,'),
  ('en.pickthall', 56, 23, 'Like unto hidden pearls,'),
  ('en.pickthall', 56, 24, 'Reward for what they used to do.'),
  ('en.pickthall', 56, 25, 'There hear they no vain speaking nor recrimination'),
  ('en.pickthall', 56, 26, '(Naught) but the saying: Peace, (and again) Peace.'),
  ('en.pickthall', 56, 27, 'And those on the right hand; what of those on the right hand?'),
  ('en.pickthall', 56, 28, 'Among thornless lote-trees'),
  ('en.pickthall', 56, 29, 'And clustered plantains,'),
  ('en.pickthall', 56, 30, 'And spreading shade,'),
  ('en.pickthall', 56, 31, 'And water gushing,'),
  ('en.pickthall', 56, 32, 'And fruit in plenty'),
  ('en.pickthall', 56, 33, 'Neither out of reach nor yet forbidden,'),
  ('en.pickthall', 56, 34, 'And raised couches;'),
  ('en.pickthall', 56, 35, 'Lo! We have created them a (new) creation'),
  ('en.pickthall', 56, 36, 'And made them virgins,'),
  ('en.pickthall', 56, 37, 'Lovers, friends,'),
  ('en.pickthall', 56, 38, 'For those on the right hand;'),
  ('en.pickthall', 56, 39, 'A multitude of those of old'),
  ('en.pickthall', 56, 40, 'And a multitude of those of later time.'),
  ('en.pickthall', 56, 41, 'And those on the left hand: What of those on the left hand?'),
  ('en.pickthall', 56, 42, 'In scorching wind and scalding water'),
  ('en.pickthall', 56, 43, 'And shadow of black smoke,'),
  ('en.pickthall', 56, 44, 'Neither cool nor refreshing.'),
  ('en.pickthall', 56, 45, 'Lo! heretofore they were effete with luxury'),
  ('en.pickthall', 56, 46, 'And used to persist in the awful sin.'),
  ('en.pickthall', 56, 47, 'And they used to say: When we are dead and have become dust and bones, shall we then, forsooth, be raised again,'),
  ('en.pickthall', 56, 48, 'And also our forefathers?'),
  ('en.pickthall', 56, 49, 'Say (unto them, O Muhammad): Lo! those of old and those of later time'),
  ('en.pickthall', 56, 50, 'Will all be brought together to the tryst of an appointed day.'),
  ('en.pickthall', 56, 51, 'Then lo! ye, the erring, the deniers,'),
  ('en.pickthall', 56, 52, 'Ye verily will eat of a tree called Zaqqum'),
  ('en.pickthall', 56, 53, 'And will fill your bellies therewith;'),
  ('en.pickthall', 56, 54, 'And thereon ye will drink of boiling water,'),
  ('en.pickthall', 56, 55, 'Drinking even as the camel drinketh.'),
  ('en.pickthall', 56, 56, 'This will be their welcome on the Day of Judgment.'),
  ('en.pickthall', 56, 57, 'We created you. Will ye then admit the truth?'),
  ('en.pickthall', 56, 58, 'Have ye seen that which ye emit?'),
  ('en.pickthall', 56, 59, 'Do ye create it or are We the Creator?'),
  ('en.pickthall', 56, 60, 'We mete out death among you, and We are not to be outrun,'),
  ('en.pickthall', 56, 61, 'That We may transfigure you and make you what ye know not.'),
  ('en.pickthall', 56, 62, 'And verily ye know the first creation. Why, then, do ye not reflect?'),
  ('en.pickthall', 56, 63, 'Have ye seen that which ye cultivate?'),
  ('en.pickthall', 56, 64, 'Is it ye who foster it, or are We the Fosterer?'),
  ('en.pickthall', 56, 65, 'If We willed, We verily could make it chaff, then would ye cease not to exclaim:'),
  ('en.pickthall', 56, 66, 'Lo! we are laden with debt!'),
  ('en.pickthall', 56, 67, 'Nay, but we are deprived!'),
  ('en.pickthall', 56, 68, 'Have ye observed the water which ye drink?'),
  ('en.pickthall', 56, 69, 'Is it ye who shed it from the raincloud, or are We the Shedder?'),
  ('en.pickthall', 56, 70, 'If We willed We verily could make it bitter. Why then, give ye not thanks?'),
  ('en.pickthall', 56, 71, 'Have ye observed the fire which ye strike out;'),
  ('en.pickthall', 56, 72, 'Was it ye who made the tree thereof to grow, or were We the grower?'),
  ('en.pickthall', 56, 73, 'We, even We, appointed it a memorial and a comfort for the dwellers in the wilderness.'),
  ('en.pickthall', 56, 74, 'Therefor (O Muhammad), praise the name of thy Lord, the Tremendous.'),
  ('en.pickthall', 56, 75, 'Nay, I swear by the places of the stars -'),
  ('en.pickthall', 56, 76, 'And lo! that verily is a tremendous oath, if ye but knew -'),
  ('en.pickthall', 56, 77, 'That (this) is indeed a noble Qur\'an'),
  ('en.pickthall', 56, 78, 'In a Book kept hidden'),
  ('en.pickthall', 56, 79, 'Which none toucheth save the purified,'),
  ('en.pickthall', 56, 80, 'A revelation from the Lord of the Worlds.'),
  ('en.pickthall', 56, 81, 'Is it this Statement that ye scorn,'),
  ('en.pickthall', 56, 82, 'And make denial thereof your livelihood?'),
  ('en.pickthall', 56, 83, 'Why, then, when (the soul) cometh up to the throat (of the dying)'),
  ('en.pickthall', 56, 84, 'And ye are at that moment looking'),
  ('en.pickthall', 56, 85, '- And We are nearer unto him than ye are, but ye see not -'),
  ('en.pickthall', 56, 86, 'Why then, if ye are not in bondage (unto Us),'),
  ('en.pickthall', 56, 87, 'Do ye not force it back, if ye are truthful?'),
  ('en.pickthall', 56, 88, 'Thus if he is of those brought nigh,'),
  ('en.pickthall', 56, 89, 'Then breath of life, and plenty, and a Garden of delight.'),
  ('en.pickthall', 56, 90, 'And if he is of those on the right hand,'),
  ('en.pickthall', 56, 91, 'Then (the greeting) "Peace be unto thee" from those on the right hand.'),
  ('en.pickthall', 56, 92, 'But if he is of the rejecters, the erring,'),
  ('en.pickthall', 56, 93, 'Then the welcome will be boiling water'),
  ('en.pickthall', 56, 94, 'And roasting at hell-fire.'),
  ('en.pickthall', 56, 95, 'Lo! this is certain truth.'),
  ('en.pickthall', 56, 96, 'Therefor (O Muhammad) praise the name of thy Lord, the Tremendous.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 56, 1, 'When the Event inevitable cometh to pass,'),
  ('en.yusufali', 56, 2, 'Then will no (soul) entertain falsehood concerning its coming.'),
  ('en.yusufali', 56, 3, '(Many) will it bring low; (many) will it exalt;'),
  ('en.yusufali', 56, 4, 'When the earth shall be shaken to its depths,'),
  ('en.yusufali', 56, 5, 'And the mountains shall be crumbled to atoms,'),
  ('en.yusufali', 56, 6, 'Becoming dust scattered abroad,'),
  ('en.yusufali', 56, 7, 'And ye shall be sorted out into three classes.'),
  ('en.yusufali', 56, 8, 'Then (there will be) the Companions of the Right Hand;- What will be the Companions of the Right Hand?'),
  ('en.yusufali', 56, 9, 'And the Companions of the Left Hand,- what will be the Companions of the Left Hand?'),
  ('en.yusufali', 56, 10, 'And those Foremost (in Faith) will be Foremost (in the Hereafter).'),
  ('en.yusufali', 56, 11, 'These will be those Nearest to Allah:'),
  ('en.yusufali', 56, 12, 'In Gardens of Bliss:'),
  ('en.yusufali', 56, 13, 'A number of people from those of old,'),
  ('en.yusufali', 56, 14, 'And a few from those of later times.'),
  ('en.yusufali', 56, 15, '(They will be) on Thrones encrusted (with gold and precious stones),'),
  ('en.yusufali', 56, 16, 'Reclining on them, facing each other.'),
  ('en.yusufali', 56, 17, 'Round about them will (serve) youths of perpetual (freshness),'),
  ('en.yusufali', 56, 18, 'With goblets, (shining) beakers, and cups (filled) out of clear-flowing fountains:'),
  ('en.yusufali', 56, 19, 'No after-ache will they receive therefrom, nor will they suffer intoxication:'),
  ('en.yusufali', 56, 20, 'And with fruits, any that they may select:'),
  ('en.yusufali', 56, 21, 'And the flesh of fowls, any that they may desire.'),
  ('en.yusufali', 56, 22, 'And (there will be) Companions with beautiful, big, and lustrous eyes,-'),
  ('en.yusufali', 56, 23, 'Like unto Pearls well-guarded.'),
  ('en.yusufali', 56, 24, 'A Reward for the deeds of their past (life).'),
  ('en.yusufali', 56, 25, 'Not frivolity will they hear therein, nor any taint of ill,-'),
  ('en.yusufali', 56, 26, 'Only the saying, "Peace! Peace".'),
  ('en.yusufali', 56, 27, 'The Companions of the Right Hand,- what will be the Companions of the Right Hand?'),
  ('en.yusufali', 56, 28, '(They will be) among Lote-trees without thorns,'),
  ('en.yusufali', 56, 29, 'Among Talh trees with flowers (or fruits) piled one above another,-'),
  ('en.yusufali', 56, 30, 'In shade long-extended,'),
  ('en.yusufali', 56, 31, 'By water flowing constantly,'),
  ('en.yusufali', 56, 32, 'And fruit in abundance.'),
  ('en.yusufali', 56, 33, 'Whose season is not limited, nor (supply) forbidden,'),
  ('en.yusufali', 56, 34, 'And on Thrones (of Dignity), raised high.'),
  ('en.yusufali', 56, 35, 'We have created (their Companions) of special creation.'),
  ('en.yusufali', 56, 36, 'And made them virgin - pure (and undefiled), -'),
  ('en.yusufali', 56, 37, 'Beloved (by nature), equal in age,-'),
  ('en.yusufali', 56, 38, 'For the Companions of the Right Hand.'),
  ('en.yusufali', 56, 39, 'A (goodly) number from those of old,'),
  ('en.yusufali', 56, 40, 'And a (goodly) number from those of later times.'),
  ('en.yusufali', 56, 41, 'The Companions of the Left Hand,- what will be the Companions of the Left Hand?'),
  ('en.yusufali', 56, 42, '(They will be) in the midst of a Fierce Blast of Fire and in Boiling Water,'),
  ('en.yusufali', 56, 43, 'And in the shades of Black Smoke:'),
  ('en.yusufali', 56, 44, 'Nothing (will there be) to refresh, nor to please:'),
  ('en.yusufali', 56, 45, 'For that they were wont to be indulged, before that, in wealth (and luxury),'),
  ('en.yusufali', 56, 46, 'And persisted obstinately in wickedness supreme!'),
  ('en.yusufali', 56, 47, 'And they used to say, "What! when we die and become dust and bones, shall we then indeed be raised up again?-'),
  ('en.yusufali', 56, 48, '"(We) and our fathers of old?"'),
  ('en.yusufali', 56, 49, 'Say: "Yea, those of old and those of later times,'),
  ('en.yusufali', 56, 50, '"All will certainly be gathered together for the meeting appointed for a Day well-known.'),
  ('en.yusufali', 56, 51, '"Then will ye truly,- O ye that go wrong, and treat (Truth) as Falsehood!-'),
  ('en.yusufali', 56, 52, '"Ye will surely taste of the Tree of Zaqqum.'),
  ('en.yusufali', 56, 53, '"Then will ye fill your insides therewith,'),
  ('en.yusufali', 56, 54, '"And drink Boiling Water on top of it:'),
  ('en.yusufali', 56, 55, '"Indeed ye shall drink like diseased camels raging with thirst!"'),
  ('en.yusufali', 56, 56, 'Such will be their entertainment on the Day of Requital!'),
  ('en.yusufali', 56, 57, 'It is We Who have created you: why will ye not witness the Truth?'),
  ('en.yusufali', 56, 58, 'Do ye then see?- The (human Seed) that ye throw out,-'),
  ('en.yusufali', 56, 59, 'Is it ye who create it, or are We the Creators?'),
  ('en.yusufali', 56, 60, 'We have decreed Death to be your common lot, and We are not to be frustrated'),
  ('en.yusufali', 56, 61, 'from changing your Forms and creating you (again) in (forms) that ye know not.'),
  ('en.yusufali', 56, 62, 'And ye certainly know already the first form of creation: why then do ye not celebrate His praises?'),
  ('en.yusufali', 56, 63, 'See ye the seed that ye sow in the ground?'),
  ('en.yusufali', 56, 64, 'Is it ye that cause it to grow, or are We the Cause?'),
  ('en.yusufali', 56, 65, 'Were it Our Will, We could crumble it to dry powder, and ye would be left in wonderment,'),
  ('en.yusufali', 56, 66, '(Saying), "We are indeed left with debts (for nothing):'),
  ('en.yusufali', 56, 67, '"Indeed are we shut out (of the fruits of our labour)"'),
  ('en.yusufali', 56, 68, 'See ye the water which ye drink?'),
  ('en.yusufali', 56, 69, 'Do ye bring it down (in rain) from the cloud or do We?'),
  ('en.yusufali', 56, 70, 'Were it Our Will, We could make it salt (and unpalatable): then why do ye not give thanks?'),
  ('en.yusufali', 56, 71, 'See ye the Fire which ye kindle?'),
  ('en.yusufali', 56, 72, 'Is it ye who grow the tree which feeds the fire, or do We grow it?'),
  ('en.yusufali', 56, 73, 'We have made it a memorial (of Our handiwork), and an article of comfort and convenience for the denizens of deserts.'),
  ('en.yusufali', 56, 74, 'Then celebrate with praises the name of thy Lord, the Supreme!'),
  ('en.yusufali', 56, 75, 'Furthermore I call to witness the setting of the Stars,-'),
  ('en.yusufali', 56, 76, 'And that is indeed a mighty adjuration if ye but knew,-'),
  ('en.yusufali', 56, 77, 'That this is indeed a qur\'an Most Honourable,'),
  ('en.yusufali', 56, 78, 'In Book well-guarded,'),
  ('en.yusufali', 56, 79, 'Which none shall touch but those who are clean:'),
  ('en.yusufali', 56, 80, 'A Revelation from the Lord of the Worlds.'),
  ('en.yusufali', 56, 81, 'Is it such a Message that ye would hold in light esteem?'),
  ('en.yusufali', 56, 82, 'And have ye made it your livelihood that ye should declare it false?'),
  ('en.yusufali', 56, 83, 'Then why do ye not (intervene) when (the soul of the dying man) reaches the throat,-'),
  ('en.yusufali', 56, 84, 'And ye the while (sit) looking on,-'),
  ('en.yusufali', 56, 85, 'But We are nearer to him than ye, and yet see not,-'),
  ('en.yusufali', 56, 86, 'Then why do ye not,- If you are exempt from (future) account,-'),
  ('en.yusufali', 56, 87, 'Call back the soul, if ye are true (in the claim of independence)?'),
  ('en.yusufali', 56, 88, 'Thus, then, if he be of those Nearest to Allah,'),
  ('en.yusufali', 56, 89, '(There is for him) Rest and Satisfaction, and a Garden of Delights.'),
  ('en.yusufali', 56, 90, 'And if he be of the Companions of the Right Hand,'),
  ('en.yusufali', 56, 91, '(For him is the salutation), "Peace be unto thee", from the Companions of the Right Hand.'),
  ('en.yusufali', 56, 92, 'And if he be of those who treat (Truth) as Falsehood, who go wrong,'),
  ('en.yusufali', 56, 93, 'For him is Entertainment with Boiling Water.'),
  ('en.yusufali', 56, 94, 'And burning in Hell-Fire.'),
  ('en.yusufali', 56, 95, 'Verily, this is the Very Truth and Certainly.'),
  ('en.yusufali', 56, 96, 'So celebrate with praises the name of thy Lord, the Supreme.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 56, 1, 'Izaa waqa\'atil waaqi\'ah'),
  ('en.transliteration', 56, 2, 'Laisa liwaq\'atihaa kaazibah'),
  ('en.transliteration', 56, 3, 'Khafidatur raafi\'ah'),
  ('en.transliteration', 56, 4, 'Izaa rujjatil ardu rajjaa'),
  ('en.transliteration', 56, 5, 'Wa bussatil jibaalu bassaa'),
  ('en.transliteration', 56, 6, 'Fakaanat habaaa\'am mumbassaa'),
  ('en.transliteration', 56, 7, 'Wa kuntum azwaajan salaasah'),
  ('en.transliteration', 56, 8, 'Fa as haabul maimanati maaa as haabul maimanah'),
  ('en.transliteration', 56, 9, 'Wa as haabul mash\'amati maaa as haabul mash\'amah'),
  ('en.transliteration', 56, 10, 'Wassaabiqoonas saabiqoon'),
  ('en.transliteration', 56, 11, 'Ulaaa\'ikal muqarraboon'),
  ('en.transliteration', 56, 12, 'Fee Jannaatin Na\'eem'),
  ('en.transliteration', 56, 13, 'Sullatum minal awwaleen'),
  ('en.transliteration', 56, 14, 'Wa qaleelum minal aa khireen'),
  ('en.transliteration', 56, 15, '\'Alaa sururim mawdoonah'),
  ('en.transliteration', 56, 16, 'Muttaki\'eena \'alaihaa mutaqabileen'),
  ('en.transliteration', 56, 17, 'Yatoofu \'alaihim wildaa num mukkhalladoon'),
  ('en.transliteration', 56, 18, 'Bi akwaabinw wa abaareeq, wa kaasim mim ma\'een'),
  ('en.transliteration', 56, 19, 'Laa yusadda\'oona \'anhaa wa laa yunzifoon'),
  ('en.transliteration', 56, 20, 'Wa faakihatim mimmaa yatakhaiyaroon'),
  ('en.transliteration', 56, 21, 'Wa lahmi tairim mimmaa yashtahoon'),
  ('en.transliteration', 56, 22, 'Wa hoorun\'een'),
  ('en.transliteration', 56, 23, 'Ka amsaalil lu\'lu\'il maknoon'),
  ('en.transliteration', 56, 24, 'Jazaaa\'am bimaa kaanoo ya\'maloon'),
  ('en.transliteration', 56, 25, 'Laa yasma\'oona feehaa laghwanw wa laa taaseemaa'),
  ('en.transliteration', 56, 26, 'Illaa qeelan salaaman salaamaa'),
  ('en.transliteration', 56, 27, 'Wa as haabul yameeni maaa as haabul Yameen'),
  ('en.transliteration', 56, 28, 'Fee sidrim makhdood'),
  ('en.transliteration', 56, 29, 'Wa talhim mandood'),
  ('en.transliteration', 56, 30, 'Wa zillim mamdood'),
  ('en.transliteration', 56, 31, 'Wa maaa\'im maskoob'),
  ('en.transliteration', 56, 32, 'Wa faakihatin kaseerah'),
  ('en.transliteration', 56, 33, 'Laa maqtoo\'atinw wa laa mamnoo\'ah'),
  ('en.transliteration', 56, 34, 'Wa furushim marfoo\'ah'),
  ('en.transliteration', 56, 35, 'Innaaa anshaanaahunna inshaaa\'aa'),
  ('en.transliteration', 56, 36, 'Faja\'alnaahunna abkaaraa'),
  ('en.transliteration', 56, 37, '\'Uruban atraabaa'),
  ('en.transliteration', 56, 38, 'Li as haabil yameen'),
  ('en.transliteration', 56, 39, 'Sullatum minal awwa leen'),
  ('en.transliteration', 56, 40, 'Wa sullatum minal aakhireen'),
  ('en.transliteration', 56, 41, 'Wa as haabush shimaali maaa as haabush shimaal'),
  ('en.transliteration', 56, 42, 'Fee samoominw wa hameem'),
  ('en.transliteration', 56, 43, 'Wa zillim miny yahmoom'),
  ('en.transliteration', 56, 44, 'Laa baaridinw wa laa kareem'),
  ('en.transliteration', 56, 45, 'Innaahum kaanoo qabla zaalika mutrafeen'),
  ('en.transliteration', 56, 46, 'Wa kaanoo yusirroona \'alal hinsil \'azeem'),
  ('en.transliteration', 56, 47, 'Wa kaanoo yaqooloona a\'izaa mitnaa wa kunnaa turaabanw wa izaaman\'ainnaa lamab\'oosoon'),
  ('en.transliteration', 56, 48, 'Awa aabaaa\'unal awwaloon'),
  ('en.transliteration', 56, 49, 'Qul innal awwaleena wal aakhireen'),
  ('en.transliteration', 56, 50, 'Lamajmoo\'oona ilaa meeqaati yawmim ma\'loon'),
  ('en.transliteration', 56, 51, 'summa innakum ayyuhad daaalloonal mukazziboon'),
  ('en.transliteration', 56, 52, 'La aakiloona min shaja rim min zaqqoom'),
  ('en.transliteration', 56, 53, 'Famaali\'oona minhal butoon'),
  ('en.transliteration', 56, 54, 'Fashaariboona \'alaihi minal hameem'),
  ('en.transliteration', 56, 55, 'Fashaariboona shurbal heem'),
  ('en.transliteration', 56, 56, 'Haazaa nuzuluhum yawmad deen'),
  ('en.transliteration', 56, 57, 'Nahnu khalaqnaakum falaw laa tusaddiqoon'),
  ('en.transliteration', 56, 58, 'Afara\'aytum maa tumnoon'),
  ('en.transliteration', 56, 59, '\'A-antum takhluqoo nahooo am nahnul khaaliqoon'),
  ('en.transliteration', 56, 60, 'Nahnu qaddarnaa baina kumul mawta wa maa nahnu bimasbooqeen'),
  ('en.transliteration', 56, 61, '\'Alaaa an nubaddila amsaalakum wa nunshi\'akum fee maa laa ta\'lamoon'),
  ('en.transliteration', 56, 62, 'Wa laqad \'alimtumun nash atal oolaa falaw laa tazakkaroon'),
  ('en.transliteration', 56, 63, 'Afara\'aytum maa tahrusoon'),
  ('en.transliteration', 56, 64, '\'A-antum tazra\'oonahooo am nahnuz zaari\'ooon'),
  ('en.transliteration', 56, 65, 'Law nashaaa\'u laja\'al naahu hutaaman fazaltum tafakkahoon'),
  ('en.transliteration', 56, 66, 'Innaa lamughramoon'),
  ('en.transliteration', 56, 67, 'Bal nahnu mahroomoon'),
  ('en.transliteration', 56, 68, 'Afara\'aytumul maaa\'allazee tashraboon'),
  ('en.transliteration', 56, 69, '\'A-antum anzaltumoohu minal muzni am nahnul munziloon'),
  ('en.transliteration', 56, 70, 'Law nashaaa\'u ja\'alnaahu ujaajan falaw laa tashkuroon'),
  ('en.transliteration', 56, 71, 'Afara\'aytumun naaral latee tooroon'),
  ('en.transliteration', 56, 72, '\'A-antum anshaatum shajaratahaaa am nahnul munshi\'oon'),
  ('en.transliteration', 56, 73, 'Nahnu ja\'alnaahaa tazkira tanw wa mataa\'al lilmuqween'),
  ('en.transliteration', 56, 74, 'Fasabbih bismi Rabbikal \'azeem'),
  ('en.transliteration', 56, 75, 'Falaa uqsimu bimaawaa qi\'innujoom'),
  ('en.transliteration', 56, 76, 'Wa innahoo laqasamul lawta\'lamoona\'azeem'),
  ('en.transliteration', 56, 77, 'Innahoo la quraanun kareem'),
  ('en.transliteration', 56, 78, 'Fee kitaabim maknoon'),
  ('en.transliteration', 56, 79, 'Laa yamassuhooo illal mutahharoon'),
  ('en.transliteration', 56, 80, 'Tanzeelum mir Rabbil\'aalameen'),
  ('en.transliteration', 56, 81, 'Afabihaazal hadeesi antum mudhinoon'),
  ('en.transliteration', 56, 82, 'Wa taj\'aloona rizqakum annakum tukazziboon'),
  ('en.transliteration', 56, 83, 'Falaw laaa izaa balaghatil hulqoom'),
  ('en.transliteration', 56, 84, 'Wa antum heena\'izin tanzuroon'),
  ('en.transliteration', 56, 85, 'Wa nahnu aqrabu ilaihi minkum wa laakil laa tubsiroon'),
  ('en.transliteration', 56, 86, 'Falaw laaa in kuntum ghira madeeneen'),
  ('en.transliteration', 56, 87, 'Tarji\'oonahaaa in kuntum saadiqeen'),
  ('en.transliteration', 56, 88, 'Fa ammaaa in kaana minal muqarrabeen'),
  ('en.transliteration', 56, 89, 'Farawhunw wa raihaa nunw wa jannatu na\'eem'),
  ('en.transliteration', 56, 90, 'Wa ammaaa in kaana min as haabil yameen'),
  ('en.transliteration', 56, 91, 'Fasalaamul laka min as haabil yameen'),
  ('en.transliteration', 56, 92, 'Wa ammaaa in kaana minal mukazzibeenad daaalleen'),
  ('en.transliteration', 56, 93, 'Fanuzulum min hameem'),
  ('en.transliteration', 56, 94, 'Wa tasliyatu jaheem'),
  ('en.transliteration', 56, 95, 'Inna haaza lahuwa haqqul yaqeen'),
  ('en.transliteration', 56, 96, 'Fasabbih bismi rabbikal \'azeem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 56, 1, 'جب واقع ہونے والی واقع ہو گی'),
  ('ur.ahmedali', 56, 2, 'جس کے واقع ہونے میں کچھ بھی جھوٹ نہیں'),
  ('ur.ahmedali', 56, 3, 'پست کرنے والی اور بلند کرنے والی'),
  ('ur.ahmedali', 56, 4, 'جب کہ زمین بڑے زور سے ہلائی جائے گی'),
  ('ur.ahmedali', 56, 5, 'اور پہاڑ ٹکڑے ٹکڑے ہو کر چورا ہو جائیں گے'),
  ('ur.ahmedali', 56, 6, 'سو و ہ غبار ہو کر اڑتے پھریں گے'),
  ('ur.ahmedali', 56, 7, 'اور (اس وقت) تمہاری تین جماعتیں ہو جائیں گی'),
  ('ur.ahmedali', 56, 8, 'پھر داہنے والے کیا خوب ہی ہیں داہنے والے'),
  ('ur.ahmedali', 56, 9, 'اوربائیں والے کیسے برے ہیں بائیں والے'),
  ('ur.ahmedali', 56, 10, 'اور سب سے اول ایمان لانے والے سب سے اول داخل ہونے والے ہیں'),
  ('ur.ahmedali', 56, 11, 'وہ الله کے ساتھ خاص قرب رکھنے والے ہیں'),
  ('ur.ahmedali', 56, 12, 'نعمت کے باغات ہوں گے'),
  ('ur.ahmedali', 56, 13, 'پہلوں میں سے بہت سے'),
  ('ur.ahmedali', 56, 14, 'اور پچھلوں میں سے تھوڑے سے'),
  ('ur.ahmedali', 56, 15, 'تختوں پر جو جڑاؤ ہوں گے'),
  ('ur.ahmedali', 56, 16, 'آمنے سامنے تکیہ لگائے ہوئےبیٹھے ہوں گے'),
  ('ur.ahmedali', 56, 17, 'ان کے پاس ایسے لڑکے جو ہمیشہ لڑکے ہی رہیں گے آمد و رفت کیا کریں گے'),
  ('ur.ahmedali', 56, 18, 'آبخورے اور آفتابے اور ایسا جام شراب لے کر جو بہتی ہوئی شراب سے بھرا جائے گا'),
  ('ur.ahmedali', 56, 19, 'نہ اس سے ان کو دردِ سر ہوگا اور نہ اس سے عقل میں فتور آئے گا'),
  ('ur.ahmedali', 56, 20, 'اور میوے جنہیں وہ پسند کریں گے'),
  ('ur.ahmedali', 56, 21, 'اور پرندوں کا گوشت جو ان کو مرغوب ہو گا'),
  ('ur.ahmedali', 56, 22, 'اوربڑی بڑی آنکھوں والی حوریں'),
  ('ur.ahmedali', 56, 23, 'جیسے موتی کئی تہو ں میں رکھےہوئے ہوں'),
  ('ur.ahmedali', 56, 24, 'بدلے اس کے جو وہ کیا کرتے تھے'),
  ('ur.ahmedali', 56, 25, 'وہ وہاں کوئی لغو اور گناہ کی بات نہیں سنیں گے'),
  ('ur.ahmedali', 56, 26, 'مگر سلام سلام کہنا'),
  ('ur.ahmedali', 56, 27, 'اور داہنے والے کیسے اچھے ہوں گے داہنے والے'),
  ('ur.ahmedali', 56, 28, 'وہ بے کانٹوں کی بیریوں میں ہوں گے'),
  ('ur.ahmedali', 56, 29, 'اور گتھے ہوئے کیلو ں میں'),
  ('ur.ahmedali', 56, 30, 'اورلمبے سایوں میں'),
  ('ur.ahmedali', 56, 31, 'اور پانی کی آبشاروں میں'),
  ('ur.ahmedali', 56, 32, 'اور باافراط میوں میں'),
  ('ur.ahmedali', 56, 33, 'جونہ کبھی منقطع ہوں گے اور نہ ان میں روک ٹوک ہو گی'),
  ('ur.ahmedali', 56, 34, 'اور اونچے فرشتوں میں'),
  ('ur.ahmedali', 56, 35, 'بے شک ہم نے انہیں (حوروں کو) ایک عجیب انداز سے پیدا کیا ہے'),
  ('ur.ahmedali', 56, 36, 'پس ہم نے انہیں کنواریاں بنا دیا ہے'),
  ('ur.ahmedali', 56, 37, 'دل لبھانے والی ہم عمر بنایا ہے'),
  ('ur.ahmedali', 56, 38, 'داہنے والوں کے لیے'),
  ('ur.ahmedali', 56, 39, 'بہت سے پہلوں میں سے ہوں گے'),
  ('ur.ahmedali', 56, 40, 'اور بہت سے پچھلوں میں سے'),
  ('ur.ahmedali', 56, 41, 'اوربائیں والے کیسے برے ہیں بائیں والے'),
  ('ur.ahmedali', 56, 42, 'وہ لووں اور کھولتے ہوئے پانی میں ہوں گے'),
  ('ur.ahmedali', 56, 43, 'اور سیاہ دھوئیں کے سائے میں'),
  ('ur.ahmedali', 56, 44, 'جو نہ ٹھنڈا ہوگا اور نہ راحت بخش'),
  ('ur.ahmedali', 56, 45, 'بے شک وہ اس سے پہلے خوش حال تھے'),
  ('ur.ahmedali', 56, 46, 'اور بڑے گناہ (شرک) پر اصرار کیا کرتے تھے'),
  ('ur.ahmedali', 56, 47, 'اور کہا کرتے تھے کیا جب ہم مر جائیں گے اور مٹی اور ہڈیاں ہو جائیں گے تو کیا ہم پھر اٹھاے جائیں گے'),
  ('ur.ahmedali', 56, 48, 'اور کیا ہمارے اگلے باپ دادا بھی'),
  ('ur.ahmedali', 56, 49, 'کہہ دو بے شک پہلے بھی اور پچھلے بھی'),
  ('ur.ahmedali', 56, 50, 'ایک معین تاریخ کے وقت پر جمع کیے جاویں گے'),
  ('ur.ahmedali', 56, 51, 'پھر بے شک تمہیں اے گمراہو جھٹلانے والو'),
  ('ur.ahmedali', 56, 52, 'البتہ تھوہر کا درخت کھانا ہوگا'),
  ('ur.ahmedali', 56, 53, 'پھر اس سے پیٹ بھرنے ہوں گے'),
  ('ur.ahmedali', 56, 54, 'پھر اس پر کھولتا ہوا پانی پینا ہوگا'),
  ('ur.ahmedali', 56, 55, 'پھر پینا ہو گا پیاسے اونٹوں کا سا پینا'),
  ('ur.ahmedali', 56, 56, 'قیامت کے دن یہ ان کی مہمانی ہو گی'),
  ('ur.ahmedali', 56, 57, 'ہم نے ہی تمہیں پیدا کیا ہے پس کیوں تم تصدیق نہیں کرتے'),
  ('ur.ahmedali', 56, 58, 'بھلا دیکھو (تو) (منی) جو تم ٹپکاتے ہو'),
  ('ur.ahmedali', 56, 59, 'کیا تم اسے پیدا کرتے ہو یا ہم ہی پیدا کرنے والے ہیں'),
  ('ur.ahmedali', 56, 60, 'ہم نے ہی تمہارے درمیان موت مقرر کر دی ہے اور ہم عاجز نہیں ہیں'),
  ('ur.ahmedali', 56, 61, 'اس بات سے کہ ہم تم جیسے لوگ بدل لائیں اور تمہیں ایسی صورت میں بنا کھڑا کریں جو تم نہیں جانتے'),
  ('ur.ahmedali', 56, 62, 'اور تم پہلی پیدائش کو جان چکے ہو پھر کیوں تم غور نہیں کرتے'),
  ('ur.ahmedali', 56, 63, 'بھلا دیکھو جو کچھ تم بولتے ہو'),
  ('ur.ahmedali', 56, 64, 'کیا تم اسے اگاتے ہو یا ہم اگانے والے ہیں'),
  ('ur.ahmedali', 56, 65, 'اگر ہم چاہیں تو اسے چورا چورا کر دیں پھر تم تعجب کرتے رہ جاؤ'),
  ('ur.ahmedali', 56, 66, 'کہ بے شک ہم پر تو تاوان پڑ گیا'),
  ('ur.ahmedali', 56, 67, 'بلکہ ہم بے نصیب ہو گئے'),
  ('ur.ahmedali', 56, 68, 'بھلا دیکھو تو سہی وہ پانی جو تم پیتے ہو'),
  ('ur.ahmedali', 56, 69, 'کیا تم نے اسے بادل سے اتارا ہے یا ہم اتارنے والے ہیں'),
  ('ur.ahmedali', 56, 70, 'اگر ہم چاہیں تو اسے کھاری کر دیں پس کیوں تم شکر نہیں کرتے'),
  ('ur.ahmedali', 56, 71, 'بھلا دیکھو تو سہی وہ آگ جو تم سلگاتے ہو'),
  ('ur.ahmedali', 56, 72, 'کیا تم نے اس کا درخت پیدا کیا ہے یا ہم پیدا کرنے والے ہیں'),
  ('ur.ahmedali', 56, 73, 'ہم نے اسے یادگار اور مسافروں کے لیے فائدہ کی چیز بنا دیا ہے'),
  ('ur.ahmedali', 56, 74, 'پس اپنے رب کے نام کی تسبیح کر جو بڑا عظمت والا ہے'),
  ('ur.ahmedali', 56, 75, 'پھر میں تاروں کے ڈوبنے کی قسم کھاتا ہوں'),
  ('ur.ahmedali', 56, 76, 'اور بے شک اگر سمجھو تو یہ بڑی قسم ہے'),
  ('ur.ahmedali', 56, 77, 'کہ بے شک یہ قرآن بڑی شان والا ہے'),
  ('ur.ahmedali', 56, 78, 'ایک پوشیدہ کتاب میں لکھا ہوا ہے'),
  ('ur.ahmedali', 56, 79, 'جسے بغیر پاکو ں کے اور کوئی نہیں چھوتا'),
  ('ur.ahmedali', 56, 80, 'پروردگار عالم کی طرف سے نازل ہوا ہے'),
  ('ur.ahmedali', 56, 81, 'سو کیا تم اس کلام کو سرسری بات سمجھتے ہو'),
  ('ur.ahmedali', 56, 82, 'اور اپنا حصہ تم یہی لیتے ہو کہ اسے جھٹلاتے ہو'),
  ('ur.ahmedali', 56, 83, 'پھر کس لیے روح کو روک نہیں لیتے جب کہ وہ گلے تک آ جاتی ہے'),
  ('ur.ahmedali', 56, 84, 'اورتم اس وقت دیکھا کرتے ہو'),
  ('ur.ahmedali', 56, 85, 'اور تم سے زیادہ ہم اس کے قرب ہوتے ہیں لیکن تم نہیں دیکھتے'),
  ('ur.ahmedali', 56, 86, 'پس اگر تمہارا حساب کتاب ہونے والا نہیں ہے'),
  ('ur.ahmedali', 56, 87, 'تو تم اس روح کو کیوں نہیں لوٹا دیتے اگر تم سچے ہو'),
  ('ur.ahmedali', 56, 88, 'پھر (جب قیامت آئے گی) اگر وہ مقربین میں سے ہے'),
  ('ur.ahmedali', 56, 89, 'تو (اس کے لیے) راحت اور خوشبو میں اور عیش کی باغ ہیں'),
  ('ur.ahmedali', 56, 90, 'اور اگر وہ داہنے والوں میں سے ہے'),
  ('ur.ahmedali', 56, 91, 'تو اے شخص تو جو داہنے والوں میں سے ہے تجھ پر سلام ہو'),
  ('ur.ahmedali', 56, 92, 'اور اگر وہ جھٹلانے والے گمراہوں میں سے ہے'),
  ('ur.ahmedali', 56, 93, 'تو کھولتا ہوا پانی مہمانی ہے'),
  ('ur.ahmedali', 56, 94, 'اور دوزخ میں داخل ہونا ہے'),
  ('ur.ahmedali', 56, 95, 'بے شک یہ تحقیقی یقینی بات ہے'),
  ('ur.ahmedali', 56, 96, 'پس اپنے رب کی نام تسبیح کر جو بڑا عظمت والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 56, 1, 'Kıyamet koptuğunda kimini alçaltacak ve kimini yükseltecek olan o hadisenin yalan olmadığı ortaya çıkacaktır.'),
  ('tr.diyanet', 56, 2, 'Kıyamet koptuğunda kimini alçaltacak ve kimini yükseltecek olan o hadisenin yalan olmadığı ortaya çıkacaktır.'),
  ('tr.diyanet', 56, 3, 'Kıyamet koptuğunda kimini alçaltacak ve kimini yükseltecek olan o hadisenin yalan olmadığı ortaya çıkacaktır.'),
  ('tr.diyanet', 56, 4, 'Ey insanlar! Yer sarsıldıkça sarsıldığı, dağlar ufalandıkça ufalanıp da toz duman haline geldiği zaman, siz de üç sınıf olursunuz.'),
  ('tr.diyanet', 56, 5, 'Ey insanlar! Yer sarsıldıkça sarsıldığı, dağlar ufalandıkça ufalanıp da toz duman haline geldiği zaman, siz de üç sınıf olursunuz.'),
  ('tr.diyanet', 56, 6, 'Ey insanlar! Yer sarsıldıkça sarsıldığı, dağlar ufalandıkça ufalanıp da toz duman haline geldiği zaman, siz de üç sınıf olursunuz.'),
  ('tr.diyanet', 56, 7, 'Ey insanlar! Yer sarsıldıkça sarsıldığı, dağlar ufalandıkça ufalanıp da toz duman haline geldiği zaman, siz de üç sınıf olursunuz.'),
  ('tr.diyanet', 56, 8, 'İyi işler işlediklerini belirtmek için, amel defterleri sağdan verilenler; ne mutlu o sağcılara!'),
  ('tr.diyanet', 56, 9, 'Kötülük işlediklerini belirtmek üzere, amel defterleri soldan verilenler; ne yazık o solculara!'),
  ('tr.diyanet', 56, 10, 'İyilik işlemekte önde olanlar, karşılıklarını almakta da önde olanlardır.'),
  ('tr.diyanet', 56, 11, 'Naim cennetlerinde Allah\'a en çok yaklaştırılmış olanlar işte bunlardır.'),
  ('tr.diyanet', 56, 12, 'Naim cennetlerinde Allah\'a en çok yaklaştırılmış olanlar işte bunlardır.'),
  ('tr.diyanet', 56, 13, 'Onların büyük kısmı eski ümmetlerden, bir kısmı da sonrakilerdendir.'),
  ('tr.diyanet', 56, 14, 'Onların büyük kısmı eski ümmetlerden, bir kısmı da sonrakilerdendir.'),
  ('tr.diyanet', 56, 15, 'Mücevheratla işlenmiş tahtlara karşılıklı olarak yaslanırlar.'),
  ('tr.diyanet', 56, 16, 'Mücevheratla işlenmiş tahtlara karşılıklı olarak yaslanırlar.'),
  ('tr.diyanet', 56, 17, 'Ölümsüz gençler yanlarında, baş ağrısı ve dönmesi vermeyen bembeyaz bir kaynaktan doldurulmuş kaseler, ibrikler, kadehler; seçecekleri meyveler, arzulayacakları kuş eti ile dolaşırlar.'),
  ('tr.diyanet', 56, 18, 'Ölümsüz gençler yanlarında, baş ağrısı ve dönmesi vermeyen bembeyaz bir kaynaktan doldurulmuş kaseler, ibrikler, kadehler; seçecekleri meyveler, arzulayacakları kuş eti ile dolaşırlar.'),
  ('tr.diyanet', 56, 19, 'Ölümsüz gençler yanlarında, baş ağrısı ve dönmesi vermeyen bembeyaz bir kaynaktan doldurulmuş kaseler, ibrikler, kadehler; seçecekleri meyveler, arzulayacakları kuş eti ile dolaşırlar.'),
  ('tr.diyanet', 56, 20, 'Ölümsüz gençler yanlarında, baş ağrısı ve dönmesi vermeyen bembeyaz bir kaynaktan doldurulmuş kaseler, ibrikler, kadehler; seçecekleri meyveler, arzulayacakları kuş eti ile dolaşırlar.'),
  ('tr.diyanet', 56, 21, 'Ölümsüz gençler yanlarında, baş ağrısı ve dönmesi vermeyen bembeyaz bir kaynaktan doldurulmuş kaseler, ibrikler, kadehler; seçecekleri meyveler, arzulayacakları kuş eti ile dolaşırlar.'),
  ('tr.diyanet', 56, 22, 'İşlediklerine karşılık olarak, sedefteki inciler gibi ceylan gözlüler vardır. Orada boş ve günaha sokacak bir söz duymazlar.'),
  ('tr.diyanet', 56, 23, 'İşlediklerine karşılık olarak, sedefteki inciler gibi ceylan gözlüler vardır. Orada boş ve günaha sokacak bir söz duymazlar.'),
  ('tr.diyanet', 56, 24, 'İşlediklerine karşılık olarak, sedefteki inciler gibi ceylan gözlüler vardır. Orada boş ve günaha sokacak bir söz duymazlar.'),
  ('tr.diyanet', 56, 25, 'Sadece selama karşılık selam sözü işitirler.'),
  ('tr.diyanet', 56, 26, 'Defterleri sağdan verilenler; ne mutlu o sağcılara!'),
  ('tr.diyanet', 56, 27, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 28, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 29, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 30, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 31, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 32, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 33, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 34, 'Onlar dikensiz sedir ağaçları, salkımları sarkmış muz ağaçları, uzamış gölge altında, çağlayarak akan sular kenarlarında; bitip tükenmeyen ve yasak da edilmeyen bol meyveler arasında; yüksek döşekler üzerindedirler.'),
  ('tr.diyanet', 56, 35, 'Biz ceylan gözlüleri, defterleri sağdan verilenler için yeniden yaratmışızdır; onları bakire, eşlerine düşkün ve hepsini bir yaşta kılmışızdır.'),
  ('tr.diyanet', 56, 36, 'Biz ceylan gözlüleri, defterleri sağdan verilenler için yeniden yaratmışızdır; onları bakire, eşlerine düşkün ve hepsini bir yaşta kılmışızdır.'),
  ('tr.diyanet', 56, 37, 'Biz ceylan gözlüleri, defterleri sağdan verilenler için yeniden yaratmışızdır; onları bakire, eşlerine düşkün ve hepsini bir yaşta kılmışızdır.'),
  ('tr.diyanet', 56, 38, 'Biz ceylan gözlüleri, defterleri sağdan verilenler için yeniden yaratmışızdır; onları bakire, eşlerine düşkün ve hepsini bir yaşta kılmışızdır.'),
  ('tr.diyanet', 56, 39, 'Bunların bir kısmı eski ümmetlerden, bir kısmı da sonrakilerdendir.'),
  ('tr.diyanet', 56, 40, 'Bunların bir kısmı eski ümmetlerden, bir kısmı da sonrakilerdendir.'),
  ('tr.diyanet', 56, 41, 'Defterleri soldan verilenler; ne yazık o solculara!'),
  ('tr.diyanet', 56, 42, 'İnsanın içine işleyen bir sıcaklık ve kaynar su içinde, serinliği ve hoşluğu olmayan kara bir dumanın gölgesinde bulunurlar.'),
  ('tr.diyanet', 56, 43, 'İnsanın içine işleyen bir sıcaklık ve kaynar su içinde, serinliği ve hoşluğu olmayan kara bir dumanın gölgesinde bulunurlar.'),
  ('tr.diyanet', 56, 44, 'İnsanın içine işleyen bir sıcaklık ve kaynar su içinde, serinliği ve hoşluğu olmayan kara bir dumanın gölgesinde bulunurlar.'),
  ('tr.diyanet', 56, 45, 'Çünkü onlar, bundan önce, dünyada, nimet içinde bulunurlar iken, büyük günah işlemekte direnir dururlardı.'),
  ('tr.diyanet', 56, 46, 'Çünkü onlar, bundan önce, dünyada, nimet içinde bulunurlar iken, büyük günah işlemekte direnir dururlardı.'),
  ('tr.diyanet', 56, 47, 'Şöyle söylerlerdi: "Öldüğümüzde, toprak ve kemik yığını olduğumuzda mı, biz mi tekrar dirileceğiz?"'),
  ('tr.diyanet', 56, 48, '"Önce gelip geçmiş babalarımız da mı?"'),
  ('tr.diyanet', 56, 49, 'De ki: "Şüphesiz öncekiler de, sonrakiler de belli bir günün belirli bir vaktinde toplanacaklardır."'),
  ('tr.diyanet', 56, 50, 'De ki: "Şüphesiz öncekiler de, sonrakiler de belli bir günün belirli bir vaktinde toplanacaklardır."'),
  ('tr.diyanet', 56, 51, 'Sonra, siz ey sapıklar, yalanlayanlar!'),
  ('tr.diyanet', 56, 52, 'Doğrusu bir zakkum ağacından yiyeceksiniz.'),
  ('tr.diyanet', 56, 53, 'Karınlarınızı onunla dolduracaksınız;'),
  ('tr.diyanet', 56, 54, 'Onun üzerine kaynar su içeceksiniz;'),
  ('tr.diyanet', 56, 55, 'Hem de susamış develerin suya saldırışı gibi içeceksiniz;'),
  ('tr.diyanet', 56, 56, 'İşte onlara, ceza günü sunulacak konukluk budur.'),
  ('tr.diyanet', 56, 57, 'Sizi yaratan Biziz; hala tasdik etmez misiniz?'),
  ('tr.diyanet', 56, 58, 'Söyleyin; akıttığınız meniden insanı yaratan siz misiniz, yoksa Biz mi yaratmaktayız?'),
  ('tr.diyanet', 56, 59, 'Söyleyin; akıttığınız meniden insanı yaratan siz misiniz, yoksa Biz mi yaratmaktayız?'),
  ('tr.diyanet', 56, 60, 'Ölümü aranızda Biz tayin ettik; sizi ortadan kaldırıp benzerlerinizi yerinize getirmeyi, sizi bilmediğiniz şekilde var etmeyi dilesek kimse önümüze geçemez.'),
  ('tr.diyanet', 56, 61, 'Ölümü aranızda Biz tayin ettik; sizi ortadan kaldırıp benzerlerinizi yerinize getirmeyi, sizi bilmediğiniz şekilde var etmeyi dilesek kimse önümüze geçemez.'),
  ('tr.diyanet', 56, 62, 'And olsun ki, ilk yaratmayı bilirsiniz, yine de düşünmez misiniz?'),
  ('tr.diyanet', 56, 63, 'Söyleyin, ektiklerinizi yerden bitirenler sizler misiniz, yoksa Biz mi bitiriyoruz?'),
  ('tr.diyanet', 56, 64, 'Söyleyin, ektiklerinizi yerden bitirenler sizler misiniz, yoksa Biz mi bitiriyoruz?'),
  ('tr.diyanet', 56, 65, 'Dilersek Biz onu çerçöp yaparız, şaşar kalırsınız; "Doğrusu borç altına girdik, hatta yoksun kaldık".'),
  ('tr.diyanet', 56, 66, 'Dilersek Biz onu çerçöp yaparız, şaşar kalırsınız; "Doğrusu borç altına girdik, hatta yoksun kaldık".'),
  ('tr.diyanet', 56, 67, 'Dilersek Biz onu çerçöp yaparız, şaşar kalırsınız; "Doğrusu borç altına girdik, hatta yoksun kaldık".'),
  ('tr.diyanet', 56, 68, 'Söyleyin; içtiğiniz suyu buluttan indirenler sizler misiniz yoksa onu Biz mi indiririz?'),
  ('tr.diyanet', 56, 69, 'Söyleyin; içtiğiniz suyu buluttan indirenler sizler misiniz yoksa onu Biz mi indiririz?'),
  ('tr.diyanet', 56, 70, 'Dileseydik onu acılaştırırdık; hala şükretmez misiniz?'),
  ('tr.diyanet', 56, 71, 'Söyleyin; yaktığınız ateşin ağacını var eden sizler misiniz, yoksa onu Biz mi var ederiz?'),
  ('tr.diyanet', 56, 72, 'Söyleyin; yaktığınız ateşin ağacını var eden sizler misiniz, yoksa onu Biz mi var ederiz?'),
  ('tr.diyanet', 56, 73, 'Biz onu bir ibret ve çölde konaklayanlar için yararlı kıldık.'),
  ('tr.diyanet', 56, 74, 'Öyleyse çok büyük Rabbinin adını tesbih et.'),
  ('tr.diyanet', 56, 75, 'Hayır; yıldızların yerleri üzerine yemin ederim; ki bunun ne büyük yemin olduğunu bir bilseniz!'),
  ('tr.diyanet', 56, 76, 'Hayır; yıldızların yerleri üzerine yemin ederim; ki bunun ne büyük yemin olduğunu bir bilseniz!'),
  ('tr.diyanet', 56, 77, 'Doğrusu bu Kitap, sadece arınmış olanların dokunabileceği, saklı bir Kitap\'da mevcutken Alemlerin Rabbi tarafından indirilmiş olan Kuranı Kerim\'dir.'),
  ('tr.diyanet', 56, 78, 'Doğrusu bu Kitap, sadece arınmış olanların dokunabileceği, saklı bir Kitap\'da mevcutken Alemlerin Rabbi tarafından indirilmiş olan Kuranı Kerim\'dir.'),
  ('tr.diyanet', 56, 79, 'Doğrusu bu Kitap, sadece arınmış olanların dokunabileceği, saklı bir Kitap\'da mevcutken Alemlerin Rabbi tarafından indirilmiş olan Kuranı Kerim\'dir.'),
  ('tr.diyanet', 56, 80, 'Doğrusu bu Kitap, sadece arınmış olanların dokunabileceği, saklı bir Kitap\'da mevcutken Alemlerin Rabbi tarafından indirilmiş olan Kuranı Kerim\'dir.'),
  ('tr.diyanet', 56, 81, 'Siz bu sözü mü hor görüyorsunuz?'),
  ('tr.diyanet', 56, 82, 'Rızkınıza şükredeceğiniz yere onu vereni mi yalanlıyorsunuz?'),
  ('tr.diyanet', 56, 83, 'Kişinin canı boğaza dayanınca ve siz o zaman bakıp kalırken, Biz o kişiye sizden daha yakınızdır, ama görmezsiniz.'),
  ('tr.diyanet', 56, 84, 'Kişinin canı boğaza dayanınca ve siz o zaman bakıp kalırken, Biz o kişiye sizden daha yakınızdır, ama görmezsiniz.'),
  ('tr.diyanet', 56, 85, 'Kişinin canı boğaza dayanınca ve siz o zaman bakıp kalırken, Biz o kişiye sizden daha yakınızdır, ama görmezsiniz.'),
  ('tr.diyanet', 56, 86, 'Siz dirilip yaptıklarınıza karşılık görmeyecekseniz ve eğer bu sözünüzde samimi iseniz, o çıkmak üzere olan canı geri çevirsenize!'),
  ('tr.diyanet', 56, 87, 'Siz dirilip yaptıklarınıza karşılık görmeyecekseniz ve eğer bu sözünüzde samimi iseniz, o çıkmak üzere olan canı geri çevirsenize!'),
  ('tr.diyanet', 56, 88, 'Eğer ölen o kişi, gözdelerden ise, rahatlık, hoşluk ve nimet cenneti onundur.'),
  ('tr.diyanet', 56, 89, 'Eğer ölen o kişi, gözdelerden ise, rahatlık, hoşluk ve nimet cenneti onundur.'),
  ('tr.diyanet', 56, 90, 'Eğer defteri sağdan verilenlerden ise,'),
  ('tr.diyanet', 56, 91, '"Ey sağcılardan olan kişi, sana selam olsun!" denir.'),
  ('tr.diyanet', 56, 92, 'Eğer, sapık yalancılardan ise,'),
  ('tr.diyanet', 56, 93, 'Ona kaynar sudan konukluk sunulur.'),
  ('tr.diyanet', 56, 94, 'Cehenneme sokulur.'),
  ('tr.diyanet', 56, 95, 'Doğrusu kesin gerçek budur.'),
  ('tr.diyanet', 56, 96, 'Öyleyse çok büyük Rabbinin adını tesbih et.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 56, 1, 'Apabila terjadi hari kiamat,'),
  ('id.indonesian', 56, 2, 'tidak seorangpun dapat berdusta tentang kejadiannya.'),
  ('id.indonesian', 56, 3, '(Kejadian itu) merendahkan (satu golongan) dan meninggikan (golongan yang lain),'),
  ('id.indonesian', 56, 4, 'apabila bumi digoncangkan sedahsyat-dahsyatnya,'),
  ('id.indonesian', 56, 5, 'dan gunung-gunung dihancur luluhkan seluluh-luluhnya,'),
  ('id.indonesian', 56, 6, 'maka jadilah ia debu yang beterbangan,'),
  ('id.indonesian', 56, 7, 'dan kamu menjadi tiga golongan.'),
  ('id.indonesian', 56, 8, 'Yaitu golongan kanan. Alangkah mulianya golongan kanan itu.'),
  ('id.indonesian', 56, 9, 'Dan golongan kiri. Alangkah sengsaranya golongan kiri itu.'),
  ('id.indonesian', 56, 10, 'Dan orang-orang yang beriman paling dahulu,'),
  ('id.indonesian', 56, 11, 'Mereka itulah yang didekatkan kepada Allah.'),
  ('id.indonesian', 56, 12, 'Berada dalam jannah kenikmatan.'),
  ('id.indonesian', 56, 13, 'Segolongan besar dari orang-orang yang terdahulu,'),
  ('id.indonesian', 56, 14, 'dan segolongan kecil dari orang-orang yang kemudian'),
  ('id.indonesian', 56, 15, 'Mereka berada di atas dipan yang bertahta emas dan permata,'),
  ('id.indonesian', 56, 16, 'seraya bertelekan di atasnya berhadap-hadapan.'),
  ('id.indonesian', 56, 17, 'Mereka dikelilingi oleh anak-anak muda yang tetap muda,'),
  ('id.indonesian', 56, 18, 'dengan membawa gelas, cerek dan minuman yang diambil dari air yang mengalir,'),
  ('id.indonesian', 56, 19, 'mereka tidak pening karenanya dan tidak pula mabuk,'),
  ('id.indonesian', 56, 20, 'dan buah-buahan dari apa yang mereka pilih,'),
  ('id.indonesian', 56, 21, 'dan daging burung dari apa yang mereka inginkan.'),
  ('id.indonesian', 56, 22, 'Dan ada bidadari-bidadari bermata jeli,'),
  ('id.indonesian', 56, 23, 'laksana mutiara yang tersimpan baik.'),
  ('id.indonesian', 56, 24, 'Sebagai balasan bagi apa yang telah mereka kerjakan.'),
  ('id.indonesian', 56, 25, 'Mereka tidak mendengar di dalamnya perkataan yang sia-sia dan tidak pula perkataan yang menimbulkan dosa,'),
  ('id.indonesian', 56, 26, 'akan tetapi mereka mendengar ucapan salam.'),
  ('id.indonesian', 56, 27, 'Dan golongan kanan, alangkah bahagianya golongan kanan itu.'),
  ('id.indonesian', 56, 28, 'Berada di antara pohon bidara yang tak berduri,'),
  ('id.indonesian', 56, 29, 'dan pohon pisang yang bersusun-susun (buahnya),'),
  ('id.indonesian', 56, 30, 'dan naungan yang terbentang luas,'),
  ('id.indonesian', 56, 31, 'dan air yang tercurah,'),
  ('id.indonesian', 56, 32, 'dan buah-buahan yang banyak,'),
  ('id.indonesian', 56, 33, 'yang tidak berhenti (berbuah) dan tidak terlarang mengambilnya.'),
  ('id.indonesian', 56, 34, 'dan kasur-kasur yang tebal lagi empuk.'),
  ('id.indonesian', 56, 35, 'Sesungguhnya Kami menciptakan mereka (bidadari-bidadari) dengan langsung'),
  ('id.indonesian', 56, 36, 'dan Kami jadikan mereka gadis-gadis perawan.'),
  ('id.indonesian', 56, 37, 'penuh cinta lagi sebaya umurnya.'),
  ('id.indonesian', 56, 38, '(Kami ciptakan mereka) untuk golongan kanan,'),
  ('id.indonesian', 56, 39, '(yaitu) segolongan besar dari orang-orang yang terdahulu.'),
  ('id.indonesian', 56, 40, 'dan segolongan besar pula dari orang-orang yang kemudian.'),
  ('id.indonesian', 56, 41, 'Dan golongan kiri, siapakah golongan kiri itu?'),
  ('id.indonesian', 56, 42, 'Dalam (siksaan) angin yang amat panas, dan air panas yang mendidih,'),
  ('id.indonesian', 56, 43, 'dan dalam naungan asap yang hitam.'),
  ('id.indonesian', 56, 44, 'Tidak sejuk dan tidak menyenangkan.'),
  ('id.indonesian', 56, 45, 'Sesungguhnya mereka sebelum itu hidup bermewahan.'),
  ('id.indonesian', 56, 46, 'Dan mereka terus-menerus mengerjakan dosa besar.'),
  ('id.indonesian', 56, 47, 'Dan mereka selalu mengatakan: "Apakah bila kami mati dan menjadi tanah dan tulang belulang, apakah sesungguhnya kami akan benar-benar dibangkitkan kembali?'),
  ('id.indonesian', 56, 48, 'apakah bapak-bapak kami yang terdahulu (juga)?"'),
  ('id.indonesian', 56, 49, 'Katakanlah: "Sesungguhnya orang-orang yang terdahulu dan orang-orang yang terkemudian,'),
  ('id.indonesian', 56, 50, 'benar-benar akan dikumpulkan di waktu tertentu pada hari yang dikenal.'),
  ('id.indonesian', 56, 51, 'Kemudian sesungguhnya kamu hai orang-orang yang sesat lagi mendustakan,'),
  ('id.indonesian', 56, 52, 'benar-benar akan memakan pohon zaqqum,'),
  ('id.indonesian', 56, 53, 'dan akan memenuhi perutmu dengannya.'),
  ('id.indonesian', 56, 54, 'Sesudah itu kamu akan meminum air yang sangat panas.'),
  ('id.indonesian', 56, 55, 'Maka kamu minum seperti unta yang sangat haus minum.'),
  ('id.indonesian', 56, 56, 'Itulah hidangan untuk mereka pada hari Pembalasan".'),
  ('id.indonesian', 56, 57, 'Kami telah menciptakan kamu, maka mengapa kamu tidak membenarkan?'),
  ('id.indonesian', 56, 58, 'Maka terangkanlah kepadaku tentang nutfah yang kamu pancarkan.'),
  ('id.indonesian', 56, 59, 'Kamukah yang menciptakannya, atau Kamikah yang menciptakannya?'),
  ('id.indonesian', 56, 60, 'Kami telah menentukan kematian di antara kamu dan Kami sekali-sekali tidak akan dapat dikalahkan,'),
  ('id.indonesian', 56, 61, 'untuk menggantikan kamu dengan orang-orang yang seperti kamu (dalam dunia) dan menciptakan kamu kelak (di akhirat) dalam keadaan yang tidak kamu ketahui.'),
  ('id.indonesian', 56, 62, 'Dan Sesungguhnya kamu telah mengetahui penciptaan yang pertama, maka mengapakah kamu tidak mengambil pelajaran (untuk penciptaan yang kedua)?'),
  ('id.indonesian', 56, 63, 'Maka terangkanlah kepadaku tentang yang kamu tanam.'),
  ('id.indonesian', 56, 64, 'Kamukah yang menumbuhkannya atau Kamikah yang menumbuhkannya?'),
  ('id.indonesian', 56, 65, 'Kalau Kami kehendaki, benar-benar Kami jadikan dia hancur dan kering, maka jadilah kamu heran dan tercengang.'),
  ('id.indonesian', 56, 66, '(Sambil berkata): "Sesungguhnya kami benar-benar menderita kerugian",'),
  ('id.indonesian', 56, 67, 'bahkan kami menjadi orang-orang yang tidak mendapat hasil apa-apa.'),
  ('id.indonesian', 56, 68, 'Maka terangkanlah kepadaku tentang air yang kamu minum.'),
  ('id.indonesian', 56, 69, 'Kamukah yang menurunkannya atau Kamikah yang menurunkannya?'),
  ('id.indonesian', 56, 70, 'Kalau Kami kehendaki, niscaya Kami jadikan dia asin, maka mengapakah kamu tidak bersyukur?'),
  ('id.indonesian', 56, 71, 'Maka terangkanlah kepadaku tentang api yang kamu nyalakan (dengan menggosok-gosokkan kayu).'),
  ('id.indonesian', 56, 72, 'Kamukah yang menjadikan kayu itu atau Kamikah yang menjadikannya?'),
  ('id.indonesian', 56, 73, 'Kami jadikan api itu untuk peringatan dan bahan yang berguna bagi musafir di padang pasir.'),
  ('id.indonesian', 56, 74, 'Maka bertasbihlah dengan (menyebut) nama Rabbmu Yang Maha Besar.'),
  ('id.indonesian', 56, 75, 'Maka Aku bersumpah dengan masa turunnya bagian-bagian Al-Quran.'),
  ('id.indonesian', 56, 76, 'Sesungguhnya sumpah itu adalah sumpah yang besar kalau kamu mengetahui.'),
  ('id.indonesian', 56, 77, 'Sesungguhnya Al-Quran ini adalah bacaan yang sangat mulia,'),
  ('id.indonesian', 56, 78, 'pada kitab yang terpelihara (Lauhul Mahfuzh),'),
  ('id.indonesian', 56, 79, 'tidak menyentuhnya kecuali orang-orang yang disucikan.'),
  ('id.indonesian', 56, 80, 'Diturunkan dari Rabbil \'alamiin.'),
  ('id.indonesian', 56, 81, 'Maka apakah kamu menganggap remeh saja Al-Quran ini?'),
  ('id.indonesian', 56, 82, 'kamu mengganti rezeki (yang Allah berikan) dengan mendustakan Allah.'),
  ('id.indonesian', 56, 83, 'Maka mengapa ketika nyawa sampai di kerongkongan,'),
  ('id.indonesian', 56, 84, 'padahal kamu ketika itu melihat,'),
  ('id.indonesian', 56, 85, 'dan Kami lebih dekat kepadanya dari pada kamu. Tetapi kamu tidak melihat,'),
  ('id.indonesian', 56, 86, 'maka mengapa jika kamu tidak dikuasai (oleh Allah)?'),
  ('id.indonesian', 56, 87, 'Kamu tidak mengembalikan nyawa itu (kepada tempatnya) jika kamu adalah orang-orang yang benar?'),
  ('id.indonesian', 56, 88, 'adapun jika dia (orang yang mati) termasuk orang-orang yang didekatkan (kepada Allah),'),
  ('id.indonesian', 56, 89, 'maka dia memperoleh ketenteraman dan rezeki serta jannah kenikmatan.'),
  ('id.indonesian', 56, 90, 'Dan adapun jika dia termasuk golongan kanan,'),
  ('id.indonesian', 56, 91, 'maka keselamatanlah bagimu karena kamu dari golongan kanan.'),
  ('id.indonesian', 56, 92, 'Dan adapun jika dia termasuk golongan yang mendustakan lagi sesat,'),
  ('id.indonesian', 56, 93, 'maka dia mendapat hidangan air yang mendidih,'),
  ('id.indonesian', 56, 94, 'dan dibakar di dalam jahannam.'),
  ('id.indonesian', 56, 95, 'Sesungguhnya (yang disebutkan ini) adalah suatu keyakinan yang benar.'),
  ('id.indonesian', 56, 96, 'Maka bertasbihlah dengan (menyebut) nama Rabbmu yang Maha Besar.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 57, 1, 'Whatever is in the heavens and earth exalts Allah, and He is the Exalted in Might, the Wise.'),
  ('en.sahih', 57, 2, 'His is the dominion of the heavens and earth. He gives life and causes death, and He is over all things competent.'),
  ('en.sahih', 57, 3, 'He is the First and the Last, the Ascendant and the Intimate, and He is, of all things, Knowing.'),
  ('en.sahih', 57, 4, 'It is He who created the heavens and earth in six days and then established Himself above the Throne. He knows what penetrates into the earth and what emerges from it and what descends from the heaven and what ascends therein; and He is with you wherever you are. And Allah, of what you do, is Seeing.'),
  ('en.sahih', 57, 5, 'His is the dominion of the heavens and earth. And to Allah are returned [all] matters.'),
  ('en.sahih', 57, 6, 'He causes the night to enter the day and causes the day to enter the night, and he is Knowing of that within the breasts.'),
  ('en.sahih', 57, 7, 'Believe in Allah and His Messenger and spend out of that in which He has made you successors. For those who have believed among you and spent, there will be a great reward.'),
  ('en.sahih', 57, 8, 'And why do you not believe in Allah while the Messenger invites you to believe in your Lord and He has taken your covenant, if you should [truly] be believers?'),
  ('en.sahih', 57, 9, 'It is He who sends down upon His Servant [Muhammad] verses of clear evidence that He may bring you out from darknesses into the light. And indeed, Allah is to you Kind and Merciful.'),
  ('en.sahih', 57, 10, 'And why do you not spend in the cause of Allah while to Allah belongs the heritage of the heavens and the earth? Not equal among you are those who spent before the conquest [of Makkah] and fought [and those who did so after it]. Those are greater in degree than they who spent afterwards and fought. But to all Allah has promised the best [reward]. And Allah, with what you do, is Acquainted.'),
  ('en.sahih', 57, 11, 'Who is it that would loan Allah a goodly loan so He will multiply it for him and he will have a noble reward?'),
  ('en.sahih', 57, 12, 'On the Day you see the believing men and believing women, their light proceeding before them and on their right, [it will be said], "Your good tidings today are [of] gardens beneath which rivers flow, wherein you will abide eternally." That is what is the great attainment.'),
  ('en.sahih', 57, 13, 'On the [same] Day the hypocrite men and hypocrite women will say to those who believed, "Wait for us that we may acquire some of your light." It will be said, "Go back behind you and seek light." And a wall will be placed between them with a door, its interior containing mercy, but on the outside of it is torment.'),
  ('en.sahih', 57, 14, 'The hypocrites will call to the believers, "Were we not with you?" They will say, "Yes, but you afflicted yourselves and awaited [misfortune for us] and doubted, and wishful thinking deluded you until there came the command of Allah. And the Deceiver deceived you concerning Allah.'),
  ('en.sahih', 57, 15, 'So today no ransom will be taken from you or from those who disbelieved. Your refuge is the Fire. It is most worthy of you, and wretched is the destination.'),
  ('en.sahih', 57, 16, 'Has the time not come for those who have believed that their hearts should become humbly submissive at the remembrance of Allah and what has come down of the truth? And let them not be like those who were given the Scripture before, and a long period passed over them, so their hearts hardened; and many of them are defiantly disobedient.'),
  ('en.sahih', 57, 17, 'Know that Allah gives life to the earth after its lifelessness. We have made clear to you the signs; perhaps you will understand.'),
  ('en.sahih', 57, 18, 'Indeed, the men who practice charity and the women who practice charity and [they who] have loaned Allah a goodly loan - it will be multiplied for them, and they will have a noble reward.'),
  ('en.sahih', 57, 19, 'And those who have believed in Allah and His messengers - those are [in the ranks of] the supporters of truth and the martyrs, with their Lord. For them is their reward and their light. But those who have disbelieved and denied Our verses - those are the companions of Hellfire.'),
  ('en.sahih', 57, 20, 'Know that the life of this world is but amusement and diversion and adornment and boasting to one another and competition in increase of wealth and children - like the example of a rain whose [resulting] plant growth pleases the tillers; then it dries and you see it turned yellow; then it becomes [scattered] debris. And in the Hereafter is severe punishment and forgiveness from Allah and approval. And what is the worldly life except the enjoyment of delusion.'),
  ('en.sahih', 57, 21, 'Race toward forgiveness from your Lord and a Garden whose width is like the width of the heavens and earth, prepared for those who believed in Allah and His messengers. That is the bounty of Allah which He gives to whom He wills, and Allah is the possessor of great bounty.'),
  ('en.sahih', 57, 22, 'No disaster strikes upon the earth or among yourselves except that it is in a register before We bring it into being - indeed that, for Allah, is easy -'),
  ('en.sahih', 57, 23, 'In order that you not despair over what has eluded you and not exult [in pride] over what He has given you. And Allah does not like everyone self-deluded and boastful -'),
  ('en.sahih', 57, 24, '[Those] who are stingy and enjoin upon people stinginess. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy.'),
  ('en.sahih', 57, 25, 'We have already sent Our messengers with clear evidences and sent down with them the Scripture and the balance that the people may maintain [their affairs] in justice. And We sent down iron, wherein is great military might and benefits for the people, and so that Allah may make evident those who support Him and His messengers unseen. Indeed, Allah is Powerful and Exalted in Might.'),
  ('en.sahih', 57, 26, 'And We have already sent Noah and Abraham and placed in their descendants prophethood and scripture; and among them is he who is guided, but many of them are defiantly disobedient.'),
  ('en.sahih', 57, 27, 'Then We sent following their footsteps Our messengers and followed [them] with Jesus, the son of Mary, and gave him the Gospel. And We placed in the hearts of those who followed him compassion and mercy and monasticism, which they innovated; We did not prescribe it for them except [that they did so] seeking the approval of Allah. But they did not observe it with due observance. So We gave the ones who believed among them their reward, but many of them are defiantly disobedient.'),
  ('en.sahih', 57, 28, 'O you who have believed, fear Allah and believe in His Messenger; He will [then] give you a double portion of His mercy and make for you a light by which you will walk and forgive you; and Allah is Forgiving and Merciful.'),
  ('en.sahih', 57, 29, '[This is] so that the People of the Scripture may know that they are not able [to obtain] anything from the bounty of Allah and that [all] bounty is in the hand of Allah; He gives it to whom He wills. And Allah is the possessor of great bounty.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 57, 1, 'নভোমন্ডল ও ভূমন্ডলে যা কিছু আছে, সবাই আল্লাহর পবিত্রতা ঘোষণা করে। তিনি শক্তিধর; প্রজ্ঞাময়।'),
  ('bn.bengali', 57, 2, 'নভোমন্ডল ও ভূমন্ডলের রাজত্ব তাঁরই। তিনি জীবন দান করেন ও মৃত্যু ঘটান। তিনি সবকিছু করতে সক্ষম।'),
  ('bn.bengali', 57, 3, 'তিনিই প্রথম, তিনিই সর্বশেষ, তিনিই প্রকাশমান ও অপ্রকাশমান এবং তিনি সব বিষয়ে সম্যক পরিজ্ঞাত।'),
  ('bn.bengali', 57, 4, 'তিনি নভোমন্ডল ও ভূ-মন্ডল সৃষ্টি করেছেন ছয়দিনে, অতঃপর আরশের উপর সমাসীন হয়েছেন। তিনি জানেন যা ভূমিতে প্রবেশ করে ও যা ভূমি থেকে নির্গত হয় এবং যা আকাশ থেকে বর্ষিত হয় ও যা আকাশে উত্থিত হয়। তিনি তোমাদের সাথে আছেন তোমরা যেখানেই থাক। তোমরা যা কর, আল্লাহ তা দেখেন।'),
  ('bn.bengali', 57, 5, 'নভোমন্ডল ও ভূমন্ডলের রাজত্ব তাঁরই। সবকিছু তাঁরই দিকে প্রত্যাবর্তন করবে।'),
  ('bn.bengali', 57, 6, 'তিনি রাত্রিকে দিবসে প্রবিষ্ট করেন এবং দিবসকে প্রবিষ্ট করেন রাত্রিতে। তিনি অন্তরের বিষয়াদি সম্পর্কেও সম্যক জ্ঞাত।'),
  ('bn.bengali', 57, 7, 'তোমরা আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন কর এবং তিনি তোমাদেরকে যার উত্তরাধিকারী করেছেন, তা থেকে ব্যয় কর। অতএব, তোমাদের মধ্যে যারা বিশ্বাস স্থাপন করে ও ব্যয় করে, তাদের জন্যে রয়েছে মহাপুরস্কার।'),
  ('bn.bengali', 57, 8, 'তোমাদের কি হল যে, তোমরা আল্লাহর প্রতি বিশ্বাস স্থাপন করছ না, অথচ রসূল তোমাদেরকে তোমাদের পালনকর্তার প্রতি বিশ্বাস স্থাপন করার দাওয়াত দিচ্ছেন? আল্লাহ তো পূর্বেই তোমাদের অঙ্গীকার নিয়েছেন-যদি তোমরা বিশ্বাসী হও।'),
  ('bn.bengali', 57, 9, 'তিনিই তাঁর দাসের প্রতি প্রকাশ্য আয়াত অবতীর্ণ করেন, যাতে তোমাদেরকে অন্ধকার থেকে আলোকে আনয়ন করেন। নিশ্চয় আল্লাহ তোমাদের প্রতি করুণাময়, পরম দয়ালু।'),
  ('bn.bengali', 57, 10, 'তোমাদেরকে আল্লাহর পথে ব্যয় করতে কিসে বাধা দেয়, যখন আল্লাহই নভোমন্ডল ও ভূমন্ডলের উত্তরাধিকারী? তোমাদের মধ্যে যে মক্কা বিজয়ের পূর্বে ব্যয় করেছে ও জেহাদ করেছে, সে সমান নয়। এরূপ লোকদের মর্যদা বড় তাদের অপেক্ষা, যার পরে ব্যয় করেছে ও জেহাদ করেছে। তবে আল্লাহ উভয়কে কল্যাণের ওয়াদা দিয়েছেন। তোমরা যা কর, আল্লাহ সে সম্পর্কে সম্যক জ্ঞাত।'),
  ('bn.bengali', 57, 11, 'কে সেই ব্যক্তি, যে আল্লাহকে উত্তম ধার দিবে, এরপর তিনি তার জন্যে তা বহুগুণে বৃদ্ধি করবেন এবং তার জন্যে রয়েছে সম্মানিত পুরস্কার।'),
  ('bn.bengali', 57, 12, 'যেদিন আপনি দেখবেন ঈমানদার পুরুষ ও ঈমানদার নারীদেরকে, তাদের সম্মুখ ভাগে ও ডানপার্শ্বে তাদের জ্যোতি ছুটোছুটি করবে বলা হবেঃ আজ তোমাদের জন্যে সুসংবাদ জান্নাতের, যার তলদেশে নদী প্রবাহিত, তাতে তারা চিরকাল থাকবে। এটাই মহাসাফল্য।'),
  ('bn.bengali', 57, 13, 'যেদিন কপট বিশ্বাসী পুরুষ ও কপট বিশ্বাসিনী নারীরা মুমিনদেরকে বলবেঃ তোমরা আমাদের জন্যে অপেক্ষা কর, আমরাও কিছু আলো নিব তোমাদের জ্যোতি থেকে। বলা হবেঃ তোমরা পিছনে ফিরে যাও ও আলোর খোঁজ কর। অতঃপর উভয় দলের মাঝখানে খাড়া করা হবে একটি প্রাচীর, যার একটি দরজা হবে। তার অভ্যন্তরে থাকবে রহমত এবং বাইরে থাকবে আযাব।'),
  ('bn.bengali', 57, 14, 'তারা মুমিনদেরকে ডেকে বলবেঃ আমরা কি তোমাদের সাথে ছিলাম না? তারা বলবেঃ হঁ্যা কিন্তু তোমরা নিজেরাই নিজেদেরকে বিপদগ্রস্ত করেছ। প্রতীক্ষা করেছ, সন্দেহ পোষণ করেছ এবং অলীক আশার পেছনে বিভ্রান্ত হয়েছ, অবশেষে আল্লাহর আদেশ পৌঁছেছে। এই সবই তোমাদেরকে আল্লাহ সম্পর্কে প্রতারিত করেছে।'),
  ('bn.bengali', 57, 15, 'অতএব, আজ তোমাদের কাছ থেকে কোন মুক্তিপন গ্রহণ করা হবে না। এবং কাফেরদের কাছ থেকেও নয়। তোমাদের সবার আবাস্থল জাহান্নাম। সেটাই তোমাদের সঙ্গী। কতই না নিকৃষ্ট এই প্রত্যাবর্তন স্থল।'),
  ('bn.bengali', 57, 16, 'যারা মুমিন, তাদের জন্যে কি আল্লাহর স্মরণে এবং যে সত্য অবর্তীর্ণ হয়েছে, তার কারণে হৃদয় বিগলিত হওয়ার সময় আসেনি? তারা তাদের মত যেন না হয়, যাদেরকে পূর্বে কিতাব দেয়া হয়েছিল। তাদের উপর সুদীর্ঘকাল অতিক্রান্ত হয়েছে, অতঃপর তাদের অন্তঃকরণ কঠিন হয়ে গেছে। তাদের অধিকাংশই পাপাচারী।'),
  ('bn.bengali', 57, 17, 'তোমরা জেনে রাখ, আল্লাহই ভূ-ভাগকে তার মৃত্যুর পর পুনরুজ্জীবিত করেন। আমি পরিস্কারভাবে তোমাদের জন্যে আয়াতগুলো ব্যক্ত করেছি, যাতে তোমরা বোঝ।'),
  ('bn.bengali', 57, 18, 'নিশ্চয় দানশীল ব্যক্তি ও দানশীলা নারী, যারা আল্লাহকে উত্তমরূপে ধার দেয়, তাদেরকে দেয়া হবে বহুগুণ এবং তাদের জন্যে রয়েছে সম্মানজনক পুরস্কার।'),
  ('bn.bengali', 57, 19, 'আর যারা আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন করে তারাই তাদের পালনকর্তার কাছে সিদ্দীক ও শহীদ বলে বিবেচিত। তাদের জন্যে রয়েছে পুরস্কার ও জ্যোতি এবং যারা কাফের ও আমার নিদর্শন অস্বীকারকারী তারাই জাহান্নামের অধিবাসী হবে।'),
  ('bn.bengali', 57, 20, 'তোমরা জেনে রাখ, পার্থিব জীবন ক্রীড়া-কৌতুক, সাজ-সজ্জা, পারস্পরিক অহমিকা এবং ধন ও জনের প্রাচুর্য ব্যতীত আর কিছু নয়, যেমন এক বৃষ্টির অবস্থা, যার সবুজ ফসল কৃষকদেরকে চমৎকৃত করে, এরপর তা শুকিয়ে যায়, ফলে তুমি তাকে পীতবর্ণ দেখতে পাও, এরপর তা খড়কুটা হয়ে যায়। আর পরকালে আছে কঠিন শাস্তি এবং আল্লাহর ক্ষমা ও সন্তুষ্টি। পার্থিব জীবন প্রতারণার উপকরণ বৈ কিছু নয়।'),
  ('bn.bengali', 57, 21, 'তোমরা অগ্রে ধাবিত হও তোমাদের পালনকর্তার ক্ষমা ও সেই জান্নাতের দিকে, যা আকাশ ও পৃথিবীর মত প্রশস্ত। এটা প্রস্তুত করা হয়েছে আল্লাহ ও তাঁর রসূলগণের প্রতি বিশ্বাসস্থাপনকারীদের জন্যে। এটা আল্লাহর কৃপা, তিনি যাকে ইচ্ছা, এটা দান করেন। আল্লাহ মহান কৃপার অধিকারী।'),
  ('bn.bengali', 57, 22, 'পৃথিবীতে এবং ব্যক্তিগতভাবে তোমাদের উপর কোন বিপদ আসে না; কিন্তু তা জগত সৃষ্টির পূর্বেই কিতাবে লিপিবদ্ধ আছে। নিশ্চয় এটা আল্লাহর পক্ষে সহজ।'),
  ('bn.bengali', 57, 23, 'এটা এজন্যে বলা হয়, যাতে তোমরা যা হারাও তজ্জন্যে দুঃখিত না হও এবং তিনি তোমাদেরকে যা দিয়েছেন, তজ্জন্যে উল্লসিত না হও। আল্লাহ কোন উদ্ধত অহংকারীকে পছন্দ করেন না,'),
  ('bn.bengali', 57, 24, 'যারা কৃপণতা করে এবং মানুষকে কৃপণতার প্রতি উৎসাহ দেয়, যে মুখ ফিরিয়ে নেয়, তার জানা উচিত যে, আল্লাহ অভাবমুক্ত, প্রশংসিত।'),
  ('bn.bengali', 57, 25, 'আমি আমার রসূলগণকে সুস্পষ্ট নিদর্শনসহ প্রেরণ করেছি এবং তাঁদের সাথে অবতীর্ণ করেছি কিতাব ও ন্যায়নীতি, যাতে মানুষ ইনসাফ প্রতিষ্ঠা করে। আর আমি নাযিল করেছি লৌহ, যাতে আছে প্রচন্ড রণশক্তি এবং মানুষের বহুবিধ উপকার। এটা এজন্যে যে, আল্লাহ জেনে নিবেন কে না দেখে তাঁকে ও তাঁর রসূলগণকে সাহায্য করে। আল্লাহ শক্তিধর, পরাক্রমশালী।'),
  ('bn.bengali', 57, 26, 'আমি নূহ ও ইব্রাহীমকে রসূলরূপে প্রেরণ করেছি এবং তাদের বংশধরের মধ্যে নবুওয়ত ও কিতাব অব্যাহত রেখেছি। অতঃপর তাদের কতক সৎপথপ্রাপ্ত হয়েছে এবং অধিকাংশই হয়েছে পাপাচারী।'),
  ('bn.bengali', 57, 27, 'অতঃপর আমি তাদের পশ্চাতে প্রেরণ করেছি আমার রসূলগণকে এবং তাদের অনুগামী করেছি মরিয়ম তনয় ঈসাকে ও তাকে দিয়েছি ইঞ্জিল। আমি তার অনুসারীদের অন্তরে স্থাপন করেছি নম্রতা ও দয়া। আর বৈরাগ্য, সে তো তারা নিজেরাই উদ্ভাবন করেছে; আমি এটা তাদের উপর ফরজ করিনি; কিন্তু তারা আল্লাহর সন্তুষ্টি লাভের জন্যে এটা অবলম্বন করেছে। অতঃপর তারা যথাযথভাবে তা পালন করেনি। তাদের মধ্যে যারা বিশ্বাসী ছিল, আমি তাদেরকে তাদের প্রাপ্য পুরস্কার দিয়েছি। আর তাদের অধিকাংশই পাপাচারী।'),
  ('bn.bengali', 57, 28, 'মুমিনগণ, তোমরা আল্লাহকে ভয় কর এবং তাঁর রসূলের প্রতি বিশ্বাস স্থাপন কর। তিনি নিজে অনুগ্রহের দ্বিগুণ অংশ তোমাদেরকে দিবেন, তোমাদেরকে দিবেন জ্যোতি, যার সাহায্যে তোমরা চলবে এবং তোমাদেরকে ক্ষমা করবেন। আল্লাহ ক্ষমাশীল, দয়াময়।'),
  ('bn.bengali', 57, 29, 'যাতে কিতাবধারীরা জানে যে, আল্লাহর সামান্য অনুগ্রহের উপর ও তাদের কোন ক্ষমতা নেই, দয়া আল্লাহরই হাতে; তিনি যাকে ইচ্ছা, তা দান করেন। আল্লাহ মহা অনুগ্রহশীল।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 57, 1, 'All that is in the heavens and the earth glorifieth Allah; and He is the Mighty, the Wise.'),
  ('en.pickthall', 57, 2, 'His is the Sovereignty of the heavens and the earth; He quickeneth and He giveth death; and He is Able to do all things.'),
  ('en.pickthall', 57, 3, 'He is the First and the Last, and the Outward and the Inward; and He is Knower of all things.'),
  ('en.pickthall', 57, 4, 'He it is Who created the heavens and the earth in six Days; then He mounted the Throne. He knoweth all that entereth the earth and all that emergeth therefrom and all that cometh down from the sky and all that ascendeth therein; and He is with you wheresoever ye may be. And Allah is Seer of what ye do.'),
  ('en.pickthall', 57, 5, 'His is the Sovereignty of the heavens and the earth, and unto Allah (all) things are brought back.'),
  ('en.pickthall', 57, 6, 'He causeth the night to pass into the day, and He causeth the day to pass into the night, and He is knower of all that is in the breasts.'),
  ('en.pickthall', 57, 7, 'Believe in Allah and His messenger, and spend of that whereof He hath made you trustees; and such of you as believe and spend (aright), theirs will be a great reward.'),
  ('en.pickthall', 57, 8, 'What aileth you that ye believe not in Allah, when the messenger calleth you to believe in your Lord, and He hath already made a covenant with you, if ye are believers?'),
  ('en.pickthall', 57, 9, 'He it is Who sendeth down clear revelations unto His slave, that He may bring you forth from darkness unto light; and lo! for you, Allah is Full of Pity, Merciful.'),
  ('en.pickthall', 57, 10, 'And what aileth you that ye spend not in the way of Allah when unto Allah belongeth the inheritance of the heavens and the earth? Those who spent and fought before the victory are not upon a level (with the rest of you). Such are greater in rank than those who spent and fought afterwards. Unto each hath Allah promised good. And Allah is Informed of what ye do.'),
  ('en.pickthall', 57, 11, 'Who is he that will lend unto Allah a goodly loan, that He may double it for him and his may be a rich reward?'),
  ('en.pickthall', 57, 12, 'On the day when thou (Muhammad) wilt see the believers, men and women, their light shining forth before them and on their right hands, (and wilt hear it said unto them): Glad news for you this day: Gardens underneath which rivers flow, wherein ye are immortal. That is the supreme triumph.'),
  ('en.pickthall', 57, 13, 'On the day when the hypocritical men and the hypocritical women will say unto those who believe: Look on us that we may borrow from your light! it will be said: Go back and seek for light! Then there will separate them a wall wherein is a gate, the inner side whereof containeth mercy, while the outer side thereof is toward the doom.'),
  ('en.pickthall', 57, 14, 'They will cry unto them (saying): Were we not with you? They will say: Yea, verily; but ye tempted one another, and hesitated, and doubted, and vain desires beguiled you till the ordinance of Allah came to pass; and the deceiver deceived you concerning Allah;'),
  ('en.pickthall', 57, 15, 'So this day no ransom can be taken from you nor from those who disbelieved. Your home is the Fire; that is your patron, and a hapless journey\'s end.'),
  ('en.pickthall', 57, 16, 'Is not the time ripe for the hearts of those who believe to submit to Allah\'s reminder and to the truth which is revealed, that they become not as those who received the scripture of old but the term was prolonged for them and so their hearts were hardened, and many of them are evil-livers.'),
  ('en.pickthall', 57, 17, 'Know that Allah quickeneth the earth after its death. We have made clear Our revelations for you, that haply ye may understand.'),
  ('en.pickthall', 57, 18, 'Lo! those who give alms, both men and women, and lend unto Allah a goodly loan, it will be doubled for them, and theirs will be a rich reward.'),
  ('en.pickthall', 57, 19, 'And those who believe in Allah and His messengers, they are the loyal, and the martyrs are with their Lord; they have their reward and their light; while as for those who disbelieve and deny Our revelations, they are owners of hell-fire.'),
  ('en.pickthall', 57, 20, 'Know that the life of the world is only play, and idle talk, and pageantry, and boasting among you, and rivalry in respect of wealth and children; as the likeness of vegetation after rain, whereof the growth is pleasing to the husbandman, but afterward it drieth up and thou seest it turning yellow, then it becometh straw. And in the Hereafter there is grievous punishment, and (also) forgiveness from Allah and His good pleasure, whereas the life of the world is but matter of illusion.'),
  ('en.pickthall', 57, 21, 'Race one with another for forgiveness from your Lord and a Garden whereof the breadth is as the breadth of the heavens and the earth, which is in store for those who believe in Allah and His messengers. Such is the bounty of Allah, which He bestoweth upon whom He will, and Allah is of Infinite Bounty.'),
  ('en.pickthall', 57, 22, 'Naught of disaster befalleth in the earth or in yourselves but it is in a Book before we bring it into being - Lo! that is easy for Allah -'),
  ('en.pickthall', 57, 23, 'That ye grieve not for the sake of that which hath escaped you, nor yet exult because of that which hath been given. Allah loveth not all prideful boasters,'),
  ('en.pickthall', 57, 24, 'Who hoard and who enjoin upon the people avarice. And whosoever turneth away, still Allah is the Absolute, the Owner of Praise.'),
  ('en.pickthall', 57, 25, 'We verily sent Our messengers with clear proofs, and revealed with them the Scripture and the Balance, that mankind may observe right measure; and He revealed iron, wherein is mighty power and (many) uses for mankind, and that Allah may know him who helpeth Him and His messengers, though unseen. Lo! Allah is Strong, Almighty.'),
  ('en.pickthall', 57, 26, 'And We verily sent Noah and Abraham and placed the prophethood and the scripture among their seed, and among them there is he who goeth right, but many of them are evil-livers.'),
  ('en.pickthall', 57, 27, 'Then We caused Our messengers to follow in their footsteps; and We caused Jesus, son of Mary, to follow, and gave him the Gospel, and placed compassion and mercy in the hearts of those who followed him. But monasticism they invented - We ordained it not for them - only seeking Allah\'s pleasure, and they observed it not with right observance. So We give those of them who believe their reward, but many of them are evil-livers.'),
  ('en.pickthall', 57, 28, 'O ye who believe! Be mindful of your duty to Allah and put faith in His messenger. He will give you twofold of His mercy and will appoint for you a light wherein ye shall walk, and will forgive you. Allah is Forgiving, Merciful;'),
  ('en.pickthall', 57, 29, 'That the People of the Scripture may know that they control naught of the bounty of Allah, but that the bounty is in Allah\'s hand to give to whom He will. And Allah is of Infinite Bounty.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 57, 1, 'Whatever is in the heavens and on earth,- let it declare the Praises and Glory of Allah: for He is the Exalted in Might, the Wise.'),
  ('en.yusufali', 57, 2, 'To Him belongs the dominion of the heavens and the earth: It is He Who gives Life and Death; and He has Power over all things.'),
  ('en.yusufali', 57, 3, 'He is the First and the Last, the Evident and the Immanent: and He has full knowledge of all things.'),
  ('en.yusufali', 57, 4, 'He it is Who created the heavens and the earth in Six Days, and is moreover firmly established on the Throne (of Authority). He knows what enters within the earth and what comes forth out of it, what comes down from heaven and what mounts up to it. And He is with you wheresoever ye may be. And Allah sees well all that ye do.'),
  ('en.yusufali', 57, 5, 'To Him belongs the dominion of the heavens and the earth: and all affairs are referred back to Allah.'),
  ('en.yusufali', 57, 6, 'He merges Night into Day, and He merges Day into Night; and He has full knowledge of the secrets of (all) hearts.'),
  ('en.yusufali', 57, 7, 'Believe in Allah and His messenger, and spend (in charity) out of the (substance) whereof He has made you heirs. For, those of you who believe and spend (in charity),- for them is a great Reward.'),
  ('en.yusufali', 57, 8, 'What cause have ye why ye should not believe in Allah?- and the Messenger invites you to believe in your Lord, and has indeed taken your Covenant, if ye are men of Faith.'),
  ('en.yusufali', 57, 9, 'He is the One Who sends to His Servant Manifest Signs, that He may lead you from the depths of Darkness into the Light and verily Allah is to you most kind and Merciful.'),
  ('en.yusufali', 57, 10, 'And what cause have ye why ye should not spend in the cause of Allah?- For to Allah belongs the heritage of the heavens and the earth. Not equal among you are those who spent (freely) and fought, before the Victory, (with those who did so later). Those are higher in rank than those who spent (freely) and fought afterwards. But to all has Allah promised a goodly (reward). And Allah is well acquainted with all that ye do.'),
  ('en.yusufali', 57, 11, 'Who is he that will Loan to Allah a beautiful loan? for (Allah) will increase it manifold to his credit, and he will have (besides) a liberal Reward.'),
  ('en.yusufali', 57, 12, 'One Day shalt thou see the believing men and the believing women- how their Light runs forward before them and by their right hands: (their greeting will be): "Good News for you this Day! Gardens beneath which flow rivers! to dwell therein for aye! This is indeed the highest Achievement!"'),
  ('en.yusufali', 57, 13, 'One Day will the Hypocrites- men and women - say to the Believers: "Wait for us! Let us borrow (a Light) from your Light!" It will be said: "Turn ye back to your rear! then seek a Light (where ye can)!" So a wall will be put up betwixt them, with a gate therein. Within it will be Mercy throughout, and without it, all alongside, will be (Wrath and) Punishment!'),
  ('en.yusufali', 57, 14, '(Those without) will call out, "Were we not with you?" (The others) will reply, "True! but ye led yourselves into temptation; ye looked forward (to our ruin); ye doubted (Allah\'s Promise); and (your false) desires deceived you; until there issued the Command of Allah. And the Deceiver deceived you in respect of Allah.'),
  ('en.yusufali', 57, 15, '"This Day shall no ransom be accepted of you, nor of those who rejected Allah." Your abode is the Fire: that is the proper place to claim you: and an evil refuge it is!"'),
  ('en.yusufali', 57, 16, 'Has not the Time arrived for the Believers that their hearts in all humility should engage in the remembrance of Allah and of the Truth which has been revealed (to them), and that they should not become like those to whom was given Revelation aforetime, but long ages passed over them and their hearts grew hard? For many among them are rebellious transgressors.'),
  ('en.yusufali', 57, 17, 'Know ye (all) that Allah giveth life to the earth after its death! already have We shown the Signs plainly to you, that ye may learn wisdom.'),
  ('en.yusufali', 57, 18, 'For those who give in Charity, men and women, and loan to Allah a Beautiful Loan, it shall be increased manifold (to their credit), and they shall have (besides) a liberal reward.'),
  ('en.yusufali', 57, 19, 'And those who believe in Allah and His messengers- they are the Sincere (lovers of Truth), and the witnesses (who testify), in the eyes of their Lord: They shall have their Reward and their Light. But those who reject Allah and deny Our Signs,- they are the Companions of Hell-Fire.'),
  ('en.yusufali', 57, 20, 'Know ye (all), that the life of this world is but play and amusement, pomp and mutual boasting and multiplying, (in rivalry) among yourselves, riches and children. Here is a similitude: How rain and the growth which it brings forth, delight (the hearts of) the tillers; soon it withers; thou wilt see it grow yellow; then it becomes dry and crumbles away. But in the Hereafter is a Penalty severe (for the devotees of wrong). And Forgiveness from Allah and (His) Good Pleasure (for the devotees of Allah). And what is the life of this world, but goods and chattels of deception?'),
  ('en.yusufali', 57, 21, 'Be ye foremost (in seeking) Forgiveness from your Lord, and a Garden (of Bliss), the width whereof is as the width of heaven and earth, prepared for those who believe in Allah and His messengers: that is the Grace of Allah, which He bestows on whom he pleases: and Allah is the Lord of Grace abounding.'),
  ('en.yusufali', 57, 22, 'No misfortune can happen on earth or in your souls but is recorded in a decree before We bring it into existence: That is truly easy for Allah:'),
  ('en.yusufali', 57, 23, 'In order that ye may not despair over matters that pass you by, nor exult over favours bestowed upon you. For Allah loveth not any vainglorious boaster,-'),
  ('en.yusufali', 57, 24, 'Such persons as are covetous and commend covetousness to men. And if any turn back (from Allah\'s Way), verily Allah is Free of all Needs, Worthy of all Praise.'),
  ('en.yusufali', 57, 25, 'We sent aforetime our messengers with Clear Signs and sent down with them the Book and the Balance (of Right and Wrong), that men may stand forth in justice; and We sent down Iron, in which is (material for) mighty war, as well as many benefits for mankind, that Allah may test who it is that will help, Unseen, Him and His messengers: For Allah is Full of Strength, Exalted in Might (and able to enforce His Will).'),
  ('en.yusufali', 57, 26, 'And We sent Noah and Abraham, and established in their line Prophethood and Revelation: and some of them were on right guidance. But many of them became rebellious transgressors.'),
  ('en.yusufali', 57, 27, 'Then, in their wake, We followed them up with (others of) Our messengers: We sent after them Jesus the son of Mary, and bestowed on him the Gospel; and We ordained in the hearts of those who followed him Compassion and Mercy. But the Monasticism which they invented for themselves, We did not prescribe for them: (We commanded) only the seeking for the Good Pleasure of Allah; but that they did not foster as they should have done. Yet We bestowed, on those among them who believed, their (due) reward, but many of them are rebellious transgressors.'),
  ('en.yusufali', 57, 28, 'O ye that believe! Fear Allah, and believe in His Messenger, and He will bestow on you a double portion of His Mercy: He will provide for you a Light by which ye shall walk (straight in your path), and He will forgive you (your past): for Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 57, 29, 'That the People of the Book may know that they have no power whatever over the Grace of Allah, that (His) Grace is (entirely) in His Hand, to bestow it on whomsoever He wills. For Allah is the Lord of Grace abounding.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 57, 1, 'Sabbaha lillaahi maa fissamaawaati wal ardi wa Huwal \'Azeezul Hakeem'),
  ('en.transliteration', 57, 2, 'Lahoo mulkus samaawaati wal ardi yuhyee wa yumeetu wa Huwa \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 57, 3, 'Huwal Awwalu wal\'Aakhiru waz Zaahiru wal Baatinu wa huwa bikulli shai\'in Aleem'),
  ('en.transliteration', 57, 4, 'Huwal lazee khalaqas samaawaati wal arda fee sittati ayyaamin summas tawaa \'alal \'Arsh; ya\'lamu maa yaliju filardi wa maa yakhruju minhaa wa maa yanzilu minas samaaa\'i wa maa ya\'ruju feeha wa Huwa ma\'akum ayna maa kuntum; wallaahu bimaa ta\'maloona Baseer'),
  ('en.transliteration', 57, 5, 'Lahoo mulkus samaawaati wal ard; wa ilal laahi turja\'ul umoor'),
  ('en.transliteration', 57, 6, 'Yoolijul laila fin nahaari wa yoolijun nahaara fil lail; wa Huwa \'Aleemum bizaatis sudoor'),
  ('en.transliteration', 57, 7, 'Aaaminoo billaahi wa Rasoolihee wa anfiqoo mimmaa ja\'alakum mustakh lafeena feehi fallazeena aamanoo minkum wa anfaqoo lahum ajrun kabeer'),
  ('en.transliteration', 57, 8, 'Wa maa lakum laa tu\'minoona billaahi war Rasoolu yad\'ookum lituu\'minoo bi Rabbikum wa qad akhaza meesaaqakum in kuntum mu\'mineen'),
  ('en.transliteration', 57, 9, 'Huwal lazee yunazzilu \'alaa \'abdiheee Aayaatim baiyinaatil liyukhrijakum minaz zulumaati ilan noor; wa innal laaha bikum la Ra\'oofur Raheem'),
  ('en.transliteration', 57, 10, 'Wa maa lakum allaa tunfiqoo fee sabeelil laahi wa lillaahi meeraasus samaawaati wal-ard; laa yastawee minkum man anfaqa min qablil fat-hi wa qaatal; ulaaaika a\'zamu darajatam minal lazeena anfaqoo mim ba\'du wa qaataloo; wa kullanw wa\'adallaahul husnaa; wallaahu bimaa ta\'maloona Khabeer'),
  ('en.transliteration', 57, 11, 'man zal lazee yuqridul laaha qardan hasanan fa yudaa\'ifahoo lahoo wa lahooo ajrun kareem'),
  ('en.transliteration', 57, 12, 'Yawma taral mu\'mineena walmu\'minaati yas\'aa nooruhum baina aydeehim wa biaymaanihim bushraakumul yawma jannaatun tajree min tahtihal anhaaru khaalideena feeha; zaalika huwal fawzul \'azeem'),
  ('en.transliteration', 57, 13, 'Yawma yaqoolul munaa fiqoona walmunaafiqaatu lillazeena aamanun zuroonaa naqtabis min noorikum qeelarji\'oo waraaa\'akum faltamisoo nooran faduriba bainahum bisooril lahoo baab, baatinuhoo feehir rahmatu wa zaahiruhoo min qibalihi-\'azaab'),
  ('en.transliteration', 57, 14, 'Yunaadoonahum alam nakum ma\'akum qaaloo balaa wa laakinnakum fatantum anfusakum wa tarabbastum wartabtum wa gharratkumul amaaniyyu hatta jaaa\'a amrul laahi wa gharrakum billaahil gharoor'),
  ('en.transliteration', 57, 15, 'Fal Yawma laa yu\'khazu minkum fidyatunw wa laa minal lazeena kafaroo; maawaakumun Naaru hiya maw laakum wa bi\'sal maseer'),
  ('en.transliteration', 57, 16, 'Alam yaani laillzeena aamanooo an takhsha\'a quloo buhum lizikril laahi wa maa nazala minal haqqi wa laa yakoonoo kallazeena ootul Kitaaba min qablu fataala \'alaihimul amadu faqasat quloobuhum wa kaseerum minhum faasiqoon'),
  ('en.transliteration', 57, 17, 'I\'lamooo annal laaha yuhyil arda ba\'da mawtihaa; qad baiyannaa lakumul Aayaati la\'allakum ta\'qiloon'),
  ('en.transliteration', 57, 18, 'Innal mussaddiqeena wal mussaddiqaati wa aqradul laaha qardan hassanany yudaa\'afu lahum wa lahum ajrun kareem'),
  ('en.transliteration', 57, 19, 'Wallazeena aamanoo billaahi wa Rusuliheee ulaaa\'ika humus siddeeqoona wash shuhadaaa\'u \'inda Rabbihim lahum ajruhum wa nooruhum wallazeena kafaroo wa kazzaboo bi aayaatinaaa ulaaaika As haabul jaheem'),
  ('en.transliteration', 57, 20, 'I\'lamooo annamal hayaa tud dunyaa la\'ibunw wa lahwunw wa zeenatunw wa takaasurun bainakum wa takaasurn fil amwaali wal awlaad, kamasali ghaisin a\'jabal kuffaara nabaatuhoo summa yaheeju fataraahu musfaaran summa yakoonu hutaamaa; wa fil aakhirati \'azaabun shadeedunw wa magh firatum minal laahi wa ridwaan; wa mal haiyaa tuddun yaaa illaa mataa\'ul ghuroor'),
  ('en.transliteration', 57, 21, 'Saabiqooo ilaa maghfiratim mir Rabbikum wa jannatin \'arduhaa ka-\'ardis samaaa\'i wal ardi u\'iddat lillazeena aamanoo billaahi wa Rusulih; zaalika fadlul laahi yu\'teehi many yashaaa\'; wal laahu zul fadlil \'azeem'),
  ('en.transliteration', 57, 22, 'Maaa asaaba mim musee batin fil ardi wa laa feee anfusikum illaa fee kitaabim min qabli an nabra ahaa; innaa zaalika \'alal laahi yaseer'),
  ('en.transliteration', 57, 23, 'Likailaa taasaw \'alaa maa faatakum wa laa tafrahoo bimaaa aataakum; wallaahu laa yuhibbu kulla mukhtaalin fakhoor'),
  ('en.transliteration', 57, 24, 'Allazeeena yabkhaloona wa yaamuroonan naasa bil bukhl; wa many yatawalla fa innal laaha Huwal Ghaniyyul Hameed'),
  ('en.transliteration', 57, 25, 'Laqad arsalnaa Rusulanaa bilbaiyinaati wa anzalnaa ma\'ahumul Kitaaba wal Meezaana liyaqooman naasu bilqist, wa anzalnal hadeeda feehi baasun shadeedunw wa manaafi\'u linnaasi wa liya\'lamal laahu many yansuruhoo wa Rusulahoo bilghaib; innal laaha Qawiyyn \'Azeez'),
  ('en.transliteration', 57, 26, 'Wa laqad arsalnaa Noohanw wa Ibraaheema wa ja\'alnaa fee zurriyyatihiman nubuwwata wal Kitaaba faminhum muhtad; wa kaseerum minhum faasiqoon'),
  ('en.transliteration', 57, 27, 'Summa qaffainaa \'alaa aasaarihim bi Rusulinaa wa qaffainaa be \'Eesab ni Maryama wa aatainaahul Injeela wa ja\'alnaa fee quloobil lazeenat taba\' oohu raafatanw wa rahmatanw wa rahbaaniyyatanib tada\' oohaa maa katanaahaa \'alaihim illab tighaaa\'a ridwaanil laahi famaa ra\'awhaa haqqa ri\'aayatihaa fa aatainal lazeena aamanoo minhum ajrahum wa kaseerum minhum faasiqoon'),
  ('en.transliteration', 57, 28, 'Yaaa ayyuhal lazeena aamaanut taqullaaha wa aaminoo bi Rasoolihee yu\'tikum kiflaini mir rahmatihee wa yaj\'al lakum nooran tamshoona bihee wa yaghfir lakum; wallaahu Ghafoorur Raheem'),
  ('en.transliteration', 57, 29, 'Li\'alla ya\'lama Ahlul kitaabi allaa yaqdiroona \'alaa shai\'im min fadlil laahi wa annal fadla bi Yadil laahi u\'teehi many yashaaa\'; wallaahu Zul fadilil \'azeem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 57, 1, 'الله کی پاکیزگی بیان کرتے ہیں وہ جو آسمانوں اور زمین میں ہیں اور وہ زبردست حکمت والا ہے'),
  ('ur.ahmedali', 57, 2, 'آسمانوں اور زمین کی بادشاہت اسی کے یے ہے وہ زندہ کرتا ہے اور مارتا ہے اور وہ ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 57, 3, 'وہی سب سے پہلا اور سب سے پچھلا اور ظاہر اور پوشیدہ ہے اور وہی ہر چیز کو جاننے والا ہے'),
  ('ur.ahmedali', 57, 4, 'وہی ہے جس نے آسمانوں اور زمین کو چھ دن میں بنایا پھر وہ عرش پر قائم ہوا وہ جانتا ہے جو چیز زمین میں داخل ہوتی ہے اور جو اس سے نکلتی ہے اور جو آسمان سے اترتی ہے اور جو اس میں اوپر چڑھتی ہے اور وہ تمہارے ساتھ ہے جہاں کہیں تم ہو اور الله اس کو جو تم کرتے ہو دیکھتا ہے'),
  ('ur.ahmedali', 57, 5, 'آسمانوں اورزمین کی حکومت اسی کے لیے ہے اور سب امور الله ہی کی طرف لوٹائے جاتے ہیں'),
  ('ur.ahmedali', 57, 6, 'وہ رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کرتا ہے اوروہ سینوں کے بھید خوب جانتا ہے'),
  ('ur.ahmedali', 57, 7, 'الله اور اس کے رسول پر ایمان لاؤ اور اس میں سے خرچ کرو جس میں اس نے تمہیں پہلوں کا جانشین بنایا ہے پس جو لوگ تم میں سے ایمان لائے اور انہوں نے خرچ کیا ان کے لیے بڑا اجر ہے'),
  ('ur.ahmedali', 57, 8, 'اور تمہیں کیا ہوا جو الله پر ایمان نہیں لاتے اور رسول تمہیں تمہارے رب پرایمان لانے کے لیے بلا رہا ہے اور تم سے عہد بھی لے چکا ہے اگر تم ایمان لانے والے ہو'),
  ('ur.ahmedali', 57, 9, 'وہی ہے جو اپنے بندے پر کھلی کھلی آیتیں نازل کر رہا ہے تاکہ تمہیں اندھیروں میں سے نکال کر روشنی میں لائے اور بے شک الله تم پر بڑا مہربان نہایت رحم والا ہے'),
  ('ur.ahmedali', 57, 10, 'اور تمہیں کیا ہوگیا جو الله کی راہ میں خرچ نہیں کرتے حالانکہ آسمانوں اور زمین کا ورثہ تو الله ہی کے لیے ہے تم میں سے اور کوئی اس کے برابر ہو نہیں سکتا جس نے فتح مکہ سے پہلے خرچ کیا اور جہاد کیا یہ ہیں کہ الله کے نزدیک جن کا بڑا درجہ ہے ان لوگو ں پر ہے جنہوں نے بعد میں خرچ کیا اور جہاد کیا اور الله نے ہر ایک سے نیک جزا کا وعدہ کیا ہے اور الله تمہارے کاموں سے خبردار ہے'),
  ('ur.ahmedali', 57, 11, 'ایسا کون ہے جو الله کو اچھا قرض دے پھر وہ اس کو ا سکے لیے دگنا کر دے اوراس کے لیے عمدہ بدلہ ہے'),
  ('ur.ahmedali', 57, 12, 'جس دن آپ ایماندار مردوں اور عورتوں کو دیکھیں گے کہ ان کا نور ان کے سامنے اور ان کے داہنے دوڑ رہا ہوگا تمہیں آج ایسے باغوں کی خوشخبری ہے کہ ان کے نیچے نہریں چلتی ہیں وہ ان میں ہمیشہ رہیں گے یہی وہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 57, 13, 'جس دن منافق مرد اورمنافق عورتیں ان سے کہیں گے جو ایمان لائے ہیں کہ ہمارا انتظار کرو کہ ہم بھی تمہارے نور سے روشنی لے لیں کہا جائے گا اپنے پیچھے لوٹ جاؤ پھر روشنی تلاش کرو پس ان کے درمیان ایک دیوار کھڑی کر دی جائے گی جس میں ایک دروازہ ہو گا اس کے اندر تو رحمت ہو گی اور اس کے باہر کی طرف عذاب ہو گا'),
  ('ur.ahmedali', 57, 14, 'وہ انہیں پکاریں گے کیا ہم تمہارے ساتھ نہ تھے وہ کہیں گے کیوں نہیں لیکن تم نے اپنے آپ کو فتنہ میں ڈالا اور راہ دیکھتے اور شک کرتے رہے اور تمہیں آرزوؤں نے دھوکہ دیا یہاں تک کہ الله کا حکم آ پہنچا اور تمہیں الله کے بارے میں شیطان نے دھوکہ دیا'),
  ('ur.ahmedali', 57, 15, 'پس آج نہ تم سے کوئی تاوان لیا جائے گا اور نہ ان سے جنہوں نے انکار کیا تھا تمہارا سب کا ٹھکانا دوزخ ہے وہی تمہارا رفیق ہے اوربہت ہی بری جگہ ہے'),
  ('ur.ahmedali', 57, 16, 'کیا ایمان والوں کے لیے اس بات کا وقت نہیں آیا کہ ان کے دل الله کی نصیحت اور جو دین حق نازل ہوا ہے اس کے سامنے جھک جائیں اور ان لوگوں کی طرح نہ ہوجائیں جنہیں ان سے پہلے کتاب (آسمانی) ملی تھی پھر ان پر مدت لمبی ہو گئی تو ان کے دل سخت ہو گئے اور ان میں سے بہت سے نافرمان ہیں'),
  ('ur.ahmedali', 57, 17, 'اور جان لو کہ الله ہی زمین کو اس کے مرنے پیچھے زندہ کرتا ہے ہم نے تو تمہارے لیے کھول کھول کر نشانیاں بیان کر دی ہیں تاکہ تم سمجھو'),
  ('ur.ahmedali', 57, 18, 'بے شک خیرات کرنے والے مرد اور خیرات کرنے والی عورتیں اور جنہوں نے الله کو اچھا قرض دیا ان کے لیے دگنا کیا جائے گا اور انہیں عمدہ بدلہ ملے گا'),
  ('ur.ahmedali', 57, 19, 'اور جو لوگ الله اور اس کے رسولوں پر ایمان لائے وہی لوگ اپنے رب کے نزدیک صدیق اور شہید ہیں ان کے لیے ان کا اجر اور ان کی روشنی ملے گی اور جنہوں نے کفر کیا اورہماری آیتوں کو جھٹلایا یہی لوگ دوزخی ہیں'),
  ('ur.ahmedali', 57, 20, 'جان لو کہ یہ دنیا کی زندگی محض کھیل اور تماشا اور زیبائش اور ایک دوسرے پر آپس میں فخر کرنا اور ایک دوسرے پر مال اور اولاد میں زیادتی چاہنا ہے جیسے بارش کی حالت کہ اس کی سبزی نے کسانوں کو خوش کر دیا پھر وہ خشک ہو جاتی ہے تو تو اسے زرد شدہ دیکھتا ہے پھر وہ چورا چورا ہو جاتی ہے اور آخرت میں سخت عذاب ہے اور الله کی مغفرت اور اس کی خوشنودی ہے اور دنیاکی زندگی سوائے دھوکے کے اسباب کے اور کیا ہے'),
  ('ur.ahmedali', 57, 21, 'اپنے رب کی مغفرت کی طرف دوڑو اور جنت کی طرف جس کا عرض آسمان اور زمین کے عرض کے برابر ہے ان کے لیے تیار کی گئی ہے جو الله اور اس کے رسولوں پر ایمان لائے یہ الله کا فضل ہے وہ جسے چاہتا ہے دیتا ہے اور الله بڑے فضل والا ہے'),
  ('ur.ahmedali', 57, 22, 'جو کوئی مصیبت زمین پر یاخودتم پر پڑتی ہے وہ اس سے پیشتر کہ ہم اسے پیدا کریں کتاب میں لکھی ہوتی ہے بے شک یہ الله کے نزدیک آسان بات ہے'),
  ('ur.ahmedali', 57, 23, 'تاکہ جو چیز تمہارے ہاتھ سے جاتی رہے اس پر رنج نہ کرو اور جو تمہیں دے اس پر اتراؤ نہیں اور الله کسی اترانے والے شیخی خورے کو پسند نہیں کرتا'),
  ('ur.ahmedali', 57, 24, 'جو خود بھی بخل کرتے ہیں اور لوگوں کو بھی بخل کا حکم دیتے ہیں اور جو کوئی منہ موڑے تو الله بھی بے پرواہ خوبیوں والا ہے'),
  ('ur.ahmedali', 57, 25, 'البتہ ہم نے اپنے رسولوں کو نشانیاں دے کر بھیجا اور ان کے ہمراہ ہم نے کتاب اور ترازوئے (عدل) بھی بھیجی تاکہ لوگ انصاف کو قائم رکھیں اور ہم نے لوہا بھی اتارا جس میں سخت جنگ کے سامان اورلوگوں کے فائدے بھی ہیں اور تاکہ الله معلوم کرے کہ کون اس کی اور اس کے رسولوں کی غائبانہ مدد کرتا ہے بے شک الله بڑا زور آور غالب ہے'),
  ('ur.ahmedali', 57, 26, 'اور ہم نے نوح اور ابراھیم کو بھیجا تھا اور ہم نے ان دونوں کیاولاد میں نبوت اور کتاب رکھی تھی پس بعض تو ان میں راہِ راست پر رہے اور بہت سے ان میں سے نافرمان ہیں'),
  ('ur.ahmedali', 57, 27, 'پھر اس کے بعد ہم نے اپنے اور رسول بھیجے اور عیسیٰ ابن مریم کو بعد میں بھیجا اور اسے ہم نے انجیل دی اور اس کے ماننے والوں کے دلوں میں ہم نے نرمی اور مہربانی رکھ دی اور ترک دنیا جو انہوں نے خود ایجاد کی ہم نے وہ ان پرفرض نہیں کی تھی مگر انہوں نے رضائے الہیٰ حاصل کرنے کے لیے ایسا کیا پس اسے نباہ نہ سکے جیسے نباہنا چاہیئے تھا تو ہم نے انہیں جو ان میں سے ایمان لائے ان کا اجر دے دیا اور بہت سے تو ان میں بدکار ہی ہیں'),
  ('ur.ahmedali', 57, 28, 'اے ایمان والو الله سے ڈرو اور اس کے رسول پر ایمان لاؤ وہ تمہیں اپنی رحمت سے دوہرا حصہ دے گا اور تمہیں ایسا نورعطا کرے گا تم اس کے ذریعہ سے چلو اور تمہیں معاف کر دے گا اور الله بخشنے والا نہایت رحم ولا ہے'),
  ('ur.ahmedali', 57, 29, 'تاکہ اہلِ کتاب یہ نہ سمجھیں کہ (مسلمان) الله کے فضل میں سے کچھ بھی حاصل نہیں کر سکتے اوریہ کہ فضل تو الله ہی کے ہاتھ میں ہے جس کو چاہے دے اور الله بڑا فضل کرنے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 57, 1, 'Göklerde ve yerde olanlar Allah\'ı tesbih ederler. O güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 57, 2, 'Göklerin ve yerin hükümranlığı O\'nundur; diriltir, öldürür. O, her şeye Kadir\'dir.'),
  ('tr.diyanet', 57, 3, 'O her şeyden öncedir; kendisinden sonraya hiçbir şeyin kalmayacağı son\'dur; varlığı aşikardır; gerçek mahiyeti insan için gizlidir. O her şeyi bilir.'),
  ('tr.diyanet', 57, 4, 'Gökleri ve yeri altı günde yaratan, sonra arşa hükmeden, yere gireni ve ondan çıkanı, gökten ineni ve oraya yükseleni bilen O\'dur. Nerede olursanız olun, O, sizinle beraberdir. Allah yaptıklarınızı görür.'),
  ('tr.diyanet', 57, 5, 'Göklerin ve yerin hükümranlığı O\'nundur. Bütün işler Allah\'a döndürülür.'),
  ('tr.diyanet', 57, 6, 'Geceyi gündüze katar, gündüzü geceye katar; O kalblerde olanı bilendir.'),
  ('tr.diyanet', 57, 7, 'Ey insanlar! Allah\'a ve Peygamberine inanın; sizi varis kıldığı şeylerden sarfedin; aranızdan, inanıp da sarfeden kimselere büyük ecir vardır'),
  ('tr.diyanet', 57, 8, 'Peygamber sizi, Rabbinize inanmaya çağırdığı halde, Allah\'a niçin inanmazsınız? Hem O, sizden söz almıştı, inanmışlar iseniz; bu çağrıya koşun.'),
  ('tr.diyanet', 57, 9, 'Sizi karanlıklardan aydınlığa çıkarmak için kuluna, apaçık ayetler indiren O\'dur. Doğrusu Allah size karşı şefkatlidir, merhametlidir.'),
  ('tr.diyanet', 57, 10, 'Göklerin ve yerin mirasçısı Allah olduğu halde, Allah yolunda siz niçin sarf etmiyorsunuz? İçinizden Mekke\'nin fethinden önce sarfeden ve savaşan kimseler, daha sonra sarfedip savaşan kimselerle bir değildirler, öncekiler daha üstün derecededirler. Allah, hepsine cenneti vadetmiştir. Allah, işlediklerinizden haberdardır.'),
  ('tr.diyanet', 57, 11, 'Allah\'a kim güzel bir ödünç takdiminde bulunursa, Allah karşılığını kat kat verir, ona cömertçe verilecek bir ecir de vardır.'),
  ('tr.diyanet', 57, 12, 'İnanmış erkek ve kadınları, defterleri sağdan verilmiş ve ışıkları önlerinde olarak giderken gördüğün gün onlara şöyle denecektir: "Müjde; bugün içlerinden ırmaklar akan, içinde temelli kalacağınız cennetler sizindir." İşte bu büyük kurtuluştur.'),
  ('tr.diyanet', 57, 13, 'İkiyüzlü erkek ve kadınlar müminlere: "Bizi de gözetin; ışığınızdan faydalanalım" dedikleri gün, onlara: "Ardınıza dönün de ışık arayın" denir; inananlarla ikiyüzlüler arasına, kapısının içinde rahmet ve dışında azap olan bir sur çekilir.'),
  ('tr.diyanet', 57, 14, 'İkiyüzlüler, inananlara: "Biz sizinle beraber değil miydik" diye seslenirler. Onlar: "Evet öyle; fakat sizler kendinizi aldattınız, bize pusu kurdunuz, Allah\'ın buyruğu gelene kadar dinde şüpheye düştünüz; sizi kuruntular aldattı; sizi şeytanlar Allah\'a karşı da ayarttı."'),
  ('tr.diyanet', 57, 15, 'Bugün sizden ve inkar edenlerden fidye kabul edilmez; varacağınız yer ateştir, layığınız orasıdır; ne kötü bir dönüştür!'),
  ('tr.diyanet', 57, 16, 'İnananların gönüllerinin Allah\'ı anması ve O\'ndan inen gerçeğe içten bağlanması zamanı daha gelmedi mi? Onlar, daha önce kendilerine kitap verilenler gibi olmasınlar; onların üzerinden uzun zaman geçti de kalbleri katılaştı; çoğu, yoldan çıkmış kimselerdir.'),
  ('tr.diyanet', 57, 17, 'Allah\'ın, yeryüzünü ölümünden sonra dirilttiğini bilin; size, akledesiniz diye açık açık deliller anlattık.'),
  ('tr.diyanet', 57, 18, 'Doğrusu, sadaka veren erkek ve kadınlara, Allah\'a güzel bir takdimde bulunanlara kat kat karşılık verilir; onlara cömertçe verilecek bir ecir vardır.'),
  ('tr.diyanet', 57, 19, 'Allah\'a ve peygamberlerine inananlara, dosdoğru olanlara ve Allah yolunda şehit düşenlere, işte onlara, Rableri katında nur ve ecir vardır. İnkar edip ayetlerimizi yalanlayanlar, işte onlar da, cehennemlik olanlardır.'),
  ('tr.diyanet', 57, 20, 'Bilin ki, dünya hayatı oyun, oyalanma, süslenme, aranızda övünme ve daha çok mal ve çocuk sahibi olmaktan ibarettir. Bu, yağmurun bitirdiği, ekicilerin de hoşuna giden bir bitkiye benzer; sonra kurur, sapsarı olduğu görülür, sonra çerçöp olur. Ahirette çetin azap da vardır. Allah\'ın hoşnudluğu ve bağışlaması da vardır; dünya hayatı ise sadece aldatıcı bir geçinmedir.'),
  ('tr.diyanet', 57, 21, 'Ey İnsanlar! Rabbiniz tarafından bağışlanmaya, Allah\'a ve Peygamberine inananlar için hazırlanmış, genişliği yerle göğün genişliği kadar olan cennete koşusun; bu Allah\'ın dilediğine verdiği lütfudur. Allah, büyük lütuf sahibidir.'),
  ('tr.diyanet', 57, 22, 'Yeryüzüne ve sizin başınıza gelen herhangi bir musibet yoktur ki biz onu yaratmadan önce o, Kitap\'da bulunmasın. Doğrusu bu Allah\'a kolaydır.'),
  ('tr.diyanet', 57, 23, 'Bu, kaybettiğinize üzülmemeniz ve Allah\'ın size verdiği nimetlerle şımarmamanız içindir. Allah, kendini beğenip öğünen hiç kimseyi sevmez;'),
  ('tr.diyanet', 57, 24, 'Bunlar cimrilik ederler ve insanlara da cimrilik yapmalarını söylerler. Allah\'ın buyruğundan kim yüz çevirirse bilsin ki, Allah şüphesiz müstağni ve övülmeğe layık olandır.'),
  ('tr.diyanet', 57, 25, 'And olsun ki peygamberlerimizi belgelerle gönderdik; insanların doğru (adaletli) hareket etmeleri için peygamberlere kitap ve ölçü indirdik; pek sert olan ve insanlara birçok faydası bulunan demiri de indirdik. Bu, Allah\'ın dinine ve peygamberlerine görmeksizin yardım edenleri meydana çıkarması içindir. Doğrusu Allah kuvvetlidir, güçlüdür.'),
  ('tr.diyanet', 57, 26, 'And olsun ki Nuh\'u ve İbrahim\'i Biz gönderdik; ikisinin soyundan gelenlere peygamberlik ve kitap verdik; soylarından gelenlerin kimi doğru yoldadır, birçoğu da yoldan çıkmıştır.'),
  ('tr.diyanet', 57, 27, 'Onların izleri üzerinden peygamberlerimizi ard arda gönderdik; Meryem oğlu İsa\'yı da ardlarından gönderdik ve ona İncil\'i verdik; ona uyanların gönüllerine şefkat ve merhamet duyguları koyduk; üzerlerine bizim gerekli kılmadığımız fakat kendilerinin güya Allah\'ın rızasını kazanmak için ortaya attıkları ruhbaniyete bile gereği gibi riayet etmediler; içlerinde inanmış olan kimselere ecirlerini verdik; ama çoğu yoldan çıkmışlardır.'),
  ('tr.diyanet', 57, 28, 'Ey inananlar! Allah\'tan sakının, Peygamberine inanın ki, Allah size rahmetini iki kat versin; size ışığında yürüyeceğiniz bir ışık var etsin; sizi bağışlasın; Allah bağışlayandır, acıyandır.'),
  ('tr.diyanet', 57, 29, 'Kitap ehli bilsinler ki, Allah\'ın lütfundan hiçbir şey elde edemezler (bu lütfa malik değillerdir); lütuf Allah\'ın elindedir, onu dilediğine verir; Allah büyük lütuf sahibidir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 57, 1, 'Semua yang berada di langit dan yang berada di bumi bertasbih kepada Allah (menyatakan kebesaran Allah). Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 57, 2, 'Kepunyaan-Nya-lah kerajaan langit dan bumi, Dia menghidupkan dan mematikan, dan Dia Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 57, 3, 'Dialah Yang Awal dan Yang Akhir Yang Zhahir dan Yang Bathin; dan Dia Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 57, 4, 'Dialah yang menciptakan langit dan bumi dalam enam masa: Kemudian Dia bersemayam di atas \'Arsy. Dia mengetahui apa yang masuk ke dalam bumi dan apa yang keluar daripadanya dan apa yang turun dari langit dan apa yang naik kepada-Nya. Dan Dia bersama kamu di mana saja kamu berada. Dan Allah Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 57, 5, 'Kepunyaan-Nya-lah kerajaan langit dan bumi. Dan kepada Allah-lah dikembalikan segala urusan.'),
  ('id.indonesian', 57, 6, 'Dialah yang memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam. Dan Dia Maha Mengetahui segala isi hati.'),
  ('id.indonesian', 57, 7, 'Berimanlah kamu kepada Allah dan Rasul-Nya dan nafkahkanlah sebagian dari hartamu yang Allah telah menjadikan kamu menguasainya. Maka orang-orang yang beriman di antara kamu dan menafkahkan (sebagian) dari hartanya memperoleh pahala yang besar.'),
  ('id.indonesian', 57, 8, 'Dan mengapa kamu tidak beriman kepada Allah padahal Rasul menyeru kamu supaya kamu beriman kepada Tuhanmu. Dan sesungguhnya Dia telah mengambil perjanjianmu jika kamu adalah orang-orang yang beriman.'),
  ('id.indonesian', 57, 9, 'Dialah yang menurunkan kepada hamba-Nya ayat-ayat yang terang (Al-Quran) supaya Dia mengeluarkan kamu dari kegelapan kepada cahaya. Dan sesungguhnya Allah benar-benar Maha Penyantun lagi Maha Penyayang terhadapmu.'),
  ('id.indonesian', 57, 10, 'Dan mengapa kamu tidak menafkahkan (sebagian hartamu) pada jalan Allah, padahal Allah-lah yang mempusakai (mempunyai) langit dan bumi? Tidak sama di antara kamu orang yang menafkahkan (hartanya) dan berperang sebelum penaklukan (Mekah). Mereka lebih tingi derajatnya daripada orang-orang yang menafkahkan (hartanya) dan berperang sesudah itu. Allah menjanjikan kepada masing-masing mereka (balasan) yang lebih baik. Dan Allah mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 57, 11, 'Siapakah yang mau meminjamkan kepada Allah pinjaman yang baik, maka Allah akan melipat-gandakan (balasan) pinjaman itu untuknya, dan dia akan memperoleh pahala yang banyak.'),
  ('id.indonesian', 57, 12, '(yaitu) pada hari ketika kamu melihat orang mukmin laki-laki dan perempuan, sedang cahaya mereka bersinar di hadapan dan di sebelah kanan mereka, (dikatakan kepada mereka): "Pada hari ini ada berita gembira untukmu, (yaitu) surga yang mengalir di bawahnya sungai-sungai, yang kamu kekal di dalamnya. Itulah keberuntungan yang besar".'),
  ('id.indonesian', 57, 13, 'Pada hari ketika orang-orang munafik laki-laki dan perempuan berkata kepada orang-orang yang beriman: "Tunggulah kami supaya kami dapat mengambil sebahagian dari cahayamu". Dikatakan (kepada mereka): "Kembalilah kamu ke belakang dan carilah sendiri cahaya (untukmu)". Lalu diadakan di antara mereka dinding yang mempunyai pintu. Di sebelah dalamnya ada rahmat dan di sebelah luarnya dari situ ada siksa.'),
  ('id.indonesian', 57, 14, 'Orang-orang munafik itu memanggil mereka (orang-orang mukmin) seraya berkata: "Bukankah kami dahulu bersama-sama dengan kamu?" Mereka menjawab: "Benar, tetapi kamu mencelakakan dirimu sendiri dan menunggu (kehancuran kami) dan kamu ragu-ragu serta ditipu oleh angan-angan kosong sehingga datanglah ketetapan Allah; dan kamu telah ditipu terhadap Allah oleh (syaitan) yang amat penipu.'),
  ('id.indonesian', 57, 15, 'Maka pada hari ini tidak diterima tebusan dari kamu dan tidak pula dari orang-orang kafir. Tempat kamu ialah neraka. Dialah tempat berlindungmu. Dan dia adalah sejahat-jahat tempat kembali".'),
  ('id.indonesian', 57, 16, 'Belumkah datang waktunya bagi orang-orang yang beriman, untuk tunduk hati mereka mengingat Allah dan kepada kebenaran yang telah turun (kepada mereka), dan janganlah mereka seperti orang-orang yang sebelumnya telah diturunkan Al Kitab kepadanya, kemudian berlalulah masa yang panjang atas mereka lalu hati mereka menjadi keras. Dan kebanyakan di antara mereka adalah orang-orang yang fasik.'),
  ('id.indonesian', 57, 17, 'Ketahuilah olehmu bahwa sesungguhnya Allah menghidupkan bumi sesudah matinya. Sesungguhnya Kami telah menjelaskan kepadamu tanda-tanda kebesaran (Kami) supaya kamu memikirkannya.'),
  ('id.indonesian', 57, 18, 'Sesungguhnya orang-orang yang membenarkan (Allah dan Rasul-Nya) baik laki-laki maupun perempuan dan meminjamkan kepada Allah pinjaman yang baik, niscaya akan dilipatgandakan (pembayarannya) kepada mereka; dan bagi mereka pahala yang banyak.'),
  ('id.indonesian', 57, 19, 'Dan orang-orang yang beriman kepada Allah dan Rasul-Nya, mereka itu orang-orang Shiddiqien dan orang-orang yang menjadi saksi di sisi Tuhan mereka. Bagi mereka pahala dan cahaya mereka. Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni-penghuni neraka.'),
  ('id.indonesian', 57, 20, 'Ketahuilah, bahwa sesungguhnya kehidupan dunia ini hanyalah permainan dan suatu yang melalaikan, perhiasan dan bermegah-megah antara kamu serta berbangga-banggaan tentang banyaknya harta dan anak, seperti hujan yang tanam-tanamannya mengagumkan para petani; kemudian tanaman itu menjadi kering dan kamu lihat warnanya kuning kemudian menjadi hancur. Dan di akhirat (nanti) ada azab yang keras dan ampunan dari Allah serta keridhaan-Nya. Dan kehidupan dunia ini tidak lain hanyalah kesenangan yang menipu.'),
  ('id.indonesian', 57, 21, 'Berlomba-lombalah kamu kepada (mendapatkan) ampunan dari Tuhanmu dan surga yang luasnya seluas langit dan bumi, yang disediakan bagi orang-orang yang beriman kepada Allah dan Rasul-rasul-Nya. Itulah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya. Dan Allah mempunyai karunia yang besar.'),
  ('id.indonesian', 57, 22, 'Tiada suatu bencanapun yang menimpa di bumi dan (tidak pula) pada dirimu sendiri melainkan telah tertulis dalam kitab (Lauhul Mahfuzh) sebelum Kami menciptakannya. Sesungguhnya yang demikian itu adalah mudah bagi Allah.'),
  ('id.indonesian', 57, 23, '(Kami jelaskan yang demikian itu) supaya kamu jangan berduka cita terhadap apa yang luput dari kamu, dan supaya kamu jangan terlalu gembira terhadap apa yang diberikan-Nya kepadamu. Dan Allah tidak menyukai setiap orang yang sombong lagi membanggakan diri,'),
  ('id.indonesian', 57, 24, '(yaitu) orang-orang yang kikir dan menyuruh manusia berbuat kikir. Dan barangsiapa yang berpaling (dari perintah-perintah Allah) maka sesungguhnya Allah Dialah Yang Maha Kaya lagi Maha Terpuji.'),
  ('id.indonesian', 57, 25, 'Sesungguhnya Kami telah mengutus rasul-rasul Kami dengan membawa bukti-bukti yang nyata dan telah Kami turunkan bersama mereka Al Kitab dan neraca (keadilan) supaya manusia dapat melaksanakan keadilan. Dan Kami ciptakan besi yang padanya terdapat kekuatan yang hebat dan berbagai manfaat bagi manusia, (supaya mereka mempergunakan besi itu) dan supaya Allah mengetahui siapa yang menolong (agama)Nya dan rasul-rasul-Nya padahal Allah tidak dilihatnya. Sesungguhnya Allah Maha Kuat lagi Maha Perkasa.'),
  ('id.indonesian', 57, 26, 'Dan sesungguhnya Kami telah mengutus Nuh dan Ibrahim dan Kami jadikan kepada keturunan keduanya kenabian dan Al Kitab, maka di antara mereka ada yang menerima petunjuk dan banyak di antara mereka fasik.'),
  ('id.indonesian', 57, 27, 'Kemudian Kami iringi di belakang mereka dengan rasul-rasul Kami dan Kami iringi (pula) dengan Isa putra Maryam; dan Kami berikan kepadanya Injil dan Kami jadikan dalam hati orang-orang yang mengikutinya rasa santun dan kasih sayang. Dan mereka mengada-adakan rahbaniyyah padahal kami tidak mewajibkannya kepada mereka tetapi (mereka sendirilah yang mengada-adakannya) untuk mencari keridhaan Allah, lalu mereka tidak memeliharanya dengan pemeliharaan yang semestinya. Maka Kami berikan kepada orang-orang yang beriman di antara mereka pahalanya dan banyak di antara mereka orang-orang fasik.'),
  ('id.indonesian', 57, 28, 'Hai orang-orang yang beriman (kepada para rasul), bertakwalah kepada Allah dan berimanlah kepada Rasul-Nya, niscaya Allah memberikan rahmat-Nya kepadamu dua bagian, dan menjadikan untukmu cahaya yang dengan cahaya itu kamu dapat berjalan dan Dia mengampuni kamu. Dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 57, 29, '(Kami terangkan yang demikian itu) supaya ahli Kitab mengetahui bahwa mereka tiada mendapat sedikitpun akan karunia Allah (jika mereka tidak beriman kepada Muhammad), dan bahwasanya karunia itu adalah di tangan Allah. Dia berikan karunia itu kepada siapa yang dikehendaki-Nya. Dan Allah mempunyai karunia yang besar.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 58, 1, 'Certainly has Allah heard the speech of the one who argues with you, [O Muhammad], concerning her husband and directs her complaint to Allah. And Allah hears your dialogue; indeed, Allah is Hearing and Seeing.'),
  ('en.sahih', 58, 2, 'Those who pronounce thihar among you [to separate] from their wives - they are not [consequently] their mothers. Their mothers are none but those who gave birth to them. And indeed, they are saying an objectionable statement and a falsehood. But indeed, Allah is Pardoning and Forgiving.'),
  ('en.sahih', 58, 3, 'And those who pronounce thihar from their wives and then [wish to] go back on what they said - then [there must be] the freeing of a slave before they touch one another. That is what you are admonished thereby; and Allah is Acquainted with what you do.'),
  ('en.sahih', 58, 4, 'And he who does not find [a slave] - then a fast for two months consecutively before they touch one another; and he who is unable - then the feeding of sixty poor persons. That is for you to believe [completely] in Allah and His Messenger; and those are the limits [set by] Allah. And for the disbelievers is a painful punishment.'),
  ('en.sahih', 58, 5, 'Indeed, those who oppose Allah and His Messenger are abased as those before them were abased. And We have certainly sent down verses of clear evidence. And for the disbelievers is a humiliating punishment.'),
  ('en.sahih', 58, 6, 'On the Day when Allah will resurrect them all and inform them of what they did. Allah had enumerated it, while they forgot it; and Allah is, over all things, Witness.'),
  ('en.sahih', 58, 7, 'Have you not considered that Allah knows what is in the heavens and what is on the earth? There is in no private conversation three but that He is the fourth of them, nor are there five but that He is the sixth of them - and no less than that and no more except that He is with them [in knowledge] wherever they are. Then He will inform them of what they did, on the Day of Resurrection. Indeed Allah is, of all things, Knowing.'),
  ('en.sahih', 58, 8, 'Have you not considered those who were forbidden from private conversation, then they return to that which they were forbidden and converse among themselves about sin and aggression and disobedience to the Messenger? And when they come to you, they greet you with that [word] by which Allah does not greet you and say among themselves, "Why does Allah not punish us for what we say?" Sufficient for them is Hell, which they will [enter to] burn, and wretched is the destination.'),
  ('en.sahih', 58, 9, 'O you who have believed, when you converse privately, do not converse about sin and aggression and disobedience to the Messenger but converse about righteousness and piety. And fear Allah, to whom you will be gathered.'),
  ('en.sahih', 58, 10, 'Private conversation is only from Satan that he may grieve those who have believed, but he will not harm them at all except by permission of Allah. And upon Allah let the believers rely.'),
  ('en.sahih', 58, 11, 'O you who have believed, when you are told, "Space yourselves" in assemblies, then make space; Allah will make space for you. And when you are told, "Arise," then arise; Allah will raise those who have believed among you and those who were given knowledge, by degrees. And Allah is Acquainted with what you do.'),
  ('en.sahih', 58, 12, 'O you who have believed, when you [wish to] privately consult the Messenger, present before your consultation a charity. That is better for you and purer. But if you find not [the means] - then indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 58, 13, 'Have you feared to present before your consultation charities? Then when you do not and Allah has forgiven you, then [at least] establish prayer and give zakah and obey Allah and His Messenger. And Allah is Acquainted with what you do.'),
  ('en.sahih', 58, 14, 'Have you not considered those who make allies of a people with whom Allah has become angry? They are neither of you nor of them, and they swear to untruth while they know [they are lying].'),
  ('en.sahih', 58, 15, 'Allah has prepared for them a severe punishment. Indeed, it was evil that they were doing.'),
  ('en.sahih', 58, 16, 'They took their [false] oaths as a cover, so they averted [people] from the way of Allah, and for them is a humiliating punishment.'),
  ('en.sahih', 58, 17, 'Never will their wealth or their children avail them against Allah at all. Those are the companions of the Fire; they will abide therein eternally'),
  ('en.sahih', 58, 18, 'On the Day Allah will resurrect them all, and they will swear to Him as they swear to you and think that they are [standing] on something. Unquestionably, it is they who are the liars.'),
  ('en.sahih', 58, 19, 'Satan has overcome them and made them forget the remembrance of Allah. Those are the party of Satan. Unquestionably, the party of Satan - they will be the losers.'),
  ('en.sahih', 58, 20, 'Indeed, the ones who oppose Allah and His Messenger - those will be among the most humbled.'),
  ('en.sahih', 58, 21, 'Allah has written, "I will surely overcome, I and My messengers." Indeed, Allah is Powerful and Exalted in Might.'),
  ('en.sahih', 58, 22, 'You will not find a people who believe in Allah and the Last Day having affection for those who oppose Allah and His Messenger, even if they were their fathers or their sons or their brothers or their kindred. Those - He has decreed within their hearts faith and supported them with spirit from Him. And We will admit them to gardens beneath which rivers flow, wherein they abide eternally. Allah is pleased with them, and they are pleased with Him - those are the party of Allah. Unquestionably, the party of Allah - they are the successful.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 58, 1, 'যে নারী তার স্বামীর বিষয়ে আপনার সাথে বাদানুবাদ করছে এবং অভিযোগ পেশ করছে আল্লাহর দরবারে, আল্লাহ তার কথা শুনেছেন। আল্লাহ আপনাদের উভয়ের কথাবার্তা শুনেন। নিশ্চয় আল্লাহ সবকিছু শুনেন, সবকিছু দেখেন।'),
  ('bn.bengali', 58, 2, 'তোমাদের মধ্যে যারা তাদের স্ত্রীগণকে মাতা বলে ফেলে, তাদের স্ত্রীগণ তাদের মাতা নয়। তাদের মাতা কেবল তারাই, যারা তাদেরকে জন্মদান করেছে। তারা তো অসমীচীন ও ভিত্তিহীন কথাই বলে। নিশ্চয় আল্লাহ মার্জনাকারী, ক্ষমাশীল।'),
  ('bn.bengali', 58, 3, 'যারা তাদের স্ত্রীগণকে মাতা বলে ফেলে, অতঃপর নিজেদের উক্তি প্রত্যাহার করে, তাদের কাফফারা এই একে অপরকে স্পর্শ করার পূর্বে একটি দাসকে মুক্তি দিবে। এটা তোমাদের জন্যে উপদেশ হবে। আল্লাহ খবর রাখেন তোমরা যা কর।'),
  ('bn.bengali', 58, 4, 'যার এ সামর্থ্য নেই, সে একে অপরকে স্পর্শ করার পূর্বে একাদিক্রমে দুই মাস রোযা রাখবে। যে এতেও অক্ষম হয় সে ষাট জন মিসকীনকে আহার করাবে। এটা এজন্যে, যাতে তোমরা আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন কর। এগুলো আল্লাহর নির্ধারিত শাস্তি। আর কাফেরদের জন্যে রয়েছে যন্ত্রণা দায়ক আযাব।'),
  ('bn.bengali', 58, 5, 'যারা আল্লাহর তাঁর রসূলের বিরুদ্ধাচরণ করে, তারা অপদস্থ হয়েছে, যেমন অপদস্থ হয়েছে তাদের পূর্ববর্তীরা। আমি সুস্পষ্ট আয়াতসমূহ নাযিল করেছি। আর কাফেরদের জন্যে রয়েছে অপমানজনক শাস্তি।'),
  ('bn.bengali', 58, 6, 'সেদিন স্মরণীয়; যেদিন আল্লাহ তাদের সকলকে পুনরুত্থিত করবেন, অতঃপর তাদেরকে জানিয়ে দিবেন যা তারা করত। আল্লাহ তার হিসাব রেখেছেন, আর তারা তা ভুলে গেছে। আল্লাহর সামনে উপস্থিত আছে সব বস্তুই।'),
  ('bn.bengali', 58, 7, 'আপনি কি ভেবে দেখেননি যে, নভোমন্ডল ও ভূমন্ডলে যা কিছু আছে, আল্লাহ তা জানেন। তিন ব্যক্তির এমন কোন পরামর্শ হয় না যাতে তিনি চতুর্থ না থাকেন এবং পাঁচ জনেরও হয় না, যাতে তিনি ষষ্ঠ না থাকেন তারা এতদপেক্ষা কম হোক বা বেশী হোক তারা যেখানেই থাকুক না কেন তিনি তাদের সাথে আছেন, তারা যা করে, তিনি কেয়ামতের দিন তা তাদেরকে জানিয়ে দিবেন। নিশ্চয় আল্লাহ সর্ববিষয়ে সম্যক জ্ঞাত।'),
  ('bn.bengali', 58, 8, 'আপনি কি ভেবে দেখেননি, যাদেরকে কানাঘুষা করতে নিষেধ করা হয়েছিল অতঃপর তারা নিষিদ্ধ কাজেরই পুনরাবৃত্তি করে এবং পাপাচার, সীমালংঘন এবং রসূলের অবাধ্যতার বিষয়েই কানাঘুষা করে। তারা যখন আপনার কাছে আসে, তখন আপনাকে এমন ভাষায় সালাম করে, যদ্দ্বারা আল্লাহ আপনাকে সালাম করেননি। তারা মনে মনে বলেঃ আমরা যা বলি, তজ্জন্যে আল্লাহ আমাদেরকে শাস্তি দেন না কেন? জাহান্নামই তাদের জন্যে যথেষ্ট। তারা তাতে প্রবেশ করবে। কতই না নিকৃষ্ট সেই জায়গা।'),
  ('bn.bengali', 58, 9, 'মুমিনগণ, তোমরা যখন কানাকানি কর, তখন পাপাচার, সীমালংঘন ও রসূলের অবাধ্যতার বিষয়ে কানাকানি করো না বরং অনুগ্রহ ও খোদাভীতির ব্যাপারে কানাকানি করো। আল্লাহকে ভয় কর, যাঁর কাছে তোমরা একত্রিত হবে।'),
  ('bn.bengali', 58, 10, 'এই কানাঘুষা তো শয়তানের কাজ; মুমিনদেরকে দুঃখ দেয়ার দেয়ার জন্যে। তবে আল্লাহর অনুমতি ব্যতীত সে তাদের কোন ক্ষতি করতে পারবে না। মুমিনদের উচিত আল্লাহর উপর ভরসা করা।'),
  ('bn.bengali', 58, 11, 'মুমিনগণ, যখন তোমাদেরকে বলা হয়ঃ মজলিসে স্থান প্রশস্ত করে দাও, তখন তোমরা স্থান প্রশস্ত করে দিও। আল্লাহর জন্যে তোমাদের জন্য প্রশস্ত করে দিবেন। যখন বলা হয়ঃ উঠে যাও, তখন উঠে যেয়ো। তোমাদের মধ্যে যারা ঈমানদার এবং যারা জ্ঞানপ্রাপ্ত, আল্লাহ তাদের মর্যাদা উচ্চ করে দিবেন। আল্লাহ খবর রাখেন যা কিছু তোমরা কর।'),
  ('bn.bengali', 58, 12, 'মুমিনগণ, তোমরা রসূলের কাছে কানকথা বলতে চাইলে তৎপূর্বে সদকা প্রদান করবে। এটা তোমাদের জন্যে শ্রেয়ঃ ও পবিত্র হওয়ার ভাল উপায়। যদি তাতে সক্ষম না হও, তবে আল্লাহ ক্ষমাশীল, পরম দয়ালু।'),
  ('bn.bengali', 58, 13, 'তোমরা কি কানকথা বলার পূর্বে সদকা প্রদান করতে ভীত হয়ে গেলে? অতঃপর তোমরা যখন সদকা দিতে পারলে না এবং আল্লাহ তোমাদেরকে মাফ করে দিলেন তখন তোমরা নামায কায়েম কর, যাকাত প্রদান কর এবং আল্লাহ ও রসূলের আনুগত্য কর। আল্লাহ খবর রাখেন তোমরা যা কর।'),
  ('bn.bengali', 58, 14, 'আপনি কি তাদের প্রতি লক্ষ্য করেননি, যারা আল্লাহর গযবে নিপতিত সম্প্রদায়ের সাথে বন্ধুত্ব করে? তারা মুসলমানদের দলভুক্ত নয় এবং তাদেরও দলভূক্ত নয়। তারা জেনেশুনে মিথ্যা বিষয়ে শপথ করে।'),
  ('bn.bengali', 58, 15, 'আল্লাহ তাদের জন্যে কঠোর শাস্তি প্রস্তুত রেখেছেন। নিশ্চয় তারা যা করে, খুবই মন্দ।'),
  ('bn.bengali', 58, 16, 'তারা তাদের শপথকে ঢাল করে রেখেছেন, অতঃপর তারা আল্লাহর পথ থেকে মানুষকে বাধা প্রদান করে। অতএব, তাদের জন্য রয়েছে অপমানজনক শাস্তি।'),
  ('bn.bengali', 58, 17, 'আল্লাহর কবল থেকে তাদের ধন-সম্পদ ও সন্তান-সন্ততি তাদেরকে মোটেই বাঁচাতে পারবেনা। তারাই জাহান্নামের অধিবাসী তথায় তারা চিরকাল থাকবে।'),
  ('bn.bengali', 58, 18, 'যেদিন আল্লাহ তাদের সকলকে পুনরুত্থিত করবেন। অতঃপর তারা আল্লাহর সামনে শপথ করবে, যেমন তোমাদের সামনে শপথ করে। তারা মনে করবে যে, তারা কিছু সৎপথে আছে। সাবধান, তারাই তো আসল মিথ্যাবাদী।'),
  ('bn.bengali', 58, 19, 'শয়তান তাদেরকে বশীভূত করে নিয়েছে, অতঃপর আল্লাহর স্মরণ ভূলিয়ে দিয়েছে। তারা শয়তানের দল। সাবধান, শয়তানের দলই ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 58, 20, 'নিশ্চয় যারা আল্লাহ ও তাঁর রসূলের বিরুদ্ধাচারণ করে, তারাই লাঞ্ছিতদের দলভূক্ত।'),
  ('bn.bengali', 58, 21, 'আল্লাহ লিখে দিয়েছেনঃ আমি এবং আমার রসূলগণ অবশ্যই বিজয়ী হব। নিশ্চয় আল্লাহ শক্তিধর, পরাক্রমশালী।'),
  ('bn.bengali', 58, 22, 'যারা আল্লাহ ও পরকালে বিশ্বাস করে, তাদেরকে আপনি আল্লাহ ও তাঁর রসূলের বিরুদ্ধাচরণকারীদের সাথে বন্ধুত্ব করতে দেখবেন না, যদিও তারা তাদের পিতা, পুত্র, ভ্রাতা অথবা জ্ঞাতি-গোষ্ঠী হয়। তাদের অন্তরে আল্লাহ ঈমান লিখে দিয়েছেন এবং তাদেরকে শক্তিশালী করেছেন তাঁর অদৃশ্য শক্তি দ্বারা। তিনি তাদেরকে জান্নাতে দাখিল করবেন, যার তলদেশে নদী প্রবাহিত। তারা তথায় চিরকাল থাকবে। আল্লাহ তাদের প্রতি সন্তুষ্ট এবং তারা আল্লাহর প্রতি সন্তুষ্ট। তারাই আল্লাহর দল। জেনে রাখ, আল্লাহর দলই সফলকাম হবে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 58, 1, 'Allah hath heard the saying of her that disputeth with thee (Muhammad) concerning her husband, and complaineth unto Allah. And Allah heareth your colloquy. Lo! Allah is Hearer, Knower.'),
  ('en.pickthall', 58, 2, 'Such of you as put away your wives (by saying they are as their mothers) - They are not their mothers; none are their mothers except those who gave them birth - they indeed utter an ill word and a lie. And lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 58, 3, 'Those who put away their wives (by saying they are as their mothers) and afterward would go back on that which they have said, (the penalty) in that case (is) the freeing of a slave before they touch one another. Unto this ye are exhorted; and Allah is Informed of what ye do.'),
  ('en.pickthall', 58, 4, 'And he who findeth not (the wherewithal), let him fast for two successive months before they touch one another; and for him who is unable to do so (the penance is) the feeding of sixty needy ones. This, that ye may put trust in Allah and His messenger. Such are the limits (imposed by Allah); and for disbelievers is a painful doom.'),
  ('en.pickthall', 58, 5, 'Lo! those who oppose Allah and His messenger will be abased even as those before them were abased; and We have sent down clear tokens, and for disbelievers is a shameful doom'),
  ('en.pickthall', 58, 6, 'On the day when Allah will raise them all together and inform them of what they did. Allah hath kept account of it while they forgot it. And Allah is Witness over all things.'),
  ('en.pickthall', 58, 7, 'Hast thou not seen that Allah knoweth all that is in the heavens and all that is in the earth? There is no secret conference of three but He is their fourth, nor of five but He is their sixth, nor of less than that or more but He is with them wheresoever they may be; and afterward, on the Day of Resurrection, He will inform them of what they did. Lo! Allah is Knower of all things.'),
  ('en.pickthall', 58, 8, 'Hast thou not observed those who were forbidden conspiracy and afterward returned to that which they had been forbidden, and (now) conspire together for crime and wrongdoing and disobedience toward the messenger? And when they come unto thee they greet thee with a greeting wherewith Allah greeteth thee not, and say within themselves: Why should Allah punish us for what we say? Hell will suffice them; they will feel the heat thereof - a hapless journey\'s end!'),
  ('en.pickthall', 58, 9, 'O ye who believe! When ye conspire together, conspire not together for crime and wrongdoing and disobedience toward the messenger, but conspire together for righteousness and piety, and keep your duty toward Allah, unto whom ye will be gathered.'),
  ('en.pickthall', 58, 10, 'Lo! Conspiracy is only of the devil, that he may vex those who believe; but he can harm them not at all unless by Allah\'s leave. In Allah let believers put their trust.'),
  ('en.pickthall', 58, 11, 'O ye who believe! when it is said unto you, Make room! in assemblies, then make room; Allah will make way for you (hereafter). And when it is said, Come up higher! go up higher; Allah will exalt those who believe among you, and those who have knowledge, to high ranks. Allah is Informed of what ye do.'),
  ('en.pickthall', 58, 12, 'O ye who believe! When ye hold conference with the messenger, offer an alms before your conference. That is better and purer for you. But if ye cannot find (the wherewithal) then lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 58, 13, 'Fear ye to offer alms before your conference? Then, when ye do it not and Allah hath forgiven you, establish worship and pay the poor-due and obey Allah and His messenger. And Allah is Aware of what ye do.'),
  ('en.pickthall', 58, 14, 'Hast thou not seen those who take for friends a folk with whom Allah is wroth? They are neither of you nor of them, and they swear a false oath knowingly.'),
  ('en.pickthall', 58, 15, 'Allah hath prepared for them a dreadful doom. Evil indeed is that which they are wont to do.'),
  ('en.pickthall', 58, 16, 'They make a shelter of their oaths and turn (men) from the way of Allah; so theirs will be a shameful doom.'),
  ('en.pickthall', 58, 17, 'Their wealth and their children will avail them naught against Allah. Such are rightful owners of the Fire; they will abide therein.'),
  ('en.pickthall', 58, 18, 'On the day when Allah will raise them all together, then will they swear unto Him as they (now) swear unto you, and they will fancy that they have some standing. Lo! is it not they who are the liars?'),
  ('en.pickthall', 58, 19, 'The devil hath engrossed them and so hath caused them to forget remembrance of Allah. They are the devil\'s party. Lo! is it not the devil\'s party who will be the losers?'),
  ('en.pickthall', 58, 20, 'Lo! those who oppose Allah and His messenger, they will be among the lowest.'),
  ('en.pickthall', 58, 21, 'Allah hath decreed: Lo! I verily shall conquer, I and My messengers. Lo! Allah is Strong, Almighty.'),
  ('en.pickthall', 58, 22, 'Thou wilt not find folk who believe in Allah and the Last Day loving those who oppose Allah and His messenger, even though they be their fathers or their sons or their brethren or their clan. As for such, He hath written faith upon their hearts and hath strengthened them with a Spirit from Him, and He will bring them into Gardens underneath which rivers flow, wherein they will abide. Allah is well pleased with them, and they are well pleased with Him. They are Allah\'s party. Lo! is it not Allah\'s party who are the successful?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 58, 1, 'Allah has indeed heard (and accepted) the statement of the woman who pleads with thee concerning her husband and carries her complaint (in prayer) to Allah: and Allah (always) hears the arguments between both sides among you: for Allah hears and sees (all things).'),
  ('en.yusufali', 58, 2, 'If any men among you divorce their wives by Zihar (calling them mothers), they cannot be their mothers: None can be their mothers except those who gave them birth. And in fact they use words (both) iniquitous and false: but truly Allah is one that blots out (sins), and forgives (again and again).'),
  ('en.yusufali', 58, 3, 'But those who divorce their wives by Zihar, then wish to go back on the words they uttered,- (It is ordained that such a one) should free a slave before they touch each other: Thus are ye admonished to perform: and Allah is well-acquainted with (all) that ye do.'),
  ('en.yusufali', 58, 4, 'And if any has not (the wherewithal), he should fast for two months consecutively before they touch each other. But if any is unable to do so, he should feed sixty indigent ones, this, that ye may show your faith in Allah and His Messenger. Those are limits (set by) Allah. For those who reject (Him), there is a grievous Penalty.'),
  ('en.yusufali', 58, 5, 'Those who resist Allah and His Messenger will be humbled to dust, as were those before them: for We have already sent down Clear Signs. And the Unbelievers (will have) a humiliating Penalty,-'),
  ('en.yusufali', 58, 6, 'On the Day that Allah will raise them all up (again) and show them the Truth (and meaning) of their conduct. Allah has reckoned its (value), though they may have forgotten it, for Allah is Witness to all things.'),
  ('en.yusufali', 58, 7, 'Seest thou not that Allah doth know (all) that is in the heavens and on earth? There is not a secret consultation between three, but He makes the fourth among them, - Nor between five but He makes the sixth,- nor between fewer nor more, but He is in their midst, wheresoever they be: In the end will He tell them the truth of their conduct, on the Day of Judgment. For Allah has full knowledge of all things.'),
  ('en.yusufali', 58, 8, 'Turnest thou not thy sight towards those who were forbidden secret counsels yet revert to that which they were forbidden (to do)? And they hold secret counsels among themselves for iniquity and hostility, and disobedience to the Messenger. And when they come to thee, they salute thee, not as Allah salutes thee, (but in crooked ways): And they say to themselves, "Why does not Allah punish us for our words?" Enough for them is Hell: In it will they burn, and evil is that destination!'),
  ('en.yusufali', 58, 9, 'O ye who believe! When ye hold secret counsel, do it not for iniquity and hostility, and disobedience to the Prophet; but do it for righteousness and self-restraint; and fear Allah, to Whom ye shall be brought back.'),
  ('en.yusufali', 58, 10, 'Secret counsels are only (inspired) by the Evil One, in order that he may cause grief to the Believers; but he cannot harm them in the least, except as Allah permits; and on Allah let the Believers put their trust.'),
  ('en.yusufali', 58, 11, 'O ye who believe! When ye are told to make room in the assemblies, (spread out and) make room: (ample) room will Allah provide for you. And when ye are told to rise up, rise up Allah will rise up, to (suitable) ranks (and degrees), those of you who believe and who have been granted (mystic) Knowledge. And Allah is well-acquainted with all ye do.'),
  ('en.yusufali', 58, 12, 'O ye who believe! When ye consult the Messenger in private, spend something in charity before your private consultation. That will be best for you, and most conducive to purity (of conduct). But if ye find not (the wherewithal), Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 58, 13, 'Is it that ye are afraid of spending sums in charity before your private consultation (with him)? If, then, ye do not so, and Allah forgives you, then (at least) establish regular prayer; practise regular charity; and obey Allah and His Messenger. And Allah is well-acquainted with all that ye do.'),
  ('en.yusufali', 58, 14, 'Turnest thou not thy attention to those who turn (in friendship) to such as have the Wrath of Allah upon them? They are neither of you nor of them, and they swear to falsehood knowingly.'),
  ('en.yusufali', 58, 15, 'Allah has prepared for them a severe Penalty: evil indeed are their deeds.'),
  ('en.yusufali', 58, 16, 'They have made their oaths a screen (for their misdeeds): thus they obstruct (men) from the Path of Allah: therefore shall they have a humiliating Penalty.'),
  ('en.yusufali', 58, 17, 'Of no profit whatever to them, against Allah, will be their riches nor their sons: they will be Companions of the Fire, to dwell therein (for aye)!'),
  ('en.yusufali', 58, 18, 'One day will Allah raise them all up (for Judgment): then will they swear to Him as they swear to you: And they think that they have something (to stand upon). No, indeed! they are but liars!'),
  ('en.yusufali', 58, 19, 'The Evil One has got the better of them: so he has made them lose the remembrance of Allah. They are the Party of the Evil One. Truly, it is the Party of the Evil One that will perish!'),
  ('en.yusufali', 58, 20, 'Those who resist Allah and His Messenger will be among those most humiliated.'),
  ('en.yusufali', 58, 21, 'Allah has decreed: "It is I and My messengers who must prevail": For Allah is One full of strength, able to enforce His Will.'),
  ('en.yusufali', 58, 22, 'Thou wilt not find any people who believe in Allah and the Last Day, loving those who resist Allah and His Messenger, even though they were their fathers or their sons, or their brothers, or their kindred. For such He has written Faith in their hearts, and strengthened them with a spirit from Himself. And He will admit them to Gardens beneath which Rivers flow, to dwell therein (for ever). Allah will be well pleased with them, and they with Him. They are the Party of Allah. Truly it is the Party of Allah that will achieve Felicity.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 58, 1, 'Qad sami\'al laahu qawlal latee tujaadiluka fee zawjihaa wa tashtakeee ilal laahi wallaahu yasma\'u tahaawurakumaa; innal laaha samee\'um baseer'),
  ('en.transliteration', 58, 2, 'Allazeena yuzaahiroona minkum min nisaaa\'ihim maa hunnaa ummahaatihim in ummahaatuhum illal laaa\'ee waladnahum; wa innaahum la yaqooloona munkaram minal qawli wa zooraa; wa innal laaha la\'afuwwun ghafoor'),
  ('en.transliteration', 58, 3, 'Wallazeena yuzaahiroona min nisaaa\'ihim summa ya\'oodoona limaa qaaloo fatabreeru raqabatim min qabli any-yatamaaassaa; zaalikum too\'azoona bih; wallaahu bimaa ta\'maloona khabeer'),
  ('en.transliteration', 58, 4, 'Famal lam yajid fa siyaamu shahraini mutataabi\'ayni min qabli any-yatamaaassaa famal lam yastati\' fa-it\'aamu sitteena miskeena; zaalika litu\'minoo billaahi wa rasoolih\'wa tilka hudoodul laah; wa lilkaafireena \'azaabun aleem'),
  ('en.transliteration', 58, 5, 'Innal lazeena yuhaaaddoonal laaha wa Rasoolahoo kubitoo kamaa kubital lazeena min qablihim; wa qad anzalnaaa aayaatim baiyinaat; wa lilkaa fireena \'azaabum muheen'),
  ('en.transliteration', 58, 6, 'Yawma yab\'asuhumul laahu jamee\'an fayunabbi\'uhum bimaa \'amiloo; ahsaahul laahu wa nasooh; wallaahu \'alaa kulli shai\'in shaheed'),
  ('en.transliteration', 58, 7, 'Alam tara annal laaha ya\'lamu maa fis samaawaati wa maa fil ardi maa yakoonu min najwaa salaasatin illaa Huwa raabi\'uhum wa laa khamsatin illaa huwa saadisuhum wa laaa adnaa min zaalika wa laaa aksara illaa huwa ma\'ahum ayna, maa kaanoo summa yunabbi\'uhum bimaa \'amiloo yawmal qiyaamah; innal laaha bikulli shai\'in aleem'),
  ('en.transliteration', 58, 8, 'Alam tara ilal lazeena nuhoo \'anin najwaa summa ya\'oodoona limaa nuhoo \'anhu wa yatanaajawna bil ismi wal\'udwaani wa ma\'siyatir rasooli wa izaa jaaa\'ooka haiyawka bimaa lam yuhai yika bihil laahu wa yaqooloona fee anfusihim law laa yu\'azzibunal laahu bimaa naqool; hasbuhum jahannnamu yaslawnahaa fabi\'sal maseer'),
  ('en.transliteration', 58, 9, 'Yaaa ayyuhal lazeena aamanoo izaa tanaajaytum falaa tatanaajaw bil ismi wal \'udwaani wa ma\'siyatir rasooli wa tanaajaw bil birri wattaqwaa wattaqul laahal lazeee ilaihi tuhsharoon'),
  ('en.transliteration', 58, 10, 'Innaman najwaa minash shaitaani liyahzunal lazeena aamanoo wa laisa bidaaarrihim shai\'an illaa bi-iznil laah; wa \'alal laahi falyatawakkalil mu\'minoon'),
  ('en.transliteration', 58, 11, 'Yaaa ayyuhal lazeena aamanoo izaa qeela lakum tafassahoo fil majaalisi fafsahoo yafsahil laahu lakum wa izaa qeelan shuzoo fanshuzoo yarfa\'il laahul lazeena aamanoo minkum wallazeena ootul \'ilma darajaat; wallaahu bimaa ta\'maloona khabeer'),
  ('en.transliteration', 58, 12, 'Yaaa ayyuhal lazeena aamanooo izaa naajitumur Rasoola faqaddimoo baina yadai najwaakum sadaqah; zaalika khairul lakum wa athar; fa il lam tajidoo fa innal laaha ghafoorur Raheem'),
  ('en.transliteration', 58, 13, '\'A-ashfaqtum an tuqaddimoo baina yadai najwaakum sadaqaat; fa-iz lam taf\'aloo wa taabal laahu \'alaikum fa aqeemus Salaata wa aatuz Zakaata wa atee\'ul laaha wa rasoolah; wallaahu khabeerum bimaa ta\'maloon'),
  ('en.transliteration', 58, 14, 'Alam tara ilal lazeena tawallaw qawman ghadibal laahu \'alaihim maa hum minkum wa laa minhum wa yahlifoona \'alal kazibi wa hum ya\'lamoon'),
  ('en.transliteration', 58, 15, 'A\'addal laahu lahum \'azaaban shadeedan innahum saaa\'a maa kaanoo ya\'maloon'),
  ('en.transliteration', 58, 16, 'Ittakhazooo aymaanahum junnatan fasaddoo \'an sabeelil laahi falahum \'azaabum muheen'),
  ('en.transliteration', 58, 17, 'Lan tughniya \'anhum amwaaluhum wa laaa awladuhum minal laahi shai\'aa; ulaaa \'ika As haabun Naari hum feehaa khaalidoon'),
  ('en.transliteration', 58, 18, 'Yawma yab\'asuhumul laahujamee\'an fa yahlifoona lahoo kamaa yahlifoona lakum wa yahsaboona annahum \'alaa shai\'; alaaa innahum humul kaaziboon'),
  ('en.transliteration', 58, 19, 'Istahwaza \'alaihimush shaitaanu fa ansaahum zikral laah; ulaaa\'ika hizbush shaitaaan; alaaa innaa hizbash shaitaani humul khaasiroon'),
  ('en.transliteration', 58, 20, 'Innal lazeena yuhaaaddoonal laaha wa Rasoolahooo ulaaa\'ika fil azalleen'),
  ('en.transliteration', 58, 21, 'Katabal laahu la aghlibanna ana wa Rusulee; innal laaha qawiyyun \'Azeez'),
  ('en.transliteration', 58, 22, 'Laa tajidu qawmany yu\'minoona billaahi wal yawmil aakhiri yuwaaaddoona man haaaddal laaha wa Rasoolahoo wa law kaanooo aabaaa\'ahum aw abnaaa\'ahum aw ikhwaa nahum aw \'asheeratahum; ulaaa\'ika kataba fee quloobihi mul eemaana wa ayyadahum biroohimminhu wa yudkhilu hum jannatin tajree min tahtihal anhaaru khaalideena feehaa; radiyal laahu \'anhum wa radoo \'anh; ulaaa \'ika hizbul laah; alaaa inna hizbal laahi humul muflihoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 58, 1, 'بے شک الله نے اس عورت کی بات سن لی ہے جو آپ سے اپنے خاوند کے بارے میں جھگڑتی تھی اور الله کی جناب میں شکایت کرتی تھی اور الله تم دونوں کی گفتگو سن رہا تھا بے شک الله سب کچھ سننے والا دیکھنے والا ہے'),
  ('ur.ahmedali', 58, 2, 'جو لوگ تم میں سے اپنی عورتوں سے ظہار کرتے ہیں وہ ان کی مائیں نہیں ہو جاتیں ان کی مائیں تو وہی ہیں جنہوں نے انہیں جنا ہے اور بےشک انہوں نے ایک بیہودہ اور جھوٹی بات منہ سے نکالی ہے اور بے شک الله معاف کرنے والا بخشنے والا ہے'),
  ('ur.ahmedali', 58, 3, 'اور جو لوگ اپنی بیویوں سے اظہار کرتے ہیں پھر اس کہی ہوئی بات سے پھرنا چاہیں تو ایک غلام ایک دوسرے کو ہاتھ لگانے سے پہلے آزاد کر دیں یہ اس کے لیے اس سے تمہیں نصیحت ہو اور الله جو کچھ تم کرتے ہو اس کی خبر رکھتا ہے'),
  ('ur.ahmedali', 58, 4, 'پس جو شخص نہ پائے تو دو مہینے کے لگاتار روزے رکھے اس سے پہلےکہ ایک دوسرے کو چھوئیں پس جو کوئی ایسا نہ کر سکے تو ساٹھ مسکینوں کو کھانا کھلائے یہ ا س لیے کہ تم الله اور اس کے رسول پر ایمان لاؤ اور یہ الله کی حدیں ہیں اورمنکروں کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 58, 5, 'بے شک جو لوگ الله اور اس کے رسول کی مخالفت کرتے ہیں وہ ذلیل کیے جائیں گے جس طرح ذلیل کیے گئے وہ لوگ جو ان سے پہلے تھے اور ہم نے تو صاف صاف آیتیں نازل کر دی ہیں اور منکروں کے لیے ذلت کا عذاب ہے'),
  ('ur.ahmedali', 58, 6, 'جس دن ان سب کو الله قبروں سے اٹھائے گا پھر ان کو بتائے گا کہ وہ کیا کرتے تھے جس کو الله نے یاد رکھا ہے اور وہ بھول گئے ہیں اور الله کے سامنے ہر چیز موجود ہے'),
  ('ur.ahmedali', 58, 7, 'کیا آپ نے نہیں دیکھا الله جانتا ہے جو کچھ آسمانوں اور زمین میں ہے (یہاں تک) کہ جو کوئی مشورہ تین آدمیوں میں ہوتا ہے تو وہ چوتھا ہوتا ہے اور جو پانچ میں ہوتا ہے تو وہ چھٹا ہوتا ہے اور خواہ اس سے کم کی سرگوشی ہو یا زیادہ کی مگر وہ ہر جگہ ان کے ساتھ ہوتا ہے پھر انہیں قیامت کے دن بتائے گا کہ وہ کیا کرتے تھے بے شک الله ہر چیز کو جاننے والا ہے'),
  ('ur.ahmedali', 58, 8, 'کیا آپ نے ان کو نہیں دیکھا جو سرگوشی کرنے سے روکے گئے تھے پھر وہ اسی بات کی طرف لوٹتے ہیں جس سے انہیں روکا گیا تھا اور گناہ اور سرکشی اور رسول کی نافرمانی کی سرگوشی کرتے ہیں اور جب وہ آپ کے پاس آتے ہیں تو آپ کو ایسے لفظوں سے سلام کرتے ہیں جن سے الله نے آپ کو سلام نہیں دیا اور اپنے دلوں میں کہتے ہیں کہ ہمیں الله اس پر کیوں عذاب نہیں دیتا جو ہم کہہ رہے ہیں ان کے لیے دوزخ کافی ہے وہ اس میں داخل ہوں گے پس وہ کیا ہی برا ٹھکانہ ہے'),
  ('ur.ahmedali', 58, 9, 'اے ایمان والو جب تم آپس میں سرگوشی کرو تو گناہ اور سرکشی اور رسول کی نافرمانی کی سرگوشی نہ کرو اورنیکی اور پرہیز گاری کی سرگوشی کرو اور الله سے ڈرو جس کی طرف تم جمع کیے جاؤ گے'),
  ('ur.ahmedali', 58, 10, '(یہ) سرگوشی تو صرف شیطانی بات ہے تاکہ ایمان داروں کو غمناک کر دے حالانکہ بغیر حکم الله کے کچھ بھی ضرر نہیں دے سکتی اور ایمان والے تو الله ہی پربھروسہ رکھتے ہیں'),
  ('ur.ahmedali', 58, 11, 'اے ایمان والو جب تمہیں مجلسوں میں کھل کر بیٹھنے کو کہا جائے تو کھل کر بیٹھو الله تمیں فراخی دے گا اور جب کہا جائے کہ اٹھ جاؤ تو اٹھ جاؤ تم میں سے الله ایمان داروں کے اور ان کے جنہیں علم دیا گیا ہے درجے بلند کرے گا اور جو کچھ تم کرتے ہواللہ اس سے خبردار ہے'),
  ('ur.ahmedali', 58, 12, 'اے ایمان والو جب تم رسول سے سرگوشی کرو تو اپنی سرگوشی سے پہلے صدقہ دے لیا کرو یہ تمہارے لیے بہتر اور زیادہ پاکیزہ بات ہے پس اگر نہ پاؤ تو الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 58, 13, 'کیا تم اپنی سرگوشی سے پہلے صدقہ دینے سے ڈر گئے پھر جب تم نے نہ کیا اور الله نے تمہیں معاف بھی کردیا تو (بس) نماز ادا کرو اور زکواة دو اور الله اور اس کے رسول کی اطاعت کرو اور جو کچھ تم کرتے ہو الله اس سے خبردار ہے'),
  ('ur.ahmedali', 58, 14, 'کیا آپ نے ان کو نہیں دیکھا جنہوں نے اس قوم سے دوستی رکھی ہے جن پر الله کا غضب ہے نہ وہ تم میں سے ہیں اور نہ ان میں سے اوروہ جان بوجھ کر جھوٹ پر قسمیں کھاتے ہیں'),
  ('ur.ahmedali', 58, 15, 'الله نے ان کے لیے سخت عذاب تیار کر رکھا ہے بے شک وہ بہت ہی برا ہے جو کچھ وہ کرتے ہیں'),
  ('ur.ahmedali', 58, 16, 'انہوں نے اپنی قسموں کو ڈھال بنا لیا ہے پس وہ (لوگوں کو) الله کی راہ سے روکتے ہیں تو ان کے لیے ذلیل کرنے والاعذآب ہے'),
  ('ur.ahmedali', 58, 17, 'الله کے مقابلہ میں نہ تو ان کے مال ہی کچھ کام آئیں گے اور نہ ان کی اولاد کچھ کام آئے گی یہ دوزخی لوگ ہیں وہ اس میں ہمیشہ رہنے والے ہیں'),
  ('ur.ahmedali', 58, 18, 'جس دن الله ان سب کو قبروں سے اٹھائے گا تو اس کے سامنے بھی ایسی ہی قسمیں کھائیں گے جیسی کہ تمہارے سامنے کھاتے ہیں اور سمھجھ رہے ہیں کہ ہم رستے پر ہیں خبردار بے شک وہی جھوٹے ہیں'),
  ('ur.ahmedali', 58, 19, 'ان پر شیطان نے غلبہ پا لیا ہے پس اس نے انہیں الله کا ذکر بھلا دیا ہے یہی شیطان کا گروہ ہے خبردار بے شک شیطان کا گروہ ہی نقصان اٹھانے والا ہے'),
  ('ur.ahmedali', 58, 20, 'بے شک جو لوگ الله اورا سکے رسول کی مخالفت کرتے ہیں یہی لوگ ذلیلوں میں ہیں'),
  ('ur.ahmedali', 58, 21, 'الله نے لکھ دیا ہے کہ میں اور میرے رسول ہی غالب رہیں گے بے شک الله زور آور زبردست ہے'),
  ('ur.ahmedali', 58, 22, 'آپ ایسی کوئی قوم نہ پائیں گے جو الله اور قیامت کے دن پر ایمان رکھتی ہو اور ان لوگو ں سے بھی دوستی رکھتے ہوں جو الله اور اس کے رسول کی مخالفت کرتے ہیں گو وہ ان کے باپ یا بیٹے یا بھائی یا کنبے کے لوگ ہی کیوں نہ ہوں یہی وہ لوگ ہیں جن کے دلوں میں اللہ نے ایمان لکھ دیا ہے اور ان کو اپنے فیض سے قوت دی ہے اور وہ انہیں بہشتوں میں داخل کرے گا جن کے نیچے نہریں بہہ رہی ہوں گی وہ ان میں ہمیشہ رہیں گے الله ان سے راضی ہوا اور وہ اس سے راضی ہوئے یہی الله کا گروہ ہے خبردار بے شک الله کا گروہ ہی کامیاب ہونے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 58, 1, 'Kocası hakkında seninle tartışan ve Allah\'a şikayette bulunan kadının sözünü Allah işitmiştir; esasen Allah konuşmanızı işitir. Doğrusu Allah işitendir, görendir.'),
  ('tr.diyanet', 58, 2, 'İçinizde karılarını "zıhar" yapanlar bilsinler ki, karıları anneleri değildir; anneleri ancak, onları doğuranlardır. Doğrusu söyledikleri kötü ve asılsız bir sözdür. Allah şüphesiz affedendir, bağışlayandır.'),
  ('tr.diyanet', 58, 3, 'Karılarını zıhar yoluyla boşamak isteyip, sonra sözlerinden dönenlerin, ailesiyle temas etmeden bir köle azad etmeleri gerekir. Size bu hususta böylece öğüt verilmektedir. Allah, işlediklerinizden haberdardır.'),
  ('tr.diyanet', 58, 4, 'Azad edecek köle bulamayanın, ailesiyle temastan önce iki ay birbiri peşinden oruç tutması gerekir. Buna gücü yetmeyen, altmış düşkünü doyurur. Bu kolaylık, Allah\'a ve Peygamberine inanmış olmanızdan ötürüdür; bunlar, Allah\'ın koyduğu sınırlardır; inkar edenler için can yakıcı azap vardır.'),
  ('tr.diyanet', 58, 5, 'Allah\'a ve Peygamberine karşı gelenler, kendilerinden öncekiler nasıl alçaltıldı ise öyle alçaltılacaklardır. Biz, apaçık ayetler indirmişizdir, bunları inkar edene alçaltıcı azap vardır.'),
  ('tr.diyanet', 58, 6, 'Allah onların hepsini dirilttiği gün, kendilerine işlediklerini haber verir; Allah onları bir bir saymıştır, fakat kendileri unutmuşlardır. Allah her şeye şahiddir.'),
  ('tr.diyanet', 58, 7, 'Göklerde olanları da, yerde olanları da Allah\'ın bildiğini bilmez misin? Üç kişinin gizli bulunduğu yerde dördüncü mutlaka O\'dur; beş kişinin gizli bulunduğu yerde altıncıları mutlaka O\'dur; bunlardan az veya çok, ne olursa olsunlar nerede bulunurlarsa bulunsunlar, mutlak onlarla beraberdir. Sonra, kıyamet günü, işlediklerini onlara haber verir. Doğrusu Allah her şeyi bilendir.'),
  ('tr.diyanet', 58, 8, 'Gizli toplantıdan menedilen, sonra menolundukları şeyi yapmaya kalkışarak günah işlemek, düşmanlık etmek ve Peygambere karşı gelmek konusunda gizli gizli konuşanları görmedin mi? Sana geldiklerinde, Allah\'ın seni selamlamadığı bir şekilde seni selamlarlar; içlerinden, "Gerçekten peygamber olsaydı Allah\'ın bizi, söylediklerimizden ötürü, cezalandırması gerekmez miydi?" derler. Cehennem onlara yeter. Oraya girerler, ne kötü dönüştür!'),
  ('tr.diyanet', 58, 9, 'Ey inananlar! Gizli konuştuğunuz zaman, günah işlemeyi, düşmanlık etmeyi ve Peygambere karşı gelmeyi fısıldaşmayın; iyilik yapmak ve Allah\'a karşı gelmekten sakınmayı konuşun; kıyamet günü huzurunda toplanacağınız Allah\'tan sakının.'),
  ('tr.diyanet', 58, 10, 'Gizli toplantılar inananları üzmek için şeytanın istediği şeydir; Allah\'ın izni olmadıkça şeytan onlara bir zarar veremez; inananlar yalnız Allah\'a güvensinler.'),
  ('tr.diyanet', 58, 11, 'Ey inananlar! Toplantılarda, size, "Yer açın" denince yer açın ki Allah da size genişlik versin; "Kalkın" denildiği zaman da hemen kalkın ki, Allah, içinizden inanmış olanları ve kendilerine ilim verilenleri derecelerle yükseltsin. Allah işlediklerinizden haberdardır.'),
  ('tr.diyanet', 58, 12, 'Ey inananlar! Peygamberle hususi olarak konuşacağınızda, bu konuşmanızdan önce fakirlere sadaka veriniz; bu, sizin daha iyi ve daha temiz olmanız içindir. Eğer sadaka verecek bir şey bulamazsanız üzülmeyiniz. Allah şüphesiz bağışlayandır, acıyandır.'),
  ('tr.diyanet', 58, 13, 'Hususi konuşmanızdan önce sadaka vermekten ürktünüz mü ki bunu yerine getirmediniz? Ama Allah, tevbenizi kabul etmiştir. Öyleyse namazı kılın, zekatı verin, Allah\'a ve Peygamberine itaat edin. Allah, işlediklerinizden haberdardır.'),
  ('tr.diyanet', 58, 14, 'Allah\'ın gazabettiği milleti dost edinen münafıkları görmedin mi? Onlar ne sizdendir ne de onlardan, bile bile, yalan yere yemin etmektedirler.'),
  ('tr.diyanet', 58, 15, 'Allah, onlara çetin bir azap hazırlamıştır. İşledikleri şey ne kötüdür!'),
  ('tr.diyanet', 58, 16, 'Yeminlerini kalkan edindiler de, Allah yolundan alıkoydular; onlara alçaltıcı bir azap vardır.'),
  ('tr.diyanet', 58, 17, 'Malları ve çocukları, onlara, Allah katında bir fayda sağlamaz. Onlar cehennemliklerdir, orada temelli kalacaklardır.'),
  ('tr.diyanet', 58, 18, 'Allah, onların hepsini tekrar dirilttiği gün, size yemin ettikleri gibi O\'na yemin ederler; kendilerine bir yarar sağlayacağını sanırlar. Dikkat edin; onlar şüphesiz yalancıdırlar.'),
  ('tr.diyanet', 58, 19, 'Şeytan onların başlarına dikilip Allah\'ı anmayı unutturmuştur. İşte onlar şeytanın taraftarlarıdır. İyi bilin; şeytanın taraftarları elbette hüsrandadırlar.'),
  ('tr.diyanet', 58, 20, 'Allah\'a ve Peygamberine karşı gelenler; işte onlar, en alçak kimselerle beraberdirler.'),
  ('tr.diyanet', 58, 21, 'Allah, "And olsun ki Ben ve peygamberlerim üstün geleceğiz" diye yazmıştır. Doğrusu Allah kuvvetlidir, güçlüdür.'),
  ('tr.diyanet', 58, 22, 'Allah\'a ve ahiret gününe inanan bir milletin, babaları veya oğulları veya kardeşleri ya da akrabaları olsa bile Allah\'a ve Peygamberine karşı gelenlere, sevgi beslediklerini görmezsin. İşte Allah, imanı bunların kalblerine yazmış, katından bir nur ile onları desteklemiştir. Onları, içlerinden ırmaklar akan, içinde temelli kalacakları cennetlere koyar. Allah onlardan hoşnut olmuştur, onlar da Allah\'tan hoşnut olmuştur. İşte bunlar, Allah\'tan yana olanlardır. İyi bilin ki, saadete erecek olanlar, Allah\'tan yana olanlardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 58, 1, 'Sesungguhnya Allah telah mendengar perkataan wanita yang mengajukan gugatan kepada kamu tentang suaminya, dan mengadukan (halnya) kepada Allah. Dan Allah mendengar soal jawab antara kamu berdua. Sesungguhnya Allah Maha Mendengar lagi Maha Melihat.'),
  ('id.indonesian', 58, 2, 'Orang-orang yang menzhihar isterinya di antara kamu, (menganggap isterinya sebagai ibunya, padahal) tiadalah isteri mereka itu ibu mereka. Ibu-ibu mereka tidak lain hanyalah wanita yang melahirkan mereka. Dan sesungguhnya mereka sungguh-sungguh mengucapkan suatu perkataan mungkar dan dusta. Dan sesungguhnya Allah Maha Pemaaf lagi Maha Pengampun.'),
  ('id.indonesian', 58, 3, 'Orang-orang yang menzhihar isteri mereka, kemudian mereka hendak menarik kembali apa yang mereka ucapkan, maka (wajib atasnya) memerdekakan seorang budak sebelum kedua suami isteri itu bercampur. Demikianlah yang diajarkan kepada kamu, dan Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 58, 4, 'Barangsiapa yang tidak mendapatkan (budak), maka (wajib atasnya) berpuasa dua bulan berturut-turut sebelum keduanya bercampur. Maka siapa yang tidak kuasa (wajiblah atasnya) memberi makan enam puluh orang miskin. Demikianlah supaya kamu beriman kepada Allah dan Rasul-Nya. Dan itulah hukum-hukum Allah, dan bagi orang kafir ada siksaan yang sangat pedih.'),
  ('id.indonesian', 58, 5, 'Sesungguhnya orang-orang yang yang menentang Allah dan Rasul-Nya, pasti mendapat kehinaan sebagaimana orang-orang yang sebelum mereka telah mendapat kehinaan. Sesungguhnya Kami telah menurunkan bukti-bukti nyata. Dan bagi orang-orang kafir ada siksa yang menghinakan.'),
  ('id.indonesian', 58, 6, 'Pada hari ketika mereka dibangkitkan Allah semuanya, lalu diberitakan-Nya kepada mereka apa yang telah mereka kerjakan. Allah mengumpulkan (mencatat) amal perbuatan itu, padahal mereka telah melupakannya. Dan Allah Maha Menyaksikan segala sesuatu.'),
  ('id.indonesian', 58, 7, 'Tidakkah kamu perhatikan, bahwa sesungguhnya Allah mengetahui apa yang ada di langit dan di bumi? Tiada pembicaraan rahasia antara tiga orang, melainkan Dialah keempatnya. Dan tiada (pembicaraan antara) lima orang, melainkan Dialah keenamnya. Dan tiada (pula) pembicaraan antara jumlah yang kurang dari itu atau lebih banyak, melainkan Dia berada bersama mereka di manapun mereka berada. Kemudian Dia akan memberitahukan kepada mereka pada hari kiamat apa yang telah mereka kerjakan. Sesungguhnya Allah Maha mengetahui segala sesuatu.'),
  ('id.indonesian', 58, 8, 'Apakah tidak kamu perhatikan orang-orang yang telah dilarang mengadakan pembicaraan rahasia, kemudian mereka kembali (mengerjakan) larangan itu dan mereka mengadakan pembicaraan rahasia untuk berbuat dosa, permusuhan dan durhaka kepada Rasul. Dan apabila mereka datang kepadamu, mereka mengucapkan salam kepadamu dengan memberi salam yang bukan sebagai yang ditentukan Allah untukmu. Dan mereka mengatakan kepada diri mereka sendiri: "Mengapa Allah tidak menyiksa kita disebabkan apa yang kita katakan itu?" Cukuplah bagi mereka Jahannam yang akan mereka masuki. Dan neraka itu adalah seburuk-buruk tempat kembali.'),
  ('id.indonesian', 58, 9, 'Hai orang-orang beriman, apabila kamu mengadakan pembicaraan rahasia, janganlah kamu membicarakan tentang membuat dosa, permusuhan dan berbuat durhaka kepada Rasul. Dan bicarakanlah tentang membuat kebajikan dan takwa. Dan bertakwalah kepada Allah yang kepada-Nya kamu akan dikembalikan.'),
  ('id.indonesian', 58, 10, 'Sesungguhnya pembicaraan rahasia itu adalah dari syaitan, supaya orang-orang yang beriman itu berduka cita, sedang pembicaraan itu tiadalah memberi mudharat sedikitpun kepada mereka, kecuali dengan izin Allah dan kepada Allah-lah hendaknya orang-orang yang beriman bertawakkal.'),
  ('id.indonesian', 58, 11, 'Hai orang-orang beriman apabila dikatakan kepadamu: "Berlapang-lapanglah dalam majlis", maka lapangkanlah niscaya Allah akan memberi kelapangan untukmu. Dan apabila dikatakan: "Berdirilah kamu", maka berdirilah, niscaya Allah akan meninggikan orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu pengetahuan beberapa derajat. Dan Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 58, 12, 'Hai orang-orang beriman, apabila kamu mengadakan pembicaraan khusus dengan Rasul hendaklah kamu mengeluarkan sedekah (kepada orang miskin) sebelum pembicaraan itu. Yang demikian itu lebih baik bagimu dan lebih bersih; jika kamu tidak memperoleh (yang akan disedekahkan) maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 58, 13, 'Apakah kamu takut akan (menjadi miskin) karena kamu memberikan sedekah sebelum mengadakan pembicaraan dengan Rasul? Maka jika kamu tiada memperbuatnya dan Allah telah memberi taubat kepadamu maka dirikanlah shalat, tunaikanlah zakat, taatlah kepada Allah dan Rasul-Nya; dan Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 58, 14, 'Tidakkah kamu perhatikan orang-orang yang menjadikan suatu kaum yang dimurkai Allah sebagai teman? Orang-orang itu bukan dari golongan kamu dan bukan (pula) dari golongan mereka. Dan mereka bersumpah untuk menguatkan kebohongan, sedang mereka mengetahui.'),
  ('id.indonesian', 58, 15, 'Allah telah menyediakan bagi mereka azab yang sangat keras, sesungguhnya amat buruklah apa yang telah mereka kerjakan.'),
  ('id.indonesian', 58, 16, 'Mereka menjadikan sumpah-sumpah mereka sebagai perisai, lalu mereka halangi (manusia) dari jalan Allah; karena itu mereka mendapat azab yang menghinakan.'),
  ('id.indonesian', 58, 17, 'Harta benda dan anak-anak mereka tiada berguna sedikitpun (untuk menolong) mereka dari azab Allah. Mereka itulah penghuni neraka, dan mereka kekal di dalamnya.'),
  ('id.indonesian', 58, 18, '(Ingatlah) hari (ketika) mereka semua dibangkitkan Allah lalu mereka bersumpah kepada-Nya (bahwa mereka bukan musyrikin) sebagaimana mereka bersumpah kepadamu; dan mereka menyangka bahwa mereka akan memperoleh suatu (manfaat). Ketahuilah, bahwa sesungguhnya merekalah orang-orang pendusta.'),
  ('id.indonesian', 58, 19, 'Syaitan telah menguasai mereka lalu menjadikan mereka lupa mengingat Allah; mereka itulah golongan syaitan. Ketahuilah, bahwa sesungguhnya golongan syaitan itulah golongan yang merugi.'),
  ('id.indonesian', 58, 20, 'Sesungguhnya orang-orang yang menentang Allah dan Rasul-Nya, mereka termasuk orang-orang yang sangat hina.'),
  ('id.indonesian', 58, 21, 'Allah telah menetapkan: "Aku dan rasul-rasul-Ku pasti menang". Sesungguhnya Allah Maha Kuat lagi Maha Perkasa.'),
  ('id.indonesian', 58, 22, 'Kamu tak akan mendapati kaum yang beriman pada Allah dan hari akhirat, saling berkasih-sayang dengan orang-orang yang menentang Allah dan Rasul-Nya, sekalipun orang-orang itu bapak-bapak, atau anak-anak atau saudara-saudara ataupun keluarga mereka. Mereka itulah orang-orang yang telah menanamkan keimanan dalam hati mereka dan menguatkan mereka dengan pertolongan yang datang daripada-Nya. Dan dimasukan-Nya mereka ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Allah ridha terhadap mereka, dan merekapun merasa puas terhadap (limpahan rahmat)-Nya. Mereka itulah golongan Allah. Ketahuilah, bahwa sesungguhnya hizbullah itu adalah golongan yang beruntung.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 59, 1, 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.'),
  ('en.sahih', 59, 2, 'It is He who expelled the ones who disbelieved among the People of the Scripture from their homes at the first gathering. You did not think they would leave, and they thought that their fortresses would protect them from Allah; but [the decree of] Allah came upon them from where they had not expected, and He cast terror into their hearts [so] they destroyed their houses by their [own] hands and the hands of the believers. So take warning, O people of vision.'),
  ('en.sahih', 59, 3, 'And if not that Allah had decreed for them evacuation, He would have punished them in [this] world, and for them in the Hereafter is the punishment of the Fire.'),
  ('en.sahih', 59, 4, 'That is because they opposed Allah and His Messenger. And whoever opposes Allah - then indeed, Allah is severe in penalty.'),
  ('en.sahih', 59, 5, 'Whatever you have cut down of [their] palm trees or left standing on their trunks - it was by permission of Allah and so He would disgrace the defiantly disobedient.'),
  ('en.sahih', 59, 6, 'And what Allah restored [of property] to His Messenger from them - you did not spur for it [in an expedition] any horses or camels, but Allah gives His messengers power over whom He wills, and Allah is over all things competent.'),
  ('en.sahih', 59, 7, 'And what Allah restored to His Messenger from the people of the towns - it is for Allah and for the Messenger and for [his] near relatives and orphans and the [stranded] traveler - so that it will not be a perpetual distribution among the rich from among you. And whatever the Messenger has given you - take; and what he has forbidden you - refrain from. And fear Allah; indeed, Allah is severe in penalty.'),
  ('en.sahih', 59, 8, 'For the poor emigrants who were expelled from their homes and their properties, seeking bounty from Allah and [His] approval and supporting Allah and His Messenger, [there is also a share]. Those are the truthful.'),
  ('en.sahih', 59, 9, 'And [also for] those who were settled in al-Madinah and [adopted] the faith before them. They love those who emigrated to them and find not any want in their breasts of what the emigrants were given but give [them] preference over themselves, even though they are in privation. And whoever is protected from the stinginess of his soul - it is those who will be the successful.'),
  ('en.sahih', 59, 10, 'And [there is a share for] those who came after them, saying, "Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful."'),
  ('en.sahih', 59, 11, 'Have you not considered those who practice hypocrisy, saying to their brothers who have disbelieved among the People of the Scripture, "If you are expelled, we will surely leave with you, and we will not obey, in regard to you, anyone - ever; and if you are fought, we will surely aid you." But Allah testifies that they are liars.'),
  ('en.sahih', 59, 12, 'If they are expelled, they will not leave with them, and if they are fought, they will not aid them. And [even] if they should aid them, they will surely turn their backs; then [thereafter] they will not be aided.'),
  ('en.sahih', 59, 13, 'You [believers] are more fearful within their breasts than Allah. That is because they are a people who do not understand.'),
  ('en.sahih', 59, 14, 'They will not fight you all except within fortified cities or from behind walls. Their violence among themselves is severe. You think they are together, but their hearts are diverse. That is because they are a people who do not reason.'),
  ('en.sahih', 59, 15, '[Theirs is] like the example of those shortly before them: they tasted the bad consequence of their affair, and they will have a painful punishment.'),
  ('en.sahih', 59, 16, '[The hypocrites are] like the example of Satan when he says to man, "Disbelieve." But when he disbelieves, he says, "Indeed, I am disassociated from you. Indeed, I fear Allah, Lord of the worlds."'),
  ('en.sahih', 59, 17, 'So the outcome for both of them is that they will be in the Fire, abiding eternally therein. And that is the recompense of the wrong-doers.'),
  ('en.sahih', 59, 18, 'O you who have believed, fear Allah. And let every soul look to what it has put forth for tomorrow - and fear Allah. Indeed, Allah is Acquainted with what you do.'),
  ('en.sahih', 59, 19, 'And be not like those who forgot Allah, so He made them forget themselves. Those are the defiantly disobedient.'),
  ('en.sahih', 59, 20, 'Not equal are the companions of the Fire and the companions of Paradise. The companions of Paradise - they are the attainers [of success].'),
  ('en.sahih', 59, 21, 'If We had sent down this Qur\'an upon a mountain, you would have seen it humbled and coming apart from fear of Allah. And these examples We present to the people that perhaps they will give thought.'),
  ('en.sahih', 59, 22, 'He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful.'),
  ('en.sahih', 59, 23, 'He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Bestower of Faith, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him.'),
  ('en.sahih', 59, 24, 'He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him. And He is the Exalted in Might, the Wise.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 59, 1, 'নভোমন্ডল ও ভূমন্ডলে যা কিছু আছে, সবই আল্লাহর পবিত্রতা বর্ণনা করে। তিনি পরাক্রমশালী মহাজ্ঞানী।'),
  ('bn.bengali', 59, 2, 'তিনিই কিতাবধারীদের মধ্যে যারা কাফের, তাদেরকে প্রথমবার একত্রিত করে তাদের বাড়ী-ঘর থেকে বহিস্কার করেছেন। তোমরা ধারণাও করতে পারনি যে, তারা বের হবে এবং তারা মনে করেছিল যে, তাদের দূর্গগুলো তাদেরকে আল্লাহর কবল থেকে রক্ষা করবে। অতঃপর আল্লাহর শাস্তি তাদের উপর এমনদিক থেকে আসল, যার কল্পনাও তারা করেনি। আল্লাহ তাদের অন্তরে ত্রাস সঞ্চার করে দিলেন। তারা তাদের বাড়ী-ঘর নিজেদের হাতে এবং মুসলমানদের হাতে ধ্বংস করছিল। অতএব, হে চক্ষুষ্মান ব্যক্তিগণ, তোমরা শিক্ষা গ্রহণ কর।'),
  ('bn.bengali', 59, 3, 'আল্লাহ যদি তাদের জন্যে নির্বাসন অবধারিত না করতেন, তবে তাদেরকে দুনিয়াতে শাস্তি দিতেন। আর পরকালে তাদের জন্যে রয়েছে জাহান্নামের আযাব।'),
  ('bn.bengali', 59, 4, 'এটা এ কারণে যে, তারা আল্লাহ ও তাঁর রসূলের বিরুদ্ধাচরণ করেছে। যে আল্লাহর বিরুদ্ধাচরণ করে, তার জানা উচিত যে, আল্লাহ কঠোর শাস্তিদাতা।'),
  ('bn.bengali', 59, 5, 'তোমরা যে কিছু কিছু খর্জুর বৃক্ষ কেটে দিয়েছ এবং কতক না কেটে ছেড়ে দিয়েছ, তা তো আল্লাহরই আদেশ এবং যাতে তিনি অবাধ্যদেরকে লাঞ্ছিত করেন।'),
  ('bn.bengali', 59, 6, 'আল্লাহ বনু-বনুযায়রের কাছ থেকে তাঁর রসূলকে যে ধন-সম্পদ দিয়েছেন, তজ্জন্যে তোমরা ঘোড়ায় কিংবা উটে চড়ে যুদ্ধ করনি, কিন্তু আল্লাহ যার উপর ইচ্ছা, তাঁর রসূলগণকে প্রাধান্য দান করেন। আল্লাহ সবকিছুর উপর সর্বশক্তিমান।'),
  ('bn.bengali', 59, 7, 'আল্লাহ জনপদবাসীদের কাছ থেকে তাঁর রসূলকে যা দিয়েছেন, তা আল্লাহর, রসূলের, তাঁর আত্নীয়-স্বজনের, ইয়াতীমদের, অভাবগ্রস্তদের এবং মুসাফিরদের জন্যে, যাতে ধনৈশ্বর্য্য কেবল তোমাদের বিত্তশালীদের মধ্যেই পুঞ্জীভূত না হয়। রসূল তোমাদেরকে যা দেন, তা গ্রহণ কর এবং যা নিষেধ করেন, তা থেকে বিরত থাক এবং আল্লাহকে ভয় কর। নিশ্চয় আল্লাহ কঠোর শাস্তিদাতা।'),
  ('bn.bengali', 59, 8, 'এই ধন-সম্পদ দেশত্যাগী নিঃস্বদের জন্যে, যারা আল্লাহর অনুগ্রহ ও সন্তুষ্টিলাভের অন্বেষণে এবং আল্লাহ তাঁর রসূলের সাহায্যার্থে নিজেদের বাস্তুভিটা ও ধন-সম্পদ থেকে বহিস্কৃত হয়েছে। তারাই সত্যবাদী।'),
  ('bn.bengali', 59, 9, 'যারা মুহাজিরদের আগমনের পূর্বে মদীনায় বসবাস করেছিল এবং বিশ্বাস স্থাপন করেছিল, তারা মুহাজিরদের ভালবাসে, মুহাজিরদেরকে যা দেয়া হয়েছে, তজ্জন্যে তারা অন্তরে ঈর্ষাপোষণ করে না এবং নিজেরা অভাবগ্রস্ত হলেও তাদেরকে অগ্রাধিকার দান করে। যারা মনের কার্পণ্য থেকে মুক্ত, তারাই সফলকাম।'),
  ('bn.bengali', 59, 10, 'আর এই সম্পদ তাদের জন্যে, যারা তাদের পরে আগমন করেছে। তারা বলেঃ হে আমাদের পালনকর্তা, আমাদেরকে এবং ঈমানে আগ্রহী আমাদের ভ্রাতাগণকে ক্ষমা কর এবং ঈমানদারদের বিরুদ্ধে আমাদের অন্তরে কোন বিদ্বেষ রেখো না। হে আমাদের পালনকর্তা, আপনি দয়ালু, পরম করুণাময়।'),
  ('bn.bengali', 59, 11, 'আপনি কি মুনাফিকদেরকে দেখেন নি? তারা তাদের কিতাবধারী কাফের ভাইদেরকে বলেঃ তোমরা যদি বহিস্কৃত হও, তবে আমরা অবশ্যই তোমাদের সাথে দেশ থেকে বের হয়ে যাব এবং তোমাদের ব্যাপারে আমরা কখনও কারও কথা মানব না। আর যদি তোমরা আক্রান্ত হও, তবে আমরা অবশ্যই তোমাদেরকে সাহায্য করব। আল্লাহ তা’আলা সাক্ষ্য দেন যে, ওরা নিশ্চয়ই মিথ্যাবাদী।'),
  ('bn.bengali', 59, 12, 'যদি তারা বহিস্কৃত হয়, তবে মুনাফিকরা তাদের সাথে দেশত্যাগ করবে না আর যদি তারা আক্রান্ত হয়, তবে তারা তাদেরকে সাহায্য করবে না। যদি তাদেরকে সাহায্য করে, তবে অবশ্যই পৃষ্ঠপ্রদর্শন করে পলায়ন করবে। এরপর কাফেররা কোন সাহায্য পাবে না।'),
  ('bn.bengali', 59, 13, 'নিশ্চয় তোমরা তাদের অন্তরে আল্লাহ তা’আলা অপেক্ষা অধিকতর ভয়াবহ। এটা এ কারণে যে, তারা এক নির্বোধ সম্প্রদায়।'),
  ('bn.bengali', 59, 14, 'তারা সংঘবদ্ধভাবেও তোমাদের বিরুদ্ধে যুদ্ধ করতে পারবে না। তারা যুদ্ধ করবে কেবল সুরক্ষিত জনপদে অথবা দুর্গ প্রাচীরের আড়াল থেকে। তাদের পারস্পরিক যুদ্ধই প্রচন্ড হয়ে থাকে। আপনি তাদেরকে ঐক্যবদ্ধ মনে করবেন; কিন্তু তাদের অন্তর শতধাবিচ্ছিন্ন। এটা এ কারণে যে, তারা এক কান্ডজ্ঞানহীণ সম্প্রদায়।'),
  ('bn.bengali', 59, 15, 'তারা সেই লোকদের মত, যারা তাদের নিকট অতীতে নিজেদের কর্মের শাস্তিভোগ করেছে। তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 59, 16, 'তারা শয়তানের মত, যে মানুষকে কাফের হতে বলে। অতঃপর যখন সে কাফের হয়, তখন শয়তান বলেঃ তোমার সাথে আমার কোন সম্পর্ক নেই। আমি বিশ্বপালনকর্তা আল্লাহ তা’আলাকে ভয় করি।'),
  ('bn.bengali', 59, 17, 'অতঃপর উভয়ের পরিণতি হবে এই যে, তারা জাহান্নামে যাবে এবং চিরকাল তথায় বসবাস করবে। এটাই জালেমদের শাস্তি।'),
  ('bn.bengali', 59, 18, 'মুমিনগণ, তোমরা আল্লাহ তা’আলাকে ভয় কর। প্রত্যেক ব্যক্তির উচিত, আগামী কালের জন্যে সে কি প্রেরণ করে, তা চিন্তা করা। আল্লাহ তা’আলাকে ভয় করতে থাক। তোমরা যা কর, আল্লাহ তা’আলা সে সম্পর্কে খবর রাখেন।'),
  ('bn.bengali', 59, 19, 'তোমরা তাদের মত হয়ো না, যারা আল্লাহ তা’আলাকে ভুলে গেছে। ফলে আল্লাহ তা’আলা তাদেরকে আত্ন বিস্মৃত করে দিয়েছেন। তারাই অবাধ্য।'),
  ('bn.bengali', 59, 20, 'জাহান্নামের অধিবাসী এবং জান্নাতের অধিবাসী সমান হতে পারে না। যারা জান্নাতের অধিবাসী, তারাই সফলকাম।'),
  ('bn.bengali', 59, 21, 'যদি আমি এই কোরআন পাহাড়ের উপর অবতীর্ণ করতাম, তবে তুমি দেখতে যে, পাহাড় বিনীত হয়ে আল্লাহ তা’আলার ভয়ে বিদীর্ণ হয়ে গেছে। আমি এসব দৃষ্টান্ত মানুষের জন্যে বর্ণনা করি, যাতে তারা চিন্তা-ভাবনা করে।'),
  ('bn.bengali', 59, 22, 'তিনিই আল্লাহ তা’আলা, তিনি ব্যতীত কোন উপাস্য নেই; তিনি দৃশ্য ও অদৃশ্যকে জানেন তিনি পরম দয়ালু, অসীম দাতা।'),
  ('bn.bengali', 59, 23, 'তিনিই আল্লাহ তিনি ব্যতিত কোন উপাস্য নেই। তিনিই একমাত্র মালিক, পবিত্র, শান্তি ও নিরাপত্তাদাতা, আশ্রয়দাতা, পরাক্রান্ত, প্রতাপান্বিত, মাহাত্ন?486;ীল। তারা যাকে অংশীদার করে আল্লাহ তা’ আলা তা থেকে পবিত্র।'),
  ('bn.bengali', 59, 24, 'তিনিই আল্লাহ তা’আলা, স্রষ্টা, উদ্ভাবক, রূপদাতা, উত্তম নাম সমূহ তাঁরই। নভোমন্ডলে ও ভূমন্ডলে যা কিছু আছে, সবই তাঁর পবিত্রতা ঘোষণা করে। তিনি পরাক্রান্ত প্রজ্ঞাময়।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 59, 1, 'All that is in the heavens and all that is in the earth glorifieth Allah, and He is the Mighty, the Wise.'),
  ('en.pickthall', 59, 2, 'He it is Who hath caused those of the People of the Scripture who disbelieved to go forth from their homes unto the first exile. Ye deemed not that they would go forth, while they deemed that their strongholds would protect them from Allah. But Allah reached them from a place whereof they recked not, and cast terror in their hearts so that they ruined their houses with their own hands and the hands of the believers. So learn a lesson, O ye who have eyes!'),
  ('en.pickthall', 59, 3, 'And if Allah had not decreed migration for them, He verily would have punished them in the world, and theirs in the Hereafter is the punishment of the Fire.'),
  ('en.pickthall', 59, 4, 'That is because they were opposed to Allah and His messenger; and whoso is opposed to Allah, (for him) verily Allah is stern in reprisal.'),
  ('en.pickthall', 59, 5, 'Whatsoever palm-trees ye cut down or left standing on their roots, it was by Allah\'s leave, in order that He might confound the evil-livers.'),
  ('en.pickthall', 59, 6, 'And that which Allah gave as spoil unto His messenger from them, ye urged not any horse or riding-camel for the sake thereof, but Allah giveth His messenger lordship over whom He will. Allah is Able to do all things.'),
  ('en.pickthall', 59, 7, 'That which Allah giveth as spoil unto His messenger from the people of the townships, it is for Allah and His messenger and for the near of kin and the orphans and the needy and the wayfarer, that it become not a commodity between the rich among you. And whatsoever the messenger giveth you, take it. And whatsoever he forbiddeth, abstain (from it). And keep your duty to Allah. Lo! Allah is stern in reprisal.'),
  ('en.pickthall', 59, 8, 'And (it is) for the poor fugitives who have been driven out from their homes and their belongings, who seek bounty from Allah and help Allah and His messenger. They are the loyal.'),
  ('en.pickthall', 59, 9, 'Those who entered the city and the faith before them love those who flee unto them for refuge, and find in their breasts no need for that which hath been given them, but prefer (the fugitives) above themselves though poverty become their lot. And whoso is saved from his own avarice - such are they who are successful.'),
  ('en.pickthall', 59, 10, 'And those who came (into the faith) after them say: Our Lord! Forgive us and our brethren who were before us in the faith, and place not in our hearts any rancour toward those who believe. Our Lord! Thou art Full of Pity, Merciful.'),
  ('en.pickthall', 59, 11, 'Hast thou not observed those who are hypocrites, (how) they tell their brethren who disbelieve among the People of the Scripture: If ye are driven out, we surely will go out with you, and we will never obey anyone against you, and if ye are attacked we verily will help you. And Allah beareth witness that they verily are liars.'),
  ('en.pickthall', 59, 12, '(For) indeed if they are driven out they go not out with them, and indeed if they are attacked they help them not, and indeed if they had helped them they would have turned and fled, and then they would not have been victorious.'),
  ('en.pickthall', 59, 13, 'Ye are more awful as a fear in their bosoms than Allah. That is because they are a folk who understand not.'),
  ('en.pickthall', 59, 14, 'They will not fight against you in a body save in fortified villages or from behind walls. Their adversity among themselves is very great. Ye think of them as a whole whereas their hearts are divers. That is because they are a folk who have no sense.'),
  ('en.pickthall', 59, 15, 'On the likeness of those (who suffered) a short time before them, they taste the ill-effects of their own conduct, and theirs is painful punishment.'),
  ('en.pickthall', 59, 16, '(And the hypocrites are) on the likeness of the devil when he telleth man to disbelieve, then, when he disbelieveth saith: Lo! I am quit of thee. Lo! I fear Allah, the Lord of the Worlds.'),
  ('en.pickthall', 59, 17, 'And the consequence for both will be that they are in the Fire, therein abiding. Such is the reward of evil-doers.'),
  ('en.pickthall', 59, 18, 'O ye who believe! Observe your duty to Allah. And let every soul look to that which it sendeth on before for the morrow. And observe your duty to Allah. Lo! Allah is Informed of what ye do.'),
  ('en.pickthall', 59, 19, 'And be not ye as those who forgot Allah, therefor He caused them to forget their souls. Such are the evil-doers.'),
  ('en.pickthall', 59, 20, 'Not equal are the owners of the Fire and the owners of the Garden. The owners of the Garden, they are the victorious.'),
  ('en.pickthall', 59, 21, 'If We had caused this Qur\'an to descend upon a mountain, thou (O Muhammad) verily hadst seen it humbled, rent asunder by the fear of Allah. Such similitudes coin We for mankind that haply they may reflect.'),
  ('en.pickthall', 59, 22, 'He is Allah, than Whom there is no other Allah, the Knower of the Invisible and the Visible. He is the Beneficent, Merciful.'),
  ('en.pickthall', 59, 23, 'He is Allah, than Whom there is no other Allah, the Sovereign Lord, the Holy One, Peace, the Keeper of Faith, the Guardian, the Majestic, the Compeller, the Superb. Glorified be Allah from all that they ascribe as partner (unto Him).'),
  ('en.pickthall', 59, 24, 'He is Allah, the Creator, the Shaper out of naught, the Fashioner. His are the most beautiful names. All that is in the heavens and the earth glorifieth Him, and He is the Mighty, the Wise.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 59, 1, 'Whatever is in the heavens and on earth, let it declare the Praises and Glory of Allah: for He is the Exalted in Might, the Wise.'),
  ('en.yusufali', 59, 2, 'It is He Who got out the Unbelievers among the People of the Book from their homes at the first gathering (of the forces). Little did ye think that they would get out: And they thought that their fortresses would defend them from Allah! But the (Wrath of) Allah came to them from quarters from which they little expected (it), and cast terror into their hearts, so that they destroyed their dwellings by their own hands and the hands of the Believers, take warning, then, O ye with eyes (to see)!'),
  ('en.yusufali', 59, 3, 'And had it not been that Allah had decreed banishment for them, He would certainly have punished them in this world: And in the Hereafter they shall (certainly) have the Punishment of the Fire.'),
  ('en.yusufali', 59, 4, 'That is because they resisted Allah and His Messenger: and if any one resists Allah, verily Allah is severe in Punishment.'),
  ('en.yusufali', 59, 5, 'Whether ye cut down (O ye Muslim!) The tender palm-trees, or ye left them standing on their roots, it was by leave of Allah, and in order that He might cover with shame the rebellious transgresses.'),
  ('en.yusufali', 59, 6, 'What Allah has bestowed on His Messenger (and taken away) from them - for this ye made no expedition with either cavalry or camelry: but Allah gives power to His messengers over any He pleases: and Allah has power over all things.'),
  ('en.yusufali', 59, 7, 'What Allah has bestowed on His Messenger (and taken away) from the people of the townships,- belongs to Allah,- to His Messenger and to kindred and orphans, the needy and the wayfarer; In order that it may not (merely) make a circuit between the wealthy among you. So take what the Messenger assigns to you, and deny yourselves that which he withholds from you. And fear Allah; for Allah is strict in Punishment.'),
  ('en.yusufali', 59, 8, '(Some part is due) to the indigent Muhajirs, those who were expelled from their homes and their property, while seeking Grace from Allah and (His) Good Pleasure, and aiding Allah and His Messenger: such are indeed the sincere ones:-'),
  ('en.yusufali', 59, 9, 'But those who before them, had homes (in Medina) and had adopted the Faith,- show their affection to such as came to them for refuge, and entertain no desire in their hearts for things given to the (latter), but give them preference over themselves, even though poverty was their (own lot). And those saved from the covetousness of their own souls,- they are the ones that achieve prosperity.'),
  ('en.yusufali', 59, 10, 'And those who came after them say: "Our Lord! Forgive us, and our brethren who came before us into the Faith, and leave not, in our hearts, rancour (or sense of injury) against those who have believed. Our Lord! Thou art indeed Full of Kindness, Most Merciful."'),
  ('en.yusufali', 59, 11, 'Hast thou not observed the Hypocrites say to their misbelieving brethren among the People of the Book? - "If ye are expelled, we too will go out with you, and we will never hearken to any one in your affair; and if ye are attacked (in fight) we will help you". But Allah is witness that they are indeed liars.'),
  ('en.yusufali', 59, 12, 'If they are expelled, never will they go out with them; and if they are attacked (in fight), they will never help them; and if they do help them, they will turn their backs; so they will receive no help.'),
  ('en.yusufali', 59, 13, 'Of a truth ye are stronger (than they) because of the terror in their hearts, (sent) by Allah. This is because they are men devoid of understanding.'),
  ('en.yusufali', 59, 14, 'They will not fight you (even) together, except in fortified townships, or from behind walls. Strong is their fighting (spirit) amongst themselves: thou wouldst think they were united, but their hearts are divided: that is because they are a people devoid of wisdom.'),
  ('en.yusufali', 59, 15, 'Like those who lately preceded them, they have tasted the evil result of their conduct; and (in the Hereafter there is) for them a grievous Penalty;-'),
  ('en.yusufali', 59, 16, '(Their allies deceived them), like the Evil One, when he says to man, "Deny Allah": but when (man) denies Allah, (the Evil One) says, "I am free of thee: I do fear Allah, the Lord of the Worlds!"'),
  ('en.yusufali', 59, 17, 'The end of both will be that they will go into the Fire, dwelling therein for ever. Such is the reward of the wrong-doers.'),
  ('en.yusufali', 59, 18, 'O ye who believe! Fear Allah, and let every soul look to what (provision) He has sent forth for the morrow. Yea, fear Allah: for Allah is well-acquainted with (all) that ye do.'),
  ('en.yusufali', 59, 19, 'And be ye not like those who forgot Allah; and He made them forget their own souls! Such are the rebellious transgressors!'),
  ('en.yusufali', 59, 20, 'Not equal are the Companions of the Fire and the Companions of the Garden: it is the Companions of the Garden, that will achieve Felicity.'),
  ('en.yusufali', 59, 21, 'Had We sent down this Qur\'an on a mountain, verily, thou wouldst have seen it humble itself and cleave asunder for fear of Allah. Such are the similitudes which We propound to men, that they may reflect.'),
  ('en.yusufali', 59, 22, 'Allah is He, than Whom there is no other god;- Who knows (all things) both secret and open; He, Most Gracious, Most Merciful.'),
  ('en.yusufali', 59, 23, 'Allah is He, than Whom there is no other god;- the Sovereign, the Holy One, the Source of Peace (and Perfection), the Guardian of Faith, the Preserver of Safety, the Exalted in Might, the Irresistible, the Supreme: Glory to Allah! (High is He) above the partners they attribute to Him.'),
  ('en.yusufali', 59, 24, 'He is Allah, the Creator, the Evolver, the Bestower of Forms (or Colours). To Him belong the Most Beautiful Names: whatever is in the heavens and on earth, doth declare His Praises and Glory: and He is the Exalted in Might, the Wise.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 59, 1, 'Sabbaha lillaahi maa fissamaawaati wa maa fil ardi wa Huwal \'Azeezul Hakeem'),
  ('en.transliteration', 59, 2, 'Huwal lazeee akharajal lazeena kafaroo min ahlil kitaabi min diyaarihim li awwalil Hashr; maa zanantum any yakhrujoo wa zannooo annahum maa ni\'atuhum husoonuhum minal laahi faataahumul laahu min haisu lam yahtasiboo wa qazafa fee quloobihimur ru\'ba yukhriboona bu yootahum bi aydeehim wa aydil mu\'mineena fa\'tabiroo yaaa ulil absaar'),
  ('en.transliteration', 59, 3, 'Wa law laaa an katabal laahu \'alaihimul jalaaa\'a la\'azzabahum fid dunyaa wa lahum fil Aakhirati \'azaabun Naar'),
  ('en.transliteration', 59, 4, 'Zaalika bi annahum shaaqqul laaha wa Rasoolahoo wa many yushaaaqqil laaha fa innal laaha shadeedul-\'iqaab'),
  ('en.transliteration', 59, 5, 'Maa qata\'tum mil leenatin aw taraktumoohaa qaaa\'imatan\'alaaa usoolihaa fabi iznil laahi wa liyukhziyal faasiqeen'),
  ('en.transliteration', 59, 6, 'Wa maaa afaaa\'al laahu \'alaaa Rasoolihee minhum famaaa awjaftum \'alaihi min khailiinw wa laa rikaabinw wa laakinnal laaha yusallitu Rusulahoo \'alaa many yashaaa\'; wallaahu \'alaa kulli shai\'in Qadeer'),
  ('en.transliteration', 59, 7, 'Maaa afaaa\'al laahu \'alaa Rasoolihee min ahlil quraa falillaahi wa lir Rasooli wa lizil qurbaa wal yataamaa walmasaakeeni wabnis sabeeli kai laa yakoona doolatam bainal aghniyaaa\'i minkum; wa maaa aataakumur Rasoolu fakhuzoohu wa maa nahaakum \'anhu fantahoo; wattaqul laaha innal laaha shadeedul-\'iqaab'),
  ('en.transliteration', 59, 8, 'Lilfuqaraaa\'il Muhaaji reenal lazeena ukhrijoo min diyaarihim wa amwaalihim yabtaghoona fadlam minal laahi wa ridwaananw wa yansuroonal laaha wa Rasoolah; ulaaa\'ika humus saadiqoon'),
  ('en.transliteration', 59, 9, 'Wallazeena tabawwa\'ud daara wal eemaana min qablihim yuhibboona man haajara ilaihim wa laa yajidoona fee sudoorihim haajatam mimmaa ootoo wa yu\'siroona \'alaa anfusihim wa law kaana bihim khasaasah; wa many yooqa shuhha nafsihee fa ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 59, 10, 'Wallazeena jaaa\'oo min ba\'dihim yaqooloona Rabbanagh fir lanaa wa li ikhwaani nal lazeena sabqoonaa bil eemaani wa laa taj\'al fee quloobinaa ghillalil lazeena aamanoo rabbannaaa innaka Ra\'oofur Raheem'),
  ('en.transliteration', 59, 11, 'Alam tara ilal lazeena naafaqoo yaqooloona li ikhwaanihimul lazeena kafaroo min ahlil kitaabi la\'in ukhrijtum lanakhrujanna ma\'akum wa laa nutee\'u feekum ahadan abadanw-wa in qootiltum lanansuran nakum wallaahu yashhadu innahum lakaaziboon'),
  ('en.transliteration', 59, 12, 'La\'in ukhrijoo laa yakhrujoona ma\'ahum wa la\'in qootiloo laa yansuroonahum wa la\'in nasaroohum la yuwallunnal adbaara summa laa yunsaroon'),
  ('en.transliteration', 59, 13, 'La antum ashaddu rahbatan fee sudoorihim minal laah; zaalika bi annahum qawmul laa yafqahoon'),
  ('en.transliteration', 59, 14, 'Laa yuqaatiloonakum jamee\'an illaa fee quram muhas sanatin aw minw waraaa\'i judur; baasuhum bainahum shadeed; tahsabuhum jamee\'anw-wa quloobuhum shatta; zaalika biannahum qawmul laa ya\'qiloon'),
  ('en.transliteration', 59, 15, 'Kamasalil lazeena min qablihim qareeban zaaqoo wabaala amrihim wa lahum \'azaabun aleem'),
  ('en.transliteration', 59, 16, 'Kamasalish shaitaani izqaala lil insaanik fur falammaa kafara qaala innee bareee\'um minka inneee akhaaful laaha rabbal \'aalameen'),
  ('en.transliteration', 59, 17, 'Fakaana \'aaqibatahumaaa annahumaa fin naari khaalidaini feehaa; wa zaalika jazaaa\'uz zaalimeen'),
  ('en.transliteration', 59, 18, 'Yaaa ayyuhal lazeena aamanut taqul laa; waltanzur nafsum maa qaddamat lighadiw wattaqual laah; innal laaha khabeerum bimaa ta\'maloon'),
  ('en.transliteration', 59, 19, 'Wa laa takoonoo kallazeena nasul laaha fa ansaahum anfusahum; ulaaa\'ika humul faasiqoon'),
  ('en.transliteration', 59, 20, 'Laa yastaweee as-haabun naari wa ashaabul jannah; as haabul jannati humul faaa\'izoon'),
  ('en.transliteration', 59, 21, 'Law anzalnaa haazal quraana \'alaa jabilil lara aytahoo khaashi\'am muta saddi\'am min khashiyatil laah; wa tilkal amsaalu nadribuhaa linnaasi la\'allahum yatafakkaroon'),
  ('en.transliteration', 59, 22, 'Huwal-laahul-lazee laaa Ilaaha illaa Huwa \'Aalimul Ghaibi wash-shahaada; Huwar Rahmaanur-Raheem'),
  ('en.transliteration', 59, 23, 'Huwal-laahul-lazee laaa Ilaaha illaa Huwal-Malikul Quddoosus-Salaamul Muminul Muhaiminul-\'aAzeezul Jabbaarul-Mutakabbir; Subhaanal laahi \'Ammaa yushrikoon'),
  ('en.transliteration', 59, 24, 'Huwal Laahul Khaaliqul Baari \'ul Musawwir; lahul Asmaaa\'ul Husnaa; yusabbihu lahoo maa fis samaawaati wal ardi wa Huwal \'Azeezul Hakeem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 59, 1, 'جو مخلوقات آسمانوں میں ہے اور جو زمین میں ہے الله کی تسبیح کرتی ہے اور وہی غالب حکمت والا ہے'),
  ('ur.ahmedali', 59, 2, 'وہی ہے جس نے اہلِ کتاب کے کافروں کو ان کے گھروں سے پہلا لشکر جمع کرنے کے وقت نکال دیا حالانکہ تمہیں ان کے نکلنے کا گمان بھی نہ تھا اور وہ یہی سمجھ رہے تھے کہ ان کے قلعے انہیں الله سے بچا لیں گے پھر الله کا عذاب ان پر وہاں سے آیا کہ جہاں کا ان کو گمان بھی نہ تھا اوران کے دلوں میں ہیبت ڈال دی کہ اپنے گھر وں کو اپنے اورمسلمانوں کے ہاتھوں سے آپ اجاڑنے لگے پس اے آنکھوں والو عبرت حاصل کرو'),
  ('ur.ahmedali', 59, 3, 'اوراگر الله نے ان کے لیے دیس نکالا نہ لکھ دیا ہوتا تو انہیں دنیا ہی میں سزا دیتا اور آخرت میں تو ان کے لیے آگ کا عذاب ہے'),
  ('ur.ahmedali', 59, 4, 'یہ ا سلیے کہ انہوں نے الله اوراس کے رسول کی مخالفت کی اور جو الله کی مخالفت کرے تو بے شک الله سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 59, 5, 'مسلمانوں تم نے جو کھجور کا پیڑ کاٹ ڈالا یا اس کو اس کی جڑوں پر کھڑا رہنے دیا یہ سب الله کے حکم سے ہوا اور تاکہ وہ نافرمانوں کو ذلیل کرے'),
  ('ur.ahmedali', 59, 6, 'اور جوکچھ الله نے اپنے رسول کو ان سے مفت دلا دیا سو تم نے اس پر گھوڑے نہیں دوڑائے اور نہ اونٹ لیکن الله اپنے رسولوں کو غالب کر دیتا ہے جس پر چاہے اور الله ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 59, 7, 'جو مال الله نے اپنےرسول کو دیہات والوں سے مفت دلایا سو وہ الله اور رسول اور قرابت والوں اور یتمیموں اور مسکینوں اور مسافروں کے لیے ہے تاکہ وہ تمہارے دولتمندوں میں نہ پھرتا رہے اور جو کچھ تمہیں رسول دے اسے لے لو اور جس سے منع کرے اس سے باز رہو اور الله سے ڈرو بیشک الله سخت عذاب دینے والا ہے'),
  ('ur.ahmedali', 59, 8, 'وہ مال وطن چھوڑنے والے مفلسوں کے لیے بھی ہے جو اپنے گھروں اور مالوں سے نکالے گئے الله کا فضل اس کی رضا مندی چاہتے ہیں اوروہ الله اور اس کے رسول کی مدد کرتے ہیں یہی سچے (مسلمان) ہیں'),
  ('ur.ahmedali', 59, 9, 'اور وہ (مال) ان کے لیے بھی ہے کہ جنہوں نے ان سے پہلے (مدینہ میں) گھر اور ایمان حاصل کر رکھا ہے جو ان کے پاس وطن چھوڑ کرآتا ہے اس سے محبت کرتے ہیں اور اپنے سینوں میں اس کی نسبت کوئی خلش نہیں پاتے جو مہاجرین کو دیا جائے اور وہ اپنی جانوں پر ترجیح دیتے ہیں اگرچہ ان پر فاقہ ہو اور جو اپنے نفس کے لالچ سے بچایا جائے پس وہی لوگ کامیاب ہیں'),
  ('ur.ahmedali', 59, 10, 'اور ان کے لیے بھی جو مہاجرین کے بعد آئے (اور) دعا مانگا کرتے ہیں کہ اے ہمارے رب ہمیں اور ہمارےان بھائیوں کو بخش دے جو ہم سے پہلے ایمان لائے ہیں اور ہمارے دلوں میں ایمانداروں کی طرف سے کینہ قائم نہ ہونے پائے اے ہمارے رب بے شک تو بڑا مہربان نہایت رحم والا ہے'),
  ('ur.ahmedali', 59, 11, 'کیا آپ نے منافقوں کو نہیں دیکھا جواپنے اہل کتاب کے کافر بھائیوں سے کہتے ہیں کہ اگر تم نکالے گئے تو ضرور ہم بھی تمہارے ساتھ نکلیں گے اور تمہارے معاملہ میں کبھی کسی کی بات نہ مانیں گے اور اگر تم سے لڑائی ہو گی تو ہم تمہاری مدد کریں گے اور الله گواہی دیتا ہے کہ وہ سراسر جھوٹے ہیں'),
  ('ur.ahmedali', 59, 12, 'اگر وہ نکالے گئے تو یہ ان کے ساتھ نہ نکلیں گے اور اگر ان سے لڑائی ہوئی تو یہ ان کی مدد بھی نہ کریں گے اور اگر ان کی مدد کریں گے تو پیٹھ پھیر کر بھاگیں گے پھر ان کو مدد نہ دی جائے گی'),
  ('ur.ahmedali', 59, 13, 'البتہ تمہارا خوف ان کے دلوں میں الله (کے خوف) سے زیادہ ہے یہ اس لیے کہ وہ لوگ سمجھتے نہیں'),
  ('ur.ahmedali', 59, 14, 'وہ تم سے سب ملکر بھی نہیں لڑ سکتے مگر محفوظ بستیوں میں یا دیواروں کی آڑ میں ان کی لڑائی تو آپس میں سخت ہے آپ ان کو متفق سمجھتے ہیں حالانکہ ان کے دل الگ الگ ہیں یہ اس لیے کہ وہ لوگ عقل نہیں رکھتے'),
  ('ur.ahmedali', 59, 15, 'ان کا حال تو پہلوں جیسا ہے کہ جنہوں نے ابھی اپنے کام کی سزا پائی ہے اور ان کے لیے (آخرت میں) دردناک عذاب ہے'),
  ('ur.ahmedali', 59, 16, '(اور) مشال شیطان کی سی ہے کہ وہ آدمی سے کہتا ہے کہ تو منکر ہو جا پھر جب وہ منکر ہو جاتا ہے تو کہتا ہے بے شک میں تم سے بری ہوں کیوں کہ میں الله سے ڈرتا ہوں جو سارے جہاں کا رب ہے'),
  ('ur.ahmedali', 59, 17, 'پس ان دونوں کا انجام یہ ہوتا ہے کہ وہ دونوں دوزخ میں ہوں گے اس میں ہمیشہ رہیں گے اور ظالموں کی یہی سزا ہے'),
  ('ur.ahmedali', 59, 18, 'اے ایمان والو الله سے ڈرو اور ہر شخص کو دیکھنا چاہیئے کہ اس نے کل کے لئے کیا آگے بھیجا ہے اور الله سے ڈرو کیوں کہ الله تمہارے کاموں سے خبردار ہے'),
  ('ur.ahmedali', 59, 19, 'اور ان کی طرح نہ ہوں جنہوں نے الله کو بھلا دیاپھر الله نے بھی ان کو (ایسا کر دیا) کہ وہ اپنے آپ ہی کو بھول گئے یہی لوگ نافرمان ہیں'),
  ('ur.ahmedali', 59, 20, 'دوزخی اور جنتی برابر نہیں ہو سکتے جنتّی ہی بامراد ہیں'),
  ('ur.ahmedali', 59, 21, 'اگر ہم اس قرآن کو کسی پہاڑ پرنازل کرتے تو آپ اسے دیکھتے کہ الله کے خوف سے جھک کر پھٹ جاتا اور ہم یہ مثالیں لوگوں کے لیے بیان کرتے ہیں تاکہ وہ غور کریں'),
  ('ur.ahmedali', 59, 22, 'وہی الله ہے کہ اس کے سوا کوئی معبود نہیں سب چھپی اور کھلی باتوں کا جاننے والا ہے وہ بڑا مہربان نہایت رحم والا ہے'),
  ('ur.ahmedali', 59, 23, 'وہی الله ہے کہ اس کے سوا کوئی معبود نہیں وہ بادشاہ پاک ذات سلامتی دینے والا امن دینے والا نگہبان زبردست خرابی کا درست کرنے والا بڑی عظمت والا ہے الله پاک ہے اس سے جو اس کے شریک ٹھیراتے ہیں'),
  ('ur.ahmedali', 59, 24, 'وہی الله ہے پیدا کرنے والا ٹھیک ٹھیک بنانے والا صورت دینے والا اس کے اچھے اچھے نام ہیں سب چیزیں اسی کی تسبیح کرتی ہیں جو آسمانوں میں اور زمین میں ہیں اور وہی زبردست حکمت والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 59, 1, 'Göklerde olanlar da yerde olanlar da Allah\'ı tesbih ederler. O güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 59, 2, 'Kitap ehlinden inkarcı olanları ilk sürgünde yurtlarından çıkaran O\'dur. Oysa ey inananlar! Çıkacaklarını sanmamıştınız, onlar da, kalelerinin kendilerini Allah\'tan koruyacağını sanmışlardı. Ama Allah\'ın azabı onlara beklemedikleri yerden geldi, kalblerine korku saldı; evlerini kendi elleriyle ve inananların elleriyle yıkıyorlardı. Ey akıl sahipleri! Ders alın.'),
  ('tr.diyanet', 59, 3, 'Allah onlara sürülmeyi yazmamış olsaydı, dünyada başka şekilde azap verecekti. Ahirette onlara ateş azabı vardır.'),
  ('tr.diyanet', 59, 4, 'Bu, Allah\'a ve Peygamberine karşı gelmelerinden ötürüdür. Kim Allah\'a karşı gelirse bilsin ki Allah\'ın cezalandırması şüphesiz çetindir.'),
  ('tr.diyanet', 59, 5, 'İnkarcı kitap ehlinin yurtlarında hurma ağaçlarını kesmeniz veya onları kesmeyip gövdeleri üzerinde ayakta bırakmanız Allah\'ın izniyledir. Allah yoldan çıkanları böylece rezilliğe uğratır.'),
  ('tr.diyanet', 59, 6, 'Ey inananlar! Onların mallarından, Allah\'ın Peygamberine verdiği şeyler için siz ne at ve ne de deve sürdünüz; fakat Allah peygamberlerine, dilediği kimselere karşı üstünlük verir. Allah herşeye Kadir\'dir.'),
  ('tr.diyanet', 59, 7, 'Allah\'ın, fethedilen memleketler halkının mallarından Peygamberine verdikleri; Allah, Peygamber, yakınlar, yetimler, yoksullar ve yolda kalmışlar içindir; ta ki içinizdeki zenginler arasında elden ele dolaşan bir devlet olmasın. Peygamber size ne verirse onu alın, sizi neden menederse ondan geri durun; Allah\'tan sakının, doğrusu Allah\'ın cezalandırması çetindir.'),
  ('tr.diyanet', 59, 8, 'Allah\'ın verdiği bu ganimet malları bilhassa; yurtlarından ve mallarından edilmiş olan, Allah\'tan bir lütuf ve rıza dileyen, Allah\'ın dinine ve Peygamberine yardım eden muhacir fakirlerindir. İşte doğru olanlar bunlardır.'),
  ('tr.diyanet', 59, 9, 'Daha önceden Medine\'yi yurt edinmiş ve gönüllerine imanı yerleştirmiş olan kimseler, kendilerine hicret edip gelenleri severler; onlara verilenler karşısında içlerinde bir çekememezlik hissetmezler; kendileri zaruret içinde bulunsalar bile onları kendilerinden önde tutarlar. Nefsinin tamahkarlığından korunabilmiş kimseler, işte onlar saadete erenlerdir.'),
  ('tr.diyanet', 59, 10, 'Onlardan sonra gelenler: "Rabbimiz! Bizi ve bizden önce inanmış olan kardeşlerimizi bağışla; kalbimizde müminlere karşı kin bırakma; Rabbimiz! Şüphesiz Sen şefkatlisin, merhametlisin" derler.'),
  ('tr.diyanet', 59, 11, 'Münafıkların, kitap ehlinin inkarcılarından olan kardeşlerine: "Eğer siz yurdunuzdan çıkarılırsanız and olsun ki, biz de sizinle beraber çıkarız; sizin aleyhinizde kimseye asla uymayız; eğer savaşa tutuşursanız mutlaka size yardım ederiz" dediklerini görmedin mi? Allah onların yalancı olduklarına şahidlik eder.'),
  ('tr.diyanet', 59, 12, 'Onlar çıkarılmış olsalar, and olsun ki, onlarla beraber çıkmazlar; savaşa tutuşmuş olsalar, and olsun ki, onlara yardıma koşmazlar; onlara yardıma gitseler, mutlaka geri dönüp kaçarlar, sonra yardım da görmezler.'),
  ('tr.diyanet', 59, 13, 'Ey inananlar! Onların yüreklerine korku salan, Allah\'tan çok sizlersiniz; çünkü onlar, anlamayan kimselerdir.'),
  ('tr.diyanet', 59, 14, 'Onlar sizinle toplu olarak, ancak surla çevrilmiş kasabalar içinde veya duvarlar arkasından savaşı kabul edebilirler. Kendi aralarındaki çekişmeleri ise serttir; onları birlik sanırsın, oysa kalbleri birbirinden ayrıdır. Bu, akletmeyen bir topluluk olmalarındandır.'),
  ('tr.diyanet', 59, 15, 'Onların durumu, kendilerinden az zaman önce geçmiş ve işlerinin karşılığını tatmış olanların durumu gibidir. Onlara can yakıcı azap vardır.'),
  ('tr.diyanet', 59, 16, 'İkiyüzlülerin durumu insana: "İnkar et!" deyip, insan da inkar edince: "Doğrusu ben senden uzağım; Alemlerin Rabbi olan Allah\'tan korkarım" diyen şeytanın durumu gibidir.'),
  ('tr.diyanet', 59, 17, 'İkisinin sonucu da, içinde temelli kalacakları ateş olacaktır. Zalimlerin cezası budur.'),
  ('tr.diyanet', 59, 18, 'Ey inananlar! Allah\'tan sakının; herkes yarına ne hazırladığına baksın; Allah\'tan sakının, çünkü Allah işlediklerinizden haberdardır.'),
  ('tr.diyanet', 59, 19, 'Allah\'ı unutup da, Allah\'ın da kendilerini kendilerine unutturduğu kimseler gibi olmayın; onlar, yoldan çıkmış kimselerdir.'),
  ('tr.diyanet', 59, 20, 'Cehennemliklerle cennetlikler bir değildir. Kurtuluşa ermiş kimseler cennetliklerdir.'),
  ('tr.diyanet', 59, 21, 'Eğer Biz Kuran\'ı bir dağa indirmiş olsaydık, sen, onun, Allah korkusuyla başeğerek parça parça olduğunu görürdün. Bu misalleri, insanlar düşünsünler diye veriyoruz.'),
  ('tr.diyanet', 59, 22, 'O, görüleni de görülmeyeni de bilen, kendisinden başka tanrı olmayan Allah\'tır. O, acıyıcı olandır, acıyandır.'),
  ('tr.diyanet', 59, 23, 'O, kendisinden başka tanrı olmayan, hükümran, çok kutsal; esenlik veren, güvenlik veren, görüp gözeten, güçlü, buyruğunu herşeye geçiren, ulu olan, Allah\'tır. Allah onların koştukları eşlerden (ortaklardan) münezzehtir.'),
  ('tr.diyanet', 59, 24, 'O, vareden, güzel yaratan, yarattıklarına şekil veren, en güzel adlar kendisinin olan Allah\'tır. Göklerde ve yerde olanlar O\'nu tesbih ederler. O güçlüdür, Hakim\'dir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 59, 1, 'Telah bertasbih kepada Allah apa yang ada di langit dan bumi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 59, 2, 'Dialah yang mengeluarkan orang-orang kafir di antara ahli kitab dari kampung-kampung mereka pada saat pengusiran yang pertama. Kamu tidak menyangka, bahwa mereka akan keluar dan merekapun yakin, bahwa benteng-benteng mereka dapat mempertahankan mereka dari (siksa) Allah; maka Allah mendatangkan kepada mereka (hukuman) dari arah yang tidak mereka sangka-sangka. Dan Allah melemparkan ketakutan dalam hati mereka; mereka memusnahkan rumah-rumah mereka dengan tangan mereka sendiri dan tangan orang-orang mukmin. Maka ambillah (kejadian itu) untuk menjadi pelajaran, hai orang-orang yang mempunyai wawasan.'),
  ('id.indonesian', 59, 3, 'Dan jika tidaklah karena Allah telah menetapkan pengusiran terhadap mereka, benar-benar Allah mengazab mereka di dunia. Dan bagi mereka di akhirat azab neraka.'),
  ('id.indonesian', 59, 4, 'Yang demikian itu adalah karena Sesungguhnya mereka menentang Allah dan Rasul-Nya. Barangsiapa menentang Allah dan Rasul-Nya, Sesungguhnya Allah sangat keras hukuman-Nya.'),
  ('id.indonesian', 59, 5, 'Apa saja yang kamu tebang dari pohon kurma (milik orang-orang kafir) atau yang kamu biarkan (tumbuh) berdiri di atas pokoknya, maka (semua itu) adalah dengan izin Allah; dan karena Dia hendak memberikan kehinaan kepada orang-orang fasik.'),
  ('id.indonesian', 59, 6, 'Dan apa saja harta rampasan (fai-i) yang diberikan Allah kepada Rasul-Nya (dari harta benda) mereka, maka untuk mendapatkan itu kamu tidak mengerahkan seekor kudapun dan (tidak pula) seekor untapun, tetapi Allah yang memberikan kekuasaan kepada Rasul-Nya terhadap apa saja yang dikehendaki-Nya. Dan Allah Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 59, 7, 'Apa saja harta rampasan (fai-i) yang diberikan Allah kepada Rasul-Nya (dari harta benda) yang berasal dari penduduk kota-kota maka adalah untuk Allah, untuk Rasul, kaum kerabat, anak-anak yatim, orang-orang miskin dan orang-orang yang dalam perjalanan, supaya harta itu jangan beredar di antara orang-orang kaya saja di antara kamu. Apa yang diberikan Rasul kepadamu, maka terimalah. Dan apa yang dilarangnya bagimu, maka tinggalkanlah. Dan bertakwalah kepada Allah. Sesungguhnya Allah amat keras hukumannya.'),
  ('id.indonesian', 59, 8, '(Juga) bagi orang fakir yang berhijrah yang diusir dari kampung halaman dan dari harta benda mereka (karena) mencari karunia dari Allah dan keridhaan-Nya dan mereka menolong Allah dan Rasul-Nya. Mereka itulah orang-orang yang benar.'),
  ('id.indonesian', 59, 9, 'Dan orang-orang yang telah menempati kota Madinah dan telah beriman (Anshor) sebelum (kedatangan) mereka (Muhajirin), mereka (Anshor) \'mencintai\' orang yang berhijrah kepada mereka (Muhajirin). Dan mereka (Anshor) tiada menaruh keinginan dalam hati mereka terhadap apa-apa yang diberikan kepada mereka (Muhajirin); dan mereka mengutamakan (orang-orang Muhajirin), atas diri mereka sendiri, sekalipun mereka dalam kesusahan. Dan siapa yang dipelihara dari kekikiran dirinya, mereka itulah orang orang yang beruntung'),
  ('id.indonesian', 59, 10, 'Dan orang-orang yang datang sesudah mereka (Muhajirin dan Anshor), mereka berdoa: "Ya Rabb kami, beri ampunlah kami dan saudara-saudara kami yang telah beriman lebih dulu dari kami, dan janganlah Engkau membiarkan kedengkian dalam hati kami terhadap orang-orang yang beriman; Ya Rabb kami, Sesungguhnya Engkau Maha Penyantun lagi Maha Penyayang".'),
  ('id.indonesian', 59, 11, 'Apakah kamu tidak memperhatikan orang-orang munafik yang berkata kepada saudara-saudara mereka yang kafir di antara ahli kitab: "Sesungguhnya jika kamu diusir niscaya kamipun akan keluar bersamamu; dan kami selama-lamanya tidak akan patuh kepada siapapun untuk (menyusahkan) kamu, dan jika kamu diperangi pasti kami akan membantu kamu". Dan Allah menyaksikan bahwa Sesungguhnya mereka benar-benar pendusta.'),
  ('id.indonesian', 59, 12, 'Sesungguhnya jika mereka diusir, orang-orang munafik itu tidak akan keluar bersama mereka, dan sesungguhnya jika mereka diperangi, niscaya mereka tidak akan menolongnya; sesungguhnya jika mereka menolongnya, niscaya mereka akan berpaling lari ke belakang; kemudian mereka tidak akan mendapat pertolongan.'),
  ('id.indonesian', 59, 13, 'Sesungguhnya kamu dalam hati mereka lebih ditakuti daripada Allah. Yang demikian itu karena mereka adalah kaum yang tidak mengerti.'),
  ('id.indonesian', 59, 14, 'Mereka tidak akan memerangi kamu dalam keadaan bersatu padu, kecuali dalam kampung-kampung yang berbenteng atau di balik tembok. Permusuhan antara sesama mereka adalah sangat hebat. Kamu kira mereka itu bersatu, sedang hati mereka berpecah belah. Yang demikian itu karena sesungguhnya mereka adalah kaum yang tidak mengerti.'),
  ('id.indonesian', 59, 15, '(Mereka adalah) seperti orang-orang Yahudi yang belum lama sebelum mereka telah merasai akibat buruk dari perbuatan mereka, dan bagi mereka azab yang pedih.'),
  ('id.indonesian', 59, 16, '(Bujukan orang-orang munafik itu adalah) seperti (bujukan) shaitan ketika dia berkata kepada manusia: "Kafirlah kamu", maka tatkala manusia itu telah kafir, maka ia berkata: "Sesungguhnya aku berlepas diri dari kamu, karena sesungguhnya aku takut kepada Allah, Rabb semesta Alam".'),
  ('id.indonesian', 59, 17, 'Maka adalah kesudahan keduanya, bahwa sesungguhnya keduanya (masuk) ke dalam neraka, mereka kekal di dalamnya. Demikianlah balasan orang-orang yang zalim.'),
  ('id.indonesian', 59, 18, 'Hai orang-orang yang beriman, bertakwalah kepada Allah dan hendaklah setiap diri memperhatikan apa yang telah diperbuatnya untuk hari esok (akhirat); dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 59, 19, 'Dan janganlah kamu seperti orang-orang yang lupa kepada Allah, lalu Allah menjadikan mereka lupa kepada mereka sendiri. Mereka itulah orang-orang yang fasik.'),
  ('id.indonesian', 59, 20, 'Tidaklah sama penghuni-penghuni neraka dengan penghuni-penghuni jannah; penghuni-penghuni jannah itulah orang-orang yang beruntung.'),
  ('id.indonesian', 59, 21, 'Kalau sekiranya Kami turunkan Al-Quran ini kepada sebuah gunung, pasti kamu akan melihatnya tunduk terpecah belah disebabkan ketakutannya kepada Allah. Dan perumpamaan-perumpamaan itu Kami buat untuk manusia supaya mereka berfikir.'),
  ('id.indonesian', 59, 22, 'Dialah Allah Yang tiada Tuhan selain Dia, Yang Mengetahui yang ghaib dan yang nyata, Dialah Yang Maha Pemurah lagi Maha Penyayang.'),
  ('id.indonesian', 59, 23, 'Dialah Allah Yang tiada Tuhan selain Dia, Raja, Yang Maha Suci, Yang Maha Sejahtera, Yang Mengaruniakan Keamanan, Yang Maha Memelihara, Yang Maha Perkasa, Yang Maha Kuasa, Yang Memiliki segala Keagungan, Maha Suci Allah dari apa yang mereka persekutukan.'),
  ('id.indonesian', 59, 24, 'Dialah Allah Yang Menciptakan, Yang Mengadakan, Yang Membentuk Rupa, Yang Mempunyai Asmaaul Husna. Bertasbih kepada-Nya apa yang di langit dan bumi. Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 60, 1, 'O you who have believed, do not take My enemies and your enemies as allies, extending to them affection while they have disbelieved in what came to you of the truth, having driven out the Prophet and yourselves [only] because you believe in Allah, your Lord. If you have come out for jihad in My cause and seeking means to My approval, [take them not as friends]. You confide to them affection, but I am most knowing of what you have concealed and what you have declared. And whoever does it among you has certainly strayed from the soundness of the way.'),
  ('en.sahih', 60, 2, 'If they gain dominance over you, they would be to you as enemies and extend against you their hands and their tongues with evil, and they wish you would disbelieve.'),
  ('en.sahih', 60, 3, 'Never will your relatives or your children benefit you; the Day of Resurrection He will judge between you. And Allah, of what you do, is Seeing.'),
  ('en.sahih', 60, 4, 'There has already been for you an excellent pattern in Abraham and those with him, when they said to their people, "Indeed, we are disassociated from you and from whatever you worship other than Allah. We have denied you, and there has appeared between us and you animosity and hatred forever until you believe in Allah alone" except for the saying of Abraham to his father, "I will surely ask forgiveness for you, but I have not [power to do] for you anything against Allah. Our Lord, upon You we have relied, and to You we have returned, and to You is the destination.'),
  ('en.sahih', 60, 5, 'Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise."'),
  ('en.sahih', 60, 6, 'There has certainly been for you in them an excellent pattern for anyone whose hope is in Allah and the Last Day. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy.'),
  ('en.sahih', 60, 7, 'Perhaps Allah will put, between you and those to whom you have been enemies among them, affection. And Allah is competent, and Allah is Forgiving and Merciful.'),
  ('en.sahih', 60, 8, 'Allah does not forbid you from those who do not fight you because of religion and do not expel you from your homes - from being righteous toward them and acting justly toward them. Indeed, Allah loves those who act justly.'),
  ('en.sahih', 60, 9, 'Allah only forbids you from those who fight you because of religion and expel you from your homes and aid in your expulsion - [forbids] that you make allies of them. And whoever makes allies of them, then it is those who are the wrongdoers.'),
  ('en.sahih', 60, 10, 'O you who have believed, when the believing women come to you as emigrants, examine them. Allah is most knowing as to their faith. And if you know them to be believers, then do not return them to the disbelievers; they are not lawful [wives] for them, nor are they lawful [husbands] for them. But give the disbelievers what they have spent. And there is no blame upon you if you marry them when you have given them their due compensation. And hold not to marriage bonds with disbelieving women, but ask for what you have spent and let them ask for what they have spent. That is the judgement of Allah; He judges between you. And Allah is Knowing and Wise.'),
  ('en.sahih', 60, 11, 'And if you have lost any of your wives to the disbelievers and you subsequently obtain [something], then give those whose wives have gone the equivalent of what they had spent. And fear Allah, in whom you are believers.'),
  ('en.sahih', 60, 12, 'O Prophet, when the believing women come to you pledging to you that they will not associate anything with Allah, nor will they steal, nor will they commit unlawful sexual intercourse, nor will they kill their children, nor will they bring forth a slander they have invented between their arms and legs, nor will they disobey you in what is right - then accept their pledge and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 60, 13, 'O you who have believed, do not make allies of a people with whom Allah has become angry. They have despaired of [reward in] the Hereafter just as the disbelievers have despaired of [meeting] the inhabitants of the graves.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 60, 1, 'মুমিনগণ, তোমরা আমার ও তোমাদের শত্রুদেরকে বন্ধরূপে গ্রহণ করো না। তোমরা তো তাদের প্রতি বন্ধুত্বের বার্তা পাঠাও, অথচ তারা যে সত্য তোমাদের কাছে আগমন করেছে, তা অস্বীকার করছে। তারা রসূলকে ও তোমাদেরকে বহিস্কার করে এই অপরাধে যে, তোমরা তোমাদের পালনকর্তার প্রতি বিশ্বাস রাখ। যদি তোমরা আমার সন্তুষ্টিলাভের জন্যে এবং আমার পথে জেহাদ করার জন্যে বের হয়ে থাক, তবে কেন তাদের প্রতি গোপনে বন্ধুত্বের পয়গাম প্রেরণ করছ? তোমরা যা গোপন কর এবং যা প্রকাশ কর, ত আমি খুব জানি। তোমাদের মধ্যে যে এটা করে, সে সরলপথ থেকে বিচ্যুত হয়ে যায়।'),
  ('bn.bengali', 60, 2, 'তোমাদেরকে করতলগত করতে পারলে তারা তোমাদের শত্রু হয়ে যাবে এবং মন্দ উদ্দেশ্যে তোমাদের প্রতি বাহু ও রসনা প্রসারিত করবে এবং চাইবে যে, কোনরূপে তোমরা ও কাফের হয়ে যাও।'),
  ('bn.bengali', 60, 3, 'তোমাদের স্বজন-পরিজন ও সন্তান-সন্ততি কিয়ামতের দিন কোন উপকারে আসবে না। তিনি তোমাদের মধ্যে ফয়সালা করবেন। তোমরা যা কর, আল্লাহ তা দেখেন।'),
  ('bn.bengali', 60, 4, 'তোমাদের জন্যে ইব্রাহীম ও তাঁর সঙ্গীগণের মধ্যে চমৎকার আদর্শ রয়েছে। তারা তাদের সম্প্রদায়কে বলেছিলঃ তোমাদের সাথে এবং তোমরা আল্লাহর পরিবর্তে যার এবাদত কর, তার সাথে আমাদের কোন সম্পর্ক নেই। আমরা তোমাদের মানি না। তোমরা এক আল্লাহর প্রতি বিশ্বাস স্থাপন না করলে তোমাদের মধ্যে ও আমাদের মধ্যে চিরশত্রুতা থাকবে। কিন্তু ইব্রাহীমের উক্তি তাঁর পিতার উদ্দেশে এই আদর্শের ব্যতিক্রম। তিনি বলেছিলেনঃ আমি অবশ্যই তোমার জন্য ক্ষমাপ্রার্থনা করব। তোমার উপকারের জন্যে আল্লাহর কাছে আমার আর কিছু করার নেই। হে আমাদের পালনকর্তা! আমরা তোমারই উপর ভরসা করেছি, তোমারই দিকে মুখ করেছি এবং তোমারই নিকট আমাদের প্রত্যাবর্তন।'),
  ('bn.bengali', 60, 5, 'হে আমাদের পালনকর্তা! তুমি আমাদেরকে কাফেরদের জন্য পরীক্ষার পাত্র করো না। হে আমাদের পালনকর্তা! আমাদের ক্ষমা কর। নিশ্চয় তুমি পরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 60, 6, 'তোমরা যারা আল্লাহ ও পরকাল প্রত্যাশা কর, তোমাদের জন্য তাদের মধ্যে উত্তম আদর্শ রয়েছে। আর যে মুখ ফিরিয়ে নেয়, তার জানা উচিত যে, আল্লাহ বেপরওয়া, প্রশংসার মালিক।'),
  ('bn.bengali', 60, 7, 'যারা তোমাদের শত্রু আল্লাহ তাদের মধ্যে ও তোমাদের মধ্যে সম্ভবতঃ বন্ধুত্ব সৃষ্টি করে দেবেন। আল্লাহ সবই করতে পারেন এবং আল্লাহ ক্ষমাশীল, করুণাময়।'),
  ('bn.bengali', 60, 8, 'ধর্মের ব্যাপারে যারা তোমাদের বিরুদ্ধে লড়াই করেনি এবং তোমাদেরকে দেশ থেকে বহিস্কৃত করেনি, তাদের প্রতি সদাচরণ ও ইনসাফ করতে আল্লাহ তোমাদেরকে নিষেধ করেন না। নিশ্চয় আল্লাহ ইনসাফকারীদেরকে ভালবাসেন।'),
  ('bn.bengali', 60, 9, 'আল্লাহ কেবল তাদের সাথে বন্ধুত্ব করতে নিষেধ করেন, যারা ধর্মের ব্যাপারে তোমাদের বিরুদ্ধে যুদ্ধ করেছে, তোমাদেরকে দেশ থেকে বহিস্কৃত করেছে এবং বহিস্কারকার্যে সহায়তা করেছে। যারা তাদের সাথে বন্ধুত্ব করে তারাই জালেম।'),
  ('bn.bengali', 60, 10, 'মুমিনগণ, যখন তোমাদের কাছে ঈমানদার নারীরা হিজরত করে আগমন করে, তখন তাদেরকে পরীক্ষা কর। আল্লাহ তাদের ঈমান সম্পর্কে সম্যক অবগত আছেন। যদি তোমরা জান যে, তারা ঈমানদার, তবে আর তাদেরকে কাফেরদের কাছে ফেরত পাঠিও না। এরা কাফেরদের জন্যে হালাল নয় এবং কাফেররা এদের জন্যে হালাল নয়। কাফেররা যা ব্যয় করেছে, তা তাদের দিয়ে দাও। তোমরা, এই নারীদেরকে প্রাপ্য মোহরানা দিয়ে বিবাহ করলে তোমাদের অপরাধ হবে না। তোমরা কাফের নারীদের সাথে দাম্পত্য সম্পর্ক বজায় রেখো না। তোমরা যা ব্যয় করেছ, তা চেয়ে নাও এবং তারাও চেয়ে নিবে যা তারা ব্যয় করেছে। এটা আল্লাহর বিধান; তিনি তোমাদের মধ্যে ফয়সালা করেন। আল্লাহ সর্বজ্ঞ প্রজ্ঞাময়।'),
  ('bn.bengali', 60, 11, 'তোমাদের স্ত্রীদের মধ্যে যদি কেউ হাতছাড়া হয়ে কাফেরদের কাছে থেকে যায়, অতঃপর তোমরা সুযোগ পাও, তখন যাদের স্ত্রী হাতছাড়া হয়ে গেছে, তাদেরকে তাদের ব্যয়কৃত অর্থের সমপরিমাণ অর্থ প্রদান কর এবং আল্লাহকে ভয় কর, যার প্রতি তোমরা বিশ্বাস রাখ।'),
  ('bn.bengali', 60, 12, 'হে নবী, ঈমানদার নারীরা যখন আপনার কাছে এসে আনুগত্যের শপথ করে যে, তারা আল্লাহর সাথে কাউকে শরীক করবে না, চুরি করবে না, ব্যভিচার করবে না, তাদের সন্তানদেরকে হত্যা করবে না, জারজ সন্তানকে স্বামীর ঔরস থেকে আপন গর্ভজাত সন্তান বলে মিথ্যা দাবী করবে না এবং ভাল কাজে আপনার অবাধ্যতা করবে না, তখন তাদের আনুগত্য গ্রহণ করুন এবং তাদের জন্যে আল্লাহর কাছে ক্ষমা প্রার্থনা করুন। নিশ্চয় আল্লাহ ক্ষমাশীল অত্যন্ত দয়ালু।'),
  ('bn.bengali', 60, 13, 'মুমিনগণ, আল্লাহ যে জাতির প্রতি রুষ্ট, তোমরা তাদের সাথে বন্ধুত্ব করো না। তারা পরকাল সম্পর্কে নিরাশ হয়ে গেছে যেমন কবরস্থ কাফেররা নিরাশ হয়ে গেছে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 60, 1, 'O ye who believe! Choose not My enemy and your enemy for allies. Do ye give them friendship when they disbelieve in that truth which hath come unto you, driving out the messenger and you because ye believe in Allah, your Lord? If ye have come forth to strive in My way and seeking My good pleasure, (show them not friendship). Do ye show friendship unto them in secret, when I am Best Aware of what ye hide and what ye proclaim? And whosoever doeth it among you, he verily hath strayed from the right way.'),
  ('en.pickthall', 60, 2, 'If they have the upper hand of you, they will be your foes, and will stretch out their hands and their tongues toward you with evil (intent), and they long for you to disbelieve.'),
  ('en.pickthall', 60, 3, 'Your ties of kindred and your children will avail you naught upon the Day of Resurrection. He will part you. Allah is Seer of what ye do.'),
  ('en.pickthall', 60, 4, 'There is a goodly pattern for you in Abraham and those with him, when they told their folk: Lo! we are guiltless of you and all that ye worship beside Allah. We have done with you. And there hath arisen between us and you hostility and hate for ever until ye believe in Allah only - save that which Abraham promised his father (when he said): I will ask forgiveness for thee, though I own nothing for thee from Allah - Our Lord! In Thee we put our trust, and unto Thee we turn repentant, and unto Thee is the journeying.'),
  ('en.pickthall', 60, 5, 'Our Lord! Make us not a prey for those who disbelieve, and forgive us, our Lord! Lo! Thou, only Thou, are the Mighty, the Wise.'),
  ('en.pickthall', 60, 6, 'Verily ye have in them a goodly pattern for everyone who looketh to Allah and the Last Day. And whosoever may turn away, lo! still Allah, He is the Absolute, the Owner of Praise.'),
  ('en.pickthall', 60, 7, 'It may be that Allah will ordain love between you and those of them with whom ye are at enmity. Allah is Mighty, and Allah is Forgiving, Merciful.'),
  ('en.pickthall', 60, 8, 'Allah forbiddeth you not those who warred not against you on account of religion and drove you not out from your homes, that ye should show them kindness and deal justly with them. Lo! Allah loveth the just dealers.'),
  ('en.pickthall', 60, 9, 'Allah forbiddeth you only those who warred against you on account of religion and have driven you out from your homes and helped to drive you out, that ye make friends of them. Whosoever maketh friends of them - (All) such are wrong-doers.'),
  ('en.pickthall', 60, 10, 'O ye who believe! When believing women come unto you as fugitives, examine them. Allah is Best Aware of their faith. Then, if ye know them for true believers, send them not back unto the disbelievers. They are not lawful for them (the disbelievers), nor are they (the disbelievers) lawful for them. And give them (the disbelievers) that which they have spent (upon them). And it is no sin for you to marry such women when ye have given them their dues. And hold not to the ties of disbelieving women; and ask for (the return of) that which ye have spent; and let them (the disbelievers) ask for that which they have spent. That is the judgment of Allah. He judgeth between you. Allah is Knower, Wise.'),
  ('en.pickthall', 60, 11, 'And if any of your wives have gone from you unto the disbelievers and afterward ye have your turn (of triumph), then give unto those whose wives have gone the like of that which they have spent, and keep your duty to Allah in Whom ye are believers.'),
  ('en.pickthall', 60, 12, 'O Prophet! If believing women come unto thee, taking oath of allegiance unto thee that they will ascribe no thing as partner unto Allah, and will neither steal nor commit adultery nor kill their children, nor produce any lie that they have devised between their hands and feet, nor disobey thee in what is right, then accept their allegiance and ask Allah to forgive them. Lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 60, 13, 'O ye who believe! Be not friendly with a folk with whom Allah is wroth, (a folk) who have despaired of the Hereafter as the disbelievers despair of those who are in the graves.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 60, 1, 'O ye who believe! Take not my enemies and yours as friends (or protectors),- offering them (your) love, even though they have rejected the Truth that has come to you, and have (on the contrary) driven out the Prophet and yourselves (from your homes), (simply) because ye believe in Allah your Lord! If ye have come out to strive in My Way and to seek My Good Pleasure, (take them not as friends), holding secret converse of love (and friendship) with them: for I know full well all that ye conceal and all that ye reveal. And any of you that does this has strayed from the Straight Path.'),
  ('en.yusufali', 60, 2, 'If they were to get the better of you, they would behave to you as enemies, and stretch forth their hands and their tongues against you for evil: and they desire that ye should reject the Truth.'),
  ('en.yusufali', 60, 3, 'Of no profit to you will be your relatives and your children on the Day of Judgment: He will judge between you: for Allah sees well all that ye do.'),
  ('en.yusufali', 60, 4, 'There is for you an excellent example (to follow) in Abraham and those with him, when they said to their people: "We are clear of you and of whatever ye worship besides Allah: we have rejected you, and there has arisen, between us and you, enmity and hatred for ever,- unless ye believe in Allah and Him alone": But not when Abraham said to his father: "I will pray for forgiveness for thee, though I have no power (to get) aught on thy behalf from Allah." (They prayed): "Our Lord! in Thee do we trust, and to Thee do we turn in repentance: to Thee is (our) Final Goal.'),
  ('en.yusufali', 60, 5, '"Our Lord! Make us not a (test and) trial for the Unbelievers, but forgive us, our Lord! for Thou art the Exalted in Might, the Wise."'),
  ('en.yusufali', 60, 6, 'There was indeed in them an excellent example for you to follow,- for those whose hope is in Allah and in the Last Day. But if any turn away, truly Allah is Free of all Wants, Worthy of all Praise.'),
  ('en.yusufali', 60, 7, 'It may be that Allah will grant love (and friendship) between you and those whom ye (now) hold as enemies. For Allah has power (over all things); And Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 60, 8, 'Allah forbids you not, with regard to those who fight you not for (your) Faith nor drive you out of your homes, from dealing kindly and justly with them: for Allah loveth those who are just.'),
  ('en.yusufali', 60, 9, 'Allah only forbids you, with regard to those who fight you for (your) Faith, and drive you out of your homes, and support (others) in driving you out, from turning to them (for friendship and protection). It is such as turn to them (in these circumstances), that do wrong.'),
  ('en.yusufali', 60, 10, 'O ye who believe! When there come to you believing women refugees, examine (and test) them: Allah knows best as to their Faith: if ye ascertain that they are Believers, then send them not back to the Unbelievers. They are not lawful (wives) for the Unbelievers, nor are the (Unbelievers) lawful (husbands) for them. But pay the Unbelievers what they have spent (on their dower), and there will be no blame on you if ye marry them on payment of their dower to them. But hold not to the guardianship of unbelieving women: ask for what ye have spent on their dowers, and let the (Unbelievers) ask for what they have spent (on the dowers of women who come over to you). Such is the command of Allah: He judges (with justice) between you. And Allah is Full of Knowledge and Wisdom.'),
  ('en.yusufali', 60, 11, 'And if any of your wives deserts you to the Unbelievers, and ye have an accession (by the coming over of a woman from the other side), then pay to those whose wives have deserted the equivalent of what they had spent (on their dower). And fear Allah, in Whom ye believe.'),
  ('en.yusufali', 60, 12, 'O Prophet! When believing women come to thee to take the oath of fealty to thee, that they will not associate in worship any other thing whatever with Allah, that they will not steal, that they will not commit adultery (or fornication), that they will not kill their children, that they will not utter slander, intentionally forging falsehood, and that they will not disobey thee in any just matter,- then do thou receive their fealty, and pray to Allah for the forgiveness (of their sins): for Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 60, 13, 'O ye who believe! Turn not (for friendship) to people on whom is the Wrath of Allah, of the Hereafter they are already in despair, just as the Unbelievers are in despair about those (buried) in graves.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 60, 1, 'Yaa ayyuhal lazeena aamanoo laa tattakhizoo \'aduwwee wa \'aduwaakum awliyaaa\'a tulqoona ilaihim bilmawaddati wa qad kafaroo bima jaaa\'akum minal haqq, yukhrijoonar Rasoola wa iyyaakum an tu\'minoo billaahi rabbikum in kuntum kharajtum jihaadan fee sabeelee wabtighaaa\'a mardaatee; tusirroona ilaihim bilma waddati wa ana a\'alamu bimaaa akhfaitum wa maaa a\'lantum; wa many yaf\'alhu minkum faqad dalla sawaaa\'as sabeel'),
  ('en.transliteration', 60, 2, 'Iny yasqafookum yakoonoo lakum a\'daaa\'anw wa yabsutooo ilaikum aydiyahum wa alsinatahum bissooo\'i wa waddoo law takfuroon'),
  ('en.transliteration', 60, 3, 'Lan tanfa\'akum arhaamukum wa laaa awlaadukum; yawmal qiyaamati yafsilu bainakum; wallaahu bimaa ta\'maloon baseer'),
  ('en.transliteration', 60, 4, 'Qad kaanat lakum uswatun basanatun feee Ibraaheema wallazeena ma\'ahoo iz qaaloo liqawmihim innaa bura\'aaa\'u minkum wa mimmaa ta\'budoona min doonil laahi kafarnaa bikum wa badaa bainanaa wa bainakumul \'adaawatu wal baghdaaa\'u abadan hattaa tu\'minoo billaahi wahdahooo illaa qawla Ibraheema li abeehi la astaghfiranna laka wa maaa amliku laka minal laahi min shai; rabbanaa \'alaika tawakkalnaa wa ilaika anabnaa wa ilaikal maseer'),
  ('en.transliteration', 60, 5, 'Rabbana laa taj\'alnaa fitnatal lillazeena kafaroo waghfir lanaa rabbanaa innaka antal azeezul hakeem'),
  ('en.transliteration', 60, 6, 'Laqad kaana lakum feehim uswatunhasanatul liman kaana yarjul laaha wal yawmal aakhir; wa many yatawalla fa innal laaha huwal ghaniyyul hameed'),
  ('en.transliteration', 60, 7, 'Asal laahu any yaj\'ala bainakum wa bainal lazeena \'aadaitum minhum mawaddah; wallahu qadeer; wallahu ghafoorur raheem'),
  ('en.transliteration', 60, 8, 'Laa yanhaakumul laahu \'anil lazeena lam yuqaatilookum fid deeni wa lam yukhrijookum min diyaarikum an tabarroohum wa tuqsitooo ilaihim; innal laaha yuhibbul muqsiteen'),
  ('en.transliteration', 60, 9, 'Innamaa yanhaakumul laahu \'anil lazeena qaatalookum fid deeni wa akhrajookum min diyaarikum wa zaaharoo \'alaa ikhraajikum an tawallawhum; wa many yatawallahum faulaaa\'ika humuz zaalimoon'),
  ('en.transliteration', 60, 10, 'Yaa ayyuhal lazeena aamanoo izaa jaaa\'akumul mu\'minaatu muhaajiraatin famtah inoohunna Allaahu a\'lamu bieemaanihinna fa in \'alimtumoohunna mu\'minaatin falaa tarji\'oohunna ilal kuffaar; laa hunna hillul lahum wa laa hum uahilloona lahunna wa aatoohum maa anfaqoo wa laa junaaha \'alaikum an tankihoohunna izaaa aataitumoohunna ujoorahunn; wa laa tumsikoo bi \'isamil kawaafiri was\'aloo maaa anfaqtum walyas\'aloo maaa anfaqoo zaalikum hukmul laahi yahkumu bainakum wallaahu \'aleemun hakeem'),
  ('en.transliteration', 60, 11, 'Wa in faatakum shai\'um min azwaajikum ilal kuffaari fa\'aaqabtum fa aatul lazeena zahabat azwaajuhum misla maaa anfaqoo; wattaqul laahal lazeee antum bihee mu\'minoon'),
  ('en.transliteration', 60, 12, 'Yaaa ayyuhan nabbiyyu izaa jaaa\'akal mu\'minaau yubaai naka \'alaaa allaa yushrikna billaahi shai \'anw wa laa yasriqna wa laa yazneena wa laa yaqtulna awlaadahunna wa laa yaateena bibuhtaaniny yaftaree nahoo baina aydeehinna wa arjulihinna wa laa ya\'seenaka fee ma\'roofin fabaayi\'hunna wastaghfir lahunnal laaha innnal laaha ghafoorur raheem'),
  ('en.transliteration', 60, 13, 'Yaaa ayyuhal lazeena amanoo laa tatawallaw qawman ghadibal laahu \'alaihim qad ya\'isoo minal aakhirati kamaa ya\'isal kuffaaru min as haabil quboor')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 60, 1, 'اے ایمان والو میرے دشمنوں اور اپنے دشمنوں کو دوست نہ بناؤ کہ ان کے پاس دوستی کے پیغام بھیجتے ہو حالانکہ تمہارے پاس جو سچا دین آیا ہے اس کے یہ منکر ہو چکے ہیں رسول کو اور تمہیں ا س بات پر نکالتے ہیں کہ تم الله اپنے رب پر ایمان لائے ہو اگر تم جہاد کے لیے میری راہ میں اور میری رضا جوئی کے لیے نکلے ہوتو ان کو دوست نہ بناؤ تم ان کے پاس پوشیدہ دوستی کے پیغام بھیجتے ہو حالانکہ میں خوب جانتا ہوں جو کچھ تم مخفی اور ظاہر کرتے ہو اور جس نے تم میں سے یہ کام کیا تو وہ سیدھے راستہ سے بہک گیا'),
  ('ur.ahmedali', 60, 2, 'اگر وہ تم پر قابو پائیں تو تمہارے دشمن ہو جائیں اور تم پر اپنے ہاتھ اور اپنی زبانیں برائی سے دراز کریں اور چاہتے ہیں کہ کہیں تم کافر ہو جاؤ'),
  ('ur.ahmedali', 60, 3, 'نہ تمہیں تمہارے رشتے ناطے اور نہ تمہاری اولاد قیامت کے دن نفع دیں گے وہ تمہارے درمیان فیصلہ کرے گا اور جو تم کرتے ہو الله اسے خوب دیکھتا ہے'),
  ('ur.ahmedali', 60, 4, 'بے شک تمہارے لیے ابراہیم میں اچھا نمونہ ہے اوران لوگوں میں جو اس کے ہمراہ تھے جب کہ انہوں نے اپنی قوم سے کہا تھا بے شک ہم تم سے بیزار ہیں اور ان سے جنہیں تم الله کے سوا پوجتے ہو ہم نے تمہارا انکار کر دیا اور ہمارے او رتمہارے درمیان دشمنی اور بیَر ہمیشہ کے لیے ظاہر ہو گیا یہاں تک کہ تم ایک الله پر ایمان لاؤ مگر ابراھیم کا اپنے باپ سے کہنا کہ میں تمہارے لیے معافی مانگوں گا اور میں الله کی طرف سے تمہارے لیے کسی بات کا مالک بھی نہیں ہوں اے ہمارے رب ہم نے تجھ ہی پر بھروسہ کیا اور تیری ہی طرف ہم رجوع ہوئے اور تیری ہی طرف لوٹنا ہے'),
  ('ur.ahmedali', 60, 5, 'اے ہمارے رب ہمیں ان کا تختہ مشق نہ بنا جو کافر ہیں اور اے ہمارے رب ہمیں معاف کر بے شک تو ہی غالب حکمت والا ہے'),
  ('ur.ahmedali', 60, 6, 'البتہ تمہارے لیے ان میں ایک نیک نمونہ ہے اس کے لیے جو الله اور قیامت کے دن کی امید رکھتا ہو اور جو کوئی منہ موڑے تو بے شک الله بھی بے پرواہ خوبیوں والا ہے'),
  ('ur.ahmedali', 60, 7, 'شاید کہ الله تم میں اور ان میں کہ جن سے تمہیں دشمنی ہے دوستی قائم کر دے اور الله قادر ہے اور الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 60, 8, 'الله تمہیں ان لوگو ں سے منع نہیں کرتا جو تم سے دین کے بارے میں نہیں لڑتے اورنہ انہوں نے تمہیں تمہارے گھروں سے نکالا ہے اس بات سے کہ تم ان سے بھلائی کرو اور ان کے حق میں انصاف کرو بیشک الله انصاف کرنے والوں کو پسند کرتا ہے'),
  ('ur.ahmedali', 60, 9, 'تمہیں الله انہیں سے منع کرتا ہے کہ جو دین میں تم سے لڑے اورانہوں نے تمہیں تمہارے گھروں سے نکال دیا اور تمہارے نکالنے پر (لوگوں کی) مدد بھی کی کہ ان سے دوستی کرو اورجس نے ان سے دوستی کی تو پھر وہی ظالم بھی ہیں'),
  ('ur.ahmedali', 60, 10, 'اے ایمان والو جب تمہارے پاس مومن عورتیں ہجرت کر کے آئيں تو ان کی جانچ کر لو الله ہی ان کے ایمان کو خوب جانتا ہے پس اگر تم انہیں مومن معلوم کر لو تو انہیں کفار کی طرف نہ لوٹاؤ نہ وہ (عورتیں) ان کے لیے حلال ہیں اور نہ وہ (کافر) ان کے لیے حلال ہیں اور ان کفار کو دے دو جو کچھ انہوں نے خرچ کیا اور تم پر گناہ نہیں کہ تم ان سے نکاح کر لو جب تم انہیں ان کے مہر دے دو اور کافر عورتوں کے ناموس کو قبضہ میں نہ رکھو اور جو تم نےان عورتوں پر خرچ کیا تھا مانگ لو اور جو انہوں نے خرچ کیا کہ وہ مانگ لیں الله کا یہی حکم ہے جو تمہارے لیے صاد رفرمایا اور الله سب کچھ جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 60, 11, 'اور اگرکوئی عورت تمہاری عورتوں میں سے کفار کے پاس نکل گئی ہے پھر تمہاری باری آجائے تو ان مسلمانو ں کو دے دو جن کی بیویاں چلی گئی ہیں جتنا کہ انہوں نے دیا تھا اوراس الله سے ڈرو کہ جس پر تم ایمان لائے ہو'),
  ('ur.ahmedali', 60, 12, 'اے نبی جب آپ کے پاس ایمان والی عورتیں اس بات پر بیعت کرنے کو آئیں کہ الله کے ساتھ کسی کو شریک نہ کرینگی اور نہ چوری کریں گی اور نہ زنا کریں گی اور نہ اپنی اولاد کو قتل کریں گی اور نہ بہتان کی اولاد لائیں گی جسے اپنے ہاتھوں اور پاؤں کے درمیان (نطفہٴ شوہر سے جنی ہوئی) بنا لیں اور نہ کسی نیک بات میں آپ کی نافرمانی کریں گی تو ان کی بیعت قبول کر اور ان کے لیے الله سے بخشش مانگ بے شک الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 60, 13, 'اے ایمان والو اس قوم سے دوستی نہ کرو جن پر الله کا غضب ہوا وہ تو آخرت سے ایسے نا امید ہو گئے کہ جیسے کافر اہلِ قبور سے نا امید ہو گئے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 60, 1, 'Ey inananlar! Benim de düşmanım, sizin de düşmanınız olanları dost edinmeyin. Onlar, size gelen gerçeği inkar etmişken, onlara sevgi gösteriyorsunuz; oysa onlar, Rabbiniz olan Allah\'a inandığınızdan ötürü sizi ve Peygamberi yurdunuzdan çıkarıyorlar. Eğer sizler Benim yolumda savaşmak ve rızamı kazanmak için çıkmışsanız onlara nasıl sevgi gösterirsiniz? Ben, sizin gizlediğinizi de, açığa vurduğunuzu da bilirim. İçinizden onlara sevgi gösteren kimse, şüphesiz doğru yoldan sapmıştır.'),
  ('tr.diyanet', 60, 2, 'Eğer sizi elegeçirirlerse sizin onlara gösterdiğiniz sevgiyi göstermezler, size düşman olurlar, ellerini ve dillerini fenalık etmek için uzatırlar, keşke inkar etseniz isterler.'),
  ('tr.diyanet', 60, 3, 'Yakınlarınız ve çocuklarınız size kıyamet gününde bir fayda veremezler. Allah onlarla sizi ayırır. Allah işlediklerinizi görendir.'),
  ('tr.diyanet', 60, 4, 'İbrahim ve onunla beraber olanlarda, sizin için uyulacak güzel bir örnek vardır. Onlar milletlerine şöyle demişlerdi: "Biz sizden ve Allah\'tan başka taptıklarınızdan uzağız; sizin dininizi inkar ediyoruz; bizimle sizin aranızda yalnız Allah\'a inanmanıza kadar ebedi düşmanlık ve öfke başgöstermiştir." -Yalnız, İbrahim\'in, babasına: "And olsun ki, senin için mağfiret dileyeceğim, fakat sana Allah\'tan gelecek herhangi bir şeyi savmaya gücüm yetmez" sözü bu örneğin dışındadır- "Rabbimiz! Sana güvendik, Sana yöneldik; dönüş Sanadır."'),
  ('tr.diyanet', 60, 5, '"Rabbimiz! Bizi, inkar edenlerle deneme; bizi bağışla, doğrusu Sen, güçlü olan, Hakim olansın."'),
  ('tr.diyanet', 60, 6, 'And olsun ki, sizlerden, Allah\'ı ve ahiret gününü uman kimse için, bunlarda güzel örnekler vardır. Kim yüz çevirirse kendi aleyhine olur, doğrusu Allah müstağnidir, övülmeğe layıktır.'),
  ('tr.diyanet', 60, 7, 'Allah\'ın sizinle, düşmanlık gösterdiğiniz kimseler arasında bir sevgi yaratması umulur; Allah Kadir\'dir, Allah bağışlayandır, acıyandır.'),
  ('tr.diyanet', 60, 8, 'Allah, din uğrunda sizinle savaşmayan, sizi yurdunuzdan çıkarmayan kimselere iyilik yapmanızı ve onlara karşı adil davranmanızı yasak kılmaz; doğrusu Allah adil olanları sever.'),
  ('tr.diyanet', 60, 9, 'Allah, ancak sizinle din uğrunda savaşanları, sizi yurtlarınızdan çıkaranları ve çıkarılmanıza yardım edenleri dost edinmenizi yasak eder; kim onları dost edinirse, işte onlar zalimdir.'),
  ('tr.diyanet', 60, 10, 'Ey inananlar! İnanmış kadınlar hicret ederek size gelirlerse onları deneyin, hicretlerinin sebebini inceleyin. Allah onların imanlarını çok iyi bilir. Onların mümin kadınlar olduklarını öğrenirseniz, inkarcılara geri çevirmeyin. Bu kadınlar, o inkarcılara helal değildir Onlar da bunlara helal olmazlar. İnkarcıların bu kadınlara verdikleri mehirleri iade edin: Bu kadınların mehirlerini kendilerine verdiğiniz zaman, onlarla evlenmenizde bir engel yoktur. İnkarcı kadınları nikahınızda tutmayın; onlara verdiğiniz mehri isteyin; inkarcı erkekler de hicret eden mümin kadınlara verdikleri mehirleri istesinler. Allah\'ın hükmü budur; aranızda O hükmeder. Allah bilendir, Hakim\'dir.'),
  ('tr.diyanet', 60, 11, 'Ey mümin erkekler! Eğer inkar eden (kafir olan) eşlerinize sarfettiklerinizden inkarcılara bir şey geçecek olursa ganimetten, eşleri giden mümin erkeklere sarfettikleri miktar kadarını verin. İnandığınız Allah\'a karşı gelmekten sakının.'),
  ('tr.diyanet', 60, 12, 'Ey Peygamber! İnanmış kadınlar, Allah\'a hiçbir ortak koşmamak, hırsızlık yapmamak, zina etmemek, çocuklarını öldürmemek, başkasının çocuğunu sahiplenerek kocasına isnadda bulunmamak ve uygun olanı işlemekte sana karşı gelmemek şartıyla sana beyat etmek üzere geldikleri zaman, onları kabul et; onlara Allah\'tan bağışlanma dile; doğrusu Allah, bağışlayandır, acıyandır.'),
  ('tr.diyanet', 60, 13, 'Ey inananlar! Allah\'ın gazabına uğramış milleti dost edinmeyin; inkarcıların kabirde bulunan kimselerden umutlarını kestikleri gibi, onlar da, ahiretten umutlarını kesmişlerdir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 60, 1, 'Hai orang-orang yang beriman, janganlah kamu mengambil musuh-Ku dan musuhmu menjadi teman-teman setia yang kamu sampaikan kepada mereka (berita-berita Muhammad), karena rasa kasih sayang; padahal sesungguhnya mereka telah ingkar kepada kebenaran yang datang kepadamu, mereka mengusir Rasul dan (mengusir) kamu karena kamu beriman kepada Allah, Tuhanmu. Jika kamu benar-benar keluar untuk berjihad di jalan-Ku dan mencari keridhaan-Ku (janganlah kamu berbuat demikian). Kamu memberitahukan secara rahasia (berita-berita Muhammad) kepada mereka, karena rasa kasih sayang. Aku lebih mengetahui apa yang kamu sembunyikan dan apa yang kamu nyatakan. Dan barangsiapa di antara kamu yang melakukannya, maka sesungguhnya dia telah tersesat dari jalan yang lurus.'),
  ('id.indonesian', 60, 2, 'Jika mereka menangkap kamu, niscaya mereka bertindak sebagai musuh bagimu dan melepaskan tangan dan lidah mereka kepadamu dengan menyakiti(mu); dan mereka ingin supaya kamu (kembali) kafir.'),
  ('id.indonesian', 60, 3, 'Karib kerabat dan anak-anakmu sekali-sekali tiada bermanfaat bagimu pada Hari Kiamat. Dia akan memisahkan antara kamu. Dan Allah Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 60, 4, 'Sesungguhnya telah ada suri tauladan yang baik bagimu pada Ibrahim dan orang-orang yang bersama dengan dia; ketika mereka berkata kepada kaum mereka: "Sesungguhnya kami berlepas diri daripada kamu dari daripada apa yang kamu sembah selain Allah, kami ingkari (kekafiran)mu dan telah nyata antara kami dan kamu permusuhan dan kebencian buat selama-lamanya sampai kamu beriman kepada Allah saja. Kecuali perkataan Ibrahim kepada bapaknya: "Sesungguhnya aku akan memohonkan ampunan bagi kamu dan aku tiada dapat menolak sesuatupun dari kamu (siksaan) Allah". (Ibrahim berkata): "Ya Tuhan kami hanya kepada Engkaulah kami bertawakkal dan hanya kepada Engkaulah kami bertaubat dan hanya kepada Engkaulah kami kembali".'),
  ('id.indonesian', 60, 5, '"Ya Tuhan kami, janganlah Engkau jadikan kami (sasaran) fitnah bagi orang-orang kafir. Dan ampunilah kami ya Tuhan kami. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana".'),
  ('id.indonesian', 60, 6, 'Sesungguhnya pada mereka itu (Ibrahim dan umatnya) ada teladan yang baik bagimu; (yaitu) bagi orang-orang yang mengharap (pahala) Allah dan (keselamatan pada) Hari Kemudian. Dan barangsiapa yang berpaling, maka sesungguhnya Allah Dialah yang Maha kaya lagi Maha Terpuji.'),
  ('id.indonesian', 60, 7, 'Mudah-mudahan Allah menimbulkan kasih sayang antaramu dengan orang-orang yang kamu musuhi di antara mereka. Dan Allah adalah Maha Kuasa. Dan Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 60, 8, 'Allah tidak melarang kamu untuk berbuat baik dan berlaku adil terhadap orang-orang yang tiada memerangimu karena agama dan tidak (pula) mengusir kamu dari negerimu. Sesungguhnya Allah menyukai orang-orang yang berlaku adil.'),
  ('id.indonesian', 60, 9, 'Sesungguhnya Allah hanya melarang kamu menjadikan sebagai kawanmu orang-orang yang memerangimu karena agama dan mengusir kamu dari negerimu, dan membantu (orang lain) untuk mengusirmu. Dan barangsiapa menjadikan mereka sebagai kawan, maka mereka itulah orang-orang yang zalim.'),
  ('id.indonesian', 60, 10, 'Hai orang-orang yang beriman, apabila datang berhijrah kepadamu perempuan-perempuan yang beriman, maka hendaklah kamu uji (keimanan) mereka. Allah lebih mengetahui tentang keimanan mereka; maka jika kamu telah mengetahui bahwa mereka (benar-benar) beriman maka janganlah kamu kembalikan mereka kepada (suami-suami mereka) orang-orang kafir. Mereka tiada halal bagi orang-orang kafir itu dan orang-orang kafir itu tiada halal pula bagi mereka. Dan berikanlah kepada (suami suami) mereka, mahar yang telah mereka bayar. Dan tiada dosa atasmu mengawini mereka apabila kamu bayar kepada mereka maharnya. Dan janganlah kamu tetap berpegang pada tali (perkawinan) dengan perempuan-perempuan kafir; dan hendaklah kamu minta mahar yang telah kamu bayar; dan hendaklah mereka meminta mahar yang telah mereka bayar. Demikianlah hukum Allah yang ditetapkan-Nya di antara kamu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 60, 11, 'Dan jika seseorang dari isteri-isterimu lari kepada orang-orang kafir, lalu kamu mengalahkan mereka maka bayarkanlah kepada orang-orang yang lari isterinya itu mahar sebanyak yang telah mereka bayar. Dan bertakwalah kepada Allah Yang kepada-Nya kamu beriman.'),
  ('id.indonesian', 60, 12, 'Hai Nabi, apabila datang kepadamu perempuan-perempuan yang beriman untuk mengadakan janji setia, bahwa mereka tiada akan menyekutukan Allah, tidak akan mencuri, tidak akan berzina, tidak akan membunuh anak-anaknya, tidak akan berbuat dusta yang mereka ada-adakan antara tangan dan kaki mereka dan tidak akan mendurhakaimu dalam urusan yang baik, maka terimalah janji setia mereka dan mohonkanlah ampunan kepada Allah untuk mereka. Sesungguhnya Allah maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 60, 13, 'Hai orang-orang yang beriman, janganlah kamu jadikan penolongmu kaum yang dimurkai Allah. Sesungguhnya mereka telah putus asa terhadap negeri akhirat sebagaimana orang-orang kafir yang telah berada dalam kubur berputus asa.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 61, 1, 'Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise.'),
  ('en.sahih', 61, 2, 'O you who have believed, why do you say what you do not do?'),
  ('en.sahih', 61, 3, 'Great is hatred in the sight of Allah that you say what you do not do.'),
  ('en.sahih', 61, 4, 'Indeed, Allah loves those who fight in His cause in a row as though they are a [single] structure joined firmly.'),
  ('en.sahih', 61, 5, 'And [mention, O Muhammad], when Moses said to his people, "O my people, why do you harm me while you certainly know that I am the messenger of Allah to you?" And when they deviated, Allah caused their hearts to deviate. And Allah does not guide the defiantly disobedient people.'),
  ('en.sahih', 61, 6, 'And [mention] when Jesus, the son of Mary, said, "O children of Israel, indeed I am the messenger of Allah to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Ahmad." But when he came to them with clear evidences, they said, "This is obvious magic."'),
  ('en.sahih', 61, 7, 'And who is more unjust than one who invents about Allah untruth while he is being invited to Islam. And Allah does not guide the wrongdoing people.'),
  ('en.sahih', 61, 8, 'They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it.'),
  ('en.sahih', 61, 9, 'It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allah dislike it.'),
  ('en.sahih', 61, 10, 'O you who have believed, shall I guide you to a transaction that will save you from a painful punishment?'),
  ('en.sahih', 61, 11, '[It is that] you believe in Allah and His Messenger and strive in the cause of Allah with your wealth and your lives. That is best for you, if you should know.'),
  ('en.sahih', 61, 12, 'He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment.'),
  ('en.sahih', 61, 13, 'And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers.'),
  ('en.sahih', 61, 14, 'O you who have believed, be supporters of Allah, as when Jesus, the son of Mary, said to the disciples, "Who are my supporters for Allah?" The disciples said, "We are supporters of Allah." And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 61, 1, 'নভোমন্ডলে ও ভূমন্ডলে যা কিছু আছে, সবই আল্লাহর পবিত্রতা ঘোষণা করে। তিনি পরাক্রান্ত প্রজ্ঞাবান।'),
  ('bn.bengali', 61, 2, 'মুমিনগণ! তোমরা যা কর না, তা কেন বল?'),
  ('bn.bengali', 61, 3, 'তোমরা যা কর না, তা বলা আল্লাহর কাছে খুবই অসন্তোষজনক।'),
  ('bn.bengali', 61, 4, 'আল্লাহ তাদেরকে ভালবাসেন, যারা তাঁর পথে সারিবদ্ধভাবে লড়াই করে, যেন তারা সীসাগালানো প্রাচীর।'),
  ('bn.bengali', 61, 5, 'স্মরণ কর, যখন মূসা (আঃ) তাঁর সম্প্রদায়কে বললঃ হে আমার সম্প্রদায়, তোমরা কেন আমাকে কষ্ট দাও, অথচ তোমরা জান যে, আমি তোমাদের কাছে আল্লাহর রসূল। অতঃপর তারা যখন বক্রতা অবলম্বন করল, তখন আল্লাহ তাদের অন্তরকে বক্র করে দিলেন। আল্লাহ পাপাচারী সম্প্রদায়কে পথপ্রদর্শন করেন না।'),
  ('bn.bengali', 61, 6, 'স্মরণ কর, যখন মরিয়ম-তনয় ঈসা (আঃ) বললঃ হে বনী ইসরাইল! আমি তোমাদের কাছে আল্লাহর প্রেরিত রসূল, আমার পূর্ববর্তী তওরাতের আমি সত্যায়নকারী এবং আমি এমন একজন রসূলের সুসংবাদদাতা, যিনি আমার পরে আগমন করবেন। তাঁর নাম আহমদ। অতঃপর যখন সে স্পষ্ট প্রমাণাদি নিয়ে আগমন করল, তখন তারা বললঃ এ তো এক প্রকাশ্য যাদু।'),
  ('bn.bengali', 61, 7, 'যে ব্যক্তি ইসলামের দিকে আহুত হয়েও আল্লাহ সম্পর্কে মিথ্যা বলে; তার চাইতে অধিক যালেম আর কে? আল্লাহ যালেম সম্প্রদায়কে পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 61, 8, 'তারা মুখের ফুঁৎকারে আল্লাহর আলো নিভিয়ে দিতে চায়। আল্লাহ তাঁর আলোকে পূর্ণরূপে বিকশিত করবেন যদিও কাফেররা তা অপছন্দ করে।'),
  ('bn.bengali', 61, 9, 'তিনি তাঁর রসূলকে পথ নির্দেশ ও সত্যধর্ম নিয়ে প্রেরণ করেছেন, যাতে একে সবধর্মের উপর প্রবল করে দেন যদিও মুশরিকরা তা অপছন্দ করে।'),
  ('bn.bengali', 61, 10, 'মুমিনগণ, আমি কি তোমাদেরকে এমন এক বানিজ্যের সন্ধান দিব, যা তোমাদেরকে যন্ত্রণাদায়ক শাস্তি থেকে মুক্তি দেবে?'),
  ('bn.bengali', 61, 11, 'তা এই যে, তোমরা আল্লাহ ও তাঁর রসূলের প্রতি বিশ্বাস স্থাপন করবে এবং আল্লাহর পথে নিজেদের ধন-সম্পদ ও জীবনপণ করে জেহাদ করবে। এটাই তোমাদের জন্যে উত্তম; যদি তোমরা বোঝ।'),
  ('bn.bengali', 61, 12, 'তিনি তোমাদের পাপরাশি ক্ষমা করবেন এবং এমন জান্নাতে দাখিল করবেন, যার পাদদেশে নদী প্রবাহিত এবং বসবাসের জান্নাতে উত্তম বাসগৃহে। এটা মহাসাফল্য।'),
  ('bn.bengali', 61, 13, 'এবং আরও একটি অনুগ্রহ দিবেন, যা তোমরা পছন্দ কর। আল্লাহর পক্ষ থেকে সাহায্য এবং আসন্ন বিজয়। মুমিনদেরকে এর সুসংবাদ দান করুন।'),
  ('bn.bengali', 61, 14, 'মুমিনগণ, তোমরা আল্লাহর সাহায্যকারী হয়ে যাও, যেমন ঈসা ইবনে-মরিয়ম তার শিষ্যবর্গকে বলেছিল, আল্লাহর পথে কে আমার সাহায্যকারী হবে? শিষ্যবর্গ বলেছিলঃ আমরা আল্লাহর পথে সাহায্যকারী। অতঃপর বনী-ইসরাঈলের একদল বিশ্বাস স্থাপন করল এবং একদল কাফের হয়ে গেল। যারা বিশ্বাস স্থাপন করেছিল, আমি তাদেরকে তাদের শত্রুদের মোকাবেলায় শক্তি যোগালাম, ফলে তারা বিজয়ী হল।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 61, 1, 'All that is in the heavens and all that is in the earth glorifieth Allah, and He is the Mighty, the Wise.'),
  ('en.pickthall', 61, 2, 'O ye who believe! Why say ye that which ye do not?'),
  ('en.pickthall', 61, 3, 'It is most hateful in the sight of Allah that ye say that which ye do not.'),
  ('en.pickthall', 61, 4, 'Lo! Allah loveth them who battle for His cause in ranks, as if they were a solid structure.'),
  ('en.pickthall', 61, 5, 'And (remember) when Moses said unto his people: O my people! Why persecute ye me, when ye well know that I am Allah\'s messenger unto you? So when they went astray Allah sent their hearts astray. And Allah guideth not the evil-living folk.'),
  ('en.pickthall', 61, 6, 'And when Jesus son of Mary said: O Children of Israel! Lo! I am the messenger of Allah unto you, confirming that which was (revealed) before me in the Torah, and bringing good tidings of a messenger who cometh after me, whose name is the Praised One. Yet when he hath come unto them with clear proofs, they say: This is mere magic.'),
  ('en.pickthall', 61, 7, 'And who doeth greater wrong than he who inventeth a lie against Allah when he is summoned unto Al-Islam? And Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 61, 8, 'Fain would they put out the light of Allah with their mouths, but Allah will perfect His light however much the disbelievers are averse.'),
  ('en.pickthall', 61, 9, 'He it is Who hath sent His messenger with the guidance and the religion of truth, that He may make it conqueror of all religion however much idolaters may be averse.'),
  ('en.pickthall', 61, 10, 'O ye who believe! Shall I show you a commerce that will save you from a painful doom?'),
  ('en.pickthall', 61, 11, 'Ye should believe in Allah and His messenger, and should strive for the cause of Allah with your wealth and your lives. That is better for you, if ye did but know.'),
  ('en.pickthall', 61, 12, 'He will forgive you your sins and bring you into Gardens underneath which rivers flow, and pleasant dwellings in Gardens of Eden. That is the supreme triumph.'),
  ('en.pickthall', 61, 13, 'And (He will give you) another (blessing) which ye love: help from Allah and present victory. Give good tidings (O Muhammad) to believers.'),
  ('en.pickthall', 61, 14, 'O ye who believe! Be Allah\'s helpers, even as Jesus son of Mary said unto the disciples: Who are my helpers for Allah? They said: We are Allah\'s helpers. And a party of the Children of Israel believed, while a party disbelieved. Then We strengthened those who believed against their foe, and they became the uppermost.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 61, 1, 'Whatever is in the heavens and on earth, let it declare the Praises and Glory of Allah: for He is the Exalted in Might, the Wise.'),
  ('en.yusufali', 61, 2, 'O ye who believe! Why say ye that which ye do not?'),
  ('en.yusufali', 61, 3, 'Grievously odious is it in the sight of Allah that ye say that which ye do not.'),
  ('en.yusufali', 61, 4, 'Truly Allah loves those who fight in His Cause in battle array, as if they were a solid cemented structure.'),
  ('en.yusufali', 61, 5, 'And remember, Moses said to his people: "O my people! why do ye vex and insult me, though ye know that I am the messenger of Allah (sent) to you?" Then when they went wrong, Allah let their hearts go wrong. For Allah guides not those who are rebellious transgressors.'),
  ('en.yusufali', 61, 6, 'And remember, Jesus, the son of Mary, said: "O Children of Israel! I am the messenger of Allah (sent) to you, confirming the Law (which came) before me, and giving Glad Tidings of a Messenger to come after me, whose name shall be Ahmad." But when he came to them with Clear Signs, they said, "this is evident sorcery!"'),
  ('en.yusufali', 61, 7, 'Who doth greater wrong than one who invents falsehood against Allah, even as he is being invited to Islam? And Allah guides not those who do wrong.'),
  ('en.yusufali', 61, 8, 'Their intention is to extinguish Allah\'s Light (by blowing) with their mouths: But Allah will complete (the revelation of) His Light, even though the Unbelievers may detest (it).'),
  ('en.yusufali', 61, 9, 'It is He Who has sent His Messenger with Guidance and the Religion of Truth, that he may proclaim it over all religion, even though the Pagans may detest (it).'),
  ('en.yusufali', 61, 10, 'O ye who believe! Shall I lead you to a bargain that will save you from a grievous Penalty?-'),
  ('en.yusufali', 61, 11, 'That ye believe in Allah and His Messenger, and that ye strive (your utmost) in the Cause of Allah, with your property and your persons: That will be best for you, if ye but knew!'),
  ('en.yusufali', 61, 12, 'He will forgive you your sins, and admit you to Gardens beneath which Rivers flow, and to beautiful mansions in Gardens of Eternity: that is indeed the Supreme Achievement.'),
  ('en.yusufali', 61, 13, 'And another (favour will He bestow,) which ye do love,- help from Allah and a speedy victory. So give the Glad Tidings to the Believers.'),
  ('en.yusufali', 61, 14, 'O ye who believe! Be ye helpers of Allah: As said Jesus the son of Mary to the Disciples, "Who will be my helpers to (the work of) Allah?" Said the disciples, "We are Allah\'s helpers!" then a portion of the Children of Israel believed, and a portion disbelieved: But We gave power to those who believed, against their enemies, and they became the ones that prevailed.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 61, 1, 'Sabbaha lillaahi maa fisamaawaati wa maa fil ardi wa huwal \'Azeezul Hakeem'),
  ('en.transliteration', 61, 2, 'Yaa ayyuhal lazeena aamanoo lima taqooloona maa laa taf\'aloon'),
  ('en.transliteration', 61, 3, 'Kabura maqtan \'indal laahi an taqooloo maa laa taf\'aloon'),
  ('en.transliteration', 61, 4, 'Innal laaha yuhibbul lazeena yuqaatiloona fee sabeelihee saffan kaannahum bunyaanum marsoos'),
  ('en.transliteration', 61, 5, 'Wa iz qaala Moosa liqawmihee yaa qawmi lima tu\'zoonanee wa qat ta\'lamoona annee Rasoolul laahi ilaikum falammaa zaaghooo azaaghal laahu quloobahum; wallaahu laa yahdil qawmal faasiqeen'),
  ('en.transliteration', 61, 6, 'Wa iz qaala \'Eesab-nu-Mayama yaa Banee Israaa\'eela innee Rasoolul laahi ilaikum musaddiqal limaa baina yadayya minat Tawraati wa mubashshiram bi Rasooliny yaatee mim ba\'dis muhooo Ahmad; falammaa jaaa\'ahum bil baiyinaati qaaloo haazaa sihrum mubeen'),
  ('en.transliteration', 61, 7, 'Wa man azlamu mimma nif taraa \'alal laahil kaziba wa huwa yad\'aaa ilal Islaam; wallaahu laa yahdil qawmaz zaalimeen'),
  ('en.transliteration', 61, 8, 'Yureedoona liyutfi\'oo nooral laahi bi afwaahimim wallaahu mutimmu noorihee wa law karihal kaafiroon'),
  ('en.transliteration', 61, 9, 'Huwal lazee arsala Rasoolahoo bilhudaa wa deenil haqqi liyuzhirahoo \'alad deeni kullihee wa law karihal mushrikoon'),
  ('en.transliteration', 61, 10, 'Yaaa ayyuhal lazeena aammano hal adullukum \'alaa tijaaratin tunjeekum min \'azaabin aleem'),
  ('en.transliteration', 61, 11, 'Tu\'minoona billaahi wa Rasoolihee wa tujaahidoona fee sabeelil laahi bi amwaalikum wa anfusikum; zaalikum khairul lakum in kuntum ta\'lamoon'),
  ('en.transliteration', 61, 12, 'Yaghfir lakum zunoobakum wa yudkhilkum Jannaatin tajree min tahtihal anhaaru wa masaakina taiyibatan fee Jannaati \'Ad; zaalikal fawzul \'Azeem'),
  ('en.transliteration', 61, 13, 'Wa ukhraa tuhibboonahaa nasrum minal laahi wa fat hun qaree; wa bashshiril mu \'mineen'),
  ('en.transliteration', 61, 14, 'Yaaa ayyuhal lazeena aamaanoo koonooo ansaaral laahi kamaa qaala \'Eesab-nu-Maryama lil Hawaariyyeena man ansaareee ilal laah; qaalal Hawaariyyoona nahnu ansaa rul laahi fa aamanat taaa\'ifatum mim Bannee Israaa\'eela wa kafarat taaa\'ifatun fa ayyadnal lazeena aammanoo \'alaa \'aduwwihim fa asbahoo zaahireen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 61, 1, 'جو مخلوقات آسمانو ں میں اور جو زمین میں ہے الله کی تسبیح کرتی ہے اور وہی غالب حکمت والا ہے'),
  ('ur.ahmedali', 61, 2, 'اے ایمان والو کیو ں کہتے ہو جو تم کرتے نہیں'),
  ('ur.ahmedali', 61, 3, 'الله کے نزدیک بڑی ناپسند بات ہے جو کہو اس کو کرو نہیں'),
  ('ur.ahmedali', 61, 4, 'بے شک الله تو ان کو پسند کرتا ہے جو اس کی راہ میں صف باندھ کر لڑتے ہیں گویا وہ سیسہ پلائی ہوئی دیوار ہے'),
  ('ur.ahmedali', 61, 5, 'اور جب موسیٰ نے اپنی قوم سے کہا کہ اے میری قوم مجھےکیوں ستاتے ہو حالانکہ تم جانتے ہو کہ میں تمہاری طرف الله کا رسول ہوں پس جب وہ پھر گئے تو الله نے ان کے دل پھیر دیئے اور الله نافرمان لوگو ں کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 61, 6, 'اور جب عیسیٰ بن مریم نے کہا اے بنی اسرائیل بے شک میں الله کا تمہاری طرف سے رسول ہوں تورات جو مجھ سے پہلے ہے اس کی تصدیق کرنے والا ہوں اور ایک رسول کی خوشخبری دینے والا ہوں جو میرے بعد آئے گا اس کا نام احمد ہو گا پس جب وہ واضح دلیلیں لے کر ان کے پاس آ گیا تو کہنے لگے یہ تو صریح جادو ہے'),
  ('ur.ahmedali', 61, 7, 'اور اس سے زیادہ کون ظالم ہے جو الله پر جھوٹ باندھے حالانکہ اسلام کی طرف اسے بلایا جارہا ہو اور ظالم لوگوں کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 61, 8, 'وہ چاہتے ہیں کہ الله کا نور اپنے مونہوں سے بجھا دیں اور الله اپنا نور پورا کر کے رہے گا اگرچہ کافر برا مانیں'),
  ('ur.ahmedali', 61, 9, 'وہی تو ہے جس نے اپنا رسول ہدایت اور سچا دین دے کر بھیجا تاکہ اس کو سب دینوں پر غالب کرے اگرچہ مشرک نا پسند کریں'),
  ('ur.ahmedali', 61, 10, 'اے ایمان والو کیا میں تمہیں ایسی تجارت بتاؤں جو تمہیں دردناک عذاب سے نجات دے'),
  ('ur.ahmedali', 61, 11, 'تم الله اور اس کے رسول پر ایمان لاؤ اور تم الله کی راہ میں اپنے مالوں اور اپنی جانوں سے جہاد کرو یہی تمہارے لیے بہتر ہے اگر تم جانتے ہو'),
  ('ur.ahmedali', 61, 12, 'وہ تمہارے لیے تمہارے گناہ بخش دے گا اور تمہیں بہشتوں میں داخل کر ے گا جن کے نیچے نہریں بہہ رہی ہوں گی اور پاکیزہ مکانوں میں ہمیشہ رہنے کے باغو ں میں یہ بڑی کامیابی ہے'),
  ('ur.ahmedali', 61, 13, 'اور دوسری بات جو تم پسند کرتے ہو الله کی طرف سے مدد ہے اور جلدی فتح اور ایمان والوں کو خوشخبری دے دے'),
  ('ur.ahmedali', 61, 14, 'ایمان والو الله کے مددگار ہو جاؤ جیسا کہ ابن مریم نے حواریوں سے کہا تھا کہ الله کی راہ میں میرا مددگار کون ہے حواریو ں نے کہا ہم الله کے مددگار ہیں پھر ایک گروہ بنی اسرائیل کا ایمان لایا اور ایک گروہ کافر ہو گیا پھر ہم نے ایمان داروں کو ان کے دشمنوں پر غالب کر دیا پھر تو وہی غالب ہو کر رہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 61, 1, 'Göklerde olanlar da yerde olanlar da Allah\'ı tesbih ederler. O, güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 61, 2, 'Ey inananlar! Yapmayacağınız şeyi niçin söylersiniz?'),
  ('tr.diyanet', 61, 3, 'Yapmayacağınız şeyi söylemeniz, Allah katında büyük gazaba sebep olur.'),
  ('tr.diyanet', 61, 4, 'Doğrusu Allah, kendi uğrunda, kenetlenmiş bir duvar gibi, saf halinde çarpışanları sever.'),
  ('tr.diyanet', 61, 5, 'Musa milletine: "Ey milletim! Beni niçin incitirsiniz? Oysa, benim size gönderilmiş Allah\'ın bir peygamberi olduğumu biliyorsunuz" demişti. Ama onlar yoldan sapınca, Allah da onların kalblerini saptırmıştı. Allah, yoldan çıkan milleti doğru yola eriştirmez.'),
  ('tr.diyanet', 61, 6, 'Meryem oğlu İsa: "Ey İsrailoğulları! Doğrusu ben, benden önce gelmiş olan Tevrat\'ı doğrulayan, benden sonra gelecek ve adı Ahmet olacak bir peygamberi müjdeleyen, Allah\'ın size gönderilmiş bir peygamberiyim" demişti. Ama o elçi, kendilerine belgelerle geldiği zaman: "Bu, apaçık bir sihirdir" demişlerdi.'),
  ('tr.diyanet', 61, 7, 'Müslüman olmağa çağırılmışken gelmeyip Allah\'a karşı yalan uydurandan daha zalim kimdir? Allah, zalim olan milleti doğru yola eriştirmez.'),
  ('tr.diyanet', 61, 8, 'Ağızlarıyla Allah\'ın nurunu söndürmek isterler. İnkarcılar ne kadar istemeseler de, Allah nurunu, dinini tamamlayacaktır.'),
  ('tr.diyanet', 61, 9, 'Ortak koşanlar istemese de, dinini bütün dinlerden üstün kılmak için, Peygamberini, doğruluk rehberi Kuran ve gerçek dinle gönderen O\'dur.'),
  ('tr.diyanet', 61, 10, 'Ey inananlar! Sizi can yakıcı bir azabdan kurtaracak, kazançlı bir yolu size göstereyim mi?'),
  ('tr.diyanet', 61, 11, 'Allah\'a ve Peygamberine inanırsınız; Allah yolunda canlarınızla, mallarınızla cihat edersiniz; bilseniz, bu sizin için en iyi yoldur.'),
  ('tr.diyanet', 61, 12, 'Böyle yaparsanız, Allah günahlarınızı size bağışlar, sizi, içlerinden ırmaklar akan cennetlere, Adn cennetlerinde hoş yerlere koyar. Büyük kurtuluş budur.'),
  ('tr.diyanet', 61, 13, 'Bundan başka, sevdiğiniz bir şey daha: Allah katından bir yardım ve yakın bir zafer vardır. İnananlara müjde ver.'),
  ('tr.diyanet', 61, 14, 'Ey inananlar! Allah\'ın dininin yardımcıları olun. Nitekim, Meryem oğlu İsa, Havarilere: "Allah\'a giden yolda yardımcılarım kimlerdir?" deyince, Havariler: "Allah\'ın dininin yardımcıları biziz" demişlerdi. İsrailoğullarının bir takımı böylece inanmış, bir takımı da inkar etmişti; ama Biz, inananları düşmanlarına karşı destekledik de üstün geldiler.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 61, 1, 'Telah bertasbih kepada Allah apa saja yang ada di langit dan apa saja yang ada di bumi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 61, 2, 'Wahai orang-orang yang beriman, kenapakah kamu mengatakan sesuatu yang tidak kamu kerjakan?'),
  ('id.indonesian', 61, 3, 'Amat besar kebencian di sisi Allah bahwa kamu mengatakan apa-apa yang tidak kamu kerjakan.'),
  ('id.indonesian', 61, 4, 'Sesungguhnya Allah menyukai orang yang berperang dijalan-Nya dalam barisan yang teratur seakan-akan mereka seperti suatu bangunan yang tersusun kokoh.'),
  ('id.indonesian', 61, 5, 'Dan (ingatlah) ketika Musa berkata kepada kaumnya: "Hai kaumku, mengapa kamu menyakitiku, sedangkan kamu mengetahui bahwa sesungguhnya aku adalah utusan Allah kepadamu?" Maka tatkala mereka berpaling (dari kebenaran), Allah memalingkan hati mereka; dan Allah tidak memberi petunjuk kepada kaum yang fasik.'),
  ('id.indonesian', 61, 6, 'Dan (ingatlah) ketika Isa ibnu Maryam berkata: "Hai Bani Israil, sesungguhnya aku adalah utusan Allah kepadamu, membenarkan kitab sebelumku, yaitu Taurat, dan memberi khabar gembira dengan (datangnya) seorang Rasul yang akan datang sesudahku, yang namanya Ahmad (Muhammad)". Maka tatkala rasul itu datang kepada mereka dengan membawa bukti-bukti yang nyata, mereka berkata: "Ini adalah sihir yang nyata".'),
  ('id.indonesian', 61, 7, 'Dan siapakah yang lebih zalim daripada orang yang mengada-adakan dusta terhadap Allah sedang dia diajak kepada Islam? Dan Allah tidak memberi petunjuk kepada orang-orang zalim.'),
  ('id.indonesian', 61, 8, 'Mereka ingin memadamkan cahaya Allah dengan mulut (tipu daya) mereka, tetapi Allah (justru) menyempurnakan cahaya-Nya, walau orang-orang kafir membencinya".'),
  ('id.indonesian', 61, 9, 'Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang benar agar Dia memenangkannya di atas segala agama-agama meskipun orang musyrik membenci.'),
  ('id.indonesian', 61, 10, 'Hai orang-orang yang beriman, sukakah kamu aku tunjukkan suatu perniagaan yang dapat menyelamatkanmu dari azab yang pedih?'),
  ('id.indonesian', 61, 11, '(yaitu) kamu beriman kepada Allah dan Rasul-Nya dan berjihad di jalan Allah dengan harta dan jiwamu. Itulah yang lebih baik bagimu, jika kamu mengetahui.'),
  ('id.indonesian', 61, 12, 'Niscaya Allah akan mengampuni dosa-dosamu dan memasukkanmu ke dalam jannah yang mengalir di bawahnya sungai-sungai; dan (memasukkan kamu) ke tempat tinggal yang baik di dalam jannah \'Adn. Itulah keberuntungan yang besar.'),
  ('id.indonesian', 61, 13, 'Dan (ada lagi) karunia yang lain yang kamu sukai (yaitu) pertolongan dari Allah dan kemenangan yang dekat (waktunya). Dan sampaikanlah berita gembira kepada orang-orang yang beriman.'),
  ('id.indonesian', 61, 14, 'Hai orang-orang yang beriman, jadilah kamu penolong (agama) Allah sebagaimana Isa ibnu Maryam telah berkata kepada pengikut-pengikutnya yang setia: "Siapakah yang akan menjadi penolong-penolongku (untuk menegakkan agama) Allah?" Pengikut-pengikut yang setia itu berkata: "Kamilah penolong-penolong agama Allah", lalu segolongan dari Bani Israil beriman dan segolongan lain kafir; maka Kami berikan kekuatan kepada orang-orang yang beriman terhadap musuh-musuh mereka, lalu mereka menjadi orang-orang yang menang.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 62, 1, 'Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise.'),
  ('en.sahih', 62, 2, 'It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error -'),
  ('en.sahih', 62, 3, 'And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise.'),
  ('en.sahih', 62, 4, 'That is the bounty of Allah, which He gives to whom He wills, and Allah is the possessor of great bounty.'),
  ('en.sahih', 62, 5, 'The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people.'),
  ('en.sahih', 62, 6, 'Say, "O you who are Jews, if you claim that you are allies of Allah, excluding the [other] people, then wish for death, if you should be truthful."'),
  ('en.sahih', 62, 7, 'But they will not wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers.'),
  ('en.sahih', 62, 8, 'Say, "Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do."'),
  ('en.sahih', 62, 9, 'O you who have believed, when [the adhan] is called for the prayer on the day of Jumu\'ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew.'),
  ('en.sahih', 62, 10, 'And when the prayer has been concluded, disperse within the land and seek from the bounty of Allah, and remember Allah often that you may succeed.'),
  ('en.sahih', 62, 11, 'But when they saw a transaction or a diversion, [O Muhammad], they rushed to it and left you standing. Say, "What is with Allah is better than diversion and than a transaction, and Allah is the best of providers."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 62, 1, 'রাজ্যাধিপতি, পবিত্র, পরাক্রমশালী ও প্রজ্ঞাময় আল্লাহর পবিত্রতা ঘোষণা করে, যা কিছু আছে নভোমন্ডলে ও যা কিছু আছে ভূমন্ডলে।'),
  ('bn.bengali', 62, 2, 'তিনিই নিরক্ষরদের মধ্য থেকে একজন রসূল প্রেরণ করেছেন, যিনি তাদের কাছে পাঠ করেন তার আয়াতসমূহ, তাদেরকে পবিত্র করেন এবং শিক্ষা দেন কিতাব ও হিকমত। ইতিপূর্বে তারা ছিল ঘোর পথভ্রষ্টতায় লিপ্ত।'),
  ('bn.bengali', 62, 3, 'এই রসূল প্রেরিত হয়েছেন অন্য আরও লোকদের জন্যে, যারা এখনও তাদের সাথে মিলিত হয়নি। তিনি পরাক্রমশালী, প্রজ্ঞাময়।'),
  ('bn.bengali', 62, 4, 'এটা আল্লাহর কৃপা, যাকে ইচ্ছা তিনি তা দান করেন। আল্লাহ মহাকৃপাশীল।'),
  ('bn.bengali', 62, 5, 'যাদেরকে তওরাত দেয়া হয়েছিল, অতঃপর তারা তার অনুসরণ করেনি, তাদের দৃষ্টান্ত সেই গাধা, যে পুস্তক বহন করে, যারা আল্লাহর আয়াতসমূহকে মিথ্যা বলে, তাদের দৃষ্টান্ত কত নিকৃষ্ট। আল্লাহ জালেম সম্প্রদায়কে পথ প্রদর্শন করেন না।'),
  ('bn.bengali', 62, 6, 'বলুন হে ইহুদীগণ, যদি তোমরা দাবী কর যে, তোমরাই আল্লাহর বন্ধু-অন্য কোন মানব নয়, তবে তোমরা মৃত্যু কামনা কর যদি তোমরা সত্যবাদী হও।'),
  ('bn.bengali', 62, 7, 'তারা নিজেদের কৃতকর্মের কারণে কখনও মৃত্যু কামনা করবে না। আল্লাহ জালেমদের সম্পর্কে সম্যক অবগত আছেন।'),
  ('bn.bengali', 62, 8, 'বলুন, তোমরা যে মৃত্যু থেকে পলায়নপর, সেই মৃত্যু অবশ্যই তোমাদের মুখামুখি হবে, অতঃপর তোমরা অদৃশ্য, দৃশ্যের জ্ঞানী আল্লাহর কাছে উপস্থিত হবে। তিনি তোমাদেরকে জানিয়ে দিবেন সেসব কর্ম, যা তোমরা করতে।'),
  ('bn.bengali', 62, 9, 'মুমিনগণ, জুমআর দিনে যখন নামাযের আযান দেয়া হয়, তখন তোমরা আল্লাহর স্মরণের পানে ত্বরা কর এবং বেচাকেনা বন্ধ কর। এটা তোমাদের জন্যে উত্তম যদি তোমরা বুঝ।'),
  ('bn.bengali', 62, 10, 'অতঃপর নামায সমাপ্ত হলে তোমরা পৃথিবীতে ছড়িয়ে পড় এবং আল্লাহর অনুগ্রহ তালাশ কর ও আল্লাহকে অধিক স্মরণ কর, যাতে তোমরা সফলকাম হও।'),
  ('bn.bengali', 62, 11, 'তারা যখন কোন ব্যবসায়ের সুযোগ অথবা ক্রীড়াকৌতুক দেখে তখন আপনাকে দাঁড়ানো অবস্থায় রেখে তারা সেদিকে ছুটে যায়। বলুনঃ আল্লাহর কাছে যা আছে, তা ক্রীড়াকৌতুক ও ব্যবসায় অপেক্ষা উৎকৃষ্ট। আল্লাহ সর্বোত্তম রিযিকদাতা।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 62, 1, 'All that is in the heavens and all that is in the earth glorifieth Allah, the Sovereign Lord, the Holy One, the Mighty, the Wise.'),
  ('en.pickthall', 62, 2, 'He it is Who hath sent among the unlettered ones a messenger of their own, to recite unto them His revelations and to make them grow, and to teach them the Scripture and wisdom, though heretofore they were indeed in error manifest,'),
  ('en.pickthall', 62, 3, 'Along with others of them who have not yet joined them. He is the Mighty, the Wise.'),
  ('en.pickthall', 62, 4, 'That is the bounty of Allah; which He giveth unto whom He will. Allah is of Infinite Bounty.'),
  ('en.pickthall', 62, 5, 'The likeness of those who are entrusted with the Law of Moses, yet apply it not, is as the likeness of the ass carrying books. Wretched is the likeness of folk who deny the revelations of Allah. And Allah guideth not wrongdoing folk.'),
  ('en.pickthall', 62, 6, 'Say (O Muhammad): O ye who are Jews! If ye claim that ye are favoured of Allah apart from (all) mankind, then long for death if ye are truthful.'),
  ('en.pickthall', 62, 7, 'But they will never long for it because of all that their own hands have sent before, and Allah is Aware of evil-doers.'),
  ('en.pickthall', 62, 8, 'Say (unto them, O Muhammad): Lo! the death from which ye shrink will surely meet you, and afterward ye will be returned unto the Knower of the Invisible and the Visible, and He will tell you what ye used to do.'),
  ('en.pickthall', 62, 9, 'O ye who believe! When the call is heard for the prayer of the day of congregation, haste unto remembrance of Allah and leave your trading. That is better for you if ye did but know.'),
  ('en.pickthall', 62, 10, 'And when the prayer is ended, then disperse in the land and seek of Allah\'s bounty, and remember Allah much, that ye may be successful.'),
  ('en.pickthall', 62, 11, 'But when they spy some merchandise or pastime they break away to it and leave thee standing. Say: That which Allah hath is better than pastime and than merchandise, and Allah is the Best of providers.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 62, 1, 'Whatever is in the heavens and on earth, doth declare the Praises and Glory of Allah,- the Sovereign, the Holy One, the Exalted in Might, the Wise.'),
  ('en.yusufali', 62, 2, 'It is He Who has sent amongst the Unlettered a messenger from among themselves, to rehearse to them His Signs, to sanctify them, and to instruct them in Scripture and Wisdom,- although they had been, before, in manifest error;-'),
  ('en.yusufali', 62, 3, 'As well as (to confer all these benefits upon) others of them, who have not already joined them: And He is exalted in Might, Wise.'),
  ('en.yusufali', 62, 4, 'Such is the Bounty of Allah, which He bestows on whom He will: and Allah is the Lord of the highest bounty.'),
  ('en.yusufali', 62, 5, 'The similitude of those who were charged with the (obligations of the) Mosaic Law, but who subsequently failed in those (obligations), is that of a donkey which carries huge tomes (but understands them not). Evil is the similitude of people who falsify the Signs of Allah: and Allah guides not people who do wrong.'),
  ('en.yusufali', 62, 6, 'Say: "O ye that stand on Judaism! If ye think that ye are friends to Allah, to the exclusion of (other) men, then express your desire for Death, if ye are truthful!"'),
  ('en.yusufali', 62, 7, 'But never will they express their desire (for Death), because of the (deeds) their hands have sent on before them! and Allah knows well those that do wrong!'),
  ('en.yusufali', 62, 8, 'Say: "The Death from which ye flee will truly overtake you: then will ye be sent back to the Knower of things secret and open: and He will tell you (the truth of) the things that ye did!"'),
  ('en.yusufali', 62, 9, 'O ye who believe! When the call is proclaimed to prayer on Friday (the Day of Assembly), hasten earnestly to the Remembrance of Allah, and leave off business (and traffic): That is best for you if ye but knew!'),
  ('en.yusufali', 62, 10, 'And when the Prayer is finished, then may ye disperse through the land, and seek of the Bounty of Allah: and celebrate the Praises of Allah often (and without stint): that ye may prosper.'),
  ('en.yusufali', 62, 11, 'But when they see some bargain or some amusement, they disperse headlong to it, and leave thee standing. Say: "The (blessing) from the Presence of Allah is better than any amusement or bargain! and Allah is the Best to provide (for all needs)."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 62, 1, 'Yusabbihu lilaahi maa fis samaawaati wa maa fil ardil Malikil Quddoosil \'Azeezil Hakeem'),
  ('en.transliteration', 62, 2, 'Huwal lazee ba\'asa fil ummiyyeena Rasoolam min hum yatloo \'alaihim aayaatihee wa yuzakkeehim wa yu\'allimuhumul Kitaaba wal Hikmata wa in kaano min qablu lafee dalaalim mubeen'),
  ('en.transliteration', 62, 3, 'Wa aakhareena minhum lammaa yalhaqoo bihim wa huwal \'azeezul hakeem'),
  ('en.transliteration', 62, 4, 'Zaalika fadlul laahi yu\'teehi many-yashaaa; wallaahu zul fadil \'azeem'),
  ('en.transliteration', 62, 5, 'Masalul lazeena hum milut tawraata summa lam yahmiloonhaa kamasalil himaari yah milu asfaaraa; bi\'sa masalul qawmil lazeena kaazzaboo bi aayaatil laah; wallaahu laa yahdil qawmazzaalimeen'),
  ('en.transliteration', 62, 6, 'Qul yaaa ayyuhal lazeena haadoo in za\'amtum annakum awliyaaa\'u lilaahi min doonin naasi fatamannawul mawta in kuntum saadiqeen'),
  ('en.transliteration', 62, 7, 'Wa laa yatamannaw nahooo abadam bimaa qaddamat aydeehim; wallaahu \'aleemum bix zaalimeen'),
  ('en.transliteration', 62, 8, 'Qul innal mawtal lazee tafirroona minhu fa innahoo mulaaqeekum summa turaddoona ilaa \'Aalimil Ghaibi wash shahaadati fa yunabbi\'ukum bimaa kuntum ta\'maloon'),
  ('en.transliteration', 62, 9, 'Yaaa ayyuhal lazeena aamanoo izaa noodiya lis-Salaati miny yawmil Jumu\'ati fas\'aw ilaa zikril laahi wa zarul bai\'; zaalikum khayrul lakum in kuntum ta\'lamoon'),
  ('en.transliteration', 62, 10, 'Fa-izaa qudiyatis Salaatu fantashiroo fil ardi wabtaghoo min fadlil laahi wazkurul laaha kaseeral la\'allakum tuflihoon'),
  ('en.transliteration', 62, 11, 'Wa izaa ra\'aw tijaaratan aw lahwanin faddooo ilaihaa wa tarakooka qaaa\'imaa; qul maa \'indal laahi khairum minal lahwi wa minat tijaarah; wallaahu khayrur raaziqeen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 62, 1, 'جو مخلوقات آسمانوں اور زمین میں ہے الله کی تسبیح کرتی ہے وہ بادشاہ پاک ذات غالب حکمت والا ہے'),
  ('ur.ahmedali', 62, 2, 'وہی ہے جس نے ان پڑھوں میں ایک رسول انہیں میں سے مبعوث فرمایا جو ان پر اس کی آیتیں پڑھتا ہے اور انہیں پاک کرتا ہے اور انہیں کتاب اور حکمت سکھاتا ہے اور بے شک وہ اس سے پہلے صریح گمراہی میں تھے'),
  ('ur.ahmedali', 62, 3, 'اور دوسروں کے لیے بھی جو ابھی ان سے نہیں ملے اور وہ زبردست حکمت والا ہے'),
  ('ur.ahmedali', 62, 4, 'یہ الله کا فضل ہے جسے چاہے دے اور الله بڑا فضل کرنے والا ہے'),
  ('ur.ahmedali', 62, 5, 'ان لوگو ں کی مثال جنہیں تورات اٹھوائی گئی پھر انہوں نے اسے نہ اٹھایا گدھے کی سی مثال ہے جو کتابیں اٹھاتا ہے ان لوگوں کی بہت بری مثال ہے جنہوں نے الله کی آیتو ں کو جھٹلایا اور الله ظالم لوگوں کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 62, 6, 'کہہ دو اے لوگو جو یہودی ہو اگر تم خیال کرتے ہو کہ تم ہی الله کے دوست ہو سوائے دوسرے لوگوں کے تو موت کی آرزو کرو اگر تم سچے ہو'),
  ('ur.ahmedali', 62, 7, 'اور وہ لوگ اس کی کبھی بھی تمنا نہ کریں گے بسبب ان (عملوں) کے جو ان کے ہاتھوں نے آگے بھیجے اور الله ظالموں کو خوب جانتا ہے'),
  ('ur.ahmedali', 62, 8, 'کہہ دو بے شک وہ موت جس سے تم بھاگتے ہو سو وہ تو ضرور تمہیں ملنے والی ہے پھر تم اس کی طرف لوٹائے جاؤ گے جو ہر چھپی اور کھلی بات کا جاننے والا ہے پھر وہ تمہیں بتائے گا جو کچھ تم کیا کرتے تھے'),
  ('ur.ahmedali', 62, 9, 'اے ایمان والو جب جمعہ کے دن نماز کے لیے اذان دی جائے تو ذکر الہیٰ کی طرف لپکو اور خرید و فروخت چھوڑ دو تمہارے لیے یہی بات بہتر ہے اگر تم علم رکھتے ہو'),
  ('ur.ahmedali', 62, 10, 'پس جب نماز ادا ہو چکے تو زمین میں چلو پھرو اور الله کا فضل تلاش کرو اور الله کو بہت یاد کرو تاکہ تم فلاح پاؤ'),
  ('ur.ahmedali', 62, 11, 'اور جب وہ لوگ تجارت یاتماشہ دیکھتے ہیں تو اس پر ٹوٹ پڑتے ہیں اور آپ کو کھڑا ہوا چھوڑ جاتے ہیں کہہ دو جو الله کے پاس ہے وہ تماشا اور تجارت سے کہیں بہتر ہے اور الله بہتر روزی دینے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 62, 1, 'Göklerde olanlar ve yerde bulunanlar, hükümran, çok kutsal, güçlü ve Hakim olan Allah\'ı tesbih ederler.'),
  ('tr.diyanet', 62, 2, 'Kitapsız (okuma-yazma bilmeyen) kimseler arasından, kendilerine ayetlerini okuyan, onları arıtan, onlara Kitabı ve hikmeti öğreten bir Peygamber gönderen O\'dur. Onlar, daha önce, şüphesiz apaçık bir sapıklık içinde idiler.'),
  ('tr.diyanet', 62, 3, 'Onlardan başkalarına da -ki henüz onlara katılmamışlardır- Kitap ve hikmeti öğretmek üzere, Peygamberi gönderen Allah\'tır. O, güçlüdür, Hakim\'dir.'),
  ('tr.diyanet', 62, 4, 'Bu, Allah\'ın dilediğine verdiği lütfüdür. Allah, büyük lütuf sahibidir.'),
  ('tr.diyanet', 62, 5, 'Kendilerine Tevrat öğretildiği halde, onun gereğini yapmayanların durumu, sırtına kitap yüklenmiş merkebin durumu gibidir. Allah\'ın ayetlerini yalanlayan kimselerin durumu ne kötüdür! Allah zalimleri doğru yola eriştirmez.'),
  ('tr.diyanet', 62, 6, 'De ki: "Ey Yahudiler! Bütün insanlar bir yana, yalnız kendinizin Allah\'ın dostları olduğunuzu iddia ediyorsanız ve bunda samimi iseniz, ölümü dilesenize!"'),
  ('tr.diyanet', 62, 7, 'Yaptıklarından ötürü, ölümü asla dileyemezler. Allah, zalimleri bilendir.'),
  ('tr.diyanet', 62, 8, 'De ki: "Doğrusu kendisinden kaçtığınız ölüm mutlaka karşınıza çıkacaktır; sonra; görüleni de görülmeyeni de bilen Allah\'a döndürüleceksiniz, O size işlediklerinizi haber verecektir."'),
  ('tr.diyanet', 62, 9, 'Ey inananlar! Cuma günü namaz için ezan okunduğu zaman Allah\'ı anmaya koşun; alım satımı bırakın; bilseniz, bu sizin için daha iyidir.'),
  ('tr.diyanet', 62, 10, 'Namaz bitince yeryüzüne yayılın; Allah\'ın lütfundan rızık isteyin; Allah\'ı çok anın ki saadete erişesiniz.'),
  ('tr.diyanet', 62, 11, 'Onlar bir kazanç veya bir eğlence gördüklerinde, seni ayakta bırakarak oraya yöneldiler. De ki: "Allah katında olan, eğlenceden de kazançtan da hayırlıdır. Allah, rızık verenlerin en iyisidir."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 62, 1, 'Senantiasa bertasbih kepada Allah apa yang ada di langit dan apa yang ada di bumi. Raja, Yang Maha Suci, Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 62, 2, 'Dialah yang mengutus kepada kaum yang buta huruf seorang Rasul di antara mereka, yang membacakan ayat-ayat-Nya kepada mereka, mensucikan mereka dan mengajarkan mereka Kitab dan Hikmah (As Sunnah). Dan sesungguhnya mereka sebelumnya benar-benar dalam kesesatan yang nyata,'),
  ('id.indonesian', 62, 3, 'dan (juga) kepada kaum yang lain dari mereka yang belum berhubungan dengan mereka. Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.'),
  ('id.indonesian', 62, 4, 'Demikianlah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya; dan Allah mempunyai karunia yang besar.'),
  ('id.indonesian', 62, 5, 'Perumpamaan orang-orang yang dipikulkan kepadanya Taurat, kemudian mereka tiada memikulnya adalah seperti keledai yang membawa kitab-kitab yang tebal. Amatlah buruknya perumpamaan kaum yang mendustakan ayat-ayat Allah itu. Dan Allah tiada memberi petunjuk kepada kaum yang zalim.'),
  ('id.indonesian', 62, 6, 'Katakanlah: "Hai orang-orang yang menganut agama Yahudi, jika kamu mendakwakan bahwa sesungguhnya kamu sajalah kekasih Allah bukan manusia-manusia yang lain, maka harapkanlah kematianmu, jika kamu adalah orang-orang yang benar".'),
  ('id.indonesian', 62, 7, 'Mereka tiada akan mengharapkan kematian itu selama-lamanya disebabkan kejahatan yang telah mereka perbuat dengan tangan mereka sendiri. Dan Allah Maha Mengetahui akan orang-orang yang zalim.'),
  ('id.indonesian', 62, 8, 'Katakanlah: "Sesungguhnya kematian yang kamu lari daripadanya, maka sesungguhnya kematian itu akan menemui kamu, kemudian kamu akan dikembalikan kepada (Allah), yang mengetahui yang ghaib dan yang nyata, lalu Dia beritakan kepadamu apa yang telah kamu kerjakan".'),
  ('id.indonesian', 62, 9, 'Hai orang-orang beriman, apabila diseru untuk menunaikan shalat Jum\'at, maka bersegeralah kamu kepada mengingat Allah dan tinggalkanlah jual beli. Yang demikian itu lebih baik bagimu jika kamu mengetahui.'),
  ('id.indonesian', 62, 10, 'Apabila telah ditunaikan shalat, maka bertebaranlah kamu di muka bumi; dan carilah karunia Allah dan ingatlah Allah banyak-banyak supaya kamu beruntung.'),
  ('id.indonesian', 62, 11, 'Dan apabila mereka melihat perniagaan atau permainan, mereka bubar untuk menuju kepadanya dan mereka tinggalkan kamu sedang berdiri (berkhotbah). Katakanlah: "Apa yang di sisi Allah lebih baik daripada permainan dan perniagaan", dan Allah Sebaik-baik Pemberi rezeki.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 63, 1, 'When the hypocrites come to you, [O Muhammad], they say, "We testify that you are the Messenger of Allah." And Allah knows that you are His Messenger, and Allah testifies that the hypocrites are liars.'),
  ('en.sahih', 63, 2, 'They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing.'),
  ('en.sahih', 63, 3, 'That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand.'),
  ('en.sahih', 63, 4, 'And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allah destroy them; how are they deluded?'),
  ('en.sahih', 63, 5, 'And when it is said to them, "Come, the Messenger of Allah will ask forgiveness for you," they turn their heads aside and you see them evading while they are arrogant.'),
  ('en.sahih', 63, 6, 'It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allah forgive them. Indeed, Allah does not guide the defiantly disobedient people.'),
  ('en.sahih', 63, 7, 'They are the ones who say, "Do not spend on those who are with the Messenger of Allah until they disband." And to Allah belongs the depositories of the heavens and the earth, but the hypocrites do not understand.'),
  ('en.sahih', 63, 8, 'They say, "If we return to al-Madinah, the more honored [for power] will surely expel therefrom the more humble." And to Allah belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know.'),
  ('en.sahih', 63, 9, 'O you who have believed, let not your wealth and your children divert you from remembrance of Allah. And whoever does that - then those are the losers.'),
  ('en.sahih', 63, 10, 'And spend [in the way of Allah] from what We have provided you before death approaches one of you and he says, "My Lord, if only You would delay me for a brief term so I would give charity and be among the righteous."'),
  ('en.sahih', 63, 11, 'But never will Allah delay a soul when its time has come. And Allah is Acquainted with what you do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 63, 1, 'মুনাফিকরা আপনার কাছে এসে বলেঃ আমরা সাক্ষ্য দিচ্ছি যে আপনি নিশ্চয়ই আল্লাহর রসূল। আল্লাহ জানেন যে, আপনি অবশ্যই আল্লাহর রসূল এবং আল্লাহ সাক্ষ্য দিচ্ছেন যে, মুনাফিকরা অবশ্যই মিথ্যাবাদী।'),
  ('bn.bengali', 63, 2, 'তারা তাদের শপথসমূহকে ঢালরূপে ব্যবহার করে। অতঃপর তারা আল্লাহর পথে বাধা সৃষ্টি করে। তারা যা করছে, তা খুবই মন্দ।'),
  ('bn.bengali', 63, 3, 'এটা এজন্য যে, তারা বিশ্বাস করার পর পুনরায় কাফের হয়েছে। ফলে তাদের অন্তরে মোহর মেরে দেয়া হয়েছে। অতএব তারা বুঝে না।'),
  ('bn.bengali', 63, 4, 'আপনি যখন তাদেরকে দেখেন, তখন তাদের দেহাবয়ব আপনার কাছে প্রীতিকর মনে হয়। আর যদি তারা কথা বলে, তবে আপনি তাদের কথা শুনেন। তারা প্রাচীরে ঠেকানো কাঠসদৃশ্য। প্রত্যেক শোরগোলকে তারা নিজেদের বিরুদ্ধে মনে করে। তারাই শত্রু, অতএব তাদের সম্পর্কে সতর্ক হোন। ধ্বংস করুন আল্লাহ তাদেরকে। তারা কোথায় বিভ্রান্ত হচ্ছে ?'),
  ('bn.bengali', 63, 5, 'যখন তাদেরকে বলা হয়ঃ তোমরা এস, আল্লাহর রসূল তোমাদের জন্য ক্ষমাপ্রার্থনা করবেন, তখন তারা মাথা ঘুরিয়ে নেয় এবং আপনি তাদেরকে দেখেন যে, তারা অহংকার করে মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 63, 6, 'আপনি তাদের জন্যে ক্ষমাপ্রার্থনা করুন অথবা না করুন, উভয়ই সমান। আল্লাহ কখনও তাদেরকে ক্ষমা করবেন না। আল্লাহ পাপাচারী সম্প্রদায়কে পথপ্রদর্শন করেন না।'),
  ('bn.bengali', 63, 7, 'তারাই বলেঃ আল্লাহর রাসূলের সাহচর্যে যারা আছে তাদের জন্যে ব্যয় করো না। পরিণামে তারা আপনা-আপনি সরে যাবে। ভূ ও নভোমন্ডলের ধন-ভান্ডার আল্লাহরই কিন্তু মুনাফিকরা তা বোঝে না।'),
  ('bn.bengali', 63, 8, 'তারাই বলেঃ আমরা যদি মদীনায় প্রত্যাবর্তন করি তবে সেখান থেকে সবল অবশ্যই দুর্বলকে বহিস্কৃত করবে। শক্তি তো আল্লাহ তাঁর রসূল ও মুমিনদেরই কিন্তু মুনাফিকরা তা জানে না।'),
  ('bn.bengali', 63, 9, 'মুমিনগণ! তোমাদের ধন-সম্পদ ও সন্তান-সন্ততি যেন তোমাদেরকে আল্লাহর স্মরণ থেকে গাফেল না করে। যারা এ কারণে গাফেল হয়, তারাই তো ক্ষতিগ্রস্ত।'),
  ('bn.bengali', 63, 10, 'আমি তোমাদেরকে যা দিয়েছি, তা থেকে মৃত্যু আসার আগেই ব্যয় কর। অন্যথায় সে বলবেঃ হে আমার পালনকর্তা, আমাকে আরও কিছুকাল অবকাশ দিলে না কেন? তাহলে আমি সদকা করতাম এবং সৎকর্মীদের অন্তর্ভুক্ত হতাম।'),
  ('bn.bengali', 63, 11, 'প্রত্যেক ব্যক্তির নির্ধারিত সময় যখন উপস্থিত হবে, তখন আল্লাহ কাউকে অবকাশ দেবেন না। তোমরা যা কর, আল্লাহ সে বিষয়ে খবর রাখেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 63, 1, 'When the hypocrites come unto thee (O Muhammad), they say: We bear witness that thou art indeed Allah\'s messenger. And Allah knoweth that thou art indeed His messenger, and Allah beareth witness that the hypocrites indeed are speaking falsely.'),
  ('en.pickthall', 63, 2, 'They make their faith a pretext so that they may turn (men) from the way of Allah. Verily evil is that which they are wont to do,'),
  ('en.pickthall', 63, 3, 'That is because they believed, then disbelieved, therefore their hearts are sealed so that they understand not.'),
  ('en.pickthall', 63, 4, 'And when thou seest them their figures please thee; and if they speak thou givest ear unto their speech. (They are) as though they were blocks of wood in striped cloaks. They deem every shout to be against them. They are the enemy, so beware of them. Allah confound them! How they are perverted!'),
  ('en.pickthall', 63, 5, 'And when it is said unto them: Come! The messenger of Allah will ask forgiveness for you! they avert their faces and thou seest them turning away, disdainful.'),
  ('en.pickthall', 63, 6, 'Whether thou ask forgiveness for them or ask not forgiveness for them is all one for them; Allah will not forgive them. Lo! Allah guideth not the evil-living folk.'),
  ('en.pickthall', 63, 7, 'They it is who say: Spend not on behalf of those (who dwell) with Allah\'s messenger that they may disperse (and go away from you); when Allah\'s are the treasures of the heavens and the earth; but the hypocrites comprehend not.'),
  ('en.pickthall', 63, 8, 'They say: Surely, if we return to Al-Madinah the mightier will soon drive out the weaker; when might belongeth to Allah and to His messenger and to the believers; but the hypocrites know not.'),
  ('en.pickthall', 63, 9, 'O ye who believe! Let not your wealth nor your children distract you from remembrance of Allah. Those who do so, they are the losers.'),
  ('en.pickthall', 63, 10, 'And spend of that wherewith We have provided you before death cometh unto one of you and he saith: My Lord! If only thou wouldst reprieve me for a little while, then I would give alms and be among the righteous.'),
  ('en.pickthall', 63, 11, 'But Allah reprieveth no soul when its term cometh, and Allah is Informed of what ye do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 63, 1, 'When the Hypocrites come to thee, they say, "We bear witness that thou art indeed the Messenger of Allah." Yea, Allah knoweth that thou art indeed His Messenger, and Allah beareth witness that the Hypocrites are indeed liars.'),
  ('en.yusufali', 63, 2, 'They have made their oaths a screen (for their misdeeds): thus they obstruct (men) from the Path of Allah: truly evil are their deeds.'),
  ('en.yusufali', 63, 3, 'That is because they believed, then they rejected Faith: So a seal was set on their hearts: therefore they understand not.'),
  ('en.yusufali', 63, 4, 'When thou lookest at them, their exteriors please thee; and when they speak, thou listenest to their words. They are as (worthless as hollow) pieces of timber propped up, (unable to stand on their own). They think that every cry is against them. They are the enemies; so beware of them. The curse of Allah be on them! How are they deluded (away from the Truth)!'),
  ('en.yusufali', 63, 5, 'And when it is said to them, "Come, the Messenger of Allah will pray for your forgiveness", they turn aside their heads, and thou wouldst see them turning away their faces in arrogance.'),
  ('en.yusufali', 63, 6, 'It is equal to them whether thou pray for their forgiveness or not. Allah will not forgive them. Truly Allah guides not rebellious transgressors.'),
  ('en.yusufali', 63, 7, 'They are the ones who say, "Spend nothing on those who are with Allah\'s Messenger, to the end that they may disperse (and quit Medina)." But to Allah belong the treasures of the heavens and the earth; but the Hypocrites understand not.'),
  ('en.yusufali', 63, 8, 'They say, "If we return to Medina, surely the more honourable (element) will expel therefrom the meaner." But honour belongs to Allah and His Messenger, and to the Believers; but the Hypocrites know not.'),
  ('en.yusufali', 63, 9, 'O ye who believe! Let not your riches or your children divert you from the remembrance of Allah. If any act thus, the loss is their own.'),
  ('en.yusufali', 63, 10, 'and spend something (in charity) out of the substance which We have bestowed on you, before Death should come to any of you and he should say, "O my Lord! why didst Thou not give me respite for a little while? I should then have given (largely) in charity, and I should have been one of the doers of good".'),
  ('en.yusufali', 63, 11, 'But to no soul will Allah grant respite when the time appointed (for it) has come; and Allah is well acquainted with (all) that ye do.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 63, 1, 'Izaa jaaa\'akal munaafiqoona qaaloo nashhadu innaka la rasoolul laah; wallaahu ya\'lamu innaka la rasooluhoo wallaahu yashhadu innal munaafiqeena lakaaziboon'),
  ('en.transliteration', 63, 2, 'Ittakhazoo aymaanahum junnatan fasaddoo \'an sabeelil laah; innahum saaa\'a maa kaanoo ya\'maloon'),
  ('en.transliteration', 63, 3, 'Zaalika bi annahum aamanoo summa kafaroo fatubi\'a \'alaa quloobihim fahum laa yafqahoon'),
  ('en.transliteration', 63, 4, 'Wa izaa ra aytahum tu\'jibuka ajsaamuhum wa iny yaqooloo tasma\' liqawlihim kaannahum khushubum musannadah; yahsaboona kulla saihatin \'alaihim; humul \'aduwwu fahzarhum; qaatalahumul laahu annaa yu\'fakoon'),
  ('en.transliteration', 63, 5, 'Wa izaa qeela lahum ta\'aalaw yastaghfir lakum rasoolul laahi lawwaw ru\'oo sahum wa ra aytahum yasuddoona wa hum mustakbiroon'),
  ('en.transliteration', 63, 6, 'Sawaaa\'un \'alaihim as taghfarta lahum am lam tastaghfir lahum lany yaghfiral laahu lahum; innal laaha laa yahdil qawmal faasiqeen'),
  ('en.transliteration', 63, 7, 'Humul lazeena yaqooloona laa tunfiqoo \'alaa man inda Rasoolil laahi hatta yanfaddoo; wa lillaahi khazaaa\' inus samaawaati wal ardi wa laakinnal munaafiqeena la yafqahoon'),
  ('en.transliteration', 63, 8, 'Yaqooloona la\'ir raja\'naaa ilal madeenati la yukhrijanal a\'azzu minhal azall; wa lillaahil \'izzatu wa li Rasoolihee wa lilmu\'mineena wa laakinnal munaafiqeena laa ya\'lamoon'),
  ('en.transliteration', 63, 9, 'Yaaa ayyuhal lazeena aamanoo la tulhikum amwaalukum wa laa awlaadukum \'anzikril laah; wa mai-yaf\'al zaalika fa-ulaaa\'ika humul khaasiroon'),
  ('en.transliteration', 63, 10, 'Wa anifqoo mim maa razaqnaakum min qabli any-yaatiya ahadakumul mawtu fa yaqoola rabbi law laaa akhkhartaneee ilaaa ajalin qareebin fa assaddaqa wa akum minassaaliheen'),
  ('en.transliteration', 63, 11, 'Wa lany yu \'akhkhiral laahu nafsan izaa jaaa\'a ajaluhaa; wallaahu khabeerum bimaa ta\'maloon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 63, 1, 'جب آپ کے پاس منافق آتے ہیں تو کہتے ہیں ہم گواہی دیتے ہیں کہ بے شک آپ الله کے رسول ہیں اور الله جانتا ہے کہ بے شک آپ اس کے رسول ہیں اور الله گواہی دیتا ہے کہ بے شک منافق جھوٹے ہیں'),
  ('ur.ahmedali', 63, 2, 'انہوں نے اپنی قسموں کو ڈھال بنا کر رکھا ہے پھر (لوگوں کو) الله کی راہ سے روکتے ہیں بے شک کیسا برا کام ہے جو وہ کر رہے ہیں'),
  ('ur.ahmedali', 63, 3, 'یہ اس لیے کہ وہ ایمان لائے پھر منکر ہو گئے پس ان کے دلوں پر مہر کر دی گئی ہے پس وہ نہیں سمجھتے'),
  ('ur.ahmedali', 63, 4, 'اور جب آپ ان کو دیکھیں تو اپ کو ان کے ڈیل ڈول اچھے لگیں اور اگر وہ بات کریں تو آپ انکی بات سن لیں گویا کہ وہ دیوار سے لگی ہوئی لکڑیاں ہیں وہ ہر آواز کو اپنے ہی اُوپر خیال کرتے ہیں وہی دشمن ہیں پس ان سے ہوشیار رہيے الله انہیں غارت کرے کہاں وہ بہکے جا رہے ہیں'),
  ('ur.ahmedali', 63, 5, 'اور جب ان سے کہا جائے کہ آؤ تمہارے لیے رسول الله مغفرت طلب کریں تو اپنے سر پھیر لیتے ہیں اور آپ انہیں دیکھیں گے کہ وہ رکتے ہیں ایسے حال میں کہ وہ تکبر کرنے والے ہیں'),
  ('ur.ahmedali', 63, 6, 'برابر ہے خواہ وہ آپ ان کے لیے معافی مانگیں یا نہ مانگیں اللهانہیں ہر گز نہیں بخشے گا بے شک الله بدکار قوم کو ہدایت نہیں کرتا'),
  ('ur.ahmedali', 63, 7, 'وہی لوگ ہیں جوکہتے ہیں کہ ان پر خرچ نہ کرو جو رسول الله کے پاس ہیں یہاں تک کہ وہ تتر بتر ہو جائیں اور آسمانوں اور زمین کے خزانے الله ہی کے لیے ہیں لیکن منافق نہیں سمجھتے'),
  ('ur.ahmedali', 63, 8, 'وہ کہتے ہیں کہ اگر ہم مدینہ کی طرف لوٹ کر گئے تو اس میں سے عزت والا ذلیل کو ضرور نکال دے گا اور عزت تو الله اوراس کے رسول اور مومنین ہی کے لیے ہے لیکن منافق نہیں جانتے'),
  ('ur.ahmedali', 63, 9, 'اے ایمان والو تمہیں تمہارے مال اور تمہاری اولاد الله کے ذکر سے غافل نہ کر دیں اور جو کوئی ایسا کرے گا سووہی نقصان اٹھانے والے ہیں'),
  ('ur.ahmedali', 63, 10, 'اوراس میں سے خرچ کرو جو ہم نے تمہیں روزی دی ہے اس سے پہلے کہ کسی کو تم میں سے موت آجائے تو کہے اے میرے رب تو نے مجھے تھوڑی مدت کے لیے ڈھیل کیوں نہ دی کہ میں خیرات کرتا اور نیک لوگو ں میں ہو جاتا'),
  ('ur.ahmedali', 63, 11, 'اور الله کسی نفس کو ہرگز مہلت نہیں دے گا جب اس کی اجل آجائے گی اور الله اس سے خبردار ہے جو تم کرتے ہو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 63, 1, 'İkiyüzlüler sana gelince: "Senin şüphesiz Allah\'ın Peygamberi olduğuna şehadet ederiz" derler. Allah, senin kendisinin peygamberi olduğunu bilir; bunun yanında Allah, ikiyüzlülerin yalancı olduklarını da bilir.'),
  ('tr.diyanet', 63, 2, 'Onlar, yeminlerini kalkan edinerek Allah\'ın yolundan alıkoyarlar. İşledikleri işler gerçekten ne kötüdür!'),
  ('tr.diyanet', 63, 3, 'Bu, önce inanıp sonra inkar etmiş olmalarındandır. Bu yüzden kalbleri mühürlenmiştir; artık anlamazlar.'),
  ('tr.diyanet', 63, 4, 'Onlara baktığın zaman cüsseleri hoşuna gider; konuşurlarsa sözlerini dinlersin; tıpkı, sıralanmış kof kütük gibidirler; her çığlığı kendi aleyhlerine sayarlar; onlar düşmandır, onlardan çekin; Allah canlarını alsın, nasıl da aldatılıp döndürülüyorlar.'),
  ('tr.diyanet', 63, 5, 'Onlara: "Gelin de Allah\'ın Peygamberi sizin için mağfiret dilesin" dendiği zaman, başlarını çevirirler; büyüklük taslayarak yüz çevirdiklerini görürsün.'),
  ('tr.diyanet', 63, 6, 'Onlar için, bağışlanma dilesen de dilemesen de birdir; Allah onları bağışlamayacaktır. Doğrusu Allah, yoldan çıkmış milleti doğru yola eriştirmez.'),
  ('tr.diyanet', 63, 7, 'Bunlar: "Allah\'ın Peygamberinin yanında bulunanlara bir şey vermeyin de dağılıp gitsinler" diyen kimselerdir. Oysa göklerin ve yerin hazineleri Allah\'ındır, ama ikiyüzlüler bu gerçeği anlamazlar.'),
  ('tr.diyanet', 63, 8, '"Eğer bu savaşdan Medine\'ye dönersek, şerefli kimseler alçakları and olsun ki, oradan çıkaracaktır" diyorlardı. Oysa, şeref Allah\'ın, Peygamberinin ve inananlarındır, ama ikiyüzlüler bu gerçeği bilmezler.'),
  ('tr.diyanet', 63, 9, 'Ey inananlar! Sizi, mallarınız ve çocuklarınız Allah\'ı anmaktan alıkoymasın; böyle olanlar hüsrana uğrayanlardır.'),
  ('tr.diyanet', 63, 10, 'Birine ölüm gelip de: "Rabbim! Beni yakın bir süreye kadar ertelesen de, sadaka versem, iyilerden olsam" diyeceği zaman gelmezden önce, size verdiğimiz rızıklardan sarfedin.'),
  ('tr.diyanet', 63, 11, 'Bir canın eceli gelip çatınca, Allah onu asla geri bırakmaz; Allah, işlediklerinizden haberdardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 63, 1, 'Apabila orang-orang munafik datang kepadamu, mereka berkata: "Kami mengakui, bahwa sesungguhnya kamu benar-benar Rasul Allah". Dan Allah mengetahui bahwa sesungguhnya kamu benar-benar Rasul-Nya; dan Allah mengetahui bahwa sesungguhnya orang-orang munafik itu benar-benar orang pendusta.'),
  ('id.indonesian', 63, 2, 'Mereka itu menjadikan sumpah mereka sebagai perisai, lalu mereka menghalangi (manusia) dari jalan Allah. Sesungguhnya amat buruklah apa yang telah mereka kerjakan.'),
  ('id.indonesian', 63, 3, 'Yang demikian itu adalah karena bahwa sesungguhnya mereka telah beriman, kemudian menjadi kafir (lagi) lalu hati mereka dikunci mati; karena itu mereka tidak dapat mengerti.'),
  ('id.indonesian', 63, 4, 'Dan apabila kamu melihat mereka, tubuh-tubuh mereka menjadikan kamu kagum. Dan jika mereka berkata kamu mendengarkan perkataan mereka. Mereka adalah seakan-akan kayu yang tersandar. Mereka mengira bahwa tiap-tiap teriakan yang keras ditujukan kepada mereka. Mereka itulah musuh (yang sebenarnya) maka waspadalah terhadap mereka; semoga Allah membinasakan mereka. Bagaimanakah mereka sampai dipalingkan (dari kebenaran)?'),
  ('id.indonesian', 63, 5, 'Dan apabila dikatakan kepada mereka: Marilah (beriman), agar Rasulullah memintakan ampunan bagimu, mereka membuang muka mereka dan kamu lihat mereka berpaling sedang mereka menyombongkan diri.'),
  ('id.indonesian', 63, 6, 'Sama saja bagi mereka, kamu mintakan ampunan atau tidak kamu mintakan ampunan bagi mereka. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang fasik.'),
  ('id.indonesian', 63, 7, 'Mereka orang-orang yang mengatakan (kepada orang-orang Anshar): "Janganlah kamu memberikan perbelanjaan kepada orang-orang (Muhajirin) yang ada disisi Rasulullah supaya mereka bubar (meninggalkan Rasulullah)". Padahal kepunyaan Allah-lah perbendaharaan langit dan bumi, tetapi orang-orang munafik itu tidak memahami.'),
  ('id.indonesian', 63, 8, 'Mereka berkata: "Sesungguhnya jika kita telah kembali ke Madinah, benar-benar orang yang kuat akan mengusir orang-orang yang lemah dari padanya". Padahal kekuatan itu hanyalah bagi Allah, bagi Rasul-Nya dan bagi orang-orang mukmin, tetapi orang-orang munafik itu tiada mengetahui.'),
  ('id.indonesian', 63, 9, 'Hai orang-orang beriman, janganlah hartamu dan anak-anakmu melalaikan kamu dari mengingat Allah. Barangsiapa yang berbuat demikian maka mereka itulah orang-orang yang merugi.'),
  ('id.indonesian', 63, 10, 'Dan belanjakanlah sebagian dari apa yang telah Kami berikan kepadamu sebelum datang kematian kepada salah seorang di antara kamu; lalu ia berkata: "Ya Rabb-ku, mengapa Engkau tidak menangguhkan (kematian)ku sampai waktu yang dekat, yang menyebabkan aku dapat bersedekah dan aku termasuk orang-orang yang saleh?"'),
  ('id.indonesian', 63, 11, 'Dan Allah sekali-kali tidak akan menangguhkan (kematian) seseorang apabila telah datang waktu kematiannya. Dan Allah Maha Mengenal apa yang kamu kerjakan.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (56, 22, 5001, 'وَحُورٌ عِينٌۭ', 535, 27, 214, 0),
  (56, 23, 5002, 'كَأَمْثَٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ', 535, 27, 214, 0),
  (56, 24, 5003, 'جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 535, 27, 214, 0),
  (56, 25, 5004, 'لَا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا تَأْثِيمًا', 535, 27, 214, 0),
  (56, 26, 5005, 'إِلَّا قِيلًۭا سَلَٰمًۭا سَلَٰمًۭا', 535, 27, 214, 0),
  (56, 27, 5006, 'وَأَصْحَٰبُ ٱلْيَمِينِ مَآ أَصْحَٰبُ ٱلْيَمِينِ', 535, 27, 214, 0),
  (56, 28, 5007, 'فِى سِدْرٍۢ مَّخْضُودٍۢ', 535, 27, 214, 0),
  (56, 29, 5008, 'وَطَلْحٍۢ مَّنضُودٍۢ', 535, 27, 214, 0),
  (56, 30, 5009, 'وَظِلٍّۢ مَّمْدُودٍۢ', 535, 27, 214, 0),
  (56, 31, 5010, 'وَمَآءٍۢ مَّسْكُوبٍۢ', 535, 27, 214, 0),
  (56, 32, 5011, 'وَفَٰكِهَةٍۢ كَثِيرَةٍۢ', 535, 27, 214, 0),
  (56, 33, 5012, 'لَّا مَقْطُوعَةٍۢ وَلَا مَمْنُوعَةٍۢ', 535, 27, 214, 0),
  (56, 34, 5013, 'وَفُرُشٍۢ مَّرْفُوعَةٍ', 535, 27, 214, 0),
  (56, 35, 5014, 'إِنَّآ أَنشَأْنَٰهُنَّ إِنشَآءًۭ', 535, 27, 214, 0),
  (56, 36, 5015, 'فَجَعَلْنَٰهُنَّ أَبْكَارًا', 535, 27, 214, 0),
  (56, 37, 5016, 'عُرُبًا أَتْرَابًۭا', 535, 27, 214, 0),
  (56, 38, 5017, 'لِّأَصْحَٰبِ ٱلْيَمِينِ', 535, 27, 214, 0),
  (56, 39, 5018, 'ثُلَّةٌۭ مِّنَ ٱلْأَوَّلِينَ', 535, 27, 214, 0),
  (56, 40, 5019, 'وَثُلَّةٌۭ مِّنَ ٱلْءَاخِرِينَ', 535, 27, 214, 0),
  (56, 41, 5020, 'وَأَصْحَٰبُ ٱلشِّمَالِ مَآ أَصْحَٰبُ ٱلشِّمَالِ', 535, 27, 214, 0),
  (56, 42, 5021, 'فِى سَمُومٍۢ وَحَمِيمٍۢ', 535, 27, 214, 0),
  (56, 43, 5022, 'وَظِلٍّۢ مِّن يَحْمُومٍۢ', 535, 27, 214, 0),
  (56, 44, 5023, 'لَّا بَارِدٍۢ وَلَا كَرِيمٍ', 535, 27, 214, 0),
  (56, 45, 5024, 'إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ', 535, 27, 214, 0),
  (56, 46, 5025, 'وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ', 535, 27, 214, 0),
  (56, 47, 5026, 'وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ', 535, 27, 214, 0),
  (56, 48, 5027, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 535, 27, 214, 0),
  (56, 49, 5028, 'قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْءَاخِرِينَ', 535, 27, 214, 0),
  (56, 50, 5029, 'لَمَجْمُوعُونَ إِلَىٰ مِيقَٰتِ يَوْمٍۢ مَّعْلُومٍۢ', 535, 27, 214, 0),
  (56, 51, 5030, 'ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ', 536, 27, 214, 0),
  (56, 52, 5031, 'لَءَاكِلُونَ مِن شَجَرٍۢ مِّن زَقُّومٍۢ', 536, 27, 214, 0),
  (56, 53, 5032, 'فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 536, 27, 214, 0),
  (56, 54, 5033, 'فَشَٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ', 536, 27, 214, 0),
  (56, 55, 5034, 'فَشَٰرِبُونَ شُرْبَ ٱلْهِيمِ', 536, 27, 214, 0),
  (56, 56, 5035, 'هَٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ', 536, 27, 214, 0),
  (56, 57, 5036, 'نَحْنُ خَلَقْنَٰكُمْ فَلَوْلَا تُصَدِّقُونَ', 536, 27, 214, 0),
  (56, 58, 5037, 'أَفَرَءَيْتُم مَّا تُمْنُونَ', 536, 27, 214, 0),
  (56, 59, 5038, 'ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ', 536, 27, 214, 0),
  (56, 60, 5039, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', 536, 27, 214, 0),
  (56, 61, 5040, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ', 536, 27, 214, 0),
  (56, 62, 5041, 'وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ', 536, 27, 214, 0),
  (56, 63, 5042, 'أَفَرَءَيْتُم مَّا تَحْرُثُونَ', 536, 27, 214, 0),
  (56, 64, 5043, 'ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ', 536, 27, 214, 0),
  (56, 65, 5044, 'لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰمًۭا فَظَلْتُمْ تَفَكَّهُونَ', 536, 27, 214, 0),
  (56, 66, 5045, 'إِنَّا لَمُغْرَمُونَ', 536, 27, 214, 0),
  (56, 67, 5046, 'بَلْ نَحْنُ مَحْرُومُونَ', 536, 27, 214, 0),
  (56, 68, 5047, 'أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ', 536, 27, 214, 0),
  (56, 69, 5048, 'ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ', 536, 27, 214, 0),
  (56, 70, 5049, 'لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجًۭا فَلَوْلَا تَشْكُرُونَ', 536, 27, 214, 0),
  (56, 71, 5050, 'أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ', 536, 27, 214, 0),
  (56, 72, 5051, 'ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ', 536, 27, 214, 0),
  (56, 73, 5052, 'نَحْنُ جَعَلْنَٰهَا تَذْكِرَةًۭ وَمَتَٰعًۭا لِّلْمُقْوِينَ', 536, 27, 214, 0),
  (56, 74, 5053, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 536, 27, 214, 0),
  (56, 75, 5054, '۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ', 536, 27, 215, 0),
  (56, 76, 5055, 'وَإِنَّهُۥ لَقَسَمٌۭ لَّوْ تَعْلَمُونَ عَظِيمٌ', 536, 27, 215, 0),
  (56, 77, 5056, 'إِنَّهُۥ لَقُرْءَانٌۭ كَرِيمٌۭ', 537, 27, 215, 0),
  (56, 78, 5057, 'فِى كِتَٰبٍۢ مَّكْنُونٍۢ', 537, 27, 215, 0),
  (56, 79, 5058, 'لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ', 537, 27, 215, 0),
  (56, 80, 5059, 'تَنزِيلٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 537, 27, 215, 0),
  (56, 81, 5060, 'أَفَبِهَٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ', 537, 27, 215, 0),
  (56, 82, 5061, 'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ', 537, 27, 215, 0),
  (56, 83, 5062, 'فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ', 537, 27, 215, 0),
  (56, 84, 5063, 'وَأَنتُمْ حِينَئِذٍۢ تَنظُرُونَ', 537, 27, 215, 0),
  (56, 85, 5064, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ', 537, 27, 215, 0),
  (56, 86, 5065, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', 537, 27, 215, 0),
  (56, 87, 5066, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ', 537, 27, 215, 0),
  (56, 88, 5067, 'فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ', 537, 27, 215, 0),
  (56, 89, 5068, 'فَرَوْحٌۭ وَرَيْحَانٌۭ وَجَنَّتُ نَعِيمٍۢ', 537, 27, 215, 0),
  (56, 90, 5069, 'وَأَمَّآ إِن كَانَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 537, 27, 215, 0),
  (56, 91, 5070, 'فَسَلَٰمٌۭ لَّكَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ', 537, 27, 215, 0),
  (56, 92, 5071, 'وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ', 537, 27, 215, 0),
  (56, 93, 5072, 'فَنُزُلٌۭ مِّنْ حَمِيمٍۢ', 537, 27, 215, 0),
  (56, 94, 5073, 'وَتَصْلِيَةُ جَحِيمٍ', 537, 27, 215, 0),
  (56, 95, 5074, 'إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ', 537, 27, 215, 0),
  (56, 96, 5075, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 537, 27, 215, 0),
  (57, 1, 5076, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 537, 27, 215, 0),
  (57, 2, 5077, 'لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 537, 27, 215, 0),
  (57, 3, 5078, 'هُوَ ٱلْأَوَّلُ وَٱلْءَاخِرُ وَٱلظَّٰهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 537, 27, 215, 0),
  (57, 4, 5079, 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍۢ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 538, 27, 215, 0),
  (57, 5, 5080, 'لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 538, 27, 215, 0),
  (57, 6, 5081, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۚ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 538, 27, 215, 0),
  (57, 7, 5082, 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ ۖ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌۭ كَبِيرٌۭ', 538, 27, 215, 0),
  (57, 8, 5083, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ ۙ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', 538, 27, 215, 0),
  (57, 9, 5084, 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَٰتٍۭ بَيِّنَٰتٍۢ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۚ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌۭ رَّحِيمٌۭ', 538, 27, 215, 0),
  (57, 10, 5085, 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَٰتَلَ ۚ أُو۟لَٰٓئِكَ أَعْظَمُ دَرَجَةًۭ مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَٰتَلُوا۟ ۚ وَكُلًّۭا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 538, 27, 215, 0),
  (57, 11, 5086, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًۭا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌۭ كَرِيمٌۭ', 538, 27, 215, 0),
  (57, 12, 5087, 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 539, 27, 215, 0),
  (57, 13, 5088, 'يَوْمَ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلْمُنَٰفِقَٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًۭا فَضُرِبَ بَيْنَهُم بِسُورٍۢ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', 539, 27, 215, 0),
  (57, 14, 5089, 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ ۖ قَالُوا۟ بَلَىٰ وَلَٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', 539, 27, 215, 0),
  (57, 15, 5090, 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌۭ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ ۚ مَأْوَىٰكُمُ ٱلنَّارُ ۖ هِىَ مَوْلَىٰكُمْ ۖ وَبِئْسَ ٱلْمَصِيرُ', 539, 27, 215, 0),
  (57, 16, 5091, '۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ', 539, 27, 216, 0),
  (57, 17, 5092, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْءَايَٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 539, 27, 216, 0),
  (57, 18, 5093, 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا يُضَٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌۭ كَرِيمٌۭ', 539, 27, 216, 0),
  (57, 19, 5094, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ ۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ ۖ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَحِيمِ', 540, 27, 216, 0),
  (57, 20, 5095, 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌۭ وَلَهْوٌۭ وَزِينَةٌۭ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌۭ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَٰدِ ۖ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّۭا ثُمَّ يَكُونُ حُطَٰمًۭا ۖ وَفِى ٱلْءَاخِرَةِ عَذَابٌۭ شَدِيدٌۭ وَمَغْفِرَةٌۭ مِّنَ ٱللَّهِ وَرِضْوَٰنٌۭ ۚ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَٰعُ ٱلْغُرُورِ', 540, 27, 216, 0),
  (57, 21, 5096, 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍۢ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 540, 27, 216, 0),
  (57, 22, 5097, 'مَآ أَصَابَ مِن مُّصِيبَةٍۢ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَٰبٍۢ مِّن قَبْلِ أَن نَّبْرَأَهَآ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 540, 27, 216, 0),
  (57, 23, 5098, 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍۢ فَخُورٍ', 540, 27, 216, 0),
  (57, 24, 5099, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ ۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 540, 27, 216, 0),
  (57, 25, 5100, 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ ۖ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌۭ شَدِيدٌۭ وَمَنَٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌۭ', 541, 27, 216, 0),
  (57, 26, 5101, 'وَلَقَدْ أَرْسَلْنَا نُوحًۭا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَٰبَ ۖ فَمِنْهُم مُّهْتَدٍۢ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ', 541, 27, 216, 0),
  (57, 27, 5102, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةًۭ وَرَحْمَةًۭ وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا ۖ فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ', 541, 27, 216, 0),
  (57, 28, 5103, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًۭا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 541, 27, 216, 0),
  (57, 29, 5104, 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍۢ مِّن فَضْلِ ٱللَّهِ ۙ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 541, 27, 216, 0),
  (58, 1, 5105, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 542, 28, 217, 0),
  (58, 2, 5106, 'ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمْ ۖ إِنْ أُمَّهَٰتُهُمْ إِلَّا ٱلَّٰٓـِٔى وَلَدْنَهُمْ ۚ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًۭا مِّنَ ٱلْقَوْلِ وَزُورًۭا ۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌۭ', 542, 28, 217, 0),
  (58, 3, 5107, 'وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍۢ مِّن قَبْلِ أَن يَتَمَآسَّا ۚ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 542, 28, 217, 0),
  (58, 4, 5108, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا ۖ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًۭا ۚ ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۗ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ', 542, 28, 217, 0),
  (58, 5, 5109, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَقَدْ أَنزَلْنَآ ءَايَٰتٍۭ بَيِّنَٰتٍۢ ۚ وَلِلْكَٰفِرِينَ عَذَابٌۭ مُّهِينٌۭ', 542, 28, 217, 0),
  (58, 6, 5110, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًۭا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 542, 28, 217, 0),
  (58, 7, 5111, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَٰمَةِ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 543, 28, 217, 0),
  (58, 8, 5112, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ ۚ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا ۖ فَبِئْسَ ٱلْمَصِيرُ', 543, 28, 217, 0),
  (58, 9, 5113, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَٰجَيْتُمْ فَلَا تَتَنَٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 543, 28, 217, 0),
  (58, 10, 5114, 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 543, 28, 217, 0),
  (58, 11, 5115, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَٰتٍۢ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 543, 28, 217, 0),
  (58, 12, 5116, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةًۭ ۚ ذَٰلِكَ خَيْرٌۭ لَّكُمْ وَأَطْهَرُ ۚ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 544, 28, 217, 0),
  (58, 13, 5117, 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَٰتٍۢ ۚ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 544, 28, 217, 0),
  (58, 14, 5118, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', 544, 28, 218, 0),
  (58, 15, 5119, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًۭا شَدِيدًا ۖ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 544, 28, 218, 0),
  (58, 16, 5120, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةًۭ فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌۭ مُّهِينٌۭ', 544, 28, 218, 0),
  (58, 17, 5121, 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَٰلِدُونَ', 544, 28, 218, 0),
  (58, 18, 5122, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًۭا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ ۖ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ ۚ أَلَآ إِنَّهُمْ هُمُ ٱلْكَٰذِبُونَ', 544, 28, 218, 0),
  (58, 19, 5123, 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ ۚ أُو۟لَٰٓئِكَ حِزْبُ ٱلشَّيْطَٰنِ ۚ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَٰنِ هُمُ ٱلْخَٰسِرُونَ', 544, 28, 218, 0),
  (58, 20, 5124, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَٰٓئِكَ فِى ٱلْأَذَلِّينَ', 544, 28, 218, 0),
  (58, 21, 5125, 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌۭ', 544, 28, 218, 0),
  (58, 22, 5126, 'لَّا تَجِدُ قَوْمًۭا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُو۟لَٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَٰنَ وَأَيَّدَهُم بِرُوحٍۢ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا ۚ رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ أُو۟لَٰٓئِكَ حِزْبُ ٱللَّهِ ۚ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', 545, 28, 218, 0),
  (59, 1, 5127, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 545, 28, 218, 0),
  (59, 2, 5128, 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ مِن دِيَٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ ۚ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ ۖ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ ۖ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ ۚ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَٰٓأُو۟لِى ٱلْأَبْصَٰرِ', 545, 28, 218, 0),
  (59, 3, 5129, 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْءَاخِرَةِ عَذَابُ ٱلنَّارِ', 545, 28, 218, 0),
  (59, 4, 5130, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 546, 28, 218, 0),
  (59, 5, 5131, 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ', 546, 28, 218, 0),
  (59, 6, 5132, 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍۢ وَلَا رِكَابٍۢ وَلَٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 546, 28, 218, 0),
  (59, 7, 5133, 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 546, 28, 218, 0),
  (59, 8, 5134, 'لِلْفُقَرَآءِ ٱلْمُهَٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًۭا مِّنَ ٱللَّهِ وَرِضْوَٰنًۭا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلصَّٰدِقُونَ', 546, 28, 218, 0),
  (59, 9, 5135, 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةًۭ مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌۭ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 546, 28, 218, 0),
  (59, 10, 5136, 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّۭا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌۭ رَّحِيمٌ', 547, 28, 218, 0),
  (59, 11, 5137, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًۭا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَٰذِبُونَ', 547, 28, 219, 0),
  (59, 12, 5138, 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَٰرَ ثُمَّ لَا يُنصَرُونَ', 547, 28, 219, 0),
  (59, 13, 5139, 'لَأَنتُمْ أَشَدُّ رَهْبَةًۭ فِى صُدُورِهِم مِّنَ ٱللَّهِ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَفْقَهُونَ', 547, 28, 219, 0),
  (59, 14, 5140, 'لَا يُقَٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًۭى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ ۚ بَأْسُهُم بَيْنَهُمْ شَدِيدٌۭ ۚ تَحْسَبُهُمْ جَمِيعًۭا وَقُلُوبُهُمْ شَتَّىٰ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌۭ لَّا يَعْقِلُونَ', 547, 28, 219, 0),
  (59, 15, 5141, 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًۭا ۖ ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 547, 28, 219, 0),
  (59, 16, 5142, 'كَمَثَلِ ٱلشَّيْطَٰنِ إِذْ قَالَ لِلْإِنسَٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌۭ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَٰلَمِينَ', 547, 28, 219, 0),
  (59, 17, 5143, 'فَكَانَ عَٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَٰلِدَيْنِ فِيهَا ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّٰلِمِينَ', 548, 28, 219, 0),
  (59, 18, 5144, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌۭ مَّا قَدَّمَتْ لِغَدٍۢ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 548, 28, 219, 0),
  (59, 19, 5145, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ ۚ أُو۟لَٰٓئِكَ هُمُ ٱلْفَٰسِقُونَ', 548, 28, 219, 0),
  (59, 20, 5146, 'لَا يَسْتَوِىٓ أَصْحَٰبُ ٱلنَّارِ وَأَصْحَٰبُ ٱلْجَنَّةِ ۚ أَصْحَٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', 548, 28, 219, 0),
  (59, 21, 5147, 'لَوْ أَنزَلْنَا هَٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍۢ لَّرَأَيْتَهُۥ خَٰشِعًۭا مُّتَصَدِّعًۭا مِّنْ خَشْيَةِ ٱللَّهِ ۚ وَتِلْكَ ٱلْأَمْثَٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', 548, 28, 219, 0),
  (59, 22, 5148, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ۖ عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ۖ هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ', 548, 28, 219, 0),
  (59, 23, 5149, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 548, 28, 219, 0),
  (59, 24, 5150, 'هُوَ ٱللَّهُ ٱلْخَٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 548, 28, 219, 0),
  (60, 1, 5151, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَٰدًۭا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى ۚ تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ ۚ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 549, 28, 219, 0),
  (60, 2, 5152, 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءًۭ وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', 549, 28, 219, 0),
  (60, 3, 5153, 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَٰدُكُمْ ۚ يَوْمَ ٱلْقِيَٰمَةِ يَفْصِلُ بَيْنَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 549, 28, 219, 0),
  (60, 4, 5154, 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌۭ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍۢ ۖ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', 549, 28, 219, 0),
  (60, 5, 5155, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةًۭ لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 549, 28, 219, 0),
  (60, 6, 5156, 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌۭ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ ۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 550, 28, 219, 0),
  (60, 7, 5157, '۞ عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةًۭ ۚ وَٱللَّهُ قَدِيرٌۭ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 550, 28, 220, 0),
  (60, 8, 5158, 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 550, 28, 220, 0),
  (60, 9, 5159, 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَٰرِكُمْ وَظَٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ ۚ وَمَن يَتَوَلَّهُمْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ', 550, 28, 220, 0),
  (60, 10, 5160, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَٰتُ مُهَٰجِرَٰتٍۢ فَٱمْتَحِنُوهُنَّ ۖ ٱللَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ ۖ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَٰتٍۢ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ ۖ لَا هُنَّ حِلٌّۭ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ ۖ وَءَاتُوهُم مَّآ أَنفَقُوا۟ ۚ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ ۚ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ۚ ذَٰلِكُمْ حُكْمُ ٱللَّهِ ۖ يَحْكُمُ بَيْنَكُمْ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌۭ', 550, 28, 220, 0),
  (60, 11, 5161, 'وَإِن فَاتَكُمْ شَىْءٌۭ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 550, 28, 220, 0),
  (60, 12, 5162, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًۭٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَٰنٍۢ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍۢ ۙ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 551, 28, 220, 0),
  (60, 13, 5163, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْءَاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَٰبِ ٱلْقُبُورِ', 551, 28, 220, 0),
  (61, 1, 5164, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 551, 28, 220, 0),
  (61, 2, 5165, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 551, 28, 220, 0),
  (61, 3, 5166, 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', 551, 28, 220, 0),
  (61, 4, 5167, 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِى سَبِيلِهِۦ صَفًّۭا كَأَنَّهُم بُنْيَٰنٌۭ مَّرْصُوصٌۭ', 551, 28, 220, 0),
  (61, 5, 5168, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ ۖ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 551, 28, 220, 0),
  (61, 6, 5169, 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًۭا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍۢ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَٰتِ قَالُوا۟ هَٰذَا سِحْرٌۭ مُّبِينٌۭ', 552, 28, 220, 0),
  (61, 7, 5170, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَٰمِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 552, 28, 220, 0),
  (61, 8, 5171, 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ', 552, 28, 220, 0),
  (61, 9, 5172, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 552, 28, 220, 0),
  (61, 10, 5173, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَٰرَةٍۢ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍۢ', 552, 28, 220, 0),
  (61, 11, 5174, 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 552, 28, 220, 0),
  (61, 12, 5175, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَمَسَٰكِنَ طَيِّبَةًۭ فِى جَنَّٰتِ عَدْنٍۢ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 552, 28, 220, 0),
  (61, 13, 5176, 'وَأُخْرَىٰ تُحِبُّونَهَا ۖ نَصْرٌۭ مِّنَ ٱللَّهِ وَفَتْحٌۭ قَرِيبٌۭ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 552, 28, 220, 0),
  (61, 14, 5177, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّۦنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ۖ فَـَٔامَنَت طَّآئِفَةٌۭ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌۭ ۖ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَٰهِرِينَ', 552, 28, 220, 0),
  (62, 1, 5178, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 553, 28, 221, 0),
  (62, 2, 5179, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍۢ', 553, 28, 221, 0),
  (62, 3, 5180, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 553, 28, 221, 0),
  (62, 4, 5181, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 553, 28, 221, 0),
  (62, 5, 5182, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ', 553, 28, 221, 0),
  (62, 6, 5183, 'قُلْ يَٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ', 553, 28, 221, 0),
  (62, 7, 5184, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ', 553, 28, 221, 0),
  (62, 8, 5185, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 553, 28, 221, 0),
  (62, 9, 5186, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 554, 28, 221, 0),
  (62, 10, 5187, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًۭا لَّعَلَّكُمْ تُفْلِحُونَ', 554, 28, 221, 0),
  (62, 11, 5188, 'وَإِذَا رَأَوْا۟ تِجَٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًۭا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌۭ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 554, 28, 221, 0),
  (63, 1, 5189, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا جَآءَكَ ٱلْمُنَٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَٰفِقِينَ لَكَٰذِبُونَ', 554, 28, 221, 0),
  (63, 2, 5190, 'ٱتَّخَذُوٓا۟ أَيْمَٰنَهُمْ جُنَّةًۭ فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 554, 28, 221, 0),
  (63, 3, 5191, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 554, 28, 221, 0),
  (63, 4, 5192, '۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌۭ مُّسَنَّدَةٌۭ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ', 554, 28, 222, 0),
  (63, 5, 5193, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 555, 28, 222, 0),
  (63, 6, 5194, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَٰسِقِينَ', 555, 28, 222, 0),
  (63, 7, 5195, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ ۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَفْقَهُونَ', 555, 28, 222, 0),
  (63, 8, 5196, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ ٱلْمُنَٰفِقِينَ لَا يَعْلَمُونَ', 555, 28, 222, 0),
  (63, 9, 5197, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُمْ عَن ذِكْرِ ٱللَّهِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ', 555, 28, 222, 0),
  (63, 10, 5198, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍۢ قَرِيبٍۢ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ', 555, 28, 222, 0),
  (63, 11, 5199, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 555, 28, 222, 0),
  (64, 1, 5200, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 556, 28, 222, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 64, 1, 'Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent.'),
  ('en.sahih', 64, 2, 'It is He who created you, and among you is the disbeliever, and among you is the believer. And Allah, of what you do, is Seeing.'),
  ('en.sahih', 64, 3, 'He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination.'),
  ('en.sahih', 64, 4, 'He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allah is Knowing of that within the breasts.'),
  ('en.sahih', 64, 5, 'Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment.'),
  ('en.sahih', 64, 6, 'That is because their messengers used to come to them with clear evidences, but they said, "Shall human beings guide us?" and disbelieved and turned away. And Allah dispensed [with them]; and Allah is Free of need and Praiseworthy.'),
  ('en.sahih', 64, 7, 'Those who disbelieve have claimed that they will never be resurrected. Say, "Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allah, is easy."'),
  ('en.sahih', 64, 8, 'So believe in Allah and His Messenger and the Qur\'an which We have sent down. And Allah is Acquainted with what you do.'),
  ('en.sahih', 64, 9, 'The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allah and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment.'),
  ('en.sahih', 64, 10, 'But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination.'),
  ('en.sahih', 64, 11, 'No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things.'),
  ('en.sahih', 64, 12, 'And obey Allah and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification.'),
  ('en.sahih', 64, 13, 'Allah - there is no deity except Him. And upon Allah let the believers rely.'),
  ('en.sahih', 64, 14, 'O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful.'),
  ('en.sahih', 64, 15, 'Your wealth and your children are but a trial, and Allah has with Him a great reward.'),
  ('en.sahih', 64, 16, 'So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful.'),
  ('en.sahih', 64, 17, 'If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing.'),
  ('en.sahih', 64, 18, 'Knower of the unseen and the witnessed, the Exalted in Might, the Wise.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 64, 1, 'নভোমন্ডল ও ভূমন্ডলে যা কিছু আছে, সবই আল্লাহর পবিত্রতা ঘোষণা করে। রাজত্ব তাঁরই এবং প্রশংসা তাঁরই। তিনি সর্ববিষয়ে সর্বশক্তিমান।'),
  ('bn.bengali', 64, 2, 'তিনিই তোমাদেরকে সৃষ্টি করেছেন, অতঃপর তোমাদের মধ্যে কেউ কাফের এবং কেউ মুমিন। তোমরা যা কর, আল্লাহ তা দেখেন।'),
  ('bn.bengali', 64, 3, 'তিনি নভোমন্ডল ও ভূমন্ডলকে যথাযথভাবে সৃষ্টি করেছেন এবং তোমাদেরকে আকৃতি দান করেছেন, অতঃপর সুন্দর করেছেন তোমাদের আকৃতি। তাঁরই কাছে প্রত্যাবর্তন।'),
  ('bn.bengali', 64, 4, 'নভোমন্ডল ও ভূমন্ডলে যা আছে, তিনি তা জানেন। তিনি আরও জানেন তোমরা যা গোপনে কর এবং যা প্রকাশ্যে কর। আল্লাহ অন্তরের বিষয়াদি সম্পর্কে সম্যক জ্ঞাত।'),
  ('bn.bengali', 64, 5, 'তোমাদের পুর্বে যারা কাফের ছিল, তাদের বৃত্তান্ত কি তোমাদের কাছে পৌছেনি? তারা তাদের কর্মের শাস্তি আস্বাদন করেছে, এবং তাদের জন্যে রয়েছে যন্ত্রণাদায়ক শাস্তি।'),
  ('bn.bengali', 64, 6, 'এটা এ কারণে যে, তাদের কাছে তাদের রসূলগণ প্রকাশ্য নিদর্শনাবলীসহ আগমন করলে তারা বলতঃ মানুষই কি আমাদেরকে পথপ্রদর্শন করবে? অতঃপর তারা কাফের হয়ে গেল এবং মুখ ফিরিয়ে নিল। এতে আল্লাহর কিছু আসে যায় না। আল্লাহ অমুখাপেক্ষী প্রশংসিত।'),
  ('bn.bengali', 64, 7, 'কাফেররা দাবী করে যে, তারা কখনও পুনরুত্থিত হবে না। বলুন, অবশ্যই হবে, আমার পালনকর্তার কসম, তোমরা নিশ্চয় পুরুত্থিত হবে। অতঃপর তোমাদেরকে অবহিত করা হবে যা তোমরা করতে। এটা আল্লাহর পক্ষে সহজ।'),
  ('bn.bengali', 64, 8, 'অতএব তোমরা আল্লাহ তাঁর রসূল এবং অবতীর্ন নূরের প্রতি বিশ্বাস স্থাপন কর। তোমরা যা কর, সে বিষয়ে আল্লাহ সম্যক অবগত।'),
  ('bn.bengali', 64, 9, 'সেদিন অর্থাৎ, সমাবেশের দিন আল্লাহ তোমাদেরকে সমবেত করবেন। এ দিন হার-জিতের দিন। যে ব্যক্তি আল্লাহর প্রতি বিশ্বাস স্থাপন করে এবং সৎকর্ম সম্পাদন করে, আল্লাহ তার পাপসমূহ মোচন করবেন এবং তাকে জান্নাতে দাখিল করবেন। যার তলদেশে নির্ঝরিনীসমূহ প্রবাহিত হবে, তারা তথায় চিরকাল বসবাস করবে। এটাই মহাসাফল্য।'),
  ('bn.bengali', 64, 10, 'আর যারা কাফের এবং আমার আয়াতসমূহকে মিথ্যা বলে, তারাই জাহান্নামের অধিবাসী, তারা তথায় অনন্তকাল থাকবে। কতই না মন্দ প্রত্যাবর্তনস্থল এটা।'),
  ('bn.bengali', 64, 11, 'আল্লাহর নির্দেশ ব্যতিরেকে কোন বিপদ আসে না এবং যে আল্লাহর প্রতি বিশ্বাস করে, তিনি তার অন্তরকে সৎপথ প্রদর্শন করেন। আল্লাহ সর্ববিষয়ে সম্যক পরিজ্ঞাত।'),
  ('bn.bengali', 64, 12, 'তোমরা আল্লাহর আনুগত্য কর এবং রসূলুল্লাহর আনুগত্য কর। যদি তোমরা মুখ ফিরিয়ে নাও, তবে আমার রসূলের দায়িত্ব কেবল খোলাখুলি পৌছে দেয়া।'),
  ('bn.bengali', 64, 13, 'আল্লাহ তিনি ব্যতীত কোন মাবুদ নেই। অতএব মুমিনগণ আল্লাহর উপর ভরসা করুক।'),
  ('bn.bengali', 64, 14, 'হে মুমিনগণ, তোমাদের কোন কোন স্ত্রী ও সন্তান-সন্ততি তোমাদের দুশমন। অতএব তাদের ব্যাপারে সতর্ক থাক। যদি মার্জনা কর, উপেক্ষা কর, এবং ক্ষমা কর, তবে আল্লাহ ক্ষমাশীল, করুনাময়।'),
  ('bn.bengali', 64, 15, 'তোমাদের ধন-সম্পদ ও সন্তান-সন্ততি তো কেবল পরীক্ষাস্বরূপ। আর আল্লাহর কাছে রয়েছে মহাপুরস্কার।'),
  ('bn.bengali', 64, 16, 'অতএব তোমরা যথাসাধ্য আল্লাহকে ভয় কর, শুন, আনুগত্য কর এবং ব্যয় কর। এটা তোমাদের জন্যে কল্যাণকর। যারা মনের কার্পন্য থেকে মুক্ত, তারাই সফলকাম।'),
  ('bn.bengali', 64, 17, 'যদি তোমরা আল্লাহকে উত্তম ঋণ দান কর, তিনি তোমাদের জন্যে তা দ্বিগুণ করে দেবেন এবং তোমাদেরকে ক্ষমা করবেন। আল্লাহ গুণগ্রাহী, সহনশীল।'),
  ('bn.bengali', 64, 18, 'তিনি দৃশ্য ও অদৃশ্যের জ্ঞানী, পরাক্রান্ত, প্রজ্ঞাময়।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 64, 1, 'All that is in the heavens and all that is in the earth glorifieth Allah; unto Him belongeth Sovereignty and unto Him belongeth praise, and He is Able to do all things.'),
  ('en.pickthall', 64, 2, 'He it is Who created you, but one of you is a disbeliever and one of you is a believer, and Allah is Seer of what ye do.'),
  ('en.pickthall', 64, 3, 'He created the heavens and the earth with truth, and He shaped you and made good your shapes, and unto Him is the journeying.'),
  ('en.pickthall', 64, 4, 'He knoweth all that is in the heavens and the earth, and He knoweth what ye conceal and what ye publish. And Allah is Aware of what is in the breasts (of men).'),
  ('en.pickthall', 64, 5, 'Hath not the story reached you of those who disbelieved of old and so did taste the ill-effects of their conduct, and theirs will be a painful doom.'),
  ('en.pickthall', 64, 6, 'That was because their messengers (from Allah) kept coming unto them with clear proofs (of Allah\'s Sovereignty), but they said: Shall mere mortals guide us? So they disbelieved and turned away, and Allah was independent (of them). Allah is Absolute, Owner of Praise.'),
  ('en.pickthall', 64, 7, 'Those who disbelieve assert that they will not be raised again. Say (unto them, O Muhammad): Yea, verily, by my Lord! ye will be raised again and then ye will be informed of what ye did; and that is easy for Allah.'),
  ('en.pickthall', 64, 8, 'So believe in Allah and His messenger and the light which We have revealed. And Allah is Informed of what ye do.'),
  ('en.pickthall', 64, 9, 'The day when He shall gather you unto the Day of Assembling, that will be a day of mutual disillusion. And whoso believeth in Allah and doeth right, He will remit from him his evil deeds and will bring him unto Gardens underneath which rivers flow, therein to abide for ever. That is the supreme triumph.'),
  ('en.pickthall', 64, 10, 'But those who disbelieve and deny Our revelations, such are owners of the Fire; they will abide therein - a hapless journey\'s end!'),
  ('en.pickthall', 64, 11, 'No calamity befalleth save by Allah\'s leave. And whosoever believeth in Allah, He guideth his heart. And Allah is Knower of all things.'),
  ('en.pickthall', 64, 12, 'Obey Allah and obey His messenger; but if ye turn away, then the duty of Our messenger is only to convey (the message) plainly.'),
  ('en.pickthall', 64, 13, 'Allah! There is no Allah save Him. In Allah, therefore, let believers put their trust.'),
  ('en.pickthall', 64, 14, 'O ye who believe! Lo! among your wives and your children there are enemies for you, therefor beware of them. And if ye efface and overlook and forgive, then lo! Allah is Forgiving, Merciful.'),
  ('en.pickthall', 64, 15, 'Your wealth and your children are only a temptation, whereas Allah! with Him is an immense reward.'),
  ('en.pickthall', 64, 16, 'So keep your duty to Allah as best ye can, and listen, and obey, and spend; that is better for your souls. And whoso is saved from his own greed, such are the successful.'),
  ('en.pickthall', 64, 17, 'If ye lend unto Allah a goodly loan, He will double it for you and will forgive you, for Allah is Responsive, Clement,'),
  ('en.pickthall', 64, 18, 'Knower of the Invisible and the Visible, the Mighty, the Wise.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 64, 1, 'Whatever is in the heavens and on earth, doth declare the Praises and Glory of Allah: to Him belongs dominion, and to Him belongs praise: and He has power over all things.'),
  ('en.yusufali', 64, 2, 'It is He Who has created you; and of you are some that are Unbelievers, and some that are Believers: and Allah sees well all that ye do.'),
  ('en.yusufali', 64, 3, 'He has created the heavens and the earth in just proportions, and has given you shape, and made your shapes beautiful: and to Him is the final Goal.'),
  ('en.yusufali', 64, 4, 'He knows what is in the heavens and on earth; and He knows what ye conceal and what ye reveal: yea, Allah knows well the (secrets) of (all) hearts.'),
  ('en.yusufali', 64, 5, 'Has not the story reached you, of those who rejected Faith aforetime? So they tasted the evil result of their conduct; and they had a grievous Penalty.'),
  ('en.yusufali', 64, 6, 'That was because there came to them messengers with Clear Signs, but they said: "Shall (mere) human beings direct us?" So they rejected (the Message) and turned away. But Allah can do without (them): and Allah is free of all needs, worthy of all praise.'),
  ('en.yusufali', 64, 7, 'The Unbelievers think that they will not be raised up (for Judgment). Say: "Yea, By my Lord, Ye shall surely be raised up: then shall ye be told (the truth) of all that ye did. And that is easy for Allah."'),
  ('en.yusufali', 64, 8, 'Believe, therefore, in Allah and His Messenger, and in the Light which we have sent down. And Allah is well acquainted with all that ye do.'),
  ('en.yusufali', 64, 9, 'The Day that He assembles you (all) for a Day of Assembly,- that will be a Day of mutual loss and gain (among you), and those who believe in Allah and work righteousness,- He will remove from them their ills, and He will admit them to Gardens beneath which Rivers flow, to dwell therein for ever: that will be the Supreme Achievement.'),
  ('en.yusufali', 64, 10, 'But those who reject Faith and treat Our Signs as falsehoods, they will be Companions of the Fire, to dwell therein for aye: and evil is that Goal.'),
  ('en.yusufali', 64, 11, 'No kind of calamity can occur, except by the leave of Allah: and if any one believes in Allah, (Allah) guides his heart (aright): for Allah knows all things.'),
  ('en.yusufali', 64, 12, 'So obey Allah, and obey His Messenger: but if ye turn back, the duty of Our Messenger is but to proclaim (the Message) clearly and openly.'),
  ('en.yusufali', 64, 13, 'Allah! There is no god but He: and on Allah, therefore, let the Believers put their trust.'),
  ('en.yusufali', 64, 14, 'O ye who believe! Truly, among your wives and your children are (some that are) enemies to yourselves: so beware of them! But if ye forgive and overlook, and cover up (their faults), verily Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 64, 15, 'Your riches and your children may be but a trial: but in the Presence of Allah, is the highest, Reward.'),
  ('en.yusufali', 64, 16, 'So fear Allah as much as ye can; listen and obey and spend in charity for the benefit of your own soul and those saved from the covetousness of their own souls,- they are the ones that achieve prosperity.'),
  ('en.yusufali', 64, 17, 'If ye loan to Allah, a beautiful loan, He will double it to your (credit), and He will grant you Forgiveness: for Allah is most Ready to appreciate (service), Most Forbearing,-'),
  ('en.yusufali', 64, 18, 'Knower of what is open, Exalted in Might, Full of Wisdom.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 64, 1, 'Yusabbihu lillaahi maa fis samaawaati wa maa fil ardi lahul mulku wa lahul hamd, wa Huwa \'alaa kulli shai \'in Qadeer'),
  ('en.transliteration', 64, 2, 'Huwal lazee khalaqakum faminkum kaafirunw wa min kum mu\'min ; wallaahu bimaa ta\'maloona Baseer'),
  ('en.transliteration', 64, 3, 'Khalaqas samaawaati wal arda bilhaqqi wa sawwarakum fa ahsana suwarakum wa ilaihil maseer'),
  ('en.transliteration', 64, 4, 'Ya\'lamu maa fis samaawaati wal ardi wa ya\'lamu maa tusirroona wa maa tu\'linoon; wallaahu \'Aleemum bizaatis sudoor'),
  ('en.transliteration', 64, 5, 'Alam yaatikum naba\'ul lazeena kafaroo min qablu fazaaqoo wabaala amrihim wa lahum \'azaabun aleem'),
  ('en.transliteration', 64, 6, 'Zaalika bi annahoo kaanat taateehim Rusuluhum bilbaiyinaati faqaaloo a basharuny yahdoonanaa fakafaroo wa tawallaw; wastaghnal laah; wallaahu ghaniyyun hameed'),
  ('en.transliteration', 64, 7, 'Za\'amal lazeena kafarooo al-lany yub\'asoo; qul balaa wa rabbee latub\'asunna summa latunabba\'unna bimaa \'amiltum; wa zaalika \'alal laahi yaseer'),
  ('en.transliteration', 64, 8, 'Fa-aaminoo billaahi wa rasoolihee wannooril lazeee anzalnaa; wallaahu bima ta\'maloona khabeer'),
  ('en.transliteration', 64, 9, 'Ywma yajma\'ukum li yawmil jam\'i zaalika yawmut taghaabun; wa many-yumim billaahi wa ya\'mal saalihany yukaffir \'anhu sayyi aatihee wa yudkhilhu jannaatin tajree min tahtihal anhaaru khaalideena feehaaa abadaa; zaalikal fawzul \'azeem'),
  ('en.transliteration', 64, 10, 'Wallazeena kafaroo wa kazzaboo bi aayaaatinaaa ulaaa\'ika ashaabun naari khaalideena feehaa bi\'sal maseer'),
  ('en.transliteration', 64, 11, 'Maaa asaaba mim musee batin illaa bi-iznil laah; wa many yu\'mim billaahi yahdi qalbah; wallaahu bikulli shai;in Aleem'),
  ('en.transliteration', 64, 12, 'Wa atee\'ul laaha wa atee\'ur Rasool; fa in tawallaitum fa innamaa \'alaa Rasoolinal balaaghul mubeen'),
  ('en.transliteration', 64, 13, 'Allaahu laaa ilaaha illaa Hoo; wa \'alal laahi falyata wakkalil mu\'minoon'),
  ('en.transliteration', 64, 14, 'Yaaa ayyuhal lazeena aamanooo inna min azwaaji kum wa awlaadikum \'aduwwal lakum fahzaroohum; wa in ta\'foo wa tasfahoo wa taghfiroo fa innal laaha ghafoorur Raheem'),
  ('en.transliteration', 64, 15, 'Innamaa amwaalukum wa awlaadukum fitnah; wallaahu \'indahooo ajrun \'azeem'),
  ('en.transliteration', 64, 16, 'Fattaqul laaha mastat\'tum wasma\'oo wa atee\'oo waanfiqoo khairal li anfusikum; wa many-yooqa shuha nafsihee fa-ulaaa\'ika humul muflihoon'),
  ('en.transliteration', 64, 17, 'In tuqridul laaha qardan hasanany yudd\'ifhu lakum wa yaghfir lakum; wallaahu Shakoorun Haleem'),
  ('en.transliteration', 64, 18, '\'Aalimul-Ghaibi wash-shahaadatil \'Azeezul Hakeem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 64, 1, 'جو مخلوقات آسمانوں میں اور جو زمین میں ہے الله کی تسبیح کرتی ہے اسی کی حکومت ہے اور اس کی تعریف ہے اوروہ ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 64, 2, 'اسی نے تو تمہیں پیدا کیا ہے پھر کوئی تم میں سے کافر ہے اور کوئی مومن اورجو کچھ تم کر رہے ہو الله دیکھ رہا ہے'),
  ('ur.ahmedali', 64, 3, 'اسی نے آسمانوں اور زمین کو ٹھیک طور پر بنایا ہے اور تمہاری صورت بنائی پھر تمہاری صورتیں اچھی بنائیں اور اسی کی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 64, 4, 'وہ جانتا ہے جو کچھ آسمانوں اور زمین میں ہے اور وہ جانتاہے جو تم چھپاتے ہو اور جو تم ظاہر کرتے ہو اور الله ہی سینوں کے بھید جانتا ہے'),
  ('ur.ahmedali', 64, 5, 'کیا تمہارے ہاں ان کی خبر نہیں پہنچی جو اس ے پہلے منکر ہوئے پس انہوں نے اپنے کام کا وبال چکھا اوران کے لیے دردناک عذاب ہے'),
  ('ur.ahmedali', 64, 6, 'یہ اس لیے کہ ان کے پاس ان کے رسول واضح دلیلیں لے کر آتے تھے تووہ کہا کرتے تھے کہ کیا آدمی ہم کو راہ دکھائیں گے پس انہوں نے انکار کیا اورمنہ موڑ لیا اور الله نے پروا نہ کی اور الله بے نیاز تعریف کیا ہوا ہے'),
  ('ur.ahmedali', 64, 7, 'کافروں نے سمجھ لیا کہ قبروں سے اٹھائے نہ جائیں گے کہہ دوکیوں نہیں مجھے اپنے رب کی قسم ہے ضرور اٹھائے جاؤ گے پھر تمہیں بتلایا جائے گا جو کچھ تم نے کیا تھا اور یہ بات الله پر آسان ہے'),
  ('ur.ahmedali', 64, 8, 'پس الله اوراس کے رسول پر ایمان لاؤ اور اس نور پر جو ہم نے نازل کیا ہے اور الله اس سے جو تم کرتے ہو خبردار ہے'),
  ('ur.ahmedali', 64, 9, 'جس دن تمہیں جمع ہونے کے دن جمع کرے گا وہ دن ہار جیت کا ہے اور جو کوئی الله پر ایمان لائے اور نیک عمل کرے الله اس سے اس کی برائیاں دور کر دے گا اور اسے بہشتوں میں داخل کرے گا جن کے نیچے نہریں بہہ رہی ہوں گی ان میں ہمیشہ رہیں گے یہی بڑی کامیابی ہے'),
  ('ur.ahmedali', 64, 10, 'اورجنہوں نے انکار کیا اور ہماری آیتوں کو جھٹلایا یہی لوگ دوزخی ہیں اس میں ہمیشہ رہیں گے اوروہ بری جگہ ہے'),
  ('ur.ahmedali', 64, 11, 'الله کے حکم کے بغیر کوئی مصیبت بھی نہیں آتی اور جو الله پر ایمان رکھتا ہے وہ اس کے دل کو ہدایت دیتا ہے اور الله ہر چیز جاننے والا ہے'),
  ('ur.ahmedali', 64, 12, 'اور الله اور اس کے رسول کی فرمانبرداری کرو پھر اگر تم نے منہ موڑ لیا تو ہمارے رسول پر بھی صرف کھول کر ہی پہنچا دینا ہے'),
  ('ur.ahmedali', 64, 13, 'الله ہی ہے اس کے سوا کوئی معبود نہیں اور الله ہی پر ایمانداروں کو بھروسہ رکھنا چاہیئے'),
  ('ur.ahmedali', 64, 14, 'اے ایمان والو بے شک تمہاری بیویوں اور اولاد میں سے بعض تمہارے دشمن بھی ہیں سو ان سے بچتے رہو اور اگرتم معاف کرو اور درگزر کرو ارو بخش دو تو الله بھی بخشنے واا نہایت رحم والا ہے'),
  ('ur.ahmedali', 64, 15, 'تمہارے مال اور اولاد تمہارے لیے محض آزمائش ہیں اور الله کے پاس تو بڑا اجر ہے'),
  ('ur.ahmedali', 64, 16, 'پس جہاں تک تم سے ہو سکے الله سے ڈرو اور سنو اور حکم مانو اور اپنے بھلے کے لیے خرچ کرو اورجو شخص اپنے دل کے لالچ سے محفوظ رکھا گیا سووہی فلاح بھی پانے والے ہیں'),
  ('ur.ahmedali', 64, 17, 'اگر تم الله کو نیک قرض دو تو وہ اسے تمہارے لیے دگنا کر دے گا اور تمہیں بخش دے گا اور الله بڑا قدردان حلم والا ہے'),
  ('ur.ahmedali', 64, 18, 'سب چھپی اورکھلی کا جاننے والا غالب حکمت والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 64, 1, 'Göklerde olanlar ve yerde bulunanlar Allah\'ı tesbih ederler. Hükümranlık O\'nundur, Övülmek O\'na mahsustur. O herşeye Kadir\'dir.'),
  ('tr.diyanet', 64, 2, 'Sizi yaratan O\'dur; kiminiz inkarcı kiminiz mümindir. Allah yaptıklarınızı gören\'dir.'),
  ('tr.diyanet', 64, 3, 'Gökleri ve yeri gerektiği gibi yaratmıştır. Size şekil vermiş ve şeklinizi güzel yapmıştır. Dönüş O\'nadır.'),
  ('tr.diyanet', 64, 4, 'Göklerde ve yerde olanları bilir; gizlediklerinizi de açığa vurduklarınızı da bilir; Allah, kalblerde olanı da bilendir.'),
  ('tr.diyanet', 64, 5, 'Daha önce inkar edip de, inkarlarının karşılığını tadan kimselerin haberi size gelmedi mi? Onlara, can yakıcı azap vardır.'),
  ('tr.diyanet', 64, 6, 'Bu, kendilerine peygamberleri belgelerle geldiğinde: "Bizi doğru yola bir insan mı eriştirecek?" diyerek inkar edip gerçeğe yüz çevirmelerinden ötürüdür. Allah hiçbir şeye muhtaç olmadığını ortaya koymuştur. Allah müstağnidir, övülmeğe layık olandır.'),
  ('tr.diyanet', 64, 7, 'İnkar edenler, tekrar dirilmeyeceklerini ileri sürerler. De ki: "Evet; Rabbime and olsun ki, şüphesiz diriltileceksiniz ve sonra, yaptıklarınız size bildirilecektir. Bu, Allah\'a kolaydır."'),
  ('tr.diyanet', 64, 8, 'Öyleyse Allah\'a, Peygamberine ve indirdiğimiz nura, Kuran\'a inanın; Allah işlediklerinizden haberdardır.'),
  ('tr.diyanet', 64, 9, 'Toplanma günü için, sizi bir araya getirdiği zaman, işte o, kimin aldandığının ortaya çıkacağı gündür; Allah\'a kim inanmış ve yararlı iş işlemişse, Allah onun kötülüklerini örter, onu içinde temelli ve sonsuz kalacağı, içlerinden ırmaklar akan cennetlere koyar; büyük kurtuluş işte budur.'),
  ('tr.diyanet', 64, 10, 'İnkar edip, ayetlerimizi yalanlayanlar, işte onlar da ateşliklerdir, orada temellidirler. Ne kötü bir dönüştür!'),
  ('tr.diyanet', 64, 11, 'Başa gelen hiçbir musibet Allah\'ın izni olmaksızın olamaz; Allah\'a kim inanırsa onun gönlünü doğruya yöneltir. Allah herşeyi bilendir.'),
  ('tr.diyanet', 64, 12, 'Allah\'a itaat edin; eğer bundan yüz çevirirseniz bilin ki Peygamberimize düşen apaçık tebliğdir.'),
  ('tr.diyanet', 64, 13, 'Allah vardır, O\'ndan başka tanrı yoktur. İnananlar yalnız Allah \'a güvensinler.'),
  ('tr.diyanet', 64, 14, 'Ey inananlar! Eşleriniz ve çocuklarınızdan size düşmanlık edenler olur, onlardan sakının; ama, siz affeder, suçlarını örter ve bağışlarsanız bilin ki Allah da bağışlar ve acır.'),
  ('tr.diyanet', 64, 15, 'Doğrusu mallarınız ve çocuklarınız bir imtihandır. Büyük ecir ise Allah katındadır.'),
  ('tr.diyanet', 64, 16, 'Allah\'a karşı gelmekten gücünüzün yettiği kadar sakının, buyruklarını dinleyin, itaat edin; kendinizin iyiliğine olarak mallarınızdan sarfedin; nefsinin tamahkarlığından korunan kimseler, işte onlar saadete erenlerdir.'),
  ('tr.diyanet', 64, 17, 'Eğer Allah\'a güzel bir ödünç takdiminde bulunursanız, onu sizin için kat kat yapar ve sizi bağışlar; Allah, şükrün karşılığını verendir; Halim\'dir.'),
  ('tr.diyanet', 64, 18, 'Görüleni görülmeyeni bilendir, güçlüdür. Hakim\'dir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 64, 1, 'Bertasbih kepada Allah apa yang ada di langit dan apa yang ada di bumi; hanya Allah lah yang mempunyai semua kerajaan dan semua pujian, dan Dia Maha Kuasa atas segala sesuatu.'),
  ('id.indonesian', 64, 2, 'Dialah yang menciptakan kamu maka di antara kamu ada yang kafir dan di antaramu ada yang mukmin. Dan Allah Maha Melihat apa yang kamu kerjakan.'),
  ('id.indonesian', 64, 3, 'Dia menciptakan langit dan bumi dengan haq. Dia membentuk rupamu dan dibaguskan-Nya rupamu itu dan hanya kepada Allah-lah kembali(mu).'),
  ('id.indonesian', 64, 4, 'Dia mengetahui apa yang ada di langit dan di bumi dan mengetahui apa yang kamu rahasiakan dan yang kamu nyatakan. Dan Allah Maha Mengetahui segala isi hati.'),
  ('id.indonesian', 64, 5, 'Apakah belum datang kepadamu (hai orang-orang kafir) berita orang-orang kafir terdahulu. Maka mereka telah merasakan akibat yang buruk dari perbuatan mereka dan mereka memperoleh azab yang pedih.'),
  ('id.indonesian', 64, 6, 'Yang demikian itu adalah karena sesungguhnya telah datang kepada mereka Rasul-Rasul mereka membawa keterangan-keterangan lalu mereka berkata: "Apakah manusia yang akan memberi petunjuk kepada kami?" lalu mereka ingkar dan berpaling; dan Allah tidak memerlukan (mereka). Dan Allah Maha Kaya lagi Maha Terpuji.'),
  ('id.indonesian', 64, 7, 'Orang-orang yang kafir mengatakan bahwa mereka sekali-kali tidak akan dibangkitkan. Katakanlah: "Memang, demi Tuhanku, benar-benar kamu akan dibangkitkan, kemudian akan diberitakan kepadamu apa yang telah kamu kerjakan". Yang demikian itu adalah mudah bagi Allah.'),
  ('id.indonesian', 64, 8, 'Maka berimanlah kamu kepada Allah dan Rasul-Nya dan kepada cahaya (Al-Quran) yang telah Kami turunkan. Dan Allah Maha Mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 64, 9, '(Ingatlah) hari (dimana) Allah mengumpulkan kamu pada hari pengumpulan, itulah hari dinampakkan kesalahan-kesalahan. Dan barangsiapa yang beriman kepada Allah dan beramal saleh, niscaya Allah akan menutupi kesalahan-kesalahannya dan memasukkannya ke dalam jannah yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Itulah keberuntungan yang besar.'),
  ('id.indonesian', 64, 10, 'Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni-penghuni neraka, mereka kekal di dalamnya. Dan itulah seburuk-buruk tempat kembali.'),
  ('id.indonesian', 64, 11, 'Tidak ada suatu musibah pun yang menimpa seseorang kecuali dengan ijin Allah; dan barangsiapa yang beriman kepada Allah niscaya Dia akan memberi petunjuk kepada hatinya. Dan Allah Maha Mengetahui segala sesuatu.'),
  ('id.indonesian', 64, 12, 'Dan taatlah kepada Allah dan taatlah kepada Rasul-Nya, jika kamu berpaling sesungguhnya kewajiban Rasul Kami hanyalah menyampaikan (amanat Allah) dengan terang.'),
  ('id.indonesian', 64, 13, '(Dialah) Allah tidak ada Tuhan selain Dia. Dan hendaklah orang-orang mukmin bertawakkal kepada Allah saja.'),
  ('id.indonesian', 64, 14, 'Hai orang-orang mukmin, sesungguhnya di antara isteri-isterimu dan anak-anakmu ada yang menjadi musuh bagimu maka berhati-hatilah kamu terhadap mereka dan jika kamu memaafkan dan tidak memarahi serta mengampuni (mereka) maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.'),
  ('id.indonesian', 64, 15, 'Sesungguhnya hartamu dan anak-anakmu hanyalah cobaan (bagimu), dan di sisi Allah-lah pahala yang besar.'),
  ('id.indonesian', 64, 16, 'Maka bertakwalah kamu kepada Allah menurut kesanggupanmu dan dengarlah serta taatlah dan nafkahkanlah nafkah yang baik untuk dirimu. Dan barangsiapa yang dipelihara dari kekikiran dirinya, maka mereka itulah orang-orang yang beruntung.'),
  ('id.indonesian', 64, 17, 'Jika kamu meminjamkan kepada Allah pinjaman yang baik, niscaya Allah melipat gandakan balasannya kepadamu dan mengampuni kamu. Dan Allah Maha Pembalas Jasa lagi Maha Penyantun.'),
  ('id.indonesian', 64, 18, 'Yang mengetahui yang ghaib dan yang nyata. Yang Maha Perkasa lagi Maha Bijaksana.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 65, 1, 'O Prophet, when you [Muslims] divorce women, divorce them for [the commencement of] their waiting period and keep count of the waiting period, and fear Allah, your Lord. Do not turn them out of their [husbands\'] houses, nor should they [themselves] leave [during that period] unless they are committing a clear immorality. And those are the limits [set by] Allah. And whoever transgresses the limits of Allah has certainly wronged himself. You know not; perhaps Allah will bring about after that a [different] matter.'),
  ('en.sahih', 65, 2, 'And when they have [nearly] fulfilled their term, either retain them according to acceptable terms or part with them according to acceptable terms. And bring to witness two just men from among you and establish the testimony for [the acceptance of] Allah. That is instructed to whoever should believe in Allah and the Last day. And whoever fears Allah - He will make for him a way out'),
  ('en.sahih', 65, 3, 'And will provide for him from where he does not expect. And whoever relies upon Allah - then He is sufficient for him. Indeed, Allah will accomplish His purpose. Allah has already set for everything a [decreed] extent.'),
  ('en.sahih', 65, 4, 'And those who no longer expect menstruation among your women - if you doubt, then their period is three months, and [also for] those who have not menstruated. And for those who are pregnant, their term is until they give birth. And whoever fears Allah - He will make for him of his matter ease.'),
  ('en.sahih', 65, 5, 'That is the command of Allah, which He has sent down to you; and whoever fears Allah - He will remove for him his misdeeds and make great for him his reward.'),
  ('en.sahih', 65, 6, 'Lodge them [in a section] of where you dwell out of your means and do not harm them in order to oppress them. And if they should be pregnant, then spend on them until they give birth. And if they breastfeed for you, then give them their payment and confer among yourselves in the acceptable way; but if you are in discord, then there may breastfeed for the father another woman.'),
  ('en.sahih', 65, 7, 'Let a man of wealth spend from his wealth, and he whose provision is restricted - let him spend from what Allah has given him. Allah does not charge a soul except [according to] what He has given it. Allah will bring about, after hardship, ease.'),
  ('en.sahih', 65, 8, 'And how many a city was insolent toward the command of its Lord and His messengers, so We took it to severe account and punished it with a terrible punishment.'),
  ('en.sahih', 65, 9, 'And it tasted the bad consequence of its affair, and the outcome of its affair was loss.'),
  ('en.sahih', 65, 10, 'Allah has prepared for them a severe punishment; so fear Allah, O you of understanding who have believed. Allah has sent down to you the Qur\'an.'),
  ('en.sahih', 65, 11, '[He sent] a Messenger [Muhammad] reciting to you the distinct verses of Allah that He may bring out those who believe and do righteous deeds from darknesses into the light. And whoever believes in Allah and does righteousness - He will admit him into gardens beneath which rivers flow to abide therein forever. Allah will have perfected for him a provision.'),
  ('en.sahih', 65, 12, 'It is Allah who has created seven heavens and of the earth, the like of them. [His] command descends among them so you may know that Allah is over all things competent and that Allah has encompassed all things in knowledge.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 65, 1, 'হে নবী, তোমরা যখন স্ত্রীদেরকে তালাক দিতে চাও, তখন তাদেরকে তালাক দিয়ো ইদ্দতের প্রতি লক্ষ্য রেখে এবং ইদ্দত গণনা করো। তোমরা তোমাদের পালনকর্তা আল্লাহকে ভয় করো। তাদেরকে তাদের গৃহ থেকে বহিস্কার করো না এবং তারাও যেন বের না হয় যদি না তারা কোন সুস্পষ্ট নির্লজ্জ কাজে লিপ্ত হয়। এগুলো আল্লাহর নির্ধারিত সীমা। যে ব্যক্তি আল্লাহর সীমালংঘন করে, সে নিজেরই অনিষ্ট করে। সে জানে না, হয়তো আল্লাহ এই তালাকের পর কোন নতুন উপায় করে দেবেন।'),
  ('bn.bengali', 65, 2, 'অতঃপর তারা যখন তাদের ইদ্দতকালে পৌঁছে, তখন তাদেরকে যথোপযুক্ত পন্থায় রেখে দেবে অথবা যথোপযুক্ত পন্থায় ছেড়ে দেবে এবং তোমাদের মধ্য থেকে দু’জন নির্ভরযোগ্য লোককে সাক্ষী রাখবে। তোমরা আল্লাহর উদ্দেশ্যে সাক্ষ্য দিবে। এতদ্দ্বারা যে ব্যক্তি আল্লাহ ও পরকালে বিশ্বাস করে, তাকে উপদেশ দেয়া হচ্ছে। আর যে আল্লাহকে ভয় করে, আল্লাহ তার জন্যে নিস্কৃতির পথ করে দেবেন।'),
  ('bn.bengali', 65, 3, 'এবং তাকে তার ধারণাতীত জায়গা থেকে রিযিক দেবেন। যে ব্যক্তি আল্লাহর উপর ভরসা করে তার জন্যে তিনিই যথেষ্ট। আল্লাহ তার কাজ পূর্ণ করবেন। আল্লাহ সবকিছুর জন্যে একটি পরিমাণ স্থির করে রেখেছেন।'),
  ('bn.bengali', 65, 4, 'তোমাদের স্ত্রীদের মধ্যে যাদের ঋতুবর্তী হওয়ার আশা নেই, তাদের ব্যাপারে সন্দেহ হলে তাদের ইদ্দত হবে তিন মাস। আর যারা এখনও ঋতুর বয়সে পৌঁছেনি, তাদেরও অনুরূপ ইদ্দতকাল হবে। গর্ভবর্তী নারীদের ইদ্দতকাল সন্তানপ্রসব পর্যন্ত। যে আল্লাহকে ভয় করে, আল্লাহ তার কাজ সহজ করে দেন।'),
  ('bn.bengali', 65, 5, 'এটা আল্লাহর নির্দেশ, যা তিনি তোমাদের প্রতি নাযিল করেছেন। যে আল্লাহকে ভয় করে, আল্লাহ তার পাপ মোচন করেন এবং তাকে মহাপুরস্কার দেন।'),
  ('bn.bengali', 65, 6, 'তোমরা তোমাদের সামর্থ?2437;নুযায়ী যেরূপ গৃহে বাস কর, তাদেরকেও বসবাসের জন্যে সেরূপ গৃহ দাও। তাদেরকে কষ্ট দিয়ে সংকটাপন্ন করো না। যদি তারা গর্ভবতী হয়, তবে সন্তানপ্রসব পর্যন্ত তাদের ব্যয়ভার বহন করবে। যদি তারা তোমাদের সন্তানদেরকে স্তন্যদান করে, তবে তাদেরকে প্রাপ্য পারিশ্রমিক দেবে এবং এ সম্পর্কে পরস্পর সংযতভাবে পরামর্শ করবে। তোমরা যদি পরস্পর জেদ কর, তবে অন্য নারী স্তন্যদান করবে।'),
  ('bn.bengali', 65, 7, 'বিত্তশালী ব্যক্তি তার বিত্ত অনুযায়ী ব্যয় করবে। যে ব্যক্তি সীমিত পরিমাণে রিযিকপ্রাপ্ত, সে আল্লাহ যা দিয়েছেন, তা থেকে ব্যয় করবে। আল্লাহ যাকে যা দিয়েছেন, তদপেক্ষা বেশী ব্যয় করার আদেশ কাউকে করেন না। আল্লাহ কষ্টের পর সুখ দেবেন।'),
  ('bn.bengali', 65, 8, 'অনেক জনপদ তাদের পালনকর্তা ও তাঁর রসূলগণের আদেশ অমান্য করেছিল, অতঃপর আমি তাদেরকে কঠোর হিসাবে ধৃত করেছিলাম এবং তাদেরকে ভীষণ শাস্তি দিয়েছিলাম।'),
  ('bn.bengali', 65, 9, 'অতঃপর তাদের কর্মের শাস্তি আস্বাদন করল এবং তাদের কর্মের পরিণাম ক্ষতিই ছিল।'),
  ('bn.bengali', 65, 10, 'আল্লাহ তাদের জন্যে যন্ত্রণাদায়ক শাস্তি প্রস্তত রেখেছেন অতএব, হে বুদ্ধিমানগণ, যারা ঈমান এনেছ, তোমরা আল্লাহকে ভয় কর। আল্লাহ তোমাদের প্রতি উপদেশ নাযিল করেছেন।'),
  ('bn.bengali', 65, 11, 'একজন রসূল, যিনি তোমাদের কাছে আল্লাহর সুস্পষ্ট আয়াতসমূহ পাঠ করেন, যাতে বিশ্বাসী ও সৎকর্মপরায়ণদের অন্ধকার থেকে আলোতে আনয়ন করেন। যে আল্লাহর প্রতি বিশ্বাস স্থাপন করে ও সৎকর্ম সম্পাদন করে, তিনি তাকে দাখিল করবেন জান্নাতে, যার তলদেশে নদী প্রবাহিত, তথায় তারা চিরকাল থাকবে। আল্লাহ তাকে উত্তম রিযিক দেবেন।'),
  ('bn.bengali', 65, 12, 'আল্লাহ সপ্তাকাশ সৃষ্টি করেছেন এবং পৃথিবীও সেই পরিমাণে, এসবের মধ্যে তাঁর আদেশ অবতীর্ণ হয়, যাতে তোমরা জানতে পার যে, আল্লাহ সর্বশক্তিমান এবং সবকিছু তাঁর গোচরীভূত।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 65, 1, 'O Prophet! When ye (men) put away women, put them away for their (legal) period and reckon the period, and keep your duty to Allah, your Lord. Expel them not from their houses nor let them go forth unless they commit open immorality. Such are the limits (imposed by) Allah; and whoso transgresseth Allah\'s limits, he verily wrongeth his soul. Thou knowest not: it may be that Allah will afterward bring some new thing to pass.'),
  ('en.pickthall', 65, 2, 'Then, when they have reached their term, take them back in kindness or part from them in kindness, and call to witness two just men among you, and keep your testimony upright for Allah. Whoso believeth in Allah and the Last Day is exhorted to act thus. And whosoever keepeth his duty to Allah, Allah will appoint a way out for him,'),
  ('en.pickthall', 65, 3, 'And will provide for him from (a quarter) whence he hath no expectation. And whosoever putteth his trust in Allah, He will suffice him. Lo! Allah bringeth His command to pass. Allah hath set a measure for all things.'),
  ('en.pickthall', 65, 4, 'And for such of your women as despair of menstruation, if ye doubt, their period (of waiting) shall be three months, along with those who have it not. And for those with child, their period shall be till they bring forth their burden. And whosoever keepeth his duty to Allah, He maketh his course easy for him.'),
  ('en.pickthall', 65, 5, 'That is the commandment of Allah which He revealeth unto you. And whoso keepeth his duty to Allah, He will remit from him his evil deeds and magnify reward for him.'),
  ('en.pickthall', 65, 6, 'Lodge them where ye dwell, according to your wealth, and harass them not so as to straiten life for them. And if they are with child, then spend for them till they bring forth their burden. Then, if they give suck for you, give them their due payment and consult together in kindness; but if ye make difficulties for one another, then let some other woman give suck for him (the father of the child).'),
  ('en.pickthall', 65, 7, 'Let him who hath abundance spend of his abundance, and he whose provision is measured, let him spend of that which Allah hath given him. Allah asketh naught of any soul save that which He hath given it. Allah will vouchsafe, after hardship, ease.'),
  ('en.pickthall', 65, 8, 'And how many a community revolted against the ordinance of its Lord and His messengers, and We called it to a stern account and punished it with dire punishment,'),
  ('en.pickthall', 65, 9, 'So that it tasted the ill-effects of its conduct, and the consequence of its conduct was loss.'),
  ('en.pickthall', 65, 10, 'Allah hath prepared for them stern punishment; so keep your duty to Allah, O men of understanding! O ye who believe! Now Allah hath sent down unto you a reminder,'),
  ('en.pickthall', 65, 11, 'A messenger reciting unto you the revelations of Allah made plain, that He may bring forth those who believe and do good works from darkness unto light. And whosoever believeth in Allah and doeth right, He will bring him into Gardens underneath which rivers flow, therein to abide for ever. Allah hath made good provision for him.'),
  ('en.pickthall', 65, 12, 'Allah it is who hath created seven heavens, and of the earth the like thereof. The commandment cometh down among them slowly, that ye may know that Allah is Able to do all things, and that Allah surroundeth all things in knowledge.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 65, 1, 'O Prophet! When ye do divorce women, divorce them at their prescribed periods, and count (accurately), their prescribed periods: And fear Allah your Lord: and turn them not out of their houses, nor shall they (themselves) leave, except in case they are guilty of some open lewdness, those are limits set by Allah: and any who transgresses the limits of Allah, does verily wrong his (own) soul: thou knowest not if perchance Allah will bring about thereafter some new situation.'),
  ('en.yusufali', 65, 2, 'Thus when they fulfil their term appointed, either take them back on equitable terms or part with them on equitable terms; and take for witness two persons from among you, endued with justice, and establish the evidence (as) before Allah. Such is the admonition given to him who believes in Allah and the Last Day. And for those who fear Allah, He (ever) prepares a way out,'),
  ('en.yusufali', 65, 3, 'And He provides for him from (sources) he never could imagine. And if any one puts his trust in Allah, sufficient is (Allah) for him. For Allah will surely accomplish his purpose: verily, for all things has Allah appointed a due proportion.'),
  ('en.yusufali', 65, 4, 'Such of your women as have passed the age of monthly courses, for them the prescribed period, if ye have any doubts, is three months, and for those who have no courses (it is the same): for those who carry (life within their wombs), their period is until they deliver their burdens: and for those who fear Allah, He will make their path easy.'),
  ('en.yusufali', 65, 5, 'That is the Command of Allah, which He has sent down to you: and if any one fears Allah, He will remove his ills, from him, and will enlarge his reward.'),
  ('en.yusufali', 65, 6, 'Let the women live (in \'iddat) in the same style as ye live, according to your means: Annoy them not, so as to restrict them. And if they carry (life in their wombs), then spend (your substance) on them until they deliver their burden: and if they suckle your (offspring), give them their recompense: and take mutual counsel together, according to what is just and reasonable. And if ye find yourselves in difficulties, let another woman suckle (the child) on the (father\'s) behalf.'),
  ('en.yusufali', 65, 7, 'Let the man of means spend according to his means: and the man whose resources are restricted, let him spend according to what Allah has given him. Allah puts no burden on any person beyond what He has given him. After a difficulty, Allah will soon grant relief.'),
  ('en.yusufali', 65, 8, 'How many populations that insolently opposed the Command of their Lord and of His messengers, did We not then call to account,- to severe account?- and We imposed on them an exemplary Punishment.'),
  ('en.yusufali', 65, 9, 'Then did they taste the evil result of their conduct, and the End of their conduct was Perdition.'),
  ('en.yusufali', 65, 10, 'Allah has prepared for them a severe Punishment (in the Hereafter). Therefore fear Allah, O ye men of understanding - who have believed!- for Allah hath indeed sent down to you a Message,-'),
  ('en.yusufali', 65, 11, 'An Messenger, who rehearses to you the Signs of Allah containing clear explanations, that he may lead forth those who believe and do righteous deeds from the depths of Darkness into Light. And those who believe in Allah and work righteousness, He will admit to Gardens beneath which Rivers flow, to dwell therein for ever: Allah has indeed granted for them a most excellent Provision.'),
  ('en.yusufali', 65, 12, 'Allah is He Who created seven Firmaments and of the earth a similar number. Through the midst of them (all) descends His Command: that ye may know that Allah has power over all things, and that Allah comprehends, all things in (His) Knowledge.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 65, 1, 'Yaaa ayyuhan nabiyyu izaa tallaqtummun nisaaa\'a fatalliqoohunna li\'iddatihinna wa ahsul\'iddata; wattaqul laaha rabbakum laa tukhri joohunna mim bu-yootihinna wa laa yakhrujna illaaa any yaateema bifaahishatim mubaiyinah; wa tilka hudoodul laah; wa many yata\'adda hudoodal laahi faqad zalama nafsha; laa tadree la\'allal laaha yuhdisu ba\'dazaalika amraa'),
  ('en.transliteration', 65, 2, 'Fa izaa balaghna ajalahunna fa amsikoohunna bima\'roofin aw faariqoohunna bima\'roofinw wa ashhidoo zawai \'adlim minkum wa aqeemush shahaadata lillaah; zaalikum yoo\'azu bihee man kaana yu\'minu billaahi wal yawmil aakhir; wa many yattaqil laaha yaj\'al lahoo makhrajaa'),
  ('en.transliteration', 65, 3, 'Wa yarzuqhu min haisu laa yahtasib; wa many yatawakkal \'alal laahi fahuwa husbuh; innal laaha baalighu amrih; qad ja\'alal laahu likulli shai\'in qadraa'),
  ('en.transliteration', 65, 4, 'Wallaaa\'ee ya\'isna minal maheedi min nisaaa \'ikum inir tabtum fa\'iddatuhunna salaasatu ashhurinw wallaaa\'ee lam yahidn; wa ulaatul ahmaali ajaluhunna any yada\'na hamlahun; wa many yattaqil laaha yaj\'al lahoo min armrihee yusraa'),
  ('en.transliteration', 65, 5, 'Zaalika amrul laahi anzalahoo ilaikum; wa many yattaqil laaha yukaffir \'anhu saiyi aatihee wa yu\'zim lahoo ajraa'),
  ('en.transliteration', 65, 6, 'Askinoohunna min haisu sakantum minw wujdikum wa laa tudaaarroohunna litudaiyiqoo \'alaihinn; wa in kunna ulaati hamlin fa anfiqoo \'alihinna hattaa yada\'na hamlahunn; fain arda\'na lakum fa aatoo hunna ujoorahunna waatamiroo bainakum bima\'roofinw wa in ta\'aasartum fasaturdi\'u lahooo ukhraa'),
  ('en.transliteration', 65, 7, 'Liyuntiq zoo sa\'atim min sa\'atihee wa man qudira \'alaihi riquhoo falyunfiq mimmaaa aataahul laah; laa yukalliful laahu nafsan illaa maaa aataahaa; sa yaj\'alul laahu ba\'da\'usriny yusraa'),
  ('en.transliteration', 65, 8, 'Wa ka ayyim min qaryatin \'atat \'an amri Rabbihaa wa Rusulihee fahaasabnaahaa hisaaban shadeedanw wa \'azzabnaahaa \'azaaban nukraa'),
  ('en.transliteration', 65, 9, 'Fazaaqat wabbala amrihaa wa kaana \'aaqibatu amrihaa khusraa'),
  ('en.transliteration', 65, 10, 'A\'addal laahu lahum \'azaaban shadeedan fattaqul laaha yaaa ulil albaab, allazeena aammanoo; qad anzalal laahu ilaikum zikraa'),
  ('en.transliteration', 65, 11, 'Rasoolany yatloo \'alaikum aayaatil laahi mubaiyinaatil liyukhrijal lazeena aamanoo wa \'amilus saalihaati minaz zulumaati ilan noor; wa many yu\'mim billaahi wa ya;mal saalihany yudkhilhu jannaatin tajree min tahtihal anhaaru khaalideena feehaa abadan qad ahsanal laahu lahoo rizqqq'),
  ('en.transliteration', 65, 12, 'Allaahul lazee khalaq Sab\'a Samaawaatinw wa minal ardi mislahunna yatanazzalul amru bainahunna lita\'lamooo annal laaha \'alaa kulli shai\'in Qadeerunw wa annal laaha qad ahaata bikulli shai\'in ilmaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 65, 1, 'اے نبی جب تم عورتوں کو طلاق دو تو ان کی عدت کے موقع پر طلاق دو اور عدت گنتے رہو اور الله سے ڈرتے رہو جو تمہارا رب ہے نہ تم ہی ان کو ان کے گھروں سے نکالو اور نہ وہ خود ہی نکلیں مگر جب کھلم کھلا کوئی بے حیائی کا کام کریں اور یہ الله کی حدیں ہیں اور جو الله کی حدوں سے بڑھاا تو اس نے اپنے نفس پر ظلم کیا آپ کو کیا معلوم کہ شاید الله اس کے بعد اور کوئی نئی بات پیدا کر دے'),
  ('ur.ahmedali', 65, 2, 'پس جب وہ اپنی عدت کو پہنچ جائیں تو انہیں دستور سے رکھ لو یا انہیں دستور سے چھوڑ دو اور دو معتبر آدمی اپنے میں سے گواہ کر لو اور الله کے لیے گواہی پوری دو یہ نصیحت کی باتیں انہیں سمجھائی جاتی ہیں جو الله اور قیامت پر ایمان رکھتے ہیں اور جو الله سے ڈرتا ہے الله اس کے لیے نجات کی صورت نکال دیتا ہے'),
  ('ur.ahmedali', 65, 3, 'اور اسے رزق دیتا ہے جہاں سے اسے گمان بھی نہ ہو اور جو الله پر بھروسہ کرتا ہے سو وہی اس کو کافی ہے بے شک الله اپنا حکم پورا کرنے والا ہے الله نے ہر چیز کے لیے ایک اندازہ مقرر کر دیا ہے'),
  ('ur.ahmedali', 65, 4, 'اور تمہاری عورتوں میں سے جن کو حیض کی امید نہیں رہی ہے اگر تمہیں شبہ ہو تو ان کی عدت تین مہینے ہیں اور ان کی بھی جنہیں ابھی حیض نہیں آیا اور حمل والیوں کی عدت ان کے بچہ جننے تک ہے اور جو الله سے ڈرتا ہے وہ اس کے کام آسان کر دیتا ہے'),
  ('ur.ahmedali', 65, 5, 'یہ الله کا حکم ہے جو اس نے تمہاری طرف نازل کیا ہے اور جو الله سے ڈرتا ہے وہ اس سے اس کی برائیاں دور کر دیتا ہے اور اسے بڑااجر بھی دیتا ہے'),
  ('ur.ahmedali', 65, 6, 'طلاق دی ہوئی عورتوں کو وہیں رکھو جہاں تم اپنے مقدور کے موافق رہتے ہو اورانہیں ایذا نہ دو انہیں تنگ کرنے کے لیے اور اگر وہ حاملہ ہوں تو انہیں نان ونفقہ دو جب تک وہ وضع حمل کریں پس اگر پلائيں دودھ تمہارے لیے تو دو ان کو ان کی اجرت دو اور آپس میں دستور کے مطابق مشورہ کر لو اور اگر تم آپس میں تنگی کرو تو اس کے لیے دوسری عورت دودھ پلائے گی'),
  ('ur.ahmedali', 65, 7, 'مقدور والا اپنے مقدور کے موافق خرچ کرے اور اگر تنگ دست ہو تو جو کچھ الله نے اسے دیا ہے اس میں سے خرچ کرے الله کسی کو تکلیف نہیں دیتا مگر اسی قدر جو اسے دے رکھا ہے عنقریب الله تنگی کے بعد آسانی کر دے گا'),
  ('ur.ahmedali', 65, 8, 'اور کتنی ہی بستیاں اپنے رب اوراس کے رسولوں کے حکم سے سر کش ہوگئیں پھر ہم نے بھی ان سے سخت حساب لیا اور ان کو بری سزا دی'),
  ('ur.ahmedali', 65, 9, 'پس ان بستیوں نے اپنے کام کا وبال چکھا اور ان کا انجام کار بربادی ہوئی'),
  ('ur.ahmedali', 65, 10, 'الله نے ان کے لیے سخت عذاب تیار کر رکھا ہے پھر اے عقل والو الله سے ڈرتے رہو جو ایمان لا چکے ہو بے شک الله نے تمہاری طرف نصیحت نازل کی ہے'),
  ('ur.ahmedali', 65, 11, 'یعنی ایک رسول جو تمہیں الله کی واضح آیتیں پڑھ کر سناتا ہے تاکہ جو ایمان لائے اورانہوں نے نیک کام بھی کیے انہیں اندھیروں سے نکال کر روشنی میں لے جائے اورجو الله پر ایمان لائے اور اس نے نیک کام بھی کیے تو اسے ایسے باغوں میں داخل کرے گا جن کے نیچے نہریں بہتی ہوں گی وہ ان میں سدا رہیں گے الله نے اس کو بہت اچھی روزی دی ہے'),
  ('ur.ahmedali', 65, 12, 'الله ہی ہے جس نے سات آسمان پیدا کیے اور زمینیں بھی اتنی ہی ان میں حکم نازل ہوا کرتا ہے تاکہ تم جان لو کہ الله ہر چیز پر قادر ہے اور الله نے ہر چیز کو علم سے احاطہ کر رکھا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 65, 1, 'Ey Peygamber! Kadınları boşayacağınızda, onları, iddetlerini gözeterek boşayın ve iddeti sayın; Rabbiniz olan Allah\'tan sakının; onları, apaçık bir hayasızlık yapmaları hali bir yana evlerinden çıkarmayın, onlar da çıkmasınlar. Bunlar, Allah\'ın sınırlarıdır. Allah\'ın sınırlarını kim aşarsa, şüphesiz, kendine yazık etmiş olur. Bilmezsin, olur ki, Allah bunun ardından bir hal meydana getirir.'),
  ('tr.diyanet', 65, 2, 'Kadınların iddet süreleri biteceğinde, onları ya uygun bir şekilde alıkoyun, ya da onlardan ayrılın; içinizden de iki adil şahit getirin; şahidliği Allah için yapın; işte bu, Allah\'a ve ahiret gününe inanan kimseye verilen öğüttür. Allah, kendisine karşı gelmekten sakınan kimseye kurtuluş yolu sağlar, ona beklemediği yerden rızık verir. Allah\'a güvenen kimseye O yeter. Allah, buyruğunu yerine getirendir. Allah her şey için bir ölçü var etmiştir.'),
  ('tr.diyanet', 65, 3, 'Kadınların iddet süreleri biteceğinde, onları ya uygun bir şekilde alıkoyun, ya da onlardan ayrılın; içinizden de iki adil şahit getirin; şahidliği Allah için yapın; işte bu, Allah\'a ve ahiret gününe inanan kimseye verilen öğüttür. Allah, kendisine karşı gelmekten sakınan kimseye kurtuluş yolu sağlar, ona beklemediği yerden rızık verir. Allah\'a güvenen kimseye O yeter. Allah, buyruğunu yerine getirendir. Allah her şey için bir ölçü var etmiştir.'),
  ('tr.diyanet', 65, 4, 'Kadınlarınızdan ay hali görmekten kesilenler ile henüz ay hali görmemiş olanların iddetleri hususunda şüpheye düşerseniz, bilin ki, onların iddet beklemesi üç aydır; gebe olanların iddeti, doğurmaları ile tamamlanır. Allah, buyruğuna karşı gelmekten sakınan kimseye işinde kolaylık verir.'),
  ('tr.diyanet', 65, 5, 'Bu, Allah\'ın size indirmiş olduğu buyruğudur. Kim Allah\'ın buyruğuna karşı gelmekten sakınırsa, O, onun kötülüklerini örter, ecrini büyültür.'),
  ('tr.diyanet', 65, 6, 'Boşadığınız, fakat iddeti dolmamış kadınları gücünüz nispetinde, kendi oturduğunuz yerde oturtun. Onları sıkıntıya sokmak için zarar vermeye kalkışmayın. Eğer hamile iseler, doğurmalarına kadar nafakalarını verin. Çocuğu sizin için emzirirlerse, onlara ücretlerini ödeyin; aranızda uygun bir şekilde anlaşın; eğer güçlükle karşılaşırsanız çocuğu başka bir kadın emzirebilir.'),
  ('tr.diyanet', 65, 7, 'Varlıklı olan kimse, nafakayı varlığına göre versin; rızkı ancak kendisine yetecek kadar verilmiş olan kimse, Allah\'ın kendisine verdiğinden versin; Allah kimseye, verdiği rızkı aşan bir yük yüklemez. Allah, güçlükten sonra kolaylık verir.'),
  ('tr.diyanet', 65, 8, 'Rablerinin ve O\'nun peygamberlerinin buyruğundan çıkan nice kasabalar halkını Biz, çetin bir hesaba çekmiş, onları, görülmedik bir azaba uğratmışızdır.'),
  ('tr.diyanet', 65, 9, 'Onlar, işlerinin karşılığını tattılar; işlerinin sonu hüsran oldu.'),
  ('tr.diyanet', 65, 10, 'Allah onlara çetin bir azap hazırlamıştır. Ey inanmış olan akıl sahipleri! Allah\'tan sakının; Allah size Kuran\'ı indirmiştir.'),
  ('tr.diyanet', 65, 11, 'İnanıp yararlı işler işleyenleri karanlıklardan aydınlığa çıkarmak üzere, size Allah\'ın apaçık ayetlerini okuyan bir Peygamber göndermiştir. Kim Allah\'a inanır ve yararlı iş işlerse, Allah onu, içinde temelli ve sonsuz kalınacak, içlerinden ırmaklarakan cennetlere koyar. Allah ona gerçekten güzel rızık vermiştir.'),
  ('tr.diyanet', 65, 12, 'Yedi göğü ve yerden de bir o kadarını yaratan Allah\'tır, Allah\'ın herşeye Kadir olduğunu ve Allah\'ın ilminin herşeyi kuşattığını bilmeniz için Allah\'ın buyruğu bunlar arasında iner durur.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 65, 1, 'Hai Nabi, apabila kamu menceraikan isteri-isterimu maka hendaklah kamu ceraikan mereka pada waktu mereka dapat (menghadapi) iddahnya (yang wajar) dan hitunglah waktu iddah itu serta bertakwalah kepada Allah Tuhanmu. Janganlah kamu keluarkan mereka dari rumah mereka dan janganlah mereka (diizinkan) ke luar kecuali mereka mengerjakan perbuatan keji yang terang. Itulah hukum-hukum Allah dan barangsiapa yang melanggar hukum-hukum Allah, maka sesungguhnya dia telah berbuat zalim terhadap dirinya sendiri. Kamu tidak mengetahui barangkali Allah mengadakan sesudah itu sesuatu hal yang baru.'),
  ('id.indonesian', 65, 2, 'Apabila mereka telah mendekati akhir iddahnya, maka rujukilah mereka dengan baik atau lepaskanlah mereka dengan baik dan persaksikanlah dengan dua orang saksi yang adil di antara kamu dan hendaklah kamu tegakkan kesaksian itu karena Allah. Demikianlah diberi pengajaran dengan itu orang yang beriman kepada Allah dan hari akhirat. Barangsiapa bertakwa kepada Allah niscaya Dia akan mengadakan baginya jalan keluar.'),
  ('id.indonesian', 65, 3, 'Dan memberinya rezeki dari arah yang tiada disangka-sangkanya. Dan barangsiapa yang bertawakkal kepada Allah niscaya Allah akan mencukupkan (keperluan)nya. Sesungguhnya Allah melaksanakan urusan yang (dikehendaki)Nya. Sesungguhnya Allah telah mengadakan ketentuan bagi tiap-tiap sesuatu.'),
  ('id.indonesian', 65, 4, 'Dan perempuan-perempuan yang tidak haid lagi (monopause) di antara perempuan-perempuanmu jika kamu ragu-ragu (tentang masa iddahnya), maka masa iddah mereka adalah tiga bulan; dan begitu (pula) perempuan-perempuan yang tidak haid. Dan perempuan-perempuan yang hamil, waktu iddah mereka itu ialah sampai mereka melahirkan kandungannya. Dan barang -siapa yang bertakwa kepada Allah, niscaya Allah menjadikan baginya kemudahan dalam urusannya.'),
  ('id.indonesian', 65, 5, 'Itulah perintah Allah yang diturunkan-Nya kepada kamu, dan barangsiapa yang bertakwa kepada Allah, niscaya Dia akan menghapus kesalahan-kesalahannya dan akan melipat gandakan pahala baginya.'),
  ('id.indonesian', 65, 6, 'Tempatkanlah mereka (para isteri) di mana kamu bertempat tinggal menurut kemampuanmu dan janganlah kamu menyusahkan mereka untuk menyempitkan (hati) mereka. Dan jika mereka (isteri-isteri yang sudah ditalaq) itu sedang hamil, maka berikanlah kepada mereka nafkahnya hingga mereka bersalin, kemudian jika mereka menyusukan (anak-anak)mu untukmu maka berikanlah kepada mereka upahnya, dan musyawarahkanlah di antara kamu (segala sesuatu) dengan baik; dan jika kamu menemui kesulitan maka perempuan lain boleh menyusukan (anak itu) untuknya.'),
  ('id.indonesian', 65, 7, 'Hendaklah orang yang mampu memberi nafkah menurut kemampuannya. Dan orang yang disempitkan rezekinya hendaklah memberi nafkah dari harta yang diberikan Allah kepadanya. Allah tidak memikulkan beban kepada seseorang melainkan sekedar apa yang Allah berikan kepadanya. Allah kelak akan memberikan kelapangan sesudah kesempitan.'),
  ('id.indonesian', 65, 8, 'Dan berapalah banyaknya (penduduk) negeri yang mendurhakai perintah Tuhan mereka dan Rasul-rasul-Nya, maka Kami hisab penduduk negeri itu dengan hisab yang keras, dan Kami azab mereka dengan azab yang mengerikan.'),
  ('id.indonesian', 65, 9, 'Maka mereka merasakan akibat yang buruk dari perbuatannya, dan adalah akibat perbuatan mereka kerugian yang besar.'),
  ('id.indonesian', 65, 10, 'Allah menyediakan bagi mereka azab yang keras, maka bertakwalah kepada Allah hai orang-orang yang mempunyai akal; (yaitu) orang-orang yang beriman. Sesungguhnya Allah telah menurunkan peringatan kepadamu,'),
  ('id.indonesian', 65, 11, '(Dan mengutus) seorang Rasul yang membacakan kepadamu ayat-ayat Allah yang menerangkan (bermacam-macam hukum) supaya Dia mengeluarkan orang-orang yang beriman dan beramal saleh dari kegelapan kepada cahaya. Dan barangsiapa beriman kepada Allah dan mengerjakan amal yang saleh niscaya Allah akan memasukkannya ke dalam surga-surga yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Sesungguhnya Allah memberikan rezeki yang baik kepadanya.'),
  ('id.indonesian', 65, 12, 'Allah-lah yang menciptakan tujuh langit dan seperti itu pula bumi. Perintah Allah berlaku padanya, agar kamu mengetahui bahwasanya Allah Maha Kuasa atas segala sesuatu, dan sesungguhnya Allah ilmu-Nya benar-benar meliputi segala sesuatu.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 66, 1, 'O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you, seeking the approval of your wives? And Allah is Forgiving and Merciful.'),
  ('en.sahih', 66, 2, 'Allah has already ordained for you [Muslims] the dissolution of your oaths. And Allah is your protector, and He is the Knowing, the Wise.'),
  ('en.sahih', 66, 3, 'And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allah showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, "Who told you this?" He said, "I was informed by the Knowing, the Acquainted."'),
  ('en.sahih', 66, 4, 'If you two [wives] repent to Allah, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allah is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants.'),
  ('en.sahih', 66, 5, 'Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allah], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins.'),
  ('en.sahih', 66, 6, 'O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded.'),
  ('en.sahih', 66, 7, 'O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do.'),
  ('en.sahih', 66, 8, 'O you who have believed, repent to Allah with sincere repentance. Perhaps your Lord will remove from you your misdeeds and admit you into gardens beneath which rivers flow [on] the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right; they will say, "Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent."'),
  ('en.sahih', 66, 9, 'O Prophet, strive against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination.'),
  ('en.sahih', 66, 10, 'Allah presents an example of those who disbelieved: the wife of Noah and the wife of Lot. They were under two of Our righteous servants but betrayed them, so those prophets did not avail them from Allah at all, and it was said, "Enter the Fire with those who enter."'),
  ('en.sahih', 66, 11, 'And Allah presents an example of those who believed: the wife of Pharaoh, when she said, "My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people."'),
  ('en.sahih', 66, 12, 'And [the example of] Mary, the daughter of \'Imran, who guarded her chastity, so We blew into [her garment] through Our angel, and she believed in the words of her Lord and His scriptures and was of the devoutly obedient.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 66, 1, 'হে নবী, আল্লাহ আপনার জন্যে যা হালাল করছেন, আপনি আপনার স্ত্রীদেরকে খুশী করার জন্যে তা নিজের জন্যে হারাম করেছেন কেন? আল্লাহ ক্ষমাশীল, দয়াময়।'),
  ('bn.bengali', 66, 2, 'আল্লাহ তোমাদের জন্যে কসম থেকে অব্যহতি লাভের উপায় নির্ধারণ করে দিয়েছেন। আল্লাহ তোমাদের মালিক। তিনি সর্বজ্ঞ, প্রজ্ঞাময়।'),
  ('bn.bengali', 66, 3, 'যখন নবী তাঁর একজন স্ত্রীর কাছে একটি কথা গোপনে বললেন, অতঃপর স্ত্রী যখন তা বলে দিল এবং আল্লাহ নবীকে তা জানিয়ে দিলেন, তখন নবী সে বিষয়ে স্ত্রীকে কিছু বললেন এবং কিছু বললেন না। নবী যখন তা স্ত্রীকে বললেন, তখন স্ত্রী বললেনঃ কে আপনাকে এ সম্পর্কে অবহিত করল? নবী বললেন,ঃ যিনি সর্বজ্ঞ, ওয়াকিফহাল, তিনি আমাকে অবহিত করেছেন।'),
  ('bn.bengali', 66, 4, 'তোমাদের অন্তর অন্যায়ের দিকে ঝুঁকে পড়েছে বলে যদি তোমরা উভয়ে তওবা কর, তবে ভাল কথা। আর যদি নবীর বিরুদ্ধে একে অপরকে সাহায্য কর, তবে জেনে রেখ আল্লাহ জিবরাঈল এবং সৎকর্মপরায়ণ মুমিনগণ তাঁর সহায়। উপরন্তুত ফেরেশতাগণও তাঁর সাহায্যকারী।'),
  ('bn.bengali', 66, 5, 'যদি নবী তোমাদের সকলকে পরিত্যাগ করেন, তবে সম্ভবতঃ তাঁর পালনকর্তা তাঁকে পরিবর্তে দিবেন তোমাদের চাইতে উত্তম স্ত্রী, যারা হবে আজ্ঞাবহ, ঈমানদার, নামাযী তওবাকারিণী, এবাদতকারিণী, রোযাদার, অকুমারী ও কুমারী।'),
  ('bn.bengali', 66, 6, 'মুমিনগণ, তোমরা নিজেদেরকে এবং তোমাদের পরিবার-পরিজনকে সেই অগ্নি থেকে রক্ষা কর, যার ইন্ধন হবে মানুষ ও প্রস্তর, যাতে নিয়োজিত আছে পাষাণ হৃদয়, কঠোরস্বভাব ফেরেশতাগণ। তারা আল্লাহ তা’আলা যা আদেশ করেন, তা অমান্য করে না এবং যা করতে আদেশ করা হয়, তাই করে।'),
  ('bn.bengali', 66, 7, 'হে কাফের সম্প্রদায়, তোমরা আজ ওযর পেশ করো না। তোমাদেরকে তারই প্রতিফল দেয়া হবে, যা তোমরা করতে।'),
  ('bn.bengali', 66, 8, 'মুমিনগণ! তোমরা আল্লাহ তা’আলার কাছে তওবা কর-আন্তরিক তওবা। আশা করা যায়, তোমাদের পালনকর্তা তোমাদের মন্দ কর্মসমূহ মোচন করে দেবেন এবং তোমাদেরকে দাখিল করবেন জান্নাতে, যার তলদেশে নদী প্রবাহিত। সেদিন আল্লাহ নবী এবং তাঁর বিশ্বাসী সহচরদেরকে অপদস্থ করবেন না। তাদের নূর তাদের সামনে ও ডানদিকে ছুটোছুটি করবে। তারা বলবেঃ হে আমাদের পালনকর্তা, আমাদের নূরকে পূর্ণ করে দিন এবং আমাদেরকে ক্ষমা করুন। নিশ্চয় আপনি সবকিছুর উপর সর্ব শক্তিমান।'),
  ('bn.bengali', 66, 9, 'হে নবী! কাফের ও মুনাফিকদের বিরুদ্ধে জেহাদ করুন এবং তাদের প্রতি কঠোর হোন। তাদের ঠিকানা জাহান্নাম। সেটা কতই না নিকৃষ্ট স্থান।'),
  ('bn.bengali', 66, 10, 'আল্লাহ তা’আলা কাফেরদের জন্যে নূহ-পত্নী ও লূত-পত্নীর দৃষ্টান্ত বর্ণনা করেছেন। তারা ছিল আমার দুই ধর্মপরায়ণ বান্দার গৃহে। অতঃপর তারা তাদের সাথে বিশ্বাসঘাতকতা করল। ফলে নূহ ও লূত তাদেরকে আল্লাহ তা’আলার কবল থেকে রক্ষা করতে পারল না এবং তাদেরকে বলা হলঃ জাহান্নামীদের সাথে জাহান্নামে চলে যাও।'),
  ('bn.bengali', 66, 11, 'আল্লাহ তা’আলা মুমিনদের জন্যে ফেরাউন-পত্নীর দৃষ্টান্ত বর্ণনা করেছেন। সে বললঃ হে আমার পালনকর্তা! আপনার সন্নিকটে জান্নাতে আমার জন্যে একটি গৃহ নির্মাণ করুন, আমাকে ফেরাউন ও তার দুস্কর্ম থেকে উদ্ধার করুন এবং আমাকে যালেম সম্প্রদায় থেকে মুক্তি দিন।'),
  ('bn.bengali', 66, 12, 'আর দৃষ্টান্ত বর্ণনা করেছেন এমরান-তনয়া মরিয়মের, যে তার সতীত্ব বজায় রেখেছিল। অতঃপর আমি তার মধ্যে আমার পক্ষ থেকে জীবন ফুঁকে দিয়েছিলাম এবং সে তার পালনকর্তার বানী ও কিতাবকে সত্যে পরিণত করেছিল। সে ছিল বিনয় প্রকাশকারীনীদের একজন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 66, 1, 'O Prophet! Why bannest thou that which Allah hath made lawful for thee, seeking to please thy wives? And Allah is Forgiving, Merciful.'),
  ('en.pickthall', 66, 2, 'Allah hath made lawful for you (Muslims) absolution from your oaths (of such a kind), and Allah is your Protector. He is the Knower, the Wise.'),
  ('en.pickthall', 66, 3, 'When the Prophet confided a fact unto one of his wives and when she afterward divulged it and Allah apprised him thereof, he made known (to her) part thereof and passed over part. And when he told it her she said: Who hath told thee? He said: The Knower, the Aware hath told me.'),
  ('en.pickthall', 66, 4, 'If ye twain turn unto Allah repentant, (ye have cause to do so) for your hearts desired (the ban); and if ye aid one another against him (Muhammad) then lo! Allah, even He, is his Protecting Friend, and Gabriel and the righteous among the believers; and furthermore the angels are his helpers.'),
  ('en.pickthall', 66, 5, 'It may happen that his Lord, if he divorce you, will give him in your stead wives better than you, submissive (to Allah), believing, pious, penitent, devout, inclined to fasting, widows and maids.'),
  ('en.pickthall', 66, 6, 'O ye who believe! Ward off from yourselves and your families a Fire whereof the fuel is men and stones, over which are set angels strong, severe, who resist not Allah in that which He commandeth them, but do that which they are commanded.'),
  ('en.pickthall', 66, 7, '(Then it will be said): O ye who disbelieve! Make no excuses for yourselves this day. Ye are only being paid for what ye used to do.'),
  ('en.pickthall', 66, 8, 'O ye who believe! Turn unto Allah in sincere repentance! It may be that your Lord will remit from you your evil deeds and bring you into Gardens underneath which rivers flow, on the day when Allah will not abase the Prophet and those who believe with him. Their light will run before them and on their right hands; they will say: Our Lord! Perfect our light for us, and forgive us! Lo! Thou art Able to do all things.'),
  ('en.pickthall', 66, 9, 'O Prophet! Strive against the disbelievers and the hypocrites, and be stern with them. Hell will be their home, a hapless journey\'s end.'),
  ('en.pickthall', 66, 10, 'Allah citeth an example for those who disbelieve: the wife of Noah and the wife of Lot, who were under two of Our righteous slaves yet betrayed them so that they (the husbands) availed them naught against Allah and it was said (unto them): Enter the Fire along with those who enter.'),
  ('en.pickthall', 66, 11, 'And Allah citeth an example for those who believe: the wife of Pharaoh when she said: My Lord! Build for me a home with thee in the Garden, and deliver me from Pharaoh and his work, and deliver me from evil-doing folk;'),
  ('en.pickthall', 66, 12, 'And Mary, daughter of \'Imran, whose body was chaste, therefor We breathed therein something of Our Spirit. And she put faith in the words of her Lord and His scriptures, and was of the obedient.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 66, 1, 'O Prophet! Why holdest thou to be forbidden that which Allah has made lawful to thee? Thou seekest to please thy consorts. But Allah is Oft-Forgiving, Most Merciful.'),
  ('en.yusufali', 66, 2, 'Allah has already ordained for you, (O men), the dissolution of your oaths (in some cases): and Allah is your Protector, and He is Full of Knowledge and Wisdom.'),
  ('en.yusufali', 66, 3, 'When the Prophet disclosed a matter in confidence to one of his consorts, and she then divulged it (to another), and Allah made it known to him, he confirmed part thereof and repudiated a part. Then when he told her thereof, she said, "Who told thee this? "He said, "He told me Who knows and is well-acquainted (with all things)."'),
  ('en.yusufali', 66, 4, 'If ye two turn in repentance to Him, your hearts are indeed so inclined; But if ye back up each other against him, truly Allah is his Protector, and Gabriel, and (every) righteous one among those who believe,- and furthermore, the angels - will back (him) up.'),
  ('en.yusufali', 66, 5, 'It may be, if he divorced you (all), that Allah will give him in exchange consorts better than you,- who submit (their wills), who believe, who are devout, who turn to Allah in repentance, who worship (in humility), who travel (for Faith) and fast,- previously married or virgins.'),
  ('en.yusufali', 66, 6, 'O ye who believe! save yourselves and your families from a Fire whose fuel is Men and Stones, over which are (appointed) angels stern (and) severe, who flinch not (from executing) the Commands they receive from Allah, but do (precisely) what they are commanded.'),
  ('en.yusufali', 66, 7, '(They will say), "O ye Unbelievers! Make no excuses this Day! Ye are being but requited for all that ye did!"'),
  ('en.yusufali', 66, 8, 'O ye who believe! Turn to Allah with sincere repentance: In the hope that your Lord will remove from you your ills and admit you to Gardens beneath which Rivers flow,- the Day that Allah will not permit to be humiliated the Prophet and those who believe with him. Their Light will run forward before them and by their right hands, while they say, "Our Lord! Perfect our Light for us, and grant us Forgiveness: for Thou hast power over all things."'),
  ('en.yusufali', 66, 9, 'O Prophet! Strive hard against the Unbelievers and the Hypocrites, and be firm against them. Their abode is Hell,- an evil refuge (indeed).'),
  ('en.yusufali', 66, 10, 'Allah sets forth, for an example to the Unbelievers, the wife of Noah and the wife of Lut: they were (respectively) under two of our righteous servants, but they were false to their (husbands), and they profited nothing before Allah on their account, but were told: "Enter ye the Fire along with (others) that enter!"'),
  ('en.yusufali', 66, 11, 'And Allah sets forth, as an example to those who believe the wife of Pharaoh: Behold she said: "O my Lord! Build for me, in nearness to Thee, a mansion in the Garden, and save me from Pharaoh and his doings, and save me from those that do wrong";'),
  ('en.yusufali', 66, 12, 'And Mary the daughter of \'Imran, who guarded her chastity; and We breathed into (her body) of Our spirit; and she testified to the truth of the words of her Lord and of His Revelations, and was one of the devout (servants).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 66, 1, 'Yaaa ayyuhan nabiyyu lima tuharrimu maaa ahallal laahu laka tabtaghee mardaata azwaajik; wallaahu ghafoorur raheem'),
  ('en.transliteration', 66, 2, 'Qad faradal laahu lakum tahillata aymaanikum; wallaahu mawlaakum wa huwal\'aleemul hakeem'),
  ('en.transliteration', 66, 3, 'Wa iz asarran nabiyyu ilaa ba\'di azwaajihee hadeesan falammaa nabba at bihee wa azharahul laahu \'alaihi \'arrafa ba\'dahoo wa a\'rada \'am ba\'din falammaa nabba ahaa bihee qaalat man amba aka haaza qaala nabba aniyal \'aleemul khabeer'),
  ('en.transliteration', 66, 4, 'In tatoobaaa ilal laahi faqad saghat quloobukumaa wa in tazaaharaa \'alihi fa innal laaha huwa mawlaahu wa jibreelu wa saalihul mu\'mineen; walma laaa\'ikatu ba\'dazaalika zaheer'),
  ('en.transliteration', 66, 5, '\'Asaa rabbuhooo in tallaqakunna anyyubdilahooo azwaajan khairam mnkunna muslimaatim mu\'minaatin qaanitaatin taaa\'ibaatin \'aabidaatin saaa\'ihaatin saiyibaatinw wa abkaaraa'),
  ('en.transliteration', 66, 6, 'Yaaa ayyuhal lazeena samanoo qooo anfusakum wa ahleekum naaranw waqoodu han naasu wal hijaaratu \'alaihaa malaaa\'ikatun ghilaazun shidaadul laa ya\'soonal laaha maa amarahum wa yaf\'aloona maa yu\'maroon'),
  ('en.transliteration', 66, 7, 'Yaaa ayyuhal lazeena kafaroo la ta\'tazinul yawma innamaa tujzawna maa kuntum ta\'maloon'),
  ('en.transliteration', 66, 8, 'Yaaa ayyuhal lazeena aammano toobooo ilal laahi tawbatan nasoohan \'asaa rabbukum any-yukaffira \'ankum sayyi aatikum wa yudkhilakum jannaatin tajree min tahtihal anhaaru yawma laa yukhzil laahun nabiyya wallazeena aamanoo ma\'ahoo nooruhum yas\'aa baina aydeehim wa bi aymaanihim yaqooloona rabbanaaa atmim lanaa nooranaa waghfir lana innaka \'alaa kulli shai\'in qadeer'),
  ('en.transliteration', 66, 9, 'yaaa ayyuuhan nabiyyu jaahidil kuffaara walmunaa-fiqeena waghluz \'alaihim; wa maawaahum jahannamu wa bi\'sal maseer'),
  ('en.transliteration', 66, 10, 'Darabal laahu masalal lillazeena kafarum ra ata Noobinw wamra ata Loot, kaanataa tahta \'abdaini min \'ibaadinaa saalihaini fakhaanataahumaa falam yughniyaa \'anhumaa minal laahi shai anw-wa qeelad khulan naara ma\'ad Daakhileen'),
  ('en.transliteration', 66, 11, 'Wa darabal laahu masa lal-lillazeena aamanumra ata Fir\'awn; iz qaalat rabbibni lee \'indaka baitan fil jannati wa najjinee min Fir\'awna wa \'amalihii wa najjinee minal qawmiz zaalimeen'),
  ('en.transliteration', 66, 12, 'Wa Maryamab nata \'Imraanal lateee ahsanat farjahaa fanafakhnaa feehi mir roobinaa wa saddaqat bikali maati Rabbihaa wa Kutubihee wakaanat minal qaaniteen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 66, 1, 'اے نبی آپ کیوں حرام کرتے ہیں جو الله نے آپ کے لیے حلال کیا ہے آپ اپنی بیویوں کی خوشنودی چاہتے ہیں اور الله بخشنے والا نہایت رحم والا ہے'),
  ('ur.ahmedali', 66, 2, 'الله نے تمہارے لیے اپنی قسموں کا توڑ دینا فرض کر دیا ہے اور الله ہی تمہارا مالک ہے اوروہی سب کا جاننے والا حکمت والا ہے'),
  ('ur.ahmedali', 66, 3, 'اور جب نبی نے چھپا کر اپنی کسی بیوی سے ایک بات کہہ دی اور پھر جب اس بیوی نے وہ بات بتا دی اور الله نے اس کو نبی پر ظاہر کر دیا تو نبی نے اس میں سے کچھ بات جتلا دی اور کچھ ٹال دی پس جب پیغمبر نے اس کو وہ بات جتلا دی تو بولی آپ کو کس نے یہ بات بتا دی آپ نے فرمایا مجھے خدائے علیم و خبیر نے یہ بات بتلائی'),
  ('ur.ahmedali', 66, 4, 'اگر تم دونوں الله کی جناب میں توبہ کرو تو (بہتر) ورنہ تمہارے دل تو مائل ہو ہی چکے ہیں اوراگر تم آپ کے خلاف ایک دوسرے کی مدد کرو گی تو بے شک اللهآپ کا مددگار ہے اور جبرائیل اور نیک بخت ایمان والے بھی اور سب فرشتے اس کے بعد آپ کے حامی ہیں'),
  ('ur.ahmedali', 66, 5, 'اگر نبی تمیں طلاق دے دے تو بہت جلد اس کا رب اس کے بدلے میں تم سے اچھی بیویاں دے دے گا فرمانبردار ایمان والیاں نمازی توبہ کرنے والی عبادت گزار روزہ دار بیوائیں اور کنواریاں'),
  ('ur.ahmedali', 66, 6, 'اے ایمان والو اپنے آپ کو اور اپنے گھر والوں کو دوزخ سے بچاؤ جس کا ایندھن آدمی اور پتھر ہیں اس پر فرشتے سخت دل قوی ہیکل مقرر ہیں وہ الله کی نافرمانی نہیں کرتے جو وہ انہیں حکم دے اور وہی کرتے ہیں جو انہیں حکم دیا جاتا ہے'),
  ('ur.ahmedali', 66, 7, 'اے کافرو آج بہانے نہ بناؤ تمہیں وہی بدلہ دیا جائے گا جو تم کیا کرتے تھے'),
  ('ur.ahmedali', 66, 8, 'اے ایمان والو الله کے سامنے خالص توبہ کرو کچھ بعید نہیں کہ تمہارا رب تم سے تمہارے گناہ دور کر دے اور تمہیں بہشتوں میں داخل کرے جن کے نیچے نہریں بہتی ہوں گی جس دن الله اپنے نبی کو اور ان کو جو اس کے ساتھ ایمان لائے رسوا نہیں کرے گا ان کا نور ان کے آگے اور ان کے دائیں دوڑ رہا ہوگا وہ کہہ رہے ہوں گے اے ہمارے رب ہمارے لیے ہمارا نور پورا کر اور ہمیں بخش دے بے شک تو ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 66, 9, 'اے نبی کافروں اور منافقوں سے جہاد کر اور ان پر سختی کر اور انکا ٹھکانا دوزخ ہے اور وہ بہت ہی بری جگہ ہے'),
  ('ur.ahmedali', 66, 10, 'الله کافرو ں کے لیے ایک مثال بیان کرتا ہے نوح اور لوط کی بیوی کی وہ ہمارے دو نیک بندوں کے نکاح میں تھیں پھر ان دونوں نے ان کی خیانت کی سو وہ الله کے غضب سے بچانے میں ان کے کچھ بھی کام نہ آئے اور کہا جائے گا دونوں دوزخ میں داخل ہونے والوں کے ساتھ داخل ہو جاؤ'),
  ('ur.ahmedali', 66, 11, 'اور الله ایمان داروں کے لیے فرعون کی بیوی کی مثال بیان کرتا ہے جب اس نے کہاکہ اے میرے رب میرے لیے اپنے پاس جنت میں ایک گھر بنا اور مجھے فرعون اور اس کے کام سے نجات دے اور مجھے ظالموں کی قوم سے نجات دے'),
  ('ur.ahmedali', 66, 12, 'اور مریم عمران کی بیٹی (کی مثال بیان کرتا ہے) جس نے اپنی عصمت کو محفوظ رکھا پھر ہم نے اس میں اپنی طرف سے روح پھونکی اور اس نے اپنے رب کی باتوں کو اور اس کی کتابوں کو سچ جانا اوروہ عبادت کرنے والو ں میں سے تھی')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 66, 1, 'Eşlerinin rızasını gözeterek, Allah\'ın sana helal kıldığı şeyi niçin kendine yasak ediyorsun? Allah bağışlayandır, acıyandır.'),
  ('tr.diyanet', 66, 2, 'Allah şüphesiz size, yeminlerinizi keffaretle geri almanızı meşru kılmıştır. Allah sizin dostunuzdur. O, bilendir, Hakim\'dir.'),
  ('tr.diyanet', 66, 3, 'Peygamber, eşlerinden birine gizlice bir söz söylemişti. O, bunu Peygamberin diğer bir eşine haber verince, Allah da Peygambere durumu bildirmiş, o da bir kısmını yüzüne vurmuş bir kısmını yüzüne vurmaktan geri durmuştu. Eşine, gizlice söylediği şeyibaşkasına nakletmiş olduğunu bildirince, eşi: "Bunu sana kim haber verdi?" demiş, o da: "Bana, herşeyi bilen ve herşeyden haberdar olan Allah haber verdi" demişti.'),
  ('tr.diyanet', 66, 4, 'Ey Peygamber\'in eşleri! Eğer ikiniz de Allah\'a tevbe ederseniz, kaymış olan kalpleriniz düzelmiş olur. Eğer eşinizin aleyhinde yardımlaşarak bir şey yapmağa kalkarsanız, bilin ki Allah onun dostu, bundan başka Cebrail, iyi müminler ve melekler de yardımcısıdır.'),
  ('tr.diyanet', 66, 5, 'Ey Peygamber\'in eşleri! Eğer o sizi boşarsa, Rabbi ona; sizden daha iyi olan, kendini Allah\'a veren, inanan, boyun eğen, tevbe eden, kulluk eden, oruç tutan, dul ve bakire eşler verebilir.'),
  ('tr.diyanet', 66, 6, 'Ey inananlar! Kendinizi ve çoluk çocuğunuzu cehennem ateşinden koruyun; onun yakıtı, insanlar ve taşlardır; görevlileri, Allah\'ın kendilerine verdiği emirlere baş kaldırmayan, kendilerine buyrulanları yerine getiren pek haşin meleklerdir.'),
  ('tr.diyanet', 66, 7, '"Ey inkar edenler! Bugün özür beyan etmeyin, ancak işlediklerinizin karşılığını görmektesiniz" denir.'),
  ('tr.diyanet', 66, 8, 'Ey inananlar! Yürekten tevbe ederek Allah\'a dönün ki, Rabbiniz kötülüklerinizi örtsün, sizi, içlerinden ırmaklar akan cennetlere koysun. Allah\'ın Peygamberini ve onunla beraber olan müminleri utandırmayacağı o gün, ışıkları önlerinde ve defterleri sağlarından verilmiş olarak yürürler ve: "Rabbimiz! Işığımızı tamamla, bizi bağışla, doğrusu Sen herşeye Kadir\'sin" derler.'),
  ('tr.diyanet', 66, 9, 'Ey Peygamber! İnkarcılarla ve ikiyüzlülerle savaş; onlara karşı sert davran. Onların varacakları yer cehennemdir, ne kötü dönüştür!...'),
  ('tr.diyanet', 66, 10, 'Allah, inkar edenlere, Nuh\'un karısıyla Lut\'un karısını misal gösterir: Onlar, kullarımızdan iki iyi kulun nikahı altında iken onlara karşı hainlik edip inkarlarını gizlemişlerdi de iki peygamber Allah\'tan gelen azabı onlardan savamamışlardı. O iki kadına: "Cehenneme girenlerle beraber siz de girin" dendi.'),
  ('tr.diyanet', 66, 11, 'Allah, inanlara Firavun\'un karısını misal gösterir: O: "Rabbim! Katından bana cennette bir ev yap; beni Firavun\'dan ve onun işlediklerinden kurtar; beni zalim milletten kurtar" demişti.'),
  ('tr.diyanet', 66, 12, 'Mahrem yerini korumuş olan İmran kızı Meryem de bir misaldir. Ona ruhumuzdan üflemiştik; Rabbinin sözlerini ve kitablarını tasdik etmişti; o, Bize gönülden itaat edenlerdendi.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 66, 1, 'Hai Nabi, mengapa kamu mengharamkan apa yang Allah halalkan bagimu; kamu mencari kesenangan hati isteri-isterimu? Dan Allah Maha Pengampun lagi Maha Penyayang'),
  ('id.indonesian', 66, 2, 'Sesungguhnya Allah telah mewajibkan kepadamu sekalian membebaskan diri dari sumpahmu dan Allah adalah Pelindungmu dan Dia Maha Mengetahui lagi Maha Bijaksana.'),
  ('id.indonesian', 66, 3, 'Dan ingatlah ketika Nabi membicarakan secara rahasia kepada salah seorang isterinya (Hafsah) suatu peristiwa. Maka tatkala (Hafsah) menceritakan peristiwa itu (kepada Aisyah) dan Allah memberitahukan hal itu (pembicaraan Hafsah dan Aisyah) kepada Muhammad lalu Muhammad memberitahukan sebagian (yang diberitakan Allah kepadanya) dan menyembunyikan sebagian yang lain (kepada Hafsah). Maka tatkala (Muhammad) memberitahukan pembicaraan (antara Hafsah dan Aisyah) lalu (Hafsah) bertanya: "Siapakah yang telah memberitahukan hal ini kepadamu?" Nabi menjawab: "Telah diberitahukan kepadaku oleh Allah yang Maha Mengetahui lagi Maha Mengenal".'),
  ('id.indonesian', 66, 4, 'Jika kamu berdua bertaubat kepada Allah, maka sesungguhnya hati kamu berdua telah condong (untuk menerima kebaikan); dan jika kamu berdua bantu-membantu menyusahkan Nabi, maka sesungguhnya Allah adalah Pelindungnya dan (begitu pula) Jibril dan orang-orang mukmin yang baik; dan selain dari itu malaikat-malaikat adalah penolongnya pula.'),
  ('id.indonesian', 66, 5, 'Jika Nabi menceraikan kamu, boleh jadi Tuhannya akan memberi ganti kepadanya dengan isteri yang lebih baik daripada kamu, yang patuh, yang beriman, yang taat, yang bertaubat, yang mengerjakan ibadat, yang berpuasa, yang janda dan yang perawan.'),
  ('id.indonesian', 66, 6, 'Hai orang-orang yang beriman, peliharalah dirimu dan keluargamu dari api neraka yang bahan bakarnya adalah manusia dan batu; penjaganya malaikat-malaikat yang kasar, keras, dan tidak mendurhakai Allah terhadap apa yang diperintahkan-Nya kepada mereka dan selalu mengerjakan apa yang diperintahkan.'),
  ('id.indonesian', 66, 7, 'Hai orang-orang kafir, janganlah kamu mengemukakan uzur pada hari ini. Sesungguhnya kamu hanya diberi balasan menurut apa yang kamu kerjakan.'),
  ('id.indonesian', 66, 8, 'Hai orang-orang yang beriman, bertaubatlah kepada Allah dengan taubatan nasuhaa (taubat yang semurni-murninya). Mudah-mudahan Rabbmu akan menutupi kesalahan-kesalahanmu dan memasukkanmu ke dalam jannah yang mengalir di bawahnya sungai-sungai, pada hari ketika Allah tidak menghinakan Nabi dan orang-orang mukmin yang bersama dia; sedang cahaya mereka memancar di hadapan dan di sebelah kanan mereka, sambil mereka mengatakan: "Ya Rabb kami, sempurnakanlah bagi kami cahaya kami dan ampunilah kami; Sesungguhnya Engkau Maha Kuasa atas segala sesuatu".'),
  ('id.indonesian', 66, 9, 'Hai Nabi, perangilah orang-orang kafir dan orang-orang munafik dan bersikap keraslah terhadap mereka. Tempat mereka adalah jahannam dan itu adalah seburuk-buruknya tempat kembali.'),
  ('id.indonesian', 66, 10, 'Allah membuat isteri Nuh dan isteri Luth sebagai perumpamaan bagi orang-orang kafir. Keduanya berada di bawah pengawasan dua orang hamba yang saleh di antara hamba-hamba Kami; lalu kedua isteri itu berkhianat kepada suaminya (masing-masing), maka suaminya itu tiada dapat membantu mereka sedikitpun dari (siksa) Allah; dan dikatakan (kepada keduanya): "Masuklah ke dalam jahannam bersama orang-orang yang masuk (jahannam)".'),
  ('id.indonesian', 66, 11, 'Dan Allah membuat isteri Fir\'aun perumpamaan bagi orang-orang yang beriman, ketika ia berkata: "Ya Rabbku, bangunkanlah untukku sebuah rumah di sisi-Mu dalam firdaus, dan selamatkanlah aku dari Fir\'aun dan perbuatannya, dan selamatkanlah aku dari kaum yang zhalim.'),
  ('id.indonesian', 66, 12, 'dan (ingatlah) Maryam binti Imran yang memelihara kehormatannya, maka Kami tiupkan ke dalam rahimnya sebagian dari ruh (ciptaan) Kami, dan dia membenarkan kalimat Rabbnya dan Kitab-Kitab-Nya, dan dia adalah termasuk orang-orang yang taat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 67, 1, 'Blessed is He in whose hand is dominion, and He is over all things competent -'),
  ('en.sahih', 67, 2, '[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving -'),
  ('en.sahih', 67, 3, '[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?'),
  ('en.sahih', 67, 4, 'Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued.'),
  ('en.sahih', 67, 5, 'And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze.'),
  ('en.sahih', 67, 6, 'And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination.'),
  ('en.sahih', 67, 7, 'When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up.'),
  ('en.sahih', 67, 8, 'It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, "Did there not come to you a warner?"'),
  ('en.sahih', 67, 9, 'They will say," Yes, a warner had come to us, but we denied and said, \'Allah has not sent down anything. You are not but in great error.\'"'),
  ('en.sahih', 67, 10, 'And they will say, "If only we had been listening or reasoning, we would not be among the companions of the Blaze."'),
  ('en.sahih', 67, 11, 'And they will admit their sin, so [it is] alienation for the companions of the Blaze.'),
  ('en.sahih', 67, 12, 'Indeed, those who fear their Lord unseen will have forgiveness and great reward.'),
  ('en.sahih', 67, 13, 'And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.'),
  ('en.sahih', 67, 14, 'Does He who created not know, while He is the Subtle, the Acquainted?'),
  ('en.sahih', 67, 15, 'It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.'),
  ('en.sahih', 67, 16, 'Do you feel secure that He who [holds authority] in the heaven would not cause the earth to swallow you and suddenly it would sway?'),
  ('en.sahih', 67, 17, 'Or do you feel secure that He who [holds authority] in the heaven would not send against you a storm of stones? Then you would know how [severe] was My warning.'),
  ('en.sahih', 67, 18, 'And already had those before them denied, and how [terrible] was My reproach.'),
  ('en.sahih', 67, 19, 'Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing.'),
  ('en.sahih', 67, 20, 'Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.'),
  ('en.sahih', 67, 21, 'Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion.'),
  ('en.sahih', 67, 22, 'Then is one who walks fallen on his face better guided or one who walks erect on a straight path?'),
  ('en.sahih', 67, 23, 'Say, "It is He who has produced you and made for you hearing and vision and hearts; little are you grateful."'),
  ('en.sahih', 67, 24, 'Say, "It is He who has multiplied you throughout the earth, and to Him you will be gathered."'),
  ('en.sahih', 67, 25, 'And they say, "When is this promise, if you should be truthful?"'),
  ('en.sahih', 67, 26, 'Say, "The knowledge is only with Allah, and I am only a clear warner."'),
  ('en.sahih', 67, 27, 'But when they see it approaching, the faces of those who disbelieve will be distressed, and it will be said, "This is that for which you used to call."'),
  ('en.sahih', 67, 28, 'Say, [O Muhammad], "Have you considered: whether Allah should cause my death and those with me or have mercy upon us, who can protect the disbelievers from a painful punishment?"'),
  ('en.sahih', 67, 29, 'Say, "He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will [come to] know who it is that is in clear error."'),
  ('en.sahih', 67, 30, 'Say, "Have you considered: if your water was to become sunken [into the earth], then who could bring you flowing water?"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 67, 1, 'পূণ্যময় তিনি, যাঁর হাতে রাজত্ব। তিনি সবকিছুর উপর সর্বশক্তিমান।'),
  ('bn.bengali', 67, 2, 'যিনি সৃষ্টি করেছেন মরণ ও জীবন, যাতে তোমাদেরকে পরীক্ষা করেন-কে তোমাদের মধ্যে কর্মে শ্রেষ্ঠ? তিনি পরাক্রমশালী, ক্ষমাময়।'),
  ('bn.bengali', 67, 3, 'তিনি সপ্ত আকাশ স্তরে স্তরে সৃষ্টি করেছেন। তুমি করুণাময় আল্লাহ তা’আলার সৃষ্টিতে কোন তফাত দেখতে পাবে না। আবার দৃষ্টিফেরাও; কোন ফাটল দেখতে পাও কি?'),
  ('bn.bengali', 67, 4, 'অতঃপর তুমি বার বার তাকিয়ে দেখ-তোমার দৃষ্টি ব্যর্থ ও পরিশ্রান্ত হয়ে তোমার দিকে ফিরে আসবে।'),
  ('bn.bengali', 67, 5, 'আমি সর্বনিম্ন আকাশকে প্রদীপমালা দ্বারা সুসজ্জত করেছি; সেগুলোকে শয়তানদের জন্যে ক্ষেপণাস্ত্রবৎ করেছি এবং প্রস্তুত করে রেখেছি তাদের জন্যে জলন্ত অগ্নির শাস্তি।'),
  ('bn.bengali', 67, 6, 'যারা তাদের পালনকর্তাকে অস্বীকার করেছে তাদের জন্যে রয়েছে জাহান্নামের শাস্তি। সেটা কতই না নিকৃষ্ট স্থান।'),
  ('bn.bengali', 67, 7, 'যখন তারা তথায় নিক্ষিপ্ত হবে, তখন তার উৎক্ষিপ্ত গর্জন শুনতে পাবে।'),
  ('bn.bengali', 67, 8, 'ক্রোধে জাহান্নাম যেন ফেটে পড়বে। যখনই তাতে কোন সম্প্রদায় নিক্ষিপ্ত হবে তখন তাদেরকে তার সিপাহীরা জিজ্ঞাসা করবে। তোমাদের কাছে কি কোন সতর্ককারী আগমন করেনি?'),
  ('bn.bengali', 67, 9, 'তারা বলবেঃ হ্যাঁ আমাদের কাছে সতর্ককারী আগমন করেছিল, অতঃপর আমরা মিথ্যারোপ করেছিলাম এবং বলেছিলামঃ আল্লাহ তা’আলা কোন কিছু নাজিল করেননি। তোমরা মহাবিভ্রান্তিতে পড়ে রয়েছ।'),
  ('bn.bengali', 67, 10, 'তারা আরও বলবেঃ যদি আমরা শুনতাম অথবা বুদ্ধি খাটাতাম, তবে আমরা জাহান্নামবাসীদের মধ্যে থাকতাম না।'),
  ('bn.bengali', 67, 11, 'অতঃপর তারা তাদের অপরাধ স্বীকার করবে। জাহান্নামীরা দূর হোক।'),
  ('bn.bengali', 67, 12, 'নিশ্চয় যারা তাদের পালনকর্তাকে না দেখে ভয় করে, তাদের জন্যে রয়েছে ক্ষমা ও মহাপুরস্কার।'),
  ('bn.bengali', 67, 13, 'তোমরা তোমাদের কথা গোপনে বল অথবা প্রকাশ্যে বল, তিনি তো অন্তরের বিষয়াদি সম্পর্কে সম্যক অবগত।'),
  ('bn.bengali', 67, 14, 'যিনি সৃষ্টি করেছেন, তিনি কি করে জানবেন না? তিনি সূক্ষ্নজ্ঞানী, সম্যক জ্ঞাত।'),
  ('bn.bengali', 67, 15, 'তিনি তোমাদের জন্যে পৃথিবীকে সুগম করেছেন, অতএব, তোমরা তার কাঁধে বিচরণ কর এবং তাঁর দেয়া রিযিক আহার কর। তাঁরই কাছে পুনরুজ্জীবন হবে।'),
  ('bn.bengali', 67, 16, 'তোমরা কি ভাবনামুক্ত হয়ে গেছ যে, আকাশে যিনি আছেন তিনি তোমাদেরকে ভূগর্ভে বিলীন করে দেবেন, অতঃপর তা কাঁপতে থাকবে।'),
  ('bn.bengali', 67, 17, 'না তোমরা নিশ্চিন্ত হয়ে গেছ যে, আকাশে যিনি আছেন, তিনি তোমাদের উপর প্রস্তর বৃষ্টি বর্ষণ করবেন, অতঃপর তোমরা জানতে পারবে কেমন ছিল আমার সতর্কবাণী।'),
  ('bn.bengali', 67, 18, 'তাদের পূর্ববর্তীরা মিথ্যারোপ করেছিল, অতঃপর কত কঠোর হয়েছিল আমার অস্বীকৃতি।'),
  ('bn.bengali', 67, 19, 'তারা কি লক্ষ্য করে না, তাদের মাথার উপর উড়ন্ত পক্ষীকুলের প্রতি পাখা বিস্তারকারী ও পাখা সংকোচনকারী? রহমান আল্লাহ-ই তাদেরকে স্থির রাখেন। তিনি সর্ব-বিষয় দেখেন।'),
  ('bn.bengali', 67, 20, 'রহমান আল্লাহ তা’আলা ব্যতীত তোমাদের কোন সৈন্য আছে কি, যে তোমাদেরকে সাহায্য করবে? কাফেররা বিভ্রান্তিতেই পতিত আছে।'),
  ('bn.bengali', 67, 21, 'তিনি যদি রিযিক বন্ধ করে দেন, তবে কে আছে, যে তোমাদেরকে রিযিক দিবে বরং তারা অবাধ্যতা ও বিমুখতায় ডুবে রয়েছে।'),
  ('bn.bengali', 67, 22, 'যে ব্যক্তি উপুড় হয়ে মুখে ভর দিয়ে চলে, সে-ই কি সৎ পথে চলে, না সে ব্যক্তি যে সোজা হয়ে সরলপথে চলে?'),
  ('bn.bengali', 67, 23, 'বলুন, তিনিই তোমাদেরকে সৃষ্টি করেছেন এবং দিয়েছেন কর্ণ, চক্ষু ও অন্তর। তোমরা অল্পই কৃতজ্ঞতা প্রকাশ কর।'),
  ('bn.bengali', 67, 24, 'বলুন, তিনিই তোমাদেরকে পৃথিবীতে বিস্তৃত করেছেন এবং তাঁরই কাছে তোমরা সমবেত হবে।'),
  ('bn.bengali', 67, 25, 'কাফেররা বলেঃ এই প্রতিশ্রুতি কবে হবে, যদি তোমরা সত্যবাদী হও?'),
  ('bn.bengali', 67, 26, 'বলুন, এর জ্ঞান আল্লাহ তা’আলার কাছেই আছে। আমি তো কেবল প্রকাশ্য সতর্ককারী।'),
  ('bn.bengali', 67, 27, 'যখন তারা সেই প্রতিশ্রুতিকে আসন্ন দেখবে তখন কাফেরদের মুখমন্ডল মলিন হয়ে পড়বে এবং বলা হবেঃ এটাই তো তোমরা চাইতে।'),
  ('bn.bengali', 67, 28, 'বলুন, তোমরা কি ভেবে দেখেছ-যদি আল্লাহ তা’আলা আমাকে ও আমার সংগীদেরকে ধ্বংস করেন অথবা আমাদের প্রতি দয়া করেন, তবে কাফেরদেরকে কে যন্ত্রণাদায়ক শাস্তি থেকে রক্ষা করবে?'),
  ('bn.bengali', 67, 29, 'বলুন, তিনি পরম করুণাময়, আমরা তাতে বিশ্বাস রাখি এবং তাঁরই উপর ভরসা করি। সত্ত্বরই তোমরা জানতে পারবে, কে প্রকাশ্য পথ-ভ্রষ্টতায় আছে।'),
  ('bn.bengali', 67, 30, 'বলুন, তোমরা ভেবে দেখেছ কি, যদি তোমাদের পানি ভূগর্ভের গভীরে চলে যায়, তবে কে তোমাদেরকে সরবরাহ করবে পানির স্রোতধারা?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 67, 1, 'Blessed is He in Whose hand is the Sovereignty, and, He is Able to do all things.'),
  ('en.pickthall', 67, 2, 'Who hath created life and death that He may try you which of you is best in conduct; and He is the Mighty, the Forgiving,'),
  ('en.pickthall', 67, 3, 'Who hath created seven heavens in harmony. Thou (Muhammad) canst see no fault in the Beneficent One\'s creation; then look again: Canst thou see any rifts?'),
  ('en.pickthall', 67, 4, 'Then look again and yet again, thy sight will return unto thee weakened and made dim.'),
  ('en.pickthall', 67, 5, 'And verily We have beautified the world\'s heaven with lamps, and We have made them missiles for the devils, and for them We have prepared the doom of flame.'),
  ('en.pickthall', 67, 6, 'And for those who disbelieve in their Lord there is the doom of hell, a hapless journey\'s end!'),
  ('en.pickthall', 67, 7, 'When they are flung therein they hear its roaring as it boileth up,'),
  ('en.pickthall', 67, 8, 'As it would burst with rage. Whenever a (fresh) host is flung therein the wardens thereof ask them: Came there unto you no warner?'),
  ('en.pickthall', 67, 9, 'They say: Yea, verily, a warner came unto us; but we denied and said: Allah hath naught revealed; ye are in naught but a great error.'),
  ('en.pickthall', 67, 10, 'And they say: Had we been wont to listen or have sense, we had not been among the dwellers in the flames.'),
  ('en.pickthall', 67, 11, 'So they acknowledge their sins; but far removed (from mercy) are the dwellers in the flames.'),
  ('en.pickthall', 67, 12, 'Lo! those who fear their Lord in secret, theirs will be forgiveness and a great reward.'),
  ('en.pickthall', 67, 13, 'And keep your opinion secret or proclaim it, lo! He is Knower of all that is in the breasts (of men).'),
  ('en.pickthall', 67, 14, 'Should He not know what He created? And He is the Subtile, the Aware.'),
  ('en.pickthall', 67, 15, 'He it is Who hath made the earth subservient unto you, so Walk in the paths thereof and eat of His providence. And unto Him will be the resurrection (of the dead).'),
  ('en.pickthall', 67, 16, 'Have ye taken security from Him Who is in the heaven that He will not cause the earth to swallow you when lo! it is convulsed?'),
  ('en.pickthall', 67, 17, 'Or have ye taken security from Him Who is in the heaven that He will not let loose on you a hurricane? But ye shall know the manner of My warning.'),
  ('en.pickthall', 67, 18, 'And verily those before them denied, then (see) the manner of My wrath (with them)!'),
  ('en.pickthall', 67, 19, 'Have they not seen the birds above them spreading out their wings and closing them? Naught upholdeth them save the Beneficent. Lo! He is Seer of all things.'),
  ('en.pickthall', 67, 20, 'Or who is he that will be an army unto you to help you instead of the Beneficent? The disbelievers are in naught but illusion.'),
  ('en.pickthall', 67, 21, 'Or who is he that will provide for you if He should withhold His providence? Nay, but they are set in pride and frowardness.'),
  ('en.pickthall', 67, 22, 'Is he who goeth groping on his face more rightly guided, or he who walketh upright on a straight road?'),
  ('en.pickthall', 67, 23, 'Say (unto them, O Muhammad): He it is who gave you being, and hath assigned unto you ears and eyes and hearts. Small thanks give ye!'),
  ('en.pickthall', 67, 24, 'Say: He it is Who multiplieth you in the earth, and unto Whom ye will be gathered.'),
  ('en.pickthall', 67, 25, 'And they say: When (will) this promise (be fulfilled), if ye are truthful?'),
  ('en.pickthall', 67, 26, 'Say: The knowledge is with Allah only, and I am but a plain warner;'),
  ('en.pickthall', 67, 27, 'But when they see it nigh, the faces of those who disbelieve will be awry, and it will be said (unto them): This is that for which ye used to call.'),
  ('en.pickthall', 67, 28, 'Say (O Muhammad): Have ye thought: Whether Allah causeth me (Muhammad) and those with me to perish or hath mercy on us, still, who will protect the disbelievers from a painful doom?'),
  ('en.pickthall', 67, 29, 'Say: He is the Beneficent. In Him we believe and in Him we put our trust. And ye will soon know who it is that is in error manifest.'),
  ('en.pickthall', 67, 30, 'Say: Have ye thought: If (all) your water were to disappear into the earth, who then could bring you gushing water?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 67, 1, 'Blessed be He in Whose hands is Dominion; and He over all things hath Power;-'),
  ('en.yusufali', 67, 2, 'He Who created Death and Life, that He may try which of you is best in deed: and He is the Exalted in Might, Oft-Forgiving;-'),
  ('en.yusufali', 67, 3, 'He Who created the seven heavens one above another: No want of proportion wilt thou see in the Creation of (Allah) Most Gracious. So turn thy vision again: seest thou any flaw?'),
  ('en.yusufali', 67, 4, 'Again turn thy vision a second time: (thy) vision will come back to thee dull and discomfited, in a state worn out.'),
  ('en.yusufali', 67, 5, 'And we have, (from of old), adorned the lowest heaven with Lamps, and We have made such (Lamps) (as) missiles to drive away the Evil Ones, and have prepared for them the Penalty of the Blazing Fire.'),
  ('en.yusufali', 67, 6, 'For those who reject their Lord (and Cherisher) is the Penalty of Hell: and evil is (such), Destination.'),
  ('en.yusufali', 67, 7, 'When they are cast therein, they will hear the (terrible) drawing in of its breath even as it blazes forth,'),
  ('en.yusufali', 67, 8, 'Almost bursting with fury: Every time a Group is cast therein, its Keepers will ask, "Did no Warner come to you?"'),
  ('en.yusufali', 67, 9, 'They will say: "Yes indeed; a Warner did come to us, but we rejected him and said, \'Allah never sent down any (Message): ye are nothing but an egregious delusion!\'"'),
  ('en.yusufali', 67, 10, 'They will further say: "Had we but listened or used our intelligence, we should not (now) be among the Companions of the Blazing Fire!"'),
  ('en.yusufali', 67, 11, 'They will then confess their sins: but far will be (Forgiveness) from the Companions of the Blazing Fire!'),
  ('en.yusufali', 67, 12, 'As for those who fear their Lord unseen, for them is Forgiveness and a great Reward.'),
  ('en.yusufali', 67, 13, 'And whether ye hide your word or publish it, He certainly has (full) knowledge, of the secrets of (all) hearts.'),
  ('en.yusufali', 67, 14, 'Should He not know,- He that created? and He is the One that understands the finest mysteries (and) is well-acquainted (with them).'),
  ('en.yusufali', 67, 15, 'It is He Who has made the earth manageable for you, so traverse ye through its tracts and enjoy of the Sustenance which He furnishes: but unto Him is the Resurrection.'),
  ('en.yusufali', 67, 16, 'Do ye feel secure that He Who is in heaven will not cause you to be swallowed up by the earth when it shakes (as in an earthquake)?'),
  ('en.yusufali', 67, 17, 'Or do ye feel secure that He Who is in Heaven will not send against you a violent tornado (with showers of stones), so that ye shall know how (terrible) was My warning?'),
  ('en.yusufali', 67, 18, 'But indeed men before them rejected (My warning): then how (terrible) was My rejection (of them)?'),
  ('en.yusufali', 67, 19, 'Do they not observe the birds above them, spreading their wings and folding them in? None can uphold them except (Allah) Most Gracious: Truly (Allah) Most Gracious: Truly it is He that watches over all things.'),
  ('en.yusufali', 67, 20, 'Nay, who is there that can help you, (even as) an army, besides (Allah) Most Merciful? In nothing but delusion are the Unbelievers.'),
  ('en.yusufali', 67, 21, 'Or who is there that can provide you with Sustenance if He were to withhold His provision? Nay, they obstinately persist in insolent impiety and flight (from the Truth).'),
  ('en.yusufali', 67, 22, 'Is then one who walks headlong, with his face grovelling, better guided,- or one who walks evenly on a Straight Way?'),
  ('en.yusufali', 67, 23, 'Say: "It is He Who has created you (and made you grow), and made for you the faculties of hearing, seeing, feeling and understanding: little thanks it is ye give.'),
  ('en.yusufali', 67, 24, 'Say: "It is He Who has multiplied you through the earth, and to Him shall ye be gathered together."'),
  ('en.yusufali', 67, 25, 'They ask: When will this promise be (fulfilled)? - If ye are telling the truth.'),
  ('en.yusufali', 67, 26, 'Say: "As to the knowledge of the time, it is with Allah alone: I am (sent) only to warn plainly in public."'),
  ('en.yusufali', 67, 27, 'At length, when they see it close at hand, grieved will be the faces of the Unbelievers, and it will be said (to them): "This is (the promise fulfilled), which ye were calling for!"'),
  ('en.yusufali', 67, 28, 'Say: "See ye?- If Allah were to destroy me, and those with me, or if He bestows His Mercy on us,- yet who can deliver the Unbelievers from a grievous Penalty?"'),
  ('en.yusufali', 67, 29, 'Say: "He is (Allah) Most Gracious: We have believed in Him, and on Him have we put our trust: So, soon will ye know which (of us) it is that is in manifest error."'),
  ('en.yusufali', 67, 30, 'Say: "See ye?- If your stream be some morning lost (in the underground earth), who then can supply you with clear-flowing water?"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 67, 1, 'Tabaarakal lazee biyadihil mulku wa huwa \'alaa kulli shai-in qadeer'),
  ('en.transliteration', 67, 2, 'Allazee khalaqal mawta walhayaata liyabluwakum ayyukum ahsanu \'amalaa; wa huwal \'azeezul ghafoor'),
  ('en.transliteration', 67, 3, 'Allazee khalaqa sab\'a samaawaatin tibaaqam maa taraa fee khalqir rahmaani min tafaawutin farji\'il basara hal taraa min futoor'),
  ('en.transliteration', 67, 4, 'Summar ji\'il basara karrataini yanqalib ilaikal basaru khaasi\'anw wa huwa haseer'),
  ('en.transliteration', 67, 5, 'Wa laqad zaiyannas samaaa\'ad dunyaa bimasaa beeha wa ja\'alnaahaa rujoomal lish shayaateeni wa a\'tadnaa lahum \'azaabas sa\'eer'),
  ('en.transliteration', 67, 6, 'Wa lillazeena kafaroo bi rabbihim \'azaabu jahannama wa bi\'sal maseer'),
  ('en.transliteration', 67, 7, 'Izaaa ulqoo feehaa sami\'oo lahaa shaheeqanw wa hiya tafoor'),
  ('en.transliteration', 67, 8, 'Takaadu tamayyazu minal ghaizi kullamaaa uliqya feehaa fawjun sa alahum khazanatuhaaa alam yaatikum nazeer'),
  ('en.transliteration', 67, 9, 'Qaaloo balaa qad jaaa\'anaa nazeerun fakazzabnaa wa qulnaa maa nazzalal laahu min shai in in antum illaa fee dalaalin kabeer'),
  ('en.transliteration', 67, 10, 'Wa qaaloo law kunnaa nasma\'u awna\'qilu maa kunnaa feee as haabis sa\'eer'),
  ('en.transliteration', 67, 11, 'Fa\'tarafoo bizambihim fasuhqal li as haabis sa\'eer'),
  ('en.transliteration', 67, 12, 'Innal lazeena yakhshawna rabbahum bilghaibi lahum maghfiratunw wa ajrun kabeer'),
  ('en.transliteration', 67, 13, 'Wa asirroo qawlakum awijharoo bihee innahoo \'aleemum bizaatis sudoor'),
  ('en.transliteration', 67, 14, 'Alaa ya\'lamu man khalaq wa huwal lateeful khabeer'),
  ('en.transliteration', 67, 15, 'Huwal lazee ja\'ala lakumul arda zaloolan famshoo fee manaakibihaa wa kuloo mir rizqihee wa ilaihin nushoor'),
  ('en.transliteration', 67, 16, '\'A-amintum man fissamaaa\'i aiyakhsifa bi kumul arda fa izaa hiya tamoor'),
  ('en.transliteration', 67, 17, 'Am amintum man fissamaaa\'i ai yursila \'alaikum haasiban fasata\'lamoona kaifa nazeer'),
  ('en.transliteration', 67, 18, 'Wa laqad kazzabal lazeena min qablihim fakaifa kaana nakeer'),
  ('en.transliteration', 67, 19, 'Awalam yaraw ilat tairi fawqahum saaaffaatinw wa yaqbidn; maa yumsikuhunna illaar rahmaan; innahoo bikulli shai im baseer'),
  ('en.transliteration', 67, 20, 'Amman haazal lazee huwa jundul lakum yansurukum min doonir rahmaan; inilkaafiroona illaa fee ghuroor'),
  ('en.transliteration', 67, 21, 'Amman haazal lazee yarzuqukum in amsaka rizqah; bal lajjoo fee \'utuwwinw wa nufoor'),
  ('en.transliteration', 67, 22, 'Afamai yamshee mukibban \'alaa wajhihee ahdaaa ammany yamshee sawiyyan \'alaa siratim mustaqeem'),
  ('en.transliteration', 67, 23, 'Qul huwal lazee ansha akum wa ja\'ala lakumus sam\'a wal absaara wal af\'idata qaleelam maa tashkuroon'),
  ('en.transliteration', 67, 24, 'Qul huwal lazee zara akum fil ardi wa ilaihi tuhsharoon'),
  ('en.transliteration', 67, 25, 'Wa yaqooloona mataa haazal wa\'du in kuntum saadiqeen'),
  ('en.transliteration', 67, 26, 'Qul innamal \'ilmu \'indallaahi wa innamaaa ana nazeerum mubeen'),
  ('en.transliteration', 67, 27, 'Falaammaa ra-awhu zulfatan seee\'at wujoohul lazeena kafaroo wa qeela haazal lazee kuntum bihee tadda\'oon'),
  ('en.transliteration', 67, 28, 'Qul ara\'aytum in ahlaka niyal laahu wa mam ma\'iya aw rahimanaa famai-yujeerul kaafireena min \'azaabin aleem'),
  ('en.transliteration', 67, 29, 'Qul huwar rahmaanu aamannaa bihee wa \'alaihi tawakkalnaa fasata\'lamoona man huwa fee dalaalim mubeen'),
  ('en.transliteration', 67, 30, 'Qul ara\'aytum in asbaha maaa\'ukum ghawran famai yaateekum bimaaa\'im ma\'een')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 67, 1, 'وہ ذات با برکت ہے جس کے ہاتھ میں سب حکومت ہے اور وہ ہر چیز پر قادر ہے'),
  ('ur.ahmedali', 67, 2, 'جس نے موت اور زندگی کو پیدا کیا تاکہ تمہیں آزمائيں کہ تم میں کس کے کام اچھے ہیں اور وہ غالب بخشنے والا ہے'),
  ('ur.ahmedali', 67, 3, 'جس نے سات آسمان اوپر تلے بنائے تو رحمان کی اس صنعت میں کوئی خلل نہ دیکھے گا تو پھر نگاہ دوڑا کیا تجھے کوئی شگاف دکھائی دیتا ہے'),
  ('ur.ahmedali', 67, 4, 'پھر دوبارہ نگاہ کر تیری طرف نگاہ ناکام لوٹ آئے گی اور وہ تھکی ہوئی ہو گی'),
  ('ur.ahmedali', 67, 5, 'اور ہم نے دنیا کے آسمان کو چراغوں سے آراستہ کیا ہے اور ہم نے انہیں شیطانوں کو مارنے کے لیے آلہ بنا دیا ہے اور ہم نے ان کے لیے بھڑکتی آگ کا عذاب تیار کر رکھا ہے'),
  ('ur.ahmedali', 67, 6, 'اور جنہوں نے اپنے رب کا انکار کیا ہے ان کے لیے جہنم کا عذاب ہے اور وہ بہت ہی بری جگہ ہے'),
  ('ur.ahmedali', 67, 7, 'جب اس میں ڈالے جائیں گے تو اس کے شور کی آواز سنیں گے اور وہ جوش مارتی ہوگی'),
  ('ur.ahmedali', 67, 8, 'ایسا معلوم ہو گا کہ جوش کی وجہ سے ابھی پھٹ پڑے گی جب اس میں ایک گروہ ڈالا جائے گا تو ان سے دوزخ کے داروغہ پوچھیں گے کیاتمہارے پاس کوئی ڈرانے والا نہیں آیا تھا'),
  ('ur.ahmedali', 67, 9, 'وہ کہیں گے ہاں بے شک ہمارے پاس ڈرنے والا آیا تھا پر ہم نے جھٹلا دیا اور کہہ دیا کہ الله نے کچھ بھی نازل نہیں کیا تم خود بڑی گمراہی میں پڑے ہوئے ہو'),
  ('ur.ahmedali', 67, 10, 'اور کہیں گے کہ اگر ہم نے سنا یا سمجھا ہوتا تو ہم دوزخیوں میں نہ ہوتے'),
  ('ur.ahmedali', 67, 11, 'پھر وہ اپنے گناہ کا اقرار کریں گے سو دوزخيوں پر پھٹکار ہے'),
  ('ur.ahmedali', 67, 12, 'بے شک جو لوگ اپنے رب سے بن دیکھے ڈرتے ہیں ان کے لیے بخشش اور بڑا اجر ہے'),
  ('ur.ahmedali', 67, 13, 'اور تم اپنی بات کو چھپاؤ یا ظاہر کرو بے شک وہ سینوں کے بھید خوب جانتا ہے'),
  ('ur.ahmedali', 67, 14, 'بھلا وہ نہیں جانتا جس نے (سب کو) پیدا کیا وہ بڑا باریک بین خبردار ہے'),
  ('ur.ahmedali', 67, 15, 'وہی تو ہے جس نے تمہارے لیے زمین کو نرم کر دیا سو تم اس کے راستوں میں چلو پھر اور الله کے رزق میں سے کھاؤ اور اسی کے پاس پھر کر جانا ہے'),
  ('ur.ahmedali', 67, 16, 'کیا تم اس سے ڈرتے نہیں جو آسمان میں ہے کہ وہ تمہیں زمین میں دھنسا دے پس یکایک وہ لرزنے لگے'),
  ('ur.ahmedali', 67, 17, 'کیا تم اس سے نڈر ہو گئے ہو جو آسمان میں ہے وہ تم پر پتھر برسا دے پھر تمہیں معلوم ہو جائے گا کہ میرا ڈرانا کیسا ہے'),
  ('ur.ahmedali', 67, 18, 'اور ان سے پہلے لوگ بھی جھٹلا چکے ہیں پھر ہماری ناراضگی کاکیا نتیجہ ہوا'),
  ('ur.ahmedali', 67, 19, 'اور کیا انہوں نے اپنے اوپر پرندوں کو پر کھولتے اور سکیڑتے ہوئے نہیں دیکھا جنہیں رحمان کے سوا کوئی نہیں تھام رہا بے شک وہ ہر چیز کو دیکھ رہاہے'),
  ('ur.ahmedali', 67, 20, 'بھلا وہ تمہارا کون سا لشکر ہے جو رحمنٰ کے مقابلہ میں تمہاری مدد کرے گا کچھ نہیں کافر تو دھوکے میں پڑے ہوئے ہیں'),
  ('ur.ahmedali', 67, 21, 'بھلا وہ کون ہے جو تم کو روزی دے گا اگر وہ اپنی روزی بند کر لے کچھ نہیں بلکہ وہ سرکشی اور نفرت میں اڑے بیٹھے ہیں'),
  ('ur.ahmedali', 67, 22, 'پس کیا وہ شخص جو اپنے منہ کے بل اوندھا چلتا ہے وہ زیادہ راہِ راست پر ہے یا وہ جو سیدھے راستے پر سیدھا چلا جاتا ہے'),
  ('ur.ahmedali', 67, 23, 'کہہ دو اسی نے تم کو پیدا کیا ہے اور تمہارے لیے کان اور آنکھ اور دل بھی بنائے ہیں (مگر) تم بہت ہی کم شکر کرتے ہو'),
  ('ur.ahmedali', 67, 24, 'کہہ دو اسی نے تمہیں زمین میں پھیلایا ہے اور اسی کے پاس جمع کر کے لائے جاؤ گے'),
  ('ur.ahmedali', 67, 25, 'اور وہ کہتے ہیں کہ یہ وعدہ کب ہو گا اگر تم سچے ہو'),
  ('ur.ahmedali', 67, 26, 'کہہ دو اس کی خبر تو الله ہی کو ہے اور میں تو صاف صاف ڈرانے والا ہوں'),
  ('ur.ahmedali', 67, 27, 'پھر جب وہ اسے قریب دیکھیں گے تو ان کی صورتیں بگڑ جائیں گی جو کافر ہیں اور کہا جائے گا یہ وہی ہے جسے تم دنیا میں مانگا کرتے تھے'),
  ('ur.ahmedali', 67, 28, 'کہہ دو بھلادیکھو تو سہی اگر الله مجھے اور میرے ساتھ والوں کو ہلاک کرے یا ہم پر رحم کرے پھر وہ کون ہے جو منکروں کو دردناک عذاب سے بچا سکے'),
  ('ur.ahmedali', 67, 29, 'کہہ دو وہی رحمنٰ ہے ہم اس پر ایمان لائے اور اسی پر ہم نے بھروسہ بھی کررکھا پس عنقریب تم جان لو گے کون صریح گمراہی میں ہے'),
  ('ur.ahmedali', 67, 30, 'کہہ دو بھلا دیکھو تو سہی اگر تمہارا پانی خشک ہو جائے تو وہ کون ہے جو تمہارے پاس صاف پانی لے آئے گا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 67, 1, 'Hükümranlık elinde olan Allah yücedir ve O herşeye Kadir\'dir.'),
  ('tr.diyanet', 67, 2, 'Hanginizin daha iyi iş işlediğini belirtmek için, ölümü ve dirimi (hayatı) yaratan O\'dur. O, güçlüdür, bağışlayandır.'),
  ('tr.diyanet', 67, 3, 'Gökleri yedi kat üzerine yaratan O\'dur. Rahman\'ın bu yaratmasında bir düzensizlik bulamazsın. Gözünü bir çevir bak, bir çatlak görebilir misin?'),
  ('tr.diyanet', 67, 4, 'Bir aksaklık bulmak için gözünü tekrar tekrar çevir bak; ama göz umduğunu bulamayıp bitkin ve yorgun düşer.'),
  ('tr.diyanet', 67, 5, 'And olsun ki, yakın göğü kandillerle donattık, onları şeytanlar için taşlamalar yaptık ve şeytanlara çılgın alev azabını hazırladık.'),
  ('tr.diyanet', 67, 6, 'Rablerini inkar eden kimseler için cehennem azabı vardır. Ne kötü bir dönüştür!'),
  ('tr.diyanet', 67, 7, 'Oraya atıldıkları zaman, onun kaynarken çıkardığı uğultuyu işitirler.'),
  ('tr.diyanet', 67, 8, 'Nerede ise öfkesinden paralanacak! İçine her bir topluluğun atılmasında, bekçileri onlara: "Size bir uyarıcı gelmemiş miydi?" diye sorarlar.'),
  ('tr.diyanet', 67, 9, 'Onlar: "Evet; doğrusu bize bir uyarıcı geldi, fakat biz yalanladık ve Allah hiçbir şey indirmemiştir, siz büyük bir sapıklık içindesiniz demiştik" derler.'),
  ('tr.diyanet', 67, 10, '"Eğer kulak vermiş veya akletmiş olsaydık, çılgın alevli cehennemlikler içinde olmazdık" derler.'),
  ('tr.diyanet', 67, 11, 'Böylece, günahlarını itiraf ederler. Çılgın alevli cehennemlikler yok olsunlar!'),
  ('tr.diyanet', 67, 12, 'Doğrusu, görünmediği halde Rablerinden korkanlara, onlara, bağışlanma ve büyük ecir vardır.'),
  ('tr.diyanet', 67, 13, 'Sizler, sözlerinizi gizleseniz de açıklasanız da birdir; O, kalblerde olanı bilir.'),
  ('tr.diyanet', 67, 14, 'Yaratan bilmez olur mu? O, Latif\'tir, haberdardır.'),
  ('tr.diyanet', 67, 15, 'Yeryüzünü, size boyun eğdiren O\'dur; öyleyse yerin sırtlarında dolaşın, Allah\'ın verdiği rızıktan yiyin; sonunda dönüş O\'nadır.'),
  ('tr.diyanet', 67, 16, 'Gökte olanın sizi yerin dibine geçirmesinden güvende misiniz? O zaman, yer, sarsıldıkça sarsılır.'),
  ('tr.diyanet', 67, 17, 'Gökte olanın başınıza taş yağdırmasından güvende misiniz? Benim uyarmamın nasıl olduğunu yakında bileceksiniz.'),
  ('tr.diyanet', 67, 18, 'And olsun ki, bunlardan öncekiler de yalanlamışlardı. Beni inkar etmek nasılmış?'),
  ('tr.diyanet', 67, 19, 'Üzerlerinde kanat çırpan dizi dizi kuşları görmezler mi? Onları havada Rahman olan Allah\'tan başkası tutmuyor; doğrusu, O, herşeyi görendir.'),
  ('tr.diyanet', 67, 20, 'Yahut, Rahman olan Allah\'ın dışında size yardımda bulunabilecek taraftarlarınız kimdir? İnkarcılar sadece aldanmaktadırlar.'),
  ('tr.diyanet', 67, 21, 'Allah size verdiği rızkı kesiverirse, size rızık verecek başka kim vardır? Hayır; onlar, azgınlık ve nefrette direnmektedirler.'),
  ('tr.diyanet', 67, 22, 'Yüzükoyun sürünen mi, yoksa doğru yolda düpedüz yürüyen mi daha doğru yoldadır?'),
  ('tr.diyanet', 67, 23, 'De ki: "Sizi yaratan sizin için kulaklar, gözler ve kalbler var eden O\'dur. Ne az şükrediyorsunuz!"'),
  ('tr.diyanet', 67, 24, 'Sizi yerde yaratıp yayan O\'dur ve O\'nun huzurunda toplanacaksınız.'),
  ('tr.diyanet', 67, 25, '"Doğru sözlü iseniz bildirin bu azap sözü ne zamandır?" derler.'),
  ('tr.diyanet', 67, 26, 'De ki: "Onu bilmek ancak Allah\'a mahsustur. Ben sadece apaçık bir uyarıcıyım."'),
  ('tr.diyanet', 67, 27, 'Azabı yaklaşırken gördükleri zaman, inkar edenlerin yüzleri çirkinleşip kararır; onlara: "Sizin arayıp durduğunuz işte budur" denir.'),
  ('tr.diyanet', 67, 28, 'De ki: "Allah, beni ve benimle beraber bulunanları isterse yok eder veya isterse merhamet eder; söyleyin, bu takdirde inkarcıları, can yakıcı azabdan kim alıkoyabilir?"'),
  ('tr.diyanet', 67, 29, 'De ki: "Bizim inandığımız ve kendisine güvendiğimiz, Rahman olan Allah\'tır. Kimin apaçık bir sapıklıkta olduğunu yakında bileceksiniz."'),
  ('tr.diyanet', 67, 30, 'De ki: "Suyunuz yere batarsa, söyleyin, size kim temiz bir su kaynağı getirebilir?"')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 67, 1, 'Maha Suci Allah Yang di tangan-Nya-lah segala kerajaan, dan Dia Maha Kuasa atas segala sesuatu,'),
  ('id.indonesian', 67, 2, 'Yang menjadikan mati dan hidup, supaya Dia menguji kamu, siapa di antara kamu yang lebih baik amalnya. Dan Dia Maha Perkasa lagi Maha Pengampun,'),
  ('id.indonesian', 67, 3, 'Yang telah menciptakan tujuh langit berlapis-lapis. Kamu sekali-kali tidak melihat pada ciptaan Tuhan Yang Maha Pemurah sesuatu yang tidak seimbang. Maka lihatlah berulang-ulang, adakah kamu lihat sesuatu yang tidak seimbang?'),
  ('id.indonesian', 67, 4, 'Kemudian pandanglah sekali lagi niscaya penglihatanmu akan kembali kepadamu dengan tidak menemukan sesuatu cacat dan penglihatanmu itupun dalam keadaan payah.'),
  ('id.indonesian', 67, 5, 'Sesungguhnya Kami telah menghiasi langit yang dekat dengan bintang-bintang, dan Kami jadikan bintang-bintang itu alat-alat pelempar syaitan, dan Kami sediakan bagi mereka siksa neraka yang menyala-nyala.'),
  ('id.indonesian', 67, 6, 'Dan orang-orang yang kafir kepada Tuhannya, memperoleh azab Jahannam. Dan itulah seburuk-buruk tempat kembali.'),
  ('id.indonesian', 67, 7, 'Apabila mereka dilemparkan ke dalamnya mereka mendengar suara neraka yang mengerikan, sedang neraka itu menggelegak,'),
  ('id.indonesian', 67, 8, 'hampir-hampir (neraka) itu terpecah-pecah lantaran marah. Setiap kali dilemparkan ke dalamnya sekumpulan (orang-orang kafir), penjaga-penjaga (neraka itu) bertanya kepada mereka: "Apakah belum pernah datang kepada kamu (di dunia) seorang pemberi peringatan?"'),
  ('id.indonesian', 67, 9, 'Mereka menjawab: "Benar ada", sesungguhnya telah datang kepada kami seorang pemberi peringatan, maka kami mendustakan(nya) dan kami katakan: "Allah tidak menurunkan sesuatupun; kamu tidak lain hanyalah di dalam kesesatan yang besar".'),
  ('id.indonesian', 67, 10, 'Dan mereka berkata: "Sekiranya kami mendengarkan atau memikirkan (peringatan itu) niscaya tidaklah kami termasuk penghuni-penghuni neraka yang menyala-nyala".'),
  ('id.indonesian', 67, 11, 'Mereka mengakui dosa mereka. Maka kebinasaanlah bagi penghuni-penghuni neraka yang menyala-nyala.'),
  ('id.indonesian', 67, 12, 'Sesungguhnya orang-orang yang takut kepada Tuhannya Yang tidak nampak oleh mereka, mereka akan memperoleh ampunan dan pahala yang besar.'),
  ('id.indonesian', 67, 13, 'Dan rahasiakanlah perkataanmu atau lahirkanlah; sesungguhnya Dia Maha Mengetahui segala isi hati.'),
  ('id.indonesian', 67, 14, 'Apakah Allah Yang menciptakan itu tidak mengetahui (yang kamu lahirkan atau rahasiakan); dan Dia Maha Halus lagi Maha Mengetahui?'),
  ('id.indonesian', 67, 15, 'Dialah Yang menjadikan bumi itu mudah bagi kamu, maka berjalanlah di segala penjurunya dan makanlah sebahagian dari rezeki-Nya. Dan hanya kepada-Nya-lah kamu (kembali setelah) dibangkitkan.'),
  ('id.indonesian', 67, 16, 'Apakah kamu merasa aman terhadap Allah yang (berkuasa) di langit bahwa Dia akan menjungkir balikkan bumi bersama kamu, sehingga dengan tiba-tiba bumi itu bergoncang?,'),
  ('id.indonesian', 67, 17, 'atau apakah kamu merasa aman terhadap Allah yang (berkuasa) di langit bahwa Dia akan mengirimkan badai yang berbatu. Maka kelak kamu akan mengetahui bagaimana (akibat mendustakan) peringatan-Ku?'),
  ('id.indonesian', 67, 18, 'Dan sesungguhnya orang-orang yang sebelum mereka telah mendustakan (rasul-rasul-Nya). Maka alangkah hebatnya kemurkaan-Ku.'),
  ('id.indonesian', 67, 19, 'Dan apakah mereka tidak memperhatikan burung-burung yang mengembangkan dan mengatupkan sayapnya di atas mereka? Tidak ada yang menahannya (di udara) selain Yang Maha Pemurah. Sesungguhnya Dia Maha Melihat segala sesuatu.'),
  ('id.indonesian', 67, 20, 'Atau siapakah dia yang menjadi tentara bagimu yang akan menolongmu selain daripada Allah Yang Maha Pemurah? Orang-orang kafir itu tidak lain hanyalah dalam (keadaan) tertipu.'),
  ('id.indonesian', 67, 21, 'Atau siapakah dia yang memberi kamu rezeki jika Allah menahan rezeki-Nya? Sebenarnya mereka terus menerus dalam kesombongan dan menjauhkan diri?'),
  ('id.indonesian', 67, 22, 'Maka apakah orang yang berjalan terjungkal di atas mukanya itu lebih banyak mendapatkan petunjuk ataukah orang yang berjalan tegap di atas jalan yang lurus?'),
  ('id.indonesian', 67, 23, 'Katakanlah: "Dialah Yang menciptakan kamu dan menjadikan bagi kamu pendengaran, penglihatan dan hati". (Tetapi) amat sedikit kamu bersyukur.'),
  ('id.indonesian', 67, 24, 'Katakanlah: "Dialah Yang menjadikan kamu berkembang biak di muka bumi, dan hanya kepada-Nya-lah kamu kelak dikumpulkan".'),
  ('id.indonesian', 67, 25, 'Dan mereka berkata: "Kapankah datangnya ancaman itu jika kamu adalah orang-orang yang benar?"'),
  ('id.indonesian', 67, 26, 'Katakanlah: "Sesungguhnya ilmu (tentang hari kiamat itu) hanya pada sisi Allah. Dan sesungguhnya aku hanyalah seorang pemberi peringatan yang menjelaskan".'),
  ('id.indonesian', 67, 27, 'Ketika mereka melihat azab (pada hari kiamat) sudah dekat, muka orang-orang kafir itu menjadi muram. Dan dikatakan (kepada mereka) inilah (azab) yang dahulunya kamu selalu meminta-mintanya.'),
  ('id.indonesian', 67, 28, 'Katakanlah: "Terangkanlah kepadaku jika Allah mematikan aku dan orang-orang yang bersama dengan aku atau memberi rahmat kepada kami, (maka kami akan masuk surga), tetapi siapakah yang dapat melindungi orang-orang yang kafir dari siksa yang pedih?"'),
  ('id.indonesian', 67, 29, 'Katakanlah: "Dialah Allah Yang Maha Penyayang kami beriman kepada-Nya dan kepada-Nya-lah kami bertawakkal. Kelak kamu akan mengetahui siapakah yang berada dalam kesesatan yang nyata".'),
  ('id.indonesian', 67, 30, 'Katakanlah: "Terangkanlah kepadaku jika sumber air kamu menjadi kering; maka siapakah yang akan mendatangkan air yang mengalir bagimu?".')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 68, 1, 'Nun. By the pen and what they inscribe,'),
  ('en.sahih', 68, 2, 'You are not, [O Muhammad], by the favor of your Lord, a madman.'),
  ('en.sahih', 68, 3, 'And indeed, for you is a reward uninterrupted.'),
  ('en.sahih', 68, 4, 'And indeed, you are of a great moral character.'),
  ('en.sahih', 68, 5, 'So you will see and they will see'),
  ('en.sahih', 68, 6, 'Which of you is the afflicted [by a devil].'),
  ('en.sahih', 68, 7, 'Indeed, your Lord is most knowing of who has gone astray from His way, and He is most knowing of the [rightly] guided.'),
  ('en.sahih', 68, 8, 'Then do not obey the deniers.'),
  ('en.sahih', 68, 9, 'They wish that you would soften [in your position], so they would soften [toward you].'),
  ('en.sahih', 68, 10, 'And do not obey every worthless habitual swearer'),
  ('en.sahih', 68, 11, '[And] scorner, going about with malicious gossip -'),
  ('en.sahih', 68, 12, 'A preventer of good, transgressing and sinful,'),
  ('en.sahih', 68, 13, 'Cruel, moreover, and an illegitimate pretender.'),
  ('en.sahih', 68, 14, 'Because he is a possessor of wealth and children,'),
  ('en.sahih', 68, 15, 'When Our verses are recited to him, he says, "Legends of the former peoples."'),
  ('en.sahih', 68, 16, 'We will brand him upon the snout.'),
  ('en.sahih', 68, 17, 'Indeed, We have tried them as We tried the companions of the garden, when they swore to cut its fruit in the [early] morning'),
  ('en.sahih', 68, 18, 'Without making exception.'),
  ('en.sahih', 68, 19, 'So there came upon the garden an affliction from your Lord while they were asleep.'),
  ('en.sahih', 68, 20, 'And it became as though reaped.'),
  ('en.sahih', 68, 21, 'And they called one another at morning,'),
  ('en.sahih', 68, 22, '[Saying], "Go early to your crop if you would cut the fruit."'),
  ('en.sahih', 68, 23, 'So they set out, while lowering their voices,'),
  ('en.sahih', 68, 24, '[Saying], "There will surely not enter it today upon you [any] poor person."'),
  ('en.sahih', 68, 25, 'And they went early in determination, [assuming themselves] able.'),
  ('en.sahih', 68, 26, 'But when they saw it, they said, "Indeed, we are lost;'),
  ('en.sahih', 68, 27, 'Rather, we have been deprived."'),
  ('en.sahih', 68, 28, 'The most moderate of them said, "Did I not say to you, \'Why do you not exalt [Allah]?\' "'),
  ('en.sahih', 68, 29, 'They said, "Exalted is our Lord! Indeed, we were wrongdoers."'),
  ('en.sahih', 68, 30, 'Then they approached one another, blaming each other.'),
  ('en.sahih', 68, 31, 'They said, "O woe to us; indeed we were transgressors.'),
  ('en.sahih', 68, 32, 'Perhaps our Lord will substitute for us [one] better than it. Indeed, we are toward our Lord desirous."'),
  ('en.sahih', 68, 33, 'Such is the punishment [of this world]. And the punishment of the Hereafter is greater, if they only knew.'),
  ('en.sahih', 68, 34, 'Indeed, for the righteous with their Lord are the Gardens of Pleasure.'),
  ('en.sahih', 68, 35, 'Then will We treat the Muslims like the criminals?'),
  ('en.sahih', 68, 36, 'What is [the matter] with you? How do you judge?'),
  ('en.sahih', 68, 37, 'Or do you have a scripture in which you learn'),
  ('en.sahih', 68, 38, 'That indeed for you is whatever you choose?'),
  ('en.sahih', 68, 39, 'Or do you have oaths [binding] upon Us, extending until the Day of Resurrection, that indeed for you is whatever you judge?'),
  ('en.sahih', 68, 40, 'Ask them which of them, for that [claim], is responsible.'),
  ('en.sahih', 68, 41, 'Or do they have partners? Then let them bring their partners, if they should be truthful.'),
  ('en.sahih', 68, 42, 'The Day the shin will be uncovered and they are invited to prostration but the disbelievers will not be able,'),
  ('en.sahih', 68, 43, 'Their eyes humbled, humiliation will cover them. And they used to be invited to prostration while they were sound.'),
  ('en.sahih', 68, 44, 'So leave Me, [O Muhammad], with [the matter of] whoever denies the Qur\'an. We will progressively lead them [to punishment] from where they do not know.'),
  ('en.sahih', 68, 45, 'And I will give them time. Indeed, My plan is firm.'),
  ('en.sahih', 68, 46, 'Or do you ask of them a payment, so they are by debt burdened down?'),
  ('en.sahih', 68, 47, 'Or have they [knowledge of] the unseen, so they write [it] down?'),
  ('en.sahih', 68, 48, 'Then be patient for the decision of your Lord, [O Muhammad], and be not like the companion of the fish when he called out while he was distressed.'),
  ('en.sahih', 68, 49, 'If not that a favor from his Lord overtook him, he would have been thrown onto the naked shore while he was censured.'),
  ('en.sahih', 68, 50, 'And his Lord chose him and made him of the righteous.'),
  ('en.sahih', 68, 51, 'And indeed, those who disbelieve would almost make you slip with their eyes when they hear the message, and they say, "Indeed, he is mad."'),
  ('en.sahih', 68, 52, 'But it is not except a reminder to the worlds.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 68, 1, 'নূন। শপথ কলমের এবং সেই বিষয়ের যা তারা লিপিবদ্ধ করে,'),
  ('bn.bengali', 68, 2, 'আপনার পালনকর্তার অনুগ্রহে আপনি উম্মাদ নন।'),
  ('bn.bengali', 68, 3, 'আপনার জন্যে অবশ্যই রয়েছে অশেষ পুরস্কার।'),
  ('bn.bengali', 68, 4, 'আপনি অবশ্যই মহান চরিত্রের অধিকারী।'),
  ('bn.bengali', 68, 5, 'সত্ত্বরই আপনি দেখে নিবেন এবং তারাও দেখে নিবে।'),
  ('bn.bengali', 68, 6, 'কে তোমাদের মধ্যে বিকারগ্রস্ত।'),
  ('bn.bengali', 68, 7, 'আপনার পালনকর্তা সম্যক জানেন কে তাঁর পথ থেকে বিচ্যুত হয়েছে এবং তিনি জানেন যারা সৎপথ প্রাপ্ত।'),
  ('bn.bengali', 68, 8, 'অতএব, আপনি মিথ্যারোপকারীদের আনুগত্য করবেন না।'),
  ('bn.bengali', 68, 9, 'তারা চায় যদি আপনি নমনীয় হন, তবে তারাও নমনীয় হবে।'),
  ('bn.bengali', 68, 10, 'যে অধিক শপথ করে, যে লাঞ্ছিত, আপনি তার আনুগত্য করবেন না।'),
  ('bn.bengali', 68, 11, 'যে পশ্চাতে নিন্দা করে একের কথা অপরের নিকট লাগিয়ে ফিরে।'),
  ('bn.bengali', 68, 12, 'যে ভাল কাজে বাধা দেয়, সে সীমালংঘন করে, সে পাপিষ্ঠ,'),
  ('bn.bengali', 68, 13, 'কঠোর স্বভাব, তদুপরি কুখ্যাত;'),
  ('bn.bengali', 68, 14, 'এ কারণে যে, সে ধন-সম্পদ ও সন্তান সন্ততির অধিকারী।'),
  ('bn.bengali', 68, 15, 'তার কাছে আমার আয়াত পাঠ করা হলে সে বলে; সেকালের উপকথা।'),
  ('bn.bengali', 68, 16, 'আমি তার নাসিকা দাগিয়ে দিব।'),
  ('bn.bengali', 68, 17, 'আমি তাদেরকে পরীক্ষা করেছি, যেমন পরীক্ষা করেছি উদ্যানওয়ালাদের, যখন তারা শপথ করেছিল যে, সকালে বাগানের ফল আহরণ করবে,'),
  ('bn.bengali', 68, 18, 'ইনশাআল্লাহ না বলে।'),
  ('bn.bengali', 68, 19, 'অতঃপর আপনার পালনকর্তার পক্ষ থেকে বাগানে এক বিপদ এসে পতিত হলো। যখন তারা নিদ্রিত ছিল।'),
  ('bn.bengali', 68, 20, 'ফলে সকাল পর্যন্ত হয়ে গেল ছিন্নবিচ্ছিন্ন তৃণসম।'),
  ('bn.bengali', 68, 21, 'সকালে তারা একে অপরকে ডেকে বলল,'),
  ('bn.bengali', 68, 22, 'তোমরা যদি ফল আহরণ করতে চাও, তবে সকাল সকাল ক্ষেতে চল।'),
  ('bn.bengali', 68, 23, 'অতঃপর তারা চলল ফিসফিস করে কথা বলতে বলতে,'),
  ('bn.bengali', 68, 24, 'অদ্য যেন কোন মিসকীন ব্যক্তি তোমাদের কাছে বাগানে প্রবেশ করতে না পারে।'),
  ('bn.bengali', 68, 25, 'তারা সকালে লাফিয়ে লাফিয়ে সজোরে রওয়ানা হল।'),
  ('bn.bengali', 68, 26, 'অতঃপর যখন তারা বাগান দেখল, তখন বললঃ আমরা তো পথ ভূলে গেছি।'),
  ('bn.bengali', 68, 27, 'বরং আমরা তো কপালপোড়া,'),
  ('bn.bengali', 68, 28, 'তাদের উত্তম ব্যক্তি বললঃ আমি কি তোমাদেরকে বলিনি? এখনও তোমরা আল্লাহ তা’আলার পবিত্রতা বর্ণনা করছো না কেন?'),
  ('bn.bengali', 68, 29, 'তারা বললঃ আমরা আমাদের পালনকর্তার পবিত্রতা ঘোষণা করছি, নিশ্চিতই আমরা সীমালংঘনকারী ছিলাম।'),
  ('bn.bengali', 68, 30, 'অতঃপর তারা একে অপরকে ভৎর্সনা করতে লাগল।'),
  ('bn.bengali', 68, 31, 'তারা বললঃ হায়! দুর্ভোগ আমাদের আমরা ছিলাম সীমাতিক্রমকারী।'),
  ('bn.bengali', 68, 32, 'সম্ভবতঃ আমাদের পালনকর্তা পরিবর্তে এর চাইতে উত্তম বাগান আমাদেরকে দিবেন। আমরা আমাদের পালনকর্তার কাছে আশাবাদী।'),
  ('bn.bengali', 68, 33, 'শাস্তি এভাবেই আসে এবং পরকালের শাস্তি আরও গুরুতর; যদি তারা জানত!'),
  ('bn.bengali', 68, 34, 'মোত্তাকীদের জন্যে তাদের পালনকর্তার কাছে রয়েছে নেয়ামতের জান্নাত।'),
  ('bn.bengali', 68, 35, 'আমি কি আজ্ঞাবহদেরকে অপরাধীদের ন্যায় গণ্য করব?'),
  ('bn.bengali', 68, 36, 'তোমাদের কি হল ? তোমরা কেমন সিদ্ধান্ত দিচ্ছ?'),
  ('bn.bengali', 68, 37, 'তোমাদের কি কোন কিতাব আছে, যা তোমরা পাঠ কর।'),
  ('bn.bengali', 68, 38, 'তাতে তোমরা যা পছন্দ কর, তাই পাও?'),
  ('bn.bengali', 68, 39, 'না তোমরা আমার কাছ থেকেকেয়ামত পর্যন্ত বলবৎ কোন শপথ নিয়েছ যে, তোমরা তাই পাবে যা তোমরা সিদ্ধান্ত করবে?'),
  ('bn.bengali', 68, 40, 'আপনি তাদেরকে জিজ্ঞাসা করুন তাদের কে এ বিষয়ে দায়িত্বশীল?'),
  ('bn.bengali', 68, 41, 'না তাদের কোন শরীক উপাস্য আছে? থাকলে তাদের শরীক উপাস্যদেরকে উপস্থিত করুক যদি তারা সত্যবাদী হয়।'),
  ('bn.bengali', 68, 42, 'গোছা পর্যন্ত পা খোলার দিনের কথা স্মরণ কর, সেদিন তাদেরকে সেজদা করতে আহবান জানানো হবে, অতঃপর তারা সক্ষম হবে না।'),
  ('bn.bengali', 68, 43, 'তাদের দৃষ্টি অবনত থাকবে; তারা লাঞ্ছনাগ্রস্ত হবে, অথচ যখন তারা সুস্থ ও স্বাভাবিক অবস্থায় ছিল, তখন তাদেরকে সেজদা করতে আহবান জানানো হত।'),
  ('bn.bengali', 68, 44, 'অতএব, যারা এই কালামকে মিথ্যা বলে, তাদেরকে আমার হাতে ছেড়ে দিন, আমি এমন ধীরে ধীরে তাদেরকে জাহান্নামের দিকে নিয়ে যাব যে, তারা জানতে পারবে না।'),
  ('bn.bengali', 68, 45, 'আমি তাদেরকে সময় দেই। নিশ্চয় আমার কৌশল মজবুত।'),
  ('bn.bengali', 68, 46, 'আপনি কি তাদের কাছে পারিশ্রমিক চান? ফলে তাদের উপর জরিমানার বোঝা পড়ছে?'),
  ('bn.bengali', 68, 47, 'না তাদের কাছে গায়বের খবর আছে? অতঃপর তারা তা লিপিবদ্ধ করে।'),
  ('bn.bengali', 68, 48, 'আপনি আপনার পালনকর্তার আদেশের অপেক্ষায় সবর করুন এবং মাছওয়ালা ইউনুসের মত হবেন না, যখন সে দুঃখাকুল মনে প্রার্থনা করেছিল।'),
  ('bn.bengali', 68, 49, 'যদি তার পালনকর্তার অনুগ্রহ তাকে সামাল না দিত, তবে সে নিন্দিত অবস্থায় জনশুন্য প্রান্তরে নিক্ষিপ্ত হত।'),
  ('bn.bengali', 68, 50, 'অতঃপর তার পালনকর্তা তাকে মনোনীত করলেন এবং তাকে সৎকর্মীদের অন্তর্ভুক্ত করে নিলেন।'),
  ('bn.bengali', 68, 51, 'কাফেররা যখন কোরআন শুনে, তখন তারা তাদের দৃষ্টি দ্বারা যেন আপনাকে আছাড় দিয়ে ফেলে দিবে এবং তারা বলেঃ সে তো একজন পাগল।'),
  ('bn.bengali', 68, 52, 'অথচ এই কোরআন তো বিশ্বজগতের জন্যে উপদেশ বৈ নয়।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 68, 1, 'Nun. By the pen and that which they write (therewith),'),
  ('en.pickthall', 68, 2, 'Thou art not, for thy Lord\'s favour unto thee, a madman.'),
  ('en.pickthall', 68, 3, 'And lo! thine verily will be a reward unfailing.'),
  ('en.pickthall', 68, 4, 'And lo! thou art of a tremendous nature.'),
  ('en.pickthall', 68, 5, 'And thou wilt see and they will see'),
  ('en.pickthall', 68, 6, 'Which of you is the demented.'),
  ('en.pickthall', 68, 7, 'Lo! thy Lord is Best Aware of him who strayeth from His way, and He is Best Aware of those who walk aright.'),
  ('en.pickthall', 68, 8, 'Therefor obey not thou the rejecters'),
  ('en.pickthall', 68, 9, 'Who would have had thee compromise, that they may compromise.'),
  ('en.pickthall', 68, 10, 'Neither obey thou each feeble oath-monger,'),
  ('en.pickthall', 68, 11, 'Detracter, spreader abroad of slanders,'),
  ('en.pickthall', 68, 12, 'Hinderer of the good, transgressor, malefactor'),
  ('en.pickthall', 68, 13, 'Greedy therewithal, intrusive.'),
  ('en.pickthall', 68, 14, 'It is because he is possessed of wealth and children'),
  ('en.pickthall', 68, 15, 'That, when Our revelations are recited unto him, he saith: Mere fables of the men of old.'),
  ('en.pickthall', 68, 16, 'We shall brand him on the nose.'),
  ('en.pickthall', 68, 17, 'Lo! We have tried them as We tried the owners of the garden when they vowed that they would pluck its fruit next morning,'),
  ('en.pickthall', 68, 18, 'And made no exception (for the Will of Allah);'),
  ('en.pickthall', 68, 19, 'Then a visitation from thy Lord came upon it while they slept'),
  ('en.pickthall', 68, 20, 'And in the morning it was as if plucked.'),
  ('en.pickthall', 68, 21, 'And they cried out one unto another in the morning,'),
  ('en.pickthall', 68, 22, 'Saying: Run unto your field if ye would pluck (the fruit).'),
  ('en.pickthall', 68, 23, 'So they went off, saying one unto another in low tones:'),
  ('en.pickthall', 68, 24, 'No needy man shall enter it to-day against you.'),
  ('en.pickthall', 68, 25, 'They went betimes, strong in (this) purpose.'),
  ('en.pickthall', 68, 26, 'But when they saw it, they said: Lo! we are in error!'),
  ('en.pickthall', 68, 27, 'Nay, but we are desolate!'),
  ('en.pickthall', 68, 28, 'The best among them said: Said I not unto you: Why glorify ye not (Allah)?'),
  ('en.pickthall', 68, 29, 'They said: Glorified be our Lord! Lo! we have been wrong-doers.'),
  ('en.pickthall', 68, 30, 'Then some of them drew near unto others, self-reproaching.'),
  ('en.pickthall', 68, 31, 'They said: Alas for us! In truth we were outrageous.'),
  ('en.pickthall', 68, 32, 'It may be that our Lord will give us better than this in place thereof. Lo! we beseech our Lord.'),
  ('en.pickthall', 68, 33, 'Such was the punishment. And verily the punishment of the Hereafter is greater if they did but know.'),
  ('en.pickthall', 68, 34, 'Lo! for those who keep from evil are gardens of bliss with their Lord.'),
  ('en.pickthall', 68, 35, 'Shall We then treat those who have surrendered as We treat the guilty?'),
  ('en.pickthall', 68, 36, 'What aileth you? How foolishly ye judge!'),
  ('en.pickthall', 68, 37, 'Or have ye a scripture wherein ye learn'),
  ('en.pickthall', 68, 38, 'That ye shall indeed have all that ye choose?'),
  ('en.pickthall', 68, 39, 'Or have ye a covenant on oath from Us that reacheth to the Day of Judgment, that yours shall be all that ye ordain?'),
  ('en.pickthall', 68, 40, 'Ask them (O Muhammad) which of them will vouch for that!'),
  ('en.pickthall', 68, 41, 'Or have they other gods? Then let them bring their other gods if they are truthful'),
  ('en.pickthall', 68, 42, 'On the day when it befalleth in earnest, and they are ordered to prostrate themselves but are not able,'),
  ('en.pickthall', 68, 43, 'With eyes downcast, abasement stupefying them. And they had been summoned to prostrate themselves while they were yet unhurt.'),
  ('en.pickthall', 68, 44, 'Leave Me (to deal) with those who give the lie to this pronouncement. We shall lead them on by steps from whence they know not.'),
  ('en.pickthall', 68, 45, 'Yet I bear with them, for lo! My scheme is firm.'),
  ('en.pickthall', 68, 46, 'Or dost thou (Muhammad) ask a fee from them so that they are heavily taxed?'),
  ('en.pickthall', 68, 47, 'Or is the Unseen theirs that they can write (thereof)?'),
  ('en.pickthall', 68, 48, 'But wait thou for thy Lord\'s decree, and be not like him of the fish, who cried out in despair.'),
  ('en.pickthall', 68, 49, 'Had it not been that favour from his Lord had reached him he surely had been cast into the wilderness while he was reprobate.'),
  ('en.pickthall', 68, 50, 'But his Lord chose him and placed him among the righteous.'),
  ('en.pickthall', 68, 51, 'And lo! those who disbelieve would fain disconcert thee with their eyes when they hear the Reminder, and they say: Lo! he is indeed mad;'),
  ('en.pickthall', 68, 52, 'When it is naught else than a Reminder to creation.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 68, 1, 'Nun. By the Pen and the (Record) which (men) write,-'),
  ('en.yusufali', 68, 2, 'Thou art not, by the Grace of thy Lord, mad or possessed.'),
  ('en.yusufali', 68, 3, 'Nay, verily for thee is a Reward unfailing:'),
  ('en.yusufali', 68, 4, 'And thou (standest) on an exalted standard of character.'),
  ('en.yusufali', 68, 5, 'Soon wilt thou see, and they will see,'),
  ('en.yusufali', 68, 6, 'Which of you is afflicted with madness.'),
  ('en.yusufali', 68, 7, 'Verily it is thy Lord that knoweth best, which (among men) hath strayed from His Path: and He knoweth best those who receive (true) Guidance.'),
  ('en.yusufali', 68, 8, 'So hearken not to those who deny (the Truth).'),
  ('en.yusufali', 68, 9, 'Their desire is that thou shouldst be pliant: so would they be pliant.'),
  ('en.yusufali', 68, 10, 'Heed not the type of despicable men,- ready with oaths,'),
  ('en.yusufali', 68, 11, 'A slanderer, going about with calumnies,'),
  ('en.yusufali', 68, 12, '(Habitually) hindering (all) good, transgressing beyond bounds, deep in sin,'),
  ('en.yusufali', 68, 13, 'Violent (and cruel),- with all that, base-born,-'),
  ('en.yusufali', 68, 14, 'Because he possesses wealth and (numerous) sons.'),
  ('en.yusufali', 68, 15, 'When to him are rehearsed Our Signs, "Tales of the ancients", he cries!'),
  ('en.yusufali', 68, 16, 'Soon shall We brand (the beast) on the snout!'),
  ('en.yusufali', 68, 17, 'Verily We have tried them as We tried the People of the Garden, when they resolved to gather the fruits of the (garden) in the morning.'),
  ('en.yusufali', 68, 18, 'But made no reservation, ("If it be Allah\'s Will").'),
  ('en.yusufali', 68, 19, 'Then there came on the (garden) a visitation from thy Lord, (which swept away) all around, while they were asleep.'),
  ('en.yusufali', 68, 20, 'So the (garden) became, by the morning, like a dark and desolate spot, (whose fruit had been gathered).'),
  ('en.yusufali', 68, 21, 'As the morning broke, they called out, one to another,-'),
  ('en.yusufali', 68, 22, '"Go ye to your tilth (betimes) in the morning, if ye would gather the fruits."'),
  ('en.yusufali', 68, 23, 'So they departed, conversing in secret low tones, (saying)-'),
  ('en.yusufali', 68, 24, '"Let not a single indigent person break in upon you into the (garden) this day."'),
  ('en.yusufali', 68, 25, 'And they opened the morning, strong in an (unjust) resolve.'),
  ('en.yusufali', 68, 26, 'But when they saw the (garden), they said: "We have surely lost our way:'),
  ('en.yusufali', 68, 27, '"Indeed we are shut out (of the fruits of our labour)!"'),
  ('en.yusufali', 68, 28, 'Said one of them, more just (than the rest): "Did I not say to you, \'Why not glorify (Allah)?\'"'),
  ('en.yusufali', 68, 29, 'They said: "Glory to our Lord! Verily we have been doing wrong!"'),
  ('en.yusufali', 68, 30, 'Then they turned, one against another, in reproach.'),
  ('en.yusufali', 68, 31, 'They said: "Alas for us! We have indeed transgressed!'),
  ('en.yusufali', 68, 32, '"It may be that our Lord will give us in exchange a better (garden) than this: for we do turn to Him (in repentance)!"'),
  ('en.yusufali', 68, 33, 'Such is the Punishment (in this life); but greater is the Punishment in the Hereafter,- if only they knew!'),
  ('en.yusufali', 68, 34, 'Verily, for the Righteous, are Gardens of Delight, in the Presence of their Lord.'),
  ('en.yusufali', 68, 35, 'Shall We then treat the People of Faith like the People of Sin?'),
  ('en.yusufali', 68, 36, 'What is the matter with you? How judge ye?'),
  ('en.yusufali', 68, 37, 'Or have ye a book through which ye learn-'),
  ('en.yusufali', 68, 38, 'That ye shall have, through it whatever ye choose?'),
  ('en.yusufali', 68, 39, 'Or have ye Covenants with Us to oath, reaching to the Day of Judgment, (providing) that ye shall have whatever ye shall demand?'),
  ('en.yusufali', 68, 40, 'Ask thou of them, which of them will stand surety for that!'),
  ('en.yusufali', 68, 41, 'Or have they some "Partners" (in Allahhead)? Then let them produce their "partners", if they are truthful!'),
  ('en.yusufali', 68, 42, 'The Day that the shin shall be laid bare, and they shall be summoned to bow in adoration, but they shall not be able,-'),
  ('en.yusufali', 68, 43, 'Their eyes will be cast down,- ignominy will cover them; seeing that they had been summoned aforetime to bow in adoration, while they were whole, (and had refused).'),
  ('en.yusufali', 68, 44, 'Then leave Me alone with such as reject this Message: by degrees shall We punish them from directions they perceive not.'),
  ('en.yusufali', 68, 45, 'A (long) respite will I grant them: truly powerful is My Plan.'),
  ('en.yusufali', 68, 46, 'Or is it that thou dost ask them for a reward, so that they are burdened with a load of debt?-'),
  ('en.yusufali', 68, 47, 'Or that the Unseen is in their hands, so that they can write it down?'),
  ('en.yusufali', 68, 48, 'So wait with patience for the Command of thy Lord, and be not like the Companion of the Fish,- when he cried out in agony.'),
  ('en.yusufali', 68, 49, 'Had not Grace from his Lord reached him, he would indeed have been cast off on the naked shore, in disgrace.'),
  ('en.yusufali', 68, 50, 'Thus did his Lord choose him and make him of the Company of the Righteous.'),
  ('en.yusufali', 68, 51, 'And the Unbelievers would almost trip thee up with their eyes when they hear the Message; and they say: "Surely he is possessed!"'),
  ('en.yusufali', 68, 52, 'But it is nothing less than a Message to all the worlds.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 68, 1, 'Noon; walqalami wa maa yasturoon'),
  ('en.transliteration', 68, 2, 'Maa anta bini\'mati Rabbika bimajnoon'),
  ('en.transliteration', 68, 3, 'Wa inna laka la ajran ghaira mamnoon'),
  ('en.transliteration', 68, 4, 'Wa innaka la\'alaa khuluqin \'azeem'),
  ('en.transliteration', 68, 5, 'Fasatubsiru wa yubsiroon'),
  ('en.transliteration', 68, 6, 'Bi ayyikumul maftoon'),
  ('en.transliteration', 68, 7, 'Innaa Rabbaka Huwa a\'lamu biman dalla \'an sabeelihee wa Huwa a\'lamu bilmuhtadeen'),
  ('en.transliteration', 68, 8, 'Falaa tuti\'il mukazzibeen'),
  ('en.transliteration', 68, 9, 'Waddoo law tudhinu fa-yudhinoon'),
  ('en.transliteration', 68, 10, 'Wa laa tuti\' kulla hallaa fim maheen'),
  ('en.transliteration', 68, 11, 'Hammaazim mash shaaa\'im binameem'),
  ('en.transliteration', 68, 12, 'Mannaa\'il lilkhairi mu\'tadin aseem'),
  ('en.transliteration', 68, 13, '\'Utullim ba\'da zaalika zaneem'),
  ('en.transliteration', 68, 14, 'An kaana zaa maalinw-wa baneen'),
  ('en.transliteration', 68, 15, 'Izaa tutlaa \'alaihi aayaatunaa qaala asaateerul awwaleen'),
  ('en.transliteration', 68, 16, 'Sanasimuhoo \'alal khurtoom'),
  ('en.transliteration', 68, 17, 'Innaa balawnaahum kamaa balawnaaa As-haabal jannati iz \'aqsamoo la-yasri munnahaa musbiheen'),
  ('en.transliteration', 68, 18, 'Wa laa yastasnoon'),
  ('en.transliteration', 68, 19, 'Fataafa \'alaihaa taaa\'i fum mir rabbika wa hum naaa\'imoon'),
  ('en.transliteration', 68, 20, 'Fa asbahat kassareem'),
  ('en.transliteration', 68, 21, 'Fatanaadaw musbiheen'),
  ('en.transliteration', 68, 22, 'Anighdoo \'alaa harsikum in kuntum saarimeen'),
  ('en.transliteration', 68, 23, 'Fantalaqoo wa hum yatakhaafatoon'),
  ('en.transliteration', 68, 24, 'Al laa yadkhulannahal yawma \'alaikum miskeen'),
  ('en.transliteration', 68, 25, 'Wa ghadaw \'alaa hardin qaadireen'),
  ('en.transliteration', 68, 26, 'Falammaa ra awhaa qaalooo innaa ladaaalloon'),
  ('en.transliteration', 68, 27, 'Bal nahnu mahroomoon'),
  ('en.transliteration', 68, 28, 'Qaala awsatuhum alam aqul lakum law laa tusabbihoon'),
  ('en.transliteration', 68, 29, 'Qaaloo subhaana rabbinaaa innaa kunnaa zaalimeen'),
  ('en.transliteration', 68, 30, 'Fa aqbala ba\'duhum \'alaa ba\'diny yatalaawamoon'),
  ('en.transliteration', 68, 31, 'Qaaloo yaa wailanaaa innaa kunnaa taagheen'),
  ('en.transliteration', 68, 32, '\'Asaa rabbunaaa any yubdilanaa khairam minhaaa innaaa ilaa rabbinaa raaghiboon'),
  ('en.transliteration', 68, 33, 'Kazaalikal azaab, wa la\'azaabul aakhirati akbar; law kaanoo ya\'lamoon'),
  ('en.transliteration', 68, 34, 'Inna lilmuttaqeena \'inda rabbihim jannaatin na\'eem'),
  ('en.transliteration', 68, 35, 'Afanaj\'alul muslimeena kalmujrimeen'),
  ('en.transliteration', 68, 36, 'Maa lakum kaifa tahhkumoon'),
  ('en.transliteration', 68, 37, 'Am lakum kitaabun feehi tadrusoon'),
  ('en.transliteration', 68, 38, 'Inna lakum feehi lamaa takhaiyaroon'),
  ('en.transliteration', 68, 39, 'Am lakum aymaanun \'alainaa baalighatun ilaa yawmil qiyaamati inna lakum lamaa tahkumoon'),
  ('en.transliteration', 68, 40, 'Salhum ayyuhum bizaa lika za\'eem'),
  ('en.transliteration', 68, 41, 'Am lahum shurakaaa\'u falyaatoo bishurakaaa \'ihim in kaanoo saadiqeen'),
  ('en.transliteration', 68, 42, 'Yawma yukshafu \'am saaqinw wa yud\'awna ilas sujoodi falaa yastatee\'oon'),
  ('en.transliteration', 68, 43, 'Khaashi\'atan absaaruhum tarhaquhum zillatunw wa qad kaanoo yud\'awna ilassujoodi wa hum saalimoon'),
  ('en.transliteration', 68, 44, 'Fazarnee wa many yukazzibu bihaazal hadeesi sanastad rijuhum min haisu laa ya\'lamoon'),
  ('en.transliteration', 68, 45, 'Wa umlee lahum; inna kaidee mateen'),
  ('en.transliteration', 68, 46, 'Am tas\'aluhum ajran fahum mim maghramim musqaloon'),
  ('en.transliteration', 68, 47, 'Am \'indahumul ghaibu fahum yaktuboon'),
  ('en.transliteration', 68, 48, 'Fasbir lihkmi rabbika wa laa takun kasaahibil boot; iz naadaa wa huwa makzoom'),
  ('en.transliteration', 68, 49, 'Law laaa an tadaara kahoo ni\'matum mir rabbihee lanubiza bil\'araaa\'i wa huwa mazmoom'),
  ('en.transliteration', 68, 50, 'Fajtabaahu rabbuhoo faja\'alahoo minas saaliheen'),
  ('en.transliteration', 68, 51, 'Wa iny-yakaadul lazeena kafaroo la-yuzliqoonaka biabsaarihim lammaa saml\'uz-Zikra wa yaqooloona innahoo lamajnoon'),
  ('en.transliteration', 68, 52, 'Wa maa huwa illaa zikrul lil\'aalameen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 68, 1, 'نۤ قلم کی قسم ہے اور اس کی جو اس سے لکھتے ہیں'),
  ('ur.ahmedali', 68, 2, 'آپ الله کے فضل سے دیوانہ نہیں ہیں'),
  ('ur.ahmedali', 68, 3, 'اور آپ کے لیے تو بے شمار اجر ہے'),
  ('ur.ahmedali', 68, 4, 'اور بے شک آپ تو بڑے ہی خوش خلق ہیں'),
  ('ur.ahmedali', 68, 5, 'پس عنقریب آپ بھی دیکھ لیں گے اور وہ بھی دیکھ لیں گے'),
  ('ur.ahmedali', 68, 6, 'کہ تم میں سے کون دیوانہ ہے'),
  ('ur.ahmedali', 68, 7, 'بے شک آپ کا رب ہی خوب جانتا ہے کہ کون اس کی راہ سے بہکا ہے اور وہ ہدایت پانے والوں کو بھی خوب جانتا ہے'),
  ('ur.ahmedali', 68, 8, 'پس آپ جھٹلانےوالوں کا کہا نہ مانیں'),
  ('ur.ahmedali', 68, 9, 'وہ تو چاہتے ہیں کہ کہیں آپ نرمی کریں تو وہ بھی نرمی کریں'),
  ('ur.ahmedali', 68, 10, 'اور ہر قسمیں کھانے والے ذلیل کا کہا نہ مان'),
  ('ur.ahmedali', 68, 11, 'جو طعنے دینے والا چغلی کھانے والا ہے'),
  ('ur.ahmedali', 68, 12, 'نیکی سے روکنے والا حد سے بڑھاہوا گناہگار ہے'),
  ('ur.ahmedali', 68, 13, 'بڑا اجڈ اس کے بعد بد اصل بھی ہے'),
  ('ur.ahmedali', 68, 14, 'اس لئے کہ وہ مال اور اولاد والا ہے'),
  ('ur.ahmedali', 68, 15, 'جب اس پر ہماری آیتیں پڑھی جاتی ہیں تو کہتا ہے پہلوں کی کہانیاں ہیں'),
  ('ur.ahmedali', 68, 16, 'عنقریب ہم اس کی ناک پر داغ لگائیں گے'),
  ('ur.ahmedali', 68, 17, 'بے شک ہم نے ان کو آزمایا ہے جیسا کہ ہم نے باغ والوں کو آزمایا تھا جب انہوں نے قسم کھائی تھی کہ وہ ضرور صبح ہوتے ہی اس کا پھل توڑ لیں گے'),
  ('ur.ahmedali', 68, 18, 'اور انشاالله بھی نہ کہا تھا'),
  ('ur.ahmedali', 68, 19, 'پھر تو اس پر رات ہی میں آپ کے رب کی طرف سے ایک جھونکا چل گیا درآنحالیکہ وہ سونے والے تھے'),
  ('ur.ahmedali', 68, 20, 'پھر وہ کٹی ہوئی کھیتی کی طرح ہو گیا'),
  ('ur.ahmedali', 68, 21, 'پھر وہ صبح کو پکارنے لگے'),
  ('ur.ahmedali', 68, 22, 'کہ اپنے کھیت پر سویرے چلو اگر تم نے پھل توڑنا ہے'),
  ('ur.ahmedali', 68, 23, 'پھر وہ آپس میں چپکے چپکے یہ کہتے ہوئے چلے'),
  ('ur.ahmedali', 68, 24, 'کہ تمہارے باغ میں آج کوئی محتاج نہ آنے پائے'),
  ('ur.ahmedali', 68, 25, 'اور وہ سویرے ہی بڑے اہتمام سے پھل توڑنے کی قدرت کا خیال کر کے چل پڑے'),
  ('ur.ahmedali', 68, 26, 'پس جب انہوں نے اسے دیکھا تو کہنے لگےکہ ہم تو راہ بھول گئے ہیں'),
  ('ur.ahmedali', 68, 27, 'بلکہ ہم تو بدنصیب ہیں'),
  ('ur.ahmedali', 68, 28, 'پھر ان میں سے اچھے آدمی نے کہا کیامیں نے تمہیں نہیں کہا تھا کہ تم کس لیے تسبیح نہیں کرتے'),
  ('ur.ahmedali', 68, 29, 'انہوں نے کہا ہمارا رب پاک ہے بے شک ہم ظالم تھے'),
  ('ur.ahmedali', 68, 30, 'پھر ایک دوسرے کی طرف متوجہ ہو کر آپس میں ملامت کرنے لگے'),
  ('ur.ahmedali', 68, 31, 'انہوں نے کہا ہائے افسوس بے شک ہم سرکش تھے'),
  ('ur.ahmedali', 68, 32, 'شاید ہمارا رب ہمارے لیے اس سے بہتر باغ بدل دے بے شک ہم اپنے رب کی طرف رجوع کرنے والے ہیں'),
  ('ur.ahmedali', 68, 33, 'عذاب یونہی ہوا کرتا ہے اور البتہ آخرت کا عذاب تو کہیں بڑھ کر ہے کاش وہ جانتے'),
  ('ur.ahmedali', 68, 34, 'بے شک پرہیزگاروں کے لیے ان کے رب کے ہاں نعمت کے باغ ہیں'),
  ('ur.ahmedali', 68, 35, 'پس کیا ہم فرمانبرداروں کو مجرموں کی طرح کر دیں گے'),
  ('ur.ahmedali', 68, 36, 'تمہیں کیا ہوگیا کیسا فیصلہ کر رہے ہو'),
  ('ur.ahmedali', 68, 37, 'کیا تمہارے پاس کوئی کتاب ہے جس میں تم پڑھتے ہو'),
  ('ur.ahmedali', 68, 38, 'کہ بے شک تمہیں آخرت میں ملے گا جو تم پسند کرتے ہو'),
  ('ur.ahmedali', 68, 39, 'کیا تمہارے لیے ہم نے قسمیں کھا لی ہیں جو قیامت تک چلی جائيں گی کہ بے شک تمہیں وہی ملے گا جو تم حکم کرو گے'),
  ('ur.ahmedali', 68, 40, 'ان سے پوچھیئے کون سا ان میں اس بات کا ذمہ دار ہے'),
  ('ur.ahmedali', 68, 41, 'کیا ان کے معبود ہیں پھر اپنے معبودوں کو لے آئيں اگر وہ سچے ہیں'),
  ('ur.ahmedali', 68, 42, 'جس دن پنڈلی کھولی جائے گی اور وہ سجدہ کرنے کو بلائے جائیں گے تو وہ نہ کر سکیں گے'),
  ('ur.ahmedali', 68, 43, 'ان کی آنکھیں جھکی ہوں گی ان پر ذلت چھا رہی ہو گی اوروہ پہلے (دنیا میں) سجدہ کے لیے بلائے جاتے تھے حالانکہ وہ صحیح سالم ہوتے تھے'),
  ('ur.ahmedali', 68, 44, 'پس مجھے اور اس کلام کے جھٹلانے والوں کو چھوڑ دو ہم انہیں بتدریج (جہنم کی طرف) لے جائے گے اس طور پر کہ انہیں خبر بھی نہیں ہو گی'),
  ('ur.ahmedali', 68, 45, 'اور ہم انکو ڈھیل دیتے ہیں بے شک ہماری تدبیر زبردست ہے'),
  ('ur.ahmedali', 68, 46, 'کیا آپ ان سے کچھ اجرت مانگتے ہیں کہ جس کا تاوان کا ان پر بوجھ پڑ رہا ہے'),
  ('ur.ahmedali', 68, 47, 'یا ان کے پاس غیب کی خبر ہے کہ وہ اسے لکھ لیتے ہیں'),
  ('ur.ahmedali', 68, 48, 'پھر آپ اپنے رب کے حکم کا انتظار کریں اور مچھلی والے جیسے نہ ہوجائیں جب کہ اس نے اپنے رب کو پکارا اور وہ بہت ہی غمگین تھا'),
  ('ur.ahmedali', 68, 49, 'اگر اس کے رب کی رحمت اسے نہ سنبھال لیتی تو وہ برے حال سے چٹیل میدان میں پھینکا جاتا'),
  ('ur.ahmedali', 68, 50, 'پس اسے اس کے رب نے نوازا پھر اسے نیک بختو ں میں کر دیا'),
  ('ur.ahmedali', 68, 51, 'اور بالکل قریب تھا کہ کافر آپ کو اپنی تیز نگاہوں سے پھسلا دیں جب کہ انہوں نے قرآن سنا اور کہتے ہیں کہ یہ تو دیوانہ ہے'),
  ('ur.ahmedali', 68, 52, 'اور حالانکہ یہ قرآن تمام دنیا کے لیے صرف نصیحت ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 68, 1, 'Nun; kalem ve onunla yazılanlara and olsun ki, sen Rabbinin nimetine uğramış bir kimsesin, deli (cinlenmiş) değilsin.'),
  ('tr.diyanet', 68, 2, 'Nun; kalem ve onunla yazılanlara and olsun ki, sen Rabbinin nimetine uğramış bir kimsesin, deli (cinlenmiş) değilsin.'),
  ('tr.diyanet', 68, 3, 'Doğrusu sana kesintisiz bir ecir vardır.'),
  ('tr.diyanet', 68, 4, 'Şüphesiz sen büyük bir ahlaka sahipsindir.'),
  ('tr.diyanet', 68, 5, 'Hanginizin aklından zoru olduğunu yakında sen de göreceksin, onlar da görecekler.'),
  ('tr.diyanet', 68, 6, 'Hanginizin aklından zoru olduğunu yakında sen de göreceksin, onlar da görecekler.'),
  ('tr.diyanet', 68, 7, 'Doğrusu senin Rabbin, yolundan sapıtanları çok iyi bilir; O, doğru yolda olanları da çok iyi bilir.'),
  ('tr.diyanet', 68, 8, 'Bundan böyle, yalanlayanlara itaat etme;'),
  ('tr.diyanet', 68, 9, '(Onlar sana indirilen ayetlerden beğenmediklerini bırakman suretiyle senin) kendilerine yumuşak davranmanı isterler; böyle yapsan, onlar da seni över, yumuşak davranırlar.'),
  ('tr.diyanet', 68, 10, 'Diliyle iğneleyen, kovuculuk eden, iyiliği daima önleyen, aşırı giden, suç işleyen, çok yemin eden alçak zorbaya, bütün bunlar dışında bir de soysuzlukla damgalanmış kimseye, mal ve oğulları vardır diye aldırış etmeyesin.'),
  ('tr.diyanet', 68, 11, 'Diliyle iğneleyen, kovuculuk eden, iyiliği daima önleyen, aşırı giden, suç işleyen, çok yemin eden alçak zorbaya, bütün bunlar dışında bir de soysuzlukla damgalanmış kimseye, mal ve oğulları vardır diye aldırış etmeyesin.'),
  ('tr.diyanet', 68, 12, 'Diliyle iğneleyen, kovuculuk eden, iyiliği daima önleyen, aşırı giden, suç işleyen, çok yemin eden alçak zorbaya, bütün bunlar dışında bir de soysuzlukla damgalanmış kimseye, mal ve oğulları vardır diye aldırış etmeyesin.'),
  ('tr.diyanet', 68, 13, 'Diliyle iğneleyen, kovuculuk eden, iyiliği daima önleyen, aşırı giden, suç işleyen, çok yemin eden alçak zorbaya, bütün bunlar dışında bir de soysuzlukla damgalanmış kimseye, mal ve oğulları vardır diye aldırış etmeyesin.'),
  ('tr.diyanet', 68, 14, 'Diliyle iğneleyen, kovuculuk eden, iyiliği daima önleyen, aşırı giden, suç işleyen, çok yemin eden alçak zorbaya, bütün bunlar dışında bir de soysuzlukla damgalanmış kimseye, mal ve oğulları vardır diye aldırış etmeyesin.'),
  ('tr.diyanet', 68, 15, 'Ayetlerimiz ona okunduğu zaman: "Öncekilerin masalları" der.'),
  ('tr.diyanet', 68, 16, 'Onun havada olan burnunu yakında yere sürteceğiz.'),
  ('tr.diyanet', 68, 17, 'Biz bunları, vaktiyle bahçe sahiplerini denediğimiz gibi denedik. Sahipleri daha sabah olmadan, bahçeyi devşireceklerine bir istisna payı bırakmaksızın yemin etmişlerdi.'),
  ('tr.diyanet', 68, 18, 'Biz bunları, vaktiyle bahçe sahiplerini denediğimiz gibi denedik. Sahipleri daha sabah olmadan, bahçeyi devşireceklerine bir istisna payı bırakmaksızın yemin etmişlerdi.'),
  ('tr.diyanet', 68, 19, 'Ama onlar daha uykudayken Rabbinin katından gönderilen bir salgın o bahçeyi sarıvermişti de bahçe kapkara kesilmişti.'),
  ('tr.diyanet', 68, 20, 'Ama onlar daha uykudayken Rabbinin katından gönderilen bir salgın o bahçeyi sarıvermişti de bahçe kapkara kesilmişti.'),
  ('tr.diyanet', 68, 21, 'Sabah erken: "Ürünlerinizi devşirecekseniz erken çıkın" diye birbirlerine seslendiler.'),
  ('tr.diyanet', 68, 22, 'Sabah erken: "Ürünlerinizi devşirecekseniz erken çıkın" diye birbirlerine seslendiler.'),
  ('tr.diyanet', 68, 23, '"Bugün orada, hiçbir düşkün kimse yanımıza sokulmasın" diye gizli gizli konuşarak yürüyorlardı.'),
  ('tr.diyanet', 68, 24, '"Bugün orada, hiçbir düşkün kimse yanımıza sokulmasın" diye gizli gizli konuşarak yürüyorlardı.'),
  ('tr.diyanet', 68, 25, 'Yoksullara yardım etmeye güçleri yeterken böyle konuşarak erkenden gittiler.'),
  ('tr.diyanet', 68, 26, 'Bahçeyi gördüklerinde: "Herhalde yolumuzu şaşırmış olacağız; belki de biz yoksun bırakıldık" dediler.'),
  ('tr.diyanet', 68, 27, 'Bahçeyi gördüklerinde: "Herhalde yolumuzu şaşırmış olacağız; belki de biz yoksun bırakıldık" dediler.'),
  ('tr.diyanet', 68, 28, 'Ortancaları: "Ben size Allah\'ı anmanız gerekmez mi, dememiş miydim?" dedi.'),
  ('tr.diyanet', 68, 29, '"Rabbimizi tenzih ederiz; doğrusu biz yazık etmiştik" dediler.'),
  ('tr.diyanet', 68, 30, 'Birbirlerini yermeye başladılar.'),
  ('tr.diyanet', 68, 31, 'Sonra şöyle dediler: "Yazıklar olsun bize; doğrusu azgınlık edenlerdendik."'),
  ('tr.diyanet', 68, 32, '"Belki Rabbimiz bize bundan daha iyisini verir; doğrusu artık, Rabbimizden dilemekteyiz."'),
  ('tr.diyanet', 68, 33, 'İşte azap böyledir; ama ahiret azabı daha büyüktür; keşke bilseler!'),
  ('tr.diyanet', 68, 34, 'Allah\'a karşı gelmekten sakınanlara, Rableri katında nimet cennetleri vardır.'),
  ('tr.diyanet', 68, 35, 'Kendilerini Allah\'a vermiş olanları hiç suçlular gibi tutar mıyız?'),
  ('tr.diyanet', 68, 36, 'Ne oluyorsunuz? Ne biçim hükmediyorsunuz?'),
  ('tr.diyanet', 68, 37, 'Yoksa okuduğunuz bir kitabınız mı var?'),
  ('tr.diyanet', 68, 38, 'Seçtikleriniz herhalde orada olacaktır.'),
  ('tr.diyanet', 68, 39, 'Yoksa aleyhimizde, kıyamet gününe kadar süregidecek ahidleriniz mi var ki, kendinize hükmettikleriniz sizin olacaktır?'),
  ('tr.diyanet', 68, 40, 'Sor onlara: "Bunu kim üzerine alır?"'),
  ('tr.diyanet', 68, 41, 'Yoksa onların ortakları mı vardır? Doğru sözlü iseler ortaklarını getirsinler.'),
  ('tr.diyanet', 68, 42, 'O gün işin dehşetinden baldırlar açılır; gözleri dönmüş olarak yüzlerini zillet bürür; secdeye çağırılırlar ama buna güçleri yetmez. Oysa, kendileri sapasağlam oldukları zaman secdeye çağırılmışlardı.'),
  ('tr.diyanet', 68, 43, 'O gün işin dehşetinden baldırlar açılır; gözleri dönmüş olarak yüzlerini zillet bürür; secdeye çağırılırlar ama buna güçleri yetmez. Oysa, kendileri sapasağlam oldukları zaman secdeye çağırılmışlardı.'),
  ('tr.diyanet', 68, 44, 'Kuran\'ı yalanlayanları Bana bırak; Biz onları bilmedikleri yerden yavaş yavaş azaba yaklaştıracağız.'),
  ('tr.diyanet', 68, 45, 'Onlara mehil veriyorum; doğrusu Benim tuzağım sağlamdır.'),
  ('tr.diyanet', 68, 46, 'Yoksa, sen onlardan ücret istiyorsun da, ağır bir borç altında mı kalıyorlar? Elbette hayır.'),
  ('tr.diyanet', 68, 47, 'Yoksa, gaybın bilgisi kendilerinin katında da onlar mı yazıyorlar?'),
  ('tr.diyanet', 68, 48, 'Sen Rabbinin hükmüne kadar sabret; balık sahibi (Yunus) gibi olma, o, pek üzgün olarak Rabbine seslenmişti.'),
  ('tr.diyanet', 68, 49, 'Rabbinin katından ona bir nimet ulaşmasaydı, kınanmış olarak sahile atılacaktı.'),
  ('tr.diyanet', 68, 50, 'Rabbi onu seçip iyilerden kıldı. Doğrusu inkar edenler, Kuran\'ı dinlediklerinde nerdeyse seni gözleriyle yıkıp devireceklerdi. "O delidir" diyorlardı.'),
  ('tr.diyanet', 68, 51, 'Rabbi onu seçip iyilerden kıldı. Doğrusu inkar edenler, Kuran\'ı dinlediklerinde nerdeyse seni gözleriyle yıkıp devireceklerdi. "O delidir" diyorlardı.'),
  ('tr.diyanet', 68, 52, 'Oysa Kuran, alemler için bir öğütten başka bir şey değildir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 68, 1, 'Nun, demi kalam dan apa yang mereka tulis,'),
  ('id.indonesian', 68, 2, 'berkat nikmat Tuhanmu kamu (Muhammad) sekali-kali bukan orang gila.'),
  ('id.indonesian', 68, 3, 'Dan sesungguhnya bagi kamu benar-benar pahala yang besar yang tidak putus-putusnya.'),
  ('id.indonesian', 68, 4, 'Dan sesungguhnya kamu benar-benar berbudi pekerti yang agung.'),
  ('id.indonesian', 68, 5, 'Maka kelak kamu akan melihat dan mereka (orang-orang kafir)pun akan melihat,'),
  ('id.indonesian', 68, 6, 'siapa di antara kamu yang gila.'),
  ('id.indonesian', 68, 7, 'Sesungguhnya Tuhanmu, Dialah Yang Paling Mengetahui siapa yang sesat dari jalan-Nya; dan Dialah Yang Paling Mengetahui orang-orang yang mendapat petunjuk.'),
  ('id.indonesian', 68, 8, 'Maka janganlah kamu ikuti orang-orang yang mendustakan (ayat-ayat Allah).'),
  ('id.indonesian', 68, 9, 'Maka mereka menginginkan supaya kamu bersikap lunak lalu mereka bersikap lunak (pula kepadamu).'),
  ('id.indonesian', 68, 10, 'Dan janganlah kamu ikuti setiap orang yang banyak bersumpah lagi hina,'),
  ('id.indonesian', 68, 11, 'yang banyak mencela, yang kian ke mari menghambur fitnah,'),
  ('id.indonesian', 68, 12, 'yang banyak menghalangi perbuatan baik, yang melampaui batas lagi banyak dosa,'),
  ('id.indonesian', 68, 13, 'yang kaku kasar, selain dari itu, yang terkenal kejahatannya,'),
  ('id.indonesian', 68, 14, 'karena dia mempunyai (banyak) harta dan anak.'),
  ('id.indonesian', 68, 15, 'Apabila dibacakan kepadanya ayat-ayat Kami, ia berkata: "(Ini adalah) dongeng-dongengan orang-orang dahulu kala".'),
  ('id.indonesian', 68, 16, 'Kelak akan Kami beri tanda dia di belalai(nya).'),
  ('id.indonesian', 68, 17, 'Sesungguhnya Kami telah mencobai mereka (musyrikin Mekah) sebagaimana Kami telah mencobai pemilik-pemilik kebun, ketika mereka bersumpah bahwa mereka sungguh-sungguh akanmemetik (hasil)nya di pagi hari,'),
  ('id.indonesian', 68, 18, 'dan mereka tidak menyisihkan (hak fakir miskin),'),
  ('id.indonesian', 68, 19, 'lalu kebun itu diliputi malapetaka (yang datang) dari Tuhanmu ketika mereka sedang tidur,'),
  ('id.indonesian', 68, 20, 'maka jadilah kebun itu hitam seperti malam yang gelap gulita.'),
  ('id.indonesian', 68, 21, 'lalu mereka panggil memanggil di pagi hari:'),
  ('id.indonesian', 68, 22, '"Pergilah diwaktu pagi (ini) ke kebunmu jika kamu hendak memetik buahnya".'),
  ('id.indonesian', 68, 23, 'Maka pergilah mereka saling berbisik-bisik.'),
  ('id.indonesian', 68, 24, '"Pada hari ini janganlah ada seorang miskinpun masuk ke dalam kebunmu".'),
  ('id.indonesian', 68, 25, 'Dan berangkatlah mereka di pagi hari dengan niat menghalangi (orang-orang miskin) padahal mereka (menolongnya).'),
  ('id.indonesian', 68, 26, 'Tatkala mereka melihat kebun itu, mereka berkata: "Sesungguhnya kita benar-benar orang-orang yang sesat (jalan),'),
  ('id.indonesian', 68, 27, 'bahkan kita dihalangi (dari memperoleh hasilnya)".'),
  ('id.indonesian', 68, 28, 'Berkatalah seorang yang paling baik pikirannya di antara mereka: "Bukankah aku telah mengatakan kepadamu, hendaklah kamu bertasbih (kepada Tuhanmu)?"'),
  ('id.indonesian', 68, 29, 'Mereka mengucapkan: "Maha Suci Tuhan kami, sesungguhnya kami adalah orang-orang yang zalim".'),
  ('id.indonesian', 68, 30, 'Lalu sebahagian mereka menghadapi sebahagian yang lain seraya cela mencela.'),
  ('id.indonesian', 68, 31, 'Mereka berkata: "Aduhai celakalah kita; sesungguhnya kita ini adalah orang-orang yang melampaui batas".'),
  ('id.indonesian', 68, 32, 'Mudah-mudahan Tuhan kita memberikan ganti kepada kita dengan (kebun) yang lebih baik daripada itu; sesungguhnya kita mengharapkan ampunan dari Tuhan kita.'),
  ('id.indonesian', 68, 33, 'Seperti itulah azab (dunia). Dan sesungguhnya azab akhirat lebih besar jika mereka mengetahui.'),
  ('id.indonesian', 68, 34, 'Sesungguhnya bagi orang-orang yang bertakwa (disediakan) surga-surga yang penuh kenikmatan di sisi Tuhannya.'),
  ('id.indonesian', 68, 35, 'Maka apakah patut Kami menjadikan orang-orang Islam itu sama dengan orang-orang yang berdosa (orang kafir)?'),
  ('id.indonesian', 68, 36, 'Atau adakah kamu (berbuat demikian): bagaimanakah kamu mengambil keputusan?'),
  ('id.indonesian', 68, 37, 'Atau adakah kamu mempunyai sebuah kitab (yang diturunkan Allah) yang kamu membacanya?,'),
  ('id.indonesian', 68, 38, 'bahwa di dalamnya kamu benar-benar boleh memilih apa yang kamu sukai untukmu.'),
  ('id.indonesian', 68, 39, 'Atau apakah kamu memperoleh janji yang diperkuat dengan sumpah dari Kami, yang tetap berlaku sampai hari kiamat; sesungguhnya kamu benar-benar dapat mengambil keputusan (sekehendakmu)?'),
  ('id.indonesian', 68, 40, 'Tanyakanlah kepada mereka: "Siapakah di antara mereka yang bertanggung jawab terhadap keputusan yang diambil itu?"'),
  ('id.indonesian', 68, 41, 'Atau apakah mereka mempunyai sekutu-sekutu? Maka hendaklah mereka mendatangkan sekutu-sekutunya jika mereka adalah orang-orang yang benar.'),
  ('id.indonesian', 68, 42, 'Pada hari betis disingkapkan dan mereka dipanggil untuk bersujud; maka mereka tidak kuasa,'),
  ('id.indonesian', 68, 43, '(dalam keadaan) pandangan mereka tunduk ke bawah, lagi mereka diliputi kehinaan. Dan sesungguhnya mereka dahulu (di dunia) diseru untuk bersujud, dan mereka dalam keadaan sejahtera.'),
  ('id.indonesian', 68, 44, 'Maka serahkanlah (ya Muhammad) kepada-Ku (urusan) orang-orang yang mendustakan perkataan ini (Al Quran). Nanti Kami akan menarik mereka dengan berangsur-angsur (ke arah kebinasaan) dari arah yang tidak mereka ketahui,'),
  ('id.indonesian', 68, 45, 'dan Aku memberi tangguh kepada mereka. Sesungguhnya rencana-Ku amat tangguh.'),
  ('id.indonesian', 68, 46, 'Apakah kamu meminta upah kepada mereka, lalu mereka diberati dengan hutang?'),
  ('id.indonesian', 68, 47, 'Ataukah ada pada mereka ilmu tentang yang ghaib lalu mereka menulis (padanya apa yang mereka tetapkan)?'),
  ('id.indonesian', 68, 48, 'Maka bersabarlah kamu (hai Muhammad) terhadap ketetapan Tuhanmu, dan janganlah kamu seperti orang yang berada dalam (perut) ikan ketika ia berdoa sedang ia dalam keadaan marah (kepada kaumnya).'),
  ('id.indonesian', 68, 49, 'Kalau sekiranya ia tidak segera mendapat nikmat dari Tuhannya, benar-benar ia dicampakkan ke tanah tandus dalam keadaan tercela.'),
  ('id.indonesian', 68, 50, 'Lalu Tuhannya memilihnya dan menjadikannya termasuk orang-orang yang saleh.'),
  ('id.indonesian', 68, 51, 'Dan sesungguhnya orang-orang kafir itu benar-benar hampir menggelincirkan kamu dengan pandangan mereka, tatkala mereka mendengar Al Quran dan mereka berkata: "Sesungguhnya ia (Muhammad) benar-benar orang yang gila".'),
  ('id.indonesian', 68, 52, 'Dan Al Quran itu tidak lain hanyalah peringatan bagi seluruh umat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 69, 1, 'The Inevitable Reality -'),
  ('en.sahih', 69, 2, 'What is the Inevitable Reality?'),
  ('en.sahih', 69, 3, 'And what can make you know what is the Inevitable Reality?'),
  ('en.sahih', 69, 4, 'Thamud and \'Aad denied the Striking Calamity.'),
  ('en.sahih', 69, 5, 'So as for Thamud, they were destroyed by the overpowering [blast].'),
  ('en.sahih', 69, 6, 'And as for \'Aad, they were destroyed by a screaming, violent wind'),
  ('en.sahih', 69, 7, 'Which Allah imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees.'),
  ('en.sahih', 69, 8, 'Then do you see of them any remains?'),
  ('en.sahih', 69, 9, 'And there came Pharaoh and those before him and the overturned cities with sin.'),
  ('en.sahih', 69, 10, 'And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity].'),
  ('en.sahih', 69, 11, 'Indeed, when the water overflowed, We carried your ancestors in the sailing ship'),
  ('en.sahih', 69, 12, 'That We might make it for you a reminder and [that] a conscious ear would be conscious of it.'),
  ('en.sahih', 69, 13, 'Then when the Horn is blown with one blast'),
  ('en.sahih', 69, 14, 'And the earth and the mountains are lifted and leveled with one blow -'),
  ('en.sahih', 69, 15, 'Then on that Day, the Resurrection will occur,'),
  ('en.sahih', 69, 16, 'And the heaven will split [open], for that Day it is infirm.'),
  ('en.sahih', 69, 17, 'And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them].'),
  ('en.sahih', 69, 18, 'That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed.'),
  ('en.sahih', 69, 19, 'So as for he who is given his record in his right hand, he will say, "Here, read my record!'),
  ('en.sahih', 69, 20, 'Indeed, I was certain that I would be meeting my account."'),
  ('en.sahih', 69, 21, 'So he will be in a pleasant life -'),
  ('en.sahih', 69, 22, 'In an elevated garden,'),
  ('en.sahih', 69, 23, 'Its [fruit] to be picked hanging near.'),
  ('en.sahih', 69, 24, '[They will be told], "Eat and drink in satisfaction for what you put forth in the days past."'),
  ('en.sahih', 69, 25, 'But as for he who is given his record in his left hand, he will say, "Oh, I wish I had not been given my record'),
  ('en.sahih', 69, 26, 'And had not known what is my account.'),
  ('en.sahih', 69, 27, 'I wish my death had been the decisive one.'),
  ('en.sahih', 69, 28, 'My wealth has not availed me.'),
  ('en.sahih', 69, 29, 'Gone from me is my authority."'),
  ('en.sahih', 69, 30, '[Allah will say], "Seize him and shackle him.'),
  ('en.sahih', 69, 31, 'Then into Hellfire drive him.'),
  ('en.sahih', 69, 32, 'Then into a chain whose length is seventy cubits insert him."'),
  ('en.sahih', 69, 33, 'Indeed, he did not used to believe in Allah, the Most Great,'),
  ('en.sahih', 69, 34, 'Nor did he encourage the feeding of the poor.'),
  ('en.sahih', 69, 35, 'So there is not for him here this Day any devoted friend'),
  ('en.sahih', 69, 36, 'Nor any food except from the discharge of wounds;'),
  ('en.sahih', 69, 37, 'None will eat it except the sinners.'),
  ('en.sahih', 69, 38, 'So I swear by what you see'),
  ('en.sahih', 69, 39, 'And what you do not see'),
  ('en.sahih', 69, 40, '[That] indeed, the Qur\'an is the word of a noble Messenger.'),
  ('en.sahih', 69, 41, 'And it is not the word of a poet; little do you believe.'),
  ('en.sahih', 69, 42, 'Nor the word of a soothsayer; little do you remember.'),
  ('en.sahih', 69, 43, '[It is] a revelation from the Lord of the worlds.'),
  ('en.sahih', 69, 44, 'And if Muhammad had made up about Us some [false] sayings,'),
  ('en.sahih', 69, 45, 'We would have seized him by the right hand;'),
  ('en.sahih', 69, 46, 'Then We would have cut from him the aorta.'),
  ('en.sahih', 69, 47, 'And there is no one of you who could prevent [Us] from him.'),
  ('en.sahih', 69, 48, 'And indeed, the Qur\'an is a reminder for the righteous.'),
  ('en.sahih', 69, 49, 'And indeed, We know that among you are deniers.'),
  ('en.sahih', 69, 50, 'And indeed, it will be [a cause of] regret upon the disbelievers.'),
  ('en.sahih', 69, 51, 'And indeed, it is the truth of certainty.'),
  ('en.sahih', 69, 52, 'So exalt the name of your Lord, the Most Great.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 69, 1, 'সুনিশ্চিত বিষয়।'),
  ('bn.bengali', 69, 2, 'সুনিশ্চিত বিষয় কি?'),
  ('bn.bengali', 69, 3, 'আপনি কি কিছু জানেন, সেই সুনিশ্চিত বিষয় কি?'),
  ('bn.bengali', 69, 4, 'আদ ও সামুদ গোত্র মহাপ্রলয়কে মিথ্যা বলেছিল।'),
  ('bn.bengali', 69, 5, 'অতঃপর সমুদ গোত্রকে ধ্বংস করা হয়েছিল এক প্রলয়ংকর বিপর্যয় দ্বারা।'),
  ('bn.bengali', 69, 6, 'এবং আদ গোত্রকে ধ্বংস করা হয়েছিল এক প্রচন্ড ঝঞ্জাবায়ূ,'),
  ('bn.bengali', 69, 7, 'যা তিনি প্রবাহিত করেছিলেন তাদের উপর সাত রাত্রি ও আট দিবস পর্যন্ত অবিরাম। আপনি তাদেরকে দেখতেন যে, তারা অসার খর্জুর কান্ডের ন্যায় ভূপাতিত হয়ে রয়েছে।'),
  ('bn.bengali', 69, 8, 'আপনি তাদের কোন অস্তিত্ব দেখতে পান কি?'),
  ('bn.bengali', 69, 9, 'ফেরাউন, তাঁর পূর্ববর্তীরা এবং উল্টে যাওয়া বস্তিবাসীরা গুরুতর পাপ করেছিল।'),
  ('bn.bengali', 69, 10, 'তারা তাদের পালনকর্তার রসূলকে অমান্য করেছিল। ফলে তিনি তাদেরকে কঠোরহস্তে পাকড়াও করলেন।'),
  ('bn.bengali', 69, 11, 'যখন জলোচ্ছ্বাস হয়েছিল, তখন আমি তোমাদেরকে চলন্ত নৌযানে আরোহণ করিয়েছিলাম।'),
  ('bn.bengali', 69, 12, 'যাতে এ ঘটনা তোমাদের জন্যে স্মৃতির বিষয় এবং কান এটাকে উপদেশ গ্রহণের উপযোগী রূপে গ্রহণ করে।'),
  ('bn.bengali', 69, 13, 'যখন শিংগায় ফুৎকার দেয়া হবে-একটি মাত্র ফুৎকার'),
  ('bn.bengali', 69, 14, 'এবং পৃথিবী ও পর্বতমালা উত্তোলিত হবে ও চুর্ণ-বিচুর্ণ করে দেয়া হবে,'),
  ('bn.bengali', 69, 15, 'সেদিন কেয়ামত সংঘটিত হবে।'),
  ('bn.bengali', 69, 16, 'সেদিন আকাশ বিদীর্ণ হবে ও বিক্ষিপ্ত হবে।'),
  ('bn.bengali', 69, 17, 'এবং ফেরেশতাগণ আকাশের প্রান্তদেশে থাকবে ও আট জন ফেরেশতা আপনার পালনকর্তার আরশকে তাদের উর্ধ্বে বহন করবে।'),
  ('bn.bengali', 69, 18, 'সেদিন তোমাদেরকে উপস্থিত করা হবে। তোমাদের কোন কিছু গোপন থাকবে না।'),
  ('bn.bengali', 69, 19, 'অতঃপর যার আমলনামা ডান হাতে দেয়া হবে, সে বলবেঃ নাও, তোমরাও আমলনামা পড়ে দেখ।'),
  ('bn.bengali', 69, 20, 'আমি জানতাম যে, আমাকে হিসাবের সম্মুখীন হতে হবে।'),
  ('bn.bengali', 69, 21, 'অতঃপর সে সুখী জীবন-যাপন করবে,'),
  ('bn.bengali', 69, 22, 'সুউচ্চ জান্নাতে।'),
  ('bn.bengali', 69, 23, 'তার ফলসমূহ অবনমিত থাকবে।'),
  ('bn.bengali', 69, 24, 'বিগত দিনে তোমরা যা প্রেরণ করেছিলে, তার প্রতিদানে তোমরা খাও এবং পান কর তৃপ্তি সহকারে।'),
  ('bn.bengali', 69, 25, 'যার আমলনামা তার বাম হাতে দেয়া হবে, সে বলবেঃ হায় আমায় যদি আমার আমল নামা না দেয়া হতো।'),
  ('bn.bengali', 69, 26, 'আমি যদি না জানতাম আমার হিসাব!'),
  ('bn.bengali', 69, 27, 'হায়, আমার মৃত্যুই যদি শেষ হত।'),
  ('bn.bengali', 69, 28, 'আমার ধন-সম্পদ আমার কোন উপকারে আসল না।'),
  ('bn.bengali', 69, 29, 'আমার ক্ষমতাও বরবাদ হয়ে গেল।'),
  ('bn.bengali', 69, 30, 'ফেরেশতাদেরকে বলা হবেঃ ধর একে গলায় বেড়ি পড়িয়ে দাও,'),
  ('bn.bengali', 69, 31, 'অতঃপর নিক্ষেপ কর জাহান্নামে।'),
  ('bn.bengali', 69, 32, 'অতঃপর তাকে শৃঙ্খলিত কর সত্তর গজ দীর্ঘ এক শিকলে।'),
  ('bn.bengali', 69, 33, 'নিশ্চয় সে মহান আল্লাহতে বিশ্বাসী ছিল না।'),
  ('bn.bengali', 69, 34, 'এবং মিসকীনকে আহার্য দিতে উৎসাহিত করত না।'),
  ('bn.bengali', 69, 35, 'অতএব, আজকের দিন এখানে তার কোন সুহূদ নাই।'),
  ('bn.bengali', 69, 36, 'এবং কোন খাদ্য নাই, ক্ষত-নিঃসৃত পুঁজ ব্যতীত।'),
  ('bn.bengali', 69, 37, 'গোনাহগার ব্যতীত কেউ এটা খাবে না।'),
  ('bn.bengali', 69, 38, 'তোমরা যা দেখ, আমি তার শপথ করছি।'),
  ('bn.bengali', 69, 39, 'এবং যা তোমরা দেখ না, তার-'),
  ('bn.bengali', 69, 40, 'নিশ্চয়ই এই কোরআন একজন সম্মানিত রসূলের আনীত।'),
  ('bn.bengali', 69, 41, 'এবং এটা কোন কবির কালাম নয়; তোমরা কমই বিশ্বাস কর।'),
  ('bn.bengali', 69, 42, 'এবং এটা কোন অতীন্দ্রিয়বাদীর কথা নয়; তোমরা কমই অনুধাবন কর।'),
  ('bn.bengali', 69, 43, 'এটা বিশ্বপালনকর্তার কাছ থেকে অবতীর্ণ।'),
  ('bn.bengali', 69, 44, 'সে যদি আমার নামে কোন কথা রচনা করত,'),
  ('bn.bengali', 69, 45, 'তবে আমি তার দক্ষিণ হস্ত ধরে ফেলতাম,'),
  ('bn.bengali', 69, 46, 'অতঃপর কেটে দিতাম তার গ্রীবা।'),
  ('bn.bengali', 69, 47, 'তোমাদের কেউ তাকে রক্ষা করতে পারতে না।'),
  ('bn.bengali', 69, 48, 'এটা খোদাভীরুদের জন্যে অবশ্যই একটি উপদেশ।'),
  ('bn.bengali', 69, 49, 'আমি জানি যে, তোমাদের মধ্যে কেউ কেউ মিথ্যারোপ করবে।'),
  ('bn.bengali', 69, 50, 'নিশ্চয় এটা কাফেরদের জন্যে অনুতাপের কারণ।'),
  ('bn.bengali', 69, 51, 'নিশ্চয় এটা নিশ্চিত সত্য।'),
  ('bn.bengali', 69, 52, 'অতএব, আপনি আপনার মহান পালনকর্তার নামের পবিত্রতা বর্ননা করুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 69, 1, 'The Reality!'),
  ('en.pickthall', 69, 2, 'What is the Reality?'),
  ('en.pickthall', 69, 3, 'Ah, what will convey unto thee what the reality is!'),
  ('en.pickthall', 69, 4, '(The tribes of) Thamud and A\'ad disbelieved in the judgment to come.'),
  ('en.pickthall', 69, 5, 'As for Thamud, they were destroyed by the lightning.'),
  ('en.pickthall', 69, 6, 'And as for A\'ad, they were destroyed by a fierce roaring wind,'),
  ('en.pickthall', 69, 7, 'Which He imposed on them for seven long nights and eight long days so that thou mightest have seen men lying overthrown, as they were hollow trunks of palm-trees.'),
  ('en.pickthall', 69, 8, 'Canst thou (O Muhammad) see any remnant of them?'),
  ('en.pickthall', 69, 9, 'And Pharaoh and those before him, and the communities that were destroyed, brought error,'),
  ('en.pickthall', 69, 10, 'And they disobeyed the messenger of their Lord, therefor did He grip them with a tightening grip.'),
  ('en.pickthall', 69, 11, 'Lo! when the waters rose, We carried you upon the ship'),
  ('en.pickthall', 69, 12, 'That We might make it a memorial for you, and that remembering ears (that heard the story) might remember.'),
  ('en.pickthall', 69, 13, 'And when the trumpet shall sound one blast'),
  ('en.pickthall', 69, 14, 'And the earth with the mountains shall be lifted up and crushed with one crash,'),
  ('en.pickthall', 69, 15, 'Then, on that day will the Event befall.'),
  ('en.pickthall', 69, 16, 'And the heaven will split asunder, for that day it will be frail.'),
  ('en.pickthall', 69, 17, 'And the angels will be on the sides thereof, and eight will uphold the Throne of thy Lord that day, above them.'),
  ('en.pickthall', 69, 18, 'On that day ye will be exposed; not a secret of you will be hidden.'),
  ('en.pickthall', 69, 19, 'Then, as for him who is given his record in his right hand, he will say: Take, read my book!'),
  ('en.pickthall', 69, 20, 'Surely I knew that I should have to meet my reckoning.'),
  ('en.pickthall', 69, 21, 'Then he will be in blissful state'),
  ('en.pickthall', 69, 22, 'In a high garden'),
  ('en.pickthall', 69, 23, 'Whereof the clusters are in easy reach.'),
  ('en.pickthall', 69, 24, '(And it will be said unto those therein): Eat and drink at ease for that which ye sent on before you in past days.'),
  ('en.pickthall', 69, 25, 'But as for him who is given his record in his left hand, he will say: Oh, would that I had not been given my book'),
  ('en.pickthall', 69, 26, 'And knew not what my reckoning!'),
  ('en.pickthall', 69, 27, 'Oh, would that it had been death!'),
  ('en.pickthall', 69, 28, 'My wealth hath not availed me,'),
  ('en.pickthall', 69, 29, 'My power hath gone from me.'),
  ('en.pickthall', 69, 30, '(It will be said): Take him and fetter him'),
  ('en.pickthall', 69, 31, 'And then expose him to hell-fire'),
  ('en.pickthall', 69, 32, 'And then insert him in a chain whereof the length is seventy cubits.'),
  ('en.pickthall', 69, 33, 'Lo! He used not to believe in Allah the Tremendous,'),
  ('en.pickthall', 69, 34, 'And urged not on the feeding of the wretched.'),
  ('en.pickthall', 69, 35, 'Therefor hath he no lover here this day,'),
  ('en.pickthall', 69, 36, 'Nor any food save filth'),
  ('en.pickthall', 69, 37, 'Which none but sinners eat.'),
  ('en.pickthall', 69, 38, 'But nay! I swear by all that ye see'),
  ('en.pickthall', 69, 39, 'And all that ye see not'),
  ('en.pickthall', 69, 40, 'That it is indeed the speech of an illustrious messenger.'),
  ('en.pickthall', 69, 41, 'It is not poet\'s speech - little is it that ye believe!'),
  ('en.pickthall', 69, 42, 'Nor diviner\'s speech - little is it that ye remember!'),
  ('en.pickthall', 69, 43, 'It is a revelation from the Lord of the Worlds.'),
  ('en.pickthall', 69, 44, 'And if he had invented false sayings concerning Us,'),
  ('en.pickthall', 69, 45, 'We assuredly had taken him by the right hand'),
  ('en.pickthall', 69, 46, 'And then severed his life-artery,'),
  ('en.pickthall', 69, 47, 'And not one of you could have held Us off from him.'),
  ('en.pickthall', 69, 48, 'And lo! it is a warrant unto those who ward off (evil).'),
  ('en.pickthall', 69, 49, 'And lo! We know that some among you will deny (it).'),
  ('en.pickthall', 69, 50, 'And lo! it is indeed an anguish for the disbelievers.'),
  ('en.pickthall', 69, 51, 'And lo! it is absolute truth.'),
  ('en.pickthall', 69, 52, 'So glorify the name of thy Tremendous Lord.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 69, 1, 'The Sure Reality!'),
  ('en.yusufali', 69, 2, 'What is the Sure Reality?'),
  ('en.yusufali', 69, 3, 'And what will make thee realise what the Sure Reality is?'),
  ('en.yusufali', 69, 4, 'The Thamud and the \'Ad People (branded) as false the Stunning Calamity!'),
  ('en.yusufali', 69, 5, 'But the Thamud,- they were destroyed by a terrible Storm of thunder and lightning!'),
  ('en.yusufali', 69, 6, 'And the \'Ad, they were destroyed by a furious Wind, exceedingly violent;'),
  ('en.yusufali', 69, 7, 'He made it rage against them seven nights and eight days in succession: so that thou couldst see the (whole) people lying prostrate in its (path), as they had been roots of hollow palm-trees tumbled down!'),
  ('en.yusufali', 69, 8, 'Then seest thou any of them left surviving?'),
  ('en.yusufali', 69, 9, 'And Pharaoh, and those before him, and the Cities Overthrown, committed habitual Sin.'),
  ('en.yusufali', 69, 10, 'And disobeyed (each) the messenger of their Lord; so He punished them with an abundant Penalty.'),
  ('en.yusufali', 69, 11, 'We, when the water (of Noah\'s Flood) overflowed beyond its limits, carried you (mankind), in the floating (Ark),'),
  ('en.yusufali', 69, 12, 'That We might make it a Message unto you, and that ears (that should hear the tale and) retain its memory should bear its (lessons) in remembrance.'),
  ('en.yusufali', 69, 13, 'Then, when one blast is sounded on the Trumpet,'),
  ('en.yusufali', 69, 14, 'And the earth is moved, and its mountains, and they are crushed to powder at one stroke,-'),
  ('en.yusufali', 69, 15, 'On that Day shall the (Great) Event come to pass.'),
  ('en.yusufali', 69, 16, 'And the sky will be rent asunder, for it will that Day be flimsy,'),
  ('en.yusufali', 69, 17, 'And the angels will be on its sides, and eight will, that Day, bear the Throne of thy Lord above them.'),
  ('en.yusufali', 69, 18, 'That Day shall ye be brought to Judgment: not an act of yours that ye hide will be hidden.'),
  ('en.yusufali', 69, 19, 'Then he that will be given his Record in his right hand will say: "Ah here! Read ye my Record!'),
  ('en.yusufali', 69, 20, '"I did really understand that my Account would (One Day) reach me!"'),
  ('en.yusufali', 69, 21, 'And he will be in a life of Bliss,'),
  ('en.yusufali', 69, 22, 'In a Garden on high,'),
  ('en.yusufali', 69, 23, 'The Fruits whereof (will hang in bunches) low and near.'),
  ('en.yusufali', 69, 24, '"Eat ye and drink ye, with full satisfaction; because of the (good) that ye sent before you, in the days that are gone!"'),
  ('en.yusufali', 69, 25, 'And he that will be given his Record in his left hand, will say: "Ah! Would that my Record had not been given to me!'),
  ('en.yusufali', 69, 26, '"And that I had never realised how my account (stood)!'),
  ('en.yusufali', 69, 27, '"Ah! Would that (Death) had made an end of me!'),
  ('en.yusufali', 69, 28, '"Of no profit to me has been my wealth!'),
  ('en.yusufali', 69, 29, '"My power has perished from me!"...'),
  ('en.yusufali', 69, 30, '(The stern command will say): "Seize ye him, and bind ye him,'),
  ('en.yusufali', 69, 31, '"And burn ye him in the Blazing Fire.'),
  ('en.yusufali', 69, 32, '"Further, make him march in a chain, whereof the length is seventy cubits!'),
  ('en.yusufali', 69, 33, '"This was he that would not believe in Allah Most High.'),
  ('en.yusufali', 69, 34, '"And would not encourage the feeding of the indigent!'),
  ('en.yusufali', 69, 35, '"So no friend hath he here this Day.'),
  ('en.yusufali', 69, 36, '"Nor hath he any food except the corruption from the washing of wounds,'),
  ('en.yusufali', 69, 37, '"Which none do eat but those in sin."'),
  ('en.yusufali', 69, 38, 'So I do call to witness what ye see,'),
  ('en.yusufali', 69, 39, 'And what ye see not,'),
  ('en.yusufali', 69, 40, 'That this is verily the word of an honoured messenger;'),
  ('en.yusufali', 69, 41, 'It is not the word of a poet: little it is ye believe!'),
  ('en.yusufali', 69, 42, 'Nor is it the word of a soothsayer: little admonition it is ye receive.'),
  ('en.yusufali', 69, 43, '(This is) a Message sent down from the Lord of the Worlds.'),
  ('en.yusufali', 69, 44, 'And if the messenger were to invent any sayings in Our name,'),
  ('en.yusufali', 69, 45, 'We should certainly seize him by his right hand,'),
  ('en.yusufali', 69, 46, 'And We should certainly then cut off the artery of his heart:'),
  ('en.yusufali', 69, 47, 'Nor could any of you withhold him (from Our wrath).'),
  ('en.yusufali', 69, 48, 'But verily this is a Message for the Allah-fearing.'),
  ('en.yusufali', 69, 49, 'And We certainly know that there are amongst you those that reject (it).'),
  ('en.yusufali', 69, 50, 'But truly (Revelation) is a cause of sorrow for the Unbelievers.'),
  ('en.yusufali', 69, 51, 'But verily it is Truth of assured certainty.'),
  ('en.yusufali', 69, 52, 'So glorify the name of thy Lord Most High.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 69, 1, 'Al haaaqqah'),
  ('en.transliteration', 69, 2, 'Mal haaaqqah'),
  ('en.transliteration', 69, 3, 'Wa maaa adraaka mal haaaqqah'),
  ('en.transliteration', 69, 4, 'Kazzabat samoodu wa \'Aadum bil qaari\'ah'),
  ('en.transliteration', 69, 5, 'Fa-ammaa Samoodu fauhlikoo bittaaghiyah'),
  ('en.transliteration', 69, 6, 'Wa ammaa \'Aadun fa uhlikoo bireehin sarsarin \'aatiyah'),
  ('en.transliteration', 69, 7, 'Sakhkharahaa \'alaihim sab\'a la yaalinw wa samaaniyata ayyaamin husooman fataral qawma feehaa sar\'aa ka annahum a\'jaazu nakhlin khaawiyah'),
  ('en.transliteration', 69, 8, 'Fahal taraa lahum mim baaqiyah'),
  ('en.transliteration', 69, 9, 'Wa jaaa\'a Firawnu wa man qablahoo wal mu\'tafikaatu bilhaati\'ah'),
  ('en.transliteration', 69, 10, 'Fa\'ansaw Rasoola Rabbihim fa akhazahum akhzatar raabiyah'),
  ('en.transliteration', 69, 11, 'Innaa lammaa taghal maaa\'u hamalnaakum fil jaariyah'),
  ('en.transliteration', 69, 12, 'Linaj\'alahaa lakum tazki ratanw-wa ta\'iyahaa unzununw waa\'iyah'),
  ('en.transliteration', 69, 13, 'Fa izaa nufikha fis soori nafkhatunw waahidah'),
  ('en.transliteration', 69, 14, 'Wa humilatil ardu wal jibaalu fadukkataa dakkatanw waahidah'),
  ('en.transliteration', 69, 15, 'Fa yawma\'izinw waqa\'atil waaqi\'ah'),
  ('en.transliteration', 69, 16, 'Wanshaqqatis samaaa\'u fahiya yawma \'izinw-waahiyah'),
  ('en.transliteration', 69, 17, 'Wal malaku \'alaaa arjaaa\'ihaa; wa yahmilu \'Arsha Rabbika fawqahum yawma\'izin samaaniyah'),
  ('en.transliteration', 69, 18, 'Yawma\'izin tu\'radoona laa takhfaa min kum khaafiyah'),
  ('en.transliteration', 69, 19, 'Fa ammaa man ootiya kitaabahoo biyameenihee fa yaqoolu haaa\'umuq ra\'oo kitaabiyah'),
  ('en.transliteration', 69, 20, 'Innee zannantu annee mulaaqin hisaabiyah'),
  ('en.transliteration', 69, 21, 'Fahuwa fee \'eeshatir raadiyah'),
  ('en.transliteration', 69, 22, 'Fee jannnatin \'aaliyah'),
  ('en.transliteration', 69, 23, 'Qutoofuhaa daaniyah'),
  ('en.transliteration', 69, 24, 'Kuloo washraboo haneee\'am bimaaa aslaftum fil ayyaamil khaliyah'),
  ('en.transliteration', 69, 25, 'Wa ammaa man ootiya kitaabahoo bishimaalihee fa yaqoolu yaalaitanee lam oota kitaaabiyah'),
  ('en.transliteration', 69, 26, 'Wa lam adri maa hisaabiyah'),
  ('en.transliteration', 69, 27, 'Yaa laitahaa kaanatil qaadiyah'),
  ('en.transliteration', 69, 28, 'Maaa aghnaa \'annee maaliyah'),
  ('en.transliteration', 69, 29, 'Halaka \'annee sultaaniyah'),
  ('en.transliteration', 69, 30, 'Khuzoohu faghullooh'),
  ('en.transliteration', 69, 31, 'Summal Jaheema sallooh'),
  ('en.transliteration', 69, 32, 'Summa fee silsilatin zar\'uhaa sab\'oona ziraa\'an faslukooh'),
  ('en.transliteration', 69, 33, 'Innahoo kaana laa yu\'minubillaahil \'Azeem'),
  ('en.transliteration', 69, 34, 'wa laa yahuddu \'alaa ta\'aamil miskeen'),
  ('en.transliteration', 69, 35, 'Falaysa lahul yawma haahunaa hameem'),
  ('en.transliteration', 69, 36, 'Wa laa ta\'aamun illaa min ghisleen'),
  ('en.transliteration', 69, 37, 'Laa yaakuluhooo illal khati\'oon'),
  ('en.transliteration', 69, 38, 'Falaaa uqsimu bimaa tubsiroon'),
  ('en.transliteration', 69, 39, 'Wa maa laa tubsiroon'),
  ('en.transliteration', 69, 40, 'Innahoo laqawlu Rasoolin kareem'),
  ('en.transliteration', 69, 41, 'Wa ma huwa biqawli shaa\'ir; qaleelam maa tu\'minoon'),
  ('en.transliteration', 69, 42, 'Wa laa biqawli kaahin; qaleelam maa tazakkaroon'),
  ('en.transliteration', 69, 43, 'Tanzeelum mir rabbil \'aalameen'),
  ('en.transliteration', 69, 44, 'Wa law taqawwala \'alainaa ba\'dal aqaaweel'),
  ('en.transliteration', 69, 45, 'La-akhaznaa minhu bilyameen'),
  ('en.transliteration', 69, 46, 'Summa laqata\'naa minhul wateen'),
  ('en.transliteration', 69, 47, 'Famaa minkum min ahadin\'anhu haajizeen'),
  ('en.transliteration', 69, 48, 'Wa innahoo latazkiratul lilmuttaqeen'),
  ('en.transliteration', 69, 49, 'Wa inna lana\'lamu anna minkum mukazzibeen'),
  ('en.transliteration', 69, 50, 'Wa innahu lahasratun \'alal kaafireen'),
  ('en.transliteration', 69, 51, 'Wa innahoo lahaqqul yaqeen'),
  ('en.transliteration', 69, 52, 'Fasbbih bismi Rabbikal \'Azeem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 69, 1, 'قیامت'),
  ('ur.ahmedali', 69, 2, 'قیامت کیا چیز ہے'),
  ('ur.ahmedali', 69, 3, 'اور تمہیں کس چیز نے بتایا کہ قیامت کیا ہے'),
  ('ur.ahmedali', 69, 4, 'ثمود اور عاد نے قیامت کو جھٹلایا تھا'),
  ('ur.ahmedali', 69, 5, 'سو ثمود تو سخت ہیبت ناک چیخ سے ہلاک کیے گئے'),
  ('ur.ahmedali', 69, 6, 'اور لیکن قوم عاد سو وہ ایک سخت آندھی سے ہلاک کیے گئے'),
  ('ur.ahmedali', 69, 7, 'وہ ان پر سات راتیں اور آٹھ دن لگاتار چلتی رہی (اگر تو موجود ہوتا) اس قوم کو اس طرح گرا ہوا دیکھتا کہ گویا کہ گھری ہوئی کھجوروں کے تنے ہیں'),
  ('ur.ahmedali', 69, 8, 'سو کیا تمہیں ان کا کوئی بچا ہوا نظر آتا ہے'),
  ('ur.ahmedali', 69, 9, 'اور فرعون اس سے پہلے کے لوگ اور الٹی ہوئی بستیوں والے گناہ کے مرتکب ہوئے'),
  ('ur.ahmedali', 69, 10, 'پس انہوں نے اپنے رب کے رسول کی نافرمانی کی تو الله نے انہیں سخت پکڑ لیا'),
  ('ur.ahmedali', 69, 11, 'بے شک ہم نے جب پانی حد سے گزر گیا تھا تو تمہیں کشتی میں سوار کر لیا تھا'),
  ('ur.ahmedali', 69, 12, 'تاکہ ہم اسے تمہارے لیے ایک یادگار بنائیں اور اس کو کان یا د رکھنے والے یاد رکھیں'),
  ('ur.ahmedali', 69, 13, 'پھر جب صور میں پھونکا جائے گا ایک بار پھونکا جانا'),
  ('ur.ahmedali', 69, 14, 'اور زمین اور پہاڑ اٹھائے جائیں گے پس وہ دونوں ریزہ ریزہ کر دیئے جائیں گے'),
  ('ur.ahmedali', 69, 15, 'پس اس دن قیامت ہو گی'),
  ('ur.ahmedali', 69, 16, 'اور آسمان پھٹ جائے گا اوروہ اس دن بودا ہوگا'),
  ('ur.ahmedali', 69, 17, 'اور اس کے کنارے پر فرشتے ہوں گے اور عرشِ الہیٰ کو اپنے اوپر اس دن آٹھ فرشتے اٹھائیں گے'),
  ('ur.ahmedali', 69, 18, 'اس دن تم پیش کیے جاؤ گے تمہارا کوئی راز مخفی نہ رہے گا'),
  ('ur.ahmedali', 69, 19, 'جس کو اس کا اعمال نامہ اس کے داہنے ہاتھ میں دیا جائے گا سو وہ کہے گا لو میرا اعمال نامہ پڑھو'),
  ('ur.ahmedali', 69, 20, 'بے شک میں سمجھتا تھا کہ میں اپنا حساب دیکھوں گا'),
  ('ur.ahmedali', 69, 21, 'سووہ دل پسند عیش میں ہو گا'),
  ('ur.ahmedali', 69, 22, 'بلند بہشت میں'),
  ('ur.ahmedali', 69, 23, 'جس کے میوے جھکے ہوں گے'),
  ('ur.ahmedali', 69, 24, 'کھاؤ اور پیئو ان کاموں کے بدلے میں جو تم نے گزشتہ دنوں میں آگے بھیجے تھے'),
  ('ur.ahmedali', 69, 25, 'اور جس کا اعمال نامہ اس کے بائیں ہاتھ میں دیا گیا تو کہے گا اے کاش میرا اعمال نامہ نہ ملتا'),
  ('ur.ahmedali', 69, 26, 'اور میں نہ جانتا کہ میرا حساب کیا ہے'),
  ('ur.ahmedali', 69, 27, 'کاش وہ (موت) خاتمہ کرنے والی ہوتی'),
  ('ur.ahmedali', 69, 28, 'میرا مال میرے کچھ کام نہ آیا'),
  ('ur.ahmedali', 69, 29, 'مجھ سے میری حکومت بھی جاتی رہی'),
  ('ur.ahmedali', 69, 30, 'اسے پکڑو اسے طوق پہنا دو'),
  ('ur.ahmedali', 69, 31, 'پھر اسے دوزخ میں ڈال دو'),
  ('ur.ahmedali', 69, 32, 'پھر ایک زنجیر میں جس کا طول ستر گز ہے اسے جکڑ دو'),
  ('ur.ahmedali', 69, 33, 'بے شک وہ الله پر یقین نہیں رکھتا تھا جو عظمت والا ہے'),
  ('ur.ahmedali', 69, 34, 'اور نہ وہ مسکین کے کھانا کھلانے کی رغبت دیتا تھا'),
  ('ur.ahmedali', 69, 35, 'سو آج اس کا یہاں کوئی دوست نہیں'),
  ('ur.ahmedali', 69, 36, 'اور نہ کھانا ہے مگر زخموں کا دھون'),
  ('ur.ahmedali', 69, 37, 'اسے سوائے گناہگاروں کے کوئی نہیں کھائے گا'),
  ('ur.ahmedali', 69, 38, 'سو میں ان چیزوں کی قسم کھاتا ہوں جو تم دیکھتے ہو'),
  ('ur.ahmedali', 69, 39, 'اوران کی جو تم نہیں دیکھتے'),
  ('ur.ahmedali', 69, 40, 'کہ بے شک یہ (قرآن) رسول کریم کی زبان سے نکلا ہے'),
  ('ur.ahmedali', 69, 41, 'اور وہ کسی شاعر کا قول نہیں (مگر) تم بہت ہی کم یقین کرتے ہو'),
  ('ur.ahmedali', 69, 42, 'اور نہ ہی کسی جادوگر کا قول ہے تم بہت ہی کم غور کرتے ہو'),
  ('ur.ahmedali', 69, 43, 'وہ پرودگار عالم کا نازل کیا ہوا ہے'),
  ('ur.ahmedali', 69, 44, 'اور اگر وہ کوئی بناوٹی بات ہمارے ذمہ لگاتا'),
  ('ur.ahmedali', 69, 45, 'تو ہم اس کا داہنا ہاتھ پکڑ لیتے'),
  ('ur.ahmedali', 69, 46, 'پھر ہم اس کی رگِ گردن کاٹ ڈالتے'),
  ('ur.ahmedali', 69, 47, 'پھر تم میں سے کوئی بھی اس سے روکنے والا نہ ہوتا'),
  ('ur.ahmedali', 69, 48, 'اور بے شک وہ تو پرہیزگاروں کے لیے ایک نصیحت ہے'),
  ('ur.ahmedali', 69, 49, 'اور بے شک ہم جانتے ہیں کہ بعض تم میں سے جھٹلانے والے ہیں'),
  ('ur.ahmedali', 69, 50, 'اور بے شک وہ کفار پر باعث حسرت ہے'),
  ('ur.ahmedali', 69, 51, 'اور بے شک وہ یقین کرنے کے قابل ہے'),
  ('ur.ahmedali', 69, 52, 'پس اپنے رب کے نام کی تسبیح کر جو بڑا عظمت والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 69, 1, 'Gerçekleşecek olan!'),
  ('tr.diyanet', 69, 2, 'Nedir o gerçekleşecek olan gün?'),
  ('tr.diyanet', 69, 3, 'Gerçekleşecek olanın ne olduğunu sana ne bildirir?'),
  ('tr.diyanet', 69, 4, 'Semud ve Ad milletleri tepelerine inecek bu gerçeği yalanladılar.'),
  ('tr.diyanet', 69, 5, 'Bu yüzden Semud milleti zorlu bir sarsıntı ile yok edildi.'),
  ('tr.diyanet', 69, 6, 'Ad milleti de bu yüzden önünde durulmaz, dondurucu bir rüzgarla yok edildi.'),
  ('tr.diyanet', 69, 7, 'Allah onların kökünü kesmek üzere, üzerlerine o rüzgarı yedi gece sekiz gün, estirdi. Halkın, kökünden çıkarılmış hurma kütükleri gibi yere yıkıldıklarını görürsün.'),
  ('tr.diyanet', 69, 8, 'Onlardan arda kalmış bir şey görür müsün?'),
  ('tr.diyanet', 69, 9, 'Firavun, ondan öncekiler ve alt üst olmuş kasabalarda oturanlar da suç işlemişlerdi.'),
  ('tr.diyanet', 69, 10, 'Rabbinin peygamberine baş kaldırmışlardı. Bunun üzerine Rableri onları şiddeti arttıkça artan bir şekilde yakaladı.'),
  ('tr.diyanet', 69, 11, 'Su taştığı vakit, size bir ibret olmak üzere, anlayışlı kulaklar anlasın diye süzülen gemide, sizi Biz taşımışızdır.'),
  ('tr.diyanet', 69, 12, 'Su taştığı vakit, size bir ibret olmak üzere, anlayışlı kulaklar anlasın diye süzülen gemide, sizi Biz taşımışızdır.'),
  ('tr.diyanet', 69, 13, 'Sura bir üfürüş üfürüldüğü, yer ve dağlar kaldırılıp bir vuruşla birbirine çarpıldığı zaman, işte o gün olacak olur, kıyamet kopar.'),
  ('tr.diyanet', 69, 14, 'Sura bir üfürüş üfürüldüğü, yer ve dağlar kaldırılıp bir vuruşla birbirine çarpıldığı zaman, işte o gün olacak olur, kıyamet kopar.'),
  ('tr.diyanet', 69, 15, 'Sura bir üfürüş üfürüldüğü, yer ve dağlar kaldırılıp bir vuruşla birbirine çarpıldığı zaman, işte o gün olacak olur, kıyamet kopar.'),
  ('tr.diyanet', 69, 16, 'Gök yarılır; o gün düzeni bozulur.'),
  ('tr.diyanet', 69, 17, 'Melekler onun çevresindedirler; o gün Rabbinin arşını onlardan başka sekiz tanesi yüklenir.'),
  ('tr.diyanet', 69, 18, 'O gün siz huzura alınırsınız, hiçbir şeyiniz gizli kalmaz.'),
  ('tr.diyanet', 69, 19, 'Kitabı sağından verilen; "Alın, kitabımı okuyun, doğrusu bir hesaplaşma ile karşılaşacağımı umuyordum" der.'),
  ('tr.diyanet', 69, 20, 'Kitabı sağından verilen; "Alın, kitabımı okuyun, doğrusu bir hesaplaşma ile karşılaşacağımı umuyordum" der.'),
  ('tr.diyanet', 69, 21, 'Artık o, meyveleri sarkmış, yüksek bir bahçede, hoş bir yaşayış içindedir.'),
  ('tr.diyanet', 69, 22, 'Artık o, meyveleri sarkmış, yüksek bir bahçede, hoş bir yaşayış içindedir.'),
  ('tr.diyanet', 69, 23, 'Artık o, meyveleri sarkmış, yüksek bir bahçede, hoş bir yaşayış içindedir.'),
  ('tr.diyanet', 69, 24, 'Onlara şöyle denir: "Geçmiş günlerde, peşinen işlediklerinize karşılık afiyetle yiyiniz içiniz."'),
  ('tr.diyanet', 69, 25, 'Fakat kitabı kendisine solundan verilen kimse: "Kitabım keşke bana verilmeseydi; keşke hesabımın ne olduğunu bilmeseydim; bu iş keşke son bulmuş olsaydı; malım bana fayda vermedi; gücüm de kalmadı" der.'),
  ('tr.diyanet', 69, 26, 'Fakat kitabı kendisine solundan verilen kimse: "Kitabım keşke bana verilmeseydi; keşke hesabımın ne olduğunu bilmeseydim; bu iş keşke son bulmuş olsaydı; malım bana fayda vermedi; gücüm de kalmadı" der.'),
  ('tr.diyanet', 69, 27, 'Fakat kitabı kendisine solundan verilen kimse: "Kitabım keşke bana verilmeseydi; keşke hesabımın ne olduğunu bilmeseydim; bu iş keşke son bulmuş olsaydı; malım bana fayda vermedi; gücüm de kalmadı" der.'),
  ('tr.diyanet', 69, 28, 'Fakat kitabı kendisine solundan verilen kimse: "Kitabım keşke bana verilmeseydi; keşke hesabımın ne olduğunu bilmeseydim; bu iş keşke son bulmuş olsaydı; malım bana fayda vermedi; gücüm de kalmadı" der.'),
  ('tr.diyanet', 69, 29, 'Fakat kitabı kendisine solundan verilen kimse: "Kitabım keşke bana verilmeseydi; keşke hesabımın ne olduğunu bilmeseydim; bu iş keşke son bulmuş olsaydı; malım bana fayda vermedi; gücüm de kalmadı" der.'),
  ('tr.diyanet', 69, 30, 'İlgililere şöyle buyurulur: "O\'nu alın, bağlayın."'),
  ('tr.diyanet', 69, 31, '"Sonra cehenneme yaslayın"'),
  ('tr.diyanet', 69, 32, '"Sonra onu boyu yetmiş arşın olan zincire vurun";'),
  ('tr.diyanet', 69, 33, '"Çünkü, o, yüce Allah\'a inanmazdı."'),
  ('tr.diyanet', 69, 34, '"Yoksulun yiyeceği ile ilgilenmezdi."'),
  ('tr.diyanet', 69, 35, '"Bu sebeple burada bugün onun bir acıyanı yoktur."'),
  ('tr.diyanet', 69, 36, '"Günahkarların yiyeceği olan kanlı irinden başka bir yiyeceği de yoktur."'),
  ('tr.diyanet', 69, 37, '"Günahkarların yiyeceği olan kanlı irinden başka bir yiyeceği de yoktur."'),
  ('tr.diyanet', 69, 38, 'Görebildikleriniz ve göremedikleriniz üzerine yemin ederim ki, Kuran şerefli bir elçinin getirdiği sözdür.'),
  ('tr.diyanet', 69, 39, 'Görebildikleriniz ve göremedikleriniz üzerine yemin ederim ki, Kuran şerefli bir elçinin getirdiği sözdür.'),
  ('tr.diyanet', 69, 40, 'Görebildikleriniz ve göremedikleriniz üzerine yemin ederim ki, Kuran şerefli bir elçinin getirdiği sözdür.'),
  ('tr.diyanet', 69, 41, 'O, şair sözü değildir; ne az inanıyorsunuz!'),
  ('tr.diyanet', 69, 42, 'Kahin sözü de değildir; ne az düşünüyorsunuz!'),
  ('tr.diyanet', 69, 43, 'Kuran, Alemlerin Rabbinden indirilmedir.'),
  ('tr.diyanet', 69, 44, 'Eğer o (Muhammed), Bize karşı, ona bazı sözler katmış olsaydı, Biz onu kuvvetle yakalardık, sonra onun şah damarını koparırdık.'),
  ('tr.diyanet', 69, 45, 'Eğer o (Muhammed), Bize karşı, ona bazı sözler katmış olsaydı, Biz onu kuvvetle yakalardık, sonra onun şah damarını koparırdık.'),
  ('tr.diyanet', 69, 46, 'Eğer o (Muhammed), Bize karşı, ona bazı sözler katmış olsaydı, Biz onu kuvvetle yakalardık, sonra onun şah damarını koparırdık.'),
  ('tr.diyanet', 69, 47, 'Hiçbiriniz de onu koruyamazdınız.'),
  ('tr.diyanet', 69, 48, 'Doğrusu Kuran Allah\'a karşı gelmekten sakınanlara bir öğüttür.'),
  ('tr.diyanet', 69, 49, 'İçinizde yalanlayanlar bulunduğunu şüphesiz bilmekteyiz.'),
  ('tr.diyanet', 69, 50, 'Doğrusu Kuran, inkarcılar için bir üzüntüdür.'),
  ('tr.diyanet', 69, 51, 'O, şüphesiz kesin gerçektir.'),
  ('tr.diyanet', 69, 52, 'Öyleyse çok büyük olan Rabbinin adını tesbih et.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 69, 1, 'Hari kiamat,'),
  ('id.indonesian', 69, 2, 'apakah hari kiamat itu?'),
  ('id.indonesian', 69, 3, 'Dan tahukah kamu apakah hari kiamat itu?'),
  ('id.indonesian', 69, 4, 'Kaum Tsamud dan \'Aad telah mendustakan hari kiamat.'),
  ('id.indonesian', 69, 5, 'Adapun kaum Tsamud, maka mereka telah dibinasakan dengan kejadian yang luar biasa.'),
  ('id.indonesian', 69, 6, 'Adapun kaum \'Aad maka mereka telah dibinasakan dengan angin yang sangat dingin lagi amat kencang,'),
  ('id.indonesian', 69, 7, 'yang Allah menimpakan angin itu kepada mereka selama tujuh malam dan delapan hari terus menerus; maka kamu lihat kaum \'Aad pada waktu itu mati bergelimpangan seakan-akan mereka tunggul pohon kurma yang telah kosong (lapuk).'),
  ('id.indonesian', 69, 8, 'Maka kamu tidak melihat seorangpun yang tinggal di antara mereka.'),
  ('id.indonesian', 69, 9, 'Dan telah datang Fir\'aun dan orang-orang yang sebelumnya dan (penduduk) negeri-negeri yang dijungkir balikkan karena kesalahan yang besar.'),
  ('id.indonesian', 69, 10, 'Maka (masing-masing) mereka mendurhakai rasul Tuhan mereka, lalu Allah menyiksa mereka dengan siksaan yang sangat keras.'),
  ('id.indonesian', 69, 11, 'Sesungguhnya Kami, tatkala air telah naik (sampai ke gunung) Kami bawa (nenek moyang) kamu, ke dalam bahtera,'),
  ('id.indonesian', 69, 12, 'agar Kami jadikan peristiwa itu peringatan bagi kamu dan agar diperhatikan oleh telinga yang mau mendengar.'),
  ('id.indonesian', 69, 13, 'Maka apabila sangkakala ditiup sekali tiup'),
  ('id.indonesian', 69, 14, 'dan diangkatlah bumi dan gunung-gunung, lalu dibenturkan keduanya sekali bentur.'),
  ('id.indonesian', 69, 15, 'Maka pada hari itu terjadilah hari kiamat,'),
  ('id.indonesian', 69, 16, 'dan terbelahlah langit, karena pada hari itu langit menjadi lemah.'),
  ('id.indonesian', 69, 17, 'Dan malaikat-malaikat berada di penjuru-penjuru langit. Dan pada hari itu delapan orang malaikat menjunjung \'Arsy Tuhanmu di atas (kepala) mereka.'),
  ('id.indonesian', 69, 18, 'Pada hari itu kamu dihadapkan (kepada Tuhanmu), tiada sesuatupun dari keadaanmu yang tersembunyi (bagi Allah).'),
  ('id.indonesian', 69, 19, 'Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kanannya, maka dia berkata: "Ambillah, bacalah kitabku (ini)".'),
  ('id.indonesian', 69, 20, 'Sesungguhnya aku yakin, bahwa sesungguhnya aku akan menemui hisab terhadap diriku.'),
  ('id.indonesian', 69, 21, 'Maka orang itu berada dalam kehidupan yang diridhai,'),
  ('id.indonesian', 69, 22, 'dalam surga yang tinggi,'),
  ('id.indonesian', 69, 23, 'buah-buahannya dekat,'),
  ('id.indonesian', 69, 24, '(kepada mereka dikatakan): "Makan dan minumlah dengan sedap disebabkan amal yang telah kamu kerjakan pada hari-hari yang telah lalu".'),
  ('id.indonesian', 69, 25, 'Adapun orang yang diberikan kepadanya kitabnya dari sebelah kirinya, maka dia berkata: "Wahai alangkah baiknya kiranya tidak diberikan kepadaku kitabku (ini).'),
  ('id.indonesian', 69, 26, 'Dan aku tidak mengetahui apa hisab terhadap diriku.'),
  ('id.indonesian', 69, 27, 'Wahai kiranya kematian itulah yang menyelesaikan segala sesuatu.'),
  ('id.indonesian', 69, 28, 'Hartaku sekali-kali tidak memberi manfaat kepadaku.'),
  ('id.indonesian', 69, 29, 'Telah hilang kekuasaanku daripadaku".'),
  ('id.indonesian', 69, 30, '(Allah berfirman): "Peganglah dia lalu belenggulah tangannya ke lehernya.'),
  ('id.indonesian', 69, 31, 'Kemudian masukkanlah dia ke dalam api neraka yang menyala-nyala.'),
  ('id.indonesian', 69, 32, 'Kemudian belitlah dia dengan rantai yang panjangnya tujuh puluh hasta.'),
  ('id.indonesian', 69, 33, 'Sesungguhnya dia dahulu tidak beriman kepada Allah Yang Maha Besar.'),
  ('id.indonesian', 69, 34, 'Dan juga dia tidak mendorong (orang lain) untuk memberi makan orang miskin.'),
  ('id.indonesian', 69, 35, 'Maka tiada seorang temanpun baginya pada hari ini di sini.'),
  ('id.indonesian', 69, 36, 'Dan tiada (pula) makanan sedikitpun (baginya) kecuali dari darah dan nanah.'),
  ('id.indonesian', 69, 37, 'Tidak ada yang memakannya kecuali orang-orang yang berdosa.'),
  ('id.indonesian', 69, 38, 'Maka Aku bersumpah dengan apa yang kamu lihat.'),
  ('id.indonesian', 69, 39, 'Dan dengan apa yang tidak kamu lihat.'),
  ('id.indonesian', 69, 40, 'Sesungguhnya Al Quran itu adalah benar-benar wahyu (Allah yang diturunkan kepada) Rasul yang mulia,'),
  ('id.indonesian', 69, 41, 'dan Al Quran itu bukanlah perkataan seorang penyair. Sedikit sekali kamu beriman kepadanya.'),
  ('id.indonesian', 69, 42, 'Dan bukan pula perkataan tukang tenung. Sedikit sekali kamu mengambil pelajaran daripadanya.'),
  ('id.indonesian', 69, 43, 'Ia adalah wahyu yang diturunkan dari Tuhan semesta alam.'),
  ('id.indonesian', 69, 44, 'Seandainya dia (Muhammad) mengadakan sebagian perkataan atas (nama) Kami,'),
  ('id.indonesian', 69, 45, 'niscaya benar-benar Kami pegang dia pada tangan kanannya.'),
  ('id.indonesian', 69, 46, 'Kemudian benar-benar Kami potong urat tali jantungnya.'),
  ('id.indonesian', 69, 47, 'Maka sekali-kali tidak ada seorangpun dari kamu yang dapat menghalangi (Kami), dari pemotongan urat nadi itu.'),
  ('id.indonesian', 69, 48, 'Dan sesungguhnya Al Quran itu benar-benar suatu pelajaran bagi orang-orang yang bertakwa.'),
  ('id.indonesian', 69, 49, 'Dan sesungguhnya Kami benar-benar mengetahui bahwa di antara kamu ada orang yang mendustakan(nya).'),
  ('id.indonesian', 69, 50, 'Dan sesungguhnya Al Quran itu benar-benar menjadi penyesalan bagi orang-orang kafir (di akhirat).'),
  ('id.indonesian', 69, 51, 'Dan sesungguhnya Al Quran itu benar-benar kebenaran yang diyakini.'),
  ('id.indonesian', 69, 52, 'Maka bertasbihlah dengan (menyebut) nama Tuhanmu Yang Maha Besar.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (64, 2, 5201, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌۭ وَمِنكُم مُّؤْمِنٌۭ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 556, 28, 222, 0),
  (64, 3, 5202, 'خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 556, 28, 222, 0),
  (64, 4, 5203, 'يَعْلَمُ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ ۚ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 556, 28, 222, 0),
  (64, 5, 5204, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌۭ', 556, 28, 222, 0),
  (64, 6, 5205, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَقَالُوٓا۟ أَبَشَرٌۭ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ ۚ وَّٱسْتَغْنَى ٱللَّهُ ۚ وَٱللَّهُ غَنِىٌّ حَمِيدٌۭ', 556, 28, 222, 0),
  (64, 7, 5206, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ ۚ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌۭ', 556, 28, 222, 0),
  (64, 8, 5207, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌۭ', 556, 28, 222, 0),
  (64, 9, 5208, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ۖ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًۭا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 556, 28, 222, 0),
  (64, 10, 5209, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَا ۖ وَبِئْسَ ٱلْمَصِيرُ', 557, 28, 222, 0),
  (64, 11, 5210, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۭ', 557, 28, 222, 0),
  (64, 12, 5211, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ', 557, 28, 222, 0),
  (64, 13, 5212, 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 557, 28, 222, 0),
  (64, 14, 5213, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَٰدِكُمْ عَدُوًّۭا لَّكُمْ فَٱحْذَرُوهُمْ ۚ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ', 557, 28, 222, 0),
  (64, 15, 5214, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَٰدُكُمْ فِتْنَةٌۭ ۚ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌۭ', 557, 28, 222, 0),
  (64, 16, 5215, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًۭا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 557, 28, 222, 0),
  (64, 17, 5216, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًۭا يُضَٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ', 557, 28, 222, 0),
  (64, 18, 5217, 'عَٰلِمُ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 557, 28, 222, 0),
  (65, 1, 5218, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَٰحِشَةٍۢ مُّبَيِّنَةٍۢ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًۭا', 558, 28, 223, 0),
  (65, 2, 5219, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍۢ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍۢ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَٰدَةَ لِلَّهِ ۚ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًۭا', 558, 28, 223, 0),
  (65, 3, 5220, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍۢ قَدْرًۭا', 558, 28, 223, 0),
  (65, 4, 5221, 'وَٱلَّٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشْهُرٍۢ وَٱلَّٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًۭا', 558, 28, 223, 0),
  (65, 5, 5222, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ ۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 558, 28, 223, 0),
  (65, 6, 5223, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ ۚ وَإِن كُنَّ أُو۟لَٰتِ حَمْلٍۢ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ ۖ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍۢ ۖ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 559, 28, 223, 0),
  (65, 7, 5224, 'لِيُنفِقْ ذُو سَعَةٍۢ مِّن سَعَتِهِۦ ۖ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ ۚ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا ۚ سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍۢ يُسْرًۭا', 559, 28, 223, 0),
  (65, 8, 5225, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَٰهَا حِسَابًۭا شَدِيدًۭا وَعَذَّبْنَٰهَا عَذَابًۭا نُّكْرًۭا', 559, 28, 223, 0),
  (65, 9, 5226, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَٰقِبَةُ أَمْرِهَا خُسْرًا', 559, 28, 223, 0),
  (65, 10, 5227, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًۭا شَدِيدًۭا ۖ فَٱتَّقُوا۟ ٱللَّهَ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ ءَامَنُوا۟ ۚ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًۭا', 559, 28, 223, 0),
  (65, 11, 5228, 'رَّسُولًۭا يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٍۢ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ ۚ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَٰلِحًۭا يُدْخِلْهُ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', 559, 28, 223, 0),
  (65, 12, 5229, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 559, 28, 223, 0),
  (66, 1, 5230, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ يَٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ', 560, 28, 224, 0),
  (66, 2, 5231, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 560, 28, 224, 0),
  (66, 3, 5232, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًۭا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍۢ ۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَٰذَا ۖ قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', 560, 28, 224, 0),
  (66, 4, 5233, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ۖ وَإِن تَظَٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَٰلِحُ ٱلْمُؤْمِنِينَ ۖ وَٱلْمَلَٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', 560, 28, 224, 0),
  (66, 5, 5234, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًۭا مِّنكُنَّ مُسْلِمَٰتٍۢ مُّؤْمِنَٰتٍۢ قَٰنِتَٰتٍۢ تَٰٓئِبَٰتٍ عَٰبِدَٰتٍۢ سَٰٓئِحَٰتٍۢ ثَيِّبَٰتٍۢ وَأَبْكَارًۭا', 560, 28, 224, 0),
  (66, 6, 5235, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًۭا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَٰٓئِكَةٌ غِلَاظٌۭ شِدَادٌۭ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 560, 28, 224, 0),
  (66, 7, 5236, 'يَٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 560, 28, 224, 0),
  (66, 8, 5237, 'يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةًۭ نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّٰتٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ', 561, 28, 224, 0),
  (66, 9, 5238, 'يَٰٓأَيُّهَا ٱلنَّبِىُّ جَٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 561, 28, 224, 0),
  (66, 10, 5239, 'ضَرَبَ ٱللَّهُ مَثَلًۭا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍۢ وَٱمْرَأَتَ لُوطٍۢ ۖ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًۭٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', 561, 28, 224, 0),
  (66, 11, 5240, 'وَضَرَبَ ٱللَّهُ مَثَلًۭا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًۭا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ', 561, 28, 224, 0),
  (66, 12, 5241, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَٰنِتِينَ', 561, 28, 224, 0),
  (67, 1, 5242, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ', 562, 29, 225, 0),
  (67, 2, 5243, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 562, 29, 225, 0),
  (67, 3, 5244, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍۢ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍۢ', 562, 29, 225, 0),
  (67, 4, 5245, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًۭا وَهُوَ حَسِيرٌۭ', 562, 29, 225, 0),
  (67, 5, 5246, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًۭا لِّلشَّيَٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', 562, 29, 225, 0),
  (67, 6, 5247, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ', 562, 29, 225, 0),
  (67, 7, 5248, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًۭا وَهِىَ تَفُورُ', 562, 29, 225, 0),
  (67, 8, 5249, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌۭ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌۭ', 562, 29, 225, 0),
  (67, 9, 5250, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌۭ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍۢ كَبِيرٍۢ', 562, 29, 225, 0),
  (67, 10, 5251, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ', 562, 29, 225, 0),
  (67, 11, 5252, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًۭا لِّأَصْحَٰبِ ٱلسَّعِيرِ', 562, 29, 225, 0),
  (67, 12, 5253, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌۭ', 562, 29, 225, 0),
  (67, 13, 5254, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 563, 29, 225, 0),
  (67, 14, 5255, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 563, 29, 225, 0),
  (67, 15, 5256, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًۭا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ', 563, 29, 225, 0),
  (67, 16, 5257, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 563, 29, 225, 0),
  (67, 17, 5258, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًۭا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 563, 29, 225, 0),
  (67, 18, 5259, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 563, 29, 225, 0),
  (67, 19, 5260, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍۢ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', 563, 29, 225, 0),
  (67, 20, 5261, 'أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌۭ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ ۚ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ', 563, 29, 225, 0),
  (67, 21, 5262, 'أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّۢ وَنُفُورٍ', 563, 29, 225, 0),
  (67, 22, 5263, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ', 563, 29, 225, 0),
  (67, 23, 5264, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًۭا مَّا تَشْكُرُونَ', 563, 29, 225, 0),
  (67, 24, 5265, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 563, 29, 225, 0),
  (67, 25, 5266, 'وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ', 563, 29, 225, 0),
  (67, 26, 5267, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌۭ', 563, 29, 225, 0),
  (67, 27, 5268, 'فَلَمَّا رَأَوْهُ زُلْفَةًۭ سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', 564, 29, 225, 0),
  (67, 28, 5269, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍۢ', 564, 29, 225, 0),
  (67, 29, 5270, 'قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍۢ مُّبِينٍۢ', 564, 29, 225, 0),
  (67, 30, 5271, 'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًۭا فَمَن يَأْتِيكُم بِمَآءٍۢ مَّعِينٍۭ', 564, 29, 225, 0),
  (68, 1, 5272, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ', 564, 29, 226, 0),
  (68, 2, 5273, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍۢ', 564, 29, 226, 0),
  (68, 3, 5274, 'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍۢ', 564, 29, 226, 0),
  (68, 4, 5275, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍۢ', 564, 29, 226, 0),
  (68, 5, 5276, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 564, 29, 226, 0),
  (68, 6, 5277, 'بِأَييِّكُمُ ٱلْمَفْتُونُ', 564, 29, 226, 0),
  (68, 7, 5278, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 564, 29, 226, 0),
  (68, 8, 5279, 'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ', 564, 29, 226, 0),
  (68, 9, 5280, 'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ', 564, 29, 226, 0),
  (68, 10, 5281, 'وَلَا تُطِعْ كُلَّ حَلَّافٍۢ مَّهِينٍ', 564, 29, 226, 0),
  (68, 11, 5282, 'هَمَّازٍۢ مَّشَّآءٍۭ بِنَمِيمٍۢ', 564, 29, 226, 0),
  (68, 12, 5283, 'مَّنَّاعٍۢ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ', 564, 29, 226, 0),
  (68, 13, 5284, 'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ', 564, 29, 226, 0),
  (68, 14, 5285, 'أَن كَانَ ذَا مَالٍۢ وَبَنِينَ', 564, 29, 226, 0),
  (68, 15, 5286, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 564, 29, 226, 0),
  (68, 16, 5287, 'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ', 565, 29, 226, 0),
  (68, 17, 5288, 'إِنَّا بَلَوْنَٰهُمْ كَمَا بَلَوْنَآ أَصْحَٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 565, 29, 226, 0),
  (68, 18, 5289, 'وَلَا يَسْتَثْنُونَ', 565, 29, 226, 0),
  (68, 19, 5290, 'فَطَافَ عَلَيْهَا طَآئِفٌۭ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 565, 29, 226, 0),
  (68, 20, 5291, 'فَأَصْبَحَتْ كَٱلصَّرِيمِ', 565, 29, 226, 0),
  (68, 21, 5292, 'فَتَنَادَوْا۟ مُصْبِحِينَ', 565, 29, 226, 0),
  (68, 22, 5293, 'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَٰرِمِينَ', 565, 29, 226, 0),
  (68, 23, 5294, 'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَٰفَتُونَ', 565, 29, 226, 0),
  (68, 24, 5295, 'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌۭ', 565, 29, 226, 0),
  (68, 25, 5296, 'وَغَدَوْا۟ عَلَىٰ حَرْدٍۢ قَٰدِرِينَ', 565, 29, 226, 0),
  (68, 26, 5297, 'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ', 565, 29, 226, 0),
  (68, 27, 5298, 'بَلْ نَحْنُ مَحْرُومُونَ', 565, 29, 226, 0),
  (68, 28, 5299, 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', 565, 29, 226, 0),
  (68, 29, 5300, 'قَالُوا۟ سُبْحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ', 565, 29, 226, 0),
  (68, 30, 5301, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَلَٰوَمُونَ', 565, 29, 226, 0),
  (68, 31, 5302, 'قَالُوا۟ يَٰوَيْلَنَآ إِنَّا كُنَّا طَٰغِينَ', 565, 29, 226, 0),
  (68, 32, 5303, 'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًۭا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', 565, 29, 226, 0),
  (68, 33, 5304, 'كَذَٰلِكَ ٱلْعَذَابُ ۖ وَلَعَذَابُ ٱلْءَاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 565, 29, 226, 0),
  (68, 34, 5305, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّٰتِ ٱلنَّعِيمِ', 565, 29, 226, 0),
  (68, 35, 5306, 'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ', 565, 29, 226, 0),
  (68, 36, 5307, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 565, 29, 226, 0),
  (68, 37, 5308, 'أَمْ لَكُمْ كِتَٰبٌۭ فِيهِ تَدْرُسُونَ', 565, 29, 226, 0),
  (68, 38, 5309, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', 565, 29, 226, 0),
  (68, 39, 5310, 'أَمْ لَكُمْ أَيْمَٰنٌ عَلَيْنَا بَٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۙ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', 565, 29, 226, 0),
  (68, 40, 5311, 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', 565, 29, 226, 0),
  (68, 41, 5312, 'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَٰدِقِينَ', 565, 29, 226, 0),
  (68, 42, 5313, 'يَوْمَ يُكْشَفُ عَن سَاقٍۢ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ', 565, 29, 226, 0),
  (68, 43, 5314, 'خَٰشِعَةً أَبْصَٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌۭ ۖ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَٰلِمُونَ', 566, 29, 226, 0),
  (68, 44, 5315, 'فَذَرْنِى وَمَن يُكَذِّبُ بِهَٰذَا ٱلْحَدِيثِ ۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 566, 29, 226, 0),
  (68, 45, 5316, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', 566, 29, 226, 0),
  (68, 46, 5317, 'أَمْ تَسْـَٔلُهُمْ أَجْرًۭا فَهُم مِّن مَّغْرَمٍۢ مُّثْقَلُونَ', 566, 29, 226, 0),
  (68, 47, 5318, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 566, 29, 226, 0),
  (68, 48, 5319, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌۭ', 566, 29, 226, 0),
  (68, 49, 5320, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌۭ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌۭ', 566, 29, 226, 0),
  (68, 50, 5321, 'فَٱجْتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ', 566, 29, 226, 0),
  (68, 51, 5322, 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌۭ', 566, 29, 226, 0),
  (68, 52, 5323, 'وَمَا هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 566, 29, 226, 0),
  (69, 1, 5324, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْحَآقَّةُ', 566, 29, 227, 0),
  (69, 2, 5325, 'مَا ٱلْحَآقَّةُ', 566, 29, 227, 0),
  (69, 3, 5326, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ', 566, 29, 227, 0),
  (69, 4, 5327, 'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ', 566, 29, 227, 0),
  (69, 5, 5328, 'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ', 566, 29, 227, 0),
  (69, 6, 5329, 'وَأَمَّا عَادٌۭ فَأُهْلِكُوا۟ بِرِيحٍۢ صَرْصَرٍ عَاتِيَةٍۢ', 566, 29, 227, 0),
  (69, 7, 5330, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍۢ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومًۭا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍۢ', 566, 29, 227, 0),
  (69, 8, 5331, 'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍۢ', 566, 29, 227, 0),
  (69, 9, 5332, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَٰتُ بِٱلْخَاطِئَةِ', 567, 29, 227, 0),
  (69, 10, 5333, 'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةًۭ رَّابِيَةً', 567, 29, 227, 0),
  (69, 11, 5334, 'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَٰكُمْ فِى ٱلْجَارِيَةِ', 567, 29, 227, 0),
  (69, 12, 5335, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةًۭ وَتَعِيَهَآ أُذُنٌۭ وَٰعِيَةٌۭ', 567, 29, 227, 0),
  (69, 13, 5336, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌۭ وَٰحِدَةٌۭ', 567, 29, 227, 0),
  (69, 14, 5337, 'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةًۭ وَٰحِدَةًۭ', 567, 29, 227, 0),
  (69, 15, 5338, 'فَيَوْمَئِذٍۢ وَقَعَتِ ٱلْوَاقِعَةُ', 567, 29, 227, 0),
  (69, 16, 5339, 'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍۢ وَاهِيَةٌۭ', 567, 29, 227, 0),
  (69, 17, 5340, 'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍۢ ثَمَٰنِيَةٌۭ', 567, 29, 227, 0),
  (69, 18, 5341, 'يَوْمَئِذٍۢ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌۭ', 567, 29, 227, 0),
  (69, 19, 5342, 'فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَٰبِيَهْ', 567, 29, 227, 0),
  (69, 20, 5343, 'إِنِّى ظَنَنتُ أَنِّى مُلَٰقٍ حِسَابِيَهْ', 567, 29, 227, 0),
