  (69, 42, 5365, 'وَلَا بِقَوْلِ كَاهِنٍۢ ۚ قَلِيلًۭا مَّا تَذَكَّرُونَ', 568, 29, 227, 0),
  (69, 43, 5366, 'تَنزِيلٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ', 568, 29, 227, 0),
  (69, 44, 5367, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ', 568, 29, 227, 0),
  (69, 45, 5368, 'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ', 568, 29, 227, 0),
  (69, 46, 5369, 'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ', 568, 29, 227, 0),
  (69, 47, 5370, 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَٰجِزِينَ', 568, 29, 227, 0),
  (69, 48, 5371, 'وَإِنَّهُۥ لَتَذْكِرَةٌۭ لِّلْمُتَّقِينَ', 568, 29, 227, 0),
  (69, 49, 5372, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', 568, 29, 227, 0),
  (69, 50, 5373, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَٰفِرِينَ', 568, 29, 227, 0),
  (69, 51, 5374, 'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ', 568, 29, 227, 0),
