  (79, 25, 5737, 'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْءَاخِرَةِ وَٱلْأُولَىٰٓ', 584, 30, 233, 0),
  (79, 26, 5738, 'إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّمَن يَخْشَىٰٓ', 584, 30, 233, 0),
  (79, 27, 5739, 'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا', 584, 30, 233, 0),
  (79, 28, 5740, 'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا', 584, 30, 233, 0),
  (79, 29, 5741, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا', 584, 30, 233, 0),
  (79, 30, 5742, 'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ', 584, 30, 233, 0),
  (79, 31, 5743, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا', 584, 30, 233, 0),
  (79, 32, 5744, 'وَٱلْجِبَالَ أَرْسَىٰهَا', 584, 30, 233, 0),
  (79, 33, 5745, 'مَتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ', 584, 30, 233, 0),
  (79, 34, 5746, 'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ', 584, 30, 233, 0),
  (79, 35, 5747, 'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ', 584, 30, 233, 0),
  (79, 36, 5748, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ', 584, 30, 233, 0),
  (79, 37, 5749, 'فَأَمَّا مَن طَغَىٰ', 584, 30, 233, 0),
  (79, 38, 5750, 'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 584, 30, 233, 0),
  (79, 39, 5751, 'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ', 584, 30, 233, 0),
  (79, 40, 5752, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ', 584, 30, 233, 0),
  (79, 41, 5753, 'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ', 584, 30, 233, 0),
  (79, 42, 5754, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا', 584, 30, 233, 0),
  (79, 43, 5755, 'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ', 584, 30, 233, 0),
  (79, 44, 5756, 'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ', 584, 30, 233, 0),
  (79, 45, 5757, 'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا', 584, 30, 233, 0),
  (79, 46, 5758, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا', 584, 30, 233, 0),
  (80, 1, 5759, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ عَبَسَ وَتَوَلَّىٰٓ', 585, 30, 234, 0),
  (80, 2, 5760, 'أَن جَآءَهُ ٱلْأَعْمَىٰ', 585, 30, 234, 0),
  (80, 3, 5761, 'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ', 585, 30, 234, 0),
  (80, 4, 5762, 'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ', 585, 30, 234, 0),
  (80, 5, 5763, 'أَمَّا مَنِ ٱسْتَغْنَىٰ', 585, 30, 234, 0),
  (80, 6, 5764, 'فَأَنتَ لَهُۥ تَصَدَّىٰ', 585, 30, 234, 0),
  (80, 7, 5765, 'وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ', 585, 30, 234, 0),
  (80, 8, 5766, 'وَأَمَّا مَن جَآءَكَ يَسْعَىٰ', 585, 30, 234, 0),
  (80, 9, 5767, 'وَهُوَ يَخْشَىٰ', 585, 30, 234, 0),
  (80, 10, 5768, 'فَأَنتَ عَنْهُ تَلَهَّىٰ', 585, 30, 234, 0),
  (80, 11, 5769, 'كَلَّآ إِنَّهَا تَذْكِرَةٌۭ', 585, 30, 234, 0),
  (80, 12, 5770, 'فَمَن شَآءَ ذَكَرَهُۥ', 585, 30, 234, 0),
  (80, 13, 5771, 'فِى صُحُفٍۢ مُّكَرَّمَةٍۢ', 585, 30, 234, 0),
  (80, 14, 5772, 'مَّرْفُوعَةٍۢ مُّطَهَّرَةٍۭ', 585, 30, 234, 0),
  (80, 15, 5773, 'بِأَيْدِى سَفَرَةٍۢ', 585, 30, 234, 0),
  (80, 16, 5774, 'كِرَامٍۭ بَرَرَةٍۢ', 585, 30, 234, 0),
  (80, 17, 5775, 'قُتِلَ ٱلْإِنسَٰنُ مَآ أَكْفَرَهُۥ', 585, 30, 234, 0),
  (80, 18, 5776, 'مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ', 585, 30, 234, 0),
  (80, 19, 5777, 'مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ', 585, 30, 234, 0),
  (80, 20, 5778, 'ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ', 585, 30, 234, 0),
  (80, 21, 5779, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ', 585, 30, 234, 0),
  (80, 22, 5780, 'ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ', 585, 30, 234, 0),
  (80, 23, 5781, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ', 585, 30, 234, 0),
  (80, 24, 5782, 'فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ', 585, 30, 234, 0),
  (80, 25, 5783, 'أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّۭا', 585, 30, 234, 0),
  (80, 26, 5784, 'ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّۭا', 585, 30, 234, 0),
  (80, 27, 5785, 'فَأَنۢبَتْنَا فِيهَا حَبًّۭا', 585, 30, 234, 0),
  (80, 28, 5786, 'وَعِنَبًۭا وَقَضْبًۭا', 585, 30, 234, 0),
  (80, 29, 5787, 'وَزَيْتُونًۭا وَنَخْلًۭا', 585, 30, 234, 0),
  (80, 30, 5788, 'وَحَدَآئِقَ غُلْبًۭا', 585, 30, 234, 0),
  (80, 31, 5789, 'وَفَٰكِهَةًۭ وَأَبًّۭا', 585, 30, 234, 0),
  (80, 32, 5790, 'مَّتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ', 585, 30, 234, 0),
  (80, 33, 5791, 'فَإِذَا جَآءَتِ ٱلصَّآخَّةُ', 585, 30, 234, 0),
  (80, 34, 5792, 'يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ', 585, 30, 234, 0),
  (80, 35, 5793, 'وَأُمِّهِۦ وَأَبِيهِ', 585, 30, 234, 0),
  (80, 36, 5794, 'وَصَٰحِبَتِهِۦ وَبَنِيهِ', 585, 30, 234, 0),
  (80, 37, 5795, 'لِكُلِّ ٱمْرِئٍۢ مِّنْهُمْ يَوْمَئِذٍۢ شَأْنٌۭ يُغْنِيهِ', 585, 30, 234, 0),
  (80, 38, 5796, 'وُجُوهٌۭ يَوْمَئِذٍۢ مُّسْفِرَةٌۭ', 585, 30, 234, 0),
  (80, 39, 5797, 'ضَاحِكَةٌۭ مُّسْتَبْشِرَةٌۭ', 585, 30, 234, 0),
  (80, 40, 5798, 'وَوُجُوهٌۭ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌۭ', 585, 30, 234, 0),
  (80, 41, 5799, 'تَرْهَقُهَا قَتَرَةٌ', 585, 30, 234, 0),
  (80, 42, 5800, 'أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ', 585, 30, 234, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 80, 1, 'The Prophet frowned and turned away'),
  ('en.sahih', 80, 2, 'Because there came to him the blind man, [interrupting].'),
  ('en.sahih', 80, 3, 'But what would make you perceive, [O Muhammad], that perhaps he might be purified'),
  ('en.sahih', 80, 4, 'Or be reminded and the remembrance would benefit him?'),
  ('en.sahih', 80, 5, 'As for he who thinks himself without need,'),
  ('en.sahih', 80, 6, 'To him you give attention.'),
  ('en.sahih', 80, 7, 'And not upon you [is any blame] if he will not be purified.'),
  ('en.sahih', 80, 8, 'But as for he who came to you striving [for knowledge]'),
  ('en.sahih', 80, 9, 'While he fears [Allah],'),
  ('en.sahih', 80, 10, 'From him you are distracted.'),
  ('en.sahih', 80, 11, 'No! Indeed, these verses are a reminder;'),
  ('en.sahih', 80, 12, 'So whoever wills may remember it.'),
  ('en.sahih', 80, 13, '[It is recorded] in honored sheets,'),
  ('en.sahih', 80, 14, 'Exalted and purified,'),
  ('en.sahih', 80, 15, '[Carried] by the hands of messenger-angels,'),
  ('en.sahih', 80, 16, 'Noble and dutiful.'),
  ('en.sahih', 80, 17, 'Cursed is man; how disbelieving is he.'),
  ('en.sahih', 80, 18, 'From what substance did He create him?'),
  ('en.sahih', 80, 19, 'From a sperm-drop He created him and destined for him;'),
  ('en.sahih', 80, 20, 'Then He eased the way for him;'),
  ('en.sahih', 80, 21, 'Then He causes his death and provides a grave for him.'),
  ('en.sahih', 80, 22, 'Then when He wills, He will resurrect him.'),
  ('en.sahih', 80, 23, 'No! Man has not yet accomplished what He commanded him.'),
  ('en.sahih', 80, 24, 'Then let mankind look at his food -'),
  ('en.sahih', 80, 25, 'How We poured down water in torrents,'),
  ('en.sahih', 80, 26, 'Then We broke open the earth, splitting [it with sprouts],'),
  ('en.sahih', 80, 27, 'And caused to grow within it grain'),
  ('en.sahih', 80, 28, 'And grapes and herbage'),
  ('en.sahih', 80, 29, 'And olive and palm trees'),
  ('en.sahih', 80, 30, 'And gardens of dense shrubbery'),
  ('en.sahih', 80, 31, 'And fruit and grass -'),
  ('en.sahih', 80, 32, '[As] enjoyment for you and your grazing livestock.'),
  ('en.sahih', 80, 33, 'But when there comes the Deafening Blast'),
  ('en.sahih', 80, 34, 'On the Day a man will flee from his brother'),
  ('en.sahih', 80, 35, 'And his mother and his father'),
  ('en.sahih', 80, 36, 'And his wife and his children,'),
  ('en.sahih', 80, 37, 'For every man, that Day, will be a matter adequate for him.'),
  ('en.sahih', 80, 38, '[Some] faces, that Day, will be bright -'),
  ('en.sahih', 80, 39, 'Laughing, rejoicing at good news.'),
  ('en.sahih', 80, 40, 'And [other] faces, that Day, will have upon them dust.'),
  ('en.sahih', 80, 41, 'Blackness will cover them.'),
  ('en.sahih', 80, 42, 'Those are the disbelievers, the wicked ones.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 80, 1, 'তিনি ভ্রূকুঞ্চিত করলেন এবং মুখ ফিরিয়ে নিলেন।'),
  ('bn.bengali', 80, 2, 'কারণ, তাঁর কাছে এক অন্ধ আগমন করল।'),
  ('bn.bengali', 80, 3, 'আপনি কি জানেন, সে হয়তো পরিশুদ্ধ হত,'),
  ('bn.bengali', 80, 4, 'অথবা উপদেশ গ্রহণ করতো এবং উপদেশ তার উপকার হত।'),
  ('bn.bengali', 80, 5, 'পরন্তু যে বেপরোয়া,'),
  ('bn.bengali', 80, 6, 'আপনি তার চিন্তায় মশগুল।'),
  ('bn.bengali', 80, 7, 'সে শুদ্ধ না হলে আপনার কোন দোষ নেই।'),
  ('bn.bengali', 80, 8, 'যে আপনার কাছে দৌড়ে আসলো'),
  ('bn.bengali', 80, 9, 'এমতাবস্থায় যে, সে ভয় করে,'),
  ('bn.bengali', 80, 10, 'আপনি তাকে অবজ্ঞা করলেন।'),
  ('bn.bengali', 80, 11, 'কখনও এরূপ করবেন না, এটা উপদেশবানী।'),
  ('bn.bengali', 80, 12, 'অতএব, যে ইচ্ছা করবে, সে একে গ্রহণ করবে।'),
  ('bn.bengali', 80, 13, 'এটা লিখিত আছে সম্মানিত,'),
  ('bn.bengali', 80, 14, 'উচ্চ পবিত্র পত্রসমূহে,'),
  ('bn.bengali', 80, 15, 'লিপিকারের হস্তে,'),
  ('bn.bengali', 80, 16, 'যারা মহৎ, পূত চরিত্র।'),
  ('bn.bengali', 80, 17, 'মানুষ ধ্বংস হোক, সে কত অকৃতজ্ঞ!'),
  ('bn.bengali', 80, 18, 'তিনি তাকে কি বস্তু থেকে সৃষ্টি করেছেন?'),
  ('bn.bengali', 80, 19, 'শুক্র থেকে তাকে সৃষ্টি করেছেন, অতঃপর তাকে সুপরিমিত করেছেন।'),
  ('bn.bengali', 80, 20, 'অতঃপর তার পথ সহজ করেছেন,'),
  ('bn.bengali', 80, 21, 'অতঃপর তার মৃত্যু ঘটান ও কবরস্থ করেন তাকে।'),
  ('bn.bengali', 80, 22, 'এরপর যখন ইচ্ছা করবেন তখন তাকে পুনরুজ্জীবিত করবেন।'),
  ('bn.bengali', 80, 23, 'সে কখনও কৃতজ্ঞ হয়নি, তিনি তাকে যা আদেশ করেছেন, সে তা পূর্ণ করেনি।'),
  ('bn.bengali', 80, 24, 'মানুষ তার খাদ্যের প্রতি লক্ষ্য করুক,'),
  ('bn.bengali', 80, 25, 'আমি আশ্চর্য উপায়ে পানি বর্ষণ করেছি,'),
  ('bn.bengali', 80, 26, 'এরপর আমি ভূমিকে বিদীর্ণ করেছি,'),
  ('bn.bengali', 80, 27, 'অতঃপর তাতে উৎপন্ন করেছি শস্য,'),
  ('bn.bengali', 80, 28, 'আঙ্গুর, শাক-সব্জি,'),
  ('bn.bengali', 80, 29, 'যয়তুন, খর্জূর,'),
  ('bn.bengali', 80, 30, 'ঘন উদ্যান,'),
  ('bn.bengali', 80, 31, 'ফল এবং ঘাস'),
  ('bn.bengali', 80, 32, 'তোমাদেরও তোমাদের চতুস্পদ জন্তুদের উপাকারার্থে।'),
  ('bn.bengali', 80, 33, 'অতঃপর যেদিন কর্ণবিদারক নাদ আসবে,'),
  ('bn.bengali', 80, 34, 'সেদিন পলায়ন করবে মানুষ তার ভ্রাতার কাছ থেকে,'),
  ('bn.bengali', 80, 35, 'তার মাতা, তার পিতা,'),
  ('bn.bengali', 80, 36, 'তার পত্নী ও তার সন্তানদের কাছ থেকে।'),
  ('bn.bengali', 80, 37, 'সেদিন প্রত্যেকেরই নিজের এক চিন্তা থাকবে, যা তাকে ব্যতিব্যস্ত করে রাখবে।'),
  ('bn.bengali', 80, 38, 'অনেক মুখমন্ডল সেদিন হবে উজ্জ্বল,'),
  ('bn.bengali', 80, 39, 'সহাস্য ও প্রফুল্ল।'),
  ('bn.bengali', 80, 40, 'এবং অনেক মুখমন্ডল সেদিন হবে ধুলি ধূসরিত।'),
  ('bn.bengali', 80, 41, 'তাদেরকে কালিমা আচ্ছন্ন করে রাখবে।'),
  ('bn.bengali', 80, 42, 'তারাই কাফের পাপিষ্ঠের দল।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 80, 1, 'He frowned and turned away'),
  ('en.pickthall', 80, 2, 'Because the blind man came unto him.'),
  ('en.pickthall', 80, 3, 'What could inform thee but that he might grow (in grace)'),
  ('en.pickthall', 80, 4, 'Or take heed and so the reminder might avail him?'),
  ('en.pickthall', 80, 5, 'As for him who thinketh himself independent,'),
  ('en.pickthall', 80, 6, 'Unto him thou payest regard.'),
  ('en.pickthall', 80, 7, 'Yet it is not thy concern if he grow not (in grace).'),
  ('en.pickthall', 80, 8, 'But as for him who cometh unto thee with earnest purpose'),
  ('en.pickthall', 80, 9, 'And hath fear,'),
  ('en.pickthall', 80, 10, 'From him thou art distracted.'),
  ('en.pickthall', 80, 11, 'Nay, but verily it is an Admonishment,'),
  ('en.pickthall', 80, 12, 'So let whosoever will pay heed to it,'),
  ('en.pickthall', 80, 13, 'On honoured leaves'),
  ('en.pickthall', 80, 14, 'Exalted, purified,'),
  ('en.pickthall', 80, 15, '(Set down) by scribes'),
  ('en.pickthall', 80, 16, 'Noble and righteous.'),
  ('en.pickthall', 80, 17, 'Man is (self-)destroyed: how ungrateful!'),
  ('en.pickthall', 80, 18, 'From what thing doth He create him?'),
  ('en.pickthall', 80, 19, 'From a drop of seed. He createth him and proportioneth him,'),
  ('en.pickthall', 80, 20, 'Then maketh the way easy for him,'),
  ('en.pickthall', 80, 21, 'Then causeth him to die, and burieth him;'),
  ('en.pickthall', 80, 22, 'Then, when He will, He bringeth him again to life.'),
  ('en.pickthall', 80, 23, 'Nay, but (man) hath not done what He commanded him.'),
  ('en.pickthall', 80, 24, 'Let man consider his food:'),
  ('en.pickthall', 80, 25, 'How We pour water in showers'),
  ('en.pickthall', 80, 26, 'Then split the earth in clefts'),
  ('en.pickthall', 80, 27, 'And cause the grain to grow therein'),
  ('en.pickthall', 80, 28, 'And grapes and green fodder'),
  ('en.pickthall', 80, 29, 'And olive-trees and palm-trees'),
  ('en.pickthall', 80, 30, 'And garden-closes of thick foliage'),
  ('en.pickthall', 80, 31, 'And fruits and grasses:'),
  ('en.pickthall', 80, 32, 'Provision for you and your cattle.'),
  ('en.pickthall', 80, 33, 'But when the Shout cometh'),
  ('en.pickthall', 80, 34, 'On the day when a man fleeth from his brother'),
  ('en.pickthall', 80, 35, 'And his mother and his father'),
  ('en.pickthall', 80, 36, 'And his wife and his children,'),
  ('en.pickthall', 80, 37, 'Every man that day will have concern enough to make him heedless (of others).'),
  ('en.pickthall', 80, 38, 'On that day faces will be bright as dawn,'),
  ('en.pickthall', 80, 39, 'Laughing, rejoicing at good news;'),
  ('en.pickthall', 80, 40, 'And other faces, on that day, with dust upon them,'),
  ('en.pickthall', 80, 41, 'Veiled in darkness,'),
  ('en.pickthall', 80, 42, 'Those are the disbelievers, the wicked.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 80, 1, '(The Prophet) frowned and turned away,'),
  ('en.yusufali', 80, 2, 'Because there came to him the blind man (interrupting).'),
  ('en.yusufali', 80, 3, 'But what could tell thee but that perchance he might grow (in spiritual understanding)?-'),
  ('en.yusufali', 80, 4, 'Or that he might receive admonition, and the teaching might profit him?'),
  ('en.yusufali', 80, 5, 'As to one who regards Himself as self-sufficient,'),
  ('en.yusufali', 80, 6, 'To him dost thou attend;'),
  ('en.yusufali', 80, 7, 'Though it is no blame to thee if he grow not (in spiritual understanding).'),
  ('en.yusufali', 80, 8, 'But as to him who came to thee striving earnestly,'),
  ('en.yusufali', 80, 9, 'And with fear (in his heart),'),
  ('en.yusufali', 80, 10, 'Of him wast thou unmindful.'),
  ('en.yusufali', 80, 11, 'By no means (should it be so)! For it is indeed a Message of instruction:'),
  ('en.yusufali', 80, 12, 'Therefore let whoso will, keep it in remembrance.'),
  ('en.yusufali', 80, 13, '(It is) in Books held (greatly) in honour,'),
  ('en.yusufali', 80, 14, 'Exalted (in dignity), kept pure and holy,'),
  ('en.yusufali', 80, 15, '(Written) by the hands of scribes-'),
  ('en.yusufali', 80, 16, 'Honourable and Pious and Just.'),
  ('en.yusufali', 80, 17, 'Woe to man! What hath made him reject Allah;'),
  ('en.yusufali', 80, 18, 'From what stuff hath He created him?'),
  ('en.yusufali', 80, 19, 'From a sperm-drop: He hath created him, and then mouldeth him in due proportions;'),
  ('en.yusufali', 80, 20, 'Then doth He make His path smooth for him;'),
  ('en.yusufali', 80, 21, 'Then He causeth him to die, and putteth him in his grave;'),
  ('en.yusufali', 80, 22, 'Then, when it is His Will, He will raise him up (again).'),
  ('en.yusufali', 80, 23, 'By no means hath he fulfilled what Allah hath commanded him.'),
  ('en.yusufali', 80, 24, 'Then let man look at his food, (and how We provide it):'),
  ('en.yusufali', 80, 25, 'For that We pour forth water in abundance,'),
  ('en.yusufali', 80, 26, 'And We split the earth in fragments,'),
  ('en.yusufali', 80, 27, 'And produce therein corn,'),
  ('en.yusufali', 80, 28, 'And Grapes and nutritious plants,'),
  ('en.yusufali', 80, 29, 'And Olives and Dates,'),
  ('en.yusufali', 80, 30, 'And enclosed Gardens, dense with lofty trees,'),
  ('en.yusufali', 80, 31, 'And fruits and fodder,-'),
  ('en.yusufali', 80, 32, 'For use and convenience to you and your cattle.'),
  ('en.yusufali', 80, 33, 'At length, when there comes the Deafening Noise,-'),
  ('en.yusufali', 80, 34, 'That Day shall a man flee from his own brother,'),
  ('en.yusufali', 80, 35, 'And from his mother and his father,'),
  ('en.yusufali', 80, 36, 'And from his wife and his children.'),
  ('en.yusufali', 80, 37, 'Each one of them, that Day, will have enough concern (of his own) to make him indifferent to the others.'),
  ('en.yusufali', 80, 38, 'Some faces that Day will be beaming,'),
  ('en.yusufali', 80, 39, 'Laughing, rejoicing.'),
  ('en.yusufali', 80, 40, 'And other faces that Day will be dust-stained,'),
  ('en.yusufali', 80, 41, 'Blackness will cover them:'),
  ('en.yusufali', 80, 42, 'Such will be the Rejecters of Allah, the doers of iniquity.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 80, 1, '\'Abasa wa tawallaa.'),
  ('en.transliteration', 80, 2, 'An jaa-ahul \'a-maa'),
  ('en.transliteration', 80, 3, 'Wa maa yudreeka la\'allahu yaz zakkaa.'),
  ('en.transliteration', 80, 4, 'Au yaz zak karu fatanfa \'ahuz zikraa.'),
  ('en.transliteration', 80, 5, 'Amma manis taghnaa'),
  ('en.transliteration', 80, 6, 'Fa-anta lahu tasaddaa'),
  ('en.transliteration', 80, 7, 'Wa ma \'alaika allaa yaz zakka.'),
  ('en.transliteration', 80, 8, 'Wa amma man jaa-aka yas\'a'),
  ('en.transliteration', 80, 9, 'Wahuwa yakhshaa,'),
  ('en.transliteration', 80, 10, 'Fa-anta \'anhu talah haa.'),
  ('en.transliteration', 80, 11, 'Kalla innaha tazkirah'),
  ('en.transliteration', 80, 12, 'Faman shaa a zakarah'),
  ('en.transliteration', 80, 13, 'Fi suhufim mukar rama,'),
  ('en.transliteration', 80, 14, 'Marfoo\'atim mutah hara,'),
  ('en.transliteration', 80, 15, 'Bi\'aidee safara'),
  ('en.transliteration', 80, 16, 'Kiraamim bararah.'),
  ('en.transliteration', 80, 17, 'Qutilal-insanu maa akfarah.'),
  ('en.transliteration', 80, 18, 'Min aiyyi shai-in Khalaq'),
  ('en.transliteration', 80, 19, 'Min nutfah; khalaqahu faqad-darah.'),
  ('en.transliteration', 80, 20, 'Thummas sabeela yas-sarah'),
  ('en.transliteration', 80, 21, 'Thumma amatahu fa-aqbarah'),
  ('en.transliteration', 80, 22, 'Thumma iza shaa-a ansharah'),
  ('en.transliteration', 80, 23, 'Kalla lamma yaqdi maa amarah.'),
  ('en.transliteration', 80, 24, 'Falyanzuril insanu ilaa ta-amih'),
  ('en.transliteration', 80, 25, 'Anna sabab nalmaa-a sabba.'),
  ('en.transliteration', 80, 26, 'Thumma sha qaqnal-arda shaqqa.'),
  ('en.transliteration', 80, 27, 'Fa ambatna feeha habba'),
  ('en.transliteration', 80, 28, 'Wa \'inabaw-wa qadba'),
  ('en.transliteration', 80, 29, 'Wa zaitoonaw wanakh la\''),
  ('en.transliteration', 80, 30, 'Wa hadaa-iqa ghulba'),
  ('en.transliteration', 80, 31, 'Wa faki hataw-wa abba.'),
  ('en.transliteration', 80, 32, 'Mata\'al-lakum wa li-an\'amikum.'),
  ('en.transliteration', 80, 33, 'Faiza jaa-atis saakhah.'),
  ('en.transliteration', 80, 34, 'Yauma yafir-rul mar-u min akheeh'),
  ('en.transliteration', 80, 35, 'Wa ummihee wa abeeh'),
  ('en.transliteration', 80, 36, 'Wa sahi batihee wa baneeh.'),
  ('en.transliteration', 80, 37, 'Likul limri-im-minuhm yaumaa-izin shaa nuy-yughneeh'),
  ('en.transliteration', 80, 38, 'Wujoo huny-yauma-izim-musfira;'),
  ('en.transliteration', 80, 39, 'Dahi katum mustab shirah'),
  ('en.transliteration', 80, 40, 'Wa wujoohuy yauma-izin \'alaiha ghabar a'),
  ('en.transliteration', 80, 41, 'Tarhaquha qatarah.'),
  ('en.transliteration', 80, 42, 'Ulaa-ika humul-kafa ratul-fajarah.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 80, 1, 'پیغمبر چین بجیں ہوئے اور منہ موڑ لیا'),
  ('ur.ahmedali', 80, 2, 'کہ ان کے پاس ایک اندھا آیا'),
  ('ur.ahmedali', 80, 3, 'اور آپ کو کیا معلوم کہ شاید وہ پاک ہوجائے'),
  ('ur.ahmedali', 80, 4, 'یا وہ نصیحت پکڑ لے تو اس کو نصیحت نفع دے'),
  ('ur.ahmedali', 80, 5, 'لیکن وہ جو پروا نہیں کرتا'),
  ('ur.ahmedali', 80, 6, 'سو آپ کے لیے توجہ کرتے ہیں'),
  ('ur.ahmedali', 80, 7, 'حالانکہ آپ پر اس کےنہ سدھرنے کا کوئی الزام نہیں'),
  ('ur.ahmedali', 80, 8, 'اور لیکن جو آپ کے پاس دوڑتا ہوا آیا'),
  ('ur.ahmedali', 80, 9, 'اور وہ ڈر رہا ہے'),
  ('ur.ahmedali', 80, 10, 'تو آپ اس سے بے پروائی کرتے ہیں'),
  ('ur.ahmedali', 80, 11, 'ایسا نہیں چاہیئے بے شک یہ تو ایک نصیحت ہے'),
  ('ur.ahmedali', 80, 12, 'پس جو چاہے اس کو یاد کرے'),
  ('ur.ahmedali', 80, 13, 'وہ عزت والے صحیفوں میں ہے'),
  ('ur.ahmedali', 80, 14, 'جو بلند مرتبہ اور پاک ہیں'),
  ('ur.ahmedali', 80, 15, 'ان لکھنے والوں کے ہاتھوں میں'),
  ('ur.ahmedali', 80, 16, 'جو بڑے بزرگ نیکو کار ہیں'),
  ('ur.ahmedali', 80, 17, 'انسان پر خدا کی مار وہ کیسا ناشکرا ہے'),
  ('ur.ahmedali', 80, 18, 'اس نے کس چیز سے اس کو بنایا'),
  ('ur.ahmedali', 80, 19, 'ایک بوند سے اس کوبنایا پھر اس کا اندزہ ٹھیرایا'),
  ('ur.ahmedali', 80, 20, 'پھراس پر راستہ آسان کر دیا'),
  ('ur.ahmedali', 80, 21, 'پھر اس کو موت دی پھر اس کو قبر میں رکھوایا'),
  ('ur.ahmedali', 80, 22, 'پھر جب چاہے گا اٹھا کر کھڑا کرے گا'),
  ('ur.ahmedali', 80, 23, 'ایسا نہیں چاہیئے اس نے تعمیل نہیں کی جو اس کو حکم دیا تھا'),
  ('ur.ahmedali', 80, 24, 'پس انسان کو اپنے کھانے کی طرف غور کرنا چاہیئے'),
  ('ur.ahmedali', 80, 25, 'کہ ہم نے اوپر سے مینہ برسایا'),
  ('ur.ahmedali', 80, 26, 'پھر ہم نے زمین کو چیر کر پھاڑا'),
  ('ur.ahmedali', 80, 27, 'پھر ہم نے اس میں اناج ا گایا'),
  ('ur.ahmedali', 80, 28, 'اورانگور اور ترکاریاں'),
  ('ur.ahmedali', 80, 29, 'اور زیتون اور کھجور'),
  ('ur.ahmedali', 80, 30, 'اور گھنے باغ'),
  ('ur.ahmedali', 80, 31, 'اور میوے اور گھاس'),
  ('ur.ahmedali', 80, 32, 'تمہارے لیے اور تمہارے چار پایوں کے لیے سامان حیات'),
  ('ur.ahmedali', 80, 33, 'پھر جس وقت کانوں کا بہرا کرنے والا شور برپا ہوگا'),
  ('ur.ahmedali', 80, 34, 'جس دن آدمی اپنے بھائی سے بھاگے گا'),
  ('ur.ahmedali', 80, 35, 'اور اپنی ماں اور باپ سے'),
  ('ur.ahmedali', 80, 36, 'اور اپنی بیوی اوراپنے بیٹوں سے'),
  ('ur.ahmedali', 80, 37, 'ہر شخص کی ایسی حالت ہوگی جو اس کو اوروں کی طرف سے بے پروا کر دے گی'),
  ('ur.ahmedali', 80, 38, 'اورکچھ چہرے اس دن چمک رہے ہوں گے'),
  ('ur.ahmedali', 80, 39, 'ہنستے ہوئے خوش و خرم'),
  ('ur.ahmedali', 80, 40, 'اور کچھ چہرے اس دن ایسے ہوں گے کہ ان پر گرد پڑی ہو گی'),
  ('ur.ahmedali', 80, 41, 'ان پر سیاہی چھا رہی ہو گی'),
  ('ur.ahmedali', 80, 42, 'یہی لوگ ہیں منکر نافرمان')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 80, 1, 'Yanına kör bir kimse geldi diye (Peygamber) yüzünü asıp çevirdi.'),
  ('tr.diyanet', 80, 2, 'Yanına kör bir kimse geldi diye (Peygamber) yüzünü asıp çevirdi.'),
  ('tr.diyanet', 80, 3, 'Ne bilirsin, belki de o arınacak;'),
  ('tr.diyanet', 80, 4, 'Yahut öğüt alacaktı da bu öğüt kendisine fayda verecekti.'),
  ('tr.diyanet', 80, 5, 'Ama sen, kendisini öğütten müstağni gören kimseyi karşına alıp ilgileniyorsun.'),
  ('tr.diyanet', 80, 6, 'Ama sen, kendisini öğütten müstağni gören kimseyi karşına alıp ilgileniyorsun.'),
  ('tr.diyanet', 80, 7, 'Arınmak istememesinden sana ne?'),
  ('tr.diyanet', 80, 8, 'Sen, Allah\'tan korkup sana koşarak gelen kimseye aldırmıyorsun.'),
  ('tr.diyanet', 80, 9, 'Sen, Allah\'tan korkup sana koşarak gelen kimseye aldırmıyorsun.'),
  ('tr.diyanet', 80, 10, 'Sen, Allah\'tan korkup sana koşarak gelen kimseye aldırmıyorsun.'),
  ('tr.diyanet', 80, 11, 'Dikkat et; bu Kuran bir öğüttür.'),
  ('tr.diyanet', 80, 12, 'Dileyen onu öğüt kabul eder.'),
  ('tr.diyanet', 80, 13, 'O, kutsal kılınmış, yüceltilmiş, arınmış sahifeler üzerindedir.'),
  ('tr.diyanet', 80, 14, 'O, kutsal kılınmış, yüceltilmiş, arınmış sahifeler üzerindedir.'),
  ('tr.diyanet', 80, 15, 'İyi kimseler, saygıdeğer elçilerin eliyle yazılmıştır.'),
  ('tr.diyanet', 80, 16, 'İyi kimseler, saygıdeğer elçilerin eliyle yazılmıştır.'),
  ('tr.diyanet', 80, 17, 'Canı çıksın o insanın, o ne nankördür!'),
  ('tr.diyanet', 80, 18, 'Allah onu hangi şeyden yaratmış?'),
  ('tr.diyanet', 80, 19, 'Onu meniden yaratıp merhalelerden geçirerek ona şekil vermiş;'),
  ('tr.diyanet', 80, 20, 'Sonra, yolu ona kolaylaştırmıştır.'),
  ('tr.diyanet', 80, 21, 'Sonra onu öldürür ve kabre koyar.'),
  ('tr.diyanet', 80, 22, 'Sonra, dilediği zaman onu tekrar diriltir.'),
  ('tr.diyanet', 80, 23, 'Hayır; Allah\'ın kendisine buyurduğunu hala yerine getirmemiştir.'),
  ('tr.diyanet', 80, 24, 'İnsan, yiyeceğine bir baksın;'),
  ('tr.diyanet', 80, 25, 'Doğrusu suyu bol bol indirmekteyiz.'),
  ('tr.diyanet', 80, 26, 'Sonra yeryüzünü iyice yarmakta ve orada taneli ekinler, üzümler, sebzeler, zeytin, hurma ağaçları ve bahçelerde koca koca ağaçlı meyveler ve çayırlar bitirmekteyiz.'),
  ('tr.diyanet', 80, 27, 'Sonra yeryüzünü iyice yarmakta ve orada taneli ekinler, üzümler, sebzeler, zeytin, hurma ağaçları ve bahçelerde koca koca ağaçlı meyveler ve çayırlar bitirmekteyiz.'),
  ('tr.diyanet', 80, 28, 'Sonra yeryüzünü iyice yarmakta ve orada taneli ekinler, üzümler, sebzeler, zeytin, hurma ağaçları ve bahçelerde koca koca ağaçlı meyveler ve çayırlar bitirmekteyiz.'),
  ('tr.diyanet', 80, 29, 'Sonra yeryüzünü iyice yarmakta ve orada taneli ekinler, üzümler, sebzeler, zeytin, hurma ağaçları ve bahçelerde koca koca ağaçlı meyveler ve çayırlar bitirmekteyiz.'),
  ('tr.diyanet', 80, 30, 'Sonra yeryüzünü iyice yarmakta ve orada taneli ekinler, üzümler, sebzeler, zeytin, hurma ağaçları ve bahçelerde koca koca ağaçlı meyveler ve çayırlar bitirmekteyiz.'),
  ('tr.diyanet', 80, 31, 'Sonra yeryüzünü iyice yarmakta ve orada taneli ekinler, üzümler, sebzeler, zeytin, hurma ağaçları ve bahçelerde koca koca ağaçlı meyveler ve çayırlar bitirmekteyiz.'),
  ('tr.diyanet', 80, 32, 'Bunlar sizin ve hayvanlarınız için geçimliktir.'),
  ('tr.diyanet', 80, 33, 'O muazzam gürültü, kıyamet kopup geldiği zaman;'),
  ('tr.diyanet', 80, 34, 'O gün, kişi kardeşinden, annesinden, babasından, karısından ve oğullarından, kaçar.'),
  ('tr.diyanet', 80, 35, 'O gün, kişi kardeşinden, annesinden, babasından, karısından ve oğullarından, kaçar.'),
  ('tr.diyanet', 80, 36, 'O gün, kişi kardeşinden, annesinden, babasından, karısından ve oğullarından, kaçar.'),
  ('tr.diyanet', 80, 37, 'O gün, herkesin kendine yeter derdi vardır.'),
  ('tr.diyanet', 80, 38, 'O gün bir takım yüzler aydınlıktır, gülmekte ve sevinmektedir.'),
  ('tr.diyanet', 80, 39, 'O gün bir takım yüzler aydınlıktır, gülmekte ve sevinmektedir.'),
  ('tr.diyanet', 80, 40, 'O gün birtakım yüzler de tozlanmış ve onları karanlık bürümüştür.'),
  ('tr.diyanet', 80, 41, 'O gün birtakım yüzler de tozlanmış ve onları karanlık bürümüştür.'),
  ('tr.diyanet', 80, 42, 'İşte bunlar inkarcı olanlar, Allah\'ın buyruğundan çıkanlardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 80, 1, 'Dia (Muhammad) bermuka masam dan berpaling,'),
  ('id.indonesian', 80, 2, 'karena telah datang seorang buta kepadanya.'),
  ('id.indonesian', 80, 3, 'Tahukah kamu barangkali ia ingin membersihkan dirinya (dari dosa),'),
  ('id.indonesian', 80, 4, 'atau dia (ingin) mendapatkan pengajaran, lalu pengajaran itu memberi manfaat kepadanya?'),
  ('id.indonesian', 80, 5, 'Adapun orang yang merasa dirinya serba cukup,'),
  ('id.indonesian', 80, 6, 'maka kamu melayaninya.'),
  ('id.indonesian', 80, 7, 'Padahal tidak ada (celaan) atasmu kalau dia tidak membersihkan diri (beriman).'),
  ('id.indonesian', 80, 8, 'Dan adapun orang yang datang kepadamu dengan bersegera (untuk mendapatkan pengajaran),'),
  ('id.indonesian', 80, 9, 'sedang ia takut kepada (Allah),'),
  ('id.indonesian', 80, 10, 'maka kamu mengabaikannya.'),
  ('id.indonesian', 80, 11, 'Sekali-kali jangan (demikian)! Sesungguhnya ajaran-ajaran Tuhan itu adalah suatu peringatan,'),
  ('id.indonesian', 80, 12, 'maka barangsiapa yang menghendaki, tentulah ia memperhatikannya,'),
  ('id.indonesian', 80, 13, 'di dalam kitab-kitab yang dimuliakan,'),
  ('id.indonesian', 80, 14, 'yang ditinggikan lagi disucikan,'),
  ('id.indonesian', 80, 15, 'di tangan para penulis (malaikat),'),
  ('id.indonesian', 80, 16, 'yang mulia lagi berbakti.'),
  ('id.indonesian', 80, 17, 'Binasalah manusia; alangkah amat sangat kekafirannya?'),
  ('id.indonesian', 80, 18, 'Dari apakah Allah menciptakannya?'),
  ('id.indonesian', 80, 19, 'Dari setetes mani, Allah menciptakannya lalu menentukannya.'),
  ('id.indonesian', 80, 20, 'Kemudian Dia memudahkan jalannya.'),
  ('id.indonesian', 80, 21, 'kemudian Dia mematikannya dan memasukkannya ke dalam kubur,'),
  ('id.indonesian', 80, 22, 'kemudian bila Dia menghendaki, Dia membangkitkannya kembali.'),
  ('id.indonesian', 80, 23, 'Sekali-kali jangan; manusia itu belum melaksanakan apa yang diperintahkan Allah kepadanya,'),
  ('id.indonesian', 80, 24, 'maka hendaklah manusia itu memperhatikan makanannya.'),
  ('id.indonesian', 80, 25, 'Sesungguhnya Kami benar-benar telah mencurahkan air (dari langit),'),
  ('id.indonesian', 80, 26, 'kemudian Kami belah bumi dengan sebaik-baiknya,'),
  ('id.indonesian', 80, 27, 'lalu Kami tumbuhkan biji-bijian di bumi itu,'),
  ('id.indonesian', 80, 28, 'anggur dan sayur-sayuran,'),
  ('id.indonesian', 80, 29, 'zaitun dan kurma,'),
  ('id.indonesian', 80, 30, 'kebun-kebun (yang) lebat,'),
  ('id.indonesian', 80, 31, 'dan buah-buahan serta rumput-rumputan,'),
  ('id.indonesian', 80, 32, 'untuk kesenanganmu dan untuk binatang-binatang ternakmu.'),
  ('id.indonesian', 80, 33, 'Dan apabila datang suara yang memekakkan (tiupan sangkakala yang kedua),'),
  ('id.indonesian', 80, 34, 'pada hari ketika manusia lari dari saudaranya,'),
  ('id.indonesian', 80, 35, 'dari ibu dan bapaknya,'),
  ('id.indonesian', 80, 36, 'dari istri dan anak-anaknya.'),
  ('id.indonesian', 80, 37, 'Setiap orang dari mereka pada hari itu mempunyai urusan yang cukup menyibukkannya.'),
  ('id.indonesian', 80, 38, 'Banyak muka pada hari itu berseri-seri,'),
  ('id.indonesian', 80, 39, 'tertawa dan bergembira ria,'),
  ('id.indonesian', 80, 40, 'dan banyak (pula) muka pada hari itu tertutup debu,'),
  ('id.indonesian', 80, 41, 'dan ditutup lagi oleh kegelapan.'),
  ('id.indonesian', 80, 42, 'Mereka itulah orang-orang kafir lagi durhaka.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 81, 1, 'When the sun is wrapped up [in darkness]'),
  ('en.sahih', 81, 2, 'And when the stars fall, dispersing,'),
  ('en.sahih', 81, 3, 'And when the mountains are removed'),
  ('en.sahih', 81, 4, 'And when full-term she-camels are neglected'),
  ('en.sahih', 81, 5, 'And when the wild beasts are gathered'),
  ('en.sahih', 81, 6, 'And when the seas are filled with flame'),
  ('en.sahih', 81, 7, 'And when the souls are paired'),
  ('en.sahih', 81, 8, 'And when the girl [who was] buried alive is asked'),
  ('en.sahih', 81, 9, 'For what sin she was killed'),
  ('en.sahih', 81, 10, 'And when the pages are made public'),
  ('en.sahih', 81, 11, 'And when the sky is stripped away'),
  ('en.sahih', 81, 12, 'And when Hellfire is set ablaze'),
  ('en.sahih', 81, 13, 'And when Paradise is brought near,'),
  ('en.sahih', 81, 14, 'A soul will [then] know what it has brought [with it].'),
  ('en.sahih', 81, 15, 'So I swear by the retreating stars -'),
  ('en.sahih', 81, 16, 'Those that run [their courses] and disappear -'),
  ('en.sahih', 81, 17, 'And by the night as it closes in'),
  ('en.sahih', 81, 18, 'And by the dawn when it breathes'),
  ('en.sahih', 81, 19, '[That] indeed, the Qur\'an is a word [conveyed by] a noble messenger'),
  ('en.sahih', 81, 20, '[Who is] possessed of power and with the Owner of the Throne, secure [in position],'),
  ('en.sahih', 81, 21, 'Obeyed there [in the heavens] and trustworthy.'),
  ('en.sahih', 81, 22, 'And your companion is not [at all] mad.'),
  ('en.sahih', 81, 23, 'And he has already seen Gabriel in the clear horizon.'),
  ('en.sahih', 81, 24, 'And Muhammad is not a withholder of [knowledge of] the unseen.'),
  ('en.sahih', 81, 25, 'And the Qur\'an is not the word of a devil, expelled [from the heavens].'),
  ('en.sahih', 81, 26, 'So where are you going?'),
  ('en.sahih', 81, 27, 'It is not except a reminder to the worlds'),
  ('en.sahih', 81, 28, 'For whoever wills among you to take a right course.'),
  ('en.sahih', 81, 29, 'And you do not will except that Allah wills - Lord of the worlds.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 81, 1, 'যখন সূর্য আলোহীন হয়ে যাবে,'),
  ('bn.bengali', 81, 2, 'যখন নক্ষত্র মলিন হয়ে যাবে,'),
  ('bn.bengali', 81, 3, 'যখন পর্বতমালা অপসারিত হবে,'),
  ('bn.bengali', 81, 4, 'যখন দশ মাসের গর্ভবতী উষ্ট্রীসমূহ উপেক্ষিত হবে;'),
  ('bn.bengali', 81, 5, 'যখন বন্য পশুরা একত্রিত হয়ে যাবে,'),
  ('bn.bengali', 81, 6, 'যখন সমুদ্রকে উত্তাল করে তোলা হবে,'),
  ('bn.bengali', 81, 7, 'যখন আত্মাসমূহকে যুগল করা হবে,'),
  ('bn.bengali', 81, 8, 'যখন জীবন্ত প্রোথিত কন্যাকে জিজ্ঞেস করা হবে,'),
  ('bn.bengali', 81, 9, 'কি অপরাধে তাকে হত্য করা হল?'),
  ('bn.bengali', 81, 10, 'যখন আমলনামা খোলা হবে,'),
  ('bn.bengali', 81, 11, 'যখন আকাশের আবরণ অপসারিত হবে,'),
  ('bn.bengali', 81, 12, 'যখন জাহান্নামের অগ্নি প্রজ্বলিত করা হবে'),
  ('bn.bengali', 81, 13, 'এবং যখন জান্নাত সন্নিকটবর্তী হবে,'),
  ('bn.bengali', 81, 14, 'তখন প্রত্যেকেই জেনে নিবে সে কি উপস্থিত করেছে।'),
  ('bn.bengali', 81, 15, 'আমি শপথ করি যেসব নক্ষত্রগুলো পশ্চাতে সরে যায়।'),
  ('bn.bengali', 81, 16, 'চলমান হয় ও অদৃশ্য হয়,'),
  ('bn.bengali', 81, 17, 'শপথ নিশাবসান ও'),
  ('bn.bengali', 81, 18, 'প্রভাত আগমন কালের,'),
  ('bn.bengali', 81, 19, 'নিশ্চয় কোরআন সম্মানিত রসূলের আনীত বাণী,'),
  ('bn.bengali', 81, 20, 'যিনি শক্তিশালী, আরশের মালিকের নিকট মর্যাদাশালী,'),
  ('bn.bengali', 81, 21, 'সবার মান্যবর, সেখানকার বিশ্বাসভাজন।'),
  ('bn.bengali', 81, 22, 'এবং তোমাদের সাথী পাগল নন।'),
  ('bn.bengali', 81, 23, 'তিনি সেই ফেরেশতাকে প্রকাশ্য দিগন্তে দেখেছেন।'),
  ('bn.bengali', 81, 24, 'তিনি অদৃশ্য বিষয় বলতে কৃপনতা করেন না।'),
  ('bn.bengali', 81, 25, 'এটা বিতাড়িত শয়তানের উক্তি নয়।'),
  ('bn.bengali', 81, 26, 'অতএব, তোমরা কোথায় যাচ্ছ?'),
  ('bn.bengali', 81, 27, 'এটা তো কেবল বিশ্বাবাসীদের জন্যে উপদেশ,'),
  ('bn.bengali', 81, 28, 'তার জন্যে, যে তোমাদের মধ্যে সোজা চলতে চায়।'),
  ('bn.bengali', 81, 29, 'তোমরা আল্লাহ রাব্বুল আলামীনের অভিপ্রায়ের বাইরে অন্য কিছুই ইচ্ছা করতে পার না।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 81, 1, 'When the sun is overthrown,'),
  ('en.pickthall', 81, 2, 'And when the stars fall,'),
  ('en.pickthall', 81, 3, 'And when the hills are moved,'),
  ('en.pickthall', 81, 4, 'And when the camels big with young are abandoned,'),
  ('en.pickthall', 81, 5, 'And when the wild beasts are herded together,'),
  ('en.pickthall', 81, 6, 'And when the seas rise,'),
  ('en.pickthall', 81, 7, 'And when souls are reunited,'),
  ('en.pickthall', 81, 8, 'And when the girl-child that was buried alive is asked'),
  ('en.pickthall', 81, 9, 'For what sin she was slain,'),
  ('en.pickthall', 81, 10, 'And when the pages are laid open,'),
  ('en.pickthall', 81, 11, 'And when the sky is torn away,'),
  ('en.pickthall', 81, 12, 'And when hell is lighted,'),
  ('en.pickthall', 81, 13, 'And when the Garden is brought nigh,'),
  ('en.pickthall', 81, 14, '(Then) every soul will know what it hath made ready.'),
  ('en.pickthall', 81, 15, 'Oh, but I call to witness the planets,'),
  ('en.pickthall', 81, 16, 'The stars which rise and set,'),
  ('en.pickthall', 81, 17, 'And the close of night,'),
  ('en.pickthall', 81, 18, 'And the breath of morning'),
  ('en.pickthall', 81, 19, 'That this is in truth the word of an honoured messenger,'),
  ('en.pickthall', 81, 20, 'Mighty, established in the presence of the Lord of the Throne,'),
  ('en.pickthall', 81, 21, '(One) to be obeyed, and trustworthy;'),
  ('en.pickthall', 81, 22, 'And your comrade is not mad.'),
  ('en.pickthall', 81, 23, 'Surely he beheld Him on the clear horizon.'),
  ('en.pickthall', 81, 24, 'And he is not avid of the Unseen.'),
  ('en.pickthall', 81, 25, 'Nor is this the utterance of a devil worthy to be stoned.'),
  ('en.pickthall', 81, 26, 'Whither then go ye?'),
  ('en.pickthall', 81, 27, 'This is naught else than a reminder unto creation,'),
  ('en.pickthall', 81, 28, 'Unto whomsoever of you willeth to walk straight.'),
  ('en.pickthall', 81, 29, 'And ye will not, unless (it be) that Allah willeth, the Lord of Creation.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 81, 1, 'When the sun (with its spacious light) is folded up;'),
  ('en.yusufali', 81, 2, 'When the stars fall, losing their lustre;'),
  ('en.yusufali', 81, 3, 'When the mountains vanish (like a mirage);'),
  ('en.yusufali', 81, 4, 'When the she-camels, ten months with young, are left untended;'),
  ('en.yusufali', 81, 5, 'When the wild beasts are herded together (in the human habitations);'),
  ('en.yusufali', 81, 6, 'When the oceans boil over with a swell;'),
  ('en.yusufali', 81, 7, 'When the souls are sorted out, (being joined, like with like);'),
  ('en.yusufali', 81, 8, 'When the female (infant), buried alive, is questioned -'),
  ('en.yusufali', 81, 9, 'For what crime she was killed;'),
  ('en.yusufali', 81, 10, 'When the scrolls are laid open;'),
  ('en.yusufali', 81, 11, 'When the world on High is unveiled;'),
  ('en.yusufali', 81, 12, 'When the Blazing Fire is kindled to fierce heat;'),
  ('en.yusufali', 81, 13, 'And when the Garden is brought near;-'),
  ('en.yusufali', 81, 14, '(Then) shall each soul know what it has put forward.'),
  ('en.yusufali', 81, 15, 'So verily I call to witness the planets - that recede,'),
  ('en.yusufali', 81, 16, 'Go straight, or hide;'),
  ('en.yusufali', 81, 17, 'And the Night as it dissipates;'),
  ('en.yusufali', 81, 18, 'And the Dawn as it breathes away the darkness;-'),
  ('en.yusufali', 81, 19, 'Verily this is the word of a most honourable Messenger,'),
  ('en.yusufali', 81, 20, 'Endued with Power, with rank before the Lord of the Throne,'),
  ('en.yusufali', 81, 21, 'With authority there, (and) faithful to his trust.'),
  ('en.yusufali', 81, 22, 'And (O people!) your companion is not one possessed;'),
  ('en.yusufali', 81, 23, 'And without doubt he saw him in the clear horizon.'),
  ('en.yusufali', 81, 24, 'Neither doth he withhold grudgingly a knowledge of the Unseen.'),
  ('en.yusufali', 81, 25, 'Nor is it the word of an evil spirit accursed.'),
  ('en.yusufali', 81, 26, 'When whither go ye?'),
  ('en.yusufali', 81, 27, 'Verily this is no less than a Message to (all) the Worlds:'),
  ('en.yusufali', 81, 28, '(With profit) to whoever among you wills to go straight:'),
  ('en.yusufali', 81, 29, 'But ye shall not will except as Allah wills,- the Cherisher of the Worlds.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 81, 1, 'Izash shamsu kuwwirat'),
  ('en.transliteration', 81, 2, 'Wa izan nujoomun kadarat'),
  ('en.transliteration', 81, 3, 'Wa izal jibaalu suyyirat'),
  ('en.transliteration', 81, 4, 'Wa izal \'ishaaru \'uttilat'),
  ('en.transliteration', 81, 5, 'Wa izal wuhooshu hushirat'),
  ('en.transliteration', 81, 6, 'Wa izal bihaaru sujjirat'),
  ('en.transliteration', 81, 7, 'Wa izan nufoosu zuwwijat'),
  ('en.transliteration', 81, 8, 'Wa izal maw\'oodatu su\'ilat'),
  ('en.transliteration', 81, 9, 'Bi ayyi zambin qutilat'),
  ('en.transliteration', 81, 10, 'Wa izas suhufu nushirat'),
  ('en.transliteration', 81, 11, 'Wa izas samaaa\'u kushitat'),
  ('en.transliteration', 81, 12, 'Wa izal jaheemu su\'-\'irat'),
  ('en.transliteration', 81, 13, 'Wa izal jannatu uzlifat'),
  ('en.transliteration', 81, 14, '\'Alimat nafsum maaa ahdarat'),
  ('en.transliteration', 81, 15, 'Falaaa uqsimu bil khunnas'),
  ('en.transliteration', 81, 16, 'Al jawaaril kunnas'),
  ('en.transliteration', 81, 17, 'Wallaili izaa \'as\'as'),
  ('en.transliteration', 81, 18, 'Wassubhi izaa tanaffas'),
  ('en.transliteration', 81, 19, 'Innahoo laqawlu rasoolin kareem'),
  ('en.transliteration', 81, 20, 'Zee quwwatin \'inda zil \'arshi makeen'),
  ('en.transliteration', 81, 21, 'Mutaa\'in samma ameen'),
  ('en.transliteration', 81, 22, 'Wa maa saahibukum bimajnoon'),
  ('en.transliteration', 81, 23, 'Wa laqad ra aahu bilufuqil mubeen'),
  ('en.transliteration', 81, 24, 'Wa maa huwa \'alal ghaibi bidaneen'),
  ('en.transliteration', 81, 25, 'Wa maa huwa biqawli shaitaanir rajeem'),
  ('en.transliteration', 81, 26, 'Fa ayna tazhaboon'),
  ('en.transliteration', 81, 27, 'In huwa illaa zikrul lil\'aalameen'),
  ('en.transliteration', 81, 28, 'Liman shaaa\'a minkum ai yastaqeem'),
  ('en.transliteration', 81, 29, 'Wa maa tashaaa\'oona illaaa ai yashaaa \'al laahu Rabbul \'Aalameen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 81, 1, 'جب سورج کی روشنی لپیٹی جائے'),
  ('ur.ahmedali', 81, 2, 'اور جب ستارے گر جائیں'),
  ('ur.ahmedali', 81, 3, 'اور جب پہاڑ چلائے جائیں'),
  ('ur.ahmedali', 81, 4, 'اور جب دس مہینے کی گابھن اونٹنیاں چھوڑ دی جائیں'),
  ('ur.ahmedali', 81, 5, 'اور جب جنگلی جانور اکھٹے ہوجائیں'),
  ('ur.ahmedali', 81, 6, 'اور جب سمندر جوش دیئے جائیں'),
  ('ur.ahmedali', 81, 7, 'اور جب جانیں جسموں سے ملائی جائیں'),
  ('ur.ahmedali', 81, 8, 'اور جب زندہ درگور لڑکی سے پوچھا جائے'),
  ('ur.ahmedali', 81, 9, 'کہ کس گناہ پر ماری گئی تھی'),
  ('ur.ahmedali', 81, 10, 'اور جب اعمال نامے کھل جائیں'),
  ('ur.ahmedali', 81, 11, 'اور آسمان کا پوست اتارا جائے'),
  ('ur.ahmedali', 81, 12, 'اورجب دوزخ دھکائی جائے'),
  ('ur.ahmedali', 81, 13, 'اورجب جنت قریب لائی جائے'),
  ('ur.ahmedali', 81, 14, 'تو ہر شخص جان لے گا کہ وہ کیا لے کر آیا ہے'),
  ('ur.ahmedali', 81, 15, 'پس میں قسم کھاتا ہوں پیچھے ہٹنے والے'),
  ('ur.ahmedali', 81, 16, 'سیدھے چلنے والے غیب ہو جانے والے ستارو ں کی'),
  ('ur.ahmedali', 81, 17, 'اور قسم ہے رات کی جب وہ جانے لگے'),
  ('ur.ahmedali', 81, 18, 'اور قسم ہے صبح کی جب وہ آنے لگے'),
  ('ur.ahmedali', 81, 19, 'بے شک یہ قرآن ایک معزز رسول کا لایا ہوا ہے'),
  ('ur.ahmedali', 81, 20, 'جو بڑا طاقتور ہے عرش کے مالک کے نزدیک بڑے رتبہ والا ہے'),
  ('ur.ahmedali', 81, 21, 'وہاں کا سردار امانت دار ہے'),
  ('ur.ahmedali', 81, 22, 'اور تمہارا رفیق کوئی دیوانہ نہیں ہے'),
  ('ur.ahmedali', 81, 23, 'اور اس نے اس کو کُھلے کنارے پر دیکھا بھی ہے'),
  ('ur.ahmedali', 81, 24, 'اور وہ غیب کی باتوں پر بخیل نہیں ہے'),
  ('ur.ahmedali', 81, 25, 'اور وہ کسی شیطان مردود کا قول نہیں ہے'),
  ('ur.ahmedali', 81, 26, 'پس تم کہاں چلے جا رہے ہو'),
  ('ur.ahmedali', 81, 27, 'یہ تو جہان بھرکے لیے نصیحت ہی نصیحت ہے'),
  ('ur.ahmedali', 81, 28, 'اس کے لیے جو تم میں سے سیدھا چلنا چاہے'),
  ('ur.ahmedali', 81, 29, 'اور تم توجب ہی چاہو گے کہ جب الله چاہے گا جو تمام جہان کا رب ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 81, 1, 'Güneş dürülüp ışığı kalmadığı zaman;'),
  ('tr.diyanet', 81, 2, 'Yıldızlar düşüp, söndüğü zaman;'),
  ('tr.diyanet', 81, 3, 'Doğurması yaklaşmış develer başıboş bırakıldığı zaman;'),
  ('tr.diyanet', 81, 4, 'Doğurması yaklaşmış develer başıboş bırakıldığı zaman;'),
  ('tr.diyanet', 81, 5, 'Yabani hayvanlar bir araya toplatıldığı zaman;'),
  ('tr.diyanet', 81, 6, 'Denizler kaynaştırıldığı zaman;'),
  ('tr.diyanet', 81, 7, 'Canlar bedenlerle birleştirildiği zaman;'),
  ('tr.diyanet', 81, 8, 'Kız çocuğun hangi suçtan ötürü öldürüldüğü kendisine sorulduğu zaman;'),
  ('tr.diyanet', 81, 9, 'Kız çocuğun hangi suçtan ötürü öldürüldüğü kendisine sorulduğu zaman;'),
  ('tr.diyanet', 81, 10, 'Amel defterleri açıldığı zaman;'),
  ('tr.diyanet', 81, 11, 'Gök yerinden oynatıldığı zaman;'),
  ('tr.diyanet', 81, 12, 'Cehennem alevlendirildiği zaman;'),
  ('tr.diyanet', 81, 13, 'Cennet yaklaştırıldığı zaman;'),
  ('tr.diyanet', 81, 14, 'İnsanoğlu önceden ne hazırladığını görecektir.'),
  ('tr.diyanet', 81, 15, 'Gündüz sinip geceleri gözüken gezegenlere and olsun;'),
  ('tr.diyanet', 81, 16, 'Gündüz sinip geceleri gözüken gezegenlere and olsun;'),
  ('tr.diyanet', 81, 17, 'Kararmaya başlayan geceye and olsun;'),
  ('tr.diyanet', 81, 18, 'Ağarmaya başlayan sabaha and olsun ki,'),
  ('tr.diyanet', 81, 19, 'Bu Kuran, arşın sahibi katında değerli, güçlü, sözü dinlenen ve güvenilen şerefli bir elçinin getirdiği sözdür.'),
  ('tr.diyanet', 81, 20, 'Bu Kuran, arşın sahibi katında değerli, güçlü, sözü dinlenen ve güvenilen şerefli bir elçinin getirdiği sözdür.'),
  ('tr.diyanet', 81, 21, 'Bu Kuran, arşın sahibi katında değerli, güçlü, sözü dinlenen ve güvenilen şerefli bir elçinin getirdiği sözdür.'),
  ('tr.diyanet', 81, 22, 'Arkadaşınız (Muhammed) asla deli değildir.'),
  ('tr.diyanet', 81, 23, 'And olsun ki, o, Cebrail\'i apaçık ufukta görmüştür.'),
  ('tr.diyanet', 81, 24, 'Peygamber, görülmeyenler hakkında söylediklerinden ötürü töhmet altında tutulamaz.'),
  ('tr.diyanet', 81, 25, 'Bu Kuran, kovulmuş şeytanın sözü olamaz.'),
  ('tr.diyanet', 81, 26, 'Nereye gidiyorsunuz?'),
  ('tr.diyanet', 81, 27, 'Kuran, ancak aranızda doğru yola girmeyi dileyene ve alemlere bir öğüttür.'),
  ('tr.diyanet', 81, 28, 'Kuran, ancak aranızda doğru yola girmeyi dileyene ve alemlere bir öğüttür.'),
  ('tr.diyanet', 81, 29, 'Alemlerin Rabbi olan Allah dilemedikçe sizler bir şey dileyemezsiniz.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 81, 1, 'Apabila matahari digulung,'),
  ('id.indonesian', 81, 2, 'dan apabila bintang-bintang berjatuhan,'),
  ('id.indonesian', 81, 3, 'dan apabila gunung-gunung dihancurkan,'),
  ('id.indonesian', 81, 4, 'dan apabila unta-unta yang bunting ditinggalkan (tidak diperdulikan)'),
  ('id.indonesian', 81, 5, 'dan apabila binatang-binatang liar dikumpulkan,'),
  ('id.indonesian', 81, 6, 'dan apabila lautan dijadikan meluap'),
  ('id.indonesian', 81, 7, 'dan apabila ruh-ruh dipertemukan (dengan tubuh)'),
  ('id.indonesian', 81, 8, 'dan apabila bayi-bayi perempuan yang dikubur hidup-hidup ditanya,'),
  ('id.indonesian', 81, 9, 'karena dosa apakah dia dibunuh,'),
  ('id.indonesian', 81, 10, 'dan apabila catatan-catatan (amal perbuatan manusia) dibuka,'),
  ('id.indonesian', 81, 11, 'dan apabila langit dilenyapkan,'),
  ('id.indonesian', 81, 12, 'dan apabila neraka Jahim dinyalakan,'),
  ('id.indonesian', 81, 13, 'dan apabila surga didekatkan,'),
  ('id.indonesian', 81, 14, 'maka tiap-tiap jiwa akan mengetahui apa yang telah dikerjakannya.'),
  ('id.indonesian', 81, 15, 'Sungguh, Aku bersumpah dengan bintang-bintang,'),
  ('id.indonesian', 81, 16, 'yang beredar dan terbenam,'),
  ('id.indonesian', 81, 17, 'demi malam apabila telah hampir meninggalkan gelapnya,'),
  ('id.indonesian', 81, 18, 'dan demi subuh apabila fajarnya mulai menyingsing,'),
  ('id.indonesian', 81, 19, 'sesungguhnya Al Quran itu benar-benar firman (Allah yang dibawa oleh) utusan yang mulia (Jibril),'),
  ('id.indonesian', 81, 20, 'yang mempunyai kekuatan, yang mempunyai kedudukan tinggi di sisi Allah yang mempunyai \'Arsy,'),
  ('id.indonesian', 81, 21, 'yang ditaati di sana (di alam malaikat) lagi dipercaya.'),
  ('id.indonesian', 81, 22, 'Dan temanmu (Muhammad) itu bukanlah sekali-kali orang yang gila.'),
  ('id.indonesian', 81, 23, 'Dan sesungguhnya Muhammad itu melihat Jibril di ufuk yang terang.'),
  ('id.indonesian', 81, 24, 'Dan dia (Muhammad) bukanlah orang yang bakhil untuk menerangkan yang ghaib.'),
  ('id.indonesian', 81, 25, 'Dan Al Quran itu bukanlah perkataan syaitan yang terkutuk,'),
  ('id.indonesian', 81, 26, 'maka ke manakah kamu akan pergi?'),
  ('id.indonesian', 81, 27, 'Al Quran itu tiada lain hanyalah peringatan bagi semesta alam,'),
  ('id.indonesian', 81, 28, '(yaitu) bagi siapa di antara kamu yang mau menempuh jalan yang lurus.'),
  ('id.indonesian', 81, 29, 'Dan kamu tidak dapat menghendaki (menempuh jalan itu) kecuali apabila dikehendaki Allah, Tuhan semesta alam.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 82, 1, 'When the sky breaks apart'),
  ('en.sahih', 82, 2, 'And when the stars fall, scattering,'),
  ('en.sahih', 82, 3, 'And when the seas are erupted'),
  ('en.sahih', 82, 4, 'And when the [contents of] graves are scattered,'),
  ('en.sahih', 82, 5, 'A soul will [then] know what it has put forth and kept back.'),
  ('en.sahih', 82, 6, 'O mankind, what has deceived you concerning your Lord, the Generous,'),
  ('en.sahih', 82, 7, 'Who created you, proportioned you, and balanced you?'),
  ('en.sahih', 82, 8, 'In whatever form He willed has He assembled you.'),
  ('en.sahih', 82, 9, 'No! But you deny the Recompense.'),
  ('en.sahih', 82, 10, 'And indeed, [appointed] over you are keepers,'),
  ('en.sahih', 82, 11, 'Noble and recording;'),
  ('en.sahih', 82, 12, 'They know whatever you do.'),
  ('en.sahih', 82, 13, 'Indeed, the righteous will be in pleasure,'),
  ('en.sahih', 82, 14, 'And indeed, the wicked will be in Hellfire.'),
  ('en.sahih', 82, 15, 'They will [enter to] burn therein on the Day of Recompense,'),
  ('en.sahih', 82, 16, 'And never therefrom will they be absent.'),
  ('en.sahih', 82, 17, 'And what can make you know what is the Day of Recompense?'),
  ('en.sahih', 82, 18, 'Then, what can make you know what is the Day of Recompense?'),
  ('en.sahih', 82, 19, 'It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 82, 1, 'যখন আকাশ বিদীর্ণ হবে,'),
  ('bn.bengali', 82, 2, 'যখন নক্ষত্রসমূহ ঝরে পড়বে,'),
  ('bn.bengali', 82, 3, 'যখন সমুদ্রকে উত্তাল করে তোলা হবে,'),
  ('bn.bengali', 82, 4, 'এবং যখন কবরসমূহ উম্মোচিত হবে,'),
  ('bn.bengali', 82, 5, 'তখন প্রত্যেকে জেনে নিবে সে কি অগ্রে প্রেরণ করেছে এবং কি পশ্চাতে ছেড়ে এসেছে।'),
  ('bn.bengali', 82, 6, 'হে মানুষ, কিসে তোমাকে তোমার মহামহিম পালনকর্তা সম্পর্কে বিভ্রান্ত করল?'),
  ('bn.bengali', 82, 7, 'যিনি তোমাকে সৃষ্টি করেছেন, অতঃপর তোমাকে সুবিন্যস্ত করেছেন এবং সুষম করেছেন।'),
  ('bn.bengali', 82, 8, 'যিনি তোমাকে তাঁর ইচ্ছামত আকৃতিতে গঠন করেছেন।'),
  ('bn.bengali', 82, 9, 'কখনও বিভ্রান্ত হয়ো না; বরং তোমরা দান-প্রতিদানকে মিথ্যা মনে কর।'),
  ('bn.bengali', 82, 10, 'অবশ্যই তোমাদের উপর তত্ত্বাবধায়ক নিযুক্ত আছে।'),
  ('bn.bengali', 82, 11, 'সম্মানিত আমল লেখকবৃন্দ।'),
  ('bn.bengali', 82, 12, 'তারা জানে যা তোমরা কর।'),
  ('bn.bengali', 82, 13, 'সৎকর্মশীলগণ থাকবে জান্নাতে।'),
  ('bn.bengali', 82, 14, 'এবং দুষ্কর্মীরা থাকবে জাহান্নামে;'),
  ('bn.bengali', 82, 15, 'তারা বিচার দিবসে তথায় প্রবেশ করবে।'),
  ('bn.bengali', 82, 16, 'তারা সেখান থেকে পৃথক হবে না।'),
  ('bn.bengali', 82, 17, 'আপনি জানেন, বিচার দিবস কি?'),
  ('bn.bengali', 82, 18, 'অতঃপর আপনি জানেন, বিচার দিবস কি?'),
  ('bn.bengali', 82, 19, 'যেদিন কেউ কারও কোন উপকার করতে পারবে না এবং সেদিন সব কতৃꦣ2468;্ব হবে আল্লাহর।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 82, 1, 'When the heaven is cleft asunder,'),
  ('en.pickthall', 82, 2, 'When the planets are dispersed,'),
  ('en.pickthall', 82, 3, 'When the seas are poured forth,'),
  ('en.pickthall', 82, 4, 'And the sepulchres are overturned,'),
  ('en.pickthall', 82, 5, 'A soul will know what it hath sent before (it) and what left behind.'),
  ('en.pickthall', 82, 6, 'O man! What hath made thee careless concerning thy Lord, the Bountiful,'),
  ('en.pickthall', 82, 7, 'Who created thee, then fashioned, then proportioned thee?'),
  ('en.pickthall', 82, 8, 'Into whatsoever form He will, He casteth thee.'),
  ('en.pickthall', 82, 9, 'Nay, but ye deny the Judgment.'),
  ('en.pickthall', 82, 10, 'Lo! there are above you guardians,'),
  ('en.pickthall', 82, 11, 'Generous and recording,'),
  ('en.pickthall', 82, 12, 'Who know (all) that ye do.'),
  ('en.pickthall', 82, 13, 'Lo! the righteous verily will be in delight.'),
  ('en.pickthall', 82, 14, 'And lo! the wicked verily will be in hell;'),
  ('en.pickthall', 82, 15, 'They will burn therein on the Day of Judgment,'),
  ('en.pickthall', 82, 16, 'And will not be absent thence.'),
  ('en.pickthall', 82, 17, 'Ah, what will convey unto thee what the Day of Judgment is!'),
  ('en.pickthall', 82, 18, 'Again, what will convey unto thee what the Day of Judgment is!'),
  ('en.pickthall', 82, 19, 'A day on which no soul hath power at all for any (other) soul. The (absolute) command on that day is Allah\'s.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 82, 1, 'When the Sky is cleft asunder;'),
  ('en.yusufali', 82, 2, 'When the Stars are scattered;'),
  ('en.yusufali', 82, 3, 'When the Oceans are suffered to burst forth;'),
  ('en.yusufali', 82, 4, 'And when the Graves are turned upside down;-'),
  ('en.yusufali', 82, 5, '(Then) shall each soul know what it hath sent forward and (what it hath) kept back.'),
  ('en.yusufali', 82, 6, 'O man! What has seduced thee from thy Lord Most Beneficent?-'),
  ('en.yusufali', 82, 7, 'Him Who created thee. Fashioned thee in due proportion, and gave thee a just bias;'),
  ('en.yusufali', 82, 8, 'In whatever Form He wills, does He put thee together.'),
  ('en.yusufali', 82, 9, 'Nay! But ye do reject Right and Judgment!'),
  ('en.yusufali', 82, 10, 'But verily over you (are appointed angels) to protect you,-'),
  ('en.yusufali', 82, 11, 'Kind and honourable,- Writing down (your deeds):'),
  ('en.yusufali', 82, 12, 'They know (and understand) all that ye do.'),
  ('en.yusufali', 82, 13, 'As for the Righteous, they will be in bliss;'),
  ('en.yusufali', 82, 14, 'And the Wicked - they will be in the Fire,'),
  ('en.yusufali', 82, 15, 'Which they will enter on the Day of Judgment,'),
  ('en.yusufali', 82, 16, 'And they will not be able to keep away therefrom.'),
  ('en.yusufali', 82, 17, 'And what will explain to thee what the Day of Judgment is?'),
  ('en.yusufali', 82, 18, 'Again, what will explain to thee what the Day of Judgment is?'),
  ('en.yusufali', 82, 19, '(It will be) the Day when no soul shall have power (to do) aught for another: For the command, that Day, will be (wholly) with Allah.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 82, 1, 'Izas samaaa\'un fatarat'),
  ('en.transliteration', 82, 2, 'Wa izal kawaakibun tasarat'),
  ('en.transliteration', 82, 3, 'Wa izal bihaaru fujjirat'),
  ('en.transliteration', 82, 4, 'Wa izal qubooru bu\'sirat'),
  ('en.transliteration', 82, 5, '\'Alimat nafsum maa qaddamat wa akhkharat'),
  ('en.transliteration', 82, 6, 'Yaaa ayyuhal insaaanu maa gharraka bi Rabbikal kareem'),
  ('en.transliteration', 82, 7, 'Allazee khalaqaka fasaw waaka fa\'adalak'),
  ('en.transliteration', 82, 8, 'Feee ayye sooratim maa shaaa\'a rakkabak'),
  ('en.transliteration', 82, 9, 'Kalla bal tukazziboona bid deen'),
  ('en.transliteration', 82, 10, 'Wa inna \'alaikum lahaa fizeen'),
  ('en.transliteration', 82, 11, 'Kiraaman kaatibeen'),
  ('en.transliteration', 82, 12, 'Ya\'lamoona ma taf\'aloon'),
  ('en.transliteration', 82, 13, 'Innal abraara lafee na\'eem'),
  ('en.transliteration', 82, 14, 'Wa innal fujjaara lafee jaheem'),
  ('en.transliteration', 82, 15, 'Yaslawnahaa Yawmad Deen'),
  ('en.transliteration', 82, 16, 'Wa maa hum \'anhaa bighaaa \'ibeen'),
  ('en.transliteration', 82, 17, 'Wa maaa adraaka maa Yawmud Deen'),
  ('en.transliteration', 82, 18, 'Summa maaa adraaka maa Yawmud Deen'),
  ('en.transliteration', 82, 19, 'Yawma laa tamliku nafsul linafsin shai\'anw walamru yawma\'izil lillaah')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 82, 1, 'جب آسمان پھٹ جائے'),
  ('ur.ahmedali', 82, 2, 'اورجب ستارے جھڑ جائیں'),
  ('ur.ahmedali', 82, 3, 'اور جب سمندر ابل پڑیں'),
  ('ur.ahmedali', 82, 4, 'اور جب قبریں اکھاڑ دی جائیں'),
  ('ur.ahmedali', 82, 5, 'تب ہر شخص جان لے گا کہ کیا آگے بھیجا اور کیا پیچھے چھوڑ آیا'),
  ('ur.ahmedali', 82, 6, 'اے انسان تجھے اپنے رب کریم کے بارے میں کس چیز نے مغرور کر دیا'),
  ('ur.ahmedali', 82, 7, 'جس نے تجھے پیدا کیا پھر تجھے ٹھیک کیا پھر تجھے برابر کیا'),
  ('ur.ahmedali', 82, 8, 'جس صورت میں چاہا تیرے اعضا کو جوڑ دیا'),
  ('ur.ahmedali', 82, 9, 'نہیں نہیں بلکہ تم جزا کو نہیں مانتے'),
  ('ur.ahmedali', 82, 10, 'اور بے شک تم پر محافظ ہیں'),
  ('ur.ahmedali', 82, 11, 'عزت والے اعمال لکھنے والے'),
  ('ur.ahmedali', 82, 12, 'وہ جانتے ہیں جو تم کرتے ہو'),
  ('ur.ahmedali', 82, 13, 'بےشک نیک لوگ نعمت میں ہوں گے'),
  ('ur.ahmedali', 82, 14, 'اور بے شک نافرمان دوزخ میں ہوں گے'),
  ('ur.ahmedali', 82, 15, 'انصاف کے دن اس میں داخل ہوں گے'),
  ('ur.ahmedali', 82, 16, 'اور وہ اس سے کہیں جانے نہ پائیں گے'),
  ('ur.ahmedali', 82, 17, 'اورتجھے کیا معلوم انصاف کا دن کیا ہے'),
  ('ur.ahmedali', 82, 18, 'پھر تجھے کیا خبر کہ انصاف کا دن کیا ہے'),
  ('ur.ahmedali', 82, 19, 'جس دن کوئی کسی کے لیے کچھ بھی نہ کر سکے گااور اس دن الله ہی کا حکم ہوگا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 82, 1, 'Gök yarıldığı zaman,'),
  ('tr.diyanet', 82, 2, 'Yıldızlar dağılıp döküldüğü zaman,'),
  ('tr.diyanet', 82, 3, 'Denizler kaynaştığı zaman,'),
  ('tr.diyanet', 82, 4, 'Kabirlerin içi dışa çıktığı zaman,'),
  ('tr.diyanet', 82, 5, 'İnsanoğlu, ne yaptığını ve ne yapmadığını görür.'),
  ('tr.diyanet', 82, 6, 'Ey insanoğlu! Seni yaratıp sonra şekil veren, düzenleyen, mütenasip kılan, istediği şekilde seni terkip eden, çok cömert olan Rabbine karşı seni aldatan nedir?'),
  ('tr.diyanet', 82, 7, 'Ey insanoğlu! Seni yaratıp sonra şekil veren, düzenleyen, mütenasip kılan, istediği şekilde seni terkip eden, çok cömert olan Rabbine karşı seni aldatan nedir?'),
  ('tr.diyanet', 82, 8, 'Ey insanoğlu! Seni yaratıp sonra şekil veren, düzenleyen, mütenasip kılan, istediği şekilde seni terkip eden, çok cömert olan Rabbine karşı seni aldatan nedir?'),
  ('tr.diyanet', 82, 9, 'Hayır, hayır; doğrusu siz dini yalanlıyorsunuz.'),
  ('tr.diyanet', 82, 10, 'Oysa, yaptıklarınızı bilen değerli yazıcılar sizi gözetlemektedirler.'),
  ('tr.diyanet', 82, 11, 'Oysa, yaptıklarınızı bilen değerli yazıcılar sizi gözetlemektedirler.'),
  ('tr.diyanet', 82, 12, 'Oysa, yaptıklarınızı bilen değerli yazıcılar sizi gözetlemektedirler.'),
  ('tr.diyanet', 82, 13, 'İyiler şüphesiz nimet içindedirler.'),
  ('tr.diyanet', 82, 14, 'Allah\'ın buyruğundan çıkanlar cehennemdedirler.'),
  ('tr.diyanet', 82, 15, 'Din Günü oraya girerler.'),
  ('tr.diyanet', 82, 16, 'Oradan bir daha ayrılamazlar.'),
  ('tr.diyanet', 82, 17, 'Din gününün ne olduğunu sen nereden bilirsin?'),
  ('tr.diyanet', 82, 18, 'Evet, din gününün ne olduğunu nereden bileceksin?'),
  ('tr.diyanet', 82, 19, 'O gün, kimsenin kimseye hiçbir fayda sağlamayacağı bir gündür. O gün buyruk, yalnız Allah\'ındır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 82, 1, 'Apabila langit terbelah,'),
  ('id.indonesian', 82, 2, 'dan apabila bintang-bintang jatuh berserakan,'),
  ('id.indonesian', 82, 3, 'dan apabila lautan menjadikan meluap,'),
  ('id.indonesian', 82, 4, 'dan apabila kuburan-kuburan dibongkar,'),
  ('id.indonesian', 82, 5, 'maka tiap-tiap jiwa akan mengetahui apa yang telah dikerjakan dan yang dilalaikannya.'),
  ('id.indonesian', 82, 6, 'Hai manusia, apakah yang telah memperdayakan kamu (berbuat durhaka) terhadap Tuhanmu Yang Maha Pemurah.'),
  ('id.indonesian', 82, 7, 'Yang telah menciptakan kamu lalu menyempurnakan kejadianmu dan menjadikan (susunan tubuh)mu seimbang,'),
  ('id.indonesian', 82, 8, 'dalam bentuk apa saja yang Dia kehendaki, Dia menyusun tubuhmu.'),
  ('id.indonesian', 82, 9, 'Bukan hanya durhaka saja, bahkan kamu mendustakan hari pembalasan.'),
  ('id.indonesian', 82, 10, 'Padahal sesungguhnya bagi kamu ada (malaikat-malaikat) yang mengawasi (pekerjaanmu),'),
  ('id.indonesian', 82, 11, 'yang mulia (di sisi Allah) dan mencatat (pekerjaan-pekerjaanmu itu),'),
  ('id.indonesian', 82, 12, 'mereka mengetahui apa yang kamu kerjakan.'),
  ('id.indonesian', 82, 13, 'Sesungguhnya orang-orang yang banyak berbakti benar-benar berada dalam surga yang penuh kenikmatan,'),
  ('id.indonesian', 82, 14, 'dan sesungguhnya orang-orang yang durhaka benar-benar berada dalam neraka.'),
  ('id.indonesian', 82, 15, 'Mereka masuk ke dalamnya pada hari pembalasan.'),
  ('id.indonesian', 82, 16, 'Dan mereka sekali-kali tidak dapat keluar dari neraka itu.'),
  ('id.indonesian', 82, 17, 'Tahukah kamu apakah hari pembalasan itu?'),
  ('id.indonesian', 82, 18, 'Sekali lagi, tahukah kamu apakah hari pembalasan itu?'),
  ('id.indonesian', 82, 19, '(Yaitu) hari (ketika) seseorang tidak berdaya sedikitpun untuk menolong orang lain. Dan segala urusan pada hari itu dalam kekuasaan Allah.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 83, 1, 'Woe to those who give less [than due],'),
  ('en.sahih', 83, 2, 'Who, when they take a measure from people, take in full.'),
  ('en.sahih', 83, 3, 'But if they give by measure or by weight to them, they cause loss.'),
  ('en.sahih', 83, 4, 'Do they not think that they will be resurrected'),
  ('en.sahih', 83, 5, 'For a tremendous Day -'),
  ('en.sahih', 83, 6, 'The Day when mankind will stand before the Lord of the worlds?'),
  ('en.sahih', 83, 7, 'No! Indeed, the record of the wicked is in sijjeen.'),
  ('en.sahih', 83, 8, 'And what can make you know what is sijjeen?'),
  ('en.sahih', 83, 9, 'It is [their destination recorded in] a register inscribed.'),
  ('en.sahih', 83, 10, 'Woe, that Day, to the deniers,'),
  ('en.sahih', 83, 11, 'Who deny the Day of Recompense.'),
  ('en.sahih', 83, 12, 'And none deny it except every sinful transgressor.'),
  ('en.sahih', 83, 13, 'When Our verses are recited to him, he says, "Legends of the former peoples."'),
  ('en.sahih', 83, 14, 'No! Rather, the stain has covered their hearts of that which they were earning.'),
  ('en.sahih', 83, 15, 'No! Indeed, from their Lord, that Day, they will be partitioned.'),
  ('en.sahih', 83, 16, 'Then indeed, they will [enter and] burn in Hellfire.'),
  ('en.sahih', 83, 17, 'Then it will be said [to them], "This is what you used to deny."'),
  ('en.sahih', 83, 18, 'No! Indeed, the record of the righteous is in \'illiyyun.'),
  ('en.sahih', 83, 19, 'And what can make you know what is \'illiyyun?'),
  ('en.sahih', 83, 20, 'It is [their destination recorded in] a register inscribed'),
  ('en.sahih', 83, 21, 'Which is witnessed by those brought near [to Allah].'),
  ('en.sahih', 83, 22, 'Indeed, the righteous will be in pleasure'),
  ('en.sahih', 83, 23, 'On adorned couches, observing.'),
  ('en.sahih', 83, 24, 'You will recognize in their faces the radiance of pleasure.'),
  ('en.sahih', 83, 25, 'They will be given to drink [pure] wine [which was] sealed.'),
  ('en.sahih', 83, 26, 'The last of it is musk. So for this let the competitors compete.'),
  ('en.sahih', 83, 27, 'And its mixture is of Tasneem,'),
  ('en.sahih', 83, 28, 'A spring from which those near [to Allah] drink.'),
  ('en.sahih', 83, 29, 'Indeed, those who committed crimes used to laugh at those who believed.'),
  ('en.sahih', 83, 30, 'And when they passed by them, they would exchange derisive glances.'),
  ('en.sahih', 83, 31, 'And when they returned to their people, they would return jesting.'),
  ('en.sahih', 83, 32, 'And when they saw them, they would say, "Indeed, those are truly lost."'),
  ('en.sahih', 83, 33, 'But they had not been sent as guardians over them.'),
  ('en.sahih', 83, 34, 'So Today those who believed are laughing at the disbelievers,'),
  ('en.sahih', 83, 35, 'On adorned couches, observing.'),
  ('en.sahih', 83, 36, 'Have the disbelievers [not] been rewarded [this Day] for what they used to do?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 83, 1, 'যারা মাপে কম করে, তাদের জন্যে দুর্ভোগ,'),
  ('bn.bengali', 83, 2, 'যারা লোকের কাছ থেকে যখন মেপে নেয়, তখন পূর্ণ মাত্রায় নেয়'),
  ('bn.bengali', 83, 3, 'এবং যখন লোকদেরকে মেপে দেয় কিংবা ওজন করে দেয়, তখন কম করে দেয়।'),
  ('bn.bengali', 83, 4, 'তারা কি চিন্তা করে না যে, তারা পুনরুত্থিত হবে।'),
  ('bn.bengali', 83, 5, 'সেই মহাদিবসে,'),
  ('bn.bengali', 83, 6, 'যেদিন মানুষ দাঁড়াবে বিশ্ব পালনকর্তার সামনে।'),
  ('bn.bengali', 83, 7, 'এটা কিছুতেই উচিত নয়, নিশ্চয় পাপাচারীদের আমলনামা সিজ্জীনে আছে।'),
  ('bn.bengali', 83, 8, 'আপনি জানেন, সিজ্জীন কি?'),
  ('bn.bengali', 83, 9, 'এটা লিপিবদ্ধ খাতা।'),
  ('bn.bengali', 83, 10, 'সেদিন দুর্ভোগ মিথ্যারোপকারীদের,'),
  ('bn.bengali', 83, 11, 'যারা প্রতিফল দিবসকে মিথ্যারোপ করে।'),
  ('bn.bengali', 83, 12, 'প্রত্যেক সীমালংঘনকারী পাপিষ্ঠই কেবল একে মিথ্যারোপ করে।'),
  ('bn.bengali', 83, 13, 'তার কাছে আমার আয়াতসমূহ পাঠ করা হলে সে বলে, পুরাকালের উপকথা।'),
  ('bn.bengali', 83, 14, 'কখনও না, বরং তারা যা করে, তাই তাদের হৃদয় মরিচা ধরিয়ে দিয়েছে।'),
  ('bn.bengali', 83, 15, 'কখনও না, তারা সেদিন তাদের পালনকর্তার থেকে পর্দার অন্তরালে থাকবে।'),
  ('bn.bengali', 83, 16, 'অতঃপর তারা জাহান্নামে প্রবেশ করবে।'),
  ('bn.bengali', 83, 17, 'এরপর বলা হবে, একেই তো তোমরা মিথ্যারোপ করতে।'),
  ('bn.bengali', 83, 18, 'কখনও না, নিশ্চয় সৎলোকদের আমলনামা আছে ইল্লিয়্যীনে।'),
  ('bn.bengali', 83, 19, 'আপনি জানেন ইল্লিয়্যীন কি?'),
  ('bn.bengali', 83, 20, 'এটা লিপিবদ্ধ খাতা।'),
  ('bn.bengali', 83, 21, 'আল্লাহর নৈকট্যপ্রাপ্ত ফেরেশতাগণ একে প্রত্যক্ষ করে।'),
  ('bn.bengali', 83, 22, 'নিশ্চয় সৎলোকগণ থাকবে পরম আরামে,'),
  ('bn.bengali', 83, 23, 'সিংহাসনে বসে অবলোকন করবে।'),
  ('bn.bengali', 83, 24, 'আপনি তাদের মুখমন্ডলে স্বাচ্ছন্দ্যের সজীবতা দেখতে পাবেন।'),
  ('bn.bengali', 83, 25, 'তাদেরকে মোহর করা বিশুদ্ধ পানীয় পান করানো হবে।'),
  ('bn.bengali', 83, 26, 'তার মোহর হবে কস্তুরী। এ বিষয়ে প্রতিযোগীদের প্রতিযোগিতা করা উচিত।'),
  ('bn.bengali', 83, 27, 'তার মিশ্রণ হবে তসনীমের পানি।'),
  ('bn.bengali', 83, 28, 'এটা একটা ঝরণা, যার পানি পান করবে নৈকট্যশীলগণ।'),
  ('bn.bengali', 83, 29, 'যারা অপরাধী, তারা বিশ্বাসীদেরকে উপহাস করত।'),
  ('bn.bengali', 83, 30, 'এবং তারা যখন তাদের কাছ দিয়ে গমন করত তখন পরস্পরে চোখ টিপে ইশারা করত।'),
  ('bn.bengali', 83, 31, 'তারা যখন তাদের পরিবার-পরিজনের কাছে ফিরত, তখনও হাসাহাসি করে ফিরত।'),
  ('bn.bengali', 83, 32, 'আর যখন তারা বিশ্বাসীদেরকে দেখত, তখন বলত, নিশ্চয় এরা বিভ্রান্ত।'),
  ('bn.bengali', 83, 33, 'অথচ তারা বিশ্বাসীদের তত্ত্বাবধায়করূপে প্রেরিত হয়নি।'),
  ('bn.bengali', 83, 34, 'আজ যারা বিশ্বাসী, তারা কাফেরদেরকে উপহাস করছে।'),
  ('bn.bengali', 83, 35, 'সিংহাসনে বসে, তাদেরকে অবলোকন করছে,'),
  ('bn.bengali', 83, 36, 'কাফেররা যা করত, তার প্রতিফল পেয়েছে তো?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 83, 1, 'Woe unto the defrauders:'),
  ('en.pickthall', 83, 2, 'Those who when they take the measure from mankind demand it full,'),
  ('en.pickthall', 83, 3, 'But if they measure unto them or weight for them, they cause them loss.'),
  ('en.pickthall', 83, 4, 'Do such (men) not consider that they will be raised again'),
  ('en.pickthall', 83, 5, 'Unto an Awful Day,'),
  ('en.pickthall', 83, 6, 'The day when (all) mankind stand before the Lord of the Worlds?'),
  ('en.pickthall', 83, 7, 'Nay, but the record of the vile is in Sijjin -'),
  ('en.pickthall', 83, 8, 'Ah! what will convey unto thee what Sijjin is! -'),
  ('en.pickthall', 83, 9, 'A written record.'),
  ('en.pickthall', 83, 10, 'Woe unto the repudiators on that day!'),
  ('en.pickthall', 83, 11, 'Those who deny the Day of Judgment'),
  ('en.pickthall', 83, 12, 'Which none denieth save each criminal transgressor,'),
  ('en.pickthall', 83, 13, 'Who, when thou readest unto him Our revelations, saith: (Mere) fables of the men of old.'),
  ('en.pickthall', 83, 14, 'Nay, but that which they have earned is rust upon their hearts.'),
  ('en.pickthall', 83, 15, 'Nay, but surely on that day they will be covered from (the mercy of) their Lord.'),
  ('en.pickthall', 83, 16, 'Then lo! they verily will burn in hell,'),
  ('en.pickthall', 83, 17, 'And it will be said (unto them): This is that which ye used to deny.'),
  ('en.pickthall', 83, 18, 'Nay, but the record of the righteous is in \'Illiyin -'),
  ('en.pickthall', 83, 19, 'Ah, what will convey unto thee what \'Illiyin is! -'),
  ('en.pickthall', 83, 20, 'A written record,'),
  ('en.pickthall', 83, 21, 'Attested by those who are brought near (unto their Lord).'),
  ('en.pickthall', 83, 22, 'Lo! the righteous verily are in delight,'),
  ('en.pickthall', 83, 23, 'On couches, gazing,'),
  ('en.pickthall', 83, 24, 'Thou wilt know in their faces the radiance of delight.'),
  ('en.pickthall', 83, 25, 'They are given to drink of a pure wine, sealed,'),
  ('en.pickthall', 83, 26, 'Whose seal is musk - for this let (all) those strive who strive for bliss -'),
  ('en.pickthall', 83, 27, 'And mixed with water of Tasnim,'),
  ('en.pickthall', 83, 28, 'A spring whence those brought near (to Allah) drink.'),
  ('en.pickthall', 83, 29, 'Lo! the guilty used to laugh at those who believed,'),
  ('en.pickthall', 83, 30, 'And wink one to another when they passed them;'),
  ('en.pickthall', 83, 31, 'And when they returned to their own folk, they returned jesting;'),
  ('en.pickthall', 83, 32, 'And when they saw them they said: Lo! these have gone astray.'),
  ('en.pickthall', 83, 33, 'Yet they were not sent as guardians over them.'),
  ('en.pickthall', 83, 34, 'This day it is those who believe who have the laugh of disbelievers,'),
  ('en.pickthall', 83, 35, 'On high couches, gazing.'),
  ('en.pickthall', 83, 36, 'Are not the disbelievers paid for what they used to do?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 83, 1, 'Woe to those that deal in fraud,-'),
  ('en.yusufali', 83, 2, 'Those who, when they have to receive by measure from men, exact full measure,'),
  ('en.yusufali', 83, 3, 'But when they have to give by measure or weight to men, give less than due.'),
  ('en.yusufali', 83, 4, 'Do they not think that they will be called to account?-'),
  ('en.yusufali', 83, 5, 'On a Mighty Day,'),
  ('en.yusufali', 83, 6, 'A Day when (all) mankind will stand before the Lord of the Worlds?'),
  ('en.yusufali', 83, 7, 'Nay! Surely the record of the wicked is (preserved) in Sijjin.'),
  ('en.yusufali', 83, 8, 'And what will explain to thee what Sijjin is?'),
  ('en.yusufali', 83, 9, '(There is) a Register (fully) inscribed.'),
  ('en.yusufali', 83, 10, 'Woe, that Day, to those that deny-'),
  ('en.yusufali', 83, 11, 'Those that deny the Day of Judgment.'),
  ('en.yusufali', 83, 12, 'And none can deny it but the Transgressor beyond bounds the Sinner!'),
  ('en.yusufali', 83, 13, 'When Our Signs are rehearsed to him, he says, "Tales of the ancients!"'),
  ('en.yusufali', 83, 14, 'By no means! but on their hearts is the stain of the (ill) which they do!'),
  ('en.yusufali', 83, 15, 'Verily, from (the Light of) their Lord, that Day, will they be veiled.'),
  ('en.yusufali', 83, 16, 'Further, they will enter the Fire of Hell.'),
  ('en.yusufali', 83, 17, 'Further, it will be said to them: "This is the (reality) which ye rejected as false!'),
  ('en.yusufali', 83, 18, 'Nay, verily the record of the Righteous is (preserved) in \'Illiyin.'),
  ('en.yusufali', 83, 19, 'And what will explain to thee what \'Illiyun is?'),
  ('en.yusufali', 83, 20, '(There is) a Register (fully) inscribed,'),
  ('en.yusufali', 83, 21, 'To which bear witness those Nearest (to Allah).'),
  ('en.yusufali', 83, 22, 'Truly the Righteous will be in Bliss:'),
  ('en.yusufali', 83, 23, 'On Thrones (of Dignity) will they command a sight (of all things):'),
  ('en.yusufali', 83, 24, 'Thou wilt recognise in their faces the beaming brightness of Bliss.'),
  ('en.yusufali', 83, 25, 'Their thirst will be slaked with Pure Wine sealed:'),
  ('en.yusufali', 83, 26, 'The seal thereof will be Musk: And for this let those aspire, who have aspirations:'),
  ('en.yusufali', 83, 27, 'With it will be (given) a mixture of Tasnim:'),
  ('en.yusufali', 83, 28, 'A spring, from (the waters) whereof drink those Nearest to Allah.'),
  ('en.yusufali', 83, 29, 'Those in sin used to laugh at those who believed,'),
  ('en.yusufali', 83, 30, 'And whenever they passed by them, used to wink at each other (in mockery);'),
  ('en.yusufali', 83, 31, 'And when they returned to their own people, they would return jesting;'),
  ('en.yusufali', 83, 32, 'And whenever they saw them, they would say, "Behold! These are the people truly astray!"'),
  ('en.yusufali', 83, 33, 'But they had not been sent as keepers over them!'),
  ('en.yusufali', 83, 34, 'But on this Day the Believers will laugh at the Unbelievers:'),
  ('en.yusufali', 83, 35, 'On Thrones (of Dignity) they will command (a sight) (of all things).'),
  ('en.yusufali', 83, 36, 'Will not the Unbelievers have been paid back for what they did?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 83, 1, 'Wailul lil mutaffifeen'),
  ('en.transliteration', 83, 2, 'Allazeena izak taaloo \'alan naasi yastawfoon'),
  ('en.transliteration', 83, 3, 'Wa izaa kaaloohum aw wazanoohum yukhsiroon'),
  ('en.transliteration', 83, 4, 'Alaa yazunnu ulaaa\'ika annahum mab\'oosoon'),
  ('en.transliteration', 83, 5, 'Li Yawmin \'Azeem'),
  ('en.transliteration', 83, 6, 'Yawma yaqoomun naasu li Rabbil \'aalameen'),
  ('en.transliteration', 83, 7, 'Kallaaa inna kitaabal fujjaari lafee Sijjeen'),
  ('en.transliteration', 83, 8, 'Wa maa adraaka maa Sijjeen'),
  ('en.transliteration', 83, 9, 'Kitaabum marqoom'),
  ('en.transliteration', 83, 10, 'Wailuny yawma\'izil lil mukazzibeen'),
  ('en.transliteration', 83, 11, 'Allazeena yukazziboona bi yawmid deen'),
  ('en.transliteration', 83, 12, 'Wa maa yukazzibu biheee illaa kullu mu\'tadin aseem'),
  ('en.transliteration', 83, 13, 'Izaa tutlaa\'alaihi aayaatunaa qaala asaateerul awwaleen'),
  ('en.transliteration', 83, 14, 'Kallaa bal raana \'alaa quloobihim maa kaanoo yaksiboon'),
  ('en.transliteration', 83, 15, 'Kallaaa innahum \'ar Rabbihim yawma\'izil lamah jooboon'),
  ('en.transliteration', 83, 16, 'Summa innahum lasaa lul jaheem'),
  ('en.transliteration', 83, 17, 'Summa yuqaalu haazal lazee kuntum bihee tukazziboon'),
  ('en.transliteration', 83, 18, 'Kallaaa inna kitaabal abraari lafee\'Illiyyeen'),
  ('en.transliteration', 83, 19, 'Wa maaa adraaka maa \'Illiyyoon'),
  ('en.transliteration', 83, 20, 'Kitaabum marqoom'),
  ('en.transliteration', 83, 21, 'Yashhadu hul muqarra boon'),
  ('en.transliteration', 83, 22, 'Innal abraara lafee Na\'eem'),
  ('en.transliteration', 83, 23, '\'Alal araaa\'iki yanzuroon'),
  ('en.transliteration', 83, 24, 'Ta\'rifu fee wujoohihim nadratan na\'eem'),
  ('en.transliteration', 83, 25, 'Yusqawna mir raheeqim makhtoom'),
  ('en.transliteration', 83, 26, 'Khitaamuhoo misk; wa fee zaalika falyatanaafasil Mutanaafisoon'),
  ('en.transliteration', 83, 27, 'Wa mizaajuhoo min Tasneem'),
  ('en.transliteration', 83, 28, '\'Ainaiy yashrabu bihal muqarraboon'),
  ('en.transliteration', 83, 29, 'Innal lazeena ajramoo kaanoo minal lazeena aamanoo yadhakoon'),
  ('en.transliteration', 83, 30, 'Wa izaa marroo bihim yataghaamazoon'),
  ('en.transliteration', 83, 31, 'Wa izan qalabooo ilaaa ahlihimun qalaboo fakiheen'),
  ('en.transliteration', 83, 32, 'Wa izaa ra awhum qaalooo inna haaa\'ulaaa\'i ladaaal loon'),
  ('en.transliteration', 83, 33, 'Wa maaa ursiloo \'alaihim haafizeen'),
  ('en.transliteration', 83, 34, 'Fal yawmal lazeena aamanoo minal kuffaari yadhakoon'),
  ('en.transliteration', 83, 35, '\'Alal araaa\'iki yanzuroon'),
  ('en.transliteration', 83, 36, 'Hal suwwibal kuffaaru maa kaanoo yaf\'aloon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 83, 1, 'کم تولنے والوں کے لیے تباہی ہے'),
  ('ur.ahmedali', 83, 2, 'وہ لوگ کہ جب لوگوں سے ماپ کر لیں تو پورا کریں'),
  ('ur.ahmedali', 83, 3, 'اور جب ان کو ماپ کر یا تول کردیں توگھٹا کر دیں'),
  ('ur.ahmedali', 83, 4, 'کیا وہ خیال نہیں کرتے کہ وہ اٹھائے جائیں گے'),
  ('ur.ahmedali', 83, 5, 'اس بڑے دن کے لیے'),
  ('ur.ahmedali', 83, 6, 'جس دن سب لوگ رب العالمین کے سامنے کھڑے ہو ں گے'),
  ('ur.ahmedali', 83, 7, 'ہر گز ایسا نہیں چاہیے بے شک نافرمانوں کے اعمال نامے سجین میں ہیں'),
  ('ur.ahmedali', 83, 8, 'اور آپ کو کیا خبر کہ سجین کیا ہے'),
  ('ur.ahmedali', 83, 9, 'ایک دفتر ہے جس میں لکھا جاتا ہے'),
  ('ur.ahmedali', 83, 10, 'اس دن جھٹلانے والوں کے لئے تباہی ہے'),
  ('ur.ahmedali', 83, 11, 'وہ جو انصاف کے دن کو جھٹلاتے ہیں'),
  ('ur.ahmedali', 83, 12, 'اور اس کو وہی جھٹلاتا ہے جو حد سے بڑھا ہوا گناہگار ہے'),
  ('ur.ahmedali', 83, 13, 'جب اس پر ہماری آیتیں پڑھی جاتی ہیں تو کہتا ہے پہلوں کی کہانیاں ہیں'),
  ('ur.ahmedali', 83, 14, 'ہر گز نہیں بلکہ ان کے (بڑے) کاموں سے ان کے دلو ں پر زنگ لگ گیا ہے'),
  ('ur.ahmedali', 83, 15, 'ہر گز نہیں بے شک وہ اپنے رب سے اس دن روک دیئے جائیں گے'),
  ('ur.ahmedali', 83, 16, 'پھر بے شک وہ دوزخ میں گرنے والے ہیں'),
  ('ur.ahmedali', 83, 17, 'پھر کہا جائے گا کہ یہی ہے وہ جسے تم جھٹلاتے تھے'),
  ('ur.ahmedali', 83, 18, 'ہر گز نہیں بےشک نیکوں کے اعمال نامے علییں میں ہیں'),
  ('ur.ahmedali', 83, 19, 'اور آپ کو کیا خبر کہ علیّین کیا ہے'),
  ('ur.ahmedali', 83, 20, 'ایک دفتر ہے جس میں لکھا جاتا ہے'),
  ('ur.ahmedali', 83, 21, 'اسے مقرب فرشتے دیکھتے ہیں'),
  ('ur.ahmedali', 83, 22, 'بے شک نیکو کار جنت میں ہوں گے'),
  ('ur.ahmedali', 83, 23, 'تختوں پر بیٹھے دیکھ رہے ہوں گے'),
  ('ur.ahmedali', 83, 24, 'آپ ان کے چہروں میں نعمت کی تازگی معلوم کریں گے'),
  ('ur.ahmedali', 83, 25, 'ان کو خالص شراب مہر لگی ہوئی پلائی جائے گی'),
  ('ur.ahmedali', 83, 26, 'اس کی مہر مشک کی ہو گی اور رغبت کرنے والوں کو اس کی رغبت کرنی چاہیئے'),
  ('ur.ahmedali', 83, 27, 'اور اس میں تسنیم ملی ہو گی'),
  ('ur.ahmedali', 83, 28, 'وہ ایک چشمہ ہے اس میں سےمقرب پئیں گے'),
  ('ur.ahmedali', 83, 29, 'بے شک نافرمان (دنیا میں) ایمان داروں سے ہنسی کیا کرتے تھے'),
  ('ur.ahmedali', 83, 30, 'اور جب ان کے پاس سے گزرتے تو آپس میں آنکھ سے اشارے کرتے تھے'),
  ('ur.ahmedali', 83, 31, 'اور جب اپنے گھر والوں کے پاس لوٹ کر جاتے تو ہنستے ہوئے جاتے تھے'),
  ('ur.ahmedali', 83, 32, 'اور جب ان کو دیکھتے تو کہتے بے شک یہی گمراہ ہیں'),
  ('ur.ahmedali', 83, 33, 'حالانکہ وہ ان پر نگہبان بنا کر نہیں بھیجے گئے تھے'),
  ('ur.ahmedali', 83, 34, 'پس آج وہ لوگ جو ایمان لائے کفار سے ہنس رہے ہوں گے'),
  ('ur.ahmedali', 83, 35, 'تختوں پر بیٹھے دیکھ رہے ہوں گے'),
  ('ur.ahmedali', 83, 36, 'آیا کافروں کو بدلہ دیا گیا ہے ان اعمال کا جو وہ کیا کرتے تھے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 83, 1, 'İnsanlardan, kendileri bir şeyi ölçerek aldıkları zaman tam alan; ama onlara bir şeyi ölçüp tartarak verdiklerinde eksik tutan kimselerin, vay haline!'),
  ('tr.diyanet', 83, 2, 'İnsanlardan, kendileri bir şeyi ölçerek aldıkları zaman tam alan; ama onlara bir şeyi ölçüp tartarak verdiklerinde eksik tutan kimselerin, vay haline!'),
  ('tr.diyanet', 83, 3, 'İnsanlardan, kendileri bir şeyi ölçerek aldıkları zaman tam alan; ama onlara bir şeyi ölçüp tartarak verdiklerinde eksik tutan kimselerin, vay haline!'),
  ('tr.diyanet', 83, 4, 'Bunlar, büyük bir günde tekrar dirileceklerini sanmıyorlar mı?'),
  ('tr.diyanet', 83, 5, 'Bunlar, büyük bir günde tekrar dirileceklerini sanmıyorlar mı?'),
  ('tr.diyanet', 83, 6, 'O gün insanlar Alemlerin Rabbinin huzurunda dururlar.'),
  ('tr.diyanet', 83, 7, 'Sakının; Allah\'ın buyruğundan dışarı çıkanlar, muhakkak "Siccin" adlı defterde yazılıdır.'),
  ('tr.diyanet', 83, 8, 'Siccin\'in ne olduğunu sen nerden bilirsin?'),
  ('tr.diyanet', 83, 9, 'O, yazılmış bir kitaptır.'),
  ('tr.diyanet', 83, 10, 'Yalanlayanların o gün vay haline!'),
  ('tr.diyanet', 83, 11, 'Onlar, kıyamet gününü yalanlamış olanlardır.'),
  ('tr.diyanet', 83, 12, 'Oysa onu mütecaviz günahkardan başka kimse yalanlamaz.'),
  ('tr.diyanet', 83, 13, 'Ona ayetlerimiz okunduğu zaman "Öncekilerin masalları" der.'),
  ('tr.diyanet', 83, 14, 'Hayır, hayır; onların kazandıkları kalblerini paslandırıp körletmiştir.'),
  ('tr.diyanet', 83, 15, 'Hayır; doğrusu onlar o gün, Rablerinden yoksun kalacaklardır.'),
  ('tr.diyanet', 83, 16, 'Sonra onlar, şüphesiz, cehenneme gireceklerdir.'),
  ('tr.diyanet', 83, 17, 'Sonra da: "yalanlayıp durduğunuz işte budur" denecektir.'),
  ('tr.diyanet', 83, 18, 'Ama iyilerin defteri yüksek katlardadır.'),
  ('tr.diyanet', 83, 19, 'O yüksek katların ne olduğunu sen bilir misin?'),
  ('tr.diyanet', 83, 20, 'O, gözde meleklerin gördüğü, yazılı bir kitapdır.'),
  ('tr.diyanet', 83, 21, 'O, gözde meleklerin gördüğü, yazılı bir kitapdır.'),
  ('tr.diyanet', 83, 22, 'İyiler, şüphesiz, nimet içinde ve tahtlar üzerinde etrafı seyrederler.'),
  ('tr.diyanet', 83, 23, 'İyiler, şüphesiz, nimet içinde ve tahtlar üzerinde etrafı seyrederler.'),
  ('tr.diyanet', 83, 24, 'Onları, yüzlerindeki nimet pırıltısından tanırsın.'),
  ('tr.diyanet', 83, 25, 'Sonunda misk kokusu bırakan, ağzı kapalı saf bir içecekten içerler. İyi şeyler için yarışanlar, bunun için yarışsınlar.'),
  ('tr.diyanet', 83, 26, 'Sonunda misk kokusu bırakan, ağzı kapalı saf bir içecekten içerler. İyi şeyler için yarışanlar, bunun için yarışsınlar.'),
  ('tr.diyanet', 83, 27, 'Onun katkısı gözdelerin içtiği yüce kaynaktandır.'),
  ('tr.diyanet', 83, 28, 'Onun katkısı gözdelerin içtiği yüce kaynaktandır.'),
  ('tr.diyanet', 83, 29, 'Suçlular, şüphesiz, inanmış olanlara gülerlerdi.'),
  ('tr.diyanet', 83, 30, 'Yanlarından geçtikleri zaman da birbirlerine göz kırparlardı.'),
  ('tr.diyanet', 83, 31, 'Taraftarlarına vardıklarında bununla eğlenirlerdi.'),
  ('tr.diyanet', 83, 32, 'İnananları gördükleri zaman: "Doğrusu bunlar sapık olanlardır" derlerdi.'),
  ('tr.diyanet', 83, 33, 'Oysa kendileri, inananlara gözcü olarak gönderilmemişlerdi.'),
  ('tr.diyanet', 83, 34, 'Bugün de, inananlar inkarcılara gülerler.'),
  ('tr.diyanet', 83, 35, 'Tahtlar üzerinde, inkarcıların yaptıkları şeylerin karşılığının nasıl verildiğini seyrederler.'),
  ('tr.diyanet', 83, 36, 'Tahtlar üzerinde, inkarcıların yaptıkları şeylerin karşılığının nasıl verildiğini seyrederler.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 83, 1, 'Kecelakaan besarlah bagi orang-orang yang curang'),
  ('id.indonesian', 83, 2, '(yaitu) orang-orang yang apabila menerima takaran dari orang lain mereka minta dipenuhi,'),
  ('id.indonesian', 83, 3, 'dan apabila mereka menakar atau menimbang untuk orang lain, mereka mengurangi.'),
  ('id.indonesian', 83, 4, 'Tidaklah orang-orang itu menyangka, bahwa sesungguhnya mereka akan dibangkitkan,'),
  ('id.indonesian', 83, 5, 'pada suatu hari yang besar,'),
  ('id.indonesian', 83, 6, '(yaitu) hari (ketika) manusia berdiri menghadap Tuhan semesta alam?'),
  ('id.indonesian', 83, 7, 'Sekali-kali jangan curang, karena sesungguhnya kitab orang yang durhaka tersimpan dalam sijjin.'),
  ('id.indonesian', 83, 8, 'Tahukah kamu apakah sijjin itu?'),
  ('id.indonesian', 83, 9, '(Ialah) kitab yang bertulis.'),
  ('id.indonesian', 83, 10, 'Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan,'),
  ('id.indonesian', 83, 11, '(yaitu) orang-orang yang mendustakan hari pembalasan.'),
  ('id.indonesian', 83, 12, 'Dan tidak ada yang mendustakan hari pembalasan itu melainkan setiap orang yang melampaui batas lagi berdosa,'),
  ('id.indonesian', 83, 13, 'yang apabila dibacakan kepadanya ayat-ayat Kami, ia berkata: "Itu adalah dongengan orang-orang yang dahulu"'),
  ('id.indonesian', 83, 14, 'Sekali-kali tidak (demikian), sebenarnya apa yang selalu mereka usahakan itu menutupi hati mereka.'),
  ('id.indonesian', 83, 15, 'Sekali-kali tidak, sesungguhnya mereka pada hari itu benar-benar tertutup dari (rahmat) Tuhan mereka.'),
  ('id.indonesian', 83, 16, 'Kemudian, sesungguhnya mereka benar-benar masuk neraka.'),
  ('id.indonesian', 83, 17, 'Kemudian, dikatakan (kepada mereka): "Inilah azab yang dahulu selalu kamu dustakan".'),
  ('id.indonesian', 83, 18, 'Sekali-kali tidak, sesungguhnya kitab orang-orang yang berbakti itu (tersimpan) dalam \'Illiyyin.'),
  ('id.indonesian', 83, 19, 'Tahukah kamu apakah \'Illiyyin itu?'),
  ('id.indonesian', 83, 20, '(Yaitu) kitab yang bertulis,'),
  ('id.indonesian', 83, 21, 'yang disaksikan oleh malaikat-malaikat yang didekatkan (kepada Allah).'),
  ('id.indonesian', 83, 22, 'Sesungguhnya orang yang berbakti itu benar-benar berada dalam kenikmatan yang besar (surga),'),
  ('id.indonesian', 83, 23, 'mereka (duduk) di atas dipan-dipan sambil memandang.'),
  ('id.indonesian', 83, 24, 'Kamu dapat mengetahui dari wajah mereka kesenangan mereka yang penuh kenikmatan.'),
  ('id.indonesian', 83, 25, 'Mereka diberi minum dari khamar murni yang dilak (tempatnya),'),
  ('id.indonesian', 83, 26, 'laknya adalah kesturi; dan untuk yang demikian itu hendaknya orang berlomba-lomba.'),
  ('id.indonesian', 83, 27, 'Dan campuran khamar murni itu adalah dari tasnim,'),
  ('id.indonesian', 83, 28, '(yaitu) mata air yang minum daripadanya orang-orang yang didekatkan kepada Allah.'),
  ('id.indonesian', 83, 29, 'Sesungguhnya orang-orang yang berdosa, adalah mereka yang menertawakan orang-orang yang beriman.'),
  ('id.indonesian', 83, 30, 'Dan apabila orang-orang yang beriman lalu di hadapan mereka, mereka saling mengedip-ngedipkan matanya.'),
  ('id.indonesian', 83, 31, 'Dan apabila orang-orang yang berdosa itu kembali kepada kaumnya, mereka kembali dengan gembira.'),
  ('id.indonesian', 83, 32, 'Dan apabila mereka melihat orang-orang mukmin, mereka mengatakan: "Sesungguhnya mereka itu benar-benar orang-orang yang sesat",'),
  ('id.indonesian', 83, 33, 'padahal orang-orang yang berdosa itu tidak dikirim untuk penjaga bagi orang-orang mukmin.'),
  ('id.indonesian', 83, 34, 'Maka pada hari ini, orang-orang yang beriman menertawakan orang-orang kafir,'),
  ('id.indonesian', 83, 35, 'mereka (duduk) di atas dipan-dipan sambil memandang.'),
  ('id.indonesian', 83, 36, 'Sesungguhnya orang-orang kafir telah diberi ganjaran terhadap apa yang dahulu mereka kerjakan.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 84, 1, 'When the sky has split [open]'),
  ('en.sahih', 84, 2, 'And has responded to its Lord and was obligated [to do so]'),
  ('en.sahih', 84, 3, 'And when the earth has been extended'),
  ('en.sahih', 84, 4, 'And has cast out that within it and relinquished [it]'),
  ('en.sahih', 84, 5, 'And has responded to its Lord and was obligated [to do so] -'),
  ('en.sahih', 84, 6, 'O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it.'),
  ('en.sahih', 84, 7, 'Then as for he who is given his record in his right hand,'),
  ('en.sahih', 84, 8, 'He will be judged with an easy account'),
  ('en.sahih', 84, 9, 'And return to his people in happiness.'),
  ('en.sahih', 84, 10, 'But as for he who is given his record behind his back,'),
  ('en.sahih', 84, 11, 'He will cry out for destruction'),
  ('en.sahih', 84, 12, 'And [enter to] burn in a Blaze.'),
  ('en.sahih', 84, 13, 'Indeed, he had [once] been among his people in happiness;'),
  ('en.sahih', 84, 14, 'Indeed, he had thought he would never return [to Allah].'),
  ('en.sahih', 84, 15, 'But yes! Indeed, his Lord was ever of him, Seeing.'),
  ('en.sahih', 84, 16, 'So I swear by the twilight glow'),
  ('en.sahih', 84, 17, 'And [by] the night and what it envelops'),
  ('en.sahih', 84, 18, 'And [by] the moon when it becomes full'),
  ('en.sahih', 84, 19, '[That] you will surely experience state after state.'),
  ('en.sahih', 84, 20, 'So what is [the matter] with them [that] they do not believe,'),
  ('en.sahih', 84, 21, 'And when the Qur\'an is recited to them, they do not prostrate [to Allah]?'),
  ('en.sahih', 84, 22, 'But those who have disbelieved deny,'),
  ('en.sahih', 84, 23, 'And Allah is most knowing of what they keep within themselves.'),
  ('en.sahih', 84, 24, 'So give them tidings of a painful punishment,'),
  ('en.sahih', 84, 25, 'Except for those who believe and do righteous deeds. For them is a reward uninterrupted.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 84, 1, 'যখন আকাশ বিদীর্ণ হবে,'),
  ('bn.bengali', 84, 2, 'ও তার পালনকর্তার আদেশ পালন করবে এবং আকাশ এরই উপযুক্ত'),
  ('bn.bengali', 84, 3, 'এবং যখন পৃথিবীকে সম্প্রসারিত করা হবে।'),
  ('bn.bengali', 84, 4, 'এবং পৃথিবী তার গর্ভস্থিত সবকিছু বাইরে নিক্ষেপ করবে ও শুন্যগর্ভ হয়ে যাবে।'),
  ('bn.bengali', 84, 5, 'এবং তার পালনকর্তার আদেশ পালন করবে এবং পৃথিবী এরই উপযুক্ত।'),
  ('bn.bengali', 84, 6, 'হে মানুষ, তোমাকে তোমরা পালনকর্তা পর্যন্ত পৌছতে কষ্ট স্বীকার করতে হবে, অতঃপর তার সাক্ষাৎ ঘটবে।'),
  ('bn.bengali', 84, 7, 'যাকে তার আমলনামা ডান হাতে দেয়া হবে'),
  ('bn.bengali', 84, 8, 'তার হিসাব-নিকাশ সহজে হয়ে যাবে'),
  ('bn.bengali', 84, 9, 'এবং সে তার পরিবার-পরিজনের কাছে হৃষ্টচিত্তে ফিরে যাবে'),
  ('bn.bengali', 84, 10, 'এবং যাকে তার আমলনামা পিঠের পশ্চাদ্দিক থেকে দেয়া, হবে,'),
  ('bn.bengali', 84, 11, 'সে মৃত্যুকে আহবান করবে,'),
  ('bn.bengali', 84, 12, 'এবং জাহান্নামে প্রবেশ করবে।'),
  ('bn.bengali', 84, 13, 'সে তার পরিবার-পরিজনের মধ্যে আনন্দিত ছিল।'),
  ('bn.bengali', 84, 14, 'সে মনে করত যে, সে কখনও ফিরে যাবে না।'),
  ('bn.bengali', 84, 15, 'কেন যাবে না, তার পালনকর্তা তো তাকে দেখতেন।'),
  ('bn.bengali', 84, 16, 'আমি শপথ করি সন্ধ্যাকালীন লাল আভার'),
  ('bn.bengali', 84, 17, 'এবং রাত্রির, এবং তাতে যার সমাবেশ ঘটে'),
  ('bn.bengali', 84, 18, 'এবং চন্দ্রের, যখন তা পূর্ণরূপ লাভ করে,'),
  ('bn.bengali', 84, 19, 'নিশ্চয় তোমরা এক সিঁড়ি থেকে আরেক সিঁড়িতে আরোহণ করবে।'),
  ('bn.bengali', 84, 20, 'অতএব, তাদের কি হল যে, তারা ঈমান আনে না?'),
  ('bn.bengali', 84, 21, 'যখন তাদের কাছে কোরআন পাঠ করা হয়, তখন সেজদা করে না।'),
  ('bn.bengali', 84, 22, 'বরং কাফেররা এর প্রতি মিথ্যারোপ করে।'),
  ('bn.bengali', 84, 23, 'তারা যা সংরক্ষণ করে, আল্লাহ তা জানেন।'),
  ('bn.bengali', 84, 24, 'অতএব, তাদেরকে যন্ত্রণাদায়ক শাস্তির সুসংবাদ দিন।'),
  ('bn.bengali', 84, 25, 'কিন্তু যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে, তাদের জন্য রয়েছে অফুরন্ত পুরস্কার।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 84, 1, 'When the heaven is split asunder'),
  ('en.pickthall', 84, 2, 'And attentive to her Lord in fear,'),
  ('en.pickthall', 84, 3, 'And when the earth is spread out'),
  ('en.pickthall', 84, 4, 'And hath cast out all that was in her, and is empty'),
  ('en.pickthall', 84, 5, 'And attentive to her Lord in fear!'),
  ('en.pickthall', 84, 6, 'Thou, verily, O man, art working toward thy Lord a work which thou wilt meet (in His presence).'),
  ('en.pickthall', 84, 7, 'Then whoso is given his account in his right hand'),
  ('en.pickthall', 84, 8, 'He truly will receive an easy reckoning'),
  ('en.pickthall', 84, 9, 'And will return unto his folk in joy.'),
  ('en.pickthall', 84, 10, 'But whoso is given his account behind his back,'),
  ('en.pickthall', 84, 11, 'He surely will invoke destruction'),
  ('en.pickthall', 84, 12, 'And be thrown to scorching fire.'),
  ('en.pickthall', 84, 13, 'He verily lived joyous with his folk,'),
  ('en.pickthall', 84, 14, 'He verily deemed that he would never return (unto Allah).'),
  ('en.pickthall', 84, 15, 'Nay, but lo! his Lord is ever looking on him!'),
  ('en.pickthall', 84, 16, 'Oh, I swear by the afterglow of sunset,'),
  ('en.pickthall', 84, 17, 'And by the night and all that it enshroudeth,'),
  ('en.pickthall', 84, 18, 'And by the moon when she is at the full,'),
  ('en.pickthall', 84, 19, 'That ye shall journey on from plane to plane.'),
  ('en.pickthall', 84, 20, 'What aileth them, then, that they believe not'),
  ('en.pickthall', 84, 21, 'And, when the Qur\'an is recited unto them, worship not (Allah)?'),
  ('en.pickthall', 84, 22, 'Nay, but those who disbelieve will deny;'),
  ('en.pickthall', 84, 23, 'And Allah knoweth best what they are hiding.'),
  ('en.pickthall', 84, 24, 'So give them tidings of a painful doom,'),
  ('en.pickthall', 84, 25, 'Save those who believe and do good works, for theirs is a reward unfailing.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 84, 1, 'When the sky is rent asunder,'),
  ('en.yusufali', 84, 2, 'And hearkens to (the Command of) its Lord, and it must needs (do so);-'),
  ('en.yusufali', 84, 3, 'And when the earth is flattened out,'),
  ('en.yusufali', 84, 4, 'And casts forth what is within it and becomes (clean) empty,'),
  ('en.yusufali', 84, 5, 'And hearkens to (the Command of) its Lord,- and it must needs (do so);- (then will come Home the full reality).'),
  ('en.yusufali', 84, 6, 'O thou man! Verily thou art ever toiling on towards thy Lord- painfully toiling,- but thou shalt meet Him.'),
  ('en.yusufali', 84, 7, 'Then he who is given his Record in his right hand,'),
  ('en.yusufali', 84, 8, 'Soon will his account be taken by an easy reckoning,'),
  ('en.yusufali', 84, 9, 'And he will turn to his people, rejoicing!'),
  ('en.yusufali', 84, 10, 'But he who is given his Record behind his back,-'),
  ('en.yusufali', 84, 11, 'Soon will he cry for perdition,'),
  ('en.yusufali', 84, 12, 'And he will enter a Blazing Fire.'),
  ('en.yusufali', 84, 13, 'Truly, did he go about among his people, rejoicing!'),
  ('en.yusufali', 84, 14, 'Truly, did he think that he would not have to return (to Us)!'),
  ('en.yusufali', 84, 15, 'Nay, nay! for his Lord was (ever) watchful of him!'),
  ('en.yusufali', 84, 16, 'So I do call to witness the ruddy glow of Sunset;'),
  ('en.yusufali', 84, 17, 'The Night and its Homing;'),
  ('en.yusufali', 84, 18, 'And the Moon in her fullness:'),
  ('en.yusufali', 84, 19, 'Ye shall surely travel from stage to stage.'),
  ('en.yusufali', 84, 20, 'What then is the matter with them, that they believe not?-'),
  ('en.yusufali', 84, 21, 'And when the Qur\'an is read to them, they fall not prostrate,'),
  ('en.yusufali', 84, 22, 'But on the contrary the Unbelievers reject (it).'),
  ('en.yusufali', 84, 23, 'But Allah has full knowledge of what they secrete (in their breasts)'),
  ('en.yusufali', 84, 24, 'So announce to them a Penalty Grievous,'),
  ('en.yusufali', 84, 25, 'Except to those who believe and work righteous deeds: For them is a Reward that will never fail.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 84, 1, 'Izas samaaa\'un shaqqat'),
  ('en.transliteration', 84, 2, 'Wa azinat li Rabbihaa wa huqqat'),
  ('en.transliteration', 84, 3, 'Wa izal ardu muddat'),
  ('en.transliteration', 84, 4, 'Wa alqat maa feehaa wa takhallat'),
  ('en.transliteration', 84, 5, 'Wa azinat li Rabbihaa wa huqqat'),
  ('en.transliteration', 84, 6, 'Yaaa ayyuhal insaanu innaka kaadihun ilaa Rabbika kad han famulaaqeeh'),
  ('en.transliteration', 84, 7, 'Fa ammaa man ootiya kitaabahoo biyameenih'),
  ('en.transliteration', 84, 8, 'Fasawfa yuhaasabu hi saabai yaseeraa'),
  ('en.transliteration', 84, 9, 'Wa yanqalibu ilaaa ahlihee masrooraa'),
  ('en.transliteration', 84, 10, 'Wa ammaa man ootiya kitaabahoo waraaa\'a zahrih'),
  ('en.transliteration', 84, 11, 'Fasawfa yad\'oo subooraa'),
  ('en.transliteration', 84, 12, 'Wa yaslaa sa\'eeraa'),
  ('en.transliteration', 84, 13, 'Innahoo kaana feee ahlihee masrooraa'),
  ('en.transliteration', 84, 14, 'Innahoo zanna al lai yahoor'),
  ('en.transliteration', 84, 15, 'Balaaa inna Rabbahoo kaana bihee baseeraa'),
  ('en.transliteration', 84, 16, 'Falaaa uqsimu bishshafaq'),
  ('en.transliteration', 84, 17, 'Wallaili wa maa wasaq'),
  ('en.transliteration', 84, 18, 'Walqamari izat tasaq'),
  ('en.transliteration', 84, 19, 'Latarkabunna tabaqan \'an tabaq'),
  ('en.transliteration', 84, 20, 'Famaa lahum laa yu\'minoon'),
  ('en.transliteration', 84, 21, 'Wa izaa quri\'a \'alaihimul Quraanu laa yasjudoon'),
  ('en.transliteration', 84, 22, 'Balil lazeena kafaroo yukazziboon'),
  ('en.transliteration', 84, 23, 'Wallaahu a\'lamu bimaa yoo\'oon'),
  ('en.transliteration', 84, 24, 'Fabashshirhum bi\'azaabin aleem'),
  ('en.transliteration', 84, 25, 'Illal lazeena aamanoo wa \'amilus saalihaati lahum ajrun ghairu mamnoon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 84, 1, 'جب آسمان پھٹ جائے گا'),
  ('ur.ahmedali', 84, 2, 'اور اپنے رب کا حکم سن لے گا اور وہ اسی لائق ہے'),
  ('ur.ahmedali', 84, 3, 'اور جب زمین پھیلا دی جائے گی'),
  ('ur.ahmedali', 84, 4, 'اور جو کچھ اس میں ہے ڈال دے گی اور خالی ہو جائے گی'),
  ('ur.ahmedali', 84, 5, 'اور اپنے رب کا حکم سن لے گی اور وہ اسی لائق ہے'),
  ('ur.ahmedali', 84, 6, 'اے انسان تو اپنے رب کے پاس پہنچنے تک کام میں کوشش کر رہا ہے پھر اس سے جا ملے گا'),
  ('ur.ahmedali', 84, 7, 'پھر جس کا اعمال نامہ اس کے دائیں ہاتھ میں دیا گیا'),
  ('ur.ahmedali', 84, 8, 'تو اس سے آسانی کے ساتھ حساب لیا جائے گا'),
  ('ur.ahmedali', 84, 9, 'اور وہ اپنے اہل و عیال میں خوش واپس آئے گا'),
  ('ur.ahmedali', 84, 10, 'اور لیکن جس کو نامہٴ اعمال پیٹھ پیچھے سے دیا گیا'),
  ('ur.ahmedali', 84, 11, 'تو وہ موت کو پکارے گا'),
  ('ur.ahmedali', 84, 12, 'اور دوزخ میں داخل ہوگا'),
  ('ur.ahmedali', 84, 13, 'بے شک وہ اپنے اہل و عیال میں بڑا خوش و خرم تھا'),
  ('ur.ahmedali', 84, 14, 'بے شک اس نے سمجھ لیا تھا کہ ہر گز نہ لوٹ کر جائے گا'),
  ('ur.ahmedali', 84, 15, 'کیوں نہیں بے شک اس کا رب تو اس کو دیکھ رہا تھا'),
  ('ur.ahmedali', 84, 16, 'پس شام کی سرخی کی قسم ہے'),
  ('ur.ahmedali', 84, 17, 'اور رات کی اور جو کچھ اس نے سمیٹا'),
  ('ur.ahmedali', 84, 18, 'اور چاند کی جب کہ وہ پورا ہوجائے'),
  ('ur.ahmedali', 84, 19, 'کہ تمہیں ایک منزل سے دوسری منزل پر چڑھنا ہوگا'),
  ('ur.ahmedali', 84, 20, 'پھر انہیں کیا ہو گیا کہ ایمان نہیں لاتے'),
  ('ur.ahmedali', 84, 21, 'اور جب ان پر قرآن پڑھا جائے تو سجدہ نہیں کرتے'),
  ('ur.ahmedali', 84, 22, 'بلکہ جو لوگ منکر ہیں جھٹلاتے ہیں'),
  ('ur.ahmedali', 84, 23, 'اور الله خوب جانتا ہے وہ جو (دل میں) محفوظ رکھتے ہیں'),
  ('ur.ahmedali', 84, 24, 'پس انہیں دردناک عذاب کی خوشخبری دے دو'),
  ('ur.ahmedali', 84, 25, 'مگر جو لوگ ایمان لائے اورانہوں نے نیک عمل کیے ان کے لیے بے انتہا اجر ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 84, 1, 'Gök yarılıp Rabbine boyun eğdiği zaman, ki gök boyun eğecektir.'),
  ('tr.diyanet', 84, 2, 'Gök yarılıp Rabbine boyun eğdiği zaman, ki gök boyun eğecektir.'),
  ('tr.diyanet', 84, 3, 'Yer düzeltilip, içinde olanları dışarı atarak boşaldığı zaman ve yer Rabbine boyun eğdiği zaman, ki yer boyun eğecektir'),
  ('tr.diyanet', 84, 4, 'Yer düzeltilip, içinde olanları dışarı atarak boşaldığı zaman ve yer Rabbine boyun eğdiği zaman, ki yer boyun eğecektir'),
  ('tr.diyanet', 84, 5, 'Yer düzeltilip, içinde olanları dışarı atarak boşaldığı zaman ve yer Rabbine boyun eğdiği zaman, ki yer boyun eğecektir'),
  ('tr.diyanet', 84, 6, 'Ey insanoğlu! Sen Rabbine kavuşuncaya kadar çalışıp çabalarsın, sonunda O\'na kavuşacaksın.'),
  ('tr.diyanet', 84, 7, 'Amel defteri kendisine sağından verilen kimse, kolay geçireceği bir hesaba çekilir ve arkadaşlarının yanına sevinçle döner.'),
  ('tr.diyanet', 84, 8, 'Amel defteri kendisine sağından verilen kimse, kolay geçireceği bir hesaba çekilir ve arkadaşlarının yanına sevinçle döner.'),
  ('tr.diyanet', 84, 9, 'Amel defteri kendisine sağından verilen kimse, kolay geçireceği bir hesaba çekilir ve arkadaşlarının yanına sevinçle döner.'),
  ('tr.diyanet', 84, 10, 'Ama amel defteri kendisine arkasından verilen kimse: "Mahvoldum" diye bağırır ve çılgın alevli cehenneme girer.'),
  ('tr.diyanet', 84, 11, 'Ama amel defteri kendisine arkasından verilen kimse: "Mahvoldum" diye bağırır ve çılgın alevli cehenneme girer.'),
  ('tr.diyanet', 84, 12, 'Ama amel defteri kendisine arkasından verilen kimse: "Mahvoldum" diye bağırır ve çılgın alevli cehenneme girer.'),
  ('tr.diyanet', 84, 13, 'Çünkü o, dünyada, adamlarının yanında iken zevk içindeydi.'),
  ('tr.diyanet', 84, 14, 'Zira; o, bir daha dirilip dönmeyeceğini sanmıştı.'),
  ('tr.diyanet', 84, 15, 'Bilin ki, Rabbi onu şüphesiz görmekteydi.'),
  ('tr.diyanet', 84, 16, 'Akşamın alaca karanlığına and olsun;'),
  ('tr.diyanet', 84, 17, 'Geceye ve gecenin içinde olan şeylere and olsun;'),
  ('tr.diyanet', 84, 18, 'Dolunay halindeki aya and olsun ki:'),
  ('tr.diyanet', 84, 19, 'Şüphesiz siz bir durumdan diğerine uğratılacaksınız. (tabakadan tabakaya bineceksiniz)'),
  ('tr.diyanet', 84, 20, 'Onlara ne oluyor da inanmıyorlar?'),
  ('tr.diyanet', 84, 21, 'Onlara Kuran okunduğu zaman neden secde etmiyorlar?'),
  ('tr.diyanet', 84, 22, 'Aksine, inkarcılar yalanlıyorlar.'),
  ('tr.diyanet', 84, 23, 'Oysa, Allah, onların sakladıklarını çok iyi bilir.'),
  ('tr.diyanet', 84, 24, 'Onlara can yakıcı azabı müjde et.'),
  ('tr.diyanet', 84, 25, 'Yalnız, inanıp yararlı işler işleyenlere, onlara, kesintisiz ecir vardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 84, 1, 'Apabila langit terbelah,'),
  ('id.indonesian', 84, 2, 'dan patuh kepada Tuhannya, dan sudah semestinya langit itu patuh,'),
  ('id.indonesian', 84, 3, 'dan apabila bumi diratakan,'),
  ('id.indonesian', 84, 4, 'dan dilemparkan apa yang ada di dalamnya dan menjadi kosong,'),
  ('id.indonesian', 84, 5, 'dan patuh kepada Tuhannya, dan sudah semestinya bumi itu patuh, (pada waktu itu manusia akan mengetahui akibat perbuatannya).'),
  ('id.indonesian', 84, 6, 'Hai manusia, sesungguhnya kamu telah bekerja dengan sungguh-sungguh menuju Tuhanmu, maka pasti kamu akan menemui-Nya.'),
  ('id.indonesian', 84, 7, 'Adapun orang yang diberikan kitabnya dari sebelah kanannya,'),
  ('id.indonesian', 84, 8, 'maka dia akan diperiksa dengan pemeriksaan yang mudah,'),
  ('id.indonesian', 84, 9, 'dan dia akan kembali kepada kaumnya (yang sama-sama beriman) dengan gembira.'),
  ('id.indonesian', 84, 10, 'Adapun orang-orang yang diberikan kitabnya dari belakang,'),
  ('id.indonesian', 84, 11, 'maka dia akan berteriak: "Celakalah aku".'),
  ('id.indonesian', 84, 12, 'Dan dia akan masuk ke dalam api yang menyala-nyala (neraka).'),
  ('id.indonesian', 84, 13, 'Sesungguhnya dia dahulu (di dunia) bergembira di kalangan kaumnya (yang sama-sama kafir).'),
  ('id.indonesian', 84, 14, 'Sesungguhnya dia menyangka bahwa dia sekali-kali tidak akan kembali (kepada Tuhannya).'),
  ('id.indonesian', 84, 15, '(Bukan demikian), yang benar, sesungguhnya Tuhannya selalu melihatnya.'),
  ('id.indonesian', 84, 16, 'Maka sesungguhnya Aku bersumpah dengan cahaya merah di waktu senja,'),
  ('id.indonesian', 84, 17, 'dan dengan malam dan apa yang diselubunginya,'),
  ('id.indonesian', 84, 18, 'dan dengan bulan apabila jadi purnama,'),
  ('id.indonesian', 84, 19, 'sesungguhnya kamu melalui tingkat demi tingkat (dalam kehidupan),'),
  ('id.indonesian', 84, 20, 'Mengapa mereka tidak mau beriman?'),
  ('id.indonesian', 84, 21, 'dan apabila Al Quran dibacakan kepada mereka, mereka tidak bersujud,'),
  ('id.indonesian', 84, 22, 'bahkan orang-orang kafir itu mendustakan(nya).'),
  ('id.indonesian', 84, 23, 'Padahal Allah mengetahui apa yang mereka sembunyikan (dalam hati mereka).'),
  ('id.indonesian', 84, 24, 'Maka beri kabar gembiralah mereka dengan azab yang pedih,'),
  ('id.indonesian', 84, 25, 'tetapi orang-orang yang beriman dan beramal saleh, bagi mereka pahala yang tidak putus-putusnya.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 85, 1, 'By the sky containing great stars'),
  ('en.sahih', 85, 2, 'And [by] the promised Day'),
  ('en.sahih', 85, 3, 'And [by] the witness and what is witnessed,'),
  ('en.sahih', 85, 4, 'Cursed were the companions of the trench'),
  ('en.sahih', 85, 5, '[Containing] the fire full of fuel,'),
  ('en.sahih', 85, 6, 'When they were sitting near it'),
  ('en.sahih', 85, 7, 'And they, to what they were doing against the believers, were witnesses.'),
  ('en.sahih', 85, 8, 'And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy,'),
  ('en.sahih', 85, 9, 'To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness.'),
  ('en.sahih', 85, 10, 'Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire.'),
  ('en.sahih', 85, 11, 'Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment.'),
  ('en.sahih', 85, 12, 'Indeed, the vengeance of your Lord is severe.'),
  ('en.sahih', 85, 13, 'Indeed, it is He who originates [creation] and repeats.'),
  ('en.sahih', 85, 14, 'And He is the Forgiving, the Affectionate,'),
  ('en.sahih', 85, 15, 'Honorable Owner of the Throne,'),
  ('en.sahih', 85, 16, 'Effecter of what He intends.'),
  ('en.sahih', 85, 17, 'Has there reached you the story of the soldiers -'),
  ('en.sahih', 85, 18, '[Those of] Pharaoh and Thamud?'),
  ('en.sahih', 85, 19, 'But they who disbelieve are in [persistent] denial,'),
  ('en.sahih', 85, 20, 'While Allah encompasses them from behind.'),
  ('en.sahih', 85, 21, 'But this is an honored Qur\'an'),
  ('en.sahih', 85, 22, '[Inscribed] in a Preserved Slate.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 85, 1, 'শপথ গ্রহ-নক্ষত্র শোভিত আকাশের,'),
  ('bn.bengali', 85, 2, 'এবং প্রতিশ্রুত দিবসের,'),
  ('bn.bengali', 85, 3, 'এবং সেই দিবসের, যে উপস্থিত হয় ও যাতে উপস্থিত হয়'),
  ('bn.bengali', 85, 4, 'অভিশপ্ত হয়েছে গর্ত ওয়ালারা অর্থাৎ,'),
  ('bn.bengali', 85, 5, 'অনেক ইন্ধনের অগ্নিসংযোগকারীরা;'),
  ('bn.bengali', 85, 6, 'যখন তারা তার কিনারায় বসেছিল।'),
  ('bn.bengali', 85, 7, 'এবং তারা বিশ্বাসীদের সাথে যা করেছিল, তা নিরীক্ষণ করছিল।'),
  ('bn.bengali', 85, 8, 'তারা তাদেরকে শাস্তি দিয়েছিল শুধু এ কারণে যে, তারা প্রশংসিত, পরাক্রান্ত আল্লাহর প্রতি বিশ্বাস স্থাপন করেছিল,'),
  ('bn.bengali', 85, 9, 'যিনি নভোমন্ডল ও ভূমন্ডলের ক্ষমতার মালিক, আল্লাহর সামনে রয়েছে সবকিছু।'),
  ('bn.bengali', 85, 10, 'যারা মুমিন পুরুষ ও নারীকে নিপীড়ন করেছে, অতঃপর তওবা করেনি, তাদের জন্যে আছে জাহান্নামের শাস্তি, আর আছে দহন যন্ত্রণা,'),
  ('bn.bengali', 85, 11, 'যারা ঈমান আনে ও সৎকর্ম করে তাদের জন্যে আছে জান্নাত, যার তলদেশে প্রবাহিত হয় নির্ঝরিণীসমূহ। এটাই মহাসাফল্য।'),
  ('bn.bengali', 85, 12, 'নিশ্চয় তোমার পালনকর্তার পাকড়াও অত্যন্ত কঠিন।'),
  ('bn.bengali', 85, 13, 'তিনিই প্রথমবার অস্তিত্ব দান করেন এবং পুনরায় জীবিত করেন।'),
  ('bn.bengali', 85, 14, 'তিনি ক্ষমাশীল, প্রেমময়;'),
  ('bn.bengali', 85, 15, 'মহান আরশের অধিকারী।'),
  ('bn.bengali', 85, 16, 'তিনি যা চান, তাই করেন।'),
  ('bn.bengali', 85, 17, 'আপনার কাছে সৈন্যবাহিনীর ইতিবৃত্ত পৌছেছে কি?'),
  ('bn.bengali', 85, 18, 'ফেরাউনের এবং সামুদের?'),
  ('bn.bengali', 85, 19, 'বরং যারা কাফের, তারা মিথ্যারোপে রত আছে।'),
  ('bn.bengali', 85, 20, 'আল্লাহ তাদেরকে চতুর্দিক থেকে পরিবেষ্টন করে রেখেছেন।'),
  ('bn.bengali', 85, 21, 'বরং এটা মহান কোরআন,'),
  ('bn.bengali', 85, 22, 'লওহে মাহফুযে লিপিবদ্ধ।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 85, 1, 'By the heaven, holding mansions of the stars,'),
  ('en.pickthall', 85, 2, 'And by the Promised Day.'),
  ('en.pickthall', 85, 3, 'And by the witness and that whereunto he beareth testimony,'),
  ('en.pickthall', 85, 4, '(Self-)destroyed were the owners of the ditch'),
  ('en.pickthall', 85, 5, 'Of the fuel-fed fire,'),
  ('en.pickthall', 85, 6, 'When they sat by it,'),
  ('en.pickthall', 85, 7, 'And were themselves the witnesses of what they did to the believers.'),
  ('en.pickthall', 85, 8, 'They had naught against them save that they believed in Allah, the Mighty, the Owner of Praise,'),
  ('en.pickthall', 85, 9, 'Him unto Whom belongeth the Sovereignty of the heavens and the earth; and Allah is of all things the Witness.'),
  ('en.pickthall', 85, 10, 'Lo! they who persecute believing men and believing women and repent not, theirs verily will be the doom of hell, and theirs the doom of burning.'),
  ('en.pickthall', 85, 11, 'Lo! those who believe and do good works, theirs will be Gardens underneath which rivers flow. That is the Great Success.'),
  ('en.pickthall', 85, 12, 'Lo! the punishment of thy Lord is stern.'),
  ('en.pickthall', 85, 13, 'Lo! He it is Who produceth, then reproduceth,'),
  ('en.pickthall', 85, 14, 'And He is the Forgiving, the Loving,'),
  ('en.pickthall', 85, 15, 'Lord of the Throne of Glory,'),
  ('en.pickthall', 85, 16, 'Doer of what He will.'),
  ('en.pickthall', 85, 17, 'Hath there come unto thee the story of the hosts'),
  ('en.pickthall', 85, 18, 'Of Pharaoh and (the tribe of) Thamud?'),
  ('en.pickthall', 85, 19, 'Nay, but those who disbelieve live in denial'),
  ('en.pickthall', 85, 20, 'And Allah, all unseen, surroundeth them.'),
  ('en.pickthall', 85, 21, 'Nay, but it is a glorious Qur\'an.'),
  ('en.pickthall', 85, 22, 'On a guarded tablet.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 85, 1, 'By the sky, (displaying) the Zodiacal Signs;'),
  ('en.yusufali', 85, 2, 'By the promised Day (of Judgment);'),
  ('en.yusufali', 85, 3, 'By one that witnesses, and the subject of the witness;-'),
  ('en.yusufali', 85, 4, 'Woe to the makers of the pit (of fire),'),
  ('en.yusufali', 85, 5, 'Fire supplied (abundantly) with fuel:'),
  ('en.yusufali', 85, 6, 'Behold! they sat over against the (fire),'),
  ('en.yusufali', 85, 7, 'And they witnessed (all) that they were doing against the Believers.'),
  ('en.yusufali', 85, 8, 'And they ill-treated them for no other reason than that they believed in Allah, Exalted in Power, Worthy of all Praise!-'),
  ('en.yusufali', 85, 9, 'Him to Whom belongs the dominion of the heavens and the earth! And Allah is Witness to all things.'),
  ('en.yusufali', 85, 10, 'Those who persecute (or draw into temptation) the Believers, men and women, and do not turn in repentance, will have the Penalty of Hell: They will have the Penalty of the Burning Fire.'),
  ('en.yusufali', 85, 11, 'For those who believe and do righteous deeds, will be Gardens; beneath which rivers flow: That is the great Salvation, (the fulfilment of all desires),'),
  ('en.yusufali', 85, 12, 'Truly strong is the Grip (and Power) of thy Lord.'),
  ('en.yusufali', 85, 13, 'It is He Who creates from the very beginning, and He can restore (life).'),
  ('en.yusufali', 85, 14, 'And He is the Oft-Forgiving, Full of Loving-Kindness,'),
  ('en.yusufali', 85, 15, 'Lord of the Throne of Glory,'),
  ('en.yusufali', 85, 16, 'Doer (without let) of all that He intends.'),
  ('en.yusufali', 85, 17, 'Has the story reached thee, of the forces-'),
  ('en.yusufali', 85, 18, 'Of Pharaoh and the Thamud?'),
  ('en.yusufali', 85, 19, 'And yet the Unbelievers (persist) in rejecting (the Truth)!'),
  ('en.yusufali', 85, 20, 'But Allah doth encompass them from behind!'),
  ('en.yusufali', 85, 21, 'Nay, this is a Glorious Qur\'an,'),
  ('en.yusufali', 85, 22, '(Inscribed) in a Tablet Preserved!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 85, 1, 'Wassamaaa\'i zaatil burooj'),
  ('en.transliteration', 85, 2, 'Wal yawmil maw\'ood'),
  ('en.transliteration', 85, 3, 'Wa shaahidinw wa mashhood'),
  ('en.transliteration', 85, 4, 'Qutila as haabul ukhdood'),
  ('en.transliteration', 85, 5, 'Annaari zaatil waqood'),
  ('en.transliteration', 85, 6, 'Iz hum \'alaihaa qu\'ood'),
  ('en.transliteration', 85, 7, 'Wa hum \'alaa maa yaf\'aloona bilmu \'mineena shuhood'),
  ('en.transliteration', 85, 8, 'Wa maa naqamoo minhum illaaa aiyu\'minoo billaahil \'azeezil Hameed'),
  ('en.transliteration', 85, 9, 'Allazee lahoo mulkus samaawaati wal ard; wallaahu \'alaa kulli shai \'in Shaheed'),
  ('en.transliteration', 85, 10, 'Innal lazeena fatanul mu\'mineena wal mu\'minaati summa lam yatooboo falahum \'azaabu Jahannama wa lahum \'azaabul hareeq'),
  ('en.transliteration', 85, 11, 'Innal lazeena aamanoo wa \'amilus saalihaati lahum Jannaatun tajree min tahtihal anhaar; zaalikal fawzul kabeer'),
  ('en.transliteration', 85, 12, 'Inna batsha Rabbika lashadeed'),
  ('en.transliteration', 85, 13, 'Innahoo Huwa yubdi\'u wa yu\'eed'),
  ('en.transliteration', 85, 14, 'Wa Huwal Ghafoorul Wadood'),
  ('en.transliteration', 85, 15, 'Zul \'Arshil Majeed'),
  ('en.transliteration', 85, 16, 'Fa\' \'aalul limaa yureed'),
  ('en.transliteration', 85, 17, 'Hal ataaka hadeesul junood'),
  ('en.transliteration', 85, 18, 'Fir\'awna wa Samood'),
  ('en.transliteration', 85, 19, 'Balil lazeena kafaroo fee takzeeb'),
  ('en.transliteration', 85, 20, 'Wallaahu minw waraaa\'ihim muheet'),
  ('en.transliteration', 85, 21, 'Bal huwa Quraanum Majeed'),
  ('en.transliteration', 85, 22, 'Fee Lawhim Mahfooz')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 85, 1, 'آسمان کی قسم ہے جس میں برج ہیں'),
  ('ur.ahmedali', 85, 2, 'اوراس دن کی جس کا وعدہ کیا گیا ہے'),
  ('ur.ahmedali', 85, 3, 'اور اس دن کی جو حاضر ہوتا ہے اور اس کی جس کے پاس حاضر ہوتے ہیں'),
  ('ur.ahmedali', 85, 4, 'خندقوں والے ہلاک ہوئے'),
  ('ur.ahmedali', 85, 5, 'جس میں آگ تھی بہت ایندھن والی'),
  ('ur.ahmedali', 85, 6, 'جب کہ وہ اس کے کنارو ں پر بیٹھے ہوئے تھے'),
  ('ur.ahmedali', 85, 7, 'اور وہ ایمانداروں سے جو کچھ کر رہے تھے اس کو دیکھ رہے تھے'),
  ('ur.ahmedali', 85, 8, 'اور ان سے اسی کا توبدلہ لے رہے تھے کہ وہ الله زبردست خوبیوں والے پر ایمان لائے تھے'),
  ('ur.ahmedali', 85, 9, 'وہ کہ جس کے قبضہ میں آسمان اور زمین ہیں اور الله ہر چیز پر شاہد ہے'),
  ('ur.ahmedali', 85, 10, 'بے شک جنہوں نے ایمان دار مردوں اور ایمان دار عورتوں کو ستایا پھر توبہ نہ کی تو ان کے لیے جہنم کا عذاب ہے اور ان کے لیے جلانے والا عذاب ہے'),
  ('ur.ahmedali', 85, 11, 'بے شک جو لوگ ایمان لائے اور انہوں نے نیک کام بھی کیے ان کے لیے باغ ہیں جن کے نیچے نہریں بہتی ہوں گی یہی بڑی کامیابی ہے'),
  ('ur.ahmedali', 85, 12, 'بے شک تیرے رب کی پکڑ بھی سخت ہے'),
  ('ur.ahmedali', 85, 13, 'بے شک وہی پہلے پیدا کرتا ہے اور دوبارہ پیدا کرے گا'),
  ('ur.ahmedali', 85, 14, 'اور وہی ہے بخشنے والا محبت کرنے والا'),
  ('ur.ahmedali', 85, 15, 'عرش کا مالک بڑی شان والا'),
  ('ur.ahmedali', 85, 16, 'جو چاہے کرنے والا'),
  ('ur.ahmedali', 85, 17, 'کیا آپ کے پاس لشکروں کا حال پہنچا'),
  ('ur.ahmedali', 85, 18, 'فرعون اور ثمود کے'),
  ('ur.ahmedali', 85, 19, 'بلکہ منکر تو جھٹلانے میں لگے ہوئے ہیں'),
  ('ur.ahmedali', 85, 20, 'اور الله ہر طرف سے ان کو گھیرے ہوئے ہے'),
  ('ur.ahmedali', 85, 21, 'بلکہ وہ قرآن ہے بڑی شان والا'),
  ('ur.ahmedali', 85, 22, 'لوح محفوظ میں (لکھا ہوا ہے)')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 85, 1, 'İçinde burçları bulunan göğe and olsun;'),
  ('tr.diyanet', 85, 2, 'Söz verilen kıyamet gününe and olsun;'),
  ('tr.diyanet', 85, 3, 'Şahitlik edene ve edilene and olsun ki, insanlar öldükten sonra diriltileceklerdir.'),
  ('tr.diyanet', 85, 4, 'Hazırladıkları hendekleri, tutuşturulmuş ateşle doldurarak onun çevresinde oturup, inanmış kimselere dinlerinden dönmeleri için yaptıkları işkenceleri seyredenler kahrolmuştur!'),
  ('tr.diyanet', 85, 5, 'Hazırladıkları hendekleri, tutuşturulmuş ateşle doldurarak onun çevresinde oturup, inanmış kimselere dinlerinden dönmeleri için yaptıkları işkenceleri seyredenler kahrolmuştur!'),
  ('tr.diyanet', 85, 6, 'Hazırladıkları hendekleri, tutuşturulmuş ateşle doldurarak onun çevresinde oturup, inanmış kimselere dinlerinden dönmeleri için yaptıkları işkenceleri seyredenler kahrolmuştur!'),
  ('tr.diyanet', 85, 7, 'Hazırladıkları hendekleri, tutuşturulmuş ateşle doldurarak onun çevresinde oturup, inanmış kimselere dinlerinden dönmeleri için yaptıkları işkenceleri seyredenler kahrolmuştur!'),
  ('tr.diyanet', 85, 8, 'Bu inkarcıların, inananlara kızmaları; onların sadece, göklerin ve yerin hükümranlığı kendisinin bulunan ve övülmeğe layık ve güçlü olan Allah\'a inanmış olmalarındandı. Allah her şeye şahiddir.'),
  ('tr.diyanet', 85, 9, 'Bu inkarcıların, inananlara kızmaları; onların sadece, göklerin ve yerin hükümranlığı kendisinin bulunan ve övülmeğe layık ve güçlü olan Allah\'a inanmış olmalarındandı. Allah her şeye şahiddir.'),
  ('tr.diyanet', 85, 10, 'Ama inanmış erkek ve kadınlara işkence ederek onları dinlerinden çevirmeğe uğraşanlar, eğer tevbe etmezlerse, onlara cehennem azabı vardır. Yakıcı azap da onlaradır.'),
  ('tr.diyanet', 85, 11, 'Şüphesiz inanıp yararlı işler işleyenlere, onlara, içlerinden ırmaklar akan cennetler vardır. Bu, büyük kurtuluştur.'),
  ('tr.diyanet', 85, 12, 'Doğrusu Rabbinin yakalaması amansızdır.'),
  ('tr.diyanet', 85, 13, 'Önce yaratıp sonra bunu tekrar eden O\'dur.'),
  ('tr.diyanet', 85, 14, 'Yüce arşın sahibi, çok seven, bağışlayan O\'dur.'),
  ('tr.diyanet', 85, 15, 'Yüce arşın sahibi, çok seven, bağışlayan O\'dur.'),
  ('tr.diyanet', 85, 16, 'Her dilediğini mutlaka yapandır.'),
  ('tr.diyanet', 85, 17, 'Firavun ve Semud ordularının haberi sana geldi mi?'),
  ('tr.diyanet', 85, 18, 'Firavun ve Semud ordularının haberi sana geldi mi?'),
  ('tr.diyanet', 85, 19, 'Doğrusu inkar edenler, hep yalanlayagelmişlerdir.'),
  ('tr.diyanet', 85, 20, 'Oysa Allah onları ardlarından çevirmiştir.'),
  ('tr.diyanet', 85, 21, 'Doğrusu sana vahyedilen bu Kitap, Levhi Mahfuz\'da bulunan şanlı bir Kuran\'dır.'),
  ('tr.diyanet', 85, 22, 'Doğrusu sana vahyedilen bu Kitap, Levhi Mahfuz\'da bulunan şanlı bir Kuran\'dır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 85, 1, 'Demi langit yang mempunyai gugusan bintang,'),
  ('id.indonesian', 85, 2, 'dan hari yang dijanjikan,'),
  ('id.indonesian', 85, 3, 'dan yang menyaksikan dan yang disaksikan.'),
  ('id.indonesian', 85, 4, 'Binasa dan terlaknatlah orang-orang yang membuat parit,'),
  ('id.indonesian', 85, 5, 'yang berapi (dinyalakan dengan) kayu bakar,'),
  ('id.indonesian', 85, 6, 'ketika mereka duduk di sekitarnya,'),
  ('id.indonesian', 85, 7, 'sedang mereka menyaksikan apa yang mereka perbuat terhadap orang-orang yang beriman.'),
  ('id.indonesian', 85, 8, 'Dan mereka tidak menyiksa orang-orang mukmin itu melainkan karena orang-orang mukmin itu beriman kepada Allah Yang Maha Perkasa lagi Maha Terpuji,'),
  ('id.indonesian', 85, 9, 'Yang mempunyai kerajaan langit dan bumi; dan Allah Maha Menyaksikan segala sesuatu.'),
  ('id.indonesian', 85, 10, 'Sesungguhnya orang-orang yang mendatangkan cobaan kepada orang-orang yang mukmin laki-laki dan perempuan kemudian mereka tidak bertaubat, maka bagi mereka azab Jahannam dan bagi mereka azab (neraka) yang membakar.'),
  ('id.indonesian', 85, 11, 'Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal yang saleh bagi mereka surga yang mengalir di bawahnya sungai-sungai; itulah keberuntungan yang besar.'),
  ('id.indonesian', 85, 12, 'Sesungguhnya azab Tuhanmu benar-benar keras.'),
  ('id.indonesian', 85, 13, 'Sesungguhnya Dialah Yang menciptakan (makhluk) dari permulaan dan menghidupkannya (kembali).'),
  ('id.indonesian', 85, 14, 'Dialah Yang Maha Pengampun lagi Maha Pengasih,'),
  ('id.indonesian', 85, 15, 'yang mempunyai \'Arsy, lagi Maha Mulia,'),
  ('id.indonesian', 85, 16, 'Maha Kuasa berbuat apa yang dikehendaki-Nya.'),
  ('id.indonesian', 85, 17, 'Sudahkah datang kepadamu berita kaum-kaum penentang,'),
  ('id.indonesian', 85, 18, '(yaitu kaum) Fir\'aun dan (kaum) Tsamud?'),
  ('id.indonesian', 85, 19, 'Sesungguhnya orang-orang kafir selalu mendustakan,'),
  ('id.indonesian', 85, 20, 'padahal Allah mengepung mereka dari belakang mereka.'),
  ('id.indonesian', 85, 21, 'Bahkan yang didustakan mereka itu ialah Al Quran yang mulia,'),
  ('id.indonesian', 85, 22, 'yang (tersimpan) dalam Lauh Mahfuzh.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 86, 1, 'By the sky and the night comer -'),
  ('en.sahih', 86, 2, 'And what can make you know what is the night comer?'),
  ('en.sahih', 86, 3, 'It is the piercing star -'),
  ('en.sahih', 86, 4, 'There is no soul but that it has over it a protector.'),
  ('en.sahih', 86, 5, 'So let man observe from what he was created.'),
  ('en.sahih', 86, 6, 'He was created from a fluid, ejected,'),
  ('en.sahih', 86, 7, 'Emerging from between the backbone and the ribs.'),
  ('en.sahih', 86, 8, 'Indeed, Allah, to return him [to life], is Able.'),
  ('en.sahih', 86, 9, 'The Day when secrets will be put on trial,'),
  ('en.sahih', 86, 10, 'Then man will have no power or any helper.'),
  ('en.sahih', 86, 11, 'By the sky which returns [rain]'),
  ('en.sahih', 86, 12, 'And [by] the earth which cracks open,'),
  ('en.sahih', 86, 13, 'Indeed, the Qur\'an is a decisive statement,'),
  ('en.sahih', 86, 14, 'And it is not amusement.'),
  ('en.sahih', 86, 15, 'Indeed, they are planning a plan,'),
  ('en.sahih', 86, 16, 'But I am planning a plan.'),
  ('en.sahih', 86, 17, 'So allow time for the disbelievers. Leave them awhile.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 86, 1, 'শপথ আকাশের এবং রাত্রিতে আগমনকারীর।'),
  ('bn.bengali', 86, 2, 'আপনি জানেন, যে রাত্রিতে আসে সেটা কি?'),
  ('bn.bengali', 86, 3, 'সেটা এক উজ্জ্বল নক্ষত্র।'),
  ('bn.bengali', 86, 4, 'প্রত্যেকের উপর একজন তত্ত্বাবধায়ক রয়েছে।'),
  ('bn.bengali', 86, 5, 'অতএব, মানুষের দেখা উচিত কি বস্তু থেকে সে সৃজিত হয়েছে।'),
  ('bn.bengali', 86, 6, 'সে সৃজিত হয়েছে সবেগে স্খলিত পানি থেকে।'),
  ('bn.bengali', 86, 7, 'এটা নির্গত হয় মেরুদন্ড ও বক্ষপাজরের মধ্য থেকে।'),
  ('bn.bengali', 86, 8, 'নিশ্চয় তিনি তাকে ফিরিয়ে নিতে সক্ষম।'),
  ('bn.bengali', 86, 9, 'যেদিন গোপন বিষয়াদি পরীক্ষিত হবে,'),
  ('bn.bengali', 86, 10, 'সেদিন তার কোন শক্তি থাকবে না এবং সাহায্যকারীও থাকবে না।'),
  ('bn.bengali', 86, 11, 'শপথ চক্রশীল আকাশের'),
  ('bn.bengali', 86, 12, 'এবং বিদারনশীল পৃথিবীর'),
  ('bn.bengali', 86, 13, 'নিশ্চয় কোরআন সত্য-মিথ্যার ফয়সালা।'),
  ('bn.bengali', 86, 14, 'এবং এটা উপহাস নয়।'),
  ('bn.bengali', 86, 15, 'তারা ভীষণ চক্রান্ত করে,'),
  ('bn.bengali', 86, 16, 'আর আমিও কৌশল করি।'),
  ('bn.bengali', 86, 17, 'অতএব, কাফেরদেরকে অবকাশ দিন, তাদেরকে অবকাশ দিন, কিছু দিনের জন্যে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 86, 1, 'By the heaven and the Morning Star'),
  ('en.pickthall', 86, 2, '- Ah, what will tell thee what the Morning Star is!'),
  ('en.pickthall', 86, 3, '- The piercing Star!'),
  ('en.pickthall', 86, 4, 'No human soul but hath a guardian over it.'),
  ('en.pickthall', 86, 5, 'So let man consider from what he is created.'),
  ('en.pickthall', 86, 6, 'He is created from a gushing fluid'),
  ('en.pickthall', 86, 7, 'That issued from between the loins and ribs.'),
  ('en.pickthall', 86, 8, 'Lo! He verily is Able to return him (unto life)'),
  ('en.pickthall', 86, 9, 'On the day when hidden thoughts shall be searched out.'),
  ('en.pickthall', 86, 10, 'Then will he have no might nor any helper.'),
  ('en.pickthall', 86, 11, 'By the heaven which giveth the returning rain,'),
  ('en.pickthall', 86, 12, 'And the earth which splitteth (with the growth of trees and plants)'),
  ('en.pickthall', 86, 13, 'Lo! this (Qur\'an) is a conclusive word,'),
  ('en.pickthall', 86, 14, 'It is no pleasantry.'),
  ('en.pickthall', 86, 15, 'Lo! they plot a plot (against thee, O Muhammad)'),
  ('en.pickthall', 86, 16, 'And I plot a plot (against them).'),
  ('en.pickthall', 86, 17, 'So give a respite to the disbelievers. Deal thou gently with them for a while.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 86, 1, 'By the Sky and the Night-Visitant (therein);-'),
  ('en.yusufali', 86, 2, 'And what will explain to thee what the Night-Visitant is?-'),
  ('en.yusufali', 86, 3, '(It is) the Star of piercing brightness;-'),
  ('en.yusufali', 86, 4, 'There is no soul but has a protector over it.'),
  ('en.yusufali', 86, 5, 'Now let man but think from what he is created!'),
  ('en.yusufali', 86, 6, 'He is created from a drop emitted-'),
  ('en.yusufali', 86, 7, 'Proceeding from between the backbone and the ribs:'),
  ('en.yusufali', 86, 8, 'Surely (Allah) is able to bring him back (to life)!'),
  ('en.yusufali', 86, 9, 'The Day that (all) things secret will be tested,'),
  ('en.yusufali', 86, 10, '(Man) will have no power, and no helper.'),
  ('en.yusufali', 86, 11, 'By the Firmament which returns (in its round),'),
  ('en.yusufali', 86, 12, 'And by the Earth which opens out (for the gushing of springs or the sprouting of vegetation),-'),
  ('en.yusufali', 86, 13, 'Behold this is the Word that distinguishes (Good from Evil):'),
  ('en.yusufali', 86, 14, 'It is not a thing for amusement.'),
  ('en.yusufali', 86, 15, 'As for them, they are but plotting a scheme,'),
  ('en.yusufali', 86, 16, 'And I am planning a scheme.'),
  ('en.yusufali', 86, 17, 'Therefore grant a delay to the Unbelievers: Give respite to them gently (for awhile).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 86, 1, 'Wassamaaa\'i wattaariq'),
  ('en.transliteration', 86, 2, 'Wa maaa adraaka mattaariq'),
  ('en.transliteration', 86, 3, 'Annajmus saaqib'),
  ('en.transliteration', 86, 4, 'In kullu nafsil lammaa \'alaihaa haafiz'),
  ('en.transliteration', 86, 5, 'Fal yanzuril insaanu mimma khuliq'),
  ('en.transliteration', 86, 6, 'Khuliqa mim maaa\'in daafiq'),
  ('en.transliteration', 86, 7, 'Yakhruju mim bainissulbi wat taraaa\'ib'),
  ('en.transliteration', 86, 8, 'Innahoo \'alaa raj\'ihee laqaadir'),
  ('en.transliteration', 86, 9, 'Yawma tublas saraaa\'ir'),
  ('en.transliteration', 86, 10, 'Famaa lahoo min quwwatinw wa laa naasir'),
  ('en.transliteration', 86, 11, 'Wassamaaa\'i zaatir raj\''),
  ('en.transliteration', 86, 12, 'Wal ardi zaatis sad\''),
  ('en.transliteration', 86, 13, 'Innahoo laqawlun fasl'),
  ('en.transliteration', 86, 14, 'Wa maa huwa bil hazl'),
  ('en.transliteration', 86, 15, 'Innahum yakeedoona kaidaa'),
  ('en.transliteration', 86, 16, 'Wa akeedu kaidaa'),
  ('en.transliteration', 86, 17, 'Famahhilil kaafireena amhilhum ruwaidaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 86, 1, 'آسمان کی قسم ہے اور رات کو آنے والے کی'),
  ('ur.ahmedali', 86, 2, 'اور آپ کو کیا معلوم رات کو آنے والا کیا ہے'),
  ('ur.ahmedali', 86, 3, 'وہ چمکتا ہوا ستارہ ہے'),
  ('ur.ahmedali', 86, 4, 'ایسی کوئی بھی جان نہیں کہ جس پر ایک محافظ مقرر نہ ہو'),
  ('ur.ahmedali', 86, 5, 'پس انسان کو دیکھنا چاہیے کہ وہ کس چیز سے پیدا کیا گیا ہے'),
  ('ur.ahmedali', 86, 6, 'ایک اچھلتے ہوئے پانی سے پیدا کیا گیا ہے'),
  ('ur.ahmedali', 86, 7, 'جو پیٹھ اور سینے کی ہڈیوں کے درمیان سے نکلتا ہے'),
  ('ur.ahmedali', 86, 8, 'بے شک وہ اس کے لوٹانے پر قادر ہے'),
  ('ur.ahmedali', 86, 9, 'جس دن بھید ظاہر کیے جائیں گے'),
  ('ur.ahmedali', 86, 10, 'تو اس کے لیے نہ کوئی طاقت ہو گی اور نہ کوئی مددگار'),
  ('ur.ahmedali', 86, 11, 'آسمان اور بارش والے کی قسم ہے'),
  ('ur.ahmedali', 86, 12, 'اور زمین کی جو پھٹ جاتی ہے'),
  ('ur.ahmedali', 86, 13, 'بے شک قرآن قطعی بات ہے'),
  ('ur.ahmedali', 86, 14, 'اوروہ ہنسی کی بات نہیں ہے'),
  ('ur.ahmedali', 86, 15, 'بے شک وہ ایک تدبیر کر رہے ہیں'),
  ('ur.ahmedali', 86, 16, 'اور میں بھی ایک تدبیر کر رہا ہوں'),
  ('ur.ahmedali', 86, 17, 'پس کافرو ں کو تھوڑے دنوں کی مہلت دے دو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 86, 1, 'Göğe ve Tarık\'a and olsun;'),
  ('tr.diyanet', 86, 2, 'Tarık\'ın ne olduğunu sen bilir misin?'),
  ('tr.diyanet', 86, 3, 'O, (ışığıyla karanlığı) delen yıldızdır.'),
  ('tr.diyanet', 86, 4, 'Üzerinde gözetici olmayan kimse yoktur.'),
  ('tr.diyanet', 86, 5, 'Öyleyse insan neden yaratıldığına bir baksın.'),
  ('tr.diyanet', 86, 6, 'O, erkek ve kadının beli ile kaburga kemikleri arasından atılagelen bir sudan yaratılmıştır.'),
  ('tr.diyanet', 86, 7, 'O, erkek ve kadının beli ile kaburga kemikleri arasından atılagelen bir sudan yaratılmıştır.'),
  ('tr.diyanet', 86, 8, 'Şüphesiz Allah, gizliliklerin ortaya çıkacağı gün, insanı tekrar yaratmaya Kadir\'dir.'),
  ('tr.diyanet', 86, 9, 'Şüphesiz Allah, gizliliklerin ortaya çıkacağı gün, insanı tekrar yaratmaya Kadir\'dir.'),
  ('tr.diyanet', 86, 10, 'O gün, insanın gücü de, yardımcısı da olmaz.'),
  ('tr.diyanet', 86, 11, 'Dönüşlü göğe ve yarılan yeryüzüne and olsun ki,'),
  ('tr.diyanet', 86, 12, 'Dönüşlü göğe ve yarılan yeryüzüne and olsun ki,'),
  ('tr.diyanet', 86, 13, 'Doğrusu bu Kuran kesin bir sözdür.'),
  ('tr.diyanet', 86, 14, 'O, eğlence için değildir.'),
  ('tr.diyanet', 86, 15, 'Gerçekten onlar düzen kuruyorlar.'),
  ('tr.diyanet', 86, 16, 'Ben de bir düzen kurmaktayım.'),
  ('tr.diyanet', 86, 17, 'Sen inkarcılara mehil ver; onlara mukabeleyi biraz geri bırak.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 86, 1, 'Demi langit dan yang datang pada malam hari,'),
  ('id.indonesian', 86, 2, 'tahukah kamu apakah yang datang pada malam hari itu?'),
  ('id.indonesian', 86, 3, '(yaitu) bintang yang cahayanya menembus,'),
  ('id.indonesian', 86, 4, 'tidak ada suatu jiwapun (diri) melainkan ada penjaganya.'),
  ('id.indonesian', 86, 5, 'Maka hendaklah manusia memperhatikan dari apakah dia diciptakan?'),
  ('id.indonesian', 86, 6, 'Dia diciptakan dari air yang dipancarkan,'),
  ('id.indonesian', 86, 7, 'yang keluar dari antara tulang sulbi laki-laki dan tulang dada perempuan.'),
  ('id.indonesian', 86, 8, 'Sesungguhnya Allah benar-benar kuasa untuk mengembalikannya (hidup sesudah mati).'),
  ('id.indonesian', 86, 9, 'Pada hari dinampakkan segala rahasia,'),
  ('id.indonesian', 86, 10, 'maka sekali-kali tidak ada bagi manusia itu suatu kekuatanpun dan tidak (pula) seorang penolong.'),
  ('id.indonesian', 86, 11, 'Demi langit yang mengandung hujan'),
  ('id.indonesian', 86, 12, 'dan bumi yang mempunyai tumbuh-tumbuhan,'),
  ('id.indonesian', 86, 13, 'sesungguhnya Al Quran itu benar-benar firman yang memisahkan antara yang hak dan yang bathil.'),
  ('id.indonesian', 86, 14, 'dan sekali-kali bukanlah dia senda gurau.'),
  ('id.indonesian', 86, 15, 'Sesungguhnya orang kafir itu merencanakan tipu daya yang jahat dengan sebenar-benarnya.'),
  ('id.indonesian', 86, 16, 'Dan Akupun membuat rencana (pula) dengan sebenar-benarnya.'),
  ('id.indonesian', 86, 17, 'Karena itu beri tangguhlah orang-orang kafir itu yaitu beri tangguhlah mereka itu barang sebentar.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 87, 1, 'Exalt the name of your Lord, the Most High,'),
  ('en.sahih', 87, 2, 'Who created and proportioned'),
  ('en.sahih', 87, 3, 'And who destined and [then] guided'),
  ('en.sahih', 87, 4, 'And who brings out the pasture'),
  ('en.sahih', 87, 5, 'And [then] makes it black stubble.'),
  ('en.sahih', 87, 6, 'We will make you recite, [O Muhammad], and you will not forget,'),
  ('en.sahih', 87, 7, 'Except what Allah should will. Indeed, He knows what is declared and what is hidden.'),
  ('en.sahih', 87, 8, 'And We will ease you toward ease.'),
  ('en.sahih', 87, 9, 'So remind, if the reminder should benefit;'),
  ('en.sahih', 87, 10, 'He who fears [Allah] will be reminded.'),
  ('en.sahih', 87, 11, 'But the wretched one will avoid it -'),
  ('en.sahih', 87, 12, '[He] who will [enter and] burn in the greatest Fire,'),
  ('en.sahih', 87, 13, 'Neither dying therein nor living.'),
  ('en.sahih', 87, 14, 'He has certainly succeeded who purifies himself'),
  ('en.sahih', 87, 15, 'And mentions the name of his Lord and prays.'),
  ('en.sahih', 87, 16, 'But you prefer the worldly life,'),
  ('en.sahih', 87, 17, 'While the Hereafter is better and more enduring.'),
  ('en.sahih', 87, 18, 'Indeed, this is in the former scriptures,'),
  ('en.sahih', 87, 19, 'The scriptures of Abraham and Moses.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 87, 1, 'আপনি আপনার মহান পালনকর্তার নামের পবিত্রতা বর্ণনা করুন'),
  ('bn.bengali', 87, 2, 'যিনি সৃষ্টি করেছেন ও সুবিন্যস্ত করেছেন।'),
  ('bn.bengali', 87, 3, 'এবং যিনি সুপরিমিত করেছেন ও পথ প্রদর্শন করেছেন'),
  ('bn.bengali', 87, 4, 'এবং যিনি তৃণাদি উৎপন্ন করেছেন,'),
  ('bn.bengali', 87, 5, 'অতঃপর করেছেন তাকে কাল আবর্জনা।'),
  ('bn.bengali', 87, 6, 'আমি আপনাকে পাঠ করাতে থাকব, ফলে আপনি বিস্মৃত হবেন না'),
  ('bn.bengali', 87, 7, 'আল্লাহ যা ইচ্ছা করেন তা ব্যতীত। নিশ্চয় তিনি জানেন প্রকাশ্য ও গোপন বিষয়।'),
  ('bn.bengali', 87, 8, 'আমি আপনার জন্যে সহজ শরীয়ত সহজতর করে দেবো।'),
  ('bn.bengali', 87, 9, 'উপদেশ ফলপ্রসূ হলে উপদেশ দান করুন,'),
  ('bn.bengali', 87, 10, 'যে ভয় করে, সে উপদেশ গ্রহণ করবে,'),
  ('bn.bengali', 87, 11, 'আর যে, হতভাগা, সে তা উপেক্ষা করবে,'),
  ('bn.bengali', 87, 12, 'সে মহা-অগ্নিতে প্রবেশ করবে।'),
  ('bn.bengali', 87, 13, 'অতঃপর সেখানে সে মরবেও না, জীবিতও থাকবে না।'),
  ('bn.bengali', 87, 14, 'নিশ্চয় সাফল্য লাভ করবে সে, যে শুদ্ধ হয়'),
  ('bn.bengali', 87, 15, 'এবং তার পালনকর্তার নাম স্মরণ করে, অতঃপর নামায আদায় করে।'),
  ('bn.bengali', 87, 16, 'বস্তুতঃ তোমরা পার্থিব জীবনকে অগ্রাধিকার দাও,'),
  ('bn.bengali', 87, 17, 'অথচ পরকালের জীবন উৎকৃষ্ট ও স্থায়ী।'),
  ('bn.bengali', 87, 18, 'এটা লিখিত রয়েছে পূর্ববতী কিতাবসমূহে;'),
  ('bn.bengali', 87, 19, 'ইব্রাহীম ও মূসার কিতাবসমূহে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 87, 1, 'Praise the name of thy Lord the Most High,'),
  ('en.pickthall', 87, 2, 'Who createth, then disposeth;'),
  ('en.pickthall', 87, 3, 'Who measureth, then guideth;'),
  ('en.pickthall', 87, 4, 'Who bringeth forth the pasturage,'),
  ('en.pickthall', 87, 5, 'Then turneth it to russet stubble.'),
  ('en.pickthall', 87, 6, 'We shall make thee read (O Muhammad) so that thou shalt not forget'),
  ('en.pickthall', 87, 7, 'Save that which Allah willeth. Lo! He knoweth the disclosed and that which still is hidden;'),
  ('en.pickthall', 87, 8, 'And We shall ease thy way unto the state of ease.'),
  ('en.pickthall', 87, 9, 'Therefor remind (men), for of use is the reminder.'),
  ('en.pickthall', 87, 10, 'He will heed who feareth,'),
  ('en.pickthall', 87, 11, 'But the most hapless will flout it,'),
  ('en.pickthall', 87, 12, 'He who will be flung to the great Fire'),
  ('en.pickthall', 87, 13, 'Wherein he will neither die nor live.'),
  ('en.pickthall', 87, 14, 'He is successful who groweth,'),
  ('en.pickthall', 87, 15, 'And remembereth the name of his Lord, so prayeth,'),
  ('en.pickthall', 87, 16, 'But ye prefer the life of the world'),
  ('en.pickthall', 87, 17, 'Although the Hereafter is better and more lasting.'),
  ('en.pickthall', 87, 18, 'Lo! This is in the former scrolls.'),
  ('en.pickthall', 87, 19, 'The Books of Abraham and Moses.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 87, 1, 'Glorify the name of thy Guardian-Lord Most High,'),
  ('en.yusufali', 87, 2, 'Who hath created, and further, given order and proportion;'),
  ('en.yusufali', 87, 3, 'Who hath ordained laws. And granted guidance;'),
  ('en.yusufali', 87, 4, 'And Who bringeth out the (green and luscious) pasture,'),
  ('en.yusufali', 87, 5, 'And then doth make it (but) swarthy stubble.'),
  ('en.yusufali', 87, 6, 'By degrees shall We teach thee to declare (the Message), so thou shalt not forget,'),
  ('en.yusufali', 87, 7, 'Except as Allah wills: For He knoweth what is manifest and what is hidden.'),
  ('en.yusufali', 87, 8, 'And We will make it easy for thee (to follow) the simple (Path).'),
  ('en.yusufali', 87, 9, 'Therefore give admonition in case the admonition profits (the hearer).'),
  ('en.yusufali', 87, 10, 'The admonition will be received by those who fear (Allah):'),
  ('en.yusufali', 87, 11, 'But it will be avoided by those most unfortunate ones,'),
  ('en.yusufali', 87, 12, 'Who will enter the Great Fire,'),
  ('en.yusufali', 87, 13, 'In which they will then neither die nor live.'),
  ('en.yusufali', 87, 14, 'But those will prosper who purify themselves,'),
  ('en.yusufali', 87, 15, 'And glorify the name of their Guardian-Lord, and (lift their hearts) in prayer.'),
  ('en.yusufali', 87, 16, 'Nay (behold), ye prefer the life of this world;'),
  ('en.yusufali', 87, 17, 'But the Hereafter is better and more enduring.'),
  ('en.yusufali', 87, 18, 'And this is in the Books of the earliest (Revelation),-'),
  ('en.yusufali', 87, 19, 'The Books of Abraham and Moses.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 87, 1, 'Sabbihisma Rabbikal A\'laa'),
  ('en.transliteration', 87, 2, 'Allazee khalaqa fasawwaa'),
  ('en.transliteration', 87, 3, 'Wallazee qaddara fahadaa'),
  ('en.transliteration', 87, 4, 'Wallazeee akhrajal mar\'aa'),
  ('en.transliteration', 87, 5, 'Faja\'alahoo ghusaaa\'an ahwaa'),
  ('en.transliteration', 87, 6, 'Sanuqri\'uka falaa tansaaa'),
  ('en.transliteration', 87, 7, 'Illaa maa shaaa\'al laah; innahoo ya\'lamul jahra wa maa yakhfaa'),
  ('en.transliteration', 87, 8, 'Wa nu-yassiruka lilyusraa'),
  ('en.transliteration', 87, 9, 'Fazakkir in nafa\'atizzikraa'),
  ('en.transliteration', 87, 10, 'Sa yazzakkaru maiyakhshaa'),
  ('en.transliteration', 87, 11, 'Wa yatajannabuhal ashqaa'),
  ('en.transliteration', 87, 12, 'Allazee yaslan Naaral kubraa'),
  ('en.transliteration', 87, 13, 'Summa laa yamootu feehaa wa laa yahyaa'),
  ('en.transliteration', 87, 14, 'Qad aflaha man tazakkaa'),
  ('en.transliteration', 87, 15, 'Wa zakaras ma Rabbihee fasallaa'),
  ('en.transliteration', 87, 16, 'Bal tu\'siroonal hayaatad dunyaa'),
  ('en.transliteration', 87, 17, 'Wal Aakhiratu khairunw wa abqaa'),
  ('en.transliteration', 87, 18, 'Inna haazaa lafis suhu fil oolaa'),
  ('en.transliteration', 87, 19, 'Suhufi Ibraaheema wa Moosaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 87, 1, 'اپنے رب کے نام کی تسبیح کیا کر جو سب سے اعلیٰ ہے'),
  ('ur.ahmedali', 87, 2, 'وہ جس نے پیدا کیا پھر ٹھیک بنایا'),
  ('ur.ahmedali', 87, 3, 'اور جس نے اندازہ ٹھہرایا پھر راہ دکھائی'),
  ('ur.ahmedali', 87, 4, 'اور وہ جس نے چارہ نکالا'),
  ('ur.ahmedali', 87, 5, 'پھر اس کو خشک چورا سیاہ کر دیا'),
  ('ur.ahmedali', 87, 6, 'البتہ ہم آپ کو پڑھائیں گے پھر آپ نہ بھولیں گے'),
  ('ur.ahmedali', 87, 7, 'مگر جو الله چاہے بے شک وہ ہرظاہر اور چھپی بات کو جانتا ہے'),
  ('ur.ahmedali', 87, 8, 'اور ہم آپ کو آسان شریعت کے سمجھنے کی توفیق دیں گے'),
  ('ur.ahmedali', 87, 9, 'پس آپ نصیحت کیجیئے اگر نصیحت فائدہ دے'),
  ('ur.ahmedali', 87, 10, 'جو الله سے ڈرتا ہے وہ جلدی سمجھ جائے گا'),
  ('ur.ahmedali', 87, 11, 'اور اس سے بڑا بدنصیب الگ رہے گا'),
  ('ur.ahmedali', 87, 12, 'جو سخت آگ میں داخل ہوگا'),
  ('ur.ahmedali', 87, 13, 'پھر اس میں نہ تو مرے گا اور نہ جیئے گا'),
  ('ur.ahmedali', 87, 14, 'بے شک وہ کامیاب ہوا جو پاک ہو گیا'),
  ('ur.ahmedali', 87, 15, 'اور اپنے رب کا نام یاد کیا پھر نماز پڑھی'),
  ('ur.ahmedali', 87, 16, 'بلکہ تم تودنیا کی زندگی کو ترجیح دیتے ہو'),
  ('ur.ahmedali', 87, 17, 'حالانکہ آخرت بہتر اور زیادہ پائدار ہے'),
  ('ur.ahmedali', 87, 18, 'بے شک یہی پہلے صحیفوں میں ہے'),
  ('ur.ahmedali', 87, 19, '(یعنی) ابراھیم اور موسیٰ کے صحیفوں میں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 87, 1, 'Yüce Rabbinin adını tesbih et.'),
  ('tr.diyanet', 87, 2, 'O, yaratıp şekil vermiştir.'),
  ('tr.diyanet', 87, 3, 'O, her şeyi ölçüyle yapıp doğru yolu göstermiştir.'),
  ('tr.diyanet', 87, 4, 'O, yeşillikler bitirmiştir.'),
  ('tr.diyanet', 87, 5, 'Sonra da onları siyah çerçöpe çevirmiştir.'),
  ('tr.diyanet', 87, 6, 'Sana Kuran\'ı Biz okutacağız ve asla unutmayacaksın;'),
  ('tr.diyanet', 87, 7, 'Allah\'ın dilediği bundan müstesnadır. Doğrusu açığı da, gizliyi de bilen O\'dur.'),
  ('tr.diyanet', 87, 8, 'Kolay olanı yapmayı sana kolaylaştırırız.'),
  ('tr.diyanet', 87, 9, 'Faydalı olacaksa insanlara öğüt ver.'),
  ('tr.diyanet', 87, 10, 'Allah\'tan korkan öğüt alacaktır.'),
  ('tr.diyanet', 87, 11, 'Bedbaht olan ondan kaçınacaktır.'),
  ('tr.diyanet', 87, 12, 'O, en büyük ateşe yaslanacaktır.'),
  ('tr.diyanet', 87, 13, 'O, orada ne ölecektir ne de dirilecektir.'),
  ('tr.diyanet', 87, 14, 'Arınmış olan, Rabbinin adını anıp namaz kılan, saadete erişecektir.'),
  ('tr.diyanet', 87, 15, 'Arınmış olan, Rabbinin adını anıp namaz kılan, saadete erişecektir.'),
  ('tr.diyanet', 87, 16, 'Ama sizler dünya hayatını tercih ediyorsunuz.'),
  ('tr.diyanet', 87, 17, 'Oysa ahiret daha iyi ve daha bakidir.'),
  ('tr.diyanet', 87, 18, 'Doğrusu bu hükümler ilk sahifelerde, İbrahim ve Musa\'nın sahifelerinde de vardır.'),
  ('tr.diyanet', 87, 19, 'Doğrusu bu hükümler ilk sahifelerde, İbrahim ve Musa\'nın sahifelerinde de vardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 87, 1, 'Sucikanlah nama Tuhanmu Yang Maha Tingi,'),
  ('id.indonesian', 87, 2, 'yang menciptakan, dan menyempurnakan (penciptaan-Nya),'),
  ('id.indonesian', 87, 3, 'dan yang menentukan kadar (masing-masing) dan memberi petunjuk,'),
  ('id.indonesian', 87, 4, 'dan yang menumbuhkan rumput-rumputan,'),
  ('id.indonesian', 87, 5, 'lalu dijadikan-Nya rumput-rumput itu kering kehitam-hitaman.'),
  ('id.indonesian', 87, 6, 'Kami akan membacakan (Al Quran) kepadamu (Muhammad) maka kamu tidak akan lupa,'),
  ('id.indonesian', 87, 7, 'kecuali kalau Allah menghendaki. Sesungguhnya Dia mengetahui yang terang dan yang tersembunyi.'),
  ('id.indonesian', 87, 8, 'dan Kami akan memberi kamu taufik ke jalan yang mudah,'),
  ('id.indonesian', 87, 9, 'oleh sebab itu berikanlah peringatan karena peringatan itu bermanfaat,'),
  ('id.indonesian', 87, 10, 'orang yang takut (kepada Allah) akan mendapat pelajaran,'),
  ('id.indonesian', 87, 11, 'dan orang-orang yang celaka (kafir) akan menjauhinya.'),
  ('id.indonesian', 87, 12, '(Yaitu) orang yang akan memasuki api yang besar (neraka).'),
  ('id.indonesian', 87, 13, 'Kemudian dia tidak akan mati di dalamnya dan tidak (pula) hidup.'),
  ('id.indonesian', 87, 14, 'Sesungguhnya beruntunglah orang yang membersihkan diri (dengan beriman),'),
  ('id.indonesian', 87, 15, 'dan dia ingat nama Tuhannya, lalu dia sembahyang.'),
  ('id.indonesian', 87, 16, 'Tetapi kamu (orang-orang kafir) memilih kehidupan duniawi.'),
  ('id.indonesian', 87, 17, 'Sedang kehidupan akhirat adalah lebih baik dan lebih kekal.'),
  ('id.indonesian', 87, 18, 'Sesungguhnya ini benar-benar terdapat dalam kitab-kitab yang dahulu,'),
  ('id.indonesian', 87, 19, '(yaitu) Kitab-kitab Ibrahim dan Musa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 88, 1, 'Has there reached you the report of the Overwhelming [event]?'),
  ('en.sahih', 88, 2, '[Some] faces, that Day, will be humbled,'),
  ('en.sahih', 88, 3, 'Working [hard] and exhausted.'),
  ('en.sahih', 88, 4, 'They will [enter to] burn in an intensely hot Fire.'),
  ('en.sahih', 88, 5, 'They will be given drink from a boiling spring.'),
  ('en.sahih', 88, 6, 'For them there will be no food except from a poisonous, thorny plant'),
  ('en.sahih', 88, 7, 'Which neither nourishes nor avails against hunger.'),
  ('en.sahih', 88, 8, '[Other] faces, that Day, will show pleasure.'),
  ('en.sahih', 88, 9, 'With their effort [they are] satisfied'),
  ('en.sahih', 88, 10, 'In an elevated garden,'),
  ('en.sahih', 88, 11, 'Wherein they will hear no unsuitable speech.'),
  ('en.sahih', 88, 12, 'Within it is a flowing spring.'),
  ('en.sahih', 88, 13, 'Within it are couches raised high'),
  ('en.sahih', 88, 14, 'And cups put in place'),
  ('en.sahih', 88, 15, 'And cushions lined up'),
  ('en.sahih', 88, 16, 'And carpets spread around.'),
  ('en.sahih', 88, 17, 'Then do they not look at the camels - how they are created?'),
  ('en.sahih', 88, 18, 'And at the sky - how it is raised?'),
  ('en.sahih', 88, 19, 'And at the mountains - how they are erected?'),
  ('en.sahih', 88, 20, 'And at the earth - how it is spread out?'),
  ('en.sahih', 88, 21, 'So remind, [O Muhammad]; you are only a reminder.'),
  ('en.sahih', 88, 22, 'You are not over them a controller.'),
  ('en.sahih', 88, 23, 'However, he who turns away and disbelieves -'),
  ('en.sahih', 88, 24, 'Then Allah will punish him with the greatest punishment.'),
  ('en.sahih', 88, 25, 'Indeed, to Us is their return.'),
  ('en.sahih', 88, 26, 'Then indeed, upon Us is their account.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 88, 1, 'আপনার কাছে আচ্ছন্নকারী কেয়ামতের বৃত্তান্ত পৌঁছেছে কি?'),
  ('bn.bengali', 88, 2, 'অনেক মুখমন্ডল সেদিন হবে লাঞ্ছিত,'),
  ('bn.bengali', 88, 3, 'ক্লিষ্ট, ক্লান্ত।'),
  ('bn.bengali', 88, 4, 'তারা জ্বলন্ত আগুনে পতিত হবে।'),
  ('bn.bengali', 88, 5, 'তাদেরকে ফুটন্ত নহর থেকে পান করানো হবে।'),
  ('bn.bengali', 88, 6, 'কন্টকপূর্ণ ঝাড় ব্যতীত তাদের জন্যে কোন খাদ্য নেই।'),
  ('bn.bengali', 88, 7, 'এটা তাদেরকে পুষ্ট করবে না এবং ক্ষুধায়ও উপকার করবে না।'),
  ('bn.bengali', 88, 8, 'অনেক মুখমন্ডল সেদিন হবে, সজীব,'),
  ('bn.bengali', 88, 9, 'তাদের কর্মের কারণে সন্তুষ্ট।'),
  ('bn.bengali', 88, 10, 'তারা থাকবে, সুউচ্চ জান্নাতে।'),
  ('bn.bengali', 88, 11, 'তথায় শুনবে না কোন অসার কথাবার্তা।'),
  ('bn.bengali', 88, 12, 'তথায় থাকবে প্রবাহিত ঝরণা।'),
  ('bn.bengali', 88, 13, 'তথায় থাকবে উন্নত সুসজ্জিত আসন।'),
  ('bn.bengali', 88, 14, 'এবং সংরক্ষিত পানপাত্র'),
  ('bn.bengali', 88, 15, 'এবং সারি সারি গালিচা'),
  ('bn.bengali', 88, 16, 'এবং বিস্তৃত বিছানো কার্পেট।'),
  ('bn.bengali', 88, 17, 'তারা কি উষ্ট্রের প্রতি লক্ষ্য করে না যে, তা কিভাবে সৃষ্টি করা হয়েছে?'),
  ('bn.bengali', 88, 18, 'এবং আকাশের প্রতি লক্ষ্য করে না যে, তা কিভাবে উচ্চ করা হয়েছে?'),
  ('bn.bengali', 88, 19, 'এবং পাহাড়ের দিকে যে, তা কিভাবে স্থাপন করা হয়েছে?'),
  ('bn.bengali', 88, 20, 'এবং পৃথিবীর দিকে যে, তা কিভাবে সমতল বিছানো হয়েছে?'),
  ('bn.bengali', 88, 21, 'অতএব, আপনি উপদেশ দিন, আপনি তো কেবল একজন উপদেশদাতা,'),
  ('bn.bengali', 88, 22, 'আপনি তাদের শাসক নন,'),
  ('bn.bengali', 88, 23, 'কিন্তু যে মুখ ফিরিয়ে নেয় ও কাফের হয়ে যায়,'),
  ('bn.bengali', 88, 24, 'আল্লাহ তাকে মহা আযাব দেবেন।'),
  ('bn.bengali', 88, 25, 'নিশ্চয় তাদের প্রত্যাবর্তন আমারই নিকট,'),
  ('bn.bengali', 88, 26, 'অতঃপর তাদের হিসাব-নিকাশ আমারই দায়িত্ব।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 88, 1, 'Hath there come unto thee tidings of the Overwhelming?'),
  ('en.pickthall', 88, 2, 'On that day (many) faces will be downcast,'),
  ('en.pickthall', 88, 3, 'Toiling, weary,'),
  ('en.pickthall', 88, 4, 'Scorched by burning fire,'),
  ('en.pickthall', 88, 5, 'Drinking from a boiling spring,'),
  ('en.pickthall', 88, 6, 'No food for them save bitter thorn-fruit'),
  ('en.pickthall', 88, 7, 'Which doth not nourish nor release from hunger.'),
  ('en.pickthall', 88, 8, 'In that day other faces will be calm,'),
  ('en.pickthall', 88, 9, 'Glad for their effort past,'),
  ('en.pickthall', 88, 10, 'In a high Garden'),
  ('en.pickthall', 88, 11, 'Where they hear no idle speech,'),
  ('en.pickthall', 88, 12, 'Wherein is a gushing spring,'),
  ('en.pickthall', 88, 13, 'Wherein are couches raised'),
  ('en.pickthall', 88, 14, 'And goblets set at hand'),
  ('en.pickthall', 88, 15, 'And cushions ranged'),
  ('en.pickthall', 88, 16, 'And silken carpets spread.'),
  ('en.pickthall', 88, 17, 'Will they not regard the camels, how they are created?'),
  ('en.pickthall', 88, 18, 'And the heaven, how it is raised?'),
  ('en.pickthall', 88, 19, 'And the hills, how they are set up?'),
  ('en.pickthall', 88, 20, 'And the earth, how it is spread?'),
  ('en.pickthall', 88, 21, 'Remind them, for thou art but a remembrancer,'),
  ('en.pickthall', 88, 22, 'Thou art not at all a warder over them.'),
  ('en.pickthall', 88, 23, 'But whoso is averse and disbelieveth,'),
  ('en.pickthall', 88, 24, 'Allah will punish him with direst punishment.'),
  ('en.pickthall', 88, 25, 'Lo! unto Us is their return'),
  ('en.pickthall', 88, 26, 'And Ours their reckoning.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 88, 1, 'Has the story reached thee of the overwhelming (Event)?'),
  ('en.yusufali', 88, 2, 'Some faces, that Day, will be humiliated,'),
  ('en.yusufali', 88, 3, 'Labouring (hard), weary,-'),
  ('en.yusufali', 88, 4, 'The while they enter the Blazing Fire,-'),
  ('en.yusufali', 88, 5, 'The while they are given, to drink, of a boiling hot spring,'),
  ('en.yusufali', 88, 6, 'No food will there be for them but a bitter Dhari\''),
  ('en.yusufali', 88, 7, 'Which will neither nourish nor satisfy hunger.'),
  ('en.yusufali', 88, 8, '(Other) faces that Day will be joyful,'),
  ('en.yusufali', 88, 9, 'Pleased with their striving,-'),
  ('en.yusufali', 88, 10, 'In a Garden on high,'),
  ('en.yusufali', 88, 11, 'Where they shall hear no (word) of vanity:'),
  ('en.yusufali', 88, 12, 'Therein will be a bubbling spring:'),
  ('en.yusufali', 88, 13, 'Therein will be Thrones (of dignity), raised on high,'),
  ('en.yusufali', 88, 14, 'Goblets placed (ready),'),
  ('en.yusufali', 88, 15, 'And cushions set in rows,'),
  ('en.yusufali', 88, 16, 'And rich carpets (all) spread out.'),
  ('en.yusufali', 88, 17, 'Do they not look at the Camels, how they are made?-'),
  ('en.yusufali', 88, 18, 'And at the Sky, how it is raised high?-'),
  ('en.yusufali', 88, 19, 'And at the Mountains, how they are fixed firm?-'),
  ('en.yusufali', 88, 20, 'And at the Earth, how it is spread out?'),
  ('en.yusufali', 88, 21, 'Therefore do thou give admonition, for thou art one to admonish.'),
  ('en.yusufali', 88, 22, 'Thou art not one to manage (men\'s) affairs.'),
  ('en.yusufali', 88, 23, 'But if any turn away and reject Allah,-'),
  ('en.yusufali', 88, 24, 'Allah will punish him with a mighty Punishment,'),
  ('en.yusufali', 88, 25, 'For to Us will be their return;'),
  ('en.yusufali', 88, 26, 'Then it will be for Us to call them to account.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 88, 1, 'Hal ataaka hadeesul ghaashiyah'),
  ('en.transliteration', 88, 2, 'Wujoohuny yawma \'izin khaashi\'ah'),
  ('en.transliteration', 88, 3, '\'Aamilatun naasibah'),
  ('en.transliteration', 88, 4, 'Taslaa naaran haamiyah'),
  ('en.transliteration', 88, 5, 'Tusqaa min \'aynin aaniyah'),
  ('en.transliteration', 88, 6, 'Laisa lahum ta\'aamun illaa min daree\''),
  ('en.transliteration', 88, 7, 'Laa yusminu wa laa yughnee min joo\''),
  ('en.transliteration', 88, 8, 'Wujoohuny yawma \'izin naa\'imah'),
  ('en.transliteration', 88, 9, 'Lisa\'yihaa raadiyah'),
  ('en.transliteration', 88, 10, 'Fee jannatin \'aaliyah'),
  ('en.transliteration', 88, 11, 'Laa tasma\'u feehaa laaghiyah'),
  ('en.transliteration', 88, 12, 'Feehaa \'aynun jaariyah'),
  ('en.transliteration', 88, 13, 'Feehaa sururum marfoo\'ah'),
  ('en.transliteration', 88, 14, 'Wa akwaabum mawdoo \'ah'),
  ('en.transliteration', 88, 15, 'Wa namaariqu masfoofah'),
  ('en.transliteration', 88, 16, 'Wa zaraabiyyu mabsoosah'),
  ('en.transliteration', 88, 17, 'Afalaa yanzuroona ilalibili kaifa khuliqat'),
  ('en.transliteration', 88, 18, 'Wa ilas samaaa\'i kaifa rufi\'at'),
  ('en.transliteration', 88, 19, 'Wa ilal jibaali kaifa nusibat'),
  ('en.transliteration', 88, 20, 'Wa ilal ardi kaifa sutihat'),
  ('en.transliteration', 88, 21, 'Fazakkir innama anta Muzakkir'),
  ('en.transliteration', 88, 22, 'Lasta \'alaihim bimusaitir'),
  ('en.transliteration', 88, 23, 'Illaa man tawallaa wa kafar'),
  ('en.transliteration', 88, 24, 'Fa yu\'azzibuhul laahul \'azaabal akbar'),
  ('en.transliteration', 88, 25, 'Innaa ilainaaa iyaabahum'),
  ('en.transliteration', 88, 26, 'Summa inna \'alainaa hisaabahum')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 88, 1, 'کیا آپ کے پاس سب پرچھا جانے والی (قیامت) کا حال پہنچا'),
  ('ur.ahmedali', 88, 2, 'کئی چہرو ں پر اس دن ذلت برس رہی ہوگی'),
  ('ur.ahmedali', 88, 3, 'محنت کرنے والے تھکنے والے'),
  ('ur.ahmedali', 88, 4, 'دھکتی ہوئی آگ میں کریں گے'),
  ('ur.ahmedali', 88, 5, 'انہیں ابلتے ہوئے چشمے سے پلایا جائے گا'),
  ('ur.ahmedali', 88, 6, 'ان کے لیے کوئی کھانا سوائے کانٹے دار جھاڑی کے نہ ہوگا'),
  ('ur.ahmedali', 88, 7, 'جو نہ فربہ کرتی ہے اور نہ بھوک کود ور کرتی ہے'),
  ('ur.ahmedali', 88, 8, 'کئی منہ اس دن ہشاش بشاش ہوں گے'),
  ('ur.ahmedali', 88, 9, 'اپنی کوشش سے خوش ہوں گے'),
  ('ur.ahmedali', 88, 10, 'اونچے باغ میں ہوں گے'),
  ('ur.ahmedali', 88, 11, 'وہاں کوئی لغو بات نہیں سنیں گے'),
  ('ur.ahmedali', 88, 12, 'وہاں ایک چشمہ جاری ہوگا'),
  ('ur.ahmedali', 88, 13, 'وہاں اونچے اونچے تخت ہوں گے'),
  ('ur.ahmedali', 88, 14, 'اور آبخورے سامنے چنے ہوئے'),
  ('ur.ahmedali', 88, 15, 'اورگاؤ تکیے قطار سے لگے ہوئے'),
  ('ur.ahmedali', 88, 16, 'اور مخملی فرش بچھے ہوئے'),
  ('ur.ahmedali', 88, 17, 'پھر کیا وہ اونٹوں کی طرف نہیں دیکھتے کہ کیسے بنائے گئے ہیں'),
  ('ur.ahmedali', 88, 18, 'اور آسمان کی طرف کہ کیسے بلند کیے گئے ہیں'),
  ('ur.ahmedali', 88, 19, 'اور پہاڑوں کی طرف کہ کیسے کھڑے کیے گئے ہیں'),
  ('ur.ahmedali', 88, 20, 'اور زمین کی طرف کہ کیسے بچھائی گئی ہے'),
  ('ur.ahmedali', 88, 21, 'پس آپ نصیحت کیجئے بے شک آپ تو نصیحت کرنے والے ہیں'),
  ('ur.ahmedali', 88, 22, 'آپ ان پر کوئی داروغہ نہیں ہیں'),
  ('ur.ahmedali', 88, 23, 'مگر جس نے منہ موڑا اورانکار کیا'),
  ('ur.ahmedali', 88, 24, 'سو اسے الله بہت بڑا عذاب دے گا'),
  ('ur.ahmedali', 88, 25, 'بےشک ہماری طرف ہی ان کو لوٹ کر آنا ہے'),
  ('ur.ahmedali', 88, 26, 'پھر ہمارےہی ذمہ ان کا حساب لینا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 88, 1, 'Her şeyi kaplayacak kıyametin haberi sana gelmedi mi?'),
  ('tr.diyanet', 88, 2, 'O gün bir takım yüzler zillete bürünmüştür.'),
  ('tr.diyanet', 88, 3, 'Zor işler altında bitkin düşmüştür.'),
  ('tr.diyanet', 88, 4, 'Yakıcı ateşe yaslanırlar.'),
  ('tr.diyanet', 88, 5, 'Kızgın bir kaynaktan içirilirler.'),
  ('tr.diyanet', 88, 6, 'Semirtmeyen, açlığı gidermeyen kötü kokulu (kuru) bir dikenden başka yiyecekleri yoktur.'),
  ('tr.diyanet', 88, 7, 'Semirtmeyen, açlığı gidermeyen kötü kokulu (kuru) bir dikenden başka yiyecekleri yoktur.'),
  ('tr.diyanet', 88, 8, 'İnanmış olanların yüzleri, o gün, pırıl pırıldır.'),
  ('tr.diyanet', 88, 9, 'Yaptıklarından hoşnuddurlar.'),
  ('tr.diyanet', 88, 10, 'Yüksek bir cennettedirler.'),
  ('tr.diyanet', 88, 11, 'Orada boş söz işitmezler.'),
  ('tr.diyanet', 88, 12, 'Orada akan kaynak vardır.'),
  ('tr.diyanet', 88, 13, 'Orada, yükseltilmiş tahtlar vardır.'),
  ('tr.diyanet', 88, 14, 'Yerleştirilmiş kaseler,'),
  ('tr.diyanet', 88, 15, 'Sıra sıra yastıklar,'),
  ('tr.diyanet', 88, 16, 'Serilmiş, yumuşak tüylü halılar vardır.'),
  ('tr.diyanet', 88, 17, 'Bu insanlar, devenin nasıl yaratıldığına, göğün nasıl yükseltildiğine, dağların nasıl dikildiğine, yerin nasıl yayıldığına bir bakmazlar mı?'),
  ('tr.diyanet', 88, 18, 'Bu insanlar, devenin nasıl yaratıldığına, göğün nasıl yükseltildiğine, dağların nasıl dikildiğine, yerin nasıl yayıldığına bir bakmazlar mı?'),
  ('tr.diyanet', 88, 19, 'Bu insanlar, devenin nasıl yaratıldığına, göğün nasıl yükseltildiğine, dağların nasıl dikildiğine, yerin nasıl yayıldığına bir bakmazlar mı?'),
  ('tr.diyanet', 88, 20, 'Bu insanlar, devenin nasıl yaratıldığına, göğün nasıl yükseltildiğine, dağların nasıl dikildiğine, yerin nasıl yayıldığına bir bakmazlar mı?'),
  ('tr.diyanet', 88, 21, 'Sen öğüt ver! Esasen sen sadece bir öğütçüsün.'),
  ('tr.diyanet', 88, 22, 'Sen, onlara zor kullanacak değilsin.'),
  ('tr.diyanet', 88, 23, 'Ama kim yüz çevirir, inkar ederse, Allah onu en büyük azaba uğratır.'),
  ('tr.diyanet', 88, 24, 'Ama kim yüz çevirir, inkar ederse, Allah onu en büyük azaba uğratır.'),
  ('tr.diyanet', 88, 25, 'Doğrusu onların dönüşü Bize\'dir.'),
  ('tr.diyanet', 88, 26, 'Şüphesiz sonra hesaplarını görmek de Bize düşmektedir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 88, 1, 'Sudah datangkah kepadamu berita (tentang) hari pembalasan?'),
  ('id.indonesian', 88, 2, 'Banyak muka pada hari itu tunduk terhina,'),
  ('id.indonesian', 88, 3, 'bekerja keras lagi kepayahan,'),
  ('id.indonesian', 88, 4, 'memasuki api yang sangat panas (neraka),'),
  ('id.indonesian', 88, 5, 'diberi minum (dengan air) dari sumber yang sangat panas.'),
  ('id.indonesian', 88, 6, 'Mereka tiada memperoleh makanan selain dari pohon yang berduri,'),
  ('id.indonesian', 88, 7, 'yang tidak menggemukkan dan tidak pula menghilangkan lapar.'),
  ('id.indonesian', 88, 8, 'Banyak muka pada hari itu berseri-seri,'),
  ('id.indonesian', 88, 9, 'merasa senang karena usahanya,'),
  ('id.indonesian', 88, 10, 'dalam surga yang tinggi,'),
  ('id.indonesian', 88, 11, 'tidak kamu dengar di dalamnya perkataan yang tidak berguna.'),
  ('id.indonesian', 88, 12, 'Di dalamnya ada mata air yang mengalir.'),
  ('id.indonesian', 88, 13, 'Di dalamnya ada takhta-takhta yang ditinggikan,'),
  ('id.indonesian', 88, 14, 'dan gelas-gelas yang terletak (di dekatnya),'),
  ('id.indonesian', 88, 15, 'dan bantal-bantal sandaran yang tersusun,'),
  ('id.indonesian', 88, 16, 'dan permadani-permadani yang terhampar.'),
  ('id.indonesian', 88, 17, 'Maka apakah mereka tidak memperhatikan unta bagaimana dia diciptakan,'),
  ('id.indonesian', 88, 18, 'Dan langit, bagaimana ia ditinggikan?'),
  ('id.indonesian', 88, 19, 'Dan gunung-gunung bagaimana ia ditegakkan?'),
  ('id.indonesian', 88, 20, 'Dan bumi bagaimana ia dihamparkan?'),
  ('id.indonesian', 88, 21, 'Maka berilah peringatan, karena sesungguhnya kamu hanyalah orang yang memberi peringatan.'),
  ('id.indonesian', 88, 22, 'Kamu bukanlah orang yang berkuasa atas mereka,'),
  ('id.indonesian', 88, 23, 'tetapi orang yang berpaling dan kafir,'),
  ('id.indonesian', 88, 24, 'maka Allah akan mengazabnya dengan azab yang besar.'),
  ('id.indonesian', 88, 25, 'Sesungguhnya kepada Kami-lah kembali mereka,'),
  ('id.indonesian', 88, 26, 'kemudian sesungguhnya kewajiban Kami-lah menghisab mereka.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (81, 1, 5801, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا ٱلشَّمْسُ كُوِّرَتْ', 586, 30, 234, 0),
  (81, 2, 5802, 'وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ', 586, 30, 234, 0),
  (81, 3, 5803, 'وَإِذَا ٱلْجِبَالُ سُيِّرَتْ', 586, 30, 234, 0),
  (81, 4, 5804, 'وَإِذَا ٱلْعِشَارُ عُطِّلَتْ', 586, 30, 234, 0),
  (81, 5, 5805, 'وَإِذَا ٱلْوُحُوشُ حُشِرَتْ', 586, 30, 234, 0),
  (81, 6, 5806, 'وَإِذَا ٱلْبِحَارُ سُجِّرَتْ', 586, 30, 234, 0),
  (81, 7, 5807, 'وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ', 586, 30, 234, 0),
  (81, 8, 5808, 'وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ', 586, 30, 234, 0),
  (81, 9, 5809, 'بِأَىِّ ذَنۢبٍۢ قُتِلَتْ', 586, 30, 234, 0),
  (81, 10, 5810, 'وَإِذَا ٱلصُّحُفُ نُشِرَتْ', 586, 30, 234, 0),
  (81, 11, 5811, 'وَإِذَا ٱلسَّمَآءُ كُشِطَتْ', 586, 30, 234, 0),
  (81, 12, 5812, 'وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ', 586, 30, 234, 0),
  (81, 13, 5813, 'وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ', 586, 30, 234, 0),
  (81, 14, 5814, 'عَلِمَتْ نَفْسٌۭ مَّآ أَحْضَرَتْ', 586, 30, 234, 0),
  (81, 15, 5815, 'فَلَآ أُقْسِمُ بِٱلْخُنَّسِ', 586, 30, 234, 0),
  (81, 16, 5816, 'ٱلْجَوَارِ ٱلْكُنَّسِ', 586, 30, 234, 0),
  (81, 17, 5817, 'وَٱلَّيْلِ إِذَا عَسْعَسَ', 586, 30, 234, 0),
  (81, 18, 5818, 'وَٱلصُّبْحِ إِذَا تَنَفَّسَ', 586, 30, 234, 0),
  (81, 19, 5819, 'إِنَّهُۥ لَقَوْلُ رَسُولٍۢ كَرِيمٍۢ', 586, 30, 234, 0),
  (81, 20, 5820, 'ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍۢ', 586, 30, 234, 0),
  (81, 21, 5821, 'مُّطَاعٍۢ ثَمَّ أَمِينٍۢ', 586, 30, 234, 0),
  (81, 22, 5822, 'وَمَا صَاحِبُكُم بِمَجْنُونٍۢ', 586, 30, 234, 0),
  (81, 23, 5823, 'وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ', 586, 30, 234, 0),
  (81, 24, 5824, 'وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍۢ', 586, 30, 234, 0),
  (81, 25, 5825, 'وَمَا هُوَ بِقَوْلِ شَيْطَٰنٍۢ رَّجِيمٍۢ', 586, 30, 234, 0),
  (81, 26, 5826, 'فَأَيْنَ تَذْهَبُونَ', 586, 30, 234, 0),
  (81, 27, 5827, 'إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ', 586, 30, 234, 0),
  (81, 28, 5828, 'لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ', 586, 30, 234, 0),
  (81, 29, 5829, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ', 586, 30, 234, 0),
  (82, 1, 5830, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ', 587, 30, 235, 0),
  (82, 2, 5831, 'وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ', 587, 30, 235, 0),
  (82, 3, 5832, 'وَإِذَا ٱلْبِحَارُ فُجِّرَتْ', 587, 30, 235, 0),
  (82, 4, 5833, 'وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ', 587, 30, 235, 0),
  (82, 5, 5834, 'عَلِمَتْ نَفْسٌۭ مَّا قَدَّمَتْ وَأَخَّرَتْ', 587, 30, 235, 0),
  (82, 6, 5835, 'يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ', 587, 30, 235, 0),
  (82, 7, 5836, 'ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ', 587, 30, 235, 0),
  (82, 8, 5837, 'فِىٓ أَىِّ صُورَةٍۢ مَّا شَآءَ رَكَّبَكَ', 587, 30, 235, 0),
  (82, 9, 5838, 'كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ', 587, 30, 235, 0),
  (82, 10, 5839, 'وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ', 587, 30, 235, 0),
  (82, 11, 5840, 'كِرَامًۭا كَٰتِبِينَ', 587, 30, 235, 0),
  (82, 12, 5841, 'يَعْلَمُونَ مَا تَفْعَلُونَ', 587, 30, 235, 0),
  (82, 13, 5842, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍۢ', 587, 30, 235, 0),
  (82, 14, 5843, 'وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍۢ', 587, 30, 235, 0),
  (82, 15, 5844, 'يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ', 587, 30, 235, 0),
  (82, 16, 5845, 'وَمَا هُمْ عَنْهَا بِغَآئِبِينَ', 587, 30, 235, 0),
  (82, 17, 5846, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 587, 30, 235, 0),
  (82, 18, 5847, 'ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ', 587, 30, 235, 0),
  (82, 19, 5848, 'يَوْمَ لَا تَمْلِكُ نَفْسٌۭ لِّنَفْسٍۢ شَيْـًۭٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍۢ لِّلَّهِ', 587, 30, 235, 0),
  (83, 1, 5849, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَيْلٌۭ لِّلْمُطَفِّفِينَ', 587, 30, 235, 0),
  (83, 2, 5850, 'ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ', 587, 30, 235, 0),
  (83, 3, 5851, 'وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ', 587, 30, 235, 0),
  (83, 4, 5852, 'أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ', 587, 30, 235, 0),
  (83, 5, 5853, 'لِيَوْمٍ عَظِيمٍۢ', 587, 30, 235, 0),
  (83, 6, 5854, 'يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ', 587, 30, 235, 0),
  (83, 7, 5855, 'كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍۢ', 588, 30, 235, 0),
  (83, 8, 5856, 'وَمَآ أَدْرَىٰكَ مَا سِجِّينٌۭ', 588, 30, 235, 0),
  (83, 9, 5857, 'كِتَٰبٌۭ مَّرْقُومٌۭ', 588, 30, 235, 0),
  (83, 10, 5858, 'وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ', 588, 30, 235, 0),
  (83, 11, 5859, 'ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ', 588, 30, 235, 0),
  (83, 12, 5860, 'وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ', 588, 30, 235, 0),
  (83, 13, 5861, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ', 588, 30, 235, 0),
  (83, 14, 5862, 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ', 588, 30, 235, 0),
  (83, 15, 5863, 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ', 588, 30, 235, 0),
  (83, 16, 5864, 'ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ', 588, 30, 235, 0),
  (83, 17, 5865, 'ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 588, 30, 235, 0),
  (83, 18, 5866, 'كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', 588, 30, 235, 0),
  (83, 19, 5867, 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', 588, 30, 235, 0),
  (83, 20, 5868, 'كِتَٰبٌۭ مَّرْقُومٌۭ', 588, 30, 235, 0),
  (83, 21, 5869, 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', 588, 30, 235, 0),
  (83, 22, 5870, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 588, 30, 235, 0),
  (83, 23, 5871, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 588, 30, 235, 0),
  (83, 24, 5872, 'تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ', 588, 30, 235, 0),
  (83, 25, 5873, 'يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ', 588, 30, 235, 0),
  (83, 26, 5874, 'خِتَٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ', 588, 30, 235, 0),
  (83, 27, 5875, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 588, 30, 235, 0),
  (83, 28, 5876, 'عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', 588, 30, 235, 0),
  (83, 29, 5877, 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', 588, 30, 235, 0),
  (83, 30, 5878, 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', 588, 30, 235, 0),
  (83, 31, 5879, 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', 588, 30, 235, 0),
  (83, 32, 5880, 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ', 588, 30, 235, 0),
  (83, 33, 5881, 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ', 588, 30, 235, 0),
  (83, 34, 5882, 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', 588, 30, 235, 0),
  (83, 35, 5883, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 589, 30, 235, 0),
  (83, 36, 5884, 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', 589, 30, 235, 0),
  (84, 1, 5885, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', 589, 30, 236, 0),
  (84, 2, 5886, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 589, 30, 236, 0),
  (84, 3, 5887, 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', 589, 30, 236, 0),
  (84, 4, 5888, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 589, 30, 236, 0),
  (84, 5, 5889, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 589, 30, 236, 0),
  (84, 6, 5890, 'يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَٰقِيهِ', 589, 30, 236, 0),
  (84, 7, 5891, 'فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ', 589, 30, 236, 0),
  (84, 8, 5892, 'فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا', 589, 30, 236, 0),
  (84, 9, 5893, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا', 589, 30, 236, 0),
  (84, 10, 5894, 'وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 589, 30, 236, 0),
  (84, 11, 5895, 'فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا', 589, 30, 236, 0),
  (84, 12, 5896, 'وَيَصْلَىٰ سَعِيرًا', 589, 30, 236, 0),
  (84, 13, 5897, 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', 589, 30, 236, 0),
  (84, 14, 5898, 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', 589, 30, 236, 0),
  (84, 15, 5899, 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا', 589, 30, 236, 0),
  (84, 16, 5900, 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', 589, 30, 236, 0),
  (84, 17, 5901, 'وَٱلَّيْلِ وَمَا وَسَقَ', 589, 30, 236, 0),
  (84, 18, 5902, 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', 589, 30, 236, 0),
  (84, 19, 5903, 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ', 589, 30, 236, 0),
  (84, 20, 5904, 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 589, 30, 236, 0),
  (84, 21, 5905, 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩', 589, 30, 236, 1),
  (84, 22, 5906, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', 589, 30, 236, 0),
  (84, 23, 5907, 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', 589, 30, 236, 0),
  (84, 24, 5908, 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 589, 30, 236, 0),
  (84, 25, 5909, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', 589, 30, 236, 0),
  (85, 1, 5910, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ', 590, 30, 236, 0),
  (85, 2, 5911, 'وَٱلْيَوْمِ ٱلْمَوْعُودِ', 590, 30, 236, 0),
  (85, 3, 5912, 'وَشَاهِدٍۢ وَمَشْهُودٍۢ', 590, 30, 236, 0),
  (85, 4, 5913, 'قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ', 590, 30, 236, 0),
  (85, 5, 5914, 'ٱلنَّارِ ذَاتِ ٱلْوَقُودِ', 590, 30, 236, 0),
  (85, 6, 5915, 'إِذْ هُمْ عَلَيْهَا قُعُودٌۭ', 590, 30, 236, 0),
  (85, 7, 5916, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌۭ', 590, 30, 236, 0),
  (85, 8, 5917, 'وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 590, 30, 236, 0),
  (85, 9, 5918, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 590, 30, 236, 0),
  (85, 10, 5919, 'إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ', 590, 30, 236, 0),
  (85, 11, 5920, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ', 590, 30, 236, 0),
  (85, 12, 5921, 'إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ', 590, 30, 236, 0),
  (85, 13, 5922, 'إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ', 590, 30, 236, 0),
  (85, 14, 5923, 'وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ', 590, 30, 236, 0),
  (85, 15, 5924, 'ذُو ٱلْعَرْشِ ٱلْمَجِيدُ', 590, 30, 236, 0),
  (85, 16, 5925, 'فَعَّالٌۭ لِّمَا يُرِيدُ', 590, 30, 236, 0),
  (85, 17, 5926, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ', 590, 30, 236, 0),
  (85, 18, 5927, 'فِرْعَوْنَ وَثَمُودَ', 590, 30, 236, 0),
  (85, 19, 5928, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍۢ', 590, 30, 236, 0),
  (85, 20, 5929, 'وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ', 590, 30, 236, 0),
  (85, 21, 5930, 'بَلْ هُوَ قُرْءَانٌۭ مَّجِيدٌۭ', 590, 30, 236, 0),
  (85, 22, 5931, 'فِى لَوْحٍۢ مَّحْفُوظٍۭ', 590, 30, 236, 0),
  (86, 1, 5932, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلسَّمَآءِ وَٱلطَّارِقِ', 591, 30, 236, 0),
  (86, 2, 5933, 'وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ', 591, 30, 236, 0),
  (86, 3, 5934, 'ٱلنَّجْمُ ٱلثَّاقِبُ', 591, 30, 236, 0),
  (86, 4, 5935, 'إِن كُلُّ نَفْسٍۢ لَّمَّا عَلَيْهَا حَافِظٌۭ', 591, 30, 236, 0),
  (86, 5, 5936, 'فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ', 591, 30, 236, 0),
  (86, 6, 5937, 'خُلِقَ مِن مَّآءٍۢ دَافِقٍۢ', 591, 30, 236, 0),
  (86, 7, 5938, 'يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ', 591, 30, 236, 0),
  (86, 8, 5939, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌۭ', 591, 30, 236, 0),
  (86, 9, 5940, 'يَوْمَ تُبْلَى ٱلسَّرَآئِرُ', 591, 30, 236, 0),
  (86, 10, 5941, 'فَمَا لَهُۥ مِن قُوَّةٍۢ وَلَا نَاصِرٍۢ', 591, 30, 236, 0),
  (86, 11, 5942, 'وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ', 591, 30, 236, 0),
  (86, 12, 5943, 'وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ', 591, 30, 236, 0),
  (86, 13, 5944, 'إِنَّهُۥ لَقَوْلٌۭ فَصْلٌۭ', 591, 30, 236, 0),
  (86, 14, 5945, 'وَمَا هُوَ بِٱلْهَزْلِ', 591, 30, 236, 0),
  (86, 15, 5946, 'إِنَّهُمْ يَكِيدُونَ كَيْدًۭا', 591, 30, 236, 0),
  (86, 16, 5947, 'وَأَكِيدُ كَيْدًۭا', 591, 30, 236, 0),
  (86, 17, 5948, 'فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا', 591, 30, 236, 0),
  (87, 1, 5949, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى', 591, 30, 237, 0),
  (87, 2, 5950, 'ٱلَّذِى خَلَقَ فَسَوَّىٰ', 591, 30, 237, 0),
  (87, 3, 5951, 'وَٱلَّذِى قَدَّرَ فَهَدَىٰ', 591, 30, 237, 0),
  (87, 4, 5952, 'وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ', 591, 30, 237, 0),
  (87, 5, 5953, 'فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ', 591, 30, 237, 0),
  (87, 6, 5954, 'سَنُقْرِئُكَ فَلَا تَنسَىٰٓ', 591, 30, 237, 0),
  (87, 7, 5955, 'إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ', 591, 30, 237, 0),
  (87, 8, 5956, 'وَنُيَسِّرُكَ لِلْيُسْرَىٰ', 591, 30, 237, 0),
  (87, 9, 5957, 'فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ', 591, 30, 237, 0),
  (87, 10, 5958, 'سَيَذَّكَّرُ مَن يَخْشَىٰ', 591, 30, 237, 0),
  (87, 11, 5959, 'وَيَتَجَنَّبُهَا ٱلْأَشْقَى', 591, 30, 237, 0),
  (87, 12, 5960, 'ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ', 591, 30, 237, 0),
  (87, 13, 5961, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 591, 30, 237, 0),
  (87, 14, 5962, 'قَدْ أَفْلَحَ مَن تَزَكَّىٰ', 591, 30, 237, 0),
  (87, 15, 5963, 'وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ', 591, 30, 237, 0),
  (87, 16, 5964, 'بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 592, 30, 237, 0),
  (87, 17, 5965, 'وَٱلْءَاخِرَةُ خَيْرٌۭ وَأَبْقَىٰٓ', 592, 30, 237, 0),
  (87, 18, 5966, 'إِنَّ هَٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ', 592, 30, 237, 0),
  (87, 19, 5967, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ', 592, 30, 237, 0),
  (88, 1, 5968, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَٰشِيَةِ', 592, 30, 237, 0),
  (88, 2, 5969, 'وُجُوهٌۭ يَوْمَئِذٍ خَٰشِعَةٌ', 592, 30, 237, 0),
  (88, 3, 5970, 'عَامِلَةٌۭ نَّاصِبَةٌۭ', 592, 30, 237, 0),
  (88, 4, 5971, 'تَصْلَىٰ نَارًا حَامِيَةًۭ', 592, 30, 237, 0),
  (88, 5, 5972, 'تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍۢ', 592, 30, 237, 0),
  (88, 6, 5973, 'لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍۢ', 592, 30, 237, 0),
  (88, 7, 5974, 'لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍۢ', 592, 30, 237, 0),
  (88, 8, 5975, 'وُجُوهٌۭ يَوْمَئِذٍۢ نَّاعِمَةٌۭ', 592, 30, 237, 0),
  (88, 9, 5976, 'لِّسَعْيِهَا رَاضِيَةٌۭ', 592, 30, 237, 0),
  (88, 10, 5977, 'فِى جَنَّةٍ عَالِيَةٍۢ', 592, 30, 237, 0),
  (88, 11, 5978, 'لَّا تَسْمَعُ فِيهَا لَٰغِيَةًۭ', 592, 30, 237, 0),
  (88, 12, 5979, 'فِيهَا عَيْنٌۭ جَارِيَةٌۭ', 592, 30, 237, 0),
  (88, 13, 5980, 'فِيهَا سُرُرٌۭ مَّرْفُوعَةٌۭ', 592, 30, 237, 0),
  (88, 14, 5981, 'وَأَكْوَابٌۭ مَّوْضُوعَةٌۭ', 592, 30, 237, 0),
  (88, 15, 5982, 'وَنَمَارِقُ مَصْفُوفَةٌۭ', 592, 30, 237, 0),
  (88, 16, 5983, 'وَزَرَابِىُّ مَبْثُوثَةٌ', 592, 30, 237, 0),
  (88, 17, 5984, 'أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ', 592, 30, 237, 0),
  (88, 18, 5985, 'وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ', 592, 30, 237, 0),
  (88, 19, 5986, 'وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ', 592, 30, 237, 0),
  (88, 20, 5987, 'وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ', 592, 30, 237, 0),
  (88, 21, 5988, 'فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌۭ', 592, 30, 237, 0),
  (88, 22, 5989, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', 592, 30, 237, 0),
  (88, 23, 5990, 'إِلَّا مَن تَوَلَّىٰ وَكَفَرَ', 592, 30, 237, 0),
  (88, 24, 5991, 'فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ', 592, 30, 237, 0),
  (88, 25, 5992, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', 592, 30, 237, 0),
  (88, 26, 5993, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم', 592, 30, 237, 0),
  (89, 1, 5994, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلْفَجْرِ', 593, 30, 237, 0),
  (89, 2, 5995, 'وَلَيَالٍ عَشْرٍۢ', 593, 30, 237, 0),
  (89, 3, 5996, 'وَٱلشَّفْعِ وَٱلْوَتْرِ', 593, 30, 237, 0),
  (89, 4, 5997, 'وَٱلَّيْلِ إِذَا يَسْرِ', 593, 30, 237, 0),
  (89, 5, 5998, 'هَلْ فِى ذَٰلِكَ قَسَمٌۭ لِّذِى حِجْرٍ', 593, 30, 237, 0),
  (89, 6, 5999, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 593, 30, 237, 0),
  (89, 7, 6000, 'إِرَمَ ذَاتِ ٱلْعِمَادِ', 593, 30, 237, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 89, 1, 'By the dawn'),
  ('en.sahih', 89, 2, 'And [by] ten nights'),
  ('en.sahih', 89, 3, 'And [by] the even [number] and the odd'),
  ('en.sahih', 89, 4, 'And [by] the night when it passes,'),
  ('en.sahih', 89, 5, 'Is there [not] in [all] that an oath [sufficient] for one of perception?'),
  ('en.sahih', 89, 6, 'Have you not considered how your Lord dealt with \'Aad -'),
  ('en.sahih', 89, 7, '[With] Iram - who had lofty pillars,'),
  ('en.sahih', 89, 8, 'The likes of whom had never been created in the land?'),
  ('en.sahih', 89, 9, 'And [with] Thamud, who carved out the rocks in the valley?'),
  ('en.sahih', 89, 10, 'And [with] Pharaoh, owner of the stakes? -'),
  ('en.sahih', 89, 11, '[All of] whom oppressed within the lands'),
  ('en.sahih', 89, 12, 'And increased therein the corruption.'),
  ('en.sahih', 89, 13, 'So your Lord poured upon them a scourge of punishment.'),
  ('en.sahih', 89, 14, 'Indeed, your Lord is in observation.'),
  ('en.sahih', 89, 15, 'And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, "My Lord has honored me."'),
  ('en.sahih', 89, 16, 'But when He tries him and restricts his provision, he says, "My Lord has humiliated me."'),
  ('en.sahih', 89, 17, 'No! But you do not honor the orphan'),
  ('en.sahih', 89, 18, 'And you do not encourage one another to feed the poor.'),
  ('en.sahih', 89, 19, 'And you consume inheritance, devouring [it] altogether,'),
  ('en.sahih', 89, 20, 'And you love wealth with immense love.'),
  ('en.sahih', 89, 21, 'No! When the earth has been leveled - pounded and crushed -'),
  ('en.sahih', 89, 22, 'And your Lord has come and the angels, rank upon rank,'),
  ('en.sahih', 89, 23, 'And brought [within view], that Day, is Hell - that Day, man will remember, but what good to him will be the remembrance?'),
  ('en.sahih', 89, 24, 'He will say, "Oh, I wish I had sent ahead [some good] for my life."'),
  ('en.sahih', 89, 25, 'So on that Day, none will punish [as severely] as His punishment,'),
  ('en.sahih', 89, 26, 'And none will bind [as severely] as His binding [of the evildoers].'),
  ('en.sahih', 89, 27, '[To the righteous it will be said], "O reassured soul,'),
  ('en.sahih', 89, 28, 'Return to your Lord, well-pleased and pleasing [to Him],'),
  ('en.sahih', 89, 29, 'And enter among My [righteous] servants'),
  ('en.sahih', 89, 30, 'And enter My Paradise."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 89, 1, 'শপথ ফজরের,'),
  ('bn.bengali', 89, 2, 'শপথ দশ রাত্রির, শপথ তার,'),
  ('bn.bengali', 89, 3, 'যা জোড় ও যা বিজোড়'),
  ('bn.bengali', 89, 4, 'এবং শপথ রাত্রির যখন তা গত হতে থাকে'),
  ('bn.bengali', 89, 5, 'এর মধ্যে আছে শপথ জ্ঞানী ব্যক্তির জন্যে।'),
  ('bn.bengali', 89, 6, 'আপনি কি লক্ষ্য করেননি, আপনার পালনকর্তা আদ বংশের ইরাম গোত্রের সাথে কি আচরণ করেছিলেন,'),
  ('bn.bengali', 89, 7, 'যাদের দৈহিক গঠন স্তম্ভ ও খুঁটির ন্যায় দীর্ঘ ছিল এবং'),
  ('bn.bengali', 89, 8, 'যাদের সমান শক্তি ও বলবীর্যে সারা বিশ্বের শহরসমূহে কোন লোক সৃজিত হয়নি'),
  ('bn.bengali', 89, 9, 'এবং সামুদ গোত্রের সাথে, যারা উপত্যকায় পাথর কেটে গৃহ নির্মাণ করেছিল।'),
  ('bn.bengali', 89, 10, 'এবং বহু কীলকের অধিপতি ফেরাউনের সাথে'),
  ('bn.bengali', 89, 11, 'যারা দেশে সীমালঙ্ঘন করেছিল।'),
  ('bn.bengali', 89, 12, 'অতঃপর সেখানে বিস্তর অশান্তি সৃষ্টি করেছিল।'),
  ('bn.bengali', 89, 13, 'অতঃপর আপনার পালনকর্তা তাদেরকে শাস্তির কশাঘাত করলেন।'),
  ('bn.bengali', 89, 14, 'নিশ্চয় আপনার পালকর্তা সতর্ক দৃষ্টি রাখেন।'),
  ('bn.bengali', 89, 15, 'মানুষ এরূপ যে, যখন তার পালনকর্তা তাকে পরীক্ষা করেন, অতঃপর সম্মান ও অনুগ্রহ দান করেন, তখন বলে, আমার পালনকর্তা আমাকে সম্মান দান করেছেন।'),
  ('bn.bengali', 89, 16, 'এবং যখন তাকে পরীক্ষা করেন, অতঃপর রিযিক সংকুচিত করে দেন, তখন বলেঃ আমার পালনকর্তা আমাকে হেয় করেছেন।'),
  ('bn.bengali', 89, 17, 'এটা অমূলক, বরং তোমরা এতীমকে সম্মান কর না।'),
  ('bn.bengali', 89, 18, 'এবং মিসকীনকে অন্নদানে পরস্পরকে উৎসাহিত কর না।'),
  ('bn.bengali', 89, 19, 'এবং তোমরা মৃতের ত্যাজ্য সম্পত্তি সম্পূর্ণরূপে কুক্ষিগত করে ফেল'),
  ('bn.bengali', 89, 20, 'এবং তোমরা ধন-সম্পদকে প্রাণভরে ভালবাস।'),
  ('bn.bengali', 89, 21, 'এটা অনুচিত। যখন পৃথিবী চুর্ণ-বিচুর্ণ হবে'),
  ('bn.bengali', 89, 22, 'এবং আপনার পালনকর্তা ও ফেরেশতাগণ সারিবদ্ধভাবে উপস্থিত হবেন,'),
  ('bn.bengali', 89, 23, 'এবং সেদিন জাহান্নামকে আনা হবে, সেদিন মানুষ স্মরণ করবে, কিন্তু এই স্মরণ তার কি কাজে আসবে?'),
  ('bn.bengali', 89, 24, 'সে বলবেঃ হায়, এ জীবনের জন্যে আমি যদি কিছু অগ্রে প্রেরণ করতাম!'),
  ('bn.bengali', 89, 25, 'সেদিন তার শাস্তির মত শাস্তি কেউ দিবে না।'),
  ('bn.bengali', 89, 26, 'এবং তার বন্ধনের মত বন্ধন কেউ দিবে না।'),
  ('bn.bengali', 89, 27, 'হে প্রশান্ত মন,'),
  ('bn.bengali', 89, 28, 'তুমি তোমার পালনকর্তার নিকট ফিরে যাও সন্তুষ্ট ও সন্তোষভাজন হয়ে।'),
  ('bn.bengali', 89, 29, 'অতঃপর আমার বান্দাদের অন্তর্ভুক্ত হয়ে যাও।'),
  ('bn.bengali', 89, 30, 'এবং আমার জান্নাতে প্রবেশ কর।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 89, 1, 'By the Dawn'),
  ('en.pickthall', 89, 2, 'And ten nights,'),
  ('en.pickthall', 89, 3, 'And the Even and the Odd,'),
  ('en.pickthall', 89, 4, 'And the night when it departeth,'),
  ('en.pickthall', 89, 5, 'There surely is an oath for thinking man.'),
  ('en.pickthall', 89, 6, 'Dost thou not consider how thy Lord dealt with (the tribe of) A\'ad,'),
  ('en.pickthall', 89, 7, 'With many-columned Iram,'),
  ('en.pickthall', 89, 8, 'The like of which was not created in the lands;'),
  ('en.pickthall', 89, 9, 'And with (the tribe of) Thamud, who clove the rocks in the valley;'),
  ('en.pickthall', 89, 10, 'And with Pharaoh, firm of might,'),
  ('en.pickthall', 89, 11, 'Who (all) were rebellious (to Allah) in these lands,'),
  ('en.pickthall', 89, 12, 'And multiplied iniquity therein?'),
  ('en.pickthall', 89, 13, 'Therefore thy Lord poured on them the disaster of His punishment.'),
  ('en.pickthall', 89, 14, 'Lo! thy Lord is ever watchful.'),
  ('en.pickthall', 89, 15, 'As for man, whenever his Lord trieth him by honouring him, and is gracious unto him, he saith: My Lord honoureth me.'),
  ('en.pickthall', 89, 16, 'But whenever He trieth him by straitening his means of life, he saith: My Lord despiseth me.'),
  ('en.pickthall', 89, 17, 'Nay, but ye (for your part) honour not the orphan'),
  ('en.pickthall', 89, 18, 'And urge not on the feeding of the poor.'),
  ('en.pickthall', 89, 19, 'And ye devour heritages with devouring greed.'),
  ('en.pickthall', 89, 20, 'And love wealth with abounding love.'),
  ('en.pickthall', 89, 21, 'Nay, but when the earth is ground to atoms, grinding, grinding,'),
  ('en.pickthall', 89, 22, 'And thy Lord shall come with angels, rank on rank,'),
  ('en.pickthall', 89, 23, 'And hell is brought near that day; on that day man will remember, but how will the remembrance (then avail him)?'),
  ('en.pickthall', 89, 24, 'He will say: Ah, would that I had sent before me (some provision) for my life!'),
  ('en.pickthall', 89, 25, 'None punisheth as He will punish on that day!'),
  ('en.pickthall', 89, 26, 'None bindeth as He then will bind.'),
  ('en.pickthall', 89, 27, 'But ah! thou soul at peace!'),
  ('en.pickthall', 89, 28, 'Return unto thy Lord, content in His good pleasure!'),
  ('en.pickthall', 89, 29, 'Enter thou among My bondmen!'),
  ('en.pickthall', 89, 30, 'Enter thou My Garden!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 89, 1, 'By the break of Day'),
  ('en.yusufali', 89, 2, 'By the Nights twice five;'),
  ('en.yusufali', 89, 3, 'By the even and odd (contrasted);'),
  ('en.yusufali', 89, 4, 'And by the Night when it passeth away;-'),
  ('en.yusufali', 89, 5, 'Is there (not) in these an adjuration (or evidence) for those who understand?'),
  ('en.yusufali', 89, 6, 'Seest thou not how thy Lord dealt with the \'Ad (people),-'),
  ('en.yusufali', 89, 7, 'Of the (city of) Iram, with lofty pillars,'),
  ('en.yusufali', 89, 8, 'The like of which were not produced in (all) the land?'),
  ('en.yusufali', 89, 9, 'And with the Thamud (people), who cut out (huge) rocks in the valley?-'),
  ('en.yusufali', 89, 10, 'And with Pharaoh, lord of stakes?'),
  ('en.yusufali', 89, 11, '(All) these transgressed beyond bounds in the lands,'),
  ('en.yusufali', 89, 12, 'And heaped therein mischief (on mischief).'),
  ('en.yusufali', 89, 13, 'Therefore did thy Lord pour on them a scourge of diverse chastisements:'),
  ('en.yusufali', 89, 14, 'For thy Lord is (as a Guardian) on a watch-tower.'),
  ('en.yusufali', 89, 15, 'Now, as for man, when his Lord trieth him, giving him honour and gifts, then saith he, (puffed up), "My Lord hath honoured me."'),
  ('en.yusufali', 89, 16, 'But when He trieth him, restricting his subsistence for him, then saith he (in despair), "My Lord hath humiliated me!"'),
  ('en.yusufali', 89, 17, 'Nay, nay! but ye honour not the orphans!'),
  ('en.yusufali', 89, 18, 'Nor do ye encourage one another to feed the poor!-'),
  ('en.yusufali', 89, 19, 'And ye devour inheritance - all with greed,'),
  ('en.yusufali', 89, 20, 'And ye love wealth with inordinate love!'),
  ('en.yusufali', 89, 21, 'Nay! When the earth is pounded to powder,'),
  ('en.yusufali', 89, 22, 'And thy Lord cometh, and His angels, rank upon rank,'),
  ('en.yusufali', 89, 23, 'And Hell, that Day, is brought (face to face),- on that Day will man remember, but how will that remembrance profit him?'),
  ('en.yusufali', 89, 24, 'He will say: "Ah! Would that I had sent forth (good deeds) for (this) my (Future) Life!"'),
  ('en.yusufali', 89, 25, 'For, that Day, His Chastisement will be such as none (else) can inflict,'),
  ('en.yusufali', 89, 26, 'And His bonds will be such as none (other) can bind.'),
  ('en.yusufali', 89, 27, '(To the righteous soul will be said:) "O (thou) soul, in (complete) rest and satisfaction!'),
  ('en.yusufali', 89, 28, '"Come back thou to thy Lord,- well pleased (thyself), and well-pleasing unto Him!'),
  ('en.yusufali', 89, 29, '"Enter thou, then, among My devotees!'),
  ('en.yusufali', 89, 30, '"Yea, enter thou My Heaven!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 89, 1, 'Wal-Fajr'),
  ('en.transliteration', 89, 2, 'Wa layaalin \'ashr'),
  ('en.transliteration', 89, 3, 'Wash shaf\'i wal watr'),
  ('en.transliteration', 89, 4, 'Wallaili izaa yasr'),
  ('en.transliteration', 89, 5, 'Hal fee zaalika qasamul lizee hijr'),
  ('en.transliteration', 89, 6, 'Alam tara kaifa fa\'ala rabbuka bi\'aad'),
  ('en.transliteration', 89, 7, 'Iramaa zaatil \'imaad'),
  ('en.transliteration', 89, 8, 'Allatee lam yukhlaq misluhaa fil bilaad'),
  ('en.transliteration', 89, 9, 'Wa samoodal lazeena jaabus sakhra bil waad'),
  ('en.transliteration', 89, 10, 'Wa fir\'awna zil awtaad'),
  ('en.transliteration', 89, 11, 'Allazeena taghaw fil bilaad'),
  ('en.transliteration', 89, 12, 'Fa aksaroo feehal fasaad'),
  ('en.transliteration', 89, 13, 'Fasabba \'alaihim Rabbuka sawta \'azaab'),
  ('en.transliteration', 89, 14, 'Inna Rabbaka labil mirsaad'),
  ('en.transliteration', 89, 15, 'Fa ammal insaanu izaa mab talaahu Rabbuhoo fa akramahoo wa na\' \'amahoo fa yaqoolu Rabbeee akraman'),
  ('en.transliteration', 89, 16, 'Wa ammaaa izaa mabtalaahu faqadara \'alaihi rizqahoo fa yaqoolu Rabbeee ahaanan'),
  ('en.transliteration', 89, 17, 'Kalla bal laa tukrimooo nal yateem'),
  ('en.transliteration', 89, 18, 'Wa laa tahaaaddoona \'alaata\'aamil miskeen'),
  ('en.transliteration', 89, 19, 'Wa taakuloonat turaasa aklal lammaa'),
  ('en.transliteration', 89, 20, 'Wa tuhibboonal maala hubban jammaa'),
  ('en.transliteration', 89, 21, 'Kallaaa izaaa dukkatil ardu dakkan dakka'),
  ('en.transliteration', 89, 22, 'Wa jaaa\'a Rabbuka wal malaku saffan saffaa'),
  ('en.transliteration', 89, 23, 'Wa jeee\'a yawma\'izim bi jahannnam; Yawma \'iziny yatazakkarul insaanu wa annaa lahuz zikraa'),
  ('en.transliteration', 89, 24, 'Yaqoolu yaa laitanee qaddamtu lihayaatee'),
  ('en.transliteration', 89, 25, 'Fa Yawma izil laa yu\'azzibu \'azaabahooo ahad'),
  ('en.transliteration', 89, 26, 'Wa laa yoosiqu wasaaqa hooo ahad'),
  ('en.transliteration', 89, 27, 'Yaaa ayyatuhan nafsul mutma \'innah'),
  ('en.transliteration', 89, 28, 'Irji\'eee ilaa Rabbiki raadiyatam mardiyyah'),
  ('en.transliteration', 89, 29, 'Fadkhulee fee \'ibaadee'),
  ('en.transliteration', 89, 30, 'Wadkhulee jannatee')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 89, 1, 'فجر کی قسم ہے'),
  ('ur.ahmedali', 89, 2, 'اور دس راتوں کی'),
  ('ur.ahmedali', 89, 3, 'اور جفت اور طاق کی'),
  ('ur.ahmedali', 89, 4, 'اور رات کی جب وہ گزر جائے'),
  ('ur.ahmedali', 89, 5, 'ان چیزو ں کی قسم عقلمندوں کے واسطے معتبر ہے'),
  ('ur.ahmedali', 89, 6, 'کیا آپ نے نہیں دیکھا کہ آپ کے رب نے عاد کے ساتھ کیا سلوک کیا'),
  ('ur.ahmedali', 89, 7, 'جو نسل ارم سے ستونوں والے تھے'),
  ('ur.ahmedali', 89, 8, 'کہ ان جیسا شہرو ں میں پیدا نہیں کیا گیا'),
  ('ur.ahmedali', 89, 9, 'اور ثمود کے ساتھ جنہوں نے پتھروں کو وادی میں تراشا تھا'),
  ('ur.ahmedali', 89, 10, 'اور فرعون میخوں والوں کے ساتھ'),
  ('ur.ahmedali', 89, 11, 'ان سب نے ملک میں سرکشی کی'),
  ('ur.ahmedali', 89, 12, 'پھر انہوں نے بہت فساد پھیلایا'),
  ('ur.ahmedali', 89, 13, 'پھر ان پر تیرے رب نے عذاب کا کوڑا پھینکا'),
  ('ur.ahmedali', 89, 14, 'بے شک آپ کا رب تاک میں ہے'),
  ('ur.ahmedali', 89, 15, 'لیکن انسان تو ایسا ہے کہ جب اسے اس کا رب آزماتا ہے پھر اسے عزت اور نعمت دیتا ہے تو کہتا ہے کہ میرے رب نے مجھے عزت بخشی ہے'),
  ('ur.ahmedali', 89, 16, 'لیکن جب اسے آزماتا ہے پھر اس پر اس کی روزی تنگ کر تا ہے تو کہتا ہے میرے رب نے مجھے ذلیل کر دیا'),
  ('ur.ahmedali', 89, 17, 'ہرگز نہیں بلکہ تم یتیم کی عزت نہیں کرتے'),
  ('ur.ahmedali', 89, 18, 'اور نہ مسکین کو کھانا کھلانے کی ترغیب دیتے ہو'),
  ('ur.ahmedali', 89, 19, 'اور میت کا ترکہ سب سمیٹ کر کھا جاتے ہو'),
  ('ur.ahmedali', 89, 20, 'اور مال سے بہت زیادہ محبت رکھتے ہو'),
  ('ur.ahmedali', 89, 21, 'ہرگز نہیں جب زمین کوٹ کوٹ کر ریزہ ریزہ کر دی جائے گی'),
  ('ur.ahmedali', 89, 22, 'اور آپ کے رب کا (تخت) آجائے گا اور فرشتے بھی صف بستہ چلے آئيں گے'),
  ('ur.ahmedali', 89, 23, 'اوراس دن دوزخ لائی جائے گی اس دن انسان سمجھے گا اور اس وقت اس کو سمجھنا کیا فائدہ دے گا'),
  ('ur.ahmedali', 89, 24, 'کہے گا اے کاش میں اپنی زندگی کے لیے کچھ آگے بھیجتا'),
  ('ur.ahmedali', 89, 25, 'پس اس دن اس کا ساعذاب کوئی بھی نہ دے گا'),
  ('ur.ahmedali', 89, 26, 'اور نہ اس کے جکڑنے کے برابر کوئی جکڑنے والا ہو گا'),
  ('ur.ahmedali', 89, 27, '(ارشاد ہوگا) اے اطمینان والی روح'),
  ('ur.ahmedali', 89, 28, 'اپنے رب کی طرف لوٹ چل تو اس سے راضی وہ تجھ سے راضی'),
  ('ur.ahmedali', 89, 29, 'پس میرے بندو ں میں شامل ہو'),
  ('ur.ahmedali', 89, 30, 'اور میری جنت میں داخل ہو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 89, 1, 'Tanyerinin ağarmasına and olsun;'),
  ('tr.diyanet', 89, 2, 'Zilhicce ayının ilk on gecesine and olsun;'),
  ('tr.diyanet', 89, 3, 'Herşeyin çiftine de, tekine de and olsun;'),
  ('tr.diyanet', 89, 4, 'Gelip geçen geceye and olsun ki, bunların her biri akıl sahibi için birer yemine değmez mi?'),
  ('tr.diyanet', 89, 5, 'Gelip geçen geceye and olsun ki, bunların her biri akıl sahibi için birer yemine değmez mi?'),
  ('tr.diyanet', 89, 6, 'Rabbinin, hiçbir memlekette benzeri ortaya konmayan sütunlara sahip İrem şehrinde oturan Ad milletine ne ettiğini görmedin mi?'),
  ('tr.diyanet', 89, 7, 'Rabbinin, hiçbir memlekette benzeri ortaya konmayan sütunlara sahip İrem şehrinde oturan Ad milletine ne ettiğini görmedin mi?'),
  ('tr.diyanet', 89, 8, 'Rabbinin, hiçbir memlekette benzeri ortaya konmayan sütunlara sahip İrem şehrinde oturan Ad milletine ne ettiğini görmedin mi?'),
  ('tr.diyanet', 89, 9, 'Vadide kayaları kesip yontan Semud milletine, memleketlerde aşırı giden, oralarda bozgunculuğu artıran, sarsılmaz bir saltanat sahibi Firavun\'a Rabbinin ne ettiğini görmedin mi?'),
  ('tr.diyanet', 89, 10, 'Vadide kayaları kesip yontan Semud milletine, memleketlerde aşırı giden, oralarda bozgunculuğu artıran, sarsılmaz bir saltanat sahibi Firavun\'a Rabbinin ne ettiğini görmedin mi?'),
  ('tr.diyanet', 89, 11, 'Vadide kayaları kesip yontan Semud milletine, memleketlerde aşırı giden, oralarda bozgunculuğu artıran, sarsılmaz bir saltanat sahibi Firavun\'a Rabbinin ne ettiğini görmedin mi?'),
  ('tr.diyanet', 89, 12, 'Vadide kayaları kesip yontan Semud milletine, memleketlerde aşırı giden, oralarda bozgunculuğu artıran, sarsılmaz bir saltanat sahibi Firavun\'a Rabbinin ne ettiğini görmedin mi?'),
  ('tr.diyanet', 89, 13, 'Rabbin onları azap kırbacından geçirmiştir.'),
  ('tr.diyanet', 89, 14, 'Doğrusu Rabbin hep gözetlemektedir.'),
  ('tr.diyanet', 89, 15, 'Rabbin denemek için bir insana iyilik edip, nimet verdiği zaman, o: "Rabbim beni şerefli kıldı" der.'),
  ('tr.diyanet', 89, 16, 'Ama onu sınamak için rızkını daraltıp bir ölçüye göre verdiği zaman: "Rabbim bana hor baktı" der.'),
  ('tr.diyanet', 89, 17, 'Hayır; yetime karşı cömert davranmıyorsunuz.'),
  ('tr.diyanet', 89, 18, 'Yoksulu yedirmek konusunda birbirinize özenmiyorsunuz.'),
  ('tr.diyanet', 89, 19, 'Size kalan mirası hak gözetmeden yiyorsunuz.'),
  ('tr.diyanet', 89, 20, 'Malı pek çok seviyorsunuz.'),
  ('tr.diyanet', 89, 21, 'Ama yer, çarpılıp paralandığı zaman;'),
  ('tr.diyanet', 89, 22, 'Melekler sıra sıra dizilip, Rabbinin buyruğu gelince,'),
  ('tr.diyanet', 89, 23, 'O gün, cehennem ortaya konur. O gün insan öğüt almaya çalışır ama artık öğütten ona ne?'),
  ('tr.diyanet', 89, 24, '"Keşke bu hayatım için önceden bir şey yapsaymışım" der.'),
  ('tr.diyanet', 89, 25, 'O gün, hiç kimse, Allah\'ın azabettiği gibi azabedemez.'),
  ('tr.diyanet', 89, 26, 'Hiç kimse O\'nun vurduğu bağ gibisini bağlayamaz.'),
  ('tr.diyanet', 89, 27, 'Ey huzur içinde olan can!'),
  ('tr.diyanet', 89, 28, 'O, senden, sen de O\'ndan hoşnut olarak Rabbine dön!'),
  ('tr.diyanet', 89, 29, 'Ey can! İyi kullarımın arasına gir.'),
  ('tr.diyanet', 89, 30, 'Cennetime gir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 89, 1, 'Demi fajar,'),
  ('id.indonesian', 89, 2, 'dan malam yang sepuluh,'),
  ('id.indonesian', 89, 3, 'dan yang genap dan yang ganjil,'),
  ('id.indonesian', 89, 4, 'dan malam bila berlalu.'),
  ('id.indonesian', 89, 5, 'Pada yang demikian itu terdapat sumpah (yang dapat diterima) oleh orang-orang yang berakal.'),
  ('id.indonesian', 89, 6, 'Apakah kamu tidak memperhatikan bagaimana Tuhanmu berbuat terhadap kaum \'Aad?'),
  ('id.indonesian', 89, 7, '(yaitu) penduduk Iram yang mempunyai bangunan-bangunan yang tinggi,'),
  ('id.indonesian', 89, 8, 'yang belum pernah dibangun (suatu kota) seperti itu, di negeri-negeri lain,'),
  ('id.indonesian', 89, 9, 'dan kaum Tsamud yang memotong batu-batu besar di lembah,'),
  ('id.indonesian', 89, 10, 'dan kaum Fir\'aun yang mempunyai pasak-pasak (tentara yang banyak),'),
  ('id.indonesian', 89, 11, 'yang berbuat sewenang-wenang dalam negeri,'),
  ('id.indonesian', 89, 12, 'lalu mereka berbuat banyak kerusakan dalam negeri itu,'),
  ('id.indonesian', 89, 13, 'karena itu Tuhanmu menimpakan kepada mereka cemeti azab,'),
  ('id.indonesian', 89, 14, 'sesungguhnya Tuhanmu benar-benar mengawasi.'),
  ('id.indonesian', 89, 15, 'Adapun manusia apabila Tuhannya mengujinya lalu dia dimuliakan-Nya dan diberi-Nya kesenangan, maka dia akan berkata: "Tuhanku telah memuliakanku".'),
  ('id.indonesian', 89, 16, 'Adapun bila Tuhannya mengujinya lalu membatasi rezekinya maka dia berkata: "Tuhanku menghinakanku".'),
  ('id.indonesian', 89, 17, 'Sekali-kali tidak (demikian), sebenarnya kamu tidak memuliakan anak yatim,'),
  ('id.indonesian', 89, 18, 'dan kamu tidak saling mengajak memberi makan orang miskin,'),
  ('id.indonesian', 89, 19, 'dan kamu memakan harta pusaka dengan cara mencampur baurkan (yang halal dan yang bathil),'),
  ('id.indonesian', 89, 20, 'dan kamu mencintai harta benda dengan kecintaan yang berlebihan.'),
  ('id.indonesian', 89, 21, 'Jangan (berbuat demikian). Apabila bumi digoncangkan berturut-turut,'),
  ('id.indonesian', 89, 22, 'dan datanglah Tuhanmu; sedang malaikat berbaris-baris.'),
  ('id.indonesian', 89, 23, 'Dan pada hari itu diperlihatkan neraka Jahannam; dan pada hari itu ingatlah manusia, akan tetapi tidak berguna lagi mengingat itu baginya.'),
  ('id.indonesian', 89, 24, 'Dia mengatakan: "Alangkah baiknya kiranya aku dahulu mengerjakan (amal saleh) untuk hidupku ini".'),
  ('id.indonesian', 89, 25, 'Maka pada hari itu tiada seorangpun yang menyiksa seperti siksa-Nya.'),
  ('id.indonesian', 89, 26, 'dan tiada seorangpun yang mengikat seperti ikatan-Nya.'),
  ('id.indonesian', 89, 27, 'Hai jiwa yang tenang.'),
  ('id.indonesian', 89, 28, 'Kembalilah kepada Tuhanmu dengan hati yang puas lagi diridhai-Nya.'),
  ('id.indonesian', 89, 29, 'Maka masuklah ke dalam jama\'ah hamba-hamba-Ku,'),
  ('id.indonesian', 89, 30, 'masuklah ke dalam surga-Ku.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 90, 1, 'I swear by this city, Makkah -'),
  ('en.sahih', 90, 2, 'And you, [O Muhammad], are free of restriction in this city -'),
  ('en.sahih', 90, 3, 'And [by] the father and that which was born [of him],'),
  ('en.sahih', 90, 4, 'We have certainly created man into hardship.'),
  ('en.sahih', 90, 5, 'Does he think that never will anyone overcome him?'),
  ('en.sahih', 90, 6, 'He says, "I have spent wealth in abundance."'),
  ('en.sahih', 90, 7, 'Does he think that no one has seen him?'),
  ('en.sahih', 90, 8, 'Have We not made for him two eyes?'),
  ('en.sahih', 90, 9, 'And a tongue and two lips?'),
  ('en.sahih', 90, 10, 'And have shown him the two ways?'),
  ('en.sahih', 90, 11, 'But he has not broken through the difficult pass.'),
  ('en.sahih', 90, 12, 'And what can make you know what is [breaking through] the difficult pass?'),
  ('en.sahih', 90, 13, 'It is the freeing of a slave'),
  ('en.sahih', 90, 14, 'Or feeding on a day of severe hunger'),
  ('en.sahih', 90, 15, 'An orphan of near relationship'),
  ('en.sahih', 90, 16, 'Or a needy person in misery'),
  ('en.sahih', 90, 17, 'And then being among those who believed and advised one another to patience and advised one another to compassion.'),
  ('en.sahih', 90, 18, 'Those are the companions of the right.'),
  ('en.sahih', 90, 19, 'But they who disbelieved in Our signs - those are the companions of the left.'),
  ('en.sahih', 90, 20, 'Over them will be fire closed in.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 90, 1, 'আমি এই নগরীর শপথ করি'),
  ('bn.bengali', 90, 2, 'এবং এই নগরীতে আপনার উপর কোন প্রতিবন্ধকতা নেই।'),
  ('bn.bengali', 90, 3, 'শপথ জনকের ও যা জন্ম দেয়।'),
  ('bn.bengali', 90, 4, 'নিশ্চয় আমি মানুষকে শ্রমনির্ভররূপে সৃষ্টি করেছি।'),
  ('bn.bengali', 90, 5, 'সে কি মনে করে যে, তার উপর কেউ ক্ষমতাবান হবে না ?'),
  ('bn.bengali', 90, 6, 'সে বলেঃ আমি প্রচুর ধন-সম্পদ ব্যয় করেছি।'),
  ('bn.bengali', 90, 7, 'সে কি মনে করে যে, তাকে কেউ দেখেনি?'),
  ('bn.bengali', 90, 8, 'আমি কি তাকে দেইনি চক্ষুদ্বয়,'),
  ('bn.bengali', 90, 9, 'জিহবা ও ওষ্ঠদ্বয় ?'),
  ('bn.bengali', 90, 10, 'বস্তুতঃ আমি তাকে দু’টি পথ প্রদর্শন করেছি।'),
  ('bn.bengali', 90, 11, 'অতঃপর সে ধর্মের ঘাঁটিতে প্রবেশ করেনি।'),
  ('bn.bengali', 90, 12, 'আপনি জানেন, সে ঘাঁটি কি?'),
  ('bn.bengali', 90, 13, 'তা হচ্ছে দাসমুক্তি'),
  ('bn.bengali', 90, 14, 'অথবা দুর্ভিক্ষের দিনে অন্নদান।'),
  ('bn.bengali', 90, 15, 'এতীম আত্বীয়কে'),
  ('bn.bengali', 90, 16, 'অথবা ধুলি-ধুসরিত মিসকীনকে'),
  ('bn.bengali', 90, 17, 'অতঃপর তাদের অন্তর্ভুক্ত হওয়া, যারা ঈমান আনে এবং পরস্পরকে উপদেশ দেয় সবরের ও উপদেশ দেয় দয়ার।'),
  ('bn.bengali', 90, 18, 'তারাই সৌভাগ্যশালী।'),
  ('bn.bengali', 90, 19, 'আর যারা আমার আয়াতসমূহ অস্বীকার করে তারাই হতভাগা।'),
  ('bn.bengali', 90, 20, 'তারা অগ্নিপরিবেষ্টিত অবস্থায় বন্দী থাকবে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 90, 1, 'Nay, I swear by this city -'),
  ('en.pickthall', 90, 2, 'And thou art an indweller of this city -'),
  ('en.pickthall', 90, 3, 'And the begetter and that which he begat,'),
  ('en.pickthall', 90, 4, 'We verily have created man in an atmosphere:'),
  ('en.pickthall', 90, 5, 'Thinketh he that none hath power over him?'),
  ('en.pickthall', 90, 6, 'And he saith: I have destroyed vast wealth:'),
  ('en.pickthall', 90, 7, 'Thinketh he that none beholdeth him?'),
  ('en.pickthall', 90, 8, 'Did We not assign unto him two eyes'),
  ('en.pickthall', 90, 9, 'And a tongue and two lips,'),
  ('en.pickthall', 90, 10, 'And guide him to the parting of the mountain ways?'),
  ('en.pickthall', 90, 11, 'But he hath not attempted the Ascent -'),
  ('en.pickthall', 90, 12, 'Ah, what will convey unto thee what the Ascent is! -'),
  ('en.pickthall', 90, 13, '(It is) to free a slave,'),
  ('en.pickthall', 90, 14, 'And to feed in the day of hunger.'),
  ('en.pickthall', 90, 15, 'An orphan near of kin,'),
  ('en.pickthall', 90, 16, 'Or some poor wretch in misery,'),
  ('en.pickthall', 90, 17, 'And to be of those who believe and exhort one another to perseverance and exhort one another to pity.'),
  ('en.pickthall', 90, 18, 'Their place will be on the right hand.'),
  ('en.pickthall', 90, 19, 'But those who disbelieve Our revelations, their place will be on the left hand.'),
  ('en.pickthall', 90, 20, 'Fire will be an awning over them.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 90, 1, 'I do call to witness this City;-'),
  ('en.yusufali', 90, 2, 'And thou art a freeman of this City;-'),
  ('en.yusufali', 90, 3, 'And (the mystic ties of) parent and child;-'),
  ('en.yusufali', 90, 4, 'Verily We have created man into toil and struggle.'),
  ('en.yusufali', 90, 5, 'Thinketh he, that none hath power over him?'),
  ('en.yusufali', 90, 6, 'He may say (boastfully); Wealth have I squandered in abundance!'),
  ('en.yusufali', 90, 7, 'Thinketh he that none beholdeth him?'),
  ('en.yusufali', 90, 8, 'Have We not made for him a pair of eyes?-'),
  ('en.yusufali', 90, 9, 'And a tongue, and a pair of lips?-'),
  ('en.yusufali', 90, 10, 'And shown him the two highways?'),
  ('en.yusufali', 90, 11, 'But he hath made no haste on the path that is steep.'),
  ('en.yusufali', 90, 12, 'And what will explain to thee the path that is steep?-'),
  ('en.yusufali', 90, 13, '(It is:) freeing the bondman;'),
  ('en.yusufali', 90, 14, 'Or the giving of food in a day of privation'),
  ('en.yusufali', 90, 15, 'To the orphan with claims of relationship,'),
  ('en.yusufali', 90, 16, 'Or to the indigent (down) in the dust.'),
  ('en.yusufali', 90, 17, 'Then will he be of those who believe, and enjoin patience, (constancy, and self-restraint), and enjoin deeds of kindness and compassion.'),
  ('en.yusufali', 90, 18, 'Such are the Companions of the Right Hand.'),
  ('en.yusufali', 90, 19, 'But those who reject Our Signs, they are the (unhappy) Companions of the Left Hand.'),
  ('en.yusufali', 90, 20, 'On them will be Fire vaulted over (all round).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 90, 1, 'Laaa uqsimu bihaazal balad'),
  ('en.transliteration', 90, 2, 'Wa anta hillum bihaazal balad'),
  ('en.transliteration', 90, 3, 'Wa waalidinw wa maa walad'),
  ('en.transliteration', 90, 4, 'Laqad khalaqnal insaana fee kabad'),
  ('en.transliteration', 90, 5, 'Ayahsabu al-lai yaqdira \'alaihi ahad'),
  ('en.transliteration', 90, 6, 'Yaqoolu ahlaktu maalal lubadaa'),
  ('en.transliteration', 90, 7, 'Ayahsabu al lam yarahooo ahad'),
  ('en.transliteration', 90, 8, 'Alam naj\'al lahoo \'aynayn'),
  ('en.transliteration', 90, 9, 'Wa lisaananw wa shafatayn'),
  ('en.transliteration', 90, 10, 'Wa hadaynaahun najdayn'),
  ('en.transliteration', 90, 11, 'Falaq tahamal-\'aqabah'),
  ('en.transliteration', 90, 12, 'Wa maaa adraaka mal\'aqabah'),
  ('en.transliteration', 90, 13, 'Fakku raqabah'),
  ('en.transliteration', 90, 14, 'Aw it\'aamun fee yawmin zee masghabah'),
  ('en.transliteration', 90, 15, 'Yateeman zaa maqrabah'),
  ('en.transliteration', 90, 16, 'Aw miskeenan zaa matrabah'),
  ('en.transliteration', 90, 17, 'Summa kaana minal lazeena aamanoo wa tawaasaw bissabri wa tawaasaw bilmarhamah'),
  ('en.transliteration', 90, 18, 'Ulaaa\'ika As-haabul maimanah'),
  ('en.transliteration', 90, 19, 'Wallazeena kafaroo bi aayaatinaa hum as-haabul Mash\'amah'),
  ('en.transliteration', 90, 20, 'Alaihim naarum mu\'sadah')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 90, 1, 'ا س شہر کی قسم ہے'),
  ('ur.ahmedali', 90, 2, 'حالانکہ آپ اس شہر میں مقیم ہیں'),
  ('ur.ahmedali', 90, 3, 'اورباپ کی اور اس کی اولاد کی قسم ہے'),
  ('ur.ahmedali', 90, 4, 'کہ بےشک ہم نے انسان کو مصیبت میں پیدا کیا ہے'),
  ('ur.ahmedali', 90, 5, 'کیا وہ خیال کرتا ہےکہ اس پر کوئی بھی ہرگز قابو نہ پا سکے گا'),
  ('ur.ahmedali', 90, 6, 'کہتا ہے کہ میں نے مال برباد کر ڈالا'),
  ('ur.ahmedali', 90, 7, 'کیا وہ خیال کرتا ہے کہ اسے کسی نے بھی نہیں دیکھا'),
  ('ur.ahmedali', 90, 8, 'کیا ہم نے اس کے لیے دو آنکھیں نہیں بنائیں'),
  ('ur.ahmedali', 90, 9, 'اور زبان اور دو ہونٹ'),
  ('ur.ahmedali', 90, 10, 'اور ہم نے اسے دونوں راستے دکھائے'),
  ('ur.ahmedali', 90, 11, 'پس وہ (دین کی) گھاٹی میں سے نہ ہو کر نکلا'),
  ('ur.ahmedali', 90, 12, 'اور آپ کو کیا معلوم کہ وہ گھاٹی کیا ہے'),
  ('ur.ahmedali', 90, 13, 'گردن کا چھوڑانا'),
  ('ur.ahmedali', 90, 14, 'یا بھوک کے دن میں کھلانا'),
  ('ur.ahmedali', 90, 15, 'کسی رشتہ دار یتیم کو'),
  ('ur.ahmedali', 90, 16, 'یا کسی خاک نشین مسکین کو'),
  ('ur.ahmedali', 90, 17, 'پھر وہ ان میں سے ہو جو ایمان لائے اور انہوں نے ایک دوسرے کو صبر کی وصیت کی اور رحم کرنے کی وصیت کی'),
  ('ur.ahmedali', 90, 18, 'یہی لوگ دائیں والے ہیں'),
  ('ur.ahmedali', 90, 19, 'اور جنہوں نے ہماری آیتوں سے انکار کیا وہی بائیں والے ہیں'),
  ('ur.ahmedali', 90, 20, 'انہیں پر چاروں طرف سے بند کی ہوئی آگ ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 90, 1, 'Bu şehre (Mekke\'ye) yemin ederim; ki sen bu şehirde oturmuşsun.'),
  ('tr.diyanet', 90, 2, 'Bu şehre (Mekke\'ye) yemin ederim; ki sen bu şehirde oturmuşsun.'),
  ('tr.diyanet', 90, 3, 'Doğurana ve doğurduğuna and olsun ki;'),
  ('tr.diyanet', 90, 4, 'İnsanoğlunu, zorluklara katlanacak şekilde yarattık.'),
  ('tr.diyanet', 90, 5, 'İnsanoğlu, kendisine kimsenin güç yetiremeyeceğini mi sanıyor?'),
  ('tr.diyanet', 90, 6, '"Yığın yığın mal tüketmişimdir" diyor.'),
  ('tr.diyanet', 90, 7, 'O, kimsenin kendisini görmediğini mi zannediyor?'),
  ('tr.diyanet', 90, 8, 'Biz onun için iki göz, bir dil ve iki dudak var etmedik mi?'),
  ('tr.diyanet', 90, 9, 'Biz onun için iki göz, bir dil ve iki dudak var etmedik mi?'),
  ('tr.diyanet', 90, 10, 'Biz ona eğri ve doğru iki yolu da göstermedik mi?'),
  ('tr.diyanet', 90, 11, 'Ama o, zor geçidi aşmaya girişemedi.'),
  ('tr.diyanet', 90, 12, 'O zor geçidin ne olduğunu sen bilir misin?'),
  ('tr.diyanet', 90, 13, 'O geçit, bir köle ve esir azadetmek,'),
  ('tr.diyanet', 90, 14, 'Yahut, açlık gününde, yakını olan bir öksüzü, yahut toprağa serilmiş bir yoksulu doyurmaktır.'),
  ('tr.diyanet', 90, 15, 'Yahut, açlık gününde, yakını olan bir öksüzü, yahut toprağa serilmiş bir yoksulu doyurmaktır.'),
  ('tr.diyanet', 90, 16, 'Yahut, açlık gününde, yakını olan bir öksüzü, yahut toprağa serilmiş bir yoksulu doyurmaktır.'),
  ('tr.diyanet', 90, 17, 'Sonra, inanıp birbirlerine sabır tavsiye edenlerden, merhametlilerden olmayı tavsiye edenlerden olmaktır.'),
  ('tr.diyanet', 90, 18, 'İşte bunlar amel defterleri sağdan verilenlerdir.'),
  ('tr.diyanet', 90, 19, 'Ayetlerimizi inkar edenler, işte onlar amel defterleri sollarından verilenlerdir.'),
  ('tr.diyanet', 90, 20, 'Onlar her yönden ateşle kapatılacaklardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 90, 1, 'Aku benar-benar bersumpah dengan kota ini (Mekah),'),
  ('id.indonesian', 90, 2, 'dan kamu (Muhammad) bertempat di kota Mekah ini,'),
  ('id.indonesian', 90, 3, 'dan demi bapak dan anaknya.'),
  ('id.indonesian', 90, 4, 'Sesungguhnya Kami telah menciptakan manusia berada dalam susah payah.'),
  ('id.indonesian', 90, 5, 'Apakah manusia itu menyangka bahwa sekali-kali tiada seorangpun yang berkuasa atasnya?'),
  ('id.indonesian', 90, 6, 'Dan mengatakan: "Aku telah menghabiskan harta yang banyak".'),
  ('id.indonesian', 90, 7, 'Apakah dia menyangka bahwa tiada seorangpun yang melihatnya?'),
  ('id.indonesian', 90, 8, 'Bukankah Kami telah memberikan kepadanya dua buah mata,'),
  ('id.indonesian', 90, 9, 'lidah dan dua buah bibir.'),
  ('id.indonesian', 90, 10, 'Dan Kami telah menunjukkan kepadanya dua jalan,'),
  ('id.indonesian', 90, 11, 'Tetapi dia tiada menempuh jalan yang mendaki lagi sukar.'),
  ('id.indonesian', 90, 12, 'Tahukah kamu apakah jalan yang mendaki lagi sukar itu?'),
  ('id.indonesian', 90, 13, '(yaitu) melepaskan budak dari perbudakan,'),
  ('id.indonesian', 90, 14, 'atau memberi makan pada hari kelaparan,'),
  ('id.indonesian', 90, 15, '(kepada) anak yatim yang ada hubungan kerabat,'),
  ('id.indonesian', 90, 16, 'atau kepada orang miskin yang sangat fakir.'),
  ('id.indonesian', 90, 17, 'Dan dia (tidak pula) termasuk orang-orang yang beriman dan saling berpesan untuk bersabar dan saling berpesan untuk berkasih sayang.'),
  ('id.indonesian', 90, 18, 'Mereka (orang-orang yang beriman dan saling berpesan itu) adalah golongan kanan.'),
  ('id.indonesian', 90, 19, 'Dan orang-orang yang kafir kepada ayat-ayat Kami, mereka itu adalah golongan kiri.'),
  ('id.indonesian', 90, 20, 'Mereka berada dalam neraka yang ditutup rapat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 91, 1, 'By the sun and its brightness'),
  ('en.sahih', 91, 2, 'And [by] the moon when it follows it'),
  ('en.sahih', 91, 3, 'And [by] the day when it displays it'),
  ('en.sahih', 91, 4, 'And [by] the night when it covers it'),
  ('en.sahih', 91, 5, 'And [by] the sky and He who constructed it'),
  ('en.sahih', 91, 6, 'And [by] the earth and He who spread it'),
  ('en.sahih', 91, 7, 'And [by] the soul and He who proportioned it'),
  ('en.sahih', 91, 8, 'And inspired it [with discernment of] its wickedness and its righteousness,'),
  ('en.sahih', 91, 9, 'He has succeeded who purifies it,'),
  ('en.sahih', 91, 10, 'And he has failed who instills it [with corruption].'),
  ('en.sahih', 91, 11, 'Thamud denied [their prophet] by reason of their transgression,'),
  ('en.sahih', 91, 12, 'When the most wretched of them was sent forth.'),
  ('en.sahih', 91, 13, 'And the messenger of Allah [Salih] said to them, "[Do not harm] the she-camel of Allah or [prevent her from] her drink."'),
  ('en.sahih', 91, 14, 'But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].'),
  ('en.sahih', 91, 15, 'And He does not fear the consequence thereof.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 91, 1, 'শপথ সূর্যের ও তার কিরণের,'),
  ('bn.bengali', 91, 2, 'শপথ চন্দ্রের যখন তা সূর্যের পশ্চাতে আসে,'),
  ('bn.bengali', 91, 3, 'শপথ দিবসের যখন সে সূর্যকে প্রখরভাবে প্রকাশ করে,'),
  ('bn.bengali', 91, 4, 'শপথ রাত্রির যখন সে সূর্যকে আচ্ছাদিত করে,'),
  ('bn.bengali', 91, 5, 'শপথ আকাশের এবং যিনি তা নির্মাণ করেছেন, তাঁর।'),
  ('bn.bengali', 91, 6, 'শপথ পৃথিবীর এবং যিনি তা বিস্তৃত করেছেন, তাঁর,'),
  ('bn.bengali', 91, 7, 'শপথ প্রাণের এবং যিনি তা সুবিন্যস্ত করেছেন, তাঁর,'),
  ('bn.bengali', 91, 8, 'অতঃপর তাকে তার অসৎকর্ম ও সৎকর্মের জ্ঞান দান করেছেন,'),
  ('bn.bengali', 91, 9, 'যে নিজেকে শুদ্ধ করে, সেই সফলকাম হয়।'),
  ('bn.bengali', 91, 10, 'এবং যে নিজেকে কলুষিত করে, সে ব্যর্থ মনোরথ হয়।'),
  ('bn.bengali', 91, 11, 'সামুদ সম্প্রদায় অবাধ্যতা বশতঃ মিথ্যারোপ করেছিল।'),
  ('bn.bengali', 91, 12, 'যখন তাদের সর্বাধিক হতভাগ্য ব্যক্তি তৎপর হয়ে উঠেছিল।'),
  ('bn.bengali', 91, 13, 'অতঃপর আল্লাহর রসূল তাদেরকে বলেছিলেনঃ আল্লাহর উষ্ট্রী ও তাকে পানি পান করানোর ব্যাপারে সতর্ক থাক।'),
  ('bn.bengali', 91, 14, 'অতঃপর ওরা তার প্রতি মিথ্যারোপ করেছিল এবং উষ্ট্রীর পা কর্তন করেছিল। তাদের পাপের কারণে তাদের পালনকর্তা তাদের উপর ধ্বংস নাযিল করে একাকার করে দিলেন।'),
  ('bn.bengali', 91, 15, 'আল্লাহ তা’আলা এই ধ্বংসের কোন বিরূপ পরিণতির আশংকা করেন না।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 91, 1, 'By the sun and his brightness,'),
  ('en.pickthall', 91, 2, 'And the moon when she followeth him,'),
  ('en.pickthall', 91, 3, 'And the day when it revealeth him,'),
  ('en.pickthall', 91, 4, 'And the night when it enshroudeth him,'),
  ('en.pickthall', 91, 5, 'And the heaven and Him Who built it,'),
  ('en.pickthall', 91, 6, 'And the earth and Him Who spread it,'),
  ('en.pickthall', 91, 7, 'And a soul and Him Who perfected it'),
  ('en.pickthall', 91, 8, 'And inspired it (with conscience of) what is wrong for it and (what is) right for it.'),
  ('en.pickthall', 91, 9, 'He is indeed successful who causeth it to grow,'),
  ('en.pickthall', 91, 10, 'And he is indeed a failure who stunteth it.'),
  ('en.pickthall', 91, 11, '(The tribe of) Thamud denied (the truth) in their rebellious pride,'),
  ('en.pickthall', 91, 12, 'When the basest of them broke forth'),
  ('en.pickthall', 91, 13, 'And the messenger of Allah said: It is the she-camel of Allah, so let her drink!'),
  ('en.pickthall', 91, 14, 'But they denied him, and they hamstrung her, so Allah doomed them for their sin and rased (their dwellings).'),
  ('en.pickthall', 91, 15, 'He dreadeth not the sequel (of events).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 91, 1, 'By the Sun and his (glorious) splendour;'),
  ('en.yusufali', 91, 2, 'By the Moon as she follows him;'),
  ('en.yusufali', 91, 3, 'By the Day as it shows up (the Sun\'s) glory;'),
  ('en.yusufali', 91, 4, 'By the Night as it conceals it;'),
  ('en.yusufali', 91, 5, 'By the Firmament and its (wonderful) structure;'),
  ('en.yusufali', 91, 6, 'By the Earth and its (wide) expanse:'),
  ('en.yusufali', 91, 7, 'By the Soul, and the proportion and order given to it;'),
  ('en.yusufali', 91, 8, 'And its enlightenment as to its wrong and its right;-'),
  ('en.yusufali', 91, 9, 'Truly he succeeds that purifies it,'),
  ('en.yusufali', 91, 10, 'And he fails that corrupts it!'),
  ('en.yusufali', 91, 11, 'The Thamud (people) rejected (their prophet) through their inordinate wrong-doing,'),
  ('en.yusufali', 91, 12, 'Behold, the most wicked man among them was deputed (for impiety).'),
  ('en.yusufali', 91, 13, 'But the Messenger of Allah said to them: "It is a She-camel of Allah! And (bar her not from) having her drink!"'),
  ('en.yusufali', 91, 14, 'Then they rejected him (as a false prophet), and they hamstrung her. So their Lord, on account of their crime, obliterated their traces and made them equal (in destruction, high and low)!'),
  ('en.yusufali', 91, 15, 'And for Him is no fear of its consequences.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 91, 1, 'Wash shamsi wa duhaa haa'),
  ('en.transliteration', 91, 2, 'Wal qamari izaa talaa haa'),
  ('en.transliteration', 91, 3, 'Wannahaari izaa jallaa haa'),
  ('en.transliteration', 91, 4, 'Wallaili izaa yaghshaa haa'),
  ('en.transliteration', 91, 5, 'Wassamaaa\'i wa maa banaahaa'),
  ('en.transliteration', 91, 6, 'Wal ardi wa maa tahaahaa'),
  ('en.transliteration', 91, 7, 'Wa nafsinw wa maa sawwaahaa'),
  ('en.transliteration', 91, 8, 'Fa-alhamahaa fujoorahaa wa taqwaahaa'),
  ('en.transliteration', 91, 9, 'Qad aflaha man zakkaahaa'),
  ('en.transliteration', 91, 10, 'Wa qad khaaba man dassaahaa'),
  ('en.transliteration', 91, 11, 'Kazzabat Samoodu bi taghwaahaaa'),
  ('en.transliteration', 91, 12, 'Izim ba\'asa ashqaahaa'),
  ('en.transliteration', 91, 13, 'Faqaala lahum Rasoolul laahi naaqatal laahi wa suqiyaahaa'),
  ('en.transliteration', 91, 14, 'Fakazzaboohu fa\'aqaroohaa fadamdama \'alaihim Rabbuhum bizambihim fasaw waahaa'),
  ('en.transliteration', 91, 15, 'Wa laa yakhaafu\'uqbaahaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 91, 1, 'سورج کی اور اس کی دھوپ کی قسم ہے'),
  ('ur.ahmedali', 91, 2, 'اور چاند کی جب وہ اس کے پیچھے آئے'),
  ('ur.ahmedali', 91, 3, 'اور دن کی جب وہ اس کو روشن کر دے'),
  ('ur.ahmedali', 91, 4, 'اور رات کی جب وہ اس کو ڈھانپ لے'),
  ('ur.ahmedali', 91, 5, 'اور آسمان کی اور اس کی جس نے اس کو بنایا'),
  ('ur.ahmedali', 91, 6, 'اور زمین اور اس کی جس نے اس کو بچھایا'),
  ('ur.ahmedali', 91, 7, 'اور جان کی اور اس کی جس نے اس کو درست کیا'),
  ('ur.ahmedali', 91, 8, 'پھر اس کو اس کی بدی اور نیکی سمجھائی'),
  ('ur.ahmedali', 91, 9, 'بے شک وہ کامیاب ہوا جس نے اپنی روح کو پاک کر لیا'),
  ('ur.ahmedali', 91, 10, 'اوربے شک وہ غارت ہوا جس نے اس کو آلودہ کر لیا'),
  ('ur.ahmedali', 91, 11, 'ثمود نے اپنی سرکشی سے (صالح کو) جھٹلایا تھا'),
  ('ur.ahmedali', 91, 12, 'جب کہ ان کا بڑا بدبخت اٹھا'),
  ('ur.ahmedali', 91, 13, 'پس ان سے الله کے رسول نے کہا کہ الله کی اونٹنی اور اس کے پانی پینے کی باری سے بچو'),
  ('ur.ahmedali', 91, 14, 'پس انہوں نے اس کو جھٹلایا اور اونٹنی کی کونچیں کاٹ ڈالیں پھر ان پر ان کے رب نےان کےگناہوں کے بدلے ہلاکت نازل کی پھر ان کو برابر کر دیا'),
  ('ur.ahmedali', 91, 15, 'اوراس نے اس کےانجام کی پروا نہ کی')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 91, 1, 'Güneşe ve onun ışığına,'),
  ('tr.diyanet', 91, 2, 'Ardından gelmekte olan aya,'),
  ('tr.diyanet', 91, 3, 'Onu ortaya koyan gündüze,'),
  ('tr.diyanet', 91, 4, 'Onu bürüyen geceye,'),
  ('tr.diyanet', 91, 5, 'Göğe ve onu yapana,'),
  ('tr.diyanet', 91, 6, 'Yere ve onu yayana,'),
  ('tr.diyanet', 91, 7, 'Kişiye ve onu şekillendirene,'),
  ('tr.diyanet', 91, 8, 'Sonra da ona iyilik ve kötülük kabiliyeti verene and olsun ki:'),
  ('tr.diyanet', 91, 9, 'Kendini arıtan saadete ermiştir.'),
  ('tr.diyanet', 91, 10, 'Kendini fenalıklara gömen kimse de ziyana uğramıştır.'),
  ('tr.diyanet', 91, 11, 'Semud milleti, içlerinden en azgını ileri atılınca, azgınlığı yüzünden peygamberleri yalanladı.'),
  ('tr.diyanet', 91, 12, 'Semud milleti, içlerinden en azgını ileri atılınca, azgınlığı yüzünden peygamberleri yalanladı.'),
  ('tr.diyanet', 91, 13, 'Allah\'ın peygamberi onlara, Allah\'ın devesini göstermiş ve: "Allah\'ın bu devesine ve onun su hakkına dokunmayın" demişti.'),
  ('tr.diyanet', 91, 14, 'Onu yalanladılar ve deveyi boğazladılar. Bunun üzerine Rableri, suçlarından dolayı onların üzerine katmerli azap indirdi; yerle bir etti onları.'),
  ('tr.diyanet', 91, 15, 'Bu işin sonundan O\'nun korkusu yoktur.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 91, 1, 'Demi matahari dan cahayanya di pagi hari,'),
  ('id.indonesian', 91, 2, 'dan bulan apabila mengiringinya,'),
  ('id.indonesian', 91, 3, 'dan siang apabila menampakkannya,'),
  ('id.indonesian', 91, 4, 'dan malam apabila menutupinya,'),
  ('id.indonesian', 91, 5, 'dan langit serta pembinaannya,'),
  ('id.indonesian', 91, 6, 'dan bumi serta penghamparannya,'),
  ('id.indonesian', 91, 7, 'dan jiwa serta penyempurnaannya (ciptaannya),'),
  ('id.indonesian', 91, 8, 'maka Allah mengilhamkan kepada jiwa itu (jalan) kefasikan dan ketakwaannya.'),
  ('id.indonesian', 91, 9, 'sesungguhnya beruntunglah orang yang mensucikan jiwa itu,'),
  ('id.indonesian', 91, 10, 'dan sesungguhnya merugilah orang yang mengotorinya.'),
  ('id.indonesian', 91, 11, '(Kaum) Tsamud telah mendustakan (rasulnya) karena mereka melampaui batas,'),
  ('id.indonesian', 91, 12, 'ketika bangkit orang yang paling celaka di antara mereka,'),
  ('id.indonesian', 91, 13, 'lalu Rasul Allah (Saleh) berkata kepada mereka: ("Biarkanlah) unta betina Allah dan minumannya".'),
  ('id.indonesian', 91, 14, 'Lalu mereka mendustakannya dan menyembelih unta itu, maka Tuhan mereka membinasakan mereka disebabkan dosa mereka, lalu Allah menyama-ratakan mereka (dengan tanah),'),
  ('id.indonesian', 91, 15, 'dan Allah tidak takut terhadap akibat tindakan-Nya itu.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 92, 1, 'By the night when it covers'),
  ('en.sahih', 92, 2, 'And [by] the day when it appears'),
  ('en.sahih', 92, 3, 'And [by] He who created the male and female,'),
  ('en.sahih', 92, 4, 'Indeed, your efforts are diverse.'),
  ('en.sahih', 92, 5, 'As for he who gives and fears Allah'),
  ('en.sahih', 92, 6, 'And believes in the best [reward],'),
  ('en.sahih', 92, 7, 'We will ease him toward ease.'),
  ('en.sahih', 92, 8, 'But as for he who withholds and considers himself free of need'),
  ('en.sahih', 92, 9, 'And denies the best [reward],'),
  ('en.sahih', 92, 10, 'We will ease him toward difficulty.'),
  ('en.sahih', 92, 11, 'And what will his wealth avail him when he falls?'),
  ('en.sahih', 92, 12, 'Indeed, [incumbent] upon Us is guidance.'),
  ('en.sahih', 92, 13, 'And indeed, to Us belongs the Hereafter and the first [life].'),
  ('en.sahih', 92, 14, 'So I have warned you of a Fire which is blazing.'),
  ('en.sahih', 92, 15, 'None will [enter to] burn therein except the most wretched one.'),
  ('en.sahih', 92, 16, 'Who had denied and turned away.'),
  ('en.sahih', 92, 17, 'But the righteous one will avoid it -'),
  ('en.sahih', 92, 18, '[He] who gives [from] his wealth to purify himself'),
  ('en.sahih', 92, 19, 'And not [giving] for anyone who has [done him] a favor to be rewarded'),
  ('en.sahih', 92, 20, 'But only seeking the countenance of his Lord, Most High.'),
  ('en.sahih', 92, 21, 'And he is going to be satisfied.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 92, 1, 'শপথ রাত্রির, যখন সে আচ্ছন্ন করে,'),
  ('bn.bengali', 92, 2, 'শপথ দিনের, যখন সে আলোকিত হয়'),
  ('bn.bengali', 92, 3, 'এবং তাঁর, যিনি নর ও নারী সৃষ্টি করেছেন,'),
  ('bn.bengali', 92, 4, 'নিশ্চয় তোমাদের কর্ম প্রচেষ্টা বিভিন্ন ধরনের।'),
  ('bn.bengali', 92, 5, 'অতএব, যে দান করে এবং খোদাভীরু হয়,'),
  ('bn.bengali', 92, 6, 'এবং উত্তম বিষয়কে সত্য মনে করে,'),
  ('bn.bengali', 92, 7, 'আমি তাকে সুখের বিষয়ের জন্যে সহজ পথ দান করব।'),
  ('bn.bengali', 92, 8, 'আর যে কৃপণতা করে ও বেপরওয়া হয়'),
  ('bn.bengali', 92, 9, 'এবং উত্তম বিষয়কে মিথ্যা মনে করে,'),
  ('bn.bengali', 92, 10, 'আমি তাকে কষ্টের বিষয়ের জন্যে সহজ পথ দান করব।'),
  ('bn.bengali', 92, 11, 'যখন সে অধঃপতিত হবে, তখন তার সম্পদ তার কোনই কাজে আসবে না।'),
  ('bn.bengali', 92, 12, 'আমার দায়িত্ব পথ প্রদর্শন করা।'),
  ('bn.bengali', 92, 13, 'আর আমি মালিক ইহকালের ও পরকালের।'),
  ('bn.bengali', 92, 14, 'অতএব, আমি তোমাদেরকে প্রজ্বলিত অগ্নি সম্পর্কে সতর্ক করে দিয়েছি।'),
  ('bn.bengali', 92, 15, 'এতে নিতান্ত হতভাগ্য ব্যক্তিই প্রবেশ করবে,'),
  ('bn.bengali', 92, 16, 'যে মিথ্যারোপ করে ও মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 92, 17, 'এ থেকে দূরে রাখা হবে খোদাভীরু ব্যক্তিকে,'),
  ('bn.bengali', 92, 18, 'যে আত্নশুদ্ধির জন্যে তার ধন-সম্পদ দান করে।'),
  ('bn.bengali', 92, 19, 'এবং তার উপর কারও কোন প্রতিদানযোগ্য অনুগ্রহ থাকে না।'),
  ('bn.bengali', 92, 20, 'তার মহান পালনকর্তার সন্তুষ্টি অন্বেষণ ব্যতীত।'),
  ('bn.bengali', 92, 21, 'সে সত্বরই সন্তুষ্টি লাভ করবে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 92, 1, 'By the night enshrouding'),
  ('en.pickthall', 92, 2, 'And the day resplendent'),
  ('en.pickthall', 92, 3, 'And Him Who hath created male and female,'),
  ('en.pickthall', 92, 4, 'Lo! your effort is dispersed (toward divers ends).'),
  ('en.pickthall', 92, 5, 'As for him who giveth and is dutiful (toward Allah)'),
  ('en.pickthall', 92, 6, 'And believeth in goodness;'),
  ('en.pickthall', 92, 7, 'Surely We will ease his way unto the state of ease.'),
  ('en.pickthall', 92, 8, 'But as for him who hoardeth and deemeth himself independent,'),
  ('en.pickthall', 92, 9, 'And disbelieveth in goodness;'),
  ('en.pickthall', 92, 10, 'Surely We will ease his way unto adversity.'),
  ('en.pickthall', 92, 11, 'His riches will not save him when he perisheth.'),
  ('en.pickthall', 92, 12, 'Lo! Ours it is (to give) the guidance'),
  ('en.pickthall', 92, 13, 'And lo! unto Us belong the latter portion and the former.'),
  ('en.pickthall', 92, 14, 'Therefor have I warned you of the flaming Fire'),
  ('en.pickthall', 92, 15, 'Which only the most wretched must endure,'),
  ('en.pickthall', 92, 16, 'He who denieth and turneth away.'),
  ('en.pickthall', 92, 17, 'Far removed from it will be the righteous'),
  ('en.pickthall', 92, 18, 'Who giveth his wealth that he may grow (in goodness).'),
  ('en.pickthall', 92, 19, 'And none hath with him any favour for reward,'),
  ('en.pickthall', 92, 20, 'Except as seeking (to fulfil) the purpose of his Lord Most High.'),
  ('en.pickthall', 92, 21, 'He verily will be content.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 92, 1, 'By the Night as it conceals (the light);'),
  ('en.yusufali', 92, 2, 'By the Day as it appears in glory;'),
  ('en.yusufali', 92, 3, 'By (the mystery of) the creation of male and female;-'),
  ('en.yusufali', 92, 4, 'Verily, (the ends) ye strive for are diverse.'),
  ('en.yusufali', 92, 5, 'So he who gives (in charity) and fears (Allah),'),
  ('en.yusufali', 92, 6, 'And (in all sincerity) testifies to the best,-'),
  ('en.yusufali', 92, 7, 'We will indeed make smooth for him the path to Bliss.'),
  ('en.yusufali', 92, 8, 'But he who is a greedy miser and thinks himself self-sufficient,'),
  ('en.yusufali', 92, 9, 'And gives the lie to the best,-'),
  ('en.yusufali', 92, 10, 'We will indeed make smooth for him the path to Misery;'),
  ('en.yusufali', 92, 11, 'Nor will his wealth profit him when he falls headlong (into the Pit).'),
  ('en.yusufali', 92, 12, 'Verily We take upon Ourselves to guide,'),
  ('en.yusufali', 92, 13, 'And verily unto Us (belong) the End and the Beginning.'),
  ('en.yusufali', 92, 14, 'Therefore do I warn you of a Fire blazing fiercely;'),
  ('en.yusufali', 92, 15, 'None shall reach it but those most unfortunate ones'),
  ('en.yusufali', 92, 16, 'Who give the lie to Truth and turn their backs.'),
  ('en.yusufali', 92, 17, 'But those most devoted to Allah shall be removed far from it,-'),
  ('en.yusufali', 92, 18, 'Those who spend their wealth for increase in self-purification,'),
  ('en.yusufali', 92, 19, 'And have in their minds no favour from anyone for which a reward is expected in return,'),
  ('en.yusufali', 92, 20, 'But only the desire to seek for the Countenance of their Lord Most High;'),
  ('en.yusufali', 92, 21, 'And soon will they attain (complete) satisfaction.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 92, 1, 'Wallaili izaa yaghshaa'),
  ('en.transliteration', 92, 2, 'Wannahaari izaa tajalla'),
  ('en.transliteration', 92, 3, 'Wa maa khalaqaz zakara wal unthaa'),
  ('en.transliteration', 92, 4, 'Inna sa\'yakum lashattaa'),
  ('en.transliteration', 92, 5, 'Fa ammaa man a\'taa wattaqaa'),
  ('en.transliteration', 92, 6, 'Wa saddaqa bil husnaa'),
  ('en.transliteration', 92, 7, 'Fasanu yassiruhoo lilyusraa'),
  ('en.transliteration', 92, 8, 'Wa ammaa mam bakhila wastaghnaa'),
  ('en.transliteration', 92, 9, 'Wa kazzaba bil husnaa'),
  ('en.transliteration', 92, 10, 'Fasanu yassiruhoo lil\'usraa'),
  ('en.transliteration', 92, 11, 'Wa maa yughnee \'anhu maaluhooo izaa taraddaa'),
  ('en.transliteration', 92, 12, 'Inna \'alainaa lal hudaa'),
  ('en.transliteration', 92, 13, 'Wa inna lanaa lal Aakhirata wal oolaa'),
  ('en.transliteration', 92, 14, 'Fa anzartukum naaran talazzaa'),
  ('en.transliteration', 92, 15, 'Laa yaslaahaaa illal ashqaa'),
  ('en.transliteration', 92, 16, 'Allazee kazzaba wa tawallaa'),
  ('en.transliteration', 92, 17, 'Wa sa yujannnabuhal atqaa'),
  ('en.transliteration', 92, 18, 'Allazee yu\'tee maalahoo yatazakkaa'),
  ('en.transliteration', 92, 19, 'Wa maa li ahadin \'indahoo min ni\'matin tujzaaa'),
  ('en.transliteration', 92, 20, 'Illab tighaaa\'a wajhi rabbihil a \'laa'),
  ('en.transliteration', 92, 21, 'Wa lasawfa yardaa')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 92, 1, 'رات کی قسم ہے جب کہ وہ چھاجائے'),
  ('ur.ahmedali', 92, 2, 'اور دن کی جبکہ وہ روشن ہو'),
  ('ur.ahmedali', 92, 3, 'اوراس کی قسم کہ جس نے نر و مادہ کوبنایا'),
  ('ur.ahmedali', 92, 4, 'بے شک تمہاری کوشش مختلف ہے'),
  ('ur.ahmedali', 92, 5, 'پھر جس نے دیا اور پرہیز گاری کی'),
  ('ur.ahmedali', 92, 6, 'اورنیک بات کی تصدیق کی'),
  ('ur.ahmedali', 92, 7, 'تو ہم اس کے لیے جنت کی راہیں آسان کر دیں گے'),
  ('ur.ahmedali', 92, 8, 'اورلیکن جس نے بخل کیا اوربے پرواہ رہا'),
  ('ur.ahmedali', 92, 9, 'اور نیک بات کو جھٹلایا'),
  ('ur.ahmedali', 92, 10, 'تو ہم اس کے لیے جہنم کی راہیں آسان کر دیں گے'),
  ('ur.ahmedali', 92, 11, 'اوراس کا مال اس کے کچھ بھی کام نہ آئے گا جب کہ وہ گھڑے میں گرے گا'),
  ('ur.ahmedali', 92, 12, 'بے شک ہمارے ذمے راہ دکھانا ہے'),
  ('ur.ahmedali', 92, 13, 'اور بے شک ہمارے ہی ہاتھ میں آخرت بھی اور دنیا بھی ہے'),
  ('ur.ahmedali', 92, 14, 'پس میں نے تمہیں بڑھکتی ہوئی آگ سے ڈرایا ہے'),
  ('ur.ahmedali', 92, 15, 'جس میں صرف وہی بد بخت داخل ہوگا'),
  ('ur.ahmedali', 92, 16, 'جس نے جھٹلایا اورمنہ موڑا'),
  ('ur.ahmedali', 92, 17, 'اوراس آگ سے وہ بڑا پرہیز گار دور رہے گا'),
  ('ur.ahmedali', 92, 18, 'جو اپنا مال دیتا ہے تاکہ وہ پاک ہو جائے'),
  ('ur.ahmedali', 92, 19, 'اور اس پر کسی کا کوئی احسان نہیں کہ جس کا بدلہ دیا جائے'),
  ('ur.ahmedali', 92, 20, 'وہ تو صرف اپنے سب سے برتر رب کی رضا مندی کے لیے دیتا ہے'),
  ('ur.ahmedali', 92, 21, 'اوروہ عنقریب خوش ہو جائے گا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 92, 1, 'Kararıp ortalığı bürüdüğü zaman geceye and olsun.'),
  ('tr.diyanet', 92, 2, 'Açılıp aydınlattığı zaman gündüze and olsun.'),
  ('tr.diyanet', 92, 3, 'Erkeği ve dişiyi yaratana and olsun ki:'),
  ('tr.diyanet', 92, 4, 'Doğrusu sizin çalışmalarınız çeşitlidir.'),
  ('tr.diyanet', 92, 5, 'Elinde bulunandan verenin, Allah\'a karşı gelmekten sakınanın, en güzel söz olan Allah\'ın birliğini doğrulayanın işlerini kolaylaştırırız.'),
  ('tr.diyanet', 92, 6, 'Elinde bulunandan verenin, Allah\'a karşı gelmekten sakınanın, en güzel söz olan Allah\'ın birliğini doğrulayanın işlerini kolaylaştırırız.'),
  ('tr.diyanet', 92, 7, 'Elinde bulunandan verenin, Allah\'a karşı gelmekten sakınanın, en güzel söz olan Allah\'ın birliğini doğrulayanın işlerini kolaylaştırırız.'),
  ('tr.diyanet', 92, 8, 'Ama, cimrilik eden, kendini Allah\'tan müstağni sayan, en güzel sözü yalanlayan kimsenin güçlüğe uğramasını kolaylaştırırız.'),
  ('tr.diyanet', 92, 9, 'Ama, cimrilik eden, kendini Allah\'tan müstağni sayan, en güzel sözü yalanlayan kimsenin güçlüğe uğramasını kolaylaştırırız.'),
  ('tr.diyanet', 92, 10, 'Ama, cimrilik eden, kendini Allah\'tan müstağni sayan, en güzel sözü yalanlayan kimsenin güçlüğe uğramasını kolaylaştırırız.'),
  ('tr.diyanet', 92, 11, 'O kimse ölüp ateşe yuvarlandığı zaman, malı ona fayda vermez.'),
  ('tr.diyanet', 92, 12, 'Bize düşen sadece doğru yolu göstermektir.'),
  ('tr.diyanet', 92, 13, 'Şüphesiz ahiret de, dünya da Bizimdir.'),
  ('tr.diyanet', 92, 14, 'Sizi alevler saçan ateşle uyardım;'),
  ('tr.diyanet', 92, 15, 'Oraya, yalanlayıp yüz çevirmiş olan o en azgından başkası yaslanmaz.'),
  ('tr.diyanet', 92, 16, 'Oraya, yalanlayıp yüz çevirmiş olan o en azgından başkası yaslanmaz.'),
  ('tr.diyanet', 92, 17, 'Arınmak için malını veren, en çok sakınan kimse ise ondan uzak tutulur.'),
  ('tr.diyanet', 92, 18, 'Arınmak için malını veren, en çok sakınan kimse ise ondan uzak tutulur.'),
  ('tr.diyanet', 92, 19, 'O yaptığı iyiliği birinden karşılık görmek için değil, ancak yüce Rabbinin hoşnudluğunu (rızasını) gözeterek yapmıştır.'),
  ('tr.diyanet', 92, 20, 'O yaptığı iyiliği birinden karşılık görmek için değil, ancak yüce Rabbinin hoşnudluğunu (rızasını) gözeterek yapmıştır.'),
  ('tr.diyanet', 92, 21, 'Elbette kendisi de hoşnut (razı) olacaktır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 92, 1, 'Demi malam apabila menutupi (cahaya siang),'),
  ('id.indonesian', 92, 2, 'dan siang apabila terang benderang,'),
  ('id.indonesian', 92, 3, 'dan penciptaan laki-laki dan perempuan,'),
  ('id.indonesian', 92, 4, 'sesungguhnya usaha kamu memang berbeda-beda.'),
  ('id.indonesian', 92, 5, 'Adapun orang yang memberikan (hartanya di jalan Allah) dan bertakwa,'),
  ('id.indonesian', 92, 6, 'dan membenarkan adanya pahala yang terbaik (surga),'),
  ('id.indonesian', 92, 7, 'maka Kami kelak akan menyiapkan baginya jalan yang mudah.'),
  ('id.indonesian', 92, 8, 'Dan adapun orang-orang yang bakhil dan merasa dirinya cukup,'),
  ('id.indonesian', 92, 9, 'serta mendustakan pahala terbaik,'),
  ('id.indonesian', 92, 10, 'maka kelak Kami akan menyiapkan baginya (jalan) yang sukar.'),
  ('id.indonesian', 92, 11, 'Dan hartanya tidak bermanfaat baginya apabila ia telah binasa.'),
  ('id.indonesian', 92, 12, 'Sesungguhnya kewajiban Kamilah memberi petunjuk,'),
  ('id.indonesian', 92, 13, 'dan sesungguhnya kepunyaan Kamilah akhirat dan dunia.'),
  ('id.indonesian', 92, 14, 'Maka, kami memperingatkan kamu dengan neraka yang menyala-nyala.'),
  ('id.indonesian', 92, 15, 'Tidak ada yang masuk ke dalamnya kecuali orang yang paling celaka,'),
  ('id.indonesian', 92, 16, 'yang mendustakan (kebenaran) dan berpaling (dari iman).'),
  ('id.indonesian', 92, 17, 'Dan kelak akan dijauhkan orang yang paling takwa dari neraka itu,'),
  ('id.indonesian', 92, 18, 'yang menafkahkan hartanya (di jalan Allah) untuk membersihkannya,'),
  ('id.indonesian', 92, 19, 'padahal tidak ada seseorangpun memberikan suatu nikmat kepadanya yang harus dibalasnya,'),
  ('id.indonesian', 92, 20, 'tetapi (dia memberikan itu semata-mata) karena mencari keridhaan Tuhannya yang Maha Tinggi.'),
  ('id.indonesian', 92, 21, 'Dan kelak dia benar-benar mendapat kepuasan.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 93, 1, 'By the morning brightness'),
  ('en.sahih', 93, 2, 'And [by] the night when it covers with darkness,'),
  ('en.sahih', 93, 3, 'Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you].'),
  ('en.sahih', 93, 4, 'And the Hereafter is better for you than the first [life].'),
  ('en.sahih', 93, 5, 'And your Lord is going to give you, and you will be satisfied.'),
  ('en.sahih', 93, 6, 'Did He not find you an orphan and give [you] refuge?'),
  ('en.sahih', 93, 7, 'And He found you lost and guided [you],'),
  ('en.sahih', 93, 8, 'And He found you poor and made [you] self-sufficient.'),
  ('en.sahih', 93, 9, 'So as for the orphan, do not oppress [him].'),
  ('en.sahih', 93, 10, 'And as for the petitioner, do not repel [him].'),
  ('en.sahih', 93, 11, 'But as for the favor of your Lord, report [it].')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 93, 1, 'শপথ পূর্বাহ্নের,'),
  ('bn.bengali', 93, 2, 'শপথ রাত্রির যখন তা গভীর হয়,'),
  ('bn.bengali', 93, 3, 'আপনার পালনকর্তা আপনাকে ত্যাগ করেনি এবং আপনার প্রতি বিরূপও হননি।'),
  ('bn.bengali', 93, 4, 'আপনার জন্যে পরকাল ইহকাল অপেক্ষা শ্রেয়।'),
  ('bn.bengali', 93, 5, 'আপনার পালনকর্তা সত্বরই আপনাকে দান করবেন, অতঃপর আপনি সন্তুষ্ট হবেন।'),
  ('bn.bengali', 93, 6, 'তিনি কি আপনাকে এতীমরূপে পাননি? অতঃপর তিনি আশ্রয় দিয়েছেন।'),
  ('bn.bengali', 93, 7, 'তিনি আপনাকে পেয়েছেন পথহারা, অতঃপর পথপ্রদর্শন করেছেন।'),
  ('bn.bengali', 93, 8, 'তিনি আপনাকে পেয়েছেন নিঃস্ব, অতঃপর অভাবমুক্ত করেছেন।'),
  ('bn.bengali', 93, 9, 'সুতরাং আপনি এতীমের প্রতি কঠোর হবেন না;'),
  ('bn.bengali', 93, 10, 'সওয়ালকারীকে ধমক দেবেন না।'),
  ('bn.bengali', 93, 11, 'এবং আপনার পালনকর্তার নেয়ামতের কথা প্রকাশ করুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 93, 1, 'By the morning hours'),
  ('en.pickthall', 93, 2, 'And by the night when it is stillest,'),
  ('en.pickthall', 93, 3, 'Thy Lord hath not forsaken thee nor doth He hate thee,'),
  ('en.pickthall', 93, 4, 'And verily the latter portion will be better for thee than the former,'),
  ('en.pickthall', 93, 5, 'And verily thy Lord will give unto thee so that thou wilt be content.'),
  ('en.pickthall', 93, 6, 'Did He not find thee an orphan and protect (thee)?'),
  ('en.pickthall', 93, 7, 'Did He not find thee wandering and direct (thee)?'),
  ('en.pickthall', 93, 8, 'Did He not find thee destitute and enrich (thee)?'),
  ('en.pickthall', 93, 9, 'Therefor the orphan oppress not,'),
  ('en.pickthall', 93, 10, 'Therefor the beggar drive not away,'),
  ('en.pickthall', 93, 11, 'Therefor of the bounty of thy Lord be thy discourse.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 93, 1, 'By the Glorious Morning Light,'),
  ('en.yusufali', 93, 2, 'And by the Night when it is still,-'),
  ('en.yusufali', 93, 3, 'Thy Guardian-Lord hath not forsaken thee, nor is He displeased.'),
  ('en.yusufali', 93, 4, 'And verily the Hereafter will be better for thee than the present.'),
  ('en.yusufali', 93, 5, 'And soon will thy Guardian-Lord give thee (that wherewith) thou shalt be well-pleased.'),
  ('en.yusufali', 93, 6, 'Did He not find thee an orphan and give thee shelter (and care)?'),
  ('en.yusufali', 93, 7, 'And He found thee wandering, and He gave thee guidance.'),
  ('en.yusufali', 93, 8, 'And He found thee in need, and made thee independent.'),
  ('en.yusufali', 93, 9, 'Therefore, treat not the orphan with harshness,'),
  ('en.yusufali', 93, 10, 'Nor repulse the petitioner (unheard);'),
  ('en.yusufali', 93, 11, 'But the bounty of the Lord - rehearse and proclaim!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 93, 1, 'Wad duhaa'),
  ('en.transliteration', 93, 2, 'Wal laili iza sajaa'),
  ('en.transliteration', 93, 3, 'Ma wad da\'aka rabbuka wa ma qalaa'),
  ('en.transliteration', 93, 4, 'Walal-aakhiratu khairul laka minal-oola'),
  ('en.transliteration', 93, 5, 'Wa la sawfa y\'uteeka rabbuka fatarda'),
  ('en.transliteration', 93, 6, 'Alam ya jidka yateeman fa aawaa'),
  ('en.transliteration', 93, 7, 'Wa wa jadaka daal lan fahada'),
  ('en.transliteration', 93, 8, 'Wa wa jadaka \'aa-ilan fa aghnaa'),
  ('en.transliteration', 93, 9, 'Fa am mal yateema fala taqhar'),
  ('en.transliteration', 93, 10, 'Wa am mas saa-ila fala tanhar'),
  ('en.transliteration', 93, 11, 'Wa amma bi ni\'mati rabbika fahad dith')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 93, 1, 'دن کی روشنی کی قسم ہے'),
  ('ur.ahmedali', 93, 2, 'اور رات کی جب وہ چھا جائے'),
  ('ur.ahmedali', 93, 3, 'آپ کے رب نے نہ آپ کو چھوڑا ہے اور نہ بیزار ہوا ہے'),
  ('ur.ahmedali', 93, 4, 'اور البتہ آخرت آپ کے لیے دنیا سے بہتر ہے'),
  ('ur.ahmedali', 93, 5, 'اور آپ کا رب آپ کو (اتنا) دے گا کہ آپ خوش ہو جائیں گے'),
  ('ur.ahmedali', 93, 6, 'کیا اس نے آپ کو یتیم نہیں پایا تھا پھر جگہ دی'),
  ('ur.ahmedali', 93, 7, 'اور آپ کو (شریعت سے) بے خبر پایا پھر (شریعت کا) راستہ بتایا'),
  ('ur.ahmedali', 93, 8, 'اوراس نے آپ کو تنگدست پایا پھر غنی کر دیا'),
  ('ur.ahmedali', 93, 9, 'پھر یتیم کو دبایا نہ کرو'),
  ('ur.ahmedali', 93, 10, 'اورسائل کو جھڑکا نہ کرو'),
  ('ur.ahmedali', 93, 11, 'اورہر حال میں اپنے رب کے احسان کا ذکر کیا کرو')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 93, 1, 'Kuşluk vaktine and olsun;'),
  ('tr.diyanet', 93, 2, 'Sükun erdiği zaman geceye and olsun ki,'),
  ('tr.diyanet', 93, 3, 'Rabbin seni ne bıraktı ve ne de sana darıldı.'),
  ('tr.diyanet', 93, 4, 'Doğrusu ahiret senin için dünyadan daha hayırlıdır.'),
  ('tr.diyanet', 93, 5, 'Rabbin şüphesiz sana verecek ve sen de hoşnut olacaksın.'),
  ('tr.diyanet', 93, 6, 'Seni öksüz bulup da barındırmadı mı?'),
  ('tr.diyanet', 93, 7, 'Seni şaşırmış bulup, doğru yola eriştirmedi mi?'),
  ('tr.diyanet', 93, 8, 'Seni fakir bulup zenginleştirmedi mi?'),
  ('tr.diyanet', 93, 9, 'Öyleyse sakın öksüze kötü muamele etme;'),
  ('tr.diyanet', 93, 10, 'Ve sakın bir şey isteyeni azarlama;'),
  ('tr.diyanet', 93, 11, 'Yalnızca Rabbinin nimetini anlat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 93, 1, 'Demi waktu matahari sepenggalahan naik,'),
  ('id.indonesian', 93, 2, 'dan demi malam apabila telah sunyi (gelap),'),
  ('id.indonesian', 93, 3, 'Tuhanmu tiada meninggalkan kamu dan tiada (pula) benci kepadamu.'),
  ('id.indonesian', 93, 4, 'Dan sesungguhnya hari kemudian itu lebih baik bagimu daripada yang sekarang (permulaan).'),
  ('id.indonesian', 93, 5, 'Dan kelak Tuhanmu pasti memberikan karunia-Nya kepadamu, lalu (hati) kamu menjadi puas.'),
  ('id.indonesian', 93, 6, 'Bukankah Dia mendapatimu sebagai seorang yatim, lalu Dia melindungimu?'),
  ('id.indonesian', 93, 7, 'Dan Dia mendapatimu sebagai seorang yang bingung, lalu Dia memberikan petunjuk.'),
  ('id.indonesian', 93, 8, 'Dan Dia mendapatimu sebagai seorang yang kekurangan, lalu Dia memberikan kecukupan.'),
  ('id.indonesian', 93, 9, 'Sebab itu, terhadap anak yatim janganlah kamu berlaku sewenang-wenang.'),
  ('id.indonesian', 93, 10, 'Dan terhadap orang yang minta-minta, janganlah kamu menghardiknya.'),
  ('id.indonesian', 93, 11, 'Dan terhadap nikmat Tuhanmu, maka hendaklah kamu siarkan.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 94, 1, 'Did We not expand for you, [O Muhammad], your breast?'),
  ('en.sahih', 94, 2, 'And We removed from you your burden'),
  ('en.sahih', 94, 3, 'Which had weighed upon your back'),
  ('en.sahih', 94, 4, 'And raised high for you your repute.'),
  ('en.sahih', 94, 5, 'For indeed, with hardship [will be] ease.'),
  ('en.sahih', 94, 6, 'Indeed, with hardship [will be] ease.'),
  ('en.sahih', 94, 7, 'So when you have finished [your duties], then stand up [for worship].'),
  ('en.sahih', 94, 8, 'And to your Lord direct [your] longing.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 94, 1, 'আমি কি আপনার বক্ষ উম্মুক্ত করে দেইনি?'),
  ('bn.bengali', 94, 2, 'আমি লাঘব করেছি আপনার বোঝা,'),
  ('bn.bengali', 94, 3, 'যা ছিল আপনার জন্যে অতিশয় দুঃসহ।'),
  ('bn.bengali', 94, 4, 'আমি আপনার আলোচনাকে সমুচ্চ করেছি।'),
  ('bn.bengali', 94, 5, 'নিশ্চয় কষ্টের সাথে স্বস্তি রয়েছে।'),
  ('bn.bengali', 94, 6, 'নিশ্চয় কষ্টের সাথে স্বস্তি রয়েছে।'),
  ('bn.bengali', 94, 7, 'অতএব, যখন অবসর পান পরিশ্রম করুন।'),
  ('bn.bengali', 94, 8, 'এবং আপনার পালনকর্তার প্রতি মনোনিবেশ করুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 94, 1, 'Have We not caused thy bosom to dilate,'),
  ('en.pickthall', 94, 2, 'And eased thee of the burden'),
  ('en.pickthall', 94, 3, 'Which weighed down thy back;'),
  ('en.pickthall', 94, 4, 'And exalted thy fame?'),
  ('en.pickthall', 94, 5, 'But lo! with hardship goeth ease,'),
  ('en.pickthall', 94, 6, 'Lo! with hardship goeth ease;'),
  ('en.pickthall', 94, 7, 'So when thou art relieved, still toil'),
  ('en.pickthall', 94, 8, 'And strive to please thy Lord.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 94, 1, 'Have We not expanded thee thy breast?-'),
  ('en.yusufali', 94, 2, 'And removed from thee thy burden'),
  ('en.yusufali', 94, 3, 'The which did gall thy back?-'),
  ('en.yusufali', 94, 4, 'And raised high the esteem (in which) thou (art held)?'),
  ('en.yusufali', 94, 5, 'So, verily, with every difficulty, there is relief:'),
  ('en.yusufali', 94, 6, 'Verily, with every difficulty there is relief.'),
  ('en.yusufali', 94, 7, 'Therefore, when thou art free (from thine immediate task), still labour hard,'),
  ('en.yusufali', 94, 8, 'And to thy Lord turn (all) thy attention.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 94, 1, 'Alam nashrah laka sadrak'),
  ('en.transliteration', 94, 2, 'Wa wa d\'ana \'anka wizrak'),
  ('en.transliteration', 94, 3, 'Allazee anqada zahrak'),
  ('en.transliteration', 94, 4, 'Wa raf \'ana laka zikrak'),
  ('en.transliteration', 94, 5, 'Fa inna ma\'al usri yusra'),
  ('en.transliteration', 94, 6, 'Inna ma\'al \'usri yusra'),
  ('en.transliteration', 94, 7, 'Fa iza faragh ta fansab'),
  ('en.transliteration', 94, 8, 'Wa ilaa rabbika far ghab')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 94, 1, 'کیا ہم نے آپ کا سینہ نہیں کھول دیا'),
  ('ur.ahmedali', 94, 2, 'اور کیا آپ سے آپ کا وہ بوجھ نہیں اتار دیا'),
  ('ur.ahmedali', 94, 3, 'جس نے آپ کی کمر جھکا دی تھی'),
  ('ur.ahmedali', 94, 4, 'اور ہم نے آپ کا ذکر بلند کر دیا'),
  ('ur.ahmedali', 94, 5, 'پس بے شک ہر مشکل کے ساتھ آسانی ہے'),
  ('ur.ahmedali', 94, 6, 'بے شک ہر مشکل کے ساتھ آسانی ہے'),
  ('ur.ahmedali', 94, 7, 'پس جب آپ (تبلیغ احکام سے) فارغ ہوں تو ریاضت کیجئے'),
  ('ur.ahmedali', 94, 8, 'اور اپنے رب کی طرف دل لگائیے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 94, 1, 'Senin gönlünü açmadık mı?'),
  ('tr.diyanet', 94, 2, 'Belini büken yükünü üzerinden almadık mı?'),
  ('tr.diyanet', 94, 3, 'Belini büken yükünü üzerinden almadık mı?'),
  ('tr.diyanet', 94, 4, 'Senin şanını yükseltmedik mi?'),
  ('tr.diyanet', 94, 5, 'Elbette güçlükle beraber şüphesiz bir kolaylık vardır.'),
  ('tr.diyanet', 94, 6, 'Gerçekten, güçlükle beraber bir kolaylık vardır.'),
  ('tr.diyanet', 94, 7, 'Öyleyse, bir işi bitirince diğerine giriş;'),
  ('tr.diyanet', 94, 8, 'Ve ümit edeceğini yalnız Rabbinden iste.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 94, 1, 'Bukankah Kami telah melapangkan untukmu dadamu?,'),
  ('id.indonesian', 94, 2, 'dan Kami telah menghilangkan daripadamu bebanmu,'),
  ('id.indonesian', 94, 3, 'yang memberatkan punggungmu?'),
  ('id.indonesian', 94, 4, 'Dan Kami tinggikan bagimu sebutan (nama)mu,'),
  ('id.indonesian', 94, 5, 'Karena sesungguhnya sesudah kesulitan itu ada kemudahan,'),
  ('id.indonesian', 94, 6, 'sesungguhnya sesudah kesulitan itu ada kemudahan.'),
  ('id.indonesian', 94, 7, 'Maka apabila kamu telah selesai (dari sesuatu urusan), kerjakanlah dengan sungguh-sungguh (urusan) yang lain,'),
  ('id.indonesian', 94, 8, 'dan hanya kepada Tuhanmulah hendaknya kamu berharap.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 95, 1, 'By the fig and the olive'),
  ('en.sahih', 95, 2, 'And [by] Mount Sinai'),
  ('en.sahih', 95, 3, 'And [by] this secure city [Makkah],'),
  ('en.sahih', 95, 4, 'We have certainly created man in the best of stature;'),
  ('en.sahih', 95, 5, 'Then We return him to the lowest of the low,'),
  ('en.sahih', 95, 6, 'Except for those who believe and do righteous deeds, for they will have a reward uninterrupted.'),
  ('en.sahih', 95, 7, 'So what yet causes you to deny the Recompense?'),
  ('en.sahih', 95, 8, 'Is not Allah the most just of judges?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 95, 1, 'শপথ আঞ্জীর (ডুমুর) ও যয়তুনের,'),
  ('bn.bengali', 95, 2, 'এবং সিনাই প্রান্তরস্থ তূর পর্বতের,'),
  ('bn.bengali', 95, 3, 'এবং এই নিরাপদ নগরীর।'),
  ('bn.bengali', 95, 4, 'আমি সৃষ্টি করেছি মানুষকে সুন্দরতর অবয়বে।'),
  ('bn.bengali', 95, 5, 'অতঃপর তাকে ফিরিয়ে দিয়েছি নীচ থেকে নীচে।'),
  ('bn.bengali', 95, 6, 'কিন্তু যারা বিশ্বাস স্থাপন করেছে ও সৎকর্ম করেছে, তাদের জন্যে রয়েছে অশেষ পুরস্কার।'),
  ('bn.bengali', 95, 7, 'অতঃপর কেন তুমি অবিশ্বাস করছ কেয়ামতকে?'),
  ('bn.bengali', 95, 8, 'আল্লাহ কি বিচারকদের মধ্যে শ্রেষ্টতম বিচারক নন?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 95, 1, 'By the fig and the olive,'),
  ('en.pickthall', 95, 2, 'By Mount Sinai,'),
  ('en.pickthall', 95, 3, 'And by this land made safe;'),
  ('en.pickthall', 95, 4, 'Surely We created man of the best stature'),
  ('en.pickthall', 95, 5, 'Then we reduced him to the lowest of the low,'),
  ('en.pickthall', 95, 6, 'Save those who believe and do good works, and theirs is a reward unfailing.'),
  ('en.pickthall', 95, 7, 'So who henceforth will give the lie to thee about the judgment?'),
  ('en.pickthall', 95, 8, 'Is not Allah the most conclusive of all judges?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 95, 1, 'By the Fig and the Olive,'),
  ('en.yusufali', 95, 2, 'And the Mount of Sinai,'),
  ('en.yusufali', 95, 3, 'And this City of security,-'),
  ('en.yusufali', 95, 4, 'We have indeed created man in the best of moulds,'),
  ('en.yusufali', 95, 5, 'Then do We abase him (to be) the lowest of the low,-'),
  ('en.yusufali', 95, 6, 'Except such as believe and do righteous deeds: For they shall have a reward unfailing.'),
  ('en.yusufali', 95, 7, 'Then what can, after this, contradict thee, as to the judgment (to come)?'),
  ('en.yusufali', 95, 8, 'Is not Allah the wisest of judges?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 95, 1, 'Wat teeni waz zaitoon'),
  ('en.transliteration', 95, 2, 'Wa toori sineen'),
  ('en.transliteration', 95, 3, 'Wa haazal balad-il ameen'),
  ('en.transliteration', 95, 4, 'Laqad khalaqnal insaana fee ahsani taqweem'),
  ('en.transliteration', 95, 5, 'Thumma ra dad naahu asfala saafileen'),
  ('en.transliteration', 95, 6, 'Ill-lal lazeena aamanoo wa \'amilus saalihaati; falahum ajrun ghairu mamnoon'),
  ('en.transliteration', 95, 7, 'Fama yu kaz zibuka b\'adu bid deen'),
  ('en.transliteration', 95, 8, 'Alai sal laahu bi-ahkamil haakimeen')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 95, 1, 'انجیر اور زیتون کی قسم ہے'),
  ('ur.ahmedali', 95, 2, 'اور طور سینا کی'),
  ('ur.ahmedali', 95, 3, 'اور اس شہر (مکہ) کی جو امن والا ہے'),
  ('ur.ahmedali', 95, 4, 'بے شک ہم نے انسان کو بڑے عمدہ انداز میں پیدا کیا ہے'),
  ('ur.ahmedali', 95, 5, 'پھر ہم نے اسے سب سے نیچے پھینک دیا ہے'),
  ('ur.ahmedali', 95, 6, 'مگر جو ایمان لائے اور نیک کام کئے سو ان کے لیے تو بے انتہا بدلہ ہے'),
  ('ur.ahmedali', 95, 7, 'پھر اس کے بعد آپ کو قیامت کے معاملہ میں کون جھٹلا سکتا ہے'),
  ('ur.ahmedali', 95, 8, 'کیا الله سب حاکموں سے بڑا حاکم نہیں (ضرور ہے)')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 95, 1, 'İncir ve zeytine and olsun,'),
  ('tr.diyanet', 95, 2, 'And olsun Sina dağına,'),
  ('tr.diyanet', 95, 3, 'And olsun bu güvenli Mekke şehrine ki:'),
  ('tr.diyanet', 95, 4, 'Biz insanı en güzel şekilde yarattık,'),
  ('tr.diyanet', 95, 5, 'Sonra onu aşağıların en aşağısı kıldık.'),
  ('tr.diyanet', 95, 6, 'Yalnız, inanıp yararlı iş işleyenler bunun dışındadır. Onlara kesintisiz ecir vardır.'),
  ('tr.diyanet', 95, 7, 'Öyleyken, sana dini yalan saydırtan nedir?'),
  ('tr.diyanet', 95, 8, 'Allah, hükmedenlerin en iyi hükmedeni değil midir?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 95, 1, 'Demi (buah) Tin dan (buah) Zaitun,'),
  ('id.indonesian', 95, 2, 'dan demi bukit Sinai,'),
  ('id.indonesian', 95, 3, 'dan demi kota (Mekah) ini yang aman,'),
  ('id.indonesian', 95, 4, 'sesungguhnya Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya.'),
  ('id.indonesian', 95, 5, 'Kemudian Kami kembalikan dia ke tempat yang serendah-rendahnya (neraka),'),
  ('id.indonesian', 95, 6, 'kecuali orang-orang yang beriman dan mengerjakan amal saleh; maka bagi mereka pahala yang tiada putus-putusnya.'),
  ('id.indonesian', 95, 7, 'Maka apakah yang menyebabkan kamu mendustakan (hari) pembalasan sesudah (adanya keterangan-keterangan) itu?'),
  ('id.indonesian', 95, 8, 'Bukankah Allah Hakim yang seadil-adilnya?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 96, 1, 'Recite in the name of your Lord who created -'),
  ('en.sahih', 96, 2, 'Created man from a clinging substance.'),
  ('en.sahih', 96, 3, 'Recite, and your Lord is the most Generous -'),
  ('en.sahih', 96, 4, 'Who taught by the pen -'),
  ('en.sahih', 96, 5, 'Taught man that which he knew not.'),
  ('en.sahih', 96, 6, 'No! [But] indeed, man transgresses'),
  ('en.sahih', 96, 7, 'Because he sees himself self-sufficient.'),
  ('en.sahih', 96, 8, 'Indeed, to your Lord is the return.'),
  ('en.sahih', 96, 9, 'Have you seen the one who forbids'),
  ('en.sahih', 96, 10, 'A servant when he prays?'),
  ('en.sahih', 96, 11, 'Have you seen if he is upon guidance'),
  ('en.sahih', 96, 12, 'Or enjoins righteousness?'),
  ('en.sahih', 96, 13, 'Have you seen if he denies and turns away -'),
  ('en.sahih', 96, 14, 'Does he not know that Allah sees?'),
  ('en.sahih', 96, 15, 'No! If he does not desist, We will surely drag him by the forelock -'),
  ('en.sahih', 96, 16, 'A lying, sinning forelock.'),
  ('en.sahih', 96, 17, 'Then let him call his associates;'),
  ('en.sahih', 96, 18, 'We will call the angels of Hell.'),
  ('en.sahih', 96, 19, 'No! Do not obey him. But prostrate and draw near [to Allah].')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 96, 1, 'পাঠ করুন আপনার পালনকর্তার নামে যিনি সৃষ্টি করেছেন'),
  ('bn.bengali', 96, 2, 'সৃষ্টি করেছেন মানুষকে জমাট রক্ত থেকে।'),
  ('bn.bengali', 96, 3, 'পাঠ করুন, আপনার পালনকর্তা মহা দয়ালু,'),
  ('bn.bengali', 96, 4, 'যিনি কলমের সাহায্যে শিক্ষা দিয়েছেন,'),
  ('bn.bengali', 96, 5, 'শিক্ষা দিয়েছেন মানুষকে যা সে জানত না।'),
  ('bn.bengali', 96, 6, 'সত্যি সত্যি মানুষ সীমালংঘন করে,'),
  ('bn.bengali', 96, 7, 'এ কারণে যে, সে নিজেকে অভাবমুক্ত মনে করে।'),
  ('bn.bengali', 96, 8, 'নিশ্চয় আপনার পালনকর্তার দিকেই প্রত্যাবর্তন হবে।'),
  ('bn.bengali', 96, 9, 'আপনি কি তাকে দেখেছেন, যে নিষেধ করে'),
  ('bn.bengali', 96, 10, 'এক বান্দাকে যখন সে নামায পড়ে?'),
  ('bn.bengali', 96, 11, 'আপনি কি দেখেছেন যদি সে সৎপথে থাকে।'),
  ('bn.bengali', 96, 12, 'অথবা খোদাভীতি শিক্ষা দেয়।'),
  ('bn.bengali', 96, 13, 'আপনি কি দেখেছেন, যদি সে মিথ্যারোপ করে ও মুখ ফিরিয়ে নেয়।'),
  ('bn.bengali', 96, 14, 'সে কি জানে না যে, আল্লাহ দেখেন?'),
  ('bn.bengali', 96, 15, 'কখনই নয়, যদি সে বিরত না হয়, তবে আমি মস্তকের সামনের কেশগুচ্ছ ধরে হেঁচড়াবই-'),
  ('bn.bengali', 96, 16, 'মিথ্যাচারী, পাপীর কেশগুচ্ছ।'),
  ('bn.bengali', 96, 17, 'অতএব, সে তার সভাসদদেরকে আহবান করুক।'),
  ('bn.bengali', 96, 18, 'আমিও আহবান করব জাহান্নামের প্রহরীদেরকে'),
  ('bn.bengali', 96, 19, 'কখনই নয়, আপনি তার আনুগত্য করবেন না। আপনি সেজদা করুন ও আমার নৈকট্য অর্জন করুন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 96, 1, 'Read: In the name of thy Lord Who createth,'),
  ('en.pickthall', 96, 2, 'Createth man from a clot.'),
  ('en.pickthall', 96, 3, 'Read: And thy Lord is the Most Bounteous,'),
  ('en.pickthall', 96, 4, 'Who teacheth by the pen,'),
  ('en.pickthall', 96, 5, 'Teacheth man that which he knew not.'),
  ('en.pickthall', 96, 6, 'Nay, but verily man is rebellious'),
  ('en.pickthall', 96, 7, 'That he thinketh himself independent!'),
  ('en.pickthall', 96, 8, 'Lo! unto thy Lord is the return.'),
  ('en.pickthall', 96, 9, 'Hast thou seen him who dissuadeth'),
  ('en.pickthall', 96, 10, 'A slave when he prayeth?'),
  ('en.pickthall', 96, 11, 'Hast thou seen if he relieth on the guidance (of Allah)'),
  ('en.pickthall', 96, 12, 'Or enjoineth piety?'),
  ('en.pickthall', 96, 13, 'Hast thou seen if he denieth (Allah\'s guidance) and is froward?'),
  ('en.pickthall', 96, 14, 'Is he then unaware that Allah seeth?'),
  ('en.pickthall', 96, 15, 'Nay, but if he cease not We will seize him by the forelock -'),
  ('en.pickthall', 96, 16, 'The lying, sinful forelock -'),
  ('en.pickthall', 96, 17, 'Then let him call upon his henchmen!'),
  ('en.pickthall', 96, 18, 'We will call the guards of hell.'),
  ('en.pickthall', 96, 19, 'Nay, Obey not thou him. But prostrate thyself, and draw near (unto Allah).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 96, 1, 'Proclaim! (or read!) in the name of thy Lord and Cherisher, Who created-'),
  ('en.yusufali', 96, 2, 'Created man, out of a (mere) clot of congealed blood:'),
  ('en.yusufali', 96, 3, 'Proclaim! And thy Lord is Most Bountiful,-'),
  ('en.yusufali', 96, 4, 'He Who taught (the use of) the pen,-'),
  ('en.yusufali', 96, 5, 'Taught man that which he knew not.'),
  ('en.yusufali', 96, 6, 'Nay, but man doth transgress all bounds,'),
  ('en.yusufali', 96, 7, 'In that he looketh upon himself as self-sufficient.'),
  ('en.yusufali', 96, 8, 'Verily, to thy Lord is the return (of all).'),
  ('en.yusufali', 96, 9, 'Seest thou one who forbids-'),
  ('en.yusufali', 96, 10, 'A votary when he (turns) to pray?'),
  ('en.yusufali', 96, 11, 'Seest thou if he is on (the road of) Guidance?-'),
  ('en.yusufali', 96, 12, 'Or enjoins Righteousness?'),
  ('en.yusufali', 96, 13, 'Seest thou if he denies (Truth) and turns away?'),
  ('en.yusufali', 96, 14, 'Knoweth he not that Allah doth see?'),
  ('en.yusufali', 96, 15, 'Let him beware! If he desist not, We will drag him by the forelock,-'),
  ('en.yusufali', 96, 16, 'A lying, sinful forelock!'),
  ('en.yusufali', 96, 17, 'Then, let him call (for help) to his council (of comrades):'),
  ('en.yusufali', 96, 18, 'We will call on the angels of punishment (to deal with him)!'),
  ('en.yusufali', 96, 19, 'Nay, heed him not: But bow down in adoration, and bring thyself the closer (to Allah)!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 96, 1, 'Iqra bismi rab bikal lazee khalaq'),
  ('en.transliteration', 96, 2, 'Khalaqal insaana min \'alaq'),
  ('en.transliteration', 96, 3, 'Iqra wa rab bukal akram'),
  ('en.transliteration', 96, 4, 'Al lazee \'allama bil qalam'),
  ('en.transliteration', 96, 5, '\'Al lamal insaana ma lam y\'alam'),
  ('en.transliteration', 96, 6, 'Kallaa innal insaana layatghaa'),
  ('en.transliteration', 96, 7, 'Ar-ra aahus taghnaa'),
  ('en.transliteration', 96, 8, 'Innna ilaa rabbikar ruj\'aa'),
  ('en.transliteration', 96, 9, 'Ara-aital lazee yanhaa'),
  ('en.transliteration', 96, 10, '\'Abdan iza sallaa'),
  ('en.transliteration', 96, 11, 'Ara-aita in kana \'alal hudaa'),
  ('en.transliteration', 96, 12, 'Au amara bit taqwaa'),
  ('en.transliteration', 96, 13, 'Ara-aita in kaz zaba wa ta walla'),
  ('en.transliteration', 96, 14, 'Alam y\'alam bi-an nal lahaa yaraa'),
  ('en.transliteration', 96, 15, 'Kalla la illam yantahi la nasfa\'am bin nasiyah'),
  ('en.transliteration', 96, 16, 'Nasiyatin kazi batin khaatiyah'),
  ('en.transliteration', 96, 17, 'Fal yad\'u naadiyah'),
  ('en.transliteration', 96, 18, 'Sanad \'uz zabaaniyah'),
  ('en.transliteration', 96, 19, 'Kalla; la tuti\'hu wasjud waqtarib')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 96, 1, 'اپنے رب کے نام سے پڑھیئے جس نے سب کو پیدا کیا'),
  ('ur.ahmedali', 96, 2, 'انسان کو خون بستہ سے پیدا کیا'),
  ('ur.ahmedali', 96, 3, 'پڑھیئے اور آپ کا رب سب سے بڑھ کر کرم والا ہے'),
  ('ur.ahmedali', 96, 4, 'جس نے قلم سے سکھایا'),
  ('ur.ahmedali', 96, 5, 'انسان کو سکھایا جو وہ نہ جانتا تھا'),
  ('ur.ahmedali', 96, 6, 'ہرگز نہیں بے شک آدمی سرکش ہو جاتا ہے'),
  ('ur.ahmedali', 96, 7, 'جب کہ اپنے آپ کو غنی پاتا ہے'),
  ('ur.ahmedali', 96, 8, 'بے شک آپ کے رب ہی کی طرف لوٹ کر جانا ہے'),
  ('ur.ahmedali', 96, 9, 'کیا آپ نے اس کو دیکھا جو منع کرتا ہے'),
  ('ur.ahmedali', 96, 10, 'ایک بندے کو جب کہ وہ نماز پڑھتا ہے'),
  ('ur.ahmedali', 96, 11, 'بھلا دیکھو تو سہی اگر وہ راہ پر ہوتا'),
  ('ur.ahmedali', 96, 12, 'یا پرہیز گاری سکھاتا'),
  ('ur.ahmedali', 96, 13, 'بھلا دیکھو تو سہی اگر اس نے جھٹلایا اور منہ موڑ لیا'),
  ('ur.ahmedali', 96, 14, 'تو کیا وہ نہیں جانتا کہ الله دیکھ رہا ہے'),
  ('ur.ahmedali', 96, 15, 'ہرگزایسا نہیں چاہیئے اگر وہ باز نہ آیا تو ہم پیشانی کے بال پکڑ کر گھسیٹیں گے'),
  ('ur.ahmedali', 96, 16, 'پیشانی جھوٹی خطا کار'),
  ('ur.ahmedali', 96, 17, 'پس وہ اپنے مجلس والوں کو بلا لے'),
  ('ur.ahmedali', 96, 18, 'ہم بھی مؤکلین دوزخ کو بلا لیں گے'),
  ('ur.ahmedali', 96, 19, 'ہر گز ایسا نہیں چاہیئے آپ اس کا کہانہ مانیے اور سجدہ کیجیئے اور قرب حاصل کیجیئے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 96, 1, 'Yaratan Rabbinin adıyla oku!'),
  ('tr.diyanet', 96, 2, 'O, insanı pıhtılaşmış kandan (alak\'tan) yarattı.'),
  ('tr.diyanet', 96, 3, 'Oku! Kalemle öğreten, insana bilmediğini bildiren Rabbin, en büyük kerem sahibidir.'),
  ('tr.diyanet', 96, 4, 'Oku! Kalemle öğreten, insana bilmediğini bildiren Rabbin, en büyük kerem sahibidir.'),
  ('tr.diyanet', 96, 5, 'Oku! Kalemle öğreten, insana bilmediğini bildiren Rabbin, en büyük kerem sahibidir.'),
  ('tr.diyanet', 96, 6, 'Ama, insanoğlu kendini müstağni sayarak azgınlık eder.'),
  ('tr.diyanet', 96, 7, 'Ama, insanoğlu kendini müstağni sayarak azgınlık eder.'),
  ('tr.diyanet', 96, 8, 'Dönüş şüphesiz Rabbinedir.'),
  ('tr.diyanet', 96, 9, 'Sen, namaz kılan kulu bundan menedeni gördün mü?'),
  ('tr.diyanet', 96, 10, 'Sen, namaz kılan kulu bundan menedeni gördün mü?'),
  ('tr.diyanet', 96, 11, 'Söyle bakalım, o kul doğru yolda giden veya Allah\'a karşı gelmekten sakınmayı buyuran bir kimse olsun; veya söyle, yalanlayıp yüz çeviren birisi olsun'),
  ('tr.diyanet', 96, 12, 'Söyle bakalım, o kul doğru yolda giden veya Allah\'a karşı gelmekten sakınmayı buyuran bir kimse olsun; veya söyle, yalanlayıp yüz çeviren birisi olsun'),
  ('tr.diyanet', 96, 13, 'Söyle bakalım, o kul doğru yolda giden veya Allah\'a karşı gelmekten sakınmayı buyuran bir kimse olsun; veya söyle, yalanlayıp yüz çeviren birisi olsun'),
  ('tr.diyanet', 96, 14, 'Allah\'ın her şeyi görmekte olduğunu bilmez mi?'),
  ('tr.diyanet', 96, 15, 'Ama bundan vazgeçmezse, and olsun ki, onu perçeminden,'),
  ('tr.diyanet', 96, 16, 'Yalancı ve günahkar perçeminden cehenneme sürükleriz.'),
  ('tr.diyanet', 96, 17, 'O zaman, kafadarlarını çağırsın,'),
  ('tr.diyanet', 96, 18, 'Biz de zebanileri çağıracağız.'),
  ('tr.diyanet', 96, 19, 'Sakın ona uyma; sen secde et, Rabbine yaklaş.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 96, 1, 'Bacalah dengan (menyebut) nama Tuhanmu Yang menciptakan,'),
  ('id.indonesian', 96, 2, 'Dia telah menciptakan manusia dari segumpal darah.'),
  ('id.indonesian', 96, 3, 'Bacalah, dan Tuhanmulah Yang Maha Pemurah,'),
  ('id.indonesian', 96, 4, 'Yang mengajar (manusia) dengan perantaran kalam,'),
  ('id.indonesian', 96, 5, 'Dia mengajar kepada manusia apa yang tidak diketahuinya.'),
  ('id.indonesian', 96, 6, 'Ketahuilah! Sesungguhnya manusia benar-benar melampaui batas,'),
  ('id.indonesian', 96, 7, 'karena dia melihat dirinya serba cukup.'),
  ('id.indonesian', 96, 8, 'Sesungguhnya hanya kepada Tuhanmulah kembali(mu).'),
  ('id.indonesian', 96, 9, 'Bagaimana pendapatmu tentang orang yang melarang,'),
  ('id.indonesian', 96, 10, 'seorang hamba ketika mengerjakan shalat,'),
  ('id.indonesian', 96, 11, 'bagaimana pendapatmu jika orang yang melarang itu berada di atas kebenaran,'),
  ('id.indonesian', 96, 12, 'atau dia menyuruh bertakwa (kepada Allah)?'),
  ('id.indonesian', 96, 13, 'Bagaimana pendapatmu jika orang yang melarang itu mendustakan dan berpaling?'),
  ('id.indonesian', 96, 14, 'Tidaklah dia mengetahui bahwa sesungguhnya Allah melihat segala perbuatannya?'),
  ('id.indonesian', 96, 15, 'Ketahuilah, sungguh jika dia tidak berhenti (berbuat demikian) niscaya Kami tarik ubun-ubunnya,'),
  ('id.indonesian', 96, 16, '(yaitu) ubun-ubun orang yang mendustakan lagi durhaka.'),
  ('id.indonesian', 96, 17, 'Maka biarlah dia memanggil golongannya (untuk menolongnya),'),
  ('id.indonesian', 96, 18, 'kelak Kami akan memanggil malaikat Zabaniyah,'),
  ('id.indonesian', 96, 19, 'sekali-kali jangan, janganlah kamu patuh kepadanya; dan sujudlah dan dekatkanlah (dirimu kepada Tuhan).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 97, 1, 'Indeed, We sent the Qur\'an down during the Night of Decree.'),
  ('en.sahih', 97, 2, 'And what can make you know what is the Night of Decree?'),
  ('en.sahih', 97, 3, 'The Night of Decree is better than a thousand months.'),
  ('en.sahih', 97, 4, 'The angels and the Spirit descend therein by permission of their Lord for every matter.'),
  ('en.sahih', 97, 5, 'Peace it is until the emergence of dawn.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 97, 1, 'আমি একে নাযিল করেছি শবে-কদরে।'),
  ('bn.bengali', 97, 2, 'শবে-কদর সমন্ধে আপনি কি জানেন?'),
  ('bn.bengali', 97, 3, 'শবে-কদর হল এক হাজার মাস অপেক্ষা শ্রেষ্ঠ।'),
  ('bn.bengali', 97, 4, 'এতে প্রত্যেক কাজের জন্যে ফেরেশতাগণ ও রূহ অবতীর্ণ হয় তাদের পালনকর্তার নির্দেশক্রমে।'),
  ('bn.bengali', 97, 5, 'এটা নিরাপত্তা, যা ফজরের উদয় পর্যন্ত অব্যাহত থাকে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 97, 1, 'Lo! We revealed it on the Night of Predestination.'),
  ('en.pickthall', 97, 2, 'Ah, what will convey unto thee what the Night of Power is!'),
  ('en.pickthall', 97, 3, 'The Night of Power is better than a thousand months.'),
  ('en.pickthall', 97, 4, 'The angels and the Spirit descend therein, by the permission of their Lord, with all decrees.'),
  ('en.pickthall', 97, 5, '(The night is) Peace until the rising of the dawn.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 97, 1, 'We have indeed revealed this (Message) in the Night of Power:'),
  ('en.yusufali', 97, 2, 'And what will explain to thee what the night of power is?'),
  ('en.yusufali', 97, 3, 'The Night of Power is better than a thousand months.'),
  ('en.yusufali', 97, 4, 'Therein come down the angels and the Spirit by Allah\'s permission, on every errand:'),
  ('en.yusufali', 97, 5, 'Peace!... This until the rise of morn!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 97, 1, 'Innaa anzalnaahu fee lailatil qadr'),
  ('en.transliteration', 97, 2, 'Wa maa adraaka ma lailatul qadr'),
  ('en.transliteration', 97, 3, 'Lailatul qadri khairum min alfee shahr'),
  ('en.transliteration', 97, 4, 'Tanaz zalul malaa-ikatu war roohu feeha bi izni-rab bihim min kulli amr'),
  ('en.transliteration', 97, 5, 'Salaamun hiya hattaa mat la\'il fajr')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 97, 1, 'بے شک ہم نے اس (قرآن) کو شب قدر میں اتارا ہے'),
  ('ur.ahmedali', 97, 2, 'اور آپ کو کیا معلوم کہ شب قدر کیا ہے'),
  ('ur.ahmedali', 97, 3, 'شب قدر ہزار مہینوں سے بہتر ہے'),
  ('ur.ahmedali', 97, 4, 'اس میں فرشتے اور روح نازل ہوتے ہیں اپنے رب کے حکم سے ہر کام پر'),
  ('ur.ahmedali', 97, 5, 'وہ صبح روشن ہونے تک سلامتی کی رات ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 97, 1, 'Doğrusu, Biz, Kuran\'ı kadir gecesinde indirmişizdir.'),
  ('tr.diyanet', 97, 2, 'Kadir gecesinin ne olduğunu sen bilir misin?'),
  ('tr.diyanet', 97, 3, 'Kadir gecesi bin aydan hayırlıdır.'),
  ('tr.diyanet', 97, 4, 'Melekler ve Cebrail o gecede Rablerinin izniyle her türlü iş için inerler.'),
  ('tr.diyanet', 97, 5, 'O gece, tan yerinin ağarmasına kadar bir esenliktir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 97, 1, 'Sesungguhnya Kami telah menurunkannya (Al Quran) pada malam kemuliaan.'),
  ('id.indonesian', 97, 2, 'Dan tahukah kamu apakah malam kemuliaan itu?'),
  ('id.indonesian', 97, 3, 'Malam kemuliaan itu lebih baik dari seribu bulan.'),
  ('id.indonesian', 97, 4, 'Pada malam itu turun malaikat-malaikat dan malaikat Jibril dengan izin Tuhannya untuk mengatur segala urusan.'),
  ('id.indonesian', 97, 5, 'Malam itu (penuh) kesejahteraan sampai terbit fajar.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 98, 1, 'Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence -'),
  ('en.sahih', 98, 2, 'A Messenger from Allah, reciting purified scriptures'),
  ('en.sahih', 98, 3, 'Within which are correct writings.'),
  ('en.sahih', 98, 4, 'Nor did those who were given the Scripture become divided until after there had come to them clear evidence.'),
  ('en.sahih', 98, 5, 'And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion.'),
  ('en.sahih', 98, 6, 'Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures.'),
  ('en.sahih', 98, 7, 'Indeed, they who have believed and done righteous deeds - those are the best of creatures.'),
  ('en.sahih', 98, 8, 'Their reward with Allah will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being pleased with them and they with Him. That is for whoever has feared his Lord.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 98, 1, 'আহলে-কিতাব ও মুশরেকদের মধ্যে যারা কাফের ছিল, তারা প্রত্যাবর্তন করত না যতক্ষণ না তাদের কাছে সুস্পষ্ট প্রমাণ আসত।'),
  ('bn.bengali', 98, 2, 'অর্থাৎ আল্লাহর একজন রসূল, যিনি আবৃত্তি করতেন পবিত্র সহীফা,'),
  ('bn.bengali', 98, 3, 'যাতে আছে, সঠিক বিষয়বস্তু।'),
  ('bn.bengali', 98, 4, 'অপর কিতাব প্রাপ্তরা যে বিভ্রান্ত হয়েছে, তা হয়েছে তাদের কাছে সুস্পষ্ট প্রমাণ আসার পরেই।'),
  ('bn.bengali', 98, 5, 'তাদেরকে এছাড়া কোন নির্দেশ করা হয়নি যে, তারা খাঁটি মনে একনিষ্ঠভাবে আল্লাহর এবাদত করবে, নামায কায়েম করবে এবং যাকাত দেবে। এটাই সঠিক ধর্ম।'),
  ('bn.bengali', 98, 6, 'আহলে-কিতাব ও মুশরেকদের মধ্যে যারা কাফের, তারা জাহান্নামের আগুনে স্থায়ীভাবে থাকবে। তারাই সৃষ্টির অধম।'),
  ('bn.bengali', 98, 7, 'যারা ঈমান আনে ও সৎকর্ম করে, তারাই সৃষ্টির সেরা।'),
  ('bn.bengali', 98, 8, 'তাদের পালনকর্তার কাছে রয়েছে তাদের প্রতিদান চিরকাল বসবাসের জান্নাত, যার তলদেশে নির্ঝরিণী প্রবাহিত। তারা সেখানে থাকবে অনন্তকাল। আল্লাহ তাদের প্রতি সন্তুষ্ট এবং তারা আল্লাহর প্রতি সন্তুষ্ট। এটা তার জন্যে, যে তার পালনকর্তাকে ভয় কর।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 98, 1, 'Those who disbelieve among the People of the Scripture and the idolaters could not have left off (erring) till the clear proof came unto them,'),
  ('en.pickthall', 98, 2, 'A messenger from Allah, reading purified pages'),
  ('en.pickthall', 98, 3, 'Containing correct scriptures.'),
  ('en.pickthall', 98, 4, 'Nor were the People of the Scripture divided until after the clear proof came unto them.'),
  ('en.pickthall', 98, 5, 'And they are ordered naught else than to serve Allah, keeping religion pure for Him, as men by nature upright, and to establish worship and to pay the poor-due. That is true religion.'),
  ('en.pickthall', 98, 6, 'Lo! those who disbelieve, among the People of the Scripture and the idolaters, will abide in fire of hell. They are the worst of created beings.'),
  ('en.pickthall', 98, 7, '(And) lo! those who believe and do good works are the best of created beings.'),
  ('en.pickthall', 98, 8, 'Their reward is with their Lord: Gardens of Eden underneath which rivers flow, wherein they dwell for ever. Allah hath pleasure in them and they have pleasure in Him. This is (in store) for him who feareth his Lord.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 98, 1, 'Those who reject (Truth), among the People of the Book and among the Polytheists, were not going to depart (from their ways) until there should come to them Clear Evidence,-'),
  ('en.yusufali', 98, 2, 'An messenger from Allah, rehearsing scriptures kept pure and holy:'),
  ('en.yusufali', 98, 3, 'Wherein are laws (or decrees) right and straight.'),
  ('en.yusufali', 98, 4, 'Nor did the People of the Book make schisms, until after there came to them Clear Evidence.'),
  ('en.yusufali', 98, 5, 'And they have been commanded no more than this: To worship Allah, offering Him sincere devotion, being true (in faith); to establish regular prayer; and to practise regular charity; and that is the Religion Right and Straight.'),
  ('en.yusufali', 98, 6, 'Those who reject (Truth), among the People of the Book and among the Polytheists, will be in Hell-Fire, to dwell therein (for aye). They are the worst of creatures.'),
  ('en.yusufali', 98, 7, 'Those who have faith and do righteous deeds,- they are the best of creatures.'),
  ('en.yusufali', 98, 8, 'Their reward is with Allah: Gardens of Eternity, beneath which rivers flow; they will dwell therein for ever; Allah well pleased with them, and they with Him: all this for such as fear their Lord and Cherisher.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 98, 1, 'Lam ya kunil lazeena kafaru min ahlil kitaabi wal mushri keena mun fak keena hattaa ta-tiya humul bayyinah'),
  ('en.transliteration', 98, 2, 'Rasoolum minal laahi yatlu suhufam mutahharah'),
  ('en.transliteration', 98, 3, 'Feeha kutubun qaiyimah'),
  ('en.transliteration', 98, 4, 'Wa maa tafarraqal lazeena ootul kitaaba il-la mim b\'adi ma jaa-at humul baiyyinah'),
  ('en.transliteration', 98, 5, 'Wa maa umiroo il-la liy\'abu dul laaha mukhliseena lahud-deena huna faa-a wa yuqeemus salaahta wa yu-tuz zakaata; wa zaalika deenul qaiyimah'),
  ('en.transliteration', 98, 6, 'Innal lazeena kafaru min ahlil kitaabi wal mushri keena fee nari jahan nama khaali deena feeha; ulaa-ika hum shar rul ba reeyah'),
  ('en.transliteration', 98, 7, 'Innal lazeena aamanu wa \'amilus saalihaati ula-ika hum khairul bareey yah'),
  ('en.transliteration', 98, 8, 'Jazaa-uhum inda rabbihim jan naatu \'adnin tajree min tahtihal an haaru khalideena feeha abada; radiy-yallaahu \'anhum wa ra du \'an zaalika liman khashiya rabbah.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 98, 1, 'اہلِ کتاب میں سے کافر اور مشرک لوگ باز آنے والے نہیں تھے یہاں تک کہ ان کے پاس کھلی دلیل آئے'),
  ('ur.ahmedali', 98, 2, 'یعنی ایک رسول الله کی طرف سے آئے جو پاک صحیفے پڑھ کر سنائے'),
  ('ur.ahmedali', 98, 3, 'جن میں درست مضامین لکھے ہوں'),
  ('ur.ahmedali', 98, 4, 'اور اہلِ کتاب نے جو اختلاف کیا تو واضح دلیل آنے کے بعد'),
  ('ur.ahmedali', 98, 5, 'اور انہیں صرف یہی حکم دیا گیا تھا کہ الله کی عبادت کریں ایک رخ ہو کر خالص اسی کی اطاعت کی نیت سے اورنماز قائم کریں اور زکواة دیں اور یہی محکم دین ہے'),
  ('ur.ahmedali', 98, 6, 'بے شک جو لوگ اہلِ کتاب میں سے منکر ہوئے اور مشرکین وہ دوزخ کی آگ میں ہوں گے اس میں ہمیشہ رہیں گے یہی لوگ بدترین مخلوقات ہیں'),
  ('ur.ahmedali', 98, 7, 'بے شک جولوگ ایمان لائے اورنیک کام کیے یہی لوگ بہترین مخلوقات ہیں'),
  ('ur.ahmedali', 98, 8, 'ان کا بدلہ ان کے رب کے ہاں ہمیشہ رہنے کے بہشت ہیں ان کے نیچے نہریں بہتی ہوں گی وہ ان میں ہمیشہ ہمیشہ رہیں گے الله ان سے راضی ہوا اور وہ اس سے راضی ہوئے یہ اس کے لئےہے جو اپنے رب سے ڈرتا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 98, 1, 'Kitap ehlinden ve ortak koşanlardan inkarcılar, kendilerine apaçık bir belge, içinde kesin ve en doğru hükümlerin bulunduğu arınmış sahifeleri okuyan, Allah katından bir Peygamber gelene kadar dinlerinden vazgeçecek değillerdi.'),
  ('tr.diyanet', 98, 2, 'Kitap ehlinden ve ortak koşanlardan inkarcılar, kendilerine apaçık bir belge, içinde kesin ve en doğru hükümlerin bulunduğu arınmış sahifeleri okuyan, Allah katından bir Peygamber gelene kadar dinlerinden vazgeçecek değillerdi.'),
  ('tr.diyanet', 98, 3, 'Kitap ehlinden ve ortak koşanlardan inkarcılar, kendilerine apaçık bir belge, içinde kesin ve en doğru hükümlerin bulunduğu arınmış sahifeleri okuyan, Allah katından bir Peygamber gelene kadar dinlerinden vazgeçecek değillerdi.'),
  ('tr.diyanet', 98, 4, 'Ama, kendilerine kitap verilenler, onlara apaçık belge geldikten sonra ayrılığa düştüler.'),
  ('tr.diyanet', 98, 5, 'Oysa onlar, doğruya yönelerek, dini yalnız Allah\'a has kılarak O\'na kulluk etmek, namazı kılmak ve zekatı vermekle emrolunmuşlardı. Dosdoğru olan din de budur.'),
  ('tr.diyanet', 98, 6, 'Kitap ehlinden ve ortak koşanlardan inkar edenler, şüphesiz içinde temelli kalacakları cehennem ateşindedirler. İşte bunlar, yaratıkların en kötüsüdürler.'),
  ('tr.diyanet', 98, 7, 'Fakat, inanıp yararlı iş işleyenler, işte onlar da, yaratıkların en iyileridirler.'),
  ('tr.diyanet', 98, 8, 'Onların Rableri katındaki mükafatı, içinde temelli ve sonsuz kalacakları, içlerinden ırmaklar akan Adn cennetleridir. Allah onlardan razıdır. Onlar da Allah\'tan razıdır. Bu, Rabbinden korkan kimseyedir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 98, 1, 'Orang-orang kafir yakni ahli Kitab dan orang-orang musyrik (mengatakan bahwa mereka) tidak akan meninggalkan (agamanya) sebelum datang kepada mereka bukti yang nyata,'),
  ('id.indonesian', 98, 2, '(yaitu) seorang Rasul dari Allah (Muhammad) yang membacakan lembaran-lembaran yang disucikan (Al Quran),'),
  ('id.indonesian', 98, 3, 'di dalamnya terdapat (isi) Kitab-kitab yang lurus.'),
  ('id.indonesian', 98, 4, 'Dan tidaklah berpecah belah orang-orang yang didatangkan Al Kitab (kepada mereka) melainkan sesudah datang kepada mereka bukti yang nyata.'),
  ('id.indonesian', 98, 5, 'Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan ketaatan kepada-Nya dalam (menjalankan) agama yang lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus.'),
  ('id.indonesian', 98, 6, 'Sesungguhnya orang-orang yang kafir yakni ahli Kitab dan orang-orang yang musyrik (akan masuk) ke neraka Jahannam; mereka kekal di dalamnya. Mereka itu adalah seburuk-buruk makhluk.'),
  ('id.indonesian', 98, 7, 'Sesungguhnya orang-orang yang beriman dan mengerjakan amal saleh, mereka itu adalah sebaik-baik makhluk.'),
  ('id.indonesian', 98, 8, 'Balasan mereka di sisi Tuhan mereka ialah surga \'Adn yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Allah ridha terhadap mereka dan merekapun ridha kepada-Nya. Yang demikian itu adalah (balasan) bagi orang yang takut kepada Tuhannya.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 99, 1, 'When the earth is shaken with its [final] earthquake'),
  ('en.sahih', 99, 2, 'And the earth discharges its burdens'),
  ('en.sahih', 99, 3, 'And man says, "What is [wrong] with it?" -'),
  ('en.sahih', 99, 4, 'That Day, it will report its news'),
  ('en.sahih', 99, 5, 'Because your Lord has commanded it.'),
  ('en.sahih', 99, 6, 'That Day, the people will depart separated [into categories] to be shown [the result of] their deeds.'),
  ('en.sahih', 99, 7, 'So whoever does an atom\'s weight of good will see it,'),
  ('en.sahih', 99, 8, 'And whoever does an atom\'s weight of evil will see it.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 99, 1, 'যখন পৃথিবী তার কম্পনে প্রকম্পিত হবে,'),
  ('bn.bengali', 99, 2, 'যখন সে তার বোঝা বের করে দেবে।'),
  ('bn.bengali', 99, 3, 'এবং মানুষ বলবে, এর কি হল ?'),
  ('bn.bengali', 99, 4, 'সেদিন সে তার বৃত্তান্ত বর্ণনা করবে,'),
  ('bn.bengali', 99, 5, 'কারণ, আপনার পালনকর্তা তাকে আদেশ করবেন।'),
  ('bn.bengali', 99, 6, 'সেদিন মানুষ বিভিন্ন দলে প্রকাশ পাবে, যাতে তাদেরকে তাদের কৃতকর্ম দেখানো হয়।'),
  ('bn.bengali', 99, 7, 'অতঃপর কেউ অণু পরিমাণ সৎকর্ম করলে তা দেখতে পাবে'),
  ('bn.bengali', 99, 8, 'এবং কেউ অণু পরিমাণ অসৎকর্ম করলে তাও দেখতে পাবে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 99, 1, 'When Earth is shaken with her (final) earthquake'),
  ('en.pickthall', 99, 2, 'And Earth yieldeth up her burdens,'),
  ('en.pickthall', 99, 3, 'And man saith: What aileth her?'),
  ('en.pickthall', 99, 4, 'That day she will relate her chronicles,'),
  ('en.pickthall', 99, 5, 'Because thy Lord inspireth her.'),
  ('en.pickthall', 99, 6, 'That day mankind will issue forth in scattered groups to be shown their deeds.'),
  ('en.pickthall', 99, 7, 'And whoso doeth good an atom\'s weight will see it then,'),
  ('en.pickthall', 99, 8, 'And whoso doeth ill an atom\'s weight will see it then.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 99, 1, 'When the earth is shaken to her (utmost) convulsion,'),
  ('en.yusufali', 99, 2, 'And the earth throws up her burdens (from within),'),
  ('en.yusufali', 99, 3, 'And man cries (distressed): \'What is the matter with her?\'-'),
  ('en.yusufali', 99, 4, 'On that Day will she declare her tidings:'),
  ('en.yusufali', 99, 5, 'For that thy Lord will have given her inspiration.'),
  ('en.yusufali', 99, 6, 'On that Day will men proceed in companies sorted out, to be shown the deeds that they (had done).'),
  ('en.yusufali', 99, 7, 'Then shall anyone who has done an atom\'s weight of good, see it!'),
  ('en.yusufali', 99, 8, 'And anyone who has done an atom\'s weight of evil, shall see it.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 99, 1, 'Izaa zul zilatil ardu zil zaalaha'),
  ('en.transliteration', 99, 2, 'Wa akh rajatil ardu athqaalaha'),
  ('en.transliteration', 99, 3, 'Wa qaalal insaanu ma laha'),
  ('en.transliteration', 99, 4, 'Yawmaa izin tuhad dithu akhbaaraha'),
  ('en.transliteration', 99, 5, 'Bi-anna rabbaka awhaa laha'),
  ('en.transliteration', 99, 6, 'Yawma iziy yas durun naasu ash tatal liyuraw a\'maalahum'),
  ('en.transliteration', 99, 7, 'Famaiy ya\'mal mithqala zarratin khai raiy-yarah'),
  ('en.transliteration', 99, 8, 'Wa maiy-y\'amal mithqala zarratin sharraiy-yarah')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 99, 1, 'جب زمین بڑے زور سے ہلا دی جائے گی'),
  ('ur.ahmedali', 99, 2, 'اور زمین اپنے بوجھ نکال پھینکے گی'),
  ('ur.ahmedali', 99, 3, 'اور انسان کہے گا کہ اس کو کیا ہوگیا'),
  ('ur.ahmedali', 99, 4, 'اس دن وہ اپنی خبریں بیا ن کرے گی'),
  ('ur.ahmedali', 99, 5, 'اس لئے کہ آپ کا رب اس کو حکم دے گا'),
  ('ur.ahmedali', 99, 6, 'اس دن لوگ مختلف حالتوں میں لوٹیں گے تاکہ انہیں ان کے اعمال دکھائے جائیں'),
  ('ur.ahmedali', 99, 7, 'پھر جس نے ذرہ بھر نیکی کی ہے وہ اس کو دیکھ لے گا'),
  ('ur.ahmedali', 99, 8, 'اورجس نے ذرہ بھر برائی کی ہے وہ اس کو دیکھ لے گا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 99, 1, 'Yer dehşetle sarsıldıkça sarsıldığı, yeryüzü ağırlıklarını dışarıya çıkardığı ve insanın: "Buna ne oluyor?" dediği zaman;'),
  ('tr.diyanet', 99, 2, 'Yer dehşetle sarsıldıkça sarsıldığı, yeryüzü ağırlıklarını dışarıya çıkardığı ve insanın: "Buna ne oluyor?" dediği zaman;'),
  ('tr.diyanet', 99, 3, 'Yer dehşetle sarsıldıkça sarsıldığı, yeryüzü ağırlıklarını dışarıya çıkardığı ve insanın: "Buna ne oluyor?" dediği zaman;'),
  ('tr.diyanet', 99, 4, 'İşte o gün, yer, Rabbinin ona vahyetmesiyle kendi haberlerini anlatır.'),
  ('tr.diyanet', 99, 5, 'İşte o gün, yer, Rabbinin ona vahyetmesiyle kendi haberlerini anlatır.'),
  ('tr.diyanet', 99, 6, 'O gün insanlar işlerinin kendilerine gösterilmesi için bölük bölük dönerler.'),
  ('tr.diyanet', 99, 7, 'Kim zerre kadar iyilik yapmışsa onu görür.'),
  ('tr.diyanet', 99, 8, 'Kim de zerre kadar kötülük yapmışsa onu görür.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 99, 1, 'Apabila bumi digoncangkan dengan goncangan (yang dahsyat),'),
  ('id.indonesian', 99, 2, 'dan bumi telah mengeluarkan beban-beban berat (yang dikandung)nya,'),
  ('id.indonesian', 99, 3, 'dan manusia bertanya: "Mengapa bumi (menjadi begini)?",'),
  ('id.indonesian', 99, 4, 'pada hari itu bumi menceritakan beritanya,'),
  ('id.indonesian', 99, 5, 'karena sesungguhnya Tuhanmu telah memerintahkan (yang sedemikian itu) kepadanya.'),
  ('id.indonesian', 99, 6, 'Pada hari itu manusia ke luar dari kuburnya dalam keadaan bermacam-macam, supaya diperlihatkan kepada mereka (balasan) pekerjaan mereka,'),
  ('id.indonesian', 99, 7, 'Barangsiapa yang mengerjakan kebaikan seberat dzarrahpun, niscaya dia akan melihat (balasan)nya.'),
  ('id.indonesian', 99, 8, 'Dan barangsiapa yang mengerjakan kejahatan sebesar dzarrahpun, niscaya dia akan melihat (balasan)nya pula.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 100, 1, 'By the racers, panting,'),
  ('en.sahih', 100, 2, 'And the producers of sparks [when] striking'),
  ('en.sahih', 100, 3, 'And the chargers at dawn,'),
  ('en.sahih', 100, 4, 'Stirring up thereby [clouds of] dust,'),
  ('en.sahih', 100, 5, 'Arriving thereby in the center collectively,'),
  ('en.sahih', 100, 6, 'Indeed mankind, to his Lord, is ungrateful.'),
  ('en.sahih', 100, 7, 'And indeed, he is to that a witness.'),
  ('en.sahih', 100, 8, 'And indeed he is, in love of wealth, intense.'),
  ('en.sahih', 100, 9, 'But does he not know that when the contents of the graves are scattered'),
  ('en.sahih', 100, 10, 'And that within the breasts is obtained,'),
  ('en.sahih', 100, 11, 'Indeed, their Lord with them, that Day, is [fully] Acquainted.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 100, 1, 'শপথ উর্ধ্বশ্বাসে চলমান অশ্বসমূহের,'),
  ('bn.bengali', 100, 2, 'অতঃপর ক্ষুরাঘাতে অগ্নিবিচ্ছুরক অশ্বসমূহের'),
  ('bn.bengali', 100, 3, 'অতঃপর প্রভাতকালে আক্রমণকারী অশ্বসমূহের'),
  ('bn.bengali', 100, 4, 'ও যারা সে সময়ে ধুলি উৎক্ষিপ্ত করে'),
  ('bn.bengali', 100, 5, 'অতঃপর যারা শক্রদলের অভ্যন্তরে ঢুকে পড়ে-'),
  ('bn.bengali', 100, 6, 'নিশ্চয় মানুষ তার পালনকর্তার প্রতি অকৃতজ্ঞ।'),
  ('bn.bengali', 100, 7, 'এবং সে অবশ্য এ বিষয়ে অবহিত'),
  ('bn.bengali', 100, 8, 'এবং সে নিশ্চিতই ধন-সম্পদের ভালবাসায় মত্ত।'),
  ('bn.bengali', 100, 9, 'সে কি জানে না, যখন কবরে যা আছে, তা উত্থিত হবে'),
  ('bn.bengali', 100, 10, 'এবং অন্তরে যা আছে, তা অর্জন করা হবে?'),
  ('bn.bengali', 100, 11, 'সেদিন তাদের কি হবে, সে সম্পর্কে তাদের পালনকর্তা সবিশেষ জ্ঞাত।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 100, 1, 'By the snorting courses,'),
  ('en.pickthall', 100, 2, 'Striking sparks of fire'),
  ('en.pickthall', 100, 3, 'And scouring to the raid at dawn,'),
  ('en.pickthall', 100, 4, 'Then, therewith, with their trail of dust,'),
  ('en.pickthall', 100, 5, 'Cleaving, as one, the centre (of the foe),'),
  ('en.pickthall', 100, 6, 'Lo! man is an ingrate unto his Lord'),
  ('en.pickthall', 100, 7, 'And lo! he is a witness unto that;'),
  ('en.pickthall', 100, 8, 'And lo! in the love of wealth he is violent.'),
  ('en.pickthall', 100, 9, 'Knoweth he not that, when the contents of the graves are poured forth'),
  ('en.pickthall', 100, 10, 'And the secrets of the breasts are made known,'),
  ('en.pickthall', 100, 11, 'On that day will their Lord be perfectly informed concerning them.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 100, 1, 'By the (Steeds) that run, with panting (breath),'),
  ('en.yusufali', 100, 2, 'And strike sparks of fire,'),
  ('en.yusufali', 100, 3, 'And push home the charge in the morning,'),
  ('en.yusufali', 100, 4, 'And raise the dust in clouds the while,'),
  ('en.yusufali', 100, 5, 'And penetrate forthwith into the midst (of the foe) en masse;-'),
  ('en.yusufali', 100, 6, 'Truly man is, to his Lord, ungrateful;'),
  ('en.yusufali', 100, 7, 'And to that (fact) he bears witness (by his deeds);'),
  ('en.yusufali', 100, 8, 'And violent is he in his love of wealth.'),
  ('en.yusufali', 100, 9, 'Does he not know,- when that which is in the graves is scattered abroad'),
  ('en.yusufali', 100, 10, 'And that which is (locked up) in (human) breasts is made manifest-'),
  ('en.yusufali', 100, 11, 'That their Lord had been Well-acquainted with them, (even to) that Day?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 100, 1, 'Wal\'aadi yaati dabha'),
  ('en.transliteration', 100, 2, 'Fal moori yaati qadha'),
  ('en.transliteration', 100, 3, 'Fal mugheeraati subha'),
  ('en.transliteration', 100, 4, 'Fa atharna bihee naq\'a'),
  ('en.transliteration', 100, 5, 'Fawa satna bihee jam\'a'),
  ('en.transliteration', 100, 6, 'Innal-insana lirabbihee lakanood'),
  ('en.transliteration', 100, 7, 'Wa innahu \'alaa zaalika la shaheed'),
  ('en.transliteration', 100, 8, 'Wa innahu lihubbil khairi la shadeed'),
  ('en.transliteration', 100, 9, 'Afala ya\'lamu iza b\'uthira ma filquboor'),
  ('en.transliteration', 100, 10, 'Wa hussila maa fis sudoor'),
  ('en.transliteration', 100, 11, 'Inna rabbahum bihim yauma \'izil la khabeer')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 100, 1, 'ان گھوڑوں کی قسم جو ہانپتے ہوئے دوڑتے ہیں'),
  ('ur.ahmedali', 100, 2, 'پھر (پتھر پر) ٹاپ مار کر آگ جھاڑتے ہیں'),
  ('ur.ahmedali', 100, 3, 'پھر صبح کے وقت دھاوا کرتے ہیں'),
  ('ur.ahmedali', 100, 4, 'پھر اس وقت غبار اُڑاتے ہیں'),
  ('ur.ahmedali', 100, 5, 'پھر اس وقت دشمنوں کی جماعت میں جا گھستے ہیں'),
  ('ur.ahmedali', 100, 6, 'بے شک انسان اپنے رب کا بڑا ناشکرا ہے'),
  ('ur.ahmedali', 100, 7, 'اوربے شک وہ اس بات پر خود شاہد ہے'),
  ('ur.ahmedali', 100, 8, 'اوربے شک وہ مال کی محبت میں بڑا سخت ہے'),
  ('ur.ahmedali', 100, 9, 'پس کیا وہ نہیں جانتا جب اکھاڑا جائے گا جو کچھ قبروں میں ہے'),
  ('ur.ahmedali', 100, 10, 'اورجو دلوں میں ہے وہ ظاہر کیا جائے گا'),
  ('ur.ahmedali', 100, 11, 'بے شک ان کا رب ان سے اس دن خوب خبردار ہو گا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 100, 1, 'And olsun Allah yolunda koştukça koşanlara;'),
  ('tr.diyanet', 100, 2, 'And olsun kıvılcımlar saçanlara;'),
  ('tr.diyanet', 100, 3, 'Sabah sabah akına çıkanlara;'),
  ('tr.diyanet', 100, 4, 'Ve tozu dumana katanlara;'),
  ('tr.diyanet', 100, 5, 'Düşman topluluğunun içine dalanlara ki:'),
  ('tr.diyanet', 100, 6, 'İnsan gerçekten Rabbine karşı pek nankördür.'),
  ('tr.diyanet', 100, 7, 'Doğrusu kendisi de bunların hepsine şahittir.'),
  ('tr.diyanet', 100, 8, 'Gerçekten mala da pek düşkündür.'),
  ('tr.diyanet', 100, 9, 'İnsan, kabirlerde bulunanların çıkarılacağı ve kalblerde olanların ortaya konulacağı bir zamanın geleceğini bilmez mi?'),
  ('tr.diyanet', 100, 10, 'İnsan, kabirlerde bulunanların çıkarılacağı ve kalblerde olanların ortaya konulacağı bir zamanın geleceğini bilmez mi?'),
  ('tr.diyanet', 100, 11, 'Doğrusu Rableri o gün onların her şeyinden haberdardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 100, 1, 'Demi kuda perang yang berlari kencang dengan terengah-engah,'),
  ('id.indonesian', 100, 2, 'dan kuda yang mencetuskan api dengan pukulan (kuku kakinya),'),
  ('id.indonesian', 100, 3, 'dan kuda yang menyerang dengan tiba-tiba di waktu pagi,'),
  ('id.indonesian', 100, 4, 'maka ia menerbangkan debu,'),
  ('id.indonesian', 100, 5, 'dan menyerbu ke tengah-tengah kumpulan musuh,'),
  ('id.indonesian', 100, 6, 'sesungguhnya manusia itu sangat ingkar, tidak berterima kasih kepada Tuhannya,'),
  ('id.indonesian', 100, 7, 'dan sesungguhnya manusia itu menyaksikan (sendiri) keingkarannya,'),
  ('id.indonesian', 100, 8, 'dan sesungguhnya dia sangat bakhil karena cintanya kepada harta.'),
  ('id.indonesian', 100, 9, 'Maka apakah dia tidak mengetahui apabila dibangkitkan apa yang ada di dalam kubur,'),
  ('id.indonesian', 100, 10, 'dan dilahirkan apa yang ada di dalam dada,'),
  ('id.indonesian', 100, 11, 'sesungguhnya Tuhan mereka pada hari itu Maha Mengetahui keadaan mereka.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 101, 1, 'The Striking Calamity -'),
  ('en.sahih', 101, 2, 'What is the Striking Calamity?'),
  ('en.sahih', 101, 3, 'And what can make you know what is the Striking Calamity?'),
  ('en.sahih', 101, 4, 'It is the Day when people will be like moths, dispersed,'),
  ('en.sahih', 101, 5, 'And the mountains will be like wool, fluffed up.'),
  ('en.sahih', 101, 6, 'Then as for one whose scales are heavy [with good deeds],'),
  ('en.sahih', 101, 7, 'He will be in a pleasant life.'),
  ('en.sahih', 101, 8, 'But as for one whose scales are light,'),
  ('en.sahih', 101, 9, 'His refuge will be an abyss.'),
  ('en.sahih', 101, 10, 'And what can make you know what that is?'),
  ('en.sahih', 101, 11, 'It is a Fire, intensely hot.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 101, 1, 'করাঘাতকারী,'),
  ('bn.bengali', 101, 2, 'করাঘাতকারী কি?'),
  ('bn.bengali', 101, 3, 'করাঘাতকারী সম্পর্কে আপনি কি জানেন ?'),
  ('bn.bengali', 101, 4, 'যেদিন মানুষ হবে বিক্ষিপ্ত পতংগের মত'),
  ('bn.bengali', 101, 5, 'এবং পর্বতমালা হবে ধুনিত রঙ্গীন পশমের মত।'),
  ('bn.bengali', 101, 6, 'অতএব যার পাল্লা ভারী হবে,'),
  ('bn.bengali', 101, 7, 'সে সুখীজীবন যাপন করবে।'),
  ('bn.bengali', 101, 8, 'আর যার পাল্লা হালকা হবে,'),
  ('bn.bengali', 101, 9, 'তার ঠিকানা হবে হাবিয়া।'),
  ('bn.bengali', 101, 10, 'আপনি জানেন তা কি?'),
  ('bn.bengali', 101, 11, 'প্রজ্জ্বলিত অগ্নি!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 101, 1, 'The Calamity!'),
  ('en.pickthall', 101, 2, 'What is the Calamity?'),
  ('en.pickthall', 101, 3, 'Ah, what will convey unto thee what the Calamity is!'),
  ('en.pickthall', 101, 4, 'A day wherein mankind will be as thickly-scattered moths'),
  ('en.pickthall', 101, 5, 'And the mountains will become as carded wool.'),
  ('en.pickthall', 101, 6, 'Then, as for him whose scales are heavy (with good works),'),
  ('en.pickthall', 101, 7, 'He will live a pleasant life.'),
  ('en.pickthall', 101, 8, 'But as for him whose scales are light,'),
  ('en.pickthall', 101, 9, 'A bereft and Hungry One will be his mother,'),
  ('en.pickthall', 101, 10, 'Ah, what will convey unto thee what she is! -'),
  ('en.pickthall', 101, 11, 'Raging Fire.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 101, 1, 'The (Day) of Noise and Clamour:'),
  ('en.yusufali', 101, 2, 'What is the (Day) of Noise and Clamour?'),
  ('en.yusufali', 101, 3, 'And what will explain to thee what the (Day) of Noise and Clamour is?'),
  ('en.yusufali', 101, 4, '(It is) a Day whereon men will be like moths scattered about,'),
  ('en.yusufali', 101, 5, 'And the mountains will be like carded wool.'),
  ('en.yusufali', 101, 6, 'Then, he whose balance (of good deeds) will be (found) heavy,'),
  ('en.yusufali', 101, 7, 'Will be in a life of good pleasure and satisfaction.'),
  ('en.yusufali', 101, 8, 'But he whose balance (of good deeds) will be (found) light,-'),
  ('en.yusufali', 101, 9, 'Will have his home in a (bottomless) Pit.'),
  ('en.yusufali', 101, 10, 'And what will explain to thee what this is?'),
  ('en.yusufali', 101, 11, '(It is) a Fire Blazing fiercely!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 101, 1, 'Al qaari\'ah'),
  ('en.transliteration', 101, 2, 'Mal qaariah'),
  ('en.transliteration', 101, 3, 'Wa maa adraaka mal qaari\'ah'),
  ('en.transliteration', 101, 4, 'Yauma ya koonun naasu kal farashil mabthooth'),
  ('en.transliteration', 101, 5, 'Wa ta koonul jibalu kal \'ihnil manfoosh'),
  ('en.transliteration', 101, 6, 'Fa-amma man thaqulat mawa zeenuh'),
  ('en.transliteration', 101, 7, 'Fahuwa fee \'ishatir raadiyah'),
  ('en.transliteration', 101, 8, 'Wa amma man khaffat mawa zeenuh'),
  ('en.transliteration', 101, 9, 'Fa-ummuhu haawiyah'),
  ('en.transliteration', 101, 10, 'Wa maa adraaka maa hiyah'),
  ('en.transliteration', 101, 11, 'Naarun hamiyah')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 101, 1, 'کھڑکھڑانے والی'),
  ('ur.ahmedali', 101, 2, 'وہ کھڑکھڑانے والی کیا ہے'),
  ('ur.ahmedali', 101, 3, 'اور آپ کو کیا خبر کہ وہ کھڑکھڑانے والی کیا ہے'),
  ('ur.ahmedali', 101, 4, 'جس دن لو گ بکھرے ہوئے پروانوں کی طرح ہوں گے'),
  ('ur.ahmedali', 101, 5, 'اور پہاڑ رنگی ہوئی دھنی ہوئی اُون کی طرح ہوں گے'),
  ('ur.ahmedali', 101, 6, 'تو جس کے اعمال (نیک) تول میں زیادہ ہوں گے'),
  ('ur.ahmedali', 101, 7, 'تو وہ خاطر خواہ عیش میں ہوگا'),
  ('ur.ahmedali', 101, 8, 'اور جس کے اعمال (نیک) تول میں کم ہوں گے'),
  ('ur.ahmedali', 101, 9, 'تواس کا ٹھکانا ہاویہ ہوگا'),
  ('ur.ahmedali', 101, 10, 'اور آپ کو کیا معلوم کہ وہ کیا چیز ہے'),
  ('ur.ahmedali', 101, 11, 'وہ دھکتی ہوئی آگ ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 101, 1, 'Gürültü koparacak olan'),
  ('tr.diyanet', 101, 2, 'Nedir o gürültü koparacak olan?'),
  ('tr.diyanet', 101, 3, 'O gürültü koparacak olanın ne olduğunu sen bilir misin?'),
  ('tr.diyanet', 101, 4, 'O gün insanlar, ateş etrafında çırpınıp dökülen pervaneye dönecekler.'),
  ('tr.diyanet', 101, 5, 'Dağlar, atılmış renkli yüne benzeyecekler.'),
  ('tr.diyanet', 101, 6, 'Ama tartıları ağır gelen kimse hoş bir hayat içinde olacaktır.'),
  ('tr.diyanet', 101, 7, 'Ama tartıları ağır gelen kimse hoş bir hayat içinde olacaktır.'),
  ('tr.diyanet', 101, 8, 'Tartıları hafif gelenler ise,'),
  ('tr.diyanet', 101, 9, 'Onların yeri bir çukurdur.'),
  ('tr.diyanet', 101, 10, 'O çukurun ne olduğunu sen bilir misin?'),
  ('tr.diyanet', 101, 11, 'O, kızgın bir ateştir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 101, 1, 'Hari Kiamat,'),
  ('id.indonesian', 101, 2, 'apakah hari Kiamat itu?'),
  ('id.indonesian', 101, 3, 'Tahukah kamu apakah hari Kiamat itu?'),
  ('id.indonesian', 101, 4, 'Pada hari itu manusia adalah seperti anai-anai yang bertebaran,'),
  ('id.indonesian', 101, 5, 'dan gunung-gunung adalah seperti bulu yang dihambur-hamburkan.'),
  ('id.indonesian', 101, 6, 'Dan adapun orang-orang yang berat timbangan (kebaikan)nya,'),
  ('id.indonesian', 101, 7, 'maka dia berada dalam kehidupan yang memuaskan.'),
  ('id.indonesian', 101, 8, 'Dan adapun orang-orang yang ringan timbangan (kebaikan)nya,'),
  ('id.indonesian', 101, 9, 'maka tempat kembalinya adalah neraka Hawiyah.'),
  ('id.indonesian', 101, 10, 'Tahukah kamu apakah neraka Hawiyah itu?'),
  ('id.indonesian', 101, 11, '(Yaitu) api yang sangat panas.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 102, 1, 'Competition in [worldly] increase diverts you'),
  ('en.sahih', 102, 2, 'Until you visit the graveyards.'),
  ('en.sahih', 102, 3, 'No! You are going to know.'),
  ('en.sahih', 102, 4, 'Then no! You are going to know.'),
  ('en.sahih', 102, 5, 'No! If you only knew with knowledge of certainty...'),
  ('en.sahih', 102, 6, 'You will surely see the Hellfire.'),
  ('en.sahih', 102, 7, 'Then you will surely see it with the eye of certainty.'),
  ('en.sahih', 102, 8, 'Then you will surely be asked that Day about pleasure.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 102, 1, 'প্রাচুর্যের লালসা তোমাদেরকে গাফেল রাখে,'),
  ('bn.bengali', 102, 2, 'এমনকি, তোমরা কবরস্থানে পৌছে যাও।'),
  ('bn.bengali', 102, 3, 'এটা কখনও উচিত নয়। তোমরা সত্ত্বরই জেনে নেবে।'),
  ('bn.bengali', 102, 4, 'অতঃপর এটা কখনও উচিত নয়। তোমরা সত্ত্বরই জেনে নেবে।'),
  ('bn.bengali', 102, 5, 'কখনই নয়; যদি তোমরা নিশ্চিত জানতে।'),
  ('bn.bengali', 102, 6, 'তোমরা অবশ্যই জাহান্নাম দেখবে,'),
  ('bn.bengali', 102, 7, 'অতঃপর তোমরা তা অবশ্যই দেখবে দিব্য প্রত্যয়ে,'),
  ('bn.bengali', 102, 8, 'এরপর অবশ্যই সেদিন তোমরা নেয়ামত সম্পর্কে জিজ্ঞাসিত হবে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 102, 1, 'Rivalry in worldly increase distracteth you'),
  ('en.pickthall', 102, 2, 'Until ye come to the graves.'),
  ('en.pickthall', 102, 3, 'Nay, but ye will come to know!'),
  ('en.pickthall', 102, 4, 'Nay, but ye will come to know!'),
  ('en.pickthall', 102, 5, 'Nay, would that ye knew (now) with a sure knowledge!'),
  ('en.pickthall', 102, 6, 'For ye will behold hell-fire.'),
  ('en.pickthall', 102, 7, 'Aye, ye will behold it with sure vision.'),
  ('en.pickthall', 102, 8, 'Then, on that day, ye will be asked concerning pleasure.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 102, 1, 'The mutual rivalry for piling up (the good things of this world) diverts you (from the more serious things),'),
  ('en.yusufali', 102, 2, 'Until ye visit the graves.'),
  ('en.yusufali', 102, 3, 'But nay, ye soon shall know (the reality).'),
  ('en.yusufali', 102, 4, 'Again, ye soon shall know!'),
  ('en.yusufali', 102, 5, 'Nay, were ye to know with certainty of mind, (ye would beware!)'),
  ('en.yusufali', 102, 6, 'Ye shall certainly see Hell-Fire!'),
  ('en.yusufali', 102, 7, 'Again, ye shall see it with certainty of sight!'),
  ('en.yusufali', 102, 8, 'Then, shall ye be questioned that Day about the joy (ye indulged in!).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 102, 1, 'Al haaku mut takathur'),
  ('en.transliteration', 102, 2, 'Hatta zurtumul-maqaabir'),
  ('en.transliteration', 102, 3, 'Kalla sawfa ta\'lamoon'),
  ('en.transliteration', 102, 4, 'Thumma kalla sawfa ta\'lamoon'),
  ('en.transliteration', 102, 5, 'Kalla law ta\'lamoona \'ilmal yaqeen'),
  ('en.transliteration', 102, 6, 'Latara-wun nal jaheem'),
  ('en.transliteration', 102, 7, 'Thumma latara wunnaha \'ainal yaqeen'),
  ('en.transliteration', 102, 8, 'Thumma latus alunna yauma-izin \'anin na\'eem')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 102, 1, 'تمہیں حرص نے غافل کر دیا'),
  ('ur.ahmedali', 102, 2, 'یہاں تک کہ قبریں جا دیکھیں'),
  ('ur.ahmedali', 102, 3, 'ایسا نہیں آئندہ تم جان لو گے'),
  ('ur.ahmedali', 102, 4, 'پھر ایسا نہیں چاہیئے آئندہ تم جان لو گے'),
  ('ur.ahmedali', 102, 5, 'ایسا نہیں چاہیئے کاش تم یقینی طور پر جانتے'),
  ('ur.ahmedali', 102, 6, 'البتہ تم ضرور دوزخ کو دیکھو گے'),
  ('ur.ahmedali', 102, 7, 'پھر تم اسے ضرور بالکل یقینی طور پر دیکھو گے'),
  ('ur.ahmedali', 102, 8, 'پھر اس دن تم سے نعمتوں کے متعلق پوچھا جائے گا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 102, 1, 'Çoğunluk olmak iddianız sizi o kadar meşgul etti ki, mezarları ziyaretle oradakileri de sayacak kadar oldunuz.'),
  ('tr.diyanet', 102, 2, 'Çoğunluk olmak iddianız sizi o kadar meşgul etti ki, mezarları ziyaretle oradakileri de sayacak kadar oldunuz.'),
  ('tr.diyanet', 102, 3, 'Hayır; öyle olmayın; yakında bileceksiniz.'),
  ('tr.diyanet', 102, 4, 'Hayır; gözünüzü açın; yakında bileceksiniz.'),
  ('tr.diyanet', 102, 5, 'Dikkat edin, şayet yaptığınızın sonucunu kesin olarak bir bilseniz!'),
  ('tr.diyanet', 102, 6, 'And olsun ki, cehennemi göreceksiniz.'),
  ('tr.diyanet', 102, 7, 'And olsun ki, onu gözünüzle kesin olarak göreceksiniz.'),
  ('tr.diyanet', 102, 8, 'Sonra o gün, size verilmiş olan her nimetten sorguya çekileceksiniz.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 102, 1, 'Bermegah-megahan telah melalaikan kamu,'),
  ('id.indonesian', 102, 2, 'sampai kamu masuk ke dalam kubur.'),
  ('id.indonesian', 102, 3, 'Janganlah begitu, kelak kamu akan mengetahui (akibat perbuatanmu itu),'),
  ('id.indonesian', 102, 4, 'dan janganlah begitu, kelak kamu akan mengetahui.'),
  ('id.indonesian', 102, 5, 'Janganlah begitu, jika kamu mengetahui dengan pengetahuan yang yakin,'),
  ('id.indonesian', 102, 6, 'niscaya kamu benar-benar akan melihat neraka Jahiim,'),
  ('id.indonesian', 102, 7, 'dan sesungguhnya kamu benar-benar akan melihatnya dengan \'ainul yaqin.'),
  ('id.indonesian', 102, 8, 'kemudian kamu pasti akan ditanyai pada hari itu tentang kenikmatan (yang kamu megah-megahkan di dunia itu).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 103, 1, 'By time,'),
  ('en.sahih', 103, 2, 'Indeed, mankind is in loss,'),
  ('en.sahih', 103, 3, 'Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 103, 1, 'কসম যুগের (সময়ের),'),
  ('bn.bengali', 103, 2, 'নিশ্চয় মানুষ ক্ষতিগ্রস্ত;'),
  ('bn.bengali', 103, 3, 'কিন্তু তারা নয়, যারা বিশ্বাস স্থাপন করে ও সৎকর্ম করে এবং পরস্পরকে তাকীদ করে সত্যের এবং তাকীদ করে সবরের।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 103, 1, 'By the declining day,'),
  ('en.pickthall', 103, 2, 'Lo! man is a state of loss,'),
  ('en.pickthall', 103, 3, 'Save those who believe and do good works, and exhort one another to truth and exhort one another to endurance.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 103, 1, 'By (the Token of) Time (through the ages),'),
  ('en.yusufali', 103, 2, 'Verily Man is in loss,'),
  ('en.yusufali', 103, 3, 'Except such as have Faith, and do righteous deeds, and (join together) in the mutual teaching of Truth, and of Patience and Constancy.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 103, 1, 'Wal\' asr'),
  ('en.transliteration', 103, 2, 'Innal insaana lafee khusr'),
  ('en.transliteration', 103, 3, 'Il lal lazeena aamanu wa \'amilus saali haati wa tawa saw bil haqqi wa tawa saw bis sabr')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 103, 1, 'زمانہ کی قسم ہے'),
  ('ur.ahmedali', 103, 2, 'بے شک انسان گھاٹے میں ہے'),
  ('ur.ahmedali', 103, 3, 'مگر جو لوگ ایمان لائے اور نیک کام کیے اور حق پر قائم رہنے کی اور صبر کرنے کی آپس میں وصیت کرتے رہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 103, 1, 'İkindi vaktine (Asra; çağa) and olsun ki,'),
  ('tr.diyanet', 103, 2, 'İnsan hiç şüphesiz hüsran içindedir.'),
  ('tr.diyanet', 103, 3, 'Ancak inanıp yararlı iş işleyenler, birbirlerine gerçeği tavsiye edenler ve sabırlı olmayı tavsiye edenler bunun dışındadır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 103, 1, 'Demi masa.'),
  ('id.indonesian', 103, 2, 'Sesungguhnya manusia itu benar-benar dalam kerugian,'),
  ('id.indonesian', 103, 3, 'kecuali orang-orang yang beriman dan mengerjakan amal saleh dan nasehat menasehati supaya mentaati kebenaran dan nasehat menasehati supaya menetapi kesabaran.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 104, 1, 'Woe to every scorner and mocker'),
  ('en.sahih', 104, 2, 'Who collects wealth and [continuously] counts it.'),
  ('en.sahih', 104, 3, 'He thinks that his wealth will make him immortal.'),
  ('en.sahih', 104, 4, 'No! He will surely be thrown into the Crusher.'),
  ('en.sahih', 104, 5, 'And what can make you know what is the Crusher?'),
  ('en.sahih', 104, 6, 'It is the fire of Allah, [eternally] fueled,'),
  ('en.sahih', 104, 7, 'Which mounts directed at the hearts.'),
  ('en.sahih', 104, 8, 'Indeed, Hellfire will be closed down upon them'),
  ('en.sahih', 104, 9, 'In extended columns.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 104, 1, 'প্রত্যেক পশ্চাতে ও সম্মুখে পরনিন্দাকারীর দুর্ভোগ,'),
  ('bn.bengali', 104, 2, 'যে অর্থ সঞ্চিত করে ও গণনা করে'),
  ('bn.bengali', 104, 3, 'সে মনে করে যে, তার অর্থ চিরকাল তার সাথে থাকবে!'),
  ('bn.bengali', 104, 4, 'কখনও না, সে অবশ্যই নিক্ষিপ্ত হবে পিষ্টকারীর মধ্যে।'),
  ('bn.bengali', 104, 5, 'আপনি কি জানেন, পিষ্টকারী কি?'),
  ('bn.bengali', 104, 6, 'এটা আল্লাহর প্রজ্জ্বলিত অগ্নি,'),
  ('bn.bengali', 104, 7, 'যা হৃদয় পর্যন্ত পৌছবে।'),
  ('bn.bengali', 104, 8, 'এতে তাদেরকে বেঁধে দেয়া হবে,'),
  ('bn.bengali', 104, 9, 'লম্বা লম্বা খুঁটিতে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 104, 1, 'Woe unto every slandering traducer,'),
  ('en.pickthall', 104, 2, 'Who hath gathered wealth (of this world) and arranged it.'),
  ('en.pickthall', 104, 3, 'He thinketh that his wealth will render him immortal.'),
  ('en.pickthall', 104, 4, 'Nay, but verily he will be flung to the Consuming One.'),
  ('en.pickthall', 104, 5, 'Ah, what will convey unto thee what the Consuming One is!'),
  ('en.pickthall', 104, 6, '(It is) the fire of Allah, kindled,'),
  ('en.pickthall', 104, 7, 'Which leapeth up over the hearts (of men).'),
  ('en.pickthall', 104, 8, 'Lo! it is closed in on them'),
  ('en.pickthall', 104, 9, 'In outstretched columns.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 104, 1, 'Woe to every (kind of) scandal-monger and-backbiter,'),
  ('en.yusufali', 104, 2, 'Who pileth up wealth and layeth it by,'),
  ('en.yusufali', 104, 3, 'Thinking that his wealth would make him last for ever!'),
  ('en.yusufali', 104, 4, 'By no means! He will be sure to be thrown into That which Breaks to Pieces,'),
  ('en.yusufali', 104, 5, 'And what will explain to thee That which Breaks to Pieces?'),
  ('en.yusufali', 104, 6, '(It is) the Fire of (the Wrath of) Allah kindled (to a blaze),'),
  ('en.yusufali', 104, 7, 'The which doth mount (Right) to the Hearts:'),
  ('en.yusufali', 104, 8, 'It shall be made into a vault over them,'),
  ('en.yusufali', 104, 9, 'In columns outstretched.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 104, 1, 'Wai lul-li kulli hu mazatil-lumaza'),
  ('en.transliteration', 104, 2, 'Al-lazi jama\'a maalaw wa\'addadah'),
  ('en.transliteration', 104, 3, 'Yahsabu anna maalahu akhladah'),
  ('en.transliteration', 104, 4, 'Kalla layum ba zanna fil hutamah'),
  ('en.transliteration', 104, 5, 'Wa maa adraaka mal-hutamah'),
  ('en.transliteration', 104, 6, 'Narul laahil-mooqada'),
  ('en.transliteration', 104, 7, 'Al latee tat tali\'u \'alalafidah'),
  ('en.transliteration', 104, 8, 'Innaha \'alaihim moosada'),
  ('en.transliteration', 104, 9, 'Fee \'amadim-mu mad dadah')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 104, 1, 'ہر غیبت کرنے والے طعنہ دینے والے کے لیے ہلاکت ہے'),
  ('ur.ahmedali', 104, 2, 'جو مال کو جمع کرتا ہے اور اسے گنتا رہتا ہے'),
  ('ur.ahmedali', 104, 3, 'وہ خیال کرتا ہے کہ اس کا مال اسے سدا رکھے گا'),
  ('ur.ahmedali', 104, 4, 'ہرگز نہیں وہ ضرور حطمہ میں پھینکا جائے گا'),
  ('ur.ahmedali', 104, 5, 'اور آپ کو کیا معلوم حطمہ کیا ہے'),
  ('ur.ahmedali', 104, 6, 'وہ الله کی بھڑکائی ہوئی آگ ہے'),
  ('ur.ahmedali', 104, 7, 'جو دلوں تک جا پہنچتی ہے'),
  ('ur.ahmedali', 104, 8, 'بے شک وہ ان پر چاروں طرف سے بند کر دی جائے گی'),
  ('ur.ahmedali', 104, 9, 'لمبے لمبے ستونوں میں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 104, 1, 'Mal toplayarak onu tekrar tekrar sayan, diliyle çekiştirip alay eden kimsenin vay haline!'),
  ('tr.diyanet', 104, 2, 'Mal toplayarak onu tekrar tekrar sayan, diliyle çekiştirip alay eden kimsenin vay haline!'),
  ('tr.diyanet', 104, 3, 'Malının kendisini ölümsüz kılacağını sanır.'),
  ('tr.diyanet', 104, 4, 'Hayır; o, and olsun ki, Hutame\'ye atılacaktır.'),
  ('tr.diyanet', 104, 5, 'Hutame\'nin ne olduğunu sen bilir misin?'),
  ('tr.diyanet', 104, 6, 'O, yüreklere çökecek olan, Allah\'ın tutuşturulmuş ateşidir.'),
  ('tr.diyanet', 104, 7, 'O, yüreklere çökecek olan, Allah\'ın tutuşturulmuş ateşidir.'),
  ('tr.diyanet', 104, 8, 'Onlar, uzun sütunlar arasında, her yönden o ateşle kapatılmışlardır.'),
  ('tr.diyanet', 104, 9, 'Onlar, uzun sütunlar arasında, her yönden o ateşle kapatılmışlardır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 104, 1, 'Kecelakaanlah bagi setiap pengumpat lagi pencela,'),
  ('id.indonesian', 104, 2, 'yang mengumpulkan harta dan menghitung-hitung,'),
  ('id.indonesian', 104, 3, 'dia mengira bahwa hartanya itu dapat mengkekalkannya,'),
  ('id.indonesian', 104, 4, 'sekali-kali tidak! Sesungguhnya dia benar-benar akan dilemparkan ke dalam Huthamah.'),
  ('id.indonesian', 104, 5, 'Dan tahukah kamu apa Huthamah itu?'),
  ('id.indonesian', 104, 6, '(yaitu) api (yang disediakan) Allah yang dinyalakan,'),
  ('id.indonesian', 104, 7, 'yang (membakar) sampai ke hati.'),
  ('id.indonesian', 104, 8, 'Sesungguhnya api itu ditutup rapat atas mereka,'),
  ('id.indonesian', 104, 9, '(sedang mereka itu) diikat pada tiang-tiang yang panjang.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 105, 1, 'Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?'),
  ('en.sahih', 105, 2, 'Did He not make their plan into misguidance?'),
  ('en.sahih', 105, 3, 'And He sent against them birds in flocks,'),
  ('en.sahih', 105, 4, 'Striking them with stones of hard clay,'),
  ('en.sahih', 105, 5, 'And He made them like eaten straw.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 105, 1, 'আপনি কি দেখেননি আপনার পালনকর্তা হস্তীবাহিনীর সাথে কিরূপ ব্যবহার করেছেন?'),
  ('bn.bengali', 105, 2, 'তিনি কি তাদের চক্রান্ত নস্যাৎ করে দেননি?'),
  ('bn.bengali', 105, 3, 'তিনি তাদের উপর প্রেরণ করেছেন ঝাঁকে ঝাঁকে পাখী,'),
  ('bn.bengali', 105, 4, 'যারা তাদের উপর পাথরের কংকর নিক্ষেপ করছিল।'),
  ('bn.bengali', 105, 5, 'অতঃপর তিনি তাদেরকে ভক্ষিত তৃণসদৃশ করে দেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 105, 1, 'Hast thou not seen how thy Lord dealt with the owners of the Elephant?'),
  ('en.pickthall', 105, 2, 'Did He not bring their stratagem to naught,'),
  ('en.pickthall', 105, 3, 'And send against them swarms of flying creatures,'),
  ('en.pickthall', 105, 4, 'Which pelted them with stones of baked clay,'),
  ('en.pickthall', 105, 5, 'And made them like green crops devoured (by cattle)?')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 105, 1, 'Seest thou not how thy Lord dealt with the Companions of the Elephant?'),
  ('en.yusufali', 105, 2, 'Did He not make their treacherous plan go astray?'),
  ('en.yusufali', 105, 3, 'And He sent against them Flights of Birds,'),
  ('en.yusufali', 105, 4, 'Striking them with stones of baked clay.'),
  ('en.yusufali', 105, 5, 'Then did He make them like an empty field of stalks and straw, (of which the corn) has been eaten up.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 105, 1, 'Alam tara kaifa fa\'ala rabbuka bi ashaabil feel'),
  ('en.transliteration', 105, 2, 'Alam yaj\'al kai dahum fee tad leel'),
  ('en.transliteration', 105, 3, 'Wa arsala \'alaihim tairan abaabeel'),
  ('en.transliteration', 105, 4, 'Tar meehim bi hi jaaratim min sij jeel'),
  ('en.transliteration', 105, 5, 'Faja \'alahum ka\'asfim m\'akool')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 105, 1, 'کیا آپ نے نہیں دیکھا کہ آپ کے رب نے ہاتھی والوں سے کیا برتاؤ کیا'),
  ('ur.ahmedali', 105, 2, 'کیا اس نے ان کی تدبیر کوبے کار نہیں بنا دیا تھا'),
  ('ur.ahmedali', 105, 3, 'اور اس نے ان پر غول کے غول پرندے بھیجے'),
  ('ur.ahmedali', 105, 4, 'جہاں پر پتھر کنکر کی قسم کے پھینکتے تھے'),
  ('ur.ahmedali', 105, 5, 'پھر انہیں کھائے ہوئے بھس کی طرح کر ڈالا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 105, 1, 'Fil sahiplerine Rabbinin ne ettiğini görmedin mi?'),
  ('tr.diyanet', 105, 2, 'Onların düzenlerini boşa çıkarmadı mı?'),
  ('tr.diyanet', 105, 3, 'Onların üzerine, sert taşlar atan sürülerle kuşlar gönderdi.'),
  ('tr.diyanet', 105, 4, 'Onların üzerine, sert taşlar atan sürülerle kuşlar gönderdi.'),
  ('tr.diyanet', 105, 5, 'Sonunda onları, yenilmiş ekin gibi yaptı.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 105, 1, 'Apakah kamu tidak memperhatikan bagaimana Tuhanmu telah bertindak terhadap tentara bergajah?'),
  ('id.indonesian', 105, 2, 'Bukankah Dia telah menjadikan tipu daya mereka (untuk menghancurkan Ka\'bah) itu sia-sia?'),
  ('id.indonesian', 105, 3, 'dan Dia mengirimkan kapada mereka burung yang berbondong-bondong,'),
  ('id.indonesian', 105, 4, 'yang melempari mereka dengan batu (berasal) dari tanah yang terbakar,'),
  ('id.indonesian', 105, 5, 'lalu Dia menjadikan mereka seperti daun-daun yang dimakan (ulat).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 106, 1, 'For the accustomed security of the Quraysh -'),
  ('en.sahih', 106, 2, 'Their accustomed security [in] the caravan of winter and summer -'),
  ('en.sahih', 106, 3, 'Let them worship the Lord of this House,'),
  ('en.sahih', 106, 4, 'Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 106, 1, 'কোরাইশের আসক্তির কারণে,'),
  ('bn.bengali', 106, 2, 'আসক্তির কারণে তাদের শীত ও গ্রীষ্মকালীন সফরের।'),
  ('bn.bengali', 106, 3, 'অতএব তারা যেন এবাদত করে এই ঘরের পালনকর্তার'),
  ('bn.bengali', 106, 4, 'যিনি তাদেরকে ক্ষুধায় আহার দিয়েছেন এবং যুদ্ধভীতি থেকে তাদেরকে নিরাপদ করেছেন।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 106, 1, 'For the taming of Qureysh.'),
  ('en.pickthall', 106, 2, 'For their taming (We cause) the caravans to set forth in winter and summer.'),
  ('en.pickthall', 106, 3, 'So let them worship the Lord of this House,'),
  ('en.pickthall', 106, 4, 'Who hath fed them against hunger and hath made them safe from fear.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 106, 1, 'For the covenants (of security and safeguard enjoyed) by the Quraish,'),
  ('en.yusufali', 106, 2, 'Their covenants (covering) journeys by winter and summer,-'),
  ('en.yusufali', 106, 3, 'Let them adore the Lord of this House,'),
  ('en.yusufali', 106, 4, 'Who provides them with food against hunger, and with security against fear (of danger).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 106, 1, 'Li-ilaafi quraish'),
  ('en.transliteration', 106, 2, 'Elaafihim rihlatash shitaa-i wass saif'),
  ('en.transliteration', 106, 3, 'Fal y\'abudu rabba haazal-bait'),
  ('en.transliteration', 106, 4, 'Allazi at\'amahum min ju\'inw-wa-aamana hum min khawf')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 106, 1, 'اس لیے کہ قریش کو مانوس کر دیا'),
  ('ur.ahmedali', 106, 2, 'ان کو جاڑے اور گرمی کے سفر سے مانوس کرنے کے باعث'),
  ('ur.ahmedali', 106, 3, 'ان کو اس گھرکے مالک کی عبادت کرنی چاہیئے'),
  ('ur.ahmedali', 106, 4, 'جس نے ان کو بھوک میں کھلایا اور ان کو خوف سے امن دیا')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 106, 1, 'Kureyş kabilesinin yaz ve kış yolculuklarında uzlaşması ve anlaşması sağlanmıştır.'),
  ('tr.diyanet', 106, 2, 'Kureyş kabilesinin yaz ve kış yolculuklarında uzlaşması ve anlaşması sağlanmıştır.'),
  ('tr.diyanet', 106, 3, 'Öyleyse kendilerini açken doyuran ve korku içindeyken güven veren bu Ev\'in (Kabe\'nin) Rabbine kulluk etsinler.'),
  ('tr.diyanet', 106, 4, 'Öyleyse kendilerini açken doyuran ve korku içindeyken güven veren bu Ev\'in (Kabe\'nin) Rabbine kulluk etsinler.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 106, 1, 'Karena kebiasaan orang-orang Quraisy,'),
  ('id.indonesian', 106, 2, '(yaitu) kebiasaan mereka bepergian pada musim dingin dan musim panas.'),
  ('id.indonesian', 106, 3, 'Maka hendaklah mereka menyembah Tuhan Pemilik rumah ini (Ka\'bah).'),
  ('id.indonesian', 106, 4, 'Yang telah memberi makanan kepada mereka untuk menghilangkan lapar dan mengamankan mereka dari ketakutan.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (89, 8, 6001, 'ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ', 593, 30, 237, 0),
  (89, 9, 6002, 'وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ', 593, 30, 237, 0),
  (89, 10, 6003, 'وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ', 593, 30, 237, 0),
  (89, 11, 6004, 'ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَٰدِ', 593, 30, 237, 0),
  (89, 12, 6005, 'فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ', 593, 30, 237, 0),
  (89, 13, 6006, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', 593, 30, 237, 0),
  (89, 14, 6007, 'إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ', 593, 30, 237, 0),
  (89, 15, 6008, 'فَأَمَّا ٱلْإِنسَٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ', 593, 30, 237, 0),
  (89, 16, 6009, 'وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَٰنَنِ', 593, 30, 237, 0),
  (89, 17, 6010, 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', 593, 30, 237, 0),
  (89, 18, 6011, 'وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 593, 30, 237, 0),
  (89, 19, 6012, 'وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًۭا لَّمًّۭا', 593, 30, 237, 0),
  (89, 20, 6013, 'وَتُحِبُّونَ ٱلْمَالَ حُبًّۭا جَمًّۭا', 593, 30, 237, 0),
  (89, 21, 6014, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّۭا دَكًّۭا', 593, 30, 237, 0),
  (89, 22, 6015, 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّۭا صَفًّۭا', 593, 30, 237, 0),
  (89, 23, 6016, 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍۢ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', 593, 30, 237, 0),
  (89, 24, 6017, 'يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', 594, 30, 237, 0),
  (89, 25, 6018, 'فَيَوْمَئِذٍۢ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌۭ', 594, 30, 237, 0),
  (89, 26, 6019, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌۭ', 594, 30, 237, 0),
  (89, 27, 6020, 'يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', 594, 30, 237, 0),
  (89, 28, 6021, 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةًۭ مَّرْضِيَّةًۭ', 594, 30, 237, 0),
  (89, 29, 6022, 'فَٱدْخُلِى فِى عِبَٰدِى', 594, 30, 237, 0),
  (89, 30, 6023, 'وَٱدْخُلِى جَنَّتِى', 594, 30, 237, 0),
  (90, 1, 6024, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ', 594, 30, 238, 0),
