  (98, 6, 6136, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ ۚ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', 598, 30, 239, 0),
  (98, 7, 6137, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', 598, 30, 239, 0),
  (98, 8, 6138, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', 599, 30, 239, 0),
  (99, 1, 6139, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', 599, 30, 239, 0),
  (99, 2, 6140, 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', 599, 30, 239, 0),
  (99, 3, 6141, 'وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا', 599, 30, 239, 0),
  (99, 4, 6142, 'يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا', 599, 30, 239, 0),
  (99, 5, 6143, 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 599, 30, 239, 0),
  (99, 6, 6144, 'يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَٰلَهُمْ', 599, 30, 239, 0),
  (99, 7, 6145, 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ', 599, 30, 239, 0),
  (99, 8, 6146, 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ', 599, 30, 239, 0),
  (100, 1, 6147, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلْعَٰدِيَٰتِ ضَبْحًۭا', 599, 30, 239, 0),
  (100, 2, 6148, 'فَٱلْمُورِيَٰتِ قَدْحًۭا', 599, 30, 239, 0),
  (100, 3, 6149, 'فَٱلْمُغِيرَٰتِ صُبْحًۭا', 599, 30, 239, 0),
  (100, 4, 6150, 'فَأَثَرْنَ بِهِۦ نَقْعًۭا', 599, 30, 239, 0),
  (100, 5, 6151, 'فَوَسَطْنَ بِهِۦ جَمْعًا', 599, 30, 239, 0),
  (100, 6, 6152, 'إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌۭ', 599, 30, 239, 0),
  (100, 7, 6153, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ', 599, 30, 239, 0),
  (100, 8, 6154, 'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ', 599, 30, 239, 0),
  (100, 9, 6155, '۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ', 599, 30, 240, 0),
  (100, 10, 6156, 'وَحُصِّلَ مَا فِى ٱلصُّدُورِ', 600, 30, 240, 0),
  (100, 11, 6157, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ', 600, 30, 240, 0),
  (101, 1, 6158, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ٱلْقَارِعَةُ', 600, 30, 240, 0),
  (101, 2, 6159, 'مَا ٱلْقَارِعَةُ', 600, 30, 240, 0),
  (101, 3, 6160, 'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ', 600, 30, 240, 0),
  (101, 4, 6161, 'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ', 600, 30, 240, 0),
  (101, 5, 6162, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', 600, 30, 240, 0),
  (101, 6, 6163, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 600, 30, 240, 0),
  (101, 7, 6164, 'فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ', 600, 30, 240, 0),
  (101, 8, 6165, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 600, 30, 240, 0),
  (101, 9, 6166, 'فَأُمُّهُۥ هَاوِيَةٌۭ', 600, 30, 240, 0),
  (101, 10, 6167, 'وَمَآ أَدْرَىٰكَ مَا هِيَهْ', 600, 30, 240, 0),
  (101, 11, 6168, 'نَارٌ حَامِيَةٌۢ', 600, 30, 240, 0),
  (102, 1, 6169, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَلْهَىٰكُمُ ٱلتَّكَاثُرُ', 600, 30, 240, 0),
  (102, 2, 6170, 'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ', 600, 30, 240, 0),
  (102, 3, 6171, 'كَلَّا سَوْفَ تَعْلَمُونَ', 600, 30, 240, 0),
  (102, 4, 6172, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ', 600, 30, 240, 0),
  (102, 5, 6173, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ', 600, 30, 240, 0),
  (102, 6, 6174, 'لَتَرَوُنَّ ٱلْجَحِيمَ', 600, 30, 240, 0),
  (102, 7, 6175, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ', 600, 30, 240, 0),
  (102, 8, 6176, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', 600, 30, 240, 0),
  (103, 1, 6177, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلْعَصْرِ', 601, 30, 240, 0),
  (103, 2, 6178, 'إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ', 601, 30, 240, 0),
  (103, 3, 6179, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ', 601, 30, 240, 0),
  (104, 1, 6180, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ', 601, 30, 240, 0),
  (104, 2, 6181, 'ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ', 601, 30, 240, 0),
  (104, 3, 6182, 'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', 601, 30, 240, 0),
  (104, 4, 6183, 'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ', 601, 30, 240, 0),
  (104, 5, 6184, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ', 601, 30, 240, 0),
  (104, 6, 6185, 'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ', 601, 30, 240, 0),
  (104, 7, 6186, 'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ', 601, 30, 240, 0),
  (104, 8, 6187, 'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ', 601, 30, 240, 0),
  (104, 9, 6188, 'فِى عَمَدٍۢ مُّمَدَّدَةٍۭ', 601, 30, 240, 0),
  (105, 1, 6189, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ', 601, 30, 240, 0),
  (105, 2, 6190, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ', 601, 30, 240, 0),
  (105, 3, 6191, 'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ', 601, 30, 240, 0),
  (105, 4, 6192, 'تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ', 601, 30, 240, 0),
  (105, 5, 6193, 'فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ', 601, 30, 240, 0),
  (106, 1, 6194, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ لِإِيلَٰفِ قُرَيْشٍ', 602, 30, 240, 0),
  (106, 2, 6195, 'إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ', 602, 30, 240, 0),
  (106, 3, 6196, 'فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ', 602, 30, 240, 0),
  (106, 4, 6197, 'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ', 602, 30, 240, 0),
  (107, 1, 6198, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ', 602, 30, 240, 0),
  (107, 2, 6199, 'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ', 602, 30, 240, 0),
  (107, 3, 6200, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 602, 30, 240, 0)
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 107, 1, 'Have you seen the one who denies the Recompense?'),
  ('en.sahih', 107, 2, 'For that is the one who drives away the orphan'),
  ('en.sahih', 107, 3, 'And does not encourage the feeding of the poor.'),
  ('en.sahih', 107, 4, 'So woe to those who pray'),
  ('en.sahih', 107, 5, '[But] who are heedless of their prayer -'),
  ('en.sahih', 107, 6, 'Those who make show [of their deeds]'),
  ('en.sahih', 107, 7, 'And withhold [simple] assistance.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 107, 1, 'আপনি কি দেখেছেন তাকে, যে বিচারদিবসকে মিথ্যা বলে?'),
  ('bn.bengali', 107, 2, 'সে সেই ব্যক্তি, যে এতীমকে গলা ধাক্কা দেয়'),
  ('bn.bengali', 107, 3, 'এবং মিসকীনকে অন্ন দিতে উৎসাহিত করে না।'),
  ('bn.bengali', 107, 4, 'অতএব দুর্ভোগ সেসব নামাযীর,'),
  ('bn.bengali', 107, 5, 'যারা তাদের নামায সম্বন্ধে বে-খবর;'),
  ('bn.bengali', 107, 6, 'যারা তা লোক-দেখানোর জন্য করে'),
  ('bn.bengali', 107, 7, 'এবং নিত্য ব্যবহার্য্য বস্তু অন্যকে দেয় না।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 107, 1, 'Hast thou observed him who belieth religion?'),
  ('en.pickthall', 107, 2, 'That is he who repelleth the orphan,'),
  ('en.pickthall', 107, 3, 'And urgeth not the feeding of the needy.'),
  ('en.pickthall', 107, 4, 'Ah, woe unto worshippers'),
  ('en.pickthall', 107, 5, 'Who are heedless of their prayer;'),
  ('en.pickthall', 107, 6, 'Who would be seen (at worship)'),
  ('en.pickthall', 107, 7, 'Yet refuse small kindnesses!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 107, 1, 'Seest thou one who denies the Judgment (to come)?'),
  ('en.yusufali', 107, 2, 'Then such is the (man) who repulses the orphan (with harshness),'),
  ('en.yusufali', 107, 3, 'And encourages not the feeding of the indigent.'),
  ('en.yusufali', 107, 4, 'So woe to the worshippers'),
  ('en.yusufali', 107, 5, 'Who are neglectful of their prayers,'),
  ('en.yusufali', 107, 6, 'Those who (want but) to be seen (of men),'),
  ('en.yusufali', 107, 7, 'But refuse (to supply) (even) neighbourly needs.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 107, 1, 'Ara-aital lazee yu kazzibu bid deen'),
  ('en.transliteration', 107, 2, 'Fa zaalikal lazi yadu\'ul-yateem'),
  ('en.transliteration', 107, 3, 'Wa la ya huddu \'alaa ta\'amil miskeen'),
  ('en.transliteration', 107, 4, 'Fa wai lul-lil mu salleen'),
  ('en.transliteration', 107, 5, 'Al lazeena hum \'an salaatihim sahoon'),
  ('en.transliteration', 107, 6, 'Al lazeena hum yuraa-oon'),
  ('en.transliteration', 107, 7, 'Wa yamna\'oonal ma\'oon')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 107, 1, 'کیا آپ نے اس کو دیکھا جو روزِ جرا کو جھٹلاتا ہے'),
  ('ur.ahmedali', 107, 2, 'پس وہ وہی ہے جو یتیم کو دھکے دیتا ہے'),
  ('ur.ahmedali', 107, 3, 'اور مسکین کو کھانا کھلانے کی ترغیب نہیں دیتا'),
  ('ur.ahmedali', 107, 4, 'پس ان نمازیوں کے لیے ہلاکت ہے'),
  ('ur.ahmedali', 107, 5, 'جو اپنی نماز سے غافل ہیں'),
  ('ur.ahmedali', 107, 6, 'جو دکھلاوا کرتے ہیں'),
  ('ur.ahmedali', 107, 7, 'اور برتنے کی چیز تک روکتے ہیں')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 107, 1, 'Dini yalan sayanı gördün mü?'),
  ('tr.diyanet', 107, 2, 'Öksüzü kakıştıran, yoksulu doyurmaya yanaşmayan kimse işte odur.'),
  ('tr.diyanet', 107, 3, 'Öksüzü kakıştıran, yoksulu doyurmaya yanaşmayan kimse işte odur.'),
  ('tr.diyanet', 107, 4, 'Vay o namaz kılanların haline ki:'),
  ('tr.diyanet', 107, 5, 'Onlar kıldıkları namazdan gafildirler.'),
  ('tr.diyanet', 107, 6, 'Onlar gösteriş yaparlar.'),
  ('tr.diyanet', 107, 7, 'Onlar basit şeyleri dahi vermezler.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 107, 1, 'Tahukah kamu (orang) yang mendustakan agama?'),
  ('id.indonesian', 107, 2, 'Itulah orang yang menghardik anak yatim,'),
  ('id.indonesian', 107, 3, 'dan tidak menganjurkan memberi makan orang miskin.'),
  ('id.indonesian', 107, 4, 'Maka kecelakaanlah bagi orang-orang yang shalat,'),
  ('id.indonesian', 107, 5, '(yaitu) orang-orang yang lalai dari shalatnya,'),
  ('id.indonesian', 107, 6, 'orang-orang yang berbuat riya,'),
  ('id.indonesian', 107, 7, 'dan enggan (menolong dengan) barang berguna.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 108, 1, 'Indeed, We have granted you, [O Muhammad], al-Kawthar.'),
  ('en.sahih', 108, 2, 'So pray to your Lord and sacrifice [to Him alone].'),
  ('en.sahih', 108, 3, 'Indeed, your enemy is the one cut off.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 108, 1, 'নিশ্চয় আমি আপনাকে কাওসার দান করেছি।'),
  ('bn.bengali', 108, 2, 'অতএব আপনার পালনকর্তার উদ্দেশ্যে নামায পড়ুন এবং কোরবানী করুন।'),
  ('bn.bengali', 108, 3, 'যে আপনার শত্রু, সেই তো লেজকাটা, নির্বংশ।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 108, 1, 'Lo! We have given thee Abundance;'),
  ('en.pickthall', 108, 2, 'So pray unto thy Lord, and sacrifice.'),
  ('en.pickthall', 108, 3, 'Lo! it is thy insulter (and not thou) who is without posterity.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 108, 1, 'To thee have We granted the Fount (of Abundance).'),
  ('en.yusufali', 108, 2, 'Therefore to thy Lord turn in Prayer and Sacrifice.'),
  ('en.yusufali', 108, 3, 'For he who hateth thee, he will be cut off (from Future Hope).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 108, 1, 'Innaa a\'taina kal kauthar'),
  ('en.transliteration', 108, 2, 'Fa salli li rabbika wanhar'),
  ('en.transliteration', 108, 3, 'Inna shani-aka huwal abtar')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 108, 1, 'بے شک ہم نے آپ کو کوثر دی'),
  ('ur.ahmedali', 108, 2, 'پس اپنے رب کے لیے نماز پڑھیئے اور قربانی کیجیئے'),
  ('ur.ahmedali', 108, 3, 'بے شک آپ کا دشمن ہی بے نام و نشان ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 108, 1, 'Doğrusu sana pek çok nimet vermişizdir.'),
  ('tr.diyanet', 108, 2, 'Öyleyse Rabbin için namaz kıl, kurban kes.'),
  ('tr.diyanet', 108, 3, 'Doğrusu adı sanı ortadan kalkacak olan, sana kin tutan kimsedir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 108, 1, 'Sesungguhnya Kami telah memberikan kepadamu nikmat yang banyak.'),
  ('id.indonesian', 108, 2, 'Maka dirikanlah shalat karena Tuhanmu; dan berkorbanlah.'),
  ('id.indonesian', 108, 3, 'Sesungguhnya orang-orang yang membenci kamu dialah yang terputus.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 109, 1, 'Say, "O disbelievers,'),
  ('en.sahih', 109, 2, 'I do not worship what you worship.'),
  ('en.sahih', 109, 3, 'Nor are you worshippers of what I worship.'),
  ('en.sahih', 109, 4, 'Nor will I be a worshipper of what you worship.'),
  ('en.sahih', 109, 5, 'Nor will you be worshippers of what I worship.'),
  ('en.sahih', 109, 6, 'For you is your religion, and for me is my religion."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 109, 1, 'বলুন, হে কাফেরকূল,'),
  ('bn.bengali', 109, 2, 'আমি এবাদত করিনা, তোমরা যার এবাদত কর।'),
  ('bn.bengali', 109, 3, 'এবং তোমরাও এবাদতকারী নও, যার এবাদত আমি করি'),
  ('bn.bengali', 109, 4, 'এবং আমি এবাদতকারী নই, যার এবাদত তোমরা কর।'),
  ('bn.bengali', 109, 5, 'তোমরা এবাদতকারী নও, যার এবাদত আমি করি।'),
  ('bn.bengali', 109, 6, 'তোমাদের কর্ম ও কর্মফল তোমাদের জন্যে এবং আমার কর্ম ও কর্মফল আমার জন্যে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 109, 1, 'Say: O disbelievers!'),
  ('en.pickthall', 109, 2, 'I worship not that which ye worship;'),
  ('en.pickthall', 109, 3, 'Nor worship ye that which I worship.'),
  ('en.pickthall', 109, 4, 'And I shall not worship that which ye worship.'),
  ('en.pickthall', 109, 5, 'Nor will ye worship that which I worship.'),
  ('en.pickthall', 109, 6, 'Unto you your religion, and unto me my religion.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 109, 1, 'Say: O ye that reject Faith!'),
  ('en.yusufali', 109, 2, 'I worship not that which ye worship,'),
  ('en.yusufali', 109, 3, 'Nor will ye worship that which I worship.'),
  ('en.yusufali', 109, 4, 'And I will not worship that which ye have been wont to worship,'),
  ('en.yusufali', 109, 5, 'Nor will ye worship that which I worship.'),
  ('en.yusufali', 109, 6, 'To you be your Way, and to me mine.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 109, 1, 'Qul yaa-ai yuhal kaafiroon'),
  ('en.transliteration', 109, 2, 'Laa a\'budu ma t\'abudoon'),
  ('en.transliteration', 109, 3, 'Wa laa antum \'aabidoona maa a\'bud'),
  ('en.transliteration', 109, 4, 'Wa laa ana \'abidum maa \'abattum'),
  ('en.transliteration', 109, 5, 'Wa laa antum \'aabidoona ma a\'bud'),
  ('en.transliteration', 109, 6, 'Lakum deenukum wa liya deen.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 109, 1, 'کہہ دو اے کافرو'),
  ('ur.ahmedali', 109, 2, 'نہ تومیں تمہارے معبودوں کی عبادت کرتا ہوں'),
  ('ur.ahmedali', 109, 3, 'اور نہ تم ہی میرے معبود کی عبادت کرتے ہو'),
  ('ur.ahmedali', 109, 4, 'اور نہ میں تمہارے معبودوں کی عبادت کروں گا'),
  ('ur.ahmedali', 109, 5, 'اور نہ تم میرے معبود کی عبادت کرو گے'),
  ('ur.ahmedali', 109, 6, 'تمہارے لیے تمہارا دین ہے اور میرے لیے میرا دین')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 109, 1, 'De ki: "Ey inkarcılar!"'),
  ('tr.diyanet', 109, 2, '"Ben sizin taptıklarınıza tapmam."'),
  ('tr.diyanet', 109, 3, '"Benim taptığıma da sizler tapmazsınız."'),
  ('tr.diyanet', 109, 4, '"Ben de sizin taptığınıza tapacak değilim."'),
  ('tr.diyanet', 109, 5, '"Benim taptığıma da sizler tapmıyorsunuz."'),
  ('tr.diyanet', 109, 6, '"Sizin dininiz size, benim dinim banadır."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 109, 1, 'Katakanlah: "Hai orang-orang kafir,'),
  ('id.indonesian', 109, 2, 'Aku tidak akan menyembah apa yang kamu sembah.'),
  ('id.indonesian', 109, 3, 'Dan kamu bukan penyembah Tuhan yang aku sembah.'),
  ('id.indonesian', 109, 4, 'Dan aku tidak pernah menjadi penyembah apa yang kamu sembah,'),
  ('id.indonesian', 109, 5, 'dan kamu tidak pernah (pula) menjadi penyembah Tuhan yang aku sembah.'),
  ('id.indonesian', 109, 6, 'Untukmu agamamu, dan untukkulah, agamaku".')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 110, 1, 'When the victory of Allah has come and the conquest,'),
  ('en.sahih', 110, 2, 'And you see the people entering into the religion of Allah in multitudes,'),
  ('en.sahih', 110, 3, 'Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 110, 1, 'যখন আসবে আল্লাহর সাহায্য ও বিজয়'),
  ('bn.bengali', 110, 2, 'এবং আপনি মানুষকে দলে দলে আল্লাহর দ্বীনে প্রবেশ করতে দেখবেন,'),
  ('bn.bengali', 110, 3, 'তখন আপনি আপনার পালনকর্তার পবিত্রতা বর্ণনা করুন এবং তাঁর কাছে ক্ষমা প্রার্থনা করুন। নিশ্চয় তিনি ক্ষমাকারী।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 110, 1, 'When Allah\'s succour and the triumph cometh'),
  ('en.pickthall', 110, 2, 'And thou seest mankind entering the religion of Allah in troops,'),
  ('en.pickthall', 110, 3, 'Then hymn the praises of thy Lord, and seek forgiveness of Him. Lo! He is ever ready to show mercy.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 110, 1, 'When comes the Help of Allah, and Victory,'),
  ('en.yusufali', 110, 2, 'And thou dost see the people enter Allah\'s Religion in crowds,'),
  ('en.yusufali', 110, 3, 'Celebrate the praises of thy Lord, and pray for His Forgiveness: For He is Oft-Returning (in Grace and Mercy).')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 110, 1, 'Iza jaa-a nas rullahi walfath'),
  ('en.transliteration', 110, 2, 'Wa ra-aitan naasa yadkhuloona fee deenil laahi afwajah'),
  ('en.transliteration', 110, 3, 'Fa sab bih bihamdi rabbika was taghfir, innahu kaana tawwaaba')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 110, 1, 'جب الله کی مدد اور فتح آ چکی'),
  ('ur.ahmedali', 110, 2, 'اورآپ نے لوگوں کو الله کے دین میں جوق در جوق داخل ہوتے دیکھ لیا'),
  ('ur.ahmedali', 110, 3, 'تو اپنے رب کی حمد کے ساتھ تسبیح کیجیئے اور اس سے معافی مانگیئے بےشک وہ بڑا توبہ قبول کرنے والا ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 110, 1, 'Allah\'ın yardımı ve zafer günü gelip, insanların Allah\'ın dinine akın akın girdiklerini görünce, Rabbini överek tesbih et; O\'ndan bağışlama dile, çünkü O, tevbeleri daima kabul edendir.'),
  ('tr.diyanet', 110, 2, 'Allah\'ın yardımı ve zafer günü gelip, insanların Allah\'ın dinine akın akın girdiklerini görünce, Rabbini överek tesbih et; O\'ndan bağışlama dile, çünkü O, tevbeleri daima kabul edendir.'),
  ('tr.diyanet', 110, 3, 'Allah\'ın yardımı ve zafer günü gelip, insanların Allah\'ın dinine akın akın girdiklerini görünce, Rabbini överek tesbih et; O\'ndan bağışlama dile, çünkü O, tevbeleri daima kabul edendir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 110, 1, 'Apabila telah datang pertolongan Allah dan kemenangan,'),
  ('id.indonesian', 110, 2, 'dan kamu lihat manusia masuk agama Allah dengan berbondong-bondong,'),
  ('id.indonesian', 110, 3, 'maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampun kepada-Nya. Sesungguhnya Dia adalah Maha Penerima taubat.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 111, 1, 'May the hands of Abu Lahab be ruined, and ruined is he.'),
  ('en.sahih', 111, 2, 'His wealth will not avail him or that which he gained.'),
  ('en.sahih', 111, 3, 'He will [enter to] burn in a Fire of [blazing] flame'),
  ('en.sahih', 111, 4, 'And his wife [as well] - the carrier of firewood.'),
  ('en.sahih', 111, 5, 'Around her neck is a rope of [twisted] fiber.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 111, 1, 'আবু লাহাবের হস্তদ্বয় ধ্বংস হোক এবং ধ্বংস হোক সে নিজে,'),
  ('bn.bengali', 111, 2, 'কোন কাজে আসেনি তার ধন-সম্পদ ও যা সে উপার্জন করেছে।'),
  ('bn.bengali', 111, 3, 'সত্বরই সে প্রবেশ করবে লেলিহান অগ্নিতে'),
  ('bn.bengali', 111, 4, 'এবং তার স্ত্রীও-যে ইন্ধন বহন করে,'),
  ('bn.bengali', 111, 5, 'তার গলদেশে খর্জুরের রশি নিয়ে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 111, 1, 'The power of Abu Lahab will perish, and he will perish.'),
  ('en.pickthall', 111, 2, 'His wealth and gains will not exempt him.'),
  ('en.pickthall', 111, 3, 'He will be plunged in flaming Fire,'),
  ('en.pickthall', 111, 4, 'And his wife, the wood-carrier,'),
  ('en.pickthall', 111, 5, 'Will have upon her neck a halter of palm-fibre.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 111, 1, 'Perish the hands of the Father of Flame! Perish he!'),
  ('en.yusufali', 111, 2, 'No profit to him from all his wealth, and all his gains!'),
  ('en.yusufali', 111, 3, 'Burnt soon will he be in a Fire of Blazing Flame!'),
  ('en.yusufali', 111, 4, 'His wife shall carry the (crackling) wood - As fuel!-'),
  ('en.yusufali', 111, 5, 'A twisted rope of palm-leaf fibre round her (own) neck!')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 111, 1, 'Tab bat yadaa abee Lahabinw-wa tabb'),
  ('en.transliteration', 111, 2, 'Maa aghna \'anhu maaluhu wa ma kasab'),
  ('en.transliteration', 111, 3, 'Sa yas laa naran zaata lahab'),
  ('en.transliteration', 111, 4, 'Wam ra-atuh hamma latal-hatab'),
  ('en.transliteration', 111, 5, 'Fee jeediha hab lum mim-masad')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 111, 1, 'ابو لہب کے دونوں ہاتھ ٹوٹ گئے اوروہ ہلاک ہو گیا'),
  ('ur.ahmedali', 111, 2, 'اس کا مال اورجو کچھ اس نے کمایا اس کے کام نہ آیا'),
  ('ur.ahmedali', 111, 3, 'وہ بھڑکتی ہوئی آگ میں پڑے گا'),
  ('ur.ahmedali', 111, 4, 'اور اس کی عورت بھی جو ایندھن اٹھائے پھرتی تھی'),
  ('ur.ahmedali', 111, 5, 'اس کی گردن میں موُنج کی رسیّ ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 111, 1, 'Ebu Leheb\'in elleri kurusun; kurudu da!'),
  ('tr.diyanet', 111, 2, 'Malı ve kazandığı kendisine fayda vermedi.'),
  ('tr.diyanet', 111, 3, 'Alevli ateşe yaslanacaktır.'),
  ('tr.diyanet', 111, 4, 'Karısı da, boynunda bir ip olduğu halde ona odun taşıyacaktır.'),
  ('tr.diyanet', 111, 5, 'Karısı da, boynunda bir ip olduğu halde ona odun taşıyacaktır.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 111, 1, 'Binasalah kedua tangan Abu Lahab dan sesungguhnya dia akan binasa.'),
  ('id.indonesian', 111, 2, 'Tidaklah berfaedah kepadanya harta bendanya dan apa yang ia usahakan.'),
  ('id.indonesian', 111, 3, 'Kelak dia akan masuk ke dalam api yang bergejolak.'),
  ('id.indonesian', 111, 4, 'Dan (begitu pula) istrinya, pembawa kayu bakar.'),
  ('id.indonesian', 111, 5, 'Yang di lehernya ada tali dari sabut.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 112, 1, 'Say, "He is Allah, [who is] One,'),
  ('en.sahih', 112, 2, 'Allah, the Eternal Refuge.'),
  ('en.sahih', 112, 3, 'He neither begets nor is born,'),
  ('en.sahih', 112, 4, 'Nor is there to Him any equivalent."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 112, 1, 'বলুন, তিনি আল্লাহ, এক,'),
  ('bn.bengali', 112, 2, 'আল্লাহ অমুখাপেক্ষী,'),
  ('bn.bengali', 112, 3, 'তিনি কাউকে জন্ম দেননি এবং কেউ তাকে জন্ম দেয়নি'),
  ('bn.bengali', 112, 4, 'এবং তার সমতুল্য কেউ নেই।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 112, 1, 'Say: He is Allah, the One!'),
  ('en.pickthall', 112, 2, 'Allah, the eternally Besought of all!'),
  ('en.pickthall', 112, 3, 'He begetteth not nor was begotten.'),
  ('en.pickthall', 112, 4, 'And there is none comparable unto Him.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 112, 1, 'Say: He is Allah, the One and Only;'),
  ('en.yusufali', 112, 2, 'Allah, the Eternal, Absolute;'),
  ('en.yusufali', 112, 3, 'He begetteth not, nor is He begotten;'),
  ('en.yusufali', 112, 4, 'And there is none like unto Him.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 112, 1, 'Qul huwal laahu ahad'),
  ('en.transliteration', 112, 2, 'Allah hus-samad'),
  ('en.transliteration', 112, 3, 'Lam yalid wa lam yoolad'),
  ('en.transliteration', 112, 4, 'Wa lam yakul-lahu kufuwan ahad')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 112, 1, 'کہہ دووہ الله ایک ہے'),
  ('ur.ahmedali', 112, 2, 'اللہ بے نیاز ہے'),
  ('ur.ahmedali', 112, 3, 'نہ اس کی کوئی اولاد ہے اور نہ وہ کسی کی اولاد ہے'),
  ('ur.ahmedali', 112, 4, 'اور اس کے برابر کا کوئی نہیں ہے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 112, 1, 'De ki: O Allah bir tektir.'),
  ('tr.diyanet', 112, 2, 'Allah her şeyden müstağni ve her şey O\'na muhtaçtır.'),
  ('tr.diyanet', 112, 3, 'O doğurmamış ve doğmamıştır.'),
  ('tr.diyanet', 112, 4, 'Hiçbir şey O\'na denk değildir.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 112, 1, 'Katakanlah: "Dialah Allah, Yang Maha Esa.'),
  ('id.indonesian', 112, 2, 'Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu.'),
  ('id.indonesian', 112, 3, 'Dia tiada beranak dan tidak pula diperanakkan,'),
  ('id.indonesian', 112, 4, 'dan tidak ada seorangpun yang setara dengan Dia".')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 113, 1, 'Say, "I seek refuge in the Lord of daybreak'),
  ('en.sahih', 113, 2, 'From the evil of that which He created'),
  ('en.sahih', 113, 3, 'And from the evil of darkness when it settles'),
  ('en.sahih', 113, 4, 'And from the evil of the blowers in knots'),
  ('en.sahih', 113, 5, 'And from the evil of an envier when he envies."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 113, 1, 'বলুন, আমি আশ্রয় গ্রহণ করছি প্রভাতের পালনকর্তার,'),
  ('bn.bengali', 113, 2, 'তিনি যা সৃষ্টি করেছেন, তার অনিষ্ট থেকে,'),
  ('bn.bengali', 113, 3, 'অন্ধকার রাত্রির অনিষ্ট থেকে, যখন তা সমাগত হয়,'),
  ('bn.bengali', 113, 4, 'গ্রন্থিতে ফুঁৎকার দিয়ে জাদুকারিনীদের অনিষ্ট থেকে'),
  ('bn.bengali', 113, 5, 'এবং হিংসুকের অনিষ্ট থেকে যখন সে হিংসা করে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 113, 1, 'Say: I seek refuge in the Lord of the Daybreak'),
  ('en.pickthall', 113, 2, 'From the evil of that which He created;'),
  ('en.pickthall', 113, 3, 'From the evil of the darkness when it is intense,'),
  ('en.pickthall', 113, 4, 'And from the evil of malignant witchcraft,'),
  ('en.pickthall', 113, 5, 'And from the evil of the envier when he envieth.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 113, 1, 'Say: I seek refuge with the Lord of the Dawn'),
  ('en.yusufali', 113, 2, 'From the mischief of created things;'),
  ('en.yusufali', 113, 3, 'From the mischief of Darkness as it overspreads;'),
  ('en.yusufali', 113, 4, 'From the mischief of those who practise secret arts;'),
  ('en.yusufali', 113, 5, 'And from the mischief of the envious one as he practises envy.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 113, 1, 'Qul a\'uzoo bi rabbil-falaq'),
  ('en.transliteration', 113, 2, 'Min sharri ma khalaq'),
  ('en.transliteration', 113, 3, 'Wa min sharri ghasiqin iza waqab'),
  ('en.transliteration', 113, 4, 'Wa min sharrin-naffaa-thaati fil \'uqad'),
  ('en.transliteration', 113, 5, 'Wa min shar ri haasidin iza hasad')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 113, 1, 'کہہ دو صبح کے پیدا کرنے والے کی پناہ مانگتا ہوں'),
  ('ur.ahmedali', 113, 2, 'اس کی مخلوقات کے شر سے'),
  ('ur.ahmedali', 113, 3, 'اور اندھیری رات کے شر سے جب وہ چھا جائے'),
  ('ur.ahmedali', 113, 4, 'اورگرہوں میں پھونکنے والیوں کے شر سے'),
  ('ur.ahmedali', 113, 5, 'اور حسد کرنے والے کے شر سے جب وہ حسد کرے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 113, 1, 'De ki: "Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım."'),
  ('tr.diyanet', 113, 2, 'De ki: "Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım."'),
  ('tr.diyanet', 113, 3, 'De ki: "Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım."'),
  ('tr.diyanet', 113, 4, 'De ki: "Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım."'),
  ('tr.diyanet', 113, 5, 'De ki: "Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 113, 1, 'Katakanlah: "Aku berlindung kepada Tuhan Yang Menguasai subuh,'),
  ('id.indonesian', 113, 2, 'dari kejahatan makhluk-Nya,'),
  ('id.indonesian', 113, 3, 'dan dari kejahatan malam apabila telah gelap gulita,'),
  ('id.indonesian', 113, 4, 'dan dari kejahatan wanita-wanita tukang sihir yang menghembus pada buhul-buhul,'),
  ('id.indonesian', 113, 5, 'dan dari kejahatan pendengki bila ia dengki".')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.sahih', 114, 1, 'Say, "I seek refuge in the Lord of mankind,'),
  ('en.sahih', 114, 2, 'The Sovereign of mankind.'),
  ('en.sahih', 114, 3, 'The God of mankind,'),
  ('en.sahih', 114, 4, 'From the evil of the retreating whisperer -'),
  ('en.sahih', 114, 5, 'Who whispers [evil] into the breasts of mankind -'),
  ('en.sahih', 114, 6, 'From among the jinn and mankind."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('bn.bengali', 114, 1, 'বলুন, আমি আশ্রয় গ্রহণ করিতেছি মানুষের পালনকর্তার,'),
  ('bn.bengali', 114, 2, 'মানুষের অধিপতির,'),
  ('bn.bengali', 114, 3, 'মানুষের মা’বুদের'),
  ('bn.bengali', 114, 4, 'তার অনিষ্ট থেকে, যে কুমন্ত্রণা দেয় ও আত্নগোপন করে,'),
  ('bn.bengali', 114, 5, 'যে কুমন্ত্রণা দেয় মানুষের অন্তরে'),
  ('bn.bengali', 114, 6, 'জ্বিনের মধ্য থেকে অথবা মানুষের মধ্য থেকে।')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.pickthall', 114, 1, 'Say: I seek refuge in the Lord of mankind,'),
  ('en.pickthall', 114, 2, 'The King of mankind,'),
  ('en.pickthall', 114, 3, 'The god of mankind,'),
  ('en.pickthall', 114, 4, 'From the evil of the sneaking whisperer,'),
  ('en.pickthall', 114, 5, 'Who whispereth in the hearts of mankind,'),
  ('en.pickthall', 114, 6, 'Of the jinn and of mankind.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.yusufali', 114, 1, 'Say: I seek refuge with the Lord and Cherisher of Mankind,'),
  ('en.yusufali', 114, 2, 'The King (or Ruler) of Mankind,'),
  ('en.yusufali', 114, 3, 'The god (or judge) of Mankind,-'),
  ('en.yusufali', 114, 4, 'From the mischief of the Whisperer (of Evil), who withdraws (after his whisper),-'),
  ('en.yusufali', 114, 5, '(The same) who whispers into the hearts of Mankind,-'),
  ('en.yusufali', 114, 6, 'Among Jinns and among men.')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('en.transliteration', 114, 1, 'Qul a\'uzu birabbin naas'),
  ('en.transliteration', 114, 2, 'Malikin naas'),
  ('en.transliteration', 114, 3, 'Ilaahin naas'),
  ('en.transliteration', 114, 4, 'Min sharril was waasil khannaas'),
  ('en.transliteration', 114, 5, 'Al lazee yuwas wisu fee sudoorin naas'),
  ('en.transliteration', 114, 6, 'Minal jinnati wan naas')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('ur.ahmedali', 114, 1, 'کہہ دو میں لوگوں کے رب کی پناہ میں آیا'),
  ('ur.ahmedali', 114, 2, 'لوگوں کے بادشاہ کی'),
  ('ur.ahmedali', 114, 3, 'لوگوں کے معبود کی'),
  ('ur.ahmedali', 114, 4, 'اس شیطان کے شر سے جووسوسہ ڈال کر چھپ جاتا ہے'),
  ('ur.ahmedali', 114, 5, 'جو لوگوں کے سینوں میں وسوسہ ڈالتا ہے'),
  ('ur.ahmedali', 114, 6, 'جنوں اور انسانوں میں سے')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('tr.diyanet', 114, 1, 'De ki: "İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah\'a sığınırım."'),
  ('tr.diyanet', 114, 2, 'De ki: "İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah\'a sığınırım."'),
  ('tr.diyanet', 114, 3, 'De ki: "İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah\'a sığınırım."'),
  ('tr.diyanet', 114, 4, 'De ki: "İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah\'a sığınırım."'),
  ('tr.diyanet', 114, 5, 'De ki: "İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah\'a sığınırım."'),
  ('tr.diyanet', 114, 6, 'De ki: "İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah\'a sığınırım."')
INSERT INTO quran_translations (edition, surah_number, ayah_number, text) VALUES
  ('id.indonesian', 114, 1, 'Katakanlah: "Aku berlindung kepada Tuhan (yang memelihara dan menguasai) manusia.'),
  ('id.indonesian', 114, 2, 'Raja manusia.'),
  ('id.indonesian', 114, 3, 'Sembahan manusia.'),
  ('id.indonesian', 114, 4, 'Dari kejahatan (bisikan) syaitan yang biasa bersembunyi,'),
  ('id.indonesian', 114, 5, 'yang membisikkan (kejahatan) ke dalam dada manusia,'),
  ('id.indonesian', 114, 6, 'dari (golongan) jin dan manusia.')
INSERT INTO quran_ayahs
  (surah_number, ayah_number, number_global, text_ar, page, juz, hizb, sajdah)
VALUES
  (107, 4, 6201, 'فَوَيْلٌۭ لِّلْمُصَلِّينَ', 602, 30, 240, 0),
  (107, 5, 6202, 'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 602, 30, 240, 0),
  (107, 6, 6203, 'ٱلَّذِينَ هُمْ يُرَآءُونَ', 602, 30, 240, 0),
  (107, 7, 6204, 'وَيَمْنَعُونَ ٱلْمَاعُونَ', 602, 30, 240, 0),
  (108, 1, 6205, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ', 602, 30, 240, 0),
  (108, 2, 6206, 'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ', 602, 30, 240, 0),
  (108, 3, 6207, 'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ', 602, 30, 240, 0),
  (109, 1, 6208, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ', 603, 30, 240, 0),
  (109, 2, 6209, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 603, 30, 240, 0),
  (109, 3, 6210, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ', 603, 30, 240, 0),
  (109, 4, 6211, 'وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ', 603, 30, 240, 0),
  (109, 5, 6212, 'وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ', 603, 30, 240, 0),
  (109, 6, 6213, 'لَكُمْ دِينُكُمْ وَلِىَ دِينِ', 603, 30, 240, 0),
  (110, 1, 6214, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ', 603, 30, 240, 0),
  (110, 2, 6215, 'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا', 603, 30, 240, 0),
  (110, 3, 6216, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا', 603, 30, 240, 0),
  (111, 1, 6217, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ', 603, 30, 240, 0),
  (111, 2, 6218, 'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ', 603, 30, 240, 0),
  (111, 3, 6219, 'سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ', 603, 30, 240, 0),
  (111, 4, 6220, 'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ', 603, 30, 240, 0),
  (111, 5, 6221, 'فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ', 603, 30, 240, 0),
  (112, 1, 6222, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ هُوَ ٱللَّهُ أَحَدٌ', 604, 30, 240, 0),
  (112, 2, 6223, 'ٱللَّهُ ٱلصَّمَدُ', 604, 30, 240, 0),
  (112, 3, 6224, 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 604, 30, 240, 0),
  (112, 4, 6225, 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', 604, 30, 240, 0),
  (113, 1, 6226, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 604, 30, 240, 0),
  (113, 2, 6227, 'مِن شَرِّ مَا خَلَقَ', 604, 30, 240, 0),
  (113, 3, 6228, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 604, 30, 240, 0),
  (113, 4, 6229, 'وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ', 604, 30, 240, 0),
  (113, 5, 6230, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 604, 30, 240, 0),
  (114, 1, 6231, 'بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 604, 30, 240, 0),
  (114, 2, 6232, 'مَلِكِ ٱلنَّاسِ', 604, 30, 240, 0),
  (114, 3, 6233, 'إِلَٰهِ ٱلنَّاسِ', 604, 30, 240, 0),
  (114, 4, 6234, 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', 604, 30, 240, 0),
  (114, 5, 6235, 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', 604, 30, 240, 0),
  (114, 6, 6236, 'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', 604, 30, 240, 0)
